window.PV_BANK=[{"id":"licensing-001","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age for a regular Class E license.","h2":"You can get a Florida learner license when you are 15 years old, one year before you can get a Class E license at 16.","p":"Right. The learner license starts at age 15."},"es":{"q":"En Florida, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad para la licencia Clase E normal.","h2":"Usted puede obtener la licencia de aprendiz en Florida a los 15 años, un año antes de poder obtener la licencia Clase E a los 16.","p":"Correcto. La licencia de aprendiz empieza a los 15 años."},"zh":{"q":"在 Florida，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比普通 Class E 驾照的年龄早一年。","h2":"你 15 岁时可以拿到 Florida 学习驾照，比 16 岁可以拿到的 Class E 驾照早一年。","p":"对。学习驾照从 15 岁开始。"},"vi":{"q":"Ở Florida, tuổi nhỏ nhất để được cấp giấy phép tập lái là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này sớm hơn một năm so với tuổi được cấp bằng lái Class E thông thường.","h2":"Bạn có thể được cấp giấy phép tập lái ở Florida khi bạn 15 tuổi, sớm hơn một năm so với bằng lái Class E lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Florida, ilang taon ang pinakabatang edad para makakuha ng learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang edad para sa karaniwang Class E license.","h2":"Puwede kang kumuha ng Florida learner license kapag 15 taong gulang ka na, isang taon bago ka puwedeng kumuha ng Class E license sa edad na 16.","p":"Tama. Nagsisimula ang learner license sa edad na 15."},"ar":{"q":"في Florida، ما أصغر عمر للحصول على رخصة متعلم؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر يأتي قبل سنة واحدة من عمر الرخصة العادية Class E.","h2":"يمكنك الحصول على رخصة متعلم في Florida عندما يكون عمرك 15 سنة، أي قبل سنة من الحصول على رخصة Class E في عمر 16.","p":"صحيح. رخصة المتعلم تبدأ في عمر 15 سنة."},"ht":{"q":"Nan Florida, ki laj ki pi piti pou w ka jwenn yon lisans aprantisaj?","o":["14 an","15 an","16 an","17 an"],"h1":"Li vini yon ane anvan laj pou yon lisans Class E nòmal.","h2":"Ou ka jwenn yon lisans aprantisaj nan Florida lè ou gen 15 an, yon ane anvan ou ka jwenn yon lisans Class E a 16 an.","p":"Se sa. Lisans aprantisaj la kòmanse a 15 an."},"ref":{"doc":"FL","page":8}},{"id":"licensing-002","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver with a learner license must have someone with them. How old must that person be?","o":["At least 16 years old","At least 18 years old","At least 25 years old","At least 21 years old"],"h1":"The helper must be an experienced adult, older than a new 18-year-old driver.","h2":"A learner must always drive with a licensed driver who is at least 21 years old, because that person needs adult experience to guide them.","p":"Right. The person with you must be a licensed driver age 21 or older."},"es":{"q":"En Florida, quien tiene licencia de aprendiz debe ir acompañado. ¿Qué edad debe tener esa persona?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 25 años","Por lo menos 21 años"],"h1":"El acompañante debe ser un adulto con experiencia, mayor que un conductor nuevo de 18 años.","h2":"El aprendiz siempre debe manejar con un conductor con licencia que tenga por lo menos 21 años, porque esa persona necesita experiencia de adulto para guiarlo.","p":"Correcto. Su acompañante debe tener licencia y 21 años o más."},"zh":{"q":"在 Florida，持学习驾照的司机必须有人陪同。这个人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须是有经验的成年人，比刚满 18 岁的新司机年龄大。","h2":"学习驾驶的人必须一直和一位至少 21 岁、有驾照的司机一起开车，因为这个人需要有成年人的经验来指导。","p":"对。陪你的人必须是 21 岁或以上、有驾照的司机。"},"vi":{"q":"Ở Florida, người có giấy phép tập lái phải có người đi cùng. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi cùng phải là người lớn có kinh nghiệm, lớn tuổi hơn một tài xế mới 18 tuổi.","h2":"Người tập lái luôn phải lái xe cùng một người có bằng lái và ít nhất 21 tuổi, vì người đó cần có kinh nghiệm của người lớn để hướng dẫn.","p":"Đúng. Người đi cùng bạn phải có bằng lái và từ 21 tuổi trở lên."},"tl":{"q":"Sa Florida, ang driver na may learner license ay dapat may kasama. Ilang taon dapat ang kasamang iyon?","o":["Hindi bababa sa 16 taong gulang","Hindi bababa sa 18 taong gulang","Hindi bababa sa 25 taong gulang","Hindi bababa sa 21 taong gulang"],"h1":"Ang kasama ay dapat isang adult na may karanasan, mas matanda pa sa bagong driver na 18 taong gulang.","h2":"Ang learner ay dapat laging magmaneho kasama ang isang lisensyadong driver na hindi bababa sa 21 taong gulang, dahil kailangan ng taong iyon ang karanasan ng adult para gabayan siya.","p":"Tama. Ang kasama mo ay dapat lisensyadong driver na 21 taong gulang o higit pa."},"ar":{"q":"في Florida، يجب أن يكون مع السائق الذي يحمل رخصة متعلم شخص آخر. كم يجب أن يكون عمر هذا الشخص؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا له خبرة، وأكبر من سائق جديد عمره 18 سنة.","h2":"يجب على المتعلم أن يقود دائمًا مع سائق مرخّص عمره 21 سنة على الأقل، لأن هذا الشخص يحتاج إلى خبرة البالغين ليرشده.","p":"صحيح. يجب أن يكون الشخص الذي معك سائقًا مرخّصًا عمره 21 سنة أو أكثر."},"ht":{"q":"Nan Florida, yon chofè ki gen lisans aprantisaj dwe toujou gen yon moun avè l. Ki laj moun sa a dwe genyen?","o":["Omwen 16 an","Omwen 18 an","Omwen 25 an","Omwen 21 an"],"h1":"Moun ki ede w la dwe yon granmoun ki gen eksperyans, ki pi gran pase yon nouvo chofè 18 an.","h2":"Yon apranti dwe toujou kondi ak yon chofè ki gen lisans epi ki gen omwen 21 an, paske moun sa a bezwen eksperyans granmoun pou l gide l.","p":"Se sa. Moun ki avè w la dwe yon chofè ki gen lisans, ki gen 21 an oswa plis."},"ref":{"doc":"FL","page":25}},{"id":"licensing-003","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, where must the licensed adult sit when a learner is driving?","o":["In the front passenger seat","In any back seat","Behind the driver","Anywhere in the car"],"h1":"The adult must be able to see the road and help right away.","h2":"The licensed adult must sit in the front passenger seat, next to the learner, so they can watch the road and help quickly.","p":"Right. The adult sits in the front seat, next to you."},"es":{"q":"En Florida, ¿dónde debe sentarse el adulto con licencia cuando maneja un aprendiz?","o":["En el asiento delantero del pasajero","En cualquier asiento de atrás","Detrás del conductor","En cualquier lugar del carro"],"h1":"El adulto debe poder ver la calle y ayudar enseguida.","h2":"El adulto con licencia debe sentarse en el asiento delantero del pasajero, al lado del aprendiz, para ver la calle y ayudar rápido.","p":"Correcto. El adulto va en el asiento de adelante, a su lado."},"zh":{"q":"在 Florida，学习驾驶的人开车时，有驾照的成年人必须坐在哪里？","o":["前排乘客座位","任何后排座位","司机后面","车里任何地方"],"h1":"这个成年人必须能看到道路，并能马上帮忙。","h2":"有驾照的成年人必须坐在前排乘客座位，在学习驾驶的人旁边，这样才能看着道路并很快帮忙。","p":"对。成年人坐在前排，在你旁边。"},"vi":{"q":"Ở Florida, khi người tập lái đang lái xe, người lớn có bằng lái phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở bất kỳ ghế sau nào","Ngồi sau lưng tài xế","Ở bất kỳ chỗ nào trong xe"],"h1":"Người lớn phải nhìn thấy đường và giúp được ngay lập tức.","h2":"Người lớn có bằng lái phải ngồi ở ghế hành khách phía trước, cạnh người tập lái, để họ quan sát đường và giúp đỡ nhanh chóng.","p":"Đúng. Người lớn ngồi ở ghế trước, cạnh bạn."},"tl":{"q":"Sa Florida, saan dapat umupo ang lisensyadong adult kapag nagmamaneho ang learner?","o":["Sa upuan ng pasahero sa harap","Sa kahit anong upuan sa likod","Sa likod ng driver","Kahit saan sa loob ng kotse"],"h1":"Dapat makita ng adult ang daan at makatulong agad.","h2":"Ang lisensyadong adult ay dapat umupo sa upuan ng pasahero sa harap, katabi ng learner, para mabantayan niya ang daan at makatulong agad.","p":"Tama. Ang adult ay umuupo sa harap, katabi mo."},"ar":{"q":"في Florida، أين يجب أن يجلس البالغ المرخّص عندما يقود المتعلم؟","o":["في المقعد الأمامي بجانب السائق","في أي مقعد خلفي","خلف السائق","في أي مكان في السيارة"],"h1":"يجب أن يستطيع البالغ رؤية الطريق والمساعدة فورًا.","h2":"يجب أن يجلس البالغ المرخّص في المقعد الأمامي بجانب المتعلم، حتى يراقب الطريق ويساعد بسرعة.","p":"صحيح. البالغ يجلس في المقعد الأمامي بجانبك."},"ht":{"q":"Nan Florida, ki kote granmoun ki gen lisans lan dwe chita lè yon apranti ap kondi?","o":["Sou chèz pasaje devan an","Sou nenpòt chèz dèyè","Dèyè chofè a","Nenpòt kote nan machin nan"],"h1":"Granmoun nan dwe ka wè wout la epi ede touswit.","h2":"Granmoun ki gen lisans lan dwe chita sou chèz pasaje devan an, bò kote apranti a, pou l ka gade wout la epi ede vit.","p":"Se sa. Granmoun nan chita devan, bò kote w."},"ref":{"doc":"FL","page":null}},{"id":"licensing-004","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, during the first 3 months with a learner license, when may you drive?","o":["Any time of day or night","Only until midnight","Only during daylight hours","Only on weekends"],"h1":"New learners start with the easiest light conditions.","h2":"For the first 3 months, a learner may drive only during daylight, because seeing well makes it easier to learn safely.","p":"Right. The first 3 months are daylight only."},"es":{"q":"En Florida, durante los primeros 3 meses con licencia de aprendiz, ¿cuándo puede manejar?","o":["A cualquier hora del día o de la noche","Solo hasta la medianoche","Solo durante las horas de luz del día","Solo los fines de semana"],"h1":"Los aprendices nuevos empiezan con la luz más fácil.","h2":"Durante los primeros 3 meses, el aprendiz solo puede manejar de día, porque ver bien hace más fácil aprender con seguridad.","p":"Correcto. Los primeros 3 meses son solo de día."},"zh":{"q":"在 Florida，持学习驾照的前 3 个月，你什么时候可以开车？","o":["白天晚上任何时间","只能开到午夜","只能在白天","只能在周末"],"h1":"新学员从光线最好、最容易的条件开始。","h2":"在前 3 个月，学习驾驶的人只能在白天开车，因为看得清楚更容易安全地学习。","p":"对。前 3 个月只能在白天开车。"},"vi":{"q":"Ở Florida, trong 3 tháng đầu có giấy phép tập lái, bạn được lái xe khi nào?","o":["Bất kỳ giờ nào, ngày hay đêm","Chỉ đến nửa đêm","Chỉ vào ban ngày","Chỉ vào cuối tuần"],"h1":"Người mới tập lái bắt đầu với điều kiện ánh sáng dễ nhất.","h2":"Trong 3 tháng đầu, người tập lái chỉ được lái xe vào ban ngày, vì nhìn rõ giúp việc học lái an toàn hơn.","p":"Đúng. 3 tháng đầu chỉ được lái vào ban ngày."},"tl":{"q":"Sa Florida, sa unang 3 buwan na may learner license, kailan ka puwedeng magmaneho?","o":["Kahit anong oras, araw man o gabi","Hanggang hatinggabi lang","Habang may liwanag ng araw lang","Tuwing weekend lang"],"h1":"Nagsisimula ang mga bagong learner sa pinakamadaling kondisyon ng liwanag.","h2":"Sa unang 3 buwan, ang learner ay puwedeng magmaneho habang may liwanag ng araw lang, dahil mas madaling matuto nang ligtas kapag malinaw ang nakikita.","p":"Tama. Sa unang 3 buwan, sa araw lang puwedeng magmaneho."},"ar":{"q":"في Florida، في أول 3 أشهر مع رخصة المتعلم، متى يُسمح لك بالقيادة؟","o":["في أي وقت من النهار أو الليل","حتى منتصف الليل فقط","في ساعات النهار فقط","في عطلة نهاية الأسبوع فقط"],"h1":"المتعلمون الجدد يبدؤون في أسهل ظروف الإضاءة.","h2":"في أول 3 أشهر، يُسمح للمتعلم بالقيادة في النهار فقط، لأن الرؤية الجيدة تجعل التعلم الآمن أسهل.","p":"صحيح. أول 3 أشهر للقيادة في النهار فقط."},"ht":{"q":"Nan Florida, pandan 3 premye mwa ou gen lisans aprantisaj la, ki lè ou ka kondi?","o":["Nenpòt lè, lajounen kou lannwit","Sèlman jiska minwi","Sèlman lajounen, lè gen limyè solèy","Sèlman nan wikenn"],"h1":"Nouvo apranti yo kòmanse ak limyè ki pi fasil la.","h2":"Pandan 3 premye mwa yo, yon apranti ka kondi sèlman lajounen, paske lè ou wè byen, li pi fasil pou aprann san danje.","p":"Se sa. 3 premye mwa yo, se lajounen sèlman."},"ref":{"doc":"FL","page":25}},{"id":"licensing-005","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after 3 months with a learner license, until what time may you drive?","o":["Until 8 p.m.","Until 10 p.m.","Until midnight","Until 1 a.m."],"h1":"After 3 months, you may drive later, but not late into the night.","h2":"After the first 3 months, a learner may drive until 10 p.m., still with a licensed driver age 21 or older.","p":"Right. After 3 months, a learner may drive until 10 p.m."},"es":{"q":"En Florida, después de 3 meses con licencia de aprendiz, ¿hasta qué hora puede manejar?","o":["Hasta las 8 p.m.","Hasta las 10 p.m.","Hasta la medianoche","Hasta la 1 a.m."],"h1":"Después de 3 meses puede manejar más tarde, pero no hasta muy tarde en la noche.","h2":"Después de los primeros 3 meses, el aprendiz puede manejar hasta las 10 p.m., siempre con un conductor con licencia de 21 años o más.","p":"Correcto. Después de 3 meses, el aprendiz puede manejar hasta las 10 p.m."},"zh":{"q":"在 Florida，持学习驾照 3 个月以后，你可以开车到几点？","o":["到晚上 8 点","到晚上 10 点","到午夜","到凌晨 1 点"],"h1":"3 个月以后，你可以开得晚一些，但不能开到深夜。","h2":"前 3 个月以后，学习驾驶的人可以开车到晚上 10 点，但仍然要有一位 21 岁或以上、有驾照的司机陪同。","p":"对。3 个月以后，学习驾驶的人可以开车到晚上 10 点。"},"vi":{"q":"Ở Florida, sau 3 tháng có giấy phép tập lái, bạn được lái xe đến mấy giờ?","o":["Đến 8 giờ tối","Đến 10 giờ tối","Đến nửa đêm","Đến 1 giờ sáng"],"h1":"Sau 3 tháng, bạn được lái muộn hơn, nhưng không được lái khuya.","h2":"Sau 3 tháng đầu, người tập lái được lái xe đến 10 giờ tối, vẫn phải có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Sau 3 tháng, người tập lái được lái đến 10 giờ tối."},"tl":{"q":"Sa Florida, pagkalipas ng 3 buwan na may learner license, hanggang anong oras ka puwedeng magmaneho?","o":["Hanggang 8 p.m.","Hanggang 10 p.m.","Hanggang hatinggabi","Hanggang 1 a.m."],"h1":"Pagkalipas ng 3 buwan, puwede ka nang magmaneho nang mas gabi, pero hindi hanggang malalim na gabi.","h2":"Pagkalipas ng unang 3 buwan, ang learner ay puwedeng magmaneho hanggang 10 p.m., kasama pa rin ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Pagkalipas ng 3 buwan, puwedeng magmaneho ang learner hanggang 10 p.m."},"ar":{"q":"في Florida، بعد 3 أشهر مع رخصة المتعلم، حتى أي ساعة يُسمح لك بالقيادة؟","o":["حتى الساعة 8 مساءً","حتى الساعة 10 مساءً","حتى منتصف الليل","حتى الساعة 1 بعد منتصف الليل"],"h1":"بعد 3 أشهر يمكنك القيادة لوقت أطول، لكن ليس حتى وقت متأخر من الليل.","h2":"بعد أول 3 أشهر، يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً، ويبقى معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. بعد 3 أشهر يُسمح للمتعلم بالقيادة حتى الساعة 10 مساءً."},"ht":{"q":"Nan Florida, apre 3 mwa ak lisans aprantisaj la, jiska ki lè ou ka kondi?","o":["Jiska 8 p.m.","Jiska 10 p.m.","Jiska minwi","Jiska 1 a.m."],"h1":"Apre 3 mwa, ou ka kondi pi ta, men pa twò ta nan nwit lan.","h2":"Apre 3 premye mwa yo, yon apranti ka kondi jiska 10 p.m., toujou ak yon chofè ki gen lisans epi ki gen 21 an oswa plis.","p":"Se sa. Apre 3 mwa, yon apranti ka kondi jiska 10 p.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-006","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what course must a first-time driver finish before getting a license?","o":["A defensive driving course for truck drivers","A first aid and CPR course","A motorcycle safety course","The Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"The course covers traffic laws and the danger of alcohol and drugs.","h2":"First-time drivers must finish the Traffic Law and Substance Abuse Education course, called TLSAE, which teaches traffic laws and how alcohol and drugs affect driving.","p":"Right. First-time drivers must take the TLSAE course."},"es":{"q":"En Florida, ¿qué curso debe terminar una persona que saca su primera licencia?","o":["Un curso de manejo defensivo para camioneros","Un curso de primeros auxilios y RCP","Un curso de seguridad en motocicleta","El curso de Ley de Tránsito y Educación sobre Abuso de Sustancias (TLSAE)"],"h1":"El curso trata de las leyes de tránsito y del peligro del alcohol y las drogas.","h2":"Quien saca su primera licencia debe terminar el curso de Ley de Tránsito y Educación sobre Abuso de Sustancias, llamado TLSAE, que enseña las leyes de tránsito y cómo el alcohol y las drogas afectan al manejar.","p":"Correcto. Los conductores nuevos deben tomar el curso TLSAE."},"zh":{"q":"在 Florida，第一次考驾照的人拿驾照前必须完成什么课程？","o":["卡车司机的防御性驾驶课程","急救和心肺复苏 (CPR) 课程","摩托车安全课程","交通法规与药物酒精滥用教育课程 (TLSAE)"],"h1":"这个课程讲交通法规，以及酒精和毒品的危险。","h2":"第一次考驾照的人必须完成交通法规与药物酒精滥用教育课程，叫做 TLSAE，它教交通法规，以及酒精和毒品怎样影响开车。","p":"对。第一次考驾照的人必须上 TLSAE 课程。"},"vi":{"q":"Ở Florida, người lái xe lần đầu phải học xong khóa học nào trước khi được cấp bằng lái?","o":["Khóa lái xe phòng vệ cho tài xế xe tải","Khóa sơ cứu và hồi sức tim phổi (CPR)","Khóa an toàn lái xe máy","Khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện (TLSAE)"],"h1":"Khóa học này nói về luật giao thông và sự nguy hiểm của rượu bia và ma túy.","h2":"Người lái xe lần đầu phải học xong khóa Luật Giao thông và Giáo dục về Lạm dụng Chất gây nghiện, gọi là TLSAE, khóa này dạy luật giao thông và cách rượu bia, ma túy ảnh hưởng đến việc lái xe.","p":"Đúng. Người lái xe lần đầu phải học khóa TLSAE."},"tl":{"q":"Sa Florida, anong kurso ang dapat tapusin ng unang beses na driver bago kumuha ng lisensya?","o":["Kurso sa defensive driving para sa mga truck driver","Kurso sa first aid at CPR","Kurso sa kaligtasan sa motorsiklo","Ang Traffic Law and Substance Abuse Education course (TLSAE)"],"h1":"Tungkol ang kurso sa mga batas trapiko at sa panganib ng alak at droga.","h2":"Ang mga unang beses na driver ay dapat tumapos ng Traffic Law and Substance Abuse Education course, na tinatawag na TLSAE, na nagtuturo ng mga batas trapiko at kung paano naaapektuhan ng alak at droga ang pagmamaneho.","p":"Tama. Ang mga unang beses na driver ay dapat kumuha ng TLSAE course."},"ar":{"q":"في Florida، ما الدورة التي يجب أن يُنهيها السائق لأول مرة قبل الحصول على الرخصة؟","o":["دورة القيادة الدفاعية لسائقي الشاحنات","دورة الإسعافات الأولية والإنعاش القلبي","دورة السلامة لسائقي الدراجات النارية","دورة قوانين المرور والتوعية بالكحول والمخدرات (TLSAE)"],"h1":"الدورة تشرح قوانين المرور وخطر الكحول والمخدرات.","h2":"يجب على السائقين لأول مرة أن يُنهوا دورة قوانين المرور والتوعية بالكحول والمخدرات، واسمها TLSAE، وهي تعلّم قوانين المرور وتأثير الكحول والمخدرات على القيادة.","p":"صحيح. السائقون لأول مرة يجب أن يأخذوا دورة TLSAE."},"ht":{"q":"Nan Florida, ki kou yon moun k ap kondi pou premye fwa dwe fini anvan l jwenn yon lisans?","o":["Yon kou kondi pridan pou chofè kamyon","Yon kou premye swen ak CPR","Yon kou sekirite pou motosiklèt","Kou Traffic Law and Substance Abuse Education (TLSAE)"],"h1":"Kou a pale sou lwa wout yo ak danje alkòl ak dwòg.","h2":"Moun k ap kondi pou premye fwa dwe fini kou Traffic Law and Substance Abuse Education, yo rele TLSAE, ki aprann lwa wout yo ak jan alkòl ak dwòg chanje fason ou kondi.","p":"Se sa. Moun k ap kondi pou premye fwa dwe pran kou TLSAE a."},"ref":{"doc":"FL","page":17}},{"id":"licensing-007","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, the learner license knowledge test has 50 questions. How many must you answer correctly to pass?","o":["At least 40","At least 30","At least 35","All 50"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 40 of the 50 questions correctly, which is 80 percent, to pass the knowledge test.","p":"Right. You need 40 correct answers out of 50."},"es":{"q":"En Florida, el examen de conocimientos para la licencia de aprendiz tiene 50 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["Por lo menos 40","Por lo menos 30","Por lo menos 35","Las 50"],"h1":"Necesita el 80 por ciento de las preguntas correctas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas, que es el 80 por ciento, para aprobar el examen de conocimientos.","p":"Correcto. Necesita 40 respuestas correctas de 50."},"zh":{"q":"在 Florida，学习驾照的笔试有 50 道题。你必须答对多少道才能通过？","o":["至少 40 道","至少 30 道","至少 35 道","全部 50 道"],"h1":"你需要答对 80% 的题目。","h2":"你必须在 50 道题里至少答对 40 道，也就是 80%，才能通过笔试。","p":"对。50 道题里你需要答对 40 道。"},"vi":{"q":"Ở Florida, bài thi kiến thức để lấy giấy phép tập lái có 50 câu hỏi. Bạn phải trả lời đúng bao nhiêu câu để đậu?","o":["Ít nhất 40 câu","Ít nhất 30 câu","Ít nhất 35 câu","Cả 50 câu"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trên 50 câu hỏi, tức là 80 phần trăm, để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 40 câu đúng trên 50 câu."},"tl":{"q":"Sa Florida, ang knowledge test para sa learner license ay may 50 tanong. Ilan ang dapat mong masagot nang tama para pumasa?","o":["Hindi bababa sa 40","Hindi bababa sa 30","Hindi bababa sa 35","Lahat ng 50"],"h1":"Kailangan mong makuha nang tama ang 80 porsyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong, na 80 porsyento, para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 40 tamang sagot sa 50."},"ar":{"q":"في Florida، اختبار المعرفة لرخصة المتعلم فيه 50 سؤالًا. كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["40 على الأقل","30 على الأقل","35 على الأقل","كل الأسئلة الـ 50"],"h1":"تحتاج إلى إجابة صحيحة عن 80 بالمئة من الأسئلة.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50، أي 80 بالمئة، لتنجح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة من 50."},"ht":{"q":"Nan Florida, egzamen konesans pou lisans aprantisaj la gen 50 kesyon. Konbyen ou dwe reponn kòrèk pou w pase?","o":["Omwen 40","Omwen 30","Omwen 35","Tout 50 yo"],"h1":"Ou bezwen 80 pousan nan kesyon yo bon.","h2":"Ou dwe reponn omwen 40 nan 50 kesyon yo kòrèk, sa ki fè 80 pousan, pou w pase egzamen konesans lan.","p":"Se sa. Ou bezwen 40 bon repons sou 50."},"ref":{"doc":"FL","page":null}},{"id":"licensing-008","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old wants a Class E license. How long must they first hold a learner license?","o":["3 months, with no traffic convictions","6 months, even with traffic convictions","12 months, or until age 18, with no traffic convictions","24 months, with no traffic convictions"],"h1":"Think about one full year of practice without breaking traffic laws.","h2":"A teen must hold the learner license for 12 months, or until turning 18, with no traffic convictions before getting a Class E license.","p":"Right. Hold the learner license 12 months with a clean record."},"es":{"q":"En Florida, una persona de 16 años quiere la licencia Clase E. ¿Cuánto tiempo debe tener antes la licencia de aprendiz?","o":["3 meses, sin condenas de tránsito","6 meses, aunque tenga condenas de tránsito","12 meses, o hasta cumplir 18, sin condenas de tránsito","24 meses, sin condenas de tránsito"],"h1":"Piense en un año completo de práctica sin violar las leyes de tránsito.","h2":"Un joven debe tener la licencia de aprendiz por 12 meses, o hasta cumplir 18 años, sin condenas de tránsito antes de obtener la licencia Clase E.","p":"Correcto. Tenga la licencia de aprendiz 12 meses con un récord limpio."},"zh":{"q":"在 Florida，一个 16 岁的人想拿 Class E 驾照。他必须先持有学习驾照多久？","o":["3 个月，没有交通违法定罪","6 个月，即使有交通违法定罪","12 个月，或者到 18 岁，没有交通违法定罪","24 个月，没有交通违法定罪"],"h1":"想一想整整一年的练习，而且不违反交通法规。","h2":"青少年必须持有学习驾照 12 个月，或者到满 18 岁，并且没有交通违法定罪，才能拿到 Class E 驾照。","p":"对。持有学习驾照 12 个月，记录要干净。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi muốn có bằng lái Class E. Trước đó, em phải giữ giấy phép tập lái trong bao lâu?","o":["3 tháng, không bị kết tội vi phạm giao thông","6 tháng, dù có bị kết tội vi phạm giao thông","12 tháng, hoặc đến khi 18 tuổi, không bị kết tội vi phạm giao thông","24 tháng, không bị kết tội vi phạm giao thông"],"h1":"Hãy nghĩ đến một năm tập lái trọn vẹn mà không vi phạm luật giao thông.","h2":"Thiếu niên phải giữ giấy phép tập lái trong 12 tháng, hoặc đến khi 18 tuổi, và không bị kết tội vi phạm giao thông, rồi mới được cấp bằng lái Class E.","p":"Đúng. Giữ giấy phép tập lái 12 tháng với hồ sơ sạch."},"tl":{"q":"Sa Florida, ang isang 16 taong gulang ay gustong kumuha ng Class E license. Gaano katagal muna niyang dapat hawak ang learner license?","o":["3 buwan, nang walang traffic conviction","6 na buwan, kahit may traffic conviction","12 buwan, o hanggang edad 18, nang walang traffic conviction","24 na buwan, nang walang traffic conviction"],"h1":"Isipin ang isang buong taon ng pagsasanay nang hindi lumalabag sa batas trapiko.","h2":"Ang teen ay dapat may hawak na learner license nang 12 buwan, o hanggang mag-18 taong gulang, nang walang traffic conviction bago makakuha ng Class E license.","p":"Tama. Hawakan ang learner license nang 12 buwan na malinis ang record."},"ar":{"q":"في Florida، شاب عمره 16 سنة يريد رخصة Class E. كم من الوقت يجب أن يحمل رخصة المتعلم أولًا؟","o":["3 أشهر، بدون مخالفات مرورية مُدان بها","6 أشهر، حتى مع مخالفات مرورية مُدان بها","12 شهرًا، أو حتى عمر 18، بدون مخالفات مرورية مُدان بها","24 شهرًا، بدون مخالفات مرورية مُدان بها"],"h1":"فكّر في سنة كاملة من التدريب بدون مخالفة قوانين المرور.","h2":"يجب على الشاب أن يحمل رخصة المتعلم 12 شهرًا، أو حتى يبلغ 18 سنة، بدون أي إدانة بمخالفة مرورية، قبل أن يحصل على رخصة Class E.","p":"صحيح. احمل رخصة المتعلم 12 شهرًا بسجل نظيف."},"ht":{"q":"Nan Florida, yon moun 16 an vle yon lisans Class E. Konbyen tan li dwe gen lisans aprantisaj la anvan?","o":["3 mwa, san okenn kondanasyon pou enfraksyon wout","6 mwa, menm si li gen kondanasyon pou enfraksyon wout","12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout","24 mwa, san okenn kondanasyon pou enfraksyon wout"],"h1":"Panse ak yon ane konplè pratik san ou pa vyole lwa wout yo.","h2":"Yon jèn dwe gen lisans aprantisaj la pandan 12 mwa, oswa jiskaske li gen 18 an, san okenn kondanasyon pou enfraksyon wout, anvan li jwenn yon lisans Class E.","p":"Se sa. Kenbe lisans aprantisaj la 12 mwa ak yon dosye pwòp."},"ref":{"doc":"FL","page":8}},{"id":"licensing-009","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many hours of supervised driving must a teen complete before getting a Class E license?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is a large number, with some of the hours at night.","h2":"A teen must complete 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Teens need 50 hours of supervised driving."},"es":{"q":"En Florida, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener la licencia Clase E?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es un número grande, y algunas de las horas son de noche.","h2":"Un joven debe completar 50 horas de manejo supervisado, y 10 de esas horas deben ser de noche.","p":"Correcto. Los jóvenes necesitan 50 horas de manejo supervisado."},"zh":{"q":"在 Florida，青少年拿 Class E 驾照前，必须完成多少小时有人监督的驾驶？","o":["20 小时","50 小时","30 小时","100 小时"],"h1":"这是一个比较大的数字，其中有一些小时要在晚上。","h2":"青少年必须完成 50 小时有人监督的驾驶，其中 10 小时必须在晚上。","p":"对。青少年需要 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Florida, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi được cấp bằng lái Class E?","o":["20 giờ","50 giờ","30 giờ","100 giờ"],"h1":"Đây là một con số lớn, và một phần số giờ phải lái vào ban đêm.","h2":"Thiếu niên phải lái xe có người giám sát đủ 50 giờ, và 10 giờ trong số đó phải lái vào ban đêm.","p":"Đúng. Thiếu niên cần 50 giờ lái xe có người giám sát."},"tl":{"q":"Sa Florida, ilang oras ng supervised driving (pagmamaneho na may kasamang lisensyadong adult) ang dapat tapusin ng teen bago makakuha ng Class E license?","o":["20 oras","50 oras","30 oras","100 oras"],"h1":"Malaking bilang ito, at ang ilan sa mga oras ay sa gabi.","h2":"Ang teen ay dapat tumapos ng 50 oras ng supervised driving, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. Kailangan ng teen ang 50 oras ng supervised driving."},"ar":{"q":"في Florida، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها الشاب قبل الحصول على رخصة Class E؟","o":["20 ساعة","50 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد كبير، وبعض الساعات تكون في الليل.","h2":"يجب على الشاب أن يُكمل 50 ساعة من القيادة تحت الإشراف، ويجب أن تكون 10 ساعات منها في الليل.","p":"صحيح. يحتاج الشباب إلى 50 ساعة من القيادة تحت الإشراف."},"ht":{"q":"Nan Florida, konbyen èdtan kondi ak siveyans yon jèn dwe fè anvan li jwenn yon lisans Class E?","o":["20 èdtan","50 èdtan","30 èdtan","100 èdtan"],"h1":"Se yon gwo kantite, epi kèk nan èdtan yo dwe fèt lannwit.","h2":"Yon jèn dwe fè 50 èdtan kondi ak siveyans, epi 10 nan èdtan sa yo dwe fèt lannwit.","p":"Se sa. Jèn yo bezwen 50 èdtan kondi ak siveyans."},"ref":{"doc":"FL","page":8}},{"id":"licensing-010","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, of the supervised driving hours a teen needs, how many must be at night?","o":["5 hours","25 hours","50 hours","10 hours"],"h1":"It is a small part of the total supervised hours.","h2":"Of the 50 supervised hours, at least 10 must be at night, so the teen learns to drive in the dark before driving alone.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Florida, de las horas de manejo supervisado que necesita un joven, ¿cuántas deben ser de noche?","o":["5 horas","25 horas","50 horas","10 horas"],"h1":"Es una parte pequeña del total de horas supervisadas.","h2":"De las 50 horas supervisadas, por lo menos 10 deben ser de noche, para que el joven aprenda a manejar en la oscuridad antes de manejar solo.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Florida，青少年需要的有人监督驾驶时间中，有多少小时必须在晚上？","o":["5 小时","25 小时","50 小时","10 小时"],"h1":"这只是全部监督时间里的一小部分。","h2":"在 50 小时有人监督的驾驶中，至少 10 小时必须在晚上，这样青少年在自己开车前就学会在黑暗中开车。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Florida, trong số giờ lái xe có người giám sát mà thiếu niên cần có, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","25 giờ","50 giờ","10 giờ"],"h1":"Đây là một phần nhỏ trong tổng số giờ có người giám sát.","h2":"Trong 50 giờ có người giám sát, ít nhất 10 giờ phải lái vào ban đêm, để thiếu niên học lái trong bóng tối trước khi lái một mình.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Florida, sa mga oras ng supervised driving na kailangan ng teen, ilan ang dapat sa gabi?","o":["5 oras","25 oras","50 oras","10 oras"],"h1":"Maliit na bahagi ito ng kabuuang supervised na oras.","h2":"Sa 50 supervised na oras, hindi bababa sa 10 ang dapat sa gabi, para matutong magmaneho ang teen sa dilim bago siya magmaneho nang mag-isa.","p":"Tama. Hindi bababa sa 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Florida، من ساعات القيادة تحت الإشراف التي يحتاجها الشاب، كم ساعة يجب أن تكون في الليل؟","o":["5 ساعات","25 ساعة","50 ساعة","10 ساعات"],"h1":"إنه جزء صغير من مجموع ساعات الإشراف.","h2":"من الـ 50 ساعة تحت الإشراف، يجب أن تكون 10 ساعات على الأقل في الليل، حتى يتعلم الشاب القيادة في الظلام قبل أن يقود وحده.","p":"صحيح. 10 ساعات على الأقل يجب أن تكون في الليل."},"ht":{"q":"Nan Florida, nan èdtan kondi ak siveyans yon jèn bezwen, konbyen ladan yo dwe fèt lannwit?","o":["5 èdtan","25 èdtan","50 èdtan","10 èdtan"],"h1":"Se yon ti pati nan total èdtan siveyans yo.","h2":"Nan 50 èdtan siveyans yo, omwen 10 dwe fèt lannwit, pou jèn nan aprann kondi nan fènwa anvan li kondi pou kont li.","p":"Se sa. Omwen 10 nan èdtan yo dwe fèt lannwit."},"ref":{"doc":"FL","page":8}},{"id":"licensing-011","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who certifies that a teen under 18 completed the supervised driving hours?","o":["A parent, legal guardian, or responsible adult","The teen alone","A police officer","The school principal"],"h1":"Think about the adult who is legally responsible for the teen.","h2":"A parent, legal guardian, or responsible adult must certify that the teen completed the supervised driving hours.","p":"Right. A parent or guardian certifies the driving hours."},"es":{"q":"En Florida, ¿quién certifica que un joven menor de 18 completó las horas de manejo supervisado?","o":["Un padre, tutor legal o adulto responsable","El joven solo","Un oficial de policía","El director de la escuela"],"h1":"Piense en el adulto que es legalmente responsable del joven.","h2":"Un padre, tutor legal o adulto responsable debe certificar que el joven completó las horas de manejo supervisado.","p":"Correcto. Un padre o tutor certifica las horas de manejo."},"zh":{"q":"在 Florida，谁来证明 18 岁以下的青少年完成了有人监督的驾驶时间？","o":["父母、法定监护人或负责任的成年人","青少年自己","警察","学校校长"],"h1":"想一想在法律上对这个青少年负责的成年人。","h2":"父母、法定监护人或负责任的成年人必须证明青少年完成了有人监督的驾驶时间。","p":"对。父母或监护人证明驾驶时间。"},"vi":{"q":"Ở Florida, ai xác nhận rằng một thiếu niên dưới 18 tuổi đã lái đủ số giờ có người giám sát?","o":["Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm","Chỉ một mình thiếu niên đó","Một cảnh sát","Hiệu trưởng nhà trường"],"h1":"Hãy nghĩ đến người lớn chịu trách nhiệm pháp lý cho thiếu niên đó.","h2":"Cha mẹ, người giám hộ hợp pháp, hoặc một người lớn có trách nhiệm phải xác nhận rằng thiếu niên đã lái đủ số giờ có người giám sát.","p":"Đúng. Cha mẹ hoặc người giám hộ xác nhận số giờ lái xe."},"tl":{"q":"Sa Florida, sino ang nagpapatunay na natapos ng teen na wala pang 18 ang mga oras ng supervised driving?","o":["Isang magulang, legal na guardian, o responsableng adult","Ang teen lang mismo","Isang pulis","Ang principal ng paaralan"],"h1":"Isipin ang adult na may legal na pananagutan sa teen.","h2":"Isang magulang, legal na guardian, o responsableng adult ang dapat magpatunay na natapos ng teen ang mga oras ng supervised driving.","p":"Tama. Ang magulang o guardian ang nagpapatunay ng mga oras ng pagmamaneho."},"ar":{"q":"في Florida، من يشهد بأن الشاب تحت 18 سنة أكمل ساعات القيادة تحت الإشراف؟","o":["أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول","الشاب وحده","شرطي","مدير المدرسة"],"h1":"فكّر في الشخص البالغ المسؤول قانونيًا عن الشاب.","h2":"يجب على أحد الوالدين، أو الوصي القانوني، أو شخص بالغ مسؤول، أن يشهد بأن الشاب أكمل ساعات القيادة تحت الإشراف.","p":"صحيح. أحد الوالدين أو الوصي يشهد على ساعات القيادة."},"ht":{"q":"Nan Florida, kiyès ki sètifye ke yon jèn ki poko gen 18 an fini èdtan kondi ak siveyans yo?","o":["Yon paran, yon gadyen legal, oswa yon granmoun ki responsab","Jèn nan pou kont li","Yon polis","Direktè lekòl la"],"h1":"Panse ak granmoun ki responsab jèn nan devan lalwa.","h2":"Yon paran, yon gadyen legal, oswa yon granmoun ki responsab dwe sètifye ke jèn nan fini èdtan kondi ak siveyans yo.","p":"Se sa. Yon paran oswa yon gadyen sètifye èdtan kondi yo."},"ref":{"doc":"FL","page":8}},{"id":"licensing-012","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 16-year-old with a Class E license may not drive alone during which hours?","o":["From 9 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 8 a.m."],"h1":"The younger the driver, the longer the night hours they cannot drive alone.","h2":"A 16-year-old may not drive from 11 p.m. to 6 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 16, no driving alone from 11 p.m. to 6 a.m."},"es":{"q":"En Florida, una persona de 16 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 9 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 8 a.m."],"h1":"Mientras más joven es el conductor, más largas son las horas de la noche en que no puede manejar solo.","h2":"Una persona de 16 años no puede manejar de 11 p.m. a 6 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 16, no se maneja solo de 11 p.m. a 6 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 16 岁司机在哪段时间不能单独开车？","o":["晚上 9 点到早上 5 点","凌晨 1 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 8 点"],"h1":"司机年龄越小，夜里不能单独开车的时间就越长。","h2":"16 岁的司机在晚上 11 点到早上 6 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。16 岁时，晚上 11 点到早上 6 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 16 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 8 giờ sáng"],"h1":"Tài xế càng nhỏ tuổi thì khoảng giờ ban đêm không được lái một mình càng dài.","h2":"Thiếu niên 16 tuổi không được lái xe từ 11 giờ tối đến 6 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 16, không lái một mình từ 11 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Florida, ang 16 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 8 a.m."],"h1":"Kapag mas bata ang driver, mas mahaba ang mga oras sa gabi na hindi siya puwedeng magmaneho nang mag-isa.","h2":"Ang 16 taong gulang ay hindi puwedeng magmaneho mula 11 p.m. hanggang 6 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 16, bawal magmaneho nang mag-isa mula 11 p.m. hanggang 6 a.m."},"ar":{"q":"في Florida، شاب عمره 16 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 9 مساءً إلى 5 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 8 صباحًا"],"h1":"كلما كان السائق أصغر، كانت ساعات الليل التي لا يقود فيها وحده أطول.","h2":"لا يُسمح لمن عمره 16 سنة بالقيادة من 11 مساءً إلى 6 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 16، لا قيادة وحدك من 11 مساءً إلى 6 صباحًا."},"ht":{"q":"Nan Florida, yon moun 16 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 9 p.m. rive 5 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 11 p.m. rive 6 a.m.","Soti minwi rive 8 a.m."],"h1":"Plis chofè a jèn, plis lè nan nwit li pa ka kondi pou kont li yo long.","h2":"Yon moun 16 an pa ka kondi soti 11 p.m. rive 6 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 16 an, ou pa kondi pou kont ou soti 11 p.m. rive 6 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-013","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a 17-year-old with a Class E license may not drive alone during which hours?","o":["From 11 p.m. to 6 a.m.","From 1 a.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 2 a.m. to 7 a.m."],"h1":"A 17-year-old gets a shorter limit than a 16-year-old.","h2":"A 17-year-old may not drive from 1 a.m. to 5 a.m. unless a licensed driver age 21 or older is with them or they are driving to or from work.","p":"Right. At 17, no driving alone from 1 a.m. to 5 a.m."},"es":{"q":"En Florida, una persona de 17 años con licencia Clase E, ¿durante qué horas no puede manejar sola?","o":["De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 2 a.m. a 7 a.m."],"h1":"A los 17 años el límite es más corto que a los 16.","h2":"Una persona de 17 años no puede manejar de 1 a.m. a 5 a.m., a menos que vaya con un conductor con licencia de 21 años o más, o que maneje hacia o desde el trabajo.","p":"Correcto. A los 17, no se maneja solo de 1 a.m. a 5 a.m."},"zh":{"q":"在 Florida，持 Class E 驾照的 17 岁司机在哪段时间不能单独开车？","o":["晚上 11 点到早上 6 点","凌晨 1 点到早上 5 点","晚上 10 点到早上 6 点","凌晨 2 点到早上 7 点"],"h1":"17 岁的司机受到的限制比 16 岁的司机短。","h2":"17 岁的司机在凌晨 1 点到早上 5 点不能开车，除非有一位 21 岁或以上、有驾照的司机陪同，或者他是在上班或下班的路上。","p":"对。17 岁时，凌晨 1 点到早上 5 点不能单独开车。"},"vi":{"q":"Ở Florida, một thiếu niên 17 tuổi có bằng lái Class E không được lái xe một mình trong khoảng giờ nào?","o":["Từ 11 giờ tối đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 2 giờ sáng đến 7 giờ sáng"],"h1":"Thiếu niên 17 tuổi bị giới hạn ngắn hơn thiếu niên 16 tuổi.","h2":"Thiếu niên 17 tuổi không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng hoặc em đang lái xe đi làm hay đi làm về.","p":"Đúng. Ở tuổi 17, không lái một mình từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Florida, ang 17 taong gulang na may Class E license ay hindi puwedeng magmaneho nang mag-isa sa anong mga oras?","o":["Mula 11 p.m. hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 2 a.m. hanggang 7 a.m."],"h1":"Mas maikli ang limitasyon ng 17 taong gulang kaysa sa 16 taong gulang.","h2":"Ang 17 taong gulang ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung kasama niya ang lisensyadong driver na 21 taong gulang o higit pa, o papunta o pauwi siya mula sa trabaho.","p":"Tama. Sa edad na 17, bawal magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Florida، شاب عمره 17 سنة يحمل رخصة Class E. في أي ساعات لا يُسمح له بالقيادة وحده؟","o":["من 11 مساءً إلى 6 صباحًا","من 1 بعد منتصف الليل إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 2 بعد منتصف الليل إلى 7 صباحًا"],"h1":"من عمره 17 سنة له وقت منع أقصر ممن عمره 16 سنة.","h2":"لا يُسمح لمن عمره 17 سنة بالقيادة من 1 بعد منتصف الليل إلى 5 صباحًا، إلا إذا كان معه سائق مرخّص عمره 21 سنة أو أكثر، أو كان ذاهبًا إلى العمل أو عائدًا منه.","p":"صحيح. في عمر 17، لا قيادة وحدك من 1 بعد منتصف الليل إلى 5 صباحًا."},"ht":{"q":"Nan Florida, yon moun 17 an ki gen lisans Class E pa ka kondi pou kont li nan ki lè?","o":["Soti 11 p.m. rive 6 a.m.","Soti 1 a.m. rive 5 a.m.","Soti 10 p.m. rive 6 a.m.","Soti 2 a.m. rive 7 a.m."],"h1":"Yon moun 17 an gen yon limit ki pi kout pase yon moun 16 an.","h2":"Yon moun 17 an pa ka kondi soti 1 a.m. rive 5 a.m., sof si yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l, oswa si l ap ale oswa l ap soti travay.","p":"Se sa. A 17 an, ou pa kondi pou kont ou soti 1 a.m. rive 5 a.m."},"ref":{"doc":"FL","page":25}},{"id":"licensing-014","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, when may a 16-year-old drive alone during curfew hours?","o":["When driving to a friend's house","When the roads are empty","When the trip is under 5 miles","When driving to or from work"],"h1":"The law makes an exception for a job.","h2":"A 16-year-old may drive alone during curfew hours only when driving to or from work, or when a licensed driver age 21 or older is with them.","p":"Right. Driving to or from work is allowed during curfew."},"es":{"q":"En Florida, ¿cuándo puede una persona de 16 años manejar sola en las horas restringidas?","o":["Cuando va a la casa de un amigo","Cuando las calles están vacías","Cuando el viaje es de menos de 5 millas","Cuando maneja hacia o desde el trabajo"],"h1":"La ley hace una excepción por el empleo.","h2":"Una persona de 16 años puede manejar sola en las horas restringidas solo cuando va hacia o desde el trabajo, o cuando la acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Se permite manejar hacia o desde el trabajo en esas horas."},"zh":{"q":"在 Florida，16 岁的司机在宵禁时间什么时候可以单独开车？","o":["开车去朋友家时","路上没有车时","路程少于 5 英里时","上班或下班的路上"],"h1":"法律对工作有一个例外。","h2":"16 岁的司机在宵禁时间只能在上班或下班的路上单独开车，或者有一位 21 岁或以上、有驾照的司机陪同。","p":"对。宵禁时间可以开车上班或下班。"},"vi":{"q":"Ở Florida, khi nào thiếu niên 16 tuổi được lái xe một mình trong giờ giới nghiêm?","o":["Khi lái xe đến nhà bạn","Khi đường vắng","Khi chuyến đi ngắn hơn 5 dặm","Khi lái xe đi làm hoặc đi làm về"],"h1":"Luật có một ngoại lệ dành cho công việc.","h2":"Thiếu niên 16 tuổi chỉ được lái xe một mình trong giờ giới nghiêm khi đi làm hoặc đi làm về, hoặc khi có người có bằng lái từ 21 tuổi trở lên đi cùng.","p":"Đúng. Được phép lái xe đi làm hoặc đi làm về trong giờ giới nghiêm."},"tl":{"q":"Sa Florida, kailan puwedeng magmaneho nang mag-isa ang 16 taong gulang sa oras ng curfew?","o":["Kapag papunta sa bahay ng kaibigan","Kapag walang laman ang mga daan","Kapag wala pang 5 milya ang biyahe","Kapag papunta o pauwi mula sa trabaho"],"h1":"May exception ang batas para sa trabaho.","h2":"Ang 16 taong gulang ay puwedeng magmaneho nang mag-isa sa oras ng curfew kapag papunta o pauwi lang siya mula sa trabaho, o kapag kasama niya ang lisensyadong driver na 21 taong gulang o higit pa.","p":"Tama. Puwede ang pagmamaneho papunta o pauwi mula sa trabaho sa oras ng curfew."},"ar":{"q":"في Florida، متى يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع الليلي؟","o":["عندما يذهب إلى بيت صديق","عندما تكون الطرق فارغة","عندما تكون الرحلة أقل من 5 أميال","عندما يذهب إلى العمل أو يعود منه"],"h1":"القانون يسمح باستثناء من أجل الوظيفة.","h2":"يُسمح لمن عمره 16 سنة بالقيادة وحده في ساعات المنع فقط عندما يذهب إلى العمل أو يعود منه، أو عندما يكون معه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. الذهاب إلى العمل أو العودة منه مسموح في ساعات المنع."},"ht":{"q":"Nan Florida, ki lè yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a?","o":["Lè l ap kondi al lakay yon zanmi","Lè wout yo vid","Lè vwayaj la mwens pase 5 mil","Lè l ap ale oswa l ap soti travay"],"h1":"Lalwa fè yon eksepsyon pou yon travay.","h2":"Yon moun 16 an ka kondi pou kont li pandan lè kouvrefe a sèlman lè l ap ale oswa l ap soti travay, oswa lè yon chofè ki gen lisans epi ki gen 21 an oswa plis avè l.","p":"Se sa. Ou gen dwa kondi pou ale oswa soti travay pandan kouvrefe a."},"ref":{"doc":"FL","page":25}},{"id":"licensing-015","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what happens if you get 12 points on your driving record within 12 months?","o":["Your license is suspended for 30 days","You get a warning letter only","Your license is suspended for 1 year","Nothing happens"],"h1":"This is the first and shortest point suspension.","h2":"If you get 12 points within 12 months, your license is suspended for 30 days.","p":"Right. 12 points in 12 months means a 30-day suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 12 puntos en su récord de manejo dentro de 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una carta de advertencia","Le suspenden la licencia por 1 año","No pasa nada"],"h1":"Es la primera suspensión por puntos y la más corta.","h2":"Si acumula 12 puntos dentro de 12 meses, le suspenden la licencia por 30 días.","p":"Correcto. 12 puntos en 12 meses significa 30 días de suspensión."},"zh":{"q":"在 Florida，如果你在 12 个月内驾驶记录被扣 12 分，会怎么样？","o":["你的驾照被暂停 30 天","你只会收到一封警告信","你的驾照被暂停 1 年","什么事也没有"],"h1":"这是第一种、也是最短的扣分暂停。","h2":"如果你在 12 个月内被扣 12 分，你的驾照会被暂停 30 天。","p":"对。12 个月内扣 12 分，驾照暂停 30 天。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 12 điểm trong hồ sơ lái xe trong vòng 12 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ nhận một thư cảnh cáo","Bằng lái của bạn bị đình chỉ 1 năm","Không có gì xảy ra"],"h1":"Đây là mức đình chỉ do điểm đầu tiên và ngắn nhất.","h2":"Nếu bạn bị 12 điểm trong vòng 12 tháng, bằng lái của bạn bị đình chỉ 30 ngày.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 12 points sa iyong driving record sa loob ng 12 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Warning letter lang ang matatanggap mo","Masususpinde ang lisensya mo nang 1 taon","Walang mangyayari"],"h1":"Ito ang una at pinakamaikling suspensyon dahil sa points.","h2":"Kung makakuha ka ng 12 points sa loob ng 12 buwan, masususpinde ang lisensya mo nang 30 araw.","p":"Tama. Ang 12 points sa loob ng 12 buwan ay suspensyon nang 30 araw."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 12 نقطة في سجل القيادة خلال 12 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تحصل على رسالة تحذير فقط","تُوقف رخصتك لمدة سنة واحدة","لا يحدث شيء"],"h1":"هذا هو أول إيقاف بسبب النقاط، وهو الأقصر.","h2":"إذا حصلت على 12 نقطة خلال 12 شهرًا، تُوقف رخصتك لمدة 30 يومًا.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إيقاف الرخصة 30 يومًا."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 12 pwen sou dosye kondi ou nan 12 mwa?","o":["Yo sispann lisans ou pou 30 jou","Ou jwenn yon lèt avètisman sèlman","Yo sispann lisans ou pou 1 an","Anyen pa rive"],"h1":"Se premye sispansyon pou pwen yo, epi se li ki pi kout.","h2":"Si ou jwenn 12 pwen nan 12 mwa, yo sispann lisans ou pou 30 jou.","p":"Se sa. 12 pwen nan 12 mwa vle di yon sispansyon 30 jou."},"ref":{"doc":"FL","page":29}},{"id":"licensing-016","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what happens if you get 18 points on your driving record within 18 months?","o":["Your license is suspended for 30 days","Your license is suspended for 5 years","Your license is suspended for 3 months","You must only pay a fine"],"h1":"It is longer than the 30-day suspension, but shorter than one year.","h2":"If you get 18 points within 18 months, your license is suspended for 3 months.","p":"Right. 18 points in 18 months means a 3-month suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 18 puntos en su récord de manejo dentro de 18 meses?","o":["Le suspenden la licencia por 30 días","Le suspenden la licencia por 5 años","Le suspenden la licencia por 3 meses","Solo tiene que pagar una multa"],"h1":"Es más larga que la suspensión de 30 días, pero más corta que un año.","h2":"Si acumula 18 puntos dentro de 18 meses, le suspenden la licencia por 3 meses.","p":"Correcto. 18 puntos en 18 meses significa 3 meses de suspensión."},"zh":{"q":"在 Florida，如果你在 18 个月内驾驶记录被扣 18 分，会怎么样？","o":["你的驾照被暂停 30 天","你的驾照被暂停 5 年","你的驾照被暂停 3 个月","你只需要交罚款"],"h1":"它比 30 天的暂停长，但比一年短。","h2":"如果你在 18 个月内被扣 18 分，你的驾照会被暂停 3 个月。","p":"对。18 个月内扣 18 分，驾照暂停 3 个月。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 18 điểm trong hồ sơ lái xe trong vòng 18 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bằng lái của bạn bị đình chỉ 5 năm","Bằng lái của bạn bị đình chỉ 3 tháng","Bạn chỉ phải đóng tiền phạt"],"h1":"Thời gian này dài hơn mức đình chỉ 30 ngày, nhưng ngắn hơn một năm.","h2":"Nếu bạn bị 18 điểm trong vòng 18 tháng, bằng lái của bạn bị đình chỉ 3 tháng.","p":"Đúng. 18 điểm trong 18 tháng nghĩa là bị đình chỉ 3 tháng."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 18 points sa iyong driving record sa loob ng 18 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Masususpinde ang lisensya mo nang 5 taon","Masususpinde ang lisensya mo nang 3 buwan","Multa lang ang babayaran mo"],"h1":"Mas mahaba ito kaysa sa suspensyon nang 30 araw, pero mas maikli kaysa sa isang taon.","h2":"Kung makakuha ka ng 18 points sa loob ng 18 buwan, masususpinde ang lisensya mo nang 3 buwan.","p":"Tama. Ang 18 points sa loob ng 18 buwan ay suspensyon nang 3 buwan."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 18 نقطة في سجل القيادة خلال 18 شهرًا؟","o":["تُوقف رخصتك لمدة 30 يومًا","تُوقف رخصتك لمدة 5 سنوات","تُوقف رخصتك لمدة 3 أشهر","يجب أن تدفع غرامة فقط"],"h1":"المدة أطول من إيقاف الـ 30 يومًا، لكنها أقصر من سنة.","h2":"إذا حصلت على 18 نقطة خلال 18 شهرًا، تُوقف رخصتك لمدة 3 أشهر.","p":"صحيح. 18 نقطة في 18 شهرًا تعني إيقاف الرخصة 3 أشهر."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 18 pwen sou dosye kondi ou nan 18 mwa?","o":["Yo sispann lisans ou pou 30 jou","Yo sispann lisans ou pou 5 an","Yo sispann lisans ou pou 3 mwa","Ou dwe peye yon amann sèlman"],"h1":"Li pi long pase sispansyon 30 jou a, men li pi kout pase yon ane.","h2":"Si ou jwenn 18 pwen nan 18 mwa, yo sispann lisans ou pou 3 mwa.","p":"Se sa. 18 pwen nan 18 mwa vle di yon sispansyon 3 mwa."},"ref":{"doc":"FL","page":29}},{"id":"licensing-017","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens if you get 24 points on your driving record within 36 months?","o":["Your license is suspended for 3 months","Your license is suspended for 1 year","Your license is suspended for 30 days","You must retake only the vision test"],"h1":"This is the most points, so it brings the longest point suspension.","h2":"If you get 24 points within 36 months, your license is suspended for 1 year.","p":"Right. 24 points in 36 months means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa si acumula 24 puntos en su récord de manejo dentro de 36 meses?","o":["Le suspenden la licencia por 3 meses","Le suspenden la licencia por 1 año","Le suspenden la licencia por 30 días","Solo tiene que repetir el examen de la vista"],"h1":"Son la mayor cantidad de puntos, así que traen la suspensión más larga.","h2":"Si acumula 24 puntos dentro de 36 meses, le suspenden la licencia por 1 año.","p":"Correcto. 24 puntos en 36 meses significa 1 año de suspensión."},"zh":{"q":"在 Florida，如果你在 36 个月内驾驶记录被扣 24 分，会怎么样？","o":["你的驾照被暂停 3 个月","你的驾照被暂停 1 年","你的驾照被暂停 30 天","你只需要重新考视力"],"h1":"这是最多的分数，所以扣分暂停的时间也最长。","h2":"如果你在 36 个月内被扣 24 分，你的驾照会被暂停 1 年。","p":"对。36 个月内扣 24 分，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra nếu bạn bị 24 điểm trong hồ sơ lái xe trong vòng 36 tháng?","o":["Bằng lái của bạn bị đình chỉ 3 tháng","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ phải thi lại phần kiểm tra mắt"],"h1":"Đây là số điểm cao nhất, nên dẫn đến mức đình chỉ do điểm dài nhất.","h2":"Nếu bạn bị 24 điểm trong vòng 36 tháng, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. 24 điểm trong 36 tháng nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari kung makakuha ka ng 24 points sa iyong driving record sa loob ng 36 na buwan?","o":["Masususpinde ang lisensya mo nang 3 buwan","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 30 araw","Vision test lang ang uulitin mo"],"h1":"Ito ang pinakamaraming points, kaya ito ang pinakamahabang suspensyon dahil sa points.","h2":"Kung makakuha ka ng 24 points sa loob ng 36 na buwan, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang 24 points sa loob ng 36 na buwan ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث إذا حصلت على 24 نقطة في سجل القيادة خلال 36 شهرًا؟","o":["تُوقف رخصتك لمدة 3 أشهر","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 30 يومًا","يجب أن تعيد اختبار النظر فقط"],"h1":"هذا أكبر عدد من النقاط، لذلك يأتي معه أطول إيقاف بسبب النقاط.","h2":"إذا حصلت على 24 نقطة خلال 36 شهرًا، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. 24 نقطة في 36 شهرًا تعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive si ou jwenn 24 pwen sou dosye kondi ou nan 36 mwa?","o":["Yo sispann lisans ou pou 3 mwa","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 30 jou","Ou dwe refè egzamen je a sèlman"],"h1":"Se plis pwen yo, kidonk li pote sispansyon pou pwen ki pi long lan.","h2":"Si ou jwenn 24 pwen nan 36 mwa, yo sispann lisans ou pou 1 an.","p":"Se sa. 24 pwen nan 36 mwa vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":29}},{"id":"licensing-018","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 18 gets 6 points within 12 months. What happens?","o":["Nothing until they reach 12 points","They get a free extra license","They must only write a letter","Driving is limited to business purposes only"],"h1":"Young drivers face limits sooner than adults.","h2":"A driver under 18 who gets 6 points within 12 months may drive only for business purposes, such as school or work, for one year.","p":"Right. Six points before 18 limits driving to business purposes only."},"es":{"q":"En Florida, un conductor menor de 18 acumula 6 puntos dentro de 12 meses. ¿Qué pasa?","o":["Nada hasta que llegue a 12 puntos","Recibe una licencia extra gratis","Solo tiene que escribir una carta","Solo puede manejar por motivos de negocio"],"h1":"Los conductores jóvenes tienen límites antes que los adultos.","h2":"Un conductor menor de 18 que acumula 6 puntos dentro de 12 meses solo puede manejar por motivos de negocio, como ir a la escuela o al trabajo, durante un año.","p":"Correcto. Seis puntos antes de los 18 limitan el manejo a motivos de negocio."},"zh":{"q":"在 Florida，一个 18 岁以下的司机在 12 个月内被扣 6 分。会怎么样？","o":["要到 12 分才会有事","他会得到一张免费的额外驾照","他只需要写一封信","只能为了办正事开车"],"h1":"年轻司机比成年人更早受到限制。","h2":"18 岁以下的司机如果在 12 个月内被扣 6 分，一年内只能为了办正事开车，例如上学或上班。","p":"对。18 岁前扣 6 分，就只能为了办正事开车。"},"vi":{"q":"Ở Florida, một tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng. Điều gì xảy ra?","o":["Không có gì cho đến khi bị 12 điểm","Tài xế được thêm một bằng lái miễn phí","Tài xế chỉ phải viết một lá thư","Tài xế chỉ được lái xe cho mục đích công việc"],"h1":"Tài xế trẻ bị giới hạn sớm hơn người lớn.","h2":"Tài xế dưới 18 tuổi bị 6 điểm trong vòng 12 tháng thì chỉ được lái xe cho mục đích công việc, như đi học hoặc đi làm, trong một năm.","p":"Đúng. Bị sáu điểm trước 18 tuổi thì chỉ được lái xe cho mục đích công việc."},"tl":{"q":"Sa Florida, ang driver na wala pang 18 ay nakakuha ng 6 points sa loob ng 12 buwan. Ano ang mangyayari?","o":["Wala, hangga't hindi umaabot sa 12 points","Bibigyan siya ng libreng dagdag na lisensya","Kailangan lang niyang sumulat ng liham","Limitado ang pagmamaneho sa business purposes lang"],"h1":"Mas maaga nagkakaroon ng limitasyon ang mga batang driver kaysa sa mga adult.","h2":"Ang driver na wala pang 18 na nakakuha ng 6 points sa loob ng 12 buwan ay puwedeng magmaneho para sa business purposes lang, gaya ng paaralan o trabaho, nang isang taon.","p":"Tama. Ang anim na points bago mag-18 ay naglilimita ng pagmamaneho sa business purposes lang."},"ar":{"q":"في Florida، سائق عمره أقل من 18 سنة حصل على 6 نقاط خلال 12 شهرًا. ماذا يحدث؟","o":["لا شيء حتى يصل إلى 12 نقطة","يحصل على رخصة إضافية مجانية","يجب أن يكتب رسالة فقط","تصبح القيادة مسموحة لأغراض العمل والدراسة فقط"],"h1":"السائقون الصغار يواجهون القيود أسرع من البالغين.","h2":"السائق الذي عمره أقل من 18 سنة ويحصل على 6 نقاط خلال 12 شهرًا يُسمح له بالقيادة لأغراض العمل والدراسة فقط، مثل المدرسة أو العمل، لمدة سنة واحدة.","p":"صحيح. ست نقاط قبل عمر 18 تحدّ القيادة لأغراض العمل والدراسة فقط."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 18 an jwenn 6 pwen nan 12 mwa. Kisa k rive?","o":["Anyen pa rive jiskaske li rive 12 pwen","Li jwenn yon lòt lisans gratis","Li dwe ekri yon lèt sèlman","Li ka kondi sèlman pou rezon biznis"],"h1":"Jèn chofè yo jwenn limit pi vit pase granmoun yo.","h2":"Yon chofè ki poko gen 18 an epi ki jwenn 6 pwen nan 12 mwa ka kondi sèlman pou rezon biznis, tankou lekòl oswa travay, pandan yon ane.","p":"Se sa. Sis pwen anvan 18 an limite w pou kondi sèlman pou rezon biznis."},"ref":{"doc":"FL","page":29}},{"id":"licensing-019","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is the minimum Personal Injury Protection (PIP) insurance a car owner must carry?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the same amount as the minimum property damage coverage.","h2":"A Florida car owner must carry at least $10,000 of Personal Injury Protection, which helps pay for your own injuries after a crash.","p":"Right. The PIP minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Protección contra Lesiones Personales (PIP) que debe tener el dueño de un carro?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la misma cantidad que la cobertura mínima de daños a la propiedad.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Protección contra Lesiones Personales, que ayuda a pagar sus propias lesiones después de un choque.","p":"Correcto. El mínimo de PIP es $10,000."},"zh":{"q":"在 Florida，车主必须买的个人伤害保障 (PIP) 保险最低是多少？","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"它和财产损失保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的个人伤害保障 (PIP)，它帮助支付你自己在车祸后的伤害费用。","p":"对。PIP 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Bảo vệ Thương tích Cá nhân (PIP) tối thiểu là bao nhiêu?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Số tiền này bằng với mức bảo hiểm tối thiểu cho thiệt hại tài sản.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Bảo vệ Thương tích Cá nhân, giúp trả chi phí cho thương tích của chính bạn sau tai nạn.","p":"Đúng. Mức PIP tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Personal Injury Protection (PIP) insurance na dapat mayroon ang may-ari ng kotse?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Pareho ito ng halaga ng pinakamababang coverage para sa pinsala sa ari-arian.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Personal Injury Protection, na tumutulong magbayad para sa sarili mong mga pinsala sa katawan pagkatapos ng banggaan.","p":"Tama. Ang pinakamababang PIP ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين الحماية من الإصابات الشخصية (PIP) يجب أن يكون لدى مالك السيارة؟","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"إنه نفس مبلغ أقل تغطية لأضرار الممتلكات.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين حماية من الإصابات الشخصية بمبلغ $10,000 على الأقل، وهو يساعد في دفع تكاليف إصاباتك أنت بعد الحادث.","p":"صحيح. أقل مبلغ لتأمين PIP هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Personal Injury Protection (PIP) yon mèt machin dwe genyen?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Se menm kantite ak pi piti kouvèti pou domaj sou byen moun.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Personal Injury Protection, ki ede peye pou pwòp blesi pa w apre yon aksidan.","p":"Se sa. Minimòm PIP la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-020","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what is the minimum Property Damage Liability (PDL) insurance a car owner must carry?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"It is the same amount as the minimum PIP coverage.","h2":"A Florida car owner must carry at least $10,000 of Property Damage Liability, which pays for damage you cause to other people's property.","p":"Right. The PDL minimum is $10,000."},"es":{"q":"En Florida, ¿cuál es el seguro mínimo de Responsabilidad por Daños a la Propiedad (PDL) que debe tener el dueño de un carro?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Es la misma cantidad que la cobertura mínima de PIP.","h2":"El dueño de un carro en Florida debe tener por lo menos $10,000 de Responsabilidad por Daños a la Propiedad, que paga los daños que usted causa a la propiedad de otras personas.","p":"Correcto. El mínimo de PDL es $10,000."},"zh":{"q":"在 Florida，车主必须买的财产损失责任 (PDL) 保险最低是多少？","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"它和 PIP 保险的最低金额一样。","h2":"Florida 的车主必须买至少 $10,000 的财产损失责任保险 (PDL)，它支付你给别人财产造成的损失。","p":"对。PDL 最低是 $10,000。"},"vi":{"q":"Ở Florida, chủ xe phải có bảo hiểm Trách nhiệm Thiệt hại Tài sản (PDL) tối thiểu là bao nhiêu?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Số tiền này bằng với mức PIP tối thiểu.","h2":"Chủ xe ở Florida phải có ít nhất $10,000 bảo hiểm Trách nhiệm Thiệt hại Tài sản, giúp trả cho thiệt hại bạn gây ra cho tài sản của người khác.","p":"Đúng. Mức PDL tối thiểu là $10,000."},"tl":{"q":"Sa Florida, magkano ang pinakamababang Property Damage Liability (PDL) insurance na dapat mayroon ang may-ari ng kotse?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Pareho ito ng halaga ng pinakamababang PIP coverage.","h2":"Ang may-ari ng kotse sa Florida ay dapat may hindi bababa sa $10,000 na Property Damage Liability, na nagbabayad para sa pinsalang nagawa mo sa ari-arian ng ibang tao.","p":"Tama. Ang pinakamababang PDL ay $10,000."},"ar":{"q":"في Florida، ما أقل مبلغ لتأمين المسؤولية عن أضرار الممتلكات (PDL) يجب أن يكون لدى مالك السيارة؟","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"إنه نفس مبلغ أقل تغطية لتأمين PIP.","h2":"يجب أن يكون لدى مالك السيارة في Florida تأمين مسؤولية عن أضرار الممتلكات بمبلغ $10,000 على الأقل، وهو يدفع ثمن الضرر الذي تسببه لممتلكات الآخرين.","p":"صحيح. أقل مبلغ لتأمين PDL هو $10,000."},"ht":{"q":"Nan Florida, ki pi piti kantite asirans Property Damage Liability (PDL) yon mèt machin dwe genyen?","o":["$1,000","$100,000","$10,000","$2,500"],"h1":"Se menm kantite ak pi piti kouvèti PIP la.","h2":"Yon mèt machin nan Florida dwe gen omwen $10,000 asirans Property Damage Liability, ki peye pou domaj ou fè sou byen lòt moun.","p":"Se sa. Minimòm PDL la se $10,000."},"ref":{"doc":"FL","page":23}},{"id":"licensing-021","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what should you do with your proof of insurance?","o":["Keep it at home in a safe place","Keep it in the car and show it when an officer asks","Show it only when you renew your license","Mail it to the police every year"],"h1":"An officer may ask for it at a traffic stop or after a crash.","h2":"You must keep proof of insurance with you in the car and show it when a law enforcement officer asks for it.","p":"Right. Keep proof of insurance in the car and show it when asked."},"es":{"q":"En Florida, ¿qué debe hacer con su comprobante de seguro?","o":["Guardarlo en casa en un lugar seguro","Tenerlo en el carro y mostrarlo cuando un oficial lo pida","Mostrarlo solo cuando renueve la licencia","Enviarlo por correo a la policía cada año"],"h1":"Un oficial se lo puede pedir en una parada de tránsito o después de un choque.","h2":"Usted debe tener el comprobante de seguro en el carro y mostrarlo cuando un oficial de la ley se lo pida.","p":"Correcto. Tenga el comprobante de seguro en el carro y muéstrelo cuando se lo pidan."},"zh":{"q":"在 Florida，你的保险证明应该怎么处理？","o":["放在家里安全的地方","放在车里，警察要的时候给他看","只在更新驾照时出示","每年寄给警察"],"h1":"在交通拦停或车祸后，警察可能会要看。","h2":"你必须把保险证明带在车里，执法人员要看的时候给他看。","p":"对。把保险证明放在车里，有人要看时出示。"},"vi":{"q":"Ở Florida, bạn nên làm gì với giấy chứng nhận bảo hiểm của mình?","o":["Cất ở nhà, ở một chỗ an toàn","Để trong xe và đưa ra khi cảnh sát yêu cầu","Chỉ đưa ra khi gia hạn bằng lái","Gửi qua bưu điện cho cảnh sát mỗi năm"],"h1":"Cảnh sát có thể yêu cầu xem giấy này khi chặn xe hoặc sau tai nạn.","h2":"Bạn phải để giấy chứng nhận bảo hiểm trong xe và đưa ra khi nhân viên công lực yêu cầu.","p":"Đúng. Để giấy chứng nhận bảo hiểm trong xe và đưa ra khi được yêu cầu."},"tl":{"q":"Sa Florida, ano ang dapat mong gawin sa iyong proof of insurance (patunay ng insurance)?","o":["Itago ito sa bahay sa ligtas na lugar","Itago ito sa kotse at ipakita kapag hiningi ng pulis","Ipakita lang ito kapag nagre-renew ka ng lisensya","Ipadala ito sa pulis bawat taon"],"h1":"Puwede itong hingin ng pulis kapag pinara ka o pagkatapos ng banggaan.","h2":"Dapat nasa kotse mo ang iyong proof of insurance at ipakita mo ito kapag hiningi ng law enforcement officer.","p":"Tama. Itago ang proof of insurance sa kotse at ipakita kapag hiningi."},"ar":{"q":"في Florida، ماذا يجب أن تفعل بإثبات التأمين؟","o":["احتفظ به في البيت في مكان آمن","احتفظ به في السيارة وأظهره عندما يطلبه الشرطي","أظهره فقط عندما تجدد رخصتك","أرسله بالبريد إلى الشرطة كل سنة"],"h1":"قد يطلبه الشرطي عند إيقافك في الطريق أو بعد حادث.","h2":"يجب أن تحتفظ بإثبات التأمين معك في السيارة، وأن تُظهره عندما يطلبه رجل الشرطة.","p":"صحيح. احتفظ بإثبات التأمين في السيارة وأظهره عند الطلب."},"ht":{"q":"Nan Florida, kisa ou dwe fè ak prèv asirans ou?","o":["Kenbe l lakay ou nan yon bon kote","Kenbe l nan machin nan epi montre l lè yon polis mande l","Montre l sèlman lè w ap renouvle lisans ou","Voye l bay lapolis pa lapòs chak ane"],"h1":"Yon polis ka mande l lè li kanpe w sou wout la oswa apre yon aksidan.","h2":"Ou dwe kenbe prèv asirans ou avè w nan machin nan epi montre l lè yon polis mande w li.","p":"Se sa. Kenbe prèv asirans lan nan machin nan epi montre l lè yo mande l."},"ref":{"doc":"FL","page":23}},{"id":"licensing-022","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you are in a crash and someone is hurt. What must you do?","o":["Leave and call your insurance later","Drive the injured person home","Wait until the next day to report it","Stay at the scene and call the police"],"h1":"When someone is injured, the law requires an official report right away.","h2":"When a crash injures someone, you must stay at the scene, call the police, and help the injured person get medical care.","p":"Right. If someone is hurt, stay and call the police."},"es":{"q":"En Florida, usted tiene un choque y alguien está herido. ¿Qué debe hacer?","o":["Irse y llamar a su seguro después","Llevar al herido a su casa","Esperar al día siguiente para reportarlo","Quedarse en el lugar y llamar a la policía"],"h1":"Cuando alguien está herido, la ley exige un reporte oficial enseguida.","h2":"Cuando un choque deja a alguien herido, usted debe quedarse en el lugar, llamar a la policía y ayudar a que el herido reciba atención médica.","p":"Correcto. Si alguien está herido, quédese y llame a la policía."},"zh":{"q":"在 Florida，你发生车祸，有人受伤。你必须做什么？","o":["离开，以后再打电话给保险公司","开车送受伤的人回家","等到第二天再报告","留在现场，打电话报警"],"h1":"有人受伤时，法律要求马上做正式报告。","h2":"车祸让人受伤时，你必须留在现场，打电话报警，并帮助受伤的人得到医疗救助。","p":"对。有人受伤时，留下来并报警。"},"vi":{"q":"Ở Florida, bạn bị tai nạn và có người bị thương. Bạn phải làm gì?","o":["Rời đi và gọi cho công ty bảo hiểm sau","Chở người bị thương về nhà","Đợi đến ngày hôm sau mới báo","Ở lại hiện trường và gọi cảnh sát"],"h1":"Khi có người bị thương, luật yêu cầu phải báo cáo chính thức ngay.","h2":"Khi tai nạn làm có người bị thương, bạn phải ở lại hiện trường, gọi cảnh sát, và giúp người bị thương được chăm sóc y tế.","p":"Đúng. Nếu có người bị thương, hãy ở lại và gọi cảnh sát."},"tl":{"q":"Sa Florida, nabangga ka at may nasaktan. Ano ang dapat mong gawin?","o":["Umalis at tumawag sa insurance mo mamaya","Ihatid pauwi ang taong nasaktan","Maghintay hanggang kinabukasan bago i-report","Manatili sa lugar ng banggaan at tumawag sa pulis"],"h1":"Kapag may nasaktan, hinihingi ng batas ang opisyal na report agad.","h2":"Kapag may nasaktan sa banggaan, dapat kang manatili sa lugar, tumawag sa pulis, at tulungan ang nasaktan na makakuha ng medikal na tulong.","p":"Tama. Kapag may nasaktan, manatili at tumawag sa pulis."},"ar":{"q":"في Florida، وقع لك حادث وأصيب شخص. ماذا يجب أن تفعل؟","o":["اذهب واتصل بشركة التأمين لاحقًا","خذ المصاب بالسيارة إلى بيته","انتظر حتى اليوم التالي لتبلّغ عن الحادث","ابقَ في مكان الحادث واتصل بالشرطة"],"h1":"عندما يصاب شخص، يطلب القانون تقريرًا رسميًا فورًا.","h2":"عندما يصاب شخص في حادث، يجب أن تبقى في مكان الحادث، وأن تتصل بالشرطة، وأن تساعد المصاب في الحصول على علاج طبي.","p":"صحيح. إذا أصيب شخص، ابقَ واتصل بالشرطة."},"ht":{"q":"Nan Florida, ou fè yon aksidan epi gen yon moun ki blese. Kisa ou dwe fè?","o":["Ale, epi rele asirans ou pita","Mennen moun ki blese a lakay li","Tann jouk demen pou w deklare l","Rete kote aksidan an epi rele lapolis"],"h1":"Lè yon moun blese, lalwa mande yon rapò ofisyèl touswit.","h2":"Lè yon aksidan blese yon moun, ou dwe rete kote aksidan an, rele lapolis, epi ede moun ki blese a jwenn swen medikal.","p":"Se sa. Si yon moun blese, rete epi rele lapolis."},"ref":{"doc":"FL","page":77}},{"id":"licensing-023","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what is true about leaving the scene of a crash where someone was hurt?","o":["It is a serious crime and can be a felony","It is allowed if you were not at fault","It is allowed if you are late for work","It is only a small parking fine"],"h1":"Think about how serious the law treats leaving a hurt person behind.","h2":"Leaving the scene of a crash where someone was hurt is a serious crime in Florida and can be a felony, with jail time and loss of your license.","p":"Right. Leaving a crash with injuries is a serious crime."},"es":{"q":"En Florida, ¿qué es cierto sobre irse del lugar de un choque donde alguien resultó herido?","o":["Es un delito grave y puede ser un delito mayor (felony)","Está permitido si usted no tuvo la culpa","Está permitido si va tarde al trabajo","Es solo una multa pequeña de estacionamiento"],"h1":"Piense en lo grave que la ley considera dejar atrás a una persona herida.","h2":"Irse del lugar de un choque donde alguien resultó herido es un delito grave en Florida y puede ser un delito mayor, con cárcel y pérdida de la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"zh":{"q":"在 Florida，离开有人受伤的车祸现场，哪一个说法是对的？","o":["这是严重的犯罪，可能是重罪","如果不是你的错，就可以离开","如果你上班要迟到了，就可以离开","这只是一张小小的停车罚单"],"h1":"想一想法律怎样严肃地看待丢下受伤的人。","h2":"在 Florida，离开有人受伤的车祸现场是严重的犯罪，可能是重罪，会坐牢并失去驾照。","p":"对。离开有人受伤的车祸现场是严重的犯罪。"},"vi":{"q":"Ở Florida, điều nào đúng về việc bỏ đi khỏi hiện trường tai nạn có người bị thương?","o":["Đó là tội nghiêm trọng và có thể là trọng tội","Được phép nếu bạn không có lỗi","Được phép nếu bạn bị trễ giờ làm","Đó chỉ là một khoản phạt đậu xe nhỏ"],"h1":"Hãy nghĩ xem luật coi việc bỏ lại người bị thương nghiêm trọng đến mức nào.","h2":"Bỏ đi khỏi hiện trường tai nạn có người bị thương là tội nghiêm trọng ở Florida và có thể là trọng tội, có thể bị tù và mất bằng lái.","p":"Đúng. Bỏ đi khỏi tai nạn có người bị thương là tội nghiêm trọng."},"tl":{"q":"Sa Florida, ano ang totoo tungkol sa pag-alis sa lugar ng banggaan kung saan may nasaktan?","o":["Malubhang krimen ito at puwedeng maging felony","Puwede ito kung hindi ikaw ang may kasalanan","Puwede ito kung late ka na sa trabaho","Maliit na multa lang ito, gaya ng sa parking"],"h1":"Isipin kung gaano kabigat ang tingin ng batas sa pag-iwan sa taong nasaktan.","h2":"Ang pag-alis sa lugar ng banggaan kung saan may nasaktan ay malubhang krimen sa Florida at puwedeng maging felony, na may kulong at pagkawala ng lisensya.","p":"Tama. Malubhang krimen ang pag-alis sa banggaan na may nasaktan."},"ar":{"q":"في Florida، ما الصحيح عن ترك مكان حادث أصيب فيه شخص؟","o":["إنه جريمة خطيرة وقد يكون جناية","إنه مسموح إذا لم تكن أنت المخطئ","إنه مسموح إذا كنت متأخرًا عن العمل","إنه مجرد غرامة وقوف صغيرة"],"h1":"فكّر في مدى جدية القانون مع من يترك شخصًا مصابًا.","h2":"ترك مكان حادث أصيب فيه شخص هو جريمة خطيرة في Florida وقد يكون جناية، وعقوبته السجن وفقدان الرخصة.","p":"صحيح. ترك حادث فيه إصابات جريمة خطيرة."},"ht":{"q":"Nan Florida, kisa ki vre lè yon moun kite kote yon aksidan kote gen yon moun ki te blese?","o":["Se yon krim grav, epi li ka yon felony","Ou gen dwa fè l si se pa t fòt ou","Ou gen dwa fè l si ou an reta pou travay","Se sèlman yon ti amann pou pakin"],"h1":"Panse ak jan lalwa pran l oserye lè yon moun kite yon moun ki blese dèyè.","h2":"Kite kote yon aksidan kote yon moun te blese se yon krim grav nan Florida, epi li ka yon felony, ak prizon epi ou ka pèdi lisans ou.","p":"Se sa. Kite yon aksidan kote gen moun ki blese se yon krim grav."},"ref":{"doc":"FL","page":77}},{"id":"licensing-024","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you hit a parked car and no one is around. What must you do?","o":["Drive away because no one saw it","Wait one hour, then leave","Find the owner or leave a note with your name and address, and report it to police","Report it only if the damage is large"],"h1":"The owner needs a way to contact you.","h2":"If you hit an unattended car, you must find the owner or leave a note with your name and address in a safe place on the car, and report the crash to the police.","p":"Right. Leave your name and address, and tell the police."},"es":{"q":"En Florida, usted choca un carro estacionado y no hay nadie. ¿Qué debe hacer?","o":["Irse porque nadie lo vio","Esperar una hora y luego irse","Buscar al dueño o dejar una nota con su nombre y dirección, y reportarlo a la policía","Reportarlo solo si el daño es grande"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"Si choca un carro sin nadie adentro, debe buscar al dueño o dejar una nota con su nombre y dirección en un lugar seguro del carro, y reportar el choque a la policía.","p":"Correcto. Deje su nombre y dirección, y avise a la policía."},"zh":{"q":"在 Florida，你撞到一辆停着的车，周围没有人。你必须做什么？","o":["开走，因为没人看到","等一个小时，然后离开","找到车主，或留下写有你姓名和地址的纸条，并向警察报告","只有损坏很大时才报告"],"h1":"车主需要有办法联系你。","h2":"如果你撞到一辆没有人的车，你必须找到车主，或在车上安全的地方留下写有你姓名和地址的纸条，并向警察报告这次车祸。","p":"对。留下你的姓名和地址，并告诉警察。"},"vi":{"q":"Ở Florida, bạn đụng vào một xe đang đậu và không có ai xung quanh. Bạn phải làm gì?","o":["Lái đi vì không ai nhìn thấy","Đợi một giờ rồi rời đi","Tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn, và báo cho cảnh sát","Chỉ báo nếu hư hỏng lớn"],"h1":"Chủ xe cần có cách để liên lạc với bạn.","h2":"Nếu bạn đụng vào một xe không có người trông, bạn phải tìm chủ xe hoặc để lại giấy ghi tên và địa chỉ của bạn ở chỗ an toàn trên xe, và báo tai nạn cho cảnh sát.","p":"Đúng. Để lại tên và địa chỉ, và báo cho cảnh sát."},"tl":{"q":"Sa Florida, nabangga mo ang isang nakaparadang kotse at walang tao sa paligid. Ano ang dapat mong gawin?","o":["Umalis dahil walang nakakita","Maghintay ng isang oras, saka umalis","Hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo, at i-report sa pulis","I-report lang kung malaki ang sira"],"h1":"Kailangan ng may-ari ng paraan para makontak ka.","h2":"Kung nabangga mo ang kotseng walang tao, dapat mong hanapin ang may-ari o mag-iwan ng sulat na may pangalan at address mo sa ligtas na lugar sa kotse, at i-report ang banggaan sa pulis.","p":"Tama. Iwan ang pangalan at address mo, at sabihin sa pulis."},"ar":{"q":"في Florida، صدمت سيارة واقفة ولا يوجد أحد حولها. ماذا يجب أن تفعل؟","o":["اذهب لأن لا أحد رأى ذلك","انتظر ساعة واحدة ثم اذهب","ابحث عن المالك أو اترك ورقة فيها اسمك وعنوانك، وبلّغ الشرطة","بلّغ فقط إذا كان الضرر كبيرًا"],"h1":"المالك يحتاج إلى طريقة للتواصل معك.","h2":"إذا صدمت سيارة ليس فيها أحد، يجب أن تجد المالك أو تترك ورقة فيها اسمك وعنوانك في مكان آمن على السيارة، وأن تبلّغ الشرطة عن الحادث.","p":"صحيح. اترك اسمك وعنوانك، وأخبر الشرطة."},"ht":{"q":"Nan Florida, ou frape yon machin ki pake epi pa gen pèsonn la. Kisa ou dwe fè?","o":["Ale paske pèsonn pa wè sa","Tann inèdtan, epi ale","Chèche mèt la oswa kite yon nòt ak non ou ak adrès ou, epi deklare l bay lapolis","Deklare l sèlman si domaj la gwo"],"h1":"Mèt machin nan bezwen yon fason pou l kontakte w.","h2":"Si ou frape yon machin ki pa gen pèsonn ladan l, ou dwe chèche mèt la oswa kite yon nòt ak non ou ak adrès ou nan yon kote ki an sekirite sou machin nan, epi deklare aksidan an bay lapolis.","p":"Se sa. Kite non ou ak adrès ou, epi di lapolis sa."},"ref":{"doc":"FL","page":77}},{"id":"licensing-025","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after a minor crash with no injuries, the cars can still be driven. What should you do?","o":["Leave the cars where they stopped","Move the cars out of the travel lanes","Drive home without talking to anyone","Stand in the road to direct traffic"],"h1":"Blocking traffic can cause a second crash.","h2":"If no one is hurt and the cars can be driven, move them out of the travel lanes to a safe place, then exchange information.","p":"Right. Move the cars out of traffic if no one is hurt."},"es":{"q":"En Florida, después de un choque leve sin heridos, los carros todavía pueden andar. ¿Qué debe hacer?","o":["Dejar los carros donde quedaron","Sacar los carros de los carriles de tránsito","Irse a casa sin hablar con nadie","Pararse en la calle para dirigir el tráfico"],"h1":"Bloquear el tráfico puede causar un segundo choque.","h2":"Si nadie está herido y los carros pueden andar, sáquelos de los carriles de tránsito a un lugar seguro y después intercambie información.","p":"Correcto. Si nadie está herido, saque los carros del tráfico."},"zh":{"q":"在 Florida，一次小车祸后没有人受伤，车还能开。你应该做什么？","o":["把车留在停下的地方","把车移出行车道","不和任何人说话就开回家","站在路中间指挥交通"],"h1":"挡住交通可能引起第二次车祸。","h2":"如果没有人受伤，车也还能开，就把车移出行车道，开到安全的地方，然后交换资料。","p":"对。没有人受伤时，把车移出车流。"},"vi":{"q":"Ở Florida, sau một tai nạn nhẹ không ai bị thương, các xe vẫn còn chạy được. Bạn nên làm gì?","o":["Để các xe ở nguyên chỗ dừng","Đưa các xe ra khỏi làn xe chạy","Lái về nhà mà không nói chuyện với ai","Đứng giữa đường để điều khiển giao thông"],"h1":"Chắn đường có thể gây ra tai nạn thứ hai.","h2":"Nếu không ai bị thương và các xe còn chạy được, hãy đưa xe ra khỏi làn xe chạy đến chỗ an toàn, rồi trao đổi thông tin.","p":"Đúng. Đưa xe ra khỏi dòng xe nếu không ai bị thương."},"tl":{"q":"Sa Florida, pagkatapos ng maliit na banggaan na walang nasaktan, puwede pang imaneho ang mga kotse. Ano ang dapat mong gawin?","o":["Iwan ang mga kotse kung saan sila huminto","Ilipat ang mga kotse palabas ng mga lane na dinadaanan","Umuwi nang hindi kumakausap ng kahit sino","Tumayo sa daan para ayusin ang trapiko"],"h1":"Ang pagharang sa trapiko ay puwedeng magdulot ng pangalawang banggaan.","h2":"Kung walang nasaktan at puwede pang imaneho ang mga kotse, ilipat ang mga ito palabas ng mga lane na dinadaanan papunta sa ligtas na lugar, saka magpalitan ng impormasyon.","p":"Tama. Ilipat ang mga kotse palabas ng trapiko kung walang nasaktan."},"ar":{"q":"في Florida، بعد حادث بسيط بدون إصابات، ما زالت السيارات تستطيع السير. ماذا يجب أن تفعل؟","o":["اترك السيارات حيث توقفت","أبعد السيارات عن مسارات السير","اذهب إلى البيت بدون أن تتكلم مع أحد","قف في الطريق لتنظّم حركة السير"],"h1":"إغلاق الطريق قد يسبب حادثًا ثانيًا.","h2":"إذا لم يُصب أحد وكانت السيارات تستطيع السير، أبعدها عن مسارات السير إلى مكان آمن، ثم تبادلوا المعلومات.","p":"صحيح. أبعد السيارات عن حركة السير إذا لم يُصب أحد."},"ht":{"q":"Nan Florida, apre yon ti aksidan san moun blese, machin yo ka toujou woule. Kisa ou ta dwe fè?","o":["Kite machin yo kote yo te kanpe a","Deplase machin yo soti nan liy kote machin ap pase yo","Kondi al lakay ou san w pa pale ak pèsonn","Kanpe nan mitan wout la pou dirije sikilasyon an"],"h1":"Bloke sikilasyon an ka lakòz yon dezyèm aksidan.","h2":"Si pèsonn pa blese epi machin yo ka woule, deplase yo soti nan liy kote machin ap pase yo pou ale nan yon kote ki an sekirite, epi apre sa, echanje enfòmasyon.","p":"Se sa. Si pèsonn pa blese, deplase machin yo soti nan sikilasyon an."},"ref":{"doc":"FL","page":77}},{"id":"licensing-026","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, after a crash, what information must you give to the other driver?","o":["Only your phone number","Your bank account number","Nothing, unless they are hurt","Your name, address, and vehicle registration, and show your license"],"h1":"The other driver needs to know who you are and which car was involved.","h2":"After a crash, you must give your name, address, and vehicle registration number, and show your driver license to the other driver.","p":"Right. Share your name, address, registration, and license."},"es":{"q":"En Florida, después de un choque, ¿qué información debe darle al otro conductor?","o":["Solo su número de teléfono","Su número de cuenta bancaria","Nada, a menos que esté herido","Su nombre, dirección y registro del vehículo, y mostrar su licencia"],"h1":"El otro conductor necesita saber quién es usted y qué carro estuvo involucrado.","h2":"Después de un choque, usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de conducir al otro conductor.","p":"Correcto. Dé su nombre, dirección, registro y licencia."},"zh":{"q":"在 Florida，车祸后你必须给另一位司机什么资料？","o":["只给你的电话号码","你的银行账号","什么都不用给，除非他受伤","你的姓名、地址和车辆登记，并出示你的驾照"],"h1":"另一位司机需要知道你是谁，以及是哪辆车。","h2":"车祸后，你必须把你的姓名、地址和车辆登记号码告诉另一位司机，并给他看你的驾照。","p":"对。告诉对方你的姓名、地址、车辆登记，并出示驾照。"},"vi":{"q":"Ở Florida, sau tai nạn, bạn phải đưa thông tin gì cho tài xế kia?","o":["Chỉ số điện thoại của bạn","Số tài khoản ngân hàng của bạn","Không đưa gì, trừ khi họ bị thương","Tên, địa chỉ, giấy đăng ký xe của bạn, và cho xem bằng lái"],"h1":"Tài xế kia cần biết bạn là ai và xe nào liên quan.","h2":"Sau tai nạn, bạn phải đưa tên, địa chỉ, và số đăng ký xe của bạn, và cho tài xế kia xem bằng lái của bạn.","p":"Đúng. Đưa tên, địa chỉ, giấy đăng ký xe, và bằng lái."},"tl":{"q":"Sa Florida, pagkatapos ng banggaan, anong impormasyon ang dapat mong ibigay sa kabilang driver?","o":["Ang phone number mo lang","Ang bank account number mo","Wala, maliban kung nasaktan siya","Ang pangalan, address, at vehicle registration mo, at ipakita ang lisensya mo"],"h1":"Kailangang malaman ng kabilang driver kung sino ka at kung aling kotse ang nasangkot.","h2":"Pagkatapos ng banggaan, dapat mong ibigay ang pangalan, address, at vehicle registration number mo, at ipakita ang iyong driver license sa kabilang driver.","p":"Tama. Ibigay ang pangalan, address, registration, at lisensya mo."},"ar":{"q":"في Florida، بعد حادث، ما المعلومات التي يجب أن تعطيها للسائق الآخر؟","o":["رقم هاتفك فقط","رقم حسابك في البنك","لا شيء، إلا إذا أصيب","اسمك وعنوانك وتسجيل السيارة، وأن تُظهر رخصتك"],"h1":"السائق الآخر يحتاج أن يعرف من أنت وأي سيارة كانت في الحادث.","h2":"بعد الحادث، يجب أن تعطي السائق الآخر اسمك وعنوانك ورقم تسجيل السيارة، وأن تُظهر له رخصة القيادة.","p":"صحيح. أعطِ اسمك وعنوانك وتسجيل السيارة ورخصتك."},"ht":{"q":"Nan Florida, apre yon aksidan, ki enfòmasyon ou dwe bay lòt chofè a?","o":["Nimewo telefòn ou sèlman","Nimewo kont labank ou","Anyen, sof si li blese","Non ou, adrès ou, ak anrejistreman machin nan, epi montre lisans ou"],"h1":"Lòt chofè a bezwen konnen kiyès ou ye ak ki machin ki te nan aksidan an.","h2":"Apre yon aksidan, ou dwe bay lòt chofè a non ou, adrès ou, ak nimewo anrejistreman machin nan, epi montre l lisans kondi ou.","p":"Se sa. Bay non ou, adrès ou, anrejistreman an, ak lisans ou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-027","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you had a crash, and the law did not require a police report. What must you do?","o":["Send a written crash report to the state within 10 days","Do nothing at all","Report it only when you renew your license","Wait a year, then report it"],"h1":"When no officer writes a report, the job falls to you, and there is a short deadline.","h2":"If no police report was required for your crash, you must send your own written crash report to the state within 10 days.","p":"Right. Send your own crash report within 10 days."},"es":{"q":"En Florida, usted tuvo un choque y la ley no exigía un reporte de la policía. ¿Qué debe hacer?","o":["Enviar un reporte escrito del choque al estado dentro de 10 días","No hacer nada","Reportarlo solo cuando renueve la licencia","Esperar un año y luego reportarlo"],"h1":"Cuando ningún oficial hace el reporte, la tarea es suya, y el plazo es corto.","h2":"Si su choque no necesitaba un reporte de la policía, usted debe enviar su propio reporte escrito del choque al estado dentro de 10 días.","p":"Correcto. Envíe su propio reporte del choque dentro de 10 días."},"zh":{"q":"在 Florida，你发生了车祸，法律没有要求警察报告。你必须做什么？","o":["10 天内向州政府寄一份书面车祸报告","什么都不用做","只在更新驾照时报告","等一年再报告"],"h1":"没有警察写报告时，这件事就由你来做，而且期限很短。","h2":"如果你的车祸不需要警察报告，你必须在 10 天内自己向州政府寄一份书面车祸报告。","p":"对。10 天内寄出你自己的车祸报告。"},"vi":{"q":"Ở Florida, bạn bị tai nạn, và luật không yêu cầu cảnh sát lập biên bản. Bạn phải làm gì?","o":["Gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày","Không cần làm gì cả","Chỉ báo khi gia hạn bằng lái","Đợi một năm rồi mới báo"],"h1":"Khi không có cảnh sát lập biên bản, việc này là của bạn, và thời hạn rất ngắn.","h2":"Nếu tai nạn của bạn không cần cảnh sát lập biên bản, bạn phải tự gửi bản báo cáo tai nạn bằng văn bản cho tiểu bang trong vòng 10 ngày.","p":"Đúng. Tự gửi báo cáo tai nạn trong vòng 10 ngày."},"tl":{"q":"Sa Florida, nagkaroon ka ng banggaan, at hindi hinihingi ng batas ang police report. Ano ang dapat mong gawin?","o":["Magpadala ng nakasulat na crash report sa estado sa loob ng 10 araw","Wala kang kailangang gawin","I-report lang ito kapag nagre-renew ka ng lisensya","Maghintay ng isang taon, saka i-report"],"h1":"Kapag walang pulis na gumawa ng report, ikaw ang may tungkulin, at maikli ang deadline.","h2":"Kung hindi kailangan ang police report para sa banggaan mo, dapat kang magpadala ng sarili mong nakasulat na crash report sa estado sa loob ng 10 araw.","p":"Tama. Magpadala ng sarili mong crash report sa loob ng 10 araw."},"ar":{"q":"في Florida، وقع لك حادث، والقانون لم يطلب تقريرًا من الشرطة. ماذا يجب أن تفعل؟","o":["أرسل تقريرًا مكتوبًا عن الحادث إلى الولاية خلال 10 أيام","لا تفعل أي شيء","بلّغ فقط عندما تجدد رخصتك","انتظر سنة ثم بلّغ"],"h1":"عندما لا يكتب الشرطي تقريرًا، تصبح المهمة عليك، والمهلة قصيرة.","h2":"إذا لم يكن تقرير الشرطة مطلوبًا لحادثك، يجب أن ترسل تقريرك المكتوب عن الحادث إلى الولاية خلال 10 أيام.","p":"صحيح. أرسل تقريرك عن الحادث خلال 10 أيام."},"ht":{"q":"Nan Florida, ou te fè yon aksidan, epi lalwa pa t mande yon rapò lapolis. Kisa ou dwe fè?","o":["Voye yon rapò aksidan ekri bay leta nan 10 jou","Pa fè anyen ditou","Deklare l sèlman lè w ap renouvle lisans ou","Tann yon ane, epi deklare l"],"h1":"Lè pa gen polis ki ekri yon rapò, se ou ki gen travay la, epi ou pa gen anpil tan.","h2":"Si yo pa t mande yon rapò lapolis pou aksidan ou a, ou dwe voye pwòp rapò aksidan ekri pa w bay leta nan 10 jou.","p":"Se sa. Voye pwòp rapò aksidan pa w nan 10 jou."},"ref":{"doc":"FL","page":77}},{"id":"licensing-028","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what does the implied consent law mean?","o":["You must agree to let police search your phone","You agree to pay any ticket without going to court","By driving, you agree to be tested for alcohol or drugs if lawfully arrested","Your passengers agree to be tested too"],"h1":"You gave this agreement when you accepted your driver license.","h2":"Implied consent means that by driving in Florida, you agree to take a breath, blood, or urine test if you are lawfully arrested for impaired driving.","p":"Right. Driving means you agree to alcohol and drug testing."},"es":{"q":"En Florida, ¿qué significa la ley de consentimiento implícito?","o":["Debe permitir que la policía revise su teléfono","Acepta pagar cualquier multa sin ir a la corte","Al manejar, usted acepta hacerse pruebas de alcohol o drogas si lo arrestan legalmente","Sus pasajeros también aceptan hacerse pruebas"],"h1":"Usted dio este acuerdo cuando aceptó su licencia de conducir.","h2":"Consentimiento implícito significa que, al manejar en Florida, usted acepta hacerse una prueba de aliento, sangre u orina si lo arrestan legalmente por manejar bajo los efectos.","p":"Correcto. Manejar significa aceptar las pruebas de alcohol y drogas."},"zh":{"q":"在 Florida，“默示同意”法律是什么意思？","o":["你必须同意让警察搜查你的手机","你同意不上法庭就交任何罚单","只要开车，就表示你同意在被合法逮捕时接受酒精或毒品检测","你的乘客也同意接受检测"],"h1":"你在接受驾照时就已经做了这个同意。","h2":"默示同意的意思是：在 Florida 开车，就表示你同意在因酒后或药后驾驶被合法逮捕时，接受呼气、血液或尿液检测。","p":"对。开车就表示你同意接受酒精和毒品检测。"},"vi":{"q":"Ở Florida, luật đồng ý ngầm định (implied consent) có nghĩa là gì?","o":["Bạn phải đồng ý cho cảnh sát lục soát điện thoại của bạn","Bạn đồng ý trả mọi giấy phạt mà không ra tòa","Khi lái xe, bạn đồng ý được kiểm tra rượu bia hoặc ma túy nếu bị bắt hợp pháp","Hành khách của bạn cũng đồng ý được kiểm tra"],"h1":"Bạn đã đưa ra sự đồng ý này khi nhận bằng lái.","h2":"Luật đồng ý ngầm định có nghĩa là khi lái xe ở Florida, bạn đồng ý làm xét nghiệm hơi thở, máu, hoặc nước tiểu nếu bạn bị bắt hợp pháp vì lái xe khi bị ảnh hưởng.","p":"Đúng. Lái xe nghĩa là bạn đồng ý được kiểm tra rượu bia và ma túy."},"tl":{"q":"Sa Florida, ano ang ibig sabihin ng implied consent law?","o":["Dapat kang pumayag na halughugin ng pulis ang phone mo","Pumapayag kang magbayad ng kahit anong ticket nang hindi pumupunta sa korte","Sa pagmamaneho, pumapayag kang ma-test para sa alak o droga kung legal kang inaresto","Pumapayag din ang mga pasahero mo na ma-test"],"h1":"Ibinigay mo ang pagpayag na ito nang tanggapin mo ang iyong driver license.","h2":"Ang implied consent ay nangangahulugang sa pagmamaneho sa Florida, pumapayag kang kumuha ng breath, blood, o urine test kung legal kang inaresto dahil sa impaired driving.","p":"Tama. Ang pagmamaneho ay nangangahulugang pumapayag ka sa test para sa alak at droga."},"ar":{"q":"في Florida، ما معنى قانون الموافقة الضمنية؟","o":["يجب أن توافق على أن تفتش الشرطة هاتفك","توافق على دفع أي مخالفة بدون الذهاب إلى المحكمة","بمجرد أنك تقود، أنت توافق على فحص الكحول أو المخدرات إذا اعتُقلت بشكل قانوني","الركاب معك يوافقون على الفحص أيضًا"],"h1":"أنت أعطيت هذه الموافقة عندما قبلت رخصة القيادة.","h2":"الموافقة الضمنية تعني أنك بمجرد أن تقود في Florida، توافق على فحص النَّفَس أو الدم أو البول إذا اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير.","p":"صحيح. القيادة تعني أنك توافق على فحص الكحول والمخدرات."},"ht":{"q":"Nan Florida, kisa lwa konsantman enplisit la (implied consent) vle di?","o":["Ou dwe kite lapolis fouye telefòn ou","Ou dakò peye nenpòt kontravansyon san w pa al nan tribinal","Lè ou kondi, ou dakò pou yo teste w pou alkòl oswa dwòg si yo arete w legalman","Pasaje ou yo dakò pou yo teste yo tou"],"h1":"Ou te bay akò sa a lè ou te aksepte lisans kondi ou.","h2":"Konsantman enplisit vle di ke lè ou kondi nan Florida, ou dakò pran yon tès souf, san, oswa pipi si yo arete w legalman paske ou t ap kondi sou enfliyans.","p":"Se sa. Lè ou kondi, ou dakò pou yo teste w pou alkòl ak dwòg."},"ref":{"doc":"FL","page":25}},{"id":"licensing-029","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what happens the first time you refuse a lawful breath, blood, or urine test?","o":["Nothing, refusing is your right","Your license is suspended for 1 year","Your license is suspended for 10 days","You get a warning only"],"h1":"Refusing has a cost, even if you were not proven drunk.","h2":"If you refuse a lawful test for the first time, your license is suspended for 1 year.","p":"Right. A first refusal means a 1-year suspension."},"es":{"q":"En Florida, ¿qué pasa la primera vez que se niega a una prueba legal de aliento, sangre u orina?","o":["Nada, negarse es su derecho","Le suspenden la licencia por 1 año","Le suspenden la licencia por 10 días","Solo recibe una advertencia"],"h1":"Negarse tiene un costo, aunque no se pruebe que estaba borracho.","h2":"Si se niega por primera vez a una prueba legal, le suspenden la licencia por 1 año.","p":"Correcto. La primera negativa significa 1 año de suspensión."},"zh":{"q":"在 Florida，你第一次拒绝合法的呼气、血液或尿液检测，会怎么样？","o":["什么事也没有，拒绝是你的权利","你的驾照被暂停 1 年","你的驾照被暂停 10 天","你只会收到警告"],"h1":"拒绝是有代价的，即使没有证明你喝醉了。","h2":"如果你第一次拒绝合法的检测，你的驾照会被暂停 1 年。","p":"对。第一次拒绝，驾照暂停 1 年。"},"vi":{"q":"Ở Florida, điều gì xảy ra lần đầu tiên bạn từ chối xét nghiệm hơi thở, máu, hoặc nước tiểu hợp pháp?","o":["Không có gì, từ chối là quyền của bạn","Bằng lái của bạn bị đình chỉ 1 năm","Bằng lái của bạn bị đình chỉ 10 ngày","Bạn chỉ bị cảnh cáo"],"h1":"Từ chối sẽ có hậu quả, dù chưa chứng minh được bạn say.","h2":"Nếu bạn từ chối xét nghiệm hợp pháp lần đầu, bằng lái của bạn bị đình chỉ 1 năm.","p":"Đúng. Từ chối lần đầu nghĩa là bị đình chỉ 1 năm."},"tl":{"q":"Sa Florida, ano ang mangyayari sa unang beses na tumanggi ka sa legal na breath, blood, o urine test?","o":["Wala, karapatan mong tumanggi","Masususpinde ang lisensya mo nang 1 taon","Masususpinde ang lisensya mo nang 10 araw","Warning lang ang makukuha mo"],"h1":"May kapalit ang pagtanggi, kahit hindi napatunayang lasing ka.","h2":"Kung tumanggi ka sa legal na test sa unang beses, masususpinde ang lisensya mo nang 1 taon.","p":"Tama. Ang unang pagtanggi ay suspensyon nang 1 taon."},"ar":{"q":"في Florida، ماذا يحدث في المرة الأولى التي ترفض فيها فحصًا قانونيًا للنَّفَس أو الدم أو البول؟","o":["لا شيء، الرفض حقك","تُوقف رخصتك لمدة سنة واحدة","تُوقف رخصتك لمدة 10 أيام","تحصل على تحذير فقط"],"h1":"الرفض له ثمن، حتى إذا لم يثبت أنك كنت سكرانًا.","h2":"إذا رفضت فحصًا قانونيًا للمرة الأولى، تُوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة سنة واحدة."},"ht":{"q":"Nan Florida, kisa k rive premye fwa ou refize yon tès souf, san, oswa pipi ki legal?","o":["Anyen, ou gen dwa refize","Yo sispann lisans ou pou 1 an","Yo sispann lisans ou pou 10 jou","Ou jwenn yon avètisman sèlman"],"h1":"Refize gen yon pri, menm si yo pa pwouve ou te sou.","h2":"Si ou refize yon tès legal pou premye fwa, yo sispann lisans ou pou 1 an.","p":"Se sa. Yon premye refi vle di yon sispansyon 1 an."},"ref":{"doc":"FL","page":25}},{"id":"licensing-030","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you already refused a test once before. What happens if you refuse again?","o":["A 30-day suspension only","Nothing more than the first time","A small fine only","An 18-month suspension, and the refusal is a crime"],"h1":"A second refusal is treated more harshly than the first.","h2":"If your license was suspended before for refusing, a second refusal brings an 18-month suspension, and the refusal itself is a misdemeanor crime.","p":"Right. A second refusal means 18 months and a criminal charge."},"es":{"q":"En Florida, usted ya se negó a una prueba antes. ¿Qué pasa si se niega otra vez?","o":["Solo una suspensión de 30 días","Nada más que la primera vez","Solo una multa pequeña","Una suspensión de 18 meses, y negarse es un delito"],"h1":"La segunda negativa se castiga más fuerte que la primera.","h2":"Si antes le suspendieron la licencia por negarse, una segunda negativa trae una suspensión de 18 meses, y negarse es en sí un delito menor.","p":"Correcto. La segunda negativa significa 18 meses y un cargo criminal."},"zh":{"q":"在 Florida，你以前已经拒绝过一次检测。如果你再拒绝，会怎么样？","o":["只暂停 30 天","和第一次一样，不会更多","只有一小笔罚款","暂停 18 个月，而且拒绝本身就是犯罪"],"h1":"第二次拒绝会比第一次处罚得更重。","h2":"如果你以前因为拒绝检测被暂停过驾照，第二次拒绝会让驾照暂停 18 个月，而且拒绝本身就是轻罪。","p":"对。第二次拒绝，驾照暂停 18 个月，还会被刑事起诉。"},"vi":{"q":"Ở Florida, bạn đã từng từ chối xét nghiệm một lần. Điều gì xảy ra nếu bạn từ chối lần nữa?","o":["Chỉ bị đình chỉ 30 ngày","Không nặng hơn lần đầu","Chỉ bị phạt tiền nhỏ","Bị đình chỉ 18 tháng, và việc từ chối là một tội"],"h1":"Từ chối lần thứ hai bị xử nặng hơn lần đầu.","h2":"Nếu bằng lái của bạn đã từng bị đình chỉ vì từ chối, lần từ chối thứ hai sẽ bị đình chỉ 18 tháng, và chính việc từ chối là một tội nhẹ (misdemeanor).","p":"Đúng. Từ chối lần thứ hai nghĩa là 18 tháng và bị buộc tội hình sự."},"tl":{"q":"Sa Florida, tumanggi ka na sa test minsan noon. Ano ang mangyayari kung tumanggi ka ulit?","o":["Suspensyon nang 30 araw lang","Wala nang higit pa sa unang beses","Maliit na multa lang","Suspensyon nang 18 buwan, at krimen ang pagtanggi"],"h1":"Mas mabigat ang parusa sa pangalawang pagtanggi kaysa sa una.","h2":"Kung nasuspinde na ang lisensya mo dati dahil sa pagtanggi, ang pangalawang pagtanggi ay magdudulot ng suspensyon nang 18 buwan, at ang pagtanggi mismo ay krimen na misdemeanor.","p":"Tama. Ang pangalawang pagtanggi ay 18 buwan at kasong kriminal."},"ar":{"q":"في Florida، أنت رفضت فحصًا مرة من قبل. ماذا يحدث إذا رفضت مرة أخرى؟","o":["إيقاف لمدة 30 يومًا فقط","لا شيء أكثر من المرة الأولى","غرامة صغيرة فقط","إيقاف لمدة 18 شهرًا، والرفض يصبح جريمة"],"h1":"الرفض الثاني يُعامل بشدة أكبر من الأول.","h2":"إذا أوقفت رخصتك من قبل بسبب الرفض، فإن الرفض الثاني يؤدي إلى إيقاف لمدة 18 شهرًا، والرفض نفسه يصبح جنحة.","p":"صحيح. الرفض الثاني يعني 18 شهرًا وتهمة جنائية."},"ht":{"q":"Nan Florida, ou te deja refize yon tès yon fwa anvan. Kisa k rive si ou refize ankò?","o":["Yon sispansyon 30 jou sèlman","Anyen plis pase premye fwa a","Yon ti amann sèlman","Yon sispansyon 18 mwa, epi refi a se yon krim"],"h1":"Yo trete yon dezyèm refi pi di pase premye a.","h2":"Si yo te deja sispann lisans ou paske ou te refize, yon dezyèm refi pote yon sispansyon 18 mwa, epi refi a li menm se yon krim (misdemeanor).","p":"Se sa. Yon dezyèm refi vle di 18 mwa ak yon akizasyon kriminèl."},"ref":{"doc":"FL","page":26}},{"id":"licensing-031","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.08 or higher","0.02 or higher","0.04 or higher","0.15 or higher"],"h1":"This is the standard limit for adult drivers of regular cars.","h2":"A driver age 21 or older is driving under the influence with a blood alcohol level of 0.08 or higher, and can also be charged with less if impaired.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Florida, ¿a qué nivel de alcohol en la sangre se considera legalmente borracho a un conductor de 21 años o más?","o":["0.08 o más","0.02 o más","0.04 o más","0.15 o más"],"h1":"Es el límite normal para adultos que manejan carros comunes.","h2":"Un conductor de 21 años o más maneja bajo los efectos del alcohol con un nivel de 0.08 o más, y también puede recibir un cargo con menos si está afectado.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 Florida，21 岁或以上的司机，血液酒精浓度达到多少在法律上算醉酒？","o":["0.08 或更高","0.02 或更高","0.04 或更高","0.15 或更高"],"h1":"这是成年人开普通汽车的标准上限。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08 或更高，就是酒后驾驶；如果已经受到影响，浓度更低也可能被起诉。","p":"对。成年人的上限是 0.08。"},"vi":{"q":"Ở Florida, tài xế từ 21 tuổi trở lên bị coi là say theo luật khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.02 trở lên","0.04 trở lên","0.15 trở lên"],"h1":"Đây là giới hạn chuẩn cho người lớn lái xe thông thường.","h2":"Tài xế từ 21 tuổi trở lên bị coi là lái xe khi bị ảnh hưởng nếu nồng độ cồn trong máu từ 0.08 trở lên, và vẫn có thể bị buộc tội ở mức thấp hơn nếu khả năng lái bị suy giảm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa Florida, ang driver na 21 taong gulang o higit pa ay legal na lasing sa anong blood alcohol level?","o":["0.08 o higit pa","0.02 o higit pa","0.04 o higit pa","0.15 o higit pa"],"h1":"Ito ang karaniwang limit para sa mga adult na driver ng ordinaryong kotse.","h2":"Ang driver na 21 taong gulang o higit pa ay nagmamaneho nang lasing (DUI) kapag ang blood alcohol level niya ay 0.08 o higit pa, at puwede rin siyang makasuhan kahit mas mababa kung apektado na siya.","p":"Tama. Para sa mga adult, ang limit ay 0.08."},"ar":{"q":"في Florida، السائق الذي عمره 21 سنة أو أكثر يُعتبر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.04 أو أكثر","0.15 أو أكثر"],"h1":"هذا هو الحد العادي للسائقين البالغين في السيارات العادية.","h2":"السائق الذي عمره 21 سنة أو أكثر يقود تحت التأثير إذا كانت نسبة الكحول في دمه 0.08 أو أكثر، ويمكن أيضًا اتهامه بنسبة أقل إذا كانت قدرته على القيادة ضعيفة.","p":"صحيح. للبالغين، الحد هو 0.08."},"ht":{"q":"Nan Florida, a ki nivo alkòl nan san lalwa di yon chofè ki gen 21 an oswa plis sou?","o":["0.08 oswa plis","0.02 oswa plis","0.04 oswa plis","0.15 oswa plis"],"h1":"Sa a se limit nòmal pou granmoun k ap kondi machin òdinè.","h2":"Yon chofè ki gen 21 an oswa plis ap kondi sou enfliyans lè nivo alkòl nan san li se 0.08 oswa plis, epi yo ka akize l menm ak mwens si li pa an kondisyon pou kondi.","p":"Se sa. Pou granmoun, limit la se 0.08."},"ref":{"doc":"FL","page":25}},{"id":"licensing-032","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a driver under 21 can lose their license at what blood alcohol level?","o":["0.08 or higher","0.10 or higher","0.02 or higher","0.05 or higher"],"h1":"Drivers under 21 may not legally drink, so the limit is very low.","h2":"A driver under 21 with a blood alcohol level of 0.02 or higher will have their license suspended, because people under 21 may not drink at all.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Florida, ¿con qué nivel de alcohol en la sangre puede perder la licencia un conductor menor de 21?","o":["0.08 o más","0.10 o más","0.02 o más","0.05 o más"],"h1":"Los menores de 21 no pueden tomar alcohol legalmente, así que el límite es muy bajo.","h2":"A un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia, porque los menores de 21 no pueden tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Florida，21 岁以下的司机血液酒精浓度达到多少会失去驾照？","o":["0.08 或更高","0.10 或更高","0.02 或更高","0.05 或更高"],"h1":"21 岁以下的人在法律上不能喝酒，所以上限很低。","h2":"21 岁以下的司机，血液酒精浓度达到 0.02 或更高，驾照就会被暂停，因为 21 岁以下的人完全不能喝酒。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Florida, tài xế dưới 21 tuổi có thể mất bằng lái khi nồng độ cồn trong máu ở mức nào?","o":["0.08 trở lên","0.10 trở lên","0.02 trở lên","0.05 trở lên"],"h1":"Tài xế dưới 21 tuổi không được phép uống rượu bia theo luật, nên giới hạn rất thấp.","h2":"Tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên sẽ bị đình chỉ bằng lái, vì người dưới 21 tuổi hoàn toàn không được uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay puwedeng mawalan ng lisensya sa anong blood alcohol level?","o":["0.08 o higit pa","0.10 o higit pa","0.02 o higit pa","0.05 o higit pa"],"h1":"Bawal uminom ng alak ang mga driver na wala pang 21, kaya napakababa ng limit.","h2":"Ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya, dahil bawal talagang uminom ang mga taong wala pang 21.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Florida، السائق الذي عمره أقل من 21 سنة قد يخسر رخصته عند أي نسبة كحول في الدم؟","o":["0.08 أو أكثر","0.10 أو أكثر","0.02 أو أكثر","0.05 أو أكثر"],"h1":"السائقون تحت 21 سنة لا يُسمح لهم بشرب الكحول قانونيًا، لذلك الحد منخفض جدًا.","h2":"السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته، لأن من هم تحت 21 سنة لا يُسمح لهم بالشرب أبدًا.","p":"صحيح. تحت 21 سنة، الحد هو 0.02."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an ka pèdi lisans li a ki nivo alkòl nan san?","o":["0.08 oswa plis","0.10 oswa plis","0.02 oswa plis","0.05 oswa plis"],"h1":"Chofè ki poko gen 21 an pa gen dwa bwè alkòl dapre lalwa, kidonk limit la ba anpil.","h2":"Yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li, paske moun ki poko gen 21 an pa gen dwa bwè ditou.","p":"Se sa. Anba 21 an, limit la se 0.02."},"ref":{"doc":"FL","page":26}},{"id":"licensing-033","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what is the blood alcohol limit for someone driving a commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Commercial drivers have a stricter limit than regular adult drivers.","h2":"A person driving a commercial motor vehicle is over the limit at a blood alcohol level of 0.04, which is half the limit for regular adult drivers.","p":"Right. For commercial drivers, the limit is 0.04."},"es":{"q":"En Florida, ¿cuál es el límite de alcohol en la sangre para quien maneja un vehículo comercial?","o":["0.08","0.04","0.10","0.02"],"h1":"Los conductores comerciales tienen un límite más estricto que los adultos comunes.","h2":"Una persona que maneja un vehículo motorizado comercial pasa el límite con un nivel de alcohol de 0.04, que es la mitad del límite para adultos comunes.","p":"Correcto. Para conductores comerciales, el límite es 0.04."},"zh":{"q":"在 Florida，驾驶商用车辆的人，血液酒精浓度上限是多少？","o":["0.08","0.04","0.10","0.02"],"h1":"商用车司机的上限比普通成年司机更严格。","h2":"驾驶商用机动车的人，血液酒精浓度达到 0.04 就超过上限，这是普通成年司机上限的一半。","p":"对。商用车司机的上限是 0.04。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu cho người lái xe thương mại là bao nhiêu?","o":["0.08","0.04","0.10","0.02"],"h1":"Tài xế xe thương mại có giới hạn nghiêm hơn người lớn lái xe thông thường.","h2":"Người lái xe cơ giới thương mại bị coi là vượt giới hạn khi nồng độ cồn trong máu là 0.04, bằng một nửa giới hạn của người lớn lái xe thông thường.","p":"Đúng. Với tài xế xe thương mại, giới hạn là 0.04."},"tl":{"q":"Sa Florida, ano ang blood alcohol limit para sa taong nagmamaneho ng commercial vehicle?","o":["0.08","0.04","0.10","0.02"],"h1":"Mas mahigpit ang limit para sa mga commercial driver kaysa sa mga ordinaryong adult na driver.","h2":"Ang taong nagmamaneho ng commercial motor vehicle ay lampas na sa limit sa blood alcohol level na 0.04, na kalahati ng limit para sa mga ordinaryong adult na driver.","p":"Tama. Para sa mga commercial driver, ang limit ay 0.04."},"ar":{"q":"في Florida، ما حد الكحول في الدم لمن يقود مركبة تجارية؟","o":["0.08","0.04","0.10","0.02"],"h1":"سائقو المركبات التجارية لهم حد أشد من السائقين البالغين العاديين.","h2":"الشخص الذي يقود مركبة تجارية يكون فوق الحد عندما تصل نسبة الكحول في دمه إلى 0.04، وهذا نصف حد السائقين البالغين العاديين.","p":"صحيح. لسائقي المركبات التجارية، الحد هو 0.04."},"ht":{"q":"Nan Florida, ki limit alkòl nan san pou yon moun k ap kondi yon machin komèsyal?","o":["0.08","0.04","0.10","0.02"],"h1":"Chofè komèsyal yo gen yon limit ki pi sevè pase granmoun k ap kondi machin òdinè.","h2":"Yon moun k ap kondi yon machin komèsyal depase limit la lè nivo alkòl nan san li rive 0.04, sa ki mwatye limit pou granmoun k ap kondi machin òdinè.","p":"Se sa. Pou chofè komèsyal yo, limit la se 0.04."},"ref":{"doc":"FL","page":null}},{"id":"licensing-034","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver under 21 is found with a blood alcohol level of 0.02. What happens to the license the first time?","o":["It is suspended for 5 years","It is not affected","It is suspended for 1 week","It is suspended for 6 months"],"h1":"It is a real suspension, longer than a few weeks but shorter than a year.","h2":"For a first offense, a driver under 21 with a blood alcohol level of 0.02 or higher has the license suspended for 6 months.","p":"Right. The first time, the license is suspended for 6 months."},"es":{"q":"En Florida, un conductor menor de 21 tiene un nivel de alcohol de 0.02. ¿Qué pasa con su licencia la primera vez?","o":["Se la suspenden por 5 años","No le pasa nada","Se la suspenden por 1 semana","Se la suspenden por 6 meses"],"h1":"Es una suspensión real, más larga que unas semanas pero más corta que un año.","h2":"La primera vez, a un conductor menor de 21 con un nivel de alcohol de 0.02 o más le suspenden la licencia por 6 meses.","p":"Correcto. La primera vez, la licencia se suspende por 6 meses."},"zh":{"q":"在 Florida，一个 21 岁以下的司机被发现血液酒精浓度是 0.02。第一次会对驾照怎么样？","o":["暂停 5 年","没有影响","暂停 1 个星期","暂停 6 个月"],"h1":"这是真正的暂停，比几个星期长，但比一年短。","h2":"第一次违法时，21 岁以下、血液酒精浓度 0.02 或更高的司机，驾照会被暂停 6 个月。","p":"对。第一次，驾照暂停 6 个月。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi bị phát hiện có nồng độ cồn trong máu là 0.02. Lần đầu, bằng lái bị xử lý thế nào?","o":["Bị đình chỉ 5 năm","Không bị ảnh hưởng","Bị đình chỉ 1 tuần","Bị đình chỉ 6 tháng"],"h1":"Đây là đình chỉ thật sự, dài hơn vài tuần nhưng ngắn hơn một năm.","h2":"Với lần vi phạm đầu, tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên bị đình chỉ bằng lái 6 tháng.","p":"Đúng. Lần đầu, bằng lái bị đình chỉ 6 tháng."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 ay nakitaan ng blood alcohol level na 0.02. Ano ang mangyayari sa lisensya sa unang beses?","o":["Masususpinde ito nang 5 taon","Walang epekto rito","Masususpinde ito nang 1 linggo","Masususpinde ito nang 6 na buwan"],"h1":"Totoong suspensyon ito, mas mahaba sa ilang linggo pero mas maikli sa isang taon.","h2":"Sa unang offense, ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay masususpinde ang lisensya nang 6 na buwan.","p":"Tama. Sa unang beses, masususpinde ang lisensya nang 6 na buwan."},"ar":{"q":"في Florida، وُجد سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02. ماذا يحدث لرخصته في المرة الأولى؟","o":["تُوقف لمدة 5 سنوات","لا تتأثر","تُوقف لمدة أسبوع واحد","تُوقف لمدة 6 أشهر"],"h1":"إنه إيقاف حقيقي، أطول من بضعة أسابيع وأقصر من سنة.","h2":"في المخالفة الأولى، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر تُوقف رخصته لمدة 6 أشهر.","p":"صحيح. في المرة الأولى، تُوقف الرخصة لمدة 6 أشهر."},"ht":{"q":"Nan Florida, yo jwenn yon chofè ki poko gen 21 an ak yon nivo alkòl nan san 0.02. Kisa k rive lisans li premye fwa a?","o":["Yo sispann li pou 5 an","Pa gen anyen ki rive l","Yo sispann li pou 1 semèn","Yo sispann li pou 6 mwa"],"h1":"Se yon vrè sispansyon, pi long pase kèk semèn men pi kout pase yon ane.","h2":"Pou yon premye fwa, yon chofè ki poko gen 21 an ki gen yon nivo alkòl nan san 0.02 oswa plis ap wè yo sispann lisans li pou 6 mwa.","p":"Se sa. Premye fwa a, yo sispann lisans lan pou 6 mwa."},"ref":{"doc":"FL","page":26}},{"id":"licensing-035","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, who may have an open container of alcohol in a moving car?","o":["No one, not the driver and not the passengers","Only the passengers","Only the driver","Anyone over 21"],"h1":"The rule covers everyone inside a regular car.","h2":"In a regular car, neither the driver nor the passengers may have an open container of alcohol while the car is on the road.","p":"Right. No one in the car may have an open container."},"es":{"q":"En Florida, ¿quién puede tener un envase abierto de alcohol en un carro en movimiento?","o":["Nadie, ni el conductor ni los pasajeros","Solo los pasajeros","Solo el conductor","Cualquier persona mayor de 21"],"h1":"La regla aplica a todos los que van en un carro común.","h2":"En un carro común, ni el conductor ni los pasajeros pueden tener un envase abierto de alcohol mientras el carro está en la calle.","p":"Correcto. Nadie en el carro puede tener un envase abierto."},"zh":{"q":"在 Florida，在行驶的车里谁可以有打开的酒瓶或酒罐？","o":["没有人可以，司机和乘客都不行","只有乘客","只有司机","21 岁以上的任何人"],"h1":"这条规定适用于普通汽车里的每一个人。","h2":"在普通汽车里，车在路上时，司机和乘客都不能有打开的酒类容器。","p":"对。车里任何人都不能有打开的酒类容器。"},"vi":{"q":"Ở Florida, ai được để chai hoặc lon rượu bia đã mở trong xe đang chạy?","o":["Không ai cả, không phải tài xế và cũng không phải hành khách","Chỉ hành khách","Chỉ tài xế","Bất kỳ ai trên 21 tuổi"],"h1":"Quy định này áp dụng cho mọi người trong một chiếc xe thông thường.","h2":"Trong một chiếc xe thông thường, cả tài xế lẫn hành khách đều không được để chai hoặc lon rượu bia đã mở khi xe đang chạy trên đường.","p":"Đúng. Không ai trong xe được để rượu bia đã mở."},"tl":{"q":"Sa Florida, sino ang puwedeng may bukas na lalagyan ng alak sa umaandar na kotse?","o":["Wala, hindi ang driver at hindi ang mga pasahero","Ang mga pasahero lang","Ang driver lang","Kahit sino na lampas 21"],"h1":"Sakop ng patakaran ang lahat ng nasa loob ng ordinaryong kotse.","h2":"Sa ordinaryong kotse, hindi puwedeng may bukas na lalagyan ng alak ang driver o ang mga pasahero habang nasa daan ang kotse.","p":"Tama. Walang sinuman sa kotse ang puwedeng may bukas na lalagyan ng alak."},"ar":{"q":"في Florida، من يُسمح له بأن يكون معه وعاء كحول مفتوح في سيارة تسير؟","o":["لا أحد، لا السائق ولا الركاب","الركاب فقط","السائق فقط","أي شخص فوق 21 سنة"],"h1":"القاعدة تشمل كل من في داخل السيارة العادية.","h2":"في السيارة العادية، لا يُسمح للسائق ولا للركاب بأن يكون معهم وعاء كحول مفتوح عندما تكون السيارة على الطريق.","p":"صحيح. لا أحد في السيارة يُسمح له بوعاء كحول مفتوح."},"ht":{"q":"Nan Florida, kiyès ki gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri nan yon machin k ap woule?","o":["Pèsonn, ni chofè a ni pasaje yo","Pasaje yo sèlman","Chofè a sèlman","Nenpòt moun ki gen plis pase 21 an"],"h1":"Règ la kouvri tout moun ki andedan yon machin òdinè.","h2":"Nan yon machin òdinè, ni chofè a ni pasaje yo pa gen dwa gen yon boutèy oswa yon bwat alkòl ki louvri pandan machin nan sou wout la.","p":"Se sa. Pèsonn nan machin nan pa gen dwa gen alkòl ki louvri."},"ref":{"doc":"FL","page":null}},{"id":"licensing-036","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, who must wear a seat belt?","o":["Only the driver","Only children under 5","The driver, front-seat passengers, and all passengers under 18","Only people on the highway"],"h1":"Think about the front of the car and about young people anywhere in the car.","h2":"The driver and all front-seat passengers must wear seat belts, and every passenger under 18 must be buckled in any seat.","p":"Right. Driver, front seat, and everyone under 18 must buckle up."},"es":{"q":"En Florida, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los niños menores de 5","El conductor, los pasajeros de adelante y todos los pasajeros menores de 18","Solo las personas en la autopista"],"h1":"Piense en la parte de adelante del carro y en los jóvenes en cualquier asiento.","h2":"El conductor y todos los pasajeros del asiento de adelante deben usar el cinturón, y todo pasajero menor de 18 debe ir abrochado en cualquier asiento.","p":"Correcto. El conductor, los de adelante y todos los menores de 18 deben abrocharse."},"zh":{"q":"在 Florida，谁必须系安全带？","o":["只有司机","只有 5 岁以下的儿童","司机、前排乘客，以及所有 18 岁以下的乘客","只有在高速公路上的人"],"h1":"想一想车的前排，以及坐在车里任何位置的年轻人。","h2":"司机和所有前排乘客都必须系安全带，每一位 18 岁以下的乘客不管坐在哪里都必须系好。","p":"对。司机、前排乘客和所有 18 岁以下的人都必须系安全带。"},"vi":{"q":"Ở Florida, ai phải thắt dây an toàn?","o":["Chỉ tài xế","Chỉ trẻ em dưới 5 tuổi","Tài xế, hành khách ngồi ghế trước, và mọi hành khách dưới 18 tuổi","Chỉ người đi trên xa lộ"],"h1":"Hãy nghĩ đến phía trước xe và đến người trẻ ở bất kỳ chỗ nào trong xe.","h2":"Tài xế và mọi hành khách ngồi ghế trước phải thắt dây an toàn, và mọi hành khách dưới 18 tuổi phải thắt dây ở bất kỳ ghế nào.","p":"Đúng. Tài xế, ghế trước, và mọi người dưới 18 tuổi phải thắt dây an toàn."},"tl":{"q":"Sa Florida, sino ang dapat magsuot ng seat belt?","o":["Ang driver lang","Ang mga batang wala pang 5 lang","Ang driver, mga pasahero sa harap, at lahat ng pasaherong wala pang 18","Ang mga tao sa highway lang"],"h1":"Isipin ang harap ng kotse at ang mga kabataan kahit saan sa loob ng kotse.","h2":"Ang driver at lahat ng pasahero sa harap ay dapat magsuot ng seat belt, at bawat pasaherong wala pang 18 ay dapat naka-seat belt sa kahit anong upuan.","p":"Tama. Ang driver, ang nasa harap, at lahat ng wala pang 18 ay dapat naka-seat belt."},"ar":{"q":"في Florida، من يجب أن يربط حزام الأمان؟","o":["السائق فقط","الأطفال تحت 5 سنوات فقط","السائق، وركاب المقعد الأمامي، وكل الركاب تحت 18 سنة","الناس على الطريق السريع فقط"],"h1":"فكّر في مقدمة السيارة، وفي الصغار في أي مكان في السيارة.","h2":"يجب على السائق وكل ركاب المقعد الأمامي أن يربطوا حزام الأمان، ويجب على كل راكب تحت 18 سنة أن يربط الحزام في أي مقعد.","p":"صحيح. السائق، والمقعد الأمامي، وكل من هو تحت 18 سنة يجب أن يربطوا الحزام."},"ht":{"q":"Nan Florida, kiyès ki dwe mete senti sekirite?","o":["Chofè a sèlman","Timoun ki poko gen 5 an sèlman","Chofè a, pasaje ki chita devan yo, ak tout pasaje ki poko gen 18 an","Moun ki sou otowout sèlman"],"h1":"Panse ak devan machin nan, epi ak jèn moun ki nenpòt kote nan machin nan.","h2":"Chofè a ak tout pasaje ki chita devan dwe mete senti sekirite, epi chak pasaje ki poko gen 18 an dwe mete senti l sou nenpòt chèz.","p":"Se sa. Chofè a, moun devan yo, ak tout moun ki poko gen 18 an dwe mete senti."},"ref":{"doc":"FL","page":27}},{"id":"licensing-037","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how must a child age 3 or younger ride in a car?","o":["On an adult's lap","In a separate child carrier or a car's built-in child seat","With only a regular seat belt","In any seat without a belt"],"h1":"The youngest children need the most protection.","h2":"A child age 3 or younger must ride in a separate crash-tested child carrier or in a child seat built into the car.","p":"Right. Children 3 and under need a child carrier or built-in seat."},"es":{"q":"En Florida, ¿cómo debe viajar en el carro un niño de 3 años o menos?","o":["En las piernas de un adulto","En un asiento para niños aparte o en un asiento para niños integrado al carro","Solo con un cinturón de seguridad normal","En cualquier asiento sin cinturón"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"Un niño de 3 años o menos debe viajar en un asiento para niños aparte, probado contra choques, o en un asiento para niños integrado al carro.","p":"Correcto. Los niños de 3 años o menos necesitan un asiento para niños."},"zh":{"q":"在 Florida，3 岁或以下的儿童坐车必须怎么坐？","o":["坐在大人腿上","坐在单独的儿童安全座椅里，或车上内置的儿童座椅里","只用普通安全带","坐在任何座位，不系安全带"],"h1":"年龄最小的孩子需要最多的保护。","h2":"3 岁或以下的儿童必须坐在单独的、经过碰撞测试的儿童安全座椅里，或车上内置的儿童座椅里。","p":"对。3 岁及以下的儿童需要儿童安全座椅或内置儿童座椅。"},"vi":{"q":"Ở Florida, trẻ em từ 3 tuổi trở xuống phải ngồi trong xe như thế nào?","o":["Ngồi trên đùi người lớn","Trong ghế an toàn trẻ em riêng hoặc ghế trẻ em gắn sẵn trong xe","Chỉ với dây an toàn thông thường","Ở bất kỳ ghế nào, không cần dây"],"h1":"Trẻ nhỏ nhất cần được bảo vệ nhiều nhất.","h2":"Trẻ em từ 3 tuổi trở xuống phải ngồi trong ghế an toàn trẻ em riêng đã được thử nghiệm va chạm, hoặc trong ghế trẻ em gắn sẵn trong xe.","p":"Đúng. Trẻ từ 3 tuổi trở xuống cần ghế an toàn trẻ em hoặc ghế gắn sẵn."},"tl":{"q":"Sa Florida, paano dapat sumakay sa kotse ang batang 3 taong gulang o mas bata?","o":["Sa kandungan ng adult","Sa hiwalay na child carrier o sa child seat na nakakabit na sa kotse","Sa ordinaryong seat belt lang","Sa kahit anong upuan nang walang seat belt"],"h1":"Ang pinakabatang mga bata ang nangangailangan ng pinakamalaking proteksyon.","h2":"Ang batang 3 taong gulang o mas bata ay dapat sumakay sa hiwalay na child carrier na na-crash test, o sa child seat na nakakabit na sa kotse.","p":"Tama. Ang mga batang 3 taon pababa ay nangangailangan ng child carrier o child seat na nakakabit sa kotse."},"ar":{"q":"في Florida، كيف يجب أن يركب الطفل الذي عمره 3 سنوات أو أقل في السيارة؟","o":["في حضن شخص بالغ","في مقعد أطفال منفصل أو في مقعد أطفال مدمج في السيارة","بحزام أمان عادي فقط","في أي مقعد بدون حزام"],"h1":"الأطفال الأصغر يحتاجون إلى أكثر حماية.","h2":"الطفل الذي عمره 3 سنوات أو أقل يجب أن يركب في مقعد أطفال منفصل مُختبَر في اختبارات التصادم، أو في مقعد أطفال مدمج في السيارة.","p":"صحيح. الأطفال بعمر 3 سنوات وأقل يحتاجون إلى مقعد أطفال منفصل أو مدمج."},"ht":{"q":"Nan Florida, kijan yon timoun ki gen 3 an oswa mwens dwe chita nan yon machin?","o":["Sou janm yon granmoun","Nan yon chèz timoun apa oswa nan yon chèz timoun ki fèt ladan machin nan","Ak yon senti sekirite òdinè sèlman","Sou nenpòt chèz san senti"],"h1":"Timoun ki pi piti yo bezwen plis pwoteksyon.","h2":"Yon timoun ki gen 3 an oswa mwens dwe chita nan yon chèz timoun apa ki te teste pou aksidan, oswa nan yon chèz timoun ki fèt ladan machin nan.","p":"Se sa. Timoun 3 an oswa mwens bezwen yon chèz timoun apa oswa yon chèz ki fèt ladan machin nan."},"ref":{"doc":"FL","page":28}},{"id":"licensing-038","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what may a child age 4 or 5 use in a car?","o":["Nothing, they may ride free","Only an adult's lap","Only the front seat with no belt","A child carrier, a built-in child seat, or a booster seat"],"h1":"Children this age have one more choice than younger children.","h2":"A child age 4 or 5 must use a separate child carrier, a built-in child seat, or a booster seat.","p":"Right. Ages 4 and 5 may use a car seat or a booster seat."},"es":{"q":"En Florida, ¿qué puede usar en el carro un niño de 4 o 5 años?","o":["Nada, puede ir suelto","Solo las piernas de un adulto","Solo el asiento de adelante sin cinturón","Un asiento para niños, un asiento integrado o un asiento elevador (booster)"],"h1":"Los niños de esta edad tienen una opción más que los niños más pequeños.","h2":"Un niño de 4 o 5 años debe usar un asiento para niños aparte, un asiento para niños integrado al carro o un asiento elevador.","p":"Correcto. A los 4 y 5 años se usa un asiento para niños o un asiento elevador."},"zh":{"q":"在 Florida，4 岁或 5 岁的儿童坐车可以用什么？","o":["什么都不用，可以随便坐","只能坐在大人腿上","只能坐前排，不系安全带","儿童安全座椅、内置儿童座椅或增高座椅"],"h1":"这个年龄的孩子比更小的孩子多一个选择。","h2":"4 岁或 5 岁的儿童必须使用单独的儿童安全座椅、内置儿童座椅或增高座椅。","p":"对。4 岁和 5 岁的儿童可以用儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Florida, trẻ em 4 hoặc 5 tuổi được dùng gì trong xe?","o":["Không cần gì, trẻ được ngồi tự do","Chỉ ngồi trên đùi người lớn","Chỉ ngồi ghế trước, không cần dây","Ghế an toàn trẻ em, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat)"],"h1":"Trẻ ở tuổi này có thêm một lựa chọn so với trẻ nhỏ hơn.","h2":"Trẻ em 4 hoặc 5 tuổi phải dùng ghế an toàn trẻ em riêng, ghế trẻ em gắn sẵn, hoặc ghế nâng (booster seat).","p":"Đúng. Trẻ 4 và 5 tuổi được dùng ghế an toàn trẻ em hoặc ghế nâng."},"tl":{"q":"Sa Florida, ano ang puwedeng gamitin ng batang 4 o 5 taong gulang sa kotse?","o":["Wala, puwede silang sumakay nang malaya","Kandungan lang ng adult","Upuan lang sa harap nang walang seat belt","Child carrier, child seat na nakakabit sa kotse, o booster seat"],"h1":"May isa pang pagpipilian ang mga batang ganito ang edad kaysa sa mas batang mga bata.","h2":"Ang batang 4 o 5 taong gulang ay dapat gumamit ng hiwalay na child carrier, child seat na nakakabit sa kotse, o booster seat.","p":"Tama. Ang edad 4 at 5 ay puwedeng gumamit ng car seat o booster seat."},"ar":{"q":"في Florida، ماذا يمكن أن يستعمل الطفل الذي عمره 4 أو 5 سنوات في السيارة؟","o":["لا شيء، يمكنه الركوب بحرية","حضن شخص بالغ فقط","المقعد الأمامي فقط بدون حزام","مقعد أطفال منفصل، أو مقعد أطفال مدمج، أو مقعد رافع (booster)"],"h1":"الأطفال في هذا العمر لهم خيار واحد إضافي مقارنة بالأطفال الأصغر.","h2":"الطفل الذي عمره 4 أو 5 سنوات يجب أن يستعمل مقعد أطفال منفصلًا، أو مقعد أطفال مدمجًا، أو مقعدًا رافعًا (booster).","p":"صحيح. في عمر 4 و5 سنوات يمكن استعمال مقعد أطفال أو مقعد رافع."},"ht":{"q":"Nan Florida, kisa yon timoun 4 oswa 5 an ka itilize nan yon machin?","o":["Anyen, yo ka chita lib","Janm yon granmoun sèlman","Chèz devan an sèlman, san senti","Yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster"],"h1":"Timoun laj sa a gen yon chwa anplis pase timoun ki pi piti yo.","h2":"Yon timoun 4 oswa 5 an dwe itilize yon chèz timoun apa, yon chèz timoun ki fèt ladan machin nan, oswa yon chèz booster.","p":"Se sa. Timoun 4 ak 5 an ka itilize yon chèz timoun oswa yon chèz booster."},"ref":{"doc":"FL","page":28}},{"id":"licensing-039","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, can a police officer stop you just for texting while driving?","o":["Yes, texting while driving is a primary offense","No, only if you also break another law","No, texting while driving is legal","Only on interstate highways"],"h1":"Think about whether the officer needs a second reason to stop you.","h2":"Texting while driving is a primary offense in Florida, so an officer can stop you for texting alone.","p":"Right. You can be stopped just for texting."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo por enviar mensajes de texto mientras maneja?","o":["Sí, enviar textos mientras maneja es una infracción primaria","No, solo si también viola otra ley","No, enviar textos mientras maneja es legal","Solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita una segunda razón para detenerlo.","h2":"Enviar textos mientras maneja es una infracción primaria en Florida, así que un oficial puede detenerlo solo por eso.","p":"Correcto. Lo pueden detener solo por enviar textos."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["可以，开车发短信是主要违法行为","不可以，除非你也违反了别的法律","不可以，开车发短信是合法的","只在州际高速公路上可以"],"h1":"想一想警察是否需要第二个理由才能让你停车。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为你发短信就可以让你停车。","p":"对。只因为发短信，你就可能被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Có, nhắn tin khi lái xe là vi phạm chính (primary offense)","Không, chỉ khi bạn vi phạm thêm luật khác","Không, nhắn tin khi lái xe là hợp pháp","Chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem cảnh sát có cần thêm lý do thứ hai để chặn xe bạn không.","h2":"Nhắn tin khi lái xe là vi phạm chính ở Florida, nên cảnh sát có thể chặn xe bạn chỉ vì nhắn tin.","p":"Đúng. Bạn có thể bị chặn xe chỉ vì nhắn tin."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Oo, ang pag-text habang nagmamaneho ay primary offense","Hindi, kung may iba ka lang ding nilabag na batas","Hindi, legal ang pag-text habang nagmamaneho","Sa interstate highway lang"],"h1":"Isipin kung kailangan pa ng pulis ng pangalawang dahilan para parahin ka.","h2":"Ang pag-text habang nagmamaneho ay primary offense sa Florida, kaya puwede kang parahin ng pulis dahil lang sa pag-text.","p":"Tama. Puwede kang parahin dahil lang sa pag-text."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["نعم، كتابة الرسائل أثناء القيادة مخالفة أساسية","لا، فقط إذا خالفت قانونًا آخر أيضًا","لا، كتابة الرسائل أثناء القيادة مسموحة","فقط على الطرق السريعة بين الولايات"],"h1":"فكّر: هل يحتاج الشرطي إلى سبب ثانٍ ليوقفك؟","h2":"كتابة الرسائل أثناء القيادة مخالفة أساسية في Florida، لذلك يمكن للشرطي أن يوقفك بسبب كتابة الرسائل وحدها.","p":"صحيح. يمكن أن يوقفوك فقط بسبب كتابة الرسائل."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Wi, voye tèks pandan w ap kondi se yon enfraksyon prensipal","Non, sèlman si ou vyole yon lòt lwa tou","Non, voye tèks pandan w ap kondi pa kont lalwa","Sèlman sou otowout entèeta yo"],"h1":"Panse si polis la bezwen yon dezyèm rezon pou l kanpe w.","h2":"Voye tèks pandan w ap kondi se yon enfraksyon prensipal nan Florida, kidonk yon polis ka kanpe w sèlman paske w ap voye tèks.","p":"Se sa. Yo ka kanpe w sèlman paske w ap voye tèks."},"ref":{"doc":"FL","page":null}},{"id":"licensing-040","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how may you use a phone while driving in a school zone or an active work zone?","o":["Holding it in your hand","Only to read texts","Only hands-free","Any way you want"],"h1":"In these zones, your hands must stay off the phone.","h2":"In a school zone or an active work zone, you may not hold a phone in your hand, so you may use it only in hands-free mode.","p":"Right. In school and work zones, phones must be hands-free."},"es":{"q":"En Florida, ¿cómo puede usar el teléfono mientras maneja en una zona escolar o en una zona de construcción activa?","o":["Sosteniéndolo en la mano","Solo para leer mensajes","Solo con manos libres","Como usted quiera"],"h1":"En estas zonas, sus manos no deben tocar el teléfono.","h2":"En una zona escolar o en una zona de construcción activa, no puede tener el teléfono en la mano, así que solo puede usarlo con manos libres.","p":"Correcto. En zonas escolares y de construcción, el teléfono debe ser de manos libres."},"zh":{"q":"在 Florida，在学校区域或正在施工的工作区开车时，你可以怎样用手机？","o":["拿在手里","只能看短信","只能免提","想怎么用就怎么用"],"h1":"在这些区域，你的手不能碰手机。","h2":"在学校区域或正在施工的工作区，你不能手里拿着手机，所以只能用免提模式。","p":"对。在学校区域和工作区，手机只能免提。"},"vi":{"q":"Ở Florida, bạn được dùng điện thoại như thế nào khi lái xe trong khu vực trường học hoặc khu vực đang thi công?","o":["Cầm điện thoại trên tay","Chỉ để đọc tin nhắn","Chỉ ở chế độ rảnh tay (hands-free)","Dùng cách nào cũng được"],"h1":"Trong những khu vực này, tay bạn không được chạm vào điện thoại.","h2":"Trong khu vực trường học hoặc khu vực đang thi công, bạn không được cầm điện thoại trên tay, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học và thi công, điện thoại phải ở chế độ rảnh tay."},"tl":{"q":"Sa Florida, paano mo puwedeng gamitin ang phone habang nagmamaneho sa school zone o sa active work zone?","o":["Hawak ito sa kamay mo","Para magbasa lang ng text","Hands-free lang","Kahit anong paraan na gusto mo"],"h1":"Sa mga zone na ito, hindi dapat hawak ng mga kamay mo ang phone.","h2":"Sa school zone o sa active work zone, bawal hawakan ang phone sa kamay mo, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa mga school at work zone, dapat hands-free ang phone."},"ar":{"q":"في Florida، كيف يمكنك استعمال الهاتف أثناء القيادة في منطقة مدرسة أو منطقة أعمال نشطة؟","o":["وأنت تمسكه بيدك","لقراءة الرسائل فقط","بدون استعمال اليدين فقط","بأي طريقة تريدها"],"h1":"في هذه المناطق، يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"في منطقة المدرسة أو منطقة الأعمال النشطة، لا يُسمح لك بإمساك الهاتف بيدك، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في مناطق المدارس والأعمال، الهاتف بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, kijan ou ka itilize yon telefòn pandan w ap kondi nan yon zòn lekòl oswa nan yon zòn travay ki aktif?","o":["Kenbe l nan men ou","Sèlman pou li tèks","Sèlman san men (hands-free)","Jan ou vle"],"h1":"Nan zòn sa yo, men ou pa dwe touche telefòn nan.","h2":"Nan yon zòn lekòl oswa nan yon zòn travay ki aktif, ou pa gen dwa kenbe telefòn nan men ou, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan zòn lekòl ak zòn travay, telefòn nan dwe san men (hands-free)."},"ref":{"doc":"FL","page":34}},{"id":"licensing-041","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you move to a new home. How soon must you update the address on your license?","o":["Within 1 year","Within 30 days","Only at your next renewal","Within 6 months"],"h1":"There is a deadline of about one month.","h2":"When you move, you must update the address on your driver license within 30 days.","p":"Right. Update your address within 30 days."},"es":{"q":"En Florida, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar la dirección de su licencia?","o":["Dentro de 1 año","Dentro de 30 días","Solo en la próxima renovación","Dentro de 6 meses"],"h1":"Hay un plazo de más o menos un mes.","h2":"Cuando se muda, usted debe actualizar la dirección de su licencia de conducir dentro de 30 días.","p":"Correcto. Actualice su dirección dentro de 30 días."},"zh":{"q":"在 Florida，你搬了新家。你必须在多长时间内更新驾照上的地址？","o":["1 年内","30 天内","只在下次更新驾照时","6 个月内"],"h1":"期限大约是一个月。","h2":"你搬家后，必须在 30 天内更新驾照上的地址。","p":"对。30 天内更新你的地址。"},"vi":{"q":"Ở Florida, bạn chuyển đến nhà mới. Bạn phải cập nhật địa chỉ trên bằng lái trong bao lâu?","o":["Trong vòng 1 năm","Trong vòng 30 ngày","Chỉ khi gia hạn lần tới","Trong vòng 6 tháng"],"h1":"Có thời hạn khoảng một tháng.","h2":"Khi chuyển nhà, bạn phải cập nhật địa chỉ trên bằng lái trong vòng 30 ngày.","p":"Đúng. Cập nhật địa chỉ trong vòng 30 ngày."},"tl":{"q":"Sa Florida, lumipat ka sa bagong bahay. Gaano kabilis mo dapat palitan ang address sa lisensya mo?","o":["Sa loob ng 1 taon","Sa loob ng 30 araw","Sa susunod na renewal lang","Sa loob ng 6 na buwan"],"h1":"May deadline na mga isang buwan.","h2":"Kapag lumipat ka, dapat mong palitan ang address sa iyong driver license sa loob ng 30 araw.","p":"Tama. Palitan ang address mo sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تغيّر العنوان في رخصتك؟","o":["خلال سنة واحدة","خلال 30 يومًا","فقط عند التجديد القادم","خلال 6 أشهر"],"h1":"المهلة حوالي شهر واحد.","h2":"عندما تنتقل، يجب أن تغيّر العنوان في رخصة القيادة خلال 30 يومًا.","p":"صحيح. غيّر عنوانك خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou demenaje nan yon nouvo kay. Nan konbyen tan ou dwe chanje adrès ki sou lisans ou?","o":["Nan 1 an","Nan 30 jou","Sèlman lè w ap renouvle l pwochen fwa","Nan 6 mwa"],"h1":"Gen yon dènye dat ki se apeprè yon mwa.","h2":"Lè ou demenaje, ou dwe chanje adrès ki sou lisans kondi ou nan 30 jou.","p":"Se sa. Chanje adrès ou nan 30 jou."},"ref":{"doc":"FL","page":12}},{"id":"licensing-042","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, how long is a Class E license valid?","o":["2 years","4 years","20 years","6 to 8 years"],"h1":"It lasts many years, but not for life.","h2":"A Florida Class E license is valid for six to eight years, and then you must renew it.","p":"Right. A Class E license lasts six to eight years."},"es":{"q":"En Florida, ¿por cuánto tiempo es válida la licencia Clase E?","o":["2 años","4 años","20 años","De 6 a 8 años"],"h1":"Dura muchos años, pero no toda la vida.","h2":"La licencia Clase E de Florida es válida de seis a ocho años, y después usted debe renovarla.","p":"Correcto. La licencia Clase E dura de seis a ocho años."},"zh":{"q":"在 Florida，Class E 驾照的有效期是多久？","o":["2 年","4 年","20 年","6 到 8 年"],"h1":"它可以用很多年，但不是一辈子。","h2":"Florida 的 Class E 驾照有效期是六到八年，之后你必须更新。","p":"对。Class E 驾照有效六到八年。"},"vi":{"q":"Ở Florida, bằng lái Class E có giá trị trong bao lâu?","o":["2 năm","4 năm","20 năm","6 đến 8 năm"],"h1":"Bằng có giá trị nhiều năm, nhưng không phải suốt đời.","h2":"Bằng lái Class E ở Florida có giá trị từ sáu đến tám năm, sau đó bạn phải gia hạn.","p":"Đúng. Bằng lái Class E có giá trị từ sáu đến tám năm."},"tl":{"q":"Sa Florida, gaano katagal valid ang Class E license?","o":["2 taon","4 na taon","20 taon","6 hanggang 8 taon"],"h1":"Tumatagal ito nang maraming taon, pero hindi habambuhay.","h2":"Ang Florida Class E license ay valid nang anim hanggang walong taon, at pagkatapos ay dapat mo itong i-renew.","p":"Tama. Tumatagal ang Class E license nang anim hanggang walong taon."},"ar":{"q":"في Florida، كم مدة صلاحية رخصة Class E؟","o":["سنتان","4 سنوات","20 سنة","من 6 إلى 8 سنوات"],"h1":"إنها تبقى سنوات كثيرة، لكن ليس طوال الحياة.","h2":"رخصة Class E في Florida صالحة من ست إلى ثماني سنوات، ثم يجب أن تجددها.","p":"صحيح. رخصة Class E تبقى من ست إلى ثماني سنوات."},"ht":{"q":"Nan Florida, pandan konbyen tan yon lisans Class E bon?","o":["2 an","4 an","20 an","6 a 8 an"],"h1":"Li dire anpil ane, men se pa pou tout lavi.","h2":"Yon lisans Class E nan Florida bon pou sis a uit ane, epi apre sa ou dwe renouvle l.","p":"Se sa. Yon lisans Class E dire sis a uit ane."},"ref":{"doc":"FL","page":13}},{"id":"licensing-043","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what must a driver age 80 or older pass when renewing a license?","o":["A vision test","A new road test every time","A written essay","A physical fitness test"],"h1":"Think about the sense you use most to drive safely.","h2":"Drivers age 80 or older must pass a vision test each time they renew their license, because good eyesight is needed to drive safely.","p":"Right. Drivers 80 and older must pass a vision test to renew."},"es":{"q":"En Florida, ¿qué debe aprobar un conductor de 80 años o más al renovar la licencia?","o":["Un examen de la vista","Un nuevo examen de manejo cada vez","Un ensayo escrito","Una prueba de condición física"],"h1":"Piense en el sentido que más usa para manejar con seguridad.","h2":"Los conductores de 80 años o más deben aprobar un examen de la vista cada vez que renuevan la licencia, porque se necesita buena vista para manejar con seguridad.","p":"Correcto. Los conductores de 80 años o más deben aprobar el examen de la vista para renovar."},"zh":{"q":"在 Florida，80 岁或以上的司机更新驾照时必须通过什么？","o":["视力检查","每次都要新的路考","书面作文","体能测试"],"h1":"想一想你安全开车时用得最多的感官。","h2":"80 岁或以上的司机每次更新驾照都必须通过视力检查，因为安全开车需要好的视力。","p":"对。80 岁及以上的司机更新驾照必须通过视力检查。"},"vi":{"q":"Ở Florida, tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra nào khi gia hạn bằng lái?","o":["Bài kiểm tra mắt","Bài thi lái xe mới mỗi lần","Một bài luận viết","Bài kiểm tra thể lực"],"h1":"Hãy nghĩ đến giác quan bạn dùng nhiều nhất để lái xe an toàn.","h2":"Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt mỗi lần gia hạn bằng lái, vì cần có mắt tốt để lái xe an toàn.","p":"Đúng. Tài xế từ 80 tuổi trở lên phải đậu bài kiểm tra mắt để gia hạn."},"tl":{"q":"Sa Florida, ano ang dapat ipasa ng driver na 80 taong gulang o higit pa kapag nagre-renew ng lisensya?","o":["Vision test (pagsusuri ng mata)","Bagong road test sa bawat renewal","Nakasulat na sanaysay","Physical fitness test"],"h1":"Isipin ang pandama na pinakaginagamit mo para magmaneho nang ligtas.","h2":"Ang mga driver na 80 taong gulang o higit pa ay dapat pumasa sa vision test sa bawat pag-renew ng lisensya, dahil kailangan ang malinaw na paningin para magmaneho nang ligtas.","p":"Tama. Ang mga driver na 80 pataas ay dapat pumasa sa vision test para mag-renew."},"ar":{"q":"في Florida، ما الاختبار الذي يجب أن ينجح فيه السائق الذي عمره 80 سنة أو أكثر عند تجديد الرخصة؟","o":["اختبار النظر","اختبار قيادة جديد في كل مرة","مقال مكتوب","اختبار لياقة بدنية"],"h1":"فكّر في الحاسة التي تستعملها أكثر شيء لتقود بأمان.","h2":"السائقون الذين عمرهم 80 سنة أو أكثر يجب أن ينجحوا في اختبار النظر في كل مرة يجددون فيها الرخصة، لأن النظر الجيد ضروري للقيادة الآمنة.","p":"صحيح. السائقون بعمر 80 وأكثر يجب أن ينجحوا في اختبار النظر للتجديد."},"ht":{"q":"Nan Florida, kisa yon chofè ki gen 80 an oswa plis dwe pase lè l ap renouvle lisans li?","o":["Yon egzamen je","Yon nouvo egzamen sou wout la chak fwa","Yon redaksyon ekri","Yon tès fòm fizik"],"h1":"Panse ak sans ou itilize plis pou kondi san danje.","h2":"Chofè ki gen 80 an oswa plis dwe pase yon egzamen je chak fwa y ap renouvle lisans yo, paske ou bezwen wè byen pou kondi san danje.","p":"Se sa. Chofè 80 an oswa plis dwe pase yon egzamen je pou renouvle."},"ref":{"doc":"FL","page":14}},{"id":"licensing-044","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you just moved here and became a resident. How soon must you get a Florida driver license?","o":["Within 1 year","Only when your old license expires","Within 30 days","Within 90 days"],"h1":"New residents have about one month.","h2":"A new Florida resident must get a Florida driver license within 30 days of becoming a resident.","p":"Right. New residents must get a Florida license within 30 days."},"es":{"q":"En Florida, usted se acaba de mudar y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Florida?","o":["Dentro de 1 año","Solo cuando se venza su licencia anterior","Dentro de 30 días","Dentro de 90 días"],"h1":"Los residentes nuevos tienen más o menos un mes.","h2":"Un nuevo residente de Florida debe obtener una licencia de conducir de Florida dentro de 30 días después de hacerse residente.","p":"Correcto. Los residentes nuevos deben obtener la licencia de Florida dentro de 30 días."},"zh":{"q":"在 Florida，你刚搬来这里，成为居民。你必须在多长时间内拿到 Florida 驾照？","o":["1 年内","只在旧驾照过期时","30 天内","90 天内"],"h1":"新居民大约有一个月的时间。","h2":"Florida 的新居民必须在成为居民后 30 天内拿到 Florida 驾照。","p":"对。新居民必须在 30 天内拿到 Florida 驾照。"},"vi":{"q":"Ở Florida, bạn mới chuyển đến đây và trở thành cư dân. Bạn phải lấy bằng lái Florida trong bao lâu?","o":["Trong vòng 1 năm","Chỉ khi bằng lái cũ hết hạn","Trong vòng 30 ngày","Trong vòng 90 ngày"],"h1":"Cư dân mới có khoảng một tháng.","h2":"Cư dân mới của Florida phải lấy bằng lái Florida trong vòng 30 ngày kể từ khi trở thành cư dân.","p":"Đúng. Cư dân mới phải lấy bằng lái Florida trong vòng 30 ngày."},"tl":{"q":"Sa Florida, kalilipat mo lang dito at naging residente ka na. Gaano kabilis ka dapat kumuha ng Florida driver license?","o":["Sa loob ng 1 taon","Kapag nag-expire na lang ang luma mong lisensya","Sa loob ng 30 araw","Sa loob ng 90 araw"],"h1":"May mga isang buwan ang mga bagong residente.","h2":"Ang bagong residente ng Florida ay dapat kumuha ng Florida driver license sa loob ng 30 araw mula nang maging residente siya.","p":"Tama. Ang mga bagong residente ay dapat kumuha ng Florida license sa loob ng 30 araw."},"ar":{"q":"في Florida، انتقلت إلى هنا للتو وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Florida؟","o":["خلال سنة واحدة","فقط عندما تنتهي رخصتك القديمة","خلال 30 يومًا","خلال 90 يومًا"],"h1":"المقيمون الجدد لديهم حوالي شهر واحد.","h2":"المقيم الجديد في Florida يجب أن يحصل على رخصة قيادة من Florida خلال 30 يومًا من أن يصبح مقيمًا.","p":"صحيح. المقيمون الجدد يجب أن يحصلوا على رخصة Florida خلال 30 يومًا."},"ht":{"q":"Nan Florida, ou fèk vin rete isit la epi ou vin yon rezidan. Nan konbyen tan ou dwe jwenn yon lisans kondi Florida?","o":["Nan 1 an","Sèlman lè ansyen lisans ou a ekspire","Nan 30 jou","Nan 90 jou"],"h1":"Nouvo rezidan yo gen apeprè yon mwa.","h2":"Yon nouvo rezidan Florida dwe jwenn yon lisans kondi Florida nan 30 jou apre li vin rezidan.","p":"Se sa. Nouvo rezidan yo dwe jwenn yon lisans Florida nan 30 jou."},"ref":{"doc":"FL","page":3}},{"id":"licensing-045","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what kind of license do most people need to drive a regular car?","o":["A Class A license","A Class E license","A Class B license","A motorcycle endorsement"],"h1":"Classes A and B are for large commercial vehicles.","h2":"Most people need a Class E license to drive a regular car, because Classes A, B, and C are for commercial vehicles.","p":"Right. A regular car needs a Class E license."},"es":{"q":"En Florida, ¿qué tipo de licencia necesita la mayoría de las personas para manejar un carro común?","o":["Una licencia Clase A","Una licencia Clase E","Una licencia Clase B","Un endoso de motocicleta"],"h1":"Las Clases A y B son para vehículos comerciales grandes.","h2":"La mayoría de las personas necesita una licencia Clase E para manejar un carro común, porque las Clases A, B y C son para vehículos comerciales.","p":"Correcto. Un carro común requiere una licencia Clase E."},"zh":{"q":"在 Florida，大多数人开普通汽车需要哪种驾照？","o":["Class A 驾照","Class E 驾照","Class B 驾照","摩托车附加许可"],"h1":"Class A 和 Class B 是给大型商用车的。","h2":"大多数人开普通汽车需要 Class E 驾照，因为 Class A、B 和 C 是给商用车的。","p":"对。普通汽车需要 Class E 驾照。"},"vi":{"q":"Ở Florida, đa số người cần loại bằng lái nào để lái xe hơi thông thường?","o":["Bằng lái Class A","Bằng lái Class E","Bằng lái Class B","Chứng nhận lái xe máy"],"h1":"Class A và Class B dành cho xe thương mại lớn.","h2":"Đa số người cần bằng lái Class E để lái xe hơi thông thường, vì Class A, B và C dành cho xe thương mại.","p":"Đúng. Xe hơi thông thường cần bằng lái Class E."},"tl":{"q":"Sa Florida, anong klase ng lisensya ang kailangan ng karamihan para magmaneho ng ordinaryong kotse?","o":["Class A license","Class E license","Class B license","Motorcycle endorsement"],"h1":"Ang Class A at B ay para sa malalaking commercial vehicle.","h2":"Karamihan ng tao ay nangangailangan ng Class E license para magmaneho ng ordinaryong kotse, dahil ang Class A, B, at C ay para sa mga commercial vehicle.","p":"Tama. Ang ordinaryong kotse ay nangangailangan ng Class E license."},"ar":{"q":"في Florida، ما نوع الرخصة التي يحتاجها معظم الناس لقيادة سيارة عادية؟","o":["رخصة Class A","رخصة Class E","رخصة Class B","إضافة الدراجة النارية على الرخصة"],"h1":"الفئتان A وB للمركبات التجارية الكبيرة.","h2":"معظم الناس يحتاجون إلى رخصة Class E لقيادة سيارة عادية، لأن الفئات A وB وC للمركبات التجارية.","p":"صحيح. السيارة العادية تحتاج إلى رخصة Class E."},"ht":{"q":"Nan Florida, ki kalite lisans pifò moun bezwen pou kondi yon machin òdinè?","o":["Yon lisans Class A","Yon lisans Class E","Yon lisans Class B","Yon andòsman motosiklèt"],"h1":"Class A ak Class B se pou gwo machin komèsyal.","h2":"Pifò moun bezwen yon lisans Class E pou kondi yon machin òdinè, paske Class A, B, ak C se pou machin komèsyal.","p":"Se sa. Yon machin òdinè bezwen yon lisans Class E."},"ref":{"doc":"FL","page":4}},{"id":"licensing-046","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a Class E license lets you drive non-commercial vehicles up to what weight rating?","o":["Under 10,001 pounds","Under 16,001 pounds","Under 26,001 pounds","Under 36,001 pounds"],"h1":"Above this weight rating, you need a commercial license (CDL).","h2":"A Florida Class E license covers non-commercial vehicles with a weight rating under 26,001 pounds.","p":"Right. Class E covers vehicles under 26,001 pounds; heavier ones need a CDL."},"es":{"q":"En Florida, ¿hasta qué peso nominal le permite manejar vehículos no comerciales una licencia Clase E?","o":["Menos de 10,001 libras","Menos de 16,001 libras","Menos de 26,001 libras","Menos de 36,001 libras"],"h1":"Por encima de este peso nominal se necesita una licencia comercial (CDL).","h2":"En Florida, la licencia Clase E cubre vehículos no comerciales con un peso nominal de menos de 26,001 libras.","p":"Correcto. La Clase E cubre vehículos de menos de 26,001 libras; los más pesados requieren una CDL."},"ref":{"doc":"FL","page":4}},{"id":"licensing-047","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you need a motorcycle endorsement for a motorcycle whose engine is bigger than what size?","o":["50 cc","150 cc","250 cc","500 cc"],"h1":"It is a small number, the size of many scooter engines.","h2":"In Florida, you need a motorcycle endorsement, or a Motorcycle Only license, for any motorcycle with an engine over 50 cc.","p":"Right. Over 50 cc, you need a motorcycle endorsement."},"es":{"q":"En Florida, ¿a partir de qué tamaño de motor necesita un endoso de motocicleta?","o":["Más de 50 cc","Más de 150 cc","Más de 250 cc","Más de 500 cc"],"h1":"Es un número pequeño, del tamaño del motor de muchos scooters.","h2":"En Florida, necesita un endoso de motocicleta, o una licencia Solo Motocicleta, para cualquier motocicleta con motor de más de 50 cc.","p":"Correcto. Con más de 50 cc, necesita un endoso de motocicleta."},"ref":{"doc":"FL","page":4}},{"id":"licensing-048","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, what kind of identity documents must you bring to get a driver license?","o":["Clear photocopies of the papers","Copies signed by a notary","Photos of the papers on your phone","Original or certified documents"],"h1":"The office will not take copies of any kind.","h2":"Florida accepts only original or certified documents; photocopies and notarized copies are not accepted.","p":"Right. Bring original or certified documents, not copies."},"es":{"q":"En Florida, ¿qué tipo de documentos de identidad debe llevar para sacar una licencia de conducir?","o":["Fotocopias claras de los papeles","Copias firmadas por un notario","Fotos de los papeles en su teléfono","Documentos originales o certificados"],"h1":"La oficina no acepta copias de ningún tipo.","h2":"Florida solo acepta documentos originales o certificados; no acepta fotocopias ni copias notariadas.","p":"Correcto. Lleve documentos originales o certificados, no copias."},"ref":{"doc":"FL","page":5}},{"id":"licensing-049","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many documents showing your home address must you bring to get a driver license?","o":["One","Two","Three","None"],"h1":"One is not enough.","h2":"Every applicant for a Florida driver license or ID card must show two documents with their Florida home address.","p":"Right. You need two proofs of your Florida address."},"es":{"q":"En Florida, ¿cuántos documentos con la dirección de su casa debe llevar para sacar una licencia de conducir?","o":["Uno","Dos","Tres","Ninguno"],"h1":"Uno no es suficiente.","h2":"Toda persona que pide una licencia o tarjeta de identificación de Florida debe mostrar dos documentos con su dirección en Florida.","p":"Correcto. Necesita dos pruebas de su dirección en Florida."},"ref":{"doc":"FL","page":7}},{"id":"licensing-050","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a 15-year-old who is not married applies for a license. Where must a parent or guardian sign the application?","o":["At home, before the visit","Online, within 30 days","In front of a license agent or a notary","On the back of the test sheet"],"h1":"Someone official must watch the parent sign.","h2":"For an unmarried applicant under 18, a parent or legal guardian must sign the application in front of a driver license agent or a notary public.","p":"Right. The parent signs in front of a license agent or a notary."},"es":{"q":"En Florida, un joven de 15 años que no está casado pide una licencia. ¿Dónde debe firmar la solicitud el padre, la madre o el tutor?","o":["En casa, antes de la cita","En línea, dentro de 30 días","Frente a un agente de licencias o un notario","Al reverso de la hoja del examen"],"h1":"Una persona oficial debe ver firmar al padre o a la madre.","h2":"Si el solicitante es menor de 18 años y no está casado, el padre, la madre o el tutor legal debe firmar la solicitud frente a un agente de licencias o un notario público.","p":"Correcto. El padre o la madre firma frente a un agente de licencias o un notario."},"ref":{"doc":"FL","page":8}},{"id":"licensing-051","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, the parent who signed a teen's license application later withdraws that consent. What happens to the teen's license?","o":["It is canceled","It stays valid until age 18","It becomes a learner license","Nothing changes"],"h1":"The signer took responsibility for the teen's driving.","h2":"If the person who signed a minor's application takes back responsibility, the minor's license is canceled.","p":"Right. Without the signer's consent, the teen's license is canceled."},"es":{"q":"En Florida, el padre que firmó la solicitud de licencia de un adolescente después retira su permiso. ¿Qué pasa con la licencia del adolescente?","o":["Se cancela","Sigue válida hasta los 18 años","Se convierte en permiso de aprendiz","No cambia nada"],"h1":"Quien firmó aceptó la responsabilidad por el manejo del adolescente.","h2":"Si la persona que firmó la solicitud de un menor retira su responsabilidad, la licencia del menor se cancela.","p":"Correcto. Sin el permiso de quien firmó, la licencia del adolescente se cancela."},"ref":{"doc":"FL","page":9}},{"id":"licensing-052","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, your license shows restriction code B. What does it mean?","o":["You may drive only in daylight","You may drive only to work","You need hand controls","You must wear glasses or contacts"],"h1":"Think about what helps you see.","h2":"Restriction code B means you must wear corrective lenses, glasses or contacts, at all times while driving.","p":"Right. Code B means corrective lenses every time you drive."},"es":{"q":"En Florida, su licencia tiene el código de restricción B. ¿Qué significa?","o":["Solo puede manejar de día","Solo puede manejar al trabajo","Necesita controles manuales","Debe usar lentes o lentes de contacto"],"h1":"Piense en lo que le ayuda a ver.","h2":"El código de restricción B significa que debe usar lentes correctivos, anteojos o lentes de contacto, siempre que maneje.","p":"Correcto. El código B significa lentes correctivos cada vez que maneja."},"ref":{"doc":"FL","page":10}},{"id":"licensing-053","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what vision in each eye meets the state standard without a referral to an eye doctor?","o":["20/70 or better","20/40 or better","20/100 or better","20/200 or better"],"h1":"Worse than this, you are sent to an eye specialist.","h2":"Vision of 20/40 or better in each eye, with or without glasses, meets the Florida standard without a referral to an eye specialist.","p":"Right. 20/40 or better in each eye meets the standard."},"es":{"q":"En Florida, ¿qué visión en cada ojo cumple con el estándar del estado sin que lo envíen a un oculista?","o":["20/70 o mejor","20/40 o mejor","20/100 o mejor","20/200 o mejor"],"h1":"Si es peor que esto, lo envían a un especialista de la vista.","h2":"Una visión de 20/40 o mejor en cada ojo, con o sin lentes, cumple con el estándar de Florida sin que lo envíen a un especialista.","p":"Correcto. 20/40 o mejor en cada ojo cumple con el estándar."},"ref":{"doc":"FL","page":19}},{"id":"licensing-054","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, after how many days in the state during the last year must a car carry Florida PIP and PDL insurance?","o":["30 days","60 days","90 days","180 days"],"h1":"The days do not have to be in a row.","h2":"You must have Florida PIP and PDL insurance if your car has been in Florida for 90 days, in a row or not, during the last 365 days.","p":"Right. 90 days in the last year means you need Florida insurance."},"es":{"q":"En Florida, ¿después de cuántos días en el estado durante el último año debe tener un carro seguro PIP y PDL de Florida?","o":["30 días","60 días","90 días","180 días"],"h1":"Los días no tienen que ser seguidos.","h2":"Debe tener seguro PIP y PDL de Florida si su carro ha estado en Florida 90 días, seguidos o no, durante los últimos 365 días.","p":"Correcto. 90 días en el último año significa que necesita seguro de Florida."},"ref":{"doc":"FL","page":23}},{"id":"licensing-055","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, your license is suspended because you had no car insurance. May you get a temporary license to drive to work?","o":["No, not for any reason","Yes, for work only","Yes, after 10 days","Yes, if a parent signs"],"h1":"This suspension has no hardship exception.","h2":"If your license or plate is suspended for not having insurance, you cannot get a temporary license for any reason, not even to go to work.","p":"Right. No temporary license, not even for work."},"es":{"q":"En Florida, le suspendieron la licencia por no tener seguro de carro. ¿Puede obtener una licencia temporal para manejar al trabajo?","o":["No, por ningún motivo","Sí, solo para el trabajo","Sí, después de 10 días","Sí, si firma un padre"],"h1":"Esta suspensión no tiene excepción por necesidad.","h2":"Si le suspenden la licencia o la placa por no tener seguro, no puede obtener una licencia temporal por ningún motivo, ni siquiera para ir al trabajo.","p":"Correcto. No hay licencia temporal, ni siquiera para el trabajo."},"ref":{"doc":"FL","page":24}},{"id":"licensing-056","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you are convicted of running a red light. What must you complete to keep your license?","o":["A motorcycle safety course","A basic driver improvement course","A new knowledge test","A first aid class"],"h1":"It is a traffic school course.","h2":"After a conviction for running a red light, you must complete a basic driver improvement course to keep your Florida license.","p":"Right. Running a red light means a basic driver improvement course."},"es":{"q":"En Florida, lo declaran culpable de pasarse una luz roja. ¿Qué debe completar para conservar su licencia?","o":["Un curso de seguridad en motocicleta","Un curso básico para mejorar el manejo","Un nuevo examen de conocimientos","Una clase de primeros auxilios"],"h1":"Es un curso de escuela de tránsito.","h2":"Después de una condena por pasarse una luz roja, debe completar un curso básico para mejorar el manejo (basic driver improvement) para conservar su licencia de Florida.","p":"Correcto. Pasarse una luz roja significa un curso básico para mejorar el manejo."},"ref":{"doc":"FL","page":17}},{"id":"licensing-057","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you may usually choose a driver improvement course instead of points. When is that choice NOT allowed for speeding?","o":["When you were 5 mph over","When you were 10 mph over","When you were 15 mph over","When you were 30 mph or more over"],"h1":"It is for very high speeds only.","h2":"You may not choose the basic driver improvement course instead of points if you were charged with going 30 mph or more over the speed limit.","p":"Right. At 30 mph or more over, the course option is gone."},"es":{"q":"En Florida, normalmente puede elegir un curso para mejorar el manejo en vez de recibir puntos. ¿Cuándo NO se permite esa opción por exceso de velocidad?","o":["Si iba 5 mph por encima","Si iba 10 mph por encima","Si iba 15 mph por encima","Si iba 30 mph o más por encima"],"h1":"Es solo para velocidades muy altas.","h2":"No puede elegir el curso básico para mejorar el manejo en vez de puntos si lo acusan de ir a 30 mph o más por encima del límite.","p":"Correcto. Con 30 mph o más por encima, ya no puede elegir el curso."},"ref":{"doc":"FL","page":17}},{"id":"licensing-058","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you chose traffic school instead of points for a ticket 8 months ago. You get another ticket. May you choose traffic school again?","o":["Yes, as often as you like","Yes, if you pay a double fee","No, not within 12 months","No, never again in your life"],"h1":"There is a waiting period after each choice.","h2":"You may not choose traffic school instead of points if you already made that choice in the past 12 months.","p":"Right. Only once in any 12-month period."},"es":{"q":"En Florida, hace 8 meses eligió la escuela de tránsito en vez de puntos por una multa. Recibe otra multa. ¿Puede elegir la escuela de tránsito otra vez?","o":["Sí, todas las veces que quiera","Sí, si paga una tarifa doble","No, no dentro de 12 meses","No, nunca más en su vida"],"h1":"Hay un tiempo de espera después de cada vez.","h2":"No puede elegir la escuela de tránsito en vez de puntos si ya hizo esa elección en los últimos 12 meses.","p":"Correcto. Solo una vez en cualquier período de 12 meses."},"ref":{"doc":"FL","page":18}},{"id":"licensing-059","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, how many points do you get for speeding 15 mph or less over the limit?","o":["3 points","4 points","6 points","8 points"],"h1":"Going 16 mph or more over gives one point more than this.","h2":"Speeding by 15 mph or less over the limit adds 3 points to your Florida driving record.","p":"Right. 15 mph or less over the limit is 3 points."},"es":{"q":"En Florida, ¿cuántos puntos recibe por manejar 15 mph o menos por encima del límite?","o":["3 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Ir a 16 mph o más por encima da un punto más que esto.","h2":"Exceder el límite por 15 mph o menos agrega 3 puntos a su récord de manejo en Florida.","p":"Correcto. 15 mph o menos por encima del límite son 3 puntos."},"ref":{"doc":"FL","page":30}},{"id":"licensing-060","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, you leave the scene of a crash that caused more than $50 in property damage. How many points go on your record?","o":["2 points","3 points","6 points","10 points"],"h1":"It is one of the highest point values in the table.","h2":"Leaving the scene of a crash with more than $50 in property damage adds 6 points to your Florida driving record.","p":"Right. Leaving the scene of a property damage crash is 6 points."},"es":{"q":"En Florida, usted se va del lugar de un choque que causó más de $50 en daños a la propiedad. ¿Cuántos puntos van a su récord?","o":["2 puntos","3 puntos","6 puntos","10 puntos"],"h1":"Es uno de los valores más altos de la tabla.","h2":"Irse del lugar de un choque con más de $50 en daños a la propiedad agrega 6 puntos a su récord de manejo en Florida.","p":"Correcto. Irse del lugar de un choque con daños son 6 puntos."},"ref":{"doc":"FL","page":30}},{"id":"licensing-061","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, how many points do you get for passing a stopped school bus when no one is hurt?","o":["2 points","4 points","6 points","12 points"],"h1":"If someone is badly hurt, it is more than this.","h2":"Passing a stopped school bus adds 4 points to your record, or 6 points if it causes serious injury or death.","p":"Right. Passing a stopped school bus is 4 points."},"es":{"q":"En Florida, ¿cuántos puntos recibe por pasar un autobús escolar detenido si nadie sale herido?","o":["2 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Si alguien sale gravemente herido, son más que esto.","h2":"Pasar un autobús escolar detenido agrega 4 puntos a su récord, o 6 puntos si causa lesiones graves o la muerte.","p":"Correcto. Pasar un autobús escolar detenido son 4 puntos."},"ref":{"doc":"FL","page":30}},{"id":"licensing-062","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver fails to stop for a school bus a second time within 5 years. What happens to the license?","o":["Nothing beyond a fine","A written warning","A 30-day restriction to work driving","A suspension of 180 days to 1 year"],"h1":"A repeat offense brings a long suspension.","h2":"A second failure to stop for a school bus within 5 years leads to a license suspension of at least 180 days and up to 1 year.","p":"Right. A second offense in 5 years means a suspension of 180 days to 1 year."},"es":{"q":"En Florida, un conductor no se detiene ante un autobús escolar por segunda vez en 5 años. ¿Qué pasa con su licencia?","o":["Nada más que una multa","Una advertencia por escrito","Restricción de 30 días a manejar al trabajo","Una suspensión de 180 días a 1 año"],"h1":"Repetir la falta trae una suspensión larga.","h2":"Una segunda falta por no detenerse ante un autobús escolar dentro de 5 años lleva a una suspensión de la licencia de 180 días como mínimo y hasta 1 año.","p":"Correcto. Una segunda falta en 5 años significa una suspensión de 180 días a 1 año."},"ref":{"doc":"FL","page":null}},{"id":"licensing-063","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver under 18 is already limited to business-purposes-only driving because of points. What happens for each extra point?","o":["The limit lasts 90 more days","The limit lasts 1 more week","The license is revoked for good","Nothing more happens"],"h1":"The restriction gets longer, a few months at a time.","h2":"For a driver under 18 on the business-purposes-only restriction, each additional point extends the restriction by 90 days.","p":"Right. Each extra point adds 90 days to the restriction."},"es":{"q":"En Florida, a un conductor menor de 18 años ya lo limitaron a manejar solo por motivos de trabajo o estudio por los puntos. ¿Qué pasa por cada punto adicional?","o":["El límite dura 90 días más","El límite dura 1 semana más","Le revocan la licencia para siempre","No pasa nada más"],"h1":"La restricción se alarga, unos meses a la vez.","h2":"Para un conductor menor de 18 años con la restricción de solo motivos de trabajo o estudio, cada punto adicional alarga la restricción por 90 días.","p":"Correcto. Cada punto adicional agrega 90 días a la restricción."},"ref":{"doc":"FL","page":29}},{"id":"licensing-064","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, what is the usual fine range for a first DUI conviction?","o":["$50 to $100","$100 to $250","$500 to $1,000","$5,000 to $10,000"],"h1":"It is higher if the blood alcohol level is 0.15 or more, or a child was in the car.","h2":"A first DUI conviction in Florida usually brings a fine of $500 to $1,000, and more if the blood alcohol level was 0.15 or higher or a minor was in the car.","p":"Right. A first DUI usually means a fine of $500 to $1,000."},"es":{"q":"En Florida, ¿cuál es el rango normal de la multa por una primera condena por DUI?","o":["De $50 a $100","De $100 a $250","De $500 a $1,000","De $5,000 a $10,000"],"h1":"Es más alta si el nivel de alcohol es 0.15 o más, o si había un niño en el carro.","h2":"Una primera condena por DUI en Florida normalmente trae una multa de $500 a $1,000, y más si el nivel de alcohol era 0.15 o más o había un menor en el carro.","p":"Correcto. Un primer DUI normalmente significa una multa de $500 a $1,000."},"ref":{"doc":"FL","page":26}},{"id":"licensing-065","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a driver under 21 is stopped with a blood alcohol level of 0.05. Besides losing the license, what must the driver do?","o":["Pay for a new car inspection","Attend a substance abuse course","Retake the driving skills test","Do nothing more"],"h1":"It is a course about alcohol and drugs.","h2":"A driver under 21 with a blood alcohol level of 0.05 or higher must attend a substance abuse course.","p":"Right. At 0.05 or higher, a driver under 21 must take a substance abuse course."},"es":{"q":"En Florida, detienen a un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.05. Además de perder la licencia, ¿qué debe hacer?","o":["Pagar una nueva inspección del carro","Asistir a un curso sobre abuso de sustancias","Repetir el examen práctico de manejo","Nada más"],"h1":"Es un curso sobre el alcohol y las drogas.","h2":"Un conductor menor de 21 años con un nivel de alcohol de 0.05 o más debe asistir a un curso sobre abuso de sustancias.","p":"Correcto. Con 0.05 o más, un conductor menor de 21 años debe tomar un curso sobre abuso de sustancias."},"ref":{"doc":"FL","page":26}},{"id":"licensing-066","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, your license is suspended at a DUI arrest. How long do you have to ask for a review hearing?","o":["24 hours","30 days","90 days","10 days"],"h1":"It is less than two weeks.","h2":"To challenge a license suspension from a DUI arrest, you must ask for a formal or informal review hearing within 10 days.","p":"Right. You have 10 days to ask for a review."},"es":{"q":"En Florida, le suspenden la licencia al arrestarlo por DUI. ¿Cuánto tiempo tiene para pedir una audiencia de revisión?","o":["24 horas","30 días","90 días","10 días"],"h1":"Es menos de dos semanas.","h2":"Para apelar la suspensión de la licencia por un arresto por DUI, debe pedir una audiencia de revisión formal o informal dentro de 10 días.","p":"Correcto. Tiene 10 días para pedir una revisión."},"ref":{"doc":"FL","page":31}},{"id":"licensing-067","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a driver leaves the scene of a crash where a person was hurt. For at least how long will the driver lose the license?","o":["3 years","6 months","30 days","1 year"],"h1":"It is several years.","h2":"A driver who leaves the scene of a crash with injury or death loses the license for at least 3 years.","p":"Right. Hit-and-run with injury means losing the license for at least 3 years."},"es":{"q":"En Florida, un conductor se va del lugar de un choque donde una persona salió herida. ¿Por cuánto tiempo como mínimo perderá la licencia?","o":["3 años","6 meses","30 días","1 año"],"h1":"Son varios años.","h2":"Un conductor que se va del lugar de un choque con heridos o muertos pierde la licencia por al menos 3 años.","p":"Correcto. Huir de un choque con heridos significa perder la licencia por al menos 3 años."},"ref":{"doc":"FL","page":77}},{"id":"licensing-068","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, your 19-year-old front-seat passenger is not wearing a seat belt. Who gets the ticket?","o":["You, the driver","The car's owner","The passenger","No one"],"h1":"The answer is different for passengers under 18.","h2":"A passenger 18 or older who does not wear a required seat belt gets the ticket; the driver is charged only for passengers under 18.","p":"Right. A passenger 18 or older is charged for not buckling up."},"es":{"q":"En Florida, su pasajero de 19 años en el asiento delantero no lleva el cinturón de seguridad. ¿Quién recibe la multa?","o":["Usted, el conductor","El dueño del carro","El pasajero","Nadie"],"h1":"La respuesta es distinta para pasajeros menores de 18 años.","h2":"Un pasajero de 18 años o más que no usa el cinturón cuando la ley lo exige recibe la multa; al conductor solo lo multan por pasajeros menores de 18.","p":"Correcto. Al pasajero de 18 años o más lo multan por no abrocharse."},"ref":{"doc":"FL","page":28}},{"id":"licensing-069","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, what license do you need to ride a moped?","o":["A motorcycle endorsement","A Class E driver license","A commercial license","No license at all"],"h1":"It is the regular car license.","h2":"In Florida, moped riders need a Class E driver license; a motorcycle endorsement is not required.","p":"Right. A moped needs a Class E license, no endorsement."},"es":{"q":"En Florida, ¿qué licencia necesita para manejar un moped?","o":["Un endoso de motocicleta","Una licencia de conducir Clase E","Una licencia comercial","Ninguna licencia"],"h1":"Es la licencia normal para carros.","h2":"En Florida, quien maneja un moped necesita una licencia de conducir Clase E; no se requiere endoso de motocicleta.","p":"Correcto. Un moped requiere licencia Clase E, sin endoso."},"ref":{"doc":"FL","page":87}},{"id":"licensing-070","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, your driver license was stolen. You bring a copy of the police report to a service center in person and change nothing on the card. What does the replacement cost?","o":["The full replacement fee","Twice the normal fee","No fee at all","Half the normal fee"],"h1":"The police report shows the loss was not your fault.","h2":"In Florida, if your license was stolen and you show a copy of the police report in person, the replacement fee is waived as long as you change nothing on the card.","p":"Right. A stolen license is replaced free when you bring the police report."},"es":{"q":"En Florida, le robaron su licencia de conducir. Usted lleva en persona una copia del informe de la policía a una oficina de licencias y no cambia nada en la tarjeta. ¿Cuánto cuesta el reemplazo?","o":["La tarifa completa de reemplazo","El doble de la tarifa normal","No se cobra nada","La mitad de la tarifa normal"],"h1":"El informe de la policía muestra que la pérdida no fue su culpa.","h2":"En Florida, si le robaron la licencia y muestra en persona una copia del informe de la policía, no se cobra el reemplazo, siempre que no cambie nada en la tarjeta.","p":"Correcto. Una licencia robada se reemplaza gratis si lleva el informe de la policía."},"ref":{"doc":"FL","page":13}},{"id":"licensing-071","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, how must you back up the car on the driving skills test?","o":["50 feet slowly, looking back, with no mirror or camera","100 feet quickly, using only the backup camera","20 feet slowly, using only the side mirrors","10 feet, using the mirror and the camera"],"h1":"The examiner wants to see you turn and look behind you.","h2":"On the Florida driving skills test, you back up 50 feet at a slow speed while looking to the rear, without using the rear-view mirror or the backup camera.","p":"Right. You back up 50 feet slowly and look back yourself."},"es":{"q":"En Florida, ¿cómo debe manejar en reversa en el examen práctico de manejo?","o":["50 pies despacio, mirando hacia atrás, sin espejo ni cámara","100 pies rápido, usando solo la cámara trasera","20 pies despacio, usando solo los espejos laterales","10 pies, usando el espejo y la cámara"],"h1":"El examinador quiere ver que usted se voltee y mire hacia atrás.","h2":"En el examen práctico de manejo de Florida, usted maneja en reversa 50 pies a baja velocidad mirando hacia atrás, sin usar el espejo retrovisor ni la cámara trasera.","p":"Correcto. Retrocede 50 pies despacio y mira hacia atrás usted mismo."},"ref":{"doc":"FL","page":20}},{"id":"licensing-072","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, on the driving skills test, how much space do you get to turn the car around with a three-point turn?","o":["10 to 15 feet","20 to 40 feet","50 to 70 feet","80 to 100 feet"],"h1":"It is about the width of a normal street.","h2":"On the Florida driving skills test, you turn the car around with a three-point turn in a space 20 to 40 feet wide.","p":"Right. The three-point turn is done in a 20 to 40 foot space."},"es":{"q":"En Florida, en el examen práctico de manejo, ¿en cuánto espacio debe dar la vuelta al carro con una vuelta en tres puntos?","o":["De 10 a 15 pies","De 20 a 40 pies","De 50 a 70 pies","De 80 a 100 pies"],"h1":"Es más o menos el ancho de una calle normal.","h2":"En el examen práctico de manejo de Florida, usted da la vuelta al carro con una vuelta en tres puntos en un espacio de 20 a 40 pies de ancho.","p":"Correcto. La vuelta en tres puntos se hace en un espacio de 20 a 40 pies."},"ref":{"doc":"FL","page":21}},{"id":"licensing-073","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, after a DUI conviction, how much bodily injury liability insurance must you carry for injuries to one person?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"It is much higher than the usual amounts, because a DUI driver is a bigger risk.","h2":"In Florida, after a DUI conviction you must carry at least $100,000 of bodily injury liability for one person, $300,000 for two or more people and $50,000 for property damage, for 3 years.","p":"Right. After a DUI, you need $100,000 of coverage for one injured person."},"es":{"q":"En Florida, después de una condena por DUI, ¿cuánto seguro de responsabilidad por lesiones corporales debe tener para las lesiones de una persona?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Es mucho más alto que las cantidades normales, porque un conductor con DUI es un riesgo mayor.","h2":"En Florida, después de una condena por DUI debe tener por 3 años al menos $100,000 de responsabilidad por lesiones para una persona, $300,000 para dos o más personas y $50,000 por daños a la propiedad.","p":"Correcto. Después de un DUI, necesita $100,000 de cobertura por una persona lesionada."},"ref":{"doc":"FL","page":24}},{"id":"licensing-074","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you will stop insuring a car that still has a valid registration. What should you do before you cancel the insurance?","o":["Turn in the license plate","Call the police station","Park the car in a garage","Peel off the registration sticker"],"h1":"A registered car must stay insured the whole registration period, unless you return one item first.","h2":"In Florida, you should turn in the car's license plate before you cancel the insurance, so your license is not suspended and you avoid reinstatement fees.","p":"Right. Turn in the plate first, then cancel the insurance."},"es":{"q":"En Florida, usted va a dejar de asegurar un carro que todavía tiene el registro vigente. ¿Qué debe hacer antes de cancelar el seguro?","o":["Entregar la placa","Llamar a la estación de policía","Guardar el carro en un garaje","Quitar la calcomanía del registro"],"h1":"Un carro registrado debe estar asegurado todo el período del registro, a menos que primero devuelva una cosa.","h2":"En Florida, debe entregar la placa del carro antes de cancelar el seguro, para que no le suspendan la licencia y evitar los cargos de restablecimiento.","p":"Correcto. Primero entregue la placa y después cancele el seguro."},"ref":{"doc":"FL","page":23}},{"id":"licensing-075","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, at least how many hours of community service come with a first DUI conviction?","o":["10 hours","25 hours","40 hours","50 hours"],"h1":"It is more than a full work week of hours.","h2":"In Florida, a first DUI conviction includes at least 50 hours of community service.","p":"Right. A first DUI brings at least 50 hours of community service."},"es":{"q":"En Florida, ¿cuántas horas de servicio comunitario, como mínimo, vienen con una primera condena por DUI?","o":["10 horas","25 horas","40 horas","50 horas"],"h1":"Son más horas que una semana completa de trabajo.","h2":"En Florida, una primera condena por DUI incluye al menos 50 horas de servicio comunitario.","p":"Correcto. Un primer DUI trae al menos 50 horas de servicio comunitario."},"ref":{"doc":"FL","page":26}},{"id":"licensing-076","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, after a first DUI conviction, for at least how long is the driver license revoked?","o":["30 days","180 days","2 years","5 years"],"h1":"It is about half a year.","h2":"In Florida, a first DUI conviction revokes your driver license for at least 180 days.","p":"Right. A first DUI costs you your license for at least 180 days."},"es":{"q":"En Florida, después de una primera condena por DUI, ¿por cuánto tiempo, como mínimo, se revoca la licencia de conducir?","o":["30 días","180 días","2 años","5 años"],"h1":"Es más o menos medio año.","h2":"En Florida, una primera condena por DUI revoca su licencia de conducir por al menos 180 días.","p":"Correcto. Un primer DUI le quita la licencia por al menos 180 días."},"ref":{"doc":"FL","page":26}},{"id":"licensing-077","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, after a second DUI conviction, for at least how long must an ignition interlock device be installed?","o":["1 month","6 months","1 year","10 years"],"h1":"The device stops the car from starting if it finds alcohol on your breath, and it stays in for a full year or more.","h2":"In Florida, a second DUI conviction requires an ignition interlock device for at least one continuous year.","p":"Right. After a second DUI, the interlock stays in for at least 1 year."},"es":{"q":"En Florida, después de una segunda condena por DUI, ¿por cuánto tiempo, como mínimo, se debe instalar un dispositivo de bloqueo de encendido?","o":["1 mes","6 meses","1 año","10 años"],"h1":"El dispositivo no deja arrancar el carro si detecta alcohol en su aliento, y se queda instalado un año completo o más.","h2":"En Florida, una segunda condena por DUI exige un dispositivo de bloqueo de encendido por al menos un año continuo.","p":"Correcto. Después de un segundo DUI, el dispositivo se queda al menos 1 año."},"ref":{"doc":"FL","page":26}},{"id":"licensing-078","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, a driver is convicted of DUI a second time, within 5 years of the first conviction. For at least how long is the license revoked?","o":["6 months","1 year","2 years","5 years"],"h1":"A second DUI in a short time is treated much more harshly than the first.","h2":"In Florida, a second DUI conviction within 5 years of the first revokes the driver license for at least 5 years.","p":"Right. A second DUI within 5 years means at least 5 years without a license."},"es":{"q":"En Florida, un conductor es condenado por DUI por segunda vez, dentro de los 5 años después de la primera condena. ¿Por cuánto tiempo, como mínimo, se revoca la licencia?","o":["6 meses","1 año","2 años","5 años"],"h1":"Un segundo DUI en poco tiempo se castiga mucho más que el primero.","h2":"En Florida, una segunda condena por DUI dentro de los 5 años después de la primera revoca la licencia de conducir por al menos 5 años.","p":"Correcto. Un segundo DUI en 5 años significa al menos 5 años sin licencia."},"ref":{"doc":"FL","page":null}},{"id":"licensing-079","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, how long must a DUI conviction stay on your driving record?","o":["3 years","7 years","10 years","75 years"],"h1":"It is longer than most people drive in a lifetime.","h2":"In Florida, a DUI conviction must stay on your driving record for 75 years.","p":"Right. A DUI stays on a Florida driving record for 75 years."},"es":{"q":"En Florida, ¿cuánto tiempo debe quedar una condena por DUI en su historial de manejo?","o":["3 años","7 años","10 años","75 años"],"h1":"Es más tiempo del que la mayoría de las personas maneja en toda su vida.","h2":"En Florida, una condena por DUI debe quedar en su historial de manejo por 75 años.","p":"Correcto. Un DUI queda en el historial de manejo de Florida por 75 años."},"ref":{"doc":"FL","page":35}},{"id":"licensing-080","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, which of these people does NOT have to wear a seat belt by law?","o":["A front-seat passenger who is 19","A driver going to the store","A 15-year-old in the back seat","A worker delivering newspapers on a home route"],"h1":"The law makes an exception for one kind of job with many quick stops.","h2":"In Florida, an employee of a newspaper home delivery service does not have to wear a seat belt while delivering newspapers on the route.","p":"Right. Newspaper home delivery workers on their route are exempt."},"es":{"q":"En Florida, ¿cuál de estas personas NO tiene que usar el cinturón de seguridad por ley?","o":["Un pasajero de 19 años en el asiento delantero","Un conductor que va a la tienda","Un joven de 15 años en el asiento trasero","Un trabajador que reparte periódicos en una ruta a domicilio"],"h1":"La ley hace una excepción para un tipo de trabajo con muchas paradas rápidas.","h2":"En Florida, un empleado de un servicio de reparto de periódicos a domicilio no tiene que usar el cinturón mientras reparte periódicos en su ruta.","p":"Correcto. Los repartidores de periódicos a domicilio están exentos en su ruta."},"ref":{"doc":"FL","page":28}},{"id":"licensing-081","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, a driver is convicted for a third crash within 36 months and must take a course with behind-the-wheel training. How long does the driver have to finish it before the license is canceled?","o":["30 days","90 days","1 year","2 years"],"h1":"It is about three months.","h2":"In Florida, under the three crashes in three years law, the driver must complete the required course within 90 days, or the license is canceled.","p":"Right. The driver has 90 days to finish, or loses the license."},"es":{"q":"En Florida, un conductor es condenado por un tercer choque en 36 meses y debe tomar un curso con práctica al volante. ¿Cuánto tiempo tiene para terminarlo antes de que le cancelen la licencia?","o":["30 días","90 días","1 año","2 años"],"h1":"Son más o menos tres meses.","h2":"En Florida, según la ley de tres choques en tres años, el conductor debe terminar el curso requerido en 90 días, o le cancelan la licencia.","p":"Correcto. El conductor tiene 90 días para terminar, o pierde la licencia."},"ref":{"doc":"FL","page":29}},{"id":"licensing-082","scope":"FL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Florida, you choose a basic driver improvement course for a non-criminal traffic ticket. What happens to the civil penalty?","o":["It is doubled","It is cut by 18 percent","It stays the same","It is canceled completely"],"h1":"Taking the course earns you a small discount.","h2":"In Florida, if you elect a basic driver improvement course for a non-criminal traffic ticket, the civil penalty is reduced by 18 percent.","p":"Right. The course lowers the civil penalty by 18 percent."},"es":{"q":"En Florida, usted elige un curso básico de mejoramiento del conductor por una multa de tránsito no criminal. ¿Qué pasa con la multa civil?","o":["Se duplica","Se reduce un 18 por ciento","Se queda igual","Se cancela por completo"],"h1":"Tomar el curso le da un pequeño descuento.","h2":"En Florida, si elige un curso básico de mejoramiento del conductor por una multa de tránsito no criminal, la multa civil se reduce un 18 por ciento.","p":"Correcto. El curso reduce la multa civil un 18 por ciento."},"ref":{"doc":"FL","page":17}},{"id":"licensing-083","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how many points go on your driving record for reckless driving?","o":["2 points","3 points","4 points","6 points"],"h1":"It is the same number of points as passing a stopped school bus when no one is hurt.","h2":"In Florida, a reckless driving conviction puts 4 points on your driving record.","p":"Right. Reckless driving is 4 points."},"es":{"q":"En Florida, ¿cuántos puntos se ponen en su historial de manejo por manejo temerario?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Es el mismo número de puntos que por pasar un autobús escolar detenido cuando nadie resulta herido.","h2":"En Florida, una condena por manejo temerario pone 4 puntos en su historial de manejo.","p":"Correcto. El manejo temerario son 4 puntos."},"ref":{"doc":"FL","page":30}},{"id":"licensing-084","scope":"FL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Florida, you were speeding and it caused a crash. How many points go on your driving record?","o":["3 points","4 points","5 points","6 points"],"h1":"A crash makes the points much higher than for speeding alone.","h2":"In Florida, unlawful speed that results in a crash puts 6 points on your driving record.","p":"Right. Speeding that causes a crash is 6 points."},"es":{"q":"En Florida, usted iba con exceso de velocidad y eso causó un choque. ¿Cuántos puntos se ponen en su historial de manejo?","o":["3 puntos","4 puntos","5 puntos","6 puntos"],"h1":"Un choque hace que los puntos sean mucho más altos que por la velocidad sola.","h2":"En Florida, la velocidad ilegal que causa un choque pone 6 puntos en su historial de manejo.","p":"Correcto. El exceso de velocidad que causa un choque son 6 puntos."},"ref":{"doc":"FL","page":30}},{"id":"licensing-085","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, how many traffic convictions that carry points, within 5 years, make you a habitual traffic offender whose license is revoked?","o":["5","10","15","25"],"h1":"It is more than ten.","h2":"In Florida, 15 convictions for offenses that carry points within a 5-year period make you a habitual traffic offender, and your license is revoked.","p":"Right. 15 point convictions in 5 years leads to revocation."},"es":{"q":"En Florida, ¿cuántas condenas de tránsito con puntos, en 5 años, lo convierten en infractor habitual y le revocan la licencia?","o":["5","10","15","25"],"h1":"Son más de diez.","h2":"En Florida, 15 condenas por infracciones con puntos en un período de 5 años lo convierten en infractor habitual de tránsito, y le revocan la licencia.","p":"Correcto. 15 condenas con puntos en 5 años llevan a la revocación."},"ref":{"doc":"FL","page":31}},{"id":"licensing-086","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, you live in another state but take a job in Florida. How soon must you register your car in Florida?","o":["Within 10 days","Within 30 days","Within 90 days","Within 6 months"],"h1":"It is a short time, less than two weeks.","h2":"In Florida, a non-resident who starts working in the state must register the car within 10 days after the job begins.","p":"Right. A non-resident who works in Florida registers the car within 10 days."},"es":{"q":"En Florida, usted vive en otro estado pero acepta un trabajo en Florida. ¿En cuánto tiempo debe registrar su carro en Florida?","o":["En 10 días","En 30 días","En 90 días","En 6 meses"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Florida, una persona no residente que empieza a trabajar en el estado debe registrar su carro dentro de los 10 días después de empezar el trabajo.","p":"Correcto. Un no residente que trabaja en Florida registra el carro en 10 días."},"ref":{"doc":"FL","page":37}},{"id":"licensing-087","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, a car is owned by a person, not a company. When does its registration usually expire?","o":["On the first owner's birthday","On December 31","On the purchase date","On June 30"],"h1":"The date is personal to the owner listed first on the registration.","h2":"In Florida, a car registration usually expires at midnight on the birthday of the first owner listed on the registration.","p":"Right. It expires on the first listed owner's birthday."},"es":{"q":"En Florida, un carro es de una persona, no de una compañía. ¿Cuándo vence normalmente su registro?","o":["En el cumpleaños del primer dueño","El 31 de diciembre","En la fecha de compra","El 30 de junio"],"h1":"La fecha es personal del dueño que aparece primero en el registro.","h2":"En Florida, el registro de un carro normalmente vence a la medianoche del cumpleaños del primer dueño que aparece en el registro.","p":"Correcto. Vence en el cumpleaños del primer dueño en el registro."},"ref":{"doc":"FL","page":37}},{"id":"licensing-088","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, a driver leaves the scene of a crash in which someone died. What is the minimum prison term?","o":["6 months","1 year","4 years","No prison term"],"h1":"It is a first-degree felony with a mandatory minimum of several years.","h2":"In Florida, leaving the scene of a crash that caused a death is a first-degree felony with a minimum prison term of 4 years.","p":"Right. A deadly hit and run carries at least 4 years in prison."},"es":{"q":"En Florida, un conductor se va del lugar de un choque en el que murió una persona. ¿Cuál es la pena mínima de prisión?","o":["6 meses","1 año","4 años","Ninguna pena de prisión"],"h1":"Es un delito grave de primer grado con un mínimo obligatorio de varios años.","h2":"En Florida, irse del lugar de un choque que causó una muerte es un delito grave de primer grado con una pena mínima de 4 años de prisión.","p":"Correcto. Huir de un choque mortal trae al menos 4 años de prisión."},"ref":{"doc":"FL","page":77}},{"id":"licensing-089","scope":"FL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Florida, what must you complete before you can get a motorcycle endorsement?","o":["An approved motorcycle safety course","A 50-hour driving log","A first aid class","A basic driver improvement course"],"h1":"The course is made just for motorcycle riders.","h2":"In Florida, you must complete an approved motorcycle safety course to get a motorcycle endorsement or a Motorcycle Only license.","p":"Right. An approved motorcycle safety course comes first."},"es":{"q":"En Florida, ¿qué debe completar antes de obtener el endoso de motocicleta?","o":["Un curso aprobado de seguridad en motocicleta","Un registro de 50 horas de manejo","Una clase de primeros auxilios","Un curso básico de mejoramiento del conductor"],"h1":"El curso está hecho solo para motociclistas.","h2":"En Florida, debe completar un curso aprobado de seguridad en motocicleta para obtener el endoso de motocicleta o una licencia solo para motocicleta.","p":"Correcto. Primero va un curso aprobado de seguridad en motocicleta."},"ref":{"doc":"FL","page":87}},{"id":"licensing-090","scope":"FL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Florida, must the owner of a motorcycle carry Personal Injury Protection (PIP) insurance?","o":["Yes, $10,000 of PIP","Yes, $20,000 of PIP","No, motorcycles do not need PIP","Only if the rider is under 21"],"h1":"Florida's PIP rule for cars does not cover every kind of vehicle.","h2":"In Florida, operators of motorcycles and mopeds do not have to carry Personal Injury Protection (PIP) insurance.","p":"Right. Motorcycles and mopeds are not required to carry PIP."},"es":{"q":"En Florida, ¿debe el dueño de una motocicleta tener seguro de Protección contra Lesiones Personales (PIP)?","o":["Sí, $10,000 de PIP","Sí, $20,000 de PIP","No, las motocicletas no necesitan PIP","Solo si el motociclista tiene menos de 21 años"],"h1":"La regla de PIP de Florida para carros no cubre todo tipo de vehículo.","h2":"En Florida, quienes manejan motocicletas y ciclomotores no tienen que tener seguro de Protección contra Lesiones Personales (PIP).","p":"Correcto. Las motocicletas y los ciclomotores no necesitan PIP."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-001","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, at a four-way stop, which car goes first?","o":["The car that came to a full stop first","The largest vehicle at the stop","The car on the far left","The car that is going straight"],"h1":"Think about the order in which the cars arrived.","h2":"At a four-way stop, the driver who stopped first goes first, and the others follow in the order they arrived.","p":"Right. At a four-way stop, the first car to stop goes first."},"es":{"q":"En Florida, en un pare de cuatro vías, ¿qué carro sigue primero?","o":["El carro que hizo el alto total primero","El vehículo más grande en el pare","El carro que está más a la izquierda","El carro que va derecho"],"h1":"Piense en el orden en que llegaron los carros.","h2":"En un pare de cuatro vías, el conductor que paró primero sigue primero, y los demás siguen en el orden en que llegaron.","p":"Correcto. En un pare de cuatro vías, el primer carro en parar sigue primero."},"zh":{"q":"在 Florida，在四向停车路口，哪辆车先走？","o":["最先完全停下的车","路口最大的车","最左边的车","直行的车"],"h1":"想一想车辆到达的先后顺序。","h2":"在四向停车路口，最先停下的司机先走，其他车按到达的顺序跟着走。","p":"对。在四向停车路口，最先停下的车先走。"},"vi":{"q":"Ở Florida, tại ngã tư có biển \"STOP\" ở cả bốn phía, xe nào được đi trước?","o":["Xe dừng hẳn lại trước tiên","Xe lớn nhất tại chỗ dừng","Xe ở phía xa bên trái","Xe đang đi thẳng"],"h1":"Hãy nghĩ về thứ tự các xe đến nơi.","h2":"Tại ngã tư có biển \"STOP\" ở cả bốn phía, người lái dừng trước sẽ đi trước, và các xe khác đi theo thứ tự đã đến.","p":"Đúng. Tại ngã tư bốn biển \"STOP\", xe dừng trước được đi trước."},"tl":{"q":"Sa Florida, sa four-way stop, aling kotse ang unang aandar?","o":["Ang kotseng unang huminto nang buo","Ang pinakamalaking sasakyan sa hintuan","Ang kotseng nasa pinakakaliwa","Ang kotseng diretso ang punta"],"h1":"Isipin ang pagkakasunod-sunod ng pagdating ng mga kotse.","h2":"Sa four-way stop, ang drayber na unang huminto ang unang aandar, at susunod ang iba ayon sa pagkakasunod ng kanilang pagdating.","p":"Tama. Sa four-way stop, ang unang kotseng huminto ang unang aandar."},"ar":{"q":"في Florida، عند تقاطع فيه علامة توقف من أربع جهات، أي سيارة تمر أولًا؟","o":["السيارة التي توقفت توقفًا كاملًا أولًا","أكبر مركبة عند التقاطع","السيارة التي في أقصى اليسار","السيارة التي تسير إلى الأمام مباشرة"],"h1":"فكّر في الترتيب الذي وصلت به السيارات.","h2":"عند تقاطع فيه علامة توقف من أربع جهات، يمر أولًا السائق الذي توقف أولًا، ثم يمر الآخرون حسب ترتيب وصولهم.","p":"صحيح. عند علامة التوقف من أربع جهات، تمر أولًا السيارة التي توقفت أولًا."},"ht":{"q":"Nan Florida, nan yon kafou ki gen siy \"STOP\" sou kat bò, ki machin ki pase anvan?","o":["Machin ki te kanpe nèt an premye a","Pi gwo machin ki nan kafou a","Machin ki pi lwen sou bò gòch la","Machin k ap kontinye tou dwat la"],"h1":"Panse ak lòd machin yo te rive.","h2":"Nan yon kafou ki gen siy \"STOP\" sou kat bò, chofè ki te kanpe an premye a pase anvan, epi lòt yo swiv nan lòd yo te rive a.","p":"Wi, se sa. Nan yon kafou ki gen \"STOP\" sou kat bò, premye machin ki kanpe a pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-002","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, two cars stop at a four-way stop at the same time. Who goes first?","o":["The driver who honks first","The driver on the left","The driver on the right","The driver who is in a hurry"],"h1":"Look at where the other car is, to your left or to your right.","h2":"When two cars stop at the same time, the driver on the left lets the driver on the right go first.","p":"Right. When you arrive together, the car on the right goes first."},"es":{"q":"En Florida, dos carros paran al mismo tiempo en un pare de cuatro vías. ¿Quién sigue primero?","o":["El conductor que toca la bocina primero","El conductor de la izquierda","El conductor de la derecha","El conductor que tiene prisa"],"h1":"Fíjese dónde está el otro carro, a su izquierda o a su derecha.","h2":"Cuando dos carros paran al mismo tiempo, el conductor de la izquierda deja pasar primero al conductor de la derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，两辆车同时停在四向停车路口。谁先走？","o":["先按喇叭的司机","左边的司机","右边的司机","赶时间的司机"],"h1":"看看另一辆车在你的左边还是右边。","h2":"两辆车同时停下时，左边的司机让右边的司机先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, hai xe dừng cùng lúc tại ngã tư có biển \"STOP\" ở cả bốn phía. Ai được đi trước?","o":["Người bấm còi trước","Người lái ở bên trái","Người lái ở bên phải","Người lái đang vội"],"h1":"Hãy xem xe kia ở đâu, bên trái hay bên phải của bạn.","h2":"Khi hai xe dừng cùng lúc, người lái bên trái phải để người lái bên phải đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, dalawang kotse ang sabay na huminto sa four-way stop. Sino ang unang aandar?","o":["Ang drayber na unang bumusina","Ang drayber na nasa kaliwa","Ang drayber na nasa kanan","Ang drayber na nagmamadali"],"h1":"Tingnan kung nasaan ang ibang kotse, sa kaliwa mo o sa kanan mo.","h2":"Kapag sabay na huminto ang dalawang kotse, pinauuna ng drayber na nasa kaliwa ang drayber na nasa kanan.","p":"Tama. Kapag sabay kayong dumating, ang kotse sa kanan ang unang aandar."},"ar":{"q":"في Florida، توقفت سيارتان عند تقاطع فيه علامة توقف من أربع جهات في الوقت نفسه. من يمر أولًا؟","o":["السائق الذي يستعمل البوق أولًا","السائق الذي على اليسار","السائق الذي على اليمين","السائق المستعجل"],"h1":"انظر أين السيارة الأخرى: على يسارك أم على يمينك؟","h2":"عندما تتوقف سيارتان في الوقت نفسه، يترك السائق الذي على اليسار السائقَ الذي على اليمين يمر أولًا.","p":"صحيح. عندما تصلان معًا، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, de machin kanpe nan yon kafou ki gen \"STOP\" sou kat bò an menm tan. Kiyès ki pase anvan?","o":["Chofè ki klaksonnen an premye a","Chofè ki sou bò gòch la","Chofè ki sou bò dwat la","Chofè ki prese a"],"h1":"Gade kote lòt machin nan ye, sou bò gòch ou oswa sou bò dwat ou.","h2":"Lè de machin kanpe an menm tan, chofè ki sou bò gòch la kite chofè ki sou bò dwat la pase anvan.","p":"Wi, se sa. Lè nou rive ansanm, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-003","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you reach an intersection with no signs or lights. A car is already crossing it. What do you do?","o":["Go first, because you are on the wider road","Let the car that is already in the intersection go first","Honk and go at the same time","Speed up to cross before it"],"h1":"Think about who is already using the space.","h2":"At an intersection with no signs or lights, you must yield to a vehicle that is already in the intersection.","p":"Right. Yield to the car that is already in the intersection."},"es":{"q":"En Florida, usted llega a una intersección sin señales ni semáforos. Un carro ya la está cruzando. ¿Qué hace?","o":["Sigue primero, porque usted va por la calle más ancha","Deja pasar primero al carro que ya está en la intersección","Toca la bocina y sigue al mismo tiempo","Acelera para cruzar antes que él"],"h1":"Piense en quién ya está usando ese espacio.","h2":"En una intersección sin señales ni semáforos, usted debe ceder el paso al vehículo que ya está dentro de la intersección.","p":"Correcto. Ceda el paso al carro que ya está en la intersección."},"zh":{"q":"在 Florida，你来到一个没有标志也没有红绿灯的路口。有一辆车已经在通过路口。你该怎么做？","o":["你先走，因为你的路更宽","让已经在路口里的车先走","按喇叭，同时开过去","加速，抢在它前面通过"],"h1":"想一想谁已经在使用这个空间。","h2":"在没有标志也没有红绿灯的路口，你必须让已经在路口里的车先走。","p":"对。让已经在路口里的车先走。"},"vi":{"q":"Ở Florida, bạn đến một giao lộ không có biển báo hay đèn. Một xe đang chạy qua giao lộ. Bạn làm gì?","o":["Đi trước, vì đường của bạn rộng hơn","Để xe đang ở trong giao lộ đi trước","Bấm còi và đi cùng lúc","Tăng tốc để qua trước xe đó"],"h1":"Hãy nghĩ xem ai đang dùng chỗ đó rồi.","h2":"Tại giao lộ không có biển báo hay đèn, bạn phải nhường đường cho xe đã ở trong giao lộ.","p":"Đúng. Hãy nhường xe đã ở trong giao lộ."},"tl":{"q":"Sa Florida, dumating ka sa intersection na walang karatula o ilaw trapiko. May kotseng tumatawid na roon. Ano ang gagawin mo?","o":["Mauna ka, dahil mas malapad ang daan mo","Paunahin ang kotseng nasa loob na ng intersection","Bumusina at sabay na umandar","Bumilis para makatawid bago ito"],"h1":"Isipin kung sino na ang gumagamit ng lugar.","h2":"Sa intersection na walang karatula o ilaw, dapat kang magbigay-daan sa sasakyang nasa loob na ng intersection.","p":"Tama. Magbigay-daan sa kotseng nasa loob na ng intersection."},"ar":{"q":"في Florida، وصلت إلى تقاطع ليس فيه علامات ولا إشارات ضوئية. هناك سيارة تعبره الآن. ماذا تفعل؟","o":["أمر أولًا لأن طريقي أعرض","أترك السيارة التي في التقاطع تمر أولًا","أستعمل البوق وأمر في الوقت نفسه","أسرع لأعبر قبلها"],"h1":"فكّر في من يستعمل المكان الآن.","h2":"عند تقاطع ليس فيه علامات ولا إشارات ضوئية، يجب أن تعطي حق المرور للمركبة الموجودة داخل التقاطع.","p":"صحيح. أعطِ حق المرور للسيارة الموجودة داخل التقاطع."},"ht":{"q":"Nan Florida, ou rive nan yon kafou ki pa gen siy ni limyè. Gen yon machin ki deja ap travèse l. Kisa ou fè?","o":["Ou pase anvan, paske wout ou a pi laj","Ou kite machin ki deja nan kafou a pase anvan","Ou klaksonnen epi ou pase an menm tan","Ou akselere pou travèse anvan li"],"h1":"Panse ak kiyès ki deja ap sèvi ak espas la.","h2":"Nan yon kafou ki pa gen siy ni limyè, ou dwe kite yon machin ki deja nan kafou a pase anvan.","p":"Wi, se sa. Kite machin ki deja nan kafou a pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-004","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you and another car reach an intersection with no signs at the same time. The other car is on your right. Who goes first?","o":["You go first, because you are on the left","The faster car goes first","Both cars go at the same time","The car on your right goes first"],"h1":"The rule is the same as when two cars stop together at a stop sign.","h2":"When two cars reach an open intersection at the same time, the driver on the left yields, so the car on your right goes first.","p":"Right. At the same time, the car on the right goes first."},"es":{"q":"En Florida, usted y otro carro llegan al mismo tiempo a una intersección sin señales. El otro carro está a su derecha. ¿Quién sigue primero?","o":["Usted sigue primero, porque está a la izquierda","Sigue primero el carro más rápido","Los dos carros siguen al mismo tiempo","Sigue primero el carro que está a su derecha"],"h1":"La regla es igual que cuando dos carros paran juntos en un pare.","h2":"Cuando dos carros llegan al mismo tiempo a una intersección sin control, cede el paso el conductor de la izquierda, así que sigue primero el carro de su derecha.","p":"Correcto. Si llegan juntos, sigue primero el carro de la derecha."},"zh":{"q":"在 Florida，你和另一辆车同时来到一个没有标志的路口。另一辆车在你的右边。谁先走？","o":["你先走，因为你在左边","开得快的车先走","两辆车同时走","你右边的车先走"],"h1":"规则和两辆车同时停在停车标志前一样。","h2":"两辆车同时来到没有管制的路口时，左边的司机要让行，所以你右边的车先走。","p":"对。同时到达时，右边的车先走。"},"vi":{"q":"Ở Florida, bạn và một xe khác đến giao lộ không có biển báo cùng lúc. Xe kia ở bên phải bạn. Ai được đi trước?","o":["Bạn đi trước, vì bạn ở bên trái","Xe nhanh hơn đi trước","Cả hai xe đi cùng lúc","Xe bên phải bạn đi trước"],"h1":"Quy tắc giống như khi hai xe cùng dừng ở biển \"STOP\".","h2":"Khi hai xe đến giao lộ không có biển báo cùng lúc, người lái bên trái phải nhường, nên xe bên phải bạn được đi trước.","p":"Đúng. Khi đến cùng lúc, xe bên phải được đi trước."},"tl":{"q":"Sa Florida, sabay kayong dumating ng isa pang kotse sa intersection na walang karatula. Nasa kanan mo ang kotse. Sino ang mauuna?","o":["Ikaw ang mauuna, dahil nasa kaliwa ka","Ang mas mabilis na kotse ang mauuna","Sabay na aandar ang dalawang kotse","Ang kotse sa kanan mo ang mauuna"],"h1":"Pareho ang patakaran kapag sabay na huminto ang dalawang kotse sa stop sign.","h2":"Kapag sabay na dumating ang dalawang kotse sa bukas na intersection, nagbibigay-daan ang drayber sa kaliwa, kaya ang kotse sa kanan mo ang mauuna.","p":"Tama. Kapag sabay, ang kotse sa kanan ang mauuna."},"ar":{"q":"في Florida، وصلت أنت وسيارة أخرى إلى تقاطع ليس فيه علامات في الوقت نفسه. السيارة الأخرى على يمينك. من يمر أولًا؟","o":["أنت تمر أولًا لأنك على اليسار","السيارة الأسرع تمر أولًا","تمر السيارتان في الوقت نفسه","السيارة التي على يمينك تمر أولًا"],"h1":"القاعدة هي نفسها عندما تتوقف سيارتان معًا عند علامة توقف.","h2":"عندما تصل سيارتان إلى تقاطع مفتوح في الوقت نفسه، يعطي السائق الذي على اليسار حق المرور، لذلك تمر السيارة التي على يمينك أولًا.","p":"صحيح. إذا وصلتما في الوقت نفسه، تمر السيارة التي على اليمين أولًا."},"ht":{"q":"Nan Florida, ou menm ak yon lòt machin rive an menm tan nan yon kafou ki pa gen siy. Lòt machin nan sou bò dwat ou. Kiyès ki pase anvan?","o":["Ou pase anvan, paske ou sou bò gòch la","Machin ki pi vit la pase anvan","De machin yo pase an menm tan","Machin ki sou bò dwat ou a pase anvan"],"h1":"Règ la se menm jan ak lè de machin kanpe ansanm devan yon siy \"STOP\".","h2":"Lè de machin rive an menm tan nan yon kafou ki pa gen siy, chofè ki sou bò gòch la kite lòt la pase, kidonk machin ki sou bò dwat ou a pase anvan.","p":"Wi, se sa. Lè nou rive an menm tan, machin ki sou bò dwat la pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-006","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you want to turn left at a green light. A car is coming toward you. What do you do?","o":["Turn quickly before it gets close","Turn, because a green light gives you the right of way","Wait and let the oncoming car pass first","Flash your lights and turn"],"h1":"A green light lets you go, but it does not clear the road in front of you.","h2":"When you turn left, you must yield to oncoming traffic, so you wait until the car passes and the way is clear.","p":"Right. When turning left, let oncoming traffic go first."},"es":{"q":"En Florida, usted quiere doblar a la izquierda con luz verde. Viene un carro de frente. ¿Qué hace?","o":["Dobla rápido antes de que se acerque","Dobla, porque la luz verde le da el derecho de paso","Espera y deja pasar primero al carro que viene de frente","Hace cambio de luces y dobla"],"h1":"La luz verde le permite seguir, pero no despeja la calle delante de usted.","h2":"Cuando usted dobla a la izquierda, debe ceder el paso al tráfico que viene de frente, así que espera hasta que el carro pase y el camino esté libre.","p":"Correcto. Al doblar a la izquierda, deje pasar primero al tráfico de frente."},"zh":{"q":"在 Florida，绿灯时你想左转。对面有一辆车开过来。你该怎么做？","o":["趁它还没靠近，赶快转","转弯，因为绿灯给你先行权","等一等，让对面的车先过去","闪一下车灯，然后转弯"],"h1":"绿灯让你可以走，但不代表你前面的路是空的。","h2":"左转时，你必须让对面来的车先走，所以要等那辆车过去、路上安全了再转。","p":"对。左转时，让对面来的车先走。"},"vi":{"q":"Ở Florida, bạn muốn rẽ trái khi đèn xanh. Có một xe đang chạy ngược chiều về phía bạn. Bạn làm gì?","o":["Rẽ nhanh trước khi xe đó đến gần","Rẽ, vì đèn xanh cho bạn quyền ưu tiên","Chờ và để xe ngược chiều đi qua trước","Nháy đèn rồi rẽ"],"h1":"Đèn xanh cho phép bạn đi, nhưng không làm đường phía trước trống.","h2":"Khi rẽ trái, bạn phải nhường xe đi ngược chiều, nên bạn chờ xe đó đi qua và đường trống rồi mới rẽ.","p":"Đúng. Khi rẽ trái, hãy để xe ngược chiều đi trước."},"tl":{"q":"Sa Florida, gusto mong kumaliwa sa berdeng ilaw. May kotseng paparating mula sa harap mo. Ano ang gagawin mo?","o":["Kumaliwa agad bago ito makalapit","Kumaliwa, dahil binibigyan ka ng berdeng ilaw ng karapatan sa daan","Maghintay at paunahin ang paparating na kotse","Mag-flash ng ilaw at kumaliwa"],"h1":"Pinapayagan kang umandar ng berdeng ilaw, pero hindi nito nililinis ang daan sa harap mo.","h2":"Kapag kumakaliwa ka, dapat kang magbigay-daan sa paparating na trapiko, kaya maghihintay ka hanggang makalampas ang kotse at malinis ang daan.","p":"Tama. Kapag kumakaliwa, paunahin ang paparating na trapiko."},"ar":{"q":"في Florida، تريد أن تنعطف يسارًا والإشارة خضراء. هناك سيارة قادمة نحوك. ماذا تفعل؟","o":["أنعطف بسرعة قبل أن تقترب","أنعطف، لأن الإشارة الخضراء تعطيني حق المرور","أنتظر وأترك السيارة القادمة تمر أولًا","أومض بالأضواء وأنعطف"],"h1":"الإشارة الخضراء تسمح لك بالتحرك، لكنها لا تجعل الطريق أمامك فارغًا.","h2":"عندما تنعطف يسارًا، يجب أن تعطي حق المرور للسيارات القادمة نحوك، لذلك تنتظر حتى تمر السيارة ويصبح الطريق فارغًا.","p":"صحيح. عند الانعطاف يسارًا، اترك السيارات القادمة نحوك تمر أولًا."},"ht":{"q":"Nan Florida, ou vle vire agòch lè limyè a vèt. Gen yon machin k ap vin sou ou. Kisa ou fè?","o":["Ou vire vit anvan li rive pre","Ou vire, paske limyè vèt la ba ou dwa pou pase anvan","Ou tann epi ou kite machin k ap vin sou ou a pase anvan","Ou flache limyè ou epi ou vire"],"h1":"Yon limyè vèt kite ou ale, men li pa libere wout ki devan ou a.","h2":"Lè w ap vire agòch, ou dwe kite machin k ap vin sou ou yo pase anvan, kidonk ou tann machin nan pase epi wout la lib.","p":"Wi, se sa. Lè w ap vire agòch, kite machin k ap vin sou ou yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-007","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you are pulling out of a driveway onto a street. Who must you yield to?","o":["Only to large trucks","No one, if you use your signal","Only to cars on your left","All cars on the street and all people walking"],"h1":"You are joining a road that others are already using.","h2":"When you enter a street from a driveway or alley, you must yield to every vehicle on the street and to every pedestrian.","p":"Right. Coming out of a driveway, yield to cars and people walking."},"es":{"q":"En Florida, usted sale de una entrada de casa hacia la calle. ¿A quién debe ceder el paso?","o":["Solo a los camiones grandes","A nadie, si usa la direccional","Solo a los carros de su izquierda","A todos los carros de la calle y a todas las personas que caminan"],"h1":"Usted entra a una calle que otros ya están usando.","h2":"Cuando usted entra a una calle desde una entrada de casa o un callejón, debe ceder el paso a todos los vehículos de la calle y a todos los peatones.","p":"Correcto. Al salir de una entrada de casa, ceda el paso a carros y peatones."},"zh":{"q":"在 Florida，你正从私人车道开上街道。你必须给谁让行？","o":["只给大卡车","谁都不用，只要你打了转向灯","只给你左边的车","街上所有的车和所有走路的人"],"h1":"你要开上一条别人已经在用的路。","h2":"从私人车道或小巷开上街道时，你必须让街上的每一辆车和每一个行人先走。","p":"对。从私人车道出来时，要让车和行人先走。"},"vi":{"q":"Ở Florida, bạn đang lái xe từ lối vào nhà ra đường. Bạn phải nhường ai?","o":["Chỉ nhường xe tải lớn","Không ai cả, nếu bạn bật đèn xi nhan","Chỉ nhường xe bên trái","Mọi xe trên đường và mọi người đi bộ"],"h1":"Bạn đang đi vào con đường mà người khác đang dùng.","h2":"Khi bạn từ lối vào nhà hoặc hẻm đi ra đường, bạn phải nhường mọi xe trên đường và mọi người đi bộ.","p":"Đúng. Khi ra từ lối vào nhà, hãy nhường xe và người đi bộ."},"tl":{"q":"Sa Florida, lalabas ka mula sa driveway papunta sa kalye. Kanino ka dapat magbigay-daan?","o":["Sa malalaking trak lang","Wala, kung gagamit ka ng signal","Sa mga kotse lang sa kaliwa mo","Sa lahat ng kotse sa kalye at sa lahat ng taong naglalakad"],"h1":"Papasok ka sa daan na ginagamit na ng iba.","h2":"Kapag pumapasok ka sa kalye mula sa driveway o eskinita, dapat kang magbigay-daan sa bawat sasakyan sa kalye at sa bawat taong naglalakad.","p":"Tama. Paglabas sa driveway, magbigay-daan sa mga kotse at sa mga naglalakad."},"ar":{"q":"في Florida، تخرج بسيارتك من ممر خاص إلى الشارع. لمن يجب أن تعطي حق المرور؟","o":["للشاحنات الكبيرة فقط","لا أحد، إذا استعملت إشارة الانعطاف","للسيارات التي على يساري فقط","لكل السيارات في الشارع ولكل المشاة"],"h1":"أنت تدخل طريقًا يستعمله آخرون الآن.","h2":"عندما تدخل الشارع من ممر خاص أو من زقاق، يجب أن تعطي حق المرور لكل مركبة في الشارع ولكل شخص يمشي.","p":"صحيح. عند الخروج من ممر خاص، أعطِ حق المرور للسيارات وللمشاة."},"ht":{"q":"Nan Florida, w ap sòti nan antre yon kay pou antre nan yon lari. Kiyès ou dwe kite pase anvan?","o":["Sèlman gwo kamyon","Pèsonn, si ou mete siyal ou","Sèlman machin ki sou bò gòch ou","Tout machin ki nan lari a ak tout moun k ap mache a pye"],"h1":"W ap antre sou yon wout lòt moun deja ap sèvi.","h2":"Lè w ap antre nan yon lari sòti nan antre yon kay oswa nan yon ti ri, ou dwe kite tout machin ki nan lari a ak tout moun k ap mache a pye pase anvan.","p":"Wi, se sa. Lè w ap sòti nan antre yon kay, kite machin yo ak moun k ap mache yo pase anvan."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-008","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you drive out of an alley. There is a sidewalk before the street. Where must you stop?","o":["Before you cross the sidewalk","In the middle of the sidewalk","At the edge of the street, past the sidewalk","You do not need to stop"],"h1":"Think about people who may be walking on the sidewalk.","h2":"When you come out of an alley or driveway, you must stop before the sidewalk, so you do not hit someone walking there.","p":"Right. Stop before the sidewalk when you leave an alley or driveway."},"es":{"q":"En Florida, usted sale de un callejón. Hay una acera antes de la calle. ¿Dónde debe parar?","o":["Antes de cruzar la acera","En medio de la acera","En el borde de la calle, después de la acera","No necesita parar"],"h1":"Piense en las personas que pueden ir caminando por la acera.","h2":"Cuando usted sale de un callejón o de una entrada de casa, debe parar antes de la acera, para no golpear a alguien que camina por ahí.","p":"Correcto. Pare antes de la acera al salir de un callejón o entrada."},"zh":{"q":"在 Florida，你从小巷开出来。到街道前有一段人行道。你必须在哪里停车？","o":["在穿过人行道之前","在人行道中间","在街道边上，过了人行道以后","你不需要停车"],"h1":"想一想可能正在人行道上走路的人。","h2":"从小巷或私人车道开出来时，你必须在人行道前停车，这样才不会撞到在那里走路的人。","p":"对。离开小巷或私人车道时，要在人行道前停车。"},"vi":{"q":"Ở Florida, bạn lái xe ra khỏi một con hẻm. Trước đường có vỉa hè. Bạn phải dừng ở đâu?","o":["Trước khi đi qua vỉa hè","Ở giữa vỉa hè","Ở mép đường, sau vỉa hè","Bạn không cần dừng"],"h1":"Hãy nghĩ đến những người có thể đang đi trên vỉa hè.","h2":"Khi ra khỏi hẻm hoặc lối vào nhà, bạn phải dừng trước vỉa hè, để không đụng vào người đang đi bộ ở đó.","p":"Đúng. Hãy dừng trước vỉa hè khi ra khỏi hẻm hoặc lối vào nhà."},"tl":{"q":"Sa Florida, lumabas ka mula sa eskinita. May bangketa bago ang kalye. Saan ka dapat huminto?","o":["Bago ka tumawid sa bangketa","Sa gitna ng bangketa","Sa gilid ng kalye, lampas sa bangketa","Hindi mo kailangang huminto"],"h1":"Isipin ang mga taong maaaring naglalakad sa bangketa.","h2":"Kapag lumalabas ka mula sa eskinita o driveway, dapat kang huminto bago ang bangketa, para hindi ka makabangga ng taong naglalakad doon.","p":"Tama. Huminto bago ang bangketa kapag lumalabas sa eskinita o driveway."},"ar":{"q":"في Florida، تخرج بسيارتك من زقاق. يوجد رصيف قبل الشارع. أين يجب أن تتوقف؟","o":["قبل أن أعبر الرصيف","في وسط الرصيف","عند طرف الشارع، بعد الرصيف","لا أحتاج إلى التوقف"],"h1":"فكّر في الناس الذين قد يمشون على الرصيف.","h2":"عندما تخرج من زقاق أو ممر خاص، يجب أن تتوقف قبل الرصيف، حتى لا تصدم شخصًا يمشي هناك.","p":"صحيح. توقف قبل الرصيف عندما تخرج من زقاق أو ممر خاص."},"ht":{"q":"Nan Florida, w ap sòti nan yon ti ri. Gen yon twotwa anvan lari a. Ki kote ou dwe kanpe?","o":["Anvan ou travèse twotwa a","Nan mitan twotwa a","Bò lari a, apre twotwa a","Ou pa bezwen kanpe"],"h1":"Panse ak moun ki ka ap mache sou twotwa a.","h2":"Lè w ap sòti nan yon ti ri oswa nan antre yon kay, ou dwe kanpe anvan twotwa a, pou ou pa frape yon moun k ap mache la.","p":"Wi, se sa. Kanpe anvan twotwa a lè w ap sòti nan yon ti ri oswa nan antre yon kay."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-009","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a person is crossing at a corner with no painted crosswalk lines. Must you yield?","o":["No, only painted crosswalks count","Yes, the corner of an intersection is a crosswalk even without lines","Only if the person is a child","Only if a police officer is there"],"h1":"A crosswalk does not always have paint.","h2":"Every corner of an intersection has a crosswalk even when no lines are painted, so you must yield to the person crossing.","p":"Right. Yield to people crossing at a corner, with or without lines."},"es":{"q":"En Florida, una persona cruza en una esquina sin líneas pintadas de cruce peatonal. ¿Debe usted ceder el paso?","o":["No, solo cuentan los cruces pintados","Sí, la esquina de una intersección es un cruce peatonal aunque no tenga líneas","Solo si la persona es un niño","Solo si hay un policía"],"h1":"Un cruce peatonal no siempre tiene pintura.","h2":"Cada esquina de una intersección tiene un cruce peatonal aunque no tenga líneas pintadas, así que usted debe ceder el paso a la persona que cruza.","p":"Correcto. Ceda el paso a quien cruza en la esquina, con o sin líneas."},"zh":{"q":"在 Florida，有人在一个没有画人行横道线的路口拐角过马路。你必须让行吗？","o":["不用，只有画了线的人行横道才算","要，路口的拐角就算没有画线，也是人行横道","只有过马路的是小孩时才要","只有警察在场时才要"],"h1":"人行横道不一定都画了线。","h2":"路口的每个拐角都有人行横道，就算没有画线也一样，所以你必须让过马路的人先走。","p":"对。不管有没有画线，都要让在拐角过马路的人先走。"},"vi":{"q":"Ở Florida, một người đang băng qua đường ở góc giao lộ không có vạch kẻ cho người đi bộ. Bạn có phải nhường không?","o":["Không, chỉ chỗ có vạch kẻ mới tính","Có, góc giao lộ là lối qua đường dù không có vạch kẻ","Chỉ khi người đó là trẻ em","Chỉ khi có cảnh sát ở đó"],"h1":"Lối qua đường cho người đi bộ không phải lúc nào cũng có sơn.","h2":"Mỗi góc của giao lộ đều có lối qua đường dù không có vạch sơn, nên bạn phải nhường người đang băng qua.","p":"Đúng. Hãy nhường người băng qua ở góc giao lộ, có vạch hay không có vạch."},"tl":{"q":"Sa Florida, may taong tumatawid sa kanto na walang pinturang guhit ng crosswalk. Dapat ka bang magbigay-daan?","o":["Hindi, ang may pinturang crosswalk lang ang binibilang","Oo, ang kanto ng intersection ay crosswalk kahit walang guhit","Kung bata lang ang tao","Kung may pulis lang doon"],"h1":"Hindi laging may pintura ang crosswalk.","h2":"Bawat kanto ng intersection ay may crosswalk kahit walang pinturang guhit, kaya dapat kang magbigay-daan sa taong tumatawid.","p":"Tama. Magbigay-daan sa mga tumatawid sa kanto, may guhit man o wala."},"ar":{"q":"في Florida، شخص يعبر الشارع عند زاوية تقاطع ليس فيها خطوط ممر مشاة مرسومة. هل يجب أن تعطيه حق المرور؟","o":["لا، ممرات المشاة المرسومة فقط هي المهمة","نعم، زاوية التقاطع هي ممر مشاة حتى بدون خطوط","فقط إذا كان الشخص طفلًا","فقط إذا كان هناك شرطي"],"h1":"ممر المشاة ليس مرسومًا دائمًا.","h2":"عند كل زاوية من زوايا التقاطع يوجد ممر مشاة حتى لو لم تكن هناك خطوط مرسومة، لذلك يجب أن تعطي حق المرور للشخص الذي يعبر.","p":"صحيح. أعطِ حق المرور للناس الذين يعبرون عند الزاوية، مع خطوط أو بدونها."},"ht":{"q":"Nan Florida, yon moun ap travèse nan kwen yon kafou ki pa gen liy pasaj pyeton ki pentire. Èske ou dwe kite l pase?","o":["Non, se sèlman pasaj pyeton ki pentire ki konte","Wi, kwen yon kafou se yon pasaj pyeton menm si li pa gen liy","Sèlman si moun nan se yon timoun","Sèlman si gen yon polis la"],"h1":"Yon pasaj pyeton pa toujou gen penti.","h2":"Chak kwen yon kafou gen yon pasaj pyeton menm lè pa gen liy ki pentire, kidonk ou dwe kite moun k ap travèse a pase.","p":"Wi, se sa. Kite moun k ap travèse nan kwen kafou a pase, kit gen liy kit pa gen liy."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-010","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you turn right on a green light. People are crossing the street you are turning into. What do you do?","o":["Drive slowly between them","Honk so they move faster","Stop and let them finish crossing","Turn, because your light is green"],"h1":"Your path crosses their path.","h2":"When you turn, you must yield to people walking in the crosswalk, so you stop and wait until they are out of your way.","p":"Right. When you turn, let people in the crosswalk cross first."},"es":{"q":"En Florida, usted dobla a la derecha con luz verde. Hay personas cruzando la calle a la que usted va a entrar. ¿Qué hace?","o":["Pasa despacio entre ellas","Toca la bocina para que caminen más rápido","Para y las deja terminar de cruzar","Dobla, porque su luz está en verde"],"h1":"Su camino se cruza con el camino de ellas.","h2":"Cuando usted dobla, debe ceder el paso a las personas que caminan en el cruce peatonal, así que para y espera hasta que salgan de su camino.","p":"Correcto. Al doblar, deje cruzar primero a las personas en el cruce peatonal."},"zh":{"q":"在 Florida，你在绿灯时右转。有人正在过你要转进去的那条街。你该怎么做？","o":["从他们中间慢慢开过去","按喇叭让他们走快一点","停车，让他们走完","转弯，因为你是绿灯"],"h1":"你的路线和他们的路线交叉。","h2":"转弯时，你必须让人行横道上的行人先走，所以你要停下来，等他们离开你的路线。","p":"对。转弯时，让人行横道上的人先过。"},"vi":{"q":"Ở Florida, bạn rẽ phải khi đèn xanh. Có người đang băng qua con đường bạn sắp rẽ vào. Bạn làm gì?","o":["Lái chậm len giữa họ","Bấm còi để họ đi nhanh hơn","Dừng lại và để họ qua hết đường","Rẽ, vì đèn của bạn là đèn xanh"],"h1":"Đường đi của bạn cắt ngang đường đi của họ.","h2":"Khi rẽ, bạn phải nhường người đi bộ trên lối qua đường, nên bạn dừng lại và chờ đến khi họ đi khỏi đường của bạn.","p":"Đúng. Khi rẽ, hãy để người trên lối qua đường đi trước."},"tl":{"q":"Sa Florida, kumanan ka sa berdeng ilaw. May mga taong tumatawid sa kalyeng papasukan mo. Ano ang gagawin mo?","o":["Dahan-dahang dumaan sa pagitan nila","Bumusina para bumilis sila","Huminto at hayaan silang matapos tumawid","Kumanan, dahil berde ang ilaw mo"],"h1":"Nagtatagpo ang daan mo at ang daan nila.","h2":"Kapag lumiliko ka, dapat kang magbigay-daan sa mga taong naglalakad sa crosswalk, kaya hihinto ka at maghihintay hanggang wala na sila sa daan mo.","p":"Tama. Kapag lumiliko, paunahing tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، تنعطف يمينًا والإشارة خضراء. هناك أشخاص يعبرون الشارع الذي تدخل إليه. ماذا تفعل؟","o":["أقود ببطء بينهم","أستعمل البوق ليسرعوا","أتوقف وأتركهم ينهون العبور","أنعطف، لأن الإشارة عندي خضراء"],"h1":"طريقك يقطع طريقهم.","h2":"عندما تنعطف، يجب أن تعطي حق المرور للمشاة في ممر المشاة، لذلك تتوقف وتنتظر حتى يبتعدوا عن طريقك.","p":"صحيح. عندما تنعطف، اترك الناس في ممر المشاة يعبرون أولًا."},"ht":{"q":"Nan Florida, ou vire adwat lè limyè a vèt. Gen moun k ap travèse lari kote w ap vire a. Kisa ou fè?","o":["Ou kondi dousman nan mitan yo","Ou klaksonnen pou yo mache pi vit","Ou kanpe epi ou kite yo fin travèse","Ou vire, paske limyè ou a vèt"],"h1":"Chemen pa w la kwaze chemen pa yo a.","h2":"Lè w ap vire, ou dwe kite moun k ap mache nan pasaj pyeton an pase anvan, kidonk ou kanpe epi ou tann yo sòti nan chemen ou.","p":"Wi, se sa. Lè w ap vire, kite moun ki nan pasaj pyeton an travèse anvan."},"ref":{"doc":"FL","page":87}},{"id":"right-of-way-011","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a person with a white cane or a guide dog is crossing the street. What must you do?","o":["Honk to let the person know you are there","Drive around the person carefully","Go if your light is green","Stop and let the person cross"],"h1":"A white cane or guide dog tells you the person may not be able to see you.","h2":"A person who is blind and uses a white cane or a guide dog always has the right of way, so you must stop and let them cross.","p":"Right. Always stop for a person with a white cane or guide dog."},"es":{"q":"En Florida, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Qué debe hacer usted?","o":["Tocar la bocina para avisar que usted está ahí","Pasar alrededor de la persona con cuidado","Seguir si su luz está en verde","Parar y dejar que la persona cruce"],"h1":"Un bastón blanco o un perro guía le indican que la persona tal vez no puede verlo.","h2":"Una persona ciega que usa bastón blanco o perro guía siempre tiene el derecho de paso, así que usted debe parar y dejarla cruzar.","p":"Correcto. Siempre pare por una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，有一个拿白色手杖或带导盲犬的人正在过马路。你必须怎么做？","o":["按喇叭，让这个人知道你在那里","小心地绕过这个人","如果你是绿灯，就开过去","停车，让这个人过马路"],"h1":"白色手杖或导盲犬告诉你，这个人可能看不见你。","h2":"使用白色手杖或导盲犬的盲人永远有先行权，所以你必须停车，让他们过马路。","p":"对。看到拿白色手杖或带导盲犬的人，一定要停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc có chó dẫn đường đang băng qua đường. Bạn phải làm gì?","o":["Bấm còi để người đó biết bạn ở đó","Lái vòng qua người đó một cách cẩn thận","Đi tiếp nếu đèn của bạn là đèn xanh","Dừng lại và để người đó băng qua"],"h1":"Gậy trắng hoặc chó dẫn đường cho bạn biết người đó có thể không nhìn thấy bạn.","h2":"Người khiếm thị dùng gậy trắng hoặc chó dẫn đường luôn có quyền ưu tiên, nên bạn phải dừng lại và để họ băng qua.","p":"Đúng. Luôn dừng lại cho người cầm gậy trắng hoặc có chó dẫn đường."},"tl":{"q":"Sa Florida, may taong may puting tungkod o guide dog na tumatawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para malaman niyang nandiyan ka","Maingat na umiwas sa paligid niya","Umandar kung berde ang ilaw mo","Huminto at hayaan siyang tumawid"],"h1":"Ang puting tungkod o guide dog ay nagsasabing maaaring hindi ka nakikita ng tao.","h2":"Ang taong bulag na gumagamit ng puting tungkod o guide dog ay laging may karapatan sa daan, kaya dapat kang huminto at hayaan siyang tumawid.","p":"Tama. Laging huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يعبر الشارع. ماذا يجب أن تفعل؟","o":["أستعمل البوق حتى يعرف أنني هنا","أقود حوله بحذر","أتحرك إذا كانت الإشارة عندي خضراء","أتوقف وأترك الشخص يعبر"],"h1":"العصا البيضاء أو الكلب المرشد يخبرك أن الشخص قد لا يستطيع أن يراك.","h2":"الشخص الكفيف الذي يستعمل عصا بيضاء أو كلبًا مرشدًا له حق المرور دائمًا، لذلك يجب أن تتوقف وتتركه يعبر.","p":"صحيح. توقف دائمًا لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap travèse lari a. Kisa ou dwe fè?","o":["Ou klaksonnen pou moun nan konnen ou la","Ou fè yon ti detou dousman bò kote moun nan","Ou pase si limyè ou a vèt","Ou kanpe epi ou kite moun nan travèse"],"h1":"Yon baton blan oswa yon chen gid montre ou moun nan ka pa ka wè ou.","h2":"Yon moun ki avèg epi ki sèvi ak yon baton blan oswa yon chen gid toujou gen dwa pou pase anvan, kidonk ou dwe kanpe epi kite l travèse.","p":"Wi, se sa. Toujou kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"right-of-way-012","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are about to enter a roundabout. Who has the right of way?","o":["Traffic already moving inside the roundabout","You, because you are entering","The car on your right that is also entering","The driver who honks first"],"h1":"Think about who is already driving in the circle.","h2":"When you enter a roundabout, you must yield to traffic that is already in the circle, then enter when there is a safe gap.","p":"Right. Yield to cars already in the roundabout."},"es":{"q":"En Florida, usted va a entrar a una rotonda. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va dentro de la rotonda","Usted, porque está entrando","El carro de su derecha que también está entrando","El conductor que toca la bocina primero"],"h1":"Piense en quién ya va manejando dentro del círculo.","h2":"Cuando usted entra a una rotonda, debe ceder el paso al tráfico que ya está en el círculo, y luego entrar cuando haya un espacio seguro.","p":"Correcto. Ceda el paso a los carros que ya están en la rotonda."},"zh":{"q":"在 Florida，你马上要进入环岛。谁有先行权？","o":["已经在环岛里行驶的车","你，因为你正在进入","你右边也正在进入的车","先按喇叭的司机"],"h1":"想一想谁已经在环岛里开车。","h2":"进入环岛时，你必须让已经在环岛里的车先走，等有安全的空隙再进去。","p":"对。让已经在环岛里的车先走。"},"vi":{"q":"Ở Florida, bạn sắp đi vào vòng xuyến. Ai có quyền ưu tiên?","o":["Xe đang chạy bên trong vòng xuyến","Bạn, vì bạn đang đi vào","Xe bên phải bạn cũng đang đi vào","Người lái bấm còi trước"],"h1":"Hãy nghĩ xem ai đang chạy trong vòng xuyến rồi.","h2":"Khi đi vào vòng xuyến, bạn phải nhường xe đã ở trong vòng xuyến, rồi đi vào khi có khoảng trống an toàn.","p":"Đúng. Hãy nhường xe đã ở trong vòng xuyến."},"tl":{"q":"Sa Florida, papasok ka na sa roundabout. Sino ang may karapatan sa daan?","o":["Ang trapikong umaandar na sa loob ng roundabout","Ikaw, dahil papasok ka","Ang kotse sa kanan mo na papasok din","Ang drayber na unang bumusina"],"h1":"Isipin kung sino na ang nagmamaneho sa loob ng bilog.","h2":"Kapag pumapasok ka sa roundabout, dapat kang magbigay-daan sa trapikong nasa loob na ng bilog, at pumasok kapag may ligtas na puwang.","p":"Tama. Magbigay-daan sa mga kotseng nasa loob na ng roundabout."},"ar":{"q":"في Florida، أنت على وشك أن تدخل دوّارًا. من له حق المرور؟","o":["السيارات التي تسير الآن داخل الدوّار","أنت، لأنك تدخل","السيارة التي على يمينك وتدخل أيضًا","السائق الذي يستعمل البوق أولًا"],"h1":"فكّر في من يقود الآن داخل الدائرة.","h2":"عندما تدخل دوّارًا، يجب أن تعطي حق المرور للسيارات الموجودة داخل الدائرة، ثم تدخل عندما توجد مسافة آمنة.","p":"صحيح. أعطِ حق المرور للسيارات الموجودة داخل الدوّار."},"ht":{"q":"Nan Florida, ou pral antre nan yon wonpwen. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja ap woule anndan wonpwen an","Ou menm, paske w ap antre","Machin ki sou bò dwat ou ki ap antre tou a","Chofè ki klaksonnen an premye a"],"h1":"Panse ak kiyès ki deja ap kondi nan wonn nan.","h2":"Lè w ap antre nan yon wonpwen, ou dwe kite machin ki deja nan wonn nan pase anvan, epi ou antre lè gen yon espas ki san danje.","p":"Wi, se sa. Kite machin ki deja nan wonpwen an pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-013","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Which way do cars travel in a roundabout in the United States?","o":["Clockwise, to the left","Counterclockwise, to the right","Either way the driver picks","Straight across the middle"],"h1":"In the United States, you drive on the right side of the road.","h2":"In a roundabout in the United States, you enter to the right and travel counterclockwise around the center.","p":"Right. In a roundabout, go to the right, counterclockwise."},"es":{"q":"¿Hacia qué lado van los carros en una rotonda en los Estados Unidos?","o":["En el sentido del reloj, hacia la izquierda","En contra del reloj, hacia la derecha","Hacia el lado que el conductor escoja","Derecho por el centro"],"h1":"En los Estados Unidos se maneja por el lado derecho de la calle.","h2":"En una rotonda en los Estados Unidos, usted entra hacia la derecha y da la vuelta en contra del sentido del reloj alrededor del centro.","p":"Correcto. En una rotonda, vaya hacia la derecha, en contra del reloj."},"zh":{"q":"在美国，车在环岛里朝哪个方向行驶？","o":["顺时针，向左","逆时针，向右","司机想走哪边都行","从中间直接穿过去"],"h1":"在美国，车靠道路右边行驶。","h2":"在美国的环岛里，你向右进入，然后绕着中心逆时针行驶。","p":"对。在环岛里，向右走，逆时针方向。"},"vi":{"q":"Ở Hoa Kỳ, xe chạy theo chiều nào trong vòng xuyến?","o":["Theo chiều kim đồng hồ, sang trái","Ngược chiều kim đồng hồ, sang phải","Theo chiều nào người lái chọn cũng được","Đi thẳng qua giữa"],"h1":"Ở Hoa Kỳ, bạn lái xe bên phải đường.","h2":"Trong vòng xuyến ở Hoa Kỳ, bạn đi vào về phía bên phải và chạy ngược chiều kim đồng hồ quanh tâm.","p":"Đúng. Trong vòng xuyến, đi sang phải, ngược chiều kim đồng hồ."},"tl":{"q":"Saang direksiyon umiikot ang mga kotse sa roundabout sa United States?","o":["Kasunod ng ikot ng orasan (clockwise), papuntang kaliwa","Salungat sa ikot ng orasan (counterclockwise), papuntang kanan","Kahit saan, depende sa drayber","Diretso sa gitna"],"h1":"Sa United States, sa kanang bahagi ng daan ka nagmamaneho.","h2":"Sa roundabout sa United States, papasok ka pakanan at iikot nang salungat sa ikot ng orasan (counterclockwise) sa paligid ng gitna.","p":"Tama. Sa roundabout, pumunta pakanan, salungat sa ikot ng orasan."},"ar":{"q":"في أي اتجاه تسير السيارات داخل الدوّار في الولايات المتحدة؟","o":["مع عقارب الساعة، إلى اليسار","عكس عقارب الساعة، إلى اليمين","في أي اتجاه يختاره السائق","مباشرة عبر الوسط"],"h1":"في الولايات المتحدة، تقود على الجانب الأيمن من الطريق.","h2":"في الدوّار في الولايات المتحدة، تدخل إلى اليمين وتسير عكس عقارب الساعة حول الوسط.","p":"صحيح. في الدوّار، اذهب إلى اليمين، عكس عقارب الساعة."},"ht":{"q":"Nan Etazini, nan ki direksyon machin yo woule nan yon wonpwen?","o":["Nan direksyon zegwi mont, sou bò gòch","Kont direksyon zegwi mont, sou bò dwat","Nan direksyon chofè a chwazi a","Tou dwat nan mitan an"],"h1":"Nan Etazini, ou kondi sou bò dwat wout la.","h2":"Nan yon wonpwen nan Etazini, ou antre sou bò dwat epi ou woule kont direksyon zegwi mont toutotou mitan an.","p":"Wi, se sa. Nan yon wonpwen, ale sou bò dwat, kont direksyon zegwi mont."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-014","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, an ambulance with a siren and flashing lights is coming behind you. What do you do?","o":["Speed up to stay ahead of it","Stop right where you are, in your lane","Pull to the nearest edge of the road and stop","Move to the left lane and keep driving"],"h1":"The ambulance needs a clear path. Think about where you can get out of its way.","h2":"When an emergency vehicle comes with a siren and flashing lights, you pull to the nearest edge of the road and stop until it passes.","p":"Right. Pull to the nearest edge and stop for emergency vehicles."},"es":{"q":"En Florida, una ambulancia con sirena y luces intermitentes viene detrás de usted. ¿Qué hace?","o":["Acelera para mantenerse delante","Para donde está, en su carril","Se orilla al borde más cercano de la calle y para","Se pasa al carril izquierdo y sigue manejando"],"h1":"La ambulancia necesita el camino libre. Piense dónde puede quitarse de su camino.","h2":"Cuando viene un vehículo de emergencia con sirena y luces intermitentes, usted se orilla al borde más cercano de la calle y para hasta que pase.","p":"Correcto. Oríllese al borde más cercano y pare para los vehículos de emergencia."},"zh":{"q":"在 Florida，一辆鸣着警笛、闪着灯的救护车从你后面开过来。你该怎么做？","o":["加速，保持在它前面","就在你的车道里原地停下","靠到离你最近的路边，然后停车","换到左边车道，继续开"],"h1":"救护车需要一条畅通的路。想一想你可以躲到哪里。","h2":"当急救车辆鸣着警笛、闪着灯开过来时，你要靠到最近的路边停车，等它过去。","p":"对。遇到急救车辆，靠到最近的路边停车。"},"vi":{"q":"Ở Florida, một xe cứu thương hú còi và nháy đèn đang đến từ phía sau bạn. Bạn làm gì?","o":["Tăng tốc để chạy trước xe đó","Dừng ngay tại chỗ, trong làn của bạn","Tấp vào mép đường gần nhất và dừng lại","Chuyển sang làn trái và tiếp tục chạy"],"h1":"Xe cứu thương cần đường trống. Hãy nghĩ xem bạn có thể tránh ra ở đâu.","h2":"Khi xe khẩn cấp đến với còi hú và đèn nháy, bạn tấp vào mép đường gần nhất và dừng lại cho đến khi xe đó đi qua.","p":"Đúng. Hãy tấp vào mép đường gần nhất và dừng lại cho xe khẩn cấp."},"tl":{"q":"Sa Florida, may ambulansiyang may sirena at kumikislap na ilaw na paparating sa likod mo. Ano ang gagawin mo?","o":["Bumilis para manatiling nauuna rito","Huminto kung nasaan ka, sa lane mo","Tumabi sa pinakamalapit na gilid ng daan at huminto","Lumipat sa kaliwang lane at magpatuloy"],"h1":"Kailangan ng ambulansiya ng malinis na daan. Isipin kung saan ka puwedeng umiwas.","h2":"Kapag may emergency vehicle na may sirena at kumikislap na ilaw, tatabi ka sa pinakamalapit na gilid ng daan at hihinto hanggang makalampas ito.","p":"Tama. Tumabi sa pinakamalapit na gilid at huminto para sa mga emergency vehicle."},"ar":{"q":"في Florida، سيارة إسعاف بصفارة وأضواء وامضة تأتي خلفك. ماذا تفعل؟","o":["أسرع لأبقى أمامها","أتوقف في مكاني، داخل مساري","أتحرك إلى أقرب طرف للطريق وأتوقف","أنتقل إلى المسار الأيسر وأستمر في القيادة"],"h1":"سيارة الإسعاف تحتاج إلى طريق فارغ. فكّر أين يمكنك أن تبتعد عن طريقها.","h2":"عندما تأتي مركبة طوارئ بصفارة وأضواء وامضة، تتحرك إلى أقرب طرف للطريق وتتوقف حتى تمر.","p":"صحيح. تحرك إلى أقرب طرف وتوقف لمركبات الطوارئ."},"ht":{"q":"Nan Florida, yon anbilans ki gen siren ak limyè k ap flache ap vini dèyè ou. Kisa ou fè?","o":["Ou akselere pou rete devan l","Ou kanpe la menm, nan liy ou a","Ou rale sou bò wout ki pi pre a epi ou kanpe","Ou ale nan liy gòch la epi ou kontinye kondi"],"h1":"Anbilans lan bezwen yon chemen ki lib. Panse ak ki kote ou ka sòti nan chemen l.","h2":"Lè yon machin ijans vini ak siren ak limyè k ap flache, ou rale sou bò wout ki pi pre a epi ou kanpe jiskaske li pase.","p":"Wi, se sa. Rale sou bò wout ki pi pre a epi kanpe pou machin ijans yo."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-015","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are in the middle of an intersection when you hear a fire truck siren behind you. What do you do?","o":["Drive through the intersection, then pull to the nearest edge and stop","Stop in the middle of the intersection","Back up out of the intersection","Turn left right away"],"h1":"Stopping inside the intersection can block the fire truck.","h2":"If you are already in an intersection, you keep going through it and then pull to the nearest edge and stop, so you do not block the emergency vehicle.","p":"Right. Clear the intersection first, then pull over and stop."},"es":{"q":"En Florida, usted está en medio de una intersección cuando oye la sirena de un camión de bomberos detrás. ¿Qué hace?","o":["Cruza la intersección y luego se orilla al borde más cercano y para","Para en medio de la intersección","Da reversa para salir de la intersección","Dobla a la izquierda de inmediato"],"h1":"Parar dentro de la intersección puede bloquear al camión de bomberos.","h2":"Si usted ya está en una intersección, sigue hasta cruzarla y luego se orilla al borde más cercano y para, para no bloquear al vehículo de emergencia.","p":"Correcto. Primero salga de la intersección, luego oríllese y pare."},"zh":{"q":"在 Florida，你正在路口中间，听到后面有消防车的警笛声。你该怎么做？","o":["开过路口，然后靠到最近的路边停车","停在路口中间","倒车退出路口","马上左转"],"h1":"停在路口里面可能会挡住消防车。","h2":"如果你已经在路口里，就继续开过去，然后靠到最近的路边停车，这样就不会挡住急救车辆。","p":"对。先开出路口，再靠边停车。"},"vi":{"q":"Ở Florida, bạn đang ở giữa giao lộ thì nghe tiếng còi xe cứu hỏa phía sau. Bạn làm gì?","o":["Chạy qua hết giao lộ, rồi tấp vào mép đường gần nhất và dừng lại","Dừng lại giữa giao lộ","Lùi xe ra khỏi giao lộ","Rẽ trái ngay lập tức"],"h1":"Dừng lại trong giao lộ có thể chắn đường xe cứu hỏa.","h2":"Nếu bạn đã ở trong giao lộ, bạn tiếp tục chạy qua, rồi tấp vào mép đường gần nhất và dừng lại, để không chắn đường xe khẩn cấp.","p":"Đúng. Hãy ra khỏi giao lộ trước, rồi tấp vào lề và dừng lại."},"tl":{"q":"Sa Florida, nasa gitna ka ng intersection nang marinig mo ang sirena ng trak ng bumbero sa likod mo. Ano ang gagawin mo?","o":["Tumawid sa intersection, saka tumabi sa pinakamalapit na gilid at huminto","Huminto sa gitna ng intersection","Umatras palabas ng intersection","Kumaliwa agad"],"h1":"Kapag huminto ka sa loob ng intersection, maaari mong maharangan ang trak ng bumbero.","h2":"Kung nasa intersection ka na, magpatuloy ka hanggang makalabas dito, saka tumabi sa pinakamalapit na gilid at huminto, para hindi mo maharangan ang emergency vehicle.","p":"Tama. Lumabas muna sa intersection, saka tumabi at huminto."},"ar":{"q":"في Florida، أنت في وسط التقاطع وتسمع صفارة سيارة إطفاء خلفك. ماذا تفعل؟","o":["أعبر التقاطع، ثم أتحرك إلى أقرب طرف وأتوقف","أتوقف في وسط التقاطع","أرجع إلى الخلف وأخرج من التقاطع","أنعطف يسارًا فورًا"],"h1":"إذا توقفت داخل التقاطع، قد تسد الطريق على سيارة الإطفاء.","h2":"إذا كنت داخل التقاطع، تستمر حتى تعبره، ثم تتحرك إلى أقرب طرف وتتوقف، حتى لا تسد الطريق على مركبة الطوارئ.","p":"صحيح. اعبر التقاطع أولًا، ثم ابتعد إلى الطرف وتوقف."},"ht":{"q":"Nan Florida, ou nan mitan yon kafou lè ou tande siren yon kamyon ponpye dèyè ou. Kisa ou fè?","o":["Ou travèse kafou a, apre sa ou rale sou bò ki pi pre a epi ou kanpe","Ou kanpe nan mitan kafou a","Ou fè bak pou sòti nan kafou a","Ou vire agòch touswit"],"h1":"Si ou kanpe anndan kafou a, ou ka bloke kamyon ponpye a.","h2":"Si ou deja nan yon kafou, ou kontinye travèse l, apre sa ou rale sou bò ki pi pre a epi ou kanpe, pou ou pa bloke machin ijans lan.","p":"Wi, se sa. Libere kafou a anvan, apre sa rale sou kote epi kanpe."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-016","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a funeral procession is passing through an intersection. What should you do?","o":["Drive between the cars when there is a gap","Join the end of the line","Honk so they move faster","Yield and wait until the whole procession passes"],"h1":"The cars in the procession are traveling together as one group.","h2":"You must yield to a funeral procession and must not cut through it or join it, so you wait until all of it has passed.","p":"Right. Yield to a funeral procession and let it pass."},"es":{"q":"En Florida, un cortejo fúnebre está pasando por una intersección. ¿Qué debe hacer?","o":["Pasar entre los carros cuando haya un espacio","Unirse al final de la fila","Tocar la bocina para que avancen más rápido","Ceder el paso y esperar hasta que pase todo el cortejo"],"h1":"Los carros del cortejo viajan juntos como un solo grupo.","h2":"Usted debe ceder el paso a un cortejo fúnebre y no debe cruzarlo ni unirse a él, así que espera hasta que pase completo.","p":"Correcto. Ceda el paso al cortejo fúnebre y déjelo pasar."},"zh":{"q":"在 Florida，一支送葬车队正在通过路口。你应该怎么做？","o":["趁有空隙，从车队中间开过去","跟在车队最后面","按喇叭让他们走快一点","让行，等整个车队过去"],"h1":"送葬车队里的车是作为一个整体一起走的。","h2":"你必须给送葬车队让行，不能从中间穿过，也不能加入车队，所以要等整个车队都过去。","p":"对。给送葬车队让行，让它过去。"},"vi":{"q":"Ở Florida, một đoàn xe đưa tang đang đi qua giao lộ. Bạn nên làm gì?","o":["Chạy chen vào giữa các xe khi có khoảng trống","Nhập vào cuối đoàn xe","Bấm còi để họ đi nhanh hơn","Nhường đường và chờ cả đoàn xe đi qua"],"h1":"Các xe trong đoàn đưa tang đi cùng nhau như một nhóm.","h2":"Bạn phải nhường đoàn xe đưa tang và không được chen ngang hay nhập vào đoàn, nên bạn chờ đến khi cả đoàn đi qua.","p":"Đúng. Hãy nhường đoàn xe đưa tang và để đoàn đi qua."},"tl":{"q":"Sa Florida, may prusisyon ng libing na dumaraan sa intersection. Ano ang dapat mong gawin?","o":["Sumingit sa pagitan ng mga kotse kapag may puwang","Sumama sa dulo ng hanay","Bumusina para bumilis sila","Magbigay-daan at maghintay hanggang makalampas ang buong prusisyon"],"h1":"Magkakasamang bumibiyahe ang mga kotse sa prusisyon bilang isang grupo.","h2":"Dapat kang magbigay-daan sa prusisyon ng libing at hindi ka dapat sumingit o sumama rito, kaya maghihintay ka hanggang makalampas ang lahat ng ito.","p":"Tama. Magbigay-daan sa prusisyon ng libing at hayaan itong makalampas."},"ar":{"q":"في Florida، موكب جنازة يعبر التقاطع. ماذا يجب أن تفعل؟","o":["أقود بين السيارات عندما توجد فجوة","أنضم إلى آخر الموكب","أستعمل البوق ليسرعوا","أعطي حق المرور وأنتظر حتى يمر الموكب كله"],"h1":"السيارات في الموكب تسير معًا كمجموعة واحدة.","h2":"يجب أن تعطي حق المرور لموكب الجنازة، ولا يجوز أن تقطعه أو تنضم إليه، لذلك تنتظر حتى يمر كله.","p":"صحيح. أعطِ حق المرور لموكب الجنازة واتركه يمر."},"ht":{"q":"Nan Florida, yon kòtèj antèman ap travèse yon kafou. Kisa ou ta dwe fè?","o":["Ou pase nan mitan machin yo lè gen yon espas","Ou antre nan bout liy lan","Ou klaksonnen pou yo ale pi vit","Ou kite yo pase epi ou tann tout kòtèj la fin pase"],"h1":"Machin ki nan kòtèj la ap mache ansanm tankou yon sèl gwoup.","h2":"Ou dwe kite yon kòtèj antèman pase, ou pa dwe koupe l ni antre ladan l, kidonk ou tann jiskaske tout kòtèj la fin pase.","p":"Wi, se sa. Kite yon kòtèj antèman pase."},"ref":{"doc":"FL","page":84}},{"id":"right-of-way-017","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a road with two lanes going your way. What must you do?","o":["Keep your speed and stay in your lane","Move out of the lane closest to the police car if it is safe","Stop next to the police car","Honk as you pass"],"h1":"Florida's Move Over law asks you to give stopped workers more space.","h2":"Under Florida's Move Over law, you must leave the lane closest to the stopped emergency vehicle when it is safe to change lanes.","p":"Right. Move over a lane for a stopped emergency vehicle."},"es":{"q":"En Florida, una patrulla de policía está parada en el acotamiento con las luces intermitentes. Usted va por una calle con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y seguir en su carril","Salir del carril más cercano a la patrulla si es seguro","Parar al lado de la patrulla","Tocar la bocina al pasar"],"h1":"La ley Move Over de Florida le pide dar más espacio a quienes están parados trabajando.","h2":"Según la ley Move Over de Florida, usted debe salir del carril más cercano al vehículo de emergencia parado cuando sea seguro cambiar de carril.","p":"Correcto. Cámbiese de carril para un vehículo de emergencia parado."},"zh":{"q":"在 Florida，一辆警车停在路肩上，车灯在闪。你所在的路，你的方向有两条车道。你必须怎么做？","o":["保持车速，留在你的车道里","如果安全，离开最靠近警车的那条车道","停在警车旁边","经过时按喇叭"],"h1":"Florida 的 Move Over 法要求你给停在路边工作的人多留空间。","h2":"根据 Florida 的 Move Over 法，在可以安全换道时，你必须离开最靠近停着的急救车辆的那条车道。","p":"对。遇到停着的急救车辆，要让出一条车道。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Đường của bạn có hai làn cùng chiều. Bạn phải làm gì?","o":["Giữ tốc độ và ở lại trong làn của bạn","Rời khỏi làn gần xe cảnh sát nhất nếu an toàn","Dừng lại cạnh xe cảnh sát","Bấm còi khi chạy qua"],"h1":"Luật \"Move Over\" của Florida yêu cầu bạn chừa thêm chỗ cho người đang làm việc bên đường.","h2":"Theo luật \"Move Over\" của Florida, bạn phải rời khỏi làn gần xe khẩn cấp đang dừng nhất khi đổi làn an toàn.","p":"Đúng. Hãy chuyển sang làn khác khi có xe khẩn cấp đang dừng."},"tl":{"q":"Sa Florida, may kotse ng pulis na nakahinto sa shoulder (gilid ng daan) na kumikislap ang ilaw. Nasa daan ka na may dalawang lane papunta sa direksiyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Umalis sa lane na pinakamalapit sa kotse ng pulis kung ligtas","Huminto sa tabi ng kotse ng pulis","Bumusina habang dumaraan"],"h1":"Hinihiling ng Move Over law ng Florida na bigyan mo ng mas malaking espasyo ang mga nakahintong manggagawa.","h2":"Ayon sa Move Over law ng Florida, dapat mong iwan ang lane na pinakamalapit sa nakahintong emergency vehicle kapag ligtas lumipat ng lane.","p":"Tama. Lumipat ng isang lane para sa nakahintong emergency vehicle."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["أحافظ على سرعتي وأبقى في مساري","أترك المسار الأقرب إلى سيارة الشرطة إذا كان ذلك آمنًا","أتوقف بجانب سيارة الشرطة","أستعمل البوق وأنا أمر"],"h1":"قانون Move Over في Florida يطلب منك أن تعطي العاملين المتوقفين مساحة أكبر.","h2":"حسب قانون Move Over في Florida، يجب أن تترك المسار الأقرب إلى مركبة الطوارئ المتوقفة عندما يكون تغيير المسار آمنًا.","p":"صحيح. ابتعد مسارًا واحدًا عن مركبة الطوارئ المتوقفة."},"ht":{"q":"Nan Florida, yon machin polis kanpe sou bò wout la ak limyè l ap flache. Ou sou yon wout ki gen de liy k ap ale nan menm direksyon ak ou. Kisa ou dwe fè?","o":["Ou kenbe menm vitès la epi ou rete nan liy ou","Ou sòti nan liy ki pi pre machin polis la si sa pa danjere","Ou kanpe bò kote machin polis la","Ou klaksonnen lè w ap pase"],"h1":"Lwa Move Over Florida a mande ou bay moun k ap travay epi ki kanpe yo plis espas.","h2":"Dapre lwa Move Over Florida a, ou dwe kite liy ki pi pre machin ijans ki kanpe a lè ou ka chanje liy san danje.","p":"Wi, se sa. Chanje liy pou yon machin ijans ki kanpe."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-018","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you cannot safely move over for a stopped emergency vehicle. The speed limit is 55 mph. What must you do?","o":["Keep driving at 55 mph","Stop in your lane","Slow to 20 mph below the limit, so 35 mph","Speed up to pass it quickly"],"h1":"If you cannot move over, the law asks for a big cut in speed.","h2":"When you cannot move over, Florida law says you must slow to 20 mph below the posted speed limit, so on a 55 mph road you slow to 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril con seguridad para un vehículo de emergencia parado. El límite de velocidad es 55 mph. ¿Qué debe hacer?","o":["Seguir manejando a 55 mph","Parar en su carril","Bajar a 20 mph menos que el límite, o sea 35 mph","Acelerar para pasarlo rápido"],"h1":"Si no puede cambiarse de carril, la ley le pide bajar mucho la velocidad.","h2":"Cuando usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 20 mph menos que el límite marcado, así que en una calle de 55 mph baja a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph del límite."},"zh":{"q":"在 Florida，你没办法安全地给停着的急救车辆让出车道。限速是 55 英里/小时。你必须怎么做？","o":["继续以 55 英里/小时行驶","停在你的车道里","减速到比限速低 20 英里/小时，也就是 35 英里/小时","加速，快点开过去"],"h1":"如果你不能换道，法律要求你大幅减速。","h2":"不能换道时，Florida 法律规定你必须减速到比限速低 20 英里/小时，所以在限速 55 英里/小时的路上，你要减到 35 英里/小时。","p":"对。不能换道时，要减速到比限速低 20 英里/小时。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn an toàn để tránh một xe khẩn cấp đang dừng. Giới hạn tốc độ là 55 mph. Bạn phải làm gì?","o":["Tiếp tục chạy 55 mph","Dừng lại trong làn của bạn","Giảm xuống thấp hơn giới hạn 20 mph, tức là 35 mph","Tăng tốc để vượt qua nhanh"],"h1":"Nếu không thể chuyển làn, luật yêu cầu bạn giảm tốc độ nhiều.","h2":"Khi không thể chuyển làn, luật Florida nói bạn phải giảm xuống thấp hơn giới hạn tốc độ 20 mph, nên trên đường 55 mph bạn giảm xuống 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka ligtas na makalipat ng lane para sa nakahintong emergency vehicle. Ang speed limit ay 55 mph. Ano ang dapat mong gawin?","o":["Magpatuloy sa 55 mph","Huminto sa lane mo","Bumagal sa 20 mph na mas mababa sa limit, kaya 35 mph","Bumilis para madaanan ito agad"],"h1":"Kung hindi ka makalipat, malaking bawas sa bilis ang hinihingi ng batas.","h2":"Kapag hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na speed limit, kaya sa daang 55 mph, bababa ka sa 35 mph.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد بأمان عن مركبة طوارئ متوقفة. حد السرعة 55 ميلًا في الساعة. ماذا يجب أن تفعل؟","o":["أستمر بسرعة 55 ميلًا في الساعة","أتوقف في مساري","أخفف السرعة إلى 20 ميلًا في الساعة أقل من الحد، أي 35 ميلًا في الساعة","أسرع لأتجاوزها بسرعة"],"h1":"إذا لم تستطع أن تبتعد، يطلب القانون تخفيضًا كبيرًا في السرعة.","h2":"عندما لا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 20 ميلًا في الساعة أقل من حد السرعة المكتوب، لذلك على طريق حده 55 ميلًا في الساعة تخفف إلى 35 ميلًا في الساعة.","p":"صحيح. إذا لم تستطع أن تبتعد، خفف السرعة إلى 20 ميلًا في الساعة أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy san danje pou yon machin ijans ki kanpe. Limit vitès la se 55 mph. Kisa ou dwe fè?","o":["Ou kontinye kondi a 55 mph","Ou kanpe nan liy ou","Ou ralanti pou ou desann 20 mph anba limit la, sa vle di 35 mph","Ou akselere pou pase l vit"],"h1":"Si ou pa ka chanje liy, lwa a mande ou bese vitès ou anpil.","h2":"Lè ou pa ka chanje liy, lwa Florida di ou dwe ralanti pou ou desann 20 mph anba limit vitès ki afiche a, kidonk sou yon wout 55 mph ou desann a 35 mph.","p":"Wi, se sa. Si ou pa ka chanje liy, desann 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-019","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, the speed limit is 20 mph. A tow truck is stopped with its lights flashing, and you cannot move over. How fast may you pass it?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Twenty below the limit would be zero, so the law gives a special number.","h2":"When the speed limit is 20 mph or less and you cannot move over, Florida law says you must slow to 5 mph.","p":"Right. On a road of 20 mph or less, slow to 5 mph."},"es":{"q":"En Florida, el límite de velocidad es 20 mph. Una grúa está parada con las luces intermitentes y usted no puede cambiarse de carril. ¿A qué velocidad puede pasarla?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Veinte menos que el límite sería cero, así que la ley da un número especial.","h2":"Cuando el límite es 20 mph o menos y usted no puede cambiarse de carril, la ley de Florida dice que debe bajar a 5 mph.","p":"Correcto. En una calle de 20 mph o menos, baje a 5 mph."},"zh":{"q":"在 Florida，限速是 20 英里/小时。一辆拖车停着，车灯在闪，你又没办法换道。你最快可以用多少速度经过它？","o":["5 英里/小时","15 英里/小时","20 英里/小时","10 英里/小时"],"h1":"比限速低 20 就变成零了，所以法律给了一个特别的数字。","h2":"当限速是 20 英里/小时或更低，而你又不能换道时，Florida 法律规定你必须减速到 5 英里/小时。","p":"对。在限速 20 英里/小时或更低的路上，要减速到 5 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ là 20 mph. Một xe kéo đang dừng và nháy đèn, và bạn không thể chuyển làn. Bạn được chạy qua với tốc độ bao nhiêu?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Thấp hơn giới hạn 20 thì sẽ là số không, nên luật đưa ra một con số riêng.","h2":"Khi giới hạn tốc độ là 20 mph hoặc thấp hơn và bạn không thể chuyển làn, luật Florida nói bạn phải giảm xuống 5 mph.","p":"Đúng. Trên đường 20 mph hoặc thấp hơn, hãy giảm xuống 5 mph."},"tl":{"q":"Sa Florida, 20 mph ang speed limit. May tow truck na nakahinto na kumikislap ang ilaw, at hindi ka makalipat ng lane. Gaano kabilis ka puwedeng dumaan?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Kung babawasan ng dalawampu ang limit, magiging zero ito, kaya may espesyal na numero ang batas.","h2":"Kapag 20 mph o mas mababa ang speed limit at hindi ka makalipat ng lane, sinasabi ng batas ng Florida na dapat kang bumagal sa 5 mph.","p":"Tama. Sa daang 20 mph o mas mababa, bumagal sa 5 mph."},"ar":{"q":"في Florida، حد السرعة 20 ميلًا في الساعة. شاحنة سحب متوقفة وأضواؤها تومض، ولا تستطيع أن تبتعد عنها. بأي سرعة يمكنك أن تمر بجانبها؟","o":["5 أميال في الساعة","15 ميلًا في الساعة","20 ميلًا في الساعة","10 أميال في الساعة"],"h1":"عشرون أقل من الحد تساوي صفرًا، لذلك يعطي القانون رقمًا خاصًا.","h2":"عندما يكون حد السرعة 20 ميلًا في الساعة أو أقل ولا تستطيع أن تبتعد، يقول قانون Florida إنه يجب أن تخفف السرعة إلى 5 أميال في الساعة.","p":"صحيح. على طريق حده 20 ميلًا في الساعة أو أقل، خفف السرعة إلى 5 أميال في الساعة."},"ht":{"q":"Nan Florida, limit vitès la se 20 mph. Yon kamyon remòk kanpe ak limyè l ap flache, epi ou pa ka chanje liy. Ak ki vitès ou ka pase bò kote l?","o":["5 mph","15 mph","20 mph","10 mph"],"h1":"Ven anba limit la ta bay zewo, kidonk lwa a bay yon chif espesyal.","h2":"Lè limit vitès la se 20 mph oswa mwens epi ou pa ka chanje liy, lwa Florida di ou dwe desann a 5 mph.","p":"Wi, se sa. Sou yon wout 20 mph oswa mwens, desann a 5 mph."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-020","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, which of these stopped vehicles is covered by the Move Over law?","o":["A parked car with no lights on","A city bus at a bus stop","A delivery van at a store","A garbage truck with its warning lights flashing"],"h1":"The law covers workers on the road who show flashing warning lights.","h2":"Florida's Move Over law covers sanitation trucks, utility trucks, tow trucks, and road crews when they are stopped with warning lights flashing, so you must move over or slow down.","p":"Right. Move over for a stopped garbage truck with flashing lights."},"es":{"q":"En Florida, ¿cuál de estos vehículos parados está cubierto por la ley Move Over?","o":["Un carro estacionado sin luces encendidas","Un autobús de la ciudad en una parada","Una camioneta de reparto frente a una tienda","Un camión de basura con las luces de advertencia intermitentes"],"h1":"La ley cubre a trabajadores en la vía que muestran luces de advertencia intermitentes.","h2":"La ley Move Over de Florida cubre camiones de basura, de servicios públicos, grúas y equipos de carretera cuando están parados con luces de advertencia intermitentes, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril por un camión de basura parado con luces intermitentes."},"zh":{"q":"在 Florida，下面哪一辆停着的车受 Move Over 法保护？","o":["一辆没开灯的停放汽车","一辆停在车站的公交车","一辆停在商店门口的送货车","一辆闪着警示灯的垃圾车"],"h1":"这条法律保护在路上工作、并闪着警示灯的人。","h2":"Florida 的 Move Over 法保护停着并闪着警示灯的环卫车、公用事业车、拖车和道路施工人员，所以你必须换道或减速。","p":"对。遇到闪着灯停着的垃圾车，要让出车道。"},"vi":{"q":"Ở Florida, xe nào sau đây khi đang dừng thì thuộc luật \"Move Over\"?","o":["Xe hơi đậu không bật đèn","Xe buýt thành phố ở trạm xe buýt","Xe giao hàng ở cửa hàng","Xe rác đang nháy đèn cảnh báo"],"h1":"Luật này bảo vệ người làm việc trên đường có đèn cảnh báo nhấp nháy.","h2":"Luật \"Move Over\" của Florida áp dụng cho xe rác, xe của công ty điện nước, xe kéo và đội sửa đường khi họ dừng và nháy đèn cảnh báo, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn khi có xe rác đang dừng và nháy đèn."},"tl":{"q":"Sa Florida, alin sa mga nakahintong sasakyang ito ang sakop ng Move Over law?","o":["Nakaparadang kotse na walang ilaw","Bus ng lungsod sa bus stop","Delivery van sa harap ng tindahan","Trak ng basura na kumikislap ang warning lights"],"h1":"Sakop ng batas ang mga manggagawa sa daan na nagpapakita ng kumikislap na warning lights.","h2":"Sakop ng Move Over law ng Florida ang mga trak ng basura, trak ng utility, tow truck, at mga road crew kapag nakahinto sila na kumikislap ang warning lights, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane para sa nakahintong trak ng basura na kumikislap ang ilaw."},"ar":{"q":"في Florida، أي مركبة متوقفة من هذه المركبات يشملها قانون Move Over؟","o":["سيارة مركونة وأضواؤها مطفأة","حافلة مدينة عند محطة الحافلات","شاحنة توصيل صغيرة عند متجر","شاحنة نفايات أضواء التحذير فيها تومض"],"h1":"القانون يشمل العاملين على الطريق الذين يُظهرون أضواء تحذير وامضة.","h2":"قانون Move Over في Florida يشمل شاحنات النفايات، وشاحنات المرافق، وشاحنات السحب، وعمال الطرق عندما يتوقفون وأضواء التحذير تومض، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد عن شاحنة نفايات متوقفة أضواؤها تومض."},"ht":{"q":"Nan Florida, kiyès nan machin ki kanpe sa yo lwa Move Over la kouvri?","o":["Yon machin ki pake san limyè limen","Yon bis vil ki kanpe nan yon arè bis","Yon kamyonèt livrezon devan yon magazen","Yon kamyon fatra ki gen limyè avètisman l ap flache"],"h1":"Lwa a kouvri moun k ap travay sou wout la ki montre limyè avètisman k ap flache.","h2":"Lwa Move Over Florida a kouvri kamyon fatra, kamyon sèvis piblik, kamyon remòk ak ekip k ap travay sou wout la lè yo kanpe ak limyè avètisman k ap flache, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy pou yon kamyon fatra ki kanpe ak limyè k ap flache."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-021","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a car is stopped on the shoulder with its hazard lights flashing. Does the Move Over law apply?","o":["No, it is only for police and ambulances","Yes, move over or slow down as you would for an emergency vehicle","Only at night","Only on toll roads"],"h1":"Florida widened the Move Over law to protect more people stopped by the road.","h2":"Florida's Move Over law also covers a disabled vehicle that is stopped and showing hazard lights or other warning signs, so you must move over or slow down.","p":"Right. Move over or slow down for a stopped car with hazard lights."},"es":{"q":"En Florida, un carro está parado en el acotamiento con las luces de emergencia encendidas. ¿Se aplica la ley Move Over?","o":["No, es solo para policías y ambulancias","Sí, cámbiese de carril o baje la velocidad como para un vehículo de emergencia","Solo de noche","Solo en carreteras de peaje"],"h1":"Florida amplió la ley Move Over para proteger a más personas paradas en la orilla.","h2":"La ley Move Over de Florida también cubre a un vehículo descompuesto que está parado y muestra luces de emergencia u otras señales de advertencia, así que usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cámbiese de carril o baje la velocidad por un carro parado con luces de emergencia."},"zh":{"q":"在 Florida，一辆车停在路肩上，开着双闪灯。Move Over 法适用吗？","o":["不适用，它只针对警车和救护车","适用，要像遇到急救车辆一样换道或减速","只在晚上适用","只在收费公路上适用"],"h1":"Florida 扩大了 Move Over 法，保护更多停在路边的人。","h2":"Florida 的 Move Over 法也保护停着并开着双闪灯或有其他警示的故障车，所以你必须换道或减速。","p":"对。遇到开着双闪灯停着的车，要换道或减速。"},"vi":{"q":"Ở Florida, một xe hơi đang dừng trên lề và bật đèn khẩn cấp nhấp nháy. Luật \"Move Over\" có áp dụng không?","o":["Không, luật chỉ dành cho cảnh sát và xe cứu thương","Có, hãy chuyển làn hoặc giảm tốc như với xe khẩn cấp","Chỉ vào ban đêm","Chỉ trên đường thu phí"],"h1":"Florida đã mở rộng luật \"Move Over\" để bảo vệ thêm nhiều người dừng bên đường.","h2":"Luật \"Move Over\" của Florida cũng áp dụng cho xe bị hỏng đang dừng và bật đèn khẩn cấp hoặc dấu hiệu cảnh báo khác, nên bạn phải chuyển làn hoặc giảm tốc.","p":"Đúng. Hãy chuyển làn hoặc giảm tốc khi có xe dừng bật đèn khẩn cấp."},"tl":{"q":"Sa Florida, may kotseng nakahinto sa shoulder na kumikislap ang hazard lights. Sakop ba ito ng Move Over law?","o":["Hindi, para lang ito sa pulis at ambulansiya","Oo, lumipat ng lane o bumagal gaya ng gagawin mo para sa emergency vehicle","Sa gabi lang","Sa toll road lang"],"h1":"Pinalawak ng Florida ang Move Over law para protektahan ang mas maraming taong nakahinto sa tabi ng daan.","h2":"Sakop din ng Move Over law ng Florida ang sirang sasakyan na nakahinto at nagpapakita ng hazard lights o iba pang babala, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Lumipat ng lane o bumagal para sa nakahintong kotse na may hazard lights."},"ar":{"q":"في Florida، سيارة متوقفة على كتف الطريق وأضواء الخطر فيها تومض. هل ينطبق قانون Move Over؟","o":["لا، هو للشرطة وسيارات الإسعاف فقط","نعم، ابتعد أو خفف السرعة كما تفعل لمركبة طوارئ","فقط في الليل","فقط على الطرق التي فيها رسوم"],"h1":"Florida وسّعت قانون Move Over لتحمي عددًا أكبر من الناس المتوقفين بجانب الطريق.","h2":"قانون Move Over في Florida يشمل أيضًا المركبة المعطلة المتوقفة التي تُظهر أضواء الخطر أو علامات تحذير أخرى، لذلك يجب أن تبتعد أو تخفف السرعة.","p":"صحيح. ابتعد أو خفف السرعة لسيارة متوقفة أضواء الخطر فيها تعمل."},"ht":{"q":"Nan Florida, yon machin kanpe sou bò wout la ak limyè ijans li (flachè) k ap flache. Èske lwa Move Over la aplike?","o":["Non, se sèlman pou polis ak anbilans","Wi, chanje liy oswa ralanti menm jan ou ta fè pou yon machin ijans","Sèlman lannwit","Sèlman sou wout peyan"],"h1":"Florida te elaji lwa Move Over la pou pwoteje plis moun ki kanpe bò wout la.","h2":"Lwa Move Over Florida a kouvri tou yon machin ki an pàn epi ki kanpe ak limyè ijans oswa lòt siy avètisman, kidonk ou dwe chanje liy oswa ralanti.","p":"Wi, se sa. Chanje liy oswa ralanti pou yon machin ki kanpe ak limyè ijans li."},"ref":{"doc":"FL","page":65}},{"id":"right-of-way-022","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, on a two-way road, a school bus ahead is stopped with its stop arm out. You are coming from the other direction. What do you do?","o":["Slow down and pass with care","Keep going, because you are on the other side","Stop and stay stopped","Honk and pass"],"h1":"On a two-way road with no median, the rule is the same for both directions.","h2":"On a two-way road, traffic going both ways must stop for a school bus that shows its stop signal, so you stop even when coming from the other side.","p":"Right. On a two-way road, both directions stop for a stopped school bus."},"es":{"q":"En Florida, en una calle de doble sentido, un autobús escolar adelante está parado con el brazo de pare afuera. Usted viene en la dirección contraria. ¿Qué hace?","o":["Baja la velocidad y pasa con cuidado","Sigue, porque usted va del otro lado","Para y se queda parado","Toca la bocina y pasa"],"h1":"En una calle de doble sentido sin división, la regla es igual para las dos direcciones.","h2":"En una calle de doble sentido, el tráfico de las dos direcciones debe parar ante un autobús escolar que muestra su señal de pare, así que usted para aunque venga del otro lado.","p":"Correcto. En calle de doble sentido, las dos direcciones paran por el autobús escolar."},"zh":{"q":"在 Florida，在一条双向道路上，前面一辆校车停着，伸出了停车臂。你从对面方向开过来。你该怎么做？","o":["减速，小心地开过去","继续开，因为你在另一边","停车，并保持停着","按喇叭，然后开过去"],"h1":"在没有中间隔离带的双向道路上，两个方向的规则是一样的。","h2":"在双向道路上，两个方向的车都必须为亮出停车信号的校车停车，所以就算你从对面来，也要停车。","p":"对。在双向道路上，两个方向都要为停着的校车停车。"},"vi":{"q":"Ở Florida, trên đường hai chiều, xe buýt trường học phía trước đang dừng và giơ cần biển \"STOP\". Bạn đến từ hướng ngược lại. Bạn làm gì?","o":["Giảm tốc và chạy qua cẩn thận","Tiếp tục chạy, vì bạn ở phía bên kia","Dừng lại và giữ nguyên ở đó","Bấm còi và chạy qua"],"h1":"Trên đường hai chiều không có dải phân cách, quy tắc giống nhau cho cả hai hướng.","h2":"Trên đường hai chiều, xe đi cả hai hướng đều phải dừng khi xe buýt trường học bật tín hiệu dừng, nên bạn phải dừng dù đến từ phía bên kia.","p":"Đúng. Trên đường hai chiều, cả hai hướng đều dừng cho xe buýt trường học đang dừng."},"tl":{"q":"Sa Florida, sa daang two-way, may school bus sa unahan na nakahinto at nakalabas ang stop arm. Galing ka sa kabilang direksiyon. Ano ang gagawin mo?","o":["Bumagal at dumaan nang maingat","Magpatuloy, dahil nasa kabilang panig ka","Huminto at manatiling nakahinto","Bumusina at dumaan"],"h1":"Sa daang two-way na walang median, pareho ang patakaran sa dalawang direksiyon.","h2":"Sa daang two-way, dapat huminto ang trapiko sa dalawang direksiyon para sa school bus na nagpapakita ng stop signal, kaya hihinto ka kahit galing ka sa kabilang panig.","p":"Tama. Sa daang two-way, humihinto ang dalawang direksiyon para sa nakahintong school bus."},"ar":{"q":"في Florida، على طريق باتجاهين، حافلة مدرسية أمامك متوقفة وذراع التوقف فيها مفتوح. أنت قادم من الاتجاه الآخر. ماذا تفعل؟","o":["أخفف السرعة وأمر بحذر","أستمر، لأنني على الجانب الآخر","أتوقف وأبقى متوقفًا","أستعمل البوق وأمر"],"h1":"على طريق باتجاهين بدون فاصل في الوسط، القاعدة هي نفسها في الاتجاهين.","h2":"على طريق باتجاهين، يجب على السيارات في الاتجاهين أن تتوقف لحافلة مدرسية تُظهر إشارة التوقف، لذلك تتوقف حتى لو كنت قادمًا من الجانب الآخر.","p":"صحيح. على طريق باتجاهين، يتوقف الاتجاهان لحافلة مدرسية متوقفة."},"ht":{"q":"Nan Florida, sou yon wout de sans, gen yon bis lekòl devan ki kanpe ak bra \"STOP\" li louvri. W ap vini nan lòt direksyon an. Kisa ou fè?","o":["Ou ralanti epi ou pase avèk atansyon","Ou kontinye, paske ou sou lòt bò a","Ou kanpe epi ou rete kanpe","Ou klaksonnen epi ou pase"],"h1":"Sou yon wout de sans ki pa gen separasyon nan mitan, règ la se menm pou de direksyon yo.","h2":"Sou yon wout de sans, machin k ap ale nan de direksyon yo dwe kanpe pou yon bis lekòl ki montre siyal \"STOP\" li, kidonk ou kanpe menm si w ap vini nan lòt bò a.","p":"Wi, se sa. Sou yon wout de sans, de direksyon yo kanpe pou yon bis lekòl ki kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-023","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, a school bus is stopped across a raised concrete median, on the other side of a divided highway. Must you stop?","o":["No, you may keep going, with care","Yes, you must always stop","Only if children are on your side","Only if the bus honks"],"h1":"A raised barrier keeps the two directions apart.","h2":"On a divided highway with a raised median, you do not have to stop when the school bus is on the other side, but you should still watch for children.","p":"Right. With a raised median, the opposite side does not have to stop."},"es":{"q":"En Florida, un autobús escolar está parado del otro lado de una división de concreto elevada en una carretera dividida. ¿Debe usted parar?","o":["No, puede seguir con cuidado","Sí, siempre debe parar","Solo si hay niños de su lado","Solo si el autobús toca la bocina"],"h1":"Una división elevada separa las dos direcciones.","h2":"En una carretera dividida con una división elevada, usted no tiene que parar cuando el autobús escolar está del otro lado, pero igual debe estar atento a los niños.","p":"Correcto. Con división elevada, el lado contrario no tiene que parar."},"zh":{"q":"在 Florida，一辆校车停在一条分隔公路的另一边，中间有凸起的水泥隔离带。你必须停车吗？","o":["不用，你可以小心地继续开","要，你永远必须停车","只有你这边有小孩时才要","只有校车按喇叭时才要"],"h1":"凸起的隔离带把两个方向分开了。","h2":"在有凸起隔离带的分隔公路上，校车在另一边时你不用停车，但你还是要注意小孩。","p":"对。有凸起隔离带时，对面方向不用停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách bằng bê tông nổi cao. Bạn có phải dừng không?","o":["Không, bạn có thể tiếp tục chạy, nhưng cẩn thận","Có, bạn luôn phải dừng","Chỉ khi có trẻ em ở phía bên bạn","Chỉ khi xe buýt bấm còi"],"h1":"Một rào chắn nổi cao tách hai hướng xe ra.","h2":"Trên xa lộ có dải phân cách nổi cao, bạn không phải dừng khi xe buýt trường học ở phía bên kia, nhưng bạn vẫn nên để ý trẻ em.","p":"Đúng. Có dải phân cách nổi cao thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may school bus na nakahinto sa kabila ng nakataas na konkretong median, sa kabilang panig ng divided highway. Dapat ka bang huminto?","o":["Hindi, puwede kang magpatuloy, nang maingat","Oo, dapat kang laging huminto","Kung may mga bata lang sa panig mo","Kung bumusina lang ang bus"],"h1":"Pinaghihiwalay ng nakataas na harang ang dalawang direksiyon.","h2":"Sa divided highway na may nakataas na median, hindi mo kailangang huminto kapag nasa kabilang panig ang school bus, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median, hindi kailangang huminto ang kabilang panig."},"ar":{"q":"في Florida، حافلة مدرسية متوقفة على الجانب الآخر من طريق سريع مقسوم بفاصل إسمنتي مرتفع. هل يجب أن تتوقف؟","o":["لا، يمكنني أن أستمر بحذر","نعم، يجب أن أتوقف دائمًا","فقط إذا كان هناك أطفال على جانبي","فقط إذا استعملت الحافلة البوق"],"h1":"الحاجز المرتفع يفصل بين الاتجاهين.","h2":"على طريق سريع مقسوم بفاصل مرتفع، ليس عليك أن تتوقف عندما تكون الحافلة المدرسية على الجانب الآخر، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع فاصل مرتفع، ليس على الجانب المقابل أن يتوقف."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe lòt bò yon separasyon an beton ki leve, sou lòt bò yon gran wout ki separe. Èske ou dwe kanpe?","o":["Non, ou ka kontinye, avèk atansyon","Wi, ou dwe toujou kanpe","Sèlman si gen timoun sou bò pa w la","Sèlman si bis la klaksonnen"],"h1":"Yon baryè ki leve kenbe de direksyon yo apa.","h2":"Sou yon gran wout ki separe ak yon separasyon ki leve, ou pa oblije kanpe lè bis lekòl la sou lòt bò a, men ou dwe toujou veye timoun yo.","p":"Wi, se sa. Lè gen yon separasyon ki leve, machin ki sou lòt bò a pa oblije kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-024","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, a highway has an unpaved grass median. How wide must it be so that traffic on the other side does not have to stop for a school bus?","o":["At least 2 feet","At least 10 feet","At least 20 feet","At least 5 feet"],"h1":"The number is small, about the length of a sofa.","h2":"Florida law says that if an unpaved median is at least 5 feet wide, traffic going the other way does not have to stop for a stopped school bus.","p":"Right. An unpaved median of at least 5 feet means the other side does not stop."},"es":{"q":"En Florida, una carretera tiene una división de césped sin pavimentar. ¿Qué ancho debe tener para que el tráfico del otro lado no tenga que parar por un autobús escolar?","o":["Por lo menos 2 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 5 pies"],"h1":"El número es pequeño, más o menos el largo de un sofá.","h2":"La ley de Florida dice que si una división sin pavimentar mide por lo menos 5 pies de ancho, el tráfico que va en la otra dirección no tiene que parar por un autobús escolar parado.","p":"Correcto. Con una división sin pavimentar de por lo menos 5 pies, el otro lado no para."},"zh":{"q":"在 Florida，一条公路中间有没铺路面的草地隔离带。它至少要多宽，对面方向的车才不用为校车停车？","o":["至少 2 英尺","至少 10 英尺","至少 20 英尺","至少 5 英尺"],"h1":"这个数字很小，大约是一张沙发的长度。","h2":"Florida 法律规定，如果没铺路面的隔离带至少有 5 英尺宽，对面方向的车就不用为停着的校车停车。","p":"对。没铺路面的隔离带至少 5 英尺宽，对面就不用停车。"},"vi":{"q":"Ở Florida, một xa lộ có dải phân cách bằng cỏ, không tráng nhựa. Dải đó phải rộng bao nhiêu để xe phía bên kia không phải dừng cho xe buýt trường học?","o":["Ít nhất 2 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 5 feet"],"h1":"Con số này nhỏ, khoảng bằng chiều dài một chiếc ghế sofa.","h2":"Luật Florida nói nếu dải phân cách không tráng nhựa rộng ít nhất 5 feet, xe đi hướng ngược lại không phải dừng cho xe buýt trường học đang dừng.","p":"Đúng. Dải phân cách không tráng nhựa rộng ít nhất 5 feet thì phía bên kia không phải dừng."},"tl":{"q":"Sa Florida, may median na damo at walang semento ang isang highway. Gaano ito dapat kalapad para hindi na kailangang huminto ng trapiko sa kabilang panig para sa school bus?","o":["Hindi bababa sa 2 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 5 feet"],"h1":"Maliit ang numero, mga kasinghaba ng sofa.","h2":"Sinasabi ng batas ng Florida na kung ang median na walang semento ay hindi bababa sa 5 feet ang lapad, hindi kailangang huminto ng trapiko sa kabilang direksiyon para sa nakahintong school bus.","p":"Tama. Kapag ang median na walang semento ay hindi bababa sa 5 feet, hindi humihinto ang kabilang panig."},"ar":{"q":"في Florida، طريق سريع في وسطه فاصل من العشب غير مرصوف. كم يجب أن يكون عرضه حتى لا تتوقف السيارات على الجانب الآخر للحافلة المدرسية؟","o":["2 قدم على الأقل","10 أقدام على الأقل","20 قدمًا على الأقل","5 أقدام على الأقل"],"h1":"الرقم صغير، تقريبًا طول أريكة.","h2":"يقول قانون Florida إنه إذا كان عرض الفاصل غير المرصوف 5 أقدام على الأقل، فليس على السيارات في الاتجاه الآخر أن تتوقف لحافلة مدرسية متوقفة.","p":"صحيح. فاصل غير مرصوف عرضه 5 أقدام على الأقل يعني أن الجانب الآخر لا يتوقف."},"ht":{"q":"Nan Florida, yon gran wout gen yon separasyon an zèb, ki pa asfalte, nan mitan l. Ki lajè separasyon an dwe genyen pou machin ki sou lòt bò a pa oblije kanpe pou yon bis lekòl?","o":["Omwen 2 pye","Omwen 10 pye","Omwen 20 pye","Omwen 5 pye"],"h1":"Chif la piti, apeprè longè yon kanape.","h2":"Lwa Florida di si yon separasyon ki pa asfalte gen omwen 5 pye lajè, machin k ap ale nan lòt direksyon an pa oblije kanpe pou yon bis lekòl ki kanpe.","p":"Wi, se sa. Yon separasyon ki pa asfalte ki gen omwen 5 pye vle di lòt bò a pa kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-025","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a road has a paved center turn lane. A school bus is stopped on the other side with its stop arm out. What do you do?","o":["Keep going, because a turn lane divides the road","Stop, because a paved turn lane does not count as a divider","Pass using the turn lane","Slow down only"],"h1":"Only a raised barrier or a wide unpaved median lets the other side keep going.","h2":"A paved center turn lane is not a raised barrier or an unpaved median, so traffic in both directions must stop for the school bus.","p":"Right. A paved turn lane does not excuse you. Stop for the bus."},"es":{"q":"En Florida, una calle tiene un carril central pavimentado para doblar. Un autobús escolar está parado del otro lado con el brazo de pare afuera. ¿Qué hace?","o":["Sigue, porque el carril para doblar divide la calle","Para, porque un carril pavimentado para doblar no cuenta como división","Pasa usando el carril para doblar","Solo baja la velocidad"],"h1":"Solo una división elevada o una división ancha sin pavimentar permite que el otro lado siga.","h2":"Un carril central pavimentado para doblar no es una división elevada ni una división sin pavimentar, así que el tráfico de las dos direcciones debe parar por el autobús escolar.","p":"Correcto. Un carril para doblar no lo exime. Pare por el autobús."},"zh":{"q":"在 Florida，一条路中间有铺了路面的中央转弯车道。一辆校车停在另一边，伸出了停车臂。你该怎么做？","o":["继续开，因为转弯车道把路分开了","停车，因为铺了路面的转弯车道不算隔离带","从转弯车道开过去","只要减速就行"],"h1":"只有凸起的隔离带或很宽的没铺路面的隔离带，才能让对面继续开。","h2":"铺了路面的中央转弯车道不是凸起的隔离带，也不是没铺路面的隔离带，所以两个方向的车都必须为校车停车。","p":"对。铺了路面的转弯车道不能当理由。要为校车停车。"},"vi":{"q":"Ở Florida, một con đường có làn rẽ ở giữa được tráng nhựa. Một xe buýt trường học đang dừng ở phía bên kia và giơ cần biển \"STOP\". Bạn làm gì?","o":["Tiếp tục chạy, vì làn rẽ chia đôi con đường","Dừng lại, vì làn rẽ tráng nhựa không được tính là dải phân cách","Chạy qua bằng làn rẽ","Chỉ cần giảm tốc"],"h1":"Chỉ có rào chắn nổi cao hoặc dải phân cách không tráng nhựa đủ rộng mới cho phía bên kia tiếp tục chạy.","h2":"Làn rẽ ở giữa được tráng nhựa không phải là rào chắn nổi cao hay dải phân cách không tráng nhựa, nên xe cả hai hướng phải dừng cho xe buýt trường học.","p":"Đúng. Làn rẽ tráng nhựa không miễn cho bạn. Hãy dừng cho xe buýt."},"tl":{"q":"Sa Florida, may sementadong center turn lane ang daan. May school bus na nakahinto sa kabilang panig na nakalabas ang stop arm. Ano ang gagawin mo?","o":["Magpatuloy, dahil hinahati ng turn lane ang daan","Huminto, dahil hindi binibilang na harang ang sementadong turn lane","Dumaan gamit ang turn lane","Bumagal lang"],"h1":"Ang nakataas na harang lang o malapad na median na walang semento ang nagpapahintulot sa kabilang panig na magpatuloy.","h2":"Ang sementadong center turn lane ay hindi nakataas na harang o median na walang semento, kaya dapat huminto ang trapiko sa dalawang direksiyon para sa school bus.","p":"Tama. Hindi dahilan ang sementadong turn lane. Huminto para sa bus."},"ar":{"q":"في Florida، في وسط الطريق مسار مرصوف للانعطاف. حافلة مدرسية متوقفة على الجانب الآخر وذراع التوقف فيها مفتوح. ماذا تفعل؟","o":["أستمر، لأن مسار الانعطاف يقسم الطريق","أتوقف، لأن مسار الانعطاف المرصوف لا يُعتبر فاصلًا","أتجاوز الحافلة من مسار الانعطاف","أخفف السرعة فقط"],"h1":"فقط الحاجز المرتفع أو الفاصل العريض غير المرصوف يسمح للجانب الآخر بأن يستمر.","h2":"مسار الانعطاف المرصوف في الوسط ليس حاجزًا مرتفعًا ولا فاصلًا غير مرصوف، لذلك يجب على السيارات في الاتجاهين أن تتوقف للحافلة المدرسية.","p":"صحيح. مسار الانعطاف المرصوف لا يعفيك. توقف للحافلة."},"ht":{"q":"Nan Florida, yon wout gen yon liy pou vire nan mitan ki asfalte. Yon bis lekòl kanpe sou lòt bò a ak bra \"STOP\" li louvri. Kisa ou fè?","o":["Ou kontinye, paske liy pou vire a separe wout la","Ou kanpe, paske yon liy pou vire ki asfalte pa konte kòm separasyon","Ou pase nan liy pou vire a","Ou ralanti sèlman"],"h1":"Se sèlman yon baryè ki leve oswa yon separasyon laj ki pa asfalte ki kite lòt bò a kontinye.","h2":"Yon liy pou vire nan mitan ki asfalte pa yon baryè ki leve ni yon separasyon ki pa asfalte, kidonk machin nan de direksyon yo dwe kanpe pou bis lekòl la.","p":"Wi, se sa. Yon liy pou vire ki asfalte pa egzante ou. Kanpe pou bis la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-026","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind a school bus on a divided highway. The bus stops and shows its stop arm. What do you do?","o":["Pass on the left","Keep going, because the highway is divided","Stop behind the bus","Pass on the right shoulder"],"h1":"The median only helps traffic on the other side.","h2":"Traffic going the same way as a stopped school bus must always stop, even on a divided highway.","p":"Right. If you are behind a stopped school bus, you always stop."},"es":{"q":"En Florida, usted maneja detrás de un autobús escolar en una carretera dividida. El autobús para y saca el brazo de pare. ¿Qué hace?","o":["Lo rebasa por la izquierda","Sigue, porque la carretera está dividida","Para detrás del autobús","Lo rebasa por el acotamiento derecho"],"h1":"La división solo ayuda al tráfico del otro lado.","h2":"El tráfico que va en la misma dirección que un autobús escolar parado siempre debe parar, aunque la carretera esté dividida.","p":"Correcto. Si va detrás de un autobús escolar parado, siempre para."},"zh":{"q":"在 Florida，你在一条分隔公路上跟在一辆校车后面。校车停下，伸出了停车臂。你该怎么做？","o":["从左边超过去","继续开，因为公路是分隔的","在校车后面停车","从右边路肩超过去"],"h1":"隔离带只对另一边的车有用。","h2":"和停着的校车同方向行驶的车永远必须停车，就算在分隔公路上也一样。","p":"对。如果你在停着的校车后面，一定要停车。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe buýt trường học trên xa lộ có dải phân cách. Xe buýt dừng lại và giơ cần biển \"STOP\". Bạn làm gì?","o":["Vượt bên trái","Tiếp tục chạy, vì xa lộ có dải phân cách","Dừng lại phía sau xe buýt","Vượt bằng lề bên phải"],"h1":"Dải phân cách chỉ giúp xe ở phía bên kia.","h2":"Xe đi cùng hướng với xe buýt trường học đang dừng luôn phải dừng, kể cả trên xa lộ có dải phân cách.","p":"Đúng. Nếu bạn ở sau xe buýt trường học đang dừng, bạn luôn phải dừng."},"tl":{"q":"Sa Florida, nasa likod ka ng school bus sa divided highway. Huminto ang bus at inilabas ang stop arm. Ano ang gagawin mo?","o":["Lumampas sa kaliwa","Magpatuloy, dahil divided ang highway","Huminto sa likod ng bus","Lumampas sa kanang shoulder"],"h1":"Ang median ay tumutulong lang sa trapiko sa kabilang panig.","h2":"Ang trapikong papunta sa parehong direksiyon ng nakahintong school bus ay dapat laging huminto, kahit sa divided highway.","p":"Tama. Kung nasa likod ka ng nakahintong school bus, laging huminto."},"ar":{"q":"في Florida، تقود خلف حافلة مدرسية على طريق سريع مقسوم. توقفت الحافلة وفتحت ذراع التوقف. ماذا تفعل؟","o":["أتجاوزها من اليسار","أستمر، لأن الطريق السريع مقسوم","أتوقف خلف الحافلة","أتجاوزها من كتف الطريق الأيمن"],"h1":"الفاصل في الوسط يساعد فقط السيارات على الجانب الآخر.","h2":"السيارات التي تسير في نفس اتجاه الحافلة المدرسية المتوقفة يجب أن تتوقف دائمًا، حتى على طريق سريع مقسوم.","p":"صحيح. إذا كنت خلف حافلة مدرسية متوقفة، تتوقف دائمًا."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon bis lekòl sou yon gran wout ki separe. Bis la kanpe epi li louvri bra \"STOP\" li. Kisa ou fè?","o":["Ou pase sou bò gòch","Ou kontinye, paske gran wout la separe","Ou kanpe dèyè bis la","Ou pase sou bò wout la adwat"],"h1":"Separasyon an ede sèlman machin ki sou lòt bò a.","h2":"Machin k ap ale nan menm direksyon ak yon bis lekòl ki kanpe dwe toujou kanpe, menm sou yon gran wout ki separe.","p":"Wi, se sa. Si ou dèyè yon bis lekòl ki kanpe, ou toujou kanpe."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-027","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you stopped for a school bus. When may you start driving again?","o":["When the stop arm is pulled back and the children are clear","As soon as the door closes","After you count to ten","When the driver waves at you"],"h1":"Watch the bus signal and the children, not a timer.","h2":"You must stay stopped until the bus pulls back its stop signal and the children are out of the road.","p":"Right. Wait until the stop arm is back in and the children are clear."},"es":{"q":"En Florida, usted paró por un autobús escolar. ¿Cuándo puede volver a manejar?","o":["Cuando el brazo de pare se recoge y los niños están fuera del camino","Apenas se cierra la puerta","Después de contar hasta diez","Cuando el chofer le hace una seña"],"h1":"Fíjese en la señal del autobús y en los niños, no en el tiempo.","h2":"Usted debe quedarse parado hasta que el autobús recoja su señal de pare y los niños estén fuera de la calle.","p":"Correcto. Espere a que se recoja el brazo de pare y los niños estén a salvo."},"zh":{"q":"在 Florida，你为校车停了车。什么时候可以再开车？","o":["停车臂收回，而且小孩都离开了路面","车门一关就可以","数到十以后","司机向你挥手的时候"],"h1":"看校车的信号和小孩，不是看时间。","h2":"你必须一直停着，直到校车收回停车信号，而且小孩都离开了路面。","p":"对。等停车臂收回、小孩都离开了再走。"},"vi":{"q":"Ở Florida, bạn đã dừng cho xe buýt trường học. Khi nào bạn được chạy tiếp?","o":["Khi cần biển \"STOP\" đã thu lại và trẻ em đã ra khỏi đường","Ngay khi cửa xe buýt đóng lại","Sau khi bạn đếm đến mười","Khi tài xế xe buýt vẫy tay với bạn"],"h1":"Hãy nhìn tín hiệu của xe buýt và trẻ em, không phải đếm giờ.","h2":"Bạn phải dừng cho đến khi xe buýt thu tín hiệu dừng lại và trẻ em đã ra khỏi đường.","p":"Đúng. Hãy chờ đến khi cần biển \"STOP\" thu lại và trẻ em đã ra khỏi đường."},"tl":{"q":"Sa Florida, huminto ka para sa school bus. Kailan ka puwedeng umandar ulit?","o":["Kapag naibalik na ang stop arm at wala na ang mga bata sa daan","Pagsara pa lang ng pinto","Pagkatapos mong magbilang hanggang sampu","Kapag kinawayan ka ng drayber"],"h1":"Bantayan ang signal ng bus at ang mga bata, hindi ang orasan.","h2":"Dapat kang manatiling nakahinto hanggang maibalik ng bus ang stop signal nito at wala na ang mga bata sa daan.","p":"Tama. Maghintay hanggang maibalik ang stop arm at wala na ang mga bata sa daan."},"ar":{"q":"في Florida، توقفت لحافلة مدرسية. متى يمكنك أن تبدأ القيادة مرة أخرى؟","o":["عندما يُسحب ذراع التوقف ويبتعد الأطفال عن الطريق","مباشرة عندما يُغلق الباب","بعد أن أعدّ إلى عشرة","عندما يلوّح لي السائق"],"h1":"راقب إشارة الحافلة والأطفال، وليس الوقت.","h2":"يجب أن تبقى متوقفًا حتى تسحب الحافلة إشارة التوقف ويخرج الأطفال من الطريق.","p":"صحيح. انتظر حتى يرجع ذراع التوقف ويبتعد الأطفال."},"ht":{"q":"Nan Florida, ou te kanpe pou yon bis lekòl. Kilè ou ka kòmanse kondi ankò?","o":["Lè bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la","Depi pòt la fèmen","Apre ou fin konte jiska dis","Lè chofè a fè ou siy ak men l"],"h1":"Gade siyal bis la ak timoun yo, pa yon revèy.","h2":"Ou dwe rete kanpe jiskaske bis la fèmen siyal \"STOP\" li epi timoun yo fin sòti nan wout la.","p":"Wi, se sa. Tann bra \"STOP\" la fèmen epi timoun yo fin sòti nan wout la."},"ref":{"doc":"FL","page":89}},{"id":"right-of-way-028","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","More than 100 feet away","Within 5 feet of the nearest rail"],"h1":"You need a safe gap from the train, but not so far that you block the road behind you.","h2":"Florida law says you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail when a train is coming.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, las luces están intermitentes en un cruce de tren. ¿Dónde debe parar?","o":["Encima de las vías","Entre 15 y 50 pies del riel más cercano","A más de 100 pies","A menos de 5 pies del riel más cercano"],"h1":"Necesita una distancia segura del tren, pero no tan lejos que bloquee la calle detrás de usted.","h2":"La ley de Florida dice que usted debe parar a no menos de 15 pies y no más de 50 pies del riel más cercano cuando viene un tren.","p":"Correcto. Pare entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，铁路道口的灯在闪。你必须在哪里停车？","o":["就停在铁轨上","离最近的铁轨 15 到 50 英尺之间","超过 100 英尺远","离最近的铁轨 5 英尺以内"],"h1":"你需要和火车保持安全距离，但也不能太远，挡住后面的路。","h2":"Florida 法律规定，有火车开来时，你必须停在离最近的铁轨不少于 15 英尺、不超过 50 英尺的地方。","p":"对。停在离最近的铁轨 15 到 50 英尺之间。"},"vi":{"q":"Ở Florida, đèn đang nháy tại chỗ giao nhau với đường sắt. Bạn phải dừng ở đâu?","o":["Ngay trên đường ray","Cách thanh ray gần nhất từ 15 đến 50 feet","Cách xa hơn 100 feet","Trong vòng 5 feet từ thanh ray gần nhất"],"h1":"Bạn cần khoảng cách an toàn với tàu hỏa, nhưng không quá xa để chắn đường phía sau.","h2":"Luật Florida nói khi có tàu đang đến, bạn phải dừng không gần hơn 15 feet và không xa hơn 50 feet từ thanh ray gần nhất.","p":"Đúng. Hãy dừng cách thanh ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Florida, kumikislap ang mga ilaw sa railroad crossing. Saan ka dapat huminto?","o":["Mismo sa ibabaw ng riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Higit sa 100 feet ang layo","Sa loob ng 5 feet mula sa pinakamalapit na riles"],"h1":"Kailangan mo ng ligtas na layo mula sa tren, pero hindi gaanong malayo na mahaharangan mo ang daan sa likod mo.","h2":"Sinasabi ng batas ng Florida na kapag may paparating na tren, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، الأضواء تومض عند تقاطع سكة حديد. أين يجب أن تتوقف؟","o":["على السكة نفسها","على مسافة بين 15 و50 قدمًا من أقرب قضيب","على مسافة أكثر من 100 قدم","على مسافة أقل من 5 أقدام من أقرب قضيب"],"h1":"تحتاج إلى مسافة آمنة من القطار، لكن ليس بعيدًا جدًا حتى لا تسد الطريق على من خلفك.","h2":"يقول قانون Florida إنه عندما يأتي قطار، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا ولا تزيد على 50 قدمًا من أقرب قضيب.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا من أقرب قضيب."},"ht":{"q":"Nan Florida, limyè yo ap flache nan yon kwazman tren. Ki kote ou dwe kanpe?","o":["Dirèkteman sou ray yo","Ant 15 ak 50 pye de ray ki pi pre a","Plis pase 100 pye lwen","Mwens pase 5 pye de ray ki pi pre a"],"h1":"Ou bezwen yon espas ki san danje ant ou ak tren an, men pa twò lwen pou ou pa bloke wout la dèyè ou.","h2":"Lwa Florida di lè yon tren ap vini, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a.","p":"Wi, se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-029","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, the gates at a railroad crossing are down, but you do not see a train. What do you do?","o":["Drive around the gates carefully","Honk and cross slowly","Back up and look for another way, then cross","Wait until the gates go up and the lights stop"],"h1":"Trains can be closer and faster than they look.","h2":"You must never drive around lowered railroad gates, so you wait until the gates are all the way up and the lights stop flashing.","p":"Right. Never go around railroad gates. Wait until they go up."},"es":{"q":"En Florida, las barreras de un cruce de tren están abajo, pero usted no ve ningún tren. ¿Qué hace?","o":["Pasa alrededor de las barreras con cuidado","Toca la bocina y cruza despacio","Da reversa, busca otro camino y cruza","Espera hasta que suban las barreras y se apaguen las luces"],"h1":"Los trenes pueden estar más cerca y ser más rápidos de lo que parece.","h2":"Usted nunca debe pasar alrededor de las barreras bajas del tren, así que espera hasta que las barreras suban por completo y las luces dejen de parpadear.","p":"Correcto. Nunca pase alrededor de las barreras del tren. Espere a que suban."},"zh":{"q":"在 Florida，铁路道口的栏杆放下来了，但你没看到火车。你该怎么做？","o":["小心地绕过栏杆","按喇叭，慢慢开过去","倒车，找另一条路，然后过去","等栏杆升起、灯不再闪"],"h1":"火车可能比看起来更近、更快。","h2":"你永远不能绕过放下的铁路栏杆，所以要等栏杆完全升起、灯不再闪。","p":"对。永远不要绕过铁路栏杆。等它升起来。"},"vi":{"q":"Ở Florida, thanh chắn ở chỗ giao nhau với đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn làm gì?","o":["Lái vòng qua thanh chắn một cách cẩn thận","Bấm còi và chạy qua chậm","Lùi xe và tìm đường khác, rồi chạy qua","Chờ đến khi thanh chắn nâng lên và đèn ngừng nháy"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn nghĩ.","h2":"Bạn không bao giờ được lái vòng qua thanh chắn đường sắt đã hạ, nên bạn chờ đến khi thanh chắn nâng lên hết và đèn ngừng nháy.","p":"Đúng. Không bao giờ lái vòng qua thanh chắn đường sắt. Hãy chờ đến khi nó nâng lên."},"tl":{"q":"Sa Florida, nakababa ang mga harang sa railroad crossing, pero wala kang nakikitang tren. Ano ang gagawin mo?","o":["Maingat na umikot sa mga harang","Bumusina at dahan-dahang tumawid","Umatras at maghanap ng ibang daan, saka tumawid","Maghintay hanggang tumaas ang mga harang at tumigil ang mga ilaw"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa tingin mo.","h2":"Hindi ka dapat kailanman umikot sa nakababang harang ng riles, kaya maghihintay ka hanggang tuluyang tumaas ang mga harang at tumigil sa pagkislap ang mga ilaw.","p":"Tama. Huwag kailanman umikot sa harang ng riles. Maghintay hanggang tumaas ito."},"ar":{"q":"في Florida، الحواجز عند تقاطع سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا تفعل؟","o":["ألتف حول الحواجز بحذر","أستعمل البوق وأعبر ببطء","أرجع إلى الخلف وأبحث عن طريق آخر، ثم أعبر","أنتظر حتى ترتفع الحواجز وتتوقف الأضواء"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"لا يجوز أبدًا أن تلتف حول حواجز سكة الحديد النازلة، لذلك تنتظر حتى ترتفع الحواجز كليًا وتتوقف الأضواء عن الوميض.","p":"صحيح. لا تلتف أبدًا حول حواجز سكة الحديد. انتظر حتى ترتفع."},"ht":{"q":"Nan Florida, baryè kwazman tren an desann, men ou pa wè okenn tren. Kisa ou fè?","o":["Ou fè yon ti detou bò baryè yo avèk atansyon","Ou klaksonnen epi ou travèse dousman","Ou fè bak pou chèche yon lòt chemen, apre sa ou travèse","Ou tann baryè yo leve epi limyè yo sispann flache"],"h1":"Yon tren ka pi pre epi pi rapid pase sa ou kwè.","h2":"Ou pa dwe janm fè detou bò baryè tren ki desann, kidonk ou tann jiskaske baryè yo fin leve nèt epi limyè yo sispann flache.","p":"Wi, se sa. Pa janm fè detou bò baryè tren yo. Tann yo leve."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-030","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, traffic is backed up past a railroad crossing. When may you start across the tracks?","o":["When the car in front of you moves","Right away, if no train is in sight","Only when there is room for your whole car on the other side","When the driver behind you honks"],"h1":"Think about where your car will be if traffic stops again.","h2":"You may start across the tracks only when there is room for your whole vehicle on the other side, so you never get stuck on the rails.","p":"Right. Do not cross until your whole car fits on the other side."},"es":{"q":"En Florida, el tráfico está detenido más allá de un cruce de tren. ¿Cuándo puede empezar a cruzar las vías?","o":["Cuando avance el carro de adelante","De inmediato, si no se ve ningún tren","Solo cuando haya espacio para todo su carro del otro lado","Cuando el conductor de atrás toque la bocina"],"h1":"Piense dónde quedará su carro si el tráfico se detiene otra vez.","h2":"Usted puede empezar a cruzar las vías solo cuando haya espacio para todo su vehículo del otro lado, para nunca quedar atrapado sobre los rieles.","p":"Correcto. No cruce hasta que todo su carro quepa del otro lado."},"zh":{"q":"在 Florida，车流一直排到铁路道口的另一边。你什么时候可以开始过铁轨？","o":["前面的车一动就可以","马上，只要看不到火车","只有另一边有足够的空间放下你整辆车时","后面的司机按喇叭的时候"],"h1":"想一想，如果车流又停下来，你的车会在哪里。","h2":"只有另一边有足够的空间放下你整辆车时，你才可以开始过铁轨，这样你就永远不会被困在铁轨上。","p":"对。另一边放不下你整辆车时，不要过铁轨。"},"vi":{"q":"Ở Florida, xe đang kẹt kéo dài qua chỗ giao nhau với đường sắt. Khi nào bạn được bắt đầu chạy qua đường ray?","o":["Khi xe phía trước bạn chạy","Ngay lập tức, nếu không thấy tàu","Chỉ khi có đủ chỗ cho cả chiếc xe của bạn ở phía bên kia","Khi người lái phía sau bấm còi"],"h1":"Hãy nghĩ xem xe của bạn sẽ ở đâu nếu dòng xe lại dừng.","h2":"Bạn chỉ được bắt đầu chạy qua đường ray khi có đủ chỗ cho cả chiếc xe ở phía bên kia, để bạn không bao giờ bị kẹt trên đường ray.","p":"Đúng. Đừng chạy qua cho đến khi cả chiếc xe vừa chỗ ở phía bên kia."},"tl":{"q":"Sa Florida, nakapila ang trapiko hanggang lampas sa railroad crossing. Kailan ka puwedeng magsimulang tumawid sa riles?","o":["Kapag umandar ang kotse sa harap mo","Agad, kung walang tren na nakikita","Kapag may lugar lang para sa buong kotse mo sa kabilang panig","Kapag bumusina ang drayber sa likod mo"],"h1":"Isipin kung nasaan ang kotse mo kung huminto ulit ang trapiko.","h2":"Puwede kang magsimulang tumawid sa riles kapag may lugar lang para sa buong sasakyan mo sa kabilang panig, para hindi ka maipit sa ibabaw ng riles.","p":"Tama. Huwag tumawid hanggang kasya ang buong kotse mo sa kabilang panig."},"ar":{"q":"في Florida، الطريق مزدحم وطابور السيارات يصل إلى ما بعد تقاطع سكة الحديد. متى يمكنك أن تبدأ عبور السكة؟","o":["عندما تتحرك السيارة التي أمامي","فورًا، إذا لم أرَ قطارًا","فقط عندما يوجد مكان لسيارتي كلها على الجانب الآخر","عندما يستعمل السائق الذي خلفي البوق"],"h1":"فكّر أين ستكون سيارتك إذا توقفت السيارات مرة أخرى.","h2":"يمكنك أن تبدأ عبور السكة فقط عندما يوجد مكان لمركبتك كلها على الجانب الآخر، حتى لا تعلق أبدًا على القضبان.","p":"صحيح. لا تعبر حتى تجد مكانًا لسيارتك كلها على الجانب الآخر."},"ht":{"q":"Nan Florida, machin yo kanpe an liy rive pi lwen pase yon kwazman tren. Kilè ou ka kòmanse travèse ray yo?","o":["Lè machin ki devan ou a avanse","Touswit, si ou pa wè okenn tren","Sèlman lè gen plas pou tout machin ou sou lòt bò a","Lè chofè ki dèyè ou a klaksonnen"],"h1":"Panse ak ki kote machin ou ap ye si sikilasyon an kanpe ankò.","h2":"Ou ka kòmanse travèse ray yo sèlman lè gen plas pou tout machin ou sou lòt bò a, pou ou pa janm rete bloke sou ray yo.","p":"Wi, se sa. Pa travèse jiskaske tout machin ou ka antre sou lòt bò a."},"ref":{"doc":"FL","page":57}},{"id":"right-of-way-031","scope":"US","cat":"right-of-way","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"What does this white X-shaped sign mean?","o":["A railroad crossing. Yield to trains.","An intersection with four roads","A hospital is nearby","No parking in this area"],"h1":"This sign stands where a road meets something that cannot stop or swerve to miss you.","h2":"The white X-shaped sign, called a crossbuck, marks a railroad crossing, and you must yield to any train.","p":"Right. The crossbuck marks a railroad crossing. Yield to trains."},"es":{"q":"¿Qué significa esta señal blanca en forma de X?","o":["Un cruce de tren. Ceda el paso a los trenes.","Una intersección de cuatro calles","Hay un hospital cerca","No se permite estacionar en esta área"],"h1":"Esta señal está donde una calle se cruza con algo que no puede parar ni desviarse para no chocar con usted.","h2":"La señal blanca en forma de X, llamada crossbuck, marca un cruce de tren, y usted debe ceder el paso a cualquier tren.","p":"Correcto. La señal en X marca un cruce de tren. Ceda el paso a los trenes."},"zh":{"q":"这个白色 X 形的标志是什么意思？","o":["铁路道口。要给火车让行。","一个有四条路的路口","附近有医院","这里禁止停车"],"h1":"这个标志立在道路和一种无法停下、也无法躲开你的东西交叉的地方。","h2":"这个白色 X 形的标志叫做铁路交叉标志，它标出铁路道口，你必须给任何火车让行。","p":"对。白色 X 形标志表示铁路道口。要给火车让行。"},"vi":{"q":"Biển báo màu trắng hình chữ X này có nghĩa là gì?","o":["Chỗ giao nhau với đường sắt. Nhường đường cho tàu.","Giao lộ có bốn con đường","Gần đây có bệnh viện","Không được đậu xe ở khu vực này"],"h1":"Biển này đặt ở nơi con đường gặp một thứ không thể dừng lại hay tránh bạn.","h2":"Biển màu trắng hình chữ X, gọi là biển \"crossbuck\", đánh dấu chỗ giao nhau với đường sắt, và bạn phải nhường đường cho mọi đoàn tàu.","p":"Đúng. Biển \"crossbuck\" đánh dấu chỗ giao nhau với đường sắt. Hãy nhường tàu."},"tl":{"q":"Ano ang ibig sabihin ng puting karatulang hugis X na ito?","o":["Railroad crossing (tawiran ng tren). Magbigay-daan sa tren.","Intersection ng apat na daan","May ospital sa malapit","Bawal pumarada sa lugar na ito"],"h1":"Nakatayo ang karatulang ito kung saan nagtatagpo ang daan at isang bagay na hindi kayang huminto o umiwas sa iyo.","h2":"Ang puting karatulang hugis X, na tinatawag na crossbuck, ay nagmamarka ng railroad crossing, at dapat kang magbigay-daan sa anumang tren.","p":"Tama. Ang crossbuck ay nagmamarka ng railroad crossing. Magbigay-daan sa tren."},"ar":{"q":"ماذا تعني هذه العلامة البيضاء التي على شكل حرف X؟","o":["تقاطع سكة حديد. أعطِ حق المرور للقطارات.","تقاطع فيه أربعة طرق","يوجد مستشفى قريب","ممنوع الوقوف في هذه المنطقة"],"h1":"هذه العلامة موجودة حيث يلتقي الطريق بشيء لا يستطيع أن يتوقف أو يبتعد عنك.","h2":"العلامة البيضاء التي على شكل حرف X، واسمها crossbuck، تدل على تقاطع سكة حديد، ويجب أن تعطي حق المرور لأي قطار.","p":"صحيح. علامة crossbuck تدل على تقاطع سكة حديد. أعطِ حق المرور للقطارات."},"ht":{"q":"Kisa siy blan sa a ki gen fòm yon X vle di?","o":["Yon kwazman tren. Kite tren yo pase anvan.","Yon kafou ki gen kat wout","Gen yon lopital tou pre","Pa gen pakin nan zòn sa a"],"h1":"Siy sa a kanpe kote yon wout kwaze yon bagay ki pa ka kanpe ni vire pou evite ou.","h2":"Siy blan ki gen fòm yon X la, ki rele \"crossbuck\", make yon kwazman tren, epi ou dwe kite nenpòt tren pase anvan.","p":"Wi, se sa. Siy \"crossbuck\" la make yon kwazman tren. Kite tren yo pase anvan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-032","scope":"US","cat":"right-of-way","sign":{"shape":"rr-advance","text":"RR"},"c":2,"en":{"q":"What does this round yellow sign with an X and the letters RR mean?","o":["A rest area is ahead","A road repair zone is ahead","A railroad crossing is ahead","You must turn right"],"h1":"This sign gives you a warning before you reach something.","h2":"The round yellow sign with an X and RR warns you that a railroad crossing is ahead, so you slow down, look, and listen.","p":"Right. The round yellow RR sign means a railroad crossing is ahead."},"es":{"q":"¿Qué significa esta señal amarilla redonda con una X y las letras RR?","o":["Hay un área de descanso adelante","Hay una zona de reparación de la calle adelante","Hay un cruce de tren adelante","Debe doblar a la derecha"],"h1":"Esta señal le avisa antes de que usted llegue a algo.","h2":"La señal amarilla redonda con una X y RR le avisa que hay un cruce de tren adelante, así que baje la velocidad, mire y escuche.","p":"Correcto. La señal amarilla redonda con RR significa cruce de tren adelante."},"zh":{"q":"这个圆形黄色、上面有一个 X 和字母 \"RR\" 的标志是什么意思？","o":["前面有休息区","前面有道路维修区","前面有铁路道口","你必须右转"],"h1":"这个标志是在你到达某个地方之前给你的警告。","h2":"这个圆形黄色、有 X 和 \"RR\" 的标志警告你前面有铁路道口，所以你要减速，看一看，听一听。","p":"对。圆形黄色的 \"RR\" 标志表示前面有铁路道口。"},"vi":{"q":"Biển báo tròn màu vàng có chữ X và hai chữ \"RR\" này có nghĩa là gì?","o":["Phía trước có trạm dừng nghỉ","Phía trước có khu vực sửa đường","Phía trước có chỗ giao nhau với đường sắt","Bạn phải rẽ phải"],"h1":"Biển này cảnh báo bạn trước khi bạn đến một nơi nào đó.","h2":"Biển tròn màu vàng có chữ X và \"RR\" cảnh báo phía trước có chỗ giao nhau với đường sắt, nên bạn giảm tốc, nhìn và lắng nghe.","p":"Đúng. Biển tròn màu vàng \"RR\" có nghĩa là phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatulang ito na may X at mga letrang RR?","o":["May rest area sa unahan","May lugar ng pagkukumpuni ng daan sa unahan","May railroad crossing sa unahan","Dapat kang kumanan"],"h1":"Binabalaan ka ng karatulang ito bago ka dumating sa isang bagay.","h2":"Binabalaan ka ng bilog na dilaw na karatulang may X at RR na may railroad crossing sa unahan, kaya babagal ka, titingin, at makikinig.","p":"Tama. Ang bilog na dilaw na karatulang RR ay nangangahulugang may railroad crossing sa unahan."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء المستديرة التي عليها X والحرفان \"RR\"؟","o":["توجد استراحة أمامك","توجد منطقة إصلاح طريق أمامك","يوجد تقاطع سكة حديد أمامك","يجب أن تنعطف يمينًا"],"h1":"هذه العلامة تحذرك قبل أن تصل إلى شيء ما.","h2":"العلامة الصفراء المستديرة التي عليها X و\"RR\" تحذرك أن تقاطع سكة حديد أمامك، لذلك تخفف السرعة وتنظر وتسمع.","p":"صحيح. العلامة الصفراء المستديرة \"RR\" تعني أن تقاطع سكة حديد أمامك."},"ht":{"q":"Kisa siy jòn won sa a ki gen yon X ak lèt \"RR\" yo vle di?","o":["Gen yon zòn repo devan","Gen yon zòn reparasyon wout devan","Gen yon kwazman tren devan","Ou dwe vire adwat"],"h1":"Siy sa a avèti ou anvan ou rive nan yon bagay.","h2":"Siy jòn won ki gen yon X ak \"RR\" a avèti ou gen yon kwazman tren devan, kidonk ou ralanti, ou gade epi ou koute.","p":"Wi, se sa. Siy jòn won \"RR\" a vle di gen yon kwazman tren devan."},"ref":{"doc":"FL","page":56}},{"id":"right-of-way-033","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. Which lane should you be in?","o":["The left lane","The right lane, close to the curb","The center lane","Any lane, if you signal"],"h1":"Pick the lane on the same side as your turn.","h2":"To turn right, you get into the right lane near the curb and turn into the right lane of the new street.","p":"Right. Turn right from the right lane, near the curb."},"es":{"q":"En Florida, usted quiere doblar a la derecha. ¿En qué carril debe estar?","o":["En el carril izquierdo","En el carril derecho, cerca de la orilla","En el carril del centro","En cualquier carril, si pone la direccional"],"h1":"Escoja el carril del mismo lado de su vuelta.","h2":"Para doblar a la derecha, usted se coloca en el carril derecho cerca de la orilla y dobla al carril derecho de la nueva calle.","p":"Correcto. Doble a la derecha desde el carril derecho, cerca de la orilla."},"zh":{"q":"在 Florida，你想右转。你应该在哪条车道？","o":["左边车道","右边车道，靠近路缘","中间车道","哪条车道都行，只要打转向灯"],"h1":"选和你转弯方向同一边的车道。","h2":"要右转，你应该进入靠近路缘的右边车道，然后转进新街道的右边车道。","p":"对。从靠近路缘的右边车道右转。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Bạn nên ở làn nào?","o":["Làn bên trái","Làn bên phải, sát lề đường","Làn ở giữa","Làn nào cũng được, nếu bạn bật xi nhan"],"h1":"Hãy chọn làn ở cùng phía với hướng bạn rẽ.","h2":"Để rẽ phải, bạn vào làn bên phải gần lề đường và rẽ vào làn bên phải của con đường mới.","p":"Đúng. Rẽ phải từ làn bên phải, sát lề đường."},"tl":{"q":"Sa Florida, gusto mong kumanan. Saang lane ka dapat naroon?","o":["Sa kaliwang lane","Sa kanang lane, malapit sa curb (gilid ng bangketa)","Sa gitnang lane","Kahit anong lane, basta mag-signal ka"],"h1":"Piliin ang lane na nasa parehong panig ng liko mo.","h2":"Para kumanan, pumunta ka sa kanang lane malapit sa curb at kumanan papunta sa kanang lane ng bagong kalye.","p":"Tama. Kumanan mula sa kanang lane, malapit sa curb."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. في أي مسار يجب أن تكون؟","o":["المسار الأيسر","المسار الأيمن، قريبًا من الرصيف","المسار الأوسط","أي مسار، إذا استعملت الإشارة"],"h1":"اختر المسار الذي في جهة انعطافك نفسها.","h2":"لكي تنعطف يمينًا، تدخل المسار الأيمن قرب الرصيف، وتنعطف إلى المسار الأيمن في الشارع الجديد.","p":"صحيح. انعطف يمينًا من المسار الأيمن، قرب الرصيف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Nan ki liy ou ta dwe ye?","o":["Liy gòch la","Liy dwat la, pre rebò twotwa a","Liy mitan an","Nenpòt liy, si ou mete siyal"],"h1":"Chwazi liy ki sou menm bò ak kote w ap vire a.","h2":"Pou vire adwat, ou antre nan liy dwat la pre rebò twotwa a, epi ou vire nan liy dwat lari kote w ap antre a.","p":"Wi, se sa. Vire adwat sòti nan liy dwat la, pre rebò twotwa a."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-034","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, you turn left from a two-way street onto another two-way street. Which lane do you turn into?","o":["The bike lane","The lane for oncoming traffic","The center turn lane","Any lane going your way that you may legally use"],"h1":"Think about which lanes carry traffic in your direction.","h2":"When you turn left, you may finish in any lane going your way that you are allowed to use, and you never enter a lane for oncoming traffic.","p":"Right. Turn left into a lane going your way that you may legally use."},"es":{"q":"En Florida, usted dobla a la izquierda de una calle de doble sentido a otra calle de doble sentido. ¿A qué carril dobla?","o":["Al carril de bicicletas","Al carril del tráfico que viene de frente","Al carril central de vuelta","A cualquier carril en su misma dirección que usted pueda usar legalmente"],"h1":"Piense en qué carriles llevan el tráfico en su misma dirección.","h2":"Cuando usted dobla a la izquierda, puede terminar en cualquier carril en su misma dirección que tenga permitido usar, y nunca entra a un carril del tráfico que viene de frente.","p":"Correcto. Doble a la izquierda a un carril en su misma dirección que usted pueda usar legalmente."},"zh":{"q":"在 Florida，你从一条双向街道左转到另一条双向街道。你应该转进哪条车道？","o":["自行车道","对面来车的车道","中央转弯车道","任何和你同方向、而且你可以合法使用的车道"],"h1":"想一想哪些车道上的车和你同一个方向。","h2":"左转时，你可以转进任何和你同方向、而且你可以使用的车道，但永远不能进入对面来车的车道。","p":"对。左转进入和你同方向、你可以合法使用的车道。"},"vi":{"q":"Ở Florida, bạn rẽ trái từ một đường hai chiều sang một đường hai chiều khác. Bạn rẽ vào làn nào?","o":["Làn xe đạp","Làn của xe đi ngược chiều","Làn rẽ ở giữa","Bất kỳ làn nào cùng chiều với bạn mà bạn được phép dùng"],"h1":"Hãy nghĩ xem làn nào có xe chạy cùng hướng với bạn.","h2":"Khi rẽ trái, bạn có thể vào bất kỳ làn nào cùng chiều mà bạn được phép dùng, và bạn không bao giờ đi vào làn của xe ngược chiều.","p":"Đúng. Rẽ trái vào làn cùng chiều mà bạn được phép dùng."},"tl":{"q":"Sa Florida, kumaliwa ka mula sa kalyeng two-way papunta sa isa pang kalyeng two-way. Saang lane ka papasok?","o":["Sa bike lane","Sa lane ng paparating na trapiko","Sa center turn lane","Sa kahit anong lane na papunta sa direksiyon mo na legal mong magagamit"],"h1":"Isipin kung aling mga lane ang may trapiko sa direksiyon mo.","h2":"Kapag kumaliwa ka, puwede kang pumasok sa kahit anong lane na papunta sa direksiyon mo na pinapayagan kang gamitin, at hindi ka kailanman papasok sa lane ng paparating na trapiko.","p":"Tama. Kumaliwa papunta sa lane na papunta sa direksiyon mo na legal mong magagamit."},"ar":{"q":"في Florida، تنعطف يسارًا من شارع باتجاهين إلى شارع آخر باتجاهين. إلى أي مسار تنعطف؟","o":["مسار الدراجات","مسار السيارات القادمة نحوك","مسار الانعطاف في الوسط","أي مسار في اتجاهك يُسمح لك باستعماله"],"h1":"فكّر في المسارات التي تسير فيها السيارات في اتجاهك.","h2":"عندما تنعطف يسارًا، يمكنك أن تنهي الانعطاف في أي مسار في اتجاهك يُسمح لك باستعماله، ولا تدخل أبدًا مسار السيارات القادمة نحوك.","p":"صحيح. انعطف يسارًا إلى مسار في اتجاهك يُسمح لك قانونيًا باستعماله."},"ht":{"q":"Nan Florida, ou vire agòch sòti nan yon lari de sans pou antre nan yon lòt lari de sans. Nan ki liy ou antre?","o":["Liy pou bisiklèt la","Liy pou machin k ap vin sou ou yo","Liy pou vire nan mitan an","Nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li"],"h1":"Panse ak ki liy ki pote machin nan direksyon pa w la.","h2":"Lè ou vire agòch, ou ka fini nan nenpòt liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li, epi ou pa janm antre nan yon liy pou machin k ap vin sou ou.","p":"Wi, se sa. Vire agòch nan yon liy k ap ale nan direksyon pa w la ou gen dwa sèvi ak li."},"ref":{"doc":"FL","page":70}},{"id":"right-of-way-035","scope":"FL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn should you turn on your signal?","o":["Only as you start to turn","At least 10 feet before","At least 25 feet before","At least 100 feet before"],"h1":"Other drivers need time to see what you plan to do.","h2":"In Florida you should signal at least 100 feet before you turn, so drivers and people walking know what you will do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de doblar?","o":["Solo cuando empieza a doblar","Por lo menos 10 pies antes","Por lo menos 25 pies antes","Por lo menos 100 pies antes"],"h1":"Los otros conductores necesitan tiempo para ver lo que usted va a hacer.","h2":"En Florida usted debe poner la direccional por lo menos 100 pies antes de doblar, para que los conductores y los peatones sepan lo que va a hacer.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de doblar."},"zh":{"q":"在 Florida，转弯前多远应该打开转向灯？","o":["只在开始转弯的时候","至少提前 10 英尺","至少提前 25 英尺","至少提前 100 英尺"],"h1":"其他司机需要时间看清你要做什么。","h2":"在 Florida，你应该在转弯前至少 100 英尺打转向灯，让司机和行人知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn nên bật xi nhan bao xa trước khi rẽ?","o":["Chỉ khi bạn bắt đầu rẽ","Ít nhất 10 feet trước đó","Ít nhất 25 feet trước đó","Ít nhất 100 feet trước đó"],"h1":"Người lái khác cần thời gian để thấy bạn định làm gì.","h2":"Ở Florida, bạn nên bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái và người đi bộ biết bạn sẽ làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong buksan ang signal mo?","o":["Habang nagsisimula ka lang lumiko","Hindi bababa sa 10 feet bago lumiko","Hindi bababa sa 25 feet bago lumiko","Hindi bababa sa 100 feet bago lumiko"],"h1":"Kailangan ng ibang drayber ng oras para makita ang balak mong gawin.","h2":"Sa Florida, dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng mga drayber at ng mga naglalakad ang gagawin mo.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تشغّل إشارة الانعطاف؟","o":["فقط عندما أبدأ الانعطاف","10 أقدام على الأقل قبله","25 قدمًا على الأقل قبله","100 قدم على الأقل قبله"],"h1":"السائقون الآخرون يحتاجون إلى وقت ليروا ماذا تريد أن تفعل.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون والمشاة ماذا ستفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou ta dwe limen siyal ou?","o":["Sèlman lè w ap kòmanse vire","Omwen 10 pye anvan","Omwen 25 pye anvan","Omwen 100 pye anvan"],"h1":"Lòt chofè yo bezwen tan pou yo wè sa ou vle fè.","h2":"Nan Florida ou ta dwe mete siyal omwen 100 pye anvan ou vire, pou chofè yo ak moun k ap mache yo konnen sa ou pral fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"right-of-way-036","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, when may you make a U-turn?","o":["Any time you miss your street","Only when it is safe and no sign forbids it","Only on a highway","Only at a railroad crossing"],"h1":"Think about signs and about traffic around you.","h2":"You may make a U-turn only where no sign forbids it and only when you can do it safely without getting in the way of other traffic.","p":"Right. Make a U-turn only when it is safe and allowed."},"es":{"q":"En Florida, ¿cuándo puede dar una vuelta en U?","o":["Cada vez que se pase de su calle","Solo cuando es seguro y ninguna señal lo prohíbe","Solo en la autopista","Solo en un cruce de tren"],"h1":"Piense en las señales y en el tráfico a su alrededor.","h2":"Usted puede dar una vuelta en U solo donde ninguna señal lo prohíba y solo cuando pueda hacerla con seguridad, sin estorbar a otros vehículos.","p":"Correcto. Dé vuelta en U solo cuando sea seguro y permitido."},"zh":{"q":"在 Florida，什么时候可以掉头（U-turn）？","o":["每次错过你要去的街道时","只有在安全、而且没有标志禁止时","只在高速公路上","只在铁路道口"],"h1":"想一想标志，也想一想你周围的车。","h2":"只有在没有标志禁止的地方，而且你能安全掉头、不妨碍其他车辆时，你才可以掉头。","p":"对。只有在安全而且允许的时候才掉头。"},"vi":{"q":"Ở Florida, khi nào bạn được quay đầu xe hình chữ U?","o":["Bất cứ lúc nào bạn đi lố con đường của mình","Chỉ khi an toàn và không có biển báo cấm","Chỉ trên xa lộ","Chỉ ở chỗ giao nhau với đường sắt"],"h1":"Hãy nghĩ đến biển báo và xe cộ xung quanh bạn.","h2":"Bạn chỉ được quay đầu chữ U ở nơi không có biển báo cấm và chỉ khi bạn làm được một cách an toàn mà không cản trở xe khác.","p":"Đúng. Chỉ quay đầu chữ U khi an toàn và được phép."},"tl":{"q":"Sa Florida, kailan ka puwedeng mag-U-turn?","o":["Anumang oras na nalampasan mo ang kalye mo","Kapag ligtas lang at walang karatulang nagbabawal","Sa highway lang","Sa railroad crossing lang"],"h1":"Isipin ang mga karatula at ang trapiko sa paligid mo.","h2":"Puwede ka lang mag-U-turn kung walang karatulang nagbabawal nito at kung magagawa mo ito nang ligtas, nang hindi nakaharang sa ibang trapiko.","p":"Tama. Mag-U-turn lang kapag ligtas at pinapayagan."},"ar":{"q":"في Florida، متى يمكنك أن تقوم بدوران كامل للخلف (U-turn)؟","o":["في أي وقت عندما يفوتني الشارع","فقط عندما يكون آمنًا ولا توجد علامة تمنعه","فقط على الطريق السريع","فقط عند تقاطع سكة حديد"],"h1":"فكّر في العلامات وفي السيارات حولك.","h2":"يمكنك أن تقوم بدوران كامل للخلف فقط حيث لا توجد علامة تمنعه، وفقط عندما تستطيع أن تقوم به بأمان بدون أن تعيق السيارات الأخرى.","p":"صحيح. قم بالدوران الكامل للخلف فقط عندما يكون آمنًا ومسموحًا."},"ht":{"q":"Nan Florida, kilè ou ka fè yon demi-tou (U-turn)?","o":["Nenpòt lè ou rate lari ou a","Sèlman lè li pa danjere epi pa gen okenn siy ki entèdi l","Sèlman sou yon gran wout","Sèlman nan yon kwazman tren"],"h1":"Panse ak siy yo ak machin ki bò kote ou yo.","h2":"Ou ka fè yon demi-tou sèlman kote pa gen okenn siy ki entèdi l epi sèlman lè ou ka fè l san danje san ou pa jennen lòt machin yo.","p":"Wi, se sa. Fè yon demi-tou sèlman lè li pa danjere epi li pèmèt."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-037","scope":"FL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Florida, you stopped at a red light and want to turn right. A person is crossing in front of you. What do you do?","o":["Turn now, because right on red is allowed","Honk and turn","Wait for the person to cross, then turn when traffic is clear","Turn into the far lane to go around the person"],"h1":"A right turn on red is allowed only after you yield.","h2":"When you turn right on red, you must first stop and yield to people crossing and to traffic, so you wait until the way is clear.","p":"Right. On red, yield to people and traffic before you turn right."},"es":{"q":"En Florida, usted paró en una luz roja y quiere doblar a la derecha. Una persona está cruzando delante de usted. ¿Qué hace?","o":["Dobla ahora, porque se permite doblar a la derecha en rojo","Toca la bocina y dobla","Espera que la persona cruce y luego dobla cuando el tráfico esté libre","Dobla al carril lejano para pasar alrededor de la persona"],"h1":"Doblar a la derecha en rojo se permite solo después de ceder el paso.","h2":"Cuando usted dobla a la derecha en rojo, primero debe parar y ceder el paso a las personas que cruzan y al tráfico, así que espera hasta que el camino esté libre.","p":"Correcto. En rojo, ceda el paso a peatones y tráfico antes de doblar a la derecha."},"zh":{"q":"在 Florida，你在红灯前停下，想右转。有一个人正在你前面过马路。你该怎么做？","o":["现在就转，因为红灯可以右转","按喇叭，然后转","等这个人过完马路，路上没车了再转","转进最远的车道，绕过这个人"],"h1":"红灯右转只有在你让行以后才可以。","h2":"红灯右转时，你必须先停车，让过马路的人和其他车先走，所以要等路上安全了再转。","p":"对。红灯右转前，先让行人和车辆走。"},"vi":{"q":"Ở Florida, bạn đã dừng ở đèn đỏ và muốn rẽ phải. Có người đang băng qua đường trước mặt bạn. Bạn làm gì?","o":["Rẽ ngay, vì được phép rẽ phải khi đèn đỏ","Bấm còi và rẽ","Chờ người đó qua hết, rồi rẽ khi không có xe","Rẽ vào làn xa để vòng qua người đó"],"h1":"Rẽ phải khi đèn đỏ chỉ được phép sau khi bạn đã nhường đường.","h2":"Khi rẽ phải lúc đèn đỏ, trước tiên bạn phải dừng lại và nhường người đi bộ và xe cộ, nên bạn chờ đến khi đường trống.","p":"Đúng. Khi đèn đỏ, hãy nhường người đi bộ và xe cộ trước khi rẽ phải."},"tl":{"q":"Sa Florida, huminto ka sa pulang ilaw at gusto mong kumanan. May taong tumatawid sa harap mo. Ano ang gagawin mo?","o":["Kumanan na, dahil pinapayagan ang pagkanan sa pula","Bumusina at kumanan","Hintaying makatawid ang tao, saka kumanan kapag malinis na ang trapiko","Kumanan papunta sa malayong lane para iwasan ang tao"],"h1":"Pinapayagan ang pagkanan sa pula pagkatapos mo lang magbigay-daan.","h2":"Kapag kumakanan ka sa pula, dapat ka munang huminto at magbigay-daan sa mga tumatawid at sa trapiko, kaya maghihintay ka hanggang malinis ang daan.","p":"Tama. Sa pula, magbigay-daan sa mga tao at trapiko bago ka kumanan."},"ar":{"q":"في Florida، توقفت عند إشارة حمراء وتريد أن تنعطف يمينًا. شخص يعبر أمامك. ماذا تفعل؟","o":["أنعطف الآن، لأن الانعطاف يمينًا عند الإشارة الحمراء مسموح","أستعمل البوق وأنعطف","أنتظر حتى يعبر الشخص، ثم أنعطف عندما يكون الطريق فارغًا","أنعطف إلى المسار البعيد لألتف حول الشخص"],"h1":"الانعطاف يمينًا عند الإشارة الحمراء مسموح فقط بعد أن تعطي حق المرور.","h2":"عندما تنعطف يمينًا عند الإشارة الحمراء، يجب أولًا أن تتوقف وتعطي حق المرور للمشاة وللسيارات، لذلك تنتظر حتى يصبح الطريق فارغًا.","p":"صحيح. عند الإشارة الحمراء، أعطِ حق المرور للناس وللسيارات قبل أن تنعطف يمينًا."},"ht":{"q":"Nan Florida, ou kanpe nan yon limyè wouj epi ou vle vire adwat. Gen yon moun k ap travèse devan ou. Kisa ou fè?","o":["Ou vire kounye a, paske yo pèmèt vire adwat sou limyè wouj","Ou klaksonnen epi ou vire","Ou tann moun nan travèse, apre sa ou vire lè pa gen machin","Ou vire nan liy ki pi lwen an pou ou pase bò kote moun nan"],"h1":"Yo pèmèt ou vire adwat sou limyè wouj sèlman apre ou fin kite lòt yo pase.","h2":"Lè ou vire adwat sou limyè wouj, ou dwe kanpe anvan epi kite moun k ap travèse yo ak machin yo pase, kidonk ou tann jiskaske chemen an lib.","p":"Wi, se sa. Sou limyè wouj, kite moun yo ak machin yo pase anvan ou vire adwat."},"ref":{"doc":"FL","page":51}},{"id":"right-of-way-038","scope":"US","cat":"right-of-way","sign":{"shape":"yield","text":"YIELD"},"c":2,"en":{"q":"What does this red and white upside-down triangle sign tell you to do?","o":["Stop fully every time","Speed up and merge","Slow down and let other traffic go first, stopping if needed","Turn around"],"h1":"This sign does not always mean a full stop.","h2":"A yield sign means you slow down and let other traffic and people go first, and you stop only if you need to.","p":"Right. A yield sign means slow down and let others go first."},"es":{"q":"¿Qué le indica esta señal de triángulo rojo y blanco con la punta hacia abajo?","o":["Pare por completo siempre","Acelere y únase al tráfico","Baje la velocidad y deje pasar primero a los demás, parando si hace falta","Dé la vuelta"],"h1":"Esta señal no siempre significa un alto total.","h2":"Una señal de ceda el paso significa que usted baja la velocidad y deja pasar primero a otros vehículos y personas, y para solo si es necesario.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a los demás."},"zh":{"q":"这个红白色、倒三角形的标志告诉你要做什么？","o":["每次都要完全停车","加速并入车流","减速，让其他车先走，需要时停车","掉头"],"h1":"这个标志不一定是要你完全停车。","h2":"让行标志的意思是你要减速，让其他车和行人先走，只有在需要时才停车。","p":"对。让行标志的意思是减速，让别人先走。"},"vi":{"q":"Biển báo hình tam giác ngược màu đỏ và trắng này bảo bạn làm gì?","o":["Luôn luôn dừng hẳn","Tăng tốc và nhập làn","Giảm tốc và để xe khác đi trước, dừng lại nếu cần","Quay đầu xe"],"h1":"Biển này không phải lúc nào cũng có nghĩa là dừng hẳn.","h2":"Biển \"YIELD\" (Nhường đường) có nghĩa là bạn giảm tốc và để xe khác và người đi bộ đi trước, và bạn chỉ dừng lại nếu cần.","p":"Đúng. Biển \"YIELD\" có nghĩa là giảm tốc và để người khác đi trước."},"tl":{"q":"Ano ang sinasabi sa iyo ng pula at puting baligtad na tatsulok na karatulang ito?","o":["Huminto nang buo sa bawat pagkakataon","Bumilis at sumanib sa trapiko","Bumagal at paunahin ang ibang trapiko, at huminto kung kailangan","Umikot pabalik"],"h1":"Hindi laging buong paghinto ang ibig sabihin ng karatulang ito.","h2":"Ang \"YIELD\" sign (magbigay-daan) ay nangangahulugang babagal ka at paunahin ang ibang trapiko at mga tao, at hihinto ka lang kung kailangan.","p":"Tama. Ang \"YIELD\" sign ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"هذه العلامة مثلث أحمر وأبيض مقلوب. ماذا تطلب منك أن تفعل؟","o":["أتوقف توقفًا كاملًا كل مرة","أسرع وأندمج","أخفف السرعة وأترك السيارات الأخرى تمر أولًا، وأتوقف إذا لزم الأمر","أرجع من حيث جئت"],"h1":"هذه العلامة لا تعني دائمًا توقفًا كاملًا.","h2":"علامة \"YIELD\" (أعطِ حق المرور) تعني أن تخفف السرعة وتترك السيارات الأخرى والمشاة يمرون أولًا، وتتوقف فقط إذا احتجت إلى ذلك.","p":"صحيح. علامة \"YIELD\" (أعطِ حق المرور) تعني: خفف السرعة واترك الآخرين يمرون أولًا."},"ht":{"q":"Kisa siy wouj e blan sa a ki gen fòm yon triyang tèt anba di ou fè?","o":["Kanpe nèt chak fwa","Akselere epi antre nan sikilasyon an","Ralanti epi kite lòt machin yo pase anvan, kanpe si sa nesesè","Fè demi-tou"],"h1":"Siy sa a pa toujou vle di kanpe nèt.","h2":"Yon siy \"YIELD\" (kite pase) vle di ou ralanti epi ou kite lòt machin ak moun yo pase anvan, epi ou kanpe sèlman si ou bezwen.","p":"Wi, se sa. Yon siy \"YIELD\" vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"right-of-way-039","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you are on a ramp joining a highway. Who has the right of way?","o":["Traffic already on the highway","You, because you are on the ramp","The faster car","Whoever signals first"],"h1":"Think about who is already on the main road.","h2":"When you merge onto a highway, you must yield to the traffic already on it and find a safe gap.","p":"Right. When merging, yield to traffic already on the highway."},"es":{"q":"En Florida, usted va por una rampa para entrar a una carretera. ¿Quién tiene el derecho de paso?","o":["El tráfico que ya va por la carretera","Usted, porque va por la rampa","El carro más rápido","El que pone la direccional primero"],"h1":"Piense en quién ya está en la vía principal.","h2":"Cuando usted entra a una carretera, debe ceder el paso al tráfico que ya va por ella y buscar un espacio seguro.","p":"Correcto. Al entrar a la carretera, ceda el paso al tráfico que ya va por ella."},"zh":{"q":"在 Florida，你在匝道上，准备并入高速公路。谁有先行权？","o":["已经在高速公路上的车","你，因为你在匝道上","开得快的车","先打转向灯的人"],"h1":"想一想谁已经在主路上。","h2":"并入高速公路时，你必须让已经在高速公路上的车先走，并找到一个安全的空隙。","p":"对。并入时，让已经在高速公路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để nhập vào xa lộ. Ai có quyền ưu tiên?","o":["Xe đã ở trên xa lộ","Bạn, vì bạn đang ở trên đường dẫn","Xe chạy nhanh hơn","Người bật xi nhan trước"],"h1":"Hãy nghĩ xem ai đã ở trên đường chính rồi.","h2":"Khi nhập vào xa lộ, bạn phải nhường xe đã ở trên xa lộ và tìm khoảng trống an toàn.","p":"Đúng. Khi nhập làn, hãy nhường xe đã ở trên xa lộ."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa highway. Sino ang may karapatan sa daan?","o":["Ang trapikong nasa highway na","Ikaw, dahil nasa ramp ka","Ang mas mabilis na kotse","Kung sino ang unang mag-signal"],"h1":"Isipin kung sino na ang nasa pangunahing daan.","h2":"Kapag sumasanib ka sa highway, dapat kang magbigay-daan sa trapikong nasa highway na at maghanap ng ligtas na puwang.","p":"Tama. Kapag sumasanib, magbigay-daan sa trapikong nasa highway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع. من له حق المرور؟","o":["السيارات الموجودة على الطريق السريع","أنت، لأنك على منحدر الدخول","السيارة الأسرع","من يشغّل الإشارة أولًا"],"h1":"فكّر في من هو موجود الآن على الطريق الرئيسي.","h2":"عندما تندمج في طريق سريع، يجب أن تعطي حق المرور للسيارات الموجودة عليه وتجد مسافة آمنة.","p":"صحيح. عند الاندماج، أعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou yon ranp k ap antre sou yon gran wout. Kiyès ki gen dwa pou pase anvan?","o":["Machin ki deja sou gran wout la","Ou menm, paske ou sou ranp lan","Machin ki pi vit la","Moun ki mete siyal an premye a"],"h1":"Panse ak kiyès ki deja sou wout prensipal la.","h2":"Lè w ap antre sou yon gran wout, ou dwe kite machin ki deja sou li yo pase anvan epi chèche yon espas ki san danje.","p":"Wi, se sa. Lè w ap antre, kite machin ki deja sou gran wout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"right-of-way-040","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"You are about to enter a roundabout. Which way should you look for traffic?","o":["To your left, at cars already coming around","To your right only","Straight ahead only","Behind you only"],"h1":"In the U.S., traffic in a roundabout comes from the left.","h2":"Before entering a roundabout, look to your left, because traffic already in the circle comes toward you from that side.","p":"Right. Look left before you enter."},"es":{"q":"Usted va a entrar a una glorieta. ¿Hacia dónde debe mirar por el tráfico?","o":["A su izquierda, a los carros que ya vienen girando","Solo a su derecha","Solo de frente","Solo hacia atrás"],"h1":"En EE. UU., el tráfico de la glorieta viene por la izquierda.","h2":"Antes de entrar a una glorieta, mire a su izquierda, porque el tráfico que ya está en el círculo viene hacia usted por ese lado.","p":"Correcto. Mire a la izquierda antes de entrar."},"zh":{"q":"你马上要进入环岛。你应该朝哪个方向看来车？","o":["看你的左边，看已经在环岛里绕过来的车","只看你的右边","只看正前方","只看你的后面"],"h1":"在美国，环岛里的车从左边过来。","h2":"进入环岛前，要看你的左边，因为已经在环岛里的车是从那一边朝你开过来的。","p":"对。进入前先看左边。"},"vi":{"q":"Bạn sắp đi vào vòng xuyến. Bạn nên nhìn về phía nào để xem xe cộ?","o":["Nhìn sang bên trái, xem các xe đang chạy vòng tới","Chỉ nhìn sang bên phải","Chỉ nhìn thẳng phía trước","Chỉ nhìn phía sau"],"h1":"Ở Hoa Kỳ, xe trong vòng xuyến đến từ bên trái.","h2":"Trước khi vào vòng xuyến, hãy nhìn sang bên trái, vì xe đang ở trong vòng xuyến chạy về phía bạn từ bên đó.","p":"Đúng. Nhìn bên trái trước khi vào."},"tl":{"q":"Papasok ka na sa roundabout. Saang direksiyon ka dapat tumingin para sa mga sasakyan?","o":["Sa kaliwa mo, sa mga kotseng umiikot na papunta sa iyo","Sa kanan mo lang","Sa harap mo lang","Sa likod mo lang"],"h1":"Sa U.S., ang mga sasakyan sa roundabout ay galing sa kaliwa.","h2":"Bago pumasok sa roundabout, tumingin sa kaliwa mo, dahil ang mga sasakyang nasa loob na ng bilog ay papunta sa iyo mula sa panig na iyon.","p":"Tama. Tumingin sa kaliwa bago pumasok."},"ar":{"q":"أنت على وشك أن تدخل دوّارًا. إلى أي جهة يجب أن تنظر لترى السيارات؟","o":["إلى يسارك، إلى السيارات التي تدور وتأتي نحوك","إلى يمينك فقط","إلى الأمام مباشرة فقط","إلى الخلف فقط"],"h1":"في الولايات المتحدة، تأتي السيارات في الدوّار من اليسار.","h2":"قبل أن تدخل الدوّار، انظر إلى يسارك، لأن السيارات التي في الدائرة تأتي نحوك من تلك الجهة.","p":"صحيح. انظر إلى اليسار قبل أن تدخل."},"ht":{"q":"Ou pral antre nan yon wonpwen. Ki bò ou dwe gade pou wè machin yo?","o":["Sou bò gòch ou, machin ki deja ap vire vin sou ou yo","Sou bò dwat ou sèlman","Tou dwat devan ou sèlman","Dèyè ou sèlman"],"h1":"Nan Etazini, machin nan yon wonpwen soti sou bò gòch.","h2":"Anvan ou antre nan yon wonpwen, gade sou bò gòch ou, paske machin ki deja nan sèk la ap vin sou ou soti bò sa a.","p":"Wi, se sa. Gade sou bò gòch anvan ou antre."}},{"id":"right-of-way-041","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"You are driving inside a roundabout. When should you stop?","o":["At every entry, to let cars in","Only if you must, to avoid a crash; otherwise keep moving to your exit","Whenever you want to read the signs","Before each exit"],"h1":"Cars entering must yield to you.","h2":"Once you are inside a roundabout, keep moving to your exit and do not stop unless you must to avoid a crash.","p":"Right. Keep moving unless you must stop."},"es":{"q":"Usted maneja dentro de una glorieta. ¿Cuándo debe pararse?","o":["En cada entrada, para dejar entrar carros","Solo si es necesario para evitar un choque; si no, siga hasta su salida","Cuando quiera leer las señales","Antes de cada salida"],"h1":"Los que entran deben cederle el paso a usted.","h2":"Una vez dentro de la glorieta, siga avanzando hasta su salida y no se pare a menos que sea necesario para evitar un choque.","p":"Correcto. Siga avanzando salvo que deba pararse."},"zh":{"q":"你正在环岛里行驶。什么时候应该停车？","o":["在每个入口都停，让车进来","只有为了避免撞车而必须停时才停；否则继续开到你的出口","想看路牌时就停","在每个出口前停"],"h1":"要进入的车必须让你。","h2":"你一旦进入环岛，就要继续开到你的出口，除非为了避免撞车必须停，否则不要停。","p":"对。除非必须停，否则继续开。"},"vi":{"q":"Bạn đang lái trong vòng xuyến. Khi nào bạn nên dừng lại?","o":["Ở mọi lối vào, để cho xe vào","Chỉ khi bắt buộc, để tránh đâm xe; nếu không thì tiếp tục chạy đến lối ra của bạn","Bất cứ khi nào bạn muốn đọc biển báo","Trước mỗi lối ra"],"h1":"Xe đang đi vào phải nhường cho bạn.","h2":"Khi đã ở trong vòng xuyến, hãy tiếp tục chạy đến lối ra của bạn và đừng dừng lại, trừ khi bắt buộc phải dừng để tránh đâm xe.","p":"Đúng. Tiếp tục chạy, trừ khi bắt buộc phải dừng."},"tl":{"q":"Nagmamaneho ka sa loob ng roundabout. Kailan ka dapat huminto?","o":["Sa bawat pasukan, para papasukin ang mga kotse","Kung kailangan lang, para makaiwas sa banggaan; kung hindi, tuloy lang hanggang sa labasan mo","Kahit kailan mo gustong basahin ang mga karatula","Bago ang bawat labasan"],"h1":"Ang mga kotseng papasok ang dapat magbigay-daan sa iyo.","h2":"Kapag nasa loob ka na ng roundabout, tuloy-tuloy lang hanggang sa labasan mo at huwag huminto maliban kung kailangan para makaiwas sa banggaan.","p":"Tama. Tuloy lang maliban kung kailangan mong huminto."},"ar":{"q":"أنت تقود داخل دوّار. متى يجب أن تتوقف؟","o":["عند كل مدخل، لتترك السيارات تدخل","فقط إذا اضطررت لتتجنب حادثًا؛ وإلا فاستمر حتى مخرجك","كلما أردت أن تقرأ اللافتات","قبل كل مخرج"],"h1":"السيارات التي تدخل يجب أن تفسح لك الطريق.","h2":"عندما تكون داخل الدوّار، استمر في السير حتى مخرجك، ويجب ألّا تتوقف إلا إذا اضطررت لتتجنب حادثًا.","p":"صحيح. استمر في السير إلا إذا اضطررت للتوقف."},"ht":{"q":"W ap kondui anndan yon wonpwen. Kilè ou dwe kanpe?","o":["Nan chak antre, pou kite machin antre","Sèlman si ou oblije, pou evite yon aksidan; sinon kontinye jis rive nan sòti ou","Chak fwa ou vle li siy yo","Anvan chak sòti"],"h1":"Machin k ap antre yo dwe ba ou pase.","h2":"Yon fwa ou anndan yon wonpwen, kontinye jis rive nan sòti ou epi pa kanpe sòf si ou oblije pou evite yon aksidan.","p":"Wi, se sa. Kontinye sòf si ou oblije kanpe."}},{"id":"right-of-way-042","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You want to turn left at a roundabout. How do you do it?","o":["Turn left into the circle and go the short way","Drive across the center island","Go around the circle to the right (counterclockwise) to the exit on your left","Stop in the circle and wait for a gap"],"h1":"In a roundabout, everyone goes the same direction.","h2":"To turn left at a roundabout, enter to the right and go counterclockwise around the center island to the exit on your left.","p":"Right. Go around to the right to reach your exit."},"es":{"q":"Usted quiere girar a la izquierda en una glorieta. ¿Cómo lo hace?","o":["Gira a la izquierda al entrar y va por el lado corto","Cruza por la isla central","Da la vuelta al círculo hacia la derecha (en sentido contrario al reloj) hasta la salida a su izquierda","Se para en el círculo y espera un espacio"],"h1":"En una glorieta, todos van en la misma dirección.","h2":"Para girar a la izquierda en una glorieta, entre hacia la derecha y dé la vuelta en sentido contrario al reloj alrededor de la isla central hasta la salida a su izquierda.","p":"Correcto. Dé la vuelta por la derecha hasta su salida."},"zh":{"q":"你想在环岛左转。应该怎么做？","o":["左转进入环岛，走近路","直接开过中间的岛","在环岛里向右绕（逆时针方向），开到你左边的出口","在环岛里停下，等有空档"],"h1":"在环岛里，所有人都朝同一个方向走。","h2":"要在环岛左转，就向右进入，沿逆时针方向绕着中间的岛开，一直开到你左边的出口。","p":"对。向右绕，开到你的出口。"},"vi":{"q":"Bạn muốn rẽ trái ở vòng xuyến. Bạn làm thế nào?","o":["Rẽ trái vào vòng xuyến và đi đường tắt","Chạy băng qua đảo ở giữa","Chạy vòng sang phải (ngược chiều kim đồng hồ) đến lối ra bên trái của bạn","Dừng trong vòng xuyến và chờ khoảng trống"],"h1":"Trong vòng xuyến, mọi người đều đi cùng một chiều.","h2":"Để rẽ trái ở vòng xuyến, hãy đi vào về phía bên phải và chạy ngược chiều kim đồng hồ quanh đảo ở giữa đến lối ra bên trái của bạn.","p":"Đúng. Chạy vòng sang phải để đến lối ra của bạn."},"tl":{"q":"Gusto mong kumaliwa sa roundabout. Paano mo ito gagawin?","o":["Kumaliwa papasok sa bilog at dumaan sa maikling daan","Dumaan sa ibabaw ng isla sa gitna","Umikot sa bilog pakanan (counterclockwise) hanggang sa labasang nasa kaliwa mo","Huminto sa bilog at maghintay ng puwang"],"h1":"Sa roundabout, iisa ang direksiyon ng lahat.","h2":"Para kumaliwa sa roundabout, pumasok pakanan at umikot nang counterclockwise sa paligid ng isla sa gitna hanggang sa labasang nasa kaliwa mo.","p":"Tama. Umikot pakanan para marating ang labasan mo."},"ar":{"q":"تريد أن تنعطف يسارًا عند دوّار. كيف تفعل ذلك؟","o":["انعطف يسارًا إلى الدائرة وخذ الطريق القصير","اعبر فوق الجزيرة التي في الوسط","دُر حول الدائرة إلى اليمين (عكس عقارب الساعة) حتى المخرج الذي على يسارك","توقف في الدائرة وانتظر فرصة"],"h1":"في الدوّار، يسير الجميع في الاتجاه نفسه.","h2":"لتنعطف يسارًا عند الدوّار، ادخل إلى اليمين ودُر عكس عقارب الساعة حول الجزيرة التي في الوسط حتى المخرج الذي على يسارك.","p":"صحيح. دُر إلى اليمين لتصل إلى مخرجك."},"ht":{"q":"Ou vle vire agòch nan yon wonpwen. Kijan ou fè sa?","o":["Vire agòch nan sèk la epi pran chemen kout la","Travèse sou zile ki nan mitan an","Fè wonn sèk la adwat (nan sans kont aiguille mont) jis rive nan sòti ki sou bò gòch ou","Kanpe nan sèk la epi tann yon espas"],"h1":"Nan yon wonpwen, tout moun ale nan menm direksyon.","h2":"Pou vire agòch nan yon wonpwen, antre adwat epi fè wonn zile ki nan mitan an nan sans kont aiguille mont jis rive nan sòti ki sou bò gòch ou.","p":"Wi, se sa. Fè wonn adwat pou rive nan sòti ou."}},{"id":"right-of-way-043","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You are inside a roundabout and miss your exit. What should you do?","o":["Stop and back up","Turn sharply across the lanes","Exit through the center island","Go around the circle again to your exit"],"h1":"A roundabout lets you circle again safely.","h2":"If you miss your exit in a roundabout, simply go around again; never stop or back up.","p":"Right. Go around again."},"es":{"q":"Usted está dentro de una glorieta y se pasa de su salida. ¿Qué debe hacer?","o":["Pararse y retroceder","Girar bruscamente cruzando los carriles","Salir por la isla central","Dar otra vuelta al círculo hasta su salida"],"h1":"Una glorieta le permite dar otra vuelta con seguridad.","h2":"Si se pasa de su salida en una glorieta, simplemente dé otra vuelta; nunca se pare ni retroceda.","p":"Correcto. Dé otra vuelta."},"zh":{"q":"你在环岛里，错过了你的出口。你应该怎么做？","o":["停下来倒车","急转弯穿过车道","从中间的岛开出去","在环岛里再绕一圈，开到你的出口"],"h1":"环岛让你可以安全地再绕一圈。","h2":"如果你在环岛里错过了出口，只要再绕一圈就好；绝对不要停车或倒车。","p":"对。再绕一圈。"},"vi":{"q":"Bạn đang ở trong vòng xuyến và đi lỡ lối ra. Bạn nên làm gì?","o":["Dừng lại và lùi xe","Quẹo gắt băng qua các làn xe","Thoát ra bằng cách chạy qua đảo ở giữa","Chạy thêm một vòng nữa đến lối ra của bạn"],"h1":"Vòng xuyến cho phép bạn chạy thêm một vòng an toàn.","h2":"Nếu bạn lỡ lối ra trong vòng xuyến, chỉ cần chạy thêm một vòng nữa; không bao giờ dừng lại hay lùi xe.","p":"Đúng. Chạy thêm một vòng."},"tl":{"q":"Nasa loob ka ng roundabout at nalampasan mo ang labasan mo. Ano ang dapat mong gawin?","o":["Huminto at umatras","Lumiko nang matalim pahalang sa mga lane","Lumabas sa ibabaw ng isla sa gitna","Umikot ulit sa bilog hanggang sa labasan mo"],"h1":"Sa roundabout, puwede kang umikot ulit nang ligtas.","h2":"Kapag nalampasan mo ang labasan mo sa roundabout, umikot ka lang ulit; huwag kailanman huminto o umatras.","p":"Tama. Umikot ulit."},"ar":{"q":"أنت داخل دوّار وفاتك مخرجك. ماذا يجب أن تفعل؟","o":["توقف وارجع إلى الخلف","انعطف بحدة عبر المسارات","اخرج عبر الجزيرة التي في الوسط","دُر حول الدائرة مرة أخرى حتى مخرجك"],"h1":"الدوّار يسمح لك أن تدور مرة أخرى بأمان.","h2":"إذا فاتك مخرجك في الدوّار، فدُر مرة أخرى فقط؛ ويجب ألّا تتوقف أو ترجع إلى الخلف أبدًا.","p":"صحيح. دُر مرة أخرى."},"ht":{"q":"Ou anndan yon wonpwen epi ou rate sòti ou. Kisa ou dwe fè?","o":["Kanpe epi fè bak","Vire sèk atravè liy yo","Sòti pa sou zile ki nan mitan an","Fè wonn sèk la ankò jis rive nan sòti ou"],"h1":"Yon wonpwen pèmèt ou fè wonn ankò san danje.","h2":"Si ou rate sòti ou nan yon wonpwen, senpleman fè wonn lan ankò; pa janm kanpe ni fè bak.","p":"Wi, se sa. Fè wonn lan ankò."}},{"id":"right-of-way-044","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In a roundabout with two lanes, which lane is usually used to turn left or make a U-turn?","o":["The left (inside) lane, unless signs or arrows say otherwise","The right (outside) lane","Either lane, and change lanes in the circle","The shoulder"],"h1":"Choose your lane before you enter.","h2":"In a two-lane roundabout, you usually use the left lane to turn left or make a U-turn, following any signs and lane arrows, and choose it before entering.","p":"Right. Usually the left lane, chosen before you enter."},"es":{"q":"En una glorieta de dos carriles, ¿qué carril se usa normalmente para girar a la izquierda o dar la vuelta en U?","o":["El carril izquierdo (interior), salvo que las señales o flechas indiquen otra cosa","El carril derecho (exterior)","Cualquiera, cambiando de carril dentro del círculo","El acotamiento"],"h1":"Escoja su carril antes de entrar.","h2":"En una glorieta de dos carriles, normalmente se usa el carril izquierdo para girar a la izquierda o dar la vuelta en U, siguiendo las señales y flechas, y se escoge antes de entrar.","p":"Correcto. Normalmente el izquierdo, escogido antes de entrar."},"zh":{"q":"在有两条车道的环岛里，左转或掉头通常用哪条车道？","o":["左边（内侧）车道，除非标志或箭头另有指示","右边（外侧）车道","哪条都可以，在环岛里再换车道","路肩"],"h1":"进入前先选好车道。","h2":"在有两条车道的环岛里，左转或掉头通常用左边车道，要按照标志和车道箭头，并在进入前选好。","p":"对。通常用左边车道，进入前选好。"},"vi":{"q":"Trong vòng xuyến có hai làn xe, làn nào thường dùng để rẽ trái hoặc quay đầu?","o":["Làn bên trái (làn trong), trừ khi biển báo hoặc mũi tên chỉ khác","Làn bên phải (làn ngoài)","Làn nào cũng được, và đổi làn trong vòng xuyến","Lề đường"],"h1":"Hãy chọn làn trước khi đi vào.","h2":"Trong vòng xuyến có hai làn, bạn thường dùng làn bên trái để rẽ trái hoặc quay đầu, theo biển báo và mũi tên trên làn, và chọn làn trước khi vào.","p":"Đúng. Thường là làn bên trái, chọn trước khi vào."},"tl":{"q":"Sa roundabout na may dalawang lane, aling lane ang karaniwang ginagamit para kumaliwa o mag-U-turn?","o":["Ang kaliwang lane (sa loob), maliban kung iba ang sinasabi ng mga karatula o arrow","Ang kanang lane (sa labas)","Kahit aling lane, at lumipat ng lane sa loob ng bilog","Ang gilid ng daan (shoulder)"],"h1":"Pumili ng lane bago ka pumasok.","h2":"Sa roundabout na may dalawang lane, karaniwang ginagamit mo ang kaliwang lane para kumaliwa o mag-U-turn, sinusunod ang mga karatula at arrow sa lane, at pinipili mo ito bago pumasok.","p":"Tama. Karaniwang ang kaliwang lane, pinili bago pumasok."},"ar":{"q":"في دوّار فيه مساران، أي مسار يُستعمل عادةً للانعطاف يسارًا أو للدوران للخلف (U-turn)؟","o":["المسار الأيسر (الداخلي)، إلا إذا قالت اللافتات أو الأسهم غير ذلك","المسار الأيمن (الخارجي)","أي مسار، مع تغيير المسار داخل الدائرة","كتف الطريق"],"h1":"اختر مسارك قبل أن تدخل.","h2":"في دوّار فيه مساران، تستعمل عادةً المسار الأيسر للانعطاف يسارًا أو للدوران للخلف، مع اتباع اللافتات وأسهم المسارات، وتختاره قبل أن تدخل.","p":"صحيح. عادةً المسار الأيسر، وتختاره قبل أن تدخل."},"ht":{"q":"Nan yon wonpwen ki gen de liy, ki liy yo konn sèvi pou vire agòch oswa fè demi-tou (U-turn)?","o":["Liy gòch la (anndan an), sòf si siy oswa flèch di yon lòt bagay","Liy dwat la (deyò a)","Nenpòt liy, epi chanje liy nan sèk la","Bòdi wout la"],"h1":"Chwazi liy ou anvan ou antre.","h2":"Nan yon wonpwen ki gen de liy, ou konn sèvi ak liy gòch la pou vire agòch oswa fè demi-tou, swiv siy yo ak flèch ki sou liy yo, epi chwazi l anvan ou antre.","p":"Wi, se sa. Anjeneral liy gòch la, chwazi anvan ou antre."}},{"id":"right-of-way-045","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A large truck is entering a roundabout next to you. What should you do?","o":["Drive next to it so you both fit","Stay back; do not drive beside the truck in the circle","Pass it inside the circle","Honk so it waits"],"h1":"Long trucks need extra room to turn.","h2":"A large truck may use more than one lane and the center apron in a roundabout, so stay back and do not drive beside it.","p":"Right. Give the truck room."},"es":{"q":"Un camión grande entra a una glorieta al lado de usted. ¿Qué debe hacer?","o":["Manejar a su lado porque caben los dos","Quedarse atrás; no manejar al lado del camión en el círculo","Rebasarlo dentro del círculo","Tocar la bocina para que espere"],"h1":"Los camiones largos necesitan más espacio para girar.","h2":"Un camión grande puede usar más de un carril y la plataforma central de la glorieta, así que quédese atrás y no maneje a su lado.","p":"Correcto. Dele espacio al camión."},"zh":{"q":"一辆大卡车正在你旁边进入环岛。你应该怎么做？","o":["开在它旁边，你们两个都能挤进去","留在后面；在环岛里不要开在卡车旁边","在环岛里超过它","按喇叭让它等"],"h1":"长卡车转弯需要更多空间。","h2":"大卡车在环岛里可能会占用不止一条车道，还会压到中间的路缘区，所以要留在后面，不要开在它旁边。","p":"对。给卡车留出空间。"},"vi":{"q":"Một xe tải lớn đang đi vào vòng xuyến bên cạnh bạn. Bạn nên làm gì?","o":["Chạy song song với nó vì cả hai đều vừa","Lùi lại phía sau; không chạy bên cạnh xe tải trong vòng xuyến","Vượt nó trong vòng xuyến","Bấm còi để nó chờ"],"h1":"Xe tải dài cần thêm chỗ để quẹo.","h2":"Xe tải lớn có thể dùng nhiều hơn một làn và cả phần nền quanh đảo ở giữa vòng xuyến, vì vậy hãy lùi lại phía sau và đừng chạy bên cạnh nó.","p":"Đúng. Chừa chỗ cho xe tải."},"tl":{"q":"May malaking trak na papasok sa roundabout sa tabi mo. Ano ang dapat mong gawin?","o":["Magmaneho sa tabi nito para kasya kayong dalawa","Manatili sa likod; huwag magmaneho sa tabi ng trak sa loob ng bilog","Lampasan ito sa loob ng bilog","Bumusina para maghintay ito"],"h1":"Kailangan ng mahahabang trak ng dagdag na espasyo para lumiko.","h2":"Puwedeng gumamit ang malaking trak ng higit sa isang lane at ng gilid ng isla sa gitna (apron) sa roundabout, kaya manatili sa likod at huwag magmaneho sa tabi nito.","p":"Tama. Bigyan ng espasyo ang trak."},"ar":{"q":"شاحنة كبيرة تدخل الدوّار بجانبك. ماذا يجب أن تفعل؟","o":["سِر بجانبها لأنكما تتسعان معًا","ابقَ في الخلف؛ ويجب ألّا تسير بجانب الشاحنة داخل الدائرة","تجاوزها داخل الدائرة","استعمل البوق لكي تنتظر"],"h1":"الشاحنات الطويلة تحتاج إلى مساحة إضافية لتنعطف.","h2":"قد تستعمل الشاحنة الكبيرة أكثر من مسار والحافة المنخفضة حول الجزيرة الوسطى في الدوّار، لذلك ابقَ في الخلف ويجب ألّا تسير بجانبها.","p":"صحيح. اترك مساحة للشاحنة."},"ht":{"q":"Yon gwo kamyon ap antre nan yon wonpwen bò kote ou. Kisa ou dwe fè?","o":["Kondui bò kote l pou nou toude ka pase","Rete dèyè; pa kondui bò kote kamyon an nan sèk la","Double l anndan sèk la","Klaksonnen pou l tann"],"h1":"Kamyon ki long bezwen plis espas pou vire.","h2":"Yon gwo kamyon ka sèvi ak plis pase yon liy ak bòdi ki ozalantou zile nan mitan wonpwen an, kidonk rete dèyè epi pa kondui bò kote l.","p":"Wi, se sa. Bay kamyon an espas."}},{"id":"right-of-way-046","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You are leaving a roundabout. People are in the crosswalk on the exit road. What should you do?","o":["Drive around them","Honk so they hurry","Stop and let them cross before you exit","Stay in the circle until they finish"],"h1":"Crosswalks are just before and after the circle.","h2":"At a roundabout, crosswalks are set back from the circle, so when you exit you must stop for people in the crosswalk.","p":"Right. Let them cross before you exit."},"es":{"q":"Usted está saliendo de una glorieta. Hay personas en el cruce peatonal de la vía de salida. ¿Qué debe hacer?","o":["Rodearlas","Tocar la bocina para que se apuren","Pararse y dejarlas cruzar antes de salir","Quedarse dando vueltas hasta que terminen"],"h1":"Los cruces peatonales están justo antes y después del círculo.","h2":"En una glorieta, los cruces peatonales están un poco alejados del círculo, así que al salir debe pararse por las personas que estén en el cruce.","p":"Correcto. Déjelas cruzar antes de salir."},"zh":{"q":"你正要离开环岛。出口路上的人行横道上有人。你应该怎么做？","o":["绕过他们开过去","按喇叭让他们快点","停车，让他们过完再出去","留在环岛里，等他们走完"],"h1":"人行横道就在环岛前后不远的地方。","h2":"在环岛，人行横道设在离环岛稍远的地方，所以你开出去时必须为人行横道上的人停车。","p":"对。让他们过完再出去。"},"vi":{"q":"Bạn đang rời vòng xuyến. Có người đang đi trên vạch qua đường ở đường ra. Bạn nên làm gì?","o":["Chạy vòng qua họ","Bấm còi để họ đi nhanh","Dừng lại và để họ qua đường trước khi bạn ra","Ở lại trong vòng xuyến cho đến khi họ qua xong"],"h1":"Vạch qua đường nằm ngay trước và sau vòng xuyến.","h2":"Ở vòng xuyến, vạch qua đường được đặt lùi ra xa vòng tròn, vì vậy khi ra khỏi vòng xuyến bạn phải dừng lại cho người đang đi trên vạch qua đường.","p":"Đúng. Để họ qua đường trước khi bạn ra."},"tl":{"q":"Lalabas ka na sa roundabout. May mga tao sa tawiran sa daang labasan. Ano ang dapat mong gawin?","o":["Lumigid sa kanila","Bumusina para magmadali sila","Huminto at hayaan silang tumawid bago ka lumabas","Manatili sa bilog hanggang matapos sila"],"h1":"Ang mga tawiran ay nasa bandang unahan at likuran lang ng bilog.","h2":"Sa roundabout, medyo malayo sa bilog ang mga tawiran, kaya kapag lumabas ka, dapat kang huminto para sa mga taong nasa tawiran.","p":"Tama. Hayaan silang tumawid bago ka lumabas."},"ar":{"q":"أنت تخرج من دوّار. هناك أشخاص على ممر المشاة في طريق الخروج. ماذا يجب أن تفعل؟","o":["التفّ حولهم بسيارتك","استعمل البوق لكي يسرعوا","توقف ودعهم يعبرون قبل أن تخرج","ابقَ في الدائرة حتى ينتهوا"],"h1":"ممرات المشاة تكون قبل الدائرة وبعدها بقليل.","h2":"في الدوّار، تكون ممرات المشاة بعيدة قليلًا عن الدائرة، لذلك عندما تخرج يجب أن تتوقف للأشخاص الذين على ممر المشاة.","p":"صحيح. دعهم يعبرون قبل أن تخرج."},"ht":{"q":"W ap sòti nan yon wonpwen. Gen moun nan pasaj pyeton an sou wout sòti a. Kisa ou dwe fè?","o":["Kondui fè wonn yo","Klaksonnen pou yo prese","Kanpe epi kite yo travèse anvan ou sòti","Rete nan sèk la jiskaske yo fini"],"h1":"Pasaj pyeton yo jis anvan ak apre sèk la.","h2":"Nan yon wonpwen, pasaj pyeton yo yon ti jan lwen sèk la, kidonk lè ou sòti ou dwe kanpe pou moun ki nan pasaj pyeton an.","p":"Wi, se sa. Kite yo travèse anvan ou sòti."}},{"id":"right-of-way-047","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You are in a roundabout and hear a siren behind you. What should you do?","o":["Stop right away inside the circle","Speed up and go around again","Pull onto the center island","Drive on to your exit, leave the roundabout, then pull over"],"h1":"Stopping inside the circle can block the emergency vehicle.","h2":"If an emergency vehicle comes while you are in a roundabout, continue to your exit, leave the circle, and then pull over to let it pass.","p":"Right. Exit first, then pull over."},"es":{"q":"Usted está en una glorieta y oye una sirena detrás. ¿Qué debe hacer?","o":["Pararse enseguida dentro del círculo","Acelerar y dar otra vuelta","Subirse a la isla central","Seguir hasta su salida, salir de la glorieta y luego orillarse"],"h1":"Pararse dentro del círculo puede bloquear al vehículo de emergencia.","h2":"Si viene un vehículo de emergencia mientras está en una glorieta, siga hasta su salida, salga del círculo y luego oríllese para dejarlo pasar.","p":"Correcto. Salga primero y luego oríllese."},"zh":{"q":"你在环岛里，听到后面有警笛声。你应该怎么做？","o":["马上在环岛里停下","加速再绕一圈","开到中间的岛上","继续开到你的出口，离开环岛，然后靠边停车"],"h1":"在环岛里停车可能会挡住紧急车辆。","h2":"如果你在环岛里时有紧急车辆过来，要继续开到你的出口，离开环岛，然后靠边停车让它过去。","p":"对。先出去，再靠边停车。"},"vi":{"q":"Bạn đang ở trong vòng xuyến và nghe tiếng còi hú phía sau. Bạn nên làm gì?","o":["Dừng lại ngay trong vòng xuyến","Tăng tốc và chạy thêm một vòng","Tấp lên đảo ở giữa","Chạy tiếp đến lối ra, rời vòng xuyến, rồi tấp vào lề"],"h1":"Dừng lại trong vòng xuyến có thể chặn đường xe khẩn cấp.","h2":"Nếu có xe khẩn cấp đến khi bạn đang ở trong vòng xuyến, hãy tiếp tục đến lối ra, rời vòng xuyến, rồi tấp vào lề để xe đó đi qua.","p":"Đúng. Ra khỏi vòng xuyến trước, rồi tấp vào lề."},"tl":{"q":"Nasa roundabout ka at nakarinig ka ng sirena sa likod mo. Ano ang dapat mong gawin?","o":["Huminto agad sa loob ng bilog","Bumilis at umikot ulit","Umakyat sa isla sa gitna","Tumuloy sa labasan mo, lumabas sa roundabout, saka tumabi"],"h1":"Kapag huminto ka sa loob ng bilog, puwede mong maharangan ang emergency vehicle.","h2":"Kung may dumating na emergency vehicle habang nasa roundabout ka, tumuloy sa labasan mo, lumabas sa bilog, saka tumabi para makadaan ito.","p":"Tama. Lumabas muna, saka tumabi."},"ar":{"q":"أنت في دوّار وتسمع صفارة خلفك. ماذا يجب أن تفعل؟","o":["توقف فورًا داخل الدائرة","أسرع ودُر مرة أخرى","اصعد إلى الجزيرة التي في الوسط","تابع إلى مخرجك، واخرج من الدوّار، ثم توقف على جانب الطريق"],"h1":"التوقف داخل الدائرة قد يسد طريق مركبة الطوارئ.","h2":"إذا جاءت مركبة طوارئ وأنت في الدوّار، فتابع إلى مخرجك، واخرج من الدائرة، ثم توقف على جانب الطريق لتتركها تمر.","p":"صحيح. اخرج أولًا، ثم توقف على جانب الطريق."},"ht":{"q":"Ou nan yon wonpwen epi ou tande yon siren dèyè ou. Kisa ou dwe fè?","o":["Kanpe touswit anndan sèk la","Akselere epi fè wonn lan ankò","Monte sou zile ki nan mitan an","Kontinye jis nan sòti ou, kite wonpwen an, epi rale sou kote"],"h1":"Si ou kanpe anndan sèk la, ou ka bloke machin ijans lan.","h2":"Si yon machin ijans vini pandan ou nan yon wonpwen, kontinye jis nan sòti ou, kite sèk la, epi rale sou kote pou kite l pase.","p":"Wi, se sa. Sòti anvan, epi rale sou kote."}},{"id":"right-of-way-048","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"What should you do just before you leave a roundabout?","o":["Turn on your right turn signal","Turn on your left turn signal","Turn on your hazard lights","Honk your horn"],"h1":"Others need to know you are leaving.","h2":"Signal right just before your exit so drivers waiting to enter and people walking know you are leaving the roundabout.","p":"Right. Signal right before your exit."},"es":{"q":"¿Qué debe hacer justo antes de salir de una glorieta?","o":["Encender la direccional derecha","Encender la direccional izquierda","Encender las luces de emergencia","Tocar la bocina"],"h1":"Los demás necesitan saber que usted sale.","h2":"Ponga la direccional derecha justo antes de su salida para que los que esperan entrar y los peatones sepan que sale de la glorieta.","p":"Correcto. Señale a la derecha antes de salir."},"zh":{"q":"在你快要离开环岛之前，应该做什么？","o":["打开右转灯","打开左转灯","打开双闪灯","按喇叭"],"h1":"别人需要知道你要离开了。","h2":"在你的出口前打右转灯，让等着进入的司机和行人知道你要离开环岛。","p":"对。在出口前打右转灯。"},"vi":{"q":"Bạn nên làm gì ngay trước khi rời vòng xuyến?","o":["Bật đèn xi-nhan phải","Bật đèn xi-nhan trái","Bật đèn khẩn cấp","Bấm còi"],"h1":"Người khác cần biết bạn đang rời đi.","h2":"Hãy bật xi-nhan phải ngay trước lối ra để người lái đang chờ vào và người đi bộ biết bạn đang rời vòng xuyến.","p":"Đúng. Bật xi-nhan phải trước lối ra."},"tl":{"q":"Ano ang dapat mong gawin bago ka lumabas sa roundabout?","o":["Buksan ang right turn signal mo","Buksan ang left turn signal mo","Buksan ang hazard lights mo","Bumusina"],"h1":"Kailangang malaman ng iba na lalabas ka na.","h2":"Mag-signal pakanan bago ang labasan mo para malaman ng mga drayber na naghihintay pumasok at ng mga naglalakad na lalabas ka na sa roundabout.","p":"Tama. Mag-signal pakanan bago ang labasan mo."},"ar":{"q":"ماذا يجب أن تفعل قبل أن تخرج من الدوّار مباشرةً؟","o":["شغّل إشارة الانعطاف إلى اليمين","شغّل إشارة الانعطاف إلى اليسار","شغّل أضواء التحذير","استعمل البوق"],"h1":"الآخرون يحتاجون أن يعرفوا أنك تخرج.","h2":"شغّل إشارة اليمين قبل مخرجك مباشرةً، لكي يعرف السائقون الذين ينتظرون الدخول والمشاة أنك تخرج من الدوّار.","p":"صحيح. شغّل إشارة اليمين قبل مخرجك."},"ht":{"q":"Kisa ou dwe fè jis anvan ou sòti nan yon wonpwen?","o":["Limen siyal pou vire adwat ou","Limen siyal pou vire agòch ou","Limen limyè danje ou (hazard)","Klaksonnen"],"h1":"Lòt moun bezwen konnen w ap sòti.","h2":"Mete siyal adwat jis anvan sòti ou pou chofè k ap tann pou antre yo ak moun k ap mache yo konnen w ap kite wonpwen an.","p":"Wi, se sa. Mete siyal adwat anvan sòti ou."}},{"id":"right-of-way-049","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"You hear a siren but cannot tell where the emergency vehicle is. What should you do?","o":["Keep driving at the same speed","Slow down, check your mirrors and look around, and be ready to pull over","Stop in your lane right away","Speed up to get out of the way"],"h1":"You need to find the vehicle before you act.","h2":"When you hear a siren but cannot see the vehicle, slow down, check mirrors and around you, and be ready to pull over and stop.","p":"Right. Slow down, look, and be ready."},"es":{"q":"Usted oye una sirena pero no sabe dónde está el vehículo de emergencia. ¿Qué debe hacer?","o":["Seguir a la misma velocidad","Bajar la velocidad, mirar los espejos y alrededor, y estar listo para orillarse","Pararse enseguida en su carril","Acelerar para quitarse del camino"],"h1":"Necesita encontrar el vehículo antes de actuar.","h2":"Cuando oye una sirena pero no ve el vehículo, baje la velocidad, revise los espejos y su alrededor, y esté listo para orillarse y pararse.","p":"Correcto. Baje la velocidad, mire y esté listo."},"zh":{"q":"你听到警笛声，但看不出紧急车辆在哪里。你应该怎么做？","o":["保持原来的速度继续开","减速，看后视镜，看看四周，准备好靠边停车","马上在你的车道里停下","加速开走，让开路"],"h1":"行动之前，你要先找到那辆车。","h2":"当你听到警笛声却看不到车时，要减速，看后视镜和四周，并准备好靠边停车。","p":"对。减速，看清楚，做好准备。"},"vi":{"q":"Bạn nghe tiếng còi hú nhưng không biết xe khẩn cấp ở đâu. Bạn nên làm gì?","o":["Tiếp tục lái với cùng tốc độ","Chạy chậm lại, nhìn gương và nhìn xung quanh, sẵn sàng tấp vào lề","Dừng ngay trong làn của bạn","Tăng tốc để tránh đường"],"h1":"Bạn cần tìm ra chiếc xe trước khi hành động.","h2":"Khi nghe tiếng còi hú mà không thấy xe, hãy chạy chậm lại, nhìn gương và xung quanh, và sẵn sàng tấp vào lề và dừng lại.","p":"Đúng. Chạy chậm, nhìn quanh, và sẵn sàng."},"tl":{"q":"May naririnig kang sirena pero hindi mo alam kung nasaan ang emergency vehicle. Ano ang dapat mong gawin?","o":["Magpatuloy sa parehong bilis","Bumagal, tingnan ang mga salamin at ang paligid, at maging handang tumabi","Huminto agad sa lane mo","Bumilis para makaalis sa daan"],"h1":"Kailangan mo munang makita ang sasakyan bago kumilos.","h2":"Kapag may naririnig kang sirena pero hindi mo makita ang sasakyan, bumagal, tingnan ang mga salamin at ang paligid mo, at maging handang tumabi at huminto.","p":"Tama. Bumagal, tumingin, at maging handa."},"ar":{"q":"تسمع صفارة لكنك لا تعرف أين مركبة الطوارئ. ماذا يجب أن تفعل؟","o":["تابع القيادة بالسرعة نفسها","خفّف السرعة، وانظر في المرايا وحولك، وكن مستعدًا للتوقف على جانب الطريق","توقف فورًا في مسارك","أسرع لتبتعد عن الطريق"],"h1":"تحتاج أن تجد المركبة قبل أن تتصرف.","h2":"عندما تسمع صفارة ولا ترى المركبة، خفّف السرعة، وانظر في المرايا وحولك، وكن مستعدًا لأن تتنحى إلى جانب الطريق وتتوقف.","p":"صحيح. خفّف السرعة، وانظر، وكن مستعدًا."},"ht":{"q":"Ou tande yon siren men ou pa ka di ki kote machin ijans lan ye. Kisa ou dwe fè?","o":["Kontinye kondui menm vitès la","Ralanti, gade nan retwovizè ou yo ak toutotou ou, epi pare pou rale sou kote","Kanpe touswit nan liy ou","Akselere pou soti nan chemen an"],"h1":"Ou bezwen jwenn machin nan anvan ou aji.","h2":"Lè ou tande yon siren men ou pa wè machin nan, ralanti, gade nan retwovizè yo ak toutotou ou, epi pare pou rale sou kote epi kanpe.","p":"Wi, se sa. Ralanti, gade, epi pare."}},{"id":"right-of-way-050","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You pulled over for a fire truck. It has passed. What should you do before you drive on?","o":["Follow close behind the fire truck","Pull out right away to catch up with traffic","Check for more emergency vehicles, then merge back carefully","Turn on your hazard lights and drive on the shoulder"],"h1":"Emergency vehicles often travel in groups.","h2":"After an emergency vehicle passes, look and listen for others that may follow, then signal and return to traffic carefully.","p":"Right. Check for more, then merge carefully."},"es":{"q":"Usted se orilló por un camión de bomberos. Ya pasó. ¿Qué debe hacer antes de seguir?","o":["Seguir muy de cerca al camión de bomberos","Salir enseguida para alcanzar al tráfico","Fijarse si vienen más vehículos de emergencia y volver al tráfico con cuidado","Poner las luces de emergencia y seguir por el acotamiento"],"h1":"Los vehículos de emergencia muchas veces van en grupo.","h2":"Después de que pasa un vehículo de emergencia, mire y escuche por si vienen otros, y luego señale y vuelva al tráfico con cuidado.","p":"Correcto. Fíjese si vienen más y vuelva con cuidado."},"zh":{"q":"你为一辆消防车靠边停了车。它已经开过去了。你继续开车之前应该做什么？","o":["紧跟在消防车后面","马上开出去追上车流","看看还有没有别的紧急车辆，然后小心地并回车流","打开双闪灯，在路肩上开"],"h1":"紧急车辆常常是好几辆一起来。","h2":"紧急车辆开过去以后，要看一看、听一听后面还有没有别的车，然后打灯，小心地回到车流中。","p":"对。看看还有没有，然后小心地并回去。"},"vi":{"q":"Bạn đã tấp vào lề cho xe cứu hỏa. Xe đã chạy qua. Bạn nên làm gì trước khi chạy tiếp?","o":["Chạy sát phía sau xe cứu hỏa","Chạy ra ngay để theo kịp dòng xe","Xem còn xe khẩn cấp nào nữa không, rồi cẩn thận nhập lại dòng xe","Bật đèn khẩn cấp và chạy trên lề đường"],"h1":"Xe khẩn cấp thường đi thành nhóm.","h2":"Sau khi xe khẩn cấp chạy qua, hãy nhìn và lắng nghe xem có xe nào khác theo sau không, rồi bật xi-nhan và cẩn thận trở lại dòng xe.","p":"Đúng. Xem còn xe nữa không, rồi cẩn thận nhập lại."},"tl":{"q":"Tumabi ka para sa trak ng bumbero. Nakadaan na ito. Ano ang dapat mong gawin bago ka magpatuloy?","o":["Sumunod nang malapit sa likod ng trak ng bumbero","Lumabas agad para makahabol sa daloy ng trapiko","Tingnan kung may iba pang emergency vehicle, saka maingat na sumanib ulit sa trapiko","Buksan ang hazard lights at magmaneho sa gilid ng daan"],"h1":"Madalas, magkakasama ang mga emergency vehicle.","h2":"Pagkatapos dumaan ng emergency vehicle, tumingin at makinig kung may iba pang susunod, saka mag-signal at maingat na bumalik sa trapiko.","p":"Tama. Tingnan kung may iba pa, saka maingat na sumanib."},"ar":{"q":"توقفت على جانب الطريق لسيارة إطفاء. لقد مرّت. ماذا يجب أن تفعل قبل أن تتابع القيادة؟","o":["سِر قريبًا جدًا خلف سيارة الإطفاء","اخرج فورًا لتلحق بحركة السير","تأكد من عدم وجود مركبات طوارئ أخرى، ثم عُد إلى حركة السير بحذر","شغّل أضواء التحذير وسِر على كتف الطريق"],"h1":"مركبات الطوارئ تسير غالبًا في مجموعات.","h2":"بعد أن تمر مركبة الطوارئ، انظر واستمع لمركبات أخرى قد تتبعها، ثم شغّل الإشارة وعُد إلى حركة السير بحذر.","p":"صحيح. تأكد من عدم وجود غيرها، ثم عُد بحذر."},"ht":{"q":"Ou te rale sou kote pou yon kamyon ponpye. Li fin pase. Kisa ou dwe fè anvan ou kontinye?","o":["Swiv kamyon ponpye a tou pre dèyè l","Sòti touswit pou rattrape sikilasyon an","Gade si gen lòt machin ijans, epi rantre nan sikilasyon an ak prekosyon","Limen limyè danje ou epi kondui sou bòdi wout la"],"h1":"Machin ijans konn vini an gwoup.","h2":"Apre yon machin ijans fin pase, gade epi koute si gen lòt k ap swiv li, epi mete siyal epi retounen nan sikilasyon an ak prekosyon.","p":"Wi, se sa. Gade si gen lòt, epi rantre ak prekosyon."}},{"id":"right-of-way-051","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You are listening to loud music with the windows up. Why is this a problem near emergency vehicles?","o":["Sirens can damage your speakers","Music makes emergency lights hard to see","It is not a problem","You may not hear a siren in time"],"h1":"Your ears warn you before your eyes can.","h2":"Loud music and closed windows can keep you from hearing a siren, so check your mirrors often and keep the volume low enough to hear.","p":"Right. You may not hear the siren."},"es":{"q":"Usted escucha música muy alta con las ventanas cerradas. ¿Por qué es un problema cerca de vehículos de emergencia?","o":["Porque las sirenas pueden dañar sus parlantes","Porque la música hace difícil ver las luces de emergencia","No es un problema","Porque puede no oír una sirena a tiempo"],"h1":"Los oídos le avisan antes que los ojos.","h2":"La música alta y las ventanas cerradas pueden impedirle oír una sirena, así que mire los espejos a menudo y mantenga el volumen lo bastante bajo para oír.","p":"Correcto. Puede no oír la sirena."},"zh":{"q":"你关着车窗，在听很大声的音乐。为什么在紧急车辆附近这是个问题？","o":["警笛会损坏你的音响","音乐会让你很难看到紧急车辆的灯","这不是问题","你可能没法及时听到警笛"],"h1":"耳朵能比眼睛更早提醒你。","h2":"大声的音乐和关着的车窗会让你听不到警笛，所以要常看后视镜，并把音量调低到能听见外面的声音。","p":"对。你可能听不到警笛。"},"vi":{"q":"Bạn đang nghe nhạc lớn và đóng kính xe. Vì sao điều này là vấn đề khi gần xe khẩn cấp?","o":["Còi hú có thể làm hỏng loa của bạn","Nhạc làm bạn khó thấy đèn khẩn cấp","Không có vấn đề gì","Bạn có thể không nghe thấy còi hú kịp lúc"],"h1":"Tai bạn có thể báo cho bạn trước cả mắt.","h2":"Nhạc lớn và kính xe đóng kín có thể làm bạn không nghe thấy còi hú, vì vậy hãy nhìn gương thường xuyên và để âm lượng đủ nhỏ để nghe được.","p":"Đúng. Bạn có thể không nghe thấy còi hú."},"tl":{"q":"Nakikinig ka ng malakas na musika at nakasara ang mga bintana. Bakit ito problema kapag may emergency vehicle sa malapit?","o":["Puwedeng masira ng sirena ang mga speaker mo","Pinahihirap ng musika na makita ang mga ilaw ng emergency","Hindi ito problema","Baka hindi mo marinig ang sirena sa tamang oras"],"h1":"Mas maaga kang binabalaan ng tainga mo kaysa ng mata mo.","h2":"Puwedeng hindi mo marinig ang sirena dahil sa malakas na musika at nakasarang mga bintana, kaya tingnan nang madalas ang mga salamin at hinaan ang volume para makarinig ka.","p":"Tama. Baka hindi mo marinig ang sirena."},"ar":{"q":"تستمع إلى موسيقى عالية والنوافذ مغلقة. لماذا يُعد هذا مشكلة قرب مركبات الطوارئ؟","o":["الصفارات قد تُتلف السماعات","الموسيقى تجعل رؤية أضواء الطوارئ صعبة","ليست مشكلة","قد لا تسمع الصفارة في الوقت المناسب"],"h1":"أذناك تنبهانك قبل أن تستطيع عيناك.","h2":"الموسيقى العالية والنوافذ المغلقة قد تمنعك من سماع الصفارة، لذلك انظر في المرايا كثيرًا واجعل الصوت منخفضًا بما يكفي لتسمع.","p":"صحيح. قد لا تسمع الصفارة."},"ht":{"q":"W ap koute mizik fò ak vit yo fèmen. Poukisa sa se yon pwoblèm toupre machin ijans?","o":["Siren yo ka abime opalè ou yo","Mizik la fè li difisil pou wè limyè ijans yo","Se pa yon pwoblèm","Ou ka pa tande yon siren a tan"],"h1":"Zòrèy ou avèti ou anvan je ou kapab.","h2":"Mizik fò ak vit fèmen ka anpeche ou tande yon siren, kidonk gade nan retwovizè ou yo souvan epi kenbe volim nan ase ba pou ou ka tande.","p":"Wi, se sa. Ou ka pa tande siren an."}},{"id":"right-of-way-052","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"A person is crossing in the middle of the block, not at a crosswalk. What should you do?","o":["Slow down and stop if needed to avoid hitting them","Keep going, because they are crossing in the wrong place","Honk and drive around them fast","Speed up to pass before they reach your lane"],"h1":"Drivers must always try to avoid hitting people.","h2":"Even when a person crosses outside a crosswalk, you must slow down and stop if needed to avoid hitting them.","p":"Right. Always avoid hitting people on foot."},"es":{"q":"Una persona cruza a mitad de cuadra, no en un cruce peatonal. ¿Qué debe hacer?","o":["Bajar la velocidad y pararse si es necesario para no atropellarla","Seguir, porque cruza en un lugar indebido","Tocar la bocina y rodearla rápido","Acelerar para pasar antes de que llegue a su carril"],"h1":"Los conductores siempre deben tratar de no atropellar a nadie.","h2":"Aunque una persona cruce fuera de un cruce peatonal, usted debe bajar la velocidad y pararse si es necesario para no atropellarla.","p":"Correcto. Siempre evite atropellar a los peatones."},"zh":{"q":"有人在街区中间过马路，不在人行横道上。你应该怎么做？","o":["减速，必要时停车，避免撞到他","继续开，因为他在错误的地方过马路","按喇叭，然后快速从他旁边绕过去","加速，在他走到你的车道前开过去"],"h1":"司机必须始终尽量避免撞到人。","h2":"即使有人不在人行横道上过马路，你也必须减速，必要时停车，避免撞到他。","p":"对。一定要避免撞到行人。"},"vi":{"q":"Một người đang băng qua đường ở giữa dãy nhà, không phải ở lối qua đường. Bạn nên làm gì?","o":["Chạy chậm lại và dừng nếu cần để không đụng người đó","Cứ chạy tiếp, vì người đó qua đường sai chỗ","Bấm còi và chạy nhanh vòng qua người đó","Tăng tốc để chạy qua trước khi người đó đến làn của bạn"],"h1":"Người lái xe luôn phải cố gắng không đụng vào người.","h2":"Ngay cả khi một người băng qua đường ngoài lối qua đường, bạn vẫn phải chạy chậm lại và dừng nếu cần để không đụng người đó.","p":"Đúng. Luôn tránh đụng vào người đi bộ."},"tl":{"q":"May taong tumatawid sa gitna ng kalye, hindi sa tawiran. Ano ang dapat mong gawin?","o":["Bumagal at huminto kung kailangan para hindi siya mabangga","Tumuloy lang, dahil mali ang lugar na tinatawiran niya","Bumusina at mabilis na lumampas sa paligid niya","Bumilis para makalampas bago siya umabot sa linya mo"],"h1":"Dapat laging iwasan ng mga drayber na makabangga ng tao.","h2":"Kahit tumatawid ang tao sa labas ng tawiran, dapat kang bumagal at huminto kung kailangan para hindi siya mabangga.","p":"Tama. Laging iwasang makabangga ng taong naglalakad."},"ar":{"q":"شخص يعبر الشارع في منتصف المبنى، وليس عند ممر المشاة. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتوقف إذا لزم الأمر حتى لا تصدمه","استمر في السير، لأنه يعبر من المكان الخطأ","استعمل البوق وتجاوزه بسرعة","زد السرعة لتمر قبل أن يصل إلى مسارك"],"h1":"يجب على السائق دائمًا أن يحاول ألّا يصدم الناس.","h2":"حتى عندما يعبر شخص خارج ممر المشاة، يجب أن تخفف السرعة وتتوقف إذا لزم الأمر حتى لا تصدمه.","p":"صحيح. تجنّب دائمًا صدم المشاة."},"ht":{"q":"Yon moun ap travèse nan mitan blòk la, pa nan yon pasaj pyeton. Kisa ou dwe fè?","o":["Ralanti epi kanpe si sa nesesè pou ou pa frape moun nan","Kontinye, paske moun nan ap travèse nan move kote","Klaksonnen epi pase bò kote l byen vit","Akselere pou pase anvan li rive nan liy ou"],"h1":"Chofè yo dwe toujou eseye pa frape moun.","h2":"Menm lè yon moun ap travèse andeyò pasaj pyeton an, ou dwe ralanti epi kanpe si sa nesesè pou ou pa frape l.","p":"Wi, se sa. Toujou evite frape moun k ap mache."}},{"id":"right-of-way-053","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A ball rolls into the street from between parked cars. What should you do?","o":["Swerve around the ball and keep your speed","Slow down and be ready to stop; a child may run after it","Honk and keep going","Speed up to pass quickly"],"h1":"Think about who might follow the ball.","h2":"A ball rolling into the street is a warning that a child may run out after it, so slow down and be ready to stop.","p":"Right. A child may follow the ball."},"es":{"q":"Una pelota sale rodando a la calle entre carros estacionados. ¿Qué debe hacer?","o":["Esquivar la pelota y mantener la velocidad","Bajar la velocidad y estar listo para pararse; un niño puede salir detrás","Tocar la bocina y seguir","Acelerar para pasar rápido"],"h1":"Piense en quién podría ir detrás de la pelota.","h2":"Una pelota que sale a la calle es una señal de que un niño puede salir corriendo detrás, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Un niño puede seguir la pelota."},"zh":{"q":"一个球从停着的车之间滚到街上。你应该怎么做？","o":["绕过球，保持车速","减速，准备停车；可能有孩子跟着球跑出来","按喇叭，继续开","加速快速开过去"],"h1":"想一想谁可能会跟着球跑出来。","h2":"球滚到街上是一个警告，可能有孩子会跟着跑出来，所以要减速，准备停车。","p":"对。可能有孩子跟着球跑出来。"},"vi":{"q":"Một quả bóng lăn ra đường từ giữa những xe đang đậu. Bạn nên làm gì?","o":["Lách qua quả bóng và giữ nguyên tốc độ","Chạy chậm lại và sẵn sàng dừng; có thể có trẻ em chạy theo","Bấm còi và chạy tiếp","Tăng tốc để chạy qua nhanh"],"h1":"Hãy nghĩ xem ai có thể chạy theo quả bóng.","h2":"Quả bóng lăn ra đường là dấu hiệu cảnh báo có thể có trẻ em chạy theo ra, vì vậy hãy chạy chậm lại và sẵn sàng dừng.","p":"Đúng. Có thể có trẻ em chạy theo quả bóng."},"tl":{"q":"May bolang gumulong papunta sa kalye mula sa pagitan ng mga nakaparadang kotse. Ano ang dapat mong gawin?","o":["Umiwas sa bola at panatilihin ang bilis mo","Bumagal at maging handang huminto; baka may batang humabol dito","Bumusina at tumuloy","Bumilis para mabilis na makalampas"],"h1":"Isipin kung sino ang maaaring sumunod sa bola.","h2":"Ang bolang gumugulong sa kalye ay babala na baka may batang tumakbo para habulin ito, kaya bumagal at maging handang huminto.","p":"Tama. Baka may batang sumunod sa bola."},"ar":{"q":"كرة تتدحرج إلى الشارع من بين السيارات المتوقفة. ماذا يجب أن تفعل؟","o":["انحرف حول الكرة وحافظ على سرعتك","خفّف السرعة وكن مستعدًا للتوقف؛ فقد يركض طفل خلفها","استعمل البوق واستمر","زد السرعة لتمر بسرعة"],"h1":"فكّر فيمن قد يلحق بالكرة.","h2":"الكرة التي تتدحرج إلى الشارع إنذار بأن طفلًا قد يركض خلفها، لذلك خفّف السرعة وكن مستعدًا للتوقف.","p":"صحيح. قد يلحق طفل بالكرة."},"ht":{"q":"Yon boul woule nan lari a soti ant machin ki pake yo. Kisa ou dwe fè?","o":["Vire bò kote boul la epi kenbe menm vitès la","Ralanti epi pare pou kanpe; yon timoun ka kouri dèyè l","Klaksonnen epi kontinye","Akselere pou pase vit"],"h1":"Panse ak kiyès ki ka kouri dèyè boul la.","h2":"Yon boul ki woule nan lari a se yon avètisman ke yon timoun ka kouri soti dèyè l, kidonk ralanti epi pare pou kanpe.","p":"Wi, se sa. Yon timoun ka swiv boul la."}},{"id":"right-of-way-054","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You are stopped at a crosswalk, and a car in the next lane is also stopped there. What should you think?","o":["The other driver is lost","You may pass the stopped car","Someone may be crossing in front of that car, where you cannot see","The light must be broken"],"h1":"A stopped car can hide a person on foot.","h2":"When another car is stopped at a crosswalk, a person may be crossing in front of it, so never pass it; wait until you are sure the crosswalk is clear.","p":"Right. A person may be hidden in front of it."},"es":{"q":"Usted se acerca a un cruce peatonal y un carro en el carril de al lado está parado allí. ¿Qué debe pensar?","o":["Que el otro conductor está perdido","Que puede rebasar al carro parado","Que alguien puede estar cruzando frente a ese carro, donde usted no ve","Que el semáforo debe estar dañado"],"h1":"Un carro parado puede ocultar a un peatón.","h2":"Cuando otro carro está parado en un cruce peatonal, puede haber una persona cruzando frente a él, así que nunca lo rebase; espere hasta estar seguro de que el cruce está libre.","p":"Correcto. Puede haber una persona oculta frente a él."},"zh":{"q":"你停在人行横道前，旁边车道的一辆车也停在那里。你应该想到什么？","o":["那个司机迷路了","你可以超过那辆停着的车","可能有人正在那辆车前面过马路，你看不到","红绿灯一定坏了"],"h1":"停着的车可能挡住行人。","h2":"当另一辆车停在人行横道前时，可能有人正在它前面过马路，所以绝不要超过它；要等到你确定人行横道上没有人。","p":"对。它前面可能有你看不到的行人。"},"vi":{"q":"Bạn đang dừng tại lối qua đường, và một xe ở làn bên cạnh cũng đang dừng ở đó. Bạn nên nghĩ gì?","o":["Người lái kia bị lạc đường","Bạn có thể vượt qua xe đang dừng","Có thể có người đang băng qua phía trước xe đó, chỗ bạn không thấy","Đèn giao thông chắc bị hư"],"h1":"Một xe đang dừng có thể che khuất người đi bộ.","h2":"Khi một xe khác đang dừng tại lối qua đường, có thể có người đang băng qua phía trước xe đó, vì vậy đừng bao giờ vượt qua nó; hãy chờ đến khi bạn chắc chắn lối qua đường không còn ai.","p":"Đúng. Có thể có người bị che khuất phía trước xe đó."},"tl":{"q":"Nakahinto ka sa tawiran, at nakahinto rin doon ang isang kotse sa katabing linya. Ano ang dapat mong isipin?","o":["Naligaw ang ibang drayber","Puwede mong lampasan ang nakahintong kotse","Baka may taong tumatawid sa harap ng kotseng iyon, kung saan hindi mo makita","Siguradong sira ang ilaw-trapiko"],"h1":"Puwedeng matakpan ng nakahintong kotse ang taong naglalakad.","h2":"Kapag may ibang kotseng nakahinto sa tawiran, baka may taong tumatawid sa harap nito, kaya huwag na huwag itong lalampasan; maghintay hanggang sigurado kang walang tao sa tawiran.","p":"Tama. Baka may taong natatakpan sa harap nito."},"ar":{"q":"أنت متوقف عند ممر المشاة، وسيارة في المسار المجاور متوقفة هناك أيضًا. بماذا يجب أن تفكر؟","o":["السائق الآخر ضائع","يمكنك أن تتجاوز السيارة المتوقفة","قد يكون شخص يعبر أمام تلك السيارة، حيث لا تستطيع أن تراه","الإشارة الضوئية معطلة بالتأكيد"],"h1":"السيارة المتوقفة قد تخفي شخصًا يمشي.","h2":"عندما تكون سيارة أخرى متوقفة عند ممر المشاة، قد يكون شخص يعبر أمامها، لذلك يجب ألّا تتجاوزها أبدًا؛ انتظر حتى تتأكد أن ممر المشاة خالٍ.","p":"صحيح. قد يكون شخص مختبئًا أمامها."},"ht":{"q":"Ou kanpe nan yon pasaj pyeton, epi yon machin nan liy akote a kanpe la tou. Kisa ou dwe panse?","o":["Lòt chofè a pèdi wout li","Ou ka pase machin ki kanpe a","Yon moun ka ap travèse devan machin sa a, kote ou pa ka wè","Limyè a dwe an pàn"],"h1":"Yon machin ki kanpe ka kache yon moun k ap mache.","h2":"Lè yon lòt machin kanpe nan yon pasaj pyeton, yon moun ka ap travèse devan l, kidonk pa janm pase l; tann jiskaske ou sèten pa gen moun nan pasaj pyeton an.","p":"Wi, se sa. Yon moun ka kache devan l."}},{"id":"right-of-way-055","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"Why should you take extra care near people walking at night?","o":["People walk faster at night","Crosswalks are closed at night","Streetlights make people easy to see","People in dark clothes are very hard to see"],"h1":"Think about what your headlights show.","h2":"At night, people on foot, especially in dark clothing, are very hard to see, so slow down and watch carefully near crosswalks and roadsides.","p":"Right. People are hard to see at night."},"es":{"q":"¿Por qué debe tener más cuidado con los peatones de noche?","o":["Porque la gente camina más rápido de noche","Porque los cruces se cierran de noche","Porque las luces de la calle hacen fácil verlos","Porque las personas con ropa oscura son muy difíciles de ver"],"h1":"Piense en lo que muestran sus faros.","h2":"De noche, los peatones, sobre todo con ropa oscura, son muy difíciles de ver, así que baje la velocidad y mire con cuidado cerca de cruces y orillas.","p":"Correcto. De noche es difícil ver a la gente."},"zh":{"q":"为什么晚上在行人附近要特别小心？","o":["人们晚上走得更快","人行横道晚上关闭","路灯让人很容易被看到","穿深色衣服的人很难被看到"],"h1":"想一想你的车灯能照到什么。","h2":"晚上，行人很难被看到，尤其是穿深色衣服的人，所以在人行横道和路边附近要减速，仔细观察。","p":"对。晚上很难看到行人。"},"vi":{"q":"Tại sao bạn cần cẩn thận hơn gần người đi bộ vào ban đêm?","o":["Ban đêm người ta đi nhanh hơn","Lối qua đường bị đóng vào ban đêm","Đèn đường làm người ta dễ thấy","Người mặc quần áo tối màu rất khó thấy"],"h1":"Hãy nghĩ xem đèn pha của bạn chiếu thấy những gì.","h2":"Vào ban đêm, người đi bộ rất khó thấy, nhất là khi mặc quần áo tối màu, vì vậy hãy chạy chậm lại và quan sát kỹ gần lối qua đường và lề đường.","p":"Đúng. Ban đêm rất khó thấy người đi bộ."},"tl":{"q":"Bakit dapat kang mas mag-ingat malapit sa mga taong naglalakad sa gabi?","o":["Mas mabilis maglakad ang mga tao sa gabi","Sarado ang mga tawiran sa gabi","Dahil sa ilaw sa kalye, madaling makita ang mga tao","Napakahirap makita ang mga taong nakasuot ng madilim na damit"],"h1":"Isipin kung ano ang naiilawan ng headlights mo.","h2":"Sa gabi, napakahirap makita ang mga taong naglalakad, lalo na kung madilim ang suot nila, kaya bumagal at magmasid nang mabuti malapit sa mga tawiran at gilid ng kalsada.","p":"Tama. Mahirap makita ang mga tao sa gabi."},"ar":{"q":"لماذا يجب أن تنتبه أكثر قرب المشاة في الليل؟","o":["الناس يمشون أسرع في الليل","ممرات المشاة مغلقة في الليل","أضواء الشوارع تجعل رؤية الناس سهلة","الأشخاص الذين يلبسون ملابس داكنة يصعب جدًا رؤيتهم"],"h1":"فكّر فيما تُظهره أضواء سيارتك الأمامية.","h2":"في الليل يصعب جدًا رؤية المشاة، خاصة من يلبسون ملابس داكنة، لذلك خفّف السرعة وراقب بانتباه قرب ممرات المشاة وجوانب الطريق.","p":"صحيح. يصعب رؤية الناس في الليل."},"ht":{"q":"Poukisa ou dwe fè plis atansyon toupre moun k ap mache lannuit?","o":["Moun mache pi vit lannuit","Pasaj pyeton yo fèmen lannuit","Limyè lari yo fè moun fasil pou wè","Moun ki mete rad fonse trè difisil pou wè"],"h1":"Panse ak sa limyè machin ou yo montre.","h2":"Lannuit, moun k ap mache trè difisil pou wè, sitou si yo mete rad fonse, kidonk ralanti epi gade byen toupre pasaj pyeton yo ak bò wout yo.","p":"Wi, se sa. Moun difisil pou wè lannuit."}},{"id":"right-of-way-056","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"You are backing out of a parking space in a busy lot. What is most important?","o":["Back up slowly and keep looking behind you for people and cars","Back up quickly to get out of the way","Use only your mirrors","Honk and back out without looking"],"h1":"Small children are hard to see behind a car.","h2":"When backing out, go slowly and keep looking behind you, because people, especially children, can walk behind your car without warning.","p":"Right. Back up slowly and keep looking."},"es":{"q":"Usted sale en reversa de un espacio en un estacionamiento lleno. ¿Qué es lo más importante?","o":["Retroceder despacio y seguir mirando hacia atrás por personas y carros","Retroceder rápido para no estorbar","Usar solo los espejos","Tocar la bocina y salir sin mirar"],"h1":"Los niños pequeños son difíciles de ver detrás de un carro.","h2":"Al salir en reversa, vaya despacio y siga mirando hacia atrás, porque las personas, sobre todo los niños, pueden pasar detrás de su carro sin aviso.","p":"Correcto. Retroceda despacio y siga mirando."},"zh":{"q":"你在一个很繁忙的停车场倒车出车位。什么最重要？","o":["慢慢倒车，一直往后看有没有人和车","快速倒车，赶紧让开","只看后视镜","按喇叭，不看就倒出去"],"h1":"车后的小孩很难被看到。","h2":"倒车出来时，要慢慢倒，一直往后看，因为人，尤其是孩子，可能会毫无预警地走到你的车后面。","p":"对。慢慢倒车，一直看着后面。"},"vi":{"q":"Bạn đang lùi xe ra khỏi chỗ đậu trong một bãi đậu xe đông đúc. Điều gì quan trọng nhất?","o":["Lùi chậm và luôn nhìn ra phía sau để thấy người và xe","Lùi nhanh để tránh đường","Chỉ dùng gương","Bấm còi và lùi ra mà không nhìn"],"h1":"Trẻ nhỏ rất khó thấy ở phía sau xe.","h2":"Khi lùi xe ra, hãy lùi chậm và luôn nhìn ra phía sau, vì người đi bộ, nhất là trẻ em, có thể đi ra sau xe bạn mà không báo trước.","p":"Đúng. Lùi chậm và luôn nhìn phía sau."},"tl":{"q":"Paatras kang lumalabas sa paradahan sa isang mataong parking lot. Ano ang pinakamahalaga?","o":["Umatras nang dahan-dahan at patuloy na tumingin sa likod para sa mga tao at kotse","Umatras nang mabilis para makaalis agad","Gamitin lang ang mga salamin","Bumusina at umatras nang hindi tumitingin"],"h1":"Mahirap makita ang maliliit na bata sa likod ng kotse.","h2":"Kapag umaatras palabas, dahan-dahan lang at patuloy na tumingin sa likod, dahil puwedeng dumaan ang mga tao, lalo na ang mga bata, sa likod ng kotse mo nang walang babala.","p":"Tama. Umatras nang dahan-dahan at patuloy na tumingin."},"ar":{"q":"أنت تخرج بالسيارة إلى الخلف من موقف في ساحة مواقف مزدحمة. ما الأهم؟","o":["ارجع ببطء واستمر في النظر خلفك لترى الناس والسيارات","ارجع بسرعة لتبتعد عن الطريق","استعمل المرايا فقط","استعمل البوق وارجع دون أن تنظر"],"h1":"يصعب رؤية الأطفال الصغار خلف السيارة.","h2":"عند الرجوع إلى الخلف، ارجع ببطء واستمر في النظر خلفك، لأن الناس، خاصة الأطفال، قد يمشون خلف سيارتك دون إنذار.","p":"صحيح. ارجع ببطء واستمر في النظر."},"ht":{"q":"W ap fè bak pou soti nan yon plas nan yon pakin ki gen anpil moun. Kisa ki pi enpòtan?","o":["Fè bak dousman epi kontinye gade dèyè ou pou moun ak machin","Fè bak vit pou ou soti nan wout la","Sèvi ak glas ou yo sèlman","Klaksonnen epi fè bak san ou pa gade"],"h1":"Timoun piti difisil pou wè dèyè yon machin.","h2":"Lè w ap fè bak pou soti, ale dousman epi kontinye gade dèyè ou, paske moun, sitou timoun, ka pase dèyè machin ou san avètisman.","p":"Wi, se sa. Fè bak dousman epi kontinye gade."}},{"id":"right-of-way-057","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A bicycle rider is ahead of you in your lane on a narrow road. What should you do?","o":["Honk so the rider moves off the road","Slow down and pass only when you can give plenty of room safely","Pass closely at your normal speed","Follow very close behind"],"h1":"A bicycle is a vehicle on the road.","h2":"Treat a bicycle as a slow vehicle: slow down, wait for a safe chance, and pass with plenty of space.","p":"Right. Wait and pass with plenty of room."},"es":{"q":"Hay un ciclista delante de usted en su carril en una vía angosta. ¿Qué debe hacer?","o":["Tocar la bocina para que se salga de la vía","Bajar la velocidad y rebasar solo cuando pueda dejar mucho espacio con seguridad","Rebasarlo de cerca a su velocidad normal","Seguirlo muy de cerca"],"h1":"Una bicicleta es un vehículo en la vía.","h2":"Trate a la bicicleta como un vehículo lento: baje la velocidad, espere una oportunidad segura y rebase dejando mucho espacio.","p":"Correcto. Espere y rebase con mucho espacio."},"zh":{"q":"在一条窄路上，一个骑自行车的人在你车道的前方。你应该怎么做？","o":["按喇叭，让骑车的人离开路面","减速，只有在能安全地留出足够空间时才超车","以正常速度贴近超过去","紧紧跟在后面"],"h1":"自行车是路上的车辆。","h2":"把自行车当作慢速车辆：减速，等待安全的机会，然后留出足够的空间超车。","p":"对。等一等，留出足够的空间再超车。"},"vi":{"q":"Một người đi xe đạp ở phía trước bạn trong làn của bạn trên một con đường hẹp. Bạn nên làm gì?","o":["Bấm còi để người đó ra khỏi đường","Chạy chậm lại và chỉ vượt khi có thể chừa đủ khoảng cách một cách an toàn","Vượt sát qua với tốc độ bình thường","Chạy theo rất sát phía sau"],"h1":"Xe đạp là một phương tiện trên đường.","h2":"Hãy coi xe đạp là một xe chạy chậm: chạy chậm lại, chờ lúc an toàn, và vượt qua với nhiều khoảng trống.","p":"Đúng. Chờ và vượt với nhiều khoảng trống."},"tl":{"q":"May nagbibisikleta sa unahan mo sa linya mo sa makitid na kalsada. Ano ang dapat mong gawin?","o":["Bumusina para umalis sa kalsada ang nagbibisikleta","Bumagal at lumampas lang kapag kaya mong magbigay ng sapat na espasyo nang ligtas","Lumampas nang malapit sa normal mong bilis","Sumunod nang napakalapit sa likod"],"h1":"Ang bisikleta ay sasakyan sa kalsada.","h2":"Ituring ang bisikleta na mabagal na sasakyan: bumagal, maghintay ng ligtas na pagkakataon, at lumampas nang may maluwag na espasyo.","p":"Tama. Maghintay at lumampas nang may maluwag na espasyo."},"ar":{"q":"راكب دراجة هوائية أمامك في مسارك على طريق ضيق. ماذا يجب أن تفعل؟","o":["استعمل البوق ليخرج الراكب من الطريق","خفّف السرعة ولا تتجاوز إلا عندما تستطيع أن تترك مسافة كافية بأمان","تجاوزه من قريب بسرعتك العادية","سِر خلفه من قريب جدًا"],"h1":"الدراجة الهوائية مركبة على الطريق.","h2":"تعامل مع الدراجة الهوائية كمركبة بطيئة: خفّف السرعة، وانتظر فرصة آمنة، وتجاوزها مع ترك مسافة كبيرة.","p":"صحيح. انتظر وتجاوز مع ترك مسافة كبيرة."},"ht":{"q":"Yon moun sou bisiklèt devan ou nan liy ou sou yon wout ki etwat. Kisa ou dwe fè?","o":["Klaksonnen pou moun nan soti sou wout la","Ralanti epi pase sèlman lè ou ka kite ase espas san danje","Pase toupre l ak vitès nòmal ou","Swiv li trè pre dèyè"],"h1":"Yon bisiklèt se yon veyikil sou wout la.","h2":"Trete yon bisiklèt tankou yon veyikil ki ralanti: ralanti, tann yon bon moman san danje, epi pase ak anpil espas.","p":"Wi, se sa. Tann epi pase ak anpil espas."}},{"id":"right-of-way-058","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"A bicycle rider ahead holds the left arm out with the hand pointing up. What does this mean?","o":["The rider is going to turn left","The rider wants you to pass","The rider is going to turn right","The rider is stopping to rest"],"h1":"Some riders use the left arm to signal a right turn.","h2":"A left arm bent up at the elbow is the hand signal for a right turn, used by drivers and bicycle riders.","p":"Right. It means a right turn."},"es":{"q":"Un ciclista adelante extiende el brazo izquierdo con la mano hacia arriba. ¿Qué significa?","o":["Que va a girar a la izquierda","Que quiere que usted lo rebase","Que va a girar a la derecha","Que se va a parar a descansar"],"h1":"Algunos ciclistas usan el brazo izquierdo para señalar un giro a la derecha.","h2":"El brazo izquierdo doblado hacia arriba es la señal de mano para girar a la derecha, que usan conductores y ciclistas.","p":"Correcto. Significa giro a la derecha."},"zh":{"q":"前面骑自行车的人伸出左臂，手指向上。这是什么意思？","o":["骑车的人要左转","骑车的人想让你超车","骑车的人要右转","骑车的人要停下来休息"],"h1":"有些骑车的人用左臂来表示右转。","h2":"左臂在肘部向上弯曲是右转的手势，司机和骑自行车的人都会用。","p":"对。意思是右转。"},"vi":{"q":"Người đi xe đạp phía trước đưa tay trái ra với bàn tay chỉ lên trên. Điều này có nghĩa là gì?","o":["Người đó sắp rẽ trái","Người đó muốn bạn vượt qua","Người đó sắp rẽ phải","Người đó dừng lại để nghỉ"],"h1":"Một số người đi xe đạp dùng tay trái để báo rẽ phải.","h2":"Tay trái gập lên ở khuỷu tay là tín hiệu tay báo rẽ phải, được người lái xe và người đi xe đạp sử dụng.","p":"Đúng. Nghĩa là rẽ phải."},"tl":{"q":"Ang nagbibisikleta sa unahan ay iniunat ang kaliwang braso na nakaturo pataas ang kamay. Ano ang ibig sabihin nito?","o":["Liliko pakaliwa ang nagbibisikleta","Gusto ng nagbibisikleta na lumampas ka","Liliko pakanan ang nagbibisikleta","Hihinto ang nagbibisikleta para magpahinga"],"h1":"May mga nagbibisikleta na ginagamit ang kaliwang braso para ipakitang liliko sila pakanan.","h2":"Ang kaliwang braso na nakabaluktot pataas sa siko ay senyas ng kamay para sa pagliko pakanan, na ginagamit ng mga drayber at nagbibisikleta.","p":"Tama. Ibig sabihin nito ay liliko pakanan."},"ar":{"q":"راكب دراجة هوائية أمامك يمد ذراعه اليسرى ويده متجهة إلى الأعلى. ماذا يعني هذا؟","o":["الراكب سيستدير إلى اليسار","الراكب يريدك أن تتجاوزه","الراكب سيستدير إلى اليمين","الراكب سيتوقف ليرتاح"],"h1":"بعض الراكبين يستعملون الذراع اليسرى للإشارة إلى الاستدارة يمينًا.","h2":"الذراع اليسرى المثنية إلى الأعلى عند المرفق هي إشارة اليد للاستدارة يمينًا، ويستعملها السائقون وراكبو الدراجات الهوائية.","p":"صحيح. معناها الاستدارة يمينًا."},"ht":{"q":"Yon moun sou bisiklèt devan ou lonje bra gòch li ak men l ki pwente anlè. Kisa sa vle di?","o":["Moun nan pral vire agòch","Moun nan vle ou pase l","Moun nan pral vire adwat","Moun nan ap kanpe pou l poze"],"h1":"Gen moun sou bisiklèt ki sèvi ak bra gòch yo pou siyale yon viraj adwat.","h2":"Yon bra gòch ki pliye anlè nan koud la se siyal men pou vire adwat, chofè ak moun sou bisiklèt sèvi ak li.","p":"Wi, se sa. Sa vle di vire adwat."}},{"id":"right-of-way-059","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"Why might a motorcycle rider move from one side of the lane to the other?","o":["To block you from passing","Because the lane is too small","Because riders should ride on the line","To be seen better and to avoid holes or debris"],"h1":"Riders adjust to stay safe.","h2":"Motorcycle riders change position in the lane to be seen by others and to avoid hazards like potholes, oil or debris.","p":"Right. To be seen and avoid hazards."},"es":{"q":"¿Por qué un motociclista puede moverse de un lado a otro del carril?","o":["Para no dejar que usted lo rebase","Porque el carril es muy pequeño","Porque los motociclistas deben ir sobre la línea","Para que lo vean mejor y para evitar baches o basura"],"h1":"Los motociclistas se acomodan para ir seguros.","h2":"Los motociclistas cambian de posición en el carril para que los demás los vean y para evitar peligros como baches, aceite o basura.","p":"Correcto. Para ser vistos y evitar peligros."},"zh":{"q":"骑摩托车的人为什么可能从车道的一边移到另一边？","o":["为了不让你超车","因为车道太小","因为骑车的人应该骑在线上","为了让别人更容易看到，并避开坑洞或杂物"],"h1":"骑车的人会调整位置来保证安全。","h2":"骑摩托车的人会在车道里改变位置，让别人看到自己，并避开坑洞、油渍或杂物等危险。","p":"对。为了被看到，并避开危险。"},"vi":{"q":"Tại sao người đi xe máy có thể chuyển từ bên này sang bên kia của làn đường?","o":["Để chặn không cho bạn vượt","Vì làn đường quá nhỏ","Vì người đi xe máy nên chạy trên vạch kẻ","Để người khác dễ thấy hơn và để tránh ổ gà hoặc vật cản"],"h1":"Người đi xe máy điều chỉnh vị trí để giữ an toàn.","h2":"Người đi xe máy thay đổi vị trí trong làn để người khác thấy mình và để tránh các nguy hiểm như ổ gà, dầu nhớt hoặc vật cản.","p":"Đúng. Để được thấy và tránh nguy hiểm."},"tl":{"q":"Bakit maaaring lumipat ang nagmomotorsiklo mula sa isang gilid ng linya papunta sa kabila?","o":["Para harangan ka sa paglampas","Dahil masyadong maliit ang linya","Dahil dapat sa guhit tumakbo ang mga nagmomotorsiklo","Para mas makita siya at para iwasan ang mga butas o kalat"],"h1":"Inaayos ng mga nagmomotorsiklo ang puwesto nila para manatiling ligtas.","h2":"Binabago ng mga nagmomotorsiklo ang puwesto nila sa linya para makita sila ng iba at para iwasan ang mga panganib tulad ng lubak, langis o kalat.","p":"Tama. Para makita at maiwasan ang panganib."},"ar":{"q":"لماذا قد ينتقل راكب الدراجة النارية من جانب المسار إلى الجانب الآخر؟","o":["ليمنعك من التجاوز","لأن المسار صغير جدًا","لأن الراكبين يجب أن يسيروا على الخط","ليراه الآخرون بشكل أفضل وليتجنب الحفر أو الأشياء الملقاة على الطريق"],"h1":"الراكبون يغيّرون مكانهم ليبقوا آمنين.","h2":"راكبو الدراجات النارية يغيّرون مكانهم في المسار ليراهم الآخرون وليتجنبوا الأخطار مثل الحفر أو الزيت أو الأشياء الملقاة على الطريق.","p":"صحيح. ليراه الآخرون وليتجنب الأخطار."},"ht":{"q":"Poukisa yon moun sou motosiklèt ka deplase soti sou yon bò liy lan pou ale sou lòt bò a?","o":["Pou anpeche ou pase","Paske liy lan twò piti","Paske moun sou motosiklèt dwe woule sou liy lan","Pou moun wè l pi byen epi pou evite twou oswa fatra"],"h1":"Moun sou motosiklèt chanje pozisyon pou yo rete an sekirite.","h2":"Moun sou motosiklèt chanje pozisyon nan liy lan pou lòt moun wè yo epi pou evite danje tankou twou, lwil oswa fatra.","p":"Wi, se sa. Pou moun wè l epi pou evite danje."}},{"id":"right-of-way-060","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"Why should you leave more space when following a motorcycle?","o":["A motorcycle can stop very quickly","Motorcycles are slower than cars","Motorcycles always swerve","You need room to pass in the same lane"],"h1":"Motorcycles are light and brake fast.","h2":"A motorcycle can stop much faster than a car, so leave extra following distance to avoid hitting it.","p":"Right. A motorcycle can stop very fast."},"es":{"q":"¿Por qué debe dejar más espacio cuando sigue a una motocicleta?","o":["Porque una motocicleta puede pararse muy rápido","Porque las motocicletas son más lentas que los carros","Porque las motocicletas siempre zigzaguean","Porque necesita espacio para rebasar en el mismo carril"],"h1":"Las motocicletas son livianas y frenan rápido.","h2":"Una motocicleta puede pararse mucho más rápido que un carro, así que deje más distancia para no chocarla.","p":"Correcto. Una motocicleta puede pararse muy rápido."},"zh":{"q":"跟在摩托车后面时，为什么要留更多距离？","o":["摩托车可以很快停下来","摩托车比汽车慢","摩托车总是突然转向","你需要空间在同一车道里超车"],"h1":"摩托车很轻，刹车很快。","h2":"摩托车停车比汽车快得多，所以要多留跟车距离，避免撞上它。","p":"对。摩托车可以很快停下来。"},"vi":{"q":"Tại sao bạn nên chừa nhiều khoảng cách hơn khi chạy sau một xe máy?","o":["Xe máy có thể dừng rất nhanh","Xe máy chạy chậm hơn xe hơi","Xe máy luôn lạng lách","Bạn cần chỗ để vượt trong cùng một làn"],"h1":"Xe máy nhẹ và thắng rất nhanh.","h2":"Xe máy có thể dừng nhanh hơn xe hơi rất nhiều, vì vậy hãy chừa thêm khoảng cách khi chạy sau để không đụng vào nó.","p":"Đúng. Xe máy có thể dừng rất nhanh."},"tl":{"q":"Bakit dapat kang mag-iwan ng mas malaking espasyo kapag sumusunod sa motorsiklo?","o":["Napakabilis makahinto ng motorsiklo","Mas mabagal ang mga motorsiklo kaysa sa mga kotse","Laging pumapaling ang mga motorsiklo","Kailangan mo ng espasyo para lumampas sa parehong linya"],"h1":"Magaan ang mga motorsiklo at mabilis magpreno.","h2":"Mas mabilis huminto ang motorsiklo kaysa sa kotse, kaya mag-iwan ng dagdag na layo sa pagsunod para hindi mo ito mabangga.","p":"Tama. Napakabilis huminto ng motorsiklo."},"ar":{"q":"لماذا يجب أن تترك مسافة أكبر عندما تسير خلف دراجة نارية؟","o":["الدراجة النارية تستطيع أن تتوقف بسرعة كبيرة","الدراجات النارية أبطأ من السيارات","الدراجات النارية تنحرف دائمًا","تحتاج إلى مكان لتتجاوز في المسار نفسه"],"h1":"الدراجات النارية خفيفة وتكبح بسرعة.","h2":"الدراجة النارية تستطيع أن تتوقف أسرع بكثير من السيارة، لذلك اترك مسافة إضافية خلفها حتى لا تصدمها.","p":"صحيح. الدراجة النارية تستطيع أن تتوقف بسرعة كبيرة."},"ht":{"q":"Poukisa ou dwe kite plis espas lè w ap swiv yon motosiklèt?","o":["Yon motosiklèt ka kanpe trè vit","Motosiklèt pi lan pase machin","Motosiklèt toujou fè zigzag","Ou bezwen espas pou pase nan menm liy lan"],"h1":"Motosiklèt yo lejè epi yo frennen vit.","h2":"Yon motosiklèt ka kanpe pi vit anpil pase yon machin, kidonk kite plis distans dèyè l pou ou pa frape l.","p":"Wi, se sa. Yon motosiklèt ka kanpe trè vit."}},{"id":"right-of-way-061","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A motorcycle coming toward you has its turn signal on. You want to pull out. What should you do?","o":["Pull out right away","Wait until you are sure it is really turning","Flash your lights so it stops","Honk and go"],"h1":"Motorcycle signals do not always turn off by themselves.","h2":"Some motorcycle turn signals do not cancel on their own, so wait until you are sure the motorcycle is actually turning before you pull out.","p":"Right. Be sure it is turning first."},"es":{"q":"Una motocicleta que viene de frente tiene la direccional puesta. Usted quiere salir. ¿Qué debe hacer?","o":["Salir enseguida","Esperar hasta estar seguro de que realmente va a girar","Hacerle cambio de luces para que se pare","Tocar la bocina y salir"],"h1":"Las direccionales de las motocicletas no siempre se apagan solas.","h2":"Algunas direccionales de motocicleta no se apagan solas, así que espere hasta estar seguro de que la motocicleta realmente gira antes de salir.","p":"Correcto. Asegúrese primero de que gira."},"zh":{"q":"一辆迎面开来的摩托车开着转向灯。你想开出去。你应该怎么做？","o":["马上开出去","等到你确定它真的在转弯","闪车灯让它停下","按喇叭然后开走"],"h1":"摩托车的转向灯不一定会自己关掉。","h2":"有些摩托车的转向灯不会自己关掉，所以要等到你确定摩托车真的在转弯，再开出去。","p":"对。先确定它真的在转弯。"},"vi":{"q":"Một xe máy đang chạy về phía bạn có bật đèn xi nhan. Bạn muốn chạy ra đường. Bạn nên làm gì?","o":["Chạy ra ngay","Chờ đến khi bạn chắc chắn nó thật sự đang rẽ","Nháy đèn để nó dừng lại","Bấm còi rồi chạy"],"h1":"Đèn xi nhan xe máy không phải lúc nào cũng tự tắt.","h2":"Đèn xi nhan của một số xe máy không tự tắt, vì vậy hãy chờ đến khi bạn chắc chắn xe máy thật sự đang rẽ rồi mới chạy ra.","p":"Đúng. Hãy chắc chắn nó đang rẽ trước đã."},"tl":{"q":"Nakabukas ang turn signal ng motorsiklong papalapit sa iyo. Gusto mong lumabas sa kalsada. Ano ang dapat mong gawin?","o":["Lumabas agad","Maghintay hanggang sigurado kang talagang liliko ito","I-flash ang ilaw mo para huminto ito","Bumusina at umandar"],"h1":"Hindi laging kusang namamatay ang signal ng motorsiklo.","h2":"Ang turn signal ng ilang motorsiklo ay hindi kusang namamatay, kaya maghintay hanggang sigurado kang talagang lumiliko ang motorsiklo bago ka lumabas.","p":"Tama. Siguraduhin munang lumiliko ito."},"ar":{"q":"دراجة نارية قادمة نحوك وإشارة الانعطاف فيها مضاءة. تريد أن تخرج إلى الطريق. ماذا يجب أن تفعل؟","o":["اخرج فورًا","انتظر حتى تتأكد أنها تنعطف فعلًا","أومض بأضوائك لتتوقف","استعمل البوق وانطلق"],"h1":"إشارات الدراجات النارية لا تنطفئ دائمًا من تلقاء نفسها.","h2":"بعض إشارات الانعطاف في الدراجات النارية لا تنطفئ من تلقاء نفسها، لذلك انتظر حتى تتأكد أن الدراجة النارية تنعطف فعلًا قبل أن تخرج.","p":"صحيح. تأكد أولًا أنها تنعطف."},"ht":{"q":"Yon motosiklèt k ap vin sou ou gen siyal viraj li limen. Ou vle soti nan wout la. Kisa ou dwe fè?","o":["Soti touswit","Tann jiskaske ou sèten li vrèman ap vire","Fè limyè ou yo klignote pou l kanpe","Klaksonnen epi ale"],"h1":"Siyal motosiklèt pa toujou etenn pou kont yo.","h2":"Gen siyal viraj motosiklèt ki pa etenn pou kont yo, kidonk tann jiskaske ou sèten motosiklèt la vrèman ap vire anvan ou soti.","p":"Wi, se sa. Asire w li ap vire anvan."}},{"id":"right-of-way-062","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"Where are a large truck's \"No-Zones\", where the driver may not see you?","o":["Only far behind the truck","Only in front of the cab","Beside the truck, close behind it, and close in front of it","There are none if the truck has mirrors"],"h1":"Trucks have large blind spots on all sides.","h2":"A large truck has No-Zones beside it, right behind it and right in front of it, where the driver cannot see your car.","p":"Right. Beside, behind and in front."},"es":{"q":"¿Dónde están las \"zonas ciegas\" (No-Zones) de un camión grande, donde el conductor puede no verlo?","o":["Solo lejos detrás del camión","Solo delante de la cabina","A los lados, muy cerca detrás y muy cerca delante","No hay si el camión tiene espejos"],"h1":"Los camiones tienen grandes puntos ciegos en todos los lados.","h2":"Un camión grande tiene zonas ciegas a sus lados, justo detrás y justo delante, donde el conductor no puede ver su carro.","p":"Correcto. A los lados, detrás y delante."},"zh":{"q":"大卡车的“No-Zones”（盲区）在哪里？在那里司机可能看不到你。","o":["只在卡车后面很远的地方","只在驾驶室前面","卡车旁边、紧挨着卡车后面和紧挨着卡车前面","如果卡车有后视镜就没有盲区"],"h1":"卡车四周都有很大的盲区。","h2":"大卡车的“No-Zones”（盲区）在它的旁边、正后方和正前方，在那里司机看不到你的车。","p":"对。旁边、后面和前面。"},"vi":{"q":"\"No-Zones\" (điểm mù) của xe tải lớn, nơi tài xế có thể không thấy bạn, ở đâu?","o":["Chỉ ở xa phía sau xe tải","Chỉ ở phía trước cabin","Bên cạnh xe tải, sát phía sau và sát phía trước xe","Không có nếu xe tải có gương"],"h1":"Xe tải có điểm mù lớn ở mọi phía.","h2":"Xe tải lớn có \"No-Zones\" (điểm mù) ở bên cạnh, ngay phía sau và ngay phía trước, nơi tài xế không thể thấy xe của bạn.","p":"Đúng. Bên cạnh, phía sau và phía trước."},"tl":{"q":"Nasaan ang \"No-Zones\" (mga blind spot) ng malaking trak, kung saan maaaring hindi ka makita ng drayber?","o":["Sa malayong likod lang ng trak","Sa harap lang ng kabina","Sa tabi ng trak, malapit sa likod nito, at malapit sa harap nito","Wala kung may mga salamin ang trak"],"h1":"May malalaking blind spot ang mga trak sa lahat ng panig.","h2":"Ang malaking trak ay may \"No-Zones\" (mga blind spot) sa tabi nito, sa mismong likod nito at sa mismong harap nito, kung saan hindi makita ng drayber ang kotse mo.","p":"Tama. Sa tabi, sa likod at sa harap."},"ar":{"q":"أين \"No-Zones\" (المناطق العمياء) للشاحنة الكبيرة، حيث قد لا يراك السائق؟","o":["بعيدًا خلف الشاحنة فقط","أمام مقصورة السائق فقط","بجانب الشاحنة، وقريبًا خلفها، وقريبًا أمامها","لا توجد إذا كانت في الشاحنة مرايا"],"h1":"للشاحنات مناطق عمياء كبيرة من كل الجهات.","h2":"للشاحنة الكبيرة \"No-Zones\" (مناطق عمياء) بجانبها، وخلفها مباشرة، وأمامها مباشرة، حيث لا يستطيع السائق أن يرى سيارتك.","p":"صحيح. بجانبها وخلفها وأمامها."},"ht":{"q":"Ki kote \"No-Zones\" (zòn avèg) yon gwo kamyon ye, kote chofè a ka pa wè ou?","o":["Sèlman byen lwen dèyè kamyon an","Sèlman devan kabin nan","Bò kote kamyon an, toupre dèyè l, ak toupre devan l","Pa genyen si kamyon an gen glas"],"h1":"Kamyon yo gen gwo zòn avèg sou tout bò.","h2":"Yon gwo kamyon gen \"No-Zones\" (zòn avèg) bò kote l, jis dèyè l ak jis devan l, kote chofè a pa ka wè machin ou.","p":"Wi, se sa. Bò kote l, dèyè l ak devan l."}},{"id":"right-of-way-063","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You want to pass a large truck on the highway. How should you do it?","o":["Stay beside it to see if it changes lanes","Pass on the right side","Pass slowly, close to the truck","Pass steadily without staying beside it, and signal clearly"],"h1":"The side of a truck is a blind spot.","h2":"Pass a large truck on the left, signal clearly, and move past steadily so you do not stay in its blind spot beside it.","p":"Right. Pass steadily; do not stay beside it."},"es":{"q":"Usted quiere rebasar a un camión grande en la carretera. ¿Cómo debe hacerlo?","o":["Quedarse a su lado para ver si cambia de carril","Rebasar por la derecha","Rebasar despacio, cerca del camión","Rebasar de forma constante sin quedarse a su lado, y señalar claramente"],"h1":"El costado de un camión es un punto ciego.","h2":"Rebase a un camión grande por la izquierda, señale claramente y pase de forma constante para no quedarse en su punto ciego al costado.","p":"Correcto. Pase de forma constante; no se quede al lado."},"zh":{"q":"你想在高速公路上超过一辆大卡车。应该怎么做？","o":["待在它旁边，看它会不会变道","从右边超车","慢慢地、贴近卡车超车","平稳地超过去，不要停留在它旁边，并清楚地打转向灯"],"h1":"卡车的侧面是盲区。","h2":"从左边超过大卡车，清楚地打转向灯，平稳地开过去，不要停留在它旁边的盲区里。","p":"对。平稳地超车，不要停留在它旁边。"},"vi":{"q":"Bạn muốn vượt một xe tải lớn trên xa lộ. Bạn nên làm thế nào?","o":["Chạy bên cạnh nó để xem nó có đổi làn không","Vượt bên phải","Vượt chậm, sát xe tải","Vượt đều đặn mà không ở lại bên cạnh nó, và bật xi nhan rõ ràng"],"h1":"Bên hông xe tải là điểm mù.","h2":"Hãy vượt xe tải lớn bên trái, bật xi nhan rõ ràng, và chạy qua đều đặn để không ở lại trong điểm mù bên cạnh nó.","p":"Đúng. Vượt đều đặn; đừng ở lại bên cạnh nó."},"tl":{"q":"Gusto mong lampasan ang isang malaking trak sa highway. Paano mo ito gagawin?","o":["Manatili sa tabi nito para makita kung lilipat ito ng linya","Lumampas sa kanang panig","Lumampas nang dahan-dahan, malapit sa trak","Lumampas nang tuloy-tuloy nang hindi nananatili sa tabi nito, at malinaw na mag-signal"],"h1":"Blind spot ang gilid ng trak.","h2":"Lampasan ang malaking trak sa kaliwa, malinaw na mag-signal, at tuloy-tuloy na lumampas para hindi ka manatili sa blind spot sa tabi nito.","p":"Tama. Lumampas nang tuloy-tuloy; huwag manatili sa tabi nito."},"ar":{"q":"تريد أن تتجاوز شاحنة كبيرة على الطريق السريع. كيف تفعل ذلك؟","o":["ابقَ بجانبها لترى إن كانت ستغيّر المسار","تجاوزها من الجهة اليمنى","تجاوزها ببطء وأنت قريب منها","تجاوزها بثبات دون أن تبقى بجانبها، وأعطِ إشارة واضحة"],"h1":"جانب الشاحنة منطقة عمياء.","h2":"تجاوز الشاحنة الكبيرة من اليسار، وأعطِ إشارة واضحة، وامضِ بثبات حتى لا تبقى في المنطقة العمياء بجانبها.","p":"صحيح. تجاوزها بثبات؛ ولا تبقَ بجانبها."},"ht":{"q":"Ou vle pase yon gwo kamyon sou otowout la. Kijan ou dwe fè l?","o":["Rete bò kote l pou wè si l ap chanje liy","Pase sou bò dwat la","Pase dousman, toupre kamyon an","Pase san rete bò kote l, epi siyale klè"],"h1":"Bò kote yon kamyon se yon zòn avèg.","h2":"Pase yon gwo kamyon sou bò gòch li, siyale klè, epi kontinye pase san ralanti pou ou pa rete nan zòn avèg bò kote l.","p":"Wi, se sa. Pase san rete; pa rete bò kote l."}},{"id":"right-of-way-064","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"Why is it dangerous to follow close behind a large truck?","o":["The driver cannot see you, and you cannot see the road ahead","Trucks never brake","The truck will slow down to let you pass","It saves fuel, so it is safe"],"h1":"A truck blocks your view.","h2":"Following close behind a truck puts you in its blind spot and blocks your view of the road ahead, so drop back.","p":"Right. Neither of you can see well."},"es":{"q":"¿Por qué es peligroso seguir muy de cerca a un camión grande?","o":["Porque el conductor no lo ve y usted no ve la vía adelante","Porque los camiones nunca frenan","Porque el camión bajará la velocidad para dejarlo pasar","Ahorra gasolina, así que es seguro"],"h1":"Un camión le tapa la vista.","h2":"Seguir muy de cerca a un camión lo pone en su punto ciego y le tapa la vista de la vía adelante, así que quédese más atrás.","p":"Correcto. Ninguno de los dos ve bien."},"zh":{"q":"为什么紧跟在大卡车后面很危险？","o":["卡车司机看不到你，你也看不到前面的路","卡车从来不刹车","卡车会减速让你超车","这样省油，所以很安全"],"h1":"卡车会挡住你的视线。","h2":"紧跟在卡车后面会让你处在它的盲区里，还会挡住你看前方道路的视线，所以要往后退一些。","p":"对。你们双方都看不清楚。"},"vi":{"q":"Tại sao chạy sát phía sau một xe tải lớn lại nguy hiểm?","o":["Tài xế không thấy bạn, và bạn không thấy đường phía trước","Xe tải không bao giờ phanh","Xe tải sẽ chạy chậm lại để bạn vượt","Cách này tiết kiệm xăng, nên an toàn"],"h1":"Xe tải che khuất tầm nhìn của bạn.","h2":"Chạy sát phía sau xe tải làm bạn nằm trong điểm mù của nó và che khuất tầm nhìn ra đường phía trước, vì vậy hãy lùi xa ra.","p":"Đúng. Cả hai bên đều không nhìn rõ."},"tl":{"q":"Bakit mapanganib na sumunod nang malapit sa likod ng malaking trak?","o":["Hindi ka nakikita ng drayber, at hindi mo nakikita ang daan sa unahan","Hindi kailanman nagpepreno ang mga trak","Babagal ang trak para makalusot ka","Nakakatipid ito sa gasolina, kaya ligtas ito"],"h1":"Tinatakpan ng trak ang tanaw mo.","h2":"Kapag sumunod ka nang malapit sa likod ng trak, nasa blind spot ka nito at hindi mo nakikita ang daan sa unahan, kaya lumayo ka.","p":"Tama. Pareho kayong hindi nakakakita nang maayos."},"ar":{"q":"لماذا من الخطر أن تسير قريبًا جدًا خلف شاحنة كبيرة؟","o":["السائق لا يراك، وأنت لا ترى الطريق أمامك","الشاحنات لا تستعمل الفرامل أبدًا","ستبطئ الشاحنة لتدعك تتجاوزها","هذا يوفّر الوقود، لذلك هو آمن"],"h1":"الشاحنة تحجب رؤيتك.","h2":"السير قريبًا خلف شاحنة يضعك في النقطة العمياء لسائقها ويحجب رؤيتك للطريق أمامك، لذلك ابتعد إلى الخلف.","p":"صحيح. لا أحد منكما يرى جيدًا."},"ht":{"q":"Poukisa li danjere pou w swiv twò pre dèyè yon gwo kamyon?","o":["Chofè a pa ka wè w, epi ou pa ka wè wout la devan","Kamyon pa janm frennen","Kamyon an ap ralanti pou kite w pase","Sa ekonomize gaz, kidonk li an sekirite"],"h1":"Yon kamyon bloke vi ou.","h2":"Lè w swiv twò pre dèyè yon kamyon, ou nan kote chofè a pa ka wè w, epi ou pa ka wè wout la devan, kidonk rete pi lwen dèyè.","p":"Wi, se sa. Ni youn ni lòt pa ka wè byen."}},{"id":"right-of-way-065","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Why should you never cut in front of a large truck and then slow down?","o":["Trucks can stop faster than cars","A loaded truck needs much more distance to stop than a car","The truck driver will honk","It is only a problem at night"],"h1":"Think about the weight of a truck.","h2":"A heavy truck needs much more distance to stop than a car, so cutting in and slowing down in front of it can cause a crash.","p":"Right. Trucks need far more room to stop."},"es":{"q":"¿Por qué nunca debe meterse delante de un camión grande y luego frenar?","o":["Porque los camiones frenan más rápido que los carros","Porque un camión cargado necesita mucha más distancia para pararse que un carro","Porque el camionero tocará la bocina","Solo es un problema de noche"],"h1":"Piense en el peso de un camión.","h2":"Un camión pesado necesita mucha más distancia para pararse que un carro, así que meterse y frenar delante de él puede causar un choque.","p":"Correcto. Los camiones necesitan mucho más espacio para parar."},"zh":{"q":"为什么绝对不要抢到大卡车前面再减速？","o":["卡车比小汽车停得更快","满载的卡车需要比小汽车长得多的距离才能停下","卡车司机会按喇叭","这只在晚上才是问题"],"h1":"想一想卡车有多重。","h2":"重型卡车需要比小汽车长得多的距离才能停下，所以抢到它前面再减速可能会造成撞车。","p":"对。卡车需要远得多的距离才能停下。"},"vi":{"q":"Tại sao không bao giờ được cắt ngang trước đầu xe tải lớn rồi chạy chậm lại?","o":["Xe tải dừng nhanh hơn xe hơi","Xe tải chở đầy hàng cần quãng đường dài hơn xe hơi rất nhiều để dừng lại","Tài xế xe tải sẽ bấm còi","Việc này chỉ nguy hiểm vào ban đêm"],"h1":"Hãy nghĩ về sức nặng của xe tải.","h2":"Xe tải nặng cần quãng đường dài hơn xe hơi rất nhiều để dừng lại, vì vậy cắt ngang trước đầu nó rồi chạy chậm lại có thể gây tai nạn.","p":"Đúng. Xe tải cần nhiều khoảng trống hơn hẳn để dừng lại."},"tl":{"q":"Bakit hindi ka dapat kailanman sumingit sa harap ng malaking trak at saka bumagal?","o":["Mas mabilis huminto ang trak kaysa sa kotse","Ang trak na may karga ay nangangailangan ng mas mahabang distansya para huminto kaysa sa kotse","Bubusina ang drayber ng trak","Problema lang ito sa gabi"],"h1":"Isipin kung gaano kabigat ang trak.","h2":"Ang mabigat na trak ay nangangailangan ng mas mahabang distansya para huminto kaysa sa kotse, kaya ang pagsingit at pagbagal sa harap nito ay maaaring magdulot ng banggaan.","p":"Tama. Mas mahabang espasyo ang kailangan ng trak para huminto."},"ar":{"q":"لماذا يجب ألّا تدخل أمام شاحنة كبيرة ثم تبطئ؟","o":["الشاحنات تتوقف أسرع من السيارات","الشاحنة المحمّلة تحتاج إلى مسافة أطول بكثير من السيارة لتتوقف","سيستعمل سائق الشاحنة البوق","هذه مشكلة في الليل فقط"],"h1":"فكّر في وزن الشاحنة.","h2":"الشاحنة الثقيلة تحتاج إلى مسافة أطول بكثير من السيارة لتتوقف، لذلك فإن الدخول أمامها ثم الإبطاء قد يسبب حادثًا.","p":"صحيح. الشاحنات تحتاج إلى مسافة أكبر بكثير لتتوقف."},"ht":{"q":"Poukisa ou pa dwe janm koupe devan yon gwo kamyon epi ralanti?","o":["Kamyon ka kanpe pi vit pase machin","Yon kamyon ki chaje bezwen anpil plis distans pase yon machin pou l kanpe","Chofè kamyon an ap klaksonnen","Se sèlman lannwit sa se yon pwoblèm"],"h1":"Panse ak pwa yon kamyon.","h2":"Yon kamyon lou bezwen anpil plis distans pase yon machin pou l kanpe, kidonk si w koupe devan l epi ralanti, sa ka lakòz yon aksidan.","p":"Wi, se sa. Kamyon bezwen anpil plis espas pou yo kanpe."}},{"id":"right-of-way-066","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"A large truck passes you on the highway, and its wind pushes your car. What should you do?","o":["Brake hard","Steer sharply away","Keep both hands on the wheel and hold your lane","Speed up beside the truck"],"h1":"The push is brief.","h2":"The air moving around a large truck can push your car, so keep both hands on the wheel, stay calm and hold your lane.","p":"Right. Hold the wheel and keep your lane."},"es":{"q":"Un camión grande lo rebasa en la carretera y el viento empuja su carro. ¿Qué debe hacer?","o":["Frenar fuerte","Girar bruscamente para alejarse","Mantener ambas manos en el volante y seguir en su carril","Acelerar al lado del camión"],"h1":"El empujón dura poco.","h2":"El aire que mueve un camión grande puede empujar su carro, así que mantenga ambas manos en el volante, conserve la calma y siga en su carril.","p":"Correcto. Sujete el volante y siga en su carril."},"zh":{"q":"一辆大卡车在高速公路上超过你，它带起的风把你的车往旁边推。你应该怎么做？","o":["用力踩刹车","猛打方向盘躲开","双手握住方向盘，保持在自己的车道内","在卡车旁边加速"],"h1":"这股推力很快就会过去。","h2":"大卡车周围流动的空气会推动你的车，所以要双手握住方向盘，保持冷静，并保持在自己的车道内。","p":"对。握住方向盘，保持在自己的车道内。"},"vi":{"q":"Một xe tải lớn vượt qua bạn trên xa lộ, và luồng gió của nó đẩy xe bạn. Bạn nên làm gì?","o":["Phanh gấp","Đánh lái mạnh ra xa","Giữ cả hai tay trên vô lăng và giữ xe trong làn của mình","Tăng tốc chạy song song với xe tải"],"h1":"Lực đẩy chỉ diễn ra trong chốc lát.","h2":"Luồng không khí quanh một xe tải lớn có thể đẩy xe bạn, vì vậy hãy giữ cả hai tay trên vô lăng, bình tĩnh và giữ xe trong làn của mình.","p":"Đúng. Giữ chặt vô lăng và giữ làn đường."},"tl":{"q":"Nilampasan ka ng malaking trak sa highway, at itinutulak ng hangin nito ang kotse mo. Ano ang dapat mong gawin?","o":["Magpreno nang malakas","Biglang lumiko palayo","Panatilihin ang dalawang kamay sa manibela at manatili sa iyong lane","Bumilis sa tabi ng trak"],"h1":"Sandali lang ang tulak.","h2":"Ang hangin sa paligid ng malaking trak ay maaaring tumulak sa kotse mo, kaya panatilihin ang dalawang kamay sa manibela, manatiling kalmado at manatili sa iyong lane.","p":"Tama. Hawakan ang manibela at manatili sa iyong lane."},"ar":{"q":"تتجاوزك شاحنة كبيرة على الطريق السريع، وهواؤها يدفع سيارتك. ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة","انحرف بحدة بعيدًا عنها","أبقِ يديك الاثنتين على المقود وابقَ في مسارك","زِد سرعتك بجانب الشاحنة"],"h1":"الدفعة قصيرة.","h2":"الهواء الذي يتحرك حول شاحنة كبيرة قد يدفع سيارتك، لذلك أبقِ يديك الاثنتين على المقود، وابقَ هادئًا، وحافظ على مسارك.","p":"صحيح. أمسك المقود وابقَ في مسارك."},"ht":{"q":"Yon gwo kamyon pase w sou otowout la, epi van li pouse machin ou. Kisa ou dwe fè?","o":["Frennen fò","Vire volan an brid sou kou pou w ale lwen","Kenbe de men ou sou volan an epi rete nan liy ou","Akselere bò kote kamyon an"],"h1":"Pouse a pa dire lontan.","h2":"Van ki deplase bò kote yon gwo kamyon ka pouse machin ou, kidonk kenbe de men ou sou volan an, rete kalm epi rete nan liy ou.","p":"Wi, se sa. Kenbe volan an epi rete nan liy ou."}},{"id":"right-of-way-067","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You are behind a school bus or transit bus that stops often. What should you do?","o":["Pass it as soon as it slows","Follow close so you can pass quickly","Honk each time it stops","Keep a safe distance and be ready to stop"],"h1":"Buses stop to pick up and drop off people.","h2":"Buses stop often and people may be getting on or off, so stay back a safe distance and be ready to stop.","p":"Right. Stay back and be ready to stop."},"es":{"q":"Usted va detrás de un autobús escolar o urbano que se para seguido. ¿Qué debe hacer?","o":["Rebasarlo en cuanto baje la velocidad","Seguirlo de cerca para rebasar rápido","Tocar la bocina cada vez que para","Mantener una distancia segura y estar listo para pararse"],"h1":"Los autobuses paran para subir y bajar personas.","h2":"Los autobuses se paran a menudo y puede haber personas subiendo o bajando, así que manténgase a una distancia segura y esté listo para pararse.","p":"Correcto. Quédese atrás y esté listo para parar."},"zh":{"q":"你跟在一辆经常停车的校车或公交车后面。你应该怎么做？","o":["它一减速就超过去","跟紧一点，好快点超车","它每次停车都按喇叭","保持安全距离，随时准备停车"],"h1":"公交车停下来是为了让人上下车。","h2":"公交车经常停车，可能有人正在上车或下车，所以要保持安全距离，随时准备停车。","p":"对。保持距离，随时准备停车。"},"vi":{"q":"Bạn đang chạy phía sau một xe buýt trường học hoặc xe buýt công cộng hay dừng lại. Bạn nên làm gì?","o":["Vượt qua ngay khi nó chạy chậm lại","Chạy sát để có thể vượt nhanh","Bấm còi mỗi lần nó dừng","Giữ khoảng cách an toàn và sẵn sàng dừng lại"],"h1":"Xe buýt dừng để đón và trả khách.","h2":"Xe buýt dừng thường xuyên và có thể có người đang lên hoặc xuống xe, vì vậy hãy giữ khoảng cách an toàn và sẵn sàng dừng lại.","p":"Đúng. Giữ khoảng cách và sẵn sàng dừng lại."},"tl":{"q":"Nasa likod ka ng school bus o pampublikong bus na madalas huminto. Ano ang dapat mong gawin?","o":["Lampasan ito agad kapag bumagal","Sumunod nang malapit para mabilis kang makalampas","Bumusina tuwing hihinto ito","Panatilihin ang ligtas na distansya at maging handang huminto"],"h1":"Humihinto ang mga bus para magsakay at magbaba ng tao.","h2":"Madalas huminto ang mga bus at maaaring may mga taong sumasakay o bumababa, kaya manatili sa ligtas na distansya at maging handang huminto.","p":"Tama. Lumayo at maging handang huminto."},"ar":{"q":"أنت خلف حافلة مدرسية أو حافلة نقل عام تتوقف كثيرًا. ماذا يجب أن تفعل؟","o":["تجاوزها بمجرد أن تبطئ","سِر قريبًا منها لتتجاوزها بسرعة","استعمل البوق كلما توقفت","حافظ على مسافة آمنة وكن مستعدًا للتوقف"],"h1":"الحافلات تتوقف لتُركب الناس وتُنزلهم.","h2":"الحافلات تتوقف كثيرًا وقد يكون هناك أشخاص يركبون أو ينزلون، لذلك ابقَ على مسافة آمنة خلفها وكن مستعدًا للتوقف.","p":"صحيح. ابقَ بعيدًا وكن مستعدًا للتوقف."},"ht":{"q":"Ou dèyè yon otobis lekòl oswa yon otobis transpò piblik ki kanpe souvan. Kisa ou dwe fè?","o":["Pase l depi li ralanti","Swiv li pre pou w ka pase l vit","Klaksonnen chak fwa li kanpe","Kenbe yon distans ki an sekirite epi pare pou w kanpe"],"h1":"Otobis kanpe pou moun monte ak desann.","h2":"Otobis kanpe souvan epi gen moun ki ka ap monte oswa desann, kidonk rete dèyè a yon distans ki an sekirite epi pare pou w kanpe.","p":"Wi, se sa. Rete dèyè epi pare pou w kanpe."}},{"id":"right-of-way-068","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"Why can a train not stop quickly to avoid a car on the tracks?","o":["A train is so heavy that it may need a mile or more to stop","Train drivers are not allowed to brake","Trains have no brakes","Trains can stop in a few feet"],"h1":"Think about how heavy a train is.","h2":"A train is extremely heavy, so even with emergency brakes it can take a mile or more to stop; it cannot stop for a car on the tracks.","p":"Right. A train needs a very long distance to stop."},"es":{"q":"¿Por qué un tren no puede pararse rápido para no chocar a un carro en las vías?","o":["Porque un tren es tan pesado que puede necesitar una milla o más para pararse","Porque los maquinistas no pueden frenar","Porque los trenes no tienen frenos","Los trenes pueden pararse en pocos pies"],"h1":"Piense en lo pesado que es un tren.","h2":"Un tren es pesadísimo, así que aun con los frenos de emergencia puede tardar una milla o más en pararse; no puede pararse por un carro en las vías.","p":"Correcto. Un tren necesita muchísima distancia para parar."},"zh":{"q":"为什么火车不能很快停下来避开铁轨上的汽车？","o":["火车非常重，可能需要一英里或更远才能停下","火车司机不准刹车","火车没有刹车","火车几英尺就能停下"],"h1":"想一想火车有多重。","h2":"火车极其沉重，即使用紧急刹车也可能需要一英里或更远才能停下；它无法为铁轨上的汽车停车。","p":"对。火车需要非常长的距离才能停下。"},"vi":{"q":"Tại sao tàu hỏa không thể dừng nhanh để tránh một chiếc xe trên đường ray?","o":["Tàu hỏa rất nặng nên có thể cần một dặm hoặc hơn để dừng lại","Người lái tàu không được phép phanh","Tàu hỏa không có phanh","Tàu hỏa có thể dừng trong vài feet"],"h1":"Hãy nghĩ xem tàu hỏa nặng đến mức nào.","h2":"Tàu hỏa cực kỳ nặng, nên dù dùng phanh khẩn cấp vẫn có thể mất một dặm hoặc hơn để dừng lại; nó không thể dừng kịp cho một chiếc xe trên đường ray.","p":"Đúng. Tàu hỏa cần một quãng đường rất dài để dừng lại."},"tl":{"q":"Bakit hindi kayang huminto agad ng tren para maiwasan ang kotse sa riles?","o":["Napakabigat ng tren kaya maaaring kailanganin nito ng isang milya o higit pa para huminto","Hindi pinapayagang magpreno ang mga drayber ng tren","Walang preno ang mga tren","Kayang huminto ng tren sa loob ng ilang talampakan"],"h1":"Isipin kung gaano kabigat ang tren.","h2":"Napakabigat ng tren, kaya kahit gumamit ito ng emergency brake ay maaaring umabot ng isang milya o higit pa bago ito huminto; hindi ito kayang huminto para sa kotseng nasa riles.","p":"Tama. Napakahabang distansya ang kailangan ng tren para huminto."},"ar":{"q":"لماذا لا يستطيع القطار أن يتوقف بسرعة ليتجنب سيارة على السكة؟","o":["القطار ثقيل جدًا لدرجة أنه قد يحتاج إلى ميل أو أكثر ليتوقف","سائقو القطارات غير مسموح لهم باستعمال الفرامل","القطارات ليس لها فرامل","القطارات تستطيع التوقف خلال بضعة أقدام"],"h1":"فكّر في مدى ثقل القطار.","h2":"القطار ثقيل جدًا، لذلك حتى مع فرامل الطوارئ قد يحتاج إلى ميل أو أكثر ليتوقف؛ ولا يستطيع أن يتوقف من أجل سيارة على السكة.","p":"صحيح. القطار يحتاج إلى مسافة طويلة جدًا ليتوقف."},"ht":{"q":"Poukisa yon tren pa ka kanpe vit pou l evite yon machin ki sou ray yo?","o":["Yon tren tèlman lou, li ka bezwen yon mil oswa plis pou l kanpe","Chofè tren pa gen dwa frennen","Tren pa gen fren","Tren ka kanpe nan kèk pye"],"h1":"Panse ak jan yon tren lou.","h2":"Yon tren lou anpil anpil, kidonk menm avèk fren ijans, li ka pran yon mil oswa plis pou l kanpe; li pa ka kanpe pou yon machin ki sou ray yo.","p":"Wi, se sa. Yon tren bezwen yon distans ki long anpil pou l kanpe."}},{"id":"right-of-way-069","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A train seems to be moving slowly and far away. Why should you still not try to cross ahead of it?","o":["Slow trains always stop for cars","Trains are usually closer and faster than they look","The crossing lights are wrong","Trains back up often"],"h1":"Large objects are hard to judge.","h2":"A train is so big that it looks slower and farther away than it really is, so never try to beat a train to the crossing.","p":"Right. Trains are closer and faster than they look."},"es":{"q":"Un tren parece ir despacio y estar lejos. ¿Por qué aun así no debe cruzar delante de él?","o":["Porque los trenes lentos siempre paran por los carros","Porque los trenes suelen estar más cerca e ir más rápido de lo que parece","Porque las luces del cruce están mal","Porque los trenes retroceden a menudo"],"h1":"Los objetos grandes son difíciles de calcular.","h2":"Un tren es tan grande que parece más lento y más lejano de lo que realmente está, así que nunca intente ganarle al tren en el cruce.","p":"Correcto. Los trenes están más cerca y van más rápido de lo que parece."},"zh":{"q":"一列火车看起来开得很慢，而且离得很远。为什么你仍然不应该抢在它前面过铁路？","o":["慢速火车总会为汽车停下","火车通常比看起来更近、更快","道口的灯坏了","火车经常倒车"],"h1":"大的物体很难判断远近和快慢。","h2":"火车非常大，看起来比实际更慢、更远，所以绝对不要想抢在火车前面通过道口。","p":"对。火车比看起来更近、更快。"},"vi":{"q":"Một đoàn tàu có vẻ đang chạy chậm và còn ở xa. Tại sao bạn vẫn không nên cố băng qua trước nó?","o":["Tàu chạy chậm luôn dừng lại nhường xe","Tàu hỏa thường ở gần hơn và chạy nhanh hơn so với vẻ bề ngoài","Đèn ở chỗ băng qua bị sai","Tàu hỏa hay chạy lùi"],"h1":"Vật lớn rất khó ước lượng.","h2":"Tàu hỏa to đến mức trông chậm hơn và xa hơn so với thực tế, vì vậy đừng bao giờ cố băng qua chỗ giao đường sắt trước khi tàu đến.","p":"Đúng. Tàu hỏa ở gần hơn và nhanh hơn so với vẻ bề ngoài."},"tl":{"q":"Mukhang mabagal at malayo pa ang isang tren. Bakit hindi ka pa rin dapat sumubok na tumawid bago ito dumating?","o":["Laging humihinto ang mabagal na tren para sa mga kotse","Kadalasang mas malapit at mas mabilis ang tren kaysa sa itsura nito","Mali ang mga ilaw sa tawiran","Madalas umatras ang mga tren"],"h1":"Mahirap tantiyahin ang malalaking bagay.","h2":"Napakalaki ng tren kaya mukha itong mas mabagal at mas malayo kaysa sa totoo, kaya huwag kailanman subukang unahan ang tren sa tawiran.","p":"Tama. Mas malapit at mas mabilis ang tren kaysa sa itsura nito."},"ar":{"q":"يبدو أن قطارًا يتحرك ببطء وهو بعيد. لماذا يجب ألّا تحاول العبور أمامه مع ذلك؟","o":["القطارات البطيئة تتوقف دائمًا من أجل السيارات","القطارات عادةً أقرب وأسرع مما تبدو","أضواء المعبر خاطئة","القطارات ترجع إلى الخلف كثيرًا"],"h1":"من الصعب تقدير الأجسام الكبيرة.","h2":"القطار كبير جدًا لدرجة أنه يبدو أبطأ وأبعد مما هو في الحقيقة، لذلك يجب ألّا تحاول أبدًا أن تسبق القطار إلى المعبر.","p":"صحيح. القطارات أقرب وأسرع مما تبدو."},"ht":{"q":"Yon tren sanble l ap mache dousman epi li lwen. Poukisa ou toujou pa dwe eseye travèse devan l?","o":["Tren ki mache dousman toujou kanpe pou machin","Tren yo konn pi pre epi pi vit pase jan yo parèt","Limyè travès la pa bon","Tren konn fè bak souvan"],"h1":"Li difisil pou w jije gwo bagay.","h2":"Yon tren tèlman gwo, li parèt pi dousman epi pi lwen pase jan li ye vre, kidonk pa janm eseye rive nan travès la anvan tren an.","p":"Wi, se sa. Tren yo pi pre epi pi vit pase jan yo parèt."}},{"id":"right-of-way-070","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You come to a railroad crossing with only a crossbuck sign: no lights or gates. What should you do?","o":["Cross at your normal speed","Stop only if you see a train on the tracks","Slow down, look both ways and listen, and be ready to stop for a train","Honk and cross"],"h1":"Nothing will warn you here except your own eyes and ears.","h2":"At a crossing with no lights or gates, slow down, look both ways and listen, and stop for any train that is coming.","p":"Right. Slow down, look and listen."},"es":{"q":"Usted llega a un cruce de tren que solo tiene la señal en cruz: sin luces ni barreras. ¿Qué debe hacer?","o":["Cruzar a su velocidad normal","Pararse solo si ve un tren sobre las vías","Bajar la velocidad, mirar a ambos lados y escuchar, y estar listo para pararse por un tren","Tocar la bocina y cruzar"],"h1":"Aquí solo sus ojos y oídos le avisarán.","h2":"En un cruce sin luces ni barreras, baje la velocidad, mire a ambos lados y escuche, y párese por cualquier tren que se acerque.","p":"Correcto. Baje la velocidad, mire y escuche."},"zh":{"q":"你来到一个铁路道口，那里只有一个交叉形铁路标志（crossbuck），没有灯也没有栏杆。你应该怎么做？","o":["以平常的速度通过","只有看到铁轨上有火车时才停车","减速，向两边看并仔细听，随时准备为火车停车","按喇叭然后通过"],"h1":"在这里，除了你自己的眼睛和耳朵，没有任何东西会提醒你。","h2":"在没有灯也没有栏杆的道口，要减速，向两边看并仔细听，有火车开来就要停车。","p":"对。减速，看一看，听一听。"},"vi":{"q":"Bạn đến một chỗ giao với đường sắt chỉ có biển hình chữ X (crossbuck), không có đèn hay thanh chắn. Bạn nên làm gì?","o":["Băng qua với tốc độ bình thường","Chỉ dừng lại nếu thấy tàu trên đường ray","Chạy chậm lại, nhìn hai bên và lắng nghe, sẵn sàng dừng lại nếu có tàu","Bấm còi rồi băng qua"],"h1":"Ở đây không có gì báo cho bạn ngoài mắt và tai của chính bạn.","h2":"Tại chỗ giao với đường sắt không có đèn hay thanh chắn, hãy chạy chậm lại, nhìn hai bên và lắng nghe, và dừng lại nếu có tàu đang đến.","p":"Đúng. Chạy chậm lại, nhìn và lắng nghe."},"tl":{"q":"Dumating ka sa tawiran ng riles na may crossbuck sign lang (karatulang hugis X): walang ilaw o harang. Ano ang dapat mong gawin?","o":["Tumawid sa karaniwan mong bilis","Huminto lang kung may nakikita kang tren sa riles","Bumagal, tumingin sa magkabilang direksyon at makinig, at maging handang huminto para sa tren","Bumusina at tumawid"],"h1":"Walang magbababala sa iyo rito maliban sa sarili mong mata at tainga.","h2":"Sa tawirang walang ilaw o harang, bumagal, tumingin sa magkabilang direksyon at makinig, at huminto kung may paparating na tren.","p":"Tama. Bumagal, tumingin at makinig."},"ar":{"q":"وصلت إلى معبر سكة حديد فيه علامة على شكل X (crossbuck) فقط: لا أضواء ولا حواجز. ماذا يجب أن تفعل؟","o":["اعبر بسرعتك العادية","توقف فقط إذا رأيت قطارًا على السكة","خفّف السرعة، وانظر إلى الجهتين واستمع، وكن مستعدًا للتوقف من أجل القطار","استعمل البوق واعبر"],"h1":"لا شيء هنا سيحذّرك إلا عيناك وأذناك.","h2":"عند معبر ليس فيه أضواء ولا حواجز، خفّف السرعة، وانظر إلى الجهتين واستمع، وتوقف إذا كان هناك قطار قادم.","p":"صحيح. خفّف السرعة، وانظر، واستمع."},"ht":{"q":"Ou rive nan yon travès tren ki gen sèlman yon siy an fòm X (crossbuck): pa gen limyè ni baryè. Kisa ou dwe fè?","o":["Travèse ak vitès nòmal ou","Kanpe sèlman si w wè yon tren sou ray yo","Ralanti, gade de bò epi koute, epi pare pou w kanpe pou yon tren","Klaksonnen epi travèse"],"h1":"Pa gen anyen isit la ki pral avèti w, sèlman pwòp je w ak zòrèy ou.","h2":"Nan yon travès ki pa gen limyè ni baryè, ralanti, gade de bò epi koute, epi kanpe pou nenpòt tren k ap vini.","p":"Wi, se sa. Ralanti, gade epi koute."}},{"id":"right-of-way-071","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"You are waiting at a railroad crossing and the train has passed, but the lights are still flashing. What should you do?","o":["Go right away, since the train is gone","Drive around the gate","Back up and turn around","Keep waiting; another train may be coming"],"h1":"The lights stay on for a reason.","h2":"If the lights keep flashing after a train passes, another train may be coming, so wait until the lights stop and the gates rise.","p":"Right. Wait until the lights stop."},"es":{"q":"Usted espera en un cruce de tren y el tren ya pasó, pero las luces siguen parpadeando. ¿Qué debe hacer?","o":["Seguir enseguida, porque el tren ya pasó","Rodear la barrera","Retroceder y dar la vuelta","Seguir esperando; puede venir otro tren"],"h1":"Las luces siguen encendidas por una razón.","h2":"Si las luces siguen parpadeando después de que pasa un tren, puede venir otro, así que espere hasta que se apaguen las luces y suban las barreras.","p":"Correcto. Espere hasta que se apaguen las luces."},"zh":{"q":"你在铁路道口等候，火车已经过去了，但灯还在闪。你应该怎么做？","o":["火车已经走了，马上开过去","绕过栏杆开过去","倒车然后掉头","继续等；可能还有另一列火车开来"],"h1":"灯一直亮着是有原因的。","h2":"如果火车过去后灯还在闪，可能还有另一列火车开来，所以要等到灯停止闪烁、栏杆升起。","p":"对。等到灯停止闪烁。"},"vi":{"q":"Bạn đang chờ ở chỗ giao với đường sắt và tàu đã đi qua, nhưng đèn vẫn còn nhấp nháy. Bạn nên làm gì?","o":["Đi ngay, vì tàu đã đi rồi","Lái vòng qua thanh chắn","Lùi xe lại và quay đầu","Tiếp tục chờ; có thể có một đoàn tàu khác đang đến"],"h1":"Đèn vẫn sáng là có lý do.","h2":"Nếu đèn vẫn nhấp nháy sau khi tàu đi qua, có thể có một đoàn tàu khác đang đến, vì vậy hãy chờ cho đến khi đèn tắt và thanh chắn được nâng lên.","p":"Đúng. Hãy chờ cho đến khi đèn tắt."},"tl":{"q":"Naghihintay ka sa tawiran ng riles at nakadaan na ang tren, pero kumikislap pa rin ang mga ilaw. Ano ang dapat mong gawin?","o":["Umandar agad, dahil wala na ang tren","Umikot sa harang","Umatras at bumalik","Patuloy na maghintay; maaaring may isa pang tren na paparating"],"h1":"May dahilan kung bakit nakabukas pa ang mga ilaw.","h2":"Kung kumikislap pa rin ang mga ilaw pagkatapos dumaan ng tren, maaaring may isa pang tren na paparating, kaya maghintay hanggang tumigil ang mga ilaw at umangat ang mga harang.","p":"Tama. Maghintay hanggang tumigil ang mga ilaw."},"ar":{"q":"أنت تنتظر عند معبر سكة حديد ومرّ القطار، لكن الأضواء ما زالت تومض. ماذا يجب أن تفعل؟","o":["انطلق فورًا، لأن القطار ذهب","التفّ حول الحاجز","ارجع إلى الخلف واستدر","استمر في الانتظار؛ فقد يكون هناك قطار آخر قادم"],"h1":"الأضواء تبقى مضاءة لسبب.","h2":"إذا استمرت الأضواء في الوميض بعد مرور القطار، فقد يكون هناك قطار آخر قادم، لذلك انتظر حتى تتوقف الأضواء وترتفع الحواجز.","p":"صحيح. انتظر حتى تتوقف الأضواء."},"ht":{"q":"Ou ap tann nan yon travès tren epi tren an fin pase, men limyè yo toujou ap flache. Kisa ou dwe fè?","o":["Ale touswit, paske tren an ale","Kondui fè wonn baryè a","Fè bak epi vire tounen","Kontinye tann; yon lòt tren ka ap vini"],"h1":"Limyè yo rete limen pou yon rezon.","h2":"Si limyè yo kontinye flache apre yon tren fin pase, yon lòt tren ka ap vini, kidonk tann jiskaske limyè yo sispann epi baryè yo leve.","p":"Wi, se sa. Tann jiskaske limyè yo sispann."}},{"id":"right-of-way-072","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"A deer runs across the road in front of you and makes it across. What should you expect?","o":["More deer may follow, so slow down and watch","The danger is over","The deer will come back to the same spot","Deer only cross at night"],"h1":"Deer often move in groups.","h2":"Deer often travel in groups, so when one crosses, slow down and watch for more that may follow.","p":"Right. More deer may follow."},"es":{"q":"Un venado cruza corriendo la vía delante de usted y llega al otro lado. ¿Qué debe esperar?","o":["Que pueden seguir más venados, así que baje la velocidad y mire","Que el peligro terminó","Que el venado volverá al mismo lugar","Que los venados solo cruzan de noche"],"h1":"Los venados suelen andar en grupo.","h2":"Los venados suelen andar en grupo, así que cuando uno cruza, baje la velocidad y fíjese en otros que puedan seguirlo.","p":"Correcto. Pueden seguir más venados."},"zh":{"q":"一只鹿从你前面横穿马路，并且已经过去了。你应该预料到什么？","o":["后面可能还有更多的鹿，所以要减速并留意","危险已经过去了","那只鹿会回到同一个地方","鹿只在晚上过马路"],"h1":"鹿常常成群活动。","h2":"鹿常常成群行动，所以当一只鹿穿过马路后，要减速并留意后面可能跟着的其他鹿。","p":"对。后面可能还有更多的鹿。"},"vi":{"q":"Một con nai chạy băng qua đường trước mặt bạn và đã qua được bên kia. Bạn nên lường trước điều gì?","o":["Có thể còn nhiều con nai khác chạy theo, vì vậy hãy chạy chậm lại và quan sát","Nguy hiểm đã qua","Con nai sẽ quay lại đúng chỗ cũ","Nai chỉ băng qua đường vào ban đêm"],"h1":"Nai thường đi theo đàn.","h2":"Nai thường di chuyển theo đàn, vì vậy khi một con băng qua, hãy chạy chậm lại và để ý những con khác có thể chạy theo.","p":"Đúng. Có thể còn nhiều nai khác chạy theo."},"tl":{"q":"Isang usa ang tumakbo patawid sa kalsada sa harap mo at nakatawid ito. Ano ang dapat mong asahan?","o":["Maaaring may iba pang usa na susunod, kaya bumagal at magmasid","Tapos na ang panganib","Babalik ang usa sa parehong lugar","Sa gabi lang tumatawid ang mga usa"],"h1":"Madalas na grupo-grupo ang galaw ng mga usa.","h2":"Madalas na grupo-grupo ang paglalakbay ng mga usa, kaya kapag may isang tumawid, bumagal at magbantay sa iba pang maaaring sumunod.","p":"Tama. Maaaring may iba pang usa na susunod."},"ar":{"q":"غزال يجري عبر الطريق أمامك ويصل إلى الجهة الأخرى. ماذا يجب أن تتوقع؟","o":["قد تتبعه غزلان أخرى، لذلك خفّف السرعة وانتبه","انتهى الخطر","سيعود الغزال إلى المكان نفسه","الغزلان تعبر في الليل فقط"],"h1":"الغزلان تتحرك غالبًا في مجموعات.","h2":"الغزلان تتنقل غالبًا في مجموعات، لذلك عندما يعبر غزال واحد، خفّف السرعة وانتبه لغزلان أخرى قد تتبعه.","p":"صحيح. قد تتبعه غزلان أخرى."},"ht":{"q":"Yon sèf kouri travèse wout la devan w epi li rive lòt bò. Kisa ou dwe atann?","o":["Lòt sèf ka swiv li, kidonk ralanti epi veye","Danje a fini","Sèf la pral tounen nan menm kote a","Sèf travèse sèlman lannwit"],"h1":"Sèf konn deplase an gwoup.","h2":"Sèf konn vwayaje an gwoup, kidonk lè youn travèse, ralanti epi veye pou lòt ki ka swiv li.","p":"Wi, se sa. Lòt sèf ka swiv li."}},{"id":"right-of-way-073","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A deer suddenly stands in your lane and you cannot stop in time. What is usually safest?","o":["Swerve hard into the other lane","Brake firmly and stay in your lane","Swerve off the road","Speed up"],"h1":"Swerving can cause a worse crash.","h2":"If you cannot avoid a deer, brake firmly and stay in your lane, because swerving can send you into oncoming traffic or off the road.","p":"Right. Brake and stay in your lane."},"es":{"q":"De repente hay un venado en su carril y no alcanza a pararse. ¿Qué suele ser lo más seguro?","o":["Girar bruscamente al otro carril","Frenar con firmeza y quedarse en su carril","Salirse de la vía","Acelerar"],"h1":"Esquivar puede causar un choque peor.","h2":"Si no puede evitar un venado, frene con firmeza y quédese en su carril, porque esquivar puede mandarlo contra el tráfico de frente o fuera de la vía.","p":"Correcto. Frene y quédese en su carril."},"zh":{"q":"一只鹿突然站在你的车道上，你来不及停车。通常怎样做最安全？","o":["猛打方向盘冲进另一条车道","用力踩刹车，留在自己的车道内","猛打方向盘冲出路面","加速"],"h1":"猛打方向盘可能造成更严重的车祸。","h2":"如果你躲不开鹿，就用力踩刹车并留在自己的车道内，因为猛打方向盘可能让你撞上对面来车或冲出路面。","p":"对。踩刹车，留在自己的车道内。"},"vi":{"q":"Một con nai bất ngờ đứng trong làn đường của bạn và bạn không thể dừng kịp. Thường thì cách nào an toàn nhất?","o":["Đánh lái gấp sang làn bên kia","Phanh mạnh và giữ xe trong làn của mình","Đánh lái gấp ra khỏi đường","Tăng tốc"],"h1":"Đánh lái gấp có thể gây ra tai nạn tệ hơn.","h2":"Nếu bạn không thể tránh con nai, hãy phanh mạnh và giữ xe trong làn của mình, vì đánh lái gấp có thể đưa bạn vào xe chạy ngược chiều hoặc lao ra khỏi đường.","p":"Đúng. Phanh và giữ xe trong làn của mình."},"tl":{"q":"Biglang may usang nakatayo sa iyong lane at hindi ka makakahinto sa oras. Ano ang karaniwang pinakaligtas?","o":["Biglang lumiko papunta sa kabilang lane","Magpreno nang mariin at manatili sa iyong lane","Biglang lumiko palabas ng kalsada","Bumilis"],"h1":"Ang biglang paglihis ay maaaring magdulot ng mas malalang banggaan.","h2":"Kung hindi mo maiiwasan ang usa, magpreno nang mariin at manatili sa iyong lane, dahil ang biglang paglihis ay maaaring magdala sa iyo sa paparating na sasakyan o palabas ng kalsada.","p":"Tama. Magpreno at manatili sa iyong lane."},"ar":{"q":"وقف غزال فجأة في مسارك ولا تستطيع أن تتوقف في الوقت المناسب. ما الأكثر أمانًا عادةً؟","o":["انحرف بقوة إلى المسار الآخر","اضغط على الفرامل بثبات وابقَ في مسارك","انحرف بقوة إلى خارج الطريق","زِد السرعة"],"h1":"الانحراف المفاجئ قد يسبب حادثًا أسوأ.","h2":"إذا لم تستطع تجنب الغزال، فاضغط على الفرامل بثبات وابقَ في مسارك، لأن الانحراف قد يدفعك إلى السيارات القادمة من الاتجاه المعاكس أو إلى خارج الطريق.","p":"صحيح. اضغط على الفرامل وابقَ في مسارك."},"ht":{"q":"Yon sèf sanzatann kanpe nan liy ou epi ou pa ka kanpe a tan. Kisa ki pi an sekirite anjeneral?","o":["Vire volan an fò pou w antre nan lòt liy lan","Frennen fèm epi rete nan liy ou","Vire volan an fò pou w soti sou wout la","Akselere"],"h1":"Vire volan an brid sou kou ka lakòz yon aksidan ki pi grav.","h2":"Si w pa ka evite yon sèf, frennen fèm epi rete nan liy ou, paske si w vire volan an brid sou kou, ou ka antre nan machin k ap vini an fas oswa soti sou wout la.","p":"Wi, se sa. Frennen epi rete nan liy ou."}},{"id":"right-of-way-074","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"How do you give the hand signal for a left turn?","o":["Hold your left arm up, bent at the elbow","Hold your left arm down, bent at the elbow","Hold your left arm straight out the window","Wave your arm in a circle"],"h1":"The arm points the way you will go.","h2":"To signal a left turn by hand, hold your left arm and hand straight out the window, pointing left.","p":"Right. Arm straight out means left turn."},"es":{"q":"¿Cómo se hace la señal de mano para girar a la izquierda?","o":["Levantando el brazo izquierdo doblado hacia arriba","Bajando el brazo izquierdo doblado hacia abajo","Extendiendo el brazo izquierdo recto por la ventana","Moviendo el brazo en círculos"],"h1":"El brazo apunta hacia donde va a ir.","h2":"Para señalar con la mano un giro a la izquierda, extienda el brazo y la mano izquierda rectos por la ventana, apuntando a la izquierda.","p":"Correcto. Brazo recto hacia afuera es giro a la izquierda."},"zh":{"q":"用手势表示左转该怎么做？","o":["左臂向上举，肘部弯曲","左臂向下垂，肘部弯曲","左臂伸出窗外，伸直","手臂画圈挥动"],"h1":"手臂指向你要去的方向。","h2":"用手势表示左转时，把左臂和左手伸出窗外，伸直并指向左边。","p":"对。手臂伸直表示左转。"},"vi":{"q":"Làm thế nào để ra tín hiệu tay khi rẽ trái?","o":["Giơ tay trái lên, gập ở khuỷu tay","Hạ tay trái xuống, gập ở khuỷu tay","Đưa tay trái thẳng ra ngoài cửa sổ","Vẫy tay theo vòng tròn"],"h1":"Cánh tay chỉ về hướng bạn sẽ đi.","h2":"Để ra tín hiệu rẽ trái bằng tay, hãy đưa tay trái và bàn tay thẳng ra ngoài cửa sổ, chỉ về bên trái.","p":"Đúng. Tay đưa thẳng ra nghĩa là rẽ trái."},"tl":{"q":"Paano mo ibibigay ang hand signal para sa pagliko pakaliwa?","o":["Itaas ang kaliwang braso, nakabaluktot sa siko","Ibaba ang kaliwang braso, nakabaluktot sa siko","Iunat nang diretso ang kaliwang braso palabas ng bintana","Iwagayway ang braso nang paikot"],"h1":"Itinuturo ng braso ang direksyong pupuntahan mo.","h2":"Para magsenyas ng pagliko pakaliwa gamit ang kamay, iunat nang diretso ang kaliwang braso at kamay palabas ng bintana, nakaturo sa kaliwa.","p":"Tama. Nakaunat na braso ay pagliko pakaliwa."},"ar":{"q":"كيف تعطي إشارة اليد للانعطاف إلى اليسار؟","o":["ارفع ذراعك اليسرى إلى الأعلى مع ثني المرفق","أنزل ذراعك اليسرى إلى الأسفل مع ثني المرفق","مُدّ ذراعك اليسرى مستقيمة خارج النافذة","حرّك ذراعك في دائرة"],"h1":"الذراع تشير إلى الاتجاه الذي ستذهب إليه.","h2":"لتعطي إشارة الانعطاف إلى اليسار باليد، مُدّ ذراعك اليسرى ويدك مستقيمة خارج النافذة، مشيرًا إلى اليسار.","p":"صحيح. الذراع الممدودة مستقيمة تعني الانعطاف إلى اليسار."},"ht":{"q":"Kijan pou w bay siyal ak men pou yon viraj agòch?","o":["Leve bra gòch ou anlè, pliye nan koud la","Bese bra gòch ou anba, pliye nan koud la","Lonje bra gòch ou tou dwat deyò fenèt la","Fè bra ou vire an won"],"h1":"Bra a montre kote w pral ale.","h2":"Pou w siyale yon viraj agòch ak men, lonje bra gòch ou ak men ou tou dwat deyò fenèt la, k ap montre bò gòch.","p":"Wi, se sa. Bra lonje tou dwat vle di viraj agòch."}},{"id":"right-of-way-075","scope":"US","cat":"right-of-way","sign":null,"c":3,"en":{"q":"A driver ahead holds the left arm out the window, bent down at the elbow. What does it mean?","o":["The driver is turning right","The driver is turning left","The driver wants you to pass","The driver is slowing down or stopping"],"h1":"The arm points toward the ground.","h2":"A left arm bent downward is the hand signal for slowing down or stopping.","p":"Right. Arm down means slow or stop."},"es":{"q":"Un conductor adelante saca el brazo izquierdo por la ventana, doblado hacia abajo. ¿Qué significa?","o":["Que va a girar a la derecha","Que va a girar a la izquierda","Que quiere que usted lo rebase","Que va a bajar la velocidad o pararse"],"h1":"El brazo apunta hacia el suelo.","h2":"El brazo izquierdo doblado hacia abajo es la señal de mano para bajar la velocidad o pararse.","p":"Correcto. Brazo hacia abajo significa bajar la velocidad o parar."},"zh":{"q":"前面的司机把左臂伸出窗外，肘部弯曲向下。这是什么意思？","o":["司机要右转","司机要左转","司机想让你超车","司机正在减速或停车"],"h1":"手臂指向地面。","h2":"左臂向下弯曲是表示减速或停车的手势。","p":"对。手臂向下表示减速或停车。"},"vi":{"q":"Người lái phía trước đưa tay trái ra ngoài cửa sổ, gập xuống ở khuỷu tay. Điều đó có nghĩa là gì?","o":["Người lái đang rẽ phải","Người lái đang rẽ trái","Người lái muốn bạn vượt qua","Người lái đang chạy chậm lại hoặc dừng lại"],"h1":"Cánh tay chỉ xuống đất.","h2":"Tay trái gập xuống dưới là tín hiệu tay cho biết đang chạy chậm lại hoặc dừng lại.","p":"Đúng. Tay chỉ xuống nghĩa là chạy chậm hoặc dừng lại."},"tl":{"q":"Inilabas ng drayber sa unahan ang kaliwang braso sa bintana, nakabaluktot pababa sa siko. Ano ang ibig sabihin nito?","o":["Liliko pakanan ang drayber","Liliko pakaliwa ang drayber","Gusto ng drayber na lampasan mo siya","Bumabagal o humihinto ang drayber"],"h1":"Nakaturo sa lupa ang braso.","h2":"Ang kaliwang brasong nakabaluktot pababa ay ang hand signal para sa pagbagal o paghinto.","p":"Tama. Brasong nakababa ay pagbagal o paghinto."},"ar":{"q":"السائق الذي أمامك يُخرج ذراعه اليسرى من النافذة، مثنية إلى الأسفل عند المرفق. ماذا يعني ذلك؟","o":["السائق سينعطف إلى اليمين","السائق سينعطف إلى اليسار","السائق يريدك أن تتجاوزه","السائق يبطئ أو يتوقف"],"h1":"الذراع تشير إلى الأرض.","h2":"الذراع اليسرى المثنية إلى الأسفل هي إشارة اليد للإبطاء أو التوقف.","p":"صحيح. الذراع إلى الأسفل تعني الإبطاء أو التوقف."},"ht":{"q":"Yon chofè devan w mete bra gòch li deyò fenèt la, pliye anba nan koud la. Kisa sa vle di?","o":["Chofè a pral vire adwat","Chofè a pral vire agòch","Chofè a vle ou pase l","Chofè a ap ralanti oswa l ap kanpe"],"h1":"Bra a montre atè.","h2":"Yon bra gòch ki pliye anba se siyal men pou ralanti oswa kanpe.","p":"Wi, se sa. Bra anba vle di ralanti oswa kanpe."}},{"id":"right-of-way-076","scope":"US","cat":"right-of-way","sign":null,"c":0,"en":{"q":"You are about to drive across a sidewalk to enter a street from a parking lot. A person is walking on the sidewalk. What should you do?","o":["Stop and let the person pass before you cross the sidewalk","Drive across slowly in front of them","Honk so they stop","Keep going; they will wait for you"],"h1":"People on the sidewalk come first.","h2":"Before you drive across a sidewalk, stop and let people on the sidewalk pass, because they have the right of way.","p":"Right. Let the person pass first."},"es":{"q":"Usted va a cruzar una acera para entrar a la calle desde un estacionamiento. Una persona camina por la acera. ¿Qué debe hacer?","o":["Pararse y dejar pasar a la persona antes de cruzar la acera","Cruzar despacio delante de ella","Tocar la bocina para que se pare","Seguir; ella lo esperará"],"h1":"Las personas en la acera van primero.","h2":"Antes de cruzar una acera con el carro, párese y deje pasar a las personas que van por ella, porque tienen el derecho de paso.","p":"Correcto. Deje pasar primero a la persona."},"zh":{"q":"你要从停车场开车穿过人行道进入街道。有人正在人行道上走路。你应该怎么做？","o":["停车，让这个人先走过去，然后再穿过人行道","在他前面慢慢开过去","按喇叭让他停下","继续开，他会等你"],"h1":"人行道上的人优先。","h2":"开车穿过人行道之前，要停车让人行道上的人先走过去，因为他们有优先通行权。","p":"对。让这个人先走过去。"},"vi":{"q":"Bạn sắp lái xe băng qua vỉa hè để từ bãi đậu xe đi vào đường. Có một người đang đi bộ trên vỉa hè. Bạn nên làm gì?","o":["Dừng lại và để người đó đi qua trước khi bạn băng qua vỉa hè","Lái chậm qua phía trước mặt họ","Bấm còi để họ dừng lại","Cứ đi tiếp; họ sẽ chờ bạn"],"h1":"Người đi trên vỉa hè được ưu tiên trước.","h2":"Trước khi lái xe băng qua vỉa hè, bạn phải dừng lại và để người đi trên vỉa hè đi qua, vì họ có quyền ưu tiên.","p":"Đúng. Hãy để người đó đi qua trước."},"tl":{"q":"Tatawid ka na sa bangketa gamit ang sasakyan para pumasok sa kalye mula sa paradahan. May taong naglalakad sa bangketa. Ano ang dapat mong gawin?","o":["Huminto at hayaang dumaan muna ang tao bago ka tumawid sa bangketa","Dumaan nang dahan-dahan sa harap niya","Bumusina para huminto siya","Tuloy lang; maghihintay siya sa iyo"],"h1":"Nauuna ang mga tao sa bangketa.","h2":"Bago ka tumawid sa bangketa gamit ang sasakyan, huminto at hayaang dumaan muna ang mga tao sa bangketa, dahil sila ang may karapatan sa daan.","p":"Tama. Hayaang dumaan muna ang tao."},"ar":{"q":"أنت على وشك أن تقطع الرصيف بالسيارة لتدخل الشارع من موقف سيارات. هناك شخص يمشي على الرصيف. ماذا يجب أن تفعل؟","o":["توقّف واترك الشخص يمر قبل أن تقطع الرصيف","مُرّ ببطء أمامه","استعمل البوق ليتوقف","تابع السير؛ سينتظرك هو"],"h1":"الناس على الرصيف لهم الأولوية.","h2":"قبل أن تقطع الرصيف بالسيارة، توقّف واترك الناس على الرصيف يمرون، لأن لهم حق المرور.","p":"صحيح. اترك الشخص يمر أولًا."},"ht":{"q":"Ou pral travèse yon twotwa ak machin nan pou antre nan lari a soti nan yon pakin. Gen yon moun k ap mache sou twotwa a. Kisa ou dwe fè?","o":["Kanpe epi kite moun nan pase anvan ou travèse twotwa a","Pase dousman devan l","Klaksonnen pou l kanpe","Kontinye; l ap tann ou"],"h1":"Moun ki sou twotwa a gen priyorite.","h2":"Anvan ou travèse yon twotwa ak machin, kanpe epi kite moun ki sou twotwa a pase, paske yo gen dwa pase anvan.","p":"Wi, se sa. Kite moun nan pase anvan."}},{"id":"right-of-way-077","scope":"US","cat":"right-of-way","sign":null,"c":1,"en":{"q":"A person is riding a horse along the side of the road. How should you pass?","o":["Honk so the horse moves over","Slow down, give plenty of room, and do not honk","Pass quickly so the horse is not scared for long","Flash your lights to warn the rider"],"h1":"Horses can be frightened by noise and speed.","h2":"When passing a horse and rider, slow down, leave plenty of room and avoid honking or revving, so the horse is not frightened.","p":"Right. Slow, wide and quiet."},"es":{"q":"Una persona va a caballo por la orilla de la vía. ¿Cómo debe rebasarla?","o":["Tocando la bocina para que el caballo se aparte","Bajando la velocidad, dejando mucho espacio y sin tocar la bocina","Pasando rápido para que el caballo no se asuste mucho tiempo","Haciendo cambio de luces para avisar al jinete"],"h1":"Los caballos se asustan con el ruido y la velocidad.","h2":"Al rebasar a una persona a caballo, baje la velocidad, deje mucho espacio y no toque la bocina ni acelere el motor, para no asustar al caballo.","p":"Correcto. Despacio, con espacio y en silencio."},"zh":{"q":"有人在路边骑马。你应该怎样超过他们？","o":["按喇叭让马让开","减速，留出足够的空间，不要按喇叭","快速超过，让马受惊的时间短一点","闪车灯提醒骑马的人"],"h1":"噪音和速度会让马受惊。","h2":"超过骑马的人时，要减速，留出足够的空间，不要按喇叭或猛踩油门，这样马就不会受惊。","p":"对。慢、宽、安静。"},"vi":{"q":"Có một người đang cưỡi ngựa dọc bên lề đường. Bạn nên vượt qua như thế nào?","o":["Bấm còi để con ngựa tránh sang bên","Chạy chậm lại, chừa nhiều khoảng trống và không bấm còi","Vượt thật nhanh để con ngựa không bị sợ lâu","Nháy đèn để báo cho người cưỡi ngựa"],"h1":"Ngựa có thể sợ vì tiếng ồn và tốc độ.","h2":"Khi vượt qua người cưỡi ngựa, hãy chạy chậm lại, chừa nhiều khoảng trống và tránh bấm còi hay rồ máy, để con ngựa không bị hoảng sợ.","p":"Đúng. Chậm, cách xa và yên lặng."},"tl":{"q":"May taong nakasakay sa kabayo sa gilid ng kalsada. Paano ka dapat lumampas?","o":["Bumusina para tumabi ang kabayo","Magdahan-dahan, magbigay ng maluwag na espasyo, at huwag bumusina","Lumampas nang mabilis para hindi matagal matakot ang kabayo","Kumislap ng ilaw para balaan ang sakay"],"h1":"Puwedeng matakot ang kabayo sa ingay at bilis.","h2":"Kapag lalampasan mo ang kabayo at ang sakay nito, magdahan-dahan, magbigay ng maluwag na espasyo, at iwasan ang pagbusina o pagpapaugong ng makina, para hindi matakot ang kabayo.","p":"Tama. Mabagal, malayo, at tahimik."},"ar":{"q":"شخص يركب حصانًا على جانب الطريق. كيف يجب أن تتجاوزه؟","o":["استعمل البوق ليبتعد الحصان","خفّف السرعة، واترك مسافة كبيرة، ولا تستعمل البوق","تجاوزه بسرعة حتى لا يبقى الحصان خائفًا مدة طويلة","ومّض بالأضواء لتنبيه الراكب"],"h1":"قد يخاف الحصان من الضجيج والسرعة.","h2":"عندما تتجاوز حصانًا وراكبه، خفّف السرعة واترك مسافة كبيرة وتجنّب البوق ورفع صوت المحرك، حتى لا يخاف الحصان.","p":"صحيح. ببطء، وبمسافة كبيرة، وبهدوء."},"ht":{"q":"Gen yon moun k ap monte chwal sou bò wout la. Kijan ou dwe pase l?","o":["Klaksonnen pou chwal la deplase","Ralanti, kite anpil espas, epi pa klaksonnen","Pase vit pou chwal la pa pè lontan","Flache limyè ou pou avèti moun ki sou chwal la"],"h1":"Bri ak vitès ka fè chwal pè.","h2":"Lè w ap pase yon chwal ak moun ki sou li, ralanti, kite anpil espas epi evite klaksonnen oswa fè motè a gwonde, pou chwal la pa pè.","p":"Wi, se sa. Dousman, lwen, epi san bri."}},{"id":"right-of-way-078","scope":"US","cat":"right-of-way","sign":null,"c":2,"en":{"q":"You are driving next to a row of parked cars where people ride bicycles. Why should you leave space between your car and the parked cars?","o":["Parked cars may roll into the road","You might want to park","A bicycle rider may swerve to avoid a car door that opens","It makes no difference"],"h1":"Car doors can open suddenly.","h2":"Bicycle riders near parked cars may swerve into your path to avoid an opening door, so give them extra space.","p":"Right. Riders may swerve to avoid a door."},"es":{"q":"Usted maneja junto a una fila de carros estacionados por donde pasan ciclistas. ¿Por qué debe dejar espacio entre su carro y los carros estacionados?","o":["Porque los carros estacionados pueden rodar a la vía","Porque quizás quiera estacionarse","Porque un ciclista puede desviarse para evitar una puerta que se abre","No hace ninguna diferencia"],"h1":"Las puertas de los carros pueden abrirse de repente.","h2":"Los ciclistas cerca de carros estacionados pueden desviarse hacia usted para evitar una puerta que se abre, así que deles espacio extra.","p":"Correcto. Pueden desviarse para evitar una puerta."},"zh":{"q":"你在一排停着的车旁边开车，这里有人骑自行车。为什么你的车和停着的车之间要留出空间？","o":["停着的车可能会滑到路上","你可能想停车","骑自行车的人可能会突然转向，躲开打开的车门","没有区别"],"h1":"车门可能会突然打开。","h2":"在停着的车旁边骑自行车的人，可能会为了躲开打开的车门而转到你的车前，所以要给他们留出更多空间。","p":"对。骑车的人可能会转向躲开车门。"},"vi":{"q":"Bạn đang lái xe cạnh một hàng xe đậu, nơi có người đi xe đạp. Tại sao bạn nên chừa khoảng cách giữa xe của bạn và các xe đang đậu?","o":["Xe đang đậu có thể lăn ra đường","Bạn có thể muốn đậu xe","Người đi xe đạp có thể bẻ lái đột ngột để tránh cửa xe mở ra","Không có gì khác biệt"],"h1":"Cửa xe có thể mở ra bất ngờ.","h2":"Người đi xe đạp gần các xe đang đậu có thể bẻ lái vào đường đi của bạn để tránh cửa xe mở ra, vì vậy hãy chừa thêm khoảng trống cho họ.","p":"Đúng. Người đi xe đạp có thể bẻ lái để tránh cửa xe."},"tl":{"q":"Nagmamaneho ka sa tabi ng hanay ng mga nakaparadang kotse kung saan may mga nagbibisikleta. Bakit dapat kang mag-iwan ng espasyo sa pagitan ng kotse mo at ng mga nakaparadang kotse?","o":["Baka gumulong papunta sa kalsada ang mga nakaparadang kotse","Baka gusto mong pumarada","Baka biglang lumihis ang nagbibisikleta para iwasan ang bumubukas na pinto ng kotse","Walang pagkakaiba"],"h1":"Puwedeng biglang bumukas ang pinto ng kotse.","h2":"Ang mga nagbibisikleta malapit sa mga nakaparadang kotse ay puwedeng lumihis papunta sa daraanan mo para iwasan ang bumubukas na pinto, kaya bigyan sila ng dagdag na espasyo.","p":"Tama. Puwedeng lumihis ang nagbibisikleta para iwasan ang pinto."},"ar":{"q":"أنت تقود بجانب صف من السيارات المتوقفة حيث يركب الناس الدراجات. لماذا يجب أن تترك مسافة بين سيارتك والسيارات المتوقفة؟","o":["قد تتدحرج السيارات المتوقفة إلى الطريق","قد ترغب في الوقوف","قد ينحرف راكب الدراجة فجأة ليتجنب باب سيارة يُفتح","لا فرق في ذلك"],"h1":"قد تُفتح أبواب السيارات فجأة.","h2":"قد ينحرف راكبو الدراجات قرب السيارات المتوقفة إلى طريقك ليتجنبوا بابًا يُفتح، لذلك اترك لهم مسافة إضافية.","p":"صحيح. قد ينحرف راكب الدراجة ليتجنب الباب."},"ht":{"q":"W ap kondi bò yon ranje machin ki pake, kote moun ap monte bisiklèt. Poukisa ou dwe kite espas ant machin ou ak machin ki pake yo?","o":["Machin ki pake yo ka woule antre nan wout la","Ou ka vle pake","Yon moun sou bisiklèt ka vire sanzatann pou evite yon pòt machin k ap louvri","Sa pa fè okenn diferans"],"h1":"Pòt machin ka louvri sanzatann.","h2":"Moun sou bisiklèt ki toupre machin ki pake yo ka vire antre nan chemen ou pou evite yon pòt k ap louvri, kidonk ba yo plis espas.","p":"Wi, se sa. Moun sou bisiklèt la ka vire pou evite pòt la."}},{"id":"right-of-way-079","scope":"FL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Florida, you come to an intersection with no signs or signals. You are on a dirt road about to enter a paved road. Who goes first?","o":["Traffic on the paved road","You, the driver on the dirt road","Whoever is bigger","Whoever honks first"],"h1":"The road surface decides it here.","h2":"At an open intersection, a driver coming from an unpaved road onto a paved road must yield the right-of-way.","p":"Right. Coming off an unpaved road, you yield to the paved road."},"es":{"q":"En Florida, llega a una intersección sin señales ni semáforos. Usted va por un camino de tierra y va a entrar a una calle pavimentada. ¿Quién pasa primero?","o":["El tráfico de la calle pavimentada","Usted, que viene del camino de tierra","El vehículo más grande","El que toque la bocina primero"],"h1":"Aquí lo decide el tipo de superficie.","h2":"En una intersección sin control, quien viene de un camino sin pavimentar hacia una calle pavimentada debe ceder el paso.","p":"Correcto. Si viene de un camino sin pavimentar, cede el paso a la calle pavimentada."},"ref":{"doc":"FL","page":62}},{"id":"right-of-way-080","scope":"FL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Florida, a city bus in a bus pullout bay signals to pull back into your lane. What must you do?","o":["Speed up to pass it first","Yield and let the bus back in","Honk so the bus waits","Change lanes without signaling"],"h1":"The law gives the bus the right-of-way here.","h2":"Florida drivers must yield to a public transit bus that has signaled and is pulling back into traffic from a marked pullout bay.","p":"Right. Let the bus pull back into traffic."},"es":{"q":"En Florida, un autobús de la ciudad que está en una bahía de parada pone la señal para volver a su carril. ¿Qué debe hacer?","o":["Acelerar para pasarlo primero","Ceder el paso y dejar entrar al autobús","Tocar la bocina para que espere","Cambiar de carril sin poner la señal"],"h1":"Aquí la ley le da el derecho de paso al autobús.","h2":"En Florida, los conductores deben ceder el paso a un autobús de transporte público que puso la señal y está volviendo al tráfico desde una bahía de parada marcada.","p":"Correcto. Deje que el autobús vuelva al tráfico."},"ref":{"doc":"FL","page":88}},{"id":"safe-driving-001","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think about a safe gap between your car and the rider.","h2":"Florida law says you must leave at least 3 feet between your car and a bicycle when you pass it.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Florida, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un espacio seguro entre su carro y el ciclista.","h2":"La ley de Florida dice que debe dejar al menos 3 pies entre su carro y una bicicleta cuando la rebasa.","p":"Correcto. Deje al menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 Florida，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"想一想你的车和骑车人之间安全的距离。","h2":"Florida 法律规定，你超过自行车时，你的车和自行车之间必须留出至少 3 英尺。","p":"对。超过自行车时，至少留出 3 英尺。"},"vi":{"q":"Ở Florida, khi vượt qua xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến một khoảng trống an toàn giữa xe bạn và người đi xe đạp.","h2":"Luật Florida nói rằng bạn phải chừa ít nhất 3 feet giữa xe bạn và xe đạp khi vượt qua.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet khi bạn vượt qua."},"tl":{"q":"Sa Florida, gaano kalaking espasyo ang dapat mong iwan kapag nag-overtake ka sa bisikleta?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Isipin ang ligtas na pagitan ng kotse mo at ng nagbibisikleta.","h2":"Sinasabi ng batas ng Florida na dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng bisikleta kapag nag-overtake ka rito.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag nag-overtake ka."},"ar":{"q":"في Florida، كم مسافة يجب أن تترك عندما تتجاوز دراجة هوائية؟","o":["قدم واحدة (1 foot) على الأقل","2 قدم (feet) على الأقل","3 أقدام (feet) على الأقل","10 أقدام (feet) على الأقل"],"h1":"فكّر في مسافة آمنة بين سيارتك وراكب الدراجة.","h2":"قانون Florida يقول إنه يجب أن تترك 3 أقدام (feet) على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها.","p":"صحيح. اترك للدراجة 3 أقدام (feet) على الأقل عندما تتجاوزها."},"ht":{"q":"Nan Florida, konbyen espas ou dwe kite lè w ap pase yon bisiklèt?","o":["Omwen 1 pye","Omwen 2 pye","Omwen 3 pye","Omwen 10 pye"],"h1":"Panse ak yon espas ki an sekirite ant machin ou ak moun ki sou bisiklèt la.","h2":"Lalwa Florida di ou dwe kite omwen 3 pye ant machin ou ak yon bisiklèt lè w ap pase l.","p":"Se sa. Bay yon bisiklèt omwen 3 pye lè w ap pase l."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-002","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you want to turn right. A bicycle is in the bike lane next to you. What should you do?","o":["Speed up and turn in front of it","Let the bicycle go by, then turn","Honk so the rider will stop","Turn from the left lane instead"],"h1":"Think about who is already moving straight in that lane.","h2":"The bicycle is going straight in its own lane, so you must let it pass before you turn right across the bike lane.","p":"Right. Let the bicycle go by first, then turn."},"es":{"q":"En Florida, usted quiere girar a la derecha. Hay una bicicleta en el carril de bicicletas a su lado. ¿Qué debe hacer?","o":["Acelerar y girar delante de ella","Dejar pasar la bicicleta y luego girar","Tocar la bocina para que pare","Girar desde el carril izquierdo"],"h1":"Piense en quién ya va derecho en ese carril.","h2":"La bicicleta va derecho en su propio carril, así que debe dejarla pasar antes de girar a la derecha y cruzar el carril de bicicletas.","p":"Correcto. Deje pasar la bicicleta primero y luego gire."},"zh":{"q":"在 Florida，你想右转。有一辆自行车在你旁边的自行车道上。你应该怎么做？","o":["加速，在它前面转弯","让自行车先过去，然后再转弯","按喇叭让骑车人停下","改从左边车道转弯"],"h1":"想一想谁已经在那条车道上直行。","h2":"自行车在自己的车道上直行，所以你必须让它先过去，然后再穿过自行车道右转。","p":"对。先让自行车过去，然后再转弯。"},"vi":{"q":"Ở Florida, bạn muốn rẽ phải. Có một xe đạp đang ở làn xe đạp cạnh bạn. Bạn nên làm gì?","o":["Tăng tốc và rẽ trước xe đạp","Để xe đạp đi qua, rồi mới rẽ","Bấm còi để người đi xe đạp dừng lại","Rẽ từ làn bên trái thay vào đó"],"h1":"Hãy nghĩ xem ai đang đi thẳng trong làn đó.","h2":"Xe đạp đang đi thẳng trong làn của nó, nên bạn phải để xe đạp đi qua trước khi rẽ phải cắt ngang làn xe đạp.","p":"Đúng. Để xe đạp đi qua trước, rồi mới rẽ."},"tl":{"q":"Sa Florida, gusto mong kumanan. May bisikleta sa bike lane sa tabi mo. Ano ang dapat mong gawin?","o":["Bumilis at kumanan sa harap nito","Hayaang dumaan muna ang bisikleta, saka kumanan","Bumusina para huminto ang nagbibisikleta","Kumanan na lang mula sa kaliwang lane"],"h1":"Isipin kung sino ang diretsong umaandar na sa lane na iyon.","h2":"Diretsong umaandar ang bisikleta sa sarili nitong lane, kaya dapat mo itong hayaang dumaan bago ka kumanan patawid sa bike lane.","p":"Tama. Hayaang dumaan muna ang bisikleta, saka kumanan."},"ar":{"q":"في Florida، تريد أن تنعطف يمينًا. توجد دراجة هوائية في مسار الدراجات بجانبك. ماذا يجب أن تفعل؟","o":["أسرع وانعطف أمامها","اترك الدراجة تمرّ، ثم انعطف","استعمل البوق حتى يتوقف راكب الدراجة","انعطف من المسار الأيسر بدلًا من ذلك"],"h1":"فكّر: من يسير إلى الأمام مباشرة في ذلك المسار الآن؟","h2":"الدراجة تسير إلى الأمام في مسارها، لذلك يجب أن تتركها تمرّ قبل أن تنعطف يمينًا وتقطع مسار الدراجات.","p":"صحيح. اترك الدراجة تمرّ أولًا، ثم انعطف."},"ht":{"q":"Nan Florida, ou vle vire adwat. Gen yon bisiklèt nan liy bisiklèt la bò kote w. Kisa ou ta dwe fè?","o":["Akselere epi vire devan l","Kite bisiklèt la pase, epi vire","Klaksonen pou moun nan kanpe","Vire soti nan liy goch la pito"],"h1":"Panse ak kiyès ki deja ap ale tou dwat nan liy sa a.","h2":"Bisiklèt la ap ale tou dwat nan pwòp liy pa l, kidonk ou dwe kite l pase anvan ou vire adwat travèse liy bisiklèt la.","p":"Se sa. Kite bisiklèt la pase anvan, epi vire."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-003","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you parked on a busy street. What should you do before you open your door on the traffic side?","o":["Open it fast so you are quick","Turn on your wipers first","Honk the horn one time","Look back for bikes and cars"],"h1":"Think about who might be coming up beside your car.","h2":"A door that opens suddenly can hit a cyclist or a car, so you must look back and wait until it is safe to open it.","p":"Right. Look back for bikes and cars before you open your door."},"es":{"q":"En Florida, usted se estacionó en una calle con mucho tráfico. ¿Qué debe hacer antes de abrir la puerta del lado del tráfico?","o":["Abrirla rápido para no tardar","Encender los limpiaparabrisas","Tocar la bocina una vez","Mirar atrás por bicicletas y carros"],"h1":"Piense en quién podría venir al lado de su carro.","h2":"Una puerta que se abre de repente puede golpear a un ciclista o a un carro, así que debe mirar atrás y esperar hasta que sea seguro abrirla.","p":"Correcto. Mire atrás por bicicletas y carros antes de abrir la puerta."},"zh":{"q":"在 Florida，你把车停在一条车很多的街上。打开靠车流一侧的车门前，你应该做什么？","o":["快速打开，节省时间","先打开雨刷","按一下喇叭","回头看有没有自行车和汽车"],"h1":"想一想谁可能正从你的车旁边过来。","h2":"突然打开的车门可能撞到骑自行车的人或汽车，所以你必须回头看，等到安全时再开门。","p":"对。开门前回头看有没有自行车和汽车。"},"vi":{"q":"Ở Florida, bạn đậu xe trên một con đường đông xe. Bạn nên làm gì trước khi mở cửa xe ở phía có xe chạy?","o":["Mở nhanh cho kịp","Bật cần gạt nước trước","Bấm còi một lần","Nhìn ra sau xem có xe đạp và xe hơi không"],"h1":"Hãy nghĩ xem ai có thể đang đến gần bên cạnh xe bạn.","h2":"Cửa xe mở đột ngột có thể đụng vào người đi xe đạp hoặc xe hơi, nên bạn phải nhìn ra sau và chờ đến khi an toàn mới mở cửa.","p":"Đúng. Nhìn ra sau xem có xe đạp và xe hơi không trước khi mở cửa."},"tl":{"q":"Sa Florida, nag-park ka sa mataong kalye. Ano ang dapat mong gawin bago buksan ang pinto mo sa gilid ng trapiko?","o":["Buksan ito nang mabilis para mabilis ka","I-on muna ang wipers mo","Bumusina nang isang beses","Lumingon sa likod para tingnan kung may bisikleta o kotse"],"h1":"Isipin kung sino ang puwedeng paparating sa tabi ng kotse mo.","h2":"Ang pintong biglang bumukas ay puwedeng tumama sa nagbibisikleta o sa kotse, kaya dapat kang lumingon sa likod at maghintay hanggang ligtas nang buksan ito.","p":"Tama. Lumingon sa likod para sa bisikleta at kotse bago buksan ang pinto mo."},"ar":{"q":"في Florida، أوقفت سيارتك في شارع مزدحم. ماذا يجب أن تفعل قبل أن تفتح بابك من جهة السير؟","o":["افتحه بسرعة حتى تنتهي بسرعة","شغّل المساحات أولًا","استعمل البوق مرة واحدة","انظر إلى الخلف لترى الدراجات والسيارات"],"h1":"فكّر: من قد يقترب بجانب سيارتك؟","h2":"الباب الذي يُفتح فجأة قد يضرب راكب دراجة أو سيارة، لذلك يجب أن تنظر إلى الخلف وتنتظر حتى يصبح فتحه آمنًا.","p":"صحيح. انظر إلى الخلف لترى الدراجات والسيارات قبل أن تفتح بابك."},"ht":{"q":"Nan Florida, ou pake nan yon lari ki gen anpil machin. Kisa ou ta dwe fè anvan ou louvri pòt ou bò kote machin yo ap pase a?","o":["Louvri l vit pou w fè vit","Limen wipè ou anvan","Klaksonen yon fwa","Gade dèyè pou bisiklèt ak machin"],"h1":"Panse ak kiyès ki ka ap vini bò kote machin ou.","h2":"Yon pòt ki louvri sanzatann ka frape yon moun sou bisiklèt oswa yon machin, kidonk ou dwe gade dèyè epi tann jiskaske li an sekirite pou w louvri l.","p":"Se sa. Gade dèyè pou bisiklèt ak machin anvan ou louvri pòt ou."},"ref":{"doc":"FL","page":81}},{"id":"safe-driving-004","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, a person is walking across the street in a crosswalk in front of you. What must you do?","o":["Stop and let the person cross","Drive slowly around the person","Honk so the person hurries","Keep going if you have a green light"],"h1":"Think about who has the right to use the crosswalk first.","h2":"A person in a crosswalk has the right of way, so you must stop and wait until the person has crossed.","p":"Right. Stop and let people in the crosswalk cross."},"es":{"q":"En Florida, una persona cruza la calle por el paso peatonal frente a usted. ¿Qué debe hacer?","o":["Parar y dejar que la persona cruce","Pasar despacio alrededor de la persona","Tocar la bocina para que se apure","Seguir si tiene luz verde"],"h1":"Piense en quién tiene primero el derecho de usar el paso peatonal.","h2":"Una persona en el paso peatonal tiene el derecho de paso, así que debe parar y esperar a que termine de cruzar.","p":"Correcto. Pare y deje cruzar a las personas en el paso peatonal."},"zh":{"q":"在 Florida，有一个人正在你前面的人行横道上过马路。你必须做什么？","o":["停车，让这个人过马路","慢慢绕过这个人","按喇叭让这个人快点走","如果是绿灯就继续开"],"h1":"想一想谁有权先使用人行横道。","h2":"在人行横道上的人有先行权，所以你必须停车，等这个人过完马路。","p":"对。停车，让人行横道上的人过马路。"},"vi":{"q":"Ở Florida, có một người đang đi bộ qua đường trên vạch qua đường trước mặt bạn. Bạn phải làm gì?","o":["Dừng lại và để người đó đi qua","Lái chậm vòng qua người đó","Bấm còi để người đó đi nhanh hơn","Cứ đi tiếp nếu bạn có đèn xanh"],"h1":"Hãy nghĩ xem ai có quyền dùng vạch qua đường trước.","h2":"Người đi trên vạch qua đường có quyền ưu tiên, nên bạn phải dừng lại và chờ đến khi người đó đi qua hết.","p":"Đúng. Dừng lại và để người trên vạch qua đường đi qua."},"tl":{"q":"Sa Florida, may taong tumatawid sa crosswalk sa harap mo. Ano ang dapat mong gawin?","o":["Huminto at hayaang tumawid ang tao","Dahan-dahang lumihis sa paligid ng tao","Bumusina para magmadali ang tao","Tumuloy kung green light ka"],"h1":"Isipin kung sino ang unang may karapatang gumamit ng crosswalk.","h2":"Ang taong nasa crosswalk ang may right of way, kaya dapat kang huminto at maghintay hanggang makatawid ang tao.","p":"Tama. Huminto at hayaang tumawid ang mga tao sa crosswalk."},"ar":{"q":"في Florida، شخص يعبر الشارع على ممر المشاة أمامك. ماذا يجب أن تفعل؟","o":["توقف واترك الشخص يعبر","قُد ببطء حول الشخص","استعمل البوق حتى يُسرع الشخص","تابع السير إذا كانت الإشارة خضراء لك"],"h1":"فكّر: من له الحق في استعمال ممر المشاة أولًا؟","h2":"الشخص الذي على ممر المشاة له حق الأولوية، لذلك يجب أن تتوقف وتنتظر حتى يعبر.","p":"صحيح. توقف واترك الناس على ممر المشاة يعبرون."},"ht":{"q":"Nan Florida, yon moun ap travèse lari a nan pasaj pyeton an devan w. Kisa ou dwe fè?","o":["Kanpe epi kite moun nan travèse","Kondi dousman bò kote moun nan","Klaksonen pou moun nan fè vit","Kontinye si limyè a vèt pou ou"],"h1":"Panse ak kiyès ki gen dwa sèvi ak pasaj pyeton an anvan.","h2":"Yon moun ki nan pasaj pyeton an gen priyorite, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse.","p":"Se sa. Kanpe epi kite moun ki nan pasaj pyeton an travèse."},"ref":{"doc":"FL","page":87}},{"id":"safe-driving-005","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a person with a white cane or a guide dog is starting to cross the street. What should you do?","o":["Honk to warn the person","Drive around the person slowly","Stop and wait until the person crosses","Wave the person back to the curb"],"h1":"Think about a person who may not be able to see your car.","h2":"A white cane or a guide dog shows that the person may be blind, so you must stop and wait until the person is safely across.","p":"Right. Stop for a person with a white cane or a guide dog."},"es":{"q":"En Florida, una persona con un bastón blanco o un perro guía empieza a cruzar la calle. ¿Qué debe hacer?","o":["Tocar la bocina para avisarle","Pasar despacio alrededor de la persona","Parar y esperar a que la persona cruce","Hacerle señas para que vuelva a la acera"],"h1":"Piense en una persona que tal vez no puede ver su carro.","h2":"Un bastón blanco o un perro guía indica que la persona puede ser ciega, así que debe parar y esperar a que cruce con seguridad.","p":"Correcto. Pare para una persona con bastón blanco o perro guía."},"zh":{"q":"在 Florida，一个拿着白色手杖或带着导盲犬的人正要过马路。你应该怎么做？","o":["按喇叭提醒这个人","慢慢绕过这个人","停车，等这个人过完马路","挥手让这个人回到路边"],"h1":"想一想一个可能看不到你车的人。","h2":"白色手杖或导盲犬表示这个人可能看不见，所以你必须停车，等这个人安全过完马路。","p":"对。为拿白色手杖或带导盲犬的人停车。"},"vi":{"q":"Ở Florida, một người cầm gậy trắng hoặc đi cùng chó dẫn đường đang bắt đầu qua đường. Bạn nên làm gì?","o":["Bấm còi để báo cho người đó","Lái chậm vòng qua người đó","Dừng lại và chờ đến khi người đó qua hết đường","Vẫy tay bảo người đó quay lại lề đường"],"h1":"Hãy nghĩ đến một người có thể không nhìn thấy xe bạn.","h2":"Gậy trắng hoặc chó dẫn đường cho thấy người đó có thể bị mù, nên bạn phải dừng lại và chờ đến khi người đó qua đường an toàn.","p":"Đúng. Dừng lại cho người cầm gậy trắng hoặc đi cùng chó dẫn đường."},"tl":{"q":"Sa Florida, ang taong may puting tungkod o guide dog ay nagsisimulang tumawid sa kalye. Ano ang dapat mong gawin?","o":["Bumusina para bigyan ng babala ang tao","Dahan-dahang lumihis sa paligid ng tao","Huminto at maghintay hanggang makatawid ang tao","Senyasan ang tao na bumalik sa gilid ng kalsada"],"h1":"Isipin ang taong maaaring hindi nakakakita sa kotse mo.","h2":"Ang puting tungkod o guide dog ay nagpapakitang maaaring bulag ang tao, kaya dapat kang huminto at maghintay hanggang ligtas na siyang nakatawid.","p":"Tama. Huminto para sa taong may puting tungkod o guide dog."},"ar":{"q":"في Florida، شخص معه عصا بيضاء أو كلب مرشد يبدأ بعبور الشارع. ماذا يجب أن تفعل؟","o":["استعمل البوق لتحذّر الشخص","قُد ببطء حول الشخص","توقف وانتظر حتى يعبر الشخص","أشِر إلى الشخص ليعود إلى الرصيف"],"h1":"فكّر في شخص قد لا يستطيع أن يرى سيارتك.","h2":"العصا البيضاء أو الكلب المرشد تدل على أن الشخص قد يكون كفيفًا، لذلك يجب أن تتوقف وتنتظر حتى يعبر بأمان.","p":"صحيح. توقف لشخص معه عصا بيضاء أو كلب مرشد."},"ht":{"q":"Nan Florida, yon moun ki gen yon baton blan oswa yon chen gid ap kòmanse travèse lari a. Kisa ou ta dwe fè?","o":["Klaksonen pou avèti moun nan","Kondi dousman bò kote moun nan","Kanpe epi tann jiskaske moun nan fin travèse","Fè moun nan siy pou l retounen sou twotwa a"],"h1":"Panse ak yon moun ki ka pa ka wè machin ou.","h2":"Yon baton blan oswa yon chen gid montre ke moun nan ka avèg, kidonk ou dwe kanpe epi tann jiskaske moun nan fin travèse san danje.","p":"Se sa. Kanpe pou yon moun ki gen yon baton blan oswa yon chen gid."},"ref":{"doc":"FL","page":88}},{"id":"safe-driving-006","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should you look twice for motorcycles before you turn or change lanes?","o":["Motorcycles must always use the right lane","Motorcycles are small and easy to miss","Motorcycles cannot use turn signals","Motorcycles always drive faster than cars"],"h1":"Think about how big a motorcycle looks next to a car.","h2":"A motorcycle is much smaller than a car, so it can hide in a blind spot or be easy to miss, and you should look twice.","p":"Right. Motorcycles are small and easy to miss, so look twice."},"es":{"q":"¿Por qué debe mirar dos veces por motocicletas antes de girar o cambiar de carril?","o":["Las motos siempre deben ir por la derecha","Las motos son pequeñas y fáciles de no ver","Las motos no pueden usar direccionales","Las motos siempre van más rápido que los carros"],"h1":"Piense en el tamaño de una moto al lado de un carro.","h2":"Una motocicleta es mucho más pequeña que un carro, así que puede esconderse en un punto ciego o pasar desapercibida, y debe mirar dos veces.","p":"Correcto. Las motos son pequeñas y fáciles de no ver; mire dos veces."},"zh":{"q":"为什么你在转弯或换车道前，应该看两次有没有摩托车？","o":["摩托车必须一直走右边车道","摩托车很小，很容易看漏","摩托车不能用转向灯","摩托车总是比汽车开得快"],"h1":"想一想摩托车在汽车旁边看起来有多大。","h2":"摩托车比汽车小很多，所以它可能藏在盲区里，或很容易被看漏，你应该看两次。","p":"对。摩托车很小，很容易看漏，所以要看两次。"},"vi":{"q":"Tại sao bạn nên nhìn hai lần để tìm xe máy trước khi rẽ hoặc đổi làn?","o":["Xe máy luôn phải đi làn bên phải","Xe máy nhỏ và dễ bị bỏ sót","Xe máy không thể dùng đèn xi-nhan","Xe máy luôn chạy nhanh hơn xe hơi"],"h1":"Hãy nghĩ xem một chiếc xe máy trông lớn cỡ nào khi ở cạnh xe hơi.","h2":"Xe máy nhỏ hơn xe hơi rất nhiều, nên nó có thể bị che trong điểm mù hoặc dễ bị bỏ sót, và bạn nên nhìn hai lần.","p":"Đúng. Xe máy nhỏ và dễ bị bỏ sót, nên hãy nhìn hai lần."},"tl":{"q":"Bakit dapat kang tumingin nang dalawang beses para sa motorsiklo bago kumanan o kumaliwa, o lumipat ng lane?","o":["Dapat laging gumamit ng kanang lane ang mga motorsiklo","Maliit ang mga motorsiklo at madaling hindi mapansin","Hindi puwedeng gumamit ng signal light ang mga motorsiklo","Laging mas mabilis ang mga motorsiklo kaysa sa mga kotse"],"h1":"Isipin kung gaano kalaki ang tingin sa motorsiklo kapag katabi ng kotse.","h2":"Mas maliit nang husto ang motorsiklo kaysa sa kotse, kaya puwede itong matago sa blind spot o madaling hindi mapansin, at dapat kang tumingin nang dalawang beses.","p":"Tama. Maliit ang mga motorsiklo at madaling hindi mapansin, kaya tumingin nang dalawang beses."},"ar":{"q":"لماذا يجب أن تنظر مرتين بحثًا عن الدراجات النارية قبل أن تنعطف أو تغيّر المسار؟","o":["الدراجات النارية يجب أن تستعمل المسار الأيمن دائمًا","الدراجات النارية صغيرة ومن السهل ألا تراها","الدراجات النارية لا تستطيع استعمال إشارات الانعطاف","الدراجات النارية تسير دائمًا أسرع من السيارات"],"h1":"فكّر في حجم الدراجة النارية بجانب السيارة.","h2":"الدراجة النارية أصغر بكثير من السيارة، لذلك قد تختفي في النقطة العمياء أو من السهل ألا تراها، ويجب أن تنظر مرتين.","p":"صحيح. الدراجات النارية صغيرة ومن السهل ألا تراها، لذلك انظر مرتين."},"ht":{"q":"Poukisa ou ta dwe gade de fwa pou motosiklèt anvan ou vire oswa chanje liy?","o":["Motosiklèt yo dwe toujou sèvi ak liy dwat la","Motosiklèt yo piti epi li fasil pou w pa wè yo","Motosiklèt yo pa ka sèvi ak siyal pou vire","Motosiklèt yo toujou kondi pi vit pase machin"],"h1":"Panse ak gwosè yon motosiklèt bò kote yon machin.","h2":"Yon motosiklèt pi piti anpil pase yon machin, kidonk li ka kache nan yon kote ou pa ka wè (blind spot) oswa li fasil pou w pa wè l, epi ou ta dwe gade de fwa.","p":"Se sa. Motosiklèt yo piti epi li fasil pou w pa wè yo, kidonk gade de fwa."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-007","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, may you share a lane side by side with a motorcycle?","o":["Yes, if the motorcycle is slow","Yes, on any multi-lane road","Yes, if you signal first","No, a motorcycle gets the full lane"],"h1":"Think about how much room a motorcycle needs to move safely.","h2":"In Florida a motorcycle has the right to use the full width of a lane, so you may not drive next to it in the same lane.","p":"Right. A motorcycle gets the full lane, so do not share it."},"es":{"q":"En Florida, ¿puede compartir un carril lado a lado con una motocicleta?","o":["Sí, si la moto va despacio","Sí, en cualquier vía de varios carriles","Sí, si pone la direccional antes","No, la moto tiene derecho a todo el carril"],"h1":"Piense en cuánto espacio necesita una moto para moverse con seguridad.","h2":"En Florida una motocicleta tiene derecho a usar todo el ancho del carril, así que usted no puede manejar a su lado en el mismo carril.","p":"Correcto. La moto tiene derecho a todo el carril; no lo comparta."},"zh":{"q":"在 Florida，你可以和摩托车在同一条车道上并排行驶吗？","o":["可以，如果摩托车开得慢","可以，在任何多车道的路上","可以，如果你先打转向灯","不可以，摩托车可以使用整条车道"],"h1":"想一想摩托车需要多少空间才能安全行驶。","h2":"在 Florida，摩托车有权使用整条车道的宽度，所以你不能在同一条车道上开在它旁边。","p":"对。摩托车可以使用整条车道，所以不要和它共用。"},"vi":{"q":"Ở Florida, bạn có được chạy song song với xe máy trong cùng một làn không?","o":["Có, nếu xe máy chạy chậm","Có, trên bất kỳ đường nhiều làn nào","Có, nếu bạn bật xi-nhan trước","Không, xe máy được dùng trọn cả làn"],"h1":"Hãy nghĩ xem xe máy cần bao nhiêu chỗ để di chuyển an toàn.","h2":"Ở Florida, xe máy có quyền dùng toàn bộ chiều rộng của một làn, nên bạn không được chạy cạnh xe máy trong cùng một làn.","p":"Đúng. Xe máy được dùng trọn cả làn, nên đừng chạy chung làn."},"tl":{"q":"Sa Florida, puwede ka bang makihati ng lane nang magkatabi sa isang motorsiklo?","o":["Oo, kung mabagal ang motorsiklo","Oo, sa kahit anong daan na maraming lane","Oo, kung mag-signal ka muna","Hindi, sa motorsiklo ang buong lane"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng motorsiklo para umandar nang ligtas.","h2":"Sa Florida, may karapatan ang motorsiklo na gamitin ang buong lapad ng lane, kaya hindi ka puwedeng magmaneho sa tabi nito sa parehong lane.","p":"Tama. Sa motorsiklo ang buong lane, kaya huwag makihati rito."},"ar":{"q":"في Florida، هل يُسمح لك بأن تسير جنبًا إلى جنب مع دراجة نارية في نفس المسار؟","o":["نعم، إذا كانت الدراجة النارية بطيئة","نعم، على أي طريق فيه عدة مسارات","نعم، إذا استعملت الإشارة أولًا","لا، الدراجة النارية لها المسار كله"],"h1":"فكّر في المساحة التي تحتاجها الدراجة النارية لتتحرك بأمان.","h2":"في Florida، للدراجة النارية الحق في استعمال عرض المسار كله، لذلك لا يُسمح لك بالقيادة بجانبها في نفس المسار.","p":"صحيح. الدراجة النارية لها المسار كله، فلا تشاركها فيه."},"ht":{"q":"Nan Florida, èske ou ka pataje yon liy ak yon motosiklèt, kòt a kòt?","o":["Wi, si motosiklèt la ap mache dousman","Wi, sou nenpòt wout ki gen plizyè liy","Wi, si ou bay siyal anvan","Non, yon motosiklèt gen dwa sou tout liy lan"],"h1":"Panse ak konbyen espas yon motosiklèt bezwen pou l deplase san danje.","h2":"Nan Florida, yon motosiklèt gen dwa sèvi ak tout lajè yon liy, kidonk ou pa gen dwa kondi bò kote l nan menm liy lan.","p":"Se sa. Yon motosiklèt gen dwa sou tout liy lan, kidonk pa pataje l."},"ref":{"doc":"FL","page":85}},{"id":"safe-driving-008","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving next to a large truck. You cannot see the driver's face in the truck's side mirror. What does this mean?","o":["The driver probably cannot see you","The driver is not paying attention","The mirror is broken","You are at a safe distance"],"h1":"Think about how mirrors work in both directions.","h2":"If you cannot see the truck driver in the mirror, the driver cannot see you either, so you are in a blind spot and should move out of it.","p":"Right. If you cannot see the driver in the mirror, the driver cannot see you."},"es":{"q":"Usted maneja al lado de un camión grande. No puede ver la cara del chofer en el espejo lateral del camión. ¿Qué significa?","o":["El chofer probablemente no lo ve a usted","El chofer no está prestando atención","El espejo está roto","Usted está a una distancia segura"],"h1":"Piense en cómo funcionan los espejos en las dos direcciones.","h2":"Si usted no ve al chofer en el espejo, el chofer tampoco lo ve a usted, así que está en un punto ciego y debe salir de ahí.","p":"Correcto. Si no ve al chofer en el espejo, él no lo ve a usted."},"zh":{"q":"你开在一辆大卡车旁边。你在卡车的侧后视镜里看不到司机的脸。这是什么意思？","o":["司机很可能看不到你","司机没有注意","后视镜坏了","你在安全的距离"],"h1":"想一想镜子是两个方向都能看到的。","h2":"如果你在镜子里看不到卡车司机，司机也看不到你，所以你在盲区里，应该离开那里。","p":"对。如果你在镜子里看不到司机，司机也看不到你。"},"vi":{"q":"Bạn đang lái xe cạnh một xe tải lớn. Bạn không nhìn thấy mặt tài xế trong gương chiếu hậu bên hông của xe tải. Điều này có nghĩa là gì?","o":["Có lẽ tài xế không nhìn thấy bạn","Tài xế không chú ý","Gương bị hỏng","Bạn đang ở khoảng cách an toàn"],"h1":"Hãy nghĩ xem gương hoạt động theo cả hai chiều như thế nào.","h2":"Nếu bạn không nhìn thấy tài xế xe tải trong gương, thì tài xế cũng không nhìn thấy bạn, nên bạn đang ở điểm mù và nên ra khỏi đó.","p":"Đúng. Nếu bạn không thấy tài xế trong gương, tài xế cũng không thấy bạn."},"tl":{"q":"Nagmamaneho ka sa tabi ng malaking truck. Hindi mo makita ang mukha ng driver sa side mirror ng truck. Ano ang ibig sabihin nito?","o":["Malamang hindi ka rin nakikita ng driver","Hindi nag-iingat ang driver","Sira ang salamin","Nasa ligtas na layo ka"],"h1":"Isipin kung paano gumagana ang salamin sa magkabilang direksyon.","h2":"Kung hindi mo makita ang truck driver sa salamin, hindi ka rin niya nakikita, kaya nasa blind spot ka at dapat kang umalis doon.","p":"Tama. Kung hindi mo makita ang driver sa salamin, hindi ka rin nakikita ng driver."},"ar":{"q":"أنت تقود بجانب شاحنة كبيرة. لا تستطيع أن ترى وجه السائق في المرآة الجانبية للشاحنة. ماذا يعني هذا؟","o":["السائق على الأغلب لا يستطيع أن يراك","السائق لا ينتبه","المرآة مكسورة","أنت على مسافة آمنة"],"h1":"فكّر في أن المرايا تعمل في الاتجاهين.","h2":"إذا لم تستطع أن ترى سائق الشاحنة في المرآة، فالسائق أيضًا لا يستطيع أن يراك، لذلك أنت في النقطة العمياء ويجب أن تخرج منها.","p":"صحيح. إذا لم ترَ السائق في المرآة، فالسائق لا يراك."},"ht":{"q":"W ap kondi bò kote yon gwo kamyon. Ou pa ka wè figi chofè a nan retwovizè bò kamyon an. Kisa sa vle di?","o":["Chofè a pwobableman pa ka wè w","Chofè a pa fè atansyon","Retwovizè a kase","Ou nan yon distans ki an sekirite"],"h1":"Panse ak jan retwovizè yo mache nan de direksyon.","h2":"Si ou pa ka wè chofè kamyon an nan retwovizè a, chofè a pa ka wè w nonplis, kidonk ou nan yon kote li pa ka wè (blind spot) epi ou ta dwe soti la.","p":"Se sa. Si ou pa ka wè chofè a nan retwovizè a, chofè a pa ka wè w."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-009","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"A large truck ahead has its right turn signal on. It moves a little to the left first. What should you do?","o":["Pass it on the right side","Honk to tell the driver to hurry","Stay back and wait for it to turn","Move up close behind the truck"],"h1":"Think about how much room a long truck needs to turn a corner.","h2":"Large trucks often swing left to make a wide right turn, so you should stay back and never squeeze in between the truck and the curb.","p":"Right. Stay back and let the truck make its wide right turn."},"es":{"q":"Un camión grande adelante tiene puesta la direccional derecha. Primero se mueve un poco a la izquierda. ¿Qué debe hacer?","o":["Rebasarlo por el lado derecho","Tocar la bocina para que se apure","Quedarse atrás y esperar a que gire","Acercarse mucho detrás del camión"],"h1":"Piense en cuánto espacio necesita un camión largo para doblar una esquina.","h2":"Los camiones grandes a menudo se abren a la izquierda para hacer un giro amplio a la derecha, así que debe quedarse atrás y nunca meterse entre el camión y la acera.","p":"Correcto. Quédese atrás y deje que el camión haga su giro amplio."},"zh":{"q":"前面一辆大卡车打开了右转向灯。它先稍微往左移动。你应该怎么做？","o":["从它右边超过去","按喇叭让司机快点","留在后面，等它转弯","开到卡车后面很近的地方"],"h1":"想一想长卡车转过一个路口需要多少空间。","h2":"大卡车常常先往左摆，才能大弯右转，所以你应该留在后面，绝不要挤进卡车和路边之间。","p":"对。留在后面，让卡车大弯右转。"},"vi":{"q":"Một xe tải lớn phía trước đang bật xi-nhan phải. Nó lấn sang trái một chút trước. Bạn nên làm gì?","o":["Vượt qua nó ở bên phải","Bấm còi giục tài xế nhanh lên","Lùi lại phía sau và chờ nó rẽ","Chạy sát lên phía sau xe tải"],"h1":"Hãy nghĩ xem một xe tải dài cần bao nhiêu chỗ để rẽ ở góc đường.","h2":"Xe tải lớn thường lấn sang trái để rẽ phải một vòng rộng, nên bạn nên lùi lại phía sau và không bao giờ chen vào giữa xe tải và lề đường.","p":"Đúng. Lùi lại phía sau và để xe tải rẽ phải một vòng rộng."},"tl":{"q":"Ang malaking truck sa unahan ay naka-signal pakanan. Kumikilos muna ito nang kaunti pakaliwa. Ano ang dapat mong gawin?","o":["Lampasan ito sa kanang bahagi","Bumusina para magmadali ang driver","Manatili sa likod at hintayin itong kumanan","Lumapit nang husto sa likod ng truck"],"h1":"Isipin kung gaano kalaking espasyo ang kailangan ng mahabang truck para lumiko sa kanto.","h2":"Madalas lumihis pakaliwa ang malalaking truck para makagawa ng malapad na pagkanan, kaya dapat kang manatili sa likod at huwag kailanman sumingit sa pagitan ng truck at ng gilid ng kalsada.","p":"Tama. Manatili sa likod at hayaang gawin ng truck ang malapad nitong pagkanan."},"ar":{"q":"شاحنة كبيرة أمامك شغّلت إشارة الانعطاف اليمنى. لكنها تتحرك قليلًا إلى اليسار أولًا. ماذا يجب أن تفعل؟","o":["تجاوزها من الجهة اليمنى","استعمل البوق لتقول للسائق أن يُسرع","ابقَ في الخلف وانتظر حتى تنعطف","اقترب كثيرًا خلف الشاحنة"],"h1":"فكّر في المساحة التي تحتاجها شاحنة طويلة لتنعطف عند الزاوية.","h2":"الشاحنات الكبيرة تميل غالبًا إلى اليسار لتنعطف يمينًا انعطافًا واسعًا، لذلك يجب أن تبقى في الخلف ولا تدخل أبدًا بين الشاحنة والرصيف.","p":"صحيح. ابقَ في الخلف واترك الشاحنة تنعطف يمينًا انعطافها الواسع."},"ht":{"q":"Yon gwo kamyon devan w limen siyal pou vire adwat. Li deplase yon ti kras agoch anvan. Kisa ou ta dwe fè?","o":["Pase l sou bò dwat la","Klaksonen pou di chofè a fè vit","Rete dèyè epi tann li vire","Vin kole dèyè kamyon an"],"h1":"Panse ak konbyen espas yon kamyon long bezwen pou l vire nan yon kwen.","h2":"Gwo kamyon yo souvan ale agoch pou yo ka fè yon gwo vire adwat, kidonk ou ta dwe rete dèyè epi pa janm foure kò w ant kamyon an ak bò twotwa a.","p":"Se sa. Rete dèyè epi kite kamyon an fè gwo vire adwat li."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-010","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You just passed a large truck. When should you move back in front of it?","o":["Right away, as soon as you pass its bumper","When you can see the whole truck front in your mirror","After you slow down a little","Only after the truck flashes its lights"],"h1":"Think about how long it takes a heavy truck to stop.","h2":"A heavy truck needs a long distance to stop, so you should wait until you can see its whole front in your rearview mirror before you move in.","p":"Right. Move in only when you can see the whole truck front in your mirror."},"es":{"q":"Usted acaba de rebasar un camión grande. ¿Cuándo debe volver a ponerse delante de él?","o":["De inmediato, al pasar su parachoques","Cuando vea todo el frente del camión en su espejo","Después de bajar un poco la velocidad","Solo cuando el camión le haga cambio de luces"],"h1":"Piense en cuánto le toma a un camión pesado frenar.","h2":"Un camión pesado necesita mucha distancia para frenar, así que debe esperar hasta ver todo su frente en el espejo retrovisor antes de ponerse delante.","p":"Correcto. Póngase delante solo cuando vea todo el frente del camión en el espejo."},"zh":{"q":"你刚超过一辆大卡车。什么时候可以回到它前面？","o":["马上，一超过它的保险杠就回去","当你在后视镜里能看到整个卡车车头时","在你稍微减速以后","只在卡车闪灯以后"],"h1":"想一想重型卡车需要多久才能停下来。","h2":"重型卡车需要很长的距离才能停下来，所以你应该等到在车内后视镜里能看到它整个车头，再回到它前面。","p":"对。只有在后视镜里能看到整个卡车车头时才回到前面。"},"vi":{"q":"Bạn vừa vượt qua một xe tải lớn. Khi nào bạn nên quay lại làn phía trước nó?","o":["Ngay lập tức, khi vừa qua khỏi cản xe của nó","Khi bạn nhìn thấy toàn bộ đầu xe tải trong gương","Sau khi bạn giảm tốc một chút","Chỉ sau khi xe tải nháy đèn"],"h1":"Hãy nghĩ xem một xe tải nặng cần bao lâu để dừng lại.","h2":"Xe tải nặng cần một quãng đường dài để dừng lại, nên bạn nên chờ đến khi nhìn thấy toàn bộ đầu xe tải trong gương chiếu hậu rồi mới quay vào làn.","p":"Đúng. Chỉ quay vào làn khi bạn nhìn thấy toàn bộ đầu xe tải trong gương."},"tl":{"q":"Kalalampas mo lang sa isang malaking truck. Kailan ka dapat bumalik sa harap nito?","o":["Agad-agad, pagkalampas mo sa bumper nito","Kapag nakikita mo na ang buong harap ng truck sa salamin mo","Pagkatapos mong bumagal nang kaunti","Pagkatapos lang mag-flash ng ilaw ang truck"],"h1":"Isipin kung gaano katagal bago makahinto ang mabigat na truck.","h2":"Kailangan ng mabigat na truck ng mahabang distansya para huminto, kaya dapat kang maghintay hanggang makita mo ang buong harap nito sa iyong rearview mirror bago ka bumalik sa lane.","p":"Tama. Bumalik lang sa lane kapag nakikita mo na ang buong harap ng truck sa salamin mo."},"ar":{"q":"تجاوزت شاحنة كبيرة الآن. متى يجب أن تعود إلى المسار أمامها؟","o":["فورًا، بمجرد أن تتجاوز مقدمتها","عندما ترى مقدمة الشاحنة كلها في مرآتك","بعد أن تخفف سرعتك قليلًا","فقط بعد أن تومض الشاحنة بأضوائها"],"h1":"فكّر في الوقت الذي تحتاجه الشاحنة الثقيلة لتتوقف.","h2":"الشاحنة الثقيلة تحتاج إلى مسافة طويلة لتتوقف، لذلك يجب أن تنتظر حتى ترى مقدمتها كلها في المرآة الداخلية قبل أن تدخل أمامها.","p":"صحيح. ادخل أمامها فقط عندما ترى مقدمة الشاحنة كلها في مرآتك."},"ht":{"q":"Ou fèk pase yon gwo kamyon. Ki lè ou ta dwe retounen devan l?","o":["Touswit, depi ou pase defans li","Lè ou ka wè tout devan kamyon an nan retwovizè ou","Apre ou ralanti yon ti kras","Sèlman apre kamyon an limen limyè li plizyè fwa"],"h1":"Panse ak konbyen tan yon kamyon lou pran pou l kanpe.","h2":"Yon kamyon lou bezwen yon long distans pou l kanpe, kidonk ou ta dwe tann jiskaske ou ka wè tout devan l nan retwovizè mitan an anvan ou retounen devan l.","p":"Se sa. Retounen devan l sèlman lè ou ka wè tout devan kamyon an nan retwovizè ou."},"ref":{"doc":"FL","page":83}},{"id":"safe-driving-011","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a school bus on a two-lane road stops. Its red lights flash and its stop arm is out. You are coming from the other direction. What must you do?","o":["Slow down and pass with care","Keep going because you are on the other side","Honk and then pass slowly","Stop and wait until the stop arm is pulled in"],"h1":"Think about children who may cross the road to reach the bus.","h2":"On a road without a divider, drivers in both directions must stop for a school bus with its stop arm out, and wait until the arm is pulled back in.","p":"Right. Stop for the school bus, even from the other direction."},"es":{"q":"En Florida, un autobús escolar para en una carretera de dos carriles. Sus luces rojas parpadean y tiene el brazo de pare afuera. Usted viene en dirección contraria. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir porque va del otro lado","Tocar la bocina y pasar despacio","Parar y esperar a que recojan el brazo de pare"],"h1":"Piense en los niños que pueden cruzar la calle para llegar al autobús.","h2":"En una vía sin división, los conductores de las dos direcciones deben parar ante un autobús escolar con el brazo de pare afuera, y esperar hasta que lo recojan.","p":"Correcto. Pare ante el autobús escolar, aunque venga en dirección contraria."},"zh":{"q":"在 Florida，一辆校车在双车道的路上停下。它的红灯在闪，停车臂也伸出来了。你从对面方向开过来。你必须做什么？","o":["减速，小心地开过去","继续开，因为你在另一边","按喇叭，然后慢慢开过去","停车，等到停车臂收回去"],"h1":"想一想孩子们可能会过马路去坐校车。","h2":"在没有隔离带的路上，两个方向的司机都必须为伸出停车臂的校车停车，并等到停车臂收回去。","p":"对。即使你从对面方向来，也要为校车停车。"},"vi":{"q":"Ở Florida, một xe buýt trường học dừng lại trên đường hai làn. Đèn đỏ nhấp nháy và tay chắn STOP đang mở ra. Bạn đang đi từ hướng ngược lại. Bạn phải làm gì?","o":["Giảm tốc và cẩn thận vượt qua","Cứ đi tiếp vì bạn ở phía bên kia","Bấm còi rồi chạy chậm qua","Dừng lại và chờ đến khi tay chắn STOP được thu vào"],"h1":"Hãy nghĩ đến trẻ em có thể băng qua đường để lên xe buýt.","h2":"Trên đường không có dải phân cách, tài xế ở cả hai chiều phải dừng lại khi xe buýt trường học mở tay chắn STOP, và chờ đến khi tay chắn được thu vào.","p":"Đúng. Dừng lại cho xe buýt trường học, dù bạn đi từ hướng ngược lại."},"tl":{"q":"Sa Florida, huminto ang school bus sa daang may dalawang lane. Kumikislap ang pulang ilaw nito at nakalabas ang stop arm. Galing ka sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Bumagal at lumampas nang maingat","Tumuloy dahil nasa kabilang bahagi ka","Bumusina at saka lumampas nang dahan-dahan","Huminto at maghintay hanggang maibalik ang stop arm"],"h1":"Isipin ang mga batang maaaring tumawid sa daan para makarating sa bus.","h2":"Sa daang walang divider, dapat huminto ang mga driver sa magkabilang direksyon para sa school bus na nakalabas ang stop arm, at maghintay hanggang maibalik ang arm.","p":"Tama. Huminto para sa school bus, kahit galing ka sa kabilang direksyon."},"ar":{"q":"في Florida، حافلة مدرسية تتوقف على طريق فيه مساران. أضواؤها الحمراء تومض وذراع التوقف مفتوح. أنت قادم من الاتجاه الآخر. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتجاوزها بحذر","تابع السير لأنك في الجهة الأخرى","استعمل البوق ثم تجاوز ببطء","توقف وانتظر حتى يُغلق ذراع التوقف"],"h1":"فكّر في الأطفال الذين قد يعبرون الطريق ليصلوا إلى الحافلة.","h2":"على طريق بدون فاصل، يجب على السائقين في الاتجاهين أن يتوقفوا للحافلة المدرسية عندما يكون ذراع التوقف مفتوحًا، وأن ينتظروا حتى يُغلق الذراع.","p":"صحيح. توقف للحافلة المدرسية، حتى إذا كنت في الاتجاه الآخر."},"ht":{"q":"Nan Florida, yon bis lekòl kanpe sou yon wout ki gen de liy. Limyè wouj li yo ap flache epi bra STOP li a louvri. W ap vini nan lòt direksyon an. Kisa ou dwe fè?","o":["Ralanti epi pase ak prekosyon","Kontinye paske ou sou lòt bò a","Klaksonen epi pase dousman","Kanpe epi tann jiskaske yo rantre bra STOP la"],"h1":"Panse ak timoun ki ka travèse wout la pou yo rive nan bis la.","h2":"Sou yon wout ki pa gen separasyon nan mitan, chofè nan tou de direksyon yo dwe kanpe pou yon bis lekòl ki gen bra STOP li louvri, epi tann jiskaske yo rantre bra a.","p":"Se sa. Kanpe pou bis lekòl la, menm si w ap vini nan lòt direksyon an."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-012","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you are on a divided highway with a raised median. A school bus stops on the other side of the median. What should you do?","o":["You do not have to stop, but drive with care","Stop until the bus drives away","Stop, then pass at walking speed","Change to the lane closest to the bus"],"h1":"Think about what the raised median does between you and the bus.","h2":"When a raised barrier or wide median separates you from the bus, you do not have to stop, but you should still watch for children.","p":"Right. With a raised median between you, you do not have to stop, but stay alert."},"es":{"q":"En Florida, usted va por una carretera dividida con una mediana elevada. Un autobús escolar para del otro lado de la mediana. ¿Qué debe hacer?","o":["No tiene que parar, pero maneje con cuidado","Parar hasta que el autobús se vaya","Parar y luego pasar muy despacio","Cambiarse al carril más cerca del autobús"],"h1":"Piense en lo que hace la mediana elevada entre usted y el autobús.","h2":"Cuando una barrera elevada o una mediana ancha lo separa del autobús, no tiene que parar, pero debe seguir atento a los niños.","p":"Correcto. Con una mediana elevada entre ustedes, no tiene que parar, pero esté atento."},"zh":{"q":"在 Florida，你在一条有凸起中央隔离带的分隔公路上。一辆校车在隔离带的另一边停下。你应该怎么做？","o":["你不必停车，但要小心开","停车，直到校车开走","停车，然后用走路的速度开过去","换到离校车最近的车道"],"h1":"想一想凸起的隔离带在你和校车之间起了什么作用。","h2":"当凸起的护栏或很宽的中央隔离带把你和校车分开时，你不必停车，但仍然要注意孩子。","p":"对。你们之间有凸起的隔离带时，你不必停车，但要保持警觉。"},"vi":{"q":"Ở Florida, bạn đang đi trên xa lộ có dải phân cách nhô cao ở giữa. Một xe buýt trường học dừng lại ở phía bên kia dải phân cách. Bạn nên làm gì?","o":["Bạn không phải dừng lại, nhưng hãy lái cẩn thận","Dừng lại đến khi xe buýt chạy đi","Dừng lại, rồi vượt qua với tốc độ đi bộ","Chuyển sang làn gần xe buýt nhất"],"h1":"Hãy nghĩ xem dải phân cách nhô cao có tác dụng gì giữa bạn và xe buýt.","h2":"Khi có rào chắn nhô cao hoặc dải phân cách rộng ngăn cách bạn với xe buýt, bạn không phải dừng lại, nhưng vẫn nên để ý trẻ em.","p":"Đúng. Khi có dải phân cách nhô cao ở giữa, bạn không phải dừng lại, nhưng hãy luôn cảnh giác."},"tl":{"q":"Sa Florida, nasa divided highway ka na may nakataas na median. Huminto ang school bus sa kabilang bahagi ng median. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero magmaneho nang maingat","Huminto hanggang umalis ang bus","Huminto, saka lumampas sa bilis ng paglalakad","Lumipat sa lane na pinakamalapit sa bus"],"h1":"Isipin kung ano ang ginagawa ng nakataas na median sa pagitan mo at ng bus.","h2":"Kapag may nakataas na harang o malapad na median sa pagitan mo at ng bus, hindi mo kailangang huminto, pero dapat ka pa ring magbantay sa mga bata.","p":"Tama. Kapag may nakataas na median sa pagitan ninyo, hindi mo kailangang huminto, pero manatiling alerto."},"ar":{"q":"في Florida، أنت على طريق سريع مقسوم بجزيرة وسطية مرتفعة. حافلة مدرسية تتوقف في الجهة الأخرى من الجزيرة. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن قُد بحذر","توقف حتى تذهب الحافلة","توقف، ثم تجاوز بسرعة المشي","انتقل إلى المسار الأقرب إلى الحافلة"],"h1":"فكّر في ما تفعله الجزيرة المرتفعة بينك وبين الحافلة.","h2":"عندما يفصلك حاجز مرتفع أو جزيرة وسطية عريضة عن الحافلة، ليس عليك أن تتوقف، لكن يجب أن تنتبه للأطفال.","p":"صحيح. مع جزيرة مرتفعة بينكما، ليس عليك أن تتوقف، لكن ابقَ منتبهًا."},"ht":{"q":"Nan Florida, ou sou yon otowout ki gen yon separasyon wo nan mitan an. Yon bis lekòl kanpe sou lòt bò separasyon an. Kisa ou ta dwe fè?","o":["Ou pa oblije kanpe, men kondi ak prekosyon","Kanpe jiskaske bis la ale","Kanpe, epi pase menm vitès ak yon moun k ap mache","Ale nan liy ki pi pre bis la"],"h1":"Panse ak sa separasyon wo a fè ant ou menm ak bis la.","h2":"Lè yon separasyon wo oswa yon separasyon ki laj nan mitan wout la separe w ak bis la, ou pa oblije kanpe, men ou ta dwe toujou veye timoun yo.","p":"Se sa. Avèk yon separasyon wo ant nou, ou pa oblije kanpe, men rete veyatif."},"ref":{"doc":"FL","page":89}},{"id":"safe-driving-013","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, what is the rule for holding a phone while driving in an active school zone?","o":["You may hold it for short calls","You may hold it if you drive slowly","You may not hold it; hands-free only","You may hold it only at a red light"],"h1":"Think about the extra danger near schools when children are present.","h2":"In Florida you may not hold a phone while driving in an active school zone, so you may only use it hands-free.","p":"Right. In an active school zone, no handheld phone, hands-free only."},"es":{"q":"En Florida, ¿cuál es la regla para sostener el teléfono mientras maneja en una zona escolar activa?","o":["Puede sostenerlo para llamadas cortas","Puede sostenerlo si maneja despacio","No puede sostenerlo; solo manos libres","Puede sostenerlo solo en luz roja"],"h1":"Piense en el peligro extra cerca de las escuelas cuando hay niños.","h2":"En Florida no puede sostener el teléfono mientras maneja en una zona escolar activa, así que solo puede usarlo con manos libres.","p":"Correcto. En una zona escolar activa, nada de teléfono en la mano; solo manos libres."},"zh":{"q":"在 Florida，在正在生效的学校区域开车时，拿着手机的规定是什么？","o":["打短电话时可以拿着","开得慢就可以拿着","不能拿在手里，只能免提","只在红灯时可以拿着"],"h1":"想一想有孩子在学校附近时多出来的危险。","h2":"在 Florida，在正在生效的学校区域开车时，你不能手拿手机，所以只能用免提。","p":"对。在正在生效的学校区域，不能手拿手机，只能免提。"},"vi":{"q":"Ở Florida, quy định về việc cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động là gì?","o":["Bạn được cầm để gọi nhanh","Bạn được cầm nếu lái chậm","Bạn không được cầm; chỉ được dùng rảnh tay (hands-free)","Bạn chỉ được cầm khi dừng đèn đỏ"],"h1":"Hãy nghĩ đến mối nguy hiểm thêm gần trường học khi có trẻ em.","h2":"Ở Florida, bạn không được cầm điện thoại khi lái xe trong khu vực trường học đang hoạt động, nên bạn chỉ được dùng ở chế độ rảnh tay.","p":"Đúng. Trong khu vực trường học đang hoạt động, không cầm điện thoại, chỉ dùng rảnh tay."},"tl":{"q":"Sa Florida, ano ang patakaran sa paghawak ng phone habang nagmamaneho sa active school zone?","o":["Puwede mo itong hawakan para sa maiikling tawag","Puwede mo itong hawakan kung mabagal ka","Bawal itong hawakan; hands-free lang","Puwede mo itong hawakan sa red light lang"],"h1":"Isipin ang dagdag na panganib malapit sa paaralan kapag may mga bata.","h2":"Sa Florida, bawal kang humawak ng phone habang nagmamaneho sa active school zone, kaya puwede mo lang itong gamitin nang hands-free.","p":"Tama. Sa active school zone, bawal ang phone na hawak sa kamay; hands-free lang."},"ar":{"q":"في Florida، ما القاعدة عن إمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة؟","o":["يمكنك أن تمسكه لمكالمات قصيرة","يمكنك أن تمسكه إذا كنت تقود ببطء","لا يُسمح لك بإمساكه؛ بدون استعمال اليدين فقط","يمكنك أن تمسكه فقط عند الإشارة الحمراء"],"h1":"فكّر في الخطر الزائد قرب المدارس عندما يكون الأطفال موجودين.","h2":"في Florida، لا يُسمح لك بإمساك الهاتف أثناء القيادة في منطقة مدرسة نشطة، لذلك يمكنك استعماله فقط بدون استعمال اليدين.","p":"صحيح. في منطقة مدرسة نشطة، لا هاتف في اليد، بدون استعمال اليدين فقط."},"ht":{"q":"Nan Florida, ki règ la pou kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif?","o":["Ou ka kenbe l pou ti apèl kout","Ou ka kenbe l si w ap kondi dousman","Ou pa ka kenbe l; san men (hands-free) sèlman","Ou ka kenbe l sèlman nan limyè wouj"],"h1":"Panse ak danje anplis toupre lekòl yo lè gen timoun.","h2":"Nan Florida, ou pa gen dwa kenbe yon telefòn nan men pandan w ap kondi nan yon zòn lekòl ki aktif, kidonk ou ka itilize l sèlman san men (hands-free).","p":"Se sa. Nan yon zòn lekòl ki aktif, pa gen telefòn nan men, san men (hands-free) sèlman."},"ref":{"doc":"FL","page":34}},{"id":"safe-driving-014","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, can a police officer stop you only because you are texting while driving?","o":["No, only if you also break another rule","Yes, texting while driving is enough","No, texting is only a warning","Yes, but only on the interstate"],"h1":"Think about how serious Florida treats texting at the wheel.","h2":"In Florida, texting while driving is a primary offense, so an officer may stop you for that reason alone.","p":"Right. In Florida you can be stopped just for texting while driving."},"es":{"q":"En Florida, ¿puede un policía detenerlo solo porque está enviando mensajes de texto mientras maneja?","o":["No, solo si también rompe otra regla","Sí, enviar mensajes al manejar es suficiente","No, los mensajes solo reciben una advertencia","Sí, pero solo en la autopista interestatal"],"h1":"Piense en qué tan en serio toma Florida los mensajes de texto al volante.","h2":"En Florida, enviar mensajes de texto mientras maneja es una infracción principal, así que un policía puede detenerlo solo por eso.","p":"Correcto. En Florida lo pueden detener solo por enviar mensajes al manejar."},"zh":{"q":"在 Florida，警察可以只因为你开车时发短信就让你停车吗？","o":["不可以，除非你也违反了别的规定","可以，开车发短信就足够了","不可以，发短信只会被警告","可以，但只在州际公路上"],"h1":"想一想 Florida 对开车时发短信有多严肃。","h2":"在 Florida，开车发短信是主要违法行为，所以警察只因为这个原因就可以让你停车。","p":"对。在 Florida，你可能只因为开车发短信就被拦下。"},"vi":{"q":"Ở Florida, cảnh sát có thể chặn xe bạn chỉ vì bạn nhắn tin khi lái xe không?","o":["Không, chỉ khi bạn vi phạm thêm quy định khác","Có, nhắn tin khi lái xe là đủ lý do","Không, nhắn tin chỉ bị cảnh cáo","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem Florida coi việc nhắn tin khi cầm lái nghiêm trọng đến mức nào.","h2":"Ở Florida, nhắn tin khi lái xe là vi phạm chính (primary offense), nên cảnh sát có thể chặn xe bạn chỉ vì lý do đó.","p":"Đúng. Ở Florida, bạn có thể bị chặn xe chỉ vì nhắn tin khi lái xe."},"tl":{"q":"Sa Florida, puwede ka bang parahin ng pulis dahil lang nagte-text ka habang nagmamaneho?","o":["Hindi, kung may iba ka lang ding nilabag na patakaran","Oo, sapat na ang pag-text habang nagmamaneho","Hindi, warning lang ang pag-text","Oo, pero sa interstate lang"],"h1":"Isipin kung gaano kabigat ang tingin ng Florida sa pag-text habang nagmamaneho.","h2":"Sa Florida, ang pag-text habang nagmamaneho ay primary offense, kaya puwede kang parahin ng pulis dahil lang doon.","p":"Tama. Sa Florida, puwede kang parahin dahil lang sa pag-text habang nagmamaneho."},"ar":{"q":"في Florida، هل يمكن للشرطي أن يوقفك فقط لأنك تكتب رسائل أثناء القيادة؟","o":["لا، فقط إذا خالفت قاعدة أخرى أيضًا","نعم، كتابة الرسائل أثناء القيادة سبب كافٍ","لا، كتابة الرسائل تعطي تحذيرًا فقط","نعم، لكن فقط على الطريق السريع بين الولايات"],"h1":"فكّر في مدى جدية Florida مع كتابة الرسائل وأنت خلف المقود.","h2":"في Florida، كتابة الرسائل أثناء القيادة مخالفة أساسية، لذلك يمكن للشرطي أن يوقفك لهذا السبب وحده.","p":"صحيح. في Florida يمكن أن يوقفوك فقط لأنك تكتب رسائل أثناء القيادة."},"ht":{"q":"Nan Florida, èske yon polis ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi?","o":["Non, sèlman si ou vyole yon lòt règ tou","Wi, voye tèks pandan w ap kondi ase","Non, voye tèks se yon avètisman sèlman","Wi, men sèlman sou otowout entèeta a"],"h1":"Panse ak jan Florida pran voye tèks nan volan an oserye.","h2":"Nan Florida, voye tèks pandan w ap kondi se yon enfraksyon prensipal, kidonk yon polis ka kanpe w pou rezon sa a sèlman.","p":"Se sa. Nan Florida, yo ka kanpe w sèlman paske w ap voye tèks pandan w ap kondi."},"ref":{"doc":"FL","page":null}},{"id":"safe-driving-015","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are present?","o":["The fine is doubled","The fine is cut in half","There is no fine, only a warning","The fine is the same as anywhere else"],"h1":"Think about how the law protects people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, to protect the people working there.","p":"Right. Speeding fines in a work zone are doubled when workers are present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de construcción cuando hay trabajadores?","o":["La multa se duplica","La multa se reduce a la mitad","No hay multa, solo una advertencia","La multa es igual que en otro lugar"],"h1":"Piense en cómo la ley protege a las personas que trabajan en la carretera.","h2":"En Florida, la multa por exceso de velocidad en una zona de construcción se duplica cuando hay trabajadores presentes, para proteger a quienes trabajan ahí.","p":"Correcto. Las multas por exceso de velocidad en zona de construcción se duplican cuando hay trabajadores."},"zh":{"q":"在 Florida，在有工人在场的工作区超速，罚款会怎么样？","o":["罚款加倍","罚款减半","没有罚款，只有警告","罚款和其他地方一样"],"h1":"想一想法律怎样保护在路上工作的人。","h2":"在 Florida，有工人在场时，在工作区超速的罚款会加倍，这是为了保护在那里工作的人。","p":"对。有工人在场时，工作区的超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công thay đổi thế nào khi có công nhân đang làm việc?","o":["Tiền phạt tăng gấp đôi","Tiền phạt giảm một nửa","Không bị phạt, chỉ bị cảnh cáo","Tiền phạt giống như ở nơi khác"],"h1":"Hãy nghĩ xem luật bảo vệ người làm việc trên đường như thế nào.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân đang làm việc, để bảo vệ những người làm việc ở đó.","p":"Đúng. Tiền phạt chạy quá tốc độ trong khu vực thi công tăng gấp đôi khi có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa overspeeding sa work zone kapag may mga trabahador?","o":["Dinodoble ang multa","Hinahati sa dalawa ang multa","Walang multa, warning lang","Pareho ang multa sa ibang lugar"],"h1":"Isipin kung paano pinoprotektahan ng batas ang mga taong nagtatrabaho sa daan.","h2":"Sa Florida, dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador, para protektahan ang mga taong nagtatrabaho roon.","p":"Tama. Dinodoble ang multa sa overspeeding sa work zone kapag may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة أعمال عندما يكون العمال موجودين؟","o":["الغرامة تتضاعف","الغرامة تنقص إلى النصف","لا توجد غرامة، فقط تحذير","الغرامة نفسها كما في أي مكان آخر"],"h1":"فكّر في كيف يحمي القانون الناس الذين يعملون على الطريق.","h2":"في Florida، غرامة السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين، لحماية الناس الذين يعملون هناك.","p":"صحيح. غرامات السرعة في منطقة الأعمال تتضاعف عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k rive amann pou vitès nan yon zòn travay lè gen travayè ki la?","o":["Amann nan double","Amann nan koupe an de","Pa gen amann, se yon avètisman sèlman","Amann nan menm jan ak nenpòt lòt kote"],"h1":"Panse ak jan lalwa pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè ki la, pou pwoteje moun k ap travay la.","p":"Se sa. Amann pou vitès nan yon zòn travay double lè gen travayè ki la."},"ref":{"doc":"FL","page":29}},{"id":"safe-driving-016","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds up a sign and signals you. What should you do?","o":["Follow the posted speed sign instead","Drive past if the lane looks clear","Honk so the flagger lets you go","Follow the flagger's signals"],"h1":"Think about who controls traffic in a work zone right now.","h2":"A flagger directs traffic in a work zone, so you must follow the flagger's signals even if other signs say something else.","p":"Right. In a work zone, follow the flagger's signals."},"es":{"q":"En una zona de construcción, un abanderado muestra una señal y le hace indicaciones. ¿Qué debe hacer?","o":["Seguir la señal de velocidad en su lugar","Pasar si el carril parece libre","Tocar la bocina para que lo deje pasar","Seguir las indicaciones del abanderado"],"h1":"Piense en quién controla el tráfico en la zona de construcción en este momento.","h2":"Un abanderado dirige el tráfico en una zona de construcción, así que debe seguir sus indicaciones aunque otras señales digan otra cosa.","p":"Correcto. En una zona de construcción, siga las indicaciones del abanderado."},"zh":{"q":"在工作区，一位旗手举起一块牌子向你打信号。你应该怎么做？","o":["改为按照路边的限速牌开","如果车道看起来没人就开过去","按喇叭让旗手放你过去","按照旗手的信号做"],"h1":"想一想现在是谁在工作区指挥交通。","h2":"旗手在工作区指挥交通，所以即使其他标志写的不一样，你也必须按照旗手的信号做。","p":"对。在工作区，按照旗手的信号做。"},"vi":{"q":"Trong khu vực thi công, một người cầm cờ điều khiển giao thông giơ biển và ra hiệu cho bạn. Bạn nên làm gì?","o":["Làm theo biển tốc độ được cắm thay vào đó","Chạy qua nếu làn đường có vẻ trống","Bấm còi để người cầm cờ cho bạn đi","Làm theo hiệu lệnh của người cầm cờ"],"h1":"Hãy nghĩ xem ai đang điều khiển giao thông trong khu vực thi công lúc này.","h2":"Người cầm cờ điều khiển giao thông trong khu vực thi công, nên bạn phải làm theo hiệu lệnh của người cầm cờ, dù các biển báo khác nói khác.","p":"Đúng. Trong khu vực thi công, hãy làm theo hiệu lệnh của người cầm cờ."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatula at sumesenyas sa iyo. Ano ang dapat mong gawin?","o":["Sundin na lang ang nakapaskil na speed sign","Lumampas kung mukhang maluwag ang lane","Bumusina para paraanin ka ng flagger","Sundin ang mga senyas ng flagger"],"h1":"Isipin kung sino ang kumokontrol sa trapiko sa work zone ngayon.","h2":"Ang flagger ang nagdidirekta ng trapiko sa work zone, kaya dapat mong sundin ang mga senyas ng flagger kahit iba ang sinasabi ng ibang karatula.","p":"Tama. Sa work zone, sundin ang mga senyas ng flagger."},"ar":{"q":"في منطقة أعمال، عامل تنظيم السير يرفع لافتة ويعطيك إشارة. ماذا يجب أن تفعل؟","o":["اتبع لافتة السرعة المكتوبة بدلًا من ذلك","تجاوزه إذا بدا المسار فارغًا","استعمل البوق حتى يتركك تمرّ","اتبع إشارات عامل تنظيم السير"],"h1":"فكّر: من ينظّم حركة السير في منطقة الأعمال الآن؟","h2":"عامل تنظيم السير يوجّه الحركة في منطقة الأعمال، لذلك يجب أن تتبع إشاراته حتى إذا كانت اللافتات الأخرى تقول شيئًا آخر.","p":"صحيح. في منطقة الأعمال، اتبع إشارات عامل تنظيم السير."},"ht":{"q":"Nan yon zòn travay, yon travayè ki gen drapo leve yon pankat epi li fè w siy. Kisa ou ta dwe fè?","o":["Swiv pankat vitès ki poste a pito","Pase si liy lan sanble li vid","Klaksonen pou travayè a kite w pase","Swiv siy travayè ki gen drapo a"],"h1":"Panse ak kiyès ki dirije sikilasyon an nan zòn travay la kounye a.","h2":"Yon travayè ki gen drapo dirije sikilasyon an nan yon zòn travay, kidonk ou dwe swiv siy li fè yo menm si lòt pankat di yon lòt bagay.","p":"Se sa. Nan yon zòn travay, swiv siy travayè ki gen drapo a."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-017","scope":"US","cat":"safe-driving","sign":{"shape":"diamond-orange"},"c":1,"en":{"q":"What does an orange diamond-shaped sign usually warn you about?","o":["A school zone ahead","A work zone ahead","A railroad crossing ahead","A hospital ahead"],"h1":"Think about the color used for road work.","h2":"Orange warning signs are used for work zones, so an orange diamond tells you that road work is ahead.","p":"Right. An orange diamond sign warns of a work zone ahead."},"es":{"q":"¿Sobre qué le advierte normalmente una señal anaranjada en forma de rombo?","o":["Una zona escolar adelante","Una zona de construcción adelante","Un cruce de tren adelante","Un hospital adelante"],"h1":"Piense en el color que se usa para trabajos en la vía.","h2":"Las señales de advertencia anaranjadas se usan para zonas de construcción, así que un rombo anaranjado le dice que hay trabajos en la vía adelante.","p":"Correcto. Un rombo anaranjado advierte una zona de construcción adelante."},"zh":{"q":"橙色菱形标志通常提醒你注意什么？","o":["前面有学校区域","前面有工作区","前面有铁路道口","前面有医院"],"h1":"想一想道路施工用的是什么颜色。","h2":"橙色警告标志用于工作区，所以橙色菱形标志告诉你前面有道路施工。","p":"对。橙色菱形标志提醒你前面有工作区。"},"vi":{"q":"Biển báo màu cam hình thoi thường cảnh báo bạn về điều gì?","o":["Phía trước có khu vực trường học","Phía trước có khu vực thi công","Phía trước có đường ray xe lửa cắt ngang","Phía trước có bệnh viện"],"h1":"Hãy nghĩ đến màu được dùng cho công việc sửa đường.","h2":"Biển cảnh báo màu cam được dùng cho khu vực thi công, nên biển màu cam hình thoi cho bạn biết phía trước có công việc sửa đường.","p":"Đúng. Biển màu cam hình thoi cảnh báo phía trước có khu vực thi công."},"tl":{"q":"Ano ang karaniwang babala ng karatulang kulay orange na hugis diamond?","o":["May school zone sa unahan","May work zone sa unahan","May tawiran ng tren sa unahan","May ospital sa unahan"],"h1":"Isipin ang kulay na ginagamit para sa trabaho sa daan.","h2":"Ang mga karatulang babala na kulay orange ay ginagamit para sa mga work zone, kaya ang orange na diamond ay nagsasabing may trabaho sa daan sa unahan.","p":"Tama. Ang orange na diamond na karatula ay babala na may work zone sa unahan."},"ar":{"q":"لافتة برتقالية على شكل معيّن (مثل الماسة). مِمّ تحذّرك عادةً؟","o":["منطقة مدرسة أمامك","منطقة أعمال أمامك","تقاطع سكة حديد أمامك","مستشفى أمامك"],"h1":"فكّر في اللون المستعمل لأعمال الطرق.","h2":"لافتات التحذير البرتقالية تُستعمل لمناطق الأعمال، لذلك اللافتة البرتقالية على شكل معيّن تخبرك بأن هناك أعمال طرق أمامك.","p":"صحيح. اللافتة البرتقالية على شكل معيّن تحذّر من منطقة أعمال أمامك."},"ht":{"q":"Kisa yon pankat oranj ki gen fòm dyaman (lozanj) konn avèti w?","o":["Yon zòn lekòl devan","Yon zòn travay devan","Yon kwazman tren devan","Yon lopital devan"],"h1":"Panse ak koulè yo itilize pou travay sou wout.","h2":"Yo itilize pankat avètisman oranj pou zòn travay, kidonk yon dyaman oranj di w gen travay sou wout la devan.","p":"Se sa. Yon pankat dyaman oranj avèti w gen yon zòn travay devan."},"ref":{"doc":"FL","page":54}},{"id":"safe-driving-018","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, a police car is stopped on the shoulder with its lights flashing. You are on a highway with two lanes going your way. What should you do?","o":["Keep your speed and stay in your lane","Stop next to the police car","Move over a lane if safe; if not, slow down","Speed up to pass the area quickly"],"h1":"Think about giving space to people working beside the road.","h2":"Florida's Move Over law says you must move out of the lane next to the stopped vehicle when it is safe, and if you cannot, you must slow down.","p":"Right. Move over a lane if you safely can, or slow down."},"es":{"q":"En Florida, un carro de policía está parado en el acotamiento con las luces encendidas. Usted va por una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Mantener su velocidad y su carril","Parar al lado del carro de policía","Cambiarse de carril si es seguro; si no, bajar la velocidad","Acelerar para pasar rápido"],"h1":"Piense en dar espacio a las personas que trabajan al lado de la vía.","h2":"La ley Move Over de Florida dice que debe salir del carril junto al vehículo detenido cuando sea seguro, y si no puede, debe bajar la velocidad.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Florida，一辆警车停在路肩上，灯在闪。你在一条你这个方向有两条车道的公路上。你应该怎么做？","o":["保持速度，留在你的车道","停在警车旁边","安全的话就换开一条车道；不行的话就减速","加速，快点开过这个地方"],"h1":"想一想给在路边工作的人留出空间。","h2":"Florida 的 Move Over 法律规定，安全时你必须离开紧挨停着的车辆的那条车道；如果不能，你就必须减速。","p":"对。安全的话就换开一条车道，不行就减速。"},"vi":{"q":"Ở Florida, một xe cảnh sát đang dừng trên lề đường và nháy đèn. Bạn đang đi trên xa lộ có hai làn cùng chiều với bạn. Bạn nên làm gì?","o":["Giữ tốc độ và ở yên trong làn","Dừng lại cạnh xe cảnh sát","Chuyển sang làn khác nếu an toàn; nếu không, hãy giảm tốc","Tăng tốc để đi qua khu vực đó thật nhanh"],"h1":"Hãy nghĩ đến việc chừa chỗ cho những người đang làm việc bên đường.","h2":"Luật Move Over của Florida nói rằng bạn phải rời khỏi làn sát xe đang dừng khi an toàn, và nếu không thể, bạn phải giảm tốc.","p":"Đúng. Chuyển sang làn khác nếu an toàn, hoặc giảm tốc."},"tl":{"q":"Sa Florida, may police car na nakahinto sa shoulder at kumikislap ang mga ilaw nito. Nasa highway ka na may dalawang lane papunta sa direksyon mo. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo at manatili sa lane mo","Huminto sa tabi ng police car","Lumipat ng isang lane kung ligtas; kung hindi, bumagal","Bumilis para mabilis na malampasan ang lugar"],"h1":"Isipin ang pagbibigay ng espasyo sa mga taong nagtatrabaho sa tabi ng daan.","h2":"Sinasabi ng Move Over law ng Florida na dapat kang umalis sa lane na katabi ng nakahintong sasakyan kapag ligtas, at kung hindi mo kaya, dapat kang bumagal.","p":"Tama. Lumipat ng isang lane kung ligtas mong magagawa, o bumagal."},"ar":{"q":"في Florida، سيارة شرطة متوقفة على كتف الطريق وأضواؤها تومض. أنت على طريق سريع فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك وابقَ في مسارك","توقف بجانب سيارة الشرطة","انتقل مسارًا واحدًا بعيدًا إذا كان ذلك آمنًا؛ وإذا لم يكن آمنًا، خفّف السرعة","أسرع لتمرّ من المكان بسرعة"],"h1":"فكّر في إعطاء مساحة للناس الذين يعملون بجانب الطريق.","h2":"قانون Move Over في Florida يقول إنه يجب أن تخرج من المسار المجاور للمركبة المتوقفة عندما يكون ذلك آمنًا، وإذا لم تستطع، يجب أن تخفّف السرعة.","p":"صحيح. انتقل مسارًا واحدًا إذا استطعت بأمان، أو خفّف السرعة."},"ht":{"q":"Nan Florida, yon machin polis kanpe bò wout la ak limyè l ap flache. Ou sou yon otowout ki gen de liy nan direksyon pa w. Kisa ou ta dwe fè?","o":["Kenbe menm vitès la epi rete nan liy ou","Kanpe bò kote machin polis la","Chanje liy si li an sekirite; si se pa sa, ralanti","Akselere pou pase zòn nan vit"],"h1":"Panse ak bay moun k ap travay bò wout la espas.","h2":"Lwa Move Over Florida a di ou dwe soti nan liy ki bò kote machin ki kanpe a lè li an sekirite, epi si ou pa kapab, ou dwe ralanti.","p":"Se sa. Chanje liy si ou ka fè l san danje, oswa ralanti."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-019","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, you cannot move over for a stopped emergency vehicle on a road with a 55 mph limit. How slow must you go?","o":["20 mph below the limit","5 mph below the limit","10 mph below the limit","Exactly 25 mph"],"h1":"Think about a big drop in speed, not a small one.","h2":"Under Florida's Move Over law, if you cannot change lanes you must slow to 20 mph below the posted limit, so on a 55 mph road you go 35 mph.","p":"Right. If you cannot move over, slow to 20 mph below the limit."},"es":{"q":"En Florida, usted no puede cambiarse de carril ante un vehículo de emergencia detenido en una vía con límite de 55 mph. ¿A qué velocidad debe ir?","o":["20 mph por debajo del límite","5 mph por debajo del límite","10 mph por debajo del límite","Exactamente 25 mph"],"h1":"Piense en una reducción grande de velocidad, no pequeña.","h2":"Según la ley Move Over de Florida, si no puede cambiarse de carril debe bajar a 20 mph por debajo del límite, así que en una vía de 55 mph va a 35 mph.","p":"Correcto. Si no puede cambiarse de carril, baje 20 mph por debajo del límite."},"zh":{"q":"在 Florida，在限速 55 mph 的路上，你不能为停着的紧急车辆换车道。你必须减到多慢？","o":["比限速低 20 mph","比限速低 5 mph","比限速低 10 mph","正好 25 mph"],"h1":"想一想大幅度减速，而不是一点点。","h2":"按照 Florida 的 Move Over 法律，如果你不能换车道，就必须减到比标示的限速低 20 mph，所以在 55 mph 的路上你要开 35 mph。","p":"对。如果不能换车道，就减到比限速低 20 mph。"},"vi":{"q":"Ở Florida, bạn không thể chuyển làn để tránh một xe cấp cứu đang dừng trên đường có giới hạn 55 mph. Bạn phải chạy chậm đến mức nào?","o":["Thấp hơn giới hạn 20 mph","Thấp hơn giới hạn 5 mph","Thấp hơn giới hạn 10 mph","Đúng 25 mph"],"h1":"Hãy nghĩ đến việc giảm tốc độ nhiều, không phải chỉ một chút.","h2":"Theo luật Move Over của Florida, nếu không thể chuyển làn, bạn phải giảm xuống thấp hơn giới hạn được cắm biển 20 mph, nên trên đường 55 mph bạn chạy 35 mph.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Florida, hindi ka makalipat ng lane para sa nakahintong emergency vehicle sa daang may 55 mph na limit. Gaano ka dapat kabagal?","o":["20 mph na mas mababa sa limit","5 mph na mas mababa sa limit","10 mph na mas mababa sa limit","Eksaktong 25 mph"],"h1":"Isipin ang malaking pagbaba ng bilis, hindi maliit.","h2":"Ayon sa Move Over law ng Florida, kung hindi ka makalipat ng lane, dapat kang bumagal sa 20 mph na mas mababa sa nakapaskil na limit, kaya sa daang 55 mph ay 35 mph ang takbo mo.","p":"Tama. Kung hindi ka makalipat, bumagal sa 20 mph na mas mababa sa limit."},"ar":{"q":"في Florida، لا تستطيع أن تبتعد عن مركبة طوارئ متوقفة، على طريق حد السرعة فيه 55 mph (ميلًا في الساعة). إلى أي سرعة يجب أن تخفّف؟","o":["20 mph أقل من الحد","5 mph أقل من الحد","10 mph أقل من الحد","25 mph بالضبط"],"h1":"فكّر في نقص كبير في السرعة، وليس نقصًا صغيرًا.","h2":"حسب قانون Move Over في Florida، إذا لم تستطع تغيير المسار يجب أن تخفّف سرعتك إلى 20 mph أقل من الحد المكتوب، فعلى طريق حده 55 mph تسير بسرعة 35 mph.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف سرعتك إلى 20 mph أقل من الحد."},"ht":{"q":"Nan Florida, ou pa ka chanje liy pou yon machin ijans ki kanpe sou yon wout kote limit la se 55 mph. Ki vitès ou dwe desann?","o":["20 mph anba limit la","5 mph anba limit la","10 mph anba limit la","Egzakteman 25 mph"],"h1":"Panse ak yon gwo bès nan vitès, pa yon ti bès.","h2":"Dapre lwa Move Over Florida a, si ou pa ka chanje liy, ou dwe ralanti pou w kondi 20 mph anba limit ki poste a, kidonk sou yon wout 55 mph ou kondi a 35 mph.","p":"Se sa. Si ou pa ka chanje liy, ralanti a 20 mph anba limit la."},"ref":{"doc":"FL","page":65}},{"id":"safe-driving-020","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car starts to skid on a slippery road. What should you do?","o":["Slam on the brakes hard","Turn the wheel sharply the other way","Press the gas to get control back","Ease off the gas and steer where you want to go"],"h1":"Think about gentle moves, not sudden ones.","h2":"In a skid, sudden braking or sharp steering makes it worse, so you should ease off the gas and gently steer in the direction you want the car to go.","p":"Right. Ease off the gas and steer where you want to go."},"es":{"q":"Su carro empieza a patinar en una vía resbalosa. ¿Qué debe hacer?","o":["Frenar de golpe con fuerza","Girar el volante bruscamente al otro lado","Acelerar para recuperar el control","Soltar el acelerador y dirigir hacia donde quiere ir"],"h1":"Piense en movimientos suaves, no bruscos.","h2":"Al patinar, frenar de golpe o girar bruscamente lo empeora, así que debe soltar el acelerador y dirigir suavemente hacia donde quiere que vaya el carro.","p":"Correcto. Suelte el acelerador y dirija hacia donde quiere ir."},"zh":{"q":"你的车在很滑的路上开始打滑。你应该怎么做？","o":["用力猛踩刹车","把方向盘猛地往反方向转","踩油门来重新控制车","慢慢松开油门，把方向盘转向你想去的方向"],"h1":"想一想轻柔的动作，而不是突然的动作。","h2":"打滑时，突然刹车或猛转方向盘会让情况更糟，所以你应该慢慢松开油门，轻轻地把方向盘转向你想让车去的方向。","p":"对。慢慢松开油门，转向你想去的方向。"},"vi":{"q":"Xe của bạn bắt đầu bị trượt trên đường trơn. Bạn nên làm gì?","o":["Đạp phanh thật mạnh","Đánh tay lái gắt sang hướng ngược lại","Nhấn ga để lấy lại kiểm soát","Nhả ga từ từ và lái về hướng bạn muốn đi"],"h1":"Hãy nghĩ đến những động tác nhẹ nhàng, không đột ngột.","h2":"Khi xe bị trượt, phanh gấp hoặc đánh lái gắt sẽ làm tệ hơn, nên bạn nên nhả ga từ từ và nhẹ nhàng lái về hướng bạn muốn xe đi.","p":"Đúng. Nhả ga từ từ và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang dumulas ang kotse mo sa madulas na daan. Ano ang dapat mong gawin?","o":["Tapakan nang malakas ang preno","Biglang iikot ang manibela sa kabilang direksyon","Tapakan ang gas para makontrol ulit","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta"],"h1":"Isipin ang mahinahong galaw, hindi ang biglaan.","h2":"Sa pagdulas, lumalala ito kapag biglang nagpreno o biglang iniikot ang manibela, kaya dapat mong dahan-dahang bitawan ang gas at marahang imaneho ang kotse sa direksyong gusto mo.","p":"Tama. Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta."},"ar":{"q":"سيارتك تبدأ بالانزلاق على طريق زلق. ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة","أدِر المقود بقوة إلى الجهة الأخرى","اضغط على البنزين لتستعيد السيطرة","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب"],"h1":"فكّر في حركات هادئة، وليس حركات مفاجئة.","h2":"أثناء الانزلاق، الفرملة المفاجئة أو إدارة المقود بقوة تجعل الوضع أسوأ، لذلك يجب أن ترفع قدمك عن البنزين بهدوء وتوجّه السيارة بلطف إلى الاتجاه الذي تريده.","p":"صحيح. ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Machin ou kòmanse glise sou yon wout ki glise. Kisa ou ta dwe fè?","o":["Peze fren an fò sanzatann","Vire volan an rapid nan lòt direksyon an","Peze gaz la pou w reprann kontwòl","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale"],"h1":"Panse ak mouvman dous, pa mouvman sanzatann.","h2":"Lè machin nan ap glise, frennen sanzatann oswa vire volan an rapid fè l pi mal, kidonk ou ta dwe leve pye ou dousman sou gaz la epi dirije machin nan dousman nan direksyon ou vle l ale.","p":"Se sa. Leve pye ou sou gaz la epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-021","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your tires start to ride on top of water on a wet road (hydroplaning). What should you do?","o":["Brake hard right away","Ease off the gas and steer where you want to go","Speed up to get through the water","Turn the wheel quickly left and right"],"h1":"Think about letting the tires touch the road again.","h2":"When you hydroplane, the tires lose their grip on the road, so you should ease off the gas, stay off the brakes, and gently steer where you want to go.","p":"Right. Ease off the gas, avoid the brakes, and steer where you want to go."},"es":{"q":"Sus llantas empiezan a deslizarse sobre el agua en una vía mojada (hidroplaneo). ¿Qué debe hacer?","o":["Frenar fuerte de inmediato","Soltar el acelerador y dirigir hacia donde quiere ir","Acelerar para pasar el agua","Mover el volante rápido a los lados"],"h1":"Piense en dejar que las llantas vuelvan a tocar la vía.","h2":"En el hidroplaneo las llantas pierden el agarre con la vía, así que debe soltar el acelerador, no usar los frenos y dirigir suavemente hacia donde quiere ir.","p":"Correcto. Suelte el acelerador, no frene y dirija hacia donde quiere ir."},"zh":{"q":"在湿的路上，你的轮胎开始浮在水面上（水滑）。你应该怎么做？","o":["马上用力刹车","慢慢松开油门，把方向盘转向你想去的方向","加速冲过水","把方向盘快速地左右转"],"h1":"想一想让轮胎重新接触路面。","h2":"发生水滑时，轮胎失去了对路面的抓地力，所以你应该慢慢松开油门，不要踩刹车，轻轻地把方向盘转向你想去的方向。","p":"对。慢慢松开油门，不要踩刹车，转向你想去的方向。"},"vi":{"q":"Bánh xe của bạn bắt đầu lướt trên mặt nước trên đường ướt (hydroplaning). Bạn nên làm gì?","o":["Phanh mạnh ngay lập tức","Nhả ga từ từ và lái về hướng bạn muốn đi","Tăng tốc để đi qua vùng nước","Đánh tay lái nhanh qua trái qua phải"],"h1":"Hãy nghĩ đến việc để bánh xe chạm lại mặt đường.","h2":"Khi xe lướt nước, bánh xe mất độ bám đường, nên bạn nên nhả ga từ từ, không đạp phanh, và nhẹ nhàng lái về hướng bạn muốn đi.","p":"Đúng. Nhả ga từ từ, tránh đạp phanh, và lái về hướng bạn muốn đi."},"tl":{"q":"Nagsisimulang lumutang sa ibabaw ng tubig ang mga gulong mo sa basang daan (hydroplaning). Ano ang dapat mong gawin?","o":["Magpreno nang malakas agad","Dahan-dahang bitawan ang gas at imaneho kung saan mo gustong pumunta","Bumilis para malampasan ang tubig","Mabilis na iikot ang manibela pakaliwa at pakanan"],"h1":"Isipin kung paano muling dadampi sa daan ang mga gulong.","h2":"Kapag nag-hydroplane ka, nawawalan ng kapit sa daan ang mga gulong, kaya dapat mong dahan-dahang bitawan ang gas, huwag magpreno, at marahang imaneho kung saan mo gustong pumunta.","p":"Tama. Dahan-dahang bitawan ang gas, iwasan ang preno, at imaneho kung saan mo gustong pumunta."},"ar":{"q":"إطاراتك بدأت تسير فوق الماء على طريق مبلل (انزلاق مائي). ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة فورًا","ارفع قدمك عن البنزين بهدوء ووجّه السيارة إلى حيث تريد أن تذهب","أسرع لتعبر الماء","أدِر المقود بسرعة يمينًا ويسارًا"],"h1":"فكّر في أن تترك الإطارات تلمس الطريق مرة أخرى.","h2":"في الانزلاق المائي، الإطارات تفقد تماسكها مع الطريق، لذلك يجب أن ترفع قدمك عن البنزين بهدوء، وألا تستعمل الفرامل، وأن توجّه السيارة بلطف إلى حيث تريد أن تذهب.","p":"صحيح. ارفع قدمك عن البنزين، وتجنّب الفرامل، ووجّه السيارة إلى حيث تريد أن تذهب."},"ht":{"q":"Kawotchou ou yo kòmanse woule sou dlo a sou yon wout mouye (hydroplaning). Kisa ou ta dwe fè?","o":["Frennen fò touswit","Leve pye ou dousman sou gaz la epi dirije machin nan kote ou vle ale","Akselere pou w travèse dlo a","Vire volan an vit agoch ak adwat"],"h1":"Panse ak kite kawotchou yo touche wout la ankò.","h2":"Lè kawotchou yo ap glise sou dlo (hydroplaning), yo pèdi kenbe yo sou wout la, kidonk ou ta dwe leve pye ou dousman sou gaz la, pa touche fren an, epi dirije machin nan dousman kote ou vle ale.","p":"Se sa. Leve pye ou sou gaz la, pa touche fren an, epi dirije machin nan kote ou vle ale."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-022","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"A front tire suddenly blows out while you are driving. What should you do first?","o":["Hold the wheel firmly and ease off the gas","Brake hard to stop right away","Steer quickly onto the shoulder","Speed up to keep the car straight"],"h1":"Think about keeping control of the car before you stop.","h2":"A blowout can pull the car to one side, so you should hold the wheel firmly, ease off the gas, and brake gently only after the car is under control.","p":"Right. Hold the wheel firmly and ease off the gas."},"es":{"q":"Una llanta delantera revienta de repente mientras maneja. ¿Qué debe hacer primero?","o":["Sostener firme el volante y soltar el acelerador","Frenar fuerte para parar de inmediato","Girar rápido hacia el acotamiento","Acelerar para mantener el carro derecho"],"h1":"Piense en mantener el control del carro antes de parar.","h2":"Una llanta reventada puede jalar el carro hacia un lado, así que debe sostener firme el volante, soltar el acelerador y frenar suave solo cuando tenga el control.","p":"Correcto. Sostenga firme el volante y suelte el acelerador."},"zh":{"q":"你开车时，一个前轮突然爆胎。你首先应该做什么？","o":["紧紧握住方向盘，慢慢松开油门","用力刹车，马上停下","快速转到路肩上","加速让车保持直行"],"h1":"想一想在停车前先控制住车。","h2":"爆胎可能会把车拉向一边，所以你应该紧紧握住方向盘，慢慢松开油门，等车被控制住以后再轻轻刹车。","p":"对。紧紧握住方向盘，慢慢松开油门。"},"vi":{"q":"Một bánh xe trước đột nhiên bị nổ khi bạn đang lái. Bạn nên làm gì trước tiên?","o":["Giữ chặt tay lái và nhả ga từ từ","Phanh mạnh để dừng ngay","Lái nhanh vào lề đường","Tăng tốc để giữ xe đi thẳng"],"h1":"Hãy nghĩ đến việc giữ kiểm soát xe trước khi dừng lại.","h2":"Nổ lốp có thể kéo xe lệch sang một bên, nên bạn nên giữ chặt tay lái, nhả ga từ từ, và chỉ phanh nhẹ sau khi đã kiểm soát được xe.","p":"Đúng. Giữ chặt tay lái và nhả ga từ từ."},"tl":{"q":"Biglang pumutok ang gulong sa harap habang nagmamaneho ka. Ano ang una mong dapat gawin?","o":["Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas","Magpreno nang malakas para huminto agad","Mabilis na lumihis papunta sa shoulder","Bumilis para manatiling diretso ang kotse"],"h1":"Isipin ang pagkontrol sa kotse bago ka huminto.","h2":"Ang pagputok ng gulong ay puwedeng humila sa kotse sa isang tabi, kaya dapat mong hawakan nang mahigpit ang manibela, dahan-dahang bitawan ang gas, at marahang magpreno pagkatapos lang makontrol ang kotse.","p":"Tama. Hawakan nang mahigpit ang manibela at dahan-dahang bitawan ang gas."},"ar":{"q":"إطار أمامي انفجر فجأة وأنت تقود. ماذا يجب أن تفعل أولًا؟","o":["أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء","اضغط على الفرامل بقوة لتتوقف فورًا","وجّه السيارة بسرعة إلى كتف الطريق","أسرع لتبقى السيارة مستقيمة"],"h1":"فكّر في السيطرة على السيارة قبل أن تتوقف.","h2":"انفجار الإطار قد يسحب السيارة إلى جهة واحدة، لذلك يجب أن تمسك المقود بقوة، وترفع قدمك عن البنزين بهدوء، وتضغط الفرامل بلطف فقط بعد أن تسيطر على السيارة.","p":"صحيح. أمسك المقود بقوة وارفع قدمك عن البنزين بهدوء."},"ht":{"q":"Yon kawotchou devan pete sanzatann pandan w ap kondi. Kisa ou ta dwe fè anvan?","o":["Kenbe volan an fèm epi leve pye ou dousman sou gaz la","Frennen fò pou kanpe touswit","Vire vit pou w ale bò wout la","Akselere pou kenbe machin nan dwat"],"h1":"Panse ak kenbe kontwòl machin nan anvan ou kanpe.","h2":"Yon kawotchou ki pete ka rale machin nan sou yon bò, kidonk ou ta dwe kenbe volan an fèm, leve pye ou dousman sou gaz la, epi frennen dousman sèlman apre ou gen kontwòl machin nan.","p":"Se sa. Kenbe volan an fèm epi leve pye ou dousman sou gaz la."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-023","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You press the brake pedal and your brakes do not work. What should you try first?","o":["Turn off the engine right away","Open the door and drag your foot","Pump the brake pedal fast","Shift into reverse"],"h1":"Think about trying to build up brake pressure again.","h2":"Pumping the brake pedal may build up pressure again, and if that fails you can use the parking brake slowly and shift to a lower gear.","p":"Right. Pump the brake pedal first, then use the parking brake."},"es":{"q":"Usted pisa el freno y los frenos no funcionan. ¿Qué debe intentar primero?","o":["Apagar el motor de inmediato","Abrir la puerta y arrastrar el pie","Bombear el pedal del freno rápido","Poner la reversa"],"h1":"Piense en volver a crear presión en los frenos.","h2":"Bombear el pedal del freno puede volver a crear presión, y si no funciona, puede usar el freno de mano poco a poco y cambiar a una velocidad más baja.","p":"Correcto. Bombee el pedal primero y luego use el freno de mano."},"zh":{"q":"你踩刹车踏板，可是刹车不灵。你首先应该试什么？","o":["马上关掉引擎","打开车门，用脚拖地","快速地连续踩刹车踏板","挂倒挡"],"h1":"想一想怎样让刹车重新产生压力。","h2":"快速连续踩刹车踏板可能会让压力重新建立起来；如果不行，你可以慢慢拉手刹，并换到低挡。","p":"对。先连续踩刹车踏板，然后用手刹。"},"vi":{"q":"Bạn đạp bàn đạp phanh nhưng phanh không ăn. Bạn nên thử làm gì trước tiên?","o":["Tắt máy xe ngay lập tức","Mở cửa và kéo chân xuống đất","Đạp nhấp bàn đạp phanh liên tục và nhanh","Chuyển sang số lùi"],"h1":"Hãy nghĩ đến việc cố tạo lại áp lực phanh.","h2":"Đạp nhấp bàn đạp phanh có thể tạo lại áp lực, và nếu không được, bạn có thể kéo phanh tay từ từ và chuyển xuống số thấp hơn.","p":"Đúng. Đạp nhấp bàn đạp phanh trước, rồi dùng phanh tay."},"tl":{"q":"Tinapakan mo ang preno at hindi gumagana ang preno mo. Ano ang una mong dapat subukan?","o":["Patayin agad ang makina","Buksan ang pinto at ikaskas ang paa mo sa daan","Mabilis na tapak-tapakan ang preno nang paulit-ulit","Ilagay sa reverse"],"h1":"Isipin ang pagsubok na muling magkaroon ng pressure sa preno.","h2":"Ang paulit-ulit at mabilis na pagtapak sa preno ay puwedeng magbalik ng pressure, at kung hindi ito gumana, puwede mong dahan-dahang gamitin ang parking brake at ilipat sa mas mababang gear.","p":"Tama. Tapak-tapakan muna ang preno, saka gamitin ang parking brake."},"ar":{"q":"تضغط على دواسة الفرامل والفرامل لا تعمل. ماذا يجب أن تجرّب أولًا؟","o":["أطفئ المحرك فورًا","افتح الباب واسحب قدمك على الأرض","اضغط على دواسة الفرامل مرات سريعة متتالية","انقل الغيار إلى الخلف (reverse)"],"h1":"فكّر في محاولة بناء ضغط الفرامل مرة أخرى.","h2":"الضغط على دواسة الفرامل مرات متتالية قد يبني الضغط مرة أخرى، وإذا لم ينجح ذلك يمكنك استعمال فرامل اليد ببطء والنقل إلى غيار أدنى.","p":"صحيح. اضغط على دواسة الفرامل مرات متتالية أولًا، ثم استعمل فرامل اليد."},"ht":{"q":"Ou peze pedal fren an epi fren yo pa mache. Kisa ou ta dwe eseye anvan?","o":["Fèmen motè a touswit","Louvri pòt la epi trennen pye ou atè","Peze pedal fren an plizyè fwa vit","Mete machin nan an mach aryè"],"h1":"Panse ak eseye fè presyon fren an monte ankò.","h2":"Lè ou peze pedal fren an plizyè fwa vit, sa ka fè presyon an monte ankò, epi si sa pa mache, ou ka sèvi ak fren a men an dousman epi mete yon vitès ki pi ba.","p":"Se sa. Peze pedal fren an plizyè fwa anvan, epi sèvi ak fren a men an."}},{"id":"safe-driving-024","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your gas pedal gets stuck and the car keeps speeding up. What should you do?","o":["Pull the key out while moving","Turn the wheel hard to the side","Pump the gas pedal many times","Shift to neutral and brake"],"h1":"Think about how to stop the engine from pushing the wheels.","h2":"Shifting to neutral stops the engine from driving the wheels, so you can brake, pull off the road, and then turn off the engine.","p":"Right. Shift to neutral and brake to a safe stop."},"es":{"q":"Su pedal del acelerador se traba y el carro sigue acelerando. ¿Qué debe hacer?","o":["Sacar la llave mientras se mueve","Girar el volante fuerte hacia un lado","Bombear el acelerador muchas veces","Poner neutro y frenar"],"h1":"Piense en cómo impedir que el motor siga empujando las ruedas.","h2":"Al poner neutro el motor deja de mover las ruedas, así que puede frenar, salir de la vía y luego apagar el motor.","p":"Correcto. Ponga neutro y frene hasta parar con seguridad."},"zh":{"q":"你的油门踏板卡住了，车一直在加速。你应该怎么做？","o":["开车时把钥匙拔出来","把方向盘用力转向一边","连续踩很多次油门","换到空挡并刹车"],"h1":"想一想怎样让引擎不再推动车轮。","h2":"换到空挡后，引擎就不再带动车轮，所以你可以刹车，把车开离道路，然后关掉引擎。","p":"对。换到空挡，刹车，安全地停下来。"},"vi":{"q":"Bàn đạp ga của bạn bị kẹt và xe cứ tăng tốc. Bạn nên làm gì?","o":["Rút chìa khóa ra khi xe đang chạy","Đánh tay lái mạnh sang một bên","Đạp nhấp bàn đạp ga nhiều lần","Chuyển sang số N (số mo) và phanh"],"h1":"Hãy nghĩ cách để động cơ không đẩy bánh xe nữa.","h2":"Chuyển sang số N làm động cơ không còn đẩy bánh xe, nên bạn có thể phanh, tấp vào lề, rồi tắt máy.","p":"Đúng. Chuyển sang số N và phanh để dừng an toàn."},"tl":{"q":"Naipit ang gas pedal mo at patuloy na bumibilis ang kotse. Ano ang dapat mong gawin?","o":["Bunutin ang susi habang umaandar","Iikot nang malakas ang manibela sa gilid","Tapak-tapakan ang gas nang maraming beses","Ilagay sa neutral at magpreno"],"h1":"Isipin kung paano pipigilan ang makina sa pagtulak sa mga gulong.","h2":"Kapag inilagay sa neutral, hindi na itinutulak ng makina ang mga gulong, kaya puwede kang magpreno, tumabi sa daan, at saka patayin ang makina.","p":"Tama. Ilagay sa neutral at magpreno hanggang ligtas na huminto."},"ar":{"q":"دواسة البنزين علقت والسيارة تستمر في زيادة السرعة. ماذا يجب أن تفعل؟","o":["اسحب المفتاح والسيارة تتحرك","أدِر المقود بقوة إلى الجانب","اضغط على دواسة البنزين مرات كثيرة","انقل الغيار إلى المحايد (neutral) واضغط الفرامل"],"h1":"فكّر في كيف تمنع المحرك من دفع العجلات.","h2":"النقل إلى المحايد (neutral) يمنع المحرك من تحريك العجلات، فتستطيع أن تضغط الفرامل، وتخرج من الطريق، ثم تطفئ المحرك.","p":"صحيح. انقل الغيار إلى المحايد (neutral) واضغط الفرامل حتى تتوقف بأمان."},"ht":{"q":"Pedal gaz ou a bloke epi machin nan kontinye ap akselere. Kisa ou ta dwe fè?","o":["Rale kle a pandan machin nan ap woule","Vire volan an fò sou kote","Peze pedal gaz la anpil fwa","Mete machin nan an netral (N) epi frennen"],"h1":"Panse ak kijan pou w anpeche motè a pouse wou yo.","h2":"Lè ou mete machin nan an netral (N), motè a pa pouse wou yo ankò, kidonk ou ka frennen, soti sou bò wout la, epi apre sa fèmen motè a.","p":"Se sa. Mete machin nan an netral (N) epi frennen pou w kanpe san danje."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-025","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your right wheels drift off the pavement onto the dirt edge. What should you do?","o":["Jerk the wheel back onto the road","Ease off the gas, slow down, then steer back gently","Brake hard right away","Speed up and steer back fast"],"h1":"Think about slowing down before you return to the road.","h2":"Turning back too fast can make you lose control, so ease off the gas, slow down, and then steer gently back onto the pavement when it is safe.","p":"Right. Slow down first, then steer back gently."},"es":{"q":"Sus ruedas derechas se salen del pavimento a la orilla de tierra. ¿Qué debe hacer?","o":["Jalar el volante de golpe hacia la vía","Soltar el acelerador, bajar la velocidad y volver suavemente","Frenar fuerte de inmediato","Acelerar y volver rápido a la vía"],"h1":"Piense en bajar la velocidad antes de volver a la vía.","h2":"Volver demasiado rápido puede hacerle perder el control, así que suelte el acelerador, baje la velocidad y vuelva suavemente al pavimento cuando sea seguro.","p":"Correcto. Primero baje la velocidad y luego vuelva suavemente."},"zh":{"q":"你右边的车轮偏出了路面，开到了泥土路边上。你应该怎么做？","o":["猛地把方向盘转回路上","慢慢松开油门，减速，然后轻轻地转回去","马上用力刹车","加速，快速转回去"],"h1":"想一想在回到路上之前先减速。","h2":"转回去太快会让你失去控制，所以要慢慢松开油门，减速，然后在安全时轻轻地把车转回路面。","p":"对。先减速，然后轻轻地转回去。"},"vi":{"q":"Bánh xe bên phải của bạn trôi ra khỏi mặt đường nhựa xuống lề đất. Bạn nên làm gì?","o":["Giật mạnh tay lái để quay lại đường","Nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại","Phanh mạnh ngay lập tức","Tăng tốc và lái trở lại thật nhanh"],"h1":"Hãy nghĩ đến việc giảm tốc trước khi quay lại đường.","h2":"Quay lại quá nhanh có thể làm bạn mất kiểm soát, nên hãy nhả ga từ từ, giảm tốc, rồi nhẹ nhàng lái trở lại mặt đường nhựa khi an toàn.","p":"Đúng. Giảm tốc trước, rồi nhẹ nhàng lái trở lại."},"tl":{"q":"Lumabas ang mga gulong mo sa kanan mula sa sementadong daan papunta sa lupang gilid. Ano ang dapat mong gawin?","o":["Biglang ibalik ang manibela papunta sa daan","Dahan-dahang bitawan ang gas, bumagal, saka marahang ibalik sa daan","Magpreno nang malakas agad","Bumilis at mabilis na ibalik sa daan"],"h1":"Isipin ang pagbagal bago ka bumalik sa daan.","h2":"Ang masyadong mabilis na pagbalik ay puwedeng magpawala ng kontrol mo, kaya dahan-dahang bitawan ang gas, bumagal, at saka marahang ibalik ang kotse sa sementadong daan kapag ligtas na.","p":"Tama. Bumagal muna, saka marahang bumalik sa daan."},"ar":{"q":"عجلاتك اليمنى خرجت عن الطريق المعبّد إلى الحافة الترابية. ماذا يجب أن تفعل؟","o":["أدِر المقود بقوة مفاجئة لتعود إلى الطريق","ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف","اضغط على الفرامل بقوة فورًا","أسرع وعُد بسرعة"],"h1":"فكّر في تخفيف السرعة قبل أن تعود إلى الطريق.","h2":"العودة بسرعة كبيرة قد تجعلك تفقد السيطرة، لذلك ارفع قدمك عن البنزين بهدوء، وخفّف السرعة، ثم عُد بلطف إلى الطريق المعبّد عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة أولًا، ثم عُد بلطف."},"ht":{"q":"Wou dwat ou yo soti sou asfalt la epi yo tonbe sou bò tè a. Kisa ou ta dwe fè?","o":["Vire volan an sèk pou retounen sou wout la","Leve pye ou sou gaz la, ralanti, epi retounen dousman","Frennen fò touswit","Akselere epi retounen vit"],"h1":"Panse ak ralanti anvan ou retounen sou wout la.","h2":"Si ou retounen twò vit, ou ka pèdi kontwòl, kidonk leve pye ou sou gaz la, ralanti, epi dirije machin nan dousman pou l retounen sou asfalt la lè li an sekirite.","p":"Se sa. Ralanti anvan, epi retounen dousman."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-026","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car stalls on railroad tracks and a train is coming. What should you do?","o":["Stay in the car and keep trying to start it","Get out and stand next to the car","Get everyone out and move away from the tracks toward the train at an angle","Get out and run straight down the tracks"],"h1":"Think about where pieces of the car could fly if the train hits it.","h2":"Get everyone out right away and move away from the tracks at an angle toward the train, so flying parts from the crash do not hit you.","p":"Right. Get out fast and move away at an angle toward the train."},"es":{"q":"Su carro se apaga sobre las vías del tren y viene un tren. ¿Qué debe hacer?","o":["Quedarse en el carro y tratar de encenderlo","Salir y quedarse al lado del carro","Sacar a todos y alejarse de las vías en diagonal hacia el tren","Salir y correr por encima de las vías"],"h1":"Piense en hacia dónde podrían volar las piezas del carro si el tren lo golpea.","h2":"Saque a todos de inmediato y aléjense de las vías en diagonal hacia donde viene el tren, para que las piezas que vuelen en el choque no los golpeen.","p":"Correcto. Salga rápido y aléjese en diagonal hacia el tren."},"zh":{"q":"你的车在铁轨上熄火了，有火车开过来。你应该怎么做？","o":["留在车里，一直试着发动","下车，站在车旁边","让所有人下车，朝火车来的方向斜着离开铁轨","下车，沿着铁轨直着跑"],"h1":"想一想火车撞到车时，车的碎片可能飞到哪里。","h2":"马上让所有人下车，朝火车来的方向斜着离开铁轨，这样撞击时飞出来的碎片才不会打到你。","p":"对。快点下车，朝火车来的方向斜着离开。"},"vi":{"q":"Xe của bạn bị chết máy trên đường ray xe lửa và có tàu đang tới. Bạn nên làm gì?","o":["Ở trong xe và tiếp tục cố nổ máy","Ra khỏi xe và đứng cạnh xe","Đưa mọi người ra ngoài và đi xa khỏi đường ray, chéo về phía tàu đang tới","Ra khỏi xe và chạy thẳng dọc theo đường ray"],"h1":"Hãy nghĩ xem các mảnh vỡ của xe có thể văng đi đâu nếu tàu đâm vào.","h2":"Đưa mọi người ra ngoài ngay và đi xa khỏi đường ray theo hướng chéo về phía tàu đang tới, để các mảnh vỡ văng ra từ vụ va chạm không trúng bạn.","p":"Đúng. Ra ngoài thật nhanh và đi xa theo hướng chéo về phía tàu."},"tl":{"q":"Namatay ang makina ng kotse mo sa riles ng tren at may paparating na tren. Ano ang dapat mong gawin?","o":["Manatili sa kotse at patuloy na subukang paandarin ito","Lumabas at tumayo sa tabi ng kotse","Palabasin ang lahat at lumayo sa riles nang pahilis, papunta sa direksyon ng tren","Lumabas at tumakbo nang diretso sa riles"],"h1":"Isipin kung saan puwedeng tumilapon ang mga piraso ng kotse kapag nabangga ito ng tren.","h2":"Palabasin agad ang lahat at lumayo sa riles nang pahilis papunta sa direksyon ng tren, para hindi kayo tamaan ng mga piraso na tumitilapon mula sa banggaan.","p":"Tama. Lumabas agad at lumayo nang pahilis papunta sa direksyon ng tren."},"ar":{"q":"سيارتك توقفت على سكة القطار والقطار قادم. ماذا يجب أن تفعل؟","o":["ابقَ في السيارة واستمر في محاولة تشغيلها","اخرج وقف بجانب السيارة","أخرِج الجميع وابتعدوا عن السكة بشكل مائل في اتجاه القطار","اخرج واركض على طول السكة مباشرة"],"h1":"فكّر: إلى أين قد تطير قطع السيارة إذا صدمها القطار؟","h2":"أخرِج الجميع فورًا وابتعدوا عن السكة بشكل مائل في اتجاه القطار، حتى لا تصيبكم القطع التي تطير من الاصطدام.","p":"صحيح. اخرج بسرعة وابتعد بشكل مائل في اتجاه القطار."},"ht":{"q":"Machin ou mouri sou ray tren an epi gen yon tren k ap vini. Kisa ou ta dwe fè?","o":["Rete nan machin nan epi kontinye eseye estat li","Desann epi kanpe bò kote machin nan","Fè tout moun desann epi kouri lwen ray yo an bivè, nan direksyon tren an","Desann epi kouri tou dwat sou ray yo"],"h1":"Panse ak ki kote moso machin nan ka vole si tren an frape l.","h2":"Fè tout moun desann touswit epi deplase lwen ray yo an bivè, nan direksyon tren k ap vini an, pou moso ki vole nan aksidan an pa frape w.","p":"Se sa. Desann vit epi ale lwen an bivè, nan direksyon tren an."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-027","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your car is stuck on railroad tracks, and no train is in sight. After everyone is out, who should you call?","o":["The number on the blue sign at the crossing, or 911","Your car insurance company","A tow truck, then wait in the car","Nobody, just keep trying to start the car"],"h1":"Think about who can warn the train before it arrives.","h2":"Get everyone out, then call the number on the blue emergency sign at the crossing or 911, so the railroad can stop or slow trains.","p":"Right. Call the number on the blue sign at the crossing, or 911."},"es":{"q":"Su carro está atascado en las vías del tren y no se ve ningún tren. Después de que todos salen, ¿a quién debe llamar?","o":["Al número del letrero azul del cruce, o al 911","A su compañía de seguros","A una grúa, y esperar dentro del carro","A nadie, solo seguir tratando de encenderlo"],"h1":"Piense en quién puede avisar al tren antes de que llegue.","h2":"Saque a todos y luego llame al número del letrero azul de emergencia del cruce o al 911, para que el ferrocarril pueda parar o frenar los trenes.","p":"Correcto. Llame al número del letrero azul del cruce, o al 911."},"zh":{"q":"你的车卡在铁轨上，看不到火车。所有人下车以后，你应该打电话给谁？","o":["道口蓝色牌子上的电话号码，或 911","你的汽车保险公司","拖车公司，然后在车里等","谁都不用打，只要一直试着发动车"],"h1":"想一想谁能在火车到来之前提醒火车。","h2":"让所有人下车，然后打道口蓝色紧急牌子上的电话号码或 911，这样铁路公司就能让火车停下或减速。","p":"对。打道口蓝色牌子上的电话号码，或 911。"},"vi":{"q":"Xe của bạn bị kẹt trên đường ray xe lửa, và chưa thấy tàu nào. Sau khi mọi người đã ra ngoài, bạn nên gọi cho ai?","o":["Số điện thoại trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911","Công ty bảo hiểm xe của bạn","Xe kéo, rồi ngồi chờ trong xe","Không gọi ai, cứ tiếp tục cố nổ máy"],"h1":"Hãy nghĩ xem ai có thể báo cho tàu trước khi tàu tới.","h2":"Đưa mọi người ra ngoài, rồi gọi số điện thoại trên biển khẩn cấp màu xanh dương ở chỗ đường ray cắt ngang hoặc gọi 911, để công ty đường sắt có thể dừng hoặc làm chậm tàu.","p":"Đúng. Gọi số trên biển màu xanh dương ở chỗ đường ray cắt ngang, hoặc 911."},"tl":{"q":"Naipit ang kotse mo sa riles ng tren, at walang tren na tanaw. Pagkalabas ng lahat, sino ang dapat mong tawagan?","o":["Ang numero sa asul na karatula sa tawiran, o 911","Ang car insurance company mo","Isang tow truck, saka maghintay sa loob ng kotse","Wala, patuloy lang na subukang paandarin ang kotse"],"h1":"Isipin kung sino ang makakapagbabala sa tren bago ito dumating.","h2":"Palabasin ang lahat, saka tawagan ang numero sa asul na emergency sign sa tawiran o ang 911, para mapahinto o mapabagal ng riles ang mga tren.","p":"Tama. Tawagan ang numero sa asul na karatula sa tawiran, o 911."},"ar":{"q":"سيارتك عالقة على سكة القطار، ولا يوجد قطار في الأفق. بعد أن يخرج الجميع، بمن يجب أن تتصل؟","o":["بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو 911","بشركة تأمين سيارتك","بشاحنة سحب، ثم انتظر في السيارة","لا أحد، فقط استمر في محاولة تشغيل السيارة"],"h1":"فكّر: من يستطيع أن يحذّر القطار قبل أن يصل؟","h2":"أخرِج الجميع، ثم اتصل بالرقم المكتوب على لافتة الطوارئ الزرقاء عند التقاطع أو بـ 911، حتى تستطيع شركة السكة الحديد أن توقف القطارات أو تخفّف سرعتها.","p":"صحيح. اتصل بالرقم المكتوب على اللافتة الزرقاء عند التقاطع، أو بـ 911."},"ht":{"q":"Machin ou bloke sou ray tren an, epi ou pa wè okenn tren. Apre tout moun fin desann, kiyès ou ta dwe rele?","o":["Nimewo ki sou pankat ble nan kwazman an, oswa 911","Konpayi asirans machin ou","Yon remòkè, epi tann nan machin nan","Pèsonn, jis kontinye eseye estat machin nan"],"h1":"Panse ak kiyès ki ka avèti tren an anvan li rive.","h2":"Fè tout moun desann, epi rele nimewo ki sou pankat ijans ble nan kwazman an oswa 911, pou konpayi tren an ka fè tren yo kanpe oswa ralanti.","p":"Se sa. Rele nimewo ki sou pankat ble nan kwazman an, oswa 911."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-028","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car goes into a canal or lake. What should you do first?","o":["Call for help and wait inside","Wait until the car fills with water","Turn on the hazard lights","Unbuckle, open a window and get out"],"h1":"Think about how fast you need to leave the car.","h2":"You should act right away: unbuckle your seat belt, open or break a window, and get out before the water gets too high.","p":"Right. Unbuckle, open a window and get out fast."},"es":{"q":"Su carro cae a un canal o a un lago. ¿Qué debe hacer primero?","o":["Pedir ayuda y esperar adentro","Esperar a que el carro se llene de agua","Encender las luces de emergencia","Quitarse el cinturón, abrir una ventana y salir"],"h1":"Piense en qué tan rápido debe salir del carro.","h2":"Debe actuar de inmediato: quítese el cinturón, abra o rompa una ventana y salga antes de que el agua suba demasiado.","p":"Correcto. Quítese el cinturón, abra una ventana y salga rápido."},"zh":{"q":"你的车开进了运河或湖里。你首先应该做什么？","o":["打电话求救，在车里等","等到车里灌满水","打开危险警示灯","解开安全带，打开车窗，出去"],"h1":"想一想你需要多快离开车。","h2":"你应该马上行动：解开安全带，打开或打破车窗，在水变得太高之前出去。","p":"对。解开安全带，打开车窗，快点出去。"},"vi":{"q":"Xe của bạn lao xuống kênh hoặc hồ. Bạn nên làm gì trước tiên?","o":["Gọi cứu giúp và chờ trong xe","Chờ đến khi xe đầy nước","Bật đèn khẩn cấp","Tháo dây an toàn, mở cửa sổ và ra ngoài"],"h1":"Hãy nghĩ xem bạn cần rời xe nhanh đến mức nào.","h2":"Bạn nên hành động ngay: tháo dây an toàn, mở hoặc đập vỡ cửa sổ, và ra ngoài trước khi nước dâng quá cao.","p":"Đúng. Tháo dây an toàn, mở cửa sổ và ra ngoài thật nhanh."},"tl":{"q":"Nahulog ang kotse mo sa kanal o lawa. Ano ang una mong dapat gawin?","o":["Tumawag ng tulong at maghintay sa loob","Maghintay hanggang mapuno ng tubig ang kotse","I-on ang hazard lights","Tanggalin ang seat belt, buksan ang bintana, at lumabas"],"h1":"Isipin kung gaano ka kabilis dapat umalis sa kotse.","h2":"Dapat kang kumilos agad: tanggalin ang seat belt mo, buksan o basagin ang bintana, at lumabas bago tumaas nang husto ang tubig.","p":"Tama. Tanggalin ang seat belt, buksan ang bintana, at lumabas agad."},"ar":{"q":"سيارتك وقعت في قناة ماء أو بحيرة. ماذا يجب أن تفعل أولًا؟","o":["اطلب المساعدة وانتظر في الداخل","انتظر حتى تمتلئ السيارة بالماء","شغّل أضواء التحذير","فُك الحزام، وافتح النافذة، واخرج"],"h1":"فكّر في السرعة التي تحتاجها لتترك السيارة.","h2":"يجب أن تتصرف فورًا: فُك حزام الأمان، وافتح النافذة أو اكسرها، واخرج قبل أن يرتفع الماء كثيرًا.","p":"صحيح. فُك الحزام، وافتح النافذة، واخرج بسرعة."},"ht":{"q":"Machin ou tonbe nan yon kanal oswa nan yon lak. Kisa ou ta dwe fè anvan?","o":["Rele pou èd epi tann andedan","Tann jiskaske machin nan plen dlo","Limen limyè ijans yo","Retire senti ou, louvri yon fenèt epi soti"],"h1":"Panse ak konbyen vit ou bezwen kite machin nan.","h2":"Ou ta dwe aji touswit: retire senti sekirite ou, louvri oswa kase yon fenèt, epi soti anvan dlo a monte twò wo.","p":"Se sa. Retire senti ou, louvri yon fenèt epi soti vit."},"ref":{"doc":"FL","page":80}},{"id":"safe-driving-029","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"After a hurricane, water covers the road ahead and you cannot see how deep it is. What should you do?","o":["Drive through it slowly","Turn around and find another way","Drive through it fast","Follow the car in front of you"],"h1":"Think about how little moving water it takes to move a car.","h2":"Even shallow moving water can sweep a car away, and you cannot see what is under it, so turn around and find another way.","p":"Right. Turn around and do not drive into flooded roads."},"es":{"q":"Después de un huracán, el agua cubre la calle adelante y no puede ver qué tan profunda es. ¿Qué debe hacer?","o":["Pasar despacio por el agua","Dar la vuelta y buscar otro camino","Pasar rápido por el agua","Seguir al carro de adelante"],"h1":"Piense en qué poca agua en movimiento basta para mover un carro.","h2":"Aun el agua poco profunda en movimiento puede arrastrar un carro, y usted no ve lo que hay debajo, así que dé la vuelta y busque otro camino.","p":"Correcto. Dé la vuelta y no maneje por calles inundadas."},"zh":{"q":"飓风过后，前面的路被水淹了，你看不出水有多深。你应该怎么做？","o":["慢慢开过去","掉头，找别的路","快速开过去","跟着前面的车开"],"h1":"想一想只要很少的流动的水就能冲走一辆车。","h2":"即使是很浅的流动的水也可能把车冲走，而且你看不到水下有什么，所以要掉头找别的路。","p":"对。掉头，不要开进被水淹的路。"},"vi":{"q":"Sau một cơn bão, nước ngập đường phía trước và bạn không thấy nước sâu bao nhiêu. Bạn nên làm gì?","o":["Lái chậm qua","Quay đầu và tìm đường khác","Lái nhanh qua","Đi theo xe phía trước"],"h1":"Hãy nghĩ xem chỉ cần một ít nước chảy là có thể cuốn trôi xe.","h2":"Ngay cả nước chảy nông cũng có thể cuốn trôi xe, và bạn không thấy được bên dưới có gì, nên hãy quay đầu và tìm đường khác.","p":"Đúng. Quay đầu và đừng lái vào đường bị ngập."},"tl":{"q":"Pagkatapos ng bagyo, may tubig na tumatakip sa daan sa unahan at hindi mo makita kung gaano ito kalalim. Ano ang dapat mong gawin?","o":["Dumaan dito nang dahan-dahan","Bumalik at maghanap ng ibang daan","Dumaan dito nang mabilis","Sundan ang kotse sa harap mo"],"h1":"Isipin kung gaano kaunting umaagos na tubig ang kailangan para matangay ang kotse.","h2":"Kahit mababaw na umaagos na tubig ay puwedeng tumangay ng kotse, at hindi mo nakikita kung ano ang nasa ilalim nito, kaya bumalik at maghanap ng ibang daan.","p":"Tama. Bumalik at huwag dumaan sa bahang daan."},"ar":{"q":"بعد إعصار، الماء يغطي الطريق أمامك ولا تستطيع أن ترى عمقه. ماذا يجب أن تفعل؟","o":["اعبره ببطء","ارجع وابحث عن طريق آخر","اعبره بسرعة","اتبع السيارة التي أمامك"],"h1":"فكّر: كم قليلًا من الماء الجاري يكفي لتحريك سيارة؟","h2":"حتى الماء الجاري غير العميق يمكن أن يجرف السيارة، ولا تستطيع أن ترى ما تحته، لذلك ارجع وابحث عن طريق آخر.","p":"صحيح. ارجع ولا تدخل الطرق المغمورة بالماء."},"ht":{"q":"Apre yon siklòn, dlo kouvri wout la devan w epi ou pa ka wè ki fon li ye. Kisa ou ta dwe fè?","o":["Travèse l dousman","Vire tounen epi chèche yon lòt chemen","Travèse l vit","Swiv machin ki devan w lan"],"h1":"Panse ak jan yon ti kras dlo k ap koule ase pou deplase yon machin.","h2":"Menm yon dlo ki pa fon, si l ap koule, ka pote yon machin ale, epi ou pa ka wè sa ki anba l, kidonk vire tounen epi chèche yon lòt chemen.","p":"Se sa. Vire tounen epi pa kondi antre nan wout ki inonde."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-030","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, after a storm, you reach an intersection where the traffic light is dark because the power is out. What should you do?","o":["Drive through without stopping","Stop only if a car is coming","Treat it like a four-way stop","Wait until the light works again"],"h1":"Think about how drivers take turns when there is no signal.","h2":"In Florida, a traffic light that is out works like a four-way stop, so you stop fully and take turns with the other drivers.","p":"Right. A dark traffic light works like a four-way stop."},"es":{"q":"En Florida, después de una tormenta, llega a un cruce donde el semáforo está apagado porque no hay luz. ¿Qué debe hacer?","o":["Pasar sin parar","Parar solo si viene un carro","Tratarlo como un pare de cuatro vías","Esperar hasta que el semáforo funcione"],"h1":"Piense en cómo se turnan los conductores cuando no hay semáforo.","h2":"En Florida, un semáforo apagado funciona como un pare de cuatro vías, así que debe parar por completo y turnarse con los otros conductores.","p":"Correcto. Un semáforo apagado funciona como un pare de cuatro vías."},"zh":{"q":"在 Florida，暴风雨过后，你到了一个路口，因为停电，红绿灯不亮了。你应该怎么做？","o":["不停车，直接开过去","只有在有车过来时才停车","把它当作四向停车路口","等到红绿灯恢复正常"],"h1":"想一想没有信号灯时，司机们怎样轮流通过。","h2":"在 Florida，不亮的红绿灯就像四向停车路口一样，所以你要完全停下，和其他司机轮流通过。","p":"对。不亮的红绿灯就像四向停车路口。"},"vi":{"q":"Ở Florida, sau một cơn bão, bạn đến một ngã tư mà đèn giao thông bị tắt vì mất điện. Bạn nên làm gì?","o":["Chạy qua mà không dừng","Chỉ dừng nếu có xe đang tới","Xem như ngã tư có biển STOP ở cả bốn hướng","Chờ đến khi đèn hoạt động lại"],"h1":"Hãy nghĩ xem các tài xế thay phiên nhau đi như thế nào khi không có đèn tín hiệu.","h2":"Ở Florida, đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng, nên bạn dừng hẳn lại và thay phiên đi với các tài xế khác.","p":"Đúng. Đèn giao thông bị tắt được xem như ngã tư có biển STOP ở cả bốn hướng."},"tl":{"q":"Sa Florida, pagkatapos ng bagyo, nakarating ka sa intersection kung saan patay ang traffic light dahil walang kuryente. Ano ang dapat mong gawin?","o":["Dumaan nang hindi humihinto","Huminto lang kung may paparating na kotse","Ituring itong four-way stop","Maghintay hanggang gumana ulit ang ilaw"],"h1":"Isipin kung paano nagsasalitan ang mga driver kapag walang signal.","h2":"Sa Florida, ang patay na traffic light ay gumagana na parang four-way stop, kaya huminto ka nang buo at makipagsalitan sa ibang mga driver.","p":"Tama. Ang patay na traffic light ay gumagana na parang four-way stop."},"ar":{"q":"في Florida، بعد عاصفة، وصلت إلى تقاطع إشارة المرور فيه مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["مُرّ بدون أن تتوقف","توقف فقط إذا كانت هناك سيارة قادمة","تعامل معه مثل تقاطع فيه توقف من أربع جهات","انتظر حتى تعمل الإشارة مرة أخرى"],"h1":"فكّر في كيف يتناوب السائقون عندما لا توجد إشارة.","h2":"في Florida، إشارة المرور المطفأة تعمل مثل تقاطع فيه توقف من أربع جهات، لذلك تتوقف توقفًا كاملًا وتتناوب مع السائقين الآخرين.","p":"صحيح. إشارة المرور المطفأة تعمل مثل توقف من أربع جهات."},"ht":{"q":"Nan Florida, apre yon tanpèt, ou rive nan yon kafou kote limyè trafik la etenn paske kouran an koupe. Kisa ou ta dwe fè?","o":["Pase san ou pa kanpe","Kanpe sèlman si gen yon machin k ap vini","Fè tankou se yon kafou ki gen STOP nan kat bò","Tann jiskaske limyè a mache ankò"],"h1":"Panse ak jan chofè yo pran tou yo lè pa gen siyal.","h2":"Nan Florida, yon limyè trafik ki pa mache travay tankou yon STOP nan kat bò, kidonk ou kanpe nèt epi ou pran tou pa w ak lòt chofè yo.","p":"Se sa. Yon limyè trafik ki etenn travay tankou yon STOP nan kat bò."},"ref":{"doc":"FL","page":79}},{"id":"safe-driving-031","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"At night, a car coming toward you has very bright headlights. Where should you look?","o":["Toward the right edge of your lane","Straight into the other car's lights","At the center line","Down at your dashboard"],"h1":"Think about a guide that keeps you in your lane without looking at the glare.","h2":"Looking toward the right edge of your lane keeps you on the road while you avoid looking straight into the glare.","p":"Right. Look toward the right edge of your lane to avoid glare."},"es":{"q":"De noche, un carro que viene hacia usted tiene las luces muy fuertes. ¿Hacia dónde debe mirar?","o":["Hacia la orilla derecha de su carril","Directo a las luces del otro carro","A la línea del centro","Hacia abajo, al tablero"],"h1":"Piense en una guía que lo mantenga en su carril sin mirar el resplandor.","h2":"Mirar hacia la orilla derecha de su carril lo mantiene en la vía mientras evita mirar directo al resplandor.","p":"Correcto. Mire hacia la orilla derecha de su carril para evitar el resplandor."},"zh":{"q":"晚上，对面开来的车车灯很亮。你应该看哪里？","o":["看向你车道的右边边缘","直直看着对面车的灯","看中线","往下看仪表板"],"h1":"想一想有什么能让你留在车道上，又不用看刺眼的光。","h2":"看向你车道的右边边缘，可以让你留在路上，同时避免直接看刺眼的光。","p":"对。看向你车道的右边边缘，避开刺眼的光。"},"vi":{"q":"Ban đêm, một xe đi ngược chiều có đèn pha rất sáng. Bạn nên nhìn về đâu?","o":["Về phía mép phải làn đường của bạn","Nhìn thẳng vào đèn của xe kia","Vào vạch giữa đường","Nhìn xuống bảng đồng hồ"],"h1":"Hãy nghĩ đến một điểm giúp bạn giữ đúng làn mà không phải nhìn vào ánh chói.","h2":"Nhìn về phía mép phải làn đường giúp bạn giữ xe trên đường mà không phải nhìn thẳng vào ánh chói.","p":"Đúng. Nhìn về phía mép phải làn đường để tránh ánh chói."},"tl":{"q":"Sa gabi, napakaliwanag ng headlights ng kotseng paparating sa iyo. Saan ka dapat tumingin?","o":["Sa kanang gilid ng lane mo","Diretso sa ilaw ng kabilang kotse","Sa center line (gitnang guhit)","Pababa sa dashboard mo"],"h1":"Isipin ang gabay na nagpapanatili sa iyo sa lane mo nang hindi tumitingin sa nakasisilaw na ilaw.","h2":"Ang pagtingin sa kanang gilid ng lane mo ay nagpapanatili sa iyo sa daan habang iniiwasan mong tumingin nang diretso sa nakasisilaw na ilaw.","p":"Tama. Tumingin sa kanang gilid ng lane mo para iwasan ang silaw."},"ar":{"q":"في الليل، سيارة قادمة نحوك أضواؤها قوية جدًا. إلى أين يجب أن تنظر؟","o":["نحو الحافة اليمنى لمسارك","مباشرة إلى أضواء السيارة الأخرى","إلى الخط الأوسط","إلى الأسفل نحو لوحة العدادات"],"h1":"فكّر في دليل يُبقيك في مسارك بدون أن تنظر إلى الضوء الساطع.","h2":"النظر نحو الحافة اليمنى لمسارك يُبقيك على الطريق، وفي نفس الوقت تتجنب النظر مباشرة إلى الضوء الساطع.","p":"صحيح. انظر نحو الحافة اليمنى لمسارك لتتجنب الضوء الساطع."},"ht":{"q":"Lannwit, yon machin k ap vini sou ou gen limyè devan ki klere anpil. Ki kote ou ta dwe gade?","o":["Bò dwat liy ou a","Dirèkteman nan limyè lòt machin nan","Liy ki nan mitan wout la","Anba, sou tablodbò ou"],"h1":"Panse ak yon gid ki kenbe w nan liy ou san ou pa gade nan limyè a ki ap avegle w.","h2":"Lè ou gade bò dwat liy ou a, ou rete sou wout la pandan ou evite gade dirèkteman nan limyè ki ap avegle w la.","p":"Se sa. Gade bò dwat liy ou a pou evite limyè a avegle w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-032","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, you are using high beams at night. When must you switch to low beams for a car coming toward you?","o":["Within 100 feet of it","Within 200 feet of it","Only when it flashes its lights","Within 500 feet of it"],"h1":"Think about a long distance, because bright lights reach far.","h2":"In Florida you must dim your high beams when an oncoming car is within 500 feet, so its driver is not blinded.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, usted usa las luces altas de noche. ¿Cuándo debe cambiar a luces bajas por un carro que viene de frente?","o":["A 100 pies de él","A 200 pies de él","Solo cuando le haga cambio de luces","A 500 pies de él"],"h1":"Piense en una distancia larga, porque las luces altas llegan lejos.","h2":"En Florida debe bajar las luces altas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Baje las luces altas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，你晚上开着远光灯。对面来车时，你必须在多远的距离内换成近光灯？","o":["在 100 英尺内","在 200 英尺内","只在它闪灯时","在 500 英尺内"],"h1":"想一想一个很长的距离，因为亮的灯照得很远。","h2":"在 Florida，对面来车在 500 英尺以内时，你必须把远光灯调暗，这样对面的司机才不会被照得看不见。","p":"对。对面来车在 500 英尺内时，把远光灯调暗。"},"vi":{"q":"Ở Florida, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần) vì có xe đi ngược chiều?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 200 feet","Chỉ khi xe đó nháy đèn","Khi cách xe đó trong vòng 500 feet"],"h1":"Hãy nghĩ đến một khoảng cách xa, vì đèn sáng chiếu được rất xa.","h2":"Ở Florida, bạn phải hạ đèn pha khi xe đi ngược chiều cách bạn trong vòng 500 feet, để tài xế kia không bị chói mắt.","p":"Đúng. Hạ đèn pha khi cách xe đi ngược chiều trong vòng 500 feet."},"tl":{"q":"Sa Florida, gumagamit ka ng high beams sa gabi. Kailan ka dapat lumipat sa low beams para sa kotseng paparating sa iyo?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 200 feet mula rito","Kapag nag-flash lang ito ng ilaw","Sa loob ng 500 feet mula rito"],"h1":"Isipin ang mahabang distansya, dahil malayo ang naaabot ng maliwanag na ilaw.","h2":"Sa Florida, dapat mong ibaba ang high beams mo kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi masilaw ang driver nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet mula sa paparating na kotse."},"ar":{"q":"في Florida، تستعمل الأضواء العالية في الليل. متى يجب أن تنتقل إلى الأضواء المنخفضة بسبب سيارة قادمة نحوك؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 200 قدم (feet) منها","فقط عندما تومض بأضوائها","عندما تكون على بعد 500 قدم (feet) منها"],"h1":"فكّر في مسافة طويلة، لأن الأضواء القوية تصل بعيدًا.","h2":"في Florida يجب أن تخفّض أضواءك العالية عندما تكون السيارة القادمة على بعد 500 قدم (feet)، حتى لا يُبهَر سائقها.","p":"صحيح. خفّض أضواءك العالية على بعد 500 قدم (feet) من السيارة القادمة."},"ht":{"q":"Nan Florida, w ap sèvi ak gwo limyè (high beams) lannwit. Ki lè ou dwe mete ti limyè (low beams) pou yon machin k ap vini sou ou?","o":["Lè li nan 100 pye","Lè li nan 200 pye","Sèlman lè li limen limyè li plizyè fwa","Lè li nan 500 pye"],"h1":"Panse ak yon long distans, paske limyè ki klere fò rive lwen.","h2":"Nan Florida, ou dwe bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye, pou chofè li a pa avegle.","p":"Se sa. Bese gwo limyè ou yo lè yon machin k ap vini sou ou nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-033","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are following another car at night. When must you use low beams?","o":["Within 100 feet of it","Within 300 feet of it","Within 1,000 feet of it","Only in the city"],"h1":"Think about your lights shining into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet behind another car, so your lights do not blind its driver in the mirrors.","p":"Right. Use low beams within 300 feet of the car ahead."},"es":{"q":"En Florida, usted va detrás de otro carro de noche. ¿Cuándo debe usar luces bajas?","o":["A 100 pies de él","A 300 pies de él","A 1,000 pies de él","Solo en la ciudad"],"h1":"Piense en sus luces brillando en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos detrás de otro carro, para que sus luces no encandilen al conductor en los espejos.","p":"Correcto. Use luces bajas a 300 pies del carro de adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面。你必须在多远的距离内用近光灯？","o":["在 100 英尺内","在 300 英尺内","在 1,000 英尺内","只在城市里"],"h1":"想一想你的车灯照进前面司机的后视镜。","h2":"在 Florida，当你在另一辆车后面 300 英尺以内时，必须用近光灯，这样你的灯光才不会通过后视镜晃到那位司机的眼睛。","p":"对。离前车 300 英尺以内时用近光灯。"},"vi":{"q":"Ở Florida, bạn đang chạy sau một xe khác vào ban đêm. Khi nào bạn phải dùng đèn cốt (đèn chiếu gần)?","o":["Khi cách xe đó trong vòng 100 feet","Khi cách xe đó trong vòng 300 feet","Khi cách xe đó trong vòng 1,000 feet","Chỉ trong thành phố"],"h1":"Hãy nghĩ đến đèn của bạn chiếu vào gương của tài xế kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi chạy sau một xe khác trong vòng 300 feet, để đèn của bạn không làm tài xế đó chói mắt qua gương.","p":"Đúng. Dùng đèn cốt khi cách xe phía trước trong vòng 300 feet."},"tl":{"q":"Sa Florida, sumusunod ka sa ibang kotse sa gabi. Kailan ka dapat gumamit ng low beams?","o":["Sa loob ng 100 feet mula rito","Sa loob ng 300 feet mula rito","Sa loob ng 1,000 feet mula rito","Sa lungsod lang"],"h1":"Isipin ang ilaw mo na tumatama sa mga salamin ng kabilang driver.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet sa likod ng ibang kotse, para hindi masilaw ang driver nito sa mga salamin.","p":"Tama. Gumamit ng low beams sa loob ng 300 feet mula sa kotse sa unahan."},"ar":{"q":"في Florida، أنت تسير خلف سيارة أخرى في الليل. متى يجب أن تستعمل الأضواء المنخفضة؟","o":["عندما تكون على بعد 100 قدم (feet) منها","عندما تكون على بعد 300 قدم (feet) منها","عندما تكون على بعد 1,000 قدم (feet) منها","في المدينة فقط"],"h1":"فكّر في أضوائك وهي تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على بعد 300 قدم (feet) خلف سيارة أخرى، حتى لا تُبهر أضواؤك سائقها في المرايا.","p":"صحيح. استعمل الأضواء المنخفضة على بعد 300 قدم (feet) من السيارة التي أمامك."},"ht":{"q":"Nan Florida, w ap swiv yon lòt machin lannwit. Ki lè ou dwe sèvi ak ti limyè (low beams)?","o":["Lè ou nan 100 pye dèyè l","Lè ou nan 300 pye dèyè l","Lè ou nan 1,000 pye dèyè l","Sèlman nan vil la"],"h1":"Panse ak limyè ou k ap klere nan retwovizè lòt chofè a.","h2":"Nan Florida, ou dwe sèvi ak ti limyè lè ou nan 300 pye dèyè yon lòt machin, pou limyè ou yo pa avegle chofè a nan retwovizè li yo.","p":"Se sa. Sèvi ak ti limyè lè ou nan 300 pye dèyè machin ki devan w lan."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-034","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"What does it mean to \"overdrive your headlights\" at night?","o":["Using high beams in the city","Driving with only parking lights on","Driving too fast to stop within the area your lights show","Leaving your lights on after you park"],"h1":"Think about how far ahead you can see at night.","h2":"If you drive so fast that you cannot stop within the distance your headlights light up, you are overdriving them, so slow down at night.","p":"Right. Drive slow enough to stop within what your headlights show."},"es":{"q":"¿Qué significa manejar más rápido de lo que alcanzan sus luces de noche?","o":["Usar luces altas en la ciudad","Manejar solo con luces de estacionamiento","Ir tan rápido que no puede parar dentro de lo que alumbran sus luces","Dejar las luces encendidas al estacionar"],"h1":"Piense en qué tan lejos puede ver de noche.","h2":"Si maneja tan rápido que no puede parar dentro de la distancia que alumbran sus faros, va más rápido de lo que alcanzan sus luces, así que baje la velocidad de noche.","p":"Correcto. Maneje a una velocidad que le permita parar dentro de lo que alumbran sus luces."},"zh":{"q":"晚上“开得比车灯照得更远”是什么意思？","o":["在城市里用远光灯","只开着停车灯开车","开得太快，无法在车灯照亮的范围内停下","停车后没有关车灯"],"h1":"想一想晚上你能看到前面多远。","h2":"如果你开得太快，在车头灯照亮的距离内停不下来，你就是开得比车灯照得更远，所以晚上要减速。","p":"对。开慢一点，要能在车头灯照到的范围内停下。"},"vi":{"q":"Ban đêm, \"chạy vượt tầm đèn pha\" (overdrive your headlights) có nghĩa là gì?","o":["Bật đèn pha trong thành phố","Lái xe chỉ bật đèn đậu xe","Lái quá nhanh nên không thể dừng trong vùng đèn chiếu tới","Để đèn sáng sau khi đậu xe"],"h1":"Hãy nghĩ xem ban đêm bạn nhìn thấy được xa đến đâu.","h2":"Nếu bạn lái nhanh đến mức không thể dừng trong khoảng đèn pha chiếu sáng, bạn đang chạy vượt tầm đèn pha, nên hãy chạy chậm lại vào ban đêm.","p":"Đúng. Lái đủ chậm để dừng được trong vùng đèn pha chiếu tới."},"tl":{"q":"Ano ang ibig sabihin ng \"overdrive your headlights\" sa gabi?","o":["Paggamit ng high beams sa lungsod","Pagmamaneho na parking lights lang ang nakabukas","Pagmamaneho nang masyadong mabilis para huminto sa loob ng lugar na naiilawan ng ilaw mo","Pag-iwan na nakabukas ang ilaw pagka-park mo"],"h1":"Isipin kung gaano kalayo sa unahan ang nakikita mo sa gabi.","h2":"Kung masyado kang mabilis kaya hindi ka makahinto sa loob ng distansyang naiilawan ng headlights mo, ikaw ay nag-o-overdrive ng headlights, kaya bumagal sa gabi.","p":"Tama. Magmaneho nang sapat na bagal para makahinto sa loob ng naiilawan ng headlights mo."},"ar":{"q":"ماذا يعني أن \"تسبق أضواءك\" في الليل؟","o":["أن تستعمل الأضواء العالية في المدينة","أن تقود وأضواء الوقوف فقط مشغّلة","أن تقود بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك","أن تترك أضواءك مشغّلة بعد أن توقف السيارة"],"h1":"فكّر: إلى أي مسافة أمامك تستطيع أن ترى في الليل؟","h2":"إذا قُدت بسرعة كبيرة لا تسمح لك بالتوقف داخل المسافة التي تضيئها أضواؤك الأمامية، فأنت تسبق أضواءك، لذلك خفّف السرعة في الليل.","p":"صحيح. قُد ببطء كافٍ لتتوقف داخل ما تُظهره أضواؤك الأمامية."},"ht":{"q":"Kisa sa vle di lè yo di w ap \"kondi pi vit pase limyè ou\" (overdrive your headlights) lannwit?","o":["Sèvi ak gwo limyè nan vil la","Kondi ak limyè pakin sèlman","Kondi twò vit pou w ka kanpe nan espas limyè ou montre w la","Kite limyè ou limen apre ou pake"],"h1":"Panse ak konbyen lwen devan ou ka wè lannwit.","h2":"Si w ap kondi tèlman vit ke ou pa ka kanpe nan distans limyè devan ou yo klere a, w ap kondi pi vit pase limyè ou, kidonk ralanti lannwit.","p":"Se sa. Kondi dousman ase pou w ka kanpe nan espas limyè devan ou yo montre w."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-035","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["Low beams","High beams","Parking lights only","No lights"],"h1":"Think about how bright light bounces back off fog.","h2":"High beams reflect off the fog and make it harder to see, so you should use low beams and slow down.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces bajas","Luces altas","Solo luces de estacionamiento","Ninguna luz"],"h1":"Piense en cómo la luz fuerte rebota en la neblina.","h2":"Las luces altas rebotan en la neblina y hacen más difícil ver, así que debe usar luces bajas y bajar la velocidad.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["近光灯","远光灯","只开停车灯","不开灯"],"h1":"想一想亮光碰到雾会怎样反射回来。","h2":"远光灯会被雾反射回来，让你更难看清，所以你应该用近光灯并减速。","p":"对。雾天用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn cốt (đèn chiếu gần)","Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Không bật đèn"],"h1":"Hãy nghĩ xem ánh sáng mạnh bị sương mù phản chiếu lại như thế nào.","h2":"Đèn pha phản chiếu lại từ sương mù và làm bạn khó nhìn hơn, nên bạn nên dùng đèn cốt và chạy chậm lại.","p":"Đúng. Dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["Low beams","High beams","Parking lights lang","Walang ilaw"],"h1":"Isipin kung paano tumatalbog pabalik ang maliwanag na ilaw mula sa fog.","h2":"Tumatalbog ang high beams sa fog at nagpapahirap makakita, kaya dapat kang gumamit ng low beams at bumagal.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"أنت تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء المنخفضة","الأضواء العالية","أضواء الوقوف فقط","بدون أضواء"],"h1":"فكّر في كيف يرتد الضوء القوي عن الضباب.","h2":"الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب، لذلك يجب أن تستعمل الأضواء المنخفضة وتخفّف السرعة.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Ti limyè (low beams)","Gwo limyè (high beams)","Limyè pakin sèlman","Okenn limyè"],"h1":"Panse ak jan limyè ki klere fò tounen sou bwouya a.","h2":"Gwo limyè yo frape bwouya a epi tounen sou ou, sa ki fè li pi difisil pou w wè, kidonk ou ta dwe sèvi ak ti limyè epi ralanti.","p":"Se sa. Sèvi ak ti limyè nan bwouya."},"ref":{"doc":"FL","page":71}},{"id":"safe-driving-036","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, it is raining and your wipers are on. What must you also turn on?","o":["Your hazard lights","Your high beams","Your inside dome light","Your headlights"],"h1":"Think about helping other drivers see your car in the rain.","h2":"In Florida you must turn on your headlights when you drive in rain, smoke or fog, so other drivers can see you.","p":"Right. In the rain, turn on your headlights."},"es":{"q":"En Florida, está lloviendo y tiene los limpiaparabrisas encendidos. ¿Qué más debe encender?","o":["Las luces de emergencia","Las luces altas","La luz interior del techo","Los faros delanteros"],"h1":"Piense en ayudar a otros conductores a ver su carro en la lluvia.","h2":"En Florida debe encender los faros delanteros cuando maneja con lluvia, humo o neblina, para que otros conductores lo vean.","p":"Correcto. Con lluvia, encienda los faros delanteros."},"zh":{"q":"在 Florida，正在下雨，你的雨刷开着。你还必须打开什么？","o":["你的危险警示灯","你的远光灯","车内顶灯","你的车头灯"],"h1":"想一想怎样帮助其他司机在雨中看到你的车。","h2":"在 Florida，你在雨中、烟中或雾中开车时，必须打开车头灯，这样其他司机才能看到你。","p":"对。下雨时，打开车头灯。"},"vi":{"q":"Ở Florida, trời đang mưa và cần gạt nước của bạn đang bật. Bạn còn phải bật gì nữa?","o":["Đèn khẩn cấp","Đèn pha (đèn chiếu xa)","Đèn trần trong xe","Đèn trước của xe"],"h1":"Hãy nghĩ đến việc giúp các tài xế khác nhìn thấy xe bạn trong mưa.","h2":"Ở Florida, bạn phải bật đèn trước khi lái xe trong mưa, khói hoặc sương mù, để các tài xế khác nhìn thấy bạn.","p":"Đúng. Khi trời mưa, hãy bật đèn trước."},"tl":{"q":"Sa Florida, umuulan at nakabukas ang wipers mo. Ano pa ang dapat mong i-on?","o":["Ang hazard lights mo","Ang high beams mo","Ang ilaw sa loob ng kotse","Ang headlights mo"],"h1":"Isipin ang pagtulong sa ibang driver na makita ang kotse mo sa ulan.","h2":"Sa Florida, dapat mong i-on ang headlights mo kapag nagmamaneho ka sa ulan, usok, o fog, para makita ka ng ibang mga driver.","p":"Tama. Sa ulan, i-on ang headlights mo."},"ar":{"q":"في Florida، المطر ينزل والمساحات تعمل. ماذا يجب أن تشغّل أيضًا؟","o":["أضواء التحذير","الأضواء العالية","الضوء الداخلي في السقف","الأضواء الأمامية"],"h1":"فكّر في مساعدة السائقين الآخرين على رؤية سيارتك في المطر.","h2":"في Florida يجب أن تشغّل الأضواء الأمامية عندما تقود في المطر أو الدخان أو الضباب، حتى يراك السائقون الآخرون.","p":"صحيح. في المطر، شغّل الأضواء الأمامية."},"ht":{"q":"Nan Florida, lapli ap tonbe epi wipè ou yo limen. Kisa ou dwe limen tou?","o":["Limyè ijans ou yo","Gwo limyè ou yo","Limyè andedan machin nan","Limyè devan ou yo"],"h1":"Panse ak ede lòt chofè yo wè machin ou nan lapli a.","h2":"Nan Florida, ou dwe limen limyè devan ou yo lè w ap kondi nan lapli, lafimen oswa bwouya, pou lòt chofè yo ka wè w.","p":"Se sa. Nan lapli, limen limyè devan ou yo."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-037","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"When is a road often most slippery during a rain?","o":["After it has rained for hours","In the first few minutes of rain","Only at night","Only when the sun comes out"],"h1":"Think about oil on the road mixing with the first water.","h2":"At the start of a rain, water mixes with oil on the road and makes it very slippery, so slow down as soon as it starts to rain.","p":"Right. Roads are often most slippery in the first minutes of rain."},"es":{"q":"¿Cuándo está la vía a menudo más resbalosa durante la lluvia?","o":["Después de horas de lluvia","En los primeros minutos de lluvia","Solo de noche","Solo cuando sale el sol"],"h1":"Piense en el aceite de la vía mezclándose con la primera agua.","h2":"Al comenzar la lluvia, el agua se mezcla con el aceite de la vía y la pone muy resbalosa, así que baje la velocidad en cuanto empiece a llover.","p":"Correcto. La vía suele estar más resbalosa en los primeros minutos de lluvia."},"zh":{"q":"下雨时，路面通常什么时候最滑？","o":["下了几个小时雨以后","下雨的头几分钟","只在晚上","只在太阳出来时"],"h1":"想一想路上的油和最先落下的雨水混在一起。","h2":"刚开始下雨时，雨水和路上的油混在一起，让路面非常滑，所以一开始下雨就要减速。","p":"对。路面通常在下雨的头几分钟最滑。"},"vi":{"q":"Khi trời mưa, mặt đường thường trơn nhất vào lúc nào?","o":["Sau khi mưa đã nhiều giờ","Trong vài phút đầu của cơn mưa","Chỉ vào ban đêm","Chỉ khi mặt trời ló ra"],"h1":"Hãy nghĩ đến dầu trên mặt đường trộn với lượng nước đầu tiên.","h2":"Lúc bắt đầu mưa, nước trộn với dầu trên mặt đường và làm đường rất trơn, nên hãy chạy chậm lại ngay khi trời bắt đầu mưa.","p":"Đúng. Mặt đường thường trơn nhất trong những phút đầu của cơn mưa."},"tl":{"q":"Kailan kadalasang pinakamadulas ang daan kapag umuulan?","o":["Pagkatapos umulan nang ilang oras","Sa unang ilang minuto ng ulan","Sa gabi lang","Kapag lumabas na ang araw lang"],"h1":"Isipin ang langis sa daan na humahalo sa unang tubig.","h2":"Sa simula ng ulan, humahalo ang tubig sa langis sa daan at nagiging napakadulas ito, kaya bumagal agad kapag nagsimulang umulan.","p":"Tama. Kadalasang pinakamadulas ang daan sa unang mga minuto ng ulan."},"ar":{"q":"متى يكون الطريق غالبًا أكثر انزلاقًا أثناء المطر؟","o":["بعد أن يمطر لساعات","في الدقائق الأولى من المطر","في الليل فقط","فقط عندما تخرج الشمس"],"h1":"فكّر في الزيت على الطريق عندما يختلط بأول ماء.","h2":"في بداية المطر، يختلط الماء بالزيت على الطريق ويجعله زلقًا جدًا، لذلك خفّف السرعة بمجرد أن يبدأ المطر.","p":"صحيح. الطرق غالبًا تكون أكثر انزلاقًا في الدقائق الأولى من المطر."},"ht":{"q":"Ki lè yon wout souvan pi glise pandan lapli?","o":["Apre lapli fin tonbe pandan plizyè èdtan","Nan premye minit lapli a","Sèlman lannwit","Sèlman lè solèy la parèt"],"h1":"Panse ak lwil ki sou wout la k ap melanje ak premye dlo a.","h2":"Lè lapli a kòmanse, dlo a melanje ak lwil ki sou wout la epi li fè wout la glise anpil, kidonk ralanti depi lapli a kòmanse tonbe.","p":"Se sa. Wout yo souvan pi glise nan premye minit lapli a."},"ref":{"doc":"FL","page":72}},{"id":"safe-driving-038","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You feel very sleepy while driving. What is the best thing to do?","o":["Open the window and keep going","Turn the radio up loud","Pull off safely and rest","Drink coffee and drive faster"],"h1":"Think about what really fixes being tired.","h2":"Cold air, loud music or coffee do not cure sleepiness, so the safe choice is to pull off the road safely and rest or sleep.","p":"Right. When you are sleepy, pull off safely and rest."},"es":{"q":"Siente mucho sueño mientras maneja. ¿Qué es lo mejor que puede hacer?","o":["Abrir la ventana y seguir","Subir el volumen de la radio","Salir de la vía con seguridad y descansar","Tomar café y manejar más rápido"],"h1":"Piense en lo que de verdad quita el cansancio.","h2":"El aire frío, la música fuerte o el café no quitan el sueño, así que lo seguro es salir de la vía con cuidado y descansar o dormir.","p":"Correcto. Si tiene sueño, salga de la vía con seguridad y descanse."},"zh":{"q":"你开车时觉得非常困。最好的做法是什么？","o":["打开车窗，继续开","把收音机开得很大声","安全地把车开到路边休息","喝咖啡，开快一点"],"h1":"想一想什么才能真正解决疲劳。","h2":"冷风、大声的音乐或咖啡都不能解决困倦，所以安全的做法是把车安全地开离道路，休息或睡一觉。","p":"对。困的时候，把车安全地开到路边休息。"},"vi":{"q":"Bạn thấy rất buồn ngủ khi đang lái xe. Điều tốt nhất nên làm là gì?","o":["Mở cửa sổ và lái tiếp","Mở radio thật lớn","Tấp vào lề an toàn và nghỉ ngơi","Uống cà phê và lái nhanh hơn"],"h1":"Hãy nghĩ xem điều gì thật sự giải quyết được sự mệt mỏi.","h2":"Không khí lạnh, nhạc lớn hay cà phê không chữa được buồn ngủ, nên cách an toàn là tấp vào lề an toàn và nghỉ ngơi hoặc ngủ.","p":"Đúng. Khi buồn ngủ, hãy tấp vào lề an toàn và nghỉ ngơi."},"tl":{"q":"Inaantok ka nang husto habang nagmamaneho. Ano ang pinakamabuting gawin?","o":["Buksan ang bintana at tumuloy","Lakasan ang radyo","Tumabi nang ligtas at magpahinga","Uminom ng kape at magmaneho nang mas mabilis"],"h1":"Isipin kung ano talaga ang nakakapagpawala ng pagod.","h2":"Hindi nagagamot ng malamig na hangin, malakas na musika, o kape ang antok, kaya ang ligtas na gawin ay tumabi nang ligtas sa daan at magpahinga o matulog.","p":"Tama. Kapag inaantok ka, tumabi nang ligtas at magpahinga."},"ar":{"q":"تشعر بنعاس شديد وأنت تقود. ما أفضل شيء تفعله؟","o":["افتح النافذة وتابع السير","ارفع صوت الراديو","اخرج من الطريق بأمان واسترح","اشرب قهوة وقُد بسرعة أكبر"],"h1":"فكّر في الشيء الذي يعالج التعب حقًا.","h2":"الهواء البارد أو الموسيقى العالية أو القهوة لا تعالج النعاس، لذلك الخيار الآمن هو أن تخرج من الطريق بأمان وتستريح أو تنام.","p":"صحيح. عندما تشعر بالنعاس، اخرج من الطريق بأمان واسترح."},"ht":{"q":"Ou santi w gen anpil dòmi pandan w ap kondi. Kisa ki pi bon bagay pou w fè?","o":["Louvri fenèt la epi kontinye","Mete radyo a fò","Soti sou bò wout la san danje epi repoze w","Bwè kafe epi kondi pi vit"],"h1":"Panse ak sa ki vrèman retire fatig.","h2":"Lè frèt, mizik fò oswa kafe pa retire dòmi, kidonk bon chwa a se soti sou bò wout la san danje epi repoze w oswa dòmi.","p":"Se sa. Lè ou gen dòmi, soti sou bò wout la san danje epi repoze w."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-039","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, what is the legal blood alcohol limit for drivers age 21 and older?","o":["0.08 percent","0.10 percent","0.05 percent","0.15 percent"],"h1":"Think about the limit used for adult drivers in Florida.","h2":"In Florida an adult driver with a blood alcohol level of 0.08 percent or more is driving under the influence.","p":"Right. For drivers 21 and older, the limit is 0.08 percent."},"es":{"q":"En Florida, ¿cuál es el límite legal de alcohol en la sangre para conductores de 21 años o más?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.15 por ciento"],"h1":"Piense en el límite que se usa para conductores adultos en Florida.","h2":"En Florida un conductor adulto con 0.08 por ciento o más de alcohol en la sangre está manejando bajo la influencia.","p":"Correcto. Para conductores de 21 años o más, el límite es 0.08 por ciento."},"zh":{"q":"在 Florida，21 岁及以上司机的法定血液酒精浓度上限是多少？","o":["0.08%","0.10%","0.05%","0.15%"],"h1":"想一想 Florida 成年司机用的上限。","h2":"在 Florida，成年司机的血液酒精浓度达到 0.08% 或更高，就是酒后驾驶。","p":"对。21 岁及以上的司机，上限是 0.08%。"},"vi":{"q":"Ở Florida, giới hạn nồng độ cồn trong máu theo luật cho tài xế từ 21 tuổi trở lên là bao nhiêu?","o":["0.08 phần trăm","0.10 phần trăm","0.05 phần trăm","0.15 phần trăm"],"h1":"Hãy nghĩ đến giới hạn dùng cho tài xế người lớn ở Florida.","h2":"Ở Florida, tài xế người lớn có nồng độ cồn trong máu từ 0.08 phần trăm trở lên là đang lái xe khi bị ảnh hưởng.","p":"Đúng. Với tài xế từ 21 tuổi trở lên, giới hạn là 0.08 phần trăm."},"tl":{"q":"Sa Florida, ano ang legal na blood alcohol limit para sa mga driver na 21 taong gulang pataas?","o":["0.08 porsyento","0.10 porsyento","0.05 porsyento","0.15 porsyento"],"h1":"Isipin ang limit na ginagamit para sa mga adult na driver sa Florida.","h2":"Sa Florida, ang adult na driver na may blood alcohol level na 0.08 porsyento o higit pa ay nagmamaneho nang lasing (DUI).","p":"Tama. Para sa mga driver na 21 pataas, ang limit ay 0.08 porsyento."},"ar":{"q":"في Florida، ما الحد القانوني لنسبة الكحول في الدم للسائقين الذين عمرهم 21 سنة أو أكثر؟","o":["0.08 بالمئة","0.10 بالمئة","0.05 بالمئة","0.15 بالمئة"],"h1":"فكّر في الحد المستعمل للسائقين البالغين في Florida.","h2":"في Florida، السائق البالغ الذي نسبة الكحول في دمه 0.08 بالمئة أو أكثر يقود تحت التأثير.","p":"صحيح. للسائقين بعمر 21 وأكثر، الحد هو 0.08 بالمئة."},"ht":{"q":"Nan Florida, ki limit legal alkòl nan san pou chofè ki gen 21 an oswa plis?","o":["0.08 pousan","0.10 pousan","0.05 pousan","0.15 pousan"],"h1":"Panse ak limit yo itilize pou chofè granmoun nan Florida.","h2":"Nan Florida, yon chofè granmoun ki gen yon nivo alkòl nan san 0.08 pousan oswa plis ap kondi sou enfliyans.","p":"Se sa. Pou chofè 21 an oswa plis, limit la se 0.08 pousan."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-040","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, a driver under age 21 has a blood alcohol level of 0.02 percent. What happens?","o":["Nothing, it is below the adult limit","Only a warning is given","The car is taken away","The driver's license is suspended"],"h1":"Think about the stricter rule for young drivers.","h2":"Florida has a zero tolerance rule for drivers under 21, so a level of 0.02 percent or more leads to a license suspension.","p":"Right. Under 21, a 0.02 percent level means a license suspension."},"es":{"q":"En Florida, un conductor menor de 21 años tiene 0.02 por ciento de alcohol en la sangre. ¿Qué pasa?","o":["Nada, está por debajo del límite de adultos","Solo recibe una advertencia","Le quitan el carro","Le suspenden la licencia de conducir"],"h1":"Piense en la regla más estricta para conductores jóvenes.","h2":"Florida tiene una regla de cero tolerancia para menores de 21 años, así que un nivel de 0.02 por ciento o más lleva a la suspensión de la licencia.","p":"Correcto. Menor de 21, un nivel de 0.02 por ciento significa suspensión de la licencia."},"zh":{"q":"在 Florida，一位 21 岁以下的司机血液酒精浓度是 0.02%。会怎么样？","o":["什么事也没有，因为低于成年人的上限","只会给一个警告","车会被拿走","司机的驾照会被暂停"],"h1":"想一想对年轻司机更严格的规定。","h2":"Florida 对 21 岁以下的司机实行零容忍规定，所以浓度达到 0.02% 或更高，驾照就会被暂停。","p":"对。21 岁以下，浓度 0.02% 就会暂停驾照。"},"vi":{"q":"Ở Florida, một tài xế dưới 21 tuổi có nồng độ cồn trong máu là 0.02 phần trăm. Điều gì xảy ra?","o":["Không có gì, vì thấp hơn giới hạn của người lớn","Chỉ bị cảnh cáo","Xe bị tịch thu","Bằng lái của tài xế bị đình chỉ"],"h1":"Hãy nghĩ đến quy định nghiêm hơn cho tài xế trẻ.","h2":"Florida có quy định không khoan nhượng với tài xế dưới 21 tuổi, nên mức 0.02 phần trăm trở lên sẽ dẫn đến bị đình chỉ bằng lái.","p":"Đúng. Dưới 21 tuổi, mức 0.02 phần trăm nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Florida, ang driver na wala pang 21 taong gulang ay may blood alcohol level na 0.02 porsyento. Ano ang mangyayari?","o":["Wala, mas mababa ito sa limit ng adult","Warning lang ang ibibigay","Kukunin ang kotse","Masususpinde ang lisensya ng driver"],"h1":"Isipin ang mas mahigpit na patakaran para sa mga batang driver.","h2":"May zero tolerance rule ang Florida para sa mga driver na wala pang 21, kaya ang level na 0.02 porsyento o higit pa ay nauuwi sa suspensyon ng lisensya.","p":"Tama. Kapag wala pang 21, ang level na 0.02 porsyento ay suspensyon ng lisensya."},"ar":{"q":"في Florida، سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة. ماذا يحدث؟","o":["لا شيء، النسبة أقل من حد البالغين","يُعطى تحذيرًا فقط","تُؤخذ منه السيارة","تُوقف رخصة السائق"],"h1":"فكّر في القاعدة الأشد للسائقين الصغار.","h2":"في Florida قاعدة عدم التسامح مطلقًا للسائقين تحت 21 سنة، لذلك نسبة 0.02 بالمئة أو أكثر تؤدي إلى إيقاف الرخصة.","p":"صحيح. تحت 21 سنة، نسبة 0.02 بالمئة تعني إيقاف الرخصة."},"ht":{"q":"Nan Florida, yon chofè ki poko gen 21 an gen yon nivo alkòl nan san 0.02 pousan. Kisa k rive?","o":["Anyen, li anba limit granmoun yo","Yo ba l yon avètisman sèlman","Yo pran machin nan","Yo sispann lisans kondi chofè a"],"h1":"Panse ak règ ki pi sevè pou jèn chofè yo.","h2":"Florida gen yon règ zewo tolerans pou chofè ki poko gen 21 an, kidonk yon nivo 0.02 pousan oswa plis mennen nan yon sispansyon lisans.","p":"Se sa. Anba 21 an, yon nivo 0.02 pousan vle di yo sispann lisans ou."},"ref":{"doc":"FL","page":26}},{"id":"safe-driving-041","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you are lawfully arrested for DUI and refuse a breath test for the first time. What happens to your license?","o":["Nothing happens to it","It is suspended for one year","It is suspended for one week","You get a warning letter only"],"h1":"Think about what you agreed to when you got a Florida license.","h2":"By driving in Florida you agree to be tested, so a first refusal after a lawful DUI arrest suspends your license for one year.","p":"Right. A first refusal suspends your license for one year."},"es":{"q":"En Florida, usted es arrestado legalmente por DUI y se niega por primera vez a una prueba de aliento. ¿Qué pasa con su licencia?","o":["No le pasa nada","La suspenden por un año","La suspenden por una semana","Solo recibe una carta de advertencia"],"h1":"Piense en lo que aceptó cuando recibió una licencia de Florida.","h2":"Al manejar en Florida usted acepta hacerse la prueba, así que negarse por primera vez después de un arresto legal por DUI suspende su licencia por un año.","p":"Correcto. Negarse la primera vez suspende su licencia por un año."},"zh":{"q":"在 Florida，你因酒后驾驶 (DUI) 被合法逮捕，第一次拒绝呼气检测。你的驾照会怎么样？","o":["没有任何影响","被暂停一年","被暂停一个星期","你只会收到一封警告信"],"h1":"想一想你拿到 Florida 驾照时同意了什么。","h2":"在 Florida 开车，就表示你同意接受检测，所以在因 DUI 被合法逮捕后第一次拒绝，你的驾照会被暂停一年。","p":"对。第一次拒绝，驾照暂停一年。"},"vi":{"q":"Ở Florida, bạn bị bắt hợp pháp vì lái xe khi say (DUI) và từ chối thổi nồng độ cồn lần đầu. Bằng lái của bạn bị xử lý thế nào?","o":["Không có gì xảy ra","Bị đình chỉ một năm","Bị đình chỉ một tuần","Bạn chỉ nhận một thư cảnh cáo"],"h1":"Hãy nghĩ xem bạn đã đồng ý điều gì khi nhận bằng lái Florida.","h2":"Khi lái xe ở Florida, bạn đồng ý được kiểm tra, nên từ chối lần đầu sau khi bị bắt hợp pháp vì DUI sẽ làm bằng lái của bạn bị đình chỉ một năm.","p":"Đúng. Từ chối lần đầu làm bằng lái bị đình chỉ một năm."},"tl":{"q":"Sa Florida, legal kang inaresto dahil sa DUI at tumanggi ka sa breath test sa unang beses. Ano ang mangyayari sa lisensya mo?","o":["Walang mangyayari rito","Masususpinde ito nang isang taon","Masususpinde ito nang isang linggo","Warning letter lang ang matatanggap mo"],"h1":"Isipin kung ano ang pinayagan mo nang makakuha ka ng Florida license.","h2":"Sa pagmamaneho sa Florida, pumapayag kang ma-test, kaya ang unang pagtanggi pagkatapos ng legal na pag-aresto dahil sa DUI ay magsususpinde sa lisensya mo nang isang taon.","p":"Tama. Ang unang pagtanggi ay magsususpinde sa lisensya mo nang isang taon."},"ar":{"q":"في Florida، اعتُقلت بشكل قانوني بسبب القيادة تحت التأثير (DUI) ورفضت فحص النَّفَس للمرة الأولى. ماذا يحدث لرخصتك؟","o":["لا يحدث لها شيء","تُوقف لمدة سنة واحدة","تُوقف لمدة أسبوع واحد","تحصل على رسالة تحذير فقط"],"h1":"فكّر في ما وافقت عليه عندما حصلت على رخصة Florida.","h2":"بمجرد أنك تقود في Florida أنت توافق على الفحص، لذلك الرفض الأول بعد اعتقال قانوني بسبب DUI يوقف رخصتك لمدة سنة واحدة.","p":"صحيح. الرفض الأول يوقف رخصتك لمدة سنة واحدة."},"ht":{"q":"Nan Florida, yo arete w legalman pou DUI (kondi sou enfliyans) epi ou refize yon tès souf pou premye fwa. Kisa k rive lisans ou?","o":["Anyen pa rive l","Yo sispann li pou yon ane","Yo sispann li pou yon semèn","Ou jwenn yon lèt avètisman sèlman"],"h1":"Panse ak sa ou te dakò lè ou te jwenn yon lisans Florida.","h2":"Lè ou kondi nan Florida, ou dakò pou yo teste w, kidonk yon premye refi apre yon arestasyon legal pou DUI fè yo sispann lisans ou pou yon ane.","p":"Se sa. Yon premye refi fè yo sispann lisans ou pou yon ane."},"ref":{"doc":"FL","page":25}},{"id":"safe-driving-042","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Which is the first thing alcohol harms in a driver?","o":["Hearing","Hand strength","Judgment","Eyesight in daylight"],"h1":"Think about making good choices, like deciding whether to drive.","h2":"Alcohol affects judgment first, so a driver may feel fine and still make bad choices, like speeding or deciding to drive at all.","p":"Right. Alcohol harms judgment first."},"es":{"q":"¿Qué es lo primero que el alcohol afecta en un conductor?","o":["El oído","La fuerza de las manos","El juicio","La vista de día"],"h1":"Piense en tomar buenas decisiones, como decidir si manejar.","h2":"El alcohol afecta primero el juicio, así que un conductor puede sentirse bien y aun así tomar malas decisiones, como ir rápido o decidir manejar.","p":"Correcto. El alcohol afecta primero el juicio."},"zh":{"q":"酒精首先伤害司机的哪一方面？","o":["听力","手的力气","判断力","白天的视力"],"h1":"想一想做出好的决定，例如决定要不要开车。","h2":"酒精首先影响判断力，所以司机可能觉得自己没事，但还是会做出坏的决定，例如超速，或者决定开车。","p":"对。酒精首先伤害判断力。"},"vi":{"q":"Rượu bia ảnh hưởng đến điều gì của tài xế đầu tiên?","o":["Thính giác","Sức mạnh của tay","Khả năng phán đoán","Thị lực vào ban ngày"],"h1":"Hãy nghĩ đến việc đưa ra lựa chọn đúng, như quyết định có nên lái xe hay không.","h2":"Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên, nên tài xế có thể thấy mình vẫn ổn mà vẫn đưa ra lựa chọn sai, như chạy quá tốc độ hoặc quyết định lái xe.","p":"Đúng. Rượu bia ảnh hưởng đến khả năng phán đoán đầu tiên."},"tl":{"q":"Ano ang unang napipinsala ng alak sa isang driver?","o":["Pandinig","Lakas ng kamay","Paghuhusga (judgment)","Paningin sa araw"],"h1":"Isipin ang paggawa ng mabuting desisyon, gaya ng pagpapasya kung magmamaneho ka.","h2":"Ang paghuhusga ang unang naaapektuhan ng alak, kaya puwedeng pakiramdam ng driver ay ayos lang siya pero gumagawa pa rin siya ng maling desisyon, gaya ng pag-overspeed o ng pagpapasyang magmaneho pa.","p":"Tama. Ang paghuhusga ang unang napipinsala ng alak."},"ar":{"q":"ما أول شيء يضرّه الكحول عند السائق؟","o":["السمع","قوة اليدين","حُسن التقدير","النظر في ضوء النهار"],"h1":"فكّر في اتخاذ القرارات الجيدة، مثل أن تقرر هل تقود أم لا.","h2":"الكحول يؤثر أولًا على حُسن التقدير، لذلك قد يشعر السائق أنه بخير ومع ذلك يتخذ قرارات سيئة، مثل السرعة أو أن يقرر القيادة أصلًا.","p":"صحيح. الكحول يضرّ حُسن التقدير أولًا."},"ht":{"q":"Ki premye bagay alkòl fè mal nan yon chofè?","o":["Zòrèy li (tande)","Fòs men li","Jijman li","Je li lajounen"],"h1":"Panse ak fè bon chwa, tankou deside si pou w kondi.","h2":"Alkòl touche jijman an anvan, kidonk yon chofè ka santi l byen epi li toujou fè move chwa, tankou kouri twò vit oswa deside kondi ditou.","p":"Se sa. Alkòl fè jijman an mal anvan."},"ref":{"doc":"FL","page":35}},{"id":"safe-driving-043","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"After drinking, what is the only thing that makes you sober?","o":["Time","Black coffee","A cold shower","Fresh air"],"h1":"Think about how the body gets rid of alcohol.","h2":"Your body removes alcohol slowly on its own, so only time makes you sober; coffee, showers and fresh air do not.","p":"Right. Only time makes you sober."},"es":{"q":"Después de tomar alcohol, ¿qué es lo único que le quita la borrachera?","o":["El tiempo","El café negro","Una ducha fría","El aire fresco"],"h1":"Piense en cómo el cuerpo elimina el alcohol.","h2":"Su cuerpo elimina el alcohol poco a poco por sí solo, así que solo el tiempo le quita la borrachera; el café, la ducha y el aire fresco no.","p":"Correcto. Solo el tiempo le quita la borrachera."},"zh":{"q":"喝酒以后，唯一能让你清醒的是什么？","o":["时间","黑咖啡","冷水澡","新鲜空气"],"h1":"想一想身体怎样排出酒精。","h2":"你的身体会自己慢慢排出酒精，所以只有时间能让你清醒；咖啡、洗澡和新鲜空气都不行。","p":"对。只有时间能让你清醒。"},"vi":{"q":"Sau khi uống rượu bia, điều duy nhất làm bạn tỉnh lại là gì?","o":["Thời gian","Cà phê đen","Tắm nước lạnh","Không khí trong lành"],"h1":"Hãy nghĩ xem cơ thể loại bỏ rượu bia như thế nào.","h2":"Cơ thể bạn tự loại bỏ rượu bia một cách chậm rãi, nên chỉ có thời gian mới làm bạn tỉnh; cà phê, tắm và không khí trong lành thì không.","p":"Đúng. Chỉ có thời gian mới làm bạn tỉnh."},"tl":{"q":"Pagkatapos uminom ng alak, ano lang ang tanging nakakapagpawala ng pagkalasing?","o":["Oras","Black coffee","Malamig na paligo","Sariwang hangin"],"h1":"Isipin kung paano inaalis ng katawan ang alak.","h2":"Dahan-dahang inaalis ng katawan mo ang alak nang kusa, kaya oras lang ang nakakapagpawala ng pagkalasing; hindi ito nagagawa ng kape, paligo, o sariwang hangin.","p":"Tama. Oras lang ang nakakapagpawala ng pagkalasing."},"ar":{"q":"بعد شرب الكحول، ما الشيء الوحيد الذي يجعلك تصحو؟","o":["الوقت","القهوة السوداء","الاستحمام بماء بارد","الهواء النقي"],"h1":"فكّر في كيف يتخلص الجسم من الكحول.","h2":"جسمك يتخلص من الكحول ببطء وحده، لذلك الوقت فقط يجعلك تصحو؛ القهوة والاستحمام والهواء النقي لا تفعل ذلك.","p":"صحيح. الوقت فقط يجعلك تصحو."},"ht":{"q":"Apre ou fin bwè, ki sèl bagay ki fè w pa sou ankò?","o":["Tan","Kafe nwa","Yon douch frèt","Bon lè fre"],"h1":"Panse ak jan kò a retire alkòl la.","h2":"Kò ou retire alkòl la dousman pou kont li, kidonk se sèlman tan ki fè w pa sou ankò; kafe, douch ak bon lè fre pa fè sa.","p":"Se sa. Se sèlman tan ki fè w pa sou ankò."}},{"id":"safe-driving-044","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You took a cold medicine you bought at the store. What should you do before you drive?","o":["Nothing, store medicines are always safe","Drive only on small streets","Drink coffee to stay awake","Read the label for warnings about drowsiness"],"h1":"Think about side effects that can make you sleepy.","h2":"Many medicines you buy without a prescription can make you sleepy or slow, so read the label and do not drive if it warns about drowsiness.","p":"Right. Read the label and do not drive if the medicine makes you drowsy."},"es":{"q":"Usted tomó una medicina para el resfriado que compró en la tienda. ¿Qué debe hacer antes de manejar?","o":["Nada, las medicinas de tienda siempre son seguras","Manejar solo por calles pequeñas","Tomar café para no dormirse","Leer la etiqueta por advertencias de sueño"],"h1":"Piense en efectos que le pueden dar sueño.","h2":"Muchas medicinas que se compran sin receta pueden darle sueño o hacerlo más lento, así que lea la etiqueta y no maneje si advierte que causa sueño.","p":"Correcto. Lea la etiqueta y no maneje si la medicina le da sueño."},"zh":{"q":"你吃了在商店买的感冒药。开车前你应该做什么？","o":["什么都不用做，商店买的药都是安全的","只在小街上开","喝咖啡保持清醒","看标签上有没有会让人犯困的警告"],"h1":"想一想可能让你犯困的副作用。","h2":"很多不用处方就能买的药会让你犯困或反应变慢，所以要看标签，如果警告会犯困，就不要开车。","p":"对。看标签，如果药会让你犯困，就不要开车。"},"vi":{"q":"Bạn đã uống thuốc cảm mua ở cửa hàng. Bạn nên làm gì trước khi lái xe?","o":["Không cần gì, thuốc mua ở cửa hàng luôn an toàn","Chỉ lái trên đường nhỏ","Uống cà phê để tỉnh táo","Đọc nhãn thuốc xem có cảnh báo gây buồn ngủ không"],"h1":"Hãy nghĩ đến tác dụng phụ có thể làm bạn buồn ngủ.","h2":"Nhiều loại thuốc mua không cần toa có thể làm bạn buồn ngủ hoặc chậm chạp, nên hãy đọc nhãn và đừng lái xe nếu nhãn cảnh báo gây buồn ngủ.","p":"Đúng. Đọc nhãn thuốc và đừng lái xe nếu thuốc làm bạn buồn ngủ."},"tl":{"q":"Uminom ka ng gamot sa sipon na binili mo sa tindahan. Ano ang dapat mong gawin bago magmaneho?","o":["Wala, laging ligtas ang mga gamot sa tindahan","Magmaneho lang sa maliliit na kalye","Uminom ng kape para manatiling gising","Basahin ang label para sa babala tungkol sa pag-aantok"],"h1":"Isipin ang mga side effect na puwedeng magpaantok sa iyo.","h2":"Maraming gamot na nabibili nang walang reseta ang puwedeng magpaantok o magpabagal sa iyo, kaya basahin ang label at huwag magmaneho kung may babala ito tungkol sa pag-aantok.","p":"Tama. Basahin ang label at huwag magmaneho kung nakakaantok ang gamot."},"ar":{"q":"أخذت دواءً للزكام اشتريته من المتجر. ماذا يجب أن تفعل قبل أن تقود؟","o":["لا شيء، أدوية المتجر آمنة دائمًا","قُد في الشوارع الصغيرة فقط","اشرب قهوة لتبقى مستيقظًا","اقرأ الملصق لترى تحذيرات عن النعاس"],"h1":"فكّر في الآثار الجانبية التي قد تجعلك نعسانًا.","h2":"أدوية كثيرة تشتريها بدون وصفة طبية قد تجعلك نعسانًا أو بطيئًا، لذلك اقرأ الملصق ولا تقُد إذا كان يحذّر من النعاس.","p":"صحيح. اقرأ الملصق ولا تقُد إذا كان الدواء يجعلك نعسانًا."},"ht":{"q":"Ou pran yon remèd pou grip ou te achte nan magazen. Kisa ou ta dwe fè anvan ou kondi?","o":["Anyen, remèd magazen toujou san danje","Kondi sèlman nan ti lari","Bwè kafe pou w rete reveye","Li etikèt la pou wè si gen avètisman sou dòmi"],"h1":"Panse ak efè segondè ki ka ba w dòmi.","h2":"Anpil remèd ou achte san preskripsyon ka ba w dòmi oswa fè w vin lan, kidonk li etikèt la epi pa kondi si li avèti w sou dòmi.","p":"Se sa. Li etikèt la epi pa kondi si remèd la ba w dòmi."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-045","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"An angry driver is tailgating you and making rude gestures. What should you do?","o":["Brake suddenly to teach a lesson","Avoid eye contact and let the driver pass","Make the same gestures back","Speed up to get away"],"h1":"Think about how to calm the situation, not make it bigger.","h2":"Reacting can make an angry driver more dangerous, so stay calm, avoid eye contact, and let the driver go by when it is safe.","p":"Right. Stay calm, avoid eye contact and let the driver pass."},"es":{"q":"Un conductor enojado lo sigue muy de cerca y le hace gestos groseros. ¿Qué debe hacer?","o":["Frenar de repente para darle una lección","Evitar mirarlo a los ojos y dejarlo pasar","Hacerle los mismos gestos","Acelerar para alejarse"],"h1":"Piense en cómo calmar la situación, no en hacerla más grande.","h2":"Responder puede hacer más peligroso a un conductor enojado, así que mantenga la calma, evite mirarlo a los ojos y déjelo pasar cuando sea seguro.","p":"Correcto. Mantenga la calma, no lo mire a los ojos y déjelo pasar."},"zh":{"q":"一个生气的司机紧跟在你后面，还做粗鲁的手势。你应该怎么做？","o":["突然刹车给他一个教训","避免和他对视，让他超过去","也对他做同样的手势","加速开走"],"h1":"想一想怎样让情况冷静下来，而不是变得更糟。","h2":"作出反应可能会让生气的司机更危险，所以要保持冷静，避免对视，在安全时让他过去。","p":"对。保持冷静，避免对视，让那位司机超过去。"},"vi":{"q":"Một tài xế đang tức giận bám sát đuôi xe bạn và làm cử chỉ thô lỗ. Bạn nên làm gì?","o":["Phanh gấp để dạy cho họ một bài học","Tránh nhìn vào mắt và để tài xế đó vượt qua","Làm lại cử chỉ giống vậy","Tăng tốc để chạy thoát"],"h1":"Hãy nghĩ cách làm tình huống dịu đi, không làm nó lớn hơn.","h2":"Phản ứng lại có thể làm tài xế đang tức giận nguy hiểm hơn, nên hãy giữ bình tĩnh, tránh nhìn vào mắt, và để tài xế đó đi qua khi an toàn.","p":"Đúng. Giữ bình tĩnh, tránh nhìn vào mắt và để tài xế đó vượt qua."},"tl":{"q":"Isang galit na driver ang dikit na dikit sa likod mo at gumagawa ng bastos na senyas. Ano ang dapat mong gawin?","o":["Biglang magpreno para turuan siya ng leksyon","Iwasang tumingin sa mata niya at hayaan siyang lumampas","Gumawa rin ng parehong senyas pabalik","Bumilis para makalayo"],"h1":"Isipin kung paano pakakalmahin ang sitwasyon, hindi palalakihin.","h2":"Ang pagpatol ay puwedeng gawing mas mapanganib ang galit na driver, kaya manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas kapag ligtas.","p":"Tama. Manatiling kalmado, iwasang tumingin sa mata niya, at hayaan siyang lumampas."},"ar":{"q":"سائق غاضب يلتصق بك من الخلف ويقوم بحركات وقحة. ماذا يجب أن تفعل؟","o":["اضغط الفرامل فجأة لتعلّمه درسًا","تجنّب النظر في عينيه واتركه يتجاوزك","قُم بنفس الحركات له","أسرع لتبتعد عنه"],"h1":"فكّر في كيف تهدّئ الموقف، لا كيف تجعله أكبر.","h2":"الرد قد يجعل السائق الغاضب أخطر، لذلك ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يمرّ عندما يكون ذلك آمنًا.","p":"صحيح. ابقَ هادئًا، وتجنّب النظر في عينيه، واتركه يتجاوزك."},"ht":{"q":"Yon chofè ki fache ap kole dèyè w epi l ap fè move jès. Kisa ou ta dwe fè?","o":["Frennen sanzatann pou ba l yon leson","Pa gade l nan je epi kite chofè a pase","Fè l menm jès yo tou","Akselere pou w chape"],"h1":"Panse ak kijan pou w kalme sitiyasyon an, pa fè l vin pi gwo.","h2":"Si ou reyaji, yon chofè ki fache ka vin pi danjere, kidonk rete kalm, pa gade l nan je, epi kite chofè a pase lè li an sekirite.","p":"Se sa. Rete kalm, pa gade l nan je epi kite chofè a pase."},"ref":{"doc":"FL","page":36}},{"id":"safe-driving-046","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"An angry driver keeps following you. Where should you drive?","o":["Straight to your home","To a quiet dead-end street","To a police station or busy public place","Onto the shoulder to stop and talk"],"h1":"Think about a place where people can help you.","h2":"You should not lead an angry driver to your home, so drive to a police station or a busy public place and call 911 if needed.","p":"Right. Drive to a police station or a busy public place."},"es":{"q":"Un conductor enojado lo sigue y no lo deja. ¿Hacia dónde debe manejar?","o":["Directo a su casa","A una calle sin salida y tranquila","A una estación de policía o un lugar público con gente","Al acotamiento para parar y hablar"],"h1":"Piense en un lugar donde la gente pueda ayudarle.","h2":"No debe llevar a un conductor enojado hasta su casa, así que maneje a una estación de policía o a un lugar público con gente y llame al 911 si hace falta.","p":"Correcto. Maneje a una estación de policía o a un lugar público con gente."},"zh":{"q":"一个生气的司机一直跟着你。你应该开到哪里？","o":["直接开回家","开到安静的死胡同","开到警察局或人多的公共场所","开到路肩停下来和他说话"],"h1":"想一想有人能帮你的地方。","h2":"你不应该把生气的司机带到你家，所以要开到警察局或人多的公共场所，需要时打 911。","p":"对。开到警察局或人多的公共场所。"},"vi":{"q":"Một tài xế đang tức giận cứ bám theo bạn. Bạn nên lái đến đâu?","o":["Thẳng về nhà bạn","Đến một con hẻm cụt vắng vẻ","Đến đồn cảnh sát hoặc nơi công cộng đông người","Vào lề đường để dừng lại nói chuyện"],"h1":"Hãy nghĩ đến một nơi có người có thể giúp bạn.","h2":"Bạn không nên dẫn tài xế đang tức giận về nhà mình, nên hãy lái đến đồn cảnh sát hoặc nơi công cộng đông người và gọi 911 nếu cần.","p":"Đúng. Lái đến đồn cảnh sát hoặc nơi công cộng đông người."},"tl":{"q":"Patuloy kang sinusundan ng isang galit na driver. Saan ka dapat magmaneho?","o":["Diretso sa bahay mo","Sa tahimik na dead-end na kalye","Sa police station o mataong pampublikong lugar","Sa shoulder para huminto at makipag-usap"],"h1":"Isipin ang lugar kung saan may mga taong makakatulong sa iyo.","h2":"Hindi mo dapat dalhin ang galit na driver sa bahay mo, kaya magmaneho papunta sa police station o mataong pampublikong lugar at tumawag sa 911 kung kailangan.","p":"Tama. Magmaneho papunta sa police station o mataong pampublikong lugar."},"ar":{"q":"سائق غاضب يستمر في اللحاق بك. إلى أين يجب أن تقود؟","o":["مباشرة إلى بيتك","إلى شارع هادئ مسدود","إلى مركز شرطة أو مكان عام مزدحم","إلى كتف الطريق لتتوقف وتتكلم معه"],"h1":"فكّر في مكان فيه ناس يستطيعون مساعدتك.","h2":"يجب ألّا تقود السائق الغاضب إلى بيتك، لذلك قُد إلى مركز شرطة أو مكان عام مزدحم، واتصل بـ 911 إذا احتجت.","p":"صحيح. قُد إلى مركز شرطة أو مكان عام مزدحم."},"ht":{"q":"Yon chofè ki fache kontinye ap swiv ou. Ki kote ou ta dwe kondi ale?","o":["Tou dwat lakay ou","Nan yon ti lari trankil ki pa gen sòti","Nan yon estasyon polis oswa yon kote piblik ki gen anpil moun","Sou bò wout la pou kanpe pale avè l"],"h1":"Panse ak yon kote moun ka ede w.","h2":"Ou pa ta dwe mennen yon chofè ki fache lakay ou, kidonk kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun, epi rele 911 si sa nesesè.","p":"Se sa. Kondi ale nan yon estasyon polis oswa yon kote piblik ki gen anpil moun."}},{"id":"safe-driving-047","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Why is carbon monoxide from a car's exhaust so dangerous?","o":["You cannot see it or smell it","It always makes a loud sound","It only harms the engine","It turns the air black"],"h1":"Think about how you would notice a gas in the car.","h2":"Carbon monoxide has no color and no smell, so it can make you sleepy or sick without warning; never run the engine in a closed garage.","p":"Right. Carbon monoxide cannot be seen or smelled."},"es":{"q":"¿Por qué es tan peligroso el monóxido de carbono del escape del carro?","o":["No se puede ver ni oler","Siempre hace un ruido fuerte","Solo daña el motor","Pone el aire negro"],"h1":"Piense en cómo notaría un gas dentro del carro.","h2":"El monóxido de carbono no tiene color ni olor, así que puede darle sueño o enfermarlo sin aviso; nunca deje el motor encendido en un garaje cerrado.","p":"Correcto. El monóxido de carbono no se puede ver ni oler."},"zh":{"q":"为什么汽车尾气里的一氧化碳这么危险？","o":["你看不到，也闻不到","它总是发出很大的声音","它只伤害引擎","它让空气变黑"],"h1":"想一想你怎样才能发现车里有一种气体。","h2":"一氧化碳没有颜色，也没有气味，所以它可能在没有任何提醒的情况下让你犯困或生病；绝不要在关着的车库里让引擎运转。","p":"对。一氧化碳看不到，也闻不到。"},"vi":{"q":"Tại sao khí carbon monoxide từ ống xả xe lại rất nguy hiểm?","o":["Bạn không thể nhìn thấy hay ngửi thấy nó","Nó luôn phát ra tiếng động lớn","Nó chỉ làm hại động cơ","Nó làm không khí biến thành màu đen"],"h1":"Hãy nghĩ xem bạn sẽ nhận ra có khí trong xe bằng cách nào.","h2":"Carbon monoxide không màu và không mùi, nên nó có thể làm bạn buồn ngủ hoặc bị bệnh mà không có dấu hiệu báo trước; đừng bao giờ nổ máy xe trong ga-ra đóng kín.","p":"Đúng. Carbon monoxide không thể nhìn thấy hay ngửi thấy."},"tl":{"q":"Bakit napakamapanganib ng carbon monoxide mula sa usok ng tambutso ng kotse?","o":["Hindi mo ito nakikita o naaamoy","Laging may malakas itong tunog","Makina lang ang napipinsala nito","Pinaiitim nito ang hangin"],"h1":"Isipin kung paano mo mapapansin ang isang gas sa loob ng kotse.","h2":"Walang kulay at walang amoy ang carbon monoxide, kaya puwede ka nitong antukin o pasamain ang pakiramdam mo nang walang babala; huwag kailanman paandarin ang makina sa saradong garahe.","p":"Tama. Hindi nakikita o naaamoy ang carbon monoxide."},"ar":{"q":"لماذا أول أكسيد الكربون الخارج من عادم السيارة خطير جدًا؟","o":["لا تستطيع أن تراه أو تشمّه","يُصدر دائمًا صوتًا عاليًا","يضرّ المحرك فقط","يجعل الهواء أسود"],"h1":"فكّر: كيف ستلاحظ وجود غاز في السيارة؟","h2":"أول أكسيد الكربون ليس له لون ولا رائحة، لذلك قد يجعلك نعسانًا أو مريضًا بدون تحذير؛ لا تشغّل المحرك أبدًا في مرآب مغلق.","p":"صحيح. أول أكسيد الكربون لا يُرى ولا يُشمّ."},"ht":{"q":"Poukisa monoksid kabòn ki soti nan tiyo echapman yon machin danjere konsa?","o":["Ou pa ka wè l ni santi l","Li toujou fè yon gwo bri","Li fè motè a sèlman mal","Li fè lè a vin nwa"],"h1":"Panse ak kijan ou ta remake yon gaz nan machin nan.","h2":"Monoksid kabòn pa gen koulè ni odè, kidonk li ka ba w dòmi oswa rann ou malad san avètisman; pa janm kite motè a limen nan yon garaj ki fèmen.","p":"Se sa. Ou pa ka wè ni santi monoksid kabòn."}},{"id":"safe-driving-048","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"While driving, you get a headache and feel sleepy. You think it may be exhaust fumes. What should you do?","o":["Close all windows to stay warm","Turn the heater up high","Keep driving to get home fast","Open the windows and pull off safely"],"h1":"Think about getting fresh air right away.","h2":"A headache and sleepiness can be signs of carbon monoxide, so open the windows for fresh air, pull off safely, and have the exhaust checked.","p":"Right. Open the windows and pull off safely."},"es":{"q":"Mientras maneja, le da dolor de cabeza y sueño. Cree que pueden ser gases del escape. ¿Qué debe hacer?","o":["Cerrar todas las ventanas para no tener frío","Subir la calefacción al máximo","Seguir manejando para llegar rápido","Abrir las ventanas y salir de la vía con seguridad"],"h1":"Piense en conseguir aire fresco de inmediato.","h2":"El dolor de cabeza y el sueño pueden ser señales de monóxido de carbono, así que abra las ventanas, salga de la vía con seguridad y haga revisar el escape.","p":"Correcto. Abra las ventanas y salga de la vía con seguridad."},"zh":{"q":"开车时，你头痛，还觉得困。你觉得可能是尾气。你应该怎么做？","o":["关上所有车窗保暖","把暖气开得很大","继续开，快点回家","打开车窗，安全地把车开到路边"],"h1":"想一想马上得到新鲜空气。","h2":"头痛和犯困可能是一氧化碳的信号，所以要打开车窗换新鲜空气，安全地把车开到路边，并找人检查排气系统。","p":"对。打开车窗，安全地把车开到路边。"},"vi":{"q":"Khi đang lái xe, bạn bị nhức đầu và thấy buồn ngủ. Bạn nghĩ có thể là do khói ống xả. Bạn nên làm gì?","o":["Đóng hết cửa sổ để giữ ấm","Mở máy sưởi thật lớn","Lái tiếp để về nhà nhanh","Mở cửa sổ và tấp vào lề an toàn"],"h1":"Hãy nghĩ đến việc lấy không khí trong lành ngay lập tức.","h2":"Nhức đầu và buồn ngủ có thể là dấu hiệu của carbon monoxide, nên hãy mở cửa sổ để có không khí trong lành, tấp vào lề an toàn, và cho kiểm tra ống xả.","p":"Đúng. Mở cửa sổ và tấp vào lề an toàn."},"tl":{"q":"Habang nagmamaneho, sumakit ang ulo mo at inaantok ka. Sa tingin mo, baka usok ito ng tambutso. Ano ang dapat mong gawin?","o":["Isara ang lahat ng bintana para manatiling mainit","Lakasan ang heater","Tumuloy sa pagmamaneho para mabilis makauwi","Buksan ang mga bintana at tumabi nang ligtas"],"h1":"Isipin ang pagkuha agad ng sariwang hangin.","h2":"Ang sakit ng ulo at antok ay puwedeng senyales ng carbon monoxide, kaya buksan ang mga bintana para sa sariwang hangin, tumabi nang ligtas, at ipasuri ang tambutso.","p":"Tama. Buksan ang mga bintana at tumabi nang ligtas."},"ar":{"q":"وأنت تقود، تشعر بصداع ونعاس. تظن أن السبب قد يكون غازات العادم. ماذا يجب أن تفعل؟","o":["أغلق كل النوافذ لتبقى دافئًا","ارفع التدفئة إلى أعلى درجة","تابع القيادة لتصل إلى البيت بسرعة","افتح النوافذ واخرج من الطريق بأمان"],"h1":"فكّر في الحصول على هواء نقي فورًا.","h2":"الصداع والنعاس قد يكونان علامات على أول أكسيد الكربون، لذلك افتح النوافذ ليدخل هواء نقي، واخرج من الطريق بأمان، وافحص العادم.","p":"صحيح. افتح النوافذ واخرج من الطريق بأمان."},"ht":{"q":"Pandan w ap kondi, ou gen tèt fè mal epi ou santi w gen dòmi. Ou panse se ka lafimen tiyo echapman an. Kisa ou ta dwe fè?","o":["Fèmen tout fenèt yo pou w rete cho","Mete chofaj la fò","Kontinye kondi pou w rive lakay vit","Louvri fenèt yo epi soti sou bò wout la san danje"],"h1":"Panse ak jwenn bon lè fre touswit.","h2":"Tèt fè mal ak dòmi ka siy monoksid kabòn, kidonk louvri fenèt yo pou bon lè fre antre, soti sou bò wout la san danje, epi fè yo tcheke tiyo echapman an.","p":"Se sa. Louvri fenèt yo epi soti sou bò wout la san danje."}},{"id":"safe-driving-049","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why are worn tires with little tread dangerous?","o":["They make the radio louder","They grip the road poorly, mostly when wet","They use less gas","They make the steering heavier"],"h1":"Think about what the grooves in a tire do with water.","h2":"Tire tread moves water away so the tire can grip, so worn tires slip more and are more likely to hydroplane on wet roads.","p":"Right. Worn tires grip poorly, mostly on wet roads."},"es":{"q":"¿Por qué son peligrosas las llantas gastadas con poco dibujo?","o":["Hacen que la radio suene más fuerte","Agarran mal la vía, sobre todo mojada","Gastan menos gasolina","Hacen el volante más pesado"],"h1":"Piense en lo que hacen las ranuras de la llanta con el agua.","h2":"El dibujo de la llanta saca el agua para que la llanta agarre, así que las llantas gastadas resbalan más y es más fácil que hidroplaneen en vías mojadas.","p":"Correcto. Las llantas gastadas agarran mal, sobre todo en vías mojadas."},"zh":{"q":"为什么磨损、花纹很浅的轮胎很危险？","o":["它们让收音机更大声","它们抓地力差，尤其是在湿路上","它们更省油","它们让方向盘更重"],"h1":"想一想轮胎上的沟槽对水起什么作用。","h2":"轮胎花纹会把水排开，让轮胎能抓住路面，所以磨损的轮胎更容易打滑，在湿路上也更容易发生水滑。","p":"对。磨损的轮胎抓地力差，尤其是在湿路上。"},"vi":{"q":"Tại sao lốp xe bị mòn, còn ít gai, lại nguy hiểm?","o":["Chúng làm radio kêu to hơn","Chúng bám đường kém, nhất là khi đường ướt","Chúng tốn ít xăng hơn","Chúng làm tay lái nặng hơn"],"h1":"Hãy nghĩ xem các rãnh trên lốp xe làm gì với nước.","h2":"Gai lốp đẩy nước ra để lốp bám được đường, nên lốp bị mòn dễ trượt hơn và dễ bị lướt nước hơn trên đường ướt.","p":"Đúng. Lốp bị mòn bám đường kém, nhất là trên đường ướt."},"tl":{"q":"Bakit mapanganib ang mga gasgas na gulong na kaunti na lang ang tread (ukit)?","o":["Pinalalakas nila ang radyo","Mahina ang kapit nila sa daan, lalo na kapag basa","Mas kaunti ang gas na nagagamit nila","Pinabibigat nila ang manibela"],"h1":"Isipin kung ano ang ginagawa ng mga ukit ng gulong sa tubig.","h2":"Inaalis ng tread ng gulong ang tubig para makakapit ang gulong, kaya mas dumudulas ang mga gasgas na gulong at mas malamang mag-hydroplane sa basang daan.","p":"Tama. Mahina ang kapit ng mga gasgas na gulong, lalo na sa basang daan."},"ar":{"q":"لماذا الإطارات المستهلكة التي فيها نقوش قليلة خطيرة؟","o":["تجعل صوت الراديو أعلى","تتماسك مع الطريق بشكل ضعيف، خاصة عندما يكون مبللًا","تستهلك بنزينًا أقل","تجعل المقود أثقل"],"h1":"فكّر في ما تفعله الأخاديد في الإطار مع الماء.","h2":"نقوش الإطار تُبعد الماء حتى يتماسك الإطار مع الطريق، لذلك الإطارات المستهلكة تنزلق أكثر، ومن المرجح أن يحدث معها انزلاق مائي على الطرق المبللة.","p":"صحيح. الإطارات المستهلكة تتماسك بشكل ضعيف، خاصة على الطرق المبللة."},"ht":{"q":"Poukisa kawotchou ki fin use, ki pa gen anpil kannal ankò, danjere?","o":["Yo fè radyo a pi fò","Yo pa kenbe wout la byen, sitou lè li mouye","Yo itilize mwens gaz","Yo fè volan an pi lou"],"h1":"Panse ak sa ti kannal ki nan yon kawotchou fè ak dlo.","h2":"Kannal kawotchou yo pouse dlo a ale pou kawotchou a ka kenbe wout la, kidonk kawotchou ki fin use glise plis epi yo gen plis chans glise sou dlo (hydroplaning) sou wout mouye.","p":"Se sa. Kawotchou ki fin use pa kenbe wout la byen, sitou sou wout mouye."},"ref":{"doc":"FL","page":39}},{"id":"safe-driving-050","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"When should you adjust your seat and mirrors?","o":["While driving on the highway","At the first red light","Before you start driving","Only when someone else drove your car"],"h1":"Think about when your hands and eyes are free to do it safely.","h2":"Adjusting mirrors while moving takes your attention off the road, so you should set your seat and mirrors before you start driving.","p":"Right. Adjust your seat and mirrors before you start driving."},"es":{"q":"¿Cuándo debe ajustar el asiento y los espejos?","o":["Mientras maneja en la autopista","En el primer semáforo en rojo","Antes de empezar a manejar","Solo si otra persona usó su carro"],"h1":"Piense en cuándo tiene las manos y los ojos libres para hacerlo con seguridad.","h2":"Ajustar los espejos en movimiento le quita la atención de la vía, así que debe ajustar el asiento y los espejos antes de empezar a manejar.","p":"Correcto. Ajuste el asiento y los espejos antes de empezar a manejar."},"zh":{"q":"你应该什么时候调整座椅和后视镜？","o":["在高速公路上开车时","在第一个红灯时","在你开始开车之前","只在别人开过你的车以后"],"h1":"想一想什么时候你的手和眼睛有空，可以安全地做这件事。","h2":"车在动的时候调整后视镜会让你不注意道路，所以你应该在开始开车之前调好座椅和后视镜。","p":"对。在开始开车之前调整座椅和后视镜。"},"vi":{"q":"Khi nào bạn nên chỉnh ghế ngồi và gương?","o":["Khi đang lái trên xa lộ","Ở đèn đỏ đầu tiên","Trước khi bạn bắt đầu lái xe","Chỉ khi có người khác đã lái xe của bạn"],"h1":"Hãy nghĩ xem khi nào tay và mắt bạn rảnh để làm việc này an toàn.","h2":"Chỉnh gương khi xe đang chạy làm bạn mất tập trung vào đường, nên bạn nên chỉnh ghế ngồi và gương trước khi bắt đầu lái xe.","p":"Đúng. Chỉnh ghế ngồi và gương trước khi bắt đầu lái xe."},"tl":{"q":"Kailan mo dapat ayusin ang upuan at mga salamin mo?","o":["Habang nagmamaneho sa highway","Sa unang red light","Bago ka magsimulang magmaneho","Kapag may ibang nagmaneho lang ng kotse mo"],"h1":"Isipin kung kailan malaya ang mga kamay at mata mo para gawin ito nang ligtas.","h2":"Ang pag-aayos ng salamin habang umaandar ay nag-aalis ng atensyon mo sa daan, kaya dapat mong ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho.","p":"Tama. Ayusin ang upuan at mga salamin mo bago ka magsimulang magmaneho."},"ar":{"q":"متى يجب أن تضبط مقعدك ومراياك؟","o":["وأنت تقود على الطريق السريع","عند أول إشارة حمراء","قبل أن تبدأ القيادة","فقط عندما يقود شخص آخر سيارتك"],"h1":"فكّر في الوقت الذي تكون فيه يداك وعيناك حرة لتفعل ذلك بأمان.","h2":"ضبط المرايا أثناء الحركة يُبعد انتباهك عن الطريق، لذلك يجب أن تضبط مقعدك ومراياك قبل أن تبدأ القيادة.","p":"صحيح. اضبط مقعدك ومراياك قبل أن تبدأ القيادة."},"ht":{"q":"Ki lè ou ta dwe ranje chèz ou ak retwovizè ou yo?","o":["Pandan w ap kondi sou otowout la","Nan premye limyè wouj la","Anvan ou kòmanse kondi","Sèlman lè yon lòt moun te kondi machin ou"],"h1":"Panse ak ki lè men ou ak je ou lib pou w fè l san danje.","h2":"Ranje retwovizè yo pandan machin nan ap woule retire atansyon ou sou wout la, kidonk ou ta dwe ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi.","p":"Se sa. Ranje chèz ou ak retwovizè ou yo anvan ou kòmanse kondi."},"ref":{"doc":"FL","page":59}},{"id":"safe-driving-051","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What is the right way to use your car horn?","o":["To warn others of danger","To show you are angry","To greet friends you pass","To make slow drivers hurry"],"h1":"Think about safety, not feelings.","h2":"The horn is a safety tool, so use it to warn others of danger and not to show anger or rush people.","p":"Right. Use the horn to warn others of danger."},"es":{"q":"¿Cuál es la forma correcta de usar la bocina?","o":["Para avisar a otros de un peligro","Para mostrar que está enojado","Para saludar a amigos que pasa","Para que los lentos se apuren"],"h1":"Piense en la seguridad, no en los sentimientos.","h2":"La bocina es una herramienta de seguridad, así que úsela para avisar a otros de un peligro y no para mostrar enojo ni apurar a la gente.","p":"Correcto. Use la bocina para avisar a otros de un peligro."},"zh":{"q":"使用汽车喇叭的正确方法是什么？","o":["提醒别人有危险","表示你很生气","和路过的朋友打招呼","让开得慢的司机快点"],"h1":"想一想安全，而不是情绪。","h2":"喇叭是一个安全工具，所以要用它提醒别人有危险，而不是用来表示生气或催促别人。","p":"对。用喇叭提醒别人有危险。"},"vi":{"q":"Cách đúng để dùng còi xe là gì?","o":["Để cảnh báo người khác về nguy hiểm","Để cho thấy bạn đang tức giận","Để chào bạn bè khi chạy ngang qua","Để giục tài xế chạy chậm đi nhanh hơn"],"h1":"Hãy nghĩ đến sự an toàn, không phải cảm xúc.","h2":"Còi xe là một công cụ an toàn, nên hãy dùng còi để cảnh báo người khác về nguy hiểm, không phải để thể hiện sự tức giận hay giục người khác.","p":"Đúng. Dùng còi để cảnh báo người khác về nguy hiểm."},"tl":{"q":"Ano ang tamang paraan ng paggamit ng busina ng kotse mo?","o":["Para bigyan ng babala ang iba tungkol sa panganib","Para ipakitang galit ka","Para batiin ang mga kaibigang nadaraanan mo","Para magmadali ang mabagal na mga driver"],"h1":"Isipin ang kaligtasan, hindi ang damdamin.","h2":"Ang busina ay kasangkapan para sa kaligtasan, kaya gamitin ito para bigyan ng babala ang iba tungkol sa panganib at hindi para ipakita ang galit o madaliin ang mga tao.","p":"Tama. Gamitin ang busina para bigyan ng babala ang iba tungkol sa panganib."},"ar":{"q":"ما الطريقة الصحيحة لاستعمال بوق السيارة؟","o":["لتحذير الآخرين من خطر","لتُظهر أنك غاضب","لتحيّي أصدقاء تمرّ بجانبهم","لتجعل السائقين البطيئين يُسرعون"],"h1":"فكّر في السلامة، وليس في المشاعر.","h2":"البوق أداة للسلامة، لذلك استعمله لتحذير الآخرين من خطر، وليس لتُظهر الغضب أو لتستعجل الناس.","p":"صحيح. استعمل البوق لتحذير الآخرين من خطر."},"ht":{"q":"Ki bon fason pou w sèvi ak klaksonn machin ou?","o":["Pou avèti lòt moun gen danje","Pou montre ou fache","Pou salye zanmi ou pase","Pou fè chofè ki dousman yo fè vit"],"h1":"Panse ak sekirite, pa ak santiman.","h2":"Klaksonn nan se yon zouti sekirite, kidonk sèvi avè l pou avèti lòt moun gen danje, epi pa pou montre ou fache oswa pou prese moun.","p":"Se sa. Sèvi ak klaksonn nan pou avèti lòt moun gen danje."}},{"id":"safe-driving-052","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your wiper blades leave streaks and you cannot see well in the rain. What should you do?","o":["Drive with your head out the window","Use them only on the highway","Turn on your high beams","Replace the wiper blades soon"],"h1":"Think about what you need to see clearly in the rain.","h2":"Worn wiper blades do not clear the glass, so you should replace them soon to see the road clearly in the rain.","p":"Right. Replace worn wiper blades so you can see in the rain."},"es":{"q":"Sus limpiaparabrisas dejan rayas y no ve bien en la lluvia. ¿Qué debe hacer?","o":["Manejar con la cabeza afuera de la ventana","Usarlos solo en la autopista","Encender las luces altas","Cambiar las plumas del limpiaparabrisas pronto"],"h1":"Piense en lo que necesita para ver bien en la lluvia.","h2":"Las plumas gastadas no limpian bien el vidrio, así que debe cambiarlas pronto para ver la vía con claridad en la lluvia.","p":"Correcto. Cambie las plumas gastadas para ver bien en la lluvia."},"zh":{"q":"你的雨刷片留下条纹，下雨时你看不清楚。你应该怎么做？","o":["把头伸出窗外开车","只在高速公路上用","打开远光灯","尽快更换雨刷片"],"h1":"想一想下雨时你需要什么才能看清楚。","h2":"磨损的雨刷片擦不干净玻璃，所以你应该尽快更换，这样下雨时才能看清道路。","p":"对。更换磨损的雨刷片，下雨时才能看清楚。"},"vi":{"q":"Lưỡi gạt nước để lại vệt trên kính và bạn không nhìn rõ khi trời mưa. Bạn nên làm gì?","o":["Lái xe và thò đầu ra ngoài cửa sổ","Chỉ dùng gạt nước trên xa lộ","Bật đèn pha (đèn chiếu xa)","Thay lưỡi gạt nước sớm"],"h1":"Hãy nghĩ xem bạn cần gì để nhìn rõ khi trời mưa.","h2":"Lưỡi gạt nước bị mòn không làm sạch được kính, nên bạn nên thay chúng sớm để nhìn rõ đường khi trời mưa.","p":"Đúng. Thay lưỡi gạt nước bị mòn để nhìn rõ khi trời mưa."},"tl":{"q":"Nag-iiwan ng guhit ang wiper blades mo at hindi ka makakita nang maayos sa ulan. Ano ang dapat mong gawin?","o":["Magmaneho na nakalabas ang ulo sa bintana","Gamitin lang ang mga ito sa highway","I-on ang high beams mo","Palitan agad ang wiper blades"],"h1":"Isipin kung ano ang kailangan mo para makakita nang malinaw sa ulan.","h2":"Hindi nalilinis ng gasgas na wiper blades ang salamin, kaya dapat mo itong palitan agad para malinaw mong makita ang daan sa ulan.","p":"Tama. Palitan ang gasgas na wiper blades para makakita ka sa ulan."},"ar":{"q":"شفرات المساحات تترك خطوطًا ولا تستطيع أن ترى جيدًا في المطر. ماذا يجب أن تفعل؟","o":["قُد ورأسك خارج النافذة","استعملها على الطريق السريع فقط","شغّل الأضواء العالية","غيّر شفرات المساحات قريبًا"],"h1":"فكّر في ما تحتاجه لترى بوضوح في المطر.","h2":"شفرات المساحات المستهلكة لا تنظّف الزجاج، لذلك يجب أن تغيّرها قريبًا حتى ترى الطريق بوضوح في المطر.","p":"صحيح. غيّر شفرات المساحات المستهلكة حتى ترى في المطر."},"ht":{"q":"Wipè ou yo kite tras sou vit la epi ou pa ka wè byen nan lapli a. Kisa ou ta dwe fè?","o":["Kondi ak tèt ou deyò fenèt la","Sèvi ak yo sèlman sou otowout la","Limen gwo limyè ou yo","Chanje wipè yo byento"],"h1":"Panse ak sa ou bezwen pou w wè klè nan lapli a.","h2":"Wipè ki fin use pa netwaye vit la, kidonk ou ta dwe chanje yo byento pou w ka wè wout la klè nan lapli a.","p":"Se sa. Chanje wipè ki fin use yo pou w ka wè nan lapli a."}},{"id":"safe-driving-053","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your brake pedal feels soft and sinks close to the floor. What should you do?","o":["Keep driving and press harder","Have the brakes checked right away","Wait until the next oil change","Use only the parking brake from now on"],"h1":"Think about what a soft pedal can say about your brakes.","h2":"A soft or sinking brake pedal is a warning sign of a brake problem, so you should have the brakes checked right away.","p":"Right. A soft brake pedal means get the brakes checked now."},"es":{"q":"El pedal del freno se siente blando y baja casi hasta el piso. ¿Qué debe hacer?","o":["Seguir manejando y pisar más fuerte","Hacer revisar los frenos de inmediato","Esperar hasta el próximo cambio de aceite","Usar solo el freno de mano desde ahora"],"h1":"Piense en lo que un pedal blando puede decir de sus frenos.","h2":"Un pedal de freno blando o que se hunde es una señal de un problema en los frenos, así que debe hacerlos revisar de inmediato.","p":"Correcto. Un pedal blando significa revisar los frenos ya."},"zh":{"q":"你的刹车踏板踩起来软软的，还会沉到快碰到地板。你应该怎么做？","o":["继续开，用力踩","马上找人检查刹车","等到下次换机油时再说","从现在起只用手刹"],"h1":"想一想软的踏板可能说明你的刹车有什么问题。","h2":"刹车踏板变软或往下沉是刹车有问题的警告信号，所以你应该马上找人检查刹车。","p":"对。刹车踏板变软，就要马上检查刹车。"},"vi":{"q":"Bàn đạp phanh của bạn có cảm giác mềm và lún xuống gần sàn xe. Bạn nên làm gì?","o":["Lái tiếp và đạp mạnh hơn","Cho kiểm tra phanh ngay","Chờ đến lần thay dầu tới","Từ giờ chỉ dùng phanh tay"],"h1":"Hãy nghĩ xem bàn đạp mềm có thể cho biết điều gì về phanh của bạn.","h2":"Bàn đạp phanh mềm hoặc bị lún là dấu hiệu cảnh báo phanh có vấn đề, nên bạn nên cho kiểm tra phanh ngay.","p":"Đúng. Bàn đạp phanh mềm nghĩa là phải cho kiểm tra phanh ngay."},"tl":{"q":"Malambot ang pakiramdam ng preno mo at lumulubog ito malapit sa sahig. Ano ang dapat mong gawin?","o":["Tumuloy sa pagmamaneho at diinan pa","Ipasuri agad ang preno","Maghintay hanggang sa susunod na change oil","Parking brake na lang ang gamitin mula ngayon"],"h1":"Isipin kung ano ang puwedeng sabihin ng malambot na preno tungkol sa preno mo.","h2":"Ang malambot o lumulubog na preno ay babala ng problema sa preno, kaya dapat mong ipasuri agad ang preno.","p":"Tama. Kapag malambot ang preno, ipasuri agad ang preno."},"ar":{"q":"دواسة الفرامل تبدو لينة وتنزل قريبًا من الأرض. ماذا يجب أن تفعل؟","o":["تابع القيادة واضغط بقوة أكبر","افحص الفرامل فورًا","انتظر حتى تغيير الزيت القادم","استعمل فرامل اليد فقط من الآن"],"h1":"فكّر في ما تقوله الدواسة اللينة عن فراملك.","h2":"دواسة الفرامل اللينة أو التي تنزل كثيرًا علامة تحذير على مشكلة في الفرامل، لذلك يجب أن تفحص الفرامل فورًا.","p":"صحيح. دواسة الفرامل اللينة تعني أن تفحص الفرامل الآن."},"ht":{"q":"Pedal fren ou a mou epi li desann prèske rive atè. Kisa ou ta dwe fè?","o":["Kontinye kondi epi peze pi fò","Fè tcheke fren yo touswit","Tann pwochen fwa w ap chanje lwil","Sèvi ak fren a men an sèlman depi kounye a"],"h1":"Panse ak sa yon pedal mou ka di sou fren ou yo.","h2":"Yon pedal fren ki mou oswa ki desann se yon siy avètisman ke gen yon pwoblèm fren, kidonk ou ta dwe fè tcheke fren yo touswit.","p":"Se sa. Yon pedal fren mou vle di fè tcheke fren yo kounye a."}},{"id":"safe-driving-054","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are stopped behind a large truck on an uphill road. Why should you leave extra space?","o":["So you can read its license plate","So other cars can pass you","The truck may roll back a little when it starts","So the truck driver can see your lights"],"h1":"Think about what a heavy vehicle can do on a hill when it starts to move.","h2":"A heavy truck can roll back a little on a hill before it moves forward, so leave extra space in front of you.","p":"Right. Leave extra space because a truck may roll back on a hill."},"es":{"q":"Usted está parado detrás de un camión grande en una subida. ¿Por qué debe dejar más espacio?","o":["Para poder leer su placa","Para que otros carros lo rebasen","El camión puede rodar un poco hacia atrás al arrancar","Para que el chofer vea sus luces"],"h1":"Piense en lo que puede hacer un vehículo pesado en una subida al empezar a moverse.","h2":"Un camión pesado puede rodar un poco hacia atrás en una subida antes de avanzar, así que deje más espacio delante de usted.","p":"Correcto. Deje más espacio porque el camión puede rodar hacia atrás."},"zh":{"q":"你在上坡路上停在一辆大卡车后面。为什么你应该多留一些空间？","o":["这样你才能看清它的车牌","这样其他车才能超过你","卡车起步时可能会往后溜一点","这样卡车司机才能看到你的车灯"],"h1":"想一想重型车辆在坡上开始移动时可能会怎样。","h2":"重型卡车在坡上往前开之前，可能会往后溜一点，所以要在你前面多留一些空间。","p":"对。多留空间，因为卡车在坡上可能会往后溜。"},"vi":{"q":"Bạn đang dừng sau một xe tải lớn trên đường lên dốc. Tại sao bạn nên chừa thêm khoảng cách?","o":["Để bạn đọc được biển số xe của nó","Để các xe khác vượt qua bạn","Xe tải có thể bị trôi lùi một chút khi bắt đầu chạy","Để tài xế xe tải nhìn thấy đèn của bạn"],"h1":"Hãy nghĩ xem một xe nặng có thể làm gì trên dốc khi bắt đầu chạy.","h2":"Xe tải nặng có thể trôi lùi một chút trên dốc trước khi chạy tới, nên hãy chừa thêm khoảng cách phía trước bạn.","p":"Đúng. Chừa thêm khoảng cách vì xe tải có thể trôi lùi trên dốc."},"tl":{"q":"Nakahinto ka sa likod ng malaking truck sa paakyat na daan. Bakit dapat kang mag-iwan ng dagdag na espasyo?","o":["Para mabasa mo ang plate number nito","Para makalampas sa iyo ang ibang kotse","Puwedeng umatras nang kaunti ang truck kapag umandar ito","Para makita ng truck driver ang ilaw mo"],"h1":"Isipin kung ano ang puwedeng gawin ng mabigat na sasakyan sa paakyat kapag nagsisimula itong umandar.","h2":"Ang mabigat na truck ay puwedeng umatras nang kaunti sa paakyat bago ito umabante, kaya mag-iwan ng dagdag na espasyo sa harap mo.","p":"Tama. Mag-iwan ng dagdag na espasyo dahil puwedeng umatras ang truck sa paakyat."},"ar":{"q":"أنت متوقف خلف شاحنة كبيرة على طريق صاعد. لماذا يجب أن تترك مسافة إضافية؟","o":["حتى تستطيع قراءة لوحة أرقامها","حتى تستطيع السيارات الأخرى تجاوزك","الشاحنة قد ترجع إلى الخلف قليلًا عندما تبدأ بالتحرك","حتى يستطيع سائق الشاحنة رؤية أضوائك"],"h1":"فكّر في ما قد تفعله مركبة ثقيلة على طريق صاعد عندما تبدأ بالتحرك.","h2":"الشاحنة الثقيلة قد ترجع إلى الخلف قليلًا على الطريق الصاعد قبل أن تتقدم إلى الأمام، لذلك اترك مسافة إضافية أمامك.","p":"صحيح. اترك مسافة إضافية لأن الشاحنة قد ترجع إلى الخلف على الطريق الصاعد."},"ht":{"q":"Ou kanpe dèyè yon gwo kamyon sou yon wout k ap monte. Poukisa ou ta dwe kite plis espas?","o":["Pou w ka li plak li","Pou lòt machin ka pase w","Kamyon an ka fè bak yon ti kras lè l ap demare","Pou chofè kamyon an ka wè limyè ou"],"h1":"Panse ak sa yon machin lou ka fè sou yon mòn lè li kòmanse deplase.","h2":"Yon kamyon lou ka fè bak yon ti kras sou yon mòn anvan li avanse, kidonk kite plis espas devan w.","p":"Se sa. Kite plis espas paske yon kamyon ka fè bak sou yon mòn."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-055","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Where should the lap part of a seat belt go?","o":["Across your stomach","Loose across your lap","Under your legs","Low and snug across your hips"],"h1":"The hip bones are strong.","h2":"The lap belt should sit low and snug across your hips, not across your stomach, so it holds your strong hip bones in a crash.","p":"Right. Low and snug across the hips."},"es":{"q":"¿Dónde debe ir la parte del cinturón que cruza la cintura?","o":["Sobre el estómago","Floja sobre las piernas","Debajo de las piernas","Baja y ajustada sobre las caderas"],"h1":"Los huesos de la cadera son fuertes.","h2":"La parte baja del cinturón debe ir baja y ajustada sobre las caderas, no sobre el estómago, para sujetar los huesos fuertes de la cadera en un choque.","p":"Correcto. Baja y ajustada sobre las caderas."},"zh":{"q":"安全带的腰带部分应该放在哪里？","o":["横过你的肚子","松松地横过你的大腿","放在你的腿下面","低低地、贴紧地横过你的髋部"],"h1":"髋骨很结实。","h2":"腰带应该低低地、贴紧地横过你的髋部，而不是横过肚子，这样发生撞车时它能拉住你结实的髋骨。","p":"对。低低地、贴紧地横过髋部。"},"vi":{"q":"Phần dây ngang hông của dây an toàn nên đặt ở đâu?","o":["Ngang qua bụng bạn","Lỏng lẻo ngang qua đùi","Dưới chân bạn","Thấp và vừa khít ngang qua hông"],"h1":"Xương hông rất chắc.","h2":"Dây ngang hông nên nằm thấp và vừa khít ngang qua hông bạn, không phải ngang qua bụng, để giữ xương hông chắc của bạn khi có va chạm.","p":"Đúng. Thấp và vừa khít ngang qua hông."},"tl":{"q":"Saan dapat nakalagay ang bahaging pang-kandungan ng seat belt?","o":["Sa ibabaw ng tiyan mo","Maluwag sa ibabaw ng kandungan mo","Sa ilalim ng mga binti mo","Mababa at mahigpit sa ibabaw ng balakang mo"],"h1":"Matibay ang mga buto ng balakang.","h2":"Ang lap belt ay dapat nakalagay nang mababa at mahigpit sa ibabaw ng balakang mo, hindi sa tiyan, para mahawakan nito ang matibay na buto ng balakang mo sa banggaan.","p":"Tama. Mababa at mahigpit sa ibabaw ng balakang."},"ar":{"q":"أين يجب أن يكون الجزء السفلي (حزام الحِجر) من حزام الأمان؟","o":["فوق بطنك","مرتخيًا فوق فخذيك","تحت رجليك","منخفضًا ومشدودًا فوق وركيك"],"h1":"عظام الورك قوية.","h2":"يجب أن يكون الجزء السفلي من الحزام منخفضًا ومشدودًا فوق وركيك، وليس فوق بطنك، حتى يمسك عظام الورك القوية عند الاصطدام.","p":"صحيح. منخفضًا ومشدودًا فوق الوركين."},"ht":{"q":"Ki kote pati senti sekirite ki pase sou janm ou yo dwe ye?","o":["Atravè vant ou","Lach sou janm ou","Anba janm ou","Ba epi byen sere atravè ranch ou"],"h1":"Zo ranch yo solid.","h2":"Pati senti ki pase anba a dwe ba epi byen sere atravè ranch ou, pa atravè vant ou, pou l kenbe zo ranch ou ki solid yo nan yon aksidan.","p":"Se sa. Ba epi byen sere atravè ranch ou."}},{"id":"safe-driving-056","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Where should the shoulder part of a seat belt go?","o":["Across the middle of your chest and over your shoulder","Behind your back","Under your arm","Across your neck"],"h1":"Never move the shoulder belt out of the way.","h2":"The shoulder belt should cross the middle of your chest and your shoulder, never behind your back or under your arm.","p":"Right. Across the chest and shoulder."},"es":{"q":"¿Dónde debe ir la parte del cinturón que cruza el hombro?","o":["Sobre el centro del pecho y el hombro","Detrás de la espalda","Debajo del brazo","Sobre el cuello"],"h1":"Nunca quite la banda del hombro de su lugar.","h2":"La banda del hombro debe cruzar el centro del pecho y el hombro, nunca detrás de la espalda ni debajo del brazo.","p":"Correcto. Sobre el pecho y el hombro."},"zh":{"q":"安全带的肩带部分应该放在哪里？","o":["横过胸口中间并越过你的肩膀","放在你的背后","放在你的手臂下面","横过你的脖子"],"h1":"千万不要把肩带挪开。","h2":"肩带应该横过你胸口中间和你的肩膀，绝不能放在背后或手臂下面。","p":"对。横过胸口和肩膀。"},"vi":{"q":"Phần dây vai của dây an toàn nên đặt ở đâu?","o":["Ngang qua giữa ngực và qua vai bạn","Sau lưng bạn","Dưới cánh tay bạn","Ngang qua cổ bạn"],"h1":"Đừng bao giờ gạt dây vai sang một bên.","h2":"Dây vai nên chéo qua giữa ngực và qua vai bạn, không bao giờ để sau lưng hay dưới cánh tay.","p":"Đúng. Ngang qua ngực và vai."},"tl":{"q":"Saan dapat nakalagay ang bahaging pang-balikat ng seat belt?","o":["Sa gitna ng dibdib mo at sa ibabaw ng balikat mo","Sa likod mo","Sa ilalim ng braso mo","Sa ibabaw ng leeg mo"],"h1":"Huwag kailanman ilayo ang shoulder belt.","h2":"Ang shoulder belt ay dapat tumawid sa gitna ng dibdib mo at sa balikat mo, hindi kailanman sa likod mo o sa ilalim ng braso mo.","p":"Tama. Sa dibdib at sa balikat."},"ar":{"q":"أين يجب أن يكون الجزء العلوي (حزام الكتف) من حزام الأمان؟","o":["عبر منتصف صدرك وفوق كتفك","خلف ظهرك","تحت ذراعك","فوق رقبتك"],"h1":"يجب ألّا تُبعد حزام الكتف عن مكانه أبدًا.","h2":"يجب أن يمر حزام الكتف عبر منتصف صدرك وفوق كتفك، وأبدًا ليس خلف ظهرك أو تحت ذراعك.","p":"صحيح. عبر الصدر والكتف."},"ht":{"q":"Ki kote pati senti sekirite ki pase sou zepòl ou a dwe ye?","o":["Atravè mitan pwatrin ou epi sou zepòl ou","Dèyè do ou","Anba bra ou","Atravè kou ou"],"h1":"Pa janm deplase senti zepòl la.","h2":"Senti zepòl la dwe travèse mitan pwatrin ou ak zepòl ou, pa janm dèyè do ou oswa anba bra ou.","p":"Se sa. Atravè pwatrin ak zepòl."}},{"id":"safe-driving-057","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"How does a seat belt protect you in a crash?","o":["It stops the car faster","It keeps you in your seat so you are not thrown against the car or out of it","It makes the air bag work","It keeps the doors closed"],"h1":"Being thrown from a car is often deadly.","h2":"A seat belt holds you in your seat, so you are not thrown into the dashboard or windshield or out of the vehicle.","p":"Right. It keeps you in your seat."},"es":{"q":"¿Cómo lo protege el cinturón de seguridad en un choque?","o":["Hace que el carro se pare más rápido","Lo mantiene en su asiento para que no salga lanzado contra el carro o fuera de él","Hace funcionar la bolsa de aire","Mantiene las puertas cerradas"],"h1":"Salir lanzado de un carro muchas veces es mortal.","h2":"El cinturón lo sujeta en su asiento, así no sale lanzado contra el tablero o el parabrisas ni fuera del vehículo.","p":"Correcto. Lo mantiene en su asiento."},"zh":{"q":"发生撞车时，安全带怎样保护你？","o":["它让车停得更快","它让你留在座位上，不会被甩到车上或甩出车外","它让安全气囊起作用","它让车门保持关闭"],"h1":"被甩出车外常常会致命。","h2":"安全带把你固定在座位上，所以你不会被甩到仪表板或挡风玻璃上，也不会被甩出车外。","p":"对。它让你留在座位上。"},"vi":{"q":"Dây an toàn bảo vệ bạn như thế nào khi có va chạm?","o":["Nó làm xe dừng nhanh hơn","Nó giữ bạn trên ghế để bạn không bị văng vào thành xe hay văng ra ngoài","Nó làm túi khí hoạt động","Nó giữ cửa xe đóng"],"h1":"Bị văng ra khỏi xe thường gây tử vong.","h2":"Dây an toàn giữ bạn trên ghế, nên bạn không bị văng vào bảng điều khiển hay kính chắn gió, hoặc văng ra khỏi xe.","p":"Đúng. Nó giữ bạn trên ghế."},"tl":{"q":"Paano ka pinoprotektahan ng seat belt sa banggaan?","o":["Pinapahinto nito nang mas mabilis ang kotse","Pinapanatili ka nito sa upuan mo para hindi ka tumilapon sa loob ng kotse o palabas nito","Pinapagana nito ang air bag","Pinapanatili nitong sarado ang mga pinto"],"h1":"Ang pagtilapon palabas ng kotse ay kadalasang nakamamatay.","h2":"Hinahawakan ka ng seat belt sa upuan mo, kaya hindi ka tumitilapon sa dashboard o windshield o palabas ng sasakyan.","p":"Tama. Pinapanatili ka nito sa upuan mo."},"ar":{"q":"كيف يحميك حزام الأمان عند الاصطدام؟","o":["يوقف السيارة أسرع","يُبقيك في مقعدك حتى لا تُقذف على أجزاء السيارة أو خارجها","يجعل الوسادة الهوائية تعمل","يُبقي الأبواب مغلقة"],"h1":"القذف خارج السيارة يكون قاتلًا في كثير من الأحيان.","h2":"حزام الأمان يُبقيك في مقعدك، فلا تُقذف على لوحة القيادة أو الزجاج الأمامي أو خارج السيارة.","p":"صحيح. يُبقيك في مقعدك."},"ht":{"q":"Kijan senti sekirite pwoteje w nan yon aksidan?","o":["Li fè machin nan kanpe pi vit","Li kenbe w sou chèz ou pou w pa voye frape sou machin nan oswa voye deyò","Li fè airbag la mache","Li kenbe pòt yo fèmen"],"h1":"Lè yo voye w deyò yon machin, souvan se lanmò.","h2":"Senti sekirite a kenbe w sou chèz ou, kidonk ou pa voye frape sou tablodbò a oswa vit devan an, ni voye deyò machin nan.","p":"Se sa. Li kenbe w sou chèz ou."}},{"id":"safe-driving-058","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car has air bags. Do you still need to wear a seat belt?","o":["No, air bags are enough","Only on the highway","Yes, air bags work with seat belts, not instead of them","Only in the back seat"],"h1":"An air bag inflates once, very fast.","h2":"Air bags are made to work together with seat belts; without a belt, you can be hurt by the air bag or thrown from the car.","p":"Right. Always wear your belt too."},"es":{"q":"Su carro tiene bolsas de aire. ¿Todavía necesita el cinturón de seguridad?","o":["No, las bolsas de aire bastan","Solo en la carretera","Sí, las bolsas de aire funcionan junto con el cinturón, no en su lugar","Solo en el asiento trasero"],"h1":"Una bolsa de aire se infla una vez, muy rápido.","h2":"Las bolsas de aire están hechas para funcionar junto con el cinturón; sin el cinturón, la bolsa puede lastimarlo o puede salir lanzado del carro.","p":"Correcto. Use siempre el cinturón también."},"zh":{"q":"你的车有安全气囊。你还需要系安全带吗？","o":["不用，有安全气囊就够了","只有在高速公路上才需要","需要，安全气囊是和安全带一起起作用，不是代替安全带","只有坐在后座才需要"],"h1":"安全气囊只会弹出一次，而且非常快。","h2":"安全气囊是设计来和安全带一起起作用的；不系安全带，你可能会被安全气囊弄伤，或被甩出车外。","p":"对。一定也要系好安全带。"},"vi":{"q":"Xe bạn có túi khí. Bạn có vẫn cần thắt dây an toàn không?","o":["Không, có túi khí là đủ","Chỉ khi chạy trên xa lộ","Có, túi khí hoạt động cùng với dây an toàn, không thay thế dây an toàn","Chỉ khi ngồi ghế sau"],"h1":"Túi khí bung ra một lần, rất nhanh.","h2":"Túi khí được làm ra để hoạt động cùng với dây an toàn; nếu không thắt dây, bạn có thể bị túi khí gây thương tích hoặc bị văng ra khỏi xe.","p":"Đúng. Luôn thắt dây an toàn nữa."},"tl":{"q":"May mga air bag ang kotse mo. Kailangan mo pa bang magsuot ng seat belt?","o":["Hindi, sapat na ang mga air bag","Sa highway lang","Oo, gumagana ang mga air bag kasama ng seat belt, hindi kapalit nito","Sa likurang upuan lang"],"h1":"Isang beses lang lumalabas ang air bag, at napakabilis.","h2":"Ginawa ang mga air bag para gumana kasama ng seat belt; kung walang seat belt, puwede kang masaktan ng air bag o tumilapon palabas ng kotse.","p":"Tama. Laging magsuot din ng seat belt."},"ar":{"q":"في سيارتك وسائد هوائية. هل ما زلت تحتاج إلى ربط حزام الأمان؟","o":["لا، الوسائد الهوائية تكفي","على الطريق السريع فقط","نعم، الوسائد الهوائية تعمل مع أحزمة الأمان، وليس بدلًا منها","في المقعد الخلفي فقط"],"h1":"الوسادة الهوائية تنتفخ مرة واحدة، وبسرعة كبيرة.","h2":"الوسائد الهوائية مصمَّمة لتعمل مع أحزمة الأمان؛ وبدون حزام قد تؤذيك الوسادة الهوائية أو تُقذف خارج السيارة.","p":"صحيح. اربط حزامك دائمًا أيضًا."},"ht":{"q":"Machin ou gen airbag. Èske ou toujou bezwen mete senti sekirite?","o":["Non, airbag yo ase","Sèlman sou otowout","Wi, airbag yo travay ansanm ak senti sekirite, yo pa ranplase yo","Sèlman sou chèz dèyè"],"h1":"Yon airbag gonfle yon sèl fwa, trè vit.","h2":"Airbag yo fèt pou travay ansanm ak senti sekirite; san senti, airbag la ka blese w oswa yo ka voye w deyò machin nan.","p":"Se sa. Toujou mete senti ou tou."}},{"id":"safe-driving-059","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Why must a rear-facing baby seat never be placed in front of an active air bag?","o":["The seat will not fit","The baby cannot see the driver","The air bag will not open","The air bag can hit the seat with great force and seriously hurt the baby"],"h1":"The back of the baby seat would be close to the air bag.","h2":"A rear-facing car seat must never be in front of an active air bag, because the bag can strike the seat with force and seriously injure the baby.","p":"Right. The air bag can badly hurt the baby."},"es":{"q":"¿Por qué nunca se debe poner una silla de bebé mirando hacia atrás frente a una bolsa de aire activa?","o":["Porque la silla no cabe","Porque el bebé no puede ver al conductor","Porque la bolsa no se abrirá","Porque la bolsa puede golpear la silla con mucha fuerza y lastimar gravemente al bebé"],"h1":"El respaldo de la silla quedaría cerca de la bolsa de aire.","h2":"Una silla de bebé mirando hacia atrás nunca debe ir frente a una bolsa de aire activa, porque la bolsa puede golpearla con fuerza y lastimar gravemente al bebé.","p":"Correcto. La bolsa puede lastimar gravemente al bebé."},"zh":{"q":"为什么绝不能把后向式婴儿座椅放在正在启用的安全气囊前面？","o":["座椅放不进去","婴儿看不到司机","安全气囊不会打开","安全气囊会用很大的力撞到座椅，严重伤害婴儿"],"h1":"婴儿座椅的背面会离安全气囊很近。","h2":"后向式儿童座椅绝不能放在正在启用的安全气囊前面，因为气囊会用力撞到座椅，严重伤害婴儿。","p":"对。安全气囊会严重伤害婴儿。"},"vi":{"q":"Vì sao không bao giờ được đặt ghế em bé quay về phía sau trước một túi khí đang hoạt động?","o":["Ghế sẽ không vừa","Em bé không nhìn thấy tài xế","Túi khí sẽ không bung ra","Túi khí có thể đập vào ghế rất mạnh và làm em bé bị thương nặng"],"h1":"Lưng ghế em bé sẽ ở rất gần túi khí.","h2":"Không bao giờ được đặt ghế xe quay về phía sau trước một túi khí đang hoạt động, vì túi khí có thể đập mạnh vào ghế và làm em bé bị thương nặng.","p":"Đúng. Túi khí có thể làm em bé bị thương nặng."},"tl":{"q":"Bakit hindi kailanman dapat ilagay ang nakaharap-sa-likod na upuan ng sanggol sa harap ng aktibong air bag?","o":["Hindi kakasya ang upuan","Hindi makikita ng sanggol ang driver","Hindi bubukas ang air bag","Puwedeng tamaan ng air bag ang upuan nang napakalakas at malubhang masaktan ang sanggol"],"h1":"Malapit sa air bag ang likod ng upuan ng sanggol.","h2":"Hindi kailanman dapat ilagay ang nakaharap-sa-likod na car seat sa harap ng aktibong air bag, dahil puwedeng tamaan nang malakas ng air bag ang upuan at malubhang masaktan ang sanggol.","p":"Tama. Puwedeng malubhang masaktan ng air bag ang sanggol."},"ar":{"q":"لماذا يجب ألّا يوضع مقعد الطفل المتجه إلى الخلف أبدًا أمام وسادة هوائية مُفعَّلة؟","o":["لأن المقعد لن يتسع","لأن الطفل لا يستطيع رؤية السائق","لأن الوسادة الهوائية لن تنفتح","لأن الوسادة الهوائية قد تضرب المقعد بقوة كبيرة وتؤذي الطفل أذى شديدًا"],"h1":"ظهر مقعد الطفل سيكون قريبًا من الوسادة الهوائية.","h2":"يجب ألّا يوضع مقعد السيارة المتجه إلى الخلف أبدًا أمام وسادة هوائية مُفعَّلة، لأن الوسادة قد تضرب المقعد بقوة وتؤذي الطفل أذى شديدًا.","p":"صحيح. الوسادة الهوائية قد تؤذي الطفل أذى شديدًا."},"ht":{"q":"Poukisa ou pa dwe janm mete yon chèz tibebe ki gade dèyè devan yon airbag ki aktive?","o":["Chèz la p ap antre","Tibebe a pa ka wè chofè a","Airbag la p ap louvri","Airbag la ka frape chèz la ak anpil fòs epi blese tibebe a grav"],"h1":"Do chèz tibebe a t ap tou pre airbag la.","h2":"Ou pa dwe janm mete yon chèz machin ki gade dèyè devan yon airbag ki aktive, paske airbag la ka frape chèz la ak fòs epi blese tibebe a grav.","p":"Se sa. Airbag la ka blese tibebe a grav."}},{"id":"safe-driving-060","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"How should a pregnant woman wear a seat belt?","o":["Lap belt low across the hips, below the belly, and shoulder belt across the chest","Lap belt across the belly","Shoulder belt behind the back","She should not wear one"],"h1":"Keep the lap belt off the belly.","h2":"A pregnant woman should wear the lap belt low across her hips below her belly and the shoulder belt across her chest, away from her neck.","p":"Right. Lap belt below the belly."},"es":{"q":"¿Cómo debe usar el cinturón una mujer embarazada?","o":["La banda baja sobre las caderas, debajo del vientre, y la del hombro sobre el pecho","La banda baja sobre el vientre","La banda del hombro detrás de la espalda","No debe usarlo"],"h1":"Mantenga la banda baja lejos del vientre.","h2":"Una mujer embarazada debe usar la banda baja sobre las caderas, debajo del vientre, y la del hombro sobre el pecho, lejos del cuello.","p":"Correcto. La banda baja debajo del vientre."},"zh":{"q":"孕妇应该怎样系安全带？","o":["腰带低低地横过髋部、在肚子下面，肩带横过胸口","腰带横过肚子","肩带放在背后","她不应该系安全带"],"h1":"不要让腰带压在肚子上。","h2":"孕妇应该把腰带低低地系在髋部、在肚子下面，并让肩带横过胸口、远离脖子。","p":"对。腰带系在肚子下面。"},"vi":{"q":"Phụ nữ mang thai nên thắt dây an toàn như thế nào?","o":["Dây ngang hông nằm thấp qua hông, dưới bụng, và dây vai chéo qua ngực","Dây ngang hông nằm qua bụng","Dây vai để sau lưng","Cô ấy không nên thắt dây"],"h1":"Giữ dây ngang hông tránh khỏi bụng.","h2":"Phụ nữ mang thai nên để dây ngang hông nằm thấp qua hông, dưới bụng, và dây vai chéo qua ngực, tránh xa cổ.","p":"Đúng. Dây ngang hông nằm dưới bụng."},"tl":{"q":"Paano dapat magsuot ng seat belt ang buntis?","o":["Ang lap belt ay mababa sa balakang, sa ilalim ng tiyan, at ang shoulder belt ay sa dibdib","Ang lap belt ay sa ibabaw ng tiyan","Ang shoulder belt ay sa likod","Hindi siya dapat magsuot nito"],"h1":"Ilayo sa tiyan ang lap belt.","h2":"Dapat isuot ng buntis ang lap belt nang mababa sa balakang niya sa ilalim ng tiyan, at ang shoulder belt sa dibdib niya, malayo sa leeg.","p":"Tama. Ang lap belt ay sa ilalim ng tiyan."},"ar":{"q":"كيف يجب أن تربط المرأة الحامل حزام الأمان؟","o":["الجزء السفلي منخفضًا فوق الوركين تحت البطن، وحزام الكتف عبر الصدر","الجزء السفلي فوق البطن","حزام الكتف خلف الظهر","يجب ألّا تربطه"],"h1":"أبعِد الجزء السفلي من الحزام عن البطن.","h2":"يجب أن تضع المرأة الحامل الجزء السفلي من الحزام منخفضًا فوق وركيها تحت بطنها، وحزام الكتف عبر صدرها بعيدًا عن رقبتها.","p":"صحيح. الجزء السفلي تحت البطن."},"ht":{"q":"Kijan yon fanm ansent dwe mete senti sekirite?","o":["Senti anba a ba atravè ranch li, anba vant li, epi senti zepòl la atravè pwatrin li","Senti anba a atravè vant li","Senti zepòl la dèyè do li","Li pa dwe mete youn"],"h1":"Kenbe senti anba a lwen vant la.","h2":"Yon fanm ansent dwe mete senti anba a ba atravè ranch li anba vant li, epi senti zepòl la atravè pwatrin li, lwen kou li.","p":"Se sa. Senti anba a anba vant la."}},{"id":"safe-driving-061","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should your hands be on the sides of the steering wheel instead of across the top?","o":["It looks better","If the air bag opens, your arms will not be thrown into your face","The horn is on the top","You can turn faster with one hand on top"],"h1":"The air bag comes out of the center of the wheel.","h2":"Holding the wheel on the sides keeps your arms out of the way of the air bag, which bursts from the center of the wheel.","p":"Right. Your arms stay clear of the air bag."},"es":{"q":"¿Por qué sus manos deben ir a los lados del volante y no cruzadas por arriba?","o":["Porque se ve mejor","Porque si se abre la bolsa de aire, sus brazos no saldrán lanzados contra su cara","Porque la bocina está arriba","Porque se gira más rápido con una mano arriba"],"h1":"La bolsa de aire sale del centro del volante.","h2":"Sujetar el volante por los lados mantiene sus brazos fuera del camino de la bolsa de aire, que sale del centro del volante.","p":"Correcto. Sus brazos quedan lejos de la bolsa."},"zh":{"q":"为什么你的双手应该放在方向盘两侧，而不是横放在上面？","o":["这样看起来更好看","如果安全气囊弹出，你的手臂不会被打到脸上","喇叭在上面","一只手放在上面可以转得更快"],"h1":"安全气囊是从方向盘中间弹出来的。","h2":"握住方向盘两侧能让你的手臂避开安全气囊，因为气囊会从方向盘中间猛地弹出。","p":"对。你的手臂避开了安全气囊。"},"vi":{"q":"Vì sao tay bạn nên đặt ở hai bên vô lăng thay vì vắt ngang phía trên?","o":["Trông đẹp hơn","Nếu túi khí bung ra, tay bạn sẽ không bị hất vào mặt","Còi xe ở phía trên","Bạn có thể quay nhanh hơn với một tay ở trên"],"h1":"Túi khí bung ra từ giữa vô lăng.","h2":"Cầm vô lăng ở hai bên giúp tay bạn tránh xa túi khí, vì túi khí bung mạnh ra từ giữa vô lăng.","p":"Đúng. Tay bạn tránh xa túi khí."},"tl":{"q":"Bakit dapat nasa magkabilang gilid ng manibela ang mga kamay mo sa halip na sa ibabaw nito?","o":["Mas maganda itong tingnan","Kung bumukas ang air bag, hindi tatama ang mga braso mo sa mukha mo","Nasa itaas ang busina","Mas mabilis kang makakaliko kung isang kamay ang nasa itaas"],"h1":"Lumalabas ang air bag mula sa gitna ng manibela.","h2":"Kapag hawak mo ang manibela sa magkabilang gilid, malayo ang mga braso mo sa air bag, na biglang lumalabas mula sa gitna ng manibela.","p":"Tama. Malayo ang mga braso mo sa air bag."},"ar":{"q":"لماذا يجب أن تكون يداك على جانبي عجلة القيادة بدلًا من أعلاها؟","o":["لأن ذلك يبدو أجمل","لأنه إذا انفتحت الوسادة الهوائية لن تُقذف ذراعاك نحو وجهك","لأن البوق في الأعلى","لأنك تستطيع أن تدير أسرع بيد واحدة في الأعلى"],"h1":"الوسادة الهوائية تخرج من وسط عجلة القيادة.","h2":"إمساك عجلة القيادة من الجانبين يُبعد ذراعيك عن طريق الوسادة الهوائية، التي تنفجر من وسط العجلة.","p":"صحيح. ذراعاك تبقيان بعيدتين عن الوسادة الهوائية."},"ht":{"q":"Poukisa men ou dwe sou kote volan an olye yo travèse sou anwo a?","o":["Li pi bèl","Si airbag la louvri, bra ou p ap voye nan figi ou","Klaksòn nan anwo a","Ou ka vire pi vit ak yon men anwo a"],"h1":"Airbag la soti nan mitan volan an.","h2":"Lè w kenbe volan an sou kote yo, bra ou rete lwen airbag la, ki pete soti nan mitan volan an.","p":"Se sa. Bra ou rete lwen airbag la."}},{"id":"safe-driving-062","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"How should you adjust your seat's head restraint?","o":["As low as it goes","Removed for comfort","So it is level with the back of your head, close to it","Behind your neck"],"h1":"It protects your neck in a rear-end crash.","h2":"Set the head restraint level with the back of your head and close to it, to help protect your neck if you are hit from behind.","p":"Right. Level with the back of your head."},"es":{"q":"¿Cómo debe ajustar el apoyacabezas de su asiento?","o":["Lo más bajo posible","Quitarlo para ir más cómodo","A la altura de la parte de atrás de la cabeza, cerca de ella","Detrás del cuello"],"h1":"Protege el cuello en un choque por detrás.","h2":"Ajuste el apoyacabezas a la altura de la parte de atrás de su cabeza y cerca de ella, para proteger el cuello si lo chocan por detrás.","p":"Correcto. A la altura de la parte de atrás de la cabeza."},"zh":{"q":"你应该怎样调整座椅的头枕？","o":["调到最低","为了舒服把它拿掉","调到和你的后脑勺一样高，并靠近后脑勺","放在你的脖子后面"],"h1":"在追尾撞车时，它能保护你的脖子。","h2":"把头枕调到和你的后脑勺一样高，并靠近后脑勺，这样被后面的车撞到时能帮助保护你的脖子。","p":"对。和你的后脑勺一样高。"},"vi":{"q":"Bạn nên chỉnh tựa đầu của ghế như thế nào?","o":["Thấp nhất có thể","Tháo ra cho thoải mái","Ngang với phía sau đầu và sát gần đầu bạn","Sau cổ bạn"],"h1":"Nó bảo vệ cổ bạn khi bị tông từ phía sau.","h2":"Hãy chỉnh tựa đầu ngang với phía sau đầu và sát gần đầu bạn, để giúp bảo vệ cổ nếu bạn bị tông từ phía sau.","p":"Đúng. Ngang với phía sau đầu."},"tl":{"q":"Paano mo dapat ayusin ang head restraint ng upuan mo?","o":["Pinakamababa hangga't maaari","Tinanggal para komportable","Kapantay ng likod ng ulo mo at malapit dito","Sa likod ng leeg mo"],"h1":"Pinoprotektahan nito ang leeg mo kapag nabangga ka mula sa likod.","h2":"Ilagay ang head restraint na kapantay ng likod ng ulo mo at malapit dito, para makatulong na protektahan ang leeg mo kung mabangga ka mula sa likod.","p":"Tama. Kapantay ng likod ng ulo mo."},"ar":{"q":"كيف يجب أن تضبط مسند الرأس في مقعدك؟","o":["في أدنى وضع","تنزعه من أجل الراحة","بحيث يكون بمستوى مؤخرة رأسك وقريبًا منها","خلف رقبتك"],"h1":"إنه يحمي رقبتك عند الاصطدام من الخلف.","h2":"اضبط مسند الرأس بمستوى مؤخرة رأسك وقريبًا منها، ليساعد على حماية رقبتك إذا صدمتك سيارة من الخلف.","p":"صحيح. بمستوى مؤخرة رأسك."},"ht":{"q":"Kijan ou dwe ajiste apiyetèt chèz ou a?","o":["Pi ba li ka desann","Retire l pou w pi alèz","Nan menm wotè ak dèyè tèt ou, tou pre l","Dèyè kou ou"],"h1":"Li pwoteje kou ou lè yon machin frape w pa dèyè.","h2":"Mete apiyetèt la nan menm wotè ak dèyè tèt ou epi tou pre l, pou ede pwoteje kou ou si yon machin frape w pa dèyè.","p":"Se sa. Nan menm wotè ak dèyè tèt ou."}},{"id":"safe-driving-063","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"It is a warm day. Is it safe to leave a child in a parked car for a few minutes with a window cracked open?","o":["Yes, if a window is open","Yes, if it is under 80 degrees outside","Yes, if the child is asleep","No, a car can get dangerously hot in minutes, even with a window open"],"h1":"A closed car heats up like an oven.","h2":"Never leave a child alone in a car: the inside can become deadly hot within minutes, even with a window cracked.","p":"Right. Never leave a child alone in a car."},"es":{"q":"Hace un día cálido. ¿Es seguro dejar a un niño unos minutos en el carro estacionado con una ventana un poco abierta?","o":["Sí, si hay una ventana abierta","Sí, si afuera hace menos de 80 grados","Sí, si el niño está dormido","No, un carro puede calentarse peligrosamente en minutos, aun con una ventana abierta"],"h1":"Un carro cerrado se calienta como un horno.","h2":"Nunca deje a un niño solo en un carro: el interior puede calentarse hasta ser mortal en pocos minutos, aun con una ventana un poco abierta.","p":"Correcto. Nunca deje a un niño solo en el carro."},"zh":{"q":"天气很暖和。把孩子留在停着的车里几分钟，车窗开一条缝，安全吗？","o":["安全，只要开着一扇车窗","安全，只要外面低于 80 华氏度","安全，只要孩子在睡觉","不安全，即使开着车窗，车里也会在几分钟内变得非常热，很危险"],"h1":"关着的车会像烤箱一样变热。","h2":"绝不要把孩子单独留在车里：即使车窗开了一条缝，车里也会在几分钟内热到致命。","p":"对。绝不要把孩子单独留在车里。"},"vi":{"q":"Trời ấm. Có an toàn không nếu để trẻ trong xe đang đậu vài phút với cửa sổ hé mở?","o":["Có, nếu mở một cửa sổ","Có, nếu bên ngoài dưới 80 độ F","Có, nếu trẻ đang ngủ","Không, xe có thể nóng nguy hiểm chỉ trong vài phút, kể cả khi mở cửa sổ"],"h1":"Một chiếc xe đóng kín nóng lên như lò nướng.","h2":"Đừng bao giờ để trẻ một mình trong xe: bên trong có thể nóng đến chết người chỉ trong vài phút, kể cả khi cửa sổ hé mở.","p":"Đúng. Đừng bao giờ để trẻ một mình trong xe."},"tl":{"q":"Mainit ang araw. Ligtas bang iwan ang bata sa nakaparadang kotse nang ilang minuto na bahagyang nakabukas ang bintana?","o":["Oo, kung may bintanang nakabukas","Oo, kung mas mababa sa 80 degrees sa labas","Oo, kung natutulog ang bata","Hindi, puwedeng uminit nang mapanganib ang kotse sa loob ng ilang minuto, kahit nakabukas ang bintana"],"h1":"Umiinit na parang oven ang nakasarang kotse.","h2":"Huwag kailanman iwan ang bata nang mag-isa sa kotse: puwedeng maging nakamamatay ang init sa loob sa loob ng ilang minuto, kahit bahagyang nakabukas ang bintana.","p":"Tama. Huwag kailanman iwan ang bata nang mag-isa sa kotse."},"ar":{"q":"الجو دافئ. هل من الآمن أن تترك طفلًا في سيارة متوقفة لبضع دقائق مع نافذة مفتوحة قليلًا؟","o":["نعم، إذا كانت هناك نافذة مفتوحة","نعم، إذا كانت الحرارة في الخارج أقل من 80 درجة فهرنهايت","نعم، إذا كان الطفل نائمًا","لا، السيارة قد تصبح حارة بشكل خطير خلال دقائق، حتى مع نافذة مفتوحة"],"h1":"السيارة المغلقة تسخن مثل الفرن.","h2":"يجب ألّا تترك طفلًا وحده في السيارة أبدًا: داخلها قد يصبح حارًا بشكل قاتل خلال دقائق، حتى مع نافذة مفتوحة قليلًا.","p":"صحيح. يجب ألّا تترك طفلًا وحده في السيارة أبدًا."},"ht":{"q":"Se yon jou ki fè cho. Èske li an sekirite pou w kite yon timoun nan yon machin ki kanpe pandan kèk minit ak yon fenèt ki louvri yon ti kras?","o":["Wi, si yon fenèt louvri","Wi, si li fè mwens pase 80 degre deyò","Wi, si timoun nan ap dòmi","Non, yon machin ka vin cho jiskaske li danjere nan kèk minit, menm ak yon fenèt louvri"],"h1":"Yon machin ki fèmen chofe tankou yon fou.","h2":"Pa janm kite yon timoun pou kont li nan yon machin: anndan an ka vin cho jiskaske li touye moun nan kèk minit, menm ak yon fenèt ki louvri yon ti kras.","p":"Se sa. Pa janm kite yon timoun pou kont li nan yon machin."}},{"id":"safe-driving-064","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What are the three main kinds of driver distraction?","o":["Eyes off the road, hands off the wheel, and mind off driving","Rain, fog and snow","Speed, noise and heat","Signs, signals and markings"],"h1":"Think of eyes, hands and mind.","h2":"Distraction takes your eyes off the road, your hands off the wheel, or your mind off driving; texting does all three.","p":"Right. Eyes, hands and mind."},"es":{"q":"¿Cuáles son los tres tipos principales de distracción al manejar?","o":["Ojos fuera de la vía, manos fuera del volante y mente fuera del manejo","Lluvia, niebla y nieve","Velocidad, ruido y calor","Señales, semáforos y marcas"],"h1":"Piense en los ojos, las manos y la mente.","h2":"La distracción le quita los ojos de la vía, las manos del volante o la mente del manejo; enviar mensajes de texto hace las tres cosas.","p":"Correcto. Ojos, manos y mente."},"zh":{"q":"司机分心主要有哪三种？","o":["眼睛离开路面、双手离开方向盘、心思离开驾驶","雨、雾和雪","速度、噪音和高温","标志、信号灯和路面标线"],"h1":"想一想眼睛、双手和心思。","h2":"分心会让你的眼睛离开路面、双手离开方向盘，或心思离开驾驶；发短信三种都占了。","p":"对。眼睛、双手和心思。"},"vi":{"q":"Ba loại xao lãng chính khi lái xe là gì?","o":["Mắt rời khỏi đường, tay rời khỏi vô lăng, và đầu óc rời khỏi việc lái xe","Mưa, sương mù và tuyết","Tốc độ, tiếng ồn và sức nóng","Biển báo, đèn tín hiệu và vạch kẻ đường"],"h1":"Hãy nghĩ đến mắt, tay và đầu óc.","h2":"Xao lãng làm mắt bạn rời khỏi đường, tay rời khỏi vô lăng, hoặc đầu óc rời khỏi việc lái xe; nhắn tin làm cả ba điều đó.","p":"Đúng. Mắt, tay và đầu óc."},"tl":{"q":"Ano ang tatlong pangunahing uri ng pagkagambala ng driver?","o":["Mata na wala sa daan, kamay na wala sa manibela, at isip na wala sa pagmamaneho","Ulan, hamog at niyebe","Bilis, ingay at init","Mga karatula, signal at marka sa daan"],"h1":"Isipin ang mata, kamay at isip.","h2":"Inaalis ng pagkagambala ang mata mo sa daan, ang kamay mo sa manibela, o ang isip mo sa pagmamaneho; ang pag-text ay ginagawa ang tatlo.","p":"Tama. Mata, kamay at isip."},"ar":{"q":"ما هي الأنواع الثلاثة الرئيسية لتشتت انتباه السائق؟","o":["العينان بعيدًا عن الطريق، واليدان بعيدًا عن عجلة القيادة، والذهن بعيدًا عن القيادة","المطر والضباب والثلج","السرعة والضجيج والحرارة","اللافتات والإشارات وعلامات الطريق"],"h1":"فكّر في العينين واليدين والذهن.","h2":"التشتت يُبعد عينيك عن الطريق، أو يديك عن عجلة القيادة، أو ذهنك عن القيادة؛ وكتابة الرسائل النصية تفعل الثلاثة معًا.","p":"صحيح. العينان واليدان والذهن."},"ht":{"q":"Ki twa prensipal kalite distraksyon pou yon chofè?","o":["Je ou pa sou wout la, men ou pa sou volan an, epi tèt ou pa sou kondui","Lapli, bwouya ak nèj","Vitès, bri ak chalè","Panno, siyal ak mak sou wout la"],"h1":"Panse ak je, men ak tèt.","h2":"Distraksyon retire je ou sou wout la, men ou sou volan an, oswa tèt ou sou kondui; voye tèks fè tou twa.","p":"Se sa. Je, men ak tèt."}},{"id":"safe-driving-065","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Reading a text takes your eyes off the road for about 5 seconds. At 55 mph, how far does your car travel in that time?","o":["About one car length","About the length of a football field","About 10 feet","You do not move much at all"],"h1":"At 55 mph you cover about 80 feet each second.","h2":"At 55 mph, 5 seconds with your eyes off the road is like driving the length of a football field blindfolded.","p":"Right. About a football field."},"es":{"q":"Leer un mensaje le quita los ojos de la vía unos 5 segundos. A 55 mph, ¿cuánto avanza su carro en ese tiempo?","o":["Más o menos el largo de un carro","Más o menos el largo de una cancha de fútbol americano","Unos 10 pies","Casi no se mueve"],"h1":"A 55 mph avanza unos 80 pies por segundo.","h2":"A 55 mph, 5 segundos sin mirar la vía es como recorrer el largo de una cancha de fútbol americano con los ojos vendados.","p":"Correcto. Más o menos una cancha de fútbol americano."},"zh":{"q":"看一条短信会让你的眼睛离开路面大约 5 秒。以 55 mph 的速度，你的车在这段时间里会开多远？","o":["大约一辆车的长度","大约一个美式足球场的长度","大约 10 英尺","你几乎没有移动"],"h1":"以 55 mph 行驶，你每秒大约开 80 英尺。","h2":"以 55 mph 行驶，眼睛离开路面 5 秒，就像蒙着眼睛开过一个美式足球场那么长的距离。","p":"对。大约一个美式足球场。"},"vi":{"q":"Đọc một tin nhắn làm mắt bạn rời khỏi đường khoảng 5 giây. Ở tốc độ 55 mph, xe bạn đi được bao xa trong thời gian đó?","o":["Khoảng một chiều dài xe","Khoảng chiều dài một sân bóng bầu dục","Khoảng 10 feet","Bạn hầu như không di chuyển"],"h1":"Ở tốc độ 55 mph, bạn đi khoảng 80 feet mỗi giây.","h2":"Ở tốc độ 55 mph, 5 giây không nhìn đường giống như bịt mắt lái hết chiều dài một sân bóng bầu dục.","p":"Đúng. Khoảng một sân bóng bầu dục."},"tl":{"q":"Ang pagbasa ng text ay nag-aalis ng mata mo sa daan nang mga 5 segundo. Sa 55 mph, gaano kalayo ang tinatakbo ng kotse mo sa panahong iyon?","o":["Mga isang haba ng kotse","Mga haba ng isang football field","Mga 10 feet","Halos hindi ka gumagalaw"],"h1":"Sa 55 mph, mga 80 feet ang tinatakbo mo bawat segundo.","h2":"Sa 55 mph, ang 5 segundong hindi nakatingin sa daan ay parang pagmamaneho nang nakapiring sa haba ng isang football field.","p":"Tama. Mga isang football field."},"ar":{"q":"قراءة رسالة نصية تُبعد عينيك عن الطريق حوالي 5 ثوانٍ. بسرعة 55 mph، كم تقطع سيارتك في هذا الوقت؟","o":["حوالي طول سيارة واحدة","حوالي طول ملعب كرة قدم أمريكية","حوالي 10 أقدام (feet)","لا تتحرك تقريبًا"],"h1":"بسرعة 55 mph تقطع حوالي 80 قدمًا (feet) كل ثانية.","h2":"بسرعة 55 mph، 5 ثوانٍ وعيناك بعيدتان عن الطريق تشبه أن تقود طول ملعب كرة قدم أمريكية وعيناك معصوبتان.","p":"صحيح. حوالي طول ملعب كرة قدم."},"ht":{"q":"Li yon tèks retire je ou sou wout la pandan anviwon 5 segond. A 55 mph, ki distans machin ou fè nan tan sa a?","o":["Anviwon longè yon machin","Anviwon longè yon teren foutbòl ameriken","Anviwon 10 pye","Ou prèske pa deplase ditou"],"h1":"A 55 mph ou fè anviwon 80 pye chak segond.","h2":"A 55 mph, 5 segond san je ou sou wout la se tankou kondui longè yon teren foutbòl ameriken ak je ou bande.","p":"Se sa. Anviwon yon teren foutbòl."}},{"id":"safe-driving-066","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Is talking on a hands-free phone while driving free of distraction?","o":["Yes, it is completely safe","Yes, if you use one hand","No, the conversation still takes your mind off driving","Yes, at low speeds"],"h1":"Distraction is not only about your hands.","h2":"Even hands-free, a phone conversation pulls your attention away from the road, so you notice and react to hazards more slowly.","p":"Right. Your mind is still distracted."},"es":{"q":"¿Hablar por un teléfono con manos libres mientras maneja está libre de distracción?","o":["Sí, es totalmente seguro","Sí, si usa una mano","No, la conversación igual le quita la mente del manejo","Sí, a baja velocidad"],"h1":"La distracción no tiene que ver solo con las manos.","h2":"Aun con manos libres, una conversación por teléfono le quita atención a la vía, así que nota los peligros y reacciona más lento.","p":"Correcto. Su mente igual se distrae."},"zh":{"q":"开车时用免提电话讲话，就不会分心吗？","o":["是的，完全安全","是的，只要你用一只手","不是，谈话仍然会让你的心思离开驾驶","是的，只要车速很低"],"h1":"分心不只是和你的双手有关。","h2":"即使是免提，打电话也会把你的注意力从路面上拉走，所以你发现危险和作出反应都会更慢。","p":"对。你的心思还是分散了。"},"vi":{"q":"Nói chuyện bằng điện thoại rảnh tay khi lái xe có phải là không bị xao lãng không?","o":["Đúng, hoàn toàn an toàn","Đúng, nếu bạn dùng một tay","Không, cuộc trò chuyện vẫn làm đầu óc bạn rời khỏi việc lái xe","Đúng, khi chạy chậm"],"h1":"Xao lãng không chỉ liên quan đến tay bạn.","h2":"Dù dùng rảnh tay, một cuộc nói chuyện điện thoại vẫn kéo sự chú ý của bạn ra khỏi đường, nên bạn nhận ra và phản ứng với nguy hiểm chậm hơn.","p":"Đúng. Đầu óc bạn vẫn bị xao lãng."},"tl":{"q":"Kapag nakikipag-usap sa hands-free na telepono habang nagmamaneho, wala na bang pagkagambala?","o":["Oo, ganap itong ligtas","Oo, kung isang kamay ang gamit mo","Hindi, inaalis pa rin ng pag-uusap ang isip mo sa pagmamaneho","Oo, sa mababang bilis"],"h1":"Ang pagkagambala ay hindi lang tungkol sa mga kamay mo.","h2":"Kahit hands-free, hinihila ng pakikipag-usap sa telepono ang atensyon mo palayo sa daan, kaya mas mabagal mong napapansin at natutugunan ang mga panganib.","p":"Tama. Gambala pa rin ang isip mo."},"ar":{"q":"هل التحدث بالهاتف دون استخدام اليدين أثناء القيادة خالٍ من تشتت الانتباه؟","o":["نعم، إنه آمن تمامًا","نعم، إذا استعملت يدًا واحدة","لا، المحادثة ما زالت تُبعد ذهنك عن القيادة","نعم، في السرعات المنخفضة"],"h1":"التشتت لا يتعلق بيديك فقط.","h2":"حتى دون استخدام اليدين، المحادثة الهاتفية تسحب انتباهك بعيدًا عن الطريق، فتلاحظ المخاطر وتتفاعل معها ببطء أكبر.","p":"صحيح. ذهنك ما زال مشتتًا."},"ht":{"q":"Èske pale nan yon telefòn san men pandan w ap kondui pa gen okenn distraksyon?","o":["Wi, li an sekirite nèt","Wi, si w sèvi ak yon sèl men","Non, konvèsasyon an toujou retire tèt ou sou kondui","Wi, lè w ap kondui dousman"],"h1":"Distraksyon pa sèlman gen pou wè ak men ou.","h2":"Menm san men, yon konvèsasyon nan telefòn rale atansyon ou lwen wout la, kidonk ou remake danje yo epi reyaji pi dousman.","p":"Se sa. Tèt ou toujou distrè."}},{"id":"safe-driving-067","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"When is the best time to set your GPS route and music?","o":["While driving on the highway","At a red light, while moving slowly","While turning","Before you start driving"],"h1":"Do it when the car is not moving.","h2":"Set your GPS, music and other controls before you start driving, or pull over safely if you need to change them.","p":"Right. Before you start driving."},"es":{"q":"¿Cuál es el mejor momento para programar el GPS y la música?","o":["Mientras maneja en la carretera","En un semáforo, mientras avanza despacio","Mientras gira","Antes de empezar a manejar"],"h1":"Hágalo cuando el carro no se mueve.","h2":"Programe el GPS, la música y otros controles antes de empezar a manejar, u oríllese con seguridad si necesita cambiarlos.","p":"Correcto. Antes de empezar a manejar."},"zh":{"q":"什么时候设置 GPS 路线和音乐最好？","o":["在高速公路上开车时","在红灯前或慢慢行驶时","在转弯时","在你开始开车之前"],"h1":"在车没有移动的时候做。","h2":"你应该在开始开车之前设置好 GPS、音乐和其他控制；如果需要更改，请先安全地靠边停车。","p":"对。在你开始开车之前。"},"vi":{"q":"Khi nào là lúc tốt nhất để cài đặt lộ trình GPS và nhạc?","o":["Khi đang lái trên xa lộ","Khi dừng đèn đỏ, hoặc khi đang chạy chậm","Khi đang rẽ","Trước khi bạn bắt đầu lái xe"],"h1":"Hãy làm khi xe không di chuyển.","h2":"Hãy cài đặt GPS, nhạc và các nút điều khiển khác trước khi bạn bắt đầu lái xe, hoặc tấp vào lề an toàn nếu cần thay đổi.","p":"Đúng. Trước khi bạn bắt đầu lái xe."},"tl":{"q":"Kailan ang pinakamagandang oras para i-set ang ruta ng GPS at ang musika?","o":["Habang nagmamaneho sa highway","Sa red light, habang mabagal na umaandar","Habang lumiliko","Bago ka magsimulang magmaneho"],"h1":"Gawin ito kapag hindi gumagalaw ang kotse.","h2":"I-set ang GPS, musika at iba pang kontrol bago ka magsimulang magmaneho, o tumabi nang ligtas kung kailangan mo itong baguhin.","p":"Tama. Bago ka magsimulang magmaneho."},"ar":{"q":"ما أفضل وقت لضبط مسار GPS والموسيقى؟","o":["أثناء القيادة على الطريق السريع","عند الإشارة الحمراء، أثناء السير ببطء","أثناء الانعطاف","قبل أن تبدأ القيادة"],"h1":"افعل ذلك عندما لا تكون السيارة متحركة.","h2":"اضبط GPS والموسيقى وباقي أدوات التحكم قبل أن تبدأ القيادة، أو توقّف جانبًا بأمان إذا احتجت إلى تغييرها.","p":"صحيح. قبل أن تبدأ القيادة."},"ht":{"q":"Ki pi bon moman pou regle wout GPS ou ak mizik ou?","o":["Pandan w ap kondui sou otowout la","Nan yon limyè wouj, pandan w ap woule dousman","Pandan w ap vire","Anvan ou kòmanse kondui"],"h1":"Fè l lè machin nan pa an mouvman.","h2":"Regle GPS ou, mizik ou ak lòt kontwòl yo anvan ou kòmanse kondui, oswa rale sou kote a an sekirite si ou bezwen chanje yo.","p":"Se sa. Anvan ou kòmanse kondui."}},{"id":"safe-driving-068","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Why should you secure loose items, like bags or bottles, inside your car?","o":["They can fly forward in a crash or roll under the brake pedal","They make the car heavier","They block the radio","They make noise"],"h1":"Loose items keep moving when the car stops suddenly.","h2":"Loose objects can fly through the car in a sudden stop or crash, and can roll under your pedals, so put them away or secure them.","p":"Right. They can fly or block the pedals."},"es":{"q":"¿Por qué debe asegurar los objetos sueltos, como bolsas o botellas, dentro del carro?","o":["Porque pueden salir volando en un choque o rodar debajo del pedal del freno","Porque hacen el carro más pesado","Porque tapan el radio","Porque hacen ruido"],"h1":"Los objetos sueltos siguen moviéndose cuando el carro se para de golpe.","h2":"Los objetos sueltos pueden salir volando dentro del carro en una frenada o un choque, y pueden rodar debajo de los pedales, así que guárdelos o asegúrelos.","p":"Correcto. Pueden salir volando o trabar los pedales."},"zh":{"q":"为什么你应该把车里松散的物品（比如包或瓶子）固定好？","o":["在撞车时它们会向前飞，或滚到刹车踏板下面","它们会让车变重","它们会挡住收音机","它们会发出噪音"],"h1":"车突然停下时，松散的物品会继续移动。","h2":"在急停或撞车时，松散的物品会在车里飞起来，还会滚到踏板下面，所以要把它们收好或固定好。","p":"对。它们会飞起来或挡住踏板。"},"vi":{"q":"Tại sao bạn nên cố định các đồ vật để lỏng, như túi hoặc chai, trong xe?","o":["Chúng có thể văng về phía trước khi va chạm hoặc lăn xuống dưới bàn đạp thắng","Chúng làm xe nặng hơn","Chúng che radio","Chúng gây tiếng ồn"],"h1":"Đồ vật để lỏng vẫn tiếp tục di chuyển khi xe dừng đột ngột.","h2":"Đồ vật để lỏng có thể văng khắp xe khi dừng gấp hoặc va chạm, và có thể lăn xuống dưới bàn đạp, nên hãy cất chúng đi hoặc cố định lại.","p":"Đúng. Chúng có thể văng ra hoặc chặn bàn đạp."},"tl":{"q":"Bakit dapat mong ayusin at itali ang mga maluwag na gamit, gaya ng bag o bote, sa loob ng kotse mo?","o":["Puwede silang tumilapon pasulong sa banggaan o gumulong sa ilalim ng brake pedal","Pinabibigat nila ang kotse","Natatakpan nila ang radyo","Nag-iingay sila"],"h1":"Patuloy na gumagalaw ang maluwag na gamit kapag biglang huminto ang kotse.","h2":"Puwedeng tumilapon sa loob ng kotse ang maluwag na gamit kapag biglang huminto o nabangga, at puwede itong gumulong sa ilalim ng mga pedal, kaya itabi o itali ang mga ito.","p":"Tama. Puwede silang tumilapon o humarang sa mga pedal."},"ar":{"q":"لماذا يجب أن تثبّت الأشياء غير المثبّتة، مثل الحقائب أو الزجاجات، داخل سيارتك؟","o":["قد تطير إلى الأمام في حادث أو تتدحرج تحت دوّاسة الفرامل","تجعل السيارة أثقل","تحجب الراديو","تُحدث ضجيجًا"],"h1":"الأشياء غير المثبّتة تستمر في الحركة عندما تتوقف السيارة فجأة.","h2":"الأشياء غير المثبّتة قد تطير داخل السيارة عند التوقف المفاجئ أو في حادث، وقد تتدحرج تحت الدوّاسات، لذلك ضعها في مكانها أو ثبّتها.","p":"صحيح. قد تطير أو تعيق الدوّاسات."},"ht":{"q":"Poukisa ou ta dwe mare oswa sere bagay ki lach, tankou sak oswa boutèy, anndan machin ou?","o":["Yo ka vole devan nan yon aksidan oswa woule anba pedal fren an","Yo fè machin nan pi lou","Yo bloke radyo a","Yo fè bri"],"h1":"Bagay ki lach kontinye deplase lè machin nan kanpe sanzatann.","h2":"Bagay ki lach ka vole nan machin nan lè ou kanpe sanzatann oswa nan yon aksidan, epi yo ka woule anba pedal yo, kidonk sere yo oswa mare yo.","p":"Se sa. Yo ka vole oswa bloke pedal yo."}},{"id":"safe-driving-069","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Which of these is a warning sign that you are too tired to drive?","o":["Feeling hungry","Yawning, heavy eyes, drifting from your lane, or missing your exit","Wanting to listen to music","Feeling cold"],"h1":"Your body warns you before you fall asleep.","h2":"Frequent yawning, heavy eyelids, drifting out of your lane and missing exits are signs you are too drowsy to drive safely.","p":"Right. These are signs of drowsiness."},"es":{"q":"¿Cuál de estas es una señal de que está demasiado cansado para manejar?","o":["Tener hambre","Bostezar, tener los ojos pesados, salirse del carril o pasarse la salida","Querer escuchar música","Tener frío"],"h1":"Su cuerpo le avisa antes de dormirse.","h2":"Bostezar seguido, tener los párpados pesados, salirse del carril y pasarse las salidas son señales de que tiene demasiado sueño para manejar con seguridad.","p":"Correcto. Son señales de sueño."},"zh":{"q":"下面哪一项是你太累、不能开车的警告信号？","o":["觉得饿","打哈欠、眼皮沉重、偏离车道，或错过出口","想听音乐","觉得冷"],"h1":"在你睡着之前，身体会提醒你。","h2":"经常打哈欠、眼皮沉重、偏离车道和错过出口，都是你太困、不能安全开车的信号。","p":"对。这些都是困倦的信号。"},"vi":{"q":"Điều nào sau đây là dấu hiệu cảnh báo bạn quá mệt để lái xe?","o":["Cảm thấy đói","Ngáp, mí mắt nặng, xe trôi ra khỏi làn, hoặc lỡ lối ra","Muốn nghe nhạc","Cảm thấy lạnh"],"h1":"Cơ thể bạn cảnh báo trước khi bạn ngủ gật.","h2":"Ngáp nhiều, mí mắt nặng, xe trôi ra khỏi làn và lỡ lối ra là dấu hiệu bạn quá buồn ngủ để lái xe an toàn.","p":"Đúng. Đây là dấu hiệu buồn ngủ."},"tl":{"q":"Alin dito ang babalang senyales na masyado ka nang pagod para magmaneho?","o":["Nakararamdam ng gutom","Paghikab, mabigat na mata, paglihis sa lane mo, o paglampas sa exit mo","Gustong makinig ng musika","Nakararamdam ng lamig"],"h1":"Binabalaan ka ng katawan mo bago ka makatulog.","h2":"Ang madalas na paghikab, mabigat na talukap ng mata, paglihis sa lane mo at paglampas sa mga exit ay senyales na masyado kang inaantok para magmaneho nang ligtas.","p":"Tama. Mga senyales ito ng antok."},"ar":{"q":"أيّ مما يلي علامة تحذير على أنك متعب جدًا ولا تستطيع القيادة؟","o":["الشعور بالجوع","التثاؤب، وثِقل الجفنين، والانحراف عن مسارك، أو تفويت مخرجك","الرغبة في الاستماع إلى الموسيقى","الشعور بالبرد"],"h1":"جسمك يحذّرك قبل أن تنام.","h2":"كثرة التثاؤب وثِقل الجفنين والانحراف عن مسارك وتفويت المخارج كلها علامات على أنك نعسان جدًا ولا تستطيع القيادة بأمان.","p":"صحيح. هذه علامات النعاس."},"ht":{"q":"Kilès nan sa yo ki se yon siy avètisman ke ou twò fatige pou kondui?","o":["Santi ou grangou","Baye, je lou, machin nan ap soti nan liy ou, oswa ou rate sòti ou","Anvi koute mizik","Santi ou frèt"],"h1":"Kò ou avèti w anvan ou tonbe dòmi.","h2":"Baye souvan, pòpyè lou, machin nan ki ap soti nan liy ou ak rate sòti yo se siy ke ou gen twòp dòmi pou kondui an sekirite.","p":"Se sa. Sa yo se siy dòmi."}},{"id":"safe-driving-070","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You feel sleepy while driving. Will opening the window or turning up the radio keep you safe?","o":["Yes, cold air always works","Yes, loud music keeps you awake","No, only sleep fixes drowsiness; pull off safely and rest","Yes, if you also chew gum"],"h1":"These tricks do not last.","h2":"Opening a window or turning up the radio does not fix drowsiness; the only real cure is sleep, so pull off safely and rest.","p":"Right. Only sleep fixes it."},"es":{"q":"Siente sueño mientras maneja. ¿Abrir la ventana o subir el radio lo mantendrá seguro?","o":["Sí, el aire frío siempre funciona","Sí, la música alta lo mantiene despierto","No, solo dormir quita el sueño; oríllese con seguridad y descanse","Sí, si además masca chicle"],"h1":"Estos trucos no duran.","h2":"Abrir la ventana o subir el radio no quita el sueño; la única solución real es dormir, así que oríllese con seguridad y descanse.","p":"Correcto. Solo dormir lo soluciona."},"zh":{"q":"你开车时觉得困。打开车窗或把收音机开大声，能让你安全吗？","o":["能，冷空气总是有用","能，大声的音乐让你保持清醒","不能，只有睡觉才能解决困倦；安全地离开道路并休息","能，如果你同时嚼口香糖"],"h1":"这些办法维持不了多久。","h2":"打开车窗或把收音机开大声都不能解决困倦；真正的办法只有睡觉，所以要安全地离开道路并休息。","p":"对。只有睡觉才能解决。"},"vi":{"q":"Bạn thấy buồn ngủ khi đang lái xe. Mở cửa sổ hoặc vặn to radio có giữ bạn an toàn không?","o":["Có, không khí lạnh luôn hiệu quả","Có, nhạc to giúp bạn tỉnh táo","Không, chỉ có ngủ mới hết buồn ngủ; hãy tấp vào an toàn và nghỉ ngơi","Có, nếu bạn cũng nhai kẹo cao su"],"h1":"Những mẹo này không kéo dài.","h2":"Mở cửa sổ hoặc vặn to radio không làm hết buồn ngủ; cách duy nhất thật sự là ngủ, nên hãy tấp vào an toàn và nghỉ ngơi.","p":"Đúng. Chỉ có ngủ mới giải quyết được."},"tl":{"q":"Inaantok ka habang nagmamaneho. Mapapanatili ka bang ligtas ng pagbukas ng bintana o paglakas ng radyo?","o":["Oo, laging gumagana ang malamig na hangin","Oo, pinananatili kang gising ng malakas na musika","Hindi, tulog lang ang lunas sa antok; tumabi nang ligtas at magpahinga","Oo, kung ngumunguya ka rin ng chewing gum"],"h1":"Hindi tumatagal ang mga paraang ito.","h2":"Hindi naaalis ng pagbukas ng bintana o paglakas ng radyo ang antok; tulog lang ang tunay na lunas, kaya tumabi nang ligtas at magpahinga.","p":"Tama. Tulog lang ang lunas."},"ar":{"q":"تشعر بالنعاس أثناء القيادة. هل فتح النافذة أو رفع صوت الراديو يحافظ على سلامتك؟","o":["نعم، الهواء البارد ينفع دائمًا","نعم، الموسيقى العالية تبقيك مستيقظًا","لا، النوم وحده يعالج النعاس؛ اخرج من الطريق بأمان واسترح","نعم، إذا مضغت العلكة أيضًا"],"h1":"هذه الحيل لا تدوم.","h2":"فتح النافذة أو رفع صوت الراديو لا يعالج النعاس؛ العلاج الحقيقي الوحيد هو النوم، لذلك اخرج من الطريق بأمان واسترح.","p":"صحيح. النوم وحده يعالجه."},"ht":{"q":"Ou santi ou gen dòmi pandan w ap kondui. Èske ouvri fenèt la oswa monte volim radyo a ap kenbe w an sekirite?","o":["Wi, lè frèt toujou mache","Wi, mizik fò kenbe w reveye","Non, se sèlman dòmi ki geri dòmi; rale sou kote a an sekirite epi repoze w","Wi, si ou kraze chiklèt tou"],"h1":"Ti trik sa yo pa dire.","h2":"Ouvri fenèt la oswa monte volim radyo a pa geri dòmi; sèl vrè remèd la se dòmi, kidonk rale sou kote a an sekirite epi repoze w.","p":"Se sa. Se sèlman dòmi ki geri l."}},{"id":"safe-driving-071","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"On a long, straight highway, you feel dazed and are not paying attention, as if half asleep. What is this called, and what helps?","o":["Road rage; drive faster","Tunnel vision; close one eye","Night blindness; turn on high beams","Highway hypnosis; keep your eyes moving and take breaks"],"h1":"Long, boring drives can dull your mind.","h2":"Highway hypnosis is a dazed state on long, unchanging drives; keep your eyes moving, check mirrors, and stop for breaks.","p":"Right. Highway hypnosis; move your eyes and take breaks."},"es":{"q":"En una carretera larga y recta, se siente aturdido y sin prestar atención, como medio dormido. ¿Cómo se llama esto y qué ayuda?","o":["Furia al volante; maneje más rápido","Visión de túnel; cierre un ojo","Ceguera nocturna; encienda las luces altas","Hipnosis de carretera; mueva los ojos y tome descansos"],"h1":"Los viajes largos y aburridos adormecen la mente.","h2":"La hipnosis de carretera es un estado de aturdimiento en viajes largos y monótonos; mueva los ojos, mire los espejos y pare a descansar.","p":"Correcto. Hipnosis de carretera; mueva los ojos y descanse."},"zh":{"q":"在又长又直的高速公路上，你觉得发呆、不集中注意力，好像半睡半醒。这叫什么？什么办法有帮助？","o":["路怒；开得更快","管状视野；闭上一只眼睛","夜盲；打开远光灯","高速公路催眠；让眼睛不停移动并休息"],"h1":"又长又无聊的驾驶会让头脑变迟钝。","h2":"高速公路催眠是在长时间、景色不变的驾驶中出现的发呆状态；要让眼睛不停移动、查看后视镜，并停车休息。","p":"对。高速公路催眠；移动眼睛并休息。"},"vi":{"q":"Trên xa lộ dài và thẳng, bạn thấy lơ mơ và không chú ý, như đang nửa ngủ. Hiện tượng này gọi là gì, và điều gì giúp ích?","o":["Nổi nóng khi lái xe; chạy nhanh hơn","Tầm nhìn hẹp; nhắm một mắt","Quáng gà; bật đèn pha","Thôi miên xa lộ; giữ mắt luôn di chuyển và nghỉ giải lao"],"h1":"Những chuyến đi dài, nhàm chán có thể làm đầu óc bạn lờ đờ.","h2":"Thôi miên xa lộ là trạng thái lơ mơ khi lái lâu trên đường không thay đổi; hãy giữ mắt luôn di chuyển, nhìn gương và dừng lại nghỉ giải lao.","p":"Đúng. Thôi miên xa lộ; di chuyển mắt và nghỉ giải lao."},"tl":{"q":"Sa mahaba at diretsong highway, parang tulala ka at hindi nakatutok, na parang kalahating tulog. Ano ang tawag dito, at ano ang nakatutulong?","o":["Road rage; magmaneho nang mas mabilis","Tunnel vision; ipikit ang isang mata","Night blindness; buksan ang high beams","Highway hypnosis; panatilihing gumagalaw ang mata mo at magpahinga"],"h1":"Nakapagpapapurol ng isip ang mahaba at nakababagot na biyahe.","h2":"Ang highway hypnosis ay pagkatulala sa mahaba at hindi nagbabagong biyahe; panatilihing gumagalaw ang mata mo, tingnan ang mga salamin, at huminto para magpahinga.","p":"Tama. Highway hypnosis; igalaw ang mata mo at magpahinga."},"ar":{"q":"على طريق سريع طويل ومستقيم، تشعر بالشرود وعدم الانتباه، كأنك نصف نائم. ماذا تُسمّى هذه الحالة، وما الذي يساعد؟","o":["غضب الطريق؛ قُد بسرعة أكبر","الرؤية النفقية؛ أغمض عينًا واحدة","العمى الليلي؛ شغّل الأضواء العالية","تنويم الطريق السريع؛ حرّك عينيك باستمرار وخذ فترات راحة"],"h1":"القيادة الطويلة المملة قد تُضعف تركيزك.","h2":"تنويم الطريق السريع حالة شرود تحدث في القيادة الطويلة التي لا يتغير فيها شيء؛ حرّك عينيك باستمرار، وانظر في المرايا، وتوقّف لتأخذ فترات راحة.","p":"صحيح. تنويم الطريق السريع؛ حرّك عينيك وخذ فترات راحة."},"ht":{"q":"Sou yon otowout ki long epi ki dwat, ou santi ou toudi epi ou pa fè atansyon, kòm si ou mwatye ap dòmi. Kijan yo rele sa, epi kisa ki ede?","o":["Kòlè sou wout; kondui pi vit","Vizyon tinèl; fèmen yon grenn je","Avèg lannwit; limen gwo limyè yo","Ipnoz otowout; kenbe je w ap deplase epi pran poz"],"h1":"Vwayaj ki long epi ki raz ka fè lespri w vin lou.","h2":"Ipnoz otowout se yon eta toudi ki rive nan vwayaj long kote anyen pa chanje; kenbe je w ap deplase, gade retwovizè yo, epi kanpe pou pran poz.","p":"Se sa. Ipnoz otowout; deplase je w epi pran poz."}},{"id":"safe-driving-072","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Besides judgment, what does alcohol do to a driver?","o":["It slows reaction time and hurts coordination and vision","It makes reactions faster","It improves night vision","It has no effect after one drink"],"h1":"Alcohol slows the brain and body.","h2":"Alcohol slows your reactions and harms your coordination, vision and ability to judge speed and distance.","p":"Right. Slower reactions and worse coordination and vision."},"es":{"q":"Además del juicio, ¿qué le hace el alcohol a un conductor?","o":["Hace más lentos los reflejos y empeora la coordinación y la vista","Hace más rápidos los reflejos","Mejora la vista de noche","No tiene efecto después de un trago"],"h1":"El alcohol hace más lentos el cerebro y el cuerpo.","h2":"El alcohol hace más lentos sus reflejos y empeora la coordinación, la vista y la capacidad de calcular velocidad y distancia.","p":"Correcto. Reflejos más lentos y peor coordinación y vista."},"zh":{"q":"除了判断力，酒精还会对司机产生什么影响？","o":["它会让反应变慢，并损害协调能力和视力","它会让反应变快","它会改善夜间视力","喝一杯以后就没有影响"],"h1":"酒精会让大脑和身体变慢。","h2":"酒精会让你的反应变慢，并损害你的协调能力、视力，以及判断速度和距离的能力。","p":"对。反应变慢，协调能力和视力变差。"},"vi":{"q":"Ngoài khả năng phán đoán, rượu bia còn ảnh hưởng gì đến người lái xe?","o":["Làm phản ứng chậm lại và làm giảm khả năng phối hợp và thị lực","Làm phản ứng nhanh hơn","Cải thiện thị lực ban đêm","Không ảnh hưởng gì sau một ly"],"h1":"Rượu bia làm não và cơ thể chậm lại.","h2":"Rượu bia làm phản ứng của bạn chậm lại và làm hại khả năng phối hợp, thị lực và khả năng ước lượng tốc độ và khoảng cách.","p":"Đúng. Phản ứng chậm hơn, phối hợp và thị lực kém hơn."},"tl":{"q":"Bukod sa paghuhusga, ano pa ang epekto ng alak sa drayber?","o":["Pinababagal nito ang reaksiyon at sinisira ang koordinasyon at paningin","Pinabibilis nito ang reaksiyon","Pinagaganda nito ang paningin sa gabi","Wala itong epekto pagkatapos ng isang inumin"],"h1":"Pinababagal ng alak ang utak at katawan.","h2":"Pinababagal ng alak ang reaksiyon mo at sinisira ang koordinasyon mo, paningin mo at kakayahan mong tantiyahin ang bilis at layo.","p":"Tama. Mas mabagal na reaksiyon at mas mahinang koordinasyon at paningin."},"ar":{"q":"إلى جانب الحكم على الأمور، ماذا يفعل الكحول بالسائق؟","o":["يُبطئ سرعة الاستجابة ويضرّ بالتناسق الحركي والرؤية","يجعل الاستجابة أسرع","يحسّن الرؤية في الليل","ليس له أي تأثير بعد مشروب واحد"],"h1":"الكحول يُبطئ الدماغ والجسم.","h2":"الكحول يُبطئ استجابتك ويضرّ بتناسقك الحركي ورؤيتك وقدرتك على تقدير السرعة والمسافة.","p":"صحيح. استجابة أبطأ وتناسق ورؤية أسوأ."},"ht":{"q":"Apa jijman, kisa alkòl fè yon chofè?","o":["Li fè reyaksyon an pi lan epi li fè kowòdinasyon ak vizyon an mal","Li fè reyaksyon yo pi rapid","Li amelyore vizyon lannwit","Li pa gen okenn efè apre yon sèl bwason"],"h1":"Alkòl fè sèvo a ak kò a vin pi lan.","h2":"Alkòl fè reyaksyon ou pi lan epi li fè mal kowòdinasyon ou, vizyon ou ak kapasite ou pou jije vitès ak distans.","p":"Se sa. Reyaksyon pi lan, kowòdinasyon ak vizyon pi mal."}},{"id":"safe-driving-073","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Which has about the same amount of alcohol as a 12-ounce regular beer?","o":["A full bottle of wine","A 5-ounce glass of wine or a 1.5-ounce shot of liquor","Three shots of liquor","None; beer has much less alcohol"],"h1":"A \"standard drink\" is the same amount of alcohol in different drinks.","h2":"A 12-ounce regular beer, a 5-ounce glass of wine and a 1.5-ounce shot of liquor each hold about the same amount of alcohol.","p":"Right. They are all about one standard drink."},"es":{"q":"¿Qué tiene más o menos la misma cantidad de alcohol que una cerveza normal de 12 onzas?","o":["Una botella entera de vino","Una copa de vino de 5 onzas o un trago de licor de 1.5 onzas","Tres tragos de licor","Nada; la cerveza tiene mucho menos alcohol"],"h1":"Una \"bebida estándar\" es la misma cantidad de alcohol en distintas bebidas.","h2":"Una cerveza normal de 12 onzas, una copa de vino de 5 onzas y un trago de licor de 1.5 onzas tienen más o menos la misma cantidad de alcohol.","p":"Correcto. Todas son más o menos una bebida estándar."},"zh":{"q":"哪一种饮料含有的酒精，和一罐 12 盎司的普通啤酒差不多？","o":["一整瓶葡萄酒","一杯 5 盎司的葡萄酒，或一小杯 1.5 盎司的烈酒","三小杯烈酒","没有；啤酒含的酒精少得多"],"h1":"“标准饮酒量”是指不同饮料中相同的酒精量。","h2":"一罐 12 盎司的普通啤酒、一杯 5 盎司的葡萄酒和一小杯 1.5 盎司的烈酒，含有的酒精量差不多。","p":"对。它们都大约是一个标准饮酒量。"},"vi":{"q":"Thứ nào có lượng cồn gần bằng một lon bia thường 12 ounce?","o":["Nguyên một chai rượu vang","Một ly rượu vang 5 ounce hoặc một ly nhỏ rượu mạnh 1.5 ounce","Ba ly nhỏ rượu mạnh","Không có; bia có ít cồn hơn nhiều"],"h1":"Một \"ly tiêu chuẩn\" là cùng một lượng cồn trong các loại đồ uống khác nhau.","h2":"Một lon bia thường 12 ounce, một ly rượu vang 5 ounce và một ly nhỏ rượu mạnh 1.5 ounce đều chứa lượng cồn gần bằng nhau.","p":"Đúng. Tất cả đều khoảng một ly tiêu chuẩn."},"tl":{"q":"Alin ang may halos parehong dami ng alkohol ng isang 12-ounce na regular na beer?","o":["Isang buong bote ng wine","Isang 5-ounce na baso ng wine o isang 1.5-ounce na shot ng alak","Tatlong shot ng alak","Wala; mas kaunti ang alkohol ng beer"],"h1":"Ang \"standard drink\" ay parehong dami ng alkohol sa iba't ibang inumin.","h2":"Ang isang 12-ounce na regular na beer, isang 5-ounce na baso ng wine at isang 1.5-ounce na shot ng alak ay may halos parehong dami ng alkohol.","p":"Tama. Lahat sila ay mga isang standard drink."},"ar":{"q":"أيّ مما يلي فيه تقريبًا نفس كمية الكحول الموجودة في بيرة عادية حجمها 12 أونصة (ounce)؟","o":["زجاجة نبيذ كاملة","كأس نبيذ 5 أونصات (ounces) أو جرعة مشروب كحولي قوي 1.5 أونصة (ounces)","ثلاث جرعات من مشروب كحولي قوي","لا شيء؛ البيرة فيها كحول أقل بكثير"],"h1":"\"المشروب القياسي\" هو نفس كمية الكحول في مشروبات مختلفة.","h2":"البيرة العادية بحجم 12 أونصة (ounces)، وكأس النبيذ بحجم 5 أونصات (ounces)، وجرعة المشروب الكحولي القوي بحجم 1.5 أونصة (ounces)، في كل منها تقريبًا نفس كمية الكحول.","p":"صحيح. كلها تقريبًا مشروب قياسي واحد."},"ht":{"q":"Kilès ki gen apeprè menm kantite alkòl ak yon byè regilye 12 ons?","o":["Yon boutèy diven tou plen","Yon vè diven 5 ons oswa yon ti vè likè fò 1.5 ons","Twa ti vè likè fò","Okenn; byè gen anpil mwens alkòl"],"h1":"Yon \"bwason estanda\" se menm kantite alkòl nan diferan bwason.","h2":"Yon byè regilye 12 ons, yon vè diven 5 ons ak yon ti vè likè fò 1.5 ons chak gen apeprè menm kantite alkòl.","p":"Se sa. Yo tout se apeprè yon bwason estanda."}},{"id":"safe-driving-074","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Can marijuana make you unsafe to drive, even where it is legal?","o":["No, if it is legal it is safe","No, it only affects passengers","Yes, it slows reaction time and affects judgment of time and distance","Only if mixed with coffee"],"h1":"Legal does not mean safe for driving.","h2":"Marijuana can slow your reactions and affect your judgment of time and distance, so driving after using it is unsafe even where it is legal.","p":"Right. It can make driving unsafe."},"es":{"q":"¿La marihuana puede hacer que manejar sea inseguro, aun donde es legal?","o":["No, si es legal es segura","No, solo afecta a los pasajeros","Sí, hace más lentos los reflejos y afecta el cálculo de tiempo y distancia","Solo si se mezcla con café"],"h1":"Legal no significa seguro para manejar.","h2":"La marihuana puede hacer más lentos sus reflejos y afectar su cálculo de tiempo y distancia, así que manejar después de usarla es inseguro aunque sea legal.","p":"Correcto. Puede hacer inseguro el manejo."},"zh":{"q":"即使在合法的地方，大麻也会让你开车不安全吗？","o":["不会，合法就是安全","不会，它只影响乘客","会，它会让反应变慢，并影响对时间和距离的判断","只有和咖啡一起用时才会"],"h1":"合法不等于开车安全。","h2":"大麻会让你的反应变慢，并影响你对时间和距离的判断，所以即使在合法的地方，使用后开车也是不安全的。","p":"对。它会让开车变得不安全。"},"vi":{"q":"Cần sa có thể làm bạn lái xe không an toàn không, kể cả ở nơi hợp pháp?","o":["Không, nếu hợp pháp thì an toàn","Không, nó chỉ ảnh hưởng đến hành khách","Có, nó làm phản ứng chậm lại và ảnh hưởng đến khả năng ước lượng thời gian và khoảng cách","Chỉ khi dùng chung với cà phê"],"h1":"Hợp pháp không có nghĩa là an toàn khi lái xe.","h2":"Cần sa có thể làm phản ứng của bạn chậm lại và ảnh hưởng đến khả năng ước lượng thời gian và khoảng cách, nên lái xe sau khi dùng là không an toàn, kể cả ở nơi hợp pháp.","p":"Đúng. Nó có thể làm việc lái xe không an toàn."},"tl":{"q":"Puwede ka bang gawing hindi ligtas magmaneho ng marijuana, kahit saan ito legal?","o":["Hindi, kung legal ito ay ligtas","Hindi, ang mga pasahero lang ang naaapektuhan","Oo, pinababagal nito ang reaksiyon at naaapektuhan ang paghuhusga sa oras at layo","Kung may halong kape lang"],"h1":"Ang legal ay hindi nangangahulugang ligtas sa pagmamaneho.","h2":"Puwedeng pabagalin ng marijuana ang reaksiyon mo at maapektuhan ang paghuhusga mo sa oras at layo, kaya hindi ligtas magmaneho pagkatapos gumamit nito kahit saan ito legal.","p":"Tama. Puwede nitong gawing hindi ligtas ang pagmamaneho."},"ar":{"q":"هل يمكن أن تجعل الماريجوانا قيادتك غير آمنة، حتى حيث تكون قانونية؟","o":["لا، إذا كانت قانونية فهي آمنة","لا، إنها تؤثر على الركاب فقط","نعم، فهي تُبطئ الاستجابة وتؤثر على تقدير الوقت والمسافة","فقط إذا خُلطت مع القهوة"],"h1":"كونها قانونية لا يعني أنها آمنة للقيادة.","h2":"الماريجوانا قد تُبطئ استجابتك وتؤثر على تقديرك للوقت والمسافة، لذلك القيادة بعد تعاطيها غير آمنة حتى حيث تكون قانونية.","p":"صحيح. قد تجعل القيادة غير آمنة."},"ht":{"q":"Èske marijuana ka fè ou pa an sekirite pou kondui, menm kote li legal?","o":["Non, si li legal li an sekirite","Non, li afekte pasaje yo sèlman","Wi, li fè reyaksyon an pi lan epi li afekte jan ou jije tan ak distans","Sèlman si yo melanje l ak kafe"],"h1":"Legal pa vle di an sekirite pou kondui.","h2":"Marijuana ka fè reyaksyon ou pi lan epi afekte jan ou jije tan ak distans, kidonk kondui apre ou fin itilize l pa an sekirite, menm kote li legal.","p":"Se sa. Li ka fè kondui vin danjere."}},{"id":"safe-driving-075","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"What happens when alcohol is mixed with other drugs, including some medicines?","o":["They cancel each other out","The alcohol wears off faster","Nothing changes","The effects can be much stronger, making driving even more dangerous"],"h1":"Two impairing substances add up.","h2":"Mixing alcohol with drugs or some medicines can greatly increase the effects of both, making driving far more dangerous.","p":"Right. The effects can be much stronger."},"es":{"q":"¿Qué pasa cuando se mezcla el alcohol con otras drogas, incluidos algunos medicamentos?","o":["Se cancelan entre sí","El alcohol se pasa más rápido","No cambia nada","Los efectos pueden ser mucho más fuertes, lo que hace manejar aún más peligroso"],"h1":"Dos sustancias que afectan se suman.","h2":"Mezclar alcohol con drogas o algunos medicamentos puede aumentar mucho los efectos de ambos, lo que hace manejar mucho más peligroso.","p":"Correcto. Los efectos pueden ser mucho más fuertes."},"zh":{"q":"酒精和其他药物（包括一些药品）混在一起时，会发生什么？","o":["它们会互相抵消","酒精会更快消退","什么都不会改变","作用会强得多，让开车更加危险"],"h1":"两种影响能力的东西会叠加在一起。","h2":"把酒精和药物或某些药品混在一起，会大大加强两者的作用，让开车危险得多。","p":"对。作用会强得多。"},"vi":{"q":"Điều gì xảy ra khi uống rượu bia cùng với các loại thuốc hay chất kích thích khác, kể cả một số thuốc chữa bệnh?","o":["Chúng triệt tiêu lẫn nhau","Rượu bia hết tác dụng nhanh hơn","Không có gì thay đổi","Tác dụng có thể mạnh hơn nhiều, làm việc lái xe còn nguy hiểm hơn"],"h1":"Hai chất làm suy giảm khả năng sẽ cộng dồn với nhau.","h2":"Uống rượu bia cùng với ma túy hoặc một số thuốc chữa bệnh có thể làm tăng mạnh tác dụng của cả hai, khiến việc lái xe nguy hiểm hơn nhiều.","p":"Đúng. Tác dụng có thể mạnh hơn nhiều."},"tl":{"q":"Ano ang nangyayari kapag pinaghalo ang alak at ibang droga, kasama ang ilang gamot?","o":["Nagkakansela sila sa isa't isa","Mas mabilis mawala ang epekto ng alak","Walang nagbabago","Puwedeng mas lumakas nang husto ang epekto, kaya mas mapanganib pa ang pagmamaneho"],"h1":"Nadaragdagan ang epekto ng dalawang bagay na nakapagpapahina sa iyo.","h2":"Ang paghahalo ng alak at droga o ilang gamot ay puwedeng magpalakas nang husto sa epekto ng dalawa, kaya mas mapanganib ang pagmamaneho.","p":"Tama. Puwedeng mas lumakas nang husto ang epekto."},"ar":{"q":"ماذا يحدث عندما يُخلط الكحول مع مخدرات أخرى، ومنها بعض الأدوية؟","o":["يُلغي كلٌّ منهما تأثير الآخر","يزول تأثير الكحول أسرع","لا يتغير شيء","قد تصبح التأثيرات أقوى بكثير، فتصبح القيادة أخطر"],"h1":"مادتان تُضعفان قدرتك يجتمع تأثيرهما.","h2":"خلط الكحول مع المخدرات أو بعض الأدوية قد يزيد تأثير كلٍّ منهما كثيرًا، فتصبح القيادة أخطر بكثير.","p":"صحيح. قد تصبح التأثيرات أقوى بكثير."},"ht":{"q":"Kisa ki rive lè yo melanje alkòl ak lòt dwòg, tankou kèk medikaman?","o":["Youn anile lòt","Alkòl la pase pi vit","Anyen pa chanje","Efè yo ka vin pi fò anpil, sa fè kondui vin pi danjere toujou"],"h1":"De bagay ki febli w ajoute youn sou lòt.","h2":"Melanje alkòl ak dwòg oswa kèk medikaman ka ogmante efè toude anpil, sa ki fè kondui vin pi danjere anpil.","p":"Se sa. Efè yo ka vin pi fò anpil."}},{"id":"safe-driving-076","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your doctor gives you a new prescription medicine. What should you do before driving?","o":["Ask your doctor or pharmacist whether it is safe to drive while taking it","Drive; prescription medicines are always safe","Take extra so it works faster","Drive only at night"],"h1":"Some medicines cause drowsiness or slow reactions.","h2":"Before driving on a new prescription, ask your doctor or pharmacist whether it can affect your driving, and read the label warnings.","p":"Right. Ask if it is safe to drive."},"es":{"q":"Su médico le receta un medicamento nuevo. ¿Qué debe hacer antes de manejar?","o":["Preguntar al médico o farmacéutico si es seguro manejar mientras lo toma","Manejar; los medicamentos recetados siempre son seguros","Tomar más para que funcione más rápido","Manejar solo de noche"],"h1":"Algunos medicamentos dan sueño o hacen más lentos los reflejos.","h2":"Antes de manejar con un medicamento nuevo, pregunte a su médico o farmacéutico si puede afectar su manejo y lea las advertencias de la etiqueta.","p":"Correcto. Pregunte si es seguro manejar."},"zh":{"q":"医生给你开了一种新的处方药。开车前你应该怎么做？","o":["问医生或药剂师，服用这种药时开车是否安全","开车；处方药总是安全的","多吃一点，让它见效更快","只在晚上开车"],"h1":"有些药会让人犯困或反应变慢。","h2":"在服用新的处方药开车之前，要问医生或药剂师这种药会不会影响你开车，并阅读标签上的警告。","p":"对。问清楚开车是否安全。"},"vi":{"q":"Bác sĩ kê cho bạn một loại thuốc theo toa mới. Bạn nên làm gì trước khi lái xe?","o":["Hỏi bác sĩ hoặc dược sĩ xem có an toàn để lái xe khi đang dùng thuốc này không","Cứ lái; thuốc theo toa luôn an toàn","Uống thêm để thuốc có tác dụng nhanh hơn","Chỉ lái xe vào ban đêm"],"h1":"Một số thuốc gây buồn ngủ hoặc làm phản ứng chậm lại.","h2":"Trước khi lái xe khi đang dùng thuốc theo toa mới, hãy hỏi bác sĩ hoặc dược sĩ xem thuốc có thể ảnh hưởng đến việc lái xe không, và đọc các cảnh báo trên nhãn.","p":"Đúng. Hãy hỏi xem có an toàn để lái xe không."},"tl":{"q":"Binigyan ka ng doktor mo ng bagong resetang gamot. Ano ang dapat mong gawin bago magmaneho?","o":["Tanungin ang doktor o parmasyutiko mo kung ligtas magmaneho habang iniinom ito","Magmaneho; laging ligtas ang resetang gamot","Uminom ng sobra para mas mabilis itong gumana","Magmaneho lang sa gabi"],"h1":"May mga gamot na nakapagpapaantok o nakapagpapabagal ng reaksiyon.","h2":"Bago magmaneho habang umiinom ng bagong resetang gamot, tanungin ang doktor o parmasyutiko mo kung puwede itong makaapekto sa pagmamaneho mo, at basahin ang mga babala sa label.","p":"Tama. Itanong kung ligtas magmaneho."},"ar":{"q":"أعطاك طبيبك دواءً جديدًا بوصفة طبية. ماذا يجب أن تفعل قبل القيادة؟","o":["اسأل طبيبك أو الصيدلي هل القيادة آمنة أثناء تناوله","قُد؛ الأدوية الموصوفة آمنة دائمًا","تناول كمية أكبر حتى يعمل أسرع","قُد في الليل فقط"],"h1":"بعض الأدوية تسبب النعاس أو تُبطئ الاستجابة.","h2":"قبل القيادة وأنت تتناول دواءً جديدًا بوصفة طبية، اسأل طبيبك أو الصيدلي هل يمكن أن يؤثر على قيادتك، واقرأ التحذيرات على الملصق.","p":"صحيح. اسأل هل القيادة آمنة."},"ht":{"q":"Doktè w ba ou yon nouvo medikaman sou preskripsyon. Kisa ou ta dwe fè anvan ou kondui?","o":["Mande doktè w oswa famasyen an si li an sekirite pou kondui pandan w ap pran l","Kondui; medikaman sou preskripsyon toujou an sekirite","Pran plis pou l aji pi vit","Kondui sèlman lannwit"],"h1":"Gen kèk medikaman ki bay dòmi oswa ki fè reyaksyon pi lan.","h2":"Anvan ou kondui ak yon nouvo medikaman sou preskripsyon, mande doktè w oswa famasyen an si li ka afekte jan ou kondui, epi li avètisman ki sou etikèt la.","p":"Se sa. Mande si li an sekirite pou kondui."}},{"id":"safe-driving-077","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You are going to a party where you will drink alcohol. What is the safest plan?","o":["Drive slowly on the way home","Arrange a sober driver, a taxi or a ride service before you go","Drink coffee before driving","Wait 10 minutes after your last drink"],"h1":"Plan before you start drinking.","h2":"If you will drink, plan a safe ride before you go, such as a sober designated driver, a taxi or a ride service.","p":"Right. Plan a sober ride ahead of time."},"es":{"q":"Va a una fiesta donde tomará alcohol. ¿Cuál es el plan más seguro?","o":["Manejar despacio de regreso","Arreglar antes un conductor sobrio, un taxi o un servicio de transporte","Tomar café antes de manejar","Esperar 10 minutos después del último trago"],"h1":"Planee antes de empezar a tomar.","h2":"Si va a tomar, planee un regreso seguro antes de salir, como un conductor designado sobrio, un taxi o un servicio de transporte.","p":"Correcto. Planee con tiempo un regreso sobrio."},"zh":{"q":"你要去一个会喝酒的聚会。最安全的计划是什么？","o":["回家路上开慢一点","出发前安排一位没喝酒的司机、出租车或叫车服务","开车前喝咖啡","喝完最后一杯后等 10 分钟"],"h1":"在开始喝酒之前就做好计划。","h2":"如果你会喝酒，出发前就要安排好安全的交通方式，比如一位不喝酒的指定司机、出租车或叫车服务。","p":"对。提前安排一个没喝酒的人送你。"},"vi":{"q":"Bạn sắp đi dự tiệc và sẽ uống rượu bia. Kế hoạch an toàn nhất là gì?","o":["Lái chậm trên đường về nhà","Sắp xếp một người lái xe không uống rượu bia, taxi hoặc dịch vụ gọi xe trước khi đi","Uống cà phê trước khi lái xe","Chờ 10 phút sau ly cuối cùng"],"h1":"Hãy lên kế hoạch trước khi bắt đầu uống.","h2":"Nếu bạn sẽ uống rượu bia, hãy sắp xếp cách về an toàn trước khi đi, như một người lái xe được chỉ định không uống rượu bia, taxi hoặc dịch vụ gọi xe.","p":"Đúng. Sắp xếp trước một người không uống để chở bạn."},"tl":{"q":"Pupunta ka sa isang party kung saan iinom ka ng alak. Ano ang pinakaligtas na plano?","o":["Magmaneho nang mabagal pauwi","Mag-ayos ng drayber na hindi iinom, taxi o ride service bago ka umalis","Uminom ng kape bago magmaneho","Maghintay ng 10 minuto pagkatapos ng huling inumin mo"],"h1":"Magplano bago ka magsimulang uminom.","h2":"Kung iinom ka, magplano ng ligtas na sasakyan bago ka umalis, gaya ng itinalagang drayber na hindi iinom, taxi o ride service.","p":"Tama. Magplano nang maaga ng drayber na hindi uminom."},"ar":{"q":"أنت ذاهب إلى حفلة ستشرب فيها الكحول. ما الخطة الأكثر أمانًا؟","o":["قُد ببطء في طريق العودة إلى البيت","رتّب سائقًا لم يشرب، أو سيارة أجرة، أو خدمة توصيل قبل أن تذهب","اشرب القهوة قبل القيادة","انتظر 10 دقائق بعد آخر مشروب"],"h1":"خطّط قبل أن تبدأ الشرب.","h2":"إذا كنت ستشرب، رتّب وسيلة عودة آمنة قبل أن تذهب، مثل سائق معيّن لا يشرب، أو سيارة أجرة، أو خدمة توصيل.","p":"صحيح. رتّب مسبقًا سائقًا لم يشرب."},"ht":{"q":"W ap ale nan yon fèt kote w ap bwè alkòl. Ki plan ki pi an sekirite?","o":["Kondui dousman lè w ap retounen lakay","Prepare yon chofè ki pa bwè, yon taksi oswa yon sèvis transpò anvan ou ale","Bwè kafe anvan ou kondui","Tann 10 minit apre dènye bwason ou"],"h1":"Fè plan anvan ou kòmanse bwè.","h2":"Si w ap bwè, prepare yon fason ki an sekirite pou w retounen anvan ou ale, tankou yon chofè ki deziyen ki pa bwè, yon taksi oswa yon sèvis transpò.","p":"Se sa. Prepare davans yon chofè ki pa bwè."}},{"id":"safe-driving-078","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are very angry or upset after an argument. What should you do before driving?","o":["Drive fast to release the stress","Drive, but play loud music","Wait until you calm down","Drive close behind others"],"h1":"Strong emotions affect your judgment.","h2":"Strong emotions like anger can make you take risks and pay less attention, so wait until you are calm before you drive.","p":"Right. Calm down first."},"es":{"q":"Usted está muy enojado o alterado después de una discusión. ¿Qué debe hacer antes de manejar?","o":["Manejar rápido para soltar el estrés","Manejar, pero con música alta","Esperar hasta calmarse","Manejar muy cerca de los demás"],"h1":"Las emociones fuertes afectan su juicio.","h2":"Las emociones fuertes como el enojo pueden hacer que se arriesgue y preste menos atención, así que espere hasta estar tranquilo antes de manejar.","p":"Correcto. Cálmese primero."},"zh":{"q":"吵架以后你非常生气或难过。开车前你应该怎么做？","o":["开快车来发泄压力","开车，但把音乐开得很大声","等到你冷静下来","紧跟在别人后面开"],"h1":"强烈的情绪会影响你的判断。","h2":"像愤怒这样的强烈情绪会让你冒险、注意力下降，所以要等到你冷静下来再开车。","p":"对。先冷静下来。"},"vi":{"q":"Bạn đang rất tức giận hoặc buồn bực sau một cuộc cãi vã. Bạn nên làm gì trước khi lái xe?","o":["Lái nhanh để xả căng thẳng","Lái xe, nhưng mở nhạc to","Chờ đến khi bạn bình tĩnh lại","Chạy sát phía sau xe khác"],"h1":"Cảm xúc mạnh ảnh hưởng đến khả năng phán đoán của bạn.","h2":"Cảm xúc mạnh như tức giận có thể khiến bạn liều lĩnh và kém chú ý, nên hãy chờ đến khi bình tĩnh rồi mới lái xe.","p":"Đúng. Hãy bình tĩnh lại trước."},"tl":{"q":"Galit na galit ka o sobrang naiinis pagkatapos ng isang away. Ano ang dapat mong gawin bago magmaneho?","o":["Magmaneho nang mabilis para mailabas ang stress","Magmaneho, pero magpatugtog ng malakas na musika","Maghintay hanggang kumalma ka","Magmaneho nang malapit sa likod ng iba"],"h1":"Naaapektuhan ng matinding emosyon ang paghuhusga mo.","h2":"Ang matinding emosyon gaya ng galit ay puwedeng magtulak sa iyo na makipagsapalaran at hindi gaanong mag-ingat, kaya maghintay hanggang kalmado ka na bago magmaneho.","p":"Tama. Kumalma muna."},"ar":{"q":"أنت غاضب جدًا أو منزعج بعد شجار. ماذا يجب أن تفعل قبل القيادة؟","o":["قُد بسرعة لتُخرج التوتر","قُد، لكن شغّل موسيقى عالية","انتظر حتى تهدأ","قُد قريبًا جدًا خلف الآخرين"],"h1":"المشاعر القوية تؤثر على حكمك على الأمور.","h2":"المشاعر القوية مثل الغضب قد تجعلك تخاطر وتقلّ انتباهك، لذلك انتظر حتى تهدأ قبل أن تقود.","p":"صحيح. اهدأ أولًا."},"ht":{"q":"Ou fache anpil oswa ou boulvèse apre yon diskisyon. Kisa ou ta dwe fè anvan ou kondui?","o":["Kondui vit pou lage estrès la","Kondui, men mete mizik fò","Tann jiskaske ou kalme w","Kondui kole dèyè lòt moun"],"h1":"Emosyon fò afekte jijman ou.","h2":"Emosyon fò tankou kòlè ka fè ou pran risk epi fè mwens atansyon, kidonk tann jiskaske ou kalm anvan ou kondui.","p":"Se sa. Kalme w anvan."}},{"id":"safe-driving-079","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your car has anti-lock brakes (ABS). You must stop fast in an emergency. What should you do?","o":["Pump the brake pedal quickly","Press the brake lightly and let go","Pull the parking brake","Press the brake pedal hard and hold it down"],"h1":"ABS does the pumping for you.","h2":"With anti-lock brakes, press the pedal hard and keep holding it; you may feel the pedal pulse, which is normal, and you can still steer.","p":"Right. Press hard and hold."},"es":{"q":"Su carro tiene frenos antibloqueo (ABS). Debe pararse rápido en una emergencia. ¿Qué debe hacer?","o":["Bombear el freno rápidamente","Pisar el freno suave y soltarlo","Jalar el freno de mano","Pisar el freno con fuerza y mantenerlo pisado"],"h1":"El ABS hace el bombeo por usted.","h2":"Con frenos antibloqueo, pise el pedal con fuerza y manténgalo pisado; puede sentir que el pedal vibra, lo cual es normal, y todavía puede girar el volante.","p":"Correcto. Pise fuerte y mantenga."},"zh":{"q":"你的车有防抱死刹车系统（ABS）。遇到紧急情况，你必须快速停车。你应该怎么做？","o":["快速地一下一下踩刹车","轻轻踩刹车，然后松开","拉手刹","用力踩住刹车踏板，一直不松开"],"h1":"ABS 会替你做一下一下踩刹车的动作。","h2":"如果你的车有防抱死刹车，就要用力踩住刹车踏板，一直不松开；你可能会感到踏板在跳动，这是正常的，你仍然可以转方向盘。","p":"对。用力踩住，不要松开。"},"vi":{"q":"Xe bạn có phanh chống bó cứng (ABS). Bạn phải dừng xe gấp trong trường hợp khẩn cấp. Bạn nên làm gì?","o":["Đạp phanh nhấp nhả thật nhanh","Đạp phanh nhẹ rồi buông ra","Kéo phanh tay","Đạp mạnh bàn đạp phanh và giữ chặt"],"h1":"ABS tự nhấp nhả phanh thay cho bạn.","h2":"Với phanh chống bó cứng, bạn hãy đạp mạnh bàn đạp phanh và giữ chặt; bạn có thể thấy bàn đạp rung giật, điều đó là bình thường, và bạn vẫn có thể lái xe tránh.","p":"Đúng. Đạp mạnh và giữ chặt."},"tl":{"q":"May anti-lock brakes (ABS) ang kotse mo. Kailangan mong huminto nang mabilis dahil sa emergency. Ano ang dapat mong gawin?","o":["Mabilis na pindut-pindutin ang preno","Pindutin nang mahina ang preno at bitawan","Hilahin ang parking brake","Diinan nang malakas ang preno at panatilihing nakadiin"],"h1":"Ang ABS na ang nagpipindut-pindot para sa iyo.","h2":"Kapag may anti-lock brakes, diinan nang malakas ang pedal at panatilihin itong nakadiin; maaaring maramdaman mong pumipintig ang pedal, normal iyon, at kaya mo pa ring imaneho ang kotse.","p":"Tama. Diinan nang malakas at huwag bitawan."},"ar":{"q":"سيارتك فيها فرامل مانعة للانغلاق (ABS). يجب أن تتوقف بسرعة في حالة طارئة. ماذا يجب أن تفعل؟","o":["اضغط على دوّاسة الفرامل وارفع قدمك بسرعة مرات كثيرة","اضغط على الفرامل بخفة ثم اتركها","اسحب فرامل اليد","اضغط على دوّاسة الفرامل بقوة واستمر في الضغط"],"h1":"نظام ABS يقوم بالضغط المتكرر بدلًا منك.","h2":"مع الفرامل المانعة للانغلاق، اضغط على الدوّاسة بقوة واستمر في الضغط؛ قد تشعر أن الدوّاسة تهتز، وهذا طبيعي، وتستطيع أن توجّه السيارة بالمقود.","p":"صحيح. اضغط بقوة واستمر في الضغط."},"ht":{"q":"Machin ou gen fren anti-blokaj (ABS). Ou dwe kanpe vit akoz yon ijans. Kisa ou ta dwe fè?","o":["Peze fren an plizyè fwa vit vit","Peze fren an dousman epi lage l","Rale fren a men an","Peze pedal fren an fò epi kenbe l peze"],"h1":"ABS la fè travay peze-lage a pou ou.","h2":"Avèk fren anti-blokaj, peze pedal la fò epi kenbe l peze; ou ka santi pedal la ap vibre, sa nòmal, epi ou ka toujou dirije machin nan.","p":"Se sa. Peze fò epi kenbe l."}},{"id":"safe-driving-080","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Your brakes fail, and pumping the pedal does not help. What should you try next?","o":["Use the parking brake slowly and shift to a lower gear","Turn off the engine and pull the key","Shift into reverse","Open the door and drag your foot"],"h1":"Use another way to slow the car gently.","h2":"If pumping does not bring the brakes back, apply the parking brake gradually and shift to a lower gear to slow down, then steer to a safe place.","p":"Right. Parking brake slowly and a lower gear."},"es":{"q":"Los frenos fallan y bombear el pedal no ayuda. ¿Qué debe intentar después?","o":["Usar el freno de mano poco a poco y pasar a un cambio más bajo","Apagar el motor y sacar la llave","Poner reversa","Abrir la puerta y arrastrar el pie"],"h1":"Use otra forma de frenar el carro con suavidad.","h2":"Si bombear no recupera los frenos, use el freno de mano poco a poco y pase a un cambio más bajo para reducir la velocidad, y luego diríjase a un lugar seguro.","p":"Correcto. Freno de mano poco a poco y un cambio más bajo."},"zh":{"q":"你的刹车失灵了，一下一下踩刹车也没有用。接下来你应该试什么？","o":["慢慢拉手刹，并换到低速挡","关掉发动机，拔出钥匙","挂倒挡","打开车门，用脚拖地"],"h1":"用别的方法让车慢慢减速。","h2":"如果一下一下踩刹车也不能让刹车恢复，就慢慢拉手刹，并换到低速挡来减速，然后把车开到安全的地方。","p":"对。慢慢拉手刹，换低速挡。"},"vi":{"q":"Phanh xe bạn bị hỏng, và đạp nhấp nhả cũng không có tác dụng. Bạn nên thử làm gì tiếp theo?","o":["Kéo phanh tay từ từ và chuyển sang số thấp hơn","Tắt máy và rút chìa khóa","Chuyển sang số lùi","Mở cửa và lết chân xuống đường"],"h1":"Hãy dùng cách khác để xe chạy chậm lại nhẹ nhàng.","h2":"Nếu đạp nhấp nhả mà phanh vẫn không hoạt động lại, hãy kéo phanh tay từ từ và chuyển sang số thấp hơn để giảm tốc, rồi lái xe vào chỗ an toàn.","p":"Đúng. Kéo phanh tay từ từ và về số thấp."},"tl":{"q":"Nasira ang preno mo, at hindi nakakatulong ang pagpindut-pindot sa pedal. Ano ang susunod mong dapat subukan?","o":["Dahan-dahang gamitin ang parking brake at ilipat sa mas mababang gear","Patayin ang makina at hugutin ang susi","Ilipat sa reverse","Buksan ang pinto at ikaladkad ang paa mo"],"h1":"Gumamit ng ibang paraan para dahan-dahang bumagal ang kotse.","h2":"Kung hindi bumalik ang preno sa pagpindut-pindot, dahan-dahang gamitin ang parking brake at ilipat sa mas mababang gear para bumagal, saka imaneho papunta sa ligtas na lugar.","p":"Tama. Dahan-dahang parking brake at mas mababang gear."},"ar":{"q":"الفرامل تعطّلت، والضغط المتكرر على الدوّاسة لا يساعد. ماذا يجب أن تجرّب بعد ذلك؟","o":["استعمل فرامل اليد ببطء وانقل إلى سرعة (غيار) أقل","أطفئ المحرك واسحب المفتاح","انقل إلى الرجوع للخلف","افتح الباب واسحب قدمك على الأرض"],"h1":"استعمل طريقة أخرى لتخفيف سرعة السيارة بهدوء.","h2":"إذا لم يُرجع الضغط المتكرر الفرامل، استعمل فرامل اليد بالتدريج وانقل إلى سرعة (غيار) أقل لتخفّف السرعة، ثم وجّه السيارة إلى مكان آمن.","p":"صحيح. فرامل اليد ببطء وسرعة (غيار) أقل."},"ht":{"q":"Fren ou yo pa mache, epi peze pedal la plizyè fwa pa ede. Kisa ou ta dwe eseye apre sa?","o":["Sèvi ak fren a men an dousman epi pase nan yon vitès ki pi ba","Etenn motè a epi retire kle a","Pase nan vitès bak","Louvri pòt la epi trennen pye ou atè"],"h1":"Sèvi ak yon lòt mwayen pou ralanti machin nan dousman.","h2":"Si peze pedal la plizyè fwa pa fè fren yo mache ankò, sèvi ak fren a men an tou dousman epi pase nan yon vitès ki pi ba pou ralanti, apre sa dirije machin nan nan yon kote ki an sekirite.","p":"Se sa. Fren a men an dousman ak yon vitès ki pi ba."}},{"id":"safe-driving-081","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"The temperature light comes on and your engine is overheating. What should you do?","o":["Keep driving fast to cool the engine","Pull off safely, turn off the engine, and do not open the radiator cap while it is hot","Open the radiator cap right away","Pour cold water on the hot engine"],"h1":"Hot coolant is under pressure.","h2":"If your engine overheats, pull off safely and turn it off; never open the radiator cap while hot, because boiling coolant can burn you.","p":"Right. Pull off and leave the cap closed."},"es":{"q":"Se enciende la luz de temperatura y el motor se está recalentando. ¿Qué debe hacer?","o":["Seguir rápido para enfriar el motor","Orillarse con seguridad, apagar el motor y no abrir la tapa del radiador mientras esté caliente","Abrir enseguida la tapa del radiador","Echar agua fría sobre el motor caliente"],"h1":"El refrigerante caliente está bajo presión.","h2":"Si el motor se recalienta, oríllese con seguridad y apáguelo; nunca abra la tapa del radiador caliente, porque el refrigerante hirviendo puede quemarlo.","p":"Correcto. Oríllese y no abra la tapa."},"zh":{"q":"温度警示灯亮了，你的发动机过热了。你应该怎么做？","o":["继续开快车，让发动机冷却","安全地把车开到路边，关掉发动机，发动机还热的时候不要打开水箱盖","马上打开水箱盖","把冷水倒在热的发动机上"],"h1":"热的冷却液有很大的压力。","h2":"如果发动机过热，要安全地把车开到路边并熄火；发动机还热的时候绝对不要打开水箱盖，因为滚烫的冷却液会烫伤你。","p":"对。开到路边，不要打开水箱盖。"},"vi":{"q":"Đèn báo nhiệt độ sáng lên và máy xe bạn bị quá nóng. Bạn nên làm gì?","o":["Tiếp tục chạy nhanh để làm mát máy","Tấp vào lề an toàn, tắt máy, và không mở nắp két nước khi máy còn nóng","Mở nắp két nước ngay","Đổ nước lạnh lên máy đang nóng"],"h1":"Nước làm mát đang nóng có áp suất cao.","h2":"Nếu máy xe quá nóng, hãy tấp vào lề an toàn và tắt máy; không bao giờ mở nắp két nước khi máy còn nóng, vì nước làm mát đang sôi có thể làm bạn bị bỏng.","p":"Đúng. Tấp vào lề và để nắp đóng."},"tl":{"q":"Umilaw ang temperature light at nag-o-overheat ang makina mo. Ano ang dapat mong gawin?","o":["Patuloy na magmaneho nang mabilis para lumamig ang makina","Tumabi nang ligtas, patayin ang makina, at huwag buksan ang takip ng radiator habang mainit pa ito","Buksan agad ang takip ng radiator","Buhusan ng malamig na tubig ang mainit na makina"],"h1":"May malakas na presyon ang mainit na coolant.","h2":"Kapag nag-overheat ang makina mo, tumabi nang ligtas at patayin ito; huwag kailanman buksan ang takip ng radiator habang mainit, dahil maaari kang mapaso ng kumukulong coolant.","p":"Tama. Tumabi at huwag buksan ang takip."},"ar":{"q":"ضوء الحرارة اشتعل والمحرك ساخن جدًا. ماذا يجب أن تفعل؟","o":["استمر في القيادة بسرعة لتبريد المحرك","توقّف جانبًا بأمان، وأطفئ المحرك، ولا تفتح غطاء الرادياتير وهو ساخن","افتح غطاء الرادياتير فورًا","اسكب ماء باردًا على المحرك الساخن"],"h1":"سائل التبريد الساخن يكون تحت ضغط قوي.","h2":"إذا سخن المحرك كثيرًا، توقّف جانبًا بأمان وأطفئه؛ يجب ألّا تفتح غطاء الرادياتير أبدًا وهو ساخن، لأن سائل التبريد المغلي قد يحرقك.","p":"صحيح. توقّف جانبًا واترك الغطاء مغلقًا."},"ht":{"q":"Limyè tanperati a limen epi motè ou twò cho. Kisa ou ta dwe fè?","o":["Kontinye kondui vit pou motè a refwadi","Rale sou kote a an sekirite, etenn motè a, epi pa louvri bouchon radyatè a pandan l cho","Louvri bouchon radyatè a touswit","Vide dlo frèt sou motè ki cho a"],"h1":"Likid refwadisman ki cho a gen anpil presyon.","h2":"Si motè ou twò cho, rale sou kote a an sekirite epi etenn li; pa janm louvri bouchon radyatè a pandan l cho, paske likid refwadisman k ap bouyi a ka boule w.","p":"Se sa. Rale sou kote a epi kite bouchon an fèmen."}},{"id":"safe-driving-082","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your headlights suddenly go out at night. What should you do?","o":["Keep driving in the dark","Stop in your lane","Try the headlight switch and hazard lights, slow down, and pull off safely","Follow close behind another car"],"h1":"Other drivers must be able to see you.","h2":"If your headlights fail, try the switches and turn on hazard lights, then slow down and pull off the road as safely as you can.","p":"Right. Try the switches and pull off safely."},"es":{"q":"Los faros se apagan de repente de noche. ¿Qué debe hacer?","o":["Seguir manejando a oscuras","Pararse en su carril","Probar el interruptor de luces y las luces de emergencia, bajar la velocidad y orillarse con seguridad","Seguir de cerca a otro carro"],"h1":"Los demás deben poder verlo.","h2":"Si fallan los faros, pruebe los interruptores y encienda las luces de emergencia, luego baje la velocidad y salga de la vía con la mayor seguridad posible.","p":"Correcto. Pruebe los interruptores y oríllese."},"zh":{"q":"晚上开车时，你的前大灯突然灭了。你应该怎么做？","o":["在黑暗中继续开","在你的车道上停车","试一试大灯开关和危险警示灯，减速，然后安全地开到路边","紧紧跟在别的车后面"],"h1":"别的司机必须能看见你。","h2":"如果前大灯坏了，试一试开关，打开危险警示灯，然后减速，尽量安全地把车开离道路。","p":"对。试一试开关，然后安全地开到路边。"},"vi":{"q":"Đèn pha xe bạn đột nhiên tắt vào ban đêm. Bạn nên làm gì?","o":["Tiếp tục lái trong bóng tối","Dừng lại trong làn xe của bạn","Thử bật lại công tắc đèn pha và đèn khẩn cấp, chạy chậm lại, và tấp vào lề an toàn","Bám sát phía sau một xe khác"],"h1":"Các tài xế khác phải nhìn thấy được bạn.","h2":"Nếu đèn pha bị hỏng, hãy thử các công tắc và bật đèn khẩn cấp, rồi chạy chậm lại và tấp ra khỏi đường an toàn nhất có thể.","p":"Đúng. Thử các công tắc và tấp vào lề an toàn."},"tl":{"q":"Biglang namatay ang headlights mo sa gabi. Ano ang dapat mong gawin?","o":["Patuloy na magmaneho sa dilim","Huminto sa lane mo","Subukan ang switch ng headlights at ang hazard lights, bumagal, at tumabi nang ligtas","Sumunod nang malapit sa likod ng ibang kotse"],"h1":"Kailangang makita ka ng ibang mga driver.","h2":"Kapag nasira ang headlights mo, subukan ang mga switch at i-on ang hazard lights, saka bumagal at tumabi palabas ng daan nang ligtas hangga't kaya mo.","p":"Tama. Subukan ang mga switch at tumabi nang ligtas."},"ar":{"q":"أضواء سيارتك الأمامية انطفأت فجأة في الليل. ماذا يجب أن تفعل؟","o":["استمر في القيادة في الظلام","توقّف في مسارك","جرّب مفتاح الأضواء الأمامية وأضواء التحذير، وخفّف السرعة، وتوقّف جانبًا بأمان","سِر قريبًا جدًا خلف سيارة أخرى"],"h1":"يجب أن يستطيع السائقون الآخرون أن يروك.","h2":"إذا تعطّلت الأضواء الأمامية، جرّب المفاتيح وشغّل أضواء التحذير، ثم خفّف السرعة واخرج من الطريق بأكثر طريقة آمنة تستطيعها.","p":"صحيح. جرّب المفاتيح وتوقّف جانبًا بأمان."},"ht":{"q":"Limyè devan machin ou yo etenn sanzatann nan mitan lannwit. Kisa ou ta dwe fè?","o":["Kontinye kondui nan fènwa a","Kanpe nan liy ou","Eseye bouton limyè devan yo ak limyè ijans yo, ralanti, epi rale sou kote a an sekirite","Swiv yon lòt machin byen pre dèyè l"],"h1":"Lòt chofè yo dwe kapab wè w.","h2":"Si limyè devan ou yo pa mache, eseye bouton yo epi limen limyè ijans yo, apre sa ralanti epi soti sou wout la yon fason ki an sekirite otan ou kapab.","p":"Se sa. Eseye bouton yo epi rale sou kote a an sekirite."}},{"id":"safe-driving-083","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"While you are driving, the hood flies up and blocks your view. What should you do?","o":["Brake hard in your lane","Get out to close it while moving","Speed up so the wind closes it","Look through the gap under the hood or out the side window, slow down, and pull off"],"h1":"Keep control and find another way to see.","h2":"If the hood flies up, look through the gap below it or out the side window, slow down, and pull off the road safely.","p":"Right. Find a way to see, then pull off."},"es":{"q":"Mientras maneja, el capó se levanta y le tapa la vista. ¿Qué debe hacer?","o":["Frenar fuerte en su carril","Bajarse a cerrarlo con el carro en marcha","Acelerar para que el viento lo cierre","Mirar por el espacio debajo del capó o por la ventana lateral, bajar la velocidad y orillarse"],"h1":"Mantenga el control y busque otra forma de ver.","h2":"Si el capó se levanta, mire por el espacio de abajo o por la ventana lateral, baje la velocidad y salga de la vía con seguridad.","p":"Correcto. Busque cómo ver y oríllese."},"zh":{"q":"你开车时，引擎盖突然弹起来，挡住了你的视线。你应该怎么做？","o":["在你的车道上用力刹车","边开车边下车去关上它","加速，让风把它吹下来","从引擎盖下面的缝隙或侧窗往外看，减速，然后开到路边"],"h1":"控制好车，找别的方法看清路。","h2":"如果引擎盖弹起来，就从它下面的缝隙或侧窗往外看，减速，然后安全地把车开离道路。","p":"对。先想办法看清路，然后开到路边。"},"vi":{"q":"Khi bạn đang lái xe, nắp ca-pô bật lên và che mất tầm nhìn. Bạn nên làm gì?","o":["Phanh gấp trong làn xe của bạn","Ra khỏi xe để đóng nắp khi xe vẫn đang chạy","Tăng tốc để gió đóng nắp lại","Nhìn qua khe hở dưới nắp ca-pô hoặc qua cửa sổ bên, chạy chậm lại, và tấp vào lề"],"h1":"Giữ vững tay lái và tìm cách khác để nhìn đường.","h2":"Nếu nắp ca-pô bật lên, hãy nhìn qua khe hở bên dưới nó hoặc qua cửa sổ bên, chạy chậm lại, và tấp ra khỏi đường an toàn.","p":"Đúng. Tìm cách nhìn đường, rồi tấp vào lề."},"tl":{"q":"Habang nagmamaneho ka, biglang umangat ang hood at natakpan ang paningin mo. Ano ang dapat mong gawin?","o":["Magpreno nang malakas sa lane mo","Lumabas para isara ito habang umaandar","Bumilis para maisara ito ng hangin","Tumingin sa puwang sa ilalim ng hood o sa bintana sa gilid, bumagal, at tumabi"],"h1":"Panatilihin ang kontrol at humanap ng ibang paraan para makakita.","h2":"Kapag umangat ang hood, tumingin sa puwang sa ilalim nito o sa bintana sa gilid, bumagal, at tumabi palabas ng daan nang ligtas.","p":"Tama. Humanap ng paraan para makakita, saka tumabi."},"ar":{"q":"وأنت تقود، ارتفع غطاء المحرك فجأة وحجب رؤيتك. ماذا يجب أن تفعل؟","o":["اضغط على الفرامل بقوة في مسارك","اخرج لتغلقه والسيارة تتحرك","أسرع حتى يغلقه الهواء","انظر من الفتحة تحت الغطاء أو من النافذة الجانبية، وخفّف السرعة، وتوقّف جانبًا"],"h1":"حافظ على السيطرة وابحث عن طريقة أخرى للرؤية.","h2":"إذا ارتفع غطاء المحرك، انظر من الفتحة تحته أو من النافذة الجانبية، وخفّف السرعة، واخرج من الطريق بأمان.","p":"صحيح. جد طريقة لترى، ثم توقّف جانبًا."},"ht":{"q":"Pandan w ap kondui, kapo motè a leve sanzatann epi li bloke je w. Kisa ou ta dwe fè?","o":["Frennen fò nan liy ou","Desann pou fèmen l pandan machin nan ap mache","Akselere pou van an fèmen l","Gade nan ti espas anba kapo a oswa pa fenèt bò kote a, ralanti, epi rale sou kote a"],"h1":"Kenbe kontwòl machin nan epi chèche yon lòt fason pou wè.","h2":"Si kapo motè a leve, gade nan ti espas anba l oswa pa fenèt bò kote a, ralanti, epi soti sou wout la an sekirite.","p":"Se sa. Jwenn yon fason pou wè, epi rale sou kote a."}},{"id":"safe-driving-084","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You see smoke or flames coming from your car. What should you do?","o":["Pull over, turn off the engine, get everyone out and move far away","Keep driving to a gas station","Open the hood to look","Stay inside with the windows closed"],"h1":"People matter more than the car.","h2":"If your car is on fire, pull over, turn off the engine, get everyone out and well away from the car, and call 911.","p":"Right. Get everyone out and away."},"es":{"q":"Ve humo o llamas saliendo de su carro. ¿Qué debe hacer?","o":["Orillarse, apagar el motor, sacar a todos y alejarse bastante","Seguir manejando hasta una gasolinera","Abrir el capó para mirar","Quedarse adentro con las ventanas cerradas"],"h1":"Las personas importan más que el carro.","h2":"Si su carro se incendia, oríllese, apague el motor, saque a todos y aléjense bien del carro, y llame al 911.","p":"Correcto. Saque a todos y aléjense."},"zh":{"q":"你看到你的车冒烟或着火了。你应该怎么做？","o":["靠边停车，关掉发动机，让所有人下车，走到远处","继续开到加油站","打开引擎盖看一看","待在车里，关好车窗"],"h1":"人比车更重要。","h2":"如果你的车着火了，要靠边停车，关掉发动机，让所有人下车并远离汽车，然后打 911。","p":"对。让所有人下车，走远一点。"},"vi":{"q":"Bạn thấy khói hoặc lửa bốc ra từ xe của bạn. Bạn nên làm gì?","o":["Tấp vào lề, tắt máy, cho mọi người ra khỏi xe và đi thật xa","Tiếp tục lái đến trạm xăng","Mở nắp ca-pô ra xem","Ở trong xe và đóng kín cửa sổ"],"h1":"Con người quan trọng hơn chiếc xe.","h2":"Nếu xe bạn bị cháy, hãy tấp vào lề, tắt máy, cho mọi người ra khỏi xe và tránh thật xa chiếc xe, rồi gọi 911.","p":"Đúng. Cho mọi người ra ngoài và tránh xa."},"tl":{"q":"May nakikita kang usok o apoy na lumalabas sa kotse mo. Ano ang dapat mong gawin?","o":["Tumabi, patayin ang makina, palabasin ang lahat at lumayo nang husto","Patuloy na magmaneho papunta sa gasolinahan","Buksan ang hood para tingnan","Manatili sa loob nang nakasara ang mga bintana"],"h1":"Mas mahalaga ang tao kaysa sa kotse.","h2":"Kapag nasusunog ang kotse mo, tumabi, patayin ang makina, palabasin ang lahat at lumayo nang husto sa kotse, at tumawag sa 911.","p":"Tama. Palabasin ang lahat at lumayo."},"ar":{"q":"ترى دخانًا أو نارًا تخرج من سيارتك. ماذا يجب أن تفعل؟","o":["توقّف جانبًا، وأطفئ المحرك، وأخرِج الجميع وابتعدوا كثيرًا","استمر في القيادة إلى محطة وقود","افتح غطاء المحرك لتنظر","ابقَ في الداخل والنوافذ مغلقة"],"h1":"الناس أهم من السيارة.","h2":"إذا اشتعلت النار في سيارتك، توقّف جانبًا، وأطفئ المحرك، وأخرِج الجميع وابتعدوا كثيرًا عن السيارة، واتصل بـ 911.","p":"صحيح. أخرِج الجميع وابتعدوا."},"ht":{"q":"Ou wè lafimen oswa flanm dife k ap soti nan machin ou. Kisa ou ta dwe fè?","o":["Rale sou kote a, etenn motè a, fè tout moun desann epi ale byen lwen","Kontinye kondui jiska yon estasyon gaz","Louvri kapo motè a pou gade","Rete anndan ak fenèt yo fèmen"],"h1":"Moun pi enpòtan pase machin nan.","h2":"Si machin ou pran dife, rale sou kote a, etenn motè a, fè tout moun desann epi ale byen lwen machin nan, epi rele 911.","p":"Se sa. Fè tout moun desann epi ale lwen."}},{"id":"safe-driving-085","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your car breaks down on a highway. What should you do?","o":["Stop in your lane and wait","Pull as far off the road as you can and turn on your hazard lights","Walk along the lanes to find help","Leave the lights off to save the battery"],"h1":"Other drivers need to see and avoid your car.","h2":"If your car breaks down, get as far off the road as possible and turn on your hazard lights so other drivers can see you.","p":"Right. Get off the road and use hazard lights."},"es":{"q":"Su carro se descompone en la carretera. ¿Qué debe hacer?","o":["Pararse en su carril y esperar","Salirse de la vía lo más que pueda y encender las luces de emergencia","Caminar por los carriles para buscar ayuda","Dejar las luces apagadas para ahorrar batería"],"h1":"Los demás deben ver su carro y esquivarlo.","h2":"Si su carro se descompone, salga de la vía lo más que pueda y encienda las luces de emergencia para que los demás lo vean.","p":"Correcto. Salga de la vía y use las luces de emergencia."},"zh":{"q":"你的车在高速公路上坏了。你应该怎么做？","o":["在你的车道上停车等待","尽量把车开到离道路远的地方，并打开危险警示灯","沿着车道走去找人帮忙","不开灯，节省电池"],"h1":"别的司机需要看见并避开你的车。","h2":"如果你的车坏了，要尽量把车开离道路，并打开危险警示灯，让别的司机能看见你。","p":"对。离开道路，打开危险警示灯。"},"vi":{"q":"Xe bạn bị hư trên xa lộ. Bạn nên làm gì?","o":["Dừng lại trong làn xe của bạn và chờ","Tấp ra khỏi đường càng xa càng tốt và bật đèn khẩn cấp","Đi bộ dọc theo các làn xe để tìm người giúp","Tắt đèn để tiết kiệm bình điện"],"h1":"Các tài xế khác cần nhìn thấy và tránh được xe bạn.","h2":"Nếu xe bạn bị hư, hãy đưa xe ra khỏi đường càng xa càng tốt và bật đèn khẩn cấp để các tài xế khác nhìn thấy bạn.","p":"Đúng. Ra khỏi đường và bật đèn khẩn cấp."},"tl":{"q":"Nasira ang kotse mo sa highway. Ano ang dapat mong gawin?","o":["Huminto sa lane mo at maghintay","Tumabi nang malayo hangga't kaya mula sa daan at i-on ang hazard lights","Maglakad sa tabi ng mga lane para humanap ng tulong","Huwag buksan ang mga ilaw para makatipid sa baterya"],"h1":"Kailangang makita at maiwasan ng ibang mga driver ang kotse mo.","h2":"Kapag nasira ang kotse mo, lumayo sa daan hangga't kaya mo at i-on ang hazard lights para makita ka ng ibang mga driver.","p":"Tama. Umalis sa daan at gamitin ang hazard lights."},"ar":{"q":"سيارتك تعطّلت على طريق سريع. ماذا يجب أن تفعل؟","o":["توقّف في مسارك وانتظر","ابتعد عن الطريق بقدر ما تستطيع وشغّل أضواء التحذير","امشِ بجانب المسارات لتبحث عن مساعدة","اترك الأضواء مطفأة لتوفّر البطارية"],"h1":"السائقون الآخرون يحتاجون أن يروا سيارتك ويتجنّبوها.","h2":"إذا تعطّلت سيارتك، ابتعد عن الطريق بأكبر قدر ممكن وشغّل أضواء التحذير حتى يراك السائقون الآخرون.","p":"صحيح. اخرج من الطريق وشغّل أضواء التحذير."},"ht":{"q":"Machin ou tonbe an pàn sou yon otowout. Kisa ou ta dwe fè?","o":["Kanpe nan liy ou epi tann","Rale osi lwen wout la ke ou kapab epi limen limyè ijans yo","Mache bò liy yo pou chèche èd","Kite limyè yo etenn pou ekonomize batri a"],"h1":"Lòt chofè yo bezwen wè machin ou epi evite l.","h2":"Si machin ou tonbe an pàn, soti sou wout la osi lwen ke ou kapab epi limen limyè ijans yo pou lòt chofè yo ka wè w.","p":"Se sa. Soti sou wout la epi limen limyè ijans yo."}},{"id":"safe-driving-086","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"A car is coming toward you in your lane. What should you do?","o":["Steer into the left lane","Speed up","Slow down, honk, and steer to the right","Stop in your lane and wait"],"h1":"The other driver may move back to their own lane.","h2":"If a car comes at you in your lane, slow down, sound your horn and steer right, toward the shoulder; do not swerve left into its lane.","p":"Right. Slow, honk and move right."},"es":{"q":"Un carro viene hacia usted en su carril. ¿Qué debe hacer?","o":["Girar al carril izquierdo","Acelerar","Bajar la velocidad, tocar la bocina y girar a la derecha","Pararse en su carril y esperar"],"h1":"El otro conductor puede volver a su carril.","h2":"Si un carro viene hacia usted en su carril, baje la velocidad, toque la bocina y gire a la derecha, hacia el acotamiento; no se desvíe a la izquierda, a su carril.","p":"Correcto. Baje la velocidad, toque la bocina y vaya a la derecha."},"zh":{"q":"有一辆车在你的车道上朝你开过来。你应该怎么做？","o":["把车转到左边车道","加速","减速，按喇叭，把车往右边开","在你的车道上停车等待"],"h1":"对方司机可能会开回他自己的车道。","h2":"如果有车在你的车道上朝你开来，要减速，按喇叭，把车往右边的路肩方向开；不要突然向左转进它的车道。","p":"对。减速，按喇叭，往右开。"},"vi":{"q":"Có một xe đang chạy ngược về phía bạn trong làn xe của bạn. Bạn nên làm gì?","o":["Lái sang làn bên trái","Tăng tốc","Chạy chậm lại, bấm còi, và lái sang bên phải","Dừng lại trong làn xe của bạn và chờ"],"h1":"Tài xế kia có thể sẽ quay về làn của họ.","h2":"Nếu có xe chạy ngược về phía bạn trong làn của bạn, hãy chạy chậm lại, bấm còi và lái sang phải, về phía lề đường; đừng đánh lái sang trái vào làn của xe đó.","p":"Đúng. Chạy chậm, bấm còi và lái sang phải."},"tl":{"q":"May kotseng papunta sa iyo sa lane mo. Ano ang dapat mong gawin?","o":["Lumipat sa kaliwang lane","Bumilis","Bumagal, bumusina, at lumihis pakanan","Huminto sa lane mo at maghintay"],"h1":"Maaaring bumalik ang kabilang driver sa sarili niyang lane.","h2":"Kapag may kotseng papunta sa iyo sa lane mo, bumagal, bumusina, at lumihis pakanan, papunta sa gilid ng daan; huwag biglang lumiko pakaliwa papasok sa lane nito.","p":"Tama. Bumagal, bumusina, at lumipat pakanan."},"ar":{"q":"سيارة تأتي نحوك في مسارك. ماذا يجب أن تفعل؟","o":["وجّه السيارة إلى المسار الأيسر","أسرع","خفّف السرعة، واستعمل البوق، ووجّه السيارة إلى اليمين","توقّف في مسارك وانتظر"],"h1":"قد يرجع السائق الآخر إلى مساره.","h2":"إذا جاءت سيارة نحوك في مسارك، خفّف السرعة واستعمل البوق ووجّه السيارة إلى اليمين نحو حافة الطريق؛ يجب ألّا تنحرف إلى اليسار نحو مسارها.","p":"صحيح. خفّف السرعة، واستعمل البوق، واتجه يمينًا."},"ht":{"q":"Gen yon machin k ap vin sou ou nan liy ou. Kisa ou ta dwe fè?","o":["Vire nan liy goch la","Akselere","Ralanti, klaksonen, epi dirije machin nan adwat","Kanpe nan liy ou epi tann"],"h1":"Lòt chofè a ka retounen nan pwòp liy pa l.","h2":"Si yon machin ap vin sou ou nan liy ou, ralanti, klaksonen epi dirije adwat, bò kote rebò wout la; pa vire brid sou kou agoch nan liy pa l.","p":"Se sa. Ralanti, klaksonen epi ale adwat."}},{"id":"safe-driving-087","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You stop to help at a crash. A person is hurt but there is no fire or other danger. What should you do?","o":["Pull the person out of the car","Give the person something to drink","Drive the person to the hospital yourself","Call 911 and do not move the person"],"h1":"Moving an injured person can make injuries worse.","h2":"Do not move an injured person unless there is danger such as fire; call 911 and wait with them for help.","p":"Right. Call 911 and do not move them."},"es":{"q":"Usted se para a ayudar en un choque. Una persona está herida, pero no hay fuego ni otro peligro. ¿Qué debe hacer?","o":["Sacar a la persona del carro","Darle algo de beber","Llevarla usted mismo al hospital","Llamar al 911 y no mover a la persona"],"h1":"Mover a un herido puede empeorar sus lesiones.","h2":"No mueva a una persona herida salvo que haya un peligro como fuego; llame al 911 y espere con ella hasta que llegue ayuda.","p":"Correcto. Llame al 911 y no la mueva."},"zh":{"q":"你停车帮助处理一起车祸。有一个人受伤了，但是没有着火，也没有别的危险。你应该怎么做？","o":["把这个人从车里拉出来","给这个人喝点东西","自己开车送这个人去医院","打 911，不要移动这个人"],"h1":"移动受伤的人可能会让伤势更严重。","h2":"除非有着火这样的危险，否则不要移动受伤的人；要打 911，并陪着他们等待救援。","p":"对。打 911，不要移动他们。"},"vi":{"q":"Bạn dừng lại để giúp ở một vụ tai nạn. Có một người bị thương nhưng không có lửa hay nguy hiểm nào khác. Bạn nên làm gì?","o":["Kéo người đó ra khỏi xe","Cho người đó uống gì đó","Tự lái xe đưa người đó đến bệnh viện","Gọi 911 và không di chuyển người đó"],"h1":"Di chuyển người bị thương có thể làm vết thương nặng hơn.","h2":"Đừng di chuyển người bị thương trừ khi có nguy hiểm như cháy; hãy gọi 911 và ở lại cùng họ chờ người đến giúp.","p":"Đúng. Gọi 911 và không di chuyển họ."},"tl":{"q":"Huminto ka para tumulong sa isang banggaan. May taong nasaktan pero walang apoy o ibang panganib. Ano ang dapat mong gawin?","o":["Hilahin palabas ng kotse ang tao","Painumin ang tao","Ikaw mismo ang magdala sa tao sa ospital","Tumawag sa 911 at huwag galawin ang tao"],"h1":"Maaaring lumala ang pinsala kapag ginalaw ang taong nasaktan.","h2":"Huwag galawin ang taong nasaktan maliban kung may panganib tulad ng apoy; tumawag sa 911 at samahan sila habang naghihintay ng tulong.","p":"Tama. Tumawag sa 911 at huwag silang galawin."},"ar":{"q":"توقّفت لتساعد في حادث. هناك شخص مصاب، لكن لا توجد نار ولا خطر آخر. ماذا يجب أن تفعل؟","o":["اسحب الشخص من السيارة","أعطِ الشخص شيئًا ليشربه","خذ الشخص إلى المستشفى بسيارتك بنفسك","اتصل بـ 911 ولا تحرّك الشخص"],"h1":"تحريك الشخص المصاب قد يجعل إصاباته أسوأ.","h2":"يجب ألّا تحرّك الشخص المصاب إلا إذا كان هناك خطر مثل النار؛ اتصل بـ 911 وابقَ معه حتى تصل المساعدة.","p":"صحيح. اتصل بـ 911 ولا تحرّكه."},"ht":{"q":"Ou kanpe pou ede nan yon aksidan. Gen yon moun ki blese, men pa gen dife ni okenn lòt danje. Kisa ou ta dwe fè?","o":["Rale moun nan soti nan machin nan","Bay moun nan yon bagay pou l bwè","Mennen moun nan lopital ak machin ou menm","Rele 911 epi pa deplase moun nan"],"h1":"Deplase yon moun ki blese ka fè blesi l yo vin pi grav.","h2":"Pa deplase yon moun ki blese sof si gen yon danje tankou dife; rele 911 epi rete avè l pandan n ap tann èd.","p":"Se sa. Rele 911 epi pa deplase l."}},{"id":"safe-driving-088","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"How can you lower your chance of hydroplaning?","o":["Slow down on wet roads and keep good tread and the right air pressure in your tires","Drive faster to get through the water","Use cruise control in the rain","Let air out of your tires"],"h1":"Speed and worn tires make hydroplaning more likely.","h2":"To lower the risk of hydroplaning, slow down when the road is wet and keep your tires properly inflated with good tread.","p":"Right. Slow down and keep good tires."},"es":{"q":"¿Cómo puede reducir el riesgo de hidroplaneo?","o":["Bajando la velocidad en vías mojadas y manteniendo buen dibujo y la presión correcta en las llantas","Manejando más rápido para pasar el agua","Usando el control de crucero con lluvia","Sacándoles aire a las llantas"],"h1":"La velocidad y las llantas gastadas hacen más probable el hidroplaneo.","h2":"Para reducir el riesgo de hidroplaneo, baje la velocidad cuando la vía está mojada y mantenga las llantas bien infladas y con buen dibujo.","p":"Correcto. Baje la velocidad y mantenga buenas llantas."},"zh":{"q":"怎样才能降低水滑的机会？","o":["在湿的路上减速，并保持轮胎花纹良好、胎压正确","开快一点，冲过水","下雨时使用定速巡航","给轮胎放气"],"h1":"车速快和轮胎磨损会让水滑更容易发生。","h2":"要降低水滑的危险，路面湿的时候要减速，并保持轮胎胎压正确、花纹良好。","p":"对。减速，保持轮胎良好。"},"vi":{"q":"Làm sao để bạn giảm nguy cơ xe bị trượt nước (hydroplaning)?","o":["Chạy chậm lại trên đường ướt và giữ lốp xe có gai tốt và áp suất đúng","Lái nhanh hơn để vượt qua vùng nước","Dùng chế độ giữ tốc độ tự động (cruise control) khi trời mưa","Xả bớt hơi trong lốp xe"],"h1":"Tốc độ cao và lốp mòn làm xe dễ bị trượt nước hơn.","h2":"Để giảm nguy cơ trượt nước, hãy chạy chậm lại khi đường ướt và giữ lốp xe được bơm đúng áp suất và có gai tốt.","p":"Đúng. Chạy chậm và giữ lốp xe tốt."},"tl":{"q":"Paano mo mababawasan ang posibilidad ng hydroplaning?","o":["Bumagal sa basang daan at panatilihing maganda ang tread at tama ang hangin ng mga gulong mo","Magmaneho nang mas mabilis para malampasan ang tubig","Gamitin ang cruise control kapag umuulan","Bawasan ang hangin ng mga gulong mo"],"h1":"Mas madaling mag-hydroplaning kapag mabilis at kapag pudpod ang gulong.","h2":"Para mabawasan ang panganib ng hydroplaning, bumagal kapag basa ang daan at panatilihing tama ang hangin at maganda ang tread ng mga gulong mo.","p":"Tama. Bumagal at panatilihing maayos ang mga gulong."},"ar":{"q":"كيف تستطيع أن تقلّل احتمال الانزلاق المائي؟","o":["خفّف السرعة على الطرق المبللة وحافظ على نقوش جيدة وضغط هواء صحيح في إطاراتك","قُد أسرع لتعبر الماء","استعمل مثبّت السرعة (cruise control) في المطر","أخرِج بعض الهواء من إطاراتك"],"h1":"السرعة والإطارات البالية تجعل الانزلاق المائي أكثر احتمالًا.","h2":"لتقليل خطر الانزلاق المائي، خفّف السرعة عندما يكون الطريق مبللًا، وحافظ على ضغط هواء صحيح ونقوش جيدة في إطاراتك.","p":"صحيح. خفّف السرعة وحافظ على إطارات جيدة."},"ht":{"q":"Kijan ou ka diminye chans pou machin ou glise sou dlo (hydroplaning)?","o":["Ralanti sou wout mouye epi kenbe kawotchou ou yo ak bon tras ak bon kantite lè","Kondui pi vit pou travèse dlo a","Sèvi ak kontwòl vitès otomatik (cruise control) lè lapli ap tonbe","Retire lè nan kawotchou ou yo"],"h1":"Vitès ak kawotchou ki fin use fè machin nan pi fasil glise sou dlo.","h2":"Pou diminye risk pou machin nan glise sou dlo, ralanti lè wout la mouye epi kenbe kawotchou ou yo ak bon kantite lè ak bon tras.","p":"Se sa. Ralanti epi kenbe bon kawotchou."}},{"id":"safe-driving-089","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"The fog becomes so thick that you can barely see. What is the safest thing to do?","o":["Stop in your lane","Pull completely off the road, away from traffic, and turn on your hazard lights","Speed up to get out of the fog","Turn on your high beams"],"h1":"Stopping in a lane in fog invites a rear-end crash.","h2":"If fog is too thick to drive safely, pull completely off the road away from traffic, turn on your hazard lights, and wait for it to clear.","p":"Right. Pull fully off the road and use hazard lights."},"es":{"q":"La niebla se vuelve tan espesa que casi no ve. ¿Qué es lo más seguro?","o":["Pararse en su carril","Salirse por completo de la vía, lejos del tráfico, y encender las luces de emergencia","Acelerar para salir de la niebla","Encender las luces altas"],"h1":"Pararse en un carril con niebla invita a que lo choquen por detrás.","h2":"Si la niebla es demasiado espesa para manejar con seguridad, salga por completo de la vía lejos del tráfico, encienda las luces de emergencia y espere a que se despeje.","p":"Correcto. Salga de la vía y use las luces de emergencia."},"zh":{"q":"雾变得很浓，你几乎看不见。最安全的做法是什么？","o":["在你的车道上停车","把车完全开离道路，远离车流，并打开危险警示灯","加速开出雾区","打开远光灯"],"h1":"在雾中停在车道上，很容易被后面的车追尾。","h2":"如果雾太浓，不能安全驾驶，就把车完全开离道路，远离车流，打开危险警示灯，等雾散了再走。","p":"对。把车完全开离道路，打开危险警示灯。"},"vi":{"q":"Sương mù dày đến mức bạn gần như không nhìn thấy gì. Điều an toàn nhất nên làm là gì?","o":["Dừng lại trong làn xe của bạn","Tấp hẳn ra khỏi đường, tránh xa dòng xe, và bật đèn khẩn cấp","Tăng tốc để ra khỏi sương mù","Bật đèn pha chiếu xa"],"h1":"Dừng xe trong làn đường khi có sương mù dễ bị xe sau đâm vào đuôi.","h2":"Nếu sương mù quá dày để lái xe an toàn, hãy tấp hẳn ra khỏi đường, tránh xa dòng xe, bật đèn khẩn cấp, và chờ đến khi sương tan.","p":"Đúng. Tấp hẳn ra khỏi đường và bật đèn khẩn cấp."},"tl":{"q":"Sobrang kapal ng hamog na halos hindi ka na makakita. Ano ang pinakaligtas na gawin?","o":["Huminto sa lane mo","Tumabi nang tuluyan palabas ng daan, malayo sa trapiko, at i-on ang hazard lights","Bumilis para makalabas sa hamog","I-on ang high beams"],"h1":"Kapag huminto ka sa lane sa gitna ng hamog, maaari kang mabangga mula sa likod.","h2":"Kung masyadong makapal ang hamog para makapagmaneho nang ligtas, tumabi nang tuluyan palabas ng daan, malayo sa trapiko, i-on ang hazard lights, at hintaying lumiwanag.","p":"Tama. Tuluyang umalis sa daan at gamitin ang hazard lights."},"ar":{"q":"الضباب أصبح كثيفًا جدًا ولا تكاد ترى شيئًا. ما أكثر شيء آمن تفعله؟","o":["توقّف في مسارك","اخرج من الطريق تمامًا بعيدًا عن السيارات، وشغّل أضواء التحذير","أسرع لتخرج من الضباب","شغّل الأضواء العالية"],"h1":"التوقف في المسار وسط الضباب قد يجعل سيارة تصدمك من الخلف.","h2":"إذا كان الضباب كثيفًا جدًا ولا تستطيع القيادة بأمان، اخرج من الطريق تمامًا بعيدًا عن السيارات، وشغّل أضواء التحذير، وانتظر حتى ينقشع.","p":"صحيح. اخرج من الطريق تمامًا وشغّل أضواء التحذير."},"ht":{"q":"Bwouya a vin tèlman epè ou prèske pa ka wè anyen. Kisa ki pi an sekirite pou w fè?","o":["Kanpe nan liy ou","Soti nèt sou wout la, lwen machin k ap pase yo, epi limen limyè ijans yo","Akselere pou soti nan bwouya a","Limen gwo limyè yo"],"h1":"Si ou kanpe nan yon liy nan bwouya, yon machin ka frape w pa dèyè.","h2":"Si bwouya a twò epè pou w kondui an sekirite, soti nèt sou wout la lwen machin k ap pase yo, limen limyè ijans yo, epi tann li klere.","p":"Se sa. Soti nèt sou wout la epi limen limyè ijans yo."}},{"id":"safe-driving-090","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"You are driving slowly in fog. What can help you stay in your lane?","o":["Follow the center line closely","Follow the taillights of the car ahead very closely","Use the white line on the right edge of the road as a guide","Look at the car beside you"],"h1":"The edge line is away from oncoming traffic.","h2":"In fog, use the right edge line as a guide to stay in your lane, and keep a safe distance from the car ahead.","p":"Right. Use the right edge line."},"es":{"q":"Usted maneja despacio en la niebla. ¿Qué le puede ayudar a mantenerse en su carril?","o":["Seguir de cerca la línea central","Seguir muy de cerca las luces traseras del carro de adelante","Usar como guía la línea blanca de la orilla derecha","Mirar al carro de al lado"],"h1":"La línea de la orilla está lejos del tráfico de frente.","h2":"Con niebla, use la línea de la orilla derecha como guía para mantenerse en su carril, y guarde una distancia segura con el carro de adelante.","p":"Correcto. Use la línea de la orilla derecha."},"zh":{"q":"你在雾中慢慢开车。什么可以帮助你保持在自己的车道上？","o":["紧紧沿着中间的线开","紧紧跟着前面那辆车的尾灯","用道路右边边缘的白线作为参考","看着你旁边的车"],"h1":"边缘线离对面开来的车比较远。","h2":"在雾中，用右边的边缘线作为参考来保持在自己的车道上，并和前面的车保持安全距离。","p":"对。用右边的边缘线。"},"vi":{"q":"Bạn đang lái chậm trong sương mù. Điều gì giúp bạn giữ đúng làn xe?","o":["Bám sát vạch giữa đường","Bám thật sát đèn hậu của xe phía trước","Dùng vạch trắng ở mép bên phải của đường làm hướng dẫn","Nhìn vào xe bên cạnh bạn"],"h1":"Vạch mép đường nằm xa dòng xe chạy ngược chiều.","h2":"Trong sương mù, hãy dùng vạch mép bên phải làm hướng dẫn để giữ đúng làn xe, và giữ khoảng cách an toàn với xe phía trước.","p":"Đúng. Dùng vạch mép bên phải."},"tl":{"q":"Mabagal kang nagmamaneho sa hamog. Ano ang makakatulong para manatili ka sa lane mo?","o":["Sundan nang malapit ang guhit sa gitna","Sundan nang napakalapit ang taillights ng kotse sa unahan","Gamiting gabay ang puting guhit sa kanang gilid ng daan","Tingnan ang kotse sa tabi mo"],"h1":"Malayo sa paparating na trapiko ang guhit sa gilid.","h2":"Sa hamog, gamiting gabay ang guhit sa kanang gilid para manatili sa lane mo, at panatilihin ang ligtas na distansya sa kotse sa unahan.","p":"Tama. Gamitin ang guhit sa kanang gilid."},"ar":{"q":"أنت تقود ببطء في الضباب. ما الذي يساعدك على البقاء في مسارك؟","o":["اتبع الخط الأوسط عن قرب","اتبع الأضواء الخلفية للسيارة التي أمامك عن قرب شديد","استعمل الخط الأبيض على الحافة اليمنى للطريق كدليل","انظر إلى السيارة التي بجانبك"],"h1":"خط الحافة بعيد عن السيارات القادمة من الاتجاه المقابل.","h2":"في الضباب، استعمل خط الحافة اليمنى كدليل لتبقى في مسارك، وحافظ على مسافة آمنة من السيارة التي أمامك.","p":"صحيح. استعمل خط الحافة اليمنى."},"ht":{"q":"W ap kondui dousman nan bwouya. Kisa ki ka ede w rete nan liy ou?","o":["Swiv liy nan mitan an byen pre","Swiv limyè dèyè machin ki devan w lan byen pre","Sèvi ak liy blan ki sou rebò dwat wout la kòm gid","Gade machin ki bò kote w la"],"h1":"Liy rebò a lwen machin k ap vin nan sans kontrè yo.","h2":"Nan bwouya, sèvi ak liy rebò dwat la kòm gid pou rete nan liy ou, epi kenbe yon distans ki an sekirite ak machin ki devan w lan.","p":"Se sa. Sèvi ak liy rebò dwat la."}},{"id":"safe-driving-091","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"At night, the headlights of a car behind you shine in your rearview mirror. What can you do?","o":["Brake to make the driver back off","Turn on your high beams","Look away from the road","Flip the mirror to its night setting"],"h1":"Most inside mirrors have a tab or dim automatically.","h2":"Use the night setting on your rearview mirror to reduce glare from headlights behind you.","p":"Right. Use the mirror's night setting."},"es":{"q":"De noche, los faros de un carro detrás de usted brillan en el espejo retrovisor. ¿Qué puede hacer?","o":["Frenar para que se aleje","Encender las luces altas","Dejar de mirar la vía","Poner el espejo en la posición de noche"],"h1":"La mayoría de los espejos interiores tienen una palanca o se oscurecen solos.","h2":"Use la posición de noche del espejo retrovisor para reducir el reflejo de los faros que vienen detrás.","p":"Correcto. Use la posición de noche del espejo."},"zh":{"q":"夜里，后面车辆的车头灯照在你的车内后视镜上。你可以怎么做？","o":["刹车，让后面的司机离远一点","打开你的远光灯","把视线从路上移开","把后视镜调到夜间模式"],"h1":"大多数车内后视镜有一个小拨片，或者会自动变暗。","h2":"使用车内后视镜的夜间模式，可以减少后面车头灯造成的眩光。","p":"对。使用后视镜的夜间模式。"},"vi":{"q":"Vào ban đêm, đèn pha của xe phía sau chiếu vào gương chiếu hậu trong xe của bạn. Bạn có thể làm gì?","o":["Đạp thắng để người lái phía sau lùi xa ra","Bật đèn pha chiếu xa của bạn","Nhìn ra chỗ khác, không nhìn đường","Gạt gương sang chế độ ban đêm"],"h1":"Hầu hết gương trong xe có một cái lẫy hoặc tự động làm tối.","h2":"Hãy dùng chế độ ban đêm của gương chiếu hậu trong xe để giảm chói từ đèn pha của xe phía sau.","p":"Đúng. Dùng chế độ ban đêm của gương."},"tl":{"q":"Sa gabi, tumatama sa rearview mirror mo ang headlights ng kotse sa likod mo. Ano ang puwede mong gawin?","o":["Mag-preno para lumayo ang driver sa likod","Buksan ang high beams mo","Tumingin palayo sa kalsada","Ilipat ang salamin sa night setting nito"],"h1":"Karamihan ng salamin sa loob ng kotse ay may maliit na pihitan o kusang dumidilim.","h2":"Gamitin ang night setting ng rearview mirror mo para mabawasan ang silaw ng headlights sa likod mo.","p":"Tama. Gamitin ang night setting ng salamin."},"ar":{"q":"في الليل، تلمع أضواء السيارة التي خلفك في مرآة الرؤية الخلفية. ماذا يمكنك أن تفعل؟","o":["اضغط على الفرامل ليبتعد السائق الذي خلفك","شغّل الأضواء العالية","انظر بعيدًا عن الطريق","حوّل المرآة إلى وضع الليل"],"h1":"معظم المرايا الداخلية فيها مقبض صغير أو تخفت تلقائيًا.","h2":"استخدم وضع الليل في مرآة الرؤية الخلفية لتخفيف الوهج من أضواء السيارات التي خلفك.","p":"صحيح. استخدم وضع الليل في المرآة."},"ht":{"q":"Lannwit, limyè machin ki dèyè w la ap klere nan retwovizè anndan machin ou. Kisa ou ka fè?","o":["Frennen pou chofè a ka rete pi lwen","Limen gwo limyè ou yo","Gade yon lòt kote, pa sou wout la","Mete retwovizè a sou pozisyon lannwit li"],"h1":"Pifò retwovizè anndan machin gen yon ti manch, oswa yo vin pi fonse poukont yo.","h2":"Sèvi ak pozisyon lannwit retwovizè a pou diminye ekla limyè machin ki dèyè w yo.","p":"Se sa. Sèvi ak pozisyon lannwit retwovizè a."}},{"id":"safe-driving-092","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"You are driving toward a low, bright sun and the glare makes it hard to see. What should you do?","o":["Use your sun visor and sunglasses, and slow down","Speed up to get past the glare","Close one eye","Follow the car ahead more closely"],"h1":"If you see less, you need more time.","h2":"In sun glare, lower the visor, wear sunglasses, keep your windshield clean and slow down, leaving extra space ahead.","p":"Right. Visor, sunglasses, and slow down."},"es":{"q":"Usted maneja hacia un sol bajo y brillante, y el reflejo no lo deja ver bien. ¿Qué debe hacer?","o":["Usar el parasol y lentes de sol, y bajar la velocidad","Acelerar para pasar el reflejo","Cerrar un ojo","Seguir más de cerca al carro de adelante"],"h1":"Si ve menos, necesita más tiempo.","h2":"Con el reflejo del sol, baje el parasol, use lentes de sol, mantenga limpio el parabrisas y baje la velocidad, dejando más espacio adelante.","p":"Correcto. Parasol, lentes de sol y menos velocidad."},"zh":{"q":"你正朝着低而刺眼的太阳开车，眩光让你很难看清。你应该怎么做？","o":["使用遮阳板和太阳镜，并且减速","加速，快点开过眩光","闭上一只眼睛","跟前面的车跟得更近"],"h1":"看得越少，就需要越多的时间。","h2":"遇到阳光眩光时，放下遮阳板，戴上太阳镜，保持挡风玻璃干净，并且减速，在前面多留空间。","p":"对。遮阳板、太阳镜，再减速。"},"vi":{"q":"Bạn đang lái xe về phía mặt trời thấp và chói, ánh chói làm bạn khó nhìn. Bạn nên làm gì?","o":["Dùng tấm che nắng và kính râm, và chạy chậm lại","Tăng tốc để qua khỏi chỗ chói","Nhắm một mắt","Chạy sát xe phía trước hơn"],"h1":"Nếu bạn nhìn thấy ít hơn, bạn cần nhiều thời gian hơn.","h2":"Khi bị nắng chói, hãy hạ tấm che nắng, đeo kính râm, giữ kính chắn gió sạch và chạy chậm lại, chừa thêm khoảng cách phía trước.","p":"Đúng. Tấm che nắng, kính râm, và chạy chậm lại."},"tl":{"q":"Nagmamaneho ka papunta sa mababa at maliwanag na araw, at dahil sa silaw ay mahirap makakita. Ano ang dapat mong gawin?","o":["Gamitin ang sun visor at sunglasses mo, at magdahan-dahan","Bumilis para malampasan ang silaw","Ipikit ang isang mata","Sundan nang mas malapit ang kotse sa unahan"],"h1":"Kapag mas kaunti ang nakikita mo, mas maraming oras ang kailangan mo.","h2":"Kapag nasisilaw sa araw, ibaba ang visor, magsuot ng sunglasses, panatilihing malinis ang windshield at magdahan-dahan, at mag-iwan ng dagdag na espasyo sa unahan.","p":"Tama. Visor, sunglasses, at magdahan-dahan."},"ar":{"q":"أنت تقود نحو شمس منخفضة وساطعة، والوهج يجعل الرؤية صعبة. ماذا يجب أن تفعل؟","o":["استخدم واقي الشمس والنظارة الشمسية، وخفّف السرعة","زِد السرعة لتتجاوز الوهج","أغمض عينًا واحدة","اقترب أكثر من السيارة التي أمامك"],"h1":"إذا كنت ترى أقل، فأنت تحتاج إلى وقت أكثر.","h2":"عند وهج الشمس، أنزل واقي الشمس، والبس نظارة شمسية، وحافظ على نظافة الزجاج الأمامي، وخفّف السرعة، واترك مسافة إضافية أمامك.","p":"صحيح. واقي الشمس، والنظارة الشمسية، وخفّف السرعة."},"ht":{"q":"W ap kondui anfas yon solèy ki ba e ki klere anpil, epi ekla a fè l difisil pou w wè. Kisa ou dwe fè?","o":["Sèvi ak parasolèy la ak linèt solèy, epi ralanti","Akselere pou w pase ekla a vit","Fèmen yon grenn je","Swiv machin devan an pi pre"],"h1":"Si w wè mwens, ou bezwen plis tan.","h2":"Lè gen ekla solèy, bese parasolèy la, mete linèt solèy, kenbe vitre devan an pwòp epi ralanti, e kite plis espas devan w.","p":"Se sa. Parasolèy, linèt solèy, epi ralanti."}},{"id":"safe-driving-093","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Why should your windshield be clean inside and out, especially at night?","o":["It makes the car faster","Dirt and film scatter light and make glare worse","It keeps the wipers from working","It does not matter at night"],"h1":"Lights from other cars hit your windshield.","h2":"A dirty windshield, inside or out, spreads the light from other headlights and makes glare much worse, so keep it clean.","p":"Right. Dirt makes glare worse."},"es":{"q":"¿Por qué el parabrisas debe estar limpio por dentro y por fuera, sobre todo de noche?","o":["Porque el carro va más rápido","Porque la suciedad dispersa la luz y empeora el reflejo","Porque así no funcionan los limpiaparabrisas","No importa de noche"],"h1":"Las luces de los otros carros dan en su parabrisas.","h2":"Un parabrisas sucio, por dentro o por fuera, dispersa la luz de los otros faros y empeora mucho el reflejo, así que manténgalo limpio.","p":"Correcto. La suciedad empeora el reflejo."},"zh":{"q":"为什么挡风玻璃里外都要保持干净，特别是在夜里？","o":["这样车会开得更快","灰尘和油膜会散射光线，让眩光更严重","这样雨刷就不会工作","夜里没关系"],"h1":"其他车的灯光会照到你的挡风玻璃上。","h2":"挡风玻璃不管里面还是外面脏了，都会把其他车头灯的光散开，让眩光严重得多，所以要保持干净。","p":"对。灰尘会让眩光更严重。"},"vi":{"q":"Tại sao kính chắn gió phải sạch cả bên trong lẫn bên ngoài, nhất là vào ban đêm?","o":["Nó làm xe chạy nhanh hơn","Bụi bẩn và lớp màng làm tán ánh sáng và làm chói nặng hơn","Nó làm cần gạt nước không hoạt động","Ban đêm thì không sao"],"h1":"Đèn của xe khác chiếu vào kính chắn gió của bạn.","h2":"Kính chắn gió bẩn, bên trong hay bên ngoài, sẽ làm tán ánh sáng từ đèn pha xe khác và làm chói nặng hơn nhiều, vì vậy hãy giữ kính sạch.","p":"Đúng. Bụi bẩn làm chói nặng hơn."},"tl":{"q":"Bakit dapat malinis ang windshield mo sa loob at labas, lalo na sa gabi?","o":["Pinabibilis nito ang kotse","Ikinakalat ng dumi at manipis na latak ang liwanag at pinalalala ang silaw","Pinipigilan nitong gumana ang wipers","Hindi ito mahalaga sa gabi"],"h1":"Tumatama sa windshield mo ang ilaw ng ibang kotse.","h2":"Ang maruming windshield, sa loob man o sa labas, ay nagkakalat ng liwanag mula sa headlights ng iba at lalong pinalalala ang silaw, kaya panatilihin itong malinis.","p":"Tama. Pinalalala ng dumi ang silaw."},"ar":{"q":"لماذا يجب أن يكون الزجاج الأمامي نظيفًا من الداخل والخارج، خاصةً في الليل؟","o":["لأنه يجعل السيارة أسرع","لأن الأوساخ والطبقة الرقيقة تشتّت الضوء وتزيد الوهج","لأنه يمنع المسّاحات من العمل","لا يهم ذلك في الليل"],"h1":"أضواء السيارات الأخرى تصل إلى زجاجك الأمامي.","h2":"الزجاج الأمامي المتّسخ، من الداخل أو الخارج، يشتّت ضوء مصابيح السيارات الأخرى ويزيد الوهج كثيرًا، لذلك حافظ على نظافته.","p":"صحيح. الأوساخ تزيد الوهج."},"ht":{"q":"Poukisa vitre devan machin ou dwe pwòp anndan kou deyò, sitou lannwit?","o":["Li fè machin nan mache pi vit","Pousyè ak kras simaye limyè a epi fè ekla a pi mal","Li anpeche esuiglas yo travay","Sa pa enpòtan lannwit"],"h1":"Limyè lòt machin yo frape vitre devan w lan.","h2":"Yon vitre devan ki sal, anndan oswa deyò, simaye limyè lòt machin yo epi fè ekla a vin pi mal anpil, kidonk kenbe l pwòp.","p":"Se sa. Kras fè ekla a pi mal."}},{"id":"safe-driving-094","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Before you drive after a snowfall, what should you clear off your car?","o":["Only a small spot on the windshield","Only the driver's window","All snow and ice from the windows, mirrors, lights and roof","Nothing; it will blow off"],"h1":"You need to see and be seen, and snow can fly off.","h2":"Clear all snow and ice from every window, mirror and light, and from the roof, so you can see, others can see you, and snow does not fly off onto other cars.","p":"Right. Clear it all off."},"es":{"q":"Antes de manejar después de una nevada, ¿qué debe limpiar de su carro?","o":["Solo una parte pequeña del parabrisas","Solo la ventana del conductor","Toda la nieve y el hielo de las ventanas, espejos, luces y techo","Nada; se volará solo"],"h1":"Necesita ver y que lo vean, y la nieve puede salir volando.","h2":"Quite toda la nieve y el hielo de cada ventana, espejo y luz, y del techo, para ver, para que lo vean, y para que la nieve no caiga sobre otros carros.","p":"Correcto. Quítelo todo."},"zh":{"q":"下雪后开车之前，你应该清除车上的什么？","o":["只清除挡风玻璃上一小块","只清除司机那边的车窗","清除车窗、后视镜、车灯和车顶上所有的雪和冰","什么都不用清，开起来就会吹掉"],"h1":"你需要看得见，也需要被别人看见，而且雪可能会飞出去。","h2":"把每一扇车窗、每一面后视镜、每一个车灯以及车顶上的雪和冰全部清除，这样你看得见，别人也看得见你，雪也不会飞到别的车上。","p":"对。全部清干净。"},"vi":{"q":"Trước khi lái xe sau khi tuyết rơi, bạn nên dọn sạch gì trên xe?","o":["Chỉ một chỗ nhỏ trên kính chắn gió","Chỉ cửa sổ bên người lái","Tất cả tuyết và băng trên cửa sổ, gương, đèn và nóc xe","Không gì cả; nó sẽ tự bay đi"],"h1":"Bạn cần nhìn thấy và được nhìn thấy, và tuyết có thể bay ra.","h2":"Hãy dọn sạch tất cả tuyết và băng trên mọi cửa sổ, gương và đèn, và trên nóc xe, để bạn nhìn thấy được, người khác thấy bạn, và tuyết không bay vào xe khác.","p":"Đúng. Dọn sạch hết."},"tl":{"q":"Bago ka magmaneho pagkatapos umulan ng niyebe, ano ang dapat mong alisin sa kotse mo?","o":["Isang maliit na bahagi lang sa windshield","Ang bintana lang ng driver","Lahat ng niyebe at yelo sa mga bintana, salamin, ilaw at bubong","Wala; liliparin lang iyon ng hangin"],"h1":"Kailangan mong makakita at makita ka, at puwedeng lumipad ang niyebe.","h2":"Alisin ang lahat ng niyebe at yelo sa bawat bintana, salamin at ilaw, at sa bubong, para makakita ka, makita ka ng iba, at hindi lumipad ang niyebe sa ibang kotse.","p":"Tama. Alisin lahat."},"ar":{"q":"قبل أن تقود بعد تساقط الثلج، ماذا يجب أن تزيل عن سيارتك؟","o":["بقعة صغيرة فقط على الزجاج الأمامي","نافذة السائق فقط","كل الثلج والجليد عن النوافذ والمرايا والأضواء والسقف","لا شيء؛ سيطير وحده"],"h1":"تحتاج أن ترى وأن يراك الآخرون، والثلج قد يطير.","h2":"أزِل كل الثلج والجليد عن كل نافذة ومرآة وضوء، وعن السقف، لكي ترى ويراك الآخرون، ولكي لا يطير الثلج على السيارات الأخرى.","p":"صحيح. أزِل كل شيء."},"ht":{"q":"Anvan ou kondui apre lanèj fin tonbe, kisa ou dwe retire sou machin ou?","o":["Yon ti kote sèlman sou vitre devan an","Vitre chofè a sèlman","Tout lanèj ak glas ki sou vitre yo, retwovizè yo, limyè yo ak twati a","Anyen; van an ap pote l ale"],"h1":"Ou bezwen wè, ou bezwen pou yo wè w, epi lanèj ka vole.","h2":"Retire tout lanèj ak glas sou chak vitre, chak retwovizè ak chak limyè, ak sou twati a, pou w ka wè, pou lòt moun ka wè w, e pou lanèj pa vole tonbe sou lòt machin.","p":"Se sa. Retire tout."}},{"id":"safe-driving-095","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"What is \"black ice\", and where is it most likely?","o":["Dirty snow on the shoulder","Ice that is easy to see because it is dark","Ice that forms only in the afternoon sun","A thin, clear layer of ice that looks like wet road, often on bridges and in shade"],"h1":"You often cannot see it.","h2":"Black ice is a thin, clear coat of ice that looks like a wet road; it forms most often on bridges, overpasses and shaded spots.","p":"Right. Clear ice that looks wet, often on bridges and in shade."},"es":{"q":"¿Qué es el \"hielo negro\" y dónde es más probable?","o":["Nieve sucia en el acotamiento","Hielo fácil de ver porque es oscuro","Hielo que se forma solo con el sol de la tarde","Una capa fina y transparente de hielo que parece vía mojada, a menudo en puentes y en la sombra"],"h1":"Muchas veces no se puede ver.","h2":"El hielo negro es una capa fina y transparente de hielo que parece vía mojada; se forma sobre todo en puentes, pasos elevados y lugares con sombra.","p":"Correcto. Hielo transparente que parece mojado, a menudo en puentes y en la sombra."},"zh":{"q":"什么是“black ice”（黑冰），它最可能出现在哪里？","o":["路肩上的脏雪","因为颜色深而很容易看见的冰","只在下午阳光下形成的冰","一层薄而透明、看起来像湿路面的冰，常在桥上和阴凉处"],"h1":"你常常看不见它。","h2":"黑冰是一层薄而透明的冰，看起来像湿的路面；它最常出现在桥上、高架桥上和阴凉的地方。","p":"对。透明的冰看起来像湿路，常在桥上和阴凉处。"},"vi":{"q":"\"Black ice\" (băng đen) là gì, và nó thường có ở đâu nhất?","o":["Tuyết bẩn trên lề đường","Băng dễ thấy vì nó có màu tối","Băng chỉ hình thành dưới nắng buổi chiều","Một lớp băng mỏng, trong suốt trông giống mặt đường ướt, thường có trên cầu và chỗ râm mát"],"h1":"Bạn thường không thể nhìn thấy nó.","h2":"Băng đen là một lớp băng mỏng, trong suốt trông giống mặt đường ướt; nó thường hình thành nhất trên cầu, cầu vượt và những chỗ râm mát.","p":"Đúng. Băng trong suốt trông như đường ướt, thường có trên cầu và chỗ râm."},"tl":{"q":"Ano ang \"black ice\", at saan ito pinakamalamang na makikita?","o":["Maruming niyebe sa gilid ng daan","Yelong madaling makita dahil madilim ito","Yelong nabubuo lang sa araw ng hapon","Isang manipis at malinaw na patong ng yelo na mukhang basang kalsada, madalas sa mga tulay at sa lilim"],"h1":"Madalas ay hindi mo ito nakikita.","h2":"Ang black ice ay manipis at malinaw na patong ng yelo na mukhang basang kalsada; madalas itong nabubuo sa mga tulay, overpass at mga lugar na may lilim.","p":"Tama. Malinaw na yelong mukhang basa, madalas sa tulay at sa lilim."},"ar":{"q":"ما هو \"black ice\" (الجليد الأسود)، وأين يكون على الأرجح؟","o":["ثلج متّسخ على كتف الطريق","جليد سهل الرؤية لأنه داكن","جليد يتكوّن فقط تحت شمس بعد الظهر","طبقة رقيقة وشفافة من الجليد تبدو مثل طريق مبلّل، غالبًا على الجسور وفي الظل"],"h1":"غالبًا لا يمكنك أن تراه.","h2":"الجليد الأسود طبقة رقيقة وشفافة من الجليد تبدو مثل طريق مبلّل، ويتكوّن غالبًا على الجسور والجسور العلوية والأماكن المظلّلة.","p":"صحيح. جليد شفاف يبدو مبلّلًا، غالبًا على الجسور وفي الظل."},"ht":{"q":"Kisa \"black ice\" (glas nwa) ye, e ki kote li gen plis chans pou l ye?","o":["Lanèj sal sou bò wout la","Glas ki fasil pou w wè paske li fonse","Glas ki fòme sèlman nan solèy aprèmidi","Yon kouch glas mens e klè ki sanble yon wout mouye, souvan sou pon ak nan lonbraj"],"h1":"Souvan ou pa ka wè l.","h2":"Glas nwa se yon kouch glas mens e klè ki sanble yon wout mouye; li fòme pi souvan sou pon, sou pasaj anwo wout ak nan kote ki gen lonbraj.","p":"Se sa. Glas klè ki sanble mouye, souvan sou pon ak nan lonbraj."}},{"id":"safe-driving-096","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"How should you drive on snow or ice?","o":["Speed up, brake and steer gently, and leave much more space","Brake hard to test the grip","Use cruise control","Make quick turns to stay in control"],"h1":"Sudden moves make tires slide.","h2":"On snow or ice, do everything gently: accelerate, brake and steer smoothly, drive slower, and leave much more space ahead.","p":"Right. Gentle moves and more space."},"es":{"q":"¿Cómo debe manejar sobre nieve o hielo?","o":["Acelerar, frenar y girar con suavidad, y dejar mucho más espacio","Frenar fuerte para probar el agarre","Usar el control de crucero","Hacer giros rápidos para mantener el control"],"h1":"Los movimientos bruscos hacen patinar las llantas.","h2":"Sobre nieve o hielo, haga todo con suavidad: acelere, frene y gire suavemente, maneje más despacio y deje mucho más espacio adelante.","p":"Correcto. Movimientos suaves y más espacio."},"zh":{"q":"在雪地或冰面上应该怎样开车？","o":["轻轻地加速、刹车和转方向，并且留出多得多的空间","用力刹车，试试抓地力","使用定速巡航","快速转弯，保持控制"],"h1":"突然的动作会让轮胎打滑。","h2":"在雪地或冰面上，每个动作都要轻：平稳地加速、刹车和转方向，开慢一点，并在前面留出多得多的空间。","p":"对。动作要轻，空间要多。"},"vi":{"q":"Bạn nên lái xe thế nào trên tuyết hoặc băng?","o":["Tăng tốc, đạp thắng và đánh lái nhẹ nhàng, và chừa khoảng cách xa hơn nhiều","Đạp thắng mạnh để thử độ bám","Dùng chế độ giữ tốc độ (cruise control)","Rẽ nhanh để giữ kiểm soát"],"h1":"Những động tác đột ngột làm bánh xe bị trượt.","h2":"Trên tuyết hoặc băng, hãy làm mọi thứ nhẹ nhàng: tăng tốc, đạp thắng và đánh lái êm, chạy chậm hơn, và chừa khoảng cách phía trước xa hơn nhiều.","p":"Đúng. Động tác nhẹ nhàng và chừa thêm khoảng cách."},"tl":{"q":"Paano ka dapat magmaneho sa niyebe o yelo?","o":["Bumilis, mag-preno at magmaniobra nang marahan, at mag-iwan ng mas malaking espasyo","Mag-preno nang malakas para subukan ang kapit","Gamitin ang cruise control","Lumiko nang mabilis para manatiling kontrolado"],"h1":"Ang biglang galaw ay nagpapadulas sa gulong.","h2":"Sa niyebe o yelo, gawin ang lahat nang marahan: bumilis, mag-preno at magmaniobra nang dahan-dahan, magmaneho nang mas mabagal, at mag-iwan ng mas malaking espasyo sa unahan.","p":"Tama. Marahang galaw at mas maraming espasyo."},"ar":{"q":"كيف يجب أن تقود على الثلج أو الجليد؟","o":["زِد السرعة واضغط الفرامل وأدِر المقود بلطف، واترك مسافة أكبر بكثير","اضغط الفرامل بقوة لتختبر تماسك الإطارات","استخدم مثبّت السرعة (cruise control)","انعطف بسرعة لتبقى مسيطرًا"],"h1":"الحركات المفاجئة تجعل الإطارات تنزلق.","h2":"على الثلج أو الجليد، افعل كل شيء بلطف: زِد السرعة واضغط الفرامل وأدِر المقود بهدوء، وقُد أبطأ، واترك مسافة أكبر بكثير أمامك.","p":"صحيح. حركات لطيفة ومسافة أكبر."},"ht":{"q":"Kijan ou dwe kondui sou lanèj oswa sou glas?","o":["Akselere, frennen epi vire volan an dousman, e kite pi plis espas anpil","Frennen fò pou teste si kawotchou yo kenbe","Sèvi ak kontwòl vitès otomatik (cruise control)","Vire vit pou w rete an kontwòl"],"h1":"Mouvman sibit fè kawotchou yo glise.","h2":"Sou lanèj oswa sou glas, fè tout bagay dousman: akselere, frennen epi vire volan an san sekous, kondui pi dousman, e kite pi plis espas anpil devan w.","p":"Se sa. Mouvman dous ak plis espas."}},{"id":"safe-driving-097","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your car is stuck in deep snow and you run the engine for heat. What must you check?","o":["That the radio works","That the exhaust pipe is clear of snow","That the windows are all shut tight","That the trunk is open"],"h1":"Blocked exhaust can fill the car with a deadly gas.","h2":"If you run the engine while stuck in snow, keep the exhaust pipe clear, because a blocked pipe can fill the car with deadly carbon monoxide.","p":"Right. Keep the exhaust pipe clear."},"es":{"q":"Su carro está atascado en nieve profunda y usted enciende el motor para tener calefacción. ¿Qué debe revisar?","o":["Que el radio funcione","Que el tubo de escape no esté tapado con nieve","Que todas las ventanas estén bien cerradas","Que el maletero esté abierto"],"h1":"Un escape tapado puede llenar el carro de un gas mortal.","h2":"Si enciende el motor estando atascado en la nieve, mantenga libre el tubo de escape, porque si se tapa puede llenar el carro de monóxido de carbono, que es mortal.","p":"Correcto. Mantenga libre el tubo de escape."},"zh":{"q":"你的车陷在深雪里，你开着发动机取暖。你必须检查什么？","o":["收音机能不能用","排气管有没有被雪堵住","车窗是不是全都关紧了","后备箱是不是打开的"],"h1":"排气管堵住，车里可能会充满致命的气体。","h2":"如果你陷在雪里还开着发动机，要让排气管保持畅通，因为排气管堵住会让车里充满致命的一氧化碳。","p":"对。保持排气管畅通。"},"vi":{"q":"Xe bạn bị kẹt trong tuyết sâu và bạn nổ máy để sưởi ấm. Bạn phải kiểm tra điều gì?","o":["Radio có hoạt động không","Ống xả không bị tuyết lấp","Tất cả cửa sổ đã đóng thật kín","Cốp xe đang mở"],"h1":"Ống xả bị nghẹt có thể làm xe đầy khí độc chết người.","h2":"Nếu bạn nổ máy khi bị kẹt trong tuyết, hãy giữ ống xả thông thoáng, vì ống xả bị nghẹt có thể làm xe đầy khí carbon monoxide chết người.","p":"Đúng. Giữ ống xả thông thoáng."},"tl":{"q":"Naipit ang kotse mo sa makapal na niyebe at pinaaandar mo ang makina para mainitan. Ano ang dapat mong tingnan?","o":["Kung gumagana ang radyo","Kung walang niyebeng nakabara sa tambutso","Kung mahigpit na nakasara ang lahat ng bintana","Kung bukas ang trunk"],"h1":"Ang baradong tambutso ay puwedeng magpuno sa kotse ng nakamamatay na gas.","h2":"Kung pinaaandar mo ang makina habang naipit sa niyebe, panatilihing walang bara ang tambutso, dahil ang baradong tambutso ay puwedeng magpuno sa kotse ng nakamamatay na carbon monoxide.","p":"Tama. Panatilihing walang bara ang tambutso."},"ar":{"q":"سيارتك عالقة في ثلج عميق وأنت تشغّل المحرّك للتدفئة. ماذا يجب أن تتأكد منه؟","o":["أن الراديو يعمل","أن أنبوب العادم غير مسدود بالثلج","أن كل النوافذ مغلقة بإحكام","أن صندوق السيارة مفتوح"],"h1":"العادم المسدود قد يملأ السيارة بغاز قاتل.","h2":"إذا شغّلت المحرّك وأنت عالق في الثلج، فأبقِ أنبوب العادم مفتوحًا، لأن الأنبوب المسدود قد يملأ السيارة بغاز أول أكسيد الكربون القاتل.","p":"صحيح. أبقِ أنبوب العادم مفتوحًا."},"ht":{"q":"Machin ou bloke nan lanèj fon epi w ap fè motè a mache pou chalè. Kisa ou dwe tcheke?","o":["Si radyo a mache","Si tiyo echapman an pa bouche ak lanèj","Si tout vitre yo byen fèmen sere","Si kòf machin nan louvri"],"h1":"Yon echapman ki bouche ka plen machin nan ak yon gaz ki ka touye moun.","h2":"Si w ap fè motè a mache pandan w bloke nan lanèj, kenbe tiyo echapman an debouche, paske yon tiyo ki bouche ka plen machin nan ak monoksid kabòn ki ka touye moun.","p":"Se sa. Kenbe tiyo echapman an debouche."}},{"id":"safe-driving-098","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"How deep must moving water be to float many cars?","o":["About 5 feet","About 3 feet","About 12 inches (one foot)","Cars never float"],"h1":"It takes much less water than people think.","h2":"About 12 inches of moving water can float many cars, so never drive into a flooded road: turn around, do not drown.","p":"Right. About one foot of water."},"es":{"q":"¿Qué profundidad debe tener el agua en movimiento para hacer flotar a muchos carros?","o":["Unos 5 pies","Unos 3 pies","Unas 12 pulgadas (un pie)","Los carros nunca flotan"],"h1":"Se necesita mucha menos agua de lo que la gente cree.","h2":"Unas 12 pulgadas de agua en movimiento pueden hacer flotar a muchos carros, así que nunca entre a una vía inundada: dé la vuelta.","p":"Correcto. Más o menos un pie de agua."},"zh":{"q":"流动的水要多深，就能让很多汽车浮起来？","o":["大约 5 英尺","大约 3 英尺","大约 12 英寸（1 英尺）","汽车永远不会浮起来"],"h1":"需要的水比人们想的少得多。","h2":"大约 12 英寸的流动的水就能让很多汽车浮起来，所以千万不要把车开进被水淹的路：掉头回去，别被淹死。","p":"对。大约 1 英尺的水。"},"vi":{"q":"Nước chảy phải sâu bao nhiêu thì có thể làm nhiều xe hơi nổi lên?","o":["Khoảng 5 feet","Khoảng 3 feet","Khoảng 12 inch (một foot)","Xe hơi không bao giờ nổi"],"h1":"Cần ít nước hơn nhiều so với người ta nghĩ.","h2":"Khoảng 12 inch nước chảy có thể làm nhiều xe hơi nổi lên, vì vậy đừng bao giờ lái vào đường bị ngập: hãy quay lại, đừng để bị chết đuối.","p":"Đúng. Khoảng một foot nước."},"tl":{"q":"Gaano kalalim ang umaagos na tubig para lumutang ang maraming kotse?","o":["Mga 5 feet","Mga 3 feet","Mga 12 inches (isang foot)","Hindi kailanman lumulutang ang kotse"],"h1":"Mas kaunting tubig ang kailangan kaysa sa iniisip ng mga tao.","h2":"Mga 12 inches ng umaagos na tubig ay kayang magpalutang ng maraming kotse, kaya huwag kailanman magmaneho sa bahang kalsada: bumalik ka, huwag kang malunod.","p":"Tama. Mga isang foot ng tubig."},"ar":{"q":"كم يجب أن يكون عمق الماء الجاري حتى تطفو سيارات كثيرة؟","o":["حوالي 5 أقدام (feet)","حوالي 3 أقدام (feet)","حوالي 12 بوصة (قدم واحدة)","السيارات لا تطفو أبدًا"],"h1":"يكفي ماء أقل بكثير مما يظن الناس.","h2":"حوالي 12 بوصة من الماء الجاري تكفي لتطفو سيارات كثيرة، لذلك يجب ألّا تقود أبدًا في طريق غمرته المياه: ارجع، ولا تغرق.","p":"صحيح. حوالي قدم واحدة من الماء."},"ht":{"q":"Ki pwofondè dlo k ap koule dwe genyen pou l fè anpil machin flote?","o":["Anviwon 5 pye","Anviwon 3 pye","Anviwon 12 pous (yon pye)","Machin pa janm flote"],"h1":"Sa pran mwens dlo pase sa moun panse anpil.","h2":"Anviwon 12 pous dlo k ap koule ka fè anpil machin flote, kidonk pa janm kondui nan yon wout ki inonde: vire tounen, pa neye.","p":"Se sa. Anviwon yon pye dlo."}},{"id":"safe-driving-099","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Where do you find the right air pressure for your car's tires?","o":["On the side of the tire, as the number to fill to","At any gas station sign","It is the same for every car","On the sticker inside the driver's door or in the owner's manual"],"h1":"The number on the tire is the most it can hold.","h2":"The correct tire pressure is on the sticker in the driver's door frame or in the owner's manual; the number on the tire is the maximum, not the target.","p":"Right. On the door sticker or in the manual."},"es":{"q":"¿Dónde encuentra la presión de aire correcta para las llantas de su carro?","o":["En el costado de la llanta, como la cifra a la que debe inflar","En cualquier letrero de gasolinera","Es igual para todos los carros","En la etiqueta dentro de la puerta del conductor o en el manual del dueño"],"h1":"La cifra en la llanta es lo máximo que aguanta.","h2":"La presión correcta está en la etiqueta del marco de la puerta del conductor o en el manual del dueño; la cifra en la llanta es la máxima, no la recomendada.","p":"Correcto. En la etiqueta de la puerta o en el manual."},"zh":{"q":"你的车的轮胎应该打多少气压，在哪里可以找到？","o":["在轮胎侧面，那个数字就是要打到的气压","在任何加油站的牌子上","每辆车都一样","在司机车门内侧的贴纸上，或在车主手册里"],"h1":"轮胎上的数字是它最多能承受的气压。","h2":"正确的轮胎气压写在司机车门框上的贴纸上，或在车主手册里；轮胎上的数字是最大值，不是应该打到的气压。","p":"对。在车门贴纸上或手册里。"},"vi":{"q":"Bạn tìm áp suất hơi đúng cho bánh xe của mình ở đâu?","o":["Trên hông bánh xe, đó là con số cần bơm tới","Trên bảng hiệu ở bất kỳ trạm xăng nào","Xe nào cũng giống nhau","Trên nhãn dán bên trong cửa người lái hoặc trong sách hướng dẫn của chủ xe"],"h1":"Con số trên bánh xe là mức cao nhất mà nó chịu được.","h2":"Áp suất bánh xe đúng ghi trên nhãn dán ở khung cửa người lái hoặc trong sách hướng dẫn của chủ xe; con số trên bánh xe là mức tối đa, không phải mức cần bơm.","p":"Đúng. Trên nhãn dán ở cửa hoặc trong sách hướng dẫn."},"tl":{"q":"Saan mo makikita ang tamang air pressure para sa mga gulong ng kotse mo?","o":["Sa gilid ng gulong, bilang numerong dapat mong punuin","Sa karatula ng kahit anong gasolinahan","Pare-pareho ito sa lahat ng kotse","Sa sticker sa loob ng pinto ng driver o sa owner's manual"],"h1":"Ang numero sa gulong ay ang pinakamataas na kaya nito.","h2":"Ang tamang tire pressure ay nasa sticker sa frame ng pinto ng driver o sa owner's manual; ang numero sa gulong ay ang maximum, hindi ang target.","p":"Tama. Sa sticker sa pinto o sa manual."},"ar":{"q":"أين تجد ضغط الهواء الصحيح لإطارات سيارتك؟","o":["على جانب الإطار، كرقم يجب أن تملأ إليه","على لافتة أي محطة وقود","هو نفسه لكل السيارات","على الملصق داخل باب السائق أو في دليل المالك"],"h1":"الرقم المكتوب على الإطار هو أقصى ما يتحمّله.","h2":"ضغط الإطارات الصحيح مكتوب على الملصق في إطار باب السائق أو في دليل المالك؛ والرقم المكتوب على الإطار هو الحدّ الأقصى، وليس الضغط المطلوب.","p":"صحيح. على ملصق الباب أو في الدليل."},"ht":{"q":"Ki kote ou jwenn bon presyon lè pou kawotchou machin ou?","o":["Sou kote kawotchou a, se chif pou w gonfle l rive","Sou nenpòt pankat estasyon gaz","Li menm bagay pou tout machin","Sou etikèt ki anndan pòt chofè a oswa nan liv mèt machin nan"],"h1":"Chif ki sou kawotchou a se maksimòm li ka kenbe.","h2":"Bon presyon kawotchou a ekri sou etikèt ki nan ankadreman pòt chofè a oswa nan liv mèt machin nan; chif ki sou kawotchou a se maksimòm, se pa presyon pou w vize a.","p":"Se sa. Sou etikèt pòt la oswa nan liv la."}},{"id":"safe-driving-100","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"When is the best time to check tire pressure?","o":["When the tires are cold, before driving far","Right after a long drive","Only once a year","Only when a tire looks flat"],"h1":"Driving warms the tires and raises the reading.","h2":"Check tire pressure when the tires are cold, before you have driven far, because warm tires give a higher reading.","p":"Right. When the tires are cold."},"es":{"q":"¿Cuál es el mejor momento para revisar la presión de las llantas?","o":["Cuando las llantas están frías, antes de manejar mucho","Justo después de un viaje largo","Solo una vez al año","Solo cuando una llanta se ve desinflada"],"h1":"Manejar calienta las llantas y sube la lectura.","h2":"Revise la presión cuando las llantas están frías, antes de haber manejado mucho, porque las llantas calientes dan una lectura más alta.","p":"Correcto. Cuando las llantas están frías."},"zh":{"q":"什么时候检查轮胎气压最好？","o":["轮胎冷的时候，在开远路之前","刚开完长途之后","一年只检查一次","只在轮胎看起来瘪了的时候"],"h1":"开车会让轮胎变热，读数会变高。","h2":"要在轮胎冷的时候检查气压，也就是还没开远之前，因为热的轮胎读数会偏高。","p":"对。在轮胎冷的时候。"},"vi":{"q":"Khi nào là lúc tốt nhất để kiểm tra áp suất bánh xe?","o":["Khi bánh xe còn nguội, trước khi lái đi xa","Ngay sau một chuyến đi dài","Chỉ một lần mỗi năm","Chỉ khi bánh xe trông bị xẹp"],"h1":"Lái xe làm bánh xe nóng lên và làm số đo cao hơn.","h2":"Hãy kiểm tra áp suất bánh xe khi bánh còn nguội, trước khi bạn lái đi xa, vì bánh xe nóng cho số đo cao hơn.","p":"Đúng. Khi bánh xe còn nguội."},"tl":{"q":"Kailan ang pinakamagandang oras para tingnan ang tire pressure?","o":["Kapag malamig pa ang mga gulong, bago magmaneho nang malayo","Pagkatapos na pagkatapos ng mahabang biyahe","Isang beses lang sa isang taon","Kapag mukhang flat lang ang gulong"],"h1":"Pinaiinit ng pagmamaneho ang mga gulong at pinatataas nito ang reading.","h2":"Tingnan ang tire pressure kapag malamig pa ang mga gulong, bago ka magmaneho nang malayo, dahil mas mataas ang reading ng mainit na gulong.","p":"Tama. Kapag malamig pa ang mga gulong."},"ar":{"q":"ما أفضل وقت لفحص ضغط الإطارات؟","o":["عندما تكون الإطارات باردة، قبل القيادة لمسافة طويلة","مباشرةً بعد رحلة طويلة","مرة واحدة فقط في السنة","فقط عندما يبدو الإطار فارغًا من الهواء"],"h1":"القيادة تُسخّن الإطارات وترفع القراءة.","h2":"افحص ضغط الإطارات عندما تكون باردة، قبل أن تقود مسافة طويلة، لأن الإطارات الساخنة تعطي قراءة أعلى.","p":"صحيح. عندما تكون الإطارات باردة."},"ht":{"q":"Ki pi bon moman pou tcheke presyon kawotchou yo?","o":["Lè kawotchou yo frèt, anvan ou kondui lwen","Touswit apre yon long vwayaj","Yon sèl fwa chak ane sèlman","Sèlman lè yon kawotchou sanble li plat"],"h1":"Kondui chofe kawotchou yo epi fè chif la monte.","h2":"Tcheke presyon kawotchou yo lè yo frèt, anvan ou kondui lwen, paske kawotchou ki cho bay yon chif ki pi wo.","p":"Se sa. Lè kawotchou yo frèt."}},{"id":"safe-driving-101","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Small raised bars run across the grooves of your tire tread. The tread is now even with these bars. What does it mean?","o":["The tires are brand new","The tires are worn out and should be replaced","The tires need more air","The tires are made for snow"],"h1":"These bars are tread wear indicators.","h2":"When the tread is worn down even with the wear bars, the tires no longer grip well, especially on wet roads, and should be replaced.","p":"Right. Time for new tires."},"es":{"q":"Unas pequeñas barras elevadas cruzan las ranuras del dibujo de su llanta. El dibujo ya está al nivel de esas barras. ¿Qué significa?","o":["Que las llantas son nuevas","Que las llantas están gastadas y deben cambiarse","Que les falta aire","Que son llantas para nieve"],"h1":"Estas barras son indicadores de desgaste.","h2":"Cuando el dibujo se gastó hasta el nivel de las barras de desgaste, las llantas ya no se agarran bien, sobre todo en vías mojadas, y deben cambiarse.","p":"Correcto. Es hora de llantas nuevas."},"zh":{"q":"轮胎花纹的沟槽里横着一些凸起的小横条。现在花纹已经磨到和这些横条一样平。这是什么意思？","o":["轮胎是全新的","轮胎已经磨坏了，应该更换","轮胎需要再打气","这是雪地专用轮胎"],"h1":"这些横条是胎纹磨损指示条。","h2":"当胎纹磨到和磨损指示条一样平时，轮胎就抓不稳路面了，特别是在湿路上，应该更换轮胎。","p":"对。该换新轮胎了。"},"vi":{"q":"Có những thanh nhỏ nổi lên chạy ngang qua các rãnh gai bánh xe. Bây giờ gai bánh xe đã mòn bằng với các thanh này. Điều đó có nghĩa là gì?","o":["Bánh xe còn mới tinh","Bánh xe đã mòn và cần được thay","Bánh xe cần bơm thêm hơi","Bánh xe được làm để chạy trên tuyết"],"h1":"Những thanh này là vạch báo mòn gai bánh xe.","h2":"Khi gai bánh xe mòn bằng với các vạch báo mòn, bánh xe không còn bám đường tốt, nhất là trên đường ướt, và cần được thay.","p":"Đúng. Đã đến lúc thay bánh xe mới."},"tl":{"q":"May maliliit na nakaumbok na bar na nakahalang sa mga uka ng tread ng gulong mo. Kapantay na ngayon ng tread ang mga bar na ito. Ano ang ibig sabihin nito?","o":["Bagong-bago ang mga gulong","Pudpod na ang mga gulong at dapat nang palitan","Kailangan ng mga gulong ng dagdag na hangin","Ang mga gulong ay para sa niyebe"],"h1":"Ang mga bar na ito ay tread wear indicators.","h2":"Kapag pudpod na ang tread hanggang kapantay ng wear bars, hindi na maayos ang kapit ng mga gulong, lalo na sa basang kalsada, at dapat na itong palitan.","p":"Tama. Oras na para sa bagong gulong."},"ar":{"q":"توجد قضبان صغيرة بارزة تمتد عرضيًا عبر أخاديد نقشة الإطار. والنقشة الآن صارت بمستوى هذه القضبان. ماذا يعني ذلك؟","o":["الإطارات جديدة تمامًا","الإطارات تآكلت ويجب تغييرها","الإطارات تحتاج إلى هواء أكثر","الإطارات مصنوعة للثلج"],"h1":"هذه القضبان هي مؤشرات تآكل النقشة.","h2":"عندما تتآكل النقشة حتى تصير بمستوى مؤشرات التآكل، لا تعود الإطارات تتماسك جيدًا مع الطريق، خاصةً على الطرق المبلّلة، ويجب تغييرها.","p":"صحيح. حان وقت إطارات جديدة."},"ht":{"q":"Gen ti ba ki leve ki travèse rak kawotchou ou yo. Kounye a, kawotchou a vin ras menm nivo ak ba sa yo. Kisa sa vle di?","o":["Kawotchou yo tou nèf","Kawotchou yo fin ize e ou dwe chanje yo","Kawotchou yo bezwen plis lè","Kawotchou yo fèt pou lanèj"],"h1":"Ba sa yo se endikatè ki montre kawotchou a ize.","h2":"Lè kawotchou a ize jiskaske li ras menm nivo ak ba endikatè yo, kawotchou yo pa kenbe wout la byen ankò, sitou sou wout mouye, e ou dwe chanje yo.","p":"Se sa. Li lè pou kawotchou nèf."}},{"id":"safe-driving-102","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your tires suddenly make a loud rumbling noise from grooves cut in the edge of the road. What does it mean?","o":["Your tire is flat","You must stop right away","You are drifting out of your lane; steer back gently","The road is about to end"],"h1":"Rumble strips are meant to wake you up.","h2":"Rumble strips at the edge or center of the road warn that you are drifting out of your lane, so steer back gently and stay alert.","p":"Right. You are drifting; steer back gently."},"es":{"q":"De repente sus llantas hacen un ruido fuerte por unas ranuras en la orilla de la vía. ¿Qué significa?","o":["Que tiene una llanta desinflada","Que debe pararse enseguida","Que se está saliendo del carril; vuelva con suavidad","Que la vía va a terminar"],"h1":"Las bandas sonoras están hechas para despertarlo.","h2":"Las bandas sonoras en la orilla o el centro de la vía advierten que se está saliendo del carril, así que vuelva con suavidad y manténgase alerta.","p":"Correcto. Se está saliendo; vuelva con suavidad."},"zh":{"q":"你的轮胎突然因为路边刻出的沟槽发出很大的隆隆声。这是什么意思？","o":["你的轮胎瘪了","你必须马上停车","你正偏出你的车道；轻轻地把方向打回来","道路马上就到尽头了"],"h1":"震动带（rumble strips）就是为了让你清醒过来。","h2":"路边或路中间的震动带（rumble strips）是在提醒你正偏出车道，所以要轻轻地把方向打回来，并保持警觉。","p":"对。你正在偏离车道；轻轻打回方向。"},"vi":{"q":"Bánh xe của bạn đột nhiên phát ra tiếng rung ầm ầm lớn từ các rãnh khắc ở mép đường. Điều đó có nghĩa là gì?","o":["Bánh xe của bạn bị xẹp","Bạn phải dừng lại ngay","Bạn đang trôi ra khỏi làn xe; hãy nhẹ nhàng đánh lái trở lại","Con đường sắp hết"],"h1":"Rãnh rung (rumble strips) được làm ra để đánh thức bạn.","h2":"Rãnh rung (rumble strips) ở mép hoặc giữa đường cảnh báo rằng bạn đang trôi ra khỏi làn xe, vì vậy hãy nhẹ nhàng đánh lái trở lại và giữ tỉnh táo.","p":"Đúng. Bạn đang trôi ra; nhẹ nhàng đánh lái trở lại."},"tl":{"q":"Biglang umugong nang malakas ang mga gulong mo dahil sa mga ukang nakaukit sa gilid ng kalsada. Ano ang ibig sabihin nito?","o":["Flat ang gulong mo","Dapat kang huminto agad","Lumalabas ka sa lane mo; marahang ibalik ang manibela","Malapit nang matapos ang kalsada"],"h1":"Ang rumble strips ay ginawa para gisingin ka.","h2":"Ang rumble strips sa gilid o gitna ng kalsada ay babala na lumalabas ka sa lane mo, kaya marahang ibalik ang manibela at manatiling alerto.","p":"Tama. Lumalabas ka; marahang ibalik ang manibela."},"ar":{"q":"فجأةً تُصدر إطاراتك صوت هدير عاليًا من أخاديد محفورة على حافة الطريق. ماذا يعني ذلك؟","o":["إطارك فارغ من الهواء","يجب أن تتوقف فورًا","أنت تنحرف خارج مسارك؛ أعِد المقود بلطف","الطريق سينتهي قريبًا"],"h1":"الأخاديد المنبّهة (rumble strips) موجودة لتوقظك.","h2":"الأخاديد المنبّهة (rumble strips) على حافة الطريق أو في وسطه تحذّرك من أنك تنحرف خارج مسارك، لذلك أعِد المقود بلطف وابقَ منتبهًا.","p":"صحيح. أنت تنحرف؛ أعِد المقود بلطف."},"ht":{"q":"Toudenkou, kawotchou ou yo fè yon gwo bri k ap gwonde akoz rak ki koupe sou bò wout la. Kisa sa vle di?","o":["Kawotchou ou plat","Ou dwe kanpe touswit","W ap glise soti nan liy ou; vire volan an dousman pou w tounen","Wout la pral fini"],"h1":"Bann vibrasyon (rumble strips) yo la pou reveye w.","h2":"Bann vibrasyon (rumble strips) sou bò oswa nan mitan wout la avèti w ke w ap glise soti nan liy ou, kidonk vire volan an dousman pou w tounen epi rete vijilan.","p":"Se sa. W ap glise soti; vire tounen dousman."}},{"id":"safe-driving-103","scope":"US","cat":"safe-driving","sign":null,"c":3,"en":{"q":"What kind of crash is the most common in work zones?","o":["Head-on crashes with trucks","Crashes with trains","Crashes in parking lots","Rear-end crashes, so keep extra space and expect sudden stops"],"h1":"Traffic in work zones often slows or stops without warning.","h2":"Rear-end crashes are the most common in work zones, so leave extra space ahead and be ready for sudden slowdowns.","p":"Right. Rear-end crashes; keep extra space."},"es":{"q":"¿Qué tipo de choque es el más común en las zonas de obras?","o":["Los choques de frente con camiones","Los choques con trenes","Los choques en estacionamientos","Los choques por detrás, así que deje más espacio y espere frenadas repentinas"],"h1":"En las zonas de obras el tráfico muchas veces frena o se para sin aviso.","h2":"Los choques por detrás son los más comunes en las zonas de obras, así que deje más espacio adelante y esté listo para frenadas repentinas.","p":"Correcto. Choques por detrás; deje más espacio."},"zh":{"q":"在施工区，哪种车祸最常见？","o":["与卡车正面相撞","与火车相撞","在停车场发生的车祸","追尾车祸，所以要多留空间，并预料前车会突然停下"],"h1":"施工区的车流常常会毫无预警地变慢或停下。","h2":"追尾车祸在施工区最常见，所以要和前车多留空间，并准备好应对突然减速。","p":"对。追尾车祸；要多留空间。"},"vi":{"q":"Loại tai nạn nào thường xảy ra nhất ở khu vực công trường?","o":["Đâm trực diện với xe tải","Đâm với xe lửa","Tai nạn trong bãi đậu xe","Tông từ phía sau, vì vậy hãy chừa thêm khoảng cách và lường trước việc xe phía trước dừng đột ngột"],"h1":"Xe cộ ở khu vực công trường thường chạy chậm lại hoặc dừng mà không báo trước.","h2":"Tông từ phía sau là loại tai nạn thường xảy ra nhất ở khu vực công trường, vì vậy hãy chừa thêm khoảng cách phía trước và sẵn sàng khi xe chậm lại đột ngột.","p":"Đúng. Tông từ phía sau; hãy chừa thêm khoảng cách."},"tl":{"q":"Anong uri ng banggaan ang pinakakaraniwan sa mga work zone?","o":["Salpukan nang harapan sa mga trak","Banggaan sa mga tren","Banggaan sa mga paradahan","Pagbangga sa likuran, kaya mag-iwan ng dagdag na espasyo at asahan ang biglang paghinto"],"h1":"Ang trapiko sa mga work zone ay madalas bumabagal o humihinto nang walang babala.","h2":"Ang pagbangga sa likuran ang pinakakaraniwang banggaan sa mga work zone, kaya mag-iwan ng dagdag na espasyo sa unahan at maging handa sa biglang pagbagal.","p":"Tama. Pagbangga sa likuran; mag-iwan ng dagdag na espasyo."},"ar":{"q":"ما أكثر نوع من الحوادث يحدث في مناطق أعمال الطرق؟","o":["الاصطدام وجهًا لوجه مع الشاحنات","الاصطدام بالقطارات","الحوادث في مواقف السيارات","الاصطدام من الخلف، لذلك اترك مسافة إضافية وتوقّع التوقف المفاجئ"],"h1":"حركة السير في مناطق أعمال الطرق تبطئ أو تتوقف كثيرًا من دون إنذار.","h2":"الاصطدام من الخلف هو أكثر الحوادث في مناطق أعمال الطرق، لذلك اترك مسافة إضافية أمامك وكن مستعدًا لتخفيف السرعة المفاجئ.","p":"صحيح. الاصطدام من الخلف؛ اترك مسافة إضافية."},"ht":{"q":"Ki kalite aksidan ki rive pi souvan nan zòn travay sou wout?","o":["Frape tèt kole tèt ak kamyon","Aksidan ak tren","Aksidan nan pakin","Frape pa dèyè, kidonk kite plis espas epi atann machin devan an kanpe sanzatann"],"h1":"Nan zòn travay, sikilasyon an souvan ralanti oswa kanpe san avètisman.","h2":"Frape pa dèyè se aksidan ki rive pi souvan nan zòn travay, kidonk kite plis espas devan w epi pare pou machin yo ralanti sanzatann.","p":"Se sa. Frape pa dèyè; kite plis espas."}},{"id":"safe-driving-104","scope":"US","cat":"safe-driving","sign":null,"c":0,"en":{"q":"What does \"defensive driving\" mean?","o":["Expecting others to make mistakes and being ready to avoid them","Driving fast to get away from danger","Never letting anyone merge in front of you","Honking whenever someone is in your way"],"h1":"Plan for other people's errors.","h2":"Defensive driving means watching for hazards, expecting other road users to make mistakes, and leaving yourself time and space to avoid a crash.","p":"Right. Expect mistakes and be ready."},"es":{"q":"¿Qué significa \"manejo defensivo\"?","o":["Esperar que los demás cometan errores y estar listo para evitarlos","Manejar rápido para alejarse del peligro","No dejar nunca que alguien se meta delante","Tocar la bocina cuando alguien estorba"],"h1":"Prepárese para los errores de los demás.","h2":"El manejo defensivo es estar atento a los peligros, esperar que los demás cometan errores y dejarse tiempo y espacio para evitar un choque.","p":"Correcto. Espere errores y esté listo."},"zh":{"q":"\"防御性驾驶\"是什么意思？","o":["预料别人会犯错，并准备好避开","开快车来躲开危险","从不让任何人并到你前面","有人挡路时就按喇叭"],"h1":"要为别人可能犯的错误做好准备。","h2":"防御性驾驶的意思是留意危险，预料其他道路使用者会犯错，并给自己留出时间和空间来避免车祸。","p":"对。预料别人会犯错，并做好准备。"},"vi":{"q":"\"Lái xe phòng thủ\" có nghĩa là gì?","o":["Lường trước người khác sẽ mắc lỗi và sẵn sàng tránh né","Chạy nhanh để thoát khỏi nguy hiểm","Không bao giờ cho ai nhập làn trước mặt bạn","Bấm còi mỗi khi có người cản đường bạn"],"h1":"Hãy chuẩn bị cho lỗi của người khác.","h2":"Lái xe phòng thủ có nghĩa là để ý các mối nguy hiểm, lường trước những người khác trên đường sẽ mắc lỗi, và chừa cho mình thời gian và khoảng cách để tránh tai nạn.","p":"Đúng. Lường trước lỗi và luôn sẵn sàng."},"tl":{"q":"Ano ang ibig sabihin ng \"defensive driving\" (depensibong pagmamaneho)?","o":["Pag-asahan na magkakamali ang iba at maging handang iwasan ang mga ito","Magmaneho nang mabilis para makalayo sa panganib","Huwag kailanman hayaang may sumingit sa harap mo","Bumusina tuwing may humaharang sa daan mo"],"h1":"Maghanda para sa mga pagkakamali ng ibang tao.","h2":"Ang defensive driving ay nangangahulugang pagbabantay sa mga panganib, pag-asahan na magkakamali ang ibang gumagamit ng kalsada, at pagbibigay sa sarili mo ng oras at espasyo para maiwasan ang banggaan.","p":"Tama. Asahan ang mga pagkakamali at maging handa."},"ar":{"q":"ماذا تعني \"القيادة الوقائية\"؟","o":["أن تتوقّع أن يخطئ الآخرون وتكون مستعدًا لتجنّب أخطائهم","أن تقود بسرعة لتبتعد عن الخطر","ألّا تسمح لأحد أبدًا بالدخول أمامك","أن تستعمل البوق كلما وقف أحد في طريقك"],"h1":"خطّط لأخطاء الآخرين.","h2":"القيادة الوقائية تعني أن تنتبه للمخاطر، وتتوقّع أن يخطئ مستخدمو الطريق الآخرون، وتترك لنفسك وقتًا ومسافة لتتجنّب الحادث.","p":"صحيح. توقّع الأخطاء وكن مستعدًا."},"ht":{"q":"Kisa \"kondui defansif\" vle di?","o":["Atann lòt moun fè erè epi pare pou evite yo","Kondui vit pou chape anba danje","Pa janm kite pyès moun antre devan w","Klaksonnen chak fwa yon moun nan wout ou"],"h1":"Prepare w pou erè lòt moun ka fè.","h2":"Kondui defansif vle di veye danje, atann lòt moun ki sou wout la fè erè, epi kite tan ak espas pou tèt ou pou evite yon aksidan.","p":"Se sa. Atann erè epi rete pare."}},{"id":"safe-driving-105","scope":"US","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You are waiting to turn and a person is about to cross in front of you. How can you be sure they know you see them?","o":["Flash your high beams","Make eye contact with the person","Honk loudly","Rev your engine"],"h1":"People feel safer when they know a driver has seen them.","h2":"Making eye contact with people walking, bicycling or driving helps you both know you have seen each other before anyone moves.","p":"Right. Make eye contact."},"es":{"q":"Usted espera para girar y una persona va a cruzar delante de usted. ¿Cómo puede asegurarse de que ella sabe que usted la vio?","o":["Haciendo cambio de luces","Haciendo contacto visual con la persona","Tocando la bocina fuerte","Acelerando el motor"],"h1":"La gente se siente más segura si sabe que el conductor la vio.","h2":"Hacer contacto visual con quien camina, va en bicicleta o maneja ayuda a que ambos sepan que se vieron antes de moverse.","p":"Correcto. Haga contacto visual."},"zh":{"q":"你正在等着转弯，有一个人正要从你前面穿过。你怎样才能确定对方知道你看到了他？","o":["闪远光灯","和这个人进行眼神交流","大声按喇叭","踩油门让引擎轰响"],"h1":"人们知道司机看到了自己，就会觉得更安全。","h2":"和步行、骑自行车或开车的人进行眼神交流，可以让你们在任何人行动之前，都知道彼此已经看到对方。","p":"对。进行眼神交流。"},"vi":{"q":"Bạn đang chờ để rẽ và có một người sắp băng qua trước mặt bạn. Làm sao để chắc chắn họ biết bạn đã thấy họ?","o":["Nháy đèn pha","Nhìn vào mắt người đó","Bấm còi thật to","Rồ máy xe"],"h1":"Người ta cảm thấy an toàn hơn khi biết tài xế đã thấy mình.","h2":"Nhìn vào mắt người đi bộ, người đi xe đạp hoặc người lái xe giúp cả hai bên biết rằng đã thấy nhau trước khi ai đó di chuyển.","p":"Đúng. Nhìn vào mắt người đó."},"tl":{"q":"Naghihintay kang lumiko at may taong tatawid na sa harap mo. Paano mo masisigurong alam niyang nakikita mo siya?","o":["I-flash ang high beams mo","Tumingin sa mata ng tao","Bumusina nang malakas","Paugungin ang makina mo"],"h1":"Mas ligtas ang pakiramdam ng mga tao kapag alam nilang nakita sila ng drayber.","h2":"Ang pagtingin sa mata ng mga naglalakad, nagbibisikleta o nagmamaneho ay tumutulong para malaman ninyong dalawa na nakita na ninyo ang isa't isa bago may gumalaw.","p":"Tama. Tumingin sa mata."},"ar":{"q":"أنت تنتظر لتنعطف، وشخص على وشك أن يعبر أمامك. كيف تتأكد أنه يعرف أنك تراه؟","o":["أومض بالأضواء العالية","انظر في عيني الشخص","استعمل البوق بصوت عالٍ","زِد صوت المحرك بالضغط على البنزين"],"h1":"يشعر الناس بأمان أكبر عندما يعرفون أن السائق رآهم.","h2":"النظر في عيون المشاة وراكبي الدراجات والسائقين يساعدكما معًا على معرفة أن كل واحد منكما رأى الآخر قبل أن يتحرك أحد.","p":"صحيح. انظر في عينيه."},"ht":{"q":"Ou ap tann pou vire epi yon moun pral travèse devan w. Kijan ou ka sèten li konnen ou wè l?","o":["Flache gwo limyè ou yo","Gade moun nan nan je","Klaksonnen fò","Fè motè a gwonde"],"h1":"Moun santi yo plis an sekirite lè yo konnen yon chofè wè yo.","h2":"Gade moun k ap mache, k ap monte bisiklèt oswa k ap kondui nan je ede nou tou de konnen nou wè youn lòt anvan pyès moun deplase.","p":"Se sa. Gade moun nan nan je."}},{"id":"safe-driving-106","scope":"US","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Why is it dangerous to use cruise control on wet or icy roads?","o":["Cruise control uses more gas in the rain","It turns off your headlights","If the tires slip, the car may keep pushing and you may lose control","It is not dangerous"],"h1":"You want full control of the gas pedal when grip is poor.","h2":"On wet or icy roads, cruise control can keep the wheels pushing when they slip, which can make you skid, so control the speed yourself.","p":"Right. It can make a skid worse."},"es":{"q":"¿Por qué es peligroso usar el control de crucero en vías mojadas o con hielo?","o":["Porque gasta más gasolina con lluvia","Porque apaga los faros","Porque si las llantas patinan, el carro puede seguir acelerando y usted puede perder el control","No es peligroso"],"h1":"Con poco agarre, usted quiere controlar el acelerador.","h2":"En vías mojadas o con hielo, el control de crucero puede seguir empujando las ruedas cuando patinan, lo que puede hacerlo derrapar, así que controle usted la velocidad.","p":"Correcto. Puede empeorar un derrape."},"zh":{"q":"为什么在湿滑或结冰的路上使用定速巡航很危险？","o":["下雨时定速巡航更费油","它会关掉你的车头灯","如果轮胎打滑，车可能会继续往前推，你可能会失去控制","这并不危险"],"h1":"路面抓地力差时，你要完全控制油门。","h2":"在湿滑或结冰的路上，车轮打滑时定速巡航会让车轮继续用力，可能让你的车侧滑，所以要自己控制车速。","p":"对。它会让侧滑更严重。"},"vi":{"q":"Tại sao dùng chế độ giữ tốc độ (cruise control) trên đường ướt hoặc đóng băng lại nguy hiểm?","o":["Cruise control tốn xăng hơn khi trời mưa","Nó tắt đèn pha của bạn","Nếu bánh xe bị trượt, xe có thể tiếp tục đẩy tới và bạn có thể mất kiểm soát","Nó không nguy hiểm"],"h1":"Bạn cần kiểm soát hoàn toàn chân ga khi đường trơn.","h2":"Trên đường ướt hoặc đóng băng, cruise control có thể khiến bánh xe tiếp tục đẩy khi bị trượt, làm xe bạn bị trượt bánh, vì vậy hãy tự kiểm soát tốc độ.","p":"Đúng. Nó có thể làm trượt bánh nặng hơn."},"tl":{"q":"Bakit mapanganib gamitin ang cruise control sa basa o nagyeyelong kalsada?","o":["Mas maraming gasolina ang nagagamit ng cruise control kapag umuulan","Pinapatay nito ang mga headlight mo","Kung madulas ang mga gulong, maaaring patuloy na tumulak ang kotse at maaari kang mawalan ng kontrol","Hindi ito mapanganib"],"h1":"Gusto mo ng buong kontrol sa gas pedal kapag madulas ang daan.","h2":"Sa basa o nagyeyelong kalsada, maaaring panatilihing tumutulak ng cruise control ang mga gulong kapag dumudulas ang mga ito, na maaaring magpadulas sa iyo, kaya ikaw mismo ang kumontrol sa bilis.","p":"Tama. Maaari nitong palalain ang pagdulas."},"ar":{"q":"لماذا يكون استعمال مثبّت السرعة (cruise control) خطيرًا على الطرق المبلّلة أو المتجمّدة؟","o":["مثبّت السرعة يستهلك بنزينًا أكثر في المطر","يطفئ المصابيح الأمامية","إذا انزلقت الإطارات قد تستمر السيارة في الدفع وقد تفقد السيطرة","ليس خطيرًا"],"h1":"تحتاج إلى سيطرة كاملة على دوّاسة البنزين عندما يكون الطريق زلقًا.","h2":"على الطرق المبلّلة أو المتجمّدة، قد يُبقي مثبّت السرعة العجلات تدفع عندما تنزلق، وهذا قد يجعل سيارتك تنزلق، لذلك تحكّم في السرعة بنفسك.","p":"صحيح. قد يجعل الانزلاق أسوأ."},"ht":{"q":"Poukisa li danjere pou itilize kontwòl vitès otomatik (cruise control) sou wout mouye oswa ki gen glas?","o":["Cruise control boule plis gaz lè lapli ap tonbe","Li etenn limyè devan ou yo","Si kawotchou yo glise, machin nan ka kontinye pouse epi ou ka pèdi kontwòl","Li pa danjere"],"h1":"Ou bezwen kontwole pedal gaz la nèt lè wout la glise.","h2":"Sou wout mouye oswa ki gen glas, cruise control ka kenbe wou yo ap pouse lè yo glise, sa ka fè machin ou derape, kidonk kontwole vitès la ou menm.","p":"Se sa. Li ka fè derapaj la vin pi grav."}},{"id":"safe-driving-107","scope":"FL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Florida, who may ride a motorcycle without a helmet?","o":["Any rider who is 16 or older","Any rider on roads under 45 mph","Any rider with a car driver license","Riders over 21 with $10,000 medical coverage"],"h1":"Two things are needed: age and insurance.","h2":"A motorcycle rider in Florida may go without a helmet only if over 21 and covered by at least $10,000 in medical insurance.","p":"Right. Over 21 and $10,000 in medical coverage, or wear a helmet."},"es":{"q":"En Florida, ¿quién puede andar en motocicleta sin casco?","o":["Cualquiera de 16 años o más","Cualquiera en calles de menos de 45 mph","Cualquiera con licencia de carro","Mayores de 21 con $10,000 de seguro médico"],"h1":"Se necesitan dos cosas: la edad y un seguro.","h2":"En Florida, un motociclista puede ir sin casco solo si tiene más de 21 años y un seguro médico de al menos $10,000.","p":"Correcto. Más de 21 años y $10,000 de seguro médico, o debe usar casco."},"ref":{"doc":"FL","page":87}},{"id":"safe-driving-108","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, which bicycle riders must wear a helmet by law?","o":["Riders and passengers under 16","Riders under 12 only","All riders of every age","Only riders on the sidewalk"],"h1":"The rule is for young riders and passengers.","h2":"Florida law requires bicycle riders and passengers under age 16 to wear a helmet that meets federal safety standards.","p":"Right. Under 16 on a bike means a helmet."},"es":{"q":"En Florida, ¿qué ciclistas deben usar casco por ley?","o":["Ciclistas y pasajeros menores de 16","Solo los menores de 12 años","Todos los ciclistas de cualquier edad","Solo los que van por la acera"],"h1":"La regla es para ciclistas y pasajeros jóvenes.","h2":"La ley de Florida exige que los ciclistas y pasajeros menores de 16 años usen un casco que cumpla con las normas federales de seguridad.","p":"Correcto. Menores de 16 en bicicleta deben usar casco."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-109","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, what is the minimum tread depth your tires should have?","o":["1/32 of an inch","1/16 of an inch","3/32 of an inch","1/2 of an inch"],"h1":"It is a little less than 1/8 of an inch.","h2":"Florida requires tires to have at least 3/32 of an inch of tread, with no worn spots that show the ply.","p":"Right. Tires need at least 3/32 of an inch of tread."},"es":{"q":"En Florida, ¿cuál es la profundidad mínima de la banda de rodadura que deben tener sus llantas?","o":["1/32 de pulgada","1/16 de pulgada","3/32 de pulgada","1/2 pulgada"],"h1":"Es un poco menos de 1/8 de pulgada.","h2":"Florida exige que las llantas tengan al menos 3/32 de pulgada de banda de rodadura, sin partes gastadas que muestren las capas internas.","p":"Correcto. Las llantas necesitan al menos 3/32 de pulgada de banda de rodadura."},"ref":{"doc":"FL","page":38}},{"id":"safe-driving-110","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, you park at night on the shoulder of a road outside a city or town. Which lights must be on?","o":["No lights","Your parking lights","Your high beams","Your interior lights"],"h1":"They are small lights that help others see your car.","h2":"Florida law says to turn on your parking lights at night when you park on a road or shoulder outside cities and towns.","p":"Right. Parking lights on when you park on a rural road at night."},"es":{"q":"En Florida, usted se estaciona de noche en el acotamiento de una carretera fuera de una ciudad o pueblo. ¿Qué luces debe tener encendidas?","o":["Ninguna luz","Sus luces de estacionamiento","Sus luces altas","Las luces de adentro del carro"],"h1":"Son luces pequeñas que ayudan a otros a ver su carro.","h2":"La ley de Florida dice que debe encender las luces de estacionamiento de noche cuando se estaciona en una carretera o acotamiento fuera de ciudades y pueblos.","p":"Correcto. Luces de estacionamiento encendidas al estacionarse de noche en una carretera rural."},"ref":{"doc":"FL","page":73}},{"id":"safe-driving-111","scope":"FL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Florida, may you drive while wearing headphones over both ears to listen to music?","o":["Yes, at any time","Yes, but only on highways","No, drivers may not wear headphones","Yes, if the volume is low"],"h1":"You need to hear horns and sirens around you.","h2":"In Florida, drivers may not wear headsets or headphones while driving.","p":"Right. Florida does not allow drivers to wear headphones."},"es":{"q":"En Florida, ¿puede manejar con audífonos en los dos oídos para escuchar música?","o":["Sí, en cualquier momento","Sí, pero solo en las autopistas","No, los conductores no pueden usar audífonos","Sí, si el volumen está bajo"],"h1":"Usted necesita oír las bocinas y sirenas a su alrededor.","h2":"En Florida, los conductores no pueden usar audífonos mientras manejan.","p":"Correcto. Florida no permite que los conductores usen audífonos."},"ref":{"doc":"FL","page":39}},{"id":"safe-driving-112","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, your load sticks out more than 4 feet behind your vehicle. During the day, how must you mark its end?","o":["Red flags, 18 inches square","A small white rag","Hazard lights only","A blue ribbon"],"h1":"The marker must be large and a warning color.","h2":"In Florida, a load that sticks out more than 4 feet past the rear must be marked during the day with red flags at least 18 inches square.","p":"Right. By day, use red flags at least 18 inches square."},"es":{"q":"En Florida, su carga sobresale más de 4 pies por detrás de su vehículo. Durante el día, ¿cómo debe marcar el extremo?","o":["Con banderas rojas de 18 pulgadas por lado","Con un trapo blanco pequeño","Solo con las luces intermitentes","Con una cinta azul"],"h1":"La marca debe ser grande y de un color de advertencia.","h2":"En Florida, una carga que sobresale más de 4 pies por detrás debe marcarse de día con banderas rojas de al menos 18 pulgadas por lado.","p":"Correcto. De día, use banderas rojas de al menos 18 pulgadas por lado."},"ref":{"doc":"FL","page":42}},{"id":"safe-driving-113","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, how many bicycle riders may ride side by side in a traffic lane?","o":["Only one; always single file","No more than two","Up to three","Up to four"],"h1":"A pair is the limit, and they must ride single file if they hold up traffic.","h2":"In Florida, bicycle riders may not ride more than two side by side in a traffic lane, and must ride single file if they are holding up traffic.","p":"Right. No more than two bicycle riders side by side."},"es":{"q":"En Florida, ¿cuántos ciclistas pueden ir uno al lado del otro en un carril de tránsito?","o":["Solo uno; siempre en fila","No más de dos","Hasta tres","Hasta cuatro"],"h1":"Una pareja es el límite, y deben ir en fila si detienen el tránsito.","h2":"En Florida, los ciclistas no pueden ir más de dos uno al lado del otro en un carril de tránsito, y deben ir en fila si están deteniendo el tránsito.","p":"Correcto. No más de dos ciclistas uno al lado del otro."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-114","scope":"FL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Florida, a bicycle is ridden after sunset. What light must it have on the front?","o":["A white light seen from 500 feet","A red light seen from 100 feet","A blue flashing light","A yellow light seen from 50 feet"],"h1":"The front light is the same color as a car's headlights.","h2":"In Florida, a bicycle ridden between sunset and sunrise must have a white front light visible from 500 feet, plus a red rear light and reflector visible from 600 feet.","p":"Right. A bike at night needs a white front light seen from 500 feet."},"es":{"q":"En Florida, se maneja una bicicleta después de la puesta del sol. ¿Qué luz debe tener adelante?","o":["Una luz blanca visible a 500 pies","Una luz roja visible a 100 pies","Una luz azul intermitente","Una luz amarilla visible a 50 pies"],"h1":"La luz delantera es del mismo color que los faros de un carro.","h2":"En Florida, una bicicleta que se usa entre la puesta y la salida del sol debe tener una luz blanca delantera visible a 500 pies, además de una luz roja y un reflector traseros visibles a 600 pies.","p":"Correcto. De noche, la bicicleta necesita una luz blanca delantera visible a 500 pies."},"ref":{"doc":"FL","page":82}},{"id":"safe-driving-115","scope":"FL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Florida, a large group of bicycle riders comes to a full stop at a stop sign. How many may then ride through together?","o":["Only one at a time","Groups of 10 or fewer","Groups of 25 or fewer","The whole group at once"],"h1":"The law allows small groups, not the whole crowd.","h2":"In Florida, after a full stop at a stop sign, bicycle riders in a group may go through in groups of 10 or fewer, and drivers must let one such group go before moving.","p":"Right. Bicycle riders may cross in groups of 10 or fewer after stopping."},"es":{"q":"En Florida, un grupo grande de ciclistas hace un alto total en una señal de PARE. ¿Cuántos pueden pasar juntos después?","o":["Solo uno a la vez","Grupos de 10 o menos","Grupos de 25 o menos","Todo el grupo a la vez"],"h1":"La ley permite grupos pequeños, no a todo el grupo.","h2":"En Florida, después de un alto total en una señal de PARE, los ciclistas en grupo pueden pasar en grupos de 10 o menos, y los conductores deben dejar pasar a uno de esos grupos antes de avanzar.","p":"Correcto. Los ciclistas pueden cruzar en grupos de 10 o menos después de parar."},"ref":{"doc":"FL","page":null}},{"id":"signals-001","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What does a steady red traffic light mean?","o":["Slow down and go if no one is coming","Stop only if a police officer is there","Stop and stay stopped until it is safe and legal to go","Speed up to clear the intersection"],"h1":"Think about the strongest color on a traffic light.","h2":"A steady red light means you must stop and stay stopped, because cross traffic has the right to go.","p":"Right. A steady red light means stop and wait."},"es":{"q":"¿Qué significa una luz roja fija en el semáforo?","o":["Baje la velocidad y siga si no viene nadie","Pare solo si hay un policía","Pare y quédese parado hasta que sea seguro y legal seguir","Acelere para salir de la intersección"],"h1":"Piense en el color más fuerte del semáforo.","h2":"Una luz roja fija significa que usted debe parar y quedarse parado, porque el tráfico que cruza tiene el derecho a pasar.","p":"Correcto. Una luz roja fija significa pare y espere."},"zh":{"q":"一直亮着的红灯是什么意思？","o":["减速，没有来车就走","只有警察在场时才停","停车，一直停到安全且合法时再走","加速，快快开过路口"],"h1":"想一想：红绿灯上最强烈的颜色。","h2":"一直亮着的红灯表示你必须停车并保持停住，因为横向的车有权通行。","p":"对。一直亮着的红灯表示停车等待。"},"vi":{"q":"Đèn đỏ sáng đứng yên (không nhấp nháy) có nghĩa là gì?","o":["Chạy chậm lại và đi nếu không có ai tới","Chỉ dừng nếu có cảnh sát ở đó","Dừng lại và đứng yên tới khi được đi an toàn và đúng luật","Tăng tốc để qua khỏi giao lộ"],"h1":"Hãy nghĩ đến màu mạnh nhất trên đèn giao thông.","h2":"Đèn đỏ sáng đứng yên nghĩa là bạn phải dừng lại và đứng yên, vì xe ở hướng cắt ngang đang được quyền đi.","p":"Đúng rồi. Đèn đỏ sáng đứng yên nghĩa là dừng lại và chờ."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na pulang ilaw trapiko?","o":["Bumagal at umandar kung walang dumarating","Huminto lang kung may pulis doon","Huminto at manatiling nakahinto hanggang ligtas at legal nang umandar","Bumilis para malampasan ang interseksyon"],"h1":"Isipin ang pinakamalakas na kulay sa ilaw trapiko.","h2":"Ang tuloy-tuloy na pulang ilaw ay nangangahulugang dapat kang huminto at manatiling nakahinto, dahil ang trapiko sa kabilang daan ang may karapatang umandar.","p":"Tama. Ang tuloy-tuloy na pulang ilaw ay nangangahulugang huminto at maghintay."},"ar":{"q":"ماذا يعني الضوء الأحمر الثابت في إشارة المرور؟","o":["خفف السرعة وانطلق إذا لم يأتِ أحد","توقف فقط إذا كان هناك شرطي","توقف وابقَ متوقفًا حتى يصبح الانطلاق آمنًا ومسموحًا","زد السرعة لتخرج من التقاطع"],"h1":"فكّر في أقوى لون في إشارة المرور.","h2":"الضوء الأحمر الثابت يعني أنه يجب أن تتوقف وتبقى متوقفًا، لأن السيارات في الاتجاه المتقاطع لها الحق في المرور.","p":"صحيح. الضوء الأحمر الثابت يعني: توقف وانتظر."},"ht":{"q":"Kisa yon limyè trafik wouj fiks vle di?","o":["Ralanti epi pase si pa gen moun k ap vini","Kanpe sèlman si gen yon polis la","Kanpe epi rete kanpe jiskaske li an sekirite epi lalwa pèmèt ou pase","Akselere pou kite kafou a"],"h1":"Panse ak koulè ki pi fò sou yon limyè trafik.","h2":"Yon limyè wouj fiks vle di ou dwe kanpe epi rete kanpe, paske machin ki sou lòt lari a gen dwa pou pase.","p":"Se sa. Yon limyè wouj fiks vle di kanpe epi tann."},"ref":{"doc":"FL","page":51}},{"id":"signals-002","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"The light turns steady yellow as you come near. What should you do?","o":["Stop if you can do it safely","Speed up to beat the red light","Stop suddenly, no matter what","Keep going at the same speed always"],"h1":"Yellow is a warning. Think about what color comes next.","h2":"A steady yellow light warns that the light will soon turn red, so you should stop if you can do it safely.","p":"Right. Steady yellow means red is coming, so stop if it is safe."},"es":{"q":"La luz cambia a amarillo fijo cuando usted se acerca. ¿Qué debe hacer?","o":["Parar si lo puede hacer con seguridad","Acelerar para pasar antes de la roja","Frenar de golpe, pase lo que pase","Seguir siempre a la misma velocidad"],"h1":"El amarillo es una advertencia. Piense qué color viene después.","h2":"Una luz amarilla fija avisa que pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Amarillo fijo significa que viene la roja, así que pare si es seguro."},"zh":{"q":"你快到路口时，灯变成一直亮着的黄灯。你应该怎么做？","o":["如果能安全停下，就停车","加速，抢在红灯前过去","不管怎样都马上急停","总是保持同样的速度继续开"],"h1":"黄灯是警告。想一想接下来是什么颜色。","h2":"一直亮着的黄灯提醒你马上要变红灯，所以如果能安全停下，你就应该停车。","p":"对。黄灯表示红灯要来了，安全的话就停车。"},"vi":{"q":"Khi bạn tới gần, đèn chuyển sang vàng sáng đứng yên. Bạn nên làm gì?","o":["Dừng lại nếu bạn có thể dừng an toàn","Tăng tốc để qua trước khi đèn đỏ","Dừng gấp, dù thế nào đi nữa","Lúc nào cũng giữ nguyên tốc độ mà chạy tiếp"],"h1":"Màu vàng là lời cảnh báo. Hãy nghĩ xem màu nào sẽ tới sau đó.","h2":"Đèn vàng sáng đứng yên cảnh báo rằng đèn sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Đèn vàng nghĩa là sắp đỏ, nên hãy dừng nếu an toàn."},"tl":{"q":"Naging tuloy-tuloy na dilaw ang ilaw habang papalapit ka. Ano ang dapat mong gawin?","o":["Huminto kung kaya mong gawin ito nang ligtas","Bumilis para maunahan ang pulang ilaw","Huminto nang biglaan, kahit ano pa ang mangyari","Magpatuloy sa parehong bilis palagi"],"h1":"Ang dilaw ay isang babala. Isipin kung anong kulay ang susunod.","h2":"Ang tuloy-tuloy na dilaw na ilaw ay babala na malapit nang maging pula ang ilaw, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw ay nangangahulugang paparating na ang pula, kaya huminto kung ligtas."},"ar":{"q":"الإشارة تصبح صفراء ثابتة وأنت تقترب. ماذا يجب أن تفعل؟","o":["توقف إذا استطعت أن تفعل ذلك بأمان","زد السرعة لتسبق الضوء الأحمر","توقف فجأة مهما كان الوضع","استمر بنفس السرعة دائمًا"],"h1":"الأصفر تحذير. فكّر في اللون الذي يأتي بعده.","h2":"الضوء الأصفر الثابت يحذّر من أن الإشارة ستصبح حمراء قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. الأصفر الثابت يعني أن الأحمر قادم، لذلك توقف إذا كان ذلك آمنًا."},"ht":{"q":"Limyè a vin jòn fiks pandan w ap pwoche. Kisa ou dwe fè?","o":["Kanpe si ou ka fè l an sekirite","Akselere pou pase anvan limyè wouj la","Kanpe sèk, kèlkeswa sa k rive","Toujou kontinye ak menm vitès la"],"h1":"Jòn se yon avètisman. Panse ak ki koulè ki vini apre.","h2":"Yon limyè jòn fiks avèti ou limyè a pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Jòn fiks vle di wouj ap vini, kidonk kanpe si sa an sekirite."},"ref":{"doc":"FL","page":51}},{"id":"signals-003","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You are already in the intersection when the light turns yellow. What should you do?","o":["Stop in the middle of the intersection","Back up to the stop line","Turn around in the intersection","Carefully finish going through the intersection"],"h1":"Think about where it is safest for your car to be when the light turns red.","h2":"If you are already in the intersection when the light turns yellow, you should carefully keep going, because stopping there would block traffic.","p":"Right. If you are already in the intersection, carefully clear it."},"es":{"q":"Usted ya está dentro de la intersección cuando la luz cambia a amarillo. ¿Qué debe hacer?","o":["Parar en medio de la intersección","Dar marcha atrás hasta la línea de pare","Dar la vuelta dentro de la intersección","Terminar de cruzar la intersección con cuidado"],"h1":"Piense dónde es más seguro estar cuando la luz cambie a roja.","h2":"Si usted ya está dentro de la intersección cuando la luz cambia a amarillo, debe seguir con cuidado, porque parar ahí bloquearía el tráfico.","p":"Correcto. Si ya está dentro de la intersección, termine de cruzar con cuidado."},"zh":{"q":"灯变黄时，你已经在路口里面了。你应该怎么做？","o":["停在路口中间","倒车回到停车线","在路口里掉头","小心地继续开出路口"],"h1":"想一想：变红灯时，你的车在哪里最安全。","h2":"如果灯变黄时你已经在路口里面，你应该小心地继续开，因为停在那里会挡住交通。","p":"对。如果你已经在路口里，就小心地开出去。"},"vi":{"q":"Bạn đã ở trong giao lộ thì đèn chuyển sang vàng. Bạn nên làm gì?","o":["Dừng lại ở giữa giao lộ","Lùi xe về vạch dừng","Quay đầu xe trong giao lộ","Cẩn thận chạy tiếp cho qua hết giao lộ"],"h1":"Hãy nghĩ xem xe bạn ở đâu là an toàn nhất khi đèn chuyển sang đỏ.","h2":"Nếu bạn đã ở trong giao lộ khi đèn chuyển sang vàng, bạn cần cẩn thận chạy tiếp, vì dừng ở đó sẽ chắn đường xe khác.","p":"Đúng rồi. Nếu bạn đã ở trong giao lộ, hãy cẩn thận chạy qua cho hết."},"tl":{"q":"Nasa loob ka na ng interseksyon nang maging dilaw ang ilaw. Ano ang dapat mong gawin?","o":["Huminto sa gitna ng interseksyon","Umatras pabalik sa stop line","Umikot pabalik sa loob ng interseksyon","Maingat na tapusin ang pagdaan sa interseksyon"],"h1":"Isipin kung saan pinakaligtas ang sasakyan mo kapag naging pula ang ilaw.","h2":"Kung nasa loob ka na ng interseksyon nang maging dilaw ang ilaw, dapat kang magpatuloy nang maingat, dahil kapag huminto ka doon ay haharangan mo ang trapiko.","p":"Tama. Kung nasa loob ka na ng interseksyon, maingat na lumabas dito."},"ar":{"q":"أنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء. ماذا يجب أن تفعل؟","o":["توقف في وسط التقاطع","ارجع إلى الخلف حتى خط التوقف","استدر عائدًا داخل التقاطع","أكمل عبور التقاطع بحذر"],"h1":"فكّر في أكثر مكان آمن لسيارتك عندما تصبح الإشارة حمراء.","h2":"إذا كنت داخل التقاطع بالفعل عندما تصبح الإشارة صفراء، يجب أن تكمل طريقك بحذر، لأن توقفك هناك سيغلق الطريق أمام السيارات.","p":"صحيح. إذا كنت داخل التقاطع بالفعل، اخرج منه بحذر."},"ht":{"q":"Ou deja nan kafou a lè limyè a vin jòn. Kisa ou dwe fè?","o":["Kanpe nan mitan kafou a","Fè bak jiska liy pou kanpe a","Vire tounen nan kafou a","Fini travèse kafou a avèk prekosyon"],"h1":"Panse ki kote li pi an sekirite pou machin ou ye lè limyè a vin wouj.","h2":"Si ou deja nan kafou a lè limyè a vin jòn, ou dwe kontinye avèk prekosyon, paske si ou kanpe la a ou ta bloke trafik la.","p":"Se sa. Si ou deja nan kafou a, fini travèse l avèk prekosyon."},"ref":{"doc":"FL","page":51}},{"id":"signals-004","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing red light mean?","o":["Slow down, but you do not need to stop","Stop fully, then go when the way is clear","The light is about to turn green","Only trucks must stop"],"h1":"A flashing red light works like a sign you already know.","h2":"A flashing red light works like a stop sign, so you must stop fully and then go when the way is clear.","p":"Right. A flashing red light means stop, then go when safe."},"es":{"q":"¿Qué significa una luz roja intermitente?","o":["Baje la velocidad, pero no tiene que parar","Pare por completo y luego siga cuando el camino esté libre","La luz está por cambiar a verde","Solo los camiones deben parar"],"h1":"Una luz roja intermitente funciona como una señal que usted ya conoce.","h2":"Una luz roja intermitente funciona como una señal de pare, así que usted debe parar por completo y luego seguir cuando el camino esté libre.","p":"Correcto. Luz roja intermitente significa pare y luego siga cuando sea seguro."},"zh":{"q":"闪烁的红灯是什么意思？","o":["减速，但不用停车","完全停车，没车时再走","灯马上要变绿了","只有卡车要停"],"h1":"闪烁的红灯和一个你已经知道的标志作用一样。","h2":"闪烁的红灯和停车标志作用一样，所以你必须完全停车，没车时再走。","p":"对。闪烁的红灯表示停车，安全时再走。"},"vi":{"q":"Đèn đỏ nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại, nhưng không cần dừng","Dừng hẳn, rồi đi khi đường đã trống","Đèn sắp chuyển sang xanh","Chỉ xe tải phải dừng"],"h1":"Đèn đỏ nhấp nháy giống như một biển báo bạn đã biết.","h2":"Đèn đỏ nhấp nháy giống như biển “STOP” (Dừng lại), nên bạn phải dừng hẳn rồi mới đi khi đường đã trống.","p":"Đúng rồi. Đèn đỏ nhấp nháy nghĩa là dừng lại, rồi đi khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na pulang ilaw?","o":["Bumagal, pero hindi mo kailangang huminto","Huminto nang buo, saka umandar kapag maluwag na ang daan","Malapit nang maging berde ang ilaw","Mga trak lang ang dapat huminto"],"h1":"Ang kumikislap na pulang ilaw ay gumagana na parang karatula na kilala mo na.","h2":"Ang kumikislap na pulang ilaw ay gumagana na parang “STOP” sign, kaya dapat kang huminto nang buo at saka umandar kapag maluwag na ang daan.","p":"Tama. Ang kumikislap na pulang ilaw ay nangangahulugang huminto, saka umandar kapag ligtas."},"ar":{"q":"ماذا يعني الضوء الأحمر الوامض؟","o":["خفف السرعة، لكن لا تحتاج إلى التوقف","توقف تمامًا، ثم انطلق عندما يكون الطريق خاليًا","الإشارة ستصبح خضراء بعد قليل","الشاحنات فقط يجب أن تتوقف"],"h1":"الضوء الأحمر الوامض يعمل مثل لافتة تعرفها بالفعل.","h2":"الضوء الأحمر الوامض يعمل مثل لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ثم تنطلق عندما يكون الطريق خاليًا.","p":"صحيح. الضوء الأحمر الوامض يعني: توقف، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Kisa yon limyè wouj k ap kliyote vle di?","o":["Ralanti, men ou pa bezwen kanpe","Kanpe nèt, epi pase lè wout la lib","Limyè a pral vin vèt talè","Se sèlman kamyon ki dwe kanpe"],"h1":"Yon limyè wouj k ap kliyote mache tankou yon siy ou deja konnen.","h2":"Yon limyè wouj k ap kliyote mache tankou yon siy “STOP”, kidonk ou dwe kanpe nèt epi pase lè wout la lib.","p":"Se sa. Yon limyè wouj k ap kliyote vle di kanpe, epi pase lè sa an sekirite."},"ref":{"doc":"FL","page":52}},{"id":"signals-005","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a flashing yellow light mean?","o":["Slow down and go ahead with care","Stop fully and wait for green","The road is closed ahead","You must turn right"],"h1":"A flashing yellow light is a warning, not an order to stop.","h2":"A flashing yellow light means you should slow down and go ahead with care, because there may be danger ahead.","p":"Right. A flashing yellow light means slow down and be careful."},"es":{"q":"¿Qué significa una luz amarilla intermitente?","o":["Baje la velocidad y siga con cuidado","Pare por completo y espere la verde","La calle está cerrada más adelante","Usted debe girar a la derecha"],"h1":"Una luz amarilla intermitente es una advertencia, no una orden de parar.","h2":"Una luz amarilla intermitente significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber peligro más adelante.","p":"Correcto. Luz amarilla intermitente significa baje la velocidad y tenga cuidado."},"zh":{"q":"闪烁的黄灯是什么意思？","o":["减速，小心往前开","完全停车，等绿灯","前方道路封闭","你必须右转"],"h1":"闪烁的黄灯是警告，不是要你停车。","h2":"闪烁的黄灯表示你应该减速，小心往前开，因为前方可能有危险。","p":"对。闪烁的黄灯表示减速，要小心。"},"vi":{"q":"Đèn vàng nhấp nháy có nghĩa là gì?","o":["Chạy chậm lại và đi tiếp một cách cẩn thận","Dừng hẳn và chờ đèn xanh","Phía trước đường bị đóng","Bạn phải rẽ phải"],"h1":"Đèn vàng nhấp nháy là lời cảnh báo, không phải lệnh dừng.","h2":"Đèn vàng nhấp nháy nghĩa là bạn cần chạy chậm lại và đi tiếp một cách cẩn thận, vì phía trước có thể có nguy hiểm.","p":"Đúng rồi. Đèn vàng nhấp nháy nghĩa là chạy chậm và cẩn thận."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na ilaw?","o":["Bumagal at magpatuloy nang maingat","Huminto nang buo at hintayin ang berde","Sarado ang kalsada sa unahan","Dapat kang kumanan"],"h1":"Ang kumikislap na dilaw na ilaw ay babala, hindi utos na huminto.","h2":"Ang kumikislap na dilaw na ilaw ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may panganib sa unahan.","p":"Tama. Ang kumikislap na dilaw na ilaw ay nangangahulugang bumagal at mag-ingat."},"ar":{"q":"ماذا يعني الضوء الأصفر الوامض؟","o":["خفف السرعة وتابع بحذر","توقف تمامًا وانتظر الأخضر","الطريق مغلق في الأمام","يجب أن تنعطف يمينًا"],"h1":"الضوء الأصفر الوامض تحذير، وليس أمرًا بالتوقف.","h2":"الضوء الأصفر الوامض يعني أنه يجب أن تخفف السرعة وتتابع بحذر، لأنه قد يكون هناك خطر في الأمام.","p":"صحيح. الضوء الأصفر الوامض يعني: خفف السرعة وكن حذرًا."},"ht":{"q":"Kisa yon limyè jòn k ap kliyote vle di?","o":["Ralanti epi kontinye avèk prekosyon","Kanpe nèt epi tann limyè vèt la","Wout la fèmen pi devan","Ou dwe vire adwat"],"h1":"Yon limyè jòn k ap kliyote se yon avètisman, se pa yon lòd pou kanpe.","h2":"Yon limyè jòn k ap kliyote vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen danje pi devan.","p":"Se sa. Yon limyè jòn k ap kliyote vle di ralanti epi fè atansyon."},"ref":{"doc":"FL","page":52}},{"id":"signals-006","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"The light is steady green. A person is still crossing in the crosswalk. What should you do?","o":["Go, because green gives you the right of way","Honk so the person moves faster","Wait and let the person finish crossing","Drive around the person"],"h1":"A green light lets you go, but think about who was there first.","h2":"A green light lets you go only when the way is clear, so you must wait for people and cars that are already in the intersection.","p":"Right. On green, you still let people finish crossing."},"es":{"q":"La luz está en verde fijo. Una persona todavía está cruzando por el paso peatonal. ¿Qué debe hacer?","o":["Seguir, porque la verde le da el derecho de paso","Tocar la bocina para que la persona se apure","Esperar y dejar que la persona termine de cruzar","Pasar por un lado de la persona"],"h1":"La luz verde le permite seguir, pero piense en quién estaba ahí primero.","h2":"La luz verde le permite seguir solo cuando el camino está libre, así que usted debe esperar a las personas y los carros que ya están en la intersección.","p":"Correcto. Con luz verde, igual deje que las personas terminen de cruzar."},"zh":{"q":"灯是一直亮着的绿灯。有一个人还在人行横道上过马路。你应该怎么做？","o":["开走，因为绿灯给你优先通行权","按喇叭让那个人走快点","等一等，让那个人走完","绕过那个人开过去"],"h1":"绿灯让你走，但想一想谁先在那里。","h2":"绿灯只有在路上没有人和车时才让你走，所以你必须等已经在路口里的行人和车辆。","p":"对。绿灯时，你仍然要让行人走完。"},"vi":{"q":"Đèn xanh sáng đứng yên. Có một người vẫn đang đi qua vạch qua đường. Bạn nên làm gì?","o":["Cứ đi, vì đèn xanh cho bạn quyền đi trước","Bấm còi để người đó đi nhanh hơn","Chờ và để người đó đi qua hết","Chạy vòng qua người đó"],"h1":"Đèn xanh cho bạn đi, nhưng hãy nghĩ xem ai đã ở đó trước.","h2":"Đèn xanh chỉ cho bạn đi khi đường đã trống, nên bạn phải chờ người đi bộ và xe đang ở trong giao lộ.","p":"Đúng rồi. Khi đèn xanh, bạn vẫn phải để người đi bộ qua hết."},"tl":{"q":"Tuloy-tuloy na berde ang ilaw. May tao pang tumatawid sa tawiran. Ano ang dapat mong gawin?","o":["Umandar, dahil ang berde ay nagbibigay sa iyo ng karapatang mauna","Bumusina para bilisan ng tao ang paglakad","Maghintay at hayaang matapos ng tao ang pagtawid","Lumihis paikot sa tao"],"h1":"Pinapayagan ka ng berdeng ilaw na umandar, pero isipin kung sino ang naunang nandoon.","h2":"Pinapayagan ka ng berdeng ilaw na umandar lang kapag maluwag na ang daan, kaya dapat mong hintayin ang mga tao at sasakyang nasa loob na ng interseksyon.","p":"Tama. Kahit berde, hayaan mo pa ring matapos tumawid ang mga tao."},"ar":{"q":"الإشارة خضراء ثابتة. شخص ما زال يعبر في ممر المشاة. ماذا يجب أن تفعل؟","o":["انطلق، لأن الأخضر يعطيك حق المرور","استخدم البوق لكي يسرع الشخص","انتظر ودع الشخص يكمل العبور","قُد حول الشخص"],"h1":"الضوء الأخضر يسمح لك بالانطلاق، لكن فكّر في من كان هناك أولًا.","h2":"الضوء الأخضر يسمح لك بالانطلاق فقط عندما يكون الطريق خاليًا، لذلك يجب أن تنتظر الأشخاص والسيارات الموجودين داخل التقاطع بالفعل.","p":"صحيح. عند الأخضر، ما زلت تترك الناس يكملون العبور."},"ht":{"q":"Limyè a vèt fiks. Gen yon moun ki toujou ap travèse nan pasaj pyeton an. Kisa ou dwe fè?","o":["Pase, paske limyè vèt la ba ou dwa pou pase","Klaksonen pou moun nan mache pi vit","Tann epi kite moun nan fini travèse","Pase bò kote moun nan"],"h1":"Yon limyè vèt kite ou pase, men panse ak kiyès ki te la anvan.","h2":"Yon limyè vèt kite ou pase sèlman lè wout la lib, kidonk ou dwe tann moun ak machin ki deja nan kafou a.","p":"Se sa. Sou limyè vèt, ou toujou kite moun yo fini travèse."},"ref":{"doc":"FL","page":51}},{"id":"signals-007","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"You see a steady green arrow pointing left. What does it mean?","o":["You may not turn left","You must yield to all oncoming cars first","Only buses may turn left","You may turn left, and oncoming traffic should be stopped"],"h1":"A green arrow gives a special turn. Think about what the other traffic sees.","h2":"A steady green arrow means you may turn in the direction of the arrow, because oncoming traffic should be facing a red light.","p":"Right. A green arrow means you may make that turn."},"es":{"q":"Usted ve una flecha verde fija que apunta a la izquierda. ¿Qué significa?","o":["No puede girar a la izquierda","Debe ceder el paso primero a todos los carros de frente","Solo los autobuses pueden girar a la izquierda","Puede girar a la izquierda, y el tráfico de frente debe estar parado"],"h1":"Una flecha verde da un giro especial. Piense qué ve el otro tráfico.","h2":"Una flecha verde fija significa que usted puede girar en la dirección de la flecha, porque el tráfico de frente debe tener luz roja.","p":"Correcto. Una flecha verde significa que puede hacer ese giro."},"zh":{"q":"你看到一个一直亮着、指向左边的绿色箭头。它是什么意思？","o":["你不能左转","你必须先让所有对面来车","只有公交车可以左转","你可以左转，对面来车应该在停着"],"h1":"绿色箭头给你一个专门的转弯时间。想一想其他车看到的是什么。","h2":"一直亮着的绿色箭头表示你可以按箭头方向转弯，因为对面来车这时应该是红灯。","p":"对。绿色箭头表示你可以这样转弯。"},"vi":{"q":"Bạn thấy mũi tên xanh sáng đứng yên chỉ sang trái. Điều đó có nghĩa là gì?","o":["Bạn không được rẽ trái","Bạn phải nhường tất cả xe ngược chiều trước","Chỉ xe buýt được rẽ trái","Bạn được rẽ trái, và xe ngược chiều lẽ ra đang phải dừng"],"h1":"Mũi tên xanh cho phép một lượt rẽ riêng. Hãy nghĩ xem xe bên kia đang thấy đèn gì.","h2":"Mũi tên xanh sáng đứng yên nghĩa là bạn được rẽ theo hướng mũi tên, vì xe ngược chiều lẽ ra đang gặp đèn đỏ.","p":"Đúng rồi. Mũi tên xanh nghĩa là bạn được rẽ theo hướng đó."},"tl":{"q":"May nakita kang tuloy-tuloy na berdeng arrow na nakaturo pakaliwa. Ano ang ibig sabihin nito?","o":["Hindi ka puwedeng kumaliwa","Dapat mo munang paunahin ang lahat ng paparating na sasakyan","Mga bus lang ang puwedeng kumaliwa","Puwede kang kumaliwa, at dapat nakahinto ang paparating na trapiko"],"h1":"Ang berdeng arrow ay nagbibigay ng espesyal na pagliko. Isipin kung ano ang nakikita ng ibang trapiko.","h2":"Ang tuloy-tuloy na berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyon ng arrow, dahil dapat nakaharap sa pulang ilaw ang paparating na trapiko.","p":"Tama. Ang berdeng arrow ay nangangahulugang puwede kang lumiko sa direksyong iyon."},"ar":{"q":"ترى سهمًا أخضر ثابتًا يشير إلى اليسار. ماذا يعني؟","o":["ممنوع أن تنعطف يسارًا","يجب أن تعطي الأولوية لكل السيارات القادمة أولًا","الحافلات فقط يمكنها أن تنعطف يسارًا","يمكنك أن تنعطف يسارًا، والسيارات القادمة يجب أن تكون متوقفة"],"h1":"السهم الأخضر يعطي انعطافًا خاصًا. فكّر في ما تراه السيارات الأخرى.","h2":"السهم الأخضر الثابت يعني أنه يمكنك أن تنعطف في اتجاه السهم، لأن السيارات القادمة يجب أن تكون أمام ضوء أحمر.","p":"صحيح. السهم الأخضر يعني أنه يمكنك أن تقوم بهذا الانعطاف."},"ht":{"q":"Ou wè yon flèch vèt fiks ki montre agoch. Kisa li vle di?","o":["Ou pa ka vire agoch","Ou dwe kite tout machin k ap vin sou ou pase anvan","Se sèlman bis ki ka vire agoch","Ou ka vire agoch, epi machin k ap vin sou ou yo ta dwe kanpe"],"h1":"Yon flèch vèt bay yon vire espesyal. Panse ak sa lòt machin yo wè.","h2":"Yon flèch vèt fiks vle di ou ka vire nan direksyon flèch la, paske machin k ap vin sou ou yo ta dwe gen yon limyè wouj devan yo.","p":"Se sa. Yon flèch vèt vle di ou ka fè vire sa a."},"ref":{"doc":"FL","page":52}},{"id":"signals-008","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a flashing yellow arrow pointing left mean?","o":["You may turn left, and oncoming traffic is stopped","You may turn left, but you must yield to oncoming traffic and people walking","You must stop and wait for a green arrow","Left turns are not allowed here"],"h1":"Flashing yellow is a warning. Think about whether oncoming cars can still come.","h2":"A flashing yellow arrow means you may turn left, but you must first yield to oncoming traffic and to people walking, because they may still have a green light.","p":"Right. A flashing yellow arrow means turn only after you yield."},"es":{"q":"¿Qué significa una flecha amarilla intermitente que apunta a la izquierda?","o":["Puede girar a la izquierda, y el tráfico de frente está parado","Puede girar a la izquierda, pero debe ceder el paso al tráfico de frente y a los peatones","Debe parar y esperar una flecha verde","No se permite girar a la izquierda aquí"],"h1":"El amarillo intermitente es una advertencia. Piense si los carros de frente todavía pueden venir.","h2":"Una flecha amarilla intermitente significa que usted puede girar a la izquierda, pero primero debe ceder el paso al tráfico de frente y a los peatones, porque ellos pueden tener luz verde.","p":"Correcto. Flecha amarilla intermitente significa gire solo después de ceder el paso."},"zh":{"q":"闪烁的黄色左转箭头是什么意思？","o":["你可以左转，对面来车已经停了","你可以左转，但必须让对面来车和行人先走","你必须停车，等绿色箭头","这里不准左转"],"h1":"闪烁的黄色是警告。想一想对面的车是不是还可能开过来。","h2":"闪烁的黄色箭头表示你可以左转，但必须先让对面来车和行人先走，因为他们可能还是绿灯。","p":"对。闪烁的黄色箭头表示先让行，再转弯。"},"vi":{"q":"Mũi tên vàng nhấp nháy chỉ sang trái có nghĩa là gì?","o":["Bạn được rẽ trái, và xe ngược chiều đang dừng","Bạn được rẽ trái, nhưng phải nhường xe ngược chiều và người đi bộ","Bạn phải dừng và chờ mũi tên xanh","Ở đây cấm rẽ trái"],"h1":"Màu vàng nhấp nháy là lời cảnh báo. Hãy nghĩ xem xe ngược chiều có còn chạy tới không.","h2":"Mũi tên vàng nhấp nháy nghĩa là bạn được rẽ trái, nhưng trước hết phải nhường xe ngược chiều và người đi bộ, vì họ có thể vẫn đang có đèn xanh.","p":"Đúng rồi. Mũi tên vàng nhấp nháy nghĩa là chỉ rẽ sau khi đã nhường đường."},"tl":{"q":"Ano ang ibig sabihin ng kumikislap na dilaw na arrow na nakaturo pakaliwa?","o":["Puwede kang kumaliwa, at nakahinto ang paparating na trapiko","Puwede kang kumaliwa, pero dapat mong paunahin ang paparating na trapiko at ang mga taong naglalakad","Dapat kang huminto at maghintay ng berdeng arrow","Bawal kumaliwa dito"],"h1":"Ang kumikislap na dilaw ay babala. Isipin kung puwede pa ring dumating ang mga paparating na sasakyan.","h2":"Ang kumikislap na dilaw na arrow ay nangangahulugang puwede kang kumaliwa, pero dapat mo munang paunahin ang paparating na trapiko at ang mga taong naglalakad, dahil maaaring berde pa rin ang ilaw nila.","p":"Tama. Ang kumikislap na dilaw na arrow ay nangangahulugang lumiko lang pagkatapos mong magbigay-daan."},"ar":{"q":"ماذا يعني سهم أصفر وامض يشير إلى اليسار؟","o":["يمكنك أن تنعطف يسارًا، والسيارات القادمة متوقفة","يمكنك أن تنعطف يسارًا، لكن يجب أن تعطي الأولوية للسيارات القادمة وللمشاة","يجب أن تتوقف وتنتظر سهمًا أخضر","الانعطاف يسارًا ممنوع هنا"],"h1":"الأصفر الوامض تحذير. فكّر: هل ما زالت السيارات القادمة يمكن أن تأتي؟","h2":"السهم الأصفر الوامض يعني أنه يمكنك أن تنعطف يسارًا، لكن يجب أولًا أن تعطي الأولوية للسيارات القادمة وللمشاة، لأن الإشارة قد تكون ما زالت خضراء لهم.","p":"صحيح. السهم الأصفر الوامض يعني: انعطف فقط بعد أن تعطي الأولوية."},"ht":{"q":"Kisa yon flèch jòn k ap kliyote ki montre agoch vle di?","o":["Ou ka vire agoch, epi machin k ap vin sou ou yo kanpe","Ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan","Ou dwe kanpe epi tann yon flèch vèt","Ou pa gen dwa vire agoch la a"],"h1":"Jòn k ap kliyote se yon avètisman. Panse si machin k ap vin sou ou yo ka toujou vini.","h2":"Yon flèch jòn k ap kliyote vle di ou ka vire agoch, men ou dwe kite machin k ap vin sou ou ak moun k ap mache pase anvan, paske yo ka toujou gen yon limyè vèt.","p":"Se sa. Yon flèch jòn k ap kliyote vle di vire sèlman apre ou fin bay pasaj."},"ref":{"doc":"FL","page":52}},{"id":"signals-009","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a steady yellow arrow mean?","o":["The protected turn is ending, so stop if you can do it safely","You may now turn without looking","Wait for the cars behind you","The turn lane is closed for the day"],"h1":"A steady yellow arrow works like a steady yellow light, but for a turn.","h2":"A steady yellow arrow means the arrow will soon turn red, so you should stop if you can do it safely.","p":"Right. A steady yellow arrow means the turn time is ending."},"es":{"q":"¿Qué significa una flecha amarilla fija?","o":["El giro protegido está terminando, así que pare si lo puede hacer con seguridad","Ahora puede girar sin mirar","Espere a los carros que vienen detrás","El carril de giro está cerrado todo el día"],"h1":"Una flecha amarilla fija funciona como una luz amarilla fija, pero para un giro.","h2":"Una flecha amarilla fija significa que la flecha pronto cambiará a roja, así que usted debe parar si lo puede hacer con seguridad.","p":"Correcto. Una flecha amarilla fija significa que el tiempo del giro se acaba."},"zh":{"q":"一直亮着的黄色箭头是什么意思？","o":["专用转弯时间要结束了，能安全停下就停车","你现在可以不看就转弯","等你后面的车","转弯车道今天关闭"],"h1":"一直亮着的黄色箭头和一直亮着的黄灯一样，只是用于转弯。","h2":"一直亮着的黄色箭头表示箭头马上要变红，所以如果能安全停下，你就应该停车。","p":"对。一直亮着的黄色箭头表示转弯时间要结束了。"},"vi":{"q":"Mũi tên vàng sáng đứng yên có nghĩa là gì?","o":["Lượt rẽ được bảo vệ sắp hết, nên hãy dừng nếu bạn có thể dừng an toàn","Bây giờ bạn được rẽ mà không cần nhìn","Chờ các xe phía sau bạn","Làn rẽ bị đóng cả ngày"],"h1":"Mũi tên vàng sáng đứng yên giống như đèn vàng sáng đứng yên, nhưng dành cho lượt rẽ.","h2":"Mũi tên vàng sáng đứng yên nghĩa là mũi tên sắp chuyển sang đỏ, nên bạn cần dừng lại nếu có thể dừng an toàn.","p":"Đúng rồi. Mũi tên vàng sáng đứng yên nghĩa là thời gian rẽ sắp hết."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na dilaw na arrow?","o":["Matatapos na ang protektadong pagliko, kaya huminto kung kaya mong gawin ito nang ligtas","Puwede ka nang lumiko nang hindi tumitingin","Hintayin ang mga sasakyan sa likod mo","Sarado ang turn lane sa buong araw"],"h1":"Ang tuloy-tuloy na dilaw na arrow ay gumagana na parang tuloy-tuloy na dilaw na ilaw, pero para sa pagliko.","h2":"Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang malapit nang maging pula ang arrow, kaya dapat kang huminto kung kaya mong gawin ito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na arrow ay nangangahulugang matatapos na ang oras ng pagliko."},"ar":{"q":"ماذا يعني السهم الأصفر الثابت؟","o":["وقت الانعطاف المحمي ينتهي، لذلك توقف إذا استطعت أن تفعل ذلك بأمان","الآن يمكنك أن تنعطف بدون أن تنظر","انتظر السيارات التي خلفك","مسار الانعطاف مغلق لبقية اليوم"],"h1":"السهم الأصفر الثابت يعمل مثل الضوء الأصفر الثابت، لكن للانعطاف.","h2":"السهم الأصفر الثابت يعني أن السهم سيصبح أحمر قريبًا، لذلك يجب أن تتوقف إذا استطعت أن تفعل ذلك بأمان.","p":"صحيح. السهم الأصفر الثابت يعني أن وقت الانعطاف ينتهي."},"ht":{"q":"Kisa yon flèch jòn fiks vle di?","o":["Tan pou vire ki pwoteje a ap fini, kidonk kanpe si ou ka fè l an sekirite","Kounye a ou ka vire san ou pa gade","Tann machin ki dèyè ou yo","Koulwa pou vire a fèmen pou jounen an"],"h1":"Yon flèch jòn fiks mache tankou yon limyè jòn fiks, men pou yon vire.","h2":"Yon flèch jòn fiks vle di flèch la pral vin wouj talè, kidonk ou dwe kanpe si ou ka fè l an sekirite.","p":"Se sa. Yon flèch jòn fiks vle di tan pou vire a ap fini."},"ref":{"doc":"FL","page":52}},{"id":"signals-010","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, you are on a two-way street. A steady red arrow points left. What must you do?","o":["Turn left after a full stop if no one is coming","Turn left slowly without stopping","Stop and do not turn left until the signal allows it","Use the next lane to turn left instead"],"h1":"Think about what a red signal means, even when it is shaped like an arrow.","h2":"In Florida, on a two-way street, a steady red arrow pointing left means you must stop and must not turn left until a green arrow or green light lets you.","p":"Right. A red left arrow means no left turn yet."},"es":{"q":"En Florida, usted está en una calle de doble sentido. Una flecha roja fija apunta a la izquierda. ¿Qué debe hacer?","o":["Girar a la izquierda después de parar por completo si no viene nadie","Girar a la izquierda despacio sin parar","Parar y no girar a la izquierda hasta que la señal lo permita","Usar el otro carril para girar a la izquierda"],"h1":"Piense qué significa una señal roja, aunque tenga forma de flecha.","h2":"En Florida, en una calle de doble sentido, una flecha roja fija que apunta a la izquierda significa que usted debe parar y no puede girar a la izquierda hasta que una flecha verde o luz verde se lo permita.","p":"Correcto. Una flecha roja a la izquierda significa que todavía no puede girar."},"zh":{"q":"在 Florida，你在一条双向街道上。一个一直亮着的红色箭头指向左边。你必须怎么做？","o":["完全停车后，没车就左转","不停车，慢慢左转","停车，在信号允许前不要左转","改用旁边的车道左转"],"h1":"想一想红色信号的意思，就算它是箭头的形状。","h2":"在 Florida 的双向街道上，指向左边、一直亮着的红色箭头表示你必须停车，在绿色箭头或绿灯允许之前不能左转。","p":"对。红色左转箭头表示现在还不能左转。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường hai chiều. Một mũi tên đỏ sáng đứng yên chỉ sang trái. Bạn phải làm gì?","o":["Rẽ trái sau khi dừng hẳn nếu không có ai tới","Rẽ trái chậm mà không cần dừng","Dừng lại và không rẽ trái cho tới khi đèn cho phép","Dùng làn bên cạnh để rẽ trái"],"h1":"Hãy nghĩ xem tín hiệu màu đỏ có nghĩa là gì, ngay cả khi nó có hình mũi tên.","h2":"Ở Florida, trên đường hai chiều, mũi tên đỏ sáng đứng yên chỉ sang trái nghĩa là bạn phải dừng lại và không được rẽ trái cho tới khi có mũi tên xanh hoặc đèn xanh cho phép.","p":"Đúng rồi. Mũi tên đỏ chỉ trái nghĩa là chưa được rẽ trái."},"tl":{"q":"Sa Florida, nasa kalyeng dalawa ang direksyon ka. May tuloy-tuloy na pulang arrow na nakaturo pakaliwa. Ano ang dapat mong gawin?","o":["Kumaliwa pagkatapos huminto nang buo kung walang dumarating","Kumaliwa nang dahan-dahan nang hindi humihinto","Huminto at huwag kumaliwa hanggang payagan ka ng ilaw","Gamitin ang katabing linya para kumaliwa"],"h1":"Isipin kung ano ang ibig sabihin ng pulang ilaw, kahit hugis arrow pa ito.","h2":"Sa Florida, sa kalyeng dalawa ang direksyon, ang tuloy-tuloy na pulang arrow na nakaturo pakaliwa ay nangangahulugang dapat kang huminto at hindi ka puwedeng kumaliwa hanggang payagan ka ng berdeng arrow o berdeng ilaw.","p":"Tama. Ang pulang arrow pakaliwa ay nangangahulugang hindi pa puwedeng kumaliwa."},"ar":{"q":"في Florida، أنت في شارع باتجاهين. سهم أحمر ثابت يشير إلى اليسار. ماذا يجب أن تفعل؟","o":["انعطف يسارًا بعد توقف تام إذا لم يأتِ أحد","انعطف يسارًا ببطء بدون أن تتوقف","توقف ولا تنعطف يسارًا حتى تسمح لك الإشارة","استخدم المسار المجاور لتنعطف يسارًا بدلًا من ذلك"],"h1":"فكّر في معنى الإشارة الحمراء، حتى لو كانت على شكل سهم.","h2":"في Florida، في شارع باتجاهين، السهم الأحمر الثابت إلى اليسار يعني أنه يجب أن تتوقف ولا تنعطف يسارًا حتى يسمح لك سهم أخضر أو ضوء أخضر.","p":"صحيح. السهم الأحمر إلى اليسار يعني: لا تنعطف يسارًا بعد."},"ht":{"q":"Nan Florida, ou sou yon lari ki gen de direksyon. Yon flèch wouj fiks montre agoch. Kisa ou dwe fè?","o":["Vire agoch apre ou fin kanpe nèt si pa gen moun k ap vini","Vire agoch dousman san ou pa kanpe","Kanpe epi pa vire agoch jiskaske siyal la pèmèt ou","Sèvi ak lòt koulwa a pou vire agoch pito"],"h1":"Panse ak sa yon siyal wouj vle di, menm lè li gen fòm yon flèch.","h2":"Nan Florida, sou yon lari ki gen de direksyon, yon flèch wouj fiks ki montre agoch vle di ou dwe kanpe epi ou pa dwe vire agoch jiskaske yon flèch vèt oswa yon limyè vèt kite ou pase.","p":"Se sa. Yon flèch wouj agoch vle di ou pa ka vire agoch ankò."},"ref":{"doc":"FL","page":52}},{"id":"signals-011","scope":"FL","cat":"signals","sign":null,"c":1,"en":{"q":"In Florida, may you turn right on a steady red light?","o":["Yes, without stopping, if no one is coming","Yes, after a full stop, if no sign forbids it and the way is clear","No, never","Only between midnight and 6 a.m."],"h1":"Think about two things: a full stop, and any sign at the corner.","h2":"In Florida, you may turn right on a red light after you stop fully and yield, unless a sign says no turn on red.","p":"Right. Stop fully, yield, and then you may turn right on red unless a sign forbids it."},"es":{"q":"En Florida, ¿puede girar a la derecha con luz roja fija?","o":["Sí, sin parar, si no viene nadie","Sí, después de parar por completo, si ninguna señal lo prohíbe y el camino está libre","No, nunca","Solo entre la medianoche y las 6 a.m."],"h1":"Piense en dos cosas: parar por completo y cualquier señal en la esquina.","h2":"En Florida, usted puede girar a la derecha con luz roja después de parar por completo y ceder el paso, a menos que una señal prohíba girar con luz roja.","p":"Correcto. Pare por completo, ceda el paso, y luego puede girar a la derecha con roja si ninguna señal lo prohíbe."},"zh":{"q":"在 Florida，一直亮着红灯时，你可以右转吗？","o":["可以，没有来车就不用停","可以，完全停车后，没有标志禁止，而且路上没车","不可以，永远不行","只在午夜到早上 6 点之间可以"],"h1":"想两件事：完全停车，和路口有没有标志。","h2":"在 Florida，你完全停车并让行后，可以在红灯时右转，除非有标志写着红灯禁止转弯。","p":"对。完全停车，让行，然后可以红灯右转，除非有标志禁止。"},"vi":{"q":"Ở Florida, bạn có được rẽ phải khi đèn đỏ sáng đứng yên không?","o":["Có, không cần dừng, nếu không có ai tới","Có, sau khi dừng hẳn, nếu không có biển cấm và đường đã trống","Không, không bao giờ","Chỉ từ nửa đêm tới 6 giờ sáng"],"h1":"Hãy nghĩ đến hai điều: dừng hẳn, và biển báo ở góc đường.","h2":"Ở Florida, bạn được rẽ phải khi đèn đỏ sau khi đã dừng hẳn và nhường đường, trừ khi có biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ).","p":"Đúng rồi. Dừng hẳn, nhường đường, rồi bạn được rẽ phải khi đèn đỏ, trừ khi có biển cấm."},"tl":{"q":"Sa Florida, puwede ka bang kumanan kapag tuloy-tuloy na pula ang ilaw?","o":["Oo, nang hindi humihinto, kung walang dumarating","Oo, pagkatapos huminto nang buo, kung walang karatulang nagbabawal at maluwag ang daan","Hindi, kailanman","Mula hatinggabi hanggang 6 a.m. lang"],"h1":"Isipin ang dalawang bagay: ang paghinto nang buo, at kung may karatula sa kanto.","h2":"Sa Florida, puwede kang kumanan kapag pula ang ilaw pagkatapos mong huminto nang buo at magbigay-daan, maliban kung may karatulang “NO TURN ON RED”.","p":"Tama. Huminto nang buo, magbigay-daan, at saka puwede kang kumanan sa pula maliban kung may karatulang nagbabawal."},"ar":{"q":"في Florida، هل يمكنك أن تنعطف يمينًا عند ضوء أحمر ثابت؟","o":["نعم، بدون توقف، إذا لم يأتِ أحد","نعم، بعد توقف تام، إذا لم تمنع ذلك لافتة وكان الطريق خاليًا","لا، أبدًا","فقط بين منتصف الليل والساعة 6 صباحًا"],"h1":"فكّر في أمرين: التوقف التام، وأي لافتة عند الزاوية.","h2":"في Florida، يمكنك أن تنعطف يمينًا عند الضوء الأحمر بعد أن تتوقف تمامًا وتعطي الأولوية، إلا إذا كانت هناك لافتة تقول «NO TURN ON RED» (ممنوع الانعطاف عند الأحمر).","p":"صحيح. توقف تمامًا، وأعطِ الأولوية، ثم يمكنك أن تنعطف يمينًا عند الأحمر إلا إذا منعت ذلك لافتة."},"ht":{"q":"Nan Florida, èske ou ka vire adwat sou yon limyè wouj fiks?","o":["Wi, san ou pa kanpe, si pa gen moun k ap vini","Wi, apre ou fin kanpe nèt, si pa gen siy ki entèdi sa epi wout la lib","Non, pa janm","Sèlman ant minwi ak 6 è dimaten"],"h1":"Panse ak de bagay: kanpe nèt, ak nenpòt siy ki nan kwen an.","h2":"Nan Florida, ou ka vire adwat sou limyè wouj apre ou fin kanpe nèt epi bay pasaj, sof si yon siy di “NO TURN ON RED”.","p":"Se sa. Kanpe nèt, bay pasaj, epi ou ka vire adwat sou wouj sof si yon siy entèdi sa."},"ref":{"doc":"FL","page":51}},{"id":"signals-012","scope":"FL","cat":"signals","sign":null,"c":3,"en":{"q":"In Florida, when may you turn left on a red light?","o":["From any street, if no one is coming","Never, under any condition","Only when you are in a hurry","From a one-way street onto another one-way street going left, after a full stop"],"h1":"Think about which streets have no oncoming traffic.","h2":"In Florida, you may turn left on red only from a one-way street onto a one-way street that goes left, and only after a full stop when the way is clear and no sign forbids it.","p":"Right. Left on red is only from one-way to one-way, after a full stop."},"es":{"q":"En Florida, ¿cuándo puede girar a la izquierda con luz roja?","o":["Desde cualquier calle, si no viene nadie","Nunca, en ningún caso","Solo cuando tiene prisa","De una calle de un solo sentido a otra calle de un solo sentido que va a la izquierda, después de parar por completo"],"h1":"Piense en qué calles no tienen tráfico de frente.","h2":"En Florida, usted puede girar a la izquierda con luz roja solo de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, y solo después de parar por completo, con el camino libre y sin una señal que lo prohíba.","p":"Correcto. Izquierda con roja solo de un solo sentido a un solo sentido, después de parar."},"zh":{"q":"在 Florida，什么时候可以在红灯时左转？","o":["从任何街道都行，只要没有来车","不行，什么情况都不行","只在你赶时间的时候","从单行道左转进入另一条往左走的单行道，并且要先完全停车"],"h1":"想一想：哪些街道没有对面来车。","h2":"在 Florida，只有从单行道左转进入往左走的单行道时，才可以在红灯时左转，而且要先完全停车，路上没车，也没有标志禁止。","p":"对。红灯左转只能从单行道到单行道，并且要先完全停车。"},"vi":{"q":"Ở Florida, khi nào bạn được rẽ trái lúc đèn đỏ?","o":["Từ bất cứ đường nào, nếu không có ai tới","Không bao giờ, trong bất cứ trường hợp nào","Chỉ khi bạn đang vội","Từ đường một chiều rẽ trái vào một đường một chiều khác, sau khi dừng hẳn"],"h1":"Hãy nghĩ xem đường nào không có xe chạy ngược chiều.","h2":"Ở Florida, bạn chỉ được rẽ trái khi đèn đỏ từ đường một chiều vào một đường một chiều chạy về phía trái, và chỉ sau khi dừng hẳn, khi đường đã trống và không có biển cấm.","p":"Đúng rồi. Rẽ trái khi đèn đỏ chỉ được từ đường một chiều sang đường một chiều, sau khi dừng hẳn."},"tl":{"q":"Sa Florida, kailan ka puwedeng kumaliwa kapag pula ang ilaw?","o":["Mula sa kahit anong kalye, kung walang dumarating","Hindi kailanman, sa anumang sitwasyon","Kapag nagmamadali ka lang","Mula sa one-way na kalye papunta sa isa pang one-way na kalye na papunta sa kaliwa, pagkatapos huminto nang buo"],"h1":"Isipin kung aling mga kalye ang walang paparating na trapiko.","h2":"Sa Florida, puwede kang kumaliwa sa pula mula lang sa one-way na kalye papunta sa one-way na kalye na papunta sa kaliwa, at pagkatapos lang huminto nang buo kapag maluwag ang daan at walang karatulang nagbabawal.","p":"Tama. Ang pagkaliwa sa pula ay mula lang sa one-way papunta sa one-way, pagkatapos huminto nang buo."},"ar":{"q":"في Florida، متى يمكنك أن تنعطف يسارًا عند ضوء أحمر؟","o":["من أي شارع، إذا لم يأتِ أحد","أبدًا، في أي حال","فقط عندما تكون مستعجلًا","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد يسير نحو اليسار، بعد توقف تام"],"h1":"فكّر في الشوارع التي لا تأتي فيها سيارات من الاتجاه المقابل.","h2":"في Florida، يمكنك أن تنعطف يسارًا عند الأحمر فقط من شارع باتجاه واحد إلى شارع باتجاه واحد يسير نحو اليسار، وفقط بعد توقف تام عندما يكون الطريق خاليًا ولا تمنع ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من اتجاه واحد إلى اتجاه واحد، بعد توقف تام."},"ht":{"q":"Nan Florida, ki lè ou ka vire agoch sou yon limyè wouj?","o":["Sou nenpòt lari, si pa gen moun k ap vini","Pa janm, nan okenn kondisyon","Sèlman lè ou prese","Soti sou yon lari yon sèl direksyon pou antre sou yon lòt lari yon sèl direksyon ki ale agoch, apre ou fin kanpe nèt"],"h1":"Panse ak ki lari ki pa gen machin k ap vin sou ou.","h2":"Nan Florida, ou ka vire agoch sou wouj sèlman soti sou yon lari yon sèl direksyon pou antre sou yon lari yon sèl direksyon ki ale agoch, epi sèlman apre ou fin kanpe nèt lè wout la lib epi pa gen siy ki entèdi sa.","p":"Se sa. Vire agoch sou wouj se sèlman soti sou yon sèl direksyon pou antre sou yon sèl direksyon, apre ou fin kanpe nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-013","scope":"FL","cat":"signals","sign":null,"c":0,"en":{"q":"In Florida, the traffic lights at an intersection are dark because the power is out. What should you do?","o":["Treat it as an all-way stop","Go through without stopping","Honk and go first","Treat it as a yield for you only"],"h1":"With no signal working, think about which sign makes every driver take turns.","h2":"In Florida, when traffic lights are not working, you treat the intersection as an all-way stop, so every driver stops and then goes in turn.","p":"Right. A dark signal means an all-way stop."},"es":{"q":"En Florida, los semáforos de una intersección están apagados porque no hay electricidad. ¿Qué debe hacer?","o":["Tratarla como una parada en todas las direcciones","Pasar sin parar","Tocar la bocina y pasar primero","Tratarla como un ceda el paso solo para usted"],"h1":"Si ninguna señal funciona, piense qué señal hace que todos los conductores tomen turnos.","h2":"En Florida, cuando los semáforos no funcionan, usted trata la intersección como una parada en todas las direcciones, así que cada conductor para y luego sigue por turno.","p":"Correcto. Un semáforo apagado significa parada en todas las direcciones."},"zh":{"q":"在 Florida，因为停电，路口的红绿灯不亮了。你应该怎么做？","o":["把它当作全向停车路口","不停车直接开过去","按喇叭，自己先走","当作只有你要让行"],"h1":"信号灯坏了时，想一想哪种标志让每个司机轮流走。","h2":"在 Florida，红绿灯不工作时，你要把路口当作全向停车路口，所以每个司机都先停车，然后轮流走。","p":"对。信号灯不亮表示全向停车。"},"vi":{"q":"Ở Florida, đèn giao thông ở một giao lộ bị tắt vì mất điện. Bạn nên làm gì?","o":["Xem đó là giao lộ mọi hướng đều phải dừng","Chạy qua mà không dừng","Bấm còi và đi trước","Xem như chỉ mình bạn phải nhường đường"],"h1":"Khi đèn không hoạt động, hãy nghĩ xem biển nào khiến mọi tài xế phải đi lần lượt.","h2":"Ở Florida, khi đèn giao thông không hoạt động, bạn xem giao lộ đó là nơi mọi hướng đều phải dừng, nên mọi tài xế đều dừng rồi đi lần lượt.","p":"Đúng rồi. Đèn tắt nghĩa là mọi hướng đều phải dừng."},"tl":{"q":"Sa Florida, patay ang mga ilaw trapiko sa isang interseksyon dahil walang kuryente. Ano ang dapat mong gawin?","o":["Ituring itong all-way stop (lahat ay hihinto)","Dumaan nang hindi humihinto","Bumusina at mauna","Ituring itong yield para sa iyo lang"],"h1":"Kapag walang gumaganang ilaw, isipin kung aling karatula ang nagpapasalitan sa lahat ng driver.","h2":"Sa Florida, kapag hindi gumagana ang mga ilaw trapiko, ituring mo ang interseksyon bilang all-way stop, kaya bawat driver ay hihinto at saka aandar nang salitan.","p":"Tama. Ang patay na ilaw trapiko ay nangangahulugang all-way stop."},"ar":{"q":"في Florida، إشارات المرور في تقاطع مطفأة لأن الكهرباء مقطوعة. ماذا يجب أن تفعل؟","o":["تعامل معه كتقاطع يتوقف فيه الجميع","اعبر بدون توقف","استخدم البوق وانطلق أولًا","تعامل معه كإعطاء أولوية لك وحدك"],"h1":"عندما لا تعمل الإشارة، فكّر في اللافتة التي تجعل كل سائق ينتظر دوره.","h2":"في Florida، عندما لا تعمل إشارات المرور، تتعامل مع التقاطع كتقاطع يتوقف فيه الجميع، لذلك كل سائق يتوقف ثم ينطلق حسب دوره.","p":"صحيح. الإشارة المطفأة تعني أن الجميع يتوقفون."},"ht":{"q":"Nan Florida, limyè trafik yo nan yon kafou etenn paske kouran an koupe. Kisa ou dwe fè?","o":["Fè l tankou yon kafou kote tout moun kanpe","Travèse san ou pa kanpe","Klaksonen epi pase anvan","Fè l tankou yon siy “YIELD” pou ou sèlman"],"h1":"Lè pa gen siyal k ap mache, panse ak ki siy ki fè chak chofè pase youn apre lòt.","h2":"Nan Florida, lè limyè trafik yo pa mache, ou fè kafou a tankou yon kafou kote tout moun kanpe, kidonk chak chofè kanpe epi pase youn apre lòt.","p":"Se sa. Yon limyè ki etenn vle di tout moun kanpe."},"ref":{"doc":"FL","page":51}},{"id":"signals-014","scope":"FL","cat":"signals","sign":null,"c":2,"en":{"q":"In Florida, your light is green, but the traffic ahead is backed up into the intersection. What should you do?","o":["Go in anyway, because the light is green","Drive into the intersection and wait there","Wait before the intersection until there is room on the other side","Drive on the shoulder around the line"],"h1":"Think about what happens to cross traffic if your car is stuck in the middle.","h2":"In Florida, you must not enter an intersection unless there is room for your car on the other side, even on green, because a stuck car blocks cross traffic.","p":"Right. Do not enter unless you can get all the way through."},"es":{"q":"En Florida, su luz está en verde, pero el tráfico de adelante está detenido hasta la intersección. ¿Qué debe hacer?","o":["Entrar de todos modos, porque la luz está en verde","Entrar a la intersección y esperar ahí","Esperar antes de la intersección hasta que haya espacio del otro lado","Manejar por el paseo para pasar la fila"],"h1":"Piense qué le pasa al tráfico que cruza si su carro queda atrapado en el medio.","h2":"En Florida, usted no debe entrar a una intersección si no hay espacio para su carro del otro lado, aunque tenga verde, porque un carro atrapado bloquea el tráfico que cruza.","p":"Correcto. No entre si no puede pasar por completo."},"zh":{"q":"在 Florida，你这边是绿灯，但前面的车已经堵到路口里了。你应该怎么做？","o":["照样开进去，因为是绿灯","开进路口，在里面等","在路口前等，等到路口另一边有空位","从路肩绕过排队的车"],"h1":"想一想：如果你的车卡在路口中间，横向的车会怎样。","h2":"在 Florida，就算是绿灯，路口另一边没有空位放你的车时，你也不能开进路口，因为卡住的车会挡住横向交通。","p":"对。除非能完全开过去，否则不要进入路口。"},"vi":{"q":"Ở Florida, đèn của bạn đang xanh, nhưng xe phía trước bị kẹt dồn vào tới giao lộ. Bạn nên làm gì?","o":["Cứ chạy vào, vì đèn đang xanh","Chạy vào giao lộ và chờ ở đó","Chờ trước giao lộ tới khi phía bên kia có chỗ trống","Chạy trên lề đường để vượt qua hàng xe"],"h1":"Hãy nghĩ xem xe ở hướng cắt ngang sẽ ra sao nếu xe bạn bị kẹt ở giữa.","h2":"Ở Florida, bạn không được chạy vào giao lộ nếu phía bên kia không có chỗ cho xe bạn, kể cả khi đèn xanh, vì xe bị kẹt sẽ chắn đường xe cắt ngang.","p":"Đúng rồi. Đừng chạy vào nếu bạn không thể qua hết giao lộ."},"tl":{"q":"Sa Florida, berde ang ilaw mo, pero ang trapiko sa unahan ay umaabot na hanggang sa interseksyon. Ano ang dapat mong gawin?","o":["Pumasok pa rin, dahil berde ang ilaw","Pumasok sa interseksyon at maghintay doon","Maghintay bago ang interseksyon hanggang may puwang sa kabilang bahagi","Magmaneho sa gilid ng kalsada para lampasan ang pila"],"h1":"Isipin kung ano ang mangyayari sa trapiko sa kabilang daan kapag naipit ang sasakyan mo sa gitna.","h2":"Sa Florida, hindi ka dapat pumasok sa interseksyon maliban kung may puwang para sa sasakyan mo sa kabilang bahagi, kahit berde, dahil ang naipit na sasakyan ay humaharang sa trapiko sa kabilang daan.","p":"Tama. Huwag pumasok maliban kung kaya mong makatawid nang buo."},"ar":{"q":"في Florida، إشارتك خضراء، لكن السيارات أمامك متكدسة حتى داخل التقاطع. ماذا يجب أن تفعل؟","o":["ادخل على أي حال، لأن الإشارة خضراء","ادخل إلى التقاطع وانتظر هناك","انتظر قبل التقاطع حتى يكون هناك مكان في الجهة الأخرى","قُد على كتف الطريق حول الطابور"],"h1":"فكّر في ما يحدث للسيارات المتقاطعة إذا علقت سيارتك في الوسط.","h2":"في Florida، يجب ألا تدخل التقاطع إلا إذا كان هناك مكان لسيارتك في الجهة الأخرى، حتى عند الأخضر، لأن السيارة العالقة تغلق الطريق أمام السيارات المتقاطعة.","p":"صحيح. لا تدخل إلا إذا كنت تستطيع أن تعبر إلى الجهة الأخرى بالكامل."},"ht":{"q":"Nan Florida, limyè ou a vèt, men machin devan yo bloke jous nan kafou a. Kisa ou dwe fè?","o":["Antre kanmèm, paske limyè a vèt","Antre nan kafou a epi tann la","Tann anvan kafou a jiskaske gen plas lòt bò a","Kondui sou arebò wout la pou pase bò kote liy machin yo"],"h1":"Panse ak sa k ap rive machin sou lòt lari a si machin ou bloke nan mitan an.","h2":"Nan Florida, ou pa dwe antre nan yon kafou sof si gen plas pou machin ou lòt bò a, menm lè limyè a vèt, paske yon machin ki bloke anpeche lòt machin yo pase.","p":"Se sa. Pa antre sof si ou ka travèse nèt."},"ref":{"doc":"FL","page":51}},{"id":"signals-015","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A pedestrian signal shows a walking person. What does it mean for people on foot?","o":["They must not start crossing","They may start crossing the street","Only bicycles may cross","Cars may turn without looking"],"h1":"The walking person is a picture of what people may do.","h2":"A walking person signal means people on foot may start crossing, so drivers who turn must yield to them.","p":"Right. The walking person means people may cross."},"es":{"q":"Una señal para peatones muestra una persona caminando. ¿Qué significa para las personas a pie?","o":["No deben empezar a cruzar","Pueden empezar a cruzar la calle","Solo las bicicletas pueden cruzar","Los carros pueden girar sin mirar"],"h1":"La persona caminando es un dibujo de lo que la gente puede hacer.","h2":"La señal de la persona caminando significa que las personas a pie pueden empezar a cruzar, así que los conductores que giran deben cederles el paso.","p":"Correcto. La persona caminando significa que pueden cruzar."},"zh":{"q":"行人信号灯显示一个走路的人。这对行人是什么意思？","o":["他们不能开始过马路","他们可以开始过马路","只有自行车可以过","汽车可以不看就转弯"],"h1":"走路的人这个图，就是行人可以做的事。","h2":"走路的人的信号表示行人可以开始过马路，所以转弯的司机必须让他们先走。","p":"对。走路的人表示行人可以过马路。"},"vi":{"q":"Đèn cho người đi bộ hiện hình một người đang đi. Điều đó có nghĩa là gì với người đi bộ?","o":["Họ không được bắt đầu băng qua","Họ được bắt đầu băng qua đường","Chỉ xe đạp được băng qua","Xe được rẽ mà không cần nhìn"],"h1":"Hình người đang đi cho thấy điều người đi bộ được làm.","h2":"Đèn có hình người đang đi nghĩa là người đi bộ được bắt đầu băng qua, nên tài xế đang rẽ phải nhường đường cho họ.","p":"Đúng rồi. Hình người đang đi nghĩa là người đi bộ được băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng taong naglalakad. Ano ang ibig sabihin nito para sa mga naglalakad?","o":["Hindi sila dapat magsimulang tumawid","Puwede na silang magsimulang tumawid sa kalye","Mga bisikleta lang ang puwedeng tumawid","Puwedeng lumiko ang mga sasakyan nang hindi tumitingin"],"h1":"Ang taong naglalakad ay larawan ng kung ano ang puwedeng gawin ng mga tao.","h2":"Ang ilaw na may taong naglalakad ay nangangahulugang puwede nang magsimulang tumawid ang mga naglalakad, kaya ang mga driver na lumiliko ay dapat magbigay-daan sa kanila.","p":"Tama. Ang taong naglalakad ay nangangahulugang puwedeng tumawid ang mga tao."},"ar":{"q":"إشارة المشاة تُظهر شخصًا يمشي. ماذا تعني للمشاة؟","o":["يجب ألا يبدؤوا العبور","يمكنهم أن يبدؤوا عبور الشارع","الدراجات فقط يمكنها العبور","السيارات يمكنها أن تنعطف بدون أن تنظر"],"h1":"الشخص الذي يمشي صورة لما يُسمح للناس أن يفعلوه.","h2":"إشارة الشخص الذي يمشي تعني أن المشاة يمكنهم أن يبدؤوا العبور، لذلك السائقون الذين ينعطفون يجب أن يعطوهم الأولوية.","p":"صحيح. الشخص الذي يمشي يعني أن الناس يمكنهم العبور."},"ht":{"q":"Yon siyal pou pyeton montre yon moun k ap mache. Kisa li vle di pou moun ki a pye?","o":["Yo pa dwe kòmanse travèse","Yo ka kòmanse travèse lari a","Se sèlman bisiklèt ki ka travèse","Machin yo ka vire san yo pa gade"],"h1":"Moun k ap mache a se yon foto sa moun yo ka fè.","h2":"Yon siyal ak yon moun k ap mache vle di moun ki a pye ka kòmanse travèse, kidonk chofè k ap vire dwe kite yo pase.","p":"Se sa. Moun k ap mache a vle di moun yo ka travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-016","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A pedestrian signal shows a flashing raised hand. What does it mean?","o":["Anyone may start crossing now","People must run back to the curb","Drivers must stop for the whole cycle","Do not start crossing, but people already crossing may finish"],"h1":"Think about the difference between starting to cross and finishing.","h2":"A flashing hand means people should not start crossing, but anyone already in the street may finish crossing.","p":"Right. A flashing hand means do not start, but finish if you already started."},"es":{"q":"Una señal para peatones muestra una mano levantada intermitente. ¿Qué significa?","o":["Cualquiera puede empezar a cruzar ahora","Las personas deben correr de vuelta a la acera","Los conductores deben parar todo el ciclo","No empiece a cruzar, pero quien ya está cruzando puede terminar"],"h1":"Piense en la diferencia entre empezar a cruzar y terminar de cruzar.","h2":"Una mano intermitente significa que las personas no deben empezar a cruzar, pero quien ya está en la calle puede terminar de cruzar.","p":"Correcto. Mano intermitente significa no empiece, pero termine si ya empezó."},"zh":{"q":"行人信号灯显示一只闪烁的举起的手。它是什么意思？","o":["任何人现在都可以开始过马路","行人必须跑回路边","司机在整个周期都必须停车","不要开始过马路，但已经在过的人可以走完"],"h1":"想一想 “开始过马路” 和 “走完” 有什么不同。","h2":"闪烁的手表示行人不应该开始过马路，但已经在马路上的人可以走完。","p":"对。闪烁的手表示不要开始，已经开始的人可以走完。"},"vi":{"q":"Đèn cho người đi bộ hiện hình bàn tay giơ lên đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Bây giờ ai cũng được bắt đầu băng qua","Người đi bộ phải chạy về lại lề đường","Tài xế phải dừng suốt cả chu kỳ đèn","Không được bắt đầu băng qua, nhưng ai đang băng qua thì được đi tiếp cho hết"],"h1":"Hãy nghĩ đến sự khác nhau giữa bắt đầu băng qua và đi cho hết.","h2":"Bàn tay nhấp nháy nghĩa là không ai nên bắt đầu băng qua, nhưng người đang ở giữa đường thì được đi tiếp cho hết.","p":"Đúng rồi. Bàn tay nhấp nháy nghĩa là đừng bắt đầu, nhưng đi cho hết nếu đã bắt đầu."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng kumikislap na nakataas na kamay. Ano ang ibig sabihin nito?","o":["Puwede nang magsimulang tumawid ang kahit sino","Dapat tumakbo pabalik sa bangketa ang mga tao","Dapat huminto ang mga driver sa buong ikot ng ilaw","Huwag magsimulang tumawid, pero puwedeng tapusin ng mga tumatawid na"],"h1":"Isipin ang pagkakaiba ng pagsisimulang tumawid at pagtatapos ng pagtawid.","h2":"Ang kumikislap na kamay ay nangangahulugang hindi dapat magsimulang tumawid ang mga tao, pero ang sinumang nasa kalye na ay puwedeng tapusin ang pagtawid.","p":"Tama. Ang kumikislap na kamay ay nangangahulugang huwag magsimula, pero tapusin kung nagsimula ka na."},"ar":{"q":"إشارة المشاة تُظهر يدًا مرفوعة تومض. ماذا تعني؟","o":["أي شخص يمكنه أن يبدأ العبور الآن","يجب أن يركض الناس عائدين إلى الرصيف","يجب أن يتوقف السائقون طوال الدورة كلها","لا تبدأ العبور، لكن من يعبر بالفعل يمكنه أن يكمل"],"h1":"فكّر في الفرق بين أن تبدأ العبور وأن تكمله.","h2":"اليد الوامضة تعني أن الناس يجب ألا يبدؤوا العبور، لكن أي شخص موجود في الشارع بالفعل يمكنه أن يكمل العبور.","p":"صحيح. اليد الوامضة تعني: لا تبدأ، لكن أكمل إذا كنت قد بدأت."},"ht":{"q":"Yon siyal pou pyeton montre yon men leve k ap kliyote. Kisa li vle di?","o":["Nenpòt moun ka kòmanse travèse kounye a","Moun yo dwe kouri tounen sou twotwa a","Chofè yo dwe kanpe pandan tout sik la","Pa kòmanse travèse, men moun ki deja ap travèse ka fini"],"h1":"Panse ak diferans ant kòmanse travèse ak fini travèse.","h2":"Yon men k ap kliyote vle di moun pa dwe kòmanse travèse, men nenpòt moun ki deja nan lari a ka fini travèse.","p":"Se sa. Yon men k ap kliyote vle di pa kòmanse, men fini si ou te deja kòmanse."},"ref":{"doc":"FL","page":55}},{"id":"signals-017","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A pedestrian signal shows a number counting down next to a hand. What does the number show?","o":["How many seconds are left to finish crossing","How many people may cross","The speed limit for the street","How many cars may turn"],"h1":"The number gets smaller every second.","h2":"The countdown number shows how many seconds are left for people to finish crossing before the signal changes.","p":"Right. The countdown shows the seconds left to cross."},"es":{"q":"Una señal para peatones muestra un número que baja al lado de una mano. ¿Qué indica el número?","o":["Cuántos segundos quedan para terminar de cruzar","Cuántas personas pueden cruzar","El límite de velocidad de la calle","Cuántos carros pueden girar"],"h1":"El número se hace más pequeño cada segundo.","h2":"El número de cuenta regresiva muestra cuántos segundos les quedan a las personas para terminar de cruzar antes de que cambie la señal.","p":"Correcto. La cuenta regresiva muestra los segundos que quedan para cruzar."},"zh":{"q":"行人信号灯在手的旁边显示一个倒数的数字。这个数字表示什么？","o":["还剩多少秒可以走完马路","可以有多少人过马路","这条街的限速","可以有多少辆车转弯"],"h1":"这个数字每秒都在变小。","h2":"倒数数字表示信号变化前，行人还剩多少秒可以走完马路。","p":"对。倒数数字表示过马路还剩几秒。"},"vi":{"q":"Đèn cho người đi bộ hiện một con số đếm ngược bên cạnh bàn tay. Con số đó cho biết gì?","o":["Còn bao nhiêu giây để đi qua hết","Bao nhiêu người được băng qua","Giới hạn tốc độ của con đường","Bao nhiêu xe được rẽ"],"h1":"Con số nhỏ đi mỗi giây.","h2":"Con số đếm ngược cho biết người đi bộ còn bao nhiêu giây để đi qua hết trước khi đèn đổi.","p":"Đúng rồi. Con số đếm ngược cho biết số giây còn lại để băng qua."},"tl":{"q":"Ang ilaw para sa tumatawid ay nagpapakita ng numerong nagbibilang pababa sa tabi ng kamay. Ano ang ipinapakita ng numero?","o":["Ilang segundo na lang ang natitira para matapos ang pagtawid","Ilang tao ang puwedeng tumawid","Ang speed limit ng kalye","Ilang sasakyan ang puwedeng lumiko"],"h1":"Lumiliit ang numero bawat segundo.","h2":"Ang numerong nagbibilang pababa ay nagpapakita kung ilang segundo na lang ang natitira para matapos tumawid ang mga tao bago magbago ang ilaw.","p":"Tama. Ipinapakita ng countdown ang natitirang segundo para tumawid."},"ar":{"q":"إشارة المشاة تُظهر رقمًا يعدّ تنازليًا بجانب يد. ماذا يُظهر الرقم؟","o":["كم ثانية بقيت لإكمال العبور","كم شخصًا يمكنه العبور","حد السرعة في الشارع","كم سيارة يمكنها أن تنعطف"],"h1":"الرقم يصغر كل ثانية.","h2":"رقم العد التنازلي يُظهر كم ثانية بقيت للناس لكي يكملوا العبور قبل أن تتغير الإشارة.","p":"صحيح. العد التنازلي يُظهر الثواني الباقية للعبور."},"ht":{"q":"Yon siyal pou pyeton montre yon nimewo k ap desann bò kote yon men. Kisa nimewo a montre?","o":["Konbyen segonn ki rete pou fini travèse","Konbyen moun ki ka travèse","Limit vitès nan lari a","Konbyen machin ki ka vire"],"h1":"Nimewo a vin pi piti chak segonn.","h2":"Nimewo k ap desann nan montre konbyen segonn ki rete pou moun yo fini travèse anvan siyal la chanje.","p":"Se sa. Nimewo k ap desann nan montre segonn ki rete pou travèse."},"ref":{"doc":"FL","page":55}},{"id":"signals-018","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do yellow center lines on a road tell you?","o":["All lanes go the same direction","The road is a school zone","Traffic on each side of the line moves in opposite directions","Parking is allowed on the line"],"h1":"Think about where yellow lines usually are: between the two sides of the road.","h2":"Yellow center lines separate traffic moving in opposite directions, so cars on the other side come toward you.","p":"Right. Yellow lines separate traffic going opposite ways."},"es":{"q":"¿Qué le indican las líneas amarillas en el centro de la calle?","o":["Todos los carriles van en la misma dirección","La calle es una zona escolar","El tráfico de cada lado de la línea va en direcciones opuestas","Se permite estacionar sobre la línea"],"h1":"Piense dónde suelen estar las líneas amarillas: entre los dos lados de la calle.","h2":"Las líneas amarillas del centro separan el tráfico que va en direcciones opuestas, así que los carros del otro lado vienen hacia usted.","p":"Correcto. Las líneas amarillas separan el tráfico que va en sentidos opuestos."},"zh":{"q":"道路上的黄色中心线告诉你什么？","o":["所有车道都往同一个方向","这条路是学校区","线两边的车往相反方向开","可以在线上停车"],"h1":"想一想黄线通常在哪里：在道路两边之间。","h2":"黄色中心线把相反方向的车流分开，所以线另一边的车是朝你开过来的。","p":"对。黄线把相反方向的车分开。"},"vi":{"q":"Vạch kẻ màu vàng ở giữa đường cho bạn biết điều gì?","o":["Tất cả các làn đều đi cùng một chiều","Con đường là khu vực trường học","Xe ở hai bên vạch chạy ngược chiều nhau","Được đỗ xe trên vạch"],"h1":"Hãy nghĩ xem vạch vàng thường nằm ở đâu: giữa hai bên của con đường.","h2":"Vạch vàng ở giữa đường tách xe chạy ngược chiều nhau, nên xe ở bên kia vạch đang chạy về phía bạn.","p":"Đúng rồi. Vạch vàng tách xe chạy ngược chiều nhau."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga dilaw na linya sa gitna ng kalsada?","o":["Lahat ng linya ay papunta sa iisang direksyon","School zone ang kalsada","Ang trapiko sa magkabilang bahagi ng linya ay papunta sa magkasalungat na direksyon","Puwedeng pumarada sa linya"],"h1":"Isipin kung saan karaniwang nakalagay ang mga dilaw na linya: sa pagitan ng dalawang bahagi ng kalsada.","h2":"Ang mga dilaw na linya sa gitna ay naghihiwalay sa trapikong papunta sa magkasalungat na direksyon, kaya ang mga sasakyan sa kabilang bahagi ay papunta sa iyo.","p":"Tama. Ang dilaw na linya ay naghihiwalay sa trapikong magkasalungat ang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط الصفراء في وسط الطريق؟","o":["كل المسارات تسير في نفس الاتجاه","الطريق منطقة مدرسة","السيارات على كل جانب من الخط تسير في اتجاهين متعاكسين","الوقوف مسموح على الخط"],"h1":"فكّر أين توجد الخطوط الصفراء عادةً: بين جانبي الطريق.","h2":"الخطوط الصفراء في الوسط تفصل بين السيارات التي تسير في اتجاهين متعاكسين، لذلك السيارات على الجانب الآخر تأتي نحوك.","p":"صحيح. الخطوط الصفراء تفصل بين السيارات التي تسير في اتجاهين متعاكسين."},"ht":{"q":"Kisa liy jòn nan mitan yon wout di ou?","o":["Tout koulwa yo ale nan menm direksyon","Wout la se yon zòn lekòl","Machin sou chak bò liy la ale nan direksyon opoze","Ou ka pake sou liy la"],"h1":"Panse ki kote liy jòn yo konn ye: ant de bò wout la.","h2":"Liy jòn nan mitan wout la separe machin k ap ale nan direksyon opoze, kidonk machin sou lòt bò a ap vin sou ou.","p":"Se sa. Liy jòn yo separe machin k ap ale nan direksyon opoze."},"ref":{"doc":"FL","page":43}},{"id":"signals-019","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What do white lines between lanes tell you?","o":["The lanes carry traffic going opposite directions","The lanes carry traffic going the same direction","The lane is only for buses","You are near a railroad crossing"],"h1":"Compare white lines with yellow lines.","h2":"White lines between lanes show that the traffic in those lanes moves in the same direction.","p":"Right. White lines separate lanes going the same way."},"es":{"q":"¿Qué le indican las líneas blancas entre los carriles?","o":["Los carriles llevan tráfico en direcciones opuestas","Los carriles llevan tráfico en la misma dirección","El carril es solo para autobuses","Usted está cerca de un cruce de tren"],"h1":"Compare las líneas blancas con las amarillas.","h2":"Las líneas blancas entre carriles muestran que el tráfico de esos carriles va en la misma dirección.","p":"Correcto. Las líneas blancas separan carriles que van en el mismo sentido."},"zh":{"q":"车道之间的白线告诉你什么？","o":["这些车道的车往相反方向开","这些车道的车往同一个方向开","这条车道只给公交车","你在铁路道口附近"],"h1":"把白线和黄线比一比。","h2":"车道之间的白线表示这些车道的车往同一个方向开。","p":"对。白线分开同方向的车道。"},"vi":{"q":"Vạch trắng giữa các làn cho bạn biết điều gì?","o":["Các làn có xe chạy ngược chiều nhau","Các làn có xe chạy cùng một chiều","Làn này chỉ dành cho xe buýt","Bạn đang ở gần chỗ băng qua đường sắt"],"h1":"Hãy so sánh vạch trắng với vạch vàng.","h2":"Vạch trắng giữa các làn cho thấy xe trong các làn đó chạy cùng một chiều.","p":"Đúng rồi. Vạch trắng tách các làn đi cùng một chiều."},"tl":{"q":"Ano ang sinasabi sa iyo ng mga puting linya sa pagitan ng mga lane?","o":["Ang mga lane ay may trapikong papunta sa magkasalungat na direksyon","Ang mga lane ay may trapikong papunta sa iisang direksyon","Para sa bus lang ang lane","Malapit ka sa tawiran ng tren"],"h1":"Ihambing ang mga puting linya sa mga dilaw na linya.","h2":"Ang mga puting linya sa pagitan ng mga lane ay nagpapakita na ang trapiko sa mga lane na iyon ay papunta sa iisang direksyon.","p":"Tama. Ang puting linya ay naghihiwalay sa mga lane na papunta sa iisang direksyon."},"ar":{"q":"ماذا تخبرك الخطوط البيضاء بين المسارات؟","o":["المسارات فيها سيارات تسير في اتجاهين متعاكسين","المسارات فيها سيارات تسير في نفس الاتجاه","المسار للحافلات فقط","أنت قريب من تقاطع سكة حديد"],"h1":"قارن الخطوط البيضاء بالخطوط الصفراء.","h2":"الخطوط البيضاء بين المسارات تُظهر أن السيارات في هذه المسارات تسير في نفس الاتجاه.","p":"صحيح. الخطوط البيضاء تفصل بين مسارات تسير في نفس الاتجاه."},"ht":{"q":"Kisa liy blan ant koulwa yo di ou?","o":["Machin nan koulwa yo ale nan direksyon opoze","Machin nan koulwa yo ale nan menm direksyon","Koulwa a se pou bis sèlman","Ou toupre yon kote tren travèse"],"h1":"Konpare liy blan yo ak liy jòn yo.","h2":"Liy blan ant koulwa yo montre machin nan koulwa sa yo ale nan menm direksyon.","p":"Se sa. Liy blan yo separe koulwa k ap ale nan menm direksyon."},"ref":{"doc":"FL","page":43}},{"id":"signals-020","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"The yellow center line on your side is broken (dashed). What does that allow?","o":["You may never pass","You may park on the line","You may drive on the line for a long time","You may pass when it is safe"],"h1":"A broken line has gaps. Think about what gaps let you do.","h2":"A broken yellow line on your side means you may pass another car, but only when the way ahead is clear and safe.","p":"Right. A broken yellow line on your side means you may pass when safe."},"es":{"q":"La línea amarilla del centro de su lado es discontinua (con espacios). ¿Qué le permite?","o":["No puede rebasar nunca","Puede estacionar sobre la línea","Puede manejar sobre la línea por mucho rato","Puede rebasar cuando sea seguro"],"h1":"Una línea discontinua tiene espacios. Piense qué le permiten esos espacios.","h2":"Una línea amarilla discontinua de su lado significa que usted puede rebasar a otro carro, pero solo cuando el camino adelante esté libre y sea seguro.","p":"Correcto. Línea amarilla discontinua de su lado significa que puede rebasar si es seguro."},"zh":{"q":"你这一边的黄色中心线是虚线（断开的）。它允许你做什么？","o":["你永远不能超车","你可以在线上停车","你可以长时间压线开","安全时你可以超车"],"h1":"虚线有空隙。想一想空隙让你做什么。","h2":"你这一边的黄色虚线表示你可以超车，但只能在前方路上没车、安全的时候。","p":"对。你这边是黄色虚线，表示安全时可以超车。"},"vi":{"q":"Vạch vàng ở giữa đường, phía bên bạn, là vạch đứt (nét đứt). Vạch này cho phép điều gì?","o":["Bạn không bao giờ được vượt","Bạn được đỗ xe trên vạch","Bạn được chạy trên vạch trong thời gian dài","Bạn được vượt khi an toàn"],"h1":"Vạch đứt có những khoảng trống. Hãy nghĩ xem khoảng trống cho bạn làm gì.","h2":"Vạch vàng đứt ở phía bên bạn nghĩa là bạn được vượt xe khác, nhưng chỉ khi đường phía trước trống và an toàn.","p":"Đúng rồi. Vạch vàng đứt ở phía bạn nghĩa là được vượt khi an toàn."},"tl":{"q":"Putol-putol (dashed) ang dilaw na linya sa gitna sa bahagi mo. Ano ang pinapayagan nito?","o":["Hindi ka kailanman puwedeng mag-overtake","Puwede kang pumarada sa linya","Puwede kang magmaneho sa ibabaw ng linya nang matagal","Puwede kang mag-overtake kapag ligtas"],"h1":"May mga puwang ang putol-putol na linya. Isipin kung ano ang ipinapagawa sa iyo ng mga puwang.","h2":"Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang lumampas sa ibang sasakyan, pero kapag maluwag at ligtas lang ang daan sa unahan.","p":"Tama. Ang putol-putol na dilaw na linya sa bahagi mo ay nangangahulugang puwede kang mag-overtake kapag ligtas."},"ar":{"q":"خط الوسط الأصفر على جانبك متقطع. بماذا يسمح ذلك؟","o":["لا يمكنك أن تتجاوز أبدًا","يمكنك أن تقف على الخط","يمكنك أن تقود على الخط وقتًا طويلًا","يمكنك أن تتجاوز عندما يكون ذلك آمنًا"],"h1":"الخط المتقطع فيه فراغات. فكّر في ما تسمح لك به الفراغات.","h2":"الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز سيارة أخرى، لكن فقط عندما يكون الطريق أمامك خاليًا وآمنًا.","p":"صحيح. الخط الأصفر المتقطع على جانبك يعني أنه يمكنك أن تتجاوز عندما يكون ذلك آمنًا."},"ht":{"q":"Liy jòn nan mitan an sou bò ou a koupe koupe (an tirè). Kisa sa pèmèt?","o":["Ou pa janm ka double","Ou ka pake sou liy la","Ou ka kondui sou liy la pou lontan","Ou ka double lè sa an sekirite"],"h1":"Yon liy koupe gen espas vid. Panse ak sa espas sa yo kite ou fè.","h2":"Yon liy jòn koupe sou bò ou a vle di ou ka double yon lòt machin, men sèlman lè wout la devan lib epi an sekirite.","p":"Se sa. Yon liy jòn koupe sou bò ou vle di ou ka double lè sa an sekirite."},"ref":{"doc":"FL","page":44}},{"id":"signals-021","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"You see a solid yellow line on your side and a broken yellow line on the other side. Who may pass?","o":["Only drivers on the side with the broken line","Only drivers on your side","Drivers on both sides","No one, at any time"],"h1":"Look at the line closest to your car. It is the one that counts for you.","h2":"The line closest to you is the one you follow, so a solid yellow line on your side means you may not pass, while drivers next to the broken line may pass when safe.","p":"Right. A solid line on your side means you may not pass."},"es":{"q":"Usted ve una línea amarilla continua de su lado y una línea amarilla discontinua del otro lado. ¿Quién puede rebasar?","o":["Solo los conductores del lado de la línea discontinua","Solo los conductores de su lado","Los conductores de los dos lados","Nadie, en ningún momento"],"h1":"Mire la línea más cerca de su carro. Esa es la que cuenta para usted.","h2":"Usted sigue la línea más cerca de su carro, así que una línea amarilla continua de su lado significa que no puede rebasar, mientras que los conductores junto a la línea discontinua pueden rebasar si es seguro.","p":"Correcto. Una línea continua de su lado significa que no puede rebasar."},"zh":{"q":"你这一边是黄色实线，另一边是黄色虚线。谁可以超车？","o":["只有虚线那一边的司机","只有你这一边的司机","两边的司机都可以","任何时候谁都不行"],"h1":"看离你的车最近的那条线。那条线才是给你的。","h2":"你要遵守离你最近的那条线，所以你这一边是黄色实线，表示你不能超车，而靠近虚线一边的司机在安全时可以超车。","p":"对。你这边是实线，表示你不能超车。"},"vi":{"q":"Bạn thấy vạch vàng liền ở phía bên bạn và vạch vàng đứt ở phía bên kia. Ai được vượt?","o":["Chỉ tài xế ở phía có vạch đứt","Chỉ tài xế ở phía bên bạn","Tài xế ở cả hai phía","Không ai cả, vào bất cứ lúc nào"],"h1":"Hãy nhìn vạch gần xe bạn nhất. Đó là vạch áp dụng cho bạn.","h2":"Bạn làm theo vạch gần bạn nhất, nên vạch vàng liền ở phía bạn nghĩa là bạn không được vượt, còn tài xế ở phía vạch đứt được vượt khi an toàn.","p":"Đúng rồi. Vạch liền ở phía bạn nghĩa là bạn không được vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na linya sa bahagi mo at putol-putol na dilaw na linya sa kabilang bahagi. Sino ang puwedeng mag-overtake?","o":["Ang mga driver lang sa bahaging may putol-putol na linya","Ang mga driver lang sa bahagi mo","Ang mga driver sa magkabilang bahagi","Walang sinuman, kailanman"],"h1":"Tingnan ang linyang pinakamalapit sa sasakyan mo. Iyon ang linyang para sa iyo.","h2":"Ang linyang pinakamalapit sa iyo ang sinusunod mo, kaya ang tuloy-tuloy na dilaw na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake, habang ang mga driver na katabi ng putol-putol na linya ay puwedeng mag-overtake kapag ligtas.","p":"Tama. Ang tuloy-tuloy na linya sa bahagi mo ay nangangahulugang hindi ka puwedeng mag-overtake."},"ar":{"q":"ترى خطًا أصفر متصلًا على جانبك وخطًا أصفر متقطعًا على الجانب الآخر. من يمكنه أن يتجاوز؟","o":["فقط السائقون على الجانب الذي فيه الخط المتقطع","فقط السائقون على جانبك","السائقون على الجانبين","لا أحد، في أي وقت"],"h1":"انظر إلى الخط الأقرب إلى سيارتك. هو الخط المهم بالنسبة لك.","h2":"الخط الأقرب إليك هو الذي تتبعه، لذلك الخط الأصفر المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز، أما السائقون بجانب الخط المتقطع فيمكنهم أن يتجاوزوا عندما يكون ذلك آمنًا.","p":"صحيح. الخط المتصل على جانبك يعني أنه لا يمكنك أن تتجاوز."},"ht":{"q":"Ou wè yon liy jòn plen sou bò ou ak yon liy jòn koupe sou lòt bò a. Kiyès ki ka double?","o":["Sèlman chofè ki sou bò liy koupe a","Sèlman chofè ki sou bò ou a","Chofè sou toude bò yo","Pèsonn, nan okenn moman"],"h1":"Gade liy ki pi pre machin ou a. Se li ki konte pou ou.","h2":"Liy ki pi pre ou a se li ou swiv, kidonk yon liy jòn plen sou bò ou vle di ou pa ka double, men chofè ki bò liy koupe a ka double lè sa an sekirite.","p":"Se sa. Yon liy plen sou bò ou vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"signals-022","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"What do two solid yellow lines in the center of the road mean?","o":["Passing is allowed in both directions","Only trucks may pass","It is a no-passing zone for traffic in both directions","The road ends ahead"],"h1":"Two solid lines are stronger than one. Think about both sides.","h2":"Two solid yellow lines mark a no-passing zone for both directions: in general, drivers on either side may not cross them to pass. Some states allow narrow exceptions, such as passing a bicyclist when it is safe.","p":"Right. Double solid yellow means no passing from either side."},"es":{"q":"¿Qué significan dos líneas amarillas continuas en el centro de la calle?","o":["Se permite rebasar en las dos direcciones","Solo los camiones pueden rebasar","Es una zona de no rebasar para el tráfico en las dos direcciones","La calle se termina más adelante"],"h1":"Dos líneas continuas son más fuertes que una. Piense en los dos lados.","h2":"Dos líneas amarillas continuas marcan una zona de no rebasar para las dos direcciones: en general, los conductores de ningún lado pueden cruzarlas para rebasar. Algunos estados permiten excepciones limitadas, como rebasar a un ciclista cuando es seguro.","p":"Correcto. Doble línea amarilla continua significa que no se rebasa de ningún lado."},"zh":{"q":"道路中间有两条黄色实线是什么意思？","o":["两个方向都可以超车","只有卡车可以超车","这是禁止超车区，两个方向的车都不能超车","前面道路到头了"],"h1":"两条实线比一条更严格。想一想两边的车。","h2":"两条黄色实线表示两个方向都禁止超车：一般来说，两边的司机都不可以越过黄线去超车。有些州允许少数例外，比如在安全时超过骑自行车的人。","p":"对。双黄实线表示两边都不能超车。"},"vi":{"q":"Hai vạch vàng liền ở giữa đường có nghĩa là gì?","o":["Được vượt xe ở cả hai chiều","Chỉ xe tải được vượt","Đây là khu vực cấm vượt cho xe ở cả hai chiều","Đường sắp hết ở phía trước"],"h1":"Hai vạch liền mạnh hơn một vạch. Hãy nghĩ đến cả hai bên.","h2":"Hai vạch vàng liền đánh dấu khu vực cấm vượt cho cả hai chiều: thông thường, tài xế ở bên nào cũng không được lấn qua vạch để vượt. Một số tiểu bang cho phép vài ngoại lệ nhỏ, chẳng hạn vượt người đi xe đạp khi an toàn.","p":"Đúng rồi. Hai vạch vàng liền nghĩa là cấm vượt từ cả hai bên."},"tl":{"q":"Ano ang ibig sabihin ng dalawang tuloy-tuloy na dilaw na guhit sa gitna ng daan?","o":["Pinapayagan ang pag-overtake sa magkabilang direksyon","Mga trak lang ang puwedeng mag-overtake","Bawal mag-overtake dito para sa trapiko sa magkabilang direksyon","Matatapos na ang daan sa unahan"],"h1":"Mas mahigpit ang dalawang tuloy-tuloy na guhit kaysa sa isa. Isipin ang magkabilang panig.","h2":"Ang dalawang tuloy-tuloy na dilaw na guhit ay nagmamarka ng lugar na bawal mag-overtake para sa magkabilang direksyon: sa pangkalahatan, hindi puwedeng tumawid sa mga ito ang mga driver sa alinmang panig para mag-overtake. May ilang estado na pumapayag sa maliliit na eksepsiyon, gaya ng pag-overtake sa nagbibisikleta kapag ligtas.","p":"Tama. Ang dobleng tuloy-tuloy na dilaw ay nangangahulugang bawal mag-overtake mula sa alinmang panig."},"ar":{"q":"ماذا يعني خطّان أصفران متصلان في وسط الطريق؟","o":["التجاوز مسموح في الاتجاهين","الشاحنات فقط يمكنها التجاوز","هذه منطقة يُمنع فيها التجاوز على السيارات في الاتجاهين","الطريق ينتهي أمامك"],"h1":"خطّان متصلان أقوى من خط واحد. فكّر في الجانبين.","h2":"الخطّان الأصفران المتصلان يحدّدان منطقة يُمنع فيها التجاوز في الاتجاهين: بشكل عام، يجب ألّا يعبرهما السائقون من أي جانب للتجاوز. بعض الولايات تسمح باستثناءات محدودة، مثل تجاوز راكب دراجة عندما يكون ذلك آمنًا.","p":"صحيح. الخطّان الأصفران المتصلان يعنيان أن التجاوز ممنوع من الجانبين."},"ht":{"q":"Kisa de liy jòn kontinyèl nan mitan wout la vle di?","o":["Ou ka double nan toulède direksyon","Se sèlman kamyon ki ka double","Se yon zòn kote yo entèdi double pou machin nan toulède direksyon","Wout la fini pi devan"],"h1":"De liy kontinyèl pi fò pase youn. Panse ak toulède bò yo.","h2":"De liy jòn kontinyèl make yon zòn kote yo entèdi double nan toulède direksyon: an jeneral, chofè ki sou nenpòt bò pa ka travèse yo pou double. Kèk eta pèmèt kèk ti eksepsyon, tankou double yon moun ki sou bisiklèt lè sa an sekirite.","p":"Se sa. De liy jòn kontinyèl vle di pa double nan okenn bò."},"ref":{"doc":"FL","page":44}},{"id":"signals-023","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"What does a solid white line between two lanes going the same way mean?","o":["You must change lanes now","Stay in your lane; changing lanes is discouraged there","Traffic in the next lane comes toward you","You may park along the line"],"h1":"A solid line asks you to stay where you are.","h2":"A solid white line between lanes means you should stay in your lane and change lanes only if you really must and it is safe.","p":"Right. A solid white line means stay in your lane."},"es":{"q":"¿Qué significa una línea blanca continua entre dos carriles que van en el mismo sentido?","o":["Usted debe cambiar de carril ahora","Quédese en su carril; no se recomienda cambiar de carril ahí","El tráfico del otro carril viene hacia usted","Puede estacionar junto a la línea"],"h1":"Una línea continua le pide quedarse donde está.","h2":"Una línea blanca continua entre carriles significa que usted debe quedarse en su carril y cambiar solo si de verdad lo necesita y es seguro.","p":"Correcto. Una línea blanca continua significa quédese en su carril."},"zh":{"q":"同方向两条车道之间的白色实线是什么意思？","o":["你现在必须换车道","待在你的车道里，这里最好不要换车道","旁边车道的车朝你开过来","你可以沿着这条线停车"],"h1":"实线是要你待在原来的地方。","h2":"车道之间的白色实线表示你应该待在自己的车道里，只有真的必须换道而且安全时才换。","p":"对。白色实线表示待在你的车道里。"},"vi":{"q":"Vạch trắng liền giữa hai làn đi cùng một chiều có nghĩa là gì?","o":["Bạn phải đổi làn ngay bây giờ","Hãy ở trong làn của bạn; không nên đổi làn ở đó","Xe ở làn bên cạnh chạy ngược về phía bạn","Bạn được đỗ xe dọc theo vạch"],"h1":"Vạch liền muốn bạn ở yên chỗ của mình.","h2":"Vạch trắng liền giữa các làn nghĩa là bạn nên ở trong làn của mình, và chỉ đổi làn khi thật sự cần và an toàn.","p":"Đúng rồi. Vạch trắng liền nghĩa là ở trong làn của bạn."},"tl":{"q":"Ano ang ibig sabihin ng tuloy-tuloy na puting linya sa pagitan ng dalawang lane na papunta sa iisang direksyon?","o":["Dapat kang lumipat ng lane ngayon","Manatili sa lane mo; hindi hinihikayat ang paglipat ng lane doon","Ang trapiko sa katabing lane ay papunta sa iyo","Puwede kang pumarada sa tabi ng linya"],"h1":"Hinihiling ng tuloy-tuloy na linya na manatili ka kung nasaan ka.","h2":"Ang tuloy-tuloy na puting linya sa pagitan ng mga lane ay nangangahulugang dapat kang manatili sa lane mo at lumipat lang ng lane kung talagang kailangan at ligtas.","p":"Tama. Ang tuloy-tuloy na puting linya ay nangangahulugang manatili sa lane mo."},"ar":{"q":"ماذا يعني خط أبيض متصل بين مسارين يسيران في نفس الاتجاه؟","o":["يجب أن تغيّر المسار الآن","ابقَ في مسارك؛ تغيير المسار غير مستحب هناك","السيارات في المسار المجاور تأتي نحوك","يمكنك أن تقف على طول الخط"],"h1":"الخط المتصل يطلب منك أن تبقى حيث أنت.","h2":"الخط الأبيض المتصل بين المسارات يعني أنه يجب أن تبقى في مسارك، وتغيّر المسار فقط إذا كنت مضطرًا حقًا وكان ذلك آمنًا.","p":"صحيح. الخط الأبيض المتصل يعني: ابقَ في مسارك."},"ht":{"q":"Kisa yon liy blan plen ant de koulwa k ap ale nan menm direksyon vle di?","o":["Ou dwe chanje koulwa kounye a","Rete nan koulwa ou; yo pa konseye chanje koulwa la a","Machin nan lòt koulwa a ap vin sou ou","Ou ka pake sou kote liy la"],"h1":"Yon liy plen mande ou rete kote ou ye a.","h2":"Yon liy blan plen ant koulwa yo vle di ou dwe rete nan koulwa ou epi chanje koulwa sèlman si ou vrèman oblije epi si sa an sekirite.","p":"Se sa. Yon liy blan plen vle di rete nan koulwa ou."},"ref":{"doc":"FL","page":43}},{"id":"signals-024","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A center lane has a solid yellow line and a broken yellow line on each side. What is this lane for?","o":["Passing slow cars","Driving long distances","Parking and loading","Left turns by drivers from both directions"],"h1":"Cars from both directions can use this lane, but only for one kind of move.","h2":"A center lane marked with solid and broken yellow lines on both sides is a two-way left-turn lane, so drivers from either direction use it only to turn left.","p":"Right. That center lane is only for left turns from both directions."},"es":{"q":"Un carril del centro tiene una línea amarilla continua y una línea amarilla discontinua en cada lado. ¿Para qué es este carril?","o":["Para rebasar a carros lentos","Para manejar distancias largas","Para estacionar y cargar","Para girar a la izquierda, para conductores de las dos direcciones"],"h1":"Carros de las dos direcciones pueden usar este carril, pero solo para un tipo de maniobra.","h2":"Un carril del centro con líneas amarillas continuas y discontinuas en los dos lados es un carril de giro a la izquierda en ambos sentidos, así que los conductores de cualquier dirección lo usan solo para girar a la izquierda.","p":"Correcto. Ese carril del centro es solo para girar a la izquierda, desde las dos direcciones."},"zh":{"q":"一条中间车道的两边各有一条黄色实线和一条黄色虚线。这条车道是做什么用的？","o":["超过慢车","开长途","停车和装卸货","两个方向的司机左转用"],"h1":"两个方向的车都能用这条车道，但只能做一种动作。","h2":"两边都画着黄色实线和黄色虚线的中间车道是双向左转车道，所以两个方向的司机都只能用它来左转。","p":"对。这条中间车道只给两个方向的车左转用。"},"vi":{"q":"Một làn ở giữa đường có vạch vàng liền và vạch vàng đứt ở mỗi bên. Làn này dùng để làm gì?","o":["Vượt xe chạy chậm","Chạy đường dài","Đỗ xe và bốc dỡ hàng","Rẽ trái cho tài xế từ cả hai chiều"],"h1":"Xe từ cả hai chiều đều được dùng làn này, nhưng chỉ cho một loại di chuyển.","h2":"Làn ở giữa có vạch vàng liền và vạch vàng đứt ở hai bên là làn rẽ trái hai chiều, nên tài xế từ chiều nào cũng chỉ dùng nó để rẽ trái.","p":"Đúng rồi. Làn giữa đó chỉ để rẽ trái, cho xe từ cả hai chiều."},"tl":{"q":"May gitnang lane na may tuloy-tuloy na dilaw na linya at putol-putol na dilaw na linya sa bawat gilid. Para saan ang lane na ito?","o":["Para lampasan ang mabagal na sasakyan","Para sa malayuang pagmamaneho","Para sa pagparada at pagkarga","Para sa pagkaliwa ng mga driver mula sa magkabilang direksyon"],"h1":"Puwedeng gamitin ng mga sasakyan mula sa magkabilang direksyon ang lane na ito, pero para lang sa isang uri ng galaw.","h2":"Ang gitnang lane na may tuloy-tuloy at putol-putol na dilaw na linya sa magkabilang gilid ay two-way left-turn lane, kaya ginagamit lang ito ng mga driver mula sa alinmang direksyon para kumaliwa.","p":"Tama. Ang gitnang lane na iyon ay para lang sa pagkaliwa mula sa magkabilang direksyon."},"ar":{"q":"مسار في الوسط له خط أصفر متصل وخط أصفر متقطع على كل جانب. ما الغرض من هذا المسار؟","o":["لتجاوز السيارات البطيئة","للقيادة لمسافات طويلة","للوقوف والتحميل","للانعطاف يسارًا للسائقين من الاتجاهين"],"h1":"السيارات من الاتجاهين يمكنها أن تستخدم هذا المسار، لكن لنوع واحد فقط من الحركة.","h2":"المسار الأوسط الذي عليه خطوط صفراء متصلة ومتقطعة على الجانبين هو مسار للانعطاف يسارًا في الاتجاهين، لذلك السائقون من أي اتجاه يستخدمونه فقط للانعطاف يسارًا.","p":"صحيح. هذا المسار الأوسط فقط للانعطاف يسارًا من الاتجاهين."},"ht":{"q":"Yon koulwa nan mitan an gen yon liy jòn plen ak yon liy jòn koupe sou chak bò. Pou kisa koulwa sa a ye?","o":["Pou double machin ki dousman","Pou kondui long distans","Pou pake ak pou chaje","Pou chofè ki soti nan toude direksyon vire agoch"],"h1":"Machin ki soti nan toude direksyon ka sèvi ak koulwa sa a, men pou yon sèl kalite mouvman.","h2":"Yon koulwa nan mitan an ki gen liy jòn plen ak liy jòn koupe sou toude bò se yon koulwa pou vire agoch nan de direksyon, kidonk chofè ki soti nan nenpòt direksyon sèvi avè l sèlman pou vire agoch.","p":"Se sa. Koulwa nan mitan sa a se sèlman pou vire agoch soti nan toude direksyon."},"ref":{"doc":"FL","page":45}},{"id":"signals-025","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Where should you stop when there is a wide white line painted across your lane at a red light?","o":["Before the white line","On top of the white line","Past the white line, at the corner","Anywhere in the intersection"],"h1":"This line shows the place where your front bumper should stop.","h2":"A wide white line across your lane is a stop line, so you must stop before it when you need to stop.","p":"Right. Stop before the white stop line."},"es":{"q":"¿Dónde debe parar cuando hay una línea blanca ancha pintada a lo ancho de su carril en una luz roja?","o":["Antes de la línea blanca","Encima de la línea blanca","Después de la línea blanca, en la esquina","En cualquier parte de la intersección"],"h1":"Esta línea muestra el lugar donde debe quedar el frente de su carro.","h2":"Una línea blanca ancha a lo ancho de su carril es la línea de pare, así que usted debe parar antes de ella cuando tiene que parar.","p":"Correcto. Pare antes de la línea blanca de pare."},"zh":{"q":"红灯时，你的车道上画着一条横过车道的宽白线。你应该停在哪里？","o":["白线前面","压在白线上","过了白线，停在路口拐角","路口里随便哪里"],"h1":"这条线表示你的前保险杠应该停在哪里。","h2":"横过你车道的宽白线是停车线，所以需要停车时，你必须停在它前面。","p":"对。停在白色停车线前面。"},"vi":{"q":"Khi đèn đỏ, có một vạch trắng rộng sơn ngang làn của bạn. Bạn nên dừng ở đâu?","o":["Trước vạch trắng","Ngay trên vạch trắng","Qua khỏi vạch trắng, ở góc đường","Bất cứ chỗ nào trong giao lộ"],"h1":"Vạch này cho thấy chỗ cản trước của xe bạn nên dừng lại.","h2":"Vạch trắng rộng ngang làn của bạn là vạch dừng, nên khi cần dừng, bạn phải dừng trước vạch đó.","p":"Đúng rồi. Hãy dừng trước vạch dừng màu trắng."},"tl":{"q":"Saan ka dapat huminto kapag may malapad na puting linyang nakapinta sa kabila ng lane mo sa pulang ilaw?","o":["Bago ang puting linya","Sa ibabaw ng puting linya","Lampas sa puting linya, sa may kanto","Kahit saan sa interseksyon"],"h1":"Ipinapakita ng linyang ito ang lugar kung saan dapat huminto ang harapang bumper mo.","h2":"Ang malapad na puting linya sa kabila ng lane mo ay stop line, kaya dapat kang huminto bago ito kapag kailangan mong huminto.","p":"Tama. Huminto bago ang puting stop line."},"ar":{"q":"أين يجب أن تتوقف عند ضوء أحمر عندما يكون هناك خط أبيض عريض مرسوم عرض مسارك؟","o":["قبل الخط الأبيض","فوق الخط الأبيض","بعد الخط الأبيض، عند الزاوية","في أي مكان داخل التقاطع"],"h1":"هذا الخط يُظهر المكان الذي يجب أن يتوقف عنده المصد الأمامي لسيارتك.","h2":"الخط الأبيض العريض عرض مسارك هو خط التوقف، لذلك يجب أن تتوقف قبله عندما تحتاج إلى التوقف.","p":"صحيح. توقف قبل خط التوقف الأبيض."},"ht":{"q":"Ki kote ou dwe kanpe lè gen yon gwo liy blan penti atravè koulwa ou nan yon limyè wouj?","o":["Anvan liy blan an","Sou liy blan an","Apre liy blan an, nan kwen an","Nenpòt kote nan kafou a"],"h1":"Liy sa a montre kote pare-chòk devan machin ou dwe kanpe.","h2":"Yon gwo liy blan atravè koulwa ou se yon liy pou kanpe, kidonk ou dwe kanpe anvan li lè ou bezwen kanpe.","p":"Se sa. Kanpe anvan liy blan pou kanpe a."},"ref":{"doc":"FL","page":45}},{"id":"signals-026","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"You must stop at an intersection. There is a marked crosswalk but no stop line. Where do you stop?","o":["In the middle of the crosswalk","Past the crosswalk, in the intersection","Before the crosswalk","Only if a person is in the crosswalk"],"h1":"Think about keeping the path clear for people walking.","h2":"When there is no stop line, you stop before the crosswalk, so people on foot have a clear path.","p":"Right. With no stop line, stop before the crosswalk."},"es":{"q":"Usted debe parar en una intersección. Hay un paso peatonal marcado, pero no hay línea de pare. ¿Dónde para?","o":["En medio del paso peatonal","Después del paso peatonal, dentro de la intersección","Antes del paso peatonal","Solo si hay una persona en el paso peatonal"],"h1":"Piense en dejar libre el camino de las personas que caminan.","h2":"Cuando no hay línea de pare, usted para antes del paso peatonal, para que las personas a pie tengan el camino libre.","p":"Correcto. Sin línea de pare, pare antes del paso peatonal."},"zh":{"q":"你必须在路口停车。那里有画好的人行横道，但没有停车线。你停在哪里？","o":["人行横道中间","过了人行横道，停在路口里","人行横道前面","只有人行横道上有人时才停"],"h1":"想一想：要给走路的人留出畅通的路。","h2":"没有停车线时，你要停在人行横道前面，这样行人有畅通的路可以走。","p":"对。没有停车线时，停在人行横道前面。"},"vi":{"q":"Bạn phải dừng ở một giao lộ. Có vạch qua đường cho người đi bộ nhưng không có vạch dừng. Bạn dừng ở đâu?","o":["Ở giữa vạch qua đường","Qua khỏi vạch qua đường, trong giao lộ","Trước vạch qua đường","Chỉ khi có người trên vạch qua đường"],"h1":"Hãy nghĩ đến việc để trống lối đi cho người đi bộ.","h2":"Khi không có vạch dừng, bạn dừng trước vạch qua đường, để người đi bộ có lối đi trống.","p":"Đúng rồi. Khi không có vạch dừng, hãy dừng trước vạch qua đường."},"tl":{"q":"Dapat kang huminto sa isang interseksyon. May minarkahang tawiran pero walang stop line. Saan ka hihinto?","o":["Sa gitna ng tawiran","Lampas sa tawiran, sa loob ng interseksyon","Bago ang tawiran","Kung may tao lang sa tawiran"],"h1":"Isipin ang pagpapanatiling maluwag ng daanan ng mga naglalakad.","h2":"Kapag walang stop line, huminto ka bago ang tawiran, para maluwag ang daanan ng mga naglalakad.","p":"Tama. Kapag walang stop line, huminto bago ang tawiran."},"ar":{"q":"يجب أن تتوقف عند تقاطع. هناك ممر مشاة مرسوم لكن لا يوجد خط توقف. أين تتوقف؟","o":["في وسط ممر المشاة","بعد ممر المشاة، داخل التقاطع","قبل ممر المشاة","فقط إذا كان هناك شخص في ممر المشاة"],"h1":"فكّر في إبقاء الطريق خاليًا للمشاة.","h2":"عندما لا يوجد خط توقف، تتوقف قبل ممر المشاة، لكي يكون طريق المشاة خاليًا.","p":"صحيح. بدون خط توقف، توقف قبل ممر المشاة."},"ht":{"q":"Ou dwe kanpe nan yon kafou. Gen yon pasaj pyeton ki make, men pa gen liy pou kanpe. Ki kote ou kanpe?","o":["Nan mitan pasaj pyeton an","Apre pasaj pyeton an, nan kafou a","Anvan pasaj pyeton an","Sèlman si gen yon moun nan pasaj pyeton an"],"h1":"Panse ak kite chemen an lib pou moun k ap mache.","h2":"Lè pa gen liy pou kanpe, ou kanpe anvan pasaj pyeton an, pou moun ki a pye yo gen yon chemen lib.","p":"Se sa. Lè pa gen liy pou kanpe, kanpe anvan pasaj pyeton an."},"ref":{"doc":"FL","page":45}},{"id":"signals-027","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"You see a bicycle symbol with two arrow shapes (chevrons) painted in your lane. What does it mean?","o":["Only bicycles may use this lane","Bicycles and cars share this lane","Bicycles are not allowed here","This lane is for parking bicycles"],"h1":"The marking is in a regular traffic lane, not in a separate bike lane.","h2":"A bicycle with chevrons is a shared lane marking, which means bicycles and cars share the lane, so watch for riders and give them room.","p":"Right. That marking means bikes and cars share the lane."},"es":{"q":"Usted ve un dibujo de bicicleta con dos flechas en forma de ángulo pintado en su carril. ¿Qué significa?","o":["Solo las bicicletas pueden usar este carril","Las bicicletas y los carros comparten este carril","No se permiten bicicletas aquí","Este carril es para estacionar bicicletas"],"h1":"La marca está en un carril normal de tráfico, no en un carril aparte para bicicletas.","h2":"Una bicicleta con flechas en ángulo es una marca de carril compartido, lo que significa que bicicletas y carros comparten el carril, así que fíjese en los ciclistas y deles espacio.","p":"Correcto. Esa marca significa que bicicletas y carros comparten el carril."},"zh":{"q":"你看到你的车道上画着一个自行车图案和两个箭头形状（V 形符号）。它是什么意思？","o":["只有自行车可以用这条车道","自行车和汽车共用这条车道","这里不准骑自行车","这条车道是停自行车的"],"h1":"这个标记在普通车道上，不在单独的自行车道上。","h2":"自行车加 V 形符号是共用车道标记，表示自行车和汽车共用这条车道，所以要注意骑车的人，给他们留出空间。","p":"对。这个标记表示自行车和汽车共用车道。"},"vi":{"q":"Bạn thấy hình xe đạp với hai hình mũi tên (chevron) được sơn trong làn của bạn. Điều đó có nghĩa là gì?","o":["Chỉ xe đạp được dùng làn này","Xe đạp và xe hơi dùng chung làn này","Ở đây cấm xe đạp","Làn này để đỗ xe đạp"],"h1":"Dấu này nằm trong làn xe bình thường, không phải trong làn riêng cho xe đạp.","h2":"Hình xe đạp có chevron là dấu làn dùng chung, nghĩa là xe đạp và xe hơi dùng chung làn, nên bạn cần chú ý người đi xe đạp và chừa chỗ cho họ.","p":"Đúng rồi. Dấu đó nghĩa là xe đạp và xe hơi dùng chung làn."},"tl":{"q":"May nakita kang simbolo ng bisikleta na may dalawang hugis-arrow (chevron) na nakapinta sa lane mo. Ano ang ibig sabihin nito?","o":["Mga bisikleta lang ang puwedeng gumamit ng lane na ito","Magkasamang ginagamit ng bisikleta at sasakyan ang lane na ito","Bawal ang bisikleta dito","Ang lane na ito ay paradahan ng bisikleta"],"h1":"Ang marka ay nasa karaniwang lane ng trapiko, hindi sa hiwalay na bike lane.","h2":"Ang bisikletang may chevron ay marka ng shared lane, na nangangahulugang magkasamang ginagamit ng bisikleta at sasakyan ang lane, kaya mag-ingat sa mga nagbibisikleta at bigyan sila ng puwang.","p":"Tama. Ang markang iyon ay nangangahulugang magkasama sa lane ang bisikleta at sasakyan."},"ar":{"q":"ترى رمز دراجة هوائية مع شكلين على هيئة سهم مرسومين في مسارك. ماذا يعني؟","o":["الدراجات فقط يمكنها أن تستخدم هذا المسار","الدراجات والسيارات تتشارك هذا المسار","الدراجات ممنوعة هنا","هذا المسار لوقوف الدراجات"],"h1":"العلامة موجودة في مسار سير عادي، وليست في مسار منفصل للدراجات.","h2":"الدراجة مع شكلي السهم هي علامة مسار مشترك، وتعني أن الدراجات والسيارات تتشارك المسار، لذلك انتبه لراكبي الدراجات واترك لهم مسافة.","p":"صحيح. هذه العلامة تعني أن الدراجات والسيارات تتشارك المسار."},"ht":{"q":"Ou wè yon foto bisiklèt ak de flèch an fòm V (chevwon) penti nan koulwa ou. Kisa li vle di?","o":["Se sèlman bisiklèt ki ka sèvi ak koulwa sa a","Bisiklèt ak machin pataje koulwa sa a","Bisiklèt pa gen dwa la a","Koulwa sa a se pou pake bisiklèt"],"h1":"Mak la nan yon koulwa trafik nòmal, se pa nan yon koulwa bisiklèt apa.","h2":"Yon bisiklèt ak chevwon se yon mak koulwa pataje, sa vle di bisiklèt ak machin pataje koulwa a, kidonk veye moun sou bisiklèt epi ba yo plas.","p":"Se sa. Mak sa a vle di bisiklèt ak machin pataje koulwa a."},"ref":{"doc":"FL","page":45}},{"id":"signals-028","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A white diamond is painted in a lane. What does it usually mean?","o":["The lane is a school zone","The lane ends soon","The lane is for slow trucks only","The lane is reserved for certain vehicles, like carpools or buses, at posted times"],"h1":"Look for a sign near the lane that tells who may use it.","h2":"A white diamond marks a reserved lane, such as a high-occupancy (HOV) lane for carpools, so you may use it only if you meet the rules posted on the signs.","p":"Right. The diamond marks a reserved lane, like a carpool lane."},"es":{"q":"Hay un diamante blanco pintado en un carril. ¿Qué suele significar?","o":["El carril es una zona escolar","El carril se termina pronto","El carril es solo para camiones lentos","El carril está reservado para ciertos vehículos, como carros compartidos o autobuses, en los horarios indicados"],"h1":"Busque una señal cerca del carril que diga quién puede usarlo.","h2":"Un diamante blanco marca un carril reservado, como un carril para vehículos con varios ocupantes (HOV), así que usted solo puede usarlo si cumple las reglas de las señales.","p":"Correcto. El diamante marca un carril reservado, como el de carros compartidos."},"zh":{"q":"车道上画着一个白色菱形。它通常是什么意思？","o":["这条车道是学校区","这条车道很快结束","这条车道只给慢速卡车","在标明的时间内，这条车道只给某些车辆用，比如拼车或公交车"],"h1":"找一找车道旁边说明谁可以用的标志。","h2":"白色菱形表示专用车道，比如给拼车用的多乘员车道（HOV），所以只有符合标志上的规定，你才可以用它。","p":"对。菱形表示专用车道，比如拼车车道。"},"vi":{"q":"Một hình thoi màu trắng được sơn trong làn. Điều đó thường có nghĩa là gì?","o":["Làn này là khu vực trường học","Làn này sắp hết","Làn này chỉ cho xe tải chạy chậm","Làn này dành riêng cho một số loại xe, như xe đi chung hoặc xe buýt, vào giờ được ghi trên biển"],"h1":"Hãy tìm biển báo gần làn cho biết ai được dùng nó.","h2":"Hình thoi màu trắng đánh dấu làn dành riêng, như làn HOV cho xe chở nhiều người đi chung, nên bạn chỉ được dùng nó nếu đúng với quy định ghi trên biển.","p":"Đúng rồi. Hình thoi đánh dấu làn dành riêng, như làn cho xe đi chung."},"tl":{"q":"May puting diyamanteng nakapinta sa isang lane. Ano ang karaniwang ibig sabihin nito?","o":["School zone ang lane","Matatapos na ang lane","Para sa mabagal na trak lang ang lane","Nakalaan ang lane para sa ilang sasakyan, tulad ng carpool o bus, sa mga oras na nakasulat sa karatula"],"h1":"Maghanap ng karatula malapit sa lane na nagsasabi kung sino ang puwedeng gumamit nito.","h2":"Ang puting diyamante ay nagmamarka ng nakalaang lane, tulad ng high-occupancy (HOV) lane para sa carpool, kaya puwede mo lang itong gamitin kung pasok ka sa mga patakarang nakasulat sa mga karatula.","p":"Tama. Ang diyamante ay nagmamarka ng nakalaang lane, tulad ng carpool lane."},"ar":{"q":"معيّن (ماسة) أبيض مرسوم في مسار. ماذا يعني عادةً؟","o":["المسار منطقة مدرسة","المسار ينتهي قريبًا","المسار للشاحنات البطيئة فقط","المسار مخصص لمركبات معيّنة، مثل السيارات المشتركة أو الحافلات، في الأوقات المكتوبة"],"h1":"ابحث عن لافتة قرب المسار تخبرك من يمكنه أن يستخدمه.","h2":"المعيّن الأبيض يدل على مسار مخصص، مثل مسار المركبات عالية الإشغال (HOV) للسيارات المشتركة، لذلك يمكنك أن تستخدمه فقط إذا كنت تتبع القواعد المكتوبة على اللافتات.","p":"صحيح. المعيّن يدل على مسار مخصص، مثل مسار السيارات المشتركة."},"ht":{"q":"Gen yon dyaman blan penti nan yon koulwa. Kisa li konn vle di?","o":["Koulwa a se yon zòn lekòl","Koulwa a ap fini talè","Koulwa a se pou kamyon ki dousman sèlman","Koulwa a rezève pou kèk machin, tankou machin ki pote plizyè moun oswa bis, nan lè ki make yo"],"h1":"Chèche yon siy toupre koulwa a ki di kiyès ki ka sèvi avè l.","h2":"Yon dyaman blan make yon koulwa rezève, tankou yon koulwa HOV pou machin ki pote plizyè moun, kidonk ou ka sèvi avè l sèlman si ou respekte règ ki ekri sou siy yo.","p":"Se sa. Dyaman an make yon koulwa rezève, tankou yon koulwa pou machin ki pote plizyè moun."},"ref":{"doc":"FL","page":69}},{"id":"signals-029","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A white arrow painted in your lane points only to the right. What should you do?","o":["Turn right from this lane","Go straight from this lane","Turn left from this lane","Make a U-turn from this lane"],"h1":"Arrows in a lane show which way that lane must go.","h2":"A lane arrow that points only to the right means drivers in that lane must turn right.","p":"Right. A right arrow in your lane means turn right."},"es":{"q":"Una flecha blanca pintada en su carril apunta solo a la derecha. ¿Qué debe hacer?","o":["Girar a la derecha desde este carril","Seguir derecho desde este carril","Girar a la izquierda desde este carril","Dar una vuelta en U desde este carril"],"h1":"Las flechas en un carril muestran hacia dónde debe ir ese carril.","h2":"Una flecha en el carril que apunta solo a la derecha significa que los conductores en ese carril deben girar a la derecha.","p":"Correcto. Una flecha a la derecha en su carril significa gire a la derecha."},"zh":{"q":"你的车道上画着一个只指向右边的白色箭头。你应该怎么做？","o":["从这条车道右转","从这条车道直行","从这条车道左转","从这条车道掉头"],"h1":"车道上的箭头表示这条车道必须往哪里走。","h2":"只指向右边的车道箭头表示这条车道上的司机必须右转。","p":"对。你的车道上有右转箭头，表示要右转。"},"vi":{"q":"Một mũi tên trắng sơn trong làn của bạn chỉ chỉ sang phải. Bạn nên làm gì?","o":["Rẽ phải từ làn này","Đi thẳng từ làn này","Rẽ trái từ làn này","Quay đầu xe từ làn này"],"h1":"Mũi tên trong làn cho biết làn đó phải đi hướng nào.","h2":"Mũi tên trong làn chỉ chỉ sang phải nghĩa là tài xế trong làn đó phải rẽ phải.","p":"Đúng rồi. Mũi tên phải trong làn của bạn nghĩa là rẽ phải."},"tl":{"q":"Ang puting arrow na nakapinta sa lane mo ay nakaturo lang pakanan. Ano ang dapat mong gawin?","o":["Kumanan mula sa lane na ito","Dumiretso mula sa lane na ito","Kumaliwa mula sa lane na ito","Mag-U-turn mula sa lane na ito"],"h1":"Ipinapakita ng mga arrow sa lane kung saan dapat pumunta ang lane na iyon.","h2":"Ang arrow sa lane na nakaturo lang pakanan ay nangangahulugang dapat kumanan ang mga driver sa lane na iyon.","p":"Tama. Ang arrow pakanan sa lane mo ay nangangahulugang kumanan."},"ar":{"q":"سهم أبيض مرسوم في مسارك يشير إلى اليمين فقط. ماذا يجب أن تفعل؟","o":["انعطف يمينًا من هذا المسار","سِر مستقيمًا من هذا المسار","انعطف يسارًا من هذا المسار","استدر للخلف من هذا المسار"],"h1":"الأسهم في المسار تُظهر الاتجاه الذي يجب أن يسير فيه هذا المسار.","h2":"سهم المسار الذي يشير إلى اليمين فقط يعني أن السائقين في هذا المسار يجب أن ينعطفوا يمينًا.","p":"صحيح. سهم إلى اليمين في مسارك يعني: انعطف يمينًا."},"ht":{"q":"Yon flèch blan penti nan koulwa ou montre sèlman adwat. Kisa ou dwe fè?","o":["Vire adwat nan koulwa sa a","Ale tou dwat nan koulwa sa a","Vire agoch nan koulwa sa a","Vire tounen nan koulwa sa a"],"h1":"Flèch nan yon koulwa montre ki bò koulwa sa a dwe ale.","h2":"Yon flèch nan koulwa a ki montre sèlman adwat vle di chofè nan koulwa sa a dwe vire adwat.","p":"Se sa. Yon flèch adwat nan koulwa ou vle di vire adwat."},"ref":{"doc":"FL","page":45}},{"id":"signals-030","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A row of white triangles is painted across your lane, pointing at you. What does it mean?","o":["Speed up to merge","The lane is for bicycles only","Yield here to traffic and people walking","You are on a one-way street the wrong way"],"h1":"The triangles look like a sign with the same shape.","h2":"A row of white triangles pointing toward you is a yield line, so you must slow down and be ready to stop there for other traffic and people walking.","p":"Right. The row of triangles is a yield line."},"es":{"q":"Una fila de triángulos blancos está pintada a lo ancho de su carril, apuntando hacia usted. ¿Qué significa?","o":["Acelere para incorporarse","El carril es solo para bicicletas","Ceda el paso aquí al tráfico y a los peatones","Usted va en contra en una calle de un solo sentido"],"h1":"Los triángulos se parecen a una señal que tiene la misma forma.","h2":"Una fila de triángulos blancos que apuntan hacia usted es una línea de ceda el paso, así que usted debe bajar la velocidad y estar listo para parar ahí por otro tráfico y por los peatones.","p":"Correcto. La fila de triángulos es una línea de ceda el paso."},"zh":{"q":"你的车道上横着画了一排白色三角形，尖角指向你。它是什么意思？","o":["加速并道","这条车道只给自行车","在这里给车辆和行人让行","你在单行道上逆行"],"h1":"这些三角形像一个形状相同的标志。","h2":"一排尖角指向你的白色三角形是让行线，所以你必须减速，准备在那里为其他车辆和行人停车。","p":"对。这排三角形是让行线。"},"vi":{"q":"Một hàng hình tam giác trắng được sơn ngang làn của bạn, mũi nhọn chỉ về phía bạn. Điều đó có nghĩa là gì?","o":["Tăng tốc để nhập làn","Làn này chỉ dành cho xe đạp","Nhường đường ở đây cho xe khác và người đi bộ","Bạn đang chạy ngược chiều trên đường một chiều"],"h1":"Các hình tam giác giống một biển báo có cùng hình dạng.","h2":"Hàng tam giác trắng chỉ về phía bạn là vạch nhường đường, nên bạn phải chạy chậm lại và sẵn sàng dừng ở đó cho xe khác và người đi bộ.","p":"Đúng rồi. Hàng tam giác đó là vạch nhường đường."},"tl":{"q":"May hanay ng mga puting tatsulok na nakapinta sa kabila ng lane mo, na nakaturo sa iyo. Ano ang ibig sabihin nito?","o":["Bumilis para makasingit","Para sa bisikleta lang ang lane","Magbigay-daan dito sa trapiko at sa mga taong naglalakad","Nasa one-way na kalye ka sa maling direksyon"],"h1":"Kamukha ng mga tatsulok ang isang karatula na may parehong hugis.","h2":"Ang hanay ng mga puting tatsulok na nakaturo sa iyo ay yield line, kaya dapat kang bumagal at maging handang huminto doon para sa ibang trapiko at sa mga taong naglalakad.","p":"Tama. Ang hanay ng mga tatsulok ay yield line."},"ar":{"q":"صف من المثلثات البيضاء مرسوم عرض مسارك، ورؤوسها تشير نحوك. ماذا يعني؟","o":["زد السرعة لتندمج","المسار للدراجات فقط","أعطِ الأولوية هنا للسيارات وللمشاة","أنت في شارع باتجاه واحد في الاتجاه الخاطئ"],"h1":"المثلثات تشبه لافتة لها نفس الشكل.","h2":"صف المثلثات البيضاء التي تشير نحوك هو خط إعطاء الأولوية، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف هناك من أجل السيارات الأخرى والمشاة.","p":"صحيح. صف المثلثات هو خط إعطاء الأولوية."},"ht":{"q":"Gen yon ranje ti triyang blan penti atravè koulwa ou, ak pwent yo vire sou ou. Kisa li vle di?","o":["Akselere pou antre","Koulwa a se pou bisiklèt sèlman","Bay machin ak moun k ap mache pasaj la a","Ou nan move direksyon sou yon lari yon sèl direksyon"],"h1":"Triyang yo sanble ak yon siy ki gen menm fòm nan.","h2":"Yon ranje triyang blan ki vire sou ou se yon liy pou bay pasaj, kidonk ou dwe ralanti epi pare pou kanpe la a pou lòt machin ak moun k ap mache.","p":"Se sa. Ranje triyang yo se yon liy pou bay pasaj."}},{"id":"signals-031","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"Over a reversible lane, you see a green arrow pointing down. What does it mean?","o":["You must leave this lane","You may drive in this lane","You may not drive in this lane","The lane is only for left turns"],"h1":"Green on a lane signal means the same thing as green on a traffic light.","h2":"A green arrow pointing down over a lane means you may drive in that lane.","p":"Right. A green arrow over the lane means you may use it."},"es":{"q":"Sobre un carril reversible, usted ve una flecha verde que apunta hacia abajo. ¿Qué significa?","o":["Debe salir de este carril","Puede manejar en este carril","No puede manejar en este carril","El carril es solo para girar a la izquierda"],"h1":"El verde en una señal de carril significa lo mismo que en un semáforo.","h2":"Una flecha verde que apunta hacia abajo sobre un carril significa que usted puede manejar en ese carril.","p":"Correcto. Una flecha verde sobre el carril significa que puede usarlo."},"zh":{"q":"在可变方向车道上方，你看到一个向下的绿色箭头。它是什么意思？","o":["你必须离开这条车道","你可以在这条车道上开","你不能在这条车道上开","这条车道只能左转"],"h1":"车道信号上的绿色和红绿灯上的绿色意思一样。","h2":"车道上方向下的绿色箭头表示你可以在这条车道上开。","p":"对。车道上方的绿色箭头表示你可以用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy mũi tên xanh chỉ xuống. Điều đó có nghĩa là gì?","o":["Bạn phải rời khỏi làn này","Bạn được chạy trong làn này","Bạn không được chạy trong làn này","Làn này chỉ để rẽ trái"],"h1":"Màu xanh trên đèn báo làn có nghĩa giống như màu xanh trên đèn giao thông.","h2":"Mũi tên xanh chỉ xuống phía trên một làn nghĩa là bạn được chạy trong làn đó.","p":"Đúng rồi. Mũi tên xanh phía trên làn nghĩa là bạn được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang berdeng arrow na nakaturo pababa. Ano ang ibig sabihin nito?","o":["Dapat kang umalis sa lane na ito","Puwede kang magmaneho sa lane na ito","Hindi ka puwedeng magmaneho sa lane na ito","Para sa pagkaliwa lang ang lane"],"h1":"Pareho ang ibig sabihin ng berde sa ilaw ng lane at ng berde sa ilaw trapiko.","h2":"Ang berdeng arrow na nakaturo pababa sa itaas ng lane ay nangangahulugang puwede kang magmaneho sa lane na iyon.","p":"Tama. Ang berdeng arrow sa itaas ng lane ay nangangahulugang puwede mo itong gamitin."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى سهمًا أخضر يشير إلى الأسفل. ماذا يعني؟","o":["يجب أن تخرج من هذا المسار","يمكنك أن تقود في هذا المسار","لا يمكنك أن تقود في هذا المسار","المسار للانعطاف يسارًا فقط"],"h1":"الأخضر في إشارة المسار يعني نفس ما يعنيه الأخضر في إشارة المرور.","h2":"السهم الأخضر الذي يشير إلى الأسفل فوق مسار يعني أنه يمكنك أن تقود في هذا المسار.","p":"صحيح. السهم الأخضر فوق المسار يعني أنه يمكنك أن تستخدمه."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon flèch vèt ki montre anba. Kisa li vle di?","o":["Ou dwe kite koulwa sa a","Ou ka kondui nan koulwa sa a","Ou pa ka kondui nan koulwa sa a","Koulwa a se pou vire agoch sèlman"],"h1":"Vèt sou yon siyal koulwa vle di menm bagay ak vèt sou yon limyè trafik.","h2":"Yon flèch vèt ki montre anba anwo yon koulwa vle di ou ka kondui nan koulwa sa a.","p":"Se sa. Yon flèch vèt anwo koulwa a vle di ou ka sèvi avè l."},"ref":{"doc":"FL","page":53}},{"id":"signals-032","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Over a reversible lane, you see a red X. What does it mean?","o":["You may drive in this lane","You may pass in this lane","The lane is for buses only","Do not drive in this lane"],"h1":"Think about what a red X means anywhere.","h2":"A red X over a lane means you must not drive in that lane, because traffic may be coming the other way.","p":"Right. A red X means do not use that lane."},"es":{"q":"Sobre un carril reversible, usted ve una X roja. ¿Qué significa?","o":["Puede manejar en este carril","Puede rebasar en este carril","El carril es solo para autobuses","No maneje en este carril"],"h1":"Piense qué significa una X roja en cualquier lugar.","h2":"Una X roja sobre un carril significa que usted no debe manejar en ese carril, porque el tráfico puede venir en el otro sentido.","p":"Correcto. Una X roja significa no use ese carril."},"zh":{"q":"在可变方向车道上方，你看到一个红色的 X。它是什么意思？","o":["你可以在这条车道上开","你可以在这条车道上超车","这条车道只给公交车","不要在这条车道上开"],"h1":"想一想红色 X 在任何地方是什么意思。","h2":"车道上方的红色 X 表示你不能在这条车道上开，因为可能有车从对面开过来。","p":"对。红色 X 表示不要用这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu đỏ. Điều đó có nghĩa là gì?","o":["Bạn được chạy trong làn này","Bạn được vượt trong làn này","Làn này chỉ dành cho xe buýt","Không được chạy trong làn này"],"h1":"Hãy nghĩ xem chữ X màu đỏ ở đâu cũng có nghĩa là gì.","h2":"Chữ X đỏ phía trên một làn nghĩa là bạn không được chạy trong làn đó, vì có thể có xe đang chạy tới từ chiều ngược lại.","p":"Đúng rồi. Chữ X đỏ nghĩa là không được dùng làn đó."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang pulang X. Ano ang ibig sabihin nito?","o":["Puwede kang magmaneho sa lane na ito","Puwede kang mag-overtake sa lane na ito","Para sa bus lang ang lane","Huwag magmaneho sa lane na ito"],"h1":"Isipin kung ano ang ibig sabihin ng pulang X saanman.","h2":"Ang pulang X sa itaas ng lane ay nangangahulugang hindi ka dapat magmaneho sa lane na iyon, dahil maaaring may trapikong papunta mula sa kabilang direksyon.","p":"Tama. Ang pulang X ay nangangahulugang huwag gamitin ang lane na iyon."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أحمر. ماذا يعني؟","o":["يمكنك أن تقود في هذا المسار","يمكنك أن تتجاوز في هذا المسار","المسار للحافلات فقط","لا تقُد في هذا المسار"],"h1":"فكّر في معنى X الأحمر في أي مكان.","h2":"حرف X الأحمر فوق مسار يعني أنه يجب ألا تقود في هذا المسار، لأن السيارات قد تأتي من الاتجاه الآخر.","p":"صحيح. X الأحمر يعني: لا تستخدم هذا المسار."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X wouj. Kisa li vle di?","o":["Ou ka kondui nan koulwa sa a","Ou ka double nan koulwa sa a","Koulwa a se pou bis sèlman","Pa kondui nan koulwa sa a"],"h1":"Panse ak sa yon X wouj vle di nenpòt kote.","h2":"Yon X wouj anwo yon koulwa vle di ou pa dwe kondui nan koulwa sa a, paske ka gen machin k ap vini nan lòt direksyon an.","p":"Se sa. Yon X wouj vle di pa sèvi ak koulwa sa a."},"ref":{"doc":"FL","page":53}},{"id":"signals-033","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Over a reversible lane, you see a steady yellow X. What should you do?","o":["Move out of this lane safely, because it is about to change","Stay in the lane as long as you like","Speed up in this lane","Stop in the lane and wait"],"h1":"A steady yellow X works like a steady yellow light: something is about to change.","h2":"A steady yellow X over a lane means the lane is about to close to your direction, so you should safely move out of it.","p":"Right. A steady yellow X means leave the lane safely."},"es":{"q":"Sobre un carril reversible, usted ve una X amarilla fija. ¿Qué debe hacer?","o":["Salir del carril con seguridad, porque está por cambiar","Quedarse en el carril todo el tiempo que quiera","Acelerar en este carril","Parar en el carril y esperar"],"h1":"Una X amarilla fija funciona como una luz amarilla fija: algo está por cambiar.","h2":"Una X amarilla fija sobre un carril significa que el carril se va a cerrar para su dirección, así que usted debe salir de él con seguridad.","p":"Correcto. Una X amarilla fija significa salga del carril con seguridad."},"zh":{"q":"在可变方向车道上方，你看到一个一直亮着的黄色 X。你应该怎么做？","o":["安全地离开这条车道，因为它马上要变","想在这条车道开多久就开多久","在这条车道上加速","在车道里停车等待"],"h1":"一直亮着的黄色 X 和一直亮着的黄灯一样：马上有变化。","h2":"车道上方一直亮着的黄色 X 表示这条车道马上要对你的方向关闭，所以你应该安全地离开它。","p":"对。一直亮着的黄色 X 表示要安全地离开这条车道。"},"vi":{"q":"Phía trên một làn đổi chiều, bạn thấy chữ X màu vàng sáng đứng yên. Bạn nên làm gì?","o":["Ra khỏi làn này một cách an toàn, vì làn sắp đổi","Ở trong làn bao lâu tùy thích","Tăng tốc trong làn này","Dừng lại trong làn và chờ"],"h1":"Chữ X vàng sáng đứng yên giống như đèn vàng sáng đứng yên: sắp có điều gì đó thay đổi.","h2":"Chữ X vàng sáng đứng yên phía trên một làn nghĩa là làn đó sắp đóng với chiều xe của bạn, nên bạn cần ra khỏi làn một cách an toàn.","p":"Đúng rồi. Chữ X vàng nghĩa là hãy rời khỏi làn một cách an toàn."},"tl":{"q":"Sa itaas ng isang reversible lane, may nakita kang tuloy-tuloy na dilaw na X. Ano ang dapat mong gawin?","o":["Lumabas nang ligtas sa lane na ito, dahil malapit na itong magbago","Manatili sa lane hangga't gusto mo","Bumilis sa lane na ito","Huminto sa lane at maghintay"],"h1":"Ang tuloy-tuloy na dilaw na X ay gumagana na parang tuloy-tuloy na dilaw na ilaw: may malapit nang magbago.","h2":"Ang tuloy-tuloy na dilaw na X sa itaas ng lane ay nangangahulugang malapit nang isara ang lane para sa direksyon mo, kaya dapat kang lumabas dito nang ligtas.","p":"Tama. Ang tuloy-tuloy na dilaw na X ay nangangahulugang umalis nang ligtas sa lane."},"ar":{"q":"فوق مسار متغيّر الاتجاه، ترى حرف X أصفر ثابتًا. ماذا يجب أن تفعل؟","o":["اخرج من هذا المسار بأمان، لأنه سيتغيّر بعد قليل","ابقَ في المسار كما تريد","زد السرعة في هذا المسار","توقف في المسار وانتظر"],"h1":"X الأصفر الثابت يعمل مثل الضوء الأصفر الثابت: شيء ما سيتغيّر بعد قليل.","h2":"حرف X الأصفر الثابت فوق مسار يعني أن المسار سيُغلق قريبًا أمام اتجاهك، لذلك يجب أن تخرج منه بأمان.","p":"صحيح. X الأصفر الثابت يعني: اخرج من المسار بأمان."},"ht":{"q":"Anwo yon koulwa ki ka chanje direksyon, ou wè yon X jòn fiks. Kisa ou dwe fè?","o":["Kite koulwa sa a an sekirite, paske li pral chanje","Rete nan koulwa a otan ou vle","Akselere nan koulwa sa a","Kanpe nan koulwa a epi tann"],"h1":"Yon X jòn fiks mache tankou yon limyè jòn fiks: yon bagay pral chanje.","h2":"Yon X jòn fiks anwo yon koulwa vle di koulwa a pral fèmen pou direksyon ou a, kidonk ou dwe kite l an sekirite.","p":"Se sa. Yon X jòn fiks vle di kite koulwa a an sekirite."},"ref":{"doc":"FL","page":53}},{"id":"signals-034","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A police officer is directing traffic at an intersection. The light is green, but the officer signals you to stop. What do you do?","o":["Go, because the light is green","Honk to get the officer to move","Stop and follow the officer","Turn right to go around the officer"],"h1":"Think about who sees the real situation at that moment.","h2":"You must follow the directions of a police officer directing traffic, even when they are different from the traffic light.","p":"Right. A police officer’s directions come before the traffic light."},"es":{"q":"Un policía está dirigiendo el tráfico en una intersección. La luz está en verde, pero el policía le indica que pare. ¿Qué hace?","o":["Seguir, porque la luz está en verde","Tocar la bocina para que el policía se mueva","Parar y seguir las indicaciones del policía","Girar a la derecha para pasar al policía"],"h1":"Piense quién ve la situación real en ese momento.","h2":"Usted debe seguir las indicaciones de un policía que dirige el tráfico, aunque sean diferentes a las del semáforo.","p":"Correcto. Las indicaciones del policía van antes que el semáforo."},"zh":{"q":"一名警察在路口指挥交通。灯是绿的，但警察示意你停车。你怎么做？","o":["开走，因为是绿灯","按喇叭让警察让开","停车，听警察的指挥","右转绕过警察"],"h1":"想一想：谁能看到当时的真实情况。","h2":"你必须服从指挥交通的警察，就算警察的指挥和红绿灯不一样也要服从。","p":"对。警察的指挥比红绿灯优先。"},"vi":{"q":"Một cảnh sát đang điều khiển giao thông ở giao lộ. Đèn đang xanh, nhưng cảnh sát ra hiệu cho bạn dừng. Bạn làm gì?","o":["Cứ đi, vì đèn đang xanh","Bấm còi để cảnh sát tránh ra","Dừng lại và làm theo cảnh sát","Rẽ phải để đi vòng qua cảnh sát"],"h1":"Hãy nghĩ xem ai đang thấy rõ tình hình thật lúc đó.","h2":"Bạn phải làm theo hướng dẫn của cảnh sát đang điều khiển giao thông, kể cả khi hướng dẫn đó khác với đèn giao thông.","p":"Đúng rồi. Hướng dẫn của cảnh sát được ưu tiên hơn đèn giao thông."},"tl":{"q":"May pulis na nagdidirekta ng trapiko sa isang interseksyon. Berde ang ilaw, pero sinesenyasan ka ng pulis na huminto. Ano ang gagawin mo?","o":["Umandar, dahil berde ang ilaw","Bumusina para umalis ang pulis","Huminto at sundin ang pulis","Kumanan para lumihis paikot sa pulis"],"h1":"Isipin kung sino ang nakakakita ng tunay na sitwasyon sa sandaling iyon.","h2":"Dapat mong sundin ang utos ng pulis na nagdidirekta ng trapiko, kahit iba ito sa sinasabi ng ilaw trapiko.","p":"Tama. Mas nauuna ang utos ng pulis kaysa sa ilaw trapiko."},"ar":{"q":"شرطي ينظّم السير في تقاطع. الإشارة خضراء، لكن الشرطي يشير لك أن تتوقف. ماذا تفعل؟","o":["انطلق، لأن الإشارة خضراء","استخدم البوق لكي يتحرك الشرطي","توقف واتبع تعليمات الشرطي","انعطف يمينًا لتمر من حول الشرطي"],"h1":"فكّر في من يرى الوضع الحقيقي في تلك اللحظة.","h2":"يجب أن تتبع تعليمات الشرطي الذي ينظّم السير، حتى عندما تكون مختلفة عن إشارة المرور.","p":"صحيح. تعليمات الشرطي تأتي قبل إشارة المرور."},"ht":{"q":"Yon polis ap dirije trafik nan yon kafou. Limyè a vèt, men polis la fè ou siy pou kanpe. Kisa ou fè?","o":["Pase, paske limyè a vèt","Klaksonen pou polis la deplase","Kanpe epi swiv polis la","Vire adwat pou pase bò kote polis la"],"h1":"Panse ak kiyès ki wè sa k ap pase vre nan moman an.","h2":"Ou dwe swiv sa yon polis k ap dirije trafik di ou, menm lè sa diferan ak limyè trafik la.","p":"Se sa. Sa polis la di pase anvan limyè trafik la."},"ref":{"doc":"FL","page":51}},{"id":"signals-035","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"In a work zone, a flagger holds up a sign that says SLOW. What should you do?","o":["Stop and wait for a police officer","Slow down and go ahead with care, watching for workers","Keep your normal speed","Turn around and find another road"],"h1":"Think about who may be working close to the road.","h2":"A flagger showing a SLOW sign means you should slow down and go ahead with care, because workers and equipment may be near the road.","p":"Right. A SLOW paddle means slow down and drive with care."},"es":{"q":"En una zona de trabajo, un abanderado levanta un letrero que dice SLOW (despacio). ¿Qué debe hacer?","o":["Parar y esperar a un policía","Bajar la velocidad y seguir con cuidado, fijándose en los trabajadores","Mantener su velocidad normal","Dar la vuelta y buscar otra calle"],"h1":"Piense en quién puede estar trabajando cerca de la calle.","h2":"Un abanderado que muestra el letrero SLOW significa que usted debe bajar la velocidad y seguir con cuidado, porque puede haber trabajadores y máquinas cerca de la calle.","p":"Correcto. El letrero SLOW significa baje la velocidad y maneje con cuidado."},"zh":{"q":"在施工区，一名旗手举起一个写着 “SLOW”（慢行）的牌子。你应该怎么做？","o":["停车，等警察来","减速，小心往前开，注意工人","保持平常的速度","掉头另找一条路"],"h1":"想一想：谁可能在路边很近的地方工作。","h2":"旗手举着 “SLOW”（慢行）牌子，表示你应该减速，小心往前开，因为路边可能有工人和机械。","p":"对。“SLOW” 牌子表示减速，小心开车。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển ghi “SLOW” (Chạy chậm). Bạn nên làm gì?","o":["Dừng lại và chờ cảnh sát","Chạy chậm lại và đi tiếp cẩn thận, chú ý công nhân","Giữ tốc độ bình thường","Quay đầu và tìm đường khác"],"h1":"Hãy nghĩ xem ai có thể đang làm việc sát bên đường.","h2":"Người cầm biển giơ biển “SLOW” nghĩa là bạn cần chạy chậm lại và đi tiếp cẩn thận, vì công nhân và máy móc có thể ở gần đường.","p":"Đúng rồi. Biển “SLOW” nghĩa là chạy chậm lại và lái cẩn thận."},"tl":{"q":"Sa work zone, may flagger na nagtataas ng karatulang nakasulat ang “SLOW” (Bumagal). Ano ang dapat mong gawin?","o":["Huminto at maghintay ng pulis","Bumagal at magpatuloy nang maingat, habang nagbabantay sa mga trabahador","Panatilihin ang karaniwan mong bilis","Umikot pabalik at maghanap ng ibang daan"],"h1":"Isipin kung sino ang maaaring nagtatrabaho malapit sa kalsada.","h2":"Ang flagger na nagpapakita ng “SLOW” na karatula ay nangangahulugang dapat kang bumagal at magpatuloy nang maingat, dahil maaaring may mga trabahador at kagamitan malapit sa kalsada.","p":"Tama. Ang “SLOW” na paddle ay nangangahulugang bumagal at magmaneho nang maingat."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع لافتة مكتوب عليها «SLOW» (ببطء). ماذا يجب أن تفعل؟","o":["توقف وانتظر شرطيًا","خفف السرعة وتابع بحذر، وانتبه للعمال","حافظ على سرعتك العادية","استدر عائدًا وابحث عن طريق آخر"],"h1":"فكّر في من قد يعمل قريبًا من الطريق.","h2":"عندما يُظهر عامل تنظيم السير لافتة «SLOW»، يجب أن تخفف السرعة وتتابع بحذر، لأن العمال والمعدات قد يكونون قرب الطريق.","p":"صحيح. لوحة «SLOW» تعني: خفف السرعة وقُد بحذر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la leve yon pankat ki di “SLOW” (ralanti). Kisa ou dwe fè?","o":["Kanpe epi tann yon polis","Ralanti epi kontinye avèk prekosyon, pandan w ap veye travayè yo","Kenbe vitès nòmal ou","Vire tounen epi chèche yon lòt wout"],"h1":"Panse ak kiyès ki ka ap travay toupre wout la.","h2":"Yon travayè ki montre yon pankat “SLOW” vle di ou dwe ralanti epi kontinye avèk prekosyon, paske ka gen travayè ak machin travay toupre wout la.","p":"Se sa. Yon pankat “SLOW” vle di ralanti epi kondui avèk prekosyon."},"ref":{"doc":"FL","page":54}},{"id":"signals-036","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A flagger in a work zone holds up a STOP sign, but the traffic light ahead is green. What should you do?","o":["Follow the green light and go","Slow down but keep moving","Pass the flagger on the shoulder","Stop and wait until the flagger lets you go"],"h1":"Think about who is in charge of traffic in a work zone.","h2":"You must obey a flagger in a work zone, so you stop when the flagger shows STOP, even if a traffic light is green.","p":"Right. A flagger’s STOP sign comes before a green light."},"es":{"q":"Un abanderado en una zona de trabajo levanta un letrero de STOP (pare), pero el semáforo de adelante está en verde. ¿Qué debe hacer?","o":["Seguir la luz verde y pasar","Bajar la velocidad pero seguir","Pasar al abanderado por el paseo","Parar y esperar hasta que el abanderado le deje pasar"],"h1":"Piense quién dirige el tráfico en una zona de trabajo.","h2":"Usted debe obedecer al abanderado en una zona de trabajo, así que para cuando el abanderado muestra STOP, aunque el semáforo esté en verde.","p":"Correcto. El letrero STOP del abanderado va antes que la luz verde."},"zh":{"q":"施工区的一名旗手举起 “STOP”（停）牌子，但前面的红绿灯是绿灯。你应该怎么做？","o":["按绿灯开走","减速但继续开","从路肩超过旗手","停车，等旗手让你走"],"h1":"想一想：在施工区里是谁在管交通。","h2":"在施工区你必须服从旗手，所以旗手举起 “STOP” 时你要停车，就算红绿灯是绿灯也一样。","p":"对。旗手的 “STOP” 牌子比绿灯优先。"},"vi":{"q":"Người cầm biển trong khu vực thi công giơ biển “STOP”, nhưng đèn giao thông phía trước đang xanh. Bạn nên làm gì?","o":["Làm theo đèn xanh và đi","Chạy chậm lại nhưng vẫn tiếp tục chạy","Vượt qua người cầm biển bằng lề đường","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Hãy nghĩ xem ai là người điều khiển giao thông trong khu vực thi công.","h2":"Bạn phải làm theo người cầm biển trong khu vực thi công, nên bạn dừng lại khi người đó giơ biển “STOP”, kể cả khi đèn giao thông đang xanh.","p":"Đúng rồi. Biển “STOP” của người cầm biển được ưu tiên hơn đèn xanh."},"tl":{"q":"May flagger sa work zone na nagtataas ng “STOP” na karatula, pero berde ang ilaw trapiko sa unahan. Ano ang dapat mong gawin?","o":["Sundin ang berdeng ilaw at umandar","Bumagal pero magpatuloy sa pag-andar","Lampasan ang flagger sa gilid ng kalsada","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Isipin kung sino ang namamahala sa trapiko sa work zone.","h2":"Dapat mong sundin ang flagger sa work zone, kaya huminto ka kapag ipinakita ng flagger ang “STOP”, kahit berde pa ang ilaw trapiko.","p":"Tama. Mas nauuna ang “STOP” na karatula ng flagger kaysa sa berdeng ilaw."},"ar":{"q":"عامل تنظيم السير في منطقة عمل يرفع لافتة «STOP» (قف)، لكن إشارة المرور أمامك خضراء. ماذا يجب أن تفعل؟","o":["اتبع الضوء الأخضر وانطلق","خفف السرعة لكن استمر في التحرك","تجاوز العامل من كتف الطريق","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"فكّر في من المسؤول عن السير في منطقة العمل.","h2":"يجب أن تطيع عامل تنظيم السير في منطقة العمل، لذلك تتوقف عندما يُظهر العامل «STOP»، حتى لو كانت إشارة المرور خضراء.","p":"صحيح. لافتة «STOP» التي يحملها العامل تأتي قبل الضوء الأخضر."},"ht":{"q":"Yon travayè ki dirije trafik nan yon zòn travay leve yon pankat “STOP”, men limyè trafik devan an vèt. Kisa ou dwe fè?","o":["Swiv limyè vèt la epi pase","Ralanti men kontinye avanse","Pase bò kote travayè a sou arebò wout la","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Panse ak kiyès ki responsab trafik la nan yon zòn travay.","h2":"Ou dwe obeyi travayè ki dirije trafik nan yon zòn travay, kidonk ou kanpe lè li montre “STOP”, menm si yon limyè trafik vèt.","p":"Se sa. Pankat “STOP” travayè a pase anvan yon limyè vèt."},"ref":{"doc":"FL","page":54}},{"id":"signals-037","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Which should you obey first: a traffic light, a stop sign, or a police officer directing traffic?","o":["The police officer","The traffic light","The stop sign","Whichever is closest to you"],"h1":"Signs and lights are set ahead of time. Think about who can react to what is happening now.","h2":"A police officer directing traffic comes first, before any traffic light or sign, because the officer is handling what is happening right now.","p":"Right. An officer directing traffic comes before lights and signs."},"es":{"q":"¿A quién debe obedecer primero: a un semáforo, a una señal de pare o a un policía que dirige el tráfico?","o":["Al policía","Al semáforo","A la señal de pare","Al que esté más cerca de usted"],"h1":"Las señales y los semáforos se ponen con anticipación. Piense quién puede reaccionar a lo que pasa ahora.","h2":"Un policía que dirige el tráfico va primero, antes que cualquier semáforo o señal, porque el policía maneja lo que está pasando en ese momento.","p":"Correcto. Un policía que dirige el tráfico va antes que los semáforos y las señales."},"zh":{"q":"红绿灯、停车标志、指挥交通的警察，你应该先服从哪一个？","o":["警察","红绿灯","停车标志","离你最近的那一个"],"h1":"标志和灯是提前设定好的。想一想谁能对眼前发生的事做出反应。","h2":"指挥交通的警察最优先，比任何红绿灯或标志都优先，因为警察在处理眼前正在发生的情况。","p":"对。指挥交通的警察比灯和标志优先。"},"vi":{"q":"Bạn nên làm theo điều nào trước tiên: đèn giao thông, biển dừng, hay cảnh sát đang điều khiển giao thông?","o":["Cảnh sát","Đèn giao thông","Biển dừng","Cái nào gần bạn nhất"],"h1":"Biển và đèn được cài đặt từ trước. Hãy nghĩ xem ai có thể phản ứng với điều đang xảy ra ngay lúc này.","h2":"Cảnh sát đang điều khiển giao thông được ưu tiên trước, hơn mọi đèn giao thông hay biển báo, vì cảnh sát đang xử lý điều đang xảy ra ngay lúc đó.","p":"Đúng rồi. Cảnh sát điều khiển giao thông được ưu tiên hơn đèn và biển báo."},"tl":{"q":"Alin ang dapat mong unang sundin: ang ilaw trapiko, ang “STOP” sign, o ang pulis na nagdidirekta ng trapiko?","o":["Ang pulis","Ang ilaw trapiko","Ang “STOP” sign","Kung alin ang pinakamalapit sa iyo"],"h1":"Ang mga karatula at ilaw ay nakatakda na nang maaga. Isipin kung sino ang nakakatugon sa nangyayari ngayon.","h2":"Ang pulis na nagdidirekta ng trapiko ang nauuna, bago ang anumang ilaw trapiko o karatula, dahil hinaharap ng pulis ang nangyayari mismo sa sandaling iyon.","p":"Tama. Mas nauuna ang pulis na nagdidirekta ng trapiko kaysa sa mga ilaw at karatula."},"ar":{"q":"أيها يجب أن تطيع أولًا: إشارة المرور، أم لافتة «STOP» (قف)، أم شرطي ينظّم السير؟","o":["الشرطي","إشارة المرور","لافتة «STOP»","أيها أقرب إليك"],"h1":"اللافتات والإشارات مضبوطة مسبقًا. فكّر في من يستطيع أن يتصرف حسب ما يحدث الآن.","h2":"الشرطي الذي ينظّم السير يأتي أولًا، قبل أي إشارة مرور أو لافتة، لأنه يتعامل مع ما يحدث الآن.","p":"صحيح. الشرطي الذي ينظّم السير يأتي قبل الإشارات واللافتات."},"ht":{"q":"Kiyès ou dwe obeyi anvan: yon limyè trafik, yon siy “STOP”, oswa yon polis k ap dirije trafik?","o":["Polis la","Limyè trafik la","Siy “STOP” la","Sa ki pi pre ou a"],"h1":"Siy ak limyè yo regle davans. Panse ak kiyès ki ka reyaji ak sa k ap pase kounye a.","h2":"Yon polis k ap dirije trafik pase anvan, devan nenpòt limyè trafik oswa siy, paske polis la ap jere sa k ap pase kounye a menm.","p":"Se sa. Yon polis k ap dirije trafik pase anvan limyè ak siy yo."},"ref":{"doc":"FL","page":51}},{"id":"signals-038","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"On a divided highway, what color is the solid line along the left edge of your lanes?","o":["White","Blue","Yellow","Red"],"h1":"Think about which color is used for the side closest to traffic going the other way.","h2":"On a divided highway, the left edge line is yellow and the right edge line is white, which helps you see the side toward opposite traffic.","p":"Right. The left edge line is yellow; the right edge line is white."},"es":{"q":"En una autopista dividida, ¿de qué color es la línea continua del borde izquierdo de sus carriles?","o":["Blanca","Azul","Amarilla","Roja"],"h1":"Piense qué color se usa para el lado más cerca del tráfico que va en sentido contrario.","h2":"En una autopista dividida, la línea del borde izquierdo es amarilla y la del borde derecho es blanca, lo que le ayuda a ver el lado del tráfico contrario.","p":"Correcto. La línea del borde izquierdo es amarilla; la del derecho es blanca."},"zh":{"q":"在分隔公路上，你的车道左边缘的实线是什么颜色？","o":["白色","蓝色","黄色","红色"],"h1":"想一想：靠近对向车流的那一边用什么颜色。","h2":"在分隔公路上，左边缘线是黄色，右边缘线是白色，这能帮你看清哪一边靠近对向车流。","p":"对。左边缘线是黄色，右边缘线是白色。"},"vi":{"q":"Trên đường có dải phân cách, vạch liền dọc theo mép trái các làn của bạn có màu gì?","o":["Trắng","Xanh dương","Vàng","Đỏ"],"h1":"Hãy nghĩ xem màu nào được dùng cho phía gần xe chạy ngược chiều nhất.","h2":"Trên đường có dải phân cách, vạch mép trái màu vàng và vạch mép phải màu trắng, giúp bạn nhận ra phía có xe chạy ngược chiều.","p":"Đúng rồi. Vạch mép trái màu vàng; vạch mép phải màu trắng."},"tl":{"q":"Sa divided highway, anong kulay ang tuloy-tuloy na linya sa kaliwang gilid ng mga lane mo?","o":["Puti","Asul","Dilaw","Pula"],"h1":"Isipin kung aling kulay ang ginagamit para sa bahaging pinakamalapit sa trapikong papunta sa kabilang direksyon.","h2":"Sa divided highway, dilaw ang linya sa kaliwang gilid at puti ang linya sa kanang gilid, na tumutulong sa iyo na makita ang bahaging nakaharap sa kasalungat na trapiko.","p":"Tama. Dilaw ang linya sa kaliwang gilid; puti ang linya sa kanang gilid."},"ar":{"q":"في طريق سريع مقسوم، ما لون الخط المتصل على الحافة اليسرى لمساراتك؟","o":["أبيض","أزرق","أصفر","أحمر"],"h1":"فكّر في اللون الذي يُستخدم للجانب الأقرب إلى السيارات التي تسير في الاتجاه الآخر.","h2":"في الطريق السريع المقسوم، خط الحافة اليسرى أصفر وخط الحافة اليمنى أبيض، وهذا يساعدك على رؤية الجانب القريب من السيارات المعاكسة.","p":"صحيح. خط الحافة اليسرى أصفر، وخط الحافة اليمنى أبيض."},"ht":{"q":"Sou yon wout ki gen separasyon, ki koulè liy plen ki sou bò goch koulwa ou yo?","o":["Blan","Ble","Jòn","Wouj"],"h1":"Panse ak ki koulè yo sèvi pou bò ki pi pre machin k ap ale nan lòt direksyon an.","h2":"Sou yon wout ki gen separasyon, liy bò goch la jòn epi liy bò dwat la blan, sa ki ede ou wè bò ki vire sou machin k ap ale nan direksyon opoze a.","p":"Se sa. Liy bò goch la jòn; liy bò dwat la blan."},"ref":{"doc":"FL","page":43}},{"id":"signals-039","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"On a traffic light that hangs up and down (vertical), where is the red light?","o":["At the bottom","In the middle","It can be anywhere","At the top"],"h1":"The order is the same on every vertical signal.","h2":"On a vertical traffic light, red is always at the top, yellow is in the middle and green is at the bottom.","p":"Right. Red is always on top."},"es":{"q":"En un semáforo que cuelga de arriba hacia abajo (vertical), ¿dónde está la luz roja?","o":["Abajo","En el medio","Puede estar en cualquier lugar","Arriba"],"h1":"El orden es igual en todos los semáforos verticales.","h2":"En un semáforo vertical, el rojo siempre está arriba, el amarillo en el medio y el verde abajo.","p":"Correcto. El rojo siempre está arriba."},"zh":{"q":"竖着挂（上下排列）的红绿灯，红灯在哪里？","o":["在最下面","在中间","哪里都有可能","在最上面"],"h1":"每个竖着的红绿灯，顺序都一样。","h2":"竖着的红绿灯上，红灯总是在最上面，黄灯在中间，绿灯在最下面。","p":"对。红灯总是在最上面。"},"vi":{"q":"Trên đèn giao thông treo dọc (từ trên xuống dưới), đèn đỏ nằm ở đâu?","o":["Ở dưới cùng","Ở giữa","Có thể ở bất cứ đâu","Ở trên cùng"],"h1":"Thứ tự giống nhau trên mọi đèn treo dọc.","h2":"Trên đèn giao thông treo dọc, đèn đỏ luôn ở trên cùng, đèn vàng ở giữa và đèn xanh ở dưới cùng.","p":"Đúng rồi. Đèn đỏ luôn ở trên cùng."},"tl":{"q":"Sa ilaw trapiko na nakabitin nang patayo (taas-baba), nasaan ang pulang ilaw?","o":["Sa ibaba","Sa gitna","Puwede itong kahit saan","Sa itaas"],"h1":"Pareho ang pagkakasunod sa bawat patayong ilaw trapiko.","h2":"Sa patayong ilaw trapiko, ang pula ay laging nasa itaas, ang dilaw ay nasa gitna at ang berde ay nasa ibaba.","p":"Tama. Laging nasa itaas ang pula."},"ar":{"q":"في إشارة المرور المعلّقة بشكل عمودي (من أعلى إلى أسفل)، أين يكون الضوء الأحمر؟","o":["في الأسفل","في الوسط","يمكن أن يكون في أي مكان","في الأعلى"],"h1":"الترتيب نفسه في كل إشارة عمودية.","h2":"في إشارة المرور العمودية، يكون الأحمر دائمًا في الأعلى، والأصفر في الوسط، والأخضر في الأسفل.","p":"صحيح. الأحمر دائمًا في الأعلى."},"ht":{"q":"Sou yon limyè trafik ki pandye kanpe (soti anwo desann anba), ki kote limyè wouj la ye?","o":["Anba nèt","Nan mitan","Li ka nenpòt ki kote","Anwo nèt"],"h1":"Lòd la menm jan sou tout limyè ki kanpe.","h2":"Sou yon limyè trafik ki kanpe, wouj toujou anwo nèt, jòn nan mitan epi vèt anba nèt.","p":"Se sa. Wouj toujou anwo."}},{"id":"signals-040","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"On a traffic light that hangs sideways (horizontal), where is the red light?","o":["On the left","On the right","In the middle","It can be anywhere"],"h1":"The position helps people who cannot tell colors apart.","h2":"On a horizontal traffic light, red is always on the left, so you can tell which light is on even if colors are hard to see.","p":"Right. Red is always on the left."},"es":{"q":"En un semáforo que cuelga de lado (horizontal), ¿dónde está la luz roja?","o":["A la izquierda","A la derecha","En el medio","Puede estar en cualquier lugar"],"h1":"La posición ayuda a quienes no distinguen bien los colores.","h2":"En un semáforo horizontal, el rojo siempre está a la izquierda, así que puede saber qué luz está encendida aunque le cueste ver los colores.","p":"Correcto. El rojo siempre está a la izquierda."},"zh":{"q":"横着挂（左右排列）的红绿灯，红灯在哪里？","o":["在最左边","在最右边","在中间","哪里都有可能"],"h1":"位置可以帮助分不清颜色的人。","h2":"横着的红绿灯上，红灯总是在最左边，所以就算看不清颜色，你也能知道哪个灯亮了。","p":"对。红灯总是在最左边。"},"vi":{"q":"Trên đèn giao thông treo ngang, đèn đỏ nằm ở đâu?","o":["Ở bên trái","Ở bên phải","Ở giữa","Có thể ở bất cứ đâu"],"h1":"Vị trí giúp những người không phân biệt được màu.","h2":"Trên đèn giao thông treo ngang, đèn đỏ luôn ở bên trái, nên bạn biết đèn nào đang sáng dù khó nhìn thấy màu.","p":"Đúng rồi. Đèn đỏ luôn ở bên trái."},"tl":{"q":"Sa ilaw trapiko na nakabitin nang pahiga (pahalang), nasaan ang pulang ilaw?","o":["Sa kaliwa","Sa kanan","Sa gitna","Puwede itong kahit saan"],"h1":"Nakakatulong ang puwesto sa mga taong hindi makilala ang mga kulay.","h2":"Sa pahalang na ilaw trapiko, ang pula ay laging nasa kaliwa, kaya malalaman mo kung aling ilaw ang nakasindi kahit mahirap makita ang mga kulay.","p":"Tama. Laging nasa kaliwa ang pula."},"ar":{"q":"في إشارة المرور المعلّقة بشكل أفقي (من جانب إلى جانب)، أين يكون الضوء الأحمر؟","o":["على اليسار","على اليمين","في الوسط","يمكن أن يكون في أي مكان"],"h1":"المكان يساعد الأشخاص الذين لا يميّزون الألوان.","h2":"في إشارة المرور الأفقية، يكون الأحمر دائمًا على اليسار، لذلك تعرف أي ضوء مضاء حتى لو كان من الصعب رؤية الألوان.","p":"صحيح. الأحمر دائمًا على اليسار."},"ht":{"q":"Sou yon limyè trafik ki pandye kouche (sou kote), ki kote limyè wouj la ye?","o":["Sou bò goch","Sou bò dwat","Nan mitan","Li ka nenpòt ki kote"],"h1":"Pozisyon an ede moun ki pa ka fè diferans ant koulè yo.","h2":"Sou yon limyè trafik ki kouche, wouj toujou sou bò goch, kidonk ou ka konnen ki limyè ki limen menm si li difisil pou w wè koulè yo.","p":"Se sa. Wouj toujou sou bò goch."}},{"id":"signals-041","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A yellow light flashes above a warning sign. What does it mean?","o":["Stop before the sign","Pay extra attention to what the warning sign says","The sign does not apply right now","The road is closed"],"h1":"A flashing yellow beacon calls attention.","h2":"A flashing yellow light on a warning sign means you should pay extra attention to the warning, because it applies right now.","p":"Right. Pay extra attention to the warning."},"es":{"q":"Una luz amarilla parpadea encima de una señal de advertencia. ¿Qué significa?","o":["Que se pare antes de la señal","Que preste más atención a lo que dice la señal","Que la señal no se aplica ahora","Que la vía está cerrada"],"h1":"Una luz amarilla intermitente llama la atención.","h2":"Una luz amarilla intermitente en una señal de advertencia significa que debe prestar más atención a la advertencia, porque se aplica en este momento.","p":"Correcto. Preste más atención a la advertencia."},"zh":{"q":"警告标志上方有黄灯在闪。这是什么意思？","o":["在标志前停车","要特别注意警告标志上说的内容","这个标志现在不适用","道路封闭了"],"h1":"闪烁的黄色警示灯是为了引起注意。","h2":"警告标志上的黄灯在闪，表示你要特别注意这个警告，因为它现在就适用。","p":"对。要特别注意这个警告。"},"vi":{"q":"Một đèn vàng nhấp nháy ở phía trên một biển cảnh báo. Điều đó có nghĩa là gì?","o":["Dừng lại trước biển","Hãy đặc biệt chú ý tới điều biển cảnh báo nói","Biển này hiện không có hiệu lực","Đường bị đóng"],"h1":"Đèn vàng nhấp nháy là để gây chú ý.","h2":"Đèn vàng nhấp nháy trên biển cảnh báo nghĩa là bạn cần đặc biệt chú ý tới lời cảnh báo, vì nó đang có hiệu lực ngay lúc này.","p":"Đúng rồi. Hãy đặc biệt chú ý tới lời cảnh báo."},"tl":{"q":"May kumikislap na dilaw na ilaw sa itaas ng isang babalang karatula. Ano ang ibig sabihin nito?","o":["Huminto bago ang karatula","Bigyan ng dagdag na pansin ang sinasabi ng babalang karatula","Hindi umiiral ang karatula sa ngayon","Sarado ang daan"],"h1":"Ang kumikislap na dilaw na ilaw ay para kumuha ng pansin.","h2":"Ang kumikislap na dilaw na ilaw sa isang babalang karatula ay nangangahulugang dapat mong bigyan ng dagdag na pansin ang babala, dahil umiiral ito ngayon mismo.","p":"Tama. Bigyan ng dagdag na pansin ang babala."},"ar":{"q":"ضوء أصفر يومض فوق لافتة تحذير. ماذا يعني ذلك؟","o":["توقف قبل اللافتة","انتبه أكثر لما تقوله لافتة التحذير","اللافتة لا تنطبق الآن","الطريق مغلق"],"h1":"الضوء الأصفر الوامض يلفت الانتباه.","h2":"الضوء الأصفر الوامض فوق لافتة تحذير يعني أنه يجب أن تنتبه أكثر للتحذير، لأنه ينطبق الآن.","p":"صحيح. انتبه أكثر للتحذير."},"ht":{"q":"Yon limyè jòn ap kliyote anwo yon siy avètisman. Kisa sa vle di?","o":["Kanpe anvan siy la","Fè plis atansyon ak sa siy avètisman an di","Siy la pa aplike kounye a","Wout la fèmen"],"h1":"Yon limyè jòn k ap kliyote la pou atire atansyon.","h2":"Yon limyè jòn k ap kliyote sou yon siy avètisman vle di ou dwe fè plis atansyon ak avètisman an, paske li aplike kounye a menm.","p":"Se sa. Fè plis atansyon ak avètisman an."}},{"id":"signals-042","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A red light flashes above a STOP sign. What must you do?","o":["Slow down without stopping","Wait until the light turns green","Stop fully, as the STOP sign says, then go when it is safe","Ignore the light; follow only the sign"],"h1":"The red light adds attention to the STOP sign.","h2":"A flashing red light above a STOP sign means you must come to a full stop, then go only when it is safe.","p":"Right. Stop fully, then go when safe."},"es":{"q":"Una luz roja parpadea encima de una señal de PARE. ¿Qué debe hacer?","o":["Bajar la velocidad sin pararse","Esperar a que la luz cambie a verde","Pararse por completo, como indica la señal, y seguir cuando sea seguro","Ignorar la luz y seguir solo la señal"],"h1":"La luz roja refuerza la señal de PARE.","h2":"Una luz roja intermitente encima de una señal de PARE significa que debe pararse por completo y seguir solo cuando sea seguro.","p":"Correcto. Párese por completo y siga cuando sea seguro."},"zh":{"q":"“STOP”（停车）标志上方有红灯在闪。你必须怎么做？","o":["减速，但不停车","等到灯变绿","按 “STOP” 标志的要求完全停车，安全时再走","不用管灯，只看标志"],"h1":"红灯是为了让人更注意 “STOP” 标志。","h2":"“STOP” 标志上方的红灯在闪，表示你必须完全停车，然后只有在安全时才走。","p":"对。完全停车，安全时再走。"},"vi":{"q":"Một đèn đỏ nhấp nháy ở phía trên biển “STOP” (Dừng lại). Bạn phải làm gì?","o":["Chạy chậm lại mà không dừng","Chờ tới khi đèn chuyển xanh","Dừng hẳn, như biển “STOP” yêu cầu, rồi đi khi an toàn","Bỏ qua đèn; chỉ làm theo biển"],"h1":"Đèn đỏ giúp biển “STOP” thu hút thêm sự chú ý.","h2":"Đèn đỏ nhấp nháy phía trên biển “STOP” nghĩa là bạn phải dừng hẳn, rồi chỉ đi khi an toàn.","p":"Đúng rồi. Dừng hẳn, rồi đi khi an toàn."},"tl":{"q":"May kumikislap na pulang ilaw sa itaas ng “STOP” sign (Huminto). Ano ang dapat mong gawin?","o":["Bumagal nang hindi humihinto","Maghintay hanggang maging berde ang ilaw","Huminto nang buo, gaya ng sinasabi ng “STOP” sign, at saka umandar kapag ligtas","Huwag pansinin ang ilaw; sundin lang ang karatula"],"h1":"Dinadagdagan ng pulang ilaw ang pansin sa “STOP” sign.","h2":"Ang kumikislap na pulang ilaw sa itaas ng “STOP” sign ay nangangahulugang dapat kang huminto nang buo, at saka umandar lang kapag ligtas.","p":"Tama. Huminto nang buo, at saka umandar kapag ligtas."},"ar":{"q":"ضوء أحمر يومض فوق لافتة «STOP» (قف). ماذا يجب أن تفعل؟","o":["خفّف السرعة من دون أن تتوقف","انتظر حتى يصبح الضوء أخضر","توقف تمامًا كما تقول لافتة «STOP»، ثم انطلق عندما يكون ذلك آمنًا","تجاهل الضوء واتبع اللافتة فقط"],"h1":"الضوء الأحمر يزيد الانتباه إلى لافتة «STOP».","h2":"الضوء الأحمر الوامض فوق لافتة «STOP» يعني أنه يجب أن تتوقف تمامًا، ثم تنطلق فقط عندما يكون ذلك آمنًا.","p":"صحيح. توقف تمامًا، ثم انطلق عندما يكون ذلك آمنًا."},"ht":{"q":"Yon limyè wouj ap kliyote anwo yon siy “STOP” (Kanpe). Kisa ou dwe fè?","o":["Ralanti san ou pa kanpe","Tann jiskaske limyè a vin vèt","Kanpe nèt, jan siy “STOP” la di a, epi pase lè sa an sekirite","Pa okipe limyè a; swiv siy la sèlman"],"h1":"Limyè wouj la atire plis atansyon sou siy “STOP” la.","h2":"Yon limyè wouj k ap kliyote anwo yon siy “STOP” vle di ou dwe kanpe nèt, epi pase sèlman lè sa an sekirite.","p":"Se sa. Kanpe nèt, epi pase lè sa an sekirite."}},{"id":"signals-043","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"At an intersection, the light facing you flashes yellow. The light facing the cross street flashes red. Who must stop?","o":["You must stop; the cross street goes ahead","Everyone must stop","No one needs to slow down","Drivers on the cross street must stop; you go ahead with care"],"h1":"Flashing red means stop. Flashing yellow means caution.","h2":"Drivers facing a flashing red light must stop, while you, facing flashing yellow, may go ahead with care, watching for anyone who does not stop.","p":"Right. The cross street stops; you proceed with care."},"es":{"q":"En una intersección, la luz que usted ve parpadea en amarillo. La luz de la calle transversal parpadea en rojo. ¿Quién debe pararse?","o":["Usted debe pararse; la calle transversal sigue","Todos deben pararse","Nadie necesita bajar la velocidad","Los de la calle transversal deben pararse; usted sigue con cuidado"],"h1":"Rojo intermitente es pare. Amarillo intermitente es precaución.","h2":"Los conductores con luz roja intermitente deben pararse, mientras usted, con amarillo intermitente, puede seguir con cuidado, atento a quien no se pare.","p":"Correcto. La transversal se para; usted sigue con cuidado."},"zh":{"q":"在路口，你这边的灯在闪黄灯，横向街道那边的灯在闪红灯。谁必须停车？","o":["你必须停车；横向街道的车先走","所有人都必须停车","谁都不用减速","横向街道的司机必须停车；你小心地继续开"],"h1":"闪红灯表示停车。闪黄灯表示小心。","h2":"面对闪红灯的司机必须停车，而你面对的是闪黄灯，可以小心地继续开，同时注意没有停车的人。","p":"对。横向街道的车要停；你小心地继续开。"},"vi":{"q":"Tại giao lộ, đèn hướng về phía bạn nhấp nháy vàng. Đèn hướng về đường cắt ngang nhấp nháy đỏ. Ai phải dừng lại?","o":["Bạn phải dừng; xe ở đường cắt ngang được đi","Mọi người đều phải dừng","Không ai cần chạy chậm lại","Tài xế ở đường cắt ngang phải dừng; bạn đi tiếp một cách cẩn thận"],"h1":"Đỏ nhấp nháy nghĩa là dừng. Vàng nhấp nháy nghĩa là cẩn thận.","h2":"Tài xế gặp đèn đỏ nhấp nháy phải dừng lại, còn bạn, gặp đèn vàng nhấp nháy, có thể đi tiếp một cách cẩn thận, để ý những ai không dừng.","p":"Đúng rồi. Xe ở đường cắt ngang dừng; bạn đi tiếp cẩn thận."},"tl":{"q":"Sa isang interseksyon, kumikislap na dilaw ang ilaw na nakaharap sa iyo. Kumikislap na pula ang ilaw na nakaharap sa kabilang kalye. Sino ang dapat huminto?","o":["Ikaw ang dapat huminto; tuloy ang kabilang kalye","Lahat ay dapat huminto","Walang kailangang bumagal","Ang mga driver sa kabilang kalye ang dapat huminto; magpatuloy ka nang maingat"],"h1":"Ang kumikislap na pula ay huminto. Ang kumikislap na dilaw ay mag-ingat.","h2":"Dapat huminto ang mga driver na nakaharap sa kumikislap na pulang ilaw, habang ikaw, na nakaharap sa kumikislap na dilaw, ay puwedeng magpatuloy nang maingat at bantayan ang sinumang hindi humihinto.","p":"Tama. Ang kabilang kalye ang hihinto; magpatuloy ka nang maingat."},"ar":{"q":"عند تقاطع، الضوء المقابل لك يومض بالأصفر. والضوء المقابل للشارع المتقاطع يومض بالأحمر. مَن يجب أن يتوقف؟","o":["أنت يجب أن تتوقف، والشارع المتقاطع يمضي","الجميع يجب أن يتوقفوا","لا أحد يحتاج إلى تخفيف السرعة","السائقون في الشارع المتقاطع يجب أن يتوقفوا، وأنت تمضي بحذر"],"h1":"الأحمر الوامض يعني توقف. الأصفر الوامض يعني احذر.","h2":"السائقون الذين يواجهون ضوءًا أحمر وامضًا يجب أن يتوقفوا، أما أنت فتواجه ضوءًا أصفر وامضًا، لذلك يمكنك أن تمضي بحذر وتراقب أي شخص لا يتوقف.","p":"صحيح. الشارع المتقاطع يتوقف، وأنت تمضي بحذر."},"ht":{"q":"Nan yon kafou, limyè ki devan ou a ap kliyote jòn. Limyè ki devan lòt lari a ap kliyote wouj. Kiyès ki dwe kanpe?","o":["Se ou ki dwe kanpe; lòt lari a pase","Tout moun dwe kanpe","Pèsonn pa bezwen ralanti","Chofè ki sou lòt lari a dwe kanpe; ou menm, ou pase ak prekosyon"],"h1":"Wouj k ap kliyote vle di kanpe. Jòn k ap kliyote vle di fè atansyon.","h2":"Chofè ki gen yon limyè wouj k ap kliyote devan yo dwe kanpe, alòske ou menm, ki gen limyè jòn k ap kliyote a, ou ka pase ak prekosyon epi veye nenpòt moun ki pa kanpe.","p":"Se sa. Lòt lari a kanpe; ou menm, ou pase ak prekosyon."}},{"id":"signals-045","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A pedestrian signal shows a steady (not flashing) raised hand. What does it mean for people on foot?","o":["Start crossing now","Do not enter the street","Cross quickly","Cross only in the middle of the block"],"h1":"A steady hand means wait.","h2":"A steady raised hand means people on foot must not enter the street in that direction.","p":"Right. Do not enter the street."},"es":{"q":"Una señal peatonal muestra una mano levantada fija (sin parpadear). ¿Qué significa para los peatones?","o":["Empezar a cruzar ahora","No entrar a la calle","Cruzar rápido","Cruzar solo a mitad de cuadra"],"h1":"Una mano fija significa esperar.","h2":"Una mano levantada fija significa que los peatones no deben entrar a la calle en esa dirección.","p":"Correcto. No entrar a la calle."},"zh":{"q":"行人信号灯显示一只一直亮着（不闪）的举起的手。这对步行的人是什么意思？","o":["现在开始过马路","不要走进街道","快点过马路","只在街区中间过马路"],"h1":"一直亮着的手表示等待。","h2":"一直亮着的举起的手表示步行的人不可以朝那个方向走进街道。","p":"对。不要走进街道。"},"vi":{"q":"Đèn cho người đi bộ hiện hình bàn tay giơ lên sáng đứng yên (không nhấp nháy). Điều đó có nghĩa gì với người đi bộ?","o":["Bắt đầu băng qua đường ngay","Không được bước xuống đường","Băng qua thật nhanh","Chỉ băng qua ở giữa dãy nhà"],"h1":"Bàn tay sáng đứng yên nghĩa là chờ.","h2":"Bàn tay giơ lên sáng đứng yên nghĩa là người đi bộ không được bước xuống đường theo hướng đó.","p":"Đúng rồi. Không được bước xuống đường."},"tl":{"q":"Ang signal para sa naglalakad ay nagpapakita ng tuloy-tuloy (hindi kumikislap) na nakataas na kamay. Ano ang ibig sabihin nito para sa mga naglalakad?","o":["Magsimulang tumawid ngayon","Huwag pumasok sa kalye","Tumawid nang mabilis","Tumawid lang sa gitna ng block"],"h1":"Ang tuloy-tuloy na kamay ay nangangahulugang maghintay.","h2":"Ang tuloy-tuloy na nakataas na kamay ay nangangahulugang hindi dapat pumasok sa kalye ang mga naglalakad sa direksyong iyon.","p":"Tama. Huwag pumasok sa kalye."},"ar":{"q":"إشارة المشاة تُظهر يدًا مرفوعة ثابتة (لا تومض). ماذا يعني ذلك للأشخاص الذين يمشون؟","o":["ابدأ العبور الآن","لا تدخل إلى الشارع","اعبر بسرعة","اعبر فقط في منتصف المربع السكني"],"h1":"اليد الثابتة تعني انتظر.","h2":"اليد المرفوعة الثابتة تعني أنه يجب ألّا يدخل المشاة إلى الشارع في ذلك الاتجاه.","p":"صحيح. لا تدخل إلى الشارع."},"ht":{"q":"Yon siyal pou pyeton montre yon men leve ki fiks (ki pa kliyote). Kisa sa vle di pou moun ki a pye?","o":["Kòmanse travèse kounye a","Pa antre nan lari a","Travèse vit","Travèse sèlman nan mitan blòk la"],"h1":"Yon men fiks vle di tann.","h2":"Yon men leve ki fiks vle di moun ki a pye pa dwe antre nan lari a nan direksyon sa a.","p":"Se sa. Pa antre nan lari a."}},{"id":"signals-046","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"At a crosswalk, you hear beeping or a voice saying the walk sign is on. What is it for?","o":["To tell drivers to speed up","To warn of a train","To help people who are blind or have low vision know when to cross","To tell drivers the light is broken"],"h1":"Some people cannot see the walk signal.","h2":"Accessible pedestrian signals make sounds or speak so that people who are blind or have low vision know when the walk signal is on.","p":"Right. It helps people who cannot see the signal."},"es":{"q":"En un cruce peatonal, usted oye pitidos o una voz que dice que la señal para cruzar está encendida. ¿Para qué es?","o":["Para decirles a los conductores que aceleren","Para advertir de un tren","Para que las personas ciegas o con baja visión sepan cuándo cruzar","Para avisar que el semáforo está dañado"],"h1":"Algunas personas no pueden ver la señal peatonal.","h2":"Las señales peatonales accesibles hacen sonidos o hablan para que las personas ciegas o con baja visión sepan cuándo está encendida la señal de cruzar.","p":"Correcto. Ayuda a quienes no pueden ver la señal."},"zh":{"q":"在人行横道，你听到哔哔声，或者有声音说可以走了。这是做什么用的？","o":["告诉司机加速","提醒有火车来","帮助盲人或视力差的人知道什么时候可以过马路","告诉司机信号灯坏了"],"h1":"有些人看不见行人通行信号。","h2":"无障碍行人信号会发出声音或说话，让盲人或视力差的人知道行人通行信号什么时候亮了。","p":"对。它帮助看不见信号的人。"},"vi":{"q":"Tại vạch qua đường, bạn nghe tiếng bíp hoặc một giọng nói báo đèn cho người đi bộ đã bật. Cái đó dùng để làm gì?","o":["Để bảo tài xế tăng tốc","Để cảnh báo có xe lửa","Để giúp người mù hoặc thị lực kém biết khi nào băng qua đường","Để báo tài xế đèn bị hư"],"h1":"Có những người không nhìn thấy đèn cho người đi bộ.","h2":"Đèn cho người đi bộ có hỗ trợ tiếp cận phát ra âm thanh hoặc lời nói để người mù hoặc thị lực kém biết khi nào đèn cho đi bộ đang bật.","p":"Đúng rồi. Nó giúp những người không nhìn thấy đèn."},"tl":{"q":"Sa tawiran, nakarinig ka ng beep o ng boses na nagsasabing naka-on ang walk signal. Para saan ito?","o":["Para sabihan ang mga driver na bumilis","Para magbabala na may tren","Para matulungan ang mga bulag o malabo ang paningin na malaman kung kailan tatawid","Para sabihan ang mga driver na sira ang ilaw"],"h1":"May mga taong hindi nakikita ang walk signal.","h2":"Ang mga accessible pedestrian signal ay gumagawa ng tunog o nagsasalita para malaman ng mga bulag o malabo ang paningin kung kailan naka-on ang walk signal.","p":"Tama. Tumutulong ito sa mga taong hindi nakikita ang signal."},"ar":{"q":"عند ممر المشاة، تسمع صفيرًا أو صوتًا يقول إن إشارة العبور مضاءة. ما فائدة ذلك؟","o":["ليطلب من السائقين زيادة السرعة","ليحذّر من قطار","ليساعد الأشخاص المكفوفين أو ضعاف البصر على معرفة وقت العبور","ليخبر السائقين أن الإشارة معطّلة"],"h1":"بعض الناس لا يستطيعون رؤية إشارة العبور.","h2":"إشارات المشاة الصوتية تُصدر أصواتًا أو تتكلم لكي يعرف الأشخاص المكفوفون أو ضعاف البصر متى تكون إشارة العبور مضاءة.","p":"صحيح. إنها تساعد الأشخاص الذين لا يستطيعون رؤية الإشارة."},"ht":{"q":"Nan yon pasaj pyeton, ou tande yon bip oswa yon vwa k ap di siyal pou mache a limen. Pou kisa sa ye?","o":["Pou di chofè yo akselere","Pou avèti gen yon tren","Pou ede moun ki avèg oswa ki pa wè byen konnen ki lè pou yo travèse","Pou di chofè yo limyè a pa mache"],"h1":"Gen moun ki pa ka wè siyal pou mache a.","h2":"Siyal pyeton aksesib yo fè son oswa yo pale pou moun ki avèg oswa ki pa wè byen konnen ki lè siyal pou mache a limen.","p":"Se sa. Li ede moun ki pa ka wè siyal la."}},{"id":"signals-047","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"At a crosswalk in the middle of a block, a pedestrian hybrid beacon (two red lights side by side above one yellow light) is dark, with no lights on. What does that mean?","o":["You must stop","The signal is broken, so stop","Treat it as a flashing yellow","No one has asked to cross; drive normally but watch for people"],"h1":"This kind of signal turns on only when a person pushes the button.","h2":"A pedestrian hybrid beacon stays dark until someone pushes the button, so when it is dark you may drive normally while watching for people.","p":"Right. Dark means no one is crossing yet."},"es":{"q":"En un cruce peatonal a mitad de cuadra, un semáforo híbrido peatonal (dos luces rojas lado a lado sobre una luz amarilla) está apagado, sin ninguna luz. ¿Qué significa?","o":["Debe pararse","El semáforo está dañado, así que párese","Trátelo como un amarillo intermitente","Nadie ha pedido cruzar; maneje normalmente pero fíjese en los peatones"],"h1":"Este tipo de semáforo se enciende solo cuando alguien aprieta el botón.","h2":"Un semáforo híbrido peatonal está apagado hasta que alguien aprieta el botón, así que cuando está apagado puede manejar normalmente, atento a los peatones.","p":"Correcto. Apagado significa que nadie está cruzando aún."},"zh":{"q":"在街区中间的人行横道，有一个行人混合信号灯（两个并排的红灯，下面一个黄灯），它是暗的，一个灯都没亮。这是什么意思？","o":["你必须停车","信号灯坏了，所以要停车","当作闪黄灯来处理","没有人要求过马路；正常开车，但要注意行人"],"h1":"这种信号灯只有在有人按按钮时才会亮。","h2":"行人混合信号灯在有人按按钮之前一直是暗的，所以灯暗的时候你可以正常开车，同时注意行人。","p":"对。灯暗表示还没有人要过马路。"},"vi":{"q":"Tại vạch qua đường ở giữa dãy nhà, một đèn hỗn hợp cho người đi bộ (hai đèn đỏ nằm cạnh nhau ở trên một đèn vàng) đang tắt, không có đèn nào sáng. Điều đó có nghĩa là gì?","o":["Bạn phải dừng lại","Đèn bị hư, nên phải dừng","Xem như đèn vàng nhấp nháy","Chưa có ai xin băng qua đường; lái bình thường nhưng để ý người đi bộ"],"h1":"Loại đèn này chỉ bật khi có người bấm nút.","h2":"Đèn hỗn hợp cho người đi bộ luôn tắt cho tới khi có người bấm nút, nên khi đèn tắt bạn có thể lái bình thường trong khi để ý người đi bộ.","p":"Đúng rồi. Đèn tắt nghĩa là chưa có ai băng qua."},"tl":{"q":"Sa tawiran sa gitna ng block, madilim ang pedestrian hybrid beacon (dalawang pulang ilaw na magkatabi sa itaas ng isang dilaw na ilaw), at walang nakasinding ilaw. Ano ang ibig sabihin nito?","o":["Dapat kang huminto","Sira ang signal, kaya huminto","Ituring itong kumikislap na dilaw","Walang humiling na tumawid; magmaneho nang normal pero bantayan ang mga tao"],"h1":"Sumisindi lang ang ganitong signal kapag may pumindot ng button.","h2":"Nananatiling madilim ang pedestrian hybrid beacon hanggang may pumindot ng button, kaya kapag madilim ito, puwede kang magmaneho nang normal habang binabantayan ang mga tao.","p":"Tama. Ang madilim ay nangangahulugang wala pang tumatawid."},"ar":{"q":"عند ممر مشاة في منتصف المربع السكني، إشارة المشاة الهجينة (ضوءان أحمران متجاوران فوق ضوء أصفر واحد) مطفأة، ولا يوجد أي ضوء مضاء. ماذا يعني ذلك؟","o":["يجب أن تتوقف","الإشارة معطّلة، لذلك توقف","تعامل معها كضوء أصفر وامض","لم يطلب أحد العبور؛ قُد بشكل عادي لكن راقب الناس"],"h1":"هذا النوع من الإشارات يُضاء فقط عندما يضغط شخص على الزر.","h2":"إشارة المشاة الهجينة تبقى مطفأة حتى يضغط شخص على الزر، لذلك عندما تكون مطفأة يمكنك أن تقود بشكل عادي مع مراقبة الناس.","p":"صحيح. الإشارة المطفأة تعني أن لا أحد يعبر بعد."},"ht":{"q":"Nan yon pasaj pyeton nan mitan yon blòk, yon siyal ibrid pou pyeton (de limyè wouj youn bò lòt anwo yon sèl limyè jòn) etenn, pa gen okenn limyè ki limen. Kisa sa vle di?","o":["Ou dwe kanpe","Siyal la pa mache, kidonk kanpe","Konsidere l tankou yon jòn k ap kliyote","Pèsonn pa mande pou travèse; kondui nòmalman men veye moun"],"h1":"Kalite siyal sa a limen sèlman lè yon moun peze bouton an.","h2":"Yon siyal ibrid pou pyeton rete etenn jiskaske yon moun peze bouton an, kidonk lè li etenn ou ka kondui nòmalman pandan w ap veye moun.","p":"Se sa. Etenn vle di pèsonn poko ap travèse."}},{"id":"signals-048","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"At a mid-block crosswalk, a signal with two red lights side by side shows both reds steady. What must you do?","o":["Stop and stay stopped while people cross","Slow down and go if no one is in your lane","Go ahead; it is only for bicycles","Honk and go"],"h1":"Steady red always means stop.","h2":"When a pedestrian hybrid beacon shows steady red lights, you must stop and stay stopped while people cross.","p":"Right. Steady red: stop and stay stopped."},"es":{"q":"En un cruce a mitad de cuadra, un semáforo con dos luces rojas una al lado de la otra muestra ambas rojas fijas. ¿Qué debe hacer?","o":["Pararse y seguir parado mientras la gente cruza","Bajar la velocidad y seguir si no hay nadie en su carril","Seguir; es solo para bicicletas","Tocar la bocina y seguir"],"h1":"El rojo fijo siempre significa pare.","h2":"Cuando un semáforo híbrido peatonal muestra luces rojas fijas, usted debe pararse y seguir parado mientras la gente cruza.","p":"Correcto. Rojo fijo: párese y siga parado."},"zh":{"q":"在街区中间的人行横道，一个有两个并排红灯的信号灯，两个红灯都一直亮着。你必须怎么做？","o":["停车，行人过马路时一直停着","减速，如果你的车道上没人就走","继续开；它只管自行车","按喇叭然后走"],"h1":"一直亮着的红灯总是表示停车。","h2":"行人混合信号灯的红灯一直亮着时，你必须停车，并在行人过马路时一直停着。","p":"对。红灯一直亮：停车并一直停着。"},"vi":{"q":"Tại vạch qua đường ở giữa dãy nhà, một đèn có hai đèn đỏ nằm cạnh nhau đang sáng đứng yên cả hai. Bạn phải làm gì?","o":["Dừng lại và đứng yên trong khi người đi bộ băng qua","Chạy chậm lại và đi nếu không có ai trong làn của bạn","Cứ đi; đèn này chỉ dành cho xe đạp","Bấm còi rồi đi"],"h1":"Đèn đỏ sáng đứng yên luôn nghĩa là dừng lại.","h2":"Khi đèn hỗn hợp cho người đi bộ hiện đèn đỏ sáng đứng yên, bạn phải dừng lại và đứng yên trong khi người đi bộ băng qua.","p":"Đúng rồi. Đỏ sáng đứng yên: dừng lại và đứng yên."},"tl":{"q":"Sa tawiran sa gitna ng block, ang signal na may dalawang pulang ilaw na magkatabi ay nagpapakita ng parehong pulang ilaw na tuloy-tuloy. Ano ang dapat mong gawin?","o":["Huminto at manatiling nakahinto habang tumatawid ang mga tao","Bumagal at umandar kung walang tao sa iyong lane","Tumuloy; para lang ito sa mga bisikleta","Bumusina at umandar"],"h1":"Ang tuloy-tuloy na pula ay laging nangangahulugang huminto.","h2":"Kapag nagpapakita ng tuloy-tuloy na pulang ilaw ang pedestrian hybrid beacon, dapat kang huminto at manatiling nakahinto habang tumatawid ang mga tao.","p":"Tama. Tuloy-tuloy na pula: huminto at manatiling nakahinto."},"ar":{"q":"عند ممر مشاة في منتصف المربع السكني، إشارة فيها ضوءان أحمران متجاوران تُظهر الضوءين الأحمرين ثابتين. ماذا يجب أن تفعل؟","o":["توقف وابقَ متوقفًا بينما يعبر الناس","خفّف السرعة وانطلق إذا لم يكن أحد في مسارك","تابع؛ إنها للدراجات فقط","أطلق البوق وانطلق"],"h1":"الأحمر الثابت يعني دائمًا توقف.","h2":"عندما تُظهر إشارة المشاة الهجينة أضواء حمراء ثابتة، يجب أن تتوقف وتبقى متوقفًا بينما يعبر الناس.","p":"صحيح. الأحمر الثابت: توقف وابقَ متوقفًا."},"ht":{"q":"Nan yon pasaj pyeton nan mitan yon blòk, yon siyal ki gen de limyè wouj youn bò lòt montre toude wouj yo fiks. Kisa ou dwe fè?","o":["Kanpe epi rete kanpe pandan moun yo ap travèse","Ralanti epi pase si pa gen pèsonn nan liy ou","Pase; se pou bisiklèt sèlman","Klaksonen epi pase"],"h1":"Wouj fiks toujou vle di kanpe.","h2":"Lè yon siyal ibrid pou pyeton montre limyè wouj fiks, ou dwe kanpe epi rete kanpe pandan moun yo ap travèse.","p":"Se sa. Wouj fiks: kanpe epi rete kanpe."}},{"id":"signals-049","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"At a mid-block crosswalk, the two red lights above the road flash back and forth (wig-wag). What should you do?","o":["Keep going without stopping","Stop, then go only if the people have finished crossing","Stay stopped until the lights go dark, even if no one is there","Speed up before the lights turn steady"],"h1":"Flashing red works like a STOP sign.","h2":"Alternating flashing red lights mean stop, then you may go only after people in the crosswalk have finished crossing.","p":"Right. Stop, then go when the crosswalk is clear."},"es":{"q":"En un cruce a mitad de cuadra, las dos luces rojas sobre la vía parpadean de forma alterna. ¿Qué debe hacer?","o":["Seguir sin pararse","Pararse y seguir solo si las personas terminaron de cruzar","Quedarse parado hasta que se apaguen, aunque no haya nadie","Acelerar antes de que se queden fijas"],"h1":"El rojo intermitente funciona como una señal de PARE.","h2":"Las luces rojas intermitentes alternas significan pare, y puede seguir solo después de que las personas terminen de cruzar.","p":"Correcto. Párese y siga cuando el cruce esté libre."},"zh":{"q":"在街区中间的人行横道，路上方的两个红灯左右轮流闪（wig-wag）。你应该怎么做？","o":["不停车，继续开","先停车，只有行人都过完了才走","一直停着，直到灯灭，就算没有人也一样","在灯变成一直亮之前加速"],"h1":"闪红灯的作用和 “STOP” 标志一样。","h2":"交替闪烁的红灯表示要停车，然后只有在人行横道上的人都过完以后你才可以走。","p":"对。先停车，人行横道没人了再走。"},"vi":{"q":"Tại vạch qua đường ở giữa dãy nhà, hai đèn đỏ phía trên đường nhấp nháy luân phiên qua lại (wig-wag). Bạn nên làm gì?","o":["Cứ đi tiếp mà không dừng","Dừng lại, rồi chỉ đi nếu người đi bộ đã băng qua xong","Đứng yên tới khi đèn tắt, dù không có ai ở đó","Tăng tốc trước khi đèn chuyển sang sáng đứng yên"],"h1":"Đèn đỏ nhấp nháy giống như biển “STOP” (Dừng lại).","h2":"Đèn đỏ nhấp nháy luân phiên nghĩa là phải dừng lại, rồi bạn chỉ được đi sau khi người đi bộ trên vạch qua đường đã băng qua xong.","p":"Đúng rồi. Dừng lại, rồi đi khi vạch qua đường đã trống."},"tl":{"q":"Sa tawiran sa gitna ng block, ang dalawang pulang ilaw sa itaas ng daan ay salitang kumikislap (wig-wag). Ano ang dapat mong gawin?","o":["Magpatuloy nang hindi humihinto","Huminto, at saka umandar lang kung tapos nang tumawid ang mga tao","Manatiling nakahinto hanggang mamatay ang mga ilaw, kahit walang tao roon","Bumilis bago maging tuloy-tuloy ang mga ilaw"],"h1":"Ang kumikislap na pula ay gumagana na parang “STOP” sign.","h2":"Ang salitang kumikislap na pulang ilaw ay nangangahulugang huminto, at saka puwede ka lang umandar kapag tapos nang tumawid ang mga tao sa tawiran.","p":"Tama. Huminto, at saka umandar kapag maluwag na ang tawiran."},"ar":{"q":"عند ممر مشاة في منتصف المربع السكني، الضوءان الأحمران فوق الطريق يومضان بالتناوب (wig-wag). ماذا يجب أن تفعل؟","o":["استمر من دون أن تتوقف","توقف، ثم انطلق فقط إذا انتهى الناس من العبور","ابقَ متوقفًا حتى تنطفئ الأضواء، حتى لو لم يكن هناك أحد","زد السرعة قبل أن تصبح الأضواء ثابتة"],"h1":"الأحمر الوامض يعمل مثل لافتة «STOP» (قف).","h2":"الأضواء الحمراء التي تومض بالتناوب تعني توقف، ثم يمكنك أن تنطلق فقط بعد أن ينتهي الناس في ممر المشاة من العبور.","p":"صحيح. توقف، ثم انطلق عندما يكون ممر المشاة خاليًا."},"ht":{"q":"Nan yon pasaj pyeton nan mitan yon blòk, de limyè wouj anwo wout la ap kliyote youn apre lòt (wig-wag). Kisa ou dwe fè?","o":["Kontinye san ou pa kanpe","Kanpe, epi pase sèlman si moun yo fin travèse","Rete kanpe jiskaske limyè yo etenn, menm si pa gen pèsonn la","Akselere anvan limyè yo vin fiks"],"h1":"Wouj k ap kliyote mache tankou yon siy “STOP”.","h2":"Limyè wouj k ap kliyote youn apre lòt vle di kanpe, epi ou ka pase sèlman apre moun ki nan pasaj pyeton an fin travèse.","p":"Se sa. Kanpe, epi pase lè pasaj pyeton an lib."}},{"id":"signals-050","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"Under a pedestrian crossing sign, bright yellow lights flash very fast. What does it mean?","o":["The crosswalk is closed","Speed up to clear the crosswalk","Someone wants to cross, so be ready to stop and let them cross","A train is coming"],"h1":"A person pushed a button to turn these lights on.","h2":"Rapid flashing yellow lights at a crosswalk mean a person is crossing or about to cross, so slow down and be ready to stop for them.","p":"Right. Someone is crossing; be ready to stop."},"es":{"q":"Debajo de una señal de cruce peatonal, unas luces amarillas brillantes parpadean muy rápido. ¿Qué significa?","o":["Que el cruce está cerrado","Que acelere para despejar el cruce","Que alguien quiere cruzar, así que esté listo para pararse y dejarlo cruzar","Que viene un tren"],"h1":"Una persona apretó un botón para encender estas luces.","h2":"Las luces amarillas de destello rápido en un cruce significan que una persona está cruzando o va a cruzar, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Alguien cruza; esté listo para pararse."},"zh":{"q":"在行人过街标志下面，明亮的黄灯闪得很快。这是什么意思？","o":["人行横道关闭了","加速，快快开过人行横道","有人要过马路，所以准备停车让他们过去","火车要来了"],"h1":"是有人按了按钮，这些灯才亮起来的。","h2":"人行横道上快速闪烁的黄灯表示有人正在过马路或马上要过马路，所以你要减速，并准备停车让他们过去。","p":"对。有人在过马路，准备停车。"},"vi":{"q":"Dưới biển báo người đi bộ băng qua đường, đèn vàng sáng chớp rất nhanh. Điều đó có nghĩa là gì?","o":["Lối băng qua đường đã đóng","Tăng tốc để qua khỏi lối băng qua đường","Có người muốn băng qua, nên hãy sẵn sàng dừng lại để họ đi qua","Xe lửa đang tới"],"h1":"Có người đã bấm nút để bật những đèn này.","h2":"Đèn vàng chớp nhanh ở lối băng qua đường nghĩa là có người đang băng qua hoặc sắp băng qua, nên bạn cần chạy chậm lại và sẵn sàng dừng lại cho họ.","p":"Đúng rồi. Có người đang băng qua; hãy sẵn sàng dừng lại."},"tl":{"q":"Sa ilalim ng karatula ng tawiran ng tao, may matingkad na dilaw na ilaw na kumikislap nang napakabilis. Ano ang ibig sabihin nito?","o":["Sarado ang tawiran","Bumilis para malampasan ang tawiran","May gustong tumawid, kaya maging handang huminto at hayaan silang tumawid","May paparating na tren"],"h1":"May taong pumindot ng button para buksan ang mga ilaw na ito.","h2":"Ang mabilis na kumikislap na dilaw na ilaw sa tawiran ay nangangahulugang may taong tumatawid o malapit nang tumawid, kaya bumagal at maging handang huminto para sa kanila.","p":"Tama. May tumatawid; maging handang huminto."},"ar":{"q":"تحت لافتة عبور المشاة، تومض أضواء صفراء ساطعة بسرعة كبيرة. ماذا يعني ذلك؟","o":["ممر المشاة مغلق","زد السرعة لتخرج من ممر المشاة","شخص يريد العبور، لذلك كن مستعدًا للتوقف ودعه يعبر","قطار قادم"],"h1":"ضغط شخص على زر ليشغّل هذه الأضواء.","h2":"الأضواء الصفراء التي تومض بسرعة عند ممر المشاة تعني أن شخصًا يعبر أو على وشك أن يعبر، لذلك خفف السرعة وكن مستعدًا للتوقف له.","p":"صحيح. شخص يعبر؛ كن مستعدًا للتوقف."},"ht":{"q":"Anba yon pankat pasaj pou moun a pye, limyè jòn ki klere anpil ap flache vit vit. Kisa sa vle di?","o":["Pasaj pou moun a pye a fèmen","Akselere pou kite pasaj la","Gen yon moun ki vle travèse, kidonk pare pou kanpe epi kite l travèse","Yon tren ap vini"],"h1":"Yon moun peze yon bouton pou limen limyè sa yo.","h2":"Limyè jòn k ap flache vit nan yon pasaj pou moun a pye vle di gen yon moun k ap travèse oswa ki pral travèse, kidonk ralanti epi pare pou kanpe pou li.","p":"Se sa. Gen yon moun k ap travèse; pare pou kanpe."}},{"id":"signals-051","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"At an intersection, one traffic light shows the shape of a bicycle. Who does it control?","o":["All vehicles","Only buses","Only people walking","Only people riding bicycles"],"h1":"Look at the shape inside the light.","h2":"A traffic light with a bicycle symbol controls only bicycle riders; drivers follow the regular signals.","p":"Right. It is for bicycles only."},"es":{"q":"En una intersección, un semáforo muestra la figura de una bicicleta. ¿A quién controla?","o":["A todos los vehículos","Solo a los autobuses","Solo a los peatones","Solo a los ciclistas"],"h1":"Fíjese en la figura dentro de la luz.","h2":"Un semáforo con el símbolo de bicicleta controla solo a los ciclistas; los conductores siguen los semáforos normales.","p":"Correcto. Es solo para bicicletas."},"zh":{"q":"在一个路口，有一个红绿灯显示的是自行车的形状。它管的是谁？","o":["所有车辆","只管公交车","只管走路的人","只管骑自行车的人"],"h1":"看一看灯里面的形状。","h2":"带自行车图案的红绿灯只管骑自行车的人；开车的人要看普通的红绿灯。","p":"对。它只管自行车。"},"vi":{"q":"Ở một giao lộ, có một đèn giao thông hiện hình chiếc xe đạp. Đèn đó dành cho ai?","o":["Tất cả các loại xe","Chỉ xe buýt","Chỉ người đi bộ","Chỉ người đi xe đạp"],"h1":"Hãy nhìn hình bên trong đèn.","h2":"Đèn giao thông có hình xe đạp chỉ dành cho người đi xe đạp; người lái xe làm theo đèn giao thông thường.","p":"Đúng rồi. Đèn đó chỉ dành cho xe đạp."},"tl":{"q":"Sa isang interseksyon, may isang ilaw trapiko na hugis bisikleta. Para kanino ang ilaw na ito?","o":["Lahat ng sasakyan","Mga bus lang","Mga taong naglalakad lang","Mga taong nagbibisikleta lang"],"h1":"Tingnan ang hugis sa loob ng ilaw.","h2":"Ang ilaw trapiko na may larawan ng bisikleta ay para lang sa mga nagbibisikleta; ang mga drayber ay sumusunod sa karaniwang ilaw trapiko.","p":"Tama. Para lang ito sa mga bisikleta."},"ar":{"q":"عند تقاطع، تُظهر إحدى إشارات المرور شكل دراجة هوائية. لمن هذه الإشارة؟","o":["لكل المركبات","للحافلات فقط","للمشاة فقط","لراكبي الدراجات الهوائية فقط"],"h1":"انظر إلى الشكل داخل الضوء.","h2":"إشارة المرور التي عليها رمز دراجة هوائية تخص راكبي الدراجات فقط؛ أما السائقون فيتبعون الإشارات العادية.","p":"صحيح. هي للدراجات الهوائية فقط."},"ht":{"q":"Nan yon kafou, gen yon limyè trafik ki montre fòm yon bisiklèt. Pou ki moun li ye?","o":["Pou tout machin","Pou bis sèlman","Pou moun k ap mache a pye sèlman","Pou moun k ap monte bisiklèt sèlman"],"h1":"Gade fòm ki andedan limyè a.","h2":"Yon limyè trafik ki gen yon siy bisiklèt se pou moun k ap monte bisiklèt sèlman; chofè yo swiv limyè trafik nòmal yo.","p":"Se sa. Li pou bisiklèt sèlman."}},{"id":"signals-052","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Near a fire station, a traffic light on a quiet road turns red. You see no fire truck yet. What should you do?","o":["Stop and wait; an emergency vehicle may be coming out","Go ahead, since no truck is there","Slow down and go through","Honk to see if a truck is coming"],"h1":"These signals turn red so fire trucks can leave safely.","h2":"An emergency-vehicle signal turns red to let fire trucks or ambulances out, so you must stop and wait even if you do not see one yet.","p":"Right. Stop; a fire truck may be coming."},"es":{"q":"Cerca de una estación de bomberos, un semáforo en una vía tranquila cambia a rojo. Aún no ve ningún camión de bomberos. ¿Qué debe hacer?","o":["Pararse y esperar; puede estar saliendo un vehículo de emergencia","Seguir, porque no hay ningún camión","Bajar la velocidad y pasar","Tocar la bocina para ver si viene un camión"],"h1":"Estos semáforos se ponen en rojo para que salgan los bomberos con seguridad.","h2":"Un semáforo de vehículos de emergencia se pone en rojo para que salgan bomberos o ambulancias, así que debe pararse y esperar aunque aún no vea ninguno.","p":"Correcto. Párese; puede salir un camión de bomberos."},"zh":{"q":"在消防站附近，一条安静的路上，红绿灯变成了红灯。你还没看到消防车。你应该怎么做？","o":["停车等待；可能有紧急车辆要开出来","没有消防车，就继续开","减速开过去","按喇叭看看有没有消防车来"],"h1":"这种信号灯变红，是为了让消防车安全开出来。","h2":"紧急车辆信号灯变红，是为了让消防车或救护车开出来，所以即使你还没看到车，也必须停车等待。","p":"对。停车；可能有消防车要出来。"},"vi":{"q":"Gần trạm cứu hỏa, đèn giao thông trên một con đường vắng chuyển sang đỏ. Bạn chưa thấy xe cứu hỏa nào. Bạn nên làm gì?","o":["Dừng lại và chờ; có thể có xe khẩn cấp sắp chạy ra","Cứ đi, vì không có xe cứu hỏa ở đó","Chạy chậm lại và đi qua","Bóp còi để xem có xe cứu hỏa tới không"],"h1":"Những đèn này chuyển đỏ để xe cứu hỏa ra đường an toàn.","h2":"Đèn dành cho xe khẩn cấp chuyển đỏ để xe cứu hỏa hoặc xe cứu thương chạy ra, nên bạn phải dừng lại và chờ dù bạn chưa thấy xe nào.","p":"Đúng rồi. Hãy dừng lại; có thể xe cứu hỏa sắp ra."},"tl":{"q":"Malapit sa istasyon ng bumbero, naging pula ang ilaw trapiko sa isang tahimik na kalsada. Wala ka pang nakikitang trak ng bumbero. Ano ang dapat mong gawin?","o":["Huminto at maghintay; maaaring may lalabas na sasakyang pang-emergency","Tumuloy, dahil walang trak doon","Bumagal at dumaan","Bumusina para malaman kung may paparating na trak"],"h1":"Nagiging pula ang mga ilaw na ito para ligtas na makalabas ang mga trak ng bumbero.","h2":"Nagiging pula ang ilaw para sa mga sasakyang pang-emergency para makalabas ang mga trak ng bumbero o ambulansya, kaya dapat kang huminto at maghintay kahit wala ka pang nakikita.","p":"Tama. Huminto; maaaring may paparating na trak ng bumbero."},"ar":{"q":"قرب محطة إطفاء، تصبح إشارة المرور حمراء على طريق هادئ. لا ترى سيارة إطفاء بعد. ماذا يجب أن تفعل؟","o":["توقف وانتظر؛ قد تخرج مركبة طوارئ","انطلق، لأنه لا توجد سيارة إطفاء","خفف السرعة وامرّ","استعمل البوق لتعرف إن كانت سيارة إطفاء قادمة"],"h1":"هذه الإشارات تصبح حمراء لتخرج سيارات الإطفاء بأمان.","h2":"إشارة مركبات الطوارئ تصبح حمراء لتسمح لسيارات الإطفاء أو الإسعاف بالخروج، لذلك يجب أن تتوقف وتنتظر حتى لو لم ترَ واحدة بعد.","p":"صحيح. توقف؛ قد تكون سيارة إطفاء قادمة."},"ht":{"q":"Toupre yon estasyon ponpye, yon limyè trafik sou yon wout trankil vin wouj. Ou poko wè okenn kamyon ponpye. Kisa ou dwe fè?","o":["Kanpe epi tann; yon machin ijans ka pral soti","Pase, paske pa gen kamyon la","Ralanti epi pase","Klaksonnen pou wè si gen yon kamyon k ap vini"],"h1":"Limyè sa yo vin wouj pou kamyon ponpye yo ka soti an sekirite.","h2":"Yon limyè pou machin ijans vin wouj pou kite kamyon ponpye oswa anbilans soti, kidonk ou dwe kanpe epi tann menm si ou poko wè youn.","p":"Se sa. Kanpe; yon kamyon ponpye ka ap vini."}},{"id":"signals-053","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"In a work zone where traffic shares one lane, a temporary traffic light is red. What should you do?","o":["Go if you see no cars coming","Stop at the light and wait for green","Drive slowly through","Use the shoulder to get by"],"h1":"Cars from the other direction are using the lane.","h2":"A temporary traffic light in a one-lane work zone lets each direction take turns, so stop at red and wait for green.","p":"Right. Wait for green."},"es":{"q":"En una zona de obras donde el tráfico comparte un carril, un semáforo temporal está en rojo. ¿Qué debe hacer?","o":["Seguir si no ve carros","Pararse en el semáforo y esperar el verde","Pasar despacio","Usar el acotamiento para pasar"],"h1":"Los carros del otro sentido están usando el carril.","h2":"Un semáforo temporal en una zona de obras de un carril hace que cada sentido se turne, así que párese en rojo y espere el verde.","p":"Correcto. Espere el verde."},"zh":{"q":"在施工区，两个方向的车共用一条车道，一个临时红绿灯是红灯。你应该怎么做？","o":["没看到来车就走","在灯前停车，等绿灯","慢慢开过去","走路肩绕过去"],"h1":"对面方向的车正在用这条车道。","h2":"单车道施工区里的临时红绿灯让两个方向的车轮流通过，所以红灯时要停车，等绿灯再走。","p":"对。等绿灯。"},"vi":{"q":"Trong khu vực thi công, xe hai chiều phải đi chung một làn, và đèn giao thông tạm thời đang đỏ. Bạn nên làm gì?","o":["Đi nếu không thấy xe nào tới","Dừng ở đèn và chờ đèn xanh","Chạy chậm qua","Đi lên lề đường để vượt qua"],"h1":"Xe từ hướng ngược lại đang dùng làn đường đó.","h2":"Đèn giao thông tạm thời trong khu vực thi công chỉ có một làn giúp xe mỗi hướng thay phiên nhau đi, nên hãy dừng khi đèn đỏ và chờ đèn xanh.","p":"Đúng rồi. Hãy chờ đèn xanh."},"tl":{"q":"Sa isang work zone kung saan iisang lane lang ang pinaghahatian ng trapiko, pula ang pansamantalang ilaw trapiko. Ano ang dapat mong gawin?","o":["Tumuloy kung wala kang nakikitang dumarating na sasakyan","Huminto sa ilaw at maghintay ng berde","Dumaan nang mabagal","Gamitin ang gilid ng kalsada (shoulder) para makalampas"],"h1":"Ginagamit ng mga sasakyan mula sa kabilang direksyon ang lane.","h2":"Ang pansamantalang ilaw trapiko sa work zone na may iisang lane ay nagpapasalit-salit sa bawat direksyon, kaya huminto kapag pula at maghintay ng berde.","p":"Tama. Maghintay ng berde."},"ar":{"q":"في منطقة عمل تتشارك فيها السيارات مسارًا واحدًا، إشارة مرور مؤقتة حمراء. ماذا يجب أن تفعل؟","o":["انطلق إذا لم ترَ سيارات قادمة","توقف عند الإشارة وانتظر الأخضر","امرّ ببطء","استعمل كتف الطريق لتتجاوز"],"h1":"السيارات القادمة من الاتجاه الآخر تستعمل المسار.","h2":"إشارة المرور المؤقتة في منطقة عمل ذات مسار واحد تجعل كل اتجاه يمر بدوره، لذلك توقف عند الأحمر وانتظر الأخضر.","p":"صحيح. انتظر الأخضر."},"ht":{"q":"Nan yon zòn travay kote machin yo pataje yon sèl liy, yon limyè trafik tanporè wouj. Kisa ou dwe fè?","o":["Pase si ou pa wè okenn machin k ap vini","Kanpe nan limyè a epi tann vèt","Kondui dousman pou pase","Sèvi ak bò wout la pou pase"],"h1":"Machin ki soti nan lòt direksyon an ap sèvi ak liy lan.","h2":"Yon limyè trafik tanporè nan yon zòn travay ki gen yon sèl liy fè chak direksyon pase youn apre lòt, kidonk kanpe lè li wouj epi tann vèt.","p":"Se sa. Tann vèt."}},{"id":"signals-054","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"In a work zone, a machine with a STOP/SLOW sign and a moving arm controls traffic instead of a person. How should you treat it?","o":["Ignore it if no worker is next to it","Drive around the arm","Obey it just like a flagger","Honk until it opens"],"h1":"Workers control these devices from a distance.","h2":"An automated flagger device is run by a worker, so you must obey its STOP and SLOW signs just as you would a flagger.","p":"Right. Obey it like a flagger."},"es":{"q":"En una zona de obras, una máquina con una señal de STOP/SLOW y un brazo que se mueve controla el tráfico en vez de una persona. ¿Cómo debe tratarla?","o":["Ignorarla si no hay un trabajador al lado","Rodear el brazo","Obedecerla igual que a un abanderado","Tocar la bocina hasta que se abra"],"h1":"Los trabajadores controlan estos aparatos a distancia.","h2":"Un abanderado automático lo maneja un trabajador, así que debe obedecer sus señales de STOP y SLOW igual que a un abanderado.","p":"Correcto. Obedézcala como a un abanderado."},"zh":{"q":"在施工区，一台带有 “STOP/SLOW”（停车/慢行）牌子和活动横杆的机器代替人来指挥交通。你应该怎样对待它？","o":["旁边没有工人就不用管它","绕过横杆开过去","像对待旗手一样服从它","一直按喇叭，直到横杆打开"],"h1":"工人在远处控制这些设备。","h2":"自动旗手设备是由工人操作的，所以你必须像服从旗手一样，服从它的 “STOP”（停车）和 “SLOW”（慢行）牌子。","p":"对。像服从旗手一样服从它。"},"vi":{"q":"Trong khu vực thi công, một máy có biển “STOP/SLOW” (Dừng/Chạy chậm) và một thanh chắn chuyển động điều khiển giao thông thay cho người. Bạn nên đối xử với nó thế nào?","o":["Bỏ qua nó nếu không có công nhân đứng cạnh","Lái vòng qua thanh chắn","Làm theo nó giống như làm theo người cầm biển","Bóp còi cho tới khi nó mở"],"h1":"Công nhân điều khiển những thiết bị này từ xa.","h2":"Thiết bị cầm biển tự động do công nhân điều khiển, nên bạn phải làm theo biển “STOP” (Dừng) và “SLOW” (Chạy chậm) của nó giống như làm theo người cầm biển.","p":"Đúng rồi. Hãy làm theo nó như làm theo người cầm biển."},"tl":{"q":"Sa isang work zone, isang makina na may karatulang “STOP/SLOW” (Huminto/Bumagal) at gumagalaw na harang ang kumokontrol sa trapiko sa halip na tao. Paano mo ito dapat ituring?","o":["Huwag pansinin kung walang trabahador sa tabi nito","Lumibot sa harang","Sundin ito gaya ng pagsunod sa flagger","Bumusina hanggang bumukas ito"],"h1":"Kinokontrol ng mga trabahador ang mga makinang ito mula sa malayo.","h2":"Ang awtomatikong flagger na makina ay pinapatakbo ng isang trabahador, kaya dapat mong sundin ang mga karatulang “STOP” (Huminto) at “SLOW” (Bumagal) nito gaya ng pagsunod mo sa isang flagger.","p":"Tama. Sundin ito gaya ng flagger."},"ar":{"q":"في منطقة عمل، آلة عليها لافتة «STOP/SLOW» (قف/ببطء) وذراع متحرك تنظم السير بدلًا من شخص. كيف يجب أن تتعامل معها؟","o":["تجاهلها إذا لم يكن بجانبها عامل","التفّ حول الذراع","أطِعها تمامًا كما تطيع عامل تنظيم السير","استعمل البوق حتى يُفتح الذراع"],"h1":"العمال يتحكمون بهذه الأجهزة من بعيد.","h2":"جهاز تنظيم السير الآلي يشغّله عامل، لذلك يجب أن تطيع لافتتَي «STOP» (قف) و«SLOW» (ببطء) عليه كما تطيع عامل تنظيم السير.","p":"صحيح. أطِعها كما تطيع عامل تنظيم السير."},"ht":{"q":"Nan yon zòn travay, yon machin ki gen yon pankat “STOP/SLOW” (kanpe/ralanti) ak yon bra k ap bouje dirije trafik la olye de yon moun. Kijan ou dwe trete l?","o":["Pa okipe l si pa gen travayè bò kote l","Kondui fè wonn bra a","Obeyi l menm jan ak yon travayè ki dirije trafik","Klaksonnen jiskaske li louvri"],"h1":"Travayè yo kontwole aparèy sa yo de lwen.","h2":"Se yon travayè ki fè aparèy otomatik sa a mache, kidonk ou dwe obeyi pankat “STOP” (kanpe) ak “SLOW” (ralanti) li yo menm jan ou ta obeyi yon travayè ki dirije trafik.","p":"Se sa. Obeyi l tankou yon travayè ki dirije trafik."}},{"id":"signals-055","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Over the center lane of a street, a signal shows a white arrow pointing left with another curving left the other way. What may you use this lane for?","o":["Passing slow cars","Driving straight through","Parking","Left turns from either direction, not driving straight"],"h1":"Two left arrows facing opposite ways.","h2":"A white two-way left-turn arrow over a lane means the lane is open only for left turns from either direction, not for through travel.","p":"Right. Left turns only, from both directions."},"es":{"q":"Sobre el carril central de una calle, un semáforo muestra una flecha blanca a la izquierda y otra que gira a la izquierda en sentido contrario. ¿Para qué puede usar este carril?","o":["Para rebasar carros lentos","Para seguir derecho","Para estacionarse","Para girar a la izquierda desde cualquier sentido, no para seguir derecho"],"h1":"Dos flechas a la izquierda en sentidos opuestos.","h2":"Una flecha blanca de giro a la izquierda en doble sentido sobre un carril significa que el carril está abierto solo para girar a la izquierda desde cualquier sentido, no para seguir derecho.","p":"Correcto. Solo giros a la izquierda, de ambos sentidos."},"zh":{"q":"在街道中间车道的上方，信号灯显示一个向左的白色箭头，旁边还有一个朝相反方向向左弯的箭头。这条车道可以用来做什么？","o":["超过慢车","直行通过","停车","两个方向的车都可以左转，但不能直行"],"h1":"两个方向相反的左转箭头。","h2":"车道上方的白色双向左转箭头表示，这条车道只供两个方向的车左转使用，不能用来直行。","p":"对。只能左转，两个方向都可以。"},"vi":{"q":"Phía trên làn giữa của con đường, đèn hiện một mũi tên trắng chỉ sang trái và một mũi tên khác cong sang trái theo hướng ngược lại. Bạn được dùng làn này để làm gì?","o":["Vượt xe chạy chậm","Chạy thẳng qua","Đậu xe","Rẽ trái từ cả hai hướng, không được chạy thẳng"],"h1":"Hai mũi tên rẽ trái quay về hai hướng ngược nhau.","h2":"Mũi tên trắng rẽ trái hai chiều phía trên một làn nghĩa là làn đó chỉ dùng để rẽ trái từ cả hai hướng, không dùng để chạy thẳng.","p":"Đúng rồi. Chỉ để rẽ trái, từ cả hai hướng."},"tl":{"q":"Sa itaas ng gitnang lane ng kalye, may signal na nagpapakita ng puting arrow na nakaturo pakaliwa at isa pang kumukurba pakaliwa sa kabilang direksyon. Para saan mo maaaring gamitin ang lane na ito?","o":["Para lampasan ang mabagal na sasakyan","Para dumiretso","Para pumarada","Para lumiko pakaliwa mula sa alinmang direksyon, hindi para dumiretso"],"h1":"Dalawang arrow pakaliwa na magkasalungat ang direksyon.","h2":"Ang puting two-way left-turn arrow sa itaas ng lane ay nangangahulugang bukas lang ang lane para sa pagliko pakaliwa mula sa alinmang direksyon, hindi para dumiretso.","p":"Tama. Pagliko pakaliwa lang, mula sa dalawang direksyon."},"ar":{"q":"فوق المسار الأوسط في شارع، تُظهر إشارة سهمًا أبيض يشير إلى اليسار وسهمًا آخر ينعطف إلى اليسار في الاتجاه المعاكس. فيمَ يمكنك أن تستعمل هذا المسار؟","o":["لتجاوز السيارات البطيئة","للسير مباشرة إلى الأمام","للوقوف (الركن)","للانعطاف إلى اليسار من الاتجاهين، وليس للسير إلى الأمام"],"h1":"سهمان إلى اليسار في اتجاهين متعاكسين.","h2":"السهم الأبيض للانعطاف إلى اليسار في الاتجاهين فوق مسار يعني أن المسار مفتوح فقط للانعطاف إلى اليسار من الاتجاهين، وليس للسير إلى الأمام.","p":"صحيح. للانعطاف إلى اليسار فقط، من الاتجاهين."},"ht":{"q":"Anlè liy mitan yon lari, yon siyal montre yon flèch blan ki pwente agoch ak yon lòt ki koube agoch nan lòt direksyon an. Pou kisa ou ka sèvi ak liy sa a?","o":["Pou pase machin ki dousman","Pou kondui tou dwat","Pou pake","Pou vire agoch soti nan nenpòt direksyon, pa pou kondui tou dwat"],"h1":"De flèch agoch ki gade nan direksyon opoze.","h2":"Yon flèch blan pou vire agoch nan de direksyon anlè yon liy vle di liy lan louvri sèlman pou vire agoch soti nan nenpòt direksyon, pa pou kondui tou dwat.","p":"Se sa. Pou vire agoch sèlman, nan de direksyon yo."}},{"id":"signals-056","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"A sign says SIGNALS SET FOR 30 MPH. What does it mean?","o":["If you drive about 30 mph, you will meet more green lights","You must drive exactly 30 mph","The lights turn red if you go faster than 30","The speed limit starts in 30 miles"],"h1":"The lights are timed in a sequence.","h2":"SIGNALS SET FOR 30 MPH means the traffic lights are timed so that driving at about that speed lets you meet more green lights.","p":"Right. That speed helps you get green lights."},"es":{"q":"Una señal dice SIGNALS SET FOR 30 MPH. ¿Qué significa?","o":["Que si maneja a unas 30 mph, encontrará más luces verdes","Que debe manejar exactamente a 30 mph","Que los semáforos se ponen rojos si va a más de 30","Que el límite empieza en 30 millas"],"h1":"Los semáforos están coordinados en secuencia.","h2":"SIGNALS SET FOR 30 MPH significa que los semáforos están coordinados para que, manejando a esa velocidad, encuentre más luces verdes.","p":"Correcto. Esa velocidad le ayuda a encontrar verdes."},"zh":{"q":"一个标志写着 “SIGNALS SET FOR 30 MPH”（信号灯按每小时30英里设置）。这是什么意思？","o":["如果你开大约每小时30英里，就会遇到更多绿灯","你必须正好开每小时30英里","开得比30快，灯就会变红","30英里后开始限速"],"h1":"这些灯是按顺序定时的。","h2":"“SIGNALS SET FOR 30 MPH” 表示红绿灯是按时间配合好的，用大约这个速度开车，你会遇到更多绿灯。","p":"对。用这个速度开，更容易遇到绿灯。"},"vi":{"q":"Một biển báo ghi “SIGNALS SET FOR 30 MPH” (Đèn được chỉnh cho tốc độ 30 dặm/giờ). Điều đó có nghĩa là gì?","o":["Nếu bạn chạy khoảng 30 dặm/giờ, bạn sẽ gặp nhiều đèn xanh hơn","Bạn phải chạy đúng 30 dặm/giờ","Đèn sẽ chuyển đỏ nếu bạn chạy nhanh hơn 30","Giới hạn tốc độ bắt đầu sau 30 dặm"],"h1":"Các đèn được canh giờ theo thứ tự.","h2":"“SIGNALS SET FOR 30 MPH” nghĩa là các đèn giao thông được canh giờ để khi bạn chạy khoảng tốc độ đó, bạn sẽ gặp nhiều đèn xanh hơn.","p":"Đúng rồi. Tốc độ đó giúp bạn gặp đèn xanh."},"tl":{"q":"May karatulang nagsasabing “SIGNALS SET FOR 30 MPH” (Nakatakda ang mga ilaw para sa 30 MPH). Ano ang ibig sabihin nito?","o":["Kung magmamaneho ka nang mga 30 mph, mas maraming berdeng ilaw ang aabutan mo","Dapat kang magmaneho nang eksaktong 30 mph","Magiging pula ang mga ilaw kung lalampas ka sa 30","Magsisimula ang speed limit pagkalipas ng 30 milya"],"h1":"Nakatakda ang oras ng mga ilaw nang sunod-sunod.","h2":"Ang “SIGNALS SET FOR 30 MPH” ay nangangahulugang nakatakda ang oras ng mga ilaw trapiko para kapag nagmaneho ka nang mga ganoong bilis, mas maraming berdeng ilaw ang aabutan mo.","p":"Tama. Ang bilis na iyon ay tumutulong para maabutan mo ang berdeng ilaw."},"ar":{"q":"لافتة مكتوب عليها «SIGNALS SET FOR 30 MPH» (الإشارات مضبوطة على 30 ميلًا في الساعة). ماذا تعني؟","o":["إذا قدت بسرعة 30 ميلًا في الساعة تقريبًا، ستصادف إشارات خضراء أكثر","يجب أن تقود بسرعة 30 ميلًا في الساعة بالضبط","تصبح الإشارات حمراء إذا تجاوزت 30","حد السرعة يبدأ بعد 30 ميلًا"],"h1":"توقيت الإشارات مضبوط بالتسلسل.","h2":"«SIGNALS SET FOR 30 MPH» تعني أن توقيت إشارات المرور مضبوط بحيث إذا قدت بهذه السرعة تقريبًا تصادف إشارات خضراء أكثر.","p":"صحيح. هذه السرعة تساعدك على مصادفة الإشارات الخضراء."},"ht":{"q":"Yon pankat di “SIGNALS SET FOR 30 MPH” (limyè yo regle pou 30 mil alè). Kisa sa vle di?","o":["Si ou kondui anviwon 30 mph, w ap jwenn plis limyè vèt","Ou dwe kondui egzakteman 30 mph","Limyè yo ap vin wouj si ou ale pi vit pase 30","Limit vitès la kòmanse nan 30 mil"],"h1":"Limyè yo regle pou youn swiv lòt.","h2":"“SIGNALS SET FOR 30 MPH” vle di limyè trafik yo regle yon fason pou si ou kondui anviwon vitès sa a, w ap jwenn plis limyè vèt.","p":"Se sa. Vitès sa a ede w jwenn limyè vèt."}},{"id":"signals-057","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"On road markings, what does a double line usually tell you?","o":["You may cross it when you like","It shows the strongest limits, such as no passing","The road is about to end","You are near a school"],"h1":"Two lines are stronger than one.","h2":"A double line on the road shows the strongest limits, such as no passing or no lane changes across it.","p":"Right. A double line shows the strongest limits."},"es":{"q":"En las marcas de la vía, ¿qué suele indicar una línea doble?","o":["Que puede cruzarla cuando quiera","Indica las restricciones más fuertes, como no rebasar","Que la vía va a terminar","Que está cerca de una escuela"],"h1":"Dos líneas son más fuertes que una.","h2":"Una línea doble en la vía indica las restricciones más fuertes, como no rebasar o no cambiar de carril cruzándola.","p":"Correcto. Una línea doble indica las restricciones más fuertes."},"zh":{"q":"在路面标线中，双线通常告诉你什么？","o":["你想什么时候越过都可以","它表示最严格的限制，比如禁止超车","路快到尽头了","你在学校附近"],"h1":"两条线比一条线更严格。","h2":"路面上的双线表示最严格的限制，比如禁止超车，或禁止越过它变换车道。","p":"对。双线表示最严格的限制。"},"vi":{"q":"Trên vạch kẻ đường, vạch đôi thường cho bạn biết điều gì?","o":["Bạn được băng qua nó lúc nào bạn muốn","Nó cho biết mức hạn chế mạnh nhất, ví dụ cấm vượt","Con đường sắp hết","Bạn đang ở gần trường học"],"h1":"Hai vạch mạnh hơn một vạch.","h2":"Vạch đôi trên mặt đường cho biết mức hạn chế mạnh nhất, ví dụ cấm vượt hoặc cấm đổi làn băng qua vạch đó.","p":"Đúng rồi. Vạch đôi cho biết mức hạn chế mạnh nhất."},"tl":{"q":"Sa mga marka sa kalsada, ano ang karaniwang sinasabi sa iyo ng dobleng linya?","o":["Maaari mo itong tawirin kahit kailan mo gusto","Ipinapakita nito ang pinakamahigpit na limitasyon, gaya ng bawal mag-overtake","Malapit nang matapos ang kalsada","Malapit ka sa isang paaralan"],"h1":"Mas mahigpit ang dalawang linya kaysa sa isa.","h2":"Ang dobleng linya sa kalsada ay nagpapakita ng pinakamahigpit na limitasyon, gaya ng bawal mag-overtake o bawal lumipat ng lane sa ibabaw nito.","p":"Tama. Ang dobleng linya ay nagpapakita ng pinakamahigpit na limitasyon."},"ar":{"q":"في علامات الطريق، ماذا يخبرك الخط المزدوج عادةً؟","o":["يمكنك أن تعبره متى شئت","يدل على أشد القيود، مثل منع التجاوز","الطريق على وشك أن ينتهي","أنت قرب مدرسة"],"h1":"خطان أقوى من خط واحد.","h2":"الخط المزدوج على الطريق يدل على أشد القيود، مثل منع التجاوز أو منع تغيير المسار بعبوره.","p":"صحيح. الخط المزدوج يدل على أشد القيود."},"ht":{"q":"Nan mak ki sou wout la, kisa yon liy doub konn di w?","o":["Ou ka travèse l lè ou vle","Li montre limit ki pi sevè yo, tankou entèdi pou depase","Wout la pral fini","Ou toupre yon lekòl"],"h1":"De liy pi fò pase yon sèl.","h2":"Yon liy doub sou wout la montre limit ki pi sevè yo, tankou entèdi pou depase oswa entèdi pou chanje liy pandan w ap travèse l.","p":"Se sa. Yon liy doub montre limit ki pi sevè yo."}},{"id":"signals-058","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"Two solid white lines run between two lanes going the same way. What do they mean?","o":["You may change lanes freely","One lane is for buses","Do not change lanes across them","Pass on either side"],"h1":"A double white line is stronger than a single one.","h2":"A double solid white line between lanes means you must not cross it to change lanes.","p":"Right. Do not cross a double white line."},"es":{"q":"Dos líneas blancas continuas separan dos carriles que van en el mismo sentido. ¿Qué significan?","o":["Que puede cambiar de carril libremente","Que un carril es para autobuses","Que no cambie de carril cruzándolas","Que puede rebasar por cualquier lado"],"h1":"Una línea blanca doble es más fuerte que una sencilla.","h2":"Una línea blanca doble continua entre carriles significa que no debe cruzarla para cambiar de carril.","p":"Correcto. No cruce una línea blanca doble."},"zh":{"q":"两条同方向的车道之间有两条白色实线。它们是什么意思？","o":["你可以随便变换车道","其中一条车道是公交车道","不要越过它们变换车道","可以从任何一边超车"],"h1":"双白线比单白线更严格。","h2":"车道之间的双白色实线表示你不可以越过它变换车道。","p":"对。不要越过双白线。"},"vi":{"q":"Giữa hai làn xe chạy cùng chiều có hai vạch trắng liền. Chúng có nghĩa là gì?","o":["Bạn được đổi làn thoải mái","Một làn dành cho xe buýt","Không được đổi làn băng qua các vạch đó","Vượt ở bên nào cũng được"],"h1":"Vạch trắng đôi mạnh hơn vạch đơn.","h2":"Vạch trắng liền đôi giữa các làn nghĩa là bạn không được băng qua nó để đổi làn.","p":"Đúng rồi. Không được băng qua vạch trắng đôi."},"tl":{"q":"May dalawang tuloy-tuloy na puting linya sa pagitan ng dalawang lane na pareho ang direksyon. Ano ang ibig sabihin nito?","o":["Malaya kang lumipat ng lane","Ang isang lane ay para sa bus","Huwag lumipat ng lane sa ibabaw ng mga ito","Mag-overtake sa alinmang panig"],"h1":"Mas mahigpit ang dobleng puting linya kaysa sa iisa.","h2":"Ang dobleng tuloy-tuloy na puting linya sa pagitan ng mga lane ay nangangahulugang hindi mo ito dapat tawirin para lumipat ng lane.","p":"Tama. Huwag tawirin ang dobleng puting linya."},"ar":{"q":"خطان أبيضان متصلان يمتدان بين مسارين في نفس الاتجاه. ماذا يعنيان؟","o":["يمكنك أن تغيّر المسار بحرية","أحد المسارين للحافلات","يجب ألّا تغيّر المسار بعبورهما","تجاوز من أي جهة"],"h1":"الخط الأبيض المزدوج أقوى من الخط المفرد.","h2":"الخط الأبيض المتصل المزدوج بين المسارات يعني أنه يجب ألّا تعبره لتغيير المسار.","p":"صحيح. يجب ألّا تعبر الخط الأبيض المزدوج."},"ht":{"q":"De liy blan kontinyèl pase ant de liy ki ale nan menm direksyon. Kisa yo vle di?","o":["Ou ka chanje liy jan ou vle","Youn nan liy yo se pou bis","Pa chanje liy pandan w ap travèse yo","Depase sou nenpòt bò"],"h1":"Yon liy blan doub pi fò pase yon sèl liy.","h2":"Yon liy blan kontinyèl doub ant liy yo vle di ou pa dwe travèse l pou chanje liy.","p":"Se sa. Pa travèse yon liy blan doub."}},{"id":"signals-059","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Between two lanes, the white line changes to short dashes that are close together. What does that warn you about?","o":["You are entering a school zone","The road will become gravel","A police check is ahead","The lane ahead will end or turn off, so get into the lane you need early"],"h1":"Short, close dashes mean a change is coming.","h2":"A dotted white lane line warns that the lane ahead will change, for example by ending or becoming an exit or turn lane.","p":"Right. The lane is about to change."},"es":{"q":"Entre dos carriles, la línea blanca cambia a rayas cortas y muy juntas. ¿De qué le advierte?","o":["De que entra a una zona escolar","De que la vía será de grava","De que hay un control de policía","De que el carril adelante terminará o saldrá, así que póngase a tiempo en el carril que necesita"],"h1":"Rayas cortas y juntas indican que viene un cambio.","h2":"Una línea blanca punteada entre carriles advierte que el carril adelante va a cambiar, por ejemplo terminando o convirtiéndose en salida o carril de giro.","p":"Correcto. El carril está por cambiar."},"zh":{"q":"两条车道之间的白线变成了又短又密的虚线。它在提醒你什么？","o":["你正在进入学校区域","路面会变成碎石路","前面有警察检查","前面的车道会结束或转出去，所以要早点进入你需要的车道"],"h1":"又短又密的虚线表示马上有变化。","h2":"白色点状车道线提醒你前面的车道会有变化，比如车道结束，或变成出口车道或转弯车道。","p":"对。车道马上要变了。"},"vi":{"q":"Giữa hai làn, vạch trắng chuyển thành các nét đứt ngắn và sát nhau. Điều đó cảnh báo bạn về chuyện gì?","o":["Bạn đang đi vào khu vực trường học","Con đường sắp thành đường sỏi","Phía trước có cảnh sát kiểm tra","Làn phía trước sẽ hết hoặc rẽ ra, nên hãy vào làn bạn cần từ sớm"],"h1":"Nét đứt ngắn và sát nhau nghĩa là sắp có thay đổi.","h2":"Vạch làn trắng dạng chấm cảnh báo rằng làn phía trước sẽ thay đổi, ví dụ làn sẽ hết hoặc trở thành làn ra hay làn rẽ.","p":"Đúng rồi. Làn đường sắp thay đổi."},"tl":{"q":"Sa pagitan ng dalawang lane, nagiging maiikli at magkakalapit na putol-putol na linya ang puting linya. Ano ang babala nito sa iyo?","o":["Papasok ka sa school zone","Magiging graba ang kalsada","May checkpoint ng pulis sa unahan","Matatapos o liliko palabas ang lane sa unahan, kaya pumasok nang maaga sa lane na kailangan mo"],"h1":"Ang maiikli at magkakalapit na putol-putol na linya ay nangangahulugang may paparating na pagbabago.","h2":"Ang puting tuldok-tuldok na linya ng lane ay babala na magbabago ang lane sa unahan, halimbawa ay matatapos ito o magiging exit o lane para lumiko.","p":"Tama. Malapit nang magbago ang lane."},"ar":{"q":"بين مسارين، يتحول الخط الأبيض إلى خطوط متقطعة قصيرة وقريبة من بعضها. مِمَّ يحذّرك ذلك؟","o":["أنت تدخل منطقة مدرسة","الطريق سيصبح من الحصى","هناك تفتيش للشرطة أمامك","المسار أمامك سينتهي أو يتفرّع، لذلك ادخل المسار الذي تحتاجه مبكرًا"],"h1":"الخطوط القصيرة القريبة من بعضها تعني أن تغييرًا قادم.","h2":"خط المسار الأبيض المنقّط يحذّر من أن المسار أمامك سيتغير، مثلًا بأن ينتهي أو يصبح مسار خروج أو مسار انعطاف.","p":"صحيح. المسار على وشك أن يتغير."},"ht":{"q":"Ant de liy, liy blan an vin tounen ti tras kout ki pre youn ak lòt. Kisa sa avèti w?","o":["W ap antre nan yon zòn lekòl","Wout la pral vin an gravye","Gen yon kontwòl polis devan","Liy devan an pral fini oswa vire soti, kidonk antre bonè nan liy ou bezwen an"],"h1":"Ti tras kout ki pre youn ak lòt vle di yon chanjman ap vini.","h2":"Yon liy blan an pwen ant liy yo avèti w liy devan an pral chanje, pa egzanp li pral fini oswa vin tounen yon liy sòti oswa yon liy pou vire.","p":"Se sa. Liy lan pral chanje."}},{"id":"signals-060","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"What does a solid white line along the right edge of the road show?","o":["The right edge of the road","A bike lane","A no-passing zone","A place to park"],"h1":"Edge lines help you see where the road ends.","h2":"A solid white line on the right side marks the right edge of the road, which helps you stay on the road at night and in bad weather.","p":"Right. It marks the right edge of the road."},"es":{"q":"¿Qué indica una línea blanca continua a lo largo de la orilla derecha de la vía?","o":["La orilla derecha de la vía","Un carril para bicicletas","Una zona de no rebasar","Un lugar para estacionarse"],"h1":"Las líneas de orilla le ayudan a ver dónde termina la vía.","h2":"Una línea blanca continua del lado derecho marca la orilla derecha de la vía, lo que le ayuda a mantenerse en ella de noche y con mal tiempo.","p":"Correcto. Marca la orilla derecha de la vía."},"zh":{"q":"沿着道路右边缘的白色实线表示什么？","o":["道路的右边缘","自行车道","禁止超车区","可以停车的地方"],"h1":"边线帮你看清路到哪里为止。","h2":"右侧的白色实线标出道路的右边缘，帮助你在夜里和天气不好时保持在路上。","p":"对。它标出道路的右边缘。"},"vi":{"q":"Vạch trắng liền chạy dọc mép phải của con đường cho biết điều gì?","o":["Mép phải của con đường","Làn xe đạp","Khu vực cấm vượt","Chỗ để đậu xe"],"h1":"Vạch mép đường giúp bạn thấy con đường kết thúc ở đâu.","h2":"Vạch trắng liền ở bên phải đánh dấu mép phải của con đường, giúp bạn giữ xe trên đường vào ban đêm và khi thời tiết xấu.","p":"Đúng rồi. Nó đánh dấu mép phải của con đường."},"tl":{"q":"Ano ang ipinapakita ng tuloy-tuloy na puting linya sa kanang gilid ng kalsada?","o":["Ang kanang gilid ng kalsada","Isang bike lane","Isang lugar na bawal mag-overtake","Isang lugar para pumarada"],"h1":"Tinutulungan ka ng mga linya sa gilid na makita kung saan nagtatapos ang kalsada.","h2":"Ang tuloy-tuloy na puting linya sa kanang bahagi ay nagmamarka ng kanang gilid ng kalsada, na tumutulong sa iyo na manatili sa kalsada sa gabi at sa masamang panahon.","p":"Tama. Minamarkahan nito ang kanang gilid ng kalsada."},"ar":{"q":"ماذا يُظهر الخط الأبيض المتصل على طول الحافة اليمنى للطريق؟","o":["الحافة اليمنى للطريق","مسار للدراجات الهوائية","منطقة يُمنع فيها التجاوز","مكانًا للوقوف (الركن)"],"h1":"خطوط الحافة تساعدك على رؤية أين ينتهي الطريق.","h2":"الخط الأبيض المتصل على الجانب الأيمن يحدد الحافة اليمنى للطريق، وهذا يساعدك على البقاء على الطريق في الليل وفي الطقس السيئ.","p":"صحيح. يحدد الحافة اليمنى للطريق."},"ht":{"q":"Kisa yon liy blan kontinyèl sou bò dwat wout la montre?","o":["Bò dwat wout la","Yon liy pou bisiklèt","Yon zòn kote li entèdi pou depase","Yon kote pou pake"],"h1":"Liy sou bò yo ede w wè kote wout la fini.","h2":"Yon liy blan kontinyèl sou bò dwat la make bò dwat wout la, sa ki ede w rete sou wout la lannwit ak lè tan an move.","p":"Se sa. Li make bò dwat wout la."}},{"id":"signals-061","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A lane is marked on both sides by two broken (dashed) yellow lines side by side. What kind of lane is it?","o":["A bike lane","A reversible lane, whose direction changes at certain times","A parking lane","A lane for passing only"],"h1":"Signs or signals tell you which way it is open.","h2":"Double broken yellow lines mark a reversible lane, which carries traffic in different directions at different times of day.","p":"Right. It is a reversible lane."},"es":{"q":"Un carril está marcado a ambos lados por dos líneas amarillas discontinuas, una junto a otra. ¿Qué tipo de carril es?","o":["Un carril para bicicletas","Un carril reversible, que cambia de sentido en ciertos horarios","Un carril de estacionamiento","Un carril solo para rebasar"],"h1":"Señales o semáforos indican hacia dónde está abierto.","h2":"Las líneas amarillas dobles discontinuas marcan un carril reversible, que lleva tráfico en distintos sentidos según la hora del día.","p":"Correcto. Es un carril reversible."},"zh":{"q":"一条车道的两边都画着并排的两条黄色虚线。这是什么车道？","o":["自行车道","可变向车道，行驶方向在某些时间会改变","停车道","只用来超车的车道"],"h1":"标志或信号灯会告诉你它往哪个方向开放。","h2":"双黄色虚线标出的是可变向车道，在一天中不同的时间，这条车道上的车会往不同的方向行驶。","p":"对。这是可变向车道。"},"vi":{"q":"Một làn đường được kẻ ở cả hai bên bằng hai vạch vàng đứt nằm cạnh nhau. Đó là loại làn gì?","o":["Làn xe đạp","Làn đổi chiều, hướng chạy thay đổi vào những giờ nhất định","Làn đậu xe","Làn chỉ dùng để vượt"],"h1":"Biển báo hoặc đèn sẽ cho bạn biết làn đang mở cho hướng nào.","h2":"Vạch vàng đứt đôi đánh dấu làn đổi chiều, là làn cho xe chạy theo những hướng khác nhau vào những giờ khác nhau trong ngày.","p":"Đúng rồi. Đó là làn đổi chiều."},"tl":{"q":"May lane na minarkahan sa magkabilang gilid ng dalawang putol-putol (dashed) na dilaw na linya na magkatabi. Anong klaseng lane ito?","o":["Isang bike lane","Isang reversible lane, na nagbabago ang direksyon sa ilang oras","Isang lane para sa pagparada","Isang lane para sa pag-overtake lang"],"h1":"Sinasabi ng mga karatula o ilaw kung saang direksyon ito bukas.","h2":"Ang dobleng putol-putol na dilaw na linya ay nagmamarka ng reversible lane, na dinadaanan ng trapiko sa magkakaibang direksyon sa magkakaibang oras ng araw.","p":"Tama. Ito ay isang reversible lane."},"ar":{"q":"مسار عليه من الجانبين خطان أصفران متقطعان متجاوران. ما نوع هذا المسار؟","o":["مسار للدراجات الهوائية","مسار قابل لعكس الاتجاه، يتغير اتجاهه في أوقات معينة","مسار للوقوف (الركن)","مسار للتجاوز فقط"],"h1":"اللافتات أو الإشارات تخبرك بالاتجاه المفتوح فيه.","h2":"الخطوط الصفراء المتقطعة المزدوجة تحدد مسارًا قابلًا لعكس الاتجاه، تسير فيه السيارات في اتجاهات مختلفة في أوقات مختلفة من اليوم.","p":"صحيح. هو مسار قابل لعكس الاتجاه."},"ht":{"q":"Yon liy make sou toulède bò pa de liy jòn an tras (koupe koupe) youn bò lòt. Ki kalite liy li ye?","o":["Yon liy pou bisiklèt","Yon liy ki chanje direksyon, direksyon l chanje nan sèten lè","Yon liy pou pake","Yon liy pou depase sèlman"],"h1":"Pankat oswa limyè ap di w nan ki direksyon li louvri.","h2":"Liy jòn an tras doub make yon liy ki chanje direksyon, kote machin yo ale nan diferan direksyon selon lè nan jounen an.","p":"Se sa. Se yon liy ki chanje direksyon."}},{"id":"signals-062","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"Where a freeway exit splits off, an area between the lanes is painted with white diagonal stripes. What should you do?","o":["Use it to change your mind at the last second","Park there in an emergency","Do not drive on the striped area","Drive over it to pass"],"h1":"The stripes fill space that is not a lane.","h2":"White diagonal or chevron stripes mark an area that is not meant for driving, so stay off it.","p":"Right. Stay off the striped area."},"es":{"q":"Donde se separa una salida de autopista, un área entre los carriles está pintada con rayas blancas diagonales. ¿Qué debe hacer?","o":["Usarla para cambiar de idea en el último segundo","Estacionarse allí en una emergencia","No manejar sobre el área rayada","Pasar por encima para rebasar"],"h1":"Las rayas llenan un espacio que no es carril.","h2":"Las rayas blancas diagonales o en forma de V marcan un área que no es para manejar, así que no pase por ella.","p":"Correcto. No pase por el área rayada."},"zh":{"q":"在高速公路出口分开的地方，车道之间有一块区域画着白色斜条纹。你应该怎么做？","o":["最后一秒改变主意时用它","紧急时在那里停车","不要开到条纹区域上","开过它去超车"],"h1":"条纹填满的地方不是车道。","h2":"白色斜条纹或 V 形条纹标出的区域不是用来开车的，所以不要开到上面。","p":"对。不要开到条纹区域上。"},"vi":{"q":"Ở chỗ lối ra xa lộ tách ra, có một khu vực giữa các làn được sơn sọc chéo màu trắng. Bạn nên làm gì?","o":["Dùng nó khi bạn đổi ý vào giây cuối","Đậu xe ở đó khi khẩn cấp","Không chạy lên khu vực có sọc","Chạy qua nó để vượt xe"],"h1":"Các sọc tô kín chỗ không phải là làn xe.","h2":"Sọc chéo hoặc sọc hình chữ V màu trắng đánh dấu khu vực không dành để chạy xe, nên đừng chạy lên đó.","p":"Đúng rồi. Đừng chạy lên khu vực có sọc."},"tl":{"q":"Kung saan humihiwalay ang exit ng freeway, may bahagi sa pagitan ng mga lane na pinintahan ng puting pahilis na guhit. Ano ang dapat mong gawin?","o":["Gamitin ito kung magbabago ang isip mo sa huling segundo","Pumarada doon kapag may emergency","Huwag magmaneho sa bahaging may guhit","Daanan ito para mag-overtake"],"h1":"Pinupuno ng mga guhit ang espasyong hindi lane.","h2":"Ang puting pahilis o chevron na guhit ay nagmamarka ng bahaging hindi para sa pagmamaneho, kaya huwag kang dumaan doon.","p":"Tama. Huwag dumaan sa bahaging may guhit."},"ar":{"q":"عند مكان انفصال مخرج الطريق السريع، توجد منطقة بين المسارات مدهونة بخطوط بيضاء مائلة. ماذا يجب أن تفعل؟","o":["استخدمها إذا غيّرت رأيك في آخر لحظة","توقف هناك في حالة الطوارئ","يجب ألّا تقود على المنطقة المخططة","قُد فوقها لتتجاوز"],"h1":"الخطوط تملأ مساحة ليست مسارًا.","h2":"الخطوط البيضاء المائلة أو على شكل حرف V تحدد منطقة ليست للقيادة، لذلك ابقَ بعيدًا عنها.","p":"صحيح. ابقَ بعيدًا عن المنطقة المخططة."},"ht":{"q":"Kote yon sòti otowout separe, gen yon espas ant liy yo ki pentire ak bann blan an dyagonal. Kisa ou dwe fè?","o":["Sèvi ak li si ou chanje lide nan dènye segonn","Pake la si gen yon ijans","Pa kondui sou espas ki gen bann yo","Kondui sou li pou depase"],"h1":"Bann yo ranpli yon espas ki pa yon liy.","h2":"Bann blan an dyagonal oswa an fòm V make yon espas ki pa fèt pou kondui, kidonk pa monte sou li.","p":"Se sa. Pa monte sou espas ki gen bann yo."}},{"id":"signals-063","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"At night you see red reflectors (red raised markers) on the road in front of you. What do they mean?","o":["You are near a fire hydrant","A school zone starts","The road is wet","You are facing the wrong way; do not go on"],"h1":"Red reflectors face drivers going the wrong direction.","h2":"Red raised markers are seen only by drivers going the wrong way on a road or ramp, so if you see them, stop and turn around safely.","p":"Right. Red markers mean wrong way."},"es":{"q":"De noche, usted ve reflectores rojos (marcadores elevados rojos) en la vía frente a usted. ¿Qué significan?","o":["Que está cerca de un hidrante","Que empieza una zona escolar","Que la vía está mojada","Que va en sentido contrario; no siga"],"h1":"Los reflectores rojos miran hacia quien va en sentido contrario.","h2":"Los marcadores rojos elevados solo los ven los conductores que van en sentido contrario por una vía o rampa, así que si los ve, párese y dé la vuelta con seguridad.","p":"Correcto. Los marcadores rojos indican sentido contrario."},"zh":{"q":"晚上你看到前面路面上有红色反光标（凸起的红色路标）。它们是什么意思？","o":["你靠近消防栓","学校区开始了","路面是湿的","你开反方向了，不要继续往前开"],"h1":"红色反光标是朝向逆行司机的。","h2":"红色凸起路标只有在道路或匝道上逆行的司机才看得到，所以如果你看到它们，就要停车并安全地掉头。","p":"对。红色路标表示你开反方向了。"},"vi":{"q":"Ban đêm bạn thấy đèn phản quang màu đỏ (cục phản quang đỏ nhô lên) trên đường phía trước. Chúng có nghĩa là gì?","o":["Bạn đang ở gần trụ nước cứu hỏa","Bắt đầu khu vực trường học","Mặt đường bị ướt","Bạn đang đi ngược chiều; đừng đi tiếp"],"h1":"Phản quang màu đỏ hướng về phía người lái đi sai chiều.","h2":"Cục phản quang đỏ nhô lên chỉ những người lái đi ngược chiều trên đường hoặc đường dốc mới thấy, nên nếu bạn thấy chúng, hãy dừng lại và quay đầu một cách an toàn.","p":"Đúng rồi. Phản quang đỏ nghĩa là bạn đi ngược chiều."},"tl":{"q":"Sa gabi, may nakikita kang pulang reflector (nakaumbok na pulang marka) sa daan sa harap mo. Ano ang ibig sabihin ng mga ito?","o":["Malapit ka sa fire hydrant","Nagsisimula ang school zone","Basa ang daan","Mali ang direksyon mo; huwag nang tumuloy"],"h1":"Nakaharap ang pulang reflector sa mga driver na mali ang direksyon.","h2":"Ang mga nakaumbok na pulang marka ay nakikita lang ng mga driver na mali ang direksyon sa daan o ramp, kaya kung makita mo ang mga ito, huminto at umikot pabalik nang ligtas.","p":"Tama. Ang pulang marka ay nangangahulugang mali ang direksyon mo."},"ar":{"q":"في الليل ترى عاكسات حمراء (علامات حمراء بارزة) على الطريق أمامك. ماذا تعني؟","o":["أنت قريب من صنبور إطفاء الحريق","تبدأ منطقة مدرسة","الطريق مبلل","أنت تسير في الاتجاه الخطأ؛ يجب ألّا تكمل"],"h1":"العاكسات الحمراء موجّهة نحو السائقين الذين يسيرون في الاتجاه الخطأ.","h2":"العلامات الحمراء البارزة لا يراها إلا السائقون الذين يسيرون في الاتجاه الخطأ على الطريق أو المنحدر، لذلك إذا رأيتها فتوقف واستدر بأمان.","p":"صحيح. العلامات الحمراء تعني أنك في الاتجاه الخطأ."},"ht":{"q":"Lannwit, ou wè reflektè wouj (ti mak wouj ki leve) sou wout la devan ou. Kisa yo vle di?","o":["Ou toupre yon bòn ponpye","Yon zòn lekòl ap kòmanse","Wout la mouye","Ou nan move direksyon; pa kontinye"],"h1":"Reflektè wouj yo vire bò kote chofè ki nan move direksyon.","h2":"Se sèlman chofè ki nan move direksyon sou yon wout oswa yon ranp ki wè mak wouj ki leve yo, kidonk si ou wè yo, kanpe epi vire tounen an sekirite.","p":"Se sa. Mak wouj yo vle di move direksyon."}},{"id":"signals-064","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"On a ramp, you see a large white arrow painted on the road pointing toward you. What does it mean?","o":["You are going the wrong way","Turn around at the end of the ramp","Two-way traffic ahead","You may drive in either direction"],"h1":"Arrows point the way traffic should go.","h2":"A painted arrow that points toward you means traffic should be coming the other way, so you are going the wrong way and must stop and turn around safely.","p":"Right. You are going the wrong way."},"es":{"q":"En una rampa, usted ve una gran flecha blanca pintada en la vía que apunta hacia usted. ¿Qué significa?","o":["Que va en sentido contrario","Que dé la vuelta al final de la rampa","Que viene tráfico en doble sentido","Que puede manejar en cualquier sentido"],"h1":"Las flechas apuntan hacia donde debe ir el tráfico.","h2":"Una flecha pintada que apunta hacia usted significa que el tráfico debe venir en sentido opuesto, así que va en sentido contrario y debe pararse y dar la vuelta con seguridad.","p":"Correcto. Va en sentido contrario."},"zh":{"q":"在匝道上，你看到路面上画着一个大白箭头，指向你这边。它是什么意思？","o":["你开反方向了","在匝道尽头掉头","前面是双向交通","你可以往任何方向开"],"h1":"箭头指向车流应该走的方向。","h2":"路面上的箭头指向你，表示车流应该从另一个方向来，所以你开反方向了，必须停车并安全地掉头。","p":"对。你开反方向了。"},"vi":{"q":"Trên đường dốc, bạn thấy một mũi tên lớn màu trắng sơn trên đường chỉ về phía bạn. Nó có nghĩa là gì?","o":["Bạn đang đi ngược chiều","Quay đầu ở cuối đường dốc","Phía trước có giao thông hai chiều","Bạn có thể chạy theo chiều nào cũng được"],"h1":"Mũi tên chỉ hướng xe cộ phải đi.","h2":"Mũi tên sơn trên đường chỉ về phía bạn nghĩa là xe phải chạy từ hướng kia tới, nên bạn đang đi ngược chiều và phải dừng lại rồi quay đầu một cách an toàn.","p":"Đúng rồi. Bạn đang đi ngược chiều."},"tl":{"q":"Sa isang ramp, may nakikita kang malaking puting arrow na nakapinta sa daan at nakaturo sa iyo. Ano ang ibig sabihin nito?","o":["Mali ang direksyon mo","Umikot pabalik sa dulo ng ramp","May two-way na trapiko sa unahan","Puwede kang magmaneho sa alinmang direksyon"],"h1":"Itinuturo ng arrow ang direksyon na dapat puntahan ng trapiko.","h2":"Ang nakapintang arrow na nakaturo sa iyo ay nangangahulugang dapat manggaling ang trapiko sa kabilang direksyon, kaya mali ang direksyon mo at dapat kang huminto at umikot pabalik nang ligtas.","p":"Tama. Mali ang direksyon mo."},"ar":{"q":"على منحدر، ترى سهمًا أبيض كبيرًا مرسومًا على الطريق يشير نحوك. ماذا يعني؟","o":["أنت تسير في الاتجاه الخطأ","استدر في نهاية المنحدر","أمامك طريق باتجاهين","يمكنك أن تقود في أي اتجاه"],"h1":"الأسهم تشير إلى الاتجاه الذي يجب أن تسير فيه السيارات.","h2":"السهم المرسوم الذي يشير نحوك يعني أن السيارات يجب أن تأتي من الاتجاه الآخر، لذلك أنت تسير في الاتجاه الخطأ ويجب أن تتوقف وتستدير بأمان.","p":"صحيح. أنت تسير في الاتجاه الخطأ."},"ht":{"q":"Sou yon ranp, ou wè yon gwo flèch blan pentire sou wout la ki pwente sou ou. Kisa li vle di?","o":["Ou nan move direksyon","Vire tounen nan bout ranp lan","Gen trafik de sans devan","Ou ka kondui nan nenpòt direksyon"],"h1":"Flèch yo montre ki bò trafik la dwe ale.","h2":"Yon flèch pentire ki pwente sou ou vle di trafik la dwe soti nan lòt bò a, kidonk ou nan move direksyon epi ou dwe kanpe epi vire tounen an sekirite.","p":"Se sa. Ou nan move direksyon."}},{"id":"signals-065","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"An intersection has white crisscross lines and the words DO NOT BLOCK. Traffic ahead is stopped. What should you do?","o":["Pull into the marked area and wait","Wait before the marked area until there is room past it","Honk to make cars move","Turn around"],"h1":"The area must stay open for cross traffic.","h2":"DO NOT BLOCK markings mean you must not stop inside the marked area, so wait before it until there is room for your car on the other side.","p":"Right. Do not stop in the marked area."},"es":{"q":"Una intersección tiene líneas blancas cruzadas y las palabras DO NOT BLOCK. El tráfico adelante está parado. ¿Qué debe hacer?","o":["Entrar al área marcada y esperar","Esperar antes del área marcada hasta que haya espacio después","Tocar la bocina para que avancen","Dar la vuelta"],"h1":"El área debe quedar libre para el tráfico que cruza.","h2":"Las marcas DO NOT BLOCK significan que no debe pararse dentro del área marcada, así que espere antes de ella hasta que haya espacio para su carro del otro lado.","p":"Correcto. No se pare en el área marcada."},"zh":{"q":"路口画着白色交叉线和 “DO NOT BLOCK”（不要堵塞）字样。前面的车停住了。你应该怎么做？","o":["开进画线区域里等","在画线区域前面等，直到区域另一边有空位","按喇叭让车子动","掉头"],"h1":"这个区域必须为横向的车留空。","h2":"“DO NOT BLOCK” 标线表示你不能停在画线区域里，所以要在它前面等，直到另一边有空位能容下你的车。","p":"对。不要停在画线区域里。"},"vi":{"q":"Một giao lộ có các đường kẻ chéo màu trắng và chữ “DO NOT BLOCK” (Không chặn lối). Xe phía trước đang dừng. Bạn nên làm gì?","o":["Chạy vào khu vực có kẻ vạch và chờ","Chờ trước khu vực có kẻ vạch cho tới khi phía bên kia có chỗ","Bấm còi để xe khác chạy","Quay đầu"],"h1":"Khu vực này phải để trống cho xe chạy cắt ngang.","h2":"Vạch “DO NOT BLOCK” nghĩa là bạn không được dừng trong khu vực có kẻ vạch, nên hãy chờ trước khu vực đó cho tới khi phía bên kia có chỗ cho xe của bạn.","p":"Đúng rồi. Đừng dừng trong khu vực có kẻ vạch."},"tl":{"q":"May interseksyon na may puting magkakakrus na guhit at mga salitang “DO NOT BLOCK” (Huwag harangan). Nakahinto ang trapiko sa unahan. Ano ang dapat mong gawin?","o":["Pumasok sa may markang bahagi at maghintay","Maghintay bago ang may markang bahagi hanggang may lugar na sa kabila nito","Bumusina para gumalaw ang mga sasakyan","Umikot pabalik"],"h1":"Dapat manatiling bukas ang bahaging ito para sa trapikong tatawid.","h2":"Ang markang “DO NOT BLOCK” ay nangangahulugang hindi ka dapat huminto sa loob ng may markang bahagi, kaya maghintay bago ito hanggang may lugar na para sa sasakyan mo sa kabila.","p":"Tama. Huwag huminto sa may markang bahagi."},"ar":{"q":"في تقاطع خطوط بيضاء متقاطعة وعبارة «DO NOT BLOCK» (لا تسدّ الطريق). السيارات أمامك متوقفة. ماذا يجب أن تفعل؟","o":["ادخل المنطقة المحددة وانتظر","انتظر قبل المنطقة المحددة حتى يوجد مكان بعدها","استخدم البوق لتتحرك السيارات","استدر"],"h1":"يجب أن تبقى هذه المنطقة مفتوحة للسيارات المتقاطعة.","h2":"علامات «DO NOT BLOCK» تعني أنه يجب ألّا تتوقف داخل المنطقة المحددة، لذلك انتظر قبلها حتى يوجد مكان لسيارتك على الجهة الأخرى.","p":"صحيح. يجب ألّا تتوقف في المنطقة المحددة."},"ht":{"q":"Yon kafou gen liy blan ki kwaze youn sou lòt ak mo “DO NOT BLOCK” (pa bloke). Trafik devan an kanpe. Kisa ou dwe fè?","o":["Antre nan espas ki make a epi tann","Tann anvan espas ki make a jiskaske gen plas apre li","Klaksonnen pou machin yo deplase","Vire tounen"],"h1":"Espas sa a dwe rete louvri pou trafik ki travèse a.","h2":"Mak “DO NOT BLOCK” vle di ou pa dwe kanpe anndan espas ki make a, kidonk tann anvan li jiskaske gen plas pou machin ou nan lòt bò a.","p":"Se sa. Pa kanpe nan espas ki make a."}},{"id":"signals-066","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A parking space is outlined in blue, with a white wheelchair symbol. Who may park there?","o":["Any driver for a few minutes","Electric cars only","A driver with a disability parking permit or plate","Delivery trucks only"],"h1":"Blue markings go with the wheelchair symbol.","h2":"Blue markings and the wheelchair symbol show a space reserved for vehicles with a valid disability parking permit or plate.","p":"Right. It is for drivers with a disability permit."},"es":{"q":"Un espacio de estacionamiento está marcado en azul, con un símbolo blanco de silla de ruedas. ¿Quién puede estacionarse allí?","o":["Cualquier conductor por unos minutos","Solo carros eléctricos","Un conductor con permiso o placa de discapacidad","Solo camiones de reparto"],"h1":"Las marcas azules van con el símbolo de silla de ruedas.","h2":"Las marcas azules y el símbolo de silla de ruedas indican un espacio reservado para vehículos con permiso o placa de discapacidad válidos.","p":"Correcto. Es para conductores con permiso de discapacidad."},"zh":{"q":"一个停车位用蓝线画出，里面有白色轮椅图案。谁可以在那里停车？","o":["任何司机都可以停几分钟","只有电动车","有残障停车证或残障车牌的司机","只有送货卡车"],"h1":"蓝色标线和轮椅图案是一起的。","h2":"蓝色标线和轮椅图案表示这个车位是留给有有效残障停车证或残障车牌的车辆的。","p":"对。它是给有残障停车证的司机用的。"},"vi":{"q":"Một chỗ đậu xe được kẻ viền màu xanh dương, có hình xe lăn màu trắng. Ai được đậu ở đó?","o":["Bất kỳ người lái nào trong vài phút","Chỉ xe điện","Người lái có giấy phép hoặc bảng số đậu xe cho người khuyết tật","Chỉ xe tải giao hàng"],"h1":"Vạch màu xanh dương đi kèm với hình xe lăn.","h2":"Vạch màu xanh dương và hình xe lăn cho thấy chỗ đậu này dành riêng cho xe có giấy phép hoặc bảng số đậu xe cho người khuyết tật còn hiệu lực.","p":"Đúng rồi. Chỗ này dành cho người lái có giấy phép người khuyết tật."},"tl":{"q":"May parking space na may asul na guhit sa paligid at puting simbolo ng wheelchair. Sino ang puwedeng pumarada doon?","o":["Kahit sinong driver nang ilang minuto","Mga de-kuryenteng sasakyan lang","Driver na may disability parking permit o plaka","Mga delivery truck lang"],"h1":"Kasama ng simbolo ng wheelchair ang asul na marka.","h2":"Ang asul na marka at simbolo ng wheelchair ay nagpapakita na nakalaan ang puwestong ito para sa mga sasakyang may valid na disability parking permit o plaka.","p":"Tama. Para ito sa mga driver na may disability permit."},"ar":{"q":"موقف سيارات محدد بخطوط زرقاء، وفيه رمز كرسي متحرك أبيض. من يُسمح له بالوقوف هناك؟","o":["أي سائق لبضع دقائق","السيارات الكهربائية فقط","السائق الذي لديه تصريح أو لوحة وقوف لذوي الإعاقة","شاحنات التوصيل فقط"],"h1":"العلامات الزرقاء تأتي مع رمز الكرسي المتحرك.","h2":"العلامات الزرقاء ورمز الكرسي المتحرك تُظهر أن هذا المكان محجوز للسيارات التي لديها تصريح أو لوحة وقوف سارية لذوي الإعاقة.","p":"صحيح. إنه للسائقين الذين لديهم تصريح لذوي الإعاقة."},"ht":{"q":"Yon plas pakin make ak liy ble, ak yon senbòl chèz woulant blan. Kiyès ki ka pake la?","o":["Nenpòt chofè pou kèk minit","Machin elektrik sèlman","Yon chofè ki gen yon pèmi oswa yon plak pakin pou moun ki gen andikap","Kamyon livrezon sèlman"],"h1":"Mak ble yo ale ansanm ak senbòl chèz woulant lan.","h2":"Mak ble ak senbòl chèz woulant lan montre plas sa a rezève pou machin ki gen yon pèmi oswa yon plak pakin valab pou moun ki gen andikap.","p":"Se sa. Li se pou chofè ki gen yon pèmi andikap."}},{"id":"signals-067","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"A lane next to the curb is marked with a solid white line and a bicycle symbol. What is it?","o":["A lane you may use to pass","A parking lane","A shared lane for cars and bikes side by side","A bike lane; do not drive in it"],"h1":"Look at the symbol painted in the lane.","h2":"A lane marked with a solid white line and a bicycle symbol is a bike lane, so do not drive in it, except to enter or cross it carefully where the law allows, such as to turn or park.","p":"Right. It is a bike lane."},"es":{"q":"Un carril junto a la acera está marcado con una línea blanca continua y el símbolo de una bicicleta. ¿Qué es?","o":["Un carril que puede usar para rebasar","Un carril de estacionamiento","Un carril compartido para carros y bicicletas lado a lado","Un carril para bicicletas; no maneje en él"],"h1":"Fíjese en el símbolo pintado en el carril.","h2":"Un carril marcado con una línea blanca continua y el símbolo de bicicleta es un carril para bicicletas, así que no maneje en él, salvo para entrar o cruzarlo con cuidado donde la ley lo permita, por ejemplo para girar o estacionarse.","p":"Correcto. Es un carril para bicicletas."},"zh":{"q":"靠路边的一条车道用白色实线标出，并画着自行车图案。它是什么？","o":["你可以用来超车的车道","停车道","汽车和自行车并排共用的车道","自行车道，不要在里面开车"],"h1":"看一看车道里画的图案。","h2":"用白色实线标出并画着自行车图案的车道是自行车道，所以不要在里面开车，除非在法律允许的地方（例如转弯或停车时）小心地进入或穿过它。","p":"对。它是自行车道。"},"vi":{"q":"Một làn sát lề đường được kẻ vạch trắng liền và có hình xe đạp. Đó là gì?","o":["Làn bạn có thể dùng để vượt xe","Làn đậu xe","Làn dùng chung để xe hơi và xe đạp chạy song song","Làn xe đạp; đừng chạy xe hơi trong đó"],"h1":"Hãy nhìn hình được sơn trong làn.","h2":"Làn được kẻ vạch trắng liền và có hình xe đạp là làn xe đạp, nên đừng chạy xe trong đó, trừ khi cần đi vào hoặc băng qua nó một cách cẩn thận ở chỗ luật cho phép, như để rẽ hoặc đậu xe.","p":"Đúng rồi. Đó là làn xe đạp."},"tl":{"q":"May lane sa tabi ng gilid ng daan na may tuloy-tuloy na puting guhit at simbolo ng bisikleta. Ano ito?","o":["Lane na puwede mong gamitin para mag-overtake","Lane para sa paradahan","Shared lane para magkatabi ang kotse at bisikleta","Bike lane; huwag magmaneho dito"],"h1":"Tingnan ang simbolong nakapinta sa lane.","h2":"Ang lane na may tuloy-tuloy na puting guhit at simbolo ng bisikleta ay bike lane, kaya huwag kang magmaneho dito, maliban kung papasok o tatawid ka nang maingat kung saan pinapayagan ng batas, gaya ng pagliko o pagparada.","p":"Tama. Ito ay bike lane."},"ar":{"q":"مسار بجانب الرصيف محدد بخط أبيض متصل ورمز دراجة هوائية. ما هو؟","o":["مسار يمكنك استخدامه للتجاوز","مسار للوقوف","مسار مشترك تسير فيه السيارات والدراجات جنبًا إلى جنب","مسار للدراجات؛ يجب ألّا تقود فيه"],"h1":"انظر إلى الرمز المرسوم في المسار.","h2":"المسار المحدد بخط أبيض متصل ورمز دراجة هوائية هو مسار للدراجات، لذلك يجب ألّا تقود فيه، إلا لتدخله أو تعبره بحذر حيث يسمح القانون، مثل الانعطاف أو الوقوف.","p":"صحيح. إنه مسار للدراجات."},"ht":{"q":"Yon liy bò twotwa a make ak yon liy blan kontinyèl ak yon senbòl bisiklèt. Kisa li ye?","o":["Yon liy ou ka sèvi pou depase","Yon liy pou pake","Yon liy machin ak bisiklèt pataje kòt a kòt","Yon liy bisiklèt; pa kondui ladan l"],"h1":"Gade senbòl ki pentire nan liy lan.","h2":"Yon liy ki make ak yon liy blan kontinyèl ak yon senbòl bisiklèt se yon liy bisiklèt, kidonk pa kondui ladan l, sof pou antre oswa travèse l ak atansyon kote lalwa pèmèt sa, tankou pou vire oswa pou pake.","p":"Se sa. Se yon liy bisiklèt."}},{"id":"signals-068","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Part of the road is painted bright green. What does green pavement usually show?","o":["A bike lane or a place where bikes cross","A parking area","A bus stop","A place to make U-turns"],"h1":"Green paint is used for bicycle areas.","h2":"Green-colored pavement marks a bike lane or an area where bicycles cross, so watch for bicycle riders there.","p":"Right. Green pavement is for bicycles."},"es":{"q":"Una parte de la vía está pintada de verde brillante. ¿Qué suele indicar el pavimento verde?","o":["Un carril para bicicletas o un lugar donde cruzan bicicletas","Un área de estacionamiento","Una parada de autobús","Un lugar para dar vuelta en U"],"h1":"La pintura verde se usa para zonas de bicicletas.","h2":"El pavimento verde marca un carril para bicicletas o un área donde cruzan bicicletas, así que fíjese en los ciclistas allí.","p":"Correcto. El pavimento verde es para bicicletas."},"zh":{"q":"一部分路面涂成鲜绿色。绿色路面通常表示什么？","o":["自行车道或自行车穿过的地方","停车区","公交车站","掉头的地方"],"h1":"绿色涂料用于自行车区域。","h2":"绿色路面标出自行车道或自行车穿过的区域，所以在那里要注意骑自行车的人。","p":"对。绿色路面是给自行车用的。"},"vi":{"q":"Một phần mặt đường được sơn màu xanh lá sáng. Mặt đường màu xanh lá thường cho thấy điều gì?","o":["Làn xe đạp hoặc chỗ xe đạp băng qua","Khu vực đậu xe","Trạm xe buýt","Chỗ để quay đầu xe"],"h1":"Sơn xanh lá được dùng cho khu vực xe đạp.","h2":"Mặt đường màu xanh lá đánh dấu làn xe đạp hoặc khu vực xe đạp băng qua, nên hãy để ý người đi xe đạp ở đó.","p":"Đúng rồi. Mặt đường xanh lá là dành cho xe đạp."},"tl":{"q":"May bahagi ng daan na pinintahan ng matingkad na berde. Ano ang karaniwang ipinapakita ng berdeng daan?","o":["Bike lane o lugar kung saan tumatawid ang mga bisikleta","Lugar na paradahan","Hintuan ng bus","Lugar para mag-U-turn"],"h1":"Ginagamit ang berdeng pintura para sa mga lugar ng bisikleta.","h2":"Ang berdeng daan ay nagmamarka ng bike lane o lugar kung saan tumatawid ang mga bisikleta, kaya mag-ingat sa mga nagbibisikleta doon.","p":"Tama. Para sa bisikleta ang berdeng daan."},"ar":{"q":"جزء من الطريق مدهون باللون الأخضر الفاتح. ماذا يُظهر الطريق الأخضر عادةً؟","o":["مسار للدراجات أو مكان تعبر فيه الدراجات","منطقة وقوف","موقف حافلات","مكان للاستدارة للخلف"],"h1":"الطلاء الأخضر يُستخدم لمناطق الدراجات.","h2":"الطريق الملوّن بالأخضر يحدد مسارًا للدراجات أو منطقة تعبر فيها الدراجات، لذلك انتبه لراكبي الدراجات هناك.","p":"صحيح. الطريق الأخضر للدراجات."},"ht":{"q":"Yon pati nan wout la pentire vèt klè. Kisa yon wout vèt montre anjeneral?","o":["Yon liy bisiklèt oswa yon kote bisiklèt travèse","Yon zòn pakin","Yon arè bis","Yon kote pou fè demi-tou"],"h1":"Yo sèvi ak penti vèt pou zòn bisiklèt.","h2":"Yon wout ki pentire vèt make yon liy bisiklèt oswa yon zòn kote bisiklèt travèse, kidonk veye moun ki sou bisiklèt la.","p":"Se sa. Wout vèt la se pou bisiklèt."}},{"id":"signals-069","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"At a red light, there is a green box with a bicycle symbol between the stop line and the crosswalk. Where should you stop your car?","o":["Inside the green box","Behind the box, at the first stop line","In the crosswalk","Next to the box"],"h1":"The box is a waiting space for bicycles.","h2":"A bike box gives bicycles a place to wait in front of cars, so drivers must stop behind it at the first stop line.","p":"Right. Stop behind the bike box."},"es":{"q":"Con el semáforo en rojo, hay un recuadro verde con el símbolo de bicicleta entre la línea de pare y el cruce peatonal. ¿Dónde debe parar su carro?","o":["Dentro del recuadro verde","Detrás del recuadro, en la primera línea de pare","En el cruce peatonal","Al lado del recuadro"],"h1":"El recuadro es un espacio de espera para bicicletas.","h2":"Un recuadro para bicicletas da a los ciclistas un lugar para esperar delante de los carros, así que los conductores deben pararse detrás, en la primera línea de pare.","p":"Correcto. Párese detrás del recuadro."},"zh":{"q":"红灯时，在停车线和人行横道之间有一个画着自行车图案的绿色方框。你应该把车停在哪里？","o":["绿色方框里面","方框后面，第一条停车线处","人行横道上","方框旁边"],"h1":"这个方框是给自行车等候的地方。","h2":"自行车等候区让自行车在汽车前面等候，所以司机必须停在它后面的第一条停车线处。","p":"对。停在自行车等候区后面。"},"vi":{"q":"Khi đèn đỏ, có một ô màu xanh lá có hình xe đạp nằm giữa vạch dừng và lối băng qua đường. Bạn nên dừng xe ở đâu?","o":["Bên trong ô xanh lá","Phía sau ô, tại vạch dừng thứ nhất","Trên lối băng qua đường","Bên cạnh ô"],"h1":"Ô này là chỗ chờ cho xe đạp.","h2":"Ô chờ xe đạp cho xe đạp chỗ chờ phía trước xe hơi, nên người lái xe hơi phải dừng phía sau nó, tại vạch dừng thứ nhất.","p":"Đúng rồi. Hãy dừng phía sau ô chờ xe đạp."},"tl":{"q":"Sa pulang ilaw, may berdeng kahon na may simbolo ng bisikleta sa pagitan ng stop line at ng tawiran. Saan mo dapat ihinto ang sasakyan mo?","o":["Sa loob ng berdeng kahon","Sa likod ng kahon, sa unang stop line","Sa tawiran","Sa tabi ng kahon"],"h1":"Ang kahon ay lugar na hintayan ng mga bisikleta.","h2":"Ang bike box ay nagbibigay sa mga bisikleta ng lugar na hintayan sa harap ng mga kotse, kaya dapat huminto ang mga driver sa likod nito, sa unang stop line.","p":"Tama. Huminto sa likod ng bike box."},"ar":{"q":"عند الضوء الأحمر، يوجد مربع أخضر عليه رمز دراجة هوائية بين خط التوقف وممر المشاة. أين يجب أن توقف سيارتك؟","o":["داخل المربع الأخضر","خلف المربع، عند خط التوقف الأول","في ممر المشاة","بجانب المربع"],"h1":"المربع مكان انتظار للدراجات.","h2":"مربع الدراجات يعطي الدراجات مكانًا للانتظار أمام السيارات، لذلك يجب على السائقين أن يتوقفوا خلفه عند خط التوقف الأول.","p":"صحيح. توقف خلف مربع الدراجات."},"ht":{"q":"Nan yon limyè wouj, gen yon bwat vèt ak yon senbòl bisiklèt ant liy kanpe a ak pasaj pyeton an. Ki kote ou dwe kanpe machin ou?","o":["Anndan bwat vèt la","Dèyè bwat la, nan premye liy kanpe a","Nan pasaj pyeton an","Bò kote bwat la"],"h1":"Bwat la se yon kote pou bisiklèt tann.","h2":"Yon bwat bisiklèt bay bisiklèt yo yon kote pou tann devan machin yo, kidonk chofè yo dwe kanpe dèyè li, nan premye liy kanpe a.","p":"Se sa. Kanpe dèyè bwat bisiklèt la."}},{"id":"signals-070","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"A lane is painted red and has the words BUS ONLY. Who may drive in it?","o":["Any car during rush hour","Bicycles only","Only buses, or vehicles the signs allow","Taxis waiting to park"],"h1":"Read the words in the lane.","h2":"A red lane marked BUS ONLY is reserved for public transit buses, so other drivers must stay out unless signs allow it.","p":"Right. Only buses may use it."},"es":{"q":"Un carril está pintado de rojo y tiene las palabras BUS ONLY. ¿Quién puede manejar en él?","o":["Cualquier carro en horas pico","Solo bicicletas","Solo autobuses, o los vehículos que permitan las señales","Taxis que esperan para estacionarse"],"h1":"Lea las palabras en el carril.","h2":"Un carril rojo marcado BUS ONLY está reservado para los autobuses de transporte público, así que los demás deben quedarse fuera a menos que las señales lo permitan.","p":"Correcto. Solo los autobuses pueden usarlo."},"zh":{"q":"一条车道涂成红色，并写着 “BUS ONLY”（公交专用）。谁可以在里面开？","o":["高峰时间任何汽车","只有自行车","只有公交车，或标志允许的车辆","等着停车的出租车"],"h1":"读一读车道里的字。","h2":"写着 “BUS ONLY” 的红色车道是留给公共交通公交车的，所以其他司机不能进去，除非标志允许。","p":"对。只有公交车可以用。"},"vi":{"q":"Một làn được sơn màu đỏ và có chữ “BUS ONLY” (Chỉ dành cho xe buýt). Ai được chạy trong làn này?","o":["Bất kỳ xe hơi nào vào giờ cao điểm","Chỉ xe đạp","Chỉ xe buýt, hoặc xe mà biển báo cho phép","Taxi đang chờ đậu"],"h1":"Hãy đọc chữ trong làn.","h2":"Làn màu đỏ có chữ “BUS ONLY” dành riêng cho xe buýt công cộng, nên những người lái khác phải tránh ra, trừ khi biển báo cho phép.","p":"Đúng rồi. Chỉ xe buýt được dùng làn này."},"tl":{"q":"May lane na pinintahan ng pula at may mga salitang “BUS ONLY” (Bus lang). Sino ang puwedeng magmaneho dito?","o":["Kahit anong kotse sa rush hour","Mga bisikleta lang","Mga bus lang, o mga sasakyang pinapayagan ng karatula","Mga taxi na naghihintay pumarada"],"h1":"Basahin ang mga salita sa lane.","h2":"Ang pulang lane na may markang “BUS ONLY” ay nakalaan para sa mga pampublikong bus, kaya dapat lumayo dito ang ibang driver maliban kung pinapayagan ng mga karatula.","p":"Tama. Mga bus lang ang puwedeng gumamit nito."},"ar":{"q":"مسار مدهون باللون الأحمر ومكتوب عليه «BUS ONLY» (للحافلات فقط). من يُسمح له بالقيادة فيه؟","o":["أي سيارة في ساعة الذروة","الدراجات الهوائية فقط","الحافلات فقط، أو المركبات التي تسمح بها اللافتات","سيارات الأجرة التي تنتظر الوقوف"],"h1":"اقرأ الكلمات المكتوبة في المسار.","h2":"المسار الأحمر المكتوب عليه «BUS ONLY» محجوز لحافلات النقل العام، لذلك يجب ألّا يدخله السائقون الآخرون إلا إذا سمحت اللافتات بذلك.","p":"صحيح. الحافلات فقط يمكنها استخدامه."},"ht":{"q":"Yon liy pentire wouj epi li gen mo “BUS ONLY” (bis sèlman). Kiyès ki ka kondui ladan l?","o":["Nenpòt machin nan lè trafik chaje","Bisiklèt sèlman","Bis sèlman, oswa machin pankat yo pèmèt","Taksi k ap tann pou pake"],"h1":"Li mo ki ekri nan liy lan.","h2":"Yon liy wouj ki make “BUS ONLY” rezève pou bis transpò piblik, kidonk lòt chofè yo dwe rete deyò sof si pankat yo pèmèt sa.","p":"Se sa. Se bis sèlman ki ka sèvi ak li."}},{"id":"signals-071","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"Painted on the road ahead you see a large X with the letters R R. What does it mean?","o":["A road repair is ahead","A rest room is ahead","Right lane only","A railroad crossing is ahead"],"h1":"It matches the round yellow warning sign.","h2":"A large X with RR painted on the road warns that a railroad crossing is ahead, so slow down and look and listen for trains.","p":"Right. A railroad crossing is ahead."},"es":{"q":"Pintada en la vía adelante, usted ve una gran X con las letras R R. ¿Qué significa?","o":["Que hay una reparación de la vía","Que hay baños adelante","Que es solo carril derecho","Que hay un cruce de tren adelante"],"h1":"Es igual a la señal amarilla redonda de advertencia.","h2":"Una gran X con RR pintada en la vía advierte que hay un cruce de tren adelante, así que baje la velocidad y mire y escuche si viene un tren.","p":"Correcto. Hay un cruce de tren adelante."},"zh":{"q":"你看到前面路面上画着一个大 X 和字母 R R。它是什么意思？","o":["前面在修路","前面有洗手间","只限右车道","前面有铁路道口"],"h1":"它和圆形黄色警告标志的意思一样。","h2":"路面上画着带 RR 的大 X，提醒你前面有铁路道口，所以要减速，并看一看、听一听有没有火车。","p":"对。前面有铁路道口。"},"vi":{"q":"Bạn thấy trên mặt đường phía trước có sơn một chữ X lớn với hai chữ R R. Nó có nghĩa là gì?","o":["Phía trước có sửa đường","Phía trước có nhà vệ sinh","Chỉ làn bên phải","Phía trước có chỗ băng qua đường xe lửa"],"h1":"Nó giống với biển cảnh báo tròn màu vàng.","h2":"Chữ X lớn với RR sơn trên đường cảnh báo phía trước có chỗ băng qua đường xe lửa, nên hãy chạy chậm lại, nhìn và lắng nghe xem có xe lửa không.","p":"Đúng rồi. Phía trước có chỗ băng qua đường xe lửa."},"tl":{"q":"Sa daan sa unahan, may nakapintang malaking X na may mga letrang R R. Ano ang ibig sabihin nito?","o":["May inaayos na daan sa unahan","May banyo sa unahan","Kanang lane lang","May tawiran ng tren sa unahan"],"h1":"Kapareho ito ng bilog na dilaw na babalang karatula.","h2":"Ang malaking X na may RR na nakapinta sa daan ay babala na may tawiran ng tren sa unahan, kaya bumagal at tumingin at makinig kung may tren.","p":"Tama. May tawiran ng tren sa unahan."},"ar":{"q":"ترى على الطريق أمامك حرف X كبيرًا مرسومًا مع الحرفين R R. ماذا يعني؟","o":["أمامك إصلاح للطريق","أمامك دورة مياه","المسار الأيمن فقط","أمامك معبر سكة حديد"],"h1":"إنه مثل لافتة التحذير الصفراء المستديرة.","h2":"حرف X الكبير مع RR المرسوم على الطريق يحذّر من أن أمامك معبر سكة حديد، لذلك خفف السرعة وانظر واستمع لتعرف إن كان هناك قطار.","p":"صحيح. أمامك معبر سكة حديد."},"ht":{"q":"Ou wè yon gwo X ak lèt R R pentire sou wout la devan ou. Kisa li vle di?","o":["Gen reparasyon wout devan","Gen yon twalèt devan","Liy dwat sèlman","Gen yon kwazman tren devan"],"h1":"Li matche ak pankat avètisman jòn won an.","h2":"Yon gwo X ak RR pentire sou wout la avèti ou gen yon kwazman tren devan, kidonk ralanti epi gade epi koute si gen tren.","p":"Se sa. Gen yon kwazman tren devan."}},{"id":"signals-072","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"White lines are painted across your lane, and they get closer together as you go. Why?","o":["To warn you to slow down","To mark a parking area","To show a bike crossing","To tell you to speed up"],"h1":"Lines that come faster make you feel you are going faster.","h2":"Speed reduction markings get closer together to make you feel your speed and warn you to slow down, often before a curve or stop.","p":"Right. They warn you to slow down."},"es":{"q":"Hay líneas blancas pintadas a lo ancho de su carril, y están cada vez más juntas. ¿Por qué?","o":["Para advertirle que baje la velocidad","Para marcar un área de estacionamiento","Para indicar un cruce de bicicletas","Para indicarle que acelere"],"h1":"Si las líneas pasan más rápido, usted siente que va más rápido.","h2":"Las marcas de reducción de velocidad se juntan cada vez más para que sienta su velocidad y le advierten que baje la velocidad, muchas veces antes de una curva o una parada.","p":"Correcto. Le advierten que baje la velocidad."},"zh":{"q":"你的车道上横着画了白线，越往前线越密。为什么？","o":["提醒你减速","标出停车区","表示自行车穿越处","叫你加速"],"h1":"线条来得越快，你会觉得自己开得越快。","h2":"减速标线越来越密，让你感觉到自己的速度，提醒你减速，常常设在弯道或停车处之前。","p":"对。它们提醒你减速。"},"vi":{"q":"Có những vạch trắng được sơn ngang làn của bạn, và càng đi tới thì chúng càng sát nhau hơn. Tại sao?","o":["Để cảnh báo bạn chạy chậm lại","Để đánh dấu khu vực đậu xe","Để chỉ chỗ xe đạp băng qua","Để bảo bạn tăng tốc"],"h1":"Vạch đến nhanh hơn làm bạn thấy mình đang chạy nhanh hơn.","h2":"Vạch giảm tốc độ ngày càng sát nhau để bạn cảm nhận tốc độ của mình và cảnh báo bạn chạy chậm lại, thường là trước khúc cua hoặc chỗ phải dừng.","p":"Đúng rồi. Chúng cảnh báo bạn chạy chậm lại."},"tl":{"q":"May mga puting guhit na nakapinta nang pahalang sa lane mo, at lalong nagkakalapit ang mga ito habang umaandar ka. Bakit?","o":["Para babalaan kang bumagal","Para markahan ang lugar na paradahan","Para ipakita ang tawiran ng bisikleta","Para sabihan kang bumilis"],"h1":"Kapag mas mabilis dumating ang mga guhit, pakiramdam mo ay mas mabilis ka.","h2":"Ang mga speed reduction marking ay lalong nagkakalapit para maramdaman mo ang bilis mo at babalaan kang bumagal, kadalasan bago ang kurbada o hintuan.","p":"Tama. Binababalaan ka nilang bumagal."},"ar":{"q":"خطوط بيضاء مرسومة بالعرض في مسارك، وتصبح أقرب إلى بعضها كلما تقدمت. لماذا؟","o":["لتحذّرك أن تخفف السرعة","لتحدد منطقة وقوف","لتُظهر معبرًا للدراجات","لتطلب منك أن تزيد السرعة"],"h1":"الخطوط التي تأتي أسرع تجعلك تشعر بأنك تسير أسرع.","h2":"علامات تخفيف السرعة تصبح أقرب إلى بعضها لتجعلك تشعر بسرعتك وتحذّرك أن تخفف السرعة، وغالبًا تكون قبل منعطف أو مكان توقف.","p":"صحيح. إنها تحذّرك أن تخفف السرعة."},"ht":{"q":"Gen liy blan pentire an travè nan liy ou a, epi yo vin pi pre youn ak lòt plis w ap avanse. Poukisa?","o":["Pou avèti ou ralanti","Pou make yon zòn pakin","Pou montre yon kwazman bisiklèt","Pou di ou akselere"],"h1":"Liy ki vini pi vit fè ou santi w ap kondui pi vit.","h2":"Mak pou diminye vitès yo vin pi pre youn ak lòt pou fè ou santi vitès ou epi avèti ou ralanti, souvan anvan yon koub oswa yon kote pou kanpe.","p":"Se sa. Yo avèti ou ralanti."}},{"id":"signals-073","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"A raised part of the road is painted with white stripes or arrow shapes. What is it?","o":["A crosswalk for bikes","A speed hump; slow down before it","A place to stop for trains","A loading zone"],"h1":"It is a bump built on purpose.","h2":"White markings on a raised part of the road show a speed hump, so slow down before you drive over it.","p":"Right. It is a speed hump."},"es":{"q":"Una parte elevada de la vía está pintada con rayas blancas o figuras de flecha. ¿Qué es?","o":["Un cruce para bicicletas","Un reductor de velocidad; baje la velocidad antes","Un lugar para pararse por trenes","Una zona de carga"],"h1":"Es un tope hecho a propósito.","h2":"Las marcas blancas en una parte elevada de la vía indican un reductor de velocidad (tope), así que baje la velocidad antes de pasarlo.","p":"Correcto. Es un tope."},"zh":{"q":"路面上一块凸起的地方画着白色条纹或箭头形状。它是什么？","o":["自行车人行横道","减速带，开到前面要减速","等火车时停车的地方","装卸区"],"h1":"这是故意做出来的凸起。","h2":"路面凸起处的白色标线表示减速带，所以开过去之前要减速。","p":"对。它是减速带。"},"vi":{"q":"Một phần mặt đường nhô lên được sơn sọc trắng hoặc hình mũi tên. Đó là gì?","o":["Lối băng qua đường cho xe đạp","Gờ giảm tốc; hãy chạy chậm lại trước khi tới đó","Chỗ dừng để chờ xe lửa","Khu vực bốc dỡ hàng"],"h1":"Đó là một gờ được làm ra có chủ ý.","h2":"Vạch trắng trên phần mặt đường nhô lên cho thấy đó là gờ giảm tốc, nên hãy chạy chậm lại trước khi chạy qua nó.","p":"Đúng rồi. Đó là gờ giảm tốc."},"tl":{"q":"May nakaumbok na bahagi ng daan na pinintahan ng puting guhit o hugis-arrow. Ano ito?","o":["Tawiran para sa bisikleta","Speed hump; bumagal bago ito","Lugar para huminto para sa tren","Loading zone"],"h1":"Isa itong umbok na sadyang ginawa.","h2":"Ang puting marka sa nakaumbok na bahagi ng daan ay nagpapakita ng speed hump, kaya bumagal bago mo ito daanan.","p":"Tama. Ito ay speed hump."},"ar":{"q":"جزء مرتفع من الطريق مدهون بخطوط بيضاء أو بأشكال أسهم. ما هو؟","o":["ممر عبور للدراجات","مطب لتخفيف السرعة؛ خفف السرعة قبله","مكان للتوقف من أجل القطارات","منطقة تحميل وتنزيل"],"h1":"إنه مطب مصنوع عن قصد.","h2":"العلامات البيضاء على الجزء المرتفع من الطريق تُظهر مطبًا لتخفيف السرعة، لذلك خفف السرعة قبل أن تمر فوقه.","p":"صحيح. إنه مطب لتخفيف السرعة."},"ht":{"q":"Yon pati nan wout la ki leve pentire ak bann blan oswa fòm flèch. Kisa li ye?","o":["Yon pasaj pou bisiklèt","Yon do bourik; ralanti anvan li","Yon kote pou kanpe pou tren","Yon zòn chajman"],"h1":"Se yon bòs yo fè espre.","h2":"Mak blan sou yon pati nan wout la ki leve montre yon do bourik, kidonk ralanti anvan ou pase sou li.","p":"Se sa. Se yon do bourik."}},{"id":"signals-074","scope":"US","cat":"signals","sign":null,"c":2,"en":{"q":"Wide white bars are painted across the street, side by side like a ladder. What do they mark?","o":["A parking area","A lane for buses","A crosswalk where people on foot cross","A place to stop for trains"],"h1":"These bars are easy for drivers to see.","h2":"Wide white bars across the street mark a high-visibility crosswalk, so watch for people crossing and be ready to yield.","p":"Right. It is a crosswalk."},"es":{"q":"Hay barras blancas anchas pintadas a lo ancho de la calle, una al lado de otra como una escalera. ¿Qué marcan?","o":["Un área de estacionamiento","Un carril de autobuses","Un cruce donde cruzan los peatones","Un lugar para pararse por trenes"],"h1":"Estas barras son fáciles de ver para los conductores.","h2":"Las barras blancas anchas a lo ancho de la calle marcan un cruce peatonal de alta visibilidad, así que fíjese en las personas que cruzan y esté listo para cederles el paso.","p":"Correcto. Es un cruce peatonal."},"zh":{"q":"街道上横着画了一条条很宽的白色横杠，一条挨着一条，像梯子一样。它们标示的是什么？","o":["停车区","公交车专用车道","行人过马路的人行横道","给火车停车的地方"],"h1":"这些横杠让司机很容易看到。","h2":"横跨街道的宽白色横杠标示的是醒目的人行横道，所以要注意过马路的人，并准备好让行。","p":"对。这是人行横道。"},"vi":{"q":"Có những vạch trắng rộng được sơn ngang qua đường, nằm cạnh nhau như cái thang. Chúng đánh dấu điều gì?","o":["Một khu đậu xe","Một làn dành cho xe buýt","Vạch qua đường nơi người đi bộ băng qua","Một chỗ dừng lại cho tàu hỏa"],"h1":"Những vạch này giúp tài xế dễ nhìn thấy.","h2":"Những vạch trắng rộng ngang qua đường đánh dấu một vạch qua đường dễ nhìn thấy, vì vậy hãy để ý người đang băng qua và sẵn sàng nhường đường.","p":"Đúng. Đó là vạch qua đường."},"tl":{"q":"May malalapad na puting guhit na nakapinta sa kabila ng kalye, magkakatabi na parang hagdan. Ano ang ipinapakita ng mga ito?","o":["Isang paradahan","Isang lane para sa mga bus","Isang tawiran kung saan tumatawid ang mga naglalakad","Isang lugar para huminto para sa tren"],"h1":"Madaling makita ng mga driver ang mga guhit na ito.","h2":"Ang malalapad na puting guhit sa kabila ng kalye ay nagpapakita ng tawirang madaling makita, kaya bantayan ang mga tumatawid at maging handang magbigay-daan.","p":"Tama. Isa itong tawiran."},"ar":{"q":"خطوط بيضاء عريضة مرسومة عرضيًا على الشارع، بجانب بعضها مثل السُّلّم. ماذا تحدّد؟","o":["منطقة لوقوف السيارات","مسارًا للحافلات","ممرًا للمشاة حيث يعبر الناس سيرًا على الأقدام","مكانًا للتوقف من أجل القطارات"],"h1":"هذه الخطوط سهلة الرؤية للسائقين.","h2":"الخطوط البيضاء العريضة عبر الشارع تحدّد ممر مشاة واضحًا جدًا، لذلك انتبه للناس الذين يعبرون وكن مستعدًا لإعطائهم حق المرور.","p":"صحيح. إنه ممر مشاة."},"ht":{"q":"Gen gwo ba blan ki pentire atravè lari a, youn bò lòt tankou yon nechèl. Kisa yo make?","o":["Yon zòn pou pakin","Yon liy pou otobis","Yon pasaj pyeton kote moun a pye travèse","Yon kote pou kanpe pou tren"],"h1":"Chofè yo ka wè ba sa yo fasilman.","h2":"Gwo ba blan atravè lari a make yon pasaj pyeton ki fasil pou wè, kidonk veye moun k ap travèse epi pare pou ba yo pase.","p":"Se sa. Se yon pasaj pyeton."}},{"id":"signals-075","scope":"US","cat":"signals","sign":null,"c":3,"en":{"q":"The words STOP AHEAD are painted on the road in your lane. What should you do?","o":["Stop right on the words","Speed up before the stop","Change lanes","Get ready to stop soon"],"h1":"Word markings repeat what signs say.","h2":"STOP AHEAD painted in your lane warns that a stop is coming, so slow down and be ready to stop.","p":"Right. A stop is coming."},"es":{"q":"Las palabras STOP AHEAD están pintadas en la vía, en su carril. ¿Qué debe hacer?","o":["Pararse justo encima de las palabras","Acelerar antes de la parada","Cambiar de carril","Prepararse para pararse pronto"],"h1":"Las palabras pintadas repiten lo que dicen las señales.","h2":"STOP AHEAD pintado en su carril advierte que viene una parada, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Viene una parada."},"zh":{"q":"你的车道路面上画着“STOP AHEAD”（前方停车）这几个字。你应该怎么做？","o":["就停在这些字上面","在停车之前加速","换车道","准备好马上要停车"],"h1":"路面上的字会重复标志上说的话。","h2":"你车道上画的“STOP AHEAD”（前方停车）提醒你前面要停车，所以要减速并准备停车。","p":"对。前面要停车。"},"vi":{"q":"Chữ \"STOP AHEAD\" (phía trước phải dừng) được sơn trên mặt đường trong làn của bạn. Bạn nên làm gì?","o":["Dừng ngay trên hàng chữ","Tăng tốc trước khi dừng","Đổi làn","Chuẩn bị sắp phải dừng lại"],"h1":"Chữ sơn trên đường nhắc lại điều biển báo nói.","h2":"Chữ \"STOP AHEAD\" (phía trước phải dừng) sơn trong làn của bạn cảnh báo sắp phải dừng, vì vậy hãy giảm tốc độ và sẵn sàng dừng lại.","p":"Đúng. Sắp phải dừng lại."},"tl":{"q":"Nakapinta sa kalsada sa iyong lane ang mga salitang \"STOP AHEAD\" (may hintuan sa unahan). Ano ang dapat mong gawin?","o":["Huminto mismo sa ibabaw ng mga salita","Bumilis bago ang hintuan","Lumipat ng lane","Maghandang huminto sa lalong madaling panahon"],"h1":"Inuulit ng mga salitang nakapinta sa kalsada ang sinasabi ng mga karatula.","h2":"Ang \"STOP AHEAD\" (may hintuan sa unahan) na nakapinta sa iyong lane ay babala na may hintuan nang paparating, kaya magdahan-dahan at maging handang huminto.","p":"Tama. May hintuan nang paparating."},"ar":{"q":"عبارة \"STOP AHEAD\" (توقّف أمامك) مكتوبة على الطريق في مسارك. ماذا يجب أن تفعل؟","o":["توقف فوق الكلمات مباشرة","زد السرعة قبل التوقف","غيّر المسار","استعد للتوقف قريبًا"],"h1":"الكلمات المرسومة على الطريق تكرّر ما تقوله اللافتات.","h2":"عبارة \"STOP AHEAD\" (توقّف أمامك) المرسومة في مسارك تحذّر من أن هناك توقفًا قادمًا، لذلك خفّف السرعة وكن مستعدًا للتوقف.","p":"صحيح. هناك توقف قادم."},"ht":{"q":"Mo \"STOP AHEAD\" (kanpe pi devan) pentire sou wout la nan liy ou. Kisa ou dwe fè?","o":["Kanpe dwat sou mo yo","Akselere anvan ou kanpe","Chanje liy","Pare pou kanpe talè"],"h1":"Mo ki pentire sou wout la repete sa pano yo di.","h2":"\"STOP AHEAD\" (kanpe pi devan) ki pentire nan liy ou a avèti ou gen yon kanpe k ap vini, kidonk ralanti epi pare pou kanpe.","p":"Se sa. Gen yon kanpe k ap vini."}},{"id":"signals-076","scope":"US","cat":"signals","sign":null,"c":0,"en":{"q":"Small raised markers (road reflectors) are placed along the lane lines. Why?","o":["To help you see the lanes at night and in rain","To slow cars down","To mark parking spaces","To show where to pass"],"h1":"They shine when your headlights hit them.","h2":"Raised pavement markers reflect your headlights so you can see the lane lines better at night and when the road is wet.","p":"Right. They help you see the lanes."},"es":{"q":"Hay pequeños marcadores elevados (reflectores) a lo largo de las líneas de los carriles. ¿Para qué?","o":["Para ayudarle a ver los carriles de noche y con lluvia","Para que los carros vayan más lento","Para marcar espacios de estacionamiento","Para indicar dónde rebasar"],"h1":"Brillan cuando les llega la luz de sus faros.","h2":"Los marcadores elevados reflejan la luz de sus faros para que vea mejor las líneas de los carriles de noche y cuando la vía está mojada.","p":"Correcto. Le ayudan a ver los carriles."},"zh":{"q":"车道线旁边放着一些凸起的小标记（道路反光钉）。为什么？","o":["帮助你在夜里和下雨时看清车道","让车慢下来","标出停车位","告诉你在哪里超车"],"h1":"车灯照到它们时，它们会发亮。","h2":"凸起的路面标记会反射你的车灯，让你在夜里和路面湿的时候更容易看清车道线。","p":"对。它们帮助你看清车道。"},"vi":{"q":"Có những cục đánh dấu nhỏ nhô lên (đinh phản quang) được gắn dọc theo vạch kẻ làn. Để làm gì?","o":["Giúp bạn nhìn thấy làn đường vào ban đêm và khi trời mưa","Làm xe chạy chậm lại","Đánh dấu chỗ đậu xe","Chỉ chỗ được vượt"],"h1":"Chúng sáng lên khi đèn pha của bạn chiếu vào.","h2":"Các cục đánh dấu nhô lên trên mặt đường phản chiếu đèn pha của bạn, để bạn nhìn thấy vạch kẻ làn rõ hơn vào ban đêm và khi đường ướt.","p":"Đúng. Chúng giúp bạn nhìn thấy làn đường."},"tl":{"q":"May maliliit na nakaumbok na marker (road reflector) sa tabi ng mga guhit ng lane. Bakit?","o":["Para matulungan kang makita ang mga lane sa gabi at kapag umuulan","Para pabagalin ang mga sasakyan","Para markahan ang mga paradahan","Para ipakita kung saan puwedeng mag-overtake"],"h1":"Kumikinang sila kapag natamaan ng iyong headlights.","h2":"Ang mga nakaumbok na marker sa kalsada ay nagpapabalik ng liwanag ng iyong headlights para mas makita mo ang mga guhit ng lane sa gabi at kapag basa ang kalsada.","p":"Tama. Tinutulungan ka nilang makita ang mga lane."},"ar":{"q":"علامات صغيرة بارزة (عاكسات الطريق) موضوعة على طول خطوط المسارات. لماذا؟","o":["لتساعدك على رؤية المسارات في الليل وفي المطر","لتبطئ السيارات","لتحديد أماكن الوقوف","لتبيّن أين يمكنك التجاوز"],"h1":"إنها تلمع عندما تصل إليها أضواء سيارتك الأمامية.","h2":"العلامات البارزة على الطريق تعكس أضواء سيارتك الأمامية، حتى ترى خطوط المسارات بشكل أفضل في الليل وعندما يكون الطريق مبلّلًا.","p":"صحيح. إنها تساعدك على رؤية المسارات."},"ht":{"q":"Gen ti makè ki leve (reflektè wout) ki mete sou longè liy ki separe liy wout yo. Poukisa?","o":["Pou ede w wè liy yo lannwit ak lè lapli ap tonbe","Pou fè machin yo ralanti","Pou make plas pakin","Pou montre kote pou depase"],"h1":"Yo klere lè limyè devan machin ou frape yo.","h2":"Makè ki leve sou wout la reflete limyè devan machin ou, pou ou ka wè liy yo pi byen lannwit ak lè wout la mouye.","p":"Se sa. Yo ede w wè liy yo."}},{"id":"signals-077","scope":"US","cat":"signals","sign":null,"c":1,"en":{"q":"On a two-lane road, which side of the yellow center line should you drive on?","o":["To the left of it","To the right of it","Right on top of it","Either side"],"h1":"In the U.S., traffic keeps to the right.","h2":"On a two-way road you drive to the right of the yellow center line; traffic going the other way is on the left side of it.","p":"Right. Keep to the right of the center line."},"es":{"q":"En una vía de dos carriles, ¿de qué lado de la línea central amarilla debe manejar?","o":["A la izquierda de ella","A la derecha de ella","Justo encima","De cualquier lado"],"h1":"En EE. UU. el tráfico va por la derecha.","h2":"En una vía de doble sentido usted maneja a la derecha de la línea central amarilla; el tráfico del otro sentido va a la izquierda de ella.","p":"Correcto. Manténgase a la derecha de la línea central."},"zh":{"q":"在双车道的路上，你应该在黄色中心线的哪一边开车？","o":["在它的左边","在它的右边","正好压在线上","哪一边都可以"],"h1":"在美国，车辆靠右行驶。","h2":"在双向行驶的路上，你要在黄色中心线的右边开车；对面方向来的车在线的左边。","p":"对。要在中心线的右边开。"},"vi":{"q":"Trên đường hai làn, bạn nên lái xe ở bên nào của vạch giữa màu vàng?","o":["Bên trái vạch","Bên phải vạch","Ngay trên vạch","Bên nào cũng được"],"h1":"Ở Hoa Kỳ, xe chạy bên phải.","h2":"Trên đường hai chiều, bạn lái xe ở bên phải vạch giữa màu vàng; xe đi chiều ngược lại ở bên trái vạch.","p":"Đúng. Hãy đi bên phải vạch giữa."},"tl":{"q":"Sa kalsadang may dalawang lane, sa aling panig ng dilaw na guhit sa gitna ka dapat magmaneho?","o":["Sa kaliwa nito","Sa kanan nito","Mismo sa ibabaw nito","Kahit saang panig"],"h1":"Sa U.S., nasa kanan ang daloy ng trapiko.","h2":"Sa kalsadang dalawa ang direksyon, magmaneho ka sa kanan ng dilaw na guhit sa gitna; nasa kaliwa nito ang trapikong papunta sa kabilang direksyon.","p":"Tama. Manatili sa kanan ng guhit sa gitna."},"ar":{"q":"على طريق بمسارين، على أي جانب من الخط الأصفر في الوسط يجب أن تقود؟","o":["على يساره","على يمينه","فوقه مباشرة","على أي جانب"],"h1":"في الولايات المتحدة، تسير السيارات على اليمين.","h2":"على طريق باتجاهين تقود على يمين الخط الأصفر في الوسط؛ والسيارات التي تسير في الاتجاه المعاكس تكون على يساره.","p":"صحيح. ابقَ على يمين الخط الأوسط."},"ht":{"q":"Sou yon wout ki gen de liy, ki bò liy jòn nan mitan an ou dwe kondi?","o":["Sou bò goch li","Sou bò dwat li","Dwat sou li","Nenpòt bò"],"h1":"Ozetazini, machin yo kenbe bò dwat.","h2":"Sou yon wout de sans, ou kondi sou bò dwat liy jòn nan mitan an; machin k ap vini nan lòt sans lan sou bò goch li.","p":"Se sa. Rete sou bò dwat liy nan mitan an."}},{"id":"signs-001","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":0,"en":{"q":"A red sign has eight sides. What must you do?","o":["Stop fully, then go when it is safe","Slow down, and stop only if cars come","Get ready for road work ahead","Watch for a school zone ahead"],"h1":"Think about the only sign with eight sides.","h2":"An eight-sided red sign is a stop sign, so you must come to a full stop and go only when the way is clear.","p":"Right. Eight sides means stop fully, then go when safe."},"es":{"q":"Una señal roja tiene ocho lados. ¿Qué debe hacer?","o":["Pararse por completo y seguir cuando sea seguro","Bajar la velocidad y pararse solo si vienen carros","Prepararse para obras en la vía","Estar atento a una zona escolar"],"h1":"Piense en la única señal que tiene ocho lados.","h2":"Una señal roja de ocho lados es la señal de pare, así que usted debe pararse por completo y seguir solo cuando el camino esté libre.","p":"Correcto. Ocho lados significa pararse por completo y seguir cuando sea seguro."},"zh":{"q":"一个红色标志有八条边。你必须怎么做？","o":["完全停车，安全时再走","减速，只有来车时才停","准备好，前方有道路施工","注意，前方有学校区"],"h1":"想一想：只有一种标志有八条边。","h2":"八边形的红色标志是停车标志，所以你必须完全停车，路上没有车和人时才能走。","p":"对。八条边表示完全停车，安全时再走。"},"vi":{"q":"Một biển báo màu đỏ có tám cạnh. Bạn phải làm gì?","o":["Dừng hẳn, rồi đi khi an toàn","Chạy chậm lại, và chỉ dừng nếu có xe tới","Chuẩn bị cho đoạn đường đang sửa phía trước","Chú ý khu vực trường học phía trước"],"h1":"Hãy nghĩ đến biển báo duy nhất có tám cạnh.","h2":"Biển báo đỏ có tám cạnh là biển “STOP” (Dừng lại), nên bạn phải dừng hẳn và chỉ đi khi đường đã trống.","p":"Đúng rồi. Tám cạnh nghĩa là dừng hẳn, rồi đi khi an toàn."},"tl":{"q":"May pulang karatula na may walong gilid. Ano ang dapat mong gawin?","o":["Huminto nang buo, saka umandar kapag ligtas na","Bumagal, at huminto lang kung may dumarating na sasakyan","Maghanda sa ginagawang kalsada sa unahan","Mag-ingat sa school zone sa unahan"],"h1":"Isipin ang nag-iisang karatula na may walong gilid.","h2":"Ang pulang karatula na may walong gilid ay “STOP” sign (Huminto), kaya dapat kang huminto nang buo at umandar lang kapag maluwag na ang daan.","p":"Tama. Ang walong gilid ay nangangahulugang huminto nang buo, saka umandar kapag ligtas."},"ar":{"q":"لافتة حمراء لها ثمانية أضلاع. ماذا يجب أن تفعل؟","o":["توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا","خفف السرعة، وتوقف فقط إذا جاءت سيارات","استعد لأعمال طرق في الأمام","انتبه لمنطقة مدرسة في الأمام"],"h1":"فكّر في اللافتة الوحيدة التي لها ثمانية أضلاع.","h2":"اللافتة الحمراء ذات الأضلاع الثمانية هي لافتة «STOP» (قف)، لذلك يجب أن تتوقف تمامًا ولا تنطلق إلا عندما يكون الطريق خاليًا.","p":"صحيح. ثمانية أضلاع تعني: توقف تمامًا، ثم انطلق عندما يكون الطريق آمنًا."},"ht":{"q":"Gen yon siy wouj ki gen uit kote. Kisa ou dwe fè?","o":["Kanpe nèt, epi pati lè sa an sekirite","Ralanti, epi kanpe sèlman si gen machin k ap vini","Prepare ou pou travay sou wout la pi devan","Veye yon zòn lekòl pi devan"],"h1":"Panse ak sèl siy ki gen uit kote a.","h2":"Yon siy wouj ki gen uit kote se yon siy “STOP” (kanpe), kidonk ou dwe kanpe nèt epi pati sèlman lè wout la lib.","p":"Se sa. Uit kote vle di kanpe nèt, epi pati lè sa an sekirite."},"ref":{"doc":"FL","page":47}},{"id":"signs-002","scope":"US","cat":"signs","sign":{"shape":"yield","text":"YIELD"},"c":1,"en":{"q":"What does a red and white triangle pointing down mean?","o":["Stop every time, even if the road is clear","Slow down, let others go first, stop if needed","Speed up so you can merge quickly","The road ends just ahead"],"h1":"This sign is about who goes first.","h2":"The upside-down triangle is a yield sign, so you slow down, let other traffic go first, and stop if you need to.","p":"Right. Yield means slow down and let others go first."},"es":{"q":"¿Qué significa un triángulo rojo y blanco con la punta hacia abajo?","o":["Pararse siempre, aunque la vía esté libre","Bajar la velocidad, dejar pasar a otros y parar si hace falta","Acelerar para entrar rápido al tráfico","La vía se termina más adelante"],"h1":"Esta señal trata de quién pasa primero.","h2":"El triángulo con la punta hacia abajo es la señal de ceda el paso, así que usted baja la velocidad, deja pasar a los demás y se para si hace falta.","p":"Correcto. Ceda el paso significa bajar la velocidad y dejar pasar a otros."},"zh":{"q":"一个尖角朝下的红白三角形标志是什么意思？","o":["每次都要停车，路上没车也要停","减速，让别人先走，需要时停车","加速，以便快速并道","道路就在前方结束"],"h1":"这个标志说的是谁先走。","h2":"倒三角形是让行标志，所以你要减速，让其他车先走，需要时停车。","p":"对。让行表示减速，让别人先走。"},"vi":{"q":"Biển hình tam giác đỏ trắng, mũi nhọn chỉ xuống, có nghĩa là gì?","o":["Lúc nào cũng phải dừng, dù đường trống","Chạy chậm lại, nhường người khác đi trước, dừng nếu cần","Tăng tốc để nhập làn cho nhanh","Con đường sắp hết ngay phía trước"],"h1":"Biển này nói về việc ai được đi trước.","h2":"Tam giác chỉ xuống là biển “YIELD” (Nhường đường), nên bạn chạy chậm lại, để xe khác đi trước, và dừng nếu cần.","p":"Đúng rồi. Nhường đường nghĩa là chạy chậm lại và để người khác đi trước."},"tl":{"q":"Ano ang ibig sabihin ng pula at puting tatsulok na nakaturo pababa?","o":["Huminto palagi, kahit maluwag ang daan","Bumagal, paunahin ang iba, huminto kung kailangan","Bumilis para mabilis kang makasingit","Matatapos na ang kalsada sa unahan"],"h1":"Ang karatulang ito ay tungkol sa kung sino ang mauuna.","h2":"Ang baligtad na tatsulok ay “YIELD” sign (Magbigay-daan), kaya babagal ka, paunahin mo ang ibang sasakyan, at huminto ka kung kailangan.","p":"Tama. Ang “YIELD” ay nangangahulugang bumagal at paunahin ang iba."},"ar":{"q":"ماذا يعني مثلث أحمر وأبيض رأسه إلى الأسفل؟","o":["توقف في كل مرة، حتى لو كان الطريق خاليًا","خفف السرعة، ودع الآخرين يمرون أولًا، وتوقف إذا لزم الأمر","زد السرعة لكي تندمج بسرعة","الطريق ينتهي بعد قليل"],"h1":"هذه اللافتة تتعلق بمن يمر أولًا.","h2":"المثلث المقلوب هو لافتة «YIELD» (أعطِ الأولوية)، لذلك تخفف السرعة، وتترك السيارات الأخرى تمر أولًا، وتتوقف إذا احتجت إلى ذلك.","p":"صحيح. «YIELD» تعني: خفف السرعة ودع الآخرين يمرون أولًا."},"ht":{"q":"Kisa yon triyang wouj ak blan ki gen pwent li anba vle di?","o":["Kanpe chak fwa, menm si wout la lib","Ralanti, kite lòt yo pase anvan, kanpe si sa nesesè","Akselere pou ou ka antre vit","Wout la fini touprè"],"h1":"Siy sa a pale de kiyès ki pase anvan.","h2":"Triyang ki tèt anba a se yon siy “YIELD” (bay pasaj), kidonk ou ralanti, ou kite lòt machin yo pase anvan, epi ou kanpe si ou bezwen.","p":"Se sa. “YIELD” vle di ralanti epi kite lòt yo pase anvan."},"ref":{"doc":"FL","page":47}},{"id":"signs-003","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":2,"en":{"q":"What does a sign with five sides warn you about?","o":["A railroad crossing ahead","A hospital nearby","A school zone or school crossing","A no-passing zone"],"h1":"Think about who you may see walking near this sign.","h2":"A five-sided sign marks a school zone or a school crossing, so you should slow down and watch for children.","p":"Right. Five sides means a school is near."},"es":{"q":"¿Sobre qué le avisa una señal de cinco lados?","o":["Un cruce de tren más adelante","Un hospital cerca","Una zona escolar o un cruce escolar","Una zona donde no se puede rebasar"],"h1":"Piense en quiénes podrían caminar cerca de esta señal.","h2":"Una señal de cinco lados marca una zona escolar o un cruce escolar, así que usted debe bajar la velocidad y estar atento a los niños.","p":"Correcto. Cinco lados significa que hay una escuela cerca."},"zh":{"q":"有五条边的标志提醒你注意什么？","o":["前方有铁路道口","附近有医院","学校区或学校人行横道","禁止超车区"],"h1":"想一想：你在这个标志附近可能看到谁在走路。","h2":"五边形标志表示学校区或学校人行横道，所以你要减速，注意儿童。","p":"对。五条边表示附近有学校。"},"vi":{"q":"Biển báo có năm cạnh cảnh báo bạn về điều gì?","o":["Có chỗ băng qua đường sắt phía trước","Có bệnh viện gần đây","Khu vực trường học hoặc chỗ học sinh qua đường","Khu vực cấm vượt"],"h1":"Hãy nghĩ xem ai có thể đang đi bộ gần biển này.","h2":"Biển có năm cạnh báo hiệu khu vực trường học hoặc chỗ học sinh qua đường, nên bạn cần chạy chậm lại và chú ý trẻ em.","p":"Đúng rồi. Năm cạnh nghĩa là gần trường học."},"tl":{"q":"Tungkol saan ang babala ng karatula na may limang gilid?","o":["Tawiran ng tren sa unahan","May ospital sa malapit","School zone o tawiran ng mga estudyante","Lugar na bawal mag-overtake"],"h1":"Isipin kung sino ang maaaring makita mong naglalakad malapit sa karatulang ito.","h2":"Ang karatula na may limang gilid ay nagmamarka ng school zone o tawiran ng mga estudyante, kaya dapat kang bumagal at mag-ingat sa mga bata.","p":"Tama. Ang limang gilid ay nangangahulugang may paaralan sa malapit."},"ar":{"q":"ممّ تحذّرك لافتة لها خمسة أضلاع؟","o":["من تقاطع مع سكة حديد في الأمام","من مستشفى قريب","من منطقة مدرسة أو معبر مدرسة","من منطقة ممنوع فيها التجاوز"],"h1":"فكّر في من قد تراه يمشي قرب هذه اللافتة.","h2":"اللافتة ذات الأضلاع الخمسة تدل على منطقة مدرسة أو معبر مدرسة، لذلك يجب أن تخفف السرعة وتنتبه للأطفال.","p":"صحيح. خمسة أضلاع تعني أن هناك مدرسة قريبة."},"ht":{"q":"Yon siy ki gen senk kote avèti ou pou kisa?","o":["Yon kote tren travèse pi devan","Yon lopital touprè","Yon zòn lekòl oswa yon kote timoun lekòl travèse","Yon zòn kote ou pa ka double"],"h1":"Panse ak kiyès ou ka wè k ap mache toupre siy sa a.","h2":"Yon siy ki gen senk kote make yon zòn lekòl oswa yon kote timoun lekòl travèse, kidonk ou dwe ralanti epi veye timoun yo.","p":"Se sa. Senk kote vle di gen yon lekòl toupre."},"ref":{"doc":"FL","page":57}},{"id":"signs-004","scope":"US","cat":"signs","sign":{"shape":"rr-advance","text":"RR"},"c":3,"en":{"q":"What does a round yellow sign with an X and two R letters mean?","o":["A traffic circle is ahead","A bus stop is ahead","A rest area is ahead","A railroad crossing is ahead"],"h1":"The two letters stand for a kind of track.","h2":"The round yellow sign warns that a railroad crossing is ahead, so you should slow down, look, listen, and be ready to stop.","p":"Right. The round yellow sign warns of a railroad crossing ahead."},"es":{"q":"¿Qué significa una señal amarilla y redonda con una X y dos letras R?","o":["Hay una rotonda más adelante","Hay una parada de autobús más adelante","Hay un área de descanso más adelante","Hay un cruce de tren más adelante"],"h1":"Las dos letras se refieren a un tipo de vía.","h2":"La señal amarilla y redonda avisa que hay un cruce de tren más adelante, así que usted debe bajar la velocidad, mirar, escuchar y estar listo para parar.","p":"Correcto. La señal amarilla y redonda avisa de un cruce de tren."},"zh":{"q":"一个黄色圆形标志，上面有一个 X 和两个字母 R，是什么意思？","o":["前方有环形交叉路口","前方有公交车站","前方有休息区","前方有铁路道口"],"h1":"这两个字母代表一种轨道。","h2":"黄色圆形标志提醒你前方有铁路道口，所以你要减速，看一看，听一听，准备停车。","p":"对。黄色圆形标志提醒你前方有铁路道口。"},"vi":{"q":"Biển tròn màu vàng có chữ X và hai chữ R có nghĩa là gì?","o":["Phía trước có vòng xuyến","Phía trước có trạm xe buýt","Phía trước có trạm dừng nghỉ","Phía trước có chỗ băng qua đường sắt"],"h1":"Hai chữ cái này nói về một loại đường ray.","h2":"Biển tròn màu vàng cảnh báo phía trước có chỗ băng qua đường sắt, nên bạn cần chạy chậm lại, nhìn, nghe, và sẵn sàng dừng.","p":"Đúng rồi. Biển tròn màu vàng cảnh báo phía trước có đường sắt."},"tl":{"q":"Ano ang ibig sabihin ng bilog na dilaw na karatula na may X at dalawang letrang R?","o":["May rotonda sa unahan","May hintuan ng bus sa unahan","May pahingahan sa unahan","May tawiran ng tren sa unahan"],"h1":"Ang dalawang letra ay tumutukoy sa isang uri ng riles.","h2":"Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan, kaya dapat kang bumagal, tumingin, makinig, at maging handang huminto.","p":"Tama. Ang bilog na dilaw na karatula ay babala na may tawiran ng tren sa unahan."},"ar":{"q":"ماذا تعني لافتة صفراء مستديرة عليها حرف X وحرفا R؟","o":["دوّار مروري في الأمام","موقف حافلات في الأمام","استراحة في الأمام","تقاطع مع سكة حديد في الأمام"],"h1":"الحرفان يرمزان إلى نوع من القضبان.","h2":"اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام، لذلك يجب أن تخفف السرعة، وتنظر، وتستمع، وتستعد للتوقف.","p":"صحيح. اللافتة الصفراء المستديرة تحذّر من تقاطع مع سكة حديد في الأمام."},"ht":{"q":"Kisa yon siy jòn won ki gen yon X ak de lèt R vle di?","o":["Gen yon wonpwen pi devan","Gen yon arè bis pi devan","Gen yon zòn repo pi devan","Gen yon kote tren travèse pi devan"],"h1":"De lèt yo kanpe pou yon kalite ray.","h2":"Siy jòn won an avèti ou gen yon kote tren travèse pi devan, kidonk ou dwe ralanti, gade, koute, epi pare pou kanpe.","p":"Se sa. Siy jòn won an avèti ou gen yon kote tren travèse pi devan."},"ref":{"doc":"FL","page":56}},{"id":"signs-005","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":0,"en":{"q":"At the tracks you see a white X-shaped sign. What should you do?","o":["Treat it like a yield sign and look for trains","Speed up to get across the tracks fast","Change lanes before you reach the tracks","Ignore it unless it is dark outside"],"h1":"Think about what could be coming down the tracks.","h2":"The white X sign is a railroad crossbuck, and it works like a yield sign, so you slow down, look both ways, and stop if a train is coming.","p":"Right. The crossbuck means yield to trains."},"es":{"q":"En la vía del tren ve una señal blanca en forma de X. ¿Qué debe hacer?","o":["Tratarla como un ceda el paso y buscar trenes","Acelerar para cruzar la vía rápido","Cambiar de carril antes de la vía","No hacerle caso a menos que sea de noche"],"h1":"Piense en lo que podría venir por la vía.","h2":"La señal blanca en forma de X es la cruz de ferrocarril, y funciona como un ceda el paso, así que usted baja la velocidad, mira a ambos lados y se para si viene un tren.","p":"Correcto. La cruz de ferrocarril significa ceder el paso a los trenes."},"zh":{"q":"在铁轨旁，你看到一个白色 X 形标志。你应该怎么做？","o":["把它当作让行标志，注意火车","加速，快快穿过铁轨","到铁轨前先换车道","不用管它，除非天黑"],"h1":"想一想：铁轨上可能开来什么。","h2":"白色 X 形标志是铁路交叉标志，它的作用和让行标志一样，所以你要减速，看两边，如果有火车开来就停车。","p":"对。铁路交叉标志表示给火车让行。"},"vi":{"q":"Tại đường ray, bạn thấy một biển màu trắng hình chữ X. Bạn nên làm gì?","o":["Làm như gặp biển nhường đường và nhìn xem có tàu không","Tăng tốc để qua đường ray thật nhanh","Đổi làn trước khi tới đường ray","Bỏ qua biển, trừ khi trời tối"],"h1":"Hãy nghĩ xem cái gì có thể đang chạy tới trên đường ray.","h2":"Biển chữ X màu trắng là biển báo đường sắt (crossbuck), và nó giống như biển nhường đường, nên bạn chạy chậm lại, nhìn cả hai phía, và dừng nếu có tàu đang tới.","p":"Đúng rồi. Biển chữ X nghĩa là phải nhường đường cho tàu."},"tl":{"q":"Sa may riles, may nakita kang puting karatula na hugis X. Ano ang dapat mong gawin?","o":["Ituring itong parang “YIELD” sign at tumingin kung may tren","Bumilis para mabilis na makatawid sa riles","Lumipat ng linya bago ka umabot sa riles","Huwag pansinin maliban kung madilim na"],"h1":"Isipin kung ano ang puwedeng dumaan sa riles.","h2":"Ang puting karatulang X ay tinatawag na crossbuck ng riles, at gumagana ito na parang “YIELD” sign, kaya babagal ka, titingin sa magkabilang direksyon, at hihinto kung may paparating na tren.","p":"Tama. Ang crossbuck ay nangangahulugang magbigay-daan sa tren."},"ar":{"q":"عند سكة الحديد ترى لافتة بيضاء على شكل حرف X. ماذا يجب أن تفعل؟","o":["تعامل معها مثل لافتة إعطاء الأولوية وانظر هل يأتي قطار","زد السرعة لتعبر السكة بسرعة","غيّر المسار قبل أن تصل إلى السكة","تجاهلها إلا إذا كان الجو مظلمًا"],"h1":"فكّر في ما قد يأتي على السكة.","h2":"اللافتة البيضاء على شكل X هي علامة تقاطع سكة الحديد، وهي تعمل مثل لافتة إعطاء الأولوية، لذلك تخفف السرعة، وتنظر في الاتجاهين، وتتوقف إذا كان قطار قادمًا.","p":"صحيح. علامة X عند السكة تعني: أعطِ الأولوية للقطارات."},"ht":{"q":"Bò ray tren an, ou wè yon siy blan ki gen fòm yon X. Kisa ou dwe fè?","o":["Fè l tankou yon siy “YIELD” epi gade si gen tren","Akselere pou travèse ray yo vit","Chanje koulwa anvan ou rive nan ray yo","Pa okipe l sof si fè nwa deyò"],"h1":"Panse ak sa ki ka ap vini sou ray yo.","h2":"Siy blan an fòm X la se yon kwa tren (crossbuck), e li mache tankou yon siy “YIELD”, kidonk ou ralanti, ou gade de bò yo, epi ou kanpe si gen yon tren k ap vini.","p":"Se sa. Kwa tren an vle di bay tren yo pasaj."},"ref":{"doc":"FL","page":56}},{"id":"signs-006","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow"},"c":1,"en":{"q":"What does a yellow diamond-shaped sign usually do?","o":["Gives you directions to a city","Warns you about a hazard or change ahead","Tells you the speed limit","Shows you a place to eat"],"h1":"Think about why a sign would use a bright yellow color.","h2":"A yellow diamond is a warning sign, so it tells you about a hazard or a change in the road ahead.","p":"Right. A yellow diamond warns you about something ahead."},"es":{"q":"¿Qué hace normalmente una señal amarilla en forma de rombo?","o":["Le da direcciones hacia una ciudad","Le avisa de un peligro o un cambio más adelante","Le dice el límite de velocidad","Le muestra un lugar para comer"],"h1":"Piense en por qué una señal usaría un amarillo fuerte.","h2":"Un rombo amarillo es una señal de advertencia, así que le avisa de un peligro o de un cambio en la vía más adelante.","p":"Correcto. Un rombo amarillo le avisa de algo más adelante."},"zh":{"q":"黄色菱形标志通常有什么作用？","o":["告诉你去某个城市的方向","提醒你前方有危险或变化","告诉你限速","告诉你哪里可以吃饭"],"h1":"想一想：标志为什么要用很亮的黄色。","h2":"黄色菱形标志是警告标志，它告诉你前方道路有危险或变化。","p":"对。黄色菱形标志提醒你注意前方。"},"vi":{"q":"Biển hình thoi màu vàng thường dùng để làm gì?","o":["Chỉ đường tới một thành phố","Cảnh báo nguy hiểm hoặc thay đổi phía trước","Cho biết tốc độ tối đa","Chỉ chỗ ăn uống"],"h1":"Hãy nghĩ xem vì sao một biển báo lại dùng màu vàng tươi.","h2":"Biển hình thoi màu vàng là biển cảnh báo, nên nó cho bạn biết có nguy hiểm hoặc đường thay đổi ở phía trước.","p":"Đúng rồi. Biển hình thoi màu vàng cảnh báo điều gì đó phía trước."},"tl":{"q":"Ano ang karaniwang ginagawa ng dilaw na karatula na hugis diyamante?","o":["Nagbibigay ng direksyon papunta sa isang lungsod","Nagbababala tungkol sa panganib o pagbabago sa unahan","Nagsasabi ng speed limit","Nagpapakita ng lugar na makakainan"],"h1":"Isipin kung bakit gagamit ang karatula ng matingkad na dilaw na kulay.","h2":"Ang dilaw na diyamante ay karatula ng babala, kaya sinasabi nito sa iyo na may panganib o pagbabago sa kalsada sa unahan.","p":"Tama. Ang dilaw na diyamante ay nagbababala tungkol sa isang bagay sa unahan."},"ar":{"q":"ما الذي تفعله عادةً لافتة صفراء على شكل معيّن (ماسة)؟","o":["تعطيك الاتجاه إلى مدينة","تحذّرك من خطر أو تغيير في الأمام","تخبرك بالحد الأقصى للسرعة","تدلّك على مكان للأكل"],"h1":"فكّر لماذا تستخدم اللافتة لونًا أصفر لامعًا.","h2":"المعيّن الأصفر هو لافتة تحذير، فهو يخبرك بوجود خطر أو تغيير في الطريق أمامك.","p":"صحيح. المعيّن الأصفر يحذّرك من شيء في الأمام."},"ht":{"q":"Kisa yon siy jòn ki gen fòm dyaman (lozanj) konn fè?","o":["Li ba ou direksyon pou yon vil","Li avèti ou gen yon danje oswa yon chanjman pi devan","Li di ou limit vitès la","Li montre ou yon kote pou manje"],"h1":"Panse poukisa yon siy ta sèvi ak yon koulè jòn klè.","h2":"Yon dyaman jòn se yon siy avètisman, kidonk li di ou gen yon danje oswa yon chanjman sou wout la pi devan.","p":"Se sa. Yon dyaman jòn avèti ou pou yon bagay pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-007","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"Orange signs tell you about what?","o":["School zones","Parks and campgrounds","Road work and work zones","Gas and food"],"h1":"Think about where you see orange cones and workers.","h2":"Orange signs are used for road work and work zones, so you should slow down and watch for workers and changes.","p":"Right. Orange signs mean road work."},"es":{"q":"¿De qué le avisan las señales anaranjadas?","o":["De zonas escolares","De parques y campamentos","De obras y zonas de trabajo en la vía","De gasolina y comida"],"h1":"Piense en dónde ve conos anaranjados y trabajadores.","h2":"Las señales anaranjadas se usan para obras y zonas de trabajo en la vía, así que usted debe bajar la velocidad y estar atento a los trabajadores y a los cambios.","p":"Correcto. Las señales anaranjadas significan obras en la vía."},"zh":{"q":"橙色标志告诉你什么？","o":["学校区","公园和露营地","道路施工和施工区","加油和吃饭"],"h1":"想一想：你在哪里会看到橙色锥桶和工人。","h2":"橙色标志用于道路施工和施工区，所以你要减速，注意工人和道路变化。","p":"对。橙色标志表示道路施工。"},"vi":{"q":"Biển báo màu cam cho bạn biết về điều gì?","o":["Khu vực trường học","Công viên và khu cắm trại","Đường đang sửa và khu vực thi công","Xăng và đồ ăn"],"h1":"Hãy nghĩ xem bạn thấy cọc màu cam và công nhân ở đâu.","h2":"Biển màu cam dùng cho đường đang sửa và khu vực thi công, nên bạn cần chạy chậm lại và chú ý công nhân cùng những thay đổi trên đường.","p":"Đúng rồi. Biển màu cam nghĩa là đường đang sửa."},"tl":{"q":"Tungkol saan ang sinasabi ng mga karatulang kulay orange?","o":["Mga school zone","Mga parke at campground","Ginagawang kalsada at work zone","Gasolina at pagkain"],"h1":"Isipin kung saan mo nakikita ang mga orange na cone at mga trabahador.","h2":"Ang mga karatulang kulay orange ay ginagamit para sa ginagawang kalsada at work zone, kaya dapat kang bumagal at mag-ingat sa mga trabahador at mga pagbabago.","p":"Tama. Ang orange na karatula ay nangangahulugang may ginagawang kalsada."},"ar":{"q":"عن أي شيء تخبرك اللافتات البرتقالية؟","o":["مناطق المدارس","الحدائق وأماكن التخييم","أعمال الطرق ومناطق العمل","الوقود والطعام"],"h1":"فكّر في المكان الذي ترى فيه الأقماع البرتقالية والعمال.","h2":"اللافتات البرتقالية تُستخدم لأعمال الطرق ومناطق العمل، لذلك يجب أن تخفف السرعة وتنتبه للعمال وللتغييرات.","p":"صحيح. اللافتات البرتقالية تعني أعمال طرق."},"ht":{"q":"Siy zoranj yo pale ou de kisa?","o":["Zòn lekòl","Pak ak kan","Travay sou wout ak zòn travay","Gaz ak manje"],"h1":"Panse kote ou wè kòn zoranj ak travayè.","h2":"Siy zoranj yo sèvi pou travay sou wout ak zòn travay, kidonk ou dwe ralanti epi veye travayè yo ak chanjman yo.","p":"Se sa. Siy zoranj yo vle di gen travay sou wout la."},"ref":{"doc":"FL","page":46}},{"id":"signs-008","scope":"US","cat":"signs","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":3,"en":{"q":"What does a yellow sign shaped like a long, sideways triangle mean?","o":["A merge is ahead on the right","Trucks have the right of way","The road gets narrow ahead","A no-passing zone begins here"],"h1":"This is the only sign with this flag-like shape.","h2":"The sideways yellow triangle, called a pennant, means a no-passing zone begins, so you must not pass other cars here.","p":"Right. The pennant means no passing."},"es":{"q":"¿Qué significa una señal amarilla en forma de triángulo largo y acostado?","o":["Hay una incorporación más adelante a la derecha","Los camiones tienen el derecho de paso","La vía se hace angosta más adelante","Aquí empieza una zona donde no se puede rebasar"],"h1":"Es la única señal con esta forma de banderín.","h2":"El triángulo amarillo acostado, llamado banderín, significa que empieza una zona donde no se puede rebasar, así que usted no debe rebasar a otros carros aquí.","p":"Correcto. El banderín significa que no se puede rebasar."},"zh":{"q":"一个横着放的长三角形黄色标志是什么意思？","o":["右前方有车辆并入","卡车有优先通行权","前方道路变窄","这里开始是禁止超车区"],"h1":"只有这一种标志是这种小旗子的形状。","h2":"横着的黄色三角形叫三角旗标志，表示禁止超车区开始，所以你在这里不能超车。","p":"对。三角旗标志表示禁止超车。"},"vi":{"q":"Biển màu vàng hình tam giác dài, nằm ngang có nghĩa là gì?","o":["Phía trước có làn nhập vào bên phải","Xe tải được quyền đi trước","Đường hẹp lại phía trước","Khu vực cấm vượt bắt đầu từ đây"],"h1":"Đây là biển duy nhất có hình giống lá cờ này.","h2":"Biển tam giác vàng nằm ngang, gọi là biển cờ đuôi nheo, nghĩa là khu vực cấm vượt bắt đầu, nên bạn không được vượt xe khác ở đây.","p":"Đúng rồi. Biển cờ đuôi nheo nghĩa là cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatula na hugis mahabang tatsulok na nakatagilid?","o":["May sasama sa daan mula sa kanan sa unahan","Ang mga trak ang may karapatang mauna","Kikitid ang kalsada sa unahan","Dito nagsisimula ang lugar na bawal mag-overtake"],"h1":"Ito lang ang karatula na may ganitong hugis na parang bandila.","h2":"Ang nakatagilid na dilaw na tatsulok, na tinatawag na pennant, ay nangangahulugang nagsisimula ang lugar na bawal mag-overtake, kaya hindi ka dapat lumampas sa ibang sasakyan dito.","p":"Tama. Ang pennant ay nangangahulugang bawal mag-overtake."},"ar":{"q":"ماذا تعني لافتة صفراء على شكل مثلث طويل مائل إلى الجانب؟","o":["اندماج طريق في الأمام من اليمين","الشاحنات لها حق المرور","الطريق يضيق في الأمام","هنا تبدأ منطقة ممنوع فيها التجاوز"],"h1":"هذه هي اللافتة الوحيدة التي لها هذا الشكل الذي يشبه العلم.","h2":"المثلث الأصفر المائل إلى الجانب يسمى «الراية»، وهو يعني أن منطقة ممنوع فيها التجاوز تبدأ هنا، لذلك يجب ألا تتجاوز السيارات الأخرى هنا.","p":"صحيح. الراية تعني ممنوع التجاوز."},"ht":{"q":"Kisa yon siy jòn ki gen fòm yon triyang long ki kouche vle di?","o":["Gen machin k ap antre sou bò dwat pi devan","Kamyon yo gen dwa pou pase anvan","Wout la vin pi etwat pi devan","Yon zòn kote ou pa ka double kòmanse la a"],"h1":"Se sèl siy ki gen fòm sa a, tankou yon ti drapo.","h2":"Triyang jòn ki kouche a, yo rele l fanyon, vle di yon zòn kote ou pa ka double kòmanse, kidonk ou pa dwe double lòt machin la a.","p":"Se sa. Fanyon an vle di ou pa ka double."},"ref":{"doc":"FL","page":48}},{"id":"signs-009","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"On which side of the road is the no-passing pennant sign placed?","o":["The left side","The right side","Over the middle lane","Painted on the road"],"h1":"Think about where your eyes look when you plan to pass.","h2":"The no-passing pennant is placed on the left side of the road, because that is the side you look at when you think about passing.","p":"Right. The pennant is on the left side of the road."},"es":{"q":"¿En qué lado de la vía se pone la señal de banderín de no rebasar?","o":["En el lado izquierdo","En el lado derecho","Encima del carril del medio","Pintada en el pavimento"],"h1":"Piense hacia dónde mira cuando planea rebasar.","h2":"El banderín de no rebasar se pone en el lado izquierdo de la vía, porque ese es el lado que usted mira cuando piensa rebasar.","p":"Correcto. El banderín está en el lado izquierdo de la vía."},"zh":{"q":"禁止超车的三角旗标志放在道路的哪一边？","o":["左边","右边","中间车道的上方","画在路面上"],"h1":"想一想：你打算超车时，眼睛会看向哪一边。","h2":"禁止超车的三角旗标志放在道路的左边，因为你想超车时会看那一边。","p":"对。三角旗标志在道路的左边。"},"vi":{"q":"Biển cờ đuôi nheo cấm vượt được đặt ở bên nào của đường?","o":["Bên trái","Bên phải","Phía trên làn giữa","Được sơn trên mặt đường"],"h1":"Hãy nghĩ xem mắt bạn nhìn về phía nào khi định vượt xe.","h2":"Biển cờ đuôi nheo cấm vượt được đặt ở bên trái đường, vì đó là phía bạn nhìn khi nghĩ đến việc vượt xe.","p":"Đúng rồi. Biển cờ đuôi nheo nằm ở bên trái đường."},"tl":{"q":"Sa aling bahagi ng kalsada inilalagay ang pennant na karatula ng bawal mag-overtake?","o":["Sa kaliwang bahagi","Sa kanang bahagi","Sa ibabaw ng gitnang linya","Nakapinta sa kalsada"],"h1":"Isipin kung saan tumitingin ang mata mo kapag balak mong mag-overtake.","h2":"Ang pennant ng bawal mag-overtake ay inilalagay sa kaliwang bahagi ng kalsada, dahil iyon ang bahaging tinitingnan mo kapag iniisip mong mag-overtake.","p":"Tama. Ang pennant ay nasa kaliwang bahagi ng kalsada."},"ar":{"q":"على أي جانب من الطريق توضع لافتة الراية التي تمنع التجاوز؟","o":["على الجانب الأيسر","على الجانب الأيمن","فوق المسار الأوسط","مرسومة على الطريق"],"h1":"فكّر إلى أين تنظر عيناك عندما تخطط للتجاوز.","h2":"لافتة الراية التي تمنع التجاوز توضع على الجانب الأيسر من الطريق، لأنه الجانب الذي تنظر إليه عندما تفكر في التجاوز.","p":"صحيح. الراية توضع على الجانب الأيسر من الطريق."},"ht":{"q":"Sou ki bò wout la yo mete siy fanyon ki di ou pa ka double a?","o":["Bò goch","Bò dwat","Anwo koulwa ki nan mitan an","Penti sou wout la"],"h1":"Panse ki kote je ou gade lè ou vle double.","h2":"Siy fanyon an yo mete l sou bò goch wout la, paske se bò sa a ou gade lè ou panse pou double.","p":"Se sa. Fanyon an sou bò goch wout la."}},{"id":"signs-010","scope":"US","cat":"signs","sign":{"shape":"rect-white"},"c":1,"en":{"q":"A white rectangle sign with black letters usually shows what?","o":["A warning about a curve","A traffic law you must obey","Directions to a city","A place to camp"],"h1":"Think about signs like the speed limit sign.","h2":"White rectangle signs with black letters are regulatory signs, so they show a traffic law that you must obey.","p":"Right. White rectangle signs show rules you must follow."},"es":{"q":"¿Qué muestra normalmente una señal blanca y rectangular con letras negras?","o":["Un aviso de una curva","Una ley de tránsito que debe obedecer","Direcciones hacia una ciudad","Un lugar para acampar"],"h1":"Piense en señales como la del límite de velocidad.","h2":"Las señales blancas y rectangulares con letras negras son señales reglamentarias, así que muestran una ley de tránsito que usted debe obedecer.","p":"Correcto. Las señales blancas rectangulares muestran reglas que debe seguir."},"zh":{"q":"白色长方形、黑色字的标志通常表示什么？","o":["提醒你前方有弯道","你必须遵守的交通法规","去某个城市的方向","可以露营的地方"],"h1":"想一想限速标志这样的标志。","h2":"白色长方形、黑色字的标志是禁令和指示标志，它告诉你必须遵守的交通法规。","p":"对。白色长方形标志告诉你必须遵守的规定。"},"vi":{"q":"Biển hình chữ nhật màu trắng, chữ đen thường cho biết điều gì?","o":["Cảnh báo về khúc cua","Một luật giao thông bạn phải tuân theo","Đường đi tới một thành phố","Chỗ để cắm trại"],"h1":"Hãy nghĩ đến những biển như biển giới hạn tốc độ.","h2":"Biển chữ nhật màu trắng, chữ đen là biển quy định, nên nó cho biết một luật giao thông mà bạn phải tuân theo.","p":"Đúng rồi. Biển chữ nhật màu trắng cho biết luật bạn phải theo."},"tl":{"q":"Ano ang karaniwang ipinapakita ng puting parihabang karatula na may itim na letra?","o":["Babala tungkol sa kurba","Batas trapiko na dapat mong sundin","Direksyon papunta sa isang lungsod","Lugar na puwedeng mag-camping"],"h1":"Isipin ang mga karatula tulad ng karatula ng speed limit.","h2":"Ang puting parihabang karatula na may itim na letra ay karatula ng regulasyon, kaya nagpapakita ito ng batas trapiko na dapat mong sundin.","p":"Tama. Ang puting parihabang karatula ay nagpapakita ng mga patakarang dapat sundin."},"ar":{"q":"لافتة بيضاء مستطيلة بحروف سوداء، ماذا تُظهر عادةً؟","o":["تحذيرًا من منعطف","قانون مرور يجب أن تطيعه","الاتجاه إلى مدينة","مكانًا للتخييم"],"h1":"فكّر في لافتات مثل لافتة حد السرعة.","h2":"اللافتات البيضاء المستطيلة بالحروف السوداء هي لافتات تنظيمية، فهي تُظهر قانون مرور يجب أن تطيعه.","p":"صحيح. اللافتات البيضاء المستطيلة تُظهر قواعد يجب أن تتبعها."},"ht":{"q":"Yon siy blan ki gen fòm rektang ak lèt nwa, kisa li konn montre?","o":["Yon avètisman pou yon koub","Yon lwa trafik ou dwe respekte","Direksyon pou yon vil","Yon kote pou kanpe tant"],"h1":"Panse ak siy tankou siy limit vitès la.","h2":"Siy blan an rektang ak lèt nwa yo se siy règleman, kidonk yo montre yon lwa trafik ou dwe respekte.","p":"Se sa. Siy blan an rektang yo montre règ ou dwe swiv."},"ref":{"doc":"FL","page":46}},{"id":"signs-011","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"Orlando 25"},"c":2,"en":{"q":"What do green signs show you?","o":["Where the hospital is","Where road work starts","Directions and distances","Where a school zone is"],"h1":"Think about signs that help you find your way.","h2":"Green signs are guide signs, so they show directions, exits, and how far it is to places.","p":"Right. Green signs show directions and distances."},"es":{"q":"¿Qué le muestran las señales verdes?","o":["Dónde está el hospital","Dónde empiezan las obras","Direcciones y distancias","Dónde hay una zona escolar"],"h1":"Piense en señales que le ayudan a encontrar el camino.","h2":"Las señales verdes son señales de guía, así que muestran direcciones, salidas y qué tan lejos están los lugares.","p":"Correcto. Las señales verdes muestran direcciones y distancias."},"zh":{"q":"绿色标志告诉你什么？","o":["医院在哪里","道路施工从哪里开始","方向和距离","学校区在哪里"],"h1":"想一想：哪些标志帮你找路。","h2":"绿色标志是指路标志，它告诉你方向、出口，以及到各地还有多远。","p":"对。绿色标志告诉你方向和距离。"},"vi":{"q":"Biển màu xanh lá cây cho bạn biết điều gì?","o":["Bệnh viện ở đâu","Đoạn đường sửa bắt đầu ở đâu","Hướng đi và khoảng cách","Khu vực trường học ở đâu"],"h1":"Hãy nghĩ đến những biển giúp bạn tìm đường.","h2":"Biển màu xanh lá cây là biển chỉ dẫn, nên nó cho biết hướng đi, lối ra, và còn bao xa nữa tới các nơi.","p":"Đúng rồi. Biển xanh lá cây cho biết hướng đi và khoảng cách."},"tl":{"q":"Ano ang ipinapakita sa iyo ng mga berdeng karatula?","o":["Kung nasaan ang ospital","Kung saan nagsisimula ang ginagawang kalsada","Mga direksyon at layo","Kung nasaan ang school zone"],"h1":"Isipin ang mga karatulang tumutulong sa iyo na mahanap ang daan.","h2":"Ang mga berdeng karatula ay gabay na karatula, kaya ipinapakita nito ang mga direksyon, mga exit, at kung gaano kalayo ang mga lugar.","p":"Tama. Ang berdeng karatula ay nagpapakita ng direksyon at layo."},"ar":{"q":"ماذا تُظهر لك اللافتات الخضراء؟","o":["مكان المستشفى","مكان بداية أعمال الطرق","الاتجاهات والمسافات","مكان منطقة المدرسة"],"h1":"فكّر في اللافتات التي تساعدك على معرفة طريقك.","h2":"اللافتات الخضراء هي لافتات إرشاد، فهي تُظهر الاتجاهات والمخارج وكم تبعد الأماكن.","p":"صحيح. اللافتات الخضراء تُظهر الاتجاهات والمسافات."},"ht":{"q":"Kisa siy vèt yo montre ou?","o":["Kote lopital la ye","Kote travay sou wout la kòmanse","Direksyon ak distans","Kote yon zòn lekòl ye"],"h1":"Panse ak siy ki ede ou jwenn chemen ou.","h2":"Siy vèt yo se siy gid, kidonk yo montre direksyon, sòti yo, ak konbyen distans ki genyen pou rive kèk kote.","p":"Se sa. Siy vèt yo montre direksyon ak distans."},"ref":{"doc":"FL","page":46}},{"id":"signs-012","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"GAS FOOD LODGING"},"c":3,"en":{"q":"What do blue signs along the road show?","o":["Speed laws","Road work","Parks and lakes","Services like gas, food, and lodging"],"h1":"Think about what you need on a long trip.","h2":"Blue signs show motorist services, so they point you to things like gas, food, lodging, and hospitals.","p":"Right. Blue signs show services like gas and food."},"es":{"q":"¿Qué muestran las señales azules en la carretera?","o":["Leyes de velocidad","Obras en la vía","Parques y lagos","Servicios como gasolina, comida y hospedaje"],"h1":"Piense en lo que necesita en un viaje largo.","h2":"Las señales azules muestran servicios para conductores, así que le indican lugares como gasolineras, comida, hospedaje y hospitales.","p":"Correcto. Las señales azules muestran servicios como gasolina y comida."},"zh":{"q":"路边的蓝色标志告诉你什么？","o":["限速法规","道路施工","公园和湖泊","加油、吃饭、住宿等服务"],"h1":"想一想：长途开车时你需要什么。","h2":"蓝色标志告诉你司机服务的地点，比如加油站、餐馆、住宿和医院。","p":"对。蓝色标志告诉你加油、吃饭等服务。"},"vi":{"q":"Biển màu xanh dương bên đường cho biết điều gì?","o":["Luật về tốc độ","Đường đang sửa","Công viên và hồ","Dịch vụ như xăng, đồ ăn, và chỗ ngủ"],"h1":"Hãy nghĩ xem bạn cần gì trong một chuyến đi xa.","h2":"Biển màu xanh dương cho biết các dịch vụ cho người lái xe, nên nó chỉ bạn tới những nơi như trạm xăng, chỗ ăn, chỗ ngủ, và bệnh viện.","p":"Đúng rồi. Biển xanh dương cho biết dịch vụ như xăng và đồ ăn."},"tl":{"q":"Ano ang ipinapakita ng mga asul na karatula sa tabi ng kalsada?","o":["Mga batas sa bilis","Ginagawang kalsada","Mga parke at lawa","Mga serbisyo tulad ng gasolina, pagkain, at matutuluyan"],"h1":"Isipin kung ano ang kailangan mo sa mahabang biyahe.","h2":"Ang mga asul na karatula ay nagpapakita ng mga serbisyo para sa motorista, kaya itinuturo nito ang mga bagay tulad ng gasolina, pagkain, matutuluyan, at ospital.","p":"Tama. Ang asul na karatula ay nagpapakita ng mga serbisyo tulad ng gasolina at pagkain."},"ar":{"q":"ماذا تُظهر اللافتات الزرقاء على جانب الطريق؟","o":["قوانين السرعة","أعمال الطرق","الحدائق والبحيرات","خدمات مثل الوقود والطعام والمبيت"],"h1":"فكّر في ما تحتاجه في رحلة طويلة.","h2":"اللافتات الزرقاء تُظهر خدمات السائقين، فهي تدلّك على أشياء مثل الوقود والطعام والمبيت والمستشفيات.","p":"صحيح. اللافتات الزرقاء تُظهر خدمات مثل الوقود والطعام."},"ht":{"q":"Kisa siy ble yo sou bò wout la montre?","o":["Lwa sou vitès","Travay sou wout","Pak ak lak","Sèvis tankou gaz, manje, ak kote pou dòmi"],"h1":"Panse ak sa ou bezwen nan yon long vwayaj.","h2":"Siy ble yo montre sèvis pou chofè, kidonk yo montre ou kote ki gen gaz, manje, kote pou dòmi, ak lopital.","p":"Se sa. Siy ble yo montre sèvis tankou gaz ak manje."},"ref":{"doc":"FL","page":46}},{"id":"signs-013","scope":"US","cat":"signs","sign":{"shape":"rect-brown","text":"STATE PARK"},"c":0,"en":{"q":"What do brown signs point you to?","o":["Parks, campgrounds, and places to visit","Gas stations and hotels","Exits and city names","Road work zones"],"h1":"Think about places you go for fun or nature.","h2":"Brown signs point to recreation and cultural places, such as parks, campgrounds, and historic sites.","p":"Right. Brown signs point to parks and places to visit."},"es":{"q":"¿Hacia dónde le indican las señales color café?","o":["Parques, campamentos y lugares para visitar","Gasolineras y hoteles","Salidas y nombres de ciudades","Zonas de obras"],"h1":"Piense en lugares a los que va para divertirse o estar en la naturaleza.","h2":"Las señales color café indican lugares de recreación y cultura, como parques, campamentos y sitios históricos.","p":"Correcto. Las señales color café indican parques y lugares para visitar."},"zh":{"q":"棕色标志指向哪里？","o":["公园、露营地和游览地点","加油站和酒店","出口和城市名","道路施工区"],"h1":"想一想：你为了玩或看大自然会去的地方。","h2":"棕色标志指向休闲和文化地点，比如公园、露营地和历史古迹。","p":"对。棕色标志指向公园和游览地点。"},"vi":{"q":"Biển màu nâu chỉ bạn tới đâu?","o":["Công viên, khu cắm trại, và nơi tham quan","Trạm xăng và khách sạn","Lối ra và tên thành phố","Khu vực đường đang sửa"],"h1":"Hãy nghĩ đến những nơi bạn đi chơi hoặc đi ngắm thiên nhiên.","h2":"Biển màu nâu chỉ tới nơi giải trí và văn hóa, như công viên, khu cắm trại, và di tích lịch sử.","p":"Đúng rồi. Biển màu nâu chỉ tới công viên và nơi tham quan."},"tl":{"q":"Saan ka itinuturo ng mga brown na karatula?","o":["Mga parke, campground, at mga lugar na mapapasyalan","Mga gasolinahan at hotel","Mga exit at pangalan ng lungsod","Mga lugar na may ginagawang kalsada"],"h1":"Isipin ang mga lugar na pinupuntahan mo para maglibang o para sa kalikasan.","h2":"Ang mga brown na karatula ay nagtuturo sa mga lugar ng libangan at kultura, tulad ng mga parke, campground, at makasaysayang lugar.","p":"Tama. Ang brown na karatula ay nagtuturo sa mga parke at mga lugar na mapapasyalan."},"ar":{"q":"إلى ماذا ترشدك اللافتات البنية؟","o":["الحدائق وأماكن التخييم والأماكن التي تستحق الزيارة","محطات الوقود والفنادق","المخارج وأسماء المدن","مناطق أعمال الطرق"],"h1":"فكّر في الأماكن التي تذهب إليها للمتعة أو للطبيعة.","h2":"اللافتات البنية ترشدك إلى أماكن الترفيه والثقافة، مثل الحدائق وأماكن التخييم والمواقع التاريخية.","p":"صحيح. اللافتات البنية ترشدك إلى الحدائق والأماكن التي تستحق الزيارة."},"ht":{"q":"Siy mawon yo montre ou ki kote?","o":["Pak, kan, ak kote pou vizite","Estasyon gaz ak otèl","Sòti ak non vil","Zòn travay sou wout"],"h1":"Panse ak kote ou ale pou pran plezi oswa pou wè lanati.","h2":"Siy mawon yo montre kote pou amizman ak kilti, tankou pak, kan, ak kote istorik.","p":"Se sa. Siy mawon yo montre pak ak kote pou vizite."},"ref":{"doc":"FL","page":46}},{"id":"signs-014","scope":"US","cat":"signs","sign":{"shape":"do-not-enter","text":"DO NOT ENTER"},"c":1,"en":{"q":"What does a red circle with a white bar across it mean?","o":["Stop, then go when clear","Do not enter this road","Hospital ahead","Two-way traffic ahead"],"h1":"Think about a road where all the cars come toward you.","h2":"The red circle with a white bar means do not enter, because traffic on that road comes toward you.","p":"Right. The red circle with a white bar means do not enter."},"es":{"q":"¿Qué significa un círculo rojo con una barra blanca en el medio?","o":["Pararse y seguir cuando esté libre","No entre a esta vía","Hospital más adelante","Tráfico en dos sentidos más adelante"],"h1":"Piense en una vía donde todos los carros vienen hacia usted.","h2":"El círculo rojo con una barra blanca significa no entre, porque el tráfico en esa vía viene hacia usted.","p":"Correcto. El círculo rojo con barra blanca significa no entre."},"zh":{"q":"红色圆形中间有一条白色横杠，是什么意思？","o":["停车，没车时再走","禁止驶入这条路","前方有医院","前方是双向交通"],"h1":"想一想：一条路上所有车都朝你开过来。","h2":"红色圆形中间有白色横杠，意思是禁止驶入，因为这条路上的车是朝你开过来的。","p":"对。红色圆形加白色横杠表示禁止驶入。"},"vi":{"q":"Hình tròn màu đỏ có một vạch trắng ngang qua có nghĩa là gì?","o":["Dừng lại, rồi đi khi đường trống","Không được đi vào con đường này","Phía trước có bệnh viện","Phía trước là đường hai chiều"],"h1":"Hãy nghĩ đến con đường mà mọi xe đều chạy ngược về phía bạn.","h2":"Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào (“DO NOT ENTER”), vì xe trên con đường đó đang chạy ngược về phía bạn.","p":"Đúng rồi. Hình tròn đỏ có vạch trắng nghĩa là cấm đi vào."},"tl":{"q":"Ano ang ibig sabihin ng pulang bilog na may puting guhit sa gitna?","o":["Huminto, saka umandar kapag maluwag na","Bawal pumasok sa daang ito","May ospital sa unahan","May dalawang-direksyong trapiko sa unahan"],"h1":"Isipin ang isang daan kung saan lahat ng sasakyan ay papunta sa iyo.","h2":"Ang pulang bilog na may puting guhit ay nangangahulugang “DO NOT ENTER” (Bawal pumasok), dahil ang trapiko sa daang iyon ay papunta sa iyo.","p":"Tama. Ang pulang bilog na may puting guhit ay nangangahulugang bawal pumasok."},"ar":{"q":"ماذا تعني دائرة حمراء يقطعها خط أبيض؟","o":["توقف، ثم انطلق عندما يكون الطريق خاليًا","لا تدخل هذا الطريق","مستشفى في الأمام","حركة مرور في الاتجاهين في الأمام"],"h1":"فكّر في طريق تأتي فيه كل السيارات نحوك.","h2":"الدائرة الحمراء التي يقطعها خط أبيض تعني «DO NOT ENTER» (ممنوع الدخول)، لأن السيارات في ذلك الطريق تأتي نحوك.","p":"صحيح. الدائرة الحمراء التي يقطعها خط أبيض تعني ممنوع الدخول."},"ht":{"q":"Kisa yon sèk wouj ki gen yon ba blan ki travèse l vle di?","o":["Kanpe, epi pati lè wout la lib","Pa antre nan wout sa a","Gen yon lopital pi devan","Gen machin k ap ale nan de direksyon pi devan"],"h1":"Panse ak yon wout kote tout machin yo ap vin sou ou.","h2":"Sèk wouj ki gen ba blan an vle di “DO NOT ENTER” (pa antre), paske machin sou wout sa a ap vin sou ou.","p":"Se sa. Sèk wouj ki gen ba blan an vle di pa antre."},"ref":{"doc":"FL","page":47}},{"id":"signs-015","scope":"US","cat":"signs","sign":{"shape":"wrong-way","text":"WRONG WAY"},"c":2,"en":{"q":"A red sign facing you says WRONG WAY. What should you do?","o":["Keep going with your hazard lights on","Speed up to reach the next exit","Pull over safely and turn around","Keep driving on the shoulder"],"h1":"The sign means you are going against traffic.","h2":"A WRONG WAY sign means you are driving against traffic, so you should pull over safely and turn around as soon as you can.","p":"Right. WRONG WAY means pull over safely and turn around."},"es":{"q":"Una señal roja frente a usted dice WRONG WAY (sentido contrario). ¿Qué debe hacer?","o":["Seguir con las luces de emergencia prendidas","Acelerar para llegar a la próxima salida","Orillarse con cuidado y dar la vuelta","Seguir manejando por el acotamiento"],"h1":"La señal quiere decir que usted va contra el tráfico.","h2":"Una señal de sentido contrario quiere decir que usted maneja contra el tráfico, así que debe orillarse con cuidado y dar la vuelta lo antes posible.","p":"Correcto. Sentido contrario significa orillarse con cuidado y dar la vuelta."},"zh":{"q":"一个面向你的红色标志写着 “WRONG WAY”（逆行）。你应该怎么做？","o":["打开危险警示灯，继续开","加速，开到下一个出口","安全靠边，然后掉头","继续在路肩上开"],"h1":"这个标志表示你在逆着车流开。","h2":"“WRONG WAY”（逆行）标志表示你在逆着车流开车，所以你要安全靠边，尽快掉头。","p":"对。“WRONG WAY” 表示安全靠边并掉头。"},"vi":{"q":"Một biển màu đỏ hướng về phía bạn ghi “WRONG WAY” (Đi sai chiều). Bạn nên làm gì?","o":["Cứ chạy tiếp và bật đèn khẩn cấp","Tăng tốc để tới lối ra kế tiếp","Tấp vào lề an toàn và quay đầu lại","Chạy tiếp trên lề đường"],"h1":"Biển này nghĩa là bạn đang chạy ngược chiều xe khác.","h2":"Biển “WRONG WAY” nghĩa là bạn đang chạy ngược chiều, nên bạn cần tấp vào lề an toàn và quay đầu lại càng sớm càng tốt.","p":"Đúng rồi. “WRONG WAY” nghĩa là tấp vào lề an toàn và quay đầu lại."},"tl":{"q":"May pulang karatula na nakaharap sa iyo at nakasulat ang “WRONG WAY” (Maling direksyon). Ano ang dapat mong gawin?","o":["Tuloy lang habang nakabukas ang hazard lights","Bumilis para maabot ang susunod na exit","Tumabi nang ligtas at umikot pabalik","Magpatuloy sa pagmamaneho sa gilid ng kalsada"],"h1":"Ang karatula ay nangangahulugang salungat ka sa daloy ng trapiko.","h2":"Ang “WRONG WAY” na karatula ay nangangahulugang salungat ka sa daloy ng trapiko, kaya dapat kang tumabi nang ligtas at umikot pabalik sa lalong madaling panahon.","p":"Tama. Ang “WRONG WAY” ay nangangahulugang tumabi nang ligtas at umikot pabalik."},"ar":{"q":"لافتة حمراء أمامك مكتوب عليها «WRONG WAY» (اتجاه خاطئ). ماذا يجب أن تفعل؟","o":["تابع السير مع تشغيل أضواء التحذير","زد السرعة لتصل إلى المخرج التالي","توقف على جانب الطريق بأمان واستدر عائدًا","تابع القيادة على كتف الطريق"],"h1":"اللافتة تعني أنك تسير عكس اتجاه السير.","h2":"لافتة «WRONG WAY» تعني أنك تقود عكس اتجاه السير، لذلك يجب أن تتوقف على جانب الطريق بأمان وتستدير عائدًا في أسرع وقت ممكن.","p":"صحيح. «WRONG WAY» تعني: توقف على الجانب بأمان واستدر عائدًا."},"ht":{"q":"Yon siy wouj ki fè fas ak ou di “WRONG WAY” (move direksyon). Kisa ou dwe fè?","o":["Kontinye ak limyè ijans ou limen","Akselere pou rive nan pwochen sòti a","Rale sou kote an sekirite epi vire tounen","Kontinye kondui sou arebò wout la"],"h1":"Siy la vle di w ap kondui kont trafik la.","h2":"Yon siy “WRONG WAY” vle di w ap kondui kont trafik la, kidonk ou dwe rale sou kote an sekirite epi vire tounen pi vit ou kapab.","p":"Se sa. “WRONG WAY” vle di rale sou kote an sekirite epi vire tounen."},"ref":{"doc":"FL","page":47}},{"id":"signs-016","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":3,"en":{"q":"What does this sign tell you?","o":["The lowest speed you may drive","The speed you must always drive","A suggested speed for curves","The top legal speed in good conditions"],"h1":"Think about whether you may go faster, or slower.","h2":"A speed limit sign shows the highest legal speed when conditions are good, so you may need to drive slower in rain, fog, or heavy traffic.","p":"Right. The speed limit is the top speed in good conditions."},"es":{"q":"¿Qué le dice esta señal?","o":["La velocidad más baja permitida","La velocidad a la que siempre debe ir","Una velocidad sugerida para curvas","La velocidad máxima legal en buenas condiciones"],"h1":"Piense si puede ir más rápido o más despacio.","h2":"Una señal de límite de velocidad muestra la velocidad máxima legal cuando las condiciones son buenas, así que puede tener que ir más despacio con lluvia, neblina o mucho tráfico.","p":"Correcto. El límite es la velocidad máxima en buenas condiciones."},"zh":{"q":"这个标志告诉你什么？","o":["你可以开的最低速度","你必须一直保持的速度","弯道的建议速度","在良好条件下的最高合法速度"],"h1":"想一想：你可以开得更快，还是要开得更慢。","h2":"限速标志表示在良好条件下的最高合法速度，所以下雨、有雾或车多时，你可能要开得更慢。","p":"对。限速是在良好条件下的最高速度。"},"vi":{"q":"Biển này cho bạn biết điều gì?","o":["Tốc độ thấp nhất bạn được chạy","Tốc độ bạn lúc nào cũng phải chạy","Tốc độ nên chạy ở khúc cua","Tốc độ cao nhất theo luật khi điều kiện tốt"],"h1":"Hãy nghĩ xem bạn được chạy nhanh hơn, hay chậm hơn.","h2":"Biển giới hạn tốc độ cho biết tốc độ cao nhất theo luật khi điều kiện tốt, nên bạn có thể cần chạy chậm hơn khi mưa, có sương mù, hoặc kẹt xe.","p":"Đúng rồi. Giới hạn tốc độ là tốc độ cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng karatulang ito?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bilis na dapat mong takbuhin palagi","Mungkahing bilis para sa mga kurba","Ang pinakamataas na legal na bilis kapag maayos ang kondisyon"],"h1":"Isipin kung puwede kang bumilis pa, o bumagal.","h2":"Ang karatula ng speed limit ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya maaaring kailangan mong bumagal kapag umuulan, may hamog, o mabigat ang trapiko.","p":"Tama. Ang speed limit ay ang pinakamataas na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه اللافتة؟","o":["أقل سرعة مسموح لك أن تقود بها","السرعة التي يجب أن تقود بها دائمًا","سرعة مقترحة للمنعطفات","أعلى سرعة قانونية عندما تكون الظروف جيدة"],"h1":"فكّر: هل يُسمح لك أن تسير أسرع، أم أبطأ؟","h2":"لافتة حد السرعة تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك قد تحتاج إلى القيادة أبطأ في المطر أو الضباب أو الزحام الشديد.","p":"صحيح. حد السرعة هو أعلى سرعة عندما تكون الظروف جيدة."},"ht":{"q":"Kisa siy sa a di ou?","o":["Vitès ki pi ba ou ka kondui","Vitès ou dwe toujou kondui","Yon vitès yo konseye pou koub yo","Vitès ki pi wo lalwa pèmèt lè kondisyon yo bon"],"h1":"Panse si ou ka ale pi vit, oswa pi dousman.","h2":"Yon siy limit vitès montre vitès ki pi wo lalwa pèmèt lè kondisyon yo bon, kidonk ou ka bezwen kondui pi dousman lè gen lapli, bwouya, oswa anpil machin.","p":"Se sa. Limit vitès la se vitès ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"signs-017","scope":"US","cat":"signs","sign":{"shape":"one-way"},"c":1,"en":{"q":"What does a ONE WAY sign with an arrow mean?","o":["Only one lane is open ahead","Traffic moves only in the arrow's direction","Only one car may pass at a time","You may make only one turn"],"h1":"Look at where the arrow points.","h2":"A ONE WAY sign means all traffic on that street moves only in the direction of the arrow.","p":"Right. One way means drive only in the arrow's direction."},"es":{"q":"¿Qué significa una señal ONE WAY (un solo sentido) con una flecha?","o":["Solo hay un carril abierto más adelante","El tráfico va solo en la dirección de la flecha","Solo puede pasar un carro a la vez","Solo puede dar una vuelta"],"h1":"Mire hacia dónde apunta la flecha.","h2":"Una señal de un solo sentido quiere decir que todo el tráfico en esa calle va solo en la dirección de la flecha.","p":"Correcto. Un solo sentido significa manejar solo hacia donde apunta la flecha."},"zh":{"q":"带箭头的 “ONE WAY”（单行道）标志是什么意思？","o":["前方只有一条车道开放","车辆只能按箭头方向行驶","一次只能过一辆车","你只能转一次弯"],"h1":"看看箭头指向哪里。","h2":"“ONE WAY”（单行道）标志表示这条街上所有车辆只能按箭头的方向行驶。","p":"对。单行道表示只能按箭头方向开。"},"vi":{"q":"Biển “ONE WAY” (Một chiều) có mũi tên có nghĩa là gì?","o":["Phía trước chỉ còn một làn mở","Xe chỉ được chạy theo hướng mũi tên","Mỗi lần chỉ một xe được đi qua","Bạn chỉ được rẽ một lần"],"h1":"Hãy nhìn xem mũi tên chỉ về đâu.","h2":"Biển “ONE WAY” nghĩa là mọi xe trên con đường đó chỉ được chạy theo hướng mũi tên.","p":"Đúng rồi. Một chiều nghĩa là chỉ chạy theo hướng mũi tên."},"tl":{"q":"Ano ang ibig sabihin ng “ONE WAY” na karatula na may arrow?","o":["Isang linya lang ang bukas sa unahan","Ang trapiko ay dumadaloy lang sa direksyon ng arrow","Isang sasakyan lang ang puwedeng dumaan bawat oras","Isang beses ka lang puwedeng lumiko"],"h1":"Tingnan kung saan nakaturo ang arrow.","h2":"Ang “ONE WAY” na karatula (Isang direksyon) ay nangangahulugang lahat ng trapiko sa kalyeng iyon ay dumadaloy lang sa direksyon ng arrow.","p":"Tama. Ang “ONE WAY” ay nangangahulugang magmaneho lang sa direksyon ng arrow."},"ar":{"q":"ماذا تعني لافتة «ONE WAY» (اتجاه واحد) التي عليها سهم؟","o":["مسار واحد فقط مفتوح في الأمام","السيارات تسير فقط في اتجاه السهم","سيارة واحدة فقط تمر في كل مرة","مسموح لك بمنعطف واحد فقط"],"h1":"انظر إلى أين يشير السهم.","h2":"لافتة «ONE WAY» تعني أن كل السيارات في ذلك الشارع تسير فقط في اتجاه السهم.","p":"صحيح. اتجاه واحد يعني: قُد فقط في اتجاه السهم."},"ht":{"q":"Kisa yon siy “ONE WAY” (yon sèl direksyon) ak yon flèch vle di?","o":["Se yon sèl koulwa ki louvri pi devan","Machin yo ale sèlman nan direksyon flèch la","Se yon sèl machin ki ka pase alafwa","Ou ka fè yon sèl vire sèlman"],"h1":"Gade ki bò flèch la montre.","h2":"Yon siy “ONE WAY” vle di tout machin nan lari sa a ale sèlman nan direksyon flèch la.","p":"Se sa. Yon sèl direksyon vle di kondui sèlman nan direksyon flèch la."},"ref":{"doc":"FL","page":48}},{"id":"signs-018","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO U-TURN"},"c":2,"en":{"q":"What does a NO U-TURN sign mean?","o":["You may not turn left here","You may not turn right here","You may not turn around here","You may not change lanes here"],"h1":"A U-turn makes the shape of the letter U.","h2":"A NO U-TURN sign means you may not turn your car around to go back the other way at that place.","p":"Right. No U-turn means you may not turn around here."},"es":{"q":"¿Qué significa una señal de NO U-TURN (prohibido dar vuelta en U)?","o":["No puede doblar a la izquierda aquí","No puede doblar a la derecha aquí","No puede dar la vuelta para regresar aquí","No puede cambiar de carril aquí"],"h1":"Una vuelta en U tiene la forma de la letra U.","h2":"Una señal de prohibido dar vuelta en U quiere decir que usted no puede dar la vuelta con su carro para regresar en ese lugar.","p":"Correcto. Prohibido vuelta en U significa que no puede dar la vuelta aquí."},"zh":{"q":"“NO U-TURN”（禁止掉头）标志是什么意思？","o":["这里不能左转","这里不能右转","这里不能掉头","这里不能换车道"],"h1":"掉头时车走的路线像字母 U。","h2":"“NO U-TURN”（禁止掉头）标志表示你在这里不能把车调过头往回开。","p":"对。禁止掉头表示这里不能掉头。"},"vi":{"q":"Biển “NO U-TURN” (Cấm quay đầu) có nghĩa là gì?","o":["Bạn không được rẽ trái ở đây","Bạn không được rẽ phải ở đây","Bạn không được quay đầu xe ở đây","Bạn không được đổi làn ở đây"],"h1":"Khi quay đầu, xe chạy theo hình chữ U.","h2":"Biển “NO U-TURN” nghĩa là ở chỗ đó bạn không được quay đầu xe để đi ngược lại.","p":"Đúng rồi. Cấm quay đầu nghĩa là bạn không được quay đầu xe ở đây."},"tl":{"q":"Ano ang ibig sabihin ng “NO U-TURN” na karatula?","o":["Hindi ka puwedeng kumaliwa dito","Hindi ka puwedeng kumanan dito","Hindi ka puwedeng umikot pabalik dito","Hindi ka puwedeng lumipat ng linya dito"],"h1":"Ang U-turn ay may hugis ng letrang U.","h2":"Ang “NO U-TURN” na karatula ay nangangahulugang hindi mo puwedeng iikot ang sasakyan mo para bumalik sa kabilang direksyon sa lugar na iyon.","p":"Tama. Ang “NO U-TURN” ay nangangahulugang hindi ka puwedeng umikot pabalik dito."},"ar":{"q":"ماذا تعني لافتة «NO U-TURN» (ممنوع الدوران للخلف)؟","o":["ممنوع أن تنعطف يسارًا هنا","ممنوع أن تنعطف يمينًا هنا","ممنوع أن تستدير عائدًا هنا","ممنوع أن تغيّر المسار هنا"],"h1":"الدوران للخلف يرسم شكل الحرف U.","h2":"لافتة «NO U-TURN» تعني أنه ممنوع أن تدير سيارتك لتعود في الاتجاه الآخر في ذلك المكان.","p":"صحيح. ممنوع الدوران للخلف يعني أنك لا تستطيع أن تستدير عائدًا هنا."},"ht":{"q":"Kisa yon siy “NO U-TURN” vle di?","o":["Ou pa ka vire agoch la a","Ou pa ka vire adwat la a","Ou pa ka vire tounen la a","Ou pa ka chanje koulwa la a"],"h1":"Yon “U-turn” fè fòm lèt U a.","h2":"Yon siy “NO U-TURN” vle di ou pa ka vire machin ou pou tounen nan lòt direksyon an kote sa a.","p":"Se sa. “NO U-TURN” vle di ou pa ka vire tounen la a."},"ref":{"doc":"FL","page":48}},{"id":"signs-019","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO TURN ON RED"},"c":3,"en":{"q":"What does a NO TURN ON RED sign mean?","o":["Turn right only after a full stop","Turn only when no cars are coming","Turn on red only at night","Wait for the green light before you turn"],"h1":"The sign changes what you may do while the light is red.","h2":"A NO TURN ON RED sign means you may not turn while the light is red, so you must wait for the green light.","p":"Right. No turn on red means wait for green."},"es":{"q":"¿Qué significa una señal de NO TURN ON RED (no doblar con luz roja)?","o":["Doblar a la derecha solo después de parar por completo","Doblar solo cuando no vengan carros","Doblar con luz roja solo de noche","Esperar la luz verde antes de doblar"],"h1":"La señal cambia lo que puede hacer mientras la luz está en rojo.","h2":"Una señal de no doblar con luz roja quiere decir que usted no puede doblar mientras la luz está en rojo, así que debe esperar la luz verde.","p":"Correcto. No doblar con luz roja significa esperar la luz verde."},"zh":{"q":"“NO TURN ON RED”（红灯禁止转弯）标志是什么意思？","o":["完全停车后才可以右转","没有来车时才可以转弯","只有晚上才可以红灯转弯","等绿灯亮了再转弯"],"h1":"这个标志改变了红灯时你可以做的事。","h2":"“NO TURN ON RED”（红灯禁止转弯）标志表示红灯时你不能转弯，所以你必须等绿灯。","p":"对。红灯禁止转弯表示要等绿灯。"},"vi":{"q":"Biển “NO TURN ON RED” (Cấm rẽ khi đèn đỏ) có nghĩa là gì?","o":["Chỉ rẽ phải sau khi dừng hẳn","Chỉ rẽ khi không có xe tới","Chỉ được rẽ khi đèn đỏ vào ban đêm","Chờ đèn xanh rồi mới rẽ"],"h1":"Biển này thay đổi điều bạn được làm khi đèn đang đỏ.","h2":"Biển “NO TURN ON RED” nghĩa là bạn không được rẽ khi đèn đang đỏ, nên bạn phải chờ đèn xanh.","p":"Đúng rồi. Cấm rẽ khi đèn đỏ nghĩa là chờ đèn xanh."},"tl":{"q":"Ano ang ibig sabihin ng “NO TURN ON RED” na karatula?","o":["Kumanan lang pagkatapos huminto nang buo","Lumiko lang kapag walang dumarating na sasakyan","Lumiko sa pula lang kapag gabi","Hintayin ang berdeng ilaw bago ka lumiko"],"h1":"Binabago ng karatula kung ano ang puwede mong gawin habang pula ang ilaw.","h2":"Ang “NO TURN ON RED” na karatula ay nangangahulugang hindi ka puwedeng lumiko habang pula ang ilaw, kaya dapat mong hintayin ang berdeng ilaw.","p":"Tama. Ang “NO TURN ON RED” ay nangangahulugang hintayin ang berde."},"ar":{"q":"ماذا تعني لافتة «NO TURN ON RED» (ممنوع الانعطاف عند الإشارة الحمراء)؟","o":["انعطف يمينًا فقط بعد توقف تام","انعطف فقط عندما لا تأتي سيارات","انعطف عند الإشارة الحمراء في الليل فقط","انتظر الإشارة الخضراء قبل أن تنعطف"],"h1":"اللافتة تغيّر ما يُسمح لك به عندما تكون الإشارة حمراء.","h2":"لافتة «NO TURN ON RED» تعني أنه ممنوع أن تنعطف والإشارة حمراء، لذلك يجب أن تنتظر الإشارة الخضراء.","p":"صحيح. ممنوع الانعطاف عند الأحمر يعني: انتظر الأخضر."},"ht":{"q":"Kisa yon siy “NO TURN ON RED” vle di?","o":["Vire adwat sèlman apre ou fin kanpe nèt","Vire sèlman lè pa gen machin k ap vini","Vire sou limyè wouj sèlman lannwit","Tann limyè vèt la anvan ou vire"],"h1":"Siy la chanje sa ou ka fè pandan limyè a wouj.","h2":"Yon siy “NO TURN ON RED” vle di ou pa ka vire pandan limyè a wouj, kidonk ou dwe tann limyè vèt la.","p":"Se sa. “NO TURN ON RED” vle di tann limyè vèt la."},"ref":{"doc":"FL","page":51}},{"id":"signs-020","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"KEEP RIGHT"},"c":0,"en":{"q":"A KEEP RIGHT sign stands at the front of a median. What does it mean?","o":["Stay to the right of the median or island","Move to the right lane to exit","The right lane ends ahead","Use the right lane only to pass"],"h1":"Think about which side of the median your car should go.","h2":"A KEEP RIGHT sign means you must drive on the right side of the median or island ahead.","p":"Right. Keep right means pass the median on its right side."},"es":{"q":"Una señal KEEP RIGHT (manténgase a la derecha) está al inicio de una isla. ¿Qué significa?","o":["Pasar por la derecha de la isla o el divisor","Cambiarse al carril derecho para salir","El carril derecho se termina más adelante","Usar el carril derecho solo para rebasar"],"h1":"Piense por qué lado de la isla debe pasar su carro.","h2":"Una señal de manténgase a la derecha quiere decir que usted debe pasar por el lado derecho de la isla o el divisor que está adelante.","p":"Correcto. Manténgase a la derecha significa pasar la isla por su lado derecho."},"zh":{"q":"一个 “KEEP RIGHT”（靠右行驶）标志立在中央隔离带的前端。它是什么意思？","o":["从隔离带或安全岛的右边通过","换到右车道准备出口","右车道在前方结束","只能用右车道超车"],"h1":"想一想：你的车应该走隔离带的哪一边。","h2":"“KEEP RIGHT”（靠右行驶）标志表示你必须从前方隔离带或安全岛的右边开过去。","p":"对。靠右行驶表示从隔离带的右边通过。"},"vi":{"q":"Biển “KEEP RIGHT” (Đi bên phải) đặt ở đầu một dải phân cách. Biển này có nghĩa là gì?","o":["Đi ở bên phải dải phân cách hoặc đảo giao thông","Chuyển sang làn phải để ra khỏi đường","Làn bên phải sắp hết","Chỉ dùng làn bên phải để vượt"],"h1":"Hãy nghĩ xem xe bạn nên đi ở bên nào của dải phân cách.","h2":"Biển “KEEP RIGHT” nghĩa là bạn phải chạy ở bên phải của dải phân cách hoặc đảo giao thông phía trước.","p":"Đúng rồi. Đi bên phải nghĩa là chạy qua bên phải dải phân cách."},"tl":{"q":"May “KEEP RIGHT” na karatula sa harap ng isang median. Ano ang ibig sabihin nito?","o":["Manatili sa kanan ng median o isla","Lumipat sa kanang linya para lumabas","Matatapos ang kanang linya sa unahan","Gamitin ang kanang linya para lang mag-overtake"],"h1":"Isipin kung sa aling bahagi ng median dapat dumaan ang sasakyan mo.","h2":"Ang “KEEP RIGHT” na karatula (Manatili sa kanan) ay nangangahulugang dapat kang magmaneho sa kanang bahagi ng median o isla sa unahan.","p":"Tama. Ang “KEEP RIGHT” ay nangangahulugang dumaan sa kanang bahagi ng median."},"ar":{"q":"لافتة «KEEP RIGHT» (الزم اليمين) موجودة في بداية جزيرة وسطية. ماذا تعني؟","o":["ابقَ على يمين الجزيرة الوسطية أو الجزيرة","انتقل إلى المسار الأيمن لتخرج","المسار الأيمن ينتهي في الأمام","استخدم المسار الأيمن للتجاوز فقط"],"h1":"فكّر في أي جانب من الجزيرة الوسطية يجب أن تمر سيارتك.","h2":"لافتة «KEEP RIGHT» تعني أنه يجب أن تقود على الجانب الأيمن من الجزيرة الوسطية أو الجزيرة التي أمامك.","p":"صحيح. الزم اليمين يعني: مُرّ على يمين الجزيرة الوسطية."},"ht":{"q":"Yon siy “KEEP RIGHT” (rete adwat) kanpe devan yon separasyon nan mitan wout la. Kisa li vle di?","o":["Rete sou bò dwat separasyon an oswa zile a","Ale nan koulwa dwat la pou sòti","Koulwa dwat la fini pi devan","Sèvi ak koulwa dwat la sèlman pou double"],"h1":"Panse sou ki bò separasyon an machin ou dwe pase.","h2":"Yon siy “KEEP RIGHT” vle di ou dwe kondui sou bò dwat separasyon an oswa zile ki devan an.","p":"Se sa. “KEEP RIGHT” vle di pase sou bò dwat separasyon an."},"ref":{"doc":"FL","page":48}},{"id":"signs-021","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ONLY"},"c":1,"en":{"q":"A sign over your lane shows only a left arrow. What must you do?","o":["You may go straight or turn left","You must turn left from this lane","You may turn left or right","You must change lanes at the light"],"h1":"The arrows show what each lane is allowed to do.","h2":"When the sign over your lane shows only a left arrow, that lane is for left turns, so you must turn left.","p":"Right. A left-only arrow means you must turn left."},"es":{"q":"Una señal encima de su carril muestra solo una flecha a la izquierda. ¿Qué debe hacer?","o":["Puede seguir derecho o doblar a la izquierda","Debe doblar a la izquierda desde este carril","Puede doblar a la izquierda o a la derecha","Debe cambiar de carril en el semáforo"],"h1":"Las flechas muestran lo que se permite en cada carril.","h2":"Cuando la señal encima de su carril muestra solo una flecha a la izquierda, ese carril es para doblar a la izquierda, así que usted debe doblar a la izquierda.","p":"Correcto. Una flecha solo a la izquierda significa que debe doblar a la izquierda."},"zh":{"q":"你车道上方的标志只有一个左转箭头。你必须怎么做？","o":["你可以直行或左转","你必须从这条车道左转","你可以左转或右转","你必须在红绿灯处换车道"],"h1":"箭头告诉你每条车道可以怎么走。","h2":"当你车道上方的标志只有左转箭头时，这条车道是左转车道，所以你必须左转。","p":"对。只有左转箭头表示你必须左转。"},"vi":{"q":"Biển phía trên làn của bạn chỉ có một mũi tên rẽ trái. Bạn phải làm gì?","o":["Bạn được đi thẳng hoặc rẽ trái","Bạn phải rẽ trái từ làn này","Bạn được rẽ trái hoặc rẽ phải","Bạn phải đổi làn ở chỗ đèn"],"h1":"Các mũi tên cho biết mỗi làn được phép đi hướng nào.","h2":"Khi biển trên làn của bạn chỉ có mũi tên rẽ trái, làn đó dành cho xe rẽ trái, nên bạn phải rẽ trái.","p":"Đúng rồi. Chỉ có mũi tên trái nghĩa là bạn phải rẽ trái."},"tl":{"q":"Ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa. Ano ang dapat mong gawin?","o":["Puwede kang dumiretso o kumaliwa","Dapat kang kumaliwa mula sa linyang ito","Puwede kang kumaliwa o kumanan","Dapat kang lumipat ng linya sa may ilaw"],"h1":"Ipinapakita ng mga arrow kung ano ang pinapayagan sa bawat linya.","h2":"Kapag ang karatula sa itaas ng linya mo ay nagpapakita lang ng arrow pakaliwa, ang linyang iyon ay para sa pagkaliwa, kaya dapat kang kumaliwa.","p":"Tama. Ang arrow na pakaliwa lang ay nangangahulugang dapat kang kumaliwa."},"ar":{"q":"لافتة فوق مسارك تُظهر سهمًا إلى اليسار فقط. ماذا يجب أن تفعل؟","o":["يمكنك أن تسير مستقيمًا أو تنعطف يسارًا","يجب أن تنعطف يسارًا من هذا المسار","يمكنك أن تنعطف يسارًا أو يمينًا","يجب أن تغيّر المسار عند الإشارة"],"h1":"الأسهم تُظهر ما هو مسموح في كل مسار.","h2":"عندما تُظهر اللافتة فوق مسارك سهمًا إلى اليسار فقط، فهذا المسار للانعطاف يسارًا، لذلك يجب أن تنعطف يسارًا.","p":"صحيح. سهم إلى اليسار فقط يعني أنه يجب أن تنعطف يسارًا."},"ht":{"q":"Yon siy anwo koulwa ou montre sèlman yon flèch agoch. Kisa ou dwe fè?","o":["Ou ka ale tou dwat oswa vire agoch","Ou dwe vire agoch nan koulwa sa a","Ou ka vire agoch oswa adwat","Ou dwe chanje koulwa nan limyè a"],"h1":"Flèch yo montre sa chak koulwa gen dwa fè.","h2":"Lè siy anwo koulwa ou montre sèlman yon flèch agoch, koulwa sa a se pou vire agoch, kidonk ou dwe vire agoch.","p":"Se sa. Yon flèch agoch sèlman vle di ou dwe vire agoch."},"ref":{"doc":"FL","page":47}},{"id":"signs-022","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"35 MPH"},"c":2,"en":{"q":"A curve warning sign has a small yellow sign below it with a speed. What is that speed?","o":["The lowest speed you may drive","The new speed limit for the road","A safe speed for the curve","A speed for trucks only"],"h1":"It is a yellow sign, not a white one.","h2":"The small yellow speed sign under a curve sign gives a safe speed for the curve in good conditions, so slow down to that speed or less.","p":"Right. The yellow speed plate gives a safe speed for the curve."},"es":{"q":"Una señal de curva tiene abajo una señal amarilla pequeña con una velocidad. ¿Qué es esa velocidad?","o":["La velocidad más baja permitida","El nuevo límite de velocidad de la vía","Una velocidad segura para la curva","Una velocidad solo para camiones"],"h1":"Es una señal amarilla, no blanca.","h2":"La señal amarilla pequeña debajo de una señal de curva le da una velocidad segura para la curva en buenas condiciones, así que baje a esa velocidad o menos.","p":"Correcto. La placa amarilla le da una velocidad segura para la curva."},"zh":{"q":"弯道警告标志下面有一个写着速度的黄色小牌子。这个速度是什么？","o":["你可以开的最低速度","这条路的新限速","过弯道的安全速度","只给卡车的速度"],"h1":"它是黄色的牌子，不是白色的。","h2":"弯道标志下面的黄色小速度牌，给出在良好条件下过这个弯道的安全速度，所以你要减速到这个速度或更低。","p":"对。黄色速度牌给出过弯道的安全速度。"},"vi":{"q":"Dưới biển báo khúc cua có một biển nhỏ màu vàng ghi tốc độ. Tốc độ đó là gì?","o":["Tốc độ thấp nhất bạn được chạy","Giới hạn tốc độ mới của con đường","Tốc độ an toàn cho khúc cua","Tốc độ chỉ dành cho xe tải"],"h1":"Đây là biển màu vàng, không phải biển màu trắng.","h2":"Biển nhỏ màu vàng dưới biển khúc cua cho biết tốc độ an toàn để qua khúc cua khi điều kiện tốt, nên bạn cần chạy chậm lại bằng hoặc thấp hơn tốc độ đó.","p":"Đúng rồi. Biển tốc độ màu vàng cho biết tốc độ an toàn qua khúc cua."},"tl":{"q":"May maliit na dilaw na karatula na may bilis sa ilalim ng karatula ng babala sa kurba. Ano ang bilis na iyon?","o":["Ang pinakamababang bilis na puwede mong takbuhin","Ang bagong speed limit ng kalsada","Isang ligtas na bilis para sa kurba","Bilis para sa mga trak lang"],"h1":"Ito ay dilaw na karatula, hindi puti.","h2":"Ang maliit na dilaw na karatula ng bilis sa ilalim ng karatula ng kurba ay nagbibigay ng ligtas na bilis para sa kurba kapag maayos ang kondisyon, kaya bumagal ka sa bilis na iyon o mas mababa pa.","p":"Tama. Ang dilaw na plaka ng bilis ay nagbibigay ng ligtas na bilis para sa kurba."},"ar":{"q":"تحت لافتة تحذير من منعطف توجد لافتة صفراء صغيرة عليها سرعة. ما هذه السرعة؟","o":["أقل سرعة مسموح لك أن تقود بها","حد السرعة الجديد للطريق","سرعة آمنة للمنعطف","سرعة للشاحنات فقط"],"h1":"إنها لافتة صفراء، وليست بيضاء.","h2":"لافتة السرعة الصفراء الصغيرة تحت لافتة المنعطف تعطي سرعة آمنة للمنعطف عندما تكون الظروف جيدة، لذلك خفف سرعتك إلى هذه السرعة أو أقل.","p":"صحيح. لوحة السرعة الصفراء تعطي سرعة آمنة للمنعطف."},"ht":{"q":"Yon siy avètisman pou koub gen yon ti siy jòn anba l ak yon vitès. Ki vitès sa a ye?","o":["Vitès ki pi ba ou ka kondui","Nouvo limit vitès pou wout la","Yon vitès ki an sekirite pou koub la","Yon vitès pou kamyon sèlman"],"h1":"Se yon siy jòn, se pa yon siy blan.","h2":"Ti siy vitès jòn anba siy koub la bay yon vitès ki an sekirite pou koub la lè kondisyon yo bon, kidonk ralanti rive nan vitès sa a oswa mwens.","p":"Se sa. Ti siy jòn nan bay yon vitès ki an sekirite pou koub la."},"ref":{"doc":"FL","page":49}},{"id":"signs-023","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"MERGE"},"c":3,"en":{"q":"A yellow sign shows a side line joining the main road. What should you expect?","o":["A railroad crossing","A dead end","A stop sign ahead","Cars entering your road from the side"],"h1":"Think about two roads becoming one.","h2":"This merge sign warns that cars will enter your road from the side, so be ready to adjust your speed or make room.","p":"Right. The merge sign means cars will join your road."},"es":{"q":"Una señal amarilla muestra una línea lateral que se une a la vía principal. ¿Qué debe esperar?","o":["Un cruce de tren","Una calle sin salida","Una señal de pare más adelante","Carros que entran a su vía desde un lado"],"h1":"Piense en dos vías que se vuelven una.","h2":"Esta señal de incorporación avisa que entrarán carros a su vía desde un lado, así que esté listo para ajustar su velocidad o darles espacio.","p":"Correcto. La señal de incorporación significa que entrarán carros a su vía."},"zh":{"q":"一个黄色标志上画着一条旁边的线并入主路。你应该预料到什么？","o":["铁路道口","死路","前方有停车标志","有车从旁边开进你的路"],"h1":"想一想：两条路变成一条路。","h2":"这个并道标志提醒你会有车从旁边开进你的路，所以要准备调整车速或让出空间。","p":"对。并道标志表示有车会开进你的路。"},"vi":{"q":"Một biển màu vàng có hình một đường nhánh nhập vào đường chính. Bạn nên chờ đợi điều gì?","o":["Chỗ băng qua đường sắt","Đường cụt","Biển dừng phía trước","Xe từ bên hông nhập vào đường của bạn"],"h1":"Hãy nghĩ đến hai con đường nhập lại thành một.","h2":"Biển nhập làn này cảnh báo rằng xe sẽ từ bên hông đi vào đường của bạn, nên bạn cần sẵn sàng đổi tốc độ hoặc chừa chỗ cho họ.","p":"Đúng rồi. Biển nhập làn nghĩa là xe khác sẽ vào đường của bạn."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng isang guhit sa gilid na sumasama sa pangunahing kalsada. Ano ang dapat mong asahan?","o":["Tawiran ng tren","Dulo ng daan (dead end)","May “STOP” sign sa unahan","Mga sasakyang papasok sa daan mo mula sa gilid"],"h1":"Isipin ang dalawang daan na nagiging isa.","h2":"Ang karatulang ito ng merge ay babala na may mga sasakyang papasok sa daan mo mula sa gilid, kaya maging handa na ayusin ang bilis mo o magbigay ng puwang.","p":"Tama. Ang karatula ng merge ay nangangahulugang may mga sasakyang sasama sa daan mo."},"ar":{"q":"لافتة صفراء تُظهر خطًا جانبيًا ينضم إلى الطريق الرئيسي. ماذا يجب أن تتوقع؟","o":["تقاطعًا مع سكة حديد","طريقًا مسدودًا","لافتة «STOP» (قف) في الأمام","سيارات تدخل طريقك من الجانب"],"h1":"فكّر في طريقين يصبحان طريقًا واحدًا.","h2":"لافتة الاندماج هذه تحذّر من أن سيارات ستدخل طريقك من الجانب، لذلك كن مستعدًا لتغيير سرعتك أو لترك مكان لها.","p":"صحيح. لافتة الاندماج تعني أن سيارات ستنضم إلى طريقك."},"ht":{"q":"Yon siy jòn montre yon liy sou kote k ap kole ak wout prensipal la. Kisa ou dwe atann?","o":["Yon kote tren travèse","Yon wout ki bloke","Yon siy “STOP” pi devan","Machin k ap antre sou wout ou a sou kote"],"h1":"Panse ak de wout k ap vin tounen yon sèl.","h2":"Siy sa a avèti ou gen machin ki pral antre sou wout ou a sou kote, kidonk pare pou chanje vitès ou oswa fè plas pou yo.","p":"Se sa. Siy sa a vle di gen machin ki pral antre sou wout ou a."},"ref":{"doc":"FL","page":49}},{"id":"signs-024","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"RIGHT LANE ENDS"},"c":0,"en":{"q":"You are in the right lane. A sign says RIGHT LANE ENDS. What should you do?","o":["Move left when it is safe","Speed up to stay ahead of others","Stop at the end of the lane","Drive on the shoulder"],"h1":"Your lane will soon be gone.","h2":"When the sign says your lane ends, you should signal and move into the next lane when it is safe.","p":"Right. When your lane ends, move over safely."},"es":{"q":"Usted va en el carril derecho. Una señal dice RIGHT LANE ENDS (el carril derecho termina). ¿Qué debe hacer?","o":["Pasarse a la izquierda cuando sea seguro","Acelerar para quedar delante de los demás","Pararse al final del carril","Manejar por el acotamiento"],"h1":"Su carril pronto desaparece.","h2":"Cuando la señal dice que su carril termina, usted debe poner la direccional y pasarse al otro carril cuando sea seguro.","p":"Correcto. Cuando su carril termina, cámbiese con cuidado."},"zh":{"q":"你在右车道。一个标志写着 “RIGHT LANE ENDS”（右车道结束）。你应该怎么做？","o":["安全时换到左边车道","加速，开到别的车前面","在车道尽头停车","在路肩上开"],"h1":"你的车道很快就没有了。","h2":"当标志说你的车道要结束时，你应该打转向灯，在安全时换到旁边的车道。","p":"对。你的车道结束时，要安全地换道。"},"vi":{"q":"Bạn đang ở làn bên phải. Một biển ghi “RIGHT LANE ENDS” (Làn phải sắp hết). Bạn nên làm gì?","o":["Chuyển sang trái khi an toàn","Tăng tốc để chạy trước xe khác","Dừng lại ở cuối làn","Chạy trên lề đường"],"h1":"Làn của bạn sắp không còn nữa.","h2":"Khi biển báo làn của bạn sắp hết, bạn cần bật xi-nhan và chuyển sang làn bên cạnh khi an toàn.","p":"Đúng rồi. Khi làn của bạn hết, hãy chuyển làn an toàn."},"tl":{"q":"Nasa kanang linya ka. Nakasulat sa karatula ang “RIGHT LANE ENDS” (Matatapos ang kanang linya). Ano ang dapat mong gawin?","o":["Lumipat sa kaliwa kapag ligtas na","Bumilis para mauna sa iba","Huminto sa dulo ng linya","Magmaneho sa gilid ng kalsada"],"h1":"Mawawala na sa lalong madaling panahon ang linya mo.","h2":"Kapag sinasabi ng karatula na matatapos ang linya mo, dapat kang mag-signal at lumipat sa katabing linya kapag ligtas na.","p":"Tama. Kapag natatapos ang linya mo, lumipat nang ligtas."},"ar":{"q":"أنت في المسار الأيمن. لافتة مكتوب عليها «RIGHT LANE ENDS» (المسار الأيمن ينتهي). ماذا يجب أن تفعل؟","o":["انتقل إلى اليسار عندما يكون ذلك آمنًا","زد السرعة لتبقى أمام الآخرين","توقف في نهاية المسار","قُد على كتف الطريق"],"h1":"مسارك سيختفي قريبًا.","h2":"عندما تقول اللافتة إن مسارك ينتهي، يجب أن تشغّل الإشارة وتنتقل إلى المسار المجاور عندما يكون ذلك آمنًا.","p":"صحيح. عندما ينتهي مسارك، انتقل إلى مسار آخر بأمان."},"ht":{"q":"Ou nan koulwa dwat la. Yon siy di “RIGHT LANE ENDS” (koulwa dwat la fini). Kisa ou dwe fè?","o":["Pase agoch lè sa an sekirite","Akselere pou rete devan lòt yo","Kanpe nan bout koulwa a","Kondui sou arebò wout la"],"h1":"Koulwa ou a pral disparèt talè.","h2":"Lè siy la di koulwa ou a fini, ou dwe mete siyal epi pase nan lòt koulwa a lè sa an sekirite.","p":"Se sa. Lè koulwa ou fini, chanje koulwa an sekirite."},"ref":{"doc":"FL","page":49}},{"id":"signs-025","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY"},"c":1,"en":{"q":"A warning sign says a divided highway begins. What changes ahead?","o":["The road comes to an end","A median will separate the two directions","The speed limit goes up","Two lanes become one lane"],"h1":"Think about what divides the road.","h2":"A divided highway begins sign means a median will soon separate traffic going each way, so keep to the right of it.","p":"Right. A median will separate the two directions."},"es":{"q":"Una señal de advertencia dice que empieza una carretera dividida. ¿Qué cambia más adelante?","o":["La vía se termina","Una isla o divisor va a separar los dos sentidos","El límite de velocidad sube","Dos carriles se vuelven uno"],"h1":"Piense en qué divide la vía.","h2":"La señal de que empieza una carretera dividida significa que pronto un divisor va a separar el tráfico de cada sentido, así que manténgase a la derecha de él.","p":"Correcto. Un divisor va a separar los dos sentidos."},"zh":{"q":"一个警告标志说分隔公路开始了。前方有什么变化？","o":["道路到头了","中央隔离带会把两个方向的车分开","限速提高","两条车道变成一条"],"h1":"想一想：是什么把道路分开。","h2":"“分隔公路开始” 标志表示很快会有中央隔离带把两个方向的车流分开，所以要从隔离带右边行驶。","p":"对。中央隔离带会把两个方向的车分开。"},"vi":{"q":"Một biển cảnh báo cho biết đường có dải phân cách bắt đầu. Phía trước có gì thay đổi?","o":["Con đường sắp hết","Một dải phân cách sẽ chia hai chiều xe ra","Giới hạn tốc độ tăng lên","Hai làn nhập thành một làn"],"h1":"Hãy nghĩ xem cái gì chia con đường ra.","h2":"Biển báo đường có dải phân cách bắt đầu nghĩa là sắp có một dải phân cách tách xe chạy mỗi chiều, nên bạn cần đi ở bên phải của nó.","p":"Đúng rồi. Một dải phân cách sẽ chia hai chiều xe ra."},"tl":{"q":"Sinasabi ng isang karatula ng babala na nagsisimula ang divided highway. Ano ang magbabago sa unahan?","o":["Matatapos na ang kalsada","May median na maghihiwalay sa dalawang direksyon","Tataas ang speed limit","Ang dalawang linya ay magiging isang linya"],"h1":"Isipin kung ano ang naghahati sa kalsada.","h2":"Ang karatula na nagsisimula ang divided highway ay nangangahulugang may median na maghihiwalay sa trapikong papunta sa magkabilang direksyon, kaya manatili ka sa kanan nito.","p":"Tama. May median na maghihiwalay sa dalawang direksyon."},"ar":{"q":"لافتة تحذير تقول إن طريقًا سريعًا مقسومًا يبدأ. ما الذي يتغيّر في الأمام؟","o":["الطريق ينتهي","جزيرة وسطية ستفصل بين الاتجاهين","حد السرعة يرتفع","مساران يصبحان مسارًا واحدًا"],"h1":"فكّر في ما يقسم الطريق.","h2":"لافتة بداية الطريق السريع المقسوم تعني أن جزيرة وسطية ستفصل قريبًا بين السيارات في كل اتجاه، لذلك ابقَ على يمينها.","p":"صحيح. جزيرة وسطية ستفصل بين الاتجاهين."},"ht":{"q":"Yon siy avètisman di yon wout ki gen separasyon kòmanse. Kisa ki chanje pi devan?","o":["Wout la fini","Yon separasyon pral separe de direksyon yo","Limit vitès la monte","De koulwa vin tounen yon sèl"],"h1":"Panse ak sa ki separe wout la.","h2":"Siy sa a vle di talè gen yon separasyon nan mitan wout la k ap separe machin k ap ale nan chak direksyon, kidonk rete sou bò dwat li.","p":"Se sa. Yon separasyon pral separe de direksyon yo."},"ref":{"doc":"FL","page":49}},{"id":"signs-026","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIVIDED HIGHWAY ENDS"},"c":2,"en":{"q":"A sign says the divided highway ends. What should you expect?","o":["You may now pass on the right","The road becomes one-way","Cars coming toward you with no divider","A bridge is just ahead"],"h1":"Think about what happens when the median is gone.","h2":"When the divided highway ends, there is no median anymore, so cars going the other way will be right beside you and you must keep right.","p":"Right. With no divider, oncoming cars share the road with you."},"es":{"q":"Una señal dice que termina la carretera dividida. ¿Qué debe esperar?","o":["Ahora puede rebasar por la derecha","La vía se vuelve de un solo sentido","Carros que vienen de frente sin divisor","Un puente justo adelante"],"h1":"Piense en lo que pasa cuando ya no hay divisor.","h2":"Cuando termina la carretera dividida, ya no hay divisor, así que los carros que van en el otro sentido pasarán a su lado y usted debe mantenerse a la derecha.","p":"Correcto. Sin divisor, los carros de frente comparten la vía con usted."},"zh":{"q":"一个标志说分隔公路结束了。你应该预料到什么？","o":["现在可以从右边超车","道路变成单行道","对面来车，中间没有隔离","前方马上有一座桥"],"h1":"想一想：没有中央隔离带后会怎样。","h2":"分隔公路结束后就没有中央隔离带了，所以对面开来的车就在你旁边，你必须靠右行驶。","p":"对。没有隔离带，对面来车和你共用道路。"},"vi":{"q":"Một biển cho biết đường có dải phân cách kết thúc. Bạn nên chờ đợi điều gì?","o":["Bây giờ bạn được vượt bên phải","Con đường trở thành đường một chiều","Xe chạy ngược chiều về phía bạn mà không có gì ngăn cách","Ngay phía trước có cây cầu"],"h1":"Hãy nghĩ xem điều gì xảy ra khi không còn dải phân cách.","h2":"Khi đường có dải phân cách kết thúc, không còn dải phân cách nữa, nên xe chạy ngược chiều sẽ ở ngay cạnh bạn và bạn phải đi bên phải.","p":"Đúng rồi. Không có dải phân cách, xe ngược chiều chạy chung đường với bạn."},"tl":{"q":"Sinasabi ng isang karatula na matatapos na ang divided highway. Ano ang dapat mong asahan?","o":["Puwede ka nang mag-overtake sa kanan","Magiging one-way ang kalsada","Mga sasakyang paparating sa iyo na walang harang sa gitna","May tulay sa unahan"],"h1":"Isipin kung ano ang mangyayari kapag wala na ang median.","h2":"Kapag natapos ang divided highway, wala nang median, kaya ang mga sasakyang papunta sa kabilang direksyon ay nasa tabi mo na mismo at dapat kang manatili sa kanan.","p":"Tama. Kapag walang harang, kasama mo sa kalsada ang mga paparating na sasakyan."},"ar":{"q":"لافتة تقول إن الطريق السريع المقسوم ينتهي. ماذا يجب أن تتوقع؟","o":["الآن يمكنك أن تتجاوز من اليمين","الطريق يصبح باتجاه واحد","سيارات تأتي نحوك بدون فاصل","جسر قريب جدًا في الأمام"],"h1":"فكّر في ما يحدث عندما تختفي الجزيرة الوسطية.","h2":"عندما ينتهي الطريق السريع المقسوم لا توجد جزيرة وسطية بعد ذلك، لذلك ستكون السيارات القادمة من الاتجاه الآخر بجانبك مباشرة، ويجب أن تلزم اليمين.","p":"صحيح. بدون فاصل، السيارات القادمة تشاركك الطريق."},"ht":{"q":"Yon siy di wout ki gen separasyon an fini. Kisa ou dwe atann?","o":["Kounye a ou ka double sou bò dwat","Wout la vin yon sèl direksyon","Machin k ap vin sou ou san anyen pou separe nou","Gen yon pon touprè"],"h1":"Panse ak sa k ap pase lè separasyon an pa la ankò.","h2":"Lè wout ki gen separasyon an fini, pa gen separasyon ankò, kidonk machin k ap ale nan lòt direksyon an ap pase bò kote ou, e ou dwe rete adwat.","p":"Se sa. San separasyon, machin k ap vin sou ou pataje wout la avè ou."},"ref":{"doc":"FL","page":49}},{"id":"signs-027","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SLIPPERY WHEN WET"},"c":0,"en":{"q":"A sign says SLIPPERY WHEN WET. It is raining. What should you do?","o":["Slow down and avoid sudden moves","Turn on cruise control","Speed up to get past the area","Brake hard if the car slides"],"h1":"Think about how tires grip a wet road.","h2":"A wet road can be slick, so you should slow down and avoid quick turns or hard braking.","p":"Right. On a slippery road, slow down and move smoothly."},"es":{"q":"Una señal dice SLIPPERY WHEN WET (resbaloso cuando está mojado). Está lloviendo. ¿Qué debe hacer?","o":["Bajar la velocidad y evitar movimientos bruscos","Prender el control de velocidad","Acelerar para pasar rápido esa zona","Frenar fuerte si el carro resbala"],"h1":"Piense en cómo agarran las llantas en una vía mojada.","h2":"Una vía mojada puede estar resbalosa, así que usted debe bajar la velocidad y evitar vueltas rápidas o frenazos.","p":"Correcto. En una vía resbalosa, baje la velocidad y maneje con suavidad."},"zh":{"q":"一个标志写着 “SLIPPERY WHEN WET”（路湿易滑）。现在正在下雨。你应该怎么做？","o":["减速，避免突然的动作","打开定速巡航","加速，快快开过这一段","车打滑时用力刹车"],"h1":"想一想：轮胎在湿路上抓地怎么样。","h2":"湿的路面可能很滑，所以你要减速，避免急转弯或急刹车。","p":"对。路滑时要减速，动作要平稳。"},"vi":{"q":"Một biển ghi “SLIPPERY WHEN WET” (Trơn khi ướt). Trời đang mưa. Bạn nên làm gì?","o":["Chạy chậm lại và tránh cử động đột ngột","Bật chế độ tự giữ tốc độ (cruise control)","Tăng tốc để qua khu vực này","Đạp thắng mạnh nếu xe bị trượt"],"h1":"Hãy nghĩ xem bánh xe bám đường ướt như thế nào.","h2":"Đường ướt có thể trơn, nên bạn cần chạy chậm lại và tránh rẽ gấp hoặc đạp thắng mạnh.","p":"Đúng rồi. Trên đường trơn, hãy chạy chậm và lái nhẹ nhàng."},"tl":{"q":"Nakasulat sa karatula ang “SLIPPERY WHEN WET” (Madulas kapag basa). Umuulan. Ano ang dapat mong gawin?","o":["Bumagal at iwasan ang biglang galaw","Buksan ang cruise control","Bumilis para malampasan ang lugar","Pumreno nang malakas kapag dumulas ang sasakyan"],"h1":"Isipin kung paano kumakapit ang gulong sa basang kalsada.","h2":"Ang basang kalsada ay maaaring madulas, kaya dapat kang bumagal at iwasan ang mabilis na pagliko o malakas na pagpreno.","p":"Tama. Sa madulas na kalsada, bumagal at gumalaw nang maayos at dahan-dahan."},"ar":{"q":"لافتة مكتوب عليها «SLIPPERY WHEN WET» (زلق عند البلل). المطر ينزل. ماذا يجب أن تفعل؟","o":["خفف السرعة وتجنّب الحركات المفاجئة","شغّل مثبّت السرعة","زد السرعة لتتجاوز المنطقة","اضغط الفرامل بقوة إذا انزلقت السيارة"],"h1":"فكّر في كيف تمسك الإطارات بالطريق المبلل.","h2":"الطريق المبلل قد يكون زلقًا، لذلك يجب أن تخفف السرعة وتتجنب الانعطاف السريع أو الضغط القوي على الفرامل.","p":"صحيح. على الطريق الزلق، خفف السرعة وتحرك بهدوء."},"ht":{"q":"Yon siy di “SLIPPERY WHEN WET” (glise lè l mouye). Lapli ap tonbe. Kisa ou dwe fè?","o":["Ralanti epi evite fè mouvman brid sou kou","Limen kontwòl vitès otomatik la","Akselere pou pase zòn nan vit","Frennen fò si machin nan glise"],"h1":"Panse ki jan kawotchou yo kenbe sou yon wout mouye.","h2":"Yon wout mouye ka glise, kidonk ou dwe ralanti epi evite vire vit oswa frennen fò.","p":"Se sa. Sou yon wout ki glise, ralanti epi kondui dousman."},"ref":{"doc":"FL","page":50}},{"id":"signs-028","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SIGNAL AHEAD"},"c":1,"en":{"q":"A yellow sign shows a traffic light. What does it warn you about?","o":["A stop sign is ahead","A traffic signal is ahead","A railroad is ahead","A police checkpoint is ahead"],"h1":"Look at the picture on the sign.","h2":"This sign warns that a traffic signal is ahead, so be ready to slow down or stop.","p":"Right. The sign warns that a traffic light is ahead."},"es":{"q":"Una señal amarilla muestra un semáforo. ¿De qué le avisa?","o":["Hay una señal de pare más adelante","Hay un semáforo más adelante","Hay un tren más adelante","Hay un retén de policía más adelante"],"h1":"Mire el dibujo en la señal.","h2":"Esta señal avisa que hay un semáforo más adelante, así que esté listo para bajar la velocidad o pararse.","p":"Correcto. La señal avisa que hay un semáforo más adelante."},"zh":{"q":"一个黄色标志上画着红绿灯。它提醒你什么？","o":["前方有停车标志","前方有交通信号灯","前方有铁路","前方有警察检查站"],"h1":"看看标志上的图。","h2":"这个标志提醒你前方有交通信号灯，所以要准备减速或停车。","p":"对。这个标志提醒你前方有红绿灯。"},"vi":{"q":"Một biển màu vàng có hình đèn giao thông. Biển này cảnh báo bạn về điều gì?","o":["Phía trước có biển dừng","Phía trước có đèn giao thông","Phía trước có đường sắt","Phía trước có trạm kiểm tra của cảnh sát"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển này cảnh báo phía trước có đèn giao thông, nên bạn cần sẵn sàng chạy chậm lại hoặc dừng.","p":"Đúng rồi. Biển này cảnh báo phía trước có đèn giao thông."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng ilaw trapiko. Tungkol saan ang babala nito?","o":["May “STOP” sign sa unahan","May ilaw trapiko sa unahan","May riles ng tren sa unahan","May checkpoint ng pulis sa unahan"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang karatulang ito ay babala na may ilaw trapiko sa unahan, kaya maging handang bumagal o huminto.","p":"Tama. Ang karatula ay babala na may ilaw trapiko sa unahan."},"ar":{"q":"لافتة صفراء تُظهر إشارة مرور ضوئية. ممّ تحذّرك؟","o":["لافتة «STOP» (قف) في الأمام","إشارة مرور ضوئية في الأمام","سكة حديد في الأمام","نقطة تفتيش للشرطة في الأمام"],"h1":"انظر إلى الصورة على اللافتة.","h2":"هذه اللافتة تحذّر من أن إشارة مرور ضوئية في الأمام، لذلك كن مستعدًا لتخفيف السرعة أو للتوقف.","p":"صحيح. اللافتة تحذّر من أن إشارة ضوئية في الأمام."},"ht":{"q":"Yon siy jòn montre yon limyè trafik. Pou kisa li avèti ou?","o":["Gen yon siy “STOP” pi devan","Gen yon limyè trafik pi devan","Gen yon ray tren pi devan","Gen yon baryè polis pi devan"],"h1":"Gade foto ki sou siy la.","h2":"Siy sa a avèti ou gen yon limyè trafik pi devan, kidonk pare pou ralanti oswa kanpe.","p":"Se sa. Siy la avèti ou gen yon limyè trafik pi devan."},"ref":{"doc":"FL","page":49}},{"id":"signs-029","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DEER CROSSING"},"c":2,"en":{"q":"A yellow sign shows a deer. What should you do?","o":["Look for a nearby zoo","Pull over and wait","Watch for deer near or on the road","Speed up through the area"],"h1":"Animals may run onto the road with no warning.","h2":"A deer crossing sign means deer often cross there, so you should slow down and watch the sides of the road, especially at dawn and dusk.","p":"Right. Watch for deer near the road."},"es":{"q":"Una señal amarilla muestra un venado. ¿Qué debe hacer?","o":["Buscar un zoológico cerca","Orillarse y esperar","Estar atento a venados cerca o en la vía","Acelerar para pasar la zona"],"h1":"Los animales pueden salir a la vía sin aviso.","h2":"Una señal de cruce de venados quiere decir que los venados cruzan seguido por ahí, así que usted debe bajar la velocidad y mirar los lados de la vía, sobre todo al amanecer y al anochecer.","p":"Correcto. Esté atento a los venados cerca de la vía."},"zh":{"q":"一个黄色标志上画着一只鹿。你应该怎么做？","o":["找找附近的动物园","靠边停车等待","注意路边或路上的鹿","加速开过这一段"],"h1":"动物可能突然跑到路上。","h2":"鹿出没标志表示鹿常在这里过马路，所以你要减速，注意路的两边，特别是在清晨和傍晚。","p":"对。注意路边的鹿。"},"vi":{"q":"Một biển màu vàng có hình con nai. Bạn nên làm gì?","o":["Tìm sở thú gần đó","Tấp vào lề và chờ","Chú ý nai ở gần hoặc trên đường","Tăng tốc qua khu vực này"],"h1":"Thú vật có thể chạy ra đường mà không báo trước.","h2":"Biển nai băng qua đường nghĩa là nai thường đi qua chỗ đó, nên bạn cần chạy chậm lại và nhìn hai bên đường, nhất là lúc bình minh và hoàng hôn.","p":"Đúng rồi. Hãy chú ý nai ở gần đường."},"tl":{"q":"Ang dilaw na karatula ay nagpapakita ng usa. Ano ang dapat mong gawin?","o":["Hanapin ang zoo sa malapit","Tumabi at maghintay","Mag-ingat sa mga usa malapit o nasa kalsada","Bumilis sa lugar na iyon"],"h1":"Maaaring tumakbo ang mga hayop papunta sa kalsada nang walang babala.","h2":"Ang karatula ng tawiran ng usa ay nangangahulugang madalas tumawid ang mga usa doon, kaya dapat kang bumagal at bantayan ang gilid ng kalsada, lalo na sa madaling-araw at takipsilim.","p":"Tama. Mag-ingat sa mga usa malapit sa kalsada."},"ar":{"q":"لافتة صفراء تُظهر غزالًا. ماذا يجب أن تفعل؟","o":["ابحث عن حديقة حيوانات قريبة","توقف على جانب الطريق وانتظر","انتبه للغزلان قرب الطريق أو عليه","زد السرعة في هذه المنطقة"],"h1":"الحيوانات قد تركض إلى الطريق بدون إنذار.","h2":"لافتة عبور الغزلان تعني أن الغزلان تعبر هناك كثيرًا، لذلك يجب أن تخفف السرعة وتراقب جانبي الطريق، خاصة عند الفجر وعند الغروب.","p":"صحيح. انتبه للغزلان قرب الطريق."},"ht":{"q":"Yon siy jòn montre yon sèf. Kisa ou dwe fè?","o":["Chèche yon zoo ki toupre","Rale sou kote epi tann","Veye si gen sèf toupre wout la oswa sou wout la","Akselere pou travèse zòn nan"],"h1":"Bèt ka kouri antre sou wout la san avètisman.","h2":"Yon siy sèf vle di sèf konn travèse la a, kidonk ou dwe ralanti epi gade de bò wout la, sitou lè solèy ap leve ak lè l ap kouche.","p":"Se sa. Veye si gen sèf toupre wout la."},"ref":{"doc":"FL","page":50}},{"id":"signs-030","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"LOW CLEARANCE"},"c":3,"en":{"q":"A sign warns of LOW CLEARANCE ahead. What does it mean?","o":["The road gets narrow","The shoulder is soft","A steep hill is ahead","A low bridge or overpass is ahead"],"h1":"Clearance is the space above your vehicle.","h2":"A low clearance sign means a bridge or overpass ahead is low, so tall vehicles may not fit under it.","p":"Right. Low clearance means a low bridge or overpass is ahead."},"es":{"q":"Una señal avisa LOW CLEARANCE (altura baja) más adelante. ¿Qué significa?","o":["La vía se hace angosta","El acotamiento está blando","Hay una cuesta empinada","Hay un puente o paso elevado bajo"],"h1":"Piense en el espacio que hay encima de su vehículo.","h2":"Una señal de altura baja quiere decir que un puente o paso elevado más adelante es bajo, así que los vehículos altos podrían no caber.","p":"Correcto. Altura baja significa que hay un puente o paso elevado bajo."},"zh":{"q":"一个标志提醒前方 “LOW CLEARANCE”（限高）。它是什么意思？","o":["道路变窄","路肩很软","前方有陡坡","前方有很低的桥或天桥"],"h1":"“Clearance” 是你的车上方的空间。","h2":"限高标志表示前方的桥或天桥很低，所以高的车辆可能过不去。","p":"对。限高表示前方有很低的桥或天桥。"},"vi":{"q":"Một biển cảnh báo “LOW CLEARANCE” (Chiều cao thấp) phía trước. Biển này có nghĩa là gì?","o":["Đường hẹp lại","Lề đường bị mềm","Phía trước có dốc cao","Phía trước có cầu hoặc cầu vượt thấp"],"h1":"Chiều cao ở đây là khoảng trống phía trên xe của bạn.","h2":"Biển chiều cao thấp nghĩa là cây cầu hoặc cầu vượt phía trước thấp, nên xe cao có thể không chui qua được.","p":"Đúng rồi. Chiều cao thấp nghĩa là phía trước có cầu hoặc cầu vượt thấp."},"tl":{"q":"May karatula na nagbababala ng “LOW CLEARANCE” (Mababang puwang sa itaas) sa unahan. Ano ang ibig sabihin nito?","o":["Kikitid ang kalsada","Malambot ang gilid ng kalsada","May matarik na burol sa unahan","May mababang tulay o overpass sa unahan"],"h1":"Ang clearance ay ang puwang sa itaas ng sasakyan mo.","h2":"Ang “LOW CLEARANCE” na karatula ay nangangahulugang mababa ang tulay o overpass sa unahan, kaya maaaring hindi kumasya sa ilalim nito ang matataas na sasakyan.","p":"Tama. Ang “LOW CLEARANCE” ay nangangahulugang may mababang tulay o overpass sa unahan."},"ar":{"q":"لافتة تحذّر من «LOW CLEARANCE» (ارتفاع منخفض) في الأمام. ماذا تعني؟","o":["الطريق يضيق","كتف الطريق طري","منحدر حاد في الأمام","جسر منخفض أو جسر علوي منخفض في الأمام"],"h1":"الارتفاع هنا هو المسافة فوق سيارتك.","h2":"لافتة الارتفاع المنخفض تعني أن جسرًا أو جسرًا علويًا في الأمام منخفض، لذلك قد لا تستطيع المركبات العالية أن تمر تحته.","p":"صحيح. الارتفاع المنخفض يعني جسرًا أو جسرًا علويًا منخفضًا في الأمام."},"ht":{"q":"Yon siy avèti “LOW CLEARANCE” (wotè ba) pi devan. Kisa li vle di?","o":["Wout la vin etwat","Arebò wout la mou","Gen yon mòn ki apik pi devan","Gen yon pon oswa yon pasaj anlè ki ba pi devan"],"h1":"Wotè a se espas ki anwo machin ou.","h2":"Yon siy “LOW CLEARANCE” vle di yon pon oswa yon pasaj anlè pi devan ba, kidonk machin ki wo yo ka pa pase anba l.","p":"Se sa. “LOW CLEARANCE” vle di gen yon pon oswa yon pasaj anlè ki ba pi devan."},"ref":{"doc":"FL","page":50}},{"id":"signs-031","scope":"US","cat":"signs","sign":{"shape":"school","text":"SCHOOL"},"c":0,"en":{"q":"You see a school crossing sign. What should you do?","o":["Slow down and watch for children","Honk to warn the children","Speed up to clear the area","Change lanes to go around"],"h1":"Children can be hard to see and may move fast.","h2":"A school crossing sign means children may be crossing, so you should slow down and be ready to stop.","p":"Right. At a school crossing, slow down and watch for children."},"es":{"q":"Usted ve una señal de cruce escolar. ¿Qué debe hacer?","o":["Bajar la velocidad y estar atento a los niños","Tocar la bocina para avisar a los niños","Acelerar para pasar la zona","Cambiar de carril para rodear"],"h1":"Los niños pueden ser difíciles de ver y moverse rápido.","h2":"Una señal de cruce escolar quiere decir que puede haber niños cruzando, así que usted debe bajar la velocidad y estar listo para parar.","p":"Correcto. En un cruce escolar, baje la velocidad y esté atento a los niños."},"zh":{"q":"你看到一个学校人行横道标志。你应该怎么做？","o":["减速，注意儿童","按喇叭提醒孩子们","加速快快开过","换车道绕过去"],"h1":"儿童不容易看到，而且可能动得很快。","h2":"学校人行横道标志表示可能有儿童过马路，所以你要减速，准备停车。","p":"对。在学校人行横道，要减速并注意儿童。"},"vi":{"q":"Bạn thấy biển báo chỗ học sinh qua đường. Bạn nên làm gì?","o":["Chạy chậm lại và chú ý trẻ em","Bấm còi để báo cho trẻ em","Tăng tốc để qua khu vực này","Đổi làn để chạy vòng qua"],"h1":"Trẻ em có thể khó thấy và có thể chạy rất nhanh.","h2":"Biển chỗ học sinh qua đường nghĩa là trẻ em có thể đang băng qua, nên bạn cần chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Ở chỗ học sinh qua đường, hãy chạy chậm và chú ý trẻ em."},"tl":{"q":"May nakita kang karatula ng tawiran ng mga estudyante. Ano ang dapat mong gawin?","o":["Bumagal at mag-ingat sa mga bata","Bumusina para bigyang-babala ang mga bata","Bumilis para malampasan ang lugar","Lumipat ng linya para lumihis"],"h1":"Mahirap makita ang mga bata at maaari silang gumalaw nang mabilis.","h2":"Ang karatula ng tawiran ng mga estudyante ay nangangahulugang maaaring may mga batang tumatawid, kaya dapat kang bumagal at maging handang huminto.","p":"Tama. Sa tawiran ng mga estudyante, bumagal at mag-ingat sa mga bata."},"ar":{"q":"ترى لافتة معبر مدرسة. ماذا يجب أن تفعل؟","o":["خفف السرعة وانتبه للأطفال","استخدم البوق لتحذير الأطفال","زد السرعة لتخرج من المنطقة","غيّر المسار لتمر من حولهم"],"h1":"الأطفال قد يكون من الصعب رؤيتهم، وقد يتحركون بسرعة.","h2":"لافتة معبر المدرسة تعني أن أطفالًا قد يعبرون، لذلك يجب أن تخفف السرعة وتكون مستعدًا للتوقف.","p":"صحيح. عند معبر المدرسة، خفف السرعة وانتبه للأطفال."},"ht":{"q":"Ou wè yon siy kote timoun lekòl travèse. Kisa ou dwe fè?","o":["Ralanti epi veye timoun yo","Klaksonen pou avèti timoun yo","Akselere pou kite zòn nan","Chanje koulwa pou pase bò kote yo"],"h1":"Timoun ka difisil pou wè epi yo ka deplase vit.","h2":"Yon siy kote timoun lekòl travèse vle di timoun ka ap travèse, kidonk ou dwe ralanti epi pare pou kanpe.","p":"Se sa. Kote timoun lekòl travèse, ralanti epi veye timoun yo."},"ref":{"doc":"FL","page":57}},{"id":"signs-032","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SPEED LIMIT WHEN FLASHING"},"c":1,"en":{"q":"A school zone speed sign has yellow lights that are flashing. What does that mean?","o":["The lower speed is only a suggestion","The lower school speed limit is in effect now","School is closed today","Only school buses must slow down"],"h1":"The lights tell you when the sign applies.","h2":"When the lights on a school zone sign are flashing, the lower school speed limit is the law right now, so you must slow down to it.","p":"Right. Flashing lights mean the school speed limit applies now."},"es":{"q":"Una señal de velocidad en zona escolar tiene luces amarillas intermitentes. ¿Qué significa?","o":["La velocidad baja es solo una sugerencia","El límite escolar más bajo está vigente ahora","Hoy no hay clases","Solo los autobuses escolares deben ir más despacio"],"h1":"Las luces le dicen cuándo aplica la señal.","h2":"Cuando las luces de una señal de zona escolar están intermitentes, el límite escolar más bajo es la ley en ese momento, así que usted debe bajar a esa velocidad.","p":"Correcto. Las luces intermitentes significan que el límite escolar aplica ahora."},"zh":{"q":"学校区限速标志上的黄灯在闪。这是什么意思？","o":["较低的速度只是建议","较低的学校区限速现在生效","学校今天放假","只有校车要减速"],"h1":"灯告诉你这个标志什么时候有效。","h2":"学校区标志上的灯在闪时，较低的学校区限速现在就是法律，所以你必须减速到这个速度。","p":"对。灯在闪表示学校区限速现在生效。"},"vi":{"q":"Biển tốc độ khu vực trường học có đèn vàng đang nhấp nháy. Điều đó có nghĩa là gì?","o":["Tốc độ thấp hơn chỉ là lời khuyên","Giới hạn tốc độ thấp hơn của trường học đang có hiệu lực ngay bây giờ","Hôm nay trường nghỉ học","Chỉ xe buýt trường học phải chạy chậm"],"h1":"Đèn cho bạn biết khi nào biển có hiệu lực.","h2":"Khi đèn trên biển khu vực trường học nhấp nháy, giới hạn tốc độ thấp hơn của trường học là luật ngay lúc đó, nên bạn phải chạy chậm lại theo tốc độ đó.","p":"Đúng rồi. Đèn nhấp nháy nghĩa là giới hạn tốc độ trường học có hiệu lực ngay bây giờ."},"tl":{"q":"Ang karatula ng bilis sa school zone ay may dilaw na ilaw na kumikislap. Ano ang ibig sabihin nito?","o":["Mungkahi lang ang mas mababang bilis","Ipinapatupad na ngayon ang mas mababang speed limit sa paaralan","Sarado ang paaralan ngayong araw","Mga school bus lang ang dapat bumagal"],"h1":"Sinasabi ng mga ilaw kung kailan ipinapatupad ang karatula.","h2":"Kapag kumikislap ang mga ilaw sa karatula ng school zone, ang mas mababang speed limit sa paaralan ay batas na sa oras na iyon, kaya dapat kang bumagal sa bilis na iyon.","p":"Tama. Ang kumikislap na ilaw ay nangangahulugang ipinapatupad na ngayon ang speed limit sa paaralan."},"ar":{"q":"لافتة سرعة في منطقة مدرسة عليها أضواء صفراء تومض. ماذا يعني ذلك؟","o":["السرعة المنخفضة مجرد اقتراح","حد السرعة المنخفض للمدرسة مطبّق الآن","المدرسة مغلقة اليوم","حافلات المدارس فقط يجب أن تخفف السرعة"],"h1":"الأضواء تخبرك متى تكون اللافتة مطبّقة.","h2":"عندما تومض الأضواء على لافتة منطقة المدرسة، يكون حد السرعة المنخفض للمدرسة هو القانون الآن، لذلك يجب أن تخفف سرعتك إليه.","p":"صحيح. الأضواء الوامضة تعني أن حد سرعة المدرسة مطبّق الآن."},"ht":{"q":"Yon siy vitès zòn lekòl gen limyè jòn k ap kliyote. Kisa sa vle di?","o":["Vitès ki pi ba a se yon konsèy sèlman","Limit vitès lekòl ki pi ba a an aplikasyon kounye a","Lekòl la fèmen jodi a","Se sèlman bis lekòl ki dwe ralanti"],"h1":"Limyè yo di ou ki lè siy la an aplikasyon.","h2":"Lè limyè ki sou siy zòn lekòl la ap kliyote, limit vitès lekòl ki pi ba a se lalwa kounye a, kidonk ou dwe ralanti rive nan vitès sa a.","p":"Se sa. Limyè k ap kliyote vle di limit vitès lekòl la an aplikasyon kounye a."},"ref":{"doc":"FL","page":57}},{"id":"signs-033","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":2,"en":{"q":"At a railroad crossing, the red lights are flashing. What must you do?","o":["Slow down and cross with care","Go if you do not see a train","Stop and wait until the lights stop","Drive around the gate"],"h1":"Flashing red lights at the tracks mean a train is coming.","h2":"Flashing red lights at a railroad crossing mean a train is near, so you must stop and wait until the lights stop flashing.","p":"Right. Flashing red lights at the tracks mean stop and wait."},"es":{"q":"En un cruce de tren, las luces rojas están intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y cruzar con cuidado","Seguir si no ve un tren","Pararse y esperar hasta que las luces se apaguen","Rodear la barrera"],"h1":"Las luces rojas intermitentes en la vía del tren significan que viene un tren.","h2":"Las luces rojas intermitentes en un cruce de tren quieren decir que un tren está cerca, así que usted debe pararse y esperar hasta que las luces dejen de parpadear.","p":"Correcto. Luces rojas intermitentes en la vía significan parar y esperar."},"zh":{"q":"在铁路道口，红灯在闪。你必须怎么做？","o":["减速，小心通过","没看到火车就走","停车，等灯不闪了再走","绕过栏杆开过去"],"h1":"铁轨旁的红灯在闪，表示火车要来了。","h2":"铁路道口的红灯在闪，表示火车就在附近，所以你必须停车，等灯不闪了再走。","p":"对。铁轨旁红灯闪表示停车等待。"},"vi":{"q":"Tại chỗ băng qua đường sắt, đèn đỏ đang nhấp nháy. Bạn phải làm gì?","o":["Chạy chậm lại và băng qua cẩn thận","Đi nếu bạn không thấy tàu","Dừng lại và chờ tới khi đèn hết nhấp nháy","Chạy vòng qua thanh chắn"],"h1":"Đèn đỏ nhấp nháy ở đường ray nghĩa là có tàu đang tới.","h2":"Đèn đỏ nhấp nháy ở chỗ băng qua đường sắt nghĩa là tàu đang ở gần, nên bạn phải dừng lại và chờ tới khi đèn hết nhấp nháy.","p":"Đúng rồi. Đèn đỏ nhấp nháy ở đường ray nghĩa là dừng lại và chờ."},"tl":{"q":"Sa tawiran ng tren, kumikislap ang mga pulang ilaw. Ano ang dapat mong gawin?","o":["Bumagal at tumawid nang maingat","Tumawid kung wala kang nakikitang tren","Huminto at maghintay hanggang tumigil ang mga ilaw","Lumihis paikot sa harang"],"h1":"Ang kumikislap na pulang ilaw sa riles ay nangangahulugang may paparating na tren.","h2":"Ang kumikislap na pulang ilaw sa tawiran ng tren ay nangangahulugang malapit na ang tren, kaya dapat kang huminto at maghintay hanggang tumigil sa pagkislap ang mga ilaw.","p":"Tama. Ang kumikislap na pulang ilaw sa riles ay nangangahulugang huminto at maghintay."},"ar":{"q":"عند تقاطع سكة حديد، الأضواء الحمراء تومض. ماذا يجب أن تفعل؟","o":["خفف السرعة واعبر بحذر","انطلق إذا لم ترَ قطارًا","توقف وانتظر حتى تتوقف الأضواء","قُد حول الحاجز"],"h1":"الأضواء الحمراء الوامضة عند السكة تعني أن قطارًا قادم.","h2":"الأضواء الحمراء الوامضة عند تقاطع سكة الحديد تعني أن قطارًا قريب، لذلك يجب أن تتوقف وتنتظر حتى تتوقف الأضواء عن الوميض.","p":"صحيح. الأضواء الحمراء الوامضة عند السكة تعني: توقف وانتظر."},"ht":{"q":"Kote tren travèse a, limyè wouj yo ap kliyote. Kisa ou dwe fè?","o":["Ralanti epi travèse avèk prekosyon","Pase si ou pa wè tren","Kanpe epi tann jiskaske limyè yo sispann","Pase bò kote baryè a"],"h1":"Limyè wouj k ap kliyote bò ray yo vle di gen yon tren k ap vini.","h2":"Limyè wouj k ap kliyote kote tren travèse vle di gen yon tren toupre, kidonk ou dwe kanpe epi tann jiskaske limyè yo sispann kliyote.","p":"Se sa. Limyè wouj k ap kliyote bò ray yo vle di kanpe epi tann."},"ref":{"doc":"FL","page":56}},{"id":"signs-034","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"The railroad gates are down, but you do not see a train. What should you do?","o":["Drive around the gates if it looks clear","Cross slowly with hazard lights on","Use the other lane to get past","Stay stopped until the gates go up"],"h1":"A train can be closer and faster than it looks.","h2":"When the gates are down, a train is coming even if you cannot see it, so you must stay stopped until the gates go all the way up.","p":"Right. Never go around the gates. Wait until they go up."},"es":{"q":"Las barreras del tren están abajo, pero usted no ve ningún tren. ¿Qué debe hacer?","o":["Rodear las barreras si parece libre","Cruzar despacio con las luces de emergencia","Usar el otro carril para pasar","Quedarse parado hasta que suban las barreras"],"h1":"Un tren puede estar más cerca y venir más rápido de lo que parece.","h2":"Cuando las barreras están abajo, viene un tren aunque usted no lo vea, así que debe quedarse parado hasta que las barreras suban por completo.","p":"Correcto. Nunca rodee las barreras. Espere a que suban."},"zh":{"q":"铁路道口的栏杆放下了，但你没看到火车。你应该怎么做？","o":["看起来没车就绕过栏杆","打开危险警示灯慢慢通过","用另一条车道开过去","一直停着，等栏杆升起"],"h1":"火车可能比看起来更近、更快。","h2":"栏杆放下时，就算你看不到火车，火车也正在开来，所以你必须一直停着，等栏杆完全升起。","p":"对。绝不要绕过栏杆。等栏杆升起。"},"vi":{"q":"Thanh chắn đường sắt đã hạ xuống, nhưng bạn không thấy tàu. Bạn nên làm gì?","o":["Chạy vòng qua thanh chắn nếu thấy đường trống","Băng qua chậm và bật đèn khẩn cấp","Dùng làn bên kia để đi qua","Đứng yên tới khi thanh chắn nâng lên"],"h1":"Tàu có thể ở gần hơn và chạy nhanh hơn bạn tưởng.","h2":"Khi thanh chắn đã hạ xuống, nghĩa là có tàu đang tới dù bạn không thấy, nên bạn phải đứng yên tới khi thanh chắn nâng lên hết.","p":"Đúng rồi. Không bao giờ chạy vòng qua thanh chắn. Hãy chờ tới khi nó nâng lên."},"tl":{"q":"Nakababa ang mga harang sa riles, pero wala kang nakikitang tren. Ano ang dapat mong gawin?","o":["Lumihis paikot sa mga harang kung mukhang walang tren","Tumawid nang dahan-dahan habang nakabukas ang hazard lights","Gamitin ang kabilang linya para makalampas","Manatiling nakahinto hanggang tumaas ang mga harang"],"h1":"Maaaring mas malapit at mas mabilis ang tren kaysa sa inaakala mo.","h2":"Kapag nakababa ang mga harang, may paparating na tren kahit hindi mo ito nakikita, kaya dapat kang manatiling nakahinto hanggang tuluyang tumaas ang mga harang.","p":"Tama. Huwag kailanman lumihis paikot sa mga harang. Maghintay hanggang tumaas ang mga ito."},"ar":{"q":"حواجز سكة الحديد نازلة، لكنك لا ترى قطارًا. ماذا يجب أن تفعل؟","o":["قُد حول الحواجز إذا بدا الطريق خاليًا","اعبر ببطء مع تشغيل أضواء التحذير","استخدم المسار الآخر لتمر","ابقَ متوقفًا حتى ترتفع الحواجز"],"h1":"القطار قد يكون أقرب وأسرع مما يبدو.","h2":"عندما تكون الحواجز نازلة فهناك قطار قادم حتى لو لم تره، لذلك يجب أن تبقى متوقفًا حتى ترتفع الحواجز بالكامل.","p":"صحيح. لا تمر أبدًا حول الحواجز. انتظر حتى ترتفع."},"ht":{"q":"Baryè tren yo desann, men ou pa wè okenn tren. Kisa ou dwe fè?","o":["Pase bò kote baryè yo si sanble pa gen anyen","Travèse dousman ak limyè ijans ou limen","Sèvi ak lòt koulwa a pou pase","Rete kanpe jiskaske baryè yo monte"],"h1":"Yon tren ka pi pre epi pi rapid pase jan li sanble.","h2":"Lè baryè yo desann, gen yon tren k ap vini menm si ou pa ka wè l, kidonk ou dwe rete kanpe jiskaske baryè yo monte nèt.","p":"Se sa. Pa janm pase bò kote baryè yo. Tann jiskaske yo monte."},"ref":{"doc":"FL","page":56}},{"id":"signs-035","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"2 TRACKS"},"c":0,"en":{"q":"A small sign under the crossbuck says 2 TRACKS. What does it warn you about?","o":["After one train passes, another may come","Trains pass only two times a day","Two lanes of cars cross the tracks","You must wait two minutes to cross"],"h1":"Think about what could hide behind the first train.","h2":"The tracks sign tells you there is more than one track, so after one train passes you must look again, because a second train may be coming.","p":"Right. More than one track means another train may come."},"es":{"q":"Una señal pequeña debajo de la cruz de ferrocarril dice 2 TRACKS (2 vías). ¿De qué le avisa?","o":["Después de que pase un tren, puede venir otro","Los trenes pasan solo dos veces al día","Dos carriles de carros cruzan la vía","Debe esperar dos minutos para cruzar"],"h1":"Piense en lo que podría estar escondido detrás del primer tren.","h2":"La señal de vías le dice que hay más de una vía, así que después de que pase un tren usted debe volver a mirar, porque puede venir un segundo tren.","p":"Correcto. Más de una vía significa que puede venir otro tren."},"zh":{"q":"铁路交叉标志下面有一个小牌子写着 “2 TRACKS”（两条铁轨）。它提醒你什么？","o":["一列火车过去后，可能还有另一列","火车一天只过两次","有两条车道的车穿过铁轨","你必须等两分钟才能过"],"h1":"想一想：第一列火车后面可能藏着什么。","h2":"这个牌子告诉你这里不止一条铁轨，所以一列火车过去后，你必须再看一看，因为可能还有第二列火车开来。","p":"对。不止一条铁轨，表示可能还有另一列火车。"},"vi":{"q":"Một biển nhỏ dưới biển chữ X ghi “2 TRACKS” (2 đường ray). Biển này cảnh báo bạn về điều gì?","o":["Sau khi một tàu chạy qua, có thể có tàu khác tới","Tàu chỉ chạy qua hai lần mỗi ngày","Có hai làn xe hơi băng qua đường ray","Bạn phải chờ hai phút mới được băng qua"],"h1":"Hãy nghĩ xem cái gì có thể bị che khuất sau chiếc tàu đầu tiên.","h2":"Biển này cho biết có nhiều hơn một đường ray, nên sau khi một tàu chạy qua bạn phải nhìn lại, vì có thể có tàu thứ hai đang tới.","p":"Đúng rồi. Nhiều hơn một đường ray nghĩa là có thể có tàu khác tới."},"tl":{"q":"May maliit na karatula sa ilalim ng crossbuck na nakasulat ang “2 TRACKS” (2 riles). Tungkol saan ang babala nito?","o":["Pagkalampas ng isang tren, maaaring may dumating pang isa","Dalawang beses lang dumadaan ang tren sa isang araw","Dalawang linya ng sasakyan ang tumatawid sa riles","Dapat kang maghintay ng dalawang minuto bago tumawid"],"h1":"Isipin kung ano ang puwedeng nakatago sa likod ng unang tren.","h2":"Sinasabi ng karatulang ito na may higit sa isang riles, kaya pagkalampas ng isang tren ay dapat kang tumingin ulit, dahil maaaring may paparating na pangalawang tren.","p":"Tama. Kapag higit sa isa ang riles, maaaring may dumating pang ibang tren."},"ar":{"q":"لافتة صغيرة تحت علامة X مكتوب عليها «2 TRACKS» (سكتان). ممّ تحذّرك؟","o":["بعد أن يمر قطار، قد يأتي قطار آخر","القطارات تمر مرتين فقط في اليوم","مساران للسيارات يعبران السكة","يجب أن تنتظر دقيقتين قبل أن تعبر"],"h1":"فكّر في ما قد يكون مختبئًا خلف القطار الأول.","h2":"لافتة عدد السكك تخبرك بأن هناك أكثر من سكة واحدة، لذلك بعد أن يمر قطار يجب أن تنظر مرة أخرى، لأن قطارًا ثانيًا قد يكون قادمًا.","p":"صحيح. أكثر من سكة واحدة يعني أن قطارًا آخر قد يأتي."},"ht":{"q":"Yon ti siy anba kwa tren an di “2 TRACKS” (2 ray). Pou kisa li avèti ou?","o":["Apre yon tren fin pase, yon lòt ka vini","Tren pase sèlman de fwa pa jou","De koulwa machin travèse ray yo","Ou dwe tann de minit pou travèse"],"h1":"Panse ak sa ki ka kache dèyè premye tren an.","h2":"Siy sa a di ou gen plis pase yon ray, kidonk apre yon tren fin pase ou dwe gade ankò, paske yon dezyèm tren ka ap vini.","p":"Se sa. Plis pase yon ray vle di yon lòt tren ka vini."},"ref":{"doc":"FL","page":56}},{"id":"signs-036","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, when you must stop for a train, where should you stop?","o":["Right on top of the first rail","Between 15 and 50 feet from the nearest rail","At least 100 feet from the tracks","Anywhere you like before the crossing"],"h1":"You need space between you and the train, but not too much.","h2":"In Florida, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail, so the train has room and you can still see it.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Florida, cuando debe pararse por un tren, ¿dónde debe pararse?","o":["Justo encima del primer riel","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies de la vía","Donde quiera antes del cruce"],"h1":"Necesita espacio entre usted y el tren, pero no demasiado.","h2":"En Florida, usted debe pararse a no menos de 15 pies y no más de 50 pies del riel más cercano, para que el tren tenga espacio y usted todavía pueda verlo.","p":"Correcto. Párese entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Florida，你必须为火车停车时，应该停在哪里？","o":["就停在第一条铁轨上","离最近的铁轨 15 到 50 feet（英尺）之间","离铁轨至少 100 feet（英尺）","过道口前随便哪里都行"],"h1":"你和火车之间要有空间，但不能太远。","h2":"在 Florida，你停车的位置离最近的铁轨不能少于 15 feet（英尺），也不能超过 50 feet（英尺），这样火车有空间通过，你也还能看见火车。","p":"对。停在离最近的铁轨 15 到 50 feet（英尺）之间。"},"vi":{"q":"Ở Florida, khi bạn phải dừng chờ tàu, bạn nên dừng ở đâu?","o":["Ngay trên thanh ray đầu tiên","Cách thanh ray gần nhất từ 15 tới 50 feet","Cách đường ray ít nhất 100 feet","Bất cứ chỗ nào bạn muốn trước chỗ băng qua"],"h1":"Bạn cần có khoảng cách với tàu, nhưng không quá xa.","h2":"Ở Florida, bạn phải dừng cách thanh ray gần nhất không dưới 15 feet và không quá 50 feet, để tàu có chỗ đi qua và bạn vẫn nhìn thấy tàu.","p":"Đúng rồi. Hãy dừng cách thanh ray gần nhất từ 15 tới 50 feet."},"tl":{"q":"Sa Florida, kapag kailangan mong huminto para sa tren, saan ka dapat huminto?","o":["Mismo sa ibabaw ng unang riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Hindi bababa sa 100 feet mula sa riles","Kahit saan mo gusto bago ang tawiran"],"h1":"Kailangan mo ng puwang sa pagitan mo at ng tren, pero hindi sobrang layo.","h2":"Sa Florida, dapat kang huminto nang hindi lalapit sa 15 feet at hindi lalayo sa 50 feet mula sa pinakamalapit na riles, para may puwang ang tren at nakikita mo pa rin ito.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Florida، عندما يجب أن تتوقف من أجل قطار، أين يجب أن تتوقف؟","o":["فوق القضيب الأول مباشرة","على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب","على بعد 100 قدم (feet) على الأقل من السكة","في أي مكان تريده قبل التقاطع"],"h1":"تحتاج إلى مسافة بينك وبين القطار، لكن ليست كبيرة جدًا.","h2":"في Florida، يجب أن تتوقف على مسافة لا تقل عن 15 قدمًا (feet) ولا تزيد عن 50 قدمًا من أقرب قضيب، لكي يكون للقطار مكان وتبقى قادرًا على رؤيته.","p":"صحيح. توقف على مسافة بين 15 و50 قدمًا (feet) من أقرب قضيب."},"ht":{"q":"Nan Florida, lè ou dwe kanpe pou yon tren, ki kote ou dwe kanpe?","o":["Dirèkteman sou premye ray la","Ant 15 ak 50 pye de ray ki pi pre a","Omwen 100 pye de ray yo","Nenpòt kote ou vle anvan kote tren travèse a"],"h1":"Ou bezwen espas ant ou menm ak tren an, men pa twòp.","h2":"Nan Florida, ou dwe kanpe pa pi pre pase 15 pye epi pa pi lwen pase 50 pye de ray ki pi pre a, pou tren an gen plas epi pou ou ka toujou wè l.","p":"Se sa. Kanpe ant 15 ak 50 pye de ray ki pi pre a."},"ref":{"doc":"FL","page":56}},{"id":"signs-037","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ROAD WORK AHEAD"},"c":2,"en":{"q":"An orange sign says ROAD WORK AHEAD. What should you do?","o":["Find another road, this one is closed","Keep your speed, workers are done","Slow down and be ready for workers and changes","Speed up to get through the work fast"],"h1":"Think about people working near moving cars.","h2":"A road work sign means workers, equipment, or lane changes may be ahead, so you should slow down and pay close attention.","p":"Right. In road work, slow down and stay alert."},"es":{"q":"Una señal anaranjada dice ROAD WORK AHEAD (obras más adelante). ¿Qué debe hacer?","o":["Buscar otra vía, esta está cerrada","Mantener su velocidad, los trabajadores ya terminaron","Bajar la velocidad y estar listo para trabajadores y cambios","Acelerar para pasar las obras rápido"],"h1":"Piense en personas trabajando cerca de carros en movimiento.","h2":"Una señal de obras quiere decir que puede haber trabajadores, máquinas o cambios de carril más adelante, así que usted debe bajar la velocidad y poner mucha atención.","p":"Correcto. En zona de obras, baje la velocidad y esté alerta."},"zh":{"q":"一个橙色标志写着 “ROAD WORK AHEAD”（前方道路施工）。你应该怎么做？","o":["另找一条路，这条路封了","保持车速，工人已经完工了","减速，准备好面对工人和道路变化","加速，快快开过施工区"],"h1":"想一想：有人在行驶的车旁边工作。","h2":"道路施工标志表示前方可能有工人、机械或车道变化，所以你要减速，非常注意。","p":"对。在道路施工区，要减速并保持警觉。"},"vi":{"q":"Một biển màu cam ghi “ROAD WORK AHEAD” (Phía trước đang sửa đường). Bạn nên làm gì?","o":["Tìm đường khác, đường này đã đóng","Giữ nguyên tốc độ, công nhân đã làm xong","Chạy chậm lại và sẵn sàng gặp công nhân và thay đổi trên đường","Tăng tốc để qua chỗ sửa đường cho nhanh"],"h1":"Hãy nghĩ đến những người đang làm việc gần xe đang chạy.","h2":"Biển sửa đường nghĩa là phía trước có thể có công nhân, máy móc, hoặc làn đường thay đổi, nên bạn cần chạy chậm lại và chú ý kỹ.","p":"Đúng rồi. Ở chỗ sửa đường, hãy chạy chậm và luôn tỉnh táo."},"tl":{"q":"Nakasulat sa orange na karatula ang “ROAD WORK AHEAD” (May ginagawang kalsada sa unahan). Ano ang dapat mong gawin?","o":["Maghanap ng ibang daan, sarado ang daang ito","Panatilihin ang bilis mo, tapos na ang mga trabahador","Bumagal at maging handa sa mga trabahador at mga pagbabago","Bumilis para mabilis na malampasan ang ginagawa"],"h1":"Isipin ang mga taong nagtatrabaho malapit sa mga umaandar na sasakyan.","h2":"Ang karatula ng ginagawang kalsada ay nangangahulugang maaaring may mga trabahador, kagamitan, o pagbabago ng linya sa unahan, kaya dapat kang bumagal at magbigay ng buong atensyon.","p":"Tama. Kapag may ginagawang kalsada, bumagal at manatiling alerto."},"ar":{"q":"لافتة برتقالية مكتوب عليها «ROAD WORK AHEAD» (أعمال طرق في الأمام). ماذا يجب أن تفعل؟","o":["ابحث عن طريق آخر، فهذا الطريق مغلق","حافظ على سرعتك، فالعمال انتهوا","خفف السرعة واستعد للعمال وللتغييرات","زد السرعة لتعبر منطقة العمل بسرعة"],"h1":"فكّر في أشخاص يعملون قرب سيارات تتحرك.","h2":"لافتة أعمال الطرق تعني أن هناك عمالًا أو معدات أو تغييرات في المسارات في الأمام، لذلك يجب أن تخفف السرعة وتنتبه جيدًا.","p":"صحيح. في أعمال الطرق، خفف السرعة وابقَ منتبهًا."},"ht":{"q":"Yon siy zoranj di “ROAD WORK AHEAD” (travay sou wout pi devan). Kisa ou dwe fè?","o":["Chèche yon lòt wout, wout sa a fèmen","Kenbe vitès ou, travayè yo fini","Ralanti epi pare pou travayè ak chanjman","Akselere pou pase travay la vit"],"h1":"Panse ak moun k ap travay toupre machin k ap woule.","h2":"Yon siy travay sou wout vle di ka gen travayè, machin travay, oswa chanjman koulwa pi devan, kidonk ou dwe ralanti epi fè anpil atansyon.","p":"Se sa. Nan travay sou wout, ralanti epi rete vijilan."},"ref":{"doc":"FL","page":54}},{"id":"signs-038","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"In a work zone, a flagger holds a STOP paddle toward you. What should you do?","o":["Slow down and drive around the flagger","Honk and keep going slowly","Stop only if workers are close to you","Stop and wait until the flagger lets you go"],"h1":"The flagger is directing traffic like a signal.","h2":"A flagger's STOP paddle has the same force as a stop sign, so you must stop and wait until the flagger signals you to go.","p":"Right. Obey the flagger and wait for the signal to go."},"es":{"q":"En una zona de obras, un banderero le muestra un letrero de STOP (pare). ¿Qué debe hacer?","o":["Bajar la velocidad y rodear al banderero","Tocar la bocina y seguir despacio","Pararse solo si hay trabajadores cerca","Pararse y esperar hasta que el banderero le deje pasar"],"h1":"El banderero dirige el tráfico como un semáforo.","h2":"El letrero de pare del banderero vale igual que una señal de pare, así que usted debe pararse y esperar hasta que el banderero le indique que siga.","p":"Correcto. Obedezca al banderero y espere su señal para seguir."},"zh":{"q":"在施工区，一名旗手把 “STOP”（停）牌子朝向你。你应该怎么做？","o":["减速，绕过旗手开过去","按喇叭，慢慢继续开","只有工人离你很近时才停","停车，等旗手让你走"],"h1":"旗手像信号灯一样指挥交通。","h2":"旗手的 “STOP” 牌子和停车标志有一样的效力，所以你必须停车，等旗手示意你走。","p":"对。服从旗手，等他示意你走。"},"vi":{"q":"Trong khu vực thi công, người cầm biển điều khiển giao thông giơ biển “STOP” về phía bạn. Bạn nên làm gì?","o":["Chạy chậm lại và chạy vòng qua người cầm biển","Bấm còi và tiếp tục chạy chậm","Chỉ dừng nếu công nhân ở gần bạn","Dừng lại và chờ tới khi người cầm biển cho bạn đi"],"h1":"Người cầm biển đang điều khiển giao thông giống như đèn tín hiệu.","h2":"Biển “STOP” của người cầm biển có hiệu lực giống như biển dừng, nên bạn phải dừng lại và chờ tới khi người đó ra hiệu cho bạn đi.","p":"Đúng rồi. Hãy làm theo người cầm biển và chờ hiệu lệnh cho đi."},"tl":{"q":"Sa work zone, may flagger na nakaharap sa iyo ang hawak na “STOP” na paddle. Ano ang dapat mong gawin?","o":["Bumagal at lumihis paikot sa flagger","Bumusina at magpatuloy nang dahan-dahan","Huminto lang kung malapit sa iyo ang mga trabahador","Huminto at maghintay hanggang payagan ka ng flagger na umandar"],"h1":"Ang flagger ay nagdidirekta ng trapiko na parang ilaw trapiko.","h2":"Ang “STOP” na paddle ng flagger ay may parehong bisa ng “STOP” sign, kaya dapat kang huminto at maghintay hanggang senyasan ka ng flagger na umandar.","p":"Tama. Sundin ang flagger at hintayin ang senyas na umandar."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يرفع نحوك لوحة «STOP» (قف). ماذا يجب أن تفعل؟","o":["خفف السرعة وقُد حول العامل","استخدم البوق واستمر ببطء","توقف فقط إذا كان العمال قريبين منك","توقف وانتظر حتى يسمح لك العامل بالمرور"],"h1":"عامل تنظيم السير يوجّه السيارات مثل الإشارة الضوئية.","h2":"لوحة «STOP» التي يحملها عامل تنظيم السير لها نفس قوة لافتة «STOP»، لذلك يجب أن تتوقف وتنتظر حتى يشير لك العامل بالمرور.","p":"صحيح. أطِع عامل تنظيم السير وانتظر إشارته لتمر."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la kenbe yon pankat “STOP” bò kote ou. Kisa ou dwe fè?","o":["Ralanti epi pase bò kote travayè a","Klaksonen epi kontinye dousman","Kanpe sèlman si travayè yo toupre ou","Kanpe epi tann jiskaske travayè a kite ou pase"],"h1":"Travayè a ap dirije trafik la tankou yon limyè trafik.","h2":"Pankat “STOP” travayè a gen menm fòs ak yon siy “STOP”, kidonk ou dwe kanpe epi tann jiskaske travayè a fè ou siy pou pase.","p":"Se sa. Obeyi travayè a epi tann siyal pou pase a."},"ref":{"doc":"FL","page":54}},{"id":"signs-039","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"An orange sign says DETOUR. What does it mean?","o":["Follow the signs on a different route","The road is closed forever","Only trucks must leave the road","Park and wait for the road to open"],"h1":"A detour is a way around something.","h2":"A detour sign means the normal road is closed for now, so you follow the detour signs on another route.","p":"Right. Detour means follow the signs on another route."},"es":{"q":"Una señal anaranjada dice DETOUR (desvío). ¿Qué significa?","o":["Seguir las señales por otra ruta","La vía está cerrada para siempre","Solo los camiones deben salir de la vía","Estacionarse y esperar a que abran la vía"],"h1":"Un desvío es un camino para rodear algo.","h2":"Una señal de desvío quiere decir que la vía normal está cerrada por ahora, así que usted sigue las señales de desvío por otra ruta.","p":"Correcto. Desvío significa seguir las señales por otra ruta."},"zh":{"q":"一个橙色标志写着 “DETOUR”（绕行）。它是什么意思？","o":["按标志走另一条路线","这条路永远封了","只有卡车要离开这条路","停车等道路开放"],"h1":"绕行就是绕过某个地方的路。","h2":"绕行标志表示平常的路暂时封闭，所以你要按绕行标志走另一条路线。","p":"对。绕行表示按标志走另一条路线。"},"vi":{"q":"Một biển màu cam ghi “DETOUR” (Đường vòng). Biển này có nghĩa là gì?","o":["Đi theo các biển chỉ dẫn sang một đường khác","Con đường bị đóng vĩnh viễn","Chỉ xe tải phải rời khỏi đường","Đỗ xe và chờ đường mở lại"],"h1":"Đường vòng là cách đi vòng qua một chỗ nào đó.","h2":"Biển đường vòng nghĩa là đường bình thường đang tạm đóng, nên bạn đi theo các biển “DETOUR” sang một đường khác.","p":"Đúng rồi. Đường vòng nghĩa là đi theo biển chỉ dẫn sang đường khác."},"tl":{"q":"Nakasulat sa orange na karatula ang “DETOUR” (Lihis na daan). Ano ang ibig sabihin nito?","o":["Sundan ang mga karatula sa ibang ruta","Sarado na ang kalsada habambuhay","Mga trak lang ang dapat umalis sa kalsada","Pumarada at hintaying magbukas ang kalsada"],"h1":"Ang detour ay isang paraan para makaiwas o makadaan paikot sa isang bagay.","h2":"Ang “DETOUR” na karatula ay nangangahulugang sarado muna ang karaniwang daan, kaya susundan mo ang mga karatula ng detour sa ibang ruta.","p":"Tama. Ang “DETOUR” ay nangangahulugang sundan ang mga karatula sa ibang ruta."},"ar":{"q":"لافتة برتقالية مكتوب عليها «DETOUR» (تحويلة). ماذا تعني؟","o":["اتبع اللافتات على طريق مختلف","الطريق مغلق إلى الأبد","الشاحنات فقط يجب أن تخرج من الطريق","أوقف السيارة وانتظر حتى يُفتح الطريق"],"h1":"التحويلة طريق يلتف حول شيء ما.","h2":"لافتة التحويلة تعني أن الطريق العادي مغلق الآن، لذلك تتبع لافتات التحويلة على طريق آخر.","p":"صحيح. التحويلة تعني: اتبع اللافتات على طريق آخر."},"ht":{"q":"Yon siy zoranj di “DETOUR” (devyasyon). Kisa li vle di?","o":["Swiv siy yo sou yon lòt wout","Wout la fèmen pou toutan","Se sèlman kamyon ki dwe kite wout la","Pake epi tann wout la louvri"],"h1":"Yon devyasyon se yon fason pou fè wonn yon bagay.","h2":"Yon siy “DETOUR” vle di wout nòmal la fèmen pou kounye a, kidonk ou swiv siy devyasyon yo sou yon lòt wout.","p":"Se sa. “DETOUR” vle di swiv siy yo sou yon lòt wout."}},{"id":"signs-040","scope":"FL","cat":"signs","sign":null,"c":1,"en":{"q":"In Florida, what happens to a speeding fine in a work zone when workers are there?","o":["It is cut in half","It is doubled","It stays the same","It becomes only a warning"],"h1":"Florida wants to protect the people working on the road.","h2":"In Florida, the fine for speeding in a work zone is doubled when workers are present, because workers near traffic are at great risk.","p":"Right. Speeding fines double in a work zone with workers present."},"es":{"q":"En Florida, ¿qué pasa con la multa por exceso de velocidad en una zona de obras cuando hay trabajadores?","o":["Se reduce a la mitad","Se duplica","Se queda igual","Se vuelve solo una advertencia"],"h1":"Florida quiere proteger a las personas que trabajan en la vía.","h2":"En Florida, la multa por exceso de velocidad en una zona de obras se duplica cuando hay trabajadores presentes, porque los trabajadores cerca del tráfico corren mucho peligro.","p":"Correcto. La multa por velocidad se duplica en zona de obras con trabajadores."},"zh":{"q":"在 Florida，有工人在场时，在施工区超速的罚款会怎样？","o":["减半","加倍","不变","只给警告"],"h1":"Florida 想保护在路上工作的人。","h2":"在 Florida，有工人在场时，在施工区超速的罚款会加倍，因为在车流旁边工作的工人非常危险。","p":"对。有工人在场时，施工区超速罚款加倍。"},"vi":{"q":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công sẽ ra sao khi có công nhân ở đó?","o":["Giảm một nửa","Tăng gấp đôi","Giữ nguyên","Chỉ bị cảnh cáo"],"h1":"Florida muốn bảo vệ những người đang làm việc trên đường.","h2":"Ở Florida, tiền phạt chạy quá tốc độ trong khu vực thi công bị tăng gấp đôi khi có công nhân, vì công nhân làm việc gần xe chạy rất nguy hiểm.","p":"Đúng rồi. Tiền phạt quá tốc độ tăng gấp đôi trong khu vực thi công có công nhân."},"tl":{"q":"Sa Florida, ano ang nangyayari sa multa sa sobrang bilis sa work zone kapag may mga trabahador doon?","o":["Nababawasan ito ng kalahati","Nadodoble ito","Nananatili itong pareho","Nagiging babala lang ito"],"h1":"Gustong protektahan ng Florida ang mga taong nagtatrabaho sa kalsada.","h2":"Sa Florida, nadodoble ang multa sa sobrang bilis sa work zone kapag may mga trabahador, dahil malaki ang panganib sa mga trabahador na malapit sa trapiko.","p":"Tama. Nadodoble ang multa sa sobrang bilis sa work zone na may mga trabahador."},"ar":{"q":"في Florida، ماذا يحدث لغرامة السرعة في منطقة عمل عندما يكون العمال موجودين؟","o":["تُخفض إلى النصف","تُضاعف","تبقى كما هي","تصبح مجرد تحذير"],"h1":"Florida تريد أن تحمي الأشخاص الذين يعملون على الطريق.","h2":"في Florida، تُضاعف غرامة السرعة في منطقة العمل عندما يكون العمال موجودين، لأن العمال القريبين من السيارات في خطر كبير.","p":"صحيح. غرامات السرعة تُضاعف في منطقة العمل عندما يكون العمال موجودين."},"ht":{"q":"Nan Florida, kisa k ap pase ak amann pou vitès nan yon zòn travay lè gen travayè la?","o":["Li diminye mwatye","Li double","Li rete menm jan an","Li vin yon avètisman sèlman"],"h1":"Florida vle pwoteje moun k ap travay sou wout la.","h2":"Nan Florida, amann pou vitès nan yon zòn travay double lè gen travayè la, paske travayè ki toupre machin yo an gwo danje.","p":"Se sa. Amann pou vitès double nan yon zòn travay lè gen travayè la."},"ref":{"doc":"FL","page":29}},{"id":"signs-041","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":2,"en":{"q":"What kind of road does a blue and red shield with a number mark?","o":["A state park road","A private toll road","An Interstate highway","A county road"],"h1":"This shield is used across the whole country.","h2":"The blue and red shield marks an Interstate highway, which is part of the national highway system.","p":"Right. The blue and red shield marks an Interstate."},"es":{"q":"¿Qué tipo de vía marca un escudo azul y rojo con un número?","o":["Una vía de parque estatal","Una vía privada de peaje","Una autopista interestatal","Una vía del condado"],"h1":"Este escudo se usa en todo el país.","h2":"El escudo azul y rojo marca una autopista interestatal, que es parte del sistema nacional de carreteras.","p":"Correcto. El escudo azul y rojo marca una interestatal."},"zh":{"q":"带数字的蓝红色盾形标志表示哪种道路？","o":["州立公园道路","私人收费公路","州际公路（Interstate）","县级公路"],"h1":"这种盾形标志在全国都用。","h2":"蓝红色盾形标志表示州际公路（Interstate），它是全国公路系统的一部分。","p":"对。蓝红色盾形标志表示州际公路。"},"vi":{"q":"Tấm khiên màu xanh dương và đỏ có ghi số đánh dấu loại đường nào?","o":["Đường trong công viên của tiểu bang","Đường thu phí tư nhân","Đường cao tốc liên bang (Interstate)","Đường của quận"],"h1":"Tấm khiên này được dùng trên khắp cả nước.","h2":"Tấm khiên xanh dương và đỏ đánh dấu đường cao tốc liên bang (Interstate), là một phần của hệ thống đường cao tốc quốc gia.","p":"Đúng rồi. Tấm khiên xanh dương và đỏ đánh dấu đường Interstate."},"tl":{"q":"Anong uri ng kalsada ang minamarkahan ng asul at pulang kalasag na may numero?","o":["Daan sa parke ng estado","Pribadong toll road","Interstate highway","Daan ng county"],"h1":"Ginagamit ang kalasag na ito sa buong bansa.","h2":"Ang asul at pulang kalasag ay nagmamarka ng Interstate highway, na bahagi ng pambansang sistema ng mga highway.","p":"Tama. Ang asul at pulang kalasag ay nagmamarka ng Interstate."},"ar":{"q":"أي نوع من الطرق يدل عليه درع أزرق وأحمر عليه رقم؟","o":["طريق حديقة تابعة للولاية","طريق خاص برسوم","طريق سريع بين الولايات (Interstate)","طريق تابع للمقاطعة"],"h1":"هذا الدرع يُستخدم في البلد كله.","h2":"الدرع الأزرق والأحمر يدل على طريق سريع بين الولايات (Interstate)، وهو جزء من شبكة الطرق السريعة الوطنية.","p":"صحيح. الدرع الأزرق والأحمر يدل على طريق Interstate."},"ht":{"q":"Ki kalite wout yon plak ble ak wouj ki gen yon nimewo make?","o":["Yon wout pak eta","Yon wout prive ki gen peyaj","Yon gran wout Interstate","Yon wout konte"],"h1":"Yo sèvi ak plak sa a nan tout peyi a.","h2":"Plak ble ak wouj la make yon gran wout Interstate, ki fè pati sistèm gran wout nasyonal la.","p":"Se sa. Plak ble ak wouj la make yon Interstate."}},{"id":"signs-042","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"95"},"c":3,"en":{"q":"Interstates with odd numbers, like I-95, usually run which way?","o":["East and west","In a loop around a city","Only inside one state","North and south"],"h1":"Odd and even numbers are used for two different directions.","h2":"Interstates with odd numbers usually run north and south, like I-95 along the east coast.","p":"Right. Odd numbers usually run north and south."},"es":{"q":"Las interestatales con número impar, como la I-95, ¿hacia dónde van normalmente?","o":["De este a oeste","En círculo alrededor de una ciudad","Solo dentro de un estado","De norte a sur"],"h1":"Los números pares e impares se usan para dos direcciones diferentes.","h2":"Las interestatales con número impar normalmente van de norte a sur, como la I-95 por la costa este.","p":"Correcto. Los números impares normalmente van de norte a sur."},"zh":{"q":"编号是单数的州际公路，比如 I-95，通常是什么走向？","o":["东西走向","绕着城市一圈","只在一个州里面","南北走向"],"h1":"单数和双数用于两个不同的方向。","h2":"编号是单数的州际公路通常是南北走向，比如沿着东海岸的 I-95。","p":"对。单数编号通常是南北走向。"},"vi":{"q":"Đường Interstate có số lẻ, như I-95, thường chạy theo hướng nào?","o":["Đông và tây","Vòng quanh một thành phố","Chỉ trong một tiểu bang","Bắc và nam"],"h1":"Số lẻ và số chẵn được dùng cho hai hướng khác nhau.","h2":"Đường Interstate có số lẻ thường chạy theo hướng bắc và nam, như I-95 dọc bờ biển phía đông.","p":"Đúng rồi. Số lẻ thường chạy theo hướng bắc và nam."},"tl":{"q":"Ang mga Interstate na may odd na numero, tulad ng I-95, ay karaniwang papunta sa aling direksyon?","o":["Silangan at kanluran","Paikot sa isang lungsod","Sa loob lang ng isang estado","Hilaga at timog"],"h1":"Ginagamit ang odd at even na numero para sa dalawang magkaibang direksyon.","h2":"Ang mga Interstate na may odd na numero ay karaniwang papunta sa hilaga at timog, tulad ng I-95 sa kahabaan ng silangang baybayin.","p":"Tama. Ang odd na numero ay karaniwang papunta sa hilaga at timog."},"ar":{"q":"طرق Interstate ذات الأرقام الفردية، مثل I-95، في أي اتجاه تمتد عادةً؟","o":["من الشرق إلى الغرب","في دائرة حول مدينة","داخل ولاية واحدة فقط","من الشمال إلى الجنوب"],"h1":"الأرقام الفردية والزوجية تُستخدم لاتجاهين مختلفين.","h2":"طرق Interstate ذات الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب، مثل I-95 على طول الساحل الشرقي.","p":"صحيح. الأرقام الفردية تمتد عادةً من الشمال إلى الجنوب."},"ht":{"q":"Interstate ki gen nimewo enpè, tankou I-95, nan ki direksyon yo konn ale?","o":["Lès ak lwès","An wonn alantou yon vil","Sèlman andedan yon sèl eta","Nò ak sid"],"h1":"Nimewo enpè ak nimewo pè sèvi pou de direksyon diferan.","h2":"Interstate ki gen nimewo enpè yo konn ale nò ak sid, tankou I-95 sou kòt lès la.","p":"Se sa. Nimewo enpè yo konn ale nò ak sid."},"ref":{"doc":"FL","page":46}},{"id":"signs-043","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"10"},"c":0,"en":{"q":"I-10 has an even number. Which way does it usually run?","o":["East and west","North and south","Around a city","Along the coast only"],"h1":"Even and odd numbers go in different directions.","h2":"Interstates with even numbers usually run east and west, like I-10 across north Florida.","p":"Right. Even numbers usually run east and west."},"es":{"q":"La I-10 tiene un número par. ¿Hacia dónde va normalmente?","o":["De este a oeste","De norte a sur","Alrededor de una ciudad","Solo por la costa"],"h1":"Los números pares e impares van en direcciones distintas.","h2":"Las interestatales con número par normalmente van de este a oeste, como la I-10 por el norte de Florida.","p":"Correcto. Los números pares normalmente van de este a oeste."},"zh":{"q":"I-10 的编号是双数。它通常是什么走向？","o":["东西走向","南北走向","绕着城市","只沿着海岸"],"h1":"双数和单数代表不同的方向。","h2":"编号是双数的州际公路通常是东西走向，比如横穿 Florida 北部的 I-10。","p":"对。双数编号通常是东西走向。"},"vi":{"q":"I-10 có số chẵn. Đường này thường chạy theo hướng nào?","o":["Đông và tây","Bắc và nam","Vòng quanh một thành phố","Chỉ dọc theo bờ biển"],"h1":"Số chẵn và số lẻ chạy theo những hướng khác nhau.","h2":"Đường Interstate có số chẵn thường chạy theo hướng đông và tây, như I-10 băng ngang miền bắc Florida.","p":"Đúng rồi. Số chẵn thường chạy theo hướng đông và tây."},"tl":{"q":"Ang I-10 ay may even na numero. Saang direksyon ito karaniwang papunta?","o":["Silangan at kanluran","Hilaga at timog","Paikot sa isang lungsod","Sa kahabaan lang ng baybayin"],"h1":"Ang even at odd na numero ay papunta sa magkaibang direksyon.","h2":"Ang mga Interstate na may even na numero ay karaniwang papunta sa silangan at kanluran, tulad ng I-10 na tumatawid sa hilagang Florida.","p":"Tama. Ang even na numero ay karaniwang papunta sa silangan at kanluran."},"ar":{"q":"الطريق I-10 رقمه زوجي. في أي اتجاه يمتد عادةً؟","o":["من الشرق إلى الغرب","من الشمال إلى الجنوب","حول مدينة","على طول الساحل فقط"],"h1":"الأرقام الزوجية والفردية تسير في اتجاهات مختلفة.","h2":"طرق Interstate ذات الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب، مثل I-10 عبر شمال Florida.","p":"صحيح. الأرقام الزوجية تمتد عادةً من الشرق إلى الغرب."},"ht":{"q":"I-10 gen yon nimewo pè. Nan ki direksyon li konn ale?","o":["Lès ak lwès","Nò ak sid","Alantou yon vil","Sèlman bò lanmè a"],"h1":"Nimewo pè ak nimewo enpè ale nan direksyon diferan.","h2":"Interstate ki gen nimewo pè yo konn ale lès ak lwès, tankou I-10 ki travèse nò Florida.","p":"Se sa. Nimewo pè yo konn ale lès ak lwès."},"ref":{"doc":"FL","page":46}},{"id":"signs-045","scope":"FL","cat":"signs","sign":{"shape":"rect-green","text":"EXIT"},"c":2,"en":{"q":"In Florida, how are exit numbers on Interstates chosen?","o":["In order, 1, 2, 3, from the state line","By the name of the nearest city","By the nearest mile marker","By the number of the crossing road"],"h1":"Think about the small green signs that count the miles.","h2":"In Florida, Interstate exit numbers match the nearest mile marker, so the exit number also tells you about how far you are along the road.","p":"Right. Florida exit numbers follow the mile markers."},"es":{"q":"En Florida, ¿cómo se escogen los números de salida en las interestatales?","o":["En orden, 1, 2, 3, desde la frontera del estado","Por el nombre de la ciudad más cercana","Por el marcador de milla más cercano","Por el número de la vía que cruza"],"h1":"Piense en las señales verdes pequeñas que cuentan las millas.","h2":"En Florida, los números de salida en las interestatales corresponden al marcador de milla más cercano, así que el número de salida también le dice más o menos qué tan lejos va en la vía.","p":"Correcto. En Florida, los números de salida siguen los marcadores de milla."},"zh":{"q":"在 Florida，州际公路的出口编号是怎么定的？","o":["从州界开始按 1、2、3 排列","按最近城市的名字","按最近的里程标","按交叉道路的编号"],"h1":"想一想计算英里数的绿色小标志。","h2":"在 Florida，州际公路的出口编号和最近的里程标一致，所以出口编号也告诉你大约在这条路上走了多远。","p":"对。Florida 的出口编号按里程标来定。"},"vi":{"q":"Ở Florida, số lối ra trên đường Interstate được đặt như thế nào?","o":["Theo thứ tự 1, 2, 3, tính từ ranh giới tiểu bang","Theo tên thành phố gần nhất","Theo cột mốc dặm gần nhất","Theo số của con đường cắt ngang"],"h1":"Hãy nghĩ đến những biển nhỏ màu xanh lá cây đếm số dặm.","h2":"Ở Florida, số lối ra trên đường Interstate trùng với cột mốc dặm gần nhất, nên số lối ra cũng cho bạn biết khoảng bao xa bạn đã đi trên con đường đó.","p":"Đúng rồi. Số lối ra ở Florida theo các cột mốc dặm."},"tl":{"q":"Sa Florida, paano pinipili ang mga numero ng exit sa mga Interstate?","o":["Sunod-sunod, 1, 2, 3, mula sa hangganan ng estado","Ayon sa pangalan ng pinakamalapit na lungsod","Ayon sa pinakamalapit na mile marker","Ayon sa numero ng kalsadang tumatawid"],"h1":"Isipin ang maliliit na berdeng karatula na nagbibilang ng milya.","h2":"Sa Florida, ang numero ng exit sa Interstate ay tugma sa pinakamalapit na mile marker, kaya sinasabi rin ng numero ng exit kung humigit-kumulang gaano na kalayo ang narating mo sa kalsada.","p":"Tama. Sinusunod ng mga numero ng exit sa Florida ang mga mile marker."},"ar":{"q":"في Florida، كيف تُختار أرقام المخارج على طرق Interstate؟","o":["بالترتيب، 1، 2، 3، من حدود الولاية","حسب اسم أقرب مدينة","حسب أقرب علامة ميل","حسب رقم الطريق الذي يتقاطع معه"],"h1":"فكّر في اللافتات الخضراء الصغيرة التي تعدّ الأميال.","h2":"في Florida، أرقام المخارج على طرق Interstate تطابق أقرب علامة ميل، لذلك رقم المخرج يخبرك أيضًا تقريبًا بالمسافة التي قطعتها على الطريق.","p":"صحيح. أرقام المخارج في Florida تتبع علامات الأميال."},"ht":{"q":"Nan Florida, ki jan yo chwazi nimewo sòti yo sou Interstate yo?","o":["Youn apre lòt, 1, 2, 3, depi fwontyè eta a","Dapre non vil ki pi pre a","Dapre ti siy mil ki pi pre a","Dapre nimewo wout ki travèse a"],"h1":"Panse ak ti siy vèt ki konte mil yo.","h2":"Nan Florida, nimewo sòti Interstate yo menm ak ti siy mil ki pi pre a, kidonk nimewo sòti a di ou apeprè ki distans ou fè sou wout la.","p":"Se sa. Nimewo sòti Florida yo swiv ti siy mil yo."},"ref":{"doc":"FL","page":46}},{"id":"signs-046","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"MILE 120"},"c":3,"en":{"q":"How do small green mile marker signs help you?","o":["They show the speed limit","They point to gas stations","They tell you where to pay tolls","They tell your location in an emergency"],"h1":"Think about what you would tell a 911 operator.","h2":"Mile markers show where you are on the highway, so you can tell emergency helpers your exact location.","p":"Right. Mile markers help you tell where you are."},"es":{"q":"¿Cómo le ayudan las señales verdes pequeñas de marcador de milla?","o":["Muestran el límite de velocidad","Indican dónde hay gasolineras","Le dicen dónde pagar el peaje","Le ayudan a decir dónde está en una emergencia"],"h1":"Piense en lo que le diría a la operadora del 911.","h2":"Los marcadores de milla muestran dónde está usted en la carretera, así que puede decirle a la ayuda de emergencia su ubicación exacta.","p":"Correcto. Los marcadores de milla le ayudan a decir dónde está."},"zh":{"q":"绿色的小里程标对你有什么帮助？","o":["它们显示限速","它们指向加油站","它们告诉你在哪里付过路费","在紧急情况下，它们告诉你在哪里"],"h1":"想一想你会告诉 911 接线员什么。","h2":"里程标显示你在公路上的位置，所以你能把准确位置告诉急救人员。","p":"对。里程标帮你说出你在哪里。"},"vi":{"q":"Những biển nhỏ màu xanh lá cây ghi cột mốc dặm giúp bạn thế nào?","o":["Cho biết giới hạn tốc độ","Chỉ tới trạm xăng","Cho biết chỗ trả phí đường","Cho biết vị trí của bạn khi có trường hợp khẩn cấp"],"h1":"Hãy nghĩ xem bạn sẽ nói gì với người trực tổng đài 911.","h2":"Cột mốc dặm cho biết bạn đang ở đâu trên đường cao tốc, nên bạn có thể nói cho người cứu hộ biết chính xác vị trí của bạn.","p":"Đúng rồi. Cột mốc dặm giúp bạn nói được mình đang ở đâu."},"tl":{"q":"Paano ka natutulungan ng maliliit na berdeng karatula ng mile marker?","o":["Ipinapakita nila ang speed limit","Itinuturo nila ang mga gasolinahan","Sinasabi nila kung saan magbabayad ng toll","Sinasabi nila ang lokasyon mo kapag may emergency"],"h1":"Isipin kung ano ang sasabihin mo sa operator ng 911.","h2":"Ipinapakita ng mga mile marker kung nasaan ka sa highway, kaya masasabi mo sa mga tagatulong sa emergency ang eksaktong lokasyon mo.","p":"Tama. Tinutulungan ka ng mga mile marker na sabihin kung nasaan ka."},"ar":{"q":"كيف تساعدك لافتات علامات الأميال الخضراء الصغيرة؟","o":["تُظهر حد السرعة","تدلّك على محطات الوقود","تخبرك أين تدفع رسوم الطريق","تخبرك بمكانك في حالة الطوارئ"],"h1":"فكّر في ما ستقوله لموظف الطوارئ على الرقم 911.","h2":"علامات الأميال تُظهر مكانك على الطريق السريع، لذلك تستطيع أن تخبر فرق الطوارئ بمكانك بالضبط.","p":"صحيح. علامات الأميال تساعدك على معرفة مكانك."},"ht":{"q":"Ki jan ti siy mil vèt yo ede ou?","o":["Yo montre limit vitès la","Yo montre kote estasyon gaz yo ye","Yo di ou ki kote pou peye peyaj","Yo di ki kote ou ye lè gen yon ijans"],"h1":"Panse ak sa ou ta di yon moun nan 911.","h2":"Ti siy mil yo montre ki kote ou ye sou gran wout la, kidonk ou ka di moun k ap vin ede ou nan yon ijans kote egzak ou ye.","p":"Se sa. Ti siy mil yo ede ou di ki kote ou ye."},"ref":{"doc":"FL","page":46}},{"id":"signs-047","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"H"},"c":0,"en":{"q":"A blue sign shows a big white letter H. What does it mean?","o":["A hospital is nearby","A hotel is nearby","A helicopter pad is nearby","The highway ends here"],"h1":"Blue signs show services you may need.","h2":"A blue sign with a white H points to a hospital, so you can find medical help nearby.","p":"Right. The blue H sign means a hospital is near."},"es":{"q":"Una señal azul muestra una letra H grande y blanca. ¿Qué significa?","o":["Hay un hospital cerca","Hay un hotel cerca","Hay un helipuerto cerca","La autopista termina aquí"],"h1":"Las señales azules muestran servicios que podría necesitar.","h2":"Una señal azul con una H blanca indica un hospital, así que usted puede encontrar ayuda médica cerca.","p":"Correcto. La señal azul con H significa que hay un hospital cerca."},"zh":{"q":"一个蓝色标志上有一个很大的白色字母 H。它是什么意思？","o":["附近有医院","附近有酒店","附近有直升机停机坪","公路到这里结束"],"h1":"蓝色标志告诉你可能需要的服务。","h2":"有白色字母 H 的蓝色标志指向医院，所以你能在附近找到医疗帮助。","p":"对。蓝色 H 标志表示附近有医院。"},"vi":{"q":"Một biển màu xanh dương có chữ H lớn màu trắng. Biển này có nghĩa là gì?","o":["Gần đây có bệnh viện","Gần đây có khách sạn","Gần đây có bãi đáp trực thăng","Đường cao tốc kết thúc ở đây"],"h1":"Biển màu xanh dương cho biết những dịch vụ bạn có thể cần.","h2":"Biển màu xanh dương có chữ H trắng chỉ tới bệnh viện, để bạn tìm được chỗ chữa bệnh gần đó.","p":"Đúng rồi. Biển chữ H màu xanh dương nghĩa là gần đây có bệnh viện."},"tl":{"q":"Ang asul na karatula ay nagpapakita ng malaking puting letrang H. Ano ang ibig sabihin nito?","o":["May ospital sa malapit","May hotel sa malapit","May helipad sa malapit","Dito natatapos ang highway"],"h1":"Ang mga asul na karatula ay nagpapakita ng mga serbisyong maaaring kailanganin mo.","h2":"Ang asul na karatula na may puting H ay nagtuturo sa ospital, kaya makakahanap ka ng tulong medikal sa malapit.","p":"Tama. Ang asul na karatulang H ay nangangahulugang may ospital sa malapit."},"ar":{"q":"لافتة زرقاء عليها حرف H أبيض كبير. ماذا تعني؟","o":["مستشفى قريب","فندق قريب","مهبط طائرات مروحية قريب","الطريق السريع ينتهي هنا"],"h1":"اللافتات الزرقاء تُظهر خدمات قد تحتاجها.","h2":"اللافتة الزرقاء التي عليها حرف H أبيض ترشدك إلى مستشفى، لكي تجد مساعدة طبية قريبة.","p":"صحيح. لافتة H الزرقاء تعني أن هناك مستشفى قريبًا."},"ht":{"q":"Yon siy ble montre yon gwo lèt H blan. Kisa li vle di?","o":["Gen yon lopital toupre","Gen yon otèl toupre","Gen yon kote elikoptè ateri toupre","Gran wout la fini la a"],"h1":"Siy ble yo montre sèvis ou ka bezwen.","h2":"Yon siy ble ak yon H blan montre yon lopital, kidonk ou ka jwenn swen medikal toupre.","p":"Se sa. Siy ble ak H la vle di gen yon lopital toupre."},"ref":{"doc":"FL","page":46}},{"id":"signs-048","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"On traffic signs, what does the color red usually mean?","o":["A warning about the road ahead","Stop, yield, or something is not allowed","Directions to a place","Services like gas and food"],"h1":"Think of the stop sign and the do not enter sign.","h2":"Red on a sign usually means stop, yield, or that something is not allowed, like on the stop sign and the do not enter sign.","p":"Right. Red means stop, yield, or not allowed."},"es":{"q":"En las señales de tránsito, ¿qué significa normalmente el color rojo?","o":["Un aviso sobre la vía más adelante","Pare, ceda el paso o algo no está permitido","Direcciones hacia un lugar","Servicios como gasolina y comida"],"h1":"Piense en la señal de pare y en la de no entre.","h2":"El rojo en una señal normalmente quiere decir pare, ceda el paso o que algo no está permitido, como en la señal de pare y la de no entre.","p":"Correcto. El rojo significa pare, ceda el paso o no está permitido."},"zh":{"q":"在交通标志上，红色通常表示什么？","o":["提醒前方道路的情况","停车、让行，或某件事不允许","去某个地方的方向","加油、吃饭等服务"],"h1":"想一想停车标志和禁止驶入标志。","h2":"标志上的红色通常表示停车、让行，或某件事不允许，比如停车标志和禁止驶入标志。","p":"对。红色表示停车、让行或不允许。"},"vi":{"q":"Trên biển báo giao thông, màu đỏ thường có nghĩa là gì?","o":["Cảnh báo về con đường phía trước","Dừng lại, nhường đường, hoặc có điều gì đó bị cấm","Chỉ đường tới một nơi","Dịch vụ như xăng và đồ ăn"],"h1":"Hãy nghĩ đến biển dừng và biển cấm đi vào.","h2":"Màu đỏ trên biển báo thường có nghĩa là dừng lại, nhường đường, hoặc có điều gì đó bị cấm, như trên biển “STOP” và biển “DO NOT ENTER”.","p":"Đúng rồi. Màu đỏ nghĩa là dừng lại, nhường đường, hoặc bị cấm."},"tl":{"q":"Sa mga karatula ng trapiko, ano ang karaniwang ibig sabihin ng kulay pula?","o":["Babala tungkol sa kalsada sa unahan","Huminto, magbigay-daan, o may bagay na hindi pinapayagan","Direksyon papunta sa isang lugar","Mga serbisyo tulad ng gasolina at pagkain"],"h1":"Isipin ang “STOP” sign at ang “DO NOT ENTER” sign.","h2":"Ang pula sa karatula ay karaniwang nangangahulugang huminto, magbigay-daan, o may bagay na hindi pinapayagan, tulad ng sa “STOP” sign at sa “DO NOT ENTER” sign.","p":"Tama. Ang pula ay nangangahulugang huminto, magbigay-daan, o hindi pinapayagan."},"ar":{"q":"على لافتات المرور، ماذا يعني اللون الأحمر عادةً؟","o":["تحذير من الطريق في الأمام","قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع","الاتجاه إلى مكان ما","خدمات مثل الوقود والطعام"],"h1":"فكّر في لافتة «STOP» ولافتة «DO NOT ENTER».","h2":"اللون الأحمر على اللافتة يعني عادةً قف، أو أعطِ الأولوية، أو أن شيئًا ممنوع، مثل لافتة «STOP» (قف) ولافتة «DO NOT ENTER» (ممنوع الدخول).","p":"صحيح. الأحمر يعني قف، أو أعطِ الأولوية، أو ممنوع."},"ht":{"q":"Sou siy trafik yo, kisa koulè wouj la konn vle di?","o":["Yon avètisman sou wout la pi devan","Kanpe, bay pasaj, oswa yon bagay ki pa pèmèt","Direksyon pou yon kote","Sèvis tankou gaz ak manje"],"h1":"Panse ak siy “STOP” la ak siy “DO NOT ENTER” la.","h2":"Wouj sou yon siy konn vle di kanpe, bay pasaj, oswa yon bagay ki pa pèmèt, tankou sou siy “STOP” la ak siy “DO NOT ENTER” la.","p":"Se sa. Wouj vle di kanpe, bay pasaj, oswa sa pa pèmèt."},"ref":{"doc":"FL","page":46}},{"id":"signs-049","scope":"US","cat":"signs","sign":{"shape":"diamond-ygreen","text":"PEDESTRIAN"},"c":2,"en":{"q":"A bright yellow-green sign shows a person walking. What should you watch for?","o":["People on bicycles only","Animals crossing","People crossing the road","Road workers"],"h1":"Look at the picture on the sign.","h2":"A yellow-green sign with a walking person warns that people may be crossing the road, so slow down and be ready to stop for them.","p":"Right. Watch for people crossing the road."},"es":{"q":"Una señal verde amarillenta brillante muestra a una persona caminando. ¿A qué debe estar atento?","o":["Solo a personas en bicicleta","A animales cruzando","A personas cruzando la vía","A trabajadores de la vía"],"h1":"Mire el dibujo en la señal.","h2":"Una señal verde amarillenta con una persona caminando avisa que puede haber personas cruzando la vía, así que baje la velocidad y esté listo para pararse por ellas.","p":"Correcto. Esté atento a personas cruzando la vía."},"zh":{"q":"一个亮黄绿色标志上画着一个走路的人。你应该注意什么？","o":["只注意骑自行车的人","动物过马路","行人过马路","道路工人"],"h1":"看看标志上的图。","h2":"画着走路的人的黄绿色标志提醒你可能有行人过马路，所以要减速，准备为他们停车。","p":"对。注意过马路的行人。"},"vi":{"q":"Một biển màu vàng chanh có hình người đang đi bộ. Bạn nên chú ý điều gì?","o":["Chỉ người đi xe đạp","Thú vật băng qua đường","Người đi bộ băng qua đường","Công nhân sửa đường"],"h1":"Hãy nhìn hình vẽ trên biển.","h2":"Biển màu vàng chanh có hình người đi bộ cảnh báo rằng có thể có người băng qua đường, nên bạn cần chạy chậm lại và sẵn sàng dừng cho họ.","p":"Đúng rồi. Hãy chú ý người đi bộ băng qua đường."},"tl":{"q":"Ang matingkad na dilaw-berdeng karatula ay nagpapakita ng taong naglalakad. Ano ang dapat mong bantayan?","o":["Mga taong nakabisikleta lang","Mga hayop na tumatawid","Mga taong tumatawid sa kalsada","Mga trabahador sa kalsada"],"h1":"Tingnan ang larawan sa karatula.","h2":"Ang dilaw-berdeng karatula na may taong naglalakad ay babala na maaaring may mga taong tumatawid sa kalsada, kaya bumagal at maging handang huminto para sa kanila.","p":"Tama. Mag-ingat sa mga taong tumatawid sa kalsada."},"ar":{"q":"لافتة بلون أصفر مخضر لامع تُظهر شخصًا يمشي. ما الذي يجب أن تنتبه له؟","o":["أشخاص على الدراجات فقط","حيوانات تعبر","أشخاص يعبرون الطريق","عمال الطرق"],"h1":"انظر إلى الصورة على اللافتة.","h2":"اللافتة الصفراء المخضرة التي عليها شخص يمشي تحذّر من أن أشخاصًا قد يعبرون الطريق، لذلك خفف السرعة وكن مستعدًا للتوقف من أجلهم.","p":"صحيح. انتبه للأشخاص الذين يعبرون الطريق."},"ht":{"q":"Yon siy jòn-vèt klè montre yon moun k ap mache. Kisa ou dwe veye?","o":["Moun sou bisiklèt sèlman","Bèt k ap travèse","Moun k ap travèse wout la","Travayè sou wout la"],"h1":"Gade foto ki sou siy la.","h2":"Yon siy jòn-vèt ak yon moun k ap mache avèti ou ka gen moun k ap travèse wout la, kidonk ralanti epi pare pou kanpe pou yo.","p":"Se sa. Veye moun k ap travèse wout la."},"ref":{"doc":"FL","page":46}},{"id":"signs-050","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":2,"en":{"q":"A small plaque under a STOP sign says ALL WAY. What does it mean?","o":["Only drivers turning left must stop","You may go without stopping if the road is empty","Drivers coming from every direction must stop","The road ahead is closed in all directions"],"h1":"Think about who else sees a STOP sign at this corner.","h2":"An ALL WAY plaque means drivers from every direction at the intersection must stop, not just you.","p":"Right. ALL WAY means every direction stops."},"es":{"q":"Una placa pequeña debajo de una señal de PARE dice ALL WAY. ¿Qué significa?","o":["Solo deben pararse los que van a girar a la izquierda","Puede seguir sin pararse si la vía está vacía","Los conductores que vienen de todas las direcciones deben pararse","La vía está cerrada en todas las direcciones"],"h1":"Piense en quién más ve una señal de PARE en esa esquina.","h2":"Una placa ALL WAY significa que los conductores de todas las direcciones en la intersección deben pararse, no solo usted.","p":"Correcto. ALL WAY significa que todas las direcciones se paran."},"zh":{"q":"停车标志下面有一块小牌子，写着 “ALL WAY”（全向）。这是什么意思？","o":["只有左转的司机必须停车","路上没车时，你可以不停车直接走","从每个方向来的司机都必须停车","前方道路所有方向都封闭"],"h1":"想一想：在这个路口，还有谁能看到停车标志。","h2":"“ALL WAY”（全向）小牌子表示，从路口每个方向来的司机都必须停车，不只是你。","p":"对。“ALL WAY” 表示每个方向都要停车。"},"vi":{"q":"Một tấm biển nhỏ dưới biển “STOP” ghi “ALL WAY” (Mọi hướng). Điều đó có nghĩa là gì?","o":["Chỉ tài xế rẽ trái mới phải dừng","Bạn có thể đi mà không dừng nếu đường trống","Tài xế từ mọi hướng đều phải dừng","Đường phía trước bị đóng ở mọi hướng"],"h1":"Hãy nghĩ xem còn ai khác thấy biển “STOP” ở góc đường này.","h2":"Tấm biển “ALL WAY” nghĩa là tài xế từ mọi hướng tại giao lộ đều phải dừng, không chỉ riêng bạn.","p":"Đúng rồi. “ALL WAY” nghĩa là mọi hướng đều phải dừng."},"tl":{"q":"May maliit na plaka sa ilalim ng “STOP” sign na nakasulat ang “ALL WAY” (Lahat ng direksyon). Ano ang ibig sabihin nito?","o":["Ang mga kakaliwa lang ang dapat huminto","Puwede kang dumiretso nang hindi humihinto kung maluwag ang daan","Dapat huminto ang mga drayber mula sa bawat direksyon","Sarado ang kalsada sa unahan sa lahat ng direksyon"],"h1":"Isipin kung sino pa ang nakakakita ng “STOP” sign sa kantong ito.","h2":"Ang “ALL WAY” na plaka ay nangangahulugang dapat huminto ang mga drayber mula sa bawat direksyon sa interseksyon, hindi lang ikaw.","p":"Tama. Ang “ALL WAY” ay nangangahulugang humihinto ang bawat direksyon."},"ar":{"q":"لوحة صغيرة تحت لافتة «STOP» (قف) مكتوب عليها «ALL WAY» (كل الاتجاهات). ماذا تعني؟","o":["السائقون الذين ينعطفون يسارًا فقط يجب أن يتوقفوا","يمكنك أن تمر دون توقف إذا كان الطريق خاليًا","السائقون القادمون من كل الاتجاهات يجب أن يتوقفوا","الطريق في الأمام مغلق في كل الاتجاهات"],"h1":"فكّر في من يرى لافتة «STOP» أيضًا عند هذا التقاطع.","h2":"لوحة «ALL WAY» تعني أن السائقين القادمين من كل اتجاه عند التقاطع يجب أن يتوقفوا، وليس أنت فقط.","p":"صحيح. «ALL WAY» تعني أن كل الاتجاهات تتوقف."},"ht":{"q":"Yon ti plak anba yon siy “STOP” (kanpe) di “ALL WAY” (tout direksyon). Kisa sa vle di?","o":["Se sèlman chofè k ap vire agoch ki dwe kanpe","Ou ka pase san kanpe si wout la lib","Chofè ki soti nan chak direksyon dwe kanpe","Wout la pi devan fèmen nan tout direksyon"],"h1":"Panse ak ki lòt moun ki wè yon siy “STOP” nan kafou sa a.","h2":"Yon plak “ALL WAY” vle di chofè ki soti nan chak direksyon nan entèseksyon an dwe kanpe, pa sèlman ou.","p":"Se sa. “ALL WAY” vle di chak direksyon kanpe."}},{"id":"signs-051","scope":"US","cat":"signs","sign":{"shape":"yield","text":"YIELD"},"c":3,"en":{"q":"At a narrow bridge, a YIELD sign has a plaque that says TO ONCOMING TRAFFIC. What should you do?","o":["Speed up to cross before other cars","Stop only if a truck is coming","Honk and then cross","Let cars coming toward you cross first"],"h1":"Oncoming traffic is coming toward you.","h2":"The plaque TO ONCOMING TRAFFIC means you must let vehicles coming toward you cross the narrow spot first.","p":"Right. Let the oncoming cars go first."},"es":{"q":"En un puente angosto, una señal de CEDA EL PASO tiene una placa que dice TO ONCOMING TRAFFIC. ¿Qué debe hacer?","o":["Acelerar para cruzar antes que los demás","Pararse solo si viene un camión","Tocar la bocina y luego cruzar","Dejar que crucen primero los carros que vienen de frente"],"h1":"El tráfico \"oncoming\" es el que viene de frente hacia usted.","h2":"La placa TO ONCOMING TRAFFIC significa que usted debe dejar que los vehículos que vienen de frente crucen primero el paso angosto.","p":"Correcto. Deje pasar primero a los que vienen de frente."},"zh":{"q":"在一座窄桥前，让行标志下有一块牌子写着 “TO ONCOMING TRAFFIC”（让对面来车）。你应该怎么做？","o":["加速，抢在别的车前面过桥","只有卡车来时才停车","按喇叭，然后过桥","让对面开过来的车先过"],"h1":"对面来车是朝你开过来的车。","h2":"“TO ONCOMING TRAFFIC” 牌子表示，你必须让朝你开过来的车先通过窄的地方。","p":"对。让对面来车先走。"},"vi":{"q":"Ở một cây cầu hẹp, biển “YIELD” (Nhường đường) có tấm biển phụ ghi “TO ONCOMING TRAFFIC” (Cho xe chạy ngược chiều). Bạn nên làm gì?","o":["Tăng tốc để qua trước các xe khác","Chỉ dừng nếu có xe tải tới","Bấm còi rồi đi qua","Để các xe đang chạy về phía bạn qua trước"],"h1":"Xe ngược chiều là xe đang chạy về phía bạn.","h2":"Tấm biển “TO ONCOMING TRAFFIC” nghĩa là bạn phải để các xe đang chạy về phía bạn qua chỗ hẹp trước.","p":"Đúng rồi. Để xe ngược chiều đi trước."},"tl":{"q":"Sa isang makitid na tulay, may plaka ang “YIELD” sign (Magbigay-daan) na nakasulat ang “TO ONCOMING TRAFFIC” (Sa paparating na trapiko). Ano ang dapat mong gawin?","o":["Bumilis para makatawid bago ang ibang sasakyan","Huminto lang kung may paparating na trak","Bumusina at saka tumawid","Paunahin tumawid ang mga sasakyang papalapit sa iyo"],"h1":"Ang paparating na trapiko ay papalapit sa iyo.","h2":"Ang plakang “TO ONCOMING TRAFFIC” ay nangangahulugang dapat mong paunahin ang mga sasakyang papalapit sa iyo na tumawid sa makitid na bahagi.","p":"Tama. Paunahin ang mga paparating na sasakyan."},"ar":{"q":"عند جسر ضيق، تحت لافتة «YIELD» (أعطِ الأولوية) لوحة مكتوب عليها «TO ONCOMING TRAFFIC» (للسيارات القادمة من الأمام). ماذا يجب أن تفعل؟","o":["زد السرعة لتعبر قبل السيارات الأخرى","توقف فقط إذا جاءت شاحنة","استخدم البوق ثم اعبر","دع السيارات القادمة نحوك تعبر أولًا"],"h1":"السيارات القادمة من الأمام تأتي نحوك.","h2":"لوحة «TO ONCOMING TRAFFIC» تعني أنه يجب أن تترك السيارات القادمة نحوك تعبر المكان الضيق أولًا.","p":"صحيح. دع السيارات القادمة من الأمام تمر أولًا."},"ht":{"q":"Bò yon pon ki etwat, yon siy “YIELD” (bay pasaj) gen yon plak ki di “TO ONCOMING TRAFFIC” (bay machin k ap vin sou ou). Kisa ou dwe fè?","o":["Akselere pou travèse anvan lòt machin yo","Kanpe sèlman si yon kamyon ap vini","Klakonen epi travèse","Kite machin k ap vin sou ou yo travèse anvan"],"h1":"Machin k ap vin sou ou yo ap vini nan direksyon ou.","h2":"Plak “TO ONCOMING TRAFFIC” la vle di ou dwe kite machin k ap vin sou ou yo travèse kote ki etwat la anvan.","p":"Se sa. Kite machin k ap vin sou ou yo pase anvan."}},{"id":"signs-052","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"STOP HERE FOR PEDESTRIANS"},"c":0,"en":{"q":"A white sign says STOP HERE FOR PEDESTRIANS and points to a line before a crosswalk. When people are crossing, where do you stop?","o":["At the line the sign points to","In the middle of the crosswalk","Right next to the people crossing","After the crosswalk"],"h1":"The sign shows you the exact place.","h2":"When people are crossing, you stop at the line the STOP HERE FOR PEDESTRIANS sign points to, well before the crosswalk.","p":"Right. Stop at the line, before the crosswalk."},"es":{"q":"Una señal blanca dice STOP HERE FOR PEDESTRIANS y apunta a una línea antes de un cruce peatonal. Cuando hay personas cruzando, ¿dónde se para?","o":["En la línea que indica la señal","En el medio del cruce peatonal","Justo al lado de las personas que cruzan","Después del cruce peatonal"],"h1":"La señal le muestra el lugar exacto.","h2":"Cuando hay personas cruzando, usted se para en la línea que indica la señal STOP HERE FOR PEDESTRIANS, bien antes del cruce peatonal.","p":"Correcto. Párese en la línea, antes del cruce."},"zh":{"q":"一个白色标志写着 “STOP HERE FOR PEDESTRIANS”（在此为行人停车），并指向人行横道前的一条线。有人过马路时，你在哪里停车？","o":["在标志指向的那条线","在人行横道中间","紧挨着过马路的人","过了人行横道以后"],"h1":"标志告诉你停车的准确位置。","h2":"有人过马路时，你要在 “STOP HERE FOR PEDESTRIANS” 标志指向的那条线停车，离人行横道还有一段距离。","p":"对。在线前停车，在人行横道之前。"},"vi":{"q":"Một biển màu trắng ghi “STOP HERE FOR PEDESTRIANS” (Dừng ở đây cho người đi bộ) và chỉ vào một vạch trước lối qua đường. Khi có người đang qua đường, bạn dừng ở đâu?","o":["Ở vạch mà biển chỉ vào","Ở giữa lối qua đường","Ngay sát những người đang qua đường","Sau lối qua đường"],"h1":"Biển cho bạn biết chính xác chỗ dừng.","h2":"Khi có người đang qua đường, bạn dừng ở vạch mà biển “STOP HERE FOR PEDESTRIANS” chỉ vào, cách xa lối qua đường.","p":"Đúng rồi. Dừng ở vạch, trước lối qua đường."},"tl":{"q":"May puting karatula na nakasulat ang “STOP HERE FOR PEDESTRIANS” (Huminto rito para sa mga tumatawid) at nakaturo sa isang linya bago ang tawiran. Kapag may tumatawid, saan ka hihinto?","o":["Sa linyang itinuturo ng karatula","Sa gitna ng tawiran","Katabi mismo ng mga tumatawid","Pagkalampas ng tawiran"],"h1":"Ipinapakita sa iyo ng karatula ang eksaktong lugar.","h2":"Kapag may tumatawid, huminto ka sa linyang itinuturo ng “STOP HERE FOR PEDESTRIANS” na karatula, malayo pa bago ang tawiran.","p":"Tama. Huminto sa linya, bago ang tawiran."},"ar":{"q":"لافتة بيضاء مكتوب عليها «STOP HERE FOR PEDESTRIANS» (قف هنا للمشاة) وتشير إلى خط قبل ممر المشاة. عندما يعبر الناس، أين تتوقف؟","o":["عند الخط الذي تشير إليه اللافتة","في وسط ممر المشاة","بجانب الناس الذين يعبرون مباشرة","بعد ممر المشاة"],"h1":"اللافتة تُريك المكان بالضبط.","h2":"عندما يعبر الناس، تتوقف عند الخط الذي تشير إليه لافتة «STOP HERE FOR PEDESTRIANS»، قبل ممر المشاة بمسافة كافية.","p":"صحيح. توقف عند الخط، قبل ممر المشاة."},"ht":{"q":"Yon siy blan di “STOP HERE FOR PEDESTRIANS” (kanpe isit la pou pyeton) epi li montre yon liy anvan pasaj pyeton an. Lè gen moun k ap travèse, ki kote ou kanpe?","o":["Sou liy siy la montre a","Nan mitan pasaj pyeton an","Kole ak moun k ap travèse yo","Apre pasaj pyeton an"],"h1":"Siy la montre ou egzakteman ki kote.","h2":"Lè gen moun k ap travèse, ou kanpe sou liy siy “STOP HERE FOR PEDESTRIANS” la montre a, byen anvan pasaj pyeton an.","p":"Se sa. Kanpe sou liy lan, anvan pasaj pyeton an."}},{"id":"signs-053","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"MINIMUM 40"},"c":1,"en":{"q":"Under a speed limit sign, a white plaque says MINIMUM 40. What does it mean?","o":["Never drive faster than 40 mph","In good conditions, do not drive slower than 40 mph","40 mph is the speed for trucks only","The speed limit ends in 40 miles"],"h1":"Minimum means the lowest.","h2":"A MINIMUM plaque under a speed limit sign means that, when conditions are good, you must not drive slower than the speed shown.","p":"Right. It is the lowest speed allowed in good conditions."},"es":{"q":"Debajo de una señal de límite de velocidad, una placa blanca dice MINIMUM 40. ¿Qué significa?","o":["Nunca maneje a más de 40 mph","Con buenas condiciones, no maneje a menos de 40 mph","40 mph es la velocidad solo para camiones","El límite de velocidad termina en 40 millas"],"h1":"Minimum quiere decir la más baja.","h2":"Una placa MINIMUM debajo de una señal de límite de velocidad significa que, cuando las condiciones son buenas, usted no debe manejar más despacio que la velocidad indicada.","p":"Correcto. Es la velocidad más baja permitida con buenas condiciones."},"zh":{"q":"限速标志下面有一块白色牌子，写着 “MINIMUM 40”（最低 40）。这是什么意思？","o":["开车速度永远不能超过每小时 40 英里","条件好的时候，车速不能低于每小时 40 英里","每小时 40 英里只是卡车的速度","限速在 40 英里后结束"],"h1":"“Minimum” 的意思是最低。","h2":"限速标志下的 “MINIMUM” 牌子表示，在条件好的时候，你的车速不能低于牌子上显示的速度。","p":"对。这是条件好时允许的最低速度。"},"vi":{"q":"Dưới biển giới hạn tốc độ, một tấm biển trắng ghi “MINIMUM 40” (Tối thiểu 40). Điều đó có nghĩa là gì?","o":["Không bao giờ chạy nhanh hơn 40 dặm/giờ","Khi điều kiện tốt, không được chạy chậm hơn 40 dặm/giờ","40 dặm/giờ là tốc độ chỉ dành cho xe tải","Giới hạn tốc độ hết sau 40 dặm"],"h1":"“Minimum” nghĩa là thấp nhất.","h2":"Tấm biển “MINIMUM” dưới biển giới hạn tốc độ nghĩa là khi điều kiện tốt, bạn không được chạy chậm hơn tốc độ ghi trên biển.","p":"Đúng rồi. Đó là tốc độ thấp nhất được phép khi điều kiện tốt."},"tl":{"q":"Sa ilalim ng karatula ng speed limit, may puting plaka na nakasulat ang “MINIMUM 40” (Pinakamababa 40). Ano ang ibig sabihin nito?","o":["Huwag kailanman magmaneho nang mas mabilis sa 40 mph","Kapag maayos ang kondisyon, huwag magmaneho nang mas mabagal sa 40 mph","Ang 40 mph ay bilis para sa mga trak lang","Matatapos ang speed limit pagkalipas ng 40 milya"],"h1":"Ang “minimum” ay nangangahulugang pinakamababa.","h2":"Ang “MINIMUM” na plaka sa ilalim ng karatula ng speed limit ay nangangahulugang, kapag maayos ang kondisyon, hindi ka dapat magmaneho nang mas mabagal sa bilis na nakasulat.","p":"Tama. Ito ang pinakamababang bilis na pinapayagan kapag maayos ang kondisyon."},"ar":{"q":"تحت لافتة حد السرعة، لوحة بيضاء مكتوب عليها «MINIMUM 40» (الحد الأدنى 40). ماذا تعني؟","o":["لا تقد أبدًا أسرع من 40 ميلًا في الساعة","عندما تكون الظروف جيدة، يجب ألّا تقود أبطأ من 40 ميلًا في الساعة","40 ميلًا في الساعة هي سرعة الشاحنات فقط","حد السرعة ينتهي بعد 40 ميلًا"],"h1":"«Minimum» تعني الأقل.","h2":"لوحة «MINIMUM» تحت لافتة حد السرعة تعني أنه عندما تكون الظروف جيدة، يجب ألّا تقود أبطأ من السرعة المكتوبة.","p":"صحيح. إنها أقل سرعة مسموح بها عندما تكون الظروف جيدة."},"ht":{"q":"Anba yon siy limit vitès, yon plak blan di “MINIMUM 40” (pi piti 40). Kisa sa vle di?","o":["Pa janm kondui pi vit pase 40 mph","Lè kondisyon yo bon, pa kondui pi dousman pase 40 mph","40 mph se vitès pou kamyon sèlman","Limit vitès la fini nan 40 mil"],"h1":"“Minimum” vle di pi piti a.","h2":"Yon plak “MINIMUM” anba yon siy limit vitès vle di, lè kondisyon yo bon, ou pa dwe kondui pi dousman pase vitès ki ekri a.","p":"Se sa. Se vitès ki pi ba ki pèmèt lè kondisyon yo bon."}},{"id":"signs-054","scope":"US","cat":"signs","sign":{"shape":"rect-black","text":"NIGHT"},"c":2,"en":{"q":"Under a speed limit sign, a black plaque says NIGHT with a lower speed. When does that lower speed apply?","o":["Only on weekends","Only when it rains","At night","Only for trucks"],"h1":"Read the word on the plaque.","h2":"A NIGHT speed limit plaque means the lower speed limit applies at night, when it is harder to see.","p":"Right. The lower limit is for night driving."},"es":{"q":"Debajo de una señal de límite de velocidad, una placa negra dice NIGHT con una velocidad más baja. ¿Cuándo se aplica esa velocidad más baja?","o":["Solo los fines de semana","Solo cuando llueve","De noche","Solo para camiones"],"h1":"NIGHT quiere decir noche.","h2":"Una placa NIGHT significa que el límite de velocidad más bajo se aplica de noche, cuando es más difícil ver.","p":"Correcto. El límite más bajo es para manejar de noche."},"zh":{"q":"限速标志下面有一块黑色牌子，写着 “NIGHT”（夜间）和一个更低的速度。这个更低的速度什么时候适用？","o":["只在周末","只在下雨时","在夜间","只对卡车"],"h1":"读一读牌子上的字。","h2":"“NIGHT”（夜间）限速牌表示，在夜间看不太清楚的时候，要遵守更低的限速。","p":"对。更低的限速是给夜间开车用的。"},"vi":{"q":"Dưới biển giới hạn tốc độ, một tấm biển đen ghi “NIGHT” (Ban đêm) với tốc độ thấp hơn. Khi nào thì áp dụng tốc độ thấp hơn đó?","o":["Chỉ vào cuối tuần","Chỉ khi trời mưa","Vào ban đêm","Chỉ cho xe tải"],"h1":"Hãy đọc chữ trên tấm biển.","h2":"Tấm biển tốc độ “NIGHT” nghĩa là giới hạn tốc độ thấp hơn được áp dụng vào ban đêm, khi khó nhìn hơn.","p":"Đúng rồi. Giới hạn thấp hơn là để lái xe ban đêm."},"tl":{"q":"Sa ilalim ng karatula ng speed limit, may itim na plaka na nakasulat ang “NIGHT” (Gabi) at mas mababang bilis. Kailan ipinapatupad ang mas mababang bilis na iyon?","o":["Tuwing weekend lang","Kapag umuulan lang","Sa gabi","Para sa mga trak lang"],"h1":"Basahin ang salita sa plaka.","h2":"Ang “NIGHT” na plaka ng speed limit ay nangangahulugang ipinapatupad ang mas mababang speed limit sa gabi, kapag mas mahirap makakita.","p":"Tama. Ang mas mababang limitasyon ay para sa pagmamaneho sa gabi."},"ar":{"q":"تحت لافتة حد السرعة، لوحة سوداء مكتوب عليها «NIGHT» (ليلًا) مع سرعة أقل. متى تُطبَّق هذه السرعة الأقل؟","o":["في عطلة نهاية الأسبوع فقط","عندما تمطر فقط","في الليل","للشاحنات فقط"],"h1":"اقرأ الكلمة المكتوبة على اللوحة.","h2":"لوحة حد السرعة «NIGHT» تعني أن حد السرعة الأقل يُطبَّق في الليل، عندما تكون الرؤية أصعب.","p":"صحيح. الحد الأقل للقيادة في الليل."},"ht":{"q":"Anba yon siy limit vitès, yon plak nwa di “NIGHT” (lannwit) ak yon vitès ki pi ba. Ki lè vitès ki pi ba a aplike?","o":["Sèlman nan wikenn","Sèlman lè lapli ap tonbe","Lannwit","Sèlman pou kamyon"],"h1":"Li mo ki sou plak la.","h2":"Yon plak limit vitès “NIGHT” vle di limit vitès ki pi ba a aplike lannwit, lè li pi difisil pou wè.","p":"Se sa. Limit ki pi ba a se pou kondui lannwit."}},{"id":"signs-055","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"TRUCKS 55"},"c":3,"en":{"q":"Under a speed limit sign, a plaque says TRUCKS 55. What does it mean?","o":["Trucks must drive at least 55 mph","Trucks are not allowed on this road","Cars must stay 55 feet behind trucks","The speed limit for trucks is 55 mph"],"h1":"The plaque names one kind of vehicle.","h2":"A TRUCKS plaque under a speed limit sign means the speed shown is the speed limit for trucks.","p":"Right. 55 mph is the limit for trucks."},"es":{"q":"Debajo de una señal de límite de velocidad, una placa dice TRUCKS 55. ¿Qué significa?","o":["Los camiones deben ir a 55 mph como mínimo","Los camiones no pueden usar esta vía","Los carros deben ir 55 pies detrás de los camiones","El límite de velocidad para camiones es 55 mph"],"h1":"La placa nombra un tipo de vehículo.","h2":"Una placa TRUCKS debajo de una señal de límite significa que la velocidad indicada es el límite para camiones.","p":"Correcto. 55 mph es el límite para camiones."},"zh":{"q":"限速标志下面有一块牌子，写着 “TRUCKS 55”（卡车 55）。这是什么意思？","o":["卡车车速至少要每小时 55 英里","卡车不准在这条路上行驶","小汽车必须在卡车后面保持 55 英尺","卡车的限速是每小时 55 英里"],"h1":"牌子上写的是一种车。","h2":"限速标志下的 “TRUCKS”（卡车）牌子表示，上面显示的速度是卡车的限速。","p":"对。每小时 55 英里是卡车的限速。"},"vi":{"q":"Dưới biển giới hạn tốc độ, một tấm biển ghi “TRUCKS 55” (Xe tải 55). Điều đó có nghĩa là gì?","o":["Xe tải phải chạy ít nhất 55 dặm/giờ","Xe tải không được chạy trên con đường này","Xe hơi phải giữ cách xe tải 55 feet","Giới hạn tốc độ cho xe tải là 55 dặm/giờ"],"h1":"Tấm biển ghi tên một loại xe.","h2":"Tấm biển “TRUCKS” dưới biển giới hạn tốc độ nghĩa là tốc độ ghi trên đó là giới hạn tốc độ cho xe tải.","p":"Đúng rồi. 55 dặm/giờ là giới hạn cho xe tải."},"tl":{"q":"Sa ilalim ng karatula ng speed limit, may plaka na nakasulat ang “TRUCKS 55” (Mga trak 55). Ano ang ibig sabihin nito?","o":["Dapat magmaneho ang mga trak nang hindi bababa sa 55 mph","Bawal ang mga trak sa kalsadang ito","Dapat manatili ang mga kotse nang 55 talampakan sa likod ng mga trak","Ang speed limit para sa mga trak ay 55 mph"],"h1":"Isang uri ng sasakyan ang nakasulat sa plaka.","h2":"Ang “TRUCKS” na plaka sa ilalim ng karatula ng speed limit ay nangangahulugang ang bilis na nakasulat ay ang speed limit para sa mga trak.","p":"Tama. Ang 55 mph ang limitasyon para sa mga trak."},"ar":{"q":"تحت لافتة حد السرعة، لوحة مكتوب عليها «TRUCKS 55» (الشاحنات 55). ماذا تعني؟","o":["يجب أن تسير الشاحنات بسرعة 55 ميلًا في الساعة على الأقل","الشاحنات ممنوعة على هذا الطريق","يجب أن تبقى السيارات على بعد 55 قدمًا خلف الشاحنات","حد السرعة للشاحنات هو 55 ميلًا في الساعة"],"h1":"اللوحة تذكر نوعًا واحدًا من المركبات.","h2":"لوحة «TRUCKS» تحت لافتة حد السرعة تعني أن السرعة المكتوبة هي حد السرعة للشاحنات.","p":"صحيح. 55 ميلًا في الساعة هو الحد للشاحنات."},"ht":{"q":"Anba yon siy limit vitès, yon plak di “TRUCKS 55” (kamyon 55). Kisa sa vle di?","o":["Kamyon yo dwe kondui omwen 55 mph","Kamyon pa gen dwa sou wout sa a","Machin yo dwe rete 55 pye dèyè kamyon yo","Limit vitès pou kamyon se 55 mph"],"h1":"Plak la bay non yon sèl kalite machin.","h2":"Yon plak “TRUCKS” anba yon siy limit vitès vle di vitès ki ekri a se limit vitès pou kamyon.","p":"Se sa. 55 mph se limit pou kamyon."}},{"id":"signs-056","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"BEGIN HIGHER FINES ZONE"},"c":0,"en":{"q":"A white sign says BEGIN HIGHER FINES ZONE. What does it tell you?","o":["Tickets for breaking traffic laws cost more in this area","You must pay a toll ahead","Parking is free in this area","The speed limit goes up here"],"h1":"A fine is the money you pay for a ticket.","h2":"A HIGHER FINES ZONE sign tells you that fines for traffic violations are higher in this area.","p":"Right. Breaking the rules here costs more."},"es":{"q":"Una señal blanca dice BEGIN HIGHER FINES ZONE. ¿Qué le indica?","o":["Las multas por violar las leyes de tránsito son más altas en esta zona","Debe pagar un peaje más adelante","El estacionamiento es gratis en esta zona","El límite de velocidad sube aquí"],"h1":"Una multa (fine) es el dinero que se paga por una infracción.","h2":"Una señal HIGHER FINES ZONE le indica que las multas por infracciones de tránsito son más altas en esta zona.","p":"Correcto. Violar las reglas aquí cuesta más."},"zh":{"q":"一个白色标志写着 “BEGIN HIGHER FINES ZONE”（加重罚款区开始）。它告诉你什么？","o":["在这个区域违反交通法规，罚单的钱更多","前方你要交过路费","在这个区域停车免费","这里的限速提高"],"h1":"罚款就是收到罚单时要交的钱。","h2":"“HIGHER FINES ZONE”（加重罚款区）标志告诉你，在这个区域违反交通法规的罚款更高。","p":"对。在这里违反规则要付更多的钱。"},"vi":{"q":"Một biển màu trắng ghi “BEGIN HIGHER FINES ZONE” (Bắt đầu khu vực phạt nặng hơn). Biển này cho bạn biết điều gì?","o":["Vi phạm luật giao thông trong khu vực này bị phạt tiền nhiều hơn","Bạn phải trả phí đường phía trước","Đậu xe miễn phí trong khu vực này","Giới hạn tốc độ tăng lên ở đây"],"h1":"Tiền phạt là số tiền bạn phải trả khi bị phạt.","h2":"Biển “HIGHER FINES ZONE” cho bạn biết tiền phạt khi vi phạm luật giao thông trong khu vực này cao hơn.","p":"Đúng rồi. Vi phạm luật ở đây sẽ tốn nhiều tiền hơn."},"tl":{"q":"May puting karatula na nakasulat ang “BEGIN HIGHER FINES ZONE” (Simula ng lugar na mas mataas ang multa). Ano ang sinasabi nito sa iyo?","o":["Mas mahal ang tiket sa paglabag sa batas-trapiko sa lugar na ito","Kailangan mong magbayad ng toll sa unahan","Libre ang paradahan sa lugar na ito","Tumataas ang speed limit dito"],"h1":"Ang multa ay ang perang ibinabayad mo para sa tiket.","h2":"Ang “HIGHER FINES ZONE” na karatula ay nagsasabi sa iyo na mas mataas ang multa sa mga paglabag sa trapiko sa lugar na ito.","p":"Tama. Mas mahal ang paglabag sa mga patakaran dito."},"ar":{"q":"لافتة بيضاء مكتوب عليها «BEGIN HIGHER FINES ZONE» (بداية منطقة الغرامات الأعلى). ماذا تخبرك؟","o":["مخالفات قوانين المرور تكلف أكثر في هذه المنطقة","يجب أن تدفع رسوم طريق في الأمام","الوقوف مجاني في هذه المنطقة","حد السرعة يرتفع هنا"],"h1":"الغرامة هي المال الذي تدفعه بسبب المخالفة.","h2":"لافتة «HIGHER FINES ZONE» تخبرك بأن غرامات مخالفات المرور أعلى في هذه المنطقة.","p":"صحيح. مخالفة القواعد هنا تكلف أكثر."},"ht":{"q":"Yon siy blan di “BEGIN HIGHER FINES ZONE” (kòmansman zòn kote amann yo pi wo). Kisa li di ou?","o":["Tikè pou vyole lwa trafik yo koute plis nan zòn sa a","Ou dwe peye yon peyaj pi devan","Pakin gratis nan zòn sa a","Limit vitès la monte isit la"],"h1":"Yon amann se lajan ou peye pou yon tikè.","h2":"Yon siy “HIGHER FINES ZONE” di ou amann pou vyolasyon trafik yo pi wo nan zòn sa a.","p":"Se sa. Vyole règ yo isit la koute plis."}},{"id":"signs-057","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"On a white regulatory sign, a symbol is inside a red circle with a red slash across it. What does that mean?","o":["What the symbol shows is required","What the symbol shows is not allowed","What the symbol shows is ahead","What the symbol shows is allowed only at night"],"h1":"The red slash crosses something out.","h2":"A red circle with a red slash on a regulatory sign means the action or vehicle shown inside is not allowed.","p":"Right. The slash means \"not allowed\"."},"es":{"q":"En una señal reglamentaria blanca, un símbolo está dentro de un círculo rojo con una raya roja que lo cruza. ¿Qué significa?","o":["Lo que muestra el símbolo es obligatorio","Lo que muestra el símbolo no está permitido","Lo que muestra el símbolo está más adelante","Lo que muestra el símbolo se permite solo de noche"],"h1":"La raya roja tacha algo.","h2":"Un círculo rojo con una raya roja en una señal reglamentaria significa que la acción o el vehículo que se ve adentro no está permitido.","p":"Correcto. La raya significa \"no permitido\"."},"zh":{"q":"在白色的管制标志上，一个图案在红圈里，红圈上有一条红色斜线。这是什么意思？","o":["必须做图案显示的事","不准做图案显示的事","前方有图案显示的东西","图案显示的事只在夜间允许"],"h1":"红色斜线是把东西划掉。","h2":"管制标志上带红色斜线的红圈表示，圈里显示的动作或车辆是不允许的。","p":"对。斜线表示“不允许”。"},"vi":{"q":"Trên một biển quy định màu trắng, có một hình nằm trong vòng tròn đỏ với một gạch chéo đỏ. Điều đó có nghĩa là gì?","o":["Bắt buộc phải làm điều mà hình cho thấy","Không được phép làm điều mà hình cho thấy","Điều mà hình cho thấy ở phía trước","Điều mà hình cho thấy chỉ được phép vào ban đêm"],"h1":"Gạch chéo đỏ là gạch bỏ một thứ gì đó.","h2":"Vòng tròn đỏ có gạch chéo đỏ trên biển quy định nghĩa là hành động hoặc loại xe bên trong không được phép.","p":"Đúng rồi. Gạch chéo nghĩa là “không được phép”."},"tl":{"q":"Sa isang puting karatula ng regulasyon, may simbolo sa loob ng pulang bilog na may pulang guhit na pahilis. Ano ang ibig sabihin nito?","o":["Kailangan ang ipinapakita ng simbolo","Bawal ang ipinapakita ng simbolo","Nasa unahan ang ipinapakita ng simbolo","Pinapayagan ang ipinapakita ng simbolo sa gabi lang"],"h1":"Ang pulang guhit na pahilis ay nag-eekis sa isang bagay.","h2":"Ang pulang bilog na may pulang guhit na pahilis sa karatula ng regulasyon ay nangangahulugang bawal ang kilos o sasakyang ipinapakita sa loob.","p":"Tama. Ang guhit ay nangangahulugang “bawal”."},"ar":{"q":"على لافتة تنظيمية بيضاء، رمز داخل دائرة حمراء يقطعها خط أحمر مائل. ماذا يعني ذلك؟","o":["ما يُظهره الرمز مطلوب","ما يُظهره الرمز ممنوع","ما يُظهره الرمز موجود في الأمام","ما يُظهره الرمز مسموح في الليل فقط"],"h1":"الخط الأحمر المائل يشطب شيئًا.","h2":"الدائرة الحمراء مع الخط الأحمر المائل على لافتة تنظيمية تعني أن الفعل أو المركبة الظاهرة في داخلها ممنوعة.","p":"صحيح. الخط المائل يعني «ممنوع»."},"ht":{"q":"Sou yon siy règleman blan, gen yon senbòl andedan yon wonn wouj ak yon ba wouj an travè sou li. Kisa sa vle di?","o":["Sa senbòl la montre a obligatwa","Sa senbòl la montre a pa pèmèt","Sa senbòl la montre a pi devan","Sa senbòl la montre a pèmèt sèlman lannwit"],"h1":"Ba wouj an travè a bare yon bagay.","h2":"Yon wonn wouj ak yon ba wouj an travè sou yon siy règleman vle di aksyon oswa machin ki andedan an pa pèmèt.","p":"Se sa. Ba a vle di “pa pèmèt”."}},{"id":"signs-058","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO LEFT TURN"},"c":2,"en":{"q":"A white sign shows a black arrow turning left, inside a red circle with a red slash. What does it mean?","o":["You must turn left here","The road curves left ahead","You may not turn left here","Left turns are allowed only on green"],"h1":"The red slash goes across the left arrow.","h2":"A left arrow inside a red circle with a slash is a NO LEFT TURN sign, so you may not turn left at that place.","p":"Right. No left turn here."},"es":{"q":"Una señal blanca muestra una flecha negra que gira a la izquierda, dentro de un círculo rojo con una raya roja. ¿Qué significa?","o":["Debe girar a la izquierda aquí","La vía se curva a la izquierda más adelante","No puede girar a la izquierda aquí","Solo se puede girar a la izquierda con luz verde"],"h1":"La raya roja cruza la flecha hacia la izquierda.","h2":"Una flecha a la izquierda dentro de un círculo rojo con una raya es la señal de NO GIRAR A LA IZQUIERDA, así que no puede girar a la izquierda en ese lugar.","p":"Correcto. Aquí no se gira a la izquierda."},"zh":{"q":"一个白色标志上有一个向左转的黑色箭头，在带红色斜线的红圈里。这是什么意思？","o":["你必须在这里左转","前方道路向左弯","你不能在这里左转","只有绿灯时才可以左转"],"h1":"红色斜线划过左转箭头。","h2":"红圈加斜线里的左转箭头是 “NO LEFT TURN”（禁止左转）标志，所以你不能在那个地方左转。","p":"对。这里禁止左转。"},"vi":{"q":"Một biển màu trắng có mũi tên đen rẽ trái, nằm trong vòng tròn đỏ có gạch chéo đỏ. Điều đó có nghĩa là gì?","o":["Bạn phải rẽ trái ở đây","Đường phía trước cong sang trái","Bạn không được rẽ trái ở đây","Chỉ được rẽ trái khi đèn xanh"],"h1":"Gạch chéo đỏ đi ngang qua mũi tên rẽ trái.","h2":"Mũi tên rẽ trái trong vòng tròn đỏ có gạch chéo là biển “NO LEFT TURN” (Cấm rẽ trái), nên bạn không được rẽ trái ở chỗ đó.","p":"Đúng rồi. Cấm rẽ trái ở đây."},"tl":{"q":"May puting karatula na may itim na arrow na kumakaliwa, sa loob ng pulang bilog na may pulang guhit na pahilis. Ano ang ibig sabihin nito?","o":["Dapat kang kumaliwa rito","Kumukurba pakaliwa ang kalsada sa unahan","Bawal kang kumaliwa rito","Pinapayagan ang pagkaliwa kapag berde lang"],"h1":"Dumadaan ang pulang guhit sa arrow na pakaliwa.","h2":"Ang arrow na pakaliwa sa loob ng pulang bilog na may guhit ay “NO LEFT TURN” sign (Bawal kumaliwa), kaya bawal kang kumaliwa sa lugar na iyon.","p":"Tama. Bawal kumaliwa rito."},"ar":{"q":"لافتة بيضاء عليها سهم أسود ينعطف إلى اليسار، داخل دائرة حمراء يقطعها خط أحمر مائل. ماذا تعني؟","o":["يجب أن تنعطف يسارًا هنا","الطريق ينحني إلى اليسار في الأمام","يجب ألّا تنعطف يسارًا هنا","الانعطاف يسارًا مسموح فقط عند الضوء الأخضر"],"h1":"الخط الأحمر المائل يقطع سهم اليسار.","h2":"سهم اليسار داخل دائرة حمراء عليها خط مائل هو لافتة «NO LEFT TURN» (ممنوع الانعطاف يسارًا)، لذلك يجب ألّا تنعطف يسارًا في ذلك المكان.","p":"صحيح. ممنوع الانعطاف يسارًا هنا."},"ht":{"q":"Yon siy blan gen yon flèch nwa k ap vire agoch, andedan yon wonn wouj ak yon ba wouj an travè. Kisa sa vle di?","o":["Ou dwe vire agoch isit la","Wout la koube agoch pi devan","Ou pa gen dwa vire agoch isit la","Ou ka vire agoch sèlman lè limyè a vèt"],"h1":"Ba wouj la travèse flèch agoch la.","h2":"Yon flèch agoch andedan yon wonn wouj ak yon ba se yon siy “NO LEFT TURN” (pa vire agoch), kidonk ou pa gen dwa vire agoch kote sa a.","p":"Se sa. Pa vire agoch isit la."}},{"id":"signs-059","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"NO STRAIGHT THROUGH"},"c":3,"en":{"q":"A white sign shows a black arrow pointing straight up, inside a red circle with a red slash. What does it mean?","o":["You must go straight; no turns","One-way road ahead","Steep hill ahead","You may not go straight; you must turn"],"h1":"The slash crosses out the straight arrow.","h2":"A straight-up arrow inside a red circle with a slash means you may not go straight through, so you must turn.","p":"Right. No going straight here."},"es":{"q":"Una señal blanca muestra una flecha negra que apunta hacia arriba, dentro de un círculo rojo con una raya roja. ¿Qué significa?","o":["Debe seguir derecho; no se permiten giros","Vía de un solo sentido más adelante","Subida empinada más adelante","No puede seguir derecho; debe girar"],"h1":"La raya tacha la flecha que va derecho.","h2":"Una flecha hacia arriba dentro de un círculo rojo con una raya significa que no puede seguir derecho, así que debe girar.","p":"Correcto. Aquí no se sigue derecho."},"zh":{"q":"一个白色标志上有一个笔直向上的黑色箭头，在带红色斜线的红圈里。这是什么意思？","o":["你必须直行，不能转弯","前方是单行道","前方有陡坡","你不能直行，必须转弯"],"h1":"斜线划掉了直行箭头。","h2":"红圈加斜线里笔直向上的箭头表示你不能直行通过，所以你必须转弯。","p":"对。这里禁止直行。"},"vi":{"q":"Một biển màu trắng có mũi tên đen chỉ thẳng lên, nằm trong vòng tròn đỏ có gạch chéo đỏ. Điều đó có nghĩa là gì?","o":["Bạn phải đi thẳng; không được rẽ","Đường một chiều phía trước","Dốc cao phía trước","Bạn không được đi thẳng; bạn phải rẽ"],"h1":"Gạch chéo gạch bỏ mũi tên đi thẳng.","h2":"Mũi tên chỉ thẳng lên trong vòng tròn đỏ có gạch chéo nghĩa là bạn không được đi thẳng qua, nên bạn phải rẽ.","p":"Đúng rồi. Không được đi thẳng ở đây."},"tl":{"q":"May puting karatula na may itim na arrow na nakaturo nang diretso pataas, sa loob ng pulang bilog na may pulang guhit na pahilis. Ano ang ibig sabihin nito?","o":["Dapat kang dumiretso; bawal lumiko","May one-way na kalsada sa unahan","May matarik na burol sa unahan","Bawal kang dumiretso; dapat kang lumiko"],"h1":"Inekisan ng guhit ang arrow na diretso.","h2":"Ang arrow na diretso pataas sa loob ng pulang bilog na may guhit ay nangangahulugang bawal kang dumiretso, kaya dapat kang lumiko.","p":"Tama. Bawal dumiretso rito."},"ar":{"q":"لافتة بيضاء عليها سهم أسود يشير إلى الأعلى مباشرة، داخل دائرة حمراء يقطعها خط أحمر مائل. ماذا تعني؟","o":["يجب أن تسير مستقيمًا؛ لا انعطاف","طريق باتجاه واحد في الأمام","منحدر شديد في الأمام","يجب ألّا تسير مستقيمًا؛ يجب أن تنعطف"],"h1":"الخط المائل يشطب السهم المستقيم.","h2":"السهم المتجه إلى الأعلى داخل دائرة حمراء عليها خط مائل يعني أنه يجب ألّا تسير مستقيمًا، لذلك يجب أن تنعطف.","p":"صحيح. ممنوع السير مستقيمًا هنا."},"ht":{"q":"Yon siy blan gen yon flèch nwa ki montre tou dwat anlè, andedan yon wonn wouj ak yon ba wouj an travè. Kisa sa vle di?","o":["Ou dwe ale tou dwat; pa vire","Wout yon sèl direksyon pi devan","Mòn ki apik pi devan","Ou pa gen dwa ale tou dwat; ou dwe vire"],"h1":"Ba a bare flèch tou dwat la.","h2":"Yon flèch tou dwat anlè andedan yon wonn wouj ak yon ba vle di ou pa gen dwa ale tou dwat, kidonk ou dwe vire.","p":"Se sa. Pa ale tou dwat isit la."}},{"id":"signs-060","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"A white sign over your lane shows two arrows: one pointing straight and one turning left. What may you do from this lane?","o":["Go straight or turn left","Only turn left","Only go straight","Turn right"],"h1":"Each arrow shows a move you may make.","h2":"A lane sign with a straight arrow and a left arrow means you may either go straight or turn left from that lane.","p":"Right. Both moves are allowed from this lane."},"es":{"q":"Una señal blanca sobre su carril muestra dos flechas: una derecho y otra que gira a la izquierda. ¿Qué puede hacer desde este carril?","o":["Seguir derecho o girar a la izquierda","Solo girar a la izquierda","Solo seguir derecho","Girar a la derecha"],"h1":"Cada flecha muestra un movimiento que puede hacer.","h2":"Una señal de carril con una flecha derecho y otra a la izquierda significa que desde ese carril puede seguir derecho o girar a la izquierda.","p":"Correcto. Desde este carril se permiten los dos movimientos."},"zh":{"q":"你车道上方的白色标志有两个箭头：一个直行，一个向左转。在这条车道你可以怎么做？","o":["直行或左转","只能左转","只能直行","右转"],"h1":"每个箭头表示你可以做的一个动作。","h2":"车道标志上有直行箭头和左转箭头，表示你在这条车道可以直行，也可以左转。","p":"对。在这条车道两个动作都可以。"},"vi":{"q":"Một biển màu trắng phía trên làn xe của bạn có hai mũi tên: một mũi tên đi thẳng và một mũi tên rẽ trái. Từ làn này bạn được làm gì?","o":["Đi thẳng hoặc rẽ trái","Chỉ rẽ trái","Chỉ đi thẳng","Rẽ phải"],"h1":"Mỗi mũi tên cho thấy một hướng bạn được đi.","h2":"Biển làn xe có mũi tên đi thẳng và mũi tên rẽ trái nghĩa là từ làn đó bạn có thể đi thẳng hoặc rẽ trái.","p":"Đúng rồi. Từ làn này được làm cả hai."},"tl":{"q":"May puting karatula sa ibabaw ng iyong linya na may dalawang arrow: isang diretso at isang pakaliwa. Ano ang puwede mong gawin mula sa linyang ito?","o":["Dumiretso o kumaliwa","Kumaliwa lang","Dumiretso lang","Kumanan"],"h1":"Ang bawat arrow ay nagpapakita ng galaw na puwede mong gawin.","h2":"Ang karatula ng linya na may arrow na diretso at arrow na pakaliwa ay nangangahulugang puwede kang dumiretso o kumaliwa mula sa linyang iyon.","p":"Tama. Pinapayagan ang dalawang galaw mula sa linyang ito."},"ar":{"q":"لافتة بيضاء فوق حارتك عليها سهمان: واحد مستقيم وواحد ينعطف إلى اليسار. ماذا يمكنك أن تفعل من هذه الحارة؟","o":["السير مستقيمًا أو الانعطاف يسارًا","الانعطاف يسارًا فقط","السير مستقيمًا فقط","الانعطاف يمينًا"],"h1":"كل سهم يُظهر حركة يمكنك أن تقوم بها.","h2":"لافتة الحارة التي عليها سهم مستقيم وسهم إلى اليسار تعني أنه يمكنك أن تسير مستقيمًا أو تنعطف يسارًا من تلك الحارة.","p":"صحيح. الحركتان مسموحتان من هذه الحارة."},"ht":{"q":"Yon siy blan anlè liy ou a gen de flèch: youn ki montre tou dwat ak youn k ap vire agoch. Kisa ou ka fè nan liy sa a?","o":["Ale tou dwat oswa vire agoch","Vire agoch sèlman","Ale tou dwat sèlman","Vire adwat"],"h1":"Chak flèch montre yon mouvman ou ka fè.","h2":"Yon siy liy ki gen yon flèch tou dwat ak yon flèch agoch vle di ou ka swa ale tou dwat swa vire agoch nan liy sa a.","p":"Se sa. Toude mouvman yo pèmèt nan liy sa a."}},{"id":"signs-061","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"RIGHT LANE MUST EXIT"},"c":1,"en":{"q":"You are in the right lane of a freeway. A sign says RIGHT LANE MUST EXIT, but you want to stay on the freeway. What should you do?","o":["Stay in your lane and cut over at the last second","Move to the left lane early, when it is safe","Stop on the shoulder and wait","Take the exit, then back up on the ramp"],"h1":"Your lane will leave the freeway.","h2":"RIGHT LANE MUST EXIT means the right lane leaves the freeway, so to stay on it you should move left early when it is safe.","p":"Right. Move left early to stay on the freeway."},"es":{"q":"Usted va en el carril derecho de una autopista. Una señal dice RIGHT LANE MUST EXIT, pero usted quiere seguir en la autopista. ¿Qué debe hacer?","o":["Quedarse en su carril y cambiarse en el último segundo","Pasarse temprano al carril izquierdo, cuando sea seguro","Pararse en el acotamiento y esperar","Tomar la salida y luego retroceder por la rampa"],"h1":"Su carril va a salir de la autopista.","h2":"RIGHT LANE MUST EXIT significa que el carril derecho sale de la autopista, así que para seguir en ella debe pasarse a la izquierda temprano, cuando sea seguro.","p":"Correcto. Cámbiese temprano a la izquierda para seguir en la autopista."},"zh":{"q":"你在高速公路的右车道。一个标志写着 “RIGHT LANE MUST EXIT”（右车道必须出口驶出），但你想留在高速公路上。你应该怎么做？","o":["留在车道里，最后一刻再切过去","安全时，尽早换到左边车道","停在路肩上等","先下出口，再在匝道上倒车"],"h1":"你的车道会离开高速公路。","h2":"“RIGHT LANE MUST EXIT” 表示右车道会离开高速公路，所以想留在高速公路上，你应该在安全时尽早向左换道。","p":"对。尽早向左换道，留在高速公路上。"},"vi":{"q":"Bạn đang ở làn bên phải của xa lộ. Một biển ghi “RIGHT LANE MUST EXIT” (Làn phải phải ra khỏi xa lộ), nhưng bạn muốn ở lại trên xa lộ. Bạn nên làm gì?","o":["Ở yên trong làn rồi cắt ngang vào giây cuối","Chuyển sang làn bên trái sớm, khi an toàn","Dừng ở lề đường và chờ","Đi vào lối ra, rồi lùi xe lại trên đường dẫn"],"h1":"Làn của bạn sẽ rời khỏi xa lộ.","h2":"“RIGHT LANE MUST EXIT” nghĩa là làn bên phải sẽ rời khỏi xa lộ, nên muốn ở lại trên xa lộ thì bạn nên chuyển sang trái sớm khi an toàn.","p":"Đúng rồi. Chuyển sang trái sớm để ở lại trên xa lộ."},"tl":{"q":"Nasa kanang linya ka ng freeway. May karatula na nakasulat ang “RIGHT LANE MUST EXIT” (Dapat lumabas ang kanang linya), pero gusto mong manatili sa freeway. Ano ang dapat mong gawin?","o":["Manatili sa iyong linya at sumingit sa huling segundo","Lumipat nang maaga sa kaliwang linya, kapag ligtas","Huminto sa gilid ng daan at maghintay","Lumabas sa exit, saka umatras sa rampa"],"h1":"Lalabas sa freeway ang linya mo.","h2":"Ang “RIGHT LANE MUST EXIT” ay nangangahulugang lalabas sa freeway ang kanang linya, kaya para manatili rito, dapat kang lumipat pakaliwa nang maaga kapag ligtas.","p":"Tama. Lumipat pakaliwa nang maaga para manatili sa freeway."},"ar":{"q":"أنت في الحارة اليمنى على طريق سريع. لافتة مكتوب عليها «RIGHT LANE MUST EXIT» (الحارة اليمنى يجب أن تخرج)، لكنك تريد البقاء على الطريق السريع. ماذا يجب أن تفعل؟","o":["ابقَ في حارتك وانتقل فجأة في آخر لحظة","انتقل إلى الحارة اليسرى مبكرًا، عندما يكون ذلك آمنًا","توقف على كتف الطريق وانتظر","اخرج من المخرج، ثم ارجع بالسيارة إلى الخلف على المنحدر"],"h1":"حارتك ستخرج من الطريق السريع.","h2":"«RIGHT LANE MUST EXIT» تعني أن الحارة اليمنى تخرج من الطريق السريع، لذلك لكي تبقى عليه يجب أن تنتقل إلى اليسار مبكرًا عندما يكون ذلك آمنًا.","p":"صحيح. انتقل إلى اليسار مبكرًا لتبقى على الطريق السريع."},"ht":{"q":"Ou nan liy adwat la sou otowout la. Yon siy di “RIGHT LANE MUST EXIT” (liy adwat la dwe sòti), men ou vle rete sou otowout la. Kisa ou dwe fè?","o":["Rete nan liy ou epi koupe antre nan dènye segonn","Pase nan liy agoch la bonè, lè sa an sekirite","Kanpe sou bò wout la epi tann","Pran sòti a, epi fè bak sou ranp lan"],"h1":"Liy ou a pral kite otowout la.","h2":"“RIGHT LANE MUST EXIT” vle di liy adwat la kite otowout la, kidonk pou rete sou li, ou dwe pase agoch bonè lè sa an sekirite.","p":"Se sa. Pase agoch bonè pou rete sou otowout la."}},{"id":"signs-062","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"DO NOT PASS"},"c":2,"en":{"q":"What does a white sign that says DO NOT PASS mean?","o":["Other cars may not pass you, but you may pass them","You may not change lanes to turn","You may not pass other vehicles here","Do not drive past this sign"],"h1":"Passing means going around a slower car.","h2":"A DO NOT PASS sign means passing other vehicles is not allowed along this part of the road.","p":"Right. No passing here."},"es":{"q":"¿Qué significa una señal blanca que dice DO NOT PASS?","o":["Otros no pueden rebasarlo a usted, pero usted sí puede","No puede cambiar de carril para girar","No puede rebasar a otros vehículos aquí","No maneje más allá de esta señal"],"h1":"Rebasar es pasar a un carro más lento.","h2":"Una señal DO NOT PASS significa que no está permitido rebasar a otros vehículos en esta parte de la vía.","p":"Correcto. Aquí no se rebasa."},"zh":{"q":"写着 “DO NOT PASS”（禁止超车）的白色标志是什么意思？","o":["别的车不能超你的车，但你可以超它们","你不能变道去转弯","你在这里不能超越其他车辆","不要开过这个标志"],"h1":"超车就是绕过前面开得慢的车。","h2":"“DO NOT PASS”（禁止超车）标志表示在这段路上不许超越其他车辆。","p":"对。这里不能超车。"},"vi":{"q":"Biển trắng ghi “DO NOT PASS” (Cấm vượt) có nghĩa là gì?","o":["Xe khác không được vượt bạn, nhưng bạn được vượt họ","Bạn không được đổi làn để rẽ","Bạn không được vượt xe khác ở đây","Không được chạy qua biển này"],"h1":"Vượt xe là chạy vòng qua một xe đang đi chậm hơn.","h2":"Biển “DO NOT PASS” (Cấm vượt) có nghĩa là không được vượt xe khác trên đoạn đường này.","p":"Đúng rồi. Không được vượt ở đây."},"tl":{"q":"Ano ang ibig sabihin ng puting karatula na may nakasulat na “DO NOT PASS” (Bawal mag-overtake)?","o":["Hindi ka puwedeng lampasan ng ibang sasakyan, pero puwede mo silang lampasan","Hindi ka puwedeng lumipat ng lane para lumiko","Hindi ka puwedeng lumampas sa ibang sasakyan dito","Huwag magmaneho lampas sa karatulang ito"],"h1":"Ang pag-overtake ay ang pag-ikot sa mas mabagal na sasakyan.","h2":"Ang “DO NOT PASS” sign (Bawal mag-overtake) ay nangangahulugang bawal lampasan ang ibang sasakyan sa bahaging ito ng kalsada.","p":"Tama. Bawal mag-overtake dito."},"ar":{"q":"ماذا تعني لافتة بيضاء مكتوب عليها «DO NOT PASS» (ممنوع التجاوز)؟","o":["ممنوع على السيارات الأخرى أن تتجاوزك، لكن يمكنك أن تتجاوزها","ممنوع أن تغيّر المسار لكي تنعطف","ممنوع أن تتجاوز المركبات الأخرى هنا","لا تقد بعد هذه اللافتة"],"h1":"التجاوز يعني أن تمر من جانب سيارة أبطأ منك.","h2":"لافتة «DO NOT PASS» (ممنوع التجاوز) تعني أن تجاوز المركبات الأخرى ممنوع في هذا الجزء من الطريق.","p":"صحيح. ممنوع التجاوز هنا."},"ht":{"q":"Kisa yon siy blan ki di “DO NOT PASS” (pa double) vle di?","o":["Lòt machin pa ka double ou, men ou ka double yo","Ou pa ka chanje liy pou vire","Ou pa ka double lòt machin isit la","Pa kondui pi lwen siy sa a"],"h1":"Double vle di pase bò yon machin ki pi dousman.","h2":"Yon siy “DO NOT PASS” (pa double) vle di yo pa pèmèt ou double lòt machin sou pati wout sa a.","p":"Se sa. Pa double isit la."}},{"id":"signs-063","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"PASS WITH CARE"},"c":3,"en":{"q":"You see a white sign that says PASS WITH CARE. What does it tell you?","o":["You must pass the car ahead now","Passing is never allowed on this road","Only trucks may pass here","The no-passing zone has ended; you may pass when it is safe"],"h1":"This sign comes at the end of a no-passing area.","h2":"A PASS WITH CARE sign marks the end of a no-passing zone, so you may pass, but only when it is safe.","p":"Right. Passing is allowed again, carefully."},"es":{"q":"Usted ve una señal blanca que dice PASS WITH CARE. ¿Qué le indica?","o":["Debe rebasar ahora al carro de adelante","Nunca se permite rebasar en esta vía","Solo los camiones pueden rebasar aquí","Terminó la zona de no rebasar; puede rebasar cuando sea seguro"],"h1":"Esta señal aparece al final de una zona donde no se rebasa.","h2":"Una señal PASS WITH CARE marca el final de una zona de no rebasar, así que puede rebasar, pero solo cuando sea seguro.","p":"Correcto. Ya se puede rebasar, con cuidado."},"zh":{"q":"你看到一个写着 “PASS WITH CARE”（小心超车）的白色标志。它告诉你什么？","o":["你现在必须超过前面的车","这条路上永远不许超车","只有卡车可以在这里超车","禁止超车区结束了；安全时你可以超车"],"h1":"这个标志出现在禁止超车路段的尽头。","h2":"“PASS WITH CARE”（小心超车）标志表示禁止超车区结束了，所以你可以超车，但只能在安全时超车。","p":"对。又可以超车了，但要小心。"},"vi":{"q":"Bạn thấy biển trắng ghi “PASS WITH CARE” (Vượt cẩn thận). Biển này cho bạn biết điều gì?","o":["Bạn phải vượt xe phía trước ngay bây giờ","Trên con đường này không bao giờ được vượt","Chỉ xe tải được vượt ở đây","Khu vực cấm vượt đã hết; bạn được vượt khi an toàn"],"h1":"Biển này nằm ở cuối một đoạn đường cấm vượt.","h2":"Biển “PASS WITH CARE” (Vượt cẩn thận) báo hết khu vực cấm vượt, nên bạn được vượt, nhưng chỉ khi an toàn.","p":"Đúng rồi. Lại được vượt, nhưng phải cẩn thận."},"tl":{"q":"May nakita kang puting karatula na may nakasulat na “PASS WITH CARE” (Mag-overtake nang maingat). Ano ang sinasabi nito sa iyo?","o":["Dapat mong lampasan ngayon ang sasakyan sa unahan","Hindi kailanman puwedeng mag-overtake sa kalsadang ito","Mga trak lang ang puwedeng mag-overtake dito","Tapos na ang no-passing zone; puwede kang mag-overtake kapag ligtas"],"h1":"Makikita ang karatulang ito sa dulo ng lugar na bawal mag-overtake.","h2":"Ang “PASS WITH CARE” sign ay nagpapakita ng dulo ng no-passing zone, kaya puwede kang mag-overtake, pero kapag ligtas lang.","p":"Tama. Puwede nang mag-overtake ulit, nang maingat."},"ar":{"q":"ترى لافتة بيضاء مكتوبًا عليها «PASS WITH CARE» (تجاوز بحذر). ماذا تخبرك؟","o":["يجب أن تتجاوز السيارة التي أمامك الآن","التجاوز ممنوع دائمًا على هذا الطريق","الشاحنات فقط يمكنها التجاوز هنا","انتهت منطقة منع التجاوز؛ يمكنك أن تتجاوز عندما يكون ذلك آمنًا"],"h1":"هذه اللافتة تأتي في نهاية منطقة يُمنع فيها التجاوز.","h2":"لافتة «PASS WITH CARE» (تجاوز بحذر) تعني أن منطقة منع التجاوز انتهت، لذلك يمكنك أن تتجاوز، ولكن فقط عندما يكون ذلك آمنًا.","p":"صحيح. التجاوز مسموح مرة أخرى، بحذر."},"ht":{"q":"Ou wè yon siy blan ki di “PASS WITH CARE” (double avèk prekosyon). Kisa li di ou?","o":["Ou dwe double machin ki devan an kounye a","Yo pa janm pèmèt double sou wout sa a","Se kamyon sèlman ki ka double isit la","Zòn kote yo pa double a fini; ou ka double lè sa an sekirite"],"h1":"Siy sa a vini nan fen yon zòn kote yo pa ka double.","h2":"Yon siy “PASS WITH CARE” (double avèk prekosyon) make fen zòn kote yo pa ka double a, kidonk ou ka double, men sèlman lè sa an sekirite.","p":"Se sa. Ou ka double ankò, avèk prekosyon."}},{"id":"signs-064","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"KEEP RIGHT EXCEPT TO PASS"},"c":0,"en":{"q":"A white sign says KEEP RIGHT EXCEPT TO PASS. What does it mean?","o":["Drive in the right lane unless you are passing","Only trucks may use the right lane","Pass other cars on the right","Keep to the right of the median"],"h1":"The sign gives one exception.","h2":"KEEP RIGHT EXCEPT TO PASS means you should drive in the right lane and use the left lane only to pass.","p":"Right. Use the left lane only to pass."},"es":{"q":"Una señal blanca dice KEEP RIGHT EXCEPT TO PASS. ¿Qué significa?","o":["Maneje en el carril derecho, salvo para rebasar","Solo los camiones pueden usar el carril derecho","Rebase a otros carros por la derecha","Manténgase a la derecha del camellón"],"h1":"La señal da una sola excepción.","h2":"KEEP RIGHT EXCEPT TO PASS significa que debe manejar en el carril derecho y usar el izquierdo solo para rebasar.","p":"Correcto. Use el carril izquierdo solo para rebasar."},"zh":{"q":"一个白色标志写着 “KEEP RIGHT EXCEPT TO PASS”（除超车外靠右行驶）。它是什么意思？","o":["除非你在超车，否则要在右车道行驶","只有卡车可以用右车道","从右边超过别的车","在中间隔离带的右边行驶"],"h1":"这个标志给出了一个例外。","h2":"“KEEP RIGHT EXCEPT TO PASS”（除超车外靠右行驶）表示你应该在右车道行驶，只有超车时才用左车道。","p":"对。只有超车时才用左车道。"},"vi":{"q":"Biển trắng ghi “KEEP RIGHT EXCEPT TO PASS” (Đi bên phải, trừ khi vượt). Biển này có nghĩa là gì?","o":["Chạy ở làn bên phải, trừ khi bạn đang vượt xe","Chỉ xe tải được dùng làn bên phải","Vượt xe khác bên phải","Đi bên phải dải phân cách giữa đường"],"h1":"Biển này có nêu một trường hợp ngoại lệ.","h2":"“KEEP RIGHT EXCEPT TO PASS” (Đi bên phải, trừ khi vượt) có nghĩa là bạn nên chạy ở làn bên phải và chỉ dùng làn bên trái để vượt.","p":"Đúng rồi. Chỉ dùng làn bên trái để vượt."},"tl":{"q":"May puting karatula na may nakasulat na “KEEP RIGHT EXCEPT TO PASS” (Manatili sa kanan maliban kung mag-o-overtake). Ano ang ibig sabihin nito?","o":["Magmaneho sa kanang lane maliban kung nag-o-overtake ka","Mga trak lang ang puwede sa kanang lane","Lampasan ang ibang sasakyan sa kanan","Manatili sa kanan ng gitnang harang (median)"],"h1":"May isang eksepsiyon ang karatula.","h2":"Ang “KEEP RIGHT EXCEPT TO PASS” ay nangangahulugang dapat kang magmaneho sa kanang lane at gamitin lang ang kaliwang lane para mag-overtake.","p":"Tama. Gamitin lang ang kaliwang lane para mag-overtake."},"ar":{"q":"لافتة بيضاء مكتوب عليها «KEEP RIGHT EXCEPT TO PASS» (الزم اليمين إلا عند التجاوز). ماذا تعني؟","o":["قُد في المسار الأيمن إلا إذا كنت تتجاوز","الشاحنات فقط يمكنها استخدام المسار الأيمن","تجاوز السيارات الأخرى من اليمين","الزم الجهة اليمنى من الجزيرة الوسطية"],"h1":"اللافتة تذكر استثناءً واحدًا.","h2":"لافتة «KEEP RIGHT EXCEPT TO PASS» (الزم اليمين إلا عند التجاوز) تعني أن عليك أن تقود في المسار الأيمن، وأن تستخدم المسار الأيسر للتجاوز فقط.","p":"صحيح. استخدم المسار الأيسر للتجاوز فقط."},"ht":{"q":"Yon siy blan di “KEEP RIGHT EXCEPT TO PASS” (rete adwat sof pou double). Kisa li vle di?","o":["Kondui nan liy adwat la sof si w ap double","Se kamyon sèlman ki ka sèvi ak liy adwat la","Double lòt machin sou bò dwat","Rete sou bò dwat separasyon mitan wout la"],"h1":"Siy la bay yon sèl eksepsyon.","h2":"“KEEP RIGHT EXCEPT TO PASS” (rete adwat sof pou double) vle di ou dwe kondui nan liy adwat la epi sèvi ak liy agoch la sèlman pou double.","p":"Se sa. Sèvi ak liy agoch la sèlman pou double."}},{"id":"signs-065","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"SLOWER TRAFFIC KEEP RIGHT"},"c":1,"en":{"q":"A sign says SLOWER TRAFFIC KEEP RIGHT. You are driving slower than the cars around you. Which lane should you use?","o":["The left lane","The right lane","The shoulder","Any lane you like"],"h1":"The sign speaks to slower drivers.","h2":"SLOWER TRAFFIC KEEP RIGHT means that if you are driving slower than other traffic, you should use the right lane.","p":"Right. Slower drivers keep right."},"es":{"q":"Una señal dice SLOWER TRAFFIC KEEP RIGHT. Usted maneja más despacio que los carros a su alrededor. ¿Qué carril debe usar?","o":["El carril izquierdo","El carril derecho","El acotamiento","El carril que usted quiera"],"h1":"La señal habla a los conductores más lentos.","h2":"SLOWER TRAFFIC KEEP RIGHT significa que si usted maneja más despacio que los demás, debe usar el carril derecho.","p":"Correcto. Los más lentos van a la derecha."},"zh":{"q":"一个标志写着 “SLOWER TRAFFIC KEEP RIGHT”（慢车靠右）。你开得比周围的车慢。你应该用哪条车道？","o":["左车道","右车道","路肩","你喜欢的任何车道"],"h1":"这个标志是说给开得慢的司机听的。","h2":"“SLOWER TRAFFIC KEEP RIGHT”（慢车靠右）表示如果你开得比其他车慢，你应该用右车道。","p":"对。开得慢的司机靠右。"},"vi":{"q":"Một biển ghi “SLOWER TRAFFIC KEEP RIGHT” (Xe chậm đi bên phải). Bạn đang chạy chậm hơn các xe xung quanh. Bạn nên dùng làn nào?","o":["Làn bên trái","Làn bên phải","Lề đường","Làn nào bạn thích cũng được"],"h1":"Biển này dành cho người lái chậm.","h2":"“SLOWER TRAFFIC KEEP RIGHT” (Xe chậm đi bên phải) có nghĩa là nếu bạn chạy chậm hơn các xe khác, bạn nên dùng làn bên phải.","p":"Đúng rồi. Người lái chậm đi bên phải."},"tl":{"q":"May karatulang nagsasabing “SLOWER TRAFFIC KEEP RIGHT” (Ang mas mabagal ay sa kanan). Mas mabagal kang magmaneho kaysa sa mga sasakyan sa paligid mo. Aling lane ang dapat mong gamitin?","o":["Ang kaliwang lane","Ang kanang lane","Ang shoulder (gilid ng kalsada)","Kahit anong lane na gusto mo"],"h1":"Para sa mas mabagal na drayber ang karatula.","h2":"Ang “SLOWER TRAFFIC KEEP RIGHT” ay nangangahulugang kung mas mabagal kang magmaneho kaysa sa ibang sasakyan, dapat mong gamitin ang kanang lane.","p":"Tama. Sa kanan ang mas mabagal na drayber."},"ar":{"q":"لافتة مكتوب عليها «SLOWER TRAFFIC KEEP RIGHT» (السير الأبطأ يلزم اليمين). أنت تقود أبطأ من السيارات التي حولك. أي مسار يجب أن تستخدم؟","o":["المسار الأيسر","المسار الأيمن","كتف الطريق","أي مسار تريده"],"h1":"اللافتة موجّهة للسائقين الأبطأ.","h2":"لافتة «SLOWER TRAFFIC KEEP RIGHT» تعني أنك إذا كنت تقود أبطأ من السيارات الأخرى، فيجب أن تستخدم المسار الأيمن.","p":"صحيح. السائقون الأبطأ يلزمون اليمين."},"ht":{"q":"Yon siy di “SLOWER TRAFFIC KEEP RIGHT” (machin ki pi dousman rete adwat). W ap kondui pi dousman pase machin ki bò kote ou yo. Ki liy ou ta dwe pran?","o":["Liy agoch la","Liy adwat la","Bò wout la (zepòl la)","Nenpòt liy ou vle"],"h1":"Siy la pale ak chofè ki pi dousman yo.","h2":"“SLOWER TRAFFIC KEEP RIGHT” vle di si w ap kondui pi dousman pase lòt machin yo, ou ta dwe pran liy adwat la.","p":"Se sa. Chofè ki pi dousman yo rete adwat."}},{"id":"signs-066","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"STAY IN LANE"},"c":2,"en":{"q":"What does a white sign that says STAY IN LANE mean?","o":["Change lanes now","The lane ends ahead","Do not change lanes here","Stay in the right lane only"],"h1":"Read the words on the sign.","h2":"A STAY IN LANE sign means you must not change lanes along that part of the road.","p":"Right. Do not change lanes here."},"es":{"q":"¿Qué significa una señal blanca que dice STAY IN LANE?","o":["Cambie de carril ahora","El carril termina más adelante","No cambie de carril aquí","Quédese solo en el carril derecho"],"h1":"STAY IN LANE quiere decir quedarse en el carril.","h2":"Una señal STAY IN LANE significa que no debe cambiar de carril en esa parte de la vía.","p":"Correcto. Aquí no se cambia de carril."},"zh":{"q":"写着 “STAY IN LANE”（保持车道）的白色标志是什么意思？","o":["现在变道","前方车道结束","不要在这里变道","只能待在右车道"],"h1":"读一读标志上的字。","h2":"“STAY IN LANE”（保持车道）标志表示在这段路上你不能变道。","p":"对。不要在这里变道。"},"vi":{"q":"Biển trắng ghi “STAY IN LANE” (Giữ nguyên làn) có nghĩa là gì?","o":["Đổi làn ngay bây giờ","Làn đường sắp hết phía trước","Không được đổi làn ở đây","Chỉ được ở làn bên phải"],"h1":"Hãy đọc chữ trên biển.","h2":"Biển “STAY IN LANE” (Giữ nguyên làn) có nghĩa là bạn không được đổi làn trên đoạn đường đó.","p":"Đúng rồi. Không được đổi làn ở đây."},"tl":{"q":"Ano ang ibig sabihin ng puting karatula na may nakasulat na “STAY IN LANE” (Manatili sa lane)?","o":["Lumipat ng lane ngayon","Matatapos ang lane sa unahan","Huwag lumipat ng lane dito","Manatili lang sa kanang lane"],"h1":"Basahin ang mga salita sa karatula.","h2":"Ang “STAY IN LANE” sign ay nangangahulugang bawal kang lumipat ng lane sa bahaging iyon ng kalsada.","p":"Tama. Huwag lumipat ng lane dito."},"ar":{"q":"ماذا تعني لافتة بيضاء مكتوب عليها «STAY IN LANE» (ابقَ في مسارك)؟","o":["غيّر المسار الآن","المسار ينتهي في الأمام","لا تغيّر المسار هنا","ابقَ في المسار الأيمن فقط"],"h1":"اقرأ الكلمات المكتوبة على اللافتة.","h2":"لافتة «STAY IN LANE» (ابقَ في مسارك) تعني أنه يجب ألّا تغيّر المسار في هذا الجزء من الطريق.","p":"صحيح. لا تغيّر المسار هنا."},"ht":{"q":"Kisa yon siy blan ki di “STAY IN LANE” (rete nan liy ou) vle di?","o":["Chanje liy kounye a","Liy la fini pi devan","Pa chanje liy isit la","Rete nan liy adwat la sèlman"],"h1":"Li mo ki ekri sou siy la.","h2":"Yon siy “STAY IN LANE” (rete nan liy ou) vle di ou pa dwe chanje liy sou pati wout sa a.","p":"Se sa. Pa chanje liy isit la."}},{"id":"signs-067","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"DO NOT DRIVE ON SHOULDER"},"c":3,"en":{"q":"Traffic is slow. A sign says DO NOT DRIVE ON SHOULDER. What should you do?","o":["Use the shoulder to get ahead","Use the shoulder only to pass trucks","Drive on the shoulder slowly","Stay in the travel lanes and wait"],"h1":"The shoulder is the paved edge outside the lanes.","h2":"DO NOT DRIVE ON SHOULDER means you must stay in the travel lanes and not use the shoulder to drive past traffic.","p":"Right. Stay off the shoulder."},"es":{"q":"El tráfico va lento. Una señal dice DO NOT DRIVE ON SHOULDER. ¿Qué debe hacer?","o":["Usar el acotamiento para adelantarse","Usar el acotamiento solo para pasar camiones","Manejar despacio por el acotamiento","Quedarse en los carriles y esperar"],"h1":"El acotamiento (shoulder) es la orilla pavimentada fuera de los carriles.","h2":"DO NOT DRIVE ON SHOULDER significa que debe quedarse en los carriles y no usar el acotamiento para pasar al tráfico.","p":"Correcto. No use el acotamiento."},"zh":{"q":"车流很慢。一个标志写着 “DO NOT DRIVE ON SHOULDER”（禁止在路肩行驶）。你应该怎么做？","o":["用路肩开到前面去","只在超卡车时用路肩","在路肩上慢慢开","待在行车道里等着"],"h1":"路肩是车道外面铺好的路边。","h2":"“DO NOT DRIVE ON SHOULDER”（禁止在路肩行驶）表示你必须待在行车道里，不能用路肩开过前面的车。","p":"对。不要开上路肩。"},"vi":{"q":"Xe đang chạy chậm. Một biển ghi “DO NOT DRIVE ON SHOULDER” (Không chạy trên lề). Bạn nên làm gì?","o":["Chạy trên lề để lên trước","Chỉ chạy trên lề để vượt xe tải","Chạy chậm trên lề","Ở lại trong làn xe chạy và chờ"],"h1":"Lề đường là phần mép đường có trải nhựa nằm ngoài các làn xe.","h2":"“DO NOT DRIVE ON SHOULDER” (Không chạy trên lề) có nghĩa là bạn phải ở trong các làn xe chạy và không được dùng lề đường để chạy qua các xe khác.","p":"Đúng rồi. Không chạy trên lề."},"tl":{"q":"Mabagal ang trapiko. May karatulang nagsasabing “DO NOT DRIVE ON SHOULDER” (Bawal magmaneho sa shoulder). Ano ang dapat mong gawin?","o":["Gamitin ang shoulder para makauna","Gamitin lang ang shoulder para lampasan ang mga trak","Magmaneho nang mabagal sa shoulder","Manatili sa mga lane ng sasakyan at maghintay"],"h1":"Ang shoulder ay ang sementadong gilid sa labas ng mga lane.","h2":"Ang “DO NOT DRIVE ON SHOULDER” ay nangangahulugang dapat kang manatili sa mga lane ng sasakyan at huwag gamitin ang shoulder para lampasan ang trapiko.","p":"Tama. Huwag dumaan sa shoulder."},"ar":{"q":"السير بطيء. لافتة مكتوب عليها «DO NOT DRIVE ON SHOULDER» (ممنوع القيادة على كتف الطريق). ماذا يجب أن تفعل؟","o":["استخدم كتف الطريق لكي تتقدم","استخدم كتف الطريق فقط لتتجاوز الشاحنات","قُد ببطء على كتف الطريق","ابقَ في مسارات السير وانتظر"],"h1":"كتف الطريق هو الحافة المرصوفة خارج المسارات.","h2":"لافتة «DO NOT DRIVE ON SHOULDER» تعني أنه يجب أن تبقى في مسارات السير، ويجب ألّا تستخدم كتف الطريق لتتقدم على السيارات الأخرى.","p":"صحيح. ابتعد عن كتف الطريق."},"ht":{"q":"Trafik la dousman. Yon siy di “DO NOT DRIVE ON SHOULDER” (pa kondui sou zepòl wout la). Kisa ou ta dwe fè?","o":["Sèvi ak zepòl la pou pase devan","Sèvi ak zepòl la sèlman pou double kamyon","Kondui dousman sou zepòl la","Rete nan liy wout yo epi tann"],"h1":"Zepòl la se bò wout la ki asfalte, deyò liy yo.","h2":"“DO NOT DRIVE ON SHOULDER” vle di ou dwe rete nan liy wout yo epi ou pa dwe sèvi ak zepòl la pou pase devan lòt machin.","p":"Se sa. Pa kondui sou zepòl la."}},{"id":"signs-068","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"RUNAWAY VEHICLES ONLY"},"c":0,"en":{"q":"On a long downhill road, a ramp has a sign that says RUNAWAY VEHICLES ONLY. Who may use the ramp?","o":["A vehicle that cannot slow down or stop, like a truck with failed brakes","Any driver who wants to rest","Cars that want to turn around","Drivers waiting for a tow truck"],"h1":"Runaway means out of control.","h2":"A RUNAWAY VEHICLES ONLY ramp is only for vehicles that cannot slow or stop, such as a truck whose brakes have failed.","p":"Right. It is only for vehicles that cannot stop."},"es":{"q":"En una bajada larga, una rampa tiene una señal que dice RUNAWAY VEHICLES ONLY. ¿Quién puede usar la rampa?","o":["Un vehículo que no puede frenar ni pararse, como un camión sin frenos","Cualquier conductor que quiera descansar","Carros que quieren dar la vuelta","Conductores que esperan una grúa"],"h1":"Runaway quiere decir fuera de control.","h2":"Una rampa RUNAWAY VEHICLES ONLY es solo para vehículos que no pueden frenar ni pararse, como un camión que se quedó sin frenos.","p":"Correcto. Es solo para vehículos que no pueden parar."},"zh":{"q":"在一条很长的下坡路上，有一条坡道，标志写着 “RUNAWAY VEHICLES ONLY”（仅限失控车辆）。谁可以用这条坡道？","o":["无法减速或停车的车辆，比如刹车失灵的卡车","任何想休息的司机","想掉头的汽车","等拖车的司机"],"h1":"“Runaway” 的意思是失去控制。","h2":"“RUNAWAY VEHICLES ONLY”（仅限失控车辆）坡道只给无法减速或停车的车辆用，比如刹车失灵的卡车。","p":"对。只给停不下来的车辆用。"},"vi":{"q":"Trên một con dốc dài, có một đường thoát với biển ghi “RUNAWAY VEHICLES ONLY” (Chỉ dành cho xe mất kiểm soát). Ai được dùng đường này?","o":["Xe không thể giảm tốc hay dừng lại, như xe tải bị mất phanh","Bất cứ tài xế nào muốn nghỉ","Xe muốn quay đầu","Tài xế đang chờ xe kéo"],"h1":"“Runaway” nghĩa là mất kiểm soát.","h2":"Đường thoát “RUNAWAY VEHICLES ONLY” chỉ dành cho xe không thể giảm tốc hay dừng lại, ví dụ như xe tải bị mất phanh.","p":"Đúng rồi. Chỉ dành cho xe không dừng được."},"tl":{"q":"Sa isang mahabang pababang kalsada, may rampa na may karatulang “RUNAWAY VEHICLES ONLY” (Para lang sa sasakyang hindi makontrol). Sino ang puwedeng gumamit ng rampa?","o":["Sasakyang hindi makabagal o makahinto, gaya ng trak na nawalan ng preno","Kahit sinong drayber na gustong magpahinga","Mga kotseng gustong umikot pabalik","Mga drayber na naghihintay ng tow truck"],"h1":"Ang “runaway” ay nangangahulugang hindi na makontrol.","h2":"Ang “RUNAWAY VEHICLES ONLY” na rampa ay para lang sa mga sasakyang hindi makabagal o makahinto, gaya ng trak na nawalan ng preno.","p":"Tama. Para lang ito sa mga sasakyang hindi makahinto."},"ar":{"q":"على طريق منحدر طويل، يوجد منحدر جانبي عليه لافتة «RUNAWAY VEHICLES ONLY» (للمركبات الخارجة عن السيطرة فقط). من يمكنه استخدام هذا المنحدر؟","o":["مركبة لا تستطيع أن تخفف سرعتها أو تتوقف، مثل شاحنة تعطلت مكابحها","أي سائق يريد أن يستريح","السيارات التي تريد أن تستدير وتعود","السائقون الذين ينتظرون شاحنة سحب"],"h1":"«Runaway» تعني خارجة عن السيطرة.","h2":"منحدر «RUNAWAY VEHICLES ONLY» مخصص فقط للمركبات التي لا تستطيع أن تخفف سرعتها أو تتوقف، مثل شاحنة تعطلت مكابحها.","p":"صحيح. إنه فقط للمركبات التي لا تستطيع التوقف."},"ht":{"q":"Sou yon long desant, gen yon ranp ki gen yon siy ki di “RUNAWAY VEHICLES ONLY” (sèlman pou machin ki pa kontwole ankò). Kiyès ki ka sèvi ak ranp lan?","o":["Yon machin ki pa ka ralanti ni kanpe, tankou yon kamyon ki pèdi fren","Nenpòt chofè ki vle repoze","Machin ki vle vire tounen","Chofè k ap tann yon kamyon remòk"],"h1":"“Runaway” vle di machin nan pa kontwole ankò.","h2":"Yon ranp “RUNAWAY VEHICLES ONLY” se sèlman pou machin ki pa ka ralanti ni kanpe, tankou yon kamyon ki pèdi fren.","p":"Se sa. Li la sèlman pou machin ki pa ka kanpe."}},{"id":"signs-069","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"Parking signs come in two colors of letters. What do parking signs with green letters usually show?","o":["Where you may never park","Where and how long you may park","Where you must stop for a train","Where a school zone starts"],"h1":"Red letters on parking signs say \"no\".","h2":"Parking signs with green letters show where and when you may park, often with a time limit; red letters show where parking is not allowed.","p":"Right. Green tells you when parking is allowed."},"es":{"q":"Las señales de estacionamiento tienen letras de dos colores. ¿Qué indican normalmente las que tienen letras verdes?","o":["Dónde nunca puede estacionarse","Dónde y por cuánto tiempo puede estacionarse","Dónde debe pararse por un tren","Dónde empieza una zona escolar"],"h1":"Las letras rojas en estas señales dicen \"no\".","h2":"Las señales de estacionamiento con letras verdes indican dónde y cuándo puede estacionarse, muchas veces con límite de tiempo; las letras rojas indican dónde no se permite.","p":"Correcto. El verde le dice cuándo se permite estacionar."},"zh":{"q":"停车标志上的字有两种颜色。绿字的停车标志通常表示什么？","o":["你永远不能停车的地方","你可以在哪里停车、可以停多久","你必须为火车停车的地方","学校区开始的地方"],"h1":"停车标志上的红字是说“不行”。","h2":"绿字的停车标志表示你可以在哪里、什么时候停车，常常有时间限制；红字表示不许停车的地方。","p":"对。绿色告诉你什么时候可以停车。"},"vi":{"q":"Biển đậu xe có chữ hai màu. Biển đậu xe chữ xanh lá thường cho biết điều gì?","o":["Nơi bạn không bao giờ được đậu","Bạn được đậu ở đâu và đậu bao lâu","Nơi bạn phải dừng chờ tàu hỏa","Nơi bắt đầu khu vực trường học"],"h1":"Chữ đỏ trên biển đậu xe nghĩa là “không”.","h2":"Biển đậu xe chữ xanh lá cho biết bạn được đậu ở đâu và khi nào, thường có giới hạn thời gian; chữ đỏ cho biết nơi không được đậu xe.","p":"Đúng rồi. Màu xanh lá cho biết khi nào được đậu xe."},"tl":{"q":"May dalawang kulay ng letra ang mga karatula sa paradahan. Ano ang karaniwang ipinapakita ng karatula sa paradahan na may berdeng letra?","o":["Kung saan hindi ka kailanman puwedeng pumarada","Kung saan at gaano katagal ka puwedeng pumarada","Kung saan ka dapat huminto para sa tren","Kung saan nagsisimula ang school zone"],"h1":"Ang pulang letra sa karatula sa paradahan ay nagsasabing “hindi”.","h2":"Ang mga karatula sa paradahan na may berdeng letra ay nagpapakita kung saan at kailan ka puwedeng pumarada, madalas may limitasyon sa oras; ang pulang letra ay nagpapakita kung saan bawal pumarada.","p":"Tama. Sinasabi ng berde kung kailan puwedeng pumarada."},"ar":{"q":"لافتات الوقوف (الركن) تأتي بحروف بلونين. ماذا تُظهر عادةً لافتات الوقوف ذات الحروف الخضراء؟","o":["الأماكن التي لا يمكنك أن تركن فيها أبدًا","أين يمكنك أن تركن وكم من الوقت","أين يجب أن تتوقف من أجل القطار","أين تبدأ منطقة المدرسة"],"h1":"الحروف الحمراء على لافتات الوقوف تقول «لا».","h2":"لافتات الوقوف ذات الحروف الخضراء تُظهر أين ومتى يمكنك أن تركن، وغالبًا مع حدّ للوقت؛ أما الحروف الحمراء فتُظهر الأماكن التي يُمنع فيها الوقوف.","p":"صحيح. الأخضر يخبرك متى يُسمح بالوقوف."},"ht":{"q":"Siy pakin yo gen lèt ki gen de koulè. Kisa siy pakin ki gen lèt vèt yo montre anjeneral?","o":["Kote ou pa janm ka pake","Ki kote ou ka pake ak pou konbyen tan","Kote ou dwe kanpe pou yon tren","Kote yon zòn lekòl kòmanse"],"h1":"Lèt wouj sou siy pakin yo di “non”.","h2":"Siy pakin ki gen lèt vèt yo montre ki kote ak ki lè ou ka pake, souvan avèk yon limit tan; lèt wouj yo montre kote yo pa pèmèt pake.","p":"Se sa. Vèt di ou ki lè ou ka pake."}},{"id":"signs-070","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"ROAD CLOSED"},"c":2,"en":{"q":"A white sign on a barrier across the road says ROAD CLOSED. What should you do?","o":["Drive around the barrier slowly","Drive past it if you see no workers","Do not drive past it; take another road","Honk and wait for someone to open it"],"h1":"Closed means no one may drive there.","h2":"A ROAD CLOSED sign means the road is closed to traffic, so you must not drive past it and should use another route.","p":"Right. Find another way."},"es":{"q":"Una señal blanca sobre una barrera que cruza la vía dice ROAD CLOSED. ¿Qué debe hacer?","o":["Rodear la barrera despacio","Pasar si no ve trabajadores","No pasar; tomar otra vía","Tocar la bocina y esperar que alguien abra"],"h1":"Closed quiere decir cerrado.","h2":"Una señal ROAD CLOSED significa que la vía está cerrada al tráfico, así que no debe pasar y debe usar otra ruta.","p":"Correcto. Busque otro camino."},"zh":{"q":"横在路上的路障上有一个白色标志，写着 “ROAD CLOSED”（道路封闭）。你应该怎么做？","o":["慢慢绕过路障开过去","如果没看到工人就开过去","不要开过去；走别的路","按喇叭，等人来打开"],"h1":"封闭的意思是谁都不能在那里开车。","h2":"“ROAD CLOSED”（道路封闭）标志表示这条路不许车辆通行，所以你不能开过去，应该走别的路线。","p":"对。找别的路走。"},"vi":{"q":"Một biển trắng trên rào chắn ngang đường ghi “ROAD CLOSED” (Đường bị đóng). Bạn nên làm gì?","o":["Chạy chậm vòng qua rào chắn","Chạy qua nếu không thấy công nhân","Không chạy qua; đi đường khác","Bấm còi và chờ người tới mở"],"h1":"Đóng có nghĩa là không ai được chạy xe ở đó.","h2":"Biển “ROAD CLOSED” (Đường bị đóng) có nghĩa là đường cấm xe chạy, nên bạn không được chạy qua và nên đi đường khác.","p":"Đúng rồi. Hãy tìm đường khác."},"tl":{"q":"May puting karatula sa harang sa kabila ng kalsada na nagsasabing “ROAD CLOSED” (Sarado ang kalsada). Ano ang dapat mong gawin?","o":["Dahan-dahang umikot sa harang","Lumampas dito kung wala kang nakikitang trabahador","Huwag lumampas dito; dumaan sa ibang kalsada","Bumusina at maghintay na may magbukas nito"],"h1":"Ang sarado ay nangangahulugang walang puwedeng magmaneho roon.","h2":"Ang “ROAD CLOSED” sign ay nangangahulugang sarado ang kalsada sa trapiko, kaya hindi ka dapat lumampas dito at dapat kang dumaan sa ibang ruta.","p":"Tama. Humanap ng ibang daan."},"ar":{"q":"على حاجز يعترض الطريق لافتة بيضاء مكتوب عليها «ROAD CLOSED» (الطريق مغلق). ماذا يجب أن تفعل؟","o":["قُد ببطء حول الحاجز","تجاوز الحاجز إذا لم ترَ عمالًا","لا تتجاوز الحاجز؛ خذ طريقًا آخر","اضغط على البوق وانتظر أن يفتحه أحد"],"h1":"مغلق يعني أنه ممنوع على أي أحد أن يقود هناك.","h2":"لافتة «ROAD CLOSED» (الطريق مغلق) تعني أن الطريق مغلق أمام السير، لذلك يجب ألّا تتجاوزها، وعليك أن تسلك طريقًا آخر.","p":"صحيح. ابحث عن طريق آخر."},"ht":{"q":"Yon siy blan sou yon baryè ki bare wout la di “ROAD CLOSED” (wout la fèmen). Kisa ou ta dwe fè?","o":["Kondui dousman bò kote baryè a","Pase si ou pa wè travayè","Pa pase; pran yon lòt wout","Klaksonnen epi tann yon moun vin louvri l"],"h1":"Fèmen vle di pèsonn pa ka kondui la.","h2":"Yon siy “ROAD CLOSED” (wout la fèmen) vle di wout la fèmen pou machin, kidonk ou pa dwe pase epi ou ta dwe pran yon lòt wout.","p":"Se sa. Chèche yon lòt wout."}},{"id":"signs-071","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"LOCAL TRAFFIC ONLY"},"c":3,"en":{"q":"A sign at the start of a road says ROAD CLOSED, LOCAL TRAFFIC ONLY. Who may drive on it?","o":["Anyone who wants a shortcut","Only trucks","No one at all","Only people going to a place on that road"],"h1":"Local traffic means people who live or have business there.","h2":"LOCAL TRAFFIC ONLY means only drivers whose destination is on that road may use it; through traffic must take another route.","p":"Right. Only drivers going to a place on that road."},"es":{"q":"Una señal al principio de una vía dice ROAD CLOSED, LOCAL TRAFFIC ONLY. ¿Quién puede manejar por ella?","o":["Cualquiera que quiera un atajo","Solo camiones","Nadie","Solo quienes van a un lugar en esa vía"],"h1":"Tráfico local son las personas que viven o tienen asuntos allí.","h2":"LOCAL TRAFFIC ONLY significa que solo pueden usarla los conductores cuyo destino está en esa vía; el tráfico de paso debe tomar otra ruta.","p":"Correcto. Solo quienes van a un lugar en esa vía."},"zh":{"q":"一条路的入口有个标志写着 “ROAD CLOSED, LOCAL TRAFFIC ONLY”（道路封闭，仅限本地车辆）。谁可以在这条路上开车？","o":["任何想抄近路的人","只有卡车","任何人都不行","只有要去这条路上某个地方的人"],"h1":"本地车辆是指住在那里或在那里办事的人。","h2":"“LOCAL TRAFFIC ONLY”（仅限本地车辆）表示只有目的地在这条路上的司机可以用这条路；路过的车辆必须走别的路线。","p":"对。只有要去这条路上某个地方的司机。"},"vi":{"q":"Ở đầu một con đường có biển ghi “ROAD CLOSED, LOCAL TRAFFIC ONLY” (Đường bị đóng, chỉ xe địa phương). Ai được chạy trên đường này?","o":["Bất cứ ai muốn đi tắt","Chỉ xe tải","Không ai cả","Chỉ những người đi tới một nơi trên con đường đó"],"h1":"Xe địa phương là người sống hoặc có việc ở đó.","h2":"“LOCAL TRAFFIC ONLY” (Chỉ xe địa phương) có nghĩa là chỉ tài xế có điểm đến trên con đường đó mới được dùng đường; xe chỉ đi ngang qua phải đi đường khác.","p":"Đúng rồi. Chỉ tài xế đi tới một nơi trên con đường đó."},"tl":{"q":"Sa simula ng isang kalsada, may karatulang nagsasabing “ROAD CLOSED, LOCAL TRAFFIC ONLY” (Sarado ang kalsada, para lang sa lokal na trapiko). Sino ang puwedeng magmaneho rito?","o":["Kahit sinong gustong mag-shortcut","Mga trak lang","Walang kahit sino","Mga taong pupunta lang sa isang lugar sa kalsadang iyon"],"h1":"Ang lokal na trapiko ay mga taong nakatira o may pakay roon.","h2":"Ang “LOCAL TRAFFIC ONLY” ay nangangahulugang ang mga drayber lang na ang pupuntahan ay nasa kalsadang iyon ang puwedeng gumamit nito; ang mga dadaan lang ay dapat dumaan sa ibang ruta.","p":"Tama. Mga drayber lang na pupunta sa isang lugar sa kalsadang iyon."},"ar":{"q":"عند بداية طريق لافتة مكتوب عليها «ROAD CLOSED, LOCAL TRAFFIC ONLY» (الطريق مغلق، للسير المحلي فقط). من يمكنه أن يقود عليه؟","o":["أي شخص يريد طريقًا مختصرًا","الشاحنات فقط","لا أحد على الإطلاق","فقط الأشخاص الذين يذهبون إلى مكان على ذلك الطريق"],"h1":"السير المحلي يعني الناس الذين يسكنون هناك أو لديهم عمل هناك.","h2":"عبارة «LOCAL TRAFFIC ONLY» تعني أن السائقين الذين وجهتهم على ذلك الطريق فقط يمكنهم استخدامه؛ أما المارّون فيجب أن يسلكوا طريقًا آخر.","p":"صحيح. فقط السائقون الذاهبون إلى مكان على ذلك الطريق."},"ht":{"q":"Nan kòmansman yon wout, gen yon siy ki di “ROAD CLOSED, LOCAL TRAFFIC ONLY” (wout la fèmen, sèlman pou moun zòn nan). Kiyès ki ka kondui sou li?","o":["Nenpòt moun ki vle pran yon chemen kout","Kamyon sèlman","Pèsonn ditou","Sèlman moun k ap ale yon kote sou wout sa a"],"h1":"Trafik lokal vle di moun ki rete oswa ki gen zafè yo la.","h2":"“LOCAL TRAFFIC ONLY” vle di se sèlman chofè ki prale yon kote sou wout sa a ki ka sèvi avè l; machin k ap travèse sèlman dwe pran yon lòt wout.","p":"Se sa. Sèlman chofè k ap ale yon kote sou wout sa a."}},{"id":"signs-072","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"WEIGHT LIMIT 10 TONS"},"c":0,"en":{"q":"Before a bridge, a sign says WEIGHT LIMIT 10 TONS. What does it mean?","o":["Vehicles heavier than 10 tons may not cross","Every vehicle must stop and be weighed","Only 10 vehicles may be on the bridge","Trucks must drive 10 mph"],"h1":"A ton is a measure of weight.","h2":"A WEIGHT LIMIT sign means vehicles that weigh more than the amount shown may not use that road or bridge.","p":"Right. Heavier vehicles may not cross."},"es":{"q":"Antes de un puente, una señal dice WEIGHT LIMIT 10 TONS. ¿Qué significa?","o":["Los vehículos de más de 10 toneladas no pueden cruzar","Todos los vehículos deben pararse a pesarse","Solo 10 vehículos pueden estar en el puente","Los camiones deben ir a 10 mph"],"h1":"Una tonelada (ton) es una medida de peso.","h2":"Una señal WEIGHT LIMIT significa que los vehículos que pesan más de lo indicado no pueden usar esa vía o puente.","p":"Correcto. Los vehículos más pesados no pueden cruzar."},"zh":{"q":"在桥前面，一个标志写着 “WEIGHT LIMIT 10 TONS”（限重10吨）。它是什么意思？","o":["重量超过10吨的车辆不能过桥","每辆车都必须停下来称重","桥上只能有10辆车","卡车必须以每小时10英里的速度行驶"],"h1":"吨是重量的单位。","h2":"“WEIGHT LIMIT”（限重）标志表示比标志上的重量更重的车辆不能走这条路或这座桥。","p":"对。更重的车辆不能过桥。"},"vi":{"q":"Trước một cây cầu có biển ghi “WEIGHT LIMIT 10 TONS” (Giới hạn tải trọng 10 tấn). Biển này có nghĩa là gì?","o":["Xe nặng hơn 10 tấn không được qua cầu","Xe nào cũng phải dừng lại để cân","Chỉ 10 xe được ở trên cầu","Xe tải phải chạy 10 mph"],"h1":"Tấn là một đơn vị đo trọng lượng.","h2":"Biển “WEIGHT LIMIT” (Giới hạn tải trọng) có nghĩa là xe nặng hơn số ghi trên biển không được đi trên con đường hay cây cầu đó.","p":"Đúng rồi. Xe nặng hơn không được qua cầu."},"tl":{"q":"Bago ang isang tulay, may karatulang nagsasabing “WEIGHT LIMIT 10 TONS” (Limitasyon sa bigat: 10 tonelada). Ano ang ibig sabihin nito?","o":["Hindi puwedeng tumawid ang mga sasakyang mas mabigat sa 10 tonelada","Dapat huminto at timbangin ang bawat sasakyan","10 sasakyan lang ang puwede sa tulay","Dapat 10 mph ang takbo ng mga trak"],"h1":"Ang tonelada ay sukat ng bigat.","h2":"Ang “WEIGHT LIMIT” sign ay nangangahulugang ang mga sasakyang mas mabigat sa nakasulat na halaga ay hindi puwedeng gumamit ng kalsada o tulay na iyon.","p":"Tama. Hindi puwedeng tumawid ang mas mabibigat na sasakyan."},"ar":{"q":"قبل جسر، لافتة مكتوب عليها «WEIGHT LIMIT 10 TONS» (الحد الأقصى للوزن 10 أطنان). ماذا تعني؟","o":["المركبات التي يزيد وزنها عن 10 أطنان ممنوع أن تعبر","يجب أن تتوقف كل مركبة ليتم وزنها","يمكن أن تكون 10 مركبات فقط على الجسر","يجب أن تسير الشاحنات بسرعة 10 أميال في الساعة"],"h1":"الطن وحدة لقياس الوزن.","h2":"لافتة «WEIGHT LIMIT» (الحد الأقصى للوزن) تعني أن المركبات التي يزيد وزنها عن الرقم المكتوب ممنوع أن تستخدم ذلك الطريق أو الجسر.","p":"صحيح. المركبات الأثقل ممنوع أن تعبر."},"ht":{"q":"Anvan yon pon, gen yon siy ki di “WEIGHT LIMIT 10 TONS” (limit pwa 10 tòn). Kisa li vle di?","o":["Machin ki peze plis pase 10 tòn pa ka travèse","Chak machin dwe kanpe pou yo peze l","Se 10 machin sèlman ki ka sou pon an","Kamyon yo dwe kondui a 10 mph"],"h1":"Yon tòn se yon mezi pou pwa.","h2":"Yon siy “WEIGHT LIMIT” (limit pwa) vle di machin ki peze plis pase kantite ki ekri a pa ka sèvi ak wout oswa pon sa a.","p":"Se sa. Machin ki pi lou yo pa ka travèse."}},{"id":"signs-073","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"LEFT TURN YIELD ON GREEN"},"c":1,"en":{"q":"Next to a traffic light, a sign says LEFT TURN YIELD ON GREEN and shows a green ball. What does it mean?","o":["On a green ball, oncoming traffic must stop for you","On a green ball, you may turn left only after letting oncoming traffic pass","You may not turn left on a green ball","Left turns are only allowed on red"],"h1":"A green ball is not a green arrow.","h2":"LEFT TURN YIELD ON GREEN means that when the light is a green ball, you may turn left but must first yield to oncoming traffic.","p":"Right. Turn left only after oncoming traffic is clear."},"es":{"q":"Junto a un semáforo, una señal dice LEFT TURN YIELD ON GREEN y muestra una bola verde. ¿Qué significa?","o":["Con la bola verde, el tráfico de frente debe pararse para usted","Con la bola verde, puede girar a la izquierda solo después de dejar pasar al tráfico de frente","No puede girar a la izquierda con la bola verde","Solo se gira a la izquierda con luz roja"],"h1":"Una bola verde no es una flecha verde.","h2":"LEFT TURN YIELD ON GREEN significa que con la bola verde puede girar a la izquierda, pero primero debe ceder el paso al tráfico que viene de frente.","p":"Correcto. Gire solo cuando el tráfico de frente haya pasado."},"zh":{"q":"红绿灯旁边有一个标志写着 “LEFT TURN YIELD ON GREEN”（绿灯左转需让行），上面有一个绿色圆灯。它是什么意思？","o":["绿色圆灯时，对面来车必须为你停车","绿色圆灯时，你要先让对面来车过去，才能左转","绿色圆灯时，你不能左转","只有红灯时才能左转"],"h1":"绿色圆灯不是绿色箭头。","h2":"“LEFT TURN YIELD ON GREEN”（绿灯左转需让行）表示绿色圆灯亮时，你可以左转，但必须先让对面来车先走。","p":"对。等对面来车过去后再左转。"},"vi":{"q":"Cạnh đèn giao thông có biển ghi “LEFT TURN YIELD ON GREEN” (Rẽ trái nhường đường khi đèn xanh) và có hình đèn xanh tròn. Biển này có nghĩa là gì?","o":["Khi đèn xanh tròn, xe đi ngược chiều phải dừng cho bạn","Khi đèn xanh tròn, bạn chỉ được rẽ trái sau khi để xe ngược chiều đi qua","Bạn không được rẽ trái khi đèn xanh tròn","Chỉ được rẽ trái khi đèn đỏ"],"h1":"Đèn xanh tròn không phải là mũi tên xanh.","h2":"“LEFT TURN YIELD ON GREEN” (Rẽ trái nhường đường khi đèn xanh) có nghĩa là khi đèn xanh tròn, bạn được rẽ trái nhưng trước hết phải nhường xe đi ngược chiều.","p":"Đúng rồi. Chỉ rẽ trái khi xe ngược chiều đã đi qua hết."},"tl":{"q":"Sa tabi ng traffic light, may karatulang nagsasabing “LEFT TURN YIELD ON GREEN” (Magbigay-daan kapag kumakaliwa sa berde) at may larawan ng berdeng bilog na ilaw. Ano ang ibig sabihin nito?","o":["Kapag berdeng bilog, dapat huminto para sa iyo ang mga paparating na sasakyan","Kapag berdeng bilog, puwede kang kumaliwa pagkatapos lang paraanin ang mga paparating na sasakyan","Hindi ka puwedeng kumaliwa kapag berdeng bilog","Puwede lang kumaliwa kapag pula"],"h1":"Ang berdeng bilog ay hindi berdeng arrow.","h2":"Ang “LEFT TURN YIELD ON GREEN” ay nangangahulugang kapag berdeng bilog ang ilaw, puwede kang kumaliwa pero dapat mo munang pagbigyan ang mga paparating na sasakyan.","p":"Tama. Kumaliwa lang kapag maluwag na mula sa mga paparating na sasakyan."},"ar":{"q":"بجانب إشارة المرور لافتة مكتوب عليها «LEFT TURN YIELD ON GREEN» (عند الانعطاف يسارًا أعطِ الأولوية في الضوء الأخضر)، وعليها دائرة خضراء. ماذا تعني؟","o":["عند الدائرة الخضراء، يجب أن تتوقف السيارات القادمة من الأمام لك","عند الدائرة الخضراء، يمكنك أن تنعطف يسارًا فقط بعد أن تترك السيارات القادمة من الأمام تمر","ممنوع أن تنعطف يسارًا عند الدائرة الخضراء","الانعطاف يسارًا مسموح فقط عند الضوء الأحمر"],"h1":"الدائرة الخضراء ليست سهمًا أخضر.","h2":"لافتة «LEFT TURN YIELD ON GREEN» تعني أنه عندما يكون الضوء دائرة خضراء، يمكنك أن تنعطف يسارًا، ولكن يجب أولًا أن تعطي الأولوية للسيارات القادمة من الأمام.","p":"صحيح. انعطف يسارًا فقط بعد أن يخلو الطريق من السيارات القادمة."},"ht":{"q":"Bò kote yon limyè trafik, gen yon siy ki di “LEFT TURN YIELD ON GREEN” (vire agoch, bay pasaj lè limyè a vèt) epi ki montre yon boul vèt. Kisa li vle di?","o":["Lè boul vèt la limen, machin k ap vini an fas yo dwe kanpe pou ou","Lè boul vèt la limen, ou ka vire agoch sèlman apre ou fin kite machin k ap vini an fas yo pase","Ou pa ka vire agoch lè boul vèt la limen","Ou ka vire agoch sèlman lè limyè a wouj"],"h1":"Yon boul vèt pa yon flèch vèt.","h2":"“LEFT TURN YIELD ON GREEN” vle di lè limyè a se yon boul vèt, ou ka vire agoch, men ou dwe bay machin k ap vini an fas yo pasaj anvan.","p":"Se sa. Vire agoch sèlman lè pa gen machin k ap vini an fas ankò."}},{"id":"signs-074","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"U-TURN YIELD TO RIGHT TURN"},"c":2,"en":{"q":"You are waiting to make a U-turn at a green arrow. A sign says U-TURN YIELD TO RIGHT TURN. What does it mean?","o":["Cars turning right must stop for you","U-turns are not allowed","Let cars turning right from the cross street go first","Make your U-turn from the right lane"],"h1":"The sign tells U-turning drivers to yield.","h2":"U-TURN YIELD TO RIGHT TURN means drivers making a U-turn must let drivers turning right from the cross street go first.","p":"Right. U-turns wait for the right-turning cars."},"es":{"q":"Usted espera para dar una vuelta en U con una flecha verde. Una señal dice U-TURN YIELD TO RIGHT TURN. ¿Qué significa?","o":["Los que giran a la derecha deben pararse para usted","No se permiten las vueltas en U","Deje pasar primero a los carros que giran a la derecha desde la calle transversal","Dé la vuelta en U desde el carril derecho"],"h1":"La señal le pide ceder el paso a quien da la vuelta en U.","h2":"U-TURN YIELD TO RIGHT TURN significa que quien da la vuelta en U debe dejar pasar primero a los que giran a la derecha desde la calle transversal.","p":"Correcto. La vuelta en U espera a los que giran a la derecha."},"zh":{"q":"你在绿色箭头灯下等着掉头。一个标志写着 “U-TURN YIELD TO RIGHT TURN”（掉头让右转）。这是什么意思？","o":["右转的车必须停下让你","不准掉头","让从横街右转的车先走","从右车道掉头"],"h1":"这个标志告诉掉头的司机要让行。","h2":"“U-TURN YIELD TO RIGHT TURN”（掉头让右转）表示掉头的司机必须让从横街右转的车先走。","p":"对。掉头的车要等右转的车。"},"vi":{"q":"Bạn đang chờ quay đầu xe khi có đèn mũi tên xanh. Một biển ghi “U-TURN YIELD TO RIGHT TURN” (Quay đầu nhường xe rẽ phải). Biển này có nghĩa là gì?","o":["Xe rẽ phải phải dừng lại cho bạn","Không được quay đầu xe","Để xe rẽ phải từ đường ngang đi trước","Quay đầu xe từ làn bên phải"],"h1":"Biển này bảo người quay đầu xe phải nhường đường.","h2":"“U-TURN YIELD TO RIGHT TURN” (Quay đầu nhường xe rẽ phải) có nghĩa là người quay đầu xe phải để xe rẽ phải từ đường ngang đi trước.","p":"Đúng rồi. Xe quay đầu phải chờ xe rẽ phải."},"tl":{"q":"Naghihintay kang mag-U-turn sa berdeng arrow. May karatulang “U-TURN YIELD TO RIGHT TURN” (Ang mag-U-turn ay magbigay-daan sa kakanan). Ano ang ibig sabihin nito?","o":["Ang mga kakanang sasakyan ay dapat huminto para sa iyo","Bawal ang U-turn","Paunahin ang mga sasakyang kumakanan mula sa krus na kalye","Mag-U-turn mula sa kanang lane"],"h1":"Sinasabi ng karatula na magbigay-daan ang mga nag-U-U-turn.","h2":"Ang “U-TURN YIELD TO RIGHT TURN” ay nangangahulugang ang mga nag-U-U-turn ay dapat magpauna sa mga sasakyang kumakanan mula sa krus na kalye.","p":"Tama. Ang nag-U-U-turn ay maghihintay sa mga kumakanan."},"ar":{"q":"أنت تنتظر لتستدير للخلف (U-turn) عند سهم أخضر. لافتة مكتوب عليها «U-TURN YIELD TO RIGHT TURN» (الاستدارة للخلف تعطي الأولوية للمنعطف يمينًا). ماذا تعني؟","o":["السيارات التي تنعطف يمينًا يجب أن تتوقف لك","الاستدارة للخلف ممنوعة","دع السيارات التي تنعطف يمينًا من الشارع المتقاطع تمر أولًا","استدر للخلف من المسار الأيمن"],"h1":"اللافتة تطلب من السائقين الذين يستديرون للخلف أن يعطوا الأولوية.","h2":"لافتة «U-TURN YIELD TO RIGHT TURN» تعني أن السائق الذي يستدير للخلف يجب أن يترك السيارات التي تنعطف يمينًا من الشارع المتقاطع تمر أولًا.","p":"صحيح. من يستدير للخلف ينتظر السيارات التي تنعطف يمينًا."},"ht":{"q":"W ap tann pou fè yon U-turn (vire tounen) lè flèch vèt la limen. Yon siy di “U-TURN YIELD TO RIGHT TURN” (U-turn bay pasaj a moun k ap vire adwat). Kisa li vle di?","o":["Machin k ap vire adwat yo dwe kanpe pou ou","U-turn entèdi","Kite machin k ap vire adwat soti nan lari travès la pase anvan","Fè U-turn ou soti nan liy adwat la"],"h1":"Siy la di chofè k ap fè U-turn yo pou yo bay pasaj.","h2":"“U-TURN YIELD TO RIGHT TURN” vle di chofè k ap fè U-turn dwe kite machin k ap vire adwat soti nan lari travès la pase anvan.","p":"Se sa. U-turn yo tann machin k ap vire adwat yo."}},{"id":"signs-075","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"STOP HERE ON RED"},"c":3,"en":{"q":"A white sign says STOP HERE ON RED and points to a line on the road. What does it mean?","o":["Stop at that line even when the light is green","Turn right at that line on red","Park at that line","When the light is red, stop at that line"],"h1":"The sign tells you where to wait.","h2":"STOP HERE ON RED means that when the traffic light is red, you must stop at the line the sign points to.","p":"Right. On red, stop at the line."},"es":{"q":"Una señal blanca dice STOP HERE ON RED y apunta a una línea en la vía. ¿Qué significa?","o":["Párese en esa línea aun con luz verde","Gire a la derecha en esa línea con luz roja","Estaciónese en esa línea","Cuando la luz está en rojo, párese en esa línea"],"h1":"La señal le dice dónde esperar.","h2":"STOP HERE ON RED significa que cuando el semáforo está en rojo debe pararse en la línea que indica la señal.","p":"Correcto. Con rojo, párese en la línea."},"zh":{"q":"一个白色标志写着 “STOP HERE ON RED”（红灯在此停车），并指向路面上的一条线。这是什么意思？","o":["即使绿灯也要在那条线停车","红灯时在那条线右转","在那条线停车泊车","红灯时，在那条线停车"],"h1":"这个标志告诉你在哪里等。","h2":"“STOP HERE ON RED”（红灯在此停车）表示红灯时，你必须停在标志所指的那条线前。","p":"对。红灯时，在线前停车。"},"vi":{"q":"Một biển màu trắng ghi “STOP HERE ON RED” (Dừng ở đây khi đèn đỏ) và chỉ vào một vạch trên đường. Biển này có nghĩa là gì?","o":["Dừng ở vạch đó ngay cả khi đèn xanh","Rẽ phải ở vạch đó khi đèn đỏ","Đậu xe ở vạch đó","Khi đèn đỏ, dừng ở vạch đó"],"h1":"Biển này cho bạn biết phải chờ ở đâu.","h2":"“STOP HERE ON RED” (Dừng ở đây khi đèn đỏ) có nghĩa là khi đèn giao thông màu đỏ, bạn phải dừng ở vạch mà biển chỉ vào.","p":"Đúng rồi. Khi đèn đỏ, dừng ở vạch."},"tl":{"q":"May puting karatula na “STOP HERE ON RED” (Huminto rito kapag pula) at nakaturo sa isang guhit sa kalsada. Ano ang ibig sabihin nito?","o":["Huminto sa guhit na iyon kahit berde ang ilaw","Kumanan sa guhit na iyon kapag pula","Pumarada sa guhit na iyon","Kapag pula ang ilaw, huminto sa guhit na iyon"],"h1":"Sinasabi ng karatula kung saan ka maghihintay.","h2":"Ang “STOP HERE ON RED” ay nangangahulugang kapag pula ang ilaw-trapiko, dapat kang huminto sa guhit na itinuturo ng karatula.","p":"Tama. Kapag pula, huminto sa guhit."},"ar":{"q":"لافتة بيضاء مكتوب عليها «STOP HERE ON RED» (قف هنا عند الأحمر) وتشير إلى خط على الطريق. ماذا تعني؟","o":["توقف عند ذلك الخط حتى عندما تكون الإشارة خضراء","انعطف يمينًا عند ذلك الخط عند الأحمر","اركن سيارتك عند ذلك الخط","عندما تكون الإشارة حمراء، توقف عند ذلك الخط"],"h1":"اللافتة تخبرك أين تنتظر.","h2":"لافتة «STOP HERE ON RED» تعني أنه عندما تكون إشارة المرور حمراء، يجب أن تتوقف عند الخط الذي تشير إليه اللافتة.","p":"صحيح. عند الأحمر، توقف عند الخط."},"ht":{"q":"Yon siy blan di “STOP HERE ON RED” (kanpe isit la lè limyè a wouj) epi li montre yon liy sou wout la. Kisa li vle di?","o":["Kanpe nan liy sa a menm lè limyè a vèt","Vire adwat nan liy sa a lè limyè a wouj","Pake nan liy sa a","Lè limyè a wouj, kanpe nan liy sa a"],"h1":"Siy la di ou ki kote pou ou tann.","h2":"“STOP HERE ON RED” vle di lè limyè trafik la wouj, ou dwe kanpe nan liy siy la montre a.","p":"Se sa. Lè li wouj, kanpe nan liy lan."}},{"id":"signs-076","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"STEEP HILL"},"c":0,"en":{"q":"A yellow sign shows a truck on a slope. What does it warn you about?","o":["A steep downhill road ahead","A truck stop ahead","Trucks are not allowed","A truck crossing ahead"],"h1":"Look at the slope under the truck.","h2":"The Hill sign warns of a steep downhill grade ahead, so check your speed and use a lower gear to save your brakes.","p":"Right. A steep downhill is ahead."},"es":{"q":"Una señal amarilla muestra un camión en una pendiente. ¿De qué le advierte?","o":["De una bajada empinada más adelante","De una parada de camiones más adelante","De que no se permiten camiones","De un cruce de camiones más adelante"],"h1":"Fíjese en la pendiente debajo del camión.","h2":"La señal de pendiente advierte de una bajada empinada más adelante, así que controle su velocidad y use un cambio más bajo para cuidar los frenos.","p":"Correcto. Viene una bajada empinada."},"zh":{"q":"一个黄色标志上画着一辆卡车在斜坡上。它在警告你什么？","o":["前方有陡峭的下坡路","前方有卡车停车站","不准卡车通行","前方有卡车穿过"],"h1":"看卡车下面的斜坡。","h2":"陡坡标志警告前方有陡峭的下坡，所以要注意车速，换低速挡，保护刹车。","p":"对。前方是陡峭的下坡。"},"vi":{"q":"Một biển màu vàng có hình xe tải trên dốc. Biển này cảnh báo bạn điều gì?","o":["Đoạn đường xuống dốc gắt phía trước","Trạm dừng xe tải phía trước","Cấm xe tải","Xe tải băng ngang đường phía trước"],"h1":"Hãy nhìn con dốc dưới chiếc xe tải.","h2":"Biển báo dốc cảnh báo có đoạn xuống dốc gắt phía trước, nên hãy kiểm tra tốc độ và dùng số thấp để giữ thắng.","p":"Đúng rồi. Phía trước có dốc xuống gắt."},"tl":{"q":"May dilaw na karatula na may larawan ng trak sa dalisdis. Ano ang babala nito sa iyo?","o":["Matarik na pababang daan sa unahan","Hintuan ng trak sa unahan","Bawal ang trak","Tawiran ng trak sa unahan"],"h1":"Tingnan ang dalisdis sa ilalim ng trak.","h2":"Ang karatulang Hill (Burol) ay nagbababala ng matarik na pababang daan sa unahan, kaya bantayan ang iyong bilis at gumamit ng mas mababang gear para hindi mapagod ang preno.","p":"Tama. May matarik na pababa sa unahan."},"ar":{"q":"لافتة صفراء عليها شاحنة على منحدر. مِمَّ تحذّرك؟","o":["طريق منحدر شديد نحو الأسفل في الأمام","موقف للشاحنات في الأمام","الشاحنات ممنوعة","معبر للشاحنات في الأمام"],"h1":"انظر إلى المنحدر تحت الشاحنة.","h2":"لافتة المنحدر تحذّر من نزول شديد في الأمام، لذلك راقب سرعتك واستخدم غيارًا منخفضًا لتحافظ على الفرامل.","p":"صحيح. هناك نزول شديد في الأمام."},"ht":{"q":"Yon siy jòn montre yon kamyon sou yon pant. Kisa li avèti ou?","o":["Yon wout ki desann rèd pi devan","Yon kote kamyon kanpe pi devan","Kamyon pa gen dwa pase","Kamyon k ap travèse pi devan"],"h1":"Gade pant ki anba kamyon an.","h2":"Siy Hill (mòn) la avèti gen yon desant rèd pi devan, kidonk veye vitès ou epi sèvi ak yon vitès ba pou ou pa fatige fren yo.","p":"Se sa. Gen yon desant rèd pi devan."}},{"id":"signs-077","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"HILL BLOCKS VIEW"},"c":1,"en":{"q":"A yellow sign says HILL BLOCKS VIEW. What should you do?","o":["Speed up to get over the hill quickly","Slow down, keep right, and be ready for something you cannot see yet","Pass the car ahead before the top","Move to the center of the road"],"h1":"You cannot see what is over the top of the hill.","h2":"HILL BLOCKS VIEW warns that the hill hides traffic or hazards beyond it, so slow down, keep right and be ready to stop.","p":"Right. Slow down and keep right."},"es":{"q":"Una señal amarilla dice HILL BLOCKS VIEW. ¿Qué debe hacer?","o":["Acelerar para pasar la loma rápido","Bajar la velocidad, mantenerse a la derecha y estar listo para algo que aún no ve","Rebasar al carro de adelante antes de la cima","Ir por el centro de la vía"],"h1":"Usted no puede ver lo que hay detrás de la cima.","h2":"HILL BLOCKS VIEW advierte que la loma oculta el tráfico o peligros del otro lado, así que baje la velocidad, manténgase a la derecha y esté listo para pararse.","p":"Correcto. Baje la velocidad y vaya a la derecha."},"zh":{"q":"一个黄色标志写着 “HILL BLOCKS VIEW”（山坡挡住视线）。你应该怎么做？","o":["加速，快速开过山坡","减速，靠右行驶，并准备应对你还看不到的东西","在坡顶前超过前面的车","开到道路中间"],"h1":"你看不到坡顶另一边有什么。","h2":"“HILL BLOCKS VIEW”（山坡挡住视线）警告山坡挡住了后面的车辆或危险，所以要减速，靠右行驶，并准备停车。","p":"对。减速并靠右。"},"vi":{"q":"Một biển màu vàng ghi “HILL BLOCKS VIEW” (Đồi che tầm nhìn). Bạn nên làm gì?","o":["Tăng tốc để qua đồi cho nhanh","Chạy chậm lại, đi sát bên phải, và sẵn sàng cho điều bạn chưa thấy","Vượt xe phía trước trước khi lên đỉnh","Chạy vào giữa đường"],"h1":"Bạn không thấy được những gì ở bên kia đỉnh đồi.","h2":"“HILL BLOCKS VIEW” (Đồi che tầm nhìn) cảnh báo ngọn đồi che khuất xe cộ hoặc nguy hiểm phía sau nó, nên hãy chạy chậm lại, đi sát bên phải và sẵn sàng dừng.","p":"Đúng rồi. Chạy chậm và đi sát bên phải."},"tl":{"q":"May dilaw na karatula na “HILL BLOCKS VIEW” (Natatakpan ng burol ang tanaw). Ano ang dapat mong gawin?","o":["Bumilis para mabilis na makalampas sa burol","Bumagal, manatili sa kanan, at maging handa sa bagay na hindi mo pa nakikita","Lampasan ang sasakyan sa unahan bago ang tuktok","Lumipat sa gitna ng kalsada"],"h1":"Hindi mo makita kung ano ang nasa kabila ng tuktok ng burol.","h2":"Ang “HILL BLOCKS VIEW” ay nagbababala na tinatakpan ng burol ang trapiko o panganib sa kabila nito, kaya bumagal, manatili sa kanan, at maging handang huminto.","p":"Tama. Bumagal at manatili sa kanan."},"ar":{"q":"لافتة صفراء مكتوب عليها «HILL BLOCKS VIEW» (التل يحجب الرؤية). ماذا يجب أن تفعل؟","o":["زد السرعة لتعبر التل بسرعة","خفف السرعة، والزم اليمين، وكن مستعدًا لشيء لا تراه بعد","تجاوز السيارة التي أمامك قبل القمة","تحرّك إلى وسط الطريق"],"h1":"لا يمكنك أن ترى ما وراء قمة التل.","h2":"لافتة «HILL BLOCKS VIEW» تحذّر من أن التل يخفي السيارات أو المخاطر التي وراءه، لذلك خفف السرعة والزم اليمين وكن مستعدًا للتوقف.","p":"صحيح. خفف السرعة والزم اليمين."},"ht":{"q":"Yon siy jòn di “HILL BLOCKS VIEW” (mòn nan bloke vi a). Kisa ou dwe fè?","o":["Akselere pou travèse mòn nan vit","Ralanti, rete adwat, epi pare pou yon bagay ou poko ka wè","Double machin ki devan an anvan tèt mòn nan","Ale nan mitan wout la"],"h1":"Ou pa ka wè sa ki lòt bò tèt mòn nan.","h2":"“HILL BLOCKS VIEW” avèti mòn nan kache machin oswa danje ki dèyè l, kidonk ralanti, rete adwat epi pare pou kanpe.","p":"Se sa. Ralanti epi rete adwat."}},{"id":"signs-078","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"ROAD NARROWS"},"c":2,"en":{"q":"What does a yellow sign that says ROAD NARROWS warn you about?","o":["The road ends ahead","A lane is added ahead","The road ahead gets narrower","A one-way road starts"],"h1":"Narrow means less wide.","h2":"ROAD NARROWS warns that the road becomes narrower ahead, so slow down and watch for cars beside and coming toward you.","p":"Right. The road gets narrower."},"es":{"q":"¿De qué le advierte una señal amarilla que dice ROAD NARROWS?","o":["De que la vía termina","De que se agrega un carril","De que la vía se hace más angosta","De que empieza una vía de un solo sentido"],"h1":"Narrow quiere decir angosto.","h2":"ROAD NARROWS advierte que la vía se vuelve más angosta adelante, así que baje la velocidad y fíjese en los carros a su lado y de frente.","p":"Correcto. La vía se hace más angosta."},"zh":{"q":"写着 “ROAD NARROWS”（道路变窄）的黄色标志在警告你什么？","o":["道路在前方结束","前方增加一条车道","前方道路变窄","单行道开始"],"h1":"窄就是不那么宽。","h2":"“ROAD NARROWS”（道路变窄）警告前方道路会变窄，所以要减速，注意旁边和对面开来的车。","p":"对。道路变窄了。"},"vi":{"q":"Biển màu vàng ghi “ROAD NARROWS” (Đường hẹp lại) cảnh báo bạn điều gì?","o":["Con đường kết thúc phía trước","Có thêm một làn xe phía trước","Con đường phía trước hẹp lại","Bắt đầu đường một chiều"],"h1":"Hẹp nghĩa là ít rộng hơn.","h2":"“ROAD NARROWS” (Đường hẹp lại) cảnh báo con đường phía trước sẽ hẹp hơn, nên hãy chạy chậm lại và chú ý xe bên cạnh và xe chạy ngược chiều tới.","p":"Đúng rồi. Con đường hẹp lại."},"tl":{"q":"Ano ang babala ng dilaw na karatulang “ROAD NARROWS” (Kumikitid ang kalsada)?","o":["Natatapos ang kalsada sa unahan","May dagdag na lane sa unahan","Kumikitid ang kalsada sa unahan","Nagsisimula ang one-way na kalsada"],"h1":"Ang makitid ay hindi gaanong malapad.","h2":"Ang “ROAD NARROWS” ay nagbababala na kumikitid ang kalsada sa unahan, kaya bumagal at bantayan ang mga sasakyan sa tabi mo at ang mga paparating.","p":"Tama. Kumikitid ang kalsada."},"ar":{"q":"مِمَّ تحذّرك لافتة صفراء مكتوب عليها «ROAD NARROWS» (الطريق يضيق)؟","o":["الطريق ينتهي في الأمام","يُضاف مسار في الأمام","الطريق في الأمام يصبح أضيق","يبدأ طريق باتجاه واحد"],"h1":"الضيق يعني أقل عرضًا.","h2":"لافتة «ROAD NARROWS» تحذّر من أن الطريق يصبح أضيق في الأمام، لذلك خفف السرعة وانتبه للسيارات التي بجانبك والقادمة نحوك.","p":"صحيح. الطريق يصبح أضيق."},"ht":{"q":"Kisa yon siy jòn ki di “ROAD NARROWS” (wout la vin pi etwat) avèti ou?","o":["Wout la fini pi devan","Gen yon liy anplis pi devan","Wout la vin pi etwat pi devan","Yon wout sans inik kòmanse"],"h1":"Etwat vle di mwens laj.","h2":"“ROAD NARROWS” avèti wout la ap vin pi etwat pi devan, kidonk ralanti epi veye machin ki bò kote ou ak sa k ap vin sou ou.","p":"Se sa. Wout la vin pi etwat."}},{"id":"signs-079","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"ONE LANE BRIDGE"},"c":3,"en":{"q":"A yellow sign says ONE LANE BRIDGE. What should you expect?","o":["The bridge has one lane in each direction","Only trucks may use the bridge","The bridge is closed","Only one vehicle at a time can cross, so you may need to wait"],"h1":"Think about cars coming from the other side.","h2":"ONE LANE BRIDGE means the bridge is wide enough for only one vehicle at a time, so be ready to yield to a car already on it.","p":"Right. One car at a time; be ready to wait."},"es":{"q":"Una señal amarilla dice ONE LANE BRIDGE. ¿Qué debe esperar?","o":["El puente tiene un carril en cada sentido","Solo los camiones pueden usar el puente","El puente está cerrado","Solo cabe un vehículo a la vez, así que quizás deba esperar"],"h1":"Piense en los carros que vienen del otro lado.","h2":"ONE LANE BRIDGE significa que el puente solo tiene espacio para un vehículo a la vez, así que esté listo para ceder el paso a quien ya esté cruzando.","p":"Correcto. Un carro a la vez; esté listo para esperar."},"zh":{"q":"一个黄色标志写着 “ONE LANE BRIDGE”（单车道桥）。你应该预料到什么？","o":["这座桥每个方向各有一条车道","只有卡车可以走这座桥","这座桥封闭了","一次只能有一辆车通过，所以你可能要等"],"h1":"想一想从对面开来的车。","h2":"“ONE LANE BRIDGE”（单车道桥）表示这座桥一次只够一辆车通过，所以要准备好让已经在桥上的车先走。","p":"对。一次一辆车；准备好等一等。"},"vi":{"q":"Một biển màu vàng ghi “ONE LANE BRIDGE” (Cầu một làn). Bạn nên chờ đợi điều gì?","o":["Cầu có một làn cho mỗi chiều","Chỉ xe tải được đi qua cầu","Cầu bị đóng","Mỗi lần chỉ một xe qua được, nên bạn có thể phải chờ"],"h1":"Hãy nghĩ đến xe đi tới từ phía bên kia.","h2":"“ONE LANE BRIDGE” (Cầu một làn) có nghĩa là cầu chỉ đủ rộng cho một xe mỗi lần, nên hãy sẵn sàng nhường cho xe đang ở trên cầu.","p":"Đúng rồi. Mỗi lần một xe; sẵn sàng chờ."},"tl":{"q":"May dilaw na karatula na “ONE LANE BRIDGE” (Tulay na may isang lane). Ano ang dapat mong asahan?","o":["May isang lane ang tulay sa bawat direksyon","Trak lang ang puwede sa tulay","Sarado ang tulay","Isang sasakyan lang ang makakatawid sa bawat pagkakataon, kaya baka kailangan mong maghintay"],"h1":"Isipin ang mga sasakyang galing sa kabilang dulo.","h2":"Ang “ONE LANE BRIDGE” ay nangangahulugang kasya lang ang isang sasakyan sa tulay sa bawat pagkakataon, kaya maging handang magpauna sa sasakyang nasa tulay na.","p":"Tama. Isang sasakyan sa bawat pagkakataon; maging handang maghintay."},"ar":{"q":"لافتة صفراء مكتوب عليها «ONE LANE BRIDGE» (جسر بمسار واحد). ماذا يجب أن تتوقع؟","o":["الجسر فيه مسار واحد لكل اتجاه","الشاحنات فقط يمكنها استخدام الجسر","الجسر مغلق","تعبر سيارة واحدة فقط في كل مرة، لذلك قد تحتاج إلى الانتظار"],"h1":"فكّر في السيارات القادمة من الجهة الأخرى.","h2":"لافتة «ONE LANE BRIDGE» تعني أن الجسر يتسع لسيارة واحدة فقط في كل مرة، لذلك كن مستعدًا لإعطاء الأولوية لسيارة موجودة عليه.","p":"صحيح. سيارة واحدة في كل مرة؛ كن مستعدًا للانتظار."},"ht":{"q":"Yon siy jòn di “ONE LANE BRIDGE” (pon ki gen yon sèl liy). Kisa ou dwe atann?","o":["Pon an gen yon liy nan chak direksyon","Se sèlman kamyon ki ka sèvi ak pon an","Pon an fèmen","Se yon sèl machin alafwa ki ka travèse, kidonk ou ka bezwen tann"],"h1":"Panse ak machin k ap vini lòt bò a.","h2":"“ONE LANE BRIDGE” vle di pon an laj ase pou yon sèl machin alafwa sèlman, kidonk pare pou bay pasaj a yon machin ki deja sou li.","p":"Se sa. Yon machin alafwa; pare pou tann."}},{"id":"signs-080","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"NARROW BRIDGE"},"c":0,"en":{"q":"What does a yellow sign that says NARROW BRIDGE mean?","o":["The bridge is narrower than the road before it","The bridge is closed to cars","The bridge may open for boats","The bridge has no railing"],"h1":"Narrow means less wide.","h2":"NARROW BRIDGE warns that the bridge is narrower than the road leading to it, so slow down and stay in your lane.","p":"Right. The bridge is narrower than the road."},"es":{"q":"¿Qué significa una señal amarilla que dice NARROW BRIDGE?","o":["El puente es más angosto que la vía antes de él","El puente está cerrado a los carros","El puente puede abrirse para barcos","El puente no tiene baranda"],"h1":"Narrow quiere decir angosto.","h2":"NARROW BRIDGE advierte que el puente es más angosto que la vía que lleva a él, así que baje la velocidad y quédese en su carril.","p":"Correcto. El puente es más angosto que la vía."},"zh":{"q":"写着 “NARROW BRIDGE”（窄桥）的黄色标志是什么意思？","o":["这座桥比前面的道路窄","这座桥不准汽车通行","这座桥可能会为船打开","这座桥没有栏杆"],"h1":"窄就是不那么宽。","h2":"“NARROW BRIDGE”（窄桥）警告这座桥比通往它的道路窄，所以要减速，留在自己的车道里。","p":"对。桥比道路窄。"},"vi":{"q":"Biển màu vàng ghi “NARROW BRIDGE” (Cầu hẹp) có nghĩa là gì?","o":["Cầu hẹp hơn đoạn đường trước nó","Cầu cấm xe hơi","Cầu có thể mở ra cho tàu thuyền","Cầu không có lan can"],"h1":"Hẹp nghĩa là ít rộng hơn.","h2":"“NARROW BRIDGE” (Cầu hẹp) cảnh báo cây cầu hẹp hơn con đường dẫn tới nó, nên hãy chạy chậm lại và giữ trong làn của mình.","p":"Đúng rồi. Cầu hẹp hơn con đường."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatulang “NARROW BRIDGE” (Makitid na tulay)?","o":["Mas makitid ang tulay kaysa sa kalsada bago ito","Bawal ang kotse sa tulay","Maaaring bumukas ang tulay para sa mga bangka","Walang barandilya ang tulay"],"h1":"Ang makitid ay hindi gaanong malapad.","h2":"Ang “NARROW BRIDGE” ay nagbababala na mas makitid ang tulay kaysa sa kalsadang papunta rito, kaya bumagal at manatili sa iyong lane.","p":"Tama. Mas makitid ang tulay kaysa sa kalsada."},"ar":{"q":"ماذا تعني لافتة صفراء مكتوب عليها «NARROW BRIDGE» (جسر ضيق)؟","o":["الجسر أضيق من الطريق الذي قبله","الجسر مغلق أمام السيارات","قد يُفتح الجسر لمرور القوارب","الجسر ليس له حاجز جانبي"],"h1":"الضيق يعني أقل عرضًا.","h2":"لافتة «NARROW BRIDGE» تحذّر من أن الجسر أضيق من الطريق المؤدي إليه، لذلك خفف السرعة وابقَ في مسارك.","p":"صحيح. الجسر أضيق من الطريق."},"ht":{"q":"Kisa yon siy jòn ki di “NARROW BRIDGE” (pon etwat) vle di?","o":["Pon an pi etwat pase wout ki anvan l lan","Pon an fèmen pou machin","Pon an ka louvri pou bato pase","Pon an pa gen balistrad"],"h1":"Etwat vle di mwens laj.","h2":"“NARROW BRIDGE” avèti pon an pi etwat pase wout ki mennen ladan l lan, kidonk ralanti epi rete nan liy ou.","p":"Se sa. Pon an pi etwat pase wout la."}},{"id":"signs-081","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"NO OUTLET"},"c":1,"en":{"q":"A yellow sign at the start of a street says NO OUTLET. What does it mean?","o":["The street has no parking","There is no other way out; you will have to come back the same way","The street has no sidewalks","The street is one-way"],"h1":"An outlet is a way out.","h2":"NO OUTLET means the street, or the group of streets it leads into, has no other way out, so you will have to come back the same way.","p":"Right. There is no way through."},"es":{"q":"Una señal amarilla al principio de una calle dice NO OUTLET. ¿Qué significa?","o":["La calle no tiene estacionamiento","No hay otra salida; tendrá que regresar por el mismo camino","La calle no tiene aceras","La calle es de un solo sentido"],"h1":"Outlet es una salida.","h2":"NO OUTLET significa que la calle, o el grupo de calles al que lleva, no tiene otra salida, así que tendrá que regresar por el mismo camino.","p":"Correcto. No tiene salida."},"zh":{"q":"街口有一个黄色标志写着 “NO OUTLET”（无出口）。这是什么意思？","o":["这条街不能停车","没有别的出路；你得原路返回","这条街没有人行道","这条街是单行道"],"h1":"出口就是出去的路。","h2":"“NO OUTLET”（无出口）表示这条街，或它通往的那几条街，没有别的出路，所以你得原路返回。","p":"对。这里走不通。"},"vi":{"q":"Một biển màu vàng ở đầu một con đường ghi “NO OUTLET” (Không có lối ra). Biển này có nghĩa là gì?","o":["Con đường không có chỗ đậu xe","Không có lối ra nào khác; bạn sẽ phải quay lại đường cũ","Con đường không có vỉa hè","Con đường là đường một chiều"],"h1":"Lối ra là đường để đi ra.","h2":"“NO OUTLET” (Không có lối ra) có nghĩa là con đường, hoặc khu đường mà nó dẫn vào, không có lối ra nào khác, nên bạn sẽ phải quay lại đường cũ.","p":"Đúng rồi. Không có đường đi xuyên qua."},"tl":{"q":"May dilaw na karatula sa simula ng isang kalye na “NO OUTLET” (Walang labasan). Ano ang ibig sabihin nito?","o":["Walang paradahan sa kalye","Wala nang ibang labasan; kailangan mong bumalik sa dinaanan mo","Walang bangketa ang kalye","One-way ang kalye"],"h1":"Ang outlet ay daan palabas.","h2":"Ang “NO OUTLET” ay nangangahulugang ang kalye, o ang mga kalyeng pinapasukan nito, ay walang ibang labasan, kaya kailangan mong bumalik sa dinaanan mo.","p":"Tama. Walang daang tagos."},"ar":{"q":"لافتة صفراء في بداية شارع مكتوب عليها «NO OUTLET» (لا مخرج). ماذا تعني؟","o":["الشارع ليس فيه مواقف","لا يوجد طريق آخر للخروج؛ ستضطر إلى العودة من الطريق نفسه","الشارع ليس فيه أرصفة للمشاة","الشارع باتجاه واحد"],"h1":"المخرج هو طريق للخروج.","h2":"لافتة «NO OUTLET» تعني أن الشارع، أو مجموعة الشوارع التي يؤدي إليها، ليس له طريق آخر للخروج، لذلك ستضطر إلى العودة من الطريق نفسه.","p":"صحيح. لا يوجد طريق نافذ."},"ht":{"q":"Yon siy jòn nan kòmansman yon lari di “NO OUTLET” (pa gen sòti). Kisa li vle di?","o":["Pa gen kote pou pake nan lari a","Pa gen lòt kote pou soti; w ap oblije tounen menm wout la","Lari a pa gen twotwa","Lari a se sans inik"],"h1":"Yon outlet se yon kote pou soti.","h2":"“NO OUTLET” vle di lari a, oswa gwoup lari li mennen ladan yo, pa gen lòt kote pou soti, kidonk w ap oblije tounen menm wout la.","p":"Se sa. Pa gen wout pou travèse."}},{"id":"signs-082","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DIP"},"c":2,"en":{"q":"A yellow sign says DIP. What does it warn you about?","o":["A bump that will lift your car","A place to stop and rest","A sharp low spot in the road ahead","A sharp curve to the left"],"h1":"A dip goes down, then up.","h2":"A DIP sign warns of a sharp low spot in the road ahead, so slow down to keep control of your car.","p":"Right. A low spot is ahead."},"es":{"q":"Una señal amarilla dice DIP. ¿De qué le advierte?","o":["De un tope que levantará su carro","De un lugar para descansar","Una parte baja y brusca en la vía más adelante","De una curva cerrada a la izquierda"],"h1":"Un dip baja y luego sube.","h2":"Una señal DIP advierte de una parte baja y brusca en la vía más adelante, así que baje la velocidad para no perder el control del carro.","p":"Correcto. Viene una parte baja."},"zh":{"q":"一个黄色标志写着 “DIP”（凹路）。它在警告你什么？","o":["一个会把车抬起的凸起","一个可以停下休息的地方","前方路面有一个突然低下去的地方","向左的急弯"],"h1":"凹路是先往下，再往上。","h2":"“DIP”（凹路）标志警告前方路面有一个突然低下去的地方，所以要减速，控制好你的车。","p":"对。前方有一个低洼处。"},"vi":{"q":"Một biển màu vàng ghi “DIP” (Đường trũng). Biển này cảnh báo bạn điều gì?","o":["Một gờ nổi sẽ nâng xe bạn lên","Một chỗ để dừng nghỉ","Một chỗ trũng đột ngột trên đường phía trước","Một khúc cua gắt sang trái"],"h1":"Chỗ trũng đi xuống, rồi đi lên.","h2":"Biển “DIP” (Đường trũng) cảnh báo có một chỗ trũng đột ngột trên đường phía trước, nên hãy chạy chậm lại để giữ được xe.","p":"Đúng rồi. Phía trước có chỗ trũng."},"tl":{"q":"May dilaw na karatula na “DIP” (Lubog). Ano ang babala nito sa iyo?","o":["Isang umbok na mag-aangat sa kotse mo","Isang lugar para huminto at magpahinga","Isang biglang lubog na bahagi ng kalsada sa unahan","Isang matalim na kurba pakaliwa"],"h1":"Ang lubog ay bumababa, saka umaakyat.","h2":"Ang karatulang “DIP” ay nagbababala ng biglang lubog na bahagi ng kalsada sa unahan, kaya bumagal para makontrol mo ang iyong sasakyan.","p":"Tama. May lubog sa unahan."},"ar":{"q":"لافتة صفراء مكتوب عليها «DIP» (انخفاض). مِمَّ تحذّرك؟","o":["مطب سيرفع سيارتك","مكان للتوقف والاستراحة","انخفاض حاد في الطريق في الأمام","منعطف حاد إلى اليسار"],"h1":"الانخفاض ينزل ثم يصعد.","h2":"لافتة «DIP» تحذّر من انخفاض حاد في الطريق في الأمام، لذلك خفف السرعة لتحافظ على السيطرة على سيارتك.","p":"صحيح. هناك انخفاض في الأمام."},"ht":{"q":"Yon siy jòn di “DIP” (twou desann). Kisa li avèti ou?","o":["Yon bòs ki pral leve machin ou","Yon kote pou kanpe pran repo","Yon kote ki desann sanzatann nan wout la pi devan","Yon koub sere sou bò gòch"],"h1":"Yon dip desann, epi li remonte.","h2":"Yon siy “DIP” avèti gen yon kote ki desann sanzatann nan wout la pi devan, kidonk ralanti pou ou kontwole machin ou.","p":"Se sa. Gen yon kote ki ba pi devan."}},{"id":"signs-083","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"PAVEMENT ENDS"},"c":3,"en":{"q":"What does a yellow sign that says PAVEMENT ENDS warn you about?","o":["The road ends at a wall","The sidewalk ends","Road painting is finished","The paved road changes to gravel or dirt"],"h1":"Pavement is the hard road surface.","h2":"PAVEMENT ENDS warns that the hard road surface is ending and gravel or dirt begins, so slow down before you reach it.","p":"Right. Gravel or dirt starts ahead."},"es":{"q":"¿De qué le advierte una señal amarilla que dice PAVEMENT ENDS?","o":["De que la vía termina en un muro","De que termina la acera","De que terminó la pintura de la vía","De que la vía pavimentada cambia a grava o tierra"],"h1":"Pavement es la superficie dura de la vía.","h2":"PAVEMENT ENDS advierte que termina la superficie pavimentada y empieza grava o tierra, así que baje la velocidad antes de llegar.","p":"Correcto. Viene grava o tierra."},"zh":{"q":"写着 “PAVEMENT ENDS”（铺装路面结束）的黄色标志在警告你什么？","o":["道路在一堵墙前结束","人行道结束","道路画线完成了","铺装的道路变成碎石路或土路"],"h1":"铺装路面就是坚硬的路面。","h2":"“PAVEMENT ENDS”（铺装路面结束）警告坚硬的路面要结束了，接下来是碎石或泥土，所以到那里之前要减速。","p":"对。前方开始是碎石路或土路。"},"vi":{"q":"Biển màu vàng ghi “PAVEMENT ENDS” (Hết mặt đường nhựa) cảnh báo bạn điều gì?","o":["Con đường kết thúc ở một bức tường","Vỉa hè kết thúc","Việc sơn đường đã xong","Đường nhựa chuyển thành đường sỏi hoặc đường đất"],"h1":"Mặt đường nhựa là mặt đường cứng.","h2":"“PAVEMENT ENDS” (Hết mặt đường nhựa) cảnh báo mặt đường cứng sắp hết và bắt đầu là sỏi hoặc đất, nên hãy chạy chậm lại trước khi tới đó.","p":"Đúng rồi. Phía trước bắt đầu là sỏi hoặc đất."},"tl":{"q":"Ano ang babala ng dilaw na karatulang “PAVEMENT ENDS” (Tapos na ang sementadong daan)?","o":["Natatapos ang kalsada sa isang pader","Natatapos ang bangketa","Tapos na ang pagpipintura ng kalsada","Nagiging graba o lupa ang sementadong kalsada"],"h1":"Ang pavement ay ang matigas na ibabaw ng kalsada.","h2":"Ang “PAVEMENT ENDS” ay nagbababala na natatapos na ang matigas na ibabaw ng kalsada at nagsisimula ang graba o lupa, kaya bumagal bago ka makarating doon.","p":"Tama. Graba o lupa ang nagsisimula sa unahan."},"ar":{"q":"مِمَّ تحذّرك لافتة صفراء مكتوب عليها «PAVEMENT ENDS» (نهاية الطريق المعبّد)؟","o":["الطريق ينتهي عند جدار","الرصيف ينتهي","انتهى طلاء الطريق","الطريق المعبّد يتحول إلى حصى أو تراب"],"h1":"الطريق المعبّد هو سطح الطريق الصلب.","h2":"لافتة «PAVEMENT ENDS» تحذّر من أن سطح الطريق الصلب ينتهي ويبدأ الحصى أو التراب، لذلك خفف السرعة قبل أن تصل إليه.","p":"صحيح. يبدأ الحصى أو التراب في الأمام."},"ht":{"q":"Kisa yon siy jòn ki di “PAVEMENT ENDS” (asfalt la fini) avèti ou?","o":["Wout la fini devan yon mi","Twotwa a fini","Yo fin pentire wout la","Wout asfalt la vin tounen gravye oswa tè"],"h1":"Pavement se sifas di wout la.","h2":"“PAVEMENT ENDS” avèti sifas di wout la ap fini epi gravye oswa tè ap kòmanse, kidonk ralanti anvan ou rive la.","p":"Se sa. Gravye oswa tè kòmanse pi devan."}},{"id":"signs-084","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SOFT SHOULDER"},"c":0,"en":{"q":"A yellow sign says SOFT SHOULDER. What should you do?","o":["Avoid driving onto the edge of the road, because it may not hold your car","Pull onto the shoulder to let others pass","Park on the shoulder","Drive on the shoulder when the road is busy"],"h1":"Soft ground can trap a tire.","h2":"SOFT SHOULDER warns that the ground at the side of the road is soft, so stay on the pavement unless you have an emergency.","p":"Right. Stay off the soft edge."},"es":{"q":"Una señal amarilla dice SOFT SHOULDER. ¿Qué debe hacer?","o":["Evitar salirse a la orilla, porque puede no aguantar su carro","Salirse al acotamiento para dejar pasar a otros","Estacionarse en el acotamiento","Usar el acotamiento cuando hay mucho tráfico"],"h1":"La tierra blanda puede atrapar una llanta.","h2":"SOFT SHOULDER advierte que la orilla de la vía es blanda, así que quédese en el pavimento salvo en una emergencia.","p":"Correcto. No se salga a la orilla blanda."},"zh":{"q":"一个黄色标志写着 “SOFT SHOULDER”（路肩松软）。你应该怎么做？","o":["不要开到路边上，因为那里可能撑不住你的车","开到路肩上让别人超车","在路肩上停车","路上车多时开在路肩上"],"h1":"松软的地面可能会陷住轮胎。","h2":"“SOFT SHOULDER”（路肩松软）警告路边的地面是软的，所以除非紧急情况，要留在铺装路面上。","p":"对。不要开到松软的路边。"},"vi":{"q":"Một biển màu vàng ghi “SOFT SHOULDER” (Lề đường mềm). Bạn nên làm gì?","o":["Tránh chạy lên mép đường, vì nó có thể không chịu nổi xe bạn","Tấp vào lề để xe khác vượt","Đậu xe trên lề","Chạy trên lề khi đường đông xe"],"h1":"Đất mềm có thể làm kẹt bánh xe.","h2":"“SOFT SHOULDER” (Lề đường mềm) cảnh báo đất bên lề đường bị mềm, nên hãy ở trên mặt đường nhựa trừ khi có trường hợp khẩn cấp.","p":"Đúng rồi. Tránh xa mép đường mềm."},"tl":{"q":"May dilaw na karatula na “SOFT SHOULDER” (Malambot ang gilid ng daan). Ano ang dapat mong gawin?","o":["Iwasang magmaneho papunta sa gilid ng kalsada, dahil baka hindi nito kayanin ang sasakyan mo","Tumabi sa shoulder para makalampas ang iba","Pumarada sa shoulder","Magmaneho sa shoulder kapag masikip ang kalsada"],"h1":"Ang malambot na lupa ay puwedeng makabaon ng gulong.","h2":"Ang “SOFT SHOULDER” ay nagbababala na malambot ang lupa sa gilid ng kalsada, kaya manatili sa sementadong daan maliban kung may emergency.","p":"Tama. Lumayo sa malambot na gilid."},"ar":{"q":"لافتة صفراء مكتوب عليها «SOFT SHOULDER» (حافة الطريق لينة). ماذا يجب أن تفعل؟","o":["تجنّب القيادة على حافة الطريق، لأنها قد لا تتحمل سيارتك","اخرج إلى حافة الطريق لتدع الآخرين يتجاوزونك","اركن سيارتك على حافة الطريق","قُد على حافة الطريق عندما يكون الطريق مزدحمًا"],"h1":"الأرض اللينة قد تعلق فيها العجلة.","h2":"لافتة «SOFT SHOULDER» تحذّر من أن الأرض على جانب الطريق لينة، لذلك ابقَ على الطريق المعبّد إلا في حالة طارئة.","p":"صحيح. ابتعد عن الحافة اللينة."},"ht":{"q":"Yon siy jòn di “SOFT SHOULDER” (bò wout la mou). Kisa ou dwe fè?","o":["Evite kondui sou rebò wout la, paske li ka pa kenbe machin ou","Rale sou bò wout la pou kite lòt yo pase","Pake sou bò wout la","Kondui sou bò wout la lè gen anpil machin"],"h1":"Tè mou ka kole yon kawotchou.","h2":"“SOFT SHOULDER” avèti tè ki bò wout la mou, kidonk rete sou asfalt la sof si gen yon ijans.","p":"Se sa. Rete lwen rebò mou a."}},{"id":"signs-085","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"BRIDGE ICES BEFORE ROAD"},"c":1,"en":{"q":"In cold weather, you see a sign that says BRIDGE ICES BEFORE ROAD. What does it mean?","o":["The bridge is heated and never icy","The bridge may be icy even when the road is not","The bridge is closed in winter","Ice is sold near the bridge"],"h1":"Cold air flows under a bridge as well as over it.","h2":"BRIDGE ICES BEFORE ROAD means a bridge freezes sooner than the road, so it can be icy even when the road looks fine; slow down before you cross.","p":"Right. The bridge can be icy first."},"es":{"q":"Con tiempo frío, usted ve una señal que dice BRIDGE ICES BEFORE ROAD. ¿Qué significa?","o":["El puente tiene calefacción y nunca tiene hielo","El puente puede tener hielo aunque la vía no lo tenga","El puente se cierra en invierno","Se vende hielo cerca del puente"],"h1":"El aire frío pasa por debajo y por encima de un puente.","h2":"BRIDGE ICES BEFORE ROAD significa que el puente se congela antes que la vía, así que puede tener hielo aunque la vía se vea bien; baje la velocidad antes de cruzar.","p":"Correcto. El puente se congela primero."},"zh":{"q":"天冷时，你看到一个标志写着 “BRIDGE ICES BEFORE ROAD”（桥面比路面先结冰）。这是什么意思？","o":["桥是加热的，从来不会结冰","即使路面没结冰，桥面也可能结冰","桥在冬天封闭","桥附近有卖冰的"],"h1":"冷空气会从桥的上面和下面流过。","h2":"“BRIDGE ICES BEFORE ROAD”（桥面比路面先结冰）表示桥比路面更早结冰，所以即使路面看起来没问题，桥上也可能有冰；过桥前要减速。","p":"对。桥面可能先结冰。"},"vi":{"q":"Khi trời lạnh, bạn thấy một biển ghi “BRIDGE ICES BEFORE ROAD” (Cầu đóng băng trước mặt đường). Biển này có nghĩa là gì?","o":["Cầu có sưởi nên không bao giờ đóng băng","Cầu có thể đóng băng ngay cả khi mặt đường không đóng băng","Cầu bị đóng vào mùa đông","Có bán đá gần cầu"],"h1":"Không khí lạnh thổi cả bên dưới lẫn bên trên cây cầu.","h2":"“BRIDGE ICES BEFORE ROAD” (Cầu đóng băng trước mặt đường) có nghĩa là cầu đóng băng sớm hơn mặt đường, nên cầu có thể có băng ngay cả khi mặt đường trông vẫn bình thường; hãy chạy chậm lại trước khi qua cầu.","p":"Đúng rồi. Cầu có thể đóng băng trước."},"tl":{"q":"Sa malamig na panahon, may nakita kang karatula na “BRIDGE ICES BEFORE ROAD” (Nauunang magyelo ang tulay kaysa sa kalsada). Ano ang ibig sabihin nito?","o":["May heater ang tulay at hindi kailanman nagyeyelo","Maaaring may yelo sa tulay kahit wala sa kalsada","Sarado ang tulay tuwing taglamig","May nagtitinda ng yelo malapit sa tulay"],"h1":"Dumadaloy ang malamig na hangin sa ilalim at sa ibabaw ng tulay.","h2":"Ang “BRIDGE ICES BEFORE ROAD” ay nangangahulugang mas maagang nagyeyelo ang tulay kaysa sa kalsada, kaya maaaring may yelo ito kahit mukhang maayos ang kalsada; bumagal bago ka tumawid.","p":"Tama. Puwedeng maunang magyelo ang tulay."},"ar":{"q":"في الطقس البارد، ترى لافتة مكتوب عليها «BRIDGE ICES BEFORE ROAD» (الجسر يتجمّد قبل الطريق). ماذا تعني؟","o":["الجسر مُدفّأ ولا يتجمّد أبدًا","قد يكون على الجسر جليد حتى لو لم يكن على الطريق","الجسر مغلق في الشتاء","يُباع الثلج قرب الجسر"],"h1":"الهواء البارد يمر تحت الجسر وفوقه أيضًا.","h2":"لافتة «BRIDGE ICES BEFORE ROAD» تعني أن الجسر يتجمّد قبل الطريق، لذلك قد يكون عليه جليد حتى لو بدا الطريق سليمًا؛ خفف السرعة قبل أن تعبره.","p":"صحيح. قد يتجمّد الجسر أولًا."},"ht":{"q":"Lè fè frèt, ou wè yon siy ki di “BRIDGE ICES BEFORE ROAD” (pon an jele anvan wout la). Kisa li vle di?","o":["Pon an chofe epi li pa janm jele","Ka gen glas sou pon an menm lè pa gen sou wout la","Pon an fèmen nan sezon ivè","Yo vann glas toupre pon an"],"h1":"Lè frèt pase anba pon an epi anwo l tou.","h2":"“BRIDGE ICES BEFORE ROAD” vle di yon pon jele pi vit pase wout la, kidonk ka gen glas sou li menm lè wout la sanble anfòm; ralanti anvan ou travèse.","p":"Se sa. Pon an ka jele an premye."}},{"id":"signs-086","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"STOP AHEAD"},"c":2,"en":{"q":"A yellow sign shows a STOP sign with an arrow, or says STOP AHEAD. What should you do?","o":["Stop right at this yellow sign","Speed up before the stop","Get ready to stop at a STOP sign coming up","Nothing; it is only for trucks"],"h1":"Yellow signs warn about what comes next.","h2":"A STOP AHEAD sign warns that a STOP sign is coming up that you may not see yet, so begin slowing and get ready to stop.","p":"Right. A STOP sign is coming."},"es":{"q":"Una señal amarilla muestra una señal de PARE con una flecha, o dice STOP AHEAD. ¿Qué debe hacer?","o":["Pararse justo en esta señal amarilla","Acelerar antes de la parada","Prepararse para pararse en la señal de PARE que viene","Nada; es solo para camiones"],"h1":"Las señales amarillas advierten de lo que viene.","h2":"Una señal STOP AHEAD advierte que viene una señal de PARE que quizás aún no ve, así que empiece a bajar la velocidad y prepárese para pararse.","p":"Correcto. Viene una señal de PARE."},"zh":{"q":"一个黄色标志上画着带箭头的停车标志，或写着 “STOP AHEAD”（前方停车）。你应该怎么做？","o":["就在这个黄色标志处停车","在停车前加速","准备好在前方的停车标志处停车","什么都不用做，它只对卡车有效"],"h1":"黄色标志提醒你前面会出现什么。","h2":"“STOP AHEAD”（前方停车）标志提醒你，前方有一个你可能还看不到的停车标志，所以要开始减速，准备停车。","p":"对。前方有停车标志。"},"vi":{"q":"Một biển báo màu vàng có hình biển “STOP” (Dừng lại) với một mũi tên, hoặc ghi “STOP AHEAD” (Phía trước phải dừng). Bạn nên làm gì?","o":["Dừng ngay tại biển báo màu vàng này","Tăng tốc trước khi dừng","Chuẩn bị dừng ở biển “STOP” sắp tới","Không làm gì cả; biển này chỉ dành cho xe tải"],"h1":"Biển màu vàng cảnh báo điều sắp đến.","h2":"Biển “STOP AHEAD” (Phía trước phải dừng) cảnh báo rằng sắp có một biển “STOP” mà bạn có thể chưa thấy, nên hãy bắt đầu chạy chậm lại và chuẩn bị dừng.","p":"Đúng rồi. Sắp có biển “STOP”."},"tl":{"q":"May dilaw na karatula na may larawan ng “STOP” sign at palaso, o nakasulat na “STOP AHEAD” (May hintuan sa unahan). Ano ang dapat mong gawin?","o":["Huminto mismo sa dilaw na karatulang ito","Bumilis bago ang hintuan","Maghandang huminto sa “STOP” sign na paparating","Wala; para lang ito sa mga trak"],"h1":"Ang dilaw na karatula ay babala sa susunod na darating.","h2":"Ang “STOP AHEAD” sign (May hintuan sa unahan) ay babala na may “STOP” sign na paparating na baka hindi mo pa nakikita, kaya magsimulang bumagal at maghandang huminto.","p":"Tama. May “STOP” sign na paparating."},"ar":{"q":"لافتة صفراء عليها لافتة «STOP» (قف) مع سهم، أو مكتوب عليها «STOP AHEAD» (توقف في الأمام). ماذا يجب أن تفعل؟","o":["توقف عند هذه اللافتة الصفراء نفسها","زد السرعة قبل التوقف","استعد للتوقف عند لافتة «STOP» القادمة","لا شيء؛ إنها للشاحنات فقط"],"h1":"اللافتات الصفراء تحذّرك مما سيأتي بعدها.","h2":"لافتة «STOP AHEAD» (توقف في الأمام) تحذّرك من أن لافتة «STOP» قادمة وقد لا تراها بعد، لذلك ابدأ بتخفيف السرعة واستعد للتوقف.","p":"صحيح. لافتة «STOP» قادمة."},"ht":{"q":"Yon siy jòn montre yon siy “STOP” (kanpe) ak yon flèch, oswa li ekri “STOP AHEAD” (kanpe pi devan). Kisa ou dwe fè?","o":["Kanpe dwat devan siy jòn sa a","Akselere anvan ou kanpe","Prepare ou pou kanpe nan yon siy “STOP” k ap vini","Anyen; se pou kamyon sèlman"],"h1":"Siy jòn yo avèti ou pou sa k ap vini apre.","h2":"Siy “STOP AHEAD” (kanpe pi devan) avèti ou gen yon siy “STOP” k ap vini ou ka poko wè, kidonk kòmanse ralanti epi prepare ou pou kanpe.","p":"Se sa. Gen yon siy “STOP” k ap vini."}},{"id":"signs-087","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"BE PREPARED TO STOP"},"c":3,"en":{"q":"A yellow sign says BE PREPARED TO STOP. What does it mean?","o":["You must stop at this sign","The road ends here","Stopping is not allowed ahead","Traffic ahead may be stopped or a signal may turn red"],"h1":"Prepared means ready.","h2":"BE PREPARED TO STOP warns that traffic ahead may be stopped or a light may be red, so slow down and be ready to stop.","p":"Right. Be ready to stop."},"es":{"q":"Una señal amarilla dice BE PREPARED TO STOP. ¿Qué significa?","o":["Debe pararse en esta señal","La vía termina aquí","No se permite pararse más adelante","El tráfico adelante puede estar parado o un semáforo puede cambiar a rojo"],"h1":"Prepared quiere decir preparado.","h2":"BE PREPARED TO STOP advierte que el tráfico adelante puede estar parado o un semáforo puede estar en rojo, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Esté listo para pararse."},"zh":{"q":"一个黄色标志写着 “BE PREPARED TO STOP”（准备停车）。这是什么意思？","o":["你必须在这个标志处停车","道路在这里结束","前方不准停车","前方的车辆可能已经停下，或者信号灯可能变红"],"h1":"准备就是做好准备。","h2":"“BE PREPARED TO STOP”（准备停车）提醒你，前方的车辆可能已经停下，或者灯可能是红灯，所以要减速，准备停车。","p":"对。准备好停车。"},"vi":{"q":"Một biển báo màu vàng ghi “BE PREPARED TO STOP” (Chuẩn bị dừng). Biển này có nghĩa là gì?","o":["Bạn phải dừng ở biển báo này","Con đường hết ở đây","Phía trước không được dừng","Xe phía trước có thể đang dừng hoặc đèn có thể chuyển đỏ"],"h1":"Chuẩn bị nghĩa là sẵn sàng.","h2":"Biển “BE PREPARED TO STOP” (Chuẩn bị dừng) cảnh báo rằng xe phía trước có thể đang dừng hoặc đèn có thể đang đỏ, nên hãy chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Hãy sẵn sàng dừng."},"tl":{"q":"May dilaw na karatula na nakasulat na “BE PREPARED TO STOP” (Maghandang huminto). Ano ang ibig sabihin nito?","o":["Dapat kang huminto sa karatulang ito","Dito nagtatapos ang kalsada","Bawal huminto sa unahan","Baka nakahinto ang mga sasakyan sa unahan o baka maging pula ang ilaw"],"h1":"Ang maghanda ay maging handa.","h2":"Ang “BE PREPARED TO STOP” (Maghandang huminto) ay babala na baka nakahinto ang mga sasakyan sa unahan o baka pula ang ilaw, kaya bumagal at maging handang huminto.","p":"Tama. Maging handang huminto."},"ar":{"q":"لافتة صفراء مكتوب عليها «BE PREPARED TO STOP» (استعد للتوقف). ماذا تعني؟","o":["يجب أن تتوقف عند هذه اللافتة","الطريق ينتهي هنا","التوقف ممنوع في الأمام","قد تكون السيارات في الأمام متوقفة أو قد تتحول الإشارة إلى الأحمر"],"h1":"الاستعداد يعني أن تكون جاهزًا.","h2":"لافتة «BE PREPARED TO STOP» (استعد للتوقف) تحذّرك من أن السيارات في الأمام قد تكون متوقفة أو أن الإشارة قد تكون حمراء، لذلك خفف السرعة وكن جاهزًا للتوقف.","p":"صحيح. كن جاهزًا للتوقف."},"ht":{"q":"Yon siy jòn ekri “BE PREPARED TO STOP” (prepare pou kanpe). Kisa sa vle di?","o":["Ou dwe kanpe devan siy sa a","Wout la fini la a","Yo pa pèmèt kanpe pi devan","Machin pi devan yo ka kanpe oswa limyè a ka vin wouj"],"h1":"Prepare vle di pare.","h2":"“BE PREPARED TO STOP” (prepare pou kanpe) avèti ou machin pi devan yo ka kanpe oswa limyè a ka wouj, kidonk ralanti epi pare pou kanpe.","p":"Se sa. Pare pou kanpe."}},{"id":"signs-088","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"DRAW BRIDGE"},"c":0,"en":{"q":"A yellow sign says DRAW BRIDGE. What should you expect?","o":["A bridge that may lift or swing open for boats, so you may have to stop","A bridge made for walking only","A bridge with a toll booth","A bridge that is always closed"],"h1":"Some bridges move to let boats through.","h2":"DRAW BRIDGE warns of a bridge that opens for boats, so watch for signals and gates and be ready to stop.","p":"Right. The bridge may open, so be ready to stop."},"es":{"q":"Una señal amarilla dice DRAW BRIDGE. ¿Qué debe esperar?","o":["Un puente que puede levantarse o girar para los barcos, así que quizás deba pararse","Un puente solo para peatones","Un puente con caseta de peaje","Un puente que siempre está cerrado"],"h1":"Algunos puentes se mueven para dejar pasar barcos.","h2":"DRAW BRIDGE advierte de un puente que se abre para los barcos, así que fíjese en los semáforos y barreras y esté listo para pararse.","p":"Correcto. El puente puede abrirse; esté listo para pararse."},"zh":{"q":"一个黄色标志写着 “DRAW BRIDGE”（开合桥）。你应该预料到什么？","o":["一座可能为船只升起或转开的桥，所以你可能要停车","一座只供步行的桥","一座有收费站的桥","一座总是关闭的桥"],"h1":"有些桥会移动，让船通过。","h2":"“DRAW BRIDGE”（开合桥）提醒你前方有一座会为船只打开的桥，所以要注意信号灯和栏杆，准备停车。","p":"对。桥可能会打开，所以要准备停车。"},"vi":{"q":"Một biển báo màu vàng ghi “DRAW BRIDGE” (Cầu mở). Bạn nên chờ đợi điều gì?","o":["Một cây cầu có thể nâng lên hoặc xoay ra cho tàu thuyền đi qua, nên bạn có thể phải dừng","Một cây cầu chỉ dành cho người đi bộ","Một cây cầu có trạm thu phí","Một cây cầu lúc nào cũng đóng"],"h1":"Có những cây cầu di chuyển để tàu thuyền đi qua.","h2":"Biển “DRAW BRIDGE” (Cầu mở) cảnh báo có một cây cầu mở ra cho tàu thuyền, nên hãy chú ý đèn và thanh chắn, và sẵn sàng dừng.","p":"Đúng rồi. Cầu có thể mở, nên hãy sẵn sàng dừng."},"tl":{"q":"May dilaw na karatula na nakasulat na “DRAW BRIDGE” (Tulay na bumubukas). Ano ang dapat mong asahan?","o":["Isang tulay na maaaring umangat o umikot para sa mga bangka, kaya baka kailangan mong huminto","Isang tulay na para lang sa naglalakad","Isang tulay na may toll booth","Isang tulay na laging sarado"],"h1":"May mga tulay na gumagalaw para makadaan ang mga bangka.","h2":"Ang “DRAW BRIDGE” (Tulay na bumubukas) ay babala sa tulay na bumubukas para sa mga bangka, kaya bantayan ang mga ilaw at harang at maging handang huminto.","p":"Tama. Baka bumukas ang tulay, kaya maging handang huminto."},"ar":{"q":"لافتة صفراء مكتوب عليها «DRAW BRIDGE» (جسر متحرك). ماذا يجب أن تتوقع؟","o":["جسرًا قد يرتفع أو يدور ليفتح للقوارب، فقد تضطر إلى التوقف","جسرًا للمشاة فقط","جسرًا عليه كشك رسوم","جسرًا مغلقًا دائمًا"],"h1":"بعض الجسور تتحرك لتمر القوارب.","h2":"لافتة «DRAW BRIDGE» (جسر متحرك) تحذّرك من جسر يُفتح للقوارب، لذلك انتبه للإشارات والحواجز وكن جاهزًا للتوقف.","p":"صحيح. قد يُفتح الجسر، فكن جاهزًا للتوقف."},"ht":{"q":"Yon siy jòn ekri “DRAW BRIDGE” (pon ki louvri). Kisa ou dwe atann?","o":["Yon pon ki ka leve oswa vire pou bato pase, kidonk ou ka oblije kanpe","Yon pon pou moun ki ap mache sèlman","Yon pon ki gen yon pòs peyaj","Yon pon ki toujou fèmen"],"h1":"Gen kèk pon ki bouje pou kite bato pase.","h2":"“DRAW BRIDGE” (pon ki louvri) avèti ou gen yon pon ki louvri pou bato, kidonk veye limyè ak baryè yo epi pare pou kanpe.","p":"Se sa. Pon an ka louvri, kidonk pare pou kanpe."}},{"id":"signs-089","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"NEW TRAFFIC PATTERN AHEAD"},"c":1,"en":{"q":"A sign says NEW TRAFFIC PATTERN AHEAD. What does it mean?","o":["Traffic is lighter than usual","The lanes or traffic rules ahead have changed, so pay extra attention","You may ignore the lane lines","A new speed camera is ahead"],"h1":"Something you are used to may be different now.","h2":"NEW TRAFFIC PATTERN AHEAD warns that lanes, turns or controls ahead have recently changed, so read the signs and markings carefully.","p":"Right. Things have changed, so pay attention."},"es":{"q":"Una señal dice NEW TRAFFIC PATTERN AHEAD. ¿Qué significa?","o":["Hay menos tráfico que de costumbre","Los carriles o las reglas de tránsito adelante cambiaron, así que preste más atención","Puede ignorar las líneas de los carriles","Hay una cámara de velocidad nueva"],"h1":"Algo a lo que usted está acostumbrado puede ser distinto ahora.","h2":"NEW TRAFFIC PATTERN AHEAD advierte que los carriles, giros o controles adelante cambiaron hace poco, así que lea con cuidado las señales y marcas.","p":"Correcto. Algo cambió; preste atención."},"zh":{"q":"一个标志写着 “NEW TRAFFIC PATTERN AHEAD”（前方交通方式已改变）。这是什么意思？","o":["车比平时少","前方的车道或交通规则已经改变，所以要特别注意","你可以不管车道线","前方有一个新的测速摄像头"],"h1":"你习惯的东西现在可能不一样了。","h2":"“NEW TRAFFIC PATTERN AHEAD”（前方交通方式已改变）提醒你，前方的车道、转弯或交通管制最近改变了，所以要仔细看标志和路面标线。","p":"对。情况变了，所以要注意。"},"vi":{"q":"Một biển báo ghi “NEW TRAFFIC PATTERN AHEAD” (Phía trước có thay đổi cách lưu thông). Biển này có nghĩa là gì?","o":["Xe cộ ít hơn bình thường","Làn đường hoặc luật giao thông phía trước đã thay đổi, nên hãy chú ý hơn","Bạn có thể bỏ qua vạch kẻ làn","Phía trước có camera bắn tốc độ mới"],"h1":"Điều bạn đã quen có thể bây giờ đã khác.","h2":"Biển “NEW TRAFFIC PATTERN AHEAD” (Phía trước có thay đổi cách lưu thông) cảnh báo rằng làn đường, chỗ rẽ hoặc đèn và biển điều khiển phía trước mới thay đổi, nên hãy đọc kỹ biển báo và vạch kẻ đường.","p":"Đúng rồi. Mọi thứ đã thay đổi, nên hãy chú ý."},"tl":{"q":"May karatula na nakasulat na “NEW TRAFFIC PATTERN AHEAD” (May bagong ayos ng trapiko sa unahan). Ano ang ibig sabihin nito?","o":["Mas maluwag ang trapiko kaysa dati","Nagbago ang mga lane o patakaran sa trapiko sa unahan, kaya mag-ingat nang husto","Puwede mong hindi pansinin ang mga linya ng lane","May bagong speed camera sa unahan"],"h1":"Baka iba na ngayon ang nakasanayan mo.","h2":"Ang “NEW TRAFFIC PATTERN AHEAD” (May bagong ayos ng trapiko sa unahan) ay babala na kamakailan lang nagbago ang mga lane, likuan o kontrol sa unahan, kaya basahin nang mabuti ang mga karatula at marka sa kalsada.","p":"Tama. May nagbago, kaya mag-ingat."},"ar":{"q":"لافتة مكتوب عليها «NEW TRAFFIC PATTERN AHEAD» (نظام سير جديد في الأمام). ماذا تعني؟","o":["حركة السير أخف من المعتاد","المسارات أو قواعد السير في الأمام تغيّرت، فانتبه أكثر","يمكنك أن تتجاهل خطوط المسارات","هناك كاميرا سرعة جديدة في الأمام"],"h1":"شيء اعتدت عليه قد يكون مختلفًا الآن.","h2":"لافتة «NEW TRAFFIC PATTERN AHEAD» (نظام سير جديد في الأمام) تحذّرك من أن المسارات أو المنعطفات أو وسائل التحكم في السير في الأمام قد تغيّرت مؤخرًا، لذلك اقرأ اللافتات وعلامات الطريق بعناية.","p":"صحيح. الأمور تغيّرت، فانتبه."},"ht":{"q":"Yon siy ekri “NEW TRAFFIC PATTERN AHEAD” (nouvo fason sikilasyon pi devan). Kisa sa vle di?","o":["Gen mwens machin pase dabitid","Liy oswa règ sikilasyon pi devan yo chanje, kidonk fè plis atansyon","Ou ka pa okipe liy ki separe ran yo","Gen yon nouvo kamera vitès pi devan"],"h1":"Yon bagay ou te abitye ka diferan kounye a.","h2":"“NEW TRAFFIC PATTERN AHEAD” (nouvo fason sikilasyon pi devan) avèti ou ran, viraj oswa siy ak limyè pi devan yo fèk chanje, kidonk li siy yo ak mak sou wout la byen.","p":"Se sa. Bagay yo chanje, kidonk fè atansyon."}},{"id":"signs-090","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SPEED LIMIT 55"},"c":2,"en":{"q":"A yellow diamond sign shows a SPEED LIMIT 55 sign with an arrow above it. What should you do?","o":["Speed up before the limit changes","Slow down only if police are there","Get ready to slow down to a lower speed limit soon","Stop at the next sign"],"h1":"A yellow sign warns you about something coming up.","h2":"This Reduced Speed Limit Ahead sign warns that a lower speed limit begins soon, so start slowing down so you are at the new limit when you reach it.","p":"Right. A lower limit is coming."},"es":{"q":"Una señal amarilla en forma de rombo muestra una señal SPEED LIMIT 55 con una flecha encima. ¿Qué debe hacer?","o":["Acelerar antes de que cambie el límite","Bajar la velocidad solo si hay policía","Prepararse para bajar pronto a un límite de velocidad menor","Pararse en la próxima señal"],"h1":"Una señal amarilla le avisa de algo que viene más adelante.","h2":"Esta señal de límite de velocidad reducido más adelante advierte que pronto empieza un límite de velocidad más bajo, así que empiece a reducir para ir al nuevo límite cuando llegue.","p":"Correcto. Viene un límite más bajo."},"zh":{"q":"一个黄色菱形标志上画着 “SPEED LIMIT 55”（限速 55）标志，上面有一个箭头。你应该怎么做？","o":["在限速改变前加速","只有警察在时才减速","准备好很快减速到更低的限速","在下一个标志处停车"],"h1":"黄色标志提醒你前面会出现的情况。","h2":"这个“前方降低限速”标志提醒你，更低的限速很快开始，所以要开始减速，到那里时你的速度就符合新的限速。","p":"对。前方有更低的限速。"},"vi":{"q":"Một biển báo hình thoi màu vàng có hình biển “SPEED LIMIT 55” (Tốc độ tối đa 55) với một mũi tên ở trên. Bạn nên làm gì?","o":["Tăng tốc trước khi tốc độ tối đa thay đổi","Chỉ chạy chậm lại nếu có cảnh sát","Chuẩn bị sớm giảm xuống tốc độ tối đa thấp hơn","Dừng ở biển báo tiếp theo"],"h1":"Biển màu vàng cảnh báo điều sắp đến.","h2":"Biển “Phía trước giảm tốc độ tối đa” này cảnh báo rằng tốc độ tối đa thấp hơn sắp bắt đầu, nên hãy bắt đầu chạy chậm lại để khi tới đó bạn đã ở đúng tốc độ mới.","p":"Đúng rồi. Sắp có tốc độ tối đa thấp hơn."},"tl":{"q":"May dilaw na karatulang hugis diyamante na may larawan ng “SPEED LIMIT 55” sign (Pinakamabilis na 55) at may palaso sa itaas nito. Ano ang dapat mong gawin?","o":["Bumilis bago magbago ang speed limit","Bumagal lang kung may pulis","Maghandang bumagal sa mas mababang speed limit sa lalong madaling panahon","Huminto sa susunod na karatula"],"h1":"Ang dilaw na karatula ay babala sa paparating.","h2":"Ang karatulang ito na “Bababa ang speed limit sa unahan” ay babala na malapit nang magsimula ang mas mababang speed limit, kaya magsimulang bumagal para nasa bagong limit ka na pagdating mo roon.","p":"Tama. May mas mababang limit na paparating."},"ar":{"q":"لافتة صفراء على شكل معيّن عليها لافتة «SPEED LIMIT 55» (الحد الأقصى للسرعة 55) وفوقها سهم. ماذا يجب أن تفعل؟","o":["زد السرعة قبل أن يتغير الحد","خفف السرعة فقط إذا كانت الشرطة موجودة","استعد لتخفيف السرعة قريبًا إلى حد أقل","توقف عند اللافتة التالية"],"h1":"اللافتة الصفراء تحذّرك من شيء قادم.","h2":"لافتة «انخفاض الحد الأقصى للسرعة في الأمام» هذه تحذّرك من أن حدًّا أقل للسرعة سيبدأ قريبًا، لذلك ابدأ بتخفيف السرعة لكي تكون على الحد الجديد عندما تصل إليه.","p":"صحيح. حد أقل للسرعة قادم."},"ht":{"q":"Yon siy jòn an fòm dyaman montre yon siy “SPEED LIMIT 55” (vitès maksimòm 55) ak yon flèch anwo l. Kisa ou dwe fè?","o":["Akselere anvan limit la chanje","Ralanti sèlman si gen lapolis","Prepare ou pou ralanti talè pou yon limit vitès ki pi ba","Kanpe nan pwochen siy la"],"h1":"Yon siy jòn avèti ou pou yon bagay k ap vini.","h2":"Siy “limit vitès ki pi ba pi devan” sa a avèti ou yon limit vitès ki pi ba ap kòmanse talè, kidonk kòmanse ralanti pou ou deja nan nouvo limit la lè ou rive la.","p":"Se sa. Yon limit ki pi ba ap vini."}},{"id":"signs-091","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"+"},"c":3,"en":{"q":"A yellow diamond sign shows a black plus sign (+). What does it warn you about?","o":["A hospital ahead","A railroad crossing ahead","A church ahead","A crossroad ahead"],"h1":"The lines show the shape of the roads.","h2":"A plus-shaped symbol on a yellow sign warns of a crossroad ahead, where another road crosses yours.","p":"Right. A crossroad is ahead."},"es":{"q":"Una señal amarilla en forma de rombo muestra un signo de más (+) negro. ¿De qué le advierte?","o":["De un hospital adelante","De un cruce de tren adelante","De una iglesia adelante","De un cruce de vías adelante"],"h1":"Las líneas muestran la forma de las vías.","h2":"Un símbolo en forma de cruz (+) en una señal amarilla advierte de un cruce adelante, donde otra vía cruza la suya.","p":"Correcto. Viene un cruce de vías."},"zh":{"q":"一个黄色菱形标志上画着一个黑色加号（+）。它提醒你注意什么？","o":["前方有医院","前方有铁路道口","前方有教堂","前方有十字路口"],"h1":"线条显示道路的形状。","h2":"黄色标志上的加号形状提醒你前方有十字路口，那里有另一条路和你的路交叉。","p":"对。前方有十字路口。"},"vi":{"q":"Một biển báo hình thoi màu vàng có dấu cộng màu đen (+). Biển này cảnh báo bạn điều gì?","o":["Phía trước có bệnh viện","Phía trước có đường sắt cắt ngang","Phía trước có nhà thờ","Phía trước có ngã tư"],"h1":"Các đường kẻ cho thấy hình dạng của con đường.","h2":"Hình dấu cộng trên biển màu vàng cảnh báo phía trước có ngã tư, nơi một con đường khác cắt ngang đường của bạn.","p":"Đúng rồi. Phía trước có ngã tư."},"tl":{"q":"May dilaw na karatulang hugis diyamante na may itim na plus sign (+). Ano ang babala nito sa iyo?","o":["May ospital sa unahan","May tawiran ng tren sa unahan","May simbahan sa unahan","May krosing ng kalsada sa unahan"],"h1":"Ipinapakita ng mga linya ang hugis ng mga kalsada.","h2":"Ang simbolong hugis plus sa dilaw na karatula ay babala na may krosing sa unahan, kung saan may ibang kalsadang tumatawid sa kalsada mo.","p":"Tama. May krosing sa unahan."},"ar":{"q":"لافتة صفراء على شكل معيّن عليها علامة زائد سوداء (+). من ماذا تحذّرك؟","o":["مستشفى في الأمام","تقاطع سكة حديد في الأمام","كنيسة في الأمام","تقاطع طرق في الأمام"],"h1":"الخطوط تُظهر شكل الطرق.","h2":"رمز على شكل علامة زائد على لافتة صفراء يحذّرك من تقاطع طرق في الأمام، حيث يعبر طريق آخر طريقك.","p":"صحيح. هناك تقاطع طرق في الأمام."},"ht":{"q":"Yon siy jòn an fòm dyaman montre yon siy plis nwa (+). Pou kisa li avèti ou?","o":["Yon lopital pi devan","Yon kwazman tren pi devan","Yon legliz pi devan","Yon kafou pi devan"],"h1":"Liy yo montre fòm wout yo.","h2":"Yon senbòl an fòm plis sou yon siy jòn avèti ou gen yon kafou pi devan, kote yon lòt wout travèse wout ou a.","p":"Se sa. Gen yon kafou pi devan."}},{"id":"signs-092","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"T"},"c":0,"en":{"q":"A yellow sign shows a black T shape. What does it warn you about?","o":["Your road ends ahead; you must turn left or right","A toll booth is ahead","A truck stop is ahead","The road splits into two lanes"],"h1":"Your road is the bottom of the T.","h2":"A T-shaped symbol warns that your road ends ahead at another road, so you will have to turn left or right.","p":"Right. The road ends; turn left or right."},"es":{"q":"Una señal amarilla muestra una forma de T negra. ¿De qué le advierte?","o":["Su vía termina adelante; tendrá que girar a la izquierda o a la derecha","Hay una caseta de peaje adelante","Hay una parada de camiones adelante","La vía se divide en dos carriles"],"h1":"Su vía es la parte de abajo de la T.","h2":"Un símbolo en forma de T advierte que su vía termina adelante en otra vía, así que tendrá que girar a la izquierda o a la derecha.","p":"Correcto. La vía termina; gire a un lado."},"zh":{"q":"一个黄色标志上画着一个黑色的 T 形。它提醒你注意什么？","o":["你的路在前方结束，你必须向左或向右转","前方有收费站","前方有卡车休息站","道路分成两条车道"],"h1":"你的路是 T 字下面的那一竖。","h2":"T 形符号提醒你，你的路在前方与另一条路相接并结束，所以你必须向左或向右转。","p":"对。路到头了，要向左或向右转。"},"vi":{"q":"Một biển báo màu vàng có hình chữ T màu đen. Biển này cảnh báo bạn điều gì?","o":["Đường của bạn hết ở phía trước; bạn phải rẽ trái hoặc rẽ phải","Phía trước có trạm thu phí","Phía trước có trạm dừng cho xe tải","Con đường chia thành hai làn"],"h1":"Đường của bạn là phần dưới của chữ T.","h2":"Hình chữ T cảnh báo rằng đường của bạn hết ở phía trước khi gặp một con đường khác, nên bạn sẽ phải rẽ trái hoặc rẽ phải.","p":"Đúng rồi. Đường hết; hãy rẽ trái hoặc rẽ phải."},"tl":{"q":"May dilaw na karatula na may itim na hugis T. Ano ang babala nito sa iyo?","o":["Matatapos ang kalsada mo sa unahan; dapat kang kumaliwa o kumanan","May toll booth sa unahan","May hintuan ng trak sa unahan","Nahahati ang kalsada sa dalawang lane"],"h1":"Ang kalsada mo ay ang ibabang bahagi ng T.","h2":"Ang simbolong hugis T ay babala na matatapos ang kalsada mo sa unahan sa isa pang kalsada, kaya kailangan mong kumaliwa o kumanan.","p":"Tama. Matatapos ang kalsada; kumaliwa o kumanan."},"ar":{"q":"لافتة صفراء عليها شكل حرف T أسود. من ماذا تحذّرك؟","o":["طريقك ينتهي في الأمام؛ يجب أن تنعطف يسارًا أو يمينًا","كشك رسوم في الأمام","استراحة شاحنات في الأمام","الطريق ينقسم إلى مسارين"],"h1":"طريقك هو الجزء السفلي من حرف T.","h2":"الرمز الذي على شكل حرف T يحذّرك من أن طريقك ينتهي في الأمام عند طريق آخر، لذلك ستضطر إلى الانعطاف يسارًا أو يمينًا.","p":"صحيح. الطريق ينتهي؛ انعطف يسارًا أو يمينًا."},"ht":{"q":"Yon siy jòn montre yon fòm T nwa. Pou kisa li avèti ou?","o":["Wout ou a fini pi devan; ou dwe vire agoch oswa adwat","Gen yon pòs peyaj pi devan","Gen yon kote kamyon kanpe pi devan","Wout la separe an de ran"],"h1":"Wout ou a se pati anba T a.","h2":"Yon senbòl an fòm T avèti ou wout ou a fini pi devan sou yon lòt wout, kidonk ou pral oblije vire agoch oswa adwat.","p":"Se sa. Wout la fini; vire agoch oswa adwat."}},{"id":"signs-093","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"ADDED LANE"},"c":1,"en":{"q":"You are on a highway. A yellow Added Lane sign shows your straight arrow and a second arrow joining from the side in its own lane. What does it mean?","o":["Your lane is ending","The joining traffic gets its own new lane and does not have to merge","You must merge into the joining lane","A lane is closed for work"],"h1":"Added means one more lane.","h2":"The Added Lane sign means the road coming in gets its own new lane, so that traffic does not need to merge into your lane.","p":"Right. The joining traffic gets its own lane."},"es":{"q":"Usted va por una carretera. Una señal amarilla de carril adicional muestra su flecha recta y otra flecha que se une desde el lado en su propio carril. ¿Qué significa?","o":["Su carril termina","El tráfico que entra tiene un carril nuevo propio y no tiene que incorporarse","Usted debe pasarse al carril que entra","Hay un carril cerrado por obras"],"h1":"Added quiere decir que hay un carril más.","h2":"La señal de carril adicional significa que la vía que entra tiene su propio carril nuevo, así que ese tráfico no necesita meterse en su carril.","p":"Correcto. El tráfico que entra tiene su propio carril."},"zh":{"q":"你在高速公路上。一个黄色的“增加车道”标志上画着你的直行箭头，还有一个从旁边汇入、有自己车道的箭头。这是什么意思？","o":["你的车道要结束了","汇入的车辆有自己的新车道，不用并道","你必须并入汇入的车道","有一条车道因施工关闭"],"h1":"增加就是多一条车道。","h2":"“增加车道”标志表示汇入的道路有自己的新车道，所以那些车辆不需要并入你的车道。","p":"对。汇入的车辆有自己的车道。"},"vi":{"q":"Bạn đang ở trên xa lộ. Một biển báo “Thêm làn” màu vàng có mũi tên thẳng của bạn và một mũi tên thứ hai nhập vào từ bên cạnh trong làn riêng của nó. Biển này có nghĩa là gì?","o":["Làn của bạn sắp hết","Xe nhập vào có làn mới riêng và không phải nhập làn","Bạn phải nhập vào làn đang nhập vào","Một làn bị đóng để sửa đường"],"h1":"Thêm nghĩa là có thêm một làn.","h2":"Biển “Thêm làn” có nghĩa là con đường nhập vào có làn mới riêng, nên xe trên đó không cần nhập vào làn của bạn.","p":"Đúng rồi. Xe nhập vào có làn riêng."},"tl":{"q":"Nasa highway ka. May dilaw na karatulang “Dagdag na lane” na may tuwid mong palaso at pangalawang palaso na sumasama mula sa gilid sa sarili nitong lane. Ano ang ibig sabihin nito?","o":["Matatapos na ang lane mo","Ang mga sumasamang sasakyan ay may sariling bagong lane at hindi na kailangang sumingit","Dapat kang lumipat sa sumasamang lane","May lane na sarado dahil sa trabaho"],"h1":"Ang dagdag ay may isa pang lane.","h2":"Ang karatulang “Dagdag na lane” ay nangangahulugang may sariling bagong lane ang kalsadang sumasama, kaya hindi na kailangang sumingit ng mga sasakyang iyon sa lane mo.","p":"Tama. May sariling lane ang mga sumasamang sasakyan."},"ar":{"q":"أنت على طريق سريع. لافتة صفراء «مسار إضافي» عليها سهمك المستقيم وسهم ثانٍ ينضم من الجانب في مساره الخاص. ماذا تعني؟","o":["مسارك سينتهي","السيارات المنضمة لها مسار جديد خاص بها وليس عليها أن تندمج","يجب أن تندمج في المسار المنضم","هناك مسار مغلق بسبب أعمال"],"h1":"إضافي يعني مسارًا آخر.","h2":"لافتة «مسار إضافي» تعني أن الطريق المنضم له مسار جديد خاص به، لذلك ليس على تلك السيارات أن تندمج في مسارك.","p":"صحيح. السيارات المنضمة لها مسارها الخاص."},"ht":{"q":"Ou sou otowout la. Yon siy jòn “ran anplis” montre flèch dwat ou a ak yon dezyèm flèch ki antre sou kote a nan pwòp ran pa l. Kisa sa vle di?","o":["Ran ou a ap fini","Machin k ap antre yo gen pwòp nouvo ran pa yo epi yo pa bezwen antre nan ran ou","Ou dwe antre nan ran k ap antre a","Yon ran fèmen pou travay"],"h1":"Anplis vle di yon ran an plis.","h2":"Siy “ran anplis” la vle di wout k ap antre a gen pwòp nouvo ran pa l, kidonk machin sa yo pa bezwen antre nan ran ou.","p":"Se sa. Machin k ap antre yo gen pwòp ran pa yo."}},{"id":"signs-094","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"TWO WAY TRAFFIC"},"c":2,"en":{"q":"You have been on a one-way road. A yellow sign shows two arrows, one up and one down. What does it warn you about?","o":["There are two lanes going your way","You may make a U-turn","Traffic will now come toward you in the other lane","The road splits in two"],"h1":"One arrow points each way.","h2":"The Two-Way Traffic sign warns that the road ahead carries traffic in both directions, so stay to the right of the center line.","p":"Right. Expect cars coming toward you."},"es":{"q":"Usted venía por una vía de un solo sentido. Una señal amarilla muestra dos flechas, una hacia arriba y otra hacia abajo. ¿De qué le advierte?","o":["De que hay dos carriles en su sentido","De que puede dar una vuelta en U","De que ahora habrá tráfico de frente en el otro carril","De que la vía se divide en dos"],"h1":"Cada flecha apunta en un sentido.","h2":"La señal de doble sentido advierte que la vía adelante tiene tráfico en ambos sentidos, así que manténgase a la derecha de la línea central.","p":"Correcto. Espere carros de frente."},"zh":{"q":"你一直在一条单行道上。一个黄色标志上画着两个箭头，一个向上，一个向下。它提醒你注意什么？","o":["有两条车道和你同方向","你可以掉头","现在对面车道会有车朝你开来","道路分成两条"],"h1":"每个方向各有一个箭头。","h2":"“双向交通”标志提醒你，前方道路两个方向都有车，所以要靠中线右边行驶。","p":"对。要注意对面开来的车。"},"vi":{"q":"Bạn đang đi trên đường một chiều. Một biển báo màu vàng có hai mũi tên, một chỉ lên và một chỉ xuống. Biển này cảnh báo bạn điều gì?","o":["Có hai làn đi cùng hướng với bạn","Bạn được quay đầu xe","Bây giờ xe sẽ chạy ngược chiều về phía bạn ở làn bên kia","Con đường chia làm hai"],"h1":"Mỗi mũi tên chỉ một hướng.","h2":"Biển “Đường hai chiều” cảnh báo rằng con đường phía trước có xe chạy cả hai chiều, nên hãy đi bên phải vạch giữa đường.","p":"Đúng rồi. Hãy chờ có xe chạy ngược chiều về phía bạn."},"tl":{"q":"Nasa one-way na kalsada ka. May dilaw na karatula na may dalawang palaso, isang pataas at isang pababa. Ano ang babala nito sa iyo?","o":["May dalawang lane na papunta sa direksyon mo","Puwede kang mag-U-turn","Ngayon may mga sasakyang darating papunta sa iyo sa kabilang lane","Nahahati sa dalawa ang kalsada"],"h1":"Tig-isang direksyon ang bawat palaso.","h2":"Ang karatulang “Dalawang direksyon ng trapiko” ay babala na may trapiko sa magkabilang direksyon ang kalsada sa unahan, kaya manatili sa kanan ng gitnang linya.","p":"Tama. Asahan ang mga sasakyang papunta sa iyo."},"ar":{"q":"كنت تسير في طريق باتجاه واحد. لافتة صفراء عليها سهمان، واحد إلى الأعلى وواحد إلى الأسفل. من ماذا تحذّرك؟","o":["هناك مساران في اتجاهك","يمكنك أن تستدير للخلف (U-turn)","السيارات ستأتي الآن نحوك في المسار الآخر","الطريق ينقسم إلى قسمين"],"h1":"كل سهم يشير إلى اتجاه.","h2":"لافتة «سير في الاتجاهين» تحذّرك من أن الطريق في الأمام فيه سيارات في الاتجاهين، لذلك ابقَ على يمين الخط الأوسط.","p":"صحيح. توقّع سيارات قادمة نحوك."},"ht":{"q":"Ou t ap kondui sou yon wout yon sèl sans. Yon siy jòn montre de flèch, youn monte, youn desann. Pou kisa li avèti ou?","o":["Gen de ran k ap ale menm direksyon ak ou","Ou ka fè yon demi-tou (U-turn)","Kounye a machin pral vini sou ou nan lòt ran an","Wout la separe an de"],"h1":"Chak flèch montre yon direksyon.","h2":"Siy “sikilasyon de sans” avèti ou wout pi devan an gen machin ki ale nan tou de direksyon, kidonk rete sou bò dwat liy nan mitan an.","p":"Se sa. Atann ou wè machin k ap vini sou ou."}},{"id":"signs-095","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"TRACTOR"},"c":3,"en":{"q":"A yellow sign shows a farm tractor. What should you expect?","o":["A place that sells tractors","A truck weigh station","A road made only for tractors","Slow farm vehicles may be on or entering the road"],"h1":"Farm machines move slowly.","h2":"A tractor symbol warns that slow farm vehicles may be on or crossing the road, so be ready to slow down behind them.","p":"Right. Watch for slow farm vehicles."},"es":{"q":"Una señal amarilla muestra un tractor. ¿Qué debe esperar?","o":["Un lugar donde venden tractores","Una estación de pesaje de camiones","Una vía solo para tractores","Vehículos agrícolas lentos en la vía o entrando a ella"],"h1":"Las máquinas del campo van despacio.","h2":"El símbolo de tractor advierte que puede haber vehículos agrícolas lentos en la vía o cruzándola, así que esté listo para ir despacio detrás de ellos.","p":"Correcto. Cuidado con vehículos agrícolas lentos."},"zh":{"q":"一个黄色标志上画着一辆农用拖拉机。你应该预料到什么？","o":["一个卖拖拉机的地方","一个卡车称重站","一条只供拖拉机走的路","慢速的农用车辆可能在路上或正要上路"],"h1":"农用机械开得很慢。","h2":"拖拉机符号提醒你，慢速的农用车辆可能在路上或正在横穿道路，所以要准备好在它们后面减速。","p":"对。注意慢速的农用车辆。"},"vi":{"q":"Một biển báo màu vàng có hình máy kéo nông nghiệp. Bạn nên chờ đợi điều gì?","o":["Một nơi bán máy kéo","Một trạm cân xe tải","Một con đường chỉ dành cho máy kéo","Xe nông nghiệp chạy chậm có thể đang ở trên đường hoặc đang đi vào đường"],"h1":"Máy móc nông nghiệp chạy chậm.","h2":"Hình máy kéo cảnh báo rằng xe nông nghiệp chạy chậm có thể đang ở trên đường hoặc đang băng qua đường, nên hãy sẵn sàng chạy chậm lại khi ở phía sau chúng.","p":"Đúng rồi. Hãy chú ý xe nông nghiệp chạy chậm."},"tl":{"q":"May dilaw na karatula na may larawan ng traktora sa bukid. Ano ang dapat mong asahan?","o":["Isang lugar na nagbebenta ng traktora","Isang timbangan ng trak","Isang kalsadang para lang sa traktora","Maaaring may mabagal na sasakyang pambukid sa kalsada o papasok dito"],"h1":"Mabagal ang mga makinang pambukid.","h2":"Ang simbolo ng traktora ay babala na maaaring may mabagal na sasakyang pambukid sa kalsada o tumatawid dito, kaya maging handang bumagal sa likod nila.","p":"Tama. Bantayan ang mabagal na sasakyang pambukid."},"ar":{"q":"لافتة صفراء عليها جرّار زراعي. ماذا يجب أن تتوقع؟","o":["مكانًا لبيع الجرّارات","محطة لوزن الشاحنات","طريقًا للجرّارات فقط","مركبات زراعية بطيئة قد تكون على الطريق أو تدخل إليه"],"h1":"الآلات الزراعية تسير ببطء.","h2":"رمز الجرّار يحذّرك من أن مركبات زراعية بطيئة قد تكون على الطريق أو تعبره، لذلك كن جاهزًا لتخفيف السرعة خلفها.","p":"صحيح. انتبه للمركبات الزراعية البطيئة."},"ht":{"q":"Yon siy jòn montre yon traktè fèm. Kisa ou dwe atann?","o":["Yon kote ki vann traktè","Yon pòs pou peze kamyon","Yon wout pou traktè sèlman","Machin fèm ki mache dousman ka sou wout la oswa ap antre sou li"],"h1":"Machin fèm yo mache dousman.","h2":"Yon senbòl traktè avèti ou machin fèm ki mache dousman ka sou wout la oswa ap travèse l, kidonk pare pou ralanti dèyè yo.","p":"Se sa. Veye machin fèm ki mache dousman."}},{"id":"signs-096","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"EMERGENCY VEHICLES"},"c":0,"en":{"q":"A yellow sign shows a fire truck. What does it warn you about?","o":["Emergency vehicles may enter the road ahead, such as from a fire station","A place to report a fire","A road only for fire trucks","A fire is burning nearby"],"h1":"Think about where fire trucks come out.","h2":"An emergency vehicle warning sign means fire trucks or ambulances may enter the road ahead, often from a station, so be ready to yield.","p":"Right. Emergency vehicles may come out ahead."},"es":{"q":"Una señal amarilla muestra un camión de bomberos. ¿De qué le advierte?","o":["De que vehículos de emergencia pueden entrar a la vía, por ejemplo desde una estación de bomberos","De un lugar para reportar incendios","De una vía solo para bomberos","De un incendio cercano"],"h1":"Piense de dónde salen los camiones de bomberos.","h2":"Una señal de vehículos de emergencia significa que camiones de bomberos o ambulancias pueden entrar a la vía adelante, muchas veces desde una estación, así que esté listo para ceder el paso.","p":"Correcto. Pueden salir vehículos de emergencia."},"zh":{"q":"一个黄色标志上画着一辆消防车。它提醒你注意什么？","o":["前方可能有紧急车辆开上道路，例如从消防站开出来","一个报告火灾的地方","一条只供消防车走的路","附近有火在燃烧"],"h1":"想一想消防车从哪里开出来。","h2":"紧急车辆警告标志表示，消防车或救护车可能在前方开上道路，常常是从消防站开出来，所以要准备让行。","p":"对。前方可能有紧急车辆开出来。"},"vi":{"q":"Một biển báo màu vàng có hình xe cứu hỏa. Biển này cảnh báo bạn điều gì?","o":["Xe cấp cứu, xe cứu hỏa có thể chạy vào đường phía trước, ví dụ từ trạm cứu hỏa","Một nơi để báo cháy","Một con đường chỉ dành cho xe cứu hỏa","Có đám cháy ở gần đây"],"h1":"Hãy nghĩ xem xe cứu hỏa chạy ra từ đâu.","h2":"Biển cảnh báo xe khẩn cấp có nghĩa là xe cứu hỏa hoặc xe cứu thương có thể chạy vào đường phía trước, thường là từ một trạm, nên hãy sẵn sàng nhường đường.","p":"Đúng rồi. Xe khẩn cấp có thể chạy ra phía trước."},"tl":{"q":"May dilaw na karatula na may larawan ng trak ng bumbero. Ano ang babala nito sa iyo?","o":["Maaaring pumasok sa kalsada sa unahan ang mga emergency vehicle, gaya ng mula sa istasyon ng bumbero","Isang lugar para mag-ulat ng sunog","Isang kalsadang para lang sa trak ng bumbero","May sunog sa malapit"],"h1":"Isipin kung saan lumalabas ang mga trak ng bumbero.","h2":"Ang karatulang babala sa emergency vehicle ay nangangahulugang maaaring pumasok sa kalsada sa unahan ang trak ng bumbero o ambulansya, kadalasan mula sa istasyon, kaya maging handang magbigay-daan.","p":"Tama. Maaaring may lumabas na emergency vehicle sa unahan."},"ar":{"q":"لافتة صفراء عليها سيارة إطفاء. من ماذا تحذّرك؟","o":["مركبات طوارئ قد تدخل الطريق في الأمام، مثلًا من محطة إطفاء","مكان للإبلاغ عن حريق","طريق لسيارات الإطفاء فقط","حريق مشتعل في مكان قريب"],"h1":"فكّر من أين تخرج سيارات الإطفاء.","h2":"لافتة التحذير من مركبات الطوارئ تعني أن سيارات الإطفاء أو الإسعاف قد تدخل الطريق في الأمام، غالبًا من محطة، لذلك كن جاهزًا لإعطاء الأولوية.","p":"صحيح. قد تخرج مركبات طوارئ في الأمام."},"ht":{"q":"Yon siy jòn montre yon kamyon ponpye. Pou kisa li avèti ou?","o":["Machin ijans ka antre sou wout la pi devan, tankou soti nan yon kazèn ponpye","Yon kote pou rapòte yon dife","Yon wout pou kamyon ponpye sèlman","Gen yon dife k ap boule toupre"],"h1":"Panse kote kamyon ponpye yo soti.","h2":"Yon siy avètisman pou machin ijans vle di kamyon ponpye oswa anbilans ka antre sou wout la pi devan, souvan soti nan yon kazèn, kidonk pare pou bay pasaj.","p":"Se sa. Machin ijans ka soti pi devan."}},{"id":"signs-097","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"HORSE AND BUGGY"},"c":1,"en":{"q":"A yellow sign shows a horse pulling a buggy. What should you do?","o":["Honk so the horse moves over","Watch for slow horse-drawn vehicles and pass them slowly with plenty of room","Speed up to pass quickly and closely","Follow very close behind the buggy"],"h1":"Horses can be scared by noise and speed.","h2":"The horse-drawn vehicle sign warns of slow buggies on the road, so slow down, do not honk, and pass only with plenty of room.","p":"Right. Slow down and give them room."},"es":{"q":"Una señal amarilla muestra un caballo que tira de un carruaje. ¿Qué debe hacer?","o":["Tocar la bocina para que el caballo se aparte","Estar atento a vehículos tirados por caballos y rebasarlos despacio, con mucho espacio","Acelerar y pasar rápido y cerca","Seguir muy de cerca al carruaje"],"h1":"El ruido y la velocidad pueden asustar a los caballos.","h2":"La señal de vehículo tirado por caballos advierte de carruajes lentos en la vía, así que baje la velocidad, no toque la bocina y rebase solo con mucho espacio.","p":"Correcto. Baje la velocidad y deles espacio."},"zh":{"q":"一个黄色标志上画着一匹马拉着一辆马车。你应该怎么做？","o":["按喇叭让马让开","注意慢速的马车，慢慢超过它们并留出很大的空间","加速，快速并贴近地超过去","紧紧跟在马车后面"],"h1":"马会被噪音和速度吓到。","h2":"马车标志提醒你路上有慢速的马车，所以要减速，不要按喇叭，只有留出很大的空间时才能超车。","p":"对。减速，给它们留出空间。"},"vi":{"q":"Một biển báo màu vàng có hình con ngựa kéo xe. Bạn nên làm gì?","o":["Bấm còi để con ngựa tránh sang bên","Chú ý xe ngựa chạy chậm và vượt qua chúng thật chậm, chừa nhiều khoảng trống","Tăng tốc để vượt nhanh và sát","Chạy thật sát phía sau xe ngựa"],"h1":"Ngựa có thể sợ tiếng ồn và tốc độ.","h2":"Biển xe ngựa kéo cảnh báo có xe ngựa chạy chậm trên đường, nên hãy chạy chậm lại, đừng bấm còi, và chỉ vượt khi chừa được nhiều khoảng trống.","p":"Đúng rồi. Chạy chậm lại và chừa chỗ cho họ."},"tl":{"q":"May dilaw na karatula na may larawan ng kabayong humihila ng karwahe. Ano ang dapat mong gawin?","o":["Bumusina para tumabi ang kabayo","Bantayan ang mabagal na sasakyang hila ng kabayo at lampasan ito nang dahan-dahan na may malaking puwang","Bumilis para makalampas nang mabilis at malapit","Sumunod nang napakalapit sa likod ng karwahe"],"h1":"Natatakot ang kabayo sa ingay at bilis.","h2":"Ang karatula ng sasakyang hila ng kabayo ay babala na may mabagal na karwahe sa kalsada, kaya bumagal, huwag bumusina, at lumampas lang kung may malaking puwang.","p":"Tama. Bumagal at bigyan sila ng puwang."},"ar":{"q":"لافتة صفراء عليها حصان يجر عربة. ماذا يجب أن تفعل؟","o":["استخدم البوق لكي يبتعد الحصان","انتبه للعربات البطيئة التي تجرها الخيول وتجاوزها ببطء مع ترك مسافة كبيرة","زد السرعة لتتجاوز بسرعة وعن قرب","سِر قريبًا جدًا خلف العربة"],"h1":"الخيول قد تخاف من الضجيج والسرعة.","h2":"لافتة العربات التي تجرها الخيول تحذّرك من عربات بطيئة على الطريق، لذلك خفف السرعة، ويجب ألّا تستخدم البوق، ولا تتجاوز إلا مع ترك مسافة كبيرة.","p":"صحيح. خفف السرعة واترك لهم مسافة."},"ht":{"q":"Yon siy jòn montre yon chwal k ap rale yon kabwèt. Kisa ou dwe fè?","o":["Klaksonnen pou chwal la deplase","Veye kabwèt chwal ki mache dousman epi depase yo dousman ak anpil espas","Akselere pou depase vit epi toupre","Swiv byen kole dèyè kabwèt la"],"h1":"Bri ak vitès ka fè chwal pè.","h2":"Siy kabwèt chwal la avèti ou gen kabwèt ki mache dousman sou wout la, kidonk ralanti, pa klaksonnen, epi depase sèlman lè gen anpil espas.","p":"Se sa. Ralanti epi ba yo espas."}},{"id":"signs-098","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"PLAYGROUND"},"c":2,"en":{"q":"A yellow sign shows two children on a seesaw. What should you do?","o":["Honk to warn the children","Park and wait for the children to leave","Slow down and watch for children who may run into the road","Keep your speed; children will stay off the road"],"h1":"Children at play may not look for cars.","h2":"The Playground sign warns that a children's playground is next to the road and children could run into the road, so slow down and watch carefully.","p":"Right. Slow down and watch for children."},"es":{"q":"Una señal amarilla muestra a dos niños en un subibaja. ¿Qué debe hacer?","o":["Tocar la bocina para avisar a los niños","Estacionarse y esperar que los niños se vayan","Bajar la velocidad y fijarse en niños que pueden salir corriendo a la vía","Mantener su velocidad; los niños no saldrán a la vía"],"h1":"Los niños que juegan quizás no miren si vienen carros.","h2":"La señal de parque infantil advierte que hay un parque infantil junto a la vía y los niños podrían salir a la vía, así que baje la velocidad y mire con cuidado.","p":"Correcto. Baje la velocidad y fíjese en los niños."},"zh":{"q":"一个黄色标志上画着两个孩子在玩跷跷板。你应该怎么做？","o":["按喇叭提醒孩子们","停车，等孩子们离开","减速，注意可能跑到路上的孩子","保持车速，孩子们不会上马路"],"h1":"在玩耍的孩子可能不会注意车辆。","h2":"游乐场标志提醒你路边有儿童游乐场，孩子可能会跑到路上，所以你要减速并仔细观察。","p":"对。减速，注意孩子。"},"vi":{"q":"Một biển báo màu vàng có hình hai em bé chơi bập bênh. Bạn nên làm gì?","o":["Bóp còi để báo cho các em","Đậu xe và chờ các em đi chỗ khác","Chạy chậm lại và chú ý trẻ em có thể chạy ra đường","Giữ tốc độ; trẻ em sẽ không ra đường"],"h1":"Trẻ em đang chơi có thể không để ý xe cộ.","h2":"Biển sân chơi cảnh báo có sân chơi trẻ em ngay cạnh đường và trẻ em có thể chạy ra đường, nên bạn cần chạy chậm lại và quan sát kỹ.","p":"Đúng rồi. Chạy chậm lại và chú ý trẻ em."},"tl":{"q":"May dilaw na karatula na may larawan ng dalawang batang naglalaro sa seesaw. Ano ang dapat mong gawin?","o":["Bumusina para bigyan ng babala ang mga bata","Pumarada at hintaying umalis ang mga bata","Bumagal at mag-ingat sa mga batang maaaring tumakbo sa kalsada","Panatilihin ang bilis; hindi lalabas sa kalsada ang mga bata"],"h1":"Ang mga batang naglalaro ay maaaring hindi tumingin sa mga sasakyan.","h2":"Ang karatula ng palaruan ay nagbababala na may palaruan ng mga bata sa tabi ng kalsada at maaaring tumakbo ang mga bata sa kalsada, kaya dapat kang bumagal at magmasid nang mabuti.","p":"Tama. Bumagal at mag-ingat sa mga bata."},"ar":{"q":"لافتة صفراء عليها طفلان على أرجوحة توازن. ماذا يجب أن تفعل؟","o":["اضغط على البوق لتحذير الأطفال","اركن السيارة وانتظر حتى يذهب الأطفال","خفف السرعة وانتبه لأطفال قد يركضون إلى الطريق","حافظ على سرعتك؛ الأطفال لن يدخلوا الطريق"],"h1":"الأطفال الذين يلعبون قد لا ينتبهون للسيارات.","h2":"لافتة الملعب تحذّرك من أن ملعب أطفال بجانب الطريق وأن الأطفال قد يركضون إلى الطريق، لذلك خفف السرعة وانتبه جيدًا.","p":"صحيح. خفف السرعة وانتبه للأطفال."},"ht":{"q":"Yon siy jòn montre de timoun sou yon balansin. Kisa ou dwe fè?","o":["Klaksonnen pou avèti timoun yo","Pake epi tann timoun yo ale","Ralanti epi veye timoun ki ka kouri antre nan wout la","Kenbe menm vitès la; timoun yo p ap antre nan wout la"],"h1":"Timoun k ap jwe ka pa gade si gen machin.","h2":"Siy teren jwèt la avèti ou gen yon teren jwèt timoun bò wout la e timoun yo ka kouri antre nan wout la, kidonk ralanti epi veye byen.","p":"Se sa. Ralanti epi veye timoun yo."}},{"id":"signs-099","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"What kind of road does a white shield-shaped sign with a black number mark?","o":["An Interstate highway","A private road","A bike route","A U.S. route"],"h1":"Interstate shields are red and blue.","h2":"A white shield with a black number marks a U.S. route, which is different from the red and blue Interstate shield.","p":"Right. A white shield marks a U.S. route."},"es":{"q":"¿Qué tipo de vía marca una señal blanca en forma de escudo con un número negro?","o":["Una autopista interestatal","Una vía privada","Una ruta para bicicletas","Una ruta federal de EE. UU. (U.S. route)"],"h1":"Los escudos interestatales son rojos y azules.","h2":"Un escudo blanco con un número negro marca una ruta federal de EE. UU. (U.S. route), distinta del escudo rojo y azul de las interestatales.","p":"Correcto. El escudo blanco marca una U.S. route."},"zh":{"q":"白色盾形标志上有黑色数字，它表示哪种道路？","o":["州际公路（Interstate）","私人道路","自行车路线","美国国道（U.S. route）"],"h1":"州际公路的盾形标志是红色和蓝色的。","h2":"白色盾形标志上有黑色数字，表示美国国道（U.S. route），这和红蓝色的州际公路盾形标志不一样。","p":"对。白色盾形标志表示美国国道。"},"vi":{"q":"Tấm khiên màu trắng có số màu đen đánh dấu loại đường nào?","o":["Đường cao tốc liên bang (Interstate)","Đường tư nhân","Đường dành cho xe đạp","Quốc lộ (U.S. route)"],"h1":"Khiên của đường Interstate có màu đỏ và xanh dương.","h2":"Tấm khiên trắng có số màu đen đánh dấu quốc lộ (U.S. route), khác với khiên đỏ và xanh dương của đường Interstate.","p":"Đúng rồi. Khiên màu trắng đánh dấu quốc lộ."},"tl":{"q":"Anong uri ng kalsada ang minamarkahan ng puting karatulang hugis-kalasag na may itim na numero?","o":["Isang Interstate highway","Isang pribadong kalsada","Isang ruta ng bisikleta","Isang U.S. route"],"h1":"Pula at asul ang kalasag ng Interstate.","h2":"Ang puting kalasag na may itim na numero ay nagmamarka ng U.S. route, na iba sa pula at asul na kalasag ng Interstate.","p":"Tama. Ang puting kalasag ay nagmamarka ng U.S. route."},"ar":{"q":"أي نوع من الطرق تدل عليه لافتة بيضاء على شكل درع عليها رقم أسود؟","o":["طريق سريع بين الولايات (Interstate)","طريق خاص","مسار للدراجات","طريق أمريكي (U.S. route)"],"h1":"دروع طرق Interstate حمراء وزرقاء.","h2":"الدرع الأبيض الذي عليه رقم أسود يدل على طريق أمريكي (U.S. route)، وهو يختلف عن درع Interstate الأحمر والأزرق.","p":"صحيح. الدرع الأبيض يدل على طريق أمريكي (U.S. route)."},"ht":{"q":"Ki kalite wout yon siy blan ki gen fòm plak ak yon nimewo nwa make?","o":["Yon gran wout Interstate","Yon wout prive","Yon wout pou bisiklèt","Yon wout U.S. (U.S. route)"],"h1":"Plak Interstate yo wouj ak ble.","h2":"Yon plak blan ki gen yon nimewo nwa make yon wout U.S. (U.S. route), ki pa menm ak plak wouj ak ble Interstate la.","p":"Se sa. Yon plak blan make yon wout U.S."}},{"id":"signs-100","scope":"US","cat":"signs","sign":{"shape":"interstate","text":"75"},"c":0,"en":{"q":"Above a route sign, a small plaque says NORTH. What does it tell you?","o":["The route goes north from here","You are at the north end of the state","Turn north at the next light","North is closed"],"h1":"The plaque goes with the route sign below it.","h2":"A direction plaque above a route sign tells you which way that route goes, so NORTH means this road takes you north.","p":"Right. This route heads north."},"es":{"q":"Encima de una señal de ruta, una placa pequeña dice NORTH. ¿Qué le indica?","o":["Que la ruta va hacia el norte desde aquí","Que está en el extremo norte del estado","Que gire al norte en el próximo semáforo","Que el norte está cerrado"],"h1":"La placa va con la señal de ruta de abajo.","h2":"Una placa de dirección encima de una señal de ruta indica hacia dónde va esa ruta, así que NORTH quiere decir que esta vía lo lleva al norte.","p":"Correcto. Esta ruta va al norte."},"zh":{"q":"路线标志上方有一块小牌子写着 NORTH。它告诉你什么？","o":["这条路线从这里往北走","你在本州的最北端","在下一个红绿灯往北转","北边封闭了"],"h1":"这块小牌子和它下面的路线标志是一起的。","h2":"路线标志上方的方向牌告诉你这条路线往哪个方向走，所以“NORTH”（北）表示这条路带你往北走。","p":"对。这条路线往北走。"},"vi":{"q":"Phía trên biển số đường có một tấm biển nhỏ ghi NORTH. Biển đó cho bạn biết gì?","o":["Con đường này đi về hướng bắc từ đây","Bạn đang ở đầu phía bắc của tiểu bang","Rẽ về hướng bắc ở đèn giao thông kế tiếp","Hướng bắc bị đóng"],"h1":"Tấm biển nhỏ đi chung với biển số đường bên dưới nó.","h2":"Tấm biển chỉ hướng phía trên biển số đường cho bạn biết con đường đó đi về hướng nào, nên “NORTH” (Bắc) nghĩa là con đường này đưa bạn về hướng bắc.","p":"Đúng rồi. Con đường này đi về hướng bắc."},"tl":{"q":"Sa itaas ng karatula ng ruta, may maliit na plaka na nagsasabing NORTH. Ano ang sinasabi nito sa iyo?","o":["Papunta sa hilaga ang ruta mula rito","Nasa hilagang dulo ka ng estado","Lumiko pahilaga sa susunod na ilaw","Sarado ang hilaga"],"h1":"Kasama ng plaka ang karatula ng ruta sa ilalim nito.","h2":"Ang plaka ng direksyon sa itaas ng karatula ng ruta ay nagsasabi kung saan papunta ang rutang iyon, kaya ang “NORTH” (Hilaga) ay nangangahulugang dadalhin ka ng daang ito pahilaga.","p":"Tama. Papunta sa hilaga ang rutang ito."},"ar":{"q":"فوق لافتة رقم الطريق، توجد لوحة صغيرة مكتوب عليها NORTH. ماذا تخبرك؟","o":["الطريق يتجه شمالًا من هنا","أنت في الطرف الشمالي من الولاية","انعطف شمالًا عند الإشارة التالية","الاتجاه الشمالي مغلق"],"h1":"اللوحة الصغيرة تتبع لافتة الطريق التي تحتها.","h2":"لوحة الاتجاه فوق لافتة الطريق تخبرك بأي اتجاه يسير هذا الطريق، لذلك «NORTH» (شمال) تعني أن هذا الطريق يأخذك نحو الشمال.","p":"صحيح. هذا الطريق يتجه شمالًا."},"ht":{"q":"Anwo yon siy wout, gen yon ti plak ki di NORTH. Kisa li di ou?","o":["Wout la ale nan nò depi isit la","Ou nan pwent nò eta a","Vire nan direksyon nò nan pwochen limyè a","Nò a fèmen"],"h1":"Ti plak la mache ak siy wout ki anba li a.","h2":"Yon plak direksyon anwo yon siy wout di ou ki bò wout sa a ale, kidonk “NORTH” (nò) vle di wout sa a mennen ou nan direksyon nò.","p":"Se sa. Wout sa a ale nan nò."}},{"id":"signs-101","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"JCT"},"c":1,"en":{"q":"A small plaque that says JCT is above a route sign. What does it mean?","o":["The route ends here","You are coming to a junction where that route meets your road","The route is closed","You are on a toll road"],"h1":"JCT is short for junction.","h2":"JCT means junction, so the sign tells you that the route shown meets your road just ahead.","p":"Right. A junction with that route is ahead."},"es":{"q":"Una placa pequeña que dice JCT está encima de una señal de ruta. ¿Qué significa?","o":["Que la ruta termina aquí","Que se acerca un cruce donde esa ruta se une a su vía","Que la ruta está cerrada","Que está en una vía de peaje"],"h1":"JCT es la abreviatura de junction, que quiere decir cruce o empalme.","h2":"JCT significa junction (empalme), así que la señal le indica que la ruta mostrada se une a su vía un poco más adelante.","p":"Correcto. Viene un empalme con esa ruta."},"zh":{"q":"路线标志上方有一块小牌子写着 JCT。这是什么意思？","o":["这条路线在这里结束","你快到路口了，那条路线在那里和你的路相交","这条路线封闭了","你在收费公路上"],"h1":"JCT 是 junction（路口、交会处）的缩写。","h2":"“JCT” 表示交会处，所以这个标志告诉你，标志上的那条路线就在前方和你的路相交。","p":"对。前方是和那条路线的交会处。"},"vi":{"q":"Phía trên biển số đường có một tấm biển nhỏ ghi JCT. Biển đó có nghĩa là gì?","o":["Con đường này hết ở đây","Bạn sắp tới chỗ giao nhau, nơi con đường đó gặp đường của bạn","Con đường này bị đóng","Bạn đang đi trên đường có thu phí"],"h1":"JCT là chữ viết tắt của junction (chỗ giao nhau).","h2":"“JCT” nghĩa là chỗ giao nhau, nên biển này cho bạn biết con đường ghi trên biển gặp đường của bạn ngay phía trước.","p":"Đúng rồi. Phía trước là chỗ giao nhau với con đường đó."},"tl":{"q":"May maliit na plaka na nagsasabing JCT sa itaas ng karatula ng ruta. Ano ang ibig sabihin nito?","o":["Dito nagtatapos ang ruta","Malapit ka na sa junction kung saan nagsasalubong ang rutang iyon at ang daan mo","Sarado ang ruta","Nasa toll road ka"],"h1":"Ang JCT ay pinaikling junction (salubungan ng daan).","h2":"Ang “JCT” ay nangangahulugang junction, kaya sinasabi ng karatula na ang rutang nakasulat ay sasalubong sa daan mo sa unahan lang.","p":"Tama. May junction sa rutang iyon sa unahan."},"ar":{"q":"لوحة صغيرة مكتوب عليها JCT فوق لافتة رقم الطريق. ماذا تعني؟","o":["الطريق ينتهي هنا","أنت تقترب من تقاطع يلتقي فيه ذلك الطريق بطريقك","الطريق مغلق","أنت على طريق برسوم"],"h1":"JCT اختصار لكلمة junction (تقاطع).","h2":"«JCT» تعني تقاطع، لذلك تخبرك اللافتة أن الطريق المكتوب عليها يلتقي بطريقك بعد قليل.","p":"صحيح. يوجد تقاطع مع ذلك الطريق في الأمام."},"ht":{"q":"Yon ti plak ki di JCT anwo yon siy wout. Kisa li vle di?","o":["Wout la fini isit la","Ou prèske rive nan yon kafou kote wout sa a kontre ak wout ou a","Wout la fèmen","Ou sou yon wout peyan"],"h1":"JCT se yon fason kout pou ekri junction (kafou).","h2":"“JCT” vle di kafou, kidonk siy la di ou wout ki make sou li a kontre ak wout ou a touprè devan.","p":"Se sa. Gen yon kafou ak wout sa a pi devan."}},{"id":"signs-102","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"MILE 12"},"c":2,"en":{"q":"On a highway, the small green mile marker numbers usually get bigger as you drive in which directions?","o":["South and west","Toward the nearest city","North and east","Toward the ocean"],"h1":"Counting starts at the south and west state lines.","h2":"Mile markers usually start at zero at the south or west state line, so the numbers get bigger as you drive north or east.","p":"Right. The numbers grow going north or east."},"es":{"q":"En una carretera, ¿en qué dirección suelen aumentar los números de los pequeños postes verdes de millas?","o":["Hacia el sur y el oeste","Hacia la ciudad más cercana","Hacia el norte y el este","Hacia el mar"],"h1":"La cuenta empieza en las fronteras sur y oeste del estado.","h2":"Los postes de millas suelen empezar en cero en la frontera sur u oeste del estado, así que los números aumentan al manejar hacia el norte o el este.","p":"Correcto. Los números aumentan hacia el norte o el este."},"zh":{"q":"在公路上，绿色的小里程标数字通常往哪个方向开时会变大？","o":["往南和往西","往最近的城市","往北和往东","往海边"],"h1":"里程从本州南边和西边的州界开始算。","h2":"里程标通常在南边或西边的州界从零开始，所以你往北或往东开时，数字会变大。","p":"对。往北或往东开，数字会变大。"},"vi":{"q":"Trên đường cao tốc, số trên các cột mốc dặm nhỏ màu xanh lá thường tăng lên khi bạn chạy theo hướng nào?","o":["Hướng nam và hướng tây","Về phía thành phố gần nhất","Hướng bắc và hướng đông","Về phía biển"],"h1":"Việc đếm bắt đầu từ ranh giới tiểu bang ở phía nam và phía tây.","h2":"Cột mốc dặm thường bắt đầu từ số không ở ranh giới tiểu bang phía nam hoặc phía tây, nên số tăng lên khi bạn chạy về hướng bắc hoặc hướng đông.","p":"Đúng rồi. Số tăng lên khi đi về hướng bắc hoặc đông."},"tl":{"q":"Sa highway, ang numero sa maliliit na berdeng mile marker ay karaniwang lumalaki habang nagmamaneho ka sa aling mga direksyon?","o":["Timog at kanluran","Papunta sa pinakamalapit na lungsod","Hilaga at silangan","Papunta sa dagat"],"h1":"Nagsisimula ang bilang sa hangganan ng estado sa timog at kanluran.","h2":"Karaniwang nagsisimula sa zero ang mile marker sa hangganan ng estado sa timog o kanluran, kaya lumalaki ang numero habang nagmamaneho ka pahilaga o pasilangan.","p":"Tama. Lumalaki ang numero papuntang hilaga o silangan."},"ar":{"q":"على الطريق السريع، أرقام علامات الأميال الخضراء الصغيرة تكبر عادةً عندما تقود في أي اتجاهين؟","o":["الجنوب والغرب","نحو أقرب مدينة","الشمال والشرق","نحو البحر"],"h1":"العدّ يبدأ من حدود الولاية الجنوبية والغربية.","h2":"علامات الأميال تبدأ عادةً من الصفر عند حدود الولاية الجنوبية أو الغربية، لذلك تكبر الأرقام عندما تقود نحو الشمال أو الشرق.","p":"صحيح. الأرقام تكبر باتجاه الشمال أو الشرق."},"ht":{"q":"Sou gran wout, ti mak mil vèt yo, nimewo yo konn vin pi gwo lè ou kondui nan ki direksyon?","o":["Sid ak lwès","Nan direksyon vil ki pi pre a","Nò ak lès","Nan direksyon lanmè a"],"h1":"Kontaj la kòmanse nan fwontyè eta a nan sid ak nan lwès.","h2":"Mak mil yo konn kòmanse a zewo nan fwontyè eta a nan sid oswa nan lwès, kidonk nimewo yo vin pi gwo lè ou kondui ale nan nò oswa nan lès.","p":"Se sa. Nimewo yo vin pi gwo lè ou ale nan nò oswa nan lès."}},{"id":"signs-103","scope":"US","cat":"signs","sign":{"shape":"rect-yellow","text":"EXIT ONLY"},"c":3,"en":{"q":"On a green freeway sign, a yellow panel that says EXIT ONLY is above your lane. What does it mean?","o":["Your lane is closed","This exit is only for trucks","You may exit only on weekends","Your lane will leave the freeway at this exit"],"h1":"Think about where your lane goes.","h2":"A yellow EXIT ONLY panel over your lane means that lane leaves the freeway at the exit; move over early if you want to stay on.","p":"Right. Your lane exits here."},"es":{"q":"En una señal verde de autopista, un panel amarillo que dice EXIT ONLY está encima de su carril. ¿Qué significa?","o":["Su carril está cerrado","Esta salida es solo para camiones","Solo se puede salir los fines de semana","Su carril sale de la autopista en esta salida"],"h1":"Piense adónde va su carril.","h2":"Un panel amarillo EXIT ONLY encima de su carril significa que ese carril sale de la autopista; cámbiese temprano si quiere seguir en ella.","p":"Correcto. Su carril sale aquí."},"zh":{"q":"高速公路的绿色标志上，你的车道上方有一块写着 EXIT ONLY 的黄色牌子。这是什么意思？","o":["你的车道封闭了","这个出口只给卡车用","你只有周末才能从这里出去","你的车道会在这个出口离开高速公路"],"h1":"想一想你的车道通往哪里。","h2":"你的车道上方有黄色的“EXIT ONLY”（只能出口）牌子，表示这条车道会在这个出口离开高速公路；如果你想继续走高速，要提早换道。","p":"对。你的车道从这里出去。"},"vi":{"q":"Trên biển xanh lá của đường cao tốc, có một ô màu vàng ghi EXIT ONLY ở phía trên làn của bạn. Điều đó có nghĩa là gì?","o":["Làn của bạn bị đóng","Lối ra này chỉ dành cho xe tải","Bạn chỉ được ra vào cuối tuần","Làn của bạn sẽ rời đường cao tốc ở lối ra này"],"h1":"Hãy nghĩ xem làn của bạn đi về đâu.","h2":"Ô màu vàng “EXIT ONLY” (Chỉ để ra) phía trên làn của bạn nghĩa là làn đó rời đường cao tốc ở lối ra này; nếu muốn ở lại trên đường cao tốc, hãy chuyển làn sớm.","p":"Đúng rồi. Làn của bạn ra ở đây."},"tl":{"q":"Sa berdeng karatula ng freeway, may dilaw na panel na nagsasabing EXIT ONLY sa itaas ng lane mo. Ano ang ibig sabihin nito?","o":["Sarado ang lane mo","Para lang sa mga trak ang exit na ito","Puwede kang lumabas tuwing weekend lang","Lalabas ng freeway ang lane mo sa exit na ito"],"h1":"Isipin kung saan papunta ang lane mo.","h2":"Ang dilaw na panel na “EXIT ONLY” (Labasan lang) sa itaas ng lane mo ay nangangahulugang lalabas ng freeway ang lane na iyon sa exit; lumipat nang maaga kung gusto mong manatili sa freeway.","p":"Tama. Lalabas dito ang lane mo."},"ar":{"q":"على لافتة خضراء في الطريق السريع، توجد لوحة صفراء مكتوب عليها EXIT ONLY فوق مسارك. ماذا تعني؟","o":["مسارك مغلق","هذا المخرج للشاحنات فقط","يمكنك الخروج في عطلة نهاية الأسبوع فقط","مسارك سيخرج من الطريق السريع عند هذا المخرج"],"h1":"فكّر إلى أين يذهب مسارك.","h2":"اللوحة الصفراء «EXIT ONLY» (للخروج فقط) فوق مسارك تعني أن هذا المسار يخرج من الطريق السريع عند المخرج؛ انتقل إلى مسار آخر مبكرًا إذا أردت البقاء على الطريق السريع.","p":"صحيح. مسارك يخرج هنا."},"ht":{"q":"Sou yon siy vèt otowout, gen yon panno jòn ki di EXIT ONLY anwo liy ou a. Kisa sa vle di?","o":["Liy ou a fèmen","Sòti sa a se pou kamyon sèlman","Ou ka sòti sèlman nan wikenn","Liy ou a pral kite otowout la nan sòti sa a"],"h1":"Panse ki kote liy ou a ale.","h2":"Yon panno jòn “EXIT ONLY” (sòti sèlman) anwo liy ou a vle di liy sa a kite otowout la nan sòti a; chanje liy bonè si ou vle rete sou otowout la.","p":"Se sa. Liy ou a sòti isit la."}},{"id":"signs-104","scope":"US","cat":"signs","sign":{"shape":"rect-yellow","text":"LEFT"},"c":0,"en":{"q":"A green freeway sign has a yellow panel that says LEFT. What does it tell you?","o":["The exit is on the left side of the freeway","The left lane is closed","You must keep left to stay on the freeway","Left turns are allowed at the end of the ramp"],"h1":"Most exits are on the right.","h2":"A LEFT panel on an exit sign tells you the exit leaves from the left side of the freeway, so you need to be in the left lane.","p":"Right. The exit is on the left."},"es":{"q":"Una señal verde de autopista tiene un panel amarillo que dice LEFT. ¿Qué le indica?","o":["Que la salida está al lado izquierdo de la autopista","Que el carril izquierdo está cerrado","Que debe ir a la izquierda para seguir en la autopista","Que al final de la rampa se puede girar a la izquierda"],"h1":"La mayoría de las salidas están a la derecha.","h2":"Un panel LEFT en una señal de salida indica que la salida está al lado izquierdo de la autopista, así que debe ir en el carril izquierdo.","p":"Correcto. La salida está a la izquierda."},"zh":{"q":"高速公路的绿色标志上有一块写着 LEFT 的黄色牌子。它告诉你什么？","o":["出口在高速公路的左边","左边车道封闭了","你必须靠左才能继续走高速公路","匝道尽头可以左转"],"h1":"大多数出口在右边。","h2":"出口标志上的“LEFT”（左）牌子告诉你，这个出口从高速公路的左边出去，所以你要在最左边的车道。","p":"对。出口在左边。"},"vi":{"q":"Một biển xanh lá trên đường cao tốc có ô màu vàng ghi LEFT. Biển đó cho bạn biết gì?","o":["Lối ra nằm ở bên trái đường cao tốc","Làn bên trái bị đóng","Bạn phải đi bên trái để ở lại trên đường cao tốc","Được rẽ trái ở cuối đường dẫn"],"h1":"Phần lớn lối ra nằm ở bên phải.","h2":"Ô “LEFT” (Bên trái) trên biển lối ra cho bạn biết lối ra nằm ở bên trái đường cao tốc, nên bạn cần đi ở làn bên trái.","p":"Đúng rồi. Lối ra ở bên trái."},"tl":{"q":"May berdeng karatula sa freeway na may dilaw na panel na nagsasabing LEFT. Ano ang sinasabi nito sa iyo?","o":["Nasa kaliwang bahagi ng freeway ang exit","Sarado ang kaliwang lane","Dapat kang manatili sa kaliwa para manatili sa freeway","Puwedeng kumaliwa sa dulo ng ramp"],"h1":"Karamihan ng exit ay nasa kanan.","h2":"Ang panel na “LEFT” (Kaliwa) sa karatula ng exit ay nagsasabing lumalabas ang exit sa kaliwang bahagi ng freeway, kaya kailangan mong nasa kaliwang lane.","p":"Tama. Nasa kaliwa ang exit."},"ar":{"q":"لافتة خضراء في الطريق السريع عليها لوحة صفراء مكتوب عليها LEFT. ماذا تخبرك؟","o":["المخرج على الجانب الأيسر من الطريق السريع","المسار الأيسر مغلق","يجب أن تبقى على اليسار لتبقى على الطريق السريع","الانعطاف يسارًا مسموح في نهاية المنحدر"],"h1":"معظم المخارج على اليمين.","h2":"لوحة «LEFT» (يسار) على لافتة المخرج تخبرك أن المخرج يخرج من الجانب الأيسر للطريق السريع، لذلك يجب أن تكون في المسار الأيسر.","p":"صحيح. المخرج على اليسار."},"ht":{"q":"Yon siy vèt otowout gen yon panno jòn ki di LEFT. Kisa li di ou?","o":["Sòti a sou bò goch otowout la","Liy goch la fèmen","Ou dwe rete sou bò goch pou ou rete sou otowout la","Ou gen dwa vire agoch nan bout ranp lan"],"h1":"Pifò sòti yo sou bò dwat.","h2":"Yon panno “LEFT” (goch) sou yon siy sòti di ou sòti a kite otowout la sou bò goch, kidonk ou bezwen nan liy goch la.","p":"Se sa. Sòti a sou bò goch."}},{"id":"signs-105","scope":"US","cat":"signs","sign":{"shape":"rect-green","text":"EXIT 1/2 MILE"},"c":1,"en":{"q":"A green freeway sign says EXIT 1/2 MILE. What does it tell you?","o":["You must exit within half a minute","The exit is half a mile ahead, so get ready to move over","The freeway ends in half a mile","The speed limit drops in half a mile"],"h1":"This is an advance sign.","h2":"EXIT 1/2 MILE means the exit is half a mile ahead, giving you time to signal and move into the correct lane.","p":"Right. The exit is half a mile ahead."},"es":{"q":"Una señal verde de autopista dice EXIT 1/2 MILE. ¿Qué le indica?","o":["Que debe salir en medio minuto","Que la salida está a media milla, así que prepárese para cambiarse de carril","Que la autopista termina en media milla","Que el límite baja en media milla"],"h1":"Es una señal de aviso anticipado.","h2":"EXIT 1/2 MILE significa que la salida está a media milla, lo que le da tiempo para señalar y pasarse al carril correcto.","p":"Correcto. La salida está a media milla."},"zh":{"q":"高速公路的绿色标志写着 EXIT 1/2 MILE。它告诉你什么？","o":["你必须在半分钟内出去","出口在前方半英里，准备换道","高速公路在半英里后结束","半英里后限速会降低"],"h1":"这是一个提前告知的标志。","h2":"“EXIT 1/2 MILE”（出口在 1/2 英里外）表示出口在前方半英里，让你有时间打方向灯并换到正确的车道。","p":"对。出口在前方半英里。"},"vi":{"q":"Một biển xanh lá trên đường cao tốc ghi EXIT 1/2 MILE. Biển đó cho bạn biết gì?","o":["Bạn phải ra trong vòng nửa phút","Lối ra ở phía trước nửa dặm, nên hãy chuẩn bị chuyển làn","Đường cao tốc hết sau nửa dặm","Giới hạn tốc độ giảm sau nửa dặm"],"h1":"Đây là biển báo trước.","h2":"“EXIT 1/2 MILE” (Lối ra cách 1/2 dặm) nghĩa là lối ra ở phía trước nửa dặm, cho bạn thời gian bật đèn xi nhan và chuyển vào đúng làn.","p":"Đúng rồi. Lối ra ở phía trước nửa dặm."},"tl":{"q":"May berdeng karatula sa freeway na nagsasabing EXIT 1/2 MILE. Ano ang sinasabi nito sa iyo?","o":["Dapat kang lumabas sa loob ng kalahating minuto","Kalahating milya pa ang exit sa unahan, kaya maghandang lumipat ng lane","Matatapos ang freeway sa loob ng kalahating milya","Bababa ang speed limit pagkalipas ng kalahating milya"],"h1":"Ito ay karatulang paunang babala.","h2":"Ang “EXIT 1/2 MILE” (Exit sa 1/2 milya) ay nangangahulugang kalahating milya pa ang exit sa unahan, kaya may oras kang mag-signal at lumipat sa tamang lane.","p":"Tama. Kalahating milya pa ang exit sa unahan."},"ar":{"q":"لافتة خضراء في الطريق السريع مكتوب عليها EXIT 1/2 MILE. ماذا تخبرك؟","o":["يجب أن تخرج خلال نصف دقيقة","المخرج بعد نصف ميل، فاستعد للانتقال إلى مسار آخر","الطريق السريع ينتهي بعد نصف ميل","حد السرعة ينخفض بعد نصف ميل"],"h1":"هذه لافتة إنذار مسبق.","h2":"«EXIT 1/2 MILE» (المخرج بعد 1/2 ميل) تعني أن المخرج أمامك بعد نصف ميل، فيكون لديك وقت لتشغيل الإشارة والانتقال إلى المسار الصحيح.","p":"صحيح. المخرج بعد نصف ميل."},"ht":{"q":"Yon siy vèt otowout di EXIT 1/2 MILE. Kisa li di ou?","o":["Ou dwe sòti nan mwatye yon minit","Sòti a se mwatye yon mil pi devan, kidonk pare pou chanje liy","Otowout la fini nan mwatye yon mil","Limit vitès la ap bese nan mwatye yon mil"],"h1":"Sa a se yon siy ki avèti ou davans.","h2":"“EXIT 1/2 MILE” (sòti nan 1/2 mil) vle di sòti a se mwatye yon mil pi devan, sa ba ou tan pou mete siyal epi antre nan bon liy lan.","p":"Se sa. Sòti a se mwatye yon mil pi devan."}},{"id":"signs-106","scope":"US","cat":"signs","sign":null,"c":2,"en":{"q":"Over a freeway, a green sign shows white arrows pointing down at some lanes, with the name of a city. What do the arrows show?","o":["Which lanes are closed","Where to stop for a toll","Which lanes continue toward that city","Where the road goes downhill"],"h1":"Each arrow points to a lane.","h2":"Downward arrows on an overhead guide sign point to the lanes that go toward the place named on the sign.","p":"Right. They show which lanes go that way."},"es":{"q":"Sobre una autopista, una señal verde muestra flechas blancas que apuntan hacia abajo a algunos carriles, con el nombre de una ciudad. ¿Qué indican las flechas?","o":["Qué carriles están cerrados","Dónde pararse a pagar peaje","Qué carriles siguen hacia esa ciudad","Dónde la vía va de bajada"],"h1":"Cada flecha apunta a un carril.","h2":"Las flechas hacia abajo en una señal elevada apuntan a los carriles que van hacia el lugar nombrado en la señal.","p":"Correcto. Indican qué carriles van en esa dirección."},"zh":{"q":"高速公路上方有一块绿色标志，上面有白色箭头朝下指着几条车道，还写着一个城市的名字。这些箭头表示什么？","o":["哪些车道封闭了","在哪里停车交过路费","哪些车道继续通往那个城市","哪里的路是下坡"],"h1":"每个箭头指着一条车道。","h2":"头顶指路标志上朝下的箭头，指的是通往标志上那个地方的车道。","p":"对。箭头告诉你哪些车道往那边走。"},"vi":{"q":"Phía trên đường cao tốc, một biển xanh lá có mũi tên trắng chỉ xuống một số làn, kèm tên một thành phố. Các mũi tên cho biết gì?","o":["Làn nào bị đóng","Chỗ dừng để trả phí","Làn nào tiếp tục đi về thành phố đó","Chỗ nào đường đổ dốc"],"h1":"Mỗi mũi tên chỉ vào một làn.","h2":"Mũi tên chỉ xuống trên biển chỉ dẫn phía trên đầu chỉ vào những làn đi về nơi ghi trên biển.","p":"Đúng rồi. Mũi tên cho biết làn nào đi về hướng đó."},"tl":{"q":"Sa itaas ng freeway, may berdeng karatula na may puting palasong nakaturo pababa sa ilang lane, at may pangalan ng lungsod. Ano ang ipinapakita ng mga palaso?","o":["Kung aling mga lane ang sarado","Kung saan hihinto para magbayad ng toll","Kung aling mga lane ang tuloy papunta sa lungsod na iyon","Kung saan pababa ang kalsada"],"h1":"Bawat palaso ay nakaturo sa isang lane.","h2":"Ang mga palasong nakaturo pababa sa gabay na karatula sa itaas ay nakaturo sa mga lane na papunta sa lugar na nakasulat sa karatula.","p":"Tama. Ipinapakita nito kung aling mga lane ang papunta roon."},"ar":{"q":"فوق الطريق السريع، لافتة خضراء عليها أسهم بيضاء تشير إلى الأسفل نحو بعض المسارات، ومعها اسم مدينة. ماذا تُظهر الأسهم؟","o":["أي المسارات مغلقة","أين تتوقف لدفع الرسوم","أي المسارات تستمر نحو تلك المدينة","أين ينحدر الطريق إلى الأسفل"],"h1":"كل سهم يشير إلى مسار.","h2":"الأسهم المتجهة إلى الأسفل على لافتة الإرشاد المعلّقة فوق الطريق تشير إلى المسارات التي تذهب نحو المكان المكتوب على اللافتة.","p":"صحيح. تُظهر أي المسارات تذهب في ذلك الاتجاه."},"ht":{"q":"Anwo yon otowout, yon siy vèt montre flèch blan ki pwente anba sou kèk liy, ak non yon vil. Kisa flèch yo montre?","o":["Ki liy ki fèmen","Ki kote pou kanpe peye peyaj","Ki liy ki kontinye ale nan vil sa a","Ki kote wout la desann"],"h1":"Chak flèch pwente sou yon liy.","h2":"Flèch ki pwente anba sou yon siy gid anwo tèt ou montre liy ki ale nan kote ki make sou siy la.","p":"Se sa. Yo montre ki liy ki ale bò sa a."}},{"id":"signs-107","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"REST AREA"},"c":3,"en":{"q":"A blue sign says REST AREA. What will you find there?","o":["A police station","A hotel","A truck repair shop only","A place off the road to stop, rest and use restrooms"],"h1":"Blue signs show services for drivers.","h2":"A REST AREA sign points to a place off the road where you can safely stop, rest and use restrooms, which helps when you feel tired.","p":"Right. A safe place to stop and rest."},"es":{"q":"Una señal azul dice REST AREA. ¿Qué va a encontrar allí?","o":["Una estación de policía","Un hotel","Solo un taller de camiones","Un lugar fuera de la vía para parar, descansar y usar baños"],"h1":"Las señales azules muestran servicios para conductores.","h2":"Una señal REST AREA indica un lugar fuera de la vía donde puede parar con seguridad, descansar y usar baños, lo que ayuda cuando se siente cansado.","p":"Correcto. Un lugar seguro para parar y descansar."},"zh":{"q":"一个蓝色标志写着 REST AREA。你在那里会找到什么？","o":["警察局","旅馆","只有卡车修理店","一个离开道路、可以停车、休息和上厕所的地方"],"h1":"蓝色标志告诉你司机服务的地点。","h2":"“REST AREA”（休息区）标志指向一个离开道路的地方，你可以在那里安全停车、休息和上厕所，觉得累的时候很有帮助。","p":"对。一个可以安全停车休息的地方。"},"vi":{"q":"Một biển màu xanh dương ghi REST AREA. Bạn sẽ thấy gì ở đó?","o":["Một đồn cảnh sát","Một khách sạn","Chỉ có tiệm sửa xe tải","Một chỗ ngoài đường để dừng, nghỉ ngơi và đi vệ sinh"],"h1":"Biển màu xanh dương cho biết các dịch vụ cho người lái xe.","h2":"Biển “REST AREA” (Trạm dừng nghỉ) chỉ tới một chỗ ngoài đường nơi bạn có thể dừng an toàn, nghỉ ngơi và đi vệ sinh, rất có ích khi bạn thấy mệt.","p":"Đúng rồi. Một chỗ an toàn để dừng và nghỉ ngơi."},"tl":{"q":"May asul na karatula na nagsasabing REST AREA. Ano ang makikita mo roon?","o":["Isang istasyon ng pulis","Isang hotel","Pagawaan lang ng trak","Isang lugar sa labas ng kalsada para huminto, magpahinga at gumamit ng banyo"],"h1":"Ang mga asul na karatula ay nagpapakita ng mga serbisyo para sa motorista.","h2":"Ang karatulang “REST AREA” (Pahingahan) ay nakaturo sa isang lugar sa labas ng kalsada kung saan ligtas kang makakahinto, makakapagpahinga at makakagamit ng banyo, na nakakatulong kapag pagod ka.","p":"Tama. Isang ligtas na lugar para huminto at magpahinga."},"ar":{"q":"لافتة زرقاء مكتوب عليها REST AREA. ماذا ستجد هناك؟","o":["مركز شرطة","فندق","ورشة لإصلاح الشاحنات فقط","مكان خارج الطريق للتوقف والاستراحة واستخدام دورات المياه"],"h1":"اللافتات الزرقاء تُظهر خدمات السائقين.","h2":"لافتة «REST AREA» (استراحة) تدلّك على مكان خارج الطريق يمكنك فيه أن تتوقف بأمان وتستريح وتستخدم دورات المياه، وهذا يساعدك عندما تشعر بالتعب.","p":"صحيح. مكان آمن للتوقف والاستراحة."},"ht":{"q":"Yon siy ble di REST AREA. Kisa ou pral jwenn la?","o":["Yon estasyon polis","Yon otèl","Yon garaj pou kamyon sèlman","Yon kote bò wout la pou kanpe, repoze ou epi itilize twalèt"],"h1":"Siy ble yo montre sèvis pou chofè.","h2":"Yon siy “REST AREA” (kote pou repoze) montre ou yon kote bò wout la kote ou ka kanpe san danje, repoze ou epi itilize twalèt, sa ede lè ou santi ou fatige.","p":"Se sa. Yon kote san danje pou kanpe epi repoze ou."}},{"id":"signs-108","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"TRAVEL INFO CALL 511"},"c":0,"en":{"q":"A blue sign says TRAVEL INFO CALL 511. What can you get by calling 511?","o":["Road, traffic and weather information","Emergency help from police","A free tow truck","Directions to a hospital only"],"h1":"For emergencies you call 911, not 511.","h2":"The 511 sign tells you that calling 511 gives road, traffic and weather information; for an emergency you call 911.","p":"Right. 511 gives travel information."},"es":{"q":"Una señal azul dice TRAVEL INFO CALL 511. ¿Qué puede obtener llamando al 511?","o":["Información de vías, tráfico y clima","Ayuda de emergencia de la policía","Una grúa gratis","Solo direcciones a un hospital"],"h1":"Para emergencias se llama al 911, no al 511.","h2":"La señal 511 indica que al llamar al 511 recibe información de vías, tráfico y clima; para una emergencia se llama al 911.","p":"Correcto. El 511 da información de viaje."},"zh":{"q":"一个蓝色标志写着 TRAVEL INFO CALL 511。打 511 可以得到什么？","o":["道路、交通和天气信息","警察的紧急帮助","免费拖车","只有去医院的路线"],"h1":"紧急情况要打 911，不是 511。","h2":"“511”标志告诉你，打 511 可以得到道路、交通和天气信息；紧急情况要打 911。","p":"对。511 提供出行信息。"},"vi":{"q":"Một biển màu xanh dương ghi TRAVEL INFO CALL 511. Gọi 511 bạn sẽ được gì?","o":["Thông tin về đường sá, giao thông và thời tiết","Cảnh sát giúp đỡ khẩn cấp","Xe kéo miễn phí","Chỉ có đường đi tới bệnh viện"],"h1":"Khi khẩn cấp bạn gọi 911, không phải 511.","h2":"Biển “511” cho bạn biết gọi 511 sẽ có thông tin về đường sá, giao thông và thời tiết; khi khẩn cấp bạn gọi 911.","p":"Đúng rồi. Số 511 cho thông tin đi đường."},"tl":{"q":"May asul na karatula na nagsasabing TRAVEL INFO CALL 511. Ano ang makukuha mo kapag tumawag ka sa 511?","o":["Impormasyon tungkol sa kalsada, trapiko at panahon","Tulong pang-emergency mula sa pulis","Libreng tow truck","Direksyon papunta sa ospital lang"],"h1":"Sa emergency, 911 ang tinatawagan, hindi 511.","h2":"Ang karatulang “511” ay nagsasabing ang pagtawag sa 511 ay nagbibigay ng impormasyon tungkol sa kalsada, trapiko at panahon; sa emergency, tumawag ka sa 911.","p":"Tama. Nagbibigay ang 511 ng impormasyon sa biyahe."},"ar":{"q":"لافتة زرقاء مكتوب عليها TRAVEL INFO CALL 511. ماذا تحصل عليه إذا اتصلت بالرقم 511؟","o":["معلومات عن الطرق وحركة المرور والطقس","مساعدة طارئة من الشرطة","شاحنة سحب مجانية","اتجاهات إلى المستشفى فقط"],"h1":"في حالات الطوارئ تتصل بالرقم 911، وليس 511.","h2":"لافتة «511» تخبرك أن الاتصال بالرقم 511 يعطيك معلومات عن الطرق وحركة المرور والطقس؛ وفي حالة الطوارئ تتصل بالرقم 911.","p":"صحيح. الرقم 511 يعطي معلومات السفر."},"ht":{"q":"Yon siy ble di TRAVEL INFO CALL 511. Kisa ou ka jwenn si ou rele 511?","o":["Enfòmasyon sou wout, sikilasyon ak tan an","Èd ijans nan men polis","Yon kamyon remòk gratis","Direksyon pou ale lopital sèlman"],"h1":"Pou yon ijans ou rele 911, pa 511.","h2":"Siy “511” la di ou lè ou rele 511 ou jwenn enfòmasyon sou wout, sikilasyon ak tan an; pou yon ijans ou rele 911.","p":"Se sa. 511 bay enfòmasyon pou vwayaj."}},{"id":"signs-109","scope":"US","cat":"signs","sign":{"shape":"rect-blue","text":"EVACUATION ROUTE"},"c":1,"en":{"q":"A blue and white sign says EVACUATION ROUTE. What is it for?","o":["To show the way to a gas station","To guide people out of an area during an emergency, such as a hurricane","To mark a road closed to cars","To show a scenic drive"],"h1":"Evacuate means leave a dangerous place.","h2":"An EVACUATION ROUTE sign shows the road to follow to leave an area safely during an emergency like a hurricane or flood.","p":"Right. It shows the way out in an emergency."},"es":{"q":"Una señal azul y blanca dice EVACUATION ROUTE. ¿Para qué sirve?","o":["Para indicar el camino a una gasolinera","Para guiar a la gente fuera de una zona en una emergencia, como un huracán","Para marcar una vía cerrada a los carros","Para indicar una ruta panorámica"],"h1":"Evacuar es salir de un lugar peligroso.","h2":"Una señal EVACUATION ROUTE muestra la vía que debe seguir para salir con seguridad de una zona durante una emergencia, como un huracán o una inundación.","p":"Correcto. Muestra la salida en una emergencia."},"zh":{"q":"一个蓝白色标志写着 EVACUATION ROUTE。它是做什么用的？","o":["指出去加油站的路","在紧急情况下（比如飓风）引导人们离开一个地区","标出不准汽车走的路","指出风景路线"],"h1":"疏散（evacuate）的意思是离开危险的地方。","h2":"“EVACUATION ROUTE”（疏散路线）标志告诉你，在飓风或洪水等紧急情况下，要沿着哪条路安全离开一个地区。","p":"对。它告诉你紧急情况时怎么离开。"},"vi":{"q":"Một biển màu xanh dương và trắng ghi EVACUATION ROUTE. Biển này dùng để làm gì?","o":["Chỉ đường tới trạm xăng","Hướng dẫn người dân rời khỏi một khu vực khi có tình trạng khẩn cấp, như bão lớn","Đánh dấu con đường cấm xe hơi","Chỉ một con đường có cảnh đẹp"],"h1":"Sơ tán nghĩa là rời khỏi nơi nguy hiểm.","h2":"Biển “EVACUATION ROUTE” (Đường sơ tán) chỉ con đường cần đi theo để rời khỏi một khu vực an toàn khi có tình trạng khẩn cấp như bão lớn hoặc lũ lụt.","p":"Đúng rồi. Biển chỉ đường thoát ra khi khẩn cấp."},"tl":{"q":"May asul at puting karatula na nagsasabing EVACUATION ROUTE. Para saan ito?","o":["Para ituro ang daan papunta sa gasolinahan","Para gabayan ang mga tao palabas ng isang lugar sa panahon ng emergency, tulad ng bagyo","Para markahan ang kalsadang sarado sa mga kotse","Para ituro ang magandang tanawin na daan"],"h1":"Ang evacuate ay nangangahulugang umalis sa mapanganib na lugar.","h2":"Ang karatulang “EVACUATION ROUTE” (Daan ng paglikas) ay nagpapakita ng daang susundan para ligtas na makaalis sa isang lugar sa panahon ng emergency tulad ng bagyo o baha.","p":"Tama. Ipinapakita nito ang daan palabas sa emergency."},"ar":{"q":"لافتة زرقاء وبيضاء مكتوب عليها EVACUATION ROUTE. لماذا توضع؟","o":["لتُظهر الطريق إلى محطة وقود","لترشد الناس إلى الخروج من منطقة أثناء حالة طوارئ، مثل الإعصار","لتحدد طريقًا مغلقًا أمام السيارات","لتُظهر طريقًا ذا مناظر جميلة"],"h1":"الإخلاء يعني مغادرة مكان خطر.","h2":"لافتة «EVACUATION ROUTE» (طريق الإخلاء) تُظهر الطريق الذي تتبعه لتغادر منطقة بأمان أثناء حالة طوارئ مثل الإعصار أو الفيضان.","p":"صحيح. تُظهر طريق الخروج في حالة الطوارئ."},"ht":{"q":"Yon siy ble ak blan di EVACUATION ROUTE. Pou kisa li ye?","o":["Pou montre wout pou ale nan yon pomp gaz","Pou gide moun soti nan yon zòn pandan yon ijans, tankou yon siklòn","Pou make yon wout ki fèmen pou machin","Pou montre yon wout ki gen bèl peyizaj"],"h1":"Evakye vle di kite yon kote ki danjere.","h2":"Yon siy “EVACUATION ROUTE” (wout evakyasyon) montre wout pou ou swiv pou kite yon zòn san danje pandan yon ijans tankou yon siklòn oswa yon inondasyon.","p":"Se sa. Li montre wout pou soti lè gen yon ijans."}},{"id":"signs-110","scope":"US","cat":"signs","sign":null,"c":2,"en":{"q":"You see a fluorescent pink sign on the highway. What does pink usually mean?","o":["A school zone is ahead","A park is nearby","A traffic incident, such as a crash, is ahead","Gas and food are at the next exit"],"h1":"Pink is used for sudden, unplanned events.","h2":"Fluorescent pink signs are used for traffic incidents, such as a crash, so slow down and expect changes ahead.","p":"Right. Pink means an incident ahead."},"es":{"q":"Usted ve una señal rosa fluorescente en la carretera. ¿Qué suele significar el rosa?","o":["Que hay una zona escolar adelante","Que hay un parque cerca","Que hay un incidente de tránsito adelante, como un choque","Que hay gasolina y comida en la próxima salida"],"h1":"El rosa se usa para sucesos repentinos, no planeados.","h2":"Las señales rosa fluorescente se usan para incidentes de tránsito, como un choque, así que baje la velocidad y espere cambios adelante.","p":"Correcto. El rosa indica un incidente adelante."},"zh":{"q":"你在公路上看到一个荧光粉红色的标志。粉红色通常是什么意思？","o":["前方有学校区","附近有公园","前方有交通事故，例如撞车","下一个出口有加油站和餐饮"],"h1":"粉红色用于突然发生、事先没有计划的事件。","h2":"荧光粉红色标志用于交通事故，例如撞车，所以你要减速，并预料前方路况会有变化。","p":"对。粉红色表示前方有交通事故。"},"vi":{"q":"Bạn thấy một biển báo màu hồng dạ quang trên xa lộ. Màu hồng thường có nghĩa là gì?","o":["Phía trước có khu vực trường học","Gần đây có công viên","Phía trước có sự cố giao thông, như tai nạn xe","Lối ra kế tiếp có xăng và đồ ăn"],"h1":"Màu hồng được dùng cho những sự việc bất ngờ, không có kế hoạch trước.","h2":"Biển báo màu hồng dạ quang được dùng cho sự cố giao thông, như tai nạn xe, nên bạn hãy chạy chậm lại và chuẩn bị cho những thay đổi phía trước.","p":"Đúng rồi. Màu hồng nghĩa là phía trước có sự cố."},"tl":{"q":"May nakita kang fluorescent na pink na karatula sa highway. Ano karaniwang ibig sabihin ng pink?","o":["May school zone sa unahan","May parke sa malapit","May insidente sa trapiko, gaya ng banggaan, sa unahan","May gasolina at pagkain sa susunod na exit"],"h1":"Ginagamit ang pink para sa biglaan at hindi planadong pangyayari.","h2":"Ginagamit ang fluorescent na pink na karatula para sa insidente sa trapiko, gaya ng banggaan, kaya bumagal ka at asahan ang mga pagbabago sa unahan.","p":"Tama. Ang pink ay nangangahulugang may insidente sa unahan."},"ar":{"q":"ترى لافتة باللون الوردي الفسفوري على الطريق السريع. ماذا يعني اللون الوردي عادةً؟","o":["توجد منطقة مدرسة في الأمام","توجد حديقة قريبة","يوجد حادث مروري، مثل تصادم، في الأمام","يوجد وقود وطعام عند المخرج التالي"],"h1":"يُستخدم اللون الوردي للأحداث المفاجئة غير المخطط لها.","h2":"تُستخدم اللافتات ذات اللون الوردي الفسفوري للحوادث المرورية، مثل التصادم، لذلك خفف السرعة وتوقّع تغييرات في الأمام.","p":"صحيح. اللون الوردي يعني وجود حادث في الأمام."},"ht":{"q":"Ou wè yon siy woz fliyoresan sou otowout la. Kisa koulè woz la vle di anjeneral?","o":["Gen yon zòn lekòl pi devan","Gen yon pak toupre","Gen yon ensidan sou wout la, tankou yon aksidan, pi devan","Gen gaz ak manje nan pwochen sòti a"],"h1":"Yo sèvi ak koulè woz pou bagay ki rive sanzatann, ki pa t planifye.","h2":"Yo sèvi ak siy woz fliyoresan pou ensidan sou wout la, tankou yon aksidan, kidonk ralanti epi atann ou a chanjman pi devan.","p":"Se sa. Woz vle di gen yon ensidan pi devan."}},{"id":"signs-111","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"Near a toll plaza, some signs and lanes are purple. Who may use those lanes?","o":["Only buses","Only drivers paying with cash","Only motorcycles","Only vehicles with an electronic toll account, such as a toll tag"],"h1":"Purple is used only for electronic tolls.","h2":"Purple signs and lanes are only for vehicles with a registered electronic toll account, such as a toll tag on the windshield.","p":"Right. Purple lanes are for electronic toll accounts."},"es":{"q":"Cerca de una caseta de peaje, algunas señales y carriles son morados. ¿Quién puede usar esos carriles?","o":["Solo autobuses","Solo quienes pagan en efectivo","Solo motocicletas","Solo vehículos con una cuenta de peaje electrónico, como una etiqueta de peaje"],"h1":"El morado se usa solo para peaje electrónico.","h2":"Las señales y carriles morados son solo para vehículos con una cuenta registrada de peaje electrónico, como una etiqueta en el parabrisas.","p":"Correcto. Los carriles morados son para peaje electrónico."},"zh":{"q":"在收费站附近，有些标志和车道是紫色的。谁可以使用这些车道？","o":["只有公交车","只有用现金付费的司机","只有摩托车","只有有电子收费账户的车辆，例如装有电子收费标签的车"],"h1":"紫色只用于电子收费。","h2":"紫色标志和车道只给已登记电子收费账户的车辆使用，例如在挡风玻璃上装有电子收费标签的车。","p":"对。紫色车道是给有电子收费账户的车用的。"},"vi":{"q":"Gần trạm thu phí, có một số biển báo và làn xe màu tím. Ai được dùng những làn đó?","o":["Chỉ xe buýt","Chỉ người lái trả bằng tiền mặt","Chỉ xe máy","Chỉ xe có tài khoản thu phí điện tử, như thẻ thu phí gắn trên xe"],"h1":"Màu tím chỉ dùng cho thu phí điện tử.","h2":"Biển báo và làn xe màu tím chỉ dành cho xe có tài khoản thu phí điện tử đã đăng ký, như thẻ thu phí gắn trên kính chắn gió.","p":"Đúng rồi. Làn màu tím dành cho xe có tài khoản thu phí điện tử."},"tl":{"q":"Malapit sa toll plaza, kulay ube ang ilang karatula at lane. Sino ang puwedeng gumamit ng mga lane na iyon?","o":["Mga bus lamang","Mga drayber na nagbabayad ng cash lamang","Mga motorsiklo lamang","Mga sasakyang may electronic toll account lamang, gaya ng toll tag"],"h1":"Ang kulay ube ay para lamang sa electronic toll.","h2":"Ang mga karatula at lane na kulay ube ay para lamang sa mga sasakyang may rehistradong electronic toll account, gaya ng toll tag sa windshield.","p":"Tama. Ang mga lane na kulay ube ay para sa may electronic toll account."},"ar":{"q":"بالقرب من محطة رسوم الطريق، بعض اللافتات والمسارات لونها بنفسجي. من يمكنه استخدام هذه المسارات؟","o":["الحافلات فقط","السائقون الذين يدفعون نقدًا فقط","الدراجات النارية فقط","المركبات التي لها حساب رسوم إلكتروني فقط، مثل شريحة رسوم الطريق"],"h1":"اللون البنفسجي يُستخدم فقط لرسوم الطريق الإلكترونية.","h2":"اللافتات والمسارات البنفسجية مخصصة فقط للمركبات التي لها حساب رسوم إلكتروني مسجَّل، مثل شريحة رسوم الطريق على الزجاج الأمامي.","p":"صحيح. المسارات البنفسجية لأصحاب حسابات الرسوم الإلكترونية."},"ht":{"q":"Toupre yon peyaj, gen kèk siy ak liy ki koulè vyolèt. Kiyès ki ka sèvi ak liy sa yo?","o":["Bis sèlman","Chofè ki peye kach sèlman","Motosiklèt sèlman","Machin ki gen yon kont peyaj elektwonik sèlman, tankou yon badj peyaj"],"h1":"Yo sèvi ak koulè vyolèt sèlman pou peyaj elektwonik.","h2":"Siy ak liy vyolèt yo se sèlman pou machin ki gen yon kont peyaj elektwonik ki anrejistre, tankou yon badj peyaj sou vit devan an.","p":"Se sa. Liy vyolèt yo se pou machin ki gen kont peyaj elektwonik."}},{"id":"signs-112","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"DO NOT STOP ON TRACKS"},"c":0,"en":{"q":"At a railroad crossing, a sign says DO NOT STOP ON TRACKS. Traffic ahead is slow. What should you do?","o":["Wait before the tracks until there is room for your whole car on the other side","Follow the car ahead onto the tracks","Stop on the tracks and wait","Drive around the cars ahead"],"h1":"Your car must never wait on the tracks.","h2":"DO NOT STOP ON TRACKS means you must never stop with any part of your vehicle on the tracks, so wait until there is room past them.","p":"Right. Never wait on the tracks."},"es":{"q":"En un cruce de tren, una señal dice DO NOT STOP ON TRACKS. El tráfico adelante va lento. ¿Qué debe hacer?","o":["Esperar antes de las vías hasta que haya espacio para todo su carro del otro lado","Seguir al carro de adelante hasta las vías","Pararse sobre las vías y esperar","Rodear a los carros de adelante"],"h1":"Su carro nunca debe esperar sobre las vías.","h2":"DO NOT STOP ON TRACKS significa que nunca debe pararse con ninguna parte de su vehículo sobre las vías, así que espere hasta que haya espacio después de ellas.","p":"Correcto. Nunca espere sobre las vías."},"zh":{"q":"在铁路道口，有个标志写着“DO NOT STOP ON TRACKS”（不要停在轨道上）。前面的车走得很慢。你应该怎么做？","o":["在轨道前等着，直到轨道另一边有足够空间停下你整辆车","跟着前面的车开上轨道","停在轨道上等","绕过前面的车"],"h1":"你的车绝不能停在轨道上等。","h2":"“DO NOT STOP ON TRACKS”表示你的车的任何部分都绝不能停在轨道上，所以要等到轨道另一边有空间再过。","p":"对。绝不要停在轨道上等。"},"vi":{"q":"Tại chỗ giao với đường sắt, có biển ghi “DO NOT STOP ON TRACKS” (Không dừng trên đường ray). Xe phía trước chạy chậm. Bạn nên làm gì?","o":["Chờ trước đường ray cho đến khi bên kia có đủ chỗ cho cả chiếc xe của bạn","Chạy theo xe phía trước lên đường ray","Dừng trên đường ray và chờ","Lái vòng qua các xe phía trước"],"h1":"Xe của bạn không bao giờ được chờ trên đường ray.","h2":"“DO NOT STOP ON TRACKS” nghĩa là bạn không bao giờ được dừng khi có bất kỳ phần nào của xe nằm trên đường ray, nên hãy chờ cho đến khi bên kia có chỗ.","p":"Đúng rồi. Không bao giờ chờ trên đường ray."},"tl":{"q":"Sa tawiran ng riles, may karatulang “DO NOT STOP ON TRACKS” (Huwag huminto sa riles). Mabagal ang trapiko sa unahan. Ano ang dapat mong gawin?","o":["Maghintay bago ang riles hanggang may lugar para sa buong kotse mo sa kabilang panig","Sundan ang kotse sa unahan papunta sa riles","Huminto sa riles at maghintay","Lumihis paikot sa mga kotse sa unahan"],"h1":"Hindi dapat maghintay ang kotse mo sa riles.","h2":"Ang “DO NOT STOP ON TRACKS” ay nangangahulugang hindi ka dapat huminto kahit kailan nang may anumang bahagi ng sasakyan mo sa riles, kaya maghintay ka hanggang may lugar na sa kabila nito.","p":"Tama. Huwag kailanman maghintay sa riles."},"ar":{"q":"عند تقاطع سكة حديد، توجد لافتة مكتوب عليها «DO NOT STOP ON TRACKS» (لا تتوقف على القضبان). حركة المرور في الأمام بطيئة. ماذا يجب أن تفعل؟","o":["انتظر قبل القضبان حتى يكون هناك مكان لسيارتك كلها في الجهة الأخرى","اتبع السيارة التي أمامك إلى القضبان","توقف على القضبان وانتظر","التفّ حول السيارات التي أمامك"],"h1":"يجب ألّا تنتظر سيارتك على القضبان أبدًا.","h2":"«DO NOT STOP ON TRACKS» تعني أنه يجب ألّا تتوقف أبدًا وأي جزء من مركبتك على القضبان، لذلك انتظر حتى يكون هناك مكان بعدها.","p":"صحيح. لا تنتظر على القضبان أبدًا."},"ht":{"q":"Nan yon kwazman tren, gen yon siy ki di “DO NOT STOP ON TRACKS” (pa kanpe sou ray yo). Machin devan yo ap avanse dousman. Kisa ou ta dwe fè?","o":["Tann anvan ray yo jiskaske gen plas pou tout machin ou lòt bò a","Swiv machin devan an sou ray yo","Kanpe sou ray yo epi tann","Kontoune machin ki devan yo"],"h1":"Machin ou pa dwe janm tann sou ray yo.","h2":"“DO NOT STOP ON TRACKS” vle di ou pa dwe janm kanpe ak okenn pati nan machin ou sou ray yo, kidonk tann jiskaske gen plas apre yo.","p":"Se sa. Pa janm tann sou ray yo."}},{"id":"signs-113","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"LOOK"},"c":1,"en":{"q":"At a railroad crossing, a sign below the crossbuck says LOOK. What does it remind you to do?","o":["Look for a place to park","Look both ways for trains before you cross","Look at the price of the toll","Look up for low wires"],"h1":"Trains can come from either side.","h2":"The LOOK sign at a railroad crossing reminds you to look both ways for trains before crossing the tracks.","p":"Right. Look both ways for trains."},"es":{"q":"En un cruce de tren, una señal debajo de la cruz dice LOOK. ¿Qué le recuerda hacer?","o":["Buscar dónde estacionarse","Mirar a ambos lados por si viene un tren antes de cruzar","Mirar el precio del peaje","Mirar hacia arriba por cables bajos"],"h1":"Los trenes pueden venir de cualquier lado.","h2":"La señal LOOK en un cruce de tren le recuerda mirar a ambos lados por si viene un tren antes de cruzar las vías.","p":"Correcto. Mire a ambos lados."},"zh":{"q":"在铁路道口，交叉形铁路标志下面有个标志写着“LOOK”（看）。它提醒你做什么？","o":["找地方停车","过道口前，向两边看有没有火车","看过路费的价格","抬头看有没有低垂的电线"],"h1":"火车可能从任何一边开来。","h2":"铁路道口的“LOOK”标志提醒你，在过轨道前要向两边看有没有火车。","p":"对。向两边看有没有火车。"},"vi":{"q":"Tại chỗ giao với đường sắt, bên dưới biển hình chữ X có biển ghi “LOOK” (Hãy nhìn). Biển này nhắc bạn làm gì?","o":["Tìm chỗ đậu xe","Nhìn cả hai bên xem có tàu hỏa không trước khi băng qua","Xem giá phí cầu đường","Nhìn lên xem có dây điện thấp không"],"h1":"Tàu hỏa có thể tới từ bên nào cũng được.","h2":"Biển “LOOK” tại chỗ giao với đường sắt nhắc bạn nhìn cả hai bên xem có tàu hỏa không trước khi băng qua đường ray.","p":"Đúng rồi. Nhìn cả hai bên xem có tàu hỏa không."},"tl":{"q":"Sa tawiran ng riles, may karatulang “LOOK” (Tumingin) sa ilalim ng crossbuck (karatulang hugis X). Ano ang ipinapaalala nito sa iyo?","o":["Maghanap ng paradahan","Tumingin sa magkabilang panig kung may tren bago tumawid","Tingnan ang presyo ng toll","Tumingala kung may mababang kawad"],"h1":"Puwedeng dumating ang tren mula sa alinmang panig.","h2":"Ang karatulang “LOOK” sa tawiran ng riles ay paalala na tumingin ka sa magkabilang panig kung may tren bago tumawid sa riles.","p":"Tama. Tumingin sa magkabilang panig kung may tren."},"ar":{"q":"عند تقاطع سكة حديد، توجد تحت علامة التقاطع (على شكل X) لافتة مكتوب عليها «LOOK» (انظر). بماذا تذكّرك؟","o":["أن تبحث عن مكان لركن السيارة","أن تنظر في الاتجاهين بحثًا عن قطارات قبل أن تعبر","أن تنظر إلى سعر رسوم الطريق","أن تنظر إلى الأعلى بحثًا عن أسلاك منخفضة"],"h1":"القطارات قد تأتي من أي جهة.","h2":"لافتة «LOOK» عند تقاطع السكة الحديد تذكّرك بأن تنظر في الاتجاهين بحثًا عن قطارات قبل عبور القضبان.","p":"صحيح. انظر في الاتجاهين بحثًا عن قطارات."},"ht":{"q":"Nan yon kwazman tren, anba siy an fòm X la, gen yon siy ki di “LOOK” (gade). Kisa li raple ou fè?","o":["Chèche yon kote pou pake","Gade toude bò pou tren anvan ou travèse","Gade pri peyaj la","Gade anlè pou fil ki ba"],"h1":"Tren ka vini nan nenpòt bò.","h2":"Siy “LOOK” nan yon kwazman tren raple ou pou gade toude bò pou tren anvan ou travèse ray yo.","p":"Se sa. Gade toude bò pou tren."}},{"id":"signs-114","scope":"US","cat":"signs","sign":{"shape":"crossbuck","text":"RAILROAD CROSSING"},"c":2,"en":{"q":"At a railroad crossing with no lights or gates, a STOP sign is mounted with the crossbuck. What must you do?","o":["Slow down and cross without stopping","Stop only if you hear a horn","Stop fully, then cross only when no train is coming","Stop only if you are driving a truck"],"h1":"The STOP sign applies even with no train in view.","h2":"A STOP sign at a railroad crossing means you must always come to a full stop, look both ways, and cross only when no train is coming.","p":"Right. Stop every time, then cross when clear."},"es":{"q":"En un cruce de tren sin luces ni barreras, hay una señal de PARE junto con la cruz. ¿Qué debe hacer?","o":["Bajar la velocidad y cruzar sin pararse","Pararse solo si oye una bocina","Pararse por completo y cruzar solo cuando no venga ningún tren","Pararse solo si maneja un camión"],"h1":"La señal de PARE se aplica aunque no vea un tren.","h2":"Una señal de PARE en un cruce de tren significa que siempre debe pararse por completo, mirar a ambos lados y cruzar solo cuando no venga ningún tren.","p":"Correcto. Párese siempre y cruce cuando esté libre."},"zh":{"q":"在一个没有信号灯也没有栏杆的铁路道口，交叉形铁路标志上装着一个“STOP”（停车）标志。你必须怎么做？","o":["减速，不停车直接过","只有听到鸣笛时才停","完全停车，然后只在没有火车开来时才过","只有开卡车时才停"],"h1":"即使看不到火车，“STOP”标志也同样适用。","h2":"铁路道口的“STOP”标志表示你每次都必须完全停车，向两边看，只有在没有火车开来时才能过。","p":"对。每次都要停车，确认安全后再过。"},"vi":{"q":"Tại chỗ giao với đường sắt không có đèn hay thanh chắn, có biển “STOP” (Dừng lại) gắn cùng biển hình chữ X. Bạn phải làm gì?","o":["Chạy chậm lại và băng qua mà không dừng","Chỉ dừng nếu nghe tiếng còi","Dừng hẳn, rồi chỉ băng qua khi không có tàu hỏa đang tới","Chỉ dừng nếu bạn lái xe tải"],"h1":"Biển “STOP” vẫn có hiệu lực dù không thấy tàu hỏa.","h2":"Biển “STOP” tại chỗ giao với đường sắt nghĩa là lần nào bạn cũng phải dừng hẳn, nhìn cả hai bên, và chỉ băng qua khi không có tàu hỏa đang tới.","p":"Đúng rồi. Lần nào cũng dừng, rồi băng qua khi đường trống."},"tl":{"q":"Sa tawiran ng riles na walang ilaw o harang, may “STOP” sign (Huminto) na nakakabit sa crossbuck. Ano ang dapat mong gawin?","o":["Bumagal at tumawid nang hindi humihinto","Huminto lang kung may marinig kang busina","Huminto nang buo, saka tumawid lang kapag walang paparating na tren","Huminto lang kung trak ang minamaneho mo"],"h1":"Sinusunod ang “STOP” sign kahit walang tren na nakikita.","h2":"Ang “STOP” sign sa tawiran ng riles ay nangangahulugang dapat kang huminto nang buo sa bawat pagkakataon, tumingin sa magkabilang panig, at tumawid lang kapag walang paparating na tren.","p":"Tama. Huminto palagi, saka tumawid kapag maluwag na."},"ar":{"q":"عند تقاطع سكة حديد بلا أضواء ولا حواجز، توجد لافتة «STOP» (قف) مثبتة مع علامة التقاطع. ماذا يجب أن تفعل؟","o":["خفف السرعة واعبر دون أن تتوقف","توقف فقط إذا سمعت صوت بوق","توقف تمامًا، ثم اعبر فقط عندما لا يكون هناك قطار قادم","توقف فقط إذا كنت تقود شاحنة"],"h1":"لافتة «STOP» تنطبق حتى إذا لم يكن هناك قطار ظاهر.","h2":"لافتة «STOP» عند تقاطع السكة الحديد تعني أنه يجب أن تتوقف تمامًا في كل مرة، وتنظر في الاتجاهين، ولا تعبر إلا عندما لا يكون هناك قطار قادم.","p":"صحيح. توقف في كل مرة، ثم اعبر عندما يكون الطريق خاليًا."},"ht":{"q":"Nan yon kwazman tren ki pa gen limyè ni baryè, gen yon siy “STOP” (kanpe) ki monte ak siy an fòm X la. Kisa ou dwe fè?","o":["Ralanti epi travèse san ou pa kanpe","Kanpe sèlman si ou tande yon klaksòn","Kanpe nèt, epi travèse sèlman lè pa gen tren k ap vini","Kanpe sèlman si se yon kamyon w ap kondui"],"h1":"Siy “STOP” la aplike menm lè ou pa wè okenn tren.","h2":"Yon siy “STOP” nan yon kwazman tren vle di ou dwe toujou kanpe nèt, gade toude bò, epi travèse sèlman lè pa gen tren k ap vini.","p":"Se sa. Kanpe chak fwa, epi travèse lè wout la lib."}},{"id":"signs-115","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"TRACKS OUT OF SERVICE"},"c":3,"en":{"q":"A sign at a railroad crossing says TRACKS OUT OF SERVICE. What does it mean?","o":["A train is stopped on the tracks","The road is closed at the tracks","You must stop and wait for a train","Trains no longer use these tracks"],"h1":"Out of service means not being used.","h2":"TRACKS OUT OF SERVICE means trains no longer use that crossing, though you should still cross with normal care.","p":"Right. Trains no longer use these tracks."},"es":{"q":"Una señal en un cruce de tren dice TRACKS OUT OF SERVICE. ¿Qué significa?","o":["Que hay un tren parado en las vías","Que la vía está cerrada en el cruce","Que debe pararse a esperar un tren","Que los trenes ya no usan estas vías"],"h1":"Out of service quiere decir fuera de servicio.","h2":"TRACKS OUT OF SERVICE significa que los trenes ya no usan ese cruce, aunque debe cruzar con el cuidado normal.","p":"Correcto. Los trenes ya no usan estas vías."},"zh":{"q":"铁路道口有个标志写着“TRACKS OUT OF SERVICE”（轨道停用）。这是什么意思？","o":["有火车停在轨道上","道路在轨道处封闭","你必须停车等火车","火车不再使用这段轨道"],"h1":"停用表示不再使用。","h2":"“TRACKS OUT OF SERVICE”表示火车不再使用这个道口，但你过道口时仍然要像平常一样小心。","p":"对。火车不再使用这段轨道。"},"vi":{"q":"Một biển báo tại chỗ giao với đường sắt ghi “TRACKS OUT OF SERVICE” (Đường ray ngưng sử dụng). Biển này có nghĩa là gì?","o":["Có tàu hỏa đang dừng trên đường ray","Con đường bị đóng tại chỗ đường ray","Bạn phải dừng và chờ tàu hỏa","Tàu hỏa không còn chạy trên đường ray này nữa"],"h1":"Ngưng sử dụng nghĩa là không còn được dùng.","h2":"“TRACKS OUT OF SERVICE” nghĩa là tàu hỏa không còn chạy qua chỗ giao này nữa, nhưng bạn vẫn nên băng qua cẩn thận như bình thường.","p":"Đúng rồi. Tàu hỏa không còn chạy trên đường ray này nữa."},"tl":{"q":"May karatula sa tawiran ng riles na “TRACKS OUT OF SERVICE” (Hindi na ginagamit ang riles). Ano ang ibig sabihin nito?","o":["May tren na nakahinto sa riles","Sarado ang kalsada sa riles","Dapat kang huminto at maghintay ng tren","Hindi na dumadaan ang tren sa riles na ito"],"h1":"Ang out of service ay nangangahulugang hindi na ginagamit.","h2":"Ang “TRACKS OUT OF SERVICE” ay nangangahulugang hindi na dumadaan ang tren sa tawirang iyon, pero dapat ka pa ring tumawid nang may karaniwang pag-iingat.","p":"Tama. Hindi na dumadaan ang tren sa riles na ito."},"ar":{"q":"لافتة عند تقاطع سكة حديد مكتوب عليها «TRACKS OUT OF SERVICE» (القضبان خارج الخدمة). ماذا تعني؟","o":["يوجد قطار متوقف على القضبان","الطريق مغلق عند القضبان","يجب أن تتوقف وتنتظر القطار","القطارات لم تعد تستخدم هذه القضبان"],"h1":"خارج الخدمة يعني أنها لم تعد مستخدمة.","h2":"«TRACKS OUT OF SERVICE» تعني أن القطارات لم تعد تستخدم هذا التقاطع، ومع ذلك عليك أن تعبر بالحذر المعتاد.","p":"صحيح. القطارات لم تعد تستخدم هذه القضبان."},"ht":{"q":"Yon siy nan yon kwazman tren di “TRACKS OUT OF SERVICE” (ray yo pa an sèvis). Kisa sa vle di?","o":["Gen yon tren ki kanpe sou ray yo","Wout la fèmen kote ray yo ye a","Ou dwe kanpe epi tann yon tren","Tren pa sèvi ak ray sa yo ankò"],"h1":"Pa an sèvis vle di yo pa sèvi ak li.","h2":"“TRACKS OUT OF SERVICE” vle di tren pa pase nan kwazman sa a ankò, men ou ta dwe toujou travèse ak prekosyon nòmal.","p":"Se sa. Tren pa sèvi ak ray sa yo ankò."}},{"id":"signs-116","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"LOW GROUND CLEARANCE"},"c":0,"en":{"q":"Before a railroad crossing, a yellow sign shows a vehicle stuck on raised tracks. What does it warn about?","o":["A vehicle that sits low to the ground could get stuck on the crossing","The tracks are under water","A train is stuck ahead","The crossing has no lights"],"h1":"The road rises sharply at the tracks.","h2":"The low ground clearance sign warns that the crossing is raised, so a vehicle that sits low, like a long trailer, could get stuck on the tracks.","p":"Right. Low vehicles could get stuck."},"es":{"q":"Antes de un cruce de tren, una señal amarilla muestra un vehículo atascado sobre vías elevadas. ¿De qué advierte?","o":["De que un vehículo muy bajo podría atascarse en el cruce","De que las vías están bajo el agua","De que hay un tren atascado adelante","De que el cruce no tiene luces"],"h1":"La vía sube de golpe en las vías del tren.","h2":"La señal de poca altura libre advierte que el cruce está elevado, así que un vehículo muy bajo, como un remolque largo, podría atascarse sobre las vías.","p":"Correcto. Los vehículos bajos podrían atascarse."},"zh":{"q":"在铁路道口前，有个黄色标志画着一辆车卡在凸起的轨道上。它在警告什么？","o":["车身离地很低的车可能会卡在道口上","轨道被水淹了","前方有火车卡住了","道口没有信号灯"],"h1":"道路在轨道处突然升高。","h2":"底盘离地低的警告标志表示道口是凸起的，所以车身低的车，例如长拖车，可能会卡在轨道上。","p":"对。车身低的车可能会卡住。"},"vi":{"q":"Trước chỗ giao với đường sắt, có biển màu vàng vẽ một chiếc xe bị kẹt trên đường ray nhô cao. Biển này cảnh báo điều gì?","o":["Xe có gầm thấp sát mặt đất có thể bị kẹt tại chỗ giao","Đường ray bị ngập nước","Có một đoàn tàu bị kẹt phía trước","Chỗ giao này không có đèn"],"h1":"Mặt đường nhô cao đột ngột tại chỗ đường ray.","h2":"Biển báo gầm xe thấp cảnh báo rằng chỗ giao với đường sắt nhô cao, nên xe có gầm thấp, như rơ-moóc dài, có thể bị kẹt trên đường ray.","p":"Đúng rồi. Xe gầm thấp có thể bị kẹt."},"tl":{"q":"Bago ang tawiran ng riles, may dilaw na karatula na may larawan ng sasakyang naipit sa nakaumbok na riles. Tungkol saan ang babala nito?","o":["Puwedeng maipit sa tawiran ang sasakyang mababa ang ilalim","Lubog sa tubig ang riles","May tren na naipit sa unahan","Walang ilaw ang tawiran"],"h1":"Biglang tumataas ang kalsada sa riles.","h2":"Ang karatula para sa mababang sasakyan ay babala na nakaumbok ang tawiran, kaya ang sasakyang mababa ang ilalim, gaya ng mahabang trailer, ay puwedeng maipit sa riles.","p":"Tama. Puwedeng maipit ang mababang sasakyan."},"ar":{"q":"قبل تقاطع سكة حديد، توجد لافتة صفراء تُظهر مركبة عالقة على قضبان مرتفعة. ممَّ تحذّر؟","o":["المركبة المنخفضة القريبة من الأرض قد تعلق على التقاطع","القضبان مغمورة بالماء","يوجد قطار عالق في الأمام","التقاطع ليس فيه أضواء"],"h1":"الطريق يرتفع بشدة عند القضبان.","h2":"لافتة الخلوص الأرضي المنخفض تحذّر من أن التقاطع مرتفع، لذلك قد تعلق على القضبان مركبة منخفضة، مثل مقطورة طويلة.","p":"صحيح. المركبات المنخفضة قد تعلق."},"ht":{"q":"Anvan yon kwazman tren, gen yon siy jòn ki montre yon machin ki kole sou ray ki leve wo. Kisa li avèti?","o":["Yon machin ki ba anpil atè ka rete kole sou kwazman an","Ray yo anba dlo","Gen yon tren ki kole pi devan","Kwazman an pa gen limyè"],"h1":"Wout la monte sèk kote ray yo ye a.","h2":"Siy machin ki ba a avèti ke kwazman an leve wo, kidonk yon machin ki ba, tankou yon long trelè, ka rete kole sou ray yo.","p":"Se sa. Machin ki ba yo ka rete kole."}},{"id":"signs-117","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"NO TRAIN HORN"},"c":1,"en":{"q":"A sign at a railroad crossing says NO TRAIN HORN. What does that mean for you?","o":["Trains do not use this crossing","Trains will not sound a horn here, so look carefully","You may not honk your horn here","The crossing lights do not work"],"h1":"You cannot count on hearing a train here.","h2":"NO TRAIN HORN means trains usually do not blow their horns at this crossing, so you must look carefully both ways yourself.","p":"Right. No horn, so look carefully."},"es":{"q":"Una señal en un cruce de tren dice NO TRAIN HORN. ¿Qué significa para usted?","o":["Que los trenes no usan este cruce","Que los trenes no tocan la bocina aquí, así que mire con cuidado","Que usted no puede tocar la bocina aquí","Que las luces del cruce no funcionan"],"h1":"Aquí no puede contar con oír al tren.","h2":"NO TRAIN HORN significa que los trenes normalmente no tocan la bocina en este cruce, así que usted mismo debe mirar con cuidado a ambos lados.","p":"Correcto. Sin bocina, mire con cuidado."},"zh":{"q":"铁路道口有个标志写着“NO TRAIN HORN”（火车不鸣笛）。这对你来说是什么意思？","o":["火车不经过这个道口","火车在这里不会鸣笛，所以要仔细看","你在这里不可以按喇叭","道口的信号灯坏了"],"h1":"在这里你不能指望听到火车的声音。","h2":"“NO TRAIN HORN”表示火车通常不会在这个道口鸣笛，所以你必须自己仔细向两边看。","p":"对。火车不鸣笛，所以要仔细看。"},"vi":{"q":"Một biển báo tại chỗ giao với đường sắt ghi “NO TRAIN HORN” (Tàu không kéo còi). Điều đó có nghĩa gì với bạn?","o":["Tàu hỏa không chạy qua chỗ giao này","Tàu hỏa sẽ không kéo còi ở đây, nên hãy nhìn thật kỹ","Bạn không được bóp còi ở đây","Đèn ở chỗ giao không hoạt động"],"h1":"Bạn không thể trông cậy vào việc nghe tiếng tàu ở đây.","h2":"“NO TRAIN HORN” nghĩa là tàu hỏa thường không kéo còi tại chỗ giao này, nên bạn phải tự mình nhìn thật kỹ cả hai bên.","p":"Đúng rồi. Không có còi, nên hãy nhìn thật kỹ."},"tl":{"q":"May karatula sa tawiran ng riles na “NO TRAIN HORN” (Walang busina ng tren). Ano ang ibig sabihin nito para sa iyo?","o":["Hindi dumadaan ang tren sa tawirang ito","Hindi bubusina ang tren dito, kaya tumingin nang mabuti","Bawal kang bumusina dito","Sira ang mga ilaw sa tawiran"],"h1":"Hindi ka makakaasa na maririnig mo ang tren dito.","h2":"Ang “NO TRAIN HORN” ay nangangahulugang karaniwang hindi bumubusina ang tren sa tawirang ito, kaya ikaw mismo ang dapat tumingin nang mabuti sa magkabilang panig.","p":"Tama. Walang busina, kaya tumingin nang mabuti."},"ar":{"q":"لافتة عند تقاطع سكة حديد مكتوب عليها «NO TRAIN HORN» (لا بوق للقطار). ماذا يعني ذلك بالنسبة لك؟","o":["القطارات لا تستخدم هذا التقاطع","القطارات لن تطلق البوق هنا، لذلك انظر بعناية","يجب ألّا تستخدم بوق سيارتك هنا","أضواء التقاطع لا تعمل"],"h1":"لا يمكنك الاعتماد على سماع القطار هنا.","h2":"«NO TRAIN HORN» تعني أن القطارات عادةً لا تطلق البوق عند هذا التقاطع، لذلك يجب أن تنظر بنفسك بعناية في الاتجاهين.","p":"صحيح. لا يوجد بوق، لذلك انظر بعناية."},"ht":{"q":"Yon siy nan yon kwazman tren di “NO TRAIN HORN” (tren pa klaksonnen). Kisa sa vle di pou ou?","o":["Tren pa pase nan kwazman sa a","Tren yo p ap klaksonnen isit la, kidonk gade byen","Ou pa gen dwa klaksonnen isit la","Limyè kwazman an pa mache"],"h1":"Ou pa ka konte sou tande yon tren isit la.","h2":"“NO TRAIN HORN” vle di tren yo anjeneral pa klaksonnen nan kwazman sa a, kidonk ou dwe gade byen toude bò ou menm.","p":"Se sa. Pa gen klaksòn, kidonk gade byen."}},{"id":"signs-118","scope":"US","cat":"signs","sign":{"shape":"rect-yellow","text":"STORAGE SPACE 50 FT"},"c":2,"en":{"q":"Just past a railroad crossing there is a stop sign at a highway. A sign says the storage space between them is short. Why does that matter?","o":["You may park between the tracks and the highway","Trains stop there to load","Do not cross the tracks unless there is room for your whole car before the highway","You may stop on the tracks while you wait"],"h1":"Your car must fit fully past the tracks.","h2":"A storage space sign warns that there is little room between the tracks and the next road, so cross only if your whole vehicle will fit there.","p":"Right. Make sure you fit before crossing."},"es":{"q":"Justo después de un cruce de tren hay una señal de PARE en una carretera. Una señal indica que el espacio entre ambos es corto. ¿Por qué importa?","o":["Puede estacionarse entre las vías y la carretera","Los trenes se paran allí a cargar","No cruce las vías a menos que todo su carro quepa antes de la carretera","Puede pararse sobre las vías mientras espera"],"h1":"Su carro debe caber completo después de las vías.","h2":"Una señal de espacio de espera advierte que hay poco lugar entre las vías y la siguiente vía, así que cruce solo si todo su vehículo cabe allí.","p":"Correcto. Asegúrese de caber antes de cruzar."},"zh":{"q":"刚过铁路道口，就有一个通往公路的停车标志。有个标志说它们之间的停车空间很短。为什么这很重要？","o":["你可以把车停在轨道和公路之间","火车在那里停下来装货","除非公路前有足够空间停下你整辆车，否则不要过轨道","等待时你可以停在轨道上"],"h1":"你的车必须完全停在轨道以外。","h2":"停车空间标志警告你轨道和下一条路之间的空间很小，所以只有在你整辆车都能停得下时才过轨道。","p":"对。过道口前，要确定你的车停得下。"},"vi":{"q":"Ngay sau chỗ giao với đường sắt có biển “STOP” (Dừng lại) trước một xa lộ. Có biển báo cho biết khoảng trống giữa hai nơi này rất ngắn. Tại sao điều đó quan trọng?","o":["Bạn có thể đậu xe giữa đường ray và xa lộ","Tàu hỏa dừng ở đó để chất hàng","Đừng băng qua đường ray trừ khi có đủ chỗ cho cả chiếc xe của bạn trước xa lộ","Bạn có thể dừng trên đường ray trong lúc chờ"],"h1":"Cả chiếc xe của bạn phải nằm trọn bên kia đường ray.","h2":"Biển báo khoảng chờ cảnh báo rằng giữa đường ray và con đường kế tiếp có rất ít chỗ, nên chỉ băng qua nếu cả chiếc xe của bạn vừa chỗ đó.","p":"Đúng rồi. Hãy chắc là xe bạn vừa chỗ trước khi băng qua."},"tl":{"q":"Paglampas lang ng tawiran ng riles, may “STOP” sign (Huminto) bago ang highway. May karatula na nagsasabing maikli ang espasyo sa pagitan ng mga ito. Bakit ito mahalaga?","o":["Puwede kang pumarada sa pagitan ng riles at highway","Doon humihinto ang tren para magkarga","Huwag tumawid sa riles maliban kung may lugar para sa buong kotse mo bago ang highway","Puwede kang huminto sa riles habang naghihintay"],"h1":"Dapat buong makalampas sa riles ang kotse mo.","h2":"Ang karatula tungkol sa espasyo ay babala na kaunti lang ang lugar sa pagitan ng riles at ng susunod na kalsada, kaya tumawid ka lang kung kakasya roon ang buong sasakyan mo.","p":"Tama. Siguraduhing kakasya ka bago tumawid."},"ar":{"q":"بعد تقاطع سكة حديد مباشرةً توجد لافتة «STOP» (قف) عند طريق سريع. ولافتة تقول إن المسافة المتاحة بينهما قصيرة. لماذا هذا مهم؟","o":["يمكنك أن تركن سيارتك بين القضبان والطريق السريع","القطارات تتوقف هناك للتحميل","لا تعبر القضبان إلا إذا كان هناك مكان لسيارتك كلها قبل الطريق السريع","يمكنك أن تتوقف على القضبان أثناء الانتظار"],"h1":"يجب أن تتسع سيارتك كلها بعد القضبان.","h2":"لافتة مساحة الانتظار تحذّر من أن المكان قليل بين القضبان والطريق التالي، لذلك لا تعبر إلا إذا كانت مركبتك كلها ستتسع هناك.","p":"صحيح. تأكد أن سيارتك تتسع قبل أن تعبر."},"ht":{"q":"Touswit apre yon kwazman tren, gen yon siy “STOP” (kanpe) devan yon otowout. Yon siy di espas ki genyen ant yo de a kout. Poukisa sa enpòtan?","o":["Ou ka pake ant ray yo ak otowout la","Tren yo kanpe la pou chaje","Pa travèse ray yo sòf si gen plas pou tout machin ou anvan otowout la","Ou ka kanpe sou ray yo pandan w ap tann"],"h1":"Tout machin ou dwe kenbe nèt apre ray yo.","h2":"Yon siy espas pou tann avèti ke gen ti kras plas ant ray yo ak pwochen wout la, kidonk travèse sèlman si tout machin ou ap kenbe la.","p":"Se sa. Asire ou ke ou kenbe anvan ou travèse."}},{"id":"signs-119","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SKEWED CROSSING"},"c":3,"en":{"q":"A yellow sign shows railroad tracks crossing the road at a slant. What does it warn about?","o":["The road curves after the tracks","There are two railroad crossings","The tracks are being repaired","The tracks cross the road at a sharp angle, so look well to each side"],"h1":"A train may come from a direction that is hard to see.","h2":"The skewed crossing sign warns that the tracks cross at an angle, so you may need to turn your head farther to look for trains.","p":"Right. The tracks cross at an angle."},"es":{"q":"Una señal amarilla muestra vías de tren que cruzan la vía en diagonal. ¿De qué advierte?","o":["De que la vía se curva después del cruce","De que hay dos cruces de tren","De que están reparando las vías","De que las vías cruzan en un ángulo marcado, así que mire bien a cada lado"],"h1":"Un tren puede venir de una dirección difícil de ver.","h2":"La señal de cruce en diagonal advierte que las vías cruzan en ángulo, así que quizás deba girar más la cabeza para ver si viene un tren.","p":"Correcto. Las vías cruzan en ángulo."},"zh":{"q":"一个黄色标志画着铁路轨道斜着穿过道路。它在警告什么？","o":["过了轨道道路会转弯","有两个铁路道口","轨道正在维修","轨道以很斜的角度穿过道路，所以要好好看清两边"],"h1":"火车可能从一个很难看到的方向开来。","h2":"斜交道口标志警告你轨道是斜着穿过道路的，所以你可能需要把头转得更多一些来看有没有火车。","p":"对。轨道是斜着穿过道路的。"},"vi":{"q":"Một biển màu vàng vẽ đường ray băng ngang qua đường theo hướng xéo. Biển này cảnh báo điều gì?","o":["Con đường có khúc cua sau đường ray","Có hai chỗ giao với đường sắt","Đường ray đang được sửa chữa","Đường ray cắt ngang đường theo một góc xéo nhiều, nên hãy nhìn kỹ mỗi bên"],"h1":"Tàu hỏa có thể tới từ một hướng khó nhìn thấy.","h2":"Biển báo chỗ giao xéo cảnh báo rằng đường ray cắt ngang theo một góc, nên bạn có thể cần quay đầu nhiều hơn để nhìn xem có tàu hỏa không.","p":"Đúng rồi. Đường ray cắt ngang theo một góc."},"tl":{"q":"May dilaw na karatula na may larawan ng riles na pahilis na tumatawid sa kalsada. Tungkol saan ang babala nito?","o":["Kumukurba ang kalsada pagkatapos ng riles","May dalawang tawiran ng riles","Inaayos ang riles","Matarik na pahilis ang tawid ng riles sa kalsada, kaya tumingin nang mabuti sa bawat panig"],"h1":"Puwedeng dumating ang tren mula sa direksyong mahirap makita.","h2":"Ang karatula para sa pahilis na tawiran ay babala na pahilis ang tawid ng riles, kaya baka kailangan mong ipihit pa nang mas malayo ang ulo mo para makita kung may tren.","p":"Tama. Pahilis ang tawid ng riles."},"ar":{"q":"لافتة صفراء تُظهر قضبان سكة حديد تعبر الطريق بشكل مائل. ممَّ تحذّر؟","o":["الطريق ينعطف بعد القضبان","يوجد تقاطعان لسكة الحديد","القضبان قيد الإصلاح","القضبان تعبر الطريق بزاوية حادة، لذلك انظر جيدًا إلى كل جهة"],"h1":"قد يأتي القطار من اتجاه يصعب رؤيته.","h2":"لافتة التقاطع المائل تحذّر من أن القضبان تعبر بزاوية، لذلك قد تحتاج إلى أن تدير رأسك أكثر لترى إن كان هناك قطار.","p":"صحيح. القضبان تعبر بزاوية."},"ht":{"q":"Yon siy jòn montre ray tren k ap travèse wout la an biye. Kisa li avèti?","o":["Wout la vire apre ray yo","Gen de kwazman tren","Y ap repare ray yo","Ray yo travèse wout la an biye anpil, kidonk gade byen chak bò"],"h1":"Yon tren ka vini nan yon direksyon ki difisil pou wè.","h2":"Siy kwazman an biye a avèti ke ray yo travèse an biye, kidonk ou ka bezwen vire tèt ou pi lwen pou gade si gen tren.","p":"Se sa. Ray yo travèse an biye."}},{"id":"signs-120","scope":"US","cat":"signs","sign":{"shape":"diamond-ygreen","text":"SCHOOL BUS STOP AHEAD"},"c":0,"en":{"q":"A yellow-green diamond sign shows a school bus with an arrow above it. It warns of a school bus stop ahead. What should you do?","o":["Slow down and be ready for a stopped school bus and children","Speed up to pass any bus ahead","Honk to warn the children","Pull over and wait for the bus"],"h1":"A bus may be stopped where you cannot see it yet.","h2":"The School Bus Stop Ahead sign warns that a school bus may be stopped ahead to load children, so slow down and be ready to stop.","p":"Right. Be ready for a stopped bus."},"es":{"q":"Una señal en forma de rombo, amarillo verdosa, muestra un autobús escolar con una flecha encima. Advierte que hay una parada de autobús escolar adelante. ¿Qué debe hacer?","o":["Bajar la velocidad y estar listo para un autobús escolar parado y niños","Acelerar para pasar cualquier autobús","Tocar la bocina para avisar a los niños","Orillarse y esperar el autobús"],"h1":"Puede haber un autobús parado donde aún no lo ve.","h2":"La señal de parada de autobús escolar adelante advierte que puede haber un autobús escolar parado adelante recogiendo niños, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Esté listo para un autobús parado."},"zh":{"q":"一个黄绿色菱形标志画着一辆校车，上面有一个箭头。它警告前方有校车停靠站。你应该怎么做？","o":["减速，准备好应对停着的校车和孩子","加速超过前面的任何公交车","按喇叭提醒孩子","靠边停车等校车"],"h1":"校车可能停在你还看不到的地方。","h2":"前方校车停靠站标志警告你，前面可能有校车停下来让孩子上车，所以要减速，准备好停车。","p":"对。准备好应对停着的校车。"},"vi":{"q":"Một biển hình thoi màu vàng xanh lá vẽ xe buýt trường học với mũi tên phía trên. Biển này cảnh báo phía trước có trạm dừng xe buýt trường học. Bạn nên làm gì?","o":["Chạy chậm lại và sẵn sàng cho xe buýt trường học đang dừng và trẻ em","Tăng tốc để vượt bất kỳ xe buýt nào phía trước","Bóp còi để báo cho trẻ em","Tấp vào lề và chờ xe buýt"],"h1":"Xe buýt có thể đang dừng ở chỗ bạn chưa thấy được.","h2":"Biển báo trạm dừng xe buýt trường học phía trước cảnh báo rằng có thể có xe buýt trường học đang dừng phía trước để đón trẻ em, nên hãy chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Hãy sẵn sàng cho xe buýt đang dừng."},"tl":{"q":"May dilaw-berdeng karatulang hugis diyamante na may larawan ng school bus at palaso sa itaas nito. Babala ito na may hintuan ng school bus sa unahan. Ano ang dapat mong gawin?","o":["Bumagal at maging handa sa nakahintong school bus at mga bata","Bumilis para lampasan ang anumang bus sa unahan","Bumusina para balaan ang mga bata","Tumabi at hintayin ang bus"],"h1":"Puwedeng may nakahintong bus sa lugar na hindi mo pa nakikita.","h2":"Ang karatulang School Bus Stop Ahead ay babala na puwedeng may school bus na nakahinto sa unahan para magsakay ng mga bata, kaya bumagal ka at maging handang huminto.","p":"Tama. Maging handa sa nakahintong bus."},"ar":{"q":"لافتة على شكل معيّن بلون أصفر مخضرّ تُظهر حافلة مدرسية فوقها سهم. تحذّر من موقف حافلة مدرسية في الأمام. ماذا يجب أن تفعل؟","o":["خفف السرعة وكن مستعدًا لحافلة مدرسية متوقفة ولأطفال","زد السرعة لتتجاوز أي حافلة في الأمام","استخدم البوق لتنبيه الأطفال","انتقل إلى جانب الطريق وانتظر الحافلة"],"h1":"قد تكون الحافلة متوقفة في مكان لا تستطيع رؤيته بعد.","h2":"لافتة موقف الحافلة المدرسية في الأمام تحذّر من أن حافلة مدرسية قد تكون متوقفة في الأمام لركوب الأطفال، لذلك خفف السرعة وكن مستعدًا للتوقف.","p":"صحيح. كن مستعدًا لحافلة متوقفة."},"ht":{"q":"Yon siy an fòm dyaman, koulè jòn vèt, montre yon bis lekòl ak yon flèch anlè li. Li avèti gen yon arè bis lekòl pi devan. Kisa ou ta dwe fè?","o":["Ralanti epi pare pou yon bis lekòl ki kanpe ak timoun","Akselere pou depase nenpòt bis ki devan","Klaksonnen pou avèti timoun yo","Rale sou kote epi tann bis la"],"h1":"Yon bis ka kanpe yon kote ou poko ka wè.","h2":"Siy arè bis lekòl pi devan an avèti ke yon bis lekòl ka kanpe pi devan pou fè timoun monte, kidonk ralanti epi pare pou kanpe.","p":"Se sa. Pare pou yon bis ki kanpe."}},{"id":"signs-121","scope":"US","cat":"signs","sign":{"shape":"rect-white","text":"END SCHOOL ZONE"},"c":1,"en":{"q":"You drove through a school zone. A sign now says END SCHOOL ZONE. What does it mean?","o":["Another school zone starts","The lower school speed limit no longer applies","You must stop for children","The road is closed to buses"],"h1":"End means finished.","h2":"END SCHOOL ZONE means the school zone and its lower speed limit end here, and the regular posted limit applies again.","p":"Right. The school zone is over."},"es":{"q":"Usted pasó por una zona escolar. Ahora una señal dice END SCHOOL ZONE. ¿Qué significa?","o":["Que empieza otra zona escolar","Que el límite escolar más bajo ya no se aplica","Que debe pararse por niños","Que la vía está cerrada a autobuses"],"h1":"End quiere decir fin.","h2":"END SCHOOL ZONE significa que la zona escolar y su límite más bajo terminan aquí, y vuelve a regir el límite normal indicado.","p":"Correcto. Terminó la zona escolar."},"zh":{"q":"你刚开过一个学校区。现在有个标志写着“END SCHOOL ZONE”（学校区结束）。这是什么意思？","o":["另一个学校区开始了","较低的学校区限速不再适用","你必须为孩子停车","道路禁止公交车通行"],"h1":"结束就是完了。","h2":"“END SCHOOL ZONE”表示学校区和它较低的限速到这里结束，标志上的一般限速重新适用。","p":"对。学校区结束了。"},"vi":{"q":"Bạn vừa lái qua khu vực trường học. Bây giờ có biển ghi “END SCHOOL ZONE” (Hết khu vực trường học). Biển này có nghĩa là gì?","o":["Một khu vực trường học khác bắt đầu","Giới hạn tốc độ thấp hơn của khu trường học không còn áp dụng","Bạn phải dừng cho trẻ em","Con đường cấm xe buýt"],"h1":"Hết nghĩa là đã kết thúc.","h2":"“END SCHOOL ZONE” nghĩa là khu vực trường học và giới hạn tốc độ thấp hơn của nó kết thúc ở đây, và giới hạn tốc độ thường ghi trên biển được áp dụng trở lại.","p":"Đúng rồi. Khu vực trường học đã hết."},"tl":{"q":"Dumaan ka sa isang school zone. May karatula ngayon na “END SCHOOL ZONE” (Tapos na ang school zone). Ano ang ibig sabihin nito?","o":["May panibagong school zone na nagsisimula","Hindi na umiiral ang mas mababang speed limit ng school zone","Dapat kang huminto para sa mga bata","Bawal ang bus sa kalsada"],"h1":"Ang end ay nangangahulugang tapos na.","h2":"Ang “END SCHOOL ZONE” ay nangangahulugang dito natatapos ang school zone at ang mas mababang speed limit nito, at muling umiiral ang karaniwang speed limit na nakapaskil.","p":"Tama. Tapos na ang school zone."},"ar":{"q":"قُدت عبر منطقة مدرسة. والآن توجد لافتة مكتوب عليها «END SCHOOL ZONE» (نهاية منطقة المدرسة). ماذا تعني؟","o":["تبدأ منطقة مدرسة أخرى","حد السرعة المنخفض الخاص بالمدرسة لم يعد ساريًا","يجب أن تتوقف من أجل الأطفال","الطريق مغلق أمام الحافلات"],"h1":"النهاية تعني أن الشيء انتهى.","h2":"«END SCHOOL ZONE» تعني أن منطقة المدرسة وحد السرعة المنخفض فيها ينتهيان هنا، ويعود حد السرعة العادي المكتوب على اللافتات.","p":"صحيح. انتهت منطقة المدرسة."},"ht":{"q":"Ou sot kondui nan yon zòn lekòl. Kounye a gen yon siy ki di “END SCHOOL ZONE” (fen zòn lekòl). Kisa sa vle di?","o":["Yon lòt zòn lekòl ap kòmanse","Limit vitès ki pi ba pou zòn lekòl la pa aplike ankò","Ou dwe kanpe pou timoun","Wout la fèmen pou bis"],"h1":"Fen vle di sa fini.","h2":"“END SCHOOL ZONE” vle di zòn lekòl la ak limit vitès ki pi ba li a fini isit la, epi limit vitès nòmal ki afiche a aplike ankò.","p":"Se sa. Zòn lekòl la fini."}},{"id":"signs-122","scope":"US","cat":"signs","sign":{"shape":"stop","text":"STOP"},"c":2,"en":{"q":"A school crossing guard steps into the street holding a STOP paddle. What must you do?","o":["Slow down and drive around them","Stop only if the light is red","Stop and wait until the guard and children are out of the street","Honk so they cross faster"],"h1":"The crossing guard controls traffic at the crossing.","h2":"When a crossing guard holds up a STOP paddle, you must stop and stay stopped until the guard and the children have left the street.","p":"Right. Stop and wait for the guard."},"es":{"q":"Un guardia de cruce escolar entra a la calle con una paleta de PARE. ¿Qué debe hacer?","o":["Bajar la velocidad y rodearlos","Pararse solo si el semáforo está en rojo","Pararse y esperar hasta que el guardia y los niños salgan de la calle","Tocar la bocina para que crucen rápido"],"h1":"El guardia de cruce controla el tráfico en el cruce.","h2":"Cuando un guardia de cruce levanta una paleta de PARE, usted debe pararse y seguir parado hasta que el guardia y los niños salgan de la calle.","p":"Correcto. Párese y espere al guardia."},"zh":{"q":"学校路口的交通协管员拿着“STOP”（停车）牌走到街上。你必须怎么做？","o":["减速，从他们旁边绕过去","只有红灯时才停车","停车，等协管员和孩子们都离开街道","按喇叭，让他们快点过"],"h1":"交通协管员在路口指挥交通。","h2":"当交通协管员举起“STOP”（停车）牌时，你必须停车，并一直停着，直到协管员和孩子们都离开街道。","p":"对。停车，等候协管员。"},"vi":{"q":"Một người hướng dẫn qua đường ở trường học bước ra đường, cầm biển “STOP” (Dừng lại). Bạn phải làm gì?","o":["Chạy chậm lại và lái vòng qua họ","Chỉ dừng nếu đèn đỏ","Dừng lại và chờ đến khi người hướng dẫn và các em nhỏ ra khỏi đường","Bấm còi để họ đi qua nhanh hơn"],"h1":"Người hướng dẫn qua đường điều khiển giao thông ở chỗ qua đường.","h2":"Khi người hướng dẫn qua đường giơ biển “STOP” (Dừng lại), bạn phải dừng lại và đứng yên cho đến khi người hướng dẫn và các em nhỏ đã ra khỏi đường.","p":"Đúng rồi. Dừng lại và chờ người hướng dẫn."},"tl":{"q":"Isang school crossing guard ang pumasok sa kalsada na may hawak na “STOP” paddle (Huminto). Ano ang dapat mong gawin?","o":["Bumagal at umikot sa kanila","Huminto lang kung pula ang ilaw","Huminto at maghintay hanggang makaalis sa kalsada ang crossing guard at ang mga bata","Bumusina para bumilis sila sa pagtawid"],"h1":"Ang crossing guard ang nagkokontrol ng trapiko sa tawiran.","h2":"Kapag itinaas ng crossing guard ang “STOP” paddle (Huminto), dapat kang huminto at manatiling nakahinto hanggang makaalis sa kalsada ang crossing guard at ang mga bata.","p":"Tama. Huminto at hintayin ang crossing guard."},"ar":{"q":"حارس عبور مدرسي ينزل إلى الشارع وهو يحمل لوحة «STOP» (قف). ماذا يجب أن تفعل؟","o":["خفف السرعة ودُر حولهم","توقف فقط إذا كانت الإشارة حمراء","توقف وانتظر حتى يخرج الحارس والأطفال من الشارع","استخدم البوق لكي يعبروا أسرع"],"h1":"حارس العبور هو من ينظم المرور عند المعبر.","h2":"عندما يرفع حارس العبور لوحة «STOP» (قف)، يجب أن تتوقف وتبقى متوقفًا حتى يخرج الحارس والأطفال من الشارع.","p":"صحيح. توقف وانتظر الحارس."},"ht":{"q":"Yon gad travèse lekòl antre nan lari a ak yon pankat “STOP” (kanpe) nan men l. Kisa ou dwe fè?","o":["Ralanti epi fè wonn yo","Kanpe sèlman si limyè a wouj","Kanpe epi tann jiskaske gad la ak timoun yo soti nan lari a","Klaksonnen pou yo travèse pi vit"],"h1":"Gad travèse a kontwole sikilasyon an nan travèse a.","h2":"Lè yon gad travèse leve yon pankat “STOP” (kanpe), ou dwe kanpe epi rete kanpe jiskaske gad la ak timoun yo kite lari a.","p":"Se sa. Kanpe epi tann gad la."}},{"id":"signs-123","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"FLAGGER"},"c":3,"en":{"q":"An orange sign shows a person holding a flag. What does it warn about?","o":["A parade is ahead","A place to buy flags","A golf course is nearby","A flagger is ahead to control traffic, so be ready to stop"],"h1":"A flagger is a worker who directs traffic.","h2":"The orange Flagger sign warns that a worker is ahead directing traffic, so slow down and be ready to stop.","p":"Right. A flagger is ahead."},"es":{"q":"Una señal anaranjada muestra a una persona con una bandera. ¿De qué advierte?","o":["De que hay un desfile adelante","De un lugar donde venden banderas","De que hay un campo de golf cerca","De que hay un abanderado adelante que controla el tráfico, así que esté listo para pararse"],"h1":"Un abanderado es un trabajador que dirige el tráfico.","h2":"La señal anaranjada del abanderado advierte que hay un trabajador adelante dirigiendo el tráfico, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Hay un abanderado adelante."},"zh":{"q":"一个橙色标志上画着一个拿旗子的人。它在提醒什么？","o":["前方有游行","可以买旗子的地方","附近有高尔夫球场","前方有旗手指挥交通，要准备停车"],"h1":"旗手是指挥交通的工人。","h2":"橙色的旗手标志提醒你前方有工人在指挥交通，所以要减速，准备停车。","p":"对。前方有旗手。"},"vi":{"q":"Một biển màu cam có hình người cầm cờ. Biển này cảnh báo điều gì?","o":["Phía trước có diễn hành","Nơi bán cờ","Gần đây có sân gôn","Phía trước có người cầm cờ điều khiển giao thông, nên hãy sẵn sàng dừng lại"],"h1":"Người cầm cờ là công nhân điều khiển giao thông.","h2":"Biển màu cam có hình người cầm cờ cảnh báo phía trước có công nhân đang điều khiển giao thông, nên bạn hãy chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Phía trước có người cầm cờ."},"tl":{"q":"May karatulang kulay orange na may larawan ng taong may hawak na bandila. Ano ang babala nito?","o":["May parada sa unahan","Lugar na mabibilhan ng bandila","May golf course sa malapit","May flagger sa unahan na nagkokontrol ng trapiko, kaya maghandang huminto"],"h1":"Ang flagger ay trabahador na nagdidirekta ng trapiko.","h2":"Ang kulay orange na Flagger sign ay babala na may trabahador sa unahan na nagdidirekta ng trapiko, kaya bumagal at maghandang huminto.","p":"Tama. May flagger sa unahan."},"ar":{"q":"لافتة برتقالية عليها شخص يحمل علمًا. مِمَّ تحذّر؟","o":["هناك موكب في الأمام","مكان لشراء الأعلام","هناك ملعب غولف قريب","هناك عامل بالعلم في الأمام ينظم المرور، فكن مستعدًا للتوقف"],"h1":"العامل بالعلم هو عامل يوجّه المرور.","h2":"لافتة العامل بالعلم البرتقالية تحذّر من أن هناك عاملًا في الأمام يوجّه المرور، لذلك خفف السرعة وكن مستعدًا للتوقف.","p":"صحيح. هناك عامل بالعلم في الأمام."},"ht":{"q":"Yon siy zoranj montre yon moun ki kenbe yon drapo. Kisa li avèti ou?","o":["Gen yon defile pi devan","Yon kote pou achte drapo","Gen yon teren gòlf toupre","Gen yon moun ak drapo pi devan k ap kontwole sikilasyon an, kidonk pare pou kanpe"],"h1":"Moun ak drapo a se yon travayè ki dirije sikilasyon an.","h2":"Siy zoranj moun ak drapo a avèti ou gen yon travayè pi devan k ap dirije sikilasyon an, kidonk ralanti epi pare pou kanpe.","p":"Se sa. Gen yon moun ak drapo pi devan."}},{"id":"signs-124","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"ONE LANE ROAD AHEAD"},"c":0,"en":{"q":"An orange sign says ONE LANE ROAD AHEAD. What should you expect?","o":["Traffic from both directions will take turns using one lane","The road becomes one-way for good","A lane is added ahead","Only trucks may use the road"],"h1":"Cars going both ways will have to share.","h2":"ONE LANE ROAD AHEAD means traffic from both directions will share one lane, so expect a flagger or signal and be ready to stop.","p":"Right. Both directions share one lane."},"es":{"q":"Una señal anaranjada dice ONE LANE ROAD AHEAD. ¿Qué debe esperar?","o":["Que el tráfico de ambos sentidos se turnará para usar un solo carril","Que la vía será de un solo sentido para siempre","Que se agrega un carril","Que solo los camiones pueden usar la vía"],"h1":"Los carros de ambos sentidos tendrán que compartir.","h2":"ONE LANE ROAD AHEAD significa que el tráfico de ambos sentidos compartirá un carril, así que espere un abanderado o un semáforo y esté listo para pararse.","p":"Correcto. Ambos sentidos comparten un carril."},"zh":{"q":"一个橙色标志写着“ONE LANE ROAD AHEAD”（前方单车道）。你应该预料到什么？","o":["两个方向的车会轮流使用同一条车道","这条路以后一直是单行道","前方会多出一条车道","只有卡车可以走这条路"],"h1":"两个方向的车要共用一条路。","h2":"“ONE LANE ROAD AHEAD”（前方单车道）表示两个方向的车要共用一条车道，所以要预料到会有旗手或信号灯，并准备停车。","p":"对。两个方向共用一条车道。"},"vi":{"q":"Một biển màu cam ghi “ONE LANE ROAD AHEAD” (Phía trước đường một làn). Bạn nên chờ đợi điều gì?","o":["Xe từ hai chiều sẽ thay phiên nhau đi trên một làn","Con đường trở thành đường một chiều luôn","Phía trước có thêm một làn","Chỉ xe tải được đi trên đường này"],"h1":"Xe đi cả hai chiều sẽ phải dùng chung.","h2":"“ONE LANE ROAD AHEAD” (Phía trước đường một làn) nghĩa là xe từ hai chiều sẽ dùng chung một làn, nên hãy chờ có người cầm cờ hoặc đèn tín hiệu và sẵn sàng dừng lại.","p":"Đúng rồi. Hai chiều dùng chung một làn."},"tl":{"q":"May karatulang kulay orange na nagsasabing “ONE LANE ROAD AHEAD” (Isang linya na lang ang kalsada sa unahan). Ano ang dapat mong asahan?","o":["Magsasalitan sa iisang linya ang trapiko mula sa dalawang direksyon","Magiging one-way na ang kalsada magpakailanman","May madadagdag na linya sa unahan","Mga trak lang ang puwede sa kalsada"],"h1":"Maghahati ang mga sasakyang papunta sa magkabilang direksyon.","h2":"Ang “ONE LANE ROAD AHEAD” ay nangangahulugang maghahati sa iisang linya ang trapiko mula sa dalawang direksyon, kaya asahan ang flagger o signal at maghandang huminto.","p":"Tama. Iisang linya ang hinahati ng dalawang direksyon."},"ar":{"q":"لافتة برتقالية مكتوب عليها «ONE LANE ROAD AHEAD» (طريق بمسار واحد في الأمام). ماذا يجب أن تتوقع؟","o":["السيارات من الاتجاهين ستتناوب على استخدام مسار واحد","الطريق يصبح باتجاه واحد بشكل دائم","سيُضاف مسار في الأمام","الشاحنات فقط يمكنها استخدام الطريق"],"h1":"السيارات في الاتجاهين ستضطر إلى التشارك.","h2":"«ONE LANE ROAD AHEAD» تعني أن السيارات من الاتجاهين ستتشارك مسارًا واحدًا، لذلك توقّع وجود عامل بالعلم أو إشارة، وكن مستعدًا للتوقف.","p":"صحيح. الاتجاهان يتشاركان مسارًا واحدًا."},"ht":{"q":"Yon siy zoranj ekri “ONE LANE ROAD AHEAD” (wout yon sèl koulwa pi devan). Kisa ou dwe atann?","o":["Machin ki soti nan de direksyon yo pral fè tou pou itilize yon sèl koulwa","Wout la vin yon sèl sans pou tout tan","Gen yon koulwa ki ajoute pi devan","Se kamyon sèlman ki ka pran wout la"],"h1":"Machin k ap ale nan de sans yo pral oblije pataje.","h2":"“ONE LANE ROAD AHEAD” vle di machin ki soti nan de direksyon yo pral pataje yon sèl koulwa, kidonk atann yon moun ak drapo oswa yon limyè, epi pare pou kanpe.","p":"Se sa. De direksyon yo pataje yon sèl koulwa."}},{"id":"signs-125","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"LEFT LANE CLOSED AHEAD"},"c":1,"en":{"q":"An orange sign says LEFT LANE CLOSED AHEAD. You are in the left lane. What should you do?","o":["Stay in your lane until it ends","Move to the right lane early, when it is safe","Stop and wait for workers to wave you on","Speed up to pass cars on the right"],"h1":"Your lane will be blocked.","h2":"LEFT LANE CLOSED AHEAD means the left lane will be blocked, so signal and move right early when there is a safe gap.","p":"Right. Move over early."},"es":{"q":"Una señal anaranjada dice LEFT LANE CLOSED AHEAD. Usted va en el carril izquierdo. ¿Qué debe hacer?","o":["Quedarse en su carril hasta que termine","Pasarse temprano al carril derecho, cuando sea seguro","Pararse y esperar que los trabajadores le hagan señas","Acelerar para rebasar por la derecha"],"h1":"Su carril va a estar bloqueado.","h2":"LEFT LANE CLOSED AHEAD significa que el carril izquierdo estará bloqueado, así que señale y pásese a la derecha temprano cuando haya un espacio seguro.","p":"Correcto. Cámbiese temprano."},"zh":{"q":"一个橙色标志写着“LEFT LANE CLOSED AHEAD”（前方左车道封闭）。你在左车道。你应该怎么做？","o":["一直留在你的车道，直到车道结束","安全时，提早换到右车道","停车，等工人挥手让你走","加速，从右边超车"],"h1":"你的车道会被挡住。","h2":"“LEFT LANE CLOSED AHEAD”（前方左车道封闭）表示左车道会被挡住，所以有安全空当时，要打灯，提早向右换道。","p":"对。提早换道。"},"vi":{"q":"Một biển màu cam ghi “LEFT LANE CLOSED AHEAD” (Phía trước đóng làn trái). Bạn đang ở làn trái. Bạn nên làm gì?","o":["Cứ ở trong làn của mình cho đến khi hết làn","Chuyển sang làn phải sớm, khi an toàn","Dừng lại và chờ công nhân vẫy tay cho đi","Tăng tốc để vượt xe bên phải"],"h1":"Làn của bạn sẽ bị chặn.","h2":"“LEFT LANE CLOSED AHEAD” (Phía trước đóng làn trái) nghĩa là làn trái sẽ bị chặn, nên hãy bật đèn xi nhan và chuyển sang phải sớm khi có khoảng trống an toàn.","p":"Đúng rồi. Chuyển làn sớm."},"tl":{"q":"May karatulang kulay orange na nagsasabing “LEFT LANE CLOSED AHEAD” (Sarado ang kaliwang linya sa unahan). Nasa kaliwang linya ka. Ano ang dapat mong gawin?","o":["Manatili sa linya mo hanggang matapos ito","Lumipat nang maaga sa kanang linya, kapag ligtas","Huminto at hintaying kawayan ka ng mga trabahador","Bumilis para lampasan ang mga sasakyan sa kanan"],"h1":"Haharangan ang linya mo.","h2":"Ang “LEFT LANE CLOSED AHEAD” ay nangangahulugang haharangan ang kaliwang linya, kaya mag-signal at lumipat sa kanan nang maaga kapag may ligtas na puwang.","p":"Tama. Lumipat nang maaga."},"ar":{"q":"لافتة برتقالية مكتوب عليها «LEFT LANE CLOSED AHEAD» (المسار الأيسر مغلق في الأمام). أنت في المسار الأيسر. ماذا يجب أن تفعل؟","o":["ابقَ في مسارك حتى ينتهي","انتقل إلى المسار الأيمن مبكرًا، عندما يكون ذلك آمنًا","توقف وانتظر حتى يشير لك العمال بالمرور","زد السرعة لتتجاوز السيارات من اليمين"],"h1":"مسارك سيكون مغلقًا.","h2":"«LEFT LANE CLOSED AHEAD» تعني أن المسار الأيسر سيكون مغلقًا، لذلك استخدم الإشارة وانتقل إلى اليمين مبكرًا عندما تجد فراغًا آمنًا.","p":"صحيح. انتقل مبكرًا."},"ht":{"q":"Yon siy zoranj ekri “LEFT LANE CLOSED AHEAD” (koulwa goch la fèmen pi devan). Ou nan koulwa goch la. Kisa ou dwe fè?","o":["Rete nan koulwa ou jiskaske li fini","Pase nan koulwa dwat la bonè, lè sa an sekirite","Kanpe epi tann travayè yo fè ou siy pou pase","Akselere pou pase machin yo sou bò dwat"],"h1":"Koulwa ou a pral bloke.","h2":"“LEFT LANE CLOSED AHEAD” vle di koulwa goch la pral bloke, kidonk mete siyal ou epi pase sou bò dwat bonè lè gen yon espas ki an sekirite.","p":"Se sa. Chanje koulwa bonè."}},{"id":"signs-126","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"WORKERS"},"c":2,"en":{"q":"An orange sign shows a person with a shovel. What should you do?","o":["Stop and offer help","Honk so the workers move","Slow down and watch for workers on or near the road","Keep your speed; workers stay off the road"],"h1":"The person on the sign is a road worker.","h2":"The Workers sign warns that people are working on or near the road, so slow down and be ready to stop for them.","p":"Right. Workers are near the road."},"es":{"q":"Una señal anaranjada muestra a una persona con una pala. ¿Qué debe hacer?","o":["Pararse y ofrecer ayuda","Tocar la bocina para que se aparten","Bajar la velocidad y estar atento a trabajadores en la vía o cerca","Mantener la velocidad; los trabajadores no salen a la vía"],"h1":"La persona de la señal es un trabajador de la vía.","h2":"La señal de trabajadores advierte que hay personas trabajando en la vía o cerca, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Hay trabajadores cerca de la vía."},"zh":{"q":"一个橙色标志上画着一个拿铁锹的人。你应该怎么做？","o":["停车，去帮忙","按喇叭让工人让开","减速，注意路上或路边的工人","保持车速；工人不会走到路上"],"h1":"标志上的人是道路工人。","h2":"工人标志提醒你有人在路上或路边工作，所以要减速，准备为他们停车。","p":"对。路边有工人。"},"vi":{"q":"Một biển màu cam có hình người cầm xẻng. Bạn nên làm gì?","o":["Dừng lại và đề nghị giúp","Bấm còi để công nhân tránh ra","Chạy chậm lại và chú ý công nhân ở trên hoặc gần đường","Giữ tốc độ; công nhân không ra đường"],"h1":"Người trên biển là công nhân làm đường.","h2":"Biển công nhân cảnh báo có người đang làm việc ở trên hoặc gần đường, nên bạn hãy chạy chậm lại và sẵn sàng dừng cho họ.","p":"Đúng rồi. Có công nhân gần đường."},"tl":{"q":"May karatulang kulay orange na may larawan ng taong may pala. Ano ang dapat mong gawin?","o":["Huminto at mag-alok ng tulong","Bumusina para umalis ang mga trabahador","Bumagal at mag-ingat sa mga trabahador sa kalsada o malapit dito","Panatilihin ang bilis mo; hindi pumupunta sa kalsada ang mga trabahador"],"h1":"Ang tao sa karatula ay trabahador sa kalsada.","h2":"Ang Workers sign ay babala na may mga taong nagtatrabaho sa kalsada o malapit dito, kaya bumagal at maghandang huminto para sa kanila.","p":"Tama. May mga trabahador malapit sa kalsada."},"ar":{"q":"لافتة برتقالية عليها شخص يحمل مجرفة. ماذا يجب أن تفعل؟","o":["توقف واعرض المساعدة","استخدم البوق لكي يبتعد العمال","خفف السرعة وانتبه للعمال على الطريق أو بالقرب منه","حافظ على سرعتك؛ العمال لا ينزلون إلى الطريق"],"h1":"الشخص على اللافتة هو عامل طرق.","h2":"لافتة العمال تحذّر من أن هناك أشخاصًا يعملون على الطريق أو بالقرب منه، لذلك خفف السرعة وكن مستعدًا للتوقف من أجلهم.","p":"صحيح. هناك عمال قرب الطريق."},"ht":{"q":"Yon siy zoranj montre yon moun ki gen yon pèl. Kisa ou dwe fè?","o":["Kanpe epi ofri èd","Klaksonnen pou travayè yo deplase","Ralanti epi veye travayè ki sou wout la oswa toupre l","Kenbe vitès ou; travayè yo pa janm sou wout la"],"h1":"Moun ki sou siy la se yon travayè wout.","h2":"Siy travayè a avèti ou gen moun k ap travay sou wout la oswa toupre l, kidonk ralanti epi pare pou kanpe pou yo.","p":"Se sa. Gen travayè toupre wout la."}},{"id":"signs-127","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"FRESH OIL"},"c":3,"en":{"q":"An orange sign says FRESH OIL. What should you do?","o":["Stop and buy oil","Speed up to get through quickly","Turn on your wipers","Slow down; the new road surface can be slippery and splash your car"],"h1":"New oil or tar was just put on the road.","h2":"FRESH OIL warns that new oil or tar is on the road, which can be slippery and splash, so slow down.","p":"Right. Slow down on the fresh oil."},"es":{"q":"Una señal anaranjada dice FRESH OIL. ¿Qué debe hacer?","o":["Pararse a comprar aceite","Acelerar para pasar rápido","Encender los limpiaparabrisas","Bajar la velocidad; la superficie nueva puede estar resbalosa y salpicar su carro"],"h1":"Acaban de poner aceite o asfalto nuevo en la vía.","h2":"FRESH OIL advierte que hay aceite o asfalto nuevo en la vía, que puede estar resbaloso y salpicar, así que baje la velocidad.","p":"Correcto. Baje la velocidad en el asfalto nuevo."},"zh":{"q":"一个橙色标志写着“FRESH OIL”（新铺沥青油）。你应该怎么做？","o":["停车买油","加速快点开过去","打开雨刷","减速；新铺的路面可能很滑，还会溅到你的车上"],"h1":"路上刚铺了新的油或沥青。","h2":"“FRESH OIL”（新铺沥青油）提醒你路上有新的油或沥青，可能很滑，还会溅起来，所以要减速。","p":"对。在新铺的油上要减速。"},"vi":{"q":"Một biển màu cam ghi “FRESH OIL” (Dầu nhựa mới rải). Bạn nên làm gì?","o":["Dừng lại để mua dầu","Tăng tốc để đi qua cho nhanh","Bật cần gạt nước","Chạy chậm lại; mặt đường mới có thể trơn và văng lên xe bạn"],"h1":"Dầu hoặc nhựa đường mới vừa được rải trên đường.","h2":"“FRESH OIL” (Dầu nhựa mới rải) cảnh báo có dầu hoặc nhựa đường mới trên đường, có thể trơn và văng lên, nên hãy chạy chậm lại.","p":"Đúng rồi. Chạy chậm trên lớp dầu mới."},"tl":{"q":"May karatulang kulay orange na nagsasabing “FRESH OIL” (Bagong langis sa kalsada). Ano ang dapat mong gawin?","o":["Huminto at bumili ng langis","Bumilis para mabilis na makalampas","Buksan ang wipers mo","Bumagal; maaaring madulas ang bagong ibabaw ng kalsada at tumalsik sa kotse mo"],"h1":"Bagong lagay ang langis o aspalto sa kalsada.","h2":"Ang “FRESH OIL” ay babala na may bagong langis o aspalto sa kalsada, na maaaring madulas at tumalsik, kaya bumagal.","p":"Tama. Bumagal sa bagong langis."},"ar":{"q":"لافتة برتقالية مكتوب عليها «FRESH OIL» (زيت جديد على الطريق). ماذا يجب أن تفعل؟","o":["توقف واشترِ زيتًا","زد السرعة لتمر بسرعة","شغّل المسّاحات","خفف السرعة؛ سطح الطريق الجديد قد يكون زلقًا ويتناثر على سيارتك"],"h1":"وُضع زيت أو قطران جديد على الطريق للتو.","h2":"«FRESH OIL» تحذّر من وجود زيت أو قطران جديد على الطريق، وقد يكون زلقًا ويتناثر، لذلك خفف السرعة.","p":"صحيح. خفف السرعة على الزيت الجديد."},"ht":{"q":"Yon siy zoranj ekri “FRESH OIL” (lwil fre sou wout la). Kisa ou dwe fè?","o":["Kanpe pou achte lwil","Akselere pou pase vit","Limen esuiglas ou","Ralanti; nouvo sifas wout la ka glise epi li ka eklabouse machin ou"],"h1":"Yo fèk mete lwil oswa goudwon nèf sou wout la.","h2":"“FRESH OIL” avèti ou gen lwil oswa goudwon nèf sou wout la, ki ka glise epi eklabouse, kidonk ralanti.","p":"Se sa. Ralanti sou lwil fre a."}},{"id":"signs-128","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"UNEVEN LANES"},"c":0,"en":{"q":"In a work zone, an orange sign says UNEVEN LANES. What does it mean?","o":["One lane is higher than the lane next to it, so change lanes with care","The lanes have different speed limits","One lane is only for trucks","The lanes are different colors"],"h1":"Uneven means not at the same height.","h2":"UNEVEN LANES warns that the road surface of one lane is higher than the next, so take care when you change lanes.","p":"Right. The lanes are at different heights."},"es":{"q":"En una zona de obras, una señal anaranjada dice UNEVEN LANES. ¿Qué significa?","o":["Que un carril está más alto que el de al lado, así que cambie de carril con cuidado","Que los carriles tienen distintos límites de velocidad","Que un carril es solo para camiones","Que los carriles son de distintos colores"],"h1":"Uneven quiere decir que no están a la misma altura.","h2":"UNEVEN LANES advierte que la superficie de un carril está más alta que la del otro, así que tenga cuidado al cambiar de carril.","p":"Correcto. Los carriles tienen distinta altura."},"zh":{"q":"在施工区，一个橙色标志写着“UNEVEN LANES”（车道高低不平）。这是什么意思？","o":["一条车道比旁边的车道高，所以换道时要小心","各条车道的限速不同","有一条车道只给卡车用","车道的颜色不同"],"h1":"“Uneven”的意思是高度不一样。","h2":"“UNEVEN LANES”（车道高低不平）提醒你一条车道的路面比旁边的高，所以换道时要小心。","p":"对。车道高度不同。"},"vi":{"q":"Trong khu vực thi công, một biển màu cam ghi “UNEVEN LANES” (Các làn không bằng nhau). Biển này có nghĩa là gì?","o":["Một làn cao hơn làn bên cạnh, nên hãy đổi làn cẩn thận","Các làn có tốc độ tối đa khác nhau","Một làn chỉ dành cho xe tải","Các làn có màu khác nhau"],"h1":"“Uneven” nghĩa là không cùng độ cao.","h2":"“UNEVEN LANES” (Các làn không bằng nhau) cảnh báo mặt đường của một làn cao hơn làn bên cạnh, nên hãy cẩn thận khi đổi làn.","p":"Đúng rồi. Các làn có độ cao khác nhau."},"tl":{"q":"Sa work zone, may karatulang kulay orange na nagsasabing “UNEVEN LANES” (Hindi pantay ang mga linya). Ano ang ibig sabihin nito?","o":["Mas mataas ang isang linya kaysa sa katabi nito, kaya mag-ingat sa paglipat ng linya","Magkakaiba ang speed limit ng mga linya","Para sa mga trak lang ang isang linya","Magkakaiba ang kulay ng mga linya"],"h1":"Ang “uneven” ay nangangahulugang hindi magkapareho ang taas.","h2":"Ang “UNEVEN LANES” ay babala na mas mataas ang ibabaw ng isang linya kaysa sa katabi nito, kaya mag-ingat kapag lilipat ka ng linya.","p":"Tama. Magkaiba ang taas ng mga linya."},"ar":{"q":"في منطقة عمل، لافتة برتقالية مكتوب عليها «UNEVEN LANES» (مسارات غير مستوية). ماذا تعني؟","o":["أحد المسارات أعلى من المسار المجاور له، فغيّر المسار بحذر","المسارات لها حدود سرعة مختلفة","أحد المسارات للشاحنات فقط","المسارات لها ألوان مختلفة"],"h1":"«Uneven» تعني ليس على الارتفاع نفسه.","h2":"«UNEVEN LANES» تحذّر من أن سطح أحد المسارات أعلى من المسار المجاور، لذلك انتبه جيدًا عندما تغيّر المسار.","p":"صحيح. المسارات على ارتفاعات مختلفة."},"ht":{"q":"Nan yon zòn travay, yon siy zoranj ekri “UNEVEN LANES” (koulwa ki pa egal). Kisa sa vle di?","o":["Yon koulwa pi wo pase koulwa ki bò kote l la, kidonk chanje koulwa avèk prekosyon","Koulwa yo gen limit vitès diferan","Yon koulwa se pou kamyon sèlman","Koulwa yo gen koulè diferan"],"h1":"“Uneven” vle di yo pa menm wotè.","h2":"“UNEVEN LANES” avèti ou sifas yon koulwa pi wo pase koulwa ki bò kote l la, kidonk fè atansyon lè w ap chanje koulwa.","p":"Se sa. Koulwa yo pa menm wotè."}},{"id":"signs-129","scope":"US","cat":"signs","sign":{"shape":"rect-orange","text":"END ROAD WORK"},"c":1,"en":{"q":"You see a sign that says END ROAD WORK. What does it tell you?","o":["Road work starts here","You have reached the end of the work zone","Workers are on a break","The road ends here"],"h1":"End means finished.","h2":"END ROAD WORK marks the end of the work zone, so you can return to normal driving while obeying the posted signs.","p":"Right. The work zone ends here."},"es":{"q":"Usted ve una señal que dice END ROAD WORK. ¿Qué le indica?","o":["Que aquí empiezan las obras","Que llegó al final de la zona de obras","Que los trabajadores están descansando","Que la vía termina aquí"],"h1":"End quiere decir fin.","h2":"END ROAD WORK marca el final de la zona de obras, así que puede volver a manejar normalmente, obedeciendo las señales indicadas.","p":"Correcto. Aquí termina la zona de obras."},"zh":{"q":"你看到一个标志写着“END ROAD WORK”（道路施工结束）。它告诉你什么？","o":["道路施工从这里开始","你已经到了施工区的尽头","工人在休息","道路在这里结束"],"h1":"“End”的意思是结束了。","h2":"“END ROAD WORK”（道路施工结束）表示施工区到这里结束，所以你可以恢复正常驾驶，同时遵守路边的标志。","p":"对。施工区在这里结束。"},"vi":{"q":"Bạn thấy một biển ghi “END ROAD WORK” (Hết đoạn sửa đường). Biển này cho bạn biết gì?","o":["Đoạn sửa đường bắt đầu từ đây","Bạn đã đến cuối khu vực thi công","Công nhân đang nghỉ","Con đường hết ở đây"],"h1":"“End” nghĩa là kết thúc.","h2":"“END ROAD WORK” (Hết đoạn sửa đường) đánh dấu cuối khu vực thi công, nên bạn có thể lái bình thường trở lại và vẫn tuân theo các biển báo trên đường.","p":"Đúng rồi. Khu vực thi công kết thúc ở đây."},"tl":{"q":"May nakita kang karatulang nagsasabing “END ROAD WORK” (Tapos na ang ginagawang kalsada). Ano ang sinasabi nito sa iyo?","o":["Dito nagsisimula ang ginagawang kalsada","Narating mo na ang dulo ng work zone","Nagpapahinga ang mga trabahador","Dito nagtatapos ang kalsada"],"h1":"Ang “end” ay nangangahulugang tapos na.","h2":"Ang “END ROAD WORK” ay nagmamarka ng dulo ng work zone, kaya puwede ka nang bumalik sa normal na pagmamaneho habang sumusunod sa mga nakapaskil na karatula.","p":"Tama. Dito nagtatapos ang work zone."},"ar":{"q":"ترى لافتة مكتوب عليها «END ROAD WORK» (نهاية أعمال الطريق). ماذا تخبرك؟","o":["أعمال الطريق تبدأ هنا","وصلت إلى نهاية منطقة العمل","العمال في استراحة","الطريق ينتهي هنا"],"h1":"«End» تعني انتهى.","h2":"«END ROAD WORK» تحدد نهاية منطقة العمل، لذلك يمكنك العودة إلى القيادة العادية مع الالتزام باللافتات الموجودة.","p":"صحيح. منطقة العمل تنتهي هنا."},"ht":{"q":"Ou wè yon siy ki ekri “END ROAD WORK” (fen travay sou wout la). Kisa li di ou?","o":["Travay sou wout la kòmanse isit la","Ou rive nan fen zòn travay la","Travayè yo an poz","Wout la fini isit la"],"h1":"“End” vle di fini.","h2":"“END ROAD WORK” make fen zòn travay la, kidonk ou ka retounen kondui nòmal pandan w ap respekte siy ki poze yo.","p":"Se sa. Zòn travay la fini isit la."}},{"id":"signs-130","scope":"US","cat":"signs","sign":{"shape":"rect-orange","text":"PILOT CAR FOLLOW ME"},"c":2,"en":{"q":"In a work zone, a truck has a sign that says PILOT CAR FOLLOW ME. What should you do?","o":["Pass the pilot car as soon as you can","Wait until the pilot car leaves the road","Follow the pilot car through the work zone","Take a different road"],"h1":"A pilot car leads traffic through a one-lane area.","h2":"A pilot car leads traffic through a work zone, so follow it and do not pass it.","p":"Right. Follow the pilot car."},"es":{"q":"En una zona de obras, una camioneta tiene una señal que dice PILOT CAR FOLLOW ME. ¿Qué debe hacer?","o":["Rebasar al vehículo guía lo antes posible","Esperar a que el vehículo guía salga de la vía","Seguir al vehículo guía a través de la zona de obras","Tomar otra vía"],"h1":"Un vehículo guía lleva al tráfico por una zona de un solo carril.","h2":"Un vehículo guía (pilot car) conduce al tráfico por una zona de obras, así que sígalo y no lo rebase.","p":"Correcto. Siga al vehículo guía."},"zh":{"q":"在施工区，一辆卡车上有个标志写着“PILOT CAR FOLLOW ME”（引导车，请跟我走）。你应该怎么做？","o":["尽快超过引导车","等引导车离开道路","跟着引导车通过施工区","换一条路走"],"h1":"引导车带领车辆通过只有一条车道的路段。","h2":"引导车带领车辆通过施工区，所以你要跟着它走，不要超过它。","p":"对。跟着引导车走。"},"vi":{"q":"Trong khu vực thi công, một xe tải có biển ghi “PILOT CAR FOLLOW ME” (Xe dẫn đường, hãy đi theo tôi). Bạn nên làm gì?","o":["Vượt xe dẫn đường ngay khi có thể","Chờ đến khi xe dẫn đường rời khỏi đường","Đi theo xe dẫn đường qua khu vực thi công","Đi đường khác"],"h1":"Xe dẫn đường dẫn xe cộ qua đoạn đường chỉ có một làn.","h2":"Xe dẫn đường dẫn xe cộ đi qua khu vực thi công, nên bạn hãy đi theo nó và không được vượt nó.","p":"Đúng rồi. Đi theo xe dẫn đường."},"tl":{"q":"Sa work zone, may trak na may karatulang nagsasabing “PILOT CAR FOLLOW ME” (Pilot car, sumunod sa akin). Ano ang dapat mong gawin?","o":["Lampasan ang pilot car sa lalong madaling panahon","Hintaying umalis sa kalsada ang pilot car","Sundan ang pilot car sa work zone","Dumaan sa ibang kalsada"],"h1":"Ang pilot car ang nangunguna sa trapiko sa lugar na iisa lang ang linya.","h2":"Ang pilot car ang nangunguna sa trapiko sa work zone, kaya sundan mo ito at huwag mo itong lampasan.","p":"Tama. Sundan ang pilot car."},"ar":{"q":"في منطقة عمل، على شاحنة لافتة مكتوب عليها «PILOT CAR FOLLOW ME» (سيارة إرشاد، اتبعني). ماذا يجب أن تفعل؟","o":["تجاوز سيارة الإرشاد في أسرع وقت ممكن","انتظر حتى تغادر سيارة الإرشاد الطريق","اتبع سيارة الإرشاد عبر منطقة العمل","خذ طريقًا آخر"],"h1":"سيارة الإرشاد تقود السيارات عبر منطقة فيها مسار واحد.","h2":"سيارة الإرشاد تقود السيارات عبر منطقة العمل، لذلك اتبعها، ويجب ألّا تتجاوزها.","p":"صحيح. اتبع سيارة الإرشاد."},"ht":{"q":"Nan yon zòn travay, yon kamyon gen yon siy ki ekri “PILOT CAR FOLLOW ME” (machin gid, swiv mwen). Kisa ou dwe fè?","o":["Pase machin gid la depi ou kapab","Tann jiskaske machin gid la kite wout la","Swiv machin gid la pou travèse zòn travay la","Pran yon lòt wout"],"h1":"Yon machin gid mennen machin yo nan yon zòn ki gen yon sèl koulwa.","h2":"Yon machin gid mennen machin yo travèse yon zòn travay, kidonk swiv li epi pa pase l.","p":"Se sa. Swiv machin gid la."}},{"id":"signs-131","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"In a work zone, a lighted arrow board shows a big flashing arrow pointing to the left. What should you do?","o":["Turn left at the next street","Stop and wait","Stay in your lane; it is only a reminder","Move to the left; the lane ahead is closed"],"h1":"The arrow points where you need to go.","h2":"A flashing arrow on an arrow board means the lane ahead is closed, so merge in the direction of the arrow when it is safe.","p":"Right. Merge the way the arrow points."},"es":{"q":"En una zona de obras, un tablero luminoso muestra una gran flecha intermitente que apunta a la izquierda. ¿Qué debe hacer?","o":["Girar a la izquierda en la próxima calle","Pararse y esperar","Seguir en su carril; es solo un recordatorio","Pasarse a la izquierda; el carril de adelante está cerrado"],"h1":"La flecha apunta hacia donde usted debe ir.","h2":"Una flecha intermitente en un tablero luminoso significa que el carril de adelante está cerrado, así que incorpórese hacia donde apunta la flecha cuando sea seguro.","p":"Correcto. Cámbiese hacia donde apunta la flecha."},"zh":{"q":"在施工区，一块发光的箭头板上有一个向左闪烁的大箭头。你应该怎么做？","o":["在下一个路口左转","停车等候","留在你的车道；这只是提醒","向左换道；前方车道封闭"],"h1":"箭头指向你要去的方向。","h2":"箭头板上闪烁的箭头表示前方车道封闭，所以安全时要按箭头方向并道。","p":"对。按箭头方向并道。"},"vi":{"q":"Trong khu vực thi công, một bảng đèn có mũi tên lớn nhấp nháy chỉ sang trái. Bạn nên làm gì?","o":["Rẽ trái ở đường kế tiếp","Dừng lại và chờ","Cứ ở trong làn của mình; đó chỉ là lời nhắc","Chuyển sang trái; làn phía trước bị đóng"],"h1":"Mũi tên chỉ hướng bạn cần đi.","h2":"Mũi tên nhấp nháy trên bảng đèn mũi tên nghĩa là làn phía trước bị đóng, nên hãy nhập làn theo hướng mũi tên khi an toàn.","p":"Đúng rồi. Nhập làn theo hướng mũi tên."},"tl":{"q":"Sa work zone, may arrow board na may ilaw na nagpapakita ng malaking kumikislap na arrow na nakaturo sa kaliwa. Ano ang dapat mong gawin?","o":["Kumaliwa sa susunod na kalye","Huminto at maghintay","Manatili sa linya mo; paalala lang ito","Lumipat sa kaliwa; sarado ang linya sa unahan"],"h1":"Itinuturo ng arrow kung saan ka dapat pumunta.","h2":"Ang kumikislap na arrow sa arrow board ay nangangahulugang sarado ang linya sa unahan, kaya sumingit sa direksyon ng arrow kapag ligtas.","p":"Tama. Sumingit sa direksyong itinuturo ng arrow."},"ar":{"q":"في منطقة عمل، لوحة أسهم مضيئة تُظهر سهمًا كبيرًا وامضًا يشير إلى اليسار. ماذا يجب أن تفعل؟","o":["انعطف يسارًا في الشارع التالي","توقف وانتظر","ابقَ في مسارك؛ إنها مجرد تذكير","انتقل إلى اليسار؛ المسار الذي أمامك مغلق"],"h1":"السهم يشير إلى المكان الذي يجب أن تذهب إليه.","h2":"السهم الوامض على لوحة الأسهم يعني أن المسار الذي أمامك مغلق، لذلك اندمج في اتجاه السهم عندما يكون ذلك آمنًا.","p":"صحيح. اندمج في الاتجاه الذي يشير إليه السهم."},"ht":{"q":"Nan yon zòn travay, yon tablo limen montre yon gwo flèch k ap kliyote ki pwente sou bò goch. Kisa ou dwe fè?","o":["Vire agoch nan pwochen lari a","Kanpe epi tann","Rete nan koulwa ou; se yon rapèl sèlman","Pase sou bò goch; koulwa pi devan an fèmen"],"h1":"Flèch la montre kote ou bezwen ale.","h2":"Yon flèch k ap kliyote sou yon tablo flèch vle di koulwa pi devan an fèmen, kidonk antre nan direksyon flèch la lè sa an sekirite.","p":"Se sa. Antre nan direksyon flèch la montre a."}},{"id":"signs-132","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"A lighted board in a work zone flashes only a bar or four corner lights, not an arrow. What does it mean?","o":["Drive with caution; work is near the road, and the board is not telling you to merge","Your lane is closed, so merge right","The road is closed ahead","You may speed up"],"h1":"An arrow would tell you to change lanes.","h2":"When an arrow board shows a bar or corner lights instead of an arrow, it is in caution mode: work is near the road, so slow down and take care.","p":"Right. It means caution, not a lane change."},"es":{"q":"Un tablero luminoso en una zona de obras muestra solo una barra o cuatro luces en las esquinas, sin flecha. ¿Qué significa?","o":["Maneje con precaución; hay obras cerca de la vía, y el tablero no le indica que cambie de carril","Su carril está cerrado, cámbiese a la derecha","La vía está cerrada adelante","Puede acelerar"],"h1":"Una flecha le diría que cambie de carril.","h2":"Cuando el tablero muestra una barra o luces en las esquinas en vez de una flecha, está en modo de precaución: hay obras cerca de la vía, así que baje la velocidad y tenga cuidado.","p":"Correcto. Significa precaución, no cambio de carril."},"zh":{"q":"施工区的一块发光板只闪一条横杠或四个角的灯，不是箭头。这是什么意思？","o":["小心驾驶；路边有施工，这块板不是叫你并道","你的车道封闭了，要向右并道","前方道路封闭","你可以加速"],"h1":"如果是箭头，就是叫你换道。","h2":"当箭头板显示横杠或四角灯而不是箭头时，它是在提醒你小心：路边有施工，所以要减速，多加小心。","p":"对。它表示小心，不是叫你换道。"},"vi":{"q":"Một bảng đèn trong khu vực thi công chỉ nhấp nháy một vạch ngang hoặc bốn đèn ở góc, không phải mũi tên. Điều đó có nghĩa là gì?","o":["Lái xe cẩn thận; có công việc gần đường, và bảng này không bảo bạn nhập làn","Làn của bạn bị đóng, nên hãy nhập sang phải","Đường phía trước bị đóng","Bạn có thể tăng tốc"],"h1":"Nếu là mũi tên thì nó bảo bạn đổi làn.","h2":"Khi bảng đèn mũi tên hiện một vạch ngang hoặc đèn ở góc thay vì mũi tên, nó đang ở chế độ cảnh báo: có công việc gần đường, nên hãy chạy chậm lại và cẩn thận.","p":"Đúng rồi. Nó có nghĩa là cẩn thận, không phải đổi làn."},"tl":{"q":"Sa work zone, may board na may ilaw na kumikislap ng isang bar o apat na ilaw sa mga sulok lang, hindi arrow. Ano ang ibig sabihin nito?","o":["Magmaneho nang maingat; may trabaho malapit sa kalsada, at hindi ka sinasabihan ng board na sumingit","Sarado ang linya mo, kaya sumingit sa kanan","Sarado ang kalsada sa unahan","Puwede kang bumilis"],"h1":"Kung arrow, sinasabihan ka nitong lumipat ng linya.","h2":"Kapag bar o mga ilaw sa sulok ang ipinakita ng arrow board sa halip na arrow, nasa caution mode ito: may trabaho malapit sa kalsada, kaya bumagal at mag-ingat.","p":"Tama. Pag-iingat ang ibig sabihin nito, hindi paglipat ng linya."},"ar":{"q":"لوحة مضيئة في منطقة عمل تومض بخط أفقي فقط أو بأربعة أضواء في الزوايا، وليس بسهم. ماذا يعني ذلك؟","o":["قُد بحذر؛ هناك أعمال قرب الطريق، واللوحة لا تطلب منك الاندماج","مسارك مغلق، فاندمج إلى اليمين","الطريق مغلق في الأمام","يمكنك زيادة السرعة"],"h1":"السهم هو الذي يطلب منك تغيير المسار.","h2":"عندما تُظهر لوحة الأسهم خطًا أفقيًا أو أضواء في الزوايا بدلًا من سهم، فهي في وضع التحذير: هناك أعمال قرب الطريق، لذلك خفف السرعة وانتبه جيدًا.","p":"صحيح. إنها تعني الحذر، وليس تغيير المسار."},"ht":{"q":"Yon tablo limen nan yon zòn travay ap kliyote yon ba sèlman oswa kat limyè nan kwen yo, pa yon flèch. Kisa sa vle di?","o":["Kondui avèk prekosyon; gen travay toupre wout la, epi tablo a pa di ou antre nan yon lòt koulwa","Koulwa ou fèmen, kidonk antre sou bò dwat","Wout la fèmen pi devan","Ou ka akselere"],"h1":"Yon flèch ta di ou chanje koulwa.","h2":"Lè yon tablo flèch montre yon ba oswa limyè nan kwen yo olye de yon flèch, li an mòd prekosyon: gen travay toupre wout la, kidonk ralanti epi fè atansyon.","p":"Se sa. Li vle di prekosyon, pa chanje koulwa."}},{"id":"signs-133","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"In a work zone, orange and white striped drums stand in a line that slants across your lane. What are they telling you?","o":["Drive between them","Follow them into the open lane","Stop at the first drum","Ignore them if no workers are present"],"h1":"Drums and cones guide traffic.","h2":"Orange and white drums placed across a lane guide you out of the closed lane, so follow their line into the open lane.","p":"Right. Follow the drums into the open lane."},"es":{"q":"En una zona de obras, barriles con rayas anaranjadas y blancas forman una línea en diagonal sobre su carril. ¿Qué le indican?","o":["Que maneje entre ellos","Que los siga hacia el carril abierto","Que se pare en el primer barril","Que los ignore si no hay trabajadores"],"h1":"Los barriles y conos guían el tráfico.","h2":"Los barriles anaranjados y blancos colocados sobre un carril lo guían fuera del carril cerrado, así que siga su línea hacia el carril abierto.","p":"Correcto. Siga los barriles hacia el carril abierto."},"zh":{"q":"在施工区，一排橙白条纹的圆桶斜着横过你的车道。它们在告诉你什么？","o":["从它们中间开过去","跟着它们进入开放的车道","在第一个圆桶前停车","如果没有工人，就不用管它们"],"h1":"圆桶和锥桶引导车辆。","h2":"橙白色圆桶斜放在车道上，是引导你离开封闭的车道，所以要沿着它们排成的线进入开放的车道。","p":"对。跟着圆桶进入开放的车道。"},"vi":{"q":"Trong khu vực thi công, các thùng sọc cam trắng đứng thành hàng chéo cắt ngang làn của bạn. Chúng đang bảo bạn điều gì?","o":["Lái xe đi giữa các thùng","Đi theo chúng vào làn đang mở","Dừng lại ở thùng đầu tiên","Không cần để ý nếu không có công nhân"],"h1":"Thùng và cọc nón hướng dẫn xe cộ.","h2":"Các thùng cam trắng đặt chéo qua một làn hướng dẫn bạn ra khỏi làn bị đóng, nên hãy đi theo hàng thùng vào làn đang mở.","p":"Đúng rồi. Đi theo hàng thùng vào làn đang mở."},"tl":{"q":"Sa work zone, may mga drum na may guhit na orange at puti na nakahanay nang pahilis sa linya mo. Ano ang sinasabi nila sa iyo?","o":["Magmaneho sa pagitan nila","Sundan sila papunta sa bukas na linya","Huminto sa unang drum","Huwag silang pansinin kung walang trabahador"],"h1":"Ginagabayan ng mga drum at cone ang trapiko.","h2":"Ang mga drum na orange at puti na nakalagay nang pahilis sa linya ay gumagabay sa iyo palabas ng saradong linya, kaya sundan ang hanay nila papunta sa bukas na linya.","p":"Tama. Sundan ang mga drum papunta sa bukas na linya."},"ar":{"q":"في منطقة عمل، براميل مخططة بالبرتقالي والأبيض مصفوفة في خط مائل يعبر مسارك. ماذا تخبرك؟","o":["قُد بينها","اتبعها إلى المسار المفتوح","توقف عند أول برميل","تجاهلها إذا لم يكن هناك عمال"],"h1":"البراميل والأقماع توجّه السيارات.","h2":"البراميل البرتقالية والبيضاء الموضوعة بشكل مائل عبر المسار توجّهك للخروج من المسار المغلق، لذلك اتبع خطها إلى المسار المفتوح.","p":"صحيح. اتبع البراميل إلى المسار المفتوح."},"ht":{"q":"Nan yon zòn travay, gen barik ak bann zoranj ak blan ki kanpe sou yon liy ki travèse koulwa ou an biyè. Kisa yo di ou?","o":["Kondui nan mitan yo","Swiv yo pou antre nan koulwa ki louvri a","Kanpe devan premye barik la","Pa okipe yo si pa gen travayè"],"h1":"Barik ak kòn yo gide sikilasyon an.","h2":"Barik zoranj ak blan ki mete an biyè sou yon koulwa gide ou soti nan koulwa ki fèmen an, kidonk swiv liy yo pou antre nan koulwa ki louvri a.","p":"Se sa. Swiv barik yo pou antre nan koulwa ki louvri a."}},{"id":"signs-134","scope":"US","cat":"signs","sign":{"shape":"diamond-orange","text":"BLASTING ZONE"},"c":2,"en":{"q":"Near a work zone, a sign says BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE. Why?","o":["Phones distract the workers","The noise will break your phone","Radio signals could set off the explosives","Phones do not work in work zones"],"h1":"Blasting uses explosives.","h2":"In a blasting zone you must turn off two-way radios and phones because their radio signals could set off the explosives.","p":"Right. Radio signals could set off a blast."},"es":{"q":"Cerca de una zona de obras, una señal dice BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE. ¿Por qué?","o":["Porque los teléfonos distraen a los trabajadores","Porque el ruido romperá su teléfono","Porque las señales de radio podrían activar los explosivos","Porque los teléfonos no funcionan en zonas de obras"],"h1":"En las voladuras (blasting) se usan explosivos.","h2":"En una zona de voladuras debe apagar los radios de dos vías y los teléfonos, porque sus señales de radio podrían activar los explosivos.","p":"Correcto. Las señales de radio podrían causar una explosión."},"zh":{"q":"在施工区附近，一个标志写着 “BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE”（爆破区，请关闭对讲机和手机）。为什么？","o":["手机会让工人分心","噪音会弄坏你的手机","无线电信号可能会引爆炸药","手机在施工区不能用"],"h1":"爆破要用炸药。","h2":"在爆破区你必须关掉对讲机和手机，因为它们的无线电信号可能会引爆炸药。","p":"对。无线电信号可能引起爆炸。"},"vi":{"q":"Gần khu vực thi công, một biển ghi “BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE” (Khu vực nổ mìn, tắt bộ đàm và điện thoại di động). Tại sao?","o":["Điện thoại làm công nhân mất tập trung","Tiếng ồn sẽ làm hỏng điện thoại của bạn","Sóng vô tuyến có thể làm thuốc nổ phát nổ","Điện thoại không dùng được trong khu vực thi công"],"h1":"Nổ mìn có dùng thuốc nổ.","h2":"Trong khu vực nổ mìn, bạn phải tắt bộ đàm và điện thoại vì sóng vô tuyến của chúng có thể làm thuốc nổ phát nổ.","p":"Đúng rồi. Sóng vô tuyến có thể gây ra vụ nổ."},"tl":{"q":"Malapit sa work zone, may karatulang nakasulat ang “BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE” (Lugar ng pagpapasabog, patayin ang two-way radio at cellphone). Bakit?","o":["Nakakaabala ang telepono sa mga trabahador","Masisira ng ingay ang telepono mo","Maaaring mapasabog ng radio signal ang mga pampasabog","Hindi gumagana ang telepono sa work zone"],"h1":"Gumagamit ng mga pampasabog ang blasting.","h2":"Sa blasting zone, dapat mong patayin ang two-way radio at telepono dahil maaaring mapasabog ng radio signal nila ang mga pampasabog.","p":"Tama. Maaaring magdulot ng pagsabog ang radio signal."},"ar":{"q":"قرب منطقة عمل، توجد لافتة مكتوب عليها «BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE» (منطقة تفجير، أطفئ جهاز اللاسلكي والهاتف المحمول). لماذا؟","o":["الهواتف تشتّت انتباه العمال","الضجيج سيكسر هاتفك","إشارات الراديو قد تفجّر المتفجرات","الهواتف لا تعمل في مناطق العمل"],"h1":"التفجير يستخدم المتفجرات.","h2":"في منطقة التفجير يجب أن تطفئ أجهزة اللاسلكي والهواتف، لأن إشاراتها قد تفجّر المتفجرات.","p":"صحيح. إشارات الراديو قد تسبب انفجارًا."},"ht":{"q":"Toupre yon zòn travay, yon siy di “BLASTING ZONE, TURN OFF 2-WAY RADIO AND CELL PHONE” (zòn eksplozyon, etenn radyo 2 bò ak telefòn selilè). Poukisa?","o":["Telefòn yo distrè travayè yo","Bri a ap kase telefòn ou","Siyal radyo ka fè eksplozif yo eksploze","Telefòn pa mache nan zòn travay"],"h1":"Yo itilize eksplozif pou fè eksplozyon.","h2":"Nan yon zòn eksplozyon, ou dwe etenn radyo 2 bò ak telefòn paske siyal radyo yo ka fè eksplozif yo eksploze.","p":"Se sa. Siyal radyo ka lakòz yon eksplozyon."}},{"id":"signs-135","scope":"US","cat":"signs","sign":null,"c":3,"en":{"q":"A flagger in a work zone holds a red flag straight out across your lane. What does it mean?","o":["Speed up","Turn left","Drive around the flagger","Stop"],"h1":"The flag blocks your lane.","h2":"When a flagger holds a red flag straight out across your lane, it means stop and wait until the flagger signals you to go.","p":"Right. A flag held across your lane means stop."},"es":{"q":"Un abanderado en una zona de obras sostiene una bandera roja extendida sobre su carril. ¿Qué significa?","o":["Acelere","Gire a la izquierda","Rodee al abanderado","Pare"],"h1":"La bandera bloquea su carril.","h2":"Cuando un abanderado sostiene una bandera roja extendida sobre su carril, significa que debe pararse y esperar hasta que le indique seguir.","p":"Correcto. La bandera sobre su carril significa pare."},"zh":{"q":"施工区的一名旗手把红旗平伸出来，挡在你的车道上。这是什么意思？","o":["加速","向左转","从旗手旁边绕过去","停车"],"h1":"旗子挡住了你的车道。","h2":"当旗手把红旗平伸出来挡在你的车道上时，意思是停车，等旗手示意你走。","p":"对。旗子挡在你的车道上表示停车。"},"vi":{"q":"Người cầm cờ điều khiển giao thông trong khu vực thi công giơ thẳng lá cờ đỏ ngang qua làn đường của bạn. Điều đó có nghĩa là gì?","o":["Tăng tốc","Rẽ trái","Lái vòng qua người cầm cờ","Dừng lại"],"h1":"Lá cờ chắn ngang làn đường của bạn.","h2":"Khi người cầm cờ giơ thẳng lá cờ đỏ ngang qua làn đường của bạn, điều đó có nghĩa là dừng lại và chờ tới khi người đó ra hiệu cho bạn đi.","p":"Đúng rồi. Lá cờ giơ ngang làn đường nghĩa là dừng lại."},"tl":{"q":"Sa work zone, may flagger na nakaunat ang pulang bandila nang diretso pahalang sa linya mo. Ano ang ibig sabihin nito?","o":["Bumilis","Kumaliwa","Umikot sa paligid ng flagger","Huminto"],"h1":"Hinaharangan ng bandila ang linya mo.","h2":"Kapag nakaunat nang diretso ang pulang bandila ng flagger pahalang sa linya mo, ibig sabihin ay huminto at maghintay hanggang senyasan ka ng flagger na umandar.","p":"Tama. Ang bandilang nakaharang sa linya mo ay nangangahulugang huminto."},"ar":{"q":"في منطقة عمل، عامل تنظيم السير يمدّ علمًا أحمر بشكل مستقيم عبر مسارك. ماذا يعني ذلك؟","o":["زد السرعة","انعطف يسارًا","قُد حول عامل تنظيم السير","توقف"],"h1":"العلم يسدّ مسارك.","h2":"عندما يمدّ عامل تنظيم السير علمًا أحمر بشكل مستقيم عبر مسارك، فهذا يعني أن تتوقف وتنتظر حتى يشير لك العامل بالمرور.","p":"صحيح. العلم الممدود عبر مسارك يعني: توقف."},"ht":{"q":"Nan yon zòn travay, yon travayè ki dirije trafik la kenbe yon drapo wouj tou dwat an travè koulwa ou. Kisa sa vle di?","o":["Akselere","Vire agoch","Kondui fè wonn travayè a","Kanpe"],"h1":"Drapo a bloke koulwa ou.","h2":"Lè travayè a kenbe yon drapo wouj tou dwat an travè koulwa ou, sa vle di kanpe epi tann jiskaske travayè a fè ou siy pou pase.","p":"Se sa. Yon drapo an travè koulwa ou vle di kanpe."}},{"id":"signs-136","scope":"US","cat":"signs","sign":null,"c":0,"en":{"q":"A flagger slowly waves a red flag up and down from the shoulder. What does it mean?","o":["Slow down and be careful","Stop and turn off your engine","Turn around","Pass the cars ahead"],"h1":"A waving flag is a warning, not a stop.","h2":"A flagger who slowly waves a flag down toward the road is telling you to slow down and drive with care.","p":"Right. A slowly waving flag means slow down."},"es":{"q":"Un abanderado mueve despacio una bandera roja de arriba hacia abajo desde el acotamiento. ¿Qué significa?","o":["Baje la velocidad y tenga cuidado","Párese y apague el motor","Dé la vuelta","Rebase a los carros de adelante"],"h1":"Una bandera que se mueve es una advertencia, no una orden de pararse.","h2":"Un abanderado que mueve despacio una bandera hacia abajo le está diciendo que baje la velocidad y maneje con cuidado.","p":"Correcto. La bandera que se mueve despacio significa bajar la velocidad."},"zh":{"q":"一名旗手站在路肩上，慢慢地上下挥动红旗。这是什么意思？","o":["减速，小心驾驶","停车并关掉引擎","掉头","超过前面的车"],"h1":"挥动的旗子是警告，不是叫你停车。","h2":"旗手把旗子慢慢地向路面往下挥动，是在告诉你要减速，小心驾驶。","p":"对。慢慢挥动的旗子表示减速。"},"vi":{"q":"Người cầm cờ điều khiển giao thông đứng ở lề đường, chậm rãi vẫy lá cờ đỏ lên xuống. Điều đó có nghĩa là gì?","o":["Chạy chậm lại và cẩn thận","Dừng lại và tắt máy xe","Quay đầu xe","Vượt các xe phía trước"],"h1":"Lá cờ được vẫy là lời cảnh báo, không phải lệnh dừng.","h2":"Người cầm cờ chậm rãi vẫy lá cờ xuống phía mặt đường là đang bảo bạn chạy chậm lại và lái cẩn thận.","p":"Đúng rồi. Cờ được vẫy chậm nghĩa là chạy chậm lại."},"tl":{"q":"Mula sa gilid ng kalsada (shoulder), dahan-dahang iwinawagayway ng flagger ang pulang bandila pataas at pababa. Ano ang ibig sabihin nito?","o":["Bumagal at mag-ingat","Huminto at patayin ang makina","Umikot pabalik","Lampasan ang mga sasakyan sa unahan"],"h1":"Babala ang iwinawagayway na bandila, hindi utos na huminto.","h2":"Ang flagger na dahan-dahang iwinawagayway ang bandila pababa sa kalsada ay nagsasabi sa iyo na bumagal at magmaneho nang maingat.","p":"Tama. Ang bandilang dahan-dahang iwinawagayway ay nangangahulugang bumagal."},"ar":{"q":"عامل تنظيم السير يقف على كتف الطريق ويحرّك علمًا أحمر ببطء إلى الأعلى والأسفل. ماذا يعني ذلك؟","o":["خفف السرعة وكن حذرًا","توقف وأطفئ المحرك","استدر عائدًا","تجاوز السيارات التي أمامك"],"h1":"العلم الذي يتحرك تحذير، وليس أمرًا بالتوقف.","h2":"عامل تنظيم السير الذي يحرّك العلم ببطء نحو الطريق يطلب منك أن تخفف السرعة وتقود بحذر.","p":"صحيح. العلم الذي يتحرك ببطء يعني: خفف السرعة."},"ht":{"q":"Yon travayè ki dirije trafik la sou bò wout la ap balanse yon drapo wouj dousman anlè anba. Kisa sa vle di?","o":["Ralanti epi fè atansyon","Kanpe epi etenn motè a","Vire tounen","Pase machin ki devan yo"],"h1":"Yon drapo k ap balanse se yon avètisman, se pa yon lòd pou kanpe.","h2":"Yon travayè ki balanse drapo a dousman desann bò wout la ap di ou ralanti epi kondui ak atansyon.","p":"Se sa. Yon drapo k ap balanse dousman vle di ralanti."}},{"id":"signs-137","scope":"US","cat":"signs","sign":null,"c":1,"en":{"q":"At the end of a road, you see a sign made of red reflectors. What does it mean?","o":["A fire station is ahead","The road ends here","A stop light is broken","Parking is allowed"],"h1":"Red often means stop.","h2":"An end-of-road marker with red reflectors means the road ends at that point, so you must stop before it.","p":"Right. The road ends here."},"es":{"q":"Al final de una vía, usted ve una señal hecha de reflectores rojos. ¿Qué significa?","o":["Que hay una estación de bomberos adelante","Que la vía termina aquí","Que un semáforo está dañado","Que se permite estacionar"],"h1":"El rojo suele significar pare.","h2":"Un marcador de fin de vía con reflectores rojos significa que la vía termina en ese punto, así que debe pararse antes.","p":"Correcto. La vía termina aquí."},"zh":{"q":"在一条路的尽头，你看到一个由红色反光片组成的标志。它是什么意思？","o":["前方有消防站","道路到这里结束","红绿灯坏了","可以停车"],"h1":"红色常常表示停。","h2":"带红色反光片的道路尽头标志表示道路在那里结束，所以你必须在它前面停车。","p":"对。道路在这里结束。"},"vi":{"q":"Ở cuối một con đường, bạn thấy một biển làm bằng các miếng phản quang màu đỏ. Biển này có nghĩa là gì?","o":["Phía trước có trạm cứu hỏa","Con đường kết thúc ở đây","Đèn giao thông bị hỏng","Được phép đậu xe"],"h1":"Màu đỏ thường có nghĩa là dừng.","h2":"Biển báo cuối đường có miếng phản quang màu đỏ nghĩa là con đường kết thúc ở chỗ đó, nên bạn phải dừng lại trước biển.","p":"Đúng rồi. Con đường kết thúc ở đây."},"tl":{"q":"Sa dulo ng isang kalsada, may nakita kang karatulang gawa sa pulang reflector. Ano ang ibig sabihin nito?","o":["May istasyon ng bumbero sa unahan","Dito nagtatapos ang kalsada","Sira ang stoplight","Puwedeng pumarada"],"h1":"Kadalasan, ang pula ay nangangahulugang huminto.","h2":"Ang end-of-road marker na may pulang reflector ay nangangahulugang doon nagtatapos ang kalsada, kaya dapat kang huminto bago ito.","p":"Tama. Dito nagtatapos ang kalsada."},"ar":{"q":"في نهاية طريق، ترى لافتة مصنوعة من عاكسات حمراء. ماذا تعني؟","o":["توجد محطة إطفاء في الأمام","الطريق ينتهي هنا","إشارة المرور معطّلة","الوقوف مسموح"],"h1":"اللون الأحمر غالبًا يعني التوقف.","h2":"علامة نهاية الطريق ذات العاكسات الحمراء تعني أن الطريق ينتهي عند تلك النقطة، لذلك يجب أن تتوقف قبلها.","p":"صحيح. الطريق ينتهي هنا."},"ht":{"q":"Nan bout yon wout, ou wè yon siy ki fèt ak reflektè wouj. Kisa li vle di?","o":["Gen yon estasyon ponpye pi devan","Wout la fini la a","Yon limyè trafik an pàn","Ou gen dwa pake"],"h1":"Wouj souvan vle di kanpe.","h2":"Yon siy bout wout ak reflektè wouj vle di wout la fini nan pwen sa a, kidonk ou dwe kanpe anvan li.","p":"Se sa. Wout la fini la a."}},{"id":"signs-138","scope":"US","cat":"signs","sign":{"shape":"one-way"},"c":2,"en":{"q":"You are about to turn onto a street. A ONE WAY sign at the corner has an arrow pointing to the right. Which way may you turn?","o":["Only to the left","Either way","Only to the right","You may not turn"],"h1":"Traffic on that street moves only in the arrow's direction.","h2":"A ONE WAY sign with an arrow to the right means traffic on that street moves only to the right, so you may only turn right onto it.","p":"Right. Turn the way the arrow points."},"es":{"q":"Usted va a girar hacia una calle. Una señal ONE WAY en la esquina tiene una flecha que apunta a la derecha. ¿Hacia dónde puede girar?","o":["Solo a la izquierda","A cualquier lado","Solo a la derecha","No puede girar"],"h1":"El tráfico de esa calle va solo en la dirección de la flecha.","h2":"Una señal ONE WAY con flecha a la derecha significa que el tráfico de esa calle va solo hacia la derecha, así que solo puede girar a la derecha.","p":"Correcto. Gire hacia donde apunta la flecha."},"zh":{"q":"你要转进一条街。街角的 “ONE WAY”（单行道）标志上有一个指向右边的箭头。你可以往哪边转？","o":["只能向左","两边都可以","只能向右","不能转"],"h1":"那条街上的车只能按箭头的方向走。","h2":"箭头指向右边的 “ONE WAY”（单行道）标志表示那条街上的车只能往右走，所以你只能向右转进去。","p":"对。按箭头指的方向转。"},"vi":{"q":"Bạn sắp rẽ vào một con đường. Biển “ONE WAY” (Một chiều) ở góc đường có mũi tên chỉ sang phải. Bạn được rẽ về hướng nào?","o":["Chỉ được rẽ trái","Hướng nào cũng được","Chỉ được rẽ phải","Bạn không được rẽ"],"h1":"Xe trên con đường đó chỉ chạy theo hướng mũi tên.","h2":"Biển “ONE WAY” có mũi tên chỉ sang phải nghĩa là xe trên con đường đó chỉ chạy về bên phải, nên bạn chỉ được rẽ phải vào đường đó.","p":"Đúng rồi. Rẽ theo hướng mũi tên chỉ."},"tl":{"q":"Liliko ka na papunta sa isang kalye. Ang “ONE WAY” na karatula (Isang direksyon) sa kanto ay may arrow na nakaturo pakanan. Saan ka puwedeng lumiko?","o":["Pakaliwa lang","Kahit saan sa dalawa","Pakanan lang","Hindi ka puwedeng lumiko"],"h1":"Ang trapiko sa kalyeng iyon ay dumadaloy lang sa direksyon ng arrow.","h2":"Ang “ONE WAY” na karatula na may arrow pakanan ay nangangahulugang pakanan lang dumadaloy ang trapiko sa kalyeng iyon, kaya pakanan ka lang puwedeng lumiko roon.","p":"Tama. Lumiko kung saan nakaturo ang arrow."},"ar":{"q":"أنت على وشك الانعطاف إلى شارع. على الزاوية لافتة «ONE WAY» (اتجاه واحد) عليها سهم يشير إلى اليمين. إلى أي جهة يُسمح لك بالانعطاف؟","o":["إلى اليسار فقط","إلى أي جهة","إلى اليمين فقط","يجب ألّا تنعطف"],"h1":"السيارات في ذلك الشارع تسير فقط في اتجاه السهم.","h2":"لافتة «ONE WAY» التي عليها سهم إلى اليمين تعني أن السيارات في ذلك الشارع تسير إلى اليمين فقط، لذلك يُسمح لك بالانعطاف إليه إلى اليمين فقط.","p":"صحيح. انعطف في الاتجاه الذي يشير إليه السهم."},"ht":{"q":"Ou pral vire nan yon lari. Yon siy “ONE WAY” (yon sèl direksyon) nan kwen an gen yon flèch ki montre adwat. Ki bò ou ka vire?","o":["Agoch sèlman","Nenpòt bò","Adwat sèlman","Ou pa ka vire"],"h1":"Machin nan lari sa a ale sèlman nan direksyon flèch la.","h2":"Yon siy “ONE WAY” ak yon flèch adwat vle di machin nan lari sa a ale adwat sèlman, kidonk ou ka vire adwat sèlman pou antre ladan l.","p":"Se sa. Vire bò flèch la montre a."}},{"id":"signs-139","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"BICYCLE"},"c":3,"en":{"q":"A yellow or yellow-green warning sign shows a bicycle. What does it mean?","o":["Bicycles are not allowed","A bike shop is ahead","Only bicycles may use the road","Bicycle riders may be on or crossing the road"],"h1":"This is a warning sign, not a rule.","h2":"A bicycle warning sign means people on bicycles may be riding on or crossing the road ahead, so watch for them and give them room.","p":"Right. Watch for bicycle riders."},"es":{"q":"Una señal de advertencia amarilla o amarillo verdosa muestra una bicicleta. ¿Qué significa?","o":["Que no se permiten bicicletas","Que hay una tienda de bicicletas","Que solo las bicicletas pueden usar la vía","Que puede haber ciclistas en la vía o cruzándola"],"h1":"Es una señal de advertencia, no una regla.","h2":"Una señal de advertencia con una bicicleta significa que puede haber ciclistas circulando o cruzando la vía adelante, así que fíjese en ellos y deles espacio.","p":"Correcto. Fíjese en los ciclistas."},"zh":{"q":"一个黄色或黄绿色的警告标志上画着一辆自行车。它是什么意思？","o":["不准骑自行车","前方有自行车店","这条路只准自行车走","可能有骑自行车的人在路上或正在过马路"],"h1":"这是警告标志，不是规定。","h2":"自行车警告标志表示前方可能有人在路上骑自行车或正在过马路，所以要注意他们，给他们留出空间。","p":"对。注意骑自行车的人。"},"vi":{"q":"Một biển cảnh báo màu vàng hoặc vàng chanh có hình xe đạp. Biển này có nghĩa là gì?","o":["Cấm xe đạp","Phía trước có tiệm xe đạp","Chỉ xe đạp mới được dùng con đường này","Có thể có người đi xe đạp trên đường hoặc đang băng qua đường"],"h1":"Đây là biển cảnh báo, không phải biển quy định.","h2":"Biển cảnh báo xe đạp nghĩa là phía trước có thể có người đi xe đạp trên đường hoặc đang băng qua đường, nên bạn cần để ý họ và chừa khoảng cách cho họ.","p":"Đúng rồi. Hãy để ý người đi xe đạp."},"tl":{"q":"May dilaw o dilaw-berdeng karatulang babala na may larawan ng bisikleta. Ano ang ibig sabihin nito?","o":["Bawal ang bisikleta","May tindahan ng bisikleta sa unahan","Bisikleta lang ang puwedeng gumamit ng kalsada","Maaaring may nagbibisikleta sa kalsada o tumatawid dito"],"h1":"Ito ay karatulang babala, hindi patakaran.","h2":"Ang karatulang babala na may bisikleta ay nangangahulugang maaaring may mga taong nagbibisikleta sa kalsada o tumatawid dito sa unahan, kaya bantayan sila at bigyan sila ng puwang.","p":"Tama. Bantayan ang mga nagbibisikleta."},"ar":{"q":"لافتة تحذير صفراء أو صفراء مخضرة تُظهر دراجة هوائية. ماذا تعني؟","o":["الدراجات الهوائية ممنوعة","يوجد محل دراجات في الأمام","الدراجات الهوائية فقط يمكنها استخدام الطريق","قد يكون راكبو الدراجات على الطريق أو يعبرونه"],"h1":"هذه لافتة تحذير، وليست قاعدة.","h2":"لافتة تحذير الدراجات تعني أن أشخاصًا على دراجات هوائية قد يسيرون على الطريق أو يعبرونه في الأمام، لذلك انتبه لهم واترك لهم مسافة.","p":"صحيح. انتبه لراكبي الدراجات."},"ht":{"q":"Yon siy avètisman jòn oswa jòn-vèt montre yon bisiklèt. Kisa li vle di?","o":["Bisiklèt pa gen dwa pase","Gen yon magazen bisiklèt pi devan","Se bisiklèt sèlman ki ka sèvi ak wout la","Ka gen moun sou bisiklèt sou wout la oswa k ap travèse l"],"h1":"Sa a se yon siy avètisman, se pa yon règ.","h2":"Yon siy avètisman bisiklèt vle di ka gen moun sou bisiklèt k ap woule sou wout la oswa k ap travèse l pi devan, kidonk veye yo epi ba yo espas.","p":"Se sa. Veye moun ki sou bisiklèt."}},{"id":"signs-140","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"CATTLE"},"c":0,"en":{"q":"A yellow sign shows a cow. What should you do?","o":["Watch for farm animals on or crossing the road","Look for a farm market","Honk to move animals off the road","Speed up through the area"],"h1":"Animals may be loose or herded across.","h2":"A cattle crossing sign warns that farm animals may be on or crossing the road, so slow down and be ready to stop.","p":"Right. Watch for animals on the road."},"es":{"q":"Una señal amarilla muestra una vaca. ¿Qué debe hacer?","o":["Estar atento a animales de granja en la vía o cruzándola","Buscar un mercado de granja","Tocar la bocina para sacar a los animales","Acelerar por la zona"],"h1":"Los animales pueden estar sueltos o cruzar en grupo.","h2":"Una señal de cruce de ganado advierte que puede haber animales de granja en la vía o cruzándola, así que baje la velocidad y esté listo para pararse.","p":"Correcto. Cuidado con los animales en la vía."},"zh":{"q":"一个黄色标志上画着一头牛。你应该怎么做？","o":["注意路上或正在过马路的家畜","找一找农产品市场","按喇叭把动物赶离道路","加速通过这个地区"],"h1":"动物可能是散放的，也可能有人赶着它们过马路。","h2":"牛群穿越标志提醒你家畜可能在路上或正在过马路，所以要减速，准备停车。","p":"对。注意路上的动物。"},"vi":{"q":"Một biển màu vàng có hình con bò. Bạn nên làm gì?","o":["Để ý gia súc trên đường hoặc đang băng qua đường","Tìm chợ nông sản","Bấm còi để đuổi thú vật ra khỏi đường","Tăng tốc chạy qua khu vực này"],"h1":"Thú vật có thể đi lang thang hoặc được lùa băng qua đường.","h2":"Biển báo gia súc băng qua đường cảnh báo rằng gia súc có thể ở trên đường hoặc đang băng qua đường, nên bạn cần chạy chậm lại và sẵn sàng dừng.","p":"Đúng rồi. Hãy để ý thú vật trên đường."},"tl":{"q":"May dilaw na karatula na may larawan ng baka. Ano ang dapat mong gawin?","o":["Bantayan ang mga hayop-bukid sa kalsada o tumatawid dito","Maghanap ng palengke ng ani mula sa bukid","Bumusina para paalisin ang mga hayop sa kalsada","Bumilis sa pagdaan sa lugar"],"h1":"Maaaring nakakawala ang mga hayop o pinapatawid sila.","h2":"Ang karatula ng tawiran ng baka ay babala na maaaring may mga hayop-bukid sa kalsada o tumatawid dito, kaya bumagal at maging handang huminto.","p":"Tama. Bantayan ang mga hayop sa kalsada."},"ar":{"q":"لافتة صفراء تُظهر بقرة. ماذا يجب أن تفعل؟","o":["انتبه لحيوانات المزرعة على الطريق أو التي تعبره","ابحث عن سوق للمزارعين","استخدم البوق لإبعاد الحيوانات عن الطريق","زد السرعة لتمرّ بسرعة من المنطقة"],"h1":"قد تكون الحيوانات طليقة أو يسوقها أحد عبر الطريق.","h2":"لافتة عبور الماشية تحذّر من أن حيوانات المزرعة قد تكون على الطريق أو تعبره، لذلك خفف السرعة وكن مستعدًا للتوقف.","p":"صحيح. انتبه للحيوانات على الطريق."},"ht":{"q":"Yon siy jòn montre yon bèf. Kisa ou dwe fè?","o":["Veye bèt fèm ki sou wout la oswa k ap travèse l","Chèche yon mache pwodwi fèm","Klaksonnen pou fè bèt yo soti sou wout la","Akselere pou travèse zòn nan"],"h1":"Bèt yo ka lage oswa gen moun k ap mennen yo travèse.","h2":"Yon siy travèse bèf avèti ou ka gen bèt fèm sou wout la oswa k ap travèse l, kidonk ralanti epi pare pou kanpe.","p":"Se sa. Veye bèt sou wout la."}},{"id":"signs-141","scope":"US","cat":"signs","sign":{"shape":"diamond-yellow","text":"SHOULDER DROP OFF"},"c":1,"en":{"q":"A yellow sign says SHOULDER DROP OFF. What does it warn about?","o":["The shoulder is a good place to stop","The edge of the road drops sharply lower than the pavement","Rocks may fall from above","The road becomes gravel"],"h1":"Drop off means a sudden step down.","h2":"SHOULDER DROP OFF warns that the ground at the edge is much lower than the pavement, so a wheel that drops off could make you lose control.","p":"Right. The edge drops lower than the road."},"es":{"q":"Una señal amarilla dice SHOULDER DROP OFF. ¿De qué advierte?","o":["De que el acotamiento es buen lugar para parar","De que la orilla de la vía está mucho más baja que el pavimento","De que pueden caer rocas","De que la vía se vuelve de grava"],"h1":"Drop off es un escalón repentino hacia abajo.","h2":"SHOULDER DROP OFF advierte que la orilla está mucho más baja que el pavimento, así que si una llanta se sale podría perder el control.","p":"Correcto. La orilla está más baja que la vía."},"zh":{"q":"一个黄色标志写着 “SHOULDER DROP OFF”（路肩落差）。它在提醒什么？","o":["路肩是停车的好地方","路边突然比路面低很多","上面可能会有落石","道路变成碎石路"],"h1":"落差的意思是突然往下低一截。","h2":"“SHOULDER DROP OFF”（路肩落差）提醒你路边的地面比路面低很多，所以车轮掉下去可能会让你失去控制。","p":"对。路边比路面低。"},"vi":{"q":"Một biển màu vàng ghi “SHOULDER DROP OFF” (Lề đường bị hạ thấp). Biển này cảnh báo điều gì?","o":["Lề đường là chỗ tốt để dừng xe","Mép đường bị hạ thấp đột ngột so với mặt đường","Đá có thể rơi từ trên cao xuống","Con đường chuyển thành đường sỏi"],"h1":"Hạ thấp nghĩa là có một bậc thụt xuống đột ngột.","h2":"“SHOULDER DROP OFF” cảnh báo rằng mặt đất ở mép đường thấp hơn mặt đường nhiều, nên nếu một bánh xe rơi xuống đó thì bạn có thể mất lái.","p":"Đúng rồi. Mép đường thấp hơn mặt đường."},"tl":{"q":"May dilaw na karatula na nakasulat ang “SHOULDER DROP OFF” (Biglang baba sa gilid ng kalsada). Ano ang ibinababala nito?","o":["Magandang huminto sa gilid ng kalsada","Biglang mas mababa ang gilid ng kalsada kaysa sa sementadong daan","Maaaring may mahulog na bato mula sa itaas","Nagiging graba ang kalsada"],"h1":"Ang drop off ay nangangahulugang biglang baba.","h2":"Ang “SHOULDER DROP OFF” ay babala na mas mababa nang husto ang lupa sa gilid kaysa sa sementadong daan, kaya kapag nahulog doon ang isang gulong, maaari kang mawalan ng kontrol.","p":"Tama. Mas mababa ang gilid kaysa sa kalsada."},"ar":{"q":"لافتة صفراء مكتوب عليها «SHOULDER DROP OFF» (انخفاض مفاجئ في كتف الطريق). مِمَّ تحذّر؟","o":["كتف الطريق مكان جيد للتوقف","حافة الطريق تنخفض فجأة أدنى بكثير من سطح الطريق","قد تسقط صخور من الأعلى","الطريق يصبح من الحصى"],"h1":"الانخفاض المفاجئ يعني درجة نازلة فجأة.","h2":"لافتة «SHOULDER DROP OFF» تحذّر من أن الأرض عند حافة الطريق أدنى بكثير من سطح الطريق، لذلك إذا نزلت عجلة عن الحافة فقد تفقد السيطرة على السيارة.","p":"صحيح. الحافة أدنى من سطح الطريق."},"ht":{"q":"Yon siy jòn di “SHOULDER DROP OFF” (bò wout la desann sou kote). Kisa li avèti ou?","o":["Bò wout la se yon bon kote pou kanpe","Rebò wout la desann pi ba anpil pase asfalt la toudenkou","Wòch ka tonbe sot anwo","Wout la vin tounen gravye"],"h1":"Drop off vle di yon desant toudenkou.","h2":"“SHOULDER DROP OFF” avèti ou tè a sou rebò a pi ba anpil pase asfalt la, kidonk si yon kawoutchou tonbe sou kote a, ou ka pèdi kontwòl.","p":"Se sa. Rebò a pi ba pase wout la."}},{"id":"speed-lanes-001","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, what is the speed limit in a business or residential area when no sign says otherwise?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Think of streets with homes and shops, where people walk a lot.","h2":"The speed limit in a Florida business or residential area is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas in Florida are 30 mph unless posted."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una zona comercial o residencial si no hay letrero que diga otra cosa?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Piense en calles con casas y tiendas, donde camina mucha gente.","h2":"El límite de velocidad en una zona comercial o residencial de Florida es 30 mph, a menos que un letrero indique otro límite.","p":"Correcto. En Florida, las zonas comerciales y residenciales son de 30 mph si no hay otro letrero."},"zh":{"q":"在 Florida，在商业区或住宅区，如果没有标志另外规定，限速是多少？","o":["25 英里/小时","35 英里/小时","30 英里/小时","40 英里/小时"],"h1":"想一想有住家和商店、很多人走路的街道。","h2":"在 Florida 的商业区或住宅区，限速是 30 英里/小时，除非有标志写着别的限速。","p":"对。Florida 的商业区和住宅区限速 30 英里/小时，除非另有标志。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư là bao nhiêu khi không có biển báo khác?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Hãy nghĩ đến những con đường có nhà ở và cửa hàng, nơi có nhiều người đi bộ.","h2":"Giới hạn tốc độ trong khu kinh doanh hoặc khu dân cư ở Florida là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu kinh doanh và khu dân cư ở Florida là 30 mph nếu không có biển báo khác."},"tl":{"q":"Sa Florida, ano ang speed limit sa lugar ng negosyo o tirahan kapag walang karatulang nagsasabi ng iba?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Isipin ang mga kalyeng may bahay at tindahan, kung saan maraming naglalakad.","h2":"Ang speed limit sa lugar ng negosyo o tirahan sa Florida ay 30 mph, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 30 mph ang limit sa mga lugar ng negosyo at tirahan sa Florida, maliban kung may nakapaskil na iba."},"ar":{"q":"في Florida، ما حد السرعة في منطقة تجارية أو سكنية عندما لا توجد علامة تقول غير ذلك؟","o":["25 ميلًا في الساعة","35 ميلًا في الساعة","30 ميلًا في الساعة","40 ميلًا في الساعة"],"h1":"فكّر في شوارع فيها بيوت ومحلات، ويمشي فيها الناس كثيرًا.","h2":"حد السرعة في المنطقة التجارية أو السكنية في Florida هو 30 ميلًا في الساعة، إلا إذا كانت هناك علامة تُظهر حدًا آخر.","p":"صحيح. في المناطق التجارية والسكنية في Florida الحد 30 ميلًا في الساعة، إلا إذا كُتب غير ذلك."},"ht":{"q":"Nan Florida, ki limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete, lè pa gen siy ki di lòt bagay?","o":["25 mph","35 mph","30 mph","40 mph"],"h1":"Panse ak lari ki gen kay ak magazen, kote anpil moun ap mache.","h2":"Limit vitès la nan yon zòn biznis oswa yon zòn kote moun rete nan Florida se 30 mph, sòf si yon siy montre yon lòt limit.","p":"Wi, se sa. Nan Florida, zòn biznis ak zòn kote moun rete se 30 mph, sòf si gen siy."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-002","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, what is the highest speed limit allowed on a rural interstate highway?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"This is the fastest limit you will see on any Florida road.","h2":"The top speed limit on a Florida rural interstate is 70 mph, and you must still follow the posted sign.","p":"Right. Rural interstates in Florida can be posted up to 70 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad más alto permitido en una autopista interestatal rural?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Es el límite más alto que verá en cualquier carretera de Florida.","h2":"El límite más alto en una interestatal rural de Florida es 70 mph, y siempre debe seguir el letrero que esté puesto.","p":"Correcto. Las interestatales rurales de Florida pueden tener un límite de hasta 70 mph."},"zh":{"q":"在 Florida，乡村州际公路上允许的最高限速是多少？","o":["70 英里/小时","65 英里/小时","75 英里/小时","60 英里/小时"],"h1":"这是你在 Florida 任何道路上会看到的最高限速。","h2":"Florida 乡村州际公路的最高限速是 70 英里/小时，而且你还是要遵守路上标出的限速。","p":"对。Florida 的乡村州际公路限速最高可以标到 70 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ cao nhất được phép trên xa lộ liên bang (interstate) ở vùng nông thôn là bao nhiêu?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Đây là giới hạn nhanh nhất bạn sẽ thấy trên mọi con đường ở Florida.","h2":"Giới hạn tốc độ cao nhất trên xa lộ liên bang vùng nông thôn ở Florida là 70 mph, và bạn vẫn phải theo biển báo trên đường.","p":"Đúng. Xa lộ liên bang vùng nông thôn ở Florida có thể có giới hạn đến 70 mph."},"tl":{"q":"Sa Florida, ano ang pinakamataas na speed limit na pinapayagan sa rural interstate highway (interstate sa labas ng lungsod)?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Ito ang pinakamabilis na limit na makikita mo sa anumang daan sa Florida.","h2":"Ang pinakamataas na speed limit sa rural interstate sa Florida ay 70 mph, at dapat mo pa ring sundin ang nakapaskil na karatula.","p":"Tama. Ang mga rural interstate sa Florida ay puwedeng may limit hanggang 70 mph."},"ar":{"q":"في Florida، ما أعلى حد سرعة مسموح به على طريق سريع بين الولايات (interstate) في منطقة ريفية؟","o":["70 ميلًا في الساعة","65 ميلًا في الساعة","75 ميلًا في الساعة","60 ميلًا في الساعة"],"h1":"هذا أعلى حد سرعة ستراه على أي طريق في Florida.","h2":"أعلى حد سرعة على طريق interstate ريفي في Florida هو 70 ميلًا في الساعة، ويجب أن تتبع أيضًا العلامة المكتوبة.","p":"صحيح. على طرق interstate الريفية في Florida يمكن أن يصل الحد المكتوب إلى 70 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès ki pi wo yo pèmèt sou yon gran wout entèeta (interstate) nan zòn andeyò?","o":["70 mph","65 mph","75 mph","60 mph"],"h1":"Se limit ki pi rapid ou ap wè sou nenpòt wout nan Florida.","h2":"Limit vitès ki pi wo sou yon gran wout entèeta nan zòn andeyò nan Florida se 70 mph, epi ou dwe toujou swiv siy ki afiche a.","p":"Wi, se sa. Gran wout entèeta nan zòn andeyò nan Florida ka gen yon limit jiska 70 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-003","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, what is the speed limit on a highway outside a city when no sign is posted?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"It is lower than the interstate limit, but higher than city streets.","h2":"When no speed limit sign is posted on a Florida highway outside a city, the limit is 55 mph.","p":"Right. With no sign on other Florida highways, the limit is 55 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad en una carretera fuera de la ciudad cuando no hay letrero?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Es más bajo que en la interestatal, pero más alto que en las calles de la ciudad.","h2":"Cuando no hay letrero de límite en una carretera de Florida fuera de la ciudad, el límite es 55 mph.","p":"Correcto. Sin letrero en otras carreteras de Florida, el límite es 55 mph."},"zh":{"q":"在 Florida，城市以外的公路上没有限速标志时，限速是多少？","o":["45 英里/小时","65 英里/小时","70 英里/小时","55 英里/小时"],"h1":"它比州际公路的限速低，但比城市街道高。","h2":"在 Florida 城市以外的公路上，如果没有限速标志，限速是 55 英里/小时。","p":"对。Florida 其他公路上没有标志时，限速是 55 英里/小时。"},"vi":{"q":"Ở Florida, giới hạn tốc độ trên xa lộ ngoài thành phố là bao nhiêu khi không có biển báo?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Nó thấp hơn giới hạn trên xa lộ liên bang, nhưng cao hơn đường trong thành phố.","h2":"Khi không có biển giới hạn tốc độ trên xa lộ ngoài thành phố ở Florida, giới hạn là 55 mph.","p":"Đúng. Không có biển báo trên các xa lộ khác ở Florida thì giới hạn là 55 mph."},"tl":{"q":"Sa Florida, ano ang speed limit sa highway sa labas ng lungsod kapag walang nakapaskil na karatula?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Mas mababa ito sa limit ng interstate, pero mas mataas sa mga kalye ng lungsod.","h2":"Kapag walang nakapaskil na speed limit sign sa highway ng Florida sa labas ng lungsod, 55 mph ang limit.","p":"Tama. Kapag walang karatula sa ibang highway sa Florida, 55 mph ang limit."},"ar":{"q":"في Florida، ما حد السرعة على طريق سريع خارج المدينة عندما لا توجد علامة؟","o":["45 ميلًا في الساعة","65 ميلًا في الساعة","70 ميلًا في الساعة","55 ميلًا في الساعة"],"h1":"هو أقل من حد طرق interstate، لكنه أعلى من حد شوارع المدينة.","h2":"عندما لا توجد علامة حد سرعة على طريق سريع خارج المدينة في Florida، يكون الحد 55 ميلًا في الساعة.","p":"صحيح. على الطرق السريعة الأخرى في Florida بدون علامة، الحد 55 ميلًا في الساعة."},"ht":{"q":"Nan Florida, ki limit vitès la sou yon gran wout deyò vil, lè pa gen okenn siy?","o":["45 mph","65 mph","70 mph","55 mph"],"h1":"Li pi ba pase limit gran wout entèeta a, men li pi wo pase lari nan vil.","h2":"Lè pa gen okenn siy limit vitès sou yon gran wout deyò vil nan Florida, limit la se 55 mph.","p":"Wi, se sa. Lè pa gen siy sou lòt gran wout nan Florida, limit la se 55 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-004","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, on an interstate where the speed limit is 70 mph, what is the lowest speed you may drive in good conditions?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Driving too slow on a fast road is also unsafe. There is a minimum.","h2":"On a Florida interstate posted at 70 mph, the minimum speed is 50 mph when the weather and traffic are normal.","p":"Right. The minimum speed on a 70 mph Florida interstate is 50 mph."},"es":{"q":"En Florida, en una interestatal con límite de 70 mph, ¿cuál es la velocidad más baja permitida con buenas condiciones?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Manejar muy despacio en una vía rápida también es peligroso. Hay un mínimo.","h2":"En una interestatal de Florida con límite de 70 mph, la velocidad mínima es 50 mph cuando el clima y el tráfico son normales.","p":"Correcto. La velocidad mínima en una interestatal de Florida de 70 mph es 50 mph."},"zh":{"q":"在 Florida，在限速 70 英里/小时的州际公路上，天气和路况好的时候，你最慢可以开多快？","o":["40 英里/小时","50 英里/小时","45 英里/小时","30 英里/小时"],"h1":"在快速道路上开得太慢也不安全。有一个最低速度。","h2":"在 Florida 限速 70 英里/小时的州际公路上，天气和交通正常时，最低速度是 50 英里/小时。","p":"对。Florida 限速 70 英里/小时的州际公路，最低速度是 50 英里/小时。"},"vi":{"q":"Ở Florida, trên xa lộ liên bang có giới hạn tốc độ 70 mph, tốc độ thấp nhất bạn được chạy khi điều kiện tốt là bao nhiêu?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Chạy quá chậm trên đường nhanh cũng không an toàn. Có một tốc độ tối thiểu.","h2":"Trên xa lộ liên bang ở Florida có giới hạn 70 mph, tốc độ tối thiểu là 50 mph khi thời tiết và giao thông bình thường.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang 70 mph ở Florida là 50 mph."},"tl":{"q":"Sa Florida, sa interstate na 70 mph ang speed limit, ano ang pinakamababang bilis na puwede mong takbuhin kapag maayos ang kondisyon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Delikado rin ang sobrang bagal sa mabilis na daan. May minimum.","h2":"Sa interstate sa Florida na 70 mph ang limit, 50 mph ang minimum na bilis kapag normal ang panahon at trapiko.","p":"Tama. 50 mph ang minimum na bilis sa interstate sa Florida na 70 mph ang limit."},"ar":{"q":"في Florida، على طريق interstate حد السرعة فيه 70 ميلًا في الساعة، ما أقل سرعة يمكنك أن تقود بها عندما تكون الظروف جيدة؟","o":["40 ميلًا في الساعة","50 ميلًا في الساعة","45 ميلًا في الساعة","30 ميلًا في الساعة"],"h1":"القيادة ببطء شديد على طريق سريع خطيرة أيضًا. هناك حد أدنى.","h2":"على طريق interstate في Florida حده المكتوب 70 ميلًا في الساعة، الحد الأدنى للسرعة هو 50 ميلًا في الساعة عندما يكون الطقس والسير عاديين.","p":"صحيح. الحد الأدنى على طريق interstate في Florida حده 70 ميلًا في الساعة هو 50 ميلًا في الساعة."},"ht":{"q":"Nan Florida, sou yon gran wout entèeta kote limit vitès la se 70 mph, ki vitès ki pi ba ou ka kondi lè kondisyon yo bon?","o":["40 mph","50 mph","45 mph","30 mph"],"h1":"Kondi twò dousman sou yon wout rapid danjere tou. Gen yon vitès minimòm.","h2":"Sou yon gran wout entèeta nan Florida ki gen limit 70 mph, vitès minimòm lan se 50 mph lè tan an ak sikilasyon an nòmal.","p":"Wi, se sa. Vitès minimòm sou yon gran wout entèeta 70 mph nan Florida se 50 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-005","scope":"FL","cat":"speed-lanes","sign":{"shape":"school","text":"SCHOOL"},"c":1,"en":{"q":"In Florida, when must you obey the lower speed limit in a school zone?","o":["Only when you see children on the road","When the lights flash or during the times shown on the sign","Only on Monday mornings","Only when a police car is nearby"],"h1":"Look at the sign. It tells you when the lower limit is active.","h2":"You must obey the school zone speed limit when its lights are flashing or during the hours shown on the sign, even if you do not see children.","p":"Right. Follow the school zone limit when the lights flash or during the posted times."},"es":{"q":"En Florida, ¿cuándo debe respetar el límite de velocidad más bajo en una zona escolar?","o":["Solo cuando ve niños en la calle","Cuando las luces parpadean o en las horas que indica el letrero","Solo los lunes por la mañana","Solo cuando hay un carro de policía cerca"],"h1":"Mire el letrero. Le dice cuándo aplica el límite más bajo.","h2":"Debe respetar el límite de la zona escolar cuando las luces parpadean o en las horas que indica el letrero, aunque no vea niños.","p":"Correcto. Respete el límite escolar cuando las luces parpadean o en las horas indicadas."},"zh":{"q":"在 Florida，什么时候必须遵守学校区较低的限速？","o":["只有看到路上有小孩时","灯在闪的时候，或标志上写的时间内","只在星期一早上","只有附近有警车时"],"h1":"看标志。它会告诉你较低的限速什么时候生效。","h2":"当学校区的灯在闪，或在标志上写的时间内，你必须遵守学校区限速，就算你没看到小孩也一样。","p":"对。灯在闪或在标出的时间内，要遵守学校区限速。"},"vi":{"q":"Ở Florida, khi nào bạn phải tuân theo giới hạn tốc độ thấp hơn trong khu vực trường học?","o":["Chỉ khi bạn thấy trẻ em trên đường","Khi đèn nháy hoặc trong khung giờ ghi trên biển báo","Chỉ vào sáng thứ Hai","Chỉ khi có xe cảnh sát gần đó"],"h1":"Hãy nhìn biển báo. Biển cho bạn biết khi nào giới hạn thấp hơn có hiệu lực.","h2":"Bạn phải tuân theo giới hạn tốc độ khu vực trường học khi đèn đang nháy hoặc trong khung giờ ghi trên biển, kể cả khi bạn không thấy trẻ em.","p":"Đúng. Hãy theo giới hạn khu vực trường học khi đèn nháy hoặc trong giờ ghi trên biển."},"tl":{"q":"Sa Florida, kailan mo dapat sundin ang mas mababang speed limit sa school zone?","o":["Kapag may nakikita ka lang na mga bata sa daan","Kapag kumikislap ang mga ilaw o sa mga oras na nakasulat sa karatula","Tuwing Lunes ng umaga lang","Kapag may kotse lang ng pulis sa malapit"],"h1":"Tingnan ang karatula. Sinasabi nito kung kailan umiiral ang mas mababang limit.","h2":"Dapat mong sundin ang speed limit sa school zone kapag kumikislap ang mga ilaw nito o sa mga oras na nakasulat sa karatula, kahit wala kang nakikitang bata.","p":"Tama. Sundin ang limit sa school zone kapag kumikislap ang ilaw o sa mga nakapaskil na oras."},"ar":{"q":"في Florida، متى يجب أن تلتزم بحد السرعة الأقل في منطقة المدرسة؟","o":["فقط عندما أرى أطفالًا في الطريق","عندما تومض الأضواء أو في الأوقات المكتوبة على العلامة","فقط صباح يوم الاثنين","فقط عندما تكون سيارة شرطة قريبة"],"h1":"انظر إلى العلامة. هي تخبرك متى يبدأ العمل بالحد الأقل.","h2":"يجب أن تلتزم بحد السرعة في منطقة المدرسة عندما تومض أضواؤها أو في الساعات المكتوبة على العلامة، حتى لو لم ترَ أطفالًا.","p":"صحيح. اتبع حد منطقة المدرسة عندما تومض الأضواء أو في الأوقات المكتوبة."},"ht":{"q":"Nan Florida, kilè ou dwe respekte limit vitès ki pi ba a nan yon zòn lekòl?","o":["Sèlman lè ou wè timoun sou wout la","Lè limyè yo ap flache oswa pandan lè ki ekri sou siy la","Sèlman lendi maten","Sèlman lè gen yon machin polis tou pre"],"h1":"Gade siy la. Li di ou kilè limit ki pi ba a an vigè.","h2":"Ou dwe respekte limit vitès zòn lekòl la lè limyè li yo ap flache oswa pandan lè ki ekri sou siy la, menm si ou pa wè timoun.","p":"Wi, se sa. Swiv limit zòn lekòl la lè limyè yo ap flache oswa pandan lè ki ekri sou siy la."},"ref":{"doc":"FL","page":57}},{"id":"speed-lanes-006","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is raining hard and you are on a road posted at 55 mph. How fast should you drive?","o":["Exactly 55 mph, because that is the limit","A little faster than 55 mph to get out of the rain","Any speed, because rain does not change the rules","Slower than 55 mph, at a speed that is safe for the rain"],"h1":"A speed limit is the most you may drive in good conditions.","h2":"You must never drive faster than is safe for the conditions, so in heavy rain you should drive slower than the posted 55 mph.","p":"Right. In bad weather, slow down below the limit to a safe speed."},"es":{"q":"En Florida, está lloviendo fuerte y usted va por una carretera con límite de 55 mph. ¿A qué velocidad debe manejar?","o":["Exactamente a 55 mph, porque ese es el límite","Un poco más rápido que 55 mph para salir de la lluvia","A cualquier velocidad, porque la lluvia no cambia las reglas","Más despacio que 55 mph, a una velocidad segura para la lluvia"],"h1":"El límite de velocidad es lo máximo que puede manejar con buenas condiciones.","h2":"Nunca debe manejar más rápido de lo que es seguro para las condiciones, así que con lluvia fuerte debe ir más despacio que 55 mph.","p":"Correcto. Con mal clima, baje la velocidad por debajo del límite a una velocidad segura."},"zh":{"q":"在 Florida，雨下得很大，你在一条限速 55 英里/小时的路上。你应该开多快？","o":["正好 55 英里/小时，因为那是限速","比 55 英里/小时快一点，好赶快离开大雨","什么速度都行，因为下雨不改变规则","比 55 英里/小时慢，用适合下雨的安全速度"],"h1":"限速是路况好的时候你最多可以开的速度。","h2":"你永远不能开得比路况允许的安全速度更快，所以下大雨时，你应该开得比标出的 55 英里/小时更慢。","p":"对。天气不好时，要减速到低于限速的安全速度。"},"vi":{"q":"Ở Florida, trời đang mưa to và bạn đang chạy trên đường có biển giới hạn 55 mph. Bạn nên chạy nhanh bao nhiêu?","o":["Đúng 55 mph, vì đó là giới hạn","Nhanh hơn 55 mph một chút để ra khỏi cơn mưa","Tốc độ nào cũng được, vì mưa không thay đổi luật","Chậm hơn 55 mph, ở tốc độ an toàn khi trời mưa"],"h1":"Giới hạn tốc độ là mức cao nhất bạn được chạy khi điều kiện tốt.","h2":"Bạn không bao giờ được chạy nhanh hơn mức an toàn cho điều kiện lúc đó, nên khi mưa to bạn nên chạy chậm hơn 55 mph ghi trên biển.","p":"Đúng. Khi thời tiết xấu, hãy giảm tốc xuống dưới giới hạn đến mức an toàn."},"tl":{"q":"Sa Florida, malakas ang ulan at nasa daan ka na 55 mph ang nakapaskil na limit. Gaano ka kabilis dapat magmaneho?","o":["Eksaktong 55 mph, dahil iyon ang limit","Medyo mas mabilis sa 55 mph para makaalis sa ulan","Kahit anong bilis, dahil hindi binabago ng ulan ang patakaran","Mas mabagal sa 55 mph, sa bilis na ligtas sa ulan"],"h1":"Ang speed limit ay ang pinakamabilis na puwede mong takbuhin kapag maayos ang kondisyon.","h2":"Hindi ka dapat kailanman magmaneho nang mas mabilis kaysa sa ligtas para sa kondisyon, kaya sa malakas na ulan dapat kang magmaneho nang mas mabagal sa nakapaskil na 55 mph.","p":"Tama. Kapag masama ang panahon, bumagal sa ilalim ng limit, sa ligtas na bilis."},"ar":{"q":"في Florida، المطر شديد وأنت على طريق حده المكتوب 55 ميلًا في الساعة. بأي سرعة يجب أن تقود؟","o":["55 ميلًا في الساعة بالضبط، لأن هذا هو الحد","أسرع قليلًا من 55 ميلًا في الساعة لأخرج من المطر","بأي سرعة، لأن المطر لا يغيّر القواعد","أبطأ من 55 ميلًا في الساعة، بسرعة آمنة في المطر"],"h1":"حد السرعة هو أعلى سرعة مسموحة عندما تكون الظروف جيدة.","h2":"لا يجوز أبدًا أن تقود أسرع مما هو آمن في الظروف الموجودة، لذلك في المطر الشديد يجب أن تقود أبطأ من الحد المكتوب 55 ميلًا في الساعة.","p":"صحيح. في الطقس السيئ، خفف السرعة إلى أقل من الحد، إلى سرعة آمنة."},"ht":{"q":"Nan Florida, lapli ap tonbe fò epi ou sou yon wout ki gen limit 55 mph. Ak ki vitès ou ta dwe kondi?","o":["Egzakteman 55 mph, paske se limit la","Yon ti kras pi vit pase 55 mph pou sòti anba lapli a","Nenpòt vitès, paske lapli pa chanje règ yo","Pi dousman pase 55 mph, a yon vitès ki san danje pou lapli a"],"h1":"Yon limit vitès se maksimòm ou ka kondi lè kondisyon yo bon.","h2":"Ou pa dwe janm kondi pi vit pase sa ki san danje pou kondisyon yo, kidonk lè gen gwo lapli ou ta dwe kondi pi dousman pase 55 mph ki afiche a.","p":"Wi, se sa. Lè tan an move, desann anba limit la pou yon vitès ki san danje."},"ref":{"doc":"FL","page":null}},{"id":"speed-lanes-007","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you get a ticket for driving too slowly?","o":["Yes, if you block the normal flow of traffic","No, driving slowly is always legal","Only if you drive slower than 10 mph","Only on dirt roads"],"h1":"Think about what happens to the cars behind a very slow driver.","h2":"Yes. In Florida you can get a ticket if you drive so slowly that you block the normal and safe flow of traffic.","p":"Right. Driving so slowly that you block traffic is against the law."},"es":{"q":"En Florida, ¿le pueden dar una multa por manejar demasiado despacio?","o":["Sí, si bloquea el flujo normal del tráfico","No, manejar despacio siempre es legal","Solo si maneja a menos de 10 mph","Solo en caminos de tierra"],"h1":"Piense en lo que les pasa a los carros que van detrás de alguien muy lento.","h2":"Sí. En Florida le pueden poner una multa si maneja tan despacio que bloquea el flujo normal y seguro del tráfico.","p":"Correcto. Manejar tan despacio que bloquea el tráfico va contra la ley."},"zh":{"q":"在 Florida，开得太慢会被开罚单吗？","o":["会，如果你挡住了正常的车流","不会，开得慢永远是合法的","只有开得比 10 英里/小时还慢时才会","只在土路上才会"],"h1":"想一想，跟在很慢的司机后面的车会怎么样。","h2":"会。在 Florida，如果你开得太慢，挡住了正常、安全的车流，你可能会被开罚单。","p":"对。开得太慢、挡住车流是违法的。"},"vi":{"q":"Ở Florida, bạn có thể bị phạt vì lái xe quá chậm không?","o":["Có, nếu bạn cản trở dòng xe bình thường","Không, lái chậm luôn hợp pháp","Chỉ khi bạn chạy chậm hơn 10 mph","Chỉ trên đường đất"],"h1":"Hãy nghĩ xem chuyện gì xảy ra với các xe phía sau một người lái rất chậm.","h2":"Có. Ở Florida bạn có thể bị phạt nếu lái chậm đến mức cản trở dòng xe bình thường và an toàn.","p":"Đúng. Lái chậm đến mức cản trở giao thông là trái luật."},"tl":{"q":"Sa Florida, puwede ka bang matiketan dahil sa sobrang bagal na pagmamaneho?","o":["Oo, kung naharangan mo ang normal na daloy ng trapiko","Hindi, laging legal ang mabagal na pagmamaneho","Kung mas mabagal ka lang sa 10 mph","Sa mga daang lupa lang"],"h1":"Isipin ang nangyayari sa mga kotse sa likod ng sobrang bagal na drayber.","h2":"Oo. Sa Florida, puwede kang matiketan kung napakabagal mong magmaneho na naharangan mo ang normal at ligtas na daloy ng trapiko.","p":"Tama. Labag sa batas ang sobrang bagal na pagmamaneho na humaharang sa trapiko."},"ar":{"q":"في Florida، هل يمكن أن تحصل على مخالفة لأنك تقود ببطء شديد؟","o":["نعم، إذا كنت أعيق حركة السير العادية","لا، القيادة البطيئة مسموحة دائمًا","فقط إذا كنت أقود أبطأ من 10 أميال في الساعة","فقط على الطرق الترابية"],"h1":"فكّر ماذا يحدث للسيارات التي خلف سائق بطيء جدًا.","h2":"نعم. في Florida يمكن أن تحصل على مخالفة إذا كنت تقود ببطء شديد حتى تعيق حركة السير العادية والآمنة.","p":"صحيح. القيادة ببطء شديد حتى تعيق السير مخالفة للقانون."},"ht":{"q":"Nan Florida, èske ou ka pran yon kontravansyon paske ou kondi twò dousman?","o":["Wi, si ou bloke sikilasyon nòmal la","Non, kondi dousman toujou legal","Sèlman si ou kondi pi dousman pase 10 mph","Sèlman sou wout tè"],"h1":"Panse ak sa k ap rive machin ki dèyè yon chofè ki kondi trè dousman.","h2":"Wi. Nan Florida ou ka pran yon kontravansyon si ou kondi tèlman dousman ou bloke sikilasyon nòmal ki san danje a.","p":"Wi, se sa. Kondi tèlman dousman ou bloke sikilasyon an se kont lalwa."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-008","scope":"US","cat":"speed-lanes","sign":{"shape":"rect-white","text":"SPEED LIMIT 55"},"c":2,"en":{"q":"What does this white sign tell you?","o":["You must drive exactly 55 mph","The slowest speed allowed is 55 mph","The fastest speed allowed in good conditions is 55 mph","The suggested speed for a curve is 55 mph"],"h1":"White signs with black letters are rules. Is this number a top or a bottom?","h2":"A white speed limit sign shows the highest legal speed when conditions are good, so you may not drive faster than 55 mph there.","p":"Right. The speed limit sign shows the top legal speed in good conditions."},"es":{"q":"¿Qué le indica este letrero blanco?","o":["Debe manejar exactamente a 55 mph","La velocidad más baja permitida es 55 mph","La velocidad más alta permitida con buenas condiciones es 55 mph","La velocidad sugerida para una curva es 55 mph"],"h1":"Los letreros blancos con letras negras son reglas. ¿Este número es un máximo o un mínimo?","h2":"Un letrero blanco de límite de velocidad muestra la velocidad legal más alta con buenas condiciones, así que no puede manejar a más de 55 mph allí.","p":"Correcto. El letrero de límite muestra la velocidad legal más alta con buenas condiciones."},"zh":{"q":"这个白色标志告诉你什么？","o":["你必须正好开 55 英里/小时","允许的最低速度是 55 英里/小时","路况好时允许的最高速度是 55 英里/小时","弯道的建议速度是 55 英里/小时"],"h1":"白底黑字的标志是规定。这个数字是最高还是最低？","h2":"白色的限速标志显示路况好时的最高合法速度，所以在那里你不能开得比 55 英里/小时更快。","p":"对。限速标志显示路况好时的最高合法速度。"},"vi":{"q":"Biển báo màu trắng này cho bạn biết điều gì?","o":["Bạn phải chạy đúng 55 mph","Tốc độ chậm nhất được phép là 55 mph","Tốc độ nhanh nhất được phép khi điều kiện tốt là 55 mph","Tốc độ đề nghị khi vào khúc cua là 55 mph"],"h1":"Biển trắng chữ đen là luật. Con số này là mức cao nhất hay thấp nhất?","h2":"Biển trắng \"SPEED LIMIT\" (Giới hạn tốc độ) cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt, nên ở đó bạn không được chạy nhanh hơn 55 mph.","p":"Đúng. Biển \"SPEED LIMIT\" cho biết tốc độ hợp pháp cao nhất khi điều kiện tốt."},"tl":{"q":"Ano ang sinasabi sa iyo ng puting karatulang ito?","o":["Dapat kang magmaneho nang eksaktong 55 mph","Ang pinakamabagal na pinapayagang bilis ay 55 mph","Ang pinakamabilis na pinapayagang bilis kapag maayos ang kondisyon ay 55 mph","Ang iminumungkahing bilis sa kurbada ay 55 mph"],"h1":"Ang mga puting karatulang may itim na letra ay mga patakaran. Pinakamataas ba o pinakamababa ang numerong ito?","h2":"Ang puting speed limit sign ay nagpapakita ng pinakamataas na legal na bilis kapag maayos ang kondisyon, kaya hindi ka puwedeng magmaneho nang mas mabilis sa 55 mph doon.","p":"Tama. Ipinapakita ng speed limit sign ang pinakamataas na legal na bilis kapag maayos ang kondisyon."},"ar":{"q":"ماذا تخبرك هذه العلامة البيضاء؟","o":["يجب أن أقود بسرعة 55 ميلًا في الساعة بالضبط","أقل سرعة مسموحة هي 55 ميلًا في الساعة","أعلى سرعة مسموحة في الظروف الجيدة هي 55 ميلًا في الساعة","السرعة المقترحة للمنعطف هي 55 ميلًا في الساعة"],"h1":"العلامات البيضاء ذات الحروف السوداء هي قواعد. هل هذا الرقم حد أعلى أم حد أدنى؟","h2":"علامة \"SPEED LIMIT\" (حد السرعة) البيضاء تُظهر أعلى سرعة قانونية عندما تكون الظروف جيدة، لذلك لا يجوز أن تقود هناك أسرع من 55 ميلًا في الساعة.","p":"صحيح. علامة حد السرعة تُظهر أعلى سرعة قانونية في الظروف الجيدة."},"ht":{"q":"Kisa siy blan sa a di ou?","o":["Ou dwe kondi egzakteman 55 mph","Vitès ki pi dousman yo pèmèt la se 55 mph","Vitès ki pi rapid yo pèmèt lè kondisyon yo bon an se 55 mph","Vitès yo konseye pou yon koub se 55 mph"],"h1":"Siy blan ak lèt nwa se règ. Èske chif sa a se yon maksimòm oswa yon minimòm?","h2":"Yon siy limit vitès blan montre vitès legal ki pi wo a lè kondisyon yo bon, kidonk ou pa ka kondi pi vit pase 55 mph la.","p":"Wi, se sa. Siy limit vitès la montre vitès legal ki pi wo a lè kondisyon yo bon."},"ref":{"doc":"FL","page":47}},{"id":"speed-lanes-009","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"What is a good way to check if you are following too closely?","o":["Count the car lengths in your mirror","Watch the speed of the car behind you","Count the seconds after the car ahead passes a fixed object","Check if you can read the license plate ahead"],"h1":"Pick something that does not move, like a sign or a pole.","h2":"When the car ahead passes a fixed object, count the seconds until you reach it, and if you reach it too soon, you are following too closely.","p":"Right. Counting seconds past a fixed object shows your following distance."},"es":{"q":"¿Cuál es una buena forma de saber si va demasiado cerca del carro de adelante?","o":["Contar los largos de carro en el espejo","Mirar la velocidad del carro que va detrás","Contar los segundos después de que el carro de adelante pasa un objeto fijo","Ver si puede leer la placa del carro de adelante"],"h1":"Escoja algo que no se mueva, como un letrero o un poste.","h2":"Cuando el carro de adelante pasa un objeto fijo, cuente los segundos hasta que usted llegue allí; si llega muy pronto, va demasiado cerca.","p":"Correcto. Contar segundos desde un objeto fijo muestra su distancia de seguimiento."},"zh":{"q":"用什么好方法可以检查你是不是跟车太近？","o":["在后视镜里数有几个车身长度","看你后面那辆车的速度","前车经过一个固定的东西后，数几秒","看你能不能看清前车的车牌"],"h1":"选一个不会动的东西，比如一个标志或一根柱子。","h2":"当前车经过一个固定的东西时，数一数你几秒后到达那里，如果你太快就到了，说明你跟车太近。","p":"对。数经过固定物体的秒数，就能知道你的跟车距离。"},"vi":{"q":"Cách nào tốt để kiểm tra xem bạn có đang chạy quá sát xe phía trước không?","o":["Đếm số chiều dài xe trong gương","Xem tốc độ của xe phía sau bạn","Đếm số giây sau khi xe phía trước chạy qua một vật đứng yên","Xem bạn có đọc được biển số xe phía trước không"],"h1":"Hãy chọn một vật không di chuyển, như biển báo hoặc cột điện.","h2":"Khi xe phía trước chạy qua một vật đứng yên, bạn đếm số giây cho đến khi bạn đến vật đó, và nếu bạn đến quá sớm thì bạn đang chạy quá sát.","p":"Đúng. Đếm số giây qua một vật đứng yên cho biết khoảng cách của bạn với xe trước."},"tl":{"q":"Ano ang magandang paraan para malaman kung masyado kang malapit sa sinusundan mo?","o":["Bilangin ang haba ng mga kotse sa salamin mo","Bantayan ang bilis ng kotse sa likod mo","Bilangin ang mga segundo matapos dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw","Tingnan kung nababasa mo ang plaka sa unahan"],"h1":"Pumili ng bagay na hindi gumagalaw, gaya ng karatula o poste.","h2":"Kapag dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw, bilangin ang mga segundo hanggang marating mo ito, at kung masyadong maaga mo itong narating, masyado kang malapit.","p":"Tama. Ipinapakita ng pagbilang ng segundo sa isang bagay na hindi gumagalaw ang layo mo sa sinusundan."},"ar":{"q":"ما الطريقة الجيدة لتعرف إن كنت تقترب كثيرًا من السيارة التي أمامك؟","o":["أعدّ أطوال السيارات في المرآة","أراقب سرعة السيارة التي خلفي","أعدّ الثواني بعد أن تمر السيارة التي أمامي بجانب شيء ثابت","أرى إن كنت أستطيع قراءة لوحة السيارة التي أمامي"],"h1":"اختر شيئًا لا يتحرك، مثل علامة أو عمود.","h2":"عندما تمر السيارة التي أمامك بجانب شيء ثابت، عدّ الثواني حتى تصل أنت إليه، وإذا وصلت إليه بسرعة كبيرة، فأنت قريب جدًا منها.","p":"صحيح. عدّ الثواني بعد شيء ثابت يُظهر لك مسافة الأمان خلف السيارة."},"ht":{"q":"Ki bon fason pou tcheke si w ap swiv twò pre?","o":["Konte longè machin nan retwovizè ou","Gade vitès machin ki dèyè ou a","Konte segonn yo apre machin devan an fin pase yon bagay ki pa bouje","Tcheke si ou ka li plak machin devan an"],"h1":"Chwazi yon bagay ki pa bouje, tankou yon siy oswa yon poto.","h2":"Lè machin devan an pase yon bagay ki pa bouje, konte segonn yo jiskaske ou rive la, epi si ou rive twò vit, sa vle di w ap swiv twò pre.","p":"Wi, se sa. Konte segonn apre yon bagay ki pa bouje montre distans ou kite dèyè lòt machin nan."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-010","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"When should you leave more space between you and the car ahead?","o":["When the road is wet or slippery","When the road is dry and clear","When you are driving slower than usual in town","When the car ahead is a small car"],"h1":"Think about when your car needs more distance to stop.","h2":"You should leave more space when the road is wet or slippery, because your car needs a longer distance to stop.","p":"Right. On wet or slippery roads, leave extra space ahead."},"es":{"q":"¿Cuándo debe dejar más espacio entre usted y el carro de adelante?","o":["Cuando la carretera está mojada o resbalosa","Cuando la carretera está seca y despejada","Cuando maneja más despacio de lo normal en la ciudad","Cuando el carro de adelante es pequeño"],"h1":"Piense en cuándo su carro necesita más distancia para frenar.","h2":"Debe dejar más espacio cuando la carretera está mojada o resbalosa, porque su carro necesita más distancia para detenerse.","p":"Correcto. En carretera mojada o resbalosa, deje más espacio adelante."},"zh":{"q":"什么时候你应该和前车留更多距离？","o":["路面湿或滑的时候","路面干燥、视线清楚的时候","在城里开得比平时慢的时候","前车是小车的时候"],"h1":"想一想，什么时候你的车需要更长的距离才能停下。","h2":"路面湿或滑时，你应该留更多距离，因为你的车需要更长的距离才能停下。","p":"对。路面湿或滑时，和前车多留一些距离。"},"vi":{"q":"Khi nào bạn nên để khoảng cách lớn hơn giữa bạn và xe phía trước?","o":["Khi đường ướt hoặc trơn","Khi đường khô và thông thoáng","Khi bạn chạy chậm hơn thường lệ trong thành phố","Khi xe phía trước là xe nhỏ"],"h1":"Hãy nghĩ xem khi nào xe của bạn cần quãng đường dài hơn để dừng lại.","h2":"Bạn nên để khoảng cách lớn hơn khi đường ướt hoặc trơn, vì xe của bạn cần quãng đường dài hơn để dừng lại.","p":"Đúng. Khi đường ướt hoặc trơn, hãy để thêm khoảng cách phía trước."},"tl":{"q":"Kailan ka dapat mag-iwan ng mas malaking espasyo sa pagitan mo at ng kotse sa unahan?","o":["Kapag basa o madulas ang daan","Kapag tuyo at malinis ang daan","Kapag mas mabagal ka kaysa karaniwan sa bayan","Kapag maliit na kotse ang nasa unahan"],"h1":"Isipin kung kailan kailangan ng kotse mo ng mas mahabang layo para huminto.","h2":"Dapat kang mag-iwan ng mas malaking espasyo kapag basa o madulas ang daan, dahil kailangan ng kotse mo ng mas mahabang layo para huminto.","p":"Tama. Sa basa o madulas na daan, mag-iwan ng dagdag na espasyo sa unahan."},"ar":{"q":"متى يجب أن تترك مسافة أكبر بينك وبين السيارة التي أمامك؟","o":["عندما يكون الطريق مبللًا أو زلقًا","عندما يكون الطريق جافًا وواضحًا","عندما أقود في المدينة أبطأ من العادة","عندما تكون السيارة التي أمامي صغيرة"],"h1":"فكّر متى تحتاج سيارتك إلى مسافة أكبر لتتوقف.","h2":"يجب أن تترك مسافة أكبر عندما يكون الطريق مبللًا أو زلقًا، لأن سيارتك تحتاج إلى مسافة أطول لتتوقف.","p":"صحيح. على الطرق المبللة أو الزلقة، اترك مسافة إضافية أمامك."},"ht":{"q":"Kilè ou ta dwe kite plis espas ant ou ak machin ki devan ou a?","o":["Lè wout la mouye oswa li glise","Lè wout la sèk epi li klè","Lè w ap kondi pi dousman pase dabitid nan vil","Lè machin devan an se yon ti machin"],"h1":"Panse ak kilè machin ou bezwen plis distans pou l kanpe.","h2":"Ou ta dwe kite plis espas lè wout la mouye oswa li glise, paske machin ou bezwen yon distans pi long pou l kanpe.","p":"Wi, se sa. Sou wout ki mouye oswa ki glise, kite plis espas devan ou."},"ref":{"doc":"FL","page":61}},{"id":"speed-lanes-011","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Your total stopping distance is made of which parts?","o":["Only the distance you travel while braking","Only the time it takes you to see the danger","The length of your car plus one car length","The distance you travel while you notice, react, and brake"],"h1":"Your car keeps moving before your foot even touches the brake.","h2":"Total stopping distance includes the distance you travel while you see the danger, while you move your foot, and while the brakes slow the car.","p":"Right. Stopping distance adds noticing, reacting, and braking."},"es":{"q":"¿De qué partes se forma la distancia total para detenerse?","o":["Solo la distancia que recorre mientras frena","Solo el tiempo que tarda en ver el peligro","El largo de su carro más el largo de otro carro","La distancia que recorre mientras nota el peligro, reacciona y frena"],"h1":"Su carro sigue avanzando antes de que su pie toque el freno.","h2":"La distancia total para detenerse incluye lo que recorre mientras ve el peligro, mientras mueve el pie y mientras los frenos paran el carro.","p":"Correcto. La distancia para detenerse suma notar, reaccionar y frenar."},"zh":{"q":"你的总停车距离由哪些部分组成？","o":["只有刹车时开过的距离","只有你看到危险所用的时间","你的车长再加一个车身长度","你注意到危险、做出反应和刹车时开过的距离"],"h1":"你的脚还没碰到刹车，车就一直在往前走。","h2":"总停车距离包括你看到危险时、你移动脚时，以及刹车让车慢下来时开过的距离。","p":"对。停车距离包括注意、反应和刹车这三部分。"},"vi":{"q":"Tổng quãng đường dừng xe của bạn gồm những phần nào?","o":["Chỉ quãng đường bạn chạy trong lúc đạp phanh","Chỉ thời gian bạn cần để thấy nguy hiểm","Chiều dài xe của bạn cộng thêm một chiều dài xe","Quãng đường bạn chạy trong lúc bạn nhận ra, phản ứng và đạp phanh"],"h1":"Xe của bạn vẫn chạy tiếp trước khi chân bạn chạm vào phanh.","h2":"Tổng quãng đường dừng xe gồm quãng đường bạn chạy trong lúc thấy nguy hiểm, trong lúc bạn di chuyển chân, và trong lúc phanh làm xe chậm lại.","p":"Đúng. Quãng đường dừng xe gồm lúc nhận ra, lúc phản ứng và lúc phanh."},"tl":{"q":"Ano-anong bahagi ang bumubuo sa kabuuang layo ng paghinto mo (total stopping distance)?","o":["Ang layong tinatakbo mo habang nagpepreno lang","Ang oras lang na kailangan mo para makita ang panganib","Ang haba ng kotse mo dagdag ang haba ng isang kotse","Ang layong tinatakbo mo habang napapansin mo, tumutugon ka, at nagpepreno"],"h1":"Umaandar pa ang kotse mo bago pa man dumampi ang paa mo sa preno.","h2":"Kasama sa kabuuang layo ng paghinto ang layong tinatakbo mo habang nakikita mo ang panganib, habang inililipat mo ang paa mo, at habang pinababagal ng preno ang kotse.","p":"Tama. Pinagsasama ng layo ng paghinto ang pagpansin, pagtugon, at pagpreno."},"ar":{"q":"من أي أجزاء تتكون مسافة التوقف الكاملة؟","o":["فقط المسافة التي تقطعها وأنت تضغط على الفرامل","فقط الوقت الذي تحتاجه لترى الخطر","طول سيارتك وطول سيارة أخرى","المسافة التي تقطعها وأنت تلاحظ الخطر، وتتفاعل، وتضغط على الفرامل"],"h1":"سيارتك تستمر في الحركة قبل أن تلمس قدمك الفرامل.","h2":"مسافة التوقف الكاملة تشمل المسافة التي تقطعها في ثلاث مراحل: وأنت ترى الخطر، ثم وأنت تحرك قدمك، ثم بينما تبطئ الفرامل السيارة.","p":"صحيح. مسافة التوقف تجمع الملاحظة والتفاعل والفرملة."},"ht":{"q":"Ak ki pati distans total pou ou kanpe a fèt?","o":["Sèlman distans ou fè pandan w ap fren","Sèlman tan ou pran pou wè danje a","Longè machin ou plis longè yon machin","Distans ou fè pandan ou remake danje a, ou reyaji epi ou fren"],"h1":"Machin ou kontinye avanse menm anvan pye ou touche fren an.","h2":"Distans total pou kanpe a gen ladan l distans ou fè pandan ou wè danje a, pandan ou deplase pye ou, ak pandan fren yo ap ralanti machin nan.","p":"Wi, se sa. Distans pou kanpe a se remake, reyaji, epi fren, tout ansanm."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-012","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"If you drive twice as fast, what happens to the distance your brakes need to stop the car?","o":["It stays the same","It becomes about four times longer","It becomes about two times longer","It becomes shorter"],"h1":"Speed makes stopping harder very quickly, not just a little.","h2":"When your speed doubles, your braking distance becomes about four times longer, because the car carries much more energy.","p":"Right. Double the speed means about four times the braking distance."},"es":{"q":"Si maneja al doble de velocidad, ¿qué pasa con la distancia que necesitan los frenos para parar el carro?","o":["Se queda igual","Se vuelve unas cuatro veces más larga","Se vuelve unas dos veces más larga","Se vuelve más corta"],"h1":"La velocidad hace que frenar sea mucho más difícil, no solo un poco.","h2":"Cuando su velocidad se duplica, la distancia de frenado se vuelve unas cuatro veces más larga, porque el carro lleva mucha más energía.","p":"Correcto. El doble de velocidad significa unas cuatro veces la distancia de frenado."},"zh":{"q":"如果你的车速变成两倍，刹车停下需要的距离会怎么样？","o":["保持不变","变成大约四倍长","变成大约两倍长","变短"],"h1":"速度会让停车变得难很多，不只是难一点。","h2":"车速变成两倍时，刹车距离会变成大约四倍长，因为车带着多得多的能量。","p":"对。车速两倍，刹车距离大约是四倍。"},"vi":{"q":"Nếu bạn chạy nhanh gấp đôi, quãng đường phanh cần để dừng xe sẽ thay đổi thế nào?","o":["Vẫn như cũ","Dài hơn khoảng bốn lần","Dài hơn khoảng hai lần","Ngắn hơn"],"h1":"Tốc độ làm việc dừng xe khó hơn rất nhanh, không chỉ một chút.","h2":"Khi tốc độ tăng gấp đôi, quãng đường phanh của bạn dài hơn khoảng bốn lần, vì xe mang nhiều năng lượng hơn rất nhiều.","p":"Đúng. Tốc độ gấp đôi thì quãng đường phanh dài khoảng gấp bốn."},"tl":{"q":"Kung doble ang bilis mo, ano ang nangyayari sa layong kailangan ng preno mo para mapahinto ang kotse?","o":["Hindi ito nagbabago","Nagiging mga apat na beses itong mas mahaba","Nagiging mga dalawang beses itong mas mahaba","Umiikli ito"],"h1":"Napakabilis na pinahihirap ng bilis ang paghinto, hindi lang nang kaunti.","h2":"Kapag dumoble ang bilis mo, nagiging mga apat na beses na mas mahaba ang layo ng pagpreno, dahil mas malaki ang lakas (enerhiya) na dala ng kotse.","p":"Tama. Ang dobleng bilis ay nangangahulugang mga apat na beses ang layo ng pagpreno."},"ar":{"q":"إذا قدت بضعف السرعة، ماذا يحدث للمسافة التي تحتاجها الفرامل لتوقف السيارة؟","o":["تبقى كما هي","تصبح أطول بحوالي أربع مرات","تصبح أطول بحوالي مرتين","تصبح أقصر"],"h1":"السرعة تجعل التوقف أصعب بكثير وبسرعة، وليس قليلًا فقط.","h2":"عندما تتضاعف سرعتك، تصبح مسافة الفرملة أطول بحوالي أربع مرات، لأن السيارة تحمل طاقة أكبر بكثير.","p":"صحيح. ضعف السرعة يعني حوالي أربعة أضعاف مسافة الفرملة."},"ht":{"q":"Si ou kondi de fwa pi vit, kisa ki rive distans fren ou bezwen pou kanpe machin nan?","o":["Li rete menm jan an","Li vin apeprè kat fwa pi long","Li vin apeprè de fwa pi long","Li vin pi kout"],"h1":"Vitès fè li vin pi difisil pou kanpe trè vit, se pa yon ti kras sèlman.","h2":"Lè vitès ou double, distans fren ou vin apeprè kat fwa pi long, paske machin nan pote anpil plis enèji.","p":"Wi, se sa. De fwa vitès la vle di apeprè kat fwa distans fren an."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-013","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"A driver is following very close behind you. What is the safest thing to do?","o":["Tap your brakes hard to warn the driver","Leave more space ahead of you and let the driver pass","Speed up to get away from the driver","Stop in your lane until the driver goes around"],"h1":"If you must stop suddenly, the driver behind may hit you. How can you avoid sudden stops?","h2":"The safest choice is to leave extra space ahead of you, so you can slow down gently, and to let the close driver pass.","p":"Right. Give yourself more space ahead and let a tailgater pass."},"es":{"q":"Un conductor va muy pegado detrás de usted. ¿Qué es lo más seguro?","o":["Frenar fuerte para avisarle al conductor","Dejar más espacio adelante y dejar que el conductor lo rebase","Acelerar para alejarse del conductor","Detenerse en su carril hasta que el conductor lo rodee"],"h1":"Si tiene que frenar de golpe, el de atrás puede chocarlo. ¿Cómo puede evitar frenadas de golpe?","h2":"Lo más seguro es dejar más espacio adelante para poder frenar suavemente, y dejar que el conductor que va pegado lo rebase.","p":"Correcto. Deje más espacio adelante y deje que el conductor pegado lo rebase."},"zh":{"q":"有一个司机紧紧跟在你后面。最安全的做法是什么？","o":["用力点一下刹车，警告那个司机","在你前面留更多空间，让那个司机超过去","加速，甩开那个司机","在你的车道里停车，等那个司机绕过去"],"h1":"如果你必须突然停车，后面的司机可能会撞上你。怎样才能避免突然停车？","h2":"最安全的做法是在你前面多留空间，这样你可以慢慢减速，并让跟得很近的司机超过去。","p":"对。在前面多留空间，让跟车太近的司机超过去。"},"vi":{"q":"Một người lái đang chạy rất sát phía sau bạn. Điều an toàn nhất nên làm là gì?","o":["Đạp phanh mạnh để cảnh báo người đó","Để thêm khoảng cách phía trước và để người đó vượt qua","Tăng tốc để tránh xa người đó","Dừng lại trong làn cho đến khi người đó vòng qua"],"h1":"Nếu bạn phải dừng gấp, người phía sau có thể đâm vào bạn. Làm sao để tránh phải dừng gấp?","h2":"Điều an toàn nhất là để thêm khoảng cách phía trước, để bạn có thể giảm tốc nhẹ nhàng, và để người lái bám sát vượt qua.","p":"Đúng. Hãy để thêm khoảng cách phía trước và để người bám sát vượt qua."},"tl":{"q":"May drayber na sobrang lapit sa likod mo. Ano ang pinakaligtas na gawin?","o":["Biglang tapakan ang preno para bigyan ng babala ang drayber","Mag-iwan ng mas malaking espasyo sa unahan mo at hayaang lumampas ang drayber","Bumilis para makalayo sa drayber","Huminto sa lane mo hanggang umikot ang drayber"],"h1":"Kung bigla kang hihinto, maaaring mabangga ka ng drayber sa likod. Paano mo maiiwasan ang biglang paghinto?","h2":"Ang pinakaligtas na gawin ay mag-iwan ng dagdag na espasyo sa unahan mo, para dahan-dahan kang makabagal, at hayaang lumampas ang drayber na sobrang lapit.","p":"Tama. Bigyan ang sarili ng mas malaking espasyo sa unahan at hayaang lumampas ang dumidikit sa likod mo."},"ar":{"q":"سائق يسير قريبًا جدًا خلفك. ما أكثر شيء آمن تفعله؟","o":["أضغط على الفرامل بقوة لأحذّر السائق","أترك مسافة أكبر أمامي وأترك السائق يتجاوزني","أسرع لأبتعد عن السائق","أتوقف في مساري حتى يلتف السائق حولي"],"h1":"إذا اضطررت إلى التوقف فجأة، قد يصدمك السائق الذي خلفك. كيف تتجنب التوقف المفاجئ؟","h2":"الخيار الأكثر أمانًا هو أن تترك مسافة إضافية أمامك، حتى تستطيع أن تخفف السرعة بهدوء، وأن تترك السائق القريب يتجاوزك.","p":"صحيح. اترك لنفسك مسافة أكبر أمامك واترك السائق الملاصق لك يتجاوزك."},"ht":{"q":"Yon chofè ap swiv ou trè pre dèyè. Kisa ki pi an sekirite pou ou fè?","o":["Peze fren an fò pou avèti chofè a","Kite plis espas devan ou epi kite chofè a pase","Akselere pou ale lwen chofè a","Kanpe nan liy ou jiskaske chofè a pase bò kote ou"],"h1":"Si ou oblije kanpe sou kou, chofè ki dèyè a ka frape ou. Kijan ou ka evite kanpe sou kou?","h2":"Pi bon chwa a se kite plis espas devan ou, pou ou ka ralanti dousman, epi kite chofè ki twò pre a pase.","p":"Wi, se sa. Kite plis espas devan ou epi kite chofè ki twò pre dèyè ou a pase."}},{"id":"speed-lanes-014","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, on a two-lane road, how close to an intersection or railroad crossing may you pass another car?","o":["Not within 25 feet","Not within 50 feet","Passing is allowed right up to it","Not within 100 feet"],"h1":"Cars and trains may enter the road there. You need a clear stretch.","h2":"In Florida you may not pass on a two-lane road within 100 feet of an intersection or a railroad crossing, because traffic may enter or stop there.","p":"Right. Do not pass within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Florida, en una carretera de dos carriles, ¿qué tan cerca de una intersección o un cruce de tren puede rebasar a otro carro?","o":["No a menos de 25 pies","No a menos de 50 pies","Se puede rebasar hasta llegar allí","No a menos de 100 pies"],"h1":"Allí pueden entrar carros o trenes. Necesita un tramo despejado.","h2":"En Florida no puede rebasar en una carretera de dos carriles a menos de 100 pies de una intersección o de un cruce de tren, porque el tráfico puede entrar o detenerse allí.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"zh":{"q":"在 Florida，在双车道道路上，离路口或铁路道口多近时不能超车？","o":["25 英尺以内不能超车","50 英尺以内不能超车","可以一直超车到路口","100 英尺以内不能超车"],"h1":"车和火车可能在那里开进来。你需要一段畅通的路。","h2":"在 Florida，在双车道道路上，离路口或铁路道口 100 英尺以内不能超车，因为车辆可能在那里开进来或停下。","p":"对。离路口或铁路道口 100 英尺以内不要超车。"},"vi":{"q":"Ở Florida, trên đường hai làn, bạn được vượt xe khác gần giao lộ hoặc chỗ giao nhau với đường sắt đến mức nào?","o":["Không được trong vòng 25 feet","Không được trong vòng 50 feet","Được vượt sát đến tận đó","Không được trong vòng 100 feet"],"h1":"Xe hơi và tàu hỏa có thể đi vào đường ở đó. Bạn cần một đoạn đường trống.","h2":"Ở Florida, bạn không được vượt trên đường hai làn trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt, vì xe cộ có thể đi vào hoặc dừng ở đó.","p":"Đúng. Không vượt trong vòng 100 feet trước giao lộ hoặc chỗ giao nhau với đường sắt."},"tl":{"q":"Sa Florida, sa daang may dalawang lane, gaano kalapit sa intersection o railroad crossing ka puwedeng lumampas sa ibang kotse?","o":["Hindi sa loob ng 25 feet","Hindi sa loob ng 50 feet","Puwedeng lumampas hanggang mismong doon","Hindi sa loob ng 100 feet"],"h1":"Maaaring pumasok sa daan ang mga kotse at tren doon. Kailangan mo ng malinis na bahagi ng daan.","h2":"Sa Florida, hindi ka puwedeng lumampas sa daang may dalawang lane sa loob ng 100 feet mula sa intersection o railroad crossing, dahil maaaring pumasok o huminto ang trapiko roon.","p":"Tama. Huwag lumampas sa loob ng 100 feet mula sa intersection o railroad crossing."},"ar":{"q":"في Florida، على طريق فيه مساران، كم يمكنك أن تقترب من تقاطع أو من تقاطع سكة حديد وأنت تتجاوز سيارة أخرى؟","o":["ليس في حدود 25 قدمًا","ليس في حدود 50 قدمًا","التجاوز مسموح حتى الوصول إليه","ليس في حدود 100 قدم"],"h1":"السيارات والقطارات قد تدخل الطريق هناك. تحتاج إلى مسافة فارغة.","h2":"في Florida لا يجوز أن تتجاوز على طريق فيه مساران في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد، لأن السيارات قد تدخل أو تتوقف هناك.","p":"صحيح. لا تتجاوز في حدود 100 قدم من تقاطع أو من تقاطع سكة حديد."},"ht":{"q":"Nan Florida, sou yon wout ki gen de liy, a ki distans de yon kafou oswa yon kwazman tren ou ka double yon lòt machin?","o":["Pa nan mwens pase 25 pye","Pa nan mwens pase 50 pye","Ou ka double jis rive bò kote l","Pa nan mwens pase 100 pye"],"h1":"Machin ak tren ka antre sou wout la la. Ou bezwen yon bout wout ki lib.","h2":"Nan Florida ou pa ka double sou yon wout ki gen de liy nan mwens pase 100 pye de yon kafou oswa yon kwazman tren, paske machin ka antre oswa kanpe la.","p":"Wi, se sa. Pa double nan mwens pase 100 pye de yon kafou oswa yon kwazman tren."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-015","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, when may you pass another car on the right?","o":["When the car ahead is turning left and there is a lane to pass in","When the car ahead is going a little slow on a two-lane road","When you can use the paved shoulder","Whenever the left lane is busy"],"h1":"You must stay on the road itself, not on the shoulder.","h2":"You may pass on the right when the car ahead is turning left and there is a full lane for you, but you may never drive on the shoulder to pass.","p":"Right. Pass on the right only with a real lane, like when a car is turning left."},"es":{"q":"En Florida, ¿cuándo puede rebasar a otro carro por la derecha?","o":["Cuando el carro de adelante va a girar a la izquierda y hay un carril para rebasar","Cuando el carro de adelante va un poco lento en una carretera de dos carriles","Cuando puede usar el acotamiento pavimentado","Siempre que el carril izquierdo esté ocupado"],"h1":"Debe quedarse en la vía, no en el acotamiento.","h2":"Puede rebasar por la derecha cuando el carro de adelante va a girar a la izquierda y hay un carril completo para usted, pero nunca puede usar el acotamiento para rebasar.","p":"Correcto. Rebase por la derecha solo si hay un carril de verdad, como cuando un carro gira a la izquierda."},"zh":{"q":"在 Florida，什么时候可以从右边超车？","o":["前车正在左转，而且有一条车道可以超车时","在双车道道路上，前车开得有点慢时","你可以用铺了路面的路肩时","左边车道车很多的时候"],"h1":"你必须留在道路上，不能开到路肩上。","h2":"当前车正在左转，而且有一整条车道给你时，你可以从右边超车，但你永远不能开上路肩去超车。","p":"对。只有在有真正车道时才从右边超车，比如前车正在左转时。"},"vi":{"q":"Ở Florida, khi nào bạn được vượt xe khác bên phải?","o":["Khi xe phía trước đang rẽ trái và có làn để bạn vượt","Khi xe phía trước chạy hơi chậm trên đường hai làn","Khi bạn có thể dùng lề đường tráng nhựa","Bất cứ khi nào làn trái đông xe"],"h1":"Bạn phải ở trên mặt đường, không phải trên lề.","h2":"Bạn được vượt bên phải khi xe phía trước đang rẽ trái và có một làn đầy đủ cho bạn, nhưng bạn không bao giờ được chạy trên lề để vượt.","p":"Đúng. Chỉ vượt bên phải khi có làn thật sự, như khi xe phía trước đang rẽ trái."},"tl":{"q":"Sa Florida, kailan ka puwedeng lumampas sa ibang kotse sa kanan?","o":["Kapag kumakaliwa ang kotse sa unahan at may lane na madadaanan mo","Kapag medyo mabagal ang kotse sa unahan sa daang may dalawang lane","Kapag puwede mong gamitin ang sementadong shoulder","Tuwing masikip ang kaliwang lane"],"h1":"Dapat kang manatili sa mismong daan, hindi sa shoulder.","h2":"Puwede kang lumampas sa kanan kapag kumakaliwa ang kotse sa unahan at may buong lane para sa iyo, pero hindi ka kailanman puwedeng magmaneho sa shoulder para lumampas.","p":"Tama. Lumampas sa kanan lang kapag may tunay na lane, gaya ng kapag kumakaliwa ang isang kotse."},"ar":{"q":"في Florida، متى يمكنك أن تتجاوز سيارة أخرى من اليمين؟","o":["عندما تنعطف السيارة التي أمامي يسارًا ويوجد مسار أتجاوز فيه","عندما تسير السيارة التي أمامي ببطء قليلًا على طريق فيه مساران","عندما أستطيع أن أستعمل كتف الطريق المرصوف","كلما كان المسار الأيسر مزدحمًا"],"h1":"يجب أن تبقى على الطريق نفسه، وليس على كتف الطريق.","h2":"يمكنك أن تتجاوز من اليمين عندما تنعطف السيارة التي أمامك يسارًا ويوجد مسار كامل لك، لكن لا يجوز أبدًا أن تقود على كتف الطريق لتتجاوز.","p":"صحيح. تجاوز من اليمين فقط عندما يوجد مسار حقيقي، مثل عندما تنعطف سيارة يسارًا."},"ht":{"q":"Nan Florida, kilè ou ka double yon lòt machin sou bò dwat?","o":["Lè machin devan an ap vire agòch epi gen yon liy pou ou pase","Lè machin devan an ap kondi yon ti kras dousman sou yon wout ki gen de liy","Lè ou ka sèvi ak bò wout ki asfalte a","Chak fwa liy gòch la chaje"],"h1":"Ou dwe rete sou wout la menm, pa sou bò wout la.","h2":"Ou ka double sou bò dwat lè machin devan an ap vire agòch epi gen yon liy konplè pou ou, men ou pa janm ka kondi sou bò wout la pou double.","p":"Wi, se sa. Double sou bò dwat sèlman lè gen yon vrè liy, tankou lè yon machin ap vire agòch."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-016","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, another car is passing you. What should you do?","o":["Speed up so the other car cannot pass","Move to the left to block the other car","Stay in your lane and do not speed up","Brake hard to let the other car in"],"h1":"Make it easy and safe for the other driver to finish passing.","h2":"When another car passes you, you must stay in your lane and not speed up, so the other driver can finish passing safely.","p":"Right. When someone passes you, keep your lane and do not speed up."},"es":{"q":"En Florida, otro carro lo está rebasando. ¿Qué debe hacer?","o":["Acelerar para que el otro carro no lo rebase","Moverse a la izquierda para bloquear al otro carro","Quedarse en su carril y no acelerar","Frenar fuerte para dejar entrar al otro carro"],"h1":"Hágale fácil y seguro al otro conductor terminar de rebasar.","h2":"Cuando otro carro lo rebasa, debe quedarse en su carril y no acelerar, para que el otro conductor termine de rebasar con seguridad.","p":"Correcto. Cuando alguien lo rebasa, quédese en su carril y no acelere."},"zh":{"q":"在 Florida，另一辆车正在超你的车。你应该怎么做？","o":["加速，不让对方超过去","向左移，挡住对方","留在你的车道里，不要加速","用力刹车，让对方进来"],"h1":"让对方司机能轻松、安全地完成超车。","h2":"别的车超你时，你必须留在你的车道里，不要加速，让对方司机能安全地完成超车。","p":"对。有人超你时，保持在你的车道，不要加速。"},"vi":{"q":"Ở Florida, một xe khác đang vượt bạn. Bạn nên làm gì?","o":["Tăng tốc để xe kia không vượt được","Lấn sang trái để chặn xe kia","Ở lại trong làn của bạn và không tăng tốc","Phanh gấp để cho xe kia vào"],"h1":"Hãy giúp người lái kia vượt xong một cách dễ dàng và an toàn.","h2":"Khi có xe khác vượt bạn, bạn phải ở lại trong làn và không tăng tốc, để người lái kia vượt xong an toàn.","p":"Đúng. Khi có người vượt bạn, hãy giữ làn và không tăng tốc."},"tl":{"q":"Sa Florida, may ibang kotseng lumalampas sa iyo. Ano ang dapat mong gawin?","o":["Bumilis para hindi makalampas ang ibang kotse","Lumipat pakaliwa para harangan ang ibang kotse","Manatili sa lane mo at huwag bumilis","Biglang magpreno para makapasok ang ibang kotse"],"h1":"Gawing madali at ligtas para sa ibang drayber ang pagtatapos ng paglampas.","h2":"Kapag may kotseng lumalampas sa iyo, dapat kang manatili sa lane mo at huwag bumilis, para ligtas na matapos ng ibang drayber ang paglampas.","p":"Tama. Kapag may lumalampas sa iyo, manatili sa lane mo at huwag bumilis."},"ar":{"q":"في Florida، سيارة أخرى تتجاوزك. ماذا يجب أن تفعل؟","o":["أسرع حتى لا تستطيع السيارة الأخرى أن تتجاوزني","أتحرك إلى اليسار لأمنع السيارة الأخرى","أبقى في مساري ولا أسرع","أضغط على الفرامل بقوة لأترك السيارة الأخرى تدخل"],"h1":"اجعل إنهاء التجاوز سهلًا وآمنًا للسائق الآخر.","h2":"عندما تتجاوزك سيارة أخرى، يجب أن تبقى في مسارك ولا تسرع، حتى يستطيع السائق الآخر أن ينهي التجاوز بأمان.","p":"صحيح. عندما يتجاوزك أحد، ابقَ في مسارك ولا تسرع."},"ht":{"q":"Nan Florida, yon lòt machin ap double ou. Kisa ou ta dwe fè?","o":["Akselere pou lòt machin nan pa ka double","Deplase sou bò gòch pou bloke lòt machin nan","Rete nan liy ou epi pa akselere","Peze fren an fò pou kite lòt machin nan antre"],"h1":"Fè li fasil epi san danje pou lòt chofè a fin double.","h2":"Lè yon lòt machin ap double ou, ou dwe rete nan liy ou epi pa akselere, pou lòt chofè a ka fin double san danje.","p":"Wi, se sa. Lè yon moun ap double ou, rete nan liy ou epi pa akselere."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-017","scope":"US","cat":"speed-lanes","sign":{"shape":"no-passing","text":"NO PASSING ZONE"},"c":2,"en":{"q":"What does this yellow pennant-shaped sign mean?","o":["A school zone starts here","The road ends ahead","A no-passing zone starts here","You may pass on the right"],"h1":"This sign is on the left side of the road, where drivers look before they pass.","h2":"The yellow pennant sign marks the start of a no-passing zone, so you may not pass other cars from that point.","p":"Right. The pennant sign shows where a no-passing zone begins."},"es":{"q":"¿Qué significa este letrero amarillo en forma de banderín?","o":["Aquí empieza una zona escolar","La carretera termina más adelante","Aquí empieza una zona donde no se puede rebasar","Puede rebasar por la derecha"],"h1":"Este letrero está al lado izquierdo de la carretera, donde miran los conductores antes de rebasar.","h2":"El letrero amarillo en forma de banderín marca el inicio de una zona donde no se puede rebasar, así que desde allí no puede rebasar a otros carros.","p":"Correcto. El banderín muestra dónde empieza la zona sin rebase."},"zh":{"q":"这个黄色三角旗形的标志是什么意思？","o":["学校区从这里开始","前面道路到头了","禁止超车区从这里开始","你可以从右边超车"],"h1":"这个标志在道路的左边，就是司机超车前会看的地方。","h2":"黄色三角旗形标志表示禁止超车区的开始，所以从那里开始你不能超车。","p":"对。三角旗形标志表示禁止超车区从哪里开始。"},"vi":{"q":"Biển báo màu vàng hình cờ đuôi nheo này có nghĩa là gì?","o":["Khu vực trường học bắt đầu ở đây","Phía trước hết đường","Khu vực cấm vượt bắt đầu ở đây","Bạn được vượt bên phải"],"h1":"Biển này nằm ở bên trái đường, nơi người lái nhìn trước khi vượt.","h2":"Biển màu vàng hình cờ đuôi nheo đánh dấu nơi bắt đầu khu vực cấm vượt, nên từ điểm đó bạn không được vượt xe khác.","p":"Đúng. Biển hình cờ đuôi nheo cho biết nơi bắt đầu khu vực cấm vượt."},"tl":{"q":"Ano ang ibig sabihin ng dilaw na karatulang hugis pennant (mahabang tatsulok na bandila) na ito?","o":["Dito nagsisimula ang school zone","Nagtatapos ang daan sa unahan","Dito nagsisimula ang no-passing zone (bawal lumampas)","Puwede kang lumampas sa kanan"],"h1":"Nasa kaliwang gilid ng daan ang karatulang ito, kung saan tumitingin ang mga drayber bago lumampas.","h2":"Ang dilaw na pennant na karatula ay nagmamarka ng simula ng no-passing zone, kaya hindi ka puwedeng lumampas sa ibang kotse mula sa puntong iyon.","p":"Tama. Ipinapakita ng pennant na karatula kung saan nagsisimula ang no-passing zone."},"ar":{"q":"ماذا تعني هذه العلامة الصفراء التي على شكل راية مثلثة؟","o":["تبدأ منطقة مدرسة هنا","الطريق ينتهي أمامك","تبدأ منطقة ممنوع فيها التجاوز هنا","يمكنك أن تتجاوز من اليمين"],"h1":"هذه العلامة على الجانب الأيسر من الطريق، حيث ينظر السائقون قبل أن يتجاوزوا.","h2":"العلامة الصفراء التي على شكل راية تدل على بداية منطقة ممنوع فيها التجاوز، لذلك لا يجوز أن تتجاوز السيارات الأخرى من تلك النقطة.","p":"صحيح. علامة الراية تُظهر أين تبدأ منطقة ممنوع فيها التجاوز."},"ht":{"q":"Kisa siy jòn sa a ki gen fòm yon drapo pwenti (pennant) vle di?","o":["Yon zòn lekòl kòmanse la","Wout la fini devan","Yon zòn kote ou pa ka double kòmanse la","Ou ka double sou bò dwat"],"h1":"Siy sa a sou bò gòch wout la, kote chofè yo gade anvan yo double.","h2":"Siy jòn ki gen fòm drapo pwenti a make kote yon zòn ou pa ka double kòmanse, kidonk ou pa ka double lòt machin depi kote sa a.","p":"Wi, se sa. Siy drapo pwenti a montre kote yon zòn ou pa ka double kòmanse."},"ref":{"doc":"FL","page":48}},{"id":"speed-lanes-018","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"There is a solid yellow line on your side of the center line. What does it mean?","o":["You may not pass","You may pass when it is safe","The road is one-way","You must stop ahead"],"h1":"Look closely: is the line on your side broken or solid?","h2":"A solid yellow line on your side of the center means you may not cross it to pass other cars.","p":"Right. A solid yellow line on your side means no passing."},"es":{"q":"Hay una línea amarilla continua de su lado de la línea central. ¿Qué significa?","o":["No puede rebasar","Puede rebasar cuando sea seguro","La calle es de un solo sentido","Debe detenerse más adelante"],"h1":"Mire bien: ¿la línea de su lado es cortada o continua?","h2":"Una línea amarilla continua de su lado de la línea central significa que no puede cruzarla para rebasar a otros carros.","p":"Correcto. Una línea amarilla continua de su lado significa que no puede rebasar."},"zh":{"q":"在中心线你这一边有一条黄色实线。这是什么意思？","o":["你不能超车","安全时你可以超车","这条路是单行道","你前面必须停车"],"h1":"仔细看：你这一边的线是虚线还是实线？","h2":"中心线你这一边的黄色实线表示你不能越过它去超车。","p":"对。你这一边是黄色实线，表示不能超车。"},"vi":{"q":"Có một vạch vàng liền ở phía bên bạn của vạch giữa đường. Vạch đó có nghĩa là gì?","o":["Bạn không được vượt","Bạn được vượt khi an toàn","Đường này là đường một chiều","Bạn phải dừng ở phía trước"],"h1":"Hãy nhìn kỹ: vạch ở phía bên bạn là vạch đứt hay vạch liền?","h2":"Vạch vàng liền ở phía bên bạn của vạch giữa đường có nghĩa là bạn không được vượt qua vạch đó để vượt xe khác.","p":"Đúng. Vạch vàng liền ở phía bên bạn có nghĩa là cấm vượt."},"tl":{"q":"May tuloy-tuloy na dilaw na guhit sa panig mo ng center line (guhit sa gitna). Ano ang ibig sabihin nito?","o":["Bawal kang lumampas","Puwede kang lumampas kapag ligtas","One-way ang daan","Dapat kang huminto sa unahan"],"h1":"Tingnang mabuti: putol-putol ba o tuloy-tuloy ang guhit sa panig mo?","h2":"Ang tuloy-tuloy na dilaw na guhit sa panig mo ng gitna ay nangangahulugang hindi mo ito puwedeng tawirin para lumampas sa ibang kotse.","p":"Tama. Ang tuloy-tuloy na dilaw na guhit sa panig mo ay nangangahulugang bawal lumampas."},"ar":{"q":"يوجد خط أصفر متصل في جهتك من خط الوسط. ماذا يعني؟","o":["لا يجوز أن أتجاوز","يمكنني أن أتجاوز عندما يكون آمنًا","الطريق باتجاه واحد","يجب أن أتوقف أمامي"],"h1":"انظر جيدًا: هل الخط في جهتك متقطع أم متصل؟","h2":"الخط الأصفر المتصل في جهتك من خط الوسط يعني أنه لا يجوز أن تعبره لتتجاوز السيارات الأخرى.","p":"صحيح. الخط الأصفر المتصل في جهتك يعني ممنوع التجاوز."},"ht":{"q":"Gen yon liy jòn ki pa koupe sou bò pa w la nan liy mitan an. Kisa li vle di?","o":["Ou pa ka double","Ou ka double lè li pa danjere","Wout la se yon sèl sans","Ou dwe kanpe devan"],"h1":"Gade byen: èske liy ki sou bò pa w la koupe oswa li pa koupe?","h2":"Yon liy jòn ki pa koupe sou bò pa w la nan mitan wout la vle di ou pa ka travèse l pou double lòt machin.","p":"Wi, se sa. Yon liy jòn ki pa koupe sou bò pa w la vle di ou pa ka double."},"ref":{"doc":"FL","page":44}},{"id":"speed-lanes-019","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how far before a turn must you start using your turn signal?","o":["At least 25 feet","At least 50 feet","Only when you begin to turn","At least 100 feet"],"h1":"Give other drivers enough warning before you move.","h2":"In Florida you must turn on your signal at least 100 feet before you turn, so other drivers know what you plan to do.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Florida, ¿con cuánta anticipación debe poner la direccional antes de girar?","o":["Al menos 25 pies antes","Al menos 50 pies antes","Solo cuando empieza a girar","Al menos 100 pies antes"],"h1":"Avise a los demás conductores con suficiente tiempo antes de moverse.","h2":"En Florida debe poner la direccional al menos 100 pies antes de girar, para que los demás sepan lo que va a hacer.","p":"Correcto. Ponga la direccional al menos 100 pies antes de girar."},"zh":{"q":"在 Florida，转弯前多远必须开始打转向灯？","o":["至少 25 英尺","至少 50 英尺","只在开始转弯时","至少 100 英尺"],"h1":"在你移动之前，给其他司机足够的提醒。","h2":"在 Florida，你必须在转弯前至少 100 英尺打开转向灯，让其他司机知道你要做什么。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Florida, bạn phải bắt đầu bật xi nhan bao xa trước khi rẽ?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 100 feet"],"h1":"Hãy báo trước đủ cho người lái khác trước khi bạn di chuyển.","h2":"Ở Florida, bạn phải bật xi nhan ít nhất 100 feet trước khi rẽ, để người lái khác biết bạn định làm gì.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Florida, gaano kalayo bago lumiko dapat mong simulang gamitin ang turn signal mo?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Kapag nagsisimula ka lang lumiko","Hindi bababa sa 100 feet"],"h1":"Bigyan ang ibang drayber ng sapat na babala bago ka gumalaw.","h2":"Sa Florida, dapat mong buksan ang signal mo nang hindi bababa sa 100 feet bago ka lumiko, para malaman ng ibang drayber ang balak mong gawin.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago ka lumiko."},"ar":{"q":"في Florida، قبل الانعطاف بكم مسافة يجب أن تبدأ باستعمال إشارة الانعطاف؟","o":["25 قدمًا على الأقل","50 قدمًا على الأقل","فقط عندما أبدأ الانعطاف","100 قدم على الأقل"],"h1":"أعطِ السائقين الآخرين تحذيرًا كافيًا قبل أن تتحرك.","h2":"في Florida يجب أن تشغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل، حتى يعرف السائقون الآخرون ماذا تنوي أن تفعل.","p":"صحيح. شغّل الإشارة قبل الانعطاف بمسافة 100 قدم على الأقل."},"ht":{"q":"Nan Florida, a ki distans anvan yon vire ou dwe kòmanse mete siyal ou?","o":["Omwen 25 pye","Omwen 50 pye","Sèlman lè ou kòmanse vire","Omwen 100 pye"],"h1":"Bay lòt chofè yo ase tan pou yo konnen anvan ou deplase.","h2":"Nan Florida ou dwe limen siyal ou omwen 100 pye anvan ou vire, pou lòt chofè yo konnen sa ou vle fè.","p":"Wi, se sa. Mete siyal omwen 100 pye anvan ou vire."},"ref":{"doc":"FL","page":69}},{"id":"speed-lanes-020","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You want to change lanes. What should you do right after checking your mirrors?","o":["Change lanes right away","Turn your head and look over your shoulder","Honk your horn","Slow down to a stop"],"h1":"Your mirrors cannot show every place next to your car.","h2":"After you check your mirrors, turn your head and look over your shoulder, because a car may be hiding in your blind spot.","p":"Right. Look over your shoulder to check your blind spot."},"es":{"q":"Quiere cambiar de carril. ¿Qué debe hacer justo después de revisar los espejos?","o":["Cambiar de carril enseguida","Voltear la cabeza y mirar por encima del hombro","Tocar la bocina","Frenar hasta detenerse"],"h1":"Los espejos no muestran todos los lugares al lado de su carro.","h2":"Después de revisar los espejos, voltee la cabeza y mire por encima del hombro, porque puede haber un carro escondido en su punto ciego.","p":"Correcto. Mire por encima del hombro para revisar su punto ciego."},"zh":{"q":"你想换车道。看完后视镜以后，紧接着应该做什么？","o":["马上换道","转头，从肩膀上方往后看","按喇叭","减速停下"],"h1":"后视镜不能照到你车旁边的每个地方。","h2":"看完后视镜后，要转头从肩膀上方往后看，因为可能有车藏在你的盲区里。","p":"对。转头往后看，检查你的盲区。"},"vi":{"q":"Bạn muốn đổi làn. Ngay sau khi nhìn gương, bạn nên làm gì?","o":["Đổi làn ngay","Quay đầu và nhìn qua vai","Bấm còi","Giảm tốc cho đến khi dừng"],"h1":"Gương của bạn không thể cho thấy mọi chỗ bên cạnh xe.","h2":"Sau khi nhìn gương, bạn quay đầu và nhìn qua vai, vì có thể có xe đang khuất trong điểm mù của bạn.","p":"Đúng. Hãy nhìn qua vai để kiểm tra điểm mù."},"tl":{"q":"Gusto mong lumipat ng lane. Ano ang dapat mong gawin pagkatapos tumingin sa mga salamin mo?","o":["Lumipat agad ng lane","Ilingon ang ulo mo at tumingin sa likod ng balikat mo","Bumusina","Bumagal hanggang huminto"],"h1":"Hindi kayang ipakita ng mga salamin mo ang bawat lugar sa tabi ng kotse mo.","h2":"Pagkatapos mong tumingin sa mga salamin, ilingon ang ulo mo at tumingin sa likod ng balikat mo, dahil maaaring may kotseng nakatago sa blind spot mo.","p":"Tama. Tumingin sa likod ng balikat mo para suriin ang blind spot mo."},"ar":{"q":"تريد أن تغيّر المسار. ماذا يجب أن تفعل مباشرة بعد أن تنظر في المرايا؟","o":["أغيّر المسار فورًا","أدير رأسي وأنظر من فوق كتفي","أستعمل البوق","أخفف السرعة حتى أتوقف"],"h1":"المرايا لا تستطيع أن تُظهر كل مكان بجانب سيارتك.","h2":"بعد أن تنظر في المرايا، أدر رأسك وانظر من فوق كتفك، لأن سيارة قد تكون مختبئة في النقطة العمياء.","p":"صحيح. انظر من فوق كتفك لتفحص النقطة العمياء."},"ht":{"q":"Ou vle chanje liy. Kisa ou ta dwe fè touswit apre ou fin tcheke retwovizè ou yo?","o":["Chanje liy touswit","Vire tèt ou epi gade pa dèyè zepòl ou","Klaksonnen","Ralanti jiskaske ou kanpe"],"h1":"Retwovizè ou yo pa ka montre tout kote ki bò kote machin ou.","h2":"Apre ou fin tcheke retwovizè ou yo, vire tèt ou epi gade pa dèyè zepòl ou, paske yon machin ka kache nan kwen ou pa wè a.","p":"Wi, se sa. Gade pa dèyè zepòl ou pou tcheke kwen ou pa wè a."},"ref":{"doc":"FL","page":60}},{"id":"speed-lanes-021","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You need to move over three lanes to reach your exit. How should you do it?","o":["Cross all three lanes in one move","Move one lane at a time and signal each time","Signal once and then cross all lanes","Slow down in your lane and wait for a gap in all lanes"],"h1":"Each lane may have its own traffic and its own blind spot.","h2":"You should move one lane at a time, signaling and checking your blind spot before each move, because every lane can hide a car.","p":"Right. Change one lane at a time and signal each time."},"es":{"q":"Necesita pasar tres carriles para llegar a su salida. ¿Cómo debe hacerlo?","o":["Cruzar los tres carriles de una sola vez","Cambiar un carril a la vez y poner la direccional cada vez","Poner la direccional una vez y cruzar todos los carriles","Frenar en su carril y esperar un espacio en todos los carriles"],"h1":"Cada carril puede tener su propio tráfico y su propio punto ciego.","h2":"Debe cambiar un carril a la vez, poniendo la direccional y revisando el punto ciego antes de cada cambio, porque en cada carril puede haber un carro.","p":"Correcto. Cambie un carril a la vez y ponga la direccional cada vez."},"zh":{"q":"你要跨过三条车道才能到你的出口。你应该怎么做？","o":["一次跨过全部三条车道","一次换一条车道，每次都打转向灯","打一次转向灯，然后跨过所有车道","在你的车道里减速，等所有车道都有空隙"],"h1":"每条车道都可能有自己的车，也有自己的盲区。","h2":"你应该一次换一条车道，每次换道前都打转向灯、检查盲区，因为每条车道都可能藏着一辆车。","p":"对。一次换一条车道，每次都打转向灯。"},"vi":{"q":"Bạn cần chuyển qua ba làn để đến lối ra. Bạn nên làm thế nào?","o":["Chuyển qua cả ba làn một lần","Chuyển từng làn một và bật xi nhan mỗi lần","Bật xi nhan một lần rồi chuyển qua tất cả các làn","Giảm tốc trong làn của bạn và chờ khoảng trống ở tất cả các làn"],"h1":"Mỗi làn có thể có xe riêng và điểm mù riêng.","h2":"Bạn nên chuyển từng làn một, bật xi nhan và kiểm tra điểm mù trước mỗi lần chuyển, vì làn nào cũng có thể có xe bị khuất.","p":"Đúng. Hãy đổi từng làn một và bật xi nhan mỗi lần."},"tl":{"q":"Kailangan mong lumipat nang tatlong lane para marating ang exit mo. Paano mo ito dapat gawin?","o":["Tawirin ang tatlong lane sa isang galaw","Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses","Mag-signal nang isang beses at saka tawirin ang lahat ng lane","Bumagal sa lane mo at maghintay ng puwang sa lahat ng lane"],"h1":"Bawat lane ay maaaring may sariling trapiko at sariling blind spot.","h2":"Dapat kang lumipat nang isang lane sa bawat pagkakataon, nagsi-signal at sumusuri sa blind spot bago ang bawat paglipat, dahil bawat lane ay maaaring may nakatagong kotse.","p":"Tama. Lumipat nang isang lane sa bawat pagkakataon at mag-signal bawat beses."},"ar":{"q":"تحتاج إلى أن تنتقل ثلاثة مسارات لتصل إلى المخرج. كيف تفعل ذلك؟","o":["أعبر المسارات الثلاثة في حركة واحدة","أنتقل مسارًا واحدًا في كل مرة وأشغّل الإشارة كل مرة","أشغّل الإشارة مرة واحدة ثم أعبر كل المسارات","أخفف السرعة في مساري وأنتظر فجوة في كل المسارات"],"h1":"كل مسار قد تكون فيه سيارات خاصة به ونقطة عمياء خاصة به.","h2":"يجب أن تنتقل مسارًا واحدًا في كل مرة، وأن تشغّل الإشارة وتفحص النقطة العمياء قبل كل انتقال، لأن كل مسار قد تختبئ فيه سيارة.","p":"صحيح. غيّر مسارًا واحدًا في كل مرة وشغّل الإشارة كل مرة."},"ht":{"q":"Ou bezwen travèse twa liy pou rive nan sòti ou a. Kijan ou ta dwe fè l?","o":["Travèse twa liy yo yon sèl kou","Chanje yon liy alafwa epi mete siyal chak fwa","Mete siyal yon sèl fwa epi travèse tout liy yo","Ralanti nan liy ou epi tann yon espas nan tout liy yo"],"h1":"Chak liy ka gen pwòp machin pa l ak pwòp kwen ou pa wè.","h2":"Ou ta dwe chanje yon liy alafwa, mete siyal epi tcheke kwen ou pa wè a anvan chak chanjman, paske chak liy ka kache yon machin.","p":"Wi, se sa. Chanje yon liy alafwa epi mete siyal chak fwa."}},{"id":"speed-lanes-022","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"What do broken white lines between lanes mean?","o":["They separate traffic going in opposite directions","You may never cross them","They mark the edge of the road","They separate lanes going the same way, and you may change lanes when safe"],"h1":"Broken lines allow you to do something, but only when it is safe.","h2":"Broken white lines separate lanes that go the same way, and you may cross them to change lanes when it is safe.","p":"Right. Broken white lines let you change lanes when it is safe."},"es":{"q":"¿Qué significan las líneas blancas cortadas entre carriles?","o":["Separan el tráfico que va en sentidos opuestos","Nunca las puede cruzar","Marcan la orilla de la carretera","Separan carriles que van en el mismo sentido, y puede cambiar de carril cuando sea seguro"],"h1":"Las líneas cortadas le permiten hacer algo, pero solo cuando es seguro.","h2":"Las líneas blancas cortadas separan carriles que van en el mismo sentido, y puede cruzarlas para cambiar de carril cuando sea seguro.","p":"Correcto. Las líneas blancas cortadas le permiten cambiar de carril cuando es seguro."},"zh":{"q":"车道之间的白色虚线是什么意思？","o":["它们分开相反方向行驶的车","你永远不能越过它们","它们标出道路的边缘","它们分开同方向的车道，安全时你可以换道"],"h1":"虚线允许你做某件事，但只能在安全的时候。","h2":"白色虚线分开同方向的车道，安全时你可以越过它们换道。","p":"对。白色虚线表示安全时可以换道。"},"vi":{"q":"Vạch trắng đứt quãng giữa các làn có nghĩa là gì?","o":["Chúng tách các xe đi ngược chiều nhau","Bạn không bao giờ được đi qua chúng","Chúng đánh dấu mép đường","Chúng tách các làn cùng chiều, và bạn được đổi làn khi an toàn"],"h1":"Vạch đứt cho phép bạn làm một việc, nhưng chỉ khi an toàn.","h2":"Vạch trắng đứt quãng tách các làn cùng chiều, và bạn được đi qua chúng để đổi làn khi an toàn.","p":"Đúng. Vạch trắng đứt quãng cho phép bạn đổi làn khi an toàn."},"tl":{"q":"Ano ang ibig sabihin ng putol-putol na puting guhit sa pagitan ng mga lane?","o":["Pinaghihiwalay nito ang trapikong magkasalungat ang direksiyon","Hindi mo ito kailanman puwedeng tawirin","Minamarkahan nito ang gilid ng daan","Pinaghihiwalay nito ang mga lane na pareho ang direksiyon, at puwede kang lumipat ng lane kapag ligtas"],"h1":"Pinapayagan ka ng putol-putol na guhit na gumawa ng isang bagay, pero kapag ligtas lang.","h2":"Pinaghihiwalay ng putol-putol na puting guhit ang mga lane na pareho ang direksiyon, at puwede mo itong tawirin para lumipat ng lane kapag ligtas.","p":"Tama. Pinapayagan ka ng putol-putol na puting guhit na lumipat ng lane kapag ligtas."},"ar":{"q":"ماذا تعني الخطوط البيضاء المتقطعة بين المسارات؟","o":["تفصل بين سيارات تسير في اتجاهين متعاكسين","لا يجوز أبدًا أن أعبرها","تحدد طرف الطريق","تفصل بين مسارات في الاتجاه نفسه، ويمكنني أن أغيّر المسار عندما يكون آمنًا"],"h1":"الخطوط المتقطعة تسمح لك بشيء، لكن فقط عندما يكون آمنًا.","h2":"الخطوط البيضاء المتقطعة تفصل بين مسارات تسير في الاتجاه نفسه، ويمكنك أن تعبرها لتغيّر المسار عندما يكون ذلك آمنًا.","p":"صحيح. الخطوط البيضاء المتقطعة تسمح لك بتغيير المسار عندما يكون آمنًا."},"ht":{"q":"Kisa liy blan ki koupe ant liy yo vle di?","o":["Yo separe machin k ap ale nan direksyon opoze","Ou pa janm ka travèse yo","Yo make bò wout la","Yo separe liy k ap ale nan menm direksyon, epi ou ka chanje liy lè li pa danjere"],"h1":"Liy ki koupe pèmèt ou fè yon bagay, men sèlman lè li pa danjere.","h2":"Liy blan ki koupe yo separe liy k ap ale nan menm direksyon, epi ou ka travèse yo pou chanje liy lè li pa danjere.","p":"Wi, se sa. Liy blan ki koupe yo pèmèt ou chanje liy lè li pa danjere."},"ref":{"doc":"FL","page":43}},{"id":"speed-lanes-023","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you are on the ramp to enter an expressway. What should you do?","o":["Speed up in the merge lane to match traffic and yield to cars on the expressway","Stop at the end of the ramp and wait","Drive slowly so cars on the expressway can see you","Enter right away, because cars on the expressway must let you in"],"h1":"The merge lane is there to help you reach the speed of traffic.","h2":"Use the merge lane to speed up to the speed of traffic, and yield to the cars already on the expressway before you move in.","p":"Right. Match the traffic speed and yield to cars already on the expressway."},"es":{"q":"En Florida, usted va por la rampa para entrar a una autopista. ¿Qué debe hacer?","o":["Acelerar en el carril de incorporación hasta la velocidad del tráfico y ceder el paso a los carros de la autopista","Detenerse al final de la rampa y esperar","Manejar despacio para que los carros de la autopista lo vean","Entrar enseguida, porque los carros de la autopista deben dejarlo pasar"],"h1":"El carril de incorporación sirve para que alcance la velocidad del tráfico.","h2":"Use el carril de incorporación para acelerar hasta la velocidad del tráfico, y ceda el paso a los carros que ya van por la autopista antes de entrar.","p":"Correcto. Iguale la velocidad del tráfico y ceda el paso a los carros de la autopista."},"zh":{"q":"在 Florida，你在进入快速路的匝道上。你应该怎么做？","o":["在并道车道上加速，跟上车流速度，并让快速路上的车先走","在匝道尽头停下等","慢慢开，让快速路上的车能看到你","马上开进去，因为快速路上的车必须让你进去"],"h1":"并道车道是用来帮你达到车流速度的。","h2":"利用并道车道加速到车流的速度，并在并入之前让已经在快速路上的车先走。","p":"对。跟上车流速度，并让已经在快速路上的车先走。"},"vi":{"q":"Ở Florida, bạn đang ở trên đường dẫn để vào đường cao tốc. Bạn nên làm gì?","o":["Tăng tốc trong làn nhập để bằng tốc độ dòng xe và nhường xe trên đường cao tốc","Dừng ở cuối đường dẫn và chờ","Chạy chậm để xe trên đường cao tốc thấy bạn","Vào ngay, vì xe trên đường cao tốc phải cho bạn vào"],"h1":"Làn nhập có để giúp bạn đạt tốc độ của dòng xe.","h2":"Hãy dùng làn nhập để tăng tốc bằng tốc độ dòng xe, và nhường xe đã ở trên đường cao tốc trước khi bạn nhập vào.","p":"Đúng. Hãy chạy bằng tốc độ dòng xe và nhường xe đã ở trên đường cao tốc."},"tl":{"q":"Sa Florida, nasa ramp ka papasok sa expressway. Ano ang dapat mong gawin?","o":["Bumilis sa merge lane para tumugma sa trapiko at magbigay-daan sa mga kotse sa expressway","Huminto sa dulo ng ramp at maghintay","Magmaneho nang mabagal para makita ka ng mga kotse sa expressway","Pumasok agad, dahil dapat kang papasukin ng mga kotse sa expressway"],"h1":"Nariyan ang merge lane para tulungan kang maabot ang bilis ng trapiko.","h2":"Gamitin ang merge lane para bumilis hanggang sa bilis ng trapiko, at magbigay-daan sa mga kotseng nasa expressway na bago ka pumasok.","p":"Tama. Itugma ang bilis mo sa trapiko at magbigay-daan sa mga kotseng nasa expressway na."},"ar":{"q":"في Florida، أنت على منحدر الدخول إلى طريق سريع (expressway). ماذا يجب أن تفعل؟","o":["أسرع في مسار الاندماج لأصل إلى سرعة السير، وأعطي حق المرور للسيارات على الطريق السريع","أتوقف في آخر المنحدر وأنتظر","أقود ببطء حتى تراني السيارات على الطريق السريع","أدخل فورًا، لأن السيارات على الطريق السريع يجب أن تتركني أدخل"],"h1":"مسار الاندماج موجود ليساعدك على الوصول إلى سرعة السير.","h2":"استعمل مسار الاندماج لتزيد سرعتك حتى تصل إلى سرعة السير، وأعطِ حق المرور للسيارات الموجودة على الطريق السريع قبل أن تدخل.","p":"صحيح. اجعل سرعتك مثل سرعة السير وأعطِ حق المرور للسيارات الموجودة على الطريق السريع."},"ht":{"q":"Nan Florida, ou sou ranp lan pou antre sou yon otowout. Kisa ou ta dwe fè?","o":["Akselere nan liy pou antre a pou ou rive nan vitès machin yo epi kite machin ki sou otowout la pase anvan","Kanpe nan bout ranp lan epi tann","Kondi dousman pou machin ki sou otowout la ka wè ou","Antre touswit, paske machin ki sou otowout la dwe kite ou antre"],"h1":"Liy pou antre a la pou ede ou rive nan vitès machin yo.","h2":"Sèvi ak liy pou antre a pou ou akselere jiskaske ou rive nan vitès machin yo, epi kite machin ki deja sou otowout la pase anvan ou antre.","p":"Wi, se sa. Rive nan vitès machin yo epi kite machin ki deja sou otowout la pase anvan."},"ref":{"doc":"FL","page":63}},{"id":"speed-lanes-024","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, where should you slow down when you leave an expressway?","o":["In the main lane, before the exit","On the shoulder next to the exit","In the exit lane, after you leave the main lanes","Only after you reach the end of the ramp"],"h1":"Slowing down in the main lanes can surprise the drivers behind you.","h2":"You should move into the exit lane first and then slow down there, so you do not block fast traffic in the main lanes.","p":"Right. Slow down in the exit lane, not on the main road."},"es":{"q":"En Florida, ¿dónde debe bajar la velocidad al salir de una autopista?","o":["En el carril principal, antes de la salida","En el acotamiento junto a la salida","En el carril de salida, después de dejar los carriles principales","Solo al llegar al final de la rampa"],"h1":"Frenar en los carriles principales puede sorprender a los conductores de atrás.","h2":"Primero debe pasarse al carril de salida y luego bajar la velocidad allí, para no frenar al tráfico rápido en los carriles principales.","p":"Correcto. Baje la velocidad en el carril de salida, no en la vía principal."},"zh":{"q":"在 Florida，离开快速路时，你应该在哪里减速？","o":["在主车道上，出口之前","在出口旁边的路肩上","在出口车道上，离开主车道以后","只有到了匝道尽头以后"],"h1":"在主车道上减速可能会让后面的司机措手不及。","h2":"你应该先进入出口车道，然后在那里减速，这样就不会挡住主车道上开得快的车。","p":"对。在出口车道减速，不要在主路上减速。"},"vi":{"q":"Ở Florida, bạn nên giảm tốc ở đâu khi rời khỏi đường cao tốc?","o":["Trong làn chính, trước lối ra","Trên lề cạnh lối ra","Trong làn ra, sau khi bạn rời khỏi các làn chính","Chỉ sau khi bạn đến cuối đường dẫn"],"h1":"Giảm tốc trong các làn chính có thể làm người lái phía sau bất ngờ.","h2":"Bạn nên vào làn ra trước rồi mới giảm tốc ở đó, để không cản trở dòng xe chạy nhanh trong các làn chính.","p":"Đúng. Hãy giảm tốc trong làn ra, không phải trên đường chính."},"tl":{"q":"Sa Florida, saan ka dapat bumagal kapag lalabas ka sa expressway?","o":["Sa pangunahing lane, bago ang exit","Sa shoulder sa tabi ng exit","Sa exit lane, pagkaalis mo sa mga pangunahing lane","Pagdating mo lang sa dulo ng ramp"],"h1":"Ang pagbagal sa mga pangunahing lane ay maaaring makagulat sa mga drayber sa likod mo.","h2":"Dapat ka munang lumipat sa exit lane at saka bumagal doon, para hindi mo maharangan ang mabilis na trapiko sa mga pangunahing lane.","p":"Tama. Bumagal sa exit lane, hindi sa pangunahing daan."},"ar":{"q":"في Florida، أين يجب أن تخفف السرعة عندما تخرج من الطريق السريع (expressway)؟","o":["في المسار الرئيسي، قبل المخرج","على كتف الطريق بجانب المخرج","في مسار الخروج، بعد أن أترك المسارات الرئيسية","فقط بعد أن أصل إلى آخر المنحدر"],"h1":"إذا خففت السرعة في المسارات الرئيسية، قد تفاجئ السائقين الذين خلفك.","h2":"يجب أن تدخل مسار الخروج أولًا ثم تخفف السرعة فيه، حتى لا تعيق السيارات السريعة في المسارات الرئيسية.","p":"صحيح. خفف السرعة في مسار الخروج، وليس على الطريق الرئيسي."},"ht":{"q":"Nan Florida, ki kote ou ta dwe ralanti lè w ap sòti sou yon otowout?","o":["Nan liy prensipal la, anvan sòti a","Sou bò wout la, bò kote sòti a","Nan liy sòti a, apre ou fin kite liy prensipal yo","Sèlman apre ou rive nan bout ranp lan"],"h1":"Si ou ralanti nan liy prensipal yo, ou ka sezi chofè ki dèyè ou yo.","h2":"Ou ta dwe antre nan liy sòti a anvan, epi ralanti la, pou ou pa bloke machin k ap kouri vit nan liy prensipal yo.","p":"Wi, se sa. Ralanti nan liy sòti a, pa sou wout prensipal la."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-025","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You missed your exit on the expressway. What should you do?","o":["Back up on the shoulder to the exit","Make a U-turn across the median","Keep going to the next exit","Stop and wait for traffic to clear"],"h1":"Backing up or turning around on a fast road is very dangerous.","h2":"If you miss your exit, keep driving to the next exit, because backing up or turning around on an expressway can cause a serious crash.","p":"Right. Missed your exit? Just go on to the next one."},"es":{"q":"Se le pasó la salida en la autopista. ¿Qué debe hacer?","o":["Dar reversa por el acotamiento hasta la salida","Dar vuelta en U por la división central","Seguir hasta la próxima salida","Detenerse y esperar a que pase el tráfico"],"h1":"Dar reversa o dar la vuelta en una vía rápida es muy peligroso.","h2":"Si se le pasa la salida, siga hasta la próxima salida, porque dar reversa o dar la vuelta en una autopista puede causar un choque grave.","p":"Correcto. ¿Se le pasó la salida? Siga hasta la próxima."},"zh":{"q":"你在快速路上错过了出口。你应该怎么做？","o":["在路肩上倒车回到出口","穿过中间隔离带掉头","继续开到下一个出口","停下来，等车流过去"],"h1":"在快速道路上倒车或掉头非常危险。","h2":"如果你错过了出口，就继续开到下一个出口，因为在快速路上倒车或掉头可能会造成严重车祸。","p":"对。错过出口了？就开到下一个出口。"},"vi":{"q":"Bạn đã đi lố lối ra trên đường cao tốc. Bạn nên làm gì?","o":["Lùi xe trên lề về lối ra","Quay đầu chữ U qua dải phân cách","Chạy tiếp đến lối ra kế tiếp","Dừng lại và chờ hết xe"],"h1":"Lùi xe hoặc quay đầu trên đường chạy nhanh là rất nguy hiểm.","h2":"Nếu bạn đi lố lối ra, hãy chạy tiếp đến lối ra kế tiếp, vì lùi xe hoặc quay đầu trên đường cao tốc có thể gây tai nạn nghiêm trọng.","p":"Đúng. Đi lố lối ra? Cứ chạy đến lối ra kế tiếp."},"tl":{"q":"Nalampasan mo ang exit mo sa expressway. Ano ang dapat mong gawin?","o":["Umatras sa shoulder papunta sa exit","Mag-U-turn sa kabila ng median","Magpatuloy hanggang sa susunod na exit","Huminto at hintaying lumuwag ang trapiko"],"h1":"Napakadelikado ang pag-atras o pag-ikot pabalik sa mabilis na daan.","h2":"Kung nalampasan mo ang exit mo, magpatuloy hanggang sa susunod na exit, dahil ang pag-atras o pag-ikot pabalik sa expressway ay maaaring magdulot ng malubhang banggaan.","p":"Tama. Nalampasan ang exit? Magpatuloy lang sa susunod."},"ar":{"q":"فاتك المخرج على الطريق السريع. ماذا يجب أن تفعل؟","o":["أرجع إلى الخلف على كتف الطريق حتى المخرج","أقوم بدوران كامل للخلف (U-turn) عبر الفاصل في الوسط","أستمر حتى المخرج التالي","أتوقف وأنتظر حتى يصبح الطريق فارغًا"],"h1":"الرجوع إلى الخلف أو الدوران على طريق سريع خطير جدًا.","h2":"إذا فاتك المخرج، استمر في القيادة حتى المخرج التالي، لأن الرجوع إلى الخلف أو الدوران على الطريق السريع قد يسبب حادثًا خطيرًا.","p":"صحيح. فاتك المخرج؟ استمر ببساطة إلى المخرج التالي."},"ht":{"q":"Ou rate sòti ou a sou otowout la. Kisa ou ta dwe fè?","o":["Fè bak sou bò wout la jis rive nan sòti a","Fè demi-tou atravè separasyon ki nan mitan an","Kontinye jis rive nan pwochen sòti a","Kanpe epi tann sikilasyon an vin lib"],"h1":"Fè bak oswa fè demi-tou sou yon wout rapid trè danjere.","h2":"Si ou rate sòti ou a, kontinye kondi jis rive nan pwochen sòti a, paske fè bak oswa fè demi-tou sou yon otowout ka lakòz yon gwo aksidan.","p":"Wi, se sa. Ou rate sòti ou a? Kontinye jis nan pwochen an."},"ref":{"doc":"FL","page":64}},{"id":"speed-lanes-026","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a ramp has a traffic signal (ramp meter) before the expressway. How do you use it?","o":["Wait for green, then one car goes on each green light","All cars in line go on one green light","Ignore it if the expressway looks empty","Go on yellow, stop on green"],"h1":"The signal lets cars onto the expressway a little at a time.","h2":"At a ramp meter, wait for the green light, and then only one car goes for each green unless a sign says otherwise.","p":"Right. At a ramp meter, one car goes on each green light."},"es":{"q":"En Florida, una rampa tiene un semáforo (medidor de rampa) antes de la autopista. ¿Cómo se usa?","o":["Espere la luz verde; pasa un carro con cada luz verde","Todos los carros de la fila pasan con una sola luz verde","Ignórelo si la autopista se ve vacía","Pase con luz amarilla y deténgase con luz verde"],"h1":"El semáforo deja entrar los carros a la autopista poco a poco.","h2":"En un medidor de rampa, espere la luz verde, y luego pasa solo un carro con cada luz verde, a menos que un letrero diga otra cosa.","p":"Correcto. En el medidor de rampa, pasa un carro con cada luz verde."},"zh":{"q":"在 Florida，一条匝道在进入快速路前有一个交通信号灯（匝道信号灯）。你该怎么用它？","o":["等绿灯，每次绿灯走一辆车","排队的所有车在一次绿灯时一起走","如果快速路看起来没车，就不用管它","黄灯走，绿灯停"],"h1":"这个信号灯让车一点一点地进入快速路。","h2":"在匝道信号灯前，要等绿灯，除非有标志另外规定，每次绿灯只走一辆车。","p":"对。在匝道信号灯前，每次绿灯走一辆车。"},"vi":{"q":"Ở Florida, một đường dẫn có đèn giao thông (đèn điều tiết) trước khi vào đường cao tốc. Bạn dùng đèn này thế nào?","o":["Chờ đèn xanh, rồi mỗi lần đèn xanh thì một xe đi","Tất cả các xe đang xếp hàng đi trong một lần đèn xanh","Bỏ qua nếu đường cao tốc trông vắng","Đi khi đèn vàng, dừng khi đèn xanh"],"h1":"Đèn này cho xe vào đường cao tốc từng chút một.","h2":"Tại đèn điều tiết, hãy chờ đèn xanh, và mỗi lần đèn xanh chỉ có một xe đi, trừ khi biển báo nói khác.","p":"Đúng. Tại đèn điều tiết, mỗi lần đèn xanh một xe đi."},"tl":{"q":"Sa Florida, may ilaw trapiko (ramp meter) ang ramp bago ang expressway. Paano mo ito gagamitin?","o":["Hintayin ang berde, at isang kotse ang aandar sa bawat berdeng ilaw","Aandar ang lahat ng kotse sa pila sa isang berdeng ilaw","Huwag pansinin kung mukhang walang laman ang expressway","Umandar sa dilaw, huminto sa berde"],"h1":"Pinapapasok ng ilaw ang mga kotse sa expressway nang paisa-isa.","h2":"Sa ramp meter, hintayin ang berdeng ilaw, at isang kotse lang ang aandar sa bawat berde maliban kung may karatulang nagsasabi ng iba.","p":"Tama. Sa ramp meter, isang kotse ang aandar sa bawat berdeng ilaw."},"ar":{"q":"في Florida، على منحدر الدخول توجد إشارة ضوئية (ramp meter) قبل الطريق السريع. كيف تستعملها؟","o":["أنتظر الضوء الأخضر، ثم تمر سيارة واحدة مع كل ضوء أخضر","كل السيارات في الطابور تمر مع ضوء أخضر واحد","أتجاهلها إذا كان الطريق السريع يبدو فارغًا","أتحرك مع الأصفر، وأتوقف مع الأخضر"],"h1":"هذه الإشارة تُدخل السيارات إلى الطريق السريع قليلًا قليلًا.","h2":"عند إشارة ramp meter، انتظر الضوء الأخضر، ثم تمر سيارة واحدة فقط مع كل ضوء أخضر، إلا إذا قالت علامة غير ذلك.","p":"صحيح. عند إشارة ramp meter، تمر سيارة واحدة مع كل ضوء أخضر."},"ht":{"q":"Nan Florida, yon ranp gen yon limyè (ramp meter) anvan otowout la. Kijan ou sèvi ak li?","o":["Tann limyè vèt la, epi yon sèl machin pase chak fwa limyè a vin vèt","Tout machin ki nan liy lan pase sou yon sèl limyè vèt","Pa okipe l si otowout la sanble vid","Pase sou limyè jòn, kanpe sou limyè vèt"],"h1":"Limyè a kite machin yo antre sou otowout la ti kras pa ti kras.","h2":"Nan yon limyè sou ranp, tann limyè vèt la, epi se yon sèl machin ki pase pou chak limyè vèt, sòf si yon siy di lòt bagay.","p":"Wi, se sa. Nan yon limyè sou ranp, yon sèl machin pase pou chak limyè vèt."},"ref":{"doc":"FL","page":53}},{"id":"speed-lanes-027","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you are in the left lane of a multi-lane highway. A faster car comes up behind you. What must you do?","o":["Stay in the left lane at the speed limit","Speed up to stay ahead of it","Tap your brakes to slow it down","Move to the right when it is safe and let it pass"],"h1":"On a highway with several lanes, the left lane is mainly for passing.","h2":"Florida law says that if a faster car is coming up behind you in the left lane, you must move right when it is safe and let it pass.","p":"Right. In the left lane, move right for faster traffic behind you."},"es":{"q":"En Florida, usted va por el carril izquierdo de una carretera de varios carriles. Un carro más rápido se acerca por detrás. ¿Qué debe hacer?","o":["Quedarse en el carril izquierdo al límite de velocidad","Acelerar para seguir delante de él","Frenar un poco para que baje la velocidad","Pasarse a la derecha cuando sea seguro y dejarlo pasar"],"h1":"En una carretera de varios carriles, el carril izquierdo es sobre todo para rebasar.","h2":"La ley de Florida dice que si un carro más rápido se acerca por detrás en el carril izquierdo, debe pasarse a la derecha cuando sea seguro y dejarlo pasar.","p":"Correcto. En el carril izquierdo, muévase a la derecha si viene alguien más rápido."},"zh":{"q":"在 Florida，你在多车道公路的左边车道。一辆更快的车从你后面开过来。你必须怎么做？","o":["以限速留在左边车道","加速，保持在它前面","点一下刹车，让它慢下来","在安全时移到右边，让它超过去"],"h1":"在有好几条车道的公路上，左边车道主要是用来超车的。","h2":"Florida 法律规定，如果在左边车道有一辆更快的车从你后面开过来，你必须在安全时移到右边，让它超过去。","p":"对。在左边车道时，要给后面更快的车让到右边。"},"vi":{"q":"Ở Florida, bạn đang ở làn trái của xa lộ nhiều làn. Một xe nhanh hơn đến phía sau bạn. Bạn phải làm gì?","o":["Ở lại làn trái và chạy đúng giới hạn tốc độ","Tăng tốc để chạy trước xe đó","Đạp nhẹ phanh để xe đó chậm lại","Chuyển sang phải khi an toàn và để xe đó vượt"],"h1":"Trên xa lộ có nhiều làn, làn trái chủ yếu dùng để vượt.","h2":"Luật Florida nói nếu có xe nhanh hơn đến phía sau bạn ở làn trái, bạn phải chuyển sang phải khi an toàn và để xe đó vượt.","p":"Đúng. Ở làn trái, hãy chuyển sang phải cho xe nhanh hơn phía sau."},"tl":{"q":"Sa Florida, nasa kaliwang lane ka ng highway na maraming lane. May mas mabilis na kotseng paparating sa likod mo. Ano ang dapat mong gawin?","o":["Manatili sa kaliwang lane sa speed limit","Bumilis para manatiling nauuna rito","Tapik-tapikin ang preno para pabagalin ito","Lumipat pakanan kapag ligtas at hayaan itong lumampas"],"h1":"Sa highway na maraming lane, ang kaliwang lane ay pangunahing para sa paglampas.","h2":"Sinasabi ng batas ng Florida na kung may mas mabilis na kotseng paparating sa likod mo sa kaliwang lane, dapat kang lumipat pakanan kapag ligtas at hayaan itong lumampas.","p":"Tama. Sa kaliwang lane, lumipat pakanan para sa mas mabilis na trapiko sa likod mo."},"ar":{"q":"في Florida، أنت في المسار الأيسر على طريق سريع فيه عدة مسارات. سيارة أسرع تقترب من خلفك. ماذا يجب أن تفعل؟","o":["أبقى في المسار الأيسر بسرعة الحد","أسرع لأبقى أمامها","أضغط على الفرامل قليلًا لأجعلها تبطئ","أنتقل إلى اليمين عندما يكون آمنًا وأتركها تتجاوزني"],"h1":"على طريق سريع فيه عدة مسارات، المسار الأيسر هو أساسًا للتجاوز.","h2":"يقول قانون Florida إنه إذا اقتربت سيارة أسرع من خلفك في المسار الأيسر، يجب أن تنتقل إلى اليمين عندما يكون آمنًا وتتركها تتجاوزك.","p":"صحيح. في المسار الأيسر، انتقل إلى اليمين للسيارات الأسرع التي خلفك."},"ht":{"q":"Nan Florida, ou nan liy gòch yon gran wout ki gen plizyè liy. Yon machin ki pi rapid rive dèyè ou. Kisa ou dwe fè?","o":["Rete nan liy gòch la a limit vitès la","Akselere pou rete devan l","Peze fren an ti kras pou fè l ralanti","Deplase sou bò dwat lè li pa danjere epi kite l pase"],"h1":"Sou yon gran wout ki gen plizyè liy, liy gòch la se sitou pou double.","h2":"Lwa Florida di si yon machin ki pi rapid ap rive dèyè ou nan liy gòch la, ou dwe deplase sou bò dwat lè li pa danjere epi kite l pase.","p":"Wi, se sa. Nan liy gòch la, deplase sou bò dwat pou machin ki pi rapid dèyè ou."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-029","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, when must your headlights be on?","o":["Only after midnight","From sunset to sunrise","Only on unlit country roads","Only when another car flashes its lights"],"h1":"Think about the hours when it gets dark outside.","h2":"In Florida your headlights must be on from sunset to sunrise, so you can see and others can see you.","p":"Right. Headlights go on from sunset to sunrise."},"es":{"q":"En Florida, ¿cuándo deben estar encendidas las luces delanteras?","o":["Solo después de la medianoche","Desde la puesta del sol hasta la salida del sol","Solo en caminos rurales sin luz","Solo cuando otro carro le hace cambio de luces"],"h1":"Piense en las horas en que oscurece afuera.","h2":"En Florida sus luces delanteras deben estar encendidas desde la puesta del sol hasta la salida del sol, para que usted vea y lo vean.","p":"Correcto. Las luces van encendidas desde la puesta hasta la salida del sol."},"zh":{"q":"在 Florida，什么时候必须开大灯？","o":["只在半夜以后","从日落到日出","只在没有路灯的乡村道路上","只在别的车对你闪灯时"],"h1":"想一想外面天黑的时间。","h2":"在 Florida，从日落到日出你必须开大灯，这样你能看清路，别人也能看到你。","p":"对。从日落到日出要开大灯。"},"vi":{"q":"Ở Florida, khi nào bạn phải bật đèn pha?","o":["Chỉ sau nửa đêm","Từ lúc mặt trời lặn đến lúc mặt trời mọc","Chỉ trên đường quê không có đèn","Chỉ khi xe khác nháy đèn với bạn"],"h1":"Hãy nghĩ đến những giờ trời tối bên ngoài.","h2":"Ở Florida, đèn pha của bạn phải bật từ lúc mặt trời lặn đến lúc mặt trời mọc, để bạn nhìn thấy và người khác thấy bạn.","p":"Đúng. Bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc."},"tl":{"q":"Sa Florida, kailan dapat nakabukas ang headlights mo?","o":["Pagkatapos lang ng hatinggabi","Mula paglubog ng araw hanggang pagsikat ng araw","Sa madidilim na daan lang sa probinsiya","Kapag nag-flash lang ng ilaw ang ibang kotse"],"h1":"Isipin ang mga oras na dumidilim sa labas.","h2":"Sa Florida, dapat nakabukas ang headlights mo mula paglubog ng araw hanggang pagsikat ng araw, para makakita ka at makita ka ng iba.","p":"Tama. Bukas ang headlights mula paglubog hanggang pagsikat ng araw."},"ar":{"q":"في Florida، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["فقط بعد منتصف الليل","من غروب الشمس إلى شروقها","فقط على الطرق الريفية غير المضاءة","فقط عندما تومض سيارة أخرى بأضوائها"],"h1":"فكّر في الساعات التي يصبح فيها الجو مظلمًا في الخارج.","h2":"في Florida يجب أن تكون المصابيح الأمامية مضاءة من غروب الشمس إلى شروقها، حتى ترى أنت ويراك الآخرون.","p":"صحيح. المصابيح الأمامية تُضاء من غروب الشمس إلى شروقها."},"ht":{"q":"Nan Florida, kilè limyè devan machin ou dwe limen?","o":["Sèlman apre minwi","Depi solèy kouche jiskaske solèy leve","Sèlman sou wout andeyò ki pa gen limyè","Sèlman lè yon lòt machin flache limyè l"],"h1":"Panse ak lè li fè nwa deyò.","h2":"Nan Florida limyè devan machin ou dwe limen depi solèy kouche jiskaske solèy leve, pou ou ka wè epi pou lòt moun ka wè ou.","p":"Wi, se sa. Limyè devan yo limen depi solèy kouche jiskaske solèy leve."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-030","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, it is daytime but rain, smoke, or fog makes it hard to see. What must you do with your headlights?","o":["Leave them off because it is daytime","Turn on only your parking lights","Turn on your hazard lights and keep driving","Turn them on"],"h1":"Lights help other drivers see you, not only help you see.","h2":"In Florida you must turn on your headlights during rain, smoke, or fog, even in the daytime, so other drivers can see you.","p":"Right. Rain, smoke, or fog means headlights on, even by day."},"es":{"q":"En Florida, es de día pero la lluvia, el humo o la neblina hacen difícil ver. ¿Qué debe hacer con las luces delanteras?","o":["Dejarlas apagadas porque es de día","Encender solo las luces de estacionamiento","Encender las luces intermitentes y seguir manejando","Encenderlas"],"h1":"Las luces ayudan a que otros lo vean, no solo a que usted vea.","h2":"En Florida debe encender las luces delanteras con lluvia, humo o neblina, aunque sea de día, para que los demás conductores lo vean.","p":"Correcto. Con lluvia, humo o neblina, encienda las luces, aunque sea de día."},"zh":{"q":"在 Florida，现在是白天，但下雨、有烟或有雾，看不清楚。你的大灯必须怎么处理？","o":["关着，因为是白天","只开停车灯","开双闪灯，继续开","把大灯打开"],"h1":"车灯不只帮你看清，也帮别的司机看到你。","h2":"在 Florida，下雨、有烟或有雾时，就算是白天，你也必须打开大灯，让别的司机能看到你。","p":"对。下雨、有烟或有雾，就算白天也要开大灯。"},"vi":{"q":"Ở Florida, đang ban ngày nhưng mưa, khói hoặc sương mù làm khó nhìn. Bạn phải làm gì với đèn pha?","o":["Để tắt vì đang là ban ngày","Chỉ bật đèn đậu xe","Bật đèn khẩn cấp và tiếp tục chạy","Bật đèn pha lên"],"h1":"Đèn giúp người lái khác thấy bạn, không chỉ giúp bạn nhìn thấy.","h2":"Ở Florida, bạn phải bật đèn pha khi có mưa, khói hoặc sương mù, kể cả ban ngày, để người lái khác thấy bạn.","p":"Đúng. Mưa, khói hoặc sương mù thì phải bật đèn pha, kể cả ban ngày."},"tl":{"q":"Sa Florida, araw pa pero dahil sa ulan, usok, o fog (hamog) ay mahirap makakita. Ano ang dapat mong gawin sa headlights mo?","o":["Iwanang nakapatay dahil araw pa","Buksan lang ang parking lights mo","Buksan ang hazard lights mo at magpatuloy","Buksan ang mga ito"],"h1":"Tinutulungan ng ilaw ang ibang drayber na makita ka, hindi lang ikaw na makakita.","h2":"Sa Florida, dapat mong buksan ang headlights mo kapag may ulan, usok, o fog, kahit araw pa, para makita ka ng ibang drayber.","p":"Tama. Kapag may ulan, usok, o fog, buksan ang headlights, kahit araw."},"ar":{"q":"في Florida، الوقت نهار، لكن المطر أو الدخان أو الضباب يجعل الرؤية صعبة. ماذا يجب أن تفعل بالمصابيح الأمامية؟","o":["أتركها مطفأة لأن الوقت نهار","أشغّل أضواء الوقوف فقط","أشغّل أضواء الخطر وأستمر في القيادة","أشغّلها"],"h1":"الأضواء تساعد السائقين الآخرين على رؤيتك، وليس فقط تساعدك على الرؤية.","h2":"في Florida يجب أن تشغّل المصابيح الأمامية في المطر أو الدخان أو الضباب، حتى في النهار، حتى يراك السائقون الآخرون.","p":"صحيح. المطر أو الدخان أو الضباب يعني أن تشغّل المصابيح الأمامية، حتى في النهار."},"ht":{"q":"Nan Florida, li fè jou men lapli, lafimen oswa bwouya fè li difisil pou wè. Kisa ou dwe fè ak limyè devan ou yo?","o":["Kite yo etenn paske li fè jou","Limen sèlman ti limyè pakin yo","Limen limyè ijans ou yo (flachè) epi kontinye kondi","Limen yo"],"h1":"Limyè yo ede lòt chofè yo wè ou, se pa sèlman ede ou wè.","h2":"Nan Florida ou dwe limen limyè devan ou yo lè gen lapli, lafimen oswa bwouya, menm lajounen, pou lòt chofè yo ka wè ou.","p":"Wi, se sa. Lapli, lafimen oswa bwouya vle di limen limyè yo, menm lajounen."},"ref":{"doc":"FL","page":71}},{"id":"speed-lanes-031","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, a car is coming toward you at night. How close can it get before you must dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Bright lights can blind the other driver from far away.","h2":"In Florida you must switch to low beams when an oncoming car is within 500 feet, so you do not blind its driver.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Florida, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Las luces altas pueden encandilar al otro conductor desde lejos.","h2":"En Florida debe cambiar a luces bajas cuando un carro que viene de frente está a 500 pies o menos, para no encandilar al conductor.","p":"Correcto. Cambie a luces bajas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Florida，晚上有一辆车迎面开过来。它离你多近时，你必须把远光灯换成近光灯？","o":["500 英尺","100 英尺","200 英尺","1,000 英尺"],"h1":"很亮的灯从很远的地方就能晃到对面的司机。","h2":"在 Florida，当对面来车在 500 英尺以内时，你必须换成近光灯，这样才不会晃到对方司机。","p":"对。对面来车在 500 英尺以内时，要关掉远光灯。"},"vi":{"q":"Ở Florida, ban đêm có một xe đang chạy ngược chiều về phía bạn. Xe đó đến gần bao nhiêu thì bạn phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Đèn sáng có thể làm người lái kia bị chói từ rất xa.","h2":"Ở Florida, bạn phải chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet, để không làm người lái đó bị chói mắt.","p":"Đúng. Hãy chuyển sang đèn cốt khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Florida, may kotseng paparating sa harap mo sa gabi. Gaano ito kalapit bago mo dapat ibaba ang high beams mo?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"Kayang silawin ng malakas na ilaw ang ibang drayber mula sa malayo.","h2":"Sa Florida, dapat kang lumipat sa low beams kapag ang paparating na kotse ay nasa loob ng 500 feet, para hindi mo masilaw ang drayber nito.","p":"Tama. Ibaba ang high beams mo sa loob ng 500 feet ng paparating na kotse."},"ar":{"q":"في Florida، سيارة قادمة نحوك في الليل. كم يمكن أن تقترب قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["500 قدم","100 قدم","200 قدم","1,000 قدم"],"h1":"الأضواء القوية يمكن أن تُعمي السائق الآخر من مسافة بعيدة.","h2":"في Florida يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على مسافة 500 قدم أو أقل، حتى لا تُعمي سائقها.","p":"صحيح. اخفض الأضواء العالية عندما تكون السيارة القادمة على مسافة 500 قدم أو أقل."},"ht":{"q":"Nan Florida, yon machin ap vin sou ou lannwit. A ki distans li ka rive anvan ou dwe bese gwo limyè ou yo?","o":["500 pye","100 pye","200 pye","1,000 pye"],"h1":"Gwo limyè yo ka avegle lòt chofè a depi byen lwen.","h2":"Nan Florida ou dwe pase sou ti limyè yo lè yon machin k ap vin sou ou rive nan 500 pye, pou ou pa avegle chofè a.","p":"Wi, se sa. Bese gwo limyè ou yo lè yon machin k ap vin sou ou rive nan 500 pye."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-032","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, you are driving behind another car at night. How close can you get before you must dim your high beams?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Your bright lights shine into the other driver's mirrors.","h2":"In Florida you must use low beams when you are within 300 feet of a car ahead of you, so your lights do not blind the driver through the mirrors.","p":"Right. Dim your lights within 300 feet of a car you are following."},"es":{"q":"En Florida, de noche usted va detrás de otro carro. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","300 pies","700 pies"],"h1":"Sus luces altas se reflejan en los espejos del otro conductor.","h2":"En Florida debe usar luces bajas cuando está a 300 pies o menos del carro de adelante, para no encandilar al conductor por los espejos.","p":"Correcto. Cambie a luces bajas a 300 pies del carro que va adelante."},"zh":{"q":"在 Florida，你晚上跟在另一辆车后面开。你离它多近时，必须把远光灯换成近光灯？","o":["50 英尺","100 英尺","300 英尺","700 英尺"],"h1":"你的远光灯会照进对方司机的后视镜。","h2":"在 Florida，当你离前面的车在 300 英尺以内时，你必须用近光灯，这样你的灯就不会通过后视镜晃到对方司机。","p":"对。跟车在 300 英尺以内时，要换成近光灯。"},"vi":{"q":"Ở Florida, ban đêm bạn đang chạy sau một xe khác. Bạn đến gần bao nhiêu thì phải chuyển đèn pha sang đèn cốt (đèn chiếu gần)?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Đèn sáng của bạn chiếu vào gương của người lái kia.","h2":"Ở Florida, bạn phải dùng đèn cốt khi bạn ở trong vòng 300 feet sau một xe phía trước, để đèn của bạn không làm người lái đó bị chói qua gương.","p":"Đúng. Hãy chuyển sang đèn cốt khi ở trong vòng 300 feet sau xe bạn đang theo."},"tl":{"q":"Sa Florida, nagmamaneho ka sa likod ng ibang kotse sa gabi. Gaano ka kalapit bago mo dapat ibaba ang high beams mo?","o":["50 feet","100 feet","300 feet","700 feet"],"h1":"Tumatama ang malakas mong ilaw sa mga salamin ng ibang drayber.","h2":"Sa Florida, dapat kang gumamit ng low beams kapag nasa loob ka ng 300 feet ng kotse sa unahan mo, para hindi masilaw ang drayber dahil sa mga salamin nito.","p":"Tama. Ibaba ang ilaw mo sa loob ng 300 feet ng kotseng sinusundan mo."},"ar":{"q":"في Florida، تقود خلف سيارة أخرى في الليل. كم يمكن أن تقترب منها قبل أن يجب عليك أن تخفض الأضواء العالية؟","o":["50 قدمًا","100 قدم","300 قدم","700 قدم"],"h1":"أضواؤك القوية تلمع في مرايا السائق الآخر.","h2":"في Florida يجب أن تستعمل الأضواء المنخفضة عندما تكون على مسافة 300 قدم أو أقل من سيارة أمامك، حتى لا تُعمي أضواؤك السائق من خلال المرايا.","p":"صحيح. اخفض أضواءك عندما تكون على مسافة 300 قدم أو أقل من سيارة تسير خلفها."},"ht":{"q":"Nan Florida, w ap kondi dèyè yon lòt machin lannwit. A ki distans ou ka rive anvan ou dwe bese gwo limyè ou yo?","o":["50 pye","100 pye","300 pye","700 pye"],"h1":"Gwo limyè ou yo klere nan retwovizè lòt chofè a.","h2":"Nan Florida ou dwe sèvi ak ti limyè yo lè ou nan 300 pye dèyè yon machin ki devan ou, pou limyè ou yo pa avegle chofè a nan retwovizè l.","p":"Wi, se sa. Bese limyè ou yo lè ou nan 300 pye dèyè yon machin w ap swiv."},"ref":{"doc":"FL","page":73}},{"id":"speed-lanes-033","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are driving in thick fog. Which lights should you use?","o":["High beams","Parking lights only","Low beams","No lights"],"h1":"Fog reflects strong light back into your eyes.","h2":"In fog you should use low beams, because high beams bounce off the fog and make it harder to see.","p":"Right. Use low beams in fog."},"es":{"q":"Usted maneja con neblina espesa. ¿Qué luces debe usar?","o":["Luces altas","Solo luces de estacionamiento","Luces bajas","Ninguna luz"],"h1":"La neblina refleja la luz fuerte hacia sus ojos.","h2":"Con neblina debe usar luces bajas, porque las luces altas rebotan en la neblina y hacen más difícil ver.","p":"Correcto. Use luces bajas con neblina."},"zh":{"q":"你在浓雾里开车。你应该用哪种灯？","o":["远光灯","只开停车灯","近光灯","不开灯"],"h1":"雾会把强光反射回你的眼睛。","h2":"在雾里你应该用近光灯，因为远光灯会被雾反射回来，让你更看不清。","p":"对。有雾时用近光灯。"},"vi":{"q":"Bạn đang lái xe trong sương mù dày. Bạn nên dùng đèn nào?","o":["Đèn pha (đèn chiếu xa)","Chỉ đèn đậu xe","Đèn cốt (đèn chiếu gần)","Không bật đèn"],"h1":"Sương mù phản chiếu ánh sáng mạnh ngược lại vào mắt bạn.","h2":"Trong sương mù, bạn nên dùng đèn cốt, vì đèn chiếu xa dội lại từ sương mù và làm bạn khó nhìn hơn.","p":"Đúng. Hãy dùng đèn cốt khi có sương mù."},"tl":{"q":"Nagmamaneho ka sa makapal na fog (hamog). Anong ilaw ang dapat mong gamitin?","o":["High beams","Parking lights lang","Low beams","Walang ilaw"],"h1":"Ibinabalik ng fog ang malakas na ilaw sa mga mata mo.","h2":"Sa fog, dapat kang gumamit ng low beams, dahil tumatalbog ang high beams sa fog at lalo kang nahihirapang makakita.","p":"Tama. Gumamit ng low beams sa fog."},"ar":{"q":"تقود في ضباب كثيف. أي أضواء يجب أن تستعمل؟","o":["الأضواء العالية","أضواء الوقوف فقط","الأضواء المنخفضة","بدون أضواء"],"h1":"الضباب يعكس الضوء القوي إلى عينيك.","h2":"في الضباب يجب أن تستعمل الأضواء المنخفضة، لأن الأضواء العالية ترتد عن الضباب وتجعل الرؤية أصعب.","p":"صحيح. استعمل الأضواء المنخفضة في الضباب."},"ht":{"q":"W ap kondi nan yon bwouya ki epè. Ki limyè ou ta dwe sèvi?","o":["Gwo limyè yo","Ti limyè pakin yo sèlman","Ti limyè yo (limyè ba)","Okenn limyè"],"h1":"Bwouya voye limyè ki fò tounen nan je ou.","h2":"Nan bwouya ou ta dwe sèvi ak ti limyè yo, paske gwo limyè yo frape bwouya a epi yo fè li pi difisil pou wè.","p":"Wi, se sa. Sèvi ak ti limyè yo nan bwouya."},"ref":{"doc":"FL","page":72}},{"id":"speed-lanes-034","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Florida you may not park within 15 feet of a fire hydrant, so firefighters can reach it quickly.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Florida, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies"],"h1":"Los bomberos necesitan espacio para conectar las mangueras.","h2":"En Florida no puede estacionarse a menos de 15 pies de un hidrante, para que los bomberos lleguen rápido a él.","p":"Correcto. Estaciónese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Florida，停车时离消防栓最近可以多近？","o":["不能少于 15 英尺","不能少于 5 英尺","不能少于 10 英尺","不能少于 30 英尺"],"h1":"消防车需要空间接上水管。","h2":"在 Florida，你不能停在离消防栓 15 英尺以内的地方，这样消防员才能很快用到它。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 30 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vòi nước.","h2":"Ở Florida, bạn không được đậu xe trong vòng 15 feet từ trụ nước cứu hỏa, để lính cứu hỏa có thể đến đó nhanh.","p":"Đúng. Hãy đậu cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangan ng mga trak ng bumbero ng lugar para ikabit ang kanilang hose.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant, para mabilis itong maabot ng mga bumbero.","p":"Tama. Lumayo nang hindi bababa sa 15 feet sa fire hydrant."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من حنفية إطفاء الحريق عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا"],"h1":"سيارات الإطفاء تحتاج إلى مكان لتوصل خراطيمها.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 15 قدمًا من حنفية إطفاء الحريق، حتى يصل إليها رجال الإطفاء بسرعة.","p":"صحيح. ابقَ على مسافة 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ht":{"q":"Nan Florida, a ki distans de yon bouch dlo ponpye (fire hydrant) ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 30 pye"],"h1":"Kamyon ponpye yo bezwen plas pou konekte tiyo yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 15 pye de yon bouch dlo ponpye, pou ponpye yo ka rive ladan l vit.","p":"Wi, se sa. Rete omwen 15 pye lwen yon bouch dlo ponpye."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-035","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Drivers must be able to see people who are walking across.","h2":"In Florida you may not park within 20 feet of a crosswalk at an intersection, so drivers can see people crossing.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Florida, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Los conductores deben poder ver a las personas que cruzan caminando.","h2":"En Florida no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, para que los conductores vean a quienes cruzan.","p":"Correcto. Estaciónese al menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Florida，停车时离路口的人行横道最近可以多近？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 50 英尺","不能少于 20 英尺"],"h1":"司机必须能看到正在过马路的人。","h2":"在 Florida，你不能停在离路口人行横道 20 英尺以内的地方，这样司机才能看到过马路的人。","p":"对。停车时离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần lối qua đường cho người đi bộ tại giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 50 feet","Không gần hơn 20 feet"],"h1":"Người lái phải nhìn thấy được người đang đi bộ qua đường.","h2":"Ở Florida, bạn không được đậu xe trong vòng 20 feet từ lối qua đường tại giao lộ, để người lái có thể thấy người đi bộ qua đường.","p":"Đúng. Hãy đậu cách lối qua đường tại giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 20 feet"],"h1":"Dapat makita ng mga drayber ang mga taong tumatawid.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa crosswalk sa intersection, para makita ng mga drayber ang mga tumatawid.","p":"Tama. Pumarada nang hindi bababa sa 20 feet ang layo sa crosswalk sa intersection."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من ممر مشاة عند تقاطع عندما تركن سيارتك؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 50 قدمًا","ليس أقرب من 20 قدمًا"],"h1":"يجب أن يستطيع السائقون رؤية الناس الذين يعبرون.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 20 قدمًا من ممر مشاة عند تقاطع، حتى يرى السائقون الناس الذين يعبرون.","p":"صحيح. اركن على مسافة 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ht":{"q":"Nan Florida, a ki distans de yon pasaj pyeton nan yon kafou ou ka pake?","o":["Pa pi pre pase 5 pye","Pa pi pre pase 10 pye","Pa pi pre pase 50 pye","Pa pi pre pase 20 pye"],"h1":"Chofè yo dwe ka wè moun k ap travèse yo.","h2":"Nan Florida ou pa ka pake nan mwens pase 20 pye de yon pasaj pyeton nan yon kafou, pou chofè yo ka wè moun k ap travèse yo.","p":"Wi, se sa. Pake omwen 20 pye lwen yon pasaj pyeton nan yon kafou."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-036","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 30 feet","No closer than 15 feet","No closer than 100 feet"],"h1":"A parked car could hide the sign from other drivers.","h2":"In Florida you may not park within 30 feet of a stop sign, so other drivers can see the sign clearly.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Florida, ¿qué tan cerca de un letrero de PARE puede estacionarse?","o":["No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies","No a menos de 100 pies"],"h1":"Un carro estacionado podría tapar el letrero para otros conductores.","h2":"En Florida no puede estacionarse a menos de 30 pies de un letrero de PARE, para que los demás conductores lo vean bien.","p":"Correcto. Estaciónese al menos a 30 pies de un letrero de PARE."},"zh":{"q":"在 Florida，停车时离停车标志最近可以多近？","o":["不能少于 10 英尺","不能少于 30 英尺","不能少于 15 英尺","不能少于 100 英尺"],"h1":"停着的车可能会挡住标志，让别的司机看不到。","h2":"在 Florida，你不能停在离停车标志 30 英尺以内的地方，这样别的司机才能清楚地看到标志。","p":"对。停车时离停车标志至少 30 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần biển \"STOP\" đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 30 feet","Không gần hơn 15 feet","Không gần hơn 100 feet"],"h1":"Một xe đang đậu có thể che biển báo khỏi tầm nhìn của người lái khác.","h2":"Ở Florida, bạn không được đậu xe trong vòng 30 feet từ biển \"STOP\", để người lái khác thấy rõ biển báo.","p":"Đúng. Hãy đậu cách biển \"STOP\" ít nhất 30 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa stop sign ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 100 feet"],"h1":"Maaaring itago ng nakaparadang kotse ang karatula sa ibang drayber.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, para malinaw na makita ng ibang drayber ang karatula.","p":"Tama. Pumarada nang hindi bababa sa 30 feet ang layo sa stop sign."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من علامة \"STOP\" (قف) عندما تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 100 قدم"],"h1":"السيارة المركونة قد تخفي العلامة عن السائقين الآخرين.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 30 قدمًا من علامة \"STOP\" (قف)، حتى يرى السائقون الآخرون العلامة بوضوح.","p":"صحيح. اركن على مسافة 30 قدمًا على الأقل من علامة \"STOP\" (قف)."},"ht":{"q":"Nan Florida, a ki distans de yon siy \"STOP\" ou ka pake?","o":["Pa pi pre pase 10 pye","Pa pi pre pase 30 pye","Pa pi pre pase 15 pye","Pa pi pre pase 100 pye"],"h1":"Yon machin ki pake ka kache siy la pou lòt chofè yo pa wè l.","h2":"Nan Florida ou pa ka pake nan mwens pase 30 pye de yon siy \"STOP\", pou lòt chofè yo ka wè siy la byen.","p":"Wi, se sa. Pake omwen 30 pye lwen yon siy \"STOP\"."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-037","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 10 feet"],"h1":"Trains are wide and drivers need a clear view of the tracks.","h2":"In Florida you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Florida, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies","No a menos de 10 pies"],"h1":"Los trenes son anchos y los conductores necesitan ver bien las vías.","h2":"En Florida no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de tren."},"zh":{"q":"在 Florida，停车时离铁路道口最近的铁轨最近可以多近？","o":["不能少于 15 英尺","不能少于 50 英尺","不能少于 25 英尺","不能少于 10 英尺"],"h1":"火车很宽，司机需要清楚地看到铁轨。","h2":"在 Florida，你不能停在离铁路道口最近的铁轨 50 英尺以内的地方。","p":"对。停车时离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Florida, bạn được đậu xe gần thanh ray gần nhất của chỗ giao nhau với đường sắt đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 25 feet","Không gần hơn 10 feet"],"h1":"Tàu hỏa rất rộng và người lái cần nhìn rõ đường ray.","h2":"Ở Florida, bạn không được đậu xe trong vòng 50 feet từ thanh ray gần nhất của chỗ giao nhau với đường sắt.","p":"Đúng. Hãy đậu cách chỗ giao nhau với đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Florida, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 10 feet"],"h1":"Malapad ang mga tren at kailangan ng mga drayber ng malinaw na tanaw sa riles.","h2":"Sa Florida, hindi ka puwedeng pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Pumarada nang hindi bababa sa 50 feet ang layo sa railroad crossing."},"ar":{"q":"في Florida، كم يمكنك أن تقترب من أقرب قضيب في تقاطع سكة حديد عندما تركن سيارتك؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 10 أقدام"],"h1":"القطارات عريضة، والسائقون يحتاجون إلى رؤية واضحة للسكة.","h2":"في Florida لا يجوز أن تركن على مسافة أقل من 50 قدمًا من أقرب قضيب في تقاطع سكة حديد.","p":"صحيح. اركن على مسافة 50 قدمًا على الأقل من تقاطع سكة الحديد."},"ht":{"q":"Nan Florida, a ki distans de ray ki pi pre a nan yon kwazman tren ou ka pake?","o":["Pa pi pre pase 15 pye","Pa pi pre pase 50 pye","Pa pi pre pase 25 pye","Pa pi pre pase 10 pye"],"h1":"Tren yo laj epi chofè yo bezwen wè ray yo byen.","h2":"Nan Florida ou pa ka pake nan mwens pase 50 pye de ray ki pi pre a nan yon kwazman tren.","p":"Wi, se sa. Pake omwen 50 pye lwen yon kwazman tren."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-038","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Straight ahead","It does not matter","Toward the curb"],"h1":"Think about where the car would roll if the brakes failed.","h2":"When you park downhill next to a curb, turn your front wheels toward the curb, so the car rolls into the curb if it moves.","p":"Right. Downhill with a curb, turn your wheels toward the curb."},"es":{"q":"En Florida, se estaciona en bajada junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Rectas hacia adelante","No importa","Hacia la acera"],"h1":"Piense hacia dónde rodaría el carro si fallaran los frenos.","h2":"Cuando se estaciona en bajada junto a la acera, gire las ruedas delanteras hacia la acera, para que el carro choque con ella si se mueve.","p":"Correcto. En bajada con acera, gire las ruedas hacia la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝下坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝正前方","朝哪边都没关系","朝路缘的方向"],"h1":"想一想，如果刹车失灵，车会往哪里滑。","h2":"在有路缘的下坡停车时，要把前轮转向路缘，这样车如果滑动，就会顶到路缘上。","p":"对。有路缘的下坡，前轮转向路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng xuống dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Thẳng về phía trước","Hướng nào cũng được","Về phía lề đường"],"h1":"Hãy nghĩ xem xe sẽ lăn về đâu nếu phanh bị hỏng.","h2":"Khi đậu xe xuống dốc cạnh lề đường, bạn quay bánh trước về phía lề, để nếu xe lăn thì sẽ chạm vào lề.","p":"Đúng. Xuống dốc có lề đường, quay bánh xe về phía lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap pababa sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Diretso","Hindi mahalaga","Papunta sa curb"],"h1":"Isipin kung saan gugulong ang kotse kung masira ang preno.","h2":"Kapag pumarada ka nang pababa sa tabi ng curb, ipihit ang mga gulong sa harap papunta sa curb, para gumulong ang kotse papunta sa curb kung gumalaw ito.","p":"Tama. Pababa at may curb, ipihit ang mga gulong papunta sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أسفل المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","إلى الأمام مباشرة","لا يهم","نحو الرصيف"],"h1":"فكّر إلى أين ستتدحرج السيارة إذا تعطلت الفرامل.","h2":"عندما تركن ووجه السيارة إلى أسفل المنحدر بجانب رصيف، أدر العجلات الأمامية نحو الرصيف، حتى تتدحرج السيارة إلى الرصيف إذا تحركت.","p":"صحيح. في النزول وبجانب رصيف، أدر العجلات نحو الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon desant bò kote yon rebò twotwa, devan machin nan bay sou desant lan. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Tou dwat","Sa pa fè okenn diferans","Bò kote rebò twotwa a"],"h1":"Panse ak ki kote machin nan ta woule si fren yo pa mache.","h2":"Lè ou pake nan yon desant bò kote yon rebò twotwa, vire wou devan yo bò kote rebò twotwa a, pou si machin nan bouje, li woule frape rebò twotwa a.","p":"Wi, se sa. Nan desant ak yon rebò twotwa, vire wou yo bò kote rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-039","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, you want the back of the front tire to touch the curb.","h2":"When you park uphill next to a curb, turn your front wheels away from the curb, so the tire catches the curb if the car rolls back.","p":"Right. Uphill with a curb, turn your wheels away from the curb."},"es":{"q":"En Florida, se estaciona en subida junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Lejos de la acera","Hacia la acera","Rectas hacia adelante","No importa"],"h1":"Si el carro rueda hacia atrás, quiere que la llanta delantera toque la acera.","h2":"Cuando se estaciona en subida junto a la acera, gire las ruedas delanteras lejos de la acera, para que la llanta se apoye en ella si el carro rueda hacia atrás.","p":"Correcto. En subida con acera, gire las ruedas lejos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边停车，车头朝上坡。你的前轮应该朝哪边转？","o":["朝远离路缘的方向","朝路缘的方向","朝正前方","朝哪边都没关系"],"h1":"如果车往后滑，你希望前轮的后部顶到路缘。","h2":"在有路缘的上坡停车时，要把前轮转离路缘，这样车如果往后滑，轮胎就会被路缘挡住。","p":"对。有路缘的上坡，前轮转离路缘。"},"vi":{"q":"Ở Florida, bạn đậu xe hướng lên dốc, cạnh lề đường. Bạn nên quay bánh trước về hướng nào?","o":["Ra xa lề đường","Về phía lề đường","Thẳng về phía trước","Hướng nào cũng được"],"h1":"Nếu xe lăn về sau, bạn muốn phần sau của bánh trước chạm vào lề.","h2":"Khi đậu xe lên dốc cạnh lề đường, bạn quay bánh trước ra xa lề, để nếu xe lăn về sau thì bánh xe sẽ chặn vào lề.","p":"Đúng. Lên dốc có lề đường, quay bánh xe ra xa lề."},"tl":{"q":"Sa Florida, pumarada ka nang nakaharap paakyat sa tabi ng curb. Saan mo dapat ipihit ang mga gulong sa harap?","o":["Palayo sa curb","Papunta sa curb","Diretso","Hindi mahalaga"],"h1":"Kung umatras ang kotse, gusto mong tumama sa curb ang likod ng gulong sa harap.","h2":"Kapag pumarada ka nang paakyat sa tabi ng curb, ipihit ang mga gulong sa harap palayo sa curb, para sumabit ang gulong sa curb kung umatras ang kotse.","p":"Tama. Paakyat at may curb, ipihit ang mga gulong palayo sa curb."},"ar":{"q":"في Florida، تركن سيارتك ووجهها إلى أعلى المنحدر بجانب رصيف. إلى أي جهة يجب أن تدير العجلات الأمامية؟","o":["بعيدًا عن الرصيف","نحو الرصيف","إلى الأمام مباشرة","لا يهم"],"h1":"إذا رجعت السيارة إلى الخلف، تريد أن يلمس الجزء الخلفي من العجلة الأمامية الرصيف.","h2":"عندما تركن ووجه السيارة إلى أعلى المنحدر بجانب رصيف، أدر العجلات الأمامية بعيدًا عن الرصيف، حتى تمسك العجلة بالرصيف إذا رجعت السيارة إلى الخلف.","p":"صحيح. في الصعود وبجانب رصيف، أدر العجلات بعيدًا عن الرصيف."},"ht":{"q":"Nan Florida, ou pake nan yon monte bò kote yon rebò twotwa, devan machin nan bay sou monte a. Nan ki direksyon ou ta dwe vire wou devan yo?","o":["Lwen rebò twotwa a","Bò kote rebò twotwa a","Tou dwat","Sa pa fè okenn diferans"],"h1":"Si machin nan woule fè bak, ou vle dèyè kawoutchou devan an touche rebò twotwa a.","h2":"Lè ou pake nan yon monte bò kote yon rebò twotwa, vire wou devan yo lwen rebò twotwa a, pou kawoutchou a kenbe sou rebò twotwa a si machin nan woule fè bak.","p":"Wi, se sa. Nan monte ak yon rebò twotwa, vire wou yo lwen rebò twotwa a."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-040","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, when you parallel park next to a curb, how close to the curb must your wheels be?","o":["Within 24 inches","Within 36 inches","Within 12 inches","Within 6 feet"],"h1":"Your car should be close enough that it does not stick out into traffic.","h2":"In Florida your wheels must be within 12 inches of the curb when you parallel park, so your car does not block the lane.","p":"Right. Park with your wheels within 12 inches of the curb."},"es":{"q":"En Florida, al estacionarse en paralelo junto a la acera, ¿qué tan cerca de la acera deben quedar las ruedas?","o":["A 24 pulgadas o menos","A 36 pulgadas o menos","A 12 pulgadas o menos","A 6 pies o menos"],"h1":"Su carro debe quedar lo bastante cerca para no salirse hacia el tráfico.","h2":"En Florida las ruedas deben quedar a 12 pulgadas o menos de la acera al estacionarse en paralelo, para que su carro no tape el carril.","p":"Correcto. Estaciónese con las ruedas a 12 pulgadas o menos de la acera."},"zh":{"q":"在 Florida，你在路缘旁边侧方停车时，车轮离路缘必须多近？","o":["24 英寸以内","36 英寸以内","12 英寸以内","6 英尺以内"],"h1":"你的车应该停得够近，不会伸到车流里。","h2":"在 Florida，侧方停车时，你的车轮必须在离路缘 12 英寸以内，这样你的车就不会挡住车道。","p":"对。停车时车轮离路缘在 12 英寸以内。"},"vi":{"q":"Ở Florida, khi đậu xe song song cạnh lề đường, bánh xe của bạn phải cách lề bao nhiêu?","o":["Trong vòng 24 inch","Trong vòng 36 inch","Trong vòng 12 inch","Trong vòng 6 feet"],"h1":"Xe của bạn nên ở đủ gần để không lấn ra dòng xe.","h2":"Ở Florida, khi đậu xe song song, bánh xe của bạn phải cách lề trong vòng 12 inch, để xe không chắn làn đường.","p":"Đúng. Hãy đậu với bánh xe cách lề trong vòng 12 inch."},"tl":{"q":"Sa Florida, kapag nag-parallel park ka sa tabi ng curb, gaano kalapit sa curb dapat ang mga gulong mo?","o":["Sa loob ng 24 inches","Sa loob ng 36 inches","Sa loob ng 12 inches","Sa loob ng 6 feet"],"h1":"Dapat sapat ang lapit ng kotse mo para hindi ito nakausli sa trapiko.","h2":"Sa Florida, dapat nasa loob ng 12 inches mula sa curb ang mga gulong mo kapag nag-parallel park ka, para hindi maharangan ng kotse mo ang lane.","p":"Tama. Pumarada nang nasa loob ng 12 inches mula sa curb ang mga gulong mo."},"ar":{"q":"في Florida، عندما تركن موازيًا للرصيف، كم يجب أن تكون عجلاتك قريبة من الرصيف؟","o":["في حدود 24 بوصة","في حدود 36 بوصة","في حدود 12 بوصة","في حدود 6 أقدام"],"h1":"يجب أن تكون سيارتك قريبة بما يكفي حتى لا تبرز إلى طريق السيارات.","h2":"في Florida يجب أن تكون عجلاتك على مسافة 12 بوصة أو أقل من الرصيف عندما تركن موازيًا له، حتى لا تسد سيارتك المسار.","p":"صحيح. اركن وعجلاتك على مسافة 12 بوصة أو أقل من الرصيف."},"ht":{"q":"Nan Florida, lè ou pake paralèl bò kote yon rebò twotwa, a ki distans wou ou yo dwe ye de rebò twotwa a?","o":["Nan 24 pous","Nan 36 pous","Nan 12 pous","Nan 6 pye"],"h1":"Machin ou dwe pre ase pou li pa depase nan wout kote machin yo ap pase.","h2":"Nan Florida wou ou yo dwe nan 12 pous de rebò twotwa a lè ou pake paralèl, pou machin ou pa bloke liy lan.","p":"Wi, se sa. Pake ak wou ou yo nan 12 pous de rebò twotwa a."},"ref":{"doc":"FL","page":65}},{"id":"speed-lanes-041","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, who may park in a space marked for people with disabilities?","o":["Anyone, if it is only for a few minutes","Anyone, if the lot is full","A driver with a valid disabled parking permit or plate shown","Any driver over 65 years old"],"h1":"These spaces are saved for people who have official proof.","h2":"Only a vehicle showing a valid disabled parking permit or license plate may park in a disabled space, even for a short time.","p":"Right. Disabled spaces are only for vehicles with a valid permit or plate."},"es":{"q":"En Florida, ¿quién puede estacionarse en un espacio para personas con discapacidad?","o":["Cualquiera, si es solo por unos minutos","Cualquiera, si el estacionamiento está lleno","Un conductor que muestre un permiso o placa válida de discapacidad","Cualquier conductor mayor de 65 años"],"h1":"Estos espacios son para personas que tienen un comprobante oficial.","h2":"Solo un vehículo que muestre un permiso o una placa válida de discapacidad puede estacionarse en ese espacio, aunque sea por poco tiempo.","p":"Correcto. Los espacios para personas con discapacidad son solo para vehículos con permiso o placa válida."},"zh":{"q":"在 Florida，谁可以停在残疾人专用车位？","o":["任何人，只要只停几分钟","任何人，只要停车场满了","展示有效残疾人停车证或车牌的司机","任何 65 岁以上的司机"],"h1":"这些车位是留给有正式证明的人的。","h2":"只有展示有效残疾人停车证或车牌的车，才可以停在残疾人车位，就算只停很短的时间也一样。","p":"对。残疾人车位只给有有效停车证或车牌的车用。"},"vi":{"q":"Ở Florida, ai được đậu xe ở chỗ dành cho người khuyết tật?","o":["Bất kỳ ai, nếu chỉ đậu vài phút","Bất kỳ ai, nếu bãi đậu xe đã đầy","Người lái có giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực đang được trưng ra","Bất kỳ người lái nào trên 65 tuổi"],"h1":"Những chỗ này được giữ cho người có giấy tờ chính thức.","h2":"Chỉ xe có trưng giấy phép đậu xe hoặc biển số xe người khuyết tật còn hiệu lực mới được đậu ở chỗ dành cho người khuyết tật, dù chỉ trong thời gian ngắn.","p":"Đúng. Chỗ đậu cho người khuyết tật chỉ dành cho xe có giấy phép hoặc biển số còn hiệu lực."},"tl":{"q":"Sa Florida, sino ang puwedeng pumarada sa espasyong nakalaan para sa mga taong may kapansanan?","o":["Kahit sino, kung ilang minuto lang","Kahit sino, kung puno na ang paradahan","Drayber na may nakapakitang balidong disabled parking permit o plaka","Kahit sinong drayber na higit 65 taong gulang"],"h1":"Nakalaan ang mga espasyong ito para sa mga taong may opisyal na patunay.","h2":"Sasakyan lang na may nakapakitang balidong disabled parking permit o plaka ang puwedeng pumarada sa espasyo para sa may kapansanan, kahit sandali lang.","p":"Tama. Ang espasyo para sa may kapansanan ay para lang sa mga sasakyang may balidong permit o plaka."},"ar":{"q":"في Florida، من يمكنه أن يركن في مكان مخصص للأشخاص ذوي الإعاقة؟","o":["أي شخص، إذا كان لبضع دقائق فقط","أي شخص، إذا كان الموقف ممتلئًا","سائق يُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية","أي سائق عمره أكثر من 65 سنة"],"h1":"هذه الأماكن محجوزة للأشخاص الذين معهم إثبات رسمي.","h2":"فقط المركبة التي تُظهر تصريح وقوف لذوي الإعاقة أو لوحة سارية يمكنها أن تركن في مكان ذوي الإعاقة، حتى لوقت قصير.","p":"صحيح. أماكن ذوي الإعاقة فقط للمركبات التي معها تصريح أو لوحة سارية."},"ht":{"q":"Nan Florida, kiyès ki ka pake nan yon plas ki make pou moun andikape?","o":["Nenpòt moun, si se pou kèk minit sèlman","Nenpòt moun, si pakin lan plen","Yon chofè ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab","Nenpòt chofè ki gen plis pase 65 an"],"h1":"Plas sa yo rezève pou moun ki gen yon prèv ofisyèl.","h2":"Se sèlman yon machin ki montre yon pèmi oswa yon plak pakin pou moun andikape ki valab ki ka pake nan yon plas pou moun andikape, menm pou yon ti tan.","p":"Wi, se sa. Plas pou moun andikape yo se sèlman pou machin ki gen yon pèmi oswa yon plak ki valab."},"ref":{"doc":"FL","page":25}},{"id":"speed-lanes-042","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, can you park on the striped lines next to a disabled parking space?","o":["No, that area must stay clear for wheelchairs and lifts","Yes, if you have a permit","Yes, for up to 15 minutes","Yes, if you stay in the car"],"h1":"Think about what a person in a wheelchair needs to get out of a van.","h2":"You may not park on the striped area next to a disabled space, because it must stay clear for wheelchairs and lifts.","p":"Right. Never park on the striped access aisle."},"es":{"q":"En Florida, ¿puede estacionarse sobre las rayas al lado de un espacio para personas con discapacidad?","o":["No, esa área debe quedar libre para sillas de ruedas y plataformas elevadoras","Sí, si tiene permiso","Sí, hasta 15 minutos","Sí, si se queda dentro del carro"],"h1":"Piense en lo que necesita una persona en silla de ruedas para bajar de una camioneta.","h2":"No puede estacionarse en el área con rayas junto a un espacio para personas con discapacidad, porque debe quedar libre para sillas de ruedas y plataformas elevadoras.","p":"Correcto. Nunca se estacione en el pasillo con rayas."},"zh":{"q":"在 Florida，你可以停在残疾人车位旁边画了斜线的地方吗？","o":["不可以，那个地方必须留空给轮椅和升降设备","可以，只要你有停车证","可以，最多 15 分钟","可以，只要你留在车里"],"h1":"想一想，坐轮椅的人从厢式车里下来需要什么。","h2":"你不能停在残疾人车位旁边画了斜线的地方，因为那里必须留空给轮椅和升降设备。","p":"对。永远不要停在画了斜线的通道上。"},"vi":{"q":"Ở Florida, bạn có được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật không?","o":["Không, khu vực đó phải để trống cho xe lăn và bệ nâng","Có, nếu bạn có giấy phép","Có, tối đa 15 phút","Có, nếu bạn ngồi trong xe"],"h1":"Hãy nghĩ xem một người ngồi xe lăn cần gì để ra khỏi xe van.","h2":"Bạn không được đậu xe trên khu vực kẻ sọc cạnh chỗ đậu cho người khuyết tật, vì khu vực đó phải để trống cho xe lăn và bệ nâng.","p":"Đúng. Không bao giờ đậu xe trên lối đi kẻ sọc dành cho xe lăn."},"tl":{"q":"Sa Florida, puwede ka bang pumarada sa mga guhit-guhit na linya sa tabi ng parking space para sa may kapansanan?","o":["Hindi, dapat manatiling bakante ang lugar na iyon para sa wheelchair at lift","Oo, kung may permit ka","Oo, hanggang 15 minuto","Oo, kung mananatili ka sa loob ng kotse"],"h1":"Isipin ang kailangan ng taong naka-wheelchair para makababa sa van.","h2":"Hindi ka puwedeng pumarada sa lugar na may guhit-guhit sa tabi ng espasyo para sa may kapansanan, dahil dapat itong manatiling bakante para sa wheelchair at lift.","p":"Tama. Huwag kailanman pumarada sa guhit-guhit na daanan (access aisle)."},"ar":{"q":"في Florida، هل يمكنك أن تركن على الخطوط المخططة بجانب مكان وقوف ذوي الإعاقة؟","o":["لا، هذه المنطقة يجب أن تبقى فارغة للكراسي المتحركة والمصاعد","نعم، إذا كان معي تصريح","نعم، حتى 15 دقيقة","نعم، إذا بقيت في السيارة"],"h1":"فكّر ماذا يحتاج شخص على كرسي متحرك لينزل من شاحنة صغيرة.","h2":"لا يجوز أن تركن على المنطقة المخططة بجانب مكان ذوي الإعاقة، لأنها يجب أن تبقى فارغة للكراسي المتحركة والمصاعد.","p":"صحيح. لا تركن أبدًا على الممر المخطط بجانب مكان ذوي الإعاقة."},"ht":{"q":"Nan Florida, èske ou ka pake sou liy bawo ki bò kote yon plas pakin pou moun andikape?","o":["Non, zòn sa a dwe rete lib pou chèz woulant ak asansè machin yo","Wi, si ou gen yon pèmi","Wi, pou jiska 15 minit","Wi, si ou rete nan machin nan"],"h1":"Panse ak sa yon moun nan chèz woulant bezwen pou l sòti nan yon kamyonèt.","h2":"Ou pa ka pake sou zòn ki gen liy bawo bò kote yon plas pou moun andikape, paske li dwe rete lib pou chèz woulant ak asansè machin yo.","p":"Wi, se sa. Pa janm pake sou zòn ki gen liy bawo a."},"ref":{"doc":"FL","page":null}},{"id":"speed-lanes-043","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"You want to pass a car on a two-lane road. What must you be sure of first?","o":["The car ahead is going under the speed limit","Your headlights are on","There is a car behind you","There is enough clear road ahead to pass and get back into your lane"],"h1":"You will be in the lane of oncoming traffic.","h2":"Before passing on a two-lane road, make sure the road ahead is clear for long enough to pass and safely return to your lane.","p":"Right. You need enough clear road to pass and return."},"es":{"q":"Usted quiere rebasar a un carro en una vía de dos carriles. ¿De qué debe estar seguro primero?","o":["De que el carro de adelante va por debajo del límite","De que sus luces están encendidas","De que hay un carro detrás de usted","De que hay suficiente vía libre adelante para rebasar y volver a su carril"],"h1":"Va a estar en el carril del tráfico que viene de frente.","h2":"Antes de rebasar en una vía de dos carriles, asegúrese de que la vía adelante está libre el tiempo suficiente para rebasar y volver a su carril con seguridad.","p":"Correcto. Necesita vía libre para rebasar y volver."},"zh":{"q":"你想在双车道的路上超车。你首先必须确定什么？","o":["前面的车开得比限速慢","你的车头灯开着","你后面有一辆车","前面有足够长的空路，可以超车并回到你的车道"],"h1":"你会开到对面来车的车道上。","h2":"在双车道的路上超车之前，要确定前面的路空着的距离足够长，可以超车并安全回到你的车道。","p":"对。你需要足够的空路来超车和回到车道。"},"vi":{"q":"Bạn muốn vượt một xe trên đường hai làn. Trước tiên bạn phải chắc chắn điều gì?","o":["Xe phía trước đang chạy chậm hơn giới hạn tốc độ","Đèn pha của bạn đang bật","Có một xe phía sau bạn","Đường phía trước đủ trống để vượt và trở về làn của bạn"],"h1":"Bạn sẽ ở trong làn của xe đi ngược chiều.","h2":"Trước khi vượt trên đường hai làn, hãy chắc chắn đường phía trước trống đủ lâu để vượt và trở về làn của bạn an toàn.","p":"Đúng. Bạn cần đủ đường trống để vượt và trở về."},"tl":{"q":"Gusto mong lampasan ang isang kotse sa kalsadang may dalawang lane. Ano ang dapat mong siguraduhin muna?","o":["Mas mabagal sa speed limit ang kotse sa unahan","Nakabukas ang iyong headlights","May kotse sa likod mo","May sapat na bakanteng daan sa unahan para lumampas at bumalik sa iyong lane"],"h1":"Mapupunta ka sa lane ng mga sasakyang paparating.","h2":"Bago lumampas sa kalsadang may dalawang lane, siguraduhing bakante ang daan sa unahan nang sapat na haba para makalampas at ligtas na makabalik sa iyong lane.","p":"Tama. Kailangan mo ng sapat na bakanteng daan para lumampas at bumalik."},"ar":{"q":"تريد أن تتجاوز سيارة على طريق ذي مسارين. ما الذي يجب أن تتأكد منه أولًا؟","o":["أن السيارة التي أمامك تسير أبطأ من حد السرعة","أن مصابيحك الأمامية مضاءة","أن هناك سيارة خلفك","أن الطريق أمامك خالٍ بما يكفي لتتجاوز وتعود إلى مسارك"],"h1":"ستكون في مسار السيارات القادمة نحوك.","h2":"قبل التجاوز على طريق ذي مسارين، تأكد أن الطريق أمامك خالٍ لمسافة تكفي لتتجاوز وتعود إلى مسارك بأمان.","p":"صحيح. تحتاج إلى طريق خالٍ يكفي للتجاوز والعودة."},"ht":{"q":"Ou vle pase yon machin sou yon wout ki gen de liy. Kisa ou dwe asire w anvan?","o":["Machin devan an ap mache pi dousman pase limit vitès la","Limyè devan machin ou limen","Gen yon machin dèyè w","Gen ase wout lib devan pou w pase epi retounen nan liy ou"],"h1":"W ap nan liy machin ki ap vini sou ou.","h2":"Anvan ou pase sou yon wout ki gen de liy, asire w wout devan an lib sou ase distans pou w pase epi retounen nan liy ou san danje.","p":"Wi, se sa. Ou bezwen ase wout lib pou w pase epi retounen."}},{"id":"speed-lanes-044","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"Why is it dangerous to pass near the top of a hill or in a curve?","o":["You cannot see cars coming toward you","Your engine may stall","The road is always slippery there","Other cars go faster there"],"h1":"Hills and curves hide what is ahead.","h2":"Near a hilltop or in a curve you cannot see oncoming traffic, so you might meet a car head-on while passing.","p":"Right. You cannot see oncoming cars."},"es":{"q":"¿Por qué es peligroso rebasar cerca de la cima de una loma o en una curva?","o":["Porque no puede ver los carros que vienen de frente","Porque el motor se puede apagar","Porque allí la vía siempre está resbalosa","Porque allí los demás van más rápido"],"h1":"Las lomas y curvas ocultan lo que viene.","h2":"Cerca de la cima de una loma o en una curva no puede ver el tráfico de frente, así que podría encontrarse de frente con un carro mientras rebasa.","p":"Correcto. No puede ver los carros de frente."},"zh":{"q":"为什么在接近坡顶或在弯道上超车很危险？","o":["你看不到对面开过来的车","你的发动机可能熄火","那里的路总是很滑","其他车在那里开得更快"],"h1":"山坡和弯道会挡住前面的情况。","h2":"在接近坡顶或在弯道上，你看不到对面来车，所以超车时可能会和车迎面相撞。","p":"对。你看不到对面来车。"},"vi":{"q":"Tại sao vượt xe gần đỉnh dốc hoặc trong khúc cua là nguy hiểm?","o":["Bạn không thấy được xe đang chạy về phía bạn","Máy xe của bạn có thể bị chết","Đường ở đó lúc nào cũng trơn","Các xe khác chạy nhanh hơn ở đó"],"h1":"Đồi và khúc cua che khuất những gì phía trước.","h2":"Gần đỉnh dốc hoặc trong khúc cua, bạn không thấy xe đi ngược chiều, nên khi vượt bạn có thể đâm trực diện vào một xe.","p":"Đúng. Bạn không thấy xe đi ngược chiều."},"tl":{"q":"Bakit mapanganib lumampas malapit sa tuktok ng burol o sa kurbada?","o":["Hindi mo makita ang mga kotseng paparating sa iyo","Baka mamatay ang makina mo","Laging madulas ang daan doon","Mas mabilis ang ibang kotse doon"],"h1":"Itinatago ng burol at kurbada ang nasa unahan.","h2":"Malapit sa tuktok ng burol o sa kurbada, hindi mo makita ang mga sasakyang paparating, kaya baka makasalubong mo nang harapan ang isang kotse habang lumalampas.","p":"Tama. Hindi mo makita ang mga paparating na kotse."},"ar":{"q":"لماذا يكون التجاوز خطيرًا قرب قمة تلّ أو في منعطف؟","o":["لأنك لا ترى السيارات القادمة نحوك","لأن محرك سيارتك قد يتوقف","لأن الطريق هناك زلق دائمًا","لأن السيارات الأخرى تسير هناك أسرع"],"h1":"التلال والمنعطفات تُخفي ما أمامك.","h2":"قرب قمة التل أو في المنعطف لا ترى السيارات القادمة نحوك، فقد تصطدم بسيارة وجهًا لوجه وأنت تتجاوز.","p":"صحيح. لا ترى السيارات القادمة."},"ht":{"q":"Poukisa li danjere pou w pase yon machin toupre tèt yon mòn oswa nan yon koub?","o":["Ou pa ka wè machin k ap vini sou ou","Motè machin ou ka mouri","Wout la toujou glise la","Lòt machin yo mache pi vit la"],"h1":"Mòn ak koub kache sa ki devan.","h2":"Toupre tèt yon mòn oswa nan yon koub, ou pa ka wè machin k ap vini an fas, kidonk ou ka frape yon machin fas a fas pandan w ap pase.","p":"Wi, se sa. Ou pa ka wè machin k ap vini yo."}},{"id":"speed-lanes-045","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You start to pass on a two-lane road, and a car appears ahead coming toward you. There is not enough room. What should you do?","o":["Speed up and hope you make it","Slow down and move back behind the car you were passing","Drive onto the left shoulder","Stay beside the car and honk"],"h1":"Getting back safely is better than racing.","h2":"If you cannot finish passing safely, slow down and return to your lane behind the car you were passing.","p":"Right. Drop back into your lane."},"es":{"q":"Usted empieza a rebasar en una vía de dos carriles y aparece un carro de frente. No hay espacio suficiente. ¿Qué debe hacer?","o":["Acelerar y esperar que le alcance","Bajar la velocidad y volver detrás del carro que rebasaba","Salirse al acotamiento izquierdo","Quedarse al lado del carro y tocar la bocina"],"h1":"Volver con seguridad es mejor que apurarse.","h2":"Si no puede terminar de rebasar con seguridad, baje la velocidad y vuelva a su carril detrás del carro que estaba rebasando.","p":"Correcto. Vuelva a su carril detrás."},"zh":{"q":"你在双车道的路上开始超车，前面出现一辆对面开来的车，空间不够。你应该怎么做？","o":["加速，希望能来得及","减速，回到你正在超的那辆车后面","开到左边的路肩上","留在那辆车旁边并按喇叭"],"h1":"安全回去比抢着冲过去好。","h2":"如果你不能安全完成超车，就减速，回到你正在超的那辆车后面，回到你的车道。","p":"对。退回到你的车道。"},"vi":{"q":"Bạn bắt đầu vượt trên đường hai làn, và một xe xuất hiện phía trước đang chạy về phía bạn. Không đủ chỗ. Bạn nên làm gì?","o":["Tăng tốc và hy vọng kịp","Giảm tốc và trở về phía sau xe bạn đang vượt","Chạy lên lề đường bên trái","Ở bên cạnh xe kia và bấm còi"],"h1":"Trở về an toàn tốt hơn là đua.","h2":"Nếu bạn không thể vượt xong một cách an toàn, hãy giảm tốc và trở về làn của bạn phía sau xe bạn đang vượt.","p":"Đúng. Lùi lại vào làn của bạn."},"tl":{"q":"Nagsimula kang lumampas sa kalsadang may dalawang lane, at may lumitaw na kotse sa unahan na papalapit sa iyo. Kulang ang espasyo. Ano ang dapat mong gawin?","o":["Bumilis at umasang aabot ka","Bumagal at bumalik sa likod ng kotseng nilalampasan mo","Pumunta sa kaliwang gilid ng daan","Manatili sa tabi ng kotse at bumusina"],"h1":"Mas mabuti ang ligtas na pagbalik kaysa makipagkarera.","h2":"Kung hindi mo ligtas na matatapos ang paglampas, bumagal at bumalik sa iyong lane sa likod ng kotseng nilalampasan mo.","p":"Tama. Bumalik sa iyong lane."},"ar":{"q":"بدأت التجاوز على طريق ذي مسارين، وظهرت أمامك سيارة قادمة نحوك. لا توجد مساحة كافية. ماذا تفعل؟","o":["تُسرع وتأمل أن تنجح","تُبطئ وتعود خلف السيارة التي كنت تتجاوزها","تقود على الكتف الأيسر للطريق","تبقى بجانب السيارة وتستعمل البوق"],"h1":"العودة بأمان أفضل من السباق.","h2":"إذا لم تستطع إكمال التجاوز بأمان، أبطئ وعُد إلى مسارك خلف السيارة التي كنت تتجاوزها.","p":"صحيح. عُد إلى مسارك."},"ht":{"q":"Ou kòmanse pase sou yon wout ki gen de liy, epi yon machin parèt devan, l ap vini sou ou. Pa gen ase plas. Kisa ou ta dwe fè?","o":["Akselere epi espere w ap rive","Ralanti epi retounen dèyè machin ou t ap pase a","Kondui sou bò wout la a goch","Rete bò kote machin nan epi klaksonnen"],"h1":"Retounen san danje pi bon pase fè kous.","h2":"Si ou pa ka fin pase san danje, ralanti epi retounen nan liy ou dèyè machin ou t ap pase a.","p":"Wi, se sa. Retounen nan liy ou."}},{"id":"speed-lanes-046","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"When is the best time to slow down for a curve?","o":["In the middle of the curve","At the end of the curve","Before you enter the curve","You do not need to slow down"],"h1":"Braking hard in a curve can make you skid.","h2":"Slow down before you enter a curve, then keep a steady speed through it; braking in the curve can make your tires lose grip.","p":"Right. Slow down before the curve."},"es":{"q":"¿Cuál es el mejor momento para bajar la velocidad en una curva?","o":["En medio de la curva","Al final de la curva","Antes de entrar a la curva","No necesita bajar la velocidad"],"h1":"Frenar fuerte en una curva puede hacerlo patinar.","h2":"Baje la velocidad antes de entrar a una curva y mantenga una velocidad constante en ella; frenar en la curva puede hacer que las llantas pierdan agarre.","p":"Correcto. Baje la velocidad antes de la curva."},"zh":{"q":"什么时候为弯道减速最好？","o":["在弯道中间","在弯道结束时","在进入弯道之前","你不需要减速"],"h1":"在弯道里猛踩刹车可能会让车打滑。","h2":"要在进入弯道之前减速，然后用平稳的速度开过弯道；在弯道里刹车会让轮胎失去抓地力。","p":"对。在弯道之前减速。"},"vi":{"q":"Khi nào là lúc tốt nhất để giảm tốc cho khúc cua?","o":["Ở giữa khúc cua","Ở cuối khúc cua","Trước khi vào khúc cua","Bạn không cần giảm tốc"],"h1":"Phanh gấp trong khúc cua có thể làm xe bị trượt.","h2":"Hãy giảm tốc trước khi vào khúc cua, rồi giữ tốc độ đều khi đi qua; phanh trong khúc cua có thể làm bánh xe mất độ bám.","p":"Đúng. Giảm tốc trước khúc cua."},"tl":{"q":"Kailan ang pinakamainam na oras para bumagal para sa kurbada?","o":["Sa gitna ng kurbada","Sa dulo ng kurbada","Bago ka pumasok sa kurbada","Hindi mo kailangang bumagal"],"h1":"Ang malakas na pagpreno sa kurbada ay puwedeng magpadulas sa iyo.","h2":"Bumagal bago ka pumasok sa kurbada, saka panatilihing pantay ang bilis habang dumadaan dito; ang pagpreno sa kurbada ay puwedeng magpawala ng kapit ng gulong.","p":"Tama. Bumagal bago ang kurbada."},"ar":{"q":"ما أفضل وقت لتخفيف السرعة عند منعطف؟","o":["في منتصف المنعطف","في نهاية المنعطف","قبل أن تدخل المنعطف","ليس عليك أن تُبطئ"],"h1":"الضغط بقوة على الفرامل في المنعطف قد يجعل السيارة تنزلق.","h2":"أبطئ قبل أن تدخل المنعطف، ثم حافظ على سرعة ثابتة وأنت تمرّ فيه؛ فالفرملة داخل المنعطف قد تُفقد الإطارات تماسكها.","p":"صحيح. أبطئ قبل المنعطف."},"ht":{"q":"Ki pi bon moman pou w ralanti pou yon koub?","o":["Nan mitan koub la","Nan fen koub la","Anvan ou antre nan koub la","Ou pa bezwen ralanti"],"h1":"Si w frennen fò nan yon koub, machin nan ka glise.","h2":"Ralanti anvan ou antre nan yon koub, epi kenbe yon vitès ki pa chanje pandan w ap pase ladan l; si w frennen nan koub la, kawotchou yo ka pèdi gripe.","p":"Wi, se sa. Ralanti anvan koub la."}},{"id":"speed-lanes-047","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Why should you try to keep open space beside your car, not just in front?","o":["So other cars can park","So your car stays cooler","So you can drive on two lanes","So you have somewhere to steer if something happens ahead"],"h1":"Space is your escape route.","h2":"Keeping open space beside your car gives you room to steer away from a hazard if you cannot stop in time.","p":"Right. It gives you a way out."},"es":{"q":"¿Por qué debe tratar de mantener espacio libre a los lados de su carro, no solo adelante?","o":["Para que otros carros puedan estacionarse","Para que su carro se mantenga más fresco","Para poder manejar en dos carriles","Para tener hacia dónde girar si pasa algo adelante"],"h1":"El espacio es su ruta de escape.","h2":"Mantener espacio libre a los lados le da lugar para esquivar un peligro si no alcanza a pararse a tiempo.","p":"Correcto. Le da una salida."},"zh":{"q":"为什么你应该尽量在车旁边也留出空间，而不只是在前面？","o":["让其他车可以停车","让你的车保持凉快","让你可以同时开在两条车道上","这样前面出事时你有地方转向躲开"],"h1":"空间就是你的逃生路线。","h2":"在车旁边留出空间，当你来不及停车时，就有地方转向躲开危险。","p":"对。这给你一条出路。"},"vi":{"q":"Tại sao bạn nên cố giữ khoảng trống bên cạnh xe, không chỉ phía trước?","o":["Để xe khác có thể đậu","Để xe của bạn mát hơn","Để bạn có thể chạy trên hai làn","Để bạn có chỗ lái tránh nếu có chuyện xảy ra phía trước"],"h1":"Khoảng trống là đường thoát của bạn.","h2":"Giữ khoảng trống bên cạnh xe cho bạn chỗ để lái tránh mối nguy nếu bạn không thể dừng kịp.","p":"Đúng. Nó cho bạn một đường thoát."},"tl":{"q":"Bakit dapat mong subukang magkaroon ng bakanteng espasyo sa tabi ng iyong kotse, hindi lang sa harap?","o":["Para makaparada ang ibang kotse","Para manatiling malamig ang kotse mo","Para makapagmaneho ka sa dalawang lane","Para may mapupuntahan ka kung may mangyari sa unahan"],"h1":"Ang espasyo ay ang iyong daan palabas.","h2":"Ang bakanteng espasyo sa tabi ng iyong kotse ay nagbibigay sa iyo ng lugar para umiwas sa panganib kung hindi ka makahinto sa oras.","p":"Tama. Nagbibigay ito sa iyo ng daan palabas."},"ar":{"q":"لماذا يجب أن تحاول ترك مساحة فارغة بجانب سيارتك، لا أمامها فقط؟","o":["حتى تتمكن السيارات الأخرى من الوقوف","حتى تبقى سيارتك أبرد","حتى تستطيع القيادة على مسارين","حتى يكون لديك مكان توجّه إليه سيارتك إذا حدث شيء أمامك"],"h1":"المساحة هي طريق نجاتك.","h2":"ترك مساحة فارغة بجانب سيارتك يعطيك مكانًا تبتعد إليه عن الخطر إذا لم تستطع التوقف في الوقت المناسب.","p":"صحيح. هي تعطيك طريقًا للخروج."},"ht":{"q":"Poukisa ou ta dwe eseye kenbe espas lib bò kote machin ou, pa sèlman devan?","o":["Pou lòt machin ka pake","Pou machin ou rete pi fre","Pou ou ka kondui sou de liy","Pou ou gen kote pou w vire si yon bagay rive devan"],"h1":"Espas se chemen pou w chape.","h2":"Lè ou kenbe espas lib bò kote machin ou, ou gen plas pou w vire evite yon danje si ou pa ka kanpe a tan.","p":"Wi, se sa. Li ba w yon fason pou w soti."}},{"id":"speed-lanes-048","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You stop behind another car at a light. How much space should you leave?","o":["Enough to see its rear tires touching the road","Just a few inches","At least five car lengths","No space; pull right up to it"],"h1":"You want room to get around it.","h2":"When stopped, leave enough space to see the rear tires of the car ahead touching the road, so you can steer around it if it stalls.","p":"Right. See its rear tires on the road."},"es":{"q":"Usted se para detrás de otro carro en un semáforo. ¿Cuánto espacio debe dejar?","o":["Suficiente para ver sus llantas traseras tocando la vía","Solo unas pulgadas","Por lo menos cinco carros de largo","Ninguno; acérquese del todo"],"h1":"Necesita espacio para rodearlo.","h2":"Al pararse, deje suficiente espacio para ver las llantas traseras del carro de adelante tocando la vía, para poder rodearlo si se queda parado.","p":"Correcto. Vea sus llantas traseras en la vía."},"zh":{"q":"你在红绿灯前停在另一辆车后面。你应该留多少空间？","o":["足够看到它的后轮接触路面","只留几英寸","至少五个车身长","不留空间，直接贴上去"],"h1":"你需要有空间可以绕过它。","h2":"停车时，要留出足够的空间，能看到前车后轮接触路面，这样如果它熄火，你可以转向绕过去。","p":"对。要看到它的后轮在路面上。"},"vi":{"q":"Bạn dừng sau một xe khác ở đèn giao thông. Bạn nên chừa khoảng cách bao nhiêu?","o":["Đủ để thấy bánh sau của xe đó chạm mặt đường","Chỉ vài inch","Ít nhất năm chiều dài xe","Không chừa chỗ; chạy sát vào"],"h1":"Bạn cần chỗ để đi vòng qua xe đó.","h2":"Khi dừng, hãy chừa đủ khoảng cách để thấy bánh sau của xe phía trước chạm mặt đường, để bạn có thể lái vòng qua nếu xe đó bị chết máy.","p":"Đúng. Thấy bánh sau của xe đó trên mặt đường."},"tl":{"q":"Huminto ka sa likod ng isang kotse sa ilaw-trapiko. Gaano kalaking espasyo ang dapat mong iwan?","o":["Sapat para makita ang mga gulong nito sa likod na nakadikit sa daan","Ilang pulgada lang","Hindi bababa sa limang haba ng kotse","Walang espasyo; idikit mo na"],"h1":"Kailangan mo ng espasyo para makaikot dito.","h2":"Kapag nakahinto, mag-iwan ng sapat na espasyo para makita ang mga gulong sa likod ng kotse sa unahan na nakadikit sa daan, para maikot mo ito kung mamatayan ito ng makina.","p":"Tama. Makita ang mga gulong nito sa likod sa daan."},"ar":{"q":"توقفت خلف سيارة أخرى عند إشارة ضوئية. كم مسافة يجب أن تترك؟","o":["ما يكفي لترى إطاراتها الخلفية تلمس الطريق","بضع بوصات فقط","طول خمس سيارات على الأقل","بدون مسافة؛ اقترب منها تمامًا"],"h1":"تحتاج إلى مكان لتلتفّ حولها.","h2":"عندما تتوقف، اترك مسافة تكفي لترى الإطارات الخلفية للسيارة التي أمامك تلمس الطريق، حتى تستطيع أن تلتفّ حولها إذا توقف محركها.","p":"صحيح. انظر إلى إطاراتها الخلفية على الطريق."},"ht":{"q":"Ou kanpe dèyè yon lòt machin nan yon limyè. Konbyen espas ou ta dwe kite?","o":["Ase pou w wè kawotchou dèyè li yo touche wout la","Kèk pous sèlman","Omwen longè senk machin","Okenn espas; kole sou li"],"h1":"Ou bezwen plas pou w fè wonn li.","h2":"Lè ou kanpe, kite ase espas pou w wè kawotchou dèyè machin devan an touche wout la, konsa ou ka vire fè wonn li si motè l mouri.","p":"Wi, se sa. Wè kawotchou dèyè li sou wout la."}},{"id":"speed-lanes-049","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"What is a blind spot?","o":["A dark part of the road at night","An area around your car that you cannot see in your mirrors","A spot on your windshield","A place where parking is not allowed"],"h1":"Mirrors do not show everything.","h2":"A blind spot is an area beside or behind your car that your mirrors do not show, so you must turn your head to check it.","p":"Right. Your mirrors cannot show it."},"es":{"q":"¿Qué es un punto ciego?","o":["Una parte oscura de la vía de noche","Un área alrededor de su carro que no ve en los espejos","Una mancha en el parabrisas","Un lugar donde no se puede estacionar"],"h1":"Los espejos no muestran todo.","h2":"Un punto ciego es un área al lado o detrás de su carro que los espejos no muestran, así que debe girar la cabeza para revisarla.","p":"Correcto. Los espejos no lo muestran."},"zh":{"q":"什么是盲点？","o":["夜里路上黑暗的地方","你车子周围在后视镜里看不到的区域","挡风玻璃上的一个点","不准停车的地方"],"h1":"后视镜不能显示所有东西。","h2":"盲点是你车旁边或后面后视镜照不到的区域，所以你必须转头去查看。","p":"对。你的后视镜看不到那里。"},"vi":{"q":"Điểm mù là gì?","o":["Một đoạn đường tối vào ban đêm","Một vùng quanh xe mà bạn không thấy được trong gương","Một vết trên kính chắn gió","Một nơi không được đậu xe"],"h1":"Gương không cho thấy mọi thứ.","h2":"Điểm mù là vùng bên cạnh hoặc phía sau xe mà gương không cho thấy, nên bạn phải quay đầu để kiểm tra.","p":"Đúng. Gương của bạn không cho thấy vùng đó."},"tl":{"q":"Ano ang blind spot?","o":["Madilim na bahagi ng daan sa gabi","Isang lugar sa paligid ng kotse mo na hindi mo makita sa mga salamin","Isang mantsa sa windshield mo","Isang lugar kung saan bawal pumarada"],"h1":"Hindi ipinapakita ng mga salamin ang lahat.","h2":"Ang blind spot ay isang lugar sa tabi o sa likod ng kotse mo na hindi ipinapakita ng mga salamin, kaya kailangan mong lumingon para tingnan ito.","p":"Tama. Hindi ito maipakita ng mga salamin mo."},"ar":{"q":"ما هي النقطة العمياء؟","o":["جزء مظلم من الطريق في الليل","منطقة حول سيارتك لا تراها في مراياك","بقعة على الزجاج الأمامي","مكان يُمنع فيه الوقوف"],"h1":"المرايا لا تُظهر كل شيء.","h2":"النقطة العمياء منطقة بجانب سيارتك أو خلفها لا تُظهرها المرايا، لذلك يجب أن تُدير رأسك لتتحقق منها.","p":"صحيح. مراياك لا تُظهرها."},"ht":{"q":"Kisa yon zòn avèg ye?","o":["Yon pati wout la ki fè nwa lannuit","Yon zòn bò machin ou ke ou pa ka wè nan miwa ou yo","Yon tach sou vit devan machin ou","Yon kote ou pa gen dwa pake"],"h1":"Miwa yo pa montre tout bagay.","h2":"Yon zòn avèg se yon zòn bò kote oswa dèyè machin ou ke miwa ou yo pa montre, kidonk ou dwe vire tèt ou pou w gade l.","p":"Wi, se sa. Miwa ou yo pa ka montre l."}},{"id":"speed-lanes-050","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are driving just behind and to the side of another car, where the driver may not see you. What should you do?","o":["Stay there; it is the safest place","Honk every few seconds","Speed up or drop back so you are not in the driver's blind spot","Turn on your hazard lights"],"h1":"Do not stay where the other driver cannot see you.","h2":"Do not ride in another driver's blind spot; speed up or drop back so the driver can see you in a mirror.","p":"Right. Move out of their blind spot."},"es":{"q":"Usted maneja justo detrás y al costado de otro carro, donde el conductor quizás no lo ve. ¿Qué debe hacer?","o":["Quedarse allí; es el lugar más seguro","Tocar la bocina cada pocos segundos","Acelerar o quedarse atrás para no estar en el punto ciego del conductor","Encender las luces de emergencia"],"h1":"No se quede donde el otro conductor no lo ve.","h2":"No maneje en el punto ciego de otro conductor; acelere o quédese atrás para que el conductor pueda verlo en un espejo.","p":"Correcto. Salga de su punto ciego."},"zh":{"q":"你正开在另一辆车的侧后方，那位司机可能看不到你。你应该怎么做？","o":["留在那里，那是最安全的位置","每隔几秒按一次喇叭","加速或放慢，让自己不在那位司机的盲点里","打开你的危险警告灯"],"h1":"不要停留在别的司机看不到你的地方。","h2":"不要一直开在别的司机的盲点里；要加速或放慢，让那位司机能在后视镜里看到你。","p":"对。离开他们的盲点。"},"vi":{"q":"Bạn đang chạy ngay phía sau và bên cạnh một xe khác, nơi tài xế có thể không thấy bạn. Bạn nên làm gì?","o":["Ở yên đó; đó là chỗ an toàn nhất","Bấm còi mỗi vài giây","Tăng tốc hoặc lùi lại để không ở trong điểm mù của tài xế","Bật đèn khẩn cấp"],"h1":"Đừng ở chỗ mà tài xế kia không thấy bạn.","h2":"Đừng chạy trong điểm mù của tài xế khác; hãy tăng tốc hoặc lùi lại để tài xế đó thấy bạn trong gương.","p":"Đúng. Ra khỏi điểm mù của họ."},"tl":{"q":"Nagmamaneho ka sa likod at sa gilid ng isang kotse, kung saan baka hindi ka makita ng drayber. Ano ang dapat mong gawin?","o":["Manatili roon; iyon ang pinakaligtas na lugar","Bumusina bawat ilang segundo","Bumilis o umatras para wala ka sa blind spot ng drayber","Buksan ang iyong hazard lights"],"h1":"Huwag manatili kung saan hindi ka makita ng ibang drayber.","h2":"Huwag magmaneho sa blind spot ng ibang drayber; bumilis o umatras para makita ka ng drayber sa salamin.","p":"Tama. Umalis sa kanilang blind spot."},"ar":{"q":"أنت تقود خلف سيارة أخرى وإلى جانبها مباشرة، حيث قد لا يراك سائقها. ماذا تفعل؟","o":["تبقى هناك؛ فهو أكثر مكان آمن","تستعمل البوق كل بضع ثوانٍ","تُسرع أو تتأخر حتى لا تكون في النقطة العمياء للسائق","تُشغّل أضواء الطوارئ"],"h1":"يجب ألّا تبقى حيث لا يستطيع السائق الآخر أن يراك.","h2":"يجب ألّا تسير في النقطة العمياء لسائق آخر؛ أسرع أو تأخّر حتى يراك السائق في المرآة.","p":"صحيح. اخرج من نقطته العمياء."},"ht":{"q":"W ap kondui jis dèyè ak sou kote yon lòt machin, kote chofè a ka pa wè w. Kisa ou ta dwe fè?","o":["Rete la; se kote ki pi san danje a","Klaksonnen chak kèk segonn","Akselere oswa ralanti pou w pa nan zòn avèg chofè a","Limen limyè ijans ou yo"],"h1":"Pa rete kote lòt chofè a pa ka wè w.","h2":"Pa kondui nan zòn avèg yon lòt chofè; akselere oswa ralanti pou chofè a ka wè w nan yon miwa.","p":"Wi, se sa. Soti nan zòn avèg li."}},{"id":"speed-lanes-051","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"How should you set your side mirrors to see as much as possible?","o":["So you see mostly your own car","Pointed at the ground","Pointed at the sky","So you can just barely see the side of your own car"],"h1":"Seeing a lot of your own car wastes mirror space.","h2":"Set each side mirror so you can just barely see the side of your car; this shows more of the lanes beside you and makes blind spots smaller.","p":"Right. Just barely see your own car."},"es":{"q":"¿Cómo debe ajustar los espejos laterales para ver lo más posible?","o":["De modo que vea sobre todo su propio carro","Apuntando al suelo","Apuntando al cielo","De modo que apenas vea el costado de su propio carro"],"h1":"Ver mucho de su propio carro desperdicia espacio del espejo.","h2":"Ajuste cada espejo lateral de modo que apenas vea el costado de su carro; así ve más de los carriles a su lado y los puntos ciegos son más pequeños.","p":"Correcto. Apenas vea su propio carro."},"zh":{"q":"侧后视镜应该怎么调，才能看到最多的范围？","o":["让你主要看到自己的车","对着地面","对着天空","让你刚好能看到一点自己车的侧面"],"h1":"看到很多自己的车会浪费镜子的空间。","h2":"把每个侧后视镜调到刚好能看到一点自己车的侧面；这样能看到更多旁边的车道，盲点也会变小。","p":"对。刚好看到一点自己的车。"},"vi":{"q":"Bạn nên chỉnh gương chiếu hậu hai bên như thế nào để thấy được nhiều nhất?","o":["Để bạn thấy chủ yếu là xe của mình","Chĩa xuống đất","Chĩa lên trời","Để bạn vừa đủ thấy một chút hông xe của mình"],"h1":"Thấy nhiều xe của mình là phí chỗ trong gương.","h2":"Chỉnh mỗi gương bên để bạn vừa đủ thấy một chút hông xe của mình; như vậy gương cho thấy nhiều hơn các làn bên cạnh và điểm mù nhỏ hơn.","p":"Đúng. Vừa đủ thấy xe của mình."},"tl":{"q":"Paano mo dapat ayusin ang mga side mirror para makita ang pinakamarami?","o":["Para karamihan ng makikita mo ay ang sarili mong kotse","Nakaturo sa lupa","Nakaturo sa langit","Para halos hindi mo na makita ang gilid ng sarili mong kotse"],"h1":"Nasasayang ang espasyo ng salamin kung maraming bahagi ng sarili mong kotse ang nakikita.","h2":"Ayusin ang bawat side mirror para halos hindi mo na makita ang gilid ng kotse mo; mas marami nitong naipapakita ang mga lane sa tabi mo at lumiliit ang mga blind spot.","p":"Tama. Halos hindi na makita ang sarili mong kotse."},"ar":{"q":"كيف تضبط المرايا الجانبية لترى أكبر مساحة ممكنة؟","o":["بحيث ترى سيارتك في معظمها","موجّهة نحو الأرض","موجّهة نحو السماء","بحيث ترى جانب سيارتك بالكاد"],"h1":"رؤية جزء كبير من سيارتك تُضيّع مساحة المرآة.","h2":"اضبط كل مرآة جانبية بحيث ترى جانب سيارتك بالكاد؛ فهذا يُظهر جزءًا أكبر من المسارات بجانبك ويجعل النقاط العمياء أصغر.","p":"صحيح. ترى سيارتك بالكاد."},"ht":{"q":"Kijan ou ta dwe ranje miwa kote yo pou w wè plis bagay posib?","o":["Pou w wè sitou pwòp machin ou","Vire anba atè","Vire anlè nan syèl la","Pou w jis apèn wè bò pwòp machin ou"],"h1":"Si w wè anpil nan machin ou, ou gaspiye plas nan miwa a.","h2":"Ranje chak miwa kote pou w jis apèn wè bò machin ou; konsa li montre plis nan liy ki bò kote w yo epi zòn avèg yo vin pi piti.","p":"Wi, se sa. Jis apèn wè pwòp machin ou."}},{"id":"speed-lanes-052","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You just changed lanes. What should you check?","o":["That your turn signal has turned off","That your hazard lights are on","That your high beams are on","That your radio is off"],"h1":"A signal left on sends the wrong message.","h2":"After a lane change, make sure your turn signal is off, or other drivers may think you are about to turn or change lanes again.","p":"Right. Make sure the signal is off."},"es":{"q":"Usted acaba de cambiar de carril. ¿Qué debe revisar?","o":["Que la direccional se haya apagado","Que las luces de emergencia estén encendidas","Que las luces altas estén encendidas","Que el radio esté apagado"],"h1":"Una direccional encendida da un mensaje equivocado.","h2":"Después de cambiar de carril, asegúrese de que la direccional esté apagada, o los demás pueden pensar que va a girar o cambiar de carril otra vez.","p":"Correcto. Asegúrese de que esté apagada."},"zh":{"q":"你刚刚换了车道。你应该检查什么？","o":["你的转向灯已经关掉","你的危险警告灯开着","你的远光灯开着","你的收音机关着"],"h1":"转向灯一直开着会传递错误的信息。","h2":"换车道后，要确定你的转向灯已经关掉，不然其他司机可能以为你又要转弯或换车道。","p":"对。要确定转向灯关了。"},"vi":{"q":"Bạn vừa chuyển làn. Bạn nên kiểm tra điều gì?","o":["Đèn xi nhan của bạn đã tắt","Đèn khẩn cấp của bạn đang bật","Đèn pha chiếu xa của bạn đang bật","Radio của bạn đã tắt"],"h1":"Đèn xi nhan để quên sẽ báo sai cho người khác.","h2":"Sau khi chuyển làn, hãy chắc chắn đèn xi nhan đã tắt, nếu không các tài xế khác có thể nghĩ bạn sắp rẽ hoặc chuyển làn nữa.","p":"Đúng. Chắc chắn xi nhan đã tắt."},"tl":{"q":"Kalilipat mo lang ng lane. Ano ang dapat mong tingnan?","o":["Na namatay na ang iyong turn signal","Na nakabukas ang iyong hazard lights","Na nakabukas ang iyong high beams","Na nakapatay ang iyong radyo"],"h1":"Ang signal na naiwang nakabukas ay nagbibigay ng maling mensahe.","h2":"Pagkatapos lumipat ng lane, siguraduhing nakapatay ang iyong turn signal, dahil baka isipin ng ibang drayber na liliko ka o lilipat ulit ng lane.","p":"Tama. Siguraduhing nakapatay ang signal."},"ar":{"q":"غيّرت مسارك للتو. ما الذي يجب أن تتحقق منه؟","o":["أن إشارة الانعطاف انطفأت","أن أضواء الطوارئ مضاءة","أن الأضواء العالية مضاءة","أن الراديو مُطفأ"],"h1":"الإشارة التي تبقى مضاءة تعطي رسالة خاطئة.","h2":"بعد تغيير المسار، تأكد أن إشارة الانعطاف مُطفأة، وإلا قد يظن السائقون الآخرون أنك ستنعطف أو ستغيّر المسار مرة أخرى.","p":"صحيح. تأكد أن الإشارة مُطفأة."},"ht":{"q":"Ou fèk chanje liy. Kisa ou ta dwe tcheke?","o":["Siyal pou vire a etenn","Limyè ijans ou yo limen","Gwo limyè ou yo limen","Radyo ou etenn"],"h1":"Yon siyal ki rete limen bay move mesaj.","h2":"Apre ou chanje liy, asire w siyal pou vire a etenn, sinon lòt chofè ka panse ou pral vire oswa chanje liy ankò.","p":"Wi, se sa. Asire w siyal la etenn."}},{"id":"speed-lanes-053","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"Why should you look far down the road ahead, not just at the car in front of you?","o":["To read signs for fun","To see problems early and have time to react","To rest your eyes","Because the car ahead does not matter"],"h1":"Early warning gives you time.","h2":"Looking far ahead lets you spot hazards early, so you have more time to slow down, change lanes or stop smoothly.","p":"Right. You see trouble sooner."},"es":{"q":"¿Por qué debe mirar lejos hacia adelante, y no solo al carro de enfrente?","o":["Para leer señales por diversión","Para ver los problemas temprano y tener tiempo de reaccionar","Para descansar la vista","Porque el carro de adelante no importa"],"h1":"Ver antes le da tiempo.","h2":"Mirar lejos hacia adelante le permite ver los peligros temprano, así tiene más tiempo para bajar la velocidad, cambiar de carril o pararse con suavidad.","p":"Correcto. Ve los problemas antes."},"zh":{"q":"为什么你应该往前方远处看，而不只是看你前面那辆车？","o":["为了好玩去看标志","为了早点发现问题，有时间反应","为了让眼睛休息","因为前面的车不重要"],"h1":"提早发现能给你时间。","h2":"往前方远处看能让你早点发现危险，这样你有更多时间平稳地减速、换车道或停车。","p":"对。你能更早看到麻烦。"},"vi":{"q":"Tại sao bạn nên nhìn xa về phía trước, không chỉ nhìn xe ngay trước mặt?","o":["Để đọc biển báo cho vui","Để thấy vấn đề sớm và có thời gian phản ứng","Để mắt được nghỉ","Vì xe phía trước không quan trọng"],"h1":"Biết trước sớm cho bạn thêm thời gian.","h2":"Nhìn xa phía trước giúp bạn phát hiện mối nguy sớm, nên bạn có nhiều thời gian hơn để giảm tốc, chuyển làn hoặc dừng lại êm.","p":"Đúng. Bạn thấy rắc rối sớm hơn."},"tl":{"q":"Bakit dapat kang tumingin nang malayo sa daan sa unahan, hindi lang sa kotseng nasa harap mo?","o":["Para magbasa ng mga karatula bilang libangan","Para makita nang maaga ang mga problema at may oras kang kumilos","Para ipahinga ang iyong mga mata","Dahil hindi mahalaga ang kotse sa unahan"],"h1":"Ang maagang babala ay nagbibigay sa iyo ng oras.","h2":"Ang pagtingin nang malayo sa unahan ay tumutulong sa iyo na makita nang maaga ang mga panganib, kaya mas marami kang oras para bumagal, lumipat ng lane o huminto nang maayos.","p":"Tama. Mas maaga mong nakikita ang problema."},"ar":{"q":"لماذا يجب أن تنظر بعيدًا إلى الطريق أمامك، لا إلى السيارة التي أمامك فقط؟","o":["لتقرأ العلامات للتسلية","لترى المشكلات مبكرًا ويكون لديك وقت لتتصرف","لتريح عينيك","لأن السيارة التي أمامك لا تهم"],"h1":"التنبّه المبكر يعطيك وقتًا.","h2":"النظر بعيدًا إلى الأمام يجعلك تلاحظ الأخطار مبكرًا، فيكون لديك وقت أطول لتُبطئ أو تغيّر المسار أو تتوقف بهدوء.","p":"صحيح. ترى المشكلة أبكر."},"ht":{"q":"Poukisa ou ta dwe gade lwen devan sou wout la, pa sèlman machin ki devan w lan?","o":["Pou li siy pou plezi","Pou w wè pwoblèm bonè epi gen tan pou w reyaji","Pou repoze je ou","Paske machin devan an pa enpòtan"],"h1":"Lè w avèti bonè, ou gen tan.","h2":"Lè ou gade lwen devan, ou wè danje yo bonè, konsa ou gen plis tan pou w ralanti, chanje liy oswa kanpe dousman.","p":"Wi, se sa. Ou wè pwoblèm pi bonè."}},{"id":"speed-lanes-054","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"How often should you check your mirrors while driving?","o":["Only when you back up","Only at red lights","Every few seconds, and before slowing, stopping or changing lanes","Once at the start of the trip"],"h1":"Traffic around you changes all the time.","h2":"Check your mirrors every few seconds and always before you slow down, stop, turn or change lanes.","p":"Right. Every few seconds and before any change."},"es":{"q":"¿Cada cuánto debe mirar los espejos mientras maneja?","o":["Solo al retroceder","Solo en los semáforos en rojo","Cada pocos segundos, y antes de frenar, pararse o cambiar de carril","Una vez al empezar el viaje"],"h1":"El tráfico a su alrededor cambia todo el tiempo.","h2":"Mire los espejos cada pocos segundos y siempre antes de bajar la velocidad, pararse, girar o cambiar de carril.","p":"Correcto. Cada pocos segundos y antes de cualquier cambio."},"zh":{"q":"开车时你应该多久看一次后视镜？","o":["只在倒车时","只在红灯时","每隔几秒看一次，并且在减速、停车或换车道之前看","出发时看一次"],"h1":"你周围的交通一直在变化。","h2":"每隔几秒看一次后视镜，并且在减速、停车、转弯或换车道之前一定要看。","p":"对。每隔几秒，以及在任何变化之前。"},"vi":{"q":"Khi lái xe, bạn nên nhìn gương bao lâu một lần?","o":["Chỉ khi lùi xe","Chỉ khi gặp đèn đỏ","Mỗi vài giây, và trước khi giảm tốc, dừng lại hoặc chuyển làn","Một lần khi bắt đầu chuyến đi"],"h1":"Xe cộ quanh bạn thay đổi liên tục.","h2":"Hãy nhìn gương mỗi vài giây và luôn nhìn trước khi giảm tốc, dừng lại, rẽ hoặc chuyển làn.","p":"Đúng. Mỗi vài giây và trước mọi thay đổi."},"tl":{"q":"Gaano kadalas mo dapat tingnan ang mga salamin habang nagmamaneho?","o":["Kapag umaatras ka lang","Sa pulang ilaw lang","Bawat ilang segundo, at bago bumagal, huminto o lumipat ng lane","Isang beses sa simula ng biyahe"],"h1":"Palaging nagbabago ang trapiko sa paligid mo.","h2":"Tingnan ang iyong mga salamin bawat ilang segundo at palagi bago ka bumagal, huminto, lumiko o lumipat ng lane.","p":"Tama. Bawat ilang segundo at bago ang anumang pagbabago."},"ar":{"q":"كم مرة يجب أن تنظر في مراياك وأنت تقود؟","o":["فقط عندما ترجع إلى الخلف","فقط عند الإشارات الحمراء","كل بضع ثوانٍ، وقبل أن تُبطئ أو تتوقف أو تغيّر المسار","مرة واحدة في بداية الرحلة"],"h1":"حركة السير حولك تتغير طوال الوقت.","h2":"انظر في مراياك كل بضع ثوانٍ، ودائمًا قبل أن تُبطئ أو تتوقف أو تنعطف أو تغيّر المسار.","p":"صحيح. كل بضع ثوانٍ وقبل أي تغيير."},"ht":{"q":"Konbyen fwa ou ta dwe gade miwa ou yo pandan w ap kondui?","o":["Sèlman lè w ap fè bak","Sèlman nan limyè wouj","Chak kèk segonn, epi anvan ou ralanti, kanpe oswa chanje liy","Yon fwa nan kòmansman vwayaj la"],"h1":"Machin ki bò kote w yo ap chanje tout tan.","h2":"Gade miwa ou yo chak kèk segonn epi toujou anvan ou ralanti, kanpe, vire oswa chanje liy.","p":"Wi, se sa. Chak kèk segonn epi anvan nenpòt chanjman."}},{"id":"speed-lanes-055","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Why should you avoid stopping at the end of a freeway on-ramp, if traffic allows?","o":["Stopping there is always a crime","Cars behind you will pass on the shoulder","The ramp will close","It is very hard to merge into fast traffic from a stop"],"h1":"Freeway traffic is moving fast.","h2":"Use the ramp to build up speed; stopping at the end means trying to merge into fast traffic from a standstill, which is dangerous.","p":"Right. Merging from a stop is very hard."},"es":{"q":"¿Por qué debe evitar pararse al final de una rampa de entrada a la autopista, si el tráfico lo permite?","o":["Porque pararse allí siempre es un delito","Porque los de atrás lo rebasarán por el acotamiento","Porque la rampa se cerrará","Porque es muy difícil incorporarse al tráfico rápido desde cero"],"h1":"El tráfico de la autopista va rápido.","h2":"Use la rampa para tomar velocidad; pararse al final significa incorporarse a un tráfico rápido desde cero, lo cual es peligroso.","p":"Correcto. Incorporarse desde cero es muy difícil."},"zh":{"q":"如果车流允许，为什么要避免在快速路入口匝道的尽头停下？","o":["在那里停车永远是犯罪","你后面的车会从路肩超过你","匝道会关闭","从停住的状态并入快速车流非常困难"],"h1":"快速路上的车开得很快。","h2":"你要利用匝道加速；在匝道尽头停下，就得从完全停住的状态并入快速车流，这很危险。","p":"对。从停住的状态并道非常困难。"},"vi":{"q":"Nếu dòng xe cho phép, tại sao bạn nên tránh dừng lại ở cuối đường dẫn vào đường cao tốc?","o":["Dừng ở đó luôn là phạm tội","Xe phía sau sẽ vượt bạn trên lề đường","Đường dẫn sẽ bị đóng","Rất khó nhập vào dòng xe chạy nhanh khi đang đứng yên"],"h1":"Xe trên đường cao tốc chạy rất nhanh.","h2":"Hãy dùng đường dẫn để tăng tốc; dừng lại ở cuối đường dẫn nghĩa là phải nhập vào dòng xe chạy nhanh từ chỗ đứng yên, điều này rất nguy hiểm.","p":"Đúng. Nhập làn từ chỗ đứng yên rất khó."},"tl":{"q":"Bakit dapat mong iwasang huminto sa dulo ng on-ramp ng expressway, kung pinapayagan ng trapiko?","o":["Laging krimen ang paghinto roon","Lalampasan ka ng mga kotse sa likod mo sa gilid ng daan (shoulder)","Isasara ang ramp","Napakahirap pumasok sa mabilis na trapiko mula sa pagkakahinto"],"h1":"Mabilis ang takbo ng trapiko sa expressway.","h2":"Gamitin ang ramp para bumilis; kapag huminto ka sa dulo, kailangan mong pumasok sa mabilis na trapiko mula sa pagkakahinto, at mapanganib iyon.","p":"Tama. Napakahirap pumasok mula sa pagkakahinto."},"ar":{"q":"لماذا يجب أن تتجنب التوقف عند نهاية منحدر الدخول إلى الطريق السريع، إذا سمحت حركة السير؟","o":["التوقف هناك جريمة دائمًا","السيارات خلفك ستتجاوزك على كتف الطريق","المنحدر سيُغلق","من الصعب جدًا أن تندمج في سير سريع وأنت متوقف"],"h1":"السيارات على الطريق السريع تسير بسرعة.","h2":"استعمل المنحدر لتزيد سرعتك؛ فالتوقف عند نهايته يعني أن تحاول الاندماج في سير سريع من الوقوف التام، وهذا خطير.","p":"صحيح. الاندماج من الوقوف صعب جدًا."},"ht":{"q":"Poukisa ou ta dwe evite kanpe nan bout ranp pou antre sou otowout la, si sikilasyon an pèmèt?","o":["Kanpe la a toujou yon krim","Machin dèyè ou yo ap pase ou sou bò wout la","Ranp lan ap fèmen","Li difisil anpil pou antre nan machin k ap kouri vit lè ou kanpe"],"h1":"Machin sou otowout la ap kouri vit.","h2":"Sèvi ak ranp lan pou ou pran vitès; si ou kanpe nan bout li, ou oblije antre nan machin k ap kouri vit pandan ou kanpe nèt, e sa danjere.","p":"Wi, se sa. Antre lè ou kanpe difisil anpil."}},{"id":"speed-lanes-056","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You are on the freeway in the right lane. A car is coming down an on-ramp to merge. How can you help?","o":["Move one lane left if it is safe, or adjust your speed to leave a gap","Speed up so it cannot merge","Stop in your lane","Honk to warn it"],"h1":"Merging is easier when others make room.","h2":"To help a car merge, change lanes to the left if it is safe, or adjust your speed so there is a gap for it.","p":"Right. Make room if you safely can."},"es":{"q":"Usted va por la autopista en el carril derecho. Un carro baja por una rampa para incorporarse. ¿Cómo puede ayudar?","o":["Pasarse un carril a la izquierda si es seguro, o ajustar su velocidad para dejar espacio","Acelerar para que no pueda entrar","Pararse en su carril","Tocar la bocina para avisarle"],"h1":"Incorporarse es más fácil cuando los demás dejan espacio.","h2":"Para ayudar a un carro a incorporarse, cámbiese a la izquierda si es seguro, o ajuste su velocidad para dejarle un espacio.","p":"Correcto. Dele espacio si puede hacerlo con seguridad."},"zh":{"q":"你在快速路的右侧车道上。一辆车正从入口匝道下来准备并道。你可以怎样帮忙？","o":["如果安全，向左换一条车道，或调整车速留出空隙","加速让它无法并道","在你的车道里停下","按喇叭警告它"],"h1":"别人让出空间时，并道会更容易。","h2":"为了帮助一辆车并道，如果安全，你可以向左换车道，或调整车速，给它留出一个空隙。","p":"对。如果能安全做到，就让出空间。"},"vi":{"q":"Bạn đang ở làn bên phải trên đường cao tốc. Một xe đang đi xuống đường dẫn để nhập vào. Bạn có thể giúp bằng cách nào?","o":["Chuyển sang một làn bên trái nếu an toàn, hoặc điều chỉnh tốc độ để chừa khoảng trống","Tăng tốc để nó không nhập vào được","Dừng lại trong làn của bạn","Bấm còi để cảnh báo nó"],"h1":"Nhập làn dễ hơn khi người khác nhường chỗ.","h2":"Để giúp một xe nhập làn, hãy chuyển sang làn bên trái nếu an toàn, hoặc điều chỉnh tốc độ để có khoảng trống cho xe đó.","p":"Đúng. Hãy nhường chỗ nếu bạn có thể làm an toàn."},"tl":{"q":"Nasa kanang lane ka ng expressway. May kotseng bumababa sa on-ramp para pumasok. Paano ka makakatulong?","o":["Lumipat nang isang lane pakaliwa kung ligtas, o ayusin ang bilis mo para mag-iwan ng puwang","Bumilis para hindi ito makapasok","Huminto sa lane mo","Bumusina para balaan ito"],"h1":"Mas madaling pumasok kapag nagbibigay ng puwang ang iba.","h2":"Para matulungan ang kotseng pumasok, lumipat pakaliwa kung ligtas, o ayusin ang bilis mo para may puwang para rito.","p":"Tama. Magbigay ng puwang kung ligtas mong magagawa."},"ar":{"q":"أنت على الطريق السريع في المسار الأيمن. سيارة تنزل على منحدر الدخول لتندمج. كيف تساعدها؟","o":["انتقل مسارًا واحدًا إلى اليسار إذا كان ذلك آمنًا، أو عدّل سرعتك لتترك فراغًا","زِد سرعتك حتى لا تستطيع الاندماج","توقف في مسارك","استعمل البوق لتحذيرها"],"h1":"الاندماج أسهل عندما يفسح الآخرون المجال.","h2":"لتساعد سيارة على الاندماج، انتقل إلى المسار الأيسر إذا كان ذلك آمنًا، أو عدّل سرعتك حتى يكون هناك فراغ لها.","p":"صحيح. أفسح المجال إذا استطعت ذلك بأمان."},"ht":{"q":"Ou sou otowout la nan liy adwat la. Yon machin ap desann yon ranp pou antre. Kijan ou ka ede l?","o":["Pase yon liy sou bò goch si sa an sekirite, oswa chanje vitès ou pou kite yon espas","Akselere pou li pa ka antre","Kanpe nan liy ou","Klaksonnen pou avèti l"],"h1":"Li pi fasil pou antre lè lòt moun fè plas.","h2":"Pou ede yon machin antre, pase sou liy agoch la si sa an sekirite, oswa chanje vitès ou pou gen yon espas pou li.","p":"Wi, se sa. Fè plas si ou ka fè l an sekirite."}},{"id":"speed-lanes-057","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"As you merge onto a freeway, how do you check for a gap in traffic?","o":["Use only the rearview mirror","Use your mirrors and a quick look over your shoulder","Look only straight ahead","Wait for other drivers to wave you in"],"h1":"Your mirrors have blind spots.","h2":"To merge, check your mirrors and take a quick look over your shoulder to find a safe gap, then signal and merge smoothly.","p":"Right. Mirrors plus a look over your shoulder."},"es":{"q":"Al incorporarse a una autopista, ¿cómo revisa si hay un espacio en el tráfico?","o":["Solo con el espejo retrovisor","Con los espejos y una mirada rápida por encima del hombro","Mirando solo hacia adelante","Esperando que otros le hagan señas"],"h1":"Los espejos tienen puntos ciegos.","h2":"Para incorporarse, mire los espejos y eche una mirada rápida por encima del hombro para encontrar un espacio seguro; luego señale y entre con suavidad.","p":"Correcto. Espejos y una mirada por encima del hombro."},"zh":{"q":"当你并入快速路时，怎样检查车流中的空隙？","o":["只看车内后视镜","看后视镜，并快速转头从肩膀上方看一眼","只看正前方","等其他司机挥手让你进去"],"h1":"后视镜有盲区。","h2":"并道时，要看后视镜，再快速转头从肩膀上方看一眼，找到安全的空隙，然后打转向灯，平稳并入。","p":"对。看后视镜，再转头从肩膀上方看一眼。"},"vi":{"q":"Khi nhập vào đường cao tốc, bạn kiểm tra khoảng trống trong dòng xe bằng cách nào?","o":["Chỉ dùng gương chiếu hậu trong xe","Dùng các gương và nhìn nhanh qua vai","Chỉ nhìn thẳng phía trước","Chờ người lái khác vẫy tay cho bạn vào"],"h1":"Gương của bạn có điểm mù.","h2":"Để nhập làn, hãy nhìn các gương và nhìn nhanh qua vai để tìm khoảng trống an toàn, rồi bật xi nhan và nhập vào một cách êm.","p":"Đúng. Nhìn gương và nhìn qua vai."},"tl":{"q":"Habang pumapasok ka sa expressway, paano mo sinusuri kung may puwang sa trapiko?","o":["Gamitin lang ang rearview mirror","Gamitin ang mga salamin mo at mabilis na lumingon sa likod ng balikat mo","Tumingin lang nang diretso sa unahan","Hintaying kawayan ka ng ibang drayber para pumasok"],"h1":"May blind spot ang mga salamin mo.","h2":"Para pumasok, tingnan ang mga salamin mo at mabilis na lumingon sa likod ng balikat mo para makahanap ng ligtas na puwang, saka mag-signal at pumasok nang maayos.","p":"Tama. Mga salamin at isang lingon sa likod ng balikat."},"ar":{"q":"وأنت تندمج في الطريق السريع، كيف تتأكد من وجود فراغ في السير؟","o":["استعمل مرآة الرؤية الخلفية فقط","استعمل المرايا وانظر نظرة سريعة من فوق كتفك","انظر إلى الأمام فقط","انتظر حتى يشير لك سائقون آخرون بالدخول"],"h1":"المرايا فيها نقاط عمياء.","h2":"لكي تندمج، انظر في المرايا ثم انظر نظرة سريعة من فوق كتفك لتجد فراغًا آمنًا، ثم شغّل الإشارة واندمج بهدوء.","p":"صحيح. المرايا ونظرة من فوق الكتف."},"ht":{"q":"Lè w ap antre sou otowout la, kijan ou tcheke si gen yon espas nan sikilasyon an?","o":["Sèvi sèlman ak retwovizè anndan an","Sèvi ak retwovizè ou yo epi gade vit pa dèyè zepòl ou","Gade sèlman tou dwat devan ou","Tann lòt chofè fè ou siy pou antre"],"h1":"Retwovizè ou yo gen kwen ou pa wè.","h2":"Pou antre, tcheke retwovizè ou yo epi gade vit pa dèyè zepòl ou pou jwenn yon espas ki an sekirite, apre sa mete siyal epi antre dousman.","p":"Wi, se sa. Retwovizè yo plis yon gade pa dèyè zepòl ou."}},{"id":"speed-lanes-058","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"Your freeway exit is coming up in a mile. What should you do?","o":["Stay in the left lane and cut across at the end","Slow down sharply in the main lanes","Move into the lane next to the exit early and signal before the exit","Stop on the shoulder near the exit"],"h1":"Plan ahead so you do not need sudden moves.","h2":"Before a freeway exit, move into the lane next to the exit early, signal, and wait to slow down until you are in the exit lane.","p":"Right. Get over early and signal."},"es":{"q":"Su salida de la autopista está a una milla. ¿Qué debe hacer?","o":["Quedarse en el carril izquierdo y cruzar al final","Frenar fuerte en los carriles principales","Pasarse temprano al carril junto a la salida y señalar antes de salir","Pararse en el acotamiento cerca de la salida"],"h1":"Planee con tiempo para no hacer movimientos bruscos.","h2":"Antes de una salida, pásese temprano al carril junto a la salida, señale, y espere a estar en el carril de salida para bajar la velocidad.","p":"Correcto. Cámbiese temprano y señale."},"zh":{"q":"再过一英里就是你要走的快速路出口。你应该怎么做？","o":["留在最左侧车道，到最后再横穿过去","在主车道上猛地减速","提前换到靠近出口的车道，并在出口前打转向灯","在出口附近的路肩上停车"],"h1":"提前计划，就不需要突然的动作。","h2":"在快速路出口前，要提前换到靠近出口的车道，打转向灯，等进入出口车道后再减速。","p":"对。提前换道并打转向灯。"},"vi":{"q":"Còn một dặm nữa là đến lối ra đường cao tốc của bạn. Bạn nên làm gì?","o":["Ở lại làn bên trái và cắt ngang ở phút cuối","Giảm tốc mạnh trong các làn chính","Sớm chuyển vào làn sát lối ra và bật xi nhan trước lối ra","Dừng trên lề đường gần lối ra"],"h1":"Hãy tính trước để không phải đổi hướng đột ngột.","h2":"Trước lối ra đường cao tốc, hãy sớm chuyển vào làn sát lối ra, bật xi nhan, và chờ đến khi vào làn ra mới giảm tốc.","p":"Đúng. Chuyển làn sớm và bật xi nhan."},"tl":{"q":"Isang milya na lang ang labasan mo sa expressway. Ano ang dapat mong gawin?","o":["Manatili sa kaliwang lane at tumawid sa dulo","Biglang magpabagal sa mga pangunahing lane","Lumipat nang maaga sa lane na katabi ng labasan at mag-signal bago ang labasan","Huminto sa gilid ng daan (shoulder) malapit sa labasan"],"h1":"Magplano nang maaga para hindi mo kailanganin ang biglang galaw.","h2":"Bago ang labasan ng expressway, lumipat nang maaga sa lane na katabi ng labasan, mag-signal, at maghintay na makapasok sa exit lane bago magpabagal.","p":"Tama. Lumipat nang maaga at mag-signal."},"ar":{"q":"مخرجك من الطريق السريع بعد ميل واحد. ماذا يجب أن تفعل؟","o":["ابقَ في المسار الأيسر واقطع المسارات في آخر لحظة","خفّف سرعتك فجأة في المسارات الرئيسية","انتقل مبكرًا إلى المسار المجاور للمخرج وشغّل الإشارة قبل المخرج","توقف على كتف الطريق قرب المخرج"],"h1":"خطّط مسبقًا حتى لا تحتاج إلى حركات مفاجئة.","h2":"قبل مخرج الطريق السريع، انتقل مبكرًا إلى المسار المجاور للمخرج، وشغّل الإشارة، ولا تخفّف سرعتك حتى تدخل مسار الخروج.","p":"صحيح. انتقل مبكرًا وشغّل الإشارة."},"ht":{"q":"Sòti otowout ou a rive nan yon mil. Kisa ou ta dwe fè?","o":["Rete nan liy agoch la epi travèse nan dènye moman","Ralanti sèk nan liy prensipal yo","Pase bonè nan liy ki akote sòti a epi mete siyal anvan sòti a","Kanpe sou bò wout la toupre sòti a"],"h1":"Planifye davans pou ou pa bezwen fè mouvman sanzatann.","h2":"Anvan yon sòti otowout, pase bonè nan liy ki akote sòti a, mete siyal, epi tann ou antre nan liy sòti a pou ou ralanti.","p":"Wi, se sa. Pase bonè epi mete siyal."}},{"id":"speed-lanes-059","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"You park on a hill where there is no curb. Which way should you turn your front wheels?","o":["Toward the middle of the road","Straight ahead","It does not matter","Toward the edge of the road, away from traffic"],"h1":"If the car rolls, it should roll off the road.","h2":"On a hill with no curb, turn your front wheels toward the edge of the road, so if the car rolls it goes away from traffic.","p":"Right. Toward the edge of the road."},"es":{"q":"Usted se estaciona en una loma donde no hay acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia el centro de la vía","Derecho","No importa","Hacia la orilla de la vía, lejos del tráfico"],"h1":"Si el carro rueda, debe salirse de la vía.","h2":"En una loma sin acera, gire las ruedas delanteras hacia la orilla de la vía, así si el carro rueda se aleja del tráfico.","p":"Correcto. Hacia la orilla de la vía."},"zh":{"q":"你在没有路缘石的坡道上停车。前轮应该朝哪个方向转？","o":["朝向道路中间","朝正前方","无所谓","朝向路边，远离车流"],"h1":"如果车滑动，应该让它滑离道路。","h2":"在没有路缘石的坡道上，要把前轮转向路边，这样如果车滑动，它会远离车流。","p":"对。朝向路边。"},"vi":{"q":"Bạn đỗ xe trên dốc ở chỗ không có lề đá (curb). Bạn nên quay bánh trước về hướng nào?","o":["Về phía giữa đường","Thẳng phía trước","Không quan trọng","Về phía mép đường, xa dòng xe"],"h1":"Nếu xe bị trôi, nó nên trôi ra khỏi đường.","h2":"Trên dốc không có lề đá, hãy quay bánh trước về phía mép đường, để nếu xe bị trôi thì nó đi xa khỏi dòng xe.","p":"Đúng. Về phía mép đường."},"tl":{"q":"Pumarada ka sa paakyat o pababang daan na walang curb. Saang direksiyon mo dapat iliko ang mga gulong sa unahan?","o":["Papunta sa gitna ng daan","Diretso sa unahan","Hindi mahalaga","Papunta sa gilid ng daan, palayo sa trapiko"],"h1":"Kung gumulong ang kotse, dapat itong gumulong palabas ng daan.","h2":"Sa paakyat o pababang daan na walang curb, iliko ang mga gulong sa unahan papunta sa gilid ng daan, para kung gumulong ang kotse, palayo ito sa trapiko.","p":"Tama. Papunta sa gilid ng daan."},"ar":{"q":"توقف سيارتك على منحدر لا يوجد فيه رصيف. إلى أي اتجاه يجب أن تدير العجلات الأمامية؟","o":["نحو وسط الطريق","إلى الأمام مباشرة","لا يهم","نحو حافة الطريق، بعيدًا عن السير"],"h1":"إذا تحركت السيارة، يجب أن تتحرك خارج الطريق.","h2":"على منحدر لا رصيف فيه، أدر العجلات الأمامية نحو حافة الطريق، حتى إذا تحركت السيارة تذهب بعيدًا عن السير.","p":"صحيح. نحو حافة الطريق."},"ht":{"q":"Ou pake sou yon mòn kote pa gen bòdi twotwa. Ki bò ou ta dwe vire wou devan yo?","o":["Nan mitan wout la","Tou dwat devan","Sa pa gen enpòtans","Sou bò wout la, lwen sikilasyon an"],"h1":"Si machin nan woule, li ta dwe woule soti sou wout la.","h2":"Sou yon mòn ki pa gen bòdi twotwa, vire wou devan yo sou bò wout la, konsa si machin nan woule li ale lwen sikilasyon an.","p":"Wi, se sa. Sou bò wout la."}},{"id":"speed-lanes-060","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You park on any hill. What else should you do besides turning your wheels?","o":["Set the parking brake","Leave the engine running","Turn on your hazard lights","Leave the car in neutral"],"h1":"Something must hold the car still.","h2":"When you park on a hill, always set the parking brake and leave the car in park (or in gear for a manual) as well as turning the wheels.","p":"Right. Set the parking brake."},"es":{"q":"Usted se estaciona en cualquier loma. Además de girar las ruedas, ¿qué más debe hacer?","o":["Poner el freno de mano","Dejar el motor encendido","Encender las luces de emergencia","Dejar el carro en neutro"],"h1":"Algo debe mantener el carro quieto.","h2":"Al estacionarse en una loma, siempre ponga el freno de mano y deje el carro en \"park\" (o en cambio si es manual), además de girar las ruedas.","p":"Correcto. Ponga el freno de mano."},"zh":{"q":"你在任何坡道上停车。除了转动车轮，你还应该做什么？","o":["拉上驻车制动（手刹）","让发动机继续运转","打开危险警告灯（双闪）","把车挂在空挡"],"h1":"必须有东西让车保持不动。","h2":"在坡道上停车时，除了转动车轮，一定要拉上驻车制动，并把车挂在 P 挡（手动挡车挂在一个挡位上）。","p":"对。拉上驻车制动。"},"vi":{"q":"Bạn đỗ xe trên bất kỳ con dốc nào. Ngoài việc quay bánh xe, bạn còn nên làm gì?","o":["Kéo phanh tay","Để máy xe tiếp tục chạy","Bật đèn khẩn cấp","Để xe ở số mo (N)"],"h1":"Phải có thứ gì đó giữ xe đứng yên.","h2":"Khi đỗ xe trên dốc, ngoài việc quay bánh xe, hãy luôn kéo phanh tay và để xe ở số P (hoặc vào một số nếu là xe số tay).","p":"Đúng. Kéo phanh tay."},"tl":{"q":"Pumarada ka sa kahit anong paakyat o pababang daan. Ano pa ang dapat mong gawin bukod sa pagliko ng mga gulong?","o":["Itaas ang parking brake","Iwanang tumatakbo ang makina","Buksan ang hazard lights","Iwanan ang kotse sa neutral"],"h1":"Kailangang may pumipigil sa kotse para hindi ito gumalaw.","h2":"Kapag pumarada ka sa paakyat o pababang daan, laging itaas ang parking brake at ilagay ang kotse sa park (o sa isang gear kung manual), bukod sa pagliko ng mga gulong.","p":"Tama. Itaas ang parking brake."},"ar":{"q":"توقف سيارتك على أي منحدر. ماذا يجب أن تفعل أيضًا إلى جانب إدارة العجلات؟","o":["شدّ فرامل الوقوف (فرامل اليد)","اترك المحرك يعمل","شغّل أضواء التحذير","اترك السيارة على وضع الحياد"],"h1":"يجب أن يثبّت شيء ما السيارة في مكانها.","h2":"عندما توقف سيارتك على منحدر، شدّ دائمًا فرامل الوقوف وضع السيارة على وضع الوقوف P (أو على غيار معيّن في السيارة اليدوية)، إلى جانب إدارة العجلات.","p":"صحيح. شدّ فرامل الوقوف."},"ht":{"q":"Ou pake sou nenpòt mòn. Kisa ankò ou ta dwe fè anplis vire wou yo?","o":["Mete fren pakin nan (fren a men)","Kite motè a ap mache","Limen limyè danje yo","Kite machin nan nan neutral"],"h1":"Fòk gen yon bagay ki kenbe machin nan an plas.","h2":"Lè ou pake sou yon mòn, toujou mete fren pakin nan epi mete machin nan nan park (oswa nan yon vitès si se yon machin manyèl), anplis vire wou yo.","p":"Wi, se sa. Mete fren pakin nan."}},{"id":"speed-lanes-061","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"You are pulling out of a parallel parking space. What should you do first?","o":["Pull out quickly before cars come","Signal, check your mirror and look over your shoulder, then go when there is a safe gap","Honk and pull out","Back into traffic"],"h1":"Cars in the lane have the right of way.","h2":"Before leaving a parking space, signal, check your mirror and blind spot, and wait for a safe gap, because traffic in the lane goes first.","p":"Right. Signal, look, and wait for a gap."},"es":{"q":"Usted va a salir de un espacio de estacionamiento en paralelo. ¿Qué debe hacer primero?","o":["Salir rápido antes de que vengan carros","Señalar, mirar el espejo y por encima del hombro, y salir cuando haya un espacio seguro","Tocar la bocina y salir","Retroceder hacia el tráfico"],"h1":"Los carros en el carril tienen el derecho de paso.","h2":"Antes de salir de un espacio de estacionamiento, señale, mire el espejo y el punto ciego, y espere un espacio seguro, porque el tráfico del carril va primero.","p":"Correcto. Señale, mire y espere un espacio."},"zh":{"q":"你要从路边的平行停车位开出来。你首先应该做什么？","o":["趁车还没来赶快开出去","打转向灯，看后视镜并转头从肩膀上方看，等有安全空隙时再走","按喇叭然后开出去","倒车进入车流"],"h1":"车道上的车有先行权。","h2":"离开停车位之前，要打转向灯，检查后视镜和盲区，并等待安全的空隙，因为车道上的车先走。","p":"对。打转向灯、观察，并等待空隙。"},"vi":{"q":"Bạn đang lái ra khỏi chỗ đỗ xe song song. Bạn nên làm gì trước tiên?","o":["Lái ra thật nhanh trước khi có xe tới","Bật xi nhan, nhìn gương và nhìn qua vai, rồi đi khi có khoảng trống an toàn","Bấm còi rồi lái ra","Lùi vào dòng xe"],"h1":"Xe đang chạy trong làn được quyền ưu tiên.","h2":"Trước khi rời chỗ đỗ, hãy bật xi nhan, kiểm tra gương và điểm mù, và chờ khoảng trống an toàn, vì xe trong làn được đi trước.","p":"Đúng. Bật xi nhan, quan sát và chờ khoảng trống."},"tl":{"q":"Lalabas ka mula sa parallel parking. Ano ang dapat mong gawin muna?","o":["Lumabas nang mabilis bago dumating ang mga kotse","Mag-signal, tingnan ang salamin mo at lumingon sa likod ng balikat mo, saka umalis kapag may ligtas na puwang","Bumusina at lumabas","Umatras papasok sa trapiko"],"h1":"May karapatan sa daan ang mga kotseng nasa lane.","h2":"Bago umalis sa paradahan, mag-signal, tingnan ang salamin mo at ang blind spot, at maghintay ng ligtas na puwang, dahil nauuna ang trapiko sa lane.","p":"Tama. Mag-signal, tumingin, at maghintay ng puwang."},"ar":{"q":"أنت تخرج من موقف اصطفاف موازٍ. ماذا يجب أن تفعل أولًا؟","o":["اخرج بسرعة قبل أن تأتي السيارات","شغّل الإشارة، وانظر في المرآة ومن فوق كتفك، ثم انطلق عندما يكون هناك فراغ آمن","استعمل البوق واخرج","ارجع إلى الخلف داخل السير"],"h1":"السيارات التي في المسار لها حق المرور.","h2":"قبل أن تغادر موقف السيارة، شغّل الإشارة، وانظر في المرآة وافحص النقطة العمياء، وانتظر فراغًا آمنًا، لأن السيارات التي في المسار تمرّ أولًا.","p":"صحيح. شغّل الإشارة، وانظر، وانتظر فراغًا."},"ht":{"q":"W ap soti nan yon plas pakin paralèl. Kisa ou ta dwe fè anvan?","o":["Soti vit anvan machin yo vini","Mete siyal, tcheke retwovizè ou epi gade pa dèyè zepòl ou, apre sa ale lè gen yon espas ki an sekirite","Klaksonnen epi soti","Fè bak antre nan sikilasyon an"],"h1":"Machin ki nan liy lan gen dwa pase.","h2":"Anvan ou kite yon plas pakin, mete siyal, tcheke retwovizè ou ak kwen ou pa wè a, epi tann yon espas ki an sekirite, paske machin ki nan liy lan pase anvan.","p":"Wi, se sa. Mete siyal, gade, epi tann yon espas."}},{"id":"speed-lanes-062","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"Why can driving much slower than the traffic around you be dangerous?","o":["Your engine will overheat","Slow cars use more gas","Other drivers must brake hard or pass you, which can cause crashes","It is never dangerous"],"h1":"Big speed differences cause conflicts.","h2":"Driving much slower than other traffic makes drivers behind you brake suddenly or pass, which raises the chance of a crash.","p":"Right. It forces others to brake or pass."},"es":{"q":"¿Por qué manejar mucho más despacio que el tráfico a su alrededor puede ser peligroso?","o":["Porque el motor se calienta","Porque los carros lentos gastan más gasolina","Porque los demás deben frenar fuerte o rebasarlo, lo que puede causar choques","Nunca es peligroso"],"h1":"Las grandes diferencias de velocidad causan conflictos.","h2":"Manejar mucho más despacio que los demás hace que los de atrás frenen de golpe o lo rebasen, lo que aumenta el riesgo de choque.","p":"Correcto. Obliga a los demás a frenar o rebasar."},"zh":{"q":"为什么开得比周围车流慢很多可能会很危险？","o":["你的发动机会过热","慢车更费油","其他司机必须猛踩刹车或超车，这可能造成撞车","这从来都不危险"],"h1":"车速相差很大会引起冲突。","h2":"开得比其他车慢很多，会让后面的司机突然刹车或超车，这会增加撞车的可能。","p":"对。这会逼别人刹车或超车。"},"vi":{"q":"Tại sao lái chậm hơn nhiều so với dòng xe xung quanh có thể nguy hiểm?","o":["Máy xe của bạn sẽ bị quá nóng","Xe chạy chậm tốn xăng hơn","Người lái khác phải phanh gấp hoặc vượt bạn, điều này có thể gây tai nạn","Điều đó không bao giờ nguy hiểm"],"h1":"Chênh lệch tốc độ lớn gây ra xung đột.","h2":"Lái chậm hơn nhiều so với các xe khác khiến người lái phía sau phải phanh đột ngột hoặc vượt, làm tăng nguy cơ tai nạn.","p":"Đúng. Nó buộc người khác phải phanh hoặc vượt."},"tl":{"q":"Bakit maaaring mapanganib ang pagmamaneho nang mas mabagal nang husto kaysa sa trapiko sa paligid mo?","o":["Mag-o-overheat ang makina mo","Mas malakas sa gasolina ang mabagal na kotse","Kailangang magpreno nang malakas o lumampas sa iyo ang ibang drayber, at maaari itong magdulot ng banggaan","Hindi ito kailanman mapanganib"],"h1":"Nagdudulot ng gulo ang malaking pagkakaiba ng bilis.","h2":"Kapag mas mabagal ka nang husto kaysa sa ibang trapiko, napipilitang biglang magpreno o lumampas ang mga drayber sa likod mo, at tumataas ang posibilidad ng banggaan.","p":"Tama. Napipilitan ang iba na magpreno o lumampas."},"ar":{"q":"لماذا قد تكون القيادة بسرعة أبطأ بكثير من السير حولك خطيرة؟","o":["محركك سترتفع حرارته","السيارات البطيئة تستهلك وقودًا أكثر","السائقون الآخرون يضطرون إلى الفرملة بقوة أو تجاوزك، وهذا قد يسبب حوادث","هي ليست خطيرة أبدًا"],"h1":"الفروق الكبيرة في السرعة تسبب مواقف خطرة.","h2":"القيادة بسرعة أبطأ بكثير من بقية السيارات تجعل السائقين خلفك يفرملون فجأة أو يتجاوزونك، وهذا يزيد احتمال وقوع حادث.","p":"صحيح. فهي تجبر الآخرين على الفرملة أو التجاوز."},"ht":{"q":"Poukisa kondui pi dousman anpil pase machin ki bò kote ou ka danjere?","o":["Motè ou ap chofe twòp","Machin ki mache dousman boule plis gaz","Lòt chofè oblije frennen fò oswa double ou, sa ka lakòz aksidan","Li pa janm danjere"],"h1":"Gwo diferans nan vitès lakòz konfli.","h2":"Lè ou kondui pi dousman anpil pase lòt machin yo, chofè dèyè ou yo oblije frennen sanzatann oswa double ou, e sa ogmante chans pou gen yon aksidan.","p":"Wi, se sa. Li fòse lòt moun frennen oswa double."}},{"id":"speed-lanes-063","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Besides a longer stopping distance, what else happens when you drive faster?","o":["Your car grips the road better","You see more of the road","Your seat belt works better","A crash hits much harder, so injuries are worse"],"h1":"More speed means more force.","h2":"Higher speed means more force in a crash, so injuries are much more serious, in addition to needing more distance to stop.","p":"Right. Crashes are much more severe."},"es":{"q":"Además de necesitar más distancia para frenar, ¿qué más pasa cuando maneja más rápido?","o":["El carro se agarra mejor a la vía","Ve más de la vía","El cinturón funciona mejor","Un choque golpea mucho más fuerte, así que las lesiones son peores"],"h1":"Más velocidad significa más fuerza.","h2":"A mayor velocidad, hay más fuerza en un choque, así que las lesiones son mucho más graves, además de necesitar más distancia para frenar.","p":"Correcto. Los choques son mucho más graves."},"zh":{"q":"开得更快时，除了刹车距离更长，还会发生什么？","o":["你的车抓地更好","你能看到更多的路","你的安全带效果更好","撞车时冲击力大得多，所以受伤更重"],"h1":"速度越快，力量越大。","h2":"速度越快，撞车时的力量就越大，所以受伤会严重得多，而且你也需要更长的距离才能停下。","p":"对。撞车会严重得多。"},"vi":{"q":"Ngoài quãng đường dừng xe dài hơn, còn điều gì xảy ra khi bạn lái nhanh hơn?","o":["Xe bám đường tốt hơn","Bạn nhìn thấy nhiều đoạn đường hơn","Dây an toàn hoạt động tốt hơn","Va chạm mạnh hơn nhiều, nên thương tích nặng hơn"],"h1":"Tốc độ càng cao thì lực càng lớn.","h2":"Tốc độ cao hơn nghĩa là lực trong va chạm lớn hơn, nên thương tích nghiêm trọng hơn nhiều, ngoài việc cần quãng đường dài hơn để dừng.","p":"Đúng. Tai nạn nghiêm trọng hơn nhiều."},"tl":{"q":"Bukod sa mas mahabang distansiya para huminto, ano pa ang nangyayari kapag mas mabilis kang magmaneho?","o":["Mas kumakapit sa daan ang kotse mo","Mas marami kang nakikita sa daan","Mas gumagana ang seat belt mo","Mas malakas ang tama ng banggaan, kaya mas malala ang pinsala sa katawan"],"h1":"Mas mabilis, mas malakas ang puwersa.","h2":"Mas mataas na bilis ay mas malakas na puwersa sa banggaan, kaya mas malala ang mga pinsala, bukod pa sa kailangan mo ng mas mahabang distansiya para huminto.","p":"Tama. Mas malala ang mga banggaan."},"ar":{"q":"إلى جانب مسافة التوقف الأطول، ماذا يحدث أيضًا عندما تقود بسرعة أكبر؟","o":["تتمسك سيارتك بالطريق بشكل أفضل","ترى جزءًا أكبر من الطريق","يعمل حزام الأمان بشكل أفضل","يكون الاصطدام أقوى بكثير، فتكون الإصابات أشد"],"h1":"سرعة أكبر تعني قوة أكبر.","h2":"السرعة الأعلى تعني قوة أكبر في الاصطدام، فتكون الإصابات أخطر بكثير، إلى جانب أنك تحتاج إلى مسافة أطول لتتوقف.","p":"صحيح. الحوادث تكون أشد بكثير."},"ht":{"q":"Anplis yon distans pi long pou kanpe, kisa ankò ki rive lè ou kondui pi vit?","o":["Machin ou kenbe wout la pi byen","Ou wè plis nan wout la","Senti sekirite ou travay pi byen","Yon aksidan frape pi fò anpil, kidonk blesi yo pi grav"],"h1":"Plis vitès vle di plis fòs.","h2":"Plis vitès vle di plis fòs nan yon aksidan, kidonk blesi yo pi grav anpil, anplis ou bezwen plis distans pou kanpe.","p":"Wi, se sa. Aksidan yo pi grav anpil."}},{"id":"speed-lanes-064","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"When can high beams help you see better?","o":["On dark roads with no other cars close ahead or coming toward you","In thick fog","In heavy snow","In city traffic"],"h1":"High beams can blind other drivers and reflect off fog.","h2":"High beams help on dark, open roads when no vehicle is close ahead or coming toward you; switch to low beams for other traffic and in fog or snow.","p":"Right. On dark roads with no cars nearby."},"es":{"q":"¿Cuándo le pueden ayudar las luces altas a ver mejor?","o":["En vías oscuras sin otros carros cerca adelante ni de frente","Con niebla espesa","Con nieve fuerte","En el tráfico de la ciudad"],"h1":"Las luces altas pueden encandilar y rebotan en la niebla.","h2":"Las luces altas ayudan en vías oscuras y abiertas cuando no hay vehículos cerca adelante ni de frente; use las bajas con otros carros y con niebla o nieve.","p":"Correcto. En vías oscuras sin carros cerca."},"zh":{"q":"什么时候远光灯能帮你看得更清楚？","o":["在黑暗的路上，前方近处和对面都没有车时","在浓雾中","在大雪中","在城市车流中"],"h1":"远光灯会晃到其他司机，也会被雾反射回来。","h2":"在黑暗、空旷的路上，前方近处和对面都没有车时，远光灯有帮助；有其他车时以及在雾或雪中，要换成近光灯。","p":"对。在附近没有车的黑暗道路上。"},"vi":{"q":"Khi nào đèn chiếu xa giúp bạn nhìn rõ hơn?","o":["Trên đường tối, không có xe nào ở gần phía trước hoặc đang chạy ngược về phía bạn","Trong sương mù dày","Trong tuyết rơi dày","Trong dòng xe ở thành phố"],"h1":"Đèn chiếu xa có thể làm chói mắt người lái khác và dội lại từ sương mù.","h2":"Đèn chiếu xa có ích trên đường tối, trống trải khi không có xe nào ở gần phía trước hoặc đang chạy ngược về phía bạn; hãy chuyển sang đèn cốt khi có xe khác và khi có sương mù hoặc tuyết.","p":"Đúng. Trên đường tối, không có xe ở gần."},"tl":{"q":"Kailan makakatulong ang high beams para mas makakita ka?","o":["Sa madilim na daan na walang ibang kotse na malapit sa unahan o paparating sa iyo","Sa makapal na fog","Sa malakas na snow","Sa trapiko sa lungsod"],"h1":"Puwedeng masilaw ng high beams ang ibang drayber at tumatalbog ito sa fog.","h2":"Nakakatulong ang high beams sa madilim at bukas na daan kapag walang sasakyang malapit sa unahan o paparating sa iyo; lumipat sa low beams kapag may ibang trapiko at sa fog o snow.","p":"Tama. Sa madilim na daan na walang kotseng malapit."},"ar":{"q":"متى يمكن أن تساعدك الأضواء العالية على الرؤية بشكل أفضل؟","o":["على الطرق المظلمة عندما لا توجد سيارات قريبة أمامك أو قادمة نحوك","في الضباب الكثيف","في الثلج الكثيف","في زحام المدينة"],"h1":"الأضواء العالية قد تُعمي السائقين الآخرين وترتد عن الضباب.","h2":"الأضواء العالية تساعد على الطرق المظلمة المفتوحة عندما لا توجد مركبة قريبة أمامك أو قادمة نحوك؛ انتقل إلى الأضواء المنخفضة عند وجود سيارات أخرى وفي الضباب أو الثلج.","p":"صحيح. على الطرق المظلمة دون سيارات قريبة."},"ht":{"q":"Kilè gwo limyè yo ka ede ou wè pi byen?","o":["Sou wout ki fè nwa, lè pa gen lòt machin toupre devan ou oswa k ap vin sou ou","Nan yon bwouya epè","Nan anpil nèj","Nan sikilasyon lavil"],"h1":"Gwo limyè yo ka avegle lòt chofè epi yo frape bwouya a.","h2":"Gwo limyè yo ede sou wout ki fè nwa e ki louvri, lè pa gen okenn machin toupre devan ou oswa k ap vin sou ou; pase sou ti limyè yo lè gen lòt machin, epi nan bwouya oswa nèj.","p":"Wi, se sa. Sou wout ki fè nwa san machin toupre."}},{"id":"speed-lanes-065","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"How should you back up a car safely?","o":["Use only the backup camera at normal speed","Turn and look back through the rear window, and go slowly","Look only in the side mirrors and go fast","Honk and back up without looking"],"h1":"Cameras and mirrors have blind spots.","h2":"To back up safely, turn your head to look through the rear window, check all around, and back up slowly.","p":"Right. Look back and go slowly."},"es":{"q":"¿Cómo debe retroceder con seguridad?","o":["Usando solo la cámara de reversa a velocidad normal","Girando para mirar por el vidrio trasero, y yendo despacio","Mirando solo los espejos laterales y yendo rápido","Tocando la bocina y retrocediendo sin mirar"],"h1":"Las cámaras y los espejos tienen puntos ciegos.","h2":"Para retroceder con seguridad, gire la cabeza para mirar por el vidrio trasero, revise todo alrededor y retroceda despacio.","p":"Correcto. Mire hacia atrás y vaya despacio."},"zh":{"q":"怎样安全地倒车？","o":["只用倒车影像，用正常速度倒车","转身从后窗往后看，并慢慢倒车","只看两侧后视镜，并快速倒车","按喇叭，不看就倒车"],"h1":"摄像头和后视镜都有盲区。","h2":"要安全地倒车，就转头从后窗往后看，检查四周，然后慢慢倒车。","p":"对。往后看，慢慢倒。"},"vi":{"q":"Bạn nên lùi xe thế nào cho an toàn?","o":["Chỉ dùng camera lùi và đi với tốc độ bình thường","Quay người nhìn ra sau qua kính sau, và đi chậm","Chỉ nhìn gương hai bên và đi nhanh","Bấm còi và lùi mà không nhìn"],"h1":"Camera và gương đều có điểm mù.","h2":"Để lùi xe an toàn, hãy quay đầu nhìn qua kính sau, kiểm tra xung quanh, và lùi thật chậm.","p":"Đúng. Nhìn ra sau và đi chậm."},"tl":{"q":"Paano ka dapat umatras nang ligtas?","o":["Gamitin lang ang backup camera sa karaniwang bilis","Lumingon at tumingin sa likurang bintana, at umatras nang dahan-dahan","Tumingin lang sa mga side mirror at umatras nang mabilis","Bumusina at umatras nang hindi tumitingin"],"h1":"May blind spot ang mga camera at salamin.","h2":"Para umatras nang ligtas, ilingon ang ulo mo para tumingin sa likurang bintana, tingnan ang buong paligid, at umatras nang dahan-dahan.","p":"Tama. Tumingin sa likod at magdahan-dahan."},"ar":{"q":"كيف ترجع بالسيارة إلى الخلف بأمان؟","o":["استعمل كاميرا الرجوع فقط وبسرعة عادية","استدر وانظر إلى الخلف من النافذة الخلفية، وتحرك ببطء","انظر في المرايا الجانبية فقط وتحرك بسرعة","استعمل البوق وارجع دون أن تنظر"],"h1":"الكاميرات والمرايا فيها نقاط عمياء.","h2":"لكي ترجع بأمان، أدر رأسك وانظر من النافذة الخلفية، وافحص كل ما حولك، وارجع ببطء.","p":"صحيح. انظر إلى الخلف وتحرك ببطء."},"ht":{"q":"Kijan ou ta dwe fè bak ak yon machin an sekirite?","o":["Sèvi sèlman ak kamera bak la nan vitès nòmal","Vire gade dèyè nan fenèt dèyè a, epi ale dousman","Gade sèlman nan retwovizè akote yo epi ale vit","Klaksonnen epi fè bak san gade"],"h1":"Kamera ak retwovizè gen kwen yo pa wè.","h2":"Pou fè bak an sekirite, vire tèt ou pou gade nan fenèt dèyè a, tcheke tout otou ou, epi fè bak dousman.","p":"Wi, se sa. Gade dèyè epi ale dousman."}},{"id":"speed-lanes-066","scope":"US","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"Why should you avoid changing lanes while you are in the middle of an intersection?","o":["Your signal will not work there","Intersections have no lanes","Other drivers do not expect it, and it can cause a crash","It makes the light change"],"h1":"Many things happen at once in an intersection.","h2":"Changing lanes inside an intersection surprises other drivers and people crossing, so pick your lane before the intersection.","p":"Right. Others do not expect it."},"es":{"q":"¿Por qué debe evitar cambiar de carril en medio de una intersección?","o":["Porque la direccional no funciona allí","Porque las intersecciones no tienen carriles","Porque los demás no lo esperan y puede causar un choque","Porque hace cambiar el semáforo"],"h1":"En una intersección pasan muchas cosas a la vez.","h2":"Cambiar de carril dentro de una intersección sorprende a otros conductores y a los peatones, así que escoja su carril antes de la intersección.","p":"Correcto. Los demás no lo esperan."},"zh":{"q":"为什么你应该避免在路口中间换车道？","o":["你的转向灯在那里不起作用","路口没有车道","其他司机想不到你会这样做，这可能造成撞车","这会让红绿灯变色"],"h1":"路口里同时发生很多事情。","h2":"在路口里换车道会让其他司机和过马路的人措手不及，所以要在进入路口之前选好车道。","p":"对。别人想不到你会这样做。"},"vi":{"q":"Tại sao bạn nên tránh chuyển làn khi đang ở giữa giao lộ?","o":["Xi nhan của bạn sẽ không hoạt động ở đó","Giao lộ không có làn","Người lái khác không ngờ tới, và điều đó có thể gây tai nạn","Nó làm đèn giao thông đổi màu"],"h1":"Nhiều việc xảy ra cùng lúc trong giao lộ.","h2":"Chuyển làn trong giao lộ làm người lái khác và người đi bộ qua đường bất ngờ, vì vậy hãy chọn làn trước khi vào giao lộ.","p":"Đúng. Người khác không ngờ tới."},"tl":{"q":"Bakit dapat mong iwasang lumipat ng lane habang nasa gitna ka ng interseksiyon?","o":["Hindi gagana roon ang signal mo","Walang mga lane sa interseksiyon","Hindi ito inaasahan ng ibang drayber, at maaari itong magdulot ng banggaan","Pinapalitan nito ang ilaw ng trapiko"],"h1":"Maraming nangyayari nang sabay-sabay sa interseksiyon.","h2":"Ang paglipat ng lane sa loob ng interseksiyon ay nakakagulat sa ibang drayber at sa mga taong tumatawid, kaya pumili ng lane bago ang interseksiyon.","p":"Tama. Hindi ito inaasahan ng iba."},"ar":{"q":"لماذا يجب أن تتجنب تغيير المسار وأنت في وسط التقاطع؟","o":["إشارتك لن تعمل هناك","التقاطعات ليس فيها مسارات","السائقون الآخرون لا يتوقعون ذلك، وقد يسبب حادثًا","هذا يجعل الإشارة الضوئية تتغير"],"h1":"أشياء كثيرة تحدث في وقت واحد داخل التقاطع.","h2":"تغيير المسار داخل التقاطع يفاجئ السائقين الآخرين والناس الذين يعبرون، لذلك اختر مسارك قبل التقاطع.","p":"صحيح. الآخرون لا يتوقعون ذلك."},"ht":{"q":"Poukisa ou ta dwe evite chanje liy pandan ou nan mitan yon entèseksyon?","o":["Siyal ou p ap mache la a","Entèseksyon pa gen liy","Lòt chofè pa atann sa, e sa ka lakòz yon aksidan","Sa fè limyè a chanje"],"h1":"Anpil bagay ap pase an menm tan nan yon entèseksyon.","h2":"Chanje liy anndan yon entèseksyon sezi lòt chofè ak moun k ap travèse, kidonk chwazi liy ou anvan entèseksyon an.","p":"Wi, se sa. Lòt moun pa atann sa."}},{"id":"speed-lanes-067","scope":"US","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"What is the \"space cushion\" around your car?","o":["A pillow for the driver","The air in your tires","The space in your trunk","Open space on all sides that gives you time and room to react"],"h1":"Think of space as a safety zone.","h2":"A space cushion is the open space you keep ahead, behind and beside your car, giving you time and room to avoid trouble.","p":"Right. Open space all around your car."},"es":{"q":"¿Qué es el \"colchón de espacio\" alrededor de su carro?","o":["Una almohada para el conductor","El aire de las llantas","El espacio del maletero","El espacio libre en todos los lados que le da tiempo y lugar para reaccionar"],"h1":"Piense en el espacio como una zona de seguridad.","h2":"El colchón de espacio es el espacio libre que mantiene adelante, atrás y a los lados de su carro, que le da tiempo y lugar para evitar problemas.","p":"Correcto. Espacio libre alrededor de su carro."},"zh":{"q":"你车子周围的“安全空间”（space cushion）是什么？","o":["给司机用的枕头","轮胎里的空气","后备箱里的空间","车子四周留出的空地，让你有时间和空间做出反应"],"h1":"把空间想成一个安全区。","h2":"安全空间是你在车前、车后和车两边留出的空地，让你有时间和空间避开危险。","p":"对。车子四周都要留出空地。"},"vi":{"q":"\"Khoảng đệm an toàn\" (space cushion) quanh xe của bạn là gì?","o":["Cái gối cho người lái","Không khí trong lốp xe","Chỗ trống trong cốp xe","Khoảng trống ở mọi phía, cho bạn thời gian và chỗ để phản ứng"],"h1":"Hãy nghĩ khoảng trống là một vùng an toàn.","h2":"Khoảng đệm an toàn là khoảng trống bạn giữ phía trước, phía sau và hai bên xe, để bạn có thời gian và chỗ tránh nguy hiểm.","p":"Đúng. Có khoảng trống ở mọi phía quanh xe."},"tl":{"q":"Ano ang \"space cushion\" sa paligid ng iyong sasakyan?","o":["Unan para sa drayber","Ang hangin sa iyong mga gulong","Ang espasyo sa iyong trunk","Bakanteng espasyo sa lahat ng panig na nagbibigay sa iyo ng oras at lugar para kumilos"],"h1":"Isipin ang espasyo bilang isang ligtas na lugar.","h2":"Ang space cushion ay ang bakanteng espasyo na iniiwan mo sa harap, likod at gilid ng iyong sasakyan, para may oras at lugar kang makaiwas sa panganib.","p":"Tama. Bakanteng espasyo sa buong paligid ng iyong sasakyan."},"ar":{"q":"ما هي \"المسافة الآمنة\" (space cushion) حول سيارتك؟","o":["وسادة للسائق","الهواء في إطارات السيارة","المساحة في صندوق السيارة","مساحة فارغة من كل الجهات تعطيك وقتًا ومكانًا لتتصرّف"],"h1":"فكّر في المساحة كمنطقة أمان.","h2":"المسافة الآمنة هي المساحة الفارغة التي تتركها أمام سيارتك وخلفها وعلى جانبيها، لتعطيك وقتًا ومكانًا لتتجنّب الخطر.","p":"صحيح. مساحة فارغة من كل الجهات حول سيارتك."},"ht":{"q":"Kisa \"espas sekirite\" (space cushion) ki bò machin ou an ye?","o":["Yon zòrye pou chofè a","Lè ki nan kawoutchou yo","Espas ki nan kòf machin nan","Espas vid sou tout kote ki ba ou tan ak plas pou reyaji"],"h1":"Panse ak espas la tankou yon zòn sekirite.","h2":"Espas sekirite a se espas vid ou kite devan, dèyè ak sou kote machin ou, pou ou gen tan ak plas pou evite danje.","p":"Wi, se sa. Espas vid tout otou machin ou."}},{"id":"speed-lanes-068","scope":"US","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You are driving on a two-lane road and a line of cars is stuck behind you because you are slow. What is a courteous, safe thing to do?","o":["Pull over where it is safe and let them pass","Speed up beyond what is safe","Brake to make them back off","Drive on the center line"],"h1":"A turnout or wide shoulder can help.","h2":"If several cars are stuck behind you, pull over at a safe place, like a turnout, and let them pass.","p":"Right. Pull over safely and let them pass."},"es":{"q":"Usted maneja por una vía de dos carriles y una fila de carros va detrás de usted porque va despacio. ¿Qué es lo cortés y seguro?","o":["Orillarse en un lugar seguro y dejarlos pasar","Acelerar más de lo seguro","Frenar para que se alejen","Manejar sobre la línea central"],"h1":"Un apartadero o un acotamiento ancho puede ayudar.","h2":"Si varios carros van atrapados detrás de usted, oríllese en un lugar seguro, como un apartadero, y déjelos pasar.","p":"Correcto. Oríllese con seguridad y déjelos pasar."},"zh":{"q":"你在双车道道路上开车，因为你开得慢，后面堵了一排车。礼貌又安全的做法是什么？","o":["在安全的地方靠边停，让他们先过","加速到超过安全的速度","踩刹车让他们退后","压着中线开"],"h1":"让车点（turnout）或宽的路肩可以帮上忙。","h2":"如果后面堵了好几辆车，就在安全的地方（比如让车点）靠边停，让他们先过。","p":"对。安全地靠边停，让他们先过。"},"vi":{"q":"Bạn đang lái trên đường hai làn và có một hàng xe bị kẹt phía sau vì bạn chạy chậm. Việc lịch sự và an toàn nên làm là gì?","o":["Tấp vào chỗ an toàn và để họ vượt qua","Tăng tốc quá mức an toàn","Đạp phanh để họ lùi lại","Chạy trên vạch giữa đường"],"h1":"Chỗ tránh xe (turnout) hoặc lề đường rộng có thể giúp ích.","h2":"Nếu có nhiều xe bị kẹt phía sau bạn, hãy tấp vào một chỗ an toàn, như chỗ tránh xe, và để họ vượt qua.","p":"Đúng. Tấp vào an toàn và để họ vượt qua."},"tl":{"q":"Nagmamaneho ka sa kalsadang may dalawang lane at may hanay ng mga sasakyang naipit sa likod mo dahil mabagal ka. Ano ang magalang at ligtas na gawin?","o":["Tumabi sa ligtas na lugar at paunahin sila","Bumilis nang lampas sa ligtas","Magpreno para umatras sila","Magmaneho sa gitnang guhit"],"h1":"Makatutulong ang turnout o malapad na gilid ng kalsada.","h2":"Kung maraming sasakyan ang naipit sa likod mo, tumabi sa ligtas na lugar, tulad ng turnout, at paunahin sila.","p":"Tama. Tumabi nang ligtas at paunahin sila."},"ar":{"q":"أنت تقود على طريق من مسارين، وهناك صف من السيارات عالق خلفك لأنك بطيء. ما التصرّف المهذّب والآمن؟","o":["توقّف على جانب الطريق في مكان آمن ودعهم يتجاوزونك","زِد سرعتك أكثر مما هو آمن","اضغط على الفرامل ليبتعدوا عنك","قُد على الخط الأوسط"],"h1":"مكان جانبي للتوقّف (turnout) أو كتف طريق عريض يمكن أن يساعد.","h2":"إذا كانت عدة سيارات عالقة خلفك، فتوقّف على جانب الطريق في مكان آمن، مثل مكان جانبي للتوقّف، ودعها تتجاوزك.","p":"صحيح. توقّف جانبًا بأمان ودعهم يتجاوزونك."},"ht":{"q":"W ap kondui sou yon wout ki gen de liy, epi yon ran machin bloke dèyè ou paske w ap mache dousman. Kisa ki yon bagay janti e san danje pou fè?","o":["Rale sou kote kote li an sekirite epi kite yo pase","Akselere plis pase sa ki an sekirite","Frennen pou fè yo rale dèyè","Kondui sou liy nan mitan an"],"h1":"Yon kote pou rale (turnout) oswa yon bò wout ki laj ka ede.","h2":"Si plizyè machin bloke dèyè ou, rale sou kote nan yon plas ki an sekirite, tankou yon kote pou rale, epi kite yo pase.","p":"Wi, se sa. Rale sou kote san danje epi kite yo pase."}},{"id":"speed-lanes-069","scope":"US","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"It is getting dark and the road is unfamiliar. How should you choose your speed?","o":["Always at the speed limit","Slow enough to stop within the distance you can see","Faster, to get there before dark","The same as the car ahead, no matter what"],"h1":"You can only react to what you can see.","h2":"Choose a speed that lets you stop within the distance you can clearly see, which is often slower than the limit at night or on an unfamiliar road.","p":"Right. Stop within the distance you can see."},"es":{"q":"Está oscureciendo y no conoce la vía. ¿Cómo debe escoger su velocidad?","o":["Siempre al límite de velocidad","Lo bastante despacio para pararse dentro de la distancia que ve","Más rápido, para llegar antes de que oscurezca","Igual que el carro de adelante, pase lo que pase"],"h1":"Solo puede reaccionar a lo que ve.","h2":"Escoja una velocidad que le permita pararse dentro de la distancia que ve con claridad, lo que muchas veces es menos que el límite de noche o en una vía desconocida.","p":"Correcto. Párese dentro de la distancia que ve."},"zh":{"q":"天快黑了，而且这条路你不熟。你应该怎样选择车速？","o":["永远按限速开","慢到能在你看得见的距离内停下来","开快一点，赶在天黑前到","不管怎样，都跟前面的车一样快"],"h1":"你只能对看得见的东西做出反应。","h2":"选择一个能让你在看得清的距离内停下来的速度；在晚上或不熟的路上，这常常比限速还慢。","p":"对。要能在看得见的距离内停下来。"},"vi":{"q":"Trời đang tối dần và con đường lạ với bạn. Bạn nên chọn tốc độ như thế nào?","o":["Luôn chạy đúng tốc độ giới hạn","Đủ chậm để dừng lại trong khoảng cách bạn nhìn thấy","Nhanh hơn, để đến nơi trước khi trời tối","Bằng xe phía trước, dù thế nào đi nữa"],"h1":"Bạn chỉ có thể phản ứng với những gì bạn nhìn thấy.","h2":"Hãy chọn tốc độ cho phép bạn dừng lại trong khoảng cách bạn nhìn thấy rõ, thường là chậm hơn giới hạn vào ban đêm hoặc trên đường lạ.","p":"Đúng. Dừng lại được trong khoảng cách bạn nhìn thấy."},"tl":{"q":"Dumidilim na at hindi mo kabisado ang kalsada. Paano mo dapat piliin ang iyong bilis?","o":["Laging nasa speed limit","Sapat na mabagal para makahinto sa layong nakikita mo","Mas mabilis, para makarating bago dumilim","Kapareho ng sasakyan sa harap, anuman ang mangyari"],"h1":"Makakakilos ka lang sa nakikita mo.","h2":"Pumili ng bilis na nagpapahintulot sa iyong huminto sa layong malinaw mong nakikita, na kadalasan ay mas mabagal sa limit sa gabi o sa hindi kabisadong kalsada.","p":"Tama. Huminto sa layong nakikita mo."},"ar":{"q":"بدأ الظلام، والطريق غير مألوف لك. كيف تختار سرعتك؟","o":["دائمًا بحد السرعة","بطيئة بما يكفي لتتوقّف ضمن المسافة التي تراها","أسرع، لتصل قبل الظلام","مثل السيارة التي أمامك، مهما حدث"],"h1":"لا يمكنك أن تتصرّف إلا تجاه ما تراه.","h2":"اختر سرعة تسمح لك بالتوقّف ضمن المسافة التي تراها بوضوح، وهي غالبًا أبطأ من حد السرعة في الليل أو على طريق غير مألوف.","p":"صحيح. توقّف ضمن المسافة التي تراها."},"ht":{"q":"Li kòmanse fè nwa epi ou pa konnen wout la. Kijan ou dwe chwazi vitès ou?","o":["Toujou nan limit vitès la","Ase dousman pou kanpe nan distans ou ka wè a","Pi vit, pou rive anvan nwa","Menm jan ak machin devan an, kèlkeswa sa ki rive"],"h1":"Ou ka reyaji sèlman ak sa ou wè.","h2":"Chwazi yon vitès ki pèmèt ou kanpe nan distans ou wè byen klè a, e souvan li pi dousman pase limit la lannwit oswa sou yon wout ou pa konnen.","p":"Wi, se sa. Kanpe nan distans ou ka wè a."}},{"id":"speed-lanes-070","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, a fire truck is going to an emergency ahead of you. How close may you follow it?","o":["As close as 50 feet","As close as 100 feet","As close as 300 feet","No closer than 500 feet"],"h1":"It is about the length of a city block or more.","h2":"Florida law forbids following a fire truck on its way to an emergency closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck going to an emergency."},"es":{"q":"En Florida, un camión de bomberos va hacia una emergencia delante de usted. ¿Qué tan cerca lo puede seguir?","o":["Hasta a 50 pies","Hasta a 100 pies","Hasta a 300 pies","No más cerca de 500 pies"],"h1":"Es como el largo de una cuadra o más.","h2":"La ley de Florida prohíbe seguir a menos de 500 pies a un camión de bomberos que va a una emergencia.","p":"Correcto. Manténgase al menos a 500 pies detrás de un camión de bomberos que va a una emergencia."},"ref":{"doc":"FL","page":62}},{"id":"speed-lanes-071","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, what does the law require before you walk away from your parked car?","o":["Leave the windows down","Leave the engine running","Take the key out","Turn on the hazard lights"],"h1":"It helps stop car theft.","h2":"Florida law requires you to stop the engine and take the key out before you leave your vehicle.","p":"Right. Engine off and key out before you leave the car."},"es":{"q":"En Florida, ¿qué exige la ley antes de alejarse de su carro estacionado?","o":["Dejar las ventanas abajo","Dejar el motor encendido","Sacar la llave","Encender las luces intermitentes"],"h1":"Ayuda a evitar el robo de carros.","h2":"La ley de Florida exige apagar el motor y sacar la llave antes de dejar su vehículo.","p":"Correcto. Motor apagado y llave afuera antes de dejar el carro."},"ref":{"doc":"FL","page":65}},{"id":"speed-lanes-072","scope":"FL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Florida, how close to the driveway entrance of a fire station may you park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In Florida, you may not park within 20 feet of the entrance to a fire, ambulance, or rescue station.","p":"Right. Keep 20 feet from a fire station entrance."},"es":{"q":"En Florida, ¿qué tan cerca de la entrada de una estación de bomberos puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 20 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Es la misma distancia que de un cruce peatonal en una intersección.","h2":"En Florida, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos, ambulancias o rescate.","p":"Correcto. Manténgase a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"FL","page":66}},{"id":"speed-lanes-073","scope":"FL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Florida, you are passing on a two-lane road. A car is coming toward you. You must be back in your lane before you get within how many feet of it?","o":["200 feet","50 feet","20 feet","1,000 feet"],"h1":"It is less than the length of a football field.","h2":"When you pass, you must return to the right side of the road before you come within 200 feet of any oncoming vehicle.","p":"Right. Be back in your lane before you are within 200 feet of oncoming traffic."},"es":{"q":"En Florida, usted está rebasando en una carretera de dos carriles. Viene un carro de frente. ¿Antes de llegar a cuántos pies de él debe volver a su carril?","o":["200 pies","50 pies","20 pies","1,000 pies"],"h1":"Es menos que el largo de un campo de fútbol americano.","h2":"Al rebasar, debe volver al lado derecho de la carretera antes de llegar a 200 pies de cualquier vehículo que viene de frente.","p":"Correcto. Vuelva a su carril antes de estar a 200 pies del tráfico de frente."},"ref":{"doc":"FL","page":67}},{"id":"speed-lanes-074","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, what is the standard speed limit in a school zone?","o":["10 mph","15 mph","25 mph","20 mph"],"h1":"It is lower than the 30 mph limit for city streets.","h2":"The standard speed limit in a Florida school zone is 20 mph.","p":"Right. School zones are usually 20 mph."},"es":{"q":"En Florida, ¿cuál es el límite de velocidad normal en una zona escolar?","o":["10 mph","15 mph","25 mph","20 mph"],"h1":"Es más bajo que el límite de 30 mph de las calles de la ciudad.","h2":"El límite de velocidad normal en una zona escolar de Florida es de 20 mph.","p":"Correcto. Las zonas escolares normalmente son de 20 mph."},"ref":{"doc":"FL","page":68}},{"id":"speed-lanes-075","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, on which streets may a low-speed vehicle (LSV) be driven?","o":["Any street, including interstates","Only on sidewalks","Streets with a speed limit of 35 mph or less","Streets with a speed limit of 55 mph or less"],"h1":"These vehicles go only about 25 mph.","h2":"A low-speed vehicle may be driven only on streets with a posted speed limit of 35 mph or less, by a driver with a valid license.","p":"Right. LSVs stay on streets posted at 35 mph or less."},"es":{"q":"En Florida, ¿por qué calles se puede manejar un vehículo de baja velocidad (LSV)?","o":["Cualquier calle, incluso interestatales","Solo por las aceras","Calles con límite de 35 mph o menos","Calles con límite de 55 mph o menos"],"h1":"Estos vehículos solo van a unas 25 mph.","h2":"Un vehículo de baja velocidad solo se puede manejar en calles con un límite de velocidad de 35 mph o menos, y el conductor debe tener licencia válida.","p":"Correcto. Los LSV van solo por calles con límite de 35 mph o menos."},"ref":{"doc":"FL","page":85}},{"id":"speed-lanes-076","scope":"FL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Florida, outside a city or town, how close may a truck follow another truck, unless it is passing?","o":["No closer than 100 feet","No closer than 200 feet","No closer than 300 feet","No closer than 500 feet"],"h1":"It is the length of a football field.","h2":"In Florida, outside cities and towns, a truck or a vehicle towing another vehicle may not follow within 300 feet of another truck or towing vehicle, except when passing.","p":"Right. Trucks must stay at least 300 feet apart outside cities."},"es":{"q":"En Florida, fuera de una ciudad o pueblo, ¿qué tan cerca puede un camión seguir a otro camión, a menos que lo esté rebasando?","o":["No más cerca de 100 pies","No más cerca de 200 pies","No más cerca de 300 pies","No más cerca de 500 pies"],"h1":"Es el largo de un campo de fútbol americano.","h2":"En Florida, fuera de las ciudades y pueblos, un camión o un vehículo que remolca a otro no puede seguir a menos de 300 pies a otro camión o vehículo con remolque, excepto al rebasar.","p":"Correcto. Los camiones deben ir al menos a 300 pies de distancia fuera de las ciudades."},"ref":{"doc":"FL","page":62}},{"id":"speed-lanes-077","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, which of these may NOT be driven on a limited access highway, such as an interstate?","o":["A pickup truck","A car pulling a small trailer","A full-size motorcycle","A motor scooter of 150 cc or less"],"h1":"Think of the smallest, slowest motor vehicle in the list.","h2":"In Florida, motor scooters and motor-driven cycles of 150 cc or less are not allowed on limited access highways.","p":"Right. Scooters of 150 cc or less may not use limited access highways."},"es":{"q":"En Florida, ¿cuál de estos NO puede manejarse en una autopista de acceso limitado, como una interestatal?","o":["Una camioneta pickup","Un carro que remolca un remolque pequeño","Una motocicleta de tamaño normal","Una motoneta de 150 cc o menos"],"h1":"Piense en el vehículo de motor más pequeño y lento de la lista.","h2":"En Florida, las motonetas y motocicletas de 150 cc o menos no se permiten en las autopistas de acceso limitado.","p":"Correcto. Las motonetas de 150 cc o menos no pueden usar las autopistas de acceso limitado."},"ref":{"doc":"FL","page":63}},{"id":"speed-lanes-078","scope":"FL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Florida, may you use your turn signal to tell the driver behind you that it is safe to pass?","o":["Yes, that is what it is for","Yes, but only on two-lane roads","Yes, but only at night","No, that is against the law"],"h1":"A turn signal should only tell others what you are about to do.","h2":"In Florida, it is against the law to use your turn signals to tell drivers behind you that they can pass.","p":"Right. Turn signals are not for waving others past."},"es":{"q":"En Florida, ¿puede usar su direccional para decirle al conductor de atrás que es seguro rebasar?","o":["Sí, para eso sirve","Sí, pero solo en caminos de dos carriles","Sí, pero solo de noche","No, eso va contra la ley"],"h1":"La direccional solo debe decir a los demás lo que usted va a hacer.","h2":"En Florida, es ilegal usar las direccionales para decirles a los conductores de atrás que pueden rebasar.","p":"Correcto. Las direccionales no sirven para indicar a otros que pasen."},"ref":{"doc":"FL","page":69}},{"id":"ak-001","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is two years before the age for a provisional license.","h2":"In Alaska you can get an instruction permit when you turn 14, so you have time to practice before you can drive alone.","p":"Right. Alaska gives instruction permits starting at age 14."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Es dos años antes de la edad para la licencia provisional.","h2":"En Alaska usted puede obtener el permiso de instrucción al cumplir 14 años, para tener tiempo de practicar antes de manejar solo.","p":"Correcto. Alaska da permisos de instrucción desde los 14 años."},"zh":{"q":"在 Alaska，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比过渡驾照的年龄早两年。","h2":"在 Alaska，你满 14 岁就可以拿到学习驾照，这样你在可以单独开车前有时间练习。","p":"对。Alaska 从 14 岁开始发学习驾照。"},"vi":{"q":"Ở Alaska, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Đó là hai năm trước tuổi được cấp bằng lái tạm thời.","h2":"Ở Alaska, bạn có thể được cấp giấy phép tập lái khi đủ 14 tuổi, để bạn có thời gian tập trước khi được lái xe một mình.","p":"Đúng. Alaska cấp giấy phép tập lái từ 14 tuổi."},"tl":{"q":"Sa Alaska, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Ito ay dalawang taon bago ang edad para sa provisional license.","h2":"Sa Alaska, puwede kang kumuha ng instruction permit pagsapit mo ng 14, para may oras kang magsanay bago ka makapagmaneho nang mag-isa.","p":"Tama. Nagbibigay ang Alaska ng instruction permit simula sa edad na 14."},"ar":{"q":"في Alaska، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل سن الرخصة المؤقتة بسنتين.","h2":"في Alaska يمكنك الحصول على تصريح التعلّم عندما تبلغ 14 سنة، حتى يكون لديك وقت للتدرّب قبل أن تقود وحدك.","p":"صحيح. تمنح Alaska تصاريح التعلّم ابتداءً من سن 14."},"ref":{"doc":"AK","page":4}},{"id":"ak-002","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver with an instruction permit must have a licensed driver with them. How old must that driver be?","o":["At least 18 years old","At least 25 years old","At least 16 years old","At least 21 years old"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"The person supervising you must be a licensed driver who is at least 21 years old, so that an experienced adult is beside you.","p":"Right. Your supervising driver must be 21 or older."},"es":{"q":"En Alaska, quien tiene permiso de instrucción debe ir con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 18 años","Por lo menos 25 años","Por lo menos 16 años","Por lo menos 21 años"],"h1":"El acompañante debe tener la edad legal para tomar alcohol.","h2":"La persona que lo supervisa debe ser un conductor con licencia de por lo menos 21 años, para que un adulto con experiencia vaya a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Alaska，持学习驾照的司机必须有一位有驾照的司机陪同。这位司机必须几岁？","o":["至少 18 岁","至少 25 岁","至少 16 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"监督你的人必须是至少 21 岁、有驾照的司机，这样你旁边就有一位有经验的成年人。","p":"对。监督你的司机必须是 21 岁或以上。"},"vi":{"q":"Ở Alaska, người lái xe có giấy phép tập lái phải có một người có bằng lái đi cùng. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 16 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi kèm phải đủ tuổi để uống rượu hợp pháp.","h2":"Người giám sát bạn phải là người có bằng lái và ít nhất 21 tuổi, để luôn có một người lớn có kinh nghiệm ngồi bên cạnh bạn.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Alaska, ang driver na may instruction permit ay dapat may kasamang lisensiyadong driver. Ilang taon dapat ang driver na iyon?","o":["Hindi bababa sa 18 taong gulang","Hindi bababa sa 25 taong gulang","Hindi bababa sa 16 taong gulang","Hindi bababa sa 21 taong gulang"],"h1":"Ang kasama ay dapat nasa edad na puwede nang uminom ng alak ayon sa batas.","h2":"Ang taong nagbabantay sa iyo ay dapat lisensiyadong driver na hindi bababa sa 21 taong gulang, para may karanasang adult sa tabi mo.","p":"Tama. Ang nagbabantay na driver ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Alaska، يجب أن يكون مع السائق الذي يحمل تصريح التعلّم سائق مرخَّص. كم يجب أن يكون عمر هذا السائق؟","o":["18 سنة على الأقل","25 سنة على الأقل","16 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في سن يسمح له قانونيًا بشرب الكحول.","h2":"يجب أن يكون الشخص الذي يشرف عليك سائقًا مرخَّصًا عمره 21 سنة على الأقل، حتى يكون بجانبك شخص بالغ لديه خبرة.","p":"صحيح. يجب أن يكون السائق المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"AK","page":4}},{"id":"ak-003","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how much driving experience must the supervising driver of a permit holder have?","o":["No experience is required","At least three months","At least one year in that kind of vehicle","At least five years in any vehicle"],"h1":"It is counted in years, and the type of vehicle matters.","h2":"The supervising driver needs at least one year of driving experience in the same kind of vehicle you are driving, so they know how to guide you.","p":"Right. The supervisor needs at least one year of experience in that kind of vehicle."},"es":{"q":"En Alaska, ¿cuánta experiencia debe tener el conductor que supervisa a quien tiene permiso?","o":["No se requiere experiencia","Por lo menos tres meses","Por lo menos un año en ese tipo de vehículo","Por lo menos cinco años en cualquier vehículo"],"h1":"Se cuenta en años, y el tipo de vehículo importa.","h2":"El conductor que lo supervisa necesita por lo menos un año de experiencia manejando el mismo tipo de vehículo que usted maneja, para saber cómo guiarlo.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia en ese tipo de vehículo."},"zh":{"q":"在 Alaska，监督持学习驾照的人开车的司机，必须有多少驾驶经验？","o":["不需要经验","至少三个月","开这种车至少一年","开任何车至少五年"],"h1":"它是按年算的，而且车的种类很重要。","h2":"监督的司机开你正在开的这种车，至少要有一年的驾驶经验，这样才知道怎样指导你。","p":"对。监督的人开这种车至少要有一年经验。"},"vi":{"q":"Ở Alaska, người giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Không cần kinh nghiệm","Ít nhất ba tháng","Ít nhất một năm với loại xe đó","Ít nhất năm năm với bất kỳ loại xe nào"],"h1":"Kinh nghiệm được tính bằng năm, và loại xe là quan trọng.","h2":"Người giám sát cần ít nhất một năm kinh nghiệm lái cùng loại xe mà bạn đang lái, để họ biết cách hướng dẫn bạn.","p":"Đúng. Người giám sát cần ít nhất một năm kinh nghiệm với loại xe đó."},"tl":{"q":"Sa Alaska, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang nagbabantay na driver ng may permit?","o":["Walang kailangang karanasan","Hindi bababa sa tatlong buwan","Hindi bababa sa isang taon sa ganoong uri ng sasakyan","Hindi bababa sa limang taon sa kahit anong sasakyan"],"h1":"Binibilang ito sa taon, at mahalaga ang uri ng sasakyan.","h2":"Ang nagbabantay na driver ay kailangang may hindi bababa sa isang taong karanasan sa pagmamaneho ng parehong uri ng sasakyan na minamaneho mo, para alam niya kung paano ka gagabayan.","p":"Tama. Kailangan ng nagbabantay ng hindi bababa sa isang taong karanasan sa ganoong uri ng sasakyan."},"ar":{"q":"في Alaska، كم يجب أن تكون خبرة القيادة لدى السائق المشرف على حامل التصريح؟","o":["لا تُطلب أي خبرة","ثلاثة أشهر على الأقل","سنة واحدة على الأقل في هذا النوع من المركبات","خمس سنوات على الأقل في أي مركبة"],"h1":"تُحسب بالسنوات، ونوع المركبة مهم.","h2":"يحتاج السائق المشرف إلى سنة واحدة على الأقل من الخبرة في قيادة نفس نوع المركبة التي تقودها، حتى يعرف كيف يرشدك.","p":"صحيح. يحتاج المشرف إلى سنة واحدة على الأقل من الخبرة في هذا النوع من المركبات."},"ref":{"doc":"AK","page":4}},{"id":"ak-004","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In any back seat","Anywhere in the vehicle","In the seat behind the driver"],"h1":"They must be able to reach you and see the road as you do.","h2":"The supervising driver must sit in the front passenger seat the whole time, so they can watch the road and help you right away.","p":"Right. The supervisor always sits in the front passenger seat."},"es":{"q":"En Alaska, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero de adelante","En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento detrás del conductor"],"h1":"Debe poder alcanzarlo a usted y ver el camino como usted.","h2":"El conductor supervisor debe ir todo el tiempo en el asiento del pasajero de adelante, para mirar el camino y ayudarle enseguida.","p":"Correcto. El supervisor siempre va en el asiento del pasajero de adelante."},"zh":{"q":"在 Alaska，持学习驾照的人开车时，监督的司机必须坐在哪里？","o":["前排乘客座位","任何后排座位","车里任何地方","司机后面的座位"],"h1":"他必须能碰到你，并且和你一样看到道路。","h2":"监督的司机必须一直坐在前排乘客座位，这样才能看着道路并马上帮你。","p":"对。监督的人一直坐在前排乘客座位。"},"vi":{"q":"Ở Alaska, khi người có giấy phép tập lái đang lái xe, người giám sát phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Ở ghế ngay sau người lái"],"h1":"Họ phải với tới bạn được và nhìn thấy đường giống như bạn.","h2":"Người giám sát phải ngồi ở ghế hành khách phía trước suốt thời gian lái, để họ nhìn đường và giúp bạn ngay lập tức.","p":"Đúng. Người giám sát luôn ngồi ở ghế hành khách phía trước."},"tl":{"q":"Sa Alaska, saan dapat umupo ang nagbabantay na driver habang nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa kahit anong upuan sa likod","Kahit saan sa loob ng sasakyan","Sa upuan sa likod ng driver"],"h1":"Dapat maabot ka niya at makita niya ang daan gaya mo.","h2":"Ang nagbabantay na driver ay dapat nakaupo sa upuan ng pasahero sa harap sa buong oras, para mabantayan niya ang daan at matulungan ka agad.","p":"Tama. Laging nakaupo ang nagbabantay sa upuan ng pasahero sa harap."},"ar":{"q":"في Alaska، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في مقعد الراكب الأمامي","في أي مقعد خلفي","في أي مكان داخل المركبة","في المقعد خلف السائق"],"h1":"يجب أن يستطيع الوصول إليك وأن يرى الطريق كما تراه.","h2":"يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي طوال الوقت، حتى يراقب الطريق ويساعدك فورًا.","p":"صحيح. يجلس المشرف دائمًا في مقعد الراكب الأمامي."},"ref":{"doc":"AK","page":4}},{"id":"ak-005","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how long is an instruction permit valid?","o":["Six months, with no renewal","One year, renewable many times","Two years, renewable one time","Five years, with no renewal"],"h1":"It lasts a little longer than one year, and you get one more chance.","h2":"An Alaska instruction permit is good for two years, and you may renew it one time if you need more practice.","p":"Right. The permit lasts two years and can be renewed once."},"es":{"q":"En Alaska, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses, sin renovación","Un año, renovable muchas veces","Dos años, renovable una vez","Cinco años, sin renovación"],"h1":"Dura un poco más de un año, y usted tiene una oportunidad más.","h2":"El permiso de instrucción de Alaska es válido por dos años, y usted puede renovarlo una vez si necesita más práctica.","p":"Correcto. El permiso dura dos años y se puede renovar una vez."},"zh":{"q":"在 Alaska，学习驾照的有效期是多久？","o":["六个月，不能延期","一年，可以延期很多次","两年，可以延期一次","五年，不能延期"],"h1":"它比一年长一些，而且你还有一次机会。","h2":"Alaska 的学习驾照有效期是两年，如果你需要更多练习，可以延期一次。","p":"对。学习驾照有效两年，可以延期一次。"},"vi":{"q":"Ở Alaska, giấy phép tập lái có giá trị trong bao lâu?","o":["Sáu tháng, không được gia hạn","Một năm, được gia hạn nhiều lần","Hai năm, được gia hạn một lần","Năm năm, không được gia hạn"],"h1":"Nó lâu hơn một năm một chút, và bạn có thêm một cơ hội nữa.","h2":"Giấy phép tập lái ở Alaska có giá trị hai năm, và bạn có thể gia hạn một lần nếu cần tập thêm.","p":"Đúng. Giấy phép có giá trị hai năm và được gia hạn một lần."},"tl":{"q":"Sa Alaska, gaano katagal may bisa ang instruction permit?","o":["Anim na buwan, walang renewal","Isang taon, puwedeng i-renew nang maraming beses","Dalawang taon, puwedeng i-renew nang isang beses","Limang taon, walang renewal"],"h1":"Medyo mas mahaba ito kaysa isang taon, at may isa ka pang pagkakataon.","h2":"Ang instruction permit sa Alaska ay may bisa nang dalawang taon, at puwede mo itong i-renew nang isang beses kung kailangan mo pa ng pagsasanay.","p":"Tama. Dalawang taon ang bisa ng permit at puwedeng i-renew nang isang beses."},"ar":{"q":"في Alaska، ما مدة صلاحية تصريح التعلّم؟","o":["ستة أشهر، بدون تجديد","سنة واحدة، يمكن تجديدها مرات كثيرة","سنتان، يمكن تجديدها مرة واحدة","خمس سنوات، بدون تجديد"],"h1":"المدة أطول قليلًا من سنة، ولديك فرصة أخرى واحدة.","h2":"تصريح التعلّم في Alaska صالح لمدة سنتين، ويمكنك تجديده مرة واحدة إذا احتجت إلى مزيد من التدرّب.","p":"صحيح. التصريح صالح لسنتين ويمكن تجديده مرة واحدة."},"ref":{"doc":"AK","page":4}},{"id":"ak-006","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what must a teen under 18 bring to apply for an instruction permit?","o":["A letter from a teacher","A consent form signed by a parent or guardian","A completed driving school course","Proof of a part-time job"],"h1":"An adult who is responsible for you has to agree.","h2":"A teen under 18 needs a consent form signed by a parent or guardian, because that adult agrees to take responsibility for the new driver.","p":"Right. A parent or guardian must sign a consent form."},"es":{"q":"En Alaska, ¿qué debe llevar un joven menor de 18 años para solicitar el permiso de instrucción?","o":["Una carta de un maestro","Un formulario de consentimiento firmado por su padre, madre o tutor","Un curso de manejo terminado","Prueba de un trabajo de medio tiempo"],"h1":"Un adulto responsable de usted tiene que estar de acuerdo.","h2":"Un joven menor de 18 años necesita un formulario de consentimiento firmado por su padre, madre o tutor, porque ese adulto acepta la responsabilidad del nuevo conductor.","p":"Correcto. Su padre, madre o tutor debe firmar un formulario de consentimiento."},"zh":{"q":"在 Alaska，18 岁以下的青少年申请学习驾照时必须带什么？","o":["老师写的信","父母或监护人签字的同意书","已完成的驾校课程","兼职工作的证明"],"h1":"一位对你负责的成年人必须同意。","h2":"18 岁以下的青少年需要一份父母或监护人签字的同意书，因为这个成年人同意为这位新司机负责。","p":"对。父母或监护人必须签同意书。"},"vi":{"q":"Ở Alaska, thiếu niên dưới 18 tuổi phải mang theo gì khi xin giấy phép tập lái?","o":["Một lá thư của giáo viên","Một mẫu đồng ý có chữ ký của cha mẹ hoặc người giám hộ","Chứng nhận đã học xong trường dạy lái xe","Giấy tờ chứng minh có việc làm bán thời gian"],"h1":"Một người lớn chịu trách nhiệm về bạn phải đồng ý.","h2":"Thiếu niên dưới 18 tuổi cần một mẫu đồng ý có chữ ký của cha mẹ hoặc người giám hộ, vì người lớn đó đồng ý chịu trách nhiệm cho người lái mới.","p":"Đúng. Cha mẹ hoặc người giám hộ phải ký mẫu đồng ý."},"tl":{"q":"Sa Alaska, ano ang dapat dalhin ng kabataang wala pang 18 taong gulang para mag-apply ng instruction permit?","o":["Sulat mula sa guro","Consent form na pinirmahan ng magulang o guardian","Natapos na kurso sa driving school","Patunay ng part-time na trabaho"],"h1":"Kailangang pumayag ang isang adult na responsable sa iyo.","h2":"Ang kabataang wala pang 18 ay kailangan ng consent form na pinirmahan ng magulang o guardian, dahil pumapayag ang adult na iyon na managot para sa bagong driver.","p":"Tama. Dapat pumirma ang magulang o guardian sa consent form."},"ar":{"q":"في Alaska، ماذا يجب أن يُحضر المراهق الذي عمره أقل من 18 سنة ليطلب تصريح التعلّم؟","o":["رسالة من معلّم","نموذج موافقة موقَّع من أحد الوالدين أو الوصي","شهادة إتمام دورة في مدرسة لتعليم القيادة","إثبات عمل بدوام جزئي"],"h1":"يجب أن يوافق شخص بالغ مسؤول عنك.","h2":"يحتاج المراهق الذي عمره أقل من 18 سنة إلى نموذج موافقة موقَّع من أحد الوالدين أو الوصي، لأن هذا الشخص البالغ يوافق على تحمّل المسؤولية عن السائق الجديد.","p":"صحيح. يجب أن يوقّع أحد الوالدين أو الوصي على نموذج الموافقة."},"ref":{"doc":"AK","page":3}},{"id":"ak-007","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, how long must a teen hold an instruction permit before getting a provisional license?","o":["One month","Three months","One year","Six months"],"h1":"It is half of a year.","h2":"A teen must hold the instruction permit for at least six months before getting a provisional license, so there is enough time to practice.","p":"Right. You must hold the permit for at least six months."},"es":{"q":"En Alaska, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de obtener la licencia provisional?","o":["Un mes","Tres meses","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"Un joven debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional, para tener tiempo suficiente de practicar.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"zh":{"q":"在 Alaska，青少年必须持有学习驾照多久，才能拿到过渡驾照？","o":["一个月","三个月","一年","六个月"],"h1":"它是半年。","h2":"青少年必须持有学习驾照至少六个月，才能拿到过渡驾照，这样才有足够的时间练习。","p":"对。你必须持有学习驾照至少六个月。"},"vi":{"q":"Ở Alaska, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái tạm thời (provisional license)?","o":["Một tháng","Ba tháng","Một năm","Sáu tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên phải giữ giấy phép tập lái ít nhất sáu tháng trước khi được cấp bằng lái tạm thời, để có đủ thời gian tập lái.","p":"Đúng. Bạn phải giữ giấy phép tập lái ít nhất sáu tháng."},"tl":{"q":"Sa Alaska, gaano katagal dapat hawak ng kabataan ang instruction permit bago makakuha ng provisional license?","o":["Isang buwan","Tatlong buwan","Isang taon","Anim na buwan"],"h1":"Ito ay kalahating taon.","h2":"Dapat hawak ng kabataan ang instruction permit nang hindi bababa sa anim na buwan bago makakuha ng provisional license, para may sapat na oras sa pagsasanay.","p":"Tama. Dapat mong hawak ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Alaska، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["شهر واحد","ثلاثة أشهر","سنة واحدة","ستة أشهر"],"h1":"إنها نصف سنة.","h2":"يجب أن يحمل المراهق تصريح التعلّم ستة أشهر على الأقل قبل الحصول على الرخصة المؤقتة، حتى يكون لديه وقت كافٍ للتدرّب.","p":"صحيح. يجب أن تحمل التصريح ستة أشهر على الأقل."},"ref":{"doc":"AK","page":4}},{"id":"ak-008","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many hours of supervised driving must a teen complete before a provisional license?","o":["40 hours","20 hours","60 hours","100 hours"],"h1":"It is more than 30 and less than 50.","h2":"A teen needs at least 40 hours of supervised driving practice before getting a provisional license, to build real experience on the road.","p":"Right. Alaska asks for at least 40 hours of supervised driving."},"es":{"q":"En Alaska, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia provisional?","o":["40 horas","20 horas","60 horas","100 horas"],"h1":"Es más de 30 y menos de 50.","h2":"Un joven necesita por lo menos 40 horas de práctica supervisada antes de obtener la licencia provisional, para ganar experiencia real en el camino.","p":"Correcto. Alaska pide por lo menos 40 horas de manejo supervisado."},"zh":{"q":"在 Alaska，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶？","o":["40 小时","20 小时","60 小时","100 小时"],"h1":"它比 30 多，比 50 少。","h2":"青少年拿过渡驾照前，至少需要 40 小时有人监督的驾驶练习，这样才能在路上积累真正的经验。","p":"对。Alaska 要求至少 40 小时有人监督的驾驶。"},"vi":{"q":"Ở Alaska, thiếu niên phải lái xe có giám sát bao nhiêu giờ trước khi được cấp bằng lái tạm thời?","o":["40 giờ","20 giờ","60 giờ","100 giờ"],"h1":"Nhiều hơn 30 và ít hơn 50.","h2":"Thiếu niên cần ít nhất 40 giờ tập lái có giám sát trước khi được cấp bằng lái tạm thời, để có kinh nghiệm thật trên đường.","p":"Đúng. Alaska yêu cầu ít nhất 40 giờ lái xe có giám sát."},"tl":{"q":"Sa Alaska, ilang oras ng pagmamaneho na may nagbabantay ang dapat matapos ng kabataan bago ang provisional license?","o":["40 oras","20 oras","60 oras","100 oras"],"h1":"Ito ay higit sa 30 at mas kaunti sa 50.","h2":"Kailangan ng kabataan ng hindi bababa sa 40 oras ng pagsasanay sa pagmamaneho na may nagbabantay bago makakuha ng provisional license, para magkaroon ng tunay na karanasan sa daan.","p":"Tama. Humihingi ang Alaska ng hindi bababa sa 40 oras ng pagmamaneho na may nagbabantay."},"ar":{"q":"في Alaska، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل الرخصة المؤقتة؟","o":["40 ساعة","20 ساعة","60 ساعة","100 ساعة"],"h1":"العدد أكثر من 30 وأقل من 50.","h2":"يحتاج المراهق إلى 40 ساعة على الأقل من التدرّب على القيادة تحت الإشراف قبل الحصول على الرخصة المؤقتة، ليكتسب خبرة حقيقية على الطريق.","p":"صحيح. تطلب Alaska 40 ساعة على الأقل من القيادة تحت الإشراف."},"ref":{"doc":"AK","page":5}},{"id":"ak-009","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many of the required supervised hours must be in challenging conditions, such as at night or in bad weather?","o":["At least 5 hours","At least 15 hours","At least 10 hours","At least 20 hours"],"h1":"It is one quarter of the total hours.","h2":"At least 10 of the supervised hours must be in harder conditions, such as darkness or bad weather, so a new driver has practiced them with help.","p":"Right. At least 10 hours must be at night or in bad weather."},"es":{"q":"En Alaska, ¿cuántas de las horas supervisadas deben ser en condiciones difíciles, como de noche o con mal tiempo?","o":["Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 10 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total de horas.","h2":"Por lo menos 10 de las horas supervisadas deben ser en condiciones más difíciles, como de noche o con mal tiempo, para que el conductor nuevo las practique con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche o con mal tiempo."},"zh":{"q":"在 Alaska，规定的监督驾驶时间里，有多少小时必须在困难的条件下，比如晚上或天气不好时？","o":["至少 5 小时","至少 15 小时","至少 10 小时","至少 20 小时"],"h1":"它是全部时间的四分之一。","h2":"监督驾驶时间里至少 10 小时必须在比较难的条件下，比如天黑或天气不好，这样新司机已经在有人帮助时练习过。","p":"对。至少 10 小时必须在晚上或天气不好时。"},"vi":{"q":"Ở Alaska, trong số giờ lái có giám sát bắt buộc, bao nhiêu giờ phải lái trong điều kiện khó, như ban đêm hoặc thời tiết xấu?","o":["Ít nhất 5 giờ","Ít nhất 15 giờ","Ít nhất 10 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần tư tổng số giờ.","h2":"Ít nhất 10 giờ lái có giám sát phải là trong điều kiện khó hơn, như trời tối hoặc thời tiết xấu, để người lái mới đã tập những điều kiện này khi có người giúp.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm hoặc khi thời tiết xấu."},"tl":{"q":"Sa Alaska, ilan sa mga kailangang oras na may nagbabantay ang dapat sa mahirap na kondisyon, gaya ng gabi o masamang panahon?","o":["Hindi bababa sa 5 oras","Hindi bababa sa 15 oras","Hindi bababa sa 10 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-kapat ng kabuuang oras.","h2":"Hindi bababa sa 10 sa mga oras na may nagbabantay ang dapat sa mas mahirap na kondisyon, gaya ng dilim o masamang panahon, para nasanay na ang bagong driver dito nang may tumutulong.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi o sa masamang panahon."},"ar":{"q":"في Alaska، كم ساعة من ساعات القيادة تحت الإشراف المطلوبة يجب أن تكون في ظروف صعبة، مثل الليل أو الطقس السيئ؟","o":["5 ساعات على الأقل","15 ساعة على الأقل","10 ساعات على الأقل","20 ساعة على الأقل"],"h1":"إنها ربع مجموع الساعات.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات الإشراف في ظروف أصعب، مثل الظلام أو الطقس السيئ، حتى يكون السائق الجديد قد تدرّب عليها مع من يساعده.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل أو في الطقس السيئ."},"ref":{"doc":"AK","page":5}},{"id":"ak-010","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is two years after the youngest permit age.","h2":"You can get a provisional license at 16, after you have held your permit long enough and finished your practice hours.","p":"Right. The provisional license starts at age 16."},"es":{"q":"En Alaska, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Es dos años después de la edad mínima del permiso.","h2":"Usted puede obtener la licencia provisional a los 16 años, después de tener el permiso el tiempo necesario y terminar sus horas de práctica.","p":"Correcto. La licencia provisional empieza a los 16 años."},"zh":{"q":"在 Alaska，最小几岁可以拿到过渡驾照？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它比拿学习驾照的最小年龄晚两年。","h2":"你在持有学习驾照够久、并完成练习时间以后，16 岁就可以拿到过渡驾照。","p":"对。过渡驾照从 16 岁开始。"},"vi":{"q":"Ở Alaska, tuổi nhỏ nhất để được cấp bằng lái tạm thời là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là hai năm sau tuổi nhỏ nhất để có giấy phép tập lái.","h2":"Bạn có thể được cấp bằng lái tạm thời khi 16 tuổi, sau khi đã giữ giấy phép tập lái đủ lâu và lái đủ số giờ tập.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Alaska, ano ang pinakabatang edad para makakuha ng provisional license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ito ay dalawang taon pagkatapos ng pinakabatang edad para sa permit.","h2":"Puwede kang kumuha ng provisional license sa edad na 16, pagkatapos mong mahawakan ang permit nang sapat na tagal at matapos ang iyong mga oras ng pagsasanay.","p":"Tama. Nagsisimula ang provisional license sa edad na 16."},"ar":{"q":"في Alaska، ما أصغر عمر للحصول على الرخصة المؤقتة؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"إنه بعد أصغر عمر للتصريح بسنتين.","h2":"يمكنك الحصول على الرخصة المؤقتة في سن 16، بعد أن تحمل التصريح مدة كافية وتُكمل ساعات التدرّب.","p":"صحيح. تبدأ الرخصة المؤقتة في سن 16."},"ref":{"doc":"AK","page":5}},{"id":"ak-011","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, during which hours may a provisional driver not drive alone, unless driving for work?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts after midnight and ends before sunrise in most seasons.","h2":"A provisional driver may not drive between 1 a.m. and 5 a.m. unless a licensed driver age 21 or older is in the car or the trip is for work.","p":"Right. Provisional drivers stay off the road from 1 a.m. to 5 a.m."},"es":{"q":"En Alaska, ¿en qué horario no puede manejar un conductor con licencia provisional, salvo por trabajo?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza después de la medianoche y termina antes del amanecer en casi todas las estaciones.","h2":"Un conductor con licencia provisional no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya con un conductor con licencia de 21 años o más, o que el viaje sea por trabajo.","p":"Correcto. Los conductores provisionales no manejan de 1 a.m. a 5 a.m."},"zh":{"q":"在 Alaska，持过渡驾照的司机在哪段时间不能单独开车（为工作开车除外）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"这个限制在午夜以后开始，在大多数季节天亮以前结束。","h2":"持过渡驾照的司机在凌晨 1 点到早上 5 点之间不能开车，除非车里有一位 21 岁或以上、有驾照的司机，或者是为工作开车。","p":"对。持过渡驾照的司机凌晨 1 点到早上 5 点不上路。"},"vi":{"q":"Ở Alaska, người có bằng lái tạm thời không được lái xe một mình trong khoảng giờ nào, trừ khi lái xe vì công việc?","o":["10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu sau nửa đêm và kết thúc trước khi mặt trời mọc ở hầu hết các mùa.","h2":"Người có bằng lái tạm thời không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên trong xe hoặc chuyến đi là vì công việc.","p":"Đúng. Người có bằng lái tạm thời không lái xe từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Alaska, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang provisional driver, maliban kung para sa trabaho?","o":["10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon pagkalipas ng hatinggabi at natatapos bago sumikat ang araw sa karamihan ng panahon.","h2":"Ang provisional driver ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung may lisensiyadong driver na 21 taong gulang o higit pa sa sasakyan o ang biyahe ay para sa trabaho.","p":"Tama. Hindi nagmamaneho ang provisional driver mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Alaska، في أي ساعات لا يجوز لصاحب الرخصة المؤقتة أن يقود وحده، إلا إذا كانت القيادة من أجل العمل؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل وينتهي قبل شروق الشمس في معظم الفصول.","h2":"لا يجوز لصاحب الرخصة المؤقتة أن يقود بين 1 صباحًا و5 صباحًا، إلا إذا كان في السيارة سائق مرخَّص عمره 21 سنة أو أكثر أو كانت الرحلة من أجل العمل.","p":"صحيح. لا يقود أصحاب الرخص المؤقتة من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"AK","page":6}},{"id":"ak-012","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, which trip is allowed for a provisional driver during the restricted night hours, even with no adult in the car?","o":["Driving to or from a job","Driving to a friend’s house","Driving to a late movie","Driving to a store"],"h1":"The exception is about earning a living.","h2":"A provisional driver may drive during the restricted hours when going to or from work, or as part of a job, using the most direct route.","p":"Right. Driving to or from work is the exception."},"es":{"q":"En Alaska, ¿qué viaje se permite a un conductor provisional en las horas restringidas de la noche, aun sin un adulto en el carro?","o":["Ir o volver del trabajo","Ir a la casa de un amigo","Ir a una película tarde","Ir a una tienda"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor provisional puede manejar en las horas restringidas cuando va o vuelve del trabajo, o como parte de su trabajo, por la ruta más directa.","p":"Correcto. Ir o volver del trabajo es la excepción."},"zh":{"q":"在 Alaska，在限制的夜间时段，即使车里没有成年人，持过渡驾照的司机可以开车去哪里？","o":["上班或下班","去朋友家","去看晚场电影","去商店"],"h1":"这个例外和赚钱养活自己有关。","h2":"持过渡驾照的司机在限制时段内，如果是上班、下班或为工作开车，可以走最直接的路线开车。","p":"对。上班或下班开车是例外。"},"vi":{"q":"Ở Alaska, chuyến đi nào được phép cho người có bằng lái tạm thời trong giờ ban đêm bị giới hạn, kể cả khi không có người lớn trong xe?","o":["Lái xe đi làm hoặc từ chỗ làm về","Lái xe đến nhà bạn","Lái xe đi xem phim khuya","Lái xe đến cửa hàng"],"h1":"Ngoại lệ này liên quan đến việc kiếm sống.","h2":"Người có bằng lái tạm thời được lái xe trong giờ bị giới hạn khi đi làm hoặc từ chỗ làm về, hoặc khi lái xe vì công việc, theo đường đi thẳng nhất.","p":"Đúng. Lái xe đi làm hoặc từ chỗ làm về là ngoại lệ."},"tl":{"q":"Sa Alaska, aling biyahe ang pinapayagan sa provisional driver sa mga oras ng gabing may limitasyon, kahit walang adult sa sasakyan?","o":["Pagmamaneho papunta o pauwi mula sa trabaho","Pagmamaneho papunta sa bahay ng kaibigan","Pagmamaneho papunta sa sine sa gabi","Pagmamaneho papunta sa tindahan"],"h1":"Ang eksepsiyon ay tungkol sa paghahanapbuhay.","h2":"Puwedeng magmaneho ang provisional driver sa mga oras na may limitasyon kapag papunta o pauwi mula sa trabaho, o bilang bahagi ng trabaho, gamit ang pinakadiretsong ruta.","p":"Tama. Ang pagmamaneho papunta o pauwi mula sa trabaho ang eksepsiyon."},"ar":{"q":"في Alaska، أي رحلة مسموحة لصاحب الرخصة المؤقتة في ساعات الليل الممنوعة، حتى بدون شخص بالغ في السيارة؟","o":["القيادة إلى العمل أو منه","القيادة إلى بيت صديق","القيادة إلى فيلم في وقت متأخر","القيادة إلى متجر"],"h1":"الاستثناء يتعلّق بكسب الرزق.","h2":"يجوز لصاحب الرخصة المؤقتة أن يقود في الساعات الممنوعة عندما يذهب إلى العمل أو يعود منه، أو كجزء من عمله، باستخدام أقصر طريق مباشر.","p":"صحيح. القيادة إلى العمل أو منه هي الاستثناء."},"ref":{"doc":"AK","page":6}},{"id":"ak-013","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, which passengers may a provisional driver carry with no adult supervisor in the car?","o":["Any friends under 18","Up to three passengers of any age","Passengers 21 or older, and siblings","Only passengers under 16"],"h1":"Young passengers are limited, but family has an exception.","h2":"Unless a parent, guardian, or another person age 21 or older is riding along, a provisional driver may not carry passengers under 21, except brothers and sisters.","p":"Right. Passengers under 21 are not allowed, except siblings."},"es":{"q":"En Alaska, ¿a qué pasajeros puede llevar un conductor provisional sin un adulto supervisor en el carro?","o":["A cualquier amigo menor de 18","Hasta tres pasajeros de cualquier edad","Pasajeros de 21 años o más, y hermanos","Solo pasajeros menores de 16"],"h1":"Los pasajeros jóvenes están limitados, pero la familia tiene una excepción.","h2":"A menos que vaya con usted su padre, madre, tutor u otra persona de 21 años o más, un conductor provisional no puede llevar pasajeros menores de 21 años, excepto a sus hermanos.","p":"Correcto. No se permiten pasajeros menores de 21, excepto hermanos."},"zh":{"q":"在 Alaska，车里没有成年人监督时，持过渡驾照的司机可以载哪些乘客？","o":["任何 18 岁以下的朋友","最多三位任何年龄的乘客","21 岁或以上的乘客，以及兄弟姐妹","只有 16 岁以下的乘客"],"h1":"年轻乘客有限制，但家人有例外。","h2":"除非有父母、监护人或另一位 21 岁或以上的人同车，持过渡驾照的司机不能载 21 岁以下的乘客，兄弟姐妹除外。","p":"对。不能载 21 岁以下的乘客，兄弟姐妹除外。"},"vi":{"q":"Ở Alaska, người có bằng lái tạm thời được chở những hành khách nào khi không có người lớn giám sát trong xe?","o":["Bất kỳ người bạn nào dưới 18 tuổi","Tối đa ba hành khách ở mọi độ tuổi","Hành khách từ 21 tuổi trở lên, và anh chị em ruột","Chỉ hành khách dưới 16 tuổi"],"h1":"Hành khách trẻ bị giới hạn, nhưng gia đình có ngoại lệ.","h2":"Trừ khi có cha mẹ, người giám hộ hoặc một người khác từ 21 tuổi trở lên đi cùng, người có bằng lái tạm thời không được chở hành khách dưới 21 tuổi, trừ anh chị em ruột.","p":"Đúng. Không được chở hành khách dưới 21 tuổi, trừ anh chị em ruột."},"tl":{"q":"Sa Alaska, aling mga pasahero ang puwedeng isakay ng provisional driver kung walang nagbabantay na adult sa sasakyan?","o":["Kahit sinong kaibigan na wala pang 18","Hanggang tatlong pasahero sa kahit anong edad","Mga pasaherong 21 taong gulang o higit pa, at mga kapatid","Mga pasaherong wala pang 16 lamang"],"h1":"Limitado ang mga batang pasahero, pero may eksepsiyon para sa pamilya.","h2":"Maliban kung may kasamang magulang, guardian, o ibang taong 21 taong gulang o higit pa, hindi puwedeng magsakay ang provisional driver ng mga pasaherong wala pang 21, maliban sa mga kapatid.","p":"Tama. Hindi pinapayagan ang mga pasaherong wala pang 21, maliban sa mga kapatid."},"ar":{"q":"في Alaska، أي ركاب يجوز لصاحب الرخصة المؤقتة أن ينقلهم بدون مشرف بالغ في السيارة؟","o":["أي أصدقاء عمرهم أقل من 18","حتى ثلاثة ركاب من أي عمر","ركاب عمرهم 21 أو أكثر، والإخوة والأخوات","ركاب عمرهم أقل من 16 فقط"],"h1":"الركاب الصغار محدودون، لكن للعائلة استثناء.","h2":"إلا إذا كان معه أحد الوالدين أو الوصي أو شخص آخر عمره 21 سنة أو أكثر، لا يجوز لصاحب الرخصة المؤقتة أن ينقل ركابًا عمرهم أقل من 21، ما عدا الإخوة والأخوات.","p":"صحيح. لا يُسمح بركاب عمرهم أقل من 21، ما عدا الإخوة والأخوات."},"ref":{"doc":"AK","page":6}},{"id":"ak-014","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, when do the provisional license limits end?","o":["After one month with no crash","At age 18, or after six months with no violations","Only at age 21","After the driver passes a second road test"],"h1":"There are two ways: an age and a clean record.","h2":"The provisional limits end when you turn 18, or after six months on the provisional license with no violations, when you ask the DMV to remove them.","p":"Right. The limits end at 18 or after six clean months."},"es":{"q":"En Alaska, ¿cuándo terminan las restricciones de la licencia provisional?","o":["Después de un mes sin choques","A los 18 años, o después de seis meses sin infracciones","Solo a los 21 años","Después de pasar un segundo examen de manejo"],"h1":"Hay dos caminos: una edad y un récord limpio.","h2":"Las restricciones provisionales terminan cuando usted cumple 18 años, o después de seis meses con la licencia provisional sin infracciones, cuando usted pide al DMV que las quite.","p":"Correcto. Terminan a los 18 o después de seis meses sin infracciones."},"zh":{"q":"在 Alaska，过渡驾照的限制什么时候结束？","o":["一个月没有车祸以后","满 18 岁，或者六个月没有违规以后","只有到 21 岁","司机通过第二次路考以后"],"h1":"有两种方法：一个年龄，和一个干净的记录。","h2":"过渡驾照的限制在你满 18 岁时结束；或者持过渡驾照六个月没有违规以后，你向 DMV 申请取消限制。","p":"对。限制在 18 岁时或六个月没有违规以后结束。"},"vi":{"q":"Ở Alaska, khi nào các giới hạn của bằng lái tạm thời kết thúc?","o":["Sau một tháng không có tai nạn","Khi 18 tuổi, hoặc sau sáu tháng không vi phạm","Chỉ khi 21 tuổi","Sau khi người lái thi đậu bài thi lái xe lần thứ hai"],"h1":"Có hai cách: một độ tuổi và một hồ sơ sạch.","h2":"Các giới hạn của bằng lái tạm thời kết thúc khi bạn 18 tuổi, hoặc sau sáu tháng có bằng lái tạm thời mà không vi phạm, khi bạn xin DMV bỏ các giới hạn đó.","p":"Đúng. Các giới hạn kết thúc khi 18 tuổi hoặc sau sáu tháng không vi phạm."},"tl":{"q":"Sa Alaska, kailan natatapos ang mga limitasyon ng provisional license?","o":["Pagkalipas ng isang buwan na walang aksidente","Sa edad na 18, o pagkalipas ng anim na buwan na walang paglabag","Sa edad na 21 lamang","Pagkatapos makapasa ang driver sa ikalawang road test"],"h1":"May dalawang paraan: isang edad at isang malinis na rekord.","h2":"Natatapos ang mga limitasyon ng provisional kapag ikaw ay 18 na, o pagkalipas ng anim na buwan sa provisional license na walang paglabag, kapag hiniling mo sa DMV na alisin ang mga ito.","p":"Tama. Natatapos ang mga limitasyon sa edad na 18 o pagkalipas ng anim na malinis na buwan."},"ar":{"q":"في Alaska، متى تنتهي قيود الرخصة المؤقتة؟","o":["بعد شهر واحد بدون حادث","في سن 18، أو بعد ستة أشهر بدون مخالفات","في سن 21 فقط","بعد أن ينجح السائق في اختبار قيادة ثانٍ"],"h1":"هناك طريقتان: عمر معيّن وسجل نظيف.","h2":"تنتهي قيود الرخصة المؤقتة عندما تبلغ 18 سنة، أو بعد ستة أشهر على الرخصة المؤقتة بدون مخالفات، عندما تطلب من DMV إزالتها.","p":"صحيح. تنتهي القيود في سن 18 أو بعد ستة أشهر نظيفة."},"ref":{"doc":"AK","page":6}},{"id":"ak-015","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many questions are on the general knowledge test for a driver license?","o":["10 questions","25 questions","20 questions","30 questions"],"h1":"It is a round number between 15 and 25.","h2":"The Alaska general knowledge test has 20 questions, so each one counts for a lot.","p":"Right. The Alaska knowledge test has 20 questions."},"es":{"q":"En Alaska, ¿cuántas preguntas tiene el examen de conocimientos generales para la licencia?","o":["10 preguntas","25 preguntas","20 preguntas","30 preguntas"],"h1":"Es un número redondo entre 15 y 25.","h2":"El examen de conocimientos generales de Alaska tiene 20 preguntas, así que cada una cuenta mucho.","p":"Correcto. El examen de conocimientos de Alaska tiene 20 preguntas."},"zh":{"q":"在 Alaska，驾照的普通知识笔试有多少道题？","o":["10 道题","25 道题","20 道题","30 道题"],"h1":"它是 15 和 25 之间的一个整数。","h2":"Alaska 的普通知识笔试有 20 道题，所以每一道题都很重要。","p":"对。Alaska 的笔试有 20 道题。"},"vi":{"q":"Ở Alaska, bài thi kiến thức chung để lấy bằng lái có bao nhiêu câu hỏi?","o":["10 câu hỏi","25 câu hỏi","20 câu hỏi","30 câu hỏi"],"h1":"Đó là một số tròn giữa 15 và 25.","h2":"Bài thi kiến thức chung ở Alaska có 20 câu hỏi, vì vậy mỗi câu đều rất quan trọng.","p":"Đúng. Bài thi kiến thức ở Alaska có 20 câu hỏi."},"tl":{"q":"Sa Alaska, ilang tanong ang nasa general knowledge test para sa driver license?","o":["10 tanong","25 tanong","20 tanong","30 tanong"],"h1":"Ito ay buong numero sa pagitan ng 15 at 25.","h2":"Ang general knowledge test sa Alaska ay may 20 tanong, kaya malaki ang halaga ng bawat isa.","p":"Tama. May 20 tanong ang knowledge test sa Alaska."},"ar":{"q":"في Alaska، كم سؤالًا في اختبار المعرفة العامة لرخصة القيادة؟","o":["10 أسئلة","25 سؤالًا","20 سؤالًا","30 سؤالًا"],"h1":"إنه رقم مستدير بين 15 و25.","h2":"اختبار المعرفة العامة في Alaska فيه 20 سؤالًا، لذلك كل سؤال له وزن كبير.","p":"صحيح. اختبار المعرفة في Alaska فيه 20 سؤالًا."},"ref":{"doc":"AK","page":null}},{"id":"ak-016","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many correct answers do you need to pass the general knowledge test?","o":["16 correct answers","14 correct answers","18 correct answers","12 correct answers"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 16 questions correctly to pass, which is 80 percent of the test.","p":"Right. You need 16 correct answers to pass."},"es":{"q":"En Alaska, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos generales?","o":["16 respuestas correctas","14 respuestas correctas","18 respuestas correctas","12 respuestas correctas"],"h1":"Necesita el 80 por ciento de las preguntas bien.","h2":"Usted debe contestar bien por lo menos 16 preguntas para aprobar, que es el 80 por ciento del examen.","p":"Correcto. Necesita 16 respuestas correctas para aprobar."},"zh":{"q":"在 Alaska，普通知识笔试要答对多少道题才能通过？","o":["答对 16 道","答对 14 道","答对 18 道","答对 12 道"],"h1":"你需要答对 80% 的题目。","h2":"你必须至少答对 16 道题才能通过，也就是笔试的 80%。","p":"对。你需要答对 16 道题才能通过。"},"vi":{"q":"Ở Alaska, bạn cần bao nhiêu câu trả lời đúng để đậu bài thi kiến thức chung?","o":["16 câu trả lời đúng","14 câu trả lời đúng","18 câu trả lời đúng","12 câu trả lời đúng"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 16 câu để đậu, tức là 80 phần trăm của bài thi.","p":"Đúng. Bạn cần 16 câu trả lời đúng để đậu."},"tl":{"q":"Sa Alaska, ilang tamang sagot ang kailangan mo para pumasa sa general knowledge test?","o":["16 na tamang sagot","14 na tamang sagot","18 na tamang sagot","12 na tamang sagot"],"h1":"Kailangan mong tama ang 80 porsiyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 16 na tanong para pumasa, na 80 porsiyento ng test.","p":"Tama. Kailangan mo ng 16 na tamang sagot para pumasa."},"ar":{"q":"في Alaska، كم إجابة صحيحة تحتاج لتنجح في اختبار المعرفة العامة؟","o":["16 إجابة صحيحة","14 إجابة صحيحة","18 إجابة صحيحة","12 إجابة صحيحة"],"h1":"تحتاج إلى إجابة 80 في المئة من الأسئلة بشكل صحيح.","h2":"يجب أن تجيب على 16 سؤالًا على الأقل بشكل صحيح لتنجح، وهذا 80 في المئة من الاختبار.","p":"صحيح. تحتاج إلى 16 إجابة صحيحة لتنجح."},"ref":{"doc":"AK","page":null}},{"id":"ak-017","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a residential district?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is a little faster than in a business district.","h2":"Unless a sign says otherwise, the top legal speed in a residential district is 25 mph, because children and walkers are often near the road.","p":"Right. The default limit in a residential district is 25 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona residencial es 25 mph, porque a menudo hay niños y peatones cerca del camino.","p":"Correcto. El límite normal en una zona residencial es 25 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，住宅区的最高速度是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比商业区快一点。","h2":"除非标志另有规定，住宅区的最高合法速度是 25 mph，因为孩子和行人常常在路边。","p":"对。住宅区的默认限速是 25 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong khu dân cư là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó nhanh hơn một chút so với khu thương mại.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong khu dân cư là 25 mph, vì trẻ em và người đi bộ thường ở gần đường.","p":"Đúng. Giới hạn mặc định trong khu dân cư là 25 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa residential district?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Medyo mas mabilis ito kaysa sa business district.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa residential district ay 25 mph, dahil madalas may mga bata at naglalakad malapit sa daan.","p":"Tama. Ang default na limitasyon sa residential district ay 25 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في المنطقة السكنية؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"إنها أسرع قليلًا من المنطقة التجارية.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في المنطقة السكنية هي 25 mph، لأن الأطفال والمشاة يكونون غالبًا قرب الطريق.","p":"صحيح. الحد الأساسي في المنطقة السكنية هو 25 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-018","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a business district?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"It is slower than a residential district.","h2":"Unless a sign says otherwise, the top legal speed in a business district is 20 mph, because traffic, parking and people on foot are very close together.","p":"Right. The default limit in a business district is 20 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en una zona comercial?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Es más lento que en una zona residencial.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en una zona comercial es 20 mph, porque el tráfico, los carros estacionados y los peatones están muy cerca.","p":"Correcto. El límite normal en una zona comercial es 20 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，商业区的最高速度是多少？","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"它比住宅区慢。","h2":"除非标志另有规定，商业区的最高合法速度是 20 mph，因为车流、停车和行人都离得很近。","p":"对。商业区的默认限速是 20 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong khu thương mại là bao nhiêu?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Nó chậm hơn so với khu dân cư.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong khu thương mại là 20 mph, vì xe cộ, chỗ đậu xe và người đi bộ ở rất gần nhau.","p":"Đúng. Giới hạn mặc định trong khu thương mại là 20 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa business district?","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"Mas mabagal ito kaysa sa residential district.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa business district ay 20 mph, dahil magkakalapit ang trapiko, paradahan at mga taong naglalakad.","p":"Tama. Ang default na limitasyon sa business district ay 20 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في المنطقة التجارية؟","o":["20 mph","15 mph","30 mph","25 mph"],"h1":"إنها أبطأ من المنطقة السكنية.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في المنطقة التجارية هي 20 mph، لأن السيارات والمواقف والمشاة قريبون جدًا من بعضهم.","p":"صحيح. الحد الأساسي في المنطقة التجارية هو 20 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-019","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is the lowest of the default limits, but more than 10.","h2":"Unless a sign says otherwise, the top legal speed in an alley is 15 mph, because alleys are narrow and you cannot see far.","p":"Right. The default limit in an alley is 15 mph."},"es":{"q":"En Alaska, si ninguna señal indica otro límite, ¿cuál es la velocidad máxima en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es el más bajo de los límites normales, pero más de 10.","h2":"Salvo que una señal diga otra cosa, la velocidad máxima legal en un callejón es 15 mph, porque los callejones son angostos y no se ve lejos.","p":"Correcto. El límite normal en un callejón es 15 mph."},"zh":{"q":"在 Alaska，如果没有标志写着别的限速，小巷里的最高速度是多少？","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"它是默认限速里最低的，但比 10 高。","h2":"除非标志另有规定，小巷里的最高合法速度是 15 mph，因为小巷很窄，你看不远。","p":"对。小巷的默认限速是 15 mph。"},"vi":{"q":"Ở Alaska, nếu không có biển báo giới hạn khác, tốc độ tối đa trong hẻm là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Đó là giới hạn mặc định thấp nhất, nhưng cao hơn 10.","h2":"Trừ khi có biển báo khác, tốc độ tối đa hợp pháp trong hẻm là 15 mph, vì hẻm hẹp và bạn không nhìn được xa.","p":"Đúng. Giới hạn mặc định trong hẻm là 15 mph."},"tl":{"q":"Sa Alaska, kung walang karatulang nagpapakita ng ibang limitasyon, ano ang pinakamataas na bilis sa eskinita (alley)?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Ito ang pinakamababa sa mga default na limitasyon, pero higit sa 10.","h2":"Maliban kung iba ang sinasabi ng karatula, ang pinakamataas na legal na bilis sa eskinita ay 15 mph, dahil makitid ang mga eskinita at hindi ka makakita nang malayo.","p":"Tama. Ang default na limitasyon sa eskinita ay 15 mph."},"ar":{"q":"في Alaska، إذا لم تكن هناك لافتة تُظهر حدًا مختلفًا، ما أعلى سرعة في الزقاق (alley)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"إنها أقل الحدود الأساسية، لكنها أكثر من 10.","h2":"إلا إذا قالت لافتة غير ذلك، أعلى سرعة قانونية في الزقاق هي 15 mph، لأن الأزقة ضيقة ولا يمكنك أن ترى بعيدًا.","p":"صحيح. الحد الأساسي في الزقاق هو 15 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-020","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, on a road outside business and residential districts with no speed sign, what is the top legal speed?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Higher limits on some highways must be posted on signs.","h2":"When no sign shows a limit on other roads, the top legal speed is 55 mph; faster limits apply only where signs post them.","p":"Right. The default limit on other roads is 55 mph."},"es":{"q":"En Alaska, en un camino fuera de zonas comerciales y residenciales y sin señal de velocidad, ¿cuál es la velocidad máxima legal?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Los límites más altos en algunas carreteras deben estar en señales.","h2":"Cuando ninguna señal indica el límite en otros caminos, la velocidad máxima legal es 55 mph; los límites más altos solo aplican donde hay señales.","p":"Correcto. El límite normal en otros caminos es 55 mph."},"zh":{"q":"在 Alaska，在商业区和住宅区以外、没有限速标志的道路上，最高合法速度是多少？","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"有些公路的更高限速必须用标志写出来。","h2":"在其他道路上没有标志写着限速时，最高合法速度是 55 mph；更高的限速只在有标志的地方适用。","p":"对。其他道路的默认限速是 55 mph。"},"vi":{"q":"Ở Alaska, trên đường ngoài khu thương mại và khu dân cư, không có biển báo tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Giới hạn cao hơn trên một số xa lộ phải được ghi trên biển báo.","h2":"Khi không có biển báo giới hạn trên các đường khác, tốc độ tối đa hợp pháp là 55 mph; giới hạn cao hơn chỉ áp dụng ở nơi có biển báo ghi rõ.","p":"Đúng. Giới hạn mặc định trên các đường khác là 55 mph."},"tl":{"q":"Sa Alaska, sa daan na nasa labas ng business at residential district na walang karatula ng bilis, ano ang pinakamataas na legal na bilis?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Ang mas mataas na limitasyon sa ilang highway ay dapat nakasulat sa karatula.","h2":"Kapag walang karatulang nagpapakita ng limitasyon sa ibang daan, ang pinakamataas na legal na bilis ay 55 mph; ang mas mabilis na limitasyon ay para lamang sa mga lugar na may karatula nito.","p":"Tama. Ang default na limitasyon sa ibang daan ay 55 mph."},"ar":{"q":"في Alaska، على طريق خارج المناطق التجارية والسكنية بدون لافتة سرعة، ما أعلى سرعة قانونية؟","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"الحدود الأعلى على بعض الطرق السريعة يجب أن تُكتب على لافتات.","h2":"عندما لا توجد لافتة تُظهر الحد على الطرق الأخرى، أعلى سرعة قانونية هي 55 mph؛ والحدود الأسرع تنطبق فقط حيث تُظهرها اللافتات.","p":"صحيح. الحد الأساسي على الطرق الأخرى هو 55 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-021","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, during which time must you have your headlights on?","o":["Only when it is fully dark outside","From half an hour after sunset to half an hour before sunrise","From one hour after sunset to sunrise","Only on highways with more than two lanes"],"h1":"The rule adds a short time around sunset and sunrise.","h2":"You must use your headlights from half an hour after sunset until half an hour before sunrise, so others can see you in low light.","p":"Right. Lights go on half an hour after sunset until half an hour before sunrise."},"es":{"q":"En Alaska, ¿en qué horario debe llevar las luces delanteras encendidas?","o":["Solo cuando está totalmente oscuro","Desde media hora después de la puesta del sol hasta media hora antes del amanecer","Desde una hora después de la puesta del sol hasta el amanecer","Solo en carreteras de más de dos carriles"],"h1":"La regla agrega un rato corto alrededor de la puesta del sol y el amanecer.","h2":"Usted debe usar las luces delanteras desde media hora después de la puesta del sol hasta media hora antes del amanecer, para que otros lo vean con poca luz.","p":"Correcto. Las luces van encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer."},"zh":{"q":"在 Alaska，你必须在什么时间打开大灯？","o":["只有外面完全黑的时候","日落后半小时到日出前半小时","日落后一小时到日出","只在超过两条车道的公路上"],"h1":"这个规定在日落和日出前后多加了一小段时间。","h2":"你必须从日落后半小时到日出前半小时打开大灯，这样在光线不好时别人能看到你。","p":"对。日落后半小时到日出前半小时要开灯。"},"vi":{"q":"Ở Alaska, bạn phải bật đèn pha trong khoảng thời gian nào?","o":["Chỉ khi bên ngoài trời tối hẳn","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc","Từ một giờ sau khi mặt trời lặn đến khi mặt trời mọc","Chỉ trên xa lộ có hơn hai làn xe"],"h1":"Quy định thêm một khoảng thời gian ngắn quanh lúc mặt trời lặn và mọc.","h2":"Bạn phải bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc, để người khác nhìn thấy bạn khi trời ít sáng.","p":"Đúng. Bật đèn từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa Alaska, sa anong oras dapat nakabukas ang iyong headlights?","o":["Kapag ganap na madilim lamang sa labas","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw","Mula isang oras pagkalubog ng araw hanggang sa pagsikat ng araw","Sa mga highway lamang na may higit sa dalawang lane"],"h1":"Nagdadagdag ang patakaran ng maikling oras sa paligid ng paglubog at pagsikat ng araw.","h2":"Dapat mong gamitin ang iyong headlights mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw, para makita ka ng iba kapag mahina ang liwanag.","p":"Tama. Binubuksan ang ilaw mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw."},"ar":{"q":"في Alaska، في أي وقت يجب أن تكون أضواء سيارتك الأمامية مضاءة؟","o":["فقط عندما يكون الظلام كاملًا في الخارج","من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها","من ساعة بعد غروب الشمس إلى شروقها","فقط على الطرق السريعة التي فيها أكثر من مسارين"],"h1":"القاعدة تضيف وقتًا قصيرًا حول الغروب والشروق.","h2":"يجب أن تستعمل الأضواء الأمامية من نصف ساعة بعد غروب الشمس حتى نصف ساعة قبل شروقها، حتى يراك الآخرون عندما يكون الضوء ضعيفًا.","p":"صحيح. تُشعل الأضواء من نصف ساعة بعد الغروب حتى نصف ساعة قبل الشروق."},"ref":{"doc":"AK","page":55}},{"id":"ak-022","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, you must also turn on your headlights when you cannot clearly see people or vehicles at what distance?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"It is a round number, about three football fields.","h2":"You must turn on your headlights any time fog, snow or low light keeps you from clearly seeing people or vehicles 1,000 feet away.","p":"Right. If you cannot see clearly at 1,000 feet, turn your lights on."},"es":{"q":"En Alaska, también debe encender las luces delanteras cuando no puede ver bien a personas o vehículos. ¿A qué distancia?","o":["500 pies","200 pies","1,500 pies","1,000 pies"],"h1":"Es un número redondo, como tres canchas de fútbol americano.","h2":"Usted debe encender las luces delanteras siempre que la niebla, la nieve o la poca luz no le dejen ver bien a personas o vehículos a 1,000 pies.","p":"Correcto. Si no ve bien a 1,000 pies, encienda las luces."},"zh":{"q":"在 Alaska，当你在多远的距离看不清人或车辆时，也必须打开大灯？","o":["500 英尺","200 英尺","1,500 英尺","1,000 英尺"],"h1":"它是一个整数，大约是三个橄榄球场那么长。","h2":"只要雾、雪或光线不好让你看不清 1,000 英尺外的人或车辆，你就必须打开大灯。","p":"对。如果在 1,000 英尺看不清，就要开灯。"},"vi":{"q":"Ở Alaska, bạn cũng phải bật đèn pha khi không nhìn rõ người hoặc xe ở khoảng cách bao xa?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"Đó là một số tròn, khoảng ba sân bóng bầu dục.","h2":"Bạn phải bật đèn pha bất cứ khi nào sương mù, tuyết hoặc trời ít sáng làm bạn không nhìn rõ người hoặc xe ở cách 1,000 feet.","p":"Đúng. Nếu không nhìn rõ ở 1,000 feet, hãy bật đèn."},"tl":{"q":"Sa Alaska, dapat mo ring buksan ang headlights kapag hindi mo malinaw na makita ang mga tao o sasakyan sa anong layo?","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"Ito ay buong numero, mga tatlong football field.","h2":"Dapat mong buksan ang headlights tuwing ang fog, niyebe o mahinang liwanag ay pumipigil sa iyong malinaw na makita ang mga tao o sasakyan sa layong 1,000 feet.","p":"Tama. Kung hindi ka malinaw na makakita sa 1,000 feet, buksan ang iyong ilaw."},"ar":{"q":"في Alaska، يجب أيضًا أن تُشعل الأضواء الأمامية عندما لا تستطيع أن ترى الناس أو المركبات بوضوح على أي مسافة؟","o":["500 feet","200 feet","1,500 feet","1,000 feet"],"h1":"إنه رقم مستدير، حوالي طول ثلاثة ملاعب كرة قدم أمريكية.","h2":"يجب أن تُشعل الأضواء الأمامية في أي وقت يمنعك فيه الضباب أو الثلج أو الضوء الضعيف من رؤية الناس أو المركبات بوضوح على بُعد 1,000 feet.","p":"صحيح. إذا لم تستطع أن ترى بوضوح على بُعد 1,000 feet، أشعل الأضواء."},"ref":{"doc":"AK","page":55}},{"id":"ak-023","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, you are driving slowly on a two-lane road outside a city. How many vehicles lined up behind you mean you must pull over at the first safe place?","o":["Two vehicles","Three vehicles","Five vehicles","Ten vehicles"],"h1":"It is the number of fingers on one hand.","h2":"When five or more vehicles are lined up right behind you on a two-lane road outside a city, you must pull off the road at the first safe place to let them by.","p":"Right. Five or more vehicles behind you means you pull over at the first safe place."},"es":{"q":"En Alaska, usted maneja despacio en un camino de dos carriles fuera de la ciudad. ¿Cuántos vehículos en fila detrás de usted lo obligan a orillarse en el primer lugar seguro?","o":["Dos vehículos","Tres vehículos","Cinco vehículos","Diez vehículos"],"h1":"Es el número de dedos de una mano.","h2":"Cuando cinco o más vehículos van en fila justo detrás de usted en un camino de dos carriles fuera de la ciudad, usted debe salirse del camino en el primer lugar seguro para dejarlos pasar.","p":"Correcto. Con cinco o más vehículos detrás, oríllese en el primer lugar seguro."},"zh":{"q":"在 Alaska，你在城外的双车道道路上开得很慢。你后面排了多少辆车时，你必须在第一个安全的地方靠边？","o":["两辆车","三辆车","五辆车","十辆车"],"h1":"它是一只手的手指数。","h2":"在城外的双车道道路上，当你正后面排了五辆或更多的车时，你必须在第一个安全的地方开出道路，让它们过去。","p":"对。后面有五辆或更多的车，就要在第一个安全的地方靠边。"},"vi":{"q":"Ở Alaska, bạn đang lái chậm trên đường hai làn ngoài thành phố. Có bao nhiêu xe nối đuôi sau bạn thì bạn phải tấp vào lề ở chỗ an toàn đầu tiên?","o":["Hai xe","Ba xe","Năm xe","Mười xe"],"h1":"Đó là số ngón tay trên một bàn tay.","h2":"Khi có năm xe trở lên nối đuôi ngay sau bạn trên đường hai làn ngoài thành phố, bạn phải tấp ra khỏi đường ở chỗ an toàn đầu tiên để họ đi qua.","p":"Đúng. Có năm xe trở lên sau bạn thì bạn tấp vào ở chỗ an toàn đầu tiên."},"tl":{"q":"Sa Alaska, mabagal kang nagmamaneho sa two-lane na daan sa labas ng lungsod. Ilang sasakyan na nakapila sa likod mo ang nangangahulugang dapat kang tumabi sa unang ligtas na lugar?","o":["Dalawang sasakyan","Tatlong sasakyan","Limang sasakyan","Sampung sasakyan"],"h1":"Ito ang bilang ng mga daliri sa isang kamay.","h2":"Kapag lima o higit pang sasakyan ang nakapila sa likod mo sa two-lane na daan sa labas ng lungsod, dapat kang umalis sa daan sa unang ligtas na lugar para makadaan sila.","p":"Tama. Lima o higit pang sasakyan sa likod mo ay nangangahulugang tumabi ka sa unang ligtas na lugar."},"ar":{"q":"في Alaska، أنت تقود ببطء على طريق ذي مسارين خارج المدينة. كم مركبة مصطفّة خلفك تعني أنه يجب أن تتنحّى جانبًا في أول مكان آمن؟","o":["مركبتان","ثلاث مركبات","خمس مركبات","عشر مركبات"],"h1":"إنه عدد أصابع اليد الواحدة.","h2":"عندما تصطفّ خمس مركبات أو أكثر خلفك مباشرة على طريق ذي مسارين خارج المدينة، يجب أن تخرج من الطريق في أول مكان آمن لتسمح لها بالمرور.","p":"صحيح. خمس مركبات أو أكثر خلفك تعني أن تتنحّى جانبًا في أول مكان آمن."},"ref":{"doc":"AK","page":27}},{"id":"ak-024","scope":"AK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alaska, a school bus ahead has stopped with its red lights flashing. How far from the bus must you stop?","o":["At least 30 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"Alaska asks for more room than many states.","h2":"You must stop at least 30 feet from a school bus with flashing red lights and wait until the lights stop and the bus moves.","p":"Right. Stop at least 30 feet from the bus."},"es":{"q":"En Alaska, un autobús escolar adelante se detuvo con las luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Por lo menos a 30 pies","Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 50 pies"],"h1":"Alaska pide más espacio que muchos estados.","h2":"Usted debe detenerse por lo menos a 30 pies de un autobús escolar con luces rojas intermitentes y esperar a que se apaguen las luces y el autobús avance.","p":"Correcto. Deténgase por lo menos a 30 pies del autobús."},"zh":{"q":"在 Alaska，前面的校车停了下来，红灯在闪。你必须在离校车多远的地方停车？","o":["至少 30 英尺","至少 10 英尺","至少 20 英尺","至少 50 英尺"],"h1":"Alaska 要求的距离比很多州都大。","h2":"你必须在离红灯闪烁的校车至少 30 英尺的地方停车，等到灯停止闪烁、校车开走。","p":"对。在离校车至少 30 英尺的地方停车。"},"vi":{"q":"Ở Alaska, một xe buýt trường học phía trước đã dừng và đang nhấp nháy đèn đỏ. Bạn phải dừng cách xe buýt bao xa?","o":["Ít nhất 30 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet"],"h1":"Alaska yêu cầu khoảng cách xa hơn nhiều tiểu bang khác.","h2":"Bạn phải dừng cách xe buýt trường học đang nhấp nháy đèn đỏ ít nhất 30 feet và chờ đến khi đèn tắt và xe buýt chạy đi.","p":"Đúng. Dừng cách xe buýt ít nhất 30 feet."},"tl":{"q":"Sa Alaska, huminto ang isang school bus sa unahan na kumikislap ang pulang ilaw. Gaano kalayo mula sa bus ka dapat huminto?","o":["Hindi bababa sa 30 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet"],"h1":"Mas malaking espasyo ang hinihingi ng Alaska kaysa sa maraming estado.","h2":"Dapat kang huminto nang hindi bababa sa 30 feet mula sa school bus na kumikislap ang pulang ilaw at maghintay hanggang tumigil ang ilaw at umandar ang bus.","p":"Tama. Huminto nang hindi bababa sa 30 feet mula sa bus."},"ar":{"q":"في Alaska، حافلة مدرسية أمامك توقفت وأضواؤها الحمراء تومض. على أي بُعد من الحافلة يجب أن تتوقف؟","o":["30 feet على الأقل","10 feet على الأقل","20 feet على الأقل","50 feet على الأقل"],"h1":"تطلب Alaska مسافة أكبر من ولايات كثيرة.","h2":"يجب أن تتوقف على بُعد 30 feet على الأقل من الحافلة المدرسية التي تومض أضواؤها الحمراء، وتنتظر حتى تتوقف الأضواء وتتحرك الحافلة.","p":"صحيح. توقّف على بُعد 30 feet على الأقل من الحافلة."},"ref":{"doc":"AK","page":null}},{"id":"ak-025","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, on a road with two lanes going your way, you see a stopped police car with flashing lights. What should you do?","o":["Keep the same lane and speed","Move to the farther lane if it is safe, or else slow down","Stop next to the police car","Speed up to pass it quickly"],"h1":"Give the officer more room, or more time.","h2":"You must move away from the stopped emergency vehicle into another lane when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Alaska, en un camino con dos carriles en su dirección, usted ve un carro de policía detenido con luces intermitentes. ¿Qué debe hacer?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril más lejano si es seguro, o si no, bajar la velocidad","Detenerse al lado del carro de policía","Acelerar para pasarlo rápido"],"h1":"Déle al oficial más espacio, o más tiempo.","h2":"Usted debe alejarse del vehículo de emergencia detenido pasándose a otro carril cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Alaska，在你的方向有两条车道的道路上，你看到一辆停着的警车，车灯在闪。你应该怎么做？","o":["保持同一条车道和速度","如果安全就换到较远的车道，否则就减速","停在警车旁边","加速快点开过去"],"h1":"给警察更多空间，或者更多时间。","h2":"在安全时，你必须换到另一条车道，离停着的急救车辆远一点；如果做不到，开过去时必须减速。","p":"对。安全时就让开车道（move over），否则就减速。"},"vi":{"q":"Ở Alaska, trên đường có hai làn cùng chiều với bạn, bạn thấy một xe cảnh sát đang dừng và nhấp nháy đèn. Bạn nên làm gì?","o":["Giữ nguyên làn và tốc độ","Chuyển sang làn xa hơn nếu an toàn, nếu không thì chạy chậm lại","Dừng lại cạnh xe cảnh sát","Tăng tốc để vượt qua nhanh"],"h1":"Hãy cho cảnh sát thêm khoảng cách, hoặc thêm thời gian.","h2":"Bạn phải chuyển sang làn khác, tránh xa xe cấp cứu đang dừng, khi an toàn; nếu không thể, bạn phải chạy chậm lại khi đi qua.","p":"Đúng. Chuyển làn nếu an toàn, nếu không thì chạy chậm lại."},"tl":{"q":"Sa Alaska, sa daan na may dalawang lane papunta sa direksiyon mo, may nakita kang nakahintong police car na kumikislap ang ilaw. Ano ang dapat mong gawin?","o":["Manatili sa parehong lane at bilis","Lumipat sa mas malayong lane kung ligtas, o kung hindi ay bumagal","Huminto sa tabi ng police car","Bumilis para malampasan ito agad"],"h1":"Bigyan ang pulis ng mas maraming espasyo, o mas maraming oras.","h2":"Dapat kang lumayo sa nakahintong emergency vehicle at lumipat sa ibang lane kapag ligtas; kung hindi mo kaya, dapat kang bumagal habang dumadaan.","p":"Tama. Lumipat ng lane kung ligtas, o bumagal."},"ar":{"q":"في Alaska، على طريق فيه مساران في اتجاهك، ترى سيارة شرطة متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["ابقَ في نفس المسار وبنفس السرعة","انتقل إلى المسار الأبعد إذا كان ذلك آمنًا، وإلا فخفّف السرعة","توقّف بجانب سيارة الشرطة","زِد السرعة لتتجاوزها بسرعة"],"h1":"أعطِ الشرطي مسافة أكبر، أو وقتًا أكثر.","h2":"يجب أن تبتعد عن مركبة الطوارئ المتوقفة وتنتقل إلى مسار آخر عندما يكون ذلك آمنًا؛ وإذا لم تستطع، يجب أن تخفّف السرعة وأنت تمرّ.","p":"صحيح. انتقل إلى مسار آخر إذا كان آمنًا، أو خفّف السرعة."},"ref":{"doc":"AK","page":64}},{"id":"ak-026","scope":"AK","cat":"signals","sign":null,"c":2,"en":{"q":"In Alaska, you are stopped at a red light and want to turn right. There is no sign about turning. What may you do?","o":["Turn right without stopping","Wait for the light to turn green","Turn right after a full stop, yielding to people and traffic","Turn right only if a police officer waves you on"],"h1":"Alaska allows it, but only after you do one thing first.","h2":"You may turn right on red after you come to a full stop and yield to people walking and to other traffic, unless a sign forbids the turn.","p":"Right. Stop fully, yield, and then you may turn right on red."},"es":{"q":"En Alaska, usted está detenido en una luz roja y quiere doblar a la derecha. No hay señal sobre la vuelta. ¿Qué puede hacer?","o":["Doblar a la derecha sin detenerse","Esperar a que la luz cambie a verde","Doblar a la derecha después de un alto total, cediendo el paso a peatones y tráfico","Doblar a la derecha solo si un policía le hace señas"],"h1":"Alaska lo permite, pero solo después de hacer algo primero.","h2":"Usted puede doblar a la derecha con luz roja después de hacer un alto total y ceder el paso a los peatones y al tráfico, salvo que una señal lo prohíba.","p":"Correcto. Haga un alto total, ceda el paso y luego puede doblar a la derecha con luz roja."},"zh":{"q":"在 Alaska，你在红灯前停着，想右转。没有关于转弯的标志。你可以怎么做？","o":["不停车直接右转","等到绿灯","完全停车后右转，让行人和其他车先走","只有警察挥手让你走时才右转"],"h1":"Alaska 允许这样做，但你必须先做一件事。","h2":"你完全停车、让行人和其他车先走以后，可以在红灯时右转，除非有标志禁止。","p":"对。完全停车，让行，然后可以红灯右转。"},"vi":{"q":"Ở Alaska, bạn đang dừng ở đèn đỏ và muốn rẽ phải. Không có biển báo nào về việc rẽ. Bạn được làm gì?","o":["Rẽ phải mà không cần dừng","Chờ đèn chuyển sang xanh","Rẽ phải sau khi dừng hẳn, nhường đường cho người đi bộ và xe khác","Chỉ rẽ phải nếu cảnh sát ra hiệu cho bạn đi"],"h1":"Alaska cho phép, nhưng chỉ sau khi bạn làm một việc trước.","h2":"Bạn được rẽ phải khi đèn đỏ sau khi dừng hẳn và nhường đường cho người đi bộ và xe khác, trừ khi có biển báo cấm rẽ.","p":"Đúng. Dừng hẳn, nhường đường, rồi bạn được rẽ phải khi đèn đỏ."},"tl":{"q":"Sa Alaska, nakahinto ka sa pulang ilaw at gusto mong kumanan. Walang karatula tungkol sa pagliko. Ano ang puwede mong gawin?","o":["Kumanan nang hindi humihinto","Maghintay na maging berde ang ilaw","Kumanan pagkatapos ng buong paghinto, nagbibigay-daan sa mga tao at trapiko","Kumanan lamang kung kinawayan ka ng pulis"],"h1":"Pinapayagan ito ng Alaska, pero pagkatapos mo lamang gawin ang isang bagay muna.","h2":"Puwede kang kumanan sa pula pagkatapos mong huminto nang buo at magbigay-daan sa mga naglalakad at sa ibang trapiko, maliban kung may karatulang nagbabawal sa pagliko.","p":"Tama. Huminto nang buo, magbigay-daan, at saka ka puwedeng kumanan sa pula."},"ar":{"q":"في Alaska، أنت متوقف عند إشارة حمراء وتريد أن تنعطف يمينًا. لا توجد لافتة عن الانعطاف. ماذا يجوز لك أن تفعل؟","o":["انعطف يمينًا بدون توقف","انتظر حتى تصبح الإشارة خضراء","انعطف يمينًا بعد توقف كامل، مع إعطاء الأولوية للناس والمركبات","انعطف يمينًا فقط إذا أشار لك شرطي بالمرور"],"h1":"Alaska تسمح بذلك، لكن فقط بعد أن تفعل شيئًا واحدًا أولًا.","h2":"يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء بعد أن تتوقف توقفًا كاملًا وتعطي الأولوية للمشاة والمركبات الأخرى، إلا إذا منعت لافتة هذا الانعطاف.","p":"صحيح. توقّف تمامًا، وأعطِ الأولوية، ثم يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء."},"ref":{"doc":"AK","page":50}},{"id":"ak-027","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, what is against the law for every driver while the vehicle is moving?","o":["Reading or typing a text message","Listening to the radio","Talking with a passenger","Using the heater"],"h1":"It means taking your eyes off the road to read or write.","h2":"Alaska forbids any driver from reading or typing a text or other written message on a device while the vehicle is moving, because it pulls your eyes off the road.","p":"Right. Reading or typing texts while moving is against the law."},"es":{"q":"En Alaska, ¿qué está prohibido para todo conductor mientras el vehículo está en movimiento?","o":["Leer o escribir un mensaje de texto","Escuchar la radio","Hablar con un pasajero","Usar la calefacción"],"h1":"Se trata de quitar la vista del camino para leer o escribir.","h2":"Alaska prohíbe a todo conductor leer o escribir un texto u otro mensaje escrito en un aparato mientras el vehículo se mueve, porque le quita la vista del camino.","p":"Correcto. Leer o escribir textos en movimiento va contra la ley."},"zh":{"q":"在 Alaska，车在行驶时，对所有司机来说，什么是违法的？","o":["看或打短信","听收音机","和乘客说话","用暖气"],"h1":"它的意思是眼睛离开道路去读或写。","h2":"Alaska 禁止任何司机在车行驶时用设备看或打短信或其他文字信息，因为这会让你的眼睛离开道路。","p":"对。车在行驶时看或打短信是违法的。"},"vi":{"q":"Ở Alaska, điều gì là phạm luật với mọi người lái xe khi xe đang chạy?","o":["Đọc hoặc gõ tin nhắn","Nghe radio","Nói chuyện với hành khách","Dùng máy sưởi"],"h1":"Đó là rời mắt khỏi đường để đọc hoặc viết.","h2":"Alaska cấm mọi người lái xe đọc hoặc gõ tin nhắn hay nội dung viết khác trên thiết bị khi xe đang chạy, vì việc đó làm bạn rời mắt khỏi đường.","p":"Đúng. Đọc hoặc gõ tin nhắn khi xe đang chạy là phạm luật."},"tl":{"q":"Sa Alaska, ano ang labag sa batas para sa bawat driver habang umaandar ang sasakyan?","o":["Pagbasa o pag-type ng text message","Pakikinig sa radyo","Pakikipag-usap sa pasahero","Paggamit ng heater"],"h1":"Ibig sabihin nito ay pag-alis ng tingin sa daan para magbasa o magsulat.","h2":"Ipinagbabawal ng Alaska sa sinumang driver ang pagbasa o pag-type ng text o ibang nakasulat na mensahe sa device habang umaandar ang sasakyan, dahil inaalis nito ang tingin mo sa daan.","p":"Tama. Labag sa batas ang pagbasa o pag-type ng text habang umaandar."},"ar":{"q":"في Alaska، ما الممنوع قانونيًا على كل سائق أثناء حركة المركبة؟","o":["قراءة رسالة نصية أو كتابتها","الاستماع إلى الراديو","التحدث مع راكب","استعمال المدفأة"],"h1":"يعني أن تُبعد عينيك عن الطريق لتقرأ أو تكتب.","h2":"تمنع Alaska أي سائق من قراءة أو كتابة رسالة نصية أو أي رسالة مكتوبة أخرى على جهاز أثناء حركة المركبة، لأن ذلك يُبعد عينيك عن الطريق.","p":"صحيح. قراءة الرسائل أو كتابتها أثناء الحركة مخالفة للقانون."},"ref":{"doc":"AK","page":26}},{"id":"ak-028","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a driver age 21 or older is legally drunk at what blood alcohol level?","o":["0.10 percent or more","0.05 percent or more","0.12 percent or more","0.08 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older with a blood alcohol level of 0.08 percent or more is considered to be driving under the influence.","p":"Right. The limit for adults is 0.08 percent."},"es":{"q":"En Alaska, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.10 por ciento o más","0.05 por ciento o más","0.12 por ciento o más","0.08 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más con 0.08 por ciento o más de alcohol en la sangre se considera que maneja bajo la influencia del alcohol.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Alaska，21 岁或以上的司机，血液酒精浓度达到多少在法律上算醉酒？","o":["0.10% 或更高","0.05% 或更高","0.12% 或更高","0.08% 或更高"],"h1":"它不到百分之一的十分之一。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，就算是酒后驾驶。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Alaska, người lái xe từ 21 tuổi trở lên bị xem là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.10 phần trăm trở lên","0.05 phần trăm trở lên","0.12 phần trăm trở lên","0.08 phần trăm trở lên"],"h1":"Nó ít hơn một phần mười của một phần trăm.","h2":"Người lái xe từ 21 tuổi trở lên có nồng độ cồn trong máu từ 0.08 phần trăm trở lên bị xem là lái xe khi say (driving under the influence).","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Alaska, ang driver na 21 taong gulang o higit pa ay legal na lasing sa anong antas ng alak sa dugo?","o":["0.10 porsiyento o higit pa","0.05 porsiyento o higit pa","0.12 porsiyento o higit pa","0.08 porsiyento o higit pa"],"h1":"Ito ay mas mababa sa ikasampung bahagi ng isang porsiyento.","h2":"Ang driver na 21 o higit pa na may blood alcohol level na 0.08 porsiyento o higit pa ay itinuturing na nagmamaneho nang lasing (driving under the influence).","p":"Tama. Ang limitasyon para sa mga adult ay 0.08 porsiyento."},"ar":{"q":"في Alaska، يُعتبر السائق الذي عمره 21 سنة أو أكثر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.10 في المئة أو أكثر","0.05 في المئة أو أكثر","0.12 في المئة أو أكثر","0.08 في المئة أو أكثر"],"h1":"إنها أقل من عُشر واحد في المئة.","h2":"السائق الذي عمره 21 سنة أو أكثر ونسبة الكحول في دمه 0.08 في المئة أو أكثر يُعتبر أنه يقود تحت تأثير الكحول (driving under the influence).","p":"صحيح. الحد للبالغين هو 0.08 في المئة."},"ref":{"doc":"AK","page":16}},{"id":"ak-029","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","None that can be detected","Up to 0.05 percent","One drink per hour"],"h1":"This is called zero tolerance.","h2":"Alaska has zero tolerance for drivers under 21, so any amount of alcohol that a test can find in their body breaks the law.","p":"Right. Drivers under 21 may have no detectable alcohol."},"es":{"q":"En Alaska, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada que se pueda detectar","Hasta 0.05 por ciento","Un trago por hora"],"h1":"Esto se llama tolerancia cero.","h2":"Alaska tiene tolerancia cero para conductores menores de 21 años, así que cualquier cantidad de alcohol que una prueba encuentre en su cuerpo viola la ley.","p":"Correcto. Los menores de 21 no pueden tener alcohol detectable."},"zh":{"q":"在 Alaska，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.08%","不能有任何可以测出的酒精","最多 0.05%","每小时一杯"],"h1":"这叫做零容忍。","h2":"Alaska 对 21 岁以下的司机零容忍，所以只要检测能在他们体内测出任何酒精，就是违法。","p":"对。21 岁以下的司机不能有可以测出的酒精。"},"vi":{"q":"Ở Alaska, người lái xe dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.08 phần trăm","Không có lượng nào đo được","Tối đa 0.05 phần trăm","Một ly mỗi giờ"],"h1":"Điều này gọi là không khoan nhượng (zero tolerance).","h2":"Alaska không khoan nhượng với người lái xe dưới 21 tuổi, vì vậy bất kỳ lượng cồn nào mà xét nghiệm tìm thấy trong cơ thể họ đều là phạm luật.","p":"Đúng. Người lái xe dưới 21 tuổi không được có lượng cồn nào đo được."},"tl":{"q":"Sa Alaska, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Wala na kayang makita ng test","Hanggang 0.05 porsiyento","Isang inumin bawat oras"],"h1":"Tinatawag itong zero tolerance.","h2":"May zero tolerance ang Alaska para sa mga driver na wala pang 21, kaya ang kahit anong dami ng alak na makita ng test sa kanilang katawan ay labag sa batas.","p":"Tama. Ang mga driver na wala pang 21 ay hindi puwedeng may alak na makikita ng test."},"ar":{"q":"في Alaska، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08 في المئة","لا شيء يمكن أن يكشفه الاختبار","حتى 0.05 في المئة","مشروب واحد في الساعة"],"h1":"هذا يُسمّى عدم التسامح مطلقًا (zero tolerance).","h2":"عند Alaska عدم تسامح مطلق مع السائقين الذين عمرهم أقل من 21 سنة، لذلك أي كمية من الكحول يجدها الاختبار في أجسامهم مخالفة للقانون.","p":"صحيح. لا يجوز أن يكون لدى السائقين تحت 21 سنة أي كحول يمكن كشفه."},"ref":{"doc":"AK","page":16}},{"id":"ak-030","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what happens if a driver stopped for drunk driving refuses a breath test?","o":["Refusing is a separate crime with its own penalties","Nothing, because the test is optional","The driver gets a warning only","The driver must take a written test instead"],"h1":"By driving, you already agreed to be tested.","h2":"By driving in Alaska you have already agreed to be tested, so refusing the test is a separate crime, charged on top of drunk driving.","p":"Right. Refusing the test is a crime of its own."},"es":{"q":"En Alaska, ¿qué pasa si un conductor detenido por manejar ebrio se niega a la prueba de aliento?","o":["Negarse es un delito aparte con sus propias sanciones","Nada, porque la prueba es opcional","El conductor recibe solo una advertencia","El conductor debe hacer un examen escrito en su lugar"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"Al manejar en Alaska, usted ya aceptó hacerse la prueba, así que negarse es un delito aparte, que se suma al cargo por manejar ebrio.","p":"Correcto. Negarse a la prueba es un delito aparte."},"zh":{"q":"在 Alaska，因为酒后驾驶被拦下的司机如果拒绝呼气检测，会怎么样？","o":["拒绝本身就是另一项罪，有自己的处罚","没事，因为检测是自愿的","司机只会收到警告","司机必须改考笔试"],"h1":"你开车，就表示你已经同意接受检测。","h2":"在 Alaska 开车，就表示你已经同意接受检测，所以拒绝检测是另一项罪，会在酒后驾驶之外另外起诉。","p":"对。拒绝检测本身就是一项罪。"},"vi":{"q":"Ở Alaska, điều gì xảy ra nếu người lái xe bị dừng vì lái xe khi say từ chối thử hơi thở?","o":["Từ chối là một tội riêng với hình phạt riêng","Không có gì, vì việc thử là không bắt buộc","Người lái xe chỉ bị cảnh cáo","Người lái xe phải làm bài thi viết thay thế"],"h1":"Khi lái xe, bạn đã đồng ý cho kiểm tra.","h2":"Khi lái xe ở Alaska, bạn đã đồng ý cho kiểm tra, vì vậy từ chối thử là một tội riêng, bị truy tố thêm ngoài tội lái xe khi say.","p":"Đúng. Từ chối thử là một tội riêng."},"tl":{"q":"Sa Alaska, ano ang mangyayari kung tumanggi sa breath test ang driver na pinahinto dahil sa pagmamaneho nang lasing?","o":["Ang pagtanggi ay hiwalay na krimen na may sariling parusa","Wala, dahil hindi sapilitan ang test","Babala lamang ang ibibigay sa driver","Kailangang kumuha ang driver ng written test sa halip"],"h1":"Sa pagmamaneho, pumayag ka na na ma-test.","h2":"Sa pagmamaneho sa Alaska, pumayag ka na na ma-test, kaya ang pagtanggi sa test ay hiwalay na krimen, na isinasampa bukod pa sa pagmamaneho nang lasing.","p":"Tama. Ang pagtanggi sa test ay sariling krimen."},"ar":{"q":"في Alaska، ماذا يحدث إذا رفض سائق أُوقف بسبب القيادة تحت تأثير الكحول اختبار التنفس؟","o":["الرفض جريمة منفصلة لها عقوباتها الخاصة","لا شيء، لأن الاختبار اختياري","يحصل السائق على تحذير فقط","يجب أن يقدّم السائق اختبارًا كتابيًا بدلًا منه"],"h1":"بمجرد أن تقود، أنت وافقت مسبقًا على الاختبار.","h2":"بمجرد أن تقود في Alaska فأنت وافقت مسبقًا على الاختبار، لذلك رفض الاختبار جريمة منفصلة، تُضاف إلى تهمة القيادة تحت تأثير الكحول.","p":"صحيح. رفض الاختبار جريمة قائمة بذاتها."},"ref":{"doc":"AK","page":14}},{"id":"ak-031","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, what is the minimum liability insurance a car owner must carry?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska asks for more than many states for injuries.","h2":"Alaska requires at least $50,000 for injury to one person, $100,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Alaska minimums are 50/100/25."},"es":{"q":"En Alaska, ¿cuál es el seguro mínimo de responsabilidad que debe tener el dueño de un carro?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska pide más que muchos estados para lesiones.","h2":"Alaska exige por lo menos $50,000 por lesiones a una persona, $100,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Alaska son 50/100/25."},"zh":{"q":"在 Alaska，车主必须买的最低责任保险是多少？","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"在人身伤害方面，Alaska 要求的比很多州都多。","h2":"Alaska 要求一个人受伤至少 $50,000，一次车祸的人身伤害至少 $100,000，财产损失至少 $25,000。","p":"对。Alaska 的最低标准是 50/100/25。"},"vi":{"q":"Ở Alaska, chủ xe phải có bảo hiểm trách nhiệm (liability insurance) tối thiểu là bao nhiêu?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Alaska yêu cầu mức bảo hiểm thương tích cao hơn nhiều tiểu bang khác.","h2":"Alaska yêu cầu ít nhất $50,000 cho thương tích của một người, $100,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Alaska là 50/100/25."},"tl":{"q":"Sa Alaska, ano ang pinakamababang liability insurance na dapat mayroon ang may-ari ng kotse?","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"Mas mataas ang hinihingi ng Alaska para sa pinsala sa tao kaysa sa maraming estado.","h2":"Hinihingi ng Alaska ang hindi bababa sa $50,000 para sa pinsala sa isang tao, $100,000 para sa mga pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Alaska ay 50/100/25."},"ar":{"q":"في Alaska، ما الحد الأدنى من تأمين المسؤولية (liability insurance) الذي يجب أن يملكه صاحب السيارة؟","o":["$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"تطلب Alaska مبلغًا للإصابات أكبر من ولايات كثيرة.","h2":"تطلب Alaska على الأقل $50,000 لإصابة شخص واحد، و$100,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Alaska هو 50/100/25."},"ref":{"doc":"AK","page":10}},{"id":"ak-032","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many points within 12 months lead to a required suspension of your license?","o":["6 points","8 points","12 points","15 points"],"h1":"Over 24 months the limit is higher than over 12 months.","h2":"In Alaska, 12 points in 12 months, or 18 points in 24 months, means your license must be suspended or revoked.","p":"Right. 12 points in 12 months brings a required suspension."},"es":{"q":"En Alaska, ¿cuántos puntos en 12 meses llevan a una suspensión obligatoria de su licencia?","o":["6 puntos","8 puntos","12 puntos","15 puntos"],"h1":"En 24 meses el límite es más alto que en 12 meses.","h2":"En Alaska, 12 puntos en 12 meses, o 18 puntos en 24 meses, significa que su licencia debe ser suspendida o revocada.","p":"Correcto. 12 puntos en 12 meses llevan a una suspensión obligatoria."},"zh":{"q":"在 Alaska，12 个月内累计多少分会导致你的驾照必须被暂停？","o":["6 分","8 分","12 分","15 分"],"h1":"24 个月内的上限比 12 个月内的高。","h2":"在 Alaska，12 个月内累计 12 分，或 24 个月内累计 18 分，你的驾照就必须被暂停或吊销。","p":"对。12 个月内累计 12 分，驾照必须被暂停。"},"vi":{"q":"Ở Alaska, bao nhiêu điểm trong 12 tháng sẽ khiến bằng lái của bạn bắt buộc bị đình chỉ?","o":["6 điểm","8 điểm","12 điểm","15 điểm"],"h1":"Trong 24 tháng, mức giới hạn cao hơn trong 12 tháng.","h2":"Ở Alaska, 12 điểm trong 12 tháng, hoặc 18 điểm trong 24 tháng, có nghĩa là bằng lái của bạn phải bị đình chỉ hoặc thu hồi.","p":"Đúng. 12 điểm trong 12 tháng dẫn đến việc bắt buộc đình chỉ bằng lái."},"tl":{"q":"Sa Alaska, ilang puntos sa loob ng 12 buwan ang magdudulot ng sapilitang suspensiyon ng iyong lisensiya?","o":["6 puntos","8 puntos","12 puntos","15 puntos"],"h1":"Sa loob ng 24 buwan, mas mataas ang limitasyon kaysa sa loob ng 12 buwan.","h2":"Sa Alaska, ang 12 puntos sa loob ng 12 buwan, o 18 puntos sa loob ng 24 buwan, ay nangangahulugang dapat suspindihin o bawiin ang iyong lisensiya.","p":"Tama. Ang 12 puntos sa loob ng 12 buwan ay nagdudulot ng sapilitang suspensiyon."},"ar":{"q":"في Alaska، كم نقطة خلال 12 شهرًا تؤدي إلى تعليق رخصتك بشكل إلزامي؟","o":["6 نقاط","8 نقاط","12 نقطة","15 نقطة"],"h1":"الحد خلال 24 شهرًا أعلى من الحد خلال 12 شهرًا.","h2":"في Alaska، 12 نقطة خلال 12 شهرًا، أو 18 نقطة خلال 24 شهرًا، تعني أنه يجب تعليق رخصتك أو إلغاؤها.","p":"صحيح. 12 نقطة خلال 12 شهرًا تؤدي إلى تعليق إلزامي."},"ref":{"doc":"AK","page":11}},{"id":"ak-033","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a driver with a provisional license gets 6 points in 12 months. What must the driver do?","o":["Complete a driver improvement course","Retake the vision test","Pay a $500 fine","Start a new instruction permit"],"h1":"The goal is to help the young driver build better habits.","h2":"In Alaska, a provisional driver with 6 or more points in 12 months, or 9 or more in 24 months, must complete a driver improvement course approved by the DMV.","p":"Right. The provisional driver must take a driver improvement course."},"es":{"q":"En Alaska, un conductor con licencia provisional acumula 6 puntos en 12 meses. ¿Qué debe hacer?","o":["Completar un curso para mejorar su manejo","Repetir el examen de la vista","Pagar una multa de $500","Empezar con un nuevo permiso de aprendizaje"],"h1":"La meta es ayudar al conductor joven a formar mejores hábitos.","h2":"En Alaska, un conductor provisional con 6 puntos o más en 12 meses, o 9 o más en 24 meses, debe completar un curso para mejorar su manejo aprobado por el DMV.","p":"Correcto. El conductor provisional debe tomar un curso para mejorar su manejo."},"zh":{"q":"在 Alaska，一位持过渡驾照的司机在 12 个月内被记了 6 分。这位司机必须做什么？","o":["完成一门驾驶改进课程","重新做视力检查","交 $500 罚款","重新开始一个学习驾照"],"h1":"目的是帮助年轻司机养成更好的习惯。","h2":"在 Alaska，持过渡驾照的司机如果 12 个月内被记 6 分或更多，或 24 个月内被记 9 分或更多，就必须完成一门 DMV 批准的驾驶改进课程。","p":"对。持过渡驾照的司机必须上驾驶改进课程。"},"vi":{"q":"Ở Alaska, một người lái xe có bằng lái tạm thời bị 6 điểm trong 12 tháng. Người đó phải làm gì?","o":["Hoàn thành một khóa học cải thiện cách lái xe","Thi lại phần kiểm tra thị lực","Trả tiền phạt $500","Bắt đầu lại với một giấy phép tập lái mới"],"h1":"Mục đích là giúp người lái trẻ tập thói quen tốt hơn.","h2":"Ở Alaska, người có bằng lái tạm thời bị từ 6 điểm trở lên trong 12 tháng, hoặc từ 9 điểm trở lên trong 24 tháng, phải hoàn thành một khóa học cải thiện cách lái xe được DMV chấp thuận.","p":"Đúng. Người có bằng lái tạm thời phải học một khóa cải thiện cách lái xe."},"tl":{"q":"Sa Alaska, ang isang driver na may provisional license ay nakakuha ng 6 na puntos sa loob ng 12 buwan. Ano ang dapat gawin ng driver?","o":["Tapusin ang isang driver improvement course","Ulitin ang vision test","Magbayad ng $500 na multa","Magsimula ng bagong instruction permit"],"h1":"Ang layunin ay tulungan ang batang driver na magkaroon ng mas mabuting gawi.","h2":"Sa Alaska, ang provisional driver na may 6 o higit pang puntos sa loob ng 12 buwan, o 9 o higit pa sa loob ng 24 buwan, ay dapat tumapos ng driver improvement course na aprubado ng DMV.","p":"Tama. Dapat kumuha ang provisional driver ng driver improvement course."},"ar":{"q":"في Alaska، سائق لديه رخصة مؤقتة حصل على 6 نقاط خلال 12 شهرًا. ماذا يجب على السائق أن يفعل؟","o":["أن يُكمل دورة لتحسين القيادة","أن يعيد فحص النظر","أن يدفع غرامة $500","أن يبدأ تصريح تعلّم جديدًا"],"h1":"الهدف هو مساعدة السائق الشاب على بناء عادات أفضل.","h2":"في Alaska، السائق صاحب الرخصة المؤقتة الذي لديه 6 نقاط أو أكثر خلال 12 شهرًا، أو 9 نقاط أو أكثر خلال 24 شهرًا، يجب أن يُكمل دورة لتحسين القيادة يوافق عليها DMV.","p":"صحيح. يجب على صاحب الرخصة المؤقتة أن يأخذ دورة لتحسين القيادة."},"ref":{"doc":"AK","page":11}},{"id":"ak-034","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, how many points are added to your record for driving 10 to 19 mph over the speed limit?","o":["2 points","3 points","6 points","4 points"],"h1":"It is more than for 3 to 9 mph over, and less than for 20 mph or more over.","h2":"In Alaska, driving 10 to 19 mph over the speed limit adds 4 points to your driving record.","p":"Right. 10 to 19 mph over the limit is 4 points."},"es":{"q":"En Alaska, ¿cuántos puntos se agregan a su historial por manejar de 10 a 19 mph sobre el límite de velocidad?","o":["2 puntos","3 puntos","6 puntos","4 puntos"],"h1":"Es más que por ir de 3 a 9 mph sobre el límite, y menos que por ir 20 mph o más.","h2":"En Alaska, manejar de 10 a 19 mph sobre el límite de velocidad agrega 4 puntos a su historial de manejo.","p":"Correcto. De 10 a 19 mph sobre el límite son 4 puntos."},"zh":{"q":"在 Alaska，超速 10 到 19 mph 会在你的记录上记几分？","o":["2 分","3 分","6 分","4 分"],"h1":"它比超速 3 到 9 mph 多，比超速 20 mph 或以上少。","h2":"在 Alaska，超过限速 10 到 19 mph 会在你的驾驶记录上记 4 分。","p":"对。超过限速 10 到 19 mph 记 4 分。"},"vi":{"q":"Ở Alaska, lái xe vượt quá giới hạn tốc độ từ 10 đến 19 mph sẽ bị ghi bao nhiêu điểm vào hồ sơ của bạn?","o":["2 điểm","3 điểm","6 điểm","4 điểm"],"h1":"Nhiều hơn khi vượt 3 đến 9 mph, và ít hơn khi vượt từ 20 mph trở lên.","h2":"Ở Alaska, lái xe vượt quá giới hạn tốc độ từ 10 đến 19 mph bị ghi 4 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Vượt quá giới hạn 10 đến 19 mph là 4 điểm."},"tl":{"q":"Sa Alaska, ilang puntos ang idinadagdag sa iyong record kapag nagmaneho ka nang 10 hanggang 19 mph na lampas sa speed limit?","o":["2 puntos","3 puntos","6 na puntos","4 na puntos"],"h1":"Mas marami ito kaysa sa 3 hanggang 9 mph na lampas, at mas kaunti kaysa sa 20 mph o higit pang lampas.","h2":"Sa Alaska, ang pagmamaneho nang 10 hanggang 19 mph na lampas sa speed limit ay nagdadagdag ng 4 na puntos sa iyong driving record.","p":"Tama. Ang 10 hanggang 19 mph na lampas sa limitasyon ay 4 na puntos."},"ar":{"q":"في Alaska، كم نقطة تُضاف إلى سجلك إذا قُدت بسرعة تزيد من 10 إلى 19 mph عن حد السرعة؟","o":["نقطتان (2)","3 نقاط","6 نقاط","4 نقاط"],"h1":"هي أكثر من زيادة 3 إلى 9 mph، وأقل من زيادة 20 mph أو أكثر.","h2":"في Alaska، القيادة بسرعة تزيد من 10 إلى 19 mph عن حد السرعة تضيف 4 نقاط إلى سجل قيادتك.","p":"صحيح. الزيادة من 10 إلى 19 mph عن الحد تعني 4 نقاط."},"ref":{"doc":"AK","page":12}},{"id":"ak-035","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, no police officer investigated your crash. How soon must you report it to the DMV?","o":["Within 24 hours","Within 10 days","Within 30 days","Within 6 months"],"h1":"You can send the report online or by mail.","h2":"In Alaska, if a police officer did not investigate your crash, you must report it to the DMV within 10 days.","p":"Right. Report the crash to the DMV within 10 days."},"es":{"q":"En Alaska, ningún policía investigó su choque. ¿En cuánto tiempo debe reportarlo al DMV?","o":["En 24 horas","En 10 días","En 30 días","En 6 meses"],"h1":"Puede enviar el reporte por internet o por correo.","h2":"En Alaska, si un policía no investigó su choque, usted debe reportarlo al DMV en un plazo de 10 días.","p":"Correcto. Reporte el choque al DMV en 10 días."},"zh":{"q":"在 Alaska，没有警察调查你的车祸。你必须在多长时间内向 DMV 报告？","o":["24 小时内","10 天内","30 天内","6 个月内"],"h1":"你可以在网上或通过邮寄提交报告。","h2":"在 Alaska，如果没有警察调查你的车祸，你必须在 10 天内向 DMV 报告。","p":"对。在 10 天内向 DMV 报告车祸。"},"vi":{"q":"Ở Alaska, không có cảnh sát nào điều tra vụ tai nạn của bạn. Bạn phải báo cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 6 tháng"],"h1":"Bạn có thể gửi bản báo cáo qua mạng hoặc qua bưu điện.","h2":"Ở Alaska, nếu cảnh sát không điều tra vụ tai nạn của bạn, bạn phải báo cho DMV trong vòng 10 ngày.","p":"Đúng. Báo vụ tai nạn cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa Alaska, walang pulis na nag-imbestiga sa iyong banggaan. Gaano kabilis mo ito dapat i-report sa DMV?","o":["Sa loob ng 24 oras","Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 6 na buwan"],"h1":"Puwede mong ipadala ang report online o sa koreo.","h2":"Sa Alaska, kung walang pulis na nag-imbestiga sa iyong banggaan, dapat mo itong i-report sa DMV sa loob ng 10 araw.","p":"Tama. I-report ang banggaan sa DMV sa loob ng 10 araw."},"ar":{"q":"في Alaska، لم يحقق أي شرطي في حادث اصطدامك. خلال كم من الوقت يجب أن تُبلغ DMV عنه؟","o":["خلال 24 ساعة","خلال 10 أيام","خلال 30 يومًا","خلال 6 أشهر"],"h1":"يمكنك إرسال البلاغ عبر الإنترنت أو بالبريد.","h2":"في Alaska، إذا لم يحقق شرطي في حادث اصطدامك، يجب أن تُبلغ DMV عنه خلال 10 أيام.","p":"صحيح. أبلغ DMV عن الحادث خلال 10 أيام."},"ref":{"doc":"AK","page":11}},{"id":"ak-036","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, after a crash where someone was hurt, how many days do you have to give the DMV proof of insurance?","o":["3 days","7 days","15 days","60 days"],"h1":"Every driver in the crash must send it, even the one who did not cause it.","h2":"In Alaska, after a crash with an injury, every driver involved must give the DMV proof of insurance within 15 days.","p":"Right. Every driver must send proof of insurance within 15 days."},"es":{"q":"En Alaska, después de un choque donde alguien resultó herido, ¿cuántos días tiene para dar al DMV prueba de seguro?","o":["3 días","7 días","15 días","60 días"],"h1":"Cada conductor del choque debe enviarla, aunque no haya causado el choque.","h2":"En Alaska, después de un choque con heridos, cada conductor involucrado debe dar al DMV prueba de seguro en un plazo de 15 días.","p":"Correcto. Cada conductor debe enviar prueba de seguro en 15 días."},"zh":{"q":"在 Alaska，发生有人受伤的车祸后，你有几天时间向 DMV 提供保险证明？","o":["3 天","7 天","15 天","60 天"],"h1":"车祸中的每位司机都必须提交，即使不是他造成车祸。","h2":"在 Alaska，发生有人受伤的车祸后，每位涉及的司机都必须在 15 天内向 DMV 提供保险证明。","p":"对。每位司机都必须在 15 天内提交保险证明。"},"vi":{"q":"Ở Alaska, sau một vụ tai nạn có người bị thương, bạn có bao nhiêu ngày để nộp bằng chứng bảo hiểm cho DMV?","o":["3 ngày","7 ngày","15 ngày","60 ngày"],"h1":"Mọi người lái xe trong vụ tai nạn đều phải nộp, kể cả người không gây ra tai nạn.","h2":"Ở Alaska, sau một vụ tai nạn có người bị thương, mọi người lái xe liên quan phải nộp bằng chứng bảo hiểm cho DMV trong vòng 15 ngày.","p":"Đúng. Mọi người lái xe phải nộp bằng chứng bảo hiểm trong vòng 15 ngày."},"tl":{"q":"Sa Alaska, pagkatapos ng banggaan kung saan may nasaktan, ilang araw ka mayroon para magbigay sa DMV ng patunay ng insurance?","o":["3 araw","7 araw","15 araw","60 araw"],"h1":"Dapat itong ipadala ng bawat driver sa banggaan, kahit ang hindi nagdulot nito.","h2":"Sa Alaska, pagkatapos ng banggaan na may nasaktan, dapat magbigay ang bawat driver na kasangkot ng patunay ng insurance sa DMV sa loob ng 15 araw.","p":"Tama. Dapat magpadala ang bawat driver ng patunay ng insurance sa loob ng 15 araw."},"ar":{"q":"في Alaska، بعد حادث اصطدام أُصيب فيه شخص، كم يومًا لديك لتقديم إثبات التأمين إلى DMV؟","o":["3 أيام","7 أيام","15 يومًا","60 يومًا"],"h1":"يجب على كل سائق في الحادث أن يرسله، حتى السائق الذي لم يتسبب فيه.","h2":"في Alaska، بعد حادث اصطدام فيه إصابة، يجب على كل سائق مشارك أن يقدّم إثبات التأمين إلى DMV خلال 15 يومًا.","p":"صحيح. يجب على كل سائق أن يرسل إثبات التأمين خلال 15 يومًا."},"ref":{"doc":"AK","page":10}},{"id":"ak-037","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, you had no insurance when you were in a crash. For a first time, how long is your license suspended?","o":["30 days","1 year","3 years","90 days"],"h1":"A second time brings a longer suspension.","h2":"In Alaska, a driver who was uninsured in a crash has the license suspended for 90 days the first time and 1 year the second time.","p":"Right. The first time, the suspension is 90 days."},"es":{"q":"En Alaska, usted no tenía seguro cuando tuvo un choque. Si es la primera vez, ¿por cuánto tiempo suspenden su licencia?","o":["30 días","1 año","3 años","90 días"],"h1":"Una segunda vez trae una suspensión más larga.","h2":"En Alaska, a un conductor sin seguro en un choque le suspenden la licencia por 90 días la primera vez y por 1 año la segunda vez.","p":"Correcto. La primera vez, la suspensión es de 90 días."},"zh":{"q":"在 Alaska，你发生车祸时没有保险。如果是第一次，你的驾照会被暂停多久？","o":["30 天","1 年","3 年","90 天"],"h1":"第二次的暂停时间更长。","h2":"在 Alaska，车祸时没有保险的司机，第一次驾照会被暂停 90 天，第二次会被暂停 1 年。","p":"对。第一次的暂停时间是 90 天。"},"vi":{"q":"Ở Alaska, bạn không có bảo hiểm khi bị tai nạn. Nếu là lần đầu, bằng lái của bạn bị đình chỉ bao lâu?","o":["30 ngày","1 năm","3 năm","90 ngày"],"h1":"Lần thứ hai sẽ bị đình chỉ lâu hơn.","h2":"Ở Alaska, người lái xe không có bảo hiểm khi bị tai nạn sẽ bị đình chỉ bằng lái 90 ngày ở lần đầu và 1 năm ở lần thứ hai.","p":"Đúng. Lần đầu, bằng lái bị đình chỉ 90 ngày."},"tl":{"q":"Sa Alaska, wala kang insurance nang ikaw ay nabangga. Kung unang beses ito, gaano katagal masususpindi ang iyong lisensiya?","o":["30 araw","1 taon","3 taon","90 araw"],"h1":"Mas mahabang suspensiyon ang ikalawang beses.","h2":"Sa Alaska, ang driver na walang insurance sa isang banggaan ay masususpindi ang lisensiya nang 90 araw sa unang beses at 1 taon sa ikalawang beses.","p":"Tama. Sa unang beses, ang suspensiyon ay 90 araw."},"ar":{"q":"في Alaska، لم يكن لديك تأمين عندما وقع لك حادث اصطدام. إذا كانت هذه المرة الأولى، كم من الوقت تُعلَّق رخصتك؟","o":["30 يومًا","سنة واحدة (1)","3 سنوات","90 يومًا"],"h1":"المرة الثانية تؤدي إلى تعليق أطول.","h2":"في Alaska، السائق الذي لم يكن لديه تأمين في حادث اصطدام تُعلَّق رخصته 90 يومًا في المرة الأولى وسنة واحدة (1) في المرة الثانية.","p":"صحيح. في المرة الأولى، مدة التعليق 90 يومًا."},"ref":{"doc":"AK","page":10}},{"id":"ak-038","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a driver with no past DUI is arrested and the breath test shows 0.08 or more. How long will the DMV revoke the license?","o":["90 days","30 days","3 years","5 years"],"h1":"The longer periods are for drivers with earlier DUI or refusal convictions.","h2":"In Alaska, the DMV revokes the license for 90 days for a first offense when a driver tests at 0.08 or more or refuses the test.","p":"Right. A first offense means a 90-day revocation by the DMV."},"es":{"q":"En Alaska, arrestan a un conductor sin DUI anteriores y la prueba de aliento muestra 0.08 o más. ¿Por cuánto tiempo revocará el DMV su licencia?","o":["90 días","30 días","3 años","5 años"],"h1":"Los periodos más largos son para conductores con condenas anteriores por DUI o por negarse a la prueba.","h2":"En Alaska, el DMV revoca la licencia por 90 días en una primera ofensa cuando el conductor marca 0.08 o más o se niega a la prueba.","p":"Correcto. Una primera ofensa significa que el DMV revoca la licencia por 90 días."},"zh":{"q":"在 Alaska，一位以前没有酒驾（DUI）记录的司机被逮捕，呼气测试结果是 0.08 或更高。DMV 会吊销驾照多久？","o":["90 天","30 天","3 年","5 年"],"h1":"较长的期限是给以前有酒驾或拒绝测试定罪的司机。","h2":"在 Alaska，司机第一次违法时，如果测试结果是 0.08 或更高，或者拒绝测试，DMV 会吊销驾照 90 天。","p":"对。第一次违法，DMV 会吊销驾照 90 天。"},"vi":{"q":"Ở Alaska, một người lái xe chưa từng bị DUI bị bắt và kết quả thử hơi thở là 0.08 trở lên. DMV sẽ thu hồi bằng lái trong bao lâu?","o":["90 ngày","30 ngày","3 năm","5 năm"],"h1":"Thời gian dài hơn dành cho người lái xe đã từng bị kết án DUI hoặc từ chối thử nghiệm.","h2":"Ở Alaska, DMV thu hồi bằng lái 90 ngày cho lần vi phạm đầu tiên khi người lái xe có kết quả 0.08 trở lên hoặc từ chối thử nghiệm.","p":"Đúng. Lần vi phạm đầu tiên có nghĩa là DMV thu hồi bằng lái 90 ngày."},"tl":{"q":"Sa Alaska, inaresto ang isang driver na walang naunang DUI at ang breath test ay nagpakita ng 0.08 o higit pa. Gaano katagal babawiin ng DMV ang lisensiya?","o":["90 araw","30 araw","3 taon","5 taon"],"h1":"Ang mas mahahabang panahon ay para sa mga driver na may naunang conviction sa DUI o sa pagtanggi sa test.","h2":"Sa Alaska, binabawi ng DMV ang lisensiya nang 90 araw sa unang paglabag kapag ang driver ay may resultang 0.08 o higit pa o tumanggi sa test.","p":"Tama. Ang unang paglabag ay nangangahulugang 90 araw na pagbawi ng DMV sa lisensiya."},"ar":{"q":"في Alaska، اعتُقل سائق ليس لديه DUI سابق، وأظهر اختبار التنفّس 0.08 أو أكثر. كم من الوقت سيُلغي DMV رخصته؟","o":["90 يومًا","30 يومًا","3 سنوات","5 سنوات"],"h1":"المدد الأطول هي للسائقين الذين أُدينوا من قبل بـ DUI أو برفض الاختبار.","h2":"في Alaska، يُلغي DMV الرخصة لمدة 90 يومًا في المخالفة الأولى عندما تكون نتيجة السائق 0.08 أو أكثر أو عندما يرفض الاختبار.","p":"صحيح. المخالفة الأولى تعني أن DMV يُلغي الرخصة لمدة 90 يومًا."},"ref":{"doc":"AK","page":16}},{"id":"ak-039","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, a driver under 21 is caught driving after drinking alcohol. For a first offense, how long does the DMV revoke the license?","o":["7 days","30 days","2 years","5 years"],"h1":"The period gets longer with each new offense.","h2":"In Alaska, a driver under 21 who drives after drinking any alcohol loses the license for 30 days for a first offense, even if the court case is dropped.","p":"Right. A first offense means a 30-day revocation."},"es":{"q":"En Alaska, encuentran a un conductor menor de 21 años manejando después de tomar alcohol. En una primera ofensa, ¿por cuánto tiempo revoca el DMV su licencia?","o":["7 días","30 días","2 años","5 años"],"h1":"El periodo se alarga con cada nueva ofensa.","h2":"En Alaska, un conductor menor de 21 años que maneja después de tomar cualquier cantidad de alcohol pierde la licencia por 30 días en una primera ofensa, aunque se cierre el caso en la corte.","p":"Correcto. Una primera ofensa significa una revocación de 30 días."},"zh":{"q":"在 Alaska，一位未满 21 岁的司机被发现喝酒后开车。如果是第一次违法，DMV 会吊销驾照多久？","o":["7 天","30 天","2 年","5 年"],"h1":"每多一次违法，期限就会更长。","h2":"在 Alaska，未满 21 岁的司机只要喝了任何酒后开车，第一次违法就会失去驾照 30 天，即使法院的案子被撤销也一样。","p":"对。第一次违法会被吊销驾照 30 天。"},"vi":{"q":"Ở Alaska, một người lái xe dưới 21 tuổi bị phát hiện lái xe sau khi uống rượu bia. Với lần vi phạm đầu tiên, DMV thu hồi bằng lái bao lâu?","o":["7 ngày","30 ngày","2 năm","5 năm"],"h1":"Thời gian sẽ dài hơn với mỗi lần vi phạm mới.","h2":"Ở Alaska, người lái xe dưới 21 tuổi lái xe sau khi uống bất kỳ lượng rượu bia nào sẽ mất bằng lái 30 ngày cho lần vi phạm đầu tiên, kể cả khi vụ án ở tòa bị hủy bỏ.","p":"Đúng. Lần vi phạm đầu tiên có nghĩa là bị thu hồi bằng lái 30 ngày."},"tl":{"q":"Sa Alaska, nahuli ang isang driver na wala pang 21 na nagmamaneho pagkatapos uminom ng alak. Sa unang paglabag, gaano katagal babawiin ng DMV ang lisensiya?","o":["7 araw","30 araw","2 taon","5 taon"],"h1":"Humahaba ang panahon sa bawat bagong paglabag.","h2":"Sa Alaska, ang driver na wala pang 21 na nagmamaneho pagkatapos uminom ng kahit anong dami ng alak ay mawawalan ng lisensiya nang 30 araw sa unang paglabag, kahit ibasura ang kaso sa korte.","p":"Tama. Ang unang paglabag ay nangangahulugang 30 araw na pagbawi ng lisensiya."},"ar":{"q":"في Alaska، ضُبط سائق عمره أقل من 21 سنة يقود بعد أن شرب الكحول. في المخالفة الأولى، كم من الوقت يُلغي DMV رخصته؟","o":["7 أيام","30 يومًا","سنتان (2)","5 سنوات"],"h1":"تطول المدة مع كل مخالفة جديدة.","h2":"في Alaska، السائق الذي عمره أقل من 21 سنة ويقود بعد شرب أي كمية من الكحول يفقد رخصته لمدة 30 يومًا في المخالفة الأولى، حتى لو أُسقطت القضية في المحكمة.","p":"صحيح. المخالفة الأولى تعني إلغاء الرخصة لمدة 30 يومًا."},"ref":{"doc":"AK","page":16}},{"id":"ak-040","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, after a first DUI conviction, how long must an ignition interlock device be on any vehicle you drive?","o":["1 month","3 months","At least 6 months","10 years"],"h1":"The time grows with each extra conviction.","h2":"In Alaska, after a first DUI or refusal conviction, you must use an ignition interlock device on any vehicle you drive for at least 6 months.","p":"Right. A first conviction means at least 6 months with the device."},"es":{"q":"En Alaska, después de una primera condena por DUI, ¿por cuánto tiempo debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje?","o":["1 mes","3 meses","Por lo menos 6 meses","10 años"],"h1":"El tiempo aumenta con cada condena adicional.","h2":"En Alaska, después de una primera condena por DUI o por negarse a la prueba, debe usar un dispositivo de bloqueo de encendido en cualquier vehículo que maneje por lo menos 6 meses.","p":"Correcto. Una primera condena significa por lo menos 6 meses con el dispositivo."},"zh":{"q":"在 Alaska，第一次被判酒驾（DUI）后，你开的任何车辆都必须安装点火联锁装置多长时间？","o":["1 个月","3 个月","至少 6 个月","10 年"],"h1":"每多一次定罪，时间就会更长。","h2":"在 Alaska，第一次因酒驾或拒绝测试被定罪后，你开的任何车辆都必须使用点火联锁装置至少 6 个月。","p":"对。第一次定罪意味着至少 6 个月要使用这个装置。"},"vi":{"q":"Ở Alaska, sau lần đầu bị kết án DUI, bạn phải có thiết bị khóa khởi động (ignition interlock) trên bất kỳ xe nào bạn lái trong bao lâu?","o":["1 tháng","3 tháng","Ít nhất 6 tháng","10 năm"],"h1":"Thời gian tăng lên với mỗi lần bị kết án thêm.","h2":"Ở Alaska, sau lần đầu bị kết án DUI hoặc từ chối thử nghiệm, bạn phải dùng thiết bị khóa khởi động trên bất kỳ xe nào bạn lái trong ít nhất 6 tháng.","p":"Đúng. Lần đầu bị kết án có nghĩa là ít nhất 6 tháng dùng thiết bị này."},"tl":{"q":"Sa Alaska, pagkatapos ng unang conviction sa DUI, gaano katagal dapat may ignition interlock device ang anumang sasakyang minamaneho mo?","o":["1 buwan","3 buwan","Hindi bababa sa 6 na buwan","10 taon"],"h1":"Humahaba ang panahon sa bawat dagdag na conviction.","h2":"Sa Alaska, pagkatapos ng unang conviction sa DUI o sa pagtanggi sa test, dapat kang gumamit ng ignition interlock device sa anumang sasakyang minamaneho mo nang hindi bababa sa 6 na buwan.","p":"Tama. Ang unang conviction ay nangangahulugang hindi bababa sa 6 na buwan na may device."},"ar":{"q":"في Alaska، بعد الإدانة الأولى بـ DUI، كم من الوقت يجب أن يكون جهاز قفل التشغيل (ignition interlock) في أي مركبة تقودها؟","o":["شهر واحد (1)","3 أشهر","6 أشهر على الأقل","10 سنوات"],"h1":"تزيد المدة مع كل إدانة إضافية.","h2":"في Alaska، بعد الإدانة الأولى بـ DUI أو برفض الاختبار، يجب أن تستخدم جهاز قفل التشغيل في أي مركبة تقودها لمدة 6 أشهر على الأقل.","p":"صحيح. الإدانة الأولى تعني 6 أشهر على الأقل مع الجهاز."},"ref":{"doc":"AK","page":19}},{"id":"ak-041","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, if you get your driver license before age 21, when does it expire?","o":["On your 18th birthday","One year after you get it","On your 25th birthday","90 days after your 21st birthday"],"h1":"It is tied to the age when you may legally drink.","h2":"In Alaska, a license issued to someone under 21 expires 90 days after the 21st birthday, and you must pass an alcohol awareness test to renew it.","p":"Right. It expires 90 days after your 21st birthday."},"es":{"q":"En Alaska, si obtiene su licencia de manejar antes de los 21 años, ¿cuándo vence?","o":["El día que cumple 18 años","Un año después de recibirla","El día que cumple 25 años","90 días después de cumplir 21 años"],"h1":"Está ligado a la edad en que se puede tomar alcohol legalmente.","h2":"En Alaska, una licencia dada a alguien menor de 21 años vence 90 días después de cumplir 21, y para renovarla debe pasar un examen sobre el alcohol.","p":"Correcto. Vence 90 días después de cumplir 21 años."},"zh":{"q":"在 Alaska，如果你在 21 岁以前拿到驾照，它什么时候到期？","o":["在你 18 岁生日那天","拿到驾照一年后","在你 25 岁生日那天","在你 21 岁生日后 90 天"],"h1":"它和可以合法喝酒的年龄有关。","h2":"在 Alaska，发给未满 21 岁的人的驾照在 21 岁生日后 90 天到期，而且你必须通过一个关于酒精的测试才能更新。","p":"对。它在你 21 岁生日后 90 天到期。"},"vi":{"q":"Ở Alaska, nếu bạn có bằng lái trước 21 tuổi, bằng lái đó hết hạn khi nào?","o":["Vào sinh nhật 18 tuổi của bạn","Một năm sau khi bạn nhận bằng","Vào sinh nhật 25 tuổi của bạn","90 ngày sau sinh nhật 21 tuổi của bạn"],"h1":"Nó liên quan đến tuổi được phép uống rượu bia hợp pháp.","h2":"Ở Alaska, bằng lái cấp cho người dưới 21 tuổi hết hạn 90 ngày sau sinh nhật 21 tuổi, và bạn phải đậu một bài kiểm tra hiểu biết về rượu bia để gia hạn.","p":"Đúng. Bằng lái hết hạn 90 ngày sau sinh nhật 21 tuổi của bạn."},"tl":{"q":"Sa Alaska, kung nakuha mo ang iyong driver license bago ka mag-21, kailan ito mag-e-expire?","o":["Sa iyong ika-18 kaarawan","Isang taon pagkatapos mo itong makuha","Sa iyong ika-25 kaarawan","90 araw pagkatapos ng iyong ika-21 kaarawan"],"h1":"Konektado ito sa edad kung kailan legal kang puwedeng uminom ng alak.","h2":"Sa Alaska, ang lisensiyang ibinigay sa taong wala pang 21 ay mag-e-expire 90 araw pagkatapos ng ika-21 kaarawan, at dapat kang pumasa sa isang alcohol awareness test para i-renew ito.","p":"Tama. Mag-e-expire ito 90 araw pagkatapos ng iyong ika-21 kaarawan."},"ar":{"q":"في Alaska، إذا حصلت على رخصة القيادة قبل سن 21، متى تنتهي صلاحيتها؟","o":["في عيد ميلادك الثامن عشر (18)","بعد سنة من حصولك عليها","في عيد ميلادك الخامس والعشرين (25)","بعد 90 يومًا من عيد ميلادك الحادي والعشرين (21)"],"h1":"إنها مرتبطة بالسن الذي يُسمح فيه قانونيًا بشرب الكحول.","h2":"في Alaska، الرخصة التي تُعطى لشخص عمره أقل من 21 سنة تنتهي بعد 90 يومًا من عيد ميلاده الحادي والعشرين (21)، ويجب أن تنجح في اختبار عن الكحول لتجديدها.","p":"صحيح. تنتهي بعد 90 يومًا من عيد ميلادك الحادي والعشرين (21)."},"ref":{"doc":"AK","page":5}},{"id":"ak-042","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what is the minimum vision needed for a license, in each eye or with both eyes together?","o":["20/40","20/80","20/100","20/200"],"h1":"You may wear glasses or contact lenses to reach it.","h2":"In Alaska, you need at least 20/40 vision in each eye or with both eyes together, and if you need lenses to pass, you must wear them when you drive.","p":"Right. The standard is 20/40."},"es":{"q":"En Alaska, ¿cuál es la vista mínima para tener licencia, en cada ojo o con los dos ojos juntos?","o":["20/40","20/80","20/100","20/200"],"h1":"Puede usar lentes o lentes de contacto para lograrla.","h2":"En Alaska, necesita por lo menos una vista de 20/40 en cada ojo o con los dos ojos juntos, y si necesita lentes para pasar, debe usarlos al manejar.","p":"Correcto. El mínimo es 20/40."},"zh":{"q":"在 Alaska，拿驾照最低需要多好的视力（每只眼睛或两只眼睛一起）？","o":["20/40","20/80","20/100","20/200"],"h1":"你可以戴眼镜或隐形眼镜来达到这个标准。","h2":"在 Alaska，你每只眼睛或两只眼睛一起的视力至少要 20/40；如果你需要戴镜片才能通过，开车时就必须戴着。","p":"对。标准是 20/40。"},"vi":{"q":"Ở Alaska, thị lực tối thiểu để có bằng lái là bao nhiêu, ở mỗi mắt hoặc cả hai mắt cùng nhau?","o":["20/40","20/80","20/100","20/200"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng để đạt mức này.","h2":"Ở Alaska, bạn cần thị lực ít nhất 20/40 ở mỗi mắt hoặc cả hai mắt cùng nhau, và nếu bạn cần kính để đậu, bạn phải đeo kính khi lái xe.","p":"Đúng. Tiêu chuẩn là 20/40."},"tl":{"q":"Sa Alaska, ano ang pinakamababang paningin na kailangan para sa lisensiya, sa bawat mata o sa dalawang mata nang magkasama?","o":["20/40","20/80","20/100","20/200"],"h1":"Puwede kang magsuot ng salamin o contact lenses para maabot ito.","h2":"Sa Alaska, kailangan mo ng hindi bababa sa 20/40 na paningin sa bawat mata o sa dalawang mata nang magkasama, at kung kailangan mo ng lens para pumasa, dapat mo itong suotin kapag nagmamaneho.","p":"Tama. Ang pamantayan ay 20/40."},"ar":{"q":"في Alaska، ما أقل مستوى نظر مطلوب للرخصة، في كل عين أو في العينين معًا؟","o":["20/40","20/80","20/100","20/200"],"h1":"يمكنك أن تلبس نظارة أو عدسات لاصقة للوصول إليه.","h2":"في Alaska، تحتاج إلى نظر 20/40 على الأقل في كل عين أو في العينين معًا، وإذا كنت تحتاج إلى عدسات لتنجح، يجب أن تلبسها عندما تقود.","p":"صحيح. المعيار هو 20/40."},"ref":{"doc":"AK","page":6}},{"id":"ak-043","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, you failed the written knowledge test. When may you take it again?","o":["After 30 days","The next day","After one week","After six months"],"h1":"Study the manual again first; you will not wait long.","h2":"In Alaska, if you fail the written test, you may take it again the following day.","p":"Right. You may retake it the next day."},"es":{"q":"En Alaska, usted no pasó el examen escrito de conocimientos. ¿Cuándo puede tomarlo otra vez?","o":["Después de 30 días","Al día siguiente","Después de una semana","Después de seis meses"],"h1":"Estudie el manual otra vez primero; no tendrá que esperar mucho.","h2":"En Alaska, si no pasa el examen escrito, puede tomarlo otra vez al día siguiente.","p":"Correcto. Puede repetirlo al día siguiente."},"zh":{"q":"在 Alaska，你没有通过笔试（知识考试）。你什么时候可以再考？","o":["30 天以后","第二天","一周以后","六个月以后"],"h1":"先再读一遍手册；你不用等很久。","h2":"在 Alaska，如果你笔试没通过，第二天就可以再考。","p":"对。你第二天就可以重考。"},"vi":{"q":"Ở Alaska, bạn thi rớt bài thi kiến thức viết. Khi nào bạn có thể thi lại?","o":["Sau 30 ngày","Ngày hôm sau","Sau một tuần","Sau sáu tháng"],"h1":"Hãy học lại cuốn sổ tay trước; bạn sẽ không phải chờ lâu.","h2":"Ở Alaska, nếu bạn thi rớt bài thi viết, bạn có thể thi lại vào ngày hôm sau.","p":"Đúng. Bạn có thể thi lại vào ngày hôm sau."},"tl":{"q":"Sa Alaska, bumagsak ka sa written knowledge test. Kailan mo ito puwedeng kunin ulit?","o":["Pagkalipas ng 30 araw","Sa susunod na araw","Pagkalipas ng isang linggo","Pagkalipas ng anim na buwan"],"h1":"Pag-aralan muna ulit ang manual; hindi ka maghihintay nang matagal.","h2":"Sa Alaska, kung bumagsak ka sa written test, puwede mo itong kunin ulit sa susunod na araw.","p":"Tama. Puwede mo itong ulitin sa susunod na araw."},"ar":{"q":"في Alaska، رسبت في الاختبار النظري المكتوب. متى يمكنك أن تقدّمه مرة أخرى؟","o":["بعد 30 يومًا","في اليوم التالي","بعد أسبوع","بعد ستة أشهر"],"h1":"ادرس الدليل مرة أخرى أولًا؛ لن تنتظر طويلًا.","h2":"في Alaska، إذا رسبت في الاختبار المكتوب، يمكنك أن تقدّمه مرة أخرى في اليوم التالي.","p":"صحيح. يمكنك أن تعيده في اليوم التالي."},"ref":{"doc":"AK","page":7}},{"id":"ak-044","scope":"AK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alaska, a child is younger than 1 year old. How must the child ride in a car?","o":["In a booster seat","On an adult's lap","In a rear-facing child safety seat","With only the car's seat belt"],"h1":"Babies need a seat that protects the head and neck in a crash.","h2":"In Alaska, a child under 1 year old, or any child who weighs less than 20 pounds, must ride in a rear-facing child safety seat.","p":"Right. A baby under 1 rides in a rear-facing seat."},"es":{"q":"En Alaska, un niño tiene menos de 1 año. ¿Cómo debe viajar en el carro?","o":["En un asiento elevado (booster)","En las piernas de un adulto","En un asiento de seguridad mirando hacia atrás","Solo con el cinturón del carro"],"h1":"Los bebés necesitan un asiento que proteja la cabeza y el cuello en un choque.","h2":"En Alaska, un niño menor de 1 año, o cualquier niño que pese menos de 20 libras, debe viajar en un asiento de seguridad mirando hacia atrás.","p":"Correcto. Un bebé menor de 1 año viaja en un asiento mirando hacia atrás."},"zh":{"q":"在 Alaska，一个孩子还不到 1 岁。这个孩子坐车时必须怎么坐？","o":["坐增高座椅","坐在大人腿上","坐后向的儿童安全座椅","只用车上的安全带"],"h1":"婴儿需要一个在车祸中能保护头和脖子的座椅。","h2":"在 Alaska，不到 1 岁的孩子，或任何体重不到 20 磅的孩子，必须坐后向的儿童安全座椅。","p":"对。不到 1 岁的婴儿要坐后向座椅。"},"vi":{"q":"Ở Alaska, một em bé chưa đầy 1 tuổi. Em bé phải ngồi trên xe như thế nào?","o":["Ngồi ghế nâng (booster seat)","Ngồi trên đùi người lớn","Ngồi ghế an toàn trẻ em quay mặt về phía sau","Chỉ dùng dây an toàn của xe"],"h1":"Em bé cần một chiếc ghế bảo vệ đầu và cổ khi có tai nạn.","h2":"Ở Alaska, trẻ dưới 1 tuổi, hoặc bất kỳ trẻ nào nặng dưới 20 pounds, phải ngồi ghế an toàn trẻ em quay mặt về phía sau.","p":"Đúng. Em bé dưới 1 tuổi ngồi ghế quay mặt về phía sau."},"tl":{"q":"Sa Alaska, ang isang bata ay wala pang 1 taong gulang. Paano dapat sumakay ang bata sa kotse?","o":["Sa booster seat","Sa kandungan ng isang adult","Sa rear-facing na child safety seat (nakaharap sa likod)","Gamit lang ang seat belt ng kotse"],"h1":"Kailangan ng mga sanggol ng upuang nagpoprotekta sa ulo at leeg kapag may banggaan.","h2":"Sa Alaska, ang batang wala pang 1 taong gulang, o sinumang bata na mas magaan sa 20 pounds, ay dapat sumakay sa rear-facing na child safety seat.","p":"Tama. Ang sanggol na wala pang 1 taon ay sumasakay sa upuang nakaharap sa likod."},"ar":{"q":"في Alaska، طفل عمره أقل من سنة واحدة (1). كيف يجب أن يركب الطفل في السيارة؟","o":["في مقعد رافع (booster)","في حضن شخص بالغ","في مقعد أمان للأطفال مُوجَّه إلى الخلف","بحزام أمان السيارة فقط"],"h1":"يحتاج الرضّع إلى مقعد يحمي الرأس والرقبة في حادث الاصطدام.","h2":"في Alaska، الطفل الذي عمره أقل من سنة واحدة (1)، أو أي طفل وزنه أقل من 20 pounds، يجب أن يركب في مقعد أمان للأطفال مُوجَّه إلى الخلف.","p":"صحيح. الرضيع الذي عمره أقل من سنة واحدة (1) يركب في مقعد مُوجَّه إلى الخلف."},"ref":{"doc":"AK","page":21}},{"id":"ak-045","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, you are driving at night with high beams on. A car is coming toward you. At what distance must you switch to low beams?","o":["100 feet","200 feet","2,000 feet","500 feet"],"h1":"The rule for a car coming toward you is longer than for a car you follow.","h2":"In Alaska, you must dim to low beams when you are 500 feet or more from an oncoming vehicle, and 300 feet from a vehicle you are following.","p":"Right. Dim your lights at 500 feet from oncoming traffic."},"es":{"q":"En Alaska, maneja de noche con las luces altas. Viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","2,000 pies","500 pies"],"h1":"La regla para un carro que viene de frente es más larga que para un carro que usted sigue.","h2":"En Alaska, debe cambiar a luces bajas cuando está a 500 pies o más de un vehículo que viene de frente, y a 300 pies de un vehículo que va delante de usted.","p":"Correcto. Baje las luces a 500 pies del tráfico que viene de frente."},"zh":{"q":"在 Alaska，你晚上开车，开着远光灯。有一辆车迎面开来。你必须在什么距离换成近光灯？","o":["100 英尺","200 英尺","2,000 英尺","500 英尺"],"h1":"对迎面来车的规定比对你跟随的车的距离更远。","h2":"在 Alaska，当你离迎面来车 500 英尺或更远时，就必须换成近光灯；离你跟随的车 300 英尺时也要换。","p":"对。离迎面来车 500 英尺时调暗车灯。"},"vi":{"q":"Ở Alaska, bạn đang lái xe ban đêm và bật đèn pha (đèn chiếu xa). Có một xe đang chạy ngược chiều về phía bạn. Bạn phải chuyển sang đèn chiếu gần ở khoảng cách nào?","o":["100 feet","200 feet","2,000 feet","500 feet"],"h1":"Quy định cho xe chạy ngược chiều xa hơn so với xe bạn đang đi theo sau.","h2":"Ở Alaska, bạn phải chuyển sang đèn chiếu gần khi cách xe chạy ngược chiều từ 500 feet trở lên, và khi cách 300 feet với xe bạn đang đi theo sau.","p":"Đúng. Giảm đèn khi cách xe chạy ngược chiều 500 feet."},"tl":{"q":"Sa Alaska, nagmamaneho ka sa gabi nang naka-high beam. May kotseng papalapit sa iyo mula sa harap. Sa anong layo ka dapat lumipat sa low beam?","o":["100 feet","200 feet","2,000 feet","500 feet"],"h1":"Mas mahaba ang patakaran para sa kotseng papalapit sa iyo kaysa sa kotseng sinusundan mo.","h2":"Sa Alaska, dapat kang lumipat sa low beam kapag ikaw ay 500 feet o higit pa mula sa paparating na sasakyan, at 300 feet mula sa sasakyang sinusundan mo.","p":"Tama. Hinaan ang ilaw sa layong 500 feet mula sa paparating na trapiko."},"ar":{"q":"في Alaska، أنت تقود ليلًا والأضواء العالية مُشغّلة. سيارة قادمة نحوك. على أي مسافة يجب أن تُغيّر إلى الأضواء المنخفضة؟","o":["100 feet","200 feet","2,000 feet","500 feet"],"h1":"القاعدة للسيارة القادمة نحوك مسافتها أطول من القاعدة للسيارة التي تسير خلفها.","h2":"في Alaska، يجب أن تُغيّر إلى الأضواء المنخفضة عندما تكون على بُعد 500 feet أو أكثر من مركبة قادمة نحوك، وعلى بُعد 300 feet من مركبة تسير خلفها.","p":"صحيح. خفّض أضواءك على بُعد 500 feet من السيارات القادمة نحوك."},"ref":{"doc":"AK","page":55}},{"id":"ak-046","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, how far from a railroad crossing must you park, at the least?","o":["50 feet","10 feet","20 feet","5 feet"],"h1":"It is the longest of the usual parking distances, after the one for a stopped fire truck.","h2":"In Alaska, you may not park closer than 50 feet to a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Alaska, ¿a qué distancia mínima de un cruce de tren debe estacionarse?","o":["50 pies","10 pies","20 pies","5 pies"],"h1":"Es la más larga de las distancias comunes para estacionar, después de la de un camión de bomberos detenido.","h2":"En Alaska, no puede estacionarse a menos de 50 pies de un cruce de tren.","p":"Correcto. Estaciónese por lo menos a 50 pies de un cruce de tren."},"zh":{"q":"在 Alaska，停车时至少要离铁路道口多远？","o":["50 英尺","10 英尺","20 英尺","5 英尺"],"h1":"在常见的停车距离中，它是最长的，仅次于停着的消防车那一条。","h2":"在 Alaska，你不可以在离铁路道口不到 50 英尺的地方停车。","p":"对。停车要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Alaska, bạn phải đậu xe cách đường ray xe lửa ít nhất bao xa?","o":["50 feet","10 feet","20 feet","5 feet"],"h1":"Đây là khoảng cách đậu xe thông thường dài nhất, chỉ sau khoảng cách với xe cứu hỏa đang dừng.","h2":"Ở Alaska, bạn không được đậu xe gần hơn 50 feet so với chỗ băng qua đường ray xe lửa.","p":"Đúng. Đậu xe cách chỗ băng qua đường ray xe lửa ít nhất 50 feet."},"tl":{"q":"Sa Alaska, gaano kalayo ka dapat pumarada mula sa tawiran ng tren, sa pinakamababa?","o":["50 feet","10 feet","20 feet","5 feet"],"h1":"Ito ang pinakamahaba sa karaniwang layo sa pagparada, pagkatapos ng para sa nakahintong fire truck.","h2":"Sa Alaska, hindi ka puwedeng pumarada nang mas malapit sa 50 feet mula sa tawiran ng tren.","p":"Tama. Pumarada nang hindi bababa sa 50 feet mula sa tawiran ng tren."},"ar":{"q":"في Alaska، ما أقل مسافة يجب أن تركن فيها بعيدًا عن معبر سكة القطار؟","o":["50 feet","10 feet","20 feet","5 feet"],"h1":"إنها أطول مسافات الركن المعتادة، بعد المسافة من سيارة إطفاء متوقفة.","h2":"في Alaska، يجب ألّا تركن على مسافة أقرب من 50 feet من معبر سكة القطار.","p":"صحيح. اركن على بُعد 50 feet على الأقل من معبر سكة القطار."},"ref":{"doc":"AK","page":62}},{"id":"ak-047","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, a fire truck is going to an emergency. If you are driving behind it, how far back must you stay?","o":["100 feet","500 feet","50 feet","200 feet"],"h1":"It is the same distance as the no-parking zone near a stopped fire truck.","h2":"In Alaska, you may not follow an emergency vehicle that is responding to an emergency closer than 500 feet.","p":"Right. Stay at least 500 feet behind it."},"es":{"q":"En Alaska, un camión de bomberos va a una emergencia. Si usted maneja detrás de él, ¿a qué distancia debe mantenerse?","o":["100 pies","500 pies","50 pies","200 pies"],"h1":"Es la misma distancia de la zona donde no se puede estacionar cerca de un camión de bomberos detenido.","h2":"En Alaska, no puede seguir a un vehículo de emergencia que va a una emergencia a menos de 500 pies.","p":"Correcto. Manténgase por lo menos a 500 pies detrás."},"zh":{"q":"在 Alaska，一辆消防车正赶往紧急情况。如果你开在它后面，你必须保持多远的距离？","o":["100 英尺","500 英尺","50 英尺","200 英尺"],"h1":"它和停着的消防车附近禁止停车区的距离一样。","h2":"在 Alaska，你跟在正赶往紧急情况的紧急车辆后面时，距离不可以少于 500 英尺。","p":"对。至少要在它后面 500 英尺。"},"vi":{"q":"Ở Alaska, một xe cứu hỏa đang chạy đến chỗ khẩn cấp. Nếu bạn lái xe phía sau nó, bạn phải giữ khoảng cách bao xa?","o":["100 feet","500 feet","50 feet","200 feet"],"h1":"Đó là cùng khoảng cách với khu vực cấm đậu xe gần xe cứu hỏa đang dừng.","h2":"Ở Alaska, bạn không được đi theo sau một xe khẩn cấp đang chạy đến chỗ khẩn cấp ở khoảng cách gần hơn 500 feet.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet phía sau xe đó."},"tl":{"q":"Sa Alaska, may fire truck na papunta sa isang emergency. Kung nagmamaneho ka sa likod nito, gaano kalayo ka dapat manatili?","o":["100 feet","500 feet","50 feet","200 feet"],"h1":"Pareho ito ng layo ng no-parking zone malapit sa nakahintong fire truck.","h2":"Sa Alaska, hindi ka puwedeng sumunod sa emergency vehicle na papunta sa isang emergency nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod nito."},"ar":{"q":"في Alaska، سيارة إطفاء متجهة إلى حالة طارئة. إذا كنت تقود خلفها، على أي مسافة يجب أن تبقى؟","o":["100 feet","500 feet","50 feet","200 feet"],"h1":"إنها نفس مسافة المنطقة الممنوع فيها الركن قرب سيارة إطفاء متوقفة.","h2":"في Alaska، يجب ألّا تتبع مركبة طوارئ متجهة إلى حالة طارئة على مسافة أقرب من 500 feet.","p":"صحيح. ابقَ على بُعد 500 feet على الأقل خلفها."},"ref":{"doc":"AK","page":64}},{"id":"ak-048","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, what happens to fines for traffic offenses inside a Traffic Safety Corridor?","o":["They are cut in half","They stay the same","They are doubled","They are tripled"],"h1":"These stretches of highway get extra protection.","h2":"In Alaska, fines for traffic offenses in a Traffic Safety Corridor are doubled.","p":"Right. Fines are doubled in a Traffic Safety Corridor."},"es":{"q":"En Alaska, ¿qué pasa con las multas por infracciones de tránsito dentro de un Traffic Safety Corridor (corredor de seguridad vial)?","o":["Se reducen a la mitad","Siguen iguales","Se duplican","Se triplican"],"h1":"Estos tramos de carretera tienen protección adicional.","h2":"En Alaska, las multas por infracciones de tránsito en un Traffic Safety Corridor se duplican.","p":"Correcto. Las multas se duplican en un Traffic Safety Corridor."},"zh":{"q":"在 Alaska，在交通安全走廊（Traffic Safety Corridor）内违反交通规则，罚款会怎样？","o":["减半","保持不变","加倍","变成三倍"],"h1":"这些路段有额外的保护。","h2":"在 Alaska，在 Traffic Safety Corridor 内违反交通规则的罚款会加倍。","p":"对。在 Traffic Safety Corridor 内罚款加倍。"},"vi":{"q":"Ở Alaska, tiền phạt vi phạm giao thông trong một Traffic Safety Corridor (hành lang an toàn giao thông) sẽ như thế nào?","o":["Giảm một nửa","Giữ nguyên","Tăng gấp đôi","Tăng gấp ba"],"h1":"Những đoạn đường cao tốc này được bảo vệ thêm.","h2":"Ở Alaska, tiền phạt vi phạm giao thông trong một Traffic Safety Corridor được tăng gấp đôi.","p":"Đúng. Tiền phạt tăng gấp đôi trong Traffic Safety Corridor."},"tl":{"q":"Sa Alaska, ano ang nangyayari sa multa para sa mga traffic violation sa loob ng Traffic Safety Corridor?","o":["Hinahati sa kalahati","Nananatiling pareho","Dinodoble","Tinatriple"],"h1":"May dagdag na proteksiyon ang mga bahaging ito ng highway.","h2":"Sa Alaska, dinodoble ang multa para sa mga traffic violation sa loob ng Traffic Safety Corridor.","p":"Tama. Dinodoble ang multa sa Traffic Safety Corridor."},"ar":{"q":"في Alaska، ماذا يحدث للغرامات على مخالفات المرور داخل ممر السلامة المرورية (Traffic Safety Corridor)؟","o":["تُخفَّض إلى النصف","تبقى كما هي","تتضاعف","تصبح ثلاثة أضعاف"],"h1":"هذه الأجزاء من الطريق السريع لها حماية إضافية.","h2":"في Alaska، الغرامات على مخالفات المرور داخل Traffic Safety Corridor تتضاعف.","p":"صحيح. الغرامات تتضاعف في Traffic Safety Corridor."},"ref":{"doc":"AK","page":29}},{"id":"ak-049","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, your car hits a moose and kills or injures it. What must you do?","o":["Keep the animal for its meat","Drive on if your car still works","Call only your insurance company","Tell a State Trooper or wildlife officer soon"],"h1":"Big game animals hit on the road belong to the state.","h2":"In Alaska, if you kill or injure a big game animal with your vehicle, you must tell a State Trooper or a Fish and Wildlife officer as soon as possible.","p":"Right. Tell a State Trooper or wildlife officer as soon as you can."},"es":{"q":"En Alaska, su carro choca con un alce y lo mata o lo hiere. ¿Qué debe hacer?","o":["Quedarse con el animal por su carne","Seguir manejando si el carro funciona","Llamar solo a su compañía de seguros","Avisar pronto a un State Trooper o agente de vida silvestre"],"h1":"Los animales de caza mayor atropellados en la carretera son del estado.","h2":"En Alaska, si mata o hiere a un animal de caza mayor con su vehículo, debe avisar a un State Trooper o a un agente de Fish and Wildlife lo antes posible.","p":"Correcto. Avise a un State Trooper o agente de vida silvestre lo antes posible."},"zh":{"q":"在 Alaska，你的车撞到一头驼鹿，把它撞死或撞伤了。你必须做什么？","o":["把动物留下来吃肉","如果车还能开就继续开走","只打电话给你的保险公司","尽快告诉州警（State Trooper）或野生动物官员"],"h1":"在路上被撞的大型猎物属于州政府。","h2":"在 Alaska，如果你的车撞死或撞伤了大型猎物，你必须尽快告诉 State Trooper 或 Fish and Wildlife 官员。","p":"对。尽快告诉 State Trooper 或野生动物官员。"},"vi":{"q":"Ở Alaska, xe của bạn đâm phải một con nai sừng tấm (moose) và làm nó chết hoặc bị thương. Bạn phải làm gì?","o":["Giữ con vật lại để lấy thịt","Tiếp tục lái đi nếu xe vẫn chạy được","Chỉ gọi cho công ty bảo hiểm của bạn","Báo sớm cho State Trooper hoặc nhân viên kiểm lâm động vật hoang dã"],"h1":"Thú săn lớn bị đâm trên đường thuộc về tiểu bang.","h2":"Ở Alaska, nếu bạn làm chết hoặc bị thương một con thú săn lớn bằng xe của mình, bạn phải báo cho State Trooper hoặc nhân viên Fish and Wildlife càng sớm càng tốt.","p":"Đúng. Báo cho State Trooper hoặc nhân viên kiểm lâm động vật hoang dã càng sớm càng tốt."},"tl":{"q":"Sa Alaska, nabangga ng kotse mo ang isang moose at namatay o nasugatan ito. Ano ang dapat mong gawin?","o":["Itago ang hayop para sa karne nito","Magpatuloy sa pagmamaneho kung gumagana pa ang kotse","Tawagan lang ang iyong insurance company","Sabihan agad ang isang State Trooper o wildlife officer"],"h1":"Ang malalaking hayop na pangangaso na nabangga sa daan ay pag-aari ng estado.","h2":"Sa Alaska, kung napatay o nasugatan mo ang isang malaking hayop na pangangaso gamit ang iyong sasakyan, dapat mong sabihan ang isang State Trooper o Fish and Wildlife officer sa lalong madaling panahon.","p":"Tama. Sabihan ang isang State Trooper o wildlife officer sa lalong madaling panahon."},"ar":{"q":"في Alaska، صدمت سيارتك حيوان موظ (moose) فقتلته أو جرحته. ماذا يجب أن تفعل؟","o":["أن تحتفظ بالحيوان من أجل لحمه","أن تتابع القيادة إذا كانت سيارتك ما زالت تعمل","أن تتصل بشركة التأمين فقط","أن تُبلغ بسرعة شرطي الولاية (State Trooper) أو موظف الحياة البرية"],"h1":"حيوانات الصيد الكبيرة التي تُصدم على الطريق مِلك للولاية.","h2":"في Alaska، إذا قتلت أو جرحت حيوان صيد كبيرًا بمركبتك، يجب أن تُبلغ State Trooper أو موظف Fish and Wildlife في أسرع وقت ممكن.","p":"صحيح. أبلغ State Trooper أو موظف الحياة البرية في أسرع وقت ممكن."},"ref":{"doc":"AK","page":60}},{"id":"ak-050","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, which parts of the road usually become slippery first in freezing weather and stay slippery longer?","o":["Bridges and shaded areas","Sunny, straight stretches","Busy streets in town","Newly paved roads"],"h1":"Think of places where cold air or shade reaches the road surface more.","h2":"In Alaska, bridges, shaded spots and protected areas become slippery before the rest of the road and stay slippery longer.","p":"Right. Watch bridges and shaded areas for ice."},"es":{"q":"En Alaska, cuando hay heladas, ¿qué partes de la carretera suelen ponerse resbalosas primero y siguen así por más tiempo?","o":["Los puentes y las zonas con sombra","Los tramos rectos y soleados","Las calles con mucho tráfico en la ciudad","Las carreteras recién pavimentadas"],"h1":"Piense en lugares donde el aire frío o la sombra llegan más a la superficie.","h2":"En Alaska, los puentes, las zonas con sombra y las áreas protegidas se ponen resbalosas antes que el resto de la carretera y siguen así por más tiempo.","p":"Correcto. Tenga cuidado con el hielo en puentes y zonas con sombra."},"zh":{"q":"在 Alaska，结冰的天气里，路上哪些地方通常最先变滑，而且滑的时间更久？","o":["桥面和背阴的地方","阳光充足的直路","城里车多的街道","刚铺好的路"],"h1":"想一想冷空气或阴影更容易接触到路面的地方。","h2":"在 Alaska，桥面、背阴的地方和被遮挡的地方会比路的其他部分更早变滑，而且滑的时间更久。","p":"对。要注意桥面和背阴处的冰。"},"vi":{"q":"Ở Alaska, khi trời giá lạnh, những phần nào của con đường thường trơn trượt trước tiên và trơn lâu hơn?","o":["Cầu và những chỗ có bóng râm","Những đoạn đường thẳng, có nắng","Những con đường đông xe trong thành phố","Những con đường mới trải nhựa"],"h1":"Hãy nghĩ đến những nơi mà không khí lạnh hoặc bóng râm chạm vào mặt đường nhiều hơn.","h2":"Ở Alaska, cầu, những chỗ có bóng râm và những khu vực được che chắn trở nên trơn trượt trước phần còn lại của con đường và trơn lâu hơn.","p":"Đúng. Hãy coi chừng băng trên cầu và ở những chỗ có bóng râm."},"tl":{"q":"Sa Alaska, aling mga bahagi ng daan ang karaniwang unang dumudulas kapag nagyeyelo ang panahon at mas matagal na madulas?","o":["Mga tulay at mga lugar na may lilim","Mga diretso at maaraw na bahagi ng daan","Mga mataong kalye sa bayan","Mga bagong sementong daan"],"h1":"Isipin ang mga lugar kung saan mas naaabot ng malamig na hangin o lilim ang ibabaw ng daan.","h2":"Sa Alaska, ang mga tulay, mga lugar na may lilim at mga natatakpang lugar ay nagiging madulas bago ang ibang bahagi ng daan at mas matagal na nananatiling madulas.","p":"Tama. Bantayan ang yelo sa mga tulay at lugar na may lilim."},"ar":{"q":"في Alaska، في الطقس المتجمّد، أي أجزاء الطريق تصبح زلقة أولًا عادةً وتبقى زلقة مدة أطول؟","o":["الجسور والأماكن المظلّلة","الأجزاء المستقيمة المشمسة","الشوارع المزدحمة في المدينة","الطرق المرصوفة حديثًا"],"h1":"فكّر في الأماكن التي يصل فيها الهواء البارد أو الظل إلى سطح الطريق أكثر.","h2":"في Alaska، الجسور والأماكن المظلّلة والمناطق المحمية تصبح زلقة قبل باقي الطريق وتبقى زلقة مدة أطول.","p":"صحيح. انتبه للجليد على الجسور وفي الأماكن المظلّلة."},"ref":{"doc":"AK","page":61}},{"id":"ak-051","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, why does the driver manual say to keep your fuel tank full in cold weather?","o":["To make the heater work faster","To keep moisture from forming in the tank","To make the car heavier on ice","To pass the vehicle inspection"],"h1":"Cold air inside an almost empty tank can leave water behind.","h2":"In Alaska, keeping your fuel tank full in cold weather helps stop moisture from condensing inside the tank.","p":"Right. A full tank keeps moisture from forming inside."},"es":{"q":"En Alaska, ¿por qué dice el manual que mantenga lleno el tanque de gasolina cuando hace frío?","o":["Para que la calefacción funcione más rápido","Para evitar que se forme humedad en el tanque","Para que el carro pese más sobre el hielo","Para pasar la inspección del vehículo"],"h1":"El aire frío dentro de un tanque casi vacío puede dejar agua.","h2":"En Alaska, mantener lleno el tanque de gasolina cuando hace frío ayuda a evitar que se condense humedad dentro del tanque.","p":"Correcto. Un tanque lleno evita que se forme humedad adentro."},"zh":{"q":"在 Alaska，驾驶手册为什么说冷天时要让油箱保持加满？","o":["让暖气更快变热","防止油箱里形成水汽","让车在冰上更重","为了通过车辆检查"],"h1":"几乎空的油箱里的冷空气可能会留下水。","h2":"在 Alaska，冷天时让油箱保持加满，可以帮助防止水汽在油箱里凝结。","p":"对。加满的油箱可以防止里面形成水汽。"},"vi":{"q":"Ở Alaska, tại sao sổ tay lái xe nói nên giữ bình xăng đầy khi trời lạnh?","o":["Để máy sưởi chạy nhanh hơn","Để hơi ẩm không hình thành trong bình","Để xe nặng hơn trên băng","Để qua được kỳ kiểm tra xe"],"h1":"Không khí lạnh trong bình xăng gần cạn có thể để lại nước.","h2":"Ở Alaska, giữ bình xăng đầy khi trời lạnh giúp ngăn hơi ẩm ngưng tụ bên trong bình.","p":"Đúng. Bình xăng đầy giúp hơi ẩm không hình thành bên trong."},"tl":{"q":"Sa Alaska, bakit sinasabi ng driver manual na panatilihing puno ang tangke ng gasolina kapag malamig ang panahon?","o":["Para mas mabilis gumana ang heater","Para hindi magkaroon ng moisture sa loob ng tangke","Para mas bumigat ang kotse sa yelo","Para pumasa sa vehicle inspection"],"h1":"Ang malamig na hangin sa loob ng halos walang lamang tangke ay puwedeng mag-iwan ng tubig.","h2":"Sa Alaska, ang pagpapanatiling puno ng tangke ng gasolina kapag malamig ang panahon ay nakakatulong na pigilan ang moisture na mabuo sa loob ng tangke.","p":"Tama. Pinipigilan ng punong tangke ang pagkakaroon ng moisture sa loob."},"ar":{"q":"في Alaska، لماذا يقول دليل القيادة أن تُبقي خزان الوقود ممتلئًا في الطقس البارد؟","o":["لكي تعمل التدفئة أسرع","لمنع تكوّن الرطوبة داخل الخزان","لكي تصبح السيارة أثقل على الجليد","لكي تنجح في فحص المركبة"],"h1":"الهواء البارد داخل خزان شبه فارغ يمكن أن يترك ماءً.","h2":"في Alaska، إبقاء خزان الوقود ممتلئًا في الطقس البارد يساعد على منع تكثّف الرطوبة داخل الخزان.","p":"صحيح. الخزان الممتلئ يمنع تكوّن الرطوبة في داخله."},"ref":{"doc":"AK","page":59}},{"id":"ak-052","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, you move to the state with a valid license from another state. How long can you drive on it before you need an Alaska license?","o":["30 days","60 days","90 days","One year"],"h1":"It is about three months.","h2":"In Alaska, a new resident with a valid out-of-state license must get an Alaska license within 90 days after arriving.","p":"Right. You have 90 days to get an Alaska license."},"es":{"q":"En Alaska, usted se muda al estado con una licencia válida de otro estado. ¿Cuánto tiempo puede manejar con ella antes de necesitar una licencia de Alaska?","o":["30 días","60 días","90 días","Un año"],"h1":"Son unos tres meses.","h2":"En Alaska, un nuevo residente con una licencia válida de otro estado debe obtener una licencia de Alaska dentro de los 90 días después de llegar.","p":"Correcto. Tiene 90 días para obtener una licencia de Alaska."},"ref":{"doc":"AK","page":2}},{"id":"ak-053","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a 14- or 15-year-old may get an M2 license. What may they drive with it?","o":["A motor scooter under 50cc","A car, with an adult beside them","Any motorcycle, in daylight only","A three-wheeled motorcycle"],"h1":"Think of the smallest motor vehicle with two wheels.","h2":"In Alaska, the M2 license lets a 14- or 15-year-old drive a motor scooter with an engine smaller than 50cc.","p":"Right. The M2 license is for scooters under 50cc."},"es":{"q":"En Alaska, una persona de 14 o 15 años puede obtener una licencia M2. ¿Qué puede manejar con ella?","o":["Una motoneta de menos de 50cc","Un carro, con un adulto al lado","Cualquier motocicleta, solo de día","Una motocicleta de tres ruedas"],"h1":"Piense en el vehículo de motor de dos ruedas más pequeño.","h2":"En Alaska, la licencia M2 permite que una persona de 14 o 15 años maneje una motoneta con motor de menos de 50cc.","p":"Correcto. La licencia M2 es para motonetas de menos de 50cc."},"ref":{"doc":"AK","page":2}},{"id":"ak-054","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, which paper is NOT accepted as proof of your date of birth for a first license or permit?","o":["A valid U.S. passport","A certified U.S. birth certificate with a raised seal","A U.S. passport card","A birth certificate issued by a hospital"],"h1":"The birth record must come from a government office.","h2":"In Alaska, a birth certificate issued by a hospital is not accepted; the birth certificate must be certified by a government agency.","p":"Right. Hospital birth certificates are not accepted."},"es":{"q":"En Alaska, ¿qué documento NO se acepta como prueba de su fecha de nacimiento para una primera licencia o permiso?","o":["Un pasaporte de EE. UU. vigente","Un acta de nacimiento certificada de EE. UU. con sello en relieve","Una tarjeta pasaporte de EE. UU.","Un acta de nacimiento emitida por un hospital"],"h1":"El registro de nacimiento debe venir de una oficina del gobierno.","h2":"En Alaska, no se acepta un acta de nacimiento emitida por un hospital; el acta debe estar certificada por una agencia del gobierno.","p":"Correcto. No se aceptan actas de nacimiento de hospital."},"ref":{"doc":"AK","page":3}},{"id":"ak-055","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, a parent signs the consent form for a teen under 18 to get a permit. What may that mean for the parent?","o":["The parent must ride along for one year","The parent may be liable for damages if the teen causes a crash","The parent pays half of every traffic ticket","The parent gets points if the teen speeds"],"h1":"Think about who could have to pay after a crash.","h2":"In Alaska, the person who signs the parental consent may be held responsible for damages caused by the minor's careless driving.","p":"Right. The signer may be liable for damages in a crash."},"es":{"q":"En Alaska, un padre firma el formulario de consentimiento para que un joven menor de 18 años obtenga un permiso. ¿Qué puede significar esto para el padre?","o":["El padre debe acompañarlo durante un año","El padre puede ser responsable de los daños si el joven causa un choque","El padre paga la mitad de cada multa de tránsito","El padre recibe puntos si el joven va a exceso de velocidad"],"h1":"Piense en quién podría tener que pagar después de un choque.","h2":"En Alaska, la persona que firma el consentimiento de los padres puede ser responsable de los daños causados por el manejo descuidado del menor.","p":"Correcto. Quien firma puede ser responsable de los daños en un choque."},"ref":{"doc":"AK","page":3}},{"id":"ak-056","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, who may withdraw the parental consent for a teen's permit or license?","o":["Any adult who lives with the teen","The teen's school principal","Only the person who signed the consent","Any police officer"],"h1":"It is the same person who gave the consent.","h2":"In Alaska, only the person who signed the parental consent may withdraw it, and then the DMV cancels the teen's permit or license.","p":"Right. Only the person who signed may withdraw consent."},"es":{"q":"En Alaska, ¿quién puede retirar el consentimiento de los padres para el permiso o la licencia de un joven?","o":["Cualquier adulto que viva con el joven","El director de la escuela del joven","Solo la persona que firmó el consentimiento","Cualquier policía"],"h1":"Es la misma persona que dio el consentimiento.","h2":"En Alaska, solo la persona que firmó el consentimiento de los padres puede retirarlo, y entonces el DMV cancela el permiso o la licencia del joven.","p":"Correcto. Solo quien firmó puede retirar el consentimiento."},"ref":{"doc":"AK","page":3}},{"id":"ak-057","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, you are practicing on a motorcycle with an instruction permit. Where must your supervising licensed driver be?","o":["Within sight of you, supervising you directly","Anywhere in the same town","At home, reachable by phone","On the back seat of the motorcycle"],"h1":"The supervisor has to be able to see you.","h2":"In Alaska, a motorcycle or scooter permit holder must stay within sight of the licensed driver and under that person's direct supervision.","p":"Right. The supervisor must be within sight of you."},"es":{"q":"En Alaska, usted practica en una motocicleta con un permiso de aprendizaje. ¿Dónde debe estar el conductor con licencia que lo supervisa?","o":["A la vista de usted, supervisándolo directamente","En cualquier lugar del mismo pueblo","En casa, disponible por teléfono","En el asiento trasero de la motocicleta"],"h1":"El supervisor tiene que poder verlo.","h2":"En Alaska, quien tiene un permiso de motocicleta o motoneta debe estar a la vista del conductor con licencia y bajo su supervisión directa.","p":"Correcto. El supervisor debe estar a la vista de usted."},"ref":{"doc":"AK","page":4}},{"id":"ak-058","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a person is convicted of driving while their license is suspended. What is the least jail time?","o":["No jail, only a warning","One day","Three days","10 days"],"h1":"It is more than a week.","h2":"In Alaska, a conviction for driving while your license is suspended, revoked or canceled brings a jail sentence of at least 10 days.","p":"Right. The jail sentence is at least 10 days."},"es":{"q":"En Alaska, una persona es declarada culpable de manejar con la licencia suspendida. ¿Cuál es el tiempo mínimo de cárcel?","o":["Nada de cárcel, solo una advertencia","Un día","Tres días","10 días"],"h1":"Es más de una semana.","h2":"En Alaska, una condena por manejar con la licencia suspendida, revocada o cancelada trae una sentencia de cárcel de al menos 10 días.","p":"Correcto. La sentencia de cárcel es de al menos 10 días."},"ref":{"doc":"AK","page":5}},{"id":"ak-059","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, your license was issued before you turned 21. What must you pass before you can renew it?","o":["A new road test","An alcohol awareness test","A first aid course","A hearing test"],"h1":"It is about drinking and driving.","h2":"In Alaska, a driver whose license was issued before age 21 must pass an alcohol awareness test before renewing it.","p":"Right. You must pass an alcohol awareness test first."},"es":{"q":"En Alaska, su licencia se emitió antes de que usted cumpliera 21 años. ¿Qué debe aprobar antes de poder renovarla?","o":["Un nuevo examen de manejo","Un examen sobre el alcohol","Un curso de primeros auxilios","Un examen de audición"],"h1":"Tiene que ver con tomar alcohol y manejar.","h2":"En Alaska, un conductor cuya licencia se emitió antes de los 21 años debe aprobar un examen sobre el alcohol antes de renovarla.","p":"Correcto. Primero debe aprobar un examen sobre el alcohol."},"ref":{"doc":"AK","page":5}},{"id":"ak-060","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, a teen has a provisional license restricted to an area not connected to the road system. Do the passenger and night-hour limits apply?","o":["Yes, they apply everywhere","Only the night-hour limit applies","No, they do not apply to an off-system license","Only in winter"],"h1":"Off-system licenses have a special note.","h2":"In Alaska, the provisional passenger and night-hour limits do not apply to an off-system license restricted to areas off the highway system.","p":"Right. Those limits do not apply to an off-system license."},"es":{"q":"En Alaska, un joven tiene una licencia provisional limitada a una zona que no está conectada a la red de carreteras. ¿Se aplican los límites de pasajeros y de horas de la noche?","o":["Sí, se aplican en todas partes","Solo se aplica el límite de horas de la noche","No, no se aplican a una licencia fuera de la red","Solo en invierno"],"h1":"Las licencias fuera de la red tienen una nota especial.","h2":"En Alaska, los límites de pasajeros y de horas de la noche de la licencia provisional no se aplican a una licencia limitada a zonas fuera de la red de carreteras.","p":"Correcto. Esos límites no se aplican a una licencia fuera de la red."},"ref":{"doc":"AK","page":6}},{"id":"ak-061","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, you failed the driving (road) test. Normally, how long must you wait to take it again?","o":["Two business days","The next day","Two weeks","30 days"],"h1":"Count only weekdays that are not holidays.","h2":"In Alaska, you normally must wait two business days before you retake the driving test.","p":"Right. You normally wait two business days."},"es":{"q":"En Alaska, usted reprobó el examen de manejo en la calle. Normalmente, ¿cuánto debe esperar para tomarlo otra vez?","o":["Dos días hábiles","Al día siguiente","Dos semanas","30 días"],"h1":"Cuente solo los días entre semana que no son feriados.","h2":"En Alaska, normalmente debe esperar dos días hábiles antes de volver a tomar el examen de manejo.","p":"Correcto. Normalmente se esperan dos días hábiles."},"ref":{"doc":"AK","page":7}},{"id":"ak-062","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, who may ride in the car with you and the examiner during the driving test?","o":["A parent or guardian","Your driving instructor","A friend, in the back seat","No one else"],"h1":"The test is just you and the examiner.","h2":"In Alaska, no one else is allowed to ride with you and the examiner during the driving test.","p":"Right. No one else may come along."},"es":{"q":"En Alaska, ¿quién puede ir en el carro con usted y el examinador durante el examen de manejo?","o":["Un padre o tutor","Su instructor de manejo","Un amigo, en el asiento de atrás","Nadie más"],"h1":"En el examen van solo usted y el examinador.","h2":"En Alaska, nadie más puede ir con usted y el examinador durante el examen de manejo.","p":"Correcto. Nadie más puede acompañarlos."},"ref":{"doc":"AK","page":7}},{"id":"ak-063","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, you moved to a new address. How soon must you tell the DMV in writing?","o":["Within 10 days","Within 30 days","Within 90 days","When you renew your license"],"h1":"It is about one month.","h2":"In Alaska, you must notify the DMV in writing within 30 days after you change your name or address.","p":"Right. You must tell the DMV within 30 days."},"es":{"q":"En Alaska, usted se mudó a una nueva dirección. ¿En cuánto tiempo debe avisar por escrito al DMV?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 90 días","Cuando renueve su licencia"],"h1":"Es más o menos un mes.","h2":"En Alaska, debe avisar por escrito al DMV dentro de los 30 días después de cambiar de nombre o de dirección.","p":"Correcto. Debe avisar al DMV dentro de 30 días."},"ref":{"doc":"AK","page":9}},{"id":"ak-064","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, a driver is in a crash without insurance for the second time. How long is the license suspended?","o":["30 days","90 days","One year","Five years"],"h1":"The first time it is 90 days; the second time is longer.","h2":"In Alaska, being uninsured in a crash a second time leads to a license suspension of one year.","p":"Right. A second time means a one-year suspension."},"es":{"q":"En Alaska, un conductor tiene un choque sin seguro por segunda vez. ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","90 días","Un año","Cinco años"],"h1":"La primera vez son 90 días; la segunda vez es más tiempo.","h2":"En Alaska, no tener seguro en un choque por segunda vez trae una suspensión de la licencia de un año.","p":"Correcto. La segunda vez significa una suspensión de un año."},"ref":{"doc":"AK","page":10}},{"id":"ak-065","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, after a crash you may be found liable for another person's damages. How long can your license be suspended under the Financial Responsibility law?","o":["Up to three years, unless you settle with the others","Up to 30 days, and then it ends on its own","Only until your car has been fully repaired","It cannot be suspended for a civil claim"],"h1":"Paying the other people can end it early.","h2":"In Alaska, your license can be suspended for up to three years, and you can end the suspension by making a financial settlement with the others in the crash.","p":"Right. Up to three years, unless you settle."},"es":{"q":"En Alaska, después de un choque, usted podría ser responsable de los daños de otra persona. ¿Por cuánto tiempo pueden suspender su licencia según la ley de Responsabilidad Financiera?","o":["Hasta tres años, a menos que llegue a un acuerdo con los demás","Hasta 30 días, y luego termina sola","Solo hasta que su carro esté reparado","No la pueden suspender por un reclamo civil"],"h1":"Pagarles a las otras personas puede terminarla antes.","h2":"En Alaska, su licencia puede suspenderse hasta por tres años, y usted puede terminar la suspensión llegando a un acuerdo de pago con los demás involucrados en el choque.","p":"Correcto. Hasta tres años, a menos que llegue a un acuerdo."},"ref":{"doc":"AK","page":10}},{"id":"ak-066","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, after a crash, when must you contact the police right away?","o":["Only when a car must be towed","Only when the crash is on a highway","Only when someone is killed","When someone is hurt or damage is $2,000 or more"],"h1":"There is a dollar amount for damage.","h2":"In Alaska, you must call the police right away if anyone is hurt or the total damage is $2,000 or more.","p":"Right. Call if someone is hurt or damage is $2,000 or more."},"es":{"q":"En Alaska, después de un choque, ¿cuándo debe llamar a la policía de inmediato?","o":["Solo cuando hay que remolcar un carro","Solo cuando el choque es en una carretera","Solo cuando alguien muere","Cuando alguien está herido o los daños son de $2,000 o más"],"h1":"Hay una cantidad de dinero para los daños.","h2":"En Alaska, debe llamar a la policía de inmediato si alguien está herido o si los daños en total son de $2,000 o más.","p":"Correcto. Llame si hay heridos o daños de $2,000 o más."},"ref":{"doc":"AK","page":11}},{"id":"ak-067","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, you have a crash with injuries outside any city or town. Whom should you contact?","o":["The nearest city police department","The Alaska State Troopers","Your insurance company only","The DMV, within 30 days"],"h1":"Outside a municipality, a state agency answers.","h2":"In Alaska, if a crash that must be reported happens outside a municipality, you contact the Alaska State Troopers right away.","p":"Right. Outside a municipality, call the State Troopers."},"es":{"q":"En Alaska, usted tiene un choque con heridos fuera de cualquier ciudad o pueblo. ¿A quién debe llamar?","o":["Al departamento de policía de la ciudad más cercana","A los Alaska State Troopers (policía estatal)","Solo a su compañía de seguros","Al DMV, dentro de 30 días"],"h1":"Fuera de un municipio, responde una agencia del estado.","h2":"En Alaska, si un choque que se debe reportar ocurre fuera de un municipio, debe llamar de inmediato a los Alaska State Troopers.","p":"Correcto. Fuera de un municipio, llame a la policía estatal."},"ref":{"doc":"AK","page":11}},{"id":"ak-068","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, besides 12 points in 12 months, which point total also leads to a required suspension?","o":["10 points in 36 months","15 points in 18 months","18 points in 24 months","24 points in 48 months"],"h1":"The time period is two years.","h2":"In Alaska, getting 18 points in 24 months also requires a suspension or revocation of your license.","p":"Right. 18 points in 24 months also means suspension."},"es":{"q":"En Alaska, además de 12 puntos en 12 meses, ¿qué otro total de puntos trae una suspensión obligatoria?","o":["10 puntos en 36 meses","15 puntos en 18 meses","18 puntos en 24 meses","24 puntos en 48 meses"],"h1":"El período es de dos años.","h2":"En Alaska, acumular 18 puntos en 24 meses también exige la suspensión o revocación de su licencia.","p":"Correcto. 18 puntos en 24 meses también significan suspensión."},"ref":{"doc":"AK","page":11}},{"id":"ak-069","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how often may you take a defensive driving course to reduce the points on your record?","o":["Once every 12 months","Once every month","Once in your life","Once every five years"],"h1":"It is once a year.","h2":"In Alaska, you may take a defensive driving course for a point reduction once every 12 months.","p":"Right. Once every 12 months."},"es":{"q":"En Alaska, ¿con qué frecuencia puede tomar un curso de manejo defensivo para reducir los puntos en su récord?","o":["Una vez cada 12 meses","Una vez al mes","Una vez en la vida","Una vez cada cinco años"],"h1":"Es una vez al año.","h2":"En Alaska, puede tomar un curso de manejo defensivo para reducir puntos una vez cada 12 meses.","p":"Correcto. Una vez cada 12 meses."},"ref":{"doc":"AK","page":11}},{"id":"ak-070","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, how many points does a conviction for driving under the influence add to your record?","o":["2 points","4 points","6 points","10 points"],"h1":"It is the highest value on the point table.","h2":"In Alaska, a conviction for driving under the influence adds 10 points to your driving record.","p":"Right. A DUI adds 10 points."},"es":{"q":"En Alaska, ¿cuántos puntos agrega a su récord una condena por manejar bajo la influencia?","o":["2 puntos","4 puntos","6 puntos","10 puntos"],"h1":"Es el valor más alto de la tabla de puntos.","h2":"En Alaska, una condena por manejar bajo la influencia agrega 10 puntos a su récord de manejo.","p":"Correcto. Manejar bajo la influencia agrega 10 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-071","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, how many points are given for leaving the scene of a crash?","o":["4 points","9 points","6 points","2 points"],"h1":"It is just under the top value of 10.","h2":"In Alaska, leaving the scene of a crash adds 9 points to your driving record.","p":"Right. Leaving the scene adds 9 points."},"es":{"q":"En Alaska, ¿cuántos puntos se dan por irse del lugar de un choque?","o":["4 puntos","9 puntos","6 puntos","2 puntos"],"h1":"Es justo debajo del valor más alto, que es 10.","h2":"En Alaska, irse del lugar de un choque agrega 9 puntos a su récord de manejo.","p":"Correcto. Irse del lugar del choque agrega 9 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-072","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many points are given for not stopping for a school bus that is loading or unloading children?","o":["2 points","4 points","6 points","10 points"],"h1":"It is the same as for driving without insurance.","h2":"In Alaska, failing to stop for a school bus while it is loading or unloading adds 6 points to your record.","p":"Right. Not stopping for a school bus adds 6 points."},"es":{"q":"En Alaska, ¿cuántos puntos se dan por no detenerse ante un autobús escolar que está subiendo o bajando niños?","o":["2 puntos","4 puntos","6 puntos","10 puntos"],"h1":"Es lo mismo que por manejar sin seguro.","h2":"En Alaska, no detenerse ante un autobús escolar mientras suben o bajan niños agrega 6 puntos a su récord.","p":"Correcto. No detenerse ante un autobús escolar agrega 6 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-073","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many points are given for driving 20 mph or more over the speed limit?","o":["6 points","2 points","4 points","9 points"],"h1":"10 to 19 mph over gives 4 points; this is the next step up.","h2":"In Alaska, driving 20 mph or more over the speed limit adds 6 points to your record.","p":"Right. 20 mph or more over adds 6 points."},"es":{"q":"En Alaska, ¿cuántos puntos se dan por manejar a 20 mph o más por encima del límite de velocidad?","o":["6 puntos","2 puntos","4 puntos","9 puntos"],"h1":"De 10 a 19 mph por encima da 4 puntos; esto es el siguiente nivel.","h2":"En Alaska, manejar a 20 mph o más por encima del límite de velocidad agrega 6 puntos a su récord.","p":"Correcto. 20 mph o más por encima agrega 6 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-074","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, after a crash, an officer asks you to blow into a portable breath tester at the scene. What is refusing this preliminary test?","o":["It is always allowed with no penalty","It is a felony","It is only a warning","It is an infraction"],"h1":"It is a minor offense, but still an offense.","h2":"In Alaska, refusing a preliminary breath test at the scene is an infraction.","p":"Right. Refusing the preliminary breath test is an infraction."},"es":{"q":"En Alaska, después de un choque, un oficial le pide soplar en un aparato portátil de aliento en el lugar. ¿Qué es negarse a esta prueba preliminar?","o":["Siempre se permite, sin castigo","Es un delito grave","Es solo una advertencia","Es una infracción"],"h1":"Es una falta menor, pero sigue siendo una falta.","h2":"En Alaska, negarse a una prueba preliminar de aliento en el lugar es una infracción.","p":"Correcto. Negarse a la prueba preliminar de aliento es una infracción."},"ref":{"doc":"AK","page":14}},{"id":"ak-075","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, a driver with one earlier DUI conviction is arrested again and tests 0.08 or more. How long will the DMV revoke the license?","o":["90 days","One year","Three years","Five years"],"h1":"A first offense is 90 days; this is the next step.","h2":"In Alaska, the DMV revokes the license for one year when the driver has one earlier DUI or refusal conviction.","p":"Right. With one earlier conviction, it is one year."},"es":{"q":"En Alaska, un conductor con una condena anterior por manejar bajo la influencia es arrestado otra vez y su prueba marca 0.08 o más. ¿Por cuánto tiempo le revocará la licencia el DMV?","o":["90 días","Un año","Tres años","Cinco años"],"h1":"La primera vez son 90 días; este es el siguiente nivel.","h2":"En Alaska, el DMV revoca la licencia por un año cuando el conductor tiene una condena anterior por manejar bajo la influencia o por negarse a la prueba.","p":"Correcto. Con una condena anterior, es un año."},"ref":{"doc":"AK","page":16}},{"id":"ak-076","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, a person uses a fake driver's license to buy alcohol for the first time. How long can the DMV revoke their driving privilege?","o":["10 days","30 days","60 days","Two years"],"h1":"It is about two months.","h2":"In Alaska, using a false or fraudulent license to get alcohol can lead to a 60-day revocation for a first offense.","p":"Right. A first offense means 60 days."},"es":{"q":"En Alaska, una persona usa una licencia falsa para comprar alcohol por primera vez. ¿Por cuánto tiempo puede el DMV revocarle el privilegio de manejar?","o":["10 días","30 días","60 días","Dos años"],"h1":"Son unos dos meses.","h2":"En Alaska, usar una licencia falsa o fraudulenta para obtener alcohol puede traer una revocación de 60 días por la primera vez.","p":"Correcto. La primera vez son 60 días."},"ref":{"doc":"AK","page":16}},{"id":"ak-077","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, the DMV gives you a notice that your license will be revoked after a DUI arrest. How soon must you ask in writing for a hearing?","o":["Within 7 days","Within 30 days","Within 60 days","Within one year"],"h1":"It is about one week.","h2":"In Alaska, you must ask for an administrative hearing in writing within 7 days of the date the notice was issued.","p":"Right. You have 7 days to ask for a hearing."},"es":{"q":"En Alaska, el DMV le entrega un aviso de que su licencia será revocada después de un arresto por manejar bajo la influencia. ¿En cuánto tiempo debe pedir por escrito una audiencia?","o":["Dentro de 7 días","Dentro de 30 días","Dentro de 60 días","Dentro de un año"],"h1":"Es más o menos una semana.","h2":"En Alaska, debe pedir una audiencia administrativa por escrito dentro de los 7 días de la fecha en que se emitió el aviso.","p":"Correcto. Tiene 7 días para pedir una audiencia."},"ref":{"doc":"AK","page":17}},{"id":"ak-078","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, after a second DUI conviction, how long must an ignition interlock device be on any vehicle you drive?","o":["3 months","6 months","30 months","12 months"],"h1":"Each conviction adds six months.","h2":"In Alaska, after a second DUI or refusal conviction, you must use an ignition interlock device for 12 months.","p":"Right. A second conviction means 12 months."},"es":{"q":"En Alaska, después de una segunda condena por manejar bajo la influencia, ¿por cuánto tiempo debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje?","o":["3 meses","6 meses","30 meses","12 meses"],"h1":"Cada condena agrega seis meses.","h2":"En Alaska, después de una segunda condena por manejar bajo la influencia o por negarse a la prueba, debe usar un dispositivo de bloqueo de encendido por 12 meses.","p":"Correcto. Una segunda condena significa 12 meses."},"ref":{"doc":"AK","page":19}},{"id":"ak-079","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, a 30-year-old passenger is not wearing a seat belt. Who gets the ticket?","o":["The driver","The passenger","The car owner","No one, adults may choose"],"h1":"The driver is responsible only for younger passengers.","h2":"In Alaska, passengers 18 and older get their own ticket for not wearing a seat belt; the driver is responsible for passengers under 16.","p":"Right. An adult passenger gets the ticket."},"es":{"q":"En Alaska, un pasajero de 30 años no lleva puesto el cinturón de seguridad. ¿Quién recibe la multa?","o":["El conductor","El pasajero","El dueño del carro","Nadie, los adultos pueden decidir"],"h1":"El conductor es responsable solo de los pasajeros más jóvenes.","h2":"En Alaska, los pasajeros de 18 años o más reciben su propia multa por no usar el cinturón; el conductor es responsable de los pasajeros menores de 16.","p":"Correcto. El pasajero adulto recibe la multa."},"ref":{"doc":"AK","page":21}},{"id":"ak-080","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, a 6-year-old is 48 inches tall and weighs 45 pounds. How must the child ride?","o":["In a booster seat used with a seat belt","With only the lap belt","In the front seat with a seat belt","On an adult's lap"],"h1":"The child is over 4, under 8 and shorter than 57 inches.","h2":"In Alaska, a child over 4 and under 8 who is under 57 inches tall and weighs 20 to 65 pounds must ride in a booster seat or other approved child seat.","p":"Right. This child needs a booster seat."},"es":{"q":"En Alaska, un niño de 6 años mide 48 pulgadas y pesa 45 libras. ¿Cómo debe viajar?","o":["En un asiento elevado (booster) usado con el cinturón","Solo con el cinturón de la cintura","En el asiento de adelante con el cinturón","En las piernas de un adulto"],"h1":"El niño tiene más de 4 años, menos de 8 y mide menos de 57 pulgadas.","h2":"En Alaska, un niño de más de 4 y menos de 8 años que mide menos de 57 pulgadas y pesa de 20 a 65 libras debe viajar en un asiento elevado u otro asiento infantil aprobado.","p":"Correcto. Este niño necesita un asiento elevado."},"ref":{"doc":"AK","page":21}},{"id":"ak-081","scope":"AK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alaska, what can happen to a driver who does not properly restrain a passenger under 16?","o":["Only a written warning","A $15 fine and no points","A fine of up to $50 and two points","A 90-day suspension"],"h1":"There is a fine and points on the license.","h2":"In Alaska, a driver who fails to restrain a passenger under 16 may be fined up to $50 and get two points.","p":"Right. Up to $50 and two points."},"es":{"q":"En Alaska, ¿qué le puede pasar a un conductor que no asegura bien a un pasajero menor de 16 años?","o":["Solo una advertencia por escrito","Una multa de $15 y ningún punto","Una multa de hasta $50 y dos puntos","Una suspensión de 90 días"],"h1":"Hay una multa y puntos en la licencia.","h2":"En Alaska, un conductor que no asegura a un pasajero menor de 16 años puede recibir una multa de hasta $50 y dos puntos.","p":"Correcto. Hasta $50 y dos puntos."},"ref":{"doc":"AK","page":22}},{"id":"ak-082","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, you are towing a trailer on a wet road. What following time does the driver manual recommend?","o":["Two seconds","Three seconds","Four seconds","Six seconds or more"],"h1":"Add extra time to the usual four seconds.","h2":"In Alaska, the manual says to increase the four-second following time to six seconds or more when towing a trailer or when the road is wet or slippery.","p":"Right. Use six seconds or more."},"es":{"q":"En Alaska, usted remolca un tráiler en una carretera mojada. ¿Qué distancia de seguimiento en segundos recomienda el manual?","o":["Dos segundos","Tres segundos","Cuatro segundos","Seis segundos o más"],"h1":"Agregue tiempo a los cuatro segundos de siempre.","h2":"En Alaska, el manual dice que aumente los cuatro segundos de distancia a seis segundos o más cuando remolque un tráiler o cuando la carretera esté mojada o resbalosa.","p":"Correcto. Use seis segundos o más."},"ref":{"doc":"AK","page":27}},{"id":"ak-083","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, the manual recommends four seconds, but what is the shortest following distance the state regulation requires?","o":["One second","Two seconds","Five seconds","One car length for every 20 mph"],"h1":"It is half of the manual's advice.","h2":"In Alaska, the regulation 13 AAC 02.090 requires at least a two-second following distance, while the manual recommends four seconds.","p":"Right. The regulation requires at least two seconds."},"es":{"q":"En Alaska, el manual recomienda cuatro segundos, pero ¿cuál es la distancia de seguimiento más corta que exige el reglamento del estado?","o":["Un segundo","Dos segundos","Cinco segundos","Un carro de distancia por cada 20 mph"],"h1":"Es la mitad de lo que aconseja el manual.","h2":"En Alaska, el reglamento 13 AAC 02.090 exige una distancia de seguimiento de al menos dos segundos, aunque el manual recomienda cuatro segundos.","p":"Correcto. El reglamento exige al menos dos segundos."},"ref":{"doc":"AK","page":27}},{"id":"ak-084","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, if no sign shows a different limit, what is the top speed in a school zone?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is the same as the business district limit.","h2":"In Alaska, the speed limit in a school zone is 20 mph unless a sign shows a different limit.","p":"Right. The school zone limit is 20 mph."},"es":{"q":"En Alaska, si ningún letrero indica otro límite, ¿cuál es la velocidad máxima en una zona escolar?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es igual al límite de una zona comercial.","h2":"En Alaska, el límite de velocidad en una zona escolar es de 20 mph, a menos que un letrero indique otro límite.","p":"Correcto. El límite en zona escolar es de 20 mph."},"ref":{"doc":"AK","page":29}},{"id":"ak-085","scope":"AK","cat":"signals","sign":null,"c":0,"en":{"q":"In Alaska, before you turn, for how far must you signal without stopping?","o":["The last 100 feet","The last 25 feet","The last 50 feet","The last mile"],"h1":"It is a little longer than a basketball court.","h2":"In Alaska, you must signal continuously during the last 100 feet before you turn.","p":"Right. Signal for the last 100 feet."},"es":{"q":"En Alaska, antes de dar vuelta, ¿durante qué distancia debe señalizar sin parar?","o":["Los últimos 100 pies","Los últimos 25 pies","Los últimos 50 pies","La última milla"],"h1":"Es un poco más que el largo de una cancha de básquetbol.","h2":"En Alaska, debe señalizar sin parar durante los últimos 100 pies antes de dar vuelta.","p":"Correcto. Señalice durante los últimos 100 pies."},"ref":{"doc":"AK","page":30}},{"id":"ak-086","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, you may not pass another vehicle when you are within what distance of an intersection or railroad crossing?","o":["25 feet","100 feet","500 feet","1,000 feet"],"h1":"It is the same distance you signal before a turn.","h2":"In Alaska, you may not pass when you are within 100 feet of an intersection or railroad crossing, or while crossing one.","p":"Right. No passing within 100 feet."},"es":{"q":"En Alaska, ¿a menos de qué distancia de una intersección o un cruce de tren no puede rebasar a otro vehículo?","o":["25 pies","100 pies","500 pies","1,000 pies"],"h1":"Es la misma distancia en que señaliza antes de una vuelta.","h2":"En Alaska, no puede rebasar cuando está a menos de 100 pies de una intersección o un cruce de tren, ni mientras lo cruza.","p":"Correcto. No se rebasa a menos de 100 pies."},"ref":{"doc":"AK","page":37}},{"id":"ak-087","scope":"AK","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alaska, you have a driver's license and get a ticket for running a stop sign on your bicycle. What happens to your driving record?","o":["You get 4 points","You get 2 points","Your license is suspended","No points are added"],"h1":"State law treats bicycle tickets differently for points.","h2":"In Alaska, no points are put on your driving record for traffic violations made while riding a bicycle.","p":"Right. Bicycle violations add no points."},"es":{"q":"En Alaska, usted tiene licencia de manejar y recibe una multa por pasarse un alto en su bicicleta. ¿Qué pasa con su récord de manejo?","o":["Recibe 4 puntos","Recibe 2 puntos","Le suspenden la licencia","No se agregan puntos"],"h1":"La ley del estado trata distinto las multas en bicicleta en cuanto a los puntos.","h2":"En Alaska, no se ponen puntos en su récord de manejo por infracciones de tránsito cometidas en bicicleta.","p":"Correcto. Las infracciones en bicicleta no agregan puntos."},"ref":{"doc":"AK","page":45}},{"id":"ak-088","scope":"AK","cat":"signals","sign":null,"c":2,"en":{"q":"In Alaska, you are following another car at night with your high beams on. You must switch to low beams when you are within what distance?","o":["100 feet","200 feet","300 feet","1,000 feet"],"h1":"It is less than the 500 feet used for oncoming cars.","h2":"In Alaska, you must dim to low beams when you are 300 feet or less behind a vehicle going the same way.","p":"Right. Dim within 300 feet of a car ahead."},"es":{"q":"En Alaska, de noche usted va detrás de otro carro con las luces altas. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","300 pies","1,000 pies"],"h1":"Es menos que los 500 pies que se usan para carros que vienen de frente.","h2":"En Alaska, debe cambiar a luces bajas cuando está a 300 pies o menos detrás de un vehículo que va en su misma dirección.","p":"Correcto. Cambie a luces bajas a 300 pies del carro de adelante."},"ref":{"doc":"AK","page":55}},{"id":"ak-089","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, a moose is killed when a car hits it. Who owns the moose?","o":["The State of Alaska","The driver who hit it","The owner of the nearest land","Anyone who stops to take it"],"h1":"Big game hit by a vehicle does not belong to the driver.","h2":"In Alaska, big game animals killed or injured in a vehicle collision are the property of the state.","p":"Right. The animal belongs to the state."},"es":{"q":"En Alaska, un alce muere cuando un carro lo golpea. ¿De quién es el alce?","o":["Del estado de Alaska","Del conductor que lo golpeó","Del dueño del terreno más cercano","De cualquiera que se detenga a llevárselo"],"h1":"La caza mayor golpeada por un vehículo no es del conductor.","h2":"En Alaska, los animales de caza mayor muertos o heridos en un choque con un vehículo son propiedad del estado.","p":"Correcto. El animal es del estado."},"ref":{"doc":"AK","page":60}},{"id":"ak-090","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Alaska, it is illegal to park closer than 15 feet to a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Alaska, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Alaska, es ilegal estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"ref":{"doc":"AK","page":62}},{"id":"ak-091","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, you park at night beside a road outside city limits. When may you leave your parking lights or low beams off?","o":["When you will be back within an hour","When the moon is bright","When your hazard lights work","When it is 8 feet or more from the pavement"],"h1":"It depends on how far the car is from the pavement.","h2":"In Alaska, a car parked beside a road outside city limits at night must have parking lights or low beams on unless it is at least 8 feet from the edge of the pavement.","p":"Right. Lights may be off only 8 feet or more from the pavement."},"es":{"q":"En Alaska, usted se estaciona de noche al lado de una carretera fuera de la ciudad. ¿Cuándo puede dejar apagadas las luces de estacionamiento o las luces bajas?","o":["Cuando vuelva en menos de una hora","Cuando la luna brille mucho","Cuando funcionen sus luces intermitentes","Cuando esté a 8 pies o más del pavimento"],"h1":"Depende de qué tan lejos esté el carro del pavimento.","h2":"En Alaska, un carro estacionado de noche al lado de una carretera fuera de la ciudad debe tener encendidas las luces de estacionamiento o las bajas, a menos que esté al menos a 8 pies del borde del pavimento.","p":"Correcto. Las luces pueden ir apagadas solo a 8 pies o más del pavimento."},"ref":{"doc":"AK","page":62}},{"id":"ak-092","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, besides a car, what else may you drive with a regular Class D license?","o":["A motorcycle of any size","A motorcycle or scooter under 50cc","A three-wheeled motorcycle of 50cc or more","A school bus with no children on it"],"h1":"Think of the smallest engines.","h2":"In Alaska, a Class D license also lets you drive a motorcycle or motor scooter with an engine smaller than 50cc.","p":"Right. Class D covers motorcycles and scooters under 50cc."},"es":{"q":"En Alaska, además de un carro, ¿qué más puede manejar con una licencia normal de Clase D?","o":["Una motocicleta de cualquier tamaño","Una motocicleta o motoneta de menos de 50cc","Una motocicleta de tres ruedas de 50cc o más","Un autobús escolar sin niños"],"h1":"Piense en los motores más pequeños.","h2":"En Alaska, una licencia de Clase D también le permite manejar una motocicleta o motoneta con motor de menos de 50cc.","p":"Correcto. La Clase D incluye motocicletas y motonetas de menos de 50cc."},"ref":{"doc":"AK","page":2}},{"id":"ak-093","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, a student has an IE instruction permit. Who must supervise the student's driving?","o":["Any licensed driver 18 or older","A parent or legal guardian only","Any adult who rides in the back seat","A licensed driver training school instructor"],"h1":"This permit is tied to a driving school.","h2":"In Alaska, an IE permit is valid only while the driver is supervised by a licensed driver training school instructor.","p":"Right. The IE permit is for driving with a driving school instructor."},"es":{"q":"En Alaska, un estudiante tiene un permiso de aprendizaje IE. ¿Quién debe supervisar su manejo?","o":["Cualquier conductor con licencia de 18 años o más","Solo un padre o tutor legal","Cualquier adulto sentado atrás","Un instructor con licencia de una escuela de manejo"],"h1":"Este permiso está ligado a una escuela de manejo.","h2":"En Alaska, un permiso IE solo es válido mientras el conductor está supervisado por un instructor con licencia de una escuela de manejo.","p":"Correcto. El permiso IE es para manejar con un instructor de escuela de manejo."},"ref":{"doc":"AK","page":2}},{"id":"ak-094","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, a soldier keeps a home and license in another state. Their 17-year-old son lives with them in Alaska and wants to drive. What does he need?","o":["Nothing, if the soldier's license is valid","Only his parent's military ID","An Alaska driver's license","A letter from the base commander"],"h1":"The exemption covers the service member and spouse, not the children.","h2":"In Alaska, dependents of military members, other than the spouse, must get an Alaska license to drive in the state.","p":"Right. Military dependents other than the spouse need an Alaska license."},"es":{"q":"En Alaska, un soldado mantiene su casa y su licencia en otro estado. Su hijo de 17 años vive con él en Alaska y quiere manejar. ¿Qué necesita el hijo?","o":["Nada, si la licencia del soldado es válida","Solo la identificación militar de su padre","Una licencia de manejo de Alaska","Una carta del comandante de la base"],"h1":"La excepción cubre al militar y a su cónyuge, no a los hijos.","h2":"En Alaska, los dependientes de militares, aparte del cónyuge, deben obtener una licencia de Alaska para manejar en el estado.","p":"Correcto. Los dependientes militares, aparte del cónyuge, necesitan una licencia de Alaska."},"ref":{"doc":"AK","page":5}},{"id":"ak-095","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, what may you give the DMV instead of taking its vision test?","o":["A certified statement from a physician or optometrist","A photo of your eyeglasses prescription","A note from your employer","A promise to wear glasses"],"h1":"An eye professional can vouch for your vision.","h2":"In Alaska, instead of the DMV vision test, you may give a certified statement from a licensed physician or optometrist that your vision meets the standard.","p":"Right. A certified statement from a physician or optometrist is accepted."},"es":{"q":"En Alaska, ¿qué puede entregar al DMV en lugar de hacer su examen de la vista?","o":["Una declaración certificada de un médico u optometrista","Una foto de la receta de sus lentes","Una nota de su empleador","La promesa de usar lentes"],"h1":"Un profesional de la vista puede confirmar cómo ve usted.","h2":"En Alaska, en lugar del examen de la vista del DMV, puede entregar una declaración certificada de un médico u optometrista con licencia que diga que su vista cumple la norma.","p":"Correcto. Se acepta una declaración certificada de un médico u optometrista."},"ref":{"doc":"AK","page":6}},{"id":"ak-096","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, your driver's license expired some time ago. When must you take the written test again?","o":["When it has been expired for over one month","When it has been expired for over one year","Only when it has been expired for over ten years","Every time you renew, no matter what"],"h1":"It is longer than a few months.","h2":"In Alaska, you must take the written test again if your driving privileges have been expired for over one year.","p":"Right. Expired for over a year means a new written test."},"es":{"q":"En Alaska, su licencia de manejo venció hace un tiempo. ¿Cuándo debe volver a hacer el examen escrito?","o":["Cuando lleva vencida más de un mes","Cuando lleva vencida más de un año","Solo cuando lleva vencida más de diez años","Cada vez que la renueve, sin excepción"],"h1":"Es más que unos pocos meses.","h2":"En Alaska, debe volver a hacer el examen escrito si sus privilegios de manejo llevan vencidos más de un año.","p":"Correcto. Más de un año vencida significa un nuevo examen escrito."},"ref":{"doc":"AK","page":7}},{"id":"ak-097","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, who must take the driving (road) test, besides people who were never licensed?","o":["Anyone who moves to a new address","Anyone who got one speeding ticket","Anyone over 65 who renews a license","Anyone with no valid license in the past 5 years"],"h1":"It depends on how long you have gone without a valid license.","h2":"In Alaska, the road test is required for people who have not had a valid license in the past 5 years, as well as new drivers and people whose privileges were revoked.","p":"Right. No valid license for 5 years means a new road test."},"es":{"q":"En Alaska, además de quienes nunca tuvieron licencia, ¿quién debe hacer el examen práctico de manejo?","o":["Cualquiera que cambie de dirección","Cualquiera que tenga una multa por velocidad","Cualquier persona mayor de 65 que renueve","Cualquiera sin licencia válida en los últimos 5 años"],"h1":"Depende de cuánto tiempo ha estado sin licencia válida.","h2":"En Alaska, el examen práctico se exige a quienes no han tenido una licencia válida en los últimos 5 años, además de los conductores nuevos y quienes tuvieron su privilegio revocado.","p":"Correcto. Sin licencia válida por 5 años, hay que hacer el examen práctico."},"ref":{"doc":"AK","page":7}},{"id":"ak-098","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, your license was once suspended by another state. What must you get before Alaska will issue you a license?","o":["A letter from your insurance company","A new birth certificate","Written proof from that state that the suspension has ended","Nothing, because Alaska ignores other states"],"h1":"The other state has to confirm something.","h2":"In Alaska, if another state suspended or revoked your privileges, you must get written proof from that state that the suspension or revocation has ended.","p":"Right. You need written proof from the other state that it ended."},"es":{"q":"En Alaska, otro estado suspendió su licencia en el pasado. ¿Qué debe conseguir antes de que Alaska le dé una licencia?","o":["Una carta de su compañía de seguros","Un nuevo certificado de nacimiento","Prueba escrita de ese estado de que la suspensión terminó","Nada, porque Alaska no toma en cuenta otros estados"],"h1":"El otro estado tiene que confirmar algo.","h2":"En Alaska, si otro estado suspendió o revocó sus privilegios, debe conseguir prueba escrita de ese estado de que la suspensión o revocación terminó.","p":"Correcto. Necesita prueba escrita del otro estado de que terminó."},"ref":{"doc":"AK","page":9}},{"id":"ak-099","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, you were in a crash with injuries, but the other driver caused it. Must you send the DMV proof of insurance?","o":["Yes, every driver in the crash must send it","No, only the driver who caused the crash","No, if the police wrote a report","Only if your car was damaged"],"h1":"Fault does not matter for this rule.","h2":"In Alaska, every driver in a crash with injury, death or enough property damage must give the DMV proof of insurance, even a driver who did not cause it.","p":"Right. All drivers must send proof of insurance, at fault or not."},"es":{"q":"En Alaska, usted tuvo un choque con heridos, pero el otro conductor lo causó. ¿Debe enviar al DMV prueba de seguro?","o":["Sí, todos los conductores del choque deben enviarla","No, solo el conductor que causó el choque","No, si la policía hizo un informe","Solo si su carro sufrió daños"],"h1":"La culpa no importa para esta regla.","h2":"En Alaska, todo conductor en un choque con heridos, muertos o suficientes daños materiales debe dar al DMV prueba de seguro, aunque no lo haya causado.","p":"Correcto. Todos los conductores deben enviar prueba de seguro, tengan la culpa o no."},"ref":{"doc":"AK","page":10}},{"id":"ak-100","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, you hit a fence and cannot find the owner. What must the note you leave include?","o":["Only your license plate number","Your name, address and phone number","Your insurance policy number only","Just an apology and the date"],"h1":"The owner must be able to find and contact you.","h2":"In Alaska, if you hit an unattended vehicle or private property and cannot find the owner, you must leave a written note with your name, address and phone number.","p":"Right. Leave your name, address and phone number."},"es":{"q":"En Alaska, usted choca contra una cerca y no encuentra al dueño. ¿Qué debe incluir la nota que deje?","o":["Solo el número de su placa","Su nombre, dirección y número de teléfono","Solo el número de su póliza de seguro","Solo una disculpa y la fecha"],"h1":"El dueño debe poder encontrarlo y comunicarse con usted.","h2":"En Alaska, si choca contra un vehículo sin nadie o una propiedad privada y no encuentra al dueño, debe dejar una nota escrita con su nombre, dirección y número de teléfono.","p":"Correcto. Deje su nombre, dirección y teléfono."},"ref":{"doc":"AK","page":11}},{"id":"ak-101","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, when does the DMV send a driver a warning letter about points?","o":["After the very first ticket","Only after the license is suspended","When the driver renews the license","When the driver is halfway to a point suspension"],"h1":"It comes partway toward a suspension.","h2":"In Alaska, a driver gets a warning letter upon reaching the halfway mark toward a point suspension.","p":"Right. The warning comes at the halfway mark."},"es":{"q":"En Alaska, ¿cuándo envía el DMV a un conductor una carta de advertencia por puntos?","o":["Después de la primera multa","Solo después de suspender la licencia","Cuando el conductor renueva la licencia","Cuando el conductor llega a la mitad del camino hacia una suspensión"],"h1":"Llega a medio camino de una suspensión.","h2":"En Alaska, un conductor recibe una carta de advertencia al llegar a la mitad de los puntos que causan una suspensión.","p":"Correcto. La advertencia llega a la mitad del camino."},"ref":{"doc":"AK","page":11}},{"id":"ak-102","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how many points are given for following another vehicle too closely?","o":["2 points","6 points","4 points","10 points"],"h1":"It is the same as for most failure-to-yield tickets.","h2":"In Alaska, a conviction for following too closely adds 4 points to your driving record.","p":"Right. Following too closely is 4 points."},"es":{"q":"En Alaska, ¿cuántos puntos se dan por seguir a otro vehículo demasiado cerca?","o":["2 puntos","6 puntos","4 puntos","10 puntos"],"h1":"Es lo mismo que por la mayoría de las multas por no ceder el paso.","h2":"En Alaska, una condena por seguir demasiado cerca agrega 4 puntos a su historial de manejo.","p":"Correcto. Seguir demasiado cerca son 4 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-103","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, how many points are given for failing to yield to an authorized emergency vehicle?","o":["6 points","2 points","4 points","9 points"],"h1":"It is one of the more serious violations, but less than a DUI.","h2":"In Alaska, failing to yield to an authorized emergency vehicle adds 6 points to your driving record.","p":"Right. Not yielding to an emergency vehicle is 6 points."},"es":{"q":"En Alaska, ¿cuántos puntos se dan por no ceder el paso a un vehículo de emergencia autorizado?","o":["6 puntos","2 puntos","4 puntos","9 puntos"],"h1":"Es una de las faltas más graves, pero menos que manejar ebrio.","h2":"En Alaska, no ceder el paso a un vehículo de emergencia autorizado agrega 6 puntos a su historial de manejo.","p":"Correcto. No ceder el paso a un vehículo de emergencia son 6 puntos."},"ref":{"doc":"AK","page":12}},{"id":"ak-104","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, your license was suspended. How do you usually prove financial responsibility for the future when you get it back?","o":["With a bank statement","With an SR22 insurance filing","With a letter from your employer","With a receipt for a new car"],"h1":"It is a special form your insurance company files.","h2":"In Alaska, after a suspension or revocation you must carry financial responsibility for the future, usually shown by an SR22 insurance filing.","p":"Right. An SR22 filing proves it."},"es":{"q":"En Alaska, su licencia fue suspendida. ¿Cómo prueba normalmente su responsabilidad financiera futura cuando la recupera?","o":["Con un estado de cuenta del banco","Con un formulario de seguro SR22","Con una carta de su empleador","Con el recibo de un carro nuevo"],"h1":"Es un formulario especial que presenta su compañía de seguros.","h2":"En Alaska, después de una suspensión o revocación debe tener responsabilidad financiera para el futuro, que normalmente se prueba con un formulario de seguro SR22.","p":"Correcto. Un formulario SR22 lo prueba."},"ref":{"doc":"AK","page":13}},{"id":"ak-105","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, when may an officer require a driver to give a blood or urine sample under the implied consent law?","o":["At any traffic stop for speeding","Only if the driver signs a form first","Only when renewing a license","After a crash that kills or seriously injures another person"],"h1":"It is about the most serious crashes.","h2":"In Alaska, an officer may require a blood or urine sample from a driver involved in a crash that causes death or serious physical injury to another person.","p":"Right. A crash with death or serious injury allows a blood or urine test."},"es":{"q":"En Alaska, ¿cuándo puede un policía exigir a un conductor una muestra de sangre u orina según la ley de consentimiento implícito?","o":["En cualquier parada por exceso de velocidad","Solo si el conductor firma un formulario antes","Solo al renovar la licencia","Después de un choque que mata o hiere gravemente a otra persona"],"h1":"Se trata de los choques más graves.","h2":"En Alaska, un policía puede exigir una muestra de sangre u orina a un conductor que tuvo un choque que causó la muerte o heridas graves a otra persona.","p":"Correcto. Un choque con muertos o heridos graves permite exigir sangre u orina."},"ref":{"doc":"AK","page":14}},{"id":"ak-106","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, a driver with two earlier DUI convictions is arrested again and tests 0.08 or more. How long will the DMV revoke the license?","o":["90 days","One year","Three years","Five years"],"h1":"Each prior conviction makes it longer.","h2":"In Alaska, the DMV revokes the license for 3 years when the driver has two prior DUI or refusal convictions.","p":"Right. Two prior convictions mean a 3-year revocation."},"es":{"q":"En Alaska, un conductor con dos condenas anteriores por manejar ebrio es arrestado otra vez y su prueba da 0.08 o más. ¿Por cuánto tiempo le revocará la licencia el DMV?","o":["90 días","Un año","Tres años","Cinco años"],"h1":"Cada condena anterior lo hace más largo.","h2":"En Alaska, el DMV revoca la licencia por 3 años cuando el conductor tiene dos condenas anteriores por manejar ebrio o por negarse a la prueba.","p":"Correcto. Dos condenas anteriores significan una revocación de 3 años."},"ref":{"doc":"AK","page":16}},{"id":"ak-107","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a 19-year-old's breath test shows some alcohol, but the court later dismisses the ticket. What happens to the DMV revocation?","o":["The DMV revocation still happens","The revocation is canceled","The revocation becomes a warning","The revocation waits for a new trial"],"h1":"The DMV action is separate from the court case.","h2":"In Alaska, the DMV revokes an under-21 driver's license for driving after drinking even if the criminal citation is dismissed or the driver is found not guilty.","p":"Right. The DMV revocation stands even if the court case is dismissed."},"es":{"q":"En Alaska, la prueba de aliento de una persona de 19 años muestra algo de alcohol, pero después el tribunal anula la multa. ¿Qué pasa con la revocación del DMV?","o":["La revocación del DMV ocurre de todos modos","La revocación se cancela","La revocación se vuelve una advertencia","La revocación espera un nuevo juicio"],"h1":"La acción del DMV es aparte del caso en el tribunal.","h2":"En Alaska, el DMV revoca la licencia de un conductor menor de 21 años por manejar después de beber, aunque se anule la citación o lo declaren no culpable.","p":"Correcto. La revocación del DMV sigue aunque se anule el caso."},"ref":{"doc":"AK","page":16}},{"id":"ak-108","scope":"AK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alaska, you ask for an administrative hearing on time and you have a valid license. What do you get until the hearing?","o":["Nothing; you may not drive at all","A temporary license to drive until the hearing date","A permit to drive only on weekends","A license that lets you drive only to court"],"h1":"You can keep driving for now.","h2":"In Alaska, if you request the hearing on time and have a valid license, you get a temporary license that lets you drive until the hearing date, unless a court has revoked you.","p":"Right. A temporary license lets you drive until the hearing."},"es":{"q":"En Alaska, usted pide una audiencia administrativa a tiempo y tiene una licencia válida. ¿Qué recibe hasta la audiencia?","o":["Nada; no puede manejar","Una licencia temporal para manejar hasta la fecha de la audiencia","Un permiso para manejar solo los fines de semana","Una licencia para manejar solo al tribunal"],"h1":"Puede seguir manejando por ahora.","h2":"En Alaska, si pide la audiencia a tiempo y tiene una licencia válida, recibe una licencia temporal que le permite manejar hasta la fecha de la audiencia, a menos que un tribunal se la haya revocado.","p":"Correcto. Una licencia temporal le permite manejar hasta la audiencia."},"ref":{"doc":"AK","page":17}},{"id":"ak-109","scope":"AK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alaska, after a third DUI conviction, how long must an ignition interlock device be on any vehicle you drive?","o":["6 months","12 months","24 months","18 months"],"h1":"Each conviction adds six months.","h2":"In Alaska, after a third DUI or refusal conviction, an ignition interlock device is required for 18 months.","p":"Right. A third conviction means 18 months with the device."},"es":{"q":"En Alaska, después de una tercera condena por manejar ebrio, ¿por cuánto tiempo debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje?","o":["6 meses","12 meses","24 meses","18 meses"],"h1":"Cada condena agrega seis meses.","h2":"En Alaska, después de una tercera condena por manejar ebrio o negarse a la prueba, se exige un dispositivo de bloqueo de encendido por 18 meses.","p":"Correcto. Una tercera condena significa 18 meses con el dispositivo."},"ref":{"doc":"AK","page":19}},{"id":"ak-110","scope":"AK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alaska, how do the penalties for driving under the influence of a controlled substance compare with those for alcohol?","o":["They are always lower","They apply only to illegal drugs","They are the same","They are only a fine"],"h1":"Alaska treats both kinds of impaired driving alike.","h2":"In Alaska, the penalties for driving under the influence of a controlled substance are the same as for driving under the influence of alcohol.","p":"Right. The penalties are the same."},"es":{"q":"En Alaska, ¿cómo se comparan las penas por manejar bajo la influencia de una sustancia controlada con las del alcohol?","o":["Siempre son menores","Solo se aplican a drogas ilegales","Son las mismas","Son solo una multa"],"h1":"Alaska trata igual los dos tipos de manejo bajo la influencia.","h2":"En Alaska, las penas por manejar bajo la influencia de una sustancia controlada son las mismas que por manejar bajo la influencia del alcohol.","p":"Correcto. Las penas son las mismas."},"ref":{"doc":"AK","page":19}},{"id":"ak-111","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, a 2-year-old child weighs 28 pounds. How must the child ride in a car?","o":["In an approved child safety seat","In a booster seat with the seat belt","In the seat belt alone","On an adult's lap, under the belt"],"h1":"A booster seat is for children over four.","h2":"In Alaska, a child at least 1 but under 5 years old who weighs 20 pounds or more must be secured in an approved child restraint device.","p":"Right. A child that age and size rides in a child safety seat."},"es":{"q":"En Alaska, un niño de 2 años pesa 28 libras. ¿Cómo debe viajar en el carro?","o":["En un asiento de seguridad infantil aprobado","En un asiento elevado con el cinturón","Solo con el cinturón de seguridad","En las piernas de un adulto, bajo el cinturón"],"h1":"El asiento elevado es para niños mayores de cuatro años.","h2":"En Alaska, un niño de al menos 1 año pero menor de 5 que pesa 20 libras o más debe ir sujeto en un asiento de seguridad infantil aprobado.","p":"Correcto. Un niño de esa edad y tamaño viaja en un asiento de seguridad infantil."},"ref":{"doc":"AK","page":21}},{"id":"ak-112","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, what is the fine for an adult who does not wear a seat belt?","o":["$5","$15","$150","$500"],"h1":"It is a small fine.","h2":"In Alaska, an adult seat belt violation carries a $15 fine.","p":"Right. The adult seat belt fine is $15."},"es":{"q":"En Alaska, ¿cuál es la multa para un adulto que no usa el cinturón de seguridad?","o":["$5","$15","$150","$500"],"h1":"Es una multa pequeña.","h2":"En Alaska, no usar el cinturón de seguridad siendo adulto tiene una multa de $15.","p":"Correcto. La multa para adultos es de $15."},"ref":{"doc":"AK","page":22}},{"id":"ak-113","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, an adult is convicted of not wearing a seat belt. How may the court let them skip paying the fine?","o":["By taking a driving test again","By watching a safety video online","By doing one day of road cleanup","By giving the same amount to an emergency medical services group"],"h1":"The money still goes to a good cause.","h2":"In Alaska, the court may waive the $15 seat belt fine if the person donates $15 to an emergency medical services (EMS) organization.","p":"Right. A donation of the same amount to an EMS group can replace the fine."},"es":{"q":"En Alaska, un adulto es condenado por no usar el cinturón de seguridad. ¿Cómo puede el tribunal permitirle no pagar la multa?","o":["Haciendo otra vez el examen de manejo","Viendo un video de seguridad en línea","Haciendo un día de limpieza de carreteras","Donando la misma cantidad a un grupo de servicios médicos de emergencia"],"h1":"El dinero igual va a una buena causa.","h2":"En Alaska, el tribunal puede perdonar la multa de $15 por el cinturón si la persona dona $15 a una organización de servicios médicos de emergencia (EMS).","p":"Correcto. Una donación de la misma cantidad a un grupo EMS puede reemplazar la multa."},"ref":{"doc":"AK","page":22}},{"id":"ak-114","scope":"AK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alaska, which vehicle is an exception to the seat belt law?","o":["Any car driven less than 5 miles","Any pickup truck on a gravel road","A vehicle built before 1965 that never came with belts","Any car going under 25 mph"],"h1":"It is about very old vehicles.","h2":"In Alaska, the seat belt law does not apply to vehicles built before 1965 that did not have safety belts as original equipment.","p":"Right. Pre-1965 vehicles built without belts are an exception."},"es":{"q":"En Alaska, ¿qué vehículo es una excepción a la ley del cinturón de seguridad?","o":["Cualquier carro que recorre menos de 5 millas","Cualquier camioneta en un camino de grava","Un vehículo fabricado antes de 1965 que nunca tuvo cinturones","Cualquier carro a menos de 25 mph"],"h1":"Se trata de vehículos muy antiguos.","h2":"En Alaska, la ley del cinturón no se aplica a vehículos fabricados antes de 1965 que no traían cinturones de fábrica.","p":"Correcto. Los vehículos de antes de 1965 sin cinturones son una excepción."},"ref":{"doc":"AK","page":22}},{"id":"ak-115","scope":"AK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alaska, at an intersection with no signs or signals, who has the right of way over cars?","o":["People walking or riding bicycles","The larger vehicle","The driver going faster","Whoever honks first"],"h1":"Think of the road users with no engine.","h2":"In Alaska, a non-motorized user, such as a person walking or biking, has the right of way over motor vehicles at an uncontrolled intersection.","p":"Right. People walking or biking have the right of way there."},"es":{"q":"En Alaska, en una intersección sin señales ni semáforos, ¿quién tiene el derecho de paso sobre los carros?","o":["Las personas que caminan o van en bicicleta","El vehículo más grande","El conductor que va más rápido","El primero que toque la bocina"],"h1":"Piense en quienes usan el camino sin motor.","h2":"En Alaska, un usuario sin motor, como una persona que camina o va en bicicleta, tiene el derecho de paso sobre los vehículos de motor en una intersección sin control.","p":"Correcto. Las personas que caminan o van en bicicleta tienen el derecho de paso allí."},"ref":{"doc":"AK","page":33}},{"id":"ak-116","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, a slow car is ahead of you on a two-lane highway. May you pass it by driving on the right shoulder?","o":["Yes, if the shoulder is paved","No, passing on the right shoulder is not allowed","Yes, if you honk first","Yes, in daylight only"],"h1":"The shoulder is not a passing lane.","h2":"In Alaska, you may not pass another vehicle on the right shoulder of the highway.","p":"Right. Never pass on the right shoulder."},"es":{"q":"En Alaska, un carro lento va delante de usted en una carretera de dos carriles. ¿Puede rebasarlo manejando por el acotamiento derecho?","o":["Sí, si el acotamiento está pavimentado","No, no se permite rebasar por el acotamiento derecho","Sí, si toca la bocina primero","Sí, solo de día"],"h1":"El acotamiento no es un carril para rebasar.","h2":"En Alaska, no puede rebasar a otro vehículo por el acotamiento derecho de la carretera.","p":"Correcto. Nunca rebase por el acotamiento derecho."},"ref":{"doc":"AK","page":37}},{"id":"ak-117","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, a motorcycle is riding near one side of a wide lane. May you drive beside it in the same lane?","o":["Yes, if the lane is wide enough","Yes, if you stay under the speed limit","Yes, if the rider waves you on","No, it is illegal and very dangerous"],"h1":"A motorcycle needs the whole lane, like a car.","h2":"In Alaska, you must never move into the same lane as a motorcycle, even a wide lane; it is illegal and extremely dangerous.","p":"Right. Never share a lane with a motorcycle."},"es":{"q":"En Alaska, una motocicleta va cerca de un lado de un carril ancho. ¿Puede manejar a su lado en el mismo carril?","o":["Sí, si el carril es bastante ancho","Sí, si no pasa el límite de velocidad","Sí, si el motociclista le hace señas","No, es ilegal y muy peligroso"],"h1":"Una motocicleta necesita todo el carril, igual que un carro.","h2":"En Alaska, nunca debe meterse en el mismo carril que una motocicleta, aunque el carril sea ancho; es ilegal y muy peligroso.","p":"Correcto. Nunca comparta un carril con una motocicleta."},"ref":{"doc":"AK","page":47}},{"id":"ak-118","scope":"AK","cat":"signals","sign":null,"c":2,"en":{"q":"In Alaska, which vehicles must show the orange-and-red slow-moving vehicle triangle?","o":["All trucks over two tons","Every vehicle towing a trailer","Vehicles that travel 25 mph or less","Only school buses"],"h1":"It depends on the vehicle's top speed.","h2":"In Alaska, the slow-moving vehicle emblem is required on all vehicles that travel 25 mph or less.","p":"Right. Vehicles going 25 mph or less need the emblem."},"es":{"q":"En Alaska, ¿qué vehículos deben mostrar el triángulo anaranjado y rojo de vehículo lento?","o":["Todos los camiones de más de dos toneladas","Todo vehículo que jala un remolque","Los vehículos que van a 25 mph o menos","Solo los autobuses escolares"],"h1":"Depende de la velocidad máxima del vehículo.","h2":"En Alaska, el emblema de vehículo lento es obligatorio en todos los vehículos que van a 25 mph o menos.","p":"Correcto. Los vehículos que van a 25 mph o menos necesitan el emblema."},"ref":{"doc":"AK","page":49}},{"id":"ak-119","scope":"AK","cat":"signals","sign":null,"c":0,"en":{"q":"In Alaska, a traffic light has no lights working, and no one is directing traffic. What must you do?","o":["Stop, then yield to traffic coming from your right","Drive through without stopping if it looks clear","Slow down and go, as at a yellow light","Turn around and find another road"],"h1":"The intersection becomes uncontrolled.","h2":"In Alaska, when a signal is completely dark and no one is directing traffic, the intersection is uncontrolled: you must stop and yield to traffic approaching on your right.","p":"Right. Stop and yield to traffic on your right."},"es":{"q":"En Alaska, un semáforo no tiene ninguna luz funcionando y nadie dirige el tráfico. ¿Qué debe hacer?","o":["Parar y luego ceder el paso al tráfico que viene por su derecha","Pasar sin parar si parece despejado","Bajar la velocidad y seguir, como con luz amarilla","Dar la vuelta y buscar otra calle"],"h1":"La intersección queda sin control.","h2":"En Alaska, cuando un semáforo está totalmente apagado y nadie dirige el tráfico, la intersección queda sin control: debe parar y ceder el paso al tráfico que viene por su derecha.","p":"Correcto. Pare y ceda el paso al tráfico de su derecha."},"ref":{"doc":"AK","page":52}},{"id":"ak-120","scope":"AK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alaska, the driver manual says to be prepared to stop at a railroad crossing when a train is within what distance?","o":["500 feet","1,500 feet","300 feet","1 mile"],"h1":"It is more than a quarter mile.","h2":"In Alaska, you should be prepared to stop if a train is within 1,500 feet of the crossing, even at an unmarked crossing.","p":"Right. Be ready to stop when a train is within 1,500 feet."},"es":{"q":"En Alaska, según el manual, ¿a qué distancia del cruce debe estar un tren para que usted esté listo para parar?","o":["500 pies","1,500 pies","300 pies","1 milla"],"h1":"Es más de un cuarto de milla.","h2":"En Alaska, debe estar listo para parar si un tren está a menos de 1,500 pies del cruce, aunque el cruce no tenga señales.","p":"Correcto. Esté listo para parar si el tren está a menos de 1,500 pies."},"ref":{"doc":"AK","page":58}},{"id":"ak-121","scope":"AK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alaska, your car is stuck on the tracks and the crossing lights start to flash. How much time may you have before the train arrives?","o":["About 2 minutes","About 5 minutes","About 1 minute","As little as 20 seconds"],"h1":"It is less than half a minute.","h2":"In Alaska, once the crossing lights start flashing, you may have only 20 seconds to get out before the train reaches the crossing.","p":"Right. You may have only 20 seconds, so get out at once."},"es":{"q":"En Alaska, su carro queda atrapado en las vías y las luces del cruce empiezan a parpadear. ¿Cuánto tiempo puede tener antes de que llegue el tren?","o":["Unos 2 minutos","Unos 5 minutos","Alrededor de 1 minuto","Apenas 20 segundos"],"h1":"Es menos de medio minuto.","h2":"En Alaska, cuando las luces del cruce empiezan a parpadear, puede tener solo 20 segundos para salir antes de que el tren llegue al cruce.","p":"Correcto. Puede tener solo 20 segundos, así que salga de inmediato."},"ref":{"doc":"AK","page":59}},{"id":"ak-122","scope":"AK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alaska, your car breaks down on a highway. Besides raising the hood, how does the manual say you can signal for help?","o":["Leave the headlights on high beam","Put a red cup on the roof","Tie a white cloth on the left door handle or antenna","Open all four doors"],"h1":"Think of a white flag.","h2":"In Alaska, the manual says to raise the hood or tie a white cloth or handkerchief on the left door handle or radio antenna when your vehicle is disabled.","p":"Right. A white cloth on the left door handle or antenna signals trouble."},"es":{"q":"En Alaska, su carro se descompone en una carretera. Además de levantar el cofre, ¿cómo dice el manual que puede pedir ayuda?","o":["Dejando las luces altas encendidas","Poniendo un vaso rojo en el techo","Atando un trapo blanco en la manija de la puerta izquierda o la antena","Abriendo las cuatro puertas"],"h1":"Piense en una bandera blanca.","h2":"En Alaska, el manual dice que levante el cofre o ate un trapo o pañuelo blanco en la manija de la puerta izquierda o en la antena cuando su vehículo esté descompuesto.","p":"Correcto. Un trapo blanco en la manija izquierda o la antena indica un problema."},"ref":{"doc":"AK","page":56}},{"id":"ak-123","scope":"AK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alaska, how close to a stop sign may you park?","o":["No closer than 30 feet","No closer than 10 feet","No closer than 15 feet","No closer than 50 feet"],"h1":"It is twice the distance for a fire hydrant.","h2":"In Alaska, it is illegal to park closer than 30 feet to a stop sign.","p":"Right. Stay at least 30 feet from a stop sign."},"es":{"q":"En Alaska, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["A no menos de 30 pies","A no menos de 10 pies","A no menos de 15 pies","A no menos de 50 pies"],"h1":"Es el doble de la distancia para un hidrante.","h2":"En Alaska, es ilegal estacionarse a menos de 30 pies de una señal de alto.","p":"Correcto. Quédese al menos a 30 pies de una señal de alto."},"ref":{"doc":"AK","page":62}},{"id":"ak-124","scope":"AK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alaska, how close to the entrance of a fire station may you park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 100 feet","No closer than 500 feet"],"h1":"It is the same distance as from a crosswalk.","h2":"In Alaska, it is illegal to park closer than 20 feet to the entrance of a fire station.","p":"Right. Stay at least 20 feet from a fire station entrance."},"es":{"q":"En Alaska, ¿qué tan cerca de la entrada de una estación de bomberos puede estacionarse?","o":["A no menos de 5 pies","A no menos de 20 pies","A no menos de 100 pies","A no menos de 500 pies"],"h1":"Es la misma distancia que de un cruce peatonal.","h2":"En Alaska, es ilegal estacionarse a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Quédese al menos a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"AK","page":62}},{"id":"ak-125","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, when you parallel park, how close to the curb must your wheels be?","o":["Within 24 inches","Within 18 inches","Within 6 feet","Within 12 inches"],"h1":"It is about one foot.","h2":"In Alaska, when you parallel park, your wheels must be within 12 inches of the curb.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En Alaska, cuando se estaciona en paralelo, ¿qué tan cerca de la acera deben quedar sus llantas?","o":["A menos de 24 pulgadas","A menos de 18 pulgadas","A menos de 6 pies","A menos de 12 pulgadas"],"h1":"Es más o menos un pie.","h2":"En Alaska, cuando se estaciona en paralelo, sus llantas deben quedar a menos de 12 pulgadas de la acera.","p":"Correcto. Estaciónese a menos de 12 pulgadas de la acera."},"ref":{"doc":"AK","page":62}},{"id":"ak-126","scope":"AK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alaska, what is the penalty for driving over a fire department hose without permission?","o":["A warning only","A $25 fine and no points","A $100 fine and 2 points","A $1,000 fine and 10 points"],"h1":"It is a fine plus a small number of points.","h2":"In Alaska, driving over a fire hose without a fire official's consent brings a $100 fine and 2 points.","p":"Right. It is a $100 fine and 2 points."},"es":{"q":"En Alaska, ¿cuál es la pena por pasar con el carro sobre una manguera de bomberos sin permiso?","o":["Solo una advertencia","Una multa de $25 y ningún punto","Una multa de $100 y 2 puntos","Una multa de $1,000 y 10 puntos"],"h1":"Es una multa más unos pocos puntos.","h2":"En Alaska, pasar sobre una manguera de bomberos sin el permiso de un oficial de bomberos trae una multa de $100 y 2 puntos.","p":"Correcto. Es una multa de $100 y 2 puntos."},"ref":{"doc":"AK","page":65}},{"id":"ak-127","scope":"AK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alaska, a police officer stops you, and you have a concealed deadly weapon on your body. What must you do?","o":["Tell the officer right away","Say nothing unless asked","Hand the weapon to the officer at once","Get out and put it on the hood"],"h1":"The officer needs to know first.","h2":"In Alaska, if an officer contacts you and you have a concealed deadly weapon on your person, you must tell the officer immediately.","p":"Right. Tell the officer about the weapon right away."},"es":{"q":"En Alaska, un policía lo detiene y usted lleva un arma mortal oculta en el cuerpo. ¿Qué debe hacer?","o":["Decírselo al policía de inmediato","No decir nada a menos que le pregunten","Entregarle el arma al policía enseguida","Bajarse y ponerla sobre el cofre"],"h1":"El policía necesita saberlo primero.","h2":"En Alaska, si un policía se comunica con usted y lleva un arma mortal oculta en su cuerpo, debe decírselo al policía de inmediato.","p":"Correcto. Avise al policía del arma de inmediato."},"ref":{"doc":"AK","page":65}},{"id":"ak-128","scope":"AK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alaska, you are driving down a long hill. What does state law forbid?","o":["Using a lower gear","Coasting in neutral or with the clutch pressed in","Tapping the brakes","Keeping both hands on the wheel"],"h1":"The engine should stay connected to the wheels.","h2":"In Alaska, a driver going downhill may not coast with the gears in neutral or with the clutch disengaged.","p":"Right. Coasting downhill in neutral is not allowed."},"es":{"q":"En Alaska, usted baja por una cuesta larga. ¿Qué prohíbe la ley del estado?","o":["Usar un cambio más bajo","Bajar en neutral o con el clutch presionado","Tocar el freno suavemente","Tener las dos manos en el volante"],"h1":"El motor debe seguir conectado a las ruedas.","h2":"En Alaska, un conductor que baja una cuesta no puede ir en neutral ni con el clutch desembragado.","p":"Correcto. No se permite bajar una cuesta en neutral."},"ref":{"doc":"AK","page":67}},{"id":"ak-129","scope":"AK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alaska, near a curve or hill, you may not turn around on the highway unless you can see how far in each direction?","o":["100 feet","200 feet","50 feet","500 feet"],"h1":"It is longer than a football field.","h2":"In Alaska, do not turn around near a curve or hill unless you can see 500 feet or more in each direction.","p":"Right. You need a view of 500 feet each way."},"es":{"q":"En Alaska, cerca de una curva o una cuesta, ¿qué distancia debe poder ver en cada dirección para dar la vuelta en la carretera?","o":["100 pies","200 pies","50 pies","500 pies"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Alaska, no dé la vuelta cerca de una curva o cuesta a menos que pueda ver 500 pies o más en cada dirección.","p":"Correcto. Necesita ver 500 pies en cada dirección."},"ref":{"doc":"AK","page":67}},{"id":"ak-130","scope":"AK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alaska, you missed your exit on a controlled-access highway. May you back up on the highway or the ramp?","o":["Yes, if your hazard lights are on","Yes, if no cars are close","No, it is illegal unless police or flaggers direct you","Yes, on the shoulder only"],"h1":"Go on to the next exit instead.","h2":"In Alaska, it is illegal to back up on a controlled-access highway or its entrance or exit ramps, unless police, fire or construction flaggers direct you.","p":"Right. Never back up there; take the next exit."},"es":{"q":"En Alaska, usted se pasó de su salida en una autopista de acceso controlado. ¿Puede ir en reversa en la autopista o en la rampa?","o":["Sí, si tiene las luces intermitentes encendidas","Sí, si no hay carros cerca","No, es ilegal a menos que la policía o los banderilleros se lo indiquen","Sí, solo por el acotamiento"],"h1":"Mejor siga hasta la próxima salida.","h2":"En Alaska, es ilegal ir en reversa en una autopista de acceso controlado o en sus rampas de entrada o salida, a menos que la policía, los bomberos o los banderilleros de obra se lo indiquen.","p":"Correcto. Nunca vaya en reversa allí; tome la próxima salida."},"ref":{"doc":"AK","page":67}},{"id":"ak-131","scope":"AK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alaska, what is the most a person can be penalized for littering?","o":["A $1,000 fine and 90 days in jail","A $50 fine only","A $250 fine and 2 points","A warning letter only"],"h1":"It can include jail time.","h2":"In Alaska, littering can bring a fine of up to $1,000 and up to 90 days in jail, and a court may also order litter pickup.","p":"Right. Up to $1,000 and 90 days in jail."},"es":{"q":"En Alaska, ¿cuál es la pena máxima por tirar basura?","o":["Una multa de $1,000 y 90 días de cárcel","Solo una multa de $50","Una multa de $250 y 2 puntos","Solo una carta de advertencia"],"h1":"Puede incluir cárcel.","h2":"En Alaska, tirar basura puede traer una multa de hasta $1,000 y hasta 90 días de cárcel, y un tribunal también puede ordenar recoger basura.","p":"Correcto. Hasta $1,000 y 90 días de cárcel."},"ref":{"doc":"AK","page":79}},{"id":"al-001","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what is the youngest age to get a Stage I learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before the age when teens can start driving alone.","h2":"In Alabama you can get a Stage I learner license at age 15, so you can practice for a year before you may drive alone at 16.","p":"Right. The Alabama learner license starts at age 15."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para obtener la licencia de aprendiz Etapa I?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad en que los jóvenes pueden empezar a manejar solos.","h2":"En Alabama usted puede obtener la licencia de aprendiz Etapa I a los 15 años, para practicar un año antes de poder manejar solo a los 16.","p":"Correcto. La licencia de aprendiz en Alabama empieza a los 15 años."},"zh":{"q":"在 Alabama，最小几岁可以拿到 Stage I 学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比青少年可以开始单独开车的年龄早一年。","h2":"在 Alabama，你 15 岁就可以拿到 Stage I 学习驾照，这样你可以练习一年，16 岁时才可以单独开车。","p":"对。Alabama 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Alabama, tuổi nhỏ nhất để được cấp giấy phép tập lái Giai đoạn I (Stage I learner license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước tuổi thanh thiếu niên được bắt đầu lái xe một mình.","h2":"Ở Alabama, bạn có thể được cấp giấy phép tập lái Giai đoạn I khi 15 tuổi, để bạn có một năm tập lái trước khi được lái một mình lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Alabama bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Alabama, ano ang pinakabatang edad para makakuha ng Stage I learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang edad kung kailan puwede nang magmaneho nang mag-isa ang mga kabataan.","h2":"Sa Alabama, puwede kang kumuha ng Stage I learner license sa edad na 15, kaya puwede kang magsanay nang isang taon bago ka puwedeng magmaneho nang mag-isa sa edad na 16.","p":"Tama. Nagsisimula ang learner license ng Alabama sa edad na 15."},"ar":{"q":"في Alabama، ما أصغر سن للحصول على رخصة تعلّم المرحلة الأولى (Stage I learner license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تأتي قبل سنة واحدة من السن التي يبدأ فيها المراهقون القيادة وحدهم.","h2":"في Alabama يمكنك الحصول على رخصة تعلّم المرحلة الأولى في سن 15، لتتدرّب سنة كاملة قبل أن يُسمح لك بالقيادة وحدك في سن 16.","p":"صحيح. رخصة التعلّم في Alabama تبدأ من سن 15."},"ref":{"doc":"AL","page":9}},{"id":"al-002","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, who may sit beside a 15-year-old with a Stage I learner license while they drive?","o":["Any friend who has a license","Any passenger age 16 or older","A licensed driver age 18 or older","A parent, guardian, or licensed driver age 21+"],"h1":"The helper must be an experienced adult, not a young friend.","h2":"A 15-year-old Alabama learner must drive with a parent, a legal guardian, or a licensed driver who is at least 21 in the front seat, because a new driver needs an experienced adult close by.","p":"Right. The person beside you is a parent, guardian, or licensed driver age 21 or older."},"es":{"q":"En Alabama, ¿quién puede ir sentado al lado de un joven de 15 años con licencia de aprendiz Etapa I mientras maneja?","o":["Cualquier amigo que tenga licencia","Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más","Un padre, tutor o conductor con licencia de 21+"],"h1":"El acompañante debe ser un adulto con experiencia, no un amigo joven.","h2":"En Alabama un aprendiz de 15 años debe manejar con un padre, un tutor legal o un conductor con licencia de por lo menos 21 años en el asiento delantero, porque un conductor nuevo necesita a un adulto con experiencia a su lado.","p":"Correcto. A su lado va un padre, un tutor o un conductor con licencia de 21 años o más."},"zh":{"q":"在 Alabama，持 Stage I 学习驾照的 15 岁司机开车时，谁可以坐在他旁边？","o":["任何有驾照的朋友","任何 16 岁或以上的乘客","18 岁或以上、有驾照的司机","父母、监护人，或 21 岁或以上、有驾照的司机"],"h1":"陪同的人必须是有经验的成年人，不是年轻的朋友。","h2":"Alabama 15 岁的学习驾驶的人开车时，前排必须坐着父母、法定监护人，或至少 21 岁、有驾照的司机，因为新司机需要一位有经验的成年人在身边。","p":"对。坐在你旁边的人是父母、监护人，或 21 岁或以上、有驾照的司机。"},"vi":{"q":"Ở Alabama, ai được ngồi bên cạnh một người 15 tuổi có giấy phép tập lái Giai đoạn I khi người đó lái xe?","o":["Bất kỳ người bạn nào có bằng lái","Bất kỳ hành khách nào từ 16 tuổi trở lên","Người có bằng lái từ 18 tuổi trở lên","Cha mẹ, người giám hộ, hoặc người có bằng lái từ 21 tuổi"],"h1":"Người hướng dẫn phải là người lớn có kinh nghiệm, không phải một người bạn trẻ.","h2":"Người tập lái 15 tuổi ở Alabama phải lái xe với cha mẹ, người giám hộ hợp pháp, hoặc người có bằng lái ít nhất 21 tuổi ngồi ở ghế trước, vì người mới lái cần một người lớn có kinh nghiệm ở gần.","p":"Đúng. Người ngồi bên cạnh bạn là cha mẹ, người giám hộ, hoặc người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Alabama, sino ang puwedeng umupo sa tabi ng isang 15 taong gulang na may Stage I learner license habang siya ay nagmamaneho?","o":["Sinumang kaibigan na may lisensya","Sinumang pasahero na 16 taong gulang pataas","Isang may lisensyang drayber na 18 pataas","Magulang, tagapag-alaga, o may lisensyang drayber na 21+"],"h1":"Ang katulong ay dapat isang may karanasang adult, hindi isang batang kaibigan.","h2":"Ang 15 taong gulang na learner sa Alabama ay dapat magmaneho kasama ang magulang, legal na tagapag-alaga, o may lisensyang drayber na hindi bababa sa 21 taong gulang sa upuan sa harap, dahil kailangan ng bagong drayber ang isang may karanasang adult sa malapit.","p":"Tama. Ang katabi mo ay magulang, tagapag-alaga, o may lisensyang drayber na 21 taong gulang pataas."},"ar":{"q":"في Alabama، من يجوز له الجلوس بجانب شخص عمره 15 سنة يحمل رخصة تعلّم المرحلة الأولى أثناء قيادته؟","o":["أي صديق لديه رخصة","أي راكب عمره 16 سنة أو أكثر","سائق مرخّص عمره 18 سنة أو أكثر","أحد الوالدين أو وليّ أمر أو سائق مرخّص عمره 21+"],"h1":"يجب أن يكون المرافق شخصًا بالغًا ذا خبرة، لا صديقًا صغيرًا.","h2":"يجب على المتعلّم في Alabama الذي عمره 15 سنة أن يقود مع أحد الوالدين أو وليّ أمر قانوني أو سائق مرخّص عمره 21 سنة على الأقل في المقعد الأمامي، لأن السائق الجديد يحتاج إلى شخص بالغ ذي خبرة بالقرب منه.","p":"صحيح. الشخص بجانبك هو أحد الوالدين أو وليّ أمر أو سائق مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"AL","page":9}},{"id":"al-003","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a driver under 18 must hold a Stage I learner license for how long before applying for Stage II?","o":["At least 1 month","At least 3 months","At least 6 months","At least 12 months"],"h1":"It is half a year.","h2":"In Alabama a driver under 18 must hold the Stage I license for at least six months before applying for Stage II, so there is time to practice with an adult.","p":"Right. Hold the learner license for at least six months first."},"es":{"q":"En Alabama, un conductor menor de 18 años debe tener la licencia de aprendiz Etapa I, ¿por cuánto tiempo antes de solicitar la Etapa II?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses"],"h1":"Es medio año.","h2":"En Alabama un conductor menor de 18 años debe tener la licencia de Etapa I por lo menos seis meses antes de solicitar la Etapa II, para tener tiempo de practicar con un adulto.","p":"Correcto. Primero debe tener la licencia de aprendiz por lo menos seis meses."},"zh":{"q":"在 Alabama，18 岁以下的司机必须持有 Stage I 学习驾照多久，才能申请 Stage II？","o":["至少 1 个月","至少 3 个月","至少 6 个月","至少 12 个月"],"h1":"它是半年。","h2":"在 Alabama，18 岁以下的司机必须持有 Stage I 驾照至少六个月，才能申请 Stage II，这样才有时间和成年人一起练习。","p":"对。先持有学习驾照至少六个月。"},"vi":{"q":"Ở Alabama, người lái dưới 18 tuổi phải giữ giấy phép tập lái Giai đoạn I bao lâu trước khi xin Giai đoạn II?","o":["Ít nhất 1 tháng","Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Alabama, người lái dưới 18 tuổi phải giữ giấy phép Giai đoạn I ít nhất sáu tháng trước khi xin Giai đoạn II, để có thời gian tập lái với người lớn.","p":"Đúng. Trước tiên hãy giữ giấy phép tập lái ít nhất sáu tháng."},"tl":{"q":"Sa Alabama, gaano katagal dapat hawak ng drayber na wala pang 18 ang Stage I learner license bago mag-apply para sa Stage II?","o":["Hindi bababa sa 1 buwan","Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 12 buwan"],"h1":"Kalahating taon ito.","h2":"Sa Alabama, ang drayber na wala pang 18 ay dapat humawak ng Stage I license nang hindi bababa sa anim na buwan bago mag-apply para sa Stage II, para may oras siyang magsanay kasama ang isang adult.","p":"Tama. Hawakan muna ang learner license nang hindi bababa sa anim na buwan."},"ar":{"q":"في Alabama، كم يجب أن يحمل السائق الذي عمره أقل من 18 سنة رخصة تعلّم المرحلة الأولى قبل أن يتقدّم للمرحلة الثانية؟","o":["شهر واحد على الأقل","3 أشهر على الأقل","6 أشهر على الأقل","12 شهرًا على الأقل"],"h1":"إنها نصف سنة.","h2":"في Alabama يجب على السائق الذي عمره أقل من 18 سنة أن يحمل رخصة المرحلة الأولى ستة أشهر على الأقل قبل أن يتقدّم للمرحلة الثانية، ليكون لديه وقت للتدرّب مع شخص بالغ.","p":"صحيح. احمل رخصة التعلّم ستة أشهر على الأقل أولًا."},"ref":{"doc":"AL","page":10}},{"id":"al-004","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, a Stage II (restricted) driver may carry how many passengers who are not parents, guardians, or family members?","o":["No more than one","No more than two","No more than three","Any number with seat belts"],"h1":"The limit is the smallest number above zero.","h2":"An Alabama Stage II driver may not carry more than one passenger besides parents, legal guardians, or family members, because friends in the car raise the risk of a crash for new drivers.","p":"Right. Only one passenger who is not family."},"es":{"q":"En Alabama, un conductor de Etapa II (restringida), ¿cuántos pasajeros puede llevar que no sean padres, tutores ni familiares?","o":["No más de uno","No más de dos","No más de tres","Cualquier número con cinturón"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"En Alabama un conductor de Etapa II no puede llevar más de un pasajero aparte de sus padres, tutores legales o familiares, porque los amigos en el carro aumentan el riesgo de choque para los conductores nuevos.","p":"Correcto. Solo un pasajero que no sea de la familia."},"zh":{"q":"在 Alabama，持 Stage II（有限制）驾照的司机，可以载多少位不是父母、监护人或家人的乘客？","o":["不超过一位","不超过两位","不超过三位","系好安全带就可以载任何人数"],"h1":"这个限制是比零大的最小数字。","h2":"Alabama 持 Stage II 驾照的司机，除了父母、法定监护人或家人以外，最多只能载一位乘客，因为车里有朋友会提高新司机出车祸的风险。","p":"对。只能载一位不是家人的乘客。"},"vi":{"q":"Ở Alabama, người lái Giai đoạn II (có giới hạn) được chở bao nhiêu hành khách không phải là cha mẹ, người giám hộ, hoặc người trong gia đình?","o":["Không quá một người","Không quá hai người","Không quá ba người","Bao nhiêu cũng được nếu thắt dây an toàn"],"h1":"Giới hạn là con số nhỏ nhất lớn hơn không.","h2":"Người lái Giai đoạn II ở Alabama không được chở quá một hành khách ngoài cha mẹ, người giám hộ hợp pháp, hoặc người trong gia đình, vì có bạn bè trong xe làm tăng nguy cơ tai nạn cho người mới lái.","p":"Đúng. Chỉ một hành khách không phải người trong gia đình."},"tl":{"q":"Sa Alabama, ilang pasahero na hindi magulang, tagapag-alaga, o kapamilya ang puwedeng isakay ng drayber na may Stage II (restricted)?","o":["Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Kahit ilan basta naka-seat belt"],"h1":"Ang limitasyon ay ang pinakamaliit na bilang na higit sa zero.","h2":"Ang drayber na may Stage II sa Alabama ay hindi puwedeng magsakay ng higit sa isang pasahero bukod sa mga magulang, legal na tagapag-alaga, o kapamilya, dahil ang mga kaibigan sa sasakyan ay nagpapataas ng panganib ng banggaan para sa mga bagong drayber.","p":"Tama. Isang pasahero lang na hindi kapamilya."},"ar":{"q":"في Alabama، كم راكبًا من غير الوالدين أو أولياء الأمور أو أفراد العائلة يجوز لسائق المرحلة الثانية (المقيّدة) أن يحمل؟","o":["راكب واحد فقط","راكبان فقط","ثلاثة ركّاب فقط","أي عدد مع أحزمة الأمان"],"h1":"الحدّ هو أصغر عدد أكبر من الصفر.","h2":"لا يجوز لسائق المرحلة الثانية في Alabama أن يحمل أكثر من راكب واحد غير الوالدين أو أولياء الأمور القانونيين أو أفراد العائلة، لأن وجود الأصدقاء في السيارة يزيد خطر الحوادث للسائقين الجدد.","p":"صحيح. راكب واحد فقط من غير العائلة."},"ref":{"doc":"AL","page":null}},{"id":"al-005","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, during which hours may a Stage II driver not drive unless a parent, guardian, or licensed adult 21+ is with them (outside the listed exceptions)?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From midnight to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts when the date changes and ends at dawn.","h2":"An Alabama Stage II driver may not drive between midnight and 6 a.m. unless a parent, a legal guardian, or a licensed driver age 21 or older is in the car, because late-night driving is the most dangerous for new drivers.","p":"Right. No driving from midnight to 6 a.m. without an adult."},"es":{"q":"En Alabama, ¿en qué horario un conductor de Etapa II no puede manejar si no lo acompaña un padre, tutor o adulto con licencia de 21+ (fuera de las excepciones)?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza cuando cambia la fecha y termina al amanecer.","h2":"En Alabama un conductor de Etapa II no puede manejar entre la medianoche y las 6 a.m. si no va con él un padre, un tutor legal o un conductor con licencia de 21 años o más, porque manejar de madrugada es lo más peligroso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un adulto."},"zh":{"q":"在 Alabama，持 Stage II 驾照的司机在哪段时间不能开车，除非有父母、监护人或 21 岁或以上、有驾照的成年人陪同（规定的例外除外）？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"它在日期变换时开始，在天亮时结束。","h2":"Alabama 持 Stage II 驾照的司机在午夜到早上 6 点之间不能开车，除非车里有父母、法定监护人，或 21 岁或以上、有驾照的司机，因为深夜开车对新司机最危险。","p":"对。没有成年人陪同时，午夜到早上 6 点不能开车。"},"vi":{"q":"Ở Alabama, trong những giờ nào người lái Giai đoạn II không được lái xe, trừ khi có cha mẹ, người giám hộ, hoặc người lớn có bằng lái từ 21 tuổi đi cùng (ngoài các trường hợp ngoại lệ)?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Bắt đầu khi sang ngày mới và kết thúc lúc rạng sáng.","h2":"Người lái Giai đoạn II ở Alabama không được lái xe từ nửa đêm đến 6 giờ sáng trừ khi có cha mẹ, người giám hộ hợp pháp, hoặc người có bằng lái từ 21 tuổi trở lên trong xe, vì lái xe khuya là nguy hiểm nhất cho người mới lái.","p":"Đúng. Không lái xe từ nửa đêm đến 6 giờ sáng nếu không có người lớn."},"tl":{"q":"Sa Alabama, sa anong mga oras hindi puwedeng magmaneho ang drayber na may Stage II maliban kung kasama ang magulang, tagapag-alaga, o may lisensyang adult na 21+ (bukod sa mga nakalistang eksepsiyon)?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito kapag nagpalit ang petsa at natatapos sa madaling-araw.","h2":"Ang drayber na may Stage II sa Alabama ay hindi puwedeng magmaneho mula hatinggabi hanggang 6 a.m. maliban kung may magulang, legal na tagapag-alaga, o may lisensyang drayber na 21 taong gulang pataas sa sasakyan, dahil ang pagmamaneho sa hatinggabi ang pinakamapanganib para sa mga bagong drayber.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 6 a.m. nang walang adult."},"ar":{"q":"في Alabama، في أي ساعات لا يجوز لسائق المرحلة الثانية أن يقود إلا إذا كان معه أحد الوالدين أو وليّ أمر أو بالغ مرخّص عمره 21+ (خارج الاستثناءات المذكورة)؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ عندما يتغيّر التاريخ وتنتهي عند الفجر.","h2":"لا يجوز لسائق المرحلة الثانية في Alabama أن يقود بين منتصف الليل و6 صباحًا إلا إذا كان في السيارة أحد الوالدين أو وليّ أمر قانوني أو سائق مرخّص عمره 21 سنة أو أكثر، لأن القيادة في آخر الليل هي الأخطر على السائقين الجدد.","p":"صحيح. لا قيادة من منتصف الليل إلى 6 صباحًا بدون شخص بالغ."},"ref":{"doc":"AL","page":null}},{"id":"al-006","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, which trip is an exception that lets a Stage II driver drive alone between midnight and 6 a.m.?","o":["Going to or from work","Going to a friend's house","Driving to a restaurant","Practicing on empty roads"],"h1":"Think of a trip that a teen must make, not one for fun.","h2":"An Alabama Stage II driver may drive alone late at night when going to or from work, because the law allows needed trips such as work, school events, religious events, and emergencies.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Alabama, ¿qué viaje es una excepción que permite a un conductor de Etapa II manejar solo entre la medianoche y las 6 a.m.?","o":["Ir al trabajo o volver de él","Ir a la casa de un amigo","Manejar a un restaurante","Practicar en calles vacías"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Alabama un conductor de Etapa II puede manejar solo de noche cuando va al trabajo o vuelve de él, porque la ley permite viajes necesarios como el trabajo, eventos de la escuela, eventos religiosos y emergencias.","p":"Correcto. Ir al trabajo o volver de él está permitido."},"zh":{"q":"在 Alabama，哪一种行程是例外，让持 Stage II 驾照的司机可以在午夜到早上 6 点之间单独开车？","o":["上班或下班","去朋友家","开车去餐馆","在没有车的路上练习"],"h1":"想一想青少年必须去的行程，不是去玩的。","h2":"Alabama 持 Stage II 驾照的司机上班或下班时可以在深夜单独开车，因为法律允许必要的行程，比如工作、学校活动、宗教活动和紧急情况。","p":"对。上班或下班的行程是允许的。"},"vi":{"q":"Ở Alabama, chuyến đi nào là trường hợp ngoại lệ cho phép người lái Giai đoạn II lái một mình từ nửa đêm đến 6 giờ sáng?","o":["Đi làm hoặc đi làm về","Đến nhà một người bạn","Lái xe đến nhà hàng","Tập lái trên đường vắng"],"h1":"Hãy nghĩ đến một chuyến đi cần thiết, không phải để vui chơi.","h2":"Người lái Giai đoạn II ở Alabama được lái một mình vào ban đêm khi đi làm hoặc đi làm về, vì luật cho phép những chuyến đi cần thiết như đi làm, sự kiện của trường, sự kiện tôn giáo, và trường hợp khẩn cấp.","p":"Đúng. Được phép đi làm hoặc đi làm về."},"tl":{"q":"Sa Alabama, aling biyahe ang eksepsiyon na nagpapahintulot sa drayber na may Stage II na magmaneho nang mag-isa mula hatinggabi hanggang 6 a.m.?","o":["Papunta o pauwi galing sa trabaho","Papunta sa bahay ng kaibigan","Pagmamaneho papunta sa restawran","Pagsasanay sa mga bakanteng kalsada"],"h1":"Isipin ang biyaheng kailangang gawin ng kabataan, hindi para sa kasiyahan.","h2":"Ang drayber na may Stage II sa Alabama ay puwedeng magmaneho nang mag-isa sa hatinggabi kapag papunta o pauwi galing sa trabaho, dahil pinapayagan ng batas ang mga kailangang biyahe gaya ng trabaho, mga event ng paaralan, mga event na panrelihiyon, at mga emergency.","p":"Tama. Pinapayagan ang biyahe papunta o pauwi galing sa trabaho."},"ar":{"q":"في Alabama، أي رحلة تُعدّ استثناءً يسمح لسائق المرحلة الثانية بالقيادة وحده بين منتصف الليل و6 صباحًا؟","o":["الذهاب إلى العمل أو العودة منه","الذهاب إلى بيت صديق","القيادة إلى مطعم","التدرّب على طرق فارغة"],"h1":"فكّر في رحلة يجب على المراهق القيام بها، لا رحلة للتسلية.","h2":"يجوز لسائق المرحلة الثانية في Alabama أن يقود وحده في آخر الليل عند الذهاب إلى العمل أو العودة منه، لأن القانون يسمح بالرحلات الضرورية مثل العمل وأنشطة المدرسة والمناسبات الدينية وحالات الطوارئ.","p":"صحيح. الرحلة إلى العمل أو منه مسموحة."},"ref":{"doc":"AL","page":null}},{"id":"al-007","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what does the Stage II license say about handheld phones while driving?","o":["They are fine at red lights","They may not be used at all","They may be used for short calls","They are fine with one passenger"],"h1":"Stage II drivers have extra limits on phones.","h2":"An Alabama Stage II driver must not use any handheld communication device while driving, because a phone in the hand takes eyes and attention off the road.","p":"Right. No handheld phone at all while driving on a Stage II license."},"es":{"q":"En Alabama, ¿qué dice la licencia de Etapa II sobre los teléfonos en la mano al manejar?","o":["Se pueden usar en los semáforos en rojo","No se pueden usar para nada","Se pueden usar para llamadas cortas","Se pueden usar con un solo pasajero"],"h1":"Los conductores de Etapa II tienen límites extra con el teléfono.","h2":"En Alabama un conductor de Etapa II no debe usar ningún aparato de comunicación en la mano mientras maneja, porque el teléfono en la mano quita la vista y la atención del camino.","p":"Correcto. Nada de teléfono en la mano con licencia de Etapa II."},"zh":{"q":"在 Alabama，Stage II 驾照对开车时用手持电话有什么规定？","o":["等红灯时可以用","完全不能用","可以打很短的电话","有一位乘客时可以用"],"h1":"Stage II 司机在用电话方面有额外的限制。","h2":"Alabama 持 Stage II 驾照的司机开车时不能用任何手持通讯设备，因为手里拿着电话会让眼睛和注意力离开道路。","p":"对。持 Stage II 驾照开车时完全不能用手持电话。"},"vi":{"q":"Ở Alabama, giấy phép Giai đoạn II quy định gì về việc cầm điện thoại khi lái xe?","o":["Được dùng khi dừng đèn đỏ","Hoàn toàn không được dùng","Được dùng cho cuộc gọi ngắn","Được dùng nếu có một hành khách"],"h1":"Người lái Giai đoạn II có thêm giới hạn về điện thoại.","h2":"Người lái Giai đoạn II ở Alabama không được dùng bất kỳ thiết bị liên lạc cầm tay nào khi lái xe, vì cầm điện thoại làm mắt và sự chú ý rời khỏi đường.","p":"Đúng. Hoàn toàn không cầm điện thoại khi lái xe với giấy phép Giai đoạn II."},"tl":{"q":"Sa Alabama, ano ang sinasabi ng Stage II license tungkol sa paghawak ng telepono habang nagmamaneho?","o":["Puwede kapag naka-red light","Hindi talaga puwedeng gamitin","Puwede para sa maikling tawag","Puwede kung may isang pasahero"],"h1":"May dagdag na limitasyon sa telepono ang mga drayber na may Stage II.","h2":"Ang drayber na may Stage II sa Alabama ay hindi dapat gumamit ng anumang hawak-kamay na kagamitang pangkomunikasyon habang nagmamaneho, dahil ang teleponong hawak mo ay naglalayo ng iyong mata at atensyon sa kalsada.","p":"Tama. Bawal talaga ang paghawak ng telepono habang nagmamaneho na may Stage II license."},"ar":{"q":"في Alabama، ماذا تقول رخصة المرحلة الثانية عن حمل الهاتف باليد أثناء القيادة؟","o":["مسموح عند الإشارة الحمراء","ممنوع استخدامه تمامًا","مسموح للمكالمات القصيرة","مسموح مع راكب واحد"],"h1":"لسائقي المرحلة الثانية قيود إضافية على الهاتف.","h2":"يجب ألّا يستخدم سائق المرحلة الثانية في Alabama أي جهاز اتصال محمول باليد أثناء القيادة، لأن الهاتف في اليد يُبعد العينين والانتباه عن الطريق.","p":"صحيح. لا هاتف في اليد إطلاقًا أثناء القيادة برخصة المرحلة الثانية."},"ref":{"doc":"AL","page":null}},{"id":"al-008","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what happens when a Stage II driver breaks one of the graduated license rules?","o":["A warning letter only","A one-time $10 fee","Nothing, if no one was hurt","The restricted period is extended"],"h1":"The limits do not end as soon as planned.","h2":"In Alabama, breaking a graduated license rule extends the restricted period by six months or until the driver turns 18, so the teen keeps the limits longer.","p":"Right. The limits last longer after a violation."},"es":{"q":"En Alabama, ¿qué pasa cuando un conductor de Etapa II no cumple una regla de la licencia por etapas?","o":["Solo una carta de aviso","Un cargo único de $10","Nada, si nadie se lastimó","Se alarga el período restringido"],"h1":"Los límites no terminan cuando se pensaba.","h2":"En Alabama, si no se cumple una regla de la licencia por etapas, el período restringido se alarga seis meses o hasta que el conductor cumpla 18 años, así que el joven mantiene los límites por más tiempo.","p":"Correcto. Los límites duran más después de una infracción."},"zh":{"q":"在 Alabama，持 Stage II 驾照的司机违反了分级驾照的一项规定，会怎么样？","o":["只会收到一封警告信","一次性收费 $10","如果没有人受伤，就没事","有限制的期间会延长"],"h1":"限制不会按原来的计划结束。","h2":"在 Alabama，违反分级驾照规定会让有限制的期间延长六个月，或者延长到司机满 18 岁，所以这位青少年要更久遵守这些限制。","p":"对。违规以后，限制会持续更久。"},"vi":{"q":"Ở Alabama, chuyện gì xảy ra khi người lái Giai đoạn II vi phạm một quy định của bằng lái theo giai đoạn?","o":["Chỉ nhận thư cảnh cáo","Trả phí một lần $10","Không sao, nếu không ai bị thương","Thời gian giới hạn bị kéo dài"],"h1":"Các giới hạn không kết thúc đúng như dự định.","h2":"Ở Alabama, vi phạm quy định của bằng lái theo giai đoạn sẽ kéo dài thời gian giới hạn thêm sáu tháng hoặc đến khi người lái 18 tuổi, nên thanh thiếu niên phải giữ các giới hạn lâu hơn.","p":"Đúng. Các giới hạn kéo dài hơn sau khi vi phạm."},"tl":{"q":"Sa Alabama, ano ang mangyayari kapag lumabag ang drayber na may Stage II sa isa sa mga patakaran ng graduated license?","o":["Sulat ng babala lang","Isang beses na bayad na $10","Wala, kung walang nasaktan","Pinahahaba ang panahon ng restriksyon"],"h1":"Hindi natatapos ang mga limitasyon sa planadong oras.","h2":"Sa Alabama, ang paglabag sa patakaran ng graduated license ay nagpapahaba ng panahon ng restriksyon nang anim na buwan o hanggang mag-18 ang drayber, kaya mas matagal na mananatili ang mga limitasyon sa kabataan.","p":"Tama. Mas tumatagal ang mga limitasyon pagkatapos ng paglabag."},"ar":{"q":"في Alabama، ماذا يحدث عندما يخالف سائق المرحلة الثانية إحدى قواعد الرخصة المتدرّجة؟","o":["رسالة تحذير فقط","رسم واحد قدره $10","لا شيء، إذا لم يُصب أحد","تمديد فترة القيود"],"h1":"القيود لا تنتهي في موعدها المخطّط.","h2":"في Alabama، مخالفة إحدى قواعد الرخصة المتدرّجة تمدّد فترة القيود ستة أشهر أو حتى يبلغ السائق 18 سنة، فيبقى المراهق تحت القيود مدة أطول.","p":"صحيح. تستمر القيود مدة أطول بعد المخالفة."},"ref":{"doc":"AL","page":null}},{"id":"al-009","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a 17-year-old can get an unrestricted Stage III license after holding Stage II for how long?","o":["At least 3 months","At least 6 months","At least 9 months","At least 12 months"],"h1":"It is the same length as the Stage I waiting time.","h2":"In Alabama a 17-year-old must hold a Stage II license for at least six months before getting the unrestricted Stage III license, so the new driver has time alone with limits first.","p":"Right. Six months on Stage II, then Stage III."},"es":{"q":"En Alabama, un joven de 17 años puede obtener la licencia sin restricciones de Etapa III después de tener la Etapa II, ¿por cuánto tiempo?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 9 meses","Por lo menos 12 meses"],"h1":"Es el mismo tiempo de espera que en la Etapa I.","h2":"En Alabama un joven de 17 años debe tener la licencia de Etapa II por lo menos seis meses antes de obtener la licencia sin restricciones de Etapa III, para tener primero un tiempo manejando solo con límites.","p":"Correcto. Seis meses en Etapa II y luego la Etapa III."},"zh":{"q":"在 Alabama，17 岁的人持有 Stage II 驾照多久以后，可以拿到没有限制的 Stage III 驾照？","o":["至少 3 个月","至少 6 个月","至少 9 个月","至少 12 个月"],"h1":"它和 Stage I 的等待时间一样长。","h2":"在 Alabama，17 岁的人必须持有 Stage II 驾照至少六个月，才能拿到没有限制的 Stage III 驾照，这样新司机先有一段在限制下单独开车的时间。","p":"对。Stage II 持有六个月，然后是 Stage III。"},"vi":{"q":"Ở Alabama, người 17 tuổi có thể được cấp bằng lái Giai đoạn III không giới hạn sau khi giữ Giai đoạn II bao lâu?","o":["Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 9 tháng","Ít nhất 12 tháng"],"h1":"Bằng với thời gian chờ của Giai đoạn I.","h2":"Ở Alabama, người 17 tuổi phải giữ bằng lái Giai đoạn II ít nhất sáu tháng trước khi được cấp bằng Giai đoạn III không giới hạn, để người mới lái có thời gian lái một mình với các giới hạn trước.","p":"Đúng. Sáu tháng với Giai đoạn II, rồi đến Giai đoạn III."},"tl":{"q":"Sa Alabama, ang 17 taong gulang ay puwedeng kumuha ng Stage III license na walang restriksyon pagkatapos humawak ng Stage II nang gaano katagal?","o":["Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 9 na buwan","Hindi bababa sa 12 buwan"],"h1":"Kapareho ito ng haba ng paghihintay sa Stage I.","h2":"Sa Alabama, ang 17 taong gulang ay dapat humawak ng Stage II license nang hindi bababa sa anim na buwan bago makakuha ng Stage III license na walang restriksyon, para may oras muna ang bagong drayber na magmaneho nang mag-isa na may mga limitasyon.","p":"Tama. Anim na buwan sa Stage II, saka Stage III."},"ar":{"q":"في Alabama، يمكن لمن عمره 17 سنة الحصول على رخصة المرحلة الثالثة غير المقيّدة بعد حمل المرحلة الثانية لكم من الوقت؟","o":["3 أشهر على الأقل","6 أشهر على الأقل","9 أشهر على الأقل","12 شهرًا على الأقل"],"h1":"إنها نفس مدة الانتظار في المرحلة الأولى.","h2":"في Alabama يجب على من عمره 17 سنة أن يحمل رخصة المرحلة الثانية ستة أشهر على الأقل قبل الحصول على رخصة المرحلة الثالثة غير المقيّدة، ليقضي السائق الجديد وقتًا يقود فيه وحده مع القيود أولًا.","p":"صحيح. ستة أشهر في المرحلة الثانية، ثم المرحلة الثالثة."},"ref":{"doc":"AL","page":null}},{"id":"al-010","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how long is a learner license valid before it must be renewed?","o":["One year","Two years","Four years","Eight years"],"h1":"It lasts longer than a typical school year or two.","h2":"An Alabama learner license is valid for four years and can be renewed once, which gives a learner plenty of time to practice.","p":"Right. The learner license is good for four years."},"es":{"q":"En Alabama, ¿por cuánto tiempo es válida la licencia de aprendiz antes de renovarla?","o":["Un año","Dos años","Cuatro años","Ocho años"],"h1":"Dura más que uno o dos años escolares.","h2":"En Alabama la licencia de aprendiz es válida por cuatro años y se puede renovar una vez, lo que le da al aprendiz mucho tiempo para practicar.","p":"Correcto. La licencia de aprendiz dura cuatro años."},"zh":{"q":"在 Alabama，学习驾照在需要延期之前有效多久？","o":["一年","两年","四年","八年"],"h1":"它比一两个学年还长。","h2":"Alabama 的学习驾照有效期是四年，可以延期一次，这让学习驾驶的人有很多时间练习。","p":"对。学习驾照有效四年。"},"vi":{"q":"Ở Alabama, giấy phép tập lái có giá trị bao lâu trước khi phải gia hạn?","o":["Một năm","Hai năm","Bốn năm","Tám năm"],"h1":"Nó kéo dài hơn một hoặc hai năm học thông thường.","h2":"Giấy phép tập lái ở Alabama có giá trị bốn năm và được gia hạn một lần, cho người tập lái nhiều thời gian để luyện tập.","p":"Đúng. Giấy phép tập lái có giá trị bốn năm."},"tl":{"q":"Sa Alabama, gaano katagal valid ang learner license bago ito dapat i-renew?","o":["Isang taon","Dalawang taon","Apat na taon","Walong taon"],"h1":"Mas matagal ito kaysa sa karaniwang isa o dalawang taon ng pag-aaral.","h2":"Ang learner license sa Alabama ay valid nang apat na taon at puwedeng i-renew nang isang beses, kaya maraming oras ang learner para magsanay.","p":"Tama. Valid ang learner license nang apat na taon."},"ar":{"q":"في Alabama، كم تبقى رخصة التعلّم سارية قبل أن يجب تجديدها؟","o":["سنة واحدة","سنتان","أربع سنوات","ثماني سنوات"],"h1":"تدوم أطول من سنة أو سنتين دراسيتين عاديتين.","h2":"رخصة التعلّم في Alabama سارية أربع سنوات ويمكن تجديدها مرة واحدة، مما يعطي المتعلّم وقتًا كافيًا للتدرّب.","p":"صحيح. رخصة التعلّم صالحة أربع سنوات."},"ref":{"doc":"AL","page":9}},{"id":"al-011","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, can a person take the written knowledge test in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only with a paid interpreter","Only for commercial licenses"],"h1":"Alabama offers the written test in several languages.","h2":"Alabama offers the written knowledge test in other languages, including Spanish, so people can show what they know in the language they read best.","p":"Right. The Alabama written test is available in Spanish."},"es":{"q":"En Alabama, ¿se puede tomar el examen escrito de conocimientos en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo con un intérprete pagado","Solo para licencias comerciales"],"h1":"Alabama ofrece el examen escrito en varios idiomas.","h2":"Alabama ofrece el examen escrito de conocimientos en otros idiomas, incluido el español, para que cada persona muestre lo que sabe en el idioma que lee mejor.","p":"Correcto. El examen escrito de Alabama se ofrece en español."},"zh":{"q":"在 Alabama，可以用西班牙语考笔试吗？","o":["可以，有西班牙语","不可以，只有英语","只有请付费翻译时才可以","只有商业驾照才可以"],"h1":"Alabama 的笔试有好几种语言。","h2":"Alabama 的笔试提供其他语言，包括西班牙语，所以人们可以用自己读得最好的语言来表现他们知道的东西。","p":"对。Alabama 的笔试有西班牙语。"},"vi":{"q":"Ở Alabama, có thể thi lý thuyết bằng tiếng Tây Ban Nha không?","o":["Có, có tiếng Tây Ban Nha","Không, chỉ có tiếng Anh","Chỉ khi trả tiền thông dịch viên","Chỉ cho bằng lái thương mại"],"h1":"Alabama có bài thi lý thuyết bằng nhiều ngôn ngữ.","h2":"Alabama có bài thi lý thuyết bằng các ngôn ngữ khác, kể cả tiếng Tây Ban Nha, để mọi người có thể thể hiện hiểu biết bằng ngôn ngữ họ đọc tốt nhất.","p":"Đúng. Bài thi lý thuyết ở Alabama có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Alabama, puwede bang kumuha ng nakasulat na knowledge test sa Spanish?","o":["Oo, may Spanish","Hindi, English lang","Kung may bayad na interpreter lang","Para sa commercial license lang"],"h1":"May nakasulat na pagsusulit ang Alabama sa ilang wika.","h2":"May nakasulat na knowledge test ang Alabama sa ibang mga wika, kasama ang Spanish, para maipakita ng mga tao ang alam nila sa wikang pinakamahusay nilang nababasa.","p":"Tama. May nakasulat na pagsusulit ang Alabama sa Spanish."},"ar":{"q":"في Alabama، هل يمكن تقديم الاختبار النظري المكتوب باللغة الإسبانية؟","o":["نعم، الإسبانية متاحة","لا، بالإنجليزية فقط","فقط مع مترجم مدفوع الأجر","فقط للرخص التجارية"],"h1":"تقدّم Alabama الاختبار المكتوب بعدة لغات.","h2":"تقدّم Alabama الاختبار النظري المكتوب بلغات أخرى، منها الإسبانية، ليتمكّن الناس من إظهار ما يعرفونه باللغة التي يقرؤونها أفضل.","p":"صحيح. الاختبار المكتوب في Alabama متاح بالإسبانية."},"ref":{"doc":"AL","page":9}},{"id":"al-012","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little higher than a typical school zone speed.","h2":"The Alabama speed limit in an urban district is 30 mph unless a sign shows a different limit, because towns have many people, driveways, and crossings.","p":"Right. Urban districts in Alabama are 30 mph unless posted."},"es":{"q":"En Alabama, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más alto que la velocidad típica de una zona escolar.","h2":"En Alabama el límite de velocidad en una zona urbana es de 30 mph si no hay una señal con otro límite, porque en los pueblos hay mucha gente, entradas de autos y cruces.","p":"Correcto. En zonas urbanas de Alabama son 30 mph si no hay otra señal."},"zh":{"q":"在 Alabama，除非标志另有规定，市区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它比一般学校区的速度高一点。","h2":"除非标志写着别的限速，Alabama 市区的限速是 30 mph，因为城镇里有很多人、车道出口和路口。","p":"对。除非有标志，Alabama 市区限速是 30 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trong khu đô thị là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Cao hơn một chút so với tốc độ thông thường ở khu trường học.","h2":"Tốc độ tối đa trong khu đô thị ở Alabama là 30 mph trừ khi biển báo ghi khác, vì thị trấn có nhiều người, lối xe ra vào, và chỗ băng qua đường.","p":"Đúng. Khu đô thị ở Alabama là 30 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Medyo mas mataas ito kaysa sa karaniwang bilis sa school zone.","h2":"Ang speed limit sa urban district sa Alabama ay 30 mph maliban kung iba ang ipinapakita ng karatula, dahil maraming tao, daanan ng sasakyan, at tawiran sa mga bayan.","p":"Tama. 30 mph ang mga urban district sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة في المنطقة الحضرية؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"إنه أعلى قليلًا من السرعة المعتادة في منطقة المدرسة.","h2":"حدّ السرعة في المنطقة الحضرية في Alabama هو 30 mph ما لم تُظهر لافتة حدًّا مختلفًا، لأن في البلدات كثيرًا من الناس ومداخل السيارات وأماكن العبور.","p":"صحيح. المناطق الحضرية في Alabama حدّها 30 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-013","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, what is the highest speed limit allowed by law on an interstate highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Interstates have the highest limit in the state.","h2":"The highest speed limit on an Alabama interstate is 70 mph, which is higher than the limit on other four-lane highways.","p":"Right. Alabama interstates go up to 70 mph."},"es":{"q":"En Alabama, ¿cuál es el límite de velocidad más alto que permite la ley en una carretera interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las interestatales tienen el límite más alto del estado.","h2":"En Alabama el límite de velocidad más alto en una interestatal es de 70 mph, más alto que en otras carreteras de cuatro carriles.","p":"Correcto. Las interestatales de Alabama llegan a 70 mph."},"zh":{"q":"在 Alabama，法律允许州际公路的最高限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"州际公路的限速是全州最高的。","h2":"Alabama 州际公路的最高限速是 70 mph，比其他四车道公路的限速高。","p":"对。Alabama 州际公路最高是 70 mph。"},"vi":{"q":"Ở Alabama, tốc độ tối đa cao nhất theo luật trên xa lộ liên bang (interstate) là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Xa lộ liên bang có tốc độ tối đa cao nhất trong tiểu bang.","h2":"Tốc độ tối đa cao nhất trên xa lộ liên bang ở Alabama là 70 mph, cao hơn tốc độ trên các xa lộ bốn làn khác.","p":"Đúng. Xa lộ liên bang ở Alabama tối đa 70 mph."},"tl":{"q":"Sa Alabama, ano ang pinakamataas na speed limit na pinapayagan ng batas sa interstate highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Ang mga interstate ang may pinakamataas na limit sa estado.","h2":"Ang pinakamataas na speed limit sa interstate sa Alabama ay 70 mph, na mas mataas kaysa sa limit sa ibang highway na may apat na lane.","p":"Tama. Hanggang 70 mph ang mga interstate sa Alabama."},"ar":{"q":"في Alabama، ما أعلى حدّ سرعة يسمح به القانون على الطريق السريع بين الولايات (interstate)؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"الطرق السريعة بين الولايات لها أعلى حدّ في الولاية.","h2":"أعلى حدّ سرعة على الطريق السريع بين الولايات في Alabama هو 70 mph، وهو أعلى من الحدّ على الطرق السريعة الأخرى ذات الأربعة مسارات.","p":"صحيح. الطرق السريعة بين الولايات في Alabama تصل إلى 70 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-014","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a highway with four or more lanes that is not an interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph below the interstate limit.","h2":"On an Alabama highway with four or more lanes that is not an interstate, the limit is 65 mph unless posted, which is 5 mph less than on an interstate.","p":"Right. Four-lane highways that are not interstates are 65 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera de cuatro carriles o más que no es interestatal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de la interestatal.","h2":"En una carretera de Alabama con cuatro carriles o más que no es interestatal, el límite es de 65 mph si no hay otra señal, o sea 5 mph menos que en una interestatal.","p":"Correcto. Las carreteras de cuatro carriles que no son interestatales tienen 65 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，不是州际公路、有四条或更多车道的公路，限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"它比州际公路的限速低 5 mph。","h2":"在 Alabama 不是州际公路、有四条或更多车道的公路上，除非有标志，限速是 65 mph，比州际公路低 5 mph。","p":"对。不是州际公路的四车道公路限速是 65 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên xa lộ có bốn làn trở lên mà không phải xa lộ liên bang là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Thấp hơn 5 mph so với xa lộ liên bang.","h2":"Trên xa lộ ở Alabama có bốn làn trở lên mà không phải xa lộ liên bang, tốc độ tối đa là 65 mph nếu không có biển báo khác, thấp hơn 5 mph so với xa lộ liên bang.","p":"Đúng. Xa lộ bốn làn không phải liên bang là 65 mph."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa highway na may apat o higit pang lane na hindi interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"5 mph itong mas mababa sa limit ng interstate.","h2":"Sa highway sa Alabama na may apat o higit pang lane na hindi interstate, ang limit ay 65 mph maliban kung may nakapaskil, na 5 mph na mas mababa kaysa sa interstate.","p":"Tama. 65 mph ang mga highway na may apat na lane na hindi interstate."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق سريع له أربعة مسارات أو أكثر وليس طريقًا بين الولايات؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"إنه أقل بـ 5 mph من حدّ الطريق بين الولايات.","h2":"على طريق سريع في Alabama له أربعة مسارات أو أكثر وليس طريقًا بين الولايات، الحدّ هو 65 mph ما لم تُشر لافتة إلى غير ذلك، وهو أقل بـ 5 mph من الطريق بين الولايات.","p":"صحيح. الطرق ذات الأربعة مسارات التي ليست بين الولايات حدّها 65 mph."},"ref":{"doc":"AL","page":null}},{"id":"al-015","scope":"AL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a state highway with fewer than four lanes?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Smaller highways have a lower limit than four-lane highways.","h2":"An Alabama highway with fewer than four lanes has a 55 mph limit unless a sign says otherwise, because two-lane roads have oncoming traffic close by.","p":"Right. Smaller Alabama highways are 55 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera estatal de menos de cuatro carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Las carreteras más pequeñas tienen un límite más bajo que las de cuatro carriles.","h2":"En Alabama una carretera de menos de cuatro carriles tiene un límite de 55 mph si no hay una señal con otro límite, porque en las carreteras de dos carriles el tráfico contrario pasa muy cerca.","p":"Correcto. Las carreteras pequeñas de Alabama tienen 55 mph si no hay otra señal."},"zh":{"q":"在 Alabama，除非标志另有规定，少于四条车道的州公路限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"比较小的公路，限速比四车道公路低。","h2":"Alabama 少于四条车道的公路，除非标志另有规定，限速是 55 mph，因为双车道道路上对面来的车离得很近。","p":"对。除非有标志，Alabama 较小的公路限速是 55 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên xa lộ tiểu bang có ít hơn bốn làn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Xa lộ nhỏ hơn có tốc độ thấp hơn xa lộ bốn làn.","h2":"Xa lộ ở Alabama có ít hơn bốn làn có tốc độ tối đa 55 mph trừ khi biển báo ghi khác, vì đường hai làn có xe đi ngược chiều ở rất gần.","p":"Đúng. Xa lộ nhỏ ở Alabama là 55 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa state highway na may mas kaunti sa apat na lane?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ang limit ng maliliit na highway kaysa sa mga highway na may apat na lane.","h2":"Ang highway sa Alabama na may mas kaunti sa apat na lane ay may limit na 55 mph maliban kung iba ang sinasabi ng karatula, dahil malapit ang mga sasakyang kasalubong sa kalsadang may dalawang lane.","p":"Tama. 55 mph ang maliliit na highway sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق سريع تابع للولاية له أقل من أربعة مسارات؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"الطرق الأصغر لها حدّ أقل من الطرق ذات الأربعة مسارات.","h2":"الطريق السريع في Alabama الذي له أقل من أربعة مسارات حدّه 55 mph ما لم تُشر لافتة إلى غير ذلك، لأن في الطرق ذات المسارين سيارات قادمة من الاتجاه المقابل قريبة جدًّا.","p":"صحيح. الطرق الأصغر في Alabama حدّها 55 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-016","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on an unpaved road?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Dirt and gravel need more care than a paved county road.","h2":"The Alabama limit on an unpaved road is 35 mph unless a sign says otherwise, because loose dirt and gravel make it harder to stop and steer.","p":"Right. Unpaved roads in Alabama are 35 mph."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino sin pavimentar?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"La tierra y la grava piden más cuidado que un camino pavimentado del condado.","h2":"En Alabama el límite en un camino sin pavimentar es de 35 mph si no hay otra señal, porque la tierra suelta y la grava hacen más difícil frenar y girar.","p":"Correcto. Los caminos sin pavimentar en Alabama tienen 35 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，没有铺路面的道路限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"土路和碎石路比铺好的县道更需要小心。","h2":"Alabama 没有铺路面的道路，除非标志另有规定，限速是 35 mph，因为松散的泥土和碎石让停车和转方向盘更难。","p":"对。Alabama 没有铺路面的道路限速是 35 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên đường không trải nhựa là bao nhiêu?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Đường đất và sỏi cần cẩn thận hơn đường quận trải nhựa.","h2":"Tốc độ tối đa trên đường không trải nhựa ở Alabama là 35 mph trừ khi biển báo ghi khác, vì đất và sỏi rời làm khó dừng và khó lái hơn.","p":"Đúng. Đường không trải nhựa ở Alabama là 35 mph."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa kalsadang hindi sementado?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Mas kailangan ng ingat sa lupa at graba kaysa sa sementadong county road.","h2":"Ang limit sa kalsadang hindi sementado sa Alabama ay 35 mph maliban kung iba ang sinasabi ng karatula, dahil mas mahirap huminto at magmaniobra sa maluwag na lupa at graba.","p":"Tama. 35 mph ang mga kalsadang hindi sementado sa Alabama."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق غير معبّد؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"التراب والحصى يحتاجان إلى حذر أكثر من طريق المقاطعة المعبّد.","h2":"حدّ السرعة على الطريق غير المعبّد في Alabama هو 35 mph ما لم تُشر لافتة إلى غير ذلك، لأن التراب والحصى المفكّك يجعلان التوقّف والتوجيه أصعب.","p":"صحيح. الطرق غير المعبّدة في Alabama حدّها 35 mph."},"ref":{"doc":"AL","page":60}},{"id":"al-017","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, unless posted otherwise, what is the speed limit on a paved county road outside a city or town?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"It is 10 mph more than on an unpaved road.","h2":"A paved county road outside a city or town in Alabama has a 45 mph limit unless posted, which is 10 mph more than on an unpaved road.","p":"Right. Paved county roads in Alabama are 45 mph unless posted."},"es":{"q":"En Alabama, si no hay otra señal, ¿cuál es el límite de velocidad en un camino pavimentado del condado fuera de una ciudad o pueblo?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Es 10 mph más que en un camino sin pavimentar.","h2":"En Alabama un camino pavimentado del condado fuera de una ciudad o pueblo tiene un límite de 45 mph si no hay otra señal, o sea 10 mph más que en un camino sin pavimentar.","p":"Correcto. Los caminos pavimentados del condado en Alabama tienen 45 mph."},"zh":{"q":"在 Alabama，除非标志另有规定，城市或城镇以外铺好路面的县道限速是多少？","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"它比没有铺路面的道路多 10 mph。","h2":"Alabama 城市或城镇以外铺好路面的县道，除非有标志，限速是 45 mph，比没有铺路面的道路多 10 mph。","p":"对。除非有标志，Alabama 铺好路面的县道限速是 45 mph。"},"vi":{"q":"Ở Alabama, nếu không có biển báo khác, tốc độ tối đa trên đường quận trải nhựa bên ngoài thành phố hoặc thị trấn là bao nhiêu?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Cao hơn 10 mph so với đường không trải nhựa.","h2":"Đường quận trải nhựa bên ngoài thành phố hoặc thị trấn ở Alabama có tốc độ tối đa 45 mph nếu không có biển báo khác, cao hơn 10 mph so với đường không trải nhựa.","p":"Đúng. Đường quận trải nhựa ở Alabama là 45 mph nếu không có biển báo khác."},"tl":{"q":"Sa Alabama, maliban kung iba ang nakapaskil, ano ang speed limit sa sementadong county road sa labas ng lungsod o bayan?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"10 mph itong mas mataas kaysa sa kalsadang hindi sementado.","h2":"Ang sementadong county road sa labas ng lungsod o bayan sa Alabama ay may limit na 45 mph maliban kung may nakapaskil, na 10 mph na mas mataas kaysa sa kalsadang hindi sementado.","p":"Tama. 45 mph ang mga sementadong county road sa Alabama maliban kung may nakapaskil."},"ar":{"q":"في Alabama، ما لم تُشر لافتة إلى غير ذلك، ما حدّ السرعة على طريق مقاطعة معبّد خارج المدينة أو البلدة؟","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"إنه أعلى بـ 10 mph من الطريق غير المعبّد.","h2":"طريق المقاطعة المعبّد خارج المدينة أو البلدة في Alabama حدّه 45 mph ما لم تُشر لافتة إلى غير ذلك، وهو أعلى بـ 10 mph من الطريق غير المعبّد.","p":"صحيح. طرق المقاطعة المعبّدة في Alabama حدّها 45 mph ما لم تُشر لافتة إلى غير ذلك."},"ref":{"doc":"AL","page":60}},{"id":"al-018","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, on an interstate, how far may you stay in the far-left lane without completely passing another vehicle?","o":["0.5 miles","1 mile","3 miles","1.5 miles"],"h1":"It is a short distance, between one and two miles.","h2":"On an Alabama interstate you may not stay in the far-left lane for more than 1.5 miles without completely passing a vehicle, because the left lane is for passing.","p":"Right. No more than 1.5 miles in the left lane without passing."},"es":{"q":"En Alabama, en una interestatal, ¿qué distancia puede ir por el carril de la izquierda sin terminar de rebasar a otro vehículo?","o":["0.5 millas","1 milla","3 millas","1.5 millas"],"h1":"Es una distancia corta, entre una y dos millas.","h2":"En una interestatal de Alabama usted no puede ir más de 1.5 millas por el carril de la izquierda sin terminar de rebasar a un vehículo, porque el carril izquierdo es para rebasar.","p":"Correcto. No más de 1.5 millas en el carril izquierdo sin rebasar."},"zh":{"q":"在 Alabama 的州际公路上，你在最左边车道最多可以开多远而不完全超过另一辆车？","o":["0.5 英里","1 英里","3 英里","1.5 英里"],"h1":"这是一段短距离，在一英里和两英里之间。","h2":"在 Alabama 的州际公路上，你在最左边车道开超过 1.5 英里却没有完全超过一辆车是不允许的，因为左边车道是用来超车的。","p":"对。在左边车道不超车，最多开 1.5 英里。"},"vi":{"q":"Ở Alabama, trên xa lộ liên bang, bạn được ở làn ngoài cùng bên trái bao xa mà không vượt hẳn qua xe khác?","o":["0.5 dặm","1 dặm","3 dặm","1.5 dặm"],"h1":"Một khoảng ngắn, giữa một và hai dặm.","h2":"Trên xa lộ liên bang ở Alabama, bạn không được ở làn ngoài cùng bên trái quá 1.5 dặm mà không vượt hẳn qua một xe, vì làn bên trái dùng để vượt.","p":"Đúng. Không quá 1.5 dặm ở làn trái mà không vượt."},"tl":{"q":"Sa Alabama, sa interstate, gaano kalayo ka puwedeng manatili sa pinakakaliwang lane nang hindi lubusang nag-o-overtake sa ibang sasakyan?","o":["0.5 milya","1 milya","3 milya","1.5 milya"],"h1":"Maikling distansya ito, sa pagitan ng isa at dalawang milya.","h2":"Sa interstate sa Alabama, hindi ka puwedeng manatili sa pinakakaliwang lane nang higit sa 1.5 milya nang hindi lubusang nag-o-overtake sa isang sasakyan, dahil ang kaliwang lane ay para sa pag-overtake.","p":"Tama. Hindi hihigit sa 1.5 milya sa kaliwang lane nang hindi nag-o-overtake."},"ar":{"q":"في Alabama، على الطريق السريع بين الولايات، ما المسافة التي يجوز لك البقاء فيها في المسار الأيسر الأقصى دون أن تتجاوز مركبة أخرى تمامًا؟","o":["0.5 ميل","1 ميل","3 أميال","1.5 ميل"],"h1":"إنها مسافة قصيرة، بين ميل وميلين.","h2":"على الطريق السريع بين الولايات في Alabama لا يجوز لك البقاء في المسار الأيسر الأقصى أكثر من 1.5 ميل دون أن تتجاوز مركبة تمامًا، لأن المسار الأيسر مخصّص للتجاوز.","p":"صحيح. لا أكثر من 1.5 ميل في المسار الأيسر دون تجاوز."},"ref":{"doc":"AL","page":null}},{"id":"al-019","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, on a road with two or more lanes in your direction, what should you do when passing a stopped police car with flashing lights?","o":["Move out of the lane next to it if safe","Stop behind it and wait","Honk and keep your speed","Speed up to pass it quickly"],"h1":"Give the stopped vehicle more room.","h2":"Under the Alabama Move Over law you must leave the lane closest to a stopped emergency vehicle when it is safe, and slow down if you cannot, to protect the people working there.","p":"Right. Move over a lane when it is safe."},"es":{"q":"En Alabama, en una vía con dos o más carriles en su dirección, ¿qué debe hacer al pasar junto a una patrulla detenida con luces encendidas?","o":["Salir del carril de al lado si es seguro","Pararse detrás y esperar","Tocar la bocina y seguir igual","Acelerar para pasar rápido"],"h1":"Dé más espacio al vehículo detenido.","h2":"Según la ley de Alabama para apartarse (Move Over), usted debe salir del carril más cercano al vehículo de emergencia detenido cuando sea seguro, y bajar la velocidad si no puede, para proteger a las personas que trabajan allí.","p":"Correcto. Cámbiese de carril cuando sea seguro."},"zh":{"q":"在 Alabama，在你的方向有两条或更多车道的道路上，经过一辆车灯在闪的停着的警车时，你应该怎么做？","o":["安全时离开它旁边的车道","停在它后面等","按喇叭并保持速度","加速快点开过去"],"h1":"给停着的车更多空间。","h2":"根据 Alabama 的 Move Over 法，安全时你必须离开最靠近停着的急救车辆的车道，做不到就要减速，来保护在那里工作的人。","p":"对。安全时换开一条车道。"},"vi":{"q":"Ở Alabama, trên đường có hai làn trở lên cùng chiều với bạn, bạn nên làm gì khi đi qua một xe cảnh sát đang dừng và nháy đèn?","o":["Rời khỏi làn sát bên nó nếu an toàn","Dừng phía sau nó và chờ","Bấm còi và giữ tốc độ","Tăng tốc để vượt qua nhanh"],"h1":"Hãy chừa thêm chỗ cho xe đang dừng.","h2":"Theo luật Nhường Làn (Move Over law) ở Alabama, bạn phải rời khỏi làn gần nhất với xe khẩn cấp đang dừng khi an toàn, và giảm tốc độ nếu không thể chuyển làn, để bảo vệ những người đang làm việc ở đó.","p":"Đúng. Chuyển sang làn khác khi an toàn."},"tl":{"q":"Sa Alabama, sa kalsadang may dalawa o higit pang lane sa iyong direksyon, ano ang dapat mong gawin kapag dumadaan sa nakahintong sasakyan ng pulis na may kumikislap na ilaw?","o":["Lumipat mula sa lane na katabi nito kung ligtas","Huminto sa likod nito at maghintay","Bumusina at panatilihin ang bilis","Bumilis para madaanan ito agad"],"h1":"Bigyan ng mas maraming espasyo ang nakahintong sasakyan.","h2":"Ayon sa Move Over law ng Alabama, dapat kang umalis sa lane na pinakamalapit sa nakahintong emergency vehicle kapag ligtas, at magbagal kung hindi ka makalipat, para protektahan ang mga taong nagtatrabaho roon.","p":"Tama. Lumipat ng isang lane kapag ligtas."},"ar":{"q":"في Alabama، على طريق فيه مساران أو أكثر في اتجاهك، ماذا يجب أن تفعل عند المرور بسيارة شرطة متوقّفة وأضواؤها تومض؟","o":["انتقل من المسار المجاور لها إن كان ذلك آمنًا","توقّف خلفها وانتظر","اضغط على البوق وحافظ على سرعتك","زِد سرعتك لتتجاوزها بسرعة"],"h1":"أعطِ المركبة المتوقّفة مساحة أكبر.","h2":"بموجب قانون الابتعاد (Move Over law) في Alabama يجب أن تغادر المسار الأقرب إلى مركبة الطوارئ المتوقّفة عندما يكون ذلك آمنًا، وأن تُبطئ إن لم تستطع، لحماية الأشخاص الذين يعملون هناك.","p":"صحيح. انتقل مسارًا واحدًا عندما يكون ذلك آمنًا."},"ref":{"doc":"AL","page":68}},{"id":"al-020","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, if you cannot change lanes away from a stopped emergency vehicle and the limit is 25 mph or more, how much should you slow down?","o":["5 mph below the limit","15 mph below the limit","25 mph below the limit","To exactly 20 mph"],"h1":"It is more than 10 mph but less than 20 mph.","h2":"In Alabama, when you cannot move over and the posted limit is 25 mph or more, you must slow to at least 15 mph below the limit so you can react to people near the road.","p":"Right. Slow to 15 mph below the limit."},"es":{"q":"En Alabama, si no puede cambiarse de carril al pasar un vehículo de emergencia detenido y el límite es de 25 mph o más, ¿cuánto debe bajar la velocidad?","o":["5 mph menos que el límite","15 mph menos que el límite","25 mph menos que el límite","Exactamente a 20 mph"],"h1":"Es más de 10 mph pero menos de 20 mph.","h2":"En Alabama, cuando usted no puede apartarse y el límite es de 25 mph o más, debe bajar por lo menos a 15 mph menos que el límite, para poder reaccionar ante las personas cerca del camino.","p":"Correcto. Baje a 15 mph menos que el límite."},"zh":{"q":"在 Alabama，如果你无法换道离开停着的急救车辆，而限速是 25 mph 或更高，你应该减速多少？","o":["比限速低 5 mph","比限速低 15 mph","比限速低 25 mph","刚好 20 mph"],"h1":"它比 10 mph 多，但比 20 mph 少。","h2":"在 Alabama，你无法换道而标出的限速是 25 mph 或更高时，必须减速到至少比限速低 15 mph，这样你才能对路边的人做出反应。","p":"对。减速到比限速低 15 mph。"},"vi":{"q":"Ở Alabama, nếu bạn không thể chuyển làn tránh xa xe khẩn cấp đang dừng và tốc độ tối đa là 25 mph trở lên, bạn nên giảm tốc độ bao nhiêu?","o":["Thấp hơn tốc độ tối đa 5 mph","Thấp hơn tốc độ tối đa 15 mph","Thấp hơn tốc độ tối đa 25 mph","Đúng 20 mph"],"h1":"Hơn 10 mph nhưng ít hơn 20 mph.","h2":"Ở Alabama, khi bạn không thể chuyển làn và tốc độ tối đa ghi trên biển là 25 mph trở lên, bạn phải giảm xuống ít nhất 15 mph thấp hơn tốc độ tối đa để kịp phản ứng với người ở gần đường.","p":"Đúng. Giảm xuống thấp hơn tốc độ tối đa 15 mph."},"tl":{"q":"Sa Alabama, kung hindi ka makalipat ng lane palayo sa nakahintong emergency vehicle at ang limit ay 25 mph o higit pa, gaano ka dapat magbagal?","o":["5 mph na mas mababa sa limit","15 mph na mas mababa sa limit","25 mph na mas mababa sa limit","Eksaktong 20 mph"],"h1":"Higit ito sa 10 mph pero mas mababa sa 20 mph.","h2":"Sa Alabama, kapag hindi ka makalipat at ang nakapaskil na limit ay 25 mph o higit pa, dapat kang magbagal nang hindi bababa sa 15 mph na mas mababa sa limit para makatugon ka sa mga taong malapit sa kalsada.","p":"Tama. Magbagal sa 15 mph na mas mababa sa limit."},"ar":{"q":"في Alabama، إذا لم تستطع الابتعاد بتغيير المسار عن مركبة طوارئ متوقّفة وكان الحدّ 25 mph أو أكثر، فكم يجب أن تُبطئ؟","o":["5 mph أقل من الحدّ","15 mph أقل من الحدّ","25 mph أقل من الحدّ","إلى 20 mph بالضبط"],"h1":"إنه أكثر من 10 mph وأقل من 20 mph.","h2":"في Alabama، عندما لا تستطيع الابتعاد ويكون الحدّ المكتوب 25 mph أو أكثر، يجب أن تُبطئ إلى 15 mph على الأقل تحت الحدّ لتتمكّن من التصرّف بسرعة تجاه الأشخاص القريبين من الطريق.","p":"صحيح. أبطئ إلى 15 mph تحت الحدّ."},"ref":{"doc":"AL","page":68}},{"id":"al-021","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, which of these stopped vehicles with flashing lights is also covered by the Move Over law?","o":["A parked delivery van","A car stopped at a red light","A garbage or recycling truck","A bus at a regular bus stop"],"h1":"The law protects many roadside workers, not only police.","h2":"The Alabama Move Over law covers garbage and recycling trucks that are collecting on the roadside, as well as police, emergency, tow, utility, and road work vehicles with flashing lights.","p":"Right. Garbage and recycling trucks are covered."},"es":{"q":"En Alabama, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley Move Over?","o":["Una camioneta de reparto estacionada","Un carro parado en un semáforo en rojo","Un camión de basura o reciclaje","Un autobús en su parada normal"],"h1":"La ley protege a muchos trabajadores en la orilla del camino, no solo a la policía.","h2":"La ley Move Over de Alabama incluye los camiones de basura y de reciclaje que están recogiendo al lado de la calle, además de los vehículos de policía, emergencia, grúa, servicios públicos y obras con luces intermitentes.","p":"Correcto. Los camiones de basura y reciclaje están incluidos."},"zh":{"q":"在 Alabama，下面哪一种车灯在闪的停着的车辆，也受 Move Over 法保护？","o":["停着的送货车","在红灯前停着的车","垃圾车或回收车","在一般公车站停着的公车"],"h1":"这条法律保护很多在路边工作的人，不只是警察。","h2":"Alabama 的 Move Over 法保护在路边收垃圾和回收物的垃圾车和回收车，也保护车灯在闪的警车、急救车、拖车、公用事业车和道路施工车。","p":"对。垃圾车和回收车也受保护。"},"vi":{"q":"Ở Alabama, xe nào sau đây đang dừng và nháy đèn cũng được bảo vệ bởi luật Nhường Làn (Move Over law)?","o":["Xe tải giao hàng đang đậu","Xe hơi dừng ở đèn đỏ","Xe chở rác hoặc xe tái chế","Xe buýt ở trạm xe buýt thường"],"h1":"Luật bảo vệ nhiều người làm việc bên đường, không chỉ cảnh sát.","h2":"Luật Nhường Làn ở Alabama bảo vệ xe chở rác và xe tái chế đang thu gom bên đường, cũng như xe cảnh sát, xe khẩn cấp, xe kéo, xe tiện ích, và xe làm đường có đèn nháy.","p":"Đúng. Xe chở rác và xe tái chế được bảo vệ."},"tl":{"q":"Sa Alabama, alin sa mga nakahintong sasakyang ito na may kumikislap na ilaw ang sakop din ng Move Over law?","o":["Nakaparadang delivery van","Kotseng nakahinto sa red light","Trak ng basura o recycling","Bus sa karaniwang hintuan ng bus"],"h1":"Pinoprotektahan ng batas ang maraming manggagawa sa gilid ng kalsada, hindi lang ang pulis.","h2":"Sakop ng Move Over law ng Alabama ang mga trak ng basura at recycling na nangongolekta sa gilid ng kalsada, pati ang mga sasakyan ng pulis, emergency, tow, utility, at road work na may kumikislap na ilaw.","p":"Tama. Sakop ang mga trak ng basura at recycling."},"ar":{"q":"في Alabama، أي من هذه المركبات المتوقّفة ذات الأضواء الوامضة يشملها أيضًا قانون الابتعاد (Move Over law)؟","o":["شاحنة توصيل متوقّفة","سيارة متوقّفة عند إشارة حمراء","شاحنة نفايات أو إعادة تدوير","حافلة في موقف حافلات عادي"],"h1":"القانون يحمي كثيرًا من العاملين على جانب الطريق، لا الشرطة فقط.","h2":"قانون الابتعاد في Alabama يشمل شاحنات النفايات وإعادة التدوير التي تجمع على جانب الطريق، وكذلك مركبات الشرطة والطوارئ والسحب والمرافق وأعمال الطرق ذات الأضواء الوامضة.","p":"صحيح. شاحنات النفايات وإعادة التدوير مشمولة."},"ref":{"doc":"AL","page":null}},{"id":"al-022","scope":"AL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alabama, a school bus is stopped with red lights flashing on the other side of a four-lane highway divided by a median. What must you do?","o":["Stop until the bus moves","Stop, then pass at 10 mph","Pull onto the shoulder","Continue carefully without stopping"],"h1":"A median between you and the bus changes the rule.","h2":"In Alabama, on a divided highway with a median, only traffic going the same direction as the bus must stop, so you may continue carefully while watching for children.","p":"Right. With a median, opposite traffic continues with care."},"es":{"q":"En Alabama, un autobús escolar está detenido con luces rojas al otro lado de una carretera de cuatro carriles dividida por una mediana. ¿Qué debe hacer?","o":["Parar hasta que el autobús avance","Parar y luego pasar a 10 mph","Salirse al acotamiento","Seguir con cuidado sin parar"],"h1":"Una mediana entre usted y el autobús cambia la regla.","h2":"En Alabama, en una carretera dividida por una mediana, solo debe parar el tráfico que va en la misma dirección que el autobús, así que usted puede seguir con cuidado y atento a los niños.","p":"Correcto. Con mediana, el tráfico contrario sigue con cuidado."},"zh":{"q":"在 Alabama，一辆校车停在有中间隔离带的四车道公路的对面，红灯在闪。你必须怎么做？","o":["停车，直到校车开走","停车，然后以 10 mph 开过去","开到路肩上","小心地继续开，不用停车"],"h1":"你和校车之间有隔离带，规定就不一样。","h2":"在 Alabama，在有中间隔离带的分隔公路上，只有和校车同方向的车必须停车，所以你可以小心地继续开，同时注意孩子。","p":"对。有隔离带时，对面方向的车小心地继续开。"},"vi":{"q":"Ở Alabama, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của xa lộ bốn làn có dải phân cách giữa. Bạn phải làm gì?","o":["Dừng cho đến khi xe buýt chạy","Dừng, rồi vượt qua ở 10 mph","Tấp vào lề đường","Tiếp tục đi cẩn thận mà không dừng"],"h1":"Dải phân cách giữa bạn và xe buýt làm quy định thay đổi.","h2":"Ở Alabama, trên xa lộ có dải phân cách giữa, chỉ xe đi cùng chiều với xe buýt phải dừng, nên bạn có thể tiếp tục đi cẩn thận và để ý trẻ em.","p":"Đúng. Có dải phân cách, xe ngược chiều tiếp tục đi cẩn thận."},"tl":{"q":"Sa Alabama, may school bus na nakahinto na may kumikislap na pulang ilaw sa kabilang panig ng highway na may apat na lane at may median sa gitna. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Huminto, saka dumaan sa 10 mph","Tumabi sa shoulder","Magpatuloy nang maingat nang hindi humihinto"],"h1":"Binabago ng median sa pagitan mo at ng bus ang patakaran.","h2":"Sa Alabama, sa divided highway na may median, ang mga sasakyang papunta lang sa parehong direksyon ng bus ang dapat huminto, kaya puwede kang magpatuloy nang maingat habang nagbabantay sa mga bata.","p":"Tama. Kapag may median, nagpapatuloy nang maingat ang kasalubong na trapiko."},"ar":{"q":"في Alabama، حافلة مدرسية متوقّفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع بأربعة مسارات يفصله حاجز وسطي. ماذا يجب أن تفعل؟","o":["توقّف حتى تتحرّك الحافلة","توقّف، ثم تجاوز بسرعة 10 mph","انتقل إلى كتف الطريق","تابع بحذر دون أن تتوقّف"],"h1":"وجود حاجز وسطي بينك وبين الحافلة يغيّر القاعدة.","h2":"في Alabama، على طريق سريع مقسوم بحاجز وسطي، يجب أن تتوقّف فقط المركبات التي تسير في نفس اتجاه الحافلة، لذلك يمكنك أن تتابع بحذر مع الانتباه إلى الأطفال.","p":"صحيح. مع وجود حاجز وسطي، تتابع حركة الاتجاه المقابل بحذر."},"ref":{"doc":"AL","page":61}},{"id":"al-023","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, a school bus stops with red lights flashing on a four-lane road with no median. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic facing the bus","Only trucks and buses"],"h1":"Without a median, children may cross every lane.","h2":"In Alabama, on a four-lane road with no median, traffic in both directions must stop for a school bus with flashing red lights, because children may cross all the lanes.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Alabama, un autobús escolar se detiene con luces rojas en una vía de cuatro carriles sin mediana. ¿Quién debe parar?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico de frente","Solo camiones y autobuses"],"h1":"Sin mediana, los niños pueden cruzar todos los carriles.","h2":"En Alabama, en una vía de cuatro carriles sin mediana, el tráfico en ambas direcciones debe parar ante un autobús escolar con luces rojas intermitentes, porque los niños pueden cruzar todos los carriles.","p":"Correcto. Sin mediana, todos paran."},"zh":{"q":"在 Alabama，一辆校车停在没有中间隔离带的四车道道路上，红灯在闪。谁必须停车？","o":["两个方向的车","只有校车后面的车","只有面对校车的车","只有卡车和公车"],"h1":"没有隔离带，孩子可能会穿过每一条车道。","h2":"在 Alabama，在没有中间隔离带的四车道道路上，两个方向的车都必须为红灯闪烁的校车停车，因为孩子可能会穿过所有车道。","p":"对。没有隔离带，大家都要停车。"},"vi":{"q":"Ở Alabama, một xe buýt trường học dừng và nháy đèn đỏ trên đường bốn làn không có dải phân cách giữa. Ai phải dừng?","o":["Xe ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe đối diện xe buýt","Chỉ xe tải và xe buýt"],"h1":"Không có dải phân cách, trẻ em có thể băng qua mọi làn.","h2":"Ở Alabama, trên đường bốn làn không có dải phân cách giữa, xe ở cả hai chiều phải dừng khi xe buýt trường học nháy đèn đỏ, vì trẻ em có thể băng qua tất cả các làn.","p":"Đúng. Không có dải phân cách, mọi người đều dừng."},"tl":{"q":"Sa Alabama, huminto ang school bus na may kumikislap na pulang ilaw sa kalsadang may apat na lane na walang median. Sino ang dapat huminto?","o":["Trapiko sa parehong direksyon","Trapiko lang sa likod ng bus","Trapiko lang na nakaharap sa bus","Mga trak at bus lang"],"h1":"Kapag walang median, puwedeng tumawid ang mga bata sa lahat ng lane.","h2":"Sa Alabama, sa kalsadang may apat na lane na walang median, dapat huminto ang trapiko sa parehong direksyon para sa school bus na may kumikislap na pulang ilaw, dahil puwedeng tumawid ang mga bata sa lahat ng lane.","p":"Tama. Kapag walang median, lahat ay humihinto."},"ar":{"q":"في Alabama، تتوقّف حافلة مدرسية وأضواؤها الحمراء تومض على طريق بأربعة مسارات بدون حاجز وسطي. من يجب أن يتوقّف؟","o":["الحركة في الاتجاهين","الحركة خلف الحافلة فقط","الحركة المواجهة للحافلة فقط","الشاحنات والحافلات فقط"],"h1":"بدون حاجز وسطي، قد يعبر الأطفال كل المسارات.","h2":"في Alabama، على طريق بأربعة مسارات بدون حاجز وسطي، يجب أن تتوقّف الحركة في الاتجاهين من أجل حافلة مدرسية أضواؤها الحمراء تومض، لأن الأطفال قد يعبرون كل المسارات.","p":"صحيح. بدون حاجز وسطي، يتوقّف الجميع."},"ref":{"doc":"AL","page":61}},{"id":"al-024","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Alabama's hands-free law, when is holding a phone while driving a violation?","o":["Only on interstate highways","When you also drive poorly, like swerving","Only between midnight and 6 a.m.","Never, if you hold it below the window"],"h1":"Police look at how you drive while the phone is in your hand.","h2":"Under the Alabama hands-free law, holding a phone while driving is a violation when you are also seen driving poorly, such as swerving or changing lanes without a signal, so it is safest to keep the phone out of your hand.","p":"Right. Holding a phone breaks the law when you also drive poorly, like swerving."},"es":{"q":"Según la ley de manos libres de Alabama, ¿cuándo es una infracción sostener el teléfono mientras maneja?","o":["Solo en las autopistas interestatales","Cuando además maneja mal, como zigzaguear","Solo entre la medianoche y las 6 a.m.","Nunca, si lo sostiene debajo de la ventana"],"h1":"La policía se fija en cómo maneja usted mientras tiene el teléfono en la mano.","h2":"Según la ley de manos libres de Alabama, sostener el teléfono mientras maneja es una infracción cuando además lo ven manejando mal, por ejemplo zigzagueando o cambiando de carril sin señalar, así que lo más seguro es no tener el teléfono en la mano.","p":"Correcto. Sostener el teléfono es ilegal cuando además maneja mal, como zigzaguear."},"zh":{"q":"根据 Alabama 的免持（hands-free）法，开车时手拿电话什么时候算违规？","o":["只在州际公路上","同时开得不好时，比如左右乱晃","只在午夜到早上 6 点之间","从来不算，只要拿在车窗下面"],"h1":"警察会看你手拿电话时怎样开车。","h2":"根据 Alabama 的免持法，开车时手拿电话，如果同时被看到开得不好，比如左右乱晃或不打灯就换道，就算违规，所以最安全的做法是不要把电话拿在手里。","p":"对。手拿电话又开得不好，比如左右乱晃，就违法了。"},"vi":{"q":"Theo luật rảnh tay (hands-free law) của Alabama, khi nào cầm điện thoại lúc lái xe là vi phạm?","o":["Chỉ trên xa lộ liên bang","Khi bạn cũng lái kém, như lạng lách","Chỉ từ nửa đêm đến 6 giờ sáng","Không bao giờ, nếu cầm thấp dưới cửa sổ"],"h1":"Cảnh sát xem cách bạn lái xe khi điện thoại đang ở trong tay bạn.","h2":"Theo luật rảnh tay của Alabama, cầm điện thoại khi lái xe là vi phạm khi bạn cũng bị thấy lái xe kém, như lạng lách hoặc chuyển làn không bật đèn xi nhan, nên an toàn nhất là không cầm điện thoại trong tay.","p":"Đúng. Cầm điện thoại là phạm luật khi bạn cũng lái kém, như lạng lách."},"tl":{"q":"Ayon sa hands-free law ng Alabama, kailan paglabag ang paghawak ng telepono habang nagmamaneho?","o":["Sa mga interstate highway lang","Kapag mali rin ang pagmamaneho mo, gaya ng pagpapagewang-gewang","Mula hatinggabi hanggang 6 a.m. lang","Hindi kailanman, kung hawak mo ito sa ibaba ng bintana"],"h1":"Tinitingnan ng pulis kung paano ka nagmamaneho habang hawak mo ang telepono.","h2":"Ayon sa hands-free law ng Alabama, paglabag ang paghawak ng telepono habang nagmamaneho kapag nakita ka ring nagmamaneho nang mali, gaya ng pagpapagewang-gewang o paglipat ng lane nang walang signal, kaya pinakaligtas na huwag hawakan ang telepono.","p":"Tama. Labag sa batas ang paghawak ng telepono kapag mali rin ang pagmamaneho mo, gaya ng pagpapagewang-gewang."},"ar":{"q":"بموجب قانون القيادة بدون استخدام اليدين (hands-free law) في Alabama، متى يكون حمل الهاتف أثناء القيادة مخالفة؟","o":["على الطرق السريعة بين الولايات فقط","عندما تقود أيضًا بشكل سيئ، مثل التمايل","بين منتصف الليل و6 صباحًا فقط","أبدًا، إذا أمسكته تحت مستوى النافذة"],"h1":"تنظر الشرطة إلى طريقة قيادتك والهاتف في يدك.","h2":"بموجب قانون القيادة بدون استخدام اليدين في Alabama، يكون حمل الهاتف أثناء القيادة مخالفة عندما تُرى أيضًا تقود بشكل سيئ، مثل التمايل أو تغيير المسار بدون إشارة، لذلك الأكثر أمانًا أن تُبقي الهاتف خارج يدك.","p":"صحيح. حمل الهاتف مخالف للقانون عندما تقود أيضًا بشكل سيئ، مثل التمايل."},"ref":{"doc":"AL","page":16}},{"id":"al-025","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, is it legal for an adult driver to read or send a text message while driving?","o":["Yes, on straight roads","Yes, if the car is slow","No, texting is banned","Yes, for short messages"],"h1":"Texting takes your eyes off the road for several seconds.","h2":"Alabama bans writing, sending, or reading text messages while driving for every driver, because texting takes your eyes and mind off the road.","p":"Right. Texting while driving is against the law in Alabama."},"es":{"q":"En Alabama, ¿es legal que un conductor adulto lea o envíe un mensaje de texto mientras maneja?","o":["Sí, en caminos rectos","Sí, si va despacio","No, está prohibido","Sí, si el mensaje es corto"],"h1":"Escribir mensajes le quita la vista del camino varios segundos.","h2":"Alabama prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan, porque eso le quita la vista y la atención del camino.","p":"Correcto. En Alabama está prohibido escribir mensajes al manejar."},"zh":{"q":"在 Alabama，成年司机开车时看或发短信合法吗？","o":["合法，在直路上","合法，如果车开得慢","不合法，禁止发短信","合法，如果是短的信息"],"h1":"发短信会让你的眼睛离开道路好几秒。","h2":"Alabama 禁止所有司机开车时写、发或看短信，因为发短信会让你的眼睛和注意力离开道路。","p":"对。在 Alabama 开车时发短信是违法的。"},"vi":{"q":"Ở Alabama, người lái xe trưởng thành có được đọc hoặc gửi tin nhắn khi lái xe không?","o":["Được, trên đường thẳng","Được, nếu xe chạy chậm","Không, nhắn tin bị cấm","Được, với tin nhắn ngắn"],"h1":"Nhắn tin làm mắt bạn rời khỏi đường trong vài giây.","h2":"Alabama cấm mọi người lái xe viết, gửi, hoặc đọc tin nhắn khi lái xe, vì nhắn tin làm mắt và tâm trí bạn rời khỏi đường.","p":"Đúng. Nhắn tin khi lái xe là phạm luật ở Alabama."},"tl":{"q":"Sa Alabama, legal ba para sa adult na drayber na magbasa o magpadala ng text message habang nagmamaneho?","o":["Oo, sa tuwid na kalsada","Oo, kung mabagal ang sasakyan","Hindi, bawal ang pag-text","Oo, para sa maikling mensahe"],"h1":"Inilalayo ng pag-text ang mata mo sa kalsada nang ilang segundo.","h2":"Ipinagbabawal ng Alabama sa lahat ng drayber ang pagsulat, pagpapadala, o pagbabasa ng text message habang nagmamaneho, dahil inilalayo ng pag-text ang iyong mata at isip sa kalsada.","p":"Tama. Labag sa batas sa Alabama ang pag-text habang nagmamaneho."},"ar":{"q":"في Alabama، هل يجوز قانونًا للسائق البالغ أن يقرأ أو يرسل رسالة نصية أثناء القيادة؟","o":["نعم، على الطرق المستقيمة","نعم، إذا كانت السيارة بطيئة","لا، الرسائل النصية ممنوعة","نعم، للرسائل القصيرة"],"h1":"الرسائل النصية تُبعد عينيك عن الطريق عدة ثوانٍ.","h2":"تمنع Alabama كل السائقين من كتابة الرسائل النصية أو إرسالها أو قراءتها أثناء القيادة، لأن الرسائل النصية تُبعد عينيك وذهنك عن الطريق.","p":"صحيح. كتابة الرسائل النصية أثناء القيادة مخالفة للقانون في Alabama."},"ref":{"doc":"AL","page":32}},{"id":"al-026","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, a driver under 21 can be charged with DUI at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"The limit for young drivers is far below the adult limit.","h2":"In Alabama a driver under 21 can be charged with DUI at a blood alcohol level of 0.02 percent, which is much lower than the adult limit, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Alabama, ¿con qué nivel de alcohol en la sangre se puede acusar de manejar ebrio a un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"El límite para los jóvenes es mucho más bajo que el de los adultos.","h2":"En Alabama a un conductor menor de 21 años se le puede acusar de manejar ebrio con 0.02 por ciento de alcohol en la sangre, mucho menos que el límite de los adultos, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Alabama，21 岁以下的司机血液酒精浓度达到多少，就可能被控 DUI（酒后驾驶）？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"年轻司机的限制比成年人的低很多。","h2":"在 Alabama，21 岁以下的司机血液酒精浓度达到 0.02%，就可能被控 DUI，这比成年人的限制低很多，因为年轻司机根本不应该喝酒。","p":"对。21 岁以下，限制是 0.02%。"},"vi":{"q":"Ở Alabama, người lái dưới 21 tuổi có thể bị buộc tội lái xe khi say (DUI) ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Giới hạn cho người lái trẻ thấp hơn nhiều so với người lớn.","h2":"Ở Alabama, người lái dưới 21 tuổi có thể bị buộc tội DUI ở nồng độ cồn trong máu 0.02 phần trăm, thấp hơn nhiều so với giới hạn của người lớn, vì người lái trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Alabama, sa anong blood alcohol level puwedeng kasuhan ng DUI ang drayber na wala pang 21?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa nang malaki ang limit para sa mga batang drayber kaysa sa limit ng adult.","h2":"Sa Alabama, ang drayber na wala pang 21 ay puwedeng kasuhan ng DUI sa blood alcohol level na 0.02 porsiyento, na mas mababa nang malaki kaysa sa limit ng adult, dahil hindi talaga dapat uminom ang mga batang drayber.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في Alabama، عند أي نسبة كحول في الدم يمكن اتهام سائق عمره أقل من 21 سنة بالقيادة تحت التأثير (DUI)؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"الحدّ للسائقين الصغار أقل بكثير من حدّ البالغين.","h2":"في Alabama يمكن اتهام سائق عمره أقل من 21 سنة بالقيادة تحت التأثير (DUI) عند نسبة كحول في الدم 0.02 بالمئة، وهي أقل بكثير من حدّ البالغين، لأن السائقين الصغار يجب ألّا يشربوا الكحول إطلاقًا.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02 بالمئة."},"ref":{"doc":"AL","page":33}},{"id":"al-027","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a driver age 21 or older is legally under the influence at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.15 percent or more"],"h1":"It is the same adult limit used in most states.","h2":"An Alabama driver age 21 or older is legally under the influence at a blood alcohol level of 0.08 percent or more, although alcohol can affect driving at lower levels too.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Alabama, un conductor de 21 años o más está legalmente bajo los efectos del alcohol, ¿a partir de qué nivel?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.15 por ciento o más"],"h1":"Es el mismo límite para adultos que usan casi todos los estados.","h2":"En Alabama un conductor de 21 años o más está legalmente bajo los efectos del alcohol con 0.08 por ciento o más, aunque el alcohol puede afectar el manejo con niveles más bajos.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Alabama，21 岁或以上的司机，血液酒精浓度达到多少在法律上算酒后驾驶？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.15% 或更高"],"h1":"它和大多数州用的成年人限制一样。","h2":"Alabama 21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，在法律上就算酒后驾驶，不过浓度更低时酒精也会影响开车。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Alabama, người lái từ 21 tuổi trở lên bị xem là say theo luật ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.15 phần trăm trở lên"],"h1":"Đây là giới hạn người lớn giống ở hầu hết các tiểu bang.","h2":"Người lái ở Alabama từ 21 tuổi trở lên bị xem là say theo luật ở nồng độ cồn trong máu 0.08 phần trăm trở lên, dù rượu bia cũng có thể ảnh hưởng đến việc lái xe ở mức thấp hơn.","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Alabama, sa anong blood alcohol level itinuturing na lasing ayon sa batas ang drayber na 21 taong gulang pataas?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.15 porsiyento o higit pa"],"h1":"Ito ang parehong limit ng adult na ginagamit sa karamihan ng estado.","h2":"Ang drayber sa Alabama na 21 taong gulang pataas ay itinuturing na lasing ayon sa batas sa blood alcohol level na 0.08 porsiyento o higit pa, kahit puwede ring maapektuhan ng alak ang pagmamaneho sa mas mababang level.","p":"Tama. Ang limit ng adult ay 0.08 porsiyento."},"ar":{"q":"في Alabama، عند أي نسبة كحول في الدم يُعدّ السائق الذي عمره 21 سنة أو أكثر تحت التأثير قانونيًا؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.15 بالمئة أو أكثر"],"h1":"إنه نفس حدّ البالغين المستخدم في معظم الولايات.","h2":"السائق في Alabama الذي عمره 21 سنة أو أكثر يُعدّ تحت التأثير قانونيًا عند نسبة كحول في الدم 0.08 بالمئة أو أكثر، مع أن الكحول قد يؤثّر في القيادة عند نسب أقل أيضًا.","p":"صحيح. حدّ البالغين هو 0.08 بالمئة."},"ref":{"doc":"AL","page":33}},{"id":"al-028","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama uses the same number for one person and for property damage.","h2":"Alabama requires at least $25,000 of liability coverage for injury to one person, as part of the 25/50/25 minimum that every driver must carry.","p":"Right. The minimum is $25,000 per person."},"es":{"q":"En Alabama, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama usa el mismo número para una persona y para daños a la propiedad.","h2":"Alabama exige por lo menos $25,000 de cobertura de responsabilidad por lesiones a una persona, como parte del mínimo de 25/50/25 que todo conductor debe tener.","p":"Correcto. El mínimo es $25,000 por persona."},"zh":{"q":"在 Alabama，车祸中一个人受伤的最低责任保险是多少？","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama 对一个人和对财产损失用同一个数字。","h2":"Alabama 要求一个人受伤至少要有 $25,000 的责任保险，这是每位司机都必须买的 25/50/25 最低标准的一部分。","p":"对。最低标准是每人 $25,000。"},"vi":{"q":"Ở Alabama, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Alabama dùng cùng một con số cho một người và cho thiệt hại tài sản.","h2":"Alabama yêu cầu ít nhất $25,000 bảo hiểm trách nhiệm cho thương tích của một người, là một phần của mức tối thiểu 25/50/25 mà mọi người lái phải có.","p":"Đúng. Mức tối thiểu là $25,000 cho mỗi người."},"tl":{"q":"Sa Alabama, ano ang minimum na liability insurance para sa pinsala sa isang tao sa banggaan?","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"Pareho ang bilang na ginagamit ng Alabama para sa isang tao at para sa pinsala sa ari-arian.","h2":"Hinihingi ng Alabama ang hindi bababa sa $25,000 na liability coverage para sa pinsala sa isang tao, bilang bahagi ng 25/50/25 na minimum na dapat taglayin ng bawat drayber.","p":"Tama. Ang minimum ay $25,000 bawat tao."},"ar":{"q":"في Alabama، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$15,000","$20,000","$25,000"],"h1":"تستخدم Alabama نفس الرقم لشخص واحد ولأضرار الممتلكات.","h2":"تشترط Alabama تغطية مسؤولية لا تقل عن $25,000 لإصابة شخص واحد، كجزء من الحدّ الأدنى 25/50/25 الذي يجب أن يحمله كل سائق.","p":"صحيح. الحدّ الأدنى هو $25,000 لكل شخص."},"ref":{"doc":"AL","page":68}},{"id":"al-029","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, when must your headlights be on during the day?","o":["Only on interstates","When wipers are on for rain","Only in school zones","When the radio is off"],"h1":"Think about bad weather.","h2":"In Alabama your headlights must be on when you use your windshield wipers because of rain, sleet, or snow, so other drivers can see you.","p":"Right. Wipers on for rain means headlights on."},"es":{"q":"En Alabama, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo en las interestatales","Con los limpiaparabrisas por lluvia","Solo en zonas escolares","Cuando el radio está apagado"],"h1":"Piense en el mal tiempo.","h2":"En Alabama usted debe encender las luces delanteras cuando usa los limpiaparabrisas por lluvia, aguanieve o nieve, para que los demás conductores lo vean.","p":"Correcto. Si usa los limpiaparabrisas por lluvia, encienda las luces."},"zh":{"q":"在 Alabama，白天什么时候必须打开大灯？","o":["只在州际公路上","因为下雨打开雨刷时","只在学校区","收音机关着时"],"h1":"想一想坏天气。","h2":"在 Alabama，因为下雨、冻雨或下雪而用雨刷时，你必须打开大灯，这样其他司机能看到你。","p":"对。下雨开雨刷，就要开大灯。"},"vi":{"q":"Ở Alabama, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ liên bang","Khi bật cần gạt nước vì mưa","Chỉ trong khu trường học","Khi tắt radio"],"h1":"Hãy nghĩ đến thời tiết xấu.","h2":"Ở Alabama, bạn phải bật đèn pha khi dùng cần gạt nước vì mưa, mưa đá nhỏ, hoặc tuyết, để các người lái khác có thể thấy bạn.","p":"Đúng. Bật cần gạt nước vì mưa thì phải bật đèn pha."},"tl":{"q":"Sa Alabama, kailan dapat nakabukas ang iyong headlights sa araw?","o":["Sa mga interstate lang","Kapag nakabukas ang wipers dahil sa ulan","Sa mga school zone lang","Kapag nakapatay ang radyo"],"h1":"Isipin ang masamang panahon.","h2":"Sa Alabama, dapat nakabukas ang iyong headlights kapag ginagamit mo ang windshield wipers dahil sa ulan, sleet, o niyebe, para makita ka ng ibang drayber.","p":"Tama. Kapag nakabukas ang wipers dahil sa ulan, buksan ang headlights."},"ar":{"q":"في Alabama، متى يجب أن تكون المصابيح الأمامية مضاءة في النهار؟","o":["على الطرق السريعة بين الولايات فقط","عند تشغيل المسّاحات بسبب المطر","في مناطق المدارس فقط","عندما يكون الراديو مطفأ"],"h1":"فكّر في الطقس السيئ.","h2":"في Alabama يجب أن تكون مصابيحك الأمامية مضاءة عندما تستخدم مسّاحات الزجاج الأمامي بسبب المطر أو المطر المتجمّد أو الثلج، ليتمكّن السائقون الآخرون من رؤيتك.","p":"صحيح. تشغيل المسّاحات بسبب المطر يعني تشغيل المصابيح الأمامية."},"ref":{"doc":"AL","page":71}},{"id":"al-030","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, how close to the nearest rail of a railroad crossing may you park?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"It is farther than the distance for a fire hydrant.","h2":"In Alabama you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the tracks when you park."},"es":{"q":"En Alabama, ¿a qué distancia del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["10 pies","25 pies","50 pies","100 pies"],"h1":"Es más lejos que la distancia para un hidrante.","h2":"En Alabama usted no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies de las vías al estacionarse."},"zh":{"q":"在 Alabama，停车时离铁路道口最近的铁轨至少要多远？","o":["10 英尺","25 英尺","50 英尺","100 英尺"],"h1":"这个距离比离消防栓的距离更远。","h2":"在 Alabama，你不可以在离铁路道口最近的铁轨 50 英尺以内停车。","p":"对。停车时要离铁轨至少 50 英尺。"},"vi":{"q":"Ở Alabama, bạn được đỗ xe cách đường ray gần nhất của chỗ giao với đường sắt bao xa?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"Khoảng cách này xa hơn khoảng cách với trụ nước cứu hỏa.","h2":"Ở Alabama, bạn không được đỗ xe trong vòng 50 feet tính từ đường ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Khi đỗ xe, hãy cách đường ray ít nhất 50 feet."},"tl":{"q":"Sa Alabama, gaano kalapit sa pinakamalapit na riles ng tawiran ng tren ka puwedeng pumarada?","o":["10 talampakan","25 talampakan","50 talampakan","100 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa Alabama, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa pinakamalapit na riles ng tawiran ng tren.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan mula sa riles."},"ar":{"q":"في Alabama، على أي مسافة من أقرب سكة في معبر السكة الحديدية يمكنك أن تركن سيارتك؟","o":["10 أقدام","25 قدمًا","50 قدمًا","100 قدم"],"h1":"هذه المسافة أبعد من المسافة المطلوبة عن حنفية الإطفاء.","h2":"في Alabama لا يجوز لك أن تركن سيارتك على مسافة أقل من 50 قدمًا من أقرب سكة في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من السكة عندما تركن."},"ref":{"doc":"AL","page":29}},{"id":"al-031","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, you are driving at night behind another car. Within what distance must you dim your high beams?","o":["200 feet","50 feet","1,000 feet","1 mile"],"h1":"The distance is shorter than for a car coming toward you.","h2":"In Alabama you must dim your headlights when you are within 200 feet of a vehicle you are following.","p":"Right. Use low beams within 200 feet of the car ahead."},"es":{"q":"En Alabama, usted maneja de noche detrás de otro carro. ¿A qué distancia debe bajar las luces altas?","o":["200 pies","50 pies","1,000 pies","1 milla"],"h1":"La distancia es menor que para un carro que viene de frente.","h2":"En Alabama usted debe bajar las luces cuando está a 200 pies o menos de un vehículo que va delante.","p":"Correcto. Use las luces bajas a 200 pies del carro de adelante."},"zh":{"q":"在 Alabama，你晚上开车跟在另一辆车后面。在多远的距离内你必须把远光灯调暗？","o":["200 英尺","50 英尺","1,000 英尺","1 英里"],"h1":"这个距离比迎面来车的距离短。","h2":"在 Alabama，当你离前面跟着的车辆 200 英尺以内时，你必须把车灯调暗。","p":"对。离前车 200 英尺以内要用近光灯。"},"vi":{"q":"Ở Alabama, bạn đang lái xe ban đêm phía sau một xe khác. Trong khoảng cách nào bạn phải giảm đèn pha xuống đèn cốt?","o":["200 feet","50 feet","1,000 feet","1 dặm"],"h1":"Khoảng cách này ngắn hơn so với khi có xe chạy ngược chiều về phía bạn.","h2":"Ở Alabama, bạn phải giảm đèn pha khi bạn ở trong vòng 200 feet phía sau một xe bạn đang đi theo.","p":"Đúng. Dùng đèn cốt khi cách xe phía trước trong vòng 200 feet."},"tl":{"q":"Sa Alabama, nagmamaneho ka sa gabi sa likod ng ibang kotse. Sa loob ng anong layo mo kailangang ibaba ang high beams mo?","o":["200 talampakan","50 talampakan","1,000 talampakan","1 milya"],"h1":"Mas maikli ang layo kaysa sa kotseng papalapit sa iyo.","h2":"Sa Alabama, kailangan mong ibaba ang ilaw mo kapag nasa loob ka ng 200 talampakan mula sa sasakyang sinusundan mo.","p":"Tama. Gumamit ng low beams sa loob ng 200 talampakan mula sa kotse sa unahan."},"ar":{"q":"في Alabama، أنت تقود ليلًا خلف سيارة أخرى. ضمن أي مسافة يجب أن تخفّض الأضواء العالية؟","o":["200 قدم","50 قدمًا","1,000 قدم","1 ميل"],"h1":"هذه المسافة أقصر من المسافة عندما تأتي سيارة نحوك.","h2":"في Alabama يجب أن تخفّض أضواء سيارتك عندما تكون على مسافة 200 قدم أو أقل من مركبة تسير خلفها.","p":"صحيح. استعمل الأضواء المنخفضة ضمن 200 قدم من السيارة التي أمامك."},"ref":{"doc":"AL","page":69}},{"id":"al-032","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how early can you renew your driver license before it expires?","o":["Up to 30 days before","Up to 90 days before","Up to 180 days before","Up to 2 years before"],"h1":"The renewal window is longer than three months but much less than a year.","h2":"In Alabama you may renew your driver license at any time within 180 days before it expires.","p":"Right. You can renew up to 180 days early."},"es":{"q":"En Alabama, ¿con cuánta anticipación puede renovar su licencia de manejar antes de que venza?","o":["Hasta 30 días antes","Hasta 90 días antes","Hasta 180 días antes","Hasta 2 años antes"],"h1":"El plazo para renovar es de más de tres meses, pero mucho menos de un año.","h2":"En Alabama usted puede renovar su licencia de manejar en cualquier momento dentro de los 180 días antes de que venza.","p":"Correcto. Puede renovar hasta 180 días antes."},"zh":{"q":"在 Alabama，驾照到期前最早多久可以续期？","o":["到期前最多 30 天","到期前最多 90 天","到期前最多 180 天","到期前最多 2 年"],"h1":"续期的时间比三个月长，但比一年短很多。","h2":"在 Alabama，你可以在驾照到期前 180 天内的任何时候续期。","p":"对。你最早可以提前 180 天续期。"},"vi":{"q":"Ở Alabama, bạn có thể gia hạn bằng lái sớm bao lâu trước khi bằng hết hạn?","o":["Tối đa 30 ngày trước","Tối đa 90 ngày trước","Tối đa 180 ngày trước","Tối đa 2 năm trước"],"h1":"Thời gian gia hạn dài hơn ba tháng nhưng ngắn hơn một năm nhiều.","h2":"Ở Alabama, bạn có thể gia hạn bằng lái bất cứ lúc nào trong vòng 180 ngày trước khi bằng hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 180 ngày."},"tl":{"q":"Sa Alabama, gaano kaaga mo puwedeng i-renew ang driver license mo bago ito mag-expire?","o":["Hanggang 30 araw bago","Hanggang 90 araw bago","Hanggang 180 araw bago","Hanggang 2 taon bago"],"h1":"Mas mahaba ang panahon ng renewal kaysa tatlong buwan pero mas maikli nang malaki kaysa isang taon.","h2":"Sa Alabama, puwede mong i-renew ang driver license mo anumang oras sa loob ng 180 araw bago ito mag-expire.","p":"Tama. Puwede kang mag-renew hanggang 180 araw nang maaga."},"ar":{"q":"في Alabama، كم من الوقت قبل انتهاء رخصة القيادة يمكنك أن تجدّدها؟","o":["حتى 30 يومًا قبل الانتهاء","حتى 90 يومًا قبل الانتهاء","حتى 180 يومًا قبل الانتهاء","حتى سنتين قبل الانتهاء"],"h1":"مدة التجديد أطول من ثلاثة أشهر، لكنها أقل بكثير من سنة.","h2":"في Alabama يمكنك أن تجدّد رخصة القيادة في أي وقت خلال 180 يومًا قبل انتهائها.","p":"صحيح. يمكنك التجديد قبل الانتهاء بما يصل إلى 180 يومًا."},"ref":{"doc":"AL","page":13}},{"id":"al-033","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, up to how long after your license expires can you renew it without taking the tests again?","o":["6 months","1 year","2 years","3 years"],"h1":"It is more than two years.","h2":"In Alabama you can renew an expired driver license without an exam for up to 3 years after it expired.","p":"Right. You have up to 3 years to renew without a test."},"es":{"q":"En Alabama, ¿hasta cuánto tiempo después de que vence su licencia puede renovarla sin volver a tomar los exámenes?","o":["6 meses","1 año","2 años","3 años"],"h1":"Es más de dos años.","h2":"En Alabama usted puede renovar una licencia vencida sin examen hasta 3 años después de que venció.","p":"Correcto. Tiene hasta 3 años para renovar sin examen."},"zh":{"q":"在 Alabama，驾照过期后最多多长时间内可以续期而不用重新考试？","o":["6 个月","1 年","2 年","3 年"],"h1":"时间比两年更长。","h2":"在 Alabama，驾照过期后最多 3 年内，你可以不用考试就续期。","p":"对。你最多有 3 年时间可以不用考试就续期。"},"vi":{"q":"Ở Alabama, sau khi bằng lái hết hạn, bạn có tối đa bao lâu để gia hạn mà không phải thi lại?","o":["6 tháng","1 năm","2 năm","3 năm"],"h1":"Thời gian đó dài hơn hai năm.","h2":"Ở Alabama, bạn có thể gia hạn bằng lái đã hết hạn mà không phải thi trong vòng tối đa 3 năm sau khi bằng hết hạn.","p":"Đúng. Bạn có tối đa 3 năm để gia hạn mà không phải thi."},"tl":{"q":"Sa Alabama, hanggang gaano katagal matapos mag-expire ang iyong lisensya ka puwedeng mag-renew nang hindi kumukuha ulit ng mga test?","o":["6 na buwan","1 taon","2 taon","3 taon"],"h1":"Mas mahaba ito sa dalawang taon.","h2":"Sa Alabama, puwede mong i-renew ang expired na driver license nang walang exam hanggang 3 taon matapos itong mag-expire.","p":"Tama. May hanggang 3 taon ka para mag-renew nang walang test."},"ar":{"q":"في Alabama، ما أقصى مدة بعد انتهاء رخصتك يمكنك خلالها تجديدها دون إعادة الاختبارات؟","o":["6 أشهر","سنة واحدة (1)","سنتان (2)","3 سنوات"],"h1":"المدة أطول من سنتين.","h2":"في Alabama يمكنك تجديد رخصة القيادة المنتهية دون اختبار حتى 3 سنوات بعد انتهائها.","p":"صحيح. لديك حتى 3 سنوات للتجديد دون اختبار."},"ref":{"doc":"AL","page":13}},{"id":"al-034","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, after you move to a new address in the state, how many days do you have to tell the Driver License Division?","o":["10 days","15 days","60 days","30 days"],"h1":"It is about one month.","h2":"In Alabama you must report your new address to the Driver License Division within 30 days after you move.","p":"Right. Report a new address within 30 days."},"es":{"q":"En Alabama, después de mudarse a una nueva dirección dentro del estado, ¿cuántos días tiene para avisar a la División de Licencias de Manejar?","o":["10 días","15 días","60 días","30 días"],"h1":"Es más o menos un mes.","h2":"En Alabama usted debe informar su nueva dirección a la División de Licencias de Manejar dentro de los 30 días después de mudarse.","p":"Correcto. Informe la nueva dirección dentro de 30 días."},"zh":{"q":"在 Alabama，你在州内搬到新地址后，有几天时间通知驾照部门（Driver License Division）？","o":["10 天","15 天","60 天","30 天"],"h1":"大约一个月。","h2":"在 Alabama，你搬家后必须在 30 天内把新地址报告给驾照部门（Driver License Division）。","p":"对。要在 30 天内报告新地址。"},"vi":{"q":"Ở Alabama, sau khi bạn chuyển đến địa chỉ mới trong tiểu bang, bạn có bao nhiêu ngày để báo cho Phòng Bằng Lái (Driver License Division)?","o":["10 ngày","15 ngày","60 ngày","30 ngày"],"h1":"Khoảng một tháng.","h2":"Ở Alabama, bạn phải báo địa chỉ mới cho Phòng Bằng Lái (Driver License Division) trong vòng 30 ngày sau khi chuyển nhà.","p":"Đúng. Báo địa chỉ mới trong vòng 30 ngày."},"tl":{"q":"Sa Alabama, pagkatapos mong lumipat sa bagong address sa loob ng estado, ilang araw ang mayroon ka para sabihan ang Driver License Division?","o":["10 araw","15 araw","60 araw","30 araw"],"h1":"Mga isang buwan ito.","h2":"Sa Alabama, dapat mong i-report ang bago mong address sa Driver License Division sa loob ng 30 araw pagkatapos mong lumipat.","p":"Tama. I-report ang bagong address sa loob ng 30 araw."},"ar":{"q":"في Alabama، بعد أن تنتقل إلى عنوان جديد داخل الولاية، كم يومًا لديك لإبلاغ قسم رخص القيادة (Driver License Division)؟","o":["10 أيام","15 يومًا","60 يومًا","30 يومًا"],"h1":"المدة نحو شهر واحد.","h2":"في Alabama يجب أن تبلّغ قسم رخص القيادة (Driver License Division) بعنوانك الجديد خلال 30 يومًا بعد انتقالك.","p":"صحيح. أبلغ عن العنوان الجديد خلال 30 يومًا."},"ref":{"doc":"AL","page":14}},{"id":"al-035","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, how much is the fee for each written knowledge test?","o":["$5","$25","$10","$50"],"h1":"It is the smallest amount on the list.","h2":"In Alabama each knowledge test costs $5, and checks are not accepted.","p":"Right. Each knowledge test costs $5."},"es":{"q":"En Alabama, ¿cuánto cuesta cada examen escrito de conocimientos?","o":["$5","$25","$10","$50"],"h1":"Es la cantidad más pequeña de la lista.","h2":"En Alabama cada examen de conocimientos cuesta $5, y no se aceptan cheques.","p":"Correcto. Cada examen de conocimientos cuesta $5."},"zh":{"q":"在 Alabama，每次笔试（知识考试）的费用是多少？","o":["$5","$25","$10","$50"],"h1":"是选项中最少的金额。","h2":"在 Alabama，每次知识考试的费用是 $5，而且不收支票。","p":"对。每次知识考试 $5。"},"vi":{"q":"Ở Alabama, lệ phí cho mỗi lần thi lý thuyết (thi viết) là bao nhiêu?","o":["$5","$25","$10","$50"],"h1":"Đó là số tiền nhỏ nhất trong danh sách.","h2":"Ở Alabama, mỗi lần thi lý thuyết có lệ phí $5, và không nhận ngân phiếu (check).","p":"Đúng. Mỗi lần thi lý thuyết tốn $5."},"tl":{"q":"Sa Alabama, magkano ang bayad sa bawat nakasulat na knowledge test?","o":["$5","$25","$10","$50"],"h1":"Ito ang pinakamaliit na halaga sa listahan.","h2":"Sa Alabama, $5 ang bayad sa bawat knowledge test, at hindi tinatanggap ang tseke.","p":"Tama. $5 ang bawat knowledge test."},"ar":{"q":"في Alabama، كم رسوم كل اختبار معرفة كتابي؟","o":["$5","$25","$10","$50"],"h1":"هو أصغر مبلغ في القائمة.","h2":"في Alabama رسوم كل اختبار معرفة هي $5، ولا تُقبل الشيكات.","p":"صحيح. رسوم كل اختبار معرفة $5."},"ref":{"doc":"AL","page":11}},{"id":"al-036","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, who must come with a 16-year-old applicant to the road test?","o":["Any friend with a license","A parent or guardian","A driving school teacher","No one; they may come alone"],"h1":"It is the adult who is legally responsible for the teen.","h2":"In Alabama a 16-year-old must be accompanied by a parent or guardian when taking the road test.","p":"Right. A parent or guardian must come along."},"es":{"q":"En Alabama, ¿quién debe acompañar a un solicitante de 16 años al examen de manejo?","o":["Cualquier amigo con licencia","Un padre, madre o tutor","Un maestro de escuela de manejo","Nadie; puede ir solo"],"h1":"Es el adulto que es legalmente responsable del joven.","h2":"En Alabama un joven de 16 años debe ir acompañado de su padre, madre o tutor para tomar el examen de manejo.","p":"Correcto. Debe ir un padre, madre o tutor."},"zh":{"q":"在 Alabama，16 岁的申请人参加路考时，谁必须陪同？","o":["任何有驾照的朋友","父母或监护人","驾校老师","不用人陪；可以自己来"],"h1":"是对这个青少年负有法律责任的成年人。","h2":"在 Alabama，16 岁的人参加路考时必须由父母或监护人陪同。","p":"对。父母或监护人必须陪同。"},"vi":{"q":"Ở Alabama, ai phải đi cùng người nộp đơn 16 tuổi đến kỳ thi lái thực hành?","o":["Bất kỳ người bạn nào có bằng lái","Cha mẹ hoặc người giám hộ","Một giáo viên trường dạy lái xe","Không ai; họ có thể tự đi một mình"],"h1":"Đó là người lớn chịu trách nhiệm pháp lý cho thiếu niên đó.","h2":"Ở Alabama, người 16 tuổi phải có cha mẹ hoặc người giám hộ đi cùng khi thi lái thực hành.","p":"Đúng. Cha mẹ hoặc người giám hộ phải đi cùng."},"tl":{"q":"Sa Alabama, sino ang dapat sumama sa 16 na taong gulang na aplikante sa road test?","o":["Kahit sinong kaibigan na may license","Isang magulang o guardian","Isang guro sa driving school","Walang kailangan; puwede siyang pumunta nang mag-isa"],"h1":"Ito ang adult na legal na responsable sa kabataan.","h2":"Sa Alabama, dapat may kasamang magulang o guardian ang 16 na taong gulang kapag kumukuha ng road test.","p":"Tama. Dapat sumama ang isang magulang o guardian."},"ar":{"q":"في Alabama، من يجب أن يرافق المتقدّم الذي عمره 16 سنة إلى اختبار القيادة على الطريق؟","o":["أي صديق لديه رخصة","أحد الوالدين أو الوصي","مدرّب في مدرسة لتعليم القيادة","لا أحد؛ يمكنه أن يأتي وحده"],"h1":"هو الشخص البالغ المسؤول قانونيًا عن المراهق.","h2":"في Alabama يجب أن يرافق أحدُ الوالدين أو الوصيُّ الشخصَ الذي عمره 16 سنة عندما يأخذ اختبار القيادة على الطريق.","p":"صحيح. يجب أن يأتي معه أحد الوالدين أو الوصي."},"ref":{"doc":"AL","page":11}},{"id":"al-037","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, what is the penalty for a first conviction under the hands-free law?","o":["A $25 fine and no points","A $100 fine and 2 points","A $50 fine and 1 point","A $150 fine and 3 points"],"h1":"The penalty grows with each conviction, and this is the first step.","h2":"In Alabama a first hands-free law conviction brings a $50 fine and 1 point on your driving record.","p":"Right. The first conviction is $50 and 1 point."},"es":{"q":"En Alabama, ¿cuál es la sanción por una primera condena bajo la ley de manos libres?","o":["Una multa de $25 y ningún punto","Una multa de $100 y 2 puntos","Una multa de $50 y 1 punto","Una multa de $150 y 3 puntos"],"h1":"La sanción aumenta con cada condena, y este es el primer paso.","h2":"En Alabama una primera condena por la ley de manos libres trae una multa de $50 y 1 punto en su historial de manejo.","p":"Correcto. La primera condena es $50 y 1 punto."},"zh":{"q":"在 Alabama，第一次违反免持（hands-free）法被定罪，处罚是什么？","o":["罚款 $25，不扣分","罚款 $100，记 2 分","罚款 $50，记 1 分","罚款 $150，记 3 分"],"h1":"每次定罪处罚都会加重，这是第一级。","h2":"在 Alabama，第一次违反免持法被定罪，会被罚款 $50，并在驾驶记录上记 1 分。","p":"对。第一次定罪是 $50 和 1 分。"},"vi":{"q":"Ở Alabama, hình phạt cho lần bị kết tội đầu tiên theo luật rảnh tay (hands-free law) là gì?","o":["Phạt $25 và không bị điểm","Phạt $100 và 2 điểm","Phạt $50 và 1 điểm","Phạt $150 và 3 điểm"],"h1":"Hình phạt tăng dần theo mỗi lần bị kết tội, và đây là mức đầu tiên.","h2":"Ở Alabama, lần đầu bị kết tội theo luật rảnh tay sẽ bị phạt $50 và 1 điểm trong hồ sơ lái xe của bạn.","p":"Đúng. Lần đầu bị kết tội là $50 và 1 điểm."},"tl":{"q":"Sa Alabama, ano ang parusa sa unang conviction sa ilalim ng hands-free law?","o":["$25 na multa at walang points","$100 na multa at 2 points","$50 na multa at 1 point","$150 na multa at 3 points"],"h1":"Lumalaki ang parusa sa bawat conviction, at ito ang unang hakbang.","h2":"Sa Alabama, ang unang conviction sa hands-free law ay may $50 na multa at 1 point sa driving record mo.","p":"Tama. $50 at 1 point ang unang conviction."},"ar":{"q":"في Alabama، ما عقوبة الإدانة الأولى بموجب قانون القيادة بدون استخدام اليدين (hands-free law)؟","o":["غرامة $25 بدون نقاط","غرامة $100 ونقطتان","غرامة $50 ونقطة واحدة","غرامة $150 و3 نقاط"],"h1":"تزداد العقوبة مع كل إدانة، وهذه هي الدرجة الأولى.","h2":"في Alabama تؤدي الإدانة الأولى بموجب قانون القيادة بدون استخدام اليدين إلى غرامة $50 ونقطة واحدة في سجل قيادتك.","p":"صحيح. الإدانة الأولى $50 ونقطة واحدة."},"ref":{"doc":"AL","page":16}},{"id":"al-038","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, how many points go on your driving record for each texting-while-driving offense?","o":["1 point","2 points","4 points","6 points"],"h1":"It is the same number for the first, second, and third offense.","h2":"In Alabama each texting-while-driving offense puts 2 points on your driving record, in addition to a fine.","p":"Right. Each texting offense adds 2 points."},"es":{"q":"En Alabama, ¿cuántos puntos se ponen en su historial de manejo por cada infracción de enviar mensajes de texto mientras maneja?","o":["1 punto","2 puntos","4 puntos","6 puntos"],"h1":"Es el mismo número para la primera, la segunda y la tercera infracción.","h2":"En Alabama cada infracción por enviar mensajes de texto mientras maneja pone 2 puntos en su historial, además de una multa.","p":"Correcto. Cada infracción por textear suma 2 puntos."},"zh":{"q":"在 Alabama，每次开车时发短信违规，会在你的驾驶记录上记几分？","o":["1 分","2 分","4 分","6 分"],"h1":"第一次、第二次和第三次违规都是同样的分数。","h2":"在 Alabama，每次开车时发短信违规，除了罚款以外，还会在你的驾驶记录上记 2 分。","p":"对。每次发短信违规记 2 分。"},"vi":{"q":"Ở Alabama, mỗi lần vi phạm nhắn tin khi lái xe sẽ bị ghi bao nhiêu điểm vào hồ sơ lái xe?","o":["1 điểm","2 điểm","4 điểm","6 điểm"],"h1":"Số điểm giống nhau cho lần vi phạm thứ nhất, thứ hai và thứ ba.","h2":"Ở Alabama, mỗi lần vi phạm nhắn tin khi lái xe bị ghi 2 điểm vào hồ sơ lái xe của bạn, ngoài tiền phạt.","p":"Đúng. Mỗi lần vi phạm nhắn tin bị thêm 2 điểm."},"tl":{"q":"Sa Alabama, ilang points ang idinadagdag sa driving record mo sa bawat paglabag sa pag-text habang nagmamaneho?","o":["1 point","2 points","4 points","6 points"],"h1":"Pareho ang bilang sa una, ikalawa, at ikatlong paglabag.","h2":"Sa Alabama, bawat paglabag sa pag-text habang nagmamaneho ay nagdadagdag ng 2 points sa driving record mo, bukod pa sa multa.","p":"Tama. Nagdadagdag ng 2 points ang bawat paglabag sa pag-text."},"ar":{"q":"في Alabama، كم نقطة تُضاف إلى سجل قيادتك عن كل مخالفة كتابة رسائل نصية أثناء القيادة؟","o":["نقطة واحدة","نقطتان","4 نقاط","6 نقاط"],"h1":"العدد نفسه في المخالفة الأولى والثانية والثالثة.","h2":"في Alabama تضيف كل مخالفة كتابة رسائل نصية أثناء القيادة نقطتين (2) إلى سجل قيادتك، بالإضافة إلى الغرامة.","p":"صحيح. كل مخالفة رسائل نصية تضيف نقطتين (2)."},"ref":{"doc":"AL","page":32}},{"id":"al-039","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, how many points are added to your record for passing a stopped school bus?","o":["2 points","3 points","4 points","5 points"],"h1":"It is one of the highest point values for a moving violation.","h2":"In Alabama passing a stopped school bus adds 5 points to your driving record.","p":"Right. Passing a stopped school bus costs 5 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan a su historial por pasar un autobús escolar detenido?","o":["2 puntos","3 puntos","4 puntos","5 puntos"],"h1":"Es uno de los valores de puntos más altos para una infracción de tránsito.","h2":"En Alabama pasar un autobús escolar detenido agrega 5 puntos a su historial de manejo.","p":"Correcto. Pasar un autobús escolar detenido cuesta 5 puntos."},"zh":{"q":"在 Alabama，超过停着的校车，会在你的记录上记几分？","o":["2 分","3 分","4 分","5 分"],"h1":"这是行车违规中分数最高的之一。","h2":"在 Alabama，超过停着的校车会在你的驾驶记录上记 5 分。","p":"对。超过停着的校车记 5 分。"},"vi":{"q":"Ở Alabama, vượt qua xe buýt trường học đang dừng sẽ bị ghi bao nhiêu điểm vào hồ sơ của bạn?","o":["2 điểm","3 điểm","4 điểm","5 điểm"],"h1":"Đó là một trong những mức điểm cao nhất cho vi phạm khi lái xe.","h2":"Ở Alabama, vượt qua xe buýt trường học đang dừng sẽ bị ghi 5 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Vượt xe buýt trường học đang dừng bị 5 điểm."},"tl":{"q":"Sa Alabama, ilang points ang idinadagdag sa record mo kapag nilampasan mo ang nakahintong school bus?","o":["2 points","3 points","4 points","5 points"],"h1":"Isa ito sa pinakamataas na points para sa paglabag habang nagmamaneho.","h2":"Sa Alabama, ang paglampas sa nakahintong school bus ay nagdadagdag ng 5 points sa driving record mo.","p":"Tama. 5 points ang paglampas sa nakahintong school bus."},"ar":{"q":"في Alabama، كم نقطة تُضاف إلى سجلك إذا تجاوزت حافلة مدرسية متوقفة؟","o":["نقطتان","3 نقاط","4 نقاط","5 نقاط"],"h1":"هي من أعلى قيم النقاط لمخالفات القيادة.","h2":"في Alabama يضيف تجاوز حافلة مدرسية متوقفة 5 نقاط إلى سجل قيادتك.","p":"صحيح. تجاوز حافلة مدرسية متوقفة يكلّف 5 نقاط."},"ref":{"doc":"AL","page":19}},{"id":"al-040","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, how many points are added for speeding 1 to 25 mph over the limit?","o":["2 points","5 points","6 points","8 points"],"h1":"It is the lowest point value on Alabama's list.","h2":"In Alabama a speeding ticket for 1 to 25 mph over the limit adds 2 points, while 26 mph or more over adds 5 points.","p":"Right. Speeding up to 25 mph over is 2 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por exceder el límite de velocidad por 1 a 25 mph?","o":["2 puntos","5 puntos","6 puntos","8 puntos"],"h1":"Es el valor de puntos más bajo de la lista de Alabama.","h2":"En Alabama una multa por exceder el límite por 1 a 25 mph agrega 2 puntos, y por 26 mph o más agrega 5 puntos.","p":"Correcto. Exceder hasta 25 mph son 2 puntos."},"zh":{"q":"在 Alabama，超速 1 到 25 mph，会记几分？","o":["2 分","5 分","6 分","8 分"],"h1":"这是 Alabama 记分表上最低的分数。","h2":"在 Alabama，超速 1 到 25 mph 的罚单记 2 分，超速 26 mph 或以上记 5 分。","p":"对。超速最多 25 mph 记 2 分。"},"vi":{"q":"Ở Alabama, chạy quá tốc độ giới hạn từ 1 đến 25 mph sẽ bị ghi bao nhiêu điểm?","o":["2 điểm","5 điểm","6 điểm","8 điểm"],"h1":"Đó là mức điểm thấp nhất trong danh sách của Alabama.","h2":"Ở Alabama, vé phạt chạy quá tốc độ từ 1 đến 25 mph bị ghi 2 điểm, còn quá 26 mph trở lên bị ghi 5 điểm.","p":"Đúng. Chạy quá tối đa 25 mph bị 2 điểm."},"tl":{"q":"Sa Alabama, ilang points ang idinadagdag sa pag-speeding nang 1 hanggang 25 mph lampas sa limit?","o":["2 points","5 points","6 points","8 points"],"h1":"Ito ang pinakamababang points sa listahan ng Alabama.","h2":"Sa Alabama, ang ticket sa pag-speeding nang 1 hanggang 25 mph lampas sa limit ay nagdadagdag ng 2 points, habang 5 points naman kapag 26 mph o higit pa ang lampas.","p":"Tama. 2 points ang pag-speeding nang hanggang 25 mph lampas."},"ar":{"q":"في Alabama، كم نقطة تُضاف عند تجاوز حدّ السرعة بمقدار 1 إلى 25 mph؟","o":["نقطتان","5 نقاط","6 نقاط","8 نقاط"],"h1":"هي أقل قيمة نقاط في قائمة Alabama.","h2":"في Alabama تضيف مخالفة تجاوز حدّ السرعة بمقدار 1 إلى 25 mph نقطتين (2)، أما التجاوز بمقدار 26 mph أو أكثر فيضيف 5 نقاط.","p":"صحيح. تجاوز السرعة حتى 25 mph يكلّف نقطتين (2)."},"ref":{"doc":"AL","page":19}},{"id":"al-041","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a driver who gets 12 to 14 points within 2 years has the license suspended for how long?","o":["30 days","60 days","6 months","1 year"],"h1":"It is the shortest suspension in the point schedule, about two months.","h2":"In Alabama a driver with 12 to 14 points in a 2-year period has the license suspended for 60 days.","p":"Right. 12 to 14 points means a 60-day suspension."},"es":{"q":"En Alabama, a un conductor que acumula de 12 a 14 puntos en 2 años, ¿por cuánto tiempo le suspenden la licencia?","o":["30 días","60 días","6 meses","1 año"],"h1":"Es la suspensión más corta de la tabla de puntos, más o menos dos meses.","h2":"En Alabama a un conductor con 12 a 14 puntos en un período de 2 años le suspenden la licencia por 60 días.","p":"Correcto. De 12 a 14 puntos significa una suspensión de 60 días."},"zh":{"q":"在 Alabama，司机在 2 年内被记 12 到 14 分，驾照会被暂停多久？","o":["30 天","60 天","6 个月","1 年"],"h1":"这是记分表中最短的暂停时间，大约两个月。","h2":"在 Alabama，司机在 2 年内被记 12 到 14 分，驾照会被暂停 60 天。","p":"对。12 到 14 分就暂停 60 天。"},"vi":{"q":"Ở Alabama, người lái bị 12 đến 14 điểm trong vòng 2 năm sẽ bị đình chỉ bằng lái bao lâu?","o":["30 ngày","60 ngày","6 tháng","1 năm"],"h1":"Đó là thời gian đình chỉ ngắn nhất trong bảng điểm, khoảng hai tháng.","h2":"Ở Alabama, người lái có 12 đến 14 điểm trong thời gian 2 năm sẽ bị đình chỉ bằng lái 60 ngày.","p":"Đúng. 12 đến 14 điểm nghĩa là bị đình chỉ 60 ngày."},"tl":{"q":"Sa Alabama, gaano katagal masususpinde ang license ng drayber na nakakuha ng 12 hanggang 14 points sa loob ng 2 taon?","o":["30 araw","60 araw","6 na buwan","1 taon"],"h1":"Ito ang pinakamaikling suspension sa listahan ng points, mga dalawang buwan.","h2":"Sa Alabama, masususpinde nang 60 araw ang license ng drayber na may 12 hanggang 14 points sa loob ng 2 taon.","p":"Tama. 60 araw na suspension ang 12 hanggang 14 points."},"ar":{"q":"في Alabama، السائق الذي يحصل على 12 إلى 14 نقطة خلال سنتين (2)، كم مدة تعليق رخصته؟","o":["30 يومًا","60 يومًا","6 أشهر","سنة واحدة"],"h1":"هي أقصر مدة تعليق في جدول النقاط، نحو شهرين.","h2":"في Alabama السائق الذي لديه 12 إلى 14 نقطة خلال مدة سنتين (2) تُعلَّق رخصته 60 يومًا.","p":"صحيح. من 12 إلى 14 نقطة يعني تعليقًا لمدة 60 يومًا."},"ref":{"doc":"AL","page":19}},{"id":"al-042","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, after a first DUI conviction, how long is the driver license suspended?","o":["90 days","30 days","1 year","3 years"],"h1":"It is about three months.","h2":"In Alabama a first DUI conviction brings a 90-day license suspension, in addition to a fine and possible jail time.","p":"Right. A first DUI means a 90-day suspension."},"es":{"q":"En Alabama, después de una primera condena por manejar bajo los efectos (DUI), ¿por cuánto tiempo se suspende la licencia?","o":["90 días","30 días","1 año","3 años"],"h1":"Son más o menos tres meses.","h2":"En Alabama una primera condena por DUI trae una suspensión de la licencia de 90 días, además de una multa y posible cárcel.","p":"Correcto. Un primer DUI significa una suspensión de 90 días."},"zh":{"q":"在 Alabama，第一次 DUI（酒后驾驶）定罪后，驾照会被暂停多久？","o":["90 天","30 天","1 年","3 年"],"h1":"大约三个月。","h2":"在 Alabama，第一次 DUI 定罪会让驾照被暂停 90 天，另外还有罚款，也可能坐牢。","p":"对。第一次 DUI 暂停 90 天。"},"vi":{"q":"Ở Alabama, sau lần đầu bị kết tội lái xe khi say (DUI), bằng lái bị đình chỉ bao lâu?","o":["90 ngày","30 ngày","1 năm","3 năm"],"h1":"Khoảng ba tháng.","h2":"Ở Alabama, lần đầu bị kết tội DUI sẽ bị đình chỉ bằng lái 90 ngày, cùng với tiền phạt và có thể bị ngồi tù.","p":"Đúng. DUI lần đầu nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Alabama, pagkatapos ng unang DUI conviction, gaano katagal masususpinde ang driver license?","o":["90 araw","30 araw","1 taon","3 taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa Alabama, ang unang DUI conviction ay may 90 araw na suspension ng license, bukod pa sa multa at posibleng pagkakulong.","p":"Tama. 90 araw na suspension ang unang DUI."},"ar":{"q":"في Alabama، بعد الإدانة الأولى بالقيادة تحت التأثير (DUI)، كم مدة تعليق رخصة القيادة؟","o":["90 يومًا","30 يومًا","سنة واحدة","3 سنوات"],"h1":"المدة نحو ثلاثة أشهر.","h2":"في Alabama تؤدي الإدانة الأولى بالقيادة تحت التأثير (DUI) إلى تعليق الرخصة 90 يومًا، بالإضافة إلى غرامة واحتمال السجن.","p":"صحيح. الإدانة الأولى بـ DUI تعني تعليقًا لمدة 90 يومًا."},"ref":{"doc":"AL","page":33}},{"id":"al-043","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, after a third DUI conviction, how long is the driver license revoked?","o":["6 months","1 year","3 years","Only until the fine is paid"],"h1":"It is several years, but less than the revocation for a fourth conviction.","h2":"In Alabama a third DUI conviction brings a 3-year license revocation, along with a large fine and at least 60 days in jail.","p":"Right. A third DUI means a 3-year revocation."},"es":{"q":"En Alabama, después de una tercera condena por DUI, ¿por cuánto tiempo se revoca la licencia?","o":["6 meses","1 año","3 años","Solo hasta pagar la multa"],"h1":"Son varios años, pero menos que la revocación por una cuarta condena.","h2":"En Alabama una tercera condena por DUI trae una revocación de la licencia por 3 años, además de una multa grande y por lo menos 60 días de cárcel.","p":"Correcto. Un tercer DUI significa una revocación de 3 años."},"zh":{"q":"在 Alabama，第三次 DUI 定罪后，驾照会被吊销多久？","o":["6 个月","1 年","3 年","只到罚款付清为止"],"h1":"是好几年，但比第四次定罪的吊销时间短。","h2":"在 Alabama，第三次 DUI 定罪会让驾照被吊销 3 年，还有高额罚款，并至少坐牢 60 天。","p":"对。第三次 DUI 吊销 3 年。"},"vi":{"q":"Ở Alabama, sau lần thứ ba bị kết tội DUI, bằng lái bị thu hồi bao lâu?","o":["6 tháng","1 năm","3 năm","Chỉ đến khi trả xong tiền phạt"],"h1":"Đó là vài năm, nhưng ngắn hơn thời gian thu hồi cho lần bị kết tội thứ tư.","h2":"Ở Alabama, lần thứ ba bị kết tội DUI sẽ bị thu hồi bằng lái 3 năm, cùng với tiền phạt lớn và ít nhất 60 ngày tù.","p":"Đúng. DUI lần thứ ba nghĩa là bị thu hồi 3 năm."},"tl":{"q":"Sa Alabama, pagkatapos ng ikatlong DUI conviction, gaano katagal mare-revoke ang driver license?","o":["6 na buwan","1 taon","3 taon","Hanggang mabayaran lang ang multa"],"h1":"Ilang taon ito, pero mas maikli kaysa sa revocation para sa ikaapat na conviction.","h2":"Sa Alabama, ang ikatlong DUI conviction ay may 3 taon na revocation ng license, kasama ang malaking multa at hindi bababa sa 60 araw na pagkakulong.","p":"Tama. 3 taon na revocation ang ikatlong DUI."},"ar":{"q":"في Alabama، بعد الإدانة الثالثة بالقيادة تحت التأثير (DUI)، كم مدة سحب رخصة القيادة؟","o":["6 أشهر","سنة واحدة","3 سنوات","فقط حتى تُدفع الغرامة"],"h1":"المدة عدة سنوات، لكنها أقل من مدة السحب عند الإدانة الرابعة.","h2":"في Alabama تؤدي الإدانة الثالثة بالقيادة تحت التأثير (DUI) إلى سحب الرخصة 3 سنوات، مع غرامة كبيرة وسجن لا يقل عن 60 يومًا.","p":"صحيح. الإدانة الثالثة بـ DUI تعني سحب الرخصة 3 سنوات."},"ref":{"doc":"AL","page":34}},{"id":"al-044","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, at least how much is the fee to reinstate a license that was suspended or revoked?","o":["$100","$20","$50","$10"],"h1":"It is the largest amount on the list.","h2":"In Alabama you must pay a reinstatement fee of at least $100, plus meet other legal requirements, to get back a suspended or revoked license.","p":"Right. Reinstatement costs at least $100."},"es":{"q":"En Alabama, ¿cuánto cuesta como mínimo la cuota para restablecer una licencia suspendida o revocada?","o":["$100","$20","$50","$10"],"h1":"Es la cantidad más grande de la lista.","h2":"En Alabama usted debe pagar una cuota de restablecimiento de por lo menos $100, y cumplir otros requisitos legales, para recuperar una licencia suspendida o revocada.","p":"Correcto. El restablecimiento cuesta por lo menos $100."},"zh":{"q":"在 Alabama，恢复被暂停或吊销的驾照，费用至少是多少？","o":["$100","$20","$50","$10"],"h1":"是选项中最大的金额。","h2":"在 Alabama，要拿回被暂停或吊销的驾照，你必须支付至少 $100 的恢复费，并满足其他法律要求。","p":"对。恢复驾照至少要 $100。"},"vi":{"q":"Ở Alabama, lệ phí để phục hồi bằng lái đã bị đình chỉ hoặc thu hồi ít nhất là bao nhiêu?","o":["$100","$20","$50","$10"],"h1":"Đó là số tiền lớn nhất trong danh sách.","h2":"Ở Alabama, bạn phải trả lệ phí phục hồi ít nhất $100, và đáp ứng các yêu cầu pháp lý khác, để lấy lại bằng lái đã bị đình chỉ hoặc thu hồi.","p":"Đúng. Phục hồi bằng lái tốn ít nhất $100."},"tl":{"q":"Sa Alabama, hindi bababa sa magkano ang bayad para maibalik ang license na sinuspinde o ni-revoke?","o":["$100","$20","$50","$10"],"h1":"Ito ang pinakamalaking halaga sa listahan.","h2":"Sa Alabama, dapat kang magbayad ng reinstatement fee na hindi bababa sa $100, at tuparin ang iba pang legal na requirement, para maibalik ang sinuspinde o ni-revoke na license.","p":"Tama. Hindi bababa sa $100 ang reinstatement."},"ar":{"q":"في Alabama، كم الحدّ الأدنى لرسوم إعادة رخصة عُلّقت أو سُحبت؟","o":["$100","$20","$50","$10"],"h1":"هو أكبر مبلغ في القائمة.","h2":"في Alabama يجب أن تدفع رسوم إعادة لا تقل عن $100، وأن تستوفي الشروط القانونية الأخرى، لتستعيد رخصة معلّقة أو مسحوبة.","p":"صحيح. إعادة الرخصة تكلّف $100 على الأقل."},"ref":{"doc":"AL","page":17}},{"id":"al-045","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, what is the highest fine for a first conviction of driving without the required liability insurance?","o":["$100","$250","$500","$5,000"],"h1":"A second conviction can cost up to twice this amount.","h2":"In Alabama a first conviction for not having the required liability insurance can bring a fine of up to $500.","p":"Right. The first offense fine is up to $500."},"es":{"q":"En Alabama, ¿cuál es la multa máxima por una primera condena por manejar sin el seguro de responsabilidad obligatorio?","o":["$100","$250","$500","$5,000"],"h1":"Una segunda condena puede costar hasta el doble de esta cantidad.","h2":"En Alabama una primera condena por no tener el seguro de responsabilidad obligatorio puede traer una multa de hasta $500.","p":"Correcto. La multa por la primera vez es de hasta $500."},"zh":{"q":"在 Alabama，第一次因没有法定责任保险开车而被定罪，最高罚款是多少？","o":["$100","$250","$500","$5,000"],"h1":"第二次定罪最多可以罚这个金额的两倍。","h2":"在 Alabama，第一次因没有法定责任保险被定罪，罚款最高可达 $500。","p":"对。第一次违规最高罚 $500。"},"vi":{"q":"Ở Alabama, mức phạt cao nhất cho lần đầu bị kết tội lái xe không có bảo hiểm trách nhiệm bắt buộc là bao nhiêu?","o":["$100","$250","$500","$5,000"],"h1":"Lần bị kết tội thứ hai có thể bị phạt gấp đôi số tiền này.","h2":"Ở Alabama, lần đầu bị kết tội vì không có bảo hiểm trách nhiệm bắt buộc có thể bị phạt tối đa $500.","p":"Đúng. Lần vi phạm đầu bị phạt tối đa $500."},"tl":{"q":"Sa Alabama, ano ang pinakamataas na multa sa unang conviction ng pagmamaneho nang walang required na liability insurance?","o":["$100","$250","$500","$5,000"],"h1":"Puwedeng umabot sa doble ng halagang ito ang ikalawang conviction.","h2":"Sa Alabama, ang unang conviction dahil walang required na liability insurance ay puwedeng magmulta nang hanggang $500.","p":"Tama. Hanggang $500 ang multa sa unang paglabag."},"ar":{"q":"في Alabama، ما أعلى غرامة عند الإدانة الأولى بالقيادة بدون تأمين المسؤولية المطلوب؟","o":["$100","$250","$500","$5,000"],"h1":"الإدانة الثانية قد تكلّف حتى ضعف هذا المبلغ.","h2":"في Alabama قد تؤدي الإدانة الأولى بعدم وجود تأمين المسؤولية المطلوب إلى غرامة تصل إلى $500.","p":"صحيح. غرامة المخالفة الأولى تصل إلى $500."},"ref":{"doc":"AL","page":68}},{"id":"al-046","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, what is the least space you must leave between your car and a person on a bicycle when you pass?","o":["1 foot","18 inches","2 feet","3 feet"],"h1":"It is about one yard, the largest choice here.","h2":"In Alabama you must leave at least 3 feet between your vehicle and a person on a bicycle when you pass.","p":"Right. Give a bicycle rider at least 3 feet."},"es":{"q":"En Alabama, ¿cuál es el espacio mínimo que debe dejar entre su carro y una persona en bicicleta al pasarla?","o":["1 pie","18 pulgadas","2 pies","3 pies"],"h1":"Es más o menos una yarda, la opción más grande aquí.","h2":"En Alabama usted debe dejar por lo menos 3 pies entre su vehículo y una persona en bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies al ciclista."},"zh":{"q":"在 Alabama，超过骑自行车的人时，你的车和他之间至少要留多少空间？","o":["1 英尺","18 英寸","2 英尺","3 英尺"],"h1":"大约一码，是这里最大的选项。","h2":"在 Alabama，超过骑自行车的人时，你的车和他之间必须至少留 3 英尺。","p":"对。给骑自行车的人至少留 3 英尺。"},"vi":{"q":"Ở Alabama, khi vượt người đi xe đạp, bạn phải chừa khoảng cách ít nhất bao nhiêu giữa xe bạn và người đó?","o":["1 foot (bộ)","18 inch","2 feet (bộ)","3 feet (bộ)"],"h1":"Khoảng một yard, lựa chọn lớn nhất ở đây.","h2":"Ở Alabama, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet giữa xe bạn và người đó.","p":"Đúng. Chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Alabama, ano ang pinakamaliit na espasyo na dapat mong iwan sa pagitan ng kotse mo at ng taong nagbibisikleta kapag nag-overtake ka?","o":["1 talampakan","18 pulgada","2 talampakan","3 talampakan"],"h1":"Mga isang yarda ito, ang pinakamalaking pagpipilian dito.","h2":"Sa Alabama, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng sasakyan mo at ng taong nagbibisikleta kapag nag-overtake ka.","p":"Tama. Bigyan ng hindi bababa sa 3 talampakan ang nagbibisikleta."},"ar":{"q":"في Alabama، ما أقل مسافة يجب أن تتركها بين سيارتك وشخص يركب درّاجة عندما تتجاوزه؟","o":["قدم واحدة","18 بوصة","قدمان","3 أقدام"],"h1":"المسافة نحو ياردة واحدة، وهي أكبر خيار هنا.","h2":"في Alabama يجب أن تترك 3 أقدام على الأقل بين مركبتك وشخص يركب درّاجة عندما تتجاوزه.","p":"صحيح. اترك لراكب الدرّاجة 3 أقدام على الأقل."},"ref":{"doc":"AL","page":24}},{"id":"al-047","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, bicycle riders under what age must wear a helmet on public roads?","o":["Under 12","Under 16","Under 18","Under 21"],"h1":"It covers younger teens, but not all teenagers.","h2":"In Alabama bicycle riders under 16 must wear a fastened helmet on public roads, bike paths, and in public parks.","p":"Right. Riders under 16 must wear a helmet."},"es":{"q":"En Alabama, ¿los ciclistas menores de qué edad deben usar casco en las vías públicas?","o":["Menores de 12","Menores de 16","Menores de 18","Menores de 21"],"h1":"Incluye a los adolescentes más jóvenes, pero no a todos los adolescentes.","h2":"En Alabama los ciclistas menores de 16 años deben usar un casco abrochado en las vías públicas, las ciclovías y los parques públicos.","p":"Correcto. Los menores de 16 deben usar casco."},"zh":{"q":"在 Alabama，多少岁以下的骑自行车的人在公共道路上必须戴头盔？","o":["12 岁以下","16 岁以下","18 岁以下","21 岁以下"],"h1":"包括年纪较小的青少年，但不是所有青少年。","h2":"在 Alabama，16 岁以下骑自行车的人在公共道路、自行车道和公共公园里必须戴好并扣紧头盔。","p":"对。16 岁以下的人必须戴头盔。"},"vi":{"q":"Ở Alabama, người đi xe đạp dưới bao nhiêu tuổi phải đội mũ bảo hiểm trên đường công cộng?","o":["Dưới 12","Dưới 16","Dưới 18","Dưới 21"],"h1":"Nó áp dụng cho thiếu niên nhỏ tuổi hơn, nhưng không phải tất cả thanh thiếu niên.","h2":"Ở Alabama, người đi xe đạp dưới 16 tuổi phải đội mũ bảo hiểm có cài quai trên đường công cộng, đường dành cho xe đạp và trong công viên công cộng.","p":"Đúng. Người đi xe đạp dưới 16 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa Alabama, ang mga nagbibisikleta na wala pang anong edad ang dapat magsuot ng helmet sa mga pampublikong kalsada?","o":["Wala pang 12","Wala pang 16","Wala pang 18","Wala pang 21"],"h1":"Saklaw nito ang mas batang mga teenager, pero hindi lahat ng teenager.","h2":"Sa Alabama, ang mga nagbibisikleta na wala pang 16 ay dapat magsuot ng nakakabit na helmet sa mga pampublikong kalsada, bike path, at sa mga pampublikong parke.","p":"Tama. Dapat magsuot ng helmet ang mga nagbibisikleta na wala pang 16."},"ar":{"q":"في Alabama، راكبو الدرّاجات الذين أعمارهم أقل من أي سن يجب أن يلبسوا خوذة على الطرق العامة؟","o":["أقل من 12","أقل من 16","أقل من 18","أقل من 21"],"h1":"يشمل المراهقين الأصغر سنًا، لكن ليس كل المراهقين.","h2":"في Alabama يجب على راكبي الدرّاجات الذين أعمارهم أقل من 16 سنة أن يلبسوا خوذة مربوطة على الطرق العامة ومسارات الدرّاجات وفي الحدائق العامة.","p":"صحيح. من عمره أقل من 16 سنة يجب أن يلبس خوذة."},"ref":{"doc":"AL","page":24}},{"id":"al-048","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, until what age must a child ride in a booster seat?","o":["3 years old","4 years old","6 years old","10 years old"],"h1":"It is the age when many children start first grade.","h2":"In Alabama a child must use a booster seat until age 6, and then a seat belt through age 15.","p":"Right. Booster seats are required until age 6."},"es":{"q":"En Alabama, ¿hasta qué edad debe un niño viajar en un asiento elevado (booster)?","o":["3 años","4 años","6 años","10 años"],"h1":"Es la edad en que muchos niños empiezan el primer grado.","h2":"En Alabama un niño debe usar un asiento elevado hasta los 6 años, y después el cinturón de seguridad hasta los 15 años.","p":"Correcto. El asiento elevado es obligatorio hasta los 6 años."},"zh":{"q":"在 Alabama，孩子必须坐加高座椅（booster seat）到几岁？","o":["3 岁","4 岁","6 岁","10 岁"],"h1":"是很多孩子开始上一年级的年龄。","h2":"在 Alabama，孩子必须使用加高座椅到 6 岁，之后到 15 岁都要系安全带。","p":"对。加高座椅要用到 6 岁。"},"vi":{"q":"Ở Alabama, trẻ em phải ngồi ghế nâng (booster seat) cho đến bao nhiêu tuổi?","o":["3 tuổi","4 tuổi","6 tuổi","10 tuổi"],"h1":"Đó là tuổi nhiều trẻ bắt đầu vào lớp một.","h2":"Ở Alabama, trẻ em phải dùng ghế nâng cho đến 6 tuổi, sau đó phải thắt dây an toàn cho đến hết 15 tuổi.","p":"Đúng. Phải dùng ghế nâng cho đến 6 tuổi."},"tl":{"q":"Sa Alabama, hanggang anong edad dapat sumakay ang bata sa booster seat?","o":["3 taong gulang","4 na taong gulang","6 na taong gulang","10 taong gulang"],"h1":"Ito ang edad kung kailan maraming bata ang nagsisimula sa unang baitang.","h2":"Sa Alabama, dapat gumamit ang bata ng booster seat hanggang edad 6, at pagkatapos ay seat belt hanggang edad 15.","p":"Tama. Kailangan ang booster seat hanggang edad 6."},"ar":{"q":"في Alabama، حتى أي سن يجب أن يجلس الطفل في مقعد رافع (booster seat)؟","o":["3 سنوات","4 سنوات","6 سنوات","10 سنوات"],"h1":"هي السن التي يبدأ فيها كثير من الأطفال الصف الأول.","h2":"في Alabama يجب أن يستخدم الطفل مقعدًا رافعًا حتى سن 6، ثم حزام الأمان حتى سن 15.","p":"صحيح. المقعد الرافع مطلوب حتى سن 6."},"ref":{"doc":"AL","page":30}},{"id":"al-049","scope":"AL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Alabama, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is closer than the distance for a railroad crossing.","h2":"In Alabama you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Alabama, ¿a qué distancia de un hidrante puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es más cerca que la distancia para un cruce de ferrocarril.","h2":"En Alabama usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Alabama，停车时离消防栓最近可以多近？","o":["不少于 10 英尺","不少于 15 英尺","不少于 30 英尺","不少于 50 英尺"],"h1":"比离铁路道口的距离近。","h2":"在 Alabama，你不可以在消防栓 15 英尺以内停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Alabama, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Gần hơn khoảng cách đối với chỗ giao với đường sắt.","h2":"Ở Alabama, bạn không được đỗ xe trong phạm vi 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Alabama, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi mas malapit sa 10 talampakan","Hindi mas malapit sa 15 talampakan","Hindi mas malapit sa 30 talampakan","Hindi mas malapit sa 50 talampakan"],"h1":"Mas malapit ito kaysa sa layo para sa tawiran ng tren.","h2":"Sa Alabama, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan sa fire hydrant."},"ar":{"q":"في Alabama، إلى أي مدى يمكنك أن تقترب من حنفية إطفاء الحريق عندما تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أقرب من المسافة المطلوبة عند معبر السكة الحديدية.","h2":"في Alabama لا يجوز لك أن تركن سيارتك على مسافة أقل من 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ref":{"doc":"AL","page":29}},{"id":"al-050","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, your headlights must be on whenever you cannot see clearly for at least how far ahead?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is the longest distance on the list.","h2":"In Alabama headlights must be on from a half hour after sunset to a half hour before sunrise, and any time you cannot see clearly for at least 500 feet.","p":"Right. Turn on headlights when you cannot see 500 feet ahead."},"es":{"q":"En Alabama, sus luces delanteras deben estar encendidas siempre que no pueda ver claramente por lo menos ¿a qué distancia?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es la distancia más larga de la lista.","h2":"En Alabama las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer, y siempre que no pueda ver claramente por lo menos a 500 pies.","p":"Correcto. Encienda las luces cuando no pueda ver a 500 pies."},"zh":{"q":"在 Alabama，当你看不清前方至少多远时，必须打开大灯？","o":["100 英尺","200 英尺","300 英尺","500 英尺"],"h1":"是选项中最远的距离。","h2":"在 Alabama，从日落后半小时到日出前半小时必须开大灯，而且任何时候看不清前方至少 500 英尺时也必须开大灯。","p":"对。看不清前方 500 英尺时要开大灯。"},"vi":{"q":"Ở Alabama, bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ phía trước ít nhất bao xa?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"Đó là khoảng cách dài nhất trong danh sách.","h2":"Ở Alabama, phải bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc, và bất cứ khi nào bạn không thể nhìn rõ ít nhất 500 feet.","p":"Đúng. Bật đèn pha khi bạn không thể nhìn rõ 500 feet phía trước."},"tl":{"q":"Sa Alabama, dapat nakabukas ang headlights mo tuwing hindi mo makita nang malinaw ang daan sa unahan nang hindi bababa sa gaano kalayo?","o":["100 talampakan","200 talampakan","300 talampakan","500 talampakan"],"h1":"Ito ang pinakamahabang layo sa listahan.","h2":"Sa Alabama, dapat nakabukas ang headlights mula kalahating oras pagkatapos lumubog ang araw hanggang kalahating oras bago sumikat ang araw, at anumang oras na hindi mo makita nang malinaw ang hindi bababa sa 500 talampakan.","p":"Tama. Buksan ang headlights kapag hindi mo makita ang 500 talampakan sa unahan."},"ar":{"q":"في Alabama، يجب أن تكون مصابيحك الأمامية مضاءة كلما لم تستطع أن ترى بوضوح أمامك لمسافة لا تقل عن كم؟","o":["100 قدم","200 قدم","300 قدم","500 قدم"],"h1":"هي أطول مسافة في القائمة.","h2":"في Alabama يجب أن تكون المصابيح الأمامية مضاءة من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها، وفي أي وقت لا تستطيع فيه أن ترى بوضوح لمسافة 500 قدم على الأقل.","p":"صحيح. أضئ المصابيح الأمامية عندما لا تستطيع أن ترى 500 قدم أمامك."},"ref":{"doc":"AL","page":69}},{"id":"al-051","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, what can you dial on a cell phone to reach the State Troopers about a crash or a drunk driver?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"It starts with a star, then two letters that stand for the troopers' patrol.","h2":"In Alabama you can dial *HP, which is *47, on a cell phone to reach the State Troopers for highway emergencies, crashes, and drunk drivers.","p":"Right. Dial *HP (*47) to reach the State Troopers."},"es":{"q":"En Alabama, ¿qué número puede marcar en un celular para comunicarse con la Policía Estatal (State Troopers) por un choque o un conductor ebrio?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"Empieza con una estrella y luego dos letras que representan la patrulla de los troopers.","h2":"En Alabama usted puede marcar *HP, que es *47, en un celular para comunicarse con la Policía Estatal por emergencias en la carretera, choques y conductores ebrios.","p":"Correcto. Marque *HP (*47) para comunicarse con la Policía Estatal."},"zh":{"q":"在 Alabama，发生车祸或看到醉酒司机时，你可以用手机拨什么号码联系州警（State Troopers）？","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"以星号开头，后面是两个代表州警巡逻的字母。","h2":"在 Alabama，你可以用手机拨 *HP，也就是 *47，联系州警（State Troopers），报告高速公路紧急情况、车祸和醉酒司机。","p":"对。拨 *HP (*47) 联系州警。"},"vi":{"q":"Ở Alabama, bạn có thể bấm số nào trên điện thoại di động để gọi Cảnh sát Tiểu bang (State Troopers) về một vụ tai nạn hoặc một người lái xe say rượu?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"Nó bắt đầu bằng dấu sao, rồi hai chữ cái chỉ đội tuần tra của cảnh sát tiểu bang.","h2":"Ở Alabama, bạn có thể bấm *HP, tức là *47, trên điện thoại di động để gọi Cảnh sát Tiểu bang (State Troopers) khi có trường hợp khẩn cấp trên xa lộ, tai nạn và người lái xe say rượu.","p":"Đúng. Bấm *HP (*47) để gọi Cảnh sát Tiểu bang."},"tl":{"q":"Sa Alabama, ano ang puwede mong i-dial sa cell phone para makontak ang State Troopers tungkol sa banggaan o lasing na drayber?","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"Nagsisimula ito sa star, tapos dalawang letra na kumakatawan sa patrol ng mga trooper.","h2":"Sa Alabama, puwede mong i-dial ang *HP, na *47, sa cell phone para makontak ang State Troopers para sa mga emergency sa highway, banggaan, at lasing na drayber.","p":"Tama. I-dial ang *HP (*47) para makontak ang State Troopers."},"ar":{"q":"في Alabama، ما الرقم الذي يمكنك أن تطلبه من الهاتف المحمول للاتصال بشرطة الولاية (State Troopers) بشأن حادث أو سائق مخمور؟","o":["*HP (*47)","*DL (*35)","#77","*411"],"h1":"يبدأ بنجمة، ثم حرفين يرمزان إلى دورية شرطة الولاية.","h2":"في Alabama يمكنك أن تطلب *HP، أي *47، من الهاتف المحمول للاتصال بشرطة الولاية (State Troopers) في حالات الطوارئ على الطرق السريعة والحوادث والسائقين المخمورين.","p":"صحيح. اطلب *HP (*47) للاتصال بشرطة الولاية."},"ref":{"doc":"AL","page":76}},{"id":"al-052","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, you just moved here with a valid license from your old state. How long may you drive on it?","o":["10 days","30 days","6 months","Until it expires"],"h1":"It is about one month.","h2":"A new Alabama resident with a valid license from the previous state may drive on it for 30 days after becoming a resident.","p":"Right. New residents may use the old license for 30 days."},"es":{"q":"En Alabama, usted acaba de mudarse aquí con una licencia válida de su estado anterior. ¿Por cuánto tiempo puede manejar con ella?","o":["10 días","30 días","6 meses","Hasta que venza"],"h1":"Es más o menos un mes.","h2":"Un nuevo residente de Alabama con una licencia válida del estado anterior puede manejar con ella durante 30 días después de hacerse residente.","p":"Correcto. Los nuevos residentes pueden usar la licencia anterior por 30 días."},"ref":{"doc":"AL","page":5}},{"id":"al-053","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, you can skip the driver exam when you trade in an out-of-state license if it has not been expired for more than how long?","o":["30 days","6 months","One year","Five years"],"h1":"It is twelve months.","h2":"In Alabama a person with an out-of-state license that has not been expired for more than one year does not have to pass the driver exam.","p":"Right. Up to one year expired, no exam is needed."},"es":{"q":"En Alabama, al cambiar una licencia de otro estado, usted no tiene que tomar el examen de manejo si esa licencia no lleva vencida más de ¿cuánto tiempo?","o":["30 días","6 meses","Un año","Cinco años"],"h1":"Son doce meses.","h2":"En Alabama una persona con una licencia de otro estado que no lleva vencida más de un año no tiene que aprobar el examen de manejo.","p":"Correcto. Con hasta un año de vencida, no necesita examen."},"ref":{"doc":"AL","page":5}},{"id":"al-054","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, what is the minimum age to drive without a supervising driver beside you?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is one year after the youngest learner age.","h2":"The minimum driving age in Alabama is 16; a 15-year-old may only drive with a learner license and a qualified adult beside them.","p":"Right. The minimum driving age is 16."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para manejar sin un conductor supervisor a su lado?","o":["16 años","15 años","17 años","18 años"],"h1":"Es un año después de la edad mínima del aprendiz.","h2":"La edad mínima para manejar en Alabama es 16 años; un joven de 15 años solo puede manejar con licencia de aprendiz y un adulto calificado a su lado.","p":"Correcto. La edad mínima para manejar es 16 años."},"ref":{"doc":"AL","page":9}},{"id":"al-055","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, applicants under what age must bring a current Student Enrollment/Exclusion Form (DL-1-93)?","o":["Under 16","Under 17","Under 21","Under 19"],"h1":"It covers most high school students, and a bit older.","h2":"In Alabama every license applicant under age 19 must present a current Student Enrollment/Exclusion Form, DL-1-93, signed by the school.","p":"Right. Applicants under 19 need the school form."},"es":{"q":"En Alabama, ¿los solicitantes menores de qué edad deben traer un formulario vigente de inscripción o exclusión escolar (DL-1-93)?","o":["Menores de 16","Menores de 17","Menores de 21","Menores de 19"],"h1":"Incluye a la mayoría de los estudiantes de secundaria, y un poco más.","h2":"En Alabama todo solicitante de licencia menor de 19 años debe presentar un formulario vigente de inscripción o exclusión escolar, DL-1-93, firmado por la escuela.","p":"Correcto. Los menores de 19 necesitan el formulario escolar."},"ref":{"doc":"AL","page":8}},{"id":"al-056","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, which restriction letter is printed on a learner license?","o":["B","Y","M","D"],"h1":"It is near the end of the alphabet.","h2":"An Alabama learner license is a Class D license with a \"Y\" restriction, which means you may drive only with a qualified licensed driver beside you.","p":"Right. The learner license carries a Y restriction."},"es":{"q":"En Alabama, ¿qué letra de restricción aparece en una licencia de aprendiz?","o":["B","Y","M","D"],"h1":"Está cerca del final del alfabeto.","h2":"Una licencia de aprendiz de Alabama es una licencia Clase D con la restricción \"Y\", que significa que solo puede manejar con un conductor con licencia calificado a su lado.","p":"Correcto. La licencia de aprendiz lleva la restricción Y."},"ref":{"doc":"AL","page":9}},{"id":"al-057","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a learner has just turned 16. Who may now sit beside them while they drive?","o":["Only a parent","Only a driving instructor","Any licensed driver","Any passenger age 14 or older"],"h1":"The age 21 rule no longer applies after the 16th birthday.","h2":"In Alabama, once a learner license holder turns 16, any licensed driver may sit in the seat beside them while they drive.","p":"Right. After 16, any licensed driver may supervise."},"es":{"q":"En Alabama, un aprendiz acaba de cumplir 16 años. ¿Quién puede ir sentado a su lado ahora mientras maneja?","o":["Solo un padre","Solo un instructor de manejo","Cualquier conductor con licencia","Cualquier pasajero de 14 años o más"],"h1":"La regla de los 21 años ya no se aplica después de cumplir 16.","h2":"En Alabama, cuando el titular de una licencia de aprendiz cumple 16 años, cualquier conductor con licencia puede ir en el asiento de al lado mientras maneja.","p":"Correcto. Después de los 16, cualquier conductor con licencia puede supervisar."},"ref":{"doc":"AL","page":9}},{"id":"al-058","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the youngest age to get a restricted license for a small motor-driven cycle?","o":["12 years old","13 years old","16 years old","14 years old"],"h1":"It is one year younger than the learner license age.","h2":"In Alabama a person 14 or 15 years old may get a restricted Class M license to ride a motor-driven cycle of no more than 150cc.","p":"Right. The motor-driven cycle license starts at 14."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para obtener una licencia restringida para un ciclomotor pequeño (motor-driven cycle)?","o":["12 años","13 años","16 años","14 años"],"h1":"Es un año menos que la edad de la licencia de aprendiz.","h2":"En Alabama una persona de 14 o 15 años puede obtener una licencia Clase M restringida para manejar un ciclomotor de no más de 150cc.","p":"Correcto. La licencia de ciclomotor empieza a los 14 años."},"ref":{"doc":"AL","page":10}},{"id":"al-059","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, your license is suspended and you do not turn it in on time. What extra fee is added when you reinstate it?","o":["$50","$5","$25","$500"],"h1":"It is half of the basic reinstatement fee.","h2":"In Alabama, if you fail to surrender a suspended, revoked, or canceled license in the time allowed, an extra $50 fee is added to the reinstatement fee.","p":"Right. Not turning in the license costs an extra $50."},"es":{"q":"En Alabama, su licencia está suspendida y usted no la entrega a tiempo. ¿Qué cargo adicional se agrega al restablecerla?","o":["$50","$5","$25","$500"],"h1":"Es la mitad del cargo básico de restablecimiento.","h2":"En Alabama, si no entrega una licencia suspendida, revocada o cancelada en el plazo indicado, se agrega un cargo adicional de $50 al cargo de restablecimiento.","p":"Correcto. No entregar la licencia cuesta $50 más."},"ref":{"doc":"AL","page":17}},{"id":"al-060","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, after a license revocation period ends, what must the driver do to get a new license?","o":["Just pay a small fee","Pass the complete driver exams","Wait one more year","Only take a vision test"],"h1":"A revoked license is not simply turned back on.","h2":"In Alabama, when a revocation period is over, the driver must apply for a new license and take and pass the complete examinations again.","p":"Right. After revocation you must pass all the exams again."},"es":{"q":"En Alabama, cuando termina el período de revocación de una licencia, ¿qué debe hacer el conductor para obtener una nueva?","o":["Solo pagar un cargo pequeño","Aprobar todos los exámenes de manejo","Esperar un año más","Solo tomar un examen de la vista"],"h1":"Una licencia revocada no se vuelve a activar así nada más.","h2":"En Alabama, cuando termina un período de revocación, el conductor debe solicitar una licencia nueva y tomar y aprobar otra vez todos los exámenes.","p":"Correcto. Después de una revocación debe aprobar todos los exámenes otra vez."},"ref":{"doc":"AL","page":17}},{"id":"al-061","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how many reckless driving convictions within 12 months require the license to be revoked?","o":["One","Two","Three","Five"],"h1":"It is more than two.","h2":"In Alabama the license must be revoked when a driver is convicted of reckless driving three times within 12 months.","p":"Right. Three reckless driving convictions in 12 months means revocation."},"es":{"q":"En Alabama, ¿cuántas condenas por manejo imprudente en 12 meses obligan a revocar la licencia?","o":["Una","Dos","Tres","Cinco"],"h1":"Son más de dos.","h2":"En Alabama la licencia debe revocarse cuando un conductor es condenado por manejo imprudente tres veces en 12 meses.","p":"Correcto. Tres condenas por manejo imprudente en 12 meses significan revocación."},"ref":{"doc":"AL","page":17}},{"id":"al-062","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, a teen on a graduated (GDL) license can have it suspended after how many moving traffic violations?","o":["Five","Four","Three","Two"],"h1":"It takes very few tickets for a new driver.","h2":"In Alabama a driver on a graduated driver license may be suspended after 2 or more moving traffic violations.","p":"Right. Two moving violations can suspend a GDL license."},"es":{"q":"En Alabama, a un adolescente con licencia graduada (GDL) se le puede suspender después de ¿cuántas infracciones de tránsito en movimiento?","o":["Cinco","Cuatro","Tres","Dos"],"h1":"Para un conductor nuevo bastan muy pocas multas.","h2":"En Alabama a un conductor con licencia graduada se le puede suspender después de 2 o más infracciones de tránsito en movimiento.","p":"Correcto. Dos infracciones en movimiento pueden suspender una licencia GDL."},"ref":{"doc":"AL","page":18}},{"id":"al-063","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, how many points does a drinking-and-driving conviction add when it does not bring a mandatory revocation?","o":["6 points","2 points","3 points","4 points"],"h1":"It is the highest value on Alabama's point list.","h2":"In Alabama a conviction for drinking alcohol and driving that does not require mandatory revocation adds 6 points to the driving record.","p":"Right. It adds 6 points."},"es":{"q":"En Alabama, ¿cuántos puntos agrega una condena por tomar alcohol y manejar cuando no trae una revocación obligatoria?","o":["6 puntos","2 puntos","3 puntos","4 puntos"],"h1":"Es el valor más alto de la lista de puntos de Alabama.","h2":"En Alabama una condena por tomar alcohol y manejar que no exige revocación obligatoria agrega 6 puntos al historial de manejo.","p":"Correcto. Agrega 6 puntos."},"ref":{"doc":"AL","page":18}},{"id":"al-064","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, how many points are added for failing to yield the right of way?","o":["2 points","5 points","1 point","8 points"],"h1":"It is the same as passing a stopped school bus.","h2":"In Alabama a conviction for failure to yield the right of way adds 5 points to your driving record.","p":"Right. Failure to yield is 5 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por no ceder el paso?","o":["2 puntos","5 puntos","1 punto","8 puntos"],"h1":"Es lo mismo que por pasar a un autobús escolar detenido.","h2":"En Alabama una condena por no ceder el paso agrega 5 puntos a su historial de manejo.","p":"Correcto. No ceder el paso son 5 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-065","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how many points are added for following another vehicle too closely?","o":["1 point","6 points","3 points","5 points"],"h1":"It is more than a speeding ticket for 1 to 25 mph over.","h2":"In Alabama a conviction for following too closely adds 3 points to your driving record.","p":"Right. Following too closely is 3 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por seguir demasiado cerca a otro vehículo?","o":["1 punto","6 puntos","3 puntos","5 puntos"],"h1":"Es más que una multa por exceso de velocidad de 1 a 25 mph.","h2":"En Alabama una condena por seguir demasiado cerca agrega 3 puntos a su historial de manejo.","p":"Correcto. Seguir demasiado cerca son 3 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-066","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the fine for a first offense of texting while driving?","o":["$100","$250","$500","$25"],"h1":"It is the smallest amount on the list; it goes up with each offense.","h2":"In Alabama a first texting-while-driving offense brings a $25 fine, then $50 for a second and $75 for a third or later offense.","p":"Right. The first texting fine is $25."},"es":{"q":"En Alabama, ¿cuál es la multa por una primera infracción de enviar mensajes de texto mientras maneja?","o":["$100","$250","$500","$25"],"h1":"Es la cantidad más pequeña de la lista; sube con cada infracción.","h2":"En Alabama una primera infracción por enviar mensajes de texto mientras maneja trae una multa de $25, luego $50 por la segunda y $75 por la tercera o siguientes.","p":"Correcto. La primera multa por textear es de $25."},"ref":{"doc":"AL","page":32}},{"id":"al-067","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, when Form SR-31 must be filed after a crash, how many days do you have to send it?","o":["30 days","5 days","10 days","1 year"],"h1":"It is about one month.","h2":"In Alabama, when the at-fault driver was not insured and the crash caused injury, death, or $500 or more in damage, the written SR-31 form must be sent within 30 days.","p":"Right. The SR-31 form is due within 30 days."},"es":{"q":"En Alabama, cuando hay que enviar el formulario SR-31 después de un choque, ¿cuántos días tiene para enviarlo?","o":["30 días","5 días","10 días","1 año"],"h1":"Es más o menos un mes.","h2":"En Alabama, cuando el conductor culpable no tenía seguro y el choque causó lesiones, una muerte o $500 o más en daños, el formulario escrito SR-31 debe enviarse dentro de 30 días.","p":"Correcto. El formulario SR-31 se envía dentro de 30 días."},"ref":{"doc":"AL","page":38}},{"id":"al-068","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, besides a fine, what license penalty can a liability insurance violation bring?","o":["A 30-day suspension","A six-month suspension","A five-year revocation","No license penalty"],"h1":"It is half a year.","h2":"In Alabama a conviction for not having the required liability insurance can bring a fine and/or a six-month driver license suspension.","p":"Right. It can mean a six-month suspension."},"es":{"q":"En Alabama, además de una multa, ¿qué castigo para la licencia puede traer una infracción del seguro de responsabilidad?","o":["Una suspensión de 30 días","Una suspensión de seis meses","Una revocación de cinco años","Ningún castigo para la licencia"],"h1":"Es medio año.","h2":"En Alabama una condena por no tener el seguro de responsabilidad obligatorio puede traer una multa y/o una suspensión de la licencia de seis meses.","p":"Correcto. Puede significar una suspensión de seis meses."},"ref":{"doc":"AL","page":68}},{"id":"al-069","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a school bus or daycare driver is legally under the influence at what blood alcohol level?","o":["0.08 percent or more","0.10 percent or more","0.02 percent or more","0.05 percent or more"],"h1":"It is the same low limit used for drivers under 21.","h2":"In Alabama a school bus or daycare driver is breaking the DUI law with a blood alcohol level of 0.02 percent or more.","p":"Right. For school bus and daycare drivers the limit is 0.02."},"es":{"q":"En Alabama, un conductor de autobús escolar o de guardería está legalmente bajo los efectos del alcohol con ¿qué nivel de alcohol en la sangre?","o":["0.08 por ciento o más","0.10 por ciento o más","0.02 por ciento o más","0.05 por ciento o más"],"h1":"Es el mismo límite bajo que se usa para los conductores menores de 21 años.","h2":"En Alabama un conductor de autobús escolar o de guardería viola la ley de DUI con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para conductores de autobús escolar y guardería el límite es 0.02."},"ref":{"doc":"AL","page":33}},{"id":"al-070","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, what is the fine range for a first DUI conviction?","o":["$50 to $100","$100 to $500","$5,000 to $10,000","$600 to $2,100"],"h1":"It starts at several hundred dollars and can go above two thousand.","h2":"In Alabama a first DUI conviction carries a fine of $600 to $2,100, up to one year in jail, or both.","p":"Right. A first DUI fine is $600 to $2,100."},"es":{"q":"En Alabama, ¿cuál es el rango de la multa por una primera condena por DUI?","o":["$50 a $100","$100 a $500","$5,000 a $10,000","$600 a $2,100"],"h1":"Empieza en varios cientos de dólares y puede pasar de dos mil.","h2":"En Alabama una primera condena por DUI trae una multa de $600 a $2,100, hasta un año de cárcel, o ambas.","p":"Correcto. La multa por un primer DUI es de $600 a $2,100."},"ref":{"doc":"AL","page":33}},{"id":"al-071","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, after a second DUI conviction within 10 years, how long is the driver license revoked?","o":["One year","90 days","30 days","Ten years"],"h1":"It is longer than the suspension for a first DUI.","h2":"In Alabama a second DUI conviction within 10 years brings a one-year license revocation, plus a fine and at least 48 hours in jail or 20 days of community service.","p":"Right. A second DUI means a one-year revocation."},"es":{"q":"En Alabama, después de una segunda condena por DUI en 10 años, ¿por cuánto tiempo se revoca la licencia?","o":["Un año","90 días","30 días","Diez años"],"h1":"Es más largo que la suspensión por un primer DUI.","h2":"En Alabama una segunda condena por DUI en 10 años trae una revocación de la licencia por un año, además de una multa y por lo menos 48 horas de cárcel o 20 días de servicio comunitario.","p":"Correcto. Un segundo DUI significa una revocación de un año."},"ref":{"doc":"AL","page":33}},{"id":"al-072","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, a driver arrested for DUI refuses the breath test an officer asks for. What happens?","o":["Nothing, the test is optional","The driver license is suspended","The driver gets a warning only","The driver must retake the road test"],"h1":"Driving on Alabama roads means you have already agreed to be tested.","h2":"Under Alabama's implied consent law, a driver arrested for DUI who refuses the chemical breath test will have the driver license suspended.","p":"Right. Refusing the test leads to a license suspension."},"es":{"q":"En Alabama, un conductor arrestado por DUI se niega a la prueba de aliento que le pide un oficial. ¿Qué pasa?","o":["Nada, la prueba es opcional","Se suspende la licencia de manejar","El conductor solo recibe una advertencia","El conductor debe repetir el examen práctico"],"h1":"Manejar en las calles de Alabama significa que usted ya aceptó hacerse la prueba.","h2":"Según la ley de consentimiento implícito de Alabama, a un conductor arrestado por DUI que se niega a la prueba química de aliento se le suspende la licencia de manejar.","p":"Correcto. Negarse a la prueba lleva a una suspensión de la licencia."},"ref":{"doc":"AL","page":34}},{"id":"al-073","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, you hit a parked car and the owner is not there. Which is one thing the law allows you to do?","o":["Drive away if the damage is small","Wait one hour, then leave","Leave a note with your name and address","Report it only if asked"],"h1":"The owner must be able to find you.","h2":"In Alabama, if you hit an unattended vehicle, you must notify the police, try to find the owner, or leave a written note in plain view with your name and address.","p":"Right. You may leave a note with your name and address in plain view."},"es":{"q":"En Alabama, usted choca contra un carro estacionado y el dueño no está. ¿Cuál es una cosa que la ley le permite hacer?","o":["Irse si el daño es pequeño","Esperar una hora y luego irse","Dejar una nota con su nombre y dirección","Reportarlo solo si se lo piden"],"h1":"El dueño debe poder encontrarlo a usted.","h2":"En Alabama, si choca contra un vehículo sin nadie adentro, debe avisar a la policía, tratar de encontrar al dueño o dejar una nota escrita a la vista con su nombre y dirección.","p":"Correcto. Puede dejar una nota a la vista con su nombre y dirección."},"ref":{"doc":"AL","page":38}},{"id":"al-074","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, until when must a baby ride in a rear-facing car seat?","o":["Until 3 months old or 10 pounds","Until the baby can sit up alone","Until 6 months old or 15 pounds","Until at least 1 year or 20 pounds"],"h1":"Think of a baby's first birthday.","h2":"Alabama law requires an infant seat or convertible seat facing the rear until the baby is at least 1 year old or 20 pounds.","p":"Right. Rear-facing until at least 1 year or 20 pounds."},"es":{"q":"En Alabama, ¿hasta cuándo debe un bebé viajar en un asiento de seguridad mirando hacia atrás?","o":["Hasta los 3 meses o 10 libras","Hasta que el bebé se siente solo","Hasta los 6 meses o 15 libras","Hasta por lo menos 1 año o 20 libras"],"h1":"Piense en el primer cumpleaños del bebé.","h2":"La ley de Alabama exige un asiento para bebé o convertible mirando hacia atrás hasta que el bebé tenga por lo menos 1 año o 20 libras.","p":"Correcto. Mirando hacia atrás hasta por lo menos 1 año o 20 libras."},"ref":{"doc":"AL","page":30}},{"id":"al-075","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, a car is coming toward you at night. Within what distance must you dim your high beams?","o":["500 feet","100 feet","200 feet","2,000 feet"],"h1":"It is longer than the distance for a car you are following.","h2":"In Alabama you must dim your headlights when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Alabama, un carro viene de frente hacia usted de noche. ¿A qué distancia debe bajar las luces altas?","o":["500 pies","100 pies","200 pies","2,000 pies"],"h1":"Es más larga que la distancia para un carro que va delante de usted.","h2":"En Alabama usted debe bajar las luces cuando está a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies del tráfico que viene de frente."},"ref":{"doc":"AL","page":69}},{"id":"al-076","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, your car breaks down at night. Where should you place flares or reflectors?","o":["Right next to your car","100 to 500 feet behind your car","In front of your car only","In the middle of the opposite lane"],"h1":"Other drivers need warning well before they reach you.","h2":"The Alabama manual says to put flares or reflectors 100 to 500 feet behind your vehicle, on the right edge of the highway, to warn traffic.","p":"Right. Place them 100 to 500 feet behind your car."},"es":{"q":"En Alabama, su carro se descompone de noche. ¿Dónde debe poner bengalas o reflectores?","o":["Justo al lado de su carro","De 100 a 500 pies detrás de su carro","Solo delante de su carro","En medio del carril contrario"],"h1":"Los otros conductores necesitan aviso mucho antes de llegar a usted.","h2":"El manual de Alabama indica poner bengalas o reflectores de 100 a 500 pies detrás de su vehículo, en el borde derecho de la carretera, para avisar al tráfico.","p":"Correcto. Póngalos de 100 a 500 pies detrás de su carro."},"ref":{"doc":"AL","page":70}},{"id":"al-077","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a tire is illegal when its tread is less than how deep?","o":["1/2 inch","1/4 inch","1/16 inch","1/64 inch"],"h1":"It is about the depth from the edge of a penny to the top of Lincoln's head.","h2":"In Alabama a tire is illegal if its tread is less than 1/16 inch deep.","p":"Right. Tread under 1/16 inch is illegal."},"es":{"q":"En Alabama, una llanta es ilegal cuando la profundidad de su dibujo es menor de ¿cuánto?","o":["1/2 pulgada","1/4 de pulgada","1/16 de pulgada","1/64 de pulgada"],"h1":"Es más o menos la distancia del borde de una moneda de un centavo a la parte de arriba de la cabeza de Lincoln.","h2":"En Alabama una llanta es ilegal si el dibujo tiene menos de 1/16 de pulgada de profundidad.","p":"Correcto. Un dibujo de menos de 1/16 de pulgada es ilegal."},"ref":{"doc":"AL","page":80}},{"id":"al-078","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, what does the law say about coasting downhill with the transmission in neutral?","o":["It is allowed to save fuel","It is allowed on hills only","It is required on steep hills","It is against the law"],"h1":"You need the engine to help control your speed.","h2":"Alabama law forbids coasting downhill with the transmission in neutral, and coasting adds 2 points to your record.","p":"Right. Coasting in neutral is against the law."},"es":{"q":"En Alabama, ¿qué dice la ley sobre bajar una cuesta en neutro (sin cambio), dejándose llevar?","o":["Se permite para ahorrar gasolina","Solo se permite en las cuestas","Es obligatorio en cuestas empinadas","Va contra la ley"],"h1":"Usted necesita el motor para ayudar a controlar la velocidad.","h2":"La ley de Alabama prohíbe bajar una cuesta con la transmisión en neutro, y hacerlo agrega 2 puntos a su historial.","p":"Correcto. Bajar en neutro va contra la ley."},"ref":{"doc":"AL","page":73}},{"id":"al-079","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, the side and rear windows of a sedan must let at least what percent of light through?","o":["32 percent","10 percent","20 percent","70 percent"],"h1":"It is a little less than one third.","h2":"In Alabama the side and rear windows of a passenger car may be tinted only if they still let at least 32 percent of light through.","p":"Right. Window tint must allow at least 32 percent light."},"es":{"q":"En Alabama, las ventanas laterales y trasera de un sedán deben dejar pasar por lo menos ¿qué porcentaje de luz?","o":["32 por ciento","10 por ciento","20 por ciento","70 por ciento"],"h1":"Es un poco menos de un tercio.","h2":"En Alabama las ventanas laterales y trasera de un carro de pasajeros pueden polarizarse solo si siguen dejando pasar por lo menos el 32 por ciento de la luz.","p":"Correcto. El polarizado debe dejar pasar por lo menos 32 por ciento de luz."},"ref":{"doc":"AL","page":68}},{"id":"al-080","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, a load sticks out 4 feet or more from the back of your vehicle in daytime. What must you attach to the end?","o":["A white cloth","A red flag, 12 inches square","A yellow WIDE LOAD sign","Nothing, if you drive slowly"],"h1":"It is red and at least one foot on each side.","h2":"In Alabama a load that extends 4 feet or more past the rear needs a red flag at least 12 inches square at its end in daytime, and a red light at night.","p":"Right. Attach a red flag at least 12 inches square."},"es":{"q":"En Alabama, una carga sobresale 4 pies o más de la parte de atrás de su vehículo durante el día. ¿Qué debe ponerle en el extremo?","o":["Un trapo blanco","Una bandera roja de 12 pulgadas por lado","Un letrero amarillo de CARGA ANCHA","Nada, si maneja despacio"],"h1":"Es roja y mide por lo menos un pie por cada lado.","h2":"En Alabama una carga que sobresale 4 pies o más por detrás necesita una bandera roja de por lo menos 12 pulgadas por lado en el extremo durante el día, y una luz roja de noche.","p":"Correcto. Ponga una bandera roja de por lo menos 12 pulgadas por lado."},"ref":{"doc":"AL","page":67}},{"id":"al-081","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, which vehicle must always stop before crossing any railroad crossing?","o":["A pickup truck","A motorcycle","A truck hauling explosives","A car pulling a small trailer"],"h1":"Think of vehicles that carry many passengers or dangerous cargo.","h2":"In Alabama school buses, church buses, other passenger buses, and trucks carrying flammable, explosive, or hazardous materials must stop before every railroad crossing.","p":"Right. Trucks carrying explosives or other hazardous cargo must stop at every railroad crossing."},"es":{"q":"En Alabama, ¿qué vehículo siempre debe parar antes de cruzar cualquier cruce de tren?","o":["Una camioneta pickup","Una motocicleta","Un camión que lleva explosivos","Un carro que jala un remolque pequeño"],"h1":"Piense en vehículos que llevan muchos pasajeros o carga peligrosa.","h2":"En Alabama los autobuses escolares, los autobuses de iglesia, otros autobuses de pasajeros y los camiones que llevan materiales inflamables, explosivos o peligrosos deben parar antes de cada cruce de tren.","p":"Correcto. Los camiones con explosivos u otra carga peligrosa deben parar en cada cruce de tren."},"ref":{"doc":"AL","page":39}},{"id":"al-082","scope":"AL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alabama, besides a school bus, which stopped bus with its stop arm out and red lights flashing must you stop for?","o":["A city transit bus","A tour bus","An airport shuttle","A church bus"],"h1":"It carries people to religious services.","h2":"In Alabama you must stop for a school bus or a church bus that is stopped with its stop signal arm out and red lights flashing.","p":"Right. Church buses get the same stop as school buses."},"es":{"q":"En Alabama, además de un autobús escolar, ¿por qué otro autobús detenido con el brazo de alto extendido y luces rojas intermitentes debe parar?","o":["Un autobús de transporte urbano","Un autobús de turismo","Un transporte del aeropuerto","Un autobús de iglesia"],"h1":"Lleva personas a servicios religiosos.","h2":"En Alabama usted debe parar por un autobús escolar o un autobús de iglesia que esté detenido con el brazo de alto extendido y las luces rojas intermitentes.","p":"Correcto. Por los autobuses de iglesia se para igual que por los escolares."},"ref":{"doc":"AL","page":61}},{"id":"al-083","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, when you stop for a school bus with red lights flashing, how far from the bus must you stop?","o":["At least 20 feet","At least 5 feet","At least 10 feet","At least 100 feet"],"h1":"It is about the length of one and a half cars.","h2":"In Alabama you must stop at least 20 feet from a school bus that is loading or unloading children.","p":"Right. Stop at least 20 feet away from the bus."},"es":{"q":"En Alabama, cuando usted para por un autobús escolar con luces rojas intermitentes, ¿a qué distancia del autobús debe parar?","o":["Por lo menos a 20 pies","Por lo menos a 5 pies","Por lo menos a 10 pies","Por lo menos a 100 pies"],"h1":"Es más o menos el largo de un carro y medio.","h2":"En Alabama usted debe parar por lo menos a 20 pies de un autobús escolar que está subiendo o bajando niños.","p":"Correcto. Pare por lo menos a 20 pies del autobús."},"ref":{"doc":"AL","page":62}},{"id":"al-084","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, a person is crossing holding out a white cane tipped with red. What must you do?","o":["Honk so they know you are there","Stop and give them the right of way","Drive around them slowly","Wait only if there is a crosswalk"],"h1":"The law protects a person who is blind at any intersection.","h2":"Alabama law requires you to stop and give the right of way at any intersection to a blind person carrying a white cane tipped with red or using a guide dog.","p":"Right. Stop and let the person cross."},"es":{"q":"En Alabama, una persona cruza con un bastón blanco con punta roja extendido. ¿Qué debe hacer usted?","o":["Tocar el claxon para que sepa que usted está ahí","Parar y darle el paso","Pasar despacio a su alrededor","Esperar solo si hay un cruce peatonal"],"h1":"La ley protege a una persona ciega en cualquier intersección.","h2":"La ley de Alabama exige que usted pare y dé el paso en cualquier intersección a una persona ciega que lleva un bastón blanco con punta roja o usa un perro guía.","p":"Correcto. Pare y deje cruzar a la persona."},"ref":{"doc":"AL","page":63}},{"id":"al-085","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, you reach an intersection with no signs or signals at an unlawful speed. What happens to your right of way?","o":["You keep it if you came from the right","You keep it if you got there first","You lose any right of way you had","You gain it because you are faster"],"h1":"Breaking the speed law costs you something here.","h2":"In Alabama, if you enter an uncontrolled intersection at an unlawful speed, you lose any right of way you would otherwise have had.","p":"Right. Speeding into the intersection means you lose the right of way."},"es":{"q":"En Alabama, usted llega a una intersección sin señales ni semáforos a una velocidad ilegal. ¿Qué pasa con su derecho de paso?","o":["Lo conserva si venía de la derecha","Lo conserva si llegó primero","Pierde cualquier derecho de paso que tuviera","Lo gana porque va más rápido"],"h1":"Violar la ley de velocidad le cuesta algo aquí.","h2":"En Alabama, si entra a una intersección sin control a una velocidad ilegal, pierde cualquier derecho de paso que de otro modo habría tenido.","p":"Correcto. Entrar con exceso de velocidad significa perder el derecho de paso."},"ref":{"doc":"AL","page":63}},{"id":"al-086","scope":"AL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Alabama, a fire truck is on an emergency run. How close may you follow it if you are not on official business?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 200 feet","No closer than 500 feet"],"h1":"It is the longest distance on the list.","h2":"In Alabama only vehicles on necessary official business may follow within 500 feet of an emergency vehicle on an emergency run.","p":"Right. Stay more than 500 feet behind."},"es":{"q":"En Alabama, un camión de bomberos va a una emergencia. ¿Qué tan cerca puede seguirlo si usted no va en asuntos oficiales?","o":["No a menos de 50 pies","No a menos de 100 pies","No a menos de 200 pies","No a menos de 500 pies"],"h1":"Es la distancia más larga de la lista.","h2":"En Alabama solo los vehículos en asuntos oficiales necesarios pueden seguir a menos de 500 pies a un vehículo de emergencia que va a una emergencia.","p":"Correcto. Manténgase a más de 500 pies detrás."},"ref":{"doc":"AL","page":65}},{"id":"al-087","scope":"AL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Alabama, where is it illegal for a person to ride a bicycle?","o":["On the sidewalk","In a marked bike lane","Two side by side on the road","With the flow of traffic"],"h1":"Bicycles belong on the road, not where people walk.","h2":"In Alabama it is illegal for people on bicycles to ride on the sidewalk; they ride with traffic and must use a bike lane when there is one.","p":"Right. Riding a bicycle on the sidewalk is illegal in Alabama."},"es":{"q":"En Alabama, ¿dónde es ilegal que una persona ande en bicicleta?","o":["En la acera","En un carril para bicicletas marcado","Dos lado a lado en la calle","En la misma dirección del tráfico"],"h1":"Las bicicletas van en la calle, no donde camina la gente.","h2":"En Alabama es ilegal que las personas en bicicleta anden por la acera; deben ir con el tráfico y usar el carril para bicicletas cuando lo haya.","p":"Correcto. Andar en bicicleta por la acera es ilegal en Alabama."},"ref":{"doc":"AL","page":24}},{"id":"al-088","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, on a two-lane road with a 20 mph limit, you pass a stopped emergency vehicle with flashing lights. How fast should you go?","o":["5 mph","10 mph","15 mph","20 mph"],"h1":"It is half the posted limit in this case.","h2":"Under Alabama's Move Over law, on a two-lane road where the limit is 20 mph or less, you must move as far away as you can in your lane and slow to 10 mph.","p":"Right. Slow to 10 mph."},"es":{"q":"En Alabama, en un camino de dos carriles con límite de 20 mph, usted pasa junto a un vehículo de emergencia detenido con luces intermitentes. ¿A qué velocidad debe ir?","o":["5 mph","10 mph","15 mph","20 mph"],"h1":"En este caso es la mitad del límite indicado.","h2":"Según la ley Move Over de Alabama, en un camino de dos carriles con límite de 20 mph o menos, usted debe alejarse lo más posible dentro de su carril y bajar a 10 mph.","p":"Correcto. Baje a 10 mph."},"ref":{"doc":"AL","page":68}},{"id":"al-089","scope":"AL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Alabama, you may not cross the center line to pass on a hill or curve unless you can see clearly ahead for at least how far?","o":["100 feet","200 feet","500 feet","50 feet"],"h1":"It is the same distance as the headlight visibility rule.","h2":"In Alabama you may not cross the center line to pass on a curve or hill where you cannot see a clear passing distance of at least 500 feet.","p":"Right. You need at least 500 feet of clear view."},"es":{"q":"En Alabama, no puede cruzar la línea central para rebasar en una cuesta o curva a menos que vea claramente hacia adelante por lo menos ¿qué distancia?","o":["100 pies","200 pies","500 pies","50 pies"],"h1":"Es la misma distancia que la regla de visibilidad de las luces.","h2":"En Alabama no puede cruzar la línea central para rebasar en una curva o cuesta donde no pueda ver una distancia libre de por lo menos 500 pies.","p":"Correcto. Necesita ver por lo menos 500 pies libres."},"ref":{"doc":"AL","page":65}},{"id":"al-090","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, you miss your exit on a freeway. May you back up on the shoulder to reach it?","o":["Yes, if you use hazard lights","Yes, if traffic is light","Yes, but only at night","No, backing on a freeway is prohibited"],"h1":"Only emergency vehicles on duty are excepted.","h2":"In Alabama backing is prohibited on controlled-access highways such as freeways, except for emergency vehicles on duty, so go on to the next exit.","p":"Right. Never back up on a freeway; take the next exit."},"es":{"q":"En Alabama, usted se pasa de su salida en una autopista. ¿Puede retroceder por el acotamiento para llegar a ella?","o":["Sí, si usa las luces de emergencia","Sí, si hay poco tráfico","Sí, pero solo de noche","No, está prohibido retroceder en una autopista"],"h1":"Solo se exceptúan los vehículos de emergencia en servicio.","h2":"En Alabama está prohibido retroceder en las carreteras de acceso controlado, como las autopistas, excepto los vehículos de emergencia en servicio, así que siga hasta la próxima salida.","p":"Correcto. Nunca retroceda en una autopista; tome la próxima salida."},"ref":{"doc":"AL","page":66}},{"id":"al-091","scope":"AL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alabama, how close may you park to a stop sign at the side of the road?","o":["No closer than 30 feet","No closer than 5 feet","No closer than 10 feet","No closer than 100 feet"],"h1":"It is twice the distance for a fire hydrant.","h2":"In Alabama you may not park within 30 feet of a stop sign, flashing beacon, or traffic signal at the side of the road.","p":"Right. Stay at least 30 feet from a stop sign."},"es":{"q":"En Alabama, ¿qué tan cerca de una señal de alto al lado del camino puede estacionarse?","o":["No a menos de 30 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 100 pies"],"h1":"Es el doble de la distancia para un hidrante.","h2":"En Alabama no puede estacionarse a menos de 30 pies de una señal de alto, una luz intermitente o un semáforo al lado del camino.","p":"Correcto. Quédese por lo menos a 30 pies de una señal de alto."},"ref":{"doc":"AL","page":29}},{"id":"al-092","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a visitor at least 16 comes from a country that does not license drivers. How long may they drive here each calendar year?","o":["10 days","30 days","90 days","One full year"],"h1":"It is about three months.","h2":"In Alabama a non-resident from a country that does not require driver licenses may drive for up to 90 days in a calendar year, if the vehicle is registered in the home country.","p":"Right. Up to 90 days in a calendar year."},"es":{"q":"En Alabama, un visitante de al menos 16 años viene de un país que no da licencias de manejo. ¿Por cuánto tiempo puede manejar aquí cada año calendario?","o":["10 días","30 días","90 días","Un año completo"],"h1":"Son unos tres meses.","h2":"En Alabama un no residente de un país que no exige licencia de manejo puede manejar hasta 90 días en un año calendario, si el vehículo está registrado en su país.","p":"Correcto. Hasta 90 días en un año calendario."},"ref":{"doc":"AL","page":5}},{"id":"al-093","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, one way to prove who you are for a license is to bring two forms of ID. What must at least one of them have?","o":["A barcode","A notary stamp","Your home address","A photo of you"],"h1":"Think of what lets the examiner see your face.","h2":"In Alabama you may present two forms of identification for a license, and at least one of them must have your photograph.","p":"Right. At least one of the two must show your photo."},"es":{"q":"En Alabama, una forma de probar su identidad para una licencia es traer dos documentos de identificación. ¿Qué debe tener por lo menos uno de ellos?","o":["Un código de barras","Un sello de notario","Su dirección","Una foto suya"],"h1":"Piense en lo que permite al examinador ver su cara.","h2":"En Alabama usted puede presentar dos documentos de identificación para una licencia, y por lo menos uno debe tener su fotografía.","p":"Correcto. Por lo menos uno de los dos debe tener su foto."},"ref":{"doc":"AL","page":6}},{"id":"al-094","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, an immigration document used for a license must show at least how much allowed time left in the United States?","o":["7 days","30 days","6 months","One year"],"h1":"It is about one month.","h2":"In Alabama an immigration document used to apply for a license must show at least 30 days of allowed time remaining in the United States.","p":"Right. At least 30 days must remain."},"es":{"q":"En Alabama, un documento de inmigración usado para una licencia debe mostrar por lo menos ¿cuánto tiempo permitido restante en los Estados Unidos?","o":["7 días","30 días","6 meses","Un año"],"h1":"Es más o menos un mes.","h2":"En Alabama un documento de inmigración usado para solicitar una licencia debe mostrar por lo menos 30 días de tiempo permitido restante en los Estados Unidos.","p":"Correcto. Deben quedar por lo menos 30 días."},"ref":{"doc":"AL","page":8}},{"id":"al-095","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, which document does the manual list as required for every 15-year-old license applicant?","o":["A recent school report card","A marriage license from the county","A certified U.S. birth certificate","A W-2 tax form from a job"],"h1":"It is the paper that shows where and when you were born.","h2":"The Alabama manual marks a certified U.S. birth certificate as required for all 15-year-old applicants; a foreign-born teen may use a U.S. passport or a certified translation instead.","p":"Right. A 15-year-old brings a certified birth certificate."},"es":{"q":"En Alabama, ¿qué documento indica el manual como obligatorio para todo solicitante de 15 años?","o":["Una libreta de calificaciones reciente de la escuela","Una licencia de matrimonio del condado","Un acta de nacimiento certificada de EE. UU.","Un formulario de impuestos W-2 de un trabajo"],"h1":"Es el papel que muestra dónde y cuándo nació.","h2":"El manual de Alabama indica que el acta de nacimiento certificada de EE. UU. es obligatoria para todos los solicitantes de 15 años; un joven nacido en el extranjero puede usar un pasaporte de EE. UU. o una traducción certificada.","p":"Correcto. Un joven de 15 años trae un acta de nacimiento certificada."},"ref":{"doc":"AL","page":8}},{"id":"al-096","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, a 16-year-old learner passes the road test. What does the new license without the Y restriction cost?","o":["$5","$25","The full license fee","Nothing; it is free"],"h1":"The learner license already paid for the four years.","h2":"In Alabama a teen who passes the road test gets a new license with the Y restriction removed for the rest of the four-year period at no cost.","p":"Right. The new license costs nothing."},"es":{"q":"En Alabama, un aprendiz de 16 años aprueba el examen de manejo en carretera. ¿Cuánto cuesta la nueva licencia sin la restricción Y?","o":["$5","$25","La tarifa completa de licencia","Nada; es gratis"],"h1":"La licencia de aprendiz ya pagó los cuatro años.","h2":"En Alabama un joven que aprueba el examen en carretera recibe una nueva licencia sin la restricción Y por el resto del período de cuatro años, sin costo.","p":"Correcto. La nueva licencia no cuesta nada."},"ref":{"doc":"AL","page":10}},{"id":"al-097","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, what is the youngest age to get a full Class M license to ride a motorcycle?","o":["16 years old","14 years old","18 years old","21 years old"],"h1":"It is the same as the minimum driving age for a car.","h2":"In Alabama a person 16 or older may get a Class M license to ride a motorcycle; younger teens may only ride small motor-driven cycles.","p":"Right. A motorcycle license starts at 16."},"es":{"q":"En Alabama, ¿cuál es la edad mínima para obtener una licencia Clase M completa para manejar una motocicleta?","o":["16 años","14 años","18 años","21 años"],"h1":"Es la misma que la edad mínima para manejar un carro.","h2":"En Alabama una persona de 16 años o más puede obtener una licencia Clase M para manejar una motocicleta; los más jóvenes solo pueden usar ciclomotores pequeños.","p":"Correcto. La licencia de motocicleta empieza a los 16."},"ref":{"doc":"AL","page":10}},{"id":"al-098","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what happens if you do not pass the vision screening at the license office?","o":["You can never get a license in Alabama","You must see an eye specialist and bring back the report","You must wait one full year before you try again","You get a license for driving in daytime only"],"h1":"A professional checks your eyes first.","h2":"In Alabama, if you fail the vision screening you must have your eyes examined by a licensed eye specialist and return the report; if it shows you can see well enough, you may finish the test.","p":"Right. An eye specialist's report comes next."},"es":{"q":"En Alabama, ¿qué pasa si no aprueba el examen de la vista en la oficina de licencias?","o":["Nunca podrá obtener licencia en Alabama","Debe ver a un especialista de los ojos y traer el informe","Debe esperar un año completo para intentarlo otra vez","Recibe una licencia para manejar solo de día"],"h1":"Primero un profesional revisa sus ojos.","h2":"En Alabama, si no aprueba el examen de la vista, debe hacerse revisar los ojos por un especialista con licencia y entregar el informe; si muestra que ve bien, puede terminar el examen.","p":"Correcto. Lo siguiente es el informe de un especialista."},"ref":{"doc":"AL","page":11}},{"id":"al-099","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, before a road test begins, the examiner checks that the car has which equipment working?","o":["Fog lights and a spare tire","A backup camera and GPS","Brake lights, turn signals and a horn","Cruise control and heated seats"],"h1":"Think of the parts that warn others what you are doing.","h2":"Before an Alabama road test the examiner inspects the vehicle to be sure it is safe and has working brake lights, left and right turn signals, and a horn.","p":"Right. Brake lights, turn signals and a horn must work."},"es":{"q":"En Alabama, antes de empezar el examen en carretera, el examinador revisa que el carro tenga ¿qué equipo funcionando?","o":["Luces antiniebla y llanta de repuesto","Una cámara de reversa y GPS","Luces de freno, direccionales y bocina","Control de crucero y asientos con calefacción"],"h1":"Piense en las partes que avisan a otros lo que usted hace.","h2":"Antes de un examen en carretera en Alabama el examinador revisa que el vehículo sea seguro y tenga luces de freno, direccionales izquierda y derecha y bocina funcionando.","p":"Correcto. Las luces de freno, las direccionales y la bocina deben funcionar."},"ref":{"doc":"AL","page":11}},{"id":"al-100","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, when may you use a rental car for your road test?","o":["Only if your name is on the rental agreement as a driver","Never; rental cars are not allowed","Only if the rental company sends a worker","Any time, with no extra papers"],"h1":"Your name must appear on the paperwork.","h2":"In Alabama a rental vehicle may be used for the road test only if the applicant's name is on the rental agreement as an additional driver.","p":"Right. Your name must be on the rental agreement."},"es":{"q":"En Alabama, ¿cuándo puede usar un carro de alquiler para su examen en carretera?","o":["Solo si su nombre está en el contrato de alquiler como conductor","Nunca; no se permiten carros de alquiler","Solo si la compañía de alquiler manda a un empleado","Siempre, sin papeles adicionales"],"h1":"Su nombre debe aparecer en los papeles.","h2":"En Alabama se puede usar un vehículo de alquiler para el examen en carretera solo si el nombre del solicitante está en el contrato de alquiler como conductor adicional.","p":"Correcto. Su nombre debe estar en el contrato de alquiler."},"ref":{"doc":"AL","page":11}},{"id":"al-101","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, how long after it is issued does a regular driver license expire?","o":["Two years","Six years","Eight years","Four years"],"h1":"It is the same length as a presidential term.","h2":"An Alabama driver license expires four years after it is issued, and the expiration date is printed on the license.","p":"Right. A license is good for four years."},"es":{"q":"En Alabama, ¿cuánto tiempo después de emitida vence una licencia de manejo normal?","o":["Dos años","Seis años","Ocho años","Cuatro años"],"h1":"Dura lo mismo que un período presidencial.","h2":"Una licencia de manejo de Alabama vence cuatro años después de emitida, y la fecha de vencimiento está impresa en la licencia.","p":"Correcto. La licencia vale por cuatro años."},"ref":{"doc":"AL","page":13}},{"id":"al-102","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, your license is lost but not expired. What do you need to get a duplicate?","o":["Pass the written test again","Proof of identity, but no exam","Pass the road test again","A letter from the police"],"h1":"No testing is needed, but you must show who you are.","h2":"In Alabama you can get a duplicate of a lost, destroyed or unreadable license without any examination, but you must show proof of identity such as a certified birth certificate.","p":"Right. No exam, just proof of identity."},"es":{"q":"En Alabama, perdió su licencia pero no está vencida. ¿Qué necesita para obtener un duplicado?","o":["Aprobar otra vez el examen escrito","Prueba de identidad, pero ningún examen","Aprobar otra vez el examen en carretera","Una carta de la policía"],"h1":"No hace falta ningún examen, pero debe mostrar quién es.","h2":"En Alabama puede obtener un duplicado de una licencia perdida, destruida o ilegible sin ningún examen, pero debe mostrar prueba de identidad, como un acta de nacimiento certificada.","p":"Correcto. Sin examen, solo prueba de identidad."},"ref":{"doc":"AL","page":13}},{"id":"al-103","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, you update your address on your driver record after a move within the state. What happens?","o":["You pay a $25 fee","You must retake the written test","It is free, but no new license is printed","A new license is mailed to you"],"h1":"Your record changes, but the card in your wallet does not.","h2":"In Alabama you may update your address on your driver record at no charge, but a new license or ID card is not reissued.","p":"Right. It is free, and no new card is issued."},"es":{"q":"En Alabama, usted actualiza su dirección en su historial de conductor después de mudarse dentro del estado. ¿Qué pasa?","o":["Paga una tarifa de $25","Debe repetir el examen escrito","Es gratis, pero no se imprime una licencia nueva","Le envían una licencia nueva por correo"],"h1":"Su historial cambia, pero la tarjeta en su cartera no.","h2":"En Alabama puede actualizar su dirección en su historial de conductor sin costo, pero no se emite una nueva licencia ni tarjeta de identificación.","p":"Correcto. Es gratis y no se emite una tarjeta nueva."},"ref":{"doc":"AL","page":14}},{"id":"al-104","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, which license class covers most ordinary passenger cars?","o":["Class D","Class A","Class C","Class M"],"h1":"It is the same class printed on a learner license.","h2":"In Alabama a Class D license covers most passenger vehicles that are not in Classes A, B, C or M.","p":"Right. Class D is for ordinary passenger cars."},"es":{"q":"En Alabama, ¿qué clase de licencia cubre la mayoría de los carros de pasajeros comunes?","o":["Clase D","Clase A","Clase C","Clase M"],"h1":"Es la misma clase que aparece en una licencia de aprendiz.","h2":"En Alabama una licencia Clase D cubre la mayoría de los vehículos de pasajeros que no están en las Clases A, B, C o M.","p":"Correcto. La Clase D es para carros de pasajeros comunes."},"ref":{"doc":"AL","page":14}},{"id":"al-105","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, what is the penalty for a third hands-free law conviction within 24 months?","o":["A warning only","A $50 fine and 1 point","A $100 fine and 2 points","A $150 fine and 3 points"],"h1":"The fine and points go up with each conviction.","h2":"Under Alabama's hands-free law, a third conviction within 24 months brings a $150 fine and 3 points on your driving record.","p":"Right. The third conviction is $150 and 3 points."},"es":{"q":"En Alabama, ¿cuál es la sanción por una tercera condena bajo la ley de manos libres dentro de 24 meses?","o":["Solo una advertencia","Una multa de $50 y 1 punto","Una multa de $100 y 2 puntos","Una multa de $150 y 3 puntos"],"h1":"La multa y los puntos suben con cada condena.","h2":"Bajo la ley de manos libres de Alabama, una tercera condena dentro de 24 meses trae una multa de $150 y 3 puntos en su historial de manejo.","p":"Correcto. La tercera condena es $150 y 3 puntos."},"ref":{"doc":"AL","page":16}},{"id":"al-106","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, a license was suspended because of a drug conviction. What extra fee is added when it is reinstated?","o":["$5","$25","$250","$1,000"],"h1":"It is a small extra amount on top of the regular reinstatement fee.","h2":"In Alabama, reinstating a license after a drug-related conviction costs an additional $25 on top of the regular reinstatement fee.","p":"Right. Drug-related reinstatements add $25."},"es":{"q":"En Alabama, una licencia fue suspendida por una condena relacionada con drogas. ¿Qué tarifa extra se agrega al restablecerla?","o":["$5","$25","$250","$1,000"],"h1":"Es una cantidad pequeña además de la tarifa normal de restablecimiento.","h2":"En Alabama, restablecer una licencia después de una condena relacionada con drogas cuesta $25 adicionales a la tarifa normal de restablecimiento.","p":"Correcto. Los casos de drogas agregan $25."},"ref":{"doc":"AL","page":17}},{"id":"al-107","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, a person gives false information on a license application. What can ALEA do to that license?","o":["Add 2 points only","Nothing, once it is issued","Cancel it","Change it to a learner license"],"h1":"The person was never entitled to the license.","h2":"In Alabama the Director of ALEA may cancel a license when the person was not entitled to it, including when false information or fraud was used on the application.","p":"Right. The license can be canceled."},"es":{"q":"En Alabama, una persona da información falsa en una solicitud de licencia. ¿Qué puede hacer ALEA con esa licencia?","o":["Solo agregar 2 puntos","Nada, una vez emitida","Cancelarla","Cambiarla a licencia de aprendiz"],"h1":"La persona nunca tuvo derecho a la licencia.","h2":"En Alabama el Director de ALEA puede cancelar una licencia cuando la persona no tenía derecho a ella, incluso cuando se usó información falsa o fraude en la solicitud.","p":"Correcto. La licencia puede ser cancelada."},"ref":{"doc":"AL","page":17}},{"id":"al-108","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, a driver is convicted of failing to stop and give aid after a crash that injured someone. What must happen to the license?","o":["It must be revoked","It gets 2 points","It gets a warning letter","Nothing, if the driver has insurance"],"h1":"This is on the list of offenses where the Director has no choice.","h2":"In Alabama the Director must revoke the license of a driver convicted of failing to stop, give aid, or identify themselves after a crash that caused death or injury.","p":"Right. The license must be revoked."},"es":{"q":"En Alabama, un conductor es condenado por no detenerse ni dar ayuda después de un choque que hirió a alguien. ¿Qué debe pasar con la licencia?","o":["Debe ser revocada","Recibe 2 puntos","Recibe una carta de advertencia","Nada, si el conductor tiene seguro"],"h1":"Está en la lista de delitos donde el Director no tiene opción.","h2":"En Alabama el Director debe revocar la licencia de un conductor condenado por no detenerse, no dar ayuda o no identificarse después de un choque que causó muerte o lesiones.","p":"Correcto. La licencia debe ser revocada."},"ref":{"doc":"AL","page":17}},{"id":"al-109","scope":"AL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Alabama, how many points are added for a reckless driving conviction?","o":["2 points","3 points","4 points","6 points"],"h1":"It is one of the highest point values on the list.","h2":"In Alabama a reckless driving or reckless endangerment conviction involving a motor vehicle adds 6 points to your record.","p":"Right. Reckless driving is 6 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por una condena por manejo imprudente (reckless driving)?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Es uno de los valores más altos de la lista.","h2":"En Alabama una condena por manejo imprudente o por poner en peligro a otros con un vehículo agrega 6 puntos a su historial.","p":"Correcto. El manejo imprudente son 6 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-110","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, how many points are added for illegal passing or driving on the wrong side of the road?","o":["2 points","4 points","5 points","6 points"],"h1":"It is more than following too closely, but less than failing to yield.","h2":"In Alabama a conviction for driving on the wrong side of the road or passing illegally adds 4 points to your record.","p":"Right. Illegal passing is 4 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por rebasar ilegalmente o manejar en el lado contrario del camino?","o":["2 puntos","4 puntos","5 puntos","6 puntos"],"h1":"Es más que seguir demasiado cerca, pero menos que no ceder el paso.","h2":"En Alabama una condena por manejar en el lado contrario del camino o rebasar ilegalmente agrega 4 puntos a su historial.","p":"Correcto. Rebasar ilegalmente son 4 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-111","scope":"AL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Alabama, how many points are added for not obeying construction or maintenance zone markers?","o":["1 point","2 points","3 points","6 points"],"h1":"It is the same as following too closely.","h2":"In Alabama failing to obey construction or maintenance zone markers adds 3 points to your driving record.","p":"Right. Work zone violations are 3 points."},"es":{"q":"En Alabama, ¿cuántos puntos se agregan por no obedecer las marcas de una zona de construcción o mantenimiento?","o":["1 punto","2 puntos","3 puntos","6 puntos"],"h1":"Es lo mismo que por seguir demasiado cerca.","h2":"En Alabama no obedecer las marcas de una zona de construcción o mantenimiento agrega 3 puntos a su historial de manejo.","p":"Correcto. Las infracciones en zonas de trabajo son 3 puntos."},"ref":{"doc":"AL","page":19}},{"id":"al-112","scope":"AL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Alabama, a driver gets 24 or more points within 2 years. How long is the license suspended?","o":["365 days","60 days","120 days","180 days"],"h1":"This is the top of the point schedule.","h2":"In Alabama a driver with 24 or more points in a 2-year period has the license suspended for 365 days.","p":"Right. 24 or more points means a 365-day suspension."},"es":{"q":"En Alabama, un conductor acumula 24 puntos o más en 2 años. ¿Por cuánto tiempo se suspende la licencia?","o":["365 días","60 días","120 días","180 días"],"h1":"Es lo más alto de la tabla de puntos.","h2":"En Alabama un conductor con 24 puntos o más en un período de 2 años tiene la licencia suspendida por 365 días.","p":"Correcto. 24 puntos o más significan una suspensión de 365 días."},"ref":{"doc":"AL","page":19}},{"id":"al-113","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, may people on bicycles ride two side by side (two abreast) on the road?","o":["No, never","Yes, at all times","Only on Sundays","Only in a bike lane"],"h1":"Alabama's rule here has no time limit.","h2":"Alabama law lets people on bicycles ride two abreast at all times, so drivers should expect to see them side by side.","p":"Right. Two abreast is allowed at all times."},"es":{"q":"En Alabama, ¿pueden las personas en bicicleta ir dos lado a lado en el camino?","o":["No, nunca","Sí, en todo momento","Solo los domingos","Solo en un carril para bicicletas"],"h1":"La regla de Alabama no tiene límite de horario.","h2":"La ley de Alabama permite que las personas en bicicleta vayan dos lado a lado en todo momento, así que los conductores deben esperar verlas así.","p":"Correcto. Ir dos lado a lado se permite en todo momento."},"ref":{"doc":"AL","page":23}},{"id":"al-114","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, you will turn right across a bicycle lane. What does the law tell you to do?","o":["Turn from the lane left of the bike lane","Honk so bicycles move away","Move into the bike lane before you turn, if it is safe","Stop in the bike lane and wait for a green arrow"],"h1":"You prepare for the turn the same way you move toward a curb.","h2":"In Alabama, when turning across a bicycle lane, you must move into the bike lane before the turn, as long as doing so does not put a person on a bicycle in danger.","p":"Right. Enter the bike lane before turning, when safe."},"es":{"q":"En Alabama, usted va a girar a la derecha cruzando un carril para bicicletas. ¿Qué le indica la ley?","o":["Girar desde el carril a la izquierda del carril de bicicletas","Tocar la bocina para que las bicicletas se aparten","Entrar al carril de bicicletas antes de girar, si es seguro","Detenerse en el carril de bicicletas y esperar una flecha verde"],"h1":"Se prepara para el giro igual que cuando se acerca a la orilla.","h2":"En Alabama, al girar cruzando un carril para bicicletas, debe entrar al carril de bicicletas antes del giro, siempre que no ponga en peligro a una persona en bicicleta.","p":"Correcto. Entre al carril de bicicletas antes de girar, si es seguro."},"ref":{"doc":"AL","page":24}},{"id":"al-115","scope":"AL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Alabama, where are three-point turns not permitted?","o":["On interstate freeways","On quiet residential streets","On any road with a speed limit","On any road during daylight"],"h1":"Think of the roads where traffic moves fastest.","h2":"In Alabama three-point turns are not permitted on interstate freeways, on curves, or near hilltops where other drivers cannot see you within 500 feet.","p":"Right. No three-point turns on interstates."},"es":{"q":"En Alabama, ¿dónde no se permiten las vueltas en tres movimientos (three-point turns)?","o":["En las autopistas interestatales","En calles residenciales tranquilas","En cualquier camino con límite de velocidad","En cualquier camino de día"],"h1":"Piense en los caminos donde el tráfico va más rápido.","h2":"En Alabama no se permiten las vueltas en tres movimientos en autopistas interestatales, en curvas ni cerca de la cima de colinas donde otros conductores no pueden verlo a menos de 500 pies.","p":"Correcto. No se dan vueltas en tres movimientos en las interestatales."},"ref":{"doc":"AL","page":23}},{"id":"al-116","scope":"AL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Alabama, at an intersection with no signs or signals, how close to a crosswalk may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"It is a little more than the distance for a fire hydrant.","h2":"In Alabama you may not park within 20 feet of a crosswalk at an uncontrolled intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Alabama, en una intersección sin señales ni semáforos, ¿qué tan cerca de un cruce peatonal puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Es un poco más que la distancia para un hidrante.","h2":"En Alabama no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección sin control.","p":"Correcto. Quédese por lo menos a 20 pies del cruce peatonal."},"ref":{"doc":"AL","page":29}},{"id":"al-117","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, until when must a child ride in a forward-facing car seat?","o":["Until at least 2 years or 25 pounds","Until at least 5 years or 40 pounds","Until at least 8 years or 80 pounds","Until at least 10 years or 4 feet 9 inches"],"h1":"After this stage comes the booster seat, used until age 6.","h2":"Alabama law requires a forward-facing or convertible seat facing forward until a child is at least 5 years old or 40 pounds.","p":"Right. Forward-facing until at least 5 years or 40 pounds."},"es":{"q":"En Alabama, ¿hasta cuándo debe un niño ir en un asiento de seguridad mirando hacia adelante?","o":["Hasta por lo menos 2 años o 25 libras","Hasta por lo menos 5 años o 40 libras","Hasta por lo menos 8 años u 80 libras","Hasta por lo menos 10 años o 4 pies 9 pulgadas"],"h1":"Después de esta etapa viene el asiento elevado, que se usa hasta los 6 años.","h2":"La ley de Alabama exige un asiento mirando hacia adelante (o convertible hacia adelante) hasta que el niño tenga por lo menos 5 años o 40 libras.","p":"Correcto. Mirando hacia adelante hasta por lo menos 5 años o 40 libras."},"ref":{"doc":"AL","page":30}},{"id":"al-118","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, a person driving a commercial vehicle is legally under the influence at what blood alcohol level?","o":["0.02 percent or more","0.08 percent or more","0.04 percent or more","0.10 percent or more"],"h1":"It is half the limit for other adult drivers.","h2":"In Alabama it is unlawful to drive a commercial vehicle with a blood alcohol level of 0.04 percent or more.","p":"Right. The commercial limit is 0.04 percent."},"es":{"q":"En Alabama, una persona que maneja un vehículo comercial está legalmente bajo la influencia con ¿qué nivel de alcohol en la sangre?","o":["0.02 por ciento o más","0.08 por ciento o más","0.04 por ciento o más","0.10 por ciento o más"],"h1":"Es la mitad del límite para los demás conductores adultos.","h2":"En Alabama es ilegal manejar un vehículo comercial con un nivel de alcohol en la sangre de 0.04 por ciento o más.","p":"Correcto. El límite comercial es 0.04 por ciento."},"ref":{"doc":"AL","page":33}},{"id":"al-119","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, what is the fine range for a second DUI conviction within 10 years?","o":["$1,100 to $5,100","$100 to $500","$600 to $2,100","$4,100 to $10,100"],"h1":"It is higher than the first-offense range of $600 to $2,100.","h2":"In Alabama a second DUI conviction within 10 years brings a fine of $1,100 to $5,100, and up to one year in jail.","p":"Right. A second DUI fine is $1,100 to $5,100."},"es":{"q":"En Alabama, ¿cuál es el rango de la multa por una segunda condena por DUI dentro de 10 años?","o":["$1,100 a $5,100","$100 a $500","$600 a $2,100","$4,100 a $10,100"],"h1":"Es más alto que el rango de la primera vez, de $600 a $2,100.","h2":"En Alabama una segunda condena por DUI dentro de 10 años trae una multa de $1,100 a $5,100 y hasta un año de cárcel.","p":"Correcto. La multa por un segundo DUI es de $1,100 a $5,100."},"ref":{"doc":"AL","page":33}},{"id":"al-120","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, a fourth DUI conviction is a felony. How long is the driver license revoked?","o":["90 days","One year","Three years","Five years"],"h1":"It is longer than the three years for a third conviction.","h2":"In Alabama a fourth or later DUI conviction is a Class C felony and brings a five-year revocation of the driver license.","p":"Right. A fourth DUI means a five-year revocation."},"es":{"q":"En Alabama, una cuarta condena por DUI es un delito grave. ¿Por cuánto tiempo se revoca la licencia de manejo?","o":["90 días","Un año","Tres años","Cinco años"],"h1":"Es más que los tres años de una tercera condena.","h2":"En Alabama una cuarta condena por DUI, o más, es un delito grave Clase C y trae una revocación de la licencia por cinco años.","p":"Correcto. Un cuarto DUI significa una revocación de cinco años."},"ref":{"doc":"AL","page":34}},{"id":"al-121","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, a crash with injuries happens on a state highway outside any city. Who must be told by the quickest means?","o":["Your insurance agent only","The State Troopers","The county probate judge","The Driver License Division by mail"],"h1":"Inside a city it would be the local police.","h2":"In Alabama any crash with injury or death must be reported by the quickest means to the local police inside a city, or to the State Troopers on a state highway.","p":"Right. On a state highway, call the State Troopers."},"es":{"q":"En Alabama, ocurre un choque con heridos en una carretera estatal fuera de cualquier ciudad. ¿A quién se debe avisar por el medio más rápido?","o":["Solo a su agente de seguros","A los State Troopers (policía estatal)","Al juez de sucesiones del condado","A la División de Licencias por correo"],"h1":"Dentro de una ciudad sería la policía local.","h2":"En Alabama todo choque con heridos o muertos debe reportarse por el medio más rápido a la policía local dentro de una ciudad, o a los State Troopers en una carretera estatal.","p":"Correcto. En una carretera estatal, llame a los State Troopers."},"ref":{"doc":"AL","page":38}},{"id":"al-122","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, both drivers in a crash were insured at the time. Does either one have to send Form SR-31?","o":["Yes, both drivers must","Only the driver who was not at fault","No, neither one has to","Only if the crash was on an interstate"],"h1":"The form matters when the at-fault driver had no insurance.","h2":"In Alabama, if both parties were insured at the time of the crash, neither one has to submit Form SR-31.","p":"Right. With both insured, no SR-31 is needed."},"es":{"q":"En Alabama, los dos conductores de un choque tenían seguro en ese momento. ¿Alguno tiene que enviar el formulario SR-31?","o":["Sí, los dos deben enviarlo","Solo el conductor que no tuvo la culpa","No, ninguno tiene que hacerlo","Solo si el choque fue en una interestatal"],"h1":"El formulario importa cuando el culpable no tenía seguro.","h2":"En Alabama, si las dos partes tenían seguro en el momento del choque, ninguna tiene que presentar el formulario SR-31.","p":"Correcto. Si los dos tenían seguro, no se necesita el SR-31."},"ref":{"doc":"AL","page":38}},{"id":"al-123","scope":"AL","cat":"signals","sign":null,"c":3,"en":{"q":"In Alabama, the round yellow railroad warning sign is usually placed how far before the tracks?","o":["50 feet","100 feet","1 mile","750 feet"],"h1":"It is between a tenth and a fifth of a mile.","h2":"The Alabama manual says the round yellow railroad advance warning sign is placed 750 feet before the track.","p":"Right. It stands about 750 feet before the tracks."},"es":{"q":"En Alabama, la señal redonda amarilla de advertencia de ferrocarril normalmente se coloca ¿a qué distancia antes de las vías?","o":["50 pies","100 pies","1 milla","750 pies"],"h1":"Está entre una décima y una quinta parte de milla.","h2":"El manual de Alabama dice que la señal redonda amarilla de advertencia de ferrocarril se coloca 750 pies antes de las vías.","p":"Correcto. Está a unos 750 pies antes de las vías."},"ref":{"doc":"AL","page":38}},{"id":"al-124","scope":"AL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Alabama, in rural areas a school bus turns on its flashing amber lights at least how far before it stops?","o":["50 feet","300 feet","1,000 feet","One mile"],"h1":"In towns it is at least 100 feet; in the country it is three times that.","h2":"In Alabama a school bus uses its flashing amber warning lights at least 300 feet before stopping in rural areas, and at least 100 feet in towns.","p":"Right. At least 300 feet in rural areas."},"es":{"q":"En Alabama, en zonas rurales un autobús escolar enciende sus luces amarillas intermitentes por lo menos ¿a qué distancia antes de detenerse?","o":["50 pies","300 pies","1,000 pies","Una milla"],"h1":"En los pueblos son por lo menos 100 pies; en el campo, el triple.","h2":"En Alabama un autobús escolar usa sus luces amarillas intermitentes por lo menos 300 pies antes de detenerse en zonas rurales, y por lo menos 100 pies en los pueblos.","p":"Correcto. Por lo menos 300 pies en zonas rurales."},"ref":{"doc":"AL","page":62}},{"id":"al-125","scope":"AL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Alabama, when may you turn left on a red light after stopping?","o":["Never; left on red is always illegal","At any intersection if no cars are coming","From a one-way street onto a one-way street going left","Only when a police officer waves you on"],"h1":"Both streets must carry traffic in one direction only.","h2":"In Alabama you may turn left after stopping at a red light when you are on a one-way street turning onto another one-way street that moves from right to left, unless a sign forbids it.","p":"Right. One-way onto one-way, after a full stop."},"es":{"q":"En Alabama, ¿cuándo puede girar a la izquierda con la luz roja después de detenerse?","o":["Nunca; girar a la izquierda en rojo siempre es ilegal","En cualquier intersección si no vienen carros","De una calle de un solo sentido a otra de un solo sentido hacia la izquierda","Solo cuando un policía le hace señas"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Alabama puede girar a la izquierda después de detenerse en una luz roja cuando va por una calle de un solo sentido hacia otra calle de un solo sentido que corre de derecha a izquierda, salvo que una señal lo prohíba.","p":"Correcto. De un solo sentido a un solo sentido, después de parar por completo."},"ref":{"doc":"AL","page":60}},{"id":"al-126","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, an officer gives you a traffic ticket and asks you to sign it. What does the manual say?","o":["Signing it means you admit that you are guilty","You may refuse to sign, and nothing will happen","Only a lawyer is allowed to sign it for you","It is not admitting guilt, but refusing may mean arrest"],"h1":"You can still fight the ticket in court later.","h2":"The Alabama manual explains that signing a traffic citation is not an admission of guilt, but refusing to accept it may result in your arrest; you can contest it in court.","p":"Right. Sign it, and contest it in court if you disagree."},"es":{"q":"En Alabama, un oficial le da una multa de tránsito y le pide que la firme. ¿Qué dice el manual?","o":["Firmarla significa que usted admite la culpa","Puede negarse a firmar y no pasará nada","Solo un abogado tiene permiso para firmarla por usted","No es admitir la culpa, pero negarse puede llevar al arresto"],"h1":"Después todavía puede impugnar la multa en la corte.","h2":"El manual de Alabama explica que firmar una multa de tránsito no es admitir la culpa, pero negarse a aceptarla puede llevar a su arresto; puede impugnarla en la corte.","p":"Correcto. Fírmela, e impúgnela en la corte si no está de acuerdo."},"ref":{"doc":"AL","page":67}},{"id":"al-127","scope":"AL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Alabama, what is the highest fine for a second conviction of driving without the required liability insurance?","o":["$500","$1,000","$2,500","$10,000"],"h1":"It is twice the highest fine for a first conviction.","h2":"In Alabama a second or later liability insurance violation can bring a fine of up to $1,000, and a six-month license suspension is also possible.","p":"Right. Up to $1,000 for a second violation."},"es":{"q":"En Alabama, ¿cuál es la multa máxima por una segunda condena por manejar sin el seguro de responsabilidad obligatorio?","o":["$500","$1,000","$2,500","$10,000"],"h1":"Es el doble de la multa máxima por una primera condena.","h2":"En Alabama una segunda infracción o más del seguro de responsabilidad puede traer una multa de hasta $1,000, y también es posible una suspensión de licencia de seis meses.","p":"Correcto. Hasta $1,000 por una segunda infracción."},"ref":{"doc":"AL","page":68}},{"id":"al-128","scope":"AL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Alabama, how much of the front windshield may be tinted?","o":["None of it","The whole windshield, if light passes 32 percent","Only the top 6 inches","The bottom half"],"h1":"It is a narrow strip along the top edge.","h2":"On every vehicle in Alabama, only the upper 6 inches of the front windshield may be tinted, and only with a see-through material.","p":"Right. Only the top 6 inches may be tinted."},"es":{"q":"En Alabama, ¿qué parte del parabrisas delantero puede tener polarizado?","o":["Ninguna parte","Todo el parabrisas, si deja pasar el 32 por ciento de luz","Solo las 6 pulgadas de arriba","La mitad de abajo"],"h1":"Es una franja angosta en el borde de arriba.","h2":"En todo vehículo en Alabama solo las 6 pulgadas de arriba del parabrisas delantero pueden tener polarizado, y solo con un material transparente.","p":"Correcto. Solo las 6 pulgadas de arriba pueden polarizarse."},"ref":{"doc":"AL","page":68}},{"id":"al-129","scope":"AL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Alabama, your car breaks down on a freeway. What does the manual suggest tying to a door handle or antenna as a distress signal?","o":["A white cloth","A red balloon","A green flag","A black bag"],"h1":"It is the color often used to show you need help or give up.","h2":"The Alabama manual says to park off the road, raise the hood, and tie a white cloth to a door handle or antenna so officers know you need help.","p":"Right. A white cloth signals that you need help."},"es":{"q":"En Alabama, su carro se descompone en una autopista. ¿Qué sugiere el manual atar a la manija de la puerta o a la antena como señal de auxilio?","o":["Un trapo blanco","Un globo rojo","Una bandera verde","Una bolsa negra"],"h1":"Es el color que se usa a menudo para pedir ayuda o rendirse.","h2":"El manual de Alabama dice que se estacione fuera del camino, levante el capó y ate un trapo blanco a la manija de la puerta o a la antena para que los oficiales sepan que necesita ayuda.","p":"Correcto. Un trapo blanco indica que necesita ayuda."},"ref":{"doc":"AL","page":76}},{"id":"al-130","scope":"AL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Alabama, what braking equipment must every car have?","o":["Anti-lock brakes","Brakes on the front wheels only","Disc brakes on all four wheels","A foot brake and a separate parking brake"],"h1":"The law asks for two separate ways to apply the brakes.","h2":"Alabama law requires every automobile to have two separate ways of applying the brakes: a regular foot brake and a parking brake.","p":"Right. A foot brake and a parking brake."},"es":{"q":"En Alabama, ¿qué equipo de frenos debe tener todo carro?","o":["Frenos antibloqueo (ABS)","Frenos solo en las ruedas delanteras","Frenos de disco en las cuatro ruedas","Un freno de pie y un freno de mano aparte"],"h1":"La ley pide dos maneras distintas de aplicar los frenos.","h2":"La ley de Alabama exige que todo automóvil tenga dos maneras distintas de aplicar los frenos: un freno de pie normal y un freno de estacionamiento.","p":"Correcto. Un freno de pie y un freno de estacionamiento."},"ref":{"doc":"AL","page":79}},{"id":"al-131","scope":"AL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Alabama, who may use a siren, bell or exhaust whistle on a vehicle?","o":["Any driver in heavy traffic","Only emergency vehicles","Trucks over 10,000 pounds","Any driver at night"],"h1":"Think of ambulances and fire trucks.","h2":"In Alabama bells, sirens and exhaust whistles may not be used on a vehicle except on emergency vehicles; other cars use a normal horn only to warn.","p":"Right. Only emergency vehicles may use them."},"es":{"q":"En Alabama, ¿quién puede usar una sirena, una campana o un silbato de escape en un vehículo?","o":["Cualquier conductor en tráfico pesado","Solo los vehículos de emergencia","Camiones de más de 10,000 libras","Cualquier conductor de noche"],"h1":"Piense en ambulancias y camiones de bomberos.","h2":"En Alabama no se pueden usar campanas, sirenas ni silbatos de escape en un vehículo, salvo en vehículos de emergencia; los demás carros usan la bocina normal solo para advertir.","p":"Correcto. Solo los vehículos de emergencia pueden usarlos."},"ref":{"doc":"AL","page":80}},{"id":"ar-001","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what is the youngest age to get a learner's license?","o":["14 years old","15 years old","16 years old","13 years old"],"h1":"Arkansas lets teens start earlier than many other states.","h2":"In Arkansas, the learner's license is for teens who are 14 or 15 years old, so 14 is the youngest age.","p":"Right. The Arkansas learner's license starts at age 14."},"es":{"q":"En Arkansas, ¿cuál es la edad mínima para obtener la licencia de aprendiz?","o":["14 años","15 años","16 años","13 años"],"h1":"Arkansas permite empezar antes que muchos otros estados.","h2":"En Arkansas, la licencia de aprendiz es para jóvenes de 14 o 15 años, así que 14 es la edad mínima.","p":"Correcto. La licencia de aprendiz en Arkansas empieza a los 14 años."},"zh":{"q":"在 Arkansas，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","13 岁"],"h1":"Arkansas 让青少年比很多其他州更早开始。","h2":"在 Arkansas，学习驾照是给 14 岁或 15 岁的青少年的，所以最小年龄是 14 岁。","p":"对。Arkansas 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Arkansas, tuổi nhỏ nhất để có giấy phép học lái (learner's license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","13 tuổi"],"h1":"Arkansas cho thanh thiếu niên bắt đầu sớm hơn nhiều tiểu bang khác.","h2":"Ở Arkansas, giấy phép học lái dành cho thanh thiếu niên 14 hoặc 15 tuổi, vì vậy 14 là tuổi nhỏ nhất.","p":"Đúng. Giấy phép học lái ở Arkansas bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Arkansas, ano ang pinakabatang edad para makakuha ng learner's license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","13 taong gulang"],"h1":"Mas maaga nagsisimula ang mga kabataan sa Arkansas kaysa sa maraming ibang estado.","h2":"Sa Arkansas, ang learner's license ay para sa mga kabataang 14 o 15 taong gulang, kaya 14 ang pinakabatang edad.","p":"Tama. Ang learner's license sa Arkansas ay nagsisimula sa edad na 14."},"ar":{"q":"في Arkansas، ما هو أصغر عمر للحصول على رخصة المتعلم (learner's license)؟","o":["14 سنة","15 سنة","16 سنة","13 سنة"],"h1":"تسمح Arkansas للمراهقين بالبدء أبكر من كثير من الولايات الأخرى.","h2":"في Arkansas، رخصة المتعلم مخصصة للمراهقين في عمر 14 أو 15 سنة، لذلك فإن 14 هو أصغر عمر.","p":"صحيح. رخصة المتعلم في Arkansas تبدأ من عمر 14 سنة."},"ref":{"doc":"AR","page":3}},{"id":"ar-002","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a teen with a learner's license must drive with a licensed driver. How old must that driver be?","o":["At least 16 years old","At least 18 years old","At least 21 years old","At least 25 years old"],"h1":"The helper must be an adult who is old enough to buy alcohol legally.","h2":"An Arkansas learner may drive only with a licensed driver who is at least 21 years old, so an experienced adult is always there to guide them.","p":"Right. A learner drives with a licensed driver age 21 or older."},"es":{"q":"En Arkansas, un joven con licencia de aprendiz debe manejar con un conductor con licencia. ¿Qué edad debe tener ese conductor?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 21 años","Por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Arkansas, el aprendiz solo puede manejar con un conductor con licencia que tenga por lo menos 21 años, para que siempre lo guíe un adulto con experiencia.","p":"Correcto. El aprendiz maneja con un conductor con licencia de 21 años o más."},"zh":{"q":"在 Arkansas，持学习驾照的青少年必须和一位有驾照的司机一起开车。这位司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"陪同的人必须是到了可以合法买酒年龄的成年人。","h2":"Arkansas 学习驾驶的人只能和至少 21 岁、有驾照的司机一起开车，这样总有一位有经验的成年人在旁边指导。","p":"对。学习驾驶的人和 21 岁或以上、有驾照的司机一起开车。"},"vi":{"q":"Ở Arkansas, thanh thiếu niên có giấy phép học lái phải lái xe cùng một người có bằng lái. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người đi kèm phải là người lớn đủ tuổi mua rượu hợp pháp.","h2":"Ở Arkansas, người học lái chỉ được lái xe cùng một người có bằng lái từ 21 tuổi trở lên, để luôn có người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người học lái phải lái cùng người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Arkansas, ang kabataang may learner's license ay dapat magmaneho kasama ang isang drayber na may lisensiya. Ilang taon dapat ang drayber na iyon?","o":["Hindi bababa sa 16 taong gulang","Hindi bababa sa 18 taong gulang","Hindi bababa sa 21 taong gulang","Hindi bababa sa 25 taong gulang"],"h1":"Ang kasama ay dapat isang adult na nasa edad na para legal na bumili ng alak.","h2":"Sa Arkansas, ang nag-aaral magmaneho ay puwede lang magmaneho kasama ang drayber na may lisensiya na hindi bababa sa 21 taong gulang, para laging may may-karanasang adult na gagabay.","p":"Tama. Nagmamaneho ang nag-aaral kasama ang drayber na may lisensiya na 21 taong gulang o higit pa."},"ar":{"q":"في Arkansas، يجب على المراهق الذي يحمل رخصة المتعلم أن يقود مع سائق يحمل رخصة. كم يجب أن يكون عمر هذا السائق؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا في عمر يسمح له بشراء الكحول قانونيًا.","h2":"في Arkansas، لا يجوز للمتعلم أن يقود إلا مع سائق يحمل رخصة وعمره 21 سنة على الأقل، حتى يكون معه دائمًا شخص بالغ له خبرة يرشده.","p":"صحيح. المتعلم يقود مع سائق يحمل رخصة وعمره 21 سنة أو أكثر."},"ref":{"doc":"AR","page":3}},{"id":"ar-003","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, at what age can a teen get an intermediate license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes right after the learner's license years of 14 and 15.","h2":"In Arkansas, the intermediate license is for drivers who are 16 or 17, so a teen can get it at 16.","p":"Right. The intermediate license starts at age 16."},"es":{"q":"En Arkansas, ¿a qué edad puede un joven obtener la licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Viene justo después de los años de la licencia de aprendiz, 14 y 15.","h2":"En Arkansas, la licencia intermedia es para conductores de 16 o 17 años, así que un joven puede obtenerla a los 16.","p":"Correcto. La licencia intermedia empieza a los 16 años."},"zh":{"q":"在 Arkansas，青少年几岁可以拿到中级驾照（intermediate license）？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它紧接在学习驾照的 14 岁和 15 岁之后。","h2":"在 Arkansas，中级驾照是给 16 岁或 17 岁的司机的，所以青少年 16 岁就可以拿到。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Arkansas, thanh thiếu niên có thể lấy bằng lái trung cấp (intermediate license) ở tuổi nào?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Nó đến ngay sau những năm có giấy phép học lái, lúc 14 và 15 tuổi.","h2":"Ở Arkansas, bằng lái trung cấp dành cho người lái 16 hoặc 17 tuổi, vì vậy thanh thiếu niên có thể lấy bằng này lúc 16 tuổi.","p":"Đúng. Bằng lái trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Arkansas, sa anong edad puwedeng makakuha ang kabataan ng intermediate license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Kasunod ito ng mga taon ng learner's license, sa edad na 14 at 15.","h2":"Sa Arkansas, ang intermediate license ay para sa mga drayber na 16 o 17 taong gulang, kaya puwede itong makuha ng kabataan sa edad na 16.","p":"Tama. Ang intermediate license ay nagsisimula sa edad na 16."},"ar":{"q":"في Arkansas، في أي عمر يمكن للمراهق الحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"تأتي مباشرة بعد سنوات رخصة المتعلم في عمر 14 و15.","h2":"في Arkansas، الرخصة المتوسطة مخصصة للسائقين في عمر 16 أو 17 سنة، لذلك يمكن للمراهق الحصول عليها في عمر 16 سنة.","p":"صحيح. الرخصة المتوسطة تبدأ من عمر 16 سنة."},"ref":{"doc":"AR","page":3}},{"id":"ar-004","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, to get an intermediate license at 16, how long must a teen's driving record be free of a serious crash or serious traffic ticket?","o":["At least three months","At least six months","At least one year","At least two years"],"h1":"It is half of a year.","h2":"In Arkansas, a teen can get an intermediate license at 16 only if the driving record has no serious crash and no serious traffic ticket in the last six months.","p":"Right. The record must be clean for the last six months."},"es":{"q":"En Arkansas, para obtener la licencia intermedia a los 16 años, ¿cuánto tiempo debe estar el historial del joven sin un choque grave ni una multa de tránsito grave?","o":["Por lo menos tres meses","Por lo menos seis meses","Por lo menos un año","Por lo menos dos años"],"h1":"Es la mitad de un año.","h2":"En Arkansas, un joven puede obtener la licencia intermedia a los 16 años solo si su historial no tiene ningún choque grave ni ninguna multa de tránsito grave en los últimos seis meses.","p":"Correcto. El historial debe estar limpio durante los últimos seis meses."},"zh":{"q":"在 Arkansas，青少年想在 16 岁拿到中级驾照，驾驶记录必须多长时间没有严重车祸或严重交通罚单？","o":["至少三个月","至少六个月","至少一年","至少两年"],"h1":"这是半年。","h2":"在 Arkansas，青少年只有在过去六个月的驾驶记录里没有严重车祸、也没有严重交通罚单，才可以在 16 岁拿到中级驾照。","p":"对。过去六个月的记录必须是干净的。"},"vi":{"q":"Ở Arkansas, để được cấp bằng lái trung cấp lúc 16 tuổi, hồ sơ lái xe của thiếu niên phải không có tai nạn nghiêm trọng hay vé phạt giao thông nghiêm trọng trong bao lâu?","o":["Ít nhất ba tháng","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Arkansas, thiếu niên chỉ được cấp bằng lái trung cấp lúc 16 tuổi nếu hồ sơ lái xe không có tai nạn nghiêm trọng và không có vé phạt giao thông nghiêm trọng trong sáu tháng gần nhất.","p":"Đúng. Hồ sơ phải sạch trong sáu tháng gần nhất."},"tl":{"q":"Sa Arkansas, para makakuha ng intermediate license sa edad na 16, gaano katagal dapat walang malubhang banggaan o malubhang traffic ticket ang driving record ng kabataan?","o":["Hindi bababa sa tatlong buwan","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Ito ay kalahati ng isang taon.","h2":"Sa Arkansas, makakakuha lang ang kabataan ng intermediate license sa edad na 16 kung walang malubhang banggaan at walang malubhang traffic ticket ang driving record sa nakaraang anim na buwan.","p":"Tama. Dapat malinis ang record sa nakaraang anim na buwan."},"ar":{"q":"في Arkansas، للحصول على رخصة قيادة متوسطة (intermediate license) في سن 16، كم يجب أن يبقى سجل قيادة المراهق خاليًا من حادث خطير أو مخالفة مرورية خطيرة؟","o":["ثلاثة أشهر على الأقل","ستة أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"إنها نصف سنة.","h2":"في Arkansas، يمكن للمراهق أن يحصل على رخصة متوسطة في سن 16 فقط إذا كان سجل القيادة بلا حادث خطير وبلا مخالفة مرورية خطيرة في الأشهر الستة الأخيرة.","p":"صحيح. يجب أن يكون السجل نظيفًا في الأشهر الستة الأخيرة."},"ref":{"doc":"AR","page":null}},{"id":"ar-005","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what must a teen's driving record show to get an intermediate license?","o":["Two minor tickets at most in the past year","A completed online safety video","A signed letter from a teacher","No serious violations or at-fault crashes in the past six months"],"h1":"Think about a clean record for a recent period of time.","h2":"To get an Arkansas intermediate license, a teen must have no serious traffic violations and no at-fault crashes during the previous six months.","p":"Right. The record must be clean of serious violations and at-fault crashes for six months."},"es":{"q":"En Arkansas, ¿qué debe mostrar el historial de manejo de un joven para obtener la licencia intermedia?","o":["Como máximo dos multas menores en el último año","Un video de seguridad completado en línea","Una carta firmada por un maestro","Ninguna infracción grave ni choque con culpa en los últimos seis meses"],"h1":"Piense en un historial limpio durante un período reciente.","h2":"Para obtener la licencia intermedia en Arkansas, el joven no debe tener infracciones graves ni choques en los que tuvo la culpa durante los seis meses anteriores.","p":"Correcto. El historial debe estar libre de infracciones graves y choques con culpa por seis meses."},"zh":{"q":"在 Arkansas，青少年的驾驶记录必须是什么样，才能拿到中级驾照？","o":["过去一年最多两张小罚单","已看完一个网上安全视频","一封老师签字的信","过去六个月没有严重违规，也没有自己有责任的车祸"],"h1":"想一想最近一段时间的干净记录。","h2":"要拿到 Arkansas 的中级驾照，青少年在过去六个月里必须没有严重的交通违规，也没有自己有责任的车祸。","p":"对。六个月里记录不能有严重违规和自己有责任的车祸。"},"vi":{"q":"Ở Arkansas, hồ sơ lái xe của thanh thiếu niên phải như thế nào để lấy bằng lái trung cấp?","o":["Nhiều nhất hai vé phạt nhẹ trong năm qua","Đã xem xong một video an toàn trên mạng","Có thư ký tên của giáo viên","Không có vi phạm nghiêm trọng hay tai nạn do lỗi của mình trong sáu tháng qua"],"h1":"Hãy nghĩ đến một hồ sơ sạch trong một thời gian gần đây.","h2":"Để lấy bằng lái trung cấp ở Arkansas, thanh thiếu niên không được có vi phạm giao thông nghiêm trọng và không có tai nạn do lỗi của mình trong sáu tháng trước đó.","p":"Đúng. Hồ sơ phải không có vi phạm nghiêm trọng và tai nạn do lỗi của mình trong sáu tháng."},"tl":{"q":"Sa Arkansas, ano ang dapat makita sa driving record ng kabataan para makakuha ng intermediate license?","o":["Hindi hihigit sa dalawang maliit na tiket sa nakaraang taon","Natapos na online na video tungkol sa kaligtasan","Pirmadong sulat mula sa isang guro","Walang malubhang paglabag o banggaan na siya ang may kasalanan sa nakaraang anim na buwan"],"h1":"Isipin ang malinis na record sa isang kamakailang panahon.","h2":"Para makakuha ng intermediate license sa Arkansas, ang kabataan ay dapat walang malubhang paglabag sa trapiko at walang banggaan na siya ang may kasalanan sa nakaraang anim na buwan.","p":"Tama. Dapat malinis ang record sa malubhang paglabag at banggaan na siya ang may kasalanan sa loob ng anim na buwan."},"ar":{"q":"في Arkansas، ماذا يجب أن يُظهر سجل القيادة للمراهق حتى يحصل على الرخصة المتوسطة؟","o":["مخالفتان بسيطتان على الأكثر في السنة الماضية","مشاهدة فيديو سلامة على الإنترنت حتى النهاية","رسالة موقعة من معلم","لا مخالفات خطيرة ولا حوادث بسبب خطئه في الأشهر الستة الماضية"],"h1":"فكّر في سجل نظيف خلال فترة قريبة.","h2":"للحصول على الرخصة المتوسطة في Arkansas، يجب ألا يكون لدى المراهق أي مخالفات مرورية خطيرة ولا حوادث بسبب خطئه خلال الأشهر الستة السابقة.","p":"صحيح. يجب أن يكون السجل خاليًا من المخالفات الخطيرة والحوادث بسبب الخطأ لمدة ستة أشهر."},"ref":{"doc":"AR","page":3}},{"id":"ar-006","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, at what age can a driver apply for a regular, unrestricted license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is the age when most people finish high school.","h2":"In Arkansas, a driver can apply for a regular, unrestricted license at 18, as long as the driving record has been clean for the year before.","p":"Right. The unrestricted license comes at age 18."},"es":{"q":"En Arkansas, ¿a qué edad se puede solicitar la licencia regular sin restricciones?","o":["16 años","17 años","18 años","21 años"],"h1":"Es la edad en que la mayoría termina la escuela secundaria.","h2":"En Arkansas, se puede solicitar la licencia regular sin restricciones a los 18 años, siempre que el historial de manejo esté limpio durante el año anterior.","p":"Correcto. La licencia sin restricciones llega a los 18 años."},"zh":{"q":"在 Arkansas，司机几岁可以申请普通、没有限制的驾照？","o":["16 岁","17 岁","18 岁","21 岁"],"h1":"这是大多数人高中毕业的年龄。","h2":"在 Arkansas，司机 18 岁可以申请普通、没有限制的驾照，只要前一年的驾驶记录是干净的。","p":"对。没有限制的驾照从 18 岁开始。"},"vi":{"q":"Ở Arkansas, người lái xe có thể xin bằng lái thường, không hạn chế (unrestricted license) ở tuổi nào?","o":["16 tuổi","17 tuổi","18 tuổi","21 tuổi"],"h1":"Đó là tuổi mà phần lớn mọi người học xong trung học.","h2":"Ở Arkansas, người lái xe có thể xin bằng lái thường, không hạn chế lúc 18 tuổi, miễn là hồ sơ lái xe sạch trong năm trước đó.","p":"Đúng. Bằng lái không hạn chế đến lúc 18 tuổi."},"tl":{"q":"Sa Arkansas, sa anong edad puwedeng mag-apply ang drayber ng regular na lisensiya na walang limitasyon (unrestricted license)?","o":["16 taong gulang","17 taong gulang","18 taong gulang","21 taong gulang"],"h1":"Ito ang edad kung kailan karamihan ng tao ay tapos na sa high school.","h2":"Sa Arkansas, puwedeng mag-apply ang drayber ng regular na lisensiya na walang limitasyon sa edad na 18, basta malinis ang driving record sa nakaraang taon.","p":"Tama. Ang unrestricted license ay sa edad na 18."},"ar":{"q":"في Arkansas، في أي عمر يمكن للسائق أن يطلب رخصة عادية بلا قيود (unrestricted license)؟","o":["16 سنة","17 سنة","18 سنة","21 سنة"],"h1":"إنه العمر الذي ينهي فيه معظم الناس المدرسة الثانوية.","h2":"في Arkansas، يمكن للسائق أن يطلب رخصة عادية بلا قيود في عمر 18 سنة، بشرط أن يكون سجل القيادة نظيفًا في السنة السابقة.","p":"صحيح. الرخصة بلا قيود تأتي في عمر 18 سنة."},"ref":{"doc":"AR","page":4}},{"id":"ar-007","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what can let a 16- or 17-year-old get an unrestricted license before turning 18?","o":["Graduating from high school or earning a GED","Passing the written test a second time","Driving 100 hours with a parent","Buying a car in their own name"],"h1":"Think about finishing school early.","h2":"Arkansas lets a 16- or 17-year-old get an unrestricted license early in some cases, such as showing a high school diploma or a GED.","p":"Right. A high school diploma or GED can allow an early unrestricted license."},"es":{"q":"En Arkansas, ¿qué puede permitir que un joven de 16 o 17 años obtenga la licencia sin restricciones antes de cumplir 18?","o":["Graduarse de la secundaria u obtener el GED","Aprobar el examen escrito por segunda vez","Manejar 100 horas con un padre","Comprar un carro a su propio nombre"],"h1":"Piense en terminar la escuela antes de tiempo.","h2":"En algunos casos, Arkansas permite que un joven de 16 o 17 años obtenga la licencia sin restricciones antes, por ejemplo si presenta el diploma de secundaria o el GED.","p":"Correcto. El diploma de secundaria o el GED puede permitir la licencia sin restricciones antes de tiempo."},"zh":{"q":"在 Arkansas，什么可以让 16 岁或 17 岁的人在满 18 岁前拿到没有限制的驾照？","o":["高中毕业或拿到 GED","第二次考过笔试","和父母一起开车 100 小时","用自己的名字买车"],"h1":"想一想提早完成学业。","h2":"Arkansas 在某些情况下让 16 岁或 17 岁的人提早拿到没有限制的驾照，比如出示高中毕业证书或 GED。","p":"对。高中毕业证书或 GED 可以让你提早拿到没有限制的驾照。"},"vi":{"q":"Ở Arkansas, điều gì có thể giúp người 16 hoặc 17 tuổi lấy bằng lái không hạn chế trước 18 tuổi?","o":["Tốt nghiệp trung học hoặc có bằng GED","Thi viết đạt lần thứ hai","Lái xe 100 giờ cùng cha mẹ","Mua xe đứng tên mình"],"h1":"Hãy nghĩ đến việc học xong sớm.","h2":"Arkansas cho người 16 hoặc 17 tuổi lấy bằng lái không hạn chế sớm trong một số trường hợp, ví dụ khi có bằng tốt nghiệp trung học hoặc bằng GED.","p":"Đúng. Bằng tốt nghiệp trung học hoặc GED có thể cho phép lấy bằng lái không hạn chế sớm."},"tl":{"q":"Sa Arkansas, ano ang puwedeng magpahintulot sa 16 o 17 taong gulang na makakuha ng unrestricted license bago mag-18?","o":["Pagtatapos ng high school o pagkakaroon ng GED","Pagpasa sa written test sa ikalawang pagkakataon","Pagmamaneho nang 100 oras kasama ang magulang","Pagbili ng kotse sa sariling pangalan"],"h1":"Isipin ang maagang pagtatapos ng pag-aaral.","h2":"Sa Arkansas, puwedeng makakuha nang maaga ng unrestricted license ang 16 o 17 taong gulang sa ilang kaso, gaya ng pagpapakita ng high school diploma o GED.","p":"Tama. Ang high school diploma o GED ay puwedeng magbigay ng maagang unrestricted license."},"ar":{"q":"في Arkansas، ما الذي يمكن أن يسمح لمن عمره 16 أو 17 سنة بالحصول على رخصة بلا قيود قبل أن يبلغ 18؟","o":["التخرج من المدرسة الثانوية أو الحصول على شهادة GED","النجاح في الامتحان الكتابي مرة ثانية","القيادة 100 ساعة مع أحد الوالدين","شراء سيارة باسمه"],"h1":"فكّر في إنهاء الدراسة مبكرًا.","h2":"تسمح Arkansas لمن عمره 16 أو 17 سنة بالحصول على رخصة بلا قيود مبكرًا في بعض الحالات، مثل تقديم شهادة المدرسة الثانوية أو شهادة GED.","p":"صحيح. شهادة المدرسة الثانوية أو GED يمكن أن تسمح برخصة بلا قيود مبكرة."},"ref":{"doc":"AR","page":null}},{"id":"ar-008","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, during which hours may a driver with an intermediate license not drive, unless an exception applies?","o":["11 p.m. to 4 a.m.","9 p.m. to 6 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"An Arkansas intermediate license holder may not drive from 11 p.m. to 4 a.m., unless a licensed driver age 21 or older is along, or the trip is to or from work, a school or church activity, or an emergency.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 4 a.m."},"es":{"q":"En Arkansas, ¿en qué horario no puede manejar quien tiene licencia intermedia, salvo que aplique una excepción?","o":["De 11 p.m. a 4 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"Una persona con licencia intermedia en Arkansas no puede manejar de 11 p. m. a 4 a. m., a menos que la acompañe un conductor con licencia de 21 años o más, o que vaya o venga del trabajo, de una actividad escolar o de la iglesia, o por una emergencia.","p":"Correcto. Los conductores con licencia intermedia no manejan de 11 p.m. a 4 a.m."},"zh":{"q":"在 Arkansas，持中级驾照的司机在哪段时间不能开车（例外情况除外）？","o":["晚上 11 点到凌晨 4 点","晚上 9 点到早上 6 点","午夜到早上 6 点","晚上 10 点到早上 5 点"],"h1":"这个限制在午夜前一小时开始。","h2":"Arkansas 持中级驾照的人在晚上 11 点到凌晨 4 点不能开车，除非有一位 21 岁或以上、有驾照的司机同车，或者是去上班或下班、去学校或教会活动，或者是紧急情况。","p":"对。持中级驾照的司机晚上 11 点到凌晨 4 点不上路。"},"vi":{"q":"Ở Arkansas, người có bằng lái trung cấp không được lái xe trong những giờ nào, trừ khi có ngoại lệ?","o":["11 giờ tối đến 4 giờ sáng","9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ trước nửa đêm.","h2":"Người có bằng lái trung cấp ở Arkansas không được lái xe từ 11 giờ tối đến 4 giờ sáng, trừ khi có người có bằng lái từ 21 tuổi trở lên đi cùng, hoặc chuyến đi là đến hay về từ chỗ làm, hoạt động của trường hoặc nhà thờ, hoặc trường hợp khẩn cấp.","p":"Đúng. Người có bằng lái trung cấp không lái xe từ 11 giờ tối đến 4 giờ sáng."},"tl":{"q":"Sa Arkansas, sa anong mga oras hindi puwedeng magmaneho ang drayber na may intermediate license, maliban kung may exception?","o":["11 p.m. hanggang 4 a.m.","9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon isang oras bago maghatinggabi.","h2":"Ang may intermediate license sa Arkansas ay hindi puwedeng magmaneho mula 11 p.m. hanggang 4 a.m., maliban kung kasama ang drayber na may lisensiya na 21 taong gulang o higit pa, o ang biyahe ay papunta o galing sa trabaho, gawain ng paaralan o simbahan, o emergency.","p":"Tama. Hindi nagmamaneho ang may intermediate license mula 11 p.m. hanggang 4 a.m."},"ar":{"q":"في Arkansas، في أي ساعات لا يجوز لصاحب الرخصة المتوسطة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 11 مساءً إلى 4 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا"],"h1":"يبدأ المنع قبل منتصف الليل بساعة واحدة.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Arkansas أن يقود من 11 مساءً إلى 4 صباحًا، إلا إذا كان معه سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو كانت الرحلة إلى العمل أو منه، أو إلى نشاط مدرسي أو كنسي أو منه، أو في حالة طوارئ.","p":"صحيح. أصحاب الرخصة المتوسطة لا يقودون من 11 مساءً إلى 4 صباحًا."},"ref":{"doc":"AR","page":4}},{"id":"ar-009","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, how many unrelated passengers under 18 may a driver with an intermediate license carry, when no adult driver is along?","o":["None at all","Two","Three","One"],"h1":"Family members do not count toward this limit.","h2":"An Arkansas intermediate license holder may carry only one unrelated passenger under 18, unless a licensed driver age 21 or older sits in the front seat.","p":"Right. Only one unrelated passenger under 18 is allowed."},"es":{"q":"En Arkansas, ¿cuántos pasajeros menores de 18 años, que no sean familiares, puede llevar un conductor con licencia intermedia si no lo acompaña un adulto con licencia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Los familiares no cuentan para este límite.","h2":"Una persona con licencia intermedia en Arkansas puede llevar solo un pasajero menor de 18 años que no sea familiar, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo se permite un pasajero menor de 18 años que no sea familiar."},"zh":{"q":"在 Arkansas，没有成年司机同车时，持中级驾照的司机可以载多少位 18 岁以下、不是家人的乘客？","o":["一位都不行","两位","三位","一位"],"h1":"家人不算在这个限制里。","h2":"Arkansas 持中级驾照的人只能载一位 18 岁以下、不是家人的乘客，除非有一位 21 岁或以上、有驾照的司机坐在前排。","p":"对。只能载一位 18 岁以下、不是家人的乘客。"},"vi":{"q":"Ở Arkansas, khi không có người lớn có bằng lái đi cùng, người có bằng lái trung cấp được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Người trong gia đình không tính vào giới hạn này.","h2":"Người có bằng lái trung cấp ở Arkansas chỉ được chở một hành khách dưới 18 tuổi không phải người nhà, trừ khi có người có bằng lái từ 21 tuổi trở lên ngồi ghế trước.","p":"Đúng. Chỉ được chở một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Arkansas, ilang pasaherong wala pang 18 na hindi kamag-anak ang puwedeng isakay ng drayber na may intermediate license, kapag walang kasamang adult na drayber?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Hindi kasama sa bilang na ito ang mga kapamilya.","h2":"Ang may intermediate license sa Arkansas ay puwede lang magsakay ng isang pasaherong wala pang 18 na hindi kamag-anak, maliban kung may drayber na may lisensiya na 21 taong gulang o higit pa na nakaupo sa harap.","p":"Tama. Isang pasaherong wala pang 18 na hindi kamag-anak lang ang puwede."},"ar":{"q":"في Arkansas، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن ينقل صاحب الرخصة المتوسطة، عندما لا يكون معه سائق بالغ؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"أفراد العائلة لا يُحسبون في هذا الحد.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Arkansas أن ينقل إلا راكبًا واحدًا عمره أقل من 18 سنة وليس من العائلة، إلا إذا جلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر.","p":"صحيح. يُسمح براكب واحد فقط عمره أقل من 18 سنة وليس من العائلة."},"ref":{"doc":"AR","page":4}},{"id":"ar-010","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, what is the rule on cell phones for drivers under 18?","o":["They may use a phone only with a hands-free device","They may not use a phone at all, except in an emergency","They may text only at a red light","They may talk only on highways"],"h1":"For the youngest drivers, even hands-free is not allowed.","h2":"In Arkansas, drivers under 18 may not use a cell phone while driving, even hands-free, except in an emergency.","p":"Right. Drivers under 18 may not use a phone, except in an emergency."},"es":{"q":"En Arkansas, ¿cuál es la regla del celular para conductores menores de 18 años?","o":["Pueden usar el teléfono solo con manos libres","No pueden usar el teléfono, salvo en una emergencia","Pueden enviar mensajes solo en un semáforo en rojo","Pueden hablar solo en las autopistas"],"h1":"Para los conductores más jóvenes, ni siquiera se permite el manos libres.","h2":"En Arkansas, los conductores menores de 18 años no pueden usar el celular mientras manejan, ni siquiera con manos libres, salvo en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, salvo en una emergencia."},"zh":{"q":"在 Arkansas，对 18 岁以下的司机，手机的规定是什么？","o":["只能用免持设备打电话","完全不能用手机，紧急情况除外","只能在红灯时发短信","只能在公路上打电话"],"h1":"对最年轻的司机来说，连免持都不允许。","h2":"在 Arkansas，18 岁以下的司机开车时不能用手机，即使是免持也不行，紧急情况除外。","p":"对。18 岁以下的司机不能用手机，紧急情况除外。"},"vi":{"q":"Ở Arkansas, quy định về điện thoại di động cho người lái xe dưới 18 tuổi là gì?","o":["Chỉ được dùng điện thoại với thiết bị rảnh tay","Hoàn toàn không được dùng điện thoại, trừ khi khẩn cấp","Chỉ được nhắn tin khi đèn đỏ","Chỉ được nói chuyện trên xa lộ"],"h1":"Với người lái trẻ nhất, ngay cả rảnh tay cũng không được.","h2":"Ở Arkansas, người lái xe dưới 18 tuổi không được dùng điện thoại di động khi lái xe, kể cả rảnh tay, trừ khi khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, trừ khi khẩn cấp."},"tl":{"q":"Sa Arkansas, ano ang patakaran sa cellphone para sa mga drayber na wala pang 18?","o":["Puwede lang gumamit ng cellphone gamit ang hands-free na device","Hindi talaga puwedeng gumamit ng cellphone, maliban sa emergency","Puwede lang mag-text kapag pula ang ilaw","Puwede lang makipag-usap sa highway"],"h1":"Para sa pinakabatang drayber, kahit hands-free ay hindi puwede.","h2":"Sa Arkansas, ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng cellphone habang nagmamaneho, kahit hands-free, maliban sa emergency.","p":"Tama. Ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng cellphone, maliban sa emergency."},"ar":{"q":"في Arkansas، ما هي القاعدة حول الهاتف المحمول للسائقين الذين عمرهم أقل من 18 سنة؟","o":["يمكنهم استخدام الهاتف فقط مع جهاز بدون استخدام اليدين","لا يجوز لهم استخدام الهاتف أبدًا، إلا في حالة طوارئ","يمكنهم كتابة الرسائل فقط عند الإشارة الحمراء","يمكنهم التحدث فقط على الطرق السريعة"],"h1":"لأصغر السائقين، حتى الاستخدام بدون اليدين غير مسموح.","h2":"في Arkansas، لا يجوز للسائقين الذين عمرهم أقل من 18 سنة استخدام الهاتف المحمول أثناء القيادة، حتى بدون استخدام اليدين، إلا في حالة طوارئ.","p":"صحيح. السائقون الذين عمرهم أقل من 18 سنة لا يستخدمون الهاتف، إلا في حالة طوارئ."},"ref":{"doc":"AR","page":46}},{"id":"ar-011","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, how may a driver who is 18 to 20 years old talk on a phone while driving?","o":["Only while holding the phone to the ear","Only on roads with no traffic lights","Only with a hands-free device","Only when a passenger holds the phone"],"h1":"The driver's hands must stay free.","h2":"In Arkansas, drivers from 18 to 20 may not use a handheld phone while driving, but they may talk with a hands-free device.","p":"Right. Drivers 18 to 20 may talk only hands-free."},"es":{"q":"En Arkansas, ¿cómo puede hablar por teléfono mientras maneja un conductor de 18 a 20 años?","o":["Solo sosteniendo el teléfono en el oído","Solo en calles sin semáforos","Solo con un dispositivo de manos libres","Solo si un pasajero sostiene el teléfono"],"h1":"Las manos del conductor deben quedar libres.","h2":"En Arkansas, los conductores de 18 a 20 años no pueden usar el teléfono en la mano mientras manejan, pero pueden hablar con un dispositivo de manos libres.","p":"Correcto. Los conductores de 18 a 20 años solo pueden hablar con manos libres."},"zh":{"q":"在 Arkansas，18 到 20 岁的司机开车时可以怎样打电话？","o":["只能把手机拿在耳边","只能在没有红绿灯的路上","只能用免持设备","只能让乘客拿着手机"],"h1":"司机的手必须空着。","h2":"在 Arkansas，18 到 20 岁的司机开车时不能用手持电话，但可以用免持设备打电话。","p":"对。18 到 20 岁的司机只能用免持打电话。"},"vi":{"q":"Ở Arkansas, người lái xe từ 18 đến 20 tuổi được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Chỉ khi cầm điện thoại áp vào tai","Chỉ trên đường không có đèn giao thông","Chỉ với thiết bị rảnh tay","Chỉ khi hành khách cầm điện thoại"],"h1":"Tay của người lái phải được rảnh.","h2":"Ở Arkansas, người lái xe từ 18 đến 20 tuổi không được cầm điện thoại trên tay khi lái xe, nhưng được nói chuyện bằng thiết bị rảnh tay.","p":"Đúng. Người lái từ 18 đến 20 tuổi chỉ được nói chuyện rảnh tay."},"tl":{"q":"Sa Arkansas, paano puwedeng makipag-usap sa cellphone habang nagmamaneho ang drayber na 18 hanggang 20 taong gulang?","o":["Habang hawak lang ang cellphone sa tainga","Sa mga daan lang na walang traffic light","Gamit lang ang hands-free na device","Kapag pasahero lang ang may hawak ng cellphone"],"h1":"Dapat malaya ang mga kamay ng drayber.","h2":"Sa Arkansas, ang mga drayber na 18 hanggang 20 taong gulang ay hindi puwedeng humawak ng cellphone habang nagmamaneho, pero puwede silang makipag-usap gamit ang hands-free na device.","p":"Tama. Ang mga drayber na 18 hanggang 20 ay puwede lang makipag-usap nang hands-free."},"ar":{"q":"في Arkansas، كيف يمكن للسائق الذي عمره من 18 إلى 20 سنة أن يتحدث في الهاتف أثناء القيادة؟","o":["فقط وهو يمسك الهاتف على أذنه","فقط على طرق بلا إشارات مرور","فقط مع جهاز بدون استخدام اليدين","فقط عندما يمسك راكب الهاتف"],"h1":"يجب أن تبقى يدا السائق حرتين.","h2":"في Arkansas، لا يجوز للسائقين من 18 إلى 20 سنة أن يمسكوا الهاتف بأيديهم أثناء القيادة، لكن يمكنهم التحدث بجهاز بدون استخدام اليدين.","p":"صحيح. السائقون من 18 إلى 20 سنة يتحدثون فقط بدون استخدام اليدين."},"ref":{"doc":"AR","page":4}},{"id":"ar-012","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, which drivers are banned from texting while driving?","o":["Drivers of every age","Only drivers under 18","Only drivers under 21","Only commercial truck drivers"],"h1":"This rule does not depend on age.","h2":"Arkansas does not allow any driver, of any age, to send or read text messages while driving.","p":"Right. No driver of any age may text while driving in Arkansas."},"es":{"q":"En Arkansas, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["A los conductores de todas las edades","Solo a los menores de 18 años","Solo a los menores de 21 años","Solo a los camioneros comerciales"],"h1":"Esta regla no depende de la edad.","h2":"Arkansas no permite que ningún conductor, de ninguna edad, envíe o lea mensajes de texto mientras maneja.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Arkansas."},"zh":{"q":"在 Arkansas，哪些司机开车时禁止发短信？","o":["所有年龄的司机","只有 18 岁以下的司机","只有 21 岁以下的司机","只有商业卡车司机"],"h1":"这个规定和年龄无关。","h2":"Arkansas 不允许任何年龄的司机开车时发或看短信。","p":"对。在 Arkansas，任何年龄的司机开车时都不能发短信。"},"vi":{"q":"Ở Arkansas, những người lái xe nào bị cấm nhắn tin khi lái xe?","o":["Người lái xe ở mọi lứa tuổi","Chỉ người lái dưới 18 tuổi","Chỉ người lái dưới 21 tuổi","Chỉ tài xế xe tải thương mại"],"h1":"Quy định này không phụ thuộc vào tuổi.","h2":"Arkansas không cho phép bất kỳ người lái xe nào, ở bất kỳ tuổi nào, gửi hoặc đọc tin nhắn khi lái xe.","p":"Đúng. Ở Arkansas, không người lái nào ở bất kỳ tuổi nào được nhắn tin khi lái xe."},"tl":{"q":"Sa Arkansas, sinong mga drayber ang bawal mag-text habang nagmamaneho?","o":["Mga drayber sa lahat ng edad","Mga drayber lang na wala pang 18","Mga drayber lang na wala pang 21","Mga drayber lang ng komersiyal na trak"],"h1":"Hindi nakadepende sa edad ang patakarang ito.","h2":"Sa Arkansas, walang drayber, sa anumang edad, ang puwedeng magpadala o magbasa ng text message habang nagmamaneho.","p":"Tama. Sa Arkansas, walang drayber sa anumang edad ang puwedeng mag-text habang nagmamaneho."},"ar":{"q":"في Arkansas، أي السائقين ممنوعون من كتابة الرسائل النصية أثناء القيادة؟","o":["السائقون من كل الأعمار","السائقون الذين عمرهم أقل من 18 سنة فقط","السائقون الذين عمرهم أقل من 21 سنة فقط","سائقو الشاحنات التجارية فقط"],"h1":"هذه القاعدة لا تعتمد على العمر.","h2":"لا تسمح Arkansas لأي سائق، من أي عمر، بإرسال الرسائل النصية أو قراءتها أثناء القيادة.","p":"صحيح. في Arkansas لا يجوز لأي سائق من أي عمر أن يكتب الرسائل أثناء القيادة."},"ref":{"doc":"AR","page":4}},{"id":"ar-013","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, where must even an adult driver use only a hands-free device to talk on the phone?","o":["On any road after dark","In any parking lot","On any road with two lanes","In a school zone, or a work zone when workers are present"],"h1":"Think of places where children or road workers may be near.","h2":"In Arkansas, even an adult driver may not hold a phone while passing a school zone during school hours when children are outside, or while driving in a highway work zone when workers are present.","p":"Right. In school zones and active work zones, calls must be hands-free."},"es":{"q":"En Arkansas, ¿dónde debe incluso un conductor adulto usar solo manos libres para hablar por teléfono?","o":["En cualquier calle de noche","En cualquier estacionamiento","En cualquier carretera de dos carriles","En una zona escolar, o en una zona de obras cuando hay trabajadores"],"h1":"Piense en lugares donde puede haber niños o trabajadores cerca.","h2":"En Arkansas, incluso un conductor adulto no puede sostener el teléfono al pasar por una zona escolar en horario de clases cuando hay niños afuera, ni al manejar en una zona de obras en la carretera cuando hay trabajadores.","p":"Correcto. En zonas escolares y zonas de obras activas, las llamadas deben ser con manos libres."},"zh":{"q":"在 Arkansas，即使是成年司机，在哪里打电话也只能用免提设备？","o":["天黑后的任何道路上","任何停车场里","任何双车道的道路上","在学校区，或者有工人在场的施工区"],"h1":"想一想孩子或道路工人可能在附近的地方。","h2":"在 Arkansas，即使是成年司机，在上学时间有孩子在外面时经过学校区，或者在有工人在场的公路施工区开车时，也不可以用手拿着电话。","p":"对。在学校区和有工人的施工区，打电话必须用免提。"},"vi":{"q":"Ở Arkansas, ở đâu thì ngay cả tài xế người lớn cũng chỉ được dùng thiết bị rảnh tay để nói điện thoại?","o":["Trên bất kỳ con đường nào sau khi trời tối","Trong bất kỳ bãi đậu xe nào","Trên bất kỳ con đường nào có hai làn xe","Trong khu vực trường học, hoặc khu vực công trường khi có công nhân"],"h1":"Hãy nghĩ đến những nơi có thể có trẻ em hoặc công nhân làm đường ở gần.","h2":"Ở Arkansas, ngay cả tài xế người lớn cũng không được cầm điện thoại khi đi qua khu vực trường học trong giờ học lúc có trẻ em ở bên ngoài, hoặc khi lái trong khu vực công trường trên xa lộ khi có công nhân.","p":"Đúng. Trong khu vực trường học và khu vực công trường đang có công nhân, phải gọi điện bằng thiết bị rảnh tay."},"tl":{"q":"Sa Arkansas, saan dapat gumamit ng hands-free device lang kahit ang adult na driver para makipag-usap sa telepono?","o":["Sa kahit anong kalsada pagkatapos dumilim","Sa kahit anong parking lot","Sa kahit anong kalsada na may dalawang lane","Sa school zone, o sa work zone kapag may mga trabahador"],"h1":"Isipin ang mga lugar kung saan maaaring malapit ang mga bata o mga trabahador sa kalsada.","h2":"Sa Arkansas, kahit ang adult na driver ay hindi puwedeng humawak ng telepono habang dumadaan sa school zone sa oras ng klase kapag may mga bata sa labas, o habang nagmamaneho sa highway work zone kapag may mga trabahador.","p":"Tama. Sa mga school zone at aktibong work zone, dapat hands-free ang tawag."},"ar":{"q":"في Arkansas، أين يجب حتى على السائق البالغ أن يستخدم جهازًا بدون استخدام اليدين فقط للتحدث في الهاتف؟","o":["على أي طريق بعد حلول الظلام","في أي موقف سيارات","على أي طريق فيه مساران","في منطقة مدرسة، أو في منطقة عمل عندما يكون العمال موجودين"],"h1":"فكّر في الأماكن التي قد يكون فيها أطفال أو عمال طرق قريبين.","h2":"في Arkansas، لا يجوز حتى للسائق البالغ أن يمسك الهاتف بيده أثناء المرور في منطقة مدرسة خلال ساعات الدراسة عندما يكون الأطفال في الخارج، أو أثناء القيادة في منطقة عمل على الطريق السريع عندما يكون العمال موجودين.","p":"صحيح. في مناطق المدارس ومناطق العمل النشطة، يجب أن تكون المكالمات بدون استخدام اليدين."},"ref":{"doc":"AR","page":null}},{"id":"ar-014","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, a driver under 21 is considered under the influence at what blood alcohol level?","o":["0.00 percent","0.02 percent or higher","0.05 percent or higher","0.08 percent or higher"],"h1":"It is far lower than the limit for adults.","h2":"In Arkansas, a driver under 21 with a blood alcohol level of 0.02 percent or higher can be charged with underage DUI.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 años está bajo la influencia?","o":["0.00 por ciento","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Arkansas, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más puede ser acusado de manejar bajo la influencia.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Arkansas，21 岁以下的司机血液酒精浓度达到多少，就算酒后驾驶？","o":["0.00%","0.02% 或更高","0.05% 或更高","0.08% 或更高"],"h1":"它比成年人的限制低很多。","h2":"在 Arkansas，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就可能被控未成年酒后驾驶（underage DUI）。","p":"对。21 岁以下的司机，限制是 0.02%。"},"vi":{"q":"Ở Arkansas, người lái xe dưới 21 tuổi bị coi là bị ảnh hưởng bởi rượu ở nồng độ cồn trong máu bao nhiêu?","o":["0.00 phần trăm","0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Arkansas, người lái xe dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên có thể bị buộc tội lái xe say rượu khi chưa đủ tuổi (underage DUI).","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Arkansas, sa anong blood alcohol level itinuturing na lasing ang drayber na wala pang 21?","o":["0.00 porsiyento","0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa mga adult.","h2":"Sa Arkansas, ang drayber na wala pang 21 na may blood alcohol level na 0.02 porsiyento o higit pa ay puwedeng kasuhan ng underage DUI.","p":"Tama. Para sa mga drayber na wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Arkansas، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره أقل من 21 سنة تحت تأثير الكحول؟","o":["0.00 بالمئة","0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في Arkansas، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر يمكن أن يُتهم بالقيادة تحت تأثير الكحول لمن هم دون السن (underage DUI).","p":"صحيح. للسائقين الذين عمرهم أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"AR","page":75}},{"id":"ar-015","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, at what blood alcohol level can a driver 21 or older be charged with DWI?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is the same limit most states use for adults.","h2":"In Arkansas, a driver 21 or older with a blood alcohol level of 0.08 percent or higher can be charged with driving while intoxicated.","p":"Right. For adults, the limit is 0.08 percent."},"es":{"q":"En Arkansas, ¿con qué nivel de alcohol en la sangre se puede acusar de DWI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es el mismo límite que usa la mayoría de los estados para adultos.","h2":"En Arkansas, un conductor de 21 años o más con un nivel de alcohol en la sangre de 0.08 por ciento o más puede ser acusado de manejar en estado de ebriedad.","p":"Correcto. Para los adultos, el límite es 0.08 por ciento."},"zh":{"q":"在 Arkansas，21 岁或以上的司机血液酒精浓度达到多少，可能被控 DWI（醉酒驾驶）？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"它和大多数州对成年人用的限制一样。","h2":"在 Arkansas，21 岁或以上的司机血液酒精浓度达到 0.08% 或更高，就可能被控醉酒驾驶。","p":"对。成年人的限制是 0.08%。"},"vi":{"q":"Ở Arkansas, người lái xe từ 21 tuổi trở lên có thể bị buộc tội DWI ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Đó là giới hạn giống phần lớn các tiểu bang dùng cho người lớn.","h2":"Ở Arkansas, người lái xe từ 21 tuổi trở lên có nồng độ cồn trong máu từ 0.08 phần trăm trở lên có thể bị buộc tội lái xe khi say (DWI).","p":"Đúng. Với người lớn, giới hạn là 0.08 phần trăm."},"tl":{"q":"Sa Arkansas, sa anong blood alcohol level puwedeng kasuhan ng DWI ang drayber na 21 taong gulang o higit pa?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Ito ang parehong limitasyon na ginagamit ng karamihan ng estado para sa mga adult.","h2":"Sa Arkansas, ang drayber na 21 taong gulang o higit pa na may blood alcohol level na 0.08 porsiyento o higit pa ay puwedeng kasuhan ng pagmamaneho nang lasing (DWI).","p":"Tama. Para sa mga adult, ang limitasyon ay 0.08 porsiyento."},"ar":{"q":"في Arkansas، عند أي نسبة كحول في الدم يمكن أن يُتهم السائق الذي عمره 21 سنة أو أكثر بـ DWI؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"إنه نفس الحد الذي تستخدمه معظم الولايات للبالغين.","h2":"في Arkansas، السائق الذي عمره 21 سنة أو أكثر ونسبة الكحول في دمه 0.08 بالمئة أو أكثر يمكن أن يُتهم بالقيادة في حالة سُكر (DWI).","p":"صحيح. للبالغين، الحد هو 0.08 بالمئة."},"ref":{"doc":"AR","page":74}},{"id":"ar-016","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, what is the highest posted speed limit for cars on rural interstates?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"It is higher than the limit for trucks on the same road.","h2":"Arkansas allows cars to drive up to 75 mph on rural interstates where it is posted, while trucks are limited to 70 mph.","p":"Right. Cars may go up to 75 mph on posted rural interstates."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad más alto para carros en las autopistas interestatales rurales?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Es más alto que el límite para camiones en la misma vía.","h2":"Arkansas permite que los carros vayan hasta 75 mph en las autopistas interestatales rurales donde está señalizado, mientras que los camiones tienen un límite de 70 mph.","p":"Correcto. Los carros pueden ir hasta 75 mph en las interestatales rurales señalizadas."},"zh":{"q":"在 Arkansas，乡村州际公路上小汽车的最高标示限速是多少？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"它比同一条路上卡车的限速高。","h2":"在有标示的乡村州际公路上，Arkansas 允许小汽车最高开到 75 mph，而卡车限速是 70 mph。","p":"对。在有标示的乡村州际公路上，小汽车最高可以开 75 mph。"},"vi":{"q":"Ở Arkansas, tốc độ tối đa được ghi trên biển cho xe hơi trên xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Nó cao hơn giới hạn cho xe tải trên cùng con đường.","h2":"Arkansas cho phép xe hơi chạy đến 75 mph trên xa lộ liên bang ở vùng nông thôn nơi có biển ghi như vậy, còn xe tải bị giới hạn ở 70 mph.","p":"Đúng. Xe hơi được chạy đến 75 mph trên xa lộ liên bang vùng nông thôn có biển ghi."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na nakapaskil na speed limit para sa mga kotse sa rural interstate?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Mas mataas ito kaysa sa limitasyon para sa mga trak sa parehong daan.","h2":"Pinapayagan ng Arkansas ang mga kotse na tumakbo hanggang 75 mph sa rural interstate kung saan ito nakapaskil, habang ang mga trak ay limitado sa 70 mph.","p":"Tama. Puwedeng tumakbo ang mga kotse hanggang 75 mph sa rural interstate na may nakapaskil."},"ar":{"q":"في Arkansas، ما هو أعلى حد سرعة مكتوب على اللافتات للسيارات على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"إنه أعلى من حد السرعة للشاحنات على نفس الطريق.","h2":"تسمح Arkansas للسيارات بالسير حتى 75 mph على الطرق السريعة بين الولايات في المناطق الريفية حيث يكون ذلك مكتوبًا على اللافتات، بينما حد الشاحنات هو 70 mph.","p":"صحيح. يمكن للسيارات السير حتى 75 mph على الطرق السريعة الريفية المكتوب عليها ذلك."},"ref":{"doc":"AR","page":null}},{"id":"ar-017","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, what is the highest speed limit for large trucks on rural interstates?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"It is 5 mph lower than the top limit for cars.","h2":"On Arkansas rural interstates, large trucks are limited to 70 mph, which is 5 mph less than the 75 mph allowed for cars.","p":"Right. Trucks are limited to 70 mph on rural interstates."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad más alto para camiones grandes en las interestatales rurales?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Es 5 mph menos que el límite más alto para carros.","h2":"En las interestatales rurales de Arkansas, los camiones grandes tienen un límite de 70 mph, que es 5 mph menos que las 75 mph permitidas para carros.","p":"Correcto. Los camiones tienen un límite de 70 mph en las interestatales rurales."},"zh":{"q":"在 Arkansas，乡村州际公路上大卡车的最高限速是多少？","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"它比小汽车的最高限速低 5 mph。","h2":"在 Arkansas 的乡村州际公路上，大卡车限速是 70 mph，比小汽车允许的 75 mph 低 5 mph。","p":"对。在乡村州际公路上，卡车限速是 70 mph。"},"vi":{"q":"Ở Arkansas, tốc độ tối đa cho xe tải lớn trên xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Nó thấp hơn 5 mph so với giới hạn cao nhất cho xe hơi.","h2":"Trên xa lộ liên bang vùng nông thôn ở Arkansas, xe tải lớn bị giới hạn ở 70 mph, tức là thấp hơn 5 mph so với 75 mph cho xe hơi.","p":"Đúng. Xe tải bị giới hạn ở 70 mph trên xa lộ liên bang vùng nông thôn."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na speed limit para sa malalaking trak sa rural interstate?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa pinakamataas na limitasyon para sa mga kotse.","h2":"Sa rural interstate ng Arkansas, ang malalaking trak ay limitado sa 70 mph, na 5 mph na mas mababa kaysa sa 75 mph na pinapayagan sa mga kotse.","p":"Tama. Limitado sa 70 mph ang mga trak sa rural interstate."},"ar":{"q":"في Arkansas، ما هو أعلى حد سرعة للشاحنات الكبيرة على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"إنه أقل بـ 5 mph من أعلى حد للسيارات.","h2":"على الطرق السريعة الريفية بين الولايات في Arkansas، حد الشاحنات الكبيرة هو 70 mph، أي أقل بـ 5 mph من 75 mph المسموح بها للسيارات.","p":"صحيح. حد الشاحنات هو 70 mph على الطرق السريعة الريفية."},"ref":{"doc":"AR","page":null}},{"id":"ar-018","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, the move-over law covers more than police cars and ambulances. Which other stopped vehicles does it cover?","o":["Any parked car with its hood open","Only city buses at a bus stop","Utility trucks and tow trucks with flashing lights","Only delivery vans with hazard lights"],"h1":"Think of work vehicles that stop on the side of the road.","h2":"Arkansas's move-over law also covers stopped utility vehicles, tow trucks and highway department vehicles that show flashing lights.","p":"Right. Utility trucks and tow trucks with flashing lights are covered."},"es":{"q":"En Arkansas, la ley de moverse de carril cubre más que patrullas y ambulancias. ¿Qué otros vehículos detenidos cubre?","o":["Cualquier carro estacionado con el capó abierto","Solo autobuses urbanos en la parada","Camiones de servicios públicos y grúas con luces intermitentes","Solo camionetas de reparto con luces de emergencia"],"h1":"Piense en vehículos de trabajo que se detienen al lado de la carretera.","h2":"La ley de Arkansas también cubre vehículos de servicios públicos, grúas y vehículos del departamento de carreteras que están detenidos con luces intermitentes.","p":"Correcto. Se incluyen los camiones de servicios públicos y las grúas con luces intermitentes."},"zh":{"q":"在 Arkansas，move-over 法不只保护警车和救护车。它还保护哪些停着的车辆？","o":["任何打开引擎盖停着的车","只有在公车站的市区公车","车灯在闪的公用事业车和拖车","只有开着双闪灯的送货车"],"h1":"想一想停在路边的工作车辆。","h2":"Arkansas 的 move-over 法也保护车灯在闪、停着的公用事业车、拖车和公路部门的车辆。","p":"对。车灯在闪的公用事业车和拖车也受保护。"},"vi":{"q":"Ở Arkansas, luật tránh sang làn khác (move-over law) không chỉ áp dụng cho xe cảnh sát và xe cứu thương. Luật này còn áp dụng cho những xe đang dừng nào khác?","o":["Bất kỳ xe đậu nào đang mở nắp capô","Chỉ xe buýt thành phố ở trạm xe buýt","Xe tải tiện ích và xe kéo có đèn nhấp nháy","Chỉ xe giao hàng có bật đèn khẩn cấp"],"h1":"Hãy nghĩ đến các xe làm việc dừng bên lề đường.","h2":"Luật tránh sang làn khác của Arkansas cũng áp dụng cho xe tiện ích, xe kéo và xe của sở đường bộ đang dừng và có đèn nhấp nháy.","p":"Đúng. Xe tải tiện ích và xe kéo có đèn nhấp nháy cũng được luật bảo vệ."},"tl":{"q":"Sa Arkansas, ang move-over law ay hindi lang para sa mga sasakyan ng pulis at ambulansiya. Anong iba pang nakahintong sasakyan ang sakop nito?","o":["Anumang nakaparadang kotse na bukas ang hood","Mga city bus lang sa bus stop","Mga utility truck at tow truck na may kumikislap na ilaw","Mga delivery van lang na naka-hazard light"],"h1":"Isipin ang mga sasakyang pantrabaho na humihinto sa gilid ng daan.","h2":"Sakop din ng move-over law ng Arkansas ang mga nakahintong utility vehicle, tow truck at sasakyan ng highway department na may kumikislap na ilaw.","p":"Tama. Sakop ang mga utility truck at tow truck na may kumikislap na ilaw."},"ar":{"q":"في Arkansas، قانون الابتعاد (move-over law) لا يشمل سيارات الشرطة والإسعاف فقط. ما هي المركبات المتوقفة الأخرى التي يشملها؟","o":["أي سيارة متوقفة غطاء محركها مفتوح","حافلات المدينة فقط عند محطة الحافلات","شاحنات المرافق وشاحنات السحب التي لها أضواء وامضة","شاحنات التوصيل فقط التي تشغّل أضواء التحذير"],"h1":"فكّر في مركبات العمل التي تتوقف على جانب الطريق.","h2":"يشمل قانون الابتعاد في Arkansas أيضًا مركبات المرافق وشاحنات السحب ومركبات دائرة الطرق المتوقفة التي تُظهر أضواء وامضة.","p":"صحيح. شاحنات المرافق وشاحنات السحب التي لها أضواء وامضة مشمولة."},"ref":{"doc":"AR","page":21}},{"id":"ar-019","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, you approach a stopped emergency vehicle with flashing lights, but you cannot safely move to another lane. What must you do?","o":["Keep your speed and pass quickly","Slow down and pass with caution","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under the Arkansas move-over law, if you cannot safely move away from the stopped vehicle, you must slow down and pass with caution.","p":"Right. When you cannot move over, you slow down and use caution."},"es":{"q":"En Arkansas, usted se acerca a un vehículo de emergencia detenido con luces intermitentes, pero no puede cambiarse de carril con seguridad. ¿Qué debe hacer?","o":["Mantener la velocidad y pasar rápido","Reducir la velocidad y pasar con precaución","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Arkansas, si usted no puede alejarse con seguridad del vehículo detenido, debe reducir la velocidad y pasar con precaución.","p":"Correcto. Si no puede cambiarse de carril, reduce la velocidad y maneja con cuidado."},"zh":{"q":"在 Arkansas，你接近一辆车灯在闪的停着的急救车辆，但你无法安全地换到另一条车道。你必须怎么做？","o":["保持速度，快点开过去","减速，小心地开过去","在你的车道停车，直到它离开","按喇叭提醒工作人员"],"h1":"如果你不能拉开距离，就降低速度。","h2":"根据 Arkansas 的 move-over 法，如果你无法安全地离开停着的车辆，你必须减速，小心地开过去。","p":"对。无法换道时，就减速并小心。"},"vi":{"q":"Ở Arkansas, bạn đến gần một xe khẩn cấp đang dừng có đèn nhấp nháy, nhưng bạn không thể chuyển sang làn khác một cách an toàn. Bạn phải làm gì?","o":["Giữ tốc độ và chạy qua nhanh","Giảm tốc độ và chạy qua cẩn thận","Dừng trong làn của mình cho đến khi xe đó đi","Bấm còi để báo cho công nhân"],"h1":"Nếu không thể giữ thêm khoảng cách, hãy giảm tốc độ.","h2":"Theo luật tránh sang làn khác của Arkansas, nếu bạn không thể tránh xa xe đang dừng một cách an toàn, bạn phải giảm tốc độ và chạy qua cẩn thận.","p":"Đúng. Khi không thể chuyển làn, bạn giảm tốc độ và cẩn thận."},"tl":{"q":"Sa Arkansas, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw, pero hindi ka ligtas na makalipat sa ibang lane. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at dumaan nang mabilis","Magdahan-dahan at dumaan nang maingat","Huminto sa iyong lane hanggang umalis ito","Bumusina para bigyan ng babala ang mga trabahador"],"h1":"Kung hindi ka makalayo, bawasan ang iyong bilis.","h2":"Ayon sa move-over law ng Arkansas, kung hindi ka ligtas na makalayo sa nakahintong sasakyan, dapat kang magdahan-dahan at dumaan nang maingat.","p":"Tama. Kapag hindi ka makalipat ng lane, magdahan-dahan at mag-ingat."},"ar":{"q":"في Arkansas، تقترب من مركبة طوارئ متوقفة ولها أضواء وامضة، لكنك لا تستطيع الانتقال إلى مسار آخر بأمان. ماذا يجب أن تفعل؟","o":["تحافظ على سرعتك وتمر بسرعة","تخفف السرعة وتمر بحذر","تتوقف في مسارك حتى تغادر","تستخدم البوق لتحذير العمال"],"h1":"إذا لم تستطع زيادة المسافة، خفّف سرعتك.","h2":"حسب قانون الابتعاد في Arkansas، إذا لم تستطع الابتعاد عن المركبة المتوقفة بأمان، يجب أن تخفف السرعة وتمر بحذر.","p":"صحيح. عندما لا تستطيع تغيير المسار، تخفف السرعة وتنتبه."},"ref":{"doc":"AR","page":21}},{"id":"ar-020","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, what fine can a driver face for breaking the move-over law?","o":["$250 to $1,000","$25 to $50","$50 to $100","$5,000 to $10,000"],"h1":"The lowest amount is a few hundred dollars.","h2":"Under Arkansas law, a driver who breaks the move-over law can be fined from $250 to $1,000, and may also face up to 90 days in jail.","p":"Right. The fine ranges from $250 to $1,000."},"es":{"q":"En Arkansas, ¿qué multa puede recibir un conductor por no cumplir la ley de moverse de carril?","o":["De $250 a $1,000","De $25 a $50","De $50 a $100","De $5,000 a $10,000"],"h1":"La cantidad más baja es de unos cientos de dólares.","h2":"Según la ley de Arkansas, quien no cumple la ley de moverse de carril puede recibir una multa de $250 a $1,000, y también hasta 90 días de cárcel.","p":"Correcto. La multa va de $250 a $1,000."},"zh":{"q":"在 Arkansas，司机违反让道法（move-over law）可能被罚多少钱？","o":["$250 到 $1,000","$25 到 $50","$50 到 $100","$5,000 到 $10,000"],"h1":"最低的金额是几百美元。","h2":"根据 Arkansas 法律，违反让道法的司机可能被罚 $250 到 $1,000，还可能被关最多 90 天。","p":"对。罚款是 $250 到 $1,000。"},"vi":{"q":"Ở Arkansas, tài xế vi phạm luật nhường làn (move-over law) có thể bị phạt bao nhiêu tiền?","o":["$250 đến $1,000","$25 đến $50","$50 đến $100","$5,000 đến $10,000"],"h1":"Số tiền thấp nhất là vài trăm đô la.","h2":"Theo luật Arkansas, tài xế vi phạm luật nhường làn có thể bị phạt từ $250 đến $1,000, và cũng có thể bị ngồi tù đến 90 ngày.","p":"Đúng. Tiền phạt từ $250 đến $1,000."},"tl":{"q":"Sa Arkansas, magkano ang multa na puwedeng harapin ng driver na lumabag sa move-over law?","o":["$250 hanggang $1,000","$25 hanggang $50","$50 hanggang $100","$5,000 hanggang $10,000"],"h1":"Ilang daang dolyar ang pinakamababang halaga.","h2":"Ayon sa batas ng Arkansas, ang driver na lumabag sa move-over law ay puwedeng multahan ng $250 hanggang $1,000, at puwede ring makulong nang hanggang 90 araw.","p":"Tama. Ang multa ay mula $250 hanggang $1,000."},"ar":{"q":"في Arkansas، ما الغرامة التي قد يواجهها السائق إذا خالف قانون الابتعاد (move-over law)؟","o":["من $250 إلى $1,000","من $25 إلى $50","من $50 إلى $100","من $5,000 إلى $10,000"],"h1":"أقل مبلغ هو بضع مئات من الدولارات.","h2":"حسب قانون Arkansas، يمكن تغريم السائق الذي يخالف قانون الابتعاد من $250 إلى $1,000، وقد يواجه أيضًا السجن حتى 90 يومًا.","p":"صحيح. الغرامة من $250 إلى $1,000."},"ref":{"doc":"AR","page":null}},{"id":"ar-021","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 5 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"It is about the length of two cars.","h2":"Arkansas law requires you to stop at least 30 feet away from a school bus that is stopped with its red lights flashing.","p":"Right. You stop at least 30 feet from the bus."},"es":{"q":"En Arkansas, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 15 pies","Por lo menos 30 pies"],"h1":"Es más o menos el largo de dos carros.","h2":"La ley de Arkansas exige que usted se detenga por lo menos a 30 pies de un autobús escolar detenido con las luces rojas intermitentes.","p":"Correcto. Usted se detiene por lo menos a 30 pies del autobús."},"zh":{"q":"在 Arkansas，你必须在离红灯闪烁、停着的校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 15 英尺","至少 30 英尺"],"h1":"它大约是两辆车的长度。","h2":"Arkansas 法律要求你在离停着、红灯在闪的校车至少 30 英尺的地方停车。","p":"对。你在离校车至少 30 英尺的地方停车。"},"vi":{"q":"Ở Arkansas, bạn phải dừng cách xe buýt trường học đang dừng có đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 15 feet","Ít nhất 30 feet"],"h1":"Khoảng bằng chiều dài hai chiếc xe hơi.","h2":"Luật Arkansas bắt buộc bạn dừng cách ít nhất 30 feet so với xe buýt trường học đang dừng có đèn đỏ nhấp nháy.","p":"Đúng. Bạn dừng cách xe buýt ít nhất 30 feet."},"tl":{"q":"Sa Arkansas, gaano kalayo ka dapat huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 15 feet","Hindi bababa sa 30 feet"],"h1":"Halos kasinghaba ito ng dalawang kotse.","h2":"Ayon sa batas ng Arkansas, dapat kang huminto nang hindi bababa sa 30 feet ang layo mula sa school bus na nakahinto at kumikislap ang pulang ilaw.","p":"Tama. Huminto ka nang hindi bababa sa 30 feet mula sa bus."},"ar":{"q":"في Arkansas، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة أضواؤها الحمراء تومض؟","o":["5 feet على الأقل","10 feet على الأقل","15 feet على الأقل","30 feet على الأقل"],"h1":"إنها تقريبًا طول سيارتين.","h2":"يفرض قانون Arkansas أن تتوقف على بعد 30 feet على الأقل من الحافلة المدرسية المتوقفة وأضواؤها الحمراء تومض.","p":"صحيح. تتوقف على بعد 30 feet على الأقل من الحافلة."},"ref":{"doc":"AR","page":null}},{"id":"ar-022","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, when may a driver going the opposite way keep moving past a stopped school bus?","o":["On any road with four lanes","On any road with a center turn lane","On a divided highway with a median at least 20 feet wide","On any road when no children are visible"],"h1":"The two sides of the road must be separated by a wide strip.","h2":"In Arkansas, a driver going the opposite way may keep going only when a median at least 20 feet wide separates them from the stopped school bus.","p":"Right. Only a wide median of at least 20 feet lets the opposite side keep going."},"es":{"q":"En Arkansas, ¿cuándo puede un conductor que va en sentido contrario seguir adelante al pasar un autobús escolar detenido?","o":["En cualquier vía de cuatro carriles","En cualquier vía con carril central para girar","En una carretera dividida con una franja central de por lo menos 20 pies","En cualquier vía si no se ven niños"],"h1":"Los dos lados de la vía deben estar separados por una franja ancha.","h2":"En Arkansas, un conductor que va en sentido contrario puede seguir solo cuando una franja divisoria de al menos 20 pies de ancho lo separa del autobús escolar detenido.","p":"Correcto. Solo una franja central de por lo menos 20 pies permite que el lado contrario siga."},"zh":{"q":"在 Arkansas，对面方向的司机什么时候可以继续开过停着的校车？","o":["在任何四车道道路上","在任何有中间转弯车道的道路上","在有至少 20 英尺宽中间隔离带的分隔公路上","在任何看不到孩子的道路上"],"h1":"道路的两边必须用一条很宽的地带分开。","h2":"在 Arkansas，只有在至少 20 英尺宽的中间隔离带把你和停着的校车分开时，对面方向的司机才可以继续开。","p":"对。只有至少 20 英尺宽的隔离带，才让对面的车可以继续开。"},"vi":{"q":"Ở Arkansas, khi nào người lái xe đi chiều ngược lại được tiếp tục chạy qua xe buýt trường học đang dừng?","o":["Trên bất kỳ con đường bốn làn nào","Trên bất kỳ con đường nào có làn rẽ ở giữa","Trên xa lộ có dải phân cách rộng ít nhất 20 feet","Trên bất kỳ con đường nào khi không thấy trẻ em"],"h1":"Hai bên đường phải được tách ra bởi một dải đất rộng.","h2":"Ở Arkansas, người lái xe đi chiều ngược lại chỉ được tiếp tục chạy khi có dải phân cách rộng ít nhất 20 feet ngăn họ với xe buýt trường học đang dừng.","p":"Đúng. Chỉ dải phân cách rộng ít nhất 20 feet mới cho phép bên ngược lại tiếp tục chạy."},"tl":{"q":"Sa Arkansas, kailan puwedeng tuloy-tuloy na dumaan ang drayber na nasa kabilang direksiyon sa nakahintong school bus?","o":["Sa anumang daan na may apat na lane","Sa anumang daan na may center turn lane","Sa divided highway na may median na hindi bababa sa 20 feet ang lapad","Sa anumang daan kapag walang nakikitang bata"],"h1":"Dapat hinihiwalay ng malapad na bahagi ang dalawang gilid ng daan.","h2":"Sa Arkansas, ang drayber na nasa kabilang direksiyon ay puwede lang tumuloy kapag may median na hindi bababa sa 20 feet ang lapad na naghihiwalay sa kanila sa nakahintong school bus.","p":"Tama. Ang malapad na median lang na hindi bababa sa 20 feet ang nagpapahintulot sa kabilang direksiyon na tumuloy."},"ar":{"q":"في Arkansas، متى يجوز للسائق القادم من الاتجاه المعاكس أن يستمر في السير بجانب حافلة مدرسية متوقفة؟","o":["على أي طريق له أربعة مسارات","على أي طريق فيه مسار للانعطاف في الوسط","على طريق سريع مقسوم بفاصل عرضه 20 feet على الأقل","على أي طريق عندما لا يُرى أي أطفال"],"h1":"يجب أن يفصل بين جانبي الطريق شريط عريض.","h2":"في Arkansas، لا يجوز للسائق القادم من الاتجاه المعاكس أن يستمر إلا عندما يفصله عن الحافلة المدرسية المتوقفة فاصل عرضه 20 feet على الأقل.","p":"صحيح. فقط الفاصل العريض الذي عرضه 20 feet على الأقل يسمح للاتجاه المعاكس بالاستمرار."},"ref":{"doc":"AR","page":12}},{"id":"ar-023","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, you are on a four-lane road with a center turn lane and no median. A school bus going the other way stops with red lights flashing. What must you do?","o":["Stop until the red lights turn off","Keep driving because you are going the other way","Slow to 20 mph and pass","Move to the far lane and keep going"],"h1":"A center turn lane is not a median.","h2":"In Arkansas, drivers on two-lane and four-lane roads, including roads with a center turn lane, must stop for a school bus that is loading or unloading children.","p":"Right. Without a wide median, traffic in both directions must stop."},"es":{"q":"En Arkansas, usted va por una vía de cuatro carriles con carril central para girar y sin franja central. Un autobús escolar que va en sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces rojas","Seguir porque usted va en sentido contrario","Reducir a 20 mph y pasar","Pasarse al carril más lejano y seguir"],"h1":"Un carril central para girar no es una franja central.","h2":"En Arkansas, los conductores en vías de dos y cuatro carriles, incluso las que tienen carril central para girar, deben detenerse ante un autobús escolar que sube o baja niños.","p":"Correcto. Sin una franja central ancha, el tráfico en ambas direcciones debe detenerse."},"zh":{"q":"在 Arkansas，你在一条有中间转弯车道、没有隔离带的四车道道路上。一辆对面方向的校车停下来，红灯在闪。你必须怎么做？","o":["停车，直到红灯熄灭","继续开，因为你是对面方向","减速到 20 mph 开过去","换到最远的车道继续开"],"h1":"中间转弯车道不是隔离带。","h2":"在 Arkansas，在双车道和四车道道路上，包括有中间转弯车道的道路，司机都必须为正在让孩子上下车的校车停车。","p":"对。没有宽的隔离带，两个方向的车都必须停车。"},"vi":{"q":"Ở Arkansas, bạn đang đi trên con đường bốn làn có làn rẽ ở giữa và không có dải phân cách. Một xe buýt trường học đi chiều ngược lại dừng và bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn đỏ tắt","Tiếp tục lái vì bạn đi chiều ngược lại","Giảm xuống 20 mph rồi chạy qua","Chuyển sang làn xa nhất và tiếp tục chạy"],"h1":"Làn rẽ ở giữa không phải là dải phân cách.","h2":"Ở Arkansas, người lái xe trên đường hai làn và bốn làn, kể cả đường có làn rẽ ở giữa, phải dừng lại khi xe buýt trường học đang cho trẻ em lên hoặc xuống.","p":"Đúng. Khi không có dải phân cách rộng, xe ở cả hai chiều đều phải dừng."},"tl":{"q":"Sa Arkansas, nasa daan ka na may apat na lane at center turn lane, at walang median. Huminto ang school bus na nasa kabilang direksiyon at kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang pulang ilaw","Tumuloy dahil nasa kabilang direksiyon ka","Bumagal sa 20 mph at dumaan","Lumipat sa pinakamalayong lane at tumuloy"],"h1":"Ang center turn lane ay hindi median.","h2":"Sa Arkansas, ang mga drayber sa daan na may dalawa o apat na lane, kasama ang mga daan na may center turn lane, ay dapat huminto para sa school bus na nagsasakay o nagbababa ng mga bata.","p":"Tama. Kapag walang malapad na median, dapat huminto ang trapiko sa dalawang direksiyon."},"ar":{"q":"في Arkansas، أنت على طريق له أربعة مسارات مع مسار للانعطاف في الوسط وبدون فاصل. حافلة مدرسية قادمة من الاتجاه الآخر تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء الحمراء","تستمر في القيادة لأنك في الاتجاه الآخر","تخفف السرعة إلى 20 mph وتمر","تنتقل إلى المسار الأبعد وتستمر"],"h1":"مسار الانعطاف في الوسط ليس فاصلًا.","h2":"في Arkansas، يجب على السائقين على الطرق ذات المسارين والأربعة مسارات، ومنها الطرق التي فيها مسار للانعطاف في الوسط، أن يتوقفوا للحافلة المدرسية التي تُركب الأطفال أو تُنزلهم.","p":"صحيح. بدون فاصل عريض، يجب أن تتوقف السيارات في الاتجاهين."},"ref":{"doc":"AR","page":13}},{"id":"ar-024","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, what is the highest fine for illegally passing a stopped school bus?","o":["$500","$2,500","$100","$10,000"],"h1":"It is a few thousand dollars, plus court costs.","h2":"Under Arkansas law, illegally passing a stopped school bus can bring a fine of up to $2,500, plus court costs.","p":"Right. The fine can reach $2,500."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por pasar ilegalmente un autobús escolar detenido?","o":["$500","$2,500","$100","$10,000"],"h1":"Son unos miles de dólares, más los costos del tribunal.","h2":"Según la ley de Arkansas, pasar ilegalmente un autobús escolar detenido puede costar una multa de hasta $2,500, más los costos del tribunal.","p":"Correcto. La multa puede llegar a $2,500."},"zh":{"q":"在 Arkansas，非法超过停着的校车，最高罚款是多少？","o":["$500","$2,500","$100","$10,000"],"h1":"它是几千美元，另外还要付法庭费用。","h2":"根据 Arkansas 法律，非法超过停着的校车，可能被罚最高 $2,500，另外还要付法庭费用。","p":"对。罚款可能高达 $2,500。"},"vi":{"q":"Ở Arkansas, tiền phạt cao nhất cho việc vượt trái phép xe buýt trường học đang dừng là bao nhiêu?","o":["$500","$2,500","$100","$10,000"],"h1":"Đó là vài nghìn đô la, cộng thêm án phí.","h2":"Theo luật Arkansas, vượt trái phép xe buýt trường học đang dừng có thể bị phạt đến $2,500, cộng thêm án phí.","p":"Đúng. Tiền phạt có thể lên đến $2,500."},"tl":{"q":"Sa Arkansas, ano ang pinakamataas na multa sa ilegal na pag-overtake sa nakahintong school bus?","o":["$500","$2,500","$100","$10,000"],"h1":"Ilang libong dolyar ito, dagdag pa ang court costs.","h2":"Ayon sa batas ng Arkansas, ang ilegal na pag-overtake sa nakahintong school bus ay puwedeng magmulta ng hanggang $2,500, dagdag pa ang court costs.","p":"Tama. Ang multa ay puwedeng umabot sa $2,500."},"ar":{"q":"في Arkansas، ما هي أعلى غرامة لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني؟","o":["$500","$2,500","$100","$10,000"],"h1":"إنها بضعة آلاف من الدولارات، بالإضافة إلى تكاليف المحكمة.","h2":"حسب قانون Arkansas، تجاوز حافلة مدرسية متوقفة بشكل غير قانوني يمكن أن يؤدي إلى غرامة تصل إلى $2,500، بالإضافة إلى تكاليف المحكمة.","p":"صحيح. يمكن أن تصل الغرامة إلى $2,500."},"ref":{"doc":"AR","page":null}},{"id":"ar-026","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, what is the minimum liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Arkansas requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Arkansas minimum is 25, 50 and 25 thousand dollars."},"es":{"q":"En Arkansas, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"El primer número y el último son iguales.","h2":"Arkansas exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Arkansas es de 25, 50 y 25 mil dólares."},"zh":{"q":"在 Arkansas，司机必须买的最低责任保险是多少？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"第一个和最后一个数字一样。","h2":"Arkansas 要求一个人受伤至少 $25,000，一次车祸的人身伤害至少 $50,000，财产损失至少 $25,000。","p":"对。Arkansas 的最低标准是 $25,000、$50,000 和 $25,000。"},"vi":{"q":"Ở Arkansas, bảo hiểm trách nhiệm tối thiểu mà người lái xe phải có là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Arkansas yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Arkansas là 25, 50 và 25 nghìn đô la."},"tl":{"q":"Sa Arkansas, ano ang pinakamababang liability insurance na dapat mayroon ang drayber?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Arkansas ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang banggaan, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Arkansas ay 25, 50 at 25 libong dolyar."},"ar":{"q":"في Arkansas، ما هو الحد الأدنى لتأمين المسؤولية الذي يجب أن يكون لدى السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تطلب Arkansas على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Arkansas هو 25 و50 و25 ألف دولار."},"ref":{"doc":"AR","page":null}},{"id":"ar-027","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, how long is an instruction permit valid?","o":["6 months, and it can be renewed","2 years, and it cannot be renewed","1 year, and it can be renewed once","4 years, and it cannot be renewed"],"h1":"You cannot extend it, so finish the road test in time.","h2":"In Arkansas an instruction permit is valid for 2 years and cannot be renewed, so you must pass the skills test and buy a license before it expires.","p":"Right. The permit lasts 2 years with no renewal."},"es":{"q":"En Arkansas, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses, y se puede renovar","2 años, y no se puede renovar","1 año, y se puede renovar una vez","4 años, y no se puede renovar"],"h1":"No se puede extender, así que termine el examen de manejo a tiempo.","h2":"En Arkansas el permiso de aprendizaje es válido por 2 años y no se puede renovar, así que debe aprobar el examen práctico y comprar la licencia antes de que venza.","p":"Correcto. El permiso dura 2 años y no se renueva."},"zh":{"q":"在 Arkansas，学习驾照（instruction permit）的有效期是多久？","o":["6 个月，可以续期","2 年，不能续期","1 年，可以续期一次","4 年，不能续期"],"h1":"它不能延长，所以要及时完成路考。","h2":"在 Arkansas，学习驾照的有效期是 2 年，而且不能续期，所以你必须在它过期之前通过路考并购买驾照。","p":"对。学习驾照有效 2 年，不能续期。"},"vi":{"q":"Ở Arkansas, giấy phép học lái (instruction permit) có giá trị trong bao lâu?","o":["6 tháng, và có thể gia hạn","2 năm, và không thể gia hạn","1 năm, và có thể gia hạn một lần","4 năm, và không thể gia hạn"],"h1":"Bạn không thể kéo dài nó, vì vậy hãy thi lái xe kịp thời.","h2":"Ở Arkansas, giấy phép học lái có giá trị trong 2 năm và không thể gia hạn, vì vậy bạn phải thi đậu bài thi kỹ năng và mua bằng lái trước khi nó hết hạn.","p":"Đúng. Giấy phép học lái có giá trị 2 năm và không được gia hạn."},"tl":{"q":"Sa Arkansas, gaano katagal valid ang instruction permit?","o":["6 na buwan, at puwede itong i-renew","2 taon, at hindi ito puwedeng i-renew","1 taon, at puwede itong i-renew nang isang beses","4 na taon, at hindi ito puwedeng i-renew"],"h1":"Hindi mo ito mapapahaba, kaya tapusin ang road test sa tamang oras.","h2":"Sa Arkansas, ang instruction permit ay valid nang 2 taon at hindi puwedeng i-renew, kaya kailangan mong pumasa sa skills test at bumili ng lisensya bago ito mag-expire.","p":"Tama. Ang permit ay tumatagal nang 2 taon at walang renewal."},"ar":{"q":"في Arkansas، ما مدة صلاحية تصريح التعلم (instruction permit)؟","o":["6 أشهر، ويمكن تجديده","سنتان (2)، ولا يمكن تجديده","سنة واحدة (1)، ويمكن تجديده مرة واحدة","4 سنوات، ولا يمكن تجديده"],"h1":"لا يمكنك تمديده، لذلك أكمل اختبار القيادة في الوقت المناسب.","h2":"في Arkansas، تصريح التعلم صالح لمدة سنتين (2) ولا يمكن تجديده، لذلك يجب أن تنجح في اختبار المهارات وتشتري الرخصة قبل انتهاء صلاحيته.","p":"صحيح. التصريح صالح لمدة سنتين (2) بدون تجديد."},"ref":{"doc":"AR","page":86}},{"id":"ar-028","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, after a crash with an injury or major damage, how long do you have to send a report to the Office of Driver Services?","o":["24 hours","5 days","10 days","30 days"],"h1":"It is about one month.","h2":"In Arkansas you must file the crash report with the Office of Driver Services within 30 days when there is an injury, a death, or more than $3,000 in damage to one person's property.","p":"Right. You have 30 days to file the report."},"es":{"q":"En Arkansas, después de un choque con heridos o daños grandes, ¿cuánto tiempo tiene para enviar un informe a la Oficina de Servicios al Conductor?","o":["24 horas","5 días","10 días","30 días"],"h1":"Es más o menos un mes.","h2":"En Arkansas usted debe enviar el informe del choque a la Oficina de Servicios al Conductor dentro de 30 días cuando hay heridos, una muerte o más de $3,000 en daños a la propiedad de una persona.","p":"Correcto. Tiene 30 días para enviar el informe."},"zh":{"q":"在 Arkansas，发生有人受伤或严重损坏的车祸后，你需要在多长时间内向 Office of Driver Services 提交报告？","o":["24 小时","5 天","10 天","30 天"],"h1":"大约是一个月。","h2":"在 Arkansas，如果有人受伤、有人死亡，或者一个人的财产损失超过 $3,000，你必须在 30 天内向 Office of Driver Services 提交车祸报告。","p":"对。你有 30 天时间提交报告。"},"vi":{"q":"Ở Arkansas, sau một vụ tai nạn có người bị thương hoặc hư hại lớn, bạn có bao lâu để gửi báo cáo cho Office of Driver Services?","o":["24 giờ","5 ngày","10 ngày","30 ngày"],"h1":"Khoảng một tháng.","h2":"Ở Arkansas, bạn phải nộp báo cáo tai nạn cho Office of Driver Services trong vòng 30 ngày khi có người bị thương, có người chết, hoặc tài sản của một người bị hư hại hơn $3,000.","p":"Đúng. Bạn có 30 ngày để nộp báo cáo."},"tl":{"q":"Sa Arkansas, pagkatapos ng banggaan na may nasaktan o malaking pinsala, gaano katagal ka para magpadala ng ulat sa Office of Driver Services?","o":["24 na oras","5 araw","10 araw","30 araw"],"h1":"Mga isang buwan ito.","h2":"Sa Arkansas, kailangan mong magpasa ng ulat ng banggaan sa Office of Driver Services sa loob ng 30 araw kapag may nasaktan, may namatay, o may higit sa $3,000 na pinsala sa ari-arian ng isang tao.","p":"Tama. May 30 araw ka para ipasa ang ulat."},"ar":{"q":"في Arkansas، بعد حادث فيه إصابة أو ضرر كبير، ما المدة المتاحة لك لإرسال تقرير إلى Office of Driver Services؟","o":["24 ساعة","5 أيام","10 أيام","30 يومًا"],"h1":"المدة حوالي شهر واحد.","h2":"في Arkansas، يجب أن تقدم تقرير الحادث إلى Office of Driver Services خلال 30 يومًا إذا كانت هناك إصابة أو وفاة أو ضرر بأكثر من $3,000 في ممتلكات شخص واحد.","p":"صحيح. لديك 30 يومًا لتقديم التقرير."},"ref":{"doc":"AR","page":81}},{"id":"ar-029","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, how close to a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 10 feet","No closer than 20 feet","Right next to it"],"h1":"It is more than three times the distance for a fire hydrant.","h2":"In Arkansas you may not park within 50 feet of a railroad crossing.","p":"Right. Park at least 50 feet away from a railroad crossing."},"es":{"q":"En Arkansas, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 50 pies","No más cerca de 10 pies","No más cerca de 20 pies","Justo al lado"],"h1":"Es más de tres veces la distancia para un hidrante.","h2":"En Arkansas usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Arkansas，你可以在离铁路道口多近的地方停车？","o":["不能少于 50 英尺","不能少于 10 英尺","不能少于 20 英尺","紧挨着道口"],"h1":"这个距离是消防栓距离的三倍多。","h2":"在 Arkansas，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Arkansas, bạn được đậu xe gần chỗ băng qua đường sắt đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Ngay sát bên cạnh"],"h1":"Khoảng cách này lớn hơn ba lần khoảng cách với trụ nước cứu hỏa.","h2":"Ở Arkansas, bạn không được đậu xe trong vòng 50 feet tính từ chỗ băng qua đường sắt.","p":"Đúng. Hãy đậu xe cách chỗ băng qua đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Arkansas, gaano kalapit sa tawiran ng riles puwede kang pumarada?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 20 talampakan","Mismong katabi nito"],"h1":"Higit ito sa tatlong beses ng layo para sa fire hydrant.","h2":"Sa Arkansas, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa tawiran ng riles.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan ang layo mula sa tawiran ng riles."},"ar":{"q":"في Arkansas، على أي مسافة من معبر السكة الحديدية يُسمح لك بالوقوف؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","بجانبه مباشرة"],"h1":"هذه المسافة أكثر من ثلاثة أضعاف المسافة عن صنبور الإطفاء.","h2":"في Arkansas، لا يجوز لك الوقوف على مسافة أقل من 50 قدمًا من معبر السكة الحديدية.","p":"صحيح. قف على بعد 50 قدمًا على الأقل من معبر السكة الحديدية."},"ref":{"doc":"AR","page":42}},{"id":"ar-030","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, on a highway with several lanes going your way, when may you drive in the far-left lane?","o":["Any time traffic is light","Only at night","When passing, exiting on the left, or when other lanes are closed","Whenever you drive at the speed limit"],"h1":"The left lane is mainly for getting around slower cars.","h2":"In Arkansas you may use the left lane of a multilane highway only to pass, to exit on the left, or when the other lanes are closed or unsafe.","p":"Right. The left lane is for passing, not for cruising."},"es":{"q":"En Arkansas, en una carretera con varios carriles en su dirección, ¿cuándo puede manejar en el carril de la extrema izquierda?","o":["Siempre que haya poco tráfico","Solo de noche","Al rebasar, al salir por la izquierda o si los otros carriles están cerrados","Siempre que maneje al límite de velocidad"],"h1":"El carril izquierdo es más que nada para pasar a los carros lentos.","h2":"En Arkansas usted puede usar el carril izquierdo de una carretera de varios carriles solo para rebasar, para salir por la izquierda o cuando los otros carriles están cerrados o no son seguros.","p":"Correcto. El carril izquierdo es para rebasar, no para ir de paseo."},"zh":{"q":"在 Arkansas，在同方向有多条车道的公路上，你什么时候可以在最左边的车道行驶？","o":["只要车不多就可以","只在晚上","超车、从左边出口驶出，或其他车道关闭时","只要你按限速行驶就可以"],"h1":"左车道主要用来超过开得较慢的车。","h2":"在 Arkansas，你只有在超车、从左边出口驶出，或其他车道关闭或不安全时，才可以使用多车道公路的左车道。","p":"对。左车道是用来超车的，不是用来一直行驶的。"},"vi":{"q":"Ở Arkansas, trên xa lộ có nhiều làn xe cùng chiều với bạn, khi nào bạn được chạy ở làn ngoài cùng bên trái?","o":["Bất cứ lúc nào xe cộ thưa thớt","Chỉ vào ban đêm","Khi vượt xe, khi ra lối bên trái, hoặc khi các làn khác bị đóng","Bất cứ khi nào bạn chạy đúng tốc độ giới hạn"],"h1":"Làn bên trái chủ yếu dùng để vượt qua xe chạy chậm hơn.","h2":"Ở Arkansas, bạn chỉ được dùng làn bên trái của xa lộ nhiều làn để vượt xe, để ra lối bên trái, hoặc khi các làn khác bị đóng hay không an toàn.","p":"Đúng. Làn bên trái dùng để vượt xe, không phải để chạy đều đều."},"tl":{"q":"Sa Arkansas, sa highway na may ilang lane papunta sa direksyon mo, kailan ka puwedeng magmaneho sa pinakakaliwang lane?","o":["Anumang oras na kaunti ang trapiko","Sa gabi lamang","Kapag nag-o-overtake, lalabas sa kaliwa, o sarado ang ibang lane","Tuwing nagmamaneho ka sa speed limit"],"h1":"Ang kaliwang lane ay pangunahing para lampasan ang mas mabagal na sasakyan.","h2":"Sa Arkansas, puwede mong gamitin ang kaliwang lane ng highway na maraming lane para lamang mag-overtake, lumabas sa kaliwa, o kapag sarado o hindi ligtas ang ibang lane.","p":"Tama. Ang kaliwang lane ay para sa pag-overtake, hindi para sa tuloy-tuloy na pagmamaneho."},"ar":{"q":"في Arkansas، على طريق سريع فيه عدة حارات في اتجاهك، متى يُسمح لك بالقيادة في الحارة اليسرى القصوى؟","o":["في أي وقت تكون فيه حركة المرور خفيفة","في الليل فقط","عند التجاوز، أو الخروج من اليسار، أو عندما تكون الحارات الأخرى مغلقة","كلما كنت تقود بالسرعة المحددة"],"h1":"الحارة اليسرى مخصصة أساسًا لتجاوز السيارات الأبطأ.","h2":"في Arkansas، يُسمح لك باستخدام الحارة اليسرى في الطريق السريع متعدد الحارات فقط للتجاوز، أو للخروج من اليسار، أو عندما تكون الحارات الأخرى مغلقة أو غير آمنة.","p":"صحيح. الحارة اليسرى للتجاوز، وليست للقيادة المستمرة."},"ref":{"doc":"AR","page":63}},{"id":"ar-031","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, which child must ride in a child safety seat?","o":["Any child under 12, at any weight","A child under 6 who weighs less than 60 pounds","Only babies under 1 year old","A child under 10 who is shorter than 5 feet"],"h1":"The rule uses both an age and a weight.","h2":"In Arkansas a child under 6 years old who weighs less than 60 pounds must ride in a child safety seat that is properly secured.","p":"Right. Under 6 and under 60 pounds means a child safety seat."},"es":{"q":"En Arkansas, ¿qué niño debe viajar en un asiento de seguridad infantil?","o":["Cualquier niño menor de 12, de cualquier peso","Un niño menor de 6 que pesa menos de 60 libras","Solo los bebés menores de 1 año","Un niño menor de 10 que mide menos de 5 pies"],"h1":"La regla usa una edad y también un peso.","h2":"En Arkansas un niño menor de 6 años que pesa menos de 60 libras debe viajar en un asiento de seguridad infantil bien sujeto.","p":"Correcto. Menor de 6 y de menos de 60 libras: asiento de seguridad."},"zh":{"q":"在 Arkansas，哪个孩子必须坐儿童安全座椅？","o":["任何 12 岁以下的孩子，不管体重多少","6 岁以下且体重不到 60 磅的孩子","只有 1 岁以下的婴儿","10 岁以下且身高不到 5 英尺的孩子"],"h1":"这条规定同时看年龄和体重。","h2":"在 Arkansas，6 岁以下并且体重不到 60 磅的孩子必须坐在固定好的儿童安全座椅里。","p":"对。6 岁以下并且不到 60 磅，就要坐儿童安全座椅。"},"vi":{"q":"Ở Arkansas, trẻ em nào phải ngồi ghế an toàn cho trẻ em?","o":["Bất kỳ trẻ nào dưới 12 tuổi, với bất kỳ cân nặng nào","Trẻ dưới 6 tuổi và nặng dưới 60 pound","Chỉ em bé dưới 1 tuổi","Trẻ dưới 10 tuổi và thấp hơn 5 feet"],"h1":"Quy định này dùng cả tuổi và cân nặng.","h2":"Ở Arkansas, trẻ dưới 6 tuổi và nặng dưới 60 pound phải ngồi trong ghế an toàn cho trẻ em được gắn chắc chắn đúng cách.","p":"Đúng. Dưới 6 tuổi và dưới 60 pound thì phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Arkansas, aling bata ang dapat nakasakay sa child safety seat?","o":["Sinumang batang wala pang 12 taong gulang, anuman ang timbang","Batang wala pang 6 taong gulang na mas magaan sa 60 pounds","Mga sanggol lamang na wala pang 1 taong gulang","Batang wala pang 10 taong gulang na mas maikli sa 5 talampakan"],"h1":"Ginagamit ng patakaran ang edad at ang timbang.","h2":"Sa Arkansas, ang batang wala pang 6 taong gulang na mas magaan sa 60 pounds ay dapat nakasakay sa child safety seat na maayos na nakakabit.","p":"Tama. Wala pang 6 na taon at wala pang 60 pounds ay kailangan ng child safety seat."},"ar":{"q":"في Arkansas، أي طفل يجب أن يجلس في مقعد أمان للأطفال؟","o":["أي طفل عمره أقل من 12 سنة، مهما كان وزنه","طفل عمره أقل من 6 سنوات ووزنه أقل من 60 رطلًا","الرضّع الذين عمرهم أقل من سنة واحدة (1) فقط","طفل عمره أقل من 10 سنوات وطوله أقل من 5 أقدام"],"h1":"القاعدة تستخدم العمر والوزن معًا.","h2":"في Arkansas، يجب أن يجلس الطفل الذي عمره أقل من 6 سنوات ووزنه أقل من 60 رطلًا في مقعد أمان للأطفال مثبّت بشكل صحيح.","p":"صحيح. أقل من 6 سنوات وأقل من 60 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"AR","page":9}},{"id":"ar-032","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, when is it against the law to smoke tobacco in a car?","o":["Only while the car is moving fast","Only when the windows are closed","Never, it is always allowed","When a child under 14 is riding in the car"],"h1":"The law protects young passengers from smoke.","h2":"In Arkansas no one may knowingly smoke tobacco in a vehicle when a child under 14 years old is a passenger.","p":"Right. No smoking with a child under 14 in the car."},"es":{"q":"En Arkansas, ¿cuándo es ilegal fumar tabaco en un carro?","o":["Solo cuando el carro va rápido","Solo con las ventanas cerradas","Nunca, siempre está permitido","Cuando un niño menor de 14 años va en el carro"],"h1":"La ley protege del humo a los pasajeros jóvenes.","h2":"En Arkansas nadie puede fumar tabaco a sabiendas en un vehículo cuando va un pasajero menor de 14 años.","p":"Correcto. No se fuma con un niño menor de 14 en el carro."},"zh":{"q":"在 Arkansas，什么时候在车里吸烟是违法的？","o":["只有在车开得很快的时候","只有在车窗关着的时候","从来不违法，总是可以","当车里坐着 14 岁以下的孩子时"],"h1":"这条法律保护年幼的乘客不受烟雾伤害。","h2":"在 Arkansas，当车里有 14 岁以下的孩子乘坐时，任何人都不可以故意在车里吸烟。","p":"对。车里有 14 岁以下的孩子时不能吸烟。"},"vi":{"q":"Ở Arkansas, khi nào hút thuốc lá trong xe là phạm luật?","o":["Chỉ khi xe đang chạy nhanh","Chỉ khi cửa sổ đóng","Không bao giờ, lúc nào cũng được phép","Khi có trẻ em dưới 14 tuổi đang ngồi trong xe"],"h1":"Luật này bảo vệ hành khách nhỏ tuổi khỏi khói thuốc.","h2":"Ở Arkansas, không ai được cố ý hút thuốc lá trong xe khi có trẻ em dưới 14 tuổi là hành khách.","p":"Đúng. Không được hút thuốc khi có trẻ em dưới 14 tuổi trong xe."},"tl":{"q":"Sa Arkansas, kailan labag sa batas ang manigarilyo sa loob ng kotse?","o":["Kapag mabilis lang ang takbo ng kotse","Kapag nakasara lang ang mga bintana","Hindi kailanman, palaging puwede","Kapag may batang wala pang 14 taong gulang na nakasakay sa kotse"],"h1":"Pinoprotektahan ng batas ang mga batang pasahero mula sa usok.","h2":"Sa Arkansas, walang sinuman ang puwedeng sadyang manigarilyo sa loob ng sasakyan kapag may pasaherong bata na wala pang 14 taong gulang.","p":"Tama. Bawal manigarilyo kapag may batang wala pang 14 taong gulang sa kotse."},"ar":{"q":"في Arkansas، متى يكون التدخين داخل السيارة مخالفًا للقانون؟","o":["فقط عندما تسير السيارة بسرعة","فقط عندما تكون النوافذ مغلقة","أبدًا، فهو مسموح دائمًا","عندما يكون في السيارة طفل عمره أقل من 14 سنة"],"h1":"القانون يحمي الركاب الصغار من الدخان.","h2":"في Arkansas، لا يجوز لأي شخص أن يدخن عمدًا داخل مركبة إذا كان فيها راكب طفل عمره أقل من 14 سنة.","p":"صحيح. ممنوع التدخين إذا كان في السيارة طفل عمره أقل من 14 سنة."},"ref":{"doc":"AR","page":9}},{"id":"ar-033","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, you just moved to the state and became a resident. How soon must you get an Arkansas driver's license?","o":["Within 6 months","Within 30 days","Within 1 year","Only when your old license expires"],"h1":"It is less than two months.","h2":"A new Arkansas resident must get an Arkansas driver's license within 30 days.","p":"Right. New residents have 30 days to get an Arkansas license."},"es":{"q":"En Arkansas, usted se acaba de mudar al estado y ya es residente. ¿En cuánto tiempo debe obtener una licencia de conducir de Arkansas?","o":["Dentro de 6 meses","Dentro de 30 días","Dentro de 1 año","Solo cuando venza su licencia anterior"],"h1":"Es menos de dos meses.","h2":"Un nuevo residente de Arkansas debe obtener una licencia de conducir de Arkansas dentro de 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para obtener una licencia de Arkansas."},"zh":{"q":"在 Arkansas，你刚搬到这个州并成为居民。你必须在多长时间内办理 Arkansas 驾照？","o":["6 个月内","30 天内","1 年内","只有在你原来的驾照过期时"],"h1":"不到两个月。","h2":"新的 Arkansas 居民必须在 30 天内办理 Arkansas 驾照。","p":"对。新居民有 30 天时间办理 Arkansas 驾照。"},"vi":{"q":"Ở Arkansas, bạn vừa chuyển đến tiểu bang và trở thành cư dân. Bạn phải lấy bằng lái Arkansas trong bao lâu?","o":["Trong vòng 6 tháng","Trong vòng 30 ngày","Trong vòng 1 năm","Chỉ khi bằng lái cũ của bạn hết hạn"],"h1":"Thời gian này ít hơn hai tháng.","h2":"Cư dân mới của Arkansas phải lấy bằng lái Arkansas trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày để lấy bằng lái Arkansas."},"tl":{"q":"Sa Arkansas, kalilipat mo lang sa estado at naging residente ka. Gaano kabilis ka dapat kumuha ng Arkansas driver's license?","o":["Sa loob ng 6 na buwan","Sa loob ng 30 araw","Sa loob ng 1 taon","Kapag nag-expire na lang ang luma mong lisensya"],"h1":"Mas maikli ito sa dalawang buwan.","h2":"Ang bagong residente ng Arkansas ay dapat kumuha ng Arkansas driver's license sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente para kumuha ng lisensya ng Arkansas."},"ar":{"q":"في Arkansas، انتقلت للتو إلى الولاية وأصبحت مقيمًا فيها. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Arkansas؟","o":["خلال 6 أشهر","خلال 30 يومًا","خلال سنة واحدة (1)","فقط عندما تنتهي صلاحية رخصتك القديمة"],"h1":"المدة أقل من شهرين.","h2":"يجب على المقيم الجديد في Arkansas أن يحصل على رخصة قيادة من Arkansas خلال 30 يومًا.","p":"صحيح. لدى المقيمين الجدد 30 يومًا للحصول على رخصة من Arkansas."},"ref":{"doc":"AR","page":2}},{"id":"ar-034","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what is the minimum vision without glasses or contacts needed for a license with no glasses restriction?","o":["20/20","20/100","20/200","20/40"],"h1":"It is a little less than perfect vision.","h2":"In Arkansas you need at least 20/40 vision without glasses or contacts for a license with no glasses restriction.","p":"Right. 20/40 without glasses is the minimum for an unrestricted license."},"es":{"q":"En Arkansas, ¿cuál es la visión mínima sin anteojos ni lentes de contacto para una licencia sin restricción de anteojos?","o":["20/20","20/100","20/200","20/40"],"h1":"Es un poco menos que una visión perfecta.","h2":"En Arkansas usted necesita por lo menos una visión de 20/40 sin anteojos ni lentes de contacto para una licencia sin restricción de anteojos.","p":"Correcto. 20/40 sin anteojos es el mínimo para una licencia sin restricción."},"zh":{"q":"在 Arkansas，要拿到没有“必须戴眼镜”限制的驾照，不戴眼镜或隐形眼镜时视力最低要达到多少？","o":["20/20","20/100","20/200","20/40"],"h1":"比完美视力差一点。","h2":"在 Arkansas，不戴眼镜或隐形眼镜时视力至少要达到 20/40，才能拿到没有眼镜限制的驾照。","p":"对。不戴眼镜视力 20/40 是无限制驾照的最低要求。"},"vi":{"q":"Ở Arkansas, thị lực tối thiểu khi không đeo kính hoặc kính áp tròng là bao nhiêu để có bằng lái không bị giới hạn phải đeo kính?","o":["20/20","20/100","20/200","20/40"],"h1":"Thị lực này kém hơn một chút so với thị lực hoàn hảo.","h2":"Ở Arkansas, bạn cần thị lực ít nhất 20/40 khi không đeo kính hoặc kính áp tròng để có bằng lái không bị giới hạn phải đeo kính.","p":"Đúng. 20/40 khi không đeo kính là mức tối thiểu cho bằng lái không giới hạn."},"tl":{"q":"Sa Arkansas, ano ang pinakamababang paningin nang walang salamin o contact lens para sa lisensyang walang restriksyon sa salamin?","o":["20/20","20/100","20/200","20/40"],"h1":"Medyo mas mababa ito sa perpektong paningin.","h2":"Sa Arkansas, kailangan mo ng hindi bababa sa 20/40 na paningin nang walang salamin o contact lens para sa lisensyang walang restriksyon sa salamin.","p":"Tama. Ang 20/40 nang walang salamin ang pinakamababa para sa lisensyang walang restriksyon."},"ar":{"q":"في Arkansas، ما أقل قوة نظر مطلوبة بدون نظارة أو عدسات لاصقة للحصول على رخصة بدون شرط ارتداء النظارة؟","o":["20/20","20/100","20/200","20/40"],"h1":"هي أقل قليلًا من النظر الكامل.","h2":"في Arkansas، تحتاج إلى قوة نظر 20/40 على الأقل بدون نظارة أو عدسات لاصقة للحصول على رخصة بدون شرط ارتداء النظارة.","p":"صحيح. قوة النظر 20/40 بدون نظارة هي الحد الأدنى لرخصة بدون قيود."},"ref":{"doc":"AR","page":5}},{"id":"ar-035","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, a teen under 18 who was born in the United States is applying for a permit. What must the teen bring as proof of birth?","o":["An original or certified U.S. birth certificate","A U.S. passport","A hospital birth certificate","A photocopy of a birth certificate"],"h1":"The state asks minors for one specific paper from the government office that records births.","h2":"In Arkansas, a U.S.-born applicant under 18 must bring an original or certified U.S. birth certificate; a passport, a hospital certificate, or a copy is not accepted.","p":"Right. Minors born in the U.S. need an original or certified birth certificate."},"es":{"q":"En Arkansas, un adolescente menor de 18 años que nació en los Estados Unidos solicita un permiso. ¿Qué debe llevar como prueba de nacimiento?","o":["Un acta de nacimiento de EE. UU. original o certificada","Un pasaporte de EE. UU.","Un certificado de nacimiento del hospital","Una fotocopia del acta de nacimiento"],"h1":"El estado pide a los menores un documento específico de la oficina del gobierno que registra los nacimientos.","h2":"En Arkansas, un solicitante menor de 18 años nacido en EE. UU. debe llevar un acta de nacimiento de EE. UU. original o certificada; no se acepta un pasaporte, un certificado del hospital ni una copia.","p":"Correcto. Los menores nacidos en EE. UU. necesitan un acta de nacimiento original o certificada."},"zh":{"q":"在 Arkansas，一名在美国出生、未满 18 岁的青少年要申请学习驾照。这名青少年必须带什么作为出生证明？","o":["美国出生证明的原件或经认证的副本","美国护照","医院开的出生证明","出生证明的复印件"],"h1":"州政府要求未成年人带一份由政府出生登记部门发的文件。","h2":"在 Arkansas，在美国出生、未满 18 岁的申请人必须带美国出生证明的原件或经认证的副本；护照、医院的证明或复印件都不被接受。","p":"对。在美国出生的未成年人需要出生证明的原件或经认证的副本。"},"vi":{"q":"Ở Arkansas, một thiếu niên dưới 18 tuổi sinh ra ở Hoa Kỳ đang xin giấy phép học lái. Thiếu niên đó phải mang gì để chứng minh nơi sinh?","o":["Giấy khai sinh Hoa Kỳ bản gốc hoặc bản sao có chứng thực","Hộ chiếu Hoa Kỳ","Giấy chứng sinh của bệnh viện","Bản photocopy giấy khai sinh"],"h1":"Tiểu bang yêu cầu người chưa thành niên mang một giấy tờ cụ thể từ cơ quan chính phủ ghi nhận việc khai sinh.","h2":"Ở Arkansas, người nộp đơn dưới 18 tuổi sinh ra ở Hoa Kỳ phải mang giấy khai sinh Hoa Kỳ bản gốc hoặc bản sao có chứng thực; hộ chiếu, giấy chứng sinh của bệnh viện hoặc bản photocopy đều không được chấp nhận.","p":"Đúng. Người chưa thành niên sinh ở Hoa Kỳ cần giấy khai sinh bản gốc hoặc bản sao có chứng thực."},"tl":{"q":"Sa Arkansas, isang teen na wala pang 18 taong gulang na ipinanganak sa United States ang nag-a-apply ng permit. Ano ang dapat dalhin ng teen bilang patunay ng kapanganakan?","o":["Orihinal o certified na U.S. birth certificate","U.S. passport","Birth certificate mula sa ospital","Photocopy ng birth certificate"],"h1":"Isang partikular na papel mula sa opisina ng gobyerno na nagtatala ng kapanganakan ang hinihingi ng estado sa mga menor de edad.","h2":"Sa Arkansas, ang aplikanteng wala pang 18 taong gulang na ipinanganak sa U.S. ay dapat magdala ng orihinal o certified na U.S. birth certificate; hindi tinatanggap ang passport, certificate mula sa ospital, o kopya.","p":"Tama. Ang mga menor de edad na ipinanganak sa U.S. ay kailangan ng orihinal o certified na birth certificate."},"ar":{"q":"في Arkansas، مراهق عمره أقل من 18 سنة وُلد في الولايات المتحدة يقدّم طلبًا للحصول على تصريح تعلّم. ماذا يجب أن يحضر المراهق كإثبات للميلاد؟","o":["شهادة ميلاد أمريكية أصلية أو مصدّقة","جواز سفر أمريكي","شهادة ميلاد من المستشفى","نسخة مصوّرة من شهادة الميلاد"],"h1":"تطلب الولاية من القاصرين ورقة معيّنة من المكتب الحكومي الذي يسجّل المواليد.","h2":"في Arkansas، يجب على المتقدّم المولود في الولايات المتحدة الذي عمره أقل من 18 سنة أن يحضر شهادة ميلاد أمريكية أصلية أو مصدّقة؛ ولا يُقبل جواز السفر أو شهادة المستشفى أو النسخة المصوّرة.","p":"صحيح. القاصرون المولودون في الولايات المتحدة يحتاجون إلى شهادة ميلاد أصلية أو مصدّقة."},"ref":{"doc":"AR","page":7}},{"id":"ar-036","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you finished a Motorcycle Safety Foundation RiderCourse. How long do you have to show the completion card to skip the motorcycle skills test?","o":["30 days","1 year","90 days","2 years"],"h1":"It is about three months.","h2":"In Arkansas you must show your RiderCourse completion card to a State Police examiner within 90 days to have the motorcycle skills test waived.","p":"Right. Bring the course card within 90 days to skip the skills test."},"es":{"q":"En Arkansas, usted terminó un curso RiderCourse de la Motorcycle Safety Foundation. ¿Cuánto tiempo tiene para mostrar la tarjeta del curso y no hacer la prueba práctica de motocicleta?","o":["30 días","1 año","90 días","2 años"],"h1":"Son unos tres meses.","h2":"En Arkansas usted debe mostrar la tarjeta del curso RiderCourse a un examinador de la Policía Estatal dentro de 90 días para que no le exijan la prueba práctica de motocicleta.","p":"Correcto. Lleve la tarjeta del curso dentro de 90 días para no hacer la prueba práctica."},"zh":{"q":"在 Arkansas，你完成了 Motorcycle Safety Foundation 的 RiderCourse 课程。你有多长时间出示结业卡，才能免考摩托车技能考试？","o":["30 天","1 年","90 天","2 年"],"h1":"大约三个月。","h2":"在 Arkansas，你必须在 90 天内把 RiderCourse 结业卡交给州警察考官，才能免考摩托车技能考试。","p":"对。在 90 天内带上课程结业卡，就可以免考技能考试。"},"vi":{"q":"Ở Arkansas, bạn đã hoàn thành khóa RiderCourse của Motorcycle Safety Foundation. Bạn có bao lâu để trình thẻ hoàn thành khóa học để được miễn bài thi kỹ năng lái xe máy?","o":["30 ngày","1 năm","90 ngày","2 năm"],"h1":"Khoảng ba tháng.","h2":"Ở Arkansas, bạn phải trình thẻ hoàn thành RiderCourse cho giám khảo của Cảnh sát Tiểu bang trong vòng 90 ngày để được miễn bài thi kỹ năng lái xe máy.","p":"Đúng. Mang thẻ khóa học đến trong vòng 90 ngày để được miễn bài thi kỹ năng."},"tl":{"q":"Sa Arkansas, natapos mo ang Motorcycle Safety Foundation RiderCourse. Gaano katagal ang mayroon ka para ipakita ang completion card para hindi na kumuha ng motorcycle skills test?","o":["30 araw","1 taon","90 araw","2 taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa Arkansas, dapat mong ipakita ang iyong RiderCourse completion card sa examiner ng State Police sa loob ng 90 araw para hindi ka na kumuha ng motorcycle skills test.","p":"Tama. Dalhin ang course card sa loob ng 90 araw para hindi na kumuha ng skills test."},"ar":{"q":"في Arkansas، أكملت دورة RiderCourse من Motorcycle Safety Foundation. كم من الوقت لديك لتقديم بطاقة إتمام الدورة حتى تُعفى من اختبار مهارات قيادة الدراجة النارية؟","o":["30 يومًا","سنة واحدة (1)","90 يومًا","سنتان (2)"],"h1":"المدة حوالي ثلاثة أشهر.","h2":"في Arkansas، يجب أن تقدّم بطاقة إتمام RiderCourse إلى فاحص من شرطة الولاية خلال 90 يومًا حتى تُعفى من اختبار مهارات قيادة الدراجة النارية.","p":"صحيح. أحضر بطاقة الدورة خلال 90 يومًا حتى تُعفى من اختبار المهارات."},"ref":{"doc":"AR","page":4}},{"id":"ar-037","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, a Motorized Bicycle Certificate lets a young rider drive a motorized bicycle or motorcycle up to what engine size?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"It is the smallest of these engine sizes.","h2":"In Arkansas, a Motorized Bicycle Certificate covers motorized bicycles and motorcycles of 50 cc or less.","p":"Right. The Motorized Bicycle Certificate is for engines of 50 cc or less."},"es":{"q":"En Arkansas, ¿hasta qué tamaño de motor permite un Certificado de Bicicleta Motorizada que un conductor joven maneje una bicicleta motorizada o motocicleta?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"Es el tamaño de motor más pequeño de estos.","h2":"En Arkansas, el Certificado de Bicicleta Motorizada cubre bicicletas motorizadas y motocicletas de 50 cc o menos.","p":"Correcto. El Certificado de Bicicleta Motorizada es para motores de 50 cc o menos."},"zh":{"q":"在 Arkansas，Motorized Bicycle Certificate 允许年轻骑手驾驶发动机最大多少排量的电动自行车或摩托车？","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"是这些排量中最小的一个。","h2":"在 Arkansas，Motorized Bicycle Certificate 适用于 50 cc 或以下的机动自行车和摩托车。","p":"对。Motorized Bicycle Certificate 适用于 50 cc 或以下的发动机。"},"vi":{"q":"Ở Arkansas, Motorized Bicycle Certificate cho phép người lái trẻ tuổi lái xe đạp gắn máy hoặc xe máy có động cơ tối đa bao nhiêu phân khối?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"Đây là dung tích động cơ nhỏ nhất trong các lựa chọn.","h2":"Ở Arkansas, Motorized Bicycle Certificate áp dụng cho xe đạp gắn máy và xe máy có động cơ 50 cc trở xuống.","p":"Đúng. Motorized Bicycle Certificate dành cho động cơ 50 cc trở xuống."},"tl":{"q":"Sa Arkansas, hanggang anong laki ng makina ng motorized bicycle o motorsiklo ang puwedeng imaneho ng batang rider na may Motorized Bicycle Certificate?","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"Ito ang pinakamaliit na laki ng makina sa mga pagpipilian.","h2":"Sa Arkansas, sakop ng Motorized Bicycle Certificate ang mga motorized bicycle at motorsiklo na 50 cc o mas mababa.","p":"Tama. Ang Motorized Bicycle Certificate ay para sa makinang 50 cc o mas mababa."},"ar":{"q":"في Arkansas، تسمح شهادة Motorized Bicycle Certificate للراكب الصغير بقيادة دراجة بمحرك أو دراجة نارية حتى أي حجم للمحرك؟","o":["125 cc","50 cc","250 cc","500 cc"],"h1":"هو أصغر حجم محرك بين هذه الخيارات.","h2":"في Arkansas، تشمل شهادة Motorized Bicycle Certificate الدراجات بمحرك والدراجات النارية التي حجم محركها 50 cc أو أقل.","p":"صحيح. شهادة Motorized Bicycle Certificate هي للمحركات التي حجمها 50 cc أو أقل."},"ref":{"doc":"AR","page":5}},{"id":"ar-038","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, what is the highest fine for a driver or front-seat passenger who does not wear a seat belt, not counting court costs?","o":["$100","$250","$500","$25"],"h1":"It is the smallest amount listed.","h2":"In Arkansas, not wearing a seat belt can bring a fine of up to $25, plus court costs.","p":"Right. The seat belt fine is up to $25, plus court costs."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta para un conductor o pasajero del asiento delantero que no usa el cinturón de seguridad, sin contar los costos del tribunal?","o":["$100","$250","$500","$25"],"h1":"Es la cantidad más pequeña de la lista.","h2":"En Arkansas, no usar el cinturón de seguridad puede traer una multa de hasta $25, más los costos del tribunal.","p":"Correcto. La multa por no usar el cinturón es de hasta $25, más los costos del tribunal."},"zh":{"q":"在 Arkansas，司机或前排乘客不系安全带，不算法庭费用，最高罚款是多少？","o":["$100","$250","$500","$25"],"h1":"是列出的金额中最小的。","h2":"在 Arkansas，不系安全带最高可被罚款 $25，另加法庭费用。","p":"对。不系安全带最高罚款 $25，另加法庭费用。"},"vi":{"q":"Ở Arkansas, mức phạt cao nhất cho tài xế hoặc hành khách ngồi ghế trước không thắt dây an toàn là bao nhiêu, chưa tính án phí?","o":["$100","$250","$500","$25"],"h1":"Đây là số tiền nhỏ nhất trong danh sách.","h2":"Ở Arkansas, không thắt dây an toàn có thể bị phạt tối đa $25, cộng thêm án phí.","p":"Đúng. Mức phạt không thắt dây an toàn tối đa là $25, cộng thêm án phí."},"tl":{"q":"Sa Arkansas, magkano ang pinakamataas na multa para sa driver o pasahero sa harap na hindi nagsusuot ng seat belt, hindi kasama ang court costs?","o":["$100","$250","$500","$25"],"h1":"Ito ang pinakamaliit na halaga sa listahan.","h2":"Sa Arkansas, ang hindi pagsusuot ng seat belt ay puwedeng magmulta nang hanggang $25, dagdag pa ang court costs.","p":"Tama. Hanggang $25 ang multa sa seat belt, dagdag pa ang court costs."},"ar":{"q":"في Arkansas، ما أعلى غرامة على السائق أو الراكب في المقعد الأمامي الذي لا يربط حزام الأمان، بدون حساب رسوم المحكمة؟","o":["$100","$250","$500","$25"],"h1":"هو أصغر مبلغ في القائمة.","h2":"في Arkansas، عدم ربط حزام الأمان قد يؤدي إلى غرامة تصل إلى $25، بالإضافة إلى رسوم المحكمة.","p":"صحيح. غرامة حزام الأمان تصل إلى $25، بالإضافة إلى رسوم المحكمة."},"ref":{"doc":"AR","page":9}},{"id":"ar-039","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, children under what age must wear a proper safety restraint whenever the car is moving?","o":["8","12","15","18"],"h1":"It is a teen age, three years before 18.","h2":"In Arkansas, all children under 15 must wear a proper safety restraint while the vehicle is moving.","p":"Right. Every child under 15 must be buckled up while the car moves."},"es":{"q":"En Arkansas, ¿los niños menores de qué edad deben usar un sistema de seguridad adecuado siempre que el auto esté en movimiento?","o":["8","12","15","18"],"h1":"Es una edad de adolescente, tres años antes de los 18.","h2":"En Arkansas, todos los niños menores de 15 años deben usar un sistema de seguridad adecuado mientras el vehículo está en movimiento.","p":"Correcto. Todo niño menor de 15 años debe ir abrochado mientras el auto se mueve."},"zh":{"q":"在 Arkansas，多少岁以下的儿童在车辆行驶时必须一直使用合适的安全约束装置？","o":["8","12","15","18"],"h1":"是一个青少年的年龄，比 18 岁小三岁。","h2":"在 Arkansas，所有 15 岁以下的儿童在车辆行驶时都必须使用合适的安全约束装置。","p":"对。车辆行驶时，每个 15 岁以下的儿童都必须系好。"},"vi":{"q":"Ở Arkansas, trẻ em dưới bao nhiêu tuổi phải dùng thiết bị an toàn phù hợp mỗi khi xe đang chạy?","o":["8","12","15","18"],"h1":"Đây là một độ tuổi thiếu niên, nhỏ hơn 18 ba tuổi.","h2":"Ở Arkansas, tất cả trẻ em dưới 15 tuổi phải dùng thiết bị an toàn phù hợp khi xe đang chạy.","p":"Đúng. Mọi trẻ em dưới 15 tuổi phải được thắt an toàn khi xe đang chạy."},"tl":{"q":"Sa Arkansas, ang mga batang wala pang ilang taong gulang ang dapat gumamit ng tamang safety restraint tuwing umaandar ang kotse?","o":["8","12","15","18"],"h1":"Edad ito ng isang teen, tatlong taon bago ang 18.","h2":"Sa Arkansas, lahat ng batang wala pang 15 taong gulang ay dapat gumamit ng tamang safety restraint habang umaandar ang sasakyan.","p":"Tama. Bawat batang wala pang 15 taong gulang ay dapat nakasuot ng seat belt o restraint habang umaandar ang kotse."},"ar":{"q":"في Arkansas، الأطفال الذين أعمارهم أقل من أي سن يجب أن يستخدموا وسيلة أمان مناسبة كلما كانت السيارة تتحرك؟","o":["8","12","15","18"],"h1":"هو سن مراهقة، قبل 18 بثلاث سنوات.","h2":"في Arkansas، يجب على كل الأطفال الذين أعمارهم أقل من 15 سنة أن يستخدموا وسيلة أمان مناسبة أثناء حركة المركبة.","p":"صحيح. يجب أن يكون كل طفل عمره أقل من 15 سنة مربوطًا أثناء حركة السيارة."},"ref":{"doc":"AR","page":9}},{"id":"ar-040","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, what is the highest fine for a first littering offense?","o":["$1,000","$50","$250","$5,000"],"h1":"It is a four-digit amount.","h2":"In Arkansas, a first littering conviction can bring a fine of up to $1,000 and up to eight hours of community service.","p":"Right. A first littering offense can cost up to $1,000."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por tirar basura por primera vez?","o":["$1,000","$50","$250","$5,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Arkansas, una primera condena por tirar basura puede traer una multa de hasta $1,000 y hasta ocho horas de servicio comunitario.","p":"Correcto. Tirar basura por primera vez puede costar hasta $1,000."},"zh":{"q":"在 Arkansas，第一次乱扔垃圾最高罚款是多少？","o":["$1,000","$50","$250","$5,000"],"h1":"是一个四位数的金额。","h2":"在 Arkansas，第一次乱扔垃圾被定罪，最高可罚款 $1,000，并做最多 8 小时的社区服务。","p":"对。第一次乱扔垃圾最高可罚 $1,000。"},"vi":{"q":"Ở Arkansas, mức phạt cao nhất cho lần đầu xả rác bừa bãi là bao nhiêu?","o":["$1,000","$50","$250","$5,000"],"h1":"Đây là số tiền có bốn chữ số.","h2":"Ở Arkansas, lần đầu bị kết tội xả rác bừa bãi có thể bị phạt tối đa $1,000 và tối đa tám giờ lao động công ích.","p":"Đúng. Lần đầu xả rác bừa bãi có thể bị phạt tới $1,000."},"tl":{"q":"Sa Arkansas, magkano ang pinakamataas na multa sa unang paglabag sa pagkakalat ng basura?","o":["$1,000","$50","$250","$5,000"],"h1":"Halaga ito na may apat na digit.","h2":"Sa Arkansas, ang unang conviction sa pagkakalat ng basura ay puwedeng magmulta nang hanggang $1,000 at hanggang walong oras ng community service.","p":"Tama. Ang unang paglabag sa pagkakalat ng basura ay puwedeng magmulta nang hanggang $1,000."},"ar":{"q":"في Arkansas، ما أعلى غرامة على أول مخالفة لرمي النفايات في الطريق؟","o":["$1,000","$50","$250","$5,000"],"h1":"هو مبلغ من أربعة أرقام.","h2":"في Arkansas، أول إدانة برمي النفايات قد تؤدي إلى غرامة تصل إلى $1,000 وخدمة مجتمعية تصل إلى ثماني ساعات.","p":"صحيح. أول مخالفة لرمي النفايات قد تكلّف حتى $1,000."},"ref":{"doc":"AR","page":10}},{"id":"ar-041","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, besides a fine, what can a court do to a driver who breaks the move-over law?","o":["Take away the driver's car for good","Revoke the license for life","Nothing else; only a fine is allowed","Suspend the driver's license for up to six months"],"h1":"The license can be affected for a limited time.","h2":"In Arkansas, a court can suspend the license of a driver who breaks the move-over law for up to six months, and can also order jail or community service.","p":"Right. Breaking the move-over law can cost you your license for up to six months."},"es":{"q":"En Arkansas, además de una multa, ¿qué puede hacer un tribunal a un conductor que no cumple la ley de cambiarse de carril (move over)?","o":["Quitarle el auto para siempre","Revocar la licencia de por vida","Nada más; solo se permite una multa","Suspender su licencia hasta por seis meses"],"h1":"La licencia puede verse afectada por un tiempo limitado.","h2":"En Arkansas, un tribunal puede suspender hasta por seis meses la licencia del conductor que no cumple la ley de cambiarse de carril, y también puede ordenar cárcel o servicio comunitario.","p":"Correcto. No cumplir esa ley puede costarle la licencia hasta por seis meses."},"zh":{"q":"在 Arkansas，除了罚款以外，法庭还可以怎样处罚违反“让道变道法”（move-over law）的司机？","o":["永久没收司机的车","终身吊销驾照","没有别的，只能罚款","暂停司机的驾照最长六个月"],"h1":"驾照可能会在一段有限的时间内受影响。","h2":"在 Arkansas，法庭可以把违反 move-over law 的司机的驾照暂停最长六个月，还可以判处监禁或社区服务。","p":"对。违反 move-over law 可能让你的驾照被暂停最长六个月。"},"vi":{"q":"Ở Arkansas, ngoài tiền phạt, tòa án có thể làm gì với tài xế vi phạm luật nhường làn (move-over law)?","o":["Tịch thu xe của tài xế vĩnh viễn","Thu hồi bằng lái suốt đời","Không gì khác; chỉ được phạt tiền","Đình chỉ bằng lái của tài xế tối đa sáu tháng"],"h1":"Bằng lái có thể bị ảnh hưởng trong một thời gian có giới hạn.","h2":"Ở Arkansas, tòa án có thể đình chỉ bằng lái của tài xế vi phạm move-over law tối đa sáu tháng, và cũng có thể ra lệnh ngồi tù hoặc lao động công ích.","p":"Đúng. Vi phạm move-over law có thể khiến bạn mất bằng lái tối đa sáu tháng."},"tl":{"q":"Sa Arkansas, bukod sa multa, ano pa ang puwedeng gawin ng korte sa driver na lumabag sa move-over law?","o":["Kunin nang tuluyan ang kotse ng driver","Bawiin ang lisensya habambuhay","Wala na; multa lang ang puwede","I-suspend ang lisensya ng driver nang hanggang anim na buwan"],"h1":"Puwedeng maapektuhan ang lisensya sa limitadong panahon.","h2":"Sa Arkansas, puwedeng i-suspend ng korte ang lisensya ng driver na lumabag sa move-over law nang hanggang anim na buwan, at puwede rin itong mag-utos ng kulong o community service.","p":"Tama. Ang paglabag sa move-over law ay puwedeng magpa-suspend ng lisensya mo nang hanggang anim na buwan."},"ar":{"q":"في Arkansas، بالإضافة إلى الغرامة، ماذا يمكن أن تفعل المحكمة بالسائق الذي يخالف قانون الابتعاد عن المركبات المتوقفة (move-over law)؟","o":["أخذ سيارة السائق إلى الأبد","إلغاء الرخصة مدى الحياة","لا شيء آخر؛ الغرامة فقط مسموحة","إيقاف رخصة السائق لمدة تصل إلى ستة أشهر"],"h1":"قد تتأثر الرخصة لمدة محدودة.","h2":"في Arkansas، يمكن للمحكمة أن توقف رخصة السائق الذي يخالف move-over law لمدة تصل إلى ستة أشهر، ويمكنها أيضًا أن تأمر بالسجن أو الخدمة المجتمعية.","p":"صحيح. مخالفة move-over law قد تكلّفك رخصتك لمدة تصل إلى ستة أشهر."},"ref":{"doc":"AR","page":11}},{"id":"ar-042","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, you get a ticket for a moving violation in a work zone while workers are present. What happens to the fine?","o":["It stays the same","It is doubled","It is cut in half","It is replaced by a warning"],"h1":"Work zone signs warn you about this.","h2":"In Arkansas, the fine for a moving violation in a work zone with workers present is doubled.","p":"Right. Fines double in work zones when workers are there."},"es":{"q":"En Arkansas, usted recibe una multa por una infracción en movimiento en una zona de construcción mientras hay trabajadores. ¿Qué pasa con la multa?","o":["Se queda igual","Se duplica","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Las señales de las zonas de construcción le avisan de esto.","h2":"En Arkansas, la multa por una infracción en movimiento en una zona de construcción con trabajadores presentes se duplica.","p":"Correcto. Las multas se duplican en zonas de construcción cuando hay trabajadores."},"zh":{"q":"在 Arkansas，你在有工人在场的施工区内因行车违规被开了罚单。罚款会怎样？","o":["保持不变","加倍","减半","改成警告"],"h1":"施工区的标志会提醒你这一点。","h2":"在 Arkansas，在有工人在场的施工区内行车违规，罚款会加倍。","p":"对。施工区有工人时，罚款加倍。"},"vi":{"q":"Ở Arkansas, bạn bị phạt vì vi phạm khi lái xe trong khu vực thi công khi có công nhân đang làm việc. Tiền phạt sẽ ra sao?","o":["Vẫn giữ nguyên","Bị tăng gấp đôi","Bị giảm một nửa","Được thay bằng một lời cảnh cáo"],"h1":"Các biển báo khu vực thi công cảnh báo bạn về điều này.","h2":"Ở Arkansas, tiền phạt cho vi phạm khi lái xe trong khu vực thi công có công nhân đang làm việc bị tăng gấp đôi.","p":"Đúng. Tiền phạt tăng gấp đôi trong khu vực thi công khi có công nhân."},"tl":{"q":"Sa Arkansas, nakakuha ka ng ticket para sa moving violation sa work zone habang may mga trabahador doon. Ano ang mangyayari sa multa?","o":["Mananatili itong pareho","Dodoblehin ito","Hahatiin ito sa kalahati","Papalitan ito ng babala"],"h1":"Binabalaan ka tungkol dito ng mga karatula sa work zone.","h2":"Sa Arkansas, dinodoble ang multa para sa moving violation sa work zone kapag may mga trabahador doon.","p":"Tama. Doble ang multa sa mga work zone kapag may mga trabahador."},"ar":{"q":"في Arkansas، حصلت على مخالفة قيادة في منطقة أشغال بينما كان العمّال موجودين. ماذا يحدث للغرامة؟","o":["تبقى كما هي","تتضاعف","تنخفض إلى النصف","تُستبدل بإنذار"],"h1":"لافتات منطقة الأشغال تحذّرك من هذا.","h2":"في Arkansas، تتضاعف غرامة مخالفة القيادة في منطقة أشغال يوجد فيها عمّال.","p":"صحيح. الغرامات تتضاعف في مناطق الأشغال عندما يكون العمّال موجودين."},"ref":{"doc":"AR","page":19}},{"id":"ar-043","scope":"AR","cat":"signals","sign":null,"c":0,"en":{"q":"In Arkansas, you see flashing green lights on a road maintenance truck. What do they tell you?","o":["Workers are active here, so slow down and use caution","You may go faster than the speed limit","The truck is about to turn left","The road ahead is closed to all traffic"],"h1":"These lights were added to make road crews easier to see.","h2":"In Arkansas, flashing green lights on a construction or maintenance vehicle mean an active work zone, so you should slow down and be careful.","p":"Right. Flashing green lights mean an active work zone: slow down."},"es":{"q":"En Arkansas, usted ve luces verdes intermitentes en un camión de mantenimiento de carreteras. ¿Qué le indican?","o":["Hay trabajadores activos aquí, así que reduzca la velocidad y tenga cuidado","Puede ir más rápido que el límite de velocidad","El camión va a girar a la izquierda","La carretera más adelante está cerrada a todo el tráfico"],"h1":"Estas luces se agregaron para que las cuadrillas de trabajo se vean mejor.","h2":"En Arkansas, las luces verdes intermitentes en un vehículo de construcción o mantenimiento indican una zona de trabajo activa, así que usted debe reducir la velocidad y tener cuidado.","p":"Correcto. Las luces verdes intermitentes indican una zona de trabajo activa: reduzca la velocidad."},"zh":{"q":"在 Arkansas，你看到一辆道路养护车上有闪烁的绿灯。这告诉你什么？","o":["这里有工人正在工作，所以要减速并小心","你可以超过限速行驶","这辆车马上要左转","前面的道路对所有车辆封闭"],"h1":"加这种灯是为了让道路工作人员更容易被看到。","h2":"在 Arkansas，施工车或养护车上的闪烁绿灯表示这是正在施工的区域，所以你应该减速并小心。","p":"对。闪烁的绿灯表示正在施工的区域：要减速。"},"vi":{"q":"Ở Arkansas, bạn thấy đèn xanh lá nhấp nháy trên một xe bảo trì đường. Đèn đó cho bạn biết điều gì?","o":["Có công nhân đang làm việc ở đây, vì vậy hãy chạy chậm lại và cẩn thận","Bạn có thể chạy nhanh hơn tốc độ giới hạn","Xe đó sắp rẽ trái","Đường phía trước bị đóng với mọi xe cộ"],"h1":"Loại đèn này được thêm vào để dễ nhìn thấy đội công nhân làm đường hơn.","h2":"Ở Arkansas, đèn xanh lá nhấp nháy trên xe thi công hoặc xe bảo trì có nghĩa là khu vực đang thi công, vì vậy bạn nên chạy chậm lại và cẩn thận.","p":"Đúng. Đèn xanh lá nhấp nháy có nghĩa là khu vực đang thi công: hãy chạy chậm lại."},"tl":{"q":"Sa Arkansas, nakakita ka ng kumikislap na berdeng ilaw sa isang truck na nag-aayos ng kalsada. Ano ang sinasabi nito sa iyo?","o":["May mga trabahador na nagtatrabaho rito, kaya bumagal at mag-ingat","Puwede kang lumampas sa speed limit","Liliko pakaliwa ang truck","Sarado ang kalsada sa unahan sa lahat ng sasakyan"],"h1":"Idinagdag ang mga ilaw na ito para mas madaling makita ang mga trabahador sa kalsada.","h2":"Sa Arkansas, ang kumikislap na berdeng ilaw sa sasakyang pang-construction o pang-maintenance ay nangangahulugang aktibong work zone, kaya dapat kang bumagal at mag-ingat.","p":"Tama. Ang kumikislap na berdeng ilaw ay nangangahulugang aktibong work zone: bumagal."},"ar":{"q":"في Arkansas، ترى أضواء خضراء وامضة على شاحنة صيانة طرق. ماذا تخبرك هذه الأضواء؟","o":["يوجد عمّال يعملون هنا، فخفّف السرعة وانتبه","يمكنك أن تسير أسرع من حد السرعة","الشاحنة على وشك أن تنعطف يسارًا","الطريق أمامك مغلق أمام كل المركبات"],"h1":"أُضيفت هذه الأضواء لكي يسهل رؤية عمّال الطرق.","h2":"في Arkansas، الأضواء الخضراء الوامضة على مركبة إنشاءات أو صيانة تعني أن هناك منطقة أشغال نشطة، لذلك يجب أن تخفّف السرعة وتنتبه.","p":"صحيح. الأضواء الخضراء الوامضة تعني منطقة أشغال نشطة: خفّف السرعة."},"ref":{"doc":"AR","page":18}},{"id":"ar-044","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, what is the speed limit on a county road when the county judge has not set one?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"It is between a city street speed and a highway speed.","h2":"In Arkansas, if the county judge has not set a speed limit on a county road, the limit is 40 mph.","p":"Right. An unposted county road has a 40 mph limit."},"es":{"q":"En Arkansas, ¿cuál es el límite de velocidad en un camino del condado cuando el juez del condado no ha fijado uno?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"Está entre la velocidad de una calle de ciudad y la de una carretera.","h2":"En Arkansas, si el juez del condado no ha fijado un límite de velocidad en un camino del condado, el límite es de 40 mph.","p":"Correcto. Un camino del condado sin límite fijado tiene un límite de 40 mph."},"zh":{"q":"在 Arkansas，如果县法官没有为县道设定限速，县道的限速是多少？","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"介于城市街道和公路的速度之间。","h2":"在 Arkansas，如果县法官没有为县道设定限速，限速就是 40 mph。","p":"对。没有限速标志的县道限速 40 mph。"},"vi":{"q":"Ở Arkansas, tốc độ giới hạn trên đường của quận là bao nhiêu khi thẩm phán quận chưa đặt ra?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"Tốc độ này nằm giữa tốc độ đường phố trong thành phố và tốc độ đường cao tốc.","h2":"Ở Arkansas, nếu thẩm phán quận chưa đặt tốc độ giới hạn cho đường của quận, thì giới hạn là 40 mph.","p":"Đúng. Đường của quận không có biển báo tốc độ có giới hạn 40 mph."},"tl":{"q":"Sa Arkansas, ano ang speed limit sa county road kapag hindi pa ito itinakda ng county judge?","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"Nasa pagitan ito ng bilis sa kalye ng lungsod at bilis sa highway.","h2":"Sa Arkansas, kung hindi pa nagtakda ng speed limit ang county judge sa isang county road, 40 mph ang limit.","p":"Tama. Ang county road na walang nakapaskil na limit ay may 40 mph na limit."},"ar":{"q":"في Arkansas، ما حد السرعة على طريق المقاطعة عندما لا يكون قاضي المقاطعة قد حدّد حدًّا له؟","o":["25 mph","55 mph","40 mph","65 mph"],"h1":"هو بين سرعة شوارع المدينة وسرعة الطرق السريعة.","h2":"في Arkansas، إذا لم يحدّد قاضي المقاطعة حدًّا للسرعة على طريق المقاطعة، فإن الحد هو 40 mph.","p":"صحيح. طريق المقاطعة الذي لا توجد عليه لافتة سرعة حدّه 40 mph."},"ref":{"doc":"AR","page":26}},{"id":"ar-045","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, you turn left out of a driveway onto a road with a shared center turn lane. How may you NOT use the center lane?","o":["As a short stop to wait for a gap","As part of your left turn","As a place to wait while turning left from the road","As a lane to speed up in before merging"],"h1":"You may pause there, but not build speed there.","h2":"In Arkansas you may use a shared center turn lane as part of a left turn to merge into traffic, but never as an acceleration lane.","p":"Right. The center turn lane is never an acceleration lane."},"es":{"q":"En Arkansas, usted gira a la izquierda al salir de una entrada de autos hacia una calle con un carril central compartido para girar. ¿Cómo NO puede usar el carril central?","o":["Como una parada corta para esperar un espacio","Como parte de su giro a la izquierda","Como lugar para esperar mientras gira a la izquierda desde la calle","Como carril para acelerar antes de incorporarse"],"h1":"Puede detenerse ahí un momento, pero no tomar velocidad ahí.","h2":"En Arkansas usted puede usar un carril central compartido como parte de un giro a la izquierda para incorporarse al tráfico, pero nunca como carril de aceleración.","p":"Correcto. El carril central para girar nunca es un carril de aceleración."},"zh":{"q":"在 Arkansas，你从车道左转驶上一条有共用中央转弯车道的道路。你不可以怎样使用中央车道？","o":["短暂停下来等待空当","作为你左转的一部分","在从道路上左转时在那里等待","作为并线前加速的车道"],"h1":"你可以在那里暂停，但不能在那里加速。","h2":"在 Arkansas，你可以把共用中央转弯车道作为左转并入车流的一部分，但绝不能把它当作加速车道。","p":"对。中央转弯车道绝不是加速车道。"},"vi":{"q":"Ở Arkansas, bạn rẽ trái từ lối xe vào nhà ra một con đường có làn rẽ chung ở giữa. Bạn KHÔNG được dùng làn giữa theo cách nào?","o":["Dừng ngắn để chờ khoảng trống","Làm một phần khi rẽ trái","Làm chỗ chờ khi rẽ trái từ con đường","Làm làn để tăng tốc trước khi nhập vào dòng xe"],"h1":"Bạn có thể dừng lại ở đó, nhưng không được tăng tốc ở đó.","h2":"Ở Arkansas, bạn có thể dùng làn rẽ chung ở giữa làm một phần khi rẽ trái để nhập vào dòng xe, nhưng không bao giờ được dùng nó làm làn tăng tốc.","p":"Đúng. Làn rẽ ở giữa không bao giờ là làn tăng tốc."},"tl":{"q":"Sa Arkansas, liliko ka pakaliwa mula sa driveway papunta sa kalsadang may shared center turn lane. Paano HINDI mo puwedeng gamitin ang center lane?","o":["Bilang maikling hintuan habang naghihintay ng puwang","Bilang bahagi ng iyong pagliko pakaliwa","Bilang lugar na hihintuan habang lumiliko pakaliwa mula sa kalsada","Bilang lane para bumilis bago sumanib sa trapiko"],"h1":"Puwede kang huminto roon sandali, pero hindi ka puwedeng bumilis doon.","h2":"Sa Arkansas, puwede mong gamitin ang shared center turn lane bilang bahagi ng pagliko pakaliwa para sumanib sa trapiko, pero hindi kailanman bilang acceleration lane.","p":"Tama. Hindi kailanman acceleration lane ang center turn lane."},"ar":{"q":"في Arkansas، تنعطف يسارًا من مدخل خاص إلى طريق فيه حارة انعطاف مشتركة في الوسط. كيف لا يجوز لك أن تستخدم الحارة الوسطى؟","o":["كمكان توقف قصير لانتظار فجوة","كجزء من انعطافك إلى اليسار","كمكان للانتظار أثناء الانعطاف يسارًا من الطريق","كحارة لزيادة السرعة قبل الاندماج"],"h1":"يمكنك أن تتوقف هناك قليلًا، لكن لا يجوز لك أن تزيد سرعتك هناك.","h2":"في Arkansas، يمكنك أن تستخدم حارة الانعطاف المشتركة في الوسط كجزء من الانعطاف يسارًا للاندماج في حركة المرور، لكن يجب ألّا تستخدمها أبدًا كحارة تسارع.","p":"صحيح. حارة الانعطاف في الوسط ليست أبدًا حارة تسارع."},"ref":{"doc":"AR","page":32}},{"id":"ar-046","scope":"AR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arkansas, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"Firefighters need room to reach it with a hose.","h2":"In Arkansas you may not park within 15 feet of a fire hydrant.","p":"Right. Park at least 15 feet away from a fire hydrant."},"es":{"q":"En Arkansas, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Los bomberos necesitan espacio para llegar a él con una manguera.","h2":"En Arkansas usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Estaciónese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Arkansas，你可以把车停在离消防栓多近的地方？","o":["不少于 5 英尺","不少于 15 英尺","不少于 50 英尺","不少于 100 英尺"],"h1":"消防员需要空间把水管接到消防栓上。","h2":"在 Arkansas，你不可以把车停在消防栓 15 英尺以内。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở Arkansas, bạn được đỗ xe gần trụ cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 100 feet"],"h1":"Lính cứu hỏa cần chỗ để nối vòi nước vào đó.","h2":"Ở Arkansas, bạn không được đỗ xe trong vòng 15 feet tính từ trụ cứu hỏa.","p":"Đúng. Đỗ xe cách trụ cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Arkansas, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ito ng hose.","h2":"Sa Arkansas, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Pumarada nang hindi bababa sa 15 talampakan ang layo mula sa fire hydrant."},"ar":{"q":"في Arkansas، إلى أي مدى يمكنك أن تركن قرب صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إليه بالخرطوم.","h2":"في Arkansas، يجب ألّا تركن على مسافة أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. اركن على بعد 15 قدمًا على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"AR","page":42}},{"id":"ar-047","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, how close to a stop sign, yield sign, or traffic light may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"Other drivers must be able to see the sign or light.","h2":"In Arkansas you may not park within 30 feet of a stop sign, yield sign, or traffic signal.","p":"Right. Stay at least 30 feet away from a stop sign, yield sign, or traffic light."},"es":{"q":"En Arkansas, ¿qué tan cerca de una señal de alto, una señal de ceda el paso o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Los demás conductores deben poder ver la señal o el semáforo.","h2":"En Arkansas usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso o un semáforo.","p":"Correcto. Manténgase por lo menos a 30 pies de una señal de alto, de ceda el paso o de un semáforo."},"zh":{"q":"在 Arkansas，你可以把车停在离停车标志、让行标志或交通灯多近的地方？","o":["不少于 5 英尺","不少于 10 英尺","不少于 30 英尺","不少于 100 英尺"],"h1":"其他司机必须能看到标志或信号灯。","h2":"在 Arkansas，你不可以把车停在停车标志、让行标志或交通信号灯 30 英尺以内。","p":"对。离停车标志、让行标志或交通灯至少 30 英尺。"},"vi":{"q":"Ở Arkansas, bạn được đỗ xe gần biển dừng, biển nhường đường hoặc đèn giao thông đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 30 feet","Không gần hơn 100 feet"],"h1":"Các tài xế khác phải nhìn thấy được biển báo hoặc đèn.","h2":"Ở Arkansas, bạn không được đỗ xe trong vòng 30 feet tính từ biển dừng, biển nhường đường hoặc đèn tín hiệu giao thông.","p":"Đúng. Đỗ xe cách biển dừng, biển nhường đường hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Arkansas, gaano kalapit sa stop sign, yield sign, o traffic light ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 30 talampakan","Hindi lalapit sa 100 talampakan"],"h1":"Dapat makita ng ibang driver ang karatula o ilaw.","h2":"Sa Arkansas, hindi ka puwedeng pumarada sa loob ng 30 talampakan mula sa stop sign, yield sign, o traffic signal.","p":"Tama. Lumayo nang hindi bababa sa 30 talampakan mula sa stop sign, yield sign, o traffic light."},"ar":{"q":"في Arkansas، إلى أي مدى يمكنك أن تركن قرب لافتة قف أو لافتة أفضلية المرور أو إشارة المرور؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 100 قدم"],"h1":"يجب أن يتمكن السائقون الآخرون من رؤية اللافتة أو الإشارة.","h2":"في Arkansas، يجب ألّا تركن على مسافة أقل من 30 قدمًا من لافتة قف أو لافتة أفضلية المرور أو إشارة المرور.","p":"صحيح. ابقَ على بعد 30 قدمًا على الأقل من لافتة قف أو لافتة أفضلية المرور أو إشارة المرور."},"ref":{"doc":"AR","page":42}},{"id":"ar-048","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, it is raining and you need your windshield wipers. What does state law also require?","o":["Turn on your headlights","Turn on your hazard lights","Use only your parking lights","Turn on your high beams"],"h1":"Think about being seen by other drivers.","h2":"Arkansas law requires you to turn on your headlights whenever you need your windshield wipers.","p":"Right. Wipers on means headlights on in Arkansas."},"es":{"q":"En Arkansas, está lloviendo y usted necesita los limpiaparabrisas. ¿Qué más exige la ley del estado?","o":["Encender los faros delanteros","Encender las luces de emergencia","Usar solo las luces de estacionamiento","Encender las luces altas"],"h1":"Piense en que los demás conductores lo vean.","h2":"La ley de Arkansas exige encender los faros delanteros siempre que usted necesite los limpiaparabrisas.","p":"Correcto. En Arkansas, si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 Arkansas，正在下雨，你需要用雨刷。州法律还要求你做什么？","o":["打开前大灯","打开危险警示灯","只用停车灯","打开远光灯"],"h1":"想一想怎样让其他司机看到你。","h2":"Arkansas 法律要求你在需要使用雨刷时打开前大灯。","p":"对。在 Arkansas，开雨刷就要开大灯。"},"vi":{"q":"Ở Arkansas, trời đang mưa và bạn cần dùng cần gạt nước. Luật tiểu bang còn yêu cầu điều gì?","o":["Bật đèn pha","Bật đèn cảnh báo nguy hiểm","Chỉ dùng đèn đỗ xe","Bật đèn chiếu xa"],"h1":"Hãy nghĩ đến việc để các tài xế khác nhìn thấy bạn.","h2":"Luật Arkansas yêu cầu bạn bật đèn pha bất cứ khi nào bạn cần dùng cần gạt nước.","p":"Đúng. Ở Arkansas, bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Arkansas, umuulan at kailangan mo ang windshield wipers. Ano pa ang hinihingi ng batas ng estado?","o":["Buksan ang headlights","Buksan ang hazard lights","Parking lights lang ang gamitin","Buksan ang high beams"],"h1":"Isipin kung paano ka makikita ng ibang driver.","h2":"Hinihingi ng batas ng Arkansas na buksan mo ang headlights tuwing kailangan mo ang windshield wipers.","p":"Tama. Sa Arkansas, kapag bukas ang wipers, dapat bukas din ang headlights."},"ar":{"q":"في Arkansas، السماء تمطر وتحتاج إلى مسّاحات الزجاج الأمامي. ماذا يتطلب قانون الولاية أيضًا؟","o":["أشعل المصابيح الأمامية","أشعل أضواء التحذير","استخدم أضواء الركن فقط","أشعل الأضواء العالية"],"h1":"فكّر في أن يراك السائقون الآخرون.","h2":"يتطلب قانون Arkansas أن تشعل المصابيح الأمامية كلما احتجت إلى مسّاحات الزجاج الأمامي.","p":"صحيح. في Arkansas، إذا شغّلت المسّاحات فيجب أن تشعل المصابيح الأمامية."},"ref":{"doc":"AR","page":51}},{"id":"ar-049","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, you see a bicycle with a red or orange pennant flag on it. What does the flag tell you?","o":["The rider is in a race","The bicycle has an engine","The rider is about to turn left","The rider has trouble hearing, so slow down"],"h1":"The flag tells you something about the rider, not the bike.","h2":"In Arkansas, a red or orange pennant flag on a bicycle means the rider has impaired hearing, so you should slow down.","p":"Right. A red or orange flag on a bike means the rider may not hear you."},"es":{"q":"En Arkansas, usted ve una bicicleta con una bandera triangular roja o anaranjada. ¿Qué le indica la bandera?","o":["El ciclista está en una carrera","La bicicleta tiene motor","El ciclista va a girar a la izquierda","El ciclista tiene problemas de audición, así que reduzca la velocidad"],"h1":"La bandera le dice algo sobre el ciclista, no sobre la bicicleta.","h2":"En Arkansas, una bandera triangular roja o anaranjada en una bicicleta significa que el ciclista tiene problemas de audición, así que usted debe reducir la velocidad.","p":"Correcto. Una bandera roja o anaranjada en una bicicleta indica que el ciclista quizás no lo oiga."},"zh":{"q":"在 Arkansas，你看到一辆自行车上插着红色或橙色的三角旗。这面旗告诉你什么？","o":["骑车人在参加比赛","这辆自行车有发动机","骑车人马上要左转","骑车人听力不好，所以要减速"],"h1":"这面旗告诉你的是骑车人的情况，而不是自行车的情况。","h2":"在 Arkansas，自行车上的红色或橙色三角旗表示骑车人听力有障碍，所以你应该减速。","p":"对。自行车上的红色或橙色旗子表示骑车人可能听不到你。"},"vi":{"q":"Ở Arkansas, bạn thấy một chiếc xe đạp có cắm cờ đuôi nheo màu đỏ hoặc cam. Lá cờ đó cho bạn biết điều gì?","o":["Người đạp xe đang đua","Xe đạp có động cơ","Người đạp xe sắp rẽ trái","Người đạp xe bị khó nghe, vì vậy hãy chạy chậm lại"],"h1":"Lá cờ cho bạn biết điều gì đó về người đạp xe, không phải về chiếc xe.","h2":"Ở Arkansas, cờ đuôi nheo màu đỏ hoặc cam trên xe đạp có nghĩa là người đạp xe bị suy giảm thính lực, vì vậy bạn nên chạy chậm lại.","p":"Đúng. Cờ đỏ hoặc cam trên xe đạp có nghĩa là người đạp xe có thể không nghe thấy bạn."},"tl":{"q":"Sa Arkansas, nakakita ka ng bisikleta na may pulang o orange na pennant flag. Ano ang sinasabi sa iyo ng flag?","o":["Kasali sa karera ang siklista","May makina ang bisikleta","Liliko pakaliwa ang siklista","Nahihirapang makarinig ang siklista, kaya bumagal"],"h1":"May sinasabi ang flag tungkol sa siklista, hindi sa bisikleta.","h2":"Sa Arkansas, ang pula o orange na pennant flag sa bisikleta ay nangangahulugang may problema sa pandinig ang siklista, kaya dapat kang bumagal.","p":"Tama. Ang pula o orange na flag sa bisikleta ay nangangahulugang baka hindi ka marinig ng siklista."},"ar":{"q":"في Arkansas، ترى درّاجة هوائية عليها علم مثلث أحمر أو برتقالي. ماذا يخبرك هذا العلم؟","o":["راكب الدرّاجة في سباق","الدرّاجة فيها محرك","راكب الدرّاجة على وشك أن ينعطف يسارًا","راكب الدرّاجة يجد صعوبة في السمع، فخفّف السرعة"],"h1":"العلم يخبرك بشيء عن الراكب، وليس عن الدرّاجة.","h2":"في Arkansas، العلم المثلث الأحمر أو البرتقالي على الدرّاجة يعني أن راكبها ضعيف السمع، لذلك يجب أن تخفّف السرعة.","p":"صحيح. العلم الأحمر أو البرتقالي على الدرّاجة يعني أن الراكب قد لا يسمعك."},"ref":{"doc":"AR","page":68}},{"id":"ar-050","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, what fine can a driver face for a first conviction of driving while intoxicated, not counting court costs?","o":["$25 to $100","$150 to $1,000","$5,000 to $10,000","No fine, only a warning"],"h1":"The top of the range is a four-digit amount.","h2":"In Arkansas, a first DWI conviction brings a fine of $150 to $1,000, plus court costs.","p":"Right. A first DWI can cost $150 to $1,000 in fines."},"es":{"q":"En Arkansas, ¿qué multa puede recibir un conductor por una primera condena por manejar en estado de ebriedad (DWI), sin contar los costos del tribunal?","o":["De $25 a $100","De $150 a $1,000","De $5,000 a $10,000","Ninguna multa, solo una advertencia"],"h1":"El máximo es una cantidad de cuatro cifras.","h2":"En Arkansas, una primera condena por DWI trae una multa de $150 a $1,000, más los costos del tribunal.","p":"Correcto. Un primer DWI puede costar de $150 a $1,000 en multas."},"zh":{"q":"在 Arkansas，司机第一次因醉酒驾驶被定罪，不算法庭费用，可能面临多少罚款？","o":["$25 到 $100","$150 到 $1,000","$5,000 到 $10,000","没有罚款，只有警告"],"h1":"这个范围的最高额是一个四位数的金额。","h2":"在 Arkansas，第一次 DWI 被定罪会被罚款 $150 到 $1,000，另加法庭费用。","p":"对。第一次 DWI 可能被罚 $150 到 $1,000。"},"vi":{"q":"Ở Arkansas, tài xế có thể bị phạt bao nhiêu khi bị kết tội lần đầu vì lái xe trong lúc say rượu, chưa tính án phí?","o":["$25 đến $100","$150 đến $1,000","$5,000 đến $10,000","Không phạt tiền, chỉ cảnh cáo"],"h1":"Mức cao nhất của khoảng này là số tiền có bốn chữ số.","h2":"Ở Arkansas, lần đầu bị kết tội DWI sẽ bị phạt từ $150 đến $1,000, cộng thêm án phí.","p":"Đúng. Lần đầu DWI có thể bị phạt từ $150 đến $1,000."},"tl":{"q":"Sa Arkansas, magkanong multa ang puwedeng harapin ng driver sa unang conviction sa pagmamaneho nang lasing, hindi kasama ang court costs?","o":["$25 hanggang $100","$150 hanggang $1,000","$5,000 hanggang $10,000","Walang multa, babala lang"],"h1":"Ang pinakamataas sa saklaw ay halagang may apat na digit.","h2":"Sa Arkansas, ang unang DWI conviction ay may multang $150 hanggang $1,000, dagdag pa ang court costs.","p":"Tama. Ang unang DWI ay puwedeng magmulta ng $150 hanggang $1,000."},"ar":{"q":"في Arkansas، ما الغرامة التي قد يواجهها السائق عند أول إدانة بالقيادة تحت تأثير الكحول، بدون حساب رسوم المحكمة؟","o":["من $25 إلى $100","من $150 إلى $1,000","من $5,000 إلى $10,000","لا غرامة، إنذار فقط"],"h1":"الحد الأعلى في هذا النطاق مبلغ من أربعة أرقام.","h2":"في Arkansas، أول إدانة بـ DWI تؤدي إلى غرامة من $150 إلى $1,000، بالإضافة إلى رسوم المحكمة.","p":"صحيح. أول DWI قد يكلّف غرامة من $150 إلى $1,000."},"ref":{"doc":"AR","page":74}},{"id":"ar-051","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a police officer asks you to take an alcohol test. Who chooses which kind of test you take?","o":["You, the driver","A judge, later in court","The police officer","Your insurance company"],"h1":"It is the person who asks you to take the test.","h2":"In Arkansas, the law enforcement officer chooses which alcohol test to request, and you can lose your license if you refuse.","p":"Right. The officer picks the test, and refusing can cost you your license."},"es":{"q":"En Arkansas, un policía le pide que se haga una prueba de alcohol. ¿Quién elige qué tipo de prueba se hace?","o":["Usted, el conductor","Un juez, más tarde en el tribunal","El policía","Su compañía de seguros"],"h1":"Es la persona que le pide que se haga la prueba.","h2":"En Arkansas, el agente de la ley elige qué prueba de alcohol pedir, y usted puede perder la licencia si se niega.","p":"Correcto. El policía elige la prueba, y negarse le puede costar la licencia."},"zh":{"q":"在 Arkansas，警察要求你做酒精测试。由谁来选择你做哪一种测试？","o":["你，司机","法官，之后在法庭上","警察","你的保险公司"],"h1":"就是要求你做测试的那个人。","h2":"在 Arkansas，由执法警察选择要求你做哪一种酒精测试，如果你拒绝，可能会失去驾照。","p":"对。由警察选择测试，拒绝可能让你失去驾照。"},"vi":{"q":"Ở Arkansas, cảnh sát yêu cầu bạn làm xét nghiệm nồng độ cồn. Ai chọn loại xét nghiệm bạn phải làm?","o":["Bạn, người lái xe","Một thẩm phán, sau đó tại tòa","Viên cảnh sát","Công ty bảo hiểm của bạn"],"h1":"Đó là người yêu cầu bạn làm xét nghiệm.","h2":"Ở Arkansas, nhân viên thực thi pháp luật chọn loại xét nghiệm nồng độ cồn để yêu cầu, và bạn có thể bị mất bằng lái nếu từ chối.","p":"Đúng. Cảnh sát chọn loại xét nghiệm, và từ chối có thể khiến bạn mất bằng lái."},"tl":{"q":"Sa Arkansas, hiniling sa iyo ng pulis na kumuha ng alcohol test. Sino ang pumipili kung anong uri ng test ang kukunin mo?","o":["Ikaw, ang driver","Isang judge, sa korte mamaya","Ang pulis","Ang kompanya ng insurance mo"],"h1":"Ito ang taong humihiling sa iyo na kumuha ng test.","h2":"Sa Arkansas, ang law enforcement officer ang pumipili kung aling alcohol test ang hihilingin, at puwede kang mawalan ng lisensya kung tatanggi ka.","p":"Tama. Ang pulis ang pumipili ng test, at ang pagtanggi ay puwedeng magpawala ng lisensya mo."},"ar":{"q":"في Arkansas، يطلب منك شرطي أن تخضع لاختبار الكحول. من يختار نوع الاختبار الذي تخضع له؟","o":["أنت، السائق","قاضٍ، لاحقًا في المحكمة","الشرطي","شركة التأمين الخاصة بك"],"h1":"هو الشخص الذي يطلب منك أن تخضع للاختبار.","h2":"في Arkansas، ضابط إنفاذ القانون هو الذي يختار اختبار الكحول الذي يطلبه، وقد تفقد رخصتك إذا رفضت.","p":"صحيح. الشرطي يختار الاختبار، والرفض قد يكلّفك رخصتك."},"ref":{"doc":"AR","page":74}},{"id":"ar-052","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, when may a person with epilepsy drive?","o":["When under a doctor's care and seizure-free for one year","Never, for any reason","Only with another adult in the car","Only during daylight hours"],"h1":"Two things are needed: medical care and a stretch of time.","h2":"In Arkansas, a person with epilepsy may drive if they are under a doctor's care and have been seizure-free for one year.","p":"Right. With a doctor's care and one year without a seizure, a person with epilepsy may drive."},"es":{"q":"En Arkansas, ¿cuándo puede manejar una persona con epilepsia?","o":["Cuando está bajo el cuidado de un médico y lleva un año sin convulsiones","Nunca, por ninguna razón","Solo con otro adulto en el auto","Solo durante el día"],"h1":"Se necesitan dos cosas: atención médica y cierto tiempo.","h2":"En Arkansas, una persona con epilepsia puede manejar si está bajo el cuidado de un médico y lleva un año sin convulsiones.","p":"Correcto. Con atención médica y un año sin convulsiones, una persona con epilepsia puede manejar."},"zh":{"q":"在 Arkansas，癫痫患者什么时候可以开车？","o":["在医生照顾下，并且一年没有发作","永远不可以，无论什么原因","只有车里有另一位成年人时","只有在白天"],"h1":"需要两样东西：医疗照顾和一段时间。","h2":"在 Arkansas，癫痫患者如果在医生照顾下，并且一年没有发作，就可以开车。","p":"对。在医生照顾下并且一年没有发作，癫痫患者就可以开车。"},"vi":{"q":"Ở Arkansas, khi nào người bị động kinh được lái xe?","o":["Khi đang được bác sĩ theo dõi và không lên cơn trong một năm","Không bao giờ, vì bất kỳ lý do nào","Chỉ khi có một người lớn khác trong xe","Chỉ vào ban ngày"],"h1":"Cần hai điều: được chăm sóc y tế và một khoảng thời gian.","h2":"Ở Arkansas, người bị động kinh được lái xe nếu đang được bác sĩ theo dõi và đã không lên cơn trong một năm.","p":"Đúng. Khi được bác sĩ theo dõi và một năm không lên cơn, người bị động kinh được lái xe."},"tl":{"q":"Sa Arkansas, kailan puwedeng magmaneho ang taong may epilepsy?","o":["Kapag nasa pangangalaga ng doktor at walang seizure nang isang taon","Hindi kailanman, sa anumang dahilan","Kapag may kasama lang na ibang adult sa kotse","Sa araw lang"],"h1":"Dalawang bagay ang kailangan: pangangalagang medikal at isang yugto ng panahon.","h2":"Sa Arkansas, puwedeng magmaneho ang taong may epilepsy kung nasa pangangalaga siya ng doktor at walang seizure nang isang taon.","p":"Tama. Kapag nasa pangangalaga ng doktor at isang taong walang seizure, puwedeng magmaneho ang taong may epilepsy."},"ar":{"q":"في Arkansas، متى يمكن لشخص مصاب بالصرع أن يقود؟","o":["عندما يكون تحت رعاية طبيب ولم تأتِه نوبة لمدة سنة واحدة","أبدًا، لأي سبب","فقط عندما يكون معه شخص بالغ آخر في السيارة","فقط في ساعات النهار"],"h1":"هناك أمران مطلوبان: رعاية طبية ومدة من الوقت.","h2":"في Arkansas، يمكن للشخص المصاب بالصرع أن يقود إذا كان تحت رعاية طبيب ولم تأتِه أي نوبة لمدة سنة واحدة.","p":"صحيح. مع رعاية الطبيب وسنة واحدة بدون نوبة، يمكن للشخص المصاب بالصرع أن يقود."},"ref":{"doc":"AR","page":72}},{"id":"ar-053","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, how much is the fee for each written knowledge exam you take?","o":["$20","$50","$5","$1"],"h1":"It is a small amount, added to the cost of your license.","h2":"In Arkansas, each written exam costs $5, and the fee is added to the cost of your driver's license.","p":"Right. Each written exam costs $5."},"es":{"q":"En Arkansas, ¿cuánto cuesta cada examen escrito de conocimientos que usted toma?","o":["$20","$50","$5","$1"],"h1":"Es una cantidad pequeña que se suma al costo de su licencia.","h2":"En Arkansas, cada examen escrito cuesta $5, y ese cargo se suma al costo de su licencia de conducir.","p":"Correcto. Cada examen escrito cuesta $5."},"ref":{"doc":"AR","page":1}},{"id":"ar-054","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, a nonresident has been living in the state for a while. After how long must that person get an Arkansas driver's license?","o":["6 months","10 days","2 years","5 years"],"h1":"It is half of a year.","h2":"In Arkansas, a nonresident who has been physically present in the state for six months must get an Arkansas driver's license.","p":"Right. A nonresident must get an Arkansas license after six months in the state."},"es":{"q":"En Arkansas, una persona no residente lleva un tiempo viviendo en el estado. ¿Después de cuánto tiempo debe obtener una licencia de conducir de Arkansas?","o":["6 meses","10 días","2 años","5 años"],"h1":"Es la mitad de un año.","h2":"En Arkansas, una persona no residente que ha estado presente en el estado por seis meses debe obtener una licencia de conducir de Arkansas.","p":"Correcto. Un no residente debe obtener una licencia de Arkansas después de seis meses en el estado."},"ref":{"doc":"AR","page":2}},{"id":"ar-055","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, you want to trade in a driver's license from another state. How long may it have been expired?","o":["No more than 1 year","No more than 5 years","Any length of time","No more than 30 days"],"h1":"It is about one month.","h2":"In Arkansas, a license from another state used to get an Arkansas license cannot be expired for more than 30 days.","p":"Right. An out-of-state license may be expired no more than 30 days."},"es":{"q":"En Arkansas, usted quiere cambiar una licencia de conducir de otro estado. ¿Cuánto tiempo puede llevar vencida?","o":["No más de 1 año","No más de 5 años","Cualquier cantidad de tiempo","No más de 30 días"],"h1":"Es más o menos un mes.","h2":"En Arkansas, la licencia de otro estado que se usa para obtener una licencia de Arkansas no puede llevar más de 30 días vencida.","p":"Correcto. Una licencia de otro estado puede estar vencida no más de 30 días."},"ref":{"doc":"AR","page":2}},{"id":"ar-056","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, which of these would keep you from getting a driver's license?","o":["Owning a car that is registered in another state","A pending court judgment for a moving traffic violation","Working at a job in a nearby state","Being younger than 25 years old"],"h1":"Think about unfinished business with a traffic court.","h2":"In Arkansas, you cannot get a driver's license while you have a judgment pending for a moving traffic violation.","p":"Right. A pending judgment for a moving violation blocks a new license."},"es":{"q":"En Arkansas, ¿cuál de estas situaciones le impediría obtener una licencia de conducir?","o":["Tener un auto registrado en otro estado","Tener pendiente un fallo judicial por una infracción de tránsito en movimiento","Trabajar en un estado cercano","Tener menos de 25 años"],"h1":"Piense en asuntos sin resolver con un tribunal de tránsito.","h2":"En Arkansas, usted no puede obtener una licencia de conducir mientras tenga pendiente un fallo por una infracción de tránsito en movimiento.","p":"Correcto. Un fallo pendiente por una infracción en movimiento impide obtener la licencia."},"ref":{"doc":"AR","page":2}},{"id":"ar-057","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, a teen with an instruction permit is driving. Where must the licensed driver who is 21 or older sit?","o":["In the back seat","In the seat beside the driver","Anywhere in the car","In another car following behind"],"h1":"The supervisor must be close enough to help right away.","h2":"In Arkansas, the licensed driver who is 21 or older must sit in the seat beside a driver who has an instruction permit.","p":"Right. The supervising driver sits right beside the permit holder."},"es":{"q":"En Arkansas, un adolescente con permiso de instrucción está manejando. ¿Dónde debe sentarse el conductor con licencia de 21 años o más?","o":["En el asiento de atrás","En el asiento al lado del conductor","En cualquier lugar del auto","En otro auto que va detrás"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Arkansas, el conductor con licencia de 21 años o más debe sentarse en el asiento al lado del conductor que tiene permiso de instrucción.","p":"Correcto. El conductor supervisor se sienta justo al lado de quien tiene el permiso."},"ref":{"doc":"AR","page":3}},{"id":"ar-058","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, which tests must you pass to get an instruction permit?","o":["Only the driving skills test","A hearing test and the skills test","No tests, only a signed form","The knowledge exam and the vision test"],"h1":"One test is written, and one checks your eyes.","h2":"In Arkansas, you must pass the knowledge exam and the vision test to get an instruction permit.","p":"Right. The permit needs the knowledge exam and the vision test."},"es":{"q":"En Arkansas, ¿qué pruebas debe aprobar para obtener un permiso de instrucción?","o":["Solo la prueba práctica de manejo","Una prueba de audición y la prueba práctica","Ninguna prueba, solo un formulario firmado","El examen de conocimientos y la prueba de la vista"],"h1":"Una prueba es escrita y la otra revisa sus ojos.","h2":"En Arkansas, usted debe aprobar el examen de conocimientos y la prueba de la vista para obtener un permiso de instrucción.","p":"Correcto. El permiso requiere el examen de conocimientos y la prueba de la vista."},"ref":{"doc":"AR","page":3}},{"id":"ar-059","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, a driver with an instruction permit is at the wheel. Who in the car must wear a seat belt?","o":["Every passenger in the car","Only the driver","Only people in the front seat","Only children under 6"],"h1":"The rule for permit drivers is wider than the usual seat belt law.","h2":"In Arkansas, every passenger in a vehicle driven by someone with an instruction permit must wear a seat belt.","p":"Right. With a permit driver, everyone in the car buckles up."},"es":{"q":"En Arkansas, un conductor con permiso de instrucción está manejando. ¿Quién en el auto debe usar el cinturón de seguridad?","o":["Todos los pasajeros del auto","Solo el conductor","Solo las personas del asiento delantero","Solo los niños menores de 6 años"],"h1":"La regla para quienes manejan con permiso es más amplia que la ley normal del cinturón.","h2":"En Arkansas, todos los pasajeros de un vehículo manejado por alguien con permiso de instrucción deben usar el cinturón de seguridad.","p":"Correcto. Con un conductor con permiso, todos en el auto se abrochan el cinturón."},"ref":{"doc":"AR","page":3}},{"id":"ar-060","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you passed all of your driver's license tests. Where do you go to get the license itself?","o":["A driving school","Your county courthouse","Any Arkansas Revenue Office","Your insurance agent"],"h1":"The tests and the license come from different offices.","h2":"In Arkansas, after you pass the tests, you go to any Arkansas Revenue Office to get your license.","p":"Right. Licenses are issued at Arkansas Revenue Offices."},"es":{"q":"En Arkansas, usted aprobó todas las pruebas para la licencia de conducir. ¿A dónde va para recibir la licencia?","o":["A una escuela de manejo","Al tribunal de su condado","A cualquier Oficina de Ingresos (Revenue Office) de Arkansas","A su agente de seguros"],"h1":"Las pruebas y la licencia vienen de oficinas diferentes.","h2":"En Arkansas, después de aprobar las pruebas, usted va a cualquier Oficina de Ingresos (Revenue Office) de Arkansas para recibir su licencia.","p":"Correcto. Las licencias se entregan en las Oficinas de Ingresos de Arkansas."},"ref":{"doc":"AR","page":3}},{"id":"ar-061","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what license do you need to drive a vehicle designed to carry 16 or more passengers?","o":["A Commercial Driver's License (CDL)","A regular Class D license","A Class M license","An intermediate license"],"h1":"Large passenger vehicles need a special license.","h2":"In Arkansas, any vehicle designed to carry 16 or more passengers requires a Commercial Driver's License, or CDL.","p":"Right. A vehicle for 16 or more passengers needs a CDL."},"es":{"q":"En Arkansas, ¿qué licencia necesita para manejar un vehículo diseñado para llevar 16 pasajeros o más?","o":["Una licencia de conducir comercial (CDL)","Una licencia normal Clase D","Una licencia Clase M","Una licencia intermedia"],"h1":"Los vehículos grandes de pasajeros necesitan una licencia especial.","h2":"En Arkansas, cualquier vehículo diseñado para llevar 16 pasajeros o más requiere una licencia de conducir comercial, o CDL.","p":"Correcto. Un vehículo para 16 pasajeros o más necesita una CDL."},"ref":{"doc":"AR","page":3}},{"id":"ar-062","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, what is the youngest age for a Class M (motorcycle) license?","o":["14","18","21","16"],"h1":"It is the same age as the intermediate car license.","h2":"In Arkansas, the Class M motorcycle license is issued to people 16 and older.","p":"Right. You can get a Class M license at 16."},"es":{"q":"En Arkansas, ¿cuál es la edad mínima para una licencia Clase M (motocicleta)?","o":["14","18","21","16"],"h1":"Es la misma edad que la licencia intermedia de auto.","h2":"En Arkansas, la licencia de motocicleta Clase M se entrega a personas de 16 años o más.","p":"Correcto. Puede obtener una licencia Clase M a los 16 años."},"ref":{"doc":"AR","page":4}},{"id":"ar-063","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, you passed the motorcycle knowledge exam. How long is that passed exam good for?","o":["30 days","One year","Five years","For life"],"h1":"You have a set time to finish the vision and skills tests.","h2":"In Arkansas, a passed motorcycle knowledge exam is valid for one year.","p":"Right. The motorcycle knowledge exam is good for one year."},"es":{"q":"En Arkansas, usted aprobó el examen de conocimientos de motocicleta. ¿Por cuánto tiempo vale ese examen aprobado?","o":["30 días","Un año","Cinco años","Toda la vida"],"h1":"Tiene un tiempo fijo para terminar la prueba de la vista y la prueba práctica.","h2":"En Arkansas, un examen de conocimientos de motocicleta aprobado es válido por un año.","p":"Correcto. El examen de conocimientos de motocicleta vale por un año."},"ref":{"doc":"AR","page":4}},{"id":"ar-064","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a Class MD (motor-driven cycle) license for ages 14 to 16 limits riders to motorcycles of what engine size?","o":["100 cc or less","500 cc or less","250 cc or less","1,000 cc or less"],"h1":"It is larger than the motorized bicycle limit but still a small bike.","h2":"In Arkansas, the Class MD license is limited to motorcycles of 250 cc or less.","p":"Right. Class MD riders are limited to 250 cc or less."},"es":{"q":"En Arkansas, la licencia Clase MD (ciclomotor) para edades de 14 a 16 años, ¿a motocicletas de qué tamaño de motor limita al conductor?","o":["100 cc o menos","500 cc o menos","250 cc o menos","1,000 cc o menos"],"h1":"Es más grande que el límite de la bicicleta motorizada, pero sigue siendo una moto pequeña.","h2":"En Arkansas, la licencia Clase MD se limita a motocicletas de 250 cc o menos.","p":"Correcto. Con la Clase MD solo puede manejar motos de 250 cc o menos."},"ref":{"doc":"AR","page":4}},{"id":"ar-065","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what is the minimum vision with glasses or contacts for a restricted license?","o":["20/70","20/100","20/150","20/200"],"h1":"It is a little worse than the 20/40 needed without glasses.","h2":"In Arkansas, you need at least 20/70 vision with glasses or contacts for a restricted license, and you must wear them when you drive.","p":"Right. 20/70 with glasses or contacts is the minimum for a restricted license."},"es":{"q":"En Arkansas, ¿cuál es la visión mínima con anteojos o lentes de contacto para una licencia con restricción?","o":["20/70","20/100","20/150","20/200"],"h1":"Es un poco peor que el 20/40 que se necesita sin anteojos.","h2":"En Arkansas, usted necesita por lo menos una visión de 20/70 con anteojos o lentes de contacto para una licencia con restricción, y debe usarlos cuando maneja.","p":"Correcto. 20/70 con anteojos o lentes de contacto es el mínimo para una licencia con restricción."},"ref":{"doc":"AR","page":5}},{"id":"ar-066","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, a person with two working eyes takes the vision test. How wide must the field of vision be?","o":["At least 45 degrees","At least 60 degrees","At least 90 degrees","At least 140 degrees"],"h1":"It is well over a right angle.","h2":"In Arkansas, a person with two functional eyes needs a field of vision of at least 140 degrees.","p":"Right. With two working eyes, you need a 140-degree field of vision."},"es":{"q":"En Arkansas, una persona con los dos ojos funcionando toma la prueba de la vista. ¿Qué tan amplio debe ser su campo visual?","o":["Por lo menos 45 grados","Por lo menos 60 grados","Por lo menos 90 grados","Por lo menos 140 grados"],"h1":"Es bastante más que un ángulo recto.","h2":"En Arkansas, una persona con los dos ojos funcionando necesita un campo visual de por lo menos 140 grados.","p":"Correcto. Con los dos ojos funcionando, necesita un campo visual de 140 grados."},"ref":{"doc":"AR","page":5}},{"id":"ar-067","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, you need a vision referral form (ASP-90) for your license. Who must fill it out?","o":["An online eye doctor","An Arkansas optometrist","An optometrist in any state","A parent or guardian"],"h1":"Forms from out of state or from virtual visits are refused.","h2":"In Arkansas, a vision referral form must be completed by an Arkansas optometrist; forms from out-of-state or online optometrists are not accepted.","p":"Right. Only an Arkansas optometrist may complete the vision referral form."},"es":{"q":"En Arkansas, usted necesita un formulario de referencia de la vista (ASP-90) para su licencia. ¿Quién debe llenarlo?","o":["Un oculista en línea","Un optometrista de Arkansas","Un optometrista de cualquier estado","Un padre o tutor"],"h1":"Los formularios de otros estados o de consultas virtuales se rechazan.","h2":"En Arkansas, el formulario de referencia de la vista debe llenarlo un optometrista de Arkansas; no se aceptan los de optometristas de otros estados ni en línea.","p":"Correcto. Solo un optometrista de Arkansas puede llenar el formulario de la vista."},"ref":{"doc":"AR","page":5}},{"id":"ar-068","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, drivers licensed in some countries can get an Arkansas license without testing. Which country is on that list?","o":["Mexico","Brazil","Germany","India"],"h1":"It is a country in Europe.","h2":"In Arkansas, license holders from Germany, France, Taiwan, South Korea, and Manitoba, Canada, may get a license without testing, because of a reciprocal agreement.","p":"Right. Germany is one of the countries exempt from testing."},"es":{"q":"En Arkansas, quienes tienen licencia de algunos países pueden obtener una licencia de Arkansas sin hacer las pruebas. ¿Qué país está en esa lista?","o":["México","Brasil","Alemania","India"],"h1":"Es un país de Europa.","h2":"En Arkansas, quienes tienen licencia de Alemania, Francia, Taiwán, Corea del Sur y Manitoba (Canadá) pueden obtener una licencia sin hacer las pruebas, gracias a un acuerdo recíproco.","p":"Correcto. Alemania es uno de los países exentos de las pruebas."},"ref":{"doc":"AR","page":5}},{"id":"ar-069","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, an applicant 18 or older is proving identity for the written test. What must they bring?","o":["Just one secondary document, like a school ID","Two primary documents, or one primary and one secondary","Three secondary documents of any kind","Any single card that shows your photo"],"h1":"Primary documents carry more weight than secondary ones.","h2":"In Arkansas, applicants 18 and older must bring two primary documents, or one primary and one secondary document.","p":"Right. Adults need two primary documents, or one primary and one secondary."},"es":{"q":"En Arkansas, un solicitante de 18 años o más debe probar su identidad para el examen escrito. ¿Qué debe llevar?","o":["Solo un documento secundario, como una identificación escolar","Dos documentos primarios, o uno primario y uno secundario","Tres documentos secundarios de cualquier tipo","Cualquier tarjeta que muestre su foto"],"h1":"Los documentos primarios valen más que los secundarios.","h2":"En Arkansas, los solicitantes de 18 años o más deben llevar dos documentos primarios, o un documento primario y uno secundario.","p":"Correcto. Los adultos necesitan dos documentos primarios, o uno primario y uno secundario."},"ref":{"doc":"AR","page":6}},{"id":"ar-070","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, a parent signs the ASP-33 form in front of a notary instead of at the test office. How soon must it be given to the examiner?","o":["Within 7 days","Within 6 months","Within 1 year","Within 30 days"],"h1":"It is about one month.","h2":"In Arkansas, a notarized ASP-33 parent affidavit must be given to the examiner within 30 days.","p":"Right. A notarized ASP-33 must reach the examiner within 30 days."},"es":{"q":"En Arkansas, un padre firma el formulario ASP-33 ante un notario en lugar de en la oficina de pruebas. ¿En cuánto tiempo debe entregarse al examinador?","o":["Dentro de 7 días","Dentro de 6 meses","Dentro de 1 año","Dentro de 30 días"],"h1":"Es más o menos un mes.","h2":"En Arkansas, la declaración jurada ASP-33 del padre, firmada ante notario, debe entregarse al examinador dentro de 30 días.","p":"Correcto. Un ASP-33 notariado debe llegar al examinador dentro de 30 días."},"ref":{"doc":"AR","page":7}},{"id":"ar-071","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, may a stepparent sign for a teen under 18 who is applying for a permit?","o":["Only with proof of adoption","Yes, always, with no papers","Only if the stepparent is over 30","Only with a letter from the school"],"h1":"The state needs proof of a legal parent tie.","h2":"In Arkansas, a stepparent cannot sign for a minor's application without proof that the stepparent adopted the child.","p":"Right. A stepparent needs proof of adoption to sign."},"es":{"q":"En Arkansas, ¿puede un padrastro o madrastra firmar por un adolescente menor de 18 años que solicita un permiso?","o":["Solo con prueba de adopción","Sí, siempre, sin documentos","Solo si tiene más de 30 años","Solo con una carta de la escuela"],"h1":"El estado necesita prueba de un vínculo legal de padre o madre.","h2":"En Arkansas, un padrastro o madrastra no puede firmar la solicitud de un menor sin prueba de que adoptó al niño.","p":"Correcto. Un padrastro o madrastra necesita prueba de adopción para firmar."},"ref":{"doc":"AR","page":7}},{"id":"ar-072","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, may a police officer stop you just because you are not wearing a seat belt?","o":["No, only along with another ticket","Only on an interstate highway","Yes, it is a primary offense","Only between sunset and sunrise"],"h1":"Since 2009, the seat belt law works on its own.","h2":"In Arkansas, not wearing a seat belt is a primary violation, so an officer may stop you for that reason alone.","p":"Right. An officer may stop you just for not buckling up."},"es":{"q":"En Arkansas, ¿puede un policía detenerlo solo porque usted no lleva puesto el cinturón de seguridad?","o":["No, solo junto con otra multa","Solo en una autopista interestatal","Sí, es una infracción primaria","Solo entre la puesta y la salida del sol"],"h1":"Desde 2009, la ley del cinturón funciona por sí sola.","h2":"En Arkansas, no usar el cinturón de seguridad es una infracción primaria, así que un policía puede detenerlo solo por eso.","p":"Correcto. Un policía puede detenerlo solo por no abrocharse el cinturón."},"ref":{"doc":"AR","page":9}},{"id":"ar-073","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, what is the highest fine for a second littering conviction within three years?","o":["$500","$2,000","$100","$10,000"],"h1":"It is double the top fine for a first offense.","h2":"In Arkansas, a second or later littering conviction can bring a fine of up to $2,000 and up to 24 hours of community service.","p":"Right. A repeat littering conviction can cost up to $2,000."},"es":{"q":"En Arkansas, ¿cuál es la multa más alta por una segunda condena por tirar basura dentro de tres años?","o":["$500","$2,000","$100","$10,000"],"h1":"Es el doble de la multa más alta por la primera vez.","h2":"En Arkansas, una segunda condena o más por tirar basura puede traer una multa de hasta $2,000 y hasta 24 horas de servicio comunitario.","p":"Correcto. Repetir la falta de tirar basura puede costar hasta $2,000."},"ref":{"doc":"AR","page":10}},{"id":"ar-074","scope":"AR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arkansas, a driver illegally passes a stopped school bus and negligently causes a person's death. What charge can the driver face?","o":["Only a small traffic fine","Only a written warning","A parking ticket","A Class C felony for negligent homicide"],"h1":"Isaac's Law treats this as a very serious crime.","h2":"Under Arkansas's Isaac's Law, a driver who negligently causes a death while illegally passing a school bus faces a Class C felony for negligent homicide.","p":"Right. Causing a death this way is a felony under Isaac's Law."},"es":{"q":"En Arkansas, un conductor pasa ilegalmente un autobús escolar detenido y por negligencia causa la muerte de una persona. ¿De qué lo pueden acusar?","o":["Solo de una multa de tránsito pequeña","Solo de una advertencia por escrito","De una multa de estacionamiento","De un delito grave Clase C por homicidio negligente"],"h1":"La Ley de Isaac trata esto como un delito muy serio.","h2":"Según la Ley de Isaac de Arkansas, un conductor que por negligencia causa una muerte al pasar ilegalmente un autobús escolar enfrenta un delito grave Clase C por homicidio negligente.","p":"Correcto. Causar una muerte así es un delito grave según la Ley de Isaac."},"ref":{"doc":"AR","page":13}},{"id":"ar-075","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, what is the fine for a first offense of using another person's disability parking certificate?","o":["$100 to $500","$10 to $50","$1,000 to $5,000","A flat $25"],"h1":"The top of the range is a three-digit amount.","h2":"In Arkansas, illegally using another person's special parking certificate is a first offense fine of at least $100 and up to $500.","p":"Right. A first offense costs $100 to $500."},"es":{"q":"En Arkansas, ¿cuál es la multa por una primera vez por usar el certificado de estacionamiento para discapacitados de otra persona?","o":["De $100 a $500","De $10 a $50","De $1,000 a $5,000","$25 fijos"],"h1":"El máximo es una cantidad de tres cifras.","h2":"En Arkansas, usar ilegalmente el certificado especial de estacionamiento de otra persona tiene una multa de por lo menos $100 y hasta $500 la primera vez.","p":"Correcto. La primera vez cuesta de $100 a $500."},"ref":{"doc":"AR","page":14}},{"id":"ar-076","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a person misuses someone else's disability parking certificate for the second time. Besides a bigger fine, what else happens?","o":["A lifetime ban from driving","The car's title is taken away","A six-month driver's license suspension","Nothing beyond the fine"],"h1":"It affects the driver's license for a set time.","h2":"In Arkansas, a second offense for misusing a special parking certificate brings a fine of $250 to $1,000 plus a six-month driver's license suspension.","p":"Right. A second offense adds a six-month license suspension."},"es":{"q":"En Arkansas, una persona usa mal por segunda vez el certificado de estacionamiento para discapacitados de otra persona. Además de una multa más alta, ¿qué más pasa?","o":["Se le prohíbe manejar de por vida","Le quitan el título del auto","Se suspende su licencia de conducir por seis meses","Nada más aparte de la multa"],"h1":"Afecta la licencia de conducir por un tiempo fijo.","h2":"En Arkansas, una segunda falta por usar mal un certificado especial de estacionamiento trae una multa de $250 a $1,000 y una suspensión de la licencia de conducir por seis meses.","p":"Correcto. Una segunda falta agrega una suspensión de la licencia por seis meses."},"ref":{"doc":"AR","page":14}},{"id":"ar-077","scope":"AR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arkansas, when may a car with a disability hang tag (Special Certificate) park in an accessible space?","o":["Whenever any family member drives the car","Only when the person the tag belongs to is in the car","Any time the tag hangs in any car","Only on weekends and holidays"],"h1":"The tag goes with the person, not with the car.","h2":"In Arkansas, a Special Certificate may be used to park in an accessible space only when the disabled person it was issued to is in the vehicle.","p":"Right. The tag holder must be in the car to use the space."},"es":{"q":"En Arkansas, ¿cuándo puede estacionarse en un espacio para discapacitados un auto con una tarjeta colgante para discapacitados (Special Certificate)?","o":["Siempre que maneje cualquier familiar","Solo cuando la persona dueña de la tarjeta va en el auto","En cualquier momento en que la tarjeta cuelgue en cualquier auto","Solo los fines de semana y días feriados"],"h1":"La tarjeta va con la persona, no con el auto.","h2":"En Arkansas, un Special Certificate se puede usar para estacionarse en un espacio para discapacitados solo cuando la persona con discapacidad a quien se le dio va en el vehículo.","p":"Correcto. La persona dueña de la tarjeta debe ir en el auto para usar el espacio."},"ref":{"doc":"AR","page":14}},{"id":"ar-078","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, fines for moving violations double in a work zone when workers are present. How high can a doubled fine be?","o":["As high as $250","As high as $500","As high as $50,000","As high as $5,000"],"h1":"It is a four-digit amount.","h2":"In Arkansas, depending on the violation, a doubled work zone fine can be as high as $5,000.","p":"Right. Doubled work zone fines can reach $5,000."},"es":{"q":"En Arkansas, las multas por infracciones en movimiento se duplican en una zona de construcción cuando hay trabajadores. ¿Qué tan alta puede ser una multa duplicada?","o":["Hasta $250","Hasta $500","Hasta $50,000","Hasta $5,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Arkansas, según la infracción, una multa duplicada en una zona de construcción puede llegar hasta $5,000.","p":"Correcto. Las multas duplicadas en zonas de construcción pueden llegar a $5,000."},"ref":{"doc":"AR","page":19}},{"id":"ar-079","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, speed cameras are used in Interstate work zones. How do they work?","o":["An officer at the end watches it and stops speeders","Tickets are mailed out with no officer involved","They only count how many cars go by","They only check whether drivers wear seat belts"],"h1":"The goal is to keep officers out of the work zone itself.","h2":"In Arkansas Interstate work zones, an officer at the end of the zone uses the speed camera to see violations and pulls the driver over after the zone.","p":"Right. The officer watches the camera from the end of the zone and stops speeders there."},"es":{"q":"En Arkansas, se usan cámaras de velocidad en las zonas de construcción de las autopistas interestatales. ¿Cómo funcionan?","o":["Un policía al final la mira y detiene a quienes van rápido","Las multas se envían por correo sin ningún policía","Solo cuentan cuántos autos pasan","Solo revisan si los conductores usan el cinturón"],"h1":"El objetivo es que los policías no tengan que estar dentro de la zona de trabajo.","h2":"En las zonas de construcción de las interestatales de Arkansas, un policía al final de la zona usa la cámara de velocidad para ver las infracciones y detiene al conductor después de la zona.","p":"Correcto. El policía mira la cámara desde el final de la zona y detiene ahí a quienes van rápido."},"ref":{"doc":"AR","page":19}},{"id":"ar-080","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, you are caught driving more than 15 mph over the speed limit on a county road. What kind of offense is it?","o":["No offense, only a warning","A felony","A Class C misdemeanor","A parking violation"],"h1":"It is a crime, but the lowest level of one.","h2":"In Arkansas, speeding more than 15 mph over the limit on a county road is a Class C misdemeanor.","p":"Right. More than 15 mph over on a county road is a Class C misdemeanor."},"es":{"q":"En Arkansas, lo detienen manejando a más de 15 mph sobre el límite de velocidad en un camino del condado. ¿Qué tipo de falta es?","o":["Ninguna falta, solo una advertencia","Un delito grave","Un delito menor Clase C","Una infracción de estacionamiento"],"h1":"Es un delito, pero del nivel más bajo.","h2":"En Arkansas, ir a más de 15 mph sobre el límite en un camino del condado es un delito menor Clase C.","p":"Correcto. Ir a más de 15 mph sobre el límite en un camino del condado es un delito menor Clase C."},"ref":{"doc":"AR","page":26}},{"id":"ar-081","scope":"AR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arkansas, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 2 feet","No closer than 10 feet"],"h1":"People in the crosswalk must be easy to see.","h2":"In Arkansas, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Arkansas, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 20 pies","No más cerca de 2 pies","No más cerca de 10 pies"],"h1":"Las personas en el cruce deben verse con facilidad.","h2":"En Arkansas, usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"AR","page":42}},{"id":"ar-082","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, you parallel park next to a curb. How far from the curb may your car be?","o":["3 feet or less","4 feet or less","6 feet or less","18 inches or less"],"h1":"It is a bit less than two feet.","h2":"In Arkansas, when you parallel park, your car should be 18 inches or less from the curb.","p":"Right. Park no more than 18 inches from the curb."},"es":{"q":"En Arkansas, usted se estaciona en paralelo junto a la acera. ¿A qué distancia de la acera puede quedar su auto?","o":["A 3 pies o menos","A 4 pies o menos","A 6 pies o menos","A 18 pulgadas o menos"],"h1":"Es un poco menos de dos pies.","h2":"En Arkansas, cuando se estaciona en paralelo, su auto debe quedar a 18 pulgadas o menos de la acera.","p":"Correcto. Estaciónese a no más de 18 pulgadas de la acera."},"ref":{"doc":"AR","page":41}},{"id":"ar-083","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, how close to a fire station driveway on the same side of the street may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 2 feet","No closer than 10 feet"],"h1":"Fire trucks need room to swing out.","h2":"In Arkansas, you may not park within 20 feet of a fire station driveway on the same side of the street.","p":"Right. Stay at least 20 feet from a fire station driveway on your side."},"es":{"q":"En Arkansas, ¿qué tan cerca de la entrada de una estación de bomberos, en el mismo lado de la calle, puede estacionarse?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 2 pies","No más cerca de 10 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir.","h2":"En Arkansas, usted no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos en el mismo lado de la calle.","p":"Correcto. Manténgase por lo menos a 20 pies de la entrada de una estación de bomberos de su lado."},"ref":{"doc":"AR","page":42}},{"id":"ar-084","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, what does a curb painted yellow mean?","o":["A fire zone","Free parking at any time","A loading zone or other parking limit","Parking for drivers with disabilities"],"h1":"In Arkansas, red marks the fire zone, so yellow means something else.","h2":"In Arkansas, a yellow curb means a loading zone or another parking restriction.","p":"Right. A yellow curb marks a loading zone or other restriction."},"es":{"q":"En Arkansas, ¿qué significa una acera pintada de amarillo?","o":["Una zona de bomberos","Estacionamiento libre en cualquier momento","Una zona de carga u otro límite para estacionarse","Estacionamiento para conductores con discapacidad"],"h1":"En Arkansas, el rojo marca la zona de bomberos, así que el amarillo significa otra cosa.","h2":"En Arkansas, una acera amarilla indica una zona de carga u otra restricción para estacionarse.","p":"Correcto. Una acera amarilla indica una zona de carga u otra restricción."},"ref":{"doc":"AR","page":42}},{"id":"ar-085","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, when should your headlights be on in the evening and early morning?","o":["From 2 hours after sunset until sunrise","From 30 minutes after sunset until 30 minutes before sunrise","Only between midnight and 5 a.m.","Only on roads with no streetlights"],"h1":"Count half an hour on each side of the night.","h2":"In Arkansas, you should turn on your headlights from 30 minutes after sunset until 30 minutes before sunrise.","p":"Right. Headlights go on from a half hour after sunset to a half hour before sunrise."},"es":{"q":"En Arkansas, ¿cuándo deben estar encendidos sus faros por la tarde y temprano en la mañana?","o":["Desde 2 horas después de la puesta del sol hasta la salida del sol","Desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol","Solo entre la medianoche y las 5 a. m.","Solo en calles sin alumbrado"],"h1":"Cuente media hora a cada lado de la noche.","h2":"En Arkansas, usted debe encender los faros desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol.","p":"Correcto. Los faros se encienden desde media hora después de la puesta del sol hasta media hora antes de la salida del sol."},"ref":{"doc":"AR","page":51}},{"id":"ar-086","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, may you drive at dusk with only your parking lights on?","o":["Yes, until it is fully dark","Yes, in light rain","Yes, on city streets","No, it is against the law"],"h1":"Parking lights are meant for cars that are parked.","h2":"In Arkansas, it is illegal to drive using only your parking lights.","p":"Right. Driving on parking lights alone is illegal in Arkansas."},"es":{"q":"En Arkansas, ¿puede manejar al atardecer solo con las luces de estacionamiento encendidas?","o":["Sí, hasta que esté completamente oscuro","Sí, con lluvia ligera","Sí, en calles de la ciudad","No, está prohibido por la ley"],"h1":"Las luces de estacionamiento son para autos estacionados.","h2":"En Arkansas, es ilegal manejar usando solo las luces de estacionamiento.","p":"Correcto. En Arkansas es ilegal manejar solo con las luces de estacionamiento."},"ref":{"doc":"AR","page":51}},{"id":"ar-087","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, you are using high beams at night. When must you dim them for an oncoming car?","o":["When it comes within 500 feet","When it comes within 50 feet","When it comes within 100 feet","Only after it has passed you"],"h1":"It is about the length of one and a half football fields.","h2":"In Arkansas, you should dim your high beams whenever you come within 500 feet of an oncoming vehicle.","p":"Right. Dim your high beams within 500 feet of an oncoming car."},"es":{"q":"En Arkansas, usted usa las luces altas de noche. ¿Cuándo debe bajarlas por un auto que viene de frente?","o":["Cuando esté a 500 pies o menos","Cuando esté a 50 pies o menos","Cuando esté a 100 pies o menos","Solo después de que lo haya pasado"],"h1":"Es como el largo de un campo y medio de fútbol americano.","h2":"En Arkansas, usted debe bajar las luces altas siempre que esté a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces altas a 500 pies de un auto que viene de frente."},"ref":{"doc":"AR","page":51}},{"id":"ar-088","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you get an automatic failure on the driving skills test. How long must you wait before you test again?","o":["1 day","6 months","30 days","1 year"],"h1":"It is about one month.","h2":"In Arkansas, an automatic failure on the skills test brings a 30-day waiting penalty.","p":"Right. An automatic failure means a 30-day wait."},"es":{"q":"En Arkansas, usted reprueba automáticamente la prueba práctica de manejo. ¿Cuánto tiempo debe esperar para volver a tomarla?","o":["1 día","6 meses","30 días","1 año"],"h1":"Es más o menos un mes.","h2":"En Arkansas, reprobar automáticamente la prueba práctica trae una espera de 30 días como castigo.","p":"Correcto. Reprobar automáticamente significa esperar 30 días."},"ref":{"doc":"AR","page":85}},{"id":"ar-089","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, how far ahead should you turn on your signal before you turn?","o":["At least 10 feet","At least 100 feet","At least 25 feet","Only as you begin to turn"],"h1":"It is about the length of six or seven cars.","h2":"In Arkansas, you should signal at least 100 feet before a turn.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En Arkansas, ¿con cuánta anticipación debe poner la señal antes de girar?","o":["Por lo menos 10 pies antes","Por lo menos 100 pies antes","Por lo menos 25 pies antes","Solo cuando empieza a girar"],"h1":"Es como el largo de seis o siete autos.","h2":"En Arkansas, usted debe poner la señal por lo menos 100 pies antes de girar.","p":"Correcto. Ponga la señal por lo menos 100 pies antes de girar."},"ref":{"doc":"AR","page":53}},{"id":"ar-090","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, how close to a hill or curve should you avoid passing another vehicle?","o":["Within 50 feet","Within 100 feet","Within 1/10 of a mile","Within 1/3 of a mile"],"h1":"It is about 1,600 feet, the room needed to pass at 55 mph.","h2":"In Arkansas, you should never pass within 1/3 of a mile of a hill or curve.","p":"Right. Do not pass within 1/3 of a mile of a hill or curve."},"es":{"q":"En Arkansas, ¿a qué distancia de una colina o curva debe evitar rebasar a otro vehículo?","o":["A menos de 50 pies","A menos de 100 pies","A menos de 1/10 de milla","A menos de 1/3 de milla"],"h1":"Son unos 1,600 pies, el espacio que se necesita para rebasar a 55 mph.","h2":"En Arkansas, usted nunca debe rebasar a menos de 1/3 de milla de una colina o curva.","p":"Correcto. No rebase a menos de 1/3 de milla de una colina o curva."},"ref":{"doc":"AR","page":62}},{"id":"ar-091","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, how much following distance should you leave behind a motorcycle?","o":["At least 4 to 6 seconds","About 1 second","About 2 seconds","Half a second"],"h1":"It is more than the usual two-second rule.","h2":"In Arkansas, you should leave at least 4 to 6 seconds of following distance behind a motorcycle.","p":"Right. Give a motorcycle at least 4 to 6 seconds."},"es":{"q":"En Arkansas, ¿cuánta distancia debe dejar detrás de una motocicleta?","o":["Por lo menos de 4 a 6 segundos","Más o menos 1 segundo","Más o menos 2 segundos","Medio segundo"],"h1":"Es más que la regla normal de dos segundos.","h2":"En Arkansas, usted debe dejar por lo menos de 4 a 6 segundos de distancia detrás de una motocicleta.","p":"Correcto. Deje por lo menos de 4 a 6 segundos detrás de una motocicleta."},"ref":{"doc":"AR","page":70}},{"id":"ar-092","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a driver is in a traffic crash or commits a serious traffic offense. At what blood alcohol level can the driver be charged with DWI?","o":["Only at 0.10 percent or higher","Only at 0.12 percent or higher","As low as 0.04 percent","Only at 0.15 percent or higher"],"h1":"It is half of the usual 0.08 limit.","h2":"In Arkansas, a driver in a crash or serious traffic offense can be charged with DWI with a blood alcohol level between 0.04 and 0.08 percent.","p":"Right. After a crash or serious offense, DWI can be charged from 0.04 percent."},"es":{"q":"En Arkansas, un conductor tiene un choque o comete una infracción de tránsito grave. ¿Con qué nivel de alcohol en la sangre lo pueden acusar de DWI?","o":["Solo con 0.10 por ciento o más","Solo con 0.12 por ciento o más","Desde 0.04 por ciento","Solo con 0.15 por ciento o más"],"h1":"Es la mitad del límite normal de 0.08.","h2":"En Arkansas, un conductor que tiene un choque o comete una infracción grave puede ser acusado de DWI con un nivel de alcohol en la sangre entre 0.04 y 0.08 por ciento.","p":"Correcto. Después de un choque o infracción grave, lo pueden acusar de DWI desde 0.04 por ciento."},"ref":{"doc":"AR","page":74}},{"id":"ar-093","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, how long is a passed vision test or a vision referral form (ASP-90) good for?","o":["30 days from the test date","One year from the test date","Five years from the test date","Until your next birthday"],"h1":"It is the same length as one trip around the calendar.","h2":"In Arkansas, a vision test and a vision referral form (ASP-90) are valid for one year from the date of the test.","p":"Right. A vision test or ASP-90 form is good for one year."},"es":{"q":"En Arkansas, ¿por cuánto tiempo vale un examen de la vista aprobado o un formulario de referencia de la vista (ASP-90)?","o":["30 días desde la fecha del examen","Un año desde la fecha del examen","Cinco años desde la fecha del examen","Hasta su próximo cumpleaños"],"h1":"Es lo mismo que una vuelta completa al calendario.","h2":"En Arkansas, el examen de la vista y el formulario de referencia de la vista (ASP-90) valen por un año desde la fecha del examen.","p":"Correcto. El examen de la vista o el formulario ASP-90 vale por un año."},"ref":{"doc":"AR","page":5}},{"id":"ar-094","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you hold a regular Class D license. May you ride a motorized bicycle of 50 cc or less?","o":["No, you also need a Motorized Bicycle Certificate","Only after passing a motorcycle skills test","Yes, your Class D license already covers it","Only if you add a Class M endorsement"],"h1":"Many kinds of Arkansas licenses already include small motorized bicycles.","h2":"In Arkansas, a person with a Class D, intermediate, learner's, Class M or Class MD license may legally ride a motorized bicycle or motorcycle of 50 cc or less.","p":"Right. A Class D license covers a motorized bicycle of 50 cc or less."},"es":{"q":"En Arkansas, usted tiene una licencia normal Clase D. ¿Puede manejar una bicicleta motorizada de 50 cc o menos?","o":["No, también necesita un Certificado de Bicicleta Motorizada","Solo después de aprobar una prueba práctica de motocicleta","Sí, su licencia Clase D ya lo permite","Solo si agrega un endoso Clase M"],"h1":"Muchos tipos de licencias de Arkansas ya incluyen las bicicletas motorizadas pequeñas.","h2":"En Arkansas, una persona con licencia Clase D, intermedia, de aprendiz, Clase M o Clase MD puede manejar legalmente una bicicleta motorizada o motocicleta de 50 cc o menos.","p":"Correcto. La licencia Clase D permite manejar una bicicleta motorizada de 50 cc o menos."},"ref":{"doc":"AR","page":5}},{"id":"ar-095","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, a military spouse's driver's license expired while the family lived outside the United States. What does state law allow?","o":["They must wait one year before applying","They must retake all tests and a driving course","They may only get an instruction permit at first","They may get an Arkansas license without testing"],"h1":"A 2005 law helps military families who were stationed abroad.","h2":"In Arkansas, Act 235 of 2005 lets a U.S. military spouse get an Arkansas driver's license without testing if their license expired while living outside the United States.","p":"Right. That military spouse can get a license without testing."},"es":{"q":"En Arkansas, la licencia de conducir del cónyuge de un militar venció mientras la familia vivía fuera de los Estados Unidos. ¿Qué permite la ley del estado?","o":["Debe esperar un año antes de solicitarla","Debe repetir todos los exámenes y un curso de manejo","Al principio solo puede obtener un permiso de instrucción","Puede obtener una licencia de Arkansas sin hacer exámenes"],"h1":"Una ley de 2005 ayuda a las familias militares que estuvieron en el extranjero.","h2":"En Arkansas, la Ley 235 de 2005 permite que el cónyuge de un militar de EE. UU. obtenga una licencia de Arkansas sin exámenes si su licencia venció mientras vivía fuera de los Estados Unidos.","p":"Correcto. Ese cónyuge de militar puede obtener la licencia sin exámenes."},"ref":{"doc":"AR","page":2}},{"id":"ar-096","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, a college student from another state pays nonresident tuition. May the student drive on a valid license from home?","o":["Yes, if the student is at least 16","No, an Arkansas license is needed within 10 days","Only with a special student permit from the State Police","Only on weekends and school holidays"],"h1":"Nonresident students are on a short list of people who may keep using a home-state license.","h2":"In Arkansas, students who are nonresidents for tuition, such as college or exchange students, may drive with a valid license from another state if they are at least 16.","p":"Right. A nonresident student 16 or older may drive on a valid home-state license."},"es":{"q":"En Arkansas, un estudiante universitario de otro estado paga matrícula de no residente. ¿Puede manejar con una licencia válida de su estado?","o":["Sí, si el estudiante tiene por lo menos 16 años","No, necesita una licencia de Arkansas en 10 días","Solo con un permiso especial de estudiante de la Policía Estatal","Solo los fines de semana y en vacaciones escolares"],"h1":"Los estudiantes no residentes están en una lista corta de personas que pueden seguir usando la licencia de su estado.","h2":"En Arkansas, los estudiantes que son no residentes para la matrícula, como los universitarios o de intercambio, pueden manejar con una licencia válida de otro estado si tienen por lo menos 16 años.","p":"Correcto. Un estudiante no residente de 16 años o más puede manejar con una licencia válida de su estado."},"ref":{"doc":"AR","page":2}},{"id":"ar-097","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, you want a motorcycle license but have no Class D license. Which exam must you pass first?","o":["The motorcycle skills test","The regular (NCL) driver knowledge exam","A road test in a car","A motorcycle safety course exam"],"h1":"You must show you know the general rules of the road first.","h2":"In Arkansas, an applicant for a motorcycle license who has no Class D license must first pass the Non-Commercial License (NCL) knowledge exam, then the motorcycle knowledge exam.","p":"Right. Without a Class D, start with the regular NCL knowledge exam."},"es":{"q":"En Arkansas, usted quiere una licencia de motocicleta pero no tiene licencia Clase D. ¿Qué examen debe aprobar primero?","o":["La prueba práctica de motocicleta","El examen de conocimientos normal para conductores (NCL)","Una prueba de manejo en auto","Un examen de curso de seguridad en motocicleta"],"h1":"Primero debe demostrar que conoce las reglas generales del camino.","h2":"En Arkansas, quien solicita una licencia de motocicleta sin tener licencia Clase D debe aprobar primero el examen de conocimientos de Licencia No Comercial (NCL) y después el examen de conocimientos de motocicleta.","p":"Correcto. Sin Clase D, empiece con el examen de conocimientos normal (NCL)."},"ref":{"doc":"AR","page":4}},{"id":"ar-098","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a teen under 18 is a U.S. citizen but was born in another country. What must the teen show as proof of birth?","o":["A translated foreign birth certificate","A hospital birth record","A Birth Abroad Certificate","A school ID card"],"h1":"It is a U.S. document made for citizens born outside the country.","h2":"In Arkansas, a minor who is a U.S. citizen born outside the country must present a Birth Abroad Certificate.","p":"Right. A U.S. citizen born abroad shows a Birth Abroad Certificate."},"es":{"q":"En Arkansas, un adolescente menor de 18 años es ciudadano de EE. UU. pero nació en otro país. ¿Qué debe mostrar como prueba de nacimiento?","o":["Un acta de nacimiento extranjera traducida","Un registro de nacimiento del hospital","Un Certificado de Nacimiento en el Extranjero","Una credencial escolar"],"h1":"Es un documento de EE. UU. hecho para ciudadanos nacidos fuera del país.","h2":"En Arkansas, un menor que es ciudadano de EE. UU. y nació fuera del país debe presentar un Certificado de Nacimiento en el Extranjero (Birth Abroad Certificate).","p":"Correcto. Un ciudadano nacido en el extranjero muestra un Certificado de Nacimiento en el Extranjero."},"ref":{"doc":"AR","page":7}},{"id":"ar-099","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, an applicant 18 or older wants to use a tax document as a secondary ID. Which one is accepted?","o":["A W-2 form from your job","A property tax receipt","A tax return from ten years ago","An IRS tax return from the last 2 years"],"h1":"The list names one IRS form and says a W-2 will not do.","h2":"In Arkansas, an IRS tax return from within the last two years is an accepted secondary document; a W-2 form is not accepted.","p":"Right. An IRS tax return from the last 2 years is accepted."},"es":{"q":"En Arkansas, un solicitante de 18 años o más quiere usar un documento de impuestos como identificación secundaria. ¿Cuál se acepta?","o":["Un formulario W-2 de su trabajo","Un recibo de impuesto a la propiedad","Una declaración de impuestos de hace diez años","Una declaración de impuestos del IRS de los últimos 2 años"],"h1":"La lista nombra un documento del IRS y dice que el W-2 no sirve.","h2":"En Arkansas, una declaración de impuestos del IRS de los últimos dos años es un documento secundario aceptado; el formulario W-2 no se acepta.","p":"Correcto. Se acepta una declaración de impuestos del IRS de los últimos 2 años."},"ref":{"doc":"AR","page":6}},{"id":"ar-100","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, a legal guardian is signing for a teen under 18 at the driver test. What must the guardian bring?","o":["An ID and court papers that show guardianship","A letter from the teen's school","A note signed by the teen's doctor","Only the teen's report card"],"h1":"The guardian has to prove the legal right to sign.","h2":"In Arkansas, a legal guardian must be present with a state driver's license or state ID and court documents that establish the guardianship.","p":"Right. A guardian brings an ID and the court papers for guardianship."},"es":{"q":"En Arkansas, un tutor legal firma por un adolescente menor de 18 años en el examen de manejo. ¿Qué debe traer el tutor?","o":["Una identificación y documentos de la corte que prueben la tutela","Una carta de la escuela del adolescente","Una nota firmada por el médico del adolescente","Solo la boleta de calificaciones del adolescente"],"h1":"El tutor debe probar que tiene el derecho legal de firmar.","h2":"En Arkansas, el tutor legal debe estar presente con una licencia o identificación estatal y documentos de la corte que establezcan la tutela.","p":"Correcto. El tutor trae una identificación y los documentos de la corte sobre la tutela."},"ref":{"doc":"AR","page":7}},{"id":"ar-101","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, a person with a disability parking certificate moves away. How soon must the certificate be returned?","o":["Within 1 year","Within 30 days","Within 6 months","It never has to be returned"],"h1":"It is about one month.","h2":"In Arkansas, a Special Certificate for disability parking must be returned within 30 days of moving, or in case of death.","p":"Right. Return it within 30 days of moving."},"es":{"q":"En Arkansas, una persona con certificado de estacionamiento para discapacitados se muda. ¿En cuánto tiempo debe devolver el certificado?","o":["En 1 año","En 30 días","En 6 meses","Nunca tiene que devolverlo"],"h1":"Es más o menos un mes.","h2":"En Arkansas, el Certificado Especial de estacionamiento para discapacitados se debe devolver en un plazo de 30 días después de mudarse, o en caso de muerte.","p":"Correcto. Devuélvalo en 30 días después de mudarse."},"ref":{"doc":"AR","page":14}},{"id":"ar-102","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, a road crew is moving slowly while patching potholes (a mobile work zone), with workers present. Do work zone fines double here?","o":["No, only fixed work zones count","Only if a police officer is in the zone","Only on Interstate highways","Yes, the same as a fixed work zone"],"h1":"Mobile work zones are marked on the back of the work trucks.","h2":"In Arkansas, mobile work zones are treated the same as standard work zones, so fines for moving violations double in both when workers are present.","p":"Right. Fines double in mobile work zones too."},"es":{"q":"En Arkansas, un equipo de trabajo avanza despacio mientras tapa baches (una zona de trabajo móvil), con trabajadores presentes. ¿Se duplican aquí las multas de zona de trabajo?","o":["No, solo cuentan las zonas de trabajo fijas","Solo si hay un policía en la zona","Solo en las autopistas interestatales","Sí, igual que en una zona de trabajo fija"],"h1":"Las zonas de trabajo móviles se señalan en la parte de atrás de los camiones.","h2":"En Arkansas, las zonas de trabajo móviles se tratan igual que las normales, así que las multas por infracciones de movimiento se duplican en las dos cuando hay trabajadores presentes.","p":"Correcto. Las multas también se duplican en las zonas de trabajo móviles."},"ref":{"doc":"AR","page":19}},{"id":"ar-103","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, you see that a lane is closed ahead in a work zone. Ideally, how far before the closure should you move to the open lane?","o":["A mile or more before it","Right at the first cone","About 50 feet before it","After you pass the flagger"],"h1":"Merging early gives you and others plenty of time.","h2":"In Arkansas, you should move to the correct lane as soon as it is safe, ideally a mile or more before a lane closure.","p":"Right. Merge early, ideally a mile or more before the closure."},"es":{"q":"En Arkansas, usted ve que un carril está cerrado más adelante en una zona de trabajo. Lo ideal, ¿con cuánta anticipación debe pasarse al carril abierto?","o":["Una milla o más antes del cierre","Justo en el primer cono","Unos 50 pies antes del cierre","Después de pasar al abanderado"],"h1":"Cambiarse temprano le da tiempo a usted y a los demás.","h2":"En Arkansas, usted debe pasarse al carril correcto tan pronto como sea seguro, idealmente una milla o más antes del cierre de un carril.","p":"Correcto. Cámbiese temprano, idealmente una milla o más antes del cierre."},"ref":{"doc":"AR","page":20}},{"id":"ar-104","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, a flagger in a work zone signals you to stop, and there is no marked stopping place. Where should you stop?","o":["Right beside the flagger","At least a car length away from the flagger","At least half a mile back","Anywhere inside the work zone"],"h1":"Leave the flagger some room to work safely.","h2":"In Arkansas, you should stop at the marked spot, or at least one car length away from the flagger, and wait for directions.","p":"Right. Stop at least a car length away from the flagger."},"es":{"q":"En Arkansas, un abanderado en una zona de trabajo le indica que se detenga, y no hay un lugar marcado para parar. ¿Dónde debe detenerse?","o":["Justo al lado del abanderado","Por lo menos a un largo de auto del abanderado","Por lo menos media milla antes","En cualquier lugar dentro de la zona de trabajo"],"h1":"Deje espacio al abanderado para trabajar con seguridad.","h2":"En Arkansas, usted debe detenerse en el lugar marcado, o por lo menos a un largo de auto del abanderado, y esperar instrucciones.","p":"Correcto. Deténgase por lo menos a un largo de auto del abanderado."},"ref":{"doc":"AR","page":22}},{"id":"ar-105","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, how close to a pedestrian safety zone may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"It is about the length of two cars.","h2":"In Arkansas, you may not park within 30 feet of a pedestrian safety zone.","p":"Right. Stay at least 30 feet from a pedestrian safety zone."},"es":{"q":"En Arkansas, ¿a qué distancia de una zona de seguridad para peatones puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Es más o menos el largo de dos autos.","h2":"En Arkansas, usted no puede estacionarse a menos de 30 pies de una zona de seguridad para peatones.","p":"Correcto. Quédese por lo menos a 30 pies de una zona de seguridad para peatones."},"ref":{"doc":"AR","page":42}},{"id":"ar-106","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, you are on a road with three or more lanes going your way, and a lot of traffic is merging from the right. Which lane should you use?","o":["The far-left lane","The shoulder","The right lane","The center lane"],"h1":"Give merging cars room without moving into the passing lane.","h2":"In Arkansas, on a road with three or more lanes in your direction, stay in the right lane except to pass, but use the center lane when there is a lot of merging traffic.","p":"Right. With heavy merging traffic, use the center lane."},"es":{"q":"En Arkansas, usted va por un camino con tres o más carriles en su dirección, y mucho tráfico se incorpora por la derecha. ¿Qué carril debe usar?","o":["El carril de la extrema izquierda","El acotamiento","El carril derecho","El carril del centro"],"h1":"Deje espacio a los autos que se incorporan sin pasarse al carril de rebase.","h2":"En Arkansas, en un camino con tres o más carriles en su dirección, quédese en el carril derecho excepto para rebasar, pero use el carril del centro cuando haya mucho tráfico incorporándose.","p":"Correcto. Con mucho tráfico incorporándose, use el carril del centro."},"ref":{"doc":"AR","page":32}},{"id":"ar-107","scope":"AR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arkansas, the railroad crossing gates start to come down just as you begin to cross the tracks. What should you do?","o":["Keep going, even if you hit the gate","Stop on the tracks and wait","Back up quickly off the tracks","Stop and get out of the car"],"h1":"Being stuck on the tracks is the real danger.","h2":"In Arkansas, if the gates begin to come down as you start to cross, keep going even if it means breaking the gate.","p":"Right. Keep going off the tracks, even if you break the gate."},"es":{"q":"En Arkansas, las barreras del cruce de ferrocarril empiezan a bajar justo cuando usted empieza a cruzar las vías. ¿Qué debe hacer?","o":["Seguir adelante, aunque golpee la barrera","Detenerse sobre las vías y esperar","Retroceder rápido para salir de las vías","Detenerse y bajarse del auto"],"h1":"El verdadero peligro es quedarse atrapado sobre las vías.","h2":"En Arkansas, si las barreras empiezan a bajar cuando usted comienza a cruzar, siga adelante aunque eso signifique romper la barrera.","p":"Correcto. Siga adelante y salga de las vías, aunque rompa la barrera."},"ref":{"doc":"AR","page":29}},{"id":"ar-108","scope":"AR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arkansas, a person with a white cane or a guide dog is crossing the street. What is the rule?","o":["They must wait for a gap in traffic","They have absolute right-of-way; do not honk","You may go if you honk first","They have right-of-way only at a signal"],"h1":"Your horn could confuse or frighten a person who cannot see.","h2":"In Arkansas, a pedestrian with a white cane or a guide dog has absolute right-of-way, and you should not use your horn.","p":"Right. Give them the right-of-way and do not honk."},"es":{"q":"En Arkansas, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Cuál es la regla?","o":["Debe esperar a que haya un espacio en el tráfico","Tiene derecho de paso absoluto; no toque la bocina","Usted puede pasar si toca la bocina primero","Solo tiene derecho de paso en un semáforo"],"h1":"La bocina podría confundir o asustar a una persona que no ve.","h2":"En Arkansas, un peatón con bastón blanco o perro guía tiene derecho de paso absoluto, y usted no debe tocar la bocina.","p":"Correcto. Dele el derecho de paso y no toque la bocina."},"ref":{"doc":"AR","page":35}},{"id":"ar-109","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, you are following another vehicle at night. When should you switch to low beams?","o":["When you are within 1,000 feet of it","Only when it is raining","When you are closer than 200 feet","Only inside city limits"],"h1":"It is less than half the distance used for oncoming cars.","h2":"In Arkansas, you should use low beams when following another vehicle closer than 200 feet.","p":"Right. Use low beams when following closer than 200 feet."},"es":{"q":"En Arkansas, de noche usted va detrás de otro vehículo. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando esté a 1,000 pies o menos","Solo cuando llueve","Cuando esté a menos de 200 pies","Solo dentro de la ciudad"],"h1":"Es menos de la mitad de la distancia que se usa para los autos de frente.","h2":"En Arkansas, usted debe usar las luces bajas cuando va detrás de otro vehículo a menos de 200 pies.","p":"Correcto. Use las luces bajas cuando va a menos de 200 pies de otro vehículo."},"ref":{"doc":"AR","page":51}},{"id":"ar-110","scope":"AR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arkansas, besides the hours around sunset and sunrise, when must your headlights be on?","o":["Only when driving over 55 mph","Only on Interstate highways","Only when other cars have theirs on","When you cannot see clearly 500 feet ahead"],"h1":"It is about the same distance used for dimming high beams.","h2":"In Arkansas, turn on your headlights any time you cannot clearly see a person or object within 500 feet.","p":"Right. Lights on when you cannot see clearly for 500 feet."},"es":{"q":"En Arkansas, además de las horas cerca del atardecer y del amanecer, ¿cuándo debe tener encendidas las luces delanteras?","o":["Solo cuando maneja a más de 55 mph","Solo en las autopistas interestatales","Solo cuando otros autos las tienen encendidas","Cuando no puede ver bien a 500 pies adelante"],"h1":"Es más o menos la misma distancia que se usa para bajar las luces altas.","h2":"En Arkansas, encienda las luces delanteras siempre que no pueda ver con claridad a una persona u objeto a 500 pies o menos.","p":"Correcto. Encienda las luces cuando no pueda ver bien a 500 pies."},"ref":{"doc":"AR","page":51}},{"id":"ar-111","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, how far ahead should you look down the road while driving?","o":["At least 15 seconds ahead","About 2 seconds ahead","About 5 seconds ahead","Only to the car in front of you"],"h1":"On a highway, this is about a quarter of a mile.","h2":"In Arkansas, you should look at least 15 seconds ahead: about one city block in town, or a quarter mile on highways.","p":"Right. Look at least 15 seconds ahead."},"es":{"q":"En Arkansas, ¿qué tan lejos debe mirar hacia adelante en el camino mientras maneja?","o":["Por lo menos 15 segundos adelante","Unos 2 segundos adelante","Unos 5 segundos adelante","Solo hasta el auto de enfrente"],"h1":"En una carretera, es como un cuarto de milla.","h2":"En Arkansas, usted debe mirar por lo menos 15 segundos adelante: más o menos una cuadra en la ciudad, o un cuarto de milla en carreteras.","p":"Correcto. Mire por lo menos 15 segundos adelante."},"ref":{"doc":"AR","page":48}},{"id":"ar-112","scope":"AR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arkansas, how big a gap in traffic do you need when you merge?","o":["About 1 second","About 4 seconds","About 10 seconds","About 20 seconds"],"h1":"Entering the middle of it leaves two seconds in front and behind.","h2":"In Arkansas, you need a gap of about four seconds to merge, which leaves about two seconds of space in front of and behind you.","p":"Right. Look for a gap of about 4 seconds."},"es":{"q":"En Arkansas, ¿qué tan grande debe ser el espacio en el tráfico para incorporarse?","o":["Más o menos 1 segundo","Más o menos 4 segundos","Más o menos 10 segundos","Más o menos 20 segundos"],"h1":"Si entra en el medio, quedan dos segundos adelante y dos atrás.","h2":"En Arkansas, usted necesita un espacio de unos cuatro segundos para incorporarse, lo que deja unos dos segundos de espacio adelante y atrás.","p":"Correcto. Busque un espacio de unos 4 segundos."},"ref":{"doc":"AR","page":61}},{"id":"ar-113","scope":"AR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arkansas, at 55 mph, about how long does it take to pass another vehicle?","o":["About 2 seconds","About 4 seconds","About 10 seconds","About 1 minute"],"h1":"You need this same gap in oncoming traffic.","h2":"In Arkansas, passing at 55 mph takes about 10 seconds, so you need a 10-second gap in oncoming traffic.","p":"Right. Passing at 55 mph takes about 10 seconds."},"es":{"q":"En Arkansas, a 55 mph, ¿más o menos cuánto tiempo toma rebasar a otro vehículo?","o":["Unos 2 segundos","Unos 4 segundos","Unos 10 segundos","Más o menos 1 minuto"],"h1":"Necesita ese mismo espacio en el tráfico que viene de frente.","h2":"En Arkansas, rebasar a 55 mph toma unos 10 segundos, así que usted necesita un espacio de 10 segundos en el tráfico que viene de frente.","p":"Correcto. Rebasar a 55 mph toma unos 10 segundos."},"ref":{"doc":"AR","page":62}},{"id":"ar-114","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, the road is covered with packed snow. How much should you slow down?","o":["By about 5 mph","By about 10 percent","Not at all with good tires","Cut your speed in half"],"h1":"On ice you would slow even more, to a coast.","h2":"In Arkansas, on packed snow you should cut your speed in half.","p":"Right. On packed snow, cut your speed in half."},"es":{"q":"En Arkansas, el camino está cubierto de nieve compacta. ¿Cuánto debe bajar la velocidad?","o":["Unas 5 mph","Más o menos un 10 por ciento","Nada, si tiene buenas llantas","A la mitad"],"h1":"Sobre hielo bajaría aún más, casi hasta dejar rodar el auto.","h2":"En Arkansas, sobre nieve compacta usted debe reducir su velocidad a la mitad.","p":"Correcto. Sobre nieve compacta, reduzca la velocidad a la mitad."},"ref":{"doc":"AR","page":55}},{"id":"ar-115","scope":"AR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arkansas, rain or fog keeps you from seeing more than 200 feet ahead. What is the fastest you should drive?","o":["30 mph","45 mph","55 mph","The posted limit"],"h1":"It is a speed often posted on city streets.","h2":"In Arkansas, if you cannot see more than 200 feet ahead because of rain or fog, you should not drive faster than 30 mph.","p":"Right. With 200 feet of sight or less, drive no faster than 30 mph."},"es":{"q":"En Arkansas, la lluvia o la niebla no le dejan ver más de 200 pies adelante. ¿Cuál es la velocidad más alta a la que debe manejar?","o":["30 mph","45 mph","55 mph","El límite indicado"],"h1":"Es una velocidad que se ve mucho en calles de la ciudad.","h2":"En Arkansas, si no puede ver más de 200 pies adelante por la lluvia o la niebla, usted no debe manejar a más de 30 mph.","p":"Correcto. Si ve 200 pies o menos, no maneje a más de 30 mph."},"ref":{"doc":"AR","page":58}},{"id":"ar-116","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, how far behind a tractor-trailer can a car be hidden in the truck's blind spot?","o":["Up to 20 feet","Up to 200 feet","Up to 2 feet","Up to 1 mile"],"h1":"In front of the cab the blind area is much shorter than behind.","h2":"In Arkansas, a car can disappear from a truck driver's view up to 200 feet behind the truck, and up to 20 feet in front of the cab.","p":"Right. The blind area behind a truck reaches up to 200 feet."},"es":{"q":"En Arkansas, ¿hasta qué distancia detrás de un tractocamión puede quedar un auto oculto en el punto ciego del camión?","o":["Hasta 20 pies","Hasta 200 pies","Hasta 2 pies","Hasta 1 milla"],"h1":"Delante de la cabina el área ciega es mucho más corta que detrás.","h2":"En Arkansas, un auto puede desaparecer de la vista del camionero hasta 200 pies detrás del camión, y hasta 20 pies delante de la cabina.","p":"Correcto. El área ciega detrás de un camión llega hasta 200 pies."},"ref":{"doc":"AR","page":65}},{"id":"ar-117","scope":"AR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arkansas, what equipment must a bicycle have for riding at night?","o":["Only a bell or horn","A flag on a tall pole","A front light and a rear reflector","Flashing lights on both wheels"],"h1":"One item helps the rider see, the other helps drivers behind see the bike.","h2":"In Arkansas, bicyclists riding at night must have proper lighting: a front light and a rear reflector.","p":"Right. A bike at night needs a front light and a rear reflector."},"es":{"q":"En Arkansas, ¿qué equipo debe tener una bicicleta para andar de noche?","o":["Solo un timbre o bocina","Una bandera en un poste alto","Una luz delantera y un reflector trasero","Luces intermitentes en las dos ruedas"],"h1":"Una cosa ayuda al ciclista a ver, y la otra ayuda a los conductores de atrás a ver la bicicleta.","h2":"En Arkansas, los ciclistas que andan de noche deben tener luces adecuadas: una luz delantera y un reflector trasero.","p":"Correcto. De noche, la bicicleta necesita luz delantera y reflector trasero."},"ref":{"doc":"AR","page":68}},{"id":"ar-118","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, your driver's license shows a \"B\" restriction. What does it mean?","o":["You may drive only in daylight","You may not drive on Interstates","You must have an adult 21 or older with you","You must wear your glasses or contacts to drive"],"h1":"It has to do with your vision test.","h2":"In Arkansas, a \"B\" restriction means you must wear your corrective lenses when you drive, and you can be ticketed if you do not.","p":"Right. A \"B\" restriction means you must wear your corrective lenses."},"es":{"q":"En Arkansas, su licencia de conducir muestra una restricción \"B\". ¿Qué significa?","o":["Solo puede manejar de día","No puede manejar en autopistas interestatales","Debe ir con un adulto de 21 años o más","Debe usar sus lentes o lentes de contacto para manejar"],"h1":"Tiene que ver con su examen de la vista.","h2":"En Arkansas, la restricción \"B\" significa que usted debe usar sus lentes correctivos cuando maneja, y le pueden dar una multa si no lo hace.","p":"Correcto. La restricción \"B\" significa que debe usar sus lentes correctivos."},"ref":{"doc":"AR","page":71}},{"id":"ar-119","scope":"AR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arkansas, about how fast does the body get rid of alcohol?","o":["About one drink per hour","About three drinks per hour","About one drink every 10 minutes","Faster if you drink coffee"],"h1":"Coffee, fresh air and a cold shower do not speed it up.","h2":"In Arkansas, the study guide says the body gets rid of alcohol at a rate of about one drink per hour, and nothing speeds it up.","p":"Right. The body clears about one drink per hour."},"es":{"q":"En Arkansas, ¿más o menos qué tan rápido elimina el cuerpo el alcohol?","o":["Más o menos una bebida por hora","Más o menos tres bebidas por hora","Más o menos una bebida cada 10 minutos","Más rápido si toma café"],"h1":"El café, el aire fresco y una ducha fría no lo aceleran.","h2":"En Arkansas, la guía de estudio dice que el cuerpo elimina el alcohol a un ritmo de más o menos una bebida por hora, y nada lo acelera.","p":"Correcto. El cuerpo elimina más o menos una bebida por hora."},"ref":{"doc":"AR","page":74}},{"id":"ar-120","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, besides a fine, what jail time can a driver face for a first DWI conviction?","o":["None for a first offense","Up to one year","Up to 10 years","Exactly 30 days"],"h1":"A first offense can still bring time behind bars.","h2":"In Arkansas, a first DWI conviction can bring a sentence of up to one year in jail, in addition to the fine.","p":"Right. A first DWI can bring up to one year in jail."},"es":{"q":"En Arkansas, además de una multa, ¿qué tiempo de cárcel puede enfrentar un conductor por una primera condena de DWI?","o":["Ninguno por una primera vez","Hasta un año","Hasta 10 años","Exactamente 30 días"],"h1":"Una primera vez todavía puede llevar a la cárcel.","h2":"En Arkansas, una primera condena de DWI puede traer una sentencia de hasta un año de cárcel, además de la multa.","p":"Correcto. Un primer DWI puede traer hasta un año de cárcel."},"ref":{"doc":"AR","page":74}},{"id":"ar-121","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, a police officer tells you to take an alcohol test and you refuse. What can happen?","o":["Nothing, because the test is optional","You must pay for the test yourself","You can lose your driver's license","You only get a written warning"],"h1":"The law says you are required to take the test.","h2":"In Arkansas, you are required by law to take an alcohol test when an officer tells you to, and you can lose your license if you refuse.","p":"Right. Refusing the test can cost you your license."},"es":{"q":"En Arkansas, un policía le dice que haga una prueba de alcohol y usted se niega. ¿Qué puede pasar?","o":["Nada, porque la prueba es opcional","Usted debe pagar la prueba","Puede perder su licencia de conducir","Solo recibe una advertencia por escrito"],"h1":"La ley dice que usted está obligado a hacer la prueba.","h2":"En Arkansas, la ley le obliga a hacer la prueba de alcohol cuando un policía se lo indica, y usted puede perder su licencia si se niega.","p":"Correcto. Negarse a la prueba puede costarle la licencia."},"ref":{"doc":"AR","page":74}},{"id":"ar-122","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, a person under 21 is convicted of buying or having alcohol. What happens to their driving privileges?","o":["Nothing, it does not affect driving","They get a warning letter only","They must retake the vision test","They can be suspended or revoked"],"h1":"This is true even if the person was not driving.","h2":"In Arkansas, anyone under 21 convicted of buying or possessing alcohol will have their driving privileges suspended, revoked or disqualified.","p":"Right. Under 21, buying or having alcohol can cost you your license."},"es":{"q":"En Arkansas, una persona menor de 21 años es condenada por comprar o tener alcohol. ¿Qué pasa con su privilegio de manejar?","o":["Nada, no afecta el manejo","Solo recibe una carta de advertencia","Debe repetir el examen de la vista","Se lo pueden suspender o revocar"],"h1":"Esto es así aunque la persona no estuviera manejando.","h2":"En Arkansas, cualquier menor de 21 años condenado por comprar o tener alcohol tendrá su privilegio de manejar suspendido, revocado o descalificado.","p":"Correcto. Si es menor de 21, comprar o tener alcohol puede costarle la licencia."},"ref":{"doc":"AR","page":75}},{"id":"ar-123","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, you are in a crash where someone is hurt. When may you leave the scene?","o":["Only after police have talked with you","As soon as you swap phone numbers","Right away, if your car still runs","After 15 minutes, if police are late"],"h1":"The police need information from every driver first.","h2":"In Arkansas, a driver may not leave the scene of a crash with injury or death until police have talked with the drivers and collected the information they need.","p":"Right. Stay until police have talked with you."},"es":{"q":"En Arkansas, usted tiene un choque donde alguien resulta herido. ¿Cuándo puede irse del lugar?","o":["Solo después de que la policía hable con usted","En cuanto intercambie números de teléfono","De inmediato, si su auto todavía funciona","Después de 15 minutos, si la policía tarda"],"h1":"Primero la policía necesita información de cada conductor.","h2":"En Arkansas, un conductor no puede irse del lugar de un choque con heridos o muertos hasta que la policía haya hablado con los conductores y reunido la información que necesita.","p":"Correcto. Quédese hasta que la policía hable con usted."},"ref":{"doc":"AR","page":80}},{"id":"ar-124","scope":"AR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arkansas, you hit a parked car and no one is in it. What must you do?","o":["Drive away, because no one was hurt","Try to find the owner","Wait one hour, then leave","Call your insurance company only"],"h1":"The owner needs to know what happened.","h2":"In Arkansas, if you are in a crash with a parked vehicle, you must try to locate the owner.","p":"Right. Try to find the owner of the parked car."},"es":{"q":"En Arkansas, usted choca contra un auto estacionado y no hay nadie adentro. ¿Qué debe hacer?","o":["Irse, porque nadie salió herido","Tratar de encontrar al dueño","Esperar una hora y luego irse","Solo llamar a su compañía de seguros"],"h1":"El dueño necesita saber lo que pasó.","h2":"En Arkansas, si usted choca contra un vehículo estacionado, debe tratar de encontrar al dueño.","p":"Correcto. Trate de encontrar al dueño del auto estacionado."},"ref":{"doc":"AR","page":80}},{"id":"ar-125","scope":"AR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arkansas, how far should you sit from the air bag in the steering wheel?","o":["About 2 inches","About 5 inches","About 10 inches","About 3 feet"],"h1":"Measure from the center of the wheel to your breastbone.","h2":"In Arkansas, sitting 10 inches from the driver air bag, measured from the center of the steering wheel to your breastbone, gives you a clear margin of safety.","p":"Right. Sit about 10 inches from the air bag."},"es":{"q":"En Arkansas, ¿a qué distancia debe sentarse de la bolsa de aire del volante?","o":["Unas 2 pulgadas","Unas 5 pulgadas","Unas 10 pulgadas","Unos 3 pies"],"h1":"Mida desde el centro del volante hasta el esternón.","h2":"En Arkansas, sentarse a 10 pulgadas de la bolsa de aire del conductor, medidas desde el centro del volante hasta el esternón, le da un buen margen de seguridad.","p":"Correcto. Siéntese a unas 10 pulgadas de la bolsa de aire."},"ref":{"doc":"AR","page":82}},{"id":"ar-126","scope":"AR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arkansas, tires are no longer safe when the tread is worn down to what depth?","o":["1/2 of an inch","1/4 of an inch","1 inch","1/16 of an inch"],"h1":"With the penny test, you would see the top of Lincoln's head.","h2":"In Arkansas, tires are generally not safe and should be replaced when the tread is worn down to 1/16 of an inch.","p":"Right. Replace tires at 1/16 of an inch of tread."},"es":{"q":"En Arkansas, ¿a qué profundidad de dibujo dejan de ser seguras las llantas?","o":["1/2 pulgada","1/4 de pulgada","1 pulgada","1/16 de pulgada"],"h1":"Con la prueba de la moneda de un centavo, vería la parte de arriba de la cabeza de Lincoln.","h2":"En Arkansas, por lo general las llantas no son seguras y se deben cambiar cuando el dibujo está gastado hasta 1/16 de pulgada.","p":"Correcto. Cambie las llantas cuando el dibujo llegue a 1/16 de pulgada."},"ref":{"doc":"AR","page":84}},{"id":"ar-127","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, on the skills test you must find each vehicle control. How many may you miss before you fail?","o":["Three","None","One","Ten"],"h1":"It is a small number, more than one.","h2":"In Arkansas, you are allowed three missed controls on the skills test before the test is failed.","p":"Right. You may miss three controls before you fail."},"es":{"q":"En Arkansas, en la prueba práctica usted debe ubicar cada control del vehículo. ¿Cuántos puede fallar antes de reprobar?","o":["Tres","Ninguno","Uno","Diez"],"h1":"Es un número pequeño, más de uno.","h2":"En Arkansas, en la prueba práctica se permiten tres controles fallados antes de reprobar.","p":"Correcto. Puede fallar tres controles antes de reprobar."},"ref":{"doc":"AR","page":85}},{"id":"ar-128","scope":"AR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arkansas, the examiner warns you once for a rolling stop on the road test, and you do it again. What happens?","o":["You get one more warning","You fail and wait two weeks to retest","You lose your instruction permit","You must retake the written exam"],"h1":"Two misses in the same category end the test.","h2":"In Arkansas, two missed attempts in the same category fail the road test; a second rolling stop brings a two-week penalty.","p":"Right. A repeat error means a failed test and a two-week wait."},"es":{"q":"En Arkansas, en la prueba de manejo el examinador le advierte una vez por no detenerse por completo, y usted lo vuelve a hacer. ¿Qué pasa?","o":["Recibe otra advertencia","Reprueba y espera dos semanas para repetirla","Pierde su permiso de instrucción","Debe repetir el examen escrito"],"h1":"Dos fallas en la misma categoría terminan la prueba.","h2":"En Arkansas, dos fallas en la misma categoría reprueban la prueba de manejo; una segunda parada sin detenerse por completo trae un castigo de dos semanas.","p":"Correcto. Repetir el error significa reprobar y esperar dos semanas."},"ref":{"doc":"AR","page":85}},{"id":"ar-129","scope":"AR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arkansas, you bring a car for your driving skills test. Which of these means the test will not be given?","o":["The car has a full-size spare tire","The car has an automatic transmission","A donut spare tire is on the car","The car is more than 10 years old"],"h1":"Look at the tires.","h2":"In Arkansas, the skills test will not be given if a donut spare tire is on the vehicle, or if the tires are badly worn.","p":"Right. No donut spares are allowed on the test car."},"es":{"q":"En Arkansas, usted lleva un auto para su prueba práctica de manejo. ¿Cuál de estas cosas hace que no le den la prueba?","o":["El auto tiene una llanta de repuesto de tamaño normal","El auto tiene transmisión automática","El auto tiene puesta una llanta de repuesto pequeña (tipo dona)","El auto tiene más de 10 años"],"h1":"Fíjese en las llantas.","h2":"En Arkansas, no se da la prueba práctica si el vehículo tiene puesta una llanta de repuesto pequeña (tipo dona), o si las llantas están muy gastadas.","p":"Correcto. No se permiten llantas de repuesto tipo dona en el auto de la prueba."},"ref":{"doc":"AR","page":85}},{"id":"ar-130","scope":"AR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arkansas, the car for your skills test has tinted windows. Which tint will get the car turned away?","o":["Clear glass on all windows","Front windows lighter than 25%","No tint on the windshield","Front windows darker than 25%"],"h1":"There are separate limits for the front and back windows.","h2":"In Arkansas, a skills test car with window tint darker than 25% on the front or darker than 10% on the back will be denied.","p":"Right. Front tint darker than 25% is not allowed for the test."},"es":{"q":"En Arkansas, el auto para su prueba práctica tiene vidrios polarizados. ¿Qué polarizado hará que rechacen el auto?","o":["Vidrio transparente en todas las ventanas","Ventanas delanteras más claras que 25%","Sin polarizado en el parabrisas","Ventanas delanteras más oscuras que 25%"],"h1":"Hay límites distintos para las ventanas de adelante y de atrás.","h2":"En Arkansas, se rechaza un auto para la prueba práctica con polarizado más oscuro que 25% en las ventanas delanteras o más oscuro que 10% en las traseras.","p":"Correcto. No se permite polarizado delantero más oscuro que 25% en la prueba."},"ref":{"doc":"AR","page":86}},{"id":"ar-131","scope":"AR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arkansas, your instruction permit expires before you pass the skills test and buy your license. What happens?","o":["You must retake every part of the driver exam","You get a free 30-day extension","You only retake the vision test","Bad weather delays extend it automatically"],"h1":"Permits cannot be extended for any reason.","h2":"In Arkansas, if you do not finish the skills test and buy a license before the permit's 2-year expiration, you must retake all phases of the driver exam.","p":"Right. Let the permit expire and you start the exams over."},"es":{"q":"En Arkansas, su permiso de instrucción vence antes de que usted apruebe la prueba práctica y compre su licencia. ¿Qué pasa?","o":["Debe repetir todas las partes del examen de manejo","Recibe una extensión gratis de 30 días","Solo repite el examen de la vista","El mal tiempo lo extiende automáticamente"],"h1":"Los permisos no se pueden extender por ningún motivo.","h2":"En Arkansas, si no completa la prueba práctica y compra la licencia antes de que el permiso venza a los 2 años, debe repetir todas las fases del examen de manejo.","p":"Correcto. Si el permiso vence, empieza los exámenes de nuevo."},"ref":{"doc":"AR","page":86}},{"id":"az-001","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the youngest age to apply for a regular instruction permit (not one only for a school driving class)?","o":["17 years old","16 years old","15 and a half years old","14 and a half years old"],"h1":"It is half a year past a birthday, before age 16.","h2":"In Arizona you can apply for an instruction permit at 15 years and 6 months, so you can practice before you turn 16.","p":"Right. The Arizona permit starts at 15 and a half."},"es":{"q":"En Arizona, ¿cuál es la edad mínima para solicitar un permiso de aprendizaje normal (no uno solo para una clase de manejo escolar)?","o":["17 años","16 años","15 años y medio","14 años y medio"],"h1":"Es medio año después de un cumpleaños, antes de los 16.","h2":"En Arizona usted puede solicitar el permiso de aprendizaje a los 15 años y 6 meses, para practicar antes de cumplir 16.","p":"Correcto. El permiso en Arizona empieza a los 15 años y medio."},"zh":{"q":"在 Arizona，最小几岁可以申请普通的学习驾照（instruction permit，不是只用于学校驾驶课的那种）？","o":["17 岁","16 岁","15 岁半","14 岁半"],"h1":"它是某个生日后再过半年，在 16 岁之前。","h2":"在 Arizona，你 15 岁 6 个月就可以申请学习驾照，这样在 16 岁前就能练车。","p":"对。Arizona 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Arizona, tuổi nhỏ nhất để xin giấy phép tập lái thông thường (instruction permit, không phải loại chỉ dùng cho lớp học lái ở trường) là bao nhiêu?","o":["17 tuổi","16 tuổi","15 tuổi rưỡi","14 tuổi rưỡi"],"h1":"Đó là nửa năm sau một ngày sinh nhật, trước 16 tuổi.","h2":"Ở Arizona, bạn có thể xin giấy phép tập lái khi 15 tuổi 6 tháng, để có thể tập lái trước khi đủ 16 tuổi.","p":"Đúng. Ở Arizona, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Arizona, ano ang pinakabatang edad para mag-apply ng regular na instruction permit (hindi ang permit na para lang sa driving class sa paaralan)?","o":["17 taong gulang","16 taong gulang","15 at kalahating taong gulang","14 at kalahating taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan, bago mag-16.","h2":"Sa Arizona, puwede kang mag-apply ng instruction permit sa edad na 15 taon at 6 na buwan, para makapag-practice ka bago ka mag-16.","p":"Tama. Nagsisimula ang permit sa Arizona sa 15 at kalahati."},"ar":{"q":"في Arizona، ما أصغر عمر للتقدّم بطلب تصريح تعلّم عادي (instruction permit)، وليس التصريح الخاص بدروس القيادة في المدرسة فقط؟","o":["17 سنة","16 سنة","15 سنة ونصف","14 سنة ونصف"],"h1":"هو نصف سنة بعد عيد ميلاد، قبل عمر 16.","h2":"في Arizona يمكنك التقدّم بطلب تصريح التعلّم في عمر 15 سنة و6 أشهر، حتى تتدرّب قبل أن تبلغ 16.","p":"صحيح. في Arizona يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"AZ","page":10}},{"id":"az-002","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a teen who takes no driver education and no driving safety course must have supervised practice. How many hours in total?","o":["10 hours","30 hours","40 hours","50 hours"],"h1":"It is fewer hours than many other states ask for.","h2":"An Arizona teen who skips approved driver education must have a parent or guardian certify at least 30 hours of supervised driving, 10 of them at night, before getting a graduated license.","p":"Right. Arizona asks for 30 supervised hours."},"es":{"q":"En Arizona, un adolescente que no toma ningún curso de manejo ni de seguridad vial debe tener práctica supervisada. ¿Cuántas horas en total?","o":["10 horas","30 horas","40 horas","50 horas"],"h1":"Son menos horas que en muchos otros estados.","h2":"Un adolescente en Arizona que no toma un curso aprobado de educación vial necesita que su padre, madre o tutor certifique por lo menos 30 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia graduada.","p":"Correcto. Arizona pide 30 horas supervisadas."},"zh":{"q":"在 Arizona，没有上驾驶教育课、也没有上安全驾驶课的青少年必须有人监督练车。一共要多少小时？","o":["10 小时","30 小时","40 小时","50 小时"],"h1":"它比很多其他州要求的小时数少。","h2":"在 Arizona，没有上认可的驾驶教育课的青少年，必须由父母或监护人证明至少 30 小时有人监督的驾驶，其中 10 小时在夜间，才能拿到分级驾照。","p":"对。Arizona 要求 30 小时有人监督的驾驶。"},"vi":{"q":"Ở Arizona, thiếu niên không học lớp giáo dục lái xe và không học lớp lái xe an toàn phải tập lái có người giám sát. Tổng cộng bao nhiêu giờ?","o":["10 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Số giờ này ít hơn nhiều tiểu bang khác yêu cầu.","h2":"Ở Arizona, thiếu niên không học lớp giáo dục lái xe được công nhận phải có cha mẹ hoặc người giám hộ xác nhận ít nhất 30 giờ lái xe có giám sát, trong đó 10 giờ vào ban đêm, trước khi lấy bằng lái theo cấp bậc.","p":"Đúng. Arizona yêu cầu 30 giờ lái xe có giám sát."},"tl":{"q":"Sa Arizona, ang tinedyer na hindi kumuha ng driver education at walang driving safety course ay kailangang mag-practice na may nagbabantay. Ilang oras lahat?","o":["10 oras","30 oras","40 oras","50 oras"],"h1":"Mas kaunti ito kaysa sa hinihingi ng maraming ibang estado.","h2":"Sa Arizona, ang tinedyer na hindi kumuha ng aprubadong driver education ay kailangang may magulang o guardian na magpapatunay ng hindi bababa sa 30 oras ng pagmamaneho na may nagbabantay, 10 dito sa gabi, bago makakuha ng graduated license.","p":"Tama. Humihingi ang Arizona ng 30 oras na may nagbabantay."},"ar":{"q":"في Arizona، المراهق الذي لا يأخذ دورة تعليم قيادة ولا دورة قيادة آمنة يجب أن يتدرّب تحت إشراف. كم ساعة في المجموع؟","o":["10 ساعات","30 ساعة","40 ساعة","50 ساعة"],"h1":"هي ساعات أقل مما تطلبه ولايات كثيرة أخرى.","h2":"في Arizona، المراهق الذي لا يأخذ دورة تعليم قيادة معتمدة يجب أن يشهد أحد والديه أو وليّ أمره على 30 ساعة على الأقل من القيادة تحت إشراف، منها 10 ساعات في الليل، قبل الحصول على الرخصة المتدرّجة.","p":"صحيح. Arizona تطلب 30 ساعة تحت إشراف."},"ref":{"doc":"AZ","page":11}},{"id":"az-003","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, how many of the 30 supervised practice hours must be done at night?","o":["At least 10 hours","At least 5 hours","At least 15 hours","At least 20 hours"],"h1":"It is one third of the 30 total hours.","h2":"At least 10 of the 30 supervised hours must be at night in Arizona, because driving in the dark needs its own practice.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Arizona, ¿cuántas de las 30 horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la tercera parte de las 30 horas en total.","h2":"En Arizona, por lo menos 10 de las 30 horas supervisadas deben ser de noche, porque manejar en la oscuridad requiere su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Arizona，30 小时有人监督的练车中，有多少小时必须在夜间？","o":["至少 10 小时","至少 5 小时","至少 15 小时","至少 20 小时"],"h1":"它是 30 小时的三分之一。","h2":"在 Arizona，30 小时有人监督的练车中，至少 10 小时必须在夜间，因为在黑暗中开车需要专门练习。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Arizona, trong 30 giờ tập lái có giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 15 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần ba của tổng 30 giờ.","h2":"Ở Arizona, ít nhất 10 trong 30 giờ có giám sát phải lái vào ban đêm, vì lái xe trong bóng tối cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Arizona, ilan sa 30 oras ng practice na may nagbabantay ang dapat gawin sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 15 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-katlo ng kabuuang 30 oras.","h2":"Sa Arizona, hindi bababa sa 10 sa 30 oras na may nagbabantay ang dapat sa gabi, dahil ang pagmamaneho sa dilim ay kailangan ng sariling practice.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Arizona، كم ساعة من الساعات الـ30 للتدريب تحت إشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","5 ساعات على الأقل","15 ساعة على الأقل","20 ساعة على الأقل"],"h1":"هي ثلث مجموع الساعات الـ30.","h2":"في Arizona، يجب أن تكون 10 ساعات على الأقل من الساعات الـ30 تحت إشراف في الليل، لأن القيادة في الظلام تحتاج إلى تدريب خاص بها.","p":"صحيح. 10 ساعات على الأقل يجب أن تكون في الليل."},"ref":{"doc":"AZ","page":11}},{"id":"az-004","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, how long must a teen hold the instruction permit before getting a graduated license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"An Arizona teen must hold the instruction permit for at least 6 months before getting a graduated license, so there is time to practice.","p":"Right. Hold the permit for at least 6 months."},"es":{"q":"En Arizona, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de obtener la licencia graduada?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Arizona debe tener el permiso de aprendizaje por lo menos 6 meses antes de obtener la licencia graduada, para tener tiempo de practicar.","p":"Correcto. Debe tener el permiso por lo menos 6 meses."},"zh":{"q":"在 Arizona，青少年拿分级驾照前，必须持有学习驾照多久？","o":["1 个月","3 个月","1 年","6 个月"],"h1":"它是半年。","h2":"在 Arizona，青少年必须持有学习驾照至少 6 个月，才能拿分级驾照，这样有时间练习。","p":"对。持有学习驾照至少 6 个月。"},"vi":{"q":"Ở Arizona, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái theo cấp bậc?","o":["1 tháng","3 tháng","1 năm","6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Arizona, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái theo cấp bậc, để có thời gian tập lái.","p":"Đúng. Giữ giấy phép tập lái ít nhất 6 tháng."},"tl":{"q":"Sa Arizona, gaano katagal dapat hawak ng tinedyer ang instruction permit bago makakuha ng graduated license?","o":["1 buwan","3 buwan","1 taon","6 na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Arizona, dapat hawak ng tinedyer ang instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng graduated license, para may oras mag-practice.","p":"Tama. Hawakan ang permit nang hindi bababa sa 6 na buwan."},"ar":{"q":"في Arizona، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتدرّجة؟","o":["شهر واحد","3 أشهر","سنة واحدة","6 أشهر"],"h1":"هي نصف سنة.","h2":"في Arizona، يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المتدرّجة، حتى يكون عنده وقت للتدريب.","p":"صحيح. احمل التصريح 6 أشهر على الأقل."},"ref":{"doc":"AZ","page":11}},{"id":"az-005","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, where must the licensed driver sit when a permit holder is driving?","o":["In the back seat behind the driver","In the seat beside the driver","Anywhere in the vehicle","In a second car close behind"],"h1":"The helper must be close enough to see the road and help right away.","h2":"The licensed driver must sit in the seat beside an Arizona permit holder, so they can watch the road and help at once.","p":"Right. The supervisor sits beside the permit driver."},"es":{"q":"En Arizona, ¿dónde debe sentarse el conductor con licencia cuando maneja alguien con permiso?","o":["En el asiento de atrás del conductor","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro carro que va justo detrás"],"h1":"El acompañante debe estar lo bastante cerca para ver la calle y ayudar enseguida.","h2":"El conductor con licencia debe ir sentado al lado de quien maneja con permiso en Arizona, para ver la calle y ayudar de inmediato.","p":"Correcto. El supervisor se sienta al lado del conductor con permiso."},"zh":{"q":"在 Arizona，学习驾照持有人开车时，有驾照的司机必须坐在哪里？","o":["坐在司机后面的后座","坐在司机旁边的座位","车里任何地方","坐在紧跟在后面的另一辆车里"],"h1":"帮忙的人必须离得够近，能看到路，并马上帮忙。","h2":"在 Arizona，有驾照的司机必须坐在学习驾照持有人旁边的座位，这样可以看着路并马上帮忙。","p":"对。监督人坐在学车司机旁边。"},"vi":{"q":"Ở Arizona, khi người có giấy phép tập lái đang lái xe, người có bằng lái phải ngồi ở đâu?","o":["Ở ghế sau, phía sau tài xế","Ở ghế bên cạnh tài xế","Ở bất kỳ chỗ nào trong xe","Trong một xe khác chạy sát phía sau"],"h1":"Người giúp phải ở đủ gần để nhìn thấy đường và giúp ngay.","h2":"Ở Arizona, người có bằng lái phải ngồi ở ghế bên cạnh người có giấy phép tập lái, để có thể nhìn đường và giúp ngay.","p":"Đúng. Người giám sát ngồi bên cạnh người tập lái."},"tl":{"q":"Sa Arizona, saan dapat umupo ang lisensiyadong driver kapag nagmamaneho ang may permit?","o":["Sa likurang upuan, sa likod ng driver","Sa upuan sa tabi ng driver","Kahit saan sa sasakyan","Sa ibang kotse na malapit sa likod"],"h1":"Dapat sapat na malapit ang tumutulong para makita ang daan at tumulong agad.","h2":"Sa Arizona, dapat umupo ang lisensiyadong driver sa upuan sa tabi ng may permit, para mabantayan ang daan at makatulong agad.","p":"Tama. Umuupo ang nagbabantay sa tabi ng driver na may permit."},"ar":{"q":"في Arizona، أين يجب أن يجلس السائق الذي لديه رخصة عندما يقود حامل التصريح؟","o":["في المقعد الخلفي وراء السائق","في المقعد بجانب السائق","في أي مكان في السيارة","في سيارة ثانية قريبة من الخلف"],"h1":"يجب أن يكون المساعد قريبًا بما يكفي ليرى الطريق ويساعد فورًا.","h2":"في Arizona، يجب أن يجلس السائق الذي لديه رخصة في المقعد بجانب حامل التصريح، حتى يراقب الطريق ويساعد فورًا.","p":"صحيح. المشرف يجلس بجانب سائق التصريح."},"ref":{"doc":"AZ","page":10}},{"id":"az-006","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, during the first six months of a teen's graduated license, when may the teen NOT drive alone?","o":["From 10 p.m. to 6 a.m.","From 9 p.m. to 5 a.m.","From midnight to 5 a.m.","From 11 p.m. to 4 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"For the first six months, an Arizona teen with a graduated license may not drive from midnight to 5 a.m. unless a parent or guardian is in the front seat, because late night driving is the most dangerous.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Arizona, durante los primeros seis meses de la licencia graduada, ¿en qué horario NO puede manejar solo el adolescente?","o":["De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite comienza justo al empezar un nuevo día.","h2":"Durante los primeros seis meses, un adolescente con licencia graduada en Arizona no puede manejar de medianoche a 5 a.m. a menos que vaya un padre o tutor en el asiento delantero, porque manejar tarde en la noche es lo más peligroso.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Arizona，青少年拿到分级驾照的前六个月，什么时间不可以独自开车？","o":["晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","午夜 12 点到早上 5 点","晚上 11 点到早上 4 点"],"h1":"限制从新的一天刚开始时开始。","h2":"在 Arizona，青少年拿到分级驾照的前六个月，午夜 12 点到早上 5 点不可以开车，除非父母或监护人坐在前座，因为深夜开车最危险。","p":"对。一开始，午夜 12 点到早上 5 点不能开车。"},"vi":{"q":"Ở Arizona, trong sáu tháng đầu của bằng lái theo cấp bậc, khi nào thiếu niên KHÔNG được lái xe một mình?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Ở Arizona, trong sáu tháng đầu, thiếu niên có bằng lái theo cấp bậc không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi cha mẹ hoặc người giám hộ ngồi ở ghế trước, vì lái xe khuya là nguy hiểm nhất.","p":"Đúng. Lúc đầu, không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Arizona, sa unang anim na buwan ng graduated license ng tinedyer, kailan HINDI siya puwedeng magmaneho nang mag-isa?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon sa pinakasimula ng bagong araw.","h2":"Sa unang anim na buwan, ang tinedyer sa Arizona na may graduated license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m. maliban kung may magulang o guardian sa harapang upuan, dahil ang pagmamaneho sa hatinggabi ang pinakadelikado.","p":"Tama. Sa simula, bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Arizona، في الأشهر الستة الأولى من الرخصة المتدرّجة للمراهق، متى لا يجوز له أن يقود وحده؟","o":["من 10 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"يبدأ المنع في أول لحظة من يوم جديد.","h2":"في الأشهر الستة الأولى، لا يجوز للمراهق في Arizona الذي يحمل رخصة متدرّجة أن يقود من منتصف الليل إلى 5 صباحًا إلا إذا كان أحد والديه أو وليّ أمره في المقعد الأمامي، لأن القيادة في آخر الليل هي الأخطر.","p":"صحيح. في البداية، لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"AZ","page":11}},{"id":"az-007","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a new teen driver wants to drive at 1 a.m. in the first six months. Who can make this legal by riding along?","o":["A licensed parent or guardian in the front seat","Any friend who is 18 or older","A younger brother or sister","Any passenger who has a permit"],"h1":"It must be an adult who is responsible for the teen.","h2":"In the first six months, an Arizona teen may drive between midnight and 5 a.m. when a licensed parent or guardian sits in the front passenger seat.","p":"Right. A licensed parent or guardian in front makes it legal."},"es":{"q":"En Arizona, un conductor adolescente nuevo quiere manejar a la 1 a.m. en los primeros seis meses. ¿Quién puede hacerlo legal si lo acompaña?","o":["Un padre o tutor con licencia en el asiento delantero","Cualquier amigo de 18 años o más","Un hermano o hermana menor","Cualquier pasajero que tenga permiso"],"h1":"Debe ser un adulto responsable del adolescente.","h2":"En los primeros seis meses, un adolescente en Arizona puede manejar entre medianoche y 5 a.m. si un padre o tutor con licencia va en el asiento delantero.","p":"Correcto. Un padre o tutor con licencia adelante lo hace legal."},"zh":{"q":"在 Arizona，一个新的青少年司机在前六个月想在凌晨 1 点开车。谁一起坐车可以让这样做合法？","o":["坐在前座、有驾照的父母或监护人","任何 18 岁或以上的朋友","弟弟或妹妹","任何有学习驾照的乘客"],"h1":"必须是对这个青少年负责的成年人。","h2":"在 Arizona，前六个月里，如果有驾照的父母或监护人坐在前排乘客座位，青少年可以在午夜 12 点到早上 5 点之间开车。","p":"对。有驾照的父母或监护人坐在前面，就合法。"},"vi":{"q":"Ở Arizona, một tài xế thiếu niên mới muốn lái xe lúc 1 giờ sáng trong sáu tháng đầu. Ai đi cùng thì việc này hợp pháp?","o":["Cha mẹ hoặc người giám hộ có bằng lái, ngồi ở ghế trước","Bất kỳ người bạn nào từ 18 tuổi trở lên","Một em trai hoặc em gái","Bất kỳ hành khách nào có giấy phép tập lái"],"h1":"Phải là một người lớn chịu trách nhiệm cho thiếu niên đó.","h2":"Ở Arizona, trong sáu tháng đầu, thiếu niên được lái xe từ nửa đêm đến 5 giờ sáng khi cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế hành khách phía trước.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái ngồi phía trước thì hợp pháp."},"tl":{"q":"Sa Arizona, gustong magmaneho ng bagong tinedyer na driver nang 1 a.m. sa unang anim na buwan. Sino ang puwedeng sumakay para maging legal ito?","o":["Lisensiyadong magulang o guardian sa harapang upuan","Kahit sinong kaibigan na 18 o mas matanda","Nakababatang kapatid","Kahit sinong pasahero na may permit"],"h1":"Dapat ito ay adult na responsable sa tinedyer.","h2":"Sa unang anim na buwan, puwedeng magmaneho ang tinedyer sa Arizona mula hatinggabi hanggang 5 a.m. kapag nakaupo sa harapang upuan ng pasahero ang lisensiyadong magulang o guardian.","p":"Tama. Legal ito kapag may lisensiyadong magulang o guardian sa harap."},"ar":{"q":"في Arizona، سائق مراهق جديد يريد أن يقود في الساعة 1 صباحًا في الأشهر الستة الأولى. من يجعل هذا قانونيًا إذا ركب معه؟","o":["أحد الوالدين أو وليّ الأمر الذي لديه رخصة، في المقعد الأمامي","أي صديق عمره 18 سنة أو أكثر","أخ أو أخت أصغر","أي راكب لديه تصريح تعلّم"],"h1":"يجب أن يكون شخصًا بالغًا مسؤولًا عن المراهق.","h2":"في الأشهر الستة الأولى، يجوز للمراهق في Arizona أن يقود بين منتصف الليل و5 صباحًا عندما يجلس أحد والديه أو وليّ أمره الذي لديه رخصة في مقعد الراكب الأمامي.","p":"صحيح. أحد الوالدين أو وليّ الأمر الذي لديه رخصة في الأمام يجعل ذلك قانونيًا."},"ref":{"doc":"AZ","page":11}},{"id":"az-008","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, in the first six months of a graduated license, how many passengers under 18 may a teen carry, not counting brothers and sisters?","o":["None at all","Two","Three","One"],"h1":"It is the smallest number above zero.","h2":"In the first six months, an Arizona teen driver may carry only one passenger under 18 who is not a brother or sister, because friends in the car are a big distraction.","p":"Right. Only one passenger under 18 at first."},"es":{"q":"En Arizona, en los primeros seis meses de la licencia graduada, ¿cuántos pasajeros menores de 18 puede llevar un adolescente, sin contar a sus hermanos?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Es el número más pequeño mayor que cero.","h2":"En los primeros seis meses, un conductor adolescente en Arizona puede llevar solo un pasajero menor de 18 que no sea su hermano o hermana, porque los amigos en el carro distraen mucho.","p":"Correcto. Al principio solo un pasajero menor de 18."},"zh":{"q":"在 Arizona，分级驾照的前六个月，不算兄弟姐妹，青少年可以载几个 18 岁以下的乘客？","o":["一个也不行","两个","三个","一个"],"h1":"它是比零大的最小数字。","h2":"在 Arizona，前六个月里，青少年司机只可以载一个不是兄弟姐妹的 18 岁以下乘客，因为车里有朋友会很分心。","p":"对。一开始只可以载一个 18 岁以下的乘客。"},"vi":{"q":"Ở Arizona, trong sáu tháng đầu của bằng lái theo cấp bậc, thiếu niên được chở bao nhiêu hành khách dưới 18 tuổi, không tính anh chị em ruột?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Arizona, trong sáu tháng đầu, tài xế thiếu niên chỉ được chở một hành khách dưới 18 tuổi không phải anh chị em ruột, vì bạn bè trong xe làm mất tập trung rất nhiều.","p":"Đúng. Lúc đầu chỉ được chở một hành khách dưới 18 tuổi."},"tl":{"q":"Sa Arizona, sa unang anim na buwan ng graduated license, ilang pasahero na wala pang 18 ang puwedeng isakay ng tinedyer, hindi kasama ang mga kapatid?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Ito ang pinakamaliit na numero na higit sa zero.","h2":"Sa unang anim na buwan, ang tinedyer na driver sa Arizona ay puwedeng magsakay ng isang pasahero lang na wala pang 18 na hindi niya kapatid, dahil malaking abala ang mga kaibigan sa kotse.","p":"Tama. Isang pasahero lang na wala pang 18 sa simula."},"ar":{"q":"في Arizona، في الأشهر الستة الأولى من الرخصة المتدرّجة، كم راكبًا عمره أقل من 18 سنة يجوز للمراهق أن ينقل، من غير حساب الإخوة والأخوات؟","o":["ولا أحد","اثنان","ثلاثة","واحد"],"h1":"هو أصغر رقم أكبر من الصفر.","h2":"في الأشهر الستة الأولى، يجوز للسائق المراهق في Arizona أن ينقل راكبًا واحدًا فقط عمره أقل من 18 سنة وليس أخًا أو أختًا، لأن الأصدقاء في السيارة يشتّتون الانتباه كثيرًا.","p":"صحيح. في البداية راكب واحد فقط عمره أقل من 18."},"ref":{"doc":"AZ","page":11}},{"id":"az-009","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, how many questions are on the regular written test for a driver license?","o":["20 questions","30 questions","40 questions","50 questions"],"h1":"It is the same number as the supervised practice hours.","h2":"The Arizona written test for a regular license has 30 multiple choice questions about signs, laws and safe driving.","p":"Right. The Arizona written test has 30 questions."},"es":{"q":"En Arizona, ¿cuántas preguntas tiene el examen escrito normal para la licencia de manejo?","o":["20 preguntas","30 preguntas","40 preguntas","50 preguntas"],"h1":"Es el mismo número que las horas de práctica supervisada.","h2":"El examen escrito de Arizona para la licencia normal tiene 30 preguntas de opción múltiple sobre señales, leyes y manejo seguro.","p":"Correcto. El examen escrito de Arizona tiene 30 preguntas."},"zh":{"q":"在 Arizona，普通驾照的笔试有多少道题？","o":["20 道题","30 道题","40 道题","50 道题"],"h1":"它和有人监督练车的小时数一样。","h2":"Arizona 普通驾照的笔试有 30 道选择题，内容是标志、法律和安全驾驶。","p":"对。Arizona 的笔试有 30 道题。"},"vi":{"q":"Ở Arizona, bài thi viết cho bằng lái thông thường có bao nhiêu câu hỏi?","o":["20 câu","30 câu","40 câu","50 câu"],"h1":"Bằng với số giờ tập lái có giám sát.","h2":"Bài thi viết ở Arizona cho bằng lái thông thường có 30 câu hỏi trắc nghiệm về biển báo, luật và lái xe an toàn.","p":"Đúng. Bài thi viết ở Arizona có 30 câu hỏi."},"tl":{"q":"Sa Arizona, ilang tanong ang nasa regular na written test para sa driver license?","o":["20 tanong","30 tanong","40 tanong","50 tanong"],"h1":"Pareho ito ng bilang ng oras ng practice na may nagbabantay.","h2":"Ang written test sa Arizona para sa regular na lisensiya ay may 30 multiple choice na tanong tungkol sa mga karatula, batas at ligtas na pagmamaneho.","p":"Tama. May 30 tanong ang written test sa Arizona."},"ar":{"q":"في Arizona، كم سؤالًا في الاختبار الكتابي العادي لرخصة القيادة؟","o":["20 سؤالًا","30 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"هو نفس عدد ساعات التدريب تحت إشراف.","h2":"الاختبار الكتابي في Arizona للرخصة العادية فيه 30 سؤال اختيار من متعدّد عن الإشارات والقوانين والقيادة الآمنة.","p":"صحيح. الاختبار الكتابي في Arizona فيه 30 سؤالًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-010","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what score do you need to pass the written knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"You must get four out of every five questions right.","h2":"You need at least 80 percent correct to pass the Arizona knowledge test, which is 24 of the 30 questions.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Arizona, ¿qué puntaje necesita para aprobar el examen escrito de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen de Arizona, es decir 24 de las 30 preguntas.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Arizona，笔试（知识考试）要考多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"每五道题你必须答对四道。","h2":"在 Arizona，知识考试你至少要答对 80% 才能通过，也就是 30 道题答对 24 道。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Arizona, bạn cần bao nhiêu điểm để đậu bài thi kiến thức viết?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Bạn phải trả lời đúng bốn trong mỗi năm câu.","h2":"Bạn cần trả lời đúng ít nhất 80 phần trăm để đậu bài thi kiến thức ở Arizona, tức là 24 trong 30 câu.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Arizona, anong score ang kailangan para pumasa sa written knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Dapat tama ang apat sa bawat limang tanong.","h2":"Kailangan mo ng hindi bababa sa 80 porsiyentong tama para pumasa sa knowledge test sa Arizona, ibig sabihin 24 sa 30 tanong.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Arizona، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي للمعرفة؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"يجب أن تجيب بشكل صحيح عن أربعة من كل خمسة أسئلة.","h2":"تحتاج إلى 80 بالمئة إجابات صحيحة على الأقل لتنجح في اختبار المعرفة في Arizona، أي 24 من 30 سؤالًا.","p":"صحيح. تحتاج إلى 80 بالمئة لتنجح."},"ref":{"doc":"AZ","page":null}},{"id":"az-012","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a driver with an instruction permit use a cell phone while driving?","o":["Yes, if it is in hands-free mode","No, only in an emergency where stopping is not possible","Yes, but only to read a map","Yes, when stopped at a red light"],"h1":"Permit drivers have a stricter rule than adult drivers.","h2":"An Arizona permit holder may not use a phone or other wireless device while driving, even hands-free, except in a real emergency, so that all attention stays on learning to drive.","p":"Right. Permit drivers may not use a phone except in an emergency."},"es":{"q":"En Arizona, ¿puede un conductor con permiso de aprendizaje usar el celular mientras maneja?","o":["Sí, si está en modo manos libres","No, solo en una emergencia donde no se puede parar","Sí, pero solo para leer un mapa","Sí, cuando está detenido en un semáforo en rojo"],"h1":"Los conductores con permiso tienen una regla más estricta que los adultos.","h2":"Quien tiene permiso de aprendizaje en Arizona no puede usar el celular ni otro aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo en una emergencia real, para que toda su atención esté en aprender a manejar.","p":"Correcto. Con permiso no se usa el celular, salvo en una emergencia."},"zh":{"q":"在 Arizona，持有学习驾照的司机开车时可以用手机吗？","o":["可以，如果是免提模式","不可以，只有在无法停车的紧急情况下才可以","可以，但只能看地图","可以，在红灯停车时"],"h1":"学车司机的规定比成年司机更严。","h2":"在 Arizona，学习驾照持有人开车时不可以用手机或其他无线设备，免提也不行，只有真正的紧急情况除外，这样注意力可以全部放在学开车上。","p":"对。学车司机除了紧急情况，不可以用手机。"},"vi":{"q":"Ở Arizona, tài xế có giấy phép tập lái có được dùng điện thoại di động khi lái xe không?","o":["Được, nếu dùng chế độ rảnh tay","Không, chỉ được dùng trong trường hợp khẩn cấp mà không thể dừng xe","Được, nhưng chỉ để xem bản đồ","Được, khi dừng ở đèn đỏ"],"h1":"Người tập lái có quy định nghiêm hơn tài xế người lớn.","h2":"Ở Arizona, người có giấy phép tập lái không được dùng điện thoại hay thiết bị không dây khác khi lái xe, kể cả rảnh tay, trừ khi thật sự khẩn cấp, để toàn bộ sự chú ý dành cho việc học lái xe.","p":"Đúng. Người tập lái không được dùng điện thoại, trừ khi khẩn cấp."},"tl":{"q":"Sa Arizona, puwede bang gumamit ng cell phone habang nagmamaneho ang driver na may instruction permit?","o":["Oo, kung naka-hands-free mode","Hindi, maliban sa emergency na hindi posibleng huminto","Oo, pero para lang tumingin ng mapa","Oo, kapag nakahinto sa red light"],"h1":"Mas mahigpit ang patakaran para sa may permit kaysa sa adult na driver.","h2":"Sa Arizona, ang may permit ay hindi puwedeng gumamit ng phone o ibang wireless device habang nagmamaneho, kahit hands-free, maliban sa totoong emergency, para buong atensiyon ay nasa pag-aaral magmaneho.","p":"Tama. Bawal sa may permit ang phone maliban sa emergency."},"ar":{"q":"في Arizona، هل يجوز للسائق الذي يحمل تصريح تعلّم أن يستعمل الهاتف المحمول أثناء القيادة؟","o":["نعم، إذا كان بوضع عدم استخدام اليدين","لا، إلا في حالة طارئة لا يمكن فيها التوقّف","نعم، لكن فقط لقراءة الخريطة","نعم، عند التوقّف عند الإشارة الحمراء"],"h1":"سائقو التصريح عليهم قاعدة أشدّ من السائقين البالغين.","h2":"في Arizona، لا يجوز لحامل التصريح أن يستعمل الهاتف أو أي جهاز لاسلكي آخر أثناء القيادة، حتى بدون استخدام اليدين، إلا في حالة طارئة حقيقية، حتى يبقى كل الانتباه على تعلّم القيادة.","p":"صحيح. سائقو التصريح لا يستعملون الهاتف إلا في حالة طارئة."},"ref":{"doc":"AZ","page":null}},{"id":"az-013","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, how may an adult driver with a full license use a cell phone while driving?","o":["Holding it in one hand","Resting it on the lap","Holding it with the shoulder","Only in hands-free mode"],"h1":"Your hands and body may not hold the phone.","h2":"Arizona's hands-free law lets drivers use a phone only in hands-free mode; you may not hold or support it with any part of your body.","p":"Right. In Arizona the phone must be hands-free."},"es":{"q":"En Arizona, ¿cómo puede un conductor adulto con licencia usar el celular mientras maneja?","o":["Sosteniéndolo con una mano","Apoyándolo en las piernas","Sosteniéndolo con el hombro","Solo en modo manos libres"],"h1":"Ni sus manos ni su cuerpo pueden sostener el teléfono.","h2":"La ley de manos libres de Arizona permite usar el teléfono solo en modo manos libres; usted no puede sostenerlo ni apoyarlo con ninguna parte del cuerpo.","p":"Correcto. En Arizona el teléfono debe ir en manos libres."},"zh":{"q":"在 Arizona，有正式驾照的成年司机开车时可以怎样用手机？","o":["用一只手拿着","放在大腿上","用肩膀夹着","只能用免提模式"],"h1":"你的手和身体都不可以拿着手机。","h2":"Arizona 的免提法律（hands-free law）规定，司机只能用免提模式用手机；你不可以用身体任何部位拿着或托着手机。","p":"对。在 Arizona，手机必须免提。"},"vi":{"q":"Ở Arizona, tài xế người lớn có bằng lái đầy đủ được dùng điện thoại di động khi lái xe như thế nào?","o":["Cầm bằng một tay","Để trên đùi","Kẹp bằng vai","Chỉ ở chế độ rảnh tay"],"h1":"Tay và cơ thể bạn không được giữ điện thoại.","h2":"Luật rảnh tay (hands-free law) của Arizona chỉ cho phép tài xế dùng điện thoại ở chế độ rảnh tay; bạn không được cầm hay đỡ điện thoại bằng bất kỳ bộ phận nào của cơ thể.","p":"Đúng. Ở Arizona, điện thoại phải ở chế độ rảnh tay."},"tl":{"q":"Sa Arizona, paano puwedeng gumamit ng cell phone habang nagmamaneho ang adult na driver na may buong lisensiya?","o":["Hawak sa isang kamay","Nakapatong sa hita","Ipit ng balikat","Sa hands-free mode lang"],"h1":"Hindi puwedeng hawakan ng kamay o katawan mo ang phone.","h2":"Ayon sa hands-free law ng Arizona, puwedeng gumamit ng phone ang driver sa hands-free mode lang; hindi mo ito puwedeng hawakan o suportahan ng anumang bahagi ng katawan.","p":"Tama. Sa Arizona, dapat hands-free ang phone."},"ar":{"q":"في Arizona، كيف يجوز للسائق البالغ الذي لديه رخصة كاملة أن يستعمل الهاتف المحمول أثناء القيادة؟","o":["يمسكه بيد واحدة","يضعه على حضنه","يمسكه بكتفه","فقط بوضع عدم استخدام اليدين"],"h1":"لا يجوز أن تمسك الهاتف بيديك أو بجسمك.","h2":"قانون عدم استخدام اليدين في Arizona (hands-free law) يسمح للسائقين باستعمال الهاتف فقط بوضع عدم استخدام اليدين؛ لا يجوز أن تمسكه أو تسنده بأي جزء من جسمك.","p":"صحيح. في Arizona يجب أن يكون الهاتف بدون استخدام اليدين."},"ref":{"doc":"AZ","page":20}},{"id":"az-014","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, you see a stopped tow truck on the shoulder with flashing lights. There are two lanes your way. What should you do?","o":["Keep your lane and speed","Stop behind the tow truck","Move to the lane not next to it, if safe","Honk and pass quickly"],"h1":"Give the people on the shoulder more room.","h2":"Arizona's move over law says to move into a lane that is not next to a stopped vehicle with flashing lights when you can do it safely, to protect people working by the road.","p":"Right. Move over to a lane that is not next to it."},"es":{"q":"En Arizona, ve una grúa detenida en el acotamiento con luces intermitentes. Hay dos carriles en su dirección. ¿Qué debe hacer?","o":["Seguir en su carril y a la misma velocidad","Detenerse detrás de la grúa","Cambiarse al carril que no está junto a ella, si es seguro","Tocar el claxon y pasar rápido"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"La ley de Arizona de cambiarse de carril dice que debe pasar a un carril que no esté junto al vehículo detenido con luces intermitentes, cuando sea seguro, para proteger a quienes trabajan junto a la vía.","p":"Correcto. Cámbiese a un carril que no esté junto a ella."},"zh":{"q":"在 Arizona，你看到路肩上停着一辆闪灯的拖车。你这个方向有两条车道。你应该怎么做？","o":["保持车道和速度","停在拖车后面","如果安全，换到不挨着它的车道","按喇叭，快速开过去"],"h1":"给路肩上的人更多空间。","h2":"Arizona 的让道法（move over law）规定，如果安全，要换到不挨着闪灯停车的车道，以保护在路边工作的人。","p":"对。换到不挨着它的车道。"},"vi":{"q":"Ở Arizona, bạn thấy một xe kéo đang dừng trên lề đường, có đèn nhấp nháy. Chiều của bạn có hai làn xe. Bạn nên làm gì?","o":["Giữ làn và tốc độ","Dừng phía sau xe kéo","Chuyển sang làn không sát bên nó, nếu an toàn","Bấm còi và chạy qua nhanh"],"h1":"Chừa thêm chỗ cho những người trên lề đường.","h2":"Luật nhường làn (move over law) của Arizona nói phải chuyển sang làn không sát bên xe đang dừng có đèn nhấp nháy khi làm được một cách an toàn, để bảo vệ những người làm việc bên đường.","p":"Đúng. Chuyển sang làn không sát bên nó."},"tl":{"q":"Sa Arizona, may nakita kang nakahintong tow truck sa gilid ng daan (shoulder) na may kumikislap na ilaw. May dalawang lane sa direksiyon mo. Ano ang dapat mong gawin?","o":["Manatili sa lane mo at sa bilis mo","Huminto sa likod ng tow truck","Lumipat sa lane na hindi katabi nito, kung ligtas","Bumusina at lumampas nang mabilis"],"h1":"Bigyan ng mas malaking espasyo ang mga tao sa gilid ng daan.","h2":"Sinasabi ng move over law ng Arizona na lumipat sa lane na hindi katabi ng nakahintong sasakyan na may kumikislap na ilaw kapag ligtas itong gawin, para protektahan ang mga taong nagtatrabaho sa tabi ng daan.","p":"Tama. Lumipat sa lane na hindi katabi nito."},"ar":{"q":"في Arizona، ترى شاحنة سحب متوقّفة على كتف الطريق وأضواؤها تومض. في اتجاهك مساران. ماذا يجب أن تفعل؟","o":["ابقَ في مسارك وبنفس سرعتك","توقّف خلف شاحنة السحب","انتقل إلى المسار غير المجاور لها، إذا كان ذلك آمنًا","اضغط على الزمور وتجاوز بسرعة"],"h1":"أعطِ الناس على كتف الطريق مساحة أكبر.","h2":"قانون الابتعاد في Arizona (move over law) يقول أن تنتقل إلى مسار غير مجاور للمركبة المتوقّفة التي أضواؤها تومض عندما تستطيع ذلك بأمان، لحماية الناس الذين يعملون بجانب الطريق.","p":"صحيح. انتقل إلى مسار غير مجاور لها."},"ref":{"doc":"AZ","page":31}},{"id":"az-015","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, you cannot safely change lanes away from a stopped vehicle with flashing lights. What must you do?","o":["Slow down and pass with caution","Keep going at the speed limit","Stop in your lane until it leaves","Drive on the shoulder to pass"],"h1":"If you cannot give more space, give more time.","h2":"When you cannot safely move over in Arizona, you must slow down and pass with care, so you have time to react if someone steps into the road.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Arizona, no puede cambiarse de carril con seguridad para alejarse de un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Seguir al límite de velocidad","Parar en su carril hasta que se vaya","Manejar por el acotamiento para pasar"],"h1":"Si no puede dar más espacio, dé más tiempo.","h2":"Cuando no puede cambiarse de carril con seguridad en Arizona, debe bajar la velocidad y pasar con cuidado, para tener tiempo de reaccionar si alguien entra a la vía.","p":"Correcto. Si no puede cambiarse, baje la velocidad."},"zh":{"q":"在 Arizona，你无法安全地换道离开一辆闪灯的停着的车。你必须怎么做？","o":["减速，小心开过去","按限速继续开","在你的车道停下，直到它离开","开上路肩超过去"],"h1":"如果不能给更多空间，就给更多时间。","h2":"在 Arizona，如果你不能安全地换道，就必须减速并小心开过去，这样如果有人走到路上，你有时间反应。","p":"对。如果不能换道，就减速。"},"vi":{"q":"Ở Arizona, bạn không thể đổi làn một cách an toàn để tránh xa một xe đang dừng có đèn nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và chạy qua cẩn thận","Tiếp tục chạy bằng tốc độ giới hạn","Dừng trong làn của bạn cho đến khi nó đi","Chạy trên lề đường để vượt qua"],"h1":"Nếu không thể chừa thêm chỗ, hãy cho thêm thời gian.","h2":"Ở Arizona, khi không thể chuyển làn an toàn, bạn phải giảm tốc độ và chạy qua cẩn thận, để có thời gian phản ứng nếu có người bước ra đường.","p":"Đúng. Nếu không thể chuyển làn, hãy giảm tốc độ."},"tl":{"q":"Sa Arizona, hindi ka ligtas na makakalipat ng lane palayo sa nakahintong sasakyan na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Bumagal at lumampas nang maingat","Tuloy lang sa speed limit","Huminto sa lane mo hanggang umalis ito","Magmaneho sa shoulder para lumampas"],"h1":"Kung hindi ka makapagbigay ng mas malaking espasyo, magbigay ng mas mahabang oras.","h2":"Sa Arizona, kapag hindi ka ligtas na makakalipat ng lane, dapat kang bumagal at lumampas nang maingat, para may oras kang kumilos kung may taong pumasok sa daan.","p":"Tama. Kung hindi ka makalipat, bumagal."},"ar":{"q":"في Arizona، لا تستطيع أن تغيّر المسار بأمان بعيدًا عن مركبة متوقّفة أضواؤها تومض. ماذا يجب أن تفعل؟","o":["خفّف السرعة وتجاوز بحذر","استمر بالسرعة القصوى المسموحة","توقّف في مسارك حتى تذهب","قُد على كتف الطريق لتتجاوز"],"h1":"إذا لم تستطع أن تعطي مساحة أكبر، فأعطِ وقتًا أكثر.","h2":"عندما لا تستطيع أن تبتعد بأمان في Arizona، يجب أن تخفّف السرعة وتتجاوز بحذر، حتى يكون عندك وقت للتصرّف إذا دخل شخص إلى الطريق.","p":"صحيح. إذا لم تستطع أن تبتعد، خفّف السرعة."},"ref":{"doc":"AZ","page":31}},{"id":"az-016","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, which stopped vehicles does the move over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only road work trucks","Any stopped vehicle with flashing lights"],"h1":"Since 2011 the law covers stranded drivers too.","h2":"Arizona's move over law covers any stationary vehicle with its flashing lights on, including a stranded driver on the shoulder, not just emergency vehicles.","p":"Right. It covers any stopped vehicle with flashing lights."},"es":{"q":"En Arizona, ¿a qué vehículos detenidos se aplica la ley de cambiarse de carril?","o":["Solo a patrullas de policía","Solo a ambulancias y bomberos","Solo a camiones de obras viales","A cualquier vehículo detenido con luces intermitentes"],"h1":"Desde 2011 la ley también protege a conductores varados.","h2":"La ley de Arizona se aplica a cualquier vehículo detenido con las luces intermitentes encendidas, incluido un conductor varado en el acotamiento, no solo a vehículos de emergencia.","p":"Correcto. Se aplica a cualquier vehículo detenido con luces intermitentes."},"zh":{"q":"在 Arizona，让道法（move over law）适用于哪些停着的车？","o":["只有警车","只有救护车和消防车","只有道路施工车","任何闪灯的停着的车"],"h1":"从 2011 年起，这个法律也包括车坏在路边的司机。","h2":"Arizona 的让道法适用于任何开着闪灯停着的车，包括车坏在路肩的司机，不只是紧急车辆。","p":"对。它适用于任何闪灯的停着的车。"},"vi":{"q":"Ở Arizona, luật nhường làn (move over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe làm đường","Bất kỳ xe đang dừng nào có đèn nhấp nháy"],"h1":"Từ năm 2011, luật này cũng áp dụng cho tài xế bị kẹt bên đường.","h2":"Luật nhường làn của Arizona áp dụng cho bất kỳ xe đang đứng yên nào bật đèn nhấp nháy, kể cả tài xế bị kẹt trên lề đường, không chỉ xe khẩn cấp.","p":"Đúng. Luật áp dụng cho bất kỳ xe đang dừng nào có đèn nhấp nháy."},"tl":{"q":"Sa Arizona, aling mga nakahintong sasakyan ang sakop ng move over law?","o":["Mga kotse ng pulis lang","Mga ambulansiya at fire truck lang","Mga truck ng road work lang","Anumang nakahintong sasakyan na may kumikislap na ilaw"],"h1":"Mula 2011, sakop na rin ng batas ang mga driver na na-stranded.","h2":"Sakop ng move over law ng Arizona ang anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw, kasama ang driver na na-stranded sa shoulder, hindi lang mga emergency vehicle.","p":"Tama. Sakop nito ang anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Arizona، ما المركبات المتوقّفة التي يشملها قانون الابتعاد (move over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","شاحنات أعمال الطرق فقط","أي مركبة متوقّفة أضواؤها تومض"],"h1":"منذ سنة 2011 يشمل القانون أيضًا السائقين العالقين.","h2":"قانون الابتعاد في Arizona يشمل أي مركبة متوقّفة أضواؤها الوامضة مشغّلة، ومنها سائق عالق على كتف الطريق، وليس مركبات الطوارئ فقط.","p":"صحيح. يشمل أي مركبة متوقّفة أضواؤها تومض."},"ref":{"doc":"AZ","page":31}},{"id":"az-017","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit when approaching a school crossing?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is the slowest limit set by state law.","h2":"Arizona law sets 15 mph when approaching a school crossing, because children may step into the street at any moment.","p":"Right. Approaching a school crossing, the limit is 15 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad al acercarse a un cruce escolar?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es el límite más bajo que fija la ley estatal.","h2":"La ley de Arizona fija 15 mph al acercarse a un cruce escolar, porque los niños pueden entrar a la calle en cualquier momento.","p":"Correcto. Al acercarse a un cruce escolar, el límite es 15 mph."},"zh":{"q":"在 Arizona，除非标志另有规定，接近学校人行横道时限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"它是州法律规定的最低限速。","h2":"Arizona 法律规定，接近学校人行横道时限速 15 mph，因为孩子随时可能走到街上。","p":"对。接近学校人行横道，限速 15 mph。"},"vi":{"q":"Ở Arizona, trừ khi có biển báo khác, tốc độ giới hạn khi đến gần chỗ băng qua đường của trường học là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Đó là giới hạn chậm nhất do luật tiểu bang đặt ra.","h2":"Luật Arizona đặt giới hạn 15 mph khi đến gần chỗ băng qua đường của trường học, vì trẻ em có thể bước ra đường bất cứ lúc nào.","p":"Đúng. Khi đến gần chỗ băng qua đường của trường học, giới hạn là 15 mph."},"tl":{"q":"Sa Arizona, maliban kung iba ang sabi ng karatula, ano ang speed limit kapag papalapit sa tawiran ng paaralan (school crossing)?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Ito ang pinakamabagal na limit na itinakda ng batas ng estado.","h2":"Itinakda ng batas ng Arizona ang 15 mph kapag papalapit sa tawiran ng paaralan, dahil puwedeng lumabas ang mga bata sa kalye anumang oras.","p":"Tama. Papalapit sa tawiran ng paaralan, 15 mph ang limit."},"ar":{"q":"في Arizona، إلا إذا قالت لافتة غير ذلك، ما حدّ السرعة عند الاقتراب من معبر مدرسة؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"هو أبطأ حدّ يضعه قانون الولاية.","h2":"قانون Arizona يضع 15 mph عند الاقتراب من معبر مدرسة، لأن الأطفال قد يدخلون الشارع في أي لحظة.","p":"صحيح. عند الاقتراب من معبر مدرسة، الحدّ 15 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-018","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, unless a sign says otherwise, what is the speed limit in a business or residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is ten more than the school crossing limit.","h2":"Arizona law sets 25 mph in business and residential districts when no other limit is posted, because people, driveways and parked cars are close to the road.","p":"Right. Business and residential districts are 25 mph."},"es":{"q":"En Arizona, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial o residencial?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es diez más que el límite del cruce escolar.","h2":"La ley de Arizona fija 25 mph en zonas comerciales y residenciales cuando no hay otro límite indicado, porque hay personas, entradas de garaje y carros estacionados cerca de la calle.","p":"Correcto. En zonas comerciales y residenciales el límite es 25 mph."},"zh":{"q":"在 Arizona，除非标志另有规定，商业区或住宅区的限速是多少？","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"它比学校人行横道的限速多 10。","h2":"Arizona 法律规定，没有其他限速标志时，商业区和住宅区限速 25 mph，因为行人、车道出入口和停着的车都离路很近。","p":"对。商业区和住宅区限速 25 mph。"},"vi":{"q":"Ở Arizona, trừ khi có biển báo khác, tốc độ giới hạn trong khu thương mại hoặc khu dân cư là bao nhiêu?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Nhiều hơn giới hạn ở chỗ băng qua đường của trường học 10.","h2":"Luật Arizona đặt giới hạn 25 mph trong khu thương mại và khu dân cư khi không có biển báo giới hạn khác, vì người đi bộ, lối xe ra vào và xe đậu ở gần đường.","p":"Đúng. Khu thương mại và khu dân cư là 25 mph."},"tl":{"q":"Sa Arizona, maliban kung iba ang sabi ng karatula, ano ang speed limit sa business o residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Sampu itong mas mataas kaysa sa limit sa tawiran ng paaralan.","h2":"Itinakda ng batas ng Arizona ang 25 mph sa business at residential district kapag walang ibang nakapaskil na limit, dahil malapit sa daan ang mga tao, driveway at nakaparadang kotse.","p":"Tama. 25 mph sa business at residential district."},"ar":{"q":"في Arizona، إلا إذا قالت لافتة غير ذلك، ما حدّ السرعة في منطقة تجارية أو سكنية؟","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"هو أكثر بعشرة من حدّ معبر المدرسة.","h2":"قانون Arizona يضع 25 mph في المناطق التجارية والسكنية عندما لا توجد لافتة بحدّ آخر، لأن الناس ومداخل البيوت والسيارات المتوقّفة قريبة من الطريق.","p":"صحيح. المناطق التجارية والسكنية 25 mph."},"ref":{"doc":"AZ","page":32}},{"id":"az-019","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what can happen if you get 8 or more points on your record in 12 months?","o":["You may have to attend Traffic Survival School or lose your license","Nothing, points only matter after 5 years","You must buy a new vehicle registration","You must retake only the vision test"],"h1":"Points add up, and the state steps in at 8.","h2":"If you collect 8 or more points within 12 months in Arizona, the MVD can order Traffic Survival School or suspend your license.","p":"Right. 8 points in 12 months can mean Traffic Survival School or suspension."},"es":{"q":"En Arizona, ¿qué puede pasar si acumula 8 puntos o más en su historial en 12 meses?","o":["Puede tener que ir a la Escuela de Supervivencia de Tráfico o perder la licencia","Nada, los puntos solo cuentan después de 5 años","Debe comprar un registro nuevo para el vehículo","Debe repetir solo el examen de la vista"],"h1":"Los puntos se suman y el estado actúa al llegar a 8.","h2":"Si acumula 8 puntos o más en 12 meses en Arizona, la MVD puede ordenarle la Escuela de Supervivencia de Tráfico o suspender su licencia.","p":"Correcto. 8 puntos en 12 meses pueden significar escuela de tráfico o suspensión."},"zh":{"q":"在 Arizona，如果你 12 个月内记录上有 8 分或更多，会怎么样？","o":["你可能要上交通生存学校（Traffic Survival School），或失去驾照","没事，分数只在 5 年后才算","你必须买新的车辆登记","你只需要重考视力"],"h1":"分数会累加，到 8 分州政府就会管。","h2":"在 Arizona，如果你 12 个月内累积 8 分或更多，MVD（车辆管理部门）可以要求你上交通生存学校（Traffic Survival School），或暂停你的驾照。","p":"对。12 个月内 8 分，可能要上交通生存学校或被暂停驾照。"},"vi":{"q":"Ở Arizona, điều gì có thể xảy ra nếu bạn bị 8 điểm trở lên trong hồ sơ trong 12 tháng?","o":["Bạn có thể phải học Trường An toàn Giao thông (Traffic Survival School) hoặc mất bằng lái","Không có gì, điểm chỉ tính sau 5 năm","Bạn phải mua đăng ký xe mới","Bạn chỉ phải thi lại thị lực"],"h1":"Điểm được cộng dồn, và tiểu bang can thiệp khi đến 8 điểm.","h2":"Ở Arizona, nếu bạn bị 8 điểm trở lên trong 12 tháng, MVD (Sở Xe cơ giới) có thể buộc bạn học Trường An toàn Giao thông (Traffic Survival School) hoặc treo bằng lái của bạn.","p":"Đúng. 8 điểm trong 12 tháng có thể là phải học Traffic Survival School hoặc bị treo bằng."},"tl":{"q":"Sa Arizona, ano ang puwedeng mangyari kung makakuha ka ng 8 o higit pang puntos sa record mo sa loob ng 12 buwan?","o":["Baka kailangan mong pumasok sa Traffic Survival School o mawalan ng lisensiya","Wala, may epekto lang ang puntos pagkatapos ng 5 taon","Kailangan mong bumili ng bagong vehicle registration","Kailangan mo lang ulitin ang vision test"],"h1":"Nag-iipon ang puntos, at kumikilos ang estado sa 8.","h2":"Sa Arizona, kung makaipon ka ng 8 o higit pang puntos sa loob ng 12 buwan, puwedeng utusan ka ng MVD (Motor Vehicle Division) na pumasok sa Traffic Survival School o suspendihin ang lisensiya mo.","p":"Tama. Ang 8 puntos sa 12 buwan ay puwedeng mangahulugan ng Traffic Survival School o suspensiyon."},"ar":{"q":"في Arizona، ماذا يمكن أن يحدث إذا حصلت على 8 نقاط أو أكثر في سجلّك خلال 12 شهرًا؟","o":["قد يجب عليك حضور مدرسة السلامة المرورية (Traffic Survival School) أو تفقد رخصتك","لا شيء، النقاط تهمّ فقط بعد 5 سنوات","يجب أن تشتري تسجيلًا جديدًا للمركبة","يجب أن تعيد اختبار النظر فقط"],"h1":"النقاط تتجمّع، والولاية تتدخّل عند 8.","h2":"إذا جمعت 8 نقاط أو أكثر خلال 12 شهرًا في Arizona، يمكن لـ MVD (قسم المركبات) أن يأمرك بحضور مدرسة السلامة المرورية (Traffic Survival School) أو يوقف رخصتك.","p":"صحيح. 8 نقاط في 12 شهرًا قد تعني Traffic Survival School أو إيقاف الرخصة."},"ref":{"doc":"AZ","page":49}},{"id":"az-020","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, which conviction always requires you to complete Traffic Survival School?","o":["A parking ticket","Running a red light","An expired registration","A broken taillight"],"h1":"It is a dangerous moving violation at an intersection.","h2":"In Arizona, a conviction for running a red light, or a flashing red light, always means you must complete Traffic Survival School, on top of paying the fine.","p":"Right. Running a red light means Traffic Survival School."},"es":{"q":"En Arizona, ¿qué infracción siempre le obliga a completar la Escuela de Supervivencia de Tráfico?","o":["Una multa de estacionamiento","Pasarse un semáforo en rojo","Un registro vencido","Una luz trasera rota"],"h1":"Es una infracción peligrosa en una intersección.","h2":"En Arizona, una condena por pasarse un semáforo en rojo, o una luz roja intermitente, siempre le obliga a completar la Escuela de Supervivencia de Tráfico, además de pagar la multa.","p":"Correcto. Pasarse un rojo lleva a la escuela de tráfico."},"zh":{"q":"在 Arizona，哪种定罪一定要你完成交通生存学校（Traffic Survival School）？","o":["停车罚单","闯红灯","车辆登记过期","尾灯坏了"],"h1":"它是在路口发生的危险的行车违规。","h2":"在 Arizona，闯红灯或闯闪烁红灯被定罪，除了交罚款，一定还要完成交通生存学校（Traffic Survival School）。","p":"对。闯红灯就要上交通生存学校。"},"vi":{"q":"Ở Arizona, bị kết tội vi phạm nào thì luôn phải hoàn thành Trường An toàn Giao thông (Traffic Survival School)?","o":["Phiếu phạt đậu xe","Vượt đèn đỏ","Đăng ký xe hết hạn","Đèn hậu bị hỏng"],"h1":"Đó là một vi phạm nguy hiểm khi đang chạy xe ở giao lộ.","h2":"Ở Arizona, bị kết tội vượt đèn đỏ, hoặc đèn đỏ nhấp nháy, thì luôn phải hoàn thành Trường An toàn Giao thông (Traffic Survival School), ngoài việc trả tiền phạt.","p":"Đúng. Vượt đèn đỏ thì phải học Traffic Survival School."},"tl":{"q":"Sa Arizona, aling conviction ang palaging nangangailangan na tapusin mo ang Traffic Survival School?","o":["Parking ticket","Paglampas sa red light","Expired na registration","Sirang taillight"],"h1":"Ito ay delikadong paglabag habang nagmamaneho sa intersection.","h2":"Sa Arizona, ang conviction sa paglampas sa red light, o sa kumikislap na red light, ay palaging nangangahulugan na dapat mong tapusin ang Traffic Survival School, bukod sa pagbabayad ng multa.","p":"Tama. Ang paglampas sa red light ay nangangahulugan ng Traffic Survival School."},"ar":{"q":"في Arizona، أي إدانة تتطلّب دائمًا أن تكمل مدرسة السلامة المرورية (Traffic Survival School)؟","o":["مخالفة وقوف","قطع الإشارة الحمراء","تسجيل منتهي الصلاحية","ضوء خلفي مكسور"],"h1":"هي مخالفة قيادة خطيرة عند تقاطع.","h2":"في Arizona، الإدانة بقطع الإشارة الحمراء، أو الإشارة الحمراء الوامضة، تعني دائمًا أنك يجب أن تكمل مدرسة السلامة المرورية (Traffic Survival School)، بالإضافة إلى دفع الغرامة.","p":"صحيح. قطع الإشارة الحمراء يعني Traffic Survival School."},"ref":{"doc":"AZ","page":30}},{"id":"az-021","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, at what blood alcohol level does a driver face an Extreme DUI charge?","o":["0.02 or more","0.05 or more","0.08 or more","0.15 or more"],"h1":"It is almost twice the normal adult limit.","h2":"Arizona charges Extreme DUI when a driver's blood alcohol is 0.15 or more, and the penalties are harsher than for a regular DUI.","p":"Right. Extreme DUI starts at 0.15."},"es":{"q":"En Arizona, ¿con qué nivel de alcohol en la sangre se acusa a un conductor de DUI Extremo?","o":["0.02 o más","0.05 o más","0.08 o más","0.15 o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"Arizona acusa de DUI Extremo cuando el alcohol en la sangre del conductor es 0.15 o más, y las sanciones son más duras que en un DUI normal.","p":"Correcto. El DUI Extremo empieza en 0.15."},"zh":{"q":"在 Arizona，血液酒精浓度达到多少时，司机会被控严重酒驾（Extreme DUI）？","o":["0.02 或以上","0.05 或以上","0.08 或以上","0.15 或以上"],"h1":"它差不多是成年人正常上限的两倍。","h2":"在 Arizona，司机血液酒精浓度 0.15 或以上时，会被控严重酒驾（Extreme DUI），处罚比普通酒驾更重。","p":"对。严重酒驾从 0.15 开始。"},"vi":{"q":"Ở Arizona, nồng độ cồn trong máu bao nhiêu thì tài xế bị buộc tội Lái xe say rượu nghiêm trọng (Extreme DUI)?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.15 trở lên"],"h1":"Gần gấp đôi giới hạn bình thường của người lớn.","h2":"Arizona buộc tội Lái xe say rượu nghiêm trọng (Extreme DUI) khi nồng độ cồn trong máu của tài xế là 0.15 trở lên, và hình phạt nặng hơn DUI thông thường.","p":"Đúng. Extreme DUI bắt đầu từ 0.15."},"tl":{"q":"Sa Arizona, sa anong antas ng alak sa dugo haharap ang driver sa kasong Extreme DUI?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.15 o higit pa"],"h1":"Halos doble ito ng karaniwang limit para sa adult.","h2":"Sa Arizona, kinakasuhan ng Extreme DUI ang driver kapag 0.15 o higit pa ang alak sa dugo niya, at mas mabigat ang parusa kaysa sa regular na DUI.","p":"Tama. Nagsisimula ang Extreme DUI sa 0.15."},"ar":{"q":"في Arizona، عند أي نسبة كحول في الدم يُتّهم السائق بالقيادة تحت تأثير الكحول الشديد (Extreme DUI)؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.15 أو أكثر"],"h1":"هي تقريبًا ضعف الحدّ العادي للبالغين.","h2":"Arizona توجّه تهمة القيادة تحت تأثير الكحول الشديد (Extreme DUI) عندما تكون نسبة الكحول في دم السائق 0.15 أو أكثر، والعقوبات أشدّ من DUI العادي.","p":"صحيح. Extreme DUI يبدأ من 0.15."},"ref":{"doc":"AZ","page":52}},{"id":"az-022","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"Arizona has zero tolerance for young drivers.","h2":"A driver under 21 in Arizona may not drive with any alcohol in the body, because the state has a zero tolerance law for young drivers.","p":"Right. Under 21 means no alcohol at all."},"es":{"q":"En Arizona, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"Arizona tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 años en Arizona no puede manejar con nada de alcohol en el cuerpo, porque el estado tiene una ley de tolerancia cero para conductores jóvenes.","p":"Correcto. Menor de 21 significa nada de alcohol."},"zh":{"q":"在 Arizona，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.02","完全不可以有","最多 0.05","最多 0.08"],"h1":"Arizona 对年轻司机零容忍。","h2":"在 Arizona，21 岁以下的司机体内有任何酒精都不可以开车，因为这个州对年轻司机有零容忍法律。","p":"对。21 岁以下，一点酒精都不能有。"},"vi":{"q":"Ở Arizona, tài xế dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.02","Hoàn toàn không có","Tối đa 0.05","Tối đa 0.08"],"h1":"Arizona không khoan nhượng với tài xế trẻ.","h2":"Ở Arizona, tài xế dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong cơ thể, vì tiểu bang có luật không khoan nhượng đối với tài xế trẻ.","p":"Đúng. Dưới 21 tuổi là hoàn toàn không có cồn."},"tl":{"q":"Sa Arizona, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.02","Wala talaga","Hanggang 0.05","Hanggang 0.08"],"h1":"Zero tolerance ang Arizona para sa mga batang driver.","h2":"Sa Arizona, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa katawan, dahil may zero tolerance law ang estado para sa mga batang driver.","p":"Tama. Kung wala pang 21, walang alak talaga."},"ar":{"q":"في Arizona، كم يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة من الكحول؟","o":["حتى 0.02","لا شيء أبدًا","حتى 0.05","حتى 0.08"],"h1":"Arizona لا تتسامح أبدًا مع السائقين الشباب.","h2":"في Arizona لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي جسمه أي كمية من الكحول، لأن الولاية لديها قانون عدم التسامح مع السائقين الشباب.","p":"صحيح. أقل من 21 سنة يعني لا كحول أبدًا."},"ref":{"doc":"AZ","page":47}},{"id":"az-023","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Arizona's minimum is often written as 25/50/15.","h2":"Arizona requires at least $15,000 of property damage liability for one crash, as part of the 25/50/15 minimum.","p":"Right. The property damage minimum is $15,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"El mínimo de Arizona se escribe a menudo como 25/50/15.","h2":"Arizona exige por lo menos $15,000 de cobertura por daños a la propiedad en un choque, como parte del mínimo 25/50/15.","p":"Correcto. El mínimo por daños a la propiedad es $15,000."},"zh":{"q":"在 Arizona，一次车祸中，对别人财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Arizona 的最低标准常写成 25/50/15。","h2":"Arizona 要求一次车祸至少有 $15,000 的财产损失责任保险，这是 25/50/15 最低标准的一部分。","p":"对。财产损失最低是 $15,000。"},"vi":{"q":"Ở Arizona, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Mức tối thiểu của Arizona thường được viết là 25/50/15.","h2":"Arizona yêu cầu ít nhất $15,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một vụ tai nạn, là một phần của mức tối thiểu 25/50/15.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $15,000."},"tl":{"q":"Sa Arizona, ano ang minimum na liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang aksidente?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Madalas isulat ang minimum ng Arizona bilang 25/50/15.","h2":"Hinihingi ng Arizona ang hindi bababa sa $15,000 na property damage liability para sa isang aksidente, bilang bahagi ng 25/50/15 na minimum.","p":"Tama. $15,000 ang minimum para sa pinsala sa ari-arian."},"ar":{"q":"في Arizona، ما الحدّ الأدنى لتأمين المسؤولية عن الضرر بممتلكات الآخرين في حادث واحد؟","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"الحدّ الأدنى في Arizona يُكتب غالبًا 25/50/15.","h2":"Arizona تطلب على الأقل $15,000 من تأمين المسؤولية عن ضرر الممتلكات لحادث واحد، كجزء من الحدّ الأدنى 25/50/15.","p":"صحيح. الحدّ الأدنى لضرر الممتلكات هو $15,000."},"ref":{"doc":"AZ","page":8}},{"id":"az-024","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what is the minimum liability insurance for injury to one person in a crash?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"It is the first number in 25/50/15.","h2":"Arizona requires at least $25,000 of bodily injury coverage for one person in a crash, the first number in the 25/50/15 minimum.","p":"Right. The minimum for one injured person is $25,000."},"es":{"q":"En Arizona, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Es el primer número de 25/50/15.","h2":"Arizona exige por lo menos $25,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 25/50/15.","p":"Correcto. El mínimo por una persona lesionada es $25,000."},"zh":{"q":"在 Arizona，一次车祸中，对一个人受伤的最低责任保险是多少？","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"它是 25/50/15 里的第一个数字。","h2":"Arizona 要求一次车祸中对一个人至少有 $25,000 的人身伤害保险，这是 25/50/15 最低标准里的第一个数字。","p":"对。一个人受伤的最低标准是 $25,000。"},"vi":{"q":"Ở Arizona, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Đó là con số đầu tiên trong 25/50/15.","h2":"Arizona yêu cầu ít nhất $25,000 bảo hiểm thương tích cơ thể cho một người trong tai nạn, là con số đầu tiên trong mức tối thiểu 25/50/15.","p":"Đúng. Mức tối thiểu cho một người bị thương là $25,000."},"tl":{"q":"Sa Arizona, ano ang minimum na liability insurance para sa pinsala sa isang tao sa aksidente?","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"Ito ang unang numero sa 25/50/15.","h2":"Hinihingi ng Arizona ang hindi bababa sa $25,000 na bodily injury coverage para sa isang tao sa aksidente, ang unang numero sa 25/50/15 na minimum.","p":"Tama. $25,000 ang minimum para sa isang taong nasaktan."},"ar":{"q":"في Arizona، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$25,000","$15,000","$30,000","$50,000"],"h1":"هو الرقم الأول في 25/50/15.","h2":"Arizona تطلب على الأقل $25,000 من تأمين الإصابات الجسدية لشخص واحد في حادث، وهو الرقم الأول في الحدّ الأدنى 25/50/15.","p":"صحيح. الحدّ الأدنى لشخص واحد مصاب هو $25,000."},"ref":{"doc":"AZ","page":8}},{"id":"az-025","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, a child must ride in a child restraint (car seat) until what age?","o":["Until age 2","Until age 4","Until age 5","Until age 10"],"h1":"It is about the age when many children start kindergarten.","h2":"In Arizona a child under five years old must ride in a child restraint.","p":"Right. In Arizona, children under 5 must be in a child restraint."},"es":{"q":"En Arizona, ¿hasta qué edad debe ir un niño en un sistema de retención infantil (asiento de seguridad)?","o":["Hasta los 2 años","Hasta los 4 años","Hasta los 5 años","Hasta los 10 años"],"h1":"Es más o menos la edad en que muchos niños empiezan el kínder.","h2":"En Arizona un niño menor de cinco años debe ir en un sistema de retención infantil.","p":"Correcto. En Arizona, los niños menores de 5 años deben ir en un asiento de seguridad."},"zh":{"q":"在 Arizona，儿童必须坐在儿童安全座椅（child restraint）里，直到几岁？","o":["到 2 岁","到 4 岁","到 5 岁","到 10 岁"],"h1":"大约是很多孩子开始上幼儿园的年龄。","h2":"在 Arizona，不满 5 岁的儿童必须坐在儿童安全座椅里。","p":"对。在 Arizona，不满 5 岁的儿童必须坐儿童安全座椅。"},"vi":{"q":"Ở Arizona, trẻ em phải ngồi ghế an toàn cho trẻ em (child restraint) cho đến bao nhiêu tuổi?","o":["Đến 2 tuổi","Đến 4 tuổi","Đến 5 tuổi","Đến 10 tuổi"],"h1":"Đó là khoảng tuổi nhiều trẻ bắt đầu đi mẫu giáo.","h2":"Ở Arizona, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em.","p":"Đúng. Ở Arizona, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Arizona, hanggang anong edad dapat nakaupo ang bata sa child restraint (car seat)?","o":["Hanggang edad 2","Hanggang edad 4","Hanggang edad 5","Hanggang edad 10"],"h1":"Ito ang edad kung kailan maraming bata ang nagsisimula sa kindergarten.","h2":"Sa Arizona, ang batang wala pang 5 taong gulang ay dapat nakaupo sa child restraint.","p":"Tama. Sa Arizona, ang mga batang wala pang 5 ay dapat nasa child restraint."},"ar":{"q":"في Arizona، حتى أي عمر يجب أن يجلس الطفل في مقعد أمان للأطفال (child restraint)؟","o":["حتى عمر 2","حتى عمر 4","حتى عمر 5","حتى عمر 10"],"h1":"إنه تقريبًا العمر الذي يبدأ فيه كثير من الأطفال الروضة.","h2":"في Arizona يجب أن يجلس الطفل الذي عمره أقل من 5 سنوات في مقعد أمان للأطفال.","p":"صحيح. في Arizona يجب أن يجلس الأطفال تحت عمر 5 في مقعد أمان للأطفال."},"ref":{"doc":"AZ","page":null}},{"id":"az-026","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, a 6-year-old is 4 feet 5 inches tall. How must the child ride?","o":["In a child restraint, such as a booster seat","With only an adult seat belt","On an adult's lap","In the front seat with an air bag"],"h1":"Children aged 5 to 7 who are 4 feet 9 inches or shorter still need extra help to fit the belt.","h2":"In Arizona a child aged 5 to 7 who is 4 feet 9 inches or shorter must ride in a child restraint, such as a booster seat.","p":"Right. This child still needs a booster seat or other child restraint in Arizona."},"es":{"q":"En Arizona, un niño de 6 años mide 4 pies 5 pulgadas. ¿Cómo debe viajar?","o":["En un sistema de retención infantil, como un asiento elevado (booster)","Solo con el cinturón de seguridad de adulto","Sentado en las piernas de un adulto","En el asiento delantero con bolsa de aire"],"h1":"Los niños de 5 a 7 años que miden 4 pies 9 pulgadas o menos todavía necesitan ayuda para que el cinturón les quede bien.","h2":"En Arizona un niño de 5 a 7 años que mide 4 pies 9 pulgadas o menos debe viajar en un sistema de retención infantil, como un asiento elevado.","p":"Correcto. En Arizona, este niño todavía necesita un asiento elevado u otro asiento infantil."},"zh":{"q":"在 Arizona，一个 6 岁的孩子身高 4 英尺 5 英寸。这个孩子必须怎样乘车？","o":["坐在儿童安全座椅里，例如加高座椅（booster seat）","只系成人安全带","坐在大人的腿上","坐在有安全气囊的前座"],"h1":"5 到 7 岁、身高 4 英尺 9 英寸或以下的孩子，仍然需要额外帮助才能系好安全带。","h2":"在 Arizona，5 到 7 岁、身高 4 英尺 9 英寸或以下的孩子，必须坐在儿童安全座椅里，例如加高座椅。","p":"对。在 Arizona，这个孩子仍然需要加高座椅或其他儿童安全座椅。"},"vi":{"q":"Ở Arizona, một em bé 6 tuổi cao 4 feet 5 inches. Em bé này phải ngồi xe như thế nào?","o":["Ngồi ghế an toàn cho trẻ em, ví dụ ghế nâng (booster seat)","Chỉ thắt dây an toàn của người lớn","Ngồi trên đùi người lớn","Ngồi ghế trước có túi khí"],"h1":"Trẻ từ 5 đến 7 tuổi cao 4 feet 9 inches hoặc thấp hơn vẫn cần thêm trợ giúp để dây an toàn vừa người.","h2":"Ở Arizona, trẻ từ 5 đến 7 tuổi cao 4 feet 9 inches hoặc thấp hơn phải ngồi ghế an toàn cho trẻ em, ví dụ ghế nâng.","p":"Đúng. Ở Arizona, em bé này vẫn cần ghế nâng hoặc ghế an toàn cho trẻ em khác."},"tl":{"q":"Sa Arizona, may batang 6 na taong gulang na 4 feet 5 inches ang taas. Paano dapat sumakay ang bata?","o":["Sa child restraint, gaya ng booster seat","Gamit lang ang seat belt ng adult","Sa kandungan ng adult","Sa front seat na may air bag"],"h1":"Ang mga batang 5 hanggang 7 taong gulang na 4 feet 9 inches o mas maliit ay kailangan pa ng tulong para tumama nang tama ang belt.","h2":"Sa Arizona, ang batang 5 hanggang 7 taong gulang na 4 feet 9 inches o mas maliit ay dapat nakaupo sa child restraint, gaya ng booster seat.","p":"Tama. Sa Arizona, kailangan pa ng batang ito ng booster seat o ibang child restraint."},"ar":{"q":"في Arizona، طفل عمره 6 سنوات وطوله 4 أقدام و5 بوصات. كيف يجب أن يركب الطفل؟","o":["في مقعد أمان للأطفال، مثل المقعد المعزِّز (booster seat)","بحزام أمان البالغين فقط","في حضن شخص بالغ","في المقعد الأمامي الذي فيه وسادة هوائية"],"h1":"الأطفال من عمر 5 إلى 7 الذين طولهم 4 أقدام و9 بوصات أو أقل ما زالوا يحتاجون إلى مساعدة إضافية ليناسبهم الحزام.","h2":"في Arizona يجب أن يجلس الطفل من عمر 5 إلى 7 الذي طوله 4 أقدام و9 بوصات أو أقل في مقعد أمان للأطفال، مثل المقعد المعزِّز.","p":"صحيح. في Arizona ما زال هذا الطفل يحتاج إلى مقعد معزِّز أو مقعد أمان آخر للأطفال."},"ref":{"doc":"AZ","page":null}},{"id":"az-027","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, you are arrested for DUI and refuse the alcohol test for the first time. How long will your license be suspended?","o":["30 days","90 days","6 months","12 months"],"h1":"It is a full year.","h2":"In Arizona a first refusal to take the alcohol test means your license is suspended for 12 months.","p":"Right. A first test refusal in Arizona brings a 12-month suspension."},"es":{"q":"En Arizona, usted es arrestado por manejar bajo los efectos del alcohol (DUI) y se niega a la prueba de alcohol por primera vez. ¿Por cuánto tiempo le suspenderán la licencia?","o":["30 días","90 días","6 meses","12 meses"],"h1":"Es un año completo.","h2":"En Arizona, negarse por primera vez a la prueba de alcohol significa que su licencia se suspende por 12 meses.","p":"Correcto. En Arizona, la primera negativa a la prueba trae una suspensión de 12 meses."},"zh":{"q":"在 Arizona，你因酒后驾驶（DUI）被捕，并且第一次拒绝酒精测试。你的驾照会被暂停多久？","o":["30 天","90 天","6 个月","12 个月"],"h1":"是整整一年。","h2":"在 Arizona，第一次拒绝酒精测试，你的驾照会被暂停 12 个月。","p":"对。在 Arizona，第一次拒绝测试会被暂停驾照 12 个月。"},"vi":{"q":"Ở Arizona, bạn bị bắt vì lái xe khi say (DUI) và từ chối kiểm tra nồng độ cồn lần đầu tiên. Bằng lái của bạn sẽ bị đình chỉ bao lâu?","o":["30 ngày","90 ngày","6 tháng","12 tháng"],"h1":"Đó là trọn một năm.","h2":"Ở Arizona, lần đầu từ chối kiểm tra nồng độ cồn thì bằng lái của bạn bị đình chỉ 12 tháng.","p":"Đúng. Ở Arizona, lần đầu từ chối kiểm tra sẽ bị đình chỉ bằng lái 12 tháng."},"tl":{"q":"Sa Arizona, inaresto ka dahil sa DUI at tumanggi ka sa alcohol test sa unang pagkakataon. Gaano katagal masususpinde ang lisensya mo?","o":["30 araw","90 araw","6 na buwan","12 buwan"],"h1":"Isang buong taon ito.","h2":"Sa Arizona, kapag unang beses kang tumanggi sa alcohol test, masususpinde ang lisensya mo nang 12 buwan.","p":"Tama. Sa Arizona, ang unang pagtanggi sa test ay may suspensyon na 12 buwan."},"ar":{"q":"في Arizona، تم القبض عليك بسبب القيادة تحت تأثير الكحول (DUI) ورفضت اختبار الكحول لأول مرة. كم مدة إيقاف رخصتك؟","o":["30 يومًا","90 يومًا","6 أشهر","12 شهرًا"],"h1":"إنها سنة كاملة.","h2":"في Arizona إذا رفضت اختبار الكحول لأول مرة تُوقَف رخصتك لمدة 12 شهرًا.","p":"صحيح. في Arizona يؤدي أول رفض للاختبار إلى إيقاف الرخصة لمدة 12 شهرًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-028","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, what is the lowest fine for a first offense of passing a stopped school bus with its stop sign out?","o":["$100","$250","$500","$1,000"],"h1":"It is a quarter of a thousand dollars.","h2":"In Arizona the minimum penalty for a first offense of passing a stopped school bus is $250.","p":"Right. In Arizona, a first school bus passing offense costs at least $250."},"es":{"q":"En Arizona, ¿cuál es la multa mínima por una primera infracción de rebasar un autobús escolar detenido con su señal de alto extendida?","o":["$100","$250","$500","$1,000"],"h1":"Es la cuarta parte de mil dólares.","h2":"En Arizona la multa mínima por una primera infracción de rebasar un autobús escolar detenido es de $250.","p":"Correcto. En Arizona, la primera infracción por rebasar un autobús escolar cuesta por lo menos $250."},"zh":{"q":"在 Arizona，第一次超越已停下并伸出停车标志的校车，最低罚款是多少？","o":["$100","$250","$500","$1,000"],"h1":"是一千美元的四分之一。","h2":"在 Arizona，第一次超越已停下的校车，最低处罚是 $250。","p":"对。在 Arizona，第一次超越校车至少要罚 $250。"},"vi":{"q":"Ở Arizona, mức phạt thấp nhất cho lần vi phạm đầu tiên khi vượt xe buýt trường học đang dừng và đưa biển STOP ra là bao nhiêu?","o":["$100","$250","$500","$1,000"],"h1":"Đó là một phần tư của một nghìn đô la.","h2":"Ở Arizona, mức phạt tối thiểu cho lần đầu vượt xe buýt trường học đang dừng là $250.","p":"Đúng. Ở Arizona, lần đầu vượt xe buýt trường học bị phạt ít nhất $250."},"tl":{"q":"Sa Arizona, magkano ang pinakamababang multa sa unang paglabag kapag nilampasan mo ang nakahintong school bus na nakalabas ang stop sign?","o":["$100","$250","$500","$1,000"],"h1":"Isang-kapat ito ng isang libong dolyar.","h2":"Sa Arizona, ang pinakamababang parusa sa unang paglabag ng paglampas sa nakahintong school bus ay $250.","p":"Tama. Sa Arizona, ang unang paglabag ng paglampas sa school bus ay hindi bababa sa $250."},"ar":{"q":"في Arizona، ما أقل غرامة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة ولافتة التوقف فيها ممدودة؟","o":["$100","$250","$500","$1,000"],"h1":"إنها ربع ألف دولار.","h2":"في Arizona أقل عقوبة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة هي $250.","p":"صحيح. في Arizona تكلّف المخالفة الأولى لتجاوز الحافلة المدرسية $250 على الأقل."},"ref":{"doc":"AZ","page":null}},{"id":"az-029","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is more than 10 feet.","h2":"In Arizona you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet away from a fire hydrant."},"es":{"q":"En Arizona, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es más de 10 pies.","h2":"En Arizona usted no puede estacionarse a menos de 15 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Arizona，你可以把车停在离消防栓多近的地方？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"它比 10 英尺多。","h2":"在 Arizona，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Arizona, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này hơn 10 feet.","h2":"Ở Arizona, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Arizona, gaano kalapit sa fire hydrant puwede kang mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Higit ito sa 10 feet.","h2":"Sa Arizona, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Arizona، إلى أي مدى يمكنك أن توقف سيارتك قرب حنفية إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"المسافة أكثر من 10 أقدام.","h2":"في Arizona لا يجوز لك أن توقف سيارتك على بُعد أقل من 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من حنفية إطفاء الحريق."},"ref":{"doc":"AZ","page":null}},{"id":"az-030","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, a police car is using its siren and red or blue lights for an emergency. How far behind it must you stay?","o":["At least 300 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"Leave a long gap, because the police car may stop or turn suddenly.","h2":"In Arizona you must stay at least 300 feet behind a police car that is using its siren and lights for an emergency.","p":"Right. Stay at least 300 feet behind a police car in an emergency."},"es":{"q":"En Arizona, una patrulla de policía usa la sirena y luces rojas o azules por una emergencia. ¿A qué distancia detrás de ella debe quedarse?","o":["Por lo menos a 300 pies","Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a 1,000 pies"],"h1":"Deje un espacio largo, porque la patrulla puede detenerse o dar vuelta de repente.","h2":"En Arizona usted debe quedarse por lo menos a 300 pies detrás de una patrulla que usa la sirena y las luces por una emergencia.","p":"Correcto. Quédese por lo menos a 300 pies detrás de una patrulla en una emergencia."},"zh":{"q":"在 Arizona，一辆警车正在为紧急情况鸣警笛并亮着红灯或蓝灯。你必须在它后面保持多远？","o":["至少 300 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"要留出很长的距离，因为警车可能会突然停下或转弯。","h2":"在 Arizona，当警车为紧急情况鸣警笛并亮灯时，你必须在它后面至少保持 300 英尺。","p":"对。紧急情况下，要在警车后面至少保持 300 英尺。"},"vi":{"q":"Ở Arizona, một xe cảnh sát đang hú còi và bật đèn đỏ hoặc xanh vì có việc khẩn cấp. Bạn phải đi cách phía sau nó bao xa?","o":["Ít nhất 300 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Hãy để một khoảng cách dài, vì xe cảnh sát có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Arizona, bạn phải đi cách phía sau xe cảnh sát ít nhất 300 feet khi xe đó đang hú còi và bật đèn vì việc khẩn cấp.","p":"Đúng. Hãy đi cách phía sau xe cảnh sát ít nhất 300 feet khi có việc khẩn cấp."},"tl":{"q":"Sa Arizona, may kotse ng pulis na gumagamit ng siren at pula o asul na ilaw dahil sa emergency. Gaano kalayo ka dapat sa likod nito?","o":["Hindi bababa sa 300 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 1,000 feet"],"h1":"Mag-iwan ng mahabang pagitan, dahil puwedeng biglang huminto o lumiko ang kotse ng pulis.","h2":"Sa Arizona, dapat kang manatili nang hindi bababa sa 300 feet sa likod ng kotse ng pulis na gumagamit ng siren at ilaw dahil sa emergency.","p":"Tama. Manatili nang hindi bababa sa 300 feet sa likod ng kotse ng pulis kapag may emergency."},"ar":{"q":"في Arizona، سيارة شرطة تستعمل صفّارتها وأضواءها الحمراء أو الزرقاء بسبب حالة طارئة. ما المسافة التي يجب أن تبقى فيها خلفها؟","o":["300 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"اترك مسافة طويلة، لأن سيارة الشرطة قد تتوقف أو تنعطف فجأة.","h2":"في Arizona يجب أن تبقى على بُعد 300 قدم على الأقل خلف سيارة الشرطة التي تستعمل صفّارتها وأضواءها بسبب حالة طارئة.","p":"صحيح. ابقَ على بُعد 300 قدم على الأقل خلف سيارة الشرطة في الحالة الطارئة."},"ref":{"doc":"AZ","page":null}},{"id":"az-031","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, a fire truck is going to a fire alarm. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 300 feet","No closer than 500 feet"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Arizona you may not follow a fire truck going to an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on its way to an alarm."},"es":{"q":"En Arizona, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No más cerca de 50 pies","No más cerca de 100 pies","No más cerca de 300 pies","No más cerca de 500 pies"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Arizona usted no puede seguir a un camión de bomberos que va hacia una alarma a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos que va a una alarma."},"zh":{"q":"在 Arizona，一辆消防车正赶去处理火警。你跟在它后面最近可以多近？","o":["不能少于 50 英尺","不能少于 100 英尺","不能少于 300 英尺","不能少于 500 英尺"],"h1":"要给它留出足够的空间，因为它可能会突然停下或转弯。","h2":"在 Arizona，跟在赶去火警的消防车后面时，距离不能少于 500 英尺。","p":"对。消防车赶去火警时，要在它后面至少保持 500 英尺。"},"vi":{"q":"Ở Arizona, một xe cứu hỏa đang chạy đến nơi có báo động cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 300 feet","Không gần hơn 500 feet"],"h1":"Hãy chừa cho nó nhiều khoảng trống, vì nó có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Arizona, khi chạy theo sau xe cứu hỏa đang đến nơi báo động cháy, bạn không được đi gần hơn 500 feet.","p":"Đúng. Hãy đi cách phía sau xe cứu hỏa đang đến nơi báo động cháy ít nhất 500 feet."},"tl":{"q":"Sa Arizona, may fire truck na papunta sa fire alarm. Gaano kalapit ka puwedeng sumunod dito?","o":["Hindi lalapit sa 50 feet","Hindi lalapit sa 100 feet","Hindi lalapit sa 300 feet","Hindi lalapit sa 500 feet"],"h1":"Bigyan ito ng maraming espasyo, dahil puwede itong biglang huminto o lumiko.","h2":"Sa Arizona, hindi ka puwedeng sumunod sa fire truck na papunta sa alarm nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng fire truck na papunta sa alarm."},"ar":{"q":"في Arizona، سيارة إطفاء متجهة إلى إنذار حريق. إلى أي مدى يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","ليس أقرب من 300 قدم","ليس أقرب من 500 قدم"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Arizona لا يجوز لك أن تسير خلف سيارة إطفاء متجهة إلى إنذار حريق على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بُعد 500 قدم على الأقل خلف سيارة الإطفاء المتجهة إلى إنذار حريق."},"ref":{"doc":"AZ","page":null}},{"id":"az-032","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["When it is within 100 feet","When it is within 500 feet","When it is within 1,500 feet","Only if the other driver flashes their lights"],"h1":"Switch early, so the other driver is not blinded.","h2":"In Arizona you must switch to low beams when an oncoming vehicle is within 500 feet.","p":"Right. Use low beams when an oncoming car is within 500 feet."},"es":{"q":"En Arizona, usted lleva las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando esté a menos de 100 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,500 pies","Solo si el otro conductor le hace cambio de luces"],"h1":"Cambie temprano, para no deslumbrar al otro conductor.","h2":"En Arizona usted debe cambiar a luces bajas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Use las luces bajas cuando un carro de frente esté a menos de 500 pies."},"zh":{"q":"在 Arizona，你晚上开着远光灯。前面有一辆车朝你开过来。你必须在什么时候换成近光灯？","o":["当它在 100 英尺以内时","当它在 500 英尺以内时","当它在 1,500 英尺以内时","只有对方司机闪灯时"],"h1":"要早点换，这样对方司机就不会被晃得看不见。","h2":"在 Arizona，当对面来车在 500 英尺以内时，你必须换成近光灯。","p":"对。对面来车在 500 英尺以内时，要用近光灯。"},"vi":{"q":"Ở Arizona, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Khi xe đó cách bạn trong vòng 100 feet","Khi xe đó cách bạn trong vòng 500 feet","Khi xe đó cách bạn trong vòng 1,500 feet","Chỉ khi tài xế kia nháy đèn"],"h1":"Hãy chuyển đèn sớm, để tài xế kia không bị chói mắt.","h2":"Ở Arizona, bạn phải chuyển sang đèn cốt khi xe chạy ngược chiều cách bạn trong vòng 500 feet.","p":"Đúng. Hãy dùng đèn cốt khi xe chạy ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Arizona, gumagamit ka ng high beams sa gabi. May kotseng paparating papunta sa iyo. Kailan ka dapat lumipat sa low beams?","o":["Kapag nasa loob na ito ng 100 feet","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng 1,500 feet","Kapag nag-flash lang ng ilaw ang ibang driver"],"h1":"Lumipat nang maaga, para hindi masilaw ang ibang driver.","h2":"Sa Arizona, dapat kang lumipat sa low beams kapag ang paparating na sasakyan ay nasa loob ng 500 feet.","p":"Tama. Gumamit ng low beams kapag ang paparating na kotse ay nasa loob ng 500 feet."},"ar":{"q":"في Arizona، أنت تستعمل الأضواء العالية (الضوء البعيد) في الليل. هناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة (الضوء القريب)؟","o":["عندما تصبح على بُعد 100 قدم أو أقل","عندما تصبح على بُعد 500 قدم أو أقل","عندما تصبح على بُعد 1,500 قدم أو أقل","فقط إذا أومض السائق الآخر بأضوائه"],"h1":"انتقل مبكرًا، حتى لا تُبهر عينَي السائق الآخر.","h2":"في Arizona يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على بُعد 500 قدم أو أقل.","p":"صحيح. استعمل الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل."},"ref":{"doc":"AZ","page":null}},{"id":"az-033","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, you are on a one-way street at a red light. You want to turn left onto another one-way street that goes left. What may you do?","o":["Never turn left on red","Turn left without stopping","Stop first, then turn left when it is safe","Wait for a police officer to wave you on"],"h1":"It is like a right turn on red, but between two one-way streets.","h2":"In Arizona you may turn left on red from a one-way street onto a one-way street going left, after a full stop and yielding, unless a sign forbids it.","p":"Right. Stop, yield, then you may turn left onto the one-way street."},"es":{"q":"En Arizona, usted está en una calle de un solo sentido con la luz roja. Quiere dar vuelta a la izquierda hacia otra calle de un solo sentido que va a la izquierda. ¿Qué puede hacer?","o":["Nunca dar vuelta a la izquierda con luz roja","Dar vuelta a la izquierda sin detenerse","Detenerse primero y luego dar vuelta a la izquierda cuando sea seguro","Esperar a que un policía le haga una señal"],"h1":"Es como dar vuelta a la derecha con luz roja, pero entre dos calles de un solo sentido.","h2":"En Arizona usted puede dar vuelta a la izquierda con luz roja de una calle de un solo sentido a otra de un solo sentido que va a la izquierda, después de detenerse por completo y ceder el paso, a menos que un letrero lo prohíba.","p":"Correcto. Deténgase, ceda el paso y luego puede dar vuelta a la izquierda hacia la calle de un solo sentido."},"zh":{"q":"在 Arizona，你在一条单行道上，遇到红灯。你想左转进入另一条向左行驶的单行道。你可以怎么做？","o":["红灯时绝对不能左转","不停车直接左转","先停车，安全时再左转","等警察挥手让你走"],"h1":"这就像红灯右转，只是在两条单行道之间。","h2":"在 Arizona，你可以在红灯时从单行道左转进入向左行驶的单行道，但必须先完全停车并让行，除非有标志禁止。","p":"对。先停车、让行，然后可以左转进入那条单行道。"},"vi":{"q":"Ở Arizona, bạn đang ở trên đường một chiều và gặp đèn đỏ. Bạn muốn rẽ trái vào một đường một chiều khác chạy về bên trái. Bạn được làm gì?","o":["Không bao giờ rẽ trái khi đèn đỏ","Rẽ trái mà không dừng lại","Dừng lại trước, rồi rẽ trái khi an toàn","Chờ cảnh sát vẫy tay cho bạn đi"],"h1":"Giống như rẽ phải khi đèn đỏ, nhưng giữa hai đường một chiều.","h2":"Ở Arizona, bạn được rẽ trái khi đèn đỏ từ đường một chiều vào đường một chiều chạy về bên trái, sau khi dừng hẳn và nhường đường, trừ khi có biển báo cấm.","p":"Đúng. Dừng lại, nhường đường, rồi bạn được rẽ trái vào đường một chiều."},"tl":{"q":"Sa Arizona, nasa one-way street ka at red light. Gusto mong kumaliwa papunta sa isa pang one-way street na papunta sa kaliwa. Ano ang puwede mong gawin?","o":["Huwag kailanman kumaliwa kapag red light","Kumaliwa nang hindi humihinto","Huminto muna, saka kumaliwa kapag ligtas na","Hintayin ang pulis na kumaway sa iyo"],"h1":"Parang pagkanan kapag red light, pero sa pagitan ng dalawang one-way street.","h2":"Sa Arizona, puwede kang kumaliwa kapag red light mula sa one-way street papunta sa one-way street na pakaliwa, pagkatapos huminto nang buo at magbigay-daan, maliban kung may karatulang nagbabawal.","p":"Tama. Huminto, magbigay-daan, saka puwede kang kumaliwa papunta sa one-way street."},"ar":{"q":"في Arizona، أنت في شارع ذي اتجاه واحد والإشارة حمراء. تريد أن تنعطف يسارًا إلى شارع آخر ذي اتجاه واحد يسير نحو اليسار. ماذا يمكنك أن تفعل؟","o":["لا تنعطف يسارًا أبدًا عند الإشارة الحمراء","انعطف يسارًا دون أن تتوقف","توقّف أولًا، ثم انعطف يسارًا عندما يكون ذلك آمنًا","انتظر حتى يلوّح لك شرطي بالمرور"],"h1":"الأمر مثل الانعطاف يمينًا عند الإشارة الحمراء، لكن بين شارعين ذوَي اتجاه واحد.","h2":"في Arizona يمكنك أن تنعطف يسارًا عند الإشارة الحمراء من شارع ذي اتجاه واحد إلى شارع ذي اتجاه واحد يسير نحو اليسار، بعد أن تتوقف تمامًا وتعطي حق المرور، إلا إذا منعت ذلك لافتة.","p":"صحيح. توقّف، وأعطِ حق المرور، ثم يمكنك أن تنعطف يسارًا إلى الشارع ذي الاتجاه الواحد."},"ref":{"doc":"AZ","page":null}},{"id":"az-034","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a teen in the first six months of a graduated license breaks one of its limits for the first time. What happens to the limits?","o":["They last 30 days longer","They end right away","They become permanent","Nothing changes"],"h1":"The state gives the teen more time under the limits.","h2":"In Arizona a first violation of the graduated license limits adds 30 more days to those limits.","p":"Right. A first violation extends the limits by 30 days."},"es":{"q":"En Arizona, un adolescente en los primeros seis meses de su licencia graduada no cumple uno de sus límites por primera vez. ¿Qué pasa con los límites?","o":["Duran 30 días más","Terminan de inmediato","Se vuelven permanentes","No cambia nada"],"h1":"El estado le da al adolescente más tiempo con los límites.","h2":"En Arizona una primera infracción de los límites de la licencia graduada agrega 30 días más a esos límites.","p":"Correcto. Una primera infracción alarga los límites por 30 días."},"zh":{"q":"在 Arizona，一个青少年拿到分级驾照的头六个月里，第一次违反了驾照的限制。这些限制会怎样？","o":["多延长 30 天","马上结束","变成永久的","什么都不变"],"h1":"州政府会让这个青少年在限制下再多待一段时间。","h2":"在 Arizona，第一次违反分级驾照的限制，这些限制会再延长 30 天。","p":"对。第一次违规，限制会延长 30 天。"},"vi":{"q":"Ở Arizona, một thiếu niên trong sáu tháng đầu có bằng lái theo cấp độ vi phạm một trong các giới hạn lần đầu tiên. Các giới hạn đó sẽ ra sao?","o":["Kéo dài thêm 30 ngày","Chấm dứt ngay","Trở thành vĩnh viễn","Không có gì thay đổi"],"h1":"Tiểu bang cho thiếu niên đó thêm thời gian chịu các giới hạn.","h2":"Ở Arizona, vi phạm lần đầu các giới hạn của bằng lái theo cấp độ sẽ cộng thêm 30 ngày vào các giới hạn đó.","p":"Đúng. Vi phạm lần đầu thì các giới hạn kéo dài thêm 30 ngày."},"tl":{"q":"Sa Arizona, isang teenager na nasa unang anim na buwan ng graduated license ang unang beses na lumabag sa isa sa mga limitasyon nito. Ano ang mangyayari sa mga limitasyon?","o":["Tatagal pa nang 30 araw","Matatapos agad","Magiging permanente","Walang magbabago"],"h1":"Bibigyan ng estado ang teenager ng mas mahabang panahon sa ilalim ng mga limitasyon.","h2":"Sa Arizona, ang unang paglabag sa mga limitasyon ng graduated license ay nagdadagdag ng 30 pang araw sa mga limitasyong iyon.","p":"Tama. Ang unang paglabag ay nagpapahaba sa mga limitasyon nang 30 araw."},"ar":{"q":"في Arizona، شاب في الأشهر الستة الأولى من رخصة القيادة المتدرّجة يخالف أحد قيودها لأول مرة. ماذا يحدث للقيود؟","o":["تستمر 30 يومًا أطول","تنتهي فورًا","تصبح دائمة","لا يتغيّر شيء"],"h1":"الولاية تُبقي الشاب تحت القيود وقتًا أطول.","h2":"في Arizona المخالفة الأولى لقيود رخصة القيادة المتدرّجة تضيف 30 يومًا أخرى إلى تلك القيود.","p":"صحيح. المخالفة الأولى تمدّد القيود 30 يومًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-035","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are in a crash and someone is hurt. When must you tell the police?","o":["Within 10 days, in writing","Right away, by the fastest way you can","Only if the other driver asks you to","Only if a car must be towed"],"h1":"An injured person needs help quickly.","h2":"In Arizona, after a crash where someone is hurt or killed, you must tell the police right away by the fastest means you have.","p":"Right. Report an injury crash to the police right away."},"es":{"q":"En Arizona, usted tiene un choque y alguien resulta herido. ¿Cuándo debe avisar a la policía?","o":["Dentro de 10 días, por escrito","De inmediato, por el medio más rápido que pueda","Solo si el otro conductor se lo pide","Solo si hay que remolcar un carro"],"h1":"Una persona herida necesita ayuda rápido.","h2":"En Arizona, después de un choque donde alguien resulta herido o muerto, usted debe avisar a la policía de inmediato por el medio más rápido que tenga.","p":"Correcto. Avise a la policía de inmediato si hay heridos."},"zh":{"q":"在 Arizona，你出了车祸，有人受伤。你必须在什么时候通知警察？","o":["10 天内，用书面方式","马上，用你能用的最快方式","只有在对方司机要求时","只有在车需要拖走时"],"h1":"受伤的人需要尽快得到帮助。","h2":"在 Arizona，车祸中有人受伤或死亡后，你必须马上用你最快的方式通知警察。","p":"对。有人受伤的车祸要马上报警。"},"vi":{"q":"Ở Arizona, bạn bị tai nạn và có người bị thương. Khi nào bạn phải báo cho cảnh sát?","o":["Trong vòng 10 ngày, bằng văn bản","Ngay lập tức, bằng cách nhanh nhất bạn có thể","Chỉ khi tài xế kia yêu cầu","Chỉ khi phải kéo xe đi"],"h1":"Người bị thương cần được giúp đỡ nhanh chóng.","h2":"Ở Arizona, sau tai nạn có người bị thương hoặc tử vong, bạn phải báo cho cảnh sát ngay lập tức bằng cách nhanh nhất bạn có.","p":"Đúng. Hãy báo ngay cho cảnh sát khi tai nạn có người bị thương."},"tl":{"q":"Sa Arizona, naaksidente ka at may nasaktan. Kailan mo dapat sabihan ang pulis?","o":["Sa loob ng 10 araw, nang nakasulat","Agad-agad, sa pinakamabilis na paraang kaya mo","Kapag hiniling lang ng ibang driver","Kapag kailangan lang i-tow ang kotse"],"h1":"Kailangan agad ng tulong ng taong nasaktan.","h2":"Sa Arizona, pagkatapos ng aksidenteng may nasaktan o namatay, dapat mong sabihan agad ang pulis sa pinakamabilis na paraang mayroon ka.","p":"Tama. I-report agad sa pulis ang aksidenteng may nasaktan."},"ar":{"q":"في Arizona، وقع لك حادث وأُصيب شخص. متى يجب أن تُبلغ الشرطة؟","o":["خلال 10 أيام، كتابةً","فورًا، بأسرع طريقة ممكنة لك","فقط إذا طلب منك السائق الآخر ذلك","فقط إذا كان يجب سحب سيارة"],"h1":"الشخص المصاب يحتاج إلى المساعدة بسرعة.","h2":"في Arizona، بعد حادث أُصيب فيه شخص أو مات، يجب أن تُبلغ الشرطة فورًا بأسرع وسيلة لديك.","p":"صحيح. أبلغ الشرطة فورًا عن حادث فيه إصابة."},"ref":{"doc":"AZ","page":null}},{"id":"az-036","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, a driver leaves the scene of a crash where someone was hurt, without stopping. What kind of crime is this?","o":["A parking violation","A civil ticket with a small fine","It is not a crime if the driver was not at fault","A felony"],"h1":"It is more serious than a misdemeanor.","h2":"In Arizona, leaving the scene of a crash where someone was hurt is a felony, and the license is revoked.","p":"Right. Leaving an injury crash is a felony."},"es":{"q":"En Arizona, un conductor se va del lugar de un choque donde alguien resultó herido, sin detenerse. ¿Qué tipo de delito es?","o":["Una infracción de estacionamiento","Una multa civil pequeña","No es delito si el conductor no tuvo la culpa","Un delito grave (felonía)"],"h1":"Es más serio que un delito menor.","h2":"En Arizona, irse del lugar de un choque donde alguien resultó herido es un delito grave (felonía), y se revoca la licencia.","p":"Correcto. Irse de un choque con heridos es un delito grave."},"zh":{"q":"在 Arizona，一个司机在有人受伤的车祸后没有停车就离开了现场。这是什么样的罪？","o":["停车违规","只罚一点钱的民事罚单","如果司机没有过错，就不是犯罪","重罪"],"h1":"它比轻罪更严重。","h2":"在 Arizona，离开有人受伤的车祸现场是重罪，驾照会被吊销。","p":"对。离开有人受伤的车祸现场是重罪。"},"vi":{"q":"Ở Arizona, một tài xế bỏ đi khỏi hiện trường tai nạn có người bị thương mà không dừng lại. Đây là loại tội gì?","o":["Vi phạm đậu xe","Vé phạt dân sự với tiền phạt nhỏ","Không phải tội nếu tài xế không có lỗi","Trọng tội"],"h1":"Nó nghiêm trọng hơn tội nhẹ.","h2":"Ở Arizona, bỏ đi khỏi hiện trường tai nạn có người bị thương là trọng tội, và bằng lái bị thu hồi.","p":"Đúng. Bỏ đi khỏi tai nạn có người bị thương là trọng tội."},"tl":{"q":"Sa Arizona, umalis ang isang driver sa lugar ng aksidenteng may nasaktan, nang hindi humihinto. Anong klaseng krimen ito?","o":["Paglabag sa paradahan","Civil ticket na may maliit na multa","Hindi ito krimen kung hindi kasalanan ng driver","Felony"],"h1":"Mas mabigat ito kaysa sa misdemeanor.","h2":"Sa Arizona, ang pag-alis sa lugar ng aksidenteng may nasaktan ay felony, at binabawi ang lisensiya.","p":"Tama. Felony ang pag-alis sa aksidenteng may nasaktan."},"ar":{"q":"في Arizona، سائق يغادر مكان حادث أُصيب فيه شخص، دون أن يتوقف. ما نوع هذه الجريمة؟","o":["مخالفة وقوف","مخالفة مدنية بغرامة صغيرة","ليست جريمة إذا لم يكن السائق مخطئًا","جناية"],"h1":"إنها أخطر من الجنحة.","h2":"في Arizona، مغادرة مكان حادث أُصيب فيه شخص جناية، وتُسحب الرخصة.","p":"صحيح. مغادرة حادث فيه إصابة جناية."},"ref":{"doc":"AZ","page":null}},{"id":"az-037","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, after a crash with another driver, what must you give that driver?","o":["Only your phone number","Your insurance company's address only","Your name, address and vehicle registration number, and your license if asked","Nothing, until the police arrive"],"h1":"The other driver needs to know who you are and which car you were driving.","h2":"In Arizona, after a crash you must give your name, address and vehicle registration number, and show your driver license if asked.","p":"Right. Share your name, address and registration, and show your license if asked."},"es":{"q":"En Arizona, después de un choque con otro conductor, ¿qué debe darle a ese conductor?","o":["Solo su número de teléfono","Solo la dirección de su compañía de seguros","Su nombre, dirección y número de registro del vehículo, y su licencia si se la piden","Nada, hasta que llegue la policía"],"h1":"El otro conductor necesita saber quién es usted y qué carro manejaba.","h2":"En Arizona, después de un choque usted debe dar su nombre, dirección y número de registro del vehículo, y mostrar su licencia de manejo si se la piden.","p":"Correcto. Dé su nombre, dirección y registro, y muestre su licencia si se la piden."},"zh":{"q":"在 Arizona，和另一个司机发生车祸后，你必须给那个司机什么？","o":["只给你的电话号码","只给你保险公司的地址","你的姓名、地址和车辆登记号码，对方要求时还要出示驾照","什么都不给，等警察来再说"],"h1":"对方司机需要知道你是谁，以及你开的是哪辆车。","h2":"在 Arizona，车祸后你必须给出你的姓名、地址和车辆登记号码，对方要求时还要出示你的驾照。","p":"对。告诉对方你的姓名、地址和车辆登记号码，对方要求时出示驾照。"},"vi":{"q":"Ở Arizona, sau tai nạn với một tài xế khác, bạn phải đưa cho tài xế đó những gì?","o":["Chỉ số điện thoại của bạn","Chỉ địa chỉ công ty bảo hiểm của bạn","Tên, địa chỉ và số đăng ký xe của bạn, và bằng lái nếu được yêu cầu","Không gì cả, cho đến khi cảnh sát đến"],"h1":"Tài xế kia cần biết bạn là ai và bạn đã lái xe nào.","h2":"Ở Arizona, sau tai nạn bạn phải đưa tên, địa chỉ và số đăng ký xe của bạn, và cho xem bằng lái nếu được yêu cầu.","p":"Đúng. Đưa tên, địa chỉ và số đăng ký xe, và cho xem bằng lái nếu được yêu cầu."},"tl":{"q":"Sa Arizona, pagkatapos ng aksidente kasama ang ibang driver, ano ang dapat mong ibigay sa driver na iyon?","o":["Ang phone number mo lang","Ang address lang ng insurance company mo","Ang pangalan, address at vehicle registration number mo, at ang lisensiya mo kung hihingin","Wala, hanggang dumating ang pulis"],"h1":"Kailangang malaman ng ibang driver kung sino ka at kung aling kotse ang minamaneho mo.","h2":"Sa Arizona, pagkatapos ng aksidente dapat mong ibigay ang pangalan, address at vehicle registration number mo, at ipakita ang driver license mo kung hihingin.","p":"Tama. Ibigay ang pangalan, address at registration mo, at ipakita ang lisensiya mo kung hihingin."},"ar":{"q":"في Arizona، بعد حادث مع سائق آخر، ماذا يجب أن تعطي ذلك السائق؟","o":["رقم هاتفك فقط","عنوان شركة التأمين فقط","اسمك وعنوانك ورقم تسجيل السيارة، ورخصتك إذا طُلبت","لا شيء، حتى تصل الشرطة"],"h1":"السائق الآخر يحتاج أن يعرف من أنت وأيّ سيارة كنت تقود.","h2":"في Arizona، بعد حادث يجب أن تعطي اسمك وعنوانك ورقم تسجيل السيارة، وأن تُظهر رخصة القيادة إذا طُلبت.","p":"صحيح. أعطِ اسمك وعنوانك ورقم التسجيل، وأظهر رخصتك إذا طُلبت."},"ref":{"doc":"AZ","page":null}},{"id":"az-038","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a driver is convicted of aggressive driving. Which class must the driver complete?","o":["Traffic Survival School","A motorcycle safety course","A first aid class","No class is required"],"h1":"It is the same school required after running a red light.","h2":"In Arizona a driver convicted of aggressive driving must complete Traffic Survival School.","p":"Right. Aggressive driving means Traffic Survival School."},"es":{"q":"En Arizona, un conductor es declarado culpable de manejo agresivo. ¿Qué clase debe completar?","o":["La escuela de supervivencia en el tráfico (Traffic Survival School)","Un curso de seguridad en motocicleta","Una clase de primeros auxilios","No se requiere ninguna clase"],"h1":"Es la misma escuela que se requiere después de pasarse una luz roja.","h2":"En Arizona un conductor declarado culpable de manejo agresivo debe completar la escuela de supervivencia en el tráfico (Traffic Survival School).","p":"Correcto. El manejo agresivo lleva a la Traffic Survival School."},"zh":{"q":"在 Arizona，一个司机因为攻击性驾驶被定罪。这个司机必须完成什么课程？","o":["交通生存学校（Traffic Survival School）","摩托车安全课程","急救课","不需要上任何课"],"h1":"闯红灯后要求上的也是这所学校。","h2":"在 Arizona，因攻击性驾驶被定罪的司机必须完成交通生存学校（Traffic Survival School）。","p":"对。攻击性驾驶就要上交通生存学校。"},"vi":{"q":"Ở Arizona, một tài xế bị kết tội lái xe hung hăng. Tài xế đó phải hoàn thành lớp học nào?","o":["Trường An toàn Giao thông (Traffic Survival School)","Khóa học an toàn xe máy","Lớp sơ cứu","Không cần học lớp nào"],"h1":"Đó là cùng trường phải học sau khi vượt đèn đỏ.","h2":"Ở Arizona, tài xế bị kết tội lái xe hung hăng phải hoàn thành Trường An toàn Giao thông (Traffic Survival School).","p":"Đúng. Lái xe hung hăng thì phải học Trường An toàn Giao thông."},"tl":{"q":"Sa Arizona, na-convict ang isang driver ng aggressive driving. Anong klase ang dapat niyang tapusin?","o":["Traffic Survival School","Isang motorcycle safety course","Isang first aid class","Walang kailangang klase"],"h1":"Ito rin ang paaralang hinihingi pagkatapos lumampas sa red light.","h2":"Sa Arizona, ang driver na na-convict ng aggressive driving ay dapat tapusin ang Traffic Survival School.","p":"Tama. Ang aggressive driving ay nangangahulugan ng Traffic Survival School."},"ar":{"q":"في Arizona، أُدين سائق بالقيادة العدوانية. أيّ دورة يجب أن يكملها السائق؟","o":["مدرسة السلامة المرورية (Traffic Survival School)","دورة سلامة الدراجات النارية","دورة إسعافات أولية","لا تلزم أي دورة"],"h1":"إنها المدرسة نفسها المطلوبة بعد قطع الإشارة الحمراء.","h2":"في Arizona يجب على السائق الذي أُدين بالقيادة العدوانية أن يكمل مدرسة السلامة المرورية (Traffic Survival School).","p":"صحيح. القيادة العدوانية تعني مدرسة السلامة المرورية."},"ref":{"doc":"AZ","page":null}},{"id":"az-039","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a driver is convicted of reckless driving for the first time. For up to how long may the judge suspend the license?","o":["Up to 7 days","Up to 90 days","Up to 5 years","The judge may not suspend it"],"h1":"It is about three months.","h2":"In Arizona a judge may suspend a driver's license for up to 90 days for a first reckless driving conviction.","p":"Right. A first reckless driving conviction can bring a suspension of up to 90 days."},"es":{"q":"En Arizona, un conductor es declarado culpable de manejo imprudente por primera vez. ¿Por cuánto tiempo como máximo puede el juez suspender la licencia?","o":["Hasta 7 días","Hasta 90 días","Hasta 5 años","El juez no puede suspenderla"],"h1":"Son unos tres meses.","h2":"En Arizona un juez puede suspender la licencia hasta por 90 días por una primera condena de manejo imprudente.","p":"Correcto. Una primera condena de manejo imprudente puede traer una suspensión de hasta 90 días."},"zh":{"q":"在 Arizona，一个司机第一次因鲁莽驾驶被定罪。法官最多可以暂停驾照多长时间？","o":["最多 7 天","最多 90 天","最多 5 年","法官不能暂停驾照"],"h1":"大约三个月。","h2":"在 Arizona，第一次因鲁莽驾驶被定罪，法官最多可以暂停司机的驾照 90 天。","p":"对。第一次鲁莽驾驶定罪，驾照最多可被暂停 90 天。"},"vi":{"q":"Ở Arizona, một tài xế bị kết tội lái xe liều lĩnh lần đầu tiên. Thẩm phán có thể treo bằng lái tối đa bao lâu?","o":["Tối đa 7 ngày","Tối đa 90 ngày","Tối đa 5 năm","Thẩm phán không được treo bằng lái"],"h1":"Khoảng ba tháng.","h2":"Ở Arizona, thẩm phán có thể treo bằng lái của tài xế tối đa 90 ngày khi bị kết tội lái xe liều lĩnh lần đầu.","p":"Đúng. Lần đầu bị kết tội lái xe liều lĩnh có thể bị treo bằng lái tối đa 90 ngày."},"tl":{"q":"Sa Arizona, unang beses na na-convict ng reckless driving ang isang driver. Hanggang gaano katagal puwedeng suspendihin ng judge ang lisensiya?","o":["Hanggang 7 araw","Hanggang 90 araw","Hanggang 5 taon","Hindi puwedeng suspendihin ito ng judge"],"h1":"Mga tatlong buwan ito.","h2":"Sa Arizona, puwedeng suspendihin ng judge ang lisensiya ng driver nang hanggang 90 araw para sa unang conviction ng reckless driving.","p":"Tama. Ang unang conviction ng reckless driving ay puwedeng magdala ng suspension nang hanggang 90 araw."},"ar":{"q":"في Arizona، أُدين سائق بالقيادة المتهوّرة لأول مرة. ما أطول مدة يمكن للقاضي أن يوقف فيها الرخصة؟","o":["حتى 7 أيام","حتى 90 يومًا","حتى 5 سنوات","لا يمكن للقاضي أن يوقفها"],"h1":"إنها نحو ثلاثة أشهر.","h2":"في Arizona يمكن للقاضي أن يوقف رخصة السائق حتى 90 يومًا عند أول إدانة بالقيادة المتهوّرة.","p":"صحيح. أول إدانة بالقيادة المتهوّرة قد تجلب إيقافًا حتى 90 يومًا."},"ref":{"doc":"AZ","page":null}},{"id":"az-040","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, when does speeding become the crime of excessive speed, not just a civil ticket?","o":["At 1 mph over the posted limit","At 5 mph over the posted limit","At more than 20 mph over the posted limit","Only at more than 50 mph over the posted limit"],"h1":"It is a big number, but not as big as 50.","h2":"In Arizona, driving more than 20 mph over the posted speed limit is the crime of excessive speed.","p":"Right. More than 20 mph over the limit is a criminal offense."},"es":{"q":"En Arizona, ¿cuándo se convierte el exceso de velocidad en el delito de velocidad excesiva y no solo en una multa civil?","o":["A 1 mph sobre el límite indicado","A 5 mph sobre el límite indicado","A más de 20 mph sobre el límite indicado","Solo a más de 50 mph sobre el límite indicado"],"h1":"Es un número grande, pero no tanto como 50.","h2":"En Arizona, manejar a más de 20 mph sobre el límite de velocidad indicado es el delito de velocidad excesiva.","p":"Correcto. Más de 20 mph sobre el límite es un delito."},"zh":{"q":"在 Arizona，超速到什么程度就成了“过度超速”罪，而不只是民事罚单？","o":["超过限速 1 mph","超过限速 5 mph","超过限速 20 mph 以上","只有超过限速 50 mph 以上"],"h1":"这个数字很大，但没有 50 那么大。","h2":"在 Arizona，开车超过限速 20 mph 以上，就是过度超速罪。","p":"对。超过限速 20 mph 以上是刑事犯罪。"},"vi":{"q":"Ở Arizona, khi nào chạy quá tốc độ trở thành tội chạy tốc độ quá mức, chứ không chỉ là vé phạt dân sự?","o":["Khi chạy quá giới hạn 1 mph","Khi chạy quá giới hạn 5 mph","Khi chạy quá giới hạn hơn 20 mph","Chỉ khi chạy quá giới hạn hơn 50 mph"],"h1":"Đó là một con số lớn, nhưng không lớn bằng 50.","h2":"Ở Arizona, lái xe quá giới hạn tốc độ hơn 20 mph là tội chạy tốc độ quá mức.","p":"Đúng. Quá giới hạn hơn 20 mph là tội hình sự."},"tl":{"q":"Sa Arizona, kailan nagiging krimen ng excessive speed ang pag-overspeed, at hindi lang civil ticket?","o":["Sa 1 mph lampas sa nakapaskil na limit","Sa 5 mph lampas sa nakapaskil na limit","Sa higit sa 20 mph lampas sa nakapaskil na limit","Sa higit lang sa 50 mph lampas sa nakapaskil na limit"],"h1":"Malaking numero ito, pero hindi kasinlaki ng 50.","h2":"Sa Arizona, ang pagmamaneho nang higit sa 20 mph lampas sa nakapaskil na speed limit ay krimen ng excessive speed.","p":"Tama. Ang higit sa 20 mph lampas sa limit ay isang krimen."},"ar":{"q":"في Arizona، متى تصبح السرعة الزائدة جريمة السرعة المفرطة، وليست مجرد مخالفة مدنية؟","o":["عند 1 mph فوق الحد المكتوب","عند 5 mph فوق الحد المكتوب","عند أكثر من 20 mph فوق الحد المكتوب","فقط عند أكثر من 50 mph فوق الحد المكتوب"],"h1":"إنه رقم كبير، لكنه ليس بحجم 50.","h2":"في Arizona، القيادة بأكثر من 20 mph فوق حد السرعة المكتوب هي جريمة السرعة المفرطة.","p":"صحيح. أكثر من 20 mph فوق الحد جريمة جنائية."},"ref":{"doc":"AZ","page":null}},{"id":"az-041","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, you drive slowly on a two-lane road where passing is unsafe. How many vehicles in a line behind you means you must pull into a turnout?","o":["2 or more","3 or more","5 or more","10 or more"],"h1":"It is more than a few, but fewer than ten.","h2":"In Arizona, if 5 or more vehicles are lined up behind your slow vehicle on a two-lane road, you must pull off at the nearest safe turnout to let them pass.","p":"Right. With 5 or more vehicles behind you, use a turnout."},"es":{"q":"En Arizona, usted maneja despacio en una carretera de dos carriles donde no es seguro rebasar. ¿Cuántos vehículos en fila detrás de usted lo obligan a salirse a un área de desvío?","o":["2 o más","3 o más","5 o más","10 o más"],"h1":"Son más que unos pocos, pero menos de diez.","h2":"En Arizona, si 5 o más vehículos van en fila detrás de su vehículo lento en una carretera de dos carriles, usted debe salirse en el área de desvío segura más cercana para dejarlos pasar.","p":"Correcto. Con 5 o más vehículos detrás, use un área de desvío."},"zh":{"q":"在 Arizona，你在一条不安全超车的双车道路上开得很慢。你后面排了多少辆车时，你必须开进避车道？","o":["2 辆或更多","3 辆或更多","5 辆或更多","10 辆或更多"],"h1":"比几辆多，但比十辆少。","h2":"在 Arizona，如果在双车道路上你慢行的车后面排了 5 辆或更多车，你必须在最近的安全避车道靠边，让它们过去。","p":"对。后面有 5 辆或更多车时，要开进避车道。"},"vi":{"q":"Ở Arizona, bạn lái chậm trên đường hai làn, nơi vượt xe không an toàn. Có bao nhiêu xe xếp hàng phía sau thì bạn phải tấp vào chỗ tránh xe?","o":["2 xe trở lên","3 xe trở lên","5 xe trở lên","10 xe trở lên"],"h1":"Nhiều hơn vài chiếc, nhưng ít hơn mười.","h2":"Ở Arizona, nếu có 5 xe trở lên xếp hàng sau xe chạy chậm của bạn trên đường hai làn, bạn phải tấp vào chỗ tránh xe an toàn gần nhất để cho họ vượt.","p":"Đúng. Có 5 xe trở lên phía sau thì hãy tấp vào chỗ tránh xe."},"tl":{"q":"Sa Arizona, mabagal kang nagmamaneho sa two-lane road kung saan hindi ligtas mag-overtake. Ilang sasakyan ang nakapila sa likod mo bago ka dapat pumasok sa turnout?","o":["2 o higit pa","3 o higit pa","5 o higit pa","10 o higit pa"],"h1":"Higit ito sa ilan, pero kulang sa sampu.","h2":"Sa Arizona, kung 5 o higit pang sasakyan ang nakapila sa likod ng mabagal mong sasakyan sa two-lane road, dapat kang tumabi sa pinakamalapit na ligtas na turnout para makalampas sila.","p":"Tama. Kapag 5 o higit pang sasakyan ang nasa likod mo, gumamit ng turnout."},"ar":{"q":"في Arizona، تقود ببطء على طريق ذي مسارين حيث التجاوز غير آمن. كم سيارة في صف خلفك تعني أنه يجب أن تدخل إلى مكان جانبي للتنحّي؟","o":["2 أو أكثر","3 أو أكثر","5 أو أكثر","10 أو أكثر"],"h1":"أكثر من بضع سيارات، لكن أقل من عشر.","h2":"في Arizona، إذا اصطفّت 5 سيارات أو أكثر خلف سيارتك البطيئة على طريق ذي مسارين، يجب أن تتنحّى في أقرب مكان جانبي آمن لتدعها تتجاوزك.","p":"صحيح. مع 5 سيارات أو أكثر خلفك، استعمل المكان الجانبي للتنحّي."},"ref":{"doc":"AZ","page":null}},{"id":"az-042","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, you get a speeding ticket in a state highway work zone while workers are present. What happens to the penalty?","o":["It is cut in half","It stays the same","It is only a warning","You pay an extra amount equal to the fine, so it doubles"],"h1":"Workers' safety makes the penalty bigger.","h2":"In Arizona, speeding in a state highway work zone with workers present adds an extra charge equal to the fine, so the penalty doubles.","p":"Right. Speeding near workers doubles the penalty."},"es":{"q":"En Arizona, usted recibe una multa por exceso de velocidad en una zona de construcción de una carretera estatal mientras hay trabajadores presentes. ¿Qué pasa con la multa?","o":["Se reduce a la mitad","Queda igual","Es solo una advertencia","Paga un cargo extra igual a la multa, así que se duplica"],"h1":"La seguridad de los trabajadores hace que la multa sea mayor.","h2":"En Arizona, exceder la velocidad en una zona de construcción de una carretera estatal con trabajadores presentes agrega un cargo extra igual a la multa, así que la multa se duplica.","p":"Correcto. Exceder la velocidad cerca de trabajadores duplica la multa."},"zh":{"q":"在 Arizona，你在有工人在场的州公路施工区收到超速罚单。处罚会怎样？","o":["减半","保持不变","只是警告","你要额外付一笔和罚款一样多的钱，所以翻倍"],"h1":"为了工人的安全，处罚会更重。","h2":"在 Arizona，在有工人在场的州公路施工区超速，会额外加收一笔和罚款相同的钱，所以处罚翻倍。","p":"对。在工人附近超速，处罚翻倍。"},"vi":{"q":"Ở Arizona, bạn bị phạt vì chạy quá tốc độ trong khu vực thi công trên xa lộ tiểu bang khi có công nhân đang làm việc. Mức phạt sẽ ra sao?","o":["Giảm một nửa","Giữ nguyên","Chỉ là cảnh cáo","Bạn trả thêm một khoản bằng tiền phạt, nên gấp đôi"],"h1":"Sự an toàn của công nhân làm cho mức phạt nặng hơn.","h2":"Ở Arizona, chạy quá tốc độ trong khu vực thi công trên xa lộ tiểu bang khi có công nhân sẽ bị cộng thêm một khoản bằng tiền phạt, nên mức phạt gấp đôi.","p":"Đúng. Chạy quá tốc độ gần công nhân thì mức phạt gấp đôi."},"tl":{"q":"Sa Arizona, nakakuha ka ng speeding ticket sa work zone ng state highway habang may mga trabahador. Ano ang mangyayari sa parusa?","o":["Mababawasan nang kalahati","Mananatiling pareho","Babala lang ito","Magbabayad ka ng dagdag na halagang kapareho ng multa, kaya dodoble ito"],"h1":"Dahil sa kaligtasan ng mga trabahador, lumalaki ang parusa.","h2":"Sa Arizona, ang pag-overspeed sa work zone ng state highway na may mga trabahador ay may dagdag na singil na kapareho ng multa, kaya dumodoble ang parusa.","p":"Tama. Dumodoble ang parusa sa pag-overspeed malapit sa mga trabahador."},"ar":{"q":"في Arizona، حصلت على مخالفة سرعة في منطقة أعمال على طريق سريع تابع للولاية بينما العمّال موجودون. ماذا يحدث للعقوبة؟","o":["تُخفَّض إلى النصف","تبقى كما هي","تكون تحذيرًا فقط","تدفع مبلغًا إضافيًا يساوي الغرامة، فتتضاعف"],"h1":"سلامة العمّال تجعل العقوبة أكبر.","h2":"في Arizona، السرعة الزائدة في منطقة أعمال على طريق سريع تابع للولاية بوجود العمّال تضيف مبلغًا يساوي الغرامة، فتتضاعف العقوبة.","p":"صحيح. السرعة الزائدة قرب العمّال تضاعف العقوبة."},"ref":{"doc":"AZ","page":null}},{"id":"az-043","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, you are passing a bicycle going the same way. How much space must you leave?","o":["At least 1 foot","At least 3 feet","At least 10 feet","No set amount"],"h1":"It is about the length of a yardstick.","h2":"In Arizona you must leave at least 3 feet between your car and a bicycle you are passing.","p":"Right. Give a bicycle at least 3 feet when you pass."},"es":{"q":"En Arizona, usted rebasa a una bicicleta que va en la misma dirección. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 10 pies","No hay una cantidad fija"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Arizona usted debe dejar por lo menos 3 pies entre su carro y una bicicleta que está rebasando.","p":"Correcto. Deje por lo menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 Arizona，你正在超过一辆同方向行驶的自行车。你必须留出多少空间？","o":["至少 1 英尺","至少 3 英尺","至少 10 英尺","没有规定"],"h1":"大约是一根码尺的长度。","h2":"在 Arizona，你超过自行车时，你的车和自行车之间必须至少留出 3 英尺。","p":"对。超过自行车时，至少留出 3 英尺。"},"vi":{"q":"Ở Arizona, bạn đang vượt một xe đạp đi cùng chiều. Bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 3 feet","Ít nhất 10 feet","Không có mức cố định"],"h1":"Khoảng bằng chiều dài một cây thước yard.","h2":"Ở Arizona, bạn phải chừa ít nhất 3 feet giữa xe của bạn và xe đạp bạn đang vượt.","p":"Đúng. Hãy chừa cho xe đạp ít nhất 3 feet khi vượt."},"tl":{"q":"Sa Arizona, nilalampasan mo ang isang bisikletang papunta sa parehong direksiyon. Gaano kalaking espasyo ang dapat mong iwan?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet","Walang takdang sukat"],"h1":"Mga kasinghaba ito ng isang yardstick.","h2":"Sa Arizona, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng bisikletang nilalampasan mo.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag lumalampas ka."},"ar":{"q":"في Arizona، أنت تتجاوز دراجة هوائية تسير في الاتجاه نفسه. كم مسافة يجب أن تترك؟","o":["على الأقل قدم واحدة","على الأقل 3 أقدام","على الأقل 10 أقدام","لا توجد مسافة محدّدة"],"h1":"إنها نحو طول مسطرة الياردة.","h2":"في Arizona يجب أن تترك على الأقل 3 أقدام بين سيارتك والدراجة الهوائية التي تتجاوزها.","p":"صحيح. اترك للدراجة الهوائية على الأقل 3 أقدام عندما تتجاوزها."},"ref":{"doc":"AZ","page":null}},{"id":"az-044","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, on a regular road with no bike path, how many bicycle riders may ride side by side?","o":["No more than two","No more than three","No more than four","As many as they want"],"h1":"Think of a pair.","h2":"In Arizona, bicycle riders on a roadway may not ride more than two side by side, except on paths set aside for bicycles.","p":"Right. Bicycle riders may ride no more than two side by side."},"es":{"q":"En Arizona, en una calle normal sin ciclovía, ¿cuántos ciclistas pueden ir uno al lado del otro?","o":["No más de dos","No más de tres","No más de cuatro","Todos los que quieran"],"h1":"Piense en una pareja.","h2":"En Arizona, los ciclistas en una calle no pueden ir más de dos uno al lado del otro, excepto en caminos reservados para bicicletas.","p":"Correcto. Los ciclistas pueden ir no más de dos uno al lado del otro."},"zh":{"q":"在 Arizona，在没有自行车道的普通道路上，最多可以有几个骑自行车的人并排骑？","o":["不超过两个","不超过三个","不超过四个","想几个都可以"],"h1":"想想“一对”。","h2":"在 Arizona，在道路上骑自行车的人不可以超过两个并排骑，专门给自行车用的道路除外。","p":"对。骑自行车的人最多两个并排骑。"},"vi":{"q":"Ở Arizona, trên đường thường không có làn xe đạp, được phép có bao nhiêu người đi xe đạp chạy song song nhau?","o":["Không quá hai người","Không quá ba người","Không quá bốn người","Bao nhiêu cũng được"],"h1":"Hãy nghĩ đến một cặp.","h2":"Ở Arizona, người đi xe đạp trên đường không được chạy quá hai người song song, trừ trên lối đi dành riêng cho xe đạp.","p":"Đúng. Người đi xe đạp chỉ được chạy tối đa hai người song song."},"tl":{"q":"Sa Arizona, sa karaniwang daan na walang bike path, ilang nagbibisikleta ang puwedeng magkatabi?","o":["Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Hindi hihigit sa apat","Kahit ilan ang gusto nila"],"h1":"Isipin ang isang pares.","h2":"Sa Arizona, ang mga nagbibisikleta sa daan ay hindi puwedeng magkatabi nang higit sa dalawa, maliban sa mga daang nakalaan para sa bisikleta.","p":"Tama. Hindi hihigit sa dalawang nagbibisikleta ang puwedeng magkatabi."},"ar":{"q":"في Arizona، على طريق عادي بلا مسار للدراجات، كم راكب دراجة هوائية يمكن أن يسيروا جنبًا إلى جنب؟","o":["ليس أكثر من اثنين","ليس أكثر من ثلاثة","ليس أكثر من أربعة","أيّ عدد يريدونه"],"h1":"فكّر في زوج.","h2":"في Arizona، يجب ألّا يسير راكبو الدراجات الهوائية على الطريق أكثر من اثنين جنبًا إلى جنب، إلا على المسارات المخصّصة للدراجات.","p":"صحيح. يسير راكبو الدراجات الهوائية اثنين جنبًا إلى جنب على الأكثر."},"ref":{"doc":"AZ","page":null}},{"id":"az-045","scope":"AZ","cat":"signals","sign":null,"c":3,"en":{"q":"In Arizona, before you turn, how far ahead must you keep your turn signal on?","o":["At least 10 feet","At least 25 feet","At least 1,000 feet","At least the last 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Arizona you must signal a turn for at least the last 100 feet before you turn.","p":"Right. Signal for at least the last 100 feet before turning."},"es":{"q":"En Arizona, antes de dar vuelta, ¿con cuánta anticipación debe tener puesta la direccional?","o":["Por lo menos 10 pies","Por lo menos 25 pies","Por lo menos 1,000 pies","Por lo menos los últimos 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"En Arizona usted debe señalar una vuelta durante por lo menos los últimos 100 pies antes de dar vuelta.","p":"Correcto. Señale por lo menos los últimos 100 pies antes de dar vuelta."},"zh":{"q":"在 Arizona，你转弯前，必须提前多远打开转向灯？","o":["至少 10 英尺","至少 25 英尺","至少 1,000 英尺","至少在最后 100 英尺"],"h1":"大约六七辆车的长度。","h2":"在 Arizona，你转弯前，必须至少在最后 100 英尺打转向灯。","p":"对。转弯前至少在最后 100 英尺打转向灯。"},"vi":{"q":"Ở Arizona, trước khi rẽ, bạn phải bật đèn xi nhan trước bao xa?","o":["Ít nhất 10 feet","Ít nhất 25 feet","Ít nhất 1,000 feet","Ít nhất trong 100 feet cuối cùng"],"h1":"Khoảng bằng chiều dài sáu hay bảy chiếc xe.","h2":"Ở Arizona, bạn phải bật xi nhan báo rẽ ít nhất trong 100 feet cuối cùng trước khi rẽ.","p":"Đúng. Bật xi nhan ít nhất trong 100 feet cuối cùng trước khi rẽ."},"tl":{"q":"Sa Arizona, bago ka lumiko, gaano kalayo nang maaga dapat nakabukas ang turn signal mo?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 25 feet","Hindi bababa sa 1,000 feet","Hindi bababa sa huling 100 feet"],"h1":"Mga kasinghaba ito ng anim o pitong kotse.","h2":"Sa Arizona, dapat kang mag-signal ng liko nang hindi bababa sa huling 100 feet bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa huling 100 feet bago lumiko."},"ar":{"q":"في Arizona، قبل أن تنعطف، من أيّ مسافة يجب أن تُبقي إشارة الانعطاف مضاءة؟","o":["على الأقل 10 أقدام","على الأقل 25 قدمًا","على الأقل 1,000 قدم","على الأقل آخر 100 قدم"],"h1":"إنها نحو طول ست أو سبع سيارات.","h2":"في Arizona يجب أن تضيء إشارة الانعطاف على الأقل في آخر 100 قدم قبل أن تنعطف.","p":"صحيح. أضئ الإشارة على الأقل في آخر 100 قدم قبل الانعطاف."},"ref":{"doc":"AZ","page":null}},{"id":"az-046","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, the lights at a railroad crossing are flashing. Where must you stop?","o":["Right on the tracks","Between 15 and 50 feet from the nearest rail","Between 100 and 200 feet from the nearest rail","Anywhere you can see the train"],"h1":"Not too close, but not too far to see.","h2":"In Arizona, when a railroad crossing signal warns of a train, you must stop between 15 and 50 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Arizona, las luces de un cruce de ferrocarril están parpadeando. ¿Dónde debe detenerse?","o":["Justo encima de las vías","Entre 15 y 50 pies del riel más cercano","Entre 100 y 200 pies del riel más cercano","En cualquier lugar donde pueda ver el tren"],"h1":"Ni muy cerca, ni tan lejos que no pueda ver.","h2":"En Arizona, cuando la señal de un cruce de ferrocarril avisa que viene un tren, usted debe detenerse entre 15 y 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Arizona，铁路道口的灯在闪。你必须停在哪里？","o":["就停在铁轨上","离最近的铁轨 15 到 50 英尺之间","离最近的铁轨 100 到 200 英尺之间","任何能看到火车的地方"],"h1":"不要太近，但也不要远到看不见。","h2":"在 Arizona，铁路道口的信号警告有火车时，你必须停在离最近的铁轨 15 到 50 英尺之间。","p":"对。停在离最近的铁轨 15 到 50 英尺的地方。"},"vi":{"q":"Ở Arizona, đèn ở chỗ đường sắt giao nhau đang nhấp nháy. Bạn phải dừng ở đâu?","o":["Ngay trên đường ray","Cách đường ray gần nhất từ 15 đến 50 feet","Cách đường ray gần nhất từ 100 đến 200 feet","Bất cứ chỗ nào bạn thấy được tàu hỏa"],"h1":"Không quá gần, nhưng cũng không quá xa để nhìn thấy.","h2":"Ở Arizona, khi tín hiệu ở chỗ đường sắt giao nhau báo có tàu hỏa, bạn phải dừng cách đường ray gần nhất từ 15 đến 50 feet.","p":"Đúng. Dừng cách đường ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Arizona, kumikislap ang mga ilaw sa railroad crossing. Saan ka dapat huminto?","o":["Mismo sa ibabaw ng riles","Sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles","Sa pagitan ng 100 at 200 feet mula sa pinakamalapit na riles","Kahit saan na nakikita mo ang tren"],"h1":"Hindi masyadong malapit, pero hindi rin masyadong malayo para makakita.","h2":"Sa Arizona, kapag nagbababala ng tren ang signal ng railroad crossing, dapat kang huminto sa pagitan ng 15 at 50 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto 15 hanggang 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Arizona، الأضواء عند معبر سكة الحديد تومض. أين يجب أن تتوقف؟","o":["على القضبان نفسها","على بُعد ما بين 15 و50 قدمًا من أقرب قضيب","على بُعد ما بين 100 و200 قدم من أقرب قضيب","في أيّ مكان ترى منه القطار"],"h1":"ليس قريبًا جدًا، وليس بعيدًا جدًا عن الرؤية.","h2":"في Arizona، عندما تحذّر إشارة معبر سكة الحديد من قطار، يجب أن تتوقف على بُعد ما بين 15 و50 قدمًا من أقرب قضيب.","p":"صحيح. توقّف على بُعد 15 إلى 50 قدمًا من أقرب قضيب."},"ref":{"doc":"AZ","page":null}},{"id":"az-047","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is a little more than the length of a car.","h2":"In Arizona you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Arizona, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 100 pies"],"h1":"Es un poco más que el largo de un carro.","h2":"En Arizona usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Arizona，你可以把车停在离路口人行横道多近的地方？","o":["不近于 5 英尺","不近于 10 英尺","不近于 20 英尺","不近于 100 英尺"],"h1":"比一辆车的长度多一点。","h2":"在 Arizona，你不可以把车停在路口人行横道 20 英尺以内。","p":"对。停车时离路口人行横道至少 20 英尺。"},"vi":{"q":"Ở Arizona, bạn được đậu xe gần lối băng qua đường ở giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 100 feet"],"h1":"Dài hơn chiều dài một chiếc xe một chút.","h2":"Ở Arizona, bạn không được đậu xe trong vòng 20 feet tính từ lối băng qua đường ở giao lộ.","p":"Đúng. Đậu xe cách lối băng qua đường ở giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Arizona, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 10 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 100 feet"],"h1":"Medyo mas mahaba ito kaysa sa haba ng isang kotse.","h2":"Sa Arizona, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa crosswalk sa intersection.","p":"Tama. Pumarada nang hindi bababa sa 20 feet mula sa crosswalk sa intersection."},"ar":{"q":"في Arizona، إلى أيّ قرب من ممرّ المشاة عند التقاطع يمكنك أن تركن سيارتك؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 100 قدم"],"h1":"إنها أكثر قليلًا من طول سيارة.","h2":"في Arizona يجب ألّا تركن سيارتك على بُعد أقل من 20 قدمًا من ممرّ المشاة عند التقاطع.","p":"صحيح. اركن على بُعد 20 قدمًا على الأقل من ممرّ المشاة عند التقاطع."},"ref":{"doc":"AZ","page":null}},{"id":"az-048","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, how close may you park before a stop sign at the side of the road?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Drivers coming up to the sign need to see it clearly.","h2":"In Arizona you may not park within 30 feet before a stop sign, yield sign, flashing beacon or traffic signal at the side of the road.","p":"Right. Park at least 30 feet before a stop sign."},"es":{"q":"En Arizona, ¿qué tan cerca puede estacionarse antes de un letrero de alto al lado del camino?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los conductores que se acercan al letrero necesitan verlo bien.","h2":"En Arizona usted no puede estacionarse a menos de 30 pies antes de un letrero de alto, de ceda el paso, una luz intermitente o un semáforo al lado del camino.","p":"Correcto. Estaciónese por lo menos 30 pies antes de un letrero de alto."},"zh":{"q":"在 Arizona，在路边的停车标志前，你可以把车停在离它多近的地方？","o":["不近于 5 英尺","不近于 10 英尺","不近于 15 英尺","不近于 30 英尺"],"h1":"开过来的司机需要清楚地看到这个标志。","h2":"在 Arizona，你不可以把车停在路边的停车标志、让行标志、闪光信号灯或交通信号灯前 30 英尺以内。","p":"对。停车时离停车标志前至少 30 英尺。"},"vi":{"q":"Ở Arizona, bạn được đậu xe trước biển báo dừng ở bên đường gần đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Tài xế đang chạy tới biển báo cần nhìn thấy nó rõ ràng.","h2":"Ở Arizona, bạn không được đậu xe trong vòng 30 feet trước biển báo dừng, biển nhường đường, đèn nhấp nháy hoặc đèn giao thông ở bên đường.","p":"Đúng. Đậu xe cách trước biển báo dừng ít nhất 30 feet."},"tl":{"q":"Sa Arizona, gaano kalapit ka puwedeng pumarada bago ang stop sign sa gilid ng daan?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 10 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 30 feet"],"h1":"Kailangang makita nang malinaw ng mga driver na papalapit ang karatula.","h2":"Sa Arizona, hindi ka puwedeng pumarada sa loob ng 30 feet bago ang stop sign, yield sign, kumikislap na beacon o traffic signal sa gilid ng daan.","p":"Tama. Pumarada nang hindi bababa sa 30 feet bago ang stop sign."},"ar":{"q":"في Arizona، إلى أيّ قرب يمكنك أن تركن قبل لافتة التوقف على جانب الطريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"السائقون القادمون نحو اللافتة يحتاجون أن يروها بوضوح.","h2":"في Arizona يجب ألّا تركن سيارتك على بُعد أقل من 30 قدمًا قبل لافتة التوقف أو لافتة إعطاء حق المرور أو الضوء الوامض أو إشارة المرور على جانب الطريق.","p":"صحيح. اركن على بُعد 30 قدمًا على الأقل قبل لافتة التوقف."},"ref":{"doc":"AZ","page":null}},{"id":"az-049","scope":"AZ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arizona, how close to a railroad crossing may you park?","o":["No closer than 50 feet from the nearest rail","No closer than 10 feet from the nearest rail","No closer than 20 feet from the nearest rail","Anywhere, if you leave your flashers on"],"h1":"It is more than 20 feet.","h2":"In Arizona you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from the nearest rail."},"es":{"q":"En Arizona, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 50 pies del riel más cercano","No más cerca de 10 pies del riel más cercano","No más cerca de 20 pies del riel más cercano","En cualquier lugar, si deja las luces intermitentes encendidas"],"h1":"Es más de 20 pies.","h2":"En Arizona usted no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Arizona，你可以把车停在离铁路道口多近的地方？","o":["离最近的铁轨不近于 50 英尺","离最近的铁轨不近于 10 英尺","离最近的铁轨不近于 20 英尺","哪里都可以，只要开着双闪灯"],"h1":"比 20 英尺多。","h2":"在 Arizona，你不可以把车停在离铁路道口最近的铁轨 50 英尺以内。","p":"对。停车时离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Arizona, bạn được đậu xe gần chỗ đường sắt giao nhau đến mức nào?","o":["Không gần hơn 50 feet tính từ đường ray gần nhất","Không gần hơn 10 feet tính từ đường ray gần nhất","Không gần hơn 20 feet tính từ đường ray gần nhất","Ở đâu cũng được, nếu bạn bật đèn khẩn cấp"],"h1":"Hơn 20 feet.","h2":"Ở Arizona, bạn không được đậu xe trong vòng 50 feet tính từ đường ray gần nhất của chỗ đường sắt giao nhau.","p":"Đúng. Đậu xe cách đường ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Arizona, gaano kalapit sa railroad crossing ka puwedeng pumarada?","o":["Hindi mas malapit sa 50 feet mula sa pinakamalapit na riles","Hindi mas malapit sa 10 feet mula sa pinakamalapit na riles","Hindi mas malapit sa 20 feet mula sa pinakamalapit na riles","Kahit saan, kung nakabukas ang flashers mo"],"h1":"Higit ito sa 20 feet.","h2":"Sa Arizona, hindi ka puwedeng pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Pumarada nang hindi bababa sa 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Arizona، إلى أيّ قرب من معبر سكة الحديد يمكنك أن تركن؟","o":["ليس أقرب من 50 قدمًا من أقرب قضيب","ليس أقرب من 10 أقدام من أقرب قضيب","ليس أقرب من 20 قدمًا من أقرب قضيب","في أيّ مكان، إذا تركت أضواء الطوارئ مضاءة"],"h1":"إنها أكثر من 20 قدمًا.","h2":"في Arizona يجب ألّا تركن سيارتك على بُعد أقل من 50 قدمًا من أقرب قضيب في معبر سكة الحديد.","p":"صحيح. اركن على بُعد 50 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"AZ","page":null}},{"id":"az-050","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, you park along a curb. How close to the curb must your right wheels be?","o":["Within 6 feet","Within 18 inches","Within 3 feet","Touching the curb"],"h1":"It is a foot and a half.","h2":"In Arizona, when you park along a curb, your right wheels must be parallel to it and within 18 inches of it.","p":"Right. Park with your wheels within 18 inches of the curb."},"es":{"q":"En Arizona, usted se estaciona junto a la banqueta. ¿Qué tan cerca de la banqueta deben estar sus llantas derechas?","o":["A menos de 6 pies","A menos de 18 pulgadas","A menos de 3 pies","Tocando la banqueta"],"h1":"Es un pie y medio.","h2":"En Arizona, cuando se estaciona junto a la banqueta, sus llantas derechas deben estar paralelas a ella y a menos de 18 pulgadas.","p":"Correcto. Estaciónese con las llantas a menos de 18 pulgadas de la banqueta."},"zh":{"q":"在 Arizona，你沿着路缘停车。你的右侧车轮必须离路缘多近？","o":["6 英尺以内","18 英寸以内","3 英尺以内","贴着路缘"],"h1":"是一英尺半。","h2":"在 Arizona，沿着路缘停车时，你的右侧车轮必须和路缘平行，并且在离路缘 18 英寸以内。","p":"对。停车时车轮离路缘要在 18 英寸以内。"},"vi":{"q":"Ở Arizona, bạn đậu xe sát lề đường. Bánh xe bên phải của bạn phải cách lề đường gần đến mức nào?","o":["Trong vòng 6 feet","Trong vòng 18 inches","Trong vòng 3 feet","Chạm vào lề đường"],"h1":"Đó là một foot rưỡi.","h2":"Ở Arizona, khi đậu xe sát lề đường, bánh xe bên phải của bạn phải song song với lề và cách lề trong vòng 18 inches.","p":"Đúng. Đậu xe với bánh xe cách lề đường trong vòng 18 inches."},"tl":{"q":"Sa Arizona, pumarada ka sa tabi ng curb. Gaano kalapit sa curb dapat ang mga gulong mo sa kanan?","o":["Sa loob ng 6 feet","Sa loob ng 18 inches","Sa loob ng 3 feet","Nakadikit sa curb"],"h1":"Isa at kalahating foot ito.","h2":"Sa Arizona, kapag pumarada ka sa tabi ng curb, dapat parallel dito ang mga gulong mo sa kanan at nasa loob ng 18 inches mula rito.","p":"Tama. Pumarada nang nasa loob ng 18 inches mula sa curb ang mga gulong mo."},"ar":{"q":"في Arizona، تركن سيارتك بجانب الرصيف. ما مدى القرب الذي يجب أن تكون عليه عجلاتك اليمنى من الرصيف؟","o":["في حدود 6 أقدام","في حدود 18 بوصة","في حدود 3 أقدام","ملامسة للرصيف"],"h1":"إنها قدم ونصف.","h2":"في Arizona، عندما تركن بجانب الرصيف، يجب أن تكون عجلاتك اليمنى موازية له وعلى بُعد 18 بوصة منه أو أقل.","p":"صحيح. اركن وعجلاتك على بُعد 18 بوصة من الرصيف أو أقل."},"ref":{"doc":"AZ","page":null}},{"id":"az-051","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, what is the fine for a first ticket for holding a phone while driving?","o":["$75 to $149","$10 to $25","$400 to $500","$1,000 to $2,000"],"h1":"It is under $150.","h2":"In Arizona the civil penalty for a first violation of the hands-free law is $75 to $149.","p":"Right. A first hands-free violation costs $75 to $149."},"es":{"q":"En Arizona, ¿cuál es la multa por una primera infracción por sostener el teléfono mientras maneja?","o":["De $75 a $149","De $10 a $25","De $400 a $500","De $1,000 a $2,000"],"h1":"Es menos de $150.","h2":"En Arizona la multa civil por una primera infracción de la ley de manos libres es de $75 a $149.","p":"Correcto. Una primera infracción de manos libres cuesta de $75 a $149."},"zh":{"q":"在 Arizona，第一次因开车时手拿手机被开罚单，罚款是多少？","o":["$75 到 $149","$10 到 $25","$400 到 $500","$1,000 到 $2,000"],"h1":"不到 $150。","h2":"在 Arizona，第一次违反免提法的民事罚款是 $75 到 $149。","p":"对。第一次违反免提法要罚 $75 到 $149。"},"vi":{"q":"Ở Arizona, tiền phạt cho vé phạt đầu tiên vì cầm điện thoại khi lái xe là bao nhiêu?","o":["$75 đến $149","$10 đến $25","$400 đến $500","$1,000 đến $2,000"],"h1":"Dưới $150.","h2":"Ở Arizona, tiền phạt dân sự cho lần vi phạm đầu tiên luật rảnh tay (không cầm điện thoại) là $75 đến $149.","p":"Đúng. Vi phạm luật rảnh tay lần đầu bị phạt $75 đến $149."},"tl":{"q":"Sa Arizona, magkano ang multa sa unang ticket dahil may hawak kang phone habang nagmamaneho?","o":["$75 hanggang $149","$10 hanggang $25","$400 hanggang $500","$1,000 hanggang $2,000"],"h1":"Mas mababa ito sa $150.","h2":"Sa Arizona, ang civil penalty sa unang paglabag sa hands-free law ay $75 hanggang $149.","p":"Tama. Ang unang paglabag sa hands-free law ay $75 hanggang $149."},"ar":{"q":"في Arizona، ما غرامة أول مخالفة بسبب الإمساك بالهاتف أثناء القيادة؟","o":["$75 إلى $149","$10 إلى $25","$400 إلى $500","$1,000 إلى $2,000"],"h1":"إنها أقل من $150.","h2":"في Arizona العقوبة المدنية لأول مخالفة لقانون عدم استعمال اليدين للهاتف هي $75 إلى $149.","p":"صحيح. أول مخالفة لقانون عدم استعمال اليدين تكلّف $75 إلى $149."},"ref":{"doc":"AZ","page":null}},{"id":"az-052","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a driver is caught for the first time with no car insurance. What is the lowest penalty?","o":["A warning only","$50, with no effect on the license","$100 and one point","$500, and the license is suspended or restricted for 3 months"],"h1":"It costs hundreds of dollars and affects the license.","h2":"In Arizona a first violation for driving without insurance brings a penalty of at least $500 and a 3-month suspension or restriction of the license.","p":"Right. At least $500 and 3 months of suspension or restriction."},"es":{"q":"En Arizona, a un conductor lo detienen por primera vez sin seguro de auto. ¿Cuál es la multa más baja?","o":["Solo una advertencia","$50, sin efecto en la licencia","$100 y un punto","$500, y la licencia se suspende o se restringe por 3 meses"],"h1":"Cuesta cientos de dólares y afecta la licencia.","h2":"En Arizona una primera infracción por manejar sin seguro trae una multa de por lo menos $500 y la suspensión o restricción de la licencia por 3 meses.","p":"Correcto. Por lo menos $500 y 3 meses de suspensión o restricción."},"zh":{"q":"在 Arizona，一个司机第一次被发现没有汽车保险。最低处罚是什么？","o":["只有警告","$50，不影响驾照","$100 加一分","$500，而且驾照被暂停或限制 3 个月"],"h1":"要花几百美元，而且会影响驾照。","h2":"在 Arizona，第一次没有保险开车，处罚至少是 $500，并且驾照被暂停或限制 3 个月。","p":"对。至少 $500，加上 3 个月的驾照暂停或限制。"},"vi":{"q":"Ở Arizona, một tài xế bị phát hiện lần đầu không có bảo hiểm xe. Mức phạt thấp nhất là gì?","o":["Chỉ cảnh cáo","$50, không ảnh hưởng đến bằng lái","$100 và một điểm","$500, và bằng lái bị treo hoặc bị hạn chế 3 tháng"],"h1":"Tốn hàng trăm đô la và ảnh hưởng đến bằng lái.","h2":"Ở Arizona, vi phạm lần đầu vì lái xe không có bảo hiểm sẽ bị phạt ít nhất $500 và bằng lái bị treo hoặc bị hạn chế 3 tháng.","p":"Đúng. Ít nhất $500 và 3 tháng bị treo hoặc hạn chế bằng lái."},"tl":{"q":"Sa Arizona, unang beses nahuli ang isang driver na walang car insurance. Ano ang pinakamababang parusa?","o":["Babala lang","$50, at walang epekto sa lisensiya","$100 at isang puntos","$500, at sususpendihin o lilimitahan ang lisensiya nang 3 buwan"],"h1":"Daan-daang dolyar ang halaga nito at may epekto sa lisensiya.","h2":"Sa Arizona, ang unang paglabag sa pagmamaneho nang walang insurance ay may parusang hindi bababa sa $500 at 3 buwang suspension o restriction ng lisensiya.","p":"Tama. Hindi bababa sa $500 at 3 buwang suspension o restriction."},"ar":{"q":"في Arizona، ضُبط سائق لأول مرة دون تأمين للسيارة. ما أقل عقوبة؟","o":["تحذير فقط","$50، دون أثر على الرخصة","$100 ونقطة واحدة","$500، وتُوقف الرخصة أو تُقيَّد لمدة 3 أشهر"],"h1":"إنها تكلّف مئات الدولارات وتؤثّر على الرخصة.","h2":"في Arizona أول مخالفة للقيادة دون تأمين تجلب عقوبة لا تقل عن $500 وإيقاف الرخصة أو تقييدها لمدة 3 أشهر.","p":"صحيح. على الأقل $500 و3 أشهر من إيقاف الرخصة أو تقييدها."},"ref":{"doc":"AZ","page":null}},{"id":"az-053","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a passenger in a private car have an open can of beer?","o":["Yes, if the driver is sober","No, not anywhere in the passenger area","Yes, if they sit in the back seat","Yes, if the can is in a paper bag"],"h1":"The rule covers everyone in the car, not only the driver.","h2":"In Arizona no one may have an open container of alcohol in the passenger area of a car on a public road; it may go in the trunk.","p":"Right. Open alcohol may not be in the passenger area."},"es":{"q":"En Arizona, ¿puede un pasajero en un carro particular tener una lata de cerveza abierta?","o":["Sí, si el conductor está sobrio","No, en ninguna parte del área de pasajeros","Sí, si va en el asiento de atrás","Sí, si la lata está en una bolsa de papel"],"h1":"La regla aplica a todos en el carro, no solo al conductor.","h2":"En Arizona nadie puede tener un envase abierto de alcohol en el área de pasajeros de un carro en una vía pública; puede ir en la cajuela.","p":"Correcto. El alcohol abierto no puede estar en el área de pasajeros."},"zh":{"q":"在 Arizona，私家车里的乘客可以拿着一罐打开的啤酒吗？","o":["可以，只要司机是清醒的","不可以，乘客区的任何地方都不行","可以，只要坐在后座","可以，只要罐子装在纸袋里"],"h1":"这条规定适用于车里的每个人，不只是司机。","h2":"在 Arizona，在公共道路上，任何人都不可以在车的乘客区放打开的酒；酒可以放在后备箱里。","p":"对。打开的酒不可以放在乘客区。"},"vi":{"q":"Ở Arizona, hành khách trong xe riêng có được cầm một lon bia đã mở không?","o":["Được, nếu tài xế tỉnh táo","Không, không được ở bất cứ chỗ nào trong khoang hành khách","Được, nếu họ ngồi ở ghế sau","Được, nếu lon bia nằm trong túi giấy"],"h1":"Quy định này áp dụng cho mọi người trong xe, không chỉ tài xế.","h2":"Ở Arizona, không ai được để đồ uống có cồn đã mở trong khoang hành khách của xe trên đường công cộng; có thể để nó trong cốp xe.","p":"Đúng. Đồ uống có cồn đã mở không được ở trong khoang hành khách."},"tl":{"q":"Sa Arizona, puwede bang may hawak na bukas na lata ng beer ang pasahero sa pribadong kotse?","o":["Oo, kung hindi lasing ang driver","Hindi, kahit saan sa passenger area","Oo, kung nakaupo sila sa likod","Oo, kung nasa paper bag ang lata"],"h1":"Para sa lahat ng nasa kotse ang patakaran, hindi lang sa driver.","h2":"Sa Arizona, walang puwedeng magkaroon ng bukas na lalagyan ng alak sa passenger area ng kotse sa pampublikong daan; puwede itong ilagay sa trunk.","p":"Tama. Hindi puwedeng nasa passenger area ang bukas na alak."},"ar":{"q":"في Arizona، هل يمكن لراكب في سيارة خاصة أن تكون معه علبة بيرة مفتوحة؟","o":["نعم، إذا كان السائق غير مخمور","لا، ولا في أيّ مكان من منطقة الركّاب","نعم، إذا جلس في المقعد الخلفي","نعم، إذا كانت العلبة في كيس ورقي"],"h1":"القاعدة تشمل كل من في السيارة، لا السائق فقط.","h2":"في Arizona يجب ألّا يكون مع أيّ شخص وعاء كحول مفتوح في منطقة الركّاب في سيارة على طريق عام؛ يمكن وضعه في صندوق السيارة.","p":"صحيح. يجب ألّا يكون الكحول المفتوح في منطقة الركّاب."},"ref":{"doc":"AZ","page":null}},{"id":"az-054","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, you move to a new home. How soon must you tell the MVD your new address?","o":["Within 30 days","Within 10 days","Within 90 days","At your next license renewal"],"h1":"The deadline is shorter than a month.","h2":"In Arizona, you must tell the MVD your new address within 10 days after you move.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Arizona, usted se muda a una casa nueva. ¿En cuánto tiempo debe informar a la MVD su nueva dirección?","o":["Dentro de 30 días","Dentro de 10 días","Dentro de 90 días","Cuando renueve su licencia"],"h1":"El plazo es menor de un mes.","h2":"En Arizona, usted debe informar a la MVD su nueva dirección dentro de los 10 días después de mudarse.","p":"Correcto. Informe la nueva dirección dentro de 10 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-055","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, you hit a parked car and nobody is in it. You cannot find the owner. What must you do?","o":["Drive away, since no one was hurt","Wait an hour, then drive away","Leave a note with your name and address","Call your insurance company next week"],"h1":"The owner must be able to find out who hit the car.","h2":"In Arizona, if you hit an unattended vehicle and cannot find the owner, you must stop and leave a written note where it is easy to see, with your name and address and those of the owner of the car you were driving.","p":"Right. Stop and leave a note with your name and address."},"es":{"q":"En Arizona, usted choca un auto estacionado y no hay nadie adentro. No puede encontrar al dueño. ¿Qué debe hacer?","o":["Irse, porque nadie se lastimó","Esperar una hora y luego irse","Dejar una nota con su nombre y dirección","Llamar a su aseguradora la próxima semana"],"h1":"El dueño debe poder saber quién chocó su auto.","h2":"En Arizona, si usted choca un vehículo sin nadie adentro y no puede encontrar al dueño, debe detenerse y dejar una nota escrita en un lugar fácil de ver, con su nombre y dirección y los del dueño del auto que usted manejaba.","p":"Correcto. Deténgase y deje una nota con su nombre y dirección."},"ref":{"doc":"AZ","page":null}},{"id":"az-056","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a driver is found responsible for driving the wrong way on a freeway. What is the civil penalty?","o":["$500","$50","$150","$75"],"h1":"It is several hundred dollars.","h2":"In Arizona, driving the wrong way on a freeway brings a civil penalty of $500, and the driver must also complete Traffic Survival School.","p":"Right. $500, plus Traffic Survival School."},"es":{"q":"En Arizona, se declara responsable a un conductor por manejar en sentido contrario en una autopista. ¿Cuál es la multa civil?","o":["$500","$50","$150","$75"],"h1":"Son varios cientos de dólares.","h2":"En Arizona, manejar en sentido contrario en una autopista trae una multa civil de $500, y además el conductor debe completar la Traffic Survival School (escuela de seguridad vial).","p":"Correcto. $500, más la Traffic Survival School."},"ref":{"doc":"AZ","page":null}},{"id":"az-057","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a driver is convicted of street racing for the second time within 24 months. What kind of crime is it?","o":["A civil ticket","A petty offense","No crime, just a warning","A felony"],"h1":"A repeat within two years is treated much more seriously.","h2":"In Arizona, a second racing conviction within 24 months is a class 6 felony, with at least 10 days in jail and a one-year license suspension.","p":"Right. A second racing conviction within 24 months is a felony."},"es":{"q":"En Arizona, un conductor es declarado culpable de hacer carreras en la calle por segunda vez en 24 meses. ¿Qué tipo de delito es?","o":["Una multa civil","Una falta menor","No es delito, solo una advertencia","Un delito grave (felonía)"],"h1":"Repetirlo dentro de dos años se trata con mucha más severidad.","h2":"En Arizona, una segunda condena por carreras dentro de 24 meses es un delito grave de clase 6, con por lo menos 10 días de cárcel y la suspensión de la licencia por un año.","p":"Correcto. Una segunda condena por carreras en 24 meses es un delito grave."},"ref":{"doc":"AZ","page":null}},{"id":"az-058","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, you pass a car on a two-lane road. You must be back in your own lane before you get within how many feet of an oncoming vehicle?","o":["50 feet","100 feet","25 feet","10 feet"],"h1":"It is more than 50 feet.","h2":"In Arizona, when you pass on the left, you must return to the right side of the road before you come within 100 feet of any vehicle coming toward you.","p":"Right. Be back in your lane before you are 100 feet from oncoming traffic."},"es":{"q":"En Arizona, usted rebasa a un auto en una carretera de dos carriles. ¿Antes de llegar a cuántos pies de un vehículo que viene de frente debe regresar a su carril?","o":["50 pies","100 pies","25 pies","10 pies"],"h1":"Son más de 50 pies.","h2":"En Arizona, cuando usted rebasa por la izquierda, debe regresar al lado derecho de la carretera antes de llegar a 100 pies de cualquier vehículo que viene de frente.","p":"Correcto. Regrese a su carril antes de estar a 100 pies del tráfico que viene de frente."},"ref":{"doc":"AZ","page":null}},{"id":"az-059","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, on a two-lane road, you may not drive on the left side to pass when you are within how many feet of an intersection or railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Think of about one third of a football field.","h2":"In Arizona, you may not drive on the left side of the road when you are within 100 feet of an intersection or a railroad crossing, or while crossing one.","p":"Right. No passing on the left within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Arizona, en una carretera de dos carriles, ¿a cuántos pies de una intersección o de un cruce de tren ya no puede manejar por el lado izquierdo para rebasar?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Piense en un tercio de una cancha de fútbol americano.","h2":"En Arizona, usted no puede manejar por el lado izquierdo de la carretera cuando está a menos de 100 pies de una intersección o de un cruce de tren, ni mientras lo cruza.","p":"Correcto. No rebase por la izquierda a menos de 100 pies de una intersección o un cruce de tren."},"ref":{"doc":"AZ","page":null}},{"id":"az-060","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, an HOV (carpool) lane is limited to vehicles with two or more people. Who may use it while riding alone?","o":["A driver of a large SUV","A driver of a pickup truck","A driver who is late for work","A person riding a motorcycle"],"h1":"Look for a vehicle on two wheels.","h2":"In Arizona, a motorcycle may use an HOV lane even with only one rider; a car, SUV or pickup with only the driver in it may not.","p":"Right. Motorcycles may use HOV lanes with one rider."},"es":{"q":"En Arizona, un carril HOV (de vehículos compartidos) es solo para vehículos con dos o más personas. ¿Quién puede usarlo yendo solo?","o":["El conductor de una camioneta SUV grande","El conductor de una camioneta pickup","Un conductor que va tarde al trabajo","Una persona en motocicleta"],"h1":"Busque un vehículo de dos ruedas.","h2":"En Arizona, una motocicleta puede usar un carril HOV aunque lleve solo a una persona; un auto, una SUV o una pickup con solo el conductor no puede.","p":"Correcto. Las motocicletas pueden usar el carril HOV con una sola persona."},"ref":{"doc":"AZ","page":null}},{"id":"az-061","scope":"AZ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Arizona, you want to make a U-turn on a curve or near the top of a hill. Other drivers must be able to see you from at least how far away?","o":["500 feet","100 feet","200 feet","50 feet"],"h1":"It is a long distance, about a tenth of a mile.","h2":"In Arizona, you may not make a U-turn on a curve or near the top of a hill unless drivers coming from either direction can see your vehicle from 500 feet away.","p":"Right. They must be able to see you from 500 feet."},"es":{"q":"En Arizona, usted quiere dar una vuelta en U en una curva o cerca de la cima de una colina. ¿Desde qué distancia mínima deben poder verlo los otros conductores?","o":["500 pies","100 pies","200 pies","50 pies"],"h1":"Es una distancia larga, como una décima de milla.","h2":"En Arizona, usted no puede dar una vuelta en U en una curva o cerca de la cima de una colina, a menos que los conductores que vienen de cualquier dirección puedan ver su vehículo desde 500 pies.","p":"Correcto. Deben poder verlo desde 500 pies."},"ref":{"doc":"AZ","page":null}},{"id":"az-062","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, you reach a T intersection with no signs or signals. You are on the road that ends. Who must yield?","o":["The driver on the road that goes on","You, on the road that ends","Whoever is on the right","Whoever is going faster"],"h1":"The road that keeps going has priority.","h2":"In Arizona, at a T intersection with no signs or signals, the driver on the road that ends must yield to traffic on the road that continues.","p":"Right. The road that ends yields to the through road."},"es":{"q":"En Arizona, usted llega a una intersección en forma de T sin señales ni semáforos. Usted va por la calle que termina. ¿Quién debe ceder el paso?","o":["El conductor de la calle que continúa","Usted, en la calle que termina","El que esté a la derecha","El que vaya más rápido"],"h1":"La calle que sigue tiene prioridad.","h2":"En Arizona, en una intersección en T sin señales ni semáforos, el conductor de la calle que termina debe ceder el paso al tráfico de la calle que continúa.","p":"Correcto. La calle que termina cede el paso a la calle que continúa."},"ref":{"doc":"AZ","page":null}},{"id":"az-063","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, a funeral procession led by a funeral escort vehicle is going through an intersection. What should you do?","o":["Join the line of cars","Drive between the cars if there is a gap","Yield to all the cars in the procession","Honk so they let you pass"],"h1":"The procession may keep going as one group.","h2":"In Arizona, drivers and pedestrians must yield to every vehicle in a funeral procession that is led by a funeral escort vehicle.","p":"Right. Yield to the whole procession."},"es":{"q":"En Arizona, un cortejo fúnebre guiado por un vehículo de escolta fúnebre está cruzando una intersección. ¿Qué debe hacer?","o":["Unirse a la fila de autos","Meterse entre los autos si hay un espacio","Ceder el paso a todos los autos del cortejo","Tocar la bocina para que lo dejen pasar"],"h1":"El cortejo puede seguir como un solo grupo.","h2":"En Arizona, los conductores y peatones deben ceder el paso a cada vehículo de un cortejo fúnebre guiado por un vehículo de escolta fúnebre.","p":"Correcto. Ceda el paso a todo el cortejo."},"ref":{"doc":"AZ","page":null}},{"id":"az-064","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, a person walks along a road that has no sidewalk. Which side of the road should they walk on?","o":["The right side, with traffic","In the middle of the lane","Either side, it does not matter","The left side, facing traffic"],"h1":"Walkers should be able to see the cars coming toward them.","h2":"In Arizona, where there is no sidewalk, a person walking along the road should walk on the left side or its shoulder, facing oncoming traffic, when practicable.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Arizona, una persona camina por una carretera que no tiene acera. ¿Por qué lado de la carretera debe caminar?","o":["Por el lado derecho, en el mismo sentido del tráfico","Por el centro del carril","Por cualquier lado, no importa","Por el lado izquierdo, de frente al tráfico"],"h1":"Quien camina debe poder ver los autos que vienen hacia él.","h2":"En Arizona, donde no hay acera, una persona que camina por la carretera debe ir por el lado izquierdo o su acotamiento, de frente al tráfico, cuando sea posible.","p":"Correcto. Camine por la izquierda, de frente al tráfico."},"ref":{"doc":"AZ","page":null}},{"id":"az-065","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, what must a bicycle have to be ridden at night?","o":["A white front light and a red rear reflector","Only a bell and a horn","A red front light and a white rear light","Only reflectors on the pedals"],"h1":"White in front, red in back.","h2":"In Arizona, a bicycle used at night must have a front lamp with a white light seen from 500 feet and a red reflector on the back.","p":"Right. White light in front, red reflector in back."},"es":{"q":"En Arizona, ¿qué debe tener una bicicleta para usarla de noche?","o":["Una luz blanca adelante y un reflector rojo atrás","Solo un timbre y una bocina","Una luz roja adelante y una luz blanca atrás","Solo reflectores en los pedales"],"h1":"Blanco adelante, rojo atrás.","h2":"En Arizona, una bicicleta que se usa de noche debe tener una lámpara delantera de luz blanca visible desde 500 pies y un reflector rojo atrás.","p":"Correcto. Luz blanca adelante y reflector rojo atrás."},"ref":{"doc":"AZ","page":null}},{"id":"az-066","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are driving down a long hill. May you shift into neutral and coast to save gas?","o":["Yes, if no cars are behind you","No, coasting downhill in neutral is not allowed","Yes, on any hill under one mile","Only in a car with an automatic transmission"],"h1":"You need the engine connected to help control your speed.","h2":"In Arizona, a driver going downhill may not coast with the gears in neutral.","p":"Right. Never coast downhill in neutral."},"es":{"q":"En Arizona, usted baja una colina larga. ¿Puede poner la transmisión en neutral y bajar en punto muerto para ahorrar gasolina?","o":["Sí, si no hay autos detrás","No, bajar en neutral no está permitido","Sí, en cualquier colina de menos de una milla","Solo en un auto con transmisión automática"],"h1":"Necesita el motor conectado para ayudar a controlar la velocidad.","h2":"En Arizona, un conductor que va cuesta abajo no puede bajar con la transmisión en neutral.","p":"Correcto. Nunca baje una colina en neutral."},"ref":{"doc":"AZ","page":null}},{"id":"az-067","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, a fire hose is lying across the street at a fire. When may you drive over it?","o":["When you drive over it very slowly","When the hose looks flat and empty","Only if the fire official in charge allows it","Whenever no firefighters are near it"],"h1":"Someone in charge at the fire must allow it.","h2":"In Arizona, you may not drive over an unprotected fire hose laid down for a fire unless the fire official in charge directs you to.","p":"Right. Only if the fire official in charge tells you to."},"es":{"q":"En Arizona, hay una manguera de bomberos atravesada en la calle durante un incendio. ¿Cuándo puede pasar con su vehículo por encima de ella?","o":["Cuando pasa muy despacio","Cuando la manguera parece vacía","Solo si el jefe de bomberos lo autoriza","Cuando no hay bomberos cerca de ella"],"h1":"Alguien a cargo del incendio debe permitirlo.","h2":"En Arizona, usted no puede pasar por encima de una manguera de bomberos sin protección tendida para un incendio, a menos que el oficial de bomberos a cargo se lo indique.","p":"Correcto. Solo si el oficial de bomberos a cargo se lo indica."},"ref":{"doc":"AZ","page":null}},{"id":"az-068","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, a motorcycle may ride between lanes of stopped traffic on some city streets. What is the top speed allowed while doing this?","o":["25 mph","35 mph","5 mph","15 mph"],"h1":"It is a slow speed, under 20 mph.","h2":"In Arizona, a two-wheeled motorcycle may pass stopped vehicles between lanes only on a street with at least two lanes in its direction and a speed limit of 45 mph or less, and only at 15 mph or less.","p":"Right. No faster than 15 mph."},"es":{"q":"En Arizona, una motocicleta puede circular entre carriles de tráfico detenido en algunas calles de la ciudad. ¿Cuál es la velocidad máxima permitida al hacerlo?","o":["25 mph","35 mph","5 mph","15 mph"],"h1":"Es una velocidad baja, menos de 20 mph.","h2":"En Arizona, una motocicleta de dos ruedas puede pasar entre carriles a vehículos detenidos solo en una calle con por lo menos dos carriles en su sentido y un límite de velocidad de 45 mph o menos, y solo a 15 mph o menos.","p":"Correcto. No más de 15 mph."},"ref":{"doc":"AZ","page":null}},{"id":"az-069","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, what is the civil penalty for not putting a child in a required car seat?","o":["$50","$500","$5","$1,000"],"h1":"It is less than $100.","h2":"In Arizona, the civil penalty for not using a required child restraint system is $50, and it may be dropped if you show that you have since gotten a proper car seat.","p":"Right. The penalty is $50."},"es":{"q":"En Arizona, ¿cuál es la multa civil por no poner a un niño en el asiento de seguridad que la ley exige?","o":["$50","$500","$5","$1,000"],"h1":"Es menos de $100.","h2":"En Arizona, la multa civil por no usar el sistema de retención infantil requerido es de $50, y se puede anular si usted demuestra que ya consiguió un asiento de seguridad adecuado.","p":"Correcto. La multa es de $50."},"ref":{"doc":"AZ","page":null}},{"id":"az-070","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, may a police officer stop a driver only because an adult in the car is not wearing a seat belt?","o":["Yes, that alone is enough reason","No, there must be another reason too","Yes, but only on freeways","Yes, but only at night"],"h1":"The seat belt law is enforced together with other traffic laws.","h2":"In Arizona, an officer may not stop a driver or give a ticket for a seat belt violation unless there is reason to believe another traffic law was also broken.","p":"Right. The officer must have another reason to stop you."},"es":{"q":"En Arizona, ¿puede un policía detener a un conductor solo porque un adulto en el auto no lleva puesto el cinturón de seguridad?","o":["Sí, eso solo es razón suficiente","No, debe haber también otra razón","Sí, pero solo en autopistas","Sí, pero solo de noche"],"h1":"La ley del cinturón se aplica junto con otras leyes de tránsito.","h2":"En Arizona, un policía no puede detener a un conductor ni ponerle una multa por no usar el cinturón, a menos que tenga razones para creer que también se violó otra ley de tránsito.","p":"Correcto. El policía debe tener otra razón para detenerlo."},"ref":{"doc":"AZ","page":null}},{"id":"az-071","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, which passengers in the back seat must wear a seat belt by law?","o":["All back-seat passengers of any age","No back-seat passengers at all","Passengers under 16","Only passengers over 65"],"h1":"The rule for the back seat depends on the rider's age.","h2":"In Arizona, everyone in the front seat must wear a seat belt, and the driver must make sure every passenger under 16 is buckled up, wherever they sit.","p":"Right. Passengers under 16 must be buckled, front or back."},"es":{"q":"En Arizona, ¿qué pasajeros del asiento trasero deben usar el cinturón de seguridad por ley?","o":["Todos los pasajeros de atrás, de cualquier edad","Ningún pasajero del asiento trasero","Los pasajeros menores de 16 años","Solo los pasajeros mayores de 65 años"],"h1":"La regla para el asiento trasero depende de la edad del pasajero.","h2":"En Arizona, todos los que van en el asiento delantero deben usar el cinturón, y el conductor debe asegurarse de que cada pasajero menor de 16 años lo lleve puesto, sin importar dónde vaya sentado.","p":"Correcto. Los pasajeros menores de 16 deben usar el cinturón, adelante o atrás."},"ref":{"doc":"AZ","page":null}},{"id":"az-072","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, a driver goes around barricades onto a flooded road and gets stuck. What can the driver have to pay?","o":["Nothing, rescue is always free","Only a $10 fine","Only the tow truck bill","The cost of the rescue, up to $2,000"],"h1":"The rescue crews' work is not always free.","h2":"In Arizona, a driver who drives onto a flooded road closed by barricades and has to be rescued can be charged for the cost of the emergency response, up to $2,000.","p":"Right. The driver can owe up to $2,000 for the rescue."},"es":{"q":"En Arizona, un conductor pasa las barricadas, entra a una calle inundada y se queda atascado. ¿Qué puede tener que pagar?","o":["Nada, el rescate siempre es gratis","Solo una multa de $10","Solo la cuenta de la grúa","El costo del rescate, hasta $2,000"],"h1":"El trabajo de los equipos de rescate no siempre es gratis.","h2":"En Arizona, un conductor que entra a una calle inundada cerrada con barricadas y tiene que ser rescatado puede tener que pagar el costo de la respuesta de emergencia, hasta $2,000.","p":"Correcto. El conductor puede deber hasta $2,000 por el rescate."},"ref":{"doc":"AZ","page":null}},{"id":"az-073","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, headlights are required from sunset to sunrise. When else must you turn them on?","o":["When you can't see people and cars 500 feet ahead","When you can't see the road 50 feet ahead","Only when it is raining very hard","Only when driving on a freeway"],"h1":"Think about how far ahead you can see.","h2":"In Arizona, headlights must be on from sunset to sunrise and any time there is not enough light to clearly see people and vehicles 500 feet ahead.","p":"Right. Lights on when you can't see 500 feet ahead."},"es":{"q":"En Arizona, los faros son obligatorios desde la puesta hasta la salida del sol. ¿En qué otro momento debe encenderlos?","o":["Cuando no puede ver personas y autos a 500 pies","Cuando no puede ver el camino a 50 pies","Solo cuando llueve muy fuerte","Solo cuando maneja en autopista"],"h1":"Piense en qué tan lejos puede ver.","h2":"En Arizona, los faros deben estar encendidos desde la puesta hasta la salida del sol y siempre que no haya suficiente luz para ver claramente a personas y vehículos a 500 pies.","p":"Correcto. Faros encendidos cuando no puede ver a 500 pies."},"ref":{"doc":"AZ","page":null}},{"id":"az-074","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, you are using high beams at night and come up behind another car. Within how many feet must you switch to low beams?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is less than the distance for oncoming cars.","h2":"In Arizona, when you follow another vehicle within 200 feet, you must not use your high beams unless you are passing it.","p":"Right. Use low beams within 200 feet of a car ahead."},"es":{"q":"En Arizona, usted usa las luces altas de noche y se acerca por detrás a otro auto. ¿A cuántos pies debe cambiar a luces bajas?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es menos que la distancia para los autos que vienen de frente.","h2":"En Arizona, cuando usted sigue a otro vehículo a menos de 200 pies, no debe usar las luces altas, a menos que lo esté rebasando.","p":"Correcto. Use luces bajas a menos de 200 pies de un auto adelante."},"ref":{"doc":"AZ","page":null}},{"id":"az-075","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, during which months may you use tires with metal studs?","o":["All year long","From June 1 to September 30","From October 1 to May 1","Never, they are always banned"],"h1":"They are allowed during the colder part of the year.","h2":"In Arizona, tires with approved metal studs may be used from October 1 to May 1.","p":"Right. October 1 to May 1."},"es":{"q":"En Arizona, ¿en qué meses se pueden usar llantas con clavos de metal?","o":["Todo el año","Del 1 de junio al 30 de septiembre","Del 1 de octubre al 1 de mayo","Nunca, siempre están prohibidas"],"h1":"Se permiten durante la parte más fría del año.","h2":"En Arizona, las llantas con clavos de metal aprobados se pueden usar del 1 de octubre al 1 de mayo.","p":"Correcto. Del 1 de octubre al 1 de mayo."},"ref":{"doc":"AZ","page":null}},{"id":"az-076","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, how long is a regular instruction permit for a car valid?","o":["30 days","6 months","2 years","12 months"],"h1":"It lasts longer than the 6 months a teen must hold it.","h2":"In Arizona, a class D or G instruction permit lets you practice driving for 12 months.","p":"Right. The permit is valid for 12 months."},"es":{"q":"En Arizona, ¿por cuánto tiempo es válido un permiso de aprendizaje regular para auto?","o":["30 días","6 meses","2 años","12 meses"],"h1":"Dura más que los 6 meses que un adolescente debe tenerlo.","h2":"En Arizona, un permiso de aprendizaje clase D o G le permite practicar manejo durante 12 meses.","p":"Correcto. El permiso es válido por 12 meses."},"ref":{"doc":"AZ","page":null}},{"id":"az-077","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, how old must the licensed driver be who rides beside a permit holder?","o":["At least 21","At least 18","At least 16","At least 25"],"h1":"It is the same as the legal drinking age.","h2":"In Arizona, a permit holder must drive with someone who is at least 21, holds a class A, B, C or D license, and sits in the seat beside them.","p":"Right. The supervising driver must be at least 21."},"es":{"q":"En Arizona, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene un permiso de aprendizaje?","o":["Por lo menos 21 años","Por lo menos 18 años","Por lo menos 16 años","Por lo menos 25 años"],"h1":"Es la misma edad legal para tomar alcohol.","h2":"En Arizona, quien tiene un permiso de aprendizaje debe manejar con una persona de por lo menos 21 años, con licencia clase A, B, C o D, sentada en el asiento de al lado.","p":"Correcto. El conductor que supervisa debe tener por lo menos 21 años."},"ref":{"doc":"AZ","page":null}},{"id":"az-078","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, how long is a motorcycle (class M) instruction permit valid?","o":["12 months","7 months","30 days","3 years"],"h1":"It is shorter than a car permit.","h2":"In Arizona, a class M motorcycle instruction permit is valid for seven months from the day it is issued.","p":"Right. A motorcycle permit lasts 7 months."},"es":{"q":"En Arizona, ¿por cuánto tiempo es válido un permiso de aprendizaje de motocicleta (clase M)?","o":["12 meses","7 meses","30 días","3 años"],"h1":"Es más corto que un permiso para auto.","h2":"En Arizona, un permiso de aprendizaje de motocicleta clase M es válido por siete meses desde el día en que se emite.","p":"Correcto. Un permiso de motocicleta dura 7 meses."},"ref":{"doc":"AZ","page":null}},{"id":"az-079","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, which of these is NOT allowed for a rider with a motorcycle instruction permit?","o":["Riding on a city street in daylight","Riding on a county road at noon","Riding on a freeway","Riding to school at midday"],"h1":"Think about high-speed roads with on-ramps.","h2":"In Arizona, a motorcycle permit holder may not ride on a freeway (controlled access highway), and may not ride from sunset to sunrise or when it is too dark to see 500 feet ahead.","p":"Right. No freeways and no night riding with a motorcycle permit."},"es":{"q":"En Arizona, ¿cuál de estas cosas NO puede hacer alguien con un permiso de aprendizaje de motocicleta?","o":["Manejar en una calle de la ciudad de día","Manejar en un camino del condado al mediodía","Manejar en una autopista","Ir a la escuela a media mañana"],"h1":"Piense en las vías rápidas con rampas de entrada.","h2":"En Arizona, quien tiene un permiso de motocicleta no puede manejar en una autopista (vía de acceso controlado), ni entre la puesta y la salida del sol, ni cuando está tan oscuro que no se ve a 500 pies.","p":"Correcto. Con permiso de motocicleta no se puede ir por autopista ni de noche."},"ref":{"doc":"AZ","page":null}},{"id":"az-080","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a teen breaks the graduated license limits for the third time. What happens?","o":["The limits last 30 days longer","Nothing, just a warning","The teen gets an adult license","The license is suspended for 30 days"],"h1":"A third time is more serious than an extension.","h2":"In Arizona, a third violation of the graduated license limits brings a civil penalty of up to $100 and a 30-day suspension of the license.","p":"Right. A third violation means a 30-day suspension."},"es":{"q":"En Arizona, un adolescente no cumple los límites de su licencia graduada por tercera vez. ¿Qué pasa?","o":["Los límites duran 30 días más","Nada, solo una advertencia","Recibe una licencia de adulto","La licencia se suspende por 30 días"],"h1":"La tercera vez es más grave que una extensión.","h2":"En Arizona, una tercera infracción de los límites de la licencia graduada trae una multa civil de hasta $100 y la suspensión de la licencia por 30 días.","p":"Correcto. Una tercera infracción significa 30 días de suspensión."},"ref":{"doc":"AZ","page":null}},{"id":"az-081","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, a teen is in the first six months of a graduated license. May the teen use spoken turn-by-turn directions from a phone?","o":["Yes, if the teen does not type or touch it while driving","No, never, not even for directions","Yes, and the teen may type the address while driving","Only while driving on a freeway"],"h1":"Hearing directions is allowed, but hands stay off the phone.","h2":"In Arizona, a teen in the first six months of a graduated license may use audible turn-by-turn navigation only if the destination is not typed in and the device is not adjusted by hand while driving.","p":"Right. Spoken directions are okay if the teen does not touch the phone while driving."},"es":{"q":"En Arizona, un adolescente está en los primeros seis meses de su licencia graduada. ¿Puede usar las indicaciones habladas, paso a paso, de un teléfono?","o":["Sí, si no escribe ni toca el teléfono mientras maneja","No, nunca, ni siquiera para direcciones","Sí, y puede escribir la dirección mientras maneja","Solo cuando maneja en autopista"],"h1":"Escuchar las indicaciones está permitido, pero las manos no tocan el teléfono.","h2":"En Arizona, un adolescente en los primeros seis meses de su licencia graduada puede usar un navegador con indicaciones habladas solo si no escribe el destino ni ajusta el aparato con la mano mientras maneja.","p":"Correcto. Las indicaciones habladas están bien si no toca el teléfono mientras maneja."},"ref":{"doc":"AZ","page":null}},{"id":"az-082","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a teen with a graduated license turns 18 before the first six months are over. What happens to the night and passenger limits?","o":["They continue for the full six months","They end on the 18th birthday","They last until age 21","They become stricter"],"h1":"Becoming an adult changes things.","h2":"In Arizona, the night, passenger and phone limits of the graduated license no longer apply starting on the driver's 18th birthday, but any penalty already given must still be completed.","p":"Right. The limits end on the 18th birthday."},"es":{"q":"En Arizona, un adolescente con licencia graduada cumple 18 años antes de terminar los primeros seis meses. ¿Qué pasa con los límites de noche y de pasajeros?","o":["Siguen hasta completar los seis meses","Terminan el día que cumple 18 años","Duran hasta los 21 años","Se vuelven más estrictos"],"h1":"Hacerse adulto cambia las cosas.","h2":"En Arizona, los límites de noche, de pasajeros y de teléfono de la licencia graduada dejan de aplicarse desde el día en que el conductor cumple 18 años, pero cualquier sanción ya impuesta se debe cumplir.","p":"Correcto. Los límites terminan al cumplir 18 años."},"ref":{"doc":"AZ","page":null}},{"id":"az-083","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, a 16-year-old wants a motorcycle license. How long must they first hold a motorcycle instruction permit?","o":["At least 30 days","At least 3 months","At least 6 months","At least 1 year"],"h1":"It is the same time a teen must hold a car permit.","h2":"In Arizona, a person under 18 must hold a class M instruction permit for at least six months, along with other requirements, before getting a motorcycle license or endorsement.","p":"Right. At least 6 months with the permit."},"es":{"q":"En Arizona, un joven de 16 años quiere una licencia de motocicleta. ¿Por cuánto tiempo debe tener primero un permiso de aprendizaje de motocicleta?","o":["Por lo menos 30 días","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 1 año"],"h1":"Es el mismo tiempo que un adolescente debe tener el permiso para auto.","h2":"En Arizona, una persona menor de 18 años debe tener un permiso de aprendizaje clase M por lo menos seis meses, además de otros requisitos, antes de obtener una licencia o un endoso de motocicleta.","p":"Correcto. Por lo menos 6 meses con el permiso."},"ref":{"doc":"AZ","page":null}},{"id":"az-084","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a 19-year-old is convicted of driving with alcohol in the body. How long will the license be suspended?","o":["30 days","90 days","6 months","2 years"],"h1":"It is longer than one year.","h2":"In Arizona, a driver under 21 who is convicted of driving with any alcohol in the body has the license suspended for two years.","p":"Right. Two years."},"es":{"q":"En Arizona, un joven de 19 años es declarado culpable de manejar con alcohol en el cuerpo. ¿Por cuánto tiempo se suspenderá su licencia?","o":["30 días","90 días","6 meses","2 años"],"h1":"Es más de un año.","h2":"En Arizona, a un conductor menor de 21 años declarado culpable de manejar con cualquier cantidad de alcohol en el cuerpo se le suspende la licencia por dos años.","p":"Correcto. Dos años."},"ref":{"doc":"AZ","page":null}},{"id":"az-085","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a 17-year-old driver is found responsible for a second moving violation. What does the MVD do?","o":["Suspends the license for 3 months","Sends a warning letter only","Cancels the license until age 21","Adds one point and nothing more"],"h1":"The first time leads to a class; the second time is stronger.","h2":"In Arizona, a driver under 18 found responsible for a second moving violation has the license suspended for three months; the first one means Traffic Survival School, and a third means six months.","p":"Right. Three months of suspension."},"es":{"q":"En Arizona, un conductor de 17 años es declarado responsable de una segunda infracción de tránsito en movimiento. ¿Qué hace la MVD?","o":["Suspende la licencia por 3 meses","Solo envía una carta de advertencia","Cancela la licencia hasta los 21 años","Agrega un punto y nada más"],"h1":"La primera vez lleva a una clase; la segunda es más fuerte.","h2":"En Arizona, a un conductor menor de 18 años declarado responsable de una segunda infracción en movimiento se le suspende la licencia por tres meses; la primera significa la Traffic Survival School, y una tercera, seis meses.","p":"Correcto. Tres meses de suspensión."},"ref":{"doc":"AZ","page":null}},{"id":"az-086","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a driver is convicted of a first DUI with a blood alcohol level of 0.20 or more. How long does the MVD require an ignition interlock device?","o":["30 days","18 months","3 months","No interlock is required"],"h1":"It is more than one year.","h2":"In Arizona, after a first conviction for DUI at 0.20 or more, the MVD requires an ignition interlock device on any vehicle the person drives for 18 months; with an earlier DUI in the past 84 months, it is 24 months.","p":"Right. 18 months."},"es":{"q":"En Arizona, un conductor es declarado culpable de su primer DUI con un nivel de alcohol en la sangre de 0.20 o más. ¿Por cuánto tiempo exige la MVD un dispositivo de bloqueo de encendido (ignition interlock)?","o":["30 días","18 meses","3 meses","No se exige ningún dispositivo"],"h1":"Es más de un año.","h2":"En Arizona, después de una primera condena por DUI con 0.20 o más, la MVD exige un dispositivo de bloqueo de encendido en cualquier vehículo que la persona maneje por 18 meses; si hubo otro DUI en los 84 meses anteriores, son 24 meses.","p":"Correcto. 18 meses."},"ref":{"doc":"AZ","page":null}},{"id":"az-087","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, a driver's blood alcohol is below 0.08, but drinking has affected the driver a little. Can it still be a DUI?","o":["No, under 0.08 is always legal","Only if there was a crash","Yes, if slightly impaired","Only for drivers over 65"],"h1":"The 0.08 limit is not the only test.","h2":"In Arizona, it is DUI to drive while impaired to the slightest degree by alcohol or drugs, even with a blood alcohol level below 0.08.","p":"Right. Impaired to the slightest degree is DUI in Arizona."},"es":{"q":"En Arizona, el nivel de alcohol en la sangre de un conductor es menor de 0.08, pero el alcohol lo ha afectado un poco. ¿Puede ser DUI de todos modos?","o":["No, menos de 0.08 siempre es legal","Solo si hubo un choque","Sí, si está afectado aunque sea un poco","Solo para conductores mayores de 65 años"],"h1":"El límite de 0.08 no es la única prueba.","h2":"En Arizona, es DUI manejar afectado en el más mínimo grado por alcohol o drogas, aunque el nivel de alcohol en la sangre sea menor de 0.08.","p":"Correcto. Estar afectado en el más mínimo grado es DUI en Arizona."},"ref":{"doc":"AZ","page":null}},{"id":"az-088","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, a person drives under the influence with a 10-year-old child in the car. What is the charge?","o":["A civil traffic ticket","A regular DUI, a misdemeanor","A warning and a class","Aggravated DUI, a felony"],"h1":"Having a young child in the car makes it much more serious.","h2":"In Arizona, DUI with a passenger under 15 in the vehicle is aggravated DUI, a class 6 felony.","p":"Right. It is aggravated DUI, a felony."},"es":{"q":"En Arizona, una persona maneja bajo los efectos del alcohol con un niño de 10 años en el auto. ¿De qué se le acusa?","o":["Una multa civil de tránsito","Un DUI común, un delito menor","Una advertencia y una clase","DUI agravado, un delito grave"],"h1":"Llevar a un niño pequeño en el auto lo hace mucho más grave.","h2":"En Arizona, el DUI con un pasajero menor de 15 años en el vehículo es DUI agravado, un delito grave de clase 6.","p":"Correcto. Es DUI agravado, un delito grave."},"ref":{"doc":"AZ","page":null}},{"id":"az-089","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a driver refuses a DUI test for the second time within 84 months (7 years). How long is the license suspended?","o":["2 years","30 days","90 days","6 months"],"h1":"It is double the suspension for a first refusal.","h2":"In Arizona, a second refusal of a DUI test within 84 months leads to a two-year license suspension.","p":"Right. Two years."},"es":{"q":"En Arizona, un conductor se niega a una prueba de DUI por segunda vez dentro de 84 meses (7 años). ¿Por cuánto tiempo se suspende la licencia?","o":["2 años","30 días","90 días","6 meses"],"h1":"Es el doble de la suspensión por la primera negativa.","h2":"En Arizona, una segunda negativa a la prueba de DUI dentro de 84 meses lleva a la suspensión de la licencia por dos años.","p":"Correcto. Dos años."},"ref":{"doc":"AZ","page":null}},{"id":"az-090","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a driver is convicted of a second DUI within 84 months (7 years). What happens to the driving privilege?","o":["It is suspended for 30 days","It is revoked for one year","Nothing, if no one was hurt","It is limited to work trips for a week"],"h1":"It is a long loss of driving rights.","h2":"In Arizona, a second DUI conviction within 84 months means the driving privilege is revoked for one year, along with jail time and fines.","p":"Right. A one-year revocation."},"es":{"q":"En Arizona, un conductor es declarado culpable de un segundo DUI dentro de 84 meses (7 años). ¿Qué pasa con su privilegio de manejar?","o":["Se suspende por 30 días","Se revoca por un año","Nada, si nadie se lastimó","Se limita a viajes al trabajo por una semana"],"h1":"Es una pérdida larga del derecho a manejar.","h2":"En Arizona, una segunda condena por DUI dentro de 84 meses significa que el privilegio de manejar se revoca por un año, además de cárcel y multas.","p":"Correcto. Una revocación de un año."},"ref":{"doc":"AZ","page":null}},{"id":"az-091","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, how may you show proof of car insurance to an officer?","o":["Only with the original paper policy","Only by having the officer call your insurer","On paper or on your phone","You never need to show proof"],"h1":"Arizona allows a digital option.","h2":"In Arizona, you must keep proof of insurance in the vehicle, and you may show it on a phone or other wireless device; showing it does not give the officer consent to look at anything else on the phone.","p":"Right. Paper or phone both work."},"es":{"q":"En Arizona, ¿cómo puede mostrarle a un policía el comprobante de seguro de su auto?","o":["Solo con la póliza original en papel","Solo si el policía llama a su aseguradora","En papel o en su teléfono","Nunca necesita mostrar un comprobante"],"h1":"Arizona permite una opción digital.","h2":"En Arizona, usted debe llevar un comprobante de seguro en el vehículo y puede mostrarlo en un teléfono u otro aparato inalámbrico; mostrarlo no le da permiso al policía para ver nada más en el teléfono.","p":"Correcto. En papel o en el teléfono, ambos sirven."},"ref":{"doc":"AZ","page":null}},{"id":"az-092","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, a school bus is stopped with its stop signal and flashing lights on, across the road from you. Only a center two-way left-turn lane separates you. What must you do?","o":["Keep going, the turn lane divides the road","Slow down to 15 mph and pass","Honk and pass carefully","Stop, because a turn lane is not a divider"],"h1":"A painted center turn lane does not count as a divided road.","h2":"In Arizona, a two-way left-turn lane does not create separate roadways, so traffic in both directions must stop for a school bus that is stopped with its signal and flashing lights on.","p":"Right. Stop. A center turn lane is not a divider."},"es":{"q":"En Arizona, un autobús escolar está detenido con su señal de alto y sus luces intermitentes encendidas, al otro lado de la calle. Solo los separa un carril central para dar vuelta a la izquierda en ambos sentidos. ¿Qué debe hacer?","o":["Seguir, porque el carril central divide la calle","Bajar a 15 mph y pasar","Tocar la bocina y pasar con cuidado","Detenerse, porque un carril central no es una división"],"h1":"Un carril central pintado no cuenta como una carretera dividida.","h2":"En Arizona, un carril central para dar vuelta a la izquierda en ambos sentidos no crea calzadas separadas, así que el tráfico de los dos sentidos debe detenerse ante un autobús escolar detenido con su señal y sus luces intermitentes encendidas.","p":"Correcto. Deténgase. Un carril central no es una división."},"ref":{"doc":"AZ","page":null}},{"id":"az-093","scope":"AZ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arizona, how close to the driveway entrance of a fire station may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 10 feet","Right up to the edge"],"h1":"It is more than 10 feet.","h2":"In Arizona, you may not park within 20 feet of a fire station driveway, and where signs are posted, not within 75 feet of it on the opposite side of the street.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Arizona, ¿a qué distancia de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["A no menos de 20 pies","A no menos de 5 pies","A no menos de 10 pies","Justo al borde"],"h1":"Son más de 10 pies.","h2":"En Arizona, usted no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos y, donde haya letreros, tampoco a menos de 75 pies en el lado opuesto de la calle.","p":"Correcto. Quédese por lo menos a 20 pies."},"ref":{"doc":"AZ","page":null}},{"id":"az-094","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, what is the civil penalty for a first violation of the move over law?","o":["$50","$275","$1,000","$25"],"h1":"It is a few hundred dollars.","h2":"In Arizona, a first violation of the move over law for stopped vehicles with flashing lights brings a civil penalty of $275; it rises to $500 and then $1,000 for repeat violations within five years.","p":"Right. $275 for a first violation."},"es":{"q":"En Arizona, ¿cuál es la multa civil por una primera infracción de la ley de \"move over\" (cambiarse de carril)?","o":["$50","$275","$1,000","$25"],"h1":"Son unos cientos de dólares.","h2":"En Arizona, una primera infracción de la ley de \"move over\" para vehículos detenidos con luces intermitentes trae una multa civil de $275; sube a $500 y luego a $1,000 si se repite dentro de cinco años.","p":"Correcto. $275 por una primera infracción."},"ref":{"doc":"AZ","page":null}},{"id":"az-095","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, a driver is caught without car insurance for the second time within 36 months. What is the lowest civil penalty?","o":["$100","$250","$750","$5,000"],"h1":"It is higher than the $500 for a first violation.","h2":"In Arizona, a second violation of the insurance law within 36 months brings a civil penalty of at least $750, and the license, registration and plates are suspended for six months.","p":"Right. At least $750 for a second time."},"es":{"q":"En Arizona, a un conductor lo detienen sin seguro de auto por segunda vez en 36 meses. ¿Cuál es la multa civil mínima?","o":["$100","$250","$750","$5,000"],"h1":"Es más alta que los $500 de la primera vez.","h2":"En Arizona, una segunda infracción de la ley de seguro en 36 meses trae una multa civil de al menos $750, y se suspenden la licencia, el registro y las placas por seis meses.","p":"Correcto. Al menos $750 la segunda vez."},"ref":{"doc":"AZ","page":null}},{"id":"az-096","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a driver is caught without car insurance for the third time within 36 months. How long are the license and the vehicle's registration suspended?","o":["One year","One month","Three months","Ten years"],"h1":"Each time, the suspension gets longer: 3 months, then 6 months, then...","h2":"In Arizona, a third insurance violation within 36 months means the driver license, the registration and the license plates are suspended for one year, and the penalty is at least $1,000.","p":"Right. One year for a third time."},"es":{"q":"En Arizona, a un conductor lo detienen sin seguro de auto por tercera vez en 36 meses. ¿Por cuánto tiempo se suspenden la licencia y el registro del vehículo?","o":["Un año","Un mes","Tres meses","Diez años"],"h1":"Cada vez la suspensión es más larga: 3 meses, luego 6 meses, luego...","h2":"En Arizona, una tercera infracción de seguro en 36 meses significa que la licencia de manejo, el registro y las placas se suspenden por un año, y la multa es de al menos $1,000.","p":"Correcto. Un año la tercera vez."},"ref":{"doc":"AZ","page":null}},{"id":"az-097","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, a driver illegally passes a stopped school bus for the second time within 36 months. What can happen to the license?","o":["Nothing; only a warning is given","It is taken away for life","It gets 1 point only","It can be suspended for up to 6 months"],"h1":"The court sends the case to the MVD for a suspension.","h2":"In Arizona, a second school bus violation within 36 months brings a penalty of at least $750, and the court has the MVD suspend the license for up to six months.","p":"Right. Up to 6 months of suspension."},"es":{"q":"En Arizona, un conductor rebasa ilegalmente un autobús escolar detenido por segunda vez en 36 meses. ¿Qué le puede pasar a su licencia?","o":["Nada; solo recibe una advertencia","Se la quitan de por vida","Recibe solo 1 punto","Se la pueden suspender hasta 6 meses"],"h1":"El tribunal manda el caso a la MVD para una suspensión.","h2":"En Arizona, una segunda infracción por el autobús escolar en 36 meses trae una multa de al menos $750, y el tribunal ordena a la MVD suspender la licencia hasta por seis meses.","p":"Correcto. Hasta 6 meses de suspensión."},"ref":{"doc":"AZ","page":null}},{"id":"az-098","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, police stop a driver who has never had a driver license from any state. What happens to the vehicle?","o":["It is impounded for 24 hours","It is impounded for 20 days","It is impounded for 1 year","Nothing happens to the vehicle"],"h1":"It is a little less than three weeks.","h2":"In Arizona, if a person drives without ever having had a license or permit, the officer has the vehicle removed and impounded or immobilized for 20 days.","p":"Right. The vehicle is held for 20 days."},"es":{"q":"En Arizona, la policía detiene a un conductor que nunca ha tenido licencia de manejo de ningún estado. ¿Qué pasa con el vehículo?","o":["Lo retienen por 24 horas","Lo retienen por 20 días","Lo retienen por 1 año","No le pasa nada al vehículo"],"h1":"Es un poco menos de tres semanas.","h2":"En Arizona, si una persona maneja sin haber tenido nunca una licencia o permiso, el policía hace retirar el vehículo y lo retienen o inmovilizan por 20 días.","p":"Correcto. Retienen el vehículo por 20 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-099","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, you buy a used car from a private seller. How soon must you apply for a title in your name?","o":["Within 15 days","Within 6 months","Within 1 year","Only when you sell it"],"h1":"It is about two weeks.","h2":"In Arizona, a buyer must apply to the MVD for a certificate of title within 15 days after buying the vehicle.","p":"Right. Apply for the title within 15 days."},"es":{"q":"En Arizona, usted compra un auto usado a un vendedor particular. ¿En cuánto tiempo debe solicitar el título a su nombre?","o":["Dentro de 15 días","Dentro de 6 meses","Dentro de 1 año","Solo cuando lo venda"],"h1":"Son unas dos semanas.","h2":"En Arizona, el comprador debe solicitar a la MVD el certificado de título dentro de los 15 días después de comprar el vehículo.","p":"Correcto. Solicite el título dentro de 15 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-100","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, what is the civil penalty for driving a vehicle that is not registered for the current year?","o":["$25","$50","$300","$3,000"],"h1":"It is a few hundred dollars.","h2":"In Arizona, driving a vehicle that is not registered or has no current plates brings a $300 civil penalty, but the court dismisses it if the owner registers the vehicle afterward.","p":"Right. $300, dismissed if you register it."},"es":{"q":"En Arizona, ¿cuál es la multa civil por manejar un vehículo que no está registrado para el año actual?","o":["$25","$50","$300","$3,000"],"h1":"Son unos cientos de dólares.","h2":"En Arizona, manejar un vehículo sin registro o sin placas vigentes trae una multa civil de $300, pero el tribunal la anula si el dueño registra el vehículo después.","p":"Correcto. $300, anulada si lo registra."},"ref":{"doc":"AZ","page":null}},{"id":"az-101","scope":"AZ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Arizona, you drive alone in an HOV (carpool) lane during the hours it is limited to two or more people. What is the civil penalty?","o":["$20","$200","$2,000","No penalty, only a warning"],"h1":"It is more than $100 but less than $500.","h2":"In Arizona, driving alone in an HOV lane while it is limited to two or more people brings a $200 civil penalty.","p":"Right. $200."},"es":{"q":"En Arizona, usted maneja solo en un carril HOV (de vehículos compartidos) en las horas en que es solo para dos o más personas. ¿Cuál es la multa civil?","o":["$20","$200","$2,000","No hay multa, solo una advertencia"],"h1":"Es más de $100 pero menos de $500.","h2":"En Arizona, manejar solo en un carril HOV mientras es solo para dos o más personas trae una multa civil de $200.","p":"Correcto. $200."},"ref":{"doc":"AZ","page":null}},{"id":"az-102","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, you park a gas-powered car in a space marked only for charging electric vehicles. What is the lowest civil penalty?","o":["$15","$35","$100","$350"],"h1":"It is a few hundred dollars.","h2":"In Arizona, parking a vehicle that is not an electric vehicle with the special plate or sticker in a space reserved for charging electric vehicles brings a civil penalty of at least $350.","p":"Right. At least $350."},"es":{"q":"En Arizona, usted estaciona un auto de gasolina en un espacio marcado solo para cargar vehículos eléctricos. ¿Cuál es la multa civil mínima?","o":["$15","$35","$100","$350"],"h1":"Son unos cientos de dólares.","h2":"En Arizona, estacionar en un espacio reservado para cargar vehículos eléctricos un vehículo que no es eléctrico con la placa o calcomanía especial trae una multa civil de al menos $350.","p":"Correcto. Al menos $350."},"ref":{"doc":"AZ","page":null}},{"id":"az-103","scope":"AZ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Arizona, you are driving on a narrow mountain road or through a canyon. Where should you keep your vehicle?","o":["In the middle of the road","As far left as you can","As near the right edge as is reasonably possible","On the shoulder at all times"],"h1":"Think about cars coming around a blind curve toward you.","h2":"In Arizona, on mountain highways and in canyons, you must keep your vehicle under control and as near the right edge of the road as is reasonably possible.","p":"Right. Keep under control and near the right edge."},"es":{"q":"En Arizona, usted maneja por una carretera de montaña angosta o por un cañón. ¿Dónde debe mantener su vehículo?","o":["En el centro de la carretera","Lo más a la izquierda posible","Lo más cerca posible del borde derecho, de forma razonable","En el acotamiento todo el tiempo"],"h1":"Piense en los autos que vienen hacia usted en una curva cerrada.","h2":"En Arizona, en carreteras de montaña y en cañones, usted debe mantener el control del vehículo y manejar lo más cerca posible del borde derecho, de forma razonable.","p":"Correcto. Con control y cerca del borde derecho."},"ref":{"doc":"AZ","page":null}},{"id":"az-104","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a person drives on a public road while their license is suspended. What kind of offense is it?","o":["A class 1 misdemeanor (a crime)","A small civil ticket","No offense if the trip is short","Only a written warning"],"h1":"It is more serious than a regular traffic ticket.","h2":"In Arizona, driving while your license is suspended, revoked or canceled is a class 1 misdemeanor, which is a crime.","p":"Right. It is a class 1 misdemeanor."},"es":{"q":"En Arizona, una persona maneja en una vía pública mientras su licencia está suspendida. ¿Qué tipo de infracción es?","o":["Un delito menor de clase 1 (un delito)","Una pequeña multa civil","Ninguna, si el viaje es corto","Solo una advertencia por escrito"],"h1":"Es más grave que una multa de tránsito común.","h2":"En Arizona, manejar con la licencia suspendida, revocada o cancelada es un delito menor de clase 1, es decir, un delito.","p":"Correcto. Es un delito menor de clase 1."},"ref":{"doc":"AZ","page":null}},{"id":"az-105","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, your friend asks to borrow your driver license. What does the law say?","o":["It is fine for one day","It is fine if your friend is over 21","It is fine if you are in the car","Lending it is a crime (class 2 misdemeanor)"],"h1":"A license is only for the person it was issued to.","h2":"In Arizona, lending your driver license to another person, or letting someone else use it, is a class 2 misdemeanor.","p":"Right. Never lend your license."},"es":{"q":"En Arizona, un amigo le pide prestada su licencia de manejo. ¿Qué dice la ley?","o":["Está bien por un día","Está bien si su amigo tiene más de 21 años","Está bien si usted va en el auto","Prestarla es un delito (delito menor de clase 2)"],"h1":"La licencia es solo para la persona a quien se la dieron.","h2":"En Arizona, prestar su licencia de manejo a otra persona, o dejar que otra persona la use, es un delito menor de clase 2.","p":"Correcto. Nunca preste su licencia."},"ref":{"doc":"AZ","page":null}},{"id":"az-106","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a 19-year-old is convicted for the first time of using a fake ID to buy alcohol. For up to how long can the license be suspended?","o":["1 week","6 months","5 years","For life"],"h1":"It is half a year.","h2":"In Arizona, a person under 21 convicted of using a false license for alcohol has the license suspended for up to six months for a first conviction, and up to 12 months after that.","p":"Right. Up to 6 months the first time."},"es":{"q":"En Arizona, una persona de 19 años es condenada por primera vez por usar una identificación falsa para comprar alcohol. ¿Hasta por cuánto tiempo se le puede suspender la licencia?","o":["1 semana","6 meses","5 años","De por vida"],"h1":"Es medio año.","h2":"En Arizona, a una persona menor de 21 años condenada por usar una licencia falsa para obtener alcohol se le suspende la licencia hasta seis meses la primera vez, y hasta 12 meses después.","p":"Correcto. Hasta 6 meses la primera vez."},"ref":{"doc":"AZ","page":null}},{"id":"az-107","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, a driver gets a criminal traffic complaint and does not go to the court date. What does the MVD do?","o":["Adds one point only","Nothing at all","Suspends the license until the person appears","Takes the car away for good"],"h1":"The suspension lasts until the person does what was missed.","h2":"In Arizona, when the court reports that a person failed to appear for a court date on a criminal traffic complaint, the MVD suspends the license until the person appears.","p":"Right. Suspended until the person appears in court."},"es":{"q":"En Arizona, un conductor recibe una denuncia penal de tránsito y no se presenta a la fecha en el tribunal. ¿Qué hace la MVD?","o":["Solo agrega un punto","Nada","Suspende la licencia hasta que la persona se presente","Le quita el auto para siempre"],"h1":"La suspensión dura hasta que la persona haga lo que no hizo.","h2":"En Arizona, cuando el tribunal informa que una persona no se presentó a una fecha de corte por una denuncia penal de tránsito, la MVD suspende la licencia hasta que la persona se presente.","p":"Correcto. Suspendida hasta que se presente."},"ref":{"doc":"AZ","page":null}},{"id":"az-108","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, who can get an identification card from the MVD (an ID that does not allow driving) with no fee?","o":["A person 65 or older","Anyone under 30","Any new resident","A person who owns a car"],"h1":"It is based on age, for older people.","h2":"In Arizona, the fee for a nonoperating identification license does not apply to a person who is 65 or older, among a few other groups.","p":"Right. No fee at 65 or older."},"es":{"q":"En Arizona, ¿quién puede obtener de la MVD una tarjeta de identificación (que no permite manejar) sin pagar?","o":["Una persona de 65 años o más","Cualquiera menor de 30 años","Cualquier residente nuevo","Una persona que tiene auto"],"h1":"Depende de la edad, para personas mayores.","h2":"En Arizona, la tarifa de la tarjeta de identificación que no permite manejar no se cobra a las personas de 65 años o más, entre otros pocos grupos.","p":"Correcto. Sin costo a los 65 años o más."},"ref":{"doc":"AZ","page":null}},{"id":"az-109","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, after a driver's 60th birthday, a regular driver license is renewed for periods of how long?","o":["1 year","2 years","10 years","5 years"],"h1":"It is half of ten.","h2":"In Arizona, after the 60th birthday, a driver license is renewed for periods of five years.","p":"Right. Five years at a time."},"es":{"q":"En Arizona, después de que un conductor cumple 60 años, ¿por cuánto tiempo se renueva cada vez la licencia de manejo común?","o":["1 año","2 años","10 años","5 años"],"h1":"Es la mitad de diez.","h2":"En Arizona, después de cumplir 60 años, la licencia de manejo se renueva por periodos de cinco años.","p":"Correcto. Cinco años cada vez."},"ref":{"doc":"AZ","page":null}},{"id":"az-110","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, a veteran's driver license expired while the veteran was in the military. How long after discharge does the veteran have before renewing?","o":["10 days","6 months","5 years","There is no extra time"],"h1":"It is half a year.","h2":"In Arizona, a veteran whose license expires does not have to renew it until six months after the date of discharge from military service.","p":"Right. Six months after discharge."},"es":{"q":"En Arizona, la licencia de un veterano venció mientras estaba en el ejército. ¿Cuánto tiempo tiene después de su baja para renovarla?","o":["10 días","6 meses","5 años","No hay tiempo extra"],"h1":"Es medio año.","h2":"En Arizona, un veterano cuya licencia vence no tiene que renovarla hasta seis meses después de la fecha de su baja del servicio militar.","p":"Correcto. Seis meses después de la baja."},"ref":{"doc":"AZ","page":null}},{"id":"az-111","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, you receive a new driver license that has a space for your signature. When is the license valid?","o":["Only after 30 days","Only after you pay a second fee","Only after you sign it","Only after a police officer signs it"],"h1":"You must do one simple thing to it yourself.","h2":"In Arizona, a driver license is not valid until the licensee signs it.","p":"Right. It is valid once you sign it."},"es":{"q":"En Arizona, usted recibe una licencia de manejo nueva que tiene un espacio para su firma. ¿Cuándo es válida la licencia?","o":["Solo después de 30 días","Solo después de pagar una segunda tarifa","Solo después de que usted la firme","Solo después de que la firme un policía"],"h1":"Usted mismo debe hacerle algo sencillo.","h2":"En Arizona, la licencia de manejo no es válida hasta que la persona la firma.","p":"Correcto. Es válida cuando usted la firma."},"ref":{"doc":"AZ","page":null}},{"id":"az-112","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, what is shown on the driver license of a person under 21, besides a special color or design?","o":["The year the person turns 21","The person's school grades","The parent's phone number","The number of hours driven"],"h1":"It helps a store clerk check the drinking age quickly.","h2":"In Arizona, a license for a person under the legal drinking age is marked by color, code or design and shows the year the person will reach the legal drinking age of 21.","p":"Right. It shows the year the person turns 21."},"es":{"q":"En Arizona, ¿qué aparece en la licencia de una persona menor de 21 años, además de un color o diseño especial?","o":["El año en que la persona cumple 21","Las calificaciones escolares","El teléfono de los padres","Las horas que ha manejado"],"h1":"Ayuda al empleado de una tienda a revisar la edad para beber.","h2":"En Arizona, la licencia de una persona menor de la edad legal para beber tiene un color, código o diseño especial y muestra el año en que cumplirá 21 años, la edad legal para beber.","p":"Correcto. Muestra el año en que cumple 21."},"ref":{"doc":"AZ","page":null}},{"id":"az-113","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, the MVD will tell you to update your license photo if it has not been updated in how many years?","o":["2 years","4 years","8 years","16 years"],"h1":"It is a long time, more than ten years.","h2":"In Arizona, the MVD must send written notice for a licensee to update the license photo if it has not been updated in the past 16 years.","p":"Right. Every 16 years at most."},"es":{"q":"En Arizona, la MVD le pedirá actualizar la foto de su licencia si no se ha actualizado en ¿cuántos años?","o":["2 años","4 años","8 años","16 años"],"h1":"Es mucho tiempo, más de diez años.","h2":"En Arizona, la MVD debe enviar un aviso por escrito para que la persona actualice la foto de su licencia si no se ha actualizado en los últimos 16 años.","p":"Correcto. Cada 16 años como máximo."},"ref":{"doc":"AZ","page":null}},{"id":"az-114","scope":"AZ","cat":"licensing","sign":null,"c":1,"en":{"q":"In Arizona, you are stopped and cited because you left your license at home. How can you get the citation cleared?","o":["Pay double the fine","Show the court a license that was valid at that time","Take the written test again","Nothing can clear it"],"h1":"The law gives a defense if you really had a license.","h2":"In Arizona, you must carry your license while driving, but if you are cited for not having it, you are not responsible if you show the court or officer's office a legible license that was valid at the time.","p":"Right. Show a license that was valid then."},"es":{"q":"En Arizona, lo detienen y le dan una citación porque dejó su licencia en casa. ¿Cómo puede anular la citación?","o":["Pagando el doble de la multa","Mostrando al tribunal una licencia válida en ese momento","Tomando otra vez el examen escrito","No hay forma de anularla"],"h1":"La ley da una defensa si de verdad tenía licencia.","h2":"En Arizona, usted debe llevar su licencia cuando maneja, pero si le dan una citación por no tenerla, no es responsable si muestra al tribunal o a la oficina del policía una licencia legible que era válida en ese momento.","p":"Correcto. Muestre una licencia que era válida entonces."},"ref":{"doc":"AZ","page":null}},{"id":"az-115","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, a 15-and-a-half-year-old lives with both parents, who are married to each other. Who must sign the teen's permit application?","o":["Both parents and a teacher","Only a police officer","Either the father or the mother","No adult signature is needed"],"h1":"With married parents who both have custody, one signature is enough.","h2":"In Arizona, when both parents are living, married to each other and have custody, either the father or the mother signs the minor's permit or license application.","p":"Right. Either parent may sign."},"es":{"q":"En Arizona, un joven de 15 años y medio vive con sus dos padres, que están casados. ¿Quién debe firmar la solicitud de permiso del joven?","o":["Los dos padres y un maestro","Solo un policía","El padre o la madre, cualquiera de los dos","No se necesita la firma de un adulto"],"h1":"Si los padres están casados y ambos tienen la custodia, basta una firma.","h2":"En Arizona, cuando los dos padres viven, están casados entre sí y tienen la custodia, el padre o la madre firma la solicitud de permiso o licencia del menor.","p":"Correcto. Puede firmar cualquiera de los padres."},"ref":{"doc":"AZ","page":null}},{"id":"az-116","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a parent knowingly lets their 14-year-old, who has no permit, drive on a public road. What is this for the parent?","o":["A crime (class 2 misdemeanor)","Legal, if the parent rides along","Legal, on roads under 35 mph","Only the child gets a ticket"],"h1":"The parent is responsible too.","h2":"In Arizona, a person who knowingly lets a child or anyone under 18 drive on a highway without authorization is guilty of a class 2 misdemeanor.","p":"Right. It is a crime for the parent."},"es":{"q":"En Arizona, un padre deja a sabiendas que su hijo de 14 años, que no tiene permiso, maneje en una vía pública. ¿Qué es esto para el padre?","o":["Un delito (delito menor de clase 2)","Es legal si el padre va con él","Es legal en calles de menos de 35 mph","Solo el hijo recibe una multa"],"h1":"El padre también es responsable.","h2":"En Arizona, una persona que a sabiendas deja que un hijo o cualquier menor de 18 años maneje en una vía pública sin autorización comete un delito menor de clase 2.","p":"Correcto. Es un delito para el padre."},"ref":{"doc":"AZ","page":null}},{"id":"az-117","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, your license says you must wear glasses, but you drive without them. What kind of violation is this?","o":["A felony","A class 1 misdemeanor","No violation at all","A civil traffic violation"],"h1":"This restriction is treated more lightly than other license restrictions.","h2":"In Arizona, breaking most license restrictions is a class 2 misdemeanor, but breaking the restriction to wear corrective lenses is a civil traffic violation.","p":"Right. It is a civil traffic violation."},"es":{"q":"En Arizona, su licencia dice que debe usar lentes, pero usted maneja sin ellos. ¿Qué tipo de infracción es?","o":["Un delito grave","Un delito menor de clase 1","No es ninguna infracción","Una infracción civil de tránsito"],"h1":"Esta restricción se trata con menos dureza que otras restricciones de la licencia.","h2":"En Arizona, no cumplir la mayoría de las restricciones de la licencia es un delito menor de clase 2, pero no cumplir la restricción de usar lentes correctivos es una infracción civil de tránsito.","p":"Correcto. Es una infracción civil de tránsito."},"ref":{"doc":"AZ","page":null}},{"id":"az-118","scope":"AZ","cat":"licensing","sign":null,"c":2,"en":{"q":"In Arizona, a 16-year-old is convicted of stealing a car. How long is the driving privilege suspended?","o":["30 days","90 days","Until the 18th birthday","Until the 25th birthday"],"h1":"It lasts until the teen becomes an adult.","h2":"In Arizona, a person under 18 convicted of motor vehicle theft has the driving privilege suspended, or a license refused, until the 18th birthday.","p":"Right. Until the 18th birthday."},"es":{"q":"En Arizona, un joven de 16 años es condenado por robar un auto. ¿Por cuánto tiempo se suspende su privilegio de manejar?","o":["30 días","90 días","Hasta que cumpla 18 años","Hasta que cumpla 25 años"],"h1":"Dura hasta que el joven sea adulto.","h2":"En Arizona, a una persona menor de 18 años condenada por robo de vehículo se le suspende el privilegio de manejar, o se le niega la licencia, hasta que cumpla 18 años.","p":"Correcto. Hasta los 18 años."},"ref":{"doc":"AZ","page":null}},{"id":"az-119","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, a 17-year-old is convicted of aggravated DUI. How long does the MVD suspend the driving privilege?","o":["3 years","6 months","1 year","10 days"],"h1":"It is longer than the 2 years for a regular underage DUI.","h2":"In Arizona, a person under 18 convicted of aggravated DUI has the driving privilege suspended for three years.","p":"Right. Three years."},"es":{"q":"En Arizona, un joven de 17 años es condenado por DUI agravado. ¿Por cuánto tiempo suspende la MVD su privilegio de manejar?","o":["3 años","6 meses","1 año","10 días"],"h1":"Es más que los 2 años de un DUI común de un menor.","h2":"En Arizona, a una persona menor de 18 años condenada por DUI agravado se le suspende el privilegio de manejar por tres años.","p":"Correcto. Tres años."},"ref":{"doc":"AZ","page":null}},{"id":"az-120","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, a driver fails to yield and causes a crash that seriously injures another person. What kind of offense can this be?","o":["Only a parking ticket","A class 1 misdemeanor (a crime)","No offense if it was an accident","Only a written warning"],"h1":"When a moving violation causes serious harm, it becomes more than a ticket.","h2":"In Arizona, causing serious physical injury or death by certain moving violations, such as failing to yield, is a class 1 misdemeanor, with Traffic Survival School and a license suspension.","p":"Right. It is a class 1 misdemeanor."},"es":{"q":"En Arizona, un conductor no cede el paso y causa un choque que hiere gravemente a otra persona. ¿Qué tipo de infracción puede ser?","o":["Solo una multa de estacionamiento","Un delito menor de clase 1 (un delito)","Ninguna, si fue un accidente","Solo una advertencia por escrito"],"h1":"Cuando una infracción de manejo causa un daño grave, es más que una multa.","h2":"En Arizona, causar lesiones graves o la muerte por ciertas infracciones de manejo, como no ceder el paso, es un delito menor de clase 1, con la escuela Traffic Survival School y suspensión de la licencia.","p":"Correcto. Es un delito menor de clase 1."},"ref":{"doc":"AZ","page":null}},{"id":"az-121","scope":"AZ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Arizona, you reach a school crossing with the school's portable signs out. A person is in the crosswalk. What must you do?","o":["Slow to 25 mph and go around","Honk and keep going","Go if the person is on the far side","Come to a complete stop"],"h1":"Slowing down is not enough here.","h2":"In Arizona, when the school's portable signs are out at a school crossing, every vehicle must come to a complete stop while a person is in the crosswalk.","p":"Right. Stop completely while anyone is in the crosswalk."},"es":{"q":"En Arizona, usted llega a un cruce escolar con los letreros portátiles de la escuela puestos. Hay una persona en el cruce peatonal. ¿Qué debe hacer?","o":["Bajar a 25 mph y rodearla","Tocar la bocina y seguir","Seguir si la persona está del otro lado","Detenerse por completo"],"h1":"Aquí no basta con bajar la velocidad.","h2":"En Arizona, cuando los letreros portátiles de la escuela están puestos en un cruce escolar, todos los vehículos deben detenerse por completo mientras haya una persona en el cruce peatonal.","p":"Correcto. Deténgase por completo mientras haya alguien en el cruce."},"ref":{"doc":"AZ","page":null}},{"id":"az-122","scope":"AZ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Arizona, at a school crossing the signs say the penalty will double. You speed through it. What do you pay?","o":["The fine plus an equal extra amount","Only half the fine","Only the normal fine","Nothing if no child is there"],"h1":"The sign tells you how the penalty changes.","h2":"In Arizona, at a school crossing posted with signs saying the penalty doubles, a violator pays the civil penalty plus an extra assessment equal to it.","p":"Right. The penalty is doubled."},"es":{"q":"En Arizona, en un cruce escolar los letreros dicen que la multa será doble. Usted pasa con exceso de velocidad. ¿Qué paga?","o":["La multa más una cantidad extra igual","Solo la mitad de la multa","Solo la multa normal","Nada si no hay niños"],"h1":"El letrero le dice cómo cambia la multa.","h2":"En Arizona, en un cruce escolar con letreros que dicen que la multa es doble, el infractor paga la multa civil más un cargo extra igual a ella.","p":"Correcto. La multa se duplica."},"ref":{"doc":"AZ","page":null}},{"id":"az-123","scope":"AZ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Arizona, a person on foot wants to cross a street between two intersections that both have working traffic signals. Where may they cross?","o":["Anywhere, if no car is near","Only by running","Only in a marked crosswalk","Anywhere in the middle of the block"],"h1":"Between two signals, there is only one legal place.","h2":"In Arizona, between two nearby intersections with working traffic signals, pedestrians may cross only in a marked crosswalk.","p":"Right. Only in a marked crosswalk."},"es":{"q":"En Arizona, una persona a pie quiere cruzar una calle entre dos intersecciones que tienen semáforos funcionando. ¿Por dónde puede cruzar?","o":["Por cualquier lugar si no hay autos cerca","Solo corriendo","Solo por un cruce peatonal marcado","Por cualquier lugar a mitad de cuadra"],"h1":"Entre dos semáforos hay un solo lugar legal.","h2":"En Arizona, entre dos intersecciones cercanas con semáforos funcionando, los peatones solo pueden cruzar por un cruce peatonal marcado.","p":"Correcto. Solo por un cruce peatonal marcado."},"ref":{"doc":"AZ","page":null}},{"id":"az-124","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, you get a civil traffic ticket while riding a bicycle. Can it be used against your driver license or car insurance?","o":["Yes, it adds points to your license","No, it cannot be used for either","Yes, it doubles your insurance","Only if you are over 18"],"h1":"The law keeps bicycle tickets separate from driving.","h2":"In Arizona, a civil traffic violation while riding a bicycle may not be used to suspend or revoke a driver license, and an insurer may not count it against your car insurance.","p":"Right. It does not count against your license or insurance."},"es":{"q":"En Arizona, usted recibe una multa civil de tránsito mientras anda en bicicleta. ¿Se puede usar contra su licencia de manejo o su seguro de auto?","o":["Sí, agrega puntos a su licencia","No, no se puede usar para ninguno de los dos","Sí, duplica su seguro","Solo si tiene más de 18 años"],"h1":"La ley mantiene las multas en bicicleta separadas del manejo.","h2":"En Arizona, una infracción civil de tránsito en bicicleta no se puede usar para suspender o revocar una licencia de manejo, y la aseguradora no puede contarla contra su seguro de auto.","p":"Correcto. No cuenta contra su licencia ni su seguro."},"ref":{"doc":"AZ","page":null}},{"id":"az-125","scope":"AZ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Arizona, your car breaks down on a freeway outside any city and you leave it. After how long may police have it towed?","o":["After 15 minutes","After 30 minutes","After 7 days","After more than 4 hours"],"h1":"Inside a city the time is 2 hours; outside, it is longer.","h2":"In Arizona, police may tow a vehicle left unattended on a freeway for more than four hours, or more than two hours inside a city.","p":"Right. More than 4 hours outside a city."},"es":{"q":"En Arizona, su auto se descompone en una autopista fuera de cualquier ciudad y usted lo deja. ¿Después de cuánto tiempo la policía puede mandar remolcarlo?","o":["Después de 15 minutos","Después de 30 minutos","Después de 7 días","Después de más de 4 horas"],"h1":"Dentro de una ciudad son 2 horas; fuera, es más.","h2":"En Arizona, la policía puede remolcar un vehículo dejado solo en una autopista por más de cuatro horas, o por más de dos horas dentro de una ciudad.","p":"Correcto. Más de 4 horas fuera de una ciudad."},"ref":{"doc":"AZ","page":null}},{"id":"az-126","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, a police officer sees that your brake light is broken. It is your first time. What can the officer do?","o":["Give you a $500 fine","Take your license","Give only a warning or a notice to repair","Tow your car at once"],"h1":"The first time is not a ticket.","h2":"In Arizona, a first violation for a missing or broken stop lamp is not a civil traffic violation; the officer may give a verbal or written warning or a notice to repair.","p":"Right. Only a warning or repair notice the first time."},"es":{"q":"En Arizona, un policía ve que su luz de freno está rota. Es la primera vez. ¿Qué puede hacer el policía?","o":["Ponerle una multa de $500","Quitarle la licencia","Darle solo una advertencia o un aviso de reparación","Remolcar su auto enseguida"],"h1":"La primera vez no es una multa.","h2":"En Arizona, la primera infracción por una luz de freno que falta o no funciona no es una infracción civil de tránsito; el policía puede darle una advertencia verbal o por escrito o un aviso de reparación.","p":"Correcto. Solo una advertencia o aviso de reparación la primera vez."},"ref":{"doc":"AZ","page":null}},{"id":"az-127","scope":"AZ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Arizona, who must wear a helmet on a motorcycle?","o":["Riders and passengers under 18","Only riders over 65","Every rider of any age","No one; helmets are never required"],"h1":"The law is about age.","h2":"In Arizona, a motorcycle operator or passenger who is under 18 must always wear a protective helmet.","p":"Right. Everyone under 18 must wear a helmet."},"es":{"q":"En Arizona, ¿quién debe usar casco en una motocicleta?","o":["Conductores y pasajeros menores de 18 años","Solo conductores mayores de 65 años","Todos los conductores de cualquier edad","Nadie; el casco nunca es obligatorio"],"h1":"La ley depende de la edad.","h2":"En Arizona, el conductor o pasajero de una motocicleta menor de 18 años siempre debe usar un casco protector.","p":"Correcto. Todos los menores de 18 años deben usar casco."},"ref":{"doc":"AZ","page":null}},{"id":"az-128","scope":"AZ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Arizona, a motorcycle has no windshield. What must the rider wear?","o":["A reflective vest","Leather gloves","Boots above the ankle","Glasses, goggles or a clear face shield"],"h1":"It protects the rider's eyes.","h2":"In Arizona, a motorcycle operator must always wear approved protective glasses, goggles or a clear face shield unless the motorcycle has a protective windshield.","p":"Right. Eye protection is required without a windshield."},"es":{"q":"En Arizona, una motocicleta no tiene parabrisas. ¿Qué debe usar el conductor?","o":["Un chaleco reflectante","Guantes de cuero","Botas por encima del tobillo","Lentes, gafas protectoras o una careta transparente"],"h1":"Protege los ojos del conductor.","h2":"En Arizona, el conductor de una motocicleta siempre debe usar lentes protectores aprobados, gafas o una careta transparente, a menos que la motocicleta tenga un parabrisas protector.","p":"Correcto. Sin parabrisas, se requiere protección para los ojos."},"ref":{"doc":"AZ","page":null}},{"id":"az-129","scope":"AZ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Arizona, fire trucks have stopped on a street to answer a fire alarm. Where may you NOT drive into or park?","o":["Any street in the same city","The block where the fire trucks stopped","Any road within 5 miles","Only the sidewalk next to them"],"h1":"The area is small but close to the trucks.","h2":"In Arizona, unless you are on official business, you may not drive into or park within the block where fire apparatus has stopped to answer a fire alarm.","p":"Right. Stay out of that block."},"es":{"q":"En Arizona, unos camiones de bomberos se detuvieron en una calle para atender una alarma de incendio. ¿Dónde NO puede entrar con su auto ni estacionarse?","o":["En ninguna calle de la misma ciudad","En la cuadra donde se detuvieron los camiones","En ninguna vía a 5 millas","Solo en la acera junto a ellos"],"h1":"La zona es pequeña, pero cerca de los camiones.","h2":"En Arizona, a menos que esté en asuntos oficiales, usted no puede entrar con su vehículo ni estacionarse en la cuadra donde se detuvieron los bomberos para atender una alarma de incendio.","p":"Correcto. No entre en esa cuadra."},"ref":{"doc":"AZ","page":null}},{"id":"az-130","scope":"AZ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Arizona, at what alcohol level is a taxi or rideshare driver who is working guilty of DUI?","o":["0.15 or more","0.10 or more","0.04 or more","0.08 or more"],"h1":"It is half of the limit for most adult drivers.","h2":"In Arizona, a person driving a vehicle for hire or giving rides as a rideshare driver commits DUI with an alcohol level of 0.04 or more.","p":"Right. 0.04 for taxi and rideshare drivers."},"es":{"q":"En Arizona, ¿con qué nivel de alcohol comete DUI un conductor de taxi o de viajes compartidos que está trabajando?","o":["0.15 o más","0.10 o más","0.04 o más","0.08 o más"],"h1":"Es la mitad del límite para la mayoría de los adultos.","h2":"En Arizona, una persona que maneja un vehículo de alquiler con chofer o lleva pasajeros como conductor de viajes compartidos comete DUI con un nivel de alcohol de 0.04 o más.","p":"Correcto. 0.04 para conductores de taxi y viajes compartidos."},"ref":{"doc":"AZ","page":null}},{"id":"az-131","scope":"AZ","cat":"licensing","sign":null,"c":0,"en":{"q":"In Arizona, after a DUI arrest, the MVD sends the driver a notice of license suspension. How long does the driver have to ask for a hearing?","o":["30 days","24 hours","1 year","There is no hearing"],"h1":"It is about one month.","h2":"In Arizona, the MVD must receive a request for a hearing or summary review within 30 days after the date of the notice, or the suspension becomes final.","p":"Right. Ask within 30 days."},"es":{"q":"En Arizona, después de un arresto por DUI, la MVD le envía al conductor un aviso de suspensión de la licencia. ¿Cuánto tiempo tiene para pedir una audiencia?","o":["30 días","24 horas","1 año","No hay audiencia"],"h1":"Es como un mes.","h2":"En Arizona, la MVD debe recibir la solicitud de audiencia o de revisión sumaria dentro de los 30 días después de la fecha del aviso; si no, la suspensión queda firme.","p":"Correcto. Pídala dentro de 30 días."},"ref":{"doc":"AZ","page":null}},{"id":"az-132","scope":"AZ","cat":"licensing","sign":null,"c":3,"en":{"q":"In Arizona, a 17-year-old visitor from another state has a valid license from their home state. May they drive a car in Arizona?","o":["No, they need an Arizona license first","Only with a parent in the car","Only after 30 days","Yes, if they carry their home-state license"],"h1":"Visitors 16 and older are covered by their home license.","h2":"In Arizona, a nonresident who is at least 16 and has a valid license from their home state with them may drive a vehicle that needs a class D license.","p":"Right. A valid home-state license works for visitors."},"es":{"q":"En Arizona, un visitante de 17 años de otro estado tiene una licencia válida de su estado. ¿Puede manejar un auto en Arizona?","o":["No, primero necesita una licencia de Arizona","Solo con uno de sus padres en el auto","Solo después de 30 días","Sí, si lleva la licencia de su estado"],"h1":"Los visitantes de 16 años o más están cubiertos por la licencia de su estado.","h2":"En Arizona, una persona no residente de al menos 16 años que lleva una licencia válida de su estado puede manejar un vehículo que requiere licencia clase D.","p":"Correcto. Una licencia válida de su estado sirve para visitantes."},"ref":{"doc":"AZ","page":null}},{"id":"az-133","scope":"AZ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Arizona, while your car is moving, may you watch a video on your phone?","o":["Yes, if the phone is in a holder","No, only navigation or driving information is allowed","Yes, on the freeway only","Yes, if the sound is off"],"h1":"Maps are allowed; movies are not.","h2":"In Arizona, while the vehicle is moving, a driver may not watch a video or movie on a phone or other device, except data for navigation or driving the vehicle.","p":"Right. No videos while moving."},"es":{"q":"En Arizona, mientras su auto está en movimiento, ¿puede ver un video en su teléfono?","o":["Sí, si el teléfono está en un soporte","No, solo se permite información de navegación o del manejo","Sí, solo en la autopista","Sí, si el sonido está apagado"],"h1":"Los mapas sí; las películas no.","h2":"En Arizona, mientras el vehículo está en movimiento, el conductor no puede ver un video o película en un teléfono u otro aparato, salvo datos de navegación o del manejo del vehículo.","p":"Correcto. Nada de videos mientras maneja."},"ref":{"doc":"AZ","page":null}},{"id":"ca-001","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, what is the youngest age to get a provisional instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday, before you turn 16.","h2":"A California teen can get a provisional instruction permit at 15 and a half, so there is time to practice before the provisional license.","p":"Right. The California permit starts at 15 and a half."},"es":{"q":"En California, ¿cuál es la edad mínima para obtener un permiso de instrucción provisional?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños, antes de cumplir 16.","h2":"En California, un adolescente puede obtener el permiso de instrucción provisional a los 15 años y medio, para tener tiempo de practicar antes de la licencia provisional.","p":"Correcto. El permiso en California empieza a los 15 años y medio."},"zh":{"q":"在 California，最小几岁可以拿到过渡学习驾照（provisional instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了某个生日半年，在你满 16 岁以前。","h2":"California 的青少年 15 岁半就可以拿到过渡学习驾照，这样在拿过渡驾照前有时间练习。","p":"对。California 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở California, tuổi nhỏ nhất để có giấy phép học lái tạm thời (provisional instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật, trước khi bạn 16 tuổi.","h2":"Thiếu niên ở California có thể có giấy phép học lái tạm thời khi 15 tuổi rưỡi, để có thời gian tập lái trước khi có bằng lái tạm thời.","p":"Đúng. Giấy phép học lái ở California bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa California, ano ang pinakabatang edad para makakuha ng provisional instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan, bago ka mag-16.","h2":"Ang isang tinedyer sa California ay makakakuha ng provisional instruction permit sa edad na 15 at kalahati, para may oras magsanay bago ang provisional license.","p":"Tama. Ang permit sa California ay nagsisimula sa 15 at kalahati."},"ar":{"q":"في California، ما أصغر عمر للحصول على تصريح التعلّم المؤقت (provisional instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد عيد ميلاد، قبل أن تبلغ 16.","h2":"يمكن للمراهق في California الحصول على تصريح التعلّم المؤقت في عمر 15 سنة ونصف، ليكون لديه وقت للتدريب قبل الرخصة المؤقتة.","p":"صحيح. يبدأ التصريح في California في عمر 15 سنة ونصف."},"ref":{"doc":"CA","page":3}},{"id":"ca-002","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, how many hours of supervised driving practice must a teen complete before a provisional license?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is a round number, more than forty.","h2":"A California teen must complete 50 hours of supervised practice before the provisional license, because new drivers need a lot of time behind the wheel.","p":"Right. California asks for 50 hours of supervised practice."},"es":{"q":"En California, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia provisional?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es un número redondo, mayor que cuarenta.","h2":"Un adolescente en California debe completar 50 horas de práctica supervisada antes de la licencia provisional, porque un conductor nuevo necesita mucho tiempo al volante.","p":"Correcto. California pide 50 horas de práctica supervisada."},"zh":{"q":"在 California，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶练习？","o":["30 小时","50 小时","40 小时","60 小时"],"h1":"它是一个整数，比四十多。","h2":"California 的青少年拿过渡驾照前必须完成 50 小时有人监督的练习，因为新司机需要很多时间开车。","p":"对。California 要求 50 小时有人监督的练习。"},"vi":{"q":"Ở California, thiếu niên phải tập lái có người giám sát bao nhiêu giờ trước khi có bằng lái tạm thời (provisional license)?","o":["30 giờ","50 giờ","40 giờ","60 giờ"],"h1":"Đó là một số tròn, nhiều hơn bốn mươi.","h2":"Thiếu niên ở California phải tập lái có người giám sát 50 giờ trước khi có bằng lái tạm thời, vì người mới lái cần nhiều thời gian sau tay lái.","p":"Đúng. California yêu cầu 50 giờ tập lái có người giám sát."},"tl":{"q":"Sa California, ilang oras ng pagmamaneho na may gabay ang dapat tapusin ng isang tinedyer bago ang provisional license?","o":["30 oras","50 oras","40 oras","60 oras"],"h1":"Isa itong buong numero, higit sa apatnapu.","h2":"Ang isang tinedyer sa California ay dapat tumapos ng 50 oras ng pagsasanay na may gabay bago ang provisional license, dahil kailangan ng bagong drayber ng maraming oras sa manibela.","p":"Tama. Humihingi ang California ng 50 oras ng pagsasanay na may gabay."},"ar":{"q":"في California، كم ساعة من التدريب على القيادة تحت الإشراف يجب أن يكملها المراهق قبل الرخصة المؤقتة (provisional license)؟","o":["30 ساعة","50 ساعة","40 ساعة","60 ساعة"],"h1":"هو رقم مدوّر، أكثر من أربعين.","h2":"يجب على المراهق في California أن يكمل 50 ساعة من التدريب تحت الإشراف قبل الرخصة المؤقتة، لأن السائق الجديد يحتاج إلى وقت طويل خلف المقود.","p":"صحيح. تطلب California 50 ساعة من التدريب تحت الإشراف."},"ref":{"doc":"CA","page":3}},{"id":"ca-003","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, how many of a teen's supervised practice hours must be driven in darkness?","o":["At least 10 hours","At least 5 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total practice time.","h2":"At least 10 of the 50 practice hours must be in darkness, because night driving needs its own practice.","p":"Right. At least 10 practice hours must be at night."},"es":{"q":"En California, ¿cuántas de las horas de práctica supervisada del adolescente deben ser en la oscuridad?","o":["Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del tiempo total de práctica.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser en la oscuridad, porque manejar de noche necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas de práctica deben ser de noche."},"zh":{"q":"在 California，青少年有人监督的练习时间里，有多少小时必须在天黑时开？","o":["至少 10 小时","至少 5 小时","至少 20 小时","至少 25 小时"],"h1":"它是全部练习时间的五分之一。","h2":"50 小时练习里至少 10 小时必须在天黑时开，因为夜间开车需要单独练习。","p":"对。至少 10 小时练习必须在晚上。"},"vi":{"q":"Ở California, trong số giờ tập lái có người giám sát của thiếu niên, phải lái trong bóng tối bao nhiêu giờ?","o":["Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm tổng số giờ tập.","h2":"Ít nhất 10 trong 50 giờ tập lái phải là lái trong bóng tối, vì lái xe ban đêm cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ tập lái phải là vào ban đêm."},"tl":{"q":"Sa California, ilan sa mga oras ng pagsasanay na may gabay ng isang tinedyer ang dapat gawin sa dilim?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuang oras ng pagsasanay.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay ang dapat gawin sa dilim, dahil kailangan ng sariling pagsasanay ang pagmamaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras ng pagsasanay ang dapat sa gabi."},"ar":{"q":"في California، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الظلام؟","o":["10 ساعات على الأقل","5 ساعات على الأقل","20 ساعة على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع ساعات التدريب.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 50 في الظلام، لأن القيادة في الليل تحتاج إلى تدريب خاص بها.","p":"صحيح. يجب أن تكون 10 ساعات تدريب على الأقل في الليل."},"ref":{"doc":"CA","page":3}},{"id":"ca-004","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, during the first year of a provisional license, when may the teen not drive without a qualified adult?","o":["From 9 p.m. to 6 a.m.","From 10 p.m. to 4 a.m.","From midnight to 6 a.m.","From 11 p.m. to 5 a.m."],"h1":"The limit starts one hour before midnight.","h2":"In the first year, a provisional driver may not drive between 11 p.m. and 5 a.m. without a qualified adult, unless an exception such as school or work applies.","p":"Right. The night limit runs from 11 p.m. to 5 a.m."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿en qué horario no puede manejar el adolescente sin un adulto calificado?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 4 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m."],"h1":"El límite empieza una hora antes de la medianoche.","h2":"En el primer año, el conductor provisional no puede manejar entre las 11 p.m. y las 5 a.m. sin un adulto calificado, salvo excepciones como la escuela o el trabajo.","p":"Correcto. El límite nocturno va de las 11 p.m. a las 5 a.m."},"zh":{"q":"在 California，持过渡驾照的第一年，青少年在什么时间不能在没有合格成年人陪同时开车？","o":["晚上 9 点到早上 6 点","晚上 10 点到凌晨 4 点","午夜到早上 6 点","晚上 11 点到早上 5 点"],"h1":"这个限制在午夜前一小时开始。","h2":"在第一年，持过渡驾照的司机在晚上 11 点到早上 5 点之间，没有合格的成年人陪同不能开车，除非有上学或上班等例外情况。","p":"对。夜间限制是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở California, trong năm đầu có bằng lái tạm thời, khi nào thiếu niên không được lái xe nếu không có người lớn đủ điều kiện đi cùng?","o":["Từ 9 giờ tối đến 6 giờ sáng","Từ 10 giờ tối đến 4 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ trước nửa đêm.","h2":"Trong năm đầu, người có bằng lái tạm thời không được lái xe từ 11 giờ tối đến 5 giờ sáng nếu không có người lớn đủ điều kiện đi cùng, trừ khi có ngoại lệ như đi học hoặc đi làm.","p":"Đúng. Giới hạn ban đêm là từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa California, sa unang taon ng provisional license, kailan hindi puwedeng magmaneho ang tinedyer nang walang kasamang kwalipikadong adulto?","o":["Mula 9 p.m. hanggang 6 a.m.","Mula 10 p.m. hanggang 4 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon isang oras bago maghatinggabi.","h2":"Sa unang taon, ang provisional driver ay hindi puwedeng magmaneho mula 11 p.m. hanggang 5 a.m. nang walang kwalipikadong adulto, maliban kung may eksepsiyon tulad ng paaralan o trabaho.","p":"Tama. Ang limitasyon sa gabi ay mula 11 p.m. hanggang 5 a.m."},"ar":{"q":"في California، في السنة الأولى من الرخصة المؤقتة، متى لا يجوز للمراهق أن يقود بدون شخص بالغ مؤهَّل؟","o":["من 9 مساءً إلى 6 صباحًا","من 10 مساءً إلى 4 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ المنع قبل منتصف الليل بساعة.","h2":"في السنة الأولى، لا يجوز لصاحب الرخصة المؤقتة أن يقود بين 11 مساءً و5 صباحًا بدون شخص بالغ مؤهَّل، إلا في حالة استثناء مثل المدرسة أو العمل.","p":"صحيح. منع القيادة الليلية من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"CA","page":4}},{"id":"ca-005","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, during the first year of a provisional license, the teen may not carry passengers under what age without a qualified adult?","o":["Under 18","Under 20","Under 16","Under 25"],"h1":"The age is just below a new decade of life.","h2":"In the first year, a provisional driver may not carry passengers under 20 unless a qualified adult is in the car, because young passengers raise crash risk.","p":"Right. No passengers under 20 without a qualified adult in the first year."},"es":{"q":"En California, durante el primer año de la licencia provisional, ¿pasajeros menores de qué edad no puede llevar el adolescente sin un adulto calificado?","o":["Menores de 18","Menores de 20","Menores de 16","Menores de 25"],"h1":"La edad está justo antes de una nueva década de vida.","h2":"En el primer año, el conductor provisional no puede llevar pasajeros menores de 20 años sin un adulto calificado en el auto, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Nada de pasajeros menores de 20 sin un adulto calificado en el primer año."},"zh":{"q":"在 California，持过渡驾照的第一年，没有合格成年人陪同时，青少年不能载几岁以下的乘客？","o":["18 岁以下","20 岁以下","16 岁以下","25 岁以下"],"h1":"这个年龄正好在人生新的十年前面一点。","h2":"在第一年，除非车里有合格的成年人，持过渡驾照的司机不能载 20 岁以下的乘客，因为年轻乘客会提高车祸风险。","p":"对。第一年没有合格成年人陪同，不能载 20 岁以下的乘客。"},"vi":{"q":"Ở California, trong năm đầu có bằng lái tạm thời, thiếu niên không được chở hành khách dưới bao nhiêu tuổi nếu không có người lớn đủ điều kiện đi cùng?","o":["Dưới 18 tuổi","Dưới 20 tuổi","Dưới 16 tuổi","Dưới 25 tuổi"],"h1":"Số tuổi này ngay trước một thập niên mới của cuộc đời.","h2":"Trong năm đầu, người có bằng lái tạm thời không được chở hành khách dưới 20 tuổi trừ khi có người lớn đủ điều kiện trong xe, vì hành khách trẻ làm tăng nguy cơ tai nạn.","p":"Đúng. Trong năm đầu, không chở hành khách dưới 20 tuổi nếu không có người lớn đủ điều kiện."},"tl":{"q":"Sa California, sa unang taon ng provisional license, hindi puwedeng magsakay ang tinedyer ng mga pasaherong mas bata sa anong edad kung walang kwalipikadong adulto?","o":["Mas bata sa 18","Mas bata sa 20","Mas bata sa 16","Mas bata sa 25"],"h1":"Ang edad ay bago lang ng isang bagong dekada ng buhay.","h2":"Sa unang taon, ang provisional driver ay hindi puwedeng magsakay ng mga pasaherong mas bata sa 20 maliban kung may kwalipikadong adulto sa kotse, dahil pinapataas ng mga batang pasahero ang panganib ng banggaan.","p":"Tama. Walang pasaherong mas bata sa 20 nang walang kwalipikadong adulto sa unang taon."},"ar":{"q":"في California، في السنة الأولى من الرخصة المؤقتة، لا يجوز للمراهق أن ينقل ركّابًا تحت أي عمر بدون شخص بالغ مؤهَّل؟","o":["تحت 18 سنة","تحت 20 سنة","تحت 16 سنة","تحت 25 سنة"],"h1":"هذا العمر قبل بداية عقد جديد من العمر مباشرة.","h2":"في السنة الأولى، لا يجوز لصاحب الرخصة المؤقتة أن ينقل ركّابًا تحت 20 سنة إلا إذا كان معه في السيارة شخص بالغ مؤهَّل، لأن الركّاب الصغار يزيدون خطر الحوادث.","p":"صحيح. لا ركّاب تحت 20 سنة بدون شخص بالغ مؤهَّل في السنة الأولى."},"ref":{"doc":"CA","page":4}},{"id":"ca-006","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a provisional driver in the first year may drive at night with which person?","o":["Any licensed driver age 18 or older","A friend who has had a license for one year","A licensed driver age 25 or older","Any passenger age 21 or older"],"h1":"The adult must be older than in many other states.","h2":"A provisional driver may drive at night or carry young passengers when a licensed parent or guardian, a licensed driver 25 or older, or a certified instructor is with them.","p":"Right. The adult must be a licensed driver 25 or older, a parent or guardian, or an instructor."},"es":{"q":"En California, ¿con qué persona puede manejar de noche un conductor provisional en su primer año?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo que tiene licencia desde hace un año","Un conductor con licencia de 25 años o más","Cualquier pasajero de 21 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados.","h2":"Un conductor provisional puede manejar de noche o llevar pasajeros jóvenes si va con su padre, madre o tutor con licencia, un conductor con licencia de 25 años o más, o un instructor certificado.","p":"Correcto. El adulto debe ser un conductor con licencia de 25 años o más, un padre o tutor, o un instructor."},"zh":{"q":"在 California，持过渡驾照第一年的司机，和下面哪一个人一起时可以在晚上开车？","o":["任何 18 岁或以上、有驾照的司机","有驾照满一年的朋友","25 岁或以上、有驾照的司机","任何 21 岁或以上的乘客"],"h1":"这个成年人的年龄要求比很多其他州高。","h2":"当有驾照的父母或监护人、25 岁或以上有驾照的司机，或有证书的驾驶教练同车时，持过渡驾照的司机可以在晚上开车，或载年轻乘客。","p":"对。这个成年人必须是 25 岁或以上有驾照的司机、父母或监护人，或教练。"},"vi":{"q":"Ở California, người có bằng lái tạm thời trong năm đầu được lái xe ban đêm với người nào?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Một người bạn đã có bằng lái một năm","Một người có bằng lái từ 25 tuổi trở lên","Bất kỳ hành khách nào từ 21 tuổi trở lên"],"h1":"Người lớn phải lớn tuổi hơn so với nhiều tiểu bang khác.","h2":"Người có bằng lái tạm thời được lái xe ban đêm hoặc chở hành khách trẻ khi có cha mẹ hoặc người giám hộ có bằng lái, một người có bằng lái từ 25 tuổi trở lên, hoặc một huấn luyện viên có chứng nhận đi cùng.","p":"Đúng. Người lớn phải là người có bằng lái từ 25 tuổi trở lên, cha mẹ hoặc người giám hộ, hoặc một huấn luyện viên."},"tl":{"q":"Sa California, kasama ang sinong tao puwedeng magmaneho sa gabi ang isang provisional driver sa unang taon?","o":["Sinumang may lisensya na edad 18 pataas","Isang kaibigang may lisensya nang isang taon","Isang drayber na may lisensya na edad 25 pataas","Sinumang pasahero na edad 21 pataas"],"h1":"Mas matanda ang adulto kaysa sa maraming ibang estado.","h2":"Ang provisional driver ay puwedeng magmaneho sa gabi o magsakay ng mga batang pasahero kapag kasama ang magulang o tagapag-alaga na may lisensya, isang drayber na may lisensya na edad 25 pataas, o isang sertipikadong instruktor.","p":"Tama. Ang adulto ay dapat drayber na may lisensya na 25 pataas, magulang o tagapag-alaga, o instruktor."},"ar":{"q":"في California، مع من يجوز لصاحب الرخصة المؤقتة في السنة الأولى أن يقود في الليل؟","o":["أي سائق مرخَّص عمره 18 سنة أو أكثر","صديق لديه رخصة منذ سنة واحدة","سائق مرخَّص عمره 25 سنة أو أكثر","أي راكب عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون البالغ أكبر سنًّا مما في ولايات كثيرة أخرى.","h2":"يجوز لصاحب الرخصة المؤقتة أن يقود في الليل أو ينقل ركّابًا صغارًا إذا كان معه أحد الوالدين أو الوصي المرخَّص، أو سائق مرخَّص عمره 25 سنة أو أكثر، أو مدرّب معتمَد.","p":"صحيح. يجب أن يكون البالغ سائقًا مرخَّصًا عمره 25 سنة أو أكثر، أو أحد الوالدين أو الوصي، أو مدرّبًا."},"ref":{"doc":"CA","page":4}},{"id":"ca-007","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, may a driver under 18 talk on a phone with a hands-free device while driving?","o":["No, not even hands-free","Yes, if the phone is mounted","Yes, on the freeway only","Yes, if the call is short"],"h1":"The rule for young drivers is stricter than the rule for adults.","h2":"A California driver under 18 may not use a phone while driving, even hands-free, except to call for help in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En California, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["No, ni siquiera con manos libres","Sí, si el teléfono está montado","Sí, solo en la autopista","Sí, si la llamada es corta"],"h1":"La regla para los conductores jóvenes es más estricta que para los adultos.","h2":"En California, un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"zh":{"q":"在 California，18 岁以下的司机开车时可以用免持设备打电话吗？","o":["不可以，免持也不行","可以，如果手机装在支架上","可以，只在高速公路上","可以，如果电话很短"],"h1":"对年轻司机的规定比对成年人更严。","h2":"California 18 岁以下的司机开车时不能用手机，即使是免持也不行，紧急情况下打电话求助除外。","p":"对。18 岁以下的司机不能用手机，免持也不行。"},"vi":{"q":"Ở California, người lái xe dưới 18 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay khi lái xe không?","o":["Không, kể cả rảnh tay","Có, nếu điện thoại được gắn cố định","Có, chỉ trên xa lộ","Có, nếu cuộc gọi ngắn"],"h1":"Luật cho người lái trẻ nghiêm hơn luật cho người lớn.","h2":"Người lái xe dưới 18 tuổi ở California không được dùng điện thoại khi lái xe, kể cả rảnh tay, trừ khi gọi cấp cứu trong trường hợp khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa California, puwede bang makipag-usap sa telepono gamit ang hands-free na device ang drayber na wala pang 18 habang nagmamaneho?","o":["Hindi, kahit hands-free","Oo, kung nakakabit ang telepono","Oo, sa freeway lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mga batang drayber kaysa sa mga adulto.","h2":"Ang drayber sa California na wala pang 18 ay hindi puwedeng gumamit ng telepono habang nagmamaneho, kahit hands-free, maliban sa pagtawag ng tulong sa emergency.","p":"Tama. Ang mga drayber na wala pang 18 ay hindi puwedeng gumamit ng telepono, kahit hands-free."},"ar":{"q":"في California، هل يجوز للسائق تحت 18 سنة أن يتكلم في الهاتف بجهاز من غير استخدام اليدين أثناء القيادة؟","o":["لا، ولا حتى بدون استخدام اليدين","نعم، إذا كان الهاتف مثبّتًا","نعم، على الطريق السريع فقط","نعم، إذا كانت المكالمة قصيرة"],"h1":"القاعدة للسائقين الصغار أشدّ من القاعدة للبالغين.","h2":"لا يجوز للسائق في California تحت 18 سنة أن يستخدم الهاتف أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا لطلب المساعدة في حالة طوارئ.","p":"صحيح. لا يجوز للسائقين تحت 18 سنة استخدام الهاتف، ولا حتى بدون استخدام اليدين."},"ref":{"doc":"CA","page":71}},{"id":"ca-008","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, when may a driver under 18 use a phone while driving?","o":["To answer a parent's call","To check a map at a red light","To send a short text","To call police, fire or a doctor in an emergency"],"h1":"Think of a call that could save a life.","h2":"A driver under 18 may use a phone only in an emergency, to reach police, the fire department or a health care provider.","p":"Right. Only an emergency call is allowed for drivers under 18."},"es":{"q":"En California, ¿cuándo puede un conductor menor de 18 años usar el teléfono mientras maneja?","o":["Para contestar una llamada de su padre","Para ver un mapa en un semáforo rojo","Para enviar un mensaje corto","Para llamar a la policía, los bomberos o un médico en una emergencia"],"h1":"Piense en una llamada que podría salvar una vida.","h2":"Un conductor menor de 18 años solo puede usar el teléfono en una emergencia, para comunicarse con la policía, los bomberos o un proveedor de salud.","p":"Correcto. Los menores de 18 solo pueden hacer llamadas de emergencia."},"zh":{"q":"在 California，18 岁以下的司机开车时什么时候可以用手机？","o":["接父母的电话","在红灯时看地图","发一条短的短信","紧急情况下打给警察、消防或医生"],"h1":"想一想可以救命的电话。","h2":"18 岁以下的司机只有在紧急情况下，为了联系警察、消防局或医疗人员，才可以用手机。","p":"对。18 岁以下的司机只可以打紧急电话。"},"vi":{"q":"Ở California, khi nào người lái xe dưới 18 tuổi được dùng điện thoại khi lái xe?","o":["Để trả lời cuộc gọi của cha mẹ","Để xem bản đồ khi dừng đèn đỏ","Để gửi một tin nhắn ngắn","Để gọi cảnh sát, cứu hỏa hoặc bác sĩ khi khẩn cấp"],"h1":"Hãy nghĩ đến một cuộc gọi có thể cứu một mạng người.","h2":"Người lái xe dưới 18 tuổi chỉ được dùng điện thoại khi khẩn cấp, để gọi cảnh sát, sở cứu hỏa hoặc nhân viên y tế.","p":"Đúng. Người lái dưới 18 tuổi chỉ được gọi khẩn cấp."},"tl":{"q":"Sa California, kailan puwedeng gumamit ng telepono ang drayber na wala pang 18 habang nagmamaneho?","o":["Para sagutin ang tawag ng magulang","Para tumingin ng mapa sa pulang ilaw","Para magpadala ng maikling text","Para tumawag sa pulis, bumbero o doktor sa emergency"],"h1":"Isipin ang tawag na puwedeng magligtas ng buhay.","h2":"Ang drayber na wala pang 18 ay puwedeng gumamit ng telepono sa emergency lang, para tumawag sa pulis, sa bumbero o sa health care provider.","p":"Tama. Tawag sa emergency lang ang puwede para sa mga drayber na wala pang 18."},"ar":{"q":"في California، متى يجوز للسائق تحت 18 سنة أن يستخدم الهاتف أثناء القيادة؟","o":["للرد على مكالمة من أحد الوالدين","للنظر في الخريطة عند الإشارة الحمراء","لإرسال رسالة قصيرة","للاتصال بالشرطة أو الإطفاء أو الطبيب في حالة طوارئ"],"h1":"فكّر في مكالمة يمكن أن تنقذ حياة.","h2":"يجوز للسائق تحت 18 سنة أن يستخدم الهاتف في حالة طوارئ فقط، للاتصال بالشرطة أو الإطفاء أو مقدّم رعاية صحية.","p":"صحيح. مكالمة الطوارئ فقط مسموحة للسائقين تحت 18 سنة."},"ref":{"doc":"CA","page":71}},{"id":"ca-009","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a driver under 21 can lose their license with a blood alcohol level of what?","o":["0.05 percent or more","0.01 percent or more","0.08 percent or more","0.04 percent or more"],"h1":"It is the smallest amount a test can measure.","h2":"California has a zero tolerance rule: a driver under 21 with 0.01 percent or more is breaking the law and can lose the license for one year.","p":"Right. For drivers under 21, the limit is 0.01 percent."},"es":{"q":"En California, un conductor menor de 21 años puede perder la licencia con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.05 por ciento o más","0.01 por ciento o más","0.08 por ciento o más","0.04 por ciento o más"],"h1":"Es la cantidad más pequeña que una prueba puede medir.","h2":"California tiene una regla de tolerancia cero: un conductor menor de 21 años con 0.01 por ciento o más viola la ley y puede perder la licencia por un año.","p":"Correcto. Para menores de 21, el límite es 0.01 por ciento."},"zh":{"q":"在 California，21 岁以下的司机血液酒精浓度达到多少，可能会失去驾照？","o":["0.05% 或更高","0.01% 或更高","0.08% 或更高","0.04% 或更高"],"h1":"它是检测能测出的最小量。","h2":"California 有零容忍规定：21 岁以下的司机酒精浓度达到 0.01% 或更高就是违法，可能失去驾照一年。","p":"对。21 岁以下的司机，限制是 0.01%。"},"vi":{"q":"Ở California, người lái xe dưới 21 tuổi có thể bị mất bằng lái khi nồng độ cồn trong máu là bao nhiêu?","o":["0.05 phần trăm trở lên","0.01 phần trăm trở lên","0.08 phần trăm trở lên","0.04 phần trăm trở lên"],"h1":"Đó là lượng nhỏ nhất mà máy đo có thể đo được.","h2":"California có luật không khoan nhượng: người lái xe dưới 21 tuổi có nồng độ 0.01 phần trăm trở lên là vi phạm luật và có thể bị mất bằng lái một năm.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.01 phần trăm."},"tl":{"q":"Sa California, ang drayber na wala pang 21 ay puwedeng mawalan ng lisensya kung ang alkohol sa dugo ay ilan?","o":["0.05 porsiyento o higit pa","0.01 porsiyento o higit pa","0.08 porsiyento o higit pa","0.04 porsiyento o higit pa"],"h1":"Ito ang pinakamaliit na dami na kayang sukatin ng test.","h2":"May zero tolerance rule ang California: ang drayber na wala pang 21 na may 0.01 porsiyento o higit pa ay lumalabag sa batas at puwedeng mawalan ng lisensya nang isang taon.","p":"Tama. Para sa mga drayber na wala pang 21, ang limitasyon ay 0.01 porsiyento."},"ar":{"q":"في California، يمكن أن يفقد السائق تحت 21 سنة رخصته إذا كانت نسبة الكحول في الدم كم؟","o":["0.05 بالمئة أو أكثر","0.01 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.04 بالمئة أو أكثر"],"h1":"هي أصغر كمية يستطيع الفحص أن يقيسها.","h2":"في California قاعدة عدم التسامح: السائق تحت 21 سنة الذي عنده 0.01 بالمئة أو أكثر يخالف القانون ويمكن أن يفقد رخصته لمدة سنة.","p":"صحيح. للسائقين تحت 21 سنة، الحدّ هو 0.01 بالمئة."},"ref":{"doc":"CA","page":73}},{"id":"ca-010","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, a driver under 21 can be charged with a crime at what blood alcohol level, even below the adult limit?","o":["0.02 percent","0.03 percent","0.05 percent","0.07 percent"],"h1":"It is a little more than half of the adult limit of 0.08.","h2":"A California driver under 21 can be charged at 0.05 percent, which is lower than the 0.08 percent limit for adults.","p":"Right. Under 21, a charge can start at 0.05 percent."},"es":{"q":"En California, ¿con qué nivel de alcohol en la sangre se puede acusar de un delito a un conductor menor de 21 años, aunque esté por debajo del límite de adultos?","o":["0.02 por ciento","0.03 por ciento","0.05 por ciento","0.07 por ciento"],"h1":"Es un poco más de la mitad del límite de adultos de 0.08.","h2":"En California, a un conductor menor de 21 años se le puede acusar con 0.05 por ciento, que es menos que el límite de 0.08 por ciento para adultos.","p":"Correcto. Para menores de 21, la acusación puede empezar en 0.05 por ciento."},"zh":{"q":"在 California，21 岁以下的司机血液酒精浓度达到多少，即使低于成年人的限制，也可能被控犯罪？","o":["0.02%","0.03%","0.05%","0.07%"],"h1":"它比成年人 0.08 的限制的一半多一点。","h2":"California 21 岁以下的司机在 0.05% 时就可能被起诉，这比成年人 0.08% 的限制低。","p":"对。21 岁以下，0.05% 就可能被起诉。"},"vi":{"q":"Ở California, người lái xe dưới 21 tuổi có thể bị buộc tội hình sự ở nồng độ cồn trong máu nào, dù thấp hơn giới hạn của người lớn?","o":["0.02 phần trăm","0.03 phần trăm","0.05 phần trăm","0.07 phần trăm"],"h1":"Đó là hơn một nửa giới hạn 0.08 của người lớn một chút.","h2":"Người lái xe dưới 21 tuổi ở California có thể bị buộc tội ở mức 0.05 phần trăm, thấp hơn giới hạn 0.08 phần trăm của người lớn.","p":"Đúng. Dưới 21 tuổi, có thể bị buộc tội từ 0.05 phần trăm."},"tl":{"q":"Sa California, sa anong antas ng alkohol sa dugo puwedeng kasuhan ng krimen ang drayber na wala pang 21, kahit mas mababa sa limitasyon ng adulto?","o":["0.02 porsiyento","0.03 porsiyento","0.05 porsiyento","0.07 porsiyento"],"h1":"Medyo higit ito sa kalahati ng 0.08 na limitasyon ng adulto.","h2":"Ang drayber sa California na wala pang 21 ay puwedeng kasuhan sa 0.05 porsiyento, na mas mababa sa 0.08 porsiyento na limitasyon para sa mga adulto.","p":"Tama. Kung wala pang 21, puwedeng magsimula ang kaso sa 0.05 porsiyento."},"ar":{"q":"في California، عند أي نسبة كحول في الدم يمكن اتهام السائق تحت 21 سنة بجريمة، حتى لو كانت أقل من حدّ البالغين؟","o":["0.02 بالمئة","0.03 بالمئة","0.05 بالمئة","0.07 بالمئة"],"h1":"هي أكثر قليلًا من نصف حدّ البالغين 0.08.","h2":"يمكن اتهام السائق في California تحت 21 سنة عند 0.05 بالمئة، وهذا أقل من حدّ البالغين 0.08 بالمئة.","p":"صحيح. تحت 21 سنة، يمكن أن يبدأ الاتهام عند 0.05 بالمئة."},"ref":{"doc":"CA","page":75}},{"id":"ca-011","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, a school bus is stopped with red lights flashing on the other side of a highway with two or more lanes in each direction. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","Honk and pass slowly","You do not have to stop"],"h1":"The rule changes when the road is wide enough on each side.","h2":"On a divided or multiple-lane highway with two or more lanes each way, you do not have to stop for a school bus on the other side, but you should still drive with care.","p":"Right. Traffic on the other side of a multiple-lane highway does not have to stop."},"es":{"q":"En California, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera con dos o más carriles en cada dirección. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","Tocar la bocina y pasar despacio","No tiene que detenerse"],"h1":"La regla cambia cuando la carretera es bastante ancha de cada lado.","h2":"En una carretera dividida o de varios carriles, con dos o más carriles en cada dirección, usted no tiene que detenerse por un autobús escolar del otro lado, pero debe manejar con cuidado.","p":"Correcto. El tráfico del otro lado de una carretera de varios carriles no tiene que detenerse."},"zh":{"q":"在 California，一辆校车停在每个方向有两条或更多车道的公路对面，红灯在闪。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 开过去","按喇叭，慢慢开过去","你不必停车"],"h1":"当每一边的道路够宽时，规定就不一样。","h2":"在每个方向有两条或更多车道的分隔公路或多车道公路上，你不必为对面的校车停车，但仍然要小心开车。","p":"对。多车道公路对面的车不必停车。"},"vi":{"q":"Ở California, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của xa lộ có hai làn trở lên mỗi chiều. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Dừng lại, rồi vượt qua với tốc độ 10 mph","Bấm còi và vượt qua chậm","Bạn không phải dừng lại"],"h1":"Luật thay đổi khi mỗi bên đường đủ rộng.","h2":"Trên xa lộ có dải phân cách hoặc nhiều làn với hai làn trở lên mỗi chiều, bạn không phải dừng lại cho xe buýt trường học ở phía bên kia, nhưng vẫn phải lái xe cẩn thận.","p":"Đúng. Xe ở phía bên kia của xa lộ nhiều làn không phải dừng lại."},"tl":{"q":"Sa California, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng highway na may dalawa o higit pang lane sa bawat direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Huminto, saka lumampas sa 10 mph","Bumusina at lumampas nang dahan-dahan","Hindi mo kailangang huminto"],"h1":"Nagbabago ang patakaran kapag sapat ang lapad ng daan sa bawat panig.","h2":"Sa divided o multiple-lane na highway na may dalawa o higit pang lane bawat direksyon, hindi mo kailangang huminto para sa school bus sa kabilang panig, pero dapat ka pa ring magmaneho nang maingat.","p":"Tama. Ang trapiko sa kabilang panig ng multiple-lane na highway ay hindi kailangang huminto."},"ar":{"q":"في California، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجهة الأخرى من طريق سريع فيه حارتان أو أكثر في كل اتجاه. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء","تتوقف، ثم تمرّ بسرعة 10 mph","تطلق البوق وتمرّ ببطء","ليس عليك أن تتوقف"],"h1":"تتغير القاعدة عندما يكون الطريق عريضًا بما يكفي في كل جهة.","h2":"على طريق سريع مقسوم أو متعدد الحارات فيه حارتان أو أكثر في كل اتجاه، ليس عليك أن تتوقف لحافلة مدرسية على الجهة الأخرى، لكن يجب أن تقود بحذر.","p":"صحيح. السير على الجهة الأخرى من طريق متعدد الحارات ليس عليه أن يتوقف."},"ref":{"doc":"CA","page":51}},{"id":"ca-012","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, a school bus with flashing red lights is stopped across a two-lane road with one lane each way. You are coming toward it. What must you do?","o":["Stop and wait until the lights stop flashing","Slow down and pass with care","Keep going, since you are on the other side","Stop only if children are in the road"],"h1":"One lane each way is not wide enough for the exception.","h2":"On a road with only one lane in each direction, drivers from both directions must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, traffic from both directions must stop."},"es":{"q":"En California, un autobús escolar con luces rojas intermitentes está detenido en una carretera de dos carriles, uno en cada dirección. Usted viene hacia él. ¿Qué debe hacer?","o":["Detenerse y esperar hasta que las luces dejen de parpadear","Reducir la velocidad y pasar con cuidado","Seguir, porque usted está del otro lado","Detenerse solo si hay niños en la calle"],"h1":"Un carril en cada dirección no es suficiente para la excepción.","h2":"En una carretera con un solo carril en cada dirección, los conductores de ambos sentidos deben detenerse ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En una carretera de dos carriles, el tráfico de ambos sentidos debe detenerse."},"zh":{"q":"在 California，一辆红灯在闪的校车停在每个方向只有一条车道的双车道道路对面。你正朝它开过去。你必须怎么做？","o":["停车，等到灯不再闪","减速，小心地开过去","继续开，因为你在对面","只有孩子在路上时才停车"],"h1":"每个方向一条车道，不够宽，不能用这个例外。","h2":"在每个方向只有一条车道的道路上，两个方向的司机都必须为红灯闪烁的校车停车，并等到灯熄灭。","p":"对。在双车道道路上，两个方向的车都必须停车。"},"vi":{"q":"Ở California, một xe buýt trường học nháy đèn đỏ đang dừng trên đường hai làn, mỗi chiều một làn. Bạn đang chạy về phía nó. Bạn phải làm gì?","o":["Dừng lại và chờ cho đến khi đèn ngừng nháy","Chạy chậm lại và vượt qua cẩn thận","Cứ chạy tiếp, vì bạn ở phía bên kia","Chỉ dừng lại nếu có trẻ em trên đường"],"h1":"Mỗi chiều một làn thì không đủ rộng để có ngoại lệ.","h2":"Trên đường chỉ có một làn mỗi chiều, xe từ cả hai chiều phải dừng lại khi xe buýt trường học nháy đèn đỏ và chờ cho đến khi đèn tắt.","p":"Đúng. Trên đường hai làn, xe từ cả hai chiều phải dừng lại."},"tl":{"q":"Sa California, may school bus na kumikislap ang pulang ilaw at nakahinto sa two-lane na daan na may isang lane bawat direksyon. Papalapit ka rito. Ano ang dapat mong gawin?","o":["Huminto at maghintay hanggang tumigil ang pagkislap ng mga ilaw","Bumagal at lumampas nang maingat","Tuloy lang, dahil nasa kabilang panig ka","Huminto lang kung may mga bata sa daan"],"h1":"Ang isang lane bawat direksyon ay hindi sapat ang lapad para sa eksepsiyon.","h2":"Sa daan na may isang lane lang sa bawat direksyon, ang mga drayber mula sa dalawang direksyon ay dapat huminto para sa school bus na kumikislap ang pulang ilaw at maghintay hanggang mamatay ang mga ilaw.","p":"Tama. Sa two-lane na daan, dapat huminto ang trapiko mula sa dalawang direksyon."},"ar":{"q":"في California، حافلة مدرسية أضواؤها الحمراء تومض ومتوقفة على طريق بحارتين، حارة واحدة في كل اتجاه. أنت قادم نحوها. ماذا يجب أن تفعل؟","o":["تتوقف وتنتظر حتى يتوقف وميض الأضواء","تخفّف السرعة وتمرّ بحذر","تستمر في السير لأنك على الجهة الأخرى","تتوقف فقط إذا كان هناك أطفال في الطريق"],"h1":"حارة واحدة في كل اتجاه ليست عريضة بما يكفي للاستثناء.","h2":"على طريق فيه حارة واحدة فقط في كل اتجاه، يجب على السائقين من الاتجاهين أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض، وأن ينتظروا حتى تنطفئ الأضواء.","p":"صحيح. على طريق بحارتين، يجب أن يتوقف السير من الاتجاهين."},"ref":{"doc":"CA","page":51}},{"id":"ca-013","scope":"CA","cat":"signals","sign":null,"c":1,"en":{"q":"In California, may you turn right at a steady red light?","o":["No, never at a red light","Yes, after a full stop, unless a sign says no","Yes, without stopping if no cars come","Only between 9 a.m. and 5 p.m."],"h1":"You must do one thing first, and a sign can forbid it.","h2":"In California you may turn right on a steady red light after a full stop, unless a sign forbids it, and you must yield to people walking and to close traffic.","p":"Right. Stop fully first, then turn right if no sign forbids it."},"es":{"q":"En California, ¿puede usted girar a la derecha con la luz roja fija?","o":["No, nunca con luz roja","Sí, después de detenerse por completo, si no hay un letrero que lo prohíba","Sí, sin detenerse si no vienen autos","Solo entre las 9 a.m. y las 5 p.m."],"h1":"Debe hacer algo primero, y un letrero puede prohibirlo.","h2":"En California usted puede girar a la derecha con la luz roja fija después de detenerse por completo, si no hay un letrero que lo prohíba, y debe ceder el paso a los peatones y al tráfico cercano.","p":"Correcto. Deténgase por completo y luego gire a la derecha si ningún letrero lo prohíbe."},"zh":{"q":"在 California，持续亮着红灯时，你可以右转吗？","o":["不可以，红灯时永远不可以","可以，完全停车后，除非有标志禁止","可以，没有车来就不用停车","只在早上 9 点到下午 5 点之间"],"h1":"你必须先做一件事，而且标志可以禁止它。","h2":"在 California，持续亮着红灯时，你完全停车后可以右转，除非有标志禁止，而且你必须让行人和很近的车先走。","p":"对。先完全停车，没有标志禁止就可以右转。"},"vi":{"q":"Ở California, bạn có được rẽ phải khi đèn đỏ sáng liên tục không?","o":["Không, không bao giờ khi đèn đỏ","Có, sau khi dừng hẳn, trừ khi có biển cấm","Có, không cần dừng nếu không có xe","Chỉ từ 9 giờ sáng đến 5 giờ chiều"],"h1":"Bạn phải làm một việc trước, và biển báo có thể cấm việc này.","h2":"Ở California bạn được rẽ phải khi đèn đỏ sáng liên tục sau khi dừng hẳn, trừ khi có biển cấm, và bạn phải nhường cho người đi bộ và xe đang đến gần.","p":"Đúng. Dừng hẳn trước, rồi rẽ phải nếu không có biển cấm."},"tl":{"q":"Sa California, puwede ka bang kumanan sa tuloy-tuloy na pulang ilaw?","o":["Hindi, hindi kailanman sa pulang ilaw","Oo, pagkatapos ng buong paghinto, maliban kung may karatulang nagbabawal","Oo, nang hindi humihinto kung walang kotse","Mula 9 a.m. hanggang 5 p.m. lang"],"h1":"May isang bagay kang dapat gawin muna, at puwede itong ipagbawal ng karatula.","h2":"Sa California puwede kang kumanan sa tuloy-tuloy na pulang ilaw pagkatapos ng buong paghinto, maliban kung may karatulang nagbabawal, at dapat kang magbigay-daan sa mga naglalakad at sa malapit na trapiko.","p":"Tama. Huminto nang buo muna, saka kumanan kung walang karatulang nagbabawal."},"ar":{"q":"في California، هل يجوز لك أن تنعطف يمينًا عند إشارة حمراء ثابتة؟","o":["لا، أبدًا عند الإشارة الحمراء","نعم، بعد توقف كامل، إلا إذا منعت ذلك لافتة","نعم، بدون توقف إذا لم تأتِ سيارات","فقط بين 9 صباحًا و5 مساءً"],"h1":"يجب أن تفعل شيئًا واحدًا أولًا، ويمكن أن تمنع ذلك لافتة.","h2":"في California يجوز لك أن تنعطف يمينًا عند إشارة حمراء ثابتة بعد توقف كامل، إلا إذا منعت ذلك لافتة، ويجب أن تعطي الأولوية للمشاة وللسيارات القريبة.","p":"صحيح. توقف توقفًا كاملًا أولًا، ثم انعطف يمينًا إذا لم تمنع ذلك لافتة."},"ref":{"doc":"CA","page":18}},{"id":"ca-014","scope":"CA","cat":"signals","sign":null,"c":2,"en":{"q":"In California, when may you turn left at a steady red light after stopping?","o":["From any street onto a two-way street","Never, left turns on red are banned","From a one-way street onto a one-way street","Only at a red arrow"],"h1":"Both streets must let traffic go only one way.","h2":"In California you may turn left on a steady red light only from a one-way street onto another one-way street, after a full stop and when no sign forbids it.","p":"Right. Left on red is allowed only from one-way to one-way."},"es":{"q":"En California, ¿cuándo puede usted girar a la izquierda con la luz roja fija después de detenerse?","o":["De cualquier calle a una calle de doble sentido","Nunca, los giros a la izquierda en rojo están prohibidos","De una calle de un solo sentido a otra de un solo sentido","Solo con una flecha roja"],"h1":"Las dos calles deben permitir el tráfico en un solo sentido.","h2":"En California usted puede girar a la izquierda con la luz roja fija solo de una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo y si ningún letrero lo prohíbe.","p":"Correcto. A la izquierda en rojo solo de un sentido a un sentido."},"zh":{"q":"在 California，持续亮着红灯时，停车以后什么时候可以左转？","o":["从任何街道转进双向街道","从来不可以，禁止红灯左转","从单行道转进单行道","只在红色箭头时"],"h1":"两条街都必须只让车往一个方向开。","h2":"在 California，只有从单行道转进另一条单行道，完全停车后，而且没有标志禁止时，你才可以在持续红灯时左转。","p":"对。只有从单行道转进单行道，才可以红灯左转。"},"vi":{"q":"Ở California, khi nào bạn được rẽ trái khi đèn đỏ sáng liên tục sau khi dừng lại?","o":["Từ bất kỳ đường nào vào đường hai chiều","Không bao giờ, rẽ trái khi đèn đỏ bị cấm","Từ đường một chiều vào đường một chiều","Chỉ khi có mũi tên đỏ"],"h1":"Cả hai con đường đều chỉ cho xe đi một chiều.","h2":"Ở California bạn chỉ được rẽ trái khi đèn đỏ sáng liên tục từ đường một chiều vào một đường một chiều khác, sau khi dừng hẳn và khi không có biển cấm.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ được phép từ đường một chiều vào đường một chiều."},"tl":{"q":"Sa California, kailan ka puwedeng kumaliwa sa tuloy-tuloy na pulang ilaw pagkatapos huminto?","o":["Mula sa kahit anong kalye papunta sa two-way na kalye","Hindi kailanman, bawal ang kaliwa sa pula","Mula sa one-way na kalye papunta sa one-way na kalye","Sa pulang arrow lang"],"h1":"Ang dalawang kalye ay dapat nagpapatakbo ng trapiko sa isang direksyon lang.","h2":"Sa California puwede kang kumaliwa sa tuloy-tuloy na pulang ilaw mula lang sa one-way na kalye papunta sa isa pang one-way na kalye, pagkatapos ng buong paghinto at kapag walang karatulang nagbabawal.","p":"Tama. Ang kaliwa sa pula ay puwede lang mula one-way papunta sa one-way."},"ar":{"q":"في California، متى يجوز لك أن تنعطف يسارًا عند إشارة حمراء ثابتة بعد التوقف؟","o":["من أي شارع إلى شارع باتجاهين","أبدًا، الانعطاف يسارًا عند الأحمر ممنوع","من شارع باتجاه واحد إلى شارع باتجاه واحد","فقط عند سهم أحمر"],"h1":"يجب أن يسمح الشارعان كلاهما بالسير في اتجاه واحد فقط.","h2":"في California يجوز لك أن تنعطف يسارًا عند إشارة حمراء ثابتة فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد، بعد توقف كامل وإذا لم تمنع ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من اتجاه واحد إلى اتجاه واحد."},"ref":{"doc":"CA","page":20}},{"id":"ca-015","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a red-painted curb mean?","o":["Parking for up to 10 minutes","Loading for trucks only","Parking for people with disabilities","No stopping, standing or parking"],"h1":"Red is the strictest curb color.","h2":"A red curb in California means no stopping, standing or parking at all, except for a bus in a marked bus zone.","p":"Right. Red curb: no stopping, standing or parking."},"es":{"q":"En California, ¿qué significa una acera pintada de rojo?","o":["Estacionamiento hasta 10 minutos","Carga solo para camiones","Estacionamiento para personas con discapacidad","Prohibido detenerse, esperar o estacionarse"],"h1":"El rojo es el color de acera más estricto.","h2":"Una acera roja en California significa que no se puede detener, esperar ni estacionar, salvo un autobús en una zona marcada para autobuses.","p":"Correcto. Acera roja: prohibido detenerse, esperar o estacionarse."},"zh":{"q":"在 California，涂成红色的路缘是什么意思？","o":["最多停车 10 分钟","只给卡车装卸货","给残障人士停车","不能停车、不能临时停靠、不能泊车"],"h1":"红色是最严格的路缘颜色。","h2":"在 California，红色路缘的意思是完全不能停车、临时停靠或泊车，在标出的公车区里的公车除外。","p":"对。红色路缘：不能停车、临时停靠或泊车。"},"vi":{"q":"Ở California, lề đường sơn màu đỏ có nghĩa là gì?","o":["Đậu xe tối đa 10 phút","Chỉ dành cho xe tải bốc dỡ hàng","Chỗ đậu xe cho người khuyết tật","Không được dừng, đứng chờ hoặc đậu xe"],"h1":"Màu đỏ là màu lề đường nghiêm nhất.","h2":"Lề đường màu đỏ ở California có nghĩa là hoàn toàn không được dừng, đứng chờ hoặc đậu xe, trừ xe buýt ở trạm xe buýt có đánh dấu.","p":"Đúng. Lề đường đỏ: không dừng, không đứng chờ, không đậu xe."},"tl":{"q":"Sa California, ano ang ibig sabihin ng gilid ng daan (curb) na pininturahan ng pula?","o":["Paradahan nang hanggang 10 minuto","Para sa pagkarga ng trak lang","Paradahan para sa mga taong may kapansanan","Bawal huminto, tumigil o pumarada"],"h1":"Ang pula ang pinakamahigpit na kulay ng curb.","h2":"Ang pulang curb sa California ay nangangahulugang bawal talagang huminto, tumigil o pumarada, maliban sa bus sa may markang bus zone.","p":"Tama. Pulang curb: bawal huminto, tumigil o pumarada."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأحمر؟","o":["الوقوف حتى 10 دقائق","لتحميل الشاحنات فقط","موقف للأشخاص ذوي الإعاقة","ممنوع التوقف أو الانتظار أو الوقوف"],"h1":"الأحمر هو أشدّ ألوان حافّة الرصيف.","h2":"حافّة الرصيف الحمراء في California تعني منع التوقف أو الانتظار أو الوقوف تمامًا، إلا للحافلة في موقف حافلات محدَّد.","p":"صحيح. الرصيف الأحمر: ممنوع التوقف أو الانتظار أو الوقوف."},"ref":{"doc":"CA","page":28}},{"id":"ca-016","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what does a yellow-painted curb mean?","o":["Stop only to load or unload passengers or freight","Park for as long as you like","Emergency vehicles only","Parking for people with disabilities"],"h1":"Think of delivery trucks.","h2":"A yellow curb in California is a loading zone: you may stop only as long as needed to load or unload passengers or freight.","p":"Right. Yellow curb: stop only to load or unload."},"es":{"q":"En California, ¿qué significa una acera pintada de amarillo?","o":["Detenerse solo para subir o bajar pasajeros o carga","Estacionarse todo el tiempo que quiera","Solo vehículos de emergencia","Estacionamiento para personas con discapacidad"],"h1":"Piense en los camiones de reparto.","h2":"Una acera amarilla en California es una zona de carga: usted puede detenerse solo el tiempo necesario para subir o bajar pasajeros o carga.","p":"Correcto. Acera amarilla: deténgase solo para cargar o descargar."},"zh":{"q":"在 California，涂成黄色的路缘是什么意思？","o":["只能停下来上下乘客或装卸货物","想停多久就停多久","只给急救车辆","给残障人士停车"],"h1":"想一想送货卡车。","h2":"在 California，黄色路缘是装卸区：你只能停留上下乘客或装卸货物需要的时间。","p":"对。黄色路缘：只能停下来上下客或装卸货。"},"vi":{"q":"Ở California, lề đường sơn màu vàng có nghĩa là gì?","o":["Chỉ dừng để cho hành khách hoặc hàng hóa lên xuống","Đậu xe bao lâu cũng được","Chỉ dành cho xe khẩn cấp","Chỗ đậu xe cho người khuyết tật"],"h1":"Hãy nghĩ đến xe tải giao hàng.","h2":"Lề đường màu vàng ở California là khu bốc dỡ: bạn chỉ được dừng trong thời gian cần để cho hành khách hoặc hàng hóa lên xuống.","p":"Đúng. Lề đường vàng: chỉ dừng để bốc dỡ."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng dilaw?","o":["Huminto lang para magbaba o magsakay ng pasahero o kargamento","Pumarada nang gaano katagal mo gusto","Para sa mga sasakyang pang-emergency lang","Paradahan para sa mga taong may kapansanan"],"h1":"Isipin ang mga delivery truck.","h2":"Ang dilaw na curb sa California ay loading zone: puwede kang huminto lang hangga't kailangan para magsakay o magbaba ng pasahero o kargamento.","p":"Tama. Dilaw na curb: huminto lang para magkarga o magbaba."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأصفر؟","o":["التوقف فقط لإنزال أو تحميل الركّاب أو البضائع","الوقوف طالما تريد","لسيارات الطوارئ فقط","موقف للأشخاص ذوي الإعاقة"],"h1":"فكّر في شاحنات التوصيل.","h2":"حافّة الرصيف الصفراء في California هي منطقة تحميل: يجوز لك أن تتوقف فقط الوقت اللازم لتحميل أو إنزال الركّاب أو البضائع.","p":"صحيح. الرصيف الأصفر: التوقف فقط للتحميل أو الإنزال."},"ref":{"doc":"CA","page":28}},{"id":"ca-017","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what does a white-painted curb mean?","o":["Parking for people with disabilities","Stop only long enough to pick up or drop off passengers","Parking for a posted time limit","No stopping at any time"],"h1":"It is for very short stops with people, not cargo.","h2":"A white curb in California allows a stop only long enough to pick up or drop off passengers.","p":"Right. White curb: a short stop for passengers."},"es":{"q":"En California, ¿qué significa una acera pintada de blanco?","o":["Estacionamiento para personas con discapacidad","Detenerse solo para recoger o dejar pasajeros","Estacionamiento con límite de tiempo indicado","Prohibido detenerse en todo momento"],"h1":"Es para paradas muy cortas con personas, no con carga.","h2":"Una acera blanca en California permite detenerse solo el tiempo necesario para recoger o dejar pasajeros.","p":"Correcto. Acera blanca: parada corta para pasajeros."},"zh":{"q":"在 California，涂成白色的路缘是什么意思？","o":["给残障人士停车","只能停一下，接送乘客上下车","按标示的时间限制停车","任何时候都不能停车"],"h1":"它是给接送人的很短的停留，不是给货物的。","h2":"在 California，白色路缘只允许停留接送乘客上下车所需的时间。","p":"对。白色路缘：为乘客短暂停留。"},"vi":{"q":"Ở California, lề đường sơn màu trắng có nghĩa là gì?","o":["Chỗ đậu xe cho người khuyết tật","Chỉ dừng đủ lâu để đón hoặc trả hành khách","Đậu xe theo thời gian ghi trên biển","Không được dừng bất cứ lúc nào"],"h1":"Đó là để dừng rất ngắn với người, không phải hàng hóa.","h2":"Lề đường màu trắng ở California chỉ cho phép dừng đủ lâu để đón hoặc trả hành khách.","p":"Đúng. Lề đường trắng: dừng ngắn cho hành khách."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng puti?","o":["Paradahan para sa mga taong may kapansanan","Huminto lang nang sapat para magsundo o magbaba ng pasahero","Paradahan ayon sa nakasulat na oras","Bawal huminto kahit kailan"],"h1":"Para ito sa napakaikling paghinto na may tao, hindi kargamento.","h2":"Ang puting curb sa California ay pinapayagan lang ang paghinto nang sapat para magsundo o magbaba ng pasahero.","p":"Tama. Puting curb: maikling paghinto para sa pasahero."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأبيض؟","o":["موقف للأشخاص ذوي الإعاقة","التوقف فقط وقتًا يكفي لأخذ الركّاب أو إنزالهم","الوقوف لمدة مكتوبة على لافتة","ممنوع التوقف في أي وقت"],"h1":"هو لتوقف قصير جدًا مع أشخاص، وليس بضائع.","h2":"حافّة الرصيف البيضاء في California تسمح بالتوقف فقط وقتًا يكفي لأخذ الركّاب أو إنزالهم.","p":"صحيح. الرصيف الأبيض: توقف قصير للركّاب."},"ref":{"doc":"CA","page":28}},{"id":"ca-018","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what does a green-painted curb mean?","o":["No parking at any time","Loading for trucks only","Parking for a limited time shown on a sign or the curb","Parking for people with disabilities"],"h1":"Green lets you park, but not forever.","h2":"A green curb in California allows parking only for a limited time, which is posted on a nearby sign or painted on the curb.","p":"Right. Green curb: parking for a limited time."},"es":{"q":"En California, ¿qué significa una acera pintada de verde?","o":["Prohibido estacionarse en todo momento","Carga solo para camiones","Estacionamiento por tiempo limitado, indicado en un letrero o en la acera","Estacionamiento para personas con discapacidad"],"h1":"El verde le permite estacionarse, pero no para siempre.","h2":"Una acera verde en California permite estacionarse solo por un tiempo limitado, que aparece en un letrero cercano o pintado en la acera.","p":"Correcto. Acera verde: estacionamiento por tiempo limitado."},"zh":{"q":"在 California，涂成绿色的路缘是什么意思？","o":["任何时候都不能停车","只给卡车装卸货","在标志或路缘上写的有限时间内停车","给残障人士停车"],"h1":"绿色让你停车，但不能一直停。","h2":"在 California，绿色路缘只允许停车一段有限的时间，时间写在附近的标志上或涂在路缘上。","p":"对。绿色路缘：限时停车。"},"vi":{"q":"Ở California, lề đường sơn màu xanh lá có nghĩa là gì?","o":["Không được đậu xe bất cứ lúc nào","Chỉ dành cho xe tải bốc dỡ hàng","Đậu xe trong thời gian giới hạn ghi trên biển hoặc trên lề đường","Chỗ đậu xe cho người khuyết tật"],"h1":"Màu xanh lá cho bạn đậu xe, nhưng không phải mãi mãi.","h2":"Lề đường màu xanh lá ở California chỉ cho đậu xe trong thời gian giới hạn, được ghi trên biển gần đó hoặc sơn trên lề đường.","p":"Đúng. Lề đường xanh lá: đậu xe trong thời gian giới hạn."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng berde?","o":["Bawal pumarada kahit kailan","Para sa pagkarga ng trak lang","Paradahan sa limitadong oras na nakasulat sa karatula o sa curb","Paradahan para sa mga taong may kapansanan"],"h1":"Pinapayagan ka ng berde na pumarada, pero hindi habambuhay.","h2":"Ang berdeng curb sa California ay pinapayagan ang pagparada sa limitadong oras lang, na nakasulat sa malapit na karatula o nakapinta sa curb.","p":"Tama. Berdeng curb: paradahan sa limitadong oras."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأخضر؟","o":["ممنوع الوقوف في أي وقت","لتحميل الشاحنات فقط","الوقوف لوقت محدود مكتوب على لافتة أو على الرصيف","موقف للأشخاص ذوي الإعاقة"],"h1":"الأخضر يسمح لك بالوقوف، لكن ليس إلى الأبد.","h2":"حافّة الرصيف الخضراء في California تسمح بالوقوف لوقت محدود فقط، مكتوب على لافتة قريبة أو مدهون على الرصيف.","p":"صحيح. الرصيف الأخضر: الوقوف لوقت محدود."},"ref":{"doc":"CA","page":28}},{"id":"ca-019","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what does a blue-painted curb mean?","o":["Parking for electric cars only","Taxi stand only","Short stop to drop off mail","Parking only for people with a disability placard or plate"],"h1":"This color matches a well-known access symbol.","h2":"A blue curb in California is for people with disabilities, and the vehicle must show a disability placard or special license plate.","p":"Right. Blue curb: disability parking with a placard or plate."},"es":{"q":"En California, ¿qué significa una acera pintada de azul?","o":["Estacionamiento solo para autos eléctricos","Solo parada de taxis","Parada corta para dejar correo","Estacionamiento solo para personas con placa o letrero de discapacidad"],"h1":"Este color coincide con un símbolo conocido de accesibilidad.","h2":"Una acera azul en California es para personas con discapacidad, y el vehículo debe mostrar un letrero o una placa especial de discapacidad.","p":"Correcto. Acera azul: estacionamiento para personas con discapacidad, con letrero o placa."},"zh":{"q":"在 California，涂成蓝色的路缘是什么意思？","o":["只给电动车停车","只给出租车停靠","短暂停下来投寄邮件","只给有残障停车证或残障车牌的人停车"],"h1":"这个颜色和一个大家都知道的无障碍标志一样。","h2":"在 California，蓝色路缘是给残障人士的，车辆必须挂残障停车证或特殊车牌。","p":"对。蓝色路缘：有停车证或车牌的残障停车位。"},"vi":{"q":"Ở California, lề đường sơn màu xanh dương có nghĩa là gì?","o":["Chỉ cho xe điện đậu","Chỉ dành cho xe taxi","Dừng ngắn để gửi thư","Chỉ cho người có thẻ hoặc biển số xe người khuyết tật đậu"],"h1":"Màu này giống màu của một biểu tượng tiếp cận rất quen thuộc.","h2":"Lề đường màu xanh dương ở California dành cho người khuyết tật, và xe phải có thẻ người khuyết tật (disability placard) hoặc biển số đặc biệt.","p":"Đúng. Lề đường xanh dương: chỗ đậu cho người khuyết tật có thẻ hoặc biển số."},"tl":{"q":"Sa California, ano ang ibig sabihin ng curb na pininturahan ng asul?","o":["Paradahan para sa electric car lang","Para sa taxi lang","Maikling paghinto para maghulog ng sulat","Paradahan lang para sa may disability placard o plaka"],"h1":"Kapareho ng kulay na ito ang kilalang simbolo ng accessibility.","h2":"Ang asul na curb sa California ay para sa mga taong may kapansanan, at dapat magpakita ang sasakyan ng disability placard o espesyal na plaka.","p":"Tama. Asul na curb: paradahan para sa may kapansanan na may placard o plaka."},"ar":{"q":"في California، ماذا يعني حافّة الرصيف المدهونة باللون الأزرق؟","o":["موقف للسيارات الكهربائية فقط","موقف سيارات الأجرة فقط","توقف قصير لوضع البريد","موقف فقط لمن لديه بطاقة أو لوحة إعاقة"],"h1":"هذا اللون يطابق رمزًا معروفًا لتسهيل الوصول.","h2":"حافّة الرصيف الزرقاء في California هي للأشخاص ذوي الإعاقة، ويجب أن تُظهر السيارة بطاقة إعاقة (disability placard) أو لوحة أرقام خاصة.","p":"صحيح. الرصيف الأزرق: موقف ذوي الإعاقة مع بطاقة أو لوحة."},"ref":{"doc":"CA","page":28}},{"id":"ca-020","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, when must you turn on your headlights during the day?","o":["Only in tunnels","When your wipers are on all the time because of rain, snow or fog","Only on freeways","Only after 6 p.m."],"h1":"Think about what your windshield needs in bad weather.","h2":"California requires your low-beam headlights whenever rain, snow or fog makes you use your wipers.","p":"Right. Wipers on all the time means headlights on."},"es":{"q":"En California, ¿cuándo debe encender las luces delanteras durante el día?","o":["Solo en túneles","Cuando usa los limpiaparabrisas todo el tiempo por lluvia, nieve o niebla","Solo en autopistas","Solo después de las 6 p.m."],"h1":"Piense en lo que necesita su parabrisas con mal tiempo.","h2":"California exige las luces bajas cada vez que la lluvia, la nieve o la niebla le obligan a usar los limpiaparabrisas.","p":"Correcto. Limpiaparabrisas todo el tiempo significa luces encendidas."},"zh":{"q":"在 California，白天什么时候必须打开大灯？","o":["只在隧道里","因为下雨、下雪或有雾而一直开着雨刷时","只在高速公路上","只在下午 6 点以后"],"h1":"想一想坏天气时你的挡风玻璃需要什么。","h2":"只要雨、雪或雾让你需要用雨刷，California 就要求你打开近光灯。","p":"对。雨刷一直开着，就要开大灯。"},"vi":{"q":"Ở California, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trong đường hầm","Khi bạn phải bật cần gạt nước liên tục vì mưa, tuyết hoặc sương mù","Chỉ trên xa lộ","Chỉ sau 6 giờ chiều"],"h1":"Hãy nghĩ đến những gì kính chắn gió cần khi thời tiết xấu.","h2":"California yêu cầu bạn bật đèn pha chiếu gần bất cứ khi nào mưa, tuyết hoặc sương mù làm bạn phải dùng cần gạt nước.","p":"Đúng. Cần gạt nước bật liên tục thì đèn pha phải bật."},"tl":{"q":"Sa California, kailan mo dapat buksan ang headlights sa araw?","o":["Sa mga tunnel lang","Kapag laging nakabukas ang wipers dahil sa ulan, niyebe o hamog","Sa mga freeway lang","Pagkatapos ng 6 p.m. lang"],"h1":"Isipin kung ano ang kailangan ng windshield mo sa masamang panahon.","h2":"Hinihingi ng California na nakabukas ang low-beam headlights mo tuwing pinapagamit ka ng wipers dahil sa ulan, niyebe o hamog.","p":"Tama. Kapag laging nakabukas ang wipers, dapat nakabukas ang headlights."},"ar":{"q":"في California، متى يجب أن تشغّل المصابيح الأمامية في النهار؟","o":["في الأنفاق فقط","عندما تكون المسّاحات تعمل طوال الوقت بسبب المطر أو الثلج أو الضباب","على الطرق السريعة فقط","بعد 6 مساءً فقط"],"h1":"فكّر فيما يحتاجه زجاجك الأمامي في الطقس السيئ.","h2":"تطلب California تشغيل المصابيح الأمامية المنخفضة كلما جعلك المطر أو الثلج أو الضباب تستخدم المسّاحات.","p":"صحيح. المسّاحات تعمل طوال الوقت تعني أن المصابيح يجب أن تعمل."},"ref":{"doc":"CA","page":11}},{"id":"ca-021","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, since 2025, what is the minimum liability insurance for injury to one person?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"The old amount was doubled in 2025.","h2":"Since January 1, 2025, California requires at least $30,000 for injury to one person, $60,000 per crash, and $15,000 for property damage.","p":"Right. The minimum is now $30,000 per injured person."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"La cantidad anterior se duplicó en 2025.","h2":"Desde el 1 de enero de 2025, California exige por lo menos $30,000 por lesiones a una persona, $60,000 por choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo ahora es $30,000 por persona lesionada."},"zh":{"q":"在 California，从 2025 年起，一个人受伤的最低责任保险是多少？","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"原来的金额在 2025 年提高了一倍。","h2":"从 2025 年 1 月 1 日起，California 要求一个人受伤至少 $30,000，每次车祸至少 $60,000，财产损失至少 $15,000。","p":"对。现在每个受伤的人最低是 $30,000。"},"vi":{"q":"Ở California, từ năm 2025, mức bảo hiểm trách nhiệm tối thiểu cho thương tích của một người là bao nhiêu?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"Mức cũ được tăng gấp đôi vào năm 2025.","h2":"Từ ngày 1 tháng 1 năm 2025, California yêu cầu ít nhất $30,000 cho thương tích của một người, $60,000 cho mỗi tai nạn, và $15,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu hiện nay là $30,000 cho mỗi người bị thương."},"tl":{"q":"Sa California, mula 2025, ano ang pinakamababang liability insurance para sa pinsala sa isang tao?","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"Dinoble ang lumang halaga noong 2025.","h2":"Mula Enero 1, 2025, hinihingi ng California ang hindi bababa sa $30,000 para sa pinsala sa isang tao, $60,000 bawat banggaan, at $15,000 para sa pinsala sa ari-arian.","p":"Tama. Ang pinakamababa ngayon ay $30,000 bawat taong nasaktan."},"ar":{"q":"في California، منذ 2025، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد؟","o":["$30,000","$15,000","$50,000","$25,000"],"h1":"تمّت مضاعفة المبلغ القديم في 2025.","h2":"منذ 1 يناير 2025، تطلب California على الأقل $30,000 لإصابة شخص واحد، و$60,000 لكل حادث، و$15,000 للأضرار بالممتلكات.","p":"صحيح. الحدّ الأدنى الآن $30,000 لكل شخص مصاب."},"ref":{"doc":"CA","page":76}},{"id":"ca-022","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, since 2025, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"It is half of the amount required for injury to one person.","h2":"California requires at least $15,000 of coverage for damage to other people's property.","p":"Right. Property damage coverage must be at least $15,000."},"es":{"q":"En California, desde 2025, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Es la mitad de la cantidad exigida por lesiones a una persona.","h2":"California exige por lo menos $15,000 de cobertura por daños a la propiedad de otras personas.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $15,000."},"zh":{"q":"在 California，从 2025 年起，财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"它是一个人受伤所需金额的一半。","h2":"California 要求对别人财产的损失至少要有 $15,000 的保险。","p":"对。财产损失保险至少要 $15,000。"},"vi":{"q":"Ở California, từ năm 2025, mức bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Đó là một nửa mức yêu cầu cho thương tích của một người.","h2":"California yêu cầu bảo hiểm ít nhất $15,000 cho thiệt hại tài sản của người khác.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất $15,000."},"tl":{"q":"Sa California, mula 2025, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Kalahati ito ng halagang kailangan para sa pinsala sa isang tao.","h2":"Hinihingi ng California ang hindi bababa sa $15,000 na coverage para sa pinsala sa ari-arian ng ibang tao.","p":"Tama. Ang coverage sa pinsala sa ari-arian ay dapat hindi bababa sa $15,000."},"ar":{"q":"في California، منذ 2025، ما الحدّ الأدنى لتأمين المسؤولية عن الأضرار بالممتلكات؟","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"هو نصف المبلغ المطلوب لإصابة شخص واحد.","h2":"تطلب California تغطية لا تقل عن $15,000 للأضرار بممتلكات الآخرين.","p":"صحيح. تغطية الأضرار بالممتلكات يجب ألا تقل عن $15,000."},"ref":{"doc":"CA","page":76}},{"id":"ca-023","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, how close to a fire hydrant may you park when the curb is not painted?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 10 feet"],"h1":"Firefighters need room for their hoses and truck.","h2":"In California you must stay 15 feet away from a fire hydrant on either side, even when the curb is not painted red.","p":"Right. Park at least 15 feet from a hydrant."},"es":{"q":"En California, ¿a qué distancia de un hidrante puede estacionarse cuando la acera no está pintada?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 30 pies","A no menos de 10 pies"],"h1":"Los bomberos necesitan espacio para sus mangueras y su camión.","h2":"En California usted debe quedarse a 15 pies de un hidrante por cada lado, aunque la acera no esté pintada de rojo.","p":"Correcto. Estaciónese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 California，路缘没有涂颜色时，你可以在离消防栓多近的地方停车？","o":["不能少于 5 英尺","不能少于 15 英尺","不能少于 30 英尺","不能少于 10 英尺"],"h1":"消防员需要空间放水管和消防车。","h2":"在 California，即使路缘没有涂红色，你也必须在消防栓两边都离开 15 英尺。","p":"对。在离消防栓至少 15 英尺的地方停车。"},"vi":{"q":"Ở California, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào khi lề đường không được sơn màu?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 10 feet"],"h1":"Lính cứu hỏa cần chỗ cho vòi nước và xe cứu hỏa.","h2":"Ở California bạn phải cách trụ nước cứu hỏa 15 feet ở mỗi bên, kể cả khi lề đường không sơn màu đỏ.","p":"Đúng. Đậu xe cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa California, gaano kalapit sa fire hydrant ka puwedeng pumarada kapag walang pintura ang curb?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 10 feet"],"h1":"Kailangan ng mga bumbero ng lugar para sa kanilang hose at trak.","h2":"Sa California dapat kang lumayo nang 15 feet sa fire hydrant sa magkabilang panig, kahit hindi pula ang pintura ng curb.","p":"Tama. Pumarada nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في California، كم يمكنك أن تقترب من صنبور إطفاء الحريق عند الوقوف إذا كانت حافّة الرصيف غير مدهونة؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 10 أقدام"],"h1":"يحتاج رجال الإطفاء إلى مكان لخراطيمهم وشاحنتهم.","h2":"في California يجب أن تبتعد 15 قدمًا عن صنبور إطفاء الحريق من كل جهة، حتى لو لم تكن حافّة الرصيف مدهونة بالأحمر.","p":"صحيح. قف على بعد 15 قدمًا على الأقل من صنبور الإطفاء."},"ref":{"doc":"CA","page":28}},{"id":"ca-024","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, what is the highest speed limit on most highways, unless a sign shows a different limit?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Higher limits apply only where signs say so.","h2":"In California the general maximum is 65 mph; some freeways are posted at 70 mph, and you must follow the signs.","p":"Right. The general maximum is 65 mph unless a sign says 70."},"es":{"q":"En California, ¿cuál es el límite de velocidad más alto en la mayoría de las carreteras, si un letrero no indica otro?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Los límites más altos solo valen donde los letreros lo indican.","h2":"En California el máximo general es 65 mph; algunas autopistas tienen un letrero de 70 mph, y usted debe seguir los letreros.","p":"Correcto. El máximo general es 65 mph, salvo que un letrero diga 70."},"zh":{"q":"在 California，除非标志写着别的限速，大多数公路的最高限速是多少？","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"更高的限速只在有标志的地方适用。","h2":"在 California，一般的最高限速是 65 mph；有些高速公路标示为 70 mph，你必须按照标志开。","p":"对。除非标志写着 70，一般最高限速是 65 mph。"},"vi":{"q":"Ở California, tốc độ tối đa cao nhất trên hầu hết các xa lộ là bao nhiêu, trừ khi biển báo ghi tốc độ khác?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Tốc độ cao hơn chỉ áp dụng ở nơi có biển báo.","h2":"Ở California tốc độ tối đa chung là 65 mph; một số xa lộ có biển 70 mph, và bạn phải theo biển báo.","p":"Đúng. Tốc độ tối đa chung là 65 mph trừ khi biển báo ghi 70."},"tl":{"q":"Sa California, ano ang pinakamataas na speed limit sa karamihan ng mga highway, maliban kung iba ang nakasulat sa karatula?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Ang mas mataas na limitasyon ay may bisa lang kung saan may karatula.","h2":"Sa California ang pangkalahatang pinakamataas ay 65 mph; may ilang freeway na nakasulat na 70 mph, at dapat mong sundin ang mga karatula.","p":"Tama. Ang pangkalahatang pinakamataas ay 65 mph maliban kung 70 ang nasa karatula."},"ar":{"q":"في California، ما أعلى حدّ للسرعة على معظم الطرق السريعة، إلا إذا أظهرت لافتة حدًّا مختلفًا؟","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"الحدود الأعلى تُطبَّق فقط حيث تقول اللافتات ذلك.","h2":"في California الحدّ الأقصى العام هو 65 mph؛ بعض الطرق السريعة عليها لافتة 70 mph، ويجب أن تتبع اللافتات.","p":"صحيح. الحدّ الأقصى العام 65 mph إلا إذا قالت لافتة 70."},"ref":{"doc":"CA","page":67}},{"id":"ca-025","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, what is the speed limit on a two-lane undivided highway unless signs show otherwise?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"It is ten less than the general highway maximum.","h2":"On a two-lane undivided highway in California, the limit is 55 mph unless signs post a higher speed.","p":"Right. Two-lane undivided highways are 55 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una carretera de dos carriles sin división, si los letreros no indican otro?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Es diez menos que el máximo general en carretera.","h2":"En una carretera de dos carriles sin división en California, el límite es 55 mph, salvo que los letreros indiquen una velocidad mayor.","p":"Correcto. En carreteras de dos carriles sin división el límite es 55 mph si no hay letrero."},"zh":{"q":"在 California，除非标志另有规定，没有分隔的双车道公路限速是多少？","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"它比一般公路最高限速少十。","h2":"在 California 没有分隔的双车道公路上，除非标志标示更高的速度，限速是 55 mph。","p":"对。除非有标志，没有分隔的双车道公路限速是 55 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trên xa lộ hai làn không có dải phân cách là bao nhiêu, trừ khi biển báo ghi khác?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Nó thấp hơn mức tối đa chung của xa lộ mười đơn vị.","h2":"Trên xa lộ hai làn không có dải phân cách ở California, tốc độ tối đa là 55 mph trừ khi biển báo ghi tốc độ cao hơn.","p":"Đúng. Xa lộ hai làn không có dải phân cách là 55 mph trừ khi có biển báo."},"tl":{"q":"Sa California, ano ang speed limit sa two-lane na highway na walang divider, maliban kung iba ang nasa karatula?","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"Sampu itong mas mababa sa pangkalahatang pinakamataas sa highway.","h2":"Sa two-lane na highway na walang divider sa California, ang limitasyon ay 55 mph maliban kung may karatulang nagsasabi ng mas mataas na bilis.","p":"Tama. Ang two-lane na highway na walang divider ay 55 mph maliban kung may karatula."},"ar":{"q":"في California، ما حدّ السرعة على طريق سريع بحارتين بدون فاصل في الوسط، إلا إذا أظهرت اللافتات غير ذلك؟","o":["55 mph","45 mph","65 mph","50 mph"],"h1":"هو أقل بعشرة من الحدّ الأقصى العام للطرق السريعة.","h2":"على طريق سريع بحارتين بدون فاصل في California، الحدّ هو 55 mph إلا إذا أظهرت اللافتات سرعة أعلى.","p":"صحيح. الطرق بحارتين بدون فاصل 55 mph إلا إذا وُجدت لافتة."},"ref":{"doc":"CA","page":67}},{"id":"ca-026","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what is the speed limit in a residential district when no sign is posted?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"It is the same as the usual school zone limit.","h2":"Unless a sign shows another limit, the speed limit in a California residential or business district is 25 mph.","p":"Right. Residential districts are 25 mph unless posted."},"es":{"q":"En California, ¿cuál es el límite de velocidad en una zona residencial cuando no hay letrero?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Es igual al límite usual de una zona escolar.","h2":"Si no hay un letrero con otro límite, la velocidad máxima en una zona residencial o comercial de California es 25 mph.","p":"Correcto. En zonas residenciales el límite es 25 mph si no hay letrero."},"zh":{"q":"在 California，没有标志时，住宅区的限速是多少？","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"它和一般学校区的限速一样。","h2":"除非标志写着别的限速，California 住宅区或商业区的限速是 25 mph。","p":"对。除非有标志，住宅区限速是 25 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trong khu dân cư là bao nhiêu khi không có biển báo?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Nó bằng tốc độ thường gặp ở khu vực trường học.","h2":"Trừ khi biển báo ghi tốc độ khác, tốc độ tối đa trong khu dân cư hoặc khu thương mại ở California là 25 mph.","p":"Đúng. Khu dân cư là 25 mph trừ khi có biển báo."},"tl":{"q":"Sa California, ano ang speed limit sa residential na lugar kapag walang karatula?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Pareho ito sa karaniwang limitasyon sa school zone.","h2":"Maliban kung iba ang nasa karatula, ang speed limit sa residential o business na lugar sa California ay 25 mph.","p":"Tama. Ang residential na lugar ay 25 mph maliban kung may karatula."},"ar":{"q":"في California، ما حدّ السرعة في منطقة سكنية عندما لا توجد لافتة؟","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"هو نفس الحدّ المعتاد في منطقة المدرسة.","h2":"إلا إذا أظهرت لافتة حدًّا آخر، فحدّ السرعة في منطقة سكنية أو تجارية في California هو 25 mph.","p":"صحيح. المناطق السكنية 25 mph إلا إذا وُجدت لافتة."},"ref":{"doc":"CA","page":52}},{"id":"ca-027","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, what is the speed limit in an alley?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Alleys are narrow, so the limit is lower than in a neighborhood.","h2":"The speed limit in a California alley is 15 mph, because alleys are narrow and people and cars can appear suddenly.","p":"Right. Alleys have a 15 mph limit."},"es":{"q":"En California, ¿cuál es el límite de velocidad en un callejón?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Los callejones son angostos, así que el límite es menor que en un vecindario.","h2":"El límite de velocidad en un callejón de California es 15 mph, porque los callejones son angostos y pueden aparecer personas o autos de repente.","p":"Correcto. En los callejones el límite es 15 mph."},"zh":{"q":"在 California，小巷里的限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"小巷很窄，所以限速比住宅区低。","h2":"California 小巷的限速是 15 mph，因为小巷很窄，人和车可能会突然出现。","p":"对。小巷限速是 15 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trong hẻm là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Hẻm thì hẹp, nên tốc độ thấp hơn trong khu dân cư.","h2":"Tốc độ tối đa trong hẻm ở California là 15 mph, vì hẻm hẹp và người hoặc xe có thể xuất hiện bất ngờ.","p":"Đúng. Trong hẻm, tốc độ tối đa là 15 mph."},"tl":{"q":"Sa California, ano ang speed limit sa eskinita (alley)?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Makitid ang mga eskinita, kaya mas mababa ang limitasyon kaysa sa kapitbahayan.","h2":"Ang speed limit sa eskinita sa California ay 15 mph, dahil makitid ang mga eskinita at biglang puwedeng sumulpot ang mga tao at kotse.","p":"Tama. Ang mga eskinita ay may 15 mph na limitasyon."},"ar":{"q":"في California، ما حدّ السرعة في الزقاق (alley)؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"الأزقّة ضيّقة، لذلك الحدّ أقل منه في الحيّ السكني.","h2":"حدّ السرعة في الزقاق في California هو 15 mph، لأن الأزقّة ضيّقة ويمكن أن يظهر الناس والسيارات فجأة.","p":"صحيح. حدّ السرعة في الأزقّة 15 mph."},"ref":{"doc":"CA","page":51}},{"id":"ca-028","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, the \"basic speed law\" means what?","o":["You may always drive at the posted limit","You may go 5 mph over the limit to pass","Only trucks must slow down in rain","You must never drive faster than is safe for conditions"],"h1":"Weather, traffic and the road all matter.","h2":"California's basic speed law says you must never drive faster than is safe for the weather, traffic and road, so you can get a ticket even below the posted limit.","p":"Right. Never drive faster than is safe for conditions."},"es":{"q":"En California, ¿qué significa la \"ley básica de velocidad\"?","o":["Que siempre puede manejar al límite indicado","Que puede ir 5 mph sobre el límite para rebasar","Que solo los camiones deben bajar la velocidad con lluvia","Que nunca debe manejar más rápido de lo seguro para las condiciones"],"h1":"El clima, el tráfico y el camino importan.","h2":"La ley básica de velocidad de California dice que nunca debe manejar más rápido de lo seguro para el clima, el tráfico y el camino, así que le pueden multar aunque vaya por debajo del límite indicado.","p":"Correcto. Nunca maneje más rápido de lo seguro para las condiciones."},"zh":{"q":"在 California，“基本速度法”（basic speed law）是什么意思？","o":["你总是可以按标示的限速开","超车时可以超速 5 mph","只有卡车下雨时要减速","你开车绝对不能快过当时条件下安全的速度"],"h1":"天气、车流和道路都有关系。","h2":"California 的基本速度法说，你开车绝对不能快过天气、车流和道路条件下安全的速度，所以即使低于标示的限速，你也可能被开罚单。","p":"对。绝对不要开得比当时条件下安全的速度快。"},"vi":{"q":"Ở California, \"luật tốc độ cơ bản\" (basic speed law) có nghĩa là gì?","o":["Bạn luôn được lái theo tốc độ ghi trên biển","Bạn được chạy quá tốc độ 5 mph để vượt","Chỉ xe tải phải chạy chậm khi trời mưa","Bạn không bao giờ được lái nhanh hơn mức an toàn theo hoàn cảnh"],"h1":"Thời tiết, giao thông và mặt đường đều quan trọng.","h2":"Luật tốc độ cơ bản của California nói rằng bạn không bao giờ được lái nhanh hơn mức an toàn theo thời tiết, giao thông và mặt đường, nên bạn có thể bị phạt dù chạy dưới tốc độ ghi trên biển.","p":"Đúng. Không bao giờ lái nhanh hơn mức an toàn theo hoàn cảnh."},"tl":{"q":"Sa California, ano ang ibig sabihin ng \"basic speed law\"?","o":["Puwede kang laging magmaneho sa nakasulat na limitasyon","Puwede kang lumampas nang 5 mph para mag-overtake","Ang mga trak lang ang dapat bumagal sa ulan","Hindi ka dapat magmaneho nang mas mabilis kaysa ligtas para sa kalagayan"],"h1":"Mahalaga ang panahon, trapiko at kalsada.","h2":"Sinasabi ng basic speed law ng California na hindi ka dapat magmaneho nang mas mabilis kaysa ligtas para sa panahon, trapiko at kalsada, kaya puwede kang ma-tiket kahit mas mababa sa nakasulat na limitasyon.","p":"Tama. Huwag magmaneho nang mas mabilis kaysa ligtas para sa kalagayan."},"ar":{"q":"في California، ماذا يعني \"قانون السرعة الأساسي\" (basic speed law)؟","o":["يجوز لك دائمًا أن تقود بالحدّ المكتوب","يجوز لك أن تزيد 5 mph عن الحدّ لتتجاوز","الشاحنات فقط يجب أن تخفّف السرعة في المطر","يجب ألا تقود أبدًا أسرع مما هو آمن حسب الظروف"],"h1":"الطقس وحركة السير والطريق كلها مهمة.","h2":"قانون السرعة الأساسي في California يقول إنه يجب ألا تقود أبدًا أسرع مما هو آمن حسب الطقس وحركة السير والطريق، لذلك يمكن أن تحصل على مخالفة حتى تحت الحدّ المكتوب.","p":"صحيح. لا تقد أبدًا أسرع مما هو آمن حسب الظروف."},"ref":{"doc":"CA","page":67}},{"id":"ca-029","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, since 2026, you approach any vehicle stopped on the side of the road with hazard lights on. What must you do?","o":["Move to a lane not next to it, or slow down if you cannot","Honk to warn the driver","Stop behind it until it leaves","Keep the same lane and speed"],"h1":"The rule now protects more than police cars and tow trucks.","h2":"Since January 1, 2026, California's move over law covers any stopped vehicle with hazard lights, so you must move away from its lane or slow down if you cannot change lanes safely.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En California, desde 2026, usted se acerca a cualquier vehículo detenido al lado del camino con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Cambiarse a un carril que no esté junto a él, o reducir la velocidad si no puede","Tocar la bocina para avisar al conductor","Detenerse detrás hasta que se vaya","Seguir en el mismo carril y a la misma velocidad"],"h1":"La regla ahora protege a más que patrullas y grúas.","h2":"Desde el 1 de enero de 2026, la ley de California de cambiarse de carril cubre cualquier vehículo detenido con luces de emergencia, así que usted debe alejarse de su carril o reducir la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Cámbiese de carril, o reduzca la velocidad si no puede."},"zh":{"q":"在 California，从 2026 年起，你接近任何停在路边、开着双闪灯的车辆。你必须怎么做？","o":["换到不在它旁边的车道，做不到就减速","按喇叭提醒司机","停在它后面，直到它离开","保持同一条车道和速度"],"h1":"这个规定现在保护的不只是警车和拖车。","h2":"从 2026 年 1 月 1 日起，California 的 move over 法保护任何开着双闪灯停着的车辆，所以你必须离开它旁边的车道，如果无法安全换道就要减速。","p":"对。换开一条车道，做不到就减速。"},"vi":{"q":"Ở California, từ năm 2026, bạn đến gần bất kỳ xe nào đang dừng bên lề đường và bật đèn khẩn cấp. Bạn phải làm gì?","o":["Chuyển sang làn không sát xe đó, hoặc chạy chậm lại nếu không chuyển được","Bấm còi để báo cho tài xế","Dừng phía sau xe đó cho đến khi nó đi","Giữ nguyên làn và tốc độ"],"h1":"Luật bây giờ bảo vệ nhiều hơn chỉ xe cảnh sát và xe kéo.","h2":"Từ ngày 1 tháng 1 năm 2026, luật nhường làn (move over law) của California áp dụng cho mọi xe đang dừng có bật đèn khẩn cấp, nên bạn phải chuyển ra xa làn của xe đó hoặc chạy chậm lại nếu không thể chuyển làn an toàn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không chuyển được."},"tl":{"q":"Sa California, mula 2026, papalapit ka sa kahit anong sasakyang nakahinto sa gilid ng daan na nakabukas ang hazard lights. Ano ang dapat mong gawin?","o":["Lumipat sa lane na hindi katabi nito, o bumagal kung hindi mo kaya","Bumusina para balaan ang drayber","Huminto sa likod nito hanggang umalis ito","Manatili sa parehong lane at bilis"],"h1":"Mas marami na ngayon ang pinoprotektahan ng patakaran kaysa sa mga kotse ng pulis at tow truck.","h2":"Mula Enero 1, 2026, sakop ng move over law ng California ang kahit anong nakahintong sasakyan na may hazard lights, kaya dapat kang lumayo sa lane nito o bumagal kung hindi ka ligtas na makalipat ng lane.","p":"Tama. Lumipat ng lane, o bumagal kung hindi mo kaya."},"ar":{"q":"في California، منذ 2026، تقترب من أي سيارة متوقفة على جانب الطريق وأضواء الخطر فيها تعمل. ماذا يجب أن تفعل؟","o":["انتقل إلى حارة غير ملاصقة لها، أو خفّف السرعة إذا لم تستطع","أطلق البوق لتنبيه السائق","توقف خلفها حتى تذهب","ابقَ في نفس الحارة وبنفس السرعة"],"h1":"القاعدة الآن تحمي أكثر من سيارات الشرطة وشاحنات السحب.","h2":"منذ 1 يناير 2026، يشمل قانون الابتعاد (move over law) في California أي سيارة متوقفة وأضواء الخطر فيها تعمل، لذلك يجب أن تبتعد عن حارتها أو تخفّف السرعة إذا لم تستطع تغيير الحارة بأمان.","p":"صحيح. ابتعد بتغيير الحارة، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"CA","page":null}},{"id":"ca-030","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, how many tries do you get to pass the knowledge test before you must apply again?","o":["One try","Two tries","Three tries","Five tries"],"h1":"It is more than two and fewer than four.","h2":"California gives you three tries at the knowledge test on one application; after that you must apply and pay again.","p":"Right. You get three tries per application."},"es":{"q":"En California, ¿cuántos intentos tiene para aprobar el examen de conocimientos antes de tener que solicitar de nuevo?","o":["Un intento","Dos intentos","Tres intentos","Cinco intentos"],"h1":"Son más de dos y menos de cuatro.","h2":"California le da tres intentos para el examen de conocimientos con una solicitud; después tiene que solicitar y pagar de nuevo.","p":"Correcto. Tiene tres intentos por solicitud."},"zh":{"q":"在 California，笔试你有几次机会，用完以后必须重新申请？","o":["一次","两次","三次","五次"],"h1":"它比两次多，比四次少。","h2":"California 一次申请给你三次笔试机会；用完以后你必须重新申请并再付费。","p":"对。每次申请有三次机会。"},"vi":{"q":"Ở California, bạn có bao nhiêu lần thi để đậu bài thi lý thuyết trước khi phải nộp đơn lại?","o":["Một lần","Hai lần","Ba lần","Năm lần"],"h1":"Nhiều hơn hai và ít hơn bốn.","h2":"California cho bạn ba lần thi lý thuyết cho mỗi đơn; sau đó bạn phải nộp đơn và trả phí lại.","p":"Đúng. Bạn có ba lần thi cho mỗi đơn."},"tl":{"q":"Sa California, ilang subok ang mayroon ka para pumasa sa knowledge test bago ka dapat mag-apply ulit?","o":["Isang subok","Dalawang subok","Tatlong subok","Limang subok"],"h1":"Higit ito sa dalawa at kulang sa apat.","h2":"Binibigyan ka ng California ng tatlong subok sa knowledge test sa isang application; pagkatapos noon, dapat kang mag-apply at magbayad ulit.","p":"Tama. May tatlong subok ka bawat application."},"ar":{"q":"في California، كم محاولة لديك لتنجح في الامتحان النظري قبل أن تقدّم طلبًا جديدًا؟","o":["محاولة واحدة","محاولتان","ثلاث محاولات","خمس محاولات"],"h1":"هو أكثر من اثنتين وأقل من أربع.","h2":"تعطيك California ثلاث محاولات في الامتحان النظري لكل طلب؛ بعد ذلك يجب أن تقدّم طلبًا جديدًا وتدفع مرة أخرى.","p":"صحيح. لديك ثلاث محاولات لكل طلب."},"ref":{"doc":"CA","page":5}},{"id":"ca-031","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In California, you must give the DMV your new address within 10 days after you move.","p":"Right. Tell the DMV within 10 days of moving."},"es":{"q":"En California, usted se muda a una nueva casa. ¿En cuánto tiempo debe darle su nueva dirección al DMV?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En California, usted debe darle su nueva dirección al DMV dentro de los 10 días después de mudarse.","p":"Correcto. Avise al DMV dentro de 10 días después de mudarse."},"zh":{"q":"在 California，你搬到新家。你必须在多久之内把新地址告诉 DMV？","o":["10 天内","30 天内","60 天内","下次更新驾照时"],"h1":"不到两个星期。","h2":"在 California，你搬家后必须在 10 天内把新地址告诉 DMV。","p":"对。搬家后 10 天内告诉 DMV。"},"vi":{"q":"Ở California, bạn chuyển đến nhà mới. Bạn phải báo địa chỉ mới cho DMV trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Vào lần gia hạn tới"],"h1":"Ít hơn hai tuần.","h2":"Ở California, bạn phải báo địa chỉ mới cho DMV trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Báo cho DMV trong vòng 10 ngày sau khi chuyển nhà."},"tl":{"q":"Sa California, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihin sa DMV ang bago mong address?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa susunod mong renewal"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa California, dapat mong ibigay sa DMV ang bago mong address sa loob ng 10 araw pagkatapos mong lumipat.","p":"Tama. Sabihin sa DMV sa loob ng 10 araw pagkatapos lumipat."},"ar":{"q":"في California، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ DMV بعنوانك الجديد؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عند التجديد القادم"],"h1":"أقل من أسبوعين.","h2":"في California، يجب أن تُبلغ DMV بعنوانك الجديد خلال 10 أيام بعد الانتقال.","p":"صحيح. أبلِغ DMV خلال 10 أيام من الانتقال."},"ref":{"doc":"CA","page":8}},{"id":"ca-032","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, what is the lowest number of points in 12 months that can get an adult's license suspended?","o":["1 point","4 points","8 points","12 points"],"h1":"It is less than the 6-point total used for a 24-month period.","h2":"In California, an adult with 4 points on their record in 12 months may have their license suspended.","p":"Right. 4 points in 12 months can lead to a suspension."},"es":{"q":"En California, ¿cuál es el número más bajo de puntos en 12 meses que puede causar la suspensión de la licencia de un adulto?","o":["1 punto","4 puntos","8 puntos","12 puntos"],"h1":"Es menos que el total de 6 puntos que se usa para un período de 24 meses.","h2":"En California, un adulto con 4 puntos en su historial en 12 meses puede perder su licencia por suspensión.","p":"Correcto. 4 puntos en 12 meses pueden causar una suspensión."},"zh":{"q":"在 California，12 个月内最少累积几分就可能让成年人的驾照被暂停？","o":["1 分","4 分","8 分","12 分"],"h1":"它比 24 个月期间用的 6 分总数少。","h2":"在 California，成年人如果 12 个月内记录上有 4 分，驾照可能会被暂停。","p":"对。12 个月内 4 分就可能导致暂停驾照。"},"vi":{"q":"Ở California, số điểm thấp nhất trong 12 tháng có thể khiến bằng lái của người lớn bị đình chỉ là bao nhiêu?","o":["1 điểm","4 điểm","8 điểm","12 điểm"],"h1":"Ít hơn tổng 6 điểm dùng cho thời gian 24 tháng.","h2":"Ở California, người lớn có 4 điểm trong hồ sơ trong 12 tháng có thể bị đình chỉ bằng lái.","p":"Đúng. 4 điểm trong 12 tháng có thể dẫn đến đình chỉ bằng lái."},"tl":{"q":"Sa California, ano ang pinakamababang bilang ng puntos sa loob ng 12 buwan na puwedeng magpasuspinde sa lisensya ng isang adulto?","o":["1 puntos","4 na puntos","8 puntos","12 puntos"],"h1":"Mas mababa ito sa kabuuang 6 na puntos na ginagamit para sa 24 na buwan.","h2":"Sa California, ang adultong may 4 na puntos sa rekord sa loob ng 12 buwan ay puwedeng masuspinde ang lisensya.","p":"Tama. Ang 4 na puntos sa loob ng 12 buwan ay puwedeng humantong sa suspensyon."},"ar":{"q":"في California، ما أقل عدد من النقاط خلال 12 شهرًا يمكن أن يؤدي إلى إيقاف رخصة شخص بالغ؟","o":["نقطة واحدة (1)","4 نقاط","8 نقاط","12 نقطة"],"h1":"هو أقل من مجموع 6 نقاط المستخدم لمدة 24 شهرًا.","h2":"في California، يمكن إيقاف رخصة الشخص البالغ إذا كان في سجلّه 4 نقاط خلال 12 شهرًا.","p":"صحيح. 4 نقاط خلال 12 شهرًا يمكن أن تؤدي إلى إيقاف الرخصة."},"ref":{"doc":"CA","page":54}},{"id":"ca-033","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a teen in the first year of a provisional license gets two tickets or at-fault crashes. What happens?","o":["Nothing until age 18","The license is taken away for one year","For 30 days, the teen may drive only with a licensed adult 25 or older","The teen must retake only the vision test"],"h1":"The teen can still drive, but not alone.","h2":"In California, two tickets or at-fault crashes in the first year mean the teen may drive for 30 days only with a licensed adult age 25 or older.","p":"Right. For 30 days, a licensed adult 25 or older must ride along."},"es":{"q":"En California, un joven en el primer año de su licencia provisional recibe dos multas o tiene dos choques por su culpa. ¿Qué pasa?","o":["Nada hasta los 18 años","Le quitan la licencia por un año","Por 30 días solo puede manejar con un adulto con licencia de 25 años o más","Solo debe repetir el examen de la vista"],"h1":"El joven todavía puede manejar, pero no solo.","h2":"En California, dos multas o choques por su culpa en el primer año significan que el joven puede manejar por 30 días solo con un adulto con licencia de 25 años o más.","p":"Correcto. Por 30 días debe ir con un adulto con licencia de 25 años o más."},"zh":{"q":"在 California，一个青少年在拿过渡驾照的第一年里收到两张罚单或发生两次自己有责任的车祸。会怎么样？","o":["到 18 岁以前都没事","驾照被收走一年","30 天内，这个青少年只能在 25 岁或以上的有驾照成年人陪同下开车","这个青少年只需要重考视力检查"],"h1":"这个青少年还可以开车，但不能一个人开。","h2":"在 California，第一年里有两张罚单或两次自己有责任的车祸，这个青少年在 30 天内只能在 25 岁或以上的有驾照成年人陪同下开车。","p":"对。30 天内必须有一位 25 岁或以上的有驾照成年人同车。"},"vi":{"q":"Ở California, một thiếu niên trong năm đầu có bằng lái tạm thời bị hai vé phạt hoặc gây ra hai tai nạn do lỗi của mình. Chuyện gì xảy ra?","o":["Không có gì cho đến 18 tuổi","Bằng lái bị thu một năm","Trong 30 ngày, thiếu niên chỉ được lái khi có một người lớn có bằng lái từ 25 tuổi trở lên","Thiếu niên chỉ phải thi lại phần kiểm tra thị lực"],"h1":"Thiếu niên vẫn được lái, nhưng không được lái một mình.","h2":"Ở California, hai vé phạt hoặc hai tai nạn do lỗi của mình trong năm đầu có nghĩa là trong 30 ngày thiếu niên chỉ được lái khi có một người lớn có bằng lái từ 25 tuổi trở lên.","p":"Đúng. Trong 30 ngày, phải có một người lớn có bằng lái từ 25 tuổi trở lên đi cùng."},"tl":{"q":"Sa California, ang isang tinedyer na nasa unang taon ng provisional license ay nakakuha ng dalawang tiket o dalawang banggaan na siya ang may kasalanan. Ano ang mangyayari?","o":["Wala hanggang edad 18","Kukunin ang lisensya nang isang taon","Sa loob ng 30 araw, puwede lang magmaneho ang tinedyer kung may kasamang may lisensyang adulto na 25 taong gulang pataas","Ang vision test lang ang uulitin ng tinedyer"],"h1":"Puwede pa ring magmaneho ang tinedyer, pero hindi nang mag-isa.","h2":"Sa California, kapag may dalawang tiket o dalawang banggaan na siya ang may kasalanan sa unang taon, puwede lang magmaneho ang tinedyer sa loob ng 30 araw kung may kasamang may lisensyang adulto na 25 taong gulang pataas.","p":"Tama. Sa loob ng 30 araw, dapat may kasamang may lisensyang adulto na 25 pataas."},"ar":{"q":"في California، مراهق في السنة الأولى من رخصته المؤقتة حصل على مخالفتين أو تسبّب في حادثين بخطئه. ماذا يحدث؟","o":["لا شيء حتى عمر 18","تُسحب الرخصة لمدة سنة","لمدة 30 يومًا، يمكن للمراهق أن يقود فقط مع شخص بالغ عمره 25 سنة أو أكثر ولديه رخصة","يجب على المراهق إعادة فحص النظر فقط"],"h1":"ما زال المراهق يستطيع القيادة، لكن ليس وحده.","h2":"في California، مخالفتان أو حادثان بخطئه في السنة الأولى يعنيان أن المراهق يمكنه القيادة لمدة 30 يومًا فقط مع شخص بالغ عمره 25 سنة أو أكثر ولديه رخصة.","p":"صحيح. لمدة 30 يومًا يجب أن يركب معه شخص بالغ عمره 25 سنة أو أكثر ولديه رخصة."},"ref":{"doc":"CA","page":55}},{"id":"ca-034","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a provisional driver has three tickets or at-fault crashes in the first year. What happens to the license?","o":["A warning letter only","A 30-day limit on night driving","A one-week suspension","A six-month suspension and one year of probation"],"h1":"It is the strictest of these choices.","h2":"In California, three tickets or at-fault crashes in a provisional driver's first year bring a six-month suspension and one year of probation.","p":"Right. Six months of suspension, then one year of probation."},"es":{"q":"En California, un conductor provisional tiene tres multas o choques por su culpa en el primer año. ¿Qué pasa con la licencia?","o":["Solo una carta de advertencia","Un límite de 30 días para manejar de noche","Una suspensión de una semana","Una suspensión de seis meses y un año de libertad condicional"],"h1":"Es la opción más estricta.","h2":"En California, tres multas o choques por su culpa en el primer año de un conductor provisional causan una suspensión de seis meses y un año de libertad condicional.","p":"Correcto. Seis meses de suspensión y luego un año de libertad condicional."},"zh":{"q":"在 California，一个过渡驾照驾驶人在第一年里有三张罚单或三次自己有责任的车祸。驾照会怎么样？","o":["只收到一封警告信","晚上开车受限 30 天","暂停一个星期","暂停六个月，再加一年观察期"],"h1":"它是这些选项中最严格的。","h2":"在 California，过渡驾照驾驶人在第一年里有三张罚单或三次自己有责任的车祸，会被暂停驾照六个月，再加一年观察期。","p":"对。暂停六个月，然后一年观察期。"},"vi":{"q":"Ở California, một người lái có bằng lái tạm thời bị ba vé phạt hoặc gây ra ba tai nạn do lỗi của mình trong năm đầu. Bằng lái sẽ ra sao?","o":["Chỉ có một thư cảnh cáo","Bị giới hạn lái ban đêm 30 ngày","Bị đình chỉ một tuần","Bị đình chỉ sáu tháng và thử thách một năm"],"h1":"Đây là lựa chọn nghiêm khắc nhất.","h2":"Ở California, ba vé phạt hoặc ba tai nạn do lỗi của mình trong năm đầu của người lái có bằng tạm thời dẫn đến đình chỉ bằng lái sáu tháng và thử thách một năm.","p":"Đúng. Đình chỉ sáu tháng, rồi thử thách một năm."},"tl":{"q":"Sa California, ang isang provisional driver ay may tatlong tiket o tatlong banggaan na siya ang may kasalanan sa unang taon. Ano ang mangyayari sa lisensya?","o":["Sulat ng babala lang","30 araw na limitasyon sa pagmamaneho sa gabi","Isang linggong suspensyon","Anim na buwang suspensyon at isang taong probation"],"h1":"Ito ang pinakamahigpit sa mga pagpipiliang ito.","h2":"Sa California, ang tatlong tiket o tatlong banggaan na kasalanan ng provisional driver sa unang taon ay nagdudulot ng anim na buwang suspensyon at isang taong probation.","p":"Tama. Anim na buwang suspensyon, tapos isang taong probation."},"ar":{"q":"في California، سائق برخصة مؤقتة حصل على ثلاث مخالفات أو تسبّب في ثلاثة حوادث بخطئه في السنة الأولى. ماذا يحدث للرخصة؟","o":["رسالة تحذير فقط","تقييد القيادة ليلًا لمدة 30 يومًا","إيقاف لمدة أسبوع","إيقاف لمدة ستة أشهر وفترة مراقبة لمدة سنة"],"h1":"هو أشدّ هذه الخيارات.","h2":"في California، ثلاث مخالفات أو ثلاثة حوادث بخطأ السائق في السنة الأولى من الرخصة المؤقتة تؤدي إلى إيقاف الرخصة ستة أشهر وفترة مراقبة لمدة سنة.","p":"صحيح. إيقاف ستة أشهر، ثم مراقبة لمدة سنة."},"ref":{"doc":"CA","page":55}},{"id":"ca-035","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, an officer thinks you are driving under the influence and you refuse a blood or urine test. What does the DMV do?","o":["Suspends or revokes your license for one year","Gives you a warning the first time","Suspends your license for one week","Nothing, because the test is optional"],"h1":"Refusing the test is treated very seriously.","h2":"In California, if you refuse a chemical test when an officer suspects DUI, the DMV suspends or revokes your license for one year.","p":"Right. Refusing the test costs you your license for one year."},"es":{"q":"En California, un oficial cree que usted maneja bajo la influencia y usted se niega a una prueba de sangre u orina. ¿Qué hace el DMV?","o":["Suspende o revoca su licencia por un año","Le da una advertencia la primera vez","Suspende su licencia por una semana","Nada, porque la prueba es opcional"],"h1":"Negarse a la prueba es algo muy serio.","h2":"En California, si usted se niega a una prueba química cuando un oficial sospecha que maneja bajo la influencia, el DMV suspende o revoca su licencia por un año.","p":"Correcto. Negarse a la prueba le quita la licencia por un año."},"zh":{"q":"在 California，警察认为你酒后或药后驾驶，而你拒绝验血或验尿。DMV 会怎么做？","o":["暂停或吊销你的驾照一年","第一次只给你警告","暂停你的驾照一个星期","什么都不做，因为检测是自愿的"],"h1":"拒绝检测会被看得很严重。","h2":"在 California，如果警察怀疑你酒后或药后驾驶（DUI）而你拒绝化学检测，DMV 会暂停或吊销你的驾照一年。","p":"对。拒绝检测会让你失去驾照一年。"},"vi":{"q":"Ở California, cảnh sát nghĩ rằng bạn đang lái xe khi say rượu hoặc dùng chất kích thích, và bạn từ chối xét nghiệm máu hoặc nước tiểu. DMV sẽ làm gì?","o":["Đình chỉ hoặc thu hồi bằng lái của bạn một năm","Cảnh cáo bạn lần đầu","Đình chỉ bằng lái của bạn một tuần","Không làm gì, vì xét nghiệm là tự nguyện"],"h1":"Từ chối xét nghiệm bị xem là rất nghiêm trọng.","h2":"Ở California, nếu bạn từ chối xét nghiệm hóa học khi cảnh sát nghi bạn lái xe khi say (DUI), DMV sẽ đình chỉ hoặc thu hồi bằng lái của bạn một năm.","p":"Đúng. Từ chối xét nghiệm làm bạn mất bằng lái một năm."},"tl":{"q":"Sa California, iniisip ng pulis na nagmamaneho ka nang lasing o nakadroga, at tumanggi ka sa blood o urine test. Ano ang gagawin ng DMV?","o":["Sususpindihin o babawiin ang lisensya mo nang isang taon","Bibigyan ka ng babala sa unang beses","Sususpindihin ang lisensya mo nang isang linggo","Wala, dahil hindi sapilitan ang test"],"h1":"Itinuturing na napakaseryoso ang pagtanggi sa test.","h2":"Sa California, kapag tumanggi ka sa chemical test habang pinaghihinalaan ka ng pulis ng DUI, sususpindihin o babawiin ng DMV ang lisensya mo nang isang taon.","p":"Tama. Ang pagtanggi sa test ay magpapawala sa lisensya mo nang isang taon."},"ar":{"q":"في California، يظن الشرطي أنك تقود تحت تأثير الكحول أو المخدرات، وأنت ترفض فحص الدم أو البول. ماذا تفعل DMV؟","o":["توقف رخصتك أو تلغيها لمدة سنة","تعطيك تحذيرًا في المرة الأولى","توقف رخصتك لمدة أسبوع","لا شيء، لأن الفحص اختياري"],"h1":"رفض الفحص يُعامَل بجدّية كبيرة.","h2":"في California، إذا رفضت الفحص الكيميائي عندما يشكّ الشرطي في أنك تقود تحت التأثير (DUI)، توقف DMV رخصتك أو تلغيها لمدة سنة.","p":"صحيح. رفض الفحص يُفقدك رخصتك لمدة سنة."},"ref":{"doc":"CA","page":72}},{"id":"ca-036","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, after a DUI arrest, how soon must you ask for a DMV hearing?","o":["Within 24 hours","Within 10 days of the arrest","Within 6 months","Only after a court trial"],"h1":"It is a short window, well under a month.","h2":"In California, you may ask for a DMV administrative hearing within 10 days from the date of a DUI arrest.","p":"Right. Ask for the hearing within 10 days of the arrest."},"es":{"q":"En California, después de un arresto por manejar bajo la influencia, ¿en cuánto tiempo debe pedir una audiencia del DMV?","o":["En 24 horas","En 10 días desde el arresto","En 6 meses","Solo después de un juicio"],"h1":"Es un plazo corto, mucho menos de un mes.","h2":"En California, usted puede pedir una audiencia administrativa del DMV dentro de los 10 días desde la fecha del arresto por manejar bajo la influencia.","p":"Correcto. Pida la audiencia dentro de 10 días después del arresto."},"zh":{"q":"在 California，因酒后或药后驾驶（DUI）被捕后，你必须在多久之内申请 DMV 听证？","o":["24 小时内","被捕后 10 天内","6 个月内","只能在法院审判以后"],"h1":"时间很短，远不到一个月。","h2":"在 California，你可以在 DUI 被捕那天起 10 天内申请 DMV 行政听证。","p":"对。在被捕后 10 天内申请听证。"},"vi":{"q":"Ở California, sau khi bị bắt vì lái xe khi say (DUI), bạn phải yêu cầu một buổi điều trần của DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 10 ngày kể từ khi bị bắt","Trong vòng 6 tháng","Chỉ sau phiên tòa"],"h1":"Đó là một khoảng thời gian ngắn, ít hơn nhiều so với một tháng.","h2":"Ở California, bạn có thể yêu cầu một buổi điều trần hành chính của DMV trong vòng 10 ngày kể từ ngày bị bắt vì DUI.","p":"Đúng. Yêu cầu điều trần trong vòng 10 ngày sau khi bị bắt."},"tl":{"q":"Sa California, pagkatapos maaresto dahil sa DUI, gaano kabilis ka dapat humiling ng hearing sa DMV?","o":["Sa loob ng 24 na oras","Sa loob ng 10 araw mula sa pagkaaresto","Sa loob ng 6 na buwan","Pagkatapos lang ng paglilitis sa korte"],"h1":"Maikli ang panahon, mas maikli pa sa isang buwan.","h2":"Sa California, puwede kang humiling ng administrative hearing sa DMV sa loob ng 10 araw mula sa araw ng pagkaaresto dahil sa DUI.","p":"Tama. Humiling ng hearing sa loob ng 10 araw mula sa pagkaaresto."},"ar":{"q":"في California، بعد القبض عليك بسبب القيادة تحت التأثير (DUI)، خلال كم من الوقت يجب أن تطلب جلسة استماع من DMV؟","o":["خلال 24 ساعة","خلال 10 أيام من القبض عليك","خلال 6 أشهر","فقط بعد محاكمة في المحكمة"],"h1":"هي مدة قصيرة، أقل بكثير من شهر.","h2":"في California، يمكنك أن تطلب جلسة استماع إدارية من DMV خلال 10 أيام من تاريخ القبض عليك بسبب DUI.","p":"صحيح. اطلب الجلسة خلال 10 أيام من القبض عليك."},"ref":{"doc":"CA","page":74}},{"id":"ca-037","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, you are in a crash and you do not have the required insurance. What can happen to your license?","o":["Nothing, if the crash was not your fault","A 10-day suspension","Suspension for up to four years","A fine only, with no suspension"],"h1":"It does not matter who caused the crash.","h2":"In California, driving without proper insurance and being in a crash can get your license suspended for up to four years, no matter who was at fault.","p":"Right. Up to four years of suspension, even if you were not at fault."},"es":{"q":"En California, usted tiene un choque y no tiene el seguro requerido. ¿Qué le puede pasar a su licencia?","o":["Nada, si el choque no fue su culpa","Una suspensión de 10 días","Una suspensión de hasta cuatro años","Solo una multa, sin suspensión"],"h1":"No importa quién causó el choque.","h2":"En California, manejar sin el seguro correcto y tener un choque puede causar la suspensión de su licencia hasta por cuatro años, sin importar quién tuvo la culpa.","p":"Correcto. Hasta cuatro años de suspensión, aunque no haya sido su culpa."},"zh":{"q":"在 California，你发生了车祸，而你没有规定的保险。你的驾照可能会怎么样？","o":["如果车祸不是你的错，就没事","暂停 10 天","暂停最多四年","只罚款，不暂停"],"h1":"是谁造成车祸都没有关系。","h2":"在 California，没有合格的保险开车又发生车祸，你的驾照可能会被暂停最多四年，不管是谁的错。","p":"对。最多暂停四年，即使不是你的错。"},"vi":{"q":"Ở California, bạn bị tai nạn và bạn không có bảo hiểm bắt buộc. Bằng lái của bạn có thể bị gì?","o":["Không có gì, nếu tai nạn không phải lỗi của bạn","Bị đình chỉ 10 ngày","Bị đình chỉ đến bốn năm","Chỉ bị phạt tiền, không bị đình chỉ"],"h1":"Ai gây ra tai nạn cũng không quan trọng.","h2":"Ở California, lái xe không có bảo hiểm đúng quy định và bị tai nạn có thể khiến bằng lái của bạn bị đình chỉ đến bốn năm, dù lỗi là của ai.","p":"Đúng. Đình chỉ đến bốn năm, kể cả khi không phải lỗi của bạn."},"tl":{"q":"Sa California, nabangga ka at wala kang kinakailangang insurance. Ano ang puwedeng mangyari sa lisensya mo?","o":["Wala, kung hindi mo kasalanan ang banggaan","10 araw na suspensyon","Suspensyon nang hanggang apat na taon","Multa lang, walang suspensyon"],"h1":"Hindi mahalaga kung sino ang nagdulot ng banggaan.","h2":"Sa California, ang pagmamaneho nang walang tamang insurance at pagkakaroon ng banggaan ay puwedeng magpasuspinde sa lisensya mo nang hanggang apat na taon, kahit sino pa ang may kasalanan.","p":"Tama. Hanggang apat na taong suspensyon, kahit hindi mo kasalanan."},"ar":{"q":"في California، تعرّضت لحادث وليس لديك التأمين المطلوب. ماذا يمكن أن يحدث لرخصتك؟","o":["لا شيء، إذا لم يكن الحادث بخطئك","إيقاف لمدة 10 أيام","إيقاف لمدة تصل إلى أربع سنوات","غرامة فقط، بدون إيقاف"],"h1":"لا يهمّ من تسبّب في الحادث.","h2":"في California، القيادة بدون التأمين المطلوب والتعرّض لحادث يمكن أن يؤديا إلى إيقاف رخصتك لمدة تصل إلى أربع سنوات، مهما كان المخطئ.","p":"صحيح. إيقاف يصل إلى أربع سنوات، حتى لو لم يكن الخطأ خطأك."},"ref":{"doc":"CA","page":76}},{"id":"ca-038","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a crash causes more than $1,000 in damage. What must each driver do?","o":["Nothing, if police came to the scene","Call the DMV within one hour","Report it only to their insurance company","File a report (SR 1) with the DMV within 10 days"],"h1":"The police report does not count for you.","h2":"In California, each driver must file an SR 1 report with the DMV within 10 days when a crash causes more than $1,000 in damage or anyone is hurt.","p":"Right. File the SR 1 with the DMV within 10 days."},"es":{"q":"En California, un choque causa más de $1,000 en daños. ¿Qué debe hacer cada conductor?","o":["Nada, si la policía llegó al lugar","Llamar al DMV dentro de una hora","Avisar solo a su compañía de seguros","Enviar un reporte (SR 1) al DMV dentro de 10 días"],"h1":"El reporte de la policía no cuenta por usted.","h2":"En California, cada conductor debe enviar un reporte SR 1 al DMV dentro de 10 días cuando un choque causa más de $1,000 en daños o alguien sale herido.","p":"Correcto. Envíe el SR 1 al DMV dentro de 10 días."},"zh":{"q":"在 California，一场车祸造成超过 $1,000 的损失。每位驾驶人必须做什么？","o":["如果警察来过现场，就什么都不用做","在一小时内打电话给 DMV","只报告给自己的保险公司","在 10 天内向 DMV 提交报告（SR 1）"],"h1":"警察的报告不能代替你的报告。","h2":"在 California，车祸造成超过 $1,000 的损失或有人受伤时，每位驾驶人都必须在 10 天内向 DMV 提交 SR 1 报告。","p":"对。在 10 天内向 DMV 提交 SR 1。"},"vi":{"q":"Ở California, một tai nạn gây thiệt hại hơn $1,000. Mỗi người lái phải làm gì?","o":["Không làm gì, nếu cảnh sát đã đến hiện trường","Gọi DMV trong vòng một giờ","Chỉ báo cho công ty bảo hiểm của mình","Nộp báo cáo (SR 1) cho DMV trong vòng 10 ngày"],"h1":"Báo cáo của cảnh sát không thay cho báo cáo của bạn.","h2":"Ở California, mỗi người lái phải nộp báo cáo SR 1 cho DMV trong vòng 10 ngày khi tai nạn gây thiệt hại hơn $1,000 hoặc có người bị thương.","p":"Đúng. Nộp SR 1 cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa California, ang isang banggaan ay nagdulot ng higit sa $1,000 na pinsala. Ano ang dapat gawin ng bawat driver?","o":["Wala, kung dumating ang pulis sa lugar","Tawagan ang DMV sa loob ng isang oras","I-report lang ito sa kanilang insurance company","Mag-file ng report (SR 1) sa DMV sa loob ng 10 araw"],"h1":"Hindi binibilang para sa iyo ang report ng pulis.","h2":"Sa California, dapat mag-file ang bawat driver ng SR 1 report sa DMV sa loob ng 10 araw kapag ang banggaan ay nagdulot ng higit sa $1,000 na pinsala o may nasaktan.","p":"Tama. Mag-file ng SR 1 sa DMV sa loob ng 10 araw."},"ar":{"q":"في California، حادث سبّب أضرارًا بأكثر من $1,000. ماذا يجب على كل سائق أن يفعل؟","o":["لا شيء، إذا جاءت الشرطة إلى المكان","الاتصال بـ DMV خلال ساعة واحدة","الإبلاغ لشركة التأمين فقط","تقديم تقرير (SR 1) إلى DMV خلال 10 أيام"],"h1":"تقرير الشرطة لا يُحسب بدلًا منك.","h2":"في California، يجب على كل سائق أن يقدّم تقرير SR 1 إلى DMV خلال 10 أيام عندما يسبّب الحادث أضرارًا بأكثر من $1,000 أو يُصاب أي شخص.","p":"صحيح. قدّم SR 1 إلى DMV خلال 10 أيام."},"ref":{"doc":"CA","page":78}},{"id":"ca-039","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, a child is 6 years old and 4 feet tall. How must the child ride?","o":["In a child safety seat in the back seat","With a regular seat belt in the front seat","On an adult's lap with a seat belt","With a lap belt only, in any seat"],"h1":"Children under 8 or shorter than 4 feet 9 inches need more than a seat belt.","h2":"In California, a child under 8 years old, or shorter than 4 feet 9 inches, must ride in a child safety seat in the back seat.","p":"Right. Under 8 or under 4 feet 9 inches means a child seat in the back."},"es":{"q":"En California, un niño tiene 6 años y mide 4 pies. ¿Cómo debe viajar?","o":["En un asiento de seguridad para niños en el asiento trasero","Con un cinturón normal en el asiento delantero","En las piernas de un adulto con cinturón","Solo con el cinturón de cadera, en cualquier asiento"],"h1":"Los niños menores de 8 años o de menos de 4 pies 9 pulgadas necesitan más que un cinturón.","h2":"En California, un niño menor de 8 años, o que mide menos de 4 pies 9 pulgadas, debe viajar en un asiento de seguridad para niños en el asiento trasero.","p":"Correcto. Menor de 8 años o de menos de 4 pies 9 pulgadas: asiento para niños atrás."},"zh":{"q":"在 California，一个孩子 6 岁，身高 4 英尺。这个孩子必须怎样坐车？","o":["坐在后座的儿童安全座椅里","在前座系普通安全带","坐在大人腿上并系安全带","在任何座位只系腰带"],"h1":"不到 8 岁或身高不到 4 英尺 9 英寸的孩子需要的不只是安全带。","h2":"在 California，不到 8 岁或身高不到 4 英尺 9 英寸的孩子必须坐在后座的儿童安全座椅里。","p":"对。不到 8 岁或不到 4 英尺 9 英寸，就要坐后座的儿童座椅。"},"vi":{"q":"Ở California, một đứa trẻ 6 tuổi và cao 4 feet. Đứa trẻ phải ngồi xe như thế nào?","o":["Trong ghế an toàn cho trẻ em ở ghế sau","Với dây an toàn thường ở ghế trước","Ngồi trên đùi người lớn có thắt dây an toàn","Chỉ với dây đai ngang hông, ở bất kỳ ghế nào"],"h1":"Trẻ dưới 8 tuổi hoặc thấp hơn 4 feet 9 inch cần nhiều hơn dây an toàn.","h2":"Ở California, trẻ dưới 8 tuổi, hoặc thấp hơn 4 feet 9 inch, phải ngồi trong ghế an toàn cho trẻ em ở ghế sau.","p":"Đúng. Dưới 8 tuổi hoặc dưới 4 feet 9 inch thì ngồi ghế trẻ em ở phía sau."},"tl":{"q":"Sa California, ang isang bata ay 6 na taong gulang at 4 feet ang taas. Paano dapat sumakay ang bata?","o":["Sa child safety seat sa likurang upuan","Na may karaniwang seat belt sa harapang upuan","Sa kandungan ng adulto na may seat belt","Na lap belt lang, sa kahit anong upuan"],"h1":"Ang mga batang wala pang 8 o mas maliit sa 4 feet 9 inches ay nangangailangan ng higit pa sa seat belt.","h2":"Sa California, ang batang wala pang 8 taong gulang, o mas maliit sa 4 feet 9 inches, ay dapat sumakay sa child safety seat sa likurang upuan.","p":"Tama. Wala pang 8 o wala pang 4 feet 9 inches ay child seat sa likod."},"ar":{"q":"في California، طفل عمره 6 سنوات وطوله 4 أقدام. كيف يجب أن يركب الطفل؟","o":["في مقعد أمان للأطفال في المقعد الخلفي","بحزام أمان عادي في المقعد الأمامي","في حضن شخص بالغ مع حزام أمان","بحزام الحِجر فقط، في أي مقعد"],"h1":"الأطفال تحت 8 سنوات أو الأقصر من 4 أقدام و9 بوصات يحتاجون أكثر من حزام الأمان.","h2":"في California، يجب على الطفل الذي عمره أقل من 8 سنوات، أو طوله أقل من 4 أقدام و9 بوصات، أن يركب في مقعد أمان للأطفال في المقعد الخلفي.","p":"صحيح. أقل من 8 سنوات أو أقل من 4 أقدام و9 بوصات يعني مقعد أطفال في الخلف."},"ref":{"doc":"CA","page":66}},{"id":"ca-040","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a child is under 2 years old, under 40 pounds and under 3 feet 4 inches tall. How must the child ride?","o":["In a forward-facing booster seat","In a rear-facing child seat","With a regular seat belt","In a front seat with an airbag"],"h1":"The child faces the back of the car.","h2":"In California, a child under 2 who is under 40 pounds and under 3 feet 4 inches tall must ride in a rear-facing child seat.","p":"Right. Babies and toddlers this small ride rear-facing."},"es":{"q":"En California, un niño tiene menos de 2 años, pesa menos de 40 libras y mide menos de 3 pies 4 pulgadas. ¿Cómo debe viajar?","o":["En un asiento elevado mirando hacia adelante","En un asiento para niños mirando hacia atrás","Con un cinturón de seguridad normal","En un asiento delantero con bolsa de aire"],"h1":"El niño mira hacia la parte de atrás del carro.","h2":"En California, un niño menor de 2 años que pesa menos de 40 libras y mide menos de 3 pies 4 pulgadas debe viajar en un asiento para niños mirando hacia atrás.","p":"Correcto. Los niños tan pequeños viajan mirando hacia atrás."},"zh":{"q":"在 California，一个孩子不到 2 岁、不到 40 磅，身高不到 3 英尺 4 英寸。这个孩子必须怎样坐车？","o":["坐在面向前方的增高座椅里","坐在面向后方的儿童座椅里","系普通安全带","坐在有安全气囊的前座"],"h1":"孩子面向车的后面。","h2":"在 California，不到 2 岁、不到 40 磅且身高不到 3 英尺 4 英寸的孩子必须坐在面向后方的儿童座椅里。","p":"对。这么小的婴幼儿要面向后方坐。"},"vi":{"q":"Ở California, một đứa trẻ dưới 2 tuổi, nặng dưới 40 pound và cao dưới 3 feet 4 inch. Đứa trẻ phải ngồi xe như thế nào?","o":["Trong ghế nâng quay về phía trước","Trong ghế trẻ em quay về phía sau","Với dây an toàn thường","Ở ghế trước có túi khí"],"h1":"Đứa trẻ quay mặt về phía sau xe.","h2":"Ở California, trẻ dưới 2 tuổi, nặng dưới 40 pound và cao dưới 3 feet 4 inch phải ngồi trong ghế trẻ em quay về phía sau.","p":"Đúng. Trẻ nhỏ như vậy phải ngồi quay về phía sau."},"tl":{"q":"Sa California, ang isang bata ay wala pang 2 taong gulang, wala pang 40 pounds at wala pang 3 feet 4 inches ang taas. Paano dapat sumakay ang bata?","o":["Sa booster seat na nakaharap sa unahan","Sa child seat na nakaharap sa likod","Na may karaniwang seat belt","Sa harapang upuan na may airbag"],"h1":"Nakaharap ang bata sa likod ng kotse.","h2":"Sa California, ang batang wala pang 2 taong gulang na wala pang 40 pounds at wala pang 3 feet 4 inches ang taas ay dapat sumakay sa child seat na nakaharap sa likod.","p":"Tama. Ang mga sanggol at batang ganito kaliit ay nakaharap sa likod."},"ar":{"q":"في California، طفل عمره أقل من سنتين (2)، ووزنه أقل من 40 رطلًا، وطوله أقل من 3 أقدام و4 بوصات. كيف يجب أن يركب الطفل؟","o":["في مقعد رافع مواجه للأمام","في مقعد أطفال مواجه للخلف","بحزام أمان عادي","في مقعد أمامي فيه وسادة هوائية"],"h1":"يكون وجه الطفل نحو خلف السيارة.","h2":"في California، يجب على الطفل الذي عمره أقل من سنتين (2) ووزنه أقل من 40 رطلًا وطوله أقل من 3 أقدام و4 بوصات أن يركب في مقعد أطفال مواجه للخلف.","p":"صحيح. الأطفال الصغار بهذا الحجم يركبون ووجوههم للخلف."},"ref":{"doc":"CA","page":66}},{"id":"ca-041","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, a child of what age may not be left alone in a car?","o":["Only a baby under 1","Only a child under 3","A child 6 years old or younger","A child 10 years old or younger"],"h1":"The child may stay with someone age 12 or older.","h2":"In California, it is illegal to leave a child 6 years old or younger alone in a vehicle unless a person at least 12 years old is watching the child.","p":"Right. Never leave a child 6 or younger alone in the car."},"es":{"q":"En California, ¿a un niño de qué edad no se le puede dejar solo en un carro?","o":["Solo a un bebé menor de 1 año","Solo a un niño menor de 3 años","A un niño de 6 años o menos","A un niño de 10 años o menos"],"h1":"El niño puede quedarse con alguien de 12 años o más.","h2":"En California, es ilegal dejar solo en un vehículo a un niño de 6 años o menos, a menos que lo cuide una persona de por lo menos 12 años.","p":"Correcto. Nunca deje solo en el carro a un niño de 6 años o menos."},"zh":{"q":"在 California，多大的孩子不可以一个人留在车里？","o":["只有不到 1 岁的婴儿","只有不到 3 岁的孩子","6 岁或更小的孩子","10 岁或更小的孩子"],"h1":"孩子可以和 12 岁或以上的人待在一起。","h2":"在 California，把 6 岁或更小的孩子单独留在车里是违法的，除非有一个至少 12 岁的人在看着孩子。","p":"对。绝不要把 6 岁或更小的孩子单独留在车里。"},"vi":{"q":"Ở California, trẻ ở độ tuổi nào thì không được để một mình trong xe?","o":["Chỉ em bé dưới 1 tuổi","Chỉ trẻ dưới 3 tuổi","Trẻ 6 tuổi trở xuống","Trẻ 10 tuổi trở xuống"],"h1":"Đứa trẻ có thể ở lại với người từ 12 tuổi trở lên.","h2":"Ở California, để trẻ 6 tuổi trở xuống một mình trong xe là phạm luật, trừ khi có một người ít nhất 12 tuổi trông chừng đứa trẻ.","p":"Đúng. Không bao giờ để trẻ 6 tuổi trở xuống một mình trong xe."},"tl":{"q":"Sa California, ilang taong gulang na bata ang hindi puwedeng iwanang mag-isa sa kotse?","o":["Sanggol lang na wala pang 1","Bata lang na wala pang 3","Batang 6 na taong gulang pababa","Batang 10 taong gulang pababa"],"h1":"Puwedeng maiwan ang bata kasama ang taong 12 taong gulang pataas.","h2":"Sa California, labag sa batas na iwanang mag-isa sa sasakyan ang batang 6 na taong gulang pababa maliban kung may taong hindi bababa sa 12 taong gulang na nagbabantay sa bata.","p":"Tama. Huwag kailanman iwanang mag-isa sa kotse ang batang 6 pababa."},"ar":{"q":"في California، الطفل الذي في أي عمر لا يجوز تركه وحده في السيارة؟","o":["الرضيع تحت سنة واحدة (1) فقط","الطفل تحت 3 سنوات فقط","الطفل الذي عمره 6 سنوات أو أقل","الطفل الذي عمره 10 سنوات أو أقل"],"h1":"يمكن أن يبقى الطفل مع شخص عمره 12 سنة أو أكثر.","h2":"في California، ترك طفل عمره 6 سنوات أو أقل وحده في السيارة مخالف للقانون، إلا إذا كان شخص عمره 12 سنة على الأقل يراقب الطفل.","p":"صحيح. لا تترك أبدًا طفلًا عمره 6 سنوات أو أقل وحده في السيارة."},"ref":{"doc":"CA","page":67}},{"id":"ca-042","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, what is the rule about headsets or earplugs while driving?","o":["You may wear them in both ears at low volume","You may wear them only on the freeway","You may wear them only during the day","You may not wear them in both ears"],"h1":"You must be able to hear sirens and horns.","h2":"In California, it is illegal to drive while wearing a headset or earplugs in both ears.","p":"Right. Never cover both ears while you drive."},"es":{"q":"En California, ¿cuál es la regla sobre audífonos o tapones para los oídos al manejar?","o":["Puede usarlos en los dos oídos con volumen bajo","Puede usarlos solo en la autopista","Puede usarlos solo durante el día","No puede usarlos en los dos oídos"],"h1":"Usted debe poder oír sirenas y bocinas.","h2":"En California, es ilegal manejar con audífonos o tapones en los dos oídos.","p":"Correcto. Nunca se tape los dos oídos mientras maneja."},"zh":{"q":"在 California，开车时戴耳机或耳塞有什么规定？","o":["两只耳朵都可以戴，只要音量小","只有在高速公路上可以戴","只有白天可以戴","两只耳朵不可以都戴"],"h1":"你必须能听到警笛和喇叭声。","h2":"在 California，开车时两只耳朵都戴着耳机或耳塞是违法的。","p":"对。开车时绝不要把两只耳朵都盖住。"},"vi":{"q":"Ở California, quy định về tai nghe hoặc nút bịt tai khi lái xe là gì?","o":["Bạn có thể đeo ở cả hai tai với âm lượng nhỏ","Bạn chỉ có thể đeo trên xa lộ","Bạn chỉ có thể đeo vào ban ngày","Bạn không được đeo ở cả hai tai"],"h1":"Bạn phải nghe được còi xe cứu thương và còi xe.","h2":"Ở California, lái xe khi đeo tai nghe hoặc nút bịt tai ở cả hai tai là phạm luật.","p":"Đúng. Không bao giờ che cả hai tai khi lái xe."},"tl":{"q":"Sa California, ano ang patakaran tungkol sa headset o earplugs habang nagmamaneho?","o":["Puwede mong isuot sa dalawang tainga kung mahina ang volume","Puwede mo lang isuot sa freeway","Puwede mo lang isuot sa araw","Hindi mo puwedeng isuot sa dalawang tainga"],"h1":"Dapat mong marinig ang mga sirena at busina.","h2":"Sa California, labag sa batas ang magmaneho nang may suot na headset o earplugs sa dalawang tainga.","p":"Tama. Huwag kailanman takpan ang dalawang tainga habang nagmamaneho."},"ar":{"q":"في California، ما القاعدة بشأن سماعات الرأس أو سدّادات الأذن أثناء القيادة؟","o":["يمكنك لبسها في الأذنين بصوت منخفض","يمكنك لبسها على الطريق السريع فقط","يمكنك لبسها في النهار فقط","يجب ألّا تلبسها في الأذنين الاثنتين"],"h1":"يجب أن تستطيع سماع صفارات الإنذار والأبواق.","h2":"في California، القيادة مع لبس سماعات الرأس أو سدّادات الأذن في الأذنين الاثنتين مخالفة للقانون.","p":"صحيح. لا تغطِّ أذنيك الاثنتين أبدًا وأنت تقود."},"ref":{"doc":"CA","page":9}},{"id":"ca-043","scope":"CA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In California, how close may you follow a fire engine or ambulance that has its siren or flashing lights on?","o":["No closer than 300 feet","No closer than 50 feet","No closer than 100 feet","As close as you like if traffic is light"],"h1":"It is about the length of a football field.","h2":"In California, it is against the law to follow within 300 feet of an emergency vehicle that has its siren or flashing lights on.","p":"Right. Stay at least 300 feet behind it."},"es":{"q":"En California, ¿qué tan cerca puede seguir a un camión de bomberos o una ambulancia con la sirena o las luces encendidas?","o":["A no menos de 300 pies","A no menos de 50 pies","A no menos de 100 pies","Tan cerca como quiera si hay poco tráfico"],"h1":"Es más o menos el largo de una cancha de fútbol americano.","h2":"En California, es ilegal seguir a menos de 300 pies a un vehículo de emergencia que tiene la sirena o las luces encendidas.","p":"Correcto. Quédese por lo menos a 300 pies detrás."},"zh":{"q":"在 California，消防车或救护车开着警笛或闪灯时，你最近可以跟在它后面多远？","o":["不能比 300 英尺更近","不能比 50 英尺更近","不能比 100 英尺更近","如果车不多，想多近都可以"],"h1":"大约是一个足球场的长度。","h2":"在 California，跟在开着警笛或闪灯的紧急车辆后面 300 英尺以内是违法的。","p":"对。至少在它后面 300 英尺。"},"vi":{"q":"Ở California, bạn được đi theo sau xe cứu hỏa hoặc xe cứu thương đang bật còi hoặc đèn nhấp nháy gần đến mức nào?","o":["Không gần hơn 300 feet","Không gần hơn 50 feet","Không gần hơn 100 feet","Gần bao nhiêu cũng được nếu ít xe"],"h1":"Khoảng chiều dài một sân bóng bầu dục.","h2":"Ở California, đi theo trong vòng 300 feet sau một xe khẩn cấp đang bật còi hoặc đèn nhấp nháy là phạm luật.","p":"Đúng. Giữ khoảng cách ít nhất 300 feet phía sau."},"tl":{"q":"Sa California, gaano kalapit ka puwedeng sumunod sa fire truck o ambulansya na nakabukas ang sirena o kumikislap na ilaw?","o":["Hindi lalapit sa 300 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 100 feet","Kahit gaano kalapit kung kaunti ang trapiko"],"h1":"Halos kasinghaba ito ng isang football field.","h2":"Sa California, labag sa batas ang sumunod sa loob ng 300 feet sa emergency vehicle na nakabukas ang sirena o kumikislap na ilaw.","p":"Tama. Manatili nang hindi bababa sa 300 feet sa likod nito."},"ar":{"q":"في California، إلى أي مدى يمكنك أن تقترب وأنت تسير خلف سيارة إطفاء أو إسعاف صفارتها أو أضواؤها الوامضة تعمل؟","o":["ليس أقرب من 300 قدم","ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","بقدر ما تريد إذا كانت حركة السير خفيفة"],"h1":"هي تقريبًا طول ملعب كرة قدم أمريكية.","h2":"في California، السير خلف مركبة طوارئ صفارتها أو أضواؤها الوامضة تعمل على مسافة أقل من 300 قدم مخالف للقانون.","p":"صحيح. ابقَ خلفها بمسافة 300 قدم على الأقل."},"ref":{"doc":"CA","page":45}},{"id":"ca-044","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, how far may you drive in a center left turn lane?","o":["Up to 50 feet","Up to 200 feet","Up to half a mile","As far as you need"],"h1":"It is not a lane for traveling or passing.","h2":"In California, you may drive no more than 200 feet in a center left turn lane before you turn.","p":"Right. Use it for at most 200 feet."},"es":{"q":"En California, ¿qué distancia puede manejar en un carril central para dar vuelta a la izquierda?","o":["Hasta 50 pies","Hasta 200 pies","Hasta media milla","Toda la que necesite"],"h1":"No es un carril para viajar ni para rebasar.","h2":"En California, usted puede manejar no más de 200 pies en un carril central para dar vuelta a la izquierda antes de dar la vuelta.","p":"Correcto. Úselo por 200 pies como máximo."},"zh":{"q":"在 California，你在中央左转车道里最多可以开多远？","o":["最多 50 英尺","最多 200 英尺","最多半英里","需要多远就开多远"],"h1":"它不是用来行驶或超车的车道。","h2":"在 California，你在转弯前在中央左转车道里最多只能开 200 英尺。","p":"对。最多使用 200 英尺。"},"vi":{"q":"Ở California, bạn được chạy bao xa trong làn rẽ trái ở giữa đường?","o":["Tối đa 50 feet","Tối đa 200 feet","Tối đa nửa dặm","Bao xa tùy bạn cần"],"h1":"Đó không phải là làn để chạy hoặc vượt xe.","h2":"Ở California, bạn chỉ được chạy tối đa 200 feet trong làn rẽ trái ở giữa đường trước khi rẽ.","p":"Đúng. Dùng nó tối đa 200 feet."},"tl":{"q":"Sa California, gaano kalayo ka puwedeng magmaneho sa center left turn lane?","o":["Hanggang 50 feet","Hanggang 200 feet","Hanggang kalahating milya","Kahit gaano kalayo ang kailangan mo"],"h1":"Hindi ito lane para bumiyahe o mag-overtake.","h2":"Sa California, hindi ka puwedeng magmaneho nang higit sa 200 feet sa center left turn lane bago ka lumiko.","p":"Tama. Gamitin ito nang hindi hihigit sa 200 feet."},"ar":{"q":"في California، ما أقصى مسافة يمكنك أن تقودها في حارة الانعطاف لليسار في الوسط؟","o":["حتى 50 قدمًا","حتى 200 قدم","حتى نصف ميل","بقدر ما تحتاج"],"h1":"ليست حارة للسير أو للتجاوز.","h2":"في California، يمكنك أن تقود 200 قدم على الأكثر في حارة الانعطاف لليسار في الوسط قبل أن تنعطف.","p":"صحيح. استخدمها لمسافة 200 قدم على الأكثر."},"ref":{"doc":"CA","page":16}},{"id":"ca-045","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, you are driving slowly on a two-lane road where passing is unsafe. When must you use a turnout to let cars pass?","o":["Whenever one car is behind you","Only at night","When five or more vehicles are following you","Only when a police officer tells you"],"h1":"Count the line of cars behind you.","h2":"In California, a slow driver on a two-lane road where passing is unsafe must use a turnout when five or more vehicles are following.","p":"Right. Five or more cars behind you means use the turnout."},"es":{"q":"En California, usted maneja despacio en una carretera de dos carriles donde no es seguro rebasar. ¿Cuándo debe usar un área de salida (turnout) para dejar pasar a otros?","o":["Siempre que haya un carro detrás","Solo de noche","Cuando lo siguen cinco vehículos o más","Solo cuando un policía se lo pide"],"h1":"Cuente la fila de carros detrás de usted.","h2":"En California, un conductor lento en una carretera de dos carriles donde no es seguro rebasar debe usar un área de salida cuando lo siguen cinco vehículos o más.","p":"Correcto. Con cinco carros o más detrás, use el área de salida."},"zh":{"q":"在 California，你在一条不安全超车的双车道道路上开得很慢。你什么时候必须开进让车区（turnout）让其他车超过？","o":["只要后面有一辆车","只在晚上","当有五辆或更多车跟在你后面时","只在警察叫你时"],"h1":"数一数你后面排了几辆车。","h2":"在 California，在不安全超车的双车道道路上，开得慢的驾驶人在有五辆或更多车跟在后面时，必须开进让车区。","p":"对。后面有五辆或更多车，就开进让车区。"},"vi":{"q":"Ở California, bạn đang chạy chậm trên đường hai làn nơi vượt xe không an toàn. Khi nào bạn phải tấp vào chỗ tránh xe (turnout) để cho xe khác vượt?","o":["Bất cứ khi nào có một xe phía sau","Chỉ vào ban đêm","Khi có năm xe trở lên đang theo sau bạn","Chỉ khi cảnh sát bảo bạn"],"h1":"Hãy đếm hàng xe phía sau bạn.","h2":"Ở California, người lái chậm trên đường hai làn nơi vượt xe không an toàn phải tấp vào chỗ tránh xe khi có năm xe trở lên đang theo sau.","p":"Đúng. Có năm xe trở lên phía sau thì tấp vào chỗ tránh xe."},"tl":{"q":"Sa California, mabagal kang nagmamaneho sa two-lane na kalsada kung saan hindi ligtas mag-overtake. Kailan mo dapat gamitin ang turnout para makalampas ang ibang kotse?","o":["Tuwing may isang kotse sa likod mo","Sa gabi lang","Kapag lima o higit pang sasakyan ang sumusunod sa iyo","Kapag sinabi lang ng pulis"],"h1":"Bilangin ang hanay ng mga kotse sa likod mo.","h2":"Sa California, ang mabagal na driver sa two-lane na kalsada kung saan hindi ligtas mag-overtake ay dapat gumamit ng turnout kapag lima o higit pang sasakyan ang sumusunod.","p":"Tama. Lima o higit pang kotse sa likod mo ay nangangahulugang gamitin ang turnout."},"ar":{"q":"في California، أنت تقود ببطء على طريق بحارتين لا يكون التجاوز فيه آمنًا. متى يجب أن تدخل إلى مكان الانتظار الجانبي (turnout) لتترك السيارات تتجاوزك؟","o":["كلما كانت سيارة واحدة خلفك","في الليل فقط","عندما تكون خمس مركبات أو أكثر خلفك","فقط عندما يطلب منك شرطي ذلك"],"h1":"عُدّ صفّ السيارات خلفك.","h2":"في California، يجب على السائق البطيء على طريق بحارتين لا يكون التجاوز فيه آمنًا أن يدخل إلى مكان الانتظار الجانبي عندما تكون خمس مركبات أو أكثر خلفه.","p":"صحيح. خمس سيارات أو أكثر خلفك تعني أن تدخل إلى مكان الانتظار الجانبي."},"ref":{"doc":"CA","page":16}},{"id":"ca-046","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, you cannot change lanes to pass a bicycle. How much space must you leave?","o":["At least 1 foot","At least 18 inches","At least 2 feet","At least 3 feet"],"h1":"It is about one long step.","h2":"In California, when you pass a bicycle in the same lane, you must leave at least 3 feet, and you must wait if you cannot.","p":"Right. Give the bicycle at least 3 feet."},"es":{"q":"En California, usted no puede cambiar de carril para rebasar a una bicicleta. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 18 pulgadas","Por lo menos 2 pies","Por lo menos 3 pies"],"h1":"Es más o menos un paso largo.","h2":"En California, cuando rebasa a una bicicleta en el mismo carril, debe dejar por lo menos 3 pies, y si no puede, debe esperar.","p":"Correcto. Deje por lo menos 3 pies a la bicicleta."},"zh":{"q":"在 California，你没办法换车道来超过一辆自行车。你必须留出多少空间？","o":["至少 1 英尺","至少 18 英寸","至少 2 英尺","至少 3 英尺"],"h1":"大约是跨一大步的距离。","h2":"在 California，在同一条车道上超过自行车时，你必须留出至少 3 英尺；如果做不到，就必须等。","p":"对。给自行车留出至少 3 英尺。"},"vi":{"q":"Ở California, bạn không thể đổi làn để vượt một xe đạp. Bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 18 inch","Ít nhất 2 feet","Ít nhất 3 feet"],"h1":"Khoảng một bước chân dài.","h2":"Ở California, khi vượt xe đạp trong cùng một làn, bạn phải chừa ít nhất 3 feet, và nếu không thể thì bạn phải chờ.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa California, hindi ka makalipat ng lane para lampasan ang isang bisikleta. Gaano kalaking espasyo ang dapat mong iwan?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 18 inches","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet"],"h1":"Halos isang mahabang hakbang ito.","h2":"Sa California, kapag nilalampasan mo ang bisikleta sa parehong lane, dapat kang mag-iwan ng hindi bababa sa 3 feet, at dapat kang maghintay kung hindi mo ito magagawa.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في California، لا تستطيع أن تغيّر الحارة لتتجاوز درّاجة هوائية. كم مسافة يجب أن تترك؟","o":["قدم واحد (1) على الأقل","18 بوصة على الأقل","قدمان (2) على الأقل","3 أقدام على الأقل"],"h1":"هي تقريبًا خطوة واحدة طويلة.","h2":"في California، عندما تتجاوز درّاجة هوائية في نفس الحارة، يجب أن تترك 3 أقدام على الأقل، ويجب أن تنتظر إذا لم تستطع ذلك.","p":"صحيح. اترك للدرّاجة 3 أقدام على الأقل."},"ref":{"doc":"CA","page":48}},{"id":"ca-047","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, how close to a crosswalk may you park, when there is no curb extension?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 10 feet","Right up to the crosswalk lines"],"h1":"It is a few car lengths away, so people on foot can be seen.","h2":"In California, you may not park within 20 feet of a marked or unmarked crosswalk, or within 15 feet where there is a curb extension.","p":"Right. Park at least 20 feet from a crosswalk."},"es":{"q":"En California, ¿a qué distancia de un cruce peatonal puede estacionarse, cuando no hay una extensión de la acera?","o":["A no menos de 20 pies","A no menos de 5 pies","A no menos de 10 pies","Justo hasta las líneas del cruce"],"h1":"Son algunos largos de carro, para que se vea a los peatones.","h2":"En California, no puede estacionarse a menos de 20 pies de un cruce peatonal, marcado o no, ni a menos de 15 pies donde hay una extensión de la acera.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal."},"zh":{"q":"在 California，没有路缘延伸（curb extension）时，你最近可以在离人行横道多远的地方停车？","o":["不能比 20 英尺更近","不能比 5 英尺更近","不能比 10 英尺更近","可以一直停到人行横道线边上"],"h1":"大约是几辆车的长度，这样走路的人才能被看见。","h2":"在 California，你不可以在有标线或没有标线的人行横道 20 英尺以内停车；有路缘延伸的地方是 15 英尺以内。","p":"对。停车时离人行横道至少 20 英尺。"},"vi":{"q":"Ở California, khi không có phần lề đường mở rộng (curb extension), bạn được đậu xe gần lối qua đường cho người đi bộ đến mức nào?","o":["Không gần hơn 20 feet","Không gần hơn 5 feet","Không gần hơn 10 feet","Sát ngay vạch lối qua đường"],"h1":"Cách vài chiều dài xe, để người đi bộ có thể được nhìn thấy.","h2":"Ở California, bạn không được đậu xe trong vòng 20 feet của lối qua đường có vạch hoặc không có vạch, hoặc trong vòng 15 feet nơi có phần lề đường mở rộng.","p":"Đúng. Đậu xe cách lối qua đường ít nhất 20 feet."},"tl":{"q":"Sa California, gaano kalapit sa tawiran ka puwedeng pumarada kapag walang curb extension?","o":["Hindi lalapit sa 20 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hanggang mismo sa mga linya ng tawiran"],"h1":"Ilang haba ito ng kotse ang layo, para makita ang mga taong naglalakad.","h2":"Sa California, hindi ka puwedeng pumarada sa loob ng 20 feet ng tawiran na may marka o walang marka, o sa loob ng 15 feet kung saan may curb extension.","p":"Tama. Pumarada nang hindi bababa sa 20 feet mula sa tawiran."},"ar":{"q":"في California، إلى أي مدى يمكنك أن تركن قرب ممرّ المشاة، عندما لا يوجد امتداد لحافّة الرصيف (curb extension)؟","o":["ليس أقرب من 20 قدمًا","ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","حتى خطوط ممرّ المشاة مباشرة"],"h1":"هي مسافة بطول بضع سيارات، حتى يمكن رؤية المشاة.","h2":"في California، يجب ألّا تركن على مسافة أقل من 20 قدمًا من ممرّ مشاة له خطوط أو بدون خطوط، أو أقل من 15 قدمًا حيث يوجد امتداد لحافّة الرصيف.","p":"صحيح. اركن على بعد 20 قدمًا على الأقل من ممرّ المشاة."},"ref":{"doc":"CA","page":28}},{"id":"ca-048","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, the signals at a railroad crossing warn that a train is coming. Where must you stop?","o":["Right on the edge of the tracks","At least 15 feet from the nearest track","At least 100 feet from the nearest track","Anywhere, as long as the gate is not down"],"h1":"Leave room so the train cannot hit your car.","h2":"In California, when a crossing warns of a train, you must stop at least 15 feet from the nearest track.","p":"Right. Stop at least 15 feet from the nearest track."},"es":{"q":"En California, las señales de un cruce de tren avisan que viene un tren. ¿Dónde debe detenerse?","o":["Justo en el borde de las vías","Por lo menos a 15 pies de la vía más cercana","Por lo menos a 100 pies de la vía más cercana","En cualquier lugar, si la barrera no está abajo"],"h1":"Deje espacio para que el tren no golpee su carro.","h2":"En California, cuando un cruce avisa que viene un tren, usted debe detenerse por lo menos a 15 pies de la vía más cercana.","p":"Correcto. Deténgase por lo menos a 15 pies de la vía más cercana."},"zh":{"q":"在 California，铁路道口的信号警告火车要来了。你必须在哪里停车？","o":["就停在铁轨边上","离最近的铁轨至少 15 英尺","离最近的铁轨至少 100 英尺","哪里都可以，只要栏杆没放下"],"h1":"留出空间，让火车撞不到你的车。","h2":"在 California，道口警告有火车时，你必须停在离最近的铁轨至少 15 英尺的地方。","p":"对。停在离最近的铁轨至少 15 英尺的地方。"},"vi":{"q":"Ở California, tín hiệu ở chỗ giao nhau với đường ray cảnh báo có tàu hỏa đang đến. Bạn phải dừng ở đâu?","o":["Ngay sát mép đường ray","Cách đường ray gần nhất ít nhất 15 feet","Cách đường ray gần nhất ít nhất 100 feet","Ở đâu cũng được, miễn là thanh chắn chưa hạ xuống"],"h1":"Chừa khoảng trống để tàu không thể đụng vào xe của bạn.","h2":"Ở California, khi chỗ giao nhau báo có tàu, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet.","p":"Đúng. Dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa California, nagbababala ang mga signal sa railroad crossing na may paparating na tren. Saan ka dapat huminto?","o":["Mismo sa gilid ng riles","Hindi bababa sa 15 feet mula sa pinakamalapit na riles","Hindi bababa sa 100 feet mula sa pinakamalapit na riles","Kahit saan, basta hindi pa bumababa ang harang"],"h1":"Mag-iwan ng espasyo para hindi mabangga ng tren ang kotse mo.","h2":"Sa California, kapag nagbababala ang crossing na may tren, dapat kang huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في California، إشارات تقاطع السكة الحديدية تحذّر من أن قطارًا قادم. أين يجب أن تتوقف؟","o":["على حافّة السكة مباشرة","على بعد 15 قدمًا على الأقل من أقرب سكة","على بعد 100 قدم على الأقل من أقرب سكة","في أي مكان، ما دام الحاجز لم ينزل"],"h1":"اترك مسافة حتى لا يصدم القطار سيارتك.","h2":"في California، عندما يحذّر التقاطع من قطار، يجب أن تتوقف على بعد 15 قدمًا على الأقل من أقرب سكة.","p":"صحيح. توقف على بعد 15 قدمًا على الأقل من أقرب سكة."},"ref":{"doc":"CA","page":51}},{"id":"ca-049","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, what is the speed limit within 500 feet of a school while children are outside or crossing?","o":["15 mph in all cases","35 mph","25 mph, unless a lower limit is posted","45 mph"],"h1":"It is the same as the limit in a residential district.","h2":"In California, the speed limit is 25 mph within 500 feet of a school while children are outside or crossing, and some school zones post 15 mph.","p":"Right. 25 mph near a school when children are around."},"es":{"q":"En California, ¿cuál es el límite de velocidad a menos de 500 pies de una escuela cuando hay niños afuera o cruzando?","o":["15 mph en todos los casos","35 mph","25 mph, a menos que se indique un límite más bajo","45 mph"],"h1":"Es igual que el límite en una zona residencial.","h2":"En California, el límite es de 25 mph a menos de 500 pies de una escuela cuando hay niños afuera o cruzando, y en algunas zonas escolares el límite es de 15 mph.","p":"Correcto. 25 mph cerca de una escuela cuando hay niños."},"zh":{"q":"在 California，孩子在外面或正在过马路时，学校 500 英尺以内的限速是多少？","o":["任何情况下都是 15 mph","35 mph","25 mph，除非标示了更低的限速","45 mph"],"h1":"它和住宅区的限速一样。","h2":"在 California，孩子在外面或正在过马路时，学校 500 英尺以内的限速是 25 mph，有些学校区标示 15 mph。","p":"对。孩子在附近时，学校旁边是 25 mph。"},"vi":{"q":"Ở California, tốc độ tối đa trong vòng 500 feet quanh trường học khi trẻ em đang ở ngoài hoặc đang băng qua đường là bao nhiêu?","o":["15 mph trong mọi trường hợp","35 mph","25 mph, trừ khi có biển ghi tốc độ thấp hơn","45 mph"],"h1":"Giống với tốc độ tối đa trong khu dân cư.","h2":"Ở California, tốc độ tối đa là 25 mph trong vòng 500 feet quanh trường học khi trẻ em đang ở ngoài hoặc đang băng qua đường, và một số khu trường học có biển 15 mph.","p":"Đúng. 25 mph gần trường học khi có trẻ em xung quanh."},"tl":{"q":"Sa California, ano ang speed limit sa loob ng 500 feet ng paaralan habang nasa labas o tumatawid ang mga bata?","o":["15 mph sa lahat ng kaso","35 mph","25 mph, maliban kung may nakasulat na mas mababang limitasyon","45 mph"],"h1":"Pareho ito ng limitasyon sa residential na lugar.","h2":"Sa California, ang speed limit ay 25 mph sa loob ng 500 feet ng paaralan habang nasa labas o tumatawid ang mga bata, at may ilang school zone na nakasulat na 15 mph.","p":"Tama. 25 mph malapit sa paaralan kapag may mga bata sa paligid."},"ar":{"q":"في California، ما حدّ السرعة على مسافة 500 قدم من المدرسة عندما يكون الأطفال في الخارج أو يعبرون الطريق؟","o":["15 mph في كل الحالات","35 mph","25 mph، إلا إذا ظهر على لافتة حدّ أقل","45 mph"],"h1":"هو نفس الحدّ في المنطقة السكنية.","h2":"في California، حدّ السرعة هو 25 mph على مسافة 500 قدم من المدرسة عندما يكون الأطفال في الخارج أو يعبرون الطريق، وبعض مناطق المدارس عليها لافتة 15 mph.","p":"صحيح. 25 mph قرب المدرسة عندما يكون الأطفال حولها."},"ref":{"doc":"CA","page":50}},{"id":"ca-050","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, what can happen if you do not stop for a school bus with flashing red lights?","o":["Only a warning","A $25 fine","A 30-day limit on passengers","A fine of up to $1,000 and a one-year suspension"],"h1":"The penalty is one of the largest on this list.","h2":"In California, failing to stop for a school bus with flashing red lights can bring a fine of up to $1,000 and a one-year suspension of your driving privilege.","p":"Right. Up to $1,000 and a one-year suspension."},"es":{"q":"En California, ¿qué puede pasar si no se detiene ante un autobús escolar con luces rojas intermitentes?","o":["Solo una advertencia","Una multa de $25","Un límite de pasajeros por 30 días","Una multa de hasta $1,000 y una suspensión de un año"],"h1":"Es uno de los castigos más grandes de esta lista.","h2":"En California, no detenerse ante un autobús escolar con luces rojas intermitentes puede costarle una multa de hasta $1,000 y la suspensión de su privilegio de manejar por un año.","p":"Correcto. Hasta $1,000 y una suspensión de un año."},"zh":{"q":"在 California，如果你没有为亮着红色闪灯的校车停车，可能会怎么样？","o":["只有警告","罚款 $25","30 天内限制载客","罚款最多 $1,000，并暂停驾照一年"],"h1":"这个处罚是这里最重的之一。","h2":"在 California，没有为亮着红色闪灯的校车停车，可能被罚款最多 $1,000，并暂停驾驶资格一年。","p":"对。最多 $1,000，并暂停一年。"},"vi":{"q":"Ở California, chuyện gì có thể xảy ra nếu bạn không dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy?","o":["Chỉ bị cảnh cáo","Bị phạt $25","Bị giới hạn chở người 30 ngày","Bị phạt đến $1,000 và đình chỉ một năm"],"h1":"Hình phạt này là một trong những hình phạt nặng nhất trong danh sách.","h2":"Ở California, không dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy có thể bị phạt đến $1,000 và bị đình chỉ quyền lái xe một năm.","p":"Đúng. Phạt đến $1,000 và đình chỉ một năm."},"tl":{"q":"Sa California, ano ang puwedeng mangyari kung hindi ka huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Babala lang","$25 na multa","30 araw na limitasyon sa mga pasahero","Multang hanggang $1,000 at isang taong suspensyon"],"h1":"Isa ang parusang ito sa pinakamabigat sa listahan.","h2":"Sa California, ang hindi paghinto para sa school bus na may kumikislap na pulang ilaw ay puwedeng magdulot ng multang hanggang $1,000 at isang taong suspensyon ng pribilehiyo mong magmaneho.","p":"Tama. Hanggang $1,000 at isang taong suspensyon."},"ar":{"q":"في California، ماذا يمكن أن يحدث إذا لم تتوقف لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["تحذير فقط","غرامة $25","تقييد عدد الركاب لمدة 30 يومًا","غرامة تصل إلى $1,000 وإيقاف لمدة سنة"],"h1":"هذه العقوبة من أكبر العقوبات في هذه القائمة.","h2":"في California، عدم التوقف لحافلة مدرسية أضواؤها الحمراء تومض يمكن أن يؤدي إلى غرامة تصل إلى $1,000 وإيقاف حقّك في القيادة لمدة سنة.","p":"صحيح. غرامة تصل إلى $1,000 وإيقاف لمدة سنة."},"ref":{"doc":"CA","page":51}},{"id":"ca-051","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, a driver is 70 or older when the license expires. How must they renew it?","o":["In person, with a vision test","Online, with no tests","By mail, with a doctor's letter","They may not renew after age 70"],"h1":"They must visit the DMV and have their eyes checked.","h2":"In California, a driver who is 70 or older when the license expires must renew in person and pass a vision test.","p":"Right. Age 70 and up renews in person with a vision test."},"es":{"q":"En California, un conductor tiene 70 años o más cuando vence su licencia. ¿Cómo debe renovarla?","o":["En persona, con un examen de la vista","En línea, sin exámenes","Por correo, con una carta del médico","No puede renovarla después de los 70 años"],"h1":"Debe ir al DMV y hacerse revisar la vista.","h2":"En California, un conductor que tiene 70 años o más cuando vence su licencia debe renovarla en persona y pasar un examen de la vista.","p":"Correcto. A partir de los 70 años se renueva en persona con examen de la vista."},"zh":{"q":"在 California，一位驾驶人在驾照到期时已经 70 岁或以上。他们必须怎样更新驾照？","o":["亲自去办，并做视力检查","在网上办，不用任何检测","邮寄，附上医生的信","70 岁以后不可以更新"],"h1":"他们必须去 DMV 检查眼睛。","h2":"在 California，驾照到期时 70 岁或以上的驾驶人必须亲自去更新，并通过视力检查。","p":"对。70 岁及以上要亲自更新，并做视力检查。"},"vi":{"q":"Ở California, một người lái đã 70 tuổi trở lên khi bằng lái hết hạn. Họ phải gia hạn như thế nào?","o":["Trực tiếp, có kiểm tra thị lực","Trực tuyến, không cần kiểm tra gì","Qua thư, kèm thư của bác sĩ","Họ không được gia hạn sau 70 tuổi"],"h1":"Họ phải đến DMV và kiểm tra mắt.","h2":"Ở California, người lái từ 70 tuổi trở lên khi bằng lái hết hạn phải gia hạn trực tiếp và qua bài kiểm tra thị lực.","p":"Đúng. Từ 70 tuổi trở lên gia hạn trực tiếp, có kiểm tra thị lực."},"tl":{"q":"Sa California, ang isang driver ay 70 taong gulang pataas nang mag-expire ang lisensya. Paano niya ito dapat i-renew?","o":["Nang personal, na may vision test","Online, nang walang anumang test","Sa koreo, na may sulat ng doktor","Hindi na siya puwedeng mag-renew pagkalipas ng 70"],"h1":"Dapat siyang pumunta sa DMV at magpatingin ng mata.","h2":"Sa California, ang driver na 70 taong gulang pataas nang mag-expire ang lisensya ay dapat mag-renew nang personal at pumasa sa vision test.","p":"Tama. Ang edad 70 pataas ay nagre-renew nang personal na may vision test."},"ar":{"q":"في California، سائق عمره 70 سنة أو أكثر عندما تنتهي رخصته. كيف يجب أن يجدّدها؟","o":["شخصيًا، مع فحص النظر","عبر الإنترنت، بدون أي فحوص","بالبريد، مع رسالة من الطبيب","لا يمكنه التجديد بعد عمر 70"],"h1":"يجب أن يذهب إلى DMV ويفحص عينيه.","h2":"في California، يجب على السائق الذي عمره 70 سنة أو أكثر عندما تنتهي رخصته أن يجدّدها شخصيًا وأن ينجح في فحص النظر.","p":"صحيح. من عمر 70 فما فوق يجدّد شخصيًا مع فحص النظر."},"ref":{"doc":"CA","page":82}},{"id":"ca-052","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a teen under 18 applies for a permit. The parents share joint custody. Who must sign the application?","o":["Only the parent the teen lives with","Only the older parent","Both parents","No parent, if the teen is 17"],"h1":"Think about what joint custody means for both adults.","h2":"In California, when parents or guardians share joint custody of a teen, both of them must sign the permit application.","p":"Right. With joint custody, both parents sign."},"es":{"q":"En California, un joven menor de 18 años solicita un permiso. Los padres tienen custodia compartida. ¿Quién debe firmar la solicitud?","o":["Solo el padre o la madre con quien vive","Solo el padre o la madre de más edad","Los dos padres","Ningún padre, si el joven tiene 17 años"],"h1":"Piense en lo que significa la custodia compartida para los dos adultos.","h2":"En California, cuando los padres o tutores tienen custodia compartida de un joven, los dos deben firmar la solicitud del permiso.","p":"Correcto. Con custodia compartida, firman los dos padres."},"ref":{"doc":"CA","page":3}},{"id":"ca-053","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, a 15-and-a-half-year-old just got an instruction permit. When may the teen start driving with it?","o":["When driver training starts and the instructor validates it","Right away, with any licensed adult age 18 or older","Only after turning 16 and passing a test","Only after passing the behind-the-wheel drive test"],"h1":"A driving instructor must do something to the permit first.","h2":"In California, a teen under 18 may not use the instruction permit until behind-the-wheel training begins with an instructor who validates the permit.","p":"Right. The permit works once training starts and the instructor validates it."},"es":{"q":"En California, un joven de 15 años y medio acaba de recibir su permiso de instrucción. ¿Cuándo puede empezar a manejar con él?","o":["Cuando empieza el entrenamiento y el instructor lo valida","De inmediato, con cualquier adulto con licencia de 18 años o más","Solo después de cumplir 16 años y pasar un examen","Solo después de pasar el examen de manejo al volante"],"h1":"Un instructor de manejo debe hacer algo con el permiso primero.","h2":"En California, un joven menor de 18 años no puede usar el permiso de instrucción hasta que empiece el entrenamiento al volante con un instructor que valide el permiso.","p":"Correcto. El permiso sirve cuando empieza el entrenamiento y el instructor lo valida."},"ref":{"doc":"CA","page":3}},{"id":"ca-054","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, you are 30 years old and have an instruction permit. How old must the licensed driver who rides with you be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The age of 25 applies only when the learner is a minor.","h2":"In California, an adult with an instruction permit must practice with a California-licensed driver who is at least 18 years old.","p":"Right. For an adult learner, the licensed driver must be at least 18."},"es":{"q":"En California, usted tiene 30 años y un permiso de instrucción. ¿Qué edad debe tener el conductor con licencia que lo acompaña?","o":["Por lo menos 16 años","Por lo menos 18 años","Por lo menos 21 años","Por lo menos 25 años"],"h1":"La edad de 25 años es solo cuando el aprendiz es menor de edad.","h2":"En California, un adulto con permiso de instrucción debe practicar con un conductor con licencia de California que tenga por lo menos 18 años.","p":"Correcto. Para un aprendiz adulto, el conductor con licencia debe tener por lo menos 18 años."},"ref":{"doc":"CA","page":3}},{"id":"ca-055","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, what is the youngest age to get a provisional driver's license?","o":["15","15 and a half","17","16"],"h1":"It is half a year after the youngest permit age.","h2":"In California, a teen must be at least 16 years old to get a provisional driver's license.","p":"Right. The provisional license starts at age 16."},"es":{"q":"En California, ¿cuál es la edad mínima para obtener una licencia de manejar provisional?","o":["15 años","15 años y medio","17 años","16 años"],"h1":"Es medio año después de la edad mínima para el permiso.","h2":"En California, un joven debe tener por lo menos 16 años para obtener una licencia de manejar provisional.","p":"Correcto. La licencia provisional empieza a los 16 años."},"ref":{"doc":"CA","page":3}},{"id":"ca-056","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, how long must a teen under 18 hold an instruction permit before scheduling the drive test?","o":["30 days, or until turning 17","3 months, or until turning 17","6 months, or until turning 18","One full year, with no exceptions"],"h1":"It is half a year, unless the teen turns 18 first.","h2":"In California, a teen must hold an instruction permit for at least 6 months, or until turning 18, before scheduling the drive test.","p":"Right. Six months with the permit, or until age 18."},"es":{"q":"En California, ¿cuánto tiempo debe tener un joven menor de 18 años el permiso de instrucción antes de hacer la cita para el examen de manejo?","o":["30 días, o hasta cumplir 17 años","3 meses, o hasta cumplir 17 años","6 meses, o hasta cumplir 18 años","Un año completo, sin excepciones"],"h1":"Es medio año, a menos que el joven cumpla 18 años antes.","h2":"En California, un joven debe tener el permiso de instrucción por lo menos 6 meses, o hasta cumplir 18 años, antes de hacer la cita para el examen de manejo.","p":"Correcto. Seis meses con el permiso, o hasta los 18 años."},"ref":{"doc":"CA","page":3}},{"id":"ca-057","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, a 16-year-old in the first year of a provisional license must drive home from work at midnight. What must the teen carry?","o":["A copy of the latest paycheck","A note signed by the employer","A note from a friend age 20 or older","Nothing; work is always allowed"],"h1":"The person who can confirm the job must sign it.","h2":"In California, a provisional driver who must drive for work during restricted hours must carry a note signed by the employer that confirms the job.","p":"Right. Carry a note signed by your employer."},"es":{"q":"En California, un joven de 16 años en el primer año de su licencia provisional debe manejar a casa desde el trabajo a medianoche. ¿Qué debe llevar?","o":["Una copia de su último cheque de pago","Una nota firmada por su empleador","Una nota de un amigo de 20 años o más","Nada; el trabajo siempre está permitido"],"h1":"La persona que puede confirmar el empleo debe firmarla.","h2":"En California, un conductor provisional que debe manejar por trabajo en las horas restringidas debe llevar una nota firmada por su empleador que confirme el empleo.","p":"Correcto. Lleve una nota firmada por su empleador."},"ref":{"doc":"CA","page":4}},{"id":"ca-058","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, a 16-year-old fails the knowledge test. How long must the teen wait before trying again?","o":["7 days","1 day","30 days","6 months"],"h1":"It is about one week.","h2":"In California, a minor who fails the knowledge test must wait seven days, not counting the day of the failure, before retaking it.","p":"Right. A minor waits seven days to retake the knowledge test."},"es":{"q":"En California, un joven de 16 años no pasa el examen de conocimientos. ¿Cuánto tiempo debe esperar para intentarlo de nuevo?","o":["7 días","1 día","30 días","6 meses"],"h1":"Es más o menos una semana.","h2":"En California, un menor que no pasa el examen de conocimientos debe esperar siete días, sin contar el día en que no lo pasó, para repetirlo.","p":"Correcto. Un menor espera siete días para repetir el examen de conocimientos."},"ref":{"doc":"CA","page":5}},{"id":"ca-059","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a 17-year-old fails the behind-the-wheel drive test. How long must the teen wait before trying again?","o":["1 day","7 days","60 days","14 days"],"h1":"It is two weeks.","h2":"In California, a minor who fails the drive test must wait 14 days, not counting the day of the failure, before retaking it.","p":"Right. A minor waits 14 days to retake the drive test."},"es":{"q":"En California, un joven de 17 años no pasa el examen de manejo al volante. ¿Cuánto tiempo debe esperar para intentarlo de nuevo?","o":["1 día","7 días","60 días","14 días"],"h1":"Son dos semanas.","h2":"En California, un menor que no pasa el examen de manejo debe esperar 14 días, sin contar el día en que no lo pasó, para repetirlo.","p":"Correcto. Un menor espera 14 días para repetir el examen de manejo."},"ref":{"doc":"CA","page":6}},{"id":"ca-060","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, you are living out of state for a while and cannot renew your license. What may you ask the DMV for before it expires?","o":["A two-week grace period","A one-year extension","A free five-year renewal","A permit to drive without a license"],"h1":"The extra time is measured in years, not weeks.","h2":"In California, a driver who is out of state and cannot renew may ask the DMV for a one-year extension before the license expires.","p":"Right. You may ask for a one-year extension."},"es":{"q":"En California, usted vive fuera del estado por un tiempo y no puede renovar su licencia. ¿Qué le puede pedir al DMV antes de que venza?","o":["Un período de gracia de dos semanas","Una extensión de un año","Una renovación gratis por cinco años","Un permiso para manejar sin licencia"],"h1":"El tiempo extra se mide en años, no en semanas.","h2":"En California, un conductor que está fuera del estado y no puede renovar puede pedirle al DMV una extensión de un año antes de que venza la licencia.","p":"Correcto. Puede pedir una extensión de un año."},"ref":{"doc":"CA","page":8}},{"id":"ca-061","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a provisional driver is on probation and then turns 18. What happens to the probation?","o":["It ends on the 18th birthday","It turns into a warning letter only","It stays; turning 18 does not end it","It is cut in half at age 18"],"h1":"A birthday does not clear the driving record.","h2":"In California, turning 18 does not erase or end a provisional driver's existing restrictions, suspensions or probation.","p":"Right. Turning 18 does not end probation."},"es":{"q":"En California, un conductor provisional está en libertad condicional y luego cumple 18 años. ¿Qué pasa con la libertad condicional?","o":["Termina el día que cumple 18 años","Se convierte en solo una carta de advertencia","Sigue igual; cumplir 18 años no la termina","Se reduce a la mitad a los 18 años"],"h1":"Un cumpleaños no borra el historial de manejo.","h2":"En California, cumplir 18 años no borra ni termina las restricciones, suspensiones o libertad condicional que ya tiene un conductor provisional.","p":"Correcto. Cumplir 18 años no termina la libertad condicional."},"ref":{"doc":"CA","page":55}},{"id":"ca-062","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a judge may let you attend traffic violator school for a one-point ticket. How often may you do this?","o":["Once in any 30-day period","Every time you get a ticket","Once in your whole lifetime","Once in any 18-month period"],"h1":"It is a period of a year and a half.","h2":"In California, you may attend traffic violator school for a one-point ticket once in any 18-month period.","p":"Right. Once every 18 months."},"es":{"q":"En California, un juez puede permitirle ir a la escuela para infractores de tránsito por una multa de un punto. ¿Con qué frecuencia puede hacerlo?","o":["Una vez en cualquier período de 30 días","Cada vez que reciba una multa","Una sola vez en toda su vida","Una vez en cualquier período de 18 meses"],"h1":"Es un período de un año y medio.","h2":"En California, usted puede ir a la escuela para infractores de tránsito por una multa de un punto una vez en cualquier período de 18 meses.","p":"Correcto. Una vez cada 18 meses."},"ref":{"doc":"CA","page":54}},{"id":"ca-063","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, what does the DMV do if you are convicted of a hit-and-run in which someone was hurt?","o":["Revokes your driving privilege","Adds one point and nothing else","Sends you a warning letter","Requires only a vision test"],"h1":"It is the most serious action the DMV can take.","h2":"In California, the DMV revokes your driving privilege if you are convicted of a hit-and-run that resulted in injury.","p":"Right. A hit-and-run conviction means revocation."},"es":{"q":"En California, ¿qué hace el DMV si a usted lo declaran culpable de huir del lugar de un choque en el que alguien resultó herido?","o":["Revoca su privilegio de manejar","Agrega un punto y nada más","Le manda una carta de advertencia","Solo le pide un examen de la vista"],"h1":"Es la acción más seria que puede tomar el DMV.","h2":"En California, el DMV revoca su privilegio de manejar si a usted lo declaran culpable de huir del lugar de un choque en el que hubo heridos.","p":"Correcto. Huir de un choque significa la revocación."},"ref":{"doc":"CA","page":54}},{"id":"ca-064","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, you lend your car to a friend who has no driver's license, and the friend is caught driving it. What can happen to your car?","o":["Nothing, because it is your car","It gets a parking ticket","It may be impounded for 30 days","It must be sold"],"h1":"The car itself can be held for about a month.","h2":"In California, if an unlicensed person is caught driving your vehicle, the vehicle may be impounded for 30 days.","p":"Right. The car may be impounded for 30 days."},"es":{"q":"En California, usted le presta su carro a un amigo que no tiene licencia de manejar, y lo detienen manejándolo. ¿Qué le puede pasar a su carro?","o":["Nada, porque el carro es suyo","Recibe una multa de estacionamiento","Pueden incautarlo por 30 días","Hay que venderlo"],"h1":"El carro mismo puede quedar retenido por más o menos un mes.","h2":"En California, si detienen a una persona sin licencia manejando su vehículo, pueden incautar el vehículo por 30 días.","p":"Correcto. Pueden incautar el carro por 30 días."},"ref":{"doc":"CA","page":53}},{"id":"ca-065","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, after a DUI arrest, the officer takes your license. How long is the temporary license you may receive good for?","o":["24 hours","30 days","6 months","One year"],"h1":"It lasts about one month.","h2":"In California, after a DUI arrest, the officer may take your license and give you a temporary license that is good for 30 days.","p":"Right. The temporary license lasts 30 days."},"es":{"q":"En California, después de un arresto por manejar bajo la influencia, el oficial le quita la licencia. ¿Por cuánto tiempo es válida la licencia temporal que le pueden dar?","o":["24 horas","30 días","6 meses","Un año"],"h1":"Dura más o menos un mes.","h2":"En California, después de un arresto por manejar bajo la influencia, el oficial puede quitarle la licencia y darle una licencia temporal válida por 30 días.","p":"Correcto. La licencia temporal dura 30 días."},"ref":{"doc":"CA","page":74}},{"id":"ca-066","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, how long does a DUI conviction stay on your driving record?","o":["1 year","3 years","5 years","10 years"],"h1":"It is longer than the usual three years for other tickets.","h2":"In California, every DUI conviction stays on your driving record for 10 years.","p":"Right. A DUI stays on your record for 10 years."},"es":{"q":"En California, ¿cuánto tiempo queda en su historial de manejo una condena por manejar bajo la influencia?","o":["1 año","3 años","5 años","10 años"],"h1":"Es más que los tres años normales de otras multas.","h2":"En California, toda condena por manejar bajo la influencia queda en su historial de manejo por 10 años.","p":"Correcto. Una condena por manejar bajo la influencia queda 10 años en su historial."},"ref":{"doc":"CA","page":74}},{"id":"ca-067","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you drive passengers for hire, such as a ride-share trip. At what blood alcohol level is it illegal for you to drive?","o":["0.04 percent or more","0.08 percent or more","0.10 percent or more","0.15 percent or more"],"h1":"It is half the regular adult limit.","h2":"In California, it is illegal to drive a passenger for hire with a blood alcohol level of 0.04 percent or more.","p":"Right. With a paying passenger, the limit is 0.04 percent."},"es":{"q":"En California, usted lleva pasajeros que le pagan, como en un viaje de transporte compartido. ¿Con qué nivel de alcohol en la sangre es ilegal manejar?","o":["0.04 por ciento o más","0.08 por ciento o más","0.10 por ciento o más","0.15 por ciento o más"],"h1":"Es la mitad del límite normal para adultos.","h2":"En California, es ilegal llevar a un pasajero que paga con un nivel de alcohol en la sangre de 0.04 por ciento o más.","p":"Correcto. Con un pasajero que paga, el límite es 0.04 por ciento."},"ref":{"doc":"CA","page":73}},{"id":"ca-068","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a 15-year-old is convicted of riding a bicycle under the influence of alcohol. What can happen to the teen's driving privilege?","o":["Nothing, because a bicycle is not a car","A $10 fine only","It may be suspended or delayed for one year","The teen must wait until age 25"],"h1":"It can affect a future license, not just the bicycle.","h2":"In California, a person 13 to 20 years old convicted of riding a bicycle under the influence may have the driving privilege suspended or delayed for one year.","p":"Right. The driving privilege may be suspended or delayed for one year."},"es":{"q":"En California, a un joven de 15 años lo declaran culpable de andar en bicicleta bajo la influencia del alcohol. ¿Qué le puede pasar a su privilegio de manejar?","o":["Nada, porque una bicicleta no es un carro","Solo una multa de $10","Pueden suspenderlo o retrasarlo por un año","Debe esperar hasta los 25 años"],"h1":"Puede afectar una licencia futura, no solo la bicicleta.","h2":"En California, a una persona de 13 a 20 años declarada culpable de andar en bicicleta bajo la influencia le pueden suspender o retrasar el privilegio de manejar por un año.","p":"Correcto. Pueden suspender o retrasar el privilegio de manejar por un año."},"ref":{"doc":"CA","page":72}},{"id":"ca-069","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, you carry an opened bottle of alcohol in your car. Where must you keep it?","o":["In the glove box","Under the driver's seat","In a cup holder with the cap on","In the trunk or where passengers do not sit"],"h1":"It must be away from where people ride.","h2":"In California, an opened alcohol container must be kept in the trunk or another place where passengers do not sit; the glove box is not allowed.","p":"Right. Keep it in the trunk or where no one sits."},"es":{"q":"En California, usted lleva en su carro una botella de alcohol abierta. ¿Dónde debe guardarla?","o":["En la guantera","Debajo del asiento del conductor","En un portavasos con la tapa puesta","En la cajuela o donde no se sientan pasajeros"],"h1":"Debe estar lejos de donde viajan las personas.","h2":"En California, un envase de alcohol abierto debe ir en la cajuela u otro lugar donde no se sientan pasajeros; la guantera no está permitida.","p":"Correcto. Guárdela en la cajuela o donde nadie se sienta."},"ref":{"doc":"CA","page":72}},{"id":"ca-070","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, what is the minimum liability insurance for injury or death to more than one person in a crash?","o":["$60,000","$15,000","$30,000","$100,000"],"h1":"It is twice the amount for one person.","h2":"In California, your insurance must cover at least $60,000 for death or injury to more than one person.","p":"Right. The minimum is $60,000 for more than one person."},"es":{"q":"En California, ¿cuál es el seguro mínimo de responsabilidad civil por lesiones o muerte de más de una persona en un choque?","o":["$60,000","$15,000","$30,000","$100,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"En California, su seguro debe cubrir por lo menos $60,000 por muerte o lesiones de más de una persona.","p":"Correcto. El mínimo es $60,000 para más de una persona."},"ref":{"doc":"CA","page":76}},{"id":"ca-071","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, your license was suspended for a crash without insurance. How can you get it back early?","o":["Pay a $50 reinstatement fee only","Retake the vision and knowledge tests","File an SR 22/SR 1P and keep it for three years","Get a letter from the other driver"],"h1":"You must prove you have insurance and keep proving it.","h2":"In California, after a suspension for driving uninsured, you can get your license back during the last three years by filing an SR 22/SR 1P insurance certificate and keeping it for those three years.","p":"Right. File an SR 22/SR 1P and keep it for three years."},"es":{"q":"En California, le suspendieron la licencia por un choque sin seguro. ¿Cómo puede recuperarla antes?","o":["Pagar solo una cuota de $50 para reactivarla","Repetir los exámenes de la vista y de conocimientos","Presentar un SR 22/SR 1P y mantenerlo por tres años","Conseguir una carta del otro conductor"],"h1":"Debe probar que tiene seguro y seguir probándolo.","h2":"En California, después de una suspensión por manejar sin seguro, puede recuperar su licencia durante los últimos tres años si presenta un certificado de seguro SR 22/SR 1P y lo mantiene esos tres años.","p":"Correcto. Presente un SR 22/SR 1P y manténgalo por tres años."},"ref":{"doc":"CA","page":76}},{"id":"ca-072","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, someone was hurt in a crash you were in. How soon must a report be made to law enforcement?","o":["Within 1 hour","Within 24 hours","Within 10 days","Within 30 days"],"h1":"It is within one day.","h2":"In California, if anyone is injured or killed in a crash, you must make a report to law enforcement within 24 hours.","p":"Right. Report it to law enforcement within 24 hours."},"es":{"q":"En California, alguien se lastimó en un choque en el que usted estuvo. ¿En cuánto tiempo se debe hacer un reporte a la policía?","o":["En 1 hora","En 24 horas","En 10 días","En 30 días"],"h1":"Es dentro de un día.","h2":"En California, si alguien resulta herido o muerto en un choque, usted debe hacer un reporte a la policía dentro de las 24 horas.","p":"Correcto. Repórtelo a la policía dentro de 24 horas."},"ref":{"doc":"CA","page":77}},{"id":"ca-073","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, you buy a used car. How long do you have to transfer the ownership into your name?","o":["24 hours","5 days","60 days","10 days"],"h1":"It is a little more than one week.","h2":"In California, when you buy a vehicle, you have 10 days to transfer ownership into your name.","p":"Right. You have 10 days to transfer ownership."},"es":{"q":"En California, usted compra un carro usado. ¿Cuánto tiempo tiene para pasar la propiedad a su nombre?","o":["24 horas","5 días","60 días","10 días"],"h1":"Es un poco más de una semana.","h2":"En California, cuando usted compra un vehículo, tiene 10 días para pasar la propiedad a su nombre.","p":"Correcto. Tiene 10 días para pasar la propiedad a su nombre."},"ref":{"doc":"CA","page":79}},{"id":"ca-074","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you sell your car. How soon must you tell the DMV with a Notice of Transfer and Release of Liability?","o":["Within 5 days","Within 10 days","Within 30 days","At your next renewal"],"h1":"It is less than one week.","h2":"In California, when you sell a vehicle, you must notify the DMV within five days with a Notice of Transfer and Release of Liability.","p":"Right. Notify the DMV within five days."},"es":{"q":"En California, usted vende su carro. ¿En cuánto tiempo debe avisar al DMV con un Aviso de Transferencia y Exención de Responsabilidad?","o":["En 5 días","En 10 días","En 30 días","En su próxima renovación"],"h1":"Es menos de una semana.","h2":"En California, cuando usted vende un vehículo, debe avisar al DMV dentro de cinco días con un Aviso de Transferencia y Exención de Responsabilidad.","p":"Correcto. Avise al DMV dentro de cinco días."},"ref":{"doc":"CA","page":79}},{"id":"ca-075","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, you just moved here and became a resident. How soon must you register your out-of-state car?","o":["Within 5 days","Within 10 days","Within 20 days","Within 6 months"],"h1":"It is close to three weeks.","h2":"In California, you have 20 days to register your vehicle after you become a resident or get a job in the state.","p":"Right. Register it within 20 days."},"es":{"q":"En California, usted acaba de mudarse aquí y se hizo residente. ¿En cuánto tiempo debe registrar su carro de otro estado?","o":["En 5 días","En 10 días","En 20 días","En 6 meses"],"h1":"Son casi tres semanas.","h2":"En California, usted tiene 20 días para registrar su vehículo después de hacerse residente o conseguir trabajo en el estado.","p":"Correcto. Regístrelo dentro de 20 días."},"ref":{"doc":"CA","page":79}},{"id":"ca-076","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, you are about to turn right and there is a bike lane next to you. How close to the turn may you move into the bike lane?","o":["Within 50 feet","Within 200 feet","Within 500 feet","Never; you must turn from your lane"],"h1":"It is a short distance before the corner, not a long stretch.","h2":"In California, you may drive in a bike lane within 200 feet of a right turn, after checking for bicyclists.","p":"Right. You may enter the bike lane within 200 feet of the turn."},"es":{"q":"En California, usted va a dar vuelta a la derecha y hay un carril para bicicletas a su lado. ¿A qué distancia de la vuelta puede entrar al carril para bicicletas?","o":["A menos de 50 pies","A menos de 200 pies","A menos de 500 pies","Nunca; debe dar vuelta desde su carril"],"h1":"Es una distancia corta antes de la esquina, no un tramo largo.","h2":"En California, usted puede manejar en un carril para bicicletas a menos de 200 pies de una vuelta a la derecha, después de revisar si hay ciclistas.","p":"Correcto. Puede entrar al carril para bicicletas a menos de 200 pies de la vuelta."},"ref":{"doc":"CA","page":18}},{"id":"ca-077","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, when may you make a U-turn in a residential district?","o":["Only when the light is red","Only in front of a fire station","Any time, even with cars close by","When no car is coming within 200 feet"],"h1":"Think about how close other cars may be.","h2":"In California, you may make a U-turn in a residential district if no vehicles are approaching within 200 feet.","p":"Right. No vehicles may be coming within 200 feet."},"es":{"q":"En California, ¿cuándo puede dar una vuelta en U en una zona residencial?","o":["Solo cuando la luz está roja","Solo frente a una estación de bomberos","En cualquier momento, aunque haya carros cerca","Cuando no viene ningún carro a menos de 200 pies"],"h1":"Piense en qué tan cerca pueden estar otros carros.","h2":"En California, usted puede dar una vuelta en U en una zona residencial si no viene ningún vehículo a menos de 200 pies.","p":"Correcto. No debe venir ningún vehículo a menos de 200 pies."},"ref":{"doc":"CA","page":20}},{"id":"ca-078","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, how close may you park to a sidewalk ramp for people with disabilities?","o":["No closer than 3 feet","No closer than 1 foot","Right up against it","No closer than 50 feet"],"h1":"Leave room the length of a long step.","h2":"In California, you may not park within three feet of a sidewalk ramp for people with disabilities.","p":"Right. Stay at least three feet away from the ramp."},"es":{"q":"En California, ¿qué tan cerca puede estacionarse de una rampa de banqueta para personas con discapacidad?","o":["No más cerca de 3 pies","No más cerca de 1 pie","Justo pegado a ella","No más cerca de 50 pies"],"h1":"Deje espacio del largo de un paso grande.","h2":"En California, usted no puede estacionarse a menos de tres pies de una rampa de banqueta para personas con discapacidad.","p":"Correcto. Quédese por lo menos a tres pies de la rampa."},"ref":{"doc":"CA","page":28}},{"id":"ca-079","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, your car is left stopped on a freeway. After how long may it be removed?","o":["30 minutes","1 hour","More than 4 hours","More than 3 days"],"h1":"It is part of a single day, longer than a couple of hours.","h2":"In California, a vehicle stopped, parked or left standing on a freeway for more than four hours may be removed.","p":"Right. After more than four hours, it may be removed."},"es":{"q":"En California, su carro queda detenido en una autopista. ¿Después de cuánto tiempo pueden retirarlo?","o":["30 minutos","1 hora","Más de 4 horas","Más de 3 días"],"h1":"Es parte de un solo día, más que un par de horas.","h2":"En California, un vehículo detenido, estacionado o abandonado en una autopista por más de cuatro horas puede ser retirado.","p":"Correcto. Después de más de cuatro horas pueden retirarlo."},"ref":{"doc":"CA","page":29}},{"id":"ca-080","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, a streetcar is stopped at a safety zone. How fast may you pass it?","o":["25 mph","15 mph","5 mph","10 mph"],"h1":"It is a very slow speed, but not walking pace.","h2":"In California, when a bus, streetcar or trolley is stopped at a safety zone or traffic light, you may pass at no more than 10 mph.","p":"Right. Pass at no more than 10 mph."},"es":{"q":"En California, un tranvía está detenido en una zona de seguridad. ¿A qué velocidad puede pasarlo?","o":["25 mph","15 mph","5 mph","10 mph"],"h1":"Es una velocidad muy baja, pero no a paso de persona.","h2":"En California, cuando un autobús, tranvía o trole está detenido en una zona de seguridad o en un semáforo, usted puede pasarlo a no más de 10 mph.","p":"Correcto. Páselo a no más de 10 mph."},"ref":{"doc":"CA","page":43}},{"id":"ca-081","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, is it legal for a motorcycle to ride between lanes of cars, called lane splitting?","o":["No, never","Yes, lane splitting is legal","Only on Sundays","Only for police motorcycles"],"h1":"The California handbook tells car drivers to expect this.","h2":"In California, it is legal for motorcycles to share lanes with cars, which is called lane splitting.","p":"Right. Lane splitting is legal in California."},"es":{"q":"En California, ¿es legal que una motocicleta circule entre los carriles de carros, lo que se llama dividir carriles?","o":["No, nunca","Sí, dividir carriles es legal","Solo los domingos","Solo para motocicletas de la policía"],"h1":"El manual de California les dice a los conductores de carros que esperen esto.","h2":"En California, es legal que las motocicletas compartan carril con los carros, lo que se llama dividir carriles.","p":"Correcto. Dividir carriles es legal en California."},"ref":{"doc":"CA","page":44}},{"id":"ca-082","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, neighborhood electric vehicles may not use roads with a speed limit above what?","o":["15 mph","25 mph","35 mph","55 mph"],"h1":"Their top speed is only 25 mph, so faster roads are off limits.","h2":"In California, neighborhood electric vehicles and low-speed vehicles are kept off roads where the speed limit is greater than 35 mph.","p":"Right. They may not use roads posted above 35 mph."},"es":{"q":"En California, ¿por encima de qué límite de velocidad no pueden usar una calle los vehículos eléctricos de vecindario?","o":["15 mph","25 mph","35 mph","55 mph"],"h1":"Su velocidad máxima es solo 25 mph, así que no pueden usar calles más rápidas.","h2":"En California, los vehículos eléctricos de vecindario y los vehículos de baja velocidad no pueden usar calles donde el límite de velocidad es mayor de 35 mph.","p":"Correcto. No pueden usar calles con límite mayor de 35 mph."},"ref":{"doc":"CA","page":46}},{"id":"ca-083","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, which bicycle riders must wear a helmet?","o":["Only riders under 12","Riders under 18","Only riders over 65","No one; helmets are optional"],"h1":"It covers all minors.","h2":"In California, a bicyclist under 18 years old must wear a helmet.","p":"Right. Riders under 18 must wear a helmet."},"es":{"q":"En California, ¿qué ciclistas deben usar casco?","o":["Solo los menores de 12 años","Los menores de 18 años","Solo los mayores de 65 años","Nadie; el casco es opcional"],"h1":"Incluye a todos los menores de edad.","h2":"En California, un ciclista menor de 18 años debe usar casco.","p":"Correcto. Los ciclistas menores de 18 años deben usar casco."},"ref":{"doc":"CA","page":47}},{"id":"ca-084","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, you are towing a trailer on a highway. Which lane must you use?","o":["The far-left lane only","Any lane, if you keep up with traffic","The carpool lane only","The far-right lane or a slow-vehicle lane"],"h1":"Slow, heavy vehicles stay to one side.","h2":"In California, when you tow a vehicle or trailer, you must drive in the far-right lane or a lane marked for slower vehicles.","p":"Right. Use the far-right lane or the slow-vehicle lane."},"es":{"q":"En California, usted va remolcando un tráiler en una carretera. ¿Qué carril debe usar?","o":["Solo el carril de la extrema izquierda","Cualquier carril, si va al ritmo del tráfico","Solo el carril de vehículos compartidos","El de la extrema derecha o uno para vehículos lentos"],"h1":"Los vehículos lentos y pesados van de un lado.","h2":"En California, cuando usted remolca un vehículo o un tráiler, debe manejar en el carril de la extrema derecha o en un carril marcado para vehículos lentos.","p":"Correcto. Use el carril de la extrema derecha o el de vehículos lentos."},"ref":{"doc":"CA","page":50}},{"id":"ca-085","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, you are within 100 feet of a railroad crossing with no gates, signals or flagman, and you cannot see 400 feet down the tracks both ways. What is the speed limit?","o":["15 mph","25 mph","35 mph","5 mph"],"h1":"It is the same as the alley speed limit.","h2":"In California, the speed limit is 15 mph within 100 feet of a railroad crossing when you cannot see the tracks for 400 feet in both directions, unless gates, a signal or a flagman control it.","p":"Right. The limit there is 15 mph."},"es":{"q":"En California, usted está a menos de 100 pies de un cruce de tren sin barreras, señales ni abanderado, y no puede ver 400 pies de las vías en ambas direcciones. ¿Cuál es el límite de velocidad?","o":["15 mph","25 mph","35 mph","5 mph"],"h1":"Es igual al límite de velocidad en un callejón.","h2":"En California, el límite de velocidad es 15 mph a menos de 100 pies de un cruce de tren cuando no puede ver las vías por 400 pies en ambas direcciones, a menos que haya barreras, señales o un abanderado.","p":"Correcto. Ahí el límite es 15 mph."},"ref":{"doc":"CA","page":51}},{"id":"ca-086","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, may you smoke in your car while a child under 18 is riding with you?","o":["Yes, if a window is open","No, you can be fined","Yes, if the car is parked","Yes, if the child agrees"],"h1":"The law protects minors from smoke in the car.","h2":"In California, you must not smoke when a minor is in the vehicle, and you can be fined for it.","p":"Right. No smoking with a minor in the car."},"es":{"q":"En California, ¿puede fumar en su carro cuando lo acompaña un menor de 18 años?","o":["Sí, si una ventana está abierta","No, le pueden poner una multa","Sí, si el carro está estacionado","Sí, si el menor está de acuerdo"],"h1":"La ley protege a los menores del humo en el carro.","h2":"En California, usted no debe fumar cuando hay un menor en el vehículo, y le pueden poner una multa.","p":"Correcto. No se fuma con un menor en el carro."},"ref":{"doc":"CA","page":52}},{"id":"ca-087","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, your load sticks out more than 4 feet past the rear bumper. What must you put on it during the day?","o":["A 12-inch red or fluorescent orange flag","A white rag of any size or shape","A sign that says WIDE LOAD on it","Nothing, as long as you drive slowly"],"h1":"It must be a bright warning color and a set size.","h2":"In California, cargo that extends more than 4 feet from the rear bumper must display a 12-inch red or fluorescent orange square flag.","p":"Right. Use a 12-inch red or fluorescent orange flag."},"es":{"q":"En California, su carga sobresale más de 4 pies detrás de la defensa trasera. ¿Qué debe ponerle durante el día?","o":["Una bandera roja o anaranjada fluorescente de 12 pulgadas","Un trapo blanco de cualquier tamaño o forma","Un letrero que diga CARGA ANCHA","Nada, siempre que maneje despacio"],"h1":"Debe ser de un color de advertencia brillante y de un tamaño fijo.","h2":"En California, una carga que sobresale más de 4 pies de la defensa trasera debe llevar una bandera cuadrada roja o anaranjada fluorescente de 12 pulgadas.","p":"Correcto. Use una bandera roja o anaranjada fluorescente de 12 pulgadas."},"ref":{"doc":"CA","page":52}},{"id":"ca-088","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, heavy rain or snow means you cannot see farther than 100 feet ahead. What is the fastest safe speed?","o":["15 mph","30 mph","45 mph","55 mph"],"h1":"It is about half the usual highway limit.","h2":"In California, if you cannot see farther than 100 feet, it is not safe to drive faster than 30 mph.","p":"Right. No faster than 30 mph."},"es":{"q":"En California, por lluvia o nieve fuerte usted no puede ver a más de 100 pies adelante. ¿Cuál es la velocidad más alta segura?","o":["15 mph","30 mph","45 mph","55 mph"],"h1":"Es más o menos la mitad del límite normal en carretera.","h2":"En California, si usted no puede ver a más de 100 pies, no es seguro manejar a más de 30 mph.","p":"Correcto. No más de 30 mph."},"ref":{"doc":"CA","page":62}},{"id":"ca-089","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, a 14-year-old passenger in your car is not wearing a seat belt. Who can get the ticket?","o":["Only the passenger","The passenger's school","No one, because the passenger is a minor","You, the driver"],"h1":"The driver is responsible for young passengers.","h2":"In California, the driver can get a ticket if a passenger under 16 years old is not wearing a seat belt.","p":"Right. The driver can be ticketed for a passenger under 16."},"es":{"q":"En California, un pasajero de 14 años en su carro no lleva puesto el cinturón de seguridad. ¿Quién puede recibir la multa?","o":["Solo el pasajero","La escuela del pasajero","Nadie, porque el pasajero es menor","Usted, el conductor"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En California, el conductor puede recibir una multa si un pasajero menor de 16 años no lleva puesto el cinturón de seguridad.","p":"Correcto. El conductor puede recibir la multa por un pasajero menor de 16 años."},"ref":{"doc":"CA","page":65}},{"id":"ca-090","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, what happens to traffic fines in a highway construction or maintenance zone when workers are present?","o":["They are cut in half","They stay the same","They are doubled","They are replaced by a warning"],"h1":"The fines go up, not down.","h2":"In California, fines are doubled in highway construction or maintenance zones when workers are present.","p":"Right. Fines are doubled when workers are present."},"es":{"q":"En California, ¿qué pasa con las multas de tránsito en una zona de construcción o mantenimiento de carreteras cuando hay trabajadores presentes?","o":["Se reducen a la mitad","Siguen igual","Se duplican","Se cambian por una advertencia"],"h1":"Las multas suben, no bajan.","h2":"En California, las multas se duplican en zonas de construcción o mantenimiento de carreteras cuando hay trabajadores presentes.","p":"Correcto. Las multas se duplican cuando hay trabajadores presentes."},"ref":{"doc":"CA","page":49}},{"id":"ca-091","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, the Mature Driver Improvement Program, which may lower insurance costs, is for drivers of what age?","o":["55 and older","21 and older","40 and older","80 and older"],"h1":"It starts well before retirement age.","h2":"In California, the Mature Driver Improvement Program is an eight-hour course for drivers 55 years old and older.","p":"Right. It is for drivers 55 and older."},"es":{"q":"En California, ¿para conductores de qué edad es el Programa de Mejoramiento para Conductores Mayores, que puede bajar el costo del seguro?","o":["55 años o más","21 años o más","40 años o más","80 años o más"],"h1":"Empieza bastante antes de la edad de jubilación.","h2":"En California, el Programa de Mejoramiento para Conductores Mayores es un curso de ocho horas para conductores de 55 años o más.","p":"Correcto. Es para conductores de 55 años o más."},"ref":{"doc":"CA","page":83}},{"id":"ca-092","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, can a resident get a driver's license without proof of legal immigration status?","o":["No, only U.S. citizens can","Only with a work visa","Yes, all residents can","Only after five years"],"h1":"The handbook says the license is open to every resident.","h2":"In California, all residents can get a driver's license, whatever their immigration status.","p":"Right. All residents can get a license, whatever their immigration status."},"es":{"q":"En California, ¿puede un residente obtener una licencia de manejo sin prueba de estatus migratorio legal?","o":["No, solo los ciudadanos de EE. UU.","Solo con una visa de trabajo","Sí, todos los residentes pueden","Solo después de cinco años"],"h1":"El manual dice que la licencia está abierta a todos los residentes.","h2":"En California, todos los residentes pueden obtener una licencia de manejo, sin importar su estatus migratorio.","p":"Correcto. Todos los residentes pueden obtener licencia, sin importar su estatus migratorio."},"ref":{"doc":"CA","page":1}},{"id":"ca-093","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, how many proofs of residency must you bring to apply for an instruction permit?","o":["One","Two","Three","None"],"h1":"It is more than one document.","h2":"In California, you must provide two proofs of residency when you apply for an instruction permit or driver's license.","p":"Right. You bring two proofs of residency."},"es":{"q":"En California, ¿cuántas pruebas de residencia debe llevar para solicitar un permiso de instrucción?","o":["Una","Dos","Tres","Ninguna"],"h1":"Es más de un documento.","h2":"En California, usted debe presentar dos pruebas de residencia cuando solicita un permiso de instrucción o una licencia de manejo.","p":"Correcto. Debe llevar dos pruebas de residencia."},"ref":{"doc":"CA","page":2}},{"id":"ca-094","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a parent signed for a teen's provisional license. Later the parent wants to stop the teen from driving. What can the parent do?","o":["Nothing until the teen turns 18","Only ask a judge to suspend it","Only take away the car keys","Ask the DMV to cancel the license"],"h1":"The parent who signed can undo that approval with a DMV form.","h2":"In California, a parent or guardian may cancel a teen's license by filling out a DMV request to cancel or surrender it.","p":"Right. The parent can ask the DMV to cancel the license."},"es":{"q":"En California, un padre firmó para la licencia provisional de su hijo adolescente. Más tarde quiere que el joven deje de manejar. ¿Qué puede hacer?","o":["Nada hasta que cumpla 18 años","Solo pedir a un juez que la suspenda","Solo quitarle las llaves del carro","Pedir al DMV que cancele la licencia"],"h1":"El padre que firmó puede retirar ese permiso con un formulario del DMV.","h2":"En California, un padre o tutor puede cancelar la licencia de su hijo adolescente llenando una solicitud del DMV para cancelarla o entregarla.","p":"Correcto. El padre puede pedir al DMV que cancele la licencia."},"ref":{"doc":"CA","page":4}},{"id":"ca-095","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, your car can park itself and has adaptive cruise control. May you use these features during the drive test?","o":["No, they are not allowed","Yes, any feature is allowed","Only adaptive cruise control","Only if the examiner is busy"],"h1":"The test checks your skill, not the car's technology.","h2":"In California, driver assistance features such as automatic parallel parking, lane departure and adaptive cruise control are not allowed during the drive test.","p":"Right. Those driver assistance features are not allowed on the test."},"es":{"q":"En California, su carro puede estacionarse solo y tiene control de crucero adaptativo. ¿Puede usar estas funciones durante el examen de manejo?","o":["No, no están permitidas","Sí, se permite cualquier función","Solo el control de crucero adaptativo","Solo si el examinador está ocupado"],"h1":"El examen revisa su habilidad, no la tecnología del carro.","h2":"En California, las funciones de asistencia al conductor, como el estacionamiento automático en paralelo, el aviso de salida de carril y el control de crucero adaptativo, no se permiten durante el examen de manejo.","p":"Correcto. Esas funciones de asistencia no se permiten en el examen."},"ref":{"doc":"CA","page":7}},{"id":"ca-096","scope":"CA","cat":"signals","sign":null,"c":1,"en":{"q":"In California, it is a sunny day and you drive into a tunnel. What should you do with your headlights?","o":["Leave them off in daylight","Turn them on","Use only parking lights","Flash your high beams"],"h1":"The handbook lists tunnels and mountain roads even on sunny days.","h2":"In California, you should use your headlights in tunnels and on mountain roads, even on sunny days.","p":"Right. Headlights go on in tunnels, even on sunny days."},"es":{"q":"En California, es un día soleado y usted entra a un túnel. ¿Qué debe hacer con sus faros?","o":["Dejarlos apagados de día","Encenderlos","Usar solo las luces de estacionamiento","Hacer cambio de luces altas"],"h1":"El manual menciona los túneles y las carreteras de montaña aun en días soleados.","h2":"En California, usted debe usar los faros en los túneles y en las carreteras de montaña, aun en días soleados.","p":"Correcto. Los faros se encienden en los túneles, aun en días soleados."},"ref":{"doc":"CA","page":11}},{"id":"ca-097","scope":"CA","cat":"signals","sign":null,"c":2,"en":{"q":"In California, you plan to change lanes on a freeway. How soon before the change should you signal?","o":["One second before","Only after you start moving","At least five seconds before","Signals are not needed on freeways"],"h1":"Freeway speeds call for a long warning.","h2":"In California, you should signal at least five seconds before you change lanes on a freeway.","p":"Right. Signal at least five seconds before a freeway lane change."},"es":{"q":"En California, usted piensa cambiar de carril en una autopista. ¿Con cuánto tiempo de anticipación debe poner la señal?","o":["Un segundo antes","Solo después de empezar a moverse","Por lo menos cinco segundos antes","En la autopista no hace falta señalar"],"h1":"A las velocidades de la autopista se necesita un aviso largo.","h2":"En California, usted debe poner la señal por lo menos cinco segundos antes de cambiar de carril en una autopista.","p":"Correcto. Señale por lo menos cinco segundos antes de cambiar de carril en la autopista."},"ref":{"doc":"CA","page":11}},{"id":"ca-098","scope":"CA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In California, you see two sets of double solid yellow lines, two or more feet apart. What do they mean?","o":["A barrier you must not drive over or turn across","A lane where you may pass with care","A center lane for left turns","A lane for buses only"],"h1":"Treat them like a wall in the road, except at openings.","h2":"In California, two sets of double solid yellow lines spaced two or more feet apart are a barrier, so you may not drive over them or turn across them except at marked openings.","p":"Right. They are a barrier; cross only at marked openings."},"es":{"q":"En California, usted ve dos pares de líneas amarillas dobles continuas, separadas por dos pies o más. ¿Qué significan?","o":["Una barrera que no debe cruzar ni para dar vuelta","Un carril donde puede rebasar con cuidado","Un carril central para dar vuelta a la izquierda","Un carril solo para autobuses"],"h1":"Trátelas como una pared en la calle, salvo en las aberturas.","h2":"En California, dos pares de líneas amarillas dobles continuas separadas por dos pies o más son una barrera, así que no puede pasar sobre ellas ni cruzarlas para dar vuelta, salvo en las aberturas marcadas.","p":"Correcto. Son una barrera; crúcelas solo en las aberturas marcadas."},"ref":{"doc":"CA","page":13}},{"id":"ca-099","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, you ride a motorcycle alone. May you use a carpool (HOV) lane?","o":["No, you need at least one passenger","Only on weekends","Only with a special decal","Yes, unless a sign says otherwise"],"h1":"Motorcycles are named in the HOV lane rules.","h2":"In California, a motorcycle may use a carpool (HOV) lane unless a sign says otherwise.","p":"Right. Motorcycles may use HOV lanes unless signs say otherwise."},"es":{"q":"En California, usted maneja una motocicleta sin pasajero. ¿Puede usar un carril de vehículos compartidos (HOV)?","o":["No, necesita por lo menos un pasajero","Solo los fines de semana","Solo con una calcomanía especial","Sí, a menos que un letrero diga otra cosa"],"h1":"Las motocicletas aparecen en las reglas del carril HOV.","h2":"En California, una motocicleta puede usar un carril de vehículos compartidos (HOV) a menos que un letrero diga otra cosa.","p":"Correcto. Las motocicletas pueden usar el carril HOV, salvo que los letreros digan otra cosa."},"ref":{"doc":"CA","page":16}},{"id":"ca-100","scope":"CA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In California, a lane on the right is marked for buses only. You need to turn right at the next corner. What may you do?","o":["Never enter or cross the bus lane","Drive in the bus lane for a full block","Cross the bus lane to make the turn","Stop in the bus lane to wait"],"h1":"You may not drive or park there, but turning is a special case.","h2":"In California, you may not drive, stop or park in a bus-only lane, but you may cross it to make a right turn.","p":"Right. You may cross a bus lane to turn right."},"es":{"q":"En California, un carril a la derecha está marcado solo para autobuses. Usted necesita dar vuelta a la derecha en la próxima esquina. ¿Qué puede hacer?","o":["Nunca entrar ni cruzar el carril de autobuses","Manejar en el carril de autobuses toda una cuadra","Cruzar el carril de autobuses para dar la vuelta","Detenerse en el carril de autobuses a esperar"],"h1":"No puede manejar ni estacionarse ahí, pero dar vuelta es un caso especial.","h2":"En California, usted no puede manejar, detenerse ni estacionarse en un carril solo para autobuses, pero sí puede cruzarlo para dar vuelta a la derecha.","p":"Correcto. Puede cruzar el carril de autobuses para dar vuelta a la derecha."},"ref":{"doc":"CA","page":18}},{"id":"ca-101","scope":"CA","cat":"signals","sign":null,"c":0,"en":{"q":"In California, you are stopped at a red arrow pointing right. May you turn right after stopping?","o":["No, wait for a green light or arrow","Yes, after a full stop","Yes, if no one is crossing","Yes, but only at night"],"h1":"A red arrow is stricter than a plain red light.","h2":"In California, you may not turn right at a red arrow; you must wait until the light changes to green.","p":"Right. No turn on a red arrow; wait for green."},"es":{"q":"En California, usted está detenido ante una flecha roja que apunta a la derecha. ¿Puede dar vuelta a la derecha después de detenerse?","o":["No, espere la luz o flecha verde","Sí, después de detenerse por completo","Sí, si nadie está cruzando","Sí, pero solo de noche"],"h1":"Una flecha roja es más estricta que una luz roja normal.","h2":"En California, no puede dar vuelta a la derecha con una flecha roja; debe esperar a que la luz cambie a verde.","p":"Correcto. No se da vuelta con flecha roja; espere la verde."},"ref":{"doc":"CA","page":18}},{"id":"ca-102","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, where must you never make a U-turn?","o":["Across a double yellow line","In front of a fire station","At a green light with no sign","Through an opening in a divider"],"h1":"Think of a place where fire trucks must get out fast.","h2":"In California, you must never make a U-turn in front of a fire station, and you must never use a fire station driveway to turn around.","p":"Right. Never make a U-turn in front of a fire station."},"es":{"q":"En California, ¿dónde no debe hacer nunca una vuelta en U?","o":["Cruzando una línea amarilla doble","Frente a una estación de bomberos","Con luz verde y sin letrero","Por una abertura en el divisor"],"h1":"Piense en un lugar de donde los camiones de bomberos deben salir rápido.","h2":"En California, nunca debe hacer una vuelta en U frente a una estación de bomberos, ni usar la entrada de una estación de bomberos para dar la vuelta.","p":"Correcto. Nunca haga una vuelta en U frente a una estación de bomberos."},"ref":{"doc":"CA","page":20}},{"id":"ca-103","scope":"CA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In California, you want to pass on a two-lane road. How far ahead should a hill or curve be?","o":["At least 100 feet","At least two car lengths","At least 500 feet","At least one-third of a mile"],"h1":"It is a fraction of a mile.","h2":"In California, to pass safely, a hill or curve ahead should be at least one-third of a mile away.","p":"Right. The hill or curve should be at least one-third of a mile ahead."},"es":{"q":"En California, usted quiere rebasar en una carretera de dos carriles. ¿A qué distancia debe estar una colina o una curva?","o":["Por lo menos 100 pies","Por lo menos dos largos de carro","Por lo menos 500 pies","Por lo menos un tercio de milla"],"h1":"Es una fracción de milla.","h2":"En California, para rebasar con seguridad, la colina o curva que viene debe estar por lo menos a un tercio de milla.","p":"Correcto. La colina o curva debe estar por lo menos a un tercio de milla."},"ref":{"doc":"CA","page":24}},{"id":"ca-104","scope":"CA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In California, you drive a gasoline car. May you park in a space marked for charging zero-emission vehicles?","o":["Yes, if you stay under one hour","No, not unless you drive a zero-emission vehicle","Yes, at night only","Yes, if no other spaces are open"],"h1":"The space is kept for a certain kind of car.","h2":"In California, you may not park in a space set aside for parking or fueling zero-emission vehicles unless you are driving a zero-emission vehicle.","p":"Right. Those spaces are only for zero-emission vehicles."},"es":{"q":"En California, usted maneja un carro de gasolina. ¿Puede estacionarse en un espacio marcado para cargar vehículos de cero emisiones?","o":["Sí, si se queda menos de una hora","No, a menos que maneje un vehículo de cero emisiones","Sí, solo de noche","Sí, si no hay otros espacios libres"],"h1":"El espacio está reservado para cierto tipo de carro.","h2":"En California, no puede estacionarse en un espacio reservado para estacionar o cargar vehículos de cero emisiones, a menos que maneje un vehículo de cero emisiones.","p":"Correcto. Esos espacios son solo para vehículos de cero emisiones."},"ref":{"doc":"CA","page":28}},{"id":"ca-105","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, a police officer pulls you over. When must the officer tell you the reason for the stop?","o":["Only if you ask in writing","Only after giving you a ticket","Before asking questions about a crime or violation","Only in court"],"h1":"It comes at the start, before the questions.","h2":"In California, an officer must state the reason for a traffic stop before asking any questions about a crime or traffic violation, except when a life or property is in immediate danger.","p":"Right. The officer must give the reason before asking questions."},"es":{"q":"En California, un policía le indica que se detenga. ¿Cuándo debe el policía decirle el motivo de la parada?","o":["Solo si usted lo pide por escrito","Solo después de darle una multa","Antes de hacer preguntas sobre un delito o infracción","Solo en la corte"],"h1":"Se hace al comienzo, antes de las preguntas.","h2":"En California, un policía debe decir el motivo de una parada de tráfico antes de hacer preguntas sobre un delito o una infracción de tránsito, salvo cuando una vida o propiedad está en peligro inmediato.","p":"Correcto. El policía debe dar el motivo antes de hacer preguntas."},"ref":{"doc":"CA","page":29}},{"id":"ca-106","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, a city police officer stops you for a traffic ticket and asks about your immigration status. What does the handbook say?","o":["Local officers may not ask; you may refuse","You must answer or you will be arrested","You must show your passport to the officer","Only your passengers must answer it"],"h1":"Only one level of law enforcement may ask about this.","h2":"In California, only federal officers may ask about your immigration status; state and local officers may not ask, and you can decline to answer.","p":"Right. State and local officers may not ask, and you can decline to answer."},"es":{"q":"En California, un policía de la ciudad lo detiene por una multa de tránsito y le pregunta por su estatus migratorio. ¿Qué dice el manual?","o":["La policía local no puede preguntar; usted puede no contestar","Debe contestar o lo van a arrestar","Debe mostrarle su pasaporte al policía","Solo sus pasajeros deben contestar"],"h1":"Solo un nivel de las fuerzas del orden puede preguntar esto.","h2":"En California, solo los agentes federales pueden preguntar por su estatus migratorio; los policías estatales y locales no pueden preguntar, y usted puede negarse a contestar.","p":"Correcto. Los policías estatales y locales no pueden preguntar, y usted puede no contestar."},"ref":{"doc":"CA","page":30}},{"id":"ca-107","scope":"CA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In California, two cars meet on a steep, narrow mountain road and neither can pass. Which one has the right-of-way?","o":["The car facing downhill","The larger car","The car that honks first","The car facing uphill"],"h1":"The car going down has more control when backing up the hill.","h2":"In California, when two vehicles meet on a steep narrow road, the vehicle facing uphill has the right-of-way, and the downhill vehicle backs up.","p":"Right. The car facing uphill has the right-of-way."},"es":{"q":"En California, dos carros se encuentran en un camino de montaña empinado y angosto, y ninguno puede pasar. ¿Cuál tiene el derecho de paso?","o":["El carro que va cuesta abajo","El carro más grande","El carro que toca la bocina primero","El carro que va cuesta arriba"],"h1":"El carro que baja tiene más control al retroceder cuesta arriba.","h2":"En California, cuando dos vehículos se encuentran en un camino empinado y angosto, el que va cuesta arriba tiene el derecho de paso, y el que va cuesta abajo retrocede.","p":"Correcto. El carro que va cuesta arriba tiene el derecho de paso."},"ref":{"doc":"CA","page":42}},{"id":"ca-108","scope":"CA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In California, a streetcar is stopped ahead of you on a two-way street. The tracks leave room to pass on the right. On which side may you pass?","o":["On the left","On the right","On either side","You may not pass a streetcar"],"h1":"Passing on the left is allowed only in a few special cases.","h2":"In California, you may not pass a light rail vehicle or streetcar on the left unless the tracks leave no room on the right, you are on a one-way street, or an officer directs you.","p":"Right. Pass a streetcar on the right unless a special case applies."},"es":{"q":"En California, un tranvía está detenido delante de usted en una calle de doble sentido. Las vías dejan espacio para pasar por la derecha. ¿Por qué lado puede pasar?","o":["Por la izquierda","Por la derecha","Por cualquier lado","No puede pasar un tranvía"],"h1":"Pasar por la izquierda se permite solo en algunos casos especiales.","h2":"En California, no puede pasar por la izquierda un tren ligero o tranvía, a menos que las vías no dejen espacio a la derecha, esté en una calle de un solo sentido o un agente se lo indique.","p":"Correcto. Pase el tranvía por la derecha, salvo en un caso especial."},"ref":{"doc":"CA","page":44}},{"id":"ca-109","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, you hear about a big fire nearby and drive there to watch. What can happen?","o":["Nothing, if you stay in your car","You get a warning only","You can be arrested","You must pay a parking fee"],"h1":"You would be in the way of rescue crews.","h2":"In California, you can be arrested if you drive to the scene of a fire, collision or other disaster, because you get in the way of rescue workers.","p":"Right. Driving to a fire or crash scene to watch can get you arrested."},"es":{"q":"En California, usted oye de un incendio grande cerca y maneja hasta allí para mirar. ¿Qué puede pasar?","o":["Nada, si se queda en su carro","Solo le dan una advertencia","Lo pueden arrestar","Debe pagar estacionamiento"],"h1":"Usted estorbaría a los equipos de rescate.","h2":"En California, lo pueden arrestar si maneja al lugar de un incendio, choque u otro desastre, porque estorba a los equipos de rescate.","p":"Correcto. Ir a mirar un incendio o un choque puede causar su arresto."},"ref":{"doc":"CA","page":45}},{"id":"ca-110","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, you ride a bicycle after dark. What front light must it have?","o":["A white lamp seen from 300 feet","A red lamp seen from 100 feet","A yellow flashing light seen from 50 feet","No front light, only reflectors"],"h1":"The front light is white.","h2":"In California, a bicycle ridden at night must have a front lamp with a white light that can be seen from 300 feet.","p":"Right. A white front lamp seen from 300 feet."},"es":{"q":"En California, usted anda en bicicleta de noche. ¿Qué luz delantera debe tener?","o":["Una luz blanca visible desde 300 pies","Una luz roja visible desde 100 pies","Una luz amarilla intermitente visible desde 50 pies","Ninguna luz delantera, solo reflectores"],"h1":"La luz delantera es blanca.","h2":"En California, una bicicleta que se usa de noche debe tener una luz delantera blanca que se vea desde 300 pies.","p":"Correcto. Una luz blanca delantera visible desde 300 pies."},"ref":{"doc":"CA","page":47}},{"id":"ca-111","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, what is the penalty for assaulting a highway worker?","o":["A $100 fine only","A warning letter","Two points and traffic school","A fine up to $2,000 and up to one year in jail"],"h1":"It is much more than a traffic ticket.","h2":"In California, a person convicted of assaulting a highway worker faces a fine of up to $2,000 and up to one year in jail.","p":"Right. Up to $2,000 and up to one year."},"es":{"q":"En California, ¿cuál es la pena por agredir a un trabajador de carreteras?","o":["Solo una multa de $100","Una carta de advertencia","Dos puntos y escuela de tránsito","Una multa de hasta $2,000 y hasta un año de cárcel"],"h1":"Es mucho más que una multa de tránsito.","h2":"En California, una persona condenada por agredir a un trabajador de carreteras enfrenta una multa de hasta $2,000 y hasta un año de cárcel.","p":"Correcto. Hasta $2,000 y hasta un año."},"ref":{"doc":"CA","page":49}},{"id":"ca-112","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, a truck ahead of you has a diamond-shaped placard for a hazardous load. What must it do at a railroad crossing?","o":["Speed up to cross quickly","Stop before crossing the tracks","Cross only with flashers on","Wait for a flagger every time"],"h1":"Expect it to stop even when no train is coming.","h2":"In California, vehicles with a hazardous-load placard must stop before crossing railroad tracks.","p":"Right. It must stop before crossing the tracks."},"es":{"q":"En California, un camión delante de usted lleva un letrero en forma de diamante de carga peligrosa. ¿Qué debe hacer en un cruce de tren?","o":["Acelerar para cruzar rápido","Detenerse antes de cruzar las vías","Cruzar solo con las luces intermitentes","Esperar siempre a un abanderado"],"h1":"Espere que se detenga aunque no venga un tren.","h2":"En California, los vehículos con letrero de carga peligrosa deben detenerse antes de cruzar las vías del tren.","p":"Correcto. Debe detenerse antes de cruzar las vías."},"ref":{"doc":"CA","page":50}},{"id":"ca-113","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, what is the penalty for dumping or abandoning an animal on a highway?","o":["A $50 fine","A warning only","Up to $1,000, six months in jail, or both","One point on your record"],"h1":"It is a crime, not just a ticket.","h2":"In California, dumping or abandoning an animal on a highway can bring a fine of up to $1,000, six months in jail, or both.","p":"Right. Up to $1,000, six months in jail, or both."},"es":{"q":"En California, ¿cuál es la pena por tirar o abandonar un animal en una carretera?","o":["Una multa de $50","Solo una advertencia","Hasta $1,000, seis meses de cárcel, o ambos","Un punto en su historial"],"h1":"Es un delito, no solo una multa.","h2":"En California, tirar o abandonar un animal en una carretera puede costar una multa de hasta $1,000, seis meses de cárcel, o ambos.","p":"Correcto. Hasta $1,000, seis meses de cárcel, o ambos."},"ref":{"doc":"CA","page":52}},{"id":"ca-114","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, may a friend ride in the open bed of your pickup truck?","o":["Only if the bed has secure seats and seat belts","Yes, on any road","Yes, if you drive under 25 mph","Yes, if the friend is over 18"],"h1":"Think about what keeps a rider safe in a crash.","h2":"In California, you may not let a person ride in the back of a pickup or other truck unless it has secure seats and seat belts.","p":"Right. Only with secure seats and seat belts."},"es":{"q":"En California, ¿puede un amigo ir en la caja abierta de su camioneta pickup?","o":["Solo si la caja tiene asientos seguros y cinturones","Sí, en cualquier camino","Sí, si maneja a menos de 25 mph","Sí, si el amigo tiene más de 18 años"],"h1":"Piense en qué protege a una persona en un choque.","h2":"En California, no puede dejar que una persona vaya en la parte de atrás de una pickup u otro camión, a menos que tenga asientos seguros y cinturones de seguridad.","p":"Correcto. Solo con asientos seguros y cinturones."},"ref":{"doc":"CA","page":52}},{"id":"ca-115","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, where may you stick a 7-inch square sticker on your windshield?","o":["In the center, at eye level","Anywhere on the driver's side","Hanging from the rearview mirror","In the lower corner on the passenger's side"],"h1":"It must stay out of the driver's main view.","h2":"In California, a 7-inch square item may go on the lower corner of the windshield on the passenger's side, or the lower corner of the rear window.","p":"Right. The lower corner on the passenger's side."},"es":{"q":"En California, ¿dónde puede pegar una calcomanía cuadrada de 7 pulgadas en el parabrisas?","o":["En el centro, a la altura de los ojos","En cualquier parte del lado del conductor","Colgada del espejo retrovisor","En la esquina de abajo del lado del pasajero"],"h1":"Debe quedar fuera de la vista principal del conductor.","h2":"En California, un objeto cuadrado de 7 pulgadas puede ir en la esquina de abajo del parabrisas del lado del pasajero, o en la esquina de abajo de la ventana trasera.","p":"Correcto. En la esquina de abajo del lado del pasajero."},"ref":{"doc":"CA","page":53}},{"id":"ca-116","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, how long do most traffic convictions and collisions stay on your driving record?","o":["6 months","36 months or longer","12 months only","Forever, for every ticket"],"h1":"It is counted in months, and it is at least three years.","h2":"In California, traffic convictions and collisions stay on your driving record for 36 months or longer, depending on the type.","p":"Right. 36 months or longer."},"es":{"q":"En California, ¿cuánto tiempo quedan en su historial de manejo la mayoría de las condenas de tránsito y los choques?","o":["6 meses","36 meses o más","Solo 12 meses","Para siempre, cada multa"],"h1":"Se cuenta en meses, y son por lo menos tres años.","h2":"En California, las condenas de tránsito y los choques quedan en su historial de manejo por 36 meses o más, según el tipo.","p":"Correcto. 36 meses o más."},"ref":{"doc":"CA","page":54}},{"id":"ca-117","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, an adult driver gets 6 points. Within how many months can that lead to a suspension?","o":["6 months","12 months","24 months","60 months"],"h1":"The handbook list goes 4 points, 6 points, 8 points, with a longer time for each.","h2":"In California, an adult's license may be suspended for 6 points in 24 months.","p":"Right. 6 points in 24 months."},"es":{"q":"En California, un conductor adulto acumula 6 puntos. ¿En cuántos meses eso puede causar una suspensión?","o":["6 meses","12 meses","24 meses","60 meses"],"h1":"La lista del manual va de 4 puntos a 6 y a 8, con más tiempo para cada uno.","h2":"En California, la licencia de un adulto puede ser suspendida por 6 puntos en 24 meses.","p":"Correcto. 6 puntos en 24 meses."},"ref":{"doc":"CA","page":54}},{"id":"ca-118","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you finish traffic violator school for a one-point ticket. What happens to the ticket?","o":["Your insurance company is not told, but it stays on your record","It is erased from your record for good","Your fine is paid back to you in full","Your insurance company gets a copy of it"],"h1":"The insurance part changes, the record part does not.","h2":"In California, traffic violator school keeps a one-point ticket from being reported to your insurance company, but the ticket stays on your driving record.","p":"Right. Not reported to insurance, but still on your record."},"es":{"q":"En California, usted termina la escuela para infractores de tránsito por una multa de un punto. ¿Qué pasa con la multa?","o":["No se informa a su aseguradora, pero queda en su historial","Se borra de su historial para siempre","Le devuelven todo el dinero de la multa","Su aseguradora recibe una copia de ella"],"h1":"Cambia la parte del seguro, no la del historial.","h2":"En California, la escuela para infractores de tránsito evita que una multa de un punto se informe a su compañía de seguros, pero la multa queda en su historial de manejo.","p":"Correcto. No se informa al seguro, pero queda en su historial."},"ref":{"doc":"CA","page":54}},{"id":"ca-119","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, what can be a reason for the DMV to reexamine a driver?","o":["Turning 65","Buying a new car","Moving to a new county","A physical or mental condition"],"h1":"It is about ability, not age.","h2":"In California, a physical or mental condition or a poor driving record can be a reason for a DMV reexamination, but a driver's age is not.","p":"Right. A condition or a poor record, not age."},"es":{"q":"En California, ¿qué puede ser motivo para que el DMV vuelva a examinar a un conductor?","o":["Cumplir 65 años","Comprar un carro nuevo","Mudarse a otro condado","Una condición física o mental"],"h1":"Se trata de la capacidad, no de la edad.","h2":"En California, una condición física o mental o un mal historial de manejo puede ser motivo para un nuevo examen del DMV, pero la edad del conductor no lo es.","p":"Correcto. Una condición o un mal historial, no la edad."},"ref":{"doc":"CA","page":80}},{"id":"ca-120","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, an officer gives you a Notice of Priority Reexamination with the top box checked. How long do you have to contact the DMV?","o":["24 hours","Five working days","30 days","Six months"],"h1":"It is about one work week.","h2":"In California, after a Notice of Priority Reexamination with the top box checked, you have five working days to contact the DMV, or your driving privilege is automatically suspended.","p":"Right. Five working days."},"es":{"q":"En California, un agente le da un Aviso de Reexaminación Prioritaria con la casilla de arriba marcada. ¿Cuánto tiempo tiene para comunicarse con el DMV?","o":["24 horas","Cinco días hábiles","30 días","Seis meses"],"h1":"Es más o menos una semana de trabajo.","h2":"En California, después de un Aviso de Reexaminación Prioritaria con la casilla de arriba marcada, tiene cinco días hábiles para comunicarse con el DMV, o su privilegio de manejar se suspende automáticamente.","p":"Correcto. Cinco días hábiles."},"ref":{"doc":"CA","page":81}},{"id":"ca-121","scope":"CA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In California, the road is wet from rain. By how much should you slow down?","o":["5 to 10 mph","1 to 2 mph","To half your speed","To 5 mph"],"h1":"Wet roads call for a small cut; ice and snow call for more.","h2":"In California, on a wet road you should reduce your speed by 5 to 10 mph.","p":"Right. Slow down by 5 to 10 mph."},"es":{"q":"En California, la calle está mojada por la lluvia. ¿Cuánto debe bajar la velocidad?","o":["De 5 a 10 mph","De 1 a 2 mph","A la mitad de su velocidad","A 5 mph"],"h1":"En calles mojadas se reduce un poco; con hielo o nieve, mucho más.","h2":"En California, en una calle mojada debe reducir la velocidad de 5 a 10 mph.","p":"Correcto. Reduzca de 5 a 10 mph."},"ref":{"doc":"CA","page":61}},{"id":"ca-122","scope":"CA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In California, the road is covered with ice. What is the fastest you should drive?","o":["25 mph","15 mph","5 mph","Half the speed limit"],"h1":"It is the slowest number in the handbook's list.","h2":"In California, on ice you should reduce your speed to no more than 5 mph.","p":"Right. No more than 5 mph on ice."},"es":{"q":"En California, la calle está cubierta de hielo. ¿Cuál es la velocidad más alta a la que debe manejar?","o":["25 mph","15 mph","5 mph","La mitad del límite de velocidad"],"h1":"Es el número más bajo de la lista del manual.","h2":"En California, sobre hielo debe reducir la velocidad a no más de 5 mph.","p":"Correcto. No más de 5 mph sobre hielo."},"ref":{"doc":"CA","page":61}},{"id":"ca-123","scope":"CA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In California, a highway patrol car ahead weaves slowly across all lanes with its lights on, to slow traffic. What should you do?","o":["Pass it on the shoulder","Brake hard and stop in your lane","Speed up to get ahead of it","Slow to its speed and do not pass it"],"h1":"This is called a traffic break.","h2":"In California, during a traffic break you should turn on your flashers, slow down gradually to the officer's speed, and not drive past the patrol car.","p":"Right. Match the officer's speed and stay behind."},"es":{"q":"En California, una patrulla de carretera adelante zigzaguea despacio por todos los carriles con las luces encendidas para frenar el tráfico. ¿Qué debe hacer?","o":["Pasarla por el acotamiento","Frenar fuerte y detenerse en su carril","Acelerar para ponerse delante","Bajar a su velocidad y no pasarla"],"h1":"Esto se llama una pausa de tráfico.","h2":"En California, durante una pausa de tráfico debe encender las luces intermitentes, bajar poco a poco a la velocidad del agente y no pasar la patrulla.","p":"Correcto. Iguale la velocidad del agente y quédese detrás."},"ref":{"doc":"CA","page":64}},{"id":"ca-124","scope":"CA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In California, an adult driver uses a phone mounted on the dashboard for directions. How may the driver touch it while driving?","o":["With a long series of taps","With a single swipe or touch","Only while holding it","Only to type a text"],"h1":"Keep the contact as short as possible.","h2":"In California, a phone must be mounted on the windshield, dashboard or center console, and the driver may use only a single swipe or touch on it.","p":"Right. A single swipe or touch only."},"es":{"q":"En California, un conductor adulto usa un teléfono montado en el tablero para ver direcciones. ¿Cómo puede tocarlo mientras maneja?","o":["Con muchos toques seguidos","Con un solo deslizamiento o toque","Solo mientras lo sostiene en la mano","Solo para escribir un mensaje"],"h1":"El contacto debe ser lo más corto posible.","h2":"En California, el teléfono debe ir montado en el parabrisas, el tablero o la consola central, y el conductor solo puede deslizarlo o tocarlo una vez.","p":"Correcto. Un solo deslizamiento o toque."},"ref":{"doc":"CA","page":71}},{"id":"ca-125","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you are 35 years old and on DUI probation. At what blood alcohol level is it illegal for you to drive?","o":["0.01 percent or more","0.08 percent or more","0.05 percent or more","0.10 percent or more"],"h1":"On DUI probation, the limit is the same as for drivers under 21.","h2":"In California, a driver of any age who is on DUI probation may not drive with a blood alcohol level of 0.01 percent or more.","p":"Right. 0.01 percent or more for anyone on DUI probation."},"es":{"q":"En California, usted tiene 35 años y está en libertad condicional por DUI. ¿Con qué nivel de alcohol en la sangre es ilegal que maneje?","o":["0.01 por ciento o más","0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"En libertad condicional por DUI, el límite es el mismo que para menores de 21 años.","h2":"En California, un conductor de cualquier edad que está en libertad condicional por DUI no puede manejar con un nivel de alcohol en la sangre de 0.01 por ciento o más.","p":"Correcto. 0.01 por ciento o más para quien está en libertad condicional por DUI."},"ref":{"doc":"CA","page":73}},{"id":"ca-126","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, besides losing the license, what jail time can a court give for a DUI conviction?","o":["None, jail is never used","Exactly one weekend","Up to six months","At least five years"],"h1":"It is counted in months.","h2":"In California, a person convicted of DUI may be sentenced to up to six months in jail.","p":"Right. Up to six months in jail."},"es":{"q":"En California, además de perder la licencia, ¿cuánta cárcel puede dar un juez por una condena de DUI?","o":["Ninguna, nunca se usa la cárcel","Exactamente un fin de semana","Hasta seis meses","Por lo menos cinco años"],"h1":"Se cuenta en meses.","h2":"En California, una persona condenada por DUI puede recibir hasta seis meses de cárcel.","p":"Correcto. Hasta seis meses de cárcel."},"ref":{"doc":"CA","page":74}},{"id":"ca-127","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, a 19-year-old driver is caught with alcohol in the car. For how long can police impound the car?","o":["24 hours","Never; only the alcohol is taken","Up to 6 months","Up to 30 days"],"h1":"It is counted in days.","h2":"In California, if a driver under 21 is caught with alcohol in the vehicle, police can impound the vehicle for up to 30 days.","p":"Right. Up to 30 days."},"es":{"q":"En California, encuentran alcohol en el carro de un conductor de 19 años. ¿Por cuánto tiempo puede la policía incautar el carro?","o":["24 horas","Nunca; solo se llevan el alcohol","Hasta 6 meses","Hasta 30 días"],"h1":"Se cuenta en días.","h2":"En California, si un conductor menor de 21 años tiene alcohol en el vehículo, la policía puede incautar el vehículo hasta por 30 días.","p":"Correcto. Hasta 30 días."},"ref":{"doc":"CA","page":75}},{"id":"ca-128","scope":"CA","cat":"licensing","sign":null,"c":1,"en":{"q":"In California, a 17-year-old driver causes a crash. Who takes on the financial responsibility for the damages?","o":["Only the teen","The teen's parents or guardians","The driving school","The state of California"],"h1":"Think about who signed the permit application.","h2":"In California, parents or guardians take on financial responsibility for drivers under 18 and pay for damages if the teen is in a collision.","p":"Right. The parents or guardians."},"es":{"q":"En California, un conductor de 17 años causa un choque. ¿Quién asume la responsabilidad económica por los daños?","o":["Solo el joven","Los padres o tutores del joven","La escuela de manejo","El estado de California"],"h1":"Piense en quién firmó la solicitud del permiso.","h2":"En California, los padres o tutores asumen la responsabilidad económica por los conductores menores de 18 años y pagan los daños si el joven tiene un choque.","p":"Correcto. Los padres o tutores."},"ref":{"doc":"CA","page":76}},{"id":"ca-129","scope":"CA","cat":"licensing","sign":null,"c":0,"en":{"q":"In California, you have a crash in a store parking lot that causes $2,000 in damage. Must you report it to the DMV?","o":["Yes, with an SR 1 within 10 days","No, private property does not count","No, the police report is enough","Only if you caused it"],"h1":"The handbook says where the crash happens does not matter.","h2":"In California, a crash with more than $1,000 in damage must be reported to the DMV on an SR 1 within 10 days, even if it happened on private property.","p":"Right. Report it on an SR 1, even on private property."},"es":{"q":"En California, usted tiene un choque en el estacionamiento de una tienda que causa $2,000 en daños. ¿Debe informarlo al DMV?","o":["Sí, con un SR 1 dentro de 10 días","No, la propiedad privada no cuenta","No, basta con el informe de la policía","Solo si usted lo causó"],"h1":"El manual dice que no importa dónde ocurre el choque.","h2":"En California, un choque con más de $1,000 en daños se debe informar al DMV con un SR 1 dentro de 10 días, aunque haya ocurrido en propiedad privada.","p":"Correcto. Infórmelo con un SR 1, aun en propiedad privada."},"ref":{"doc":"CA","page":78}},{"id":"ca-130","scope":"CA","cat":"licensing","sign":null,"c":2,"en":{"q":"In California, about how long before your license expires does the DMV mail a renewal notice?","o":["About 10 days","About one year","About 90 days","The DMV does not send notices"],"h1":"It is about three months.","h2":"In California, the DMV sends a renewal notice to your address of record about 90 days before your license expires.","p":"Right. About 90 days before."},"es":{"q":"En California, ¿con cuánto tiempo de anticipación envía el DMV el aviso de renovación antes de que venza su licencia?","o":["Unos 10 días","Un año más o menos","Unos 90 días","El DMV no envía avisos"],"h1":"Son unos tres meses.","h2":"En California, el DMV envía un aviso de renovación a su dirección registrada unos 90 días antes de que venza su licencia.","p":"Correcto. Unos 90 días antes."},"ref":{"doc":"CA","page":82}},{"id":"ca-131","scope":"CA","cat":"licensing","sign":null,"c":3,"en":{"q":"In California, at what age can you get a Senior ID card with no fee?","o":["50","55","70","62"],"h1":"It is a few years after the Mature Driver course age of 55.","h2":"In California, people 62 years old or older can get a Senior ID card with no fee.","p":"Right. At 62 or older."},"es":{"q":"En California, ¿a qué edad puede obtener una tarjeta de identificación para personas mayores sin costo?","o":["50","55","70","62"],"h1":"Es unos años después de los 55 del curso para conductores mayores.","h2":"En California, las personas de 62 años o más pueden obtener una tarjeta de identificación para personas mayores sin costo.","p":"Correcto. A los 62 años o más."},"ref":{"doc":"CA","page":83}},{"id":"co-001","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"You must first finish a 30-hour driver education course to start this early.","h2":"In Colorado you can get an instruction permit at 15 if you have completed an approved 30-hour driver education course.","p":"Right. A Colorado permit can start at 15, after driver education."},"es":{"q":"En Colorado, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Primero debe terminar un curso de educación vial de 30 horas para empezar tan temprano.","h2":"En Colorado usted puede obtener un permiso de instrucción a los 15 años si completó un curso aprobado de educación vial de 30 horas.","p":"Correcto. El permiso en Colorado puede empezar a los 15, después de la educación vial."},"zh":{"q":"在 Colorado，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"要这么早开始，你必须先完成 30 小时的驾驶教育课程。","h2":"在 Colorado，如果你完成了认可的 30 小时驾驶教育课程，15 岁就可以拿到学习驾照。","p":"对。上完驾驶教育课以后，Colorado 的学习驾照可以从 15 岁开始。"},"vi":{"q":"Ở Colorado, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Bạn phải học xong một khóa giáo dục lái xe 30 giờ trước thì mới được bắt đầu sớm như vậy.","h2":"Ở Colorado, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu đã học xong một khóa giáo dục lái xe 30 giờ được chấp thuận.","p":"Đúng. Ở Colorado, giấy phép tập lái có thể bắt đầu từ 15 tuổi, sau khóa giáo dục lái xe."},"tl":{"q":"Sa Colorado, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Kailangan mo munang tapusin ang 30-oras na kurso sa driver education para makapagsimula nang ganito kaaga.","h2":"Sa Colorado, puwede kang kumuha ng instruction permit sa edad na 15 kung natapos mo na ang aprubadong 30-oras na kurso sa driver education.","p":"Tama. Puwedeng magsimula ang permit sa Colorado sa 15, pagkatapos ng driver education."},"ar":{"q":"في Colorado، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"يجب أن تُنهي أولًا دورة تعليم القيادة لمدة 30 ساعة لتبدأ بهذا العمر المبكر.","h2":"في Colorado يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا أنهيت دورة معتمدة لتعليم القيادة مدتها 30 ساعة.","p":"صحيح. في Colorado يمكن أن يبدأ التصريح في عمر 15 سنة، بعد دورة تعليم القيادة."},"ref":{"doc":"CO","page":null}},{"id":"co-002","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, starting January 1, 2027, what must a new permit applicant aged 15 to 17 complete first?","o":["A 4-hour driver awareness class","A first aid course","Ten hours with a tutor","A 30-hour driver education course"],"h1":"It is the longer of the two courses that used to be allowed.","h2":"From January 1, 2027, Colorado requires applicants aged 15 to 17 to finish an approved 30-hour driver education course, online or in person, before they get a permit.","p":"Right. From 2027, teens need the 30-hour driver education course first."},"es":{"q":"En Colorado, a partir del 1 de enero de 2027, ¿qué debe completar primero quien solicita un permiso entre los 15 y los 17 años?","o":["Una clase de conciencia vial de 4 horas","Un curso de primeros auxilios","Diez horas con un tutor","Un curso de educación vial de 30 horas"],"h1":"Es el más largo de los dos cursos que antes se permitían.","h2":"Desde el 1 de enero de 2027, Colorado exige que los solicitantes de 15 a 17 años terminen un curso aprobado de educación vial de 30 horas, en línea o en persona, antes de recibir el permiso.","p":"Correcto. Desde 2027, los adolescentes necesitan primero el curso de 30 horas."},"zh":{"q":"在 Colorado，从 2027 年 1 月 1 日起，15 到 17 岁的新学习驾照申请人必须先完成什么？","o":["4 小时的驾驶意识课","急救课程","和家教上十小时课","30 小时的驾驶教育课程"],"h1":"它是以前允许的两种课程里比较长的那个。","h2":"从 2027 年 1 月 1 日起，Colorado 要求 15 到 17 岁的申请人在拿学习驾照前，先完成认可的 30 小时驾驶教育课程，网上或面授都可以。","p":"对。从 2027 年起，青少年要先上 30 小时的驾驶教育课程。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2027, người xin giấy phép tập lái mới từ 15 đến 17 tuổi phải học xong gì trước?","o":["Một lớp nhận thức lái xe 4 giờ","Một khóa sơ cứu","Mười giờ học với gia sư","Một khóa giáo dục lái xe 30 giờ (driver education)"],"h1":"Đó là khóa dài hơn trong hai khóa trước đây được chấp nhận.","h2":"Từ ngày 1 tháng 1 năm 2027, Colorado yêu cầu người xin từ 15 đến 17 tuổi phải học xong một khóa giáo dục lái xe 30 giờ được chấp thuận, học trực tuyến hoặc trực tiếp, trước khi lấy giấy phép tập lái.","p":"Đúng. Từ năm 2027, thanh thiếu niên phải học khóa giáo dục lái xe 30 giờ trước."},"tl":{"q":"Sa Colorado, simula Enero 1, 2027, ano ang kailangang tapusin muna ng bagong aplikante para sa permit na 15 hanggang 17 taong gulang?","o":["Isang 4-oras na klase sa driver awareness","Isang kurso sa first aid","Sampung oras kasama ang isang tutor","Isang 30-oras na kurso sa driver education"],"h1":"Ito ang mas mahaba sa dalawang kursong dating pinapayagan.","h2":"Mula Enero 1, 2027, hinihingi ng Colorado na tapusin ng mga aplikanteng 15 hanggang 17 taong gulang ang aprubadong 30-oras na kurso sa driver education, online o personal, bago sila makakuha ng permit.","p":"Tama. Mula 2027, kailangan muna ng mga tinedyer ang 30-oras na kurso sa driver education."},"ar":{"q":"في Colorado، ابتداءً من 1 يناير 2027، ماذا يجب أن يُنهي أولًا المتقدّم الجديد للتصريح الذي عمره من 15 إلى 17 سنة؟","o":["درس توعية بالقيادة لمدة 4 ساعات","دورة إسعافات أولية","عشر ساعات مع مدرّس خاص","دورة تعليم القيادة لمدة 30 ساعة (driver education)"],"h1":"هي الأطول بين الدورتين اللتين كانتا مسموحتين من قبل.","h2":"ابتداءً من 1 يناير 2027، تطلب Colorado من المتقدّمين الذين أعمارهم من 15 إلى 17 سنة أن يُنهوا دورة معتمدة لتعليم القيادة مدتها 30 ساعة، عبر الإنترنت أو حضوريًا، قبل أن يحصلوا على التصريح.","p":"صحيح. ابتداءً من 2027، يحتاج المراهقون أولًا إلى دورة تعليم القيادة لمدة 30 ساعة."},"ref":{"doc":"CO","page":null}},{"id":"co-003","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, how long must a driver under 18 hold an instruction permit before getting a license?","o":["3 months","6 months","9 months","12 months"],"h1":"Think of one full year of practice.","h2":"A Colorado driver under 18 must hold the instruction permit for at least 12 months before getting a driver license, so there is a full year of practice.","p":"Right. Under 18, the permit must be held for 12 months."},"es":{"q":"En Colorado, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Piense en un año completo de práctica.","h2":"En Colorado, un conductor menor de 18 años debe tener el permiso de instrucción por lo menos 12 meses antes de obtener la licencia, para tener un año completo de práctica.","p":"Correcto. Si es menor de 18, debe tener el permiso 12 meses."},"zh":{"q":"在 Colorado，18 岁以下的司机必须持有学习驾照多久，才能拿到驾照？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"想一想整整一年的练习。","h2":"Colorado 18 岁以下的司机必须持有学习驾照至少 12 个月才能拿到驾照，这样就有整整一年的练习。","p":"对。18 岁以下，学习驾照必须持有 12 个月。"},"vi":{"q":"Ở Colorado, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Hãy nghĩ đến một năm tập lái trọn vẹn.","h2":"Ở Colorado, người lái dưới 18 tuổi phải giữ giấy phép tập lái ít nhất 12 tháng trước khi lấy bằng lái, để có trọn một năm tập lái.","p":"Đúng. Dưới 18 tuổi, phải giữ giấy phép tập lái 12 tháng."},"tl":{"q":"Sa Colorado, gaano katagal dapat hawak ng driver na wala pang 18 ang instruction permit bago makakuha ng lisensya?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Isipin ang isang buong taon ng pagsasanay.","h2":"Ang driver sa Colorado na wala pang 18 ay dapat humawak ng instruction permit nang hindi bababa sa 12 buwan bago makakuha ng driver license, para may isang buong taon ng pagsasanay.","p":"Tama. Kapag wala pang 18, dapat hawak ang permit nang 12 buwan."},"ar":{"q":"في Colorado، كم مدة يجب أن يحمل السائق الذي عمره أقل من 18 سنة تصريح التعلّم قبل الحصول على الرخصة؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"فكّر في سنة كاملة من التدريب.","h2":"يجب على السائق في Colorado الذي عمره أقل من 18 سنة أن يحمل تصريح التعلّم 12 شهرًا على الأقل قبل الحصول على رخصة القيادة، ليكون عنده سنة كاملة من التدريب.","p":"صحيح. تحت 18 سنة، يجب حمل التصريح 12 شهرًا."},"ref":{"doc":"CO","page":2}},{"id":"co-004","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","50 hours","70 hours"],"h1":"The log sheet asks for more than 40 hours.","h2":"A Colorado teen must log at least 50 hours of supervised driving before getting a license, so the new driver has real practice on the road.","p":"Right. Colorado asks for 50 logged hours."},"es":{"q":"En Colorado, ¿cuántas horas de manejo supervisado debe registrar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","70 horas"],"h1":"El registro pide más de 40 horas.","h2":"En Colorado, un adolescente debe registrar por lo menos 50 horas de manejo supervisado antes de obtener la licencia, para tener práctica real en la calle.","p":"Correcto. Colorado pide 50 horas registradas."},"zh":{"q":"在 Colorado，青少年拿驾照前必须记录多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","70 小时"],"h1":"记录表要求超过 40 小时。","h2":"Colorado 的青少年拿驾照前必须记录至少 50 小时有人监督的驾驶，这样新司机在路上有真正的练习。","p":"对。Colorado 要求记录 50 小时。"},"vi":{"q":"Ở Colorado, thanh thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","50 giờ","70 giờ"],"h1":"Tờ ghi chép yêu cầu nhiều hơn 40 giờ.","h2":"Ở Colorado, thanh thiếu niên phải ghi lại ít nhất 50 giờ lái xe có người giám sát trước khi lấy bằng lái, để người mới lái có thực hành thật trên đường.","p":"Đúng. Colorado yêu cầu ghi lại 50 giờ."},"tl":{"q":"Sa Colorado, ilang oras ng pagmamaneho na may gumagabay ang dapat itala ng tinedyer bago makakuha ng lisensya?","o":["20 oras","30 oras","50 oras","70 oras"],"h1":"Humihingi ang talaan ng higit sa 40 oras.","h2":"Ang tinedyer sa Colorado ay dapat magtala ng hindi bababa sa 50 oras ng pagmamaneho na may gumagabay bago makakuha ng lisensya, para may tunay na pagsasanay sa kalsada ang bagong driver.","p":"Tama. Humihingi ang Colorado ng 50 nakatalang oras."},"ar":{"q":"في Colorado، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","50 ساعة","70 ساعة"],"h1":"ورقة التسجيل تطلب أكثر من 40 ساعة.","h2":"يجب على المراهق في Colorado أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف قبل الحصول على الرخصة، ليكون عند السائق الجديد تدريب حقيقي على الطريق.","p":"صحيح. تطلب Colorado تسجيل 50 ساعة."},"ref":{"doc":"CO","page":2}},{"id":"co-005","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many of the teen's logged driving hours must be at night?","o":["10 hours","5 hours","15 hours","20 hours"],"h1":"It is one fifth of the total hours.","h2":"Of the 50 logged hours in Colorado, at least 10 must be driven at night, because driving in the dark is harder and needs practice.","p":"Right. 10 of the 50 hours must be at night."},"es":{"q":"En Colorado, ¿cuántas de las horas registradas por el adolescente deben ser de noche?","o":["10 horas","5 horas","15 horas","20 horas"],"h1":"Es una quinta parte del total de horas.","h2":"De las 50 horas registradas en Colorado, por lo menos 10 deben ser de noche, porque manejar en la oscuridad es más difícil y necesita práctica.","p":"Correcto. 10 de las 50 horas deben ser de noche."},"zh":{"q":"在 Colorado，青少年记录的驾驶时间里，有多少小时必须在晚上？","o":["10 小时","5 小时","15 小时","20 小时"],"h1":"它是全部时间的五分之一。","h2":"在 Colorado 记录的 50 小时里，至少 10 小时必须在晚上开，因为天黑开车更难，需要练习。","p":"对。50 小时里 10 小时必须在晚上。"},"vi":{"q":"Ở Colorado, trong số giờ lái xe đã ghi lại của thanh thiếu niên, bao nhiêu giờ phải lái vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","20 giờ"],"h1":"Đó là một phần năm tổng số giờ.","h2":"Trong 50 giờ đã ghi lại ở Colorado, ít nhất 10 giờ phải lái vào ban đêm, vì lái xe trong bóng tối khó hơn và cần tập luyện.","p":"Đúng. 10 trong 50 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Colorado, ilan sa mga nakatalang oras ng pagmamaneho ng tinedyer ang dapat sa gabi?","o":["10 oras","5 oras","15 oras","20 oras"],"h1":"Ito ay one-fifth (ikalima) ng kabuuang oras.","h2":"Sa 50 nakatalang oras sa Colorado, hindi bababa sa 10 ang dapat imaneho sa gabi, dahil mas mahirap magmaneho sa dilim at kailangan itong sanayin.","p":"Tama. 10 sa 50 oras ay dapat sa gabi."},"ar":{"q":"في Colorado، كم ساعة من ساعات القيادة المسجّلة للمراهق يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","20 ساعة"],"h1":"هي خُمس مجموع الساعات.","h2":"من الـ 50 ساعة المسجّلة في Colorado، يجب أن تكون 10 ساعات على الأقل قيادة في الليل، لأن القيادة في الظلام أصعب وتحتاج إلى تدريب.","p":"صحيح. 10 من الـ 50 ساعة يجب أن تكون في الليل."},"ref":{"doc":"CO","page":2}},{"id":"co-006","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, who must ride with a minor who drives on an instruction permit?","o":["Any licensed driver age 18 or older","A licensed driver age 21 or older in the front seat","Any adult sitting in the back seat","A driving instructor only"],"h1":"The person must be old enough to drink alcohol legally and sit close to the driver.","h2":"A Colorado minor with a permit must drive with a licensed driver who is at least 21 and sits in the front passenger seat, so help is always within reach.","p":"Right. The supervisor is licensed, 21 or older, and in the front seat."},"es":{"q":"En Colorado, ¿quién debe acompañar a un menor que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más en el asiento delantero","Cualquier adulto en el asiento trasero","Solamente un instructor de manejo"],"h1":"La persona debe tener edad legal para tomar alcohol y sentarse cerca del conductor.","h2":"En Colorado, un menor con permiso debe manejar con un conductor con licencia que tenga por lo menos 21 años y vaya en el asiento del pasajero delantero, para que la ayuda esté siempre a la mano.","p":"Correcto. El supervisor tiene licencia, 21 años o más, y va adelante."},"zh":{"q":"在 Colorado，未成年人用学习驾照开车时，谁必须同车？","o":["任何 18 岁或以上、有驾照的司机","坐在前排、21 岁或以上、有驾照的司机","任何坐在后排的成年人","只有驾驶教练"],"h1":"这个人必须到了可以合法喝酒的年龄，并且坐在司机旁边。","h2":"Colorado 持学习驾照的未成年人必须和至少 21 岁、有驾照、坐在前排乘客座位的司机一起开车，这样随时都有人可以帮忙。","p":"对。监督的人有驾照、21 岁或以上，并坐在前排。"},"vi":{"q":"Ở Colorado, ai phải ngồi cùng xe khi người chưa đủ 18 tuổi lái xe bằng giấy phép tập lái?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Một người có bằng lái từ 21 tuổi trở lên, ngồi ghế trước","Bất kỳ người lớn nào ngồi ghế sau","Chỉ giáo viên dạy lái xe"],"h1":"Người này phải đủ tuổi uống rượu hợp pháp và ngồi gần người lái.","h2":"Ở Colorado, người chưa đủ 18 tuổi có giấy phép tập lái phải lái cùng một người có bằng lái, ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước, để luôn có người giúp ngay bên cạnh.","p":"Đúng. Người giám sát có bằng lái, từ 21 tuổi trở lên, và ngồi ghế trước."},"tl":{"q":"Sa Colorado, sino ang dapat kasama ng menor de edad na nagmamaneho gamit ang instruction permit?","o":["Sinumang may lisensya na 18 taong gulang pataas","Isang may lisensyang driver na 21 taong gulang pataas, nakaupo sa harap","Sinumang adult na nakaupo sa likod","Driving instructor lamang"],"h1":"Ang tao ay dapat nasa legal na edad para uminom ng alak at nakaupo malapit sa driver.","h2":"Ang menor de edad sa Colorado na may permit ay dapat magmaneho kasama ang isang may lisensyang driver na hindi bababa sa 21 taong gulang at nakaupo sa harap na upuan ng pasahero, para laging malapit ang tulong.","p":"Tama. Ang gumagabay ay may lisensya, 21 pataas, at nasa harap na upuan."},"ar":{"q":"في Colorado، من يجب أن يركب مع القاصر الذي يقود بتصريح التعلّم؟","o":["أي سائق مرخّص عمره 18 سنة أو أكثر","سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي","أي شخص بالغ يجلس في المقعد الخلفي","مدرّب القيادة فقط"],"h1":"يجب أن يكون الشخص في العمر القانوني لشرب الكحول وأن يجلس قريبًا من السائق.","h2":"يجب على القاصر في Colorado الذي معه تصريح أن يقود مع سائق مرخّص عمره 21 سنة على الأقل ويجلس في مقعد الراكب الأمامي، لتكون المساعدة دائمًا قريبة.","p":"صحيح. المشرف مرخّص، وعمره 21 سنة أو أكثر، ويجلس في المقعد الأمامي."},"ref":{"doc":"CO","page":1}},{"id":"co-007","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, who usually signs the affidavit of liability for a driver under 18?","o":["A parent or legal guardian","A school principal","A driving school teacher","A police officer"],"h1":"It is the adult who takes financial responsibility for the teen.","h2":"In Colorado the affidavit of liability is usually signed by a parent or legal guardian, and that adult accepts legal responsibility for the teen's driving.","p":"Right. A parent or legal guardian signs it."},"es":{"q":"En Colorado, ¿quién firma normalmente la declaración de responsabilidad de un conductor menor de 18 años?","o":["Un padre, madre o tutor legal","El director de la escuela","Un maestro de manejo","Un agente de policía"],"h1":"Es el adulto que asume la responsabilidad económica del adolescente.","h2":"En Colorado, la declaración jurada de responsabilidad normalmente la firma uno de los padres o el tutor legal, y ese adulto acepta la responsabilidad legal por la manera de manejar del joven.","p":"Correcto. La firma un padre, madre o tutor legal."},"zh":{"q":"在 Colorado，18 岁以下司机的责任声明书（affidavit of liability）通常由谁签字？","o":["父母或法定监护人","学校校长","驾校老师","警察"],"h1":"它是为这个青少年承担经济责任的成年人。","h2":"在 Colorado，责任声明书通常由父母或法定监护人签字，这个成年人为青少年的驾驶承担法律责任。","p":"对。由父母或法定监护人签字。"},"vi":{"q":"Ở Colorado, ai thường ký bản cam kết trách nhiệm (affidavit of liability) cho người lái dưới 18 tuổi?","o":["Cha mẹ hoặc người giám hộ hợp pháp","Hiệu trưởng trường học","Giáo viên trường dạy lái xe","Cảnh sát"],"h1":"Đó là người lớn chịu trách nhiệm tài chính cho thanh thiếu niên.","h2":"Ở Colorado, bản cam kết trách nhiệm thường do cha mẹ hoặc người giám hộ hợp pháp ký, và người lớn đó nhận trách nhiệm pháp lý về việc lái xe của thanh thiếu niên.","p":"Đúng. Cha mẹ hoặc người giám hộ hợp pháp ký bản này."},"tl":{"q":"Sa Colorado, sino ang karaniwang pumipirma sa affidavit of liability para sa driver na wala pang 18?","o":["Magulang o legal na tagapag-alaga","Punong-guro ng paaralan","Guro sa driving school","Pulis"],"h1":"Ito ang adult na umaako ng pinansyal na pananagutan para sa tinedyer.","h2":"Sa Colorado, ang affidavit of liability ay karaniwang pinipirmahan ng magulang o legal na tagapag-alaga, at ang adult na iyon ang umaako ng legal na pananagutan sa pagmamaneho ng tinedyer.","p":"Tama. Magulang o legal na tagapag-alaga ang pumipirma."},"ar":{"q":"في Colorado، من يوقّع عادةً إقرار المسؤولية (affidavit of liability) للسائق الذي عمره أقل من 18 سنة؟","o":["أحد الوالدين أو الوصي القانوني","مدير المدرسة","معلّم في مدرسة القيادة","شرطي"],"h1":"هو الشخص البالغ الذي يتحمّل المسؤولية المالية عن المراهق.","h2":"في Colorado يوقّع إقرار المسؤولية عادةً أحد الوالدين أو الوصي القانوني، وهذا الشخص البالغ يقبل المسؤولية القانونية عن قيادة المراهق.","p":"صحيح. يوقّعه أحد الوالدين أو الوصي القانوني."},"ref":{"doc":"CO","page":2}},{"id":"co-008","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, during the first year with a license, when may a teen driver not drive?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"The limit begins exactly when the date changes.","h2":"A Colorado driver under 18 in the first year of a license may not drive from midnight to 5 a.m., except for allowed reasons such as work, school or a medical emergency.","p":"Right. No driving from midnight to 5 a.m. in the first year."},"es":{"q":"En Colorado, durante el primer año con licencia, ¿cuándo no puede manejar un conductor adolescente?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"El límite empieza justo cuando cambia la fecha.","h2":"En Colorado, un conductor menor de 18 años en su primer año con licencia no puede manejar de medianoche a 5 a.m., salvo por razones permitidas como trabajo, escuela o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m. el primer año."},"zh":{"q":"在 Colorado，拿到驾照的第一年，青少年司机什么时候不能开车？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"这个限制正好在日期变换时开始。","h2":"Colorado 18 岁以下的司机在拿到驾照的第一年，午夜到早上 5 点不能开车，工作、上学或医疗紧急情况等允许的理由除外。","p":"对。第一年午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Colorado, trong năm đầu tiên có bằng lái, thanh thiếu niên không được lái xe vào giờ nào?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu đúng lúc sang ngày mới.","h2":"Ở Colorado, người lái dưới 18 tuổi trong năm đầu có bằng lái không được lái xe từ nửa đêm đến 5 giờ sáng, trừ các lý do được phép như đi làm, đi học hoặc cấp cứu y tế.","p":"Đúng. Trong năm đầu, không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Colorado, sa unang taon na may lisensya, kailan bawal magmaneho ang tinedyer na driver?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon eksakto kapag nagpalit ang petsa.","h2":"Ang driver sa Colorado na wala pang 18 at nasa unang taon ng lisensya ay bawal magmaneho mula hatinggabi hanggang 5 a.m., maliban sa mga pinapayagang dahilan gaya ng trabaho, paaralan o medical emergency.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. sa unang taon."},"ar":{"q":"في Colorado، خلال السنة الأولى مع الرخصة، متى لا يجوز للسائق المراهق أن يقود؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"يبدأ المنع بالضبط عندما يتغيّر التاريخ.","h2":"السائق في Colorado الذي عمره أقل من 18 سنة وفي سنته الأولى مع الرخصة لا يجوز له أن يقود من منتصف الليل إلى 5 صباحًا، إلا لأسباب مسموحة مثل العمل أو المدرسة أو حالة طوارئ طبية.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا في السنة الأولى."},"ref":{"doc":"CO","page":2}},{"id":"co-009","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, during the first six months with a license, which passengers may a teen driver carry?","o":["Up to two friends of any age","One passenger under 21","Up to three passengers under 21","Only passengers 21 or older"],"h1":"Siblings and medical emergencies are the only exceptions to this strict rule.","h2":"For the first six months with a Colorado license, a teen may carry only passengers who are 21 or older, except brothers and sisters or in a medical emergency.","p":"Right. In the first six months, only passengers 21 or older."},"es":{"q":"En Colorado, durante los primeros seis meses con licencia, ¿qué pasajeros puede llevar un conductor adolescente?","o":["Hasta dos amigos de cualquier edad","Un pasajero menor de 21 años","Hasta tres pasajeros menores de 21 años","Solamente pasajeros de 21 años o más"],"h1":"Los hermanos y las emergencias médicas son las únicas excepciones a esta regla estricta.","h2":"Durante los primeros seis meses con licencia en Colorado, un adolescente solo puede llevar pasajeros de 21 años o más, salvo sus hermanos o en una emergencia médica.","p":"Correcto. Los primeros seis meses, solo pasajeros de 21 años o más."},"zh":{"q":"在 Colorado，拿到驾照的前六个月，青少年司机可以载哪些乘客？","o":["最多两位任何年龄的朋友","一位 21 岁以下的乘客","最多三位 21 岁以下的乘客","只有 21 岁或以上的乘客"],"h1":"兄弟姐妹和医疗紧急情况是这个严格规定仅有的例外。","h2":"拿到 Colorado 驾照的前六个月，青少年只能载 21 岁或以上的乘客，兄弟姐妹或医疗紧急情况除外。","p":"对。前六个月只能载 21 岁或以上的乘客。"},"vi":{"q":"Ở Colorado, trong sáu tháng đầu có bằng lái, thanh thiếu niên được chở những hành khách nào?","o":["Tối đa hai người bạn ở bất kỳ tuổi nào","Một hành khách dưới 21 tuổi","Tối đa ba hành khách dưới 21 tuổi","Chỉ hành khách từ 21 tuổi trở lên"],"h1":"Anh chị em ruột và trường hợp cấp cứu y tế là ngoại lệ duy nhất của quy định nghiêm ngặt này.","h2":"Trong sáu tháng đầu có bằng lái Colorado, thanh thiếu niên chỉ được chở hành khách từ 21 tuổi trở lên, trừ anh chị em ruột hoặc khi có cấp cứu y tế.","p":"Đúng. Trong sáu tháng đầu, chỉ chở hành khách từ 21 tuổi trở lên."},"tl":{"q":"Sa Colorado, sa unang anim na buwan na may lisensya, aling mga pasahero ang puwedeng isakay ng tinedyer na driver?","o":["Hanggang dalawang kaibigan ng anumang edad","Isang pasahero na wala pang 21","Hanggang tatlong pasahero na wala pang 21","Mga pasahero lamang na 21 pataas"],"h1":"Ang mga kapatid at medical emergency lamang ang eksepsiyon sa mahigpit na patakarang ito.","h2":"Sa unang anim na buwan na may lisensya sa Colorado, puwedeng magsakay ang tinedyer ng mga pasahero lamang na 21 pataas, maliban sa mga kapatid o kapag may medical emergency.","p":"Tama. Sa unang anim na buwan, mga pasahero lamang na 21 pataas."},"ar":{"q":"في Colorado، خلال الأشهر الستة الأولى مع الرخصة، أي ركّاب يجوز للسائق المراهق أن يحملهم؟","o":["حتى صديقين من أي عمر","راكب واحد عمره أقل من 21 سنة","حتى ثلاثة ركّاب أعمارهم أقل من 21 سنة","الركّاب الذين عمرهم 21 سنة أو أكثر فقط"],"h1":"الإخوة والأخوات وحالات الطوارئ الطبية هي الاستثناءات الوحيدة لهذه القاعدة الصارمة.","h2":"في الأشهر الستة الأولى مع رخصة Colorado، يجوز للمراهق أن يحمل فقط ركّابًا عمرهم 21 سنة أو أكثر، إلا الإخوة والأخوات أو في حالة طوارئ طبية.","p":"صحيح. في الأشهر الستة الأولى، فقط الركّاب الذين عمرهم 21 سنة أو أكثر."},"ref":{"doc":"CO","page":2}},{"id":"co-010","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, during the second six months with a license, how many passengers under 21 may a teen driver carry?","o":["None at all","One","Two","Three"],"h1":"The limit loosens a little after the first six months.","h2":"In the second six months with a Colorado license, a teen may carry one passenger under 21, which is a small step up from the first six months.","p":"Right. One passenger under 21 is allowed in the second six months."},"es":{"q":"En Colorado, durante los segundos seis meses con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite se relaja un poco después de los primeros seis meses.","h2":"En los segundos seis meses con licencia en Colorado, un adolescente puede llevar un pasajero menor de 21 años, un pequeño paso más que en los primeros seis meses.","p":"Correcto. En los segundos seis meses se permite un pasajero menor de 21."},"zh":{"q":"在 Colorado，拿到驾照的第二个六个月，青少年司机可以载多少位 21 岁以下的乘客？","o":["一位都不行","一位","两位","三位"],"h1":"过了前六个月，限制放松一点。","h2":"拿到 Colorado 驾照的第二个六个月，青少年可以载一位 21 岁以下的乘客，比前六个月放宽了一小步。","p":"对。第二个六个月可以载一位 21 岁以下的乘客。"},"vi":{"q":"Ở Colorado, trong sáu tháng thứ hai có bằng lái, thanh thiếu niên được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai cả","Một","Hai","Ba"],"h1":"Giới hạn được nới lỏng một chút sau sáu tháng đầu.","h2":"Trong sáu tháng thứ hai có bằng lái Colorado, thanh thiếu niên được chở một hành khách dưới 21 tuổi, nhiều hơn một chút so với sáu tháng đầu.","p":"Đúng. Trong sáu tháng thứ hai, được chở một hành khách dưới 21 tuổi."},"tl":{"q":"Sa Colorado, sa ikalawang anim na buwan na may lisensya, ilang pasahero na wala pang 21 ang puwedeng isakay ng tinedyer na driver?","o":["Wala talaga","Isa","Dalawa","Tatlo"],"h1":"Lumuluwag nang kaunti ang limitasyon pagkatapos ng unang anim na buwan.","h2":"Sa ikalawang anim na buwan na may lisensya sa Colorado, puwedeng magsakay ang tinedyer ng isang pasahero na wala pang 21, na maliit na hakbang pataas mula sa unang anim na buwan.","p":"Tama. Isang pasahero na wala pang 21 ang pinapayagan sa ikalawang anim na buwan."},"ar":{"q":"في Colorado، خلال الأشهر الستة الثانية مع الرخصة، كم راكبًا عمره أقل من 21 سنة يجوز للسائق المراهق أن يحمل؟","o":["لا أحد أبدًا","واحد","اثنان","ثلاثة"],"h1":"يخفّ المنع قليلًا بعد الأشهر الستة الأولى.","h2":"في الأشهر الستة الثانية مع رخصة Colorado، يجوز للمراهق أن يحمل راكبًا واحدًا عمره أقل من 21 سنة، وهذه خطوة صغيرة أكثر من الأشهر الستة الأولى.","p":"صحيح. يُسمح براكب واحد عمره أقل من 21 سنة في الأشهر الستة الثانية."},"ref":{"doc":"CO","page":2}},{"id":"co-011","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, which young passengers may ride with a new teen driver at any time?","o":["Classmates","Teammates","The driver's brothers and sisters","Neighbors' children"],"h1":"Think of family who live in the same home.","h2":"Colorado lets a new teen driver carry brothers and sisters at any time, even while other passengers under 21 are limited.","p":"Right. Siblings may ride at any time."},"es":{"q":"En Colorado, ¿qué pasajeros jóvenes pueden viajar con un conductor adolescente nuevo en cualquier momento?","o":["Compañeros de clase","Compañeros de equipo","Los hermanos y hermanas del conductor","Los hijos de los vecinos"],"h1":"Piense en la familia que vive en la misma casa.","h2":"Colorado permite que un conductor adolescente nuevo lleve a sus hermanos y hermanas en cualquier momento, aunque otros pasajeros menores de 21 años estén limitados.","p":"Correcto. Los hermanos pueden ir en cualquier momento."},"zh":{"q":"在 Colorado，哪些年轻乘客任何时候都可以坐新的青少年司机的车？","o":["同学","队友","司机的兄弟姐妹","邻居的孩子"],"h1":"想一想住在同一个家里的家人。","h2":"Colorado 允许新的青少年司机任何时候载兄弟姐妹，即使其他 21 岁以下的乘客有限制。","p":"对。兄弟姐妹任何时候都可以坐车。"},"vi":{"q":"Ở Colorado, những hành khách trẻ nào được đi cùng thanh thiếu niên mới lái xe vào bất kỳ lúc nào?","o":["Bạn cùng lớp","Bạn cùng đội","Anh chị em ruột của người lái","Con của hàng xóm"],"h1":"Hãy nghĩ đến người trong gia đình sống cùng nhà.","h2":"Colorado cho phép thanh thiếu niên mới lái xe chở anh chị em ruột vào bất kỳ lúc nào, ngay cả khi các hành khách khác dưới 21 tuổi bị giới hạn.","p":"Đúng. Anh chị em ruột được đi cùng bất kỳ lúc nào."},"tl":{"q":"Sa Colorado, aling mga batang pasahero ang puwedeng sumakay kasama ng bagong tinedyer na driver anumang oras?","o":["Mga kaklase","Mga kakampi sa team","Mga kapatid ng driver","Mga anak ng kapitbahay"],"h1":"Isipin ang pamilyang nakatira sa iisang bahay.","h2":"Pinapayagan ng Colorado ang bagong tinedyer na driver na magsakay ng mga kapatid anumang oras, kahit limitado ang ibang pasahero na wala pang 21.","p":"Tama. Puwedeng sumakay ang mga kapatid anumang oras."},"ar":{"q":"في Colorado، أي ركّاب صغار يجوز لهم الركوب مع السائق المراهق الجديد في أي وقت؟","o":["زملاء الصف","زملاء الفريق","إخوة السائق وأخواته","أطفال الجيران"],"h1":"فكّر في العائلة التي تعيش في البيت نفسه.","h2":"تسمح Colorado للسائق المراهق الجديد أن يحمل إخوته وأخواته في أي وقت، حتى عندما يكون عدد الركّاب الآخرين الذين أعمارهم أقل من 21 سنة محدودًا.","p":"صحيح. يجوز للإخوة والأخوات الركوب في أي وقت."},"ref":{"doc":"CO","page":2}},{"id":"co-012","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many passengers may sit in the front seat when a new teen driver is driving?","o":["Only one","Two, if they are small","As many as fit","None at all"],"h1":"Each front-seat rider needs a seat belt of their own.","h2":"Colorado allows only one passenger in the front seat with a new teen driver, and everyone in the car must wear a seat belt.","p":"Right. Only one passenger may sit in the front."},"es":{"q":"En Colorado, ¿cuántos pasajeros pueden ir en el asiento delantero cuando maneja un adolescente nuevo?","o":["Solamente uno","Dos, si son pequeños","Todos los que quepan","Ninguno"],"h1":"Cada pasajero de adelante necesita su propio cinturón.","h2":"Colorado permite solo un pasajero en el asiento delantero con un conductor adolescente nuevo, y todos en el carro deben usar el cinturón de seguridad.","p":"Correcto. Solo un pasajero puede ir adelante."},"zh":{"q":"在 Colorado，新的青少年司机开车时，前排可以坐几位乘客？","o":["只有一位","两位，如果他们个子小","坐得下几位就几位","一位都不行"],"h1":"每位坐前排的人都需要自己的安全带。","h2":"Colorado 只允许一位乘客和新的青少年司机坐在前排，车里每个人都必须系安全带。","p":"对。前排只能坐一位乘客。"},"vi":{"q":"Ở Colorado, khi thanh thiếu niên mới lái xe, bao nhiêu hành khách được ngồi ở ghế trước?","o":["Chỉ một người","Hai người, nếu họ nhỏ","Bao nhiêu người cũng được nếu vừa chỗ","Không ai cả"],"h1":"Mỗi người ngồi ghế trước cần dây an toàn riêng.","h2":"Colorado chỉ cho phép một hành khách ngồi ghế trước với thanh thiếu niên mới lái xe, và mọi người trong xe phải thắt dây an toàn.","p":"Đúng. Chỉ một hành khách được ngồi ghế trước."},"tl":{"q":"Sa Colorado, ilang pasahero ang puwedeng umupo sa harap kapag nagmamaneho ang bagong tinedyer na driver?","o":["Isa lamang","Dalawa, kung maliliit sila","Kahit ilan basta kasya","Wala talaga"],"h1":"Bawat nakaupo sa harap ay kailangan ng sariling seat belt.","h2":"Isang pasahero lamang sa harap na upuan ang pinapayagan ng Colorado kasama ng bagong tinedyer na driver, at lahat ng nasa sasakyan ay dapat naka-seat belt.","p":"Tama. Isang pasahero lamang ang puwedeng umupo sa harap."},"ar":{"q":"في Colorado، كم راكبًا يجوز أن يجلس في المقعد الأمامي عندما يقود سائق مراهق جديد؟","o":["واحد فقط","اثنان، إذا كانا صغيرين","أي عدد يتّسع له المكان","لا أحد أبدًا"],"h1":"كل من يجلس في الأمام يحتاج إلى حزام أمان خاص به.","h2":"تسمح Colorado براكب واحد فقط في المقعد الأمامي مع السائق المراهق الجديد، ويجب على كل من في السيارة أن يضع حزام الأمان.","p":"صحيح. راكب واحد فقط يجوز أن يجلس في الأمام."},"ref":{"doc":"CO","page":null}},{"id":"co-013","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, since January 1, 2025, when may a driver hold a phone to talk or text while driving?","o":["Only to call for help in an emergency","When stopped at a red light","When the call is short","When traffic is light"],"h1":"Holding the phone is allowed only when help is needed.","h2":"Since January 1, 2025, a Colorado driver may not hold a phone to talk or text while driving, except to call police, fire or other help in an emergency.","p":"Right. Hold the phone only to call for help in an emergency."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cuándo puede un conductor sostener el teléfono en la mano para hablar o enviar mensajes mientras maneja?","o":["Solo para pedir ayuda en una emergencia","Cuando está detenido en un semáforo en rojo","Cuando la llamada es corta","Cuando hay poco tráfico"],"h1":"Sostener el teléfono solo se permite cuando se necesita ayuda.","h2":"Desde el 1 de enero de 2025, un conductor en Colorado no puede sostener el teléfono para hablar o enviar mensajes mientras maneja, excepto para llamar a la policía, a los bomberos u otra ayuda en una emergencia.","p":"Correcto. Sostenga el teléfono solo para pedir ayuda en una emergencia."},"zh":{"q":"在 Colorado，从 2025 年 1 月 1 日起，司机开车时什么时候可以手拿手机打电话或发短信？","o":["只有在紧急情况下打电话求助","在红灯停车时","电话很短时","车不多时"],"h1":"只有需要帮助时才可以拿着手机。","h2":"从 2025 年 1 月 1 日起，Colorado 的司机开车时不能手拿手机打电话或发短信，紧急情况下打给警察、消防或其他求助除外。","p":"对。只有在紧急情况下求助时才可以拿手机。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2025, khi nào người lái được cầm điện thoại để nói chuyện hoặc nhắn tin trong lúc lái xe?","o":["Chỉ khi gọi cấp cứu trong trường hợp khẩn cấp","Khi dừng ở đèn đỏ","Khi cuộc gọi ngắn","Khi đường vắng xe"],"h1":"Chỉ được cầm điện thoại khi cần người giúp.","h2":"Từ ngày 1 tháng 1 năm 2025, người lái ở Colorado không được cầm điện thoại để nói chuyện hoặc nhắn tin khi lái xe, trừ khi gọi cảnh sát, cứu hỏa hoặc sự giúp đỡ khác trong trường hợp khẩn cấp.","p":"Đúng. Chỉ cầm điện thoại để gọi cấp cứu khi khẩn cấp."},"tl":{"q":"Sa Colorado, mula Enero 1, 2025, kailan puwedeng hawakan ng driver ang telepono para tumawag o mag-text habang nagmamaneho?","o":["Para lamang humingi ng tulong sa emergency","Kapag nakahinto sa pulang ilaw","Kapag maikli ang tawag","Kapag kaunti ang trapiko"],"h1":"Pinapayagan lamang hawakan ang telepono kapag kailangan ng tulong.","h2":"Mula Enero 1, 2025, bawal sa driver sa Colorado na hawakan ang telepono para tumawag o mag-text habang nagmamaneho, maliban kung tatawag sa pulis, bumbero o ibang tulong sa emergency.","p":"Tama. Hawakan lamang ang telepono para humingi ng tulong sa emergency."},"ar":{"q":"في Colorado، منذ 1 يناير 2025، متى يجوز للسائق أن يمسك الهاتف ليتكلّم أو يرسل رسالة أثناء القيادة؟","o":["فقط ليطلب المساعدة في حالة طوارئ","عندما يتوقّف عند الإشارة الحمراء","عندما تكون المكالمة قصيرة","عندما تكون حركة المرور خفيفة"],"h1":"إمساك الهاتف مسموح فقط عندما تحتاج إلى مساعدة.","h2":"منذ 1 يناير 2025، لا يجوز للسائق في Colorado أن يمسك الهاتف ليتكلّم أو يرسل رسالة أثناء القيادة، إلا ليتّصل بالشرطة أو الإطفاء أو مساعدة أخرى في حالة طوارئ.","p":"صحيح. أمسك الهاتف فقط لتطلب المساعدة في حالة طوارئ."},"ref":{"doc":"CO","page":null}},{"id":"co-014","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, since January 1, 2025, how may a driver age 18 or older use a phone while driving?","o":["Holding it at any time","Holding it only on highways","Only with a hands-free accessory","Not at all, even hands-free"],"h1":"The adult's hands must stay free.","h2":"Since January 1, 2025, Colorado drivers 18 and older may not hold or handle a phone while driving; they may use it only with a hands-free accessory.","p":"Right. Adults must use hands-free."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿cómo puede usar el teléfono al manejar un conductor de 18 años o más?","o":["Sosteniéndolo en cualquier momento","Sosteniéndolo solo en las autopistas","Solo con un accesorio de manos libres","De ninguna manera, ni con manos libres"],"h1":"Las manos del adulto deben quedar libres.","h2":"Desde el 1 de enero de 2025, los conductores de 18 años o más en Colorado no pueden sostener ni manipular el teléfono al manejar; solo pueden usarlo con un accesorio de manos libres.","p":"Correcto. Los adultos deben usar manos libres."},"zh":{"q":"在 Colorado，从 2025 年 1 月 1 日起，18 岁或以上的司机开车时可以怎样用手机？","o":["任何时候都可以拿着","只在公路上可以拿着","只能用免持配件","完全不能用，免持也不行"],"h1":"成年人的手必须空着。","h2":"从 2025 年 1 月 1 日起，Colorado 18 岁或以上的司机开车时不能拿着或操作手机；只能用免持配件来用手机。","p":"对。成年人必须用免持。"},"vi":{"q":"Ở Colorado, từ ngày 1 tháng 1 năm 2025, người lái từ 18 tuổi trở lên được dùng điện thoại khi lái xe như thế nào?","o":["Cầm trên tay bất kỳ lúc nào","Chỉ cầm trên tay khi đi xa lộ","Chỉ với thiết bị rảnh tay (hands-free)","Hoàn toàn không, kể cả rảnh tay"],"h1":"Tay của người lớn phải được để trống.","h2":"Từ ngày 1 tháng 1 năm 2025, người lái ở Colorado từ 18 tuổi trở lên không được cầm hoặc thao tác điện thoại khi lái xe; họ chỉ được dùng với thiết bị rảnh tay.","p":"Đúng. Người lớn phải dùng thiết bị rảnh tay."},"tl":{"q":"Sa Colorado, mula Enero 1, 2025, paano puwedeng gamitin ng driver na 18 pataas ang telepono habang nagmamaneho?","o":["Hawak ito anumang oras","Hawak ito sa highway lamang","Gamit lamang ang hands-free na accessory","Hindi talaga, kahit hands-free"],"h1":"Dapat malaya ang mga kamay ng adult.","h2":"Mula Enero 1, 2025, bawal sa mga driver sa Colorado na 18 pataas na hawakan o galawin ang telepono habang nagmamaneho; puwede lamang nila itong gamitin sa hands-free na accessory.","p":"Tama. Dapat gumamit ng hands-free ang mga adult."},"ar":{"q":"في Colorado، منذ 1 يناير 2025، كيف يجوز للسائق الذي عمره 18 سنة أو أكثر أن يستعمل الهاتف أثناء القيادة؟","o":["يمسكه في أي وقت","يمسكه على الطرق السريعة فقط","فقط مع جهاز بدون استعمال اليدين (hands-free)","لا يجوز أبدًا، حتى بدون استعمال اليدين"],"h1":"يجب أن تبقى يدا البالغ حرّتين.","h2":"منذ 1 يناير 2025، لا يجوز للسائقين في Colorado الذين عمرهم 18 سنة أو أكثر أن يمسكوا الهاتف أو يستعملوه بأيديهم أثناء القيادة؛ يجوز لهم استعماله فقط مع جهاز بدون استعمال اليدين.","p":"صحيح. يجب على البالغين استعمال الهاتف بدون اليدين."},"ref":{"doc":"CO","page":null}},{"id":"co-015","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, what is the penalty for a first offense of holding a phone while driving?","o":["A warning only","A $75 fine and 2 points","A $500 fine and 6 points","A 30-day suspension"],"h1":"The fine is under one hundred dollars.","h2":"A first offense under Colorado's hands-free law brings a $75 fine and 2 points on the license, and the penalties grow for repeat offenses.","p":"Right. The first offense is $75 and 2 points."},"es":{"q":"En Colorado, ¿cuál es la sanción por la primera vez que se sostiene el teléfono al manejar?","o":["Solo una advertencia","Una multa de $75 y 2 puntos","Una multa de $500 y 6 puntos","Una suspensión de 30 días"],"h1":"La multa es de menos de cien dólares.","h2":"La primera infracción de la ley de manos libres de Colorado tiene una multa de $75 y 2 puntos en la licencia, y las sanciones aumentan si se repite.","p":"Correcto. La primera vez son $75 y 2 puntos."},"zh":{"q":"在 Colorado，第一次开车时手拿手机，处罚是什么？","o":["只有警告","罚款 $75 并记 2 分","罚款 $500 并记 6 分","暂停驾照 30 天"],"h1":"罚款不到一百美元。","h2":"根据 Colorado 的免持法，第一次违规罚款 $75，驾照记 2 分，再犯处罚会加重。","p":"对。第一次违规是 $75 和 2 分。"},"vi":{"q":"Ở Colorado, hình phạt cho lần vi phạm đầu tiên vì cầm điện thoại khi lái xe là gì?","o":["Chỉ bị cảnh cáo","Phạt $75 và 2 điểm","Phạt $500 và 6 điểm","Bị treo bằng 30 ngày"],"h1":"Tiền phạt dưới một trăm đô la.","h2":"Lần vi phạm đầu tiên theo luật rảnh tay của Colorado bị phạt $75 và 2 điểm vào bằng lái, và hình phạt tăng lên nếu vi phạm lại.","p":"Đúng. Lần đầu bị phạt $75 và 2 điểm."},"tl":{"q":"Sa Colorado, ano ang parusa sa unang paglabag sa paghawak ng telepono habang nagmamaneho?","o":["Babala lamang","$75 na multa at 2 puntos","$500 na multa at 6 na puntos","30 araw na suspensyon"],"h1":"Mas mababa sa isang daang dolyar ang multa.","h2":"Ang unang paglabag sa hands-free na batas ng Colorado ay may $75 na multa at 2 puntos sa lisensya, at lumalaki ang parusa sa mga susunod na paglabag.","p":"Tama. Ang unang paglabag ay $75 at 2 puntos."},"ar":{"q":"في Colorado، ما عقوبة المخالفة الأولى لإمساك الهاتف أثناء القيادة؟","o":["إنذار فقط","غرامة $75 ونقطتان","غرامة $500 و6 نقاط","إيقاف لمدة 30 يومًا"],"h1":"الغرامة أقل من مئة دولار.","h2":"المخالفة الأولى لقانون استعمال الهاتف بدون اليدين في Colorado عقوبتها غرامة $75 ونقطتان على الرخصة، وتزيد العقوبات إذا تكرّرت المخالفة.","p":"صحيح. المخالفة الأولى $75 ونقطتان."},"ref":{"doc":"CO","page":null}},{"id":"co-016","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, a driver under 21 can be charged with underage drinking and driving starting at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Colorado a driver under 21 can be charged with underage drinking and driving at a blood alcohol level of 0.02 percent, far below the adult limit.","p":"Right. Under 21, the limit starts at 0.02."},"es":{"q":"En Colorado, ¿a partir de qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años de manejar después de beber?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Colorado, a un conductor menor de 21 años se le puede acusar de manejar después de beber con un nivel de alcohol de 0.02 por ciento, muy por debajo del límite para adultos.","p":"Correcto. Para menores de 21, el límite empieza en 0.02."},"zh":{"q":"在 Colorado，21 岁以下的司机血液酒精浓度从多少开始，可能被控未成年饮酒驾驶？","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"它是选项里最低的数字。","h2":"在 Colorado，21 岁以下的司机血液酒精浓度达到 0.02%，就可能被控未成年饮酒驾驶，比成年人的限制低很多。","p":"对。21 岁以下，限制从 0.02 开始。"},"vi":{"q":"Ở Colorado, người lái dưới 21 tuổi có thể bị buộc tội uống rượu khi lái xe ở tuổi vị thành niên bắt đầu từ nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.05 phần trăm","0.10 phần trăm","0.02 phần trăm"],"h1":"Đó là con số thấp nhất trong danh sách.","h2":"Ở Colorado, người lái dưới 21 tuổi có thể bị buộc tội uống rượu khi lái xe ở tuổi vị thành niên khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn bắt đầu từ 0.02."},"tl":{"q":"Sa Colorado, ang driver na wala pang 21 ay puwedeng kasuhan ng underage drinking and driving simula sa anong blood alcohol level?","o":["0.08 porsiyento","0.05 porsiyento","0.10 porsiyento","0.02 porsiyento"],"h1":"Ito ang pinakamababang numero sa listahan.","h2":"Sa Colorado, ang driver na wala pang 21 ay puwedeng kasuhan ng underage drinking and driving sa blood alcohol level na 0.02 porsiyento, malayong mas mababa sa limitasyon para sa adult.","p":"Tama. Kapag wala pang 21, nagsisimula ang limitasyon sa 0.02."},"ar":{"q":"في Colorado، يمكن اتّهام السائق الذي عمره أقل من 21 سنة بالشرب والقيادة تحت السن القانونية ابتداءً من أي نسبة كحول في الدم؟","o":["0.08 بالمئة","0.05 بالمئة","0.10 بالمئة","0.02 بالمئة"],"h1":"هي أصغر رقم في القائمة.","h2":"في Colorado يمكن اتّهام السائق الذي عمره أقل من 21 سنة بالشرب والقيادة تحت السن القانونية عند نسبة كحول في الدم 0.02 بالمئة، وهي أقل بكثير من حدّ البالغين.","p":"صحيح. تحت 21 سنة، يبدأ الحدّ من 0.02."},"ref":{"doc":"CO","page":3}},{"id":"co-017","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, driving while ability impaired (DWAI) can be charged at about what blood alcohol level?","o":["0.02 percent","0.05 percent","0.12 percent","0.15 percent"],"h1":"It is lower than the 0.08 DUI level.","h2":"Colorado can charge driving while ability impaired at a blood alcohol level of about 0.05 percent, so you can be in trouble before you reach the 0.08 DUI level.","p":"Right. DWAI starts at about 0.05."},"es":{"q":"En Colorado, ¿con qué nivel aproximado de alcohol en la sangre se puede acusar de manejar con la capacidad disminuida (DWAI)?","o":["0.02 por ciento","0.05 por ciento","0.12 por ciento","0.15 por ciento"],"h1":"Es menor que el nivel de 0.08 de DUI.","h2":"Colorado puede acusar de manejar con la capacidad disminuida con un nivel de alcohol de aproximadamente 0.05 por ciento, así que puede tener problemas antes de llegar al nivel de 0.08 de DUI.","p":"Correcto. El DWAI empieza alrededor de 0.05."},"zh":{"q":"在 Colorado，血液酒精浓度大约多少时，可能被控能力受损驾驶（DWAI）？","o":["0.02%","0.05%","0.12%","0.15%"],"h1":"它比 0.08 的 DUI 标准低。","h2":"Colorado 在血液酒精浓度大约 0.05% 时就可以控告能力受损驾驶，所以你还没到 0.08 的 DUI 标准就可能惹上麻烦。","p":"对。DWAI 大约从 0.05 开始。"},"vi":{"q":"Ở Colorado, tội lái xe khi khả năng bị suy giảm (DWAI) có thể bị buộc ở nồng độ cồn trong máu khoảng bao nhiêu?","o":["0.02 phần trăm","0.05 phần trăm","0.12 phần trăm","0.15 phần trăm"],"h1":"Nó thấp hơn mức DUI 0.08.","h2":"Colorado có thể buộc tội lái xe khi khả năng bị suy giảm ở nồng độ cồn trong máu khoảng 0.05 phần trăm, nên bạn có thể gặp rắc rối trước khi đến mức DUI 0.08.","p":"Đúng. DWAI bắt đầu từ khoảng 0.05."},"tl":{"q":"Sa Colorado, ang driving while ability impaired (DWAI) ay puwedeng ikaso sa mga anong blood alcohol level?","o":["0.02 porsiyento","0.05 porsiyento","0.12 porsiyento","0.15 porsiyento"],"h1":"Mas mababa ito sa 0.08 na antas ng DUI.","h2":"Puwedeng magkaso ang Colorado ng driving while ability impaired sa blood alcohol level na mga 0.05 porsiyento, kaya puwede kang magkaproblema bago ka umabot sa 0.08 na antas ng DUI.","p":"Tama. Nagsisimula ang DWAI sa mga 0.05."},"ar":{"q":"في Colorado، يمكن الاتّهام بالقيادة مع ضعف القدرة (DWAI) عند نسبة كحول في الدم تقارب كم؟","o":["0.02 بالمئة","0.05 بالمئة","0.12 بالمئة","0.15 بالمئة"],"h1":"هي أقل من مستوى DUI وهو 0.08.","h2":"يمكن في Colorado الاتّهام بالقيادة مع ضعف القدرة عند نسبة كحول في الدم تقارب 0.05 بالمئة، فقد تقع في مشكلة قبل أن تصل إلى مستوى DUI وهو 0.08.","p":"صحيح. يبدأ DWAI من حوالي 0.05."},"ref":{"doc":"CO","page":4}},{"id":"co-018","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, at what blood alcohol level is a driver 21 or older automatically considered driving under the influence (DUI)?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Colorado a driver 21 or older is automatically considered DUI at a blood alcohol level of 0.08 percent or higher.","p":"Right. The adult DUI level is 0.08."},"es":{"q":"En Colorado, ¿con qué nivel de alcohol en la sangre se considera automáticamente que un conductor de 21 años o más maneja bajo la influencia (DUI)?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Colorado, se considera automáticamente DUI a un conductor de 21 años o más con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El nivel de DUI para adultos es 0.08."},"zh":{"q":"在 Colorado，21 岁或以上的司机血液酒精浓度达到多少，自动算作酒后驾驶（DUI）？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它是美国最常见的成年人限制。","h2":"在 Colorado，21 岁或以上的司机血液酒精浓度达到 0.08% 或更高，自动算作 DUI。","p":"对。成年人的 DUI 标准是 0.08。"},"vi":{"q":"Ở Colorado, người lái từ 21 tuổi trở lên tự động bị coi là lái xe khi say (DUI) ở nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Đó là giới hạn phổ biến nhất cho người lớn ở Hoa Kỳ.","h2":"Ở Colorado, người lái từ 21 tuổi trở lên tự động bị coi là DUI khi nồng độ cồn trong máu là 0.08 phần trăm trở lên.","p":"Đúng. Mức DUI cho người lớn là 0.08."},"tl":{"q":"Sa Colorado, sa anong blood alcohol level awtomatikong itinuturing na nagmamaneho nang lasing (DUI) ang driver na 21 pataas?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Ito ang pinakakaraniwang limitasyon para sa adult sa United States.","h2":"Sa Colorado, ang driver na 21 pataas ay awtomatikong itinuturing na DUI sa blood alcohol level na 0.08 porsiyento o higit pa.","p":"Tama. Ang antas ng DUI para sa adult ay 0.08."},"ar":{"q":"في Colorado، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره 21 سنة أو أكثر تلقائيًا يقود تحت تأثير الكحول (DUI)؟","o":["0.08 بالمئة","0.02 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هو الحدّ الأكثر شيوعًا للبالغين في الولايات المتحدة.","h2":"في Colorado يُعتبر السائق الذي عمره 21 سنة أو أكثر تلقائيًا DUI عند نسبة كحول في الدم 0.08 بالمئة أو أكثر.","p":"صحيح. مستوى DUI للبالغين هو 0.08."},"ref":{"doc":"CO","page":3}},{"id":"co-019","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, you approach a stopped car on the roadside with its hazard lights flashing. What must you do?","o":["Honk and keep your speed","Stop behind it and wait","Move over one lane if safe; if not, slow down","Slow down only if police are there"],"h1":"The law protects any stopped vehicle that shows hazard lights.","h2":"In Colorado, when you pass a stopped vehicle with flashing hazard lights, you must move over one lane if you safely can; if you cannot, you must slow down to a safe speed.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Colorado, usted se acerca a un carro detenido al lado del camino con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Tocar la bocina y seguir igual","Pararse detrás y esperar","Cambiarse un carril si es seguro; si no, bajar la velocidad","Bajar la velocidad solo si hay policía"],"h1":"La ley protege a cualquier vehículo detenido con luces de emergencia.","h2":"En Colorado, cuando usted pasa un vehículo detenido con las luces de emergencia encendidas, debe cambiarse un carril si puede hacerlo con seguridad; si no puede, debe bajar a una velocidad segura.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Colorado，你接近一辆停在路边、双闪灯在闪的车。你必须怎么做？","o":["按喇叭并保持速度","停在它后面等","如果安全就换开一条车道；做不到就减速","只有警察在场时才减速"],"h1":"这条法律保护任何开着双闪灯停着的车辆。","h2":"在 Colorado，经过一辆双闪灯在闪的停着的车时，如果可以安全换道，你必须换开一条车道；做不到的话，必须减速到安全的速度。","p":"对。换开一条车道，做不到就减速。"},"vi":{"q":"Ở Colorado, bạn đến gần một chiếc xe đang dừng bên đường với đèn cảnh báo nguy hiểm đang nhấp nháy. Bạn phải làm gì?","o":["Bấm còi và giữ nguyên tốc độ","Dừng phía sau nó và chờ","Chuyển sang một làn khác nếu an toàn; nếu không, hãy giảm tốc độ","Chỉ giảm tốc độ nếu có cảnh sát ở đó"],"h1":"Luật bảo vệ bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm.","h2":"Ở Colorado, khi bạn đi qua một xe đang dừng có đèn cảnh báo nguy hiểm nhấp nháy, bạn phải chuyển sang một làn khác nếu làm được một cách an toàn; nếu không thể, bạn phải giảm xuống tốc độ an toàn.","p":"Đúng. Chuyển sang một làn khác, hoặc giảm tốc độ nếu không thể."},"tl":{"q":"Sa Colorado, papalapit ka sa nakahintong sasakyan sa gilid ng daan na kumikislap ang hazard lights. Ano ang dapat mong gawin?","o":["Bumusina at panatilihin ang bilis","Huminto sa likod nito at maghintay","Lumipat ng isang lane kung ligtas; kung hindi, magbagal","Magbagal lamang kung may pulis doon"],"h1":"Pinoprotektahan ng batas ang anumang nakahintong sasakyan na may hazard lights.","h2":"Sa Colorado, kapag dumaraan ka sa nakahintong sasakyan na kumikislap ang hazard lights, dapat kang lumipat ng isang lane kung kaya mo nang ligtas; kung hindi mo kaya, dapat kang magbagal sa ligtas na bilis.","p":"Tama. Lumipat ng isang lane, o magbagal kung hindi mo kaya."},"ar":{"q":"في Colorado، تقترب من سيارة متوقّفة على جانب الطريق وأضواء الخطر فيها تومض. ماذا يجب أن تفعل؟","o":["تستعمل البوق وتحافظ على سرعتك","تتوقّف خلفها وتنتظر","تنتقل مسارًا واحدًا إذا كان ذلك آمنًا؛ وإلا تخفّف السرعة","تخفّف السرعة فقط إذا كانت الشرطة هناك"],"h1":"القانون يحمي أي مركبة متوقّفة تُظهر أضواء الخطر.","h2":"في Colorado، عندما تمرّ بمركبة متوقّفة أضواء الخطر فيها تومض، يجب أن تنتقل مسارًا واحدًا إذا استطعت ذلك بأمان؛ وإذا لم تستطع، يجب أن تخفّف إلى سرعة آمنة.","p":"صحيح. انتقل مسارًا واحدًا، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"CO","page":null}},{"id":"co-020","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, since August 2023, which stopped vehicles does the move-over law protect?","o":["Only police cars","Only tow trucks and ambulances","Only road crew trucks","Any stopped vehicle with hazard lights on"],"h1":"The 2023 change made the rule much wider.","h2":"Since August 2023, Colorado's move-over law covers any stopped vehicle with flashing hazard lights, not only emergency and service vehicles.","p":"Right. It covers any stopped vehicle with hazard lights."},"es":{"q":"En Colorado, desde agosto de 2023, ¿qué vehículos detenidos protege la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo las grúas y ambulancias","Solo los camiones de obras viales","Cualquier vehículo detenido con luces de emergencia"],"h1":"El cambio de 2023 amplió mucho la regla.","h2":"Desde agosto de 2023, la ley de Colorado de cambiarse de carril protege a cualquier vehículo detenido con luces de emergencia, no solo a vehículos de emergencia y de servicio.","p":"Correcto. Protege a cualquier vehículo detenido con luces de emergencia."},"zh":{"q":"在 Colorado，从 2023 年 8 月起，move-over 法保护哪些停着的车辆？","o":["只有警车","只有拖车和救护车","只有道路施工车","任何开着双闪灯停着的车辆"],"h1":"2023 年的修改让这个规定的范围大了很多。","h2":"从 2023 年 8 月起，Colorado 的 move-over 法保护任何开着双闪灯停着的车辆，不只是急救车辆和服务车辆。","p":"对。它保护任何开着双闪灯停着的车辆。"},"vi":{"q":"Ở Colorado, từ tháng 8 năm 2023, luật nhường làn (move-over law) bảo vệ những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe kéo và xe cứu thương","Chỉ xe của đội sửa đường","Bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm"],"h1":"Thay đổi năm 2023 làm cho quy định rộng hơn nhiều.","h2":"Từ tháng 8 năm 2023, luật nhường làn của Colorado áp dụng cho bất kỳ xe nào đang dừng có đèn cảnh báo nguy hiểm nhấp nháy, không chỉ xe cấp cứu và xe dịch vụ.","p":"Đúng. Luật áp dụng cho bất kỳ xe nào đang dừng có bật đèn cảnh báo nguy hiểm."},"tl":{"q":"Sa Colorado, mula Agosto 2023, aling mga nakahintong sasakyan ang pinoprotektahan ng move-over law?","o":["Mga sasakyan ng pulis lamang","Mga tow truck at ambulansya lamang","Mga trak ng road crew lamang","Anumang nakahintong sasakyan na naka-on ang hazard lights"],"h1":"Pinalawak nang husto ng pagbabago noong 2023 ang patakaran.","h2":"Mula Agosto 2023, sakop ng move-over law ng Colorado ang anumang nakahintong sasakyan na kumikislap ang hazard lights, hindi lamang mga emergency at service vehicle.","p":"Tama. Sakop nito ang anumang nakahintong sasakyan na may hazard lights."},"ar":{"q":"في Colorado، منذ أغسطس 2023، أي مركبات متوقّفة يحميها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة فقط","شاحنات السحب وسيارات الإسعاف فقط","شاحنات عمّال الطرق فقط","أي مركبة متوقّفة أضواء الخطر فيها مُشغّلة"],"h1":"تغيير عام 2023 جعل القاعدة أوسع بكثير.","h2":"منذ أغسطس 2023، يشمل قانون الابتعاد في Colorado أي مركبة متوقّفة أضواء الخطر فيها تومض، وليس فقط مركبات الطوارئ والخدمة.","p":"صحيح. يشمل أي مركبة متوقّفة أضواء الخطر فيها مُشغّلة."},"ref":{"doc":"CO","page":null}},{"id":"co-021","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a residence district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a little faster than the business district limit.","h2":"Colorado law sets 30 mph as the lawful speed in a residence district when no other limit is posted.","p":"Right. A residence district is 30 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona residencial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un poco más rápido que el límite de la zona comercial.","h2":"La ley de Colorado fija 30 mph como velocidad legal en una zona residencial cuando no hay otro límite indicado.","p":"Correcto. Una zona residencial es de 30 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，住宅区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它比商业区的限速快一点。","h2":"在没有标示其他限速时，Colorado 法律规定住宅区的合法速度是 30 mph。","p":"对。住宅区是 30 mph。"},"vi":{"q":"Ở Colorado, nếu không có biển báo khác, giới hạn tốc độ trong khu dân cư (residence district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Nó nhanh hơn một chút so với giới hạn trong khu thương mại.","h2":"Luật Colorado quy định 30 mph là tốc độ hợp pháp trong khu dân cư khi không có giới hạn nào khác được ghi trên biển báo.","p":"Đúng. Khu dân cư là 30 mph."},"tl":{"q":"Sa Colorado, kung walang ibang sinasabi ang karatula, ano ang speed limit sa residence district (lugar ng mga tirahan)?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Medyo mas mabilis ito kaysa sa limitasyon sa business district.","h2":"Itinatakda ng batas ng Colorado ang 30 mph bilang legal na bilis sa residence district kapag walang ibang nakapaskil na limitasyon.","p":"Tama. 30 mph sa residence district."},"ar":{"q":"في Colorado، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في المنطقة السكنية (residence district)؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"هو أسرع قليلًا من حدّ المنطقة التجارية.","h2":"قانون Colorado يحدّد 30 mph كسرعة قانونية في المنطقة السكنية عندما لا يكون هناك حدّ آخر مكتوب على لافتة.","p":"صحيح. المنطقة السكنية 30 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-022","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit in a business district?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"It is slower than the residence district limit.","h2":"Colorado law sets 25 mph as the lawful speed in a business district when no other limit is posted, because shops bring many people and cars together.","p":"Right. A business district is 25 mph."},"es":{"q":"En Colorado, si no hay letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Es más lento que el límite de la zona residencial.","h2":"La ley de Colorado fija 25 mph como velocidad legal en una zona comercial cuando no hay otro límite indicado, porque las tiendas reúnen a mucha gente y muchos carros.","p":"Correcto. Una zona comercial es de 25 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，商业区的限速是多少？","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"它比住宅区的限速慢。","h2":"在没有标示其他限速时，Colorado 法律规定商业区的合法速度是 25 mph，因为商店让很多人和车聚在一起。","p":"对。商业区是 25 mph。"},"vi":{"q":"Ở Colorado, nếu không có biển báo khác, giới hạn tốc độ trong khu thương mại (business district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Nó chậm hơn giới hạn trong khu dân cư.","h2":"Luật Colorado quy định 25 mph là tốc độ hợp pháp trong khu thương mại khi không có giới hạn nào khác được ghi trên biển báo, vì cửa hàng thu hút nhiều người và xe cùng một chỗ.","p":"Đúng. Khu thương mại là 25 mph."},"tl":{"q":"Sa Colorado, kung walang ibang sinasabi ang karatula, ano ang speed limit sa business district (lugar ng negosyo)?","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"Mas mabagal ito kaysa sa limitasyon sa residence district.","h2":"Itinatakda ng batas ng Colorado ang 25 mph bilang legal na bilis sa business district kapag walang ibang nakapaskil na limitasyon, dahil maraming tao at sasakyan ang nagtitipon sa mga tindahan.","p":"Tama. 25 mph sa business district."},"ar":{"q":"في Colorado، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في المنطقة التجارية (business district)؟","o":["25 mph","30 mph","35 mph","20 mph"],"h1":"هو أبطأ من حدّ المنطقة السكنية.","h2":"قانون Colorado يحدّد 25 mph كسرعة قانونية في المنطقة التجارية عندما لا يكون هناك حدّ آخر مكتوب على لافتة، لأن المحلات تجمع كثيرًا من الناس والسيارات معًا.","p":"صحيح. المنطقة التجارية 25 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-023","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, what is the lawful speed on a narrow, winding mountain highway or a blind curve, if no sign says otherwise?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"It is the lowest number in Colorado's speed law.","h2":"Colorado law sets 20 mph on narrow, winding mountain highways and blind curves when no other limit is posted, because you cannot see far ahead.","p":"Right. Narrow mountain roads and blind curves are 20 mph."},"es":{"q":"En Colorado, ¿cuál es la velocidad legal en una carretera de montaña estrecha y con curvas, o en una curva ciega, si no hay letrero?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Es el número más bajo de la ley de velocidad de Colorado.","h2":"La ley de Colorado fija 20 mph en carreteras de montaña estrechas y con curvas, y en curvas ciegas, cuando no hay otro límite indicado, porque no se ve lejos.","p":"Correcto. Las carreteras de montaña estrechas y las curvas ciegas son de 20 mph."},"zh":{"q":"在 Colorado，如果没有标志另有规定，在狭窄弯曲的山区公路或看不到前方的弯道上，合法速度是多少？","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"它是 Colorado 速度法里最低的数字。","h2":"在没有标示其他限速时，Colorado 法律规定狭窄弯曲的山区公路和看不到前方的弯道限速 20 mph，因为你看不远。","p":"对。狭窄的山路和看不到前方的弯道是 20 mph。"},"vi":{"q":"Ở Colorado, tốc độ hợp pháp trên đường núi hẹp, quanh co hoặc ở khúc cua khuất tầm nhìn là bao nhiêu, nếu không có biển báo khác?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Đó là con số thấp nhất trong luật tốc độ của Colorado.","h2":"Luật Colorado quy định 20 mph trên đường núi hẹp, quanh co và ở khúc cua khuất tầm nhìn khi không có giới hạn nào khác được ghi trên biển báo, vì bạn không thể nhìn xa phía trước.","p":"Đúng. Đường núi hẹp và khúc cua khuất tầm nhìn là 20 mph."},"tl":{"q":"Sa Colorado, ano ang legal na bilis sa makitid at paliko-likong highway sa bundok o sa blind curve, kung walang ibang sinasabi ang karatula?","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"Ito ang pinakamababang numero sa batas ng bilis ng Colorado.","h2":"Itinatakda ng batas ng Colorado ang 20 mph sa makikitid at paliko-likong highway sa bundok at sa mga blind curve kapag walang ibang nakapaskil na limitasyon, dahil hindi mo matanaw nang malayo ang nasa unahan.","p":"Tama. 20 mph sa makikitid na daan sa bundok at mga blind curve."},"ar":{"q":"في Colorado، ما السرعة القانونية على طريق جبلي ضيّق كثير المنعطفات أو عند منعطف لا ترى ما بعده، إذا لم تقل لافتة غير ذلك؟","o":["40 mph","30 mph","20 mph","55 mph"],"h1":"هو أصغر رقم في قانون السرعة في Colorado.","h2":"قانون Colorado يحدّد 20 mph على الطرق الجبلية الضيّقة الكثيرة المنعطفات وعند المنعطفات التي لا ترى ما بعدها عندما لا يكون هناك حدّ آخر مكتوب على لافتة، لأنك لا تستطيع أن ترى بعيدًا أمامك.","p":"صحيح. الطرق الجبلية الضيّقة والمنعطفات التي لا ترى ما بعدها 20 mph."},"ref":{"doc":"CO","page":11}},{"id":"co-024","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, what is the highest speed limit that may be set on any highway?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Only some rural interstate highways are posted this high.","h2":"Colorado law does not allow any highway speed limit above 75 mph, and only some rural interstate stretches are posted that high.","p":"Right. The highest limit in Colorado is 75 mph."},"es":{"q":"En Colorado, ¿cuál es el límite de velocidad más alto que se puede fijar en una carretera?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Solo algunas autopistas interestatales rurales tienen este límite.","h2":"La ley de Colorado no permite un límite de velocidad mayor de 75 mph en ninguna carretera, y solo algunos tramos rurales de autopista interestatal lo tienen.","p":"Correcto. El límite más alto en Colorado es de 75 mph."},"zh":{"q":"在 Colorado，任何公路最高可以定多少限速？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"只有一些乡村州际公路标示这么高。","h2":"Colorado 法律不允许任何公路的限速高于 75 mph，而且只有一些乡村州际公路路段标示这么高。","p":"对。Colorado 最高限速是 75 mph。"},"vi":{"q":"Ở Colorado, giới hạn tốc độ cao nhất có thể đặt trên bất kỳ xa lộ nào là bao nhiêu?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Chỉ một số xa lộ liên bang ở vùng nông thôn được ghi cao như vậy.","h2":"Luật Colorado không cho phép giới hạn tốc độ trên xa lộ nào cao hơn 75 mph, và chỉ một số đoạn xa lộ liên bang ở nông thôn được ghi cao như vậy.","p":"Đúng. Giới hạn cao nhất ở Colorado là 75 mph."},"tl":{"q":"Sa Colorado, ano ang pinakamataas na speed limit na puwedeng itakda sa anumang highway?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Ilang interstate highway lamang sa probinsya ang may ganito kataas na nakapaskil.","h2":"Hindi pinapayagan ng batas ng Colorado ang anumang speed limit sa highway na higit sa 75 mph, at ilang bahagi lamang ng interstate sa probinsya ang may ganito kataas.","p":"Tama. Ang pinakamataas na limitasyon sa Colorado ay 75 mph."},"ar":{"q":"في Colorado، ما أعلى حدّ سرعة يجوز وضعه على أي طريق سريع؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"بعض الطرق السريعة بين الولايات (interstate) في الأرياف فقط مكتوب عليها هذا الحدّ.","h2":"قانون Colorado لا يسمح بأي حدّ سرعة على الطرق السريعة أعلى من 75 mph، وبعض أجزاء الطرق السريعة بين الولايات في الأرياف فقط مكتوب عليها هذا الحدّ.","p":"صحيح. أعلى حدّ في Colorado هو 75 mph."},"ref":{"doc":"CO","page":12}},{"id":"co-025","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, on a highway with a speed limit of 65 mph or more, when may you drive in the far left lane?","o":["Only to pass or to turn left","Any time traffic is light","Whenever you drive the speed limit","Only at night"],"h1":"This lane has one main job.","h2":"On Colorado highways with a limit of 65 mph or more, the far left lane is for passing or turning left, unless heavy traffic makes it unsafe to move right.","p":"Right. The far left lane is for passing or turning left."},"es":{"q":"En Colorado, en una carretera con límite de 65 mph o más, ¿cuándo puede manejar en el carril del extremo izquierdo?","o":["Solo para rebasar o para girar a la izquierda","Siempre que haya poco tráfico","Siempre que vaya al límite de velocidad","Solo de noche"],"h1":"Este carril tiene una función principal.","h2":"En las carreteras de Colorado con límite de 65 mph o más, el carril del extremo izquierdo es para rebasar o girar a la izquierda, salvo que el tráfico pesado impida pasarse a la derecha con seguridad.","p":"Correcto. El carril del extremo izquierdo es para rebasar o girar a la izquierda."},"zh":{"q":"在 Colorado，在限速 65 mph 或更高的公路上，你什么时候可以在最左边车道开？","o":["只有超车或左转时","车不多的任何时候","只要你按限速开","只在晚上"],"h1":"这条车道有一个主要用途。","h2":"在限速 65 mph 或更高的 Colorado 公路上，最左边车道是用来超车或左转的，除非车太多，往右换道不安全。","p":"对。最左边车道是用来超车或左转的。"},"vi":{"q":"Ở Colorado, trên xa lộ có giới hạn tốc độ từ 65 mph trở lên, khi nào bạn được lái ở làn ngoài cùng bên trái?","o":["Chỉ để vượt hoặc để rẽ trái","Bất kỳ lúc nào đường vắng xe","Bất cứ khi nào bạn lái đúng giới hạn tốc độ","Chỉ vào ban đêm"],"h1":"Làn này có một nhiệm vụ chính.","h2":"Trên xa lộ ở Colorado có giới hạn từ 65 mph trở lên, làn ngoài cùng bên trái dùng để vượt hoặc rẽ trái, trừ khi xe đông khiến việc chuyển sang phải không an toàn.","p":"Đúng. Làn ngoài cùng bên trái dùng để vượt hoặc rẽ trái."},"tl":{"q":"Sa Colorado, sa highway na may speed limit na 65 mph pataas, kailan ka puwedeng magmaneho sa pinakakaliwang lane?","o":["Para lamang mag-overtake o kumaliwa","Anumang oras na kaunti ang trapiko","Tuwing nagmamaneho ka sa speed limit","Sa gabi lamang"],"h1":"May isang pangunahing gamit ang lane na ito.","h2":"Sa mga highway sa Colorado na may limitasyon na 65 mph pataas, ang pinakakaliwang lane ay para sa pag-overtake o pagkaliwa, maliban kung dahil sa mabigat na trapiko ay hindi ligtas lumipat sa kanan.","p":"Tama. Ang pinakakaliwang lane ay para sa pag-overtake o pagkaliwa."},"ar":{"q":"في Colorado، على طريق سريع حدّ السرعة فيه 65 mph أو أكثر، متى يجوز لك أن تقود في المسار الأيسر الأقصى؟","o":["فقط للتجاوز أو للانعطاف يسارًا","في أي وقت تكون فيه حركة المرور خفيفة","كلما قدت بحدّ السرعة","في الليل فقط"],"h1":"لهذا المسار مهمّة رئيسية واحدة.","h2":"على الطرق السريعة في Colorado التي حدّها 65 mph أو أكثر، المسار الأيسر الأقصى للتجاوز أو للانعطاف يسارًا، إلا إذا كانت حركة المرور كثيفة تجعل الانتقال إلى اليمين غير آمن.","p":"صحيح. المسار الأيسر الأقصى للتجاوز أو للانعطاف يسارًا."},"ref":{"doc":"CO","page":null}},{"id":"co-026","scope":"CO","cat":"signals","sign":null,"c":0,"en":{"q":"In Colorado, when may you turn left on a red light after a full stop?","o":["From a one-way street onto another one-way street","From any street onto a two-way street","Only when a police officer waves you on","Never, under any conditions"],"h1":"Both streets must have traffic moving in only one direction.","h2":"Colorado allows a left turn on red after a full stop only from a one-way street onto another one-way street, when no sign forbids it and after yielding.","p":"Right. Left on red is only from one-way onto one-way."},"es":{"q":"En Colorado, ¿cuándo puede girar a la izquierda con luz roja después de parar por completo?","o":["De una calle de un solo sentido a otra de un solo sentido","De cualquier calle a una calle de doble sentido","Solo cuando un policía le indica que pase","Nunca, bajo ninguna condición"],"h1":"Las dos calles deben tener tráfico en una sola dirección.","h2":"Colorado permite girar a la izquierda con luz roja, después de parar por completo, solo de una calle de un solo sentido a otra de un solo sentido, si no hay letrero que lo prohíba y después de ceder el paso.","p":"Correcto. Se gira a la izquierda en rojo solo de un sentido a un sentido."},"zh":{"q":"在 Colorado，什么时候可以在完全停车后红灯左转？","o":["从单行道转进另一条单行道","从任何街道转进双向街道","只有警察挥手让你走时","从来不可以，任何情况都不行"],"h1":"两条街都必须只有一个方向的车。","h2":"Colorado 只允许从单行道转进另一条单行道时，在完全停车、没有标志禁止并让行以后红灯左转。","p":"对。只有从单行道转进单行道才可以红灯左转。"},"vi":{"q":"Ở Colorado, khi nào bạn được rẽ trái khi đèn đỏ sau khi đã dừng hẳn?","o":["Từ đường một chiều vào một đường một chiều khác","Từ bất kỳ đường nào vào đường hai chiều","Chỉ khi cảnh sát vẫy tay cho bạn đi","Không bao giờ, trong mọi trường hợp"],"h1":"Cả hai đường đều phải có xe chạy theo một hướng duy nhất.","h2":"Colorado chỉ cho phép rẽ trái khi đèn đỏ, sau khi đã dừng hẳn, từ đường một chiều vào một đường một chiều khác, khi không có biển báo cấm và sau khi đã nhường đường.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ từ đường một chiều vào đường một chiều."},"tl":{"q":"Sa Colorado, kailan ka puwedeng kumaliwa sa pulang ilaw pagkatapos ng buong paghinto?","o":["Mula sa one-way na kalye papunta sa isa pang one-way na kalye","Mula sa anumang kalye papunta sa two-way na kalye","Kapag kinawayan ka lamang ng pulis","Hindi kailanman, sa anumang kondisyon"],"h1":"Ang dalawang kalye ay dapat may trapikong papunta sa iisang direksyon lamang.","h2":"Pinapayagan ng Colorado ang pagkaliwa sa pulang ilaw pagkatapos ng buong paghinto mula lamang sa one-way na kalye papunta sa isa pang one-way na kalye, kapag walang karatulang nagbabawal at pagkatapos magbigay-daan.","p":"Tama. Ang pagkaliwa sa pula ay mula lamang sa one-way papunta sa one-way."},"ar":{"q":"في Colorado، متى يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء بعد التوقّف الكامل؟","o":["من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","من أي شارع إلى شارع باتجاهين","فقط عندما يشير لك شرطي بالمرور","أبدًا، في أي حال"],"h1":"يجب أن تكون حركة المرور في الشارعين في اتجاه واحد فقط.","h2":"تسمح Colorado بالانعطاف يسارًا عند الإشارة الحمراء بعد التوقّف الكامل فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد، عندما لا توجد لافتة تمنع ذلك وبعد إعطاء الأولوية.","p":"صحيح. الانعطاف يسارًا عند الأحمر فقط من اتجاه واحد إلى اتجاه واحد."},"ref":{"doc":"CO","page":7}},{"id":"co-027","scope":"CO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Colorado, when a school bus has its red lights flashing and stop arm out, how far away must you stop?","o":["At least 5 feet","At least 20 feet","At least 50 feet","At least 100 feet"],"h1":"The distance is about the length of a large car and a half.","h2":"In Colorado you must stop at least 20 feet from a school bus that shows flashing red lights and its stop arm, so children have room to cross.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Colorado, cuando un autobús escolar tiene las luces rojas intermitentes y el brazo de alto extendido, ¿a qué distancia debe parar?","o":["Por lo menos a 5 pies","Por lo menos a 20 pies","Por lo menos a 50 pies","Por lo menos a 100 pies"],"h1":"La distancia es como el largo de un carro grande y medio.","h2":"En Colorado usted debe parar por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y el brazo de alto, para que los niños tengan espacio para cruzar.","p":"Correcto. Pare por lo menos a 20 pies del autobús."},"zh":{"q":"在 Colorado，当校车红灯在闪、伸出停车臂时，你必须在离它多远的地方停车？","o":["至少 5 英尺","至少 20 英尺","至少 50 英尺","至少 100 英尺"],"h1":"这个距离大约是一辆半大车的长度。","h2":"在 Colorado，你必须在离红灯闪烁、伸出停车臂的校车至少 20 英尺的地方停车，这样孩子有空间过马路。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Colorado, khi xe buýt trường học bật đèn đỏ nhấp nháy và giơ cần báo dừng (stop arm), bạn phải dừng cách xe bao xa?","o":["Ít nhất 5 feet","Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng cách này bằng khoảng một chiếc xe hơi lớn rưỡi.","h2":"Ở Colorado, bạn phải dừng cách ít nhất 20 feet khi xe buýt trường học bật đèn đỏ nhấp nháy và giơ cần báo dừng, để trẻ em có chỗ đi qua đường.","p":"Đúng. Dừng cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Colorado, kapag kumikislap ang pulang ilaw ng school bus at nakalabas ang stop arm nito, gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 5 talampakan (feet)","Hindi bababa sa 20 talampakan (feet)","Hindi bababa sa 50 talampakan (feet)","Hindi bababa sa 100 talampakan (feet)"],"h1":"Ang layo ay mga isa't kalahating haba ng malaking kotse.","h2":"Sa Colorado, dapat kang huminto nang hindi bababa sa 20 talampakan mula sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm, para may lugar ang mga bata sa pagtawid.","p":"Tama. Huminto nang hindi bababa sa 20 talampakan mula sa bus."},"ar":{"q":"في Colorado، عندما تكون أضواء الحافلة المدرسية الحمراء تومض وذراع التوقّف (stop arm) ممدودة، على أي مسافة يجب أن تتوقّف؟","o":["5 أقدام على الأقل","20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"المسافة تقارب طول سيارة كبيرة ونصف.","h2":"في Colorado يجب أن تتوقّف على بُعد 20 قدمًا على الأقل من الحافلة المدرسية التي تُظهر أضواء حمراء تومض وذراع التوقّف، ليكون عند الأطفال مكان لعبور الطريق.","p":"صحيح. توقّف على بُعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"CO","page":11}},{"id":"co-028","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, on a two-lane road, you meet a school bus from the opposite direction with red lights flashing. What must you do?","o":["Slow down and pass with care","Honk and continue","Stop until the lights turn off","Stop only if children are visible"],"h1":"On a road this narrow, children may cross into your lane.","h2":"On a Colorado two-lane road, drivers coming from either direction must stop for a school bus with flashing red lights and wait until the lights turn off.","p":"Right. On a two-lane road, both directions stop."},"es":{"q":"En Colorado, en un camino de dos carriles, usted encuentra de frente un autobús escolar con luces rojas intermitentes. ¿Qué debe hacer?","o":["Bajar la velocidad y pasar con cuidado","Tocar la bocina y seguir","Parar hasta que se apaguen las luces","Parar solo si ve niños"],"h1":"En un camino tan angosto, los niños pueden cruzar a su carril.","h2":"En un camino de dos carriles en Colorado, los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. En un camino de dos carriles, paran las dos direcciones."},"zh":{"q":"在 Colorado，在双车道道路上，你遇到一辆从对面方向来、红灯在闪的校车。你必须怎么做？","o":["减速，小心地开过去","按喇叭，继续开","停车，直到灯熄灭","只有看到孩子时才停车"],"h1":"在这么窄的路上，孩子可能会走到你的车道。","h2":"在 Colorado 的双车道道路上，两个方向来的司机都必须为红灯闪烁的校车停车，并等到灯熄灭。","p":"对。在双车道道路上，两个方向都要停车。"},"vi":{"q":"Ở Colorado, trên đường hai làn, bạn gặp một xe buýt trường học đi ngược chiều đang bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và đi qua cẩn thận","Bấm còi và đi tiếp","Dừng lại cho đến khi đèn tắt","Chỉ dừng nếu thấy trẻ em"],"h1":"Trên đường hẹp như vậy, trẻ em có thể đi qua làn của bạn.","h2":"Trên đường hai làn ở Colorado, người lái từ cả hai hướng phải dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy và chờ cho đến khi đèn tắt.","p":"Đúng. Trên đường hai làn, cả hai hướng đều phải dừng."},"tl":{"q":"Sa Colorado, sa daang may dalawang lane, nakasalubong mo ang school bus mula sa kabilang direksyon na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Magbagal at dumaan nang maingat","Bumusina at magpatuloy","Huminto hanggang mamatay ang mga ilaw","Huminto lamang kung may nakikitang bata"],"h1":"Sa ganito kakitid na daan, puwedeng tumawid ang mga bata sa lane mo.","h2":"Sa daang may dalawang lane sa Colorado, ang mga driver mula sa alinmang direksyon ay dapat huminto para sa school bus na kumikislap ang pulang ilaw at maghintay hanggang mamatay ang mga ilaw.","p":"Tama. Sa daang may dalawang lane, humihinto ang dalawang direksyon."},"ar":{"q":"في Colorado، على طريق بمسارين، تقابل حافلة مدرسية آتية من الاتجاه المعاكس وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تخفّف السرعة وتمرّ بحذر","تستعمل البوق وتستمرّ","تتوقّف حتى تنطفئ الأضواء","تتوقّف فقط إذا رأيت أطفالًا"],"h1":"على طريق بهذا الضيق، قد يعبر الأطفال إلى مسارك.","h2":"على طريق بمسارين في Colorado، يجب على السائقين الآتين من أي من الاتجاهين أن يتوقّفوا للحافلة المدرسية التي أضواؤها الحمراء تومض وأن ينتظروا حتى تنطفئ الأضواء.","p":"صحيح. على طريق بمسارين، يتوقّف الاتجاهان."},"ref":{"doc":"CO","page":20}},{"id":"co-029","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 17 or younger?","o":["4 points","6 points","9 points","12 points"],"h1":"Young drivers get far fewer points than adults before trouble starts.","h2":"A Colorado driver age 17 or younger can be suspended with 6 or more points in any 12 months, or 7 or more points at any time before turning 18.","p":"Right. Under 18, 6 points in 12 months can mean suspension."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 17 años o menos?","o":["4 puntos","6 puntos","9 puntos","12 puntos"],"h1":"Los conductores jóvenes acumulan muchos menos puntos que los adultos antes de tener problemas.","h2":"En Colorado, a un conductor de 17 años o menos se le puede suspender con 6 puntos o más en 12 meses, o con 7 puntos o más en cualquier momento antes de cumplir 18.","p":"Correcto. Menores de 18: 6 puntos en 12 meses pueden causar suspensión."},"zh":{"q":"在 Colorado，17 岁或以下的司机在 12 个月内被记多少分，可能被暂停驾照？","o":["4 分","6 分","9 分","12 分"],"h1":"年轻司机比成年人少很多分就会有麻烦。","h2":"Colorado 17 岁或以下的司机，在任何 12 个月内被记 6 分或更多，或在满 18 岁前任何时候被记 7 分或更多，就可能被暂停驾照。","p":"对。18 岁以下，12 个月内 6 分就可能被暂停驾照。"},"vi":{"q":"Ở Colorado, người lái từ 17 tuổi trở xuống bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["4 điểm","6 điểm","9 điểm","12 điểm"],"h1":"Người lái trẻ bị giới hạn ít điểm hơn nhiều so với người lớn trước khi gặp rắc rối.","h2":"Ở Colorado, người lái từ 17 tuổi trở xuống có thể bị treo bằng lái khi có từ 6 điểm trở lên trong 12 tháng bất kỳ, hoặc từ 7 điểm trở lên vào bất kỳ lúc nào trước khi đủ 18 tuổi.","p":"Đúng. Dưới 18 tuổi, 6 điểm trong 12 tháng có thể bị treo bằng lái."},"tl":{"q":"Sa Colorado, ilang puntos sa loob ng 12 buwan ang puwedeng magdulot ng suspensyon para sa driver na 17 taong gulang pababa?","o":["4 na puntos","6 na puntos","9 na puntos","12 puntos"],"h1":"Mas kaunting puntos ang pinapayagan sa mga batang driver kaysa sa mga adult bago magkaproblema.","h2":"Ang driver sa Colorado na 17 taong gulang pababa ay puwedeng masuspinde kapag may 6 o higit pang puntos sa anumang 12 buwan, o 7 o higit pang puntos anumang oras bago mag-18.","p":"Tama. Kapag wala pang 18, ang 6 na puntos sa 12 buwan ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في Colorado، كم نقطة خلال 12 شهرًا يمكن أن تؤدّي إلى إيقاف رخصة السائق الذي عمره 17 سنة أو أقل؟","o":["4 نقاط","6 نقاط","9 نقاط","12 نقطة"],"h1":"السائقون الصغار يُسمح لهم بنقاط أقل بكثير من البالغين قبل أن تبدأ المشكلة.","h2":"يمكن إيقاف رخصة السائق في Colorado الذي عمره 17 سنة أو أقل إذا حصل على 6 نقاط أو أكثر في أي 12 شهرًا، أو 7 نقاط أو أكثر في أي وقت قبل أن يبلغ 18 سنة.","p":"صحيح. تحت 18 سنة، 6 نقاط في 12 شهرًا قد تعني الإيقاف."},"ref":{"doc":"CO","page":null}},{"id":"co-030","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many points within 12 months can lead to suspension for a driver age 18 to 21?","o":["4 points","6 points","9 points","14 points"],"h1":"It is more than the under-18 limit but less than a dozen.","h2":"A Colorado driver age 18 to 21 can be suspended with 9 or more points in any 12 months, 12 in any 24 months, or 14 at any time between 18 and 21.","p":"Right. Ages 18 to 21: 9 points in 12 months."},"es":{"q":"En Colorado, ¿cuántos puntos en 12 meses pueden causar la suspensión de un conductor de 18 a 21 años?","o":["4 puntos","6 puntos","9 puntos","14 puntos"],"h1":"Es más que el límite para menores de 18, pero menos de una docena.","h2":"En Colorado, a un conductor de 18 a 21 años se le puede suspender con 9 puntos o más en 12 meses, 12 en 24 meses, o 14 en cualquier momento entre los 18 y los 21.","p":"Correcto. De 18 a 21 años: 9 puntos en 12 meses."},"zh":{"q":"在 Colorado，18 到 21 岁的司机在 12 个月内被记多少分，可能被暂停驾照？","o":["4 分","6 分","9 分","14 分"],"h1":"它比 18 岁以下的限制多，但比一打少。","h2":"Colorado 18 到 21 岁的司机，在任何 12 个月内被记 9 分或更多、任何 24 个月内 12 分，或在 18 到 21 岁之间任何时候 14 分，就可能被暂停驾照。","p":"对。18 到 21 岁：12 个月内 9 分。"},"vi":{"q":"Ở Colorado, người lái từ 18 đến 21 tuổi bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["4 điểm","6 điểm","9 điểm","14 điểm"],"h1":"Nhiều hơn giới hạn cho người dưới 18 tuổi nhưng ít hơn một tá.","h2":"Ở Colorado, người lái từ 18 đến 21 tuổi có thể bị treo bằng lái khi có từ 9 điểm trở lên trong 12 tháng bất kỳ, 12 điểm trong 24 tháng bất kỳ, hoặc 14 điểm vào bất kỳ lúc nào từ 18 đến 21 tuổi.","p":"Đúng. Từ 18 đến 21 tuổi: 9 điểm trong 12 tháng."},"tl":{"q":"Sa Colorado, ilang puntos sa loob ng 12 buwan ang puwedeng magdulot ng suspensyon para sa driver na 18 hanggang 21 taong gulang?","o":["4 na puntos","6 na puntos","9 na puntos","14 na puntos"],"h1":"Mas marami ito kaysa sa limitasyon para sa wala pang 18 pero mas kaunti sa isang dosena.","h2":"Ang driver sa Colorado na 18 hanggang 21 taong gulang ay puwedeng masuspinde kapag may 9 o higit pang puntos sa anumang 12 buwan, 12 sa anumang 24 na buwan, o 14 anumang oras mula 18 hanggang 21.","p":"Tama. Edad 18 hanggang 21: 9 na puntos sa 12 buwan."},"ar":{"q":"في Colorado، كم نقطة خلال 12 شهرًا يمكن أن تؤدّي إلى إيقاف رخصة السائق الذي عمره من 18 إلى 21 سنة؟","o":["4 نقاط","6 نقاط","9 نقاط","14 نقطة"],"h1":"هي أكثر من حدّ من هم تحت 18 سنة لكن أقل من دزينة.","h2":"يمكن إيقاف رخصة السائق في Colorado الذي عمره من 18 إلى 21 سنة إذا حصل على 9 نقاط أو أكثر في أي 12 شهرًا، أو 12 في أي 24 شهرًا، أو 14 في أي وقت بين 18 و21 سنة.","p":"صحيح. من 18 إلى 21 سنة: 9 نقاط في 12 شهرًا."},"ref":{"doc":"CO","page":null}},{"id":"co-031","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"The property damage part is $15,000.","h2":"Colorado requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $15,000 for property damage.","p":"Right. Colorado's minimum is 25/50/15."},"es":{"q":"En Colorado, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"La parte de daños a la propiedad es de $15,000.","h2":"Colorado exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $15,000 por daños a la propiedad.","p":"Correcto. El mínimo en Colorado es 25/50/15."},"zh":{"q":"在 Colorado，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"财产损失的部分是 $15,000。","h2":"Colorado 要求一个人受伤至少 $25,000，一次车祸的人身伤害至少 $50,000，财产损失至少 $15,000。","p":"对。Colorado 的最低标准是 25/50/15。"},"vi":{"q":"Ở Colorado, mức bảo hiểm trách nhiệm (liability insurance) tối thiểu người lái phải có là bao nhiêu?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"Phần thiệt hại tài sản là $15,000.","h2":"Colorado yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $15,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Colorado là 25/50/15."},"tl":{"q":"Sa Colorado, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"Ang bahagi para sa pinsala sa ari-arian ay $15,000.","h2":"Hinihingi ng Colorado ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang aksidente, at $15,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Colorado ay 25/50/15."},"ar":{"q":"في Colorado، ما الحدّ الأدنى لتأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$25,000 / $50,000 / $15,000","$10,000 / $20,000 / $10,000","$50,000 / $100,000 / $25,000","$30,000 / $60,000 / $25,000"],"h1":"جزء الأضرار بالممتلكات هو $15,000.","h2":"تطلب Colorado على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$15,000 للأضرار بالممتلكات.","p":"صحيح. الحدّ الأدنى في Colorado هو 25/50/15."},"ref":{"doc":"CO","page":null}},{"id":"co-032","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when the passenger vehicle chain law is active, which vehicles need chains or another approved traction device?","o":["Only two-wheel-drive cars","Only trucks over 16,000 pounds","Only cars with worn tires","All vehicles, including four-wheel drive"],"h1":"It is the last step before a highway closes.","h2":"When Colorado's passenger vehicle chain law is active, every vehicle needs chains or an approved alternative traction device, even all-wheel and four-wheel drive.","p":"Right. Under the chain law, all vehicles need chains or a traction device."},"es":{"q":"En Colorado, cuando está activa la ley de cadenas para vehículos de pasajeros, ¿qué vehículos necesitan cadenas u otro dispositivo de tracción aprobado?","o":["Solo los carros de tracción en dos ruedas","Solo los camiones de más de 16,000 libras","Solo los carros con llantas gastadas","Todos los vehículos, incluso los de doble tracción"],"h1":"Es el último paso antes de cerrar una carretera.","h2":"Cuando está activa la ley de cadenas en Colorado, todo vehículo necesita cadenas o un dispositivo de tracción aprobado, incluso los de tracción total o doble tracción.","p":"Correcto. Con la ley de cadenas, todos los vehículos necesitan cadenas o tracción."},"zh":{"q":"在 Colorado，客车防滑链法（chain law）生效时，哪些车辆需要防滑链或其他认可的防滑装置？","o":["只有两轮驱动的车","只有超过 16,000 磅的卡车","只有轮胎磨损的车","所有车辆，包括四轮驱动"],"h1":"它是公路封闭前的最后一步。","h2":"Colorado 的客车防滑链法生效时，每一辆车都需要防滑链或认可的其他防滑装置，即使是全轮驱动和四轮驱动也一样。","p":"对。防滑链法生效时，所有车辆都需要防滑链或防滑装置。"},"vi":{"q":"Ở Colorado, khi luật xích bánh xe cho xe chở khách (passenger vehicle chain law) có hiệu lực, những xe nào cần xích hoặc thiết bị bám đường khác được chấp thuận?","o":["Chỉ xe dẫn động hai bánh","Chỉ xe tải nặng hơn 16,000 pound","Chỉ xe có lốp mòn","Tất cả các xe, kể cả xe dẫn động bốn bánh"],"h1":"Đó là bước cuối cùng trước khi xa lộ bị đóng.","h2":"Khi luật xích bánh xe cho xe chở khách của Colorado có hiệu lực, mọi xe đều cần xích hoặc thiết bị bám đường thay thế được chấp thuận, kể cả xe dẫn động mọi bánh và bốn bánh.","p":"Đúng. Theo luật xích bánh xe, mọi xe đều cần xích hoặc thiết bị bám đường."},"tl":{"q":"Sa Colorado, kapag aktibo ang passenger vehicle chain law, aling mga sasakyan ang kailangan ng kadena o ibang aprubadong traction device?","o":["Mga kotseng two-wheel drive lamang","Mga trak na higit sa 16,000 libra lamang","Mga kotseng may pudpod na gulong lamang","Lahat ng sasakyan, kasama ang four-wheel drive"],"h1":"Ito ang huling hakbang bago isara ang highway.","h2":"Kapag aktibo ang passenger vehicle chain law ng Colorado, bawat sasakyan ay kailangan ng kadena o aprubadong alternatibong traction device, kahit all-wheel at four-wheel drive.","p":"Tama. Sa ilalim ng chain law, lahat ng sasakyan ay kailangan ng kadena o traction device."},"ar":{"q":"في Colorado، عندما يكون قانون السلاسل لمركبات الركّاب (passenger vehicle chain law) مُفعّلًا، أي مركبات تحتاج إلى سلاسل أو جهاز تماسك آخر معتمد؟","o":["السيارات ذات الدفع الثنائي فقط","الشاحنات التي وزنها أكثر من 16,000 رطل فقط","السيارات ذات الإطارات البالية فقط","كل المركبات، ومنها ذات الدفع الرباعي"],"h1":"هي الخطوة الأخيرة قبل إغلاق الطريق السريع.","h2":"عندما يكون قانون السلاسل لمركبات الركّاب في Colorado مُفعّلًا، تحتاج كل مركبة إلى سلاسل أو جهاز تماسك بديل معتمد، حتى المركبات ذات الدفع الكلّي والدفع الرباعي.","p":"صحيح. بموجب قانون السلاسل، كل المركبات تحتاج إلى سلاسل أو جهاز تماسك."},"ref":{"doc":"CO","page":null}},{"id":"co-033","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, during which months must passenger vehicles on I-70 between Dotsero and Morrison be ready to follow the traction law?","o":["December 1 to February 28","November 1 to March 31","September 1 to May 31","All year round"],"h1":"The season covers most of the school year.","h2":"From September 1 to May 31, passenger vehicles on I-70 between Dotsero and Morrison must be ready to meet the traction law whenever the signs turn on.","p":"Right. The I-70 traction season is September 1 to May 31."},"es":{"q":"En Colorado, ¿en qué meses deben estar listos los vehículos de pasajeros en la I-70, entre Dotsero y Morrison, para cumplir la ley de tracción?","o":["Del 1 de diciembre al 28 de febrero","Del 1 de noviembre al 31 de marzo","Del 1 de septiembre al 31 de mayo","Todo el año"],"h1":"La temporada abarca casi todo el año escolar.","h2":"Del 1 de septiembre al 31 de mayo, los vehículos de pasajeros en la I-70 entre Dotsero y Morrison deben estar listos para cumplir la ley de tracción cuando se enciendan los letreros.","p":"Correcto. La temporada de tracción en la I-70 es del 1 de septiembre al 31 de mayo."},"zh":{"q":"在 Colorado，在哪几个月，Dotsero 和 Morrison 之间 I-70 上的客车必须准备好遵守牵引力法（traction law）？","o":["十二月 1 日到二月 28 日","十一月 1 日到三月 31 日","九月 1 日到五月 31 日","全年"],"h1":"这个季节包括学年的大部分时间。","h2":"从九月 1 日到五月 31 日，Dotsero 和 Morrison 之间 I-70 上的客车必须准备好，只要标志一亮就能符合牵引力法。","p":"对。I-70 的牵引力季节是九月 1 日到五月 31 日。"},"vi":{"q":"Ở Colorado, trong những tháng nào xe chở khách trên I-70 giữa Dotsero và Morrison phải sẵn sàng tuân theo luật bám đường (traction law)?","o":["Từ 1 tháng 12 đến 28 tháng 2","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 9 đến 31 tháng 5","Quanh năm"],"h1":"Mùa này gồm phần lớn năm học.","h2":"Từ ngày 1 tháng 9 đến ngày 31 tháng 5, xe chở khách trên I-70 giữa Dotsero và Morrison phải sẵn sàng đáp ứng luật bám đường mỗi khi biển báo được bật.","p":"Đúng. Mùa luật bám đường trên I-70 là từ 1 tháng 9 đến 31 tháng 5."},"tl":{"q":"Sa Colorado, sa anong mga buwan dapat handang sumunod sa traction law ang mga pampasaherong sasakyan sa I-70 sa pagitan ng Dotsero at Morrison?","o":["Disyembre 1 hanggang Pebrero 28","Nobyembre 1 hanggang Marso 31","Setyembre 1 hanggang Mayo 31","Buong taon"],"h1":"Sakop ng panahong ito ang malaking bahagi ng school year.","h2":"Mula Setyembre 1 hanggang Mayo 31, ang mga pampasaherong sasakyan sa I-70 sa pagitan ng Dotsero at Morrison ay dapat handang sumunod sa traction law tuwing bubukas ang mga karatula.","p":"Tama. Ang traction season sa I-70 ay Setyembre 1 hanggang Mayo 31."},"ar":{"q":"في Colorado، في أي أشهر يجب أن تكون مركبات الركّاب على I-70 بين Dotsero وMorrison مستعدّة لاتّباع قانون التماسك (traction law)؟","o":["من 1 ديسمبر إلى 28 فبراير","من 1 نوفمبر إلى 31 مارس","من 1 سبتمبر إلى 31 مايو","طوال السنة"],"h1":"هذا الموسم يشمل معظم السنة الدراسية.","h2":"من 1 سبتمبر إلى 31 مايو، يجب أن تكون مركبات الركّاب على I-70 بين Dotsero وMorrison مستعدّة لتلبية قانون التماسك كلما أُضيئت اللافتات.","p":"صحيح. موسم قانون التماسك على I-70 من 1 سبتمبر إلى 31 مايو."},"ref":{"doc":"CO","page":null}},{"id":"co-034","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, when a driver under 18 is driving, who must wear a seat belt?","o":["Only the driver","Only front-seat riders","Only passengers under 18","The driver and every passenger"],"h1":"Age of the passenger does not matter here.","h2":"When a Colorado driver is under 18, the driver and every passenger, of any age, must wear a seat belt or ride in the right child seat.","p":"Right. The teen driver and every passenger must buckle up."},"es":{"q":"En Colorado, cuando maneja un conductor menor de 18 años, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo los que van adelante","Solo los pasajeros menores de 18","El conductor y todos los pasajeros"],"h1":"Aquí no importa la edad del pasajero.","h2":"Cuando un conductor en Colorado es menor de 18 años, el conductor y todos los pasajeros, de cualquier edad, deben usar el cinturón de seguridad o ir en el asiento infantil adecuado.","p":"Correcto. El conductor joven y todos los pasajeros deben abrocharse."},"zh":{"q":"在 Colorado，18 岁以下的司机开车时，谁必须系安全带？","o":["只有司机","只有坐前排的人","只有 18 岁以下的乘客","司机和每一位乘客"],"h1":"这里乘客的年龄没有关系。","h2":"当 Colorado 的司机未满 18 岁时，司机和每一位任何年龄的乘客都必须系安全带，或坐在合适的儿童座椅里。","p":"对。青少年司机和每一位乘客都必须系好安全带。"},"vi":{"q":"Ở Colorado, khi người lái dưới 18 tuổi đang lái xe, ai phải thắt dây an toàn?","o":["Chỉ người lái","Chỉ người ngồi ghế trước","Chỉ hành khách dưới 18 tuổi","Người lái và mọi hành khách"],"h1":"Tuổi của hành khách không quan trọng ở đây.","h2":"Khi người lái ở Colorado dưới 18 tuổi, người lái và mọi hành khách, ở bất kỳ tuổi nào, phải thắt dây an toàn hoặc ngồi đúng ghế an toàn cho trẻ em.","p":"Đúng. Người lái tuổi teen và mọi hành khách đều phải thắt dây an toàn."},"tl":{"q":"Sa Colorado, kapag nagmamaneho ang driver na wala pang 18, sino ang dapat naka-seat belt?","o":["Ang driver lamang","Ang mga nakaupo sa harap lamang","Ang mga pasahero na wala pang 18 lamang","Ang driver at bawat pasahero"],"h1":"Hindi mahalaga dito ang edad ng pasahero.","h2":"Kapag wala pang 18 ang driver sa Colorado, ang driver at bawat pasahero, anuman ang edad, ay dapat naka-seat belt o nakaupo sa tamang child seat.","p":"Tama. Ang tinedyer na driver at bawat pasahero ay dapat mag-seat belt."},"ar":{"q":"في Colorado، عندما يقود سائق عمره أقل من 18 سنة، من يجب أن يضع حزام الأمان؟","o":["السائق فقط","من يجلسون في الأمام فقط","الركّاب الذين عمرهم أقل من 18 سنة فقط","السائق وكل راكب"],"h1":"عمر الراكب لا يهمّ هنا.","h2":"عندما يكون السائق في Colorado عمره أقل من 18 سنة، يجب على السائق وكل راكب، من أي عمر، أن يضع حزام الأمان أو يجلس في مقعد الطفل المناسب.","p":"صحيح. السائق المراهق وكل راكب يجب أن يضعوا حزام الأمان."},"ref":{"doc":"CO","page":3}},{"id":"co-035","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, in which languages does the DMV offer the driving knowledge test?","o":["English only","English, Spanish and French","English and Spanish","Any language you choose"],"h1":"The online test uses the same two languages as the office test.","h2":"The Colorado DMV offers the driving knowledge test in English and Spanish, both in the office and online.","p":"Right. The test is offered in English and Spanish."},"es":{"q":"En Colorado, ¿en qué idiomas ofrece el DMV el examen de conocimientos de manejo?","o":["Solo en inglés","En inglés, español y francés","En inglés y español","En el idioma que usted elija"],"h1":"El examen en línea usa los mismos dos idiomas que el examen en la oficina.","h2":"El DMV de Colorado ofrece el examen de conocimientos de manejo en inglés y en español, tanto en la oficina como en línea.","p":"Correcto. El examen se ofrece en inglés y en español."},"zh":{"q":"在 Colorado，DMV 用哪些语言进行驾驶知识考试？","o":["只有英语","英语、西班牙语和法语","英语和西班牙语","你选择的任何语言"],"h1":"网上考试和办公室考试用的是同样的两种语言。","h2":"Colorado DMV 的驾驶知识考试用英语和西班牙语，在办公室考和在网上考都一样。","p":"对。考试用英语和西班牙语。"},"vi":{"q":"Ở Colorado, DMV cho thi kiến thức lái xe bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh, tiếng Tây Ban Nha và tiếng Pháp","Tiếng Anh và tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Bài thi trực tuyến dùng cùng hai ngôn ngữ như bài thi tại văn phòng.","h2":"Colorado DMV cho thi kiến thức lái xe bằng tiếng Anh và tiếng Tây Ban Nha, cả tại văn phòng và trực tuyến.","p":"Đúng. Bài thi có bằng tiếng Anh và tiếng Tây Ban Nha."},"tl":{"q":"Sa Colorado, sa anong mga wika inaalok ng DMV ang driving knowledge test?","o":["Ingles lang","Ingles, Espanyol at Pranses","Ingles at Espanyol","Kahit anong wika na piliin mo"],"h1":"Ang online test ay gumagamit ng parehong dalawang wika gaya ng test sa opisina.","h2":"Inaalok ng Colorado DMV ang driving knowledge test sa Ingles at Espanyol, sa opisina man o online.","p":"Tama. Inaalok ang test sa Ingles at Espanyol."},"ar":{"q":"في Colorado، بأي لغات يقدّم DMV اختبار المعرفة للقيادة؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية والفرنسية","الإنجليزية والإسبانية","أي لغة تختارها"],"h1":"يستخدم الاختبار عبر الإنترنت نفس اللغتين المستخدمتين في اختبار المكتب.","h2":"يقدّم Colorado DMV اختبار المعرفة للقيادة بالإنجليزية والإسبانية، في المكتب وعبر الإنترنت.","p":"صحيح. الاختبار متاح بالإنجليزية والإسبانية."},"ref":{"doc":"CO","page":null}},{"id":"co-036","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, what happens to your license if you refuse a chemical test when an officer suspects impaired driving?","o":["You get a warning the first time","It is suspended for 30 days","It is revoked for one year","Nothing, if you pass a field test"],"h1":"Colorado's express consent law treats refusal very seriously.","h2":"In Colorado, if you refuse a chemical test of your blood, breath, saliva or urine, your license is revoked for one year, and you must also use an ignition interlock for two years.","p":"Right. Refusing the test means a one-year revocation."},"es":{"q":"En Colorado, ¿qué pasa con su licencia si usted se niega a una prueba química cuando un agente sospecha que maneja bajo los efectos?","o":["Recibe una advertencia la primera vez","Se suspende por 30 días","Se revoca por un año","Nada, si pasa una prueba de campo"],"h1":"La ley de consentimiento expreso de Colorado trata la negativa con mucha seriedad.","h2":"En Colorado, si usted se niega a una prueba química de sangre, aliento, saliva u orina, su licencia se revoca por un año y además debe usar un dispositivo de bloqueo de encendido por dos años.","p":"Correcto. Negarse a la prueba significa un año de revocación."},"zh":{"q":"在 Colorado，如果警察怀疑你在受影响的状态下驾驶，而你拒绝化学检测，你的驾照会怎样？","o":["第一次只会收到警告","被暂停 30 天","被吊销一年","如果你通过了现场测试，就没事"],"h1":"Colorado 的默示同意法（express consent law）对拒绝检测处理得非常严格。","h2":"在 Colorado，如果你拒绝血液、呼气、唾液或尿液的化学检测，你的驾照会被吊销一年，而且你还必须使用点火联锁装置（ignition interlock）两年。","p":"对。拒绝检测就是吊销驾照一年。"},"vi":{"q":"Ở Colorado, nếu bạn từ chối xét nghiệm hóa học khi cảnh sát nghi bạn lái xe trong tình trạng bị ảnh hưởng, bằng lái của bạn sẽ ra sao?","o":["Lần đầu bạn chỉ bị cảnh cáo","Bị treo 30 ngày","Bị thu hồi một năm","Không sao, nếu bạn qua được bài kiểm tra tại chỗ"],"h1":"Luật đồng ý mặc nhiên (express consent law) của Colorado xử lý việc từ chối rất nghiêm khắc.","h2":"Ở Colorado, nếu bạn từ chối xét nghiệm hóa học máu, hơi thở, nước bọt hoặc nước tiểu, bằng lái của bạn bị thu hồi một năm, và bạn còn phải dùng thiết bị khóa khởi động (ignition interlock) trong hai năm.","p":"Đúng. Từ chối xét nghiệm nghĩa là bị thu hồi bằng lái một năm."},"tl":{"q":"Sa Colorado, ano ang mangyayari sa lisensya mo kung tumanggi ka sa chemical test kapag hinihinala ng pulis na nagmamaneho ka nang impaired?","o":["Babalaan ka lang sa unang beses","Masususpinde ito nang 30 araw","Babawiin ito nang isang taon","Wala, kung pumasa ka sa field test"],"h1":"Napakaseryoso ng pagtingin ng express consent law ng Colorado sa pagtanggi.","h2":"Sa Colorado, kung tumanggi ka sa chemical test ng dugo, hininga, laway o ihi, babawiin ang lisensya mo nang isang taon, at kailangan mo ring gumamit ng ignition interlock nang dalawang taon.","p":"Tama. Ang pagtanggi sa test ay nangangahulugang babawiin ang lisensya nang isang taon."},"ar":{"q":"في Colorado، ماذا يحدث لرخصتك إذا رفضت الفحص الكيميائي عندما يشكّ الشرطي أنك تقود تحت التأثير؟","o":["تحصل على تحذير في المرة الأولى","تُوقَف لمدة 30 يومًا","تُلغى لمدة سنة واحدة","لا شيء، إذا نجحت في الاختبار الميداني"],"h1":"قانون الموافقة الضمنية (express consent law) في Colorado يتعامل مع الرفض بجدّية كبيرة.","h2":"في Colorado، إذا رفضت الفحص الكيميائي للدم أو النَّفَس أو اللعاب أو البول، تُلغى رخصتك لمدة سنة واحدة، ويجب عليك أيضًا استخدام جهاز قفل الإشعال (ignition interlock) لمدة سنتين.","p":"صحيح. رفض الفحص يعني إلغاء الرخصة لمدة سنة واحدة."},"ref":{"doc":"CO","page":5}},{"id":"co-037","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many points go on your record for a first conviction of driving while ability impaired (DWAI)?","o":["8 points","2 points","4 points","12 points"],"h1":"It is a large number, close to a full suspension for some drivers.","h2":"In Colorado, a first conviction for driving while ability impaired adds 8 points to your driving record.","p":"Right. A first DWAI brings 8 points."},"es":{"q":"En Colorado, ¿cuántos puntos se agregan a su historial por una primera condena por manejar con la capacidad disminuida (DWAI)?","o":["8 puntos","2 puntos","4 puntos","12 puntos"],"h1":"Es un número alto, cerca de una suspensión para algunos conductores.","h2":"En Colorado, una primera condena por manejar con la capacidad disminuida agrega 8 puntos a su historial de manejo.","p":"Correcto. Un primer DWAI suma 8 puntos."},"zh":{"q":"在 Colorado，第一次被判能力受损驾驶（DWAI），你的记录上会被记几分？","o":["8 分","2 分","4 分","12 分"],"h1":"这是一个很大的数字，对有些司机来说已经接近被暂停驾照。","h2":"在 Colorado，第一次被判能力受损驾驶，会在你的驾驶记录上记 8 分。","p":"对。第一次 DWAI 记 8 分。"},"vi":{"q":"Ở Colorado, lần đầu bị kết tội lái xe khi khả năng bị suy giảm (DWAI), hồ sơ của bạn bị ghi bao nhiêu điểm?","o":["8 điểm","2 điểm","4 điểm","12 điểm"],"h1":"Đó là một con số lớn, với một số người lái thì gần đến mức bị treo bằng lái.","h2":"Ở Colorado, lần đầu bị kết tội lái xe khi khả năng bị suy giảm sẽ bị ghi 8 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Lần DWAI đầu tiên bị ghi 8 điểm."},"tl":{"q":"Sa Colorado, ilang puntos ang ilalagay sa record mo sa unang conviction para sa driving while ability impaired (DWAI)?","o":["8 na puntos","2 puntos","4 na puntos","12 puntos"],"h1":"Malaking numero ito, malapit na sa suspensyon para sa ilang driver.","h2":"Sa Colorado, ang unang conviction para sa driving while ability impaired ay nagdadagdag ng 8 puntos sa driving record mo.","p":"Tama. Ang unang DWAI ay may 8 puntos."},"ar":{"q":"في Colorado، كم نقطة تُضاف إلى سجلّك عند أول إدانة بالقيادة مع ضعف القدرة (DWAI)؟","o":["8 نقاط","نقطتان (2)","4 نقاط","12 نقطة"],"h1":"هو رقم كبير، قريب من إيقاف الرخصة عند بعض السائقين.","h2":"في Colorado، أول إدانة بالقيادة مع ضعف القدرة تضيف 8 نقاط إلى سجلّ قيادتك.","p":"صحيح. أول إدانة DWAI تضيف 8 نقاط."},"ref":{"doc":"CO","page":4}},{"id":"co-038","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, at what level of THC (from marijuana) in the blood may a court infer that a driver was under the influence?","o":["Any amount at all","1 nanogram per milliliter","10 nanograms per milliliter","5 nanograms per milliliter"],"h1":"The number is measured in nanograms per milliliter of blood.","h2":"In Colorado, a blood level of 5 nanograms of THC per milliliter allows a court to infer that the driver was driving under the influence.","p":"Right. The THC inference level is 5 nanograms per milliliter."},"es":{"q":"En Colorado, ¿con qué nivel de THC (de la marihuana) en la sangre puede un tribunal suponer que el conductor manejaba bajo los efectos?","o":["Cualquier cantidad","1 nanogramo por mililitro","10 nanogramos por mililitro","5 nanogramos por mililitro"],"h1":"El número se mide en nanogramos por mililitro de sangre.","h2":"En Colorado, un nivel de 5 nanogramos de THC por mililitro de sangre permite a un tribunal suponer que el conductor manejaba bajo los efectos.","p":"Correcto. El nivel para el THC es de 5 nanogramos por mililitro."},"zh":{"q":"在 Colorado，血液中的 THC（来自大麻）达到什么水平时，法院可以推定司机是在受影响的状态下驾驶？","o":["任何含量都算","每毫升 1 纳克","每毫升 10 纳克","每毫升 5 纳克"],"h1":"这个数字用每毫升血液中有多少纳克来计算。","h2":"在 Colorado，血液中 THC 达到每毫升 5 纳克时，法院可以推定司机是在受影响的状态下驾驶。","p":"对。THC 的推定标准是每毫升 5 纳克。"},"vi":{"q":"Ở Colorado, nồng độ THC (từ cần sa) trong máu ở mức nào thì tòa án có thể suy ra người lái đã lái xe trong tình trạng bị ảnh hưởng?","o":["Bất kỳ lượng nào","1 nanogram mỗi mililít","10 nanogram mỗi mililít","5 nanogram mỗi mililít"],"h1":"Con số này được đo bằng nanogram trong mỗi mililít máu.","h2":"Ở Colorado, mức THC 5 nanogram mỗi mililít máu cho phép tòa án suy ra rằng người lái đã lái xe trong tình trạng bị ảnh hưởng.","p":"Đúng. Mức suy ra cho THC là 5 nanogram mỗi mililít."},"tl":{"q":"Sa Colorado, sa anong level ng THC (mula sa marijuana) sa dugo puwedeng ipalagay ng korte na nagmamaneho ang driver nang under the influence?","o":["Kahit anong dami","1 nanogram bawat milliliter","10 nanogram bawat milliliter","5 nanogram bawat milliliter"],"h1":"Sinusukat ang numero sa nanogram bawat milliliter ng dugo.","h2":"Sa Colorado, ang 5 nanogram ng THC bawat milliliter ng dugo ay nagpapahintulot sa korte na ipalagay na nagmamaneho ang driver nang under the influence.","p":"Tama. Ang level para sa THC ay 5 nanogram bawat milliliter."},"ar":{"q":"في Colorado، عند أي مستوى من THC (من الماريجوانا) في الدم يمكن للمحكمة أن تستنتج أن السائق كان يقود تحت التأثير؟","o":["أي كمية مهما كانت","1 نانوغرام لكل مليلتر","10 نانوغرامات لكل مليلتر","5 نانوغرامات لكل مليلتر"],"h1":"يُقاس الرقم بالنانوغرام لكل مليلتر من الدم.","h2":"في Colorado، مستوى 5 نانوغرامات من THC لكل مليلتر من الدم يسمح للمحكمة أن تستنتج أن السائق كان يقود تحت التأثير.","p":"صحيح. مستوى THC للاستنتاج هو 5 نانوغرامات لكل مليلتر."},"ref":{"doc":"CO","page":5}},{"id":"co-039","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, which open containers are not allowed in the passenger area of a vehicle on a public road?","o":["Only open bottles of liquor","Open containers of alcohol or marijuana","Only open beer cans","Open containers only if the driver drank"],"h1":"The rule covers more than one substance.","h2":"In Colorado, it is against the law to have an open container of alcohol or an open container of marijuana in the passenger area of a vehicle on a public road.","p":"Right. No open alcohol or marijuana in the passenger area."},"es":{"q":"En Colorado, ¿qué envases abiertos no se permiten en el área de pasajeros de un vehículo en una vía pública?","o":["Solo botellas de licor abiertas","Envases abiertos de alcohol o de marihuana","Solo latas de cerveza abiertas","Solo si el conductor bebió"],"h1":"La regla cubre más de una sustancia.","h2":"En Colorado, es ilegal tener un envase abierto de alcohol o de marihuana en el área de pasajeros de un vehículo en una vía pública.","p":"Correcto. Nada de alcohol ni marihuana abiertos en el área de pasajeros."},"zh":{"q":"在 Colorado，在公共道路上，车辆的乘客区不允许有哪些打开的容器？","o":["只有打开的烈酒瓶","打开的酒类或大麻容器","只有打开的啤酒罐","只有司机喝过酒时才算"],"h1":"这个规定不只包括一种东西。","h2":"在 Colorado，在公共道路上，车辆的乘客区有打开的酒类容器或打开的大麻容器都是违法的。","p":"对。乘客区不能有打开的酒类或大麻。"},"vi":{"q":"Ở Colorado, những đồ chứa đã mở nào không được để trong khu vực hành khách của xe trên đường công cộng?","o":["Chỉ chai rượu mạnh đã mở","Đồ chứa rượu bia hoặc cần sa đã mở","Chỉ lon bia đã mở","Chỉ khi người lái đã uống"],"h1":"Quy định này bao gồm nhiều hơn một chất.","h2":"Ở Colorado, để đồ chứa rượu bia đã mở hoặc đồ chứa cần sa đã mở trong khu vực hành khách của xe trên đường công cộng là phạm luật.","p":"Đúng. Không có rượu bia hay cần sa đã mở trong khu vực hành khách."},"tl":{"q":"Sa Colorado, aling mga bukas na lalagyan ang hindi pinapayagan sa lugar ng pasahero ng sasakyan sa pampublikong kalsada?","o":["Mga bukas na bote ng alak lamang","Mga bukas na lalagyan ng alak o marijuana","Mga bukas na lata ng beer lamang","Mga bukas na lalagyan kung uminom lang ang driver"],"h1":"Higit sa isang bagay ang sakop ng patakaran.","h2":"Sa Colorado, labag sa batas ang magkaroon ng bukas na lalagyan ng alak o bukas na lalagyan ng marijuana sa lugar ng pasahero ng sasakyan sa pampublikong kalsada.","p":"Tama. Walang bukas na alak o marijuana sa lugar ng pasahero."},"ar":{"q":"في Colorado، ما الأوعية المفتوحة غير المسموح بها في منطقة الركّاب في المركبة على طريق عام؟","o":["زجاجات الخمور المفتوحة فقط","الأوعية المفتوحة للكحول أو الماريجوانا","علب البيرة المفتوحة فقط","الأوعية المفتوحة فقط إذا شرب السائق"],"h1":"القاعدة تشمل أكثر من مادة واحدة.","h2":"في Colorado، من المخالف للقانون أن يكون في منطقة الركّاب في المركبة على طريق عام وعاء مفتوح للكحول أو وعاء مفتوح للماريجوانا.","p":"صحيح. لا كحول ولا ماريجوانا مفتوحة في منطقة الركّاب."},"ref":{"doc":"CO","page":3}},{"id":"co-040","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how soon must a new resident get a Colorado driver license?","o":["Within 10 days","Within 30 days","Within 90 days","Within one year"],"h1":"It is about one month.","h2":"In Colorado, a new resident must get a Colorado driver license within 30 days of becoming a resident, with a few exceptions such as active-duty military.","p":"Right. New residents have 30 days."},"es":{"q":"En Colorado, ¿en cuánto tiempo debe un nuevo residente obtener una licencia de Colorado?","o":["En 10 días","En 30 días","En 90 días","En un año"],"h1":"Es más o menos un mes.","h2":"En Colorado, un nuevo residente debe obtener una licencia de manejo de Colorado dentro de los 30 días de hacerse residente, con algunas excepciones como el personal militar en servicio activo.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Colorado，新居民必须在多长时间内拿到 Colorado 驾照？","o":["10 天内","30 天内","90 天内","一年内"],"h1":"大约一个月。","h2":"在 Colorado，新居民必须在成为居民后 30 天内拿到 Colorado 驾照，现役军人等少数情况除外。","p":"对。新居民有 30 天时间。"},"vi":{"q":"Ở Colorado, người mới đến cư trú phải lấy bằng lái Colorado trong vòng bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 90 ngày","Trong vòng một năm"],"h1":"Khoảng một tháng.","h2":"Ở Colorado, người mới đến cư trú phải lấy bằng lái Colorado trong vòng 30 ngày kể từ khi trở thành cư dân, trừ một vài trường hợp như quân nhân đang tại ngũ.","p":"Đúng. Người mới cư trú có 30 ngày."},"tl":{"q":"Sa Colorado, gaano kabilis dapat kumuha ng Colorado driver license ang bagong residente?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 90 araw","Sa loob ng isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Colorado, dapat kumuha ng Colorado driver license ang bagong residente sa loob ng 30 araw mula nang maging residente, maliban sa ilang kaso gaya ng mga nasa active-duty military.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Colorado، خلال كم من الوقت يجب على المقيم الجديد أن يحصل على رخصة قيادة من Colorado؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 90 يومًا","خلال سنة واحدة"],"h1":"هي شهر تقريبًا.","h2":"في Colorado، يجب على المقيم الجديد أن يحصل على رخصة قيادة من Colorado خلال 30 يومًا من أن يصبح مقيمًا، مع بعض الاستثناءات مثل العسكريين في الخدمة الفعلية.","p":"صحيح. المقيمون الجدد لديهم 30 يومًا."},"ref":{"doc":"CO","page":1}},{"id":"co-041","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, a teen applies for a license before age 16 and a half. What training must the teen also complete?","o":["A first aid class","A night driving class only","Nothing more than the driving log","6 hours behind the wheel with a driving instructor"],"h1":"It is time in the car with a professional teacher.","h2":"In Colorado, a teen younger than 16 and a half must also complete 6 hours of behind-the-wheel training with an approved driver education instructor.","p":"Right. Under 16 and a half, 6 hours with an instructor are needed."},"es":{"q":"En Colorado, un adolescente pide la licencia antes de cumplir 16 años y medio. ¿Qué entrenamiento debe completar además?","o":["Una clase de primeros auxilios","Solo una clase de manejo nocturno","Nada más que el registro de manejo","6 horas al volante con un instructor de manejo"],"h1":"Es tiempo en el carro con un maestro profesional.","h2":"En Colorado, un adolescente menor de 16 años y medio también debe completar 6 horas de práctica al volante con un instructor de educación vial aprobado.","p":"Correcto. Antes de los 16 años y medio, se necesitan 6 horas con un instructor."},"zh":{"q":"在 Colorado，一名青少年在 16 岁半之前申请驾照。这名青少年还必须完成什么训练？","o":["急救课","只有夜间驾驶课","除了驾驶记录以外不需要别的","跟驾驶教练上路练习 6 小时"],"h1":"这是在车里跟专业老师一起的时间。","h2":"在 Colorado，不满 16 岁半的青少年还必须跟认可的驾驶教育教练完成 6 小时的上路驾驶训练。","p":"对。不满 16 岁半，需要跟教练练 6 小时。"},"vi":{"q":"Ở Colorado, một thiếu niên xin bằng lái trước 16 tuổi rưỡi. Thiếu niên đó còn phải hoàn thành khóa huấn luyện nào?","o":["Một lớp sơ cứu","Chỉ một lớp lái xe ban đêm","Không cần gì thêm ngoài sổ ghi giờ lái","6 giờ cầm lái với người dạy lái xe"],"h1":"Đó là thời gian ngồi trong xe với một giáo viên chuyên nghiệp.","h2":"Ở Colorado, thiếu niên dưới 16 tuổi rưỡi còn phải hoàn thành 6 giờ cầm lái thực hành với một người dạy lái xe được chấp thuận.","p":"Đúng. Dưới 16 tuổi rưỡi, cần 6 giờ với người dạy lái."},"tl":{"q":"Sa Colorado, nag-apply ng lisensya ang isang teen bago mag-16 at kalahating taong gulang. Anong training pa ang dapat niyang tapusin?","o":["Isang klase sa first aid","Klase sa pagmamaneho sa gabi lamang","Wala nang iba bukod sa driving log","6 na oras sa manibela kasama ang driving instructor"],"h1":"Ito ay oras sa loob ng kotse kasama ang isang propesyonal na guro.","h2":"Sa Colorado, ang teen na wala pang 16 at kalahati ay dapat ding tumapos ng 6 na oras ng behind-the-wheel training kasama ang aprubadong driver education instructor.","p":"Tama. Kapag wala pang 16 at kalahati, kailangan ang 6 na oras kasama ang instructor."},"ar":{"q":"في Colorado، يتقدّم مراهق لطلب رخصة قبل أن يبلغ 16 سنة ونصفًا. ما التدريب الذي يجب أن يُكمله أيضًا؟","o":["دورة إسعافات أولية","دورة قيادة ليلية فقط","لا شيء غير سجلّ القيادة","6 ساعات خلف المقود مع مدرّب قيادة"],"h1":"هو وقت في السيارة مع معلّم محترف.","h2":"في Colorado، يجب على المراهق الذي عمره أقل من 16 سنة ونصف أن يُكمل أيضًا 6 ساعات من التدريب خلف المقود مع مدرّب معتمد لتعليم القيادة.","p":"صحيح. تحت 16 سنة ونصف، تلزم 6 ساعات مع مدرّب."},"ref":{"doc":"CO","page":2}},{"id":"co-042","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, when must your headlights be on, besides from sunset to sunrise?","o":["When you cannot see clearly for 1,000 feet","Only when it is snowing","Only on the interstate","When you drive faster than 55 mph"],"h1":"Think about how far ahead you can see.","h2":"Colorado law requires headlights from sunset to sunrise and any time you cannot see clearly for 1,000 feet.","p":"Right. Lights on when you cannot see 1,000 feet."},"es":{"q":"En Colorado, además de la puesta a la salida del sol, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Cuando no puede ver bien a 1,000 pies","Solo cuando está nevando","Solo en la autopista interestatal","Cuando maneja a más de 55 mph"],"h1":"Piense en qué tan lejos puede ver.","h2":"La ley de Colorado exige las luces delanteras desde la puesta hasta la salida del sol y siempre que usted no pueda ver bien a 1,000 pies.","p":"Correcto. Luces encendidas cuando no ve a 1,000 pies."},"zh":{"q":"在 Colorado，除了从日落到日出以外，什么时候还必须开大灯？","o":["当你看不清 1,000 英尺远的时候","只有下雪的时候","只有在州际公路上","当你开得比 55 mph 快的时候"],"h1":"想一想你能看多远。","h2":"Colorado 法律规定，从日落到日出，以及任何你看不清 1,000 英尺远的时候，都必须开大灯。","p":"对。看不清 1,000 英尺远时要开灯。"},"vi":{"q":"Ở Colorado, ngoài thời gian từ lúc mặt trời lặn đến lúc mặt trời mọc, khi nào bạn phải bật đèn pha?","o":["Khi bạn không nhìn rõ được 1,000 feet","Chỉ khi trời có tuyết","Chỉ trên xa lộ liên bang","Khi bạn lái nhanh hơn 55 mph"],"h1":"Hãy nghĩ xem bạn nhìn được xa bao nhiêu phía trước.","h2":"Luật Colorado yêu cầu bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc và bất cứ khi nào bạn không nhìn rõ được 1,000 feet.","p":"Đúng. Bật đèn khi bạn không nhìn thấy được 1,000 feet."},"tl":{"q":"Sa Colorado, kailan dapat nakabukas ang headlights mo, bukod sa mula paglubog hanggang pagsikat ng araw?","o":["Kapag hindi ka makakita nang malinaw hanggang 1,000 talampakan","Kapag umuulan lang ng niyebe","Sa interstate lamang","Kapag nagmamaneho ka nang mas mabilis sa 55 mph"],"h1":"Isipin kung gaano kalayo ang nakikita mo sa unahan.","h2":"Ayon sa batas ng Colorado, dapat nakabukas ang headlights mula paglubog hanggang pagsikat ng araw at anumang oras na hindi ka makakita nang malinaw hanggang 1,000 talampakan.","p":"Tama. Buksan ang ilaw kapag hindi ka makakita hanggang 1,000 talampakan."},"ar":{"q":"في Colorado، متى يجب أن تكون أضواء سيارتك الأمامية مُشغّلة، غير الوقت من غروب الشمس إلى شروقها؟","o":["عندما لا تستطيع أن ترى بوضوح لمسافة 1,000 قدم","فقط عندما يتساقط الثلج","فقط على الطريق السريع بين الولايات","عندما تقود أسرع من 55 mph"],"h1":"فكّر في المسافة التي تستطيع أن تراها أمامك.","h2":"يفرض قانون Colorado تشغيل الأضواء الأمامية من غروب الشمس إلى شروقها وفي أي وقت لا تستطيع فيه أن ترى بوضوح لمسافة 1,000 قدم.","p":"صحيح. شغّل الأضواء عندما لا تستطيع أن ترى لمسافة 1,000 قدم."},"ref":{"doc":"CO","page":16}},{"id":"co-043","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, you are using high beams at night. How close may an oncoming vehicle get before you must dim them?","o":["100 feet","1,000 feet","500 feet","50 feet"],"h1":"It is farther than the distance for a car you are following.","h2":"In Colorado, you must dim your high beams before you come within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Colorado, usted usa las luces altas de noche. ¿A qué distancia de un vehículo que viene de frente debe bajarlas?","o":["100 pies","1,000 pies","500 pies","50 pies"],"h1":"Es más lejos que la distancia para un carro que usted sigue.","h2":"En Colorado, usted debe bajar las luces altas antes de acercarse a 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies del tráfico de frente."},"zh":{"q":"在 Colorado，你在晚上开着远光灯。对面来车离你多近时，你必须把灯调暗？","o":["100 英尺","1,000 英尺","500 英尺","50 英尺"],"h1":"它比跟在别的车后面时的距离更远。","h2":"在 Colorado，你必须在离对面来车 500 英尺以内之前，把远光灯调暗。","p":"对。离对面来车 500 英尺内要调暗车灯。"},"vi":{"q":"Ở Colorado, bạn đang bật đèn pha chiếu xa vào ban đêm. Xe đi ngược chiều đến gần bao nhiêu thì bạn phải hạ đèn?","o":["100 feet","1,000 feet","500 feet","50 feet"],"h1":"Khoảng cách này xa hơn khoảng cách khi bạn đi sau một xe khác.","h2":"Ở Colorado, bạn phải hạ đèn pha chiếu xa trước khi đến gần trong vòng 500 feet của xe đi ngược chiều.","p":"Đúng. Hạ đèn khi cách xe ngược chiều 500 feet."},"tl":{"q":"Sa Colorado, gumagamit ka ng high beams sa gabi. Gaano kalapit ang paparating na sasakyan bago mo dapat i-dim ang mga ito?","o":["100 talampakan","1,000 talampakan","500 talampakan","50 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa kotseng sinusundan mo.","h2":"Sa Colorado, dapat mong i-dim ang high beams bago ka umabot sa 500 talampakan mula sa paparating na sasakyan.","p":"Tama. I-dim ang ilaw sa loob ng 500 talampakan mula sa paparating na trapiko."},"ar":{"q":"في Colorado، أنت تستخدم الأضواء العالية ليلًا. إلى أي مسافة يمكن أن تقترب مركبة قادمة من الأمام قبل أن يجب عليك خفض الأضواء؟","o":["100 قدم","1,000 قدم","500 قدم","50 قدمًا"],"h1":"هي أبعد من المسافة الخاصة بسيارة تسير خلفها.","h2":"في Colorado، يجب أن تخفض أضواءك العالية قبل أن تقترب إلى مسافة 500 قدم من مركبة قادمة من الأمام.","p":"صحيح. اخفض الأضواء على بُعد 500 قدم من المركبات القادمة."},"ref":{"doc":"CO","page":16}},{"id":"co-044","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is less than the distance for a stop sign.","h2":"In Colorado, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a fire hydrant."},"es":{"q":"En Colorado, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es menos que la distancia para un letrero de alto.","h2":"En Colorado, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies de un hidrante."},"zh":{"q":"在 Colorado，你可以在离消防栓多近的地方停车？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"它比停车标志的距离短。","h2":"在 Colorado，你不能在离消防栓 15 英尺以内的地方停车。","p":"对。离消防栓要保持 15 英尺。"},"vi":{"q":"Ở Colorado, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Khoảng cách này ngắn hơn khoảng cách với biển báo dừng.","h2":"Ở Colorado, bạn không được đậu xe trong vòng 15 feet của trụ nước cứu hỏa.","p":"Đúng. Cách trụ nước cứu hỏa 15 feet."},"tl":{"q":"Sa Colorado, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 30 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas maikli ito kaysa sa layo para sa stop sign.","h2":"Sa Colorado, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang 15 talampakan sa fire hydrant."},"ar":{"q":"في Colorado، إلى أي مدى يمكنك أن تركن قريبًا من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أقل من المسافة الخاصة بإشارة التوقّف.","h2":"في Colorado، يجب ألّا تركن على مسافة أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا من صنبور الإطفاء."},"ref":{"doc":"CO","page":13}},{"id":"co-045","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, you may not park within how many feet before a stop sign or a traffic signal at the side of the road?","o":["10 feet","15 feet","20 feet","30 feet"],"h1":"It is double the fire hydrant distance.","h2":"In Colorado, you may not park within 30 feet before a stop sign or a traffic signal at the side of the road (near a railroad crossing the limit is 50 feet).","p":"Right. Keep 30 feet back from a stop sign or traffic signal."},"es":{"q":"En Colorado, ¿a menos de cuántos pies antes de un letrero de alto o un semáforo al lado de la calle no puede estacionarse?","o":["10 pies","15 pies","20 pies","30 pies"],"h1":"Es el doble de la distancia del hidrante.","h2":"En Colorado, no puede estacionarse a menos de 30 pies antes de un letrero de alto o un semáforo al lado de la calle (cerca de un cruce de tren el límite es de 50 pies).","p":"Correcto. Manténgase a 30 pies de un letrero de alto o un semáforo."},"zh":{"q":"在 Colorado，在路边的停车标志（stop sign）或交通信号灯前方多少英尺以内不可以停车？","o":["10 英尺","15 英尺","20 英尺","30 英尺"],"h1":"这是消防栓距离的两倍。","h2":"在 Colorado，你不可以在路边的停车标志或交通信号灯前方 30 英尺以内停车（在铁路道口附近，限制是 50 英尺）。","p":"对。停车时要离停车标志或交通信号灯至少 30 英尺。"},"vi":{"q":"Ở Colorado, bạn không được đậu xe trong phạm vi bao nhiêu feet trước biển báo dừng (stop sign) hoặc đèn giao thông bên đường?","o":["10 feet","15 feet","20 feet","30 feet"],"h1":"Đó là gấp đôi khoảng cách với trụ nước chữa cháy.","h2":"Ở Colorado, bạn không được đậu xe trong phạm vi 30 feet trước biển báo dừng hoặc đèn giao thông bên đường (gần chỗ băng qua đường sắt, giới hạn là 50 feet).","p":"Đúng. Hãy đậu cách biển báo dừng hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Colorado, hindi ka puwedeng pumarada sa loob ng ilang talampakan bago ang stop sign o traffic signal sa gilid ng daan?","o":["10 talampakan","15 talampakan","20 talampakan","30 talampakan"],"h1":"Doble ito ng layo mula sa fire hydrant.","h2":"Sa Colorado, hindi ka puwedeng pumarada sa loob ng 30 talampakan bago ang stop sign o traffic signal sa gilid ng daan (malapit sa tawiran ng tren, ang limitasyon ay 50 talampakan).","p":"Tama. Lumayo nang 30 talampakan mula sa stop sign o traffic signal."},"ar":{"q":"في Colorado، لا يجوز لك أن تركن سيارتك على بُعد أقل من كم قدمًا قبل إشارة التوقف (stop sign) أو إشارة المرور على جانب الطريق؟","o":["10 أقدام","15 قدمًا","20 قدمًا","30 قدمًا"],"h1":"إنها ضعف المسافة من صنبور إطفاء الحريق.","h2":"في Colorado يجب ألّا تركن سيارتك على بُعد أقل من 30 قدمًا قبل إشارة التوقف أو إشارة المرور على جانب الطريق (وقرب معبر السكة الحديدية يكون الحد 50 قدمًا).","p":"صحيح. ابقَ على بُعد 30 قدمًا من إشارة التوقف أو إشارة المرور."},"ref":{"doc":"CO","page":13}},{"id":"co-046","scope":"CO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Colorado, two cars meet on a steep mountain road too narrow for both. Who must usually yield?","o":["The car going downhill","The car going uphill","The smaller car","The car that honks last"],"h1":"Starting again on a steep hill is harder going up.","h2":"In Colorado, on a steep, narrow road, the vehicle going downhill must yield by backing up to a wider spot or stopping to let the uphill vehicle pass.","p":"Right. The downhill car yields to the uphill car."},"es":{"q":"En Colorado, dos carros se encuentran en un camino de montaña empinado y demasiado angosto para ambos. ¿Quién debe ceder el paso, por lo general?","o":["El carro que va cuesta abajo","El carro que va cuesta arriba","El carro más pequeño","El último que toca la bocina"],"h1":"Volver a arrancar en una cuesta es más difícil subiendo.","h2":"En Colorado, en un camino empinado y angosto, el vehículo que baja debe ceder el paso retrocediendo a un lugar más ancho o deteniéndose para dejar pasar al que sube.","p":"Correcto. El que baja cede el paso al que sube."},"zh":{"q":"在 Colorado，两辆车在陡峭的山路上相遇，路太窄，两辆车不能同时通过。通常谁必须让行？","o":["下坡的车","上坡的车","比较小的车","最后按喇叭的车"],"h1":"在陡坡上重新起步，上坡更难。","h2":"在 Colorado，在陡峭狭窄的路上，下坡的车必须让行：倒车到较宽的地方，或停下来让上坡的车先过。","p":"对。下坡的车让上坡的车。"},"vi":{"q":"Ở Colorado, hai xe gặp nhau trên một con đường núi dốc, quá hẹp cho cả hai xe. Thường thì xe nào phải nhường?","o":["Xe đang xuống dốc","Xe đang lên dốc","Xe nhỏ hơn","Xe bấm còi sau cùng"],"h1":"Khởi động lại trên dốc cao thì khó hơn khi đang lên dốc.","h2":"Ở Colorado, trên đường dốc và hẹp, xe đang xuống dốc phải nhường đường bằng cách lùi lại đến chỗ rộng hơn hoặc dừng lại để xe đang lên dốc đi qua.","p":"Đúng. Xe xuống dốc nhường xe lên dốc."},"tl":{"q":"Sa Colorado, nagkasalubong ang dalawang kotse sa matarik na daan sa bundok na masyadong makitid para sa dalawa. Sino ang karaniwang dapat magbigay-daan?","o":["Ang kotseng pababa","Ang kotseng paakyat","Ang mas maliit na kotse","Ang huling bumusina"],"h1":"Mas mahirap umandar ulit sa matarik na daan kapag paakyat.","h2":"Sa Colorado, sa matarik at makitid na daan, ang sasakyang pababa ang dapat magbigay-daan sa pag-atras papunta sa mas malapad na lugar o paghinto para makadaan ang sasakyang paakyat.","p":"Tama. Ang pababang kotse ang nagbibigay-daan sa paakyat."},"ar":{"q":"في Colorado، تلتقي سيارتان على طريق جبلي شديد الانحدار وضيّق جدًا لا يتّسع للاثنتين. من يجب عليه عادةً أن يُفسح الطريق؟","o":["السيارة النازلة","السيارة الصاعدة","السيارة الأصغر","السيارة التي تُطلق البوق أخيرًا"],"h1":"الانطلاق من جديد على منحدر شديد أصعب عند الصعود.","h2":"في Colorado، على طريق شديد الانحدار وضيّق، يجب على المركبة النازلة أن تُفسح الطريق بالرجوع إلى مكان أوسع أو بالتوقّف لتمرّ المركبة الصاعدة.","p":"صحيح. السيارة النازلة تُفسح الطريق للصاعدة."},"ref":{"doc":"CO","page":11}},{"id":"co-047","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, several snow plows are clearing the highway together in a staggered, diagonal line. What does the law say?","o":["You may pass them on the right","You may pass after you honk","You may not pass them","You may pass if the road is dry"],"h1":"The plows make a wall of blowing snow across the lanes.","h2":"In Colorado, it is illegal to pass snow plows that are working together in a staggered formation, so you must stay behind them.","p":"Right. Do not pass plows working in formation."},"es":{"q":"En Colorado, varios quitanieves limpian la carretera juntos en una fila diagonal escalonada. ¿Qué dice la ley?","o":["Puede rebasarlos por la derecha","Puede rebasarlos después de tocar la bocina","No puede rebasarlos","Puede rebasarlos si el camino está seco"],"h1":"Los quitanieves forman una pared de nieve en los carriles.","h2":"En Colorado, es ilegal rebasar a quitanieves que trabajan juntos en formación escalonada, así que usted debe quedarse detrás de ellos.","p":"Correcto. No rebase a quitanieves que trabajan en formación."},"zh":{"q":"在 Colorado，几辆铲雪车排成错开的斜线，一起清理公路。法律怎么说？","o":["你可以从右边超过它们","你可以按喇叭后超过它们","你不可以超过它们","如果路面是干的，你可以超过它们"],"h1":"铲雪车会在车道上扬起一道雪墙。","h2":"在 Colorado，超过排成错开队形一起作业的铲雪车是违法的，所以你必须留在它们后面。","p":"对。不要超过排成队形作业的铲雪车。"},"vi":{"q":"Ở Colorado, nhiều xe ủi tuyết đang cùng dọn xa lộ theo một hàng chéo so le. Luật nói gì?","o":["Bạn được vượt chúng bên phải","Bạn được vượt sau khi bấm còi","Bạn không được vượt chúng","Bạn được vượt nếu mặt đường khô"],"h1":"Các xe ủi tuyết tạo ra một bức tường tuyết bay ngang qua các làn đường.","h2":"Ở Colorado, vượt các xe ủi tuyết đang cùng làm việc theo đội hình so le là phạm luật, vì vậy bạn phải đi phía sau chúng.","p":"Đúng. Không vượt xe ủi tuyết đang làm việc theo đội hình."},"tl":{"q":"Sa Colorado, ilang snow plow ang sabay na naglilinis ng highway sa isang pahilis at salit-salit na hanay. Ano ang sinasabi ng batas?","o":["Puwede mo silang lampasan sa kanan","Puwede kang lumampas pagkatapos bumusina","Hindi mo sila puwedeng lampasan","Puwede kang lumampas kung tuyo ang kalsada"],"h1":"Gumagawa ang mga plow ng pader ng lumilipad na niyebe sa mga lane.","h2":"Sa Colorado, labag sa batas ang lampasan ang mga snow plow na sabay na nagtatrabaho sa salit-salit na formation, kaya dapat kang manatili sa likod nila.","p":"Tama. Huwag lampasan ang mga plow na nagtatrabaho nang naka-formation."},"ar":{"q":"في Colorado، عدّة كاسحات ثلج تنظّف الطريق السريع معًا في خط مائل ومتدرّج. ماذا يقول القانون؟","o":["يمكنك أن تتجاوزها من اليمين","يمكنك أن تتجاوزها بعد أن تُطلق البوق","يجب ألّا تتجاوزها","يمكنك أن تتجاوزها إذا كان الطريق جافًا"],"h1":"تصنع الكاسحات جدارًا من الثلج المتطاير عبر المسارات.","h2":"في Colorado، من المخالف للقانون أن تتجاوز كاسحات الثلج التي تعمل معًا في تشكيل متدرّج، لذلك يجب أن تبقى خلفها.","p":"صحيح. لا تتجاوز الكاسحات التي تعمل في تشكيل."},"ref":{"doc":"CO","page":11}},{"id":"co-048","scope":"CO","cat":"signals","sign":null,"c":1,"en":{"q":"In Colorado, on a four-lane highway with a speed limit above 40 mph, how far ahead must you signal before turning or changing lanes?","o":["50 feet","200 feet","100 feet","500 feet"],"h1":"It is twice the distance used on city streets.","h2":"In Colorado, on a four-lane highway with a limit above 40 mph, you must signal for 200 feet before you turn or change lanes.","p":"Right. Signal for 200 feet on faster four-lane highways."},"es":{"q":"En Colorado, en una carretera de cuatro carriles con límite de más de 40 mph, ¿con cuánta anticipación debe poner la direccional antes de girar o cambiar de carril?","o":["50 pies","200 pies","100 pies","500 pies"],"h1":"Es el doble de la distancia que se usa en las calles de la ciudad.","h2":"En Colorado, en una carretera de cuatro carriles con límite de más de 40 mph, debe poner la direccional durante 200 pies antes de girar o cambiar de carril.","p":"Correcto. Direccional por 200 pies en carreteras rápidas de cuatro carriles."},"zh":{"q":"在 Colorado，在限速超过 40 mph 的四车道公路上，转弯或变道前你必须提前多远打方向灯？","o":["50 英尺","200 英尺","100 英尺","500 英尺"],"h1":"它是城市街道上所用距离的两倍。","h2":"在 Colorado，在限速超过 40 mph 的四车道公路上，你必须在转弯或变道前打方向灯至少 200 英尺。","p":"对。在较快的四车道公路上，要打方向灯 200 英尺。"},"vi":{"q":"Ở Colorado, trên xa lộ bốn làn có tốc độ giới hạn trên 40 mph, bạn phải bật đèn xi nhan trước bao xa trước khi rẽ hoặc đổi làn?","o":["50 feet","200 feet","100 feet","500 feet"],"h1":"Khoảng cách này gấp đôi khoảng cách dùng trên đường phố trong thành phố.","h2":"Ở Colorado, trên xa lộ bốn làn có tốc độ giới hạn trên 40 mph, bạn phải bật đèn xi nhan trong 200 feet trước khi rẽ hoặc đổi làn.","p":"Đúng. Bật xi nhan trong 200 feet trên xa lộ bốn làn chạy nhanh."},"tl":{"q":"Sa Colorado, sa four-lane highway na may speed limit na higit sa 40 mph, gaano kalayo bago lumiko o lumipat ng lane ka dapat mag-signal?","o":["50 talampakan","200 talampakan","100 talampakan","500 talampakan"],"h1":"Doble ito ng layo na ginagamit sa mga kalye sa lungsod.","h2":"Sa Colorado, sa four-lane highway na may limit na higit sa 40 mph, dapat kang mag-signal nang 200 talampakan bago ka lumiko o lumipat ng lane.","p":"Tama. Mag-signal nang 200 talampakan sa mas mabibilis na four-lane highway."},"ar":{"q":"في Colorado، على طريق سريع من أربعة مسارات حدّ السرعة فيه أكثر من 40 mph، من أي مسافة يجب أن تُشغّل الإشارة قبل أن تنعطف أو تغيّر المسار؟","o":["50 قدمًا","200 قدم","100 قدم","500 قدم"],"h1":"هي ضعف المسافة المستخدمة في شوارع المدينة.","h2":"في Colorado، على طريق سريع من أربعة مسارات حدّ السرعة فيه أكثر من 40 mph، يجب أن تُشغّل الإشارة لمسافة 200 قدم قبل أن تنعطف أو تغيّر المسار.","p":"صحيح. شغّل الإشارة لمسافة 200 قدم على الطرق السريعة ذات المسارات الأربعة."},"ref":{"doc":"CO","page":12}},{"id":"co-049","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, what is the least space you must leave when you pass a bicyclist?","o":["1 foot","2 feet","10 feet","3 feet"],"h1":"Count from the outer edge of your car, including the mirrors.","h2":"In Colorado, you must leave at least 3 feet between the bicyclist and the outermost part of your vehicle, and you may briefly cross a solid yellow line to do it when no traffic is coming.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Colorado, ¿cuál es el espacio mínimo que debe dejar al rebasar a un ciclista?","o":["1 pie","2 pies","10 pies","3 pies"],"h1":"Cuente desde la parte más exterior de su carro, incluidos los espejos.","h2":"En Colorado, debe dejar por lo menos 3 pies entre el ciclista y la parte más exterior de su vehículo, y puede cruzar brevemente una línea amarilla continua para lograrlo si no viene tráfico.","p":"Correcto. Deje al ciclista por lo menos 3 pies."},"zh":{"q":"在 Colorado，超过骑自行车的人时，你至少必须留出多少空间？","o":["1 英尺","2 英尺","10 英尺","3 英尺"],"h1":"从你车子最外面的边缘算起，包括后视镜。","h2":"在 Colorado，你必须在骑自行车的人和你车子最外面的部分之间留出至少 3 英尺；如果对面没有来车，你可以为此短暂越过黄色实线。","p":"对。给骑自行车的人至少留 3 英尺。"},"vi":{"q":"Ở Colorado, khi vượt người đi xe đạp, bạn phải chừa khoảng cách ít nhất là bao nhiêu?","o":["1 foot","2 feet","10 feet","3 feet"],"h1":"Hãy tính từ mép ngoài cùng của xe bạn, kể cả gương chiếu hậu.","h2":"Ở Colorado, bạn phải chừa ít nhất 3 feet giữa người đi xe đạp và phần ngoài cùng của xe bạn, và bạn được tạm thời băng qua vạch vàng liền để làm việc này khi không có xe đi tới.","p":"Đúng. Chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Colorado, ano ang pinakamaliit na espasyo na dapat mong iwan kapag nilalampasan mo ang nagbibisikleta?","o":["1 talampakan","2 talampakan","10 talampakan","3 talampakan"],"h1":"Magbilang mula sa pinakalabas na gilid ng kotse mo, kasama ang mga salamin.","h2":"Sa Colorado, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng nagbibisikleta at ng pinakalabas na bahagi ng sasakyan mo, at puwede kang tumawid sandali sa solid na dilaw na linya para gawin ito kapag walang paparating na trapiko.","p":"Tama. Bigyan ang nagbibisikleta ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Colorado، ما أقل مسافة يجب أن تتركها عندما تتجاوز راكب درّاجة؟","o":["1 قدم","2 قدم","10 أقدام","3 أقدام"],"h1":"احسب من الحافة الخارجية لسيارتك، ومعها المرايا.","h2":"في Colorado، يجب أن تترك 3 أقدام على الأقل بين راكب الدرّاجة وأبعد جزء خارجي من مركبتك، ويمكنك أن تعبر الخط الأصفر المتّصل لوقت قصير لتفعل ذلك إذا لم تكن هناك مركبات قادمة.","p":"صحيح. اترك لراكب الدرّاجة 3 أقدام على الأقل."},"ref":{"doc":"CO","page":15}},{"id":"co-050","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, you have a minor crash on a divided highway. No one is hurt, no alcohol or drugs are involved, and the cars can be driven. What must you do?","o":["Move the cars off the highway","Leave the cars where they stopped","Wait in the cars for police","Drive home and call later"],"h1":"Colorado has a law named for what you should do with the cars.","h2":"Under Colorado's Move It law, after a minor crash on a divided highway with no injuries, no alcohol or drugs, and drivable cars, you must move the vehicles off the highway, then exchange information and notify police.","p":"Right. Move it off the highway, then share information."},"es":{"q":"En Colorado, usted tiene un choque menor en una carretera dividida. Nadie está herido, no hay alcohol ni drogas, y los carros se pueden manejar. ¿Qué debe hacer?","o":["Sacar los carros de la carretera","Dejar los carros donde quedaron","Esperar en los carros a la policía","Irse a casa y llamar después"],"h1":"Colorado tiene una ley con el nombre de lo que debe hacer con los carros.","h2":"Según la ley Move It de Colorado, después de un choque menor en una carretera dividida, sin heridos, sin alcohol ni drogas y con carros que se pueden manejar, usted debe sacar los vehículos de la carretera y luego intercambiar datos y avisar a la policía.","p":"Correcto. Saque los carros de la carretera y luego intercambie datos."},"zh":{"q":"在 Colorado，你在有中间分隔的公路上发生了小车祸。没有人受伤，没有涉及酒精或毒品，车也还能开。你必须怎么做？","o":["把车移出公路","把车留在停下的地方","在车里等警察","开车回家，以后再打电话"],"h1":"Colorado 有一条法律，名字就是你应该怎么处理车子。","h2":"根据 Colorado 的 Move It 法，在有中间分隔的公路上发生没有人受伤、没有酒精或毒品、车还能开的小车祸后，你必须把车移出公路，然后交换资料并通知警察。","p":"对。把车移出公路，然后交换资料。"},"vi":{"q":"Ở Colorado, bạn gặp một vụ va chạm nhẹ trên xa lộ có dải phân cách. Không ai bị thương, không có rượu bia hay ma túy, và các xe vẫn lái được. Bạn phải làm gì?","o":["Dời các xe ra khỏi xa lộ","Để các xe ở chỗ chúng dừng lại","Ngồi trong xe chờ cảnh sát","Lái xe về nhà rồi gọi sau"],"h1":"Colorado có một luật được đặt tên theo việc bạn nên làm với các xe.","h2":"Theo luật Move It của Colorado, sau một vụ va chạm nhẹ trên xa lộ có dải phân cách, không ai bị thương, không có rượu bia hay ma túy, và xe vẫn lái được, bạn phải dời các xe ra khỏi xa lộ, rồi trao đổi thông tin và báo cho cảnh sát.","p":"Đúng. Dời xe ra khỏi xa lộ, rồi trao đổi thông tin."},"tl":{"q":"Sa Colorado, nagkaroon ka ng maliit na banggaan sa divided highway. Walang nasaktan, walang alak o droga, at puwede pang imaneho ang mga kotse. Ano ang dapat mong gawin?","o":["Alisin ang mga kotse sa highway","Iwan ang mga kotse kung saan sila huminto","Maghintay sa loob ng kotse para sa pulis","Umuwi at tumawag mamaya"],"h1":"May batas ang Colorado na ipinangalan sa dapat mong gawin sa mga kotse.","h2":"Ayon sa Move It law ng Colorado, pagkatapos ng maliit na banggaan sa divided highway na walang nasaktan, walang alak o droga, at puwede pang imaneho ang mga kotse, dapat mong alisin ang mga sasakyan sa highway, saka magpalitan ng impormasyon at ipaalam sa pulis.","p":"Tama. Alisin ang mga kotse sa highway, saka magpalitan ng impormasyon."},"ar":{"q":"في Colorado، وقع لك حادث بسيط على طريق سريع مُقسَّم. لم يُصَب أحد، ولا كحول ولا مخدّرات، والسيارات يمكن قيادتها. ماذا يجب أن تفعل؟","o":["أن تُبعد السيارات عن الطريق السريع","أن تترك السيارات حيث توقّفت","أن تنتظر الشرطة داخل السيارات","أن تقود إلى البيت وتتّصل لاحقًا"],"h1":"في Colorado قانون اسمه هو ما يجب أن تفعله بالسيارات.","h2":"حسب قانون Move It في Colorado، بعد حادث بسيط على طريق سريع مُقسَّم بلا إصابات، وبلا كحول أو مخدّرات، والسيارات يمكن قيادتها، يجب أن تُبعد المركبات عن الطريق السريع، ثم تتبادل المعلومات وتُبلغ الشرطة.","p":"صحيح. أبعد السيارات عن الطريق السريع، ثم تبادل المعلومات."},"ref":{"doc":"CO","page":25}},{"id":"co-051","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, when the traction law is active, how much tread must the tires on an all-wheel or four-wheel drive vehicle have?","o":["1/16 inch","2/32 inch","3/16 inch","Any tread is enough"],"h1":"Snow driving needs deep grooves, much more than the bare legal minimum.","h2":"In Colorado, when the traction law is active, an all-wheel or four-wheel drive vehicle without chains needs snow-rated or all-weather tires with at least 3/16 inch of tread.","p":"Right. The traction law needs 3/16 inch of tread."},"es":{"q":"En Colorado, cuando la ley de tracción está activa, ¿cuánta profundidad de dibujo deben tener las llantas de un vehículo con tracción integral o en las cuatro ruedas?","o":["1/16 de pulgada","2/32 de pulgada","3/16 de pulgada","Cualquier dibujo es suficiente"],"h1":"Manejar en nieve necesita surcos profundos, mucho más que el mínimo legal.","h2":"En Colorado, cuando la ley de tracción está activa, un vehículo con tracción integral o en las cuatro ruedas sin cadenas necesita llantas para nieve o para todo clima con al menos 3/16 de pulgada de dibujo.","p":"Correcto. La ley de tracción exige 3/16 de pulgada de dibujo."},"zh":{"q":"在 Colorado，当防滑法（traction law）生效时，全轮驱动或四轮驱动车辆的轮胎花纹至少要有多深？","o":["1/16 英寸","2/32 英寸","3/16 英寸","有花纹就够了"],"h1":"在雪地开车需要很深的花纹，比法律最低要求深得多。","h2":"在 Colorado，当防滑法生效时，没有装防滑链的全轮驱动或四轮驱动车辆，需要雪地轮胎或全天候轮胎，花纹深度至少 3/16 英寸。","p":"对。防滑法要求花纹深度 3/16 英寸。"},"vi":{"q":"Ở Colorado, khi luật bám đường (traction law) có hiệu lực, lốp của xe dẫn động mọi bánh hoặc bốn bánh phải có gai lốp sâu bao nhiêu?","o":["1/16 inch","2/32 inch","3/16 inch","Có gai lốp là đủ"],"h1":"Lái xe trên tuyết cần rãnh lốp sâu, sâu hơn nhiều so với mức tối thiểu theo luật.","h2":"Ở Colorado, khi luật bám đường có hiệu lực, xe dẫn động mọi bánh hoặc bốn bánh không có xích phải dùng lốp đi tuyết hoặc lốp mọi thời tiết có gai lốp sâu ít nhất 3/16 inch.","p":"Đúng. Luật bám đường yêu cầu gai lốp sâu 3/16 inch."},"tl":{"q":"Sa Colorado, kapag aktibo ang traction law, gaano kalalim dapat ang tread ng mga gulong ng sasakyang all-wheel o four-wheel drive?","o":["1/16 pulgada","2/32 pulgada","3/16 pulgada","Sapat na ang kahit anong tread"],"h1":"Kailangan ng malalalim na uka sa pagmamaneho sa niyebe, higit pa sa pinakamababang legal na sukat.","h2":"Sa Colorado, kapag aktibo ang traction law, ang sasakyang all-wheel o four-wheel drive na walang chains ay kailangan ng snow-rated o all-weather na gulong na may hindi bababa sa 3/16 pulgada ng tread.","p":"Tama. Kailangan ng traction law ang 3/16 pulgada ng tread."},"ar":{"q":"في Colorado، عندما يكون قانون التماسك (traction law) مُفعّلًا، كم يجب أن يكون عمق نقشة الإطارات في مركبة دفع كلّي أو دفع رباعي؟","o":["1/16 بوصة","2/32 بوصة","3/16 بوصة","أي نقشة تكفي"],"h1":"القيادة على الثلج تحتاج إلى أخاديد عميقة، أعمق بكثير من الحدّ الأدنى القانوني.","h2":"في Colorado، عندما يكون قانون التماسك مُفعّلًا، تحتاج مركبة الدفع الكلّي أو الدفع الرباعي التي ليس عليها سلاسل إلى إطارات للثلج أو لكل الأحوال الجوية بعمق نقشة 3/16 بوصة على الأقل.","p":"صحيح. قانون التماسك يتطلّب عمق نقشة 3/16 بوصة."},"ref":{"doc":"CO","page":null}},{"id":"co-052","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, after you change your name or address, how soon must you tell the DMV?","o":["Within 10 days","Within 30 days","Within 90 days","At your next renewal"],"h1":"You have about one month.","h2":"In Colorado, you must notify the Division of Motor Vehicles within 30 days after you change your name or address.","p":"Right. Tell the DMV within 30 days."},"es":{"q":"En Colorado, después de cambiar su nombre o su dirección, ¿en cuánto tiempo debe avisar al DMV?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 90 días","En su próxima renovación"],"h1":"Tiene más o menos un mes.","h2":"En Colorado, usted debe avisar a la División de Vehículos Motorizados dentro de los 30 días después de cambiar su nombre o su dirección.","p":"Correcto. Avise al DMV dentro de 30 días."},"ref":{"doc":"CO","page":1}},{"id":"co-053","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, if you fail the driving skills test, when may you take it again?","o":["After waiting 30 days","After a one-week wait","On the next business day","After six full months"],"h1":"The wait is short.","h2":"In Colorado, if you fail the drive test, you must wait until the next business day before you take it again.","p":"Right. You may retest on the next business day."},"es":{"q":"En Colorado, si usted reprueba el examen práctico de manejo, ¿cuándo puede tomarlo otra vez?","o":["Después de esperar 30 días","Después de una semana de espera","El siguiente día hábil","Después de seis meses completos"],"h1":"La espera es corta.","h2":"En Colorado, si usted reprueba el examen de manejo, debe esperar hasta el siguiente día hábil para tomarlo otra vez.","p":"Correcto. Puede repetirlo el siguiente día hábil."},"ref":{"doc":"CO","page":1}},{"id":"co-054","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, the affidavit of liability for a driver under 18 must be signed in front of whom?","o":["A teacher or coach at school","Any adult friend over age 21","Only the driving test examiner","A license office employee or a notary"],"h1":"The person watching the signature must be an official.","h2":"In Colorado, the affidavit of liability for a minor must be signed in front of a driver license office employee or a notary public.","p":"Right. It is signed before a license office employee or a notary."},"es":{"q":"En Colorado, ¿frente a quién se debe firmar la declaración jurada de responsabilidad de un conductor menor de 18 años?","o":["Un maestro o entrenador de la escuela","Cualquier amigo adulto mayor de 21 años","Solo el examinador del examen de manejo","Un empleado de la oficina de licencias o un notario"],"h1":"La persona que ve la firma debe ser un funcionario.","h2":"En Colorado, la declaración jurada de responsabilidad de un menor se debe firmar frente a un empleado de la oficina de licencias de conducir o un notario público.","p":"Correcto. Se firma frente a un empleado de la oficina de licencias o un notario."},"ref":{"doc":"CO","page":2}},{"id":"co-055","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, what happens if the adult who signed a teen's affidavit of liability withdraws the signature?","o":["The teen gets a warning letter","The teen must retake the written test","Nothing changes until age 18","The teen's permit or license is canceled"],"h1":"The signer is taking legal responsibility for the teen's driving.","h2":"In Colorado, if the person who signed the affidavit of liability withdraws the signature, the teen's permit or license is canceled.","p":"Right. Without the signer, the permit or license is canceled."},"es":{"q":"En Colorado, ¿qué pasa si el adulto que firmó la declaración jurada de responsabilidad de un adolescente retira su firma?","o":["El adolescente recibe una carta de advertencia","El adolescente debe repetir el examen escrito","Nada cambia hasta los 18 años","Se cancela el permiso o la licencia del adolescente"],"h1":"Quien firma acepta la responsabilidad legal por el manejo del adolescente.","h2":"En Colorado, si la persona que firmó la declaración jurada de responsabilidad retira su firma, se cancela el permiso o la licencia del adolescente.","p":"Correcto. Sin quien firma, se cancela el permiso o la licencia."},"ref":{"doc":"CO","page":2}},{"id":"co-056","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, a teen under 16 and a half has no approved driving school within 30 miles. What may replace the 6 hours of training with an instructor?","o":["12 more hours with a parent","2 more hours with a parent","A one-hour online video","Nothing; the rule is waived"],"h1":"The parent or permit supervisor does the extra driving.","h2":"In Colorado, if no approved driving school offers behind-the-wheel training within 30 miles of home, a teen under 16 and a half may drive 12 extra hours with a parent, guardian or alternate permit supervisor instead of the 6 instructor hours.","p":"Right. Twelve extra hours with a parent can take the place of the instructor hours."},"es":{"q":"En Colorado, un adolescente menor de 16 años y medio no tiene una escuela de manejo aprobada a menos de 30 millas. ¿Qué puede reemplazar las 6 horas de práctica con un instructor?","o":["12 horas más con un padre","2 horas más con un padre","Un video en línea de una hora","Nada; la regla no aplica"],"h1":"El padre o supervisor del permiso hace la práctica adicional.","h2":"En Colorado, si ninguna escuela de manejo aprobada ofrece práctica al volante a menos de 30 millas de la casa, un adolescente menor de 16 años y medio puede manejar 12 horas adicionales con un padre, tutor o supervisor alterno del permiso en lugar de las 6 horas con instructor.","p":"Correcto. Doce horas adicionales con un padre pueden reemplazar las horas con instructor."},"ref":{"doc":"CO","page":2}},{"id":"co-057","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how long is an instruction permit for a car valid after it is issued?","o":["6 months","1 year","3 years","5 years"],"h1":"It lasts longer than the one year a teen must hold it.","h2":"In Colorado, an instruction permit expires three years after the date it is issued.","p":"Right. The permit expires after three years."},"es":{"q":"En Colorado, ¿por cuánto tiempo es válido un permiso de aprendizaje para carro después de emitirse?","o":["6 meses","1 año","3 años","5 años"],"h1":"Dura más que el año que un adolescente debe tenerlo.","h2":"En Colorado, un permiso de aprendizaje vence tres años después de la fecha en que se emite.","p":"Correcto. El permiso vence a los tres años."},"ref":{"doc":"CO","page":null}},{"id":"co-058","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, when does a regular driver license for a person 21 or older expire?","o":["On your birthday 2 years later","On your birthday 5 years later","On your birthday 10 years later","It never expires"],"h1":"It is a middle number of years.","h2":"In Colorado, a driver license issued to a person 21 or older expires on the driver's birthday in the fifth year after it is issued.","p":"Right. It expires on your birthday five years later."},"es":{"q":"En Colorado, ¿cuándo vence una licencia de conducir regular de una persona de 21 años o más?","o":["En su cumpleaños 2 años después","En su cumpleaños 5 años después","En su cumpleaños 10 años después","Nunca vence"],"h1":"Es un número medio de años.","h2":"En Colorado, una licencia de conducir emitida a una persona de 21 años o más vence en el cumpleaños del conductor en el quinto año después de emitirse.","p":"Correcto. Vence en su cumpleaños cinco años después."},"ref":{"doc":"CO","page":null}},{"id":"co-059","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, when does a minor driver's license (issued under age 21) expire?","o":["On the driver's 18th birthday","On the driver's 25th birthday","One year after it is issued","20 days after the 21st birthday"],"h1":"It lasts a little past the age when the driver is no longer a minor.","h2":"In Colorado, a minor driver's license expires 20 days after the driver's 21st birthday.","p":"Right. It expires 20 days after the 21st birthday."},"es":{"q":"En Colorado, ¿cuándo vence una licencia de conducir de menor (emitida antes de los 21 años)?","o":["En el cumpleaños 18 del conductor","En el cumpleaños 25 del conductor","Un año después de emitirse","20 días después del cumpleaños 21"],"h1":"Dura un poco más allá de la edad en que el conductor deja de ser menor.","h2":"En Colorado, una licencia de conducir de menor vence 20 días después del cumpleaños 21 del conductor.","p":"Correcto. Vence 20 días después del cumpleaños 21."},"ref":{"doc":"CO","page":null}},{"id":"co-060","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, a driver age 21 or older can have the license suspended after how many points within 12 months?","o":["6 points","9 points","12 points","20 points"],"h1":"Adults are allowed more points than younger drivers.","h2":"In Colorado, a driver 21 or older can be suspended for 12 or more points within 12 months, or 18 or more within 24 months.","p":"Right. For adults, 12 points in 12 months can mean suspension."},"es":{"q":"En Colorado, ¿con cuántos puntos en 12 meses se puede suspender la licencia de un conductor de 21 años o más?","o":["6 puntos","9 puntos","12 puntos","20 puntos"],"h1":"A los adultos se les permiten más puntos que a los conductores jóvenes.","h2":"En Colorado, a un conductor de 21 años o más se le puede suspender la licencia con 12 puntos o más en 12 meses, o con 18 puntos o más en 24 meses.","p":"Correcto. Para los adultos, 12 puntos en 12 meses pueden causar una suspensión."},"ref":{"doc":"CO","page":null}},{"id":"co-061","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how many points does a ticket for driving 10 to 19 mph over the speed limit add?","o":["1 point","4 points","8 points","12 points"],"h1":"It is more than for going just a few miles over, but far less than for a DUI.","h2":"In Colorado, a conviction for speeding 10 to 19 mph over the limit adds 4 points to your driving record.","p":"Right. Speeding 10 to 19 mph over adds 4 points."},"es":{"q":"En Colorado, ¿cuántos puntos agrega una multa por manejar de 10 a 19 mph sobre el límite de velocidad?","o":["1 punto","4 puntos","8 puntos","12 puntos"],"h1":"Es más que por pasarse pocas millas, pero mucho menos que por un DUI.","h2":"En Colorado, una condena por exceder el límite de velocidad por 10 a 19 mph agrega 4 puntos a su historial de manejo.","p":"Correcto. Exceder por 10 a 19 mph suma 4 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-062","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, how many points does a conviction for leaving the scene of a crash add?","o":["2 points","4 points","6 points","12 points"],"h1":"It is one of the most serious offenses on the points list.","h2":"In Colorado, a conviction for leaving the scene of a crash adds 12 points, enough to suspend any driver's license.","p":"Right. Leaving the scene brings 12 points."},"es":{"q":"En Colorado, ¿cuántos puntos agrega una condena por abandonar el lugar de un choque?","o":["2 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Es una de las faltas más graves de la lista de puntos.","h2":"En Colorado, una condena por abandonar el lugar de un choque agrega 12 puntos, suficientes para suspender la licencia de cualquier conductor.","p":"Correcto. Abandonar el lugar del choque suma 12 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-063","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many points does a conviction for failing to stop for a school bus add?","o":["6 points","1 point","3 points","12 points"],"h1":"It is more than for a basic speeding ticket, but it does not reach 12.","h2":"In Colorado, failing to stop for a school bus adds 6 points to your driving record.","p":"Right. Not stopping for a school bus brings 6 points."},"es":{"q":"En Colorado, ¿cuántos puntos agrega una condena por no detenerse ante un autobús escolar?","o":["6 puntos","1 punto","3 puntos","12 puntos"],"h1":"Es más que una multa básica por velocidad, pero no llega a 12.","h2":"En Colorado, no detenerse ante un autobús escolar agrega 6 puntos a su historial de manejo.","p":"Correcto. No detenerse ante un autobús escolar suma 6 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-064","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, a teen driver breaks the passenger limit or the midnight to 5 a.m. limit. How many points can that add?","o":["None; it is only a warning","2 points","8 points","12 points"],"h1":"It is a small number, but it counts toward a teen's low suspension limit.","h2":"In Colorado, a teen convicted of breaking the young-passenger limit or the midnight to 5 a.m. limit gets 2 points on the driving record.","p":"Right. Breaking the teen passenger or night limit adds 2 points."},"es":{"q":"En Colorado, un conductor adolescente no respeta el límite de pasajeros o el horario de medianoche a 5 a. m. ¿Cuántos puntos puede sumar eso?","o":["Ninguno; solo es una advertencia","2 puntos","8 puntos","12 puntos"],"h1":"Es un número pequeño, pero cuenta para el límite bajo de suspensión de los adolescentes.","h2":"En Colorado, un adolescente condenado por no respetar el límite de pasajeros jóvenes o el horario de medianoche a 5 a. m. recibe 2 puntos en su historial de manejo.","p":"Correcto. Romper el límite de pasajeros o de horario nocturno suma 2 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-065","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many points can a reckless driving conviction add to your record?","o":["1 point","2 points","8 points","4 points"],"h1":"It is the same number as a first DWAI.","h2":"In Colorado, a reckless driving conviction can add 8 points to your driving record.","p":"Right. Reckless driving can bring 8 points."},"es":{"q":"En Colorado, ¿cuántos puntos puede agregar a su historial una condena por manejo imprudente (reckless driving)?","o":["1 punto","2 puntos","8 puntos","4 puntos"],"h1":"Es el mismo número que un primer DWAI.","h2":"En Colorado, una condena por manejo imprudente puede agregar 8 puntos a su historial de manejo.","p":"Correcto. El manejo imprudente puede sumar 8 puntos."},"ref":{"doc":"CO","page":23}},{"id":"co-066","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, what is the smallest fine for a first conviction of driving without insurance?","o":["$50","$100","$500","$5,000"],"h1":"It is a mandatory fine of several hundred dollars.","h2":"In Colorado, a first conviction for driving without insurance has a mandatory minimum fine of $500.","p":"Right. The minimum fine is $500."},"es":{"q":"En Colorado, ¿cuál es la multa mínima por una primera condena por manejar sin seguro?","o":["$50","$100","$500","$5,000"],"h1":"Es una multa obligatoria de varios cientos de dólares.","h2":"En Colorado, una primera condena por manejar sin seguro tiene una multa mínima obligatoria de $500.","p":"Correcto. La multa mínima es de $500."},"ref":{"doc":"CO","page":null}},{"id":"co-067","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, which of these can cause you to lose your driving privilege?","o":["Failing to pay ordered child support","Changing jobs within the state","Selling your car to a friend","Renewing your license by mail"],"h1":"It is a court order that has nothing to do with driving.","h2":"In Colorado, failing to pay court-ordered child support is one of the reasons your driving privilege can be suspended.","p":"Right. Unpaid ordered child support can cost you your license."},"es":{"q":"En Colorado, ¿cuál de estas cosas puede hacerle perder su privilegio de manejar?","o":["No pagar la manutención de hijos ordenada","Cambiar de trabajo dentro del estado","Vender su carro a un amigo","Renovar su licencia por correo"],"h1":"Es una orden judicial que no tiene que ver con manejar.","h2":"En Colorado, no pagar la manutención de hijos ordenada por un tribunal es una de las razones por las que se puede suspender su privilegio de manejar.","p":"Correcto. No pagar la manutención ordenada puede costarle la licencia."},"ref":{"doc":"CO","page":3}},{"id":"co-068","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, a 19-year-old is convicted of having alcohol while walking, not driving. What can happen to the driving privilege?","o":["Nothing, since no car was involved","It can be revoked","It is extended by one year","Only the car's registration is affected"],"h1":"For people under 21, driving does not have to be part of it.","h2":"In Colorado, a person under 21 convicted of buying or possessing alcohol can have the driving privilege revoked even if driving was not involved.","p":"Right. The privilege can be revoked even without driving."},"es":{"q":"En Colorado, una persona de 19 años es condenada por tener alcohol mientras caminaba, no manejaba. ¿Qué puede pasar con su privilegio de manejar?","o":["Nada, porque no había un carro","Se le puede revocar","Se le extiende un año","Solo se afecta el registro del carro"],"h1":"Para menores de 21 años, no hace falta que estuvieran manejando.","h2":"En Colorado, a una persona menor de 21 años condenada por comprar o tener alcohol se le puede revocar el privilegio de manejar aunque no estuviera manejando.","p":"Correcto. Se puede revocar aunque no manejara."},"ref":{"doc":"CO","page":4}},{"id":"co-069","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, a commercial (CDL) driver can have the license revoked for a blood alcohol level over what amount?","o":["0.02 percent","0.04 percent","0.08 percent","0.10 percent"],"h1":"It is half the usual adult limit.","h2":"In Colorado, a commercial driver's license may be revoked when the driver's blood alcohol level is over 0.04 percent.","p":"Right. For CDL drivers, the level is 0.04 percent."},"es":{"q":"En Colorado, ¿con qué nivel de alcohol en la sangre se le puede revocar la licencia a un conductor comercial (CDL)?","o":["Más de 0.02 por ciento","Más de 0.04 por ciento","Más de 0.08 por ciento","Más de 0.10 por ciento"],"h1":"Es la mitad del límite normal para adultos.","h2":"En Colorado, se puede revocar la licencia de un conductor comercial cuando su nivel de alcohol en la sangre es de más de 0.04 por ciento.","p":"Correcto. Para conductores CDL, el nivel es 0.04 por ciento."},"ref":{"doc":"CO","page":3}},{"id":"co-070","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, for a driver 21 or older, how long is the license revoked after a first DUI conviction?","o":["30 days","3 months","9 months","3 years"],"h1":"It is less than one year.","h2":"In Colorado, a first conviction for driving under the influence leads to a license revocation of 9 months for a driver 21 or older.","p":"Right. A first DUI means a 9-month revocation."},"es":{"q":"En Colorado, para un conductor de 21 años o más, ¿por cuánto tiempo se revoca la licencia después de una primera condena por DUI?","o":["30 días","3 meses","9 meses","3 años"],"h1":"Es menos de un año.","h2":"En Colorado, una primera condena por manejar bajo los efectos (DUI) causa una revocación de la licencia por 9 meses para un conductor de 21 años o más.","p":"Correcto. Un primer DUI significa 9 meses de revocación."},"ref":{"doc":"CO","page":4}},{"id":"co-071","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, after a driver refuses a chemical test, how long must the driver use an ignition interlock device?","o":["2 years","3 months","6 months","10 years"],"h1":"It is longer than the one-year revocation for refusing.","h2":"In Colorado, a driver who refuses a chemical test must have an ignition interlock device on any vehicle they drive for two years.","p":"Right. Refusing means two years with an interlock."},"es":{"q":"En Colorado, después de que un conductor se niega a una prueba química, ¿por cuánto tiempo debe usar un dispositivo de bloqueo de encendido?","o":["2 años","3 meses","6 meses","10 años"],"h1":"Es más largo que el año de revocación por negarse.","h2":"En Colorado, un conductor que se niega a una prueba química debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje por dos años.","p":"Correcto. Negarse significa dos años con el dispositivo de bloqueo."},"ref":{"doc":"CO","page":5}},{"id":"co-072","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, may you drive while wearing earphones that cover both ears?","o":["Yes, at any volume","Yes, if the music is quiet","No, it is not allowed","Yes, but only on highways"],"h1":"You need to hear sirens and horns around you.","h2":"In Colorado, you may not drive wearing earphones that cover both ears; hearing aids and a phone device in only one ear are allowed.","p":"Right. Earphones on both ears are not allowed."},"es":{"q":"En Colorado, ¿puede manejar con audífonos que cubren los dos oídos?","o":["Sí, a cualquier volumen","Sí, si la música está baja","No, no está permitido","Sí, pero solo en carreteras"],"h1":"Usted necesita oír las sirenas y bocinas a su alrededor.","h2":"En Colorado, no puede manejar con audífonos que cubren los dos oídos; se permiten los aparatos para la sordera y un dispositivo de teléfono en un solo oído.","p":"Correcto. No se permiten audífonos en los dos oídos."},"ref":{"doc":"CO","page":5}},{"id":"co-073","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, a driver age 18 or older is not wearing a seat belt. When can an officer give a ticket for it?","o":["Any time an officer notices it","Only after a stop for another violation","Only when driving on an interstate","Never; adults are exempt from it"],"h1":"For adult drivers, the seat belt law is enforced together with another offense.","h2":"In Colorado, a driver 18 or older can be ticketed for not wearing a seat belt only after being stopped for some other traffic violation.","p":"Right. For adults, it needs a stop for another violation first."},"es":{"q":"En Colorado, un conductor de 18 años o más no lleva el cinturón de seguridad. ¿Cuándo puede un agente darle una multa por eso?","o":["Cada vez que un agente lo note","Solo después de detenerlo por otra infracción","Solo cuando maneja en una interestatal","Nunca; los adultos están exentos de ella"],"h1":"Para conductores adultos, la ley del cinturón se aplica junto con otra falta.","h2":"En Colorado, a un conductor de 18 años o más solo se le puede multar por no usar el cinturón de seguridad después de detenerlo por otra infracción de tránsito.","p":"Correcto. Para los adultos, primero debe haber una parada por otra infracción."},"ref":{"doc":"CO","page":null}},{"id":"co-074","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, since January 1, 2025, children under what age must ride in a car seat or booster seat?","o":["Under 4","Under 6","Under 9","Under 13"],"h1":"The age was raised by one year in 2025.","h2":"In Colorado, since January 1, 2025, children under 9 years old must ride in a child car seat or booster seat that fits them.","p":"Right. Children under 9 need a car seat or booster."},"es":{"q":"En Colorado, desde el 1 de enero de 2025, ¿los niños menores de qué edad deben viajar en un asiento infantil o elevado?","o":["Menores de 4","Menores de 6","Menores de 9","Menores de 13"],"h1":"La edad subió un año en 2025.","h2":"En Colorado, desde el 1 de enero de 2025, los niños menores de 9 años deben viajar en un asiento infantil o asiento elevado adecuado para ellos.","p":"Correcto. Los niños menores de 9 años necesitan asiento infantil o elevado."},"ref":{"doc":"CO","page":null}},{"id":"co-075","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, how must a child under 2 years old who weighs less than 40 pounds ride?","o":["Rear-facing, in a back seat if possible","Forward-facing, in the front seat","On an adult's lap, with a belt","In a booster seat, in any seat"],"h1":"Babies and toddlers face the back of the car.","h2":"In Colorado, a child under 2 who weighs less than 40 pounds must ride in a rear-facing car seat, in a back seat if the vehicle has one.","p":"Right. Under 2 and under 40 pounds means rear-facing, in the back."},"es":{"q":"En Colorado, ¿cómo debe viajar un niño menor de 2 años que pesa menos de 40 libras?","o":["Mirando hacia atrás, en un asiento trasero si es posible","Mirando hacia adelante, en el asiento delantero","En las piernas de un adulto, con cinturón","En un asiento elevado, en cualquier lugar"],"h1":"Los bebés y niños pequeños miran hacia la parte trasera del carro.","h2":"En Colorado, un niño menor de 2 años que pesa menos de 40 libras debe viajar en un asiento infantil mirando hacia atrás, en un asiento trasero si el vehículo lo tiene.","p":"Correcto. Menor de 2 años y de 40 libras: mirando hacia atrás, en el asiento trasero."},"ref":{"doc":"CO","page":null}},{"id":"co-076","scope":"CO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Colorado, a highway maintenance vehicle at work is flashing yellow and blue lights. What must you do?","o":["Yield the right-of-way to it","Pass it quickly on the right","Honk so the driver sees you","Follow close behind it"],"h1":"These lights mean the crew is working on the road.","h2":"In Colorado, you must yield the right-of-way to service and maintenance vehicles that are working with flashing yellow and blue lights, and use extra care near them.","p":"Right. Yield to working maintenance vehicles."},"es":{"q":"En Colorado, un vehículo de mantenimiento de carreteras está trabajando con luces amarillas y azules intermitentes. ¿Qué debe hacer?","o":["Cederle el paso","Rebasarlo rápido por la derecha","Tocar la bocina para que lo vea","Seguirlo muy de cerca"],"h1":"Estas luces significan que el equipo está trabajando en la carretera.","h2":"En Colorado, usted debe ceder el paso a los vehículos de servicio y mantenimiento que trabajan con luces amarillas y azules intermitentes, y tener mucho cuidado cerca de ellos.","p":"Correcto. Ceda el paso a los vehículos de mantenimiento que trabajan."},"ref":{"doc":"CO","page":11}},{"id":"co-077","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, a transit bus is signaling to pull into your lane, and the yield sign on its back is lit. What must you do?","o":["Speed up to pass it first","Honk and keep going","Move onto the shoulder","Yield and let the bus enter"],"h1":"The lit sign on the bus is speaking to you.","h2":"In Colorado, you must yield to a transit bus that is signaling to enter a traffic lane when the yield sign on the back of the bus is lit.","p":"Right. Let the bus enter the lane."},"es":{"q":"En Colorado, un autobús de transporte público señala que va a entrar a su carril y la señal de ceder el paso en su parte trasera está encendida. ¿Qué debe hacer?","o":["Acelerar para pasar primero","Tocar la bocina y seguir","Moverse al acotamiento","Ceder el paso y dejar entrar al autobús"],"h1":"La señal encendida del autobús le habla a usted.","h2":"En Colorado, usted debe ceder el paso a un autobús de transporte público que señala para entrar a un carril cuando la señal de ceder el paso en la parte trasera del autobús está encendida.","p":"Correcto. Deje que el autobús entre al carril."},"ref":{"doc":"CO","page":11}},{"id":"co-078","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, what happens to the fine if you speed in a marked work zone?","o":["It is cut in half","It stays the same","It is doubled","It is replaced by a warning"],"h1":"Fines are higher where workers are on the road.","h2":"In Colorado, speeding in a work or construction zone can bring double fines.","p":"Right. Work zone speeding fines are doubled."},"es":{"q":"En Colorado, ¿qué pasa con la multa si usted maneja con exceso de velocidad en una zona de trabajo señalizada?","o":["Se reduce a la mitad","Queda igual","Se duplica","Se cambia por una advertencia"],"h1":"Las multas son más altas donde hay trabajadores en la carretera.","h2":"En Colorado, exceder la velocidad en una zona de trabajo o construcción puede traer multas dobles.","p":"Correcto. Las multas por velocidad en zonas de trabajo se duplican."},"ref":{"doc":"CO","page":11}},{"id":"co-079","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, if no sign says otherwise, what is the speed limit on an open mountain highway?","o":["40 mph","30 mph","55 mph","65 mph"],"h1":"It is higher than on winding mountain curves, but lower than on urban highways.","h2":"In Colorado, unless a sign shows a different limit, the speed limit on open mountain highways is 40 mph.","p":"Right. Open mountain highways are 40 mph unless posted."},"es":{"q":"En Colorado, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una carretera de montaña abierta?","o":["40 mph","30 mph","55 mph","65 mph"],"h1":"Es más alto que en las curvas cerradas de montaña, pero más bajo que en las carreteras urbanas.","h2":"En Colorado, a menos que una señal indique otro límite, el límite de velocidad en las carreteras de montaña abiertas es de 40 mph.","p":"Correcto. Las carreteras de montaña abiertas son de 40 mph si no hay señal."},"ref":{"doc":"CO","page":12}},{"id":"co-080","scope":"CO","cat":"signals","sign":null,"c":3,"en":{"q":"In Colorado, in a city or town, how far ahead must you keep your turn signal on before turning or changing lanes?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"It is half the distance required on fast four-lane highways.","h2":"In Colorado, in urban areas you must signal continuously for 100 feet before you turn or change lanes.","p":"Right. In town, signal for 100 feet."},"es":{"q":"En Colorado, en una ciudad o pueblo, ¿con cuánta distancia debe mantener la direccional encendida antes de girar o cambiar de carril?","o":["10 pies","25 pies","50 pies","100 pies"],"h1":"Es la mitad de la distancia exigida en carreteras rápidas de cuatro carriles.","h2":"En Colorado, en zonas urbanas usted debe señalar sin parar durante 100 pies antes de girar o cambiar de carril.","p":"Correcto. En la ciudad, señale por 100 pies."},"ref":{"doc":"CO","page":12}},{"id":"co-081","scope":"CO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Colorado, when you parallel park, how close to the curb must your car be?","o":["Within 12 inches","Within 24 inches","Within 36 inches","Within 48 inches"],"h1":"It is about one foot.","h2":"In Colorado, when you parallel park, your vehicle must be within 12 inches of the curb, or as close as possible to the edge of the shoulder.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En Colorado, cuando usted se estaciona en paralelo, ¿qué tan cerca de la acera debe quedar su carro?","o":["A 12 pulgadas o menos","A 24 pulgadas o menos","A 36 pulgadas o menos","A 48 pulgadas o menos"],"h1":"Es más o menos un pie.","h2":"En Colorado, cuando usted se estaciona en paralelo, su vehículo debe quedar a 12 pulgadas o menos de la acera, o lo más cerca posible del borde del acotamiento.","p":"Correcto. Estaciónese a 12 pulgadas o menos de la acera."},"ref":{"doc":"CO","page":13}},{"id":"co-082","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, on which of these roads may you pass another car on the right?","o":["A two-lane road, using the shoulder","Any road, if the car ahead is slow","A curve, if you can see ahead","A road with two or more lanes each way"],"h1":"There must be a full marked lane for you on the right.","h2":"In Colorado, you may pass on the right on one-way streets and on roads with two or more lanes in each direction, but never by driving on the shoulder or off the pavement.","p":"Right. Pass on the right only where there are enough marked lanes."},"es":{"q":"En Colorado, ¿en cuál de estas vías puede rebasar a otro carro por la derecha?","o":["Una vía de dos carriles, usando el acotamiento","Cualquier vía, si el carro de adelante va lento","Una curva, si puede ver adelante","Una vía con dos o más carriles en cada sentido"],"h1":"Debe haber un carril completo marcado para usted a la derecha.","h2":"En Colorado, usted puede rebasar por la derecha en calles de un solo sentido y en vías con dos o más carriles en cada sentido, pero nunca manejando por el acotamiento o fuera del pavimento.","p":"Correcto. Rebase por la derecha solo donde haya suficientes carriles marcados."},"ref":{"doc":"CO","page":15}},{"id":"co-083","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, you may not pass another vehicle within how many feet of an intersection or railroad crossing?","o":["25 feet","100 feet","500 feet","1,000 feet"],"h1":"It is about the length of a few houses.","h2":"In Colorado, it is illegal to pass within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Colorado, ¿a cuántos pies de una intersección o un cruce de tren no puede rebasar a otro vehículo?","o":["25 pies","100 pies","500 pies","1,000 pies"],"h1":"Es más o menos el largo de unas pocas casas.","h2":"En Colorado, es ilegal rebasar a menos de 100 pies de una intersección o de un cruce de tren.","p":"Correcto. No rebase a menos de 100 pies de una intersección o cruce de tren."},"ref":{"doc":"CO","page":15}},{"id":"co-084","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, when you pass on a two-lane road, you must be back in your lane before you come within how many feet of an oncoming vehicle?","o":["20 feet","50 feet","200 feet","2,000 feet"],"h1":"It is the same distance as the turn signal rule on fast four-lane highways.","h2":"In Colorado, do not pass unless you can return to the right side before coming within 200 feet of an oncoming vehicle, including a bicyclist.","p":"Right. Get back in your lane before you are within 200 feet of oncoming traffic."},"es":{"q":"En Colorado, cuando usted rebasa en una vía de dos carriles, ¿antes de llegar a cuántos pies de un vehículo que viene de frente debe estar de vuelta en su carril?","o":["20 pies","50 pies","200 pies","2,000 pies"],"h1":"Es la misma distancia que la regla de la direccional en carreteras rápidas de cuatro carriles.","h2":"En Colorado, no rebase a menos que pueda volver al lado derecho antes de llegar a 200 pies de un vehículo que viene de frente, incluido un ciclista.","p":"Correcto. Vuelva a su carril antes de estar a 200 pies del tránsito que viene de frente."},"ref":{"doc":"CO","page":15}},{"id":"co-085","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, your car is parked along the side of the road after sunset. Which lights must be on?","o":["No lights at all","The parking lights","The high beams","Only the inside dome light"],"h1":"Other drivers must be able to see your parked car in the dark.","h2":"In Colorado, a vehicle parked along the roadway, attended or not, must have its parking lights on from sunset to sunrise or when you cannot see clearly for 1,000 feet.","p":"Right. Turn on the parking lights."},"es":{"q":"En Colorado, su carro está estacionado al lado de la vía después de la puesta del sol. ¿Qué luces deben estar encendidas?","o":["Ninguna luz","Las luces de estacionamiento","Las luces altas","Solo la luz interior"],"h1":"Los demás conductores deben poder ver su carro estacionado en la oscuridad.","h2":"En Colorado, un vehículo estacionado al lado de la vía, con o sin alguien adentro, debe tener encendidas las luces de estacionamiento desde la puesta hasta la salida del sol o cuando no se puede ver con claridad a 1,000 pies.","p":"Correcto. Encienda las luces de estacionamiento."},"ref":{"doc":"CO","page":16}},{"id":"co-086","scope":"CO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Colorado, on a four-lane road with no median, a school bus in the opposite lanes stops with red lights flashing. What must you do?","o":["Keep going; it is across the road","Stop; both directions must stop","Slow to 20 mph and pass","Stop only if you see children"],"h1":"Without a median, the other side of the road is not protected.","h2":"In Colorado, on a four-lane road without a median, traffic in both directions must stop for a school bus with flashing red lights.","p":"Right. With no median, both directions stop."},"es":{"q":"En Colorado, en una vía de cuatro carriles sin camellón, un autobús escolar en los carriles del sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Seguir; está al otro lado de la vía","Detenerse; los dos sentidos deben parar","Bajar a 20 mph y pasar","Detenerse solo si ve niños"],"h1":"Sin camellón, el otro lado de la vía no está protegido.","h2":"En Colorado, en una vía de cuatro carriles sin camellón, el tránsito de los dos sentidos debe detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. Sin camellón, se detienen los dos sentidos."},"ref":{"doc":"CO","page":20}},{"id":"co-087","scope":"CO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Colorado, since 2022, how may a bicycle rider age 15 or older treat a stop sign when the intersection is clear?","o":["Like a yield sign","Like a green light","As a sign for cars only","Like a no-entry sign"],"h1":"The rider may slow down instead of making a full stop.","h2":"In Colorado, since 2022, when the intersection is clear and the rider already has the right-of-way, a bicycle rider age 15 or older may treat a stop sign as a yield sign.","p":"Right. Older bicycle riders may treat a stop sign like a yield sign."},"es":{"q":"En Colorado, desde 2022, ¿cómo puede tratar una señal de alto un ciclista de 15 años o más cuando la intersección está libre?","o":["Como una señal de ceder el paso","Como una luz verde","Como una señal solo para carros","Como una señal de no entrar"],"h1":"El ciclista puede bajar la velocidad en vez de detenerse por completo.","h2":"En Colorado, desde 2022, cuando la intersección está libre y el ciclista ya tiene el derecho de paso, un ciclista de 15 años o más puede tratar una señal de alto como una señal de ceder el paso.","p":"Correcto. Los ciclistas mayores pueden tratar el alto como ceder el paso."},"ref":{"doc":"CO","page":22}},{"id":"co-088","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, which number can you dial from a cell phone to report an aggressive driver to the State Patrol?","o":["*277 (*CSP)","411","*511","311"],"h1":"The number spells the letters of the Colorado State Patrol.","h2":"In Colorado, you can dial *CSP, which is *277, from a cell phone to report an aggressive driver to the Colorado State Patrol, and the call is free.","p":"Right. Dial *277 to report aggressive drivers."},"es":{"q":"En Colorado, ¿a qué número puede marcar desde un celular para reportar a un conductor agresivo a la Patrulla Estatal?","o":["*277 (*CSP)","411","*511","311"],"h1":"El número forma las letras de la Patrulla Estatal de Colorado (CSP).","h2":"En Colorado, usted puede marcar *CSP, es decir *277, desde un celular para reportar a un conductor agresivo a la Patrulla Estatal de Colorado, y la llamada es gratis.","p":"Correcto. Marque *277 para reportar conductores agresivos."},"ref":{"doc":"CO","page":24}},{"id":"co-089","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, after a crash with injuries, the driver is physically unable to report it. What must a passenger do?","o":["Nothing; only drivers report","Leave and call the next day","Wait for the insurer to call","Report the crash"],"h1":"Someone in the car still has the duty.","h2":"In Colorado, if the driver in an injury crash is physically unable to report it, a passenger must report the crash and stay at the scene if police say to.","p":"Right. The passenger must report the crash."},"es":{"q":"En Colorado, después de un choque con heridos, el conductor no puede reportarlo por su estado físico. ¿Qué debe hacer un pasajero?","o":["Nada; solo los conductores reportan","Irse y llamar al día siguiente","Esperar a que llame la aseguradora","Reportar el choque"],"h1":"Alguien en el carro todavía tiene esa obligación.","h2":"En Colorado, si el conductor en un choque con heridos no puede reportarlo por su estado físico, un pasajero debe reportar el choque y quedarse en el lugar si la policía lo indica.","p":"Correcto. El pasajero debe reportar el choque."},"ref":{"doc":"CO","page":25}},{"id":"co-090","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, during Accident Alert status, you have a minor crash with no injuries, no alcohol or drugs, and drivable cars. When must you file a report with law enforcement?","o":["Within 30 days","Within 7 days","No report is needed","Within 24 hours"],"h1":"Police are too busy to come, but you still report soon.","h2":"In Colorado, during Accident Alert status, drivers in a minor crash exchange information and must file an accident report with law enforcement within 24 hours.","p":"Right. File the report within 24 hours."},"es":{"q":"En Colorado, durante el estado de Alerta de Accidentes, usted tiene un choque menor sin heridos, sin alcohol ni drogas, y con carros que se pueden manejar. ¿Cuándo debe presentar un reporte a la policía?","o":["Dentro de 30 días","Dentro de 7 días","No hace falta reporte","Dentro de 24 horas"],"h1":"La policía está muy ocupada para venir, pero igual debe reportar pronto.","h2":"En Colorado, durante el estado de Alerta de Accidentes, los conductores en un choque menor intercambian datos y deben presentar un reporte del accidente a la policía dentro de 24 horas.","p":"Correcto. Presente el reporte dentro de 24 horas."},"ref":{"doc":"CO","page":25}},{"id":"co-091","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, how close to a crosswalk at an intersection may you park?","o":["Right up to its edge","No closer than 5 feet","No closer than 10 feet","No closer than 20 feet"],"h1":"Drivers turning the corner need to see people starting to cross.","h2":"In Colorado, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Colorado, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["Justo hasta el borde","No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies"],"h1":"Los conductores que dan la vuelta en la esquina deben ver a quienes empiezan a cruzar.","h2":"En Colorado, usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Manténgase al menos a 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"CO","page":null}},{"id":"co-092","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, who may be in the car during your driving skills test?","o":["You, the examiner and one parent","You, the examiner and an interpreter","Only you and the examiner","Anyone who has a seat belt"],"h1":"For safety, the car is kept as empty as possible.","h2":"In Colorado, only the driver and the examiner may be in the vehicle during the drive test; family, friends, interpreters and pets are not allowed.","p":"Right. Only you and the examiner ride during the test."},"es":{"q":"En Colorado, ¿quién puede estar en el carro durante su examen práctico de manejo?","o":["Usted, el examinador y uno de sus padres","Usted, el examinador y un intérprete","Solo usted y el examinador","Cualquier persona que tenga cinturón"],"h1":"Por seguridad, el carro va lo más vacío posible.","h2":"En Colorado, solo el conductor y el examinador pueden estar en el vehículo durante el examen de manejo; no se permiten familiares, amigos, intérpretes ni mascotas.","p":"Correcto. Solo usted y el examinador van en el carro durante el examen."},"ref":{"doc":"CO","page":1}},{"id":"co-093","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, may a driver charged with an alcohol or drug driving offense plea bargain it down to a lesser charge?","o":["No, the law does not allow it","Yes, on a first offense only","Yes, if no one was hurt","Yes, if the driver is under 21"],"h1":"Colorado treats these offenses very strictly.","h2":"In Colorado, the law does not allow a person to plea bargain out of an alcohol or drug related driving offense.","p":"Right. No plea bargain out of an alcohol or drug driving offense."},"es":{"q":"En Colorado, ¿puede un conductor acusado de un delito de manejo con alcohol o drogas negociar un cargo menor?","o":["No, la ley no lo permite","Sí, solo en la primera vez","Sí, si nadie resultó herido","Sí, si el conductor es menor de 21 años"],"h1":"Colorado trata estos delitos de manera muy estricta.","h2":"En Colorado, la ley no permite que una persona negocie para salir de un delito de manejo relacionado con alcohol o drogas.","p":"Correcto. No se puede negociar para salir de un delito de manejo con alcohol o drogas."},"ref":{"doc":"CO","page":5}},{"id":"co-094","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, a driver used marijuana for a medical reason and is charged with DUI. Is the medical use a defense?","o":["Yes, with a doctor's note","Yes, if the dose was small","Yes, on a first offense","No, it is not a defense"],"h1":"The law looks at whether you were impaired, not why you used the drug.","h2":"In Colorado, using marijuana or another drug for medical purposes is not a defense to a DUI or DWAI charge.","p":"Right. Medical use is not a defense to impaired driving."},"es":{"q":"En Colorado, un conductor usó marihuana por razones médicas y lo acusan de DUI. ¿El uso médico es una defensa?","o":["Sí, con una nota del médico","Sí, si la dosis fue pequeña","Sí, en la primera vez","No, no es una defensa"],"h1":"La ley mira si usted estaba afectado, no por qué usó la droga.","h2":"En Colorado, usar marihuana u otra droga con fines médicos no es una defensa contra un cargo de DUI o DWAI.","p":"Correcto. El uso médico no es una defensa por manejar bajo los efectos."},"ref":{"doc":"CO","page":4}},{"id":"co-095","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, what is the fine range for a first DUI conviction for a driver 21 or older?","o":["$50 to $150","$600 to $1,000","$5,000 to $10,000","$200 to $300"],"h1":"It is higher than the fine for a first DWAI.","h2":"In Colorado, a first DUI conviction for a driver 21 or older carries a fine of $600 to $1,000, along with other penalties.","p":"Right. A first DUI fine is $600 to $1,000."},"es":{"q":"En Colorado, ¿cuál es el rango de la multa por una primera condena por DUI para un conductor de 21 años o más?","o":["De $50 a $150","De $600 a $1,000","De $5,000 a $10,000","De $200 a $300"],"h1":"Es más alta que la multa por un primer DWAI.","h2":"En Colorado, una primera condena por DUI para un conductor de 21 años o más tiene una multa de $600 a $1,000, además de otras sanciones.","p":"Correcto. La multa por un primer DUI es de $600 a $1,000."},"ref":{"doc":"CO","page":4}},{"id":"co-096","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, for a driver 21 or older, how long is the license revoked after a second DWAI or DUI conviction?","o":["30 days","6 months","1 year","10 years"],"h1":"It is longer than the revocation for a first DUI.","h2":"In Colorado, a second DWAI or DUI conviction for a driver 21 or older leads to a license revocation of one year.","p":"Right. A second DWAI or DUI means a one-year revocation."},"es":{"q":"En Colorado, para un conductor de 21 años o más, ¿por cuánto tiempo se revoca la licencia después de una segunda condena por DWAI o DUI?","o":["30 días","6 meses","1 año","10 años"],"h1":"Es más largo que la revocación por un primer DUI.","h2":"En Colorado, una segunda condena por DWAI o DUI para un conductor de 21 años o más lleva a una revocación de la licencia por un año.","p":"Correcto. Un segundo DWAI o DUI significa una revocación de un año."},"ref":{"doc":"CO","page":4}},{"id":"co-097","scope":"CO","cat":"signals","sign":null,"c":0,"en":{"q":"In Colorado, you reach an intersection where the traffic signal is not working. What should you do?","o":["Treat it as a four-way stop","Drive through if no one is close","Yield only to cars on your left","Turn on your hazard lights and go"],"h1":"Everyone takes turns, as at a stop sign.","h2":"In Colorado, if a traffic signal is not operating or is malfunctioning, you must treat the intersection as a four-way stop.","p":"Right. A broken signal means a four-way stop."},"es":{"q":"En Colorado, usted llega a una intersección donde el semáforo no funciona. ¿Qué debe hacer?","o":["Tratarla como un alto en cuatro direcciones","Pasar si no hay nadie cerca","Ceder el paso solo a los carros a su izquierda","Prender las luces intermitentes y seguir"],"h1":"Todos toman turnos, como en una señal de alto.","h2":"En Colorado, si un semáforo no funciona o funciona mal, usted debe tratar la intersección como un alto en cuatro direcciones.","p":"Correcto. Un semáforo dañado significa un alto en cuatro direcciones."},"ref":{"doc":"CO","page":7}},{"id":"co-098","scope":"CO","cat":"signals","sign":null,"c":3,"en":{"q":"In Colorado, a vehicle ahead has a reflective orange triangle on the back. What does it tell you?","o":["It carries hazardous materials","It is a police vehicle","It is driven by a student driver","It is built to go slower than 25 mph"],"h1":"Farm tractors often have this sign.","h2":"In Colorado, a reflective orange triangle on the rear of a vehicle means it is designed to travel slower than 25 miles per hour.","p":"Right. The orange triangle marks a slow-moving vehicle."},"es":{"q":"En Colorado, un vehículo adelante tiene un triángulo anaranjado reflectante atrás. ¿Qué le indica?","o":["Lleva materiales peligrosos","Es un vehículo de la policía","Lo maneja un estudiante de manejo","Está hecho para ir a menos de 25 mph"],"h1":"Los tractores de granja muchas veces tienen esta señal.","h2":"En Colorado, un triángulo anaranjado reflectante en la parte de atrás de un vehículo significa que está diseñado para ir a menos de 25 millas por hora.","p":"Correcto. El triángulo anaranjado marca un vehículo lento."},"ref":{"doc":"CO","page":8}},{"id":"co-099","scope":"CO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Colorado, a bike lane stops being painted where it crosses an intersection. Does the bike lane continue?","o":["No, it ends where the paint ends","Yes, it continues through the intersection","Only where a sign marks the lane","Only during the daylight hours"],"h1":"The paint is not what makes the lane.","h2":"In Colorado, a bike lane extends through an intersection whether or not the paint connects the lane on both sides.","p":"Right. The bike lane goes on through the intersection."},"es":{"q":"En Colorado, la pintura de un carril para bicicletas se interrumpe donde cruza una intersección. ¿Sigue el carril para bicicletas?","o":["No, termina donde acaba la pintura","Sí, sigue a través de la intersección","Solo donde una señal marca el carril","Solo durante las horas del día"],"h1":"La pintura no es lo que crea el carril.","h2":"En Colorado, un carril para bicicletas sigue a través de una intersección, aunque la pintura no una el carril de ambos lados.","p":"Correcto. El carril para bicicletas sigue a través de la intersección."},"ref":{"doc":"CO","page":9}},{"id":"co-100","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, when may a car drive into a bike lane?","o":["To pass a slow car on the right","To wait for a parking space","To cross it when turning or using a driveway","Any time no bicycle is in sight"],"h1":"You may only go through it, not use it as a lane.","h2":"In Colorado, drivers may not drive, stop or park in a bike lane, but may cross it when turning or when entering or leaving a road, driveway or alley.","p":"Right. Only cross a bike lane to turn or reach a driveway or alley."},"es":{"q":"En Colorado, ¿cuándo puede un carro entrar en un carril para bicicletas?","o":["Para rebasar a un carro lento por la derecha","Para esperar un espacio de estacionamiento","Para cruzarlo al dar vuelta o usar una entrada","Siempre que no se vea ninguna bicicleta"],"h1":"Solo puede atravesarlo, no usarlo como carril.","h2":"En Colorado, los conductores no pueden manejar, detenerse ni estacionarse en un carril para bicicletas, pero pueden cruzarlo al dar vuelta o al entrar o salir de una calle, una entrada de carros o un callejón.","p":"Correcto. Solo cruce un carril para bicicletas para dar vuelta o llegar a una entrada o callejón."},"ref":{"doc":"CO","page":22}},{"id":"co-101","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, at night you are following another vehicle. Within how many feet of it must you use low beams?","o":["200 feet","50 feet","1,000 feet","1 mile"],"h1":"It is less than the distance for an oncoming car.","h2":"In Colorado, when you follow another vehicle at night, you must use low beams, with fog lights off, within 200 feet of the vehicle ahead.","p":"Right. Use low beams within 200 feet of the car ahead."},"es":{"q":"En Colorado, de noche usted va detrás de otro vehículo. ¿A cuántos pies de él debe usar las luces bajas?","o":["200 pies","50 pies","1,000 pies","1 milla"],"h1":"Es menos que la distancia para un carro que viene de frente.","h2":"En Colorado, cuando usted sigue a otro vehículo de noche, debe usar las luces bajas, con los faros de niebla apagados, a menos de 200 pies del vehículo de adelante.","p":"Correcto. Use las luces bajas a menos de 200 pies del carro de adelante."},"ref":{"doc":"CO","page":16}},{"id":"co-102","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, an officer gives you a traffic ticket. What can happen if you refuse to sign it?","o":["The ticket is canceled","The fine is cut in half","Nothing at all happens","You may be arrested"],"h1":"Signing is not the same as saying you are guilty.","h2":"In Colorado, signing a traffic ticket is not an admission of guilt, but refusing to sign it may result in your arrest.","p":"Right. Refusing to sign a ticket can lead to arrest."},"es":{"q":"En Colorado, un oficial le da una multa de tránsito. ¿Qué puede pasar si usted se niega a firmarla?","o":["Se cancela la multa","La multa se reduce a la mitad","No pasa nada","Lo pueden arrestar"],"h1":"Firmar no es lo mismo que decir que es culpable.","h2":"En Colorado, firmar una multa de tránsito no es admitir la culpa, pero negarse a firmarla puede resultar en su arresto.","p":"Correcto. Negarse a firmar una multa puede llevar a un arresto."},"ref":{"doc":"CO","page":19}},{"id":"co-103","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, may you stop on a runaway truck ramp to put on tire chains?","o":["Yes, if your hazard lights are on","No, it is illegal and unsafe","Yes, but only during a storm","Yes, if no truck is in sight"],"h1":"The ramp must stay clear for a truck that cannot stop.","h2":"In Colorado, you must never chain up, change a tire or park on a runaway truck ramp or its entrance; it is illegal and unsafe.","p":"Right. Never stop on a runaway truck ramp."},"es":{"q":"En Colorado, ¿puede detenerse en una rampa de frenado de emergencia para camiones para ponerle cadenas a las llantas?","o":["Sí, si tiene las luces intermitentes prendidas","No, es ilegal y peligroso","Sí, pero solo durante una tormenta","Sí, si no se ve ningún camión"],"h1":"La rampa debe estar libre para un camión que no puede frenar.","h2":"En Colorado, nunca debe poner cadenas, cambiar una llanta ni estacionarse en una rampa de frenado de emergencia para camiones ni en su entrada; es ilegal y peligroso.","p":"Correcto. Nunca se detenga en una rampa de frenado de emergencia."},"ref":{"doc":"CO","page":19}},{"id":"co-104","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, you are on a highway with five or more lanes and a shared center turn lane. A school bus going the other way stops with red lights flashing. What must you do?","o":["Stop at least 20 feet away","Stop until the stop arm is pulled in","You do not have to stop","Pull onto the right shoulder"],"h1":"On a road this wide, only traffic behind the bus must stop.","h2":"In Colorado, on a highway with five or more lanes and a shared center turn lane, only traffic behind the school bus must stop; vehicles going the opposite way are not required to stop.","p":"Right. Opposite traffic does not have to stop on that kind of road."},"es":{"q":"En Colorado, usted va por una carretera con cinco carriles o más y un carril central compartido para dar vuelta. Un autobús escolar que va en sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse al menos a 20 pies","Detenerse hasta que guarden el brazo de alto","No tiene que detenerse","Salirse al acotamiento derecho"],"h1":"En una carretera tan ancha, solo el tráfico detrás del autobús debe detenerse.","h2":"En Colorado, en una carretera con cinco carriles o más y un carril central compartido para dar vuelta, solo el tráfico detrás del autobús escolar debe detenerse; los vehículos en sentido contrario no tienen que detenerse.","p":"Correcto. El tráfico en sentido contrario no tiene que detenerse en ese tipo de carretera."},"ref":{"doc":"CO","page":20}},{"id":"co-105","scope":"CO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Colorado, when may bicyclists ride side by side on the road?","o":["Never on any public road","Only on roads with a bike lane","Only on Sundays and holidays","When they do not block normal traffic"],"h1":"Riding side by side can make a group easier to see.","h2":"In Colorado, bicyclists may ride side by side as long as they do not impede the normal and reasonable movement of traffic.","p":"Right. Bicyclists may ride side by side if they do not block normal traffic."},"es":{"q":"En Colorado, ¿cuándo pueden los ciclistas ir uno al lado del otro en la calle?","o":["Nunca en una vía pública","Solo en calles con carril para bicicletas","Solo los domingos y días feriados","Cuando no bloquean el tráfico normal"],"h1":"Ir uno al lado del otro puede hacer que un grupo se vea mejor.","h2":"En Colorado, los ciclistas pueden ir uno al lado del otro siempre que no impidan el movimiento normal y razonable del tráfico.","p":"Correcto. Los ciclistas pueden ir lado a lado si no bloquean el tráfico normal."},"ref":{"doc":"CO","page":22}},{"id":"co-106","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, which adult front-seat passenger does not have to wear a seat belt?","o":["One with a doctor's written statement","One who is riding less than a mile","One who is sitting in a truck","One who is over age 65"],"h1":"The exception needs paperwork from a physician.","h2":"In Colorado, a person with a written statement from a physician saying they cannot wear a seat belt for physical or psychological reasons is exempt from the seat belt law.","p":"Right. A doctor's written statement is one of the few exceptions."},"es":{"q":"En Colorado, ¿qué pasajero adulto del asiento delantero no tiene que usar el cinturón de seguridad?","o":["Uno con una declaración escrita de un médico","Uno que viaja menos de una milla","Uno que va sentado en una camioneta","Uno que tiene más de 65 años"],"h1":"La excepción necesita un documento de un médico.","h2":"En Colorado, una persona con una declaración escrita de un médico que diga que no puede usar el cinturón por razones físicas o psicológicas está exenta de la ley del cinturón.","p":"Correcto. Una declaración escrita de un médico es una de las pocas excepciones."},"ref":{"doc":"CO","page":3}},{"id":"co-107","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, after a crash, to whom must you provide proof of insurance?","o":["Only to your own insurance company","To law enforcement at the scene or the police station","Only to the DMV within one year","To anyone who stops to help you"],"h1":"The officers handling the crash will ask for it.","h2":"In Colorado, if you are in a crash, you must provide proof of insurance to law enforcement at the scene or at the police station.","p":"Right. Show proof of insurance to law enforcement."},"es":{"q":"En Colorado, después de un choque, ¿a quién debe presentar el comprobante de seguro?","o":["Solo a su propia compañía de seguros","A la policía en el lugar o en la estación de policía","Solo al DMV dentro de un año","A cualquier persona que se detenga a ayudar"],"h1":"Los oficiales que atienden el choque se lo van a pedir.","h2":"En Colorado, si usted tiene un choque, debe presentar el comprobante de seguro a la policía en el lugar del choque o en la estación de policía.","p":"Correcto. Muestre el comprobante de seguro a la policía."},"ref":{"doc":"CO","page":25}},{"id":"co-108","scope":"CO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Colorado, you may not pass within 100 feet of which of these when your view is blocked?","o":["A gas station","A rest area","A school parking lot","A bridge, viaduct or tunnel"],"h1":"Think of narrow structures where the road has no room to escape.","h2":"In Colorado, you must not pass within 100 feet of any bridge, viaduct or tunnel when your view is obstructed.","p":"Right. No passing within 100 feet of a bridge, viaduct or tunnel when you cannot see ahead."},"es":{"q":"En Colorado, ¿no puede rebasar a menos de 100 pies de cuál de estos cuando su vista está bloqueada?","o":["Una gasolinera","Un área de descanso","Un estacionamiento escolar","Un puente, viaducto o túnel"],"h1":"Piense en estructuras angostas donde no hay espacio para escapar.","h2":"En Colorado, usted no debe rebasar a menos de 100 pies de un puente, viaducto o túnel cuando su vista está bloqueada.","p":"Correcto. No rebase a menos de 100 pies de un puente, viaducto o túnel si no puede ver adelante."},"ref":{"doc":"CO","page":15}},{"id":"co-109","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, what appears on the front of your license if you sign up as an organ donor?","o":["A heart with a \"Y\"","A red cross","A blue star","The letters OD"],"h1":"It is a symbol of love with a letter for \"yes\".","h2":"In Colorado, if you say yes to organ, eye and tissue donation, a heart with a \"Y\" appears on the front of your license, permit or ID.","p":"Right. A heart with a \"Y\" shows you are a donor."},"es":{"q":"En Colorado, ¿qué aparece en el frente de su licencia si se registra como donante de órganos?","o":["Un corazón con una \"Y\"","Una cruz roja","Una estrella azul","Las letras OD"],"h1":"Es un símbolo de amor con una letra que significa \"sí\" en inglés.","h2":"En Colorado, si usted acepta donar órganos, ojos y tejidos, aparece un corazón con una \"Y\" en el frente de su licencia, permiso o identificación.","p":"Correcto. Un corazón con una \"Y\" muestra que usted es donante."},"ref":{"doc":"CO","page":26}},{"id":"co-110","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, you have a family member's disabled parking placard. When may you park in a disabled space with it?","o":["Any time the placard is in the car","When you are only stopping briefly","When the placard owner is getting in or out","When all other spaces are full"],"h1":"The placard belongs to a person, not to the car.","h2":"In Colorado, to park in a disabled parking space, the person who owns the placard must be entering or exiting the vehicle.","p":"Right. The placard owner must be getting in or out of the car."},"es":{"q":"En Colorado, usted tiene el permiso de estacionamiento para discapacitados de un familiar. ¿Cuándo puede estacionarse con él en un espacio para discapacitados?","o":["Siempre que el permiso esté en el carro","Cuando se detiene solo un momento","Cuando el dueño del permiso sube o baja","Cuando todos los otros espacios están llenos"],"h1":"El permiso pertenece a una persona, no al carro.","h2":"En Colorado, para estacionarse en un espacio para discapacitados, la persona dueña del permiso debe estar subiendo o bajando del vehículo.","p":"Correcto. El dueño del permiso debe estar subiendo o bajando del carro."},"ref":{"doc":"CO","page":9}},{"id":"co-111","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, how many points does a ticket for driving 20 to 39 mph over the speed limit add?","o":["2 points","6 points","10 points","1 point"],"h1":"It is more than for 10 to 19 mph over.","h2":"In Colorado, a conviction for driving 20 to 39 miles per hour over the speed limit adds 6 points to your record.","p":"Right. Driving 20 to 39 mph over adds 6 points."},"es":{"q":"En Colorado, ¿cuántos puntos suma una multa por manejar de 20 a 39 mph sobre el límite de velocidad?","o":["2 puntos","6 puntos","10 puntos","1 punto"],"h1":"Es más que por ir de 10 a 19 mph sobre el límite.","h2":"En Colorado, una condena por manejar de 20 a 39 millas por hora sobre el límite de velocidad suma 6 puntos a su historial.","p":"Correcto. Ir de 20 a 39 mph sobre el límite suma 6 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-112","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, how many points does a ticket for driving 40 mph or more over the speed limit add?","o":["4 points","6 points","8 points","12 points"],"h1":"It is enough by itself to suspend an adult's license.","h2":"In Colorado, a conviction for driving 40 or more miles per hour over the speed limit adds 12 points to your record.","p":"Right. Driving 40 mph or more over adds 12 points."},"es":{"q":"En Colorado, ¿cuántos puntos suma una multa por manejar a 40 mph o más sobre el límite de velocidad?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Basta por sí sola para suspender la licencia de un adulto.","h2":"En Colorado, una condena por manejar a 40 millas por hora o más sobre el límite de velocidad suma 12 puntos a su historial.","p":"Correcto. Ir a 40 mph o más sobre el límite suma 12 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-113","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, how many points does a careless driving conviction add?","o":["4 points","1 point","12 points","No points"],"h1":"It is half of what reckless driving can add.","h2":"In Colorado, a careless driving conviction adds 4 points to your driving record.","p":"Right. Careless driving adds 4 points."},"es":{"q":"En Colorado, ¿cuántos puntos suma una condena por manejo descuidado?","o":["4 puntos","1 punto","12 puntos","Ningún punto"],"h1":"Es la mitad de lo que puede sumar el manejo imprudente.","h2":"En Colorado, una condena por manejo descuidado suma 4 puntos a su historial de manejo.","p":"Correcto. El manejo descuidado suma 4 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-114","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, how many points does a conviction for failing to yield to an emergency vehicle add?","o":["1 point","2 points","4 points","12 points"],"h1":"It is the same as for following too closely.","h2":"In Colorado, failing to yield to an emergency vehicle adds 4 points to your driving record.","p":"Right. Failing to yield to an emergency vehicle adds 4 points."},"es":{"q":"En Colorado, ¿cuántos puntos suma una condena por no ceder el paso a un vehículo de emergencia?","o":["1 punto","2 puntos","4 puntos","12 puntos"],"h1":"Es lo mismo que por seguir a otro vehículo demasiado cerca.","h2":"En Colorado, no ceder el paso a un vehículo de emergencia suma 4 puntos a su historial de manejo.","p":"Correcto. No ceder el paso a un vehículo de emergencia suma 4 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-115","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, you get a ticket worth 4 points and pay the fine on or before the due date. What happens to the points?","o":["They are all removed","They are reduced by 2","They are doubled","Nothing changes"],"h1":"Paying on time earns a small break.","h2":"In Colorado, if you pay a penalty assessment ticket on time, a violation worth 3 or more points is reduced by 2 points.","p":"Right. Paying on time takes 2 points off."},"es":{"q":"En Colorado, usted recibe una multa de 4 puntos y paga la multa en la fecha límite o antes. ¿Qué pasa con los puntos?","o":["Se eliminan todos","Se reducen en 2","Se duplican","No cambia nada"],"h1":"Pagar a tiempo le da un pequeño beneficio.","h2":"En Colorado, si usted paga a tiempo una multa de tránsito con aviso de sanción, una infracción de 3 puntos o más se reduce en 2 puntos.","p":"Correcto. Pagar a tiempo le quita 2 puntos."},"ref":{"doc":"CO","page":null}},{"id":"co-116","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, a driver under 18 is convicted of a first violation of the seat belt rule for teen drivers. Besides a fine and points, what does the law require?","o":["A new written test","A year without a license","A driving course in another state","8 to 24 hours of community service"],"h1":"The teen gives some time to help the community.","h2":"In Colorado, a driver under 18 convicted of a first seat belt violation must do 8 to 24 hours of community service, pay a fine of up to $65 and get 2 points.","p":"Right. A first offense means 8 to 24 hours of community service."},"es":{"q":"En Colorado, un conductor menor de 18 años es condenado por una primera violación de la regla del cinturón para conductores adolescentes. Además de una multa y puntos, ¿qué exige la ley?","o":["Un nuevo examen escrito","Un año sin licencia","Un curso de manejo en otro estado","De 8 a 24 horas de servicio comunitario"],"h1":"El adolescente da algo de su tiempo para ayudar a la comunidad.","h2":"En Colorado, un conductor menor de 18 años condenado por una primera violación del cinturón debe hacer de 8 a 24 horas de servicio comunitario, pagar una multa de hasta $65 y recibir 2 puntos.","p":"Correcto. La primera vez significa de 8 a 24 horas de servicio comunitario."},"ref":{"doc":"CO","page":null}},{"id":"co-117","scope":"CO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Colorado, at least how much light must the front side windows of a car let through?","o":["5 percent","15 percent","27 percent","90 percent"],"h1":"It is a little more than one quarter.","h2":"In Colorado, windows other than the windshield, including the front side windows, must allow at least 27 percent of light to pass through.","p":"Right. Front side windows must let through at least 27 percent of light."},"es":{"q":"En Colorado, ¿por lo menos cuánta luz deben dejar pasar las ventanas laterales delanteras de un carro?","o":["5 por ciento","15 por ciento","27 por ciento","90 por ciento"],"h1":"Es un poco más de la cuarta parte.","h2":"En Colorado, las ventanas que no son el parabrisas, incluidas las ventanas laterales delanteras, deben dejar pasar al menos el 27 por ciento de la luz.","p":"Correcto. Las ventanas laterales delanteras deben dejar pasar al menos el 27 por ciento de la luz."},"ref":{"doc":"CO","page":null}},{"id":"co-118","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, after you buy a vehicle, how soon must you register it?","o":["Within 60 days","Within 7 days","Within 1 year","At your next license renewal"],"h1":"You have about two months.","h2":"In Colorado, the owner of a motor vehicle must register it with the state within 60 days after buying it.","p":"Right. Register a vehicle within 60 days of buying it."},"es":{"q":"En Colorado, después de comprar un vehículo, ¿en cuánto tiempo debe registrarlo?","o":["Dentro de 60 días","Dentro de 7 días","Dentro de 1 año","En su próxima renovación de licencia"],"h1":"Tiene más o menos dos meses.","h2":"En Colorado, el dueño de un vehículo motorizado debe registrarlo con el estado dentro de los 60 días después de comprarlo.","p":"Correcto. Registre un vehículo dentro de 60 días después de comprarlo."},"ref":{"doc":"CO","page":null}},{"id":"co-119","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, on a cold morning, may you leave your unlocked car running and unattended to warm it up?","o":["Yes, at any time","Only with a remote starter or similar","Only on a private driveway","No, never in any situation"],"h1":"The law cares that no one can simply drive the car away.","h2":"In Colorado, you may not leave an unlocked car running and unattended, but using a remote starter or adequate security measures, such as keeping a keyless fob away from the car, meets the law.","p":"Right. A remote starter or other security measure makes it legal."},"es":{"q":"En Colorado, en una mañana fría, ¿puede dejar su carro sin llave encendido y solo para calentarlo?","o":["Sí, en cualquier momento","Solo con arranque remoto o algo similar","Solo en una entrada de carros privada","No, nunca en ninguna situación"],"h1":"A la ley le importa que nadie pueda llevarse el carro fácilmente.","h2":"En Colorado, no puede dejar un carro sin llave encendido y solo, pero usar un arranque remoto o medidas de seguridad adecuadas, como mantener la llave electrónica lejos del carro, cumple con la ley.","p":"Correcto. Un arranque remoto u otra medida de seguridad lo hace legal."},"ref":{"doc":"CO","page":null}},{"id":"co-120","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, may you coast down a hill with your car in neutral?","o":["Yes, to save fuel","Yes, if the hill is short","Yes, if no one is behind you","No, it is against the law"],"h1":"In neutral, the engine cannot help you slow down.","h2":"In Colorado, a driver going downhill must not coast with the gears or transmission in neutral.","p":"Right. Coasting downhill in neutral is illegal."},"es":{"q":"En Colorado, ¿puede bajar una cuesta en neutro dejando que el carro ruede solo?","o":["Sí, para ahorrar gasolina","Sí, si la cuesta es corta","Sí, si no hay nadie detrás de usted","No, va contra la ley"],"h1":"En neutro, el motor no le ayuda a bajar la velocidad.","h2":"En Colorado, un conductor que va cuesta abajo no debe dejar que el carro ruede con los cambios o la transmisión en neutro.","p":"Correcto. Bajar una cuesta en neutro es ilegal."},"ref":{"doc":"CO","page":null}},{"id":"co-121","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, on a mountain highway, you approach a curve where you cannot see 200 feet ahead. What does the law say you must do?","o":["Sound your horn","Flash your high beams","Stop completely","Turn on your hazard lights"],"h1":"Warn anyone coming around the curve with sound.","h2":"In Colorado, on mountain highways, a driver approaching a curve where the view is blocked within 200 feet must give a warning with the horn.","p":"Right. Sound your horn before a blind mountain curve."},"es":{"q":"En Colorado, en una carretera de montaña, usted se acerca a una curva donde no puede ver 200 pies adelante. ¿Qué dice la ley que debe hacer?","o":["Tocar la bocina","Hacer cambio de luces altas","Detenerse por completo","Prender las luces intermitentes"],"h1":"Avise con sonido a quien venga por la curva.","h2":"En Colorado, en carreteras de montaña, un conductor que se acerca a una curva donde la vista está bloqueada a menos de 200 pies debe avisar con la bocina.","p":"Correcto. Toque la bocina antes de una curva ciega en la montaña."},"ref":{"doc":"CO","page":null}},{"id":"co-122","scope":"CO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Colorado, a fire truck is going to a fire alarm ahead of you. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 500 feet","As close as traffic allows"],"h1":"It is about one and a half football fields.","h2":"In Colorado, unless you are on official business, you may not follow a fire truck answering a fire alarm closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on a call."},"es":{"q":"En Colorado, un camión de bomberos va adelante de usted hacia una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No a menos de 50 pies","No a menos de 100 pies","No a menos de 500 pies","Tan cerca como lo permita el tráfico"],"h1":"Es más o menos una cancha y media de fútbol americano.","h2":"En Colorado, a menos que esté en servicio oficial, usted no puede seguir a menos de 500 pies a un camión de bomberos que responde a una alarma de incendio.","p":"Correcto. Manténgase al menos a 500 pies detrás de un camión de bomberos en servicio."},"ref":{"doc":"CO","page":null}},{"id":"co-123","scope":"CO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Colorado, what is the law about throwing a lit cigarette out of a car window?","o":["It is legal on paved roads","It is not allowed","It is allowed in winter","It is allowed if no grass is near"],"h1":"Burning material can start a fire or hurt someone.","h2":"In Colorado, no one may throw, drop or expel a lighted cigarette, cigar, match or other burning material from a motor vehicle onto a highway.","p":"Right. Throwing burning material from a car is against the law."},"es":{"q":"En Colorado, ¿qué dice la ley sobre tirar un cigarrillo encendido por la ventana del carro?","o":["Es legal en calles pavimentadas","No está permitido","Está permitido en invierno","Está permitido si no hay pasto cerca"],"h1":"El material encendido puede causar un incendio o herir a alguien.","h2":"En Colorado, nadie puede tirar, dejar caer ni arrojar un cigarrillo, puro, fósforo u otro material encendido desde un vehículo a una carretera.","p":"Correcto. Tirar material encendido desde un carro va contra la ley."},"ref":{"doc":"CO","page":null}},{"id":"co-124","scope":"CO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Colorado, who must wear a helmet on a motorcycle?","o":["Every rider of any age","Only riders over 65","Only the driver, not passengers","Every rider under 18"],"h1":"The helmet law is based on age.","h2":"In Colorado, every motorcycle driver and passenger under 18 must wear a motorcycle helmet secured with a chin strap.","p":"Right. Riders under 18 must wear a helmet."},"es":{"q":"En Colorado, ¿quién debe usar casco en una motocicleta?","o":["Todo motociclista de cualquier edad","Solo los mayores de 65 años","Solo el conductor, no los pasajeros","Todo motociclista menor de 18 años"],"h1":"La ley del casco depende de la edad.","h2":"En Colorado, todo conductor y pasajero de motocicleta menor de 18 años debe usar un casco de motocicleta abrochado con la correa de la barbilla.","p":"Correcto. Los menores de 18 años deben usar casco."},"ref":{"doc":"CO","page":null}},{"id":"co-125","scope":"CO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Colorado, what eye protection must a motorcycle rider wear?","o":["Goggles, safety glasses or a helmet face shield","None if the bike has a windshield","Sunglasses, but only in the daytime","Nothing, unless riding on a highway"],"h1":"The rule applies to drivers and passengers of all ages.","h2":"In Colorado, motorcycle drivers and passengers must wear goggles or eyeglasses with safety glass or plastic lenses, unless they wear a helmet with eye protection.","p":"Right. Wear goggles or safety glasses, or a helmet with eye protection."},"es":{"q":"En Colorado, ¿qué protección para los ojos debe usar un motociclista?","o":["Gafas protectoras, lentes de seguridad o casco con visera","Ninguna si la moto tiene parabrisas","Lentes de sol, pero solo de día","Nada, salvo en las carreteras"],"h1":"La regla se aplica a conductores y pasajeros de todas las edades.","h2":"En Colorado, los conductores y pasajeros de motocicleta deben usar gafas protectoras o anteojos con lentes de vidrio de seguridad o plástico, a menos que usen un casco con protección para los ojos.","p":"Correcto. Use gafas protectoras o lentes de seguridad, o un casco con protección para los ojos."},"ref":{"doc":"CO","page":null}},{"id":"co-126","scope":"CO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Colorado, since August 2024, a two-wheeled motorcycle may pass between stopped cars in the same lane. At what speed or less?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"It is a slow speed, a little faster than a jog.","h2":"In Colorado, a two-wheeled motorcycle may pass stopped vehicles in the same lane only when traffic is stopped, the lanes are wide enough and the motorcycle goes 15 miles per hour or less.","p":"Right. Lane filtering is allowed only at 15 mph or less."},"es":{"q":"En Colorado, desde agosto de 2024, una motocicleta de dos ruedas puede pasar entre carros detenidos en el mismo carril. ¿A qué velocidad o menos?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"Es una velocidad lenta, un poco más rápida que trotar.","h2":"En Colorado, una motocicleta de dos ruedas puede pasar a vehículos detenidos en el mismo carril solo cuando el tráfico está parado, los carriles son lo bastante anchos y la motocicleta va a 15 millas por hora o menos.","p":"Correcto. Pasar entre carros solo se permite a 15 mph o menos."},"ref":{"doc":"CO","page":null}},{"id":"co-127","scope":"CO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Colorado, who may renew a driver license by mail or online?","o":["Any driver age 16 or older","Only drivers age 21 or older","Only drivers age 65 or older","Only drivers with no points"],"h1":"Minor drivers must renew in person.","h2":"In Colorado, renewing a driver license by mail or by electronic means is available only to drivers 21 or older.","p":"Right. Mail and online renewal are only for drivers 21 or older."},"es":{"q":"En Colorado, ¿quién puede renovar la licencia de conducir por correo o en línea?","o":["Cualquier conductor de 16 años o más","Solo los conductores de 21 años o más","Solo los conductores de 65 años o más","Solo los conductores sin puntos"],"h1":"Los conductores menores deben renovar en persona.","h2":"En Colorado, renovar la licencia de conducir por correo o por medios electrónicos solo está disponible para conductores de 21 años o más.","p":"Correcto. La renovación por correo o en línea es solo para conductores de 21 años o más."},"ref":{"doc":"CO","page":null}},{"id":"co-128","scope":"CO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Colorado, a driver age 80 wants to renew by mail or online. What must the driver get?","o":["A new driving skills test","A letter from a family member","A note from a pharmacist","An eye doctor's recent signed statement"],"h1":"It concerns vision, checked recently by a specialist.","h2":"In Colorado, a driver 80 or older who renews by mail or online must get a signed statement from an optometrist or ophthalmologist about an eye exam within the past six months.","p":"Right. An eye doctor's signed statement from the last 6 months is needed."},"es":{"q":"En Colorado, un conductor de 80 años quiere renovar por correo o en línea. ¿Qué debe conseguir?","o":["Un nuevo examen práctico de manejo","Una carta de un familiar","Una nota de un farmacéutico","Una declaración reciente de un médico de los ojos"],"h1":"Tiene que ver con la vista, revisada hace poco por un especialista.","h2":"En Colorado, un conductor de 80 años o más que renueva por correo o en línea debe conseguir una declaración firmada de un optometrista u oftalmólogo sobre un examen de la vista hecho en los últimos seis meses.","p":"Correcto. Se necesita una declaración firmada de un médico de los ojos de los últimos 6 meses."},"ref":{"doc":"CO","page":null}},{"id":"co-129","scope":"CO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Colorado, a driver is caught driving with a blood alcohol level of 0.15 or more. How does the law label this driver?","o":["A persistent drunk driver","A habitual offender","A first-time minor offender","A provisional driver"],"h1":"The law treats such a high level as a sign of a serious drinking problem.","h2":"In Colorado, a person who drives with a blood or breath alcohol level of 0.15 or more is defined as a persistent drunk driver.","p":"Right. A level of 0.15 or more makes you a persistent drunk driver."},"es":{"q":"En Colorado, detienen a un conductor que maneja con un nivel de alcohol en la sangre de 0.15 o más. ¿Cómo lo clasifica la ley?","o":["Conductor ebrio persistente","Infractor habitual","Menor infractor por primera vez","Conductor provisional"],"h1":"La ley ve un nivel tan alto como señal de un problema serio con el alcohol.","h2":"En Colorado, una persona que maneja con un nivel de alcohol en la sangre o el aliento de 0.15 o más se define como conductor ebrio persistente.","p":"Correcto. Un nivel de 0.15 o más lo clasifica como conductor ebrio persistente."},"ref":{"doc":"CO","page":null}},{"id":"co-130","scope":"CO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Colorado, a driver leaves the scene of a crash in which a person was killed. What kind of crime is this?","o":["A minor traffic infraction","A petty offense with a warning","A felony","A parking violation"],"h1":"It is more serious than a misdemeanor.","h2":"In Colorado, leaving the scene of a crash that caused a death is a class 3 felony, and the driver's license is revoked.","p":"Right. Leaving the scene of a deadly crash is a felony."},"es":{"q":"En Colorado, un conductor se va del lugar de un choque en el que murió una persona. ¿Qué tipo de delito es?","o":["Una infracción de tránsito menor","Una falta leve con advertencia","Un delito grave (felonía)","Una infracción de estacionamiento"],"h1":"Es más serio que un delito menor.","h2":"En Colorado, irse del lugar de un choque que causó una muerte es un delito grave de clase 3, y se revoca la licencia del conductor.","p":"Correcto. Irse del lugar de un choque mortal es un delito grave."},"ref":{"doc":"CO","page":null}},{"id":"co-131","scope":"CO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Colorado, a driver carelessly drives much too close to a bicyclist. What can the driver be charged with?","o":["Nothing, if the rider was not touched","Careless driving","A parking violation","Only a written warning"],"h1":"Crowding a bicyclist is treated like other unsafe driving.","h2":"In Colorado, driving carelessly and unnecessarily close to, toward or near a bicyclist is careless driving.","p":"Right. Crowding a bicyclist counts as careless driving."},"es":{"q":"En Colorado, un conductor maneja con descuido demasiado cerca de un ciclista. ¿De qué lo pueden acusar?","o":["De nada, si no tocó al ciclista","De manejo descuidado","De una infracción de estacionamiento","Solo de una advertencia escrita"],"h1":"Acosar a un ciclista se trata como otro manejo inseguro.","h2":"En Colorado, manejar con descuido e innecesariamente cerca de un ciclista o hacia él es manejo descuidado.","p":"Correcto. Acosar a un ciclista cuenta como manejo descuidado."},"ref":{"doc":"CO","page":null}},{"id":"ct-001","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the age when many teens in other states can already get a license.","h2":"In Connecticut you must be at least 16 years old to get a learner's permit.","p":"Right. The Connecticut learner's permit starts at 16."},"es":{"q":"En Connecticut, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la edad en que muchos jóvenes de otros estados ya pueden obtener la licencia.","h2":"En Connecticut usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. El permiso de aprendiz en Connecticut empieza a los 16."},"zh":{"q":"在 Connecticut，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"在其他很多州，青少年到这个年龄已经可以拿正式驾照了。","h2":"在 Connecticut，你必须至少 16 岁才能拿到学习驾照。","p":"对。Connecticut 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Connecticut, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là tuổi mà nhiều thiếu niên ở các tiểu bang khác đã có thể lấy bằng lái.","h2":"Ở Connecticut, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái.","p":"Đúng. Giấy phép tập lái ở Connecticut bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Connecticut, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang edad kung kailan maraming teenager sa ibang estado ay puwede nang kumuha ng lisensya.","h2":"Sa Connecticut, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng learner's permit.","p":"Tama. Nagsisimula ang learner's permit sa Connecticut sa edad na 16."},"ar":{"q":"في Connecticut، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو العمر الذي يستطيع فيه كثير من المراهقين في ولايات أخرى الحصول على رخصة القيادة.","h2":"في Connecticut يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم.","p":"صحيح. يبدأ تصريح التعلّم في Connecticut في عمر 16 سنة."},"ref":{"doc":"CT","page":5}},{"id":"ct-002","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, who may ride with a driver who holds a learner's permit?","o":["Only the qualified trainer, and parents or others with a driving instructor","Any friend who has a license","Up to three passengers of any age","Anyone, as long as all wear seat belts"],"h1":"The permit is only for practice with a teacher.","h2":"A Connecticut permit holder may carry only the person giving instruction, plus parents or others riding with a licensed driving instructor.","p":"Right. A permit driver rides only with the trainer and the few people the law allows."},"es":{"q":"En Connecticut, ¿quién puede viajar con un conductor que tiene permiso de aprendiz?","o":["Solo el instructor calificado, y los padres u otras personas con un instructor de manejo","Cualquier amigo que tenga licencia","Hasta tres pasajeros de cualquier edad","Cualquier persona, si todos usan el cinturón"],"h1":"El permiso es solo para practicar con un maestro.","h2":"En Connecticut, quien tiene permiso de aprendiz solo puede llevar a la persona que le enseña, y a los padres u otras personas que viajan con un instructor de manejo con licencia.","p":"Correcto. El aprendiz solo viaja con su instructor y las pocas personas que permite la ley."},"zh":{"q":"在 Connecticut，谁可以坐持学习驾照的司机的车？","o":["只有合格的指导人，以及有驾驶教练同车时的父母或其他人","任何有驾照的朋友","最多三位任何年龄的乘客","任何人，只要都系好安全带"],"h1":"学习驾照只是用来和老师一起练习的。","h2":"Connecticut 持学习驾照的人只能载正在指导他的人，以及和有执照的驾驶教练同车的父母或其他人。","p":"对。持学习驾照的司机只能载指导人和法律允许的少数几个人。"},"vi":{"q":"Ở Connecticut, ai được phép đi cùng xe với người lái có giấy phép tập lái (learner's permit)?","o":["Chỉ người hướng dẫn đủ điều kiện, và cha mẹ hoặc người khác khi có giáo viên dạy lái xe","Bất kỳ người bạn nào có bằng lái","Tối đa ba hành khách ở mọi lứa tuổi","Bất kỳ ai, miễn là mọi người đều thắt dây an toàn"],"h1":"Giấy phép này chỉ dùng để tập lái với người dạy.","h2":"Ở Connecticut, người có giấy phép tập lái chỉ được chở người đang hướng dẫn lái, cùng với cha mẹ hoặc người khác khi đi với giáo viên dạy lái xe có giấy phép.","p":"Đúng. Người tập lái chỉ đi cùng người hướng dẫn và vài người mà luật cho phép."},"tl":{"q":"Sa Connecticut, sino ang puwedeng sumakay kasama ng driver na may learner's permit?","o":["Ang qualified trainer lang, at ang mga magulang o iba pa kapag may kasamang driving instructor","Kahit sinong kaibigan na may lisensya","Hanggang tatlong pasahero kahit anong edad","Kahit sino, basta lahat ay naka-seat belt"],"h1":"Ang permit ay para lang sa pagsasanay kasama ang isang guro.","h2":"Sa Connecticut, ang may permit ay puwede lang magsakay ng taong nagtuturo sa kanya, pati ang mga magulang o iba pa kapag kasama ang isang lisensyadong driving instructor.","p":"Tama. Ang driver na may permit ay sumasakay lang kasama ang trainer at ang ilang taong pinapayagan ng batas."},"ar":{"q":"في Connecticut، من يُسمح له بالركوب مع سائق يحمل تصريح التعلّم (learner's permit)؟","o":["المدرّب المؤهَّل فقط، والوالدان أو غيرهم عند وجود مدرّب قيادة","أي صديق لديه رخصة","حتى ثلاثة ركاب من أي عمر","أي شخص، ما دام الجميع يربطون حزام الأمان"],"h1":"التصريح هو للتدريب مع معلّم فقط.","h2":"في Connecticut لا يجوز لحامل تصريح التعلّم أن يُركب معه إلا الشخص الذي يعلّمه، بالإضافة إلى الوالدين أو غيرهم عند الركوب مع مدرّب قيادة مرخَّص.","p":"صحيح. سائق التصريح يركب فقط مع المدرّب ومع عدد قليل من الأشخاص الذين يسمح بهم القانون."},"ref":{"doc":"CT","page":6}},{"id":"ct-003","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how old must a non-professional person be to give driving instruction to a permit holder?","o":["At least 18","At least 25","At least 21","At least 20"],"h1":"It is a little younger than the age most states ask for.","h2":"In Connecticut the person who gives instruction must be at least 20 years old, unless it is a licensed driving instructor.","p":"Right. A Connecticut trainer must be 20 or older."},"es":{"q":"En Connecticut, ¿qué edad debe tener una persona que no es instructor profesional para enseñar a manejar a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 20"],"h1":"Es un poco menos que la edad que piden la mayoría de los estados.","h2":"En Connecticut, la persona que enseña debe tener por lo menos 20 años, salvo que sea un instructor de manejo con licencia.","p":"Correcto. En Connecticut el instructor debe tener 20 años o más."},"zh":{"q":"在 Connecticut，不是专业教练的人要几岁才能指导持学习驾照的人开车？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 20 岁"],"h1":"它比大多数州要求的年龄小一点。","h2":"在 Connecticut，指导开车的人必须至少 20 岁，有执照的驾驶教练除外。","p":"对。Connecticut 的指导人必须 20 岁或以上。"},"vi":{"q":"Ở Connecticut, một người không phải giáo viên chuyên nghiệp phải bao nhiêu tuổi để được dạy lái xe cho người có giấy phép tập lái?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi","Ít nhất 20 tuổi"],"h1":"Tuổi này trẻ hơn một chút so với tuổi mà phần lớn các tiểu bang yêu cầu.","h2":"Ở Connecticut, người hướng dẫn lái xe phải ít nhất 20 tuổi, trừ khi đó là giáo viên dạy lái xe có giấy phép.","p":"Đúng. Người hướng dẫn ở Connecticut phải từ 20 tuổi trở lên."},"tl":{"q":"Sa Connecticut, ilang taon dapat ang isang taong hindi propesyonal para makapagturo ng pagmamaneho sa may permit?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 20"],"h1":"Medyo mas bata ito kaysa sa edad na hinihingi ng karamihan ng estado.","h2":"Sa Connecticut, ang taong nagtuturo ay dapat hindi bababa sa 20 taong gulang, maliban kung siya ay lisensyadong driving instructor.","p":"Tama. Ang trainer sa Connecticut ay dapat 20 taong gulang o higit pa."},"ar":{"q":"في Connecticut، كم يجب أن يكون عمر الشخص غير المحترف حتى يعلّم القيادة لحامل التصريح؟","o":["18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل","20 سنة على الأقل"],"h1":"هو أصغر قليلًا من العمر الذي تطلبه معظم الولايات.","h2":"في Connecticut يجب أن يكون عمر الشخص الذي يعلّم القيادة 20 سنة على الأقل، إلا إذا كان مدرّب قيادة مرخَّصًا.","p":"صحيح. يجب أن يكون المدرّب في Connecticut في عمر 20 سنة أو أكثر."},"ref":{"doc":"CT","page":6}},{"id":"ct-004","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, for how long must the person teaching a permit holder have held a driver's license?","o":["At least one year","At least four years in a row","At least ten years","Any amount of time"],"h1":"It is more than a few years, with no suspension in that time.","h2":"In Connecticut the trainer must have held a license for at least four years in a row, with no suspension in those four years.","p":"Right. Four clean years of licensing are required."},"es":{"q":"En Connecticut, ¿por cuánto tiempo debe haber tenido licencia la persona que enseña a quien tiene permiso?","o":["Por lo menos un año","Por lo menos cuatro años seguidos","Por lo menos diez años","Cualquier tiempo"],"h1":"Son varios años, sin ninguna suspensión en ese tiempo.","h2":"En Connecticut el instructor debe haber tenido licencia por lo menos cuatro años seguidos, sin suspensión en esos cuatro años.","p":"Correcto. Se requieren cuatro años de licencia sin suspensión."},"zh":{"q":"在 Connecticut，指导持学习驾照的人开车的人，必须持有驾照多久？","o":["至少一年","连续至少四年","至少十年","多久都可以"],"h1":"它不止几年，而且这段时间里驾照没有被暂停过。","h2":"在 Connecticut，指导人必须连续持有驾照至少四年，而且这四年里驾照没有被暂停过。","p":"对。需要四年没有问题的驾照记录。"},"vi":{"q":"Ở Connecticut, người dạy lái cho người có giấy phép tập lái phải có bằng lái trong bao lâu?","o":["Ít nhất một năm","Ít nhất bốn năm liên tục","Ít nhất mười năm","Bao lâu cũng được"],"h1":"Đó là hơn vài năm, và không bị treo bằng trong thời gian đó.","h2":"Ở Connecticut, người hướng dẫn phải có bằng lái ít nhất bốn năm liên tục và không bị treo bằng trong bốn năm đó.","p":"Đúng. Cần có bằng lái bốn năm không vi phạm."},"tl":{"q":"Sa Connecticut, gaano katagal dapat may lisensya ang taong nagtuturo sa may permit?","o":["Hindi bababa sa isang taon","Hindi bababa sa apat na taon nang tuloy-tuloy","Hindi bababa sa sampung taon","Kahit gaano katagal"],"h1":"Higit ito sa ilang taon, at walang suspensyon sa panahong iyon.","h2":"Sa Connecticut, ang trainer ay dapat may lisensya nang hindi bababa sa apat na taon nang tuloy-tuloy, at walang suspensyon sa apat na taong iyon.","p":"Tama. Kailangan ang apat na taon ng malinis na lisensya."},"ar":{"q":"في Connecticut، كم مدة يجب أن يكون الشخص الذي يعلّم حامل التصريح قد حمل رخصة قيادة؟","o":["سنة واحدة على الأقل","أربع سنوات متتالية على الأقل","عشر سنوات على الأقل","أي مدة"],"h1":"هي أكثر من بضع سنوات، دون إيقاف للرخصة في تلك المدة.","h2":"في Connecticut يجب أن يكون المدرّب قد حمل رخصة القيادة أربع سنوات متتالية على الأقل، دون إيقاف للرخصة في تلك السنوات الأربع.","p":"صحيح. يجب أن تكون هناك أربع سنوات من الرخصة دون مخالفات."},"ref":{"doc":"CT","page":6}},{"id":"ct-005","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, may a 17-year-old driver talk on a phone with a hands-free device?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all while driving","Yes, if a parent is in the car"],"h1":"Young drivers have a stricter rule than adults.","h2":"In Connecticut a driver under 18 may not use a cell phone or other mobile electronic device while driving, even with a hands-free accessory.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Connecticut, ¿puede un conductor de 17 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono mientras manejan","Sí, si uno de sus padres va en el carro"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"En Connecticut un conductor menor de 18 años no puede usar un celular ni otro aparato electrónico móvil mientras maneja, aunque sea con manos libres.","p":"Correcto. Antes de los 18, nada de teléfono al manejar."},"zh":{"q":"在 Connecticut，17 岁的司机可以用免持设备打电话吗？","o":["可以，免持总是允许的","可以，但只在公路上","不可以，18 岁以下的司机开车时完全不能用手机","可以，如果父母在车里"],"h1":"年轻司机的规定比成年人更严。","h2":"在 Connecticut，18 岁以下的司机开车时不能用手机或其他移动电子设备，即使用免持配件也不行。","p":"对。18 岁以下，开车时完全不能用手机。"},"vi":{"q":"Ở Connecticut, người lái xe 17 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại khi lái xe","Có, nếu có cha mẹ trong xe"],"h1":"Người lái trẻ có luật nghiêm hơn người lớn.","h2":"Ở Connecticut, người lái dưới 18 tuổi không được dùng điện thoại di động hay thiết bị điện tử di động khác khi lái xe, kể cả khi có thiết bị rảnh tay.","p":"Đúng. Dưới 18 tuổi thì hoàn toàn không dùng điện thoại khi lái xe."},"tl":{"q":"Sa Connecticut, puwede bang makipag-usap sa telepono ang 17 taong gulang na driver gamit ang hands-free na device?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, ang mga driver na wala pang 18 ay bawal gumamit ng telepono habang nagmamaneho","Oo, kung may magulang sa kotse"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa matatanda.","h2":"Sa Connecticut, ang driver na wala pang 18 taong gulang ay bawal gumamit ng cell phone o ibang mobile electronic device habang nagmamaneho, kahit may hands-free na gamit.","p":"Tama. Kapag wala pang 18, walang telepono habang nagmamaneho."},"ar":{"q":"في Connecticut، هل يجوز لسائق عمره 17 سنة أن يتحدث في الهاتف بجهاز لا يحتاج إلى اليدين (hands-free)؟","o":["نعم، الجهاز الذي لا يحتاج إلى اليدين مسموح دائمًا","نعم، ولكن على الطرق السريعة فقط","لا، السائقون تحت 18 سنة لا يجوز لهم استخدام الهاتف أبدًا أثناء القيادة","نعم، إذا كان أحد الوالدين في السيارة"],"h1":"للسائقين الصغار قاعدة أشدّ من الكبار.","h2":"في Connecticut لا يجوز للسائق تحت 18 سنة أن يستخدم الهاتف المحمول أو أي جهاز إلكتروني محمول آخر أثناء القيادة، حتى مع ملحق لا يحتاج إلى اليدين.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء القيادة."},"ref":{"doc":"CT","page":8}},{"id":"ct-006","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, what does the law say about adult drivers and hand-held phones?","o":["Using a hand-held phone or device while driving is not allowed","Hand-held phones are allowed at red lights","Hand-held phones are allowed below 30 mph","There is no rule for adults"],"h1":"Adults may still talk, but not with the device in hand.","h2":"In Connecticut no driver may use a hand-held mobile electronic device while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Connecticut, ¿qué dice la ley sobre los conductores adultos y los teléfonos en la mano?","o":["No se permite usar un teléfono o aparato en la mano mientras maneja","Se permite en los semáforos en rojo","Se permite por debajo de 30 mph","No hay ninguna regla para adultos"],"h1":"Los adultos pueden hablar, pero sin tener el aparato en la mano.","h2":"En Connecticut ningún conductor puede usar un aparato electrónico móvil en la mano mientras maneja.","p":"Correcto. Deje el teléfono mientras maneja."},"zh":{"q":"在 Connecticut，法律对成年司机和手持电话有什么规定？","o":["开车时不能用手持电话或设备","红灯时可以用手持电话","低于 30 mph 时可以用手持电话","对成年人没有规定"],"h1":"成年人还是可以打电话，但设备不能拿在手里。","h2":"在 Connecticut，任何司机开车时都不能用手持移动电子设备。","p":"对。开车时把手机放下。"},"vi":{"q":"Ở Connecticut, luật nói gì về người lái xe trưởng thành và điện thoại cầm tay?","o":["Không được dùng điện thoại hoặc thiết bị cầm tay khi lái xe","Được dùng điện thoại cầm tay khi dừng đèn đỏ","Được dùng điện thoại cầm tay khi chạy dưới 30 mph","Không có luật nào cho người lớn"],"h1":"Người lớn vẫn có thể nói chuyện, nhưng không được cầm thiết bị trên tay.","h2":"Ở Connecticut, không người lái xe nào được dùng thiết bị điện tử di động cầm tay khi đang lái xe.","p":"Đúng. Hãy để điện thoại xuống khi bạn lái xe."},"tl":{"q":"Sa Connecticut, ano ang sinasabi ng batas tungkol sa mga adult na driver at hand-held na telepono?","o":["Bawal gumamit ng hand-held na telepono o device habang nagmamaneho","Pinapayagan ang hand-held na telepono sa pulang ilaw","Pinapayagan ang hand-held na telepono kapag mas mababa sa 30 mph","Walang patakaran para sa mga adult"],"h1":"Puwede pa ring makipag-usap ang mga adult, pero hindi hawak ang device.","h2":"Sa Connecticut, walang driver ang puwedeng gumamit ng hand-held na mobile electronic device habang nagmamaneho.","p":"Tama. Ibaba ang telepono habang nagmamaneho."},"ar":{"q":"في Connecticut، ماذا يقول القانون عن السائقين البالغين والهواتف المحمولة باليد؟","o":["لا يجوز استخدام هاتف أو جهاز محمول باليد أثناء القيادة","الهواتف المحمولة باليد مسموحة عند الإشارة الحمراء","الهواتف المحمولة باليد مسموحة تحت 30 mph","لا توجد قاعدة للبالغين"],"h1":"يمكن للبالغين أن يتحدثوا، لكن دون أن يمسكوا الجهاز بأيديهم.","h2":"في Connecticut لا يجوز لأي سائق أن يستخدم جهازًا إلكترونيًا محمولًا باليد أثناء القيادة.","p":"صحيح. ضع الهاتف جانبًا أثناء القيادة."},"ref":{"doc":"CT","page":13}},{"id":"ct-007","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, what is the fine for a first offense of using a hand-held phone while driving?","o":["$50","$200","$625","$1,000"],"h1":"The fine goes up to $375 and then $625 for later offenses.","h2":"In Connecticut a first hand-held phone offense costs $200, and the fine is higher for each later offense.","p":"Right. The first offense is $200."},"es":{"q":"En Connecticut, ¿cuál es la multa por la primera vez que se usa un teléfono en la mano mientras se maneja?","o":["$50","$200","$625","$1,000"],"h1":"La multa sube a $375 y después a $625 en las siguientes infracciones.","h2":"En Connecticut la primera infracción por usar el teléfono en la mano cuesta $200, y la multa es más alta en cada infracción siguiente.","p":"Correcto. La primera infracción cuesta $200."},"zh":{"q":"在 Connecticut，第一次开车时用手持电话，罚款是多少？","o":["$50","$200","$625","$1,000"],"h1":"以后再犯，罚款会提高到 $375，然后是 $625。","h2":"在 Connecticut，第一次用手持电话违规罚 $200，以后每次再犯罚款都更高。","p":"对。第一次违规是 $200。"},"vi":{"q":"Ở Connecticut, tiền phạt cho lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe là bao nhiêu?","o":["$50","$200","$625","$1,000"],"h1":"Tiền phạt tăng lên $375 rồi $625 cho các lần vi phạm sau.","h2":"Ở Connecticut, lần vi phạm đầu tiên vì dùng điện thoại cầm tay bị phạt $200, và tiền phạt cao hơn cho mỗi lần vi phạm sau.","p":"Đúng. Lần vi phạm đầu tiên bị phạt $200."},"tl":{"q":"Sa Connecticut, magkano ang multa sa unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho?","o":["$50","$200","$625","$1,000"],"h1":"Tumataas ang multa sa $375 at pagkatapos ay $625 sa mga susunod na paglabag.","h2":"Sa Connecticut, ang unang paglabag sa paggamit ng hand-held na telepono ay $200, at mas mataas ang multa sa bawat susunod na paglabag.","p":"Tama. $200 ang unang paglabag."},"ar":{"q":"في Connecticut، ما الغرامة على المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة؟","o":["$50","$200","$625","$1,000"],"h1":"ترتفع الغرامة إلى $375 ثم إلى $625 في المخالفات التالية.","h2":"في Connecticut تكون غرامة المخالفة الأولى لاستخدام الهاتف المحمول باليد $200، وتزيد الغرامة في كل مخالفة بعدها.","p":"صحيح. غرامة المخالفة الأولى $200."},"ref":{"doc":"CT","page":null}},{"id":"ct-008","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, during the first six months with a license, who may a 16- or 17-year-old driver carry as passengers?","o":["Up to two friends","Any family member or friend","Anyone over 16","Only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older"],"h1":"It is the same short list as during the permit.","h2":"In Connecticut, for the first six months, a newly licensed 16- or 17-year-old may carry only a driving instructor, a parent or guardian, or one qualified trainer age 20 or older.","p":"Right. The first six months are almost passenger-free."},"es":{"q":"En Connecticut, durante los primeros seis meses con licencia, ¿a quién puede llevar como pasajero un conductor de 16 o 17 años?","o":["Hasta dos amigos","Cualquier familiar o amigo","Cualquier persona mayor de 16","Solo un instructor de manejo, sus padres o tutor, o un instructor calificado de 20 años o más"],"h1":"Es la misma lista corta que durante el permiso.","h2":"En Connecticut, durante los primeros seis meses, un conductor de 16 o 17 años con licencia nueva solo puede llevar a un instructor de manejo, a sus padres o tutor, o a un instructor calificado de 20 años o más.","p":"Correcto. Los primeros seis meses son casi sin pasajeros."},"zh":{"q":"在 Connecticut，拿到驾照的前六个月，16 岁或 17 岁的司机可以载谁？","o":["最多两位朋友","任何家人或朋友","任何 16 岁以上的人","只有驾驶教练、父母或监护人，或一位 20 岁或以上的合格指导人"],"h1":"它和持学习驾照时的短名单一样。","h2":"在 Connecticut，前六个月，刚拿到驾照的 16 岁或 17 岁司机只能载驾驶教练、父母或监护人，或一位 20 岁或以上的合格指导人。","p":"对。前六个月几乎不能载乘客。"},"vi":{"q":"Ở Connecticut, trong sáu tháng đầu có bằng lái, người lái 16 hoặc 17 tuổi được chở ai?","o":["Tối đa hai người bạn","Bất kỳ người nhà hay bạn bè nào","Bất kỳ ai trên 16 tuổi","Chỉ giáo viên dạy lái xe, cha mẹ hoặc người giám hộ, hoặc một người hướng dẫn đủ điều kiện từ 20 tuổi trở lên"],"h1":"Đó là cùng một danh sách ngắn như khi còn giấy phép tập lái.","h2":"Ở Connecticut, trong sáu tháng đầu, người mới có bằng lái 16 hoặc 17 tuổi chỉ được chở giáo viên dạy lái xe, cha mẹ hoặc người giám hộ, hoặc một người hướng dẫn đủ điều kiện từ 20 tuổi trở lên.","p":"Đúng. Sáu tháng đầu gần như không được chở hành khách."},"tl":{"q":"Sa Connecticut, sa unang anim na buwan na may lisensya, sino ang puwedeng isakay ng 16 o 17 taong gulang na driver?","o":["Hanggang dalawang kaibigan","Kahit sinong kapamilya o kaibigan","Kahit sinong lampas 16","Driving instructor lang, magulang o guardian, o isang qualified trainer na 20 taong gulang o higit pa"],"h1":"Ito rin ang maikling listahan noong may permit pa.","h2":"Sa Connecticut, sa unang anim na buwan, ang bagong may lisensya na 16 o 17 taong gulang ay puwede lang magsakay ng driving instructor, magulang o guardian, o isang qualified trainer na 20 taong gulang o higit pa.","p":"Tama. Halos walang pasahero sa unang anim na buwan."},"ar":{"q":"في Connecticut، خلال الأشهر الستة الأولى بعد الحصول على الرخصة، من يجوز للسائق الذي عمره 16 أو 17 سنة أن يُركبه معه؟","o":["حتى صديقين","أي فرد من العائلة أو صديق","أي شخص فوق 16 سنة","مدرّب القيادة فقط، أو أحد الوالدين أو الوصي، أو مدرّب مؤهَّل واحد عمره 20 سنة أو أكثر"],"h1":"هي نفس القائمة القصيرة التي كانت في فترة التصريح.","h2":"في Connecticut، خلال الأشهر الستة الأولى، لا يجوز للسائق الجديد الذي عمره 16 أو 17 سنة أن يُركب معه إلا مدرّب القيادة، أو أحد الوالدين أو الوصي، أو مدرّبًا مؤهَّلًا واحدًا عمره 20 سنة أو أكثر.","p":"صحيح. الأشهر الستة الأولى تكون تقريبًا بلا ركاب."},"ref":{"doc":"CT","page":8}},{"id":"ct-009","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, in the second six months with a license, who else may a 16- or 17-year-old driver carry?","o":["Up to three friends","Members of the driver's immediate family","Any classmate","No one at all"],"h1":"The rule opens a little, but only for people at home.","h2":"In Connecticut, in the second six months, a 16- or 17-year-old driver may also carry members of their immediate family.","p":"Right. Immediate family may ride in the second six months."},"es":{"q":"En Connecticut, en los segundos seis meses con licencia, ¿a quién más puede llevar un conductor de 16 o 17 años?","o":["Hasta tres amigos","A miembros de su familia inmediata","A cualquier compañero de clase","A nadie"],"h1":"La regla se abre un poco, pero solo para la gente de su casa.","h2":"En Connecticut, en los segundos seis meses, un conductor de 16 o 17 años también puede llevar a miembros de su familia inmediata.","p":"Correcto. La familia inmediata puede viajar en los segundos seis meses."},"zh":{"q":"在 Connecticut，拿到驾照的第二个六个月，16 岁或 17 岁的司机还可以载谁？","o":["最多三位朋友","司机的直系家人","任何同学","谁都不行"],"h1":"规定放宽一点，但只限家里的人。","h2":"在 Connecticut，第二个六个月，16 岁或 17 岁的司机也可以载自己的直系家人。","p":"对。第二个六个月可以载直系家人。"},"vi":{"q":"Ở Connecticut, trong sáu tháng thứ hai có bằng lái, người lái 16 hoặc 17 tuổi được chở thêm ai?","o":["Tối đa ba người bạn","Người trong gia đình ruột thịt của người lái","Bất kỳ bạn cùng lớp nào","Không ai cả"],"h1":"Luật nới ra một chút, nhưng chỉ cho người trong nhà.","h2":"Ở Connecticut, trong sáu tháng thứ hai, người lái 16 hoặc 17 tuổi cũng được chở người trong gia đình ruột thịt của mình.","p":"Đúng. Gia đình ruột thịt được đi cùng trong sáu tháng thứ hai."},"tl":{"q":"Sa Connecticut, sa ikalawang anim na buwan na may lisensya, sino pa ang puwedeng isakay ng 16 o 17 taong gulang na driver?","o":["Hanggang tatlong kaibigan","Mga miyembro ng malapit na pamilya (immediate family) ng driver","Kahit sinong kaklase","Wala talaga"],"h1":"Lumuluwag nang kaunti ang patakaran, pero para lang sa mga taong kasama sa bahay.","h2":"Sa Connecticut, sa ikalawang anim na buwan, puwede ring isakay ng 16 o 17 taong gulang na driver ang mga miyembro ng kanyang malapit na pamilya.","p":"Tama. Puwedeng sumakay ang malapit na pamilya sa ikalawang anim na buwan."},"ar":{"q":"في Connecticut، في الأشهر الستة الثانية بعد الحصول على الرخصة، من يجوز أيضًا للسائق الذي عمره 16 أو 17 سنة أن يُركبه معه؟","o":["حتى ثلاثة أصدقاء","أفراد العائلة المباشرة للسائق","أي زميل في الصف","لا أحد أبدًا"],"h1":"تصبح القاعدة أسهل قليلًا، ولكن فقط لأهل البيت.","h2":"في Connecticut، في الأشهر الستة الثانية، يجوز للسائق الذي عمره 16 أو 17 سنة أن يُركب معه أيضًا أفراد عائلته المباشرة.","p":"صحيح. يمكن للعائلة المباشرة أن تركب في الأشهر الستة الثانية."},"ref":{"doc":"CT","page":8}},{"id":"ct-010","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, during which hours may a licensed 16- or 17-year-old not drive, except for reasons such as work, school or a medical emergency?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Connecticut a licensed 16- or 17-year-old may not drive from 11 p.m. to 5 a.m., except for work, school, religious activities or a medical emergency.","p":"Right. The teen curfew is 11 p.m. to 5 a.m."},"es":{"q":"En Connecticut, ¿en qué horario no puede manejar un joven de 16 o 17 años con licencia, salvo por trabajo, escuela o una emergencia médica?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Connecticut un joven de 16 o 17 años con licencia no puede manejar de 11 p.m. a 5 a.m., salvo por trabajo, escuela, actividades religiosas o una emergencia médica.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Connecticut，有驾照的 16 岁或 17 岁司机在哪段时间不能开车（工作、上学或医疗紧急情况等理由除外）？","o":["晚上 9 点到早上 6 点","午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点"],"h1":"它在午夜前一小时开始。","h2":"在 Connecticut，有驾照的 16 岁或 17 岁司机在晚上 11 点到早上 5 点不能开车，工作、上学、宗教活动或医疗紧急情况除外。","p":"对。青少年的宵禁是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Connecticut, người lái có bằng 16 hoặc 17 tuổi không được lái xe trong khung giờ nào, trừ các lý do như đi làm, đi học hoặc cấp cứu y tế?","o":["9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Nó bắt đầu một giờ trước nửa đêm.","h2":"Ở Connecticut, người lái có bằng 16 hoặc 17 tuổi không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi đi làm, đi học, sinh hoạt tôn giáo hoặc cấp cứu y tế.","p":"Đúng. Giờ giới nghiêm cho thiếu niên là 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Connecticut, sa anong oras bawal magmaneho ang 16 o 17 taong gulang na may lisensya, maliban sa mga dahilan tulad ng trabaho, paaralan o medical emergency?","o":["9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na may lisensya ay bawal magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung para sa trabaho, paaralan, gawaing panrelihiyon o medical emergency.","p":"Tama. Ang curfew para sa teenager ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Connecticut، في أي ساعات لا يجوز للسائق المرخَّص الذي عمره 16 أو 17 سنة أن يقود، إلا لأسباب مثل العمل أو المدرسة أو حالة طبية طارئة؟","o":["من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"في Connecticut لا يجوز للسائق المرخَّص الذي عمره 16 أو 17 سنة أن يقود من 11 مساءً إلى 5 صباحًا، إلا للعمل أو المدرسة أو نشاط ديني أو حالة طبية طارئة.","p":"صحيح. حظر التجول للمراهقين من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"CT","page":8}},{"id":"ct-011","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what can police do on the spot when a 16- or 17-year-old driver commits certain serious violations?","o":["Take the license for 48 hours and remove the car","Only give a warning","Take away the car for one year","Nothing until a court date"],"h1":"It happens right away, at the side of the road.","h2":"In Connecticut police can take a 16- or 17-year-old driver's license on the spot for 48 hours for certain violations, and they may also remove the car.","p":"Right. The license is taken for 48 hours, and the car can be removed."},"es":{"q":"En Connecticut, ¿qué puede hacer la policía en el momento si un conductor de 16 o 17 años comete ciertas infracciones graves?","o":["Quitarle la licencia por 48 horas y retirar el carro","Solo darle una advertencia","Quitarle el carro por un año","Nada hasta la fecha de la corte"],"h1":"Ocurre de inmediato, al lado de la carretera.","h2":"En Connecticut la policía puede quitarle la licencia en el momento por 48 horas a un conductor de 16 o 17 años por ciertas infracciones, y también puede retirar el carro.","p":"Correcto. Le quitan la licencia por 48 horas y pueden retirar el carro."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的司机有某些严重违规时，警察可以当场怎么做？","o":["收走驾照 48 小时，并把车移走","只给警告","把车收走一年","开庭前什么都不做"],"h1":"它马上发生，就在路边。","h2":"在 Connecticut，16 岁或 17 岁的司机有某些违规时，警察可以当场收走驾照 48 小时，也可以把车移走。","p":"对。驾照被收走 48 小时，车也可能被移走。"},"vi":{"q":"Ở Connecticut, cảnh sát có thể làm gì ngay tại chỗ khi người lái 16 hoặc 17 tuổi phạm một số lỗi nghiêm trọng?","o":["Lấy bằng lái trong 48 giờ và mang xe đi","Chỉ cảnh cáo","Lấy xe trong một năm","Không làm gì cho đến ngày ra tòa"],"h1":"Việc này xảy ra ngay lập tức, bên lề đường.","h2":"Ở Connecticut, cảnh sát có thể lấy bằng lái của người lái 16 hoặc 17 tuổi ngay tại chỗ trong 48 giờ vì một số lỗi, và cũng có thể mang xe đi.","p":"Đúng. Bằng lái bị lấy trong 48 giờ, và xe có thể bị mang đi."},"tl":{"q":"Sa Connecticut, ano ang puwedeng gawin agad ng pulis kapag ang 16 o 17 taong gulang na driver ay gumawa ng ilang seryosong paglabag?","o":["Kunin ang lisensya nang 48 oras at alisin ang kotse","Magbigay lang ng babala","Kunin ang kotse nang isang taon","Wala hanggang sa araw ng korte"],"h1":"Nangyayari ito agad, sa gilid ng kalsada.","h2":"Sa Connecticut, puwedeng kunin agad ng pulis ang lisensya ng 16 o 17 taong gulang na driver nang 48 oras dahil sa ilang paglabag, at puwede rin nilang alisin ang kotse.","p":"Tama. Kinukuha ang lisensya nang 48 oras, at puwedeng alisin ang kotse."},"ar":{"q":"في Connecticut، ماذا يمكن للشرطة أن تفعل في الحال عندما يرتكب سائق عمره 16 أو 17 سنة بعض المخالفات الخطيرة؟","o":["أخذ الرخصة لمدة 48 ساعة وإبعاد السيارة","إعطاء تحذير فقط","أخذ السيارة لمدة سنة واحدة","لا شيء حتى موعد المحكمة"],"h1":"يحدث ذلك في الحال، على جانب الطريق.","h2":"في Connecticut يمكن للشرطة أن تأخذ رخصة السائق الذي عمره 16 أو 17 سنة في الحال لمدة 48 ساعة بسبب بعض المخالفات، ويمكنها أيضًا إبعاد السيارة.","p":"صحيح. تؤخذ الرخصة لمدة 48 ساعة، ويمكن إبعاد السيارة."},"ref":{"doc":"CT","page":null}},{"id":"ct-012","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, at what blood alcohol level is a driver under 21 considered to be driving illegally?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Connecticut a driver under 21 is driving illegally with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Connecticut, ¿con qué nivel de alcohol en la sangre se considera que un conductor menor de 21 maneja ilegalmente?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Connecticut un conductor menor de 21 años maneja ilegalmente con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Connecticut，21 岁以下的司机血液酒精浓度达到多少，就算违法驾驶？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它比成年人 0.08 的限制低很多。","h2":"在 Connecticut，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就是违法驾驶。","p":"对。21 岁以下的司机，限制是 0.02。"},"vi":{"q":"Ở Connecticut, người lái dưới 21 tuổi bị coi là lái xe bất hợp pháp ở nồng độ cồn trong máu bao nhiêu?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Connecticut, người lái dưới 21 tuổi lái xe bất hợp pháp khi nồng độ cồn trong máu từ 0.02 phần trăm trở lên.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Connecticut, sa anong blood alcohol level itinuturing na ilegal ang pagmamaneho ng driver na wala pang 21?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa 0.08 na limit para sa mga adult.","h2":"Sa Connecticut, ilegal ang pagmamaneho ng driver na wala pang 21 kapag ang blood alcohol level niya ay 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Connecticut، عند أي نسبة من الكحول في الدم يُعتبر السائق تحت 21 سنة يقود بشكل غير قانوني؟","o":["0.08 بالمئة","0.02 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Connecticut يقود السائق تحت 21 سنة بشكل غير قانوني إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين تحت 21 سنة الحد هو 0.02."},"ref":{"doc":"CT","page":31}},{"id":"ct-013","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, what must you do when you approach an emergency vehicle stopped on the shoulder and you are in the lane next to it?","o":["Keep the same speed and lane","Stop in your lane until it leaves","Speed up to pass it quickly","Slow down below the speed limit and move over one lane if it is safe"],"h1":"There are two steps: one with your speed, one with your lane.","h2":"In Connecticut you must slow to a safe speed below the posted limit and, if you are in the next lane, move over one lane when it is safe.","p":"Right. Slow down and move over."},"es":{"q":"En Connecticut, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido en el acotamiento si usted va en el carril de al lado?","o":["Seguir a la misma velocidad y en el mismo carril","Detenerse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Bajar la velocidad por debajo del límite y cambiarse un carril si es seguro"],"h1":"Son dos pasos: uno con su velocidad y otro con su carril.","h2":"En Connecticut usted debe bajar a una velocidad segura por debajo del límite y, si va en el carril de al lado, cambiarse un carril cuando sea seguro.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Connecticut，你接近一辆停在路肩上的急救车辆，而你在它旁边的车道上。你必须怎么做？","o":["保持同样的速度和车道","在你的车道停车，直到它离开","加速快点开过去","减速到低于限速，如果安全就换开一条车道"],"h1":"有两个步骤：一个和速度有关，一个和车道有关。","h2":"在 Connecticut，你必须减速到低于标示限速的安全速度；如果你在旁边的车道，安全时要换开一条车道。","p":"对。减速并换道（move over）。"},"vi":{"q":"Ở Connecticut, bạn phải làm gì khi đến gần xe cấp cứu đang dừng bên lề đường và bạn đang ở làn kế bên nó?","o":["Giữ nguyên tốc độ và làn đường","Dừng lại trong làn của bạn cho đến khi xe đó đi","Tăng tốc để vượt qua nhanh","Chạy chậm lại dưới tốc độ giới hạn và chuyển sang một làn khác nếu an toàn"],"h1":"Có hai bước: một về tốc độ, một về làn đường.","h2":"Ở Connecticut, bạn phải chạy chậm lại đến tốc độ an toàn dưới mức giới hạn đã ghi và, nếu bạn ở làn kế bên, chuyển sang một làn khác khi an toàn.","p":"Đúng. Chạy chậm lại và chuyển làn."},"tl":{"q":"Sa Connecticut, ano ang dapat mong gawin kapag papalapit ka sa emergency vehicle na nakahinto sa gilid ng kalsada at nasa katabing lane ka?","o":["Panatilihin ang parehong bilis at lane","Huminto sa lane mo hanggang umalis ito","Bilisan para malampasan ito agad","Bagalan nang mas mababa sa speed limit at lumipat ng isang lane kung ligtas"],"h1":"May dalawang hakbang: isa sa bilis mo, isa sa lane mo.","h2":"Sa Connecticut, dapat kang bumagal sa ligtas na bilis na mas mababa sa nakapaskil na limit at, kung nasa katabing lane ka, lumipat ng isang lane kapag ligtas.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Connecticut، ماذا يجب أن تفعل عندما تقترب من سيارة طوارئ متوقفة على جانب الطريق وأنت في الحارة المجاورة لها؟","o":["ابقَ على نفس السرعة ونفس الحارة","توقف في حارتك حتى تغادر","زِد سرعتك لتتجاوزها بسرعة","خفّف السرعة إلى أقل من الحد المسموح وانتقل حارة واحدة إذا كان ذلك آمنًا"],"h1":"هناك خطوتان: واحدة لسرعتك، وواحدة لحارتك.","h2":"في Connecticut يجب أن تخفّف السرعة إلى سرعة آمنة أقل من الحد المكتوب، وإذا كنت في الحارة المجاورة، يجب أن تنتقل حارة واحدة عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة وابتعد بحارة."},"ref":{"doc":"CT","page":16}},{"id":"ct-014","scope":"CT","cat":"signals","sign":null,"c":0,"en":{"q":"In Connecticut, when may you turn right on a red light?","o":["After a full stop, when it is safe and no sign forbids it","Never","Without stopping, if no one is coming","Only between midnight and 6 a.m."],"h1":"Some intersections have a sign that says you may not.","h2":"In Connecticut you may turn right on red only after a complete stop, when it is safe, and where no sign says \"No Turn on Red.\"","p":"Right. Stop first, then turn if it is safe and allowed."},"es":{"q":"En Connecticut, ¿cuándo puede girar a la derecha con la luz roja?","o":["Después de detenerse por completo, si es seguro y ninguna señal lo prohíbe","Nunca","Sin detenerse, si no viene nadie","Solo de medianoche a 6 a.m."],"h1":"Algunas intersecciones tienen una señal que lo prohíbe.","h2":"En Connecticut usted puede girar a la derecha con luz roja solo después de detenerse por completo, si es seguro y donde ninguna señal diga \"No Turn on Red\".","p":"Correcto. Primero se detiene, y luego gira si es seguro y está permitido."},"zh":{"q":"在 Connecticut，什么时候可以红灯右转？","o":["完全停车后，安全而且没有标志禁止时","从来不可以","没人来时不用停车","只在午夜到早上 6 点之间"],"h1":"有些路口有标志说你不可以。","h2":"在 Connecticut，只有完全停车以后、安全时，而且没有写着 \"No Turn on Red\"（红灯禁止转弯）的标志，你才可以红灯右转。","p":"对。先停车，安全又允许时再转弯。"},"vi":{"q":"Ở Connecticut, khi nào bạn được rẽ phải khi đèn đỏ?","o":["Sau khi dừng hẳn, khi an toàn và không có biển cấm","Không bao giờ","Không cần dừng, nếu không có ai đến","Chỉ từ nửa đêm đến 6 giờ sáng"],"h1":"Một số giao lộ có biển báo nói rằng bạn không được rẽ.","h2":"Ở Connecticut, bạn chỉ được rẽ phải khi đèn đỏ sau khi dừng hẳn, khi an toàn, và ở nơi không có biển \"No Turn on Red\" (cấm rẽ khi đèn đỏ).","p":"Đúng. Dừng trước, rồi rẽ nếu an toàn và được phép."},"tl":{"q":"Sa Connecticut, kailan ka puwedeng kumanan kapag pula ang ilaw?","o":["Pagkatapos huminto nang buo, kapag ligtas at walang karatulang nagbabawal","Hindi kailanman","Nang hindi humihinto, kung walang paparating","Mula hatinggabi hanggang 6 a.m. lang"],"h1":"May ilang interseksyon na may karatulang nagsasabing bawal.","h2":"Sa Connecticut, puwede kang kumanan sa pulang ilaw pagkatapos lang ng buong paghinto, kapag ligtas, at kung walang karatulang \"No Turn on Red.\"","p":"Tama. Huminto muna, saka kumanan kung ligtas at pinapayagan."},"ar":{"q":"في Connecticut، متى يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء؟","o":["بعد التوقف الكامل، عندما يكون الأمر آمنًا ولا توجد لافتة تمنع ذلك","أبدًا","دون توقف، إذا لم يكن أحد قادمًا","فقط بين منتصف الليل و6 صباحًا"],"h1":"بعض التقاطعات فيها لافتة تقول إنه لا يجوز لك ذلك.","h2":"في Connecticut يجوز لك أن تنعطف يمينًا عند الإشارة الحمراء فقط بعد التوقف الكامل، وعندما يكون ذلك آمنًا، وحيث لا توجد لافتة \"No Turn on Red\" (ممنوع الانعطاف عند الأحمر).","p":"صحيح. توقف أولًا، ثم انعطف إذا كان ذلك آمنًا ومسموحًا."},"ref":{"doc":"CT","page":15}},{"id":"ct-015","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who took a commercial or school driver education course wait after getting a permit before applying for a license?","o":["30 days","60 days","120 days","One year"],"h1":"It is about four months.","h2":"In Connecticut a 16- or 17-year-old who took a commercial or high school driver education course must wait at least 120 days after the permit before applying for a license.","p":"Right. The wait is 120 days with a course."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que tomó un curso de manejo comercial o escolar antes de pedir la licencia?","o":["30 días","60 días","120 días","Un año"],"h1":"Son unos cuatro meses.","h2":"En Connecticut un joven de 16 o 17 años que tomó un curso de manejo comercial o de la escuela debe esperar por lo menos 120 días después del permiso para pedir la licencia.","p":"Correcto. La espera es de 120 días con un curso."},"zh":{"q":"在 Connecticut，上过商业驾校或学校驾驶教育课程的 16 岁或 17 岁的人，拿到学习驾照后要等多久才能申请驾照？","o":["30 天","60 天","120 天","一年"],"h1":"它大约是四个月。","h2":"在 Connecticut，上过商业驾校或高中驾驶教育课程的 16 岁或 17 岁的人，拿到学习驾照后至少要等 120 天才能申请驾照。","p":"对。上过课程要等 120 天。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi đã học khóa giáo dục lái xe ở trường lái hoặc trường học phải chờ bao lâu sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái?","o":["30 ngày","60 ngày","120 ngày","Một năm"],"h1":"Khoảng bốn tháng.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi đã học khóa giáo dục lái xe ở trường lái hoặc trường trung học phải chờ ít nhất 120 ngày sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái.","p":"Đúng. Nếu có học khóa lái xe thì phải chờ 120 ngày."},"tl":{"q":"Sa Connecticut, gaano katagal dapat maghintay pagkatapos makakuha ng permit ang 16 o 17 taong gulang na kumuha ng driver education course sa driving school o paaralan bago mag-apply ng lisensya?","o":["30 araw","60 araw","120 araw","Isang taon"],"h1":"Mga apat na buwan ito.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na kumuha ng driver education course sa driving school o high school ay dapat maghintay nang hindi bababa sa 120 araw pagkatapos ng permit bago mag-apply ng lisensya.","p":"Tama. 120 araw ang paghihintay kapag may course."},"ar":{"q":"في Connecticut، كم يجب أن ينتظر من عمره 16 أو 17 سنة وأخذ دورة تعليم قيادة في مدرسة قيادة أو في المدرسة بعد الحصول على التصريح قبل أن يتقدّم بطلب رخصة؟","o":["30 يومًا","60 يومًا","120 يومًا","سنة واحدة"],"h1":"هي حوالي أربعة أشهر.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة وأخذ دورة تعليم قيادة في مدرسة قيادة أو في المدرسة الثانوية أن ينتظر 120 يومًا على الأقل بعد التصريح قبل أن يتقدّم بطلب رخصة.","p":"صحيح. الانتظار 120 يومًا مع الدورة."},"ref":{"doc":"CT","page":6}},{"id":"ct-016","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how long must a 16- or 17-year-old who chose home training wait after getting a permit before applying for a license?","o":["90 days","180 days","120 days","365 days"],"h1":"It is longer than the wait after a driving school course.","h2":"In Connecticut a 16- or 17-year-old who learns through home training must wait at least 180 days after the permit before applying for a license.","p":"Right. Home training means a 180-day wait."},"es":{"q":"En Connecticut, ¿cuánto debe esperar después de recibir el permiso un joven de 16 o 17 años que eligió aprender en casa antes de pedir la licencia?","o":["90 días","180 días","120 días","365 días"],"h1":"Es más tiempo que después de un curso en una escuela de manejo.","h2":"En Connecticut un joven de 16 o 17 años que aprende en casa debe esperar por lo menos 180 días después del permiso para pedir la licencia.","p":"Correcto. Aprender en casa significa esperar 180 días."},"zh":{"q":"在 Connecticut，选择在家训练的 16 岁或 17 岁的人，拿到学习驾照后要等多久才能申请驾照？","o":["90 天","180 天","120 天","365 天"],"h1":"它比上驾校课程后的等待时间长。","h2":"在 Connecticut，通过在家训练学开车的 16 岁或 17 岁的人，拿到学习驾照后至少要等 180 天才能申请驾照。","p":"对。在家训练要等 180 天。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi chọn tập lái tại nhà (home training) phải chờ bao lâu sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái?","o":["90 ngày","180 ngày","120 ngày","365 ngày"],"h1":"Thời gian này dài hơn thời gian chờ sau khóa học ở trường lái.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi tập lái tại nhà phải chờ ít nhất 180 ngày sau khi có giấy phép tập lái mới được nộp đơn xin bằng lái.","p":"Đúng. Tập lái tại nhà thì phải chờ 180 ngày."},"tl":{"q":"Sa Connecticut, gaano katagal dapat maghintay pagkatapos makakuha ng permit ang 16 o 17 taong gulang na pumili ng home training bago mag-apply ng lisensya?","o":["90 araw","180 araw","120 araw","365 araw"],"h1":"Mas matagal ito kaysa sa paghihintay pagkatapos ng course sa driving school.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na natuto sa home training ay dapat maghintay nang hindi bababa sa 180 araw pagkatapos ng permit bago mag-apply ng lisensya.","p":"Tama. Sa home training, 180 araw ang paghihintay."},"ar":{"q":"في Connecticut، كم يجب أن ينتظر من عمره 16 أو 17 سنة واختار التدريب المنزلي (home training) بعد الحصول على التصريح قبل أن يتقدّم بطلب رخصة؟","o":["90 يومًا","180 يومًا","120 يومًا","365 يومًا"],"h1":"هو أطول من الانتظار بعد دورة مدرسة القيادة.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة ويتعلّم بالتدريب المنزلي أن ينتظر 180 يومًا على الأقل بعد التصريح قبل أن يتقدّم بطلب رخصة.","p":"صحيح. التدريب المنزلي يعني انتظار 180 يومًا."},"ref":{"doc":"CT","page":6}},{"id":"ct-017","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how many hours of behind-the-wheel training must a 16- or 17-year-old complete?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"It is more than the 30 hours of classroom study.","h2":"In Connecticut a 16- or 17-year-old must complete 40 hours of behind-the-wheel training, along with 30 hours of classroom study.","p":"Right. 40 hours behind the wheel."},"es":{"q":"En Connecticut, ¿cuántas horas de práctica al volante debe completar un joven de 16 o 17 años?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Son más que las 30 horas de estudio en clase.","h2":"En Connecticut un joven de 16 o 17 años debe completar 40 horas de práctica al volante, además de 30 horas de estudio en clase.","p":"Correcto. 40 horas al volante."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人必须完成多少小时的实际上车驾驶训练？","o":["10 小时","20 小时","30 小时","40 小时"],"h1":"它比 30 小时的课堂学习多。","h2":"在 Connecticut，16 岁或 17 岁的人必须完成 40 小时的实际上车驾驶训练，另外还有 30 小时的课堂学习。","p":"对。实际开车 40 小时。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành bao nhiêu giờ tập lái thực tế sau tay lái?","o":["10 giờ","20 giờ","30 giờ","40 giờ"],"h1":"Nhiều hơn 30 giờ học lý thuyết trong lớp.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành 40 giờ tập lái thực tế sau tay lái, cùng với 30 giờ học lý thuyết trong lớp.","p":"Đúng. 40 giờ sau tay lái."},"tl":{"q":"Sa Connecticut, ilang oras ng behind-the-wheel training (aktwal na pagmamaneho) ang dapat tapusin ng 16 o 17 taong gulang?","o":["10 oras","20 oras","30 oras","40 oras"],"h1":"Mas marami ito kaysa sa 30 oras ng pag-aaral sa klase.","h2":"Sa Connecticut, ang 16 o 17 taong gulang ay dapat tumapos ng 40 oras ng behind-the-wheel training, kasama ang 30 oras ng pag-aaral sa klase.","p":"Tama. 40 oras sa likod ng manibela."},"ar":{"q":"في Connecticut، كم ساعة من التدريب العملي خلف المقود يجب أن يُكمل من عمره 16 أو 17 سنة؟","o":["10 ساعات","20 ساعة","30 ساعة","40 ساعة"],"h1":"هي أكثر من 30 ساعة الدراسة في الصف.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة أن يُكمل 40 ساعة من التدريب العملي خلف المقود، بالإضافة إلى 30 ساعة من الدراسة في الصف.","p":"صحيح. 40 ساعة خلف المقود."},"ref":{"doc":"CT","page":6}},{"id":"ct-018","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, how many hours of driver education study must a 16- or 17-year-old complete?","o":["30 hours","10 hours","15 hours","50 hours"],"h1":"It is ten hours less than the behind-the-wheel training.","h2":"In Connecticut a 16- or 17-year-old must complete 30 hours of driver education study, which includes the 8-hour safe driving course.","p":"Right. 30 hours of study."},"es":{"q":"En Connecticut, ¿cuántas horas de estudio de manejo debe completar un joven de 16 o 17 años?","o":["30 horas","10 horas","15 horas","50 horas"],"h1":"Son diez horas menos que la práctica al volante.","h2":"En Connecticut un joven de 16 o 17 años debe completar 30 horas de estudio de manejo, que incluyen el curso de manejo seguro de 8 horas.","p":"Correcto. 30 horas de estudio."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人必须完成多少小时的驾驶教育学习？","o":["30 小时","10 小时","15 小时","50 小时"],"h1":"它比实际上车驾驶训练少十小时。","h2":"在 Connecticut，16 岁或 17 岁的人必须完成 30 小时的驾驶教育学习，其中包括 8 小时的安全驾驶课。","p":"对。学习 30 小时。"},"vi":{"q":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành bao nhiêu giờ học giáo dục lái xe?","o":["30 giờ","10 giờ","15 giờ","50 giờ"],"h1":"Ít hơn mười giờ so với số giờ tập lái thực tế sau tay lái.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi phải hoàn thành 30 giờ học giáo dục lái xe, bao gồm khóa học lái xe an toàn 8 giờ.","p":"Đúng. 30 giờ học."},"tl":{"q":"Sa Connecticut, ilang oras ng pag-aaral ng driver education ang dapat tapusin ng 16 o 17 taong gulang?","o":["30 oras","10 oras","15 oras","50 oras"],"h1":"Sampung oras itong mas kaunti kaysa sa behind-the-wheel training.","h2":"Sa Connecticut, ang 16 o 17 taong gulang ay dapat tumapos ng 30 oras ng pag-aaral ng driver education, kasama na ang 8 oras na safe driving course.","p":"Tama. 30 oras ng pag-aaral."},"ar":{"q":"في Connecticut، كم ساعة من دراسة تعليم القيادة يجب أن يُكمل من عمره 16 أو 17 سنة؟","o":["30 ساعة","10 ساعات","15 ساعة","50 ساعة"],"h1":"هي أقل بعشر ساعات من التدريب العملي خلف المقود.","h2":"في Connecticut يجب على من عمره 16 أو 17 سنة أن يُكمل 30 ساعة من دراسة تعليم القيادة، وتشمل دورة القيادة الآمنة لمدة 8 ساعات.","p":"صحيح. 30 ساعة من الدراسة."},"ref":{"doc":"CT","page":6}},{"id":"ct-019","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, is there a night curfew for a driver with a learner's permit?","o":["Yes, from 9 p.m. to 6 a.m.","Yes, from 11 p.m. to 5 a.m.","No curfew, but a qualified trainer must always be in the car","No curfew, and the permit driver may drive alone"],"h1":"The permit rule is about who is beside you, not the clock.","h2":"In Connecticut a permit holder has no curfew, but must always drive with a qualified trainer.","p":"Right. No curfew, but never alone."},"es":{"q":"En Connecticut, ¿hay horario de restricción nocturna para quien tiene permiso de aprendiz?","o":["Sí, de 9 p.m. a 6 a.m.","Sí, de 11 p.m. a 5 a.m.","No hay horario, pero siempre debe ir un instructor calificado en el carro","No hay horario, y puede manejar solo"],"h1":"La regla del permiso es sobre quién va a su lado, no sobre la hora.","h2":"En Connecticut quien tiene permiso de aprendiz no tiene horario restringido, pero siempre debe manejar con un instructor calificado.","p":"Correcto. Sin horario, pero nunca solo."},"zh":{"q":"在 Connecticut，持学习驾照的司机有夜间宵禁吗？","o":["有，晚上 9 点到早上 6 点","有，晚上 11 点到早上 5 点","没有宵禁，但车里一定要有合格的指导人","没有宵禁，持学习驾照的司机可以单独开车"],"h1":"学习驾照的规定和谁坐在你旁边有关，和时间无关。","h2":"在 Connecticut，持学习驾照的人没有宵禁，但必须一直和合格的指导人一起开车。","p":"对。没有宵禁，但永远不能单独开车。"},"vi":{"q":"Ở Connecticut, người lái có giấy phép tập lái (learner's permit) có bị giới nghiêm ban đêm không?","o":["Có, từ 9 giờ tối đến 6 giờ sáng","Có, từ 11 giờ tối đến 5 giờ sáng","Không có giới nghiêm, nhưng luôn phải có người hướng dẫn đủ điều kiện trong xe","Không có giới nghiêm, và người tập lái được lái một mình"],"h1":"Luật của giấy phép tập lái là về người ngồi bên cạnh bạn, không phải về giờ giấc.","h2":"Ở Connecticut, người có giấy phép tập lái không bị giới nghiêm, nhưng luôn phải lái xe cùng người hướng dẫn đủ điều kiện.","p":"Đúng. Không có giới nghiêm, nhưng không bao giờ lái một mình."},"tl":{"q":"Sa Connecticut, may curfew ba sa gabi para sa driver na may learner's permit?","o":["Oo, mula 9 p.m. hanggang 6 a.m.","Oo, mula 11 p.m. hanggang 5 a.m.","Walang curfew, pero dapat laging may qualified trainer sa kotse","Walang curfew, at puwedeng magmaneho nang mag-isa ang may permit"],"h1":"Ang patakaran sa permit ay tungkol sa kung sino ang katabi mo, hindi sa oras.","h2":"Sa Connecticut, walang curfew ang may permit, pero dapat lagi siyang nagmamaneho kasama ang qualified trainer.","p":"Tama. Walang curfew, pero hindi kailanman nag-iisa."},"ar":{"q":"في Connecticut، هل يوجد حظر تجول ليلي لسائق يحمل تصريح التعلّم (learner's permit)؟","o":["نعم، من 9 مساءً إلى 6 صباحًا","نعم، من 11 مساءً إلى 5 صباحًا","لا يوجد حظر تجول، لكن يجب أن يكون مدرّب مؤهَّل في السيارة دائمًا","لا يوجد حظر تجول، ويمكن لسائق التصريح أن يقود وحده"],"h1":"قاعدة التصريح تتعلق بمن يجلس بجانبك، لا بالساعة.","h2":"في Connecticut لا يوجد حظر تجول على حامل التصريح، لكن يجب أن يقود دائمًا مع مدرّب مؤهَّل.","p":"صحيح. لا حظر تجول، لكن لا قيادة وحدك أبدًا."},"ref":{"doc":"CT","page":null}},{"id":"ct-020","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, who must be with a 16- or 17-year-old when taking the knowledge test, if they do not send a signed consent form?","o":["A teacher","A parent or guardian","A driving instructor","No one"],"h1":"It is the adult responsible for the teen.","h2":"In Connecticut a parent or guardian must come to the knowledge test with an applicant under 18, or fill out a consent form.","p":"Right. A parent or guardian gives consent."},"es":{"q":"En Connecticut, ¿quién debe acompañar a un joven de 16 o 17 años al examen teórico, si no envía un formulario de consentimiento firmado?","o":["Un maestro","Su padre, madre o tutor","Un instructor de manejo","Nadie"],"h1":"Es el adulto responsable del joven.","h2":"En Connecticut el padre, la madre o el tutor debe ir al examen teórico con un solicitante menor de 18, o llenar un formulario de consentimiento.","p":"Correcto. El padre, la madre o el tutor da su consentimiento."},"zh":{"q":"在 Connecticut，16 岁或 17 岁的人如果没有交签字的同意书，考笔试时谁必须陪同？","o":["老师","父母或监护人","驾驶教练","不需要任何人"],"h1":"它是对这个青少年负责的成年人。","h2":"在 Connecticut，18 岁以下的申请人考笔试时，父母或监护人必须一起来，或者填写同意书。","p":"对。由父母或监护人表示同意。"},"vi":{"q":"Ở Connecticut, ai phải đi cùng người 16 hoặc 17 tuổi khi thi lý thuyết, nếu họ không gửi mẫu đơn đồng ý có chữ ký?","o":["Một giáo viên","Cha mẹ hoặc người giám hộ","Một giáo viên dạy lái xe","Không ai cả"],"h1":"Đó là người lớn chịu trách nhiệm cho thiếu niên.","h2":"Ở Connecticut, cha mẹ hoặc người giám hộ phải đến buổi thi lý thuyết cùng người dưới 18 tuổi, hoặc điền mẫu đơn đồng ý.","p":"Đúng. Cha mẹ hoặc người giám hộ cho phép."},"tl":{"q":"Sa Connecticut, sino ang dapat kasama ng 16 o 17 taong gulang sa pagkuha ng knowledge test, kung hindi sila nagpadala ng pinirmahang consent form?","o":["Isang guro","Magulang o guardian","Isang driving instructor","Wala"],"h1":"Ito ang adult na responsable sa teenager.","h2":"Sa Connecticut, ang magulang o guardian ay dapat sumama sa knowledge test ng aplikanteng wala pang 18, o sumagot ng consent form.","p":"Tama. Ang magulang o guardian ang nagbibigay ng pahintulot."},"ar":{"q":"في Connecticut، من يجب أن يكون مع من عمره 16 أو 17 سنة عند أداء الاختبار النظري، إذا لم يرسل نموذج موافقة موقَّعًا؟","o":["معلّم","أحد الوالدين أو الوصي","مدرّب قيادة","لا أحد"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Connecticut يجب أن يأتي أحد الوالدين أو الوصي إلى الاختبار النظري مع المتقدّم الذي عمره أقل من 18 سنة، أو أن يملأ نموذج موافقة.","p":"صحيح. أحد الوالدين أو الوصي يعطي الموافقة."},"ref":{"doc":"CT","page":null}},{"id":"ct-021","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how long is a learner's permit valid if you do not get a license first?","o":["6 months","1 year","18 months","2 years"],"h1":"It lasts longer than one year.","h2":"In Connecticut a learner's permit is valid for 2 years, or until you get your driver's license, whichever comes first.","p":"Right. The permit lasts up to 2 years."},"es":{"q":"En Connecticut, ¿por cuánto tiempo es válido un permiso de aprendizaje si usted no obtiene la licencia antes?","o":["6 meses","1 año","18 meses","2 años"],"h1":"Dura más de un año.","h2":"En Connecticut un permiso de aprendizaje es válido por 2 años, o hasta que usted obtenga su licencia de manejo, lo que ocurra primero.","p":"Correcto. El permiso dura hasta 2 años."},"zh":{"q":"在 Connecticut，如果你还没拿到驾照，学习驾照的有效期是多久？","o":["6 个月","1 年","18 个月","2 年"],"h1":"它的有效期比一年更长。","h2":"在 Connecticut，学习驾照的有效期是 2 年，或者到你拿到驾照为止，以先到者为准。","p":"对。学习驾照最长有效 2 年。"},"vi":{"q":"Ở Connecticut, giấy phép tập lái (learner's permit) có hiệu lực bao lâu nếu bạn chưa lấy bằng lái trước đó?","o":["6 tháng","1 năm","18 tháng","2 năm"],"h1":"Nó kéo dài hơn một năm.","h2":"Ở Connecticut, giấy phép tập lái có hiệu lực 2 năm, hoặc cho đến khi bạn lấy được bằng lái, tùy điều nào đến trước.","p":"Đúng. Giấy phép tập lái có hiệu lực tối đa 2 năm."},"tl":{"q":"Sa Connecticut, gaano katagal valid ang learner's permit kung hindi ka muna nakakuha ng lisensya?","o":["6 buwan","1 taon","18 buwan","2 taon"],"h1":"Mas matagal ito kaysa isang taon.","h2":"Sa Connecticut, valid ang learner's permit nang 2 taon, o hanggang makuha mo ang iyong driver's license, alinman ang mauna.","p":"Tama. Tumatagal ang permit nang hanggang 2 taon."},"ar":{"q":"في Connecticut، كم مدة صلاحية تصريح التعلّم (learner's permit) إذا لم تحصل على رخصة القيادة قبل ذلك؟","o":["6 أشهر","سنة واحدة (1)","18 شهرًا","سنتان (2)"],"h1":"مدته أطول من سنة واحدة.","h2":"في Connecticut يكون تصريح التعلّم صالحًا لمدة 2 سنة، أو حتى تحصل على رخصة القيادة، أيهما يأتي أولًا.","p":"صحيح. يبقى التصريح صالحًا حتى 2 سنة."},"ref":{"doc":"CT","page":5}},{"id":"ct-022","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how many questions must you answer correctly to pass the 25-question knowledge test?","o":["15","20","22","25"],"h1":"You may miss a few questions, but not many.","h2":"In Connecticut you must answer 20 of the 25 knowledge test questions correctly to pass.","p":"Right. You need 20 correct answers out of 25."},"es":{"q":"En Connecticut, ¿cuántas preguntas debe contestar bien para aprobar el examen teórico de 25 preguntas?","o":["15","20","22","25"],"h1":"Puede fallar algunas preguntas, pero no muchas.","h2":"En Connecticut usted debe contestar bien 20 de las 25 preguntas del examen teórico para aprobar.","p":"Correcto. Necesita 20 respuestas correctas de 25."},"zh":{"q":"在 Connecticut，25 道题的笔试要答对几道题才能通过？","o":["15","20","22","25"],"h1":"你可以答错几道题，但不能错太多。","h2":"在 Connecticut，笔试 25 道题中你必须答对 20 道才能通过。","p":"对。25 道题中要答对 20 道。"},"vi":{"q":"Ở Connecticut, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi lý thuyết 25 câu?","o":["15","20","22","25"],"h1":"Bạn có thể sai vài câu, nhưng không được sai nhiều.","h2":"Ở Connecticut, bạn phải trả lời đúng 20 trên 25 câu của bài thi lý thuyết để đậu.","p":"Đúng. Bạn cần 20 câu đúng trên 25 câu."},"tl":{"q":"Sa Connecticut, ilang tanong ang dapat mong masagot nang tama para pumasa sa 25-tanong na knowledge test?","o":["15","20","22","25"],"h1":"Puwede kang magkamali sa ilang tanong, pero hindi sa marami.","h2":"Sa Connecticut, dapat mong masagot nang tama ang 20 sa 25 tanong ng knowledge test para pumasa.","p":"Tama. Kailangan mo ng 20 tamang sagot sa 25."},"ar":{"q":"في Connecticut، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في الاختبار النظري الذي فيه 25 سؤالًا؟","o":["15","20","22","25"],"h1":"يمكنك أن تخطئ في بعض الأسئلة، لكن ليس في كثير منها.","h2":"في Connecticut يجب أن تجيب إجابة صحيحة عن 20 من أسئلة الاختبار النظري الـ 25 حتى تنجح.","p":"صحيح. تحتاج إلى 20 إجابة صحيحة من 25."},"ref":{"doc":"CT","page":5}},{"id":"ct-024","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, how must a child under age 2, or under 30 pounds, ride in a car?","o":["In a rear-facing car seat with a 5-point harness","In a booster seat","In a forward-facing seat with a lap belt","With an adult seat belt"],"h1":"The smallest children face the back of the car.","h2":"In Connecticut a child under age 2, or under 30 pounds, must ride in a rear-facing car seat with a 5-point harness.","p":"Right. Babies and small toddlers ride rear-facing."},"es":{"q":"En Connecticut, ¿cómo debe viajar en el carro un niño menor de 2 años o que pese menos de 30 libras?","o":["En un asiento mirando hacia atrás con arnés de 5 puntos","En un asiento elevador","En un asiento mirando hacia adelante con cinturón de cadera","Con un cinturón de seguridad de adulto"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Connecticut un niño menor de 2 años, o que pese menos de 30 libras, debe viajar en un asiento mirando hacia atrás con arnés de 5 puntos.","p":"Correcto. Los bebés y niños pequeños viajan mirando hacia atrás."},"zh":{"q":"在 Connecticut，2 岁以下或体重不到 30 磅的孩子坐车时必须怎么坐？","o":["坐在后向的儿童安全座椅里，用 5 点式安全带","坐在增高座椅里","坐在前向座椅里，用腰部安全带","用大人的安全带"],"h1":"最小的孩子要面向车的后面。","h2":"在 Connecticut，2 岁以下或体重不到 30 磅的孩子必须坐在后向的儿童安全座椅里，并用 5 点式安全带。","p":"对。婴儿和小幼儿要面向后坐。"},"vi":{"q":"Ở Connecticut, trẻ dưới 2 tuổi, hoặc nặng dưới 30 pound, phải ngồi trên xe như thế nào?","o":["Trong ghế xe quay mặt về phía sau, có dây đai 5 điểm","Trong ghế nâng (booster seat)","Trong ghế quay mặt về phía trước, có dây an toàn ngang hông","Với dây an toàn của người lớn"],"h1":"Những trẻ nhỏ nhất ngồi quay mặt về phía sau xe.","h2":"Ở Connecticut, trẻ dưới 2 tuổi, hoặc nặng dưới 30 pound, phải ngồi trong ghế xe quay mặt về phía sau, có dây đai 5 điểm.","p":"Đúng. Em bé và trẻ nhỏ ngồi quay mặt về phía sau."},"tl":{"q":"Sa Connecticut, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang, o wala pang 30 pounds?","o":["Sa rear-facing na car seat na may 5-point harness","Sa booster seat","Sa forward-facing na upuan na may lap belt","Gamit ang seat belt ng adult"],"h1":"Ang pinakamaliliit na bata ay nakaharap sa likod ng kotse.","h2":"Sa Connecticut, ang batang wala pang 2 taong gulang, o wala pang 30 pounds, ay dapat sumakay sa rear-facing na car seat na may 5-point harness.","p":"Tama. Ang mga baby at maliliit na bata ay nakaharap sa likod."},"ar":{"q":"في Connecticut، كيف يجب أن يركب في السيارة طفل عمره أقل من 2 سنة، أو وزنه أقل من 30 رطلًا؟","o":["في مقعد سيارة مواجه للخلف مع حزام من 5 نقاط","في مقعد رافع (booster seat)","في مقعد مواجه للأمام مع حزام حول الخصر","بحزام أمان الكبار"],"h1":"أصغر الأطفال يكون وجههم نحو مؤخرة السيارة.","h2":"في Connecticut يجب أن يركب الطفل الذي عمره أقل من 2 سنة، أو وزنه أقل من 30 رطلًا، في مقعد سيارة مواجه للخلف مع حزام من 5 نقاط.","p":"صحيح. الرضّع والأطفال الصغار يركبون ووجههم نحو الخلف."},"ref":{"doc":"CT","page":12}},{"id":"ct-025","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, what happens to your license if you refuse a blood, breath or urine test after a DUI arrest?","o":["Nothing, if you pass a walking test","It is suspended for at least 45 days, and you need an ignition interlock device","You get a warning letter","It is suspended for 7 days"],"h1":"The penalty applies at any age, and it is serious.","h2":"In Connecticut refusing the test means your license is suspended for at least 45 days, and you must use an ignition interlock device to get it back.","p":"Right. Refusing brings at least a 45-day suspension and an interlock device."},"es":{"q":"En Connecticut, ¿qué pasa con su licencia si se niega a una prueba de sangre, aliento u orina después de un arresto por manejar bajo la influencia?","o":["Nada, si pasa una prueba de caminar","Se suspende por al menos 45 días y necesita un dispositivo de bloqueo de encendido","Recibe una carta de advertencia","Se suspende por 7 días"],"h1":"La sanción se aplica a cualquier edad, y es seria.","h2":"En Connecticut negarse a la prueba significa que su licencia se suspende por al menos 45 días, y debe usar un dispositivo de bloqueo de encendido para recuperarla.","p":"Correcto. Negarse trae una suspensión de al menos 45 días y un dispositivo de bloqueo."},"zh":{"q":"在 Connecticut，因酒驾或药驾被逮捕后，如果你拒绝验血、呼气或验尿，你的驾照会怎么样？","o":["如果你通过走路测试，就没事","至少被吊销 45 天，而且你需要安装点火联锁装置","你会收到一封警告信","被吊销 7 天"],"h1":"不管几岁都会受罚，而且处罚很重。","h2":"在 Connecticut，拒绝检测意味着你的驾照至少被吊销 45 天，而且你必须使用点火联锁装置才能拿回驾照。","p":"对。拒绝检测会被吊销至少 45 天，还要装联锁装置。"},"vi":{"q":"Ở Connecticut, điều gì xảy ra với bằng lái của bạn nếu bạn từ chối xét nghiệm máu, hơi thở hoặc nước tiểu sau khi bị bắt vì lái xe khi say (DUI)?","o":["Không có gì, nếu bạn qua được bài kiểm tra đi bộ","Bị treo ít nhất 45 ngày, và bạn cần thiết bị khóa khởi động xe (ignition interlock)","Bạn nhận một thư cảnh cáo","Bị treo 7 ngày"],"h1":"Hình phạt áp dụng cho mọi lứa tuổi, và nó rất nặng.","h2":"Ở Connecticut, từ chối xét nghiệm nghĩa là bằng lái của bạn bị treo ít nhất 45 ngày, và bạn phải dùng thiết bị khóa khởi động xe để lấy lại bằng.","p":"Đúng. Từ chối xét nghiệm sẽ bị treo bằng ít nhất 45 ngày và phải dùng thiết bị khóa khởi động."},"tl":{"q":"Sa Connecticut, ano ang mangyayari sa lisensya mo kung tatanggi ka sa blood, breath o urine test pagkatapos kang arestuhin dahil sa DUI?","o":["Wala, kung papasa ka sa walking test","Masususpinde ito nang hindi bababa sa 45 araw, at kailangan mo ng ignition interlock device","Makakatanggap ka ng warning letter","Masususpinde ito nang 7 araw"],"h1":"Ang parusa ay para sa kahit anong edad, at mabigat ito.","h2":"Sa Connecticut, kapag tumanggi ka sa test, masususpinde ang lisensya mo nang hindi bababa sa 45 araw, at dapat kang gumamit ng ignition interlock device para maibalik ito.","p":"Tama. Ang pagtanggi ay may suspensyon na hindi bababa sa 45 araw at interlock device."},"ar":{"q":"في Connecticut، ماذا يحدث لرخصتك إذا رفضت فحص الدم أو النَّفَس أو البول بعد القبض عليك بسبب القيادة تحت تأثير الكحول أو المخدرات (DUI)؟","o":["لا شيء، إذا نجحت في اختبار المشي","تُوقَف لمدة 45 يومًا على الأقل، وتحتاج إلى جهاز قفل التشغيل (ignition interlock)","تحصل على رسالة تحذير","تُوقَف لمدة 7 أيام"],"h1":"العقوبة تنطبق على كل الأعمار، وهي شديدة.","h2":"في Connecticut رفض الفحص يعني أن رخصتك تُوقَف لمدة 45 يومًا على الأقل، ويجب أن تستخدم جهاز قفل التشغيل حتى تستعيدها.","p":"صحيح. الرفض يؤدي إلى إيقاف لمدة 45 يومًا على الأقل وجهاز قفل التشغيل."},"ref":{"doc":"CT","page":33}},{"id":"ct-026","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, what must you do when an ice cream truck has its lights flashing and its stop arm out?","o":["Honk and pass slowly","Pass only on the left side","Keep going if no children are in the road","Stop at least 10 feet away, then pass at 5 mph or less"],"h1":"Children may run out to the truck, so you must stop first.","h2":"In Connecticut you must stop at least 10 feet from the ice cream truck, then you may pass at no more than 5 mph while yielding to people crossing.","p":"Right. Stop 10 feet away, then pass at 5 mph or less."},"es":{"q":"En Connecticut, ¿qué debe hacer cuando un camión de helados tiene las luces intermitentes encendidas y el brazo de parada afuera?","o":["Tocar la bocina y pasar despacio","Pasar solo por el lado izquierdo","Seguir si no hay niños en la calle","Parar al menos a 10 pies y luego pasar a 5 mph o menos"],"h1":"Los niños pueden correr hacia el camión, así que primero debe parar.","h2":"En Connecticut usted debe parar al menos a 10 pies del camión de helados, y luego puede pasar a no más de 5 mph, cediendo el paso a las personas que cruzan.","p":"Correcto. Pare a 10 pies y luego pase a 5 mph o menos."},"zh":{"q":"在 Connecticut，当冰淇淋车的灯在闪、停车臂伸出来时，你必须怎么做？","o":["按喇叭，慢慢开过去","只能从左边开过去","如果路上没有孩子，就继续开","在至少 10 英尺外停车，然后以 5 mph 或更慢的速度开过去"],"h1":"孩子可能会跑向冰淇淋车，所以你必须先停车。","h2":"在 Connecticut，你必须在离冰淇淋车至少 10 英尺的地方停车，然后才可以用不超过 5 mph 的速度开过去，同时让过路的人先走。","p":"对。在 10 英尺外停车，然后以 5 mph 或更慢开过去。"},"vi":{"q":"Ở Connecticut, bạn phải làm gì khi xe bán kem đang nháy đèn và đưa cần báo dừng ra ngoài?","o":["Bấm còi và chạy qua chậm","Chỉ chạy qua ở bên trái","Cứ chạy tiếp nếu không có trẻ em trên đường","Dừng cách xa ít nhất 10 feet, rồi chạy qua với tốc độ 5 mph hoặc thấp hơn"],"h1":"Trẻ em có thể chạy ra xe kem, nên bạn phải dừng trước.","h2":"Ở Connecticut, bạn phải dừng cách xe bán kem ít nhất 10 feet, rồi mới được chạy qua với tốc độ không quá 5 mph và nhường đường cho người đang băng qua.","p":"Đúng. Dừng cách 10 feet, rồi chạy qua với tốc độ 5 mph hoặc thấp hơn."},"tl":{"q":"Sa Connecticut, ano ang dapat mong gawin kapag ang ice cream truck ay may kumikislap na ilaw at nakalabas ang stop arm nito?","o":["Bumusina at lumampas nang dahan-dahan","Lumampas lang sa kaliwang gilid","Tumuloy kung walang bata sa kalsada","Huminto nang hindi bababa sa 10 feet ang layo, saka lumampas sa 5 mph o mas mabagal"],"h1":"Puwedeng tumakbo ang mga bata papunta sa truck, kaya dapat huminto ka muna.","h2":"Sa Connecticut, dapat kang huminto nang hindi bababa sa 10 feet mula sa ice cream truck, saka ka puwedeng lumampas nang hindi hihigit sa 5 mph habang pinauuna ang mga taong tumatawid.","p":"Tama. Huminto nang 10 feet ang layo, saka lumampas sa 5 mph o mas mabagal."},"ar":{"q":"في Connecticut، ماذا يجب أن تفعل عندما تكون أضواء شاحنة المثلجات (الآيس كريم) تومض وذراع التوقف خارجًا منها؟","o":["أطلق البوق وتجاوزها ببطء","تجاوزها من الجهة اليسرى فقط","استمر إذا لم يكن هناك أطفال في الطريق","توقف على بُعد 10 أقدام على الأقل، ثم تجاوزها بسرعة 5 mph أو أقل"],"h1":"قد يركض الأطفال نحو الشاحنة، لذلك يجب أن تتوقف أولًا.","h2":"في Connecticut يجب أن تتوقف على بُعد 10 أقدام على الأقل من شاحنة المثلجات، ثم يجوز لك أن تتجاوزها بسرعة لا تزيد على 5 mph مع إعطاء حق المرور للناس الذين يعبرون.","p":"صحيح. توقف على بُعد 10 أقدام، ثم تجاوز بسرعة 5 mph أو أقل."},"ref":{"doc":"CT","page":18}},{"id":"ct-027","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, how high can the fine be for speeding or endangering a worker in a highway work zone?","o":["Up to $100","Up to $1,000","Up to $250","Up to $500"],"h1":"Work zone fines are very high to protect workers.","h2":"In Connecticut speeding or endangering a highway worker in a work zone can bring a fine of up to $1,000, plus points on your license.","p":"Right. The fine can be as high as $1,000."},"es":{"q":"En Connecticut, ¿hasta cuánto puede ser la multa por exceso de velocidad o por poner en peligro a un trabajador en una zona de obras en la carretera?","o":["Hasta $100","Hasta $1,000","Hasta $250","Hasta $500"],"h1":"Las multas en zonas de obras son muy altas para proteger a los trabajadores.","h2":"En Connecticut el exceso de velocidad o poner en peligro a un trabajador en una zona de obras puede traer una multa de hasta $1,000, además de puntos en su licencia.","p":"Correcto. La multa puede llegar a $1,000."},"zh":{"q":"在 Connecticut，在公路施工区超速或危及工人安全，罚款最高可以是多少？","o":["最高 $100","最高 $1,000","最高 $250","最高 $500"],"h1":"为了保护工人，施工区的罚款非常高。","h2":"在 Connecticut，在施工区超速或危及公路工人安全，最高可罚款 $1,000，驾照还会被记分。","p":"对。罚款最高可达 $1,000。"},"vi":{"q":"Ở Connecticut, tiền phạt cao nhất là bao nhiêu khi chạy quá tốc độ hoặc gây nguy hiểm cho công nhân trong khu vực công trường trên xa lộ?","o":["Tối đa $100","Tối đa $1,000","Tối đa $250","Tối đa $500"],"h1":"Tiền phạt ở khu vực công trường rất cao để bảo vệ công nhân.","h2":"Ở Connecticut, chạy quá tốc độ hoặc gây nguy hiểm cho công nhân xa lộ trong khu vực công trường có thể bị phạt tối đa $1,000, cộng thêm điểm vào bằng lái.","p":"Đúng. Tiền phạt có thể lên đến $1,000."},"tl":{"q":"Sa Connecticut, gaano kalaki ang puwedeng multa sa sobrang bilis o sa paglalagay sa panganib ng isang trabahador sa highway work zone?","o":["Hanggang $100","Hanggang $1,000","Hanggang $250","Hanggang $500"],"h1":"Napakalaki ng multa sa work zone para protektahan ang mga trabahador.","h2":"Sa Connecticut, ang sobrang bilis o paglalagay sa panganib ng trabahador sa highway work zone ay puwedeng magresulta sa multang hanggang $1,000, at may dagdag na points sa lisensya mo.","p":"Tama. Puwedeng umabot sa $1,000 ang multa."},"ar":{"q":"في Connecticut، إلى كم يمكن أن تصل الغرامة على السرعة الزائدة أو تعريض عامل للخطر في منطقة أعمال على الطريق السريع؟","o":["حتى $100","حتى $1,000","حتى $250","حتى $500"],"h1":"غرامات مناطق الأعمال عالية جدًا لحماية العمال.","h2":"في Connecticut يمكن أن تؤدي السرعة الزائدة أو تعريض عامل الطريق للخطر في منطقة أعمال إلى غرامة تصل إلى $1,000، بالإضافة إلى نقاط على رخصتك.","p":"صحيح. يمكن أن تصل الغرامة إلى $1,000."},"ref":{"doc":"CT","page":15}},{"id":"ct-028","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, how much space must you leave between your car and a bicycle when you pass it?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"Think of about one long step to the side.","h2":"In Connecticut, you must leave at least three feet of space when you pass a bicycle.","p":"Right. Give a bicycle at least three feet when you pass."},"es":{"q":"En Connecticut, ¿cuánto espacio debe dejar entre su auto y una bicicleta al rebasarla?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 10 pies"],"h1":"Piense en un paso largo hacia un lado.","h2":"En Connecticut, debe dejar al menos tres pies de espacio al rebasar una bicicleta.","p":"Correcto. Deje al menos tres pies al rebasar una bicicleta."},"zh":{"q":"在 Connecticut，超过自行车时，你的车和自行车之间必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"想一想大约向旁边跨出一大步的距离。","h2":"在 Connecticut，超过自行车时，你必须留出至少 3 英尺的空间。","p":"对。超过自行车时，要留出至少 3 英尺。"},"vi":{"q":"Ở Connecticut, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài sang một bên.","h2":"Ở Connecticut, khi vượt xe đạp, bạn phải chừa khoảng cách ít nhất 3 feet.","p":"Đúng. Khi vượt xe đạp, hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Connecticut, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Isipin ang mga isang mahabang hakbang patagilid.","h2":"Sa Connecticut, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo kapag nilalampasan mo ang bisikleta.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet kapag nilalampasan mo ito."},"ar":{"q":"في Connecticut، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["1 قدم على الأقل","2 قدم على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"فكّر في خطوة طويلة واحدة تقريبًا إلى الجانب.","h2":"في Connecticut، يجب أن تترك مسافة 3 أقدام على الأقل عندما تتجاوز دراجة.","p":"صحيح. اترك للدراجة 3 أقدام على الأقل عندما تتجاوزها."},"ref":{"doc":"CT","page":22}},{"id":"ct-029","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, how close to a fire hydrant may you not park?","o":["Within 10 feet","Within 5 feet","Within 25 feet","Within 50 feet"],"h1":"Fire crews need room to reach the hydrant. The distance is short.","h2":"In Connecticut, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet away from a fire hydrant when you park."},"es":{"q":"En Connecticut, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 10 pies","A menos de 5 pies","A menos de 25 pies","A menos de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante. La distancia es corta.","h2":"En Connecticut, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese al menos a 10 pies de un hidrante al estacionarse."},"zh":{"q":"在 Connecticut，离消防栓多近的地方不可以停车？","o":["10 英尺以内","5 英尺以内","25 英尺以内","50 英尺以内"],"h1":"消防员需要空间接近消防栓。这个距离不长。","h2":"在 Connecticut，你不可以在离消防栓 10 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Connecticut, bạn không được đậu xe gần trụ nước cứu hỏa trong khoảng cách bao nhiêu?","o":["Trong vòng 10 feet","Trong vòng 5 feet","Trong vòng 25 feet","Trong vòng 50 feet"],"h1":"Lính cứu hỏa cần chỗ để đến được trụ nước. Khoảng cách này ngắn.","h2":"Ở Connecticut, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Connecticut, gaano kalapit sa fire hydrant ang bawal kang pumarada?","o":["Sa loob ng 10 feet","Sa loob ng 5 feet","Sa loob ng 25 feet","Sa loob ng 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant. Maikli ang layo.","h2":"Sa Connecticut, bawal kang pumarada sa loob ng 10 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 feet sa fire hydrant kapag pumaparada ka."},"ar":{"q":"في Connecticut، على أي مسافة من صنبور إطفاء الحريق يُمنع عليك الوقوف بسيارتك؟","o":["ضمن 10 أقدام","ضمن 5 أقدام","ضمن 25 قدمًا","ضمن 50 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور. المسافة قصيرة.","h2":"في Connecticut، لا يجوز لك أن توقف سيارتك ضمن 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 10 أقدام على الأقل عن صنبور إطفاء الحريق عندما توقف سيارتك."},"ref":{"doc":"CT","page":37}},{"id":"ct-030","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, what is the minimum vision needed for a driver's license, with or without glasses?","o":["20/20","20/40","20/70","20/100"],"h1":"It is the same for all license classes, and glasses or contacts may be used.","h2":"In Connecticut, you need at least 20/40 vision, with or without glasses or contact lenses.","p":"Right. The minimum is 20/40, and glasses or contacts are allowed."},"es":{"q":"En Connecticut, ¿cuál es la visión mínima para una licencia de conducir, con o sin lentes?","o":["20/20","20/40","20/70","20/100"],"h1":"Es igual para todas las clases de licencia, y se pueden usar lentes o lentes de contacto.","h2":"En Connecticut, necesita una visión de al menos 20/40, con o sin lentes o lentes de contacto.","p":"Correcto. El mínimo es 20/40, y se permiten lentes o lentes de contacto."},"zh":{"q":"在 Connecticut，戴或不戴眼镜，申请驾照所需的最低视力是多少？","o":["20/20","20/40","20/70","20/100"],"h1":"所有驾照类别的要求都一样，可以戴眼镜或隐形眼镜。","h2":"在 Connecticut，你的视力至少要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。最低视力是 20/40，可以戴眼镜或隐形眼镜。"},"vi":{"q":"Ở Connecticut, thị lực tối thiểu để có bằng lái là bao nhiêu, có hoặc không đeo kính?","o":["20/20","20/40","20/70","20/100"],"h1":"Yêu cầu giống nhau cho mọi hạng bằng lái, và được phép đeo kính hoặc kính áp tròng.","h2":"Ở Connecticut, bạn cần thị lực ít nhất 20/40, có hoặc không đeo kính hay kính áp tròng.","p":"Đúng. Mức tối thiểu là 20/40, và được phép đeo kính hoặc kính áp tròng."},"tl":{"q":"Sa Connecticut, ano ang pinakamababang paningin na kailangan para sa driver's license, may salamin man o wala?","o":["20/20","20/40","20/70","20/100"],"h1":"Pareho ito para sa lahat ng klase ng lisensya, at puwedeng gumamit ng salamin o contact lens.","h2":"Sa Connecticut, kailangan mo ng paningin na hindi bababa sa 20/40, may salamin o contact lens man o wala.","p":"Tama. Ang pinakamababa ay 20/40, at puwede ang salamin o contact lens."},"ar":{"q":"في Connecticut، ما الحد الأدنى للنظر المطلوب لرخصة القيادة، بالنظارة أو بدونها؟","o":["20/20","20/40","20/70","20/100"],"h1":"الشرط نفسه لكل فئات الرخص، ويُسمح باستخدام النظارة أو العدسات اللاصقة.","h2":"في Connecticut، تحتاج إلى نظر 20/40 على الأقل، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. الحد الأدنى هو 20/40، ويُسمح بالنظارة أو العدسات اللاصقة."},"ref":{"doc":"CT","page":5}},{"id":"ct-031","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, you turn on your windshield wipers because of rain. What does the law say you must also turn on?","o":["Your hazard lights","Your parking lights only","Your high beams","Your headlights"],"h1":"Other drivers need to see you better in the rain.","h2":"In Connecticut, the law says that when your wipers are on, your headlights must be on too.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Connecticut, usted enciende los limpiaparabrisas porque llueve. ¿Qué más debe encender según la ley?","o":["Las luces de emergencia","Solo las luces de estacionamiento","Las luces altas","Los faros delanteros"],"h1":"Los demás conductores necesitan verlo mejor bajo la lluvia.","h2":"En Connecticut, la ley dice que si los limpiaparabrisas están encendidos, los faros delanteros también deben estarlo.","p":"Correcto. Con limpiaparabrisas encendidos, faros encendidos."},"zh":{"q":"在 Connecticut，你因为下雨打开了雨刷。法律规定你还必须打开什么？","o":["危险警示灯","只开停车灯","远光灯","前大灯"],"h1":"下雨时，其他司机需要更清楚地看到你。","h2":"在 Connecticut，法律规定，当你打开雨刷时，也必须打开前大灯。","p":"对。开雨刷，就要开前大灯。"},"vi":{"q":"Ở Connecticut, bạn bật cần gạt nước vì trời mưa. Luật nói bạn cũng phải bật gì?","o":["Đèn cảnh báo nguy hiểm","Chỉ đèn đậu xe","Đèn pha chiếu xa","Đèn pha"],"h1":"Những tài xế khác cần nhìn thấy bạn rõ hơn khi trời mưa.","h2":"Ở Connecticut, luật nói rằng khi cần gạt nước đang bật, bạn cũng phải bật đèn pha.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Connecticut, binuksan mo ang windshield wipers mo dahil umuulan. Ano ang sinasabi ng batas na dapat mo ring buksan?","o":["Ang hazard lights mo","Ang parking lights mo lang","Ang high beams mo","Ang headlights mo"],"h1":"Kailangan kang makita nang mas mabuti ng ibang driver kapag umuulan.","h2":"Sa Connecticut, sinasabi ng batas na kapag nakabukas ang wipers mo, dapat nakabukas din ang headlights mo.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Connecticut، شغّلت مسّاحات الزجاج الأمامي بسبب المطر. ماذا يقول القانون إنه يجب عليك أن تشغّل أيضًا؟","o":["أضواء التحذير","أضواء الوقوف فقط","الأضواء العالية","المصابيح الأمامية"],"h1":"يحتاج السائقون الآخرون إلى رؤيتك بشكل أفضل في المطر.","h2":"في Connecticut، يقول القانون إنه عندما تكون المسّاحات مشغّلة، يجب أن تكون المصابيح الأمامية مشغّلة أيضًا.","p":"صحيح. المسّاحات تعمل يعني أن المصابيح الأمامية تعمل."},"ref":{"doc":"CT","page":38}},{"id":"ct-032","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, how long must a learner aged 18 or older hold a permit before taking the road test?","o":["30 days","60 days","90 days","180 days"],"h1":"Adults wait less time than teens who train at home.","h2":"In Connecticut, a learner aged 18 or older must hold the permit for at least 90 days before the road test.","p":"Right. Adults must hold the permit for at least 90 days."},"es":{"q":"En Connecticut, ¿cuánto tiempo debe tener el permiso un aprendiz de 18 años o más antes del examen de manejo?","o":["30 días","60 días","90 días","180 días"],"h1":"Los adultos esperan menos que los adolescentes que practican en casa.","h2":"En Connecticut, un aprendiz de 18 años o más debe tener el permiso al menos 90 días antes del examen de manejo.","p":"Correcto. Los adultos deben tener el permiso al menos 90 días."},"zh":{"q":"在 Connecticut，18 岁或以上的学员在参加路考前必须持有学习驾照多长时间？","o":["30 天","60 天","90 天","180 天"],"h1":"成年人等待的时间比在家训练的青少年短。","h2":"在 Connecticut，18 岁或以上的学员必须持有学习驾照至少 90 天，才能参加路考。","p":"对。成年人必须持有学习驾照至少 90 天。"},"vi":{"q":"Ở Connecticut, người tập lái từ 18 tuổi trở lên phải giữ giấy phép tập lái bao lâu trước khi thi lái xe trên đường?","o":["30 ngày","60 ngày","90 ngày","180 ngày"],"h1":"Người lớn chờ ít hơn so với thiếu niên tập lái ở nhà.","h2":"Ở Connecticut, người tập lái từ 18 tuổi trở lên phải giữ giấy phép tập lái ít nhất 90 ngày trước khi thi lái xe trên đường.","p":"Đúng. Người lớn phải giữ giấy phép tập lái ít nhất 90 ngày."},"tl":{"q":"Sa Connecticut, gaano katagal dapat hawak ng learner na 18 taong gulang pataas ang permit bago kumuha ng road test?","o":["30 araw","60 araw","90 araw","180 araw"],"h1":"Mas maikli ang hinihintay ng mga adult kaysa sa mga teenager na nagsasanay sa bahay.","h2":"Sa Connecticut, dapat hawak ng learner na 18 taong gulang pataas ang permit nang hindi bababa sa 90 araw bago ang road test.","p":"Tama. Dapat hawak ng mga adult ang permit nang hindi bababa sa 90 araw."},"ar":{"q":"في Connecticut، كم يجب أن يحمل المتعلّم الذي عمره 18 سنة أو أكثر تصريح التعلّم قبل اختبار القيادة على الطريق؟","o":["30 يومًا","60 يومًا","90 يومًا","180 يومًا"],"h1":"البالغون ينتظرون وقتًا أقل من المراهقين الذين يتدرّبون في البيت.","h2":"في Connecticut يجب أن يحمل المتعلّم الذي عمره 18 سنة أو أكثر تصريح التعلّم 90 يومًا على الأقل قبل اختبار القيادة على الطريق.","p":"صحيح. يجب أن يحمل البالغون التصريح 90 يومًا على الأقل."},"ref":{"doc":"CT","page":7}},{"id":"ct-033","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what is the regular (non-commercial) driver's license for passenger cars called?","o":["Class D","Class A","Class B","Class C"],"h1":"It is the class for everyday drivers, not trucks or buses.","h2":"In Connecticut, the regular non-commercial driver's license is called a Class D license.","p":"Right. The regular license is Class D."},"es":{"q":"En Connecticut, ¿cómo se llama la licencia de conducir común (no comercial) para autos de pasajeros?","o":["Clase D","Clase A","Clase B","Clase C"],"h1":"Es la clase para los conductores de todos los días, no para camiones ni autobuses.","h2":"En Connecticut, la licencia de conducir común no comercial se llama licencia Clase D.","p":"Correcto. La licencia común es Clase D."},"zh":{"q":"在 Connecticut，普通（非商业）小汽车驾照叫什么？","o":["Class D","Class A","Class B","Class C"],"h1":"这是给普通司机的驾照类别，不是卡车或巴士的。","h2":"在 Connecticut，普通的非商业驾照叫做 Class D 驾照。","p":"对。普通驾照是 Class D。"},"vi":{"q":"Ở Connecticut, bằng lái thông thường (không phải thương mại) cho xe hơi chở khách được gọi là gì?","o":["Class D","Class A","Class B","Class C"],"h1":"Đó là hạng bằng cho người lái xe hằng ngày, không phải xe tải hay xe buýt.","h2":"Ở Connecticut, bằng lái thông thường không phải thương mại được gọi là bằng Class D.","p":"Đúng. Bằng lái thông thường là Class D."},"tl":{"q":"Sa Connecticut, ano ang tawag sa regular (hindi commercial) na lisensya para sa mga pampasaherong kotse?","o":["Class D","Class A","Class B","Class C"],"h1":"Ito ang class para sa mga pang-araw-araw na driver, hindi para sa trak o bus.","h2":"Sa Connecticut, ang regular na hindi commercial na lisensya ay tinatawag na Class D na lisensya.","p":"Tama. Class D ang regular na lisensya."},"ar":{"q":"في Connecticut، ما اسم رخصة القيادة العادية (غير التجارية) لسيارات الركاب؟","o":["Class D","Class A","Class B","Class C"],"h1":"هي الفئة للسائقين العاديين، وليست للشاحنات أو الحافلات.","h2":"في Connecticut تُسمّى رخصة القيادة العادية غير التجارية رخصة Class D.","p":"صحيح. الرخصة العادية هي Class D."},"ref":{"doc":"CT","page":4}},{"id":"ct-034","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, what is the most passengers a permit holder or a 16- or 17-year-old driver may ever carry?","o":["Two people","The number of doors on the car","Four people","The number of seat belts in the car"],"h1":"Think about what every passenger needs in order to buckle up.","h2":"In Connecticut, permit holders and 16- and 17-year-old drivers may not carry more passengers than the car has seat belts.","p":"Right. Never more passengers than seat belts."},"es":{"q":"En Connecticut, ¿cuál es el número máximo de pasajeros que puede llevar un conductor con permiso o un conductor de 16 o 17 años?","o":["Dos personas","El número de puertas del auto","Cuatro personas","El número de cinturones de seguridad del auto"],"h1":"Piense en lo que necesita cada pasajero para abrocharse.","h2":"En Connecticut, los conductores con permiso y los de 16 y 17 años no pueden llevar más pasajeros que cinturones de seguridad tenga el auto.","p":"Correcto. Nunca más pasajeros que cinturones."},"zh":{"q":"在 Connecticut，持学习驾照的人或 16、17 岁的司机最多可以载多少名乘客？","o":["两个人","车门的数量","四个人","车里安全带的数量"],"h1":"想一想每位乘客需要什么才能系好安全带。","h2":"在 Connecticut，持学习驾照的人和 16、17 岁的司机载的乘客不能多于车里安全带的数量。","p":"对。乘客永远不能多于安全带。"},"vi":{"q":"Ở Connecticut, người có giấy phép tập lái hoặc tài xế 16 hay 17 tuổi được chở nhiều nhất bao nhiêu hành khách?","o":["Hai người","Bằng số cửa của xe","Bốn người","Bằng số dây an toàn trong xe"],"h1":"Hãy nghĩ xem mỗi hành khách cần gì để thắt dây an toàn.","h2":"Ở Connecticut, người có giấy phép tập lái và tài xế 16, 17 tuổi không được chở nhiều hành khách hơn số dây an toàn trong xe.","p":"Đúng. Không bao giờ chở nhiều hành khách hơn số dây an toàn."},"tl":{"q":"Sa Connecticut, ano ang pinakamaraming pasahero na puwedeng isakay ng may permit o ng driver na 16 o 17 taong gulang?","o":["Dalawang tao","Kasindami ng pinto ng kotse","Apat na tao","Kasindami ng seat belt sa kotse"],"h1":"Isipin kung ano ang kailangan ng bawat pasahero para makapag-seat belt.","h2":"Sa Connecticut, hindi puwedeng magsakay ang may permit at ang mga driver na 16 at 17 taong gulang ng mas maraming pasahero kaysa sa mga seat belt sa kotse.","p":"Tama. Hindi kailanman mas maraming pasahero kaysa sa seat belt."},"ar":{"q":"في Connecticut، ما أكبر عدد من الركاب يجوز أن يحمله صاحب تصريح التعلّم أو السائق الذي عمره 16 أو 17 سنة؟","o":["شخصان","عدد أبواب السيارة","أربعة أشخاص","عدد أحزمة الأمان في السيارة"],"h1":"فكّر فيما يحتاجه كل راكب ليربط حزام الأمان.","h2":"في Connecticut لا يجوز لصاحب تصريح التعلّم ولا للسائق الذي عمره 16 أو 17 سنة أن يحمل ركابًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. لا يزيد عدد الركاب أبدًا على عدد أحزمة الأمان."},"ref":{"doc":"CT","page":8}},{"id":"ct-035","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 17-year-old just got a motorcycle endorsement. How long must they wait before carrying a passenger on the motorcycle?","o":["30 days","Six months","One year","Until age 21"],"h1":"It is the same length as the first stage of the teen passenger limits for cars.","h2":"In Connecticut, a 16- or 17-year-old may not carry a passenger on a motorcycle for six months after getting a motorcycle endorsement.","p":"Right. No motorcycle passengers for the first six months."},"es":{"q":"En Connecticut, un joven de 17 años acaba de obtener el endoso de motocicleta. ¿Cuánto tiempo debe esperar antes de llevar a un pasajero en la motocicleta?","o":["30 días","Seis meses","Un año","Hasta los 21 años"],"h1":"Es el mismo tiempo que la primera etapa de los límites de pasajeros para adolescentes en auto.","h2":"En Connecticut, un joven de 16 o 17 años no puede llevar pasajeros en motocicleta durante seis meses después de obtener el endoso de motocicleta.","p":"Correcto. Nada de pasajeros en motocicleta los primeros seis meses."},"zh":{"q":"在 Connecticut，一名 17 岁的人刚拿到摩托车签注。他要等多久才能在摩托车上载乘客？","o":["30 天","六个月","一年","到 21 岁"],"h1":"这和青少年开汽车时载客限制的第一阶段一样长。","h2":"在 Connecticut，16 或 17 岁的人拿到摩托车签注后六个月内，不能在摩托车上载乘客。","p":"对。前六个月不能在摩托车上载乘客。"},"vi":{"q":"Ở Connecticut, một người 17 tuổi vừa có chứng nhận lái xe máy (motorcycle endorsement). Người đó phải chờ bao lâu mới được chở người khác trên xe máy?","o":["30 ngày","Sáu tháng","Một năm","Đến 21 tuổi"],"h1":"Thời gian này bằng với giai đoạn đầu của giới hạn chở khách đối với thiếu niên lái xe hơi.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi không được chở người khác trên xe máy trong sáu tháng sau khi có chứng nhận lái xe máy.","p":"Đúng. Không chở người trên xe máy trong sáu tháng đầu."},"tl":{"q":"Sa Connecticut, kakakuha lang ng isang 17 taong gulang ng motorcycle endorsement. Gaano katagal siya dapat maghintay bago magsakay ng pasahero sa motorsiklo?","o":["30 araw","Anim na buwan","Isang taon","Hanggang edad 21"],"h1":"Kasinghaba ito ng unang yugto ng limit sa pasahero ng mga teenager sa kotse.","h2":"Sa Connecticut, hindi puwedeng magsakay ng pasahero sa motorsiklo ang 16 o 17 taong gulang sa loob ng anim na buwan pagkatapos makakuha ng motorcycle endorsement.","p":"Tama. Walang pasahero sa motorsiklo sa unang anim na buwan."},"ar":{"q":"في Connecticut، حصل شخص عمره 17 سنة للتو على إذن قيادة الدراجة النارية (motorcycle endorsement). كم يجب أن ينتظر قبل أن يحمل راكبًا على الدراجة النارية؟","o":["30 يومًا","ستة أشهر","سنة واحدة","حتى عمر 21 سنة"],"h1":"هي المدة نفسها للمرحلة الأولى من حدود الركاب للمراهقين في السيارات.","h2":"في Connecticut لا يجوز لمن عمره 16 أو 17 سنة أن يحمل راكبًا على الدراجة النارية لمدة ستة أشهر بعد حصوله على إذن قيادة الدراجة النارية.","p":"صحيح. لا ركاب على الدراجة النارية في الأشهر الستة الأولى."},"ref":{"doc":"CT","page":8}},{"id":"ct-036","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 17-year-old driver is convicted for the first time of breaking the curfew or passenger rules. What happens to the license?","o":["It is suspended for 30 days","Only a written warning is given","It is suspended for one year","It is taken away until age 21"],"h1":"The first time, the suspension is counted in days.","h2":"In Connecticut, a first conviction for breaking a teen driving rule, such as the curfew or passenger limits, brings a 30-day license suspension.","p":"Right. A first teen-rule violation means a 30-day suspension."},"es":{"q":"En Connecticut, un conductor de 17 años es declarado culpable por primera vez de no respetar el horario nocturno o las reglas de pasajeros. ¿Qué pasa con su licencia?","o":["Se suspende por 30 días","Solo recibe una advertencia por escrito","Se suspende por un año","Se le quita hasta los 21 años"],"h1":"La primera vez, la suspensión se cuenta en días.","h2":"En Connecticut, la primera condena por no cumplir una regla para conductores adolescentes, como el horario nocturno o los límites de pasajeros, trae una suspensión de licencia de 30 días.","p":"Correcto. La primera falta a las reglas para adolescentes significa 30 días de suspensión."},"zh":{"q":"在 Connecticut，一名 17 岁的司机第一次因违反宵禁或载客规定被定罪。驾照会怎样？","o":["被吊销 30 天","只会收到书面警告","被吊销一年","被收走直到 21 岁"],"h1":"第一次的吊销时间是按天计算的。","h2":"在 Connecticut，第一次因违反青少年驾驶规定（例如宵禁或载客限制）被定罪，驾照会被吊销 30 天。","p":"对。第一次违反青少年规定，驾照被吊销 30 天。"},"vi":{"q":"Ở Connecticut, một tài xế 17 tuổi bị kết tội lần đầu vì vi phạm giờ giới nghiêm hoặc quy định chở khách. Bằng lái sẽ ra sao?","o":["Bị treo 30 ngày","Chỉ bị cảnh cáo bằng văn bản","Bị treo một năm","Bị thu hồi đến 21 tuổi"],"h1":"Lần đầu, thời gian treo bằng được tính bằng ngày.","h2":"Ở Connecticut, lần đầu bị kết tội vi phạm quy định lái xe dành cho thiếu niên, như giờ giới nghiêm hoặc giới hạn chở khách, thì bằng lái bị treo 30 ngày.","p":"Đúng. Vi phạm quy định thiếu niên lần đầu nghĩa là bị treo bằng 30 ngày."},"tl":{"q":"Sa Connecticut, nahatulan sa unang pagkakataon ang isang 17 taong gulang na driver dahil lumabag sa curfew o sa patakaran sa pasahero. Ano ang mangyayari sa lisensya?","o":["Masususpinde ito nang 30 araw","Nakasulat na babala lang ang ibibigay","Masususpinde ito nang isang taon","Kukunin ito hanggang edad 21"],"h1":"Sa unang pagkakataon, ang suspensyon ay binibilang sa araw.","h2":"Sa Connecticut, ang unang hatol dahil sa paglabag sa patakaran para sa teen driver, gaya ng curfew o limit sa pasahero, ay may kasamang 30 araw na suspensyon ng lisensya.","p":"Tama. Ang unang paglabag sa teen rule ay 30 araw na suspensyon."},"ar":{"q":"في Connecticut، أُدين سائق عمره 17 سنة لأول مرة بمخالفة حظر التجول أو قواعد الركاب. ماذا يحدث لرخصته؟","o":["تُوقَف لمدة 30 يومًا","يحصل على إنذار مكتوب فقط","تُوقَف لمدة سنة","تُسحب منه حتى عمر 21 سنة"],"h1":"في المرة الأولى تُحسب مدة الإيقاف بالأيام.","h2":"في Connecticut الإدانة الأولى بمخالفة قاعدة من قواعد قيادة المراهقين، مثل حظر التجول أو حدود الركاب، تؤدي إلى إيقاف الرخصة لمدة 30 يومًا.","p":"صحيح. المخالفة الأولى لقواعد المراهقين تعني إيقاف الرخصة 30 يومًا."},"ref":{"doc":"CT","page":34}},{"id":"ct-037","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, a 16-year-old is convicted for the first time of driving 20 mph or more over the speed limit. How long is the license suspended?","o":["7 days","30 days","60 days","Two years"],"h1":"It is longer than the suspension for a first curfew violation.","h2":"In Connecticut, a 16- or 17-year-old convicted for the first time of speeding 20 mph or more over the limit loses the license for 60 days.","p":"Right. A first offense means a 60-day suspension."},"es":{"q":"En Connecticut, un joven de 16 años es declarado culpable por primera vez de manejar 20 mph o más por encima del límite de velocidad. ¿Por cuánto tiempo se suspende su licencia?","o":["7 días","30 días","60 días","Dos años"],"h1":"Es más tiempo que la suspensión por una primera falta al horario nocturno.","h2":"En Connecticut, un joven de 16 o 17 años declarado culpable por primera vez de exceder el límite por 20 mph o más pierde la licencia por 60 días.","p":"Correcto. Una primera falta significa 60 días de suspensión."},"zh":{"q":"在 Connecticut，一名 16 岁的人第一次因超速 20 mph 或以上被定罪。驾照会被吊销多久？","o":["7 天","30 天","60 天","两年"],"h1":"这比第一次违反宵禁的吊销时间更长。","h2":"在 Connecticut，16 或 17 岁的人第一次因超速 20 mph 或以上被定罪，驾照会被吊销 60 天。","p":"对。第一次违规，驾照被吊销 60 天。"},"vi":{"q":"Ở Connecticut, một người 16 tuổi bị kết tội lần đầu vì chạy quá tốc độ giới hạn từ 20 mph trở lên. Bằng lái bị treo bao lâu?","o":["7 ngày","30 ngày","60 ngày","Hai năm"],"h1":"Thời gian này dài hơn mức treo bằng khi vi phạm giờ giới nghiêm lần đầu.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi bị kết tội lần đầu vì chạy quá tốc độ giới hạn từ 20 mph trở lên sẽ bị treo bằng lái 60 ngày.","p":"Đúng. Vi phạm lần đầu nghĩa là bị treo bằng 60 ngày."},"tl":{"q":"Sa Connecticut, nahatulan sa unang pagkakataon ang isang 16 taong gulang dahil nagmaneho nang 20 mph o higit pa lampas sa speed limit. Gaano katagal masususpinde ang lisensya?","o":["7 araw","30 araw","60 araw","Dalawang taon"],"h1":"Mas mahaba ito kaysa sa suspensyon para sa unang paglabag sa curfew.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na nahatulan sa unang pagkakataon dahil lumampas nang 20 mph o higit pa sa limit ay mawawalan ng lisensya nang 60 araw.","p":"Tama. Ang unang paglabag ay 60 araw na suspensyon."},"ar":{"q":"في Connecticut، أُدين شخص عمره 16 سنة لأول مرة بالقيادة بسرعة تزيد على الحد المسموح بمقدار 20 mph أو أكثر. كم تُوقَف رخصته؟","o":["7 أيام","30 يومًا","60 يومًا","سنتان"],"h1":"المدة أطول من الإيقاف بسبب أول مخالفة لحظر التجول.","h2":"في Connecticut من عمره 16 أو 17 سنة ويُدان لأول مرة بتجاوز الحد المسموح بمقدار 20 mph أو أكثر تُوقَف رخصته لمدة 60 يومًا.","p":"صحيح. المخالفة الأولى تعني إيقاف الرخصة 60 يومًا."},"ref":{"doc":"CT","page":34}},{"id":"ct-038","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how long is the license of a 16- or 17-year-old suspended after a first conviction for reckless driving?","o":["10 days","30 days","60 days","Six months"],"h1":"Reckless driving is punished much more harshly than a curfew violation.","h2":"In Connecticut, a 16- or 17-year-old convicted of reckless driving for the first time has the license suspended for six months.","p":"Right. A first reckless driving conviction means a six-month suspension."},"es":{"q":"En Connecticut, ¿por cuánto tiempo se suspende la licencia de un joven de 16 o 17 años después de una primera condena por manejo imprudente?","o":["10 días","30 días","60 días","Seis meses"],"h1":"El manejo imprudente se castiga mucho más que una falta al horario nocturno.","h2":"En Connecticut, a un joven de 16 o 17 años declarado culpable de manejo imprudente por primera vez se le suspende la licencia por seis meses.","p":"Correcto. Una primera condena por manejo imprudente significa seis meses de suspensión."},"zh":{"q":"在 Connecticut，16 或 17 岁的人第一次因鲁莽驾驶被定罪后，驾照会被吊销多久？","o":["10 天","30 天","60 天","六个月"],"h1":"鲁莽驾驶的处罚比违反宵禁重得多。","h2":"在 Connecticut，16 或 17 岁的人第一次因鲁莽驾驶被定罪，驾照会被吊销六个月。","p":"对。第一次鲁莽驾驶被定罪，驾照被吊销六个月。"},"vi":{"q":"Ở Connecticut, bằng lái của người 16 hoặc 17 tuổi bị treo bao lâu sau lần đầu bị kết tội lái xe liều lĩnh?","o":["10 ngày","30 ngày","60 ngày","Sáu tháng"],"h1":"Lái xe liều lĩnh bị phạt nặng hơn nhiều so với vi phạm giờ giới nghiêm.","h2":"Ở Connecticut, người 16 hoặc 17 tuổi bị kết tội lái xe liều lĩnh lần đầu sẽ bị treo bằng lái sáu tháng.","p":"Đúng. Lần đầu bị kết tội lái xe liều lĩnh nghĩa là bị treo bằng sáu tháng."},"tl":{"q":"Sa Connecticut, gaano katagal masususpinde ang lisensya ng 16 o 17 taong gulang pagkatapos ng unang hatol sa reckless driving?","o":["10 araw","30 araw","60 araw","Anim na buwan"],"h1":"Mas mabigat ang parusa sa reckless driving kaysa sa paglabag sa curfew.","h2":"Sa Connecticut, ang 16 o 17 taong gulang na nahatulan sa reckless driving sa unang pagkakataon ay masususpinde ang lisensya nang anim na buwan.","p":"Tama. Ang unang hatol sa reckless driving ay anim na buwang suspensyon."},"ar":{"q":"في Connecticut، كم تُوقَف رخصة من عمره 16 أو 17 سنة بعد أول إدانة بالقيادة المتهوّرة؟","o":["10 أيام","30 يومًا","60 يومًا","ستة أشهر"],"h1":"عقوبة القيادة المتهوّرة أشد بكثير من عقوبة مخالفة حظر التجول.","h2":"في Connecticut من عمره 16 أو 17 سنة ويُدان بالقيادة المتهوّرة لأول مرة تُوقَف رخصته لمدة ستة أشهر.","p":"صحيح. أول إدانة بالقيادة المتهوّرة تعني إيقاف الرخصة ستة أشهر."},"ref":{"doc":"CT","page":34}},{"id":"ct-039","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, the DMV warns you that the insurance on your registered car has lapsed. What happens if you do not respond?","o":["Nothing, as long as you do not drive the car","The car's registration is suspended","You get one extra point on your license","Your insurance company pays a fine for you"],"h1":"Think about what makes it legal to drive the car on a public road.","h2":"In Connecticut, if you do not respond to the DMV's warning about lapsed insurance, the car's registration is suspended.","p":"Right. Ignoring the warning leads to a suspended registration."},"es":{"q":"En Connecticut, el DMV le avisa que el seguro de su auto registrado se canceló. ¿Qué pasa si usted no responde?","o":["Nada, si no maneja el auto","Se suspende el registro del auto","Recibe un punto más en su licencia","Su compañía de seguros paga una multa por usted"],"h1":"Piense en lo que permite manejar el auto legalmente en una vía pública.","h2":"En Connecticut, si usted no responde al aviso del DMV sobre el seguro cancelado, se suspende el registro del auto.","p":"Correcto. Si ignora el aviso, se suspende el registro."},"zh":{"q":"在 Connecticut，DMV 警告你，你已登记的车的保险已经失效。如果你不回应，会怎样？","o":["没事，只要你不开这辆车","这辆车的登记会被暂停","你的驾照会多扣一分","你的保险公司会替你交罚款"],"h1":"想一想，是什么让这辆车可以合法地在公共道路上行驶。","h2":"在 Connecticut，如果你不回应 DMV 关于保险失效的警告，这辆车的登记会被暂停。","p":"对。不理会警告，车辆登记就会被暂停。"},"vi":{"q":"Ở Connecticut, DMV cảnh báo rằng bảo hiểm của chiếc xe bạn đã đăng ký đã hết hiệu lực. Nếu bạn không trả lời thì sao?","o":["Không sao, miễn là bạn không lái chiếc xe đó","Giấy đăng ký của xe bị treo","Bạn bị thêm một điểm vào bằng lái","Công ty bảo hiểm trả tiền phạt thay bạn"],"h1":"Hãy nghĩ xem điều gì làm cho việc lái chiếc xe trên đường công cộng là hợp pháp.","h2":"Ở Connecticut, nếu bạn không trả lời cảnh báo của DMV về việc bảo hiểm hết hiệu lực, giấy đăng ký của xe sẽ bị treo.","p":"Đúng. Bỏ qua cảnh báo sẽ khiến giấy đăng ký xe bị treo."},"tl":{"q":"Sa Connecticut, binalaan ka ng DMV na nag-lapse na ang insurance ng rehistradong kotse mo. Ano ang mangyayari kung hindi ka sasagot?","o":["Wala, basta hindi mo minamaneho ang kotse","Masususpinde ang rehistro ng kotse","Madadagdagan ng isang point ang lisensya mo","Ang insurance company mo ang magbabayad ng multa para sa iyo"],"h1":"Isipin kung ano ang nagpapalegal sa pagmamaneho ng kotse sa pampublikong kalsada.","h2":"Sa Connecticut, kapag hindi ka sumagot sa babala ng DMV tungkol sa nag-lapse na insurance, masususpinde ang rehistro ng kotse.","p":"Tama. Kapag binalewala ang babala, masususpinde ang rehistro."},"ar":{"q":"في Connecticut، يحذّرك الـ DMV من أن تأمين سيارتك المسجّلة قد انتهى. ماذا يحدث إذا لم تردّ؟","o":["لا شيء، ما دمت لا تقود السيارة","يُوقَف تسجيل السيارة","تُضاف نقطة واحدة إلى رخصتك","تدفع شركة التأمين الغرامة عنك"],"h1":"فكّر فيما يجعل قيادة السيارة على الطريق العام قانونية.","h2":"في Connecticut إذا لم تردّ على تحذير الـ DMV بشأن انتهاء التأمين، يُوقَف تسجيل السيارة.","p":"صحيح. تجاهل التحذير يؤدي إلى إيقاف تسجيل السيارة."},"ref":{"doc":"CT","page":13}},{"id":"ct-040","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 22-year-old driver is convicted of two moving violations. What must the driver do?","o":["Complete the DMV operator retraining program","Take the knowledge test again","Get a new learner's permit","Nothing until a third violation"],"h1":"Drivers 24 and younger get fewer chances than older drivers.","h2":"In Connecticut, a driver aged 24 or younger with two or more moving violations must complete the DMV operator retraining program.","p":"Right. Two violations at 24 or younger means operator retraining."},"es":{"q":"En Connecticut, un conductor de 22 años es declarado culpable de dos infracciones de tránsito en movimiento. ¿Qué debe hacer?","o":["Completar el programa de reentrenamiento de conductores del DMV","Tomar el examen escrito otra vez","Sacar un nuevo permiso de aprendizaje","Nada hasta una tercera infracción"],"h1":"Los conductores de 24 años o menos tienen menos oportunidades que los mayores.","h2":"En Connecticut, un conductor de 24 años o menos con dos o más infracciones en movimiento debe completar el programa de reentrenamiento de conductores del DMV.","p":"Correcto. Dos infracciones a los 24 años o menos significan reentrenamiento."},"zh":{"q":"在 Connecticut，一名 22 岁的司机被判两次行车违规。这名司机必须做什么？","o":["完成 DMV 的驾驶员再培训课程","重新参加笔试","重新申请学习驾照","在第三次违规前什么都不用做"],"h1":"24 岁及以下的司机，机会比年长的司机少。","h2":"在 Connecticut，24 岁或以下、有两次或更多行车违规的司机，必须完成 DMV 的驾驶员再培训课程。","p":"对。24 岁或以下有两次违规，就要参加驾驶员再培训。"},"vi":{"q":"Ở Connecticut, một tài xế 22 tuổi bị kết tội hai lần vi phạm khi lái xe. Tài xế này phải làm gì?","o":["Hoàn thành chương trình đào tạo lại người lái của DMV","Thi lại bài thi kiến thức","Lấy giấy phép tập lái mới","Không phải làm gì cho đến lần vi phạm thứ ba"],"h1":"Tài xế từ 24 tuổi trở xuống có ít cơ hội hơn tài xế lớn tuổi.","h2":"Ở Connecticut, tài xế từ 24 tuổi trở xuống có hai lần vi phạm khi lái xe trở lên phải hoàn thành chương trình đào tạo lại người lái của DMV.","p":"Đúng. Hai lần vi phạm khi từ 24 tuổi trở xuống nghĩa là phải học lại."},"tl":{"q":"Sa Connecticut, nahatulan ang isang 22 taong gulang na driver ng dalawang moving violation. Ano ang dapat gawin ng driver?","o":["Tapusin ang operator retraining program ng DMV","Kumuha ulit ng knowledge test","Kumuha ng bagong learner's permit","Wala hanggang sa ikatlong paglabag"],"h1":"Mas kaunti ang pagkakataon ng mga driver na 24 pababa kaysa sa mas matatandang driver.","h2":"Sa Connecticut, ang driver na 24 taong gulang pababa na may dalawa o higit pang moving violation ay dapat tapusin ang operator retraining program ng DMV.","p":"Tama. Dalawang paglabag sa edad 24 pababa ay nangangahulugan ng operator retraining."},"ar":{"q":"في Connecticut، أُدين سائق عمره 22 سنة بمخالفتين مروريتين أثناء القيادة. ماذا يجب على السائق أن يفعل؟","o":["أن يُكمل برنامج إعادة تدريب السائقين في الـ DMV","أن يعيد الاختبار النظري","أن يحصل على تصريح تعلّم جديد","لا شيء حتى المخالفة الثالثة"],"h1":"السائقون الذين عمرهم 24 سنة أو أقل يحصلون على فرص أقل من السائقين الأكبر سنًا.","h2":"في Connecticut يجب على السائق الذي عمره 24 سنة أو أقل وعليه مخالفتان مروريتان أو أكثر أن يُكمل برنامج إعادة تدريب السائقين في الـ DMV.","p":"صحيح. مخالفتان في عمر 24 سنة أو أقل تعنيان إعادة تدريب السائق."},"ref":{"doc":"CT","page":35}},{"id":"ct-041","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, an adult driver fails a blood alcohol test after a DUI arrest. To get the license back, for at least how long must an ignition interlock device be used?","o":["One week","One month","Six months","Ten years"],"h1":"The device stays in the car for months, not days.","h2":"In Connecticut, a driver who fails the alcohol test must use an ignition interlock device for at least six months to get the license back.","p":"Right. At least six months with an ignition interlock device."},"es":{"q":"En Connecticut, un conductor adulto no pasa una prueba de alcohol en la sangre después de un arresto por manejar ebrio. Para recuperar la licencia, ¿por cuánto tiempo como mínimo debe usar un dispositivo de bloqueo de encendido?","o":["Una semana","Un mes","Seis meses","Diez años"],"h1":"El dispositivo se queda en el auto por meses, no por días.","h2":"En Connecticut, un conductor que no pasa la prueba de alcohol debe usar un dispositivo de bloqueo de encendido por al menos seis meses para recuperar la licencia.","p":"Correcto. Al menos seis meses con el dispositivo de bloqueo de encendido."},"zh":{"q":"在 Connecticut，一名成年司机因酒驾被捕后，血液酒精检测不合格。为了拿回驾照，至少要使用点火联锁装置多长时间？","o":["一周","一个月","六个月","十年"],"h1":"这个装置要在车里装几个月，而不是几天。","h2":"在 Connecticut，酒精检测不合格的司机必须使用点火联锁装置至少六个月，才能拿回驾照。","p":"对。至少使用点火联锁装置六个月。"},"vi":{"q":"Ở Connecticut, một tài xế người lớn không đạt bài xét nghiệm nồng độ cồn trong máu sau khi bị bắt vì lái xe khi say (DUI). Để lấy lại bằng lái, phải dùng thiết bị khóa khởi động xe ít nhất bao lâu?","o":["Một tuần","Một tháng","Sáu tháng","Mười năm"],"h1":"Thiết bị ở trong xe hàng tháng, không phải vài ngày.","h2":"Ở Connecticut, tài xế không đạt bài xét nghiệm nồng độ cồn phải dùng thiết bị khóa khởi động xe ít nhất sáu tháng để lấy lại bằng lái.","p":"Đúng. Ít nhất sáu tháng với thiết bị khóa khởi động xe."},"tl":{"q":"Sa Connecticut, bumagsak ang isang adult na driver sa blood alcohol test matapos maaresto dahil sa DUI. Para maibalik ang lisensya, gaano katagal man lang dapat gumamit ng ignition interlock device?","o":["Isang linggo","Isang buwan","Anim na buwan","Sampung taon"],"h1":"Nananatili ang device sa kotse nang ilang buwan, hindi ilang araw.","h2":"Sa Connecticut, ang driver na bumagsak sa alcohol test ay dapat gumamit ng ignition interlock device nang hindi bababa sa anim na buwan para maibalik ang lisensya.","p":"Tama. Hindi bababa sa anim na buwan na may ignition interlock device."},"ar":{"q":"في Connecticut، رسب سائق بالغ في فحص نسبة الكحول في الدم بعد اعتقاله بتهمة القيادة تحت تأثير الكحول (DUI). لكي يستعيد رخصته، كم يجب أن يستخدم جهاز قفل التشغيل على الأقل؟","o":["أسبوعًا واحدًا","شهرًا واحدًا","ستة أشهر","عشر سنوات"],"h1":"يبقى الجهاز في السيارة أشهرًا، لا أيامًا.","h2":"في Connecticut يجب على السائق الذي يرسب في فحص الكحول أن يستخدم جهاز قفل التشغيل ستة أشهر على الأقل لكي يستعيد رخصته.","p":"صحيح. ستة أشهر على الأقل مع جهاز قفل التشغيل."},"ref":{"doc":"CT","page":33}},{"id":"ct-042","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, where does the 0.02 percent alcohol limit for drivers under 21 apply?","o":["Only on highways","On public roads and on private property","Only on public roads at night","Only in school zones"],"h1":"The rule follows the young driver wherever they drive.","h2":"In Connecticut, the 0.02 percent limit for drivers under 21 applies on public roads and on private property.","p":"Right. It applies on public roads and private property alike."},"es":{"q":"En Connecticut, ¿dónde se aplica el límite de alcohol de 0.02 por ciento para conductores menores de 21 años?","o":["Solo en las autopistas","En las vías públicas y en propiedad privada","Solo en las vías públicas de noche","Solo en zonas escolares"],"h1":"La regla acompaña al conductor joven dondequiera que maneje.","h2":"En Connecticut, el límite de 0.02 por ciento para menores de 21 años se aplica en las vías públicas y en propiedad privada.","p":"Correcto. Se aplica igual en vías públicas y en propiedad privada."},"zh":{"q":"在 Connecticut，21 岁以下司机的 0.02% 酒精限制适用于哪里？","o":["只在高速公路上","在公共道路上和私人场所","只在夜间的公共道路上","只在学校区域"],"h1":"无论年轻司机在哪里开车，这条规定都适用。","h2":"在 Connecticut，21 岁以下司机的 0.02% 限制适用于公共道路，也适用于私人场所。","p":"对。在公共道路和私人场所都适用。"},"vi":{"q":"Ở Connecticut, giới hạn nồng độ cồn 0.02 phần trăm cho tài xế dưới 21 tuổi áp dụng ở đâu?","o":["Chỉ trên xa lộ","Trên đường công cộng và trên đất tư nhân","Chỉ trên đường công cộng vào ban đêm","Chỉ trong khu vực trường học"],"h1":"Quy định này theo tài xế trẻ đến bất cứ nơi nào họ lái xe.","h2":"Ở Connecticut, giới hạn 0.02 phần trăm cho tài xế dưới 21 tuổi áp dụng trên đường công cộng và trên đất tư nhân.","p":"Đúng. Giới hạn áp dụng cả trên đường công cộng lẫn đất tư nhân."},"tl":{"q":"Sa Connecticut, saan umiiral ang 0.02 porsiyentong limit sa alcohol para sa mga driver na wala pang 21?","o":["Sa highway lang","Sa pampublikong kalsada at sa pribadong lugar","Sa pampublikong kalsada lang sa gabi","Sa school zone lang"],"h1":"Sumusunod ang patakaran sa batang driver saanman siya magmaneho.","h2":"Sa Connecticut, umiiral ang 0.02 porsiyentong limit para sa mga driver na wala pang 21 sa pampublikong kalsada at sa pribadong lugar.","p":"Tama. Umiiral ito sa pampublikong kalsada at sa pribadong lugar."},"ar":{"q":"في Connecticut، أين ينطبق حدّ الكحول 0.02 بالمئة على السائقين تحت 21 سنة؟","o":["على الطرق السريعة فقط","على الطرق العامة وفي الأملاك الخاصة","على الطرق العامة ليلًا فقط","في مناطق المدارس فقط"],"h1":"القاعدة تتبع السائق الشاب أينما قاد.","h2":"في Connecticut ينطبق حدّ 0.02 بالمئة على السائقين تحت 21 سنة على الطرق العامة وفي الأملاك الخاصة.","p":"صحيح. ينطبق على الطرق العامة والأملاك الخاصة على حدّ سواء."},"ref":{"doc":"CT","page":33}},{"id":"ct-043","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, what happens to the fine for using a hand-held phone while driving through a work zone?","o":["It is cut in half","It stays the same","It is replaced by a warning","It is doubled"],"h1":"Work zones bring tougher penalties, not lighter ones.","h2":"In Connecticut, the fine for illegally using a hand-held phone or device is doubled in a work zone.","p":"Right. Hand-held phone fines are doubled in work zones."},"es":{"q":"En Connecticut, ¿qué pasa con la multa por usar un teléfono en la mano mientras maneja por una zona de construcción?","o":["Se reduce a la mitad","Sigue igual","Se cambia por una advertencia","Se duplica"],"h1":"Las zonas de construcción traen castigos más fuertes, no más leves.","h2":"En Connecticut, la multa por usar ilegalmente un teléfono o aparato en la mano se duplica en una zona de construcción.","p":"Correcto. Las multas por usar el teléfono en la mano se duplican en zonas de construcción."},"zh":{"q":"在 Connecticut，开车经过施工区时使用手持电话，罚款会怎样？","o":["减半","保持不变","改为警告","加倍"],"h1":"施工区的处罚更重，而不是更轻。","h2":"在 Connecticut，在施工区违法使用手持电话或设备，罚款会加倍。","p":"对。在施工区使用手持电话的罚款加倍。"},"vi":{"q":"Ở Connecticut, tiền phạt khi dùng điện thoại cầm tay lúc lái xe qua khu vực công trường thay đổi thế nào?","o":["Giảm một nửa","Giữ nguyên","Được thay bằng cảnh cáo","Tăng gấp đôi"],"h1":"Khu vực công trường có hình phạt nặng hơn, không nhẹ hơn.","h2":"Ở Connecticut, tiền phạt khi dùng điện thoại hoặc thiết bị cầm tay trái phép được tăng gấp đôi trong khu vực công trường.","p":"Đúng. Tiền phạt dùng điện thoại cầm tay tăng gấp đôi trong khu vực công trường."},"tl":{"q":"Sa Connecticut, ano ang nangyayari sa multa sa paggamit ng hand-held na phone habang nagmamaneho sa work zone?","o":["Nababawasan ito ng kalahati","Nananatili itong pareho","Napapalitan ito ng babala","Dinodoble ito"],"h1":"Mas mabigat ang parusa sa work zone, hindi mas magaan.","h2":"Sa Connecticut, dinodoble ang multa sa ilegal na paggamit ng hand-held na phone o device sa work zone.","p":"Tama. Doble ang multa sa hand-held na phone sa work zone."},"ar":{"q":"في Connecticut، ماذا يحدث لغرامة استخدام الهاتف المحمول باليد أثناء القيادة في منطقة أعمال الطرق؟","o":["تُخفَّض إلى النصف","تبقى كما هي","يُستبدل بها إنذار","تُضاعَف"],"h1":"مناطق أعمال الطرق فيها عقوبات أشد، لا أخف.","h2":"في Connecticut تُضاعَف غرامة استخدام الهاتف أو الجهاز المحمول باليد بشكل غير قانوني في منطقة أعمال الطرق.","p":"صحيح. غرامات الهاتف المحمول باليد تُضاعَف في مناطق أعمال الطرق."},"ref":{"doc":"CT","page":15}},{"id":"ct-044","scope":"CT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Connecticut, what is special about the fine for failing to yield the right-of-way to a bicyclist?","o":["It is doubled","It applies only at night","It is paid by the bicyclist","It is lower than for a car"],"h1":"The law gives bicyclists extra protection.","h2":"In Connecticut, fines are doubled for drivers who fail to yield the right-of-way to a bicyclist.","p":"Right. Failing to yield to a bicyclist means a doubled fine."},"es":{"q":"En Connecticut, ¿qué tiene de especial la multa por no ceder el paso a un ciclista?","o":["Se duplica","Solo se aplica de noche","La paga el ciclista","Es más baja que la de un auto"],"h1":"La ley da protección adicional a los ciclistas.","h2":"En Connecticut, las multas se duplican para los conductores que no ceden el paso a un ciclista.","p":"Correcto. No ceder el paso a un ciclista significa una multa doble."},"zh":{"q":"在 Connecticut，不给骑自行车的人让路，罚款有什么特别之处？","o":["罚款加倍","只在夜间适用","由骑自行车的人支付","比对汽车不让路的罚款低"],"h1":"法律给骑自行车的人额外的保护。","h2":"在 Connecticut，不给骑自行车的人让路的司机，罚款会加倍。","p":"对。不给骑自行车的人让路，罚款加倍。"},"vi":{"q":"Ở Connecticut, tiền phạt khi không nhường đường cho người đi xe đạp có gì đặc biệt?","o":["Bị tăng gấp đôi","Chỉ áp dụng vào ban đêm","Do người đi xe đạp trả","Thấp hơn so với xe hơi"],"h1":"Luật bảo vệ thêm cho người đi xe đạp.","h2":"Ở Connecticut, tài xế không nhường đường cho người đi xe đạp sẽ bị phạt gấp đôi.","p":"Đúng. Không nhường đường cho người đi xe đạp nghĩa là bị phạt gấp đôi."},"tl":{"q":"Sa Connecticut, ano ang espesyal sa multa sa hindi pagbibigay ng right-of-way sa nagbibisikleta?","o":["Dinodoble ito","Umiiral lang ito sa gabi","Ang nagbibisikleta ang nagbabayad nito","Mas mababa ito kaysa sa kotse"],"h1":"Binibigyan ng batas ng dagdag na proteksyon ang mga nagbibisikleta.","h2":"Sa Connecticut, dinodoble ang multa ng mga driver na hindi nagbibigay ng right-of-way sa nagbibisikleta.","p":"Tama. Doble ang multa kapag hindi pinagbigyan ang nagbibisikleta."},"ar":{"q":"في Connecticut، ما الخاص في غرامة عدم إعطاء حق المرور لراكب الدراجة الهوائية؟","o":["تُضاعَف","تنطبق ليلًا فقط","يدفعها راكب الدراجة","أقل من غرامة السيارة"],"h1":"يعطي القانون راكبي الدراجات حماية إضافية.","h2":"في Connecticut تُضاعَف الغرامة على السائقين الذين لا يعطون حق المرور لراكب الدراجة الهوائية.","p":"صحيح. عدم إعطاء حق المرور لراكب الدراجة يعني غرامة مضاعفة."},"ref":{"doc":"CT","page":17}},{"id":"ct-045","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, who must wear a helmet when riding a bicycle?","o":["Only riders on highways","Every rider of any age","Riders under 16 years old","Riders under 10 years old"],"h1":"The rule covers children and young teens.","h2":"In Connecticut, bicycle riders under 16 years old must wear a helmet.","p":"Right. Riders under 16 must wear a helmet."},"es":{"q":"En Connecticut, ¿quién debe usar casco al andar en bicicleta?","o":["Solo quienes van por autopistas","Todos los ciclistas de cualquier edad","Los ciclistas menores de 16 años","Los ciclistas menores de 10 años"],"h1":"La regla cubre a los niños y a los adolescentes más jóvenes.","h2":"En Connecticut, los ciclistas menores de 16 años deben usar casco.","p":"Correcto. Los menores de 16 años deben usar casco."},"zh":{"q":"在 Connecticut，骑自行车时谁必须戴头盔？","o":["只有在高速公路上骑车的人","所有年龄的骑车人","16 岁以下的骑车人","10 岁以下的骑车人"],"h1":"这条规定包括儿童和年纪较小的青少年。","h2":"在 Connecticut，16 岁以下的骑车人必须戴头盔。","p":"对。16 岁以下的骑车人必须戴头盔。"},"vi":{"q":"Ở Connecticut, ai phải đội mũ bảo hiểm khi đi xe đạp?","o":["Chỉ người đi trên xa lộ","Mọi người ở mọi lứa tuổi","Người dưới 16 tuổi","Người dưới 10 tuổi"],"h1":"Quy định này áp dụng cho trẻ em và thiếu niên nhỏ tuổi.","h2":"Ở Connecticut, người đi xe đạp dưới 16 tuổi phải đội mũ bảo hiểm.","p":"Đúng. Người đi xe đạp dưới 16 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa Connecticut, sino ang dapat magsuot ng helmet kapag nagbibisikleta?","o":["Ang mga nagbibisikleta sa highway lang","Lahat ng nagbibisikleta sa anumang edad","Ang mga nagbibisikleta na wala pang 16 taong gulang","Ang mga nagbibisikleta na wala pang 10 taong gulang"],"h1":"Saklaw ng patakaran ang mga bata at batang teenager.","h2":"Sa Connecticut, dapat magsuot ng helmet ang mga nagbibisikleta na wala pang 16 taong gulang.","p":"Tama. Dapat mag-helmet ang mga nagbibisikleta na wala pang 16."},"ar":{"q":"في Connecticut، من يجب عليه أن يلبس خوذة عند ركوب الدراجة الهوائية؟","o":["الراكبون على الطرق السريعة فقط","كل راكب من أي عمر","الراكبون تحت 16 سنة","الراكبون تحت 10 سنوات"],"h1":"القاعدة تشمل الأطفال والمراهقين الصغار.","h2":"في Connecticut يجب على راكبي الدراجات الهوائية تحت 16 سنة أن يلبسوا خوذة.","p":"صحيح. يجب على الراكبين تحت 16 سنة أن يلبسوا خوذة."},"ref":{"doc":"CT","page":17}},{"id":"ct-046","scope":"CT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Connecticut, you are on a road with two lanes going your way. Where does the law say you must drive?","o":["In the left lane","In the right lane, except when passing","In either lane, as you like","On the shoulder when traffic is slow"],"h1":"The left lane is meant for passing.","h2":"In Connecticut, when there are fewer than three lanes in your direction, you must drive in the right lane except when passing.","p":"Right. Keep right unless you are passing."},"es":{"q":"En Connecticut, usted va por una vía con dos carriles en su dirección. ¿Por dónde dice la ley que debe manejar?","o":["Por el carril izquierdo","Por el carril derecho, salvo para rebasar","Por cualquier carril, como prefiera","Por el acotamiento cuando el tránsito va lento"],"h1":"El carril izquierdo es para rebasar.","h2":"En Connecticut, cuando hay menos de tres carriles en su dirección, debe manejar por el carril derecho, salvo para rebasar.","p":"Correcto. Manténgase a la derecha, salvo para rebasar."},"zh":{"q":"在 Connecticut，你在一条同方向有两条车道的路上。法律规定你必须在哪里行驶？","o":["在左车道","在右车道，超车时除外","两条车道都可以，随你","车多时在路肩上"],"h1":"左车道是用来超车的。","h2":"在 Connecticut，你的方向少于三条车道时，你必须在右车道行驶，超车时除外。","p":"对。除了超车，都要靠右行驶。"},"vi":{"q":"Ở Connecticut, bạn đang chạy trên con đường có hai làn cùng chiều với bạn. Luật nói bạn phải chạy ở đâu?","o":["Ở làn bên trái","Ở làn bên phải, trừ khi vượt xe","Ở làn nào cũng được, tùy bạn","Trên lề đường khi xe cộ chạy chậm"],"h1":"Làn bên trái dành cho việc vượt xe.","h2":"Ở Connecticut, khi chiều đi của bạn có ít hơn ba làn, bạn phải chạy ở làn bên phải, trừ khi vượt xe.","p":"Đúng. Đi bên phải trừ khi bạn đang vượt xe."},"tl":{"q":"Sa Connecticut, nasa kalsada ka na may dalawang lane papunta sa direksyon mo. Saan ka dapat magmaneho ayon sa batas?","o":["Sa kaliwang lane","Sa kanang lane, maliban kapag nag-o-overtake","Sa kahit anong lane, ayon sa gusto mo","Sa shoulder kapag mabagal ang trapiko"],"h1":"Ang kaliwang lane ay para sa pag-overtake.","h2":"Sa Connecticut, kapag wala pang tatlong lane sa direksyon mo, dapat kang magmaneho sa kanang lane maliban kapag nag-o-overtake.","p":"Tama. Manatili sa kanan maliban kung nag-o-overtake ka."},"ar":{"q":"في Connecticut، أنت على طريق فيه مساران في اتجاهك. أين يقول القانون إنه يجب أن تقود؟","o":["في المسار الأيسر","في المسار الأيمن، إلا عند التجاوز","في أي مسار، كما تريد","على كتف الطريق عندما تكون حركة السير بطيئة"],"h1":"المسار الأيسر مخصّص للتجاوز.","h2":"في Connecticut عندما يكون في اتجاهك أقل من ثلاثة مسارات، يجب أن تقود في المسار الأيمن إلا عند التجاوز.","p":"صحيح. ابقَ على اليمين إلا إذا كنت تتجاوز."},"ref":{"doc":"CT","page":23}},{"id":"ct-047","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, during which dates are studded snow tires allowed?","o":["All year","October 1 to March 31","December 1 to February 28","November 15 to April 30"],"h1":"The season covers late fall, all of winter, and much of spring.","h2":"In Connecticut, studded tires are allowed from November 15 through April 30.","p":"Right. Studded tires are allowed from November 15 to April 30."},"es":{"q":"En Connecticut, ¿en qué fechas se permiten las llantas con clavos para nieve?","o":["Todo el año","Del 1 de octubre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Del 15 de noviembre al 30 de abril"],"h1":"La temporada cubre el final del otoño, todo el invierno y buena parte de la primavera.","h2":"En Connecticut, las llantas con clavos se permiten del 15 de noviembre al 30 de abril.","p":"Correcto. Se permiten del 15 de noviembre al 30 de abril."},"zh":{"q":"在 Connecticut，哪段日期内允许使用带钉的雪地轮胎？","o":["全年","10 月 1 日到 3 月 31 日","12 月 1 日到 2 月 28 日","11 月 15 日到 4 月 30 日"],"h1":"这个季节包括晚秋、整个冬天和大半个春天。","h2":"在 Connecticut，从 11 月 15 日到 4 月 30 日允许使用带钉轮胎。","p":"对。带钉轮胎允许从 11 月 15 日用到 4 月 30 日。"},"vi":{"q":"Ở Connecticut, lốp xe có đinh chống trượt tuyết được phép dùng trong khoảng ngày nào?","o":["Cả năm","Từ 1 tháng 10 đến 31 tháng 3","Từ 1 tháng 12 đến 28 tháng 2","Từ 15 tháng 11 đến 30 tháng 4"],"h1":"Mùa này gồm cuối mùa thu, cả mùa đông và phần lớn mùa xuân.","h2":"Ở Connecticut, lốp có đinh được phép dùng từ 15 tháng 11 đến hết 30 tháng 4.","p":"Đúng. Lốp có đinh được phép dùng từ 15 tháng 11 đến 30 tháng 4."},"tl":{"q":"Sa Connecticut, sa anong mga petsa pinapayagan ang studded na snow tire?","o":["Buong taon","Oktubre 1 hanggang Marso 31","Disyembre 1 hanggang Pebrero 28","Nobyembre 15 hanggang Abril 30"],"h1":"Saklaw ng panahon ang huling bahagi ng taglagas, buong taglamig, at malaking bahagi ng tagsibol.","h2":"Sa Connecticut, pinapayagan ang studded tire mula Nobyembre 15 hanggang Abril 30.","p":"Tama. Pinapayagan ang studded tire mula Nobyembre 15 hanggang Abril 30."},"ar":{"q":"في Connecticut، في أي فترة يُسمح بإطارات الثلج ذات المسامير؟","o":["طوال السنة","من 1 أكتوبر إلى 31 مارس","من 1 ديسمبر إلى 28 فبراير","من 15 نوفمبر إلى 30 أبريل"],"h1":"الموسم يشمل آخر الخريف والشتاء كله ومعظم الربيع.","h2":"في Connecticut يُسمح بالإطارات ذات المسامير من 15 نوفمبر حتى 30 أبريل.","p":"صحيح. يُسمح بالإطارات ذات المسامير من 15 نوفمبر إلى 30 أبريل."},"ref":{"doc":"CT","page":25}},{"id":"ct-049","scope":"CT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Connecticut, when you park next to a curb, what is the farthest your car may be from it?","o":["Three feet","Two feet","One foot","Six feet"],"h1":"Park as close to the curb as you can.","h2":"In Connecticut, you may not park more than one foot from the curb.","p":"Right. Park no more than one foot from the curb."},"es":{"q":"En Connecticut, cuando se estaciona junto a la acera, ¿a qué distancia máxima de ella puede quedar su auto?","o":["Tres pies","Dos pies","Un pie","Seis pies"],"h1":"Estaciónese tan cerca de la acera como pueda.","h2":"En Connecticut, no se puede estacionar a más de un pie de la acera.","p":"Correcto. Estaciónese a no más de un pie de la acera."},"zh":{"q":"在 Connecticut，你靠路缘停车时，车离路缘最远可以有多远？","o":["3 英尺","2 英尺","1 英尺","6 英尺"],"h1":"停车时要尽量靠近路缘。","h2":"在 Connecticut，你停车时离路缘不可以超过 1 英尺。","p":"对。停车时离路缘不超过 1 英尺。"},"vi":{"q":"Ở Connecticut, khi đậu xe sát lề đường, xe của bạn được cách lề xa nhất là bao nhiêu?","o":["3 feet","2 feet","1 foot","6 feet"],"h1":"Hãy đậu xe sát lề đường nhất có thể.","h2":"Ở Connecticut, bạn không được đậu xe cách lề đường hơn 1 foot.","p":"Đúng. Đậu xe cách lề đường không quá 1 foot."},"tl":{"q":"Sa Connecticut, kapag pumarada ka sa tabi ng curb, ano ang pinakamalayong puwedeng layo ng kotse mo rito?","o":["3 feet","2 feet","1 foot","6 feet"],"h1":"Pumarada nang pinakamalapit sa curb hangga't kaya mo.","h2":"Sa Connecticut, bawal kang pumarada nang mahigit 1 foot ang layo mula sa curb.","p":"Tama. Pumarada nang hindi hihigit sa 1 foot mula sa curb."},"ar":{"q":"في Connecticut، عندما توقف سيارتك بجانب الرصيف، ما أبعد مسافة يجوز أن تكون بينها وبين الرصيف؟","o":["3 أقدام","قدمان","قدم واحدة","6 أقدام"],"h1":"أوقف السيارة أقرب ما تستطيع إلى الرصيف.","h2":"في Connecticut لا يجوز لك أن توقف سيارتك على بُعد أكثر من قدم واحدة من الرصيف.","p":"صحيح. أوقف السيارة على بُعد قدم واحدة على الأكثر من الرصيف."},"ref":{"doc":"CT","page":37}},{"id":"ct-050","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, a person stands at the curb at a crosswalk and raises a hand toward traffic. What must you do?","o":["Honk so the person waits","Slow or stop and let the person cross","Keep going, since the person is not in the road yet","Stop only if there is a traffic light"],"h1":"Showing the intent to cross counts, even before stepping into the road.","h2":"In Connecticut, you must slow or stop and yield when a person at the curb raises a hand to show they want to cross at a crosswalk.","p":"Right. A raised hand at the curb means you must yield."},"es":{"q":"En Connecticut, una persona está en la acera junto a un cruce peatonal y levanta la mano hacia el tránsito. ¿Qué debe hacer usted?","o":["Tocar la bocina para que espere","Reducir la velocidad o parar y dejarla cruzar","Seguir, porque todavía no está en la calle","Parar solo si hay semáforo"],"h1":"Mostrar la intención de cruzar cuenta, aun antes de bajar a la calle.","h2":"En Connecticut, usted debe reducir la velocidad o parar y ceder el paso cuando una persona en la acera levanta la mano para mostrar que quiere cruzar por un cruce peatonal.","p":"Correcto. Una mano levantada en la acera significa que debe ceder el paso."},"zh":{"q":"在 Connecticut，一个人站在人行横道边的路缘上，向车流举起手。你必须怎么做？","o":["按喇叭让这个人等","减速或停车，让这个人过马路","继续开，因为这个人还没走到路上","只有有红绿灯时才停车"],"h1":"表示想过马路就算数，即使还没走到路上。","h2":"在 Connecticut，当有人在路缘举手表示想从人行横道过马路时，你必须减速或停车并让路。","p":"对。路缘上有人举手，你就必须让路。"},"vi":{"q":"Ở Connecticut, một người đứng ở lề đường tại vạch qua đường và giơ tay về phía xe cộ. Bạn phải làm gì?","o":["Bấm còi để người đó chờ","Chạy chậm lại hoặc dừng để người đó băng qua","Cứ chạy tiếp, vì người đó chưa xuống đường","Chỉ dừng nếu có đèn giao thông"],"h1":"Việc cho thấy ý muốn băng qua đã được tính, kể cả trước khi bước xuống đường.","h2":"Ở Connecticut, bạn phải chạy chậm lại hoặc dừng và nhường đường khi một người ở lề đường giơ tay để cho thấy họ muốn băng qua tại vạch qua đường.","p":"Đúng. Người ở lề đường giơ tay nghĩa là bạn phải nhường đường."},"tl":{"q":"Sa Connecticut, may taong nakatayo sa curb sa tawiran at nagtaas ng kamay sa trapiko. Ano ang dapat mong gawin?","o":["Bumusina para maghintay ang tao","Bumagal o huminto at patawirin ang tao","Tuloy lang, dahil wala pa sa kalsada ang tao","Huminto lang kung may traffic light"],"h1":"Bilang na ang pagpapakita na gustong tumawid, kahit hindi pa siya nakakatapak sa kalsada.","h2":"Sa Connecticut, dapat kang bumagal o huminto at magbigay-daan kapag nagtaas ng kamay ang tao sa curb para ipakitang gusto niyang tumawid sa tawiran.","p":"Tama. Kapag may nagtaas ng kamay sa curb, dapat kang magbigay-daan."},"ar":{"q":"في Connecticut، شخص يقف على الرصيف عند ممر المشاة ويرفع يده نحو السيارات. ماذا يجب أن تفعل؟","o":["أن تُطلق البوق لكي ينتظر الشخص","أن تُبطئ أو تتوقف وتترك الشخص يعبر","أن تستمر، لأن الشخص ليس في الطريق بعد","أن تتوقف فقط إذا كانت هناك إشارة مرور"],"h1":"إظهار نيّة العبور يُحسب، حتى قبل النزول إلى الطريق.","h2":"في Connecticut يجب أن تُبطئ أو تتوقف وتعطي حق المرور عندما يرفع شخص على الرصيف يده ليُظهر أنه يريد العبور من ممر المشاة.","p":"صحيح. اليد المرفوعة على الرصيف تعني أنه يجب أن تعطي حق المرور."},"ref":{"doc":"CT","page":16}},{"id":"ct-051","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, you come up behind a bicycle in a no-passing zone with a double yellow line. What does state law allow?","o":["You must stay behind it until the zone ends","You may pass only after you honk","You may pass it on the right shoulder","You may cross the line to pass it when it is safe"],"h1":"The law makes an exception for slow road users like bicycles.","h2":"In Connecticut, you may cross a double yellow line in a no-passing zone to pass a bicycle or other slow traffic, but only when you can see far enough ahead to pass safely.","p":"Right. You may pass it when it is safe to do so."},"es":{"q":"En Connecticut, usted va detrás de una bicicleta en una zona de no rebasar con doble línea amarilla. ¿Qué permite la ley del estado?","o":["Debe quedarse detrás hasta que termine la zona","Puede rebasar solo después de tocar la bocina","Puede rebasarla por el acotamiento derecho","Puede cruzar la línea para rebasarla cuando sea seguro"],"h1":"La ley hace una excepción para usuarios lentos de la vía, como las bicicletas.","h2":"En Connecticut, usted puede cruzar la doble línea amarilla en una zona de no rebasar para pasar a una bicicleta u otro tránsito lento, pero solo cuando pueda ver lo bastante adelante para hacerlo con seguridad.","p":"Correcto. Puede rebasarla cuando sea seguro hacerlo."},"zh":{"q":"在 Connecticut，你在有双黄线的禁止超车区跟在一辆自行车后面。州法律允许你怎么做？","o":["你必须一直跟在后面，直到禁止超车区结束","你只有按喇叭后才可以超车","你可以从右边的路肩超过它","安全时，你可以越过黄线超过它"],"h1":"法律对自行车这样慢速的道路使用者有例外。","h2":"在 Connecticut，你可以在禁止超车区越过双黄线超过自行车或其他慢速车辆，但只有在你能看清前方足够远、可以安全超车时才可以。","p":"对。安全时你可以超过它。"},"vi":{"q":"Ở Connecticut, bạn đến sau một chiếc xe đạp trong khu vực cấm vượt có vạch đôi màu vàng. Luật tiểu bang cho phép gì?","o":["Bạn phải ở phía sau cho đến hết khu vực đó","Bạn chỉ được vượt sau khi bấm còi","Bạn được vượt nó bằng lề đường bên phải","Bạn được lấn qua vạch để vượt khi an toàn"],"h1":"Luật có ngoại lệ cho người dùng đường chạy chậm như xe đạp.","h2":"Ở Connecticut, bạn được lấn qua vạch đôi màu vàng trong khu vực cấm vượt để vượt xe đạp hoặc xe chạy chậm khác, nhưng chỉ khi bạn thấy đủ xa phía trước để vượt an toàn.","p":"Đúng. Bạn được vượt khi làm vậy an toàn."},"tl":{"q":"Sa Connecticut, napunta ka sa likod ng bisikleta sa no-passing zone na may double yellow line. Ano ang pinapayagan ng batas ng estado?","o":["Dapat kang manatili sa likod nito hanggang matapos ang zone","Puwede ka lang lumampas pagkatapos mong bumusina","Puwede mo itong lampasan sa kanang shoulder","Puwede mong tawirin ang linya para lampasan ito kapag ligtas"],"h1":"May exception ang batas para sa mabagal na gumagamit ng kalsada gaya ng bisikleta.","h2":"Sa Connecticut, puwede mong tawirin ang double yellow line sa no-passing zone para lampasan ang bisikleta o iba pang mabagal na sasakyan, pero kapag nakikita mo lang nang sapat na malayo sa unahan para ligtas na lumampas.","p":"Tama. Puwede mo itong lampasan kapag ligtas."},"ar":{"q":"في Connecticut، وصلت خلف دراجة هوائية في منطقة يُمنع فيها التجاوز وفيها خط أصفر مزدوج. ماذا يسمح قانون الولاية؟","o":["يجب أن تبقى خلفها حتى تنتهي المنطقة","يجوز لك أن تتجاوزها فقط بعد أن تُطلق البوق","يجوز لك أن تتجاوزها من كتف الطريق الأيمن","يجوز لك أن تعبر الخط لتتجاوزها عندما يكون ذلك آمنًا"],"h1":"القانون يستثني مستخدمي الطريق البطيئين مثل الدراجات الهوائية.","h2":"في Connecticut يجوز لك أن تعبر الخط الأصفر المزدوج في منطقة منع التجاوز لتتجاوز دراجة هوائية أو مركبة بطيئة أخرى، ولكن فقط عندما ترى مسافة كافية أمامك لتتجاوز بأمان.","p":"صحيح. يجوز لك أن تتجاوزها عندما يكون ذلك آمنًا."},"ref":{"doc":"CT","page":18}},{"id":"ct-052","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, a person is blind in one eye. What must the other eye have to meet the vision standard?","o":["20/20 vision and a field of 60 degrees","20/60 vision and a field of 80 degrees","20/40 vision and a field of at least 100 degrees","20/50 vision and a field of 120 degrees"],"h1":"The sharpness needed is the same as the normal standard for everyone.","h2":"In Connecticut, if you are blind in one eye, the other eye must see at least 20/40 and have a visual field of 100 degrees or more.","p":"Right. The other eye needs 20/40 and a field of at least 100 degrees."},"es":{"q":"En Connecticut, una persona es ciega de un ojo. ¿Qué debe tener el otro ojo para cumplir el requisito de visión?","o":["Visión de 20/20 y un campo de 60 grados","Visión de 20/60 y un campo de 80 grados","Visión de 20/40 y un campo de al menos 100 grados","Visión de 20/50 y un campo de 120 grados"],"h1":"La nitidez que se pide es la misma del requisito normal para todos.","h2":"En Connecticut, si usted es ciego de un ojo, el otro ojo debe ver al menos 20/40 y tener un campo visual de 100 grados o más.","p":"Correcto. El otro ojo necesita 20/40 y un campo de al menos 100 grados."},"ref":{"doc":"CT","page":5}},{"id":"ct-053","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, who must take the 8-hour Safe Driving Practices course before getting a license?","o":["Any new driver of any age with no prior license","Only new drivers who are under 18","Only drivers who fail the road test once","Only drivers moving here from abroad"],"h1":"Age does not matter for this course.","h2":"In Connecticut, anyone of any age who has never held a Connecticut license or a valid license from another state must take the 8-hour Safe Driving Practices course.","p":"Right. Every first-time driver takes the 8-hour course, whatever their age."},"es":{"q":"En Connecticut, ¿quién debe tomar el curso de 8 horas de Prácticas de Manejo Seguro antes de obtener una licencia?","o":["Todo conductor nuevo de cualquier edad sin licencia previa","Solo los conductores nuevos menores de 18 años","Solo quienes reprueban una vez el examen de manejo","Solo quienes llegan a vivir aquí desde otro país"],"h1":"La edad no importa para este curso.","h2":"En Connecticut, toda persona de cualquier edad que nunca tuvo licencia de Connecticut ni una licencia válida de otro estado debe tomar el curso de 8 horas de Prácticas de Manejo Seguro.","p":"Correcto. Todo conductor primerizo toma el curso de 8 horas, sin importar su edad."},"ref":{"doc":"CT","page":4}},{"id":"ct-054","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, where must the person teaching a learner's permit holder sit?","o":["In the back seat behind the driver","In the front passenger seat next to the learner","Anywhere in the car, as long as they are awake","In a second car that follows the learner"],"h1":"They must be able to take over quickly.","h2":"In Connecticut, the person giving instruction must sit in the front passenger seat beside the learner, ready to take control.","p":"Right. The trainer sits in the front passenger seat."},"es":{"q":"En Connecticut, ¿dónde debe sentarse la persona que le enseña a quien tiene permiso de aprendizaje?","o":["En el asiento de atrás, detrás del conductor","En el asiento del pasajero de adelante, junto al aprendiz","En cualquier lugar del auto, si está despierta","En otro auto que sigue al aprendiz"],"h1":"Debe poder tomar el control rápidamente.","h2":"En Connecticut, la persona que da la instrucción debe sentarse en el asiento del pasajero de adelante, junto al aprendiz, lista para tomar el control.","p":"Correcto. El instructor se sienta en el asiento del pasajero de adelante."},"ref":{"doc":"CT","page":5}},{"id":"ct-055","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, how much training must a parent or guardian of a 16- or 17-year-old permit holder complete?","o":["None, it is only for the teen","A 30-minute online video","An 8-hour driving course alone","A 2-hour class with the teen"],"h1":"It is a short class about teen driving laws and dangers.","h2":"In Connecticut, a parent or legal guardian of a 16- or 17-year-old permit holder must take a 2-hour class with the teen about teen driving laws and dangers.","p":"Right. Parents take a 2-hour class with their teen."},"es":{"q":"En Connecticut, ¿cuánta capacitación debe completar el padre, la madre o el tutor de un joven de 16 o 17 años con permiso de aprendizaje?","o":["Ninguna, es solo para el joven","Un video en línea de 30 minutos","Un curso de manejo de 8 horas, solo","Una clase de 2 horas con el joven"],"h1":"Es una clase corta sobre las leyes y los peligros del manejo de adolescentes.","h2":"En Connecticut, el padre, la madre o el tutor legal de un joven de 16 o 17 años con permiso debe tomar una clase de 2 horas con el joven sobre las leyes y los peligros del manejo de adolescentes.","p":"Correcto. Los padres toman una clase de 2 horas con su hijo."},"ref":{"doc":"CT","page":6}},{"id":"ct-056","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, the 8-hour safe driving course includes at least how many hours on alcohol and drugs?","o":["4 hours","1 hour","2 hours","8 hours"],"h1":"It is half of the course.","h2":"In Connecticut, at least 4 hours of the 8-hour safe driving course cover alcohol, drugs, and their dangers and penalties.","p":"Right. At least half the course, 4 hours, is about alcohol and drugs."},"es":{"q":"En Connecticut, ¿cuántas horas como mínimo sobre alcohol y drogas incluye el curso de manejo seguro de 8 horas?","o":["4 horas","1 hora","2 horas","8 horas"],"h1":"Es la mitad del curso.","h2":"En Connecticut, al menos 4 horas del curso de manejo seguro de 8 horas tratan sobre el alcohol, las drogas, sus peligros y sus castigos.","p":"Correcto. Al menos la mitad del curso, 4 horas, trata sobre alcohol y drogas."},"ref":{"doc":"CT","page":6}},{"id":"ct-057","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, a 16-year-old has no parent, guardian, foster parent or grandparent to do home training. Who else may do it, if qualified?","o":["A neighbor","A family friend","An older brother or sister","A school classmate"],"h1":"It must be a close relative.","h2":"In Connecticut, if there is no parent, guardian, foster parent or grandparent, a qualified uncle, aunt, brother, sister or stepparent may do home training.","p":"Right. A qualified brother or sister may train the teen."},"es":{"q":"En Connecticut, un joven de 16 años no tiene padre, madre, tutor, padre de crianza ni abuelo que le dé el entrenamiento en casa. ¿Quién más puede hacerlo, si cumple los requisitos?","o":["Un vecino","Un amigo de la familia","Un hermano o una hermana mayor","Un compañero de la escuela"],"h1":"Debe ser un pariente cercano.","h2":"En Connecticut, si no hay padre, madre, tutor, padre de crianza ni abuelo, puede dar el entrenamiento en casa un tío, una tía, un hermano, una hermana o un padrastro que cumpla los requisitos.","p":"Correcto. Un hermano o una hermana que cumpla los requisitos puede entrenar al joven."},"ref":{"doc":"CT","page":6}},{"id":"ct-058","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 17-year-old with a license from another state moves here. What course must they take to get a Connecticut license?","o":["No course at all","The 8-hour safe driving course","A 30-hour classroom course only","A motorcycle safety course"],"h1":"It is the same short course that new teen drivers take.","h2":"In Connecticut, 16- and 17-year-old drivers licensed in another state must complete the 8-hour safe driving course to get a Connecticut license.","p":"Right. They must take the 8-hour course."},"es":{"q":"En Connecticut, un joven de 17 años con licencia de otro estado se muda aquí. ¿Qué curso debe tomar para obtener una licencia de Connecticut?","o":["Ningún curso","El curso de manejo seguro de 8 horas","Solo un curso en aula de 30 horas","Un curso de seguridad en motocicleta"],"h1":"Es el mismo curso corto que toman los conductores adolescentes nuevos.","h2":"En Connecticut, los conductores de 16 y 17 años con licencia de otro estado deben completar el curso de manejo seguro de 8 horas para obtener una licencia de Connecticut.","p":"Correcto. Deben tomar el curso de 8 horas."},"ref":{"doc":"CT","page":6}},{"id":"ct-059","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, you have only a learner's permit. How may you get to your road test?","o":["Alone, if the office is close","Alone, if it is daytime","Alone, if you carry your permit","Not alone; a qualified driver must come"],"h1":"A permit never lets you drive by yourself.","h2":"In Connecticut, a person without a license may not drive alone to the road test location.","p":"Right. You cannot drive to the test alone."},"es":{"q":"En Connecticut, usted solo tiene un permiso de aprendizaje. ¿Cómo puede llegar a su examen de manejo?","o":["Solo, si la oficina está cerca","Solo, si es de día","Solo, si lleva su permiso","No solo; debe ir con un conductor autorizado"],"h1":"Un permiso nunca le deja manejar sin compañía.","h2":"En Connecticut, una persona sin licencia no puede manejar sola hasta el lugar del examen de manejo.","p":"Correcto. No puede manejar solo hasta el examen."},"ref":{"doc":"CT","page":7}},{"id":"ct-060","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, may you take your road test in a rented car if you do not have a valid license?","o":["No, a rented car is not allowed","Yes, if the rental is in your name","Yes, if a parent signs the rental","Yes, but only on weekdays"],"h1":"A properly insured long-term lease is a different case.","h2":"In Connecticut, if you do not have a valid driver's license, you cannot take the road test in a rented vehicle.","p":"Right. Without a license, you cannot test in a rented car."},"es":{"q":"En Connecticut, ¿puede tomar el examen de manejo en un auto rentado si no tiene una licencia válida?","o":["No, un auto rentado no se permite","Sí, si la renta está a su nombre","Sí, si uno de sus padres firma la renta","Sí, pero solo entre semana"],"h1":"Un arrendamiento a largo plazo bien asegurado es un caso distinto.","h2":"En Connecticut, si usted no tiene una licencia de conducir válida, no puede tomar el examen de manejo en un vehículo rentado.","p":"Correcto. Sin licencia, no puede hacer el examen en un auto rentado."},"ref":{"doc":"CT","page":7}},{"id":"ct-061","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, the examiner finds that your test car is unsafe. What happens?","o":["You fail and wait seven days","You pay a fee and test in a DMV car","No test is given, and you reschedule for no fee","You take the test anyway with a warning"],"h1":"You are not charged for this.","h2":"In Connecticut, if the test vehicle is unsafe, no road test is given and you reschedule it at no cost.","p":"Right. You reschedule the test for free."},"es":{"q":"En Connecticut, el examinador ve que su auto para el examen no es seguro. ¿Qué pasa?","o":["Usted reprueba y espera siete días","Paga un cargo y hace el examen en un auto del DMV","No se hace el examen y usted lo reprograma sin costo","Hace el examen de todos modos con una advertencia"],"h1":"No se le cobra por esto.","h2":"En Connecticut, si el vehículo del examen no es seguro, no se hace el examen de manejo y usted lo reprograma sin costo.","p":"Correcto. Reprograma el examen gratis."},"ref":{"doc":"CT","page":7}},{"id":"ct-062","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 17-year-old volunteer firefighter is driving home from an emergency call at midnight. Does the teen curfew apply?","o":["Yes, the curfew has no exceptions","No, this trip is an exception","Yes, unless a parent is in the car","No, but only before 1 a.m."],"h1":"Some emergency volunteers are treated differently.","h2":"In Connecticut, the teen curfew and passenger limits do not apply to active volunteer firefighters or ambulance members going to or returning from an emergency call.","p":"Right. Volunteer emergency duty is an exception to the curfew."},"es":{"q":"En Connecticut, un bombero voluntario de 17 años vuelve a casa manejando a medianoche después de una llamada de emergencia. ¿Se aplica el horario restringido para adolescentes?","o":["Sí, el horario no tiene excepciones","No, este viaje es una excepción","Sí, a menos que vaya uno de sus padres","No, pero solo antes de la 1 a.m."],"h1":"Algunos voluntarios de emergencia reciben un trato distinto.","h2":"En Connecticut, el horario restringido y los límites de pasajeros para adolescentes no se aplican a bomberos o miembros de ambulancia voluntarios activos que van a una llamada de emergencia o vuelven de ella.","p":"Correcto. El servicio voluntario de emergencia es una excepción al horario."},"ref":{"doc":"CT","page":8}},{"id":"ct-063","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, which of these may a 17-year-old licensed driver NOT drive?","o":["A family pickup truck","A car with an automatic transmission","A borrowed car with insurance","A vanpool vehicle"],"h1":"It is a vehicle that carries groups of riders to work.","h2":"In Connecticut, permit holders and 16- and 17-year-old drivers may not drive a vanpool vehicle or any vehicle that needs a public passenger transportation permit.","p":"Right. Teens may not drive a vanpool vehicle."},"es":{"q":"En Connecticut, ¿cuál de estos vehículos NO puede manejar un conductor de 17 años con licencia?","o":["La camioneta pickup de la familia","Un auto con transmisión automática","Un auto prestado que tiene seguro","Un vehículo de transporte compartido (vanpool)"],"h1":"Es un vehículo que lleva grupos de personas al trabajo.","h2":"En Connecticut, quienes tienen permiso de aprendizaje y los conductores de 16 y 17 años no pueden manejar un vehículo de transporte compartido (vanpool) ni ningún vehículo que necesite un permiso de transporte público de pasajeros.","p":"Correcto. Los adolescentes no pueden manejar un vanpool."},"ref":{"doc":"CT","page":8}},{"id":"ct-064","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a limited license allows driving only during daylight. What hours does that mean?","o":["From half an hour before sunrise to half an hour after sunset","From one hour after sunrise to one hour before sunset","From 6 a.m. until 6 p.m. in every season","From sunrise until the street lights turn on"],"h1":"It starts a little before the sun comes up.","h2":"In Connecticut, a daylight-only limited license allows driving from half an hour before sunrise until half an hour after sunset.","p":"Right. Daylight means half an hour before sunrise to half an hour after sunset."},"es":{"q":"En Connecticut, una licencia limitada permite manejar solo con luz del día. ¿Qué horario significa eso?","o":["Desde media hora antes del amanecer hasta media hora después del atardecer","Desde una hora después del amanecer hasta una hora antes del atardecer","De 6 a.m. a 6 p.m. en todas las estaciones","Desde el amanecer hasta que se encienden las luces de la calle"],"h1":"Empieza un poco antes de que salga el sol.","h2":"En Connecticut, una licencia limitada solo de día permite manejar desde media hora antes del amanecer hasta media hora después del atardecer.","p":"Correcto. Luz del día significa desde media hora antes del amanecer hasta media hora después del atardecer."},"ref":{"doc":"CT","page":9}},{"id":"ct-065","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, you have a medical condition that affects your driving. How early does the DMV suggest you contact its Driver Services Division before applying for a license?","o":["One week before","Two days before","At least four months before","On the day of your test"],"h1":"It takes time to review medical reports.","h2":"In Connecticut, the DMV recommends contacting the Driver Services Division at least four months before applying if a medical condition affects your driving.","p":"Right. Contact the DMV at least four months ahead."},"es":{"q":"En Connecticut, usted tiene una condición médica que afecta su manejo. ¿Con cuánta anticipación recomienda el DMV que se comunique con su División de Servicios al Conductor antes de solicitar la licencia?","o":["Una semana antes","Dos días antes","Al menos cuatro meses antes","El mismo día del examen"],"h1":"Revisar los informes médicos toma tiempo.","h2":"En Connecticut, el DMV recomienda comunicarse con la División de Servicios al Conductor al menos cuatro meses antes de solicitar la licencia si una condición médica afecta su manejo.","p":"Correcto. Comuníquese con el DMV al menos cuatro meses antes."},"ref":{"doc":"CT","page":9}},{"id":"ct-066","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, your car fails its emissions inspection. How long do you have to fix it and get it rechecked?","o":["10 days","60 days","6 months","1 year"],"h1":"It is about two months.","h2":"In Connecticut, if your vehicle fails the emissions test, you have 60 days to fix the problem and have it retested.","p":"Right. You have 60 days."},"es":{"q":"En Connecticut, su auto no pasa la inspección de emisiones. ¿Cuánto tiempo tiene para repararlo y volver a revisarlo?","o":["10 días","60 días","6 meses","1 año"],"h1":"Son unos dos meses.","h2":"En Connecticut, si su vehículo no pasa la prueba de emisiones, tiene 60 días para reparar el problema y hacer que lo vuelvan a revisar.","p":"Correcto. Tiene 60 días."},"ref":{"doc":"CT","page":11}},{"id":"ct-067","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, how must a 3-year-old child who weighs 35 pounds ride in a car?","o":["In a booster seat with a lap belt","With only an adult seat belt","On an adult's lap in the back","In a car seat with a 5-point harness"],"h1":"Children this age still need a harness with five straps.","h2":"In Connecticut, a child aged 2 to 5, or under 40 pounds, must ride in a rear- or forward-facing car seat with a 5-point harness.","p":"Right. This child needs a car seat with a 5-point harness."},"es":{"q":"En Connecticut, ¿cómo debe viajar en el auto un niño de 3 años que pesa 35 libras?","o":["En un asiento elevado con cinturón de regazo","Solo con el cinturón de seguridad de adulto","En las piernas de un adulto, atrás","En un asiento de seguridad con arnés de 5 puntos"],"h1":"Los niños de esta edad todavía necesitan un arnés de cinco correas.","h2":"En Connecticut, un niño de 2 a 5 años, o de menos de 40 libras, debe viajar en un asiento de seguridad mirando hacia atrás o hacia adelante con arnés de 5 puntos.","p":"Correcto. Este niño necesita un asiento con arnés de 5 puntos."},"ref":{"doc":"CT","page":12}},{"id":"ct-068","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, a 6-year-old weighs 50 pounds. Which car seat options does the law allow?","o":["A 5-point harness seat or a booster seat","Only the adult seat belt","Only a rear-facing seat","Sitting on a pillow with a lap belt"],"h1":"This child is between the harness stage and the seat belt stage.","h2":"In Connecticut, a child aged 5 to 8, or weighing 40 to 60 pounds, must ride in a 5-point harness seat or a booster seat.","p":"Right. A harness seat or a booster seat is required."},"es":{"q":"En Connecticut, un niño de 6 años pesa 50 libras. ¿Qué opciones de asiento permite la ley?","o":["Un asiento con arnés de 5 puntos o un asiento elevado","Solo el cinturón de seguridad de adulto","Solo un asiento mirando hacia atrás","Sentado sobre una almohada con cinturón de regazo"],"h1":"Este niño está entre la etapa del arnés y la del cinturón de seguridad.","h2":"En Connecticut, un niño de 5 a 8 años, o que pesa entre 40 y 60 libras, debe viajar en un asiento con arnés de 5 puntos o en un asiento elevado.","p":"Correcto. Se requiere un asiento con arnés o un asiento elevado."},"ref":{"doc":"CT","page":12}},{"id":"ct-069","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, where may you NOT put a rear-facing child seat?","o":["In the back seat behind the driver","In the middle of the back seat","In the front seat with a working passenger airbag","In the back seat behind the passenger"],"h1":"Think about what opens fast in a crash.","h2":"In Connecticut, the law does not allow a rear-facing child seat in a front seat that has a working passenger-side airbag.","p":"Right. Never in front of an active passenger airbag."},"es":{"q":"En Connecticut, ¿dónde NO puede poner un asiento infantil mirando hacia atrás?","o":["En el asiento de atrás, detrás del conductor","En el centro del asiento de atrás","En el asiento de adelante con bolsa de aire del pasajero activa","En el asiento de atrás, detrás del pasajero"],"h1":"Piense en lo que se abre muy rápido en un choque.","h2":"En Connecticut, la ley no permite poner un asiento infantil mirando hacia atrás en un asiento de adelante que tenga activa la bolsa de aire del pasajero.","p":"Correcto. Nunca frente a una bolsa de aire activa del pasajero."},"ref":{"doc":"CT","page":12}},{"id":"ct-070","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, a child is 20 months old but weighs 33 pounds. Which rule applies?","o":["The weight rule, so a booster seat","The stricter rule, so a rear-facing seat","The parent may choose any seat","The age rule, so a seat belt only"],"h1":"When age and weight point to different seats, the law picks the safer one.","h2":"In Connecticut, when a child's age and weight fall in different groups, the more protective rule applies, so a child under 2 rides in a rear-facing seat.","p":"Right. The stricter rule applies: a rear-facing seat."},"es":{"q":"En Connecticut, un niño tiene 20 meses pero pesa 33 libras. ¿Qué regla se aplica?","o":["La del peso, así que un asiento elevado","La más estricta, así que un asiento mirando hacia atrás","Los padres pueden elegir cualquier asiento","La de la edad, así que solo el cinturón"],"h1":"Cuando la edad y el peso indican asientos distintos, la ley elige el más seguro.","h2":"En Connecticut, cuando la edad y el peso de un niño caen en grupos distintos, se aplica la regla que más protege, así que un niño menor de 2 años viaja en un asiento mirando hacia atrás.","p":"Correcto. Se aplica la regla más estricta: un asiento mirando hacia atrás."},"ref":{"doc":"CT","page":12}},{"id":"ct-071","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, who is responsible for making sure a 12-year-old passenger wears a seat belt?","o":["Only the child's parent","The child alone","The front seat passenger","The driver of the car"],"h1":"Think of who is in charge of the car.","h2":"In Connecticut, every driver must make sure any passenger between 7 and 16 years old is wearing a seat belt.","p":"Right. The driver must make sure passengers aged 7 to 16 buckle up."},"es":{"q":"En Connecticut, ¿quién es responsable de que un pasajero de 12 años use el cinturón de seguridad?","o":["Solo el padre o la madre del niño","El niño solo","El pasajero de adelante","El conductor del auto"],"h1":"Piense en quién está a cargo del auto.","h2":"En Connecticut, todo conductor debe asegurarse de que cualquier pasajero de 7 a 16 años use el cinturón de seguridad.","p":"Correcto. El conductor debe asegurarse de que los pasajeros de 7 a 16 años usen el cinturón."},"ref":{"doc":"CT","page":13}},{"id":"ct-072","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, when may an adult driver use a hand-held phone?","o":["When safely parked on the shoulder","When stopped at a red light","When stuck in slow traffic","When driving under 25 mph"],"h1":"The car must be out of traffic, not just stopped.","h2":"In Connecticut, an adult driver may pick up a hand-held phone once safely parked on the side or shoulder of the road, but not while stopped at a light or in traffic; emergency calls are the other exception.","p":"Right. Park safely off the road first."},"es":{"q":"En Connecticut, ¿cuándo puede un conductor adulto usar un teléfono en la mano?","o":["Cuando está estacionado con seguridad en el acotamiento","Cuando está detenido en un semáforo en rojo","Cuando está atrapado en tránsito lento","Cuando maneja a menos de 25 mph"],"h1":"El auto debe estar fuera del tránsito, no solo detenido.","h2":"En Connecticut, un conductor adulto puede usar un teléfono en la mano una vez estacionado con seguridad al lado o en el acotamiento de la vía, pero no mientras está detenido en un semáforo o en el tránsito; las llamadas de emergencia son la otra excepción.","p":"Correcto. Primero estaciónese con seguridad fuera de la vía."},"ref":{"doc":"CT","page":13}},{"id":"ct-073","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, a 16-year-old driver sees a crash and needs to call for help. May the teen use a phone?","o":["No, never while driving","Only with a hands-free device","Yes, to call 911 or another emergency service","Only if a parent is in the car"],"h1":"There is one exception for all ages.","h2":"In Connecticut, a driver of any age may use a phone in an emergency to contact an emergency operator, hospital, doctor, ambulance, or fire or police department.","p":"Right. Emergency calls are allowed at any age."},"es":{"q":"En Connecticut, un conductor de 16 años ve un choque y necesita pedir ayuda. ¿Puede usar el teléfono?","o":["No, nunca mientras maneja","Solo con un aparato de manos libres","Sí, para llamar al 911 u otro servicio de emergencia","Solo si va uno de sus padres en el auto"],"h1":"Hay una excepción para todas las edades.","h2":"En Connecticut, un conductor de cualquier edad puede usar el teléfono en una emergencia para comunicarse con un operador de emergencias, un hospital, un médico, una ambulancia, o los bomberos o la policía.","p":"Correcto. Las llamadas de emergencia se permiten a cualquier edad."},"ref":{"doc":"CT","page":13}},{"id":"ct-074","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 17-year-old is convicted a second time of using a cell phone while driving. How long is the license suspended?","o":["30 days","90 days","1 year","Until age 21"],"h1":"It is longer than for the first offense but less than six months.","h2":"In Connecticut, a second cell phone conviction for a 16- or 17-year-old brings a 90-day license suspension.","p":"Right. A second phone offense means 90 days."},"es":{"q":"En Connecticut, un joven de 17 años es declarado culpable por segunda vez de usar el celular mientras maneja. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","90 días","1 año","Hasta los 21 años"],"h1":"Es más que por la primera falta, pero menos de seis meses.","h2":"En Connecticut, una segunda condena por usar el celular para un joven de 16 o 17 años trae una suspensión de la licencia de 90 días.","p":"Correcto. Una segunda falta con el teléfono significa 90 días."},"ref":{"doc":"CT","page":34}},{"id":"ct-075","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, a 16-year-old is convicted a second time of breaking the passenger or curfew rules. How long is the suspension?","o":["30 days or until age 17","60 days or until age 17","90 days, whatever the age","6 months or until age 18, if longer"],"h1":"The second time can last until the teen becomes an adult.","h2":"In Connecticut, a second teen driving restriction conviction brings a suspension of 6 months or until age 18, whichever is longer.","p":"Right. Six months or until 18, whichever is longer."},"es":{"q":"En Connecticut, un joven de 16 años es declarado culpable por segunda vez de no cumplir las reglas de pasajeros o de horario. ¿Cuánto dura la suspensión?","o":["30 días o hasta los 17 años","60 días o hasta los 17 años","90 días, sin importar la edad","6 meses o hasta los 18 años, si es más largo"],"h1":"La segunda vez puede durar hasta que el joven sea adulto.","h2":"En Connecticut, una segunda condena por no cumplir las restricciones para adolescentes trae una suspensión de 6 meses o hasta los 18 años, lo que sea más largo.","p":"Correcto. Seis meses o hasta los 18 años, lo que sea más largo."},"ref":{"doc":"CT","page":34}},{"id":"ct-076","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what fee must a 16- or 17-year-old pay to restore a license after a teen driving suspension?","o":["$175","$25","$50","$500"],"h1":"It is more than $100 but less than $200.","h2":"In Connecticut, a 16- or 17-year-old must pay a $175 license restoration fee after these suspensions, plus any court fines.","p":"Right. The restoration fee is $175."},"es":{"q":"En Connecticut, ¿qué cargo debe pagar un joven de 16 o 17 años para recuperar la licencia después de una suspensión por manejo de adolescentes?","o":["$175","$25","$50","$500"],"h1":"Es más de $100 pero menos de $200.","h2":"En Connecticut, un joven de 16 o 17 años debe pagar un cargo de $175 para recuperar la licencia después de estas suspensiones, además de las multas del tribunal.","p":"Correcto. El cargo para recuperar la licencia es de $175."},"ref":{"doc":"CT","page":34}},{"id":"ct-077","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, a 17-year-old is convicted of reckless driving for the second time. How long is the license suspended?","o":["30 days","90 days","1 year","10 years"],"h1":"It is twice as long as for the first offense.","h2":"In Connecticut, a 16- or 17-year-old convicted of reckless driving a second time loses the license for one year.","p":"Right. A second reckless driving conviction means a 1-year suspension."},"es":{"q":"En Connecticut, un joven de 17 años es declarado culpable de manejo imprudente por segunda vez. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","90 días","1 año","10 años"],"h1":"Es el doble que por la primera falta.","h2":"En Connecticut, un joven de 16 o 17 años declarado culpable de manejo imprudente por segunda vez pierde la licencia por un año.","p":"Correcto. Una segunda condena por manejo imprudente significa un año de suspensión."},"ref":{"doc":"CT","page":34}},{"id":"ct-078","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, who counts as a \"vulnerable user\" under the Vulnerable User's Law?","o":["A passenger in a car","A highway worker","A driver on the interstate","A rider inside a city bus"],"h1":"These people are outside a vehicle, on or near the road.","h2":"In Connecticut, vulnerable users include pedestrians, bicyclists, wheelchair users, horse riders and highway workers, and drivers who carelessly injure them face higher penalties.","p":"Right. A highway worker is a vulnerable user."},"es":{"q":"En Connecticut, ¿quién cuenta como \"usuario vulnerable\" según la Ley de Usuarios Vulnerables?","o":["Un pasajero dentro de un auto","Un trabajador de carreteras","Un conductor en la autopista interestatal","Un pasajero dentro de un autobús de la ciudad"],"h1":"Son personas que están fuera de un vehículo, en la vía o cerca de ella.","h2":"En Connecticut, los usuarios vulnerables incluyen peatones, ciclistas, personas en silla de ruedas, jinetes y trabajadores de carreteras, y los conductores que los lesionan por descuido reciben castigos más altos.","p":"Correcto. Un trabajador de carreteras es un usuario vulnerable."},"ref":{"doc":"CT","page":16}},{"id":"ct-079","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, a bicyclist is going straight, but the right lane is a right-turn lane. Where may the bicyclist ride?","o":["Only on the sidewalk","In the middle of the left lane","Only on the shoulder","On the left edge of the right-turn lane"],"h1":"The rider stays near the right side but out of the way of turning cars.","h2":"In Connecticut, a bicyclist going straight may ride along the left edge of a right-turn lane.","p":"Right. The bicyclist may use the left edge of the right-turn lane."},"es":{"q":"En Connecticut, un ciclista va a seguir derecho, pero el carril derecho es solo para girar a la derecha. ¿Por dónde puede ir el ciclista?","o":["Solo por la acera","Por el centro del carril izquierdo","Solo por el acotamiento","Por el borde izquierdo del carril para girar a la derecha"],"h1":"El ciclista se queda cerca de la derecha, pero fuera del camino de los autos que giran.","h2":"En Connecticut, un ciclista que sigue derecho puede ir por el borde izquierdo de un carril para girar a la derecha.","p":"Correcto. El ciclista puede usar el borde izquierdo del carril para girar a la derecha."},"ref":{"doc":"CT","page":17}},{"id":"ct-080","scope":"CT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Connecticut, you are about to turn right where there is a bike lane. What does the law say?","o":["You may cross the bike lane but not drive in it before the turn","You must drive in the bike lane for 100 feet before turning","You may drive in the bike lane if no bike is in sight","You must make the turn from the left lane instead"],"h1":"Crossing it is different from driving along it.","h2":"In Connecticut, you may turn across a bicycle lane, but you may not drive in the bike lane as you approach the turn, and you must yield to bicycles in it.","p":"Right. Cross the bike lane to turn, but do not drive in it."},"es":{"q":"En Connecticut, usted va a girar a la derecha donde hay un carril para bicicletas. ¿Qué dice la ley?","o":["Puede cruzar el carril para bicicletas, pero no manejar en él antes del giro","Debe manejar en el carril para bicicletas 100 pies antes de girar","Puede manejar en el carril para bicicletas si no ve ninguna bicicleta","Debe hacer el giro desde el carril izquierdo"],"h1":"Cruzarlo es distinto de manejar a lo largo de él.","h2":"En Connecticut, usted puede cruzar un carril para bicicletas al girar, pero no puede manejar en él al acercarse al giro, y debe ceder el paso a las bicicletas que van en él.","p":"Correcto. Cruce el carril para bicicletas al girar, pero no maneje en él."},"ref":{"doc":"CT","page":17}},{"id":"ct-081","scope":"CT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Connecticut, how many motorcycles may share one traffic lane?","o":["Only one","Three, side by side","Two","As many as fit"],"h1":"The law allows a pair.","h2":"In Connecticut, a motorcycle may use a full lane, and two motorcycles may share one lane.","p":"Right. Two motorcycles may share a lane."},"es":{"q":"En Connecticut, ¿cuántas motocicletas pueden compartir un mismo carril?","o":["Solo una","Tres, una al lado de otra","Dos","Todas las que quepan"],"h1":"La ley permite un par.","h2":"En Connecticut, una motocicleta puede usar un carril completo, y dos motocicletas pueden compartir un carril.","p":"Correcto. Dos motocicletas pueden compartir un carril."},"ref":{"doc":"CT","page":18}},{"id":"ct-082","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, how far behind a motorcycle should you follow on a dry road?","o":["Half a second","3 to 4 seconds","1 to 2 seconds","One car length"],"h1":"It is at least the usual three-second gap, and up to a second more.","h2":"In Connecticut, you should leave a following distance of 3 to 4 seconds behind a motorcycle, and more on wet roads.","p":"Right. Follow a motorcycle by 3 to 4 seconds or more."},"es":{"q":"En Connecticut, ¿a qué distancia debe ir detrás de una motocicleta en una vía seca?","o":["Medio segundo","De 3 a 4 segundos","De 1 a 2 segundos","El largo de un auto"],"h1":"Es al menos la distancia normal de tres segundos, y hasta un segundo más.","h2":"En Connecticut, usted debe dejar una distancia de 3 a 4 segundos detrás de una motocicleta, y más en vías mojadas.","p":"Correcto. Siga a una motocicleta a 3 o 4 segundos o más."},"ref":{"doc":"CT","page":18}},{"id":"ct-083","scope":"CT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Connecticut, a bus ahead in your direction signals to pull back into traffic. What must you do?","o":["Yield and let the bus go","Speed up to pass it first","Honk so the bus waits","Keep going; buses must wait"],"h1":"The law gives the bus a turn in this case.","h2":"In Connecticut, drivers must yield the right-of-way to a bus traveling in the same direction when the bus properly signals.","p":"Right. Yield to the signaling bus."},"es":{"q":"En Connecticut, un autobús adelante, en su misma dirección, pone la señal para volver al tránsito. ¿Qué debe hacer usted?","o":["Ceder el paso y dejar salir al autobús","Acelerar para pasarlo primero","Tocar la bocina para que espere","Seguir; los autobuses deben esperar"],"h1":"En este caso la ley le da el turno al autobús.","h2":"En Connecticut, los conductores deben ceder el paso a un autobús que va en la misma dirección cuando el autobús hace la señal correcta.","p":"Correcto. Ceda el paso al autobús que hace la señal."},"ref":{"doc":"CT","page":18}},{"id":"ct-084","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, an ice cream truck with its stop arm out is in the opposite lanes, across a raised safety island. Must you stop?","o":["Yes, at least 10 feet away","Yes, until the truck leaves","Yes, but only if children are near","No, the barrier means you need not stop"],"h1":"A physical divider changes the rule.","h2":"In Connecticut, you do not have to stop for an ice cream truck that is in another lane separated by a safety island or physical barrier.","p":"Right. With a barrier between you, you need not stop."},"es":{"q":"En Connecticut, un camión de helados con el brazo de alto extendido está en los carriles contrarios, al otro lado de una isla de seguridad elevada. ¿Debe parar?","o":["Sí, al menos a 10 pies","Sí, hasta que el camión se vaya","Sí, pero solo si hay niños cerca","No, por la barrera no tiene que parar"],"h1":"Una división física cambia la regla.","h2":"En Connecticut, usted no tiene que parar por un camión de helados que está en otro carril separado por una isla de seguridad o una barrera física.","p":"Correcto. Con una barrera de por medio, no tiene que parar."},"ref":{"doc":"CT","page":18}},{"id":"ct-085","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, what does the driver's manual say about a person under 21 who has had just one alcoholic drink?","o":["They are fine to drive after 10 minutes","They may drive if they eat food","They could be considered impaired","They may drive only in daylight"],"h1":"Connecticut is very strict with young drivers.","h2":"In Connecticut, a person under 21 could be considered impaired after only one alcoholic drink.","p":"Right. Even one drink could count as impaired for someone under 21."},"es":{"q":"En Connecticut, ¿qué dice el manual del conductor sobre una persona menor de 21 años que tomó solo una bebida alcohólica?","o":["Puede manejar bien después de 10 minutos","Puede manejar si come algo","Podría considerarse que está afectada","Puede manejar solo de día"],"h1":"Connecticut es muy estricto con los conductores jóvenes.","h2":"En Connecticut, una persona menor de 21 años podría considerarse afectada por el alcohol después de una sola bebida.","p":"Correcto. Incluso una bebida podría contar como estar afectado para un menor de 21 años."},"ref":{"doc":"CT","page":33}},{"id":"ct-086","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a 19-year-old tests at 0.03 percent after a DUI arrest. To get the license back, for at least how long must an ignition interlock device be used?","o":["Six months","One year","Two weeks","One month"],"h1":"It is longer than for adult drivers.","h2":"In Connecticut, a driver under 21 who tests at 0.02 percent or higher must use an ignition interlock device for at least one year to get the license back.","p":"Right. At least one year with an ignition interlock device."},"es":{"q":"En Connecticut, una persona de 19 años marca 0.03 por ciento en la prueba después de un arresto por manejar ebria. Para recuperar la licencia, ¿por cuánto tiempo como mínimo debe usar un dispositivo de bloqueo de encendido?","o":["Seis meses","Un año","Dos semanas","Un mes"],"h1":"Es más tiempo que para los conductores adultos.","h2":"En Connecticut, un conductor menor de 21 años que marca 0.02 por ciento o más debe usar un dispositivo de bloqueo de encendido por al menos un año para recuperar la licencia.","p":"Correcto. Al menos un año con el dispositivo de bloqueo de encendido."},"ref":{"doc":"CT","page":33}},{"id":"ct-087","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 17-year-old is charged with driving under the influence. Can the teen be treated as a youthful offender?","o":["No, DUI is excluded","Yes, anyone under 18 can be","Yes, if it is a first offense","Yes, if no one was hurt"],"h1":"Some serious offenses are never treated as youthful offenses.","h2":"In Connecticut, a person under 18 who drives under the influence of alcohol or drugs cannot be treated as a youthful offender.","p":"Right. DUI is excluded from youthful offender status."},"es":{"q":"En Connecticut, un joven de 17 años es acusado de manejar bajo la influencia del alcohol o drogas. ¿Puede tratarse como delincuente juvenil (youthful offender)?","o":["No, manejar ebrio está excluido","Sí, cualquier menor de 18 años puede","Sí, si es la primera falta","Sí, si nadie resultó herido"],"h1":"Algunas faltas graves nunca se tratan como faltas juveniles.","h2":"En Connecticut, una persona menor de 18 años que maneja bajo la influencia del alcohol o drogas no puede tratarse como delincuente juvenil.","p":"Correcto. Manejar ebrio está excluido de la condición de delincuente juvenil."},"ref":{"doc":"CT","page":35}},{"id":"ct-088","scope":"CT","cat":"signals","sign":null,"c":3,"en":{"q":"In Connecticut, what flashing lights does a police car use to signal you to stop?","o":["Green and white lights","Amber and yellow lights","Only white lights","Blue, or blue and red, lights"],"h1":"Think of the colors used by police here.","h2":"In Connecticut, police signal drivers to stop with flashing blue lights, flashing blue and red lights, or a siren.","p":"Right. Police use blue, or blue and red, lights."},"es":{"q":"En Connecticut, ¿qué luces intermitentes usa una patrulla de policía para indicarle que se detenga?","o":["Luces verdes y blancas","Luces ámbar y amarillas","Solo luces blancas","Luces azules, o azules y rojas"],"h1":"Piense en los colores que usa la policía aquí.","h2":"En Connecticut, la policía indica a los conductores que se detengan con luces azules intermitentes, luces azules y rojas intermitentes, o una sirena.","p":"Correcto. La policía usa luces azules, o azules y rojas."},"ref":{"doc":"CT","page":35}},{"id":"ct-089","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, you finished the operator retraining program. What happens if you get another moving violation within three years?","o":["Nothing extra happens","You must retake the program only","Your license is suspended for at least 30 days","You pay a $10 fine only"],"h1":"The penalty is now more serious than a class.","h2":"In Connecticut, a new moving violation within three years after completing operator retraining brings a license suspension of at least 30 days.","p":"Right. That means a suspension of at least 30 days."},"es":{"q":"En Connecticut, usted terminó el programa de reentrenamiento de conductores. ¿Qué pasa si comete otra infracción en movimiento dentro de tres años?","o":["No pasa nada más","Solo debe repetir el programa","Le suspenden la licencia por al menos 30 días","Solo paga una multa de $10"],"h1":"Ahora el castigo es más serio que una clase.","h2":"En Connecticut, una nueva infracción en movimiento dentro de los tres años después de terminar el reentrenamiento trae una suspensión de la licencia de al menos 30 días.","p":"Correcto. Eso significa una suspensión de al menos 30 días."},"ref":{"doc":"CT","page":35}},{"id":"ct-091","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, when must you report a crash to the police?","o":["If there is injury, death or property damage","Only when someone is killed","Only when a car must be towed","Only when damage is over $5,000"],"h1":"Even damage alone counts.","h2":"In Connecticut, you must report a crash to the police if anyone is injured or killed or there is property damage.","p":"Right. Report any crash with injury, death or property damage."},"es":{"q":"En Connecticut, ¿cuándo debe reportar un choque a la policía?","o":["Si hay heridos, muertos o daños a la propiedad","Solo cuando alguien muere","Solo cuando hay que remolcar un auto","Solo cuando el daño pasa de $5,000"],"h1":"Incluso los daños solos cuentan.","h2":"En Connecticut, usted debe reportar un choque a la policía si alguien resulta herido o muerto, o si hay daños a la propiedad.","p":"Correcto. Reporte todo choque con heridos, muertos o daños a la propiedad."},"ref":{"doc":"CT","page":41}},{"id":"ct-092","scope":"CT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Connecticut, what is the highest speed limit the state may set on a multi-lane, limited-access highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 10 mph more than the usual top limit on other roads.","h2":"In Connecticut, the speed limit on a multi-lane, limited-access highway may not be set higher than 65 mph.","p":"Right. 65 mph is the highest limit the state may set there."},"es":{"q":"En Connecticut, ¿cuál es el límite de velocidad más alto que el estado puede fijar en una autopista de acceso limitado con varios carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Son 10 mph más que el límite máximo normal en otras vías.","h2":"En Connecticut, el límite de velocidad en una autopista de acceso limitado con varios carriles no puede ser mayor de 65 mph.","p":"Correcto. 65 mph es el límite más alto que el estado puede fijar allí."},"ref":{"doc":"CT","page":null}},{"id":"ct-093","scope":"CT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Connecticut, what is the lowest speed allowed on a limited-access divided highway, unless going slower is needed for safety?","o":["40 mph","30 mph","45 mph","50 mph"],"h1":"It is well below the usual highway limit.","h2":"In Connecticut, you may not drive slower than 40 mph on a limited-access divided highway unless a slower speed is needed for safety, an emergency or an officer's order.","p":"Right. The minimum is 40 mph unless safety requires less."},"es":{"q":"En Connecticut, ¿cuál es la velocidad mínima permitida en una autopista dividida de acceso limitado, a menos que ir más despacio sea necesario por seguridad?","o":["40 mph","30 mph","45 mph","50 mph"],"h1":"Es bastante menor que el límite normal de la autopista.","h2":"En Connecticut, no se puede manejar a menos de 40 mph en una autopista dividida de acceso limitado, a menos que una velocidad menor sea necesaria por seguridad, una emergencia o la orden de un agente.","p":"Correcto. La mínima es 40 mph, salvo que la seguridad exija menos."},"ref":{"doc":"CT","page":null}},{"id":"ct-094","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, driving faster than what speed counts as reckless driving under state law?","o":["70 mph","75 mph","80 mph","85 mph"],"h1":"It is 20 mph above the highest posted limit in the state.","h2":"In Connecticut, driving more than 85 mph is reckless driving under state law, not just speeding.","p":"Right. Over 85 mph is reckless driving."},"es":{"q":"En Connecticut, según la ley estatal, ¿a partir de qué velocidad se considera manejo imprudente?","o":["70 mph","75 mph","80 mph","85 mph"],"h1":"Son 20 mph más que el límite más alto del estado.","h2":"En Connecticut, manejar a más de 85 mph es manejo imprudente según la ley estatal, no solo exceso de velocidad.","p":"Correcto. Más de 85 mph es manejo imprudente."},"ref":{"doc":"CT","page":null}},{"id":"ct-095","scope":"CT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Connecticut, what happens to a speeding fine in a marked school zone?","o":["It stays the same","It is doubled","It is cut in half","It becomes a warning"],"h1":"Look for the sign that says SCHOOL ZONE AHEAD.","h2":"In Connecticut, speeding in a marked school zone doubles the fine, and signs at the start of the zone say so.","p":"Right. Speeding fines are doubled in a school zone."},"es":{"q":"En Connecticut, ¿qué pasa con la multa por exceso de velocidad en una zona escolar señalizada?","o":["Sigue igual","Se duplica","Se reduce a la mitad","Se convierte en advertencia"],"h1":"Fíjese en el letrero que dice SCHOOL ZONE AHEAD.","h2":"En Connecticut, el exceso de velocidad en una zona escolar señalizada duplica la multa, y los letreros al inicio de la zona lo indican.","p":"Correcto. Las multas por velocidad se duplican en una zona escolar."},"ref":{"doc":"CT","page":null}},{"id":"ct-096","scope":"CT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Connecticut, since October 1, 2026, when may a car use the far-left lane of a limited-access highway with three or more lanes in your direction?","o":["To pass, for a left exit, or in heavy traffic","At any time, if you drive at the limit","Only at night, when traffic is light","Only when two or more people are inside"],"h1":"Think of the far-left lane as the passing lane.","h2":"In Connecticut, since October 1, 2026, on a limited-access highway with three or more lanes your way, cars may use the far-left lane only to pass, to reach a left exit or entrance, or when traffic makes it necessary.","p":"Right. The far-left lane is for passing, left exits and heavy traffic."},"es":{"q":"En Connecticut, desde el 1 de octubre de 2026, ¿cuándo puede un auto usar el carril del extremo izquierdo de una autopista de acceso limitado con tres o más carriles en su dirección?","o":["Para rebasar, para una salida a la izquierda o con mucho tráfico","En cualquier momento, si va al límite","Solo de noche, con poco tráfico","Solo si van dos o más personas"],"h1":"Piense en el carril del extremo izquierdo como el carril para rebasar.","h2":"En Connecticut, desde el 1 de octubre de 2026, en una autopista de acceso limitado con tres o más carriles en su dirección, los autos pueden usar el carril del extremo izquierdo solo para rebasar, para llegar a una salida o entrada a la izquierda, o cuando el tráfico lo hace necesario.","p":"Correcto. El carril del extremo izquierdo es para rebasar, salidas a la izquierda y tráfico pesado."},"ref":{"doc":"CT","page":null}},{"id":"ct-097","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, at least how far before a turn must you start to signal?","o":["25 feet","50 feet","100 feet","300 feet"],"h1":"It is about the length of a few houses.","h2":"In Connecticut, you must signal without stopping for at least the last 100 feet before you turn.","p":"Right. Signal for at least the last 100 feet."},"es":{"q":"En Connecticut, ¿al menos a qué distancia antes de dar vuelta debe empezar a poner la direccional?","o":["25 pies","50 pies","100 pies","300 pies"],"h1":"Es más o menos el frente de unas cuantas casas.","h2":"En Connecticut, debe poner la direccional sin parar durante al menos los últimos 100 pies antes de dar vuelta.","p":"Correcto. Ponga la direccional al menos en los últimos 100 pies."},"ref":{"doc":"CT","page":null}},{"id":"ct-098","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, you must turn on your headlights when you cannot clearly see people and vehicles how far ahead?","o":["200 feet","500 feet","1,000 feet","1 mile"],"h1":"It is a bit less than the length of two football fields.","h2":"In Connecticut, you must turn on your lights whenever poor light or bad weather keeps you from clearly seeing people and vehicles 500 feet ahead.","p":"Right. Lights go on when you cannot see clearly 500 feet ahead."},"es":{"q":"En Connecticut, debe encender los faros si no ve con claridad a personas y vehículos a cierta distancia adelante. ¿Cuál es esa distancia?","o":["200 pies","500 pies","1,000 pies","1 milla"],"h1":"Es un poco menos que el largo de dos campos de fútbol americano.","h2":"En Connecticut, debe encender las luces cuando la poca luz o el mal tiempo no le dejan ver con claridad a personas y vehículos a 500 pies adelante.","p":"Correcto. Las luces se encienden si no ve bien a 500 pies."},"ref":{"doc":"CT","page":null}},{"id":"ct-099","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, a fire truck is going to a fire alarm. What is the closest you may follow it?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is much farther than for an ambulance.","h2":"In Connecticut, unless you are on official business for the emergency, you may not follow a fire truck going to a fire alarm closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on an alarm."},"es":{"q":"En Connecticut, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca como máximo puede seguirlo?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es mucho más lejos que para una ambulancia.","h2":"En Connecticut, a menos que esté en servicio oficial para la emergencia, no puede seguir a un camión de bomberos que va a una alarma a menos de 500 pies.","p":"Correcto. Quédese al menos a 500 pies detrás de un camión de bomberos."},"ref":{"doc":"CT","page":null}},{"id":"ct-100","scope":"CT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Connecticut, what is the closest you may follow an ambulance that is using its flashing lights or siren?","o":["100 feet","20 feet","50 feet","75 feet"],"h1":"It is about the length of seven cars.","h2":"In Connecticut, you may not follow an ambulance that is using flashing lights or a siren more closely than 100 feet.","p":"Right. Stay at least 100 feet behind the ambulance."},"es":{"q":"En Connecticut, ¿qué tan cerca como máximo puede seguir a una ambulancia que usa sus luces intermitentes o sirena?","o":["100 pies","20 pies","50 pies","75 pies"],"h1":"Es más o menos el largo de siete autos.","h2":"En Connecticut, no puede seguir a una ambulancia que usa luces intermitentes o sirena a menos de 100 pies.","p":"Correcto. Quédese al menos a 100 pies detrás de la ambulancia."},"ref":{"doc":"CT","page":null}},{"id":"ct-101","scope":"CT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Connecticut, a school bus ahead has its red lights flashing. What is the minimum distance from the bus at which you must stop?","o":["5 feet","3 feet","10 feet","1 foot"],"h1":"It is the same distance as for an ice cream truck with its stop arm out.","h2":"In Connecticut, you must stop at least 10 feet from the front or the back of a school bus with flashing red lights.","p":"Right. Stop at least 10 feet away from the bus."},"es":{"q":"En Connecticut, un autobús escolar adelante tiene sus luces rojas intermitentes. ¿A qué distancia mínima del autobús debe detenerse?","o":["5 pies","3 pies","10 pies","1 pie"],"h1":"Es la misma distancia que para un camión de helados con su brazo de alto extendido.","h2":"En Connecticut, debe detenerse al menos a 10 pies del frente o de la parte de atrás de un autobús escolar con luces rojas intermitentes.","p":"Correcto. Deténgase al menos a 10 pies del autobús."},"ref":{"doc":"CT","page":null}},{"id":"ct-102","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, what is the fine for a first offense of passing a school bus that has its red lights flashing?","o":["$100","$450","$250","$50"],"h1":"It is close to five hundred dollars.","h2":"In Connecticut, the fine for a first offense of not stopping for a school bus with flashing red lights is $450, and later offenses cost more.","p":"Right. The first offense costs $450."},"es":{"q":"En Connecticut, ¿cuál es la multa por la primera vez que se rebasa un autobús escolar con sus luces rojas intermitentes?","o":["$100","$450","$250","$50"],"h1":"Se acerca a quinientos dólares.","h2":"En Connecticut, la multa por la primera vez que no se detiene ante un autobús escolar con luces rojas intermitentes es de $450, y las siguientes cuestan más.","p":"Correcto. La primera infracción cuesta $450."},"ref":{"doc":"CT","page":null}},{"id":"ct-103","scope":"CT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Connecticut, at an intersection, a school bus on the cross street has its red lights flashing while children get on. May you turn toward the bus?","o":["Yes, if you turn slowly","Yes, if no children are in the road","Yes, if the bus driver waves you on","No, turning toward the bus is not allowed"],"h1":"Children may cross in front of the bus.","h2":"In Connecticut, at an intersection you may not turn toward a school bus that is picking up or dropping off passengers.","p":"Right. Do not turn toward a school bus that is loading or unloading."},"es":{"q":"En Connecticut, en una intersección, un autobús escolar en la calle transversal tiene las luces rojas intermitentes mientras suben niños. ¿Puede dar vuelta hacia el autobús?","o":["Sí, si da vuelta despacio","Sí, si no hay niños en la calle","Sí, si el chofer le hace señas","No, no se permite dar vuelta hacia el autobús"],"h1":"Los niños pueden cruzar frente al autobús.","h2":"En Connecticut, en una intersección no se puede dar vuelta hacia un autobús escolar que está subiendo o bajando pasajeros.","p":"Correcto. No dé vuelta hacia un autobús escolar que sube o baja pasajeros."},"ref":{"doc":"CT","page":null}},{"id":"ct-104","scope":"CT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Connecticut, how high can the fine be for a driver who does not yield to a pedestrian at a crosswalk?","o":["Up to $750","Up to $90","Up to $150","Up to $5,000"],"h1":"It is several hundred dollars.","h2":"In Connecticut, a driver who breaks the crosswalk rules, such as not yielding to a pedestrian, can be fined up to $750.","p":"Right. The fine can be as high as $750."},"es":{"q":"En Connecticut, ¿de cuánto puede ser la multa para un conductor que no le cede el paso a un peatón en un cruce peatonal?","o":["Hasta $750","Hasta $90","Hasta $150","Hasta $5,000"],"h1":"Son varios cientos de dólares.","h2":"En Connecticut, un conductor que no cumple las reglas del cruce peatonal, como no cederle el paso a un peatón, puede recibir una multa de hasta $750.","p":"Correcto. La multa puede llegar a $750."},"ref":{"doc":"CT","page":null}},{"id":"ct-105","scope":"CT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Connecticut, a driver who is not careful seriously injures a bicyclist who was riding safely. How high can the fine be under the vulnerable user law?","o":["Up to $100","Up to $250","Up to $1,000","Up to $10,000"],"h1":"It is in the thousands, but not ten thousand.","h2":"In Connecticut, a driver who fails to use reasonable care and seriously hurts or kills a vulnerable user, such as a careful bicyclist, can be fined up to $1,000.","p":"Right. The fine can be up to $1,000."},"es":{"q":"En Connecticut, un conductor descuidado hiere gravemente a un ciclista que iba con cuidado. ¿De cuánto puede ser la multa según la ley de usuarios vulnerables?","o":["Hasta $100","Hasta $250","Hasta $1,000","Hasta $10,000"],"h1":"Llega a los miles, pero no a diez mil.","h2":"En Connecticut, un conductor que no tiene el cuidado debido y hiere gravemente o mata a un usuario vulnerable, como un ciclista cuidadoso, puede recibir una multa de hasta $1,000.","p":"Correcto. La multa puede ser de hasta $1,000."},"ref":{"doc":"CT","page":null}},{"id":"ct-106","scope":"CT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Connecticut, you are parked and open your door into a bicyclist who is riding past. What does state law say?","o":["The bicyclist is always at fault","Opening a door into moving traffic is a violation","It is legal because your car is parked","It is only wrong if your engine is on"],"h1":"Look before you open the door.","h2":"In Connecticut, opening a car door so that it hits moving traffic, including a bicyclist, is a traffic violation.","p":"Right. You may not open a door into moving traffic."},"es":{"q":"En Connecticut, usted está estacionado y abre la puerta contra un ciclista que pasa. ¿Qué dice la ley estatal?","o":["El ciclista siempre tiene la culpa","Abrir una puerta contra el tráfico en movimiento es una infracción","Es legal porque su auto está estacionado","Solo está mal si el motor está encendido"],"h1":"Mire antes de abrir la puerta.","h2":"En Connecticut, abrir la puerta del auto de modo que golpee al tráfico en movimiento, incluido un ciclista, es una infracción de tránsito.","p":"Correcto. No puede abrir la puerta contra el tráfico en movimiento."},"ref":{"doc":"CT","page":null}},{"id":"ct-107","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, you drive with a thick layer of snow on your car's roof that could fly off. What is the fine?","o":["$10","$500","$1,500","$75"],"h1":"It is less than one hundred dollars if no one is hurt.","h2":"In Connecticut, you must clear ice and snow from your car, including the roof, hood and trunk, and the fine is $75 if it could endanger people or property.","p":"Right. The fine is $75."},"es":{"q":"En Connecticut, usted maneja con una capa gruesa de nieve en el techo del auto que podría salir volando. ¿Cuál es la multa?","o":["$10","$500","$1,500","$75"],"h1":"Es menos de cien dólares si nadie sale herido.","h2":"En Connecticut, debe quitar el hielo y la nieve del auto, incluido el techo, el cofre y la cajuela, y la multa es de $75 si puede poner en peligro a personas o bienes.","p":"Correcto. La multa es de $75."},"ref":{"doc":"CT","page":null}},{"id":"ct-108","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, a 12-year-old wants to ride in the open bed of a pickup truck on a public road. What does the law require?","o":["The child must wear a fastened seat belt","Nothing, if you drive under 25 mph","Nothing, if an adult rides with the child","Nothing, on roads outside of towns"],"h1":"The same safety device used inside the car is needed.","h2":"In Connecticut, a child under 16 may ride in the open bed of a pickup truck on a public road only while wearing a properly fastened seat belt, except in some parades, farm work and hayrides.","p":"Right. The child must wear a fastened seat belt."},"es":{"q":"En Connecticut, un niño de 12 años quiere ir en la caja abierta de una camioneta pickup en una vía pública. ¿Qué exige la ley?","o":["El niño debe llevar un cinturón de seguridad abrochado","Nada, si maneja a menos de 25 mph","Nada, si un adulto va con el niño","Nada, en caminos fuera de los pueblos"],"h1":"Se necesita el mismo dispositivo de seguridad que dentro del auto.","h2":"En Connecticut, un menor de 16 años puede ir en la caja abierta de una pickup en una vía pública solo si lleva un cinturón de seguridad bien abrochado, salvo en algunos desfiles, trabajos de granja y paseos en carreta.","p":"Correcto. El niño debe llevar el cinturón abrochado."},"ref":{"doc":"CT","page":null}},{"id":"ct-109","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, which papers must be in the car whenever it is driven on a public road?","o":["The car's title and bill of sale","The owner's birth certificate","The registration and the insurance ID card","The last repair receipt"],"h1":"One shows the car is registered, the other shows it is insured.","h2":"In Connecticut, the registration certificate and the insurance identification card must be in the car whenever it is driven, and the fine for not having them is $50.","p":"Right. Keep the registration and insurance card in the car."},"es":{"q":"En Connecticut, ¿qué documentos deben estar en el auto siempre que se maneja en una vía pública?","o":["El título del auto y la factura de compra","El acta de nacimiento del dueño","El registro y la tarjeta de seguro","El último recibo de reparación"],"h1":"Uno muestra que el auto está registrado y el otro que está asegurado.","h2":"En Connecticut, el certificado de registro y la tarjeta de identificación del seguro deben estar en el auto siempre que se maneja, y la multa por no tenerlos es de $50.","p":"Correcto. Mantenga el registro y la tarjeta de seguro en el auto."},"ref":{"doc":"CT","page":null}},{"id":"ct-110","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 10 days","Within 48 hours","Within 30 days","Within 6 months"],"h1":"It is very soon, counted in hours.","h2":"In Connecticut, a license holder must tell the DMV about a change of address within 48 hours, giving both the old and new address.","p":"Right. Report a new address within 48 hours."},"es":{"q":"En Connecticut, usted se muda a una casa nueva. ¿En cuánto tiempo debe informar al DMV su nueva dirección?","o":["En 10 días","En 48 horas","En 30 días","En 6 meses"],"h1":"Es muy pronto y se cuenta en horas.","h2":"En Connecticut, quien tiene licencia debe avisar al DMV del cambio de dirección en 48 horas, dando la dirección anterior y la nueva.","p":"Correcto. Informe la nueva dirección en 48 horas."},"ref":{"doc":"CT","page":null}},{"id":"ct-111","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, what are the minimum liability insurance amounts for a car?","o":["$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"The middle number is twice the first.","h2":"In Connecticut, liability insurance must cover at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The minimum is $25,000 / $50,000 / $25,000."},"es":{"q":"En Connecticut, ¿cuáles son los montos mínimos del seguro de responsabilidad civil para un auto?","o":["$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"El número del medio es el doble del primero.","h2":"En Connecticut, el seguro de responsabilidad civil debe cubrir al menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo es $25,000 / $50,000 / $25,000."},"ref":{"doc":"CT","page":null}},{"id":"ct-112","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what renewal option is open to drivers aged 65 or older?","o":["A shorter, two-year license","A free lifetime license","A license with no photo","A license with no vision rule"],"h1":"It is about how long the license lasts.","h2":"In Connecticut, a driver aged 65 or older may choose to renew the license for just two years instead of the usual longer period.","p":"Right. Drivers 65 and older may renew for two years."},"es":{"q":"En Connecticut, ¿qué opción de renovación tienen los conductores de 65 años o más?","o":["Una licencia más corta, de dos años","Una licencia gratis de por vida","Una licencia sin foto","Una licencia sin requisito de visión"],"h1":"Tiene que ver con cuánto dura la licencia.","h2":"En Connecticut, un conductor de 65 años o más puede renovar la licencia por solo dos años en lugar del periodo normal, que es más largo.","p":"Correcto. Los mayores de 65 pueden renovar por dos años."},"ref":{"doc":"CT","page":null}},{"id":"ct-113","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, you renew your driver's license after it has already expired. What extra fee do you pay?","o":["$5","$100","$25","$250"],"h1":"It is a small late fee.","h2":"In Connecticut, renewing a license after it has expired adds a $25 late fee.","p":"Right. The late fee is $25."},"es":{"q":"En Connecticut, usted renueva su licencia de conducir cuando ya venció. ¿Qué cargo extra paga?","o":["$5","$100","$25","$250"],"h1":"Es un cargo pequeño por atraso.","h2":"En Connecticut, renovar una licencia vencida tiene un cargo adicional de $25 por atraso.","p":"Correcto. El cargo por atraso es de $25."},"ref":{"doc":"CT","page":null}},{"id":"ct-114","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, how early may you renew your driver's license before it expires?","o":["Up to 30 days before","Up to 180 days before","Up to 1 year before","Up to 2 years before"],"h1":"It is about six months.","h2":"In Connecticut, you may renew your driver's license on its expiration date or as early as 180 days before.","p":"Right. You may renew up to 180 days early."},"es":{"q":"En Connecticut, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 30 días antes","Hasta 180 días antes","Hasta 1 año antes","Hasta 2 años antes"],"h1":"Son unos seis meses.","h2":"En Connecticut, puede renovar su licencia el día en que vence o hasta 180 días antes.","p":"Correcto. Puede renovar hasta 180 días antes."},"ref":{"doc":"CT","page":null}},{"id":"ct-115","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, a 17-year-old is convicted of driving without a license. What happens to the right to get a license?","o":["It is delayed for 30 days","It is delayed for 90 days","It is delayed for 6 months","It is suspended for at least 1 year"],"h1":"It is a long time for a teen.","h2":"In Connecticut, a person under 18 convicted of driving without a license cannot get a license, or has it suspended, for at least one year.","p":"Right. The suspension lasts at least one year."},"es":{"q":"En Connecticut, un joven de 17 años es condenado por manejar sin licencia. ¿Qué pasa con su derecho a obtener una licencia?","o":["Se retrasa 30 días","Se retrasa 90 días","Se retrasa 6 meses","Se suspende por al menos 1 año"],"h1":"Es mucho tiempo para un adolescente.","h2":"En Connecticut, una persona menor de 18 años condenada por manejar sin licencia no puede obtenerla, o se le suspende, por al menos un año.","p":"Correcto. La suspensión dura al menos un año."},"ref":{"doc":"CT","page":null}},{"id":"ct-116","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, a 19-year-old is convicted of having alcohol on a street or highway. What happens to the license?","o":["It is suspended for 60 days","It is suspended for 10 days","It is suspended for 5 years","Nothing; only a fine is given"],"h1":"It is about two months.","h2":"In Connecticut, a person under 21 convicted of having alcohol on a street or highway gets a 60-day license suspension.","p":"Right. The license is suspended for 60 days."},"es":{"q":"En Connecticut, un joven de 19 años es condenado por tener alcohol en una calle o carretera. ¿Qué pasa con su licencia?","o":["Se suspende por 60 días","Se suspende por 10 días","Se suspende por 5 años","Nada; solo recibe una multa"],"h1":"Son unos dos meses.","h2":"En Connecticut, una persona menor de 21 años condenada por tener alcohol en una calle o carretera recibe una suspensión de licencia de 60 días.","p":"Correcto. La licencia se suspende por 60 días."},"ref":{"doc":"CT","page":null}},{"id":"ct-117","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, what is the fine for a first conviction of driving under the influence?","o":["$100 to $250","$200 to $400","$500 to $1,000","$5,000 to $10,000"],"h1":"It starts at five hundred dollars.","h2":"In Connecticut, a first conviction for driving under the influence brings a fine of $500 to $1,000, plus other penalties.","p":"Right. The fine is $500 to $1,000."},"es":{"q":"En Connecticut, ¿cuál es la multa por una primera condena por manejar bajo la influencia?","o":["De $100 a $250","De $200 a $400","De $500 a $1,000","De $5,000 a $10,000"],"h1":"Empieza en quinientos dólares.","h2":"En Connecticut, una primera condena por manejar bajo la influencia trae una multa de $500 a $1,000, además de otras sanciones.","p":"Correcto. La multa es de $500 a $1,000."},"ref":{"doc":"CT","page":null}},{"id":"ct-118","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, a driver gets a second DUI conviction within 10 years. After the license is restored, for how long must an ignition interlock device be used?","o":["6 months","3 years","10 years","30 days"],"h1":"It is longer than for a first conviction.","h2":"In Connecticut, after a second DUI conviction within 10 years, the driver must use an ignition interlock device for three years after the license is restored.","p":"Right. The device is required for three years."},"es":{"q":"En Connecticut, un conductor recibe una segunda condena por DUI en 10 años. Después de recuperar la licencia, ¿por cuánto tiempo debe usar un dispositivo de bloqueo de encendido?","o":["6 meses","3 años","10 años","30 días"],"h1":"Es más tiempo que en una primera condena.","h2":"En Connecticut, después de una segunda condena por DUI en 10 años, el conductor debe usar un dispositivo de bloqueo de encendido por tres años después de recuperar la licencia.","p":"Correcto. El dispositivo se exige por tres años."},"ref":{"doc":"CT","page":null}},{"id":"ct-119","scope":"CT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Connecticut, what happens to the license after a third DUI conviction within 10 years?","o":["It is suspended for 45 days","It is suspended for 6 months","It is suspended for 1 year","It is permanently revoked"],"h1":"This is the most serious result.","h2":"In Connecticut, a third DUI conviction within 10 years means the driver's license is permanently revoked.","p":"Right. The license is permanently revoked."},"es":{"q":"En Connecticut, ¿qué pasa con la licencia después de una tercera condena por DUI en 10 años?","o":["Se suspende por 45 días","Se suspende por 6 meses","Se suspende por 1 año","Se revoca de forma permanente"],"h1":"Es el resultado más grave.","h2":"En Connecticut, una tercera condena por DUI en 10 años significa que la licencia se revoca de forma permanente.","p":"Correcto. La licencia se revoca de forma permanente."},"ref":{"doc":"CT","page":null}},{"id":"ct-120","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, who must wear a helmet when riding on a motorcycle?","o":["Riders and passengers under 21","Riders and passengers under 16","Only riders who have a learner's permit","Only passengers, not riders"],"h1":"The age limit was raised in 2025.","h2":"In Connecticut, motorcycle riders and passengers under 21 must wear an approved helmet; before the 2025 change the age was under 18.","p":"Right. Everyone under 21 on a motorcycle needs a helmet."},"es":{"q":"En Connecticut, ¿quién debe usar casco al ir en motocicleta?","o":["Conductores y pasajeros menores de 21 años","Conductores y pasajeros menores de 16 años","Solo los conductores con permiso de aprendiz","Solo los pasajeros, no los conductores"],"h1":"La edad límite subió en 2025.","h2":"En Connecticut, los conductores y pasajeros de motocicleta menores de 21 años deben usar un casco aprobado; antes del cambio de 2025 la edad era menos de 18.","p":"Correcto. Todos los menores de 21 en motocicleta necesitan casco."},"ref":{"doc":"CT","page":null}},{"id":"ct-121","scope":"CT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Connecticut, may a motorcyclist ride between two lanes of slow traffic?","o":["Yes, in slow traffic","Yes, below 30 mph","No, riding between lanes is not allowed","Yes, but only on highways"],"h1":"Two motorcycles may share a lane, but that is different.","h2":"In Connecticut, a motorcyclist may not ride between lanes of traffic or pass a car in the same lane.","p":"Right. Riding between lanes is not allowed."},"es":{"q":"En Connecticut, ¿puede un motociclista circular entre dos carriles de tráfico lento?","o":["Sí, con tráfico lento","Sí, a menos de 30 mph","No, no se permite circular entre carriles","Sí, pero solo en autopistas"],"h1":"Dos motocicletas pueden compartir un carril, pero eso es diferente.","h2":"En Connecticut, un motociclista no puede circular entre carriles de tráfico ni rebasar a un auto dentro del mismo carril.","p":"Correcto. No se permite circular entre carriles."},"ref":{"doc":"CT","page":null}},{"id":"ct-122","scope":"CT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Connecticut, when must the headlight of a modern motorcycle be on?","o":["Only at night","At all times while riding","Only in rain or fog","Only on highways"],"h1":"It helps other drivers see the motorcycle.","h2":"In Connecticut, a motorcycle made after January 1, 1980 must have its headlight on at all times while it is ridden on a highway.","p":"Right. The headlight is on at all times."},"es":{"q":"En Connecticut, ¿cuándo debe estar encendido el faro de una motocicleta moderna?","o":["Solo de noche","Siempre que se maneja","Solo con lluvia o niebla","Solo en autopistas"],"h1":"Ayuda a que otros conductores vean la motocicleta.","h2":"En Connecticut, una motocicleta fabricada después del 1 de enero de 1980 debe llevar el faro encendido siempre que se maneja en una vía.","p":"Correcto. El faro va encendido siempre."},"ref":{"doc":"CT","page":null}},{"id":"ct-123","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, a 30-year-old just got a motorcycle endorsement. How long must they wait before carrying a passenger?","o":["1 week","1 month","1 year","3 months"],"h1":"Teens wait six months; adults wait half as long.","h2":"In Connecticut, a rider who has held a motorcycle endorsement for less than three months may not carry a passenger; riders aged 16 or 17 must wait six months.","p":"Right. Adults wait three months before carrying a passenger."},"es":{"q":"En Connecticut, una persona de 30 años acaba de obtener el permiso de motocicleta en su licencia. ¿Cuánto debe esperar antes de llevar un pasajero?","o":["1 semana","1 mes","1 año","3 meses"],"h1":"Los adolescentes esperan seis meses; los adultos, la mitad.","h2":"En Connecticut, quien tiene el permiso de motocicleta desde hace menos de tres meses no puede llevar pasajero; los de 16 o 17 años deben esperar seis meses.","p":"Correcto. Los adultos esperan tres meses antes de llevar pasajero."},"ref":{"doc":"CT","page":null}},{"id":"ct-124","scope":"CT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Connecticut, a driver gets a first ticket for not using the right car seat for a child. What does the DMV require?","o":["Take a child car seat safety course","Retake the road test","Do 40 more hours of practice","Get a new learner's permit"],"h1":"The goal is to learn how to use car seats correctly.","h2":"In Connecticut, a driver with a first or second child restraint violation must attend a child car seat safety course offered or approved by the DMV.","p":"Right. The driver must take a car seat safety course."},"es":{"q":"En Connecticut, un conductor recibe su primera multa por no usar el asiento correcto para un niño. ¿Qué exige el DMV?","o":["Tomar un curso de seguridad de asientos infantiles","Repetir el examen de manejo","Hacer 40 horas más de práctica","Sacar un nuevo permiso de aprendiz"],"h1":"La idea es aprender a usar bien los asientos infantiles.","h2":"En Connecticut, un conductor con una primera o segunda infracción de asiento infantil debe tomar un curso de seguridad de asientos infantiles ofrecido o aprobado por el DMV.","p":"Correcto. El conductor debe tomar un curso de asientos infantiles."},"ref":{"doc":"CT","page":null}},{"id":"ct-125","scope":"CT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Connecticut, may police stop a car only because a 20-year-old in the back seat is not wearing a seat belt?","o":["Yes, at any time","Yes, but only at night","No, that alone is not a reason to stop","Yes, but only on highways"],"h1":"The belt is still required, but the stop rule is different.","h2":"In Connecticut, police may not stop a car only because a back-seat passenger aged 16 or older is not belted, although the belt is still required.","p":"Right. That alone is not a reason for a stop."},"es":{"q":"En Connecticut, ¿puede la policía detener un auto solo porque un pasajero de 20 años en el asiento trasero no lleva cinturón?","o":["Sí, en cualquier momento","Sí, pero solo de noche","No, eso solo no es motivo para detenerlo","Sí, pero solo en autopistas"],"h1":"El cinturón sigue siendo obligatorio, pero la regla para detener es distinta.","h2":"En Connecticut, la policía no puede detener un auto solo porque un pasajero de 16 años o más en el asiento trasero no lleva cinturón, aunque el cinturón sigue siendo obligatorio.","p":"Correcto. Eso solo no es motivo para detener el auto."},"ref":{"doc":"CT","page":null}},{"id":"ct-126","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, you fail your road test. How long must you wait before you can take it again?","o":["1 day","At least 14 days","At least 6 months","At least 90 days"],"h1":"It is about two weeks.","h2":"In Connecticut, if you fail the road test you must wait at least 14 days and pay the $40 testing fee again before retesting.","p":"Right. Wait at least 14 days."},"es":{"q":"En Connecticut, usted reprueba el examen de manejo. ¿Cuánto debe esperar para volver a tomarlo?","o":["1 día","Al menos 14 días","Al menos 6 meses","Al menos 90 días"],"h1":"Son unas dos semanas.","h2":"En Connecticut, si reprueba el examen de manejo debe esperar al menos 14 días y pagar otra vez la tarifa de $40 antes de repetirlo.","p":"Correcto. Espere al menos 14 días."},"ref":{"doc":"CT","page":null}},{"id":"ct-127","scope":"CT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Connecticut, you fail the vision test at your learner's permit appointment. What happens next?","o":["You take the knowledge test anyway","You get a permit for daytime only","You get the permit with no changes","You cannot take the knowledge test and must reschedule"],"h1":"The vision test comes first.","h2":"In Connecticut, if you fail the vision test you cannot go on to the knowledge test, and you must reschedule.","p":"Right. You must pass the vision test before the knowledge test."},"es":{"q":"En Connecticut, usted reprueba el examen de la vista en su cita para el permiso de aprendiz. ¿Qué pasa después?","o":["Toma el examen de conocimientos de todos modos","Recibe un permiso solo para el día","Recibe el permiso sin cambios","No puede tomar el examen de conocimientos y debe hacer otra cita"],"h1":"El examen de la vista va primero.","h2":"En Connecticut, si reprueba el examen de la vista no puede pasar al examen de conocimientos y debe hacer otra cita.","p":"Correcto. Debe aprobar la vista antes del examen de conocimientos."},"ref":{"doc":"CT","page":null}},{"id":"ct-128","scope":"CT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Connecticut, what must a new driver complete first, before getting a learner's permit?","o":["The Connecticut Work Zone Safety Course","A first aid and CPR class","The motorcycle safety course","A car repair class"],"h1":"It is about safety near road workers.","h2":"In Connecticut, the first step for a new driver is the free online Connecticut Work Zone Safety Course, completed before getting a learner's permit.","p":"Right. The Work Zone Safety Course comes first."},"es":{"q":"En Connecticut, ¿qué debe completar primero un conductor nuevo, antes de obtener el permiso de aprendiz?","o":["El curso de Seguridad en Zonas de Trabajo de Connecticut","Una clase de primeros auxilios y RCP","El curso de seguridad en motocicleta","Una clase de reparación de autos"],"h1":"Tiene que ver con la seguridad cerca de los trabajadores en la vía.","h2":"En Connecticut, el primer paso para un conductor nuevo es el curso gratuito en línea de Seguridad en Zonas de Trabajo de Connecticut, antes de obtener el permiso de aprendiz.","p":"Correcto. El curso de Zonas de Trabajo va primero."},"ref":{"doc":"CT","page":null}},{"id":"ct-129","scope":"CT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Connecticut, your driver's license has been expired for more than two years. What must you do to drive again?","o":["Pay a $25 late fee only","Take only a vision test","Get a permit and pass a road test","Mail in a renewal form"],"h1":"After two years, it is like being a new driver.","h2":"In Connecticut, if your license has been expired for two years or more, you must do all the testing again, including a learner's permit and a road test.","p":"Right. You start over with a permit and road test."},"es":{"q":"En Connecticut, su licencia de conducir lleva más de dos años vencida. ¿Qué debe hacer para volver a manejar?","o":["Pagar solo un cargo de $25 por atraso","Tomar solo un examen de la vista","Sacar un permiso y aprobar el examen de manejo","Enviar un formulario de renovación por correo"],"h1":"Después de dos años, es como ser un conductor nuevo.","h2":"En Connecticut, si su licencia lleva dos años o más vencida, debe hacer todos los exámenes otra vez, incluidos el permiso de aprendiz y el examen de manejo.","p":"Correcto. Empieza de nuevo con permiso y examen de manejo."},"ref":{"doc":"CT","page":null}},{"id":"ct-130","scope":"CT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Connecticut, a visitor has a valid license from another country and an International Driving Permit. For how long may they drive here?","o":["30 days","1 year","5 years","6 months"],"h1":"It is twelve months.","h2":"In Connecticut, a person with a valid license from another country and an International Driving Permit from that country may drive for one year.","p":"Right. They may drive for one year."},"es":{"q":"En Connecticut, un visitante tiene una licencia válida de otro país y un Permiso Internacional de Conducir. ¿Por cuánto tiempo puede manejar aquí?","o":["30 días","1 año","5 años","6 meses"],"h1":"Son doce meses.","h2":"En Connecticut, una persona con una licencia válida de otro país y un Permiso Internacional de Conducir de ese país puede manejar durante un año.","p":"Correcto. Puede manejar durante un año."},"ref":{"doc":"CT","page":null}},{"id":"ct-131","scope":"CT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Connecticut, unless a parking space is marked there, how close to an intersection may you not park?","o":["Within 10 feet","Within 15 feet","Within 20 feet","Within 30 feet"],"h1":"The distance was raised in 2025.","h2":"In Connecticut, since October 2025 you may not park within 30 feet of an intersection or the approach to a marked crosswalk, unless there is a marked parking space.","p":"Right. Do not park within 30 feet of an intersection."},"es":{"q":"En Connecticut, a menos que haya un espacio de estacionamiento marcado, ¿a qué distancia de una intersección no se puede estacionar?","o":["A menos de 10 pies","A menos de 15 pies","A menos de 20 pies","A menos de 30 pies"],"h1":"La distancia aumentó en 2025.","h2":"En Connecticut, desde octubre de 2025 no se puede estacionar a menos de 30 pies de una intersección o de la llegada a un cruce peatonal marcado, a menos que haya un espacio de estacionamiento marcado.","p":"Correcto. No se estacione a menos de 30 pies de una intersección."},"ref":{"doc":"CT","page":null}},{"id":"dc-001","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is the same age at which many teens get their first job.","h2":"In the District of Columbia, you must be at least 16 years old to get a learner permit.","p":"Right. In DC the learner permit starts at 16."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","18 años"],"h1":"Es la misma edad en que muchos jóvenes consiguen su primer trabajo.","h2":"En el Distrito de Columbia, usted debe tener por lo menos 16 años para obtener un permiso de aprendiz.","p":"Correcto. En DC el permiso de aprendiz empieza a los 16."},"zh":{"q":"在 District of Columbia，最小几岁可以拿到学习驾照？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"它和很多青少年找到第一份工作的年龄一样。","h2":"在 District of Columbia，你必须至少 16 岁才能拿到学习驾照。","p":"对。在 DC，学习驾照从 16 岁开始。"},"vi":{"q":"Ở District of Columbia (DC), tuổi nhỏ nhất để lấy giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là tuổi mà nhiều thiếu niên có việc làm đầu tiên.","h2":"Ở District of Columbia, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái.","p":"Đúng. Ở DC, giấy phép tập lái bắt đầu từ 16 tuổi."},"tl":{"q":"Sa District of Columbia (DC), ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Ito ang edad kung kailan maraming kabataan ang nagkakaroon ng unang trabaho.","h2":"Sa District of Columbia, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng learner permit.","p":"Tama. Sa DC, nagsisimula ang learner permit sa 16."},"ar":{"q":"في District of Columbia (DC)، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو العمر الذي يحصل فيه كثير من المراهقين على أول عمل لهم.","h2":"في District of Columbia يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم.","p":"صحيح. في DC يبدأ تصريح التعلّم من عمر 16 سنة."},"ref":{"doc":"DC","page":14}},{"id":"dc-002","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, during which hours may a learner permit holder drive?","o":["6:00 a.m. to 9:00 p.m.","5:00 a.m. to midnight","Any time of day","8:00 a.m. to 6:00 p.m."],"h1":"The window starts early in the morning and ends in the evening, before late night.","h2":"In the District of Columbia, a learner permit holder may drive only between 6:00 in the morning and 9:00 at night.","p":"Right. With a DC learner permit you drive from 6 a.m. to 9 p.m."},"es":{"q":"En el Distrito de Columbia, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a medianoche","A cualquier hora","De 8:00 a.m. a 6:00 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche, antes de que sea muy tarde.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz solo puede manejar entre las 6:00 de la mañana y las 9:00 de la noche.","p":"Correcto. Con permiso de aprendiz en DC se maneja de 6 a.m. a 9 p.m."},"zh":{"q":"在 District of Columbia，持学习驾照的人在什么时间可以开车？","o":["早上 6:00 到晚上 9:00","早上 5:00 到午夜","任何时间","早上 8:00 到下午 6:00"],"h1":"这段时间在清早开始，在晚上深夜以前结束。","h2":"在 District of Columbia，持学习驾照的人只能在早上 6:00 到晚上 9:00 之间开车。","p":"对。持 DC 学习驾照，你可以在早上 6 点到晚上 9 点开车。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái được lái xe trong những giờ nào?","o":["Từ 6:00 sáng đến 9:00 tối","Từ 5:00 sáng đến nửa đêm","Bất cứ giờ nào trong ngày","Từ 8:00 sáng đến 6:00 chiều"],"h1":"Khoảng thời gian bắt đầu từ sáng sớm và kết thúc vào buổi tối, trước khi khuya.","h2":"Ở District of Columbia, người có giấy phép tập lái chỉ được lái xe từ 6:00 sáng đến 9:00 tối.","p":"Đúng. Với giấy phép tập lái ở DC, bạn lái từ 6 giờ sáng đến 9 giờ tối."},"tl":{"q":"Sa District of Columbia, anong oras puwedeng magmaneho ang may hawak ng learner permit?","o":["6:00 a.m. hanggang 9:00 p.m.","5:00 a.m. hanggang hatinggabi","Kahit anong oras","8:00 a.m. hanggang 6:00 p.m."],"h1":"Nagsisimula ito nang maaga sa umaga at natatapos sa gabi, bago maghatinggabi.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay puwedeng magmaneho lang mula 6:00 ng umaga hanggang 9:00 ng gabi.","p":"Tama. May learner permit sa DC, nagmamaneho ka mula 6 a.m. hanggang 9 p.m."},"ar":{"q":"في District of Columbia، في أي ساعات يجوز لحامل تصريح التعلّم أن يقود؟","o":["من 6:00 صباحًا إلى 9:00 مساءً","من 5:00 صباحًا إلى منتصف الليل","في أي وقت من اليوم","من 8:00 صباحًا إلى 6:00 مساءً"],"h1":"تبدأ الفترة في الصباح الباكر وتنتهي في المساء، قبل آخر الليل.","h2":"في District of Columbia يجوز لحامل تصريح التعلّم أن يقود فقط بين الساعة 6:00 صباحًا والساعة 9:00 مساءً.","p":"صحيح. بتصريح التعلّم في DC تقود من 6 صباحًا إلى 9 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-003","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how many hours of supervised driving must a teen complete before getting a provisional license?","o":["10 hours","20 hours","60 hours","40 hours"],"h1":"It is the same number as a full work week.","h2":"In the District of Columbia, a teen must complete at least 40 hours of supervised driving before moving to a provisional license.","p":"Right. DC asks for 40 supervised hours first."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo supervisado debe completar un joven antes de obtener una licencia provisional?","o":["10 horas","20 horas","60 horas","40 horas"],"h1":"Es el mismo número que una semana completa de trabajo.","h2":"En el Distrito de Columbia, un joven debe completar por lo menos 40 horas de manejo supervisado antes de pasar a la licencia provisional.","p":"Correcto. DC pide primero 40 horas supervisadas."},"zh":{"q":"在 District of Columbia，青少年拿过渡驾照前，必须完成多少小时有人监督的驾驶？","o":["10 小时","20 小时","60 小时","40 小时"],"h1":"它和一个完整工作周的小时数一样。","h2":"在 District of Columbia，青少年升到过渡驾照前，必须完成至少 40 小时有人监督的驾驶。","p":"对。DC 先要求 40 小时有人监督的驾驶。"},"vi":{"q":"Ở District of Columbia, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái tạm thời (provisional license)?","o":["10 giờ","20 giờ","60 giờ","40 giờ"],"h1":"Đó là số giờ của một tuần làm việc đầy đủ.","h2":"Ở District of Columbia, thiếu niên phải lái xe có người giám sát ít nhất 40 giờ trước khi chuyển sang bằng lái tạm thời.","p":"Đúng. DC yêu cầu 40 giờ lái có người giám sát trước."},"tl":{"q":"Sa District of Columbia, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng kabataan bago makakuha ng provisional license?","o":["10 oras","20 oras","60 oras","40 oras"],"h1":"Ito ang bilang ng oras sa isang buong linggo ng trabaho.","h2":"Sa District of Columbia, dapat tapusin ng kabataan ang hindi bababa sa 40 oras ng pagmamaneho na may gumagabay bago lumipat sa provisional license.","p":"Tama. Humihingi muna ang DC ng 40 oras na may gumagabay."},"ar":{"q":"في District of Columbia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["10 ساعات","20 ساعة","60 ساعة","40 ساعة"],"h1":"هو عدد ساعات أسبوع عمل كامل.","h2":"في District of Columbia يجب أن يكمل المراهق 40 ساعة على الأقل من القيادة تحت الإشراف قبل الانتقال إلى الرخصة المؤقتة.","p":"صحيح. تطلب DC أولًا 40 ساعة تحت الإشراف."},"ref":{"doc":"DC","page":14}},{"id":"dc-004","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, how many hours of supervised night driving must a provisional driver complete before the next license stage?","o":["5 hours","10 hours","30 hours","50 hours"],"h1":"It is a small, round number.","h2":"In the District of Columbia, a provisional driver must complete at least 10 hours of supervised night driving before moving to the full license with conditions.","p":"Right. DC asks for 10 hours of night practice."},"es":{"q":"En el Distrito de Columbia, ¿cuántas horas de manejo nocturno supervisado debe completar un conductor provisional antes de la siguiente etapa de licencia?","o":["5 horas","10 horas","30 horas","50 horas"],"h1":"Es un número pequeño y redondo.","h2":"En el Distrito de Columbia, un conductor provisional debe completar por lo menos 10 horas de manejo nocturno supervisado antes de pasar a la licencia completa con condiciones.","p":"Correcto. DC pide 10 horas de práctica de noche."},"zh":{"q":"在 District of Columbia，持过渡驾照的司机升到下一个驾照阶段前，必须完成多少小时有人监督的夜间驾驶？","o":["5 小时","10 小时","30 小时","50 小时"],"h1":"它是一个小的整数。","h2":"在 District of Columbia，持过渡驾照的司机升到有条件的正式驾照前，必须完成至少 10 小时有人监督的夜间驾驶。","p":"对。DC 要求 10 小时夜间练习。"},"vi":{"q":"Ở District of Columbia, người có bằng lái tạm thời phải lái xe ban đêm có người giám sát bao nhiêu giờ trước giai đoạn bằng lái tiếp theo?","o":["5 giờ","10 giờ","30 giờ","50 giờ"],"h1":"Đó là một số nhỏ và tròn.","h2":"Ở District of Columbia, người có bằng lái tạm thời phải lái xe ban đêm có người giám sát ít nhất 10 giờ trước khi chuyển sang bằng lái đầy đủ có điều kiện.","p":"Đúng. DC yêu cầu 10 giờ tập lái ban đêm."},"tl":{"q":"Sa District of Columbia, ilang oras ng pagmamaneho sa gabi na may gumagabay ang dapat tapusin ng provisional driver bago ang susunod na yugto ng lisensya?","o":["5 oras","10 oras","30 oras","50 oras"],"h1":"Maliit at buong numero ito.","h2":"Sa District of Columbia, dapat tapusin ng provisional driver ang hindi bababa sa 10 oras ng pagmamaneho sa gabi na may gumagabay bago lumipat sa buong lisensya na may mga kondisyon.","p":"Tama. Humihingi ang DC ng 10 oras na pagsasanay sa gabi."},"ar":{"q":"في District of Columbia، كم ساعة من القيادة الليلية تحت الإشراف يجب أن يكملها حامل الرخصة المؤقتة قبل المرحلة التالية من الرخصة؟","o":["5 ساعات","10 ساعات","30 ساعة","50 ساعة"],"h1":"هو عدد صغير ومستدير.","h2":"في District of Columbia يجب أن يكمل حامل الرخصة المؤقتة 10 ساعات على الأقل من القيادة الليلية تحت الإشراف قبل الانتقال إلى الرخصة الكاملة بشروط.","p":"صحيح. تطلب DC عشر ساعات من التدريب الليلي."},"ref":{"doc":"DC","page":14}},{"id":"dc-005","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, how long must a teen hold a learner permit before moving to the next stage?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"In the District of Columbia, a teen must hold the learner permit for at least 6 months before moving to a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En el Distrito de Columbia, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de pasar a la siguiente etapa?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"En el Distrito de Columbia, un joven debe tener el permiso de aprendiz por lo menos 6 meses antes de pasar a la licencia provisional.","p":"Correcto. Primero seis meses con el permiso."},"zh":{"q":"在 District of Columbia，青少年必须持有学习驾照多久，才能升到下一个阶段？","o":["1 个月","3 个月","6 个月","2 年"],"h1":"它是半年。","h2":"在 District of Columbia，青少年必须持有学习驾照至少 6 个月，才能升到过渡驾照。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở District of Columbia, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi chuyển sang giai đoạn tiếp theo?","o":["1 tháng","3 tháng","6 tháng","2 năm"],"h1":"Đó là nửa năm.","h2":"Ở District of Columbia, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi chuyển sang bằng lái tạm thời.","p":"Đúng. Giữ giấy phép tập lái sáu tháng trước."},"tl":{"q":"Sa District of Columbia, gaano katagal dapat hawak ng kabataan ang learner permit bago lumipat sa susunod na yugto?","o":["1 buwan","3 buwan","6 na buwan","2 taon"],"h1":"Kalahating taon ito.","h2":"Sa District of Columbia, dapat hawak ng kabataan ang learner permit nang hindi bababa sa 6 na buwan bago lumipat sa provisional license.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في District of Columbia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الانتقال إلى المرحلة التالية؟","o":["شهر واحد","3 أشهر","6 أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في District of Columbia يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الانتقال إلى الرخصة المؤقتة.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"DC","page":14}},{"id":"dc-006","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what can you do if you turn 21 while you hold a learner permit?","o":["Schedule the road test right away, without waiting out the six months","Drive alone with the permit","Skip the road test","Nothing changes; you still wait six months"],"h1":"Being an adult removes the waiting period, not the test.","h2":"In the District of Columbia, if you turn 21 while holding a learner permit, you may schedule the road test right away, without the driving certification form or the six-month wait.","p":"Right. At 21 the wait is gone, but you still take the road test."},"es":{"q":"En el Distrito de Columbia, ¿qué puede hacer si cumple 21 años mientras tiene un permiso de aprendiz?","o":["Programar el examen de manejo de inmediato, sin esperar los seis meses","Manejar solo con el permiso","No tomar el examen de manejo","Nada cambia; todavía espera seis meses"],"h1":"Ser adulto quita el tiempo de espera, no el examen.","h2":"En el Distrito de Columbia, si usted cumple 21 años con permiso de aprendiz, puede programar el examen de manejo de inmediato, sin el formulario de certificación de manejo ni la espera de seis meses.","p":"Correcto. A los 21 ya no espera, pero sí toma el examen de manejo."},"zh":{"q":"在 District of Columbia，如果你持有学习驾照时满了 21 岁，你可以怎么做？","o":["马上预约路考，不用等满六个月","用学习驾照单独开车","不用路考","什么都不变，还是要等六个月"],"h1":"成年会取消等待期，但不会取消考试。","h2":"在 District of Columbia，如果你持有学习驾照时满了 21 岁，你可以马上预约路考，不需要驾驶证明表，也不用等六个月。","p":"对。21 岁时不用再等，但还是要路考。"},"vi":{"q":"Ở District of Columbia, bạn có thể làm gì nếu bạn tròn 21 tuổi khi đang có giấy phép tập lái?","o":["Đặt lịch thi lái xe ngay, không cần chờ hết sáu tháng","Lái xe một mình với giấy phép tập lái","Bỏ qua bài thi lái xe","Không có gì thay đổi; bạn vẫn chờ sáu tháng"],"h1":"Là người lớn thì bỏ được thời gian chờ, nhưng không bỏ được bài thi.","h2":"Ở District of Columbia, nếu bạn tròn 21 tuổi khi đang có giấy phép tập lái, bạn có thể đặt lịch thi lái xe ngay, không cần mẫu xác nhận giờ lái và không cần chờ sáu tháng.","p":"Đúng. Đến 21 tuổi thì không phải chờ, nhưng bạn vẫn phải thi lái xe."},"tl":{"q":"Sa District of Columbia, ano ang puwede mong gawin kung mag-21 ka habang may hawak kang learner permit?","o":["Mag-iskedyul agad ng road test, nang hindi hinihintay ang anim na buwan","Magmaneho nang mag-isa gamit ang permit","Laktawan ang road test","Walang nagbabago; maghihintay ka pa rin ng anim na buwan"],"h1":"Ang pagiging adulto ay nag-aalis ng paghihintay, hindi ng test.","h2":"Sa District of Columbia, kung mag-21 ka habang may hawak na learner permit, puwede kang mag-iskedyul agad ng road test, nang walang driving certification form at walang anim na buwang paghihintay.","p":"Tama. Sa 21, wala nang paghihintay, pero kukuha ka pa rin ng road test."},"ar":{"q":"في District of Columbia، ماذا يمكنك أن تفعل إذا بلغت 21 سنة وأنت تحمل تصريح التعلّم؟","o":["تحجز اختبار القيادة على الطريق فورًا، دون انتظار الأشهر الستة","تقود وحدك بالتصريح","تتخطى اختبار القيادة على الطريق","لا يتغير شيء؛ ما زلت تنتظر ستة أشهر"],"h1":"كونك بالغًا يلغي فترة الانتظار، لا الاختبار.","h2":"في District of Columbia إذا بلغت 21 سنة وأنت تحمل تصريح التعلّم، يمكنك حجز اختبار القيادة على الطريق فورًا، دون استمارة إثبات ساعات القيادة ودون انتظار ستة أشهر.","p":"صحيح. في عمر 21 يزول الانتظار، لكنك ما زلت تخضع لاختبار القيادة على الطريق."},"ref":{"doc":"DC","page":15}},{"id":"dc-007","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, from September to June, until what time may a provisional driver drive on a Monday through Thursday night?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"It is one minute before 11 at night.","h2":"In the District of Columbia, from September to June, a provisional driver may drive on Monday through Thursday only until 10:59 at night.","p":"Right. From Monday to Thursday the limit is 10:59 p.m."},"es":{"q":"En el Distrito de Columbia, de septiembre a junio, ¿hasta qué hora puede manejar un conductor provisional de lunes a jueves en la noche?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"Es un minuto antes de las 11 de la noche.","h2":"En el Distrito de Columbia, de septiembre a junio, un conductor provisional puede manejar de lunes a jueves solo hasta las 10:59 de la noche.","p":"Correcto. De lunes a jueves el límite es 10:59 p.m."},"zh":{"q":"在 District of Columbia，从九月到六月，持过渡驾照的司机星期一到星期四晚上可以开车到几点？","o":["晚上 9:00","晚上 10:59","晚上 11:59","凌晨 1:00"],"h1":"它是晚上 11 点前一分钟。","h2":"在 District of Columbia，从九月到六月，持过渡驾照的司机星期一到星期四只能开车到晚上 10:59。","p":"对。星期一到星期四的限制是晚上 10:59。"},"vi":{"q":"Ở District of Columbia, từ tháng Chín đến tháng Sáu, người có bằng lái tạm thời được lái xe đến mấy giờ vào tối thứ Hai đến thứ Năm?","o":["9:00 tối","10:59 tối","11:59 tối","1:00 sáng"],"h1":"Đó là một phút trước 11 giờ đêm.","h2":"Ở District of Columbia, từ tháng Chín đến tháng Sáu, người có bằng lái tạm thời chỉ được lái xe vào thứ Hai đến thứ Năm cho đến 10:59 tối.","p":"Đúng. Từ thứ Hai đến thứ Năm, giới hạn là 10:59 tối."},"tl":{"q":"Sa District of Columbia, mula Setyembre hanggang Hunyo, hanggang anong oras puwedeng magmaneho ang provisional driver sa gabi ng Lunes hanggang Huwebes?","o":["9:00 p.m.","10:59 p.m.","11:59 p.m.","1:00 a.m."],"h1":"Isang minuto ito bago mag-11 ng gabi.","h2":"Sa District of Columbia, mula Setyembre hanggang Hunyo, ang provisional driver ay puwedeng magmaneho sa Lunes hanggang Huwebes hanggang 10:59 ng gabi lang.","p":"Tama. Mula Lunes hanggang Huwebes, ang limitasyon ay 10:59 p.m."},"ar":{"q":"في District of Columbia، من سبتمبر إلى يونيو، حتى أي ساعة يجوز لحامل الرخصة المؤقتة أن يقود في ليالي الاثنين إلى الخميس؟","o":["9:00 مساءً","10:59 مساءً","11:59 مساءً","1:00 صباحًا"],"h1":"هي دقيقة واحدة قبل الساعة 11 ليلًا.","h2":"في District of Columbia، من سبتمبر إلى يونيو، يجوز لحامل الرخصة المؤقتة أن يقود من الاثنين إلى الخميس حتى الساعة 10:59 مساءً فقط.","p":"صحيح. من الاثنين إلى الخميس الحد هو 10:59 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-008","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, in July and August, until what time may a provisional driver drive alone?","o":["9:00 p.m. every day","10:59 p.m. every day","There is no limit in summer","11:59 p.m. every day"],"h1":"In summer the latest time is the same every day, just before midnight.","h2":"In the District of Columbia, in July and August, a provisional driver may drive alone every day until 11:59 at night.","p":"Right. Summer nights end at 11:59 p.m."},"es":{"q":"En el Distrito de Columbia, en julio y agosto, ¿hasta qué hora puede manejar solo un conductor provisional?","o":["9:00 p.m. todos los días","10:59 p.m. todos los días","No hay límite en verano","11:59 p.m. todos los días"],"h1":"En verano la hora límite es igual todos los días, justo antes de medianoche.","h2":"En el Distrito de Columbia, en julio y agosto, un conductor provisional puede manejar solo todos los días hasta las 11:59 de la noche.","p":"Correcto. En verano el límite es 11:59 p.m."},"zh":{"q":"在 District of Columbia，在七月和八月，持过渡驾照的司机可以单独开车到几点？","o":["每天晚上 9:00","每天晚上 10:59","夏天没有限制","每天晚上 11:59"],"h1":"夏天每天最晚的时间都一样，就在午夜之前。","h2":"在 District of Columbia，在七月和八月，持过渡驾照的司机每天可以单独开车到晚上 11:59。","p":"对。夏天晚上到 11:59 为止。"},"vi":{"q":"Ở District of Columbia, vào tháng Bảy và tháng Tám, người có bằng lái tạm thời được lái xe một mình đến mấy giờ?","o":["9:00 tối mỗi ngày","10:59 tối mỗi ngày","Mùa hè không có giới hạn","11:59 tối mỗi ngày"],"h1":"Vào mùa hè, giờ muộn nhất giống nhau mỗi ngày, ngay trước nửa đêm.","h2":"Ở District of Columbia, vào tháng Bảy và tháng Tám, người có bằng lái tạm thời được lái xe một mình mỗi ngày đến 11:59 tối.","p":"Đúng. Tối mùa hè kết thúc lúc 11:59 tối."},"tl":{"q":"Sa District of Columbia, sa Hulyo at Agosto, hanggang anong oras puwedeng magmaneho nang mag-isa ang provisional driver?","o":["9:00 p.m. araw-araw","10:59 p.m. araw-araw","Walang limitasyon sa tag-init","11:59 p.m. araw-araw"],"h1":"Sa tag-init, pareho ang pinakahuling oras araw-araw, bago maghatinggabi.","h2":"Sa District of Columbia, sa Hulyo at Agosto, ang provisional driver ay puwedeng magmaneho nang mag-isa araw-araw hanggang 11:59 ng gabi.","p":"Tama. Natatapos ang gabi sa tag-init sa 11:59 p.m."},"ar":{"q":"في District of Columbia، في يوليو وأغسطس، حتى أي ساعة يجوز لحامل الرخصة المؤقتة أن يقود وحده؟","o":["9:00 مساءً كل يوم","10:59 مساءً كل يوم","لا يوجد حد في الصيف","11:59 مساءً كل يوم"],"h1":"في الصيف آخر وقت هو نفسه كل يوم، قبل منتصف الليل مباشرة.","h2":"في District of Columbia، في يوليو وأغسطس، يجوز لحامل الرخصة المؤقتة أن يقود وحده كل يوم حتى الساعة 11:59 مساءً.","p":"صحيح. ليالي الصيف تنتهي عند 11:59 مساءً."},"ref":{"doc":"DC","page":14}},{"id":"dc-009","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is the speed limit on a street with no speed limit sign?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than in most states, and it has been since 2020.","h2":"In the District of Columbia, the speed limit is 20 miles per hour on any street where no other limit is posted.","p":"Right. The DC default is 20 mph."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad en una calle que no tiene letrero de límite?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que en la mayoría de los estados, y así es desde 2020.","h2":"En el Distrito de Columbia, el límite de velocidad es de 20 millas por hora en cualquier calle donde no haya otro límite indicado.","p":"Correcto. En DC el límite general es 20 mph."},"zh":{"q":"在 District of Columbia，没有限速标志的街道限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比大多数州低，从 2020 年起就是这样。","h2":"在 District of Columbia，任何没有标示其他限速的街道，限速是每小时 20 英里。","p":"对。DC 的默认限速是 20 mph。"},"vi":{"q":"Ở District of Columbia, tốc độ tối đa trên đường không có biển báo tốc độ là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó thấp hơn ở hầu hết các tiểu bang, và như vậy từ năm 2020.","h2":"Ở District of Columbia, tốc độ tối đa là 20 dặm một giờ (mph) trên mọi con đường không có biển báo giới hạn khác.","p":"Đúng. Tốc độ mặc định ở DC là 20 mph."},"tl":{"q":"Sa District of Columbia, ano ang speed limit sa kalyeng walang karatula ng speed limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Mas mababa ito kaysa sa karamihan ng estado, at ganito na mula 2020.","h2":"Sa District of Columbia, ang speed limit ay 20 milya bawat oras (mph) sa anumang kalye na walang ibang nakapaskil na limitasyon.","p":"Tama. Ang default sa DC ay 20 mph."},"ar":{"q":"في District of Columbia، ما حد السرعة في شارع لا توجد فيه لافتة حد السرعة؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أقل مما في معظم الولايات، وهو كذلك منذ 2020.","h2":"في District of Columbia حد السرعة هو 20 ميلًا في الساعة (mph) في أي شارع لا يوجد فيه حد آخر مكتوب.","p":"صحيح. الحد العادي في DC هو 20 mph."},"ref":{"doc":"DC","page":46}},{"id":"dc-010","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the speed limit next to a school at the times shown on the signs?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is lower than the city's usual 20 mph.","h2":"In the District of Columbia, the speed limit on streets next to schools is 15 miles per hour at the times shown on the signs.","p":"Right. 15 mph near schools."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad junto a una escuela en los horarios indicados en los letreros?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es más bajo que el límite general de 20 mph de la ciudad.","h2":"En el Distrito de Columbia, el límite de velocidad en las calles junto a las escuelas es de 15 millas por hora en los horarios indicados en los letreros.","p":"Correcto. 15 mph cerca de las escuelas."},"zh":{"q":"在 District of Columbia，在标志写的时间内，学校旁边的限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"它比城市一般的 20 mph 低。","h2":"在 District of Columbia，在标志写的时间内，学校旁边街道的限速是每小时 15 英里。","p":"对。学校附近 15 mph。"},"vi":{"q":"Ở District of Columbia, tốc độ tối đa gần trường học vào những giờ ghi trên biển báo là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Nó thấp hơn mức 20 mph thông thường của thành phố.","h2":"Ở District of Columbia, tốc độ tối đa trên đường gần trường học là 15 dặm một giờ (mph) vào những giờ ghi trên biển báo.","p":"Đúng. 15 mph gần trường học."},"tl":{"q":"Sa District of Columbia, ano ang speed limit malapit sa paaralan sa mga oras na nakasulat sa karatula?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Mas mababa ito kaysa sa karaniwang 20 mph ng lungsod.","h2":"Sa District of Columbia, ang speed limit sa mga kalyeng malapit sa paaralan ay 15 milya bawat oras (mph) sa mga oras na nakasulat sa karatula.","p":"Tama. 15 mph malapit sa paaralan."},"ar":{"q":"في District of Columbia، ما حد السرعة بجانب مدرسة في الأوقات المكتوبة على اللافتات؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"هو أقل من حد المدينة المعتاد 20 mph.","h2":"في District of Columbia حد السرعة في الشوارع بجانب المدارس هو 15 ميلًا في الساعة (mph) في الأوقات المكتوبة على اللافتات.","p":"صحيح. 15 mph قرب المدارس."},"ref":{"doc":"DC","page":46}},{"id":"dc-011","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, how may an adult driver talk on a cell phone while the car is moving?","o":["Holding the phone at the ear","Only while stopped at a red light, holding the phone","Only with a hands-free device","Never, not even hands-free"],"h1":"Both hands must be able to stay on the wheel.","h2":"In the District of Columbia, an adult driver may use a cell phone while moving only with a hands-free device.","p":"Right. In DC, adults must use hands-free."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede un conductor adulto hablar por celular mientras el auto está en movimiento?","o":["Sosteniendo el teléfono en el oído","Solo en un semáforo en rojo, sosteniendo el teléfono","Solo con un dispositivo de manos libres","Nunca, ni con manos libres"],"h1":"Las dos manos deben poder quedarse en el volante.","h2":"En el Distrito de Columbia, un conductor adulto solo puede usar el celular en movimiento con un dispositivo de manos libres.","p":"Correcto. En DC los adultos deben usar manos libres."},"zh":{"q":"在 District of Columbia，车在行驶时，成年司机可以怎样用手机打电话？","o":["把手机拿在耳边","只在红灯停车时，拿着手机","只能用免持设备","从来不可以，免持也不行"],"h1":"两只手都必须能一直放在方向盘上。","h2":"在 District of Columbia，成年司机在车行驶时只能用免持设备用手机。","p":"对。在 DC，成年人必须用免持。"},"vi":{"q":"Ở District of Columbia, người lái xe trưởng thành được nói chuyện điện thoại di động như thế nào khi xe đang chạy?","o":["Cầm điện thoại áp vào tai","Chỉ khi dừng đèn đỏ, cầm điện thoại","Chỉ với thiết bị rảnh tay (hands-free)","Không bao giờ, kể cả rảnh tay"],"h1":"Cả hai tay phải có thể giữ trên vô lăng.","h2":"Ở District of Columbia, người lái xe trưởng thành chỉ được dùng điện thoại di động khi xe đang chạy nếu dùng thiết bị rảnh tay.","p":"Đúng. Ở DC, người lớn phải dùng thiết bị rảnh tay."},"tl":{"q":"Sa District of Columbia, paano puwedeng makipag-usap sa cell phone ang adultong driver habang umaandar ang sasakyan?","o":["Hawak ang phone sa tainga","Habang nakahinto lang sa pulang ilaw, hawak ang phone","Gamit lang ang hands-free na device","Hindi kailanman, kahit hands-free"],"h1":"Dapat manatili sa manibela ang dalawang kamay.","h2":"Sa District of Columbia, ang adultong driver ay puwedeng gumamit ng cell phone habang umaandar lang kung may hands-free na device.","p":"Tama. Sa DC, dapat hands-free ang mga adulto."},"ar":{"q":"في District of Columbia، كيف يجوز للسائق البالغ أن يتكلم في الهاتف المحمول والسيارة تسير؟","o":["يمسك الهاتف على أذنه","فقط عند التوقف عند الإشارة الحمراء، ممسكًا الهاتف","فقط بجهاز بدون استخدام اليدين (hands-free)","أبدًا، ولا حتى بدون استخدام اليدين"],"h1":"يجب أن تبقى اليدان كلتاهما على المقود.","h2":"في District of Columbia يجوز للسائق البالغ أن يستعمل الهاتف المحمول والسيارة تسير فقط بجهاز بدون استخدام اليدين.","p":"صحيح. في DC يجب على البالغين استخدام جهاز بدون يدين."},"ref":{"doc":"DC","page":26}},{"id":"dc-012","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, may a learner permit holder use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","Yes, if the supervisor agrees","No, only to call for an emergency"],"h1":"The rule for learners is stricter than the rule for adults.","h2":"In the District of Columbia, a learner permit holder may not use a cell phone at all while driving, even hands-free, except to make an emergency call.","p":"Right. Learners in DC put the phone away, hands-free included."},"es":{"q":"En el Distrito de Columbia, ¿puede una persona con permiso de aprendiz usar un teléfono de manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, si el acompañante está de acuerdo","No, solo para llamar en una emergencia"],"h1":"La regla para aprendices es más estricta que la regla para adultos.","h2":"En el Distrito de Columbia, quien tiene permiso de aprendiz no puede usar el celular mientras maneja, ni con manos libres, excepto para hacer una llamada de emergencia.","p":"Correcto. En DC los aprendices guardan el teléfono, incluso el de manos libres."},"zh":{"q":"在 District of Columbia，持学习驾照的人开车时可以用免持电话吗？","o":["可以，免持总是允许的","可以，但只在公路上","可以，如果监督的人同意","不可以，只能打紧急电话"],"h1":"对学习驾驶的人的规定比对成年人更严。","h2":"在 District of Columbia，持学习驾照的人开车时完全不能用手机，即使是免持也不行，打紧急电话除外。","p":"对。在 DC 学习驾驶的人要把手机收起来，免持也一样。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên đường cao tốc","Có, nếu người giám sát đồng ý","Không, chỉ được gọi khi khẩn cấp"],"h1":"Quy định cho người tập lái nghiêm hơn quy định cho người lớn.","h2":"Ở District of Columbia, người có giấy phép tập lái hoàn toàn không được dùng điện thoại di động khi lái xe, kể cả rảnh tay, trừ khi gọi khẩn cấp.","p":"Đúng. Người tập lái ở DC phải cất điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa District of Columbia, puwede bang gumamit ng hands-free na phone habang nagmamaneho ang may hawak ng learner permit?","o":["Oo, laging puwede ang hands-free","Oo, pero sa highway lang","Oo, kung papayag ang gumagabay","Hindi, maliban sa pagtawag kapag may emergency"],"h1":"Mas mahigpit ang patakaran para sa nag-aaral kaysa sa mga adulto.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay hindi puwedeng gumamit ng cell phone habang nagmamaneho, kahit hands-free, maliban sa pagtawag kapag may emergency.","p":"Tama. Sa DC, itinatabi ng nag-aaral ang phone, kahit hands-free."},"ar":{"q":"في District of Columbia، هل يجوز لحامل تصريح التعلّم أن يستعمل هاتفًا بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، بدون اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","نعم، إذا وافق المشرف","لا، إلا للاتصال في حالة طوارئ"],"h1":"القاعدة للمتعلمين أشد من القاعدة للبالغين.","h2":"في District of Columbia لا يجوز لحامل تصريح التعلّم أن يستعمل الهاتف المحمول أبدًا أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا للاتصال في حالة طوارئ.","p":"صحيح. المتعلمون في DC يبعدون الهاتف، حتى بدون استخدام اليدين."},"ref":{"doc":"DC","page":15}},{"id":"dc-013","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, how much alcohol may a driver under 21 have in the body?","o":["None; any measurable amount is against the law","Up to 0.02","Up to 0.05","Up to 0.08"],"h1":"Think of the lowest possible amount.","h2":"In the District of Columbia, a driver under 21 may not have any measurable amount of alcohol, and can be arrested for driving while intoxicated.","p":"Right. Under 21 in DC, the limit is zero."},"es":{"q":"En el Distrito de Columbia, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Nada; cualquier cantidad que se pueda medir es ilegal","Hasta 0.02","Hasta 0.05","Hasta 0.08"],"h1":"Piense en la cantidad más baja posible.","h2":"En el Distrito de Columbia, un conductor menor de 21 años no puede tener ninguna cantidad medible de alcohol, y lo pueden arrestar por manejar intoxicado.","p":"Correcto. Para menores de 21 en DC, el límite es cero."},"zh":{"q":"在 District of Columbia，21 岁以下的司机体内可以有多少酒精？","o":["一点都不能有；任何可以测出的量都是违法的","最多 0.02","最多 0.05","最多 0.08"],"h1":"想一想最低可能的量。","h2":"在 District of Columbia，21 岁以下的司机体内不能有任何可以测出的酒精，否则可能因醉酒驾驶被逮捕。","p":"对。在 DC，21 岁以下的限制是零。"},"vi":{"q":"Ở District of Columbia, người lái xe dưới 21 tuổi được có bao nhiêu rượu bia trong cơ thể?","o":["Không có; bất kỳ lượng nào đo được đều phạm luật","Tối đa 0.02","Tối đa 0.05","Tối đa 0.08"],"h1":"Hãy nghĩ đến mức thấp nhất có thể.","h2":"Ở District of Columbia, người lái xe dưới 21 tuổi không được có bất kỳ lượng rượu bia nào đo được, và có thể bị bắt vì lái xe khi say.","p":"Đúng. Dưới 21 tuổi ở DC, giới hạn là không."},"tl":{"q":"Sa District of Columbia, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Wala; labag sa batas ang anumang dami na nasusukat","Hanggang 0.02","Hanggang 0.05","Hanggang 0.08"],"h1":"Isipin ang pinakamababang posibleng dami.","h2":"Sa District of Columbia, ang driver na wala pang 21 ay hindi puwedeng magkaroon ng anumang dami ng alak na nasusukat, at puwede siyang arestuhin dahil sa pagmamaneho nang lasing.","p":"Tama. Wala pang 21 sa DC, zero ang limitasyon."},"ar":{"q":"في District of Columbia، كم كحولًا يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["لا شيء؛ أي كمية يمكن قياسها مخالفة للقانون","حتى 0.02","حتى 0.05","حتى 0.08"],"h1":"فكّر في أقل كمية ممكنة.","h2":"في District of Columbia لا يجوز أن يكون لدى السائق الذي عمره أقل من 21 سنة أي كمية كحول يمكن قياسها، ويمكن القبض عليه بتهمة القيادة تحت تأثير الكحول.","p":"صحيح. تحت 21 سنة في DC الحد هو صفر."},"ref":{"doc":"DC","page":null}},{"id":"dc-014","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, how long is a learner permit valid for a US citizen?","o":["6 months","2 years","4 years","8 years"],"h1":"It is longer than one year, but you cannot renew it.","h2":"In the District of Columbia, a learner permit is valid for two years for a US citizen and cannot be renewed; after that you must pass the knowledge test again.","p":"Right. The permit lasts two years and cannot be renewed."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo es válido el permiso de aprendiz para un ciudadano de EE. UU.?","o":["6 meses","2 años","4 años","8 años"],"h1":"Es más de un año, pero no se puede renovar.","h2":"En el Distrito de Columbia, el permiso de aprendiz es válido por dos años para un ciudadano de EE. UU. y no se puede renovar; después usted debe aprobar otra vez el examen de conocimientos.","p":"Correcto. El permiso dura dos años y no se puede renovar."},"zh":{"q":"在 District of Columbia，美国公民的学习驾照有效期是多久？","o":["6 个月","2 年","4 年","8 年"],"h1":"它比一年长，但是不能续期。","h2":"在 District of Columbia，美国公民的学习驾照有效期是两年，而且不能续期；过期后你必须再考一次笔试。","p":"对。学习驾照有效两年，不能续期。"},"vi":{"q":"Ở District of Columbia, giấy phép tập lái có giá trị bao lâu đối với công dân Mỹ?","o":["6 tháng","2 năm","4 năm","8 năm"],"h1":"Nó dài hơn một năm, nhưng bạn không thể gia hạn.","h2":"Ở District of Columbia, giấy phép tập lái có giá trị hai năm đối với công dân Mỹ và không thể gia hạn; sau đó bạn phải thi lại bài thi lý thuyết.","p":"Đúng. Giấy phép tập lái có giá trị hai năm và không thể gia hạn."},"tl":{"q":"Sa District of Columbia, gaano katagal valid ang learner permit para sa US citizen?","o":["6 na buwan","2 taon","4 na taon","8 taon"],"h1":"Mas mahaba ito sa isang taon, pero hindi mo ito puwedeng i-renew.","h2":"Sa District of Columbia, valid ang learner permit nang dalawang taon para sa US citizen at hindi ito puwedeng i-renew; pagkatapos nito, dapat kang pumasa ulit sa knowledge test.","p":"Tama. Tumatagal ang permit nang dalawang taon at hindi puwedeng i-renew."},"ar":{"q":"في District of Columbia، ما مدة صلاحية تصريح التعلّم للمواطن الأمريكي؟","o":["6 أشهر","سنتان","4 سنوات","8 سنوات"],"h1":"هي أطول من سنة واحدة، لكن لا يمكنك تجديده.","h2":"في District of Columbia يكون تصريح التعلّم صالحًا لمدة سنتين للمواطن الأمريكي ولا يمكن تجديده؛ بعد ذلك يجب أن تنجح في الاختبار النظري مرة أخرى.","p":"صحيح. التصريح صالح لمدة سنتين ولا يمكن تجديده."},"ref":{"doc":"DC","page":14}},{"id":"dc-015","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, what is the youngest age to get a provisional license?","o":["16 years old","17 years old","18 years old","16 and a half years old"],"h1":"It is six months after the youngest age for a learner permit.","h2":"In the District of Columbia, you must be at least 16 and a half years old to get a provisional license.","p":"Right. The provisional license starts at 16 and a half."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["16 años","17 años","18 años","16 años y medio"],"h1":"Es seis meses después de la edad mínima para el permiso de aprendiz.","h2":"En el Distrito de Columbia, usted debe tener por lo menos 16 años y medio para obtener una licencia provisional.","p":"Correcto. La licencia provisional empieza a los 16 años y medio."},"zh":{"q":"在 District of Columbia，最小几岁可以拿到过渡驾照？","o":["16 岁","17 岁","18 岁","16 岁半"],"h1":"它比拿学习驾照的最小年龄晚六个月。","h2":"在 District of Columbia，你必须至少 16 岁半才能拿到过渡驾照。","p":"对。过渡驾照从 16 岁半开始。"},"vi":{"q":"Ở District of Columbia, tuổi nhỏ nhất để lấy bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","17 tuổi","18 tuổi","16 tuổi rưỡi"],"h1":"Đó là sáu tháng sau tuổi nhỏ nhất để lấy giấy phép tập lái.","h2":"Ở District of Columbia, bạn phải ít nhất 16 tuổi rưỡi để lấy bằng lái tạm thời.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi rưỡi."},"tl":{"q":"Sa District of Columbia, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","17 taong gulang","18 taong gulang","16 at kalahating taong gulang"],"h1":"Anim na buwan ito pagkatapos ng pinakabatang edad para sa learner permit.","h2":"Sa District of Columbia, dapat ay hindi bababa sa 16 at kalahating taong gulang ka para makakuha ng provisional license.","p":"Tama. Nagsisimula ang provisional license sa 16 at kalahati."},"ar":{"q":"في District of Columbia، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","17 سنة","18 سنة","16 سنة ونصف"],"h1":"هو بعد ستة أشهر من أصغر عمر للحصول على تصريح التعلّم.","h2":"في District of Columbia يجب أن يكون عمرك 16 سنة ونصفًا على الأقل للحصول على الرخصة المؤقتة.","p":"صحيح. تبدأ الرخصة المؤقتة من عمر 16 سنة ونصف."},"ref":{"doc":"DC","page":14}},{"id":"dc-016","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, you fail the knowledge test. How long must you wait before you try again?","o":["3 calendar days","1 week","30 days","6 months"],"h1":"It is only a few days.","h2":"In the District of Columbia, after you fail the knowledge test you must wait 3 calendar days before you can take it again.","p":"Right. Wait 3 calendar days, then try again."},"es":{"q":"En el Distrito de Columbia, usted no aprueba el examen de conocimientos. ¿Cuánto tiempo debe esperar para intentarlo otra vez?","o":["3 días naturales","1 semana","30 días","6 meses"],"h1":"Son solo unos pocos días.","h2":"En el Distrito de Columbia, si usted no aprueba el examen de conocimientos, debe esperar 3 días naturales para volver a tomarlo.","p":"Correcto. Espere 3 días naturales y vuelva a intentarlo."},"zh":{"q":"在 District of Columbia，你笔试没有通过。你必须等多久才能再考？","o":["3 个日历日","1 个星期","30 天","6 个月"],"h1":"只有几天。","h2":"在 District of Columbia，笔试没有通过后，你必须等 3 个日历日才能再考。","p":"对。等 3 个日历日，然后再考。"},"vi":{"q":"Ở District of Columbia, bạn thi trượt bài thi lý thuyết. Bạn phải chờ bao lâu trước khi thi lại?","o":["3 ngày theo lịch","1 tuần","30 ngày","6 tháng"],"h1":"Chỉ vài ngày thôi.","h2":"Ở District of Columbia, sau khi thi trượt bài thi lý thuyết, bạn phải chờ 3 ngày theo lịch trước khi được thi lại.","p":"Đúng. Chờ 3 ngày theo lịch, rồi thi lại."},"tl":{"q":"Sa District of Columbia, bumagsak ka sa knowledge test. Gaano katagal ka dapat maghintay bago sumubok ulit?","o":["3 araw sa kalendaryo","1 linggo","30 araw","6 na buwan"],"h1":"Ilang araw lang ito.","h2":"Sa District of Columbia, pagkatapos mong bumagsak sa knowledge test, dapat kang maghintay ng 3 araw sa kalendaryo bago ka puwedeng kumuha ulit nito.","p":"Tama. Maghintay ng 3 araw sa kalendaryo, saka sumubok ulit."},"ar":{"q":"في District of Columbia، رسبت في الاختبار النظري. كم يجب أن تنتظر قبل أن تحاول مرة أخرى؟","o":["3 أيام تقويمية","أسبوع واحد","30 يومًا","6 أشهر"],"h1":"هي أيام قليلة فقط.","h2":"في District of Columbia بعد أن ترسب في الاختبار النظري يجب أن تنتظر 3 أيام تقويمية قبل أن تتمكن من إعادته.","p":"صحيح. انتظر 3 أيام تقويمية، ثم حاول مرة أخرى."},"ref":{"doc":"DC","page":12}},{"id":"dc-017","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, who may ride in the car while a learner permit holder is driving?","o":["Any friends, if they wear seat belts","Up to two passengers under 21","Only the supervising driver, who is 21 or older","Only family members"],"h1":"Think of the one person the learner needs next to them.","h2":"In the District of Columbia, a learner permit holder may not carry any passengers other than the fully licensed supervising driver, who is 21 or older and sits in the front seat.","p":"Right. With a learner permit, only the supervisor rides along."},"es":{"q":"En el Distrito de Columbia, ¿quién puede ir en el carro mientras maneja una persona con permiso de aprendiz?","o":["Cualquier amigo, si usa el cinturón","Hasta dos pasajeros menores de 21 años","Solo el conductor que supervisa, de 21 años o más","Solo familiares"],"h1":"Piense en la única persona que el aprendiz necesita a su lado.","h2":"En el Distrito de Columbia, una persona con permiso de aprendiz no puede llevar más pasajeros que el conductor supervisor con licencia completa, de 21 años o más, sentado en el asiento delantero.","p":"Correcto. Con permiso de aprendiz, solo va el supervisor."},"zh":{"q":"在 District of Columbia，持学习驾照的人开车时，谁可以坐在车里？","o":["任何朋友，只要他们系安全带","最多两个 21 岁以下的乘客","只有监督的司机，他必须 21 岁或以上","只有家人"],"h1":"想一想学习驾驶的人身边需要的那一个人。","h2":"在 District of Columbia，持学习驾照的人除了有正式驾照的监督司机以外，不能载任何乘客；监督司机必须 21 岁或以上，并且坐在前座。","p":"对。持学习驾照时，只有监督的人可以一起坐车。"},"vi":{"q":"Ở District of Columbia, ai được ngồi trong xe khi người có giấy phép tập lái đang lái?","o":["Bất kỳ người bạn nào, nếu họ thắt dây an toàn","Tối đa hai hành khách dưới 21 tuổi","Chỉ người lái xe giám sát, từ 21 tuổi trở lên","Chỉ người trong gia đình"],"h1":"Hãy nghĩ đến một người mà người tập lái cần ngồi bên cạnh.","h2":"Ở District of Columbia, người có giấy phép tập lái không được chở hành khách nào khác ngoài người lái xe giám sát có bằng lái đầy đủ, từ 21 tuổi trở lên và ngồi ở ghế trước.","p":"Đúng. Với giấy phép tập lái, chỉ người giám sát được đi cùng."},"tl":{"q":"Sa District of Columbia, sino ang puwedeng sumakay sa kotse habang nagmamaneho ang may hawak ng learner permit?","o":["Kahit sinong kaibigan, kung naka-seat belt sila","Hanggang dalawang pasaherong wala pang 21","Ang gumagabay na driver lang, na 21 o mas matanda","Mga kapamilya lang"],"h1":"Isipin ang isang taong kailangan ng nag-aaral sa tabi niya.","h2":"Sa District of Columbia, ang may hawak ng learner permit ay hindi puwedeng magsakay ng ibang pasahero maliban sa gumagabay na driver na may buong lisensya, na 21 o mas matanda at nakaupo sa harap.","p":"Tama. Kapag may learner permit, ang gumagabay lang ang kasama sa sasakyan."},"ar":{"q":"في District of Columbia، من يجوز له أن يركب في السيارة بينما يقود حامل تصريح التعلّم؟","o":["أي أصدقاء، إذا وضعوا أحزمة الأمان","حتى راكبين اثنين عمرهما أقل من 21 سنة","السائق المشرف فقط، وعمره 21 سنة أو أكثر","أفراد العائلة فقط"],"h1":"فكّر في الشخص الوحيد الذي يحتاجه المتعلم بجانبه.","h2":"في District of Columbia لا يجوز لحامل تصريح التعلّم أن يحمل أي ركاب غير السائق المشرف الذي يحمل رخصة كاملة، وعمره 21 سنة أو أكثر ويجلس في المقعد الأمامي.","p":"صحيح. مع تصريح التعلّم، يركب المشرف فقط معك."},"ref":{"doc":"DC","page":15}},{"id":"dc-018","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, a driver under 18 has a full license with conditions. How many passengers under 21 may they carry, not counting siblings or their own child?","o":["None","No more than 2","No more than 3","No more than 4"],"h1":"It is a small number, but more than one.","h2":"In the District of Columbia, a driver under 18 with a full license with conditions may carry no more than two passengers under 21, not counting their brothers, sisters or own child.","p":"Right. No more than two passengers under 21."},"es":{"q":"En el Distrito de Columbia, un conductor menor de 18 años tiene licencia completa con condiciones. ¿Cuántos pasajeros menores de 21 años puede llevar, sin contar a sus hermanos ni a su propio hijo?","o":["Ninguno","No más de 2","No más de 3","No más de 4"],"h1":"Es un número pequeño, pero más de uno.","h2":"En el Distrito de Columbia, un conductor menor de 18 años con licencia completa con condiciones puede llevar no más de dos pasajeros menores de 21 años, sin contar a sus hermanos ni a su propio hijo.","p":"Correcto. No más de dos pasajeros menores de 21 años."},"zh":{"q":"在 District of Columbia，一个 18 岁以下的司机有有条件的正式驾照。不算兄弟姐妹或自己的孩子，他可以载多少个 21 岁以下的乘客？","o":["一个都不行","不超过 2 个","不超过 3 个","不超过 4 个"],"h1":"它是一个小的数字，但比一多。","h2":"在 District of Columbia，有有条件的正式驾照、18 岁以下的司机，最多只能载两个 21 岁以下的乘客，不算他的兄弟姐妹或自己的孩子。","p":"对。21 岁以下的乘客不超过两个。"},"vi":{"q":"Ở District of Columbia, một người lái xe dưới 18 tuổi có bằng lái đầy đủ có điều kiện. Họ được chở bao nhiêu hành khách dưới 21 tuổi, không tính anh chị em hoặc con của họ?","o":["Không ai","Không quá 2","Không quá 3","Không quá 4"],"h1":"Đó là một số nhỏ, nhưng nhiều hơn một.","h2":"Ở District of Columbia, người lái xe dưới 18 tuổi có bằng lái đầy đủ có điều kiện được chở không quá hai hành khách dưới 21 tuổi, không tính anh chị em hoặc con của họ.","p":"Đúng. Không quá hai hành khách dưới 21 tuổi."},"tl":{"q":"Sa District of Columbia, may buong lisensya na may mga kondisyon ang driver na wala pang 18. Ilang pasaherong wala pang 21 ang puwede niyang isakay, hindi kasama ang mga kapatid o sariling anak?","o":["Wala","Hindi hihigit sa 2","Hindi hihigit sa 3","Hindi hihigit sa 4"],"h1":"Maliit na numero ito, pero higit sa isa.","h2":"Sa District of Columbia, ang driver na wala pang 18 na may buong lisensya na may mga kondisyon ay puwedeng magsakay ng hindi hihigit sa dalawang pasaherong wala pang 21, hindi kasama ang kanyang mga kapatid o sariling anak.","p":"Tama. Hindi hihigit sa dalawang pasaherong wala pang 21."},"ar":{"q":"في District of Columbia، سائق عمره أقل من 18 سنة يحمل الرخصة الكاملة بشروط. كم راكبًا عمره أقل من 21 سنة يجوز له أن يحمل، دون حساب إخوته وأخواته أو طفله؟","o":["لا أحد","ليس أكثر من 2","ليس أكثر من 3","ليس أكثر من 4"],"h1":"هو عدد صغير، لكنه أكثر من واحد.","h2":"في District of Columbia يجوز للسائق الذي عمره أقل من 18 سنة ويحمل الرخصة الكاملة بشروط أن يحمل راكبين اثنين على الأكثر عمرهما أقل من 21 سنة، دون حساب إخوته وأخواته أو طفله.","p":"صحيح. ليس أكثر من راكبين اثنين عمرهما أقل من 21 سنة."},"ref":{"doc":"DC","page":15}},{"id":"dc-019","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what happens when a driver reaches 10 or 11 points?","o":["A warning letter only","A required safety class only","The license is suspended for 90 days","The license is revoked for 2 years"],"h1":"You lose your driving privileges for about three months.","h2":"In the District of Columbia, a driver who reaches 10 or 11 points has the license suspended for 90 days.","p":"Right. 10 or 11 points means a 90-day suspension."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa cuando un conductor llega a 10 u 11 puntos?","o":["Solo recibe una carta de advertencia","Solo debe tomar una clase de seguridad","Le suspenden la licencia por 90 días","Le revocan la licencia por 2 años"],"h1":"Usted pierde el derecho a manejar por unos tres meses.","h2":"En el Distrito de Columbia, a un conductor que llega a 10 u 11 puntos le suspenden la licencia por 90 días.","p":"Correcto. 10 u 11 puntos significan una suspensión de 90 días."},"zh":{"q":"在 District of Columbia，司机累计到 10 或 11 分时，会怎么样？","o":["只收到一封警告信","只需要上一门安全课","驾照被暂停 90 天","驾照被吊销 2 年"],"h1":"你会失去开车的权利大约三个月。","h2":"在 District of Columbia，累计到 10 或 11 分的司机，驾照会被暂停 90 天。","p":"对。10 或 11 分就是暂停 90 天。"},"vi":{"q":"Ở District of Columbia, điều gì xảy ra khi người lái xe bị 10 hoặc 11 điểm?","o":["Chỉ nhận thư cảnh cáo","Chỉ phải học một lớp an toàn","Bằng lái bị tạm đình chỉ 90 ngày","Bằng lái bị thu hồi 2 năm"],"h1":"Bạn mất quyền lái xe khoảng ba tháng.","h2":"Ở District of Columbia, người lái xe bị 10 hoặc 11 điểm sẽ bị tạm đình chỉ bằng lái 90 ngày.","p":"Đúng. 10 hoặc 11 điểm nghĩa là bị tạm đình chỉ 90 ngày."},"tl":{"q":"Sa District of Columbia, ano ang mangyayari kapag umabot sa 10 o 11 puntos ang driver?","o":["Isang sulat ng babala lang","Isang required na safety class lang","Masususpinde ang lisensya nang 90 araw","Babawiin ang lisensya nang 2 taon"],"h1":"Mawawala ang karapatan mong magmaneho nang mga tatlong buwan.","h2":"Sa District of Columbia, ang driver na umabot sa 10 o 11 puntos ay masususpinde ang lisensya nang 90 araw.","p":"Tama. Ang 10 o 11 puntos ay 90 araw na suspensyon."},"ar":{"q":"في District of Columbia، ماذا يحدث عندما يصل السائق إلى 10 أو 11 نقطة؟","o":["رسالة تحذير فقط","دورة سلامة إلزامية فقط","تُوقَف الرخصة لمدة 90 يومًا","تُلغى الرخصة لمدة سنتين"],"h1":"تفقد حقك في القيادة لمدة ثلاثة أشهر تقريبًا.","h2":"في District of Columbia السائق الذي يصل إلى 10 أو 11 نقطة تُوقَف رخصته لمدة 90 يومًا.","p":"صحيح. 10 أو 11 نقطة تعني إيقاف الرخصة 90 يومًا."},"ref":{"doc":"DC","page":19}},{"id":"dc-020","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what happens when a driver reaches 12 or more points?","o":["The license is revoked for at least 6 months","The license is suspended for 30 days","The driver pays a fine and keeps driving","The points are removed after a class"],"h1":"This is more serious than a suspension.","h2":"In the District of Columbia, a driver who reaches 12 or more points has the license revoked and cannot get it back for at least six months.","p":"Right. 12 points or more means revocation for at least six months."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa cuando un conductor llega a 12 puntos o más?","o":["Le revocan la licencia por lo menos 6 meses","Le suspenden la licencia por 30 días","Paga una multa y sigue manejando","Le quitan los puntos después de una clase"],"h1":"Es más grave que una suspensión.","h2":"En el Distrito de Columbia, a un conductor que llega a 12 puntos o más le revocan la licencia y no la puede recuperar por lo menos en seis meses.","p":"Correcto. 12 puntos o más significan revocación por lo menos por seis meses."},"zh":{"q":"在 District of Columbia，司机累计到 12 分或更多时，会怎么样？","o":["驾照被吊销至少 6 个月","驾照被暂停 30 天","司机交罚款，可以继续开车","上一门课以后，分数就被取消"],"h1":"这比暂停驾照更严重。","h2":"在 District of Columbia，累计到 12 分或更多的司机，驾照会被吊销，至少六个月不能拿回来。","p":"对。12 分或更多就是吊销驾照至少六个月。"},"vi":{"q":"Ở District of Columbia, điều gì xảy ra khi người lái xe bị 12 điểm trở lên?","o":["Bằng lái bị thu hồi ít nhất 6 tháng","Bằng lái bị tạm đình chỉ 30 ngày","Người lái xe nộp phạt và tiếp tục lái","Điểm bị xóa sau khi học một lớp"],"h1":"Điều này nghiêm trọng hơn tạm đình chỉ.","h2":"Ở District of Columbia, người lái xe bị 12 điểm trở lên sẽ bị thu hồi bằng lái và không thể lấy lại trong ít nhất sáu tháng.","p":"Đúng. 12 điểm trở lên nghĩa là bị thu hồi bằng lái ít nhất sáu tháng."},"tl":{"q":"Sa District of Columbia, ano ang mangyayari kapag umabot sa 12 puntos o higit pa ang driver?","o":["Babawiin ang lisensya nang hindi bababa sa 6 na buwan","Masususpinde ang lisensya nang 30 araw","Magbabayad ng multa ang driver at patuloy na magmamaneho","Matatanggal ang mga puntos pagkatapos ng isang klase"],"h1":"Mas mabigat ito kaysa sa suspensyon.","h2":"Sa District of Columbia, ang driver na umabot sa 12 puntos o higit pa ay babawian ng lisensya at hindi ito makukuha ulit nang hindi bababa sa anim na buwan.","p":"Tama. Ang 12 puntos o higit pa ay pagbawi ng lisensya nang hindi bababa sa anim na buwan."},"ar":{"q":"في District of Columbia، ماذا يحدث عندما يصل السائق إلى 12 نقطة أو أكثر؟","o":["تُلغى الرخصة لمدة 6 أشهر على الأقل","تُوقَف الرخصة لمدة 30 يومًا","يدفع السائق غرامة ويستمر في القيادة","تُحذف النقاط بعد دورة"],"h1":"هذا أشد من إيقاف الرخصة.","h2":"في District of Columbia السائق الذي يصل إلى 12 نقطة أو أكثر تُلغى رخصته ولا يستطيع استعادتها قبل ستة أشهر على الأقل.","p":"صحيح. 12 نقطة أو أكثر تعني إلغاء الرخصة لمدة ستة أشهر على الأقل."},"ref":{"doc":"DC","page":19}},{"id":"dc-021","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how long do points stay active on your driving record?","o":["6 months","1 year","5 years","2 years"],"h1":"It is more than one year, but less than three.","h2":"In the District of Columbia, points stay active on your driving record for two years.","p":"Right. Points stay active for two years."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo siguen activos los puntos en su historial de manejo?","o":["6 meses","1 año","5 años","2 años"],"h1":"Es más de un año, pero menos de tres.","h2":"En el Distrito de Columbia, los puntos siguen activos en su historial de manejo por dos años.","p":"Correcto. Los puntos siguen activos por dos años."},"zh":{"q":"在 District of Columbia，扣分在你的驾驶记录上有效多久？","o":["6 个月","1 年","5 年","2 年"],"h1":"它比一年长，但比三年短。","h2":"在 District of Columbia，扣分在你的驾驶记录上有效两年。","p":"对。扣分有效两年。"},"vi":{"q":"Ở District of Columbia, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn bao lâu?","o":["6 tháng","1 năm","5 năm","2 năm"],"h1":"Nó nhiều hơn một năm, nhưng ít hơn ba năm.","h2":"Ở District of Columbia, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn hai năm.","p":"Đúng. Điểm phạt còn hiệu lực hai năm."},"tl":{"q":"Sa District of Columbia, gaano katagal aktibo ang mga puntos sa iyong driving record?","o":["6 na buwan","1 taon","5 taon","2 taon"],"h1":"Higit ito sa isang taon, pero kulang sa tatlo.","h2":"Sa District of Columbia, aktibo ang mga puntos sa iyong driving record nang dalawang taon.","p":"Tama. Aktibo ang mga puntos nang dalawang taon."},"ar":{"q":"في District of Columbia، كم مدة بقاء النقاط سارية في سجل القيادة الخاص بك؟","o":["6 أشهر","سنة واحدة","5 سنوات","سنتان"],"h1":"هي أكثر من سنة واحدة، لكن أقل من ثلاث سنوات.","h2":"في District of Columbia تبقى النقاط سارية في سجل القيادة الخاص بك لمدة سنتين.","p":"صحيح. تبقى النقاط سارية لمدة سنتين."},"ref":{"doc":"DC","page":19}},{"id":"dc-022","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, a learner permit holder gets 8 points or breaks a GRAD rule. What happens?","o":["Nothing, if no one was hurt","The permit is suspended for 90 days","The permit is extended by one week","The supervisor gets the points instead"],"h1":"The learner loses the permit for about three months.","h2":"In the District of Columbia, a learner permit holder who gets 8 or more points or breaks a GRAD rule has the permit suspended for 90 days and must pay a fee to get it back.","p":"Right. That means a 90-day suspension of the permit."},"es":{"q":"En el Distrito de Columbia, una persona con permiso de aprendiz recibe 8 puntos o no cumple una regla del programa GRAD. ¿Qué pasa?","o":["Nada, si nadie salió herido","Le suspenden el permiso por 90 días","Le alargan el permiso una semana","El supervisor recibe los puntos"],"h1":"El aprendiz pierde el permiso por unos tres meses.","h2":"En el Distrito de Columbia, a una persona con permiso de aprendiz que recibe 8 puntos o más, o que no cumple una regla del programa GRAD, le suspenden el permiso por 90 días y debe pagar una cuota para recuperarlo.","p":"Correcto. Eso significa una suspensión del permiso por 90 días."},"zh":{"q":"在 District of Columbia，持学习驾照的人被扣了 8 分，或者违反了一条 GRAD 规定。会怎么样？","o":["如果没有人受伤，就没事","学习驾照被暂停 90 天","学习驾照延长一个星期","改由监督的人被扣分"],"h1":"学习驾驶的人会失去学习驾照大约三个月。","h2":"在 District of Columbia，持学习驾照的人如果被扣 8 分或更多，或者违反 GRAD 规定，学习驾照会被暂停 90 天，而且要交费才能拿回来。","p":"对。这表示学习驾照被暂停 90 天。"},"vi":{"q":"Ở District of Columbia, người có giấy phép tập lái bị 8 điểm hoặc vi phạm một quy định GRAD. Điều gì xảy ra?","o":["Không có gì, nếu không ai bị thương","Giấy phép tập lái bị tạm đình chỉ 90 ngày","Giấy phép tập lái được gia hạn thêm một tuần","Người giám sát bị trừ điểm thay"],"h1":"Người tập lái mất giấy phép khoảng ba tháng.","h2":"Ở District of Columbia, người có giấy phép tập lái bị 8 điểm trở lên hoặc vi phạm quy định GRAD sẽ bị tạm đình chỉ giấy phép 90 ngày và phải trả phí để lấy lại.","p":"Đúng. Điều đó nghĩa là giấy phép tập lái bị tạm đình chỉ 90 ngày."},"tl":{"q":"Sa District of Columbia, nakakuha ng 8 puntos o lumabag sa isang patakaran ng GRAD ang may hawak ng learner permit. Ano ang mangyayari?","o":["Wala, kung walang nasaktan","Masususpinde ang permit nang 90 araw","Hahabaan ang permit nang isang linggo","Ang gumagabay ang makakakuha ng mga puntos"],"h1":"Mawawala sa nag-aaral ang permit nang mga tatlong buwan.","h2":"Sa District of Columbia, ang may hawak ng learner permit na nakakuha ng 8 puntos o higit pa o lumabag sa patakaran ng GRAD ay masususpinde ang permit nang 90 araw at dapat magbayad ng fee para makuha ito ulit.","p":"Tama. Ibig sabihin nito, 90 araw na suspensyon ng permit."},"ar":{"q":"في District of Columbia، حامل تصريح التعلّم حصل على 8 نقاط أو خالف قاعدة من قواعد GRAD. ماذا يحدث؟","o":["لا شيء، إذا لم يُصَب أحد","يُوقَف التصريح لمدة 90 يومًا","يُمدَّد التصريح أسبوعًا واحدًا","يحصل المشرف على النقاط بدلًا منه"],"h1":"يفقد المتعلم التصريح لمدة ثلاثة أشهر تقريبًا.","h2":"في District of Columbia حامل تصريح التعلّم الذي يحصل على 8 نقاط أو أكثر أو يخالف قاعدة من قواعد GRAD يُوقَف تصريحه لمدة 90 يومًا ويجب أن يدفع رسومًا لاستعادته.","p":"صحيح. هذا يعني إيقاف التصريح لمدة 90 يومًا."},"ref":{"doc":"DC","page":16}},{"id":"dc-023","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the penalty when someone in the car is not wearing a seat belt?","o":["A warning only","A $10 fine and no points","A $50 fine and 2 points","A $500 fine and 6 points"],"h1":"There is a fine and also points on the driver's record.","h2":"In the District of Columbia, the penalty for not wearing a seat belt is a $50 fine and 2 points, and the driver is responsible for every passenger.","p":"Right. A $50 fine and 2 points."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la sanción cuando alguien en el carro no usa el cinturón de seguridad?","o":["Solo una advertencia","Una multa de $10 y ningún punto","Una multa de $50 y 2 puntos","Una multa de $500 y 6 puntos"],"h1":"Hay una multa y también puntos en el historial del conductor.","h2":"En el Distrito de Columbia, la sanción por no usar el cinturón de seguridad es una multa de $50 y 2 puntos, y el conductor es responsable de todos los pasajeros.","p":"Correcto. Una multa de $50 y 2 puntos."},"zh":{"q":"在 District of Columbia，车里有人没有系安全带，会受到什么处罚？","o":["只有警告","罚款 $10，不扣分","罚款 $50，扣 2 分","罚款 $500，扣 6 分"],"h1":"会有罚款，司机的记录上也会被扣分。","h2":"在 District of Columbia，不系安全带的处罚是罚款 $50 并扣 2 分，而且司机要为每一位乘客负责。","p":"对。罚款 $50，扣 2 分。"},"vi":{"q":"Ở District of Columbia, hình phạt là gì khi có người trong xe không thắt dây an toàn?","o":["Chỉ cảnh cáo","Phạt $10 và không bị điểm","Phạt $50 và 2 điểm","Phạt $500 và 6 điểm"],"h1":"Có tiền phạt và cũng có điểm trong hồ sơ của người lái xe.","h2":"Ở District of Columbia, hình phạt cho việc không thắt dây an toàn là phạt $50 và 2 điểm, và người lái xe chịu trách nhiệm cho mọi hành khách.","p":"Đúng. Phạt $50 và 2 điểm."},"tl":{"q":"Sa District of Columbia, ano ang parusa kapag may tao sa kotse na hindi naka-seat belt?","o":["Babala lang","Multang $10 at walang puntos","Multang $50 at 2 puntos","Multang $500 at 6 na puntos"],"h1":"May multa at may puntos din sa record ng driver.","h2":"Sa District of Columbia, ang parusa sa hindi pagsusuot ng seat belt ay multang $50 at 2 puntos, at ang driver ang responsable sa bawat pasahero.","p":"Tama. Multang $50 at 2 puntos."},"ar":{"q":"في District of Columbia، ما العقوبة عندما لا يضع شخص في السيارة حزام الأمان؟","o":["تحذير فقط","غرامة $10 بدون نقاط","غرامة $50 ونقطتان (2)","غرامة $500 و6 نقاط"],"h1":"هناك غرامة وأيضًا نقاط في سجل السائق.","h2":"في District of Columbia عقوبة عدم وضع حزام الأمان هي غرامة $50 ونقطتان (2)، والسائق مسؤول عن كل راكب.","p":"صحيح. غرامة $50 ونقطتان (2)."},"ref":{"doc":"DC","page":48}},{"id":"dc-024","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is true about wearing headphones while you drive?","o":["Headphones for music are not allowed; a phone earpiece or hearing aid is allowed","Headphones are allowed if the volume is low","Headphones are allowed only on the highway","Headphones are allowed in both ears at any time"],"h1":"Think about what could stop you from hearing a siren.","h2":"In the District of Columbia, you may not wear headphones or earplugs connected to a radio or other audio player while driving, but a cell phone earpiece or a hearing aid is allowed.","p":"Right. No music headphones; a phone earpiece or hearing aid is fine."},"es":{"q":"En el Distrito de Columbia, ¿qué es cierto sobre usar audífonos mientras maneja?","o":["Los audífonos para música no se permiten; el audífono del celular o un aparato auditivo sí","Se permiten audífonos si el volumen está bajo","Se permiten audífonos solo en la autopista","Se permiten audífonos en los dos oídos en todo momento"],"h1":"Piense en lo que le podría impedir oír una sirena.","h2":"En el Distrito de Columbia, usted no puede usar audífonos ni tapones conectados a un radio u otro aparato de audio mientras maneja, pero sí puede usar el audífono del celular o un aparato auditivo.","p":"Correcto. Nada de audífonos para música; el del celular o un aparato auditivo sí."},"zh":{"q":"在 District of Columbia，关于开车时戴耳机，哪一项是对的？","o":["不可以戴听音乐的耳机；可以用手机耳塞或助听器","音量小的话可以戴耳机","只有在公路上可以戴耳机","任何时候都可以两只耳朵戴耳机"],"h1":"想一想什么会让你听不到警笛声。","h2":"在 District of Columbia，开车时不可以戴连接收音机或其他播放器的耳机或耳塞，但可以用手机耳塞或助听器。","p":"对。不能戴听音乐的耳机；手机耳塞或助听器可以。"},"vi":{"q":"Ở District of Columbia, điều nào đúng về việc đeo tai nghe khi lái xe?","o":["Không được đeo tai nghe nghe nhạc; được dùng tai nghe điện thoại hoặc máy trợ thính","Được đeo tai nghe nếu âm lượng nhỏ","Chỉ được đeo tai nghe trên đường cao tốc","Được đeo tai nghe cả hai tai bất cứ lúc nào"],"h1":"Hãy nghĩ đến điều gì có thể làm bạn không nghe thấy còi hụ.","h2":"Ở District of Columbia, bạn không được đeo tai nghe hoặc nút tai nối với radio hay máy phát âm thanh khác khi lái xe, nhưng được dùng tai nghe điện thoại di động hoặc máy trợ thính.","p":"Đúng. Không đeo tai nghe nghe nhạc; tai nghe điện thoại hoặc máy trợ thính thì được."},"tl":{"q":"Sa District of Columbia, ano ang totoo tungkol sa pagsusuot ng headphones habang nagmamaneho?","o":["Bawal ang headphones para sa musika; puwede ang earpiece ng phone o hearing aid","Puwede ang headphones kung mahina ang volume","Puwede ang headphones sa highway lang","Puwede ang headphones sa dalawang tainga kahit kailan"],"h1":"Isipin kung ano ang puwedeng pumigil sa iyo na marinig ang sirena.","h2":"Sa District of Columbia, hindi ka puwedeng magsuot ng headphones o earplugs na nakakonekta sa radyo o ibang audio player habang nagmamaneho, pero puwede ang earpiece ng cell phone o hearing aid.","p":"Tama. Bawal ang headphones para sa musika; puwede ang earpiece ng phone o hearing aid."},"ar":{"q":"في District of Columbia، ما الصحيح عن وضع سماعات الرأس أثناء القيادة؟","o":["سماعات الموسيقى غير مسموحة؛ سماعة الهاتف أو جهاز السمع مسموح","السماعات مسموحة إذا كان الصوت منخفضًا","السماعات مسموحة على الطريق السريع فقط","السماعات مسموحة في الأذنين في أي وقت"],"h1":"فكّر في ما قد يمنعك من سماع صفارة الإنذار.","h2":"في District of Columbia لا يجوز لك أثناء القيادة أن تضع سماعات أو سدادات أذن متصلة بالراديو أو بجهاز صوت آخر، لكن سماعة الهاتف المحمول أو جهاز السمع مسموح.","p":"صحيح. لا سماعات للموسيقى؛ سماعة الهاتف أو جهاز السمع لا بأس بهما."},"ref":{"doc":"DC","page":47}},{"id":"dc-025","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, may you turn left on a red light?","o":["Yes, after a full stop","Yes, from a one-way street onto another one-way street","Yes, if no cars are coming","No, a left turn on red is against the law"],"h1":"DC is stricter than many states about this.","h2":"In the District of Columbia, it is against the law to make a left turn on a red light.","p":"Right. In DC you never turn left on red."},"es":{"q":"En el Distrito de Columbia, ¿puede usted girar a la izquierda con la luz roja?","o":["Sí, después de parar por completo","Sí, de una calle de un solo sentido a otra de un solo sentido","Sí, si no vienen carros","No, girar a la izquierda con luz roja es ilegal"],"h1":"DC es más estricto que muchos estados en esto.","h2":"En el Distrito de Columbia, es ilegal girar a la izquierda con la luz roja.","p":"Correcto. En DC nunca se gira a la izquierda con luz roja."},"zh":{"q":"在 District of Columbia，红灯时可以左转吗？","o":["可以，在完全停车以后","可以，从单行道转到另一条单行道","可以，如果没有车来","不可以，红灯左转是违法的"],"h1":"在这一点上，DC 比很多州更严。","h2":"在 District of Columbia，红灯时左转是违法的。","p":"对。在 DC，红灯时永远不能左转。"},"vi":{"q":"Ở District of Columbia, bạn có được rẽ trái khi đèn đỏ không?","o":["Có, sau khi dừng hẳn","Có, từ đường một chiều sang một đường một chiều khác","Có, nếu không có xe đang tới","Không, rẽ trái khi đèn đỏ là phạm luật"],"h1":"Về điều này, DC nghiêm hơn nhiều tiểu bang.","h2":"Ở District of Columbia, rẽ trái khi đèn đỏ là phạm luật.","p":"Đúng. Ở DC, bạn không bao giờ rẽ trái khi đèn đỏ."},"tl":{"q":"Sa District of Columbia, puwede ka bang kumaliwa kapag pula ang ilaw?","o":["Oo, pagkatapos ng buong paghinto","Oo, mula sa one-way na kalye papunta sa isa pang one-way na kalye","Oo, kung walang paparating na sasakyan","Hindi, labag sa batas ang pagkaliwa kapag pula ang ilaw"],"h1":"Mas mahigpit ang DC dito kaysa sa maraming estado.","h2":"Sa District of Columbia, labag sa batas ang kumaliwa kapag pula ang ilaw.","p":"Tama. Sa DC, hindi ka kailanman kumakaliwa kapag pula ang ilaw."},"ar":{"q":"في District of Columbia، هل يجوز لك الانعطاف يسارًا عند الإشارة الحمراء؟","o":["نعم، بعد التوقف التام","نعم، من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","نعم، إذا لم تكن هناك سيارات قادمة","لا، الانعطاف يسارًا عند الإشارة الحمراء مخالف للقانون"],"h1":"DC أشد من ولايات كثيرة في هذا.","h2":"في District of Columbia الانعطاف يسارًا عند الإشارة الحمراء مخالف للقانون.","p":"صحيح. في DC لا تنعطف يسارًا عند الإشارة الحمراء أبدًا."},"ref":{"doc":"DC","page":42}},{"id":"dc-026","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, where is a U-turn against the law?","o":["On any one-way street","At an intersection with traffic lights","On any street with two lanes","Anywhere after dark"],"h1":"Think of intersections controlled by signals.","h2":"In the District of Columbia, U-turns are not allowed at intersections controlled by traffic lights, or on a crosswalk next to one.","p":"Right. No U-turns at intersections with traffic lights."},"es":{"q":"En el Distrito de Columbia, ¿dónde es ilegal dar una vuelta en U?","o":["En cualquier calle de un solo sentido","En una intersección con semáforo","En cualquier calle de dos carriles","En cualquier lugar de noche"],"h1":"Piense en las intersecciones controladas por señales.","h2":"En el Distrito de Columbia, no se permiten las vueltas en U en intersecciones controladas por semáforos, ni en el cruce peatonal junto a ellas.","p":"Correcto. Nada de vueltas en U en intersecciones con semáforo."},"zh":{"q":"在 District of Columbia，在哪里掉头是违法的？","o":["在任何单行道上","在有红绿灯的路口","在任何有两条车道的街道上","天黑以后在任何地方"],"h1":"想一想由信号灯控制的路口。","h2":"在 District of Columbia，不可以在由红绿灯控制的路口掉头，也不可以在这种路口旁边的人行横道上掉头。","p":"对。有红绿灯的路口不能掉头。"},"vi":{"q":"Ở District of Columbia, quay đầu xe (U-turn) ở đâu là phạm luật?","o":["Trên bất kỳ đường một chiều nào","Tại giao lộ có đèn giao thông","Trên bất kỳ đường nào có hai làn","Ở bất cứ đâu sau khi trời tối"],"h1":"Hãy nghĩ đến các giao lộ được điều khiển bằng đèn tín hiệu.","h2":"Ở District of Columbia, không được quay đầu xe tại giao lộ có đèn giao thông điều khiển, hoặc trên vạch qua đường dành cho người đi bộ bên cạnh giao lộ đó.","p":"Đúng. Không quay đầu xe tại giao lộ có đèn giao thông."},"tl":{"q":"Sa District of Columbia, saan labag sa batas ang U-turn?","o":["Sa anumang one-way na kalye","Sa interseksyon na may traffic light","Sa anumang kalye na may dalawang lane","Kahit saan pagkagabi"],"h1":"Isipin ang mga interseksyon na kontrolado ng mga signal.","h2":"Sa District of Columbia, bawal ang U-turn sa mga interseksyon na kontrolado ng traffic light, o sa tawiran ng tao na katabi nito.","p":"Tama. Bawal ang U-turn sa mga interseksyon na may traffic light."},"ar":{"q":"في District of Columbia، أين يكون الدوران للخلف (U-turn) مخالفًا للقانون؟","o":["في أي شارع باتجاه واحد","عند تقاطع فيه إشارات مرور","في أي شارع فيه مساران","في أي مكان بعد حلول الظلام"],"h1":"فكّر في التقاطعات التي تنظمها الإشارات.","h2":"في District of Columbia لا يجوز الدوران للخلف عند التقاطعات التي تنظمها إشارات المرور، ولا على ممر المشاة الذي بجانب تقاطع كهذا.","p":"صحيح. لا دوران للخلف عند التقاطعات التي فيها إشارات مرور."},"ref":{"doc":"DC","page":47}},{"id":"dc-027","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, how close to a fire hydrant may you stand or park?","o":["Up to 5 feet away","No closer than 10 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"The District uses a shorter distance than many states.","h2":"In the District of Columbia, you may not stand or park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia de un hidrante puede detenerse o estacionarse?","o":["Hasta 5 pies de distancia","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"El Distrito usa una distancia más corta que muchos estados.","h2":"En el Distrito de Columbia, usted no puede detenerse ni estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 District of Columbia，你可以在离消防栓多近的地方停车或临时停靠？","o":["最近 5 英尺","不能少于 10 英尺","不能少于 25 英尺","不能少于 50 英尺"],"h1":"DC 用的距离比很多州短。","h2":"在 District of Columbia，你不能在离消防栓 10 英尺以内的地方停车或临时停靠。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở District of Columbia (DC), bạn được dừng hoặc đỗ xe gần trụ cứu hỏa đến mức nào?","o":["Cách tối đa 5 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"DC dùng khoảng cách ngắn hơn nhiều tiểu bang khác.","h2":"Ở District of Columbia, bạn không được dừng hoặc đỗ xe trong vòng 10 feet tính từ trụ cứu hỏa.","p":"Đúng. Hãy cách trụ cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa District of Columbia (DC), gaano kalapit sa fire hydrant ka puwedeng huminto o pumarada?","o":["Hanggang 5 talampakan ang layo","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas maikli ang layong ginagamit ng DC kaysa sa maraming estado.","h2":"Sa District of Columbia, hindi ka puwedeng huminto o pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan sa hydrant."},"ar":{"q":"في District of Columbia (DC)، كم يمكنك أن تقترب من صنبور إطفاء الحريق عند التوقف أو الركن؟","o":["حتى 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تستخدم DC مسافة أقصر من ولايات كثيرة.","h2":"في District of Columbia لا يجوز لك التوقف أو الركن على بُعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 10 أقدام على الأقل من صنبور الإطفاء."},"ref":{"doc":"DC","page":44}},{"id":"dc-028","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the rule when you pass a bicyclist?","o":["Honk first so the rider knows you are there","Leave at least 1 foot of space","Leave at least 3 feet and do not use your horn","Pass only on the right"],"h1":"A loud noise can startle a rider.","h2":"In the District of Columbia, you must leave at least three feet of space when passing a bicyclist, and you should not use your horn.","p":"Right. Leave 3 feet and do not honk."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la regla al rebasar a un ciclista?","o":["Tocar la bocina primero para avisarle","Dejar por lo menos 1 pie de espacio","Dejar por lo menos 3 pies y no tocar la bocina","Rebasar solo por la derecha"],"h1":"Un ruido fuerte puede asustar al ciclista.","h2":"En el Distrito de Columbia, debe dejar por lo menos tres pies de espacio al rebasar a un ciclista, y no debe tocar la bocina.","p":"Correcto. Deje 3 pies y no toque la bocina."},"zh":{"q":"在 District of Columbia，超过骑自行车的人时，规定是什么？","o":["先按喇叭，让骑车人知道你在那里","至少留出 1 英尺的空间","至少留出 3 英尺，而且不要按喇叭","只能从右边超车"],"h1":"很大的声音会吓到骑车人。","h2":"在 District of Columbia，超过骑自行车的人时，你必须至少留出 3 英尺的空间，而且不应该按喇叭。","p":"对。留出 3 英尺，不要按喇叭。"},"vi":{"q":"Ở District of Columbia (DC), quy định là gì khi bạn vượt người đi xe đạp?","o":["Bấm còi trước để người đạp xe biết bạn ở đó","Chừa ít nhất 1 foot khoảng trống","Chừa ít nhất 3 feet và không bấm còi","Chỉ vượt bên phải"],"h1":"Tiếng động lớn có thể làm người đạp xe giật mình.","h2":"Ở District of Columbia, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng trống và không nên bấm còi.","p":"Đúng. Chừa 3 feet và không bấm còi."},"tl":{"q":"Sa District of Columbia (DC), ano ang patakaran kapag nilalampasan mo ang nagbibisikleta?","o":["Bumusina muna para malaman ng siklista na nandiyan ka","Mag-iwan ng hindi bababa sa 1 talampakang espasyo","Mag-iwan ng hindi bababa sa 3 talampakan at huwag bumusina","Lumampas lang sa kanan"],"h1":"Puwedeng magulat ang siklista sa malakas na ingay.","h2":"Sa District of Columbia, kapag nilalampasan mo ang nagbibisikleta, dapat kang mag-iwan ng hindi bababa sa 3 talampakang espasyo, at hindi ka dapat bumusina.","p":"Tama. Mag-iwan ng 3 talampakan at huwag bumusina."},"ar":{"q":"في District of Columbia (DC)، ما القاعدة عندما تتجاوز راكب دراجة هوائية؟","o":["اضغط على البوق أولًا ليعرف الراكب أنك هناك","اترك مسافة قدم واحدة (1) على الأقل","اترك 3 أقدام على الأقل ولا تستخدم البوق","تجاوز من اليمين فقط"],"h1":"الصوت العالي قد يُفزع راكب الدراجة.","h2":"في District of Columbia يجب أن تترك مسافة 3 أقدام على الأقل عندما تتجاوز راكب دراجة هوائية، ولا ينبغي أن تستخدم البوق.","p":"صحيح. اترك 3 أقدام ولا تستخدم البوق."},"ref":{"doc":"DC","page":41}},{"id":"dc-029","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, how close to the curb must you be when you parallel park?","o":["Within 12 inches","Within 24 inches","Within 3 feet","Touching the curb"],"h1":"The distance is about one foot.","h2":"In the District of Columbia, when you parallel park you must be parallel to the curb and within 12 inches of it.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En el Distrito de Columbia, ¿qué tan cerca de la acera debe quedar al estacionarse en paralelo?","o":["A 12 pulgadas o menos","A 24 pulgadas o menos","A 3 pies o menos","Tocando la acera"],"h1":"La distancia es de más o menos un pie.","h2":"En el Distrito de Columbia, al estacionarse en paralelo debe quedar paralelo a la acera y a no más de 12 pulgadas de ella.","p":"Correcto. Estaciónese a 12 pulgadas o menos de la acera."},"zh":{"q":"在 District of Columbia，平行停车时，你必须离路缘多近？","o":["12 英寸以内","24 英寸以内","3 英尺以内","贴着路缘"],"h1":"这个距离大约是 1 英尺。","h2":"在 District of Columbia，平行停车时，你必须和路缘平行，并且离路缘 12 英寸以内。","p":"对。停车时离路缘 12 英寸以内。"},"vi":{"q":"Ở District of Columbia (DC), khi đỗ xe song song, bạn phải cách lề đường bao xa?","o":["Trong vòng 12 inch","Trong vòng 24 inch","Trong vòng 3 feet","Chạm vào lề đường"],"h1":"Khoảng cách này khoảng 1 foot.","h2":"Ở District of Columbia, khi đỗ xe song song, bạn phải đỗ song song với lề đường và cách lề đường trong vòng 12 inch.","p":"Đúng. Đỗ xe cách lề đường trong vòng 12 inch."},"tl":{"q":"Sa District of Columbia (DC), gaano kalapit sa gilid ng bangketa (curb) ka dapat kapag nag-parallel park ka?","o":["Sa loob ng 12 pulgada","Sa loob ng 24 pulgada","Sa loob ng 3 talampakan","Nakadikit sa curb"],"h1":"Mga isang talampakan ang layo.","h2":"Sa District of Columbia, kapag nag-parallel park ka, dapat ay kahanay ka ng curb at nasa loob ng 12 pulgada mula rito.","p":"Tama. Pumarada sa loob ng 12 pulgada mula sa curb."},"ar":{"q":"في District of Columbia (DC)، كم يجب أن تكون قريبًا من الرصيف عند الركن الموازي؟","o":["في حدود 12 بوصة","في حدود 24 بوصة","في حدود 3 أقدام","ملامسًا للرصيف"],"h1":"المسافة نحو قدم واحدة تقريبًا.","h2":"في District of Columbia يجب عند الركن الموازي أن تكون موازيًا للرصيف وعلى بُعد 12 بوصة منه أو أقل.","p":"صحيح. اركن على بُعد 12 بوصة أو أقل من الرصيف."},"ref":{"doc":"DC","page":43}},{"id":"dc-030","scope":"DC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the District of Columbia, where is it legal to pass another vehicle on the right?","o":["On any two-lane road","On the shoulder of any road","Only at night","On a one-way road with room for more than one line of traffic"],"h1":"Think of roads where all traffic goes the same way.","h2":"In the District of Columbia, you may pass on the left or right on a one-way road with room for more than one line of traffic, and on highways with four or more lanes.","p":"Right. One-way roads with more than one lane allow passing on either side."},"es":{"q":"En el Distrito de Columbia, ¿dónde es legal rebasar a otro vehículo por la derecha?","o":["En cualquier vía de dos carriles","Por el acotamiento de cualquier vía","Solo de noche","En una vía de un solo sentido con espacio para más de una fila de tráfico"],"h1":"Piense en las vías donde todo el tráfico va en la misma dirección.","h2":"En el Distrito de Columbia, puede rebasar por la izquierda o por la derecha en una vía de un solo sentido con espacio para más de una fila de tráfico, y en carreteras de cuatro carriles o más.","p":"Correcto. En vías de un solo sentido con más de un carril se puede rebasar por cualquier lado."},"zh":{"q":"在 District of Columbia，在哪里从右边超车是合法的？","o":["在任何双车道道路上","在任何道路的路肩上","只在晚上","在有足够空间容纳多于一列车流的单行道上"],"h1":"想一想所有车都往同一个方向开的道路。","h2":"在 District of Columbia，在有足够空间容纳多于一列车流的单行道上，以及在有 4 条或更多车道的公路上，你可以从左边或右边超车。","p":"对。有多于一条车道的单行道，可以从任一边超车。"},"vi":{"q":"Ở District of Columbia (DC), ở đâu thì được phép vượt xe khác bên phải?","o":["Trên bất kỳ đường hai làn nào","Trên lề của bất kỳ con đường nào","Chỉ vào ban đêm","Trên đường một chiều có đủ chỗ cho hơn một hàng xe"],"h1":"Hãy nghĩ đến những con đường mà mọi xe đều đi cùng một hướng.","h2":"Ở District of Columbia, bạn được vượt bên trái hoặc bên phải trên đường một chiều có đủ chỗ cho hơn một hàng xe, và trên xa lộ có 4 làn trở lên.","p":"Đúng. Đường một chiều có hơn một làn cho phép vượt ở cả hai bên."},"tl":{"q":"Sa District of Columbia (DC), saan legal na lampasan ang ibang sasakyan sa kanan?","o":["Sa kahit anong kalsadang may dalawang lane","Sa shoulder ng kahit anong kalsada","Sa gabi lang","Sa one-way na kalsadang may espasyo para sa higit sa isang hanay ng sasakyan"],"h1":"Isipin ang mga kalsada kung saan iisang direksyon ang takbo ng lahat ng sasakyan.","h2":"Sa District of Columbia, puwede kang lumampas sa kaliwa o sa kanan sa one-way na kalsadang may espasyo para sa higit sa isang hanay ng sasakyan, at sa mga highway na may 4 o higit pang lane.","p":"Tama. Sa one-way na kalsadang may higit sa isang lane, puwedeng lumampas sa alinmang gilid."},"ar":{"q":"في District of Columbia (DC)، أين يجوز قانونًا أن تتجاوز مركبة أخرى من اليمين؟","o":["على أي طريق بمسارين","على كتف أي طريق","في الليل فقط","على طريق باتجاه واحد فيه مكان لأكثر من صف واحد من السيارات"],"h1":"فكّر في الطرق التي تسير فيها كل السيارات في الاتجاه نفسه.","h2":"في District of Columbia يجوز لك التجاوز من اليسار أو من اليمين على طريق باتجاه واحد فيه مكان لأكثر من صف واحد من السيارات، وعلى الطرق السريعة التي فيها 4 مسارات أو أكثر.","p":"صحيح. على الطرق ذات الاتجاه الواحد وأكثر من مسار يجوز التجاوز من أي جانب."},"ref":{"doc":"DC","page":41}},{"id":"dc-031","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, when must you turn on your headlights?","o":["Only after midnight","Whenever your windshield wipers are on","Only on highways","Only when it snows"],"h1":"Think about rain.","h2":"In the District of Columbia, you must turn on your headlights whenever your windshield wipers are on, and also in tunnels and from half an hour after sunset to half an hour before sunrise.","p":"Right. Wipers on means headlights on."},"es":{"q":"En el Distrito de Columbia, ¿cuándo debe encender los faros?","o":["Solo después de medianoche","Siempre que tenga los limpiaparabrisas encendidos","Solo en las carreteras","Solo cuando nieva"],"h1":"Piense en la lluvia.","h2":"En el Distrito de Columbia, debe encender los faros siempre que tenga los limpiaparabrisas encendidos, y también en los túneles y desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Limpiaparabrisas encendidos significa faros encendidos."},"zh":{"q":"在 District of Columbia，你什么时候必须打开车头灯？","o":["只在半夜以后","每次打开雨刷的时候","只在公路上","只在下雪的时候"],"h1":"想一想下雨的时候。","h2":"在 District of Columbia，每次打开雨刷时你都必须打开车头灯；在隧道里，以及从日落后半小时到日出前半小时，也必须打开车头灯。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở District of Columbia (DC), khi nào bạn phải bật đèn pha?","o":["Chỉ sau nửa đêm","Bất cứ khi nào cần gạt nước đang bật","Chỉ trên xa lộ","Chỉ khi có tuyết"],"h1":"Hãy nghĩ đến lúc trời mưa.","h2":"Ở District of Columbia, bạn phải bật đèn pha bất cứ khi nào cần gạt nước đang bật, và cũng phải bật trong đường hầm và từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa District of Columbia (DC), kailan mo dapat buksan ang headlights mo?","o":["Pagkalipas lang ng hatinggabi","Tuwing nakabukas ang windshield wipers mo","Sa mga highway lang","Kapag umuulan lang ng niyebe"],"h1":"Isipin ang ulan.","h2":"Sa District of Columbia, dapat mong buksan ang headlights mo tuwing nakabukas ang windshield wipers mo, at gayundin sa mga tunnel at mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Kapag nakabukas ang wipers, nakabukas din ang headlights."},"ar":{"q":"في District of Columbia (DC)، متى يجب أن تشغّل المصابيح الأمامية؟","o":["بعد منتصف الليل فقط","كلما كانت مسّاحات الزجاج الأمامي تعمل","على الطرق السريعة فقط","عندما يتساقط الثلج فقط"],"h1":"فكّر في المطر.","h2":"في District of Columbia يجب أن تشغّل المصابيح الأمامية كلما كانت مسّاحات الزجاج الأمامي تعمل، وكذلك في الأنفاق، ومن نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. إذا عملت المسّاحات فشغّل المصابيح الأمامية."},"ref":{"doc":"DC","page":42}},{"id":"dc-032","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, you move to the District with a license from another place. How soon must you get a DC driver license?","o":["Within 10 days","Within 60 days","Within 6 months","Within 1 year"],"h1":"It is about two months.","h2":"In the District of Columbia, a new resident must get a DC driver license within 60 days of moving there.","p":"Right. New residents have 60 days to get a DC license."},"es":{"q":"En el Distrito de Columbia, usted se muda al Distrito con una licencia de otro lugar. ¿En cuánto tiempo debe sacar una licencia de DC?","o":["En 10 días","En 60 días","En 6 meses","En 1 año"],"h1":"Son unos dos meses.","h2":"En el Distrito de Columbia, un nuevo residente debe sacar una licencia de conducir de DC dentro de los 60 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 60 días para sacar una licencia de DC."},"zh":{"q":"在 District of Columbia，你带着其他地方的驾照搬到 DC。你必须多快拿到 DC 驾照？","o":["10 天内","60 天内","6 个月内","1 年内"],"h1":"大约是两个月。","h2":"在 District of Columbia，新居民必须在搬来后 60 天内拿到 DC 驾照。","p":"对。新居民有 60 天时间拿到 DC 驾照。"},"vi":{"q":"Ở District of Columbia, bạn chuyển đến DC với bằng lái của nơi khác. Bạn phải lấy bằng lái DC trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 60 ngày","Trong vòng 6 tháng","Trong vòng 1 năm"],"h1":"Khoảng hai tháng.","h2":"Ở District of Columbia, cư dân mới phải lấy bằng lái DC trong vòng 60 ngày sau khi chuyển đến.","p":"Đúng. Cư dân mới có 60 ngày để lấy bằng lái DC."},"tl":{"q":"Sa District of Columbia, lumipat ka sa DC na may lisensya mula sa ibang lugar. Gaano kabilis ka dapat kumuha ng DC driver license?","o":["Sa loob ng 10 araw","Sa loob ng 60 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa District of Columbia, dapat kumuha ang bagong residente ng DC driver license sa loob ng 60 araw mula nang lumipat siya roon.","p":"Tama. May 60 araw ang bagong residente para kumuha ng DC license."},"ar":{"q":"في District of Columbia، انتقلت إلى DC ومعك رخصة من مكان آخر. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من DC؟","o":["خلال 10 أيام","خلال 60 يومًا","خلال 6 أشهر","خلال سنة واحدة (1)"],"h1":"المدة شهران تقريبًا.","h2":"في District of Columbia يجب على المقيم الجديد أن يحصل على رخصة قيادة من DC خلال 60 يومًا من انتقاله إليها.","p":"صحيح. لدى المقيم الجديد 60 يومًا للحصول على رخصة DC."},"ref":{"doc":"DC","page":11}},{"id":"dc-033","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 5 days","Within 10 days","Within 1 year","Within 60 days"],"h1":"It is the same length of time a new resident has to get a license.","h2":"In the District of Columbia, residents must update their address with the DMV within 60 days.","p":"Right. Update your address within 60 days."},"es":{"q":"En el Distrito de Columbia, usted se muda a una casa nueva. ¿En cuánto tiempo debe darle su nueva dirección al DMV?","o":["En 5 días","En 10 días","En 1 año","En 60 días"],"h1":"Es el mismo tiempo que tiene un nuevo residente para sacar la licencia.","h2":"En el Distrito de Columbia, los residentes deben actualizar su dirección con el DMV dentro de los 60 días.","p":"Correcto. Actualice su dirección dentro de los 60 días."},"zh":{"q":"在 District of Columbia，你搬了新家。你必须多快把新地址告诉 DMV？","o":["5 天内","10 天内","1 年内","60 天内"],"h1":"它和新居民拿驾照的时间一样长。","h2":"在 District of Columbia，居民必须在 60 天内向 DMV 更新地址。","p":"对。60 天内更新你的地址。"},"vi":{"q":"Ở District of Columbia, bạn chuyển đến nhà mới. Bạn phải báo địa chỉ mới cho DMV trong bao lâu?","o":["Trong vòng 5 ngày","Trong vòng 10 ngày","Trong vòng 1 năm","Trong vòng 60 ngày"],"h1":"Đó là cùng thời gian mà cư dân mới có để lấy bằng lái.","h2":"Ở District of Columbia, cư dân phải cập nhật địa chỉ với DMV trong vòng 60 ngày.","p":"Đúng. Hãy cập nhật địa chỉ trong vòng 60 ngày."},"tl":{"q":"Sa District of Columbia, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihin sa DMV ang bago mong address?","o":["Sa loob ng 5 araw","Sa loob ng 10 araw","Sa loob ng 1 taon","Sa loob ng 60 araw"],"h1":"Pareho ito sa tagal na mayroon ang bagong residente para kumuha ng lisensya.","h2":"Sa District of Columbia, dapat i-update ng mga residente ang kanilang address sa DMV sa loob ng 60 araw.","p":"Tama. I-update ang address mo sa loob ng 60 araw."},"ar":{"q":"في District of Columbia، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ DMV بعنوانك الجديد؟","o":["خلال 5 أيام","خلال 10 أيام","خلال سنة واحدة (1)","خلال 60 يومًا"],"h1":"هي نفس المدة التي لدى المقيم الجديد للحصول على رخصة.","h2":"في District of Columbia يجب على المقيمين تحديث عنوانهم لدى DMV خلال 60 يومًا.","p":"صحيح. حدّث عنوانك خلال 60 يومًا."},"ref":{"doc":"DC","page":19}},{"id":"dc-034","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, your driver license has been expired for more than 545 days. What must you do to get it back?","o":["Pass both the knowledge test and the road skills test","Only pay a late fee","Only pass a vision screening","Only take an online traffic school course"],"h1":"After this long, the DMV wants to see both what you know and how you drive.","h2":"In the District of Columbia, if your license has been expired for more than 545 days, you must pass both the knowledge test and the road skills test.","p":"Right. After 545 days, you take both tests again."},"es":{"q":"En el Distrito de Columbia, su licencia lleva más de 545 días vencida. ¿Qué debe hacer para recuperarla?","o":["Aprobar el examen de conocimientos y el examen de manejo","Solo pagar un recargo","Solo pasar el examen de la vista","Solo tomar un curso de manejo en línea"],"h1":"Después de tanto tiempo, el DMV quiere ver lo que usted sabe y cómo maneja.","h2":"En el Distrito de Columbia, si su licencia lleva más de 545 días vencida, debe aprobar el examen de conocimientos y el examen de manejo.","p":"Correcto. Después de 545 días, se toman los dos exámenes otra vez."},"zh":{"q":"在 District of Columbia，你的驾照已经过期超过 545 天。你必须做什么才能拿回驾照？","o":["笔试和路考都要通过","只交滞纳金","只通过视力检查","只上一门网上交通学校课程"],"h1":"过了这么久，DMV 想看你懂多少，也想看你怎么开车。","h2":"在 District of Columbia，如果你的驾照过期超过 545 天，你必须通过笔试和路考。","p":"对。过了 545 天，两个考试都要重新考。"},"vi":{"q":"Ở District of Columbia, bằng lái của bạn đã hết hạn hơn 545 ngày. Bạn phải làm gì để lấy lại?","o":["Thi đậu cả bài thi lý thuyết và bài thi lái xe trên đường","Chỉ trả phí trễ hạn","Chỉ kiểm tra thị lực","Chỉ học một khóa trường luật giao thông trực tuyến"],"h1":"Sau thời gian lâu như vậy, DMV muốn xem cả kiến thức lẫn cách bạn lái xe.","h2":"Ở District of Columbia, nếu bằng lái của bạn đã hết hạn hơn 545 ngày, bạn phải thi đậu cả bài thi lý thuyết và bài thi lái xe trên đường.","p":"Đúng. Sau 545 ngày, bạn phải thi lại cả hai bài."},"tl":{"q":"Sa District of Columbia, expired na ang driver license mo nang higit sa 545 araw. Ano ang dapat mong gawin para makuha ito ulit?","o":["Pumasa sa knowledge test at sa road skills test","Magbayad lang ng late fee","Pumasa lang sa vision screening","Kumuha lang ng online na kurso sa traffic school"],"h1":"Pagkatapos ng ganito katagal, gusto ng DMV na makita ang alam mo at kung paano ka magmaneho.","h2":"Sa District of Columbia, kung expired na ang lisensya mo nang higit sa 545 araw, dapat kang pumasa sa knowledge test at sa road skills test.","p":"Tama. Pagkalipas ng 545 araw, kukunin mo ulit ang dalawang test."},"ar":{"q":"في District of Columbia، انتهت صلاحية رخصة القيادة الخاصة بك منذ أكثر من 545 يومًا. ماذا يجب أن تفعل لاستعادتها؟","o":["أن تنجح في الاختبار النظري واختبار القيادة على الطريق معًا","أن تدفع رسوم تأخير فقط","أن تجتاز فحص النظر فقط","أن تأخذ دورة مدرسة مرور على الإنترنت فقط"],"h1":"بعد كل هذه المدة يريد DMV أن يرى ما تعرفه وكيف تقود.","h2":"في District of Columbia إذا انتهت صلاحية رخصتك منذ أكثر من 545 يومًا، يجب أن تنجح في الاختبار النظري واختبار القيادة على الطريق معًا.","p":"صحيح. بعد 545 يومًا تعيد الاختبارين كليهما."},"ref":{"doc":"DC","page":12}},{"id":"dc-035","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, you will be 70 or older when your license expires. What extra step do you need to renew it?","o":["Retake the road skills test every year","Drive only in daylight","Have your doctor fill out the Mature Driver section of the application","Get a new learner permit first"],"h1":"A medical professional must say you can still drive safely.","h2":"In the District of Columbia, a driver who is 70 or older when the license expires must have a doctor complete the Mature Driver section of the application.","p":"Right. At 70 and up, your doctor signs the Mature Driver section."},"es":{"q":"En el Distrito de Columbia, usted tendrá 70 años o más cuando venza su licencia. ¿Qué paso adicional necesita para renovarla?","o":["Repetir el examen de manejo cada año","Manejar solo de día","Pedirle a su médico que llene la sección de Conductor Mayor de la solicitud","Sacar primero un nuevo permiso de aprendiz"],"h1":"Un profesional de la salud debe decir que usted todavía puede manejar con seguridad.","h2":"En el Distrito de Columbia, un conductor que tenga 70 años o más cuando venza su licencia debe pedirle a un médico que llene la sección de Conductor Mayor de la solicitud.","p":"Correcto. A partir de los 70, su médico firma la sección de Conductor Mayor."},"zh":{"q":"在 District of Columbia，你的驾照到期时你将满 70 岁或以上。续期需要多做哪一步？","o":["每年重新考一次路考","只在白天开车","请你的医生填写申请表上的 Mature Driver 部分","先重新拿一个学习驾照"],"h1":"必须由医疗人员说明你还能安全开车。","h2":"在 District of Columbia，驾照到期时满 70 岁或以上的司机，必须请医生填写申请表上的 Mature Driver 部分。","p":"对。70 岁以上，要请医生签 Mature Driver 部分。"},"vi":{"q":"Ở District of Columbia, bạn sẽ 70 tuổi trở lên khi bằng lái hết hạn. Bạn cần làm thêm bước nào để gia hạn?","o":["Thi lại bài thi lái xe trên đường mỗi năm","Chỉ lái xe ban ngày","Nhờ bác sĩ điền phần Mature Driver trong đơn","Lấy giấy phép tập lái mới trước"],"h1":"Một nhân viên y tế phải xác nhận bạn vẫn lái xe an toàn được.","h2":"Ở District of Columbia, người lái xe 70 tuổi trở lên khi bằng lái hết hạn phải nhờ bác sĩ điền phần Mature Driver trong đơn.","p":"Đúng. Từ 70 tuổi trở lên, bác sĩ của bạn ký phần Mature Driver."},"tl":{"q":"Sa District of Columbia, ikaw ay 70 taong gulang o higit pa kapag nag-expire ang lisensya mo. Anong dagdag na hakbang ang kailangan para ma-renew ito?","o":["Kunin ulit ang road skills test taon-taon","Magmaneho lang sa araw","Ipasagot sa doktor mo ang Mature Driver section ng application","Kumuha muna ng bagong learner permit"],"h1":"Dapat sabihin ng isang medical professional na kaya mo pang magmaneho nang ligtas.","h2":"Sa District of Columbia, ang driver na 70 taong gulang o higit pa kapag nag-expire ang lisensya ay dapat ipasagot sa doktor ang Mature Driver section ng application.","p":"Tama. Sa edad na 70 pataas, pipirmahan ng doktor mo ang Mature Driver section."},"ar":{"q":"في District of Columbia، سيكون عمرك 70 سنة أو أكثر عند انتهاء صلاحية رخصتك. ما الخطوة الإضافية التي تحتاجها لتجديدها؟","o":["أن تعيد اختبار القيادة على الطريق كل سنة","أن تقود في النهار فقط","أن يملأ طبيبك قسم Mature Driver في الطلب","أن تحصل على تصريح تعلّم جديد أولًا"],"h1":"يجب أن يقول مختص طبي إنك ما زلت تستطيع القيادة بأمان.","h2":"في District of Columbia السائق الذي يكون عمره 70 سنة أو أكثر عند انتهاء صلاحية رخصته يجب أن يملأ طبيبه قسم Mature Driver في الطلب.","p":"صحيح. من عمر 70 فما فوق يوقّع طبيبك قسم Mature Driver."},"ref":{"doc":"DC","page":12}},{"id":"dc-036","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you fail the road skills test. How long must you wait before you take it again?","o":["You may retake it the same day","24 hours","30 days","72 hours"],"h1":"It is three days, counted in hours.","h2":"In the District of Columbia, after you fail the road skills test, you must wait 72 hours before you may take it again.","p":"Right. Wait 72 hours before the next road test."},"es":{"q":"En el Distrito de Columbia, usted no aprueba el examen de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Puede repetirlo el mismo día","24 horas","30 días","72 horas"],"h1":"Son tres días, contados en horas.","h2":"En el Distrito de Columbia, si no aprueba el examen de manejo, debe esperar 72 horas antes de tomarlo otra vez.","p":"Correcto. Espere 72 horas antes del próximo examen de manejo."},"zh":{"q":"在 District of Columbia，你路考没有通过。你必须等多久才能再考？","o":["你当天就可以再考","24 小时","30 天","72 小时"],"h1":"是三天，用小时来算。","h2":"在 District of Columbia，路考没有通过后，你必须等 72 小时才能再考。","p":"对。等 72 小时再考下一次路考。"},"vi":{"q":"Ở District of Columbia, bạn thi trượt bài thi lái xe trên đường. Bạn phải chờ bao lâu trước khi thi lại?","o":["Bạn có thể thi lại ngay trong ngày","24 giờ","30 ngày","72 giờ"],"h1":"Đó là ba ngày, tính bằng giờ.","h2":"Ở District of Columbia, sau khi thi trượt bài thi lái xe trên đường, bạn phải chờ 72 giờ trước khi được thi lại.","p":"Đúng. Hãy chờ 72 giờ trước lần thi lái xe tiếp theo."},"tl":{"q":"Sa District of Columbia, bumagsak ka sa road skills test. Gaano katagal ka dapat maghintay bago kumuha ulit nito?","o":["Puwede mo itong kunin ulit sa parehong araw","24 na oras","30 araw","72 oras"],"h1":"Tatlong araw ito, binilang sa oras.","h2":"Sa District of Columbia, pagkatapos mong bumagsak sa road skills test, dapat kang maghintay ng 72 oras bago ka puwedeng kumuha ulit nito.","p":"Tama. Maghintay ng 72 oras bago ang susunod na road test."},"ar":{"q":"في District of Columbia، رسبت في اختبار القيادة على الطريق. كم يجب أن تنتظر قبل أن تعيده؟","o":["يمكنك أن تعيده في نفس اليوم","24 ساعة","30 يومًا","72 ساعة"],"h1":"هي ثلاثة أيام، محسوبة بالساعات.","h2":"في District of Columbia بعد أن ترسب في اختبار القيادة على الطريق يجب أن تنتظر 72 ساعة قبل أن يُسمح لك بإعادته.","p":"صحيح. انتظر 72 ساعة قبل اختبار الطريق التالي."},"ref":{"doc":"DC","page":13}},{"id":"dc-037","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what happens if you do not cancel your road skills test at least two business days ahead?","o":["You lose your learner permit","You pay a $30 cancellation fee","You must wait one year to test","Nothing happens"],"h1":"It costs you money.","h2":"In the District of Columbia, if you do not cancel a road skills test at least two business days ahead, you are charged a $30 cancellation fee.","p":"Right. A late cancel costs $30."},"es":{"q":"En el Distrito de Columbia, ¿qué pasa si no cancela su examen de manejo con por lo menos dos días hábiles de anticipación?","o":["Pierde su permiso de aprendiz","Paga un cargo de cancelación de $30","Debe esperar un año para el examen","No pasa nada"],"h1":"Le cuesta dinero.","h2":"En el Distrito de Columbia, si no cancela el examen de manejo con por lo menos dos días hábiles de anticipación, se le cobra un cargo de cancelación de $30.","p":"Correcto. Cancelar tarde cuesta $30."},"zh":{"q":"在 District of Columbia，如果你没有至少提前两个工作日取消路考，会怎么样？","o":["你会失去学习驾照","你要付 $30 的取消费","你必须等一年才能考试","什么事都不会发生"],"h1":"你要花钱。","h2":"在 District of Columbia，如果你没有至少提前两个工作日取消路考，你会被收 $30 的取消费。","p":"对。太晚取消要付 $30。"},"vi":{"q":"Ở District of Columbia, điều gì xảy ra nếu bạn không hủy bài thi lái xe trên đường trước ít nhất hai ngày làm việc?","o":["Bạn mất giấy phép tập lái","Bạn phải trả phí hủy $30","Bạn phải chờ một năm mới được thi","Không có gì xảy ra"],"h1":"Bạn sẽ mất tiền.","h2":"Ở District of Columbia, nếu bạn không hủy bài thi lái xe trên đường trước ít nhất hai ngày làm việc, bạn bị tính phí hủy $30.","p":"Đúng. Hủy trễ sẽ mất $30."},"tl":{"q":"Sa District of Columbia, ano ang mangyayari kung hindi mo kinansela ang road skills test mo nang hindi bababa sa dalawang business day bago nito?","o":["Mawawala ang learner permit mo","Magbabayad ka ng $30 na cancellation fee","Dapat kang maghintay ng isang taon bago mag-test","Walang mangyayari"],"h1":"Gagastos ka ng pera.","h2":"Sa District of Columbia, kung hindi mo kinansela ang road skills test nang hindi bababa sa dalawang business day bago nito, sisingilin ka ng $30 na cancellation fee.","p":"Tama. Ang huling pagkansela ay may bayad na $30."},"ar":{"q":"في District of Columbia، ماذا يحدث إذا لم تُلغِ اختبار القيادة على الطريق قبل يومَي عمل على الأقل؟","o":["تخسر تصريح التعلّم","تدفع رسوم إلغاء قدرها $30","يجب أن تنتظر سنة واحدة لتختبر","لا يحدث شيء"],"h1":"يكلّفك ذلك مالًا.","h2":"في District of Columbia إذا لم تُلغِ اختبار القيادة على الطريق قبل يومَي عمل على الأقل، تُفرض عليك رسوم إلغاء قدرها $30.","p":"صحيح. الإلغاء المتأخر يكلّف $30."},"ref":{"doc":"DC","page":12}},{"id":"dc-038","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how long is a provisional driver license valid?","o":["1 year, and it can be renewed","6 months, and it cannot be renewed","2 years, and it cannot be renewed","8 years, like a full license"],"h1":"It is shorter than the learner permit.","h2":"In the District of Columbia, a provisional driver license is valid for one year and can be renewed.","p":"Right. A provisional license lasts one year and can be renewed."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo es válida una licencia provisional?","o":["1 año, y se puede renovar","6 meses, y no se puede renovar","2 años, y no se puede renovar","8 años, como una licencia completa"],"h1":"Es más corto que el permiso de aprendiz.","h2":"En el Distrito de Columbia, una licencia provisional es válida por un año y se puede renovar.","p":"Correcto. La licencia provisional dura un año y se puede renovar."},"zh":{"q":"在 District of Columbia，过渡驾照的有效期是多久？","o":["1 年，而且可以续期","6 个月，而且不能续期","2 年，而且不能续期","8 年，和正式驾照一样"],"h1":"它比学习驾照的有效期短。","h2":"在 District of Columbia，过渡驾照的有效期是一年，而且可以续期。","p":"对。过渡驾照有效一年，可以续期。"},"vi":{"q":"Ở District of Columbia, bằng lái tạm thời (provisional license) có giá trị bao lâu?","o":["1 năm, và có thể gia hạn","6 tháng, và không thể gia hạn","2 năm, và không thể gia hạn","8 năm, giống bằng lái đầy đủ"],"h1":"Nó ngắn hơn giấy phép tập lái.","h2":"Ở District of Columbia, bằng lái tạm thời có giá trị một năm và có thể gia hạn.","p":"Đúng. Bằng lái tạm thời có giá trị một năm và có thể gia hạn."},"tl":{"q":"Sa District of Columbia, gaano katagal valid ang provisional driver license?","o":["1 taon, at puwede itong i-renew","6 na buwan, at hindi ito puwedeng i-renew","2 taon, at hindi ito puwedeng i-renew","8 taon, tulad ng buong lisensya"],"h1":"Mas maikli ito kaysa sa learner permit.","h2":"Sa District of Columbia, valid ang provisional driver license nang isang taon at puwede itong i-renew.","p":"Tama. Tumatagal ang provisional license nang isang taon at puwede itong i-renew."},"ar":{"q":"في District of Columbia، ما مدة صلاحية الرخصة المؤقتة (provisional license)؟","o":["سنة واحدة (1)، ويمكن تجديدها","6 أشهر، ولا يمكن تجديدها","سنتان (2)، ولا يمكن تجديدها","8 سنوات، مثل الرخصة الكاملة"],"h1":"هي أقصر من مدة تصريح التعلّم.","h2":"في District of Columbia تكون الرخصة المؤقتة صالحة لمدة سنة واحدة ويمكن تجديدها.","p":"صحيح. الرخصة المؤقتة صالحة سنة واحدة ويمكن تجديدها."},"ref":{"doc":"DC","page":14}},{"id":"dc-039","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, a provisional driver breaks a GRAD rule for the first time. How long is the license suspended?","o":["7 days","1 year","30 days","It is never suspended for a first time"],"h1":"The suspension grows to 60 and then 90 days for later violations.","h2":"In the District of Columbia, a provisional license is suspended for 30 days for a first GRAD violation, 60 days for a second, and 90 days for a third or more.","p":"Right. A first GRAD violation means a 30-day suspension."},"es":{"q":"En el Distrito de Columbia, un conductor con licencia provisional rompe una regla del programa GRAD por primera vez. ¿Por cuánto tiempo se suspende la licencia?","o":["7 días","1 año","30 días","Nunca se suspende la primera vez"],"h1":"La suspensión sube a 60 y luego a 90 días en las siguientes infracciones.","h2":"En el Distrito de Columbia, la licencia provisional se suspende 30 días por la primera infracción del programa GRAD, 60 días por la segunda y 90 días por la tercera o más.","p":"Correcto. La primera infracción del GRAD significa 30 días de suspensión."},"zh":{"q":"在 District of Columbia，持过渡驾照的司机第一次违反 GRAD 规定。驾照会被暂停多久？","o":["7 天","1 年","30 天","第一次永远不会被暂停"],"h1":"以后再违反，暂停时间会增加到 60 天，然后是 90 天。","h2":"在 District of Columbia，过渡驾照第一次违反 GRAD 规定会被暂停 30 天，第二次 60 天，第三次或更多次 90 天。","p":"对。第一次违反 GRAD 规定，暂停 30 天。"},"vi":{"q":"Ở District of Columbia, người có bằng lái tạm thời vi phạm quy định GRAD lần đầu. Bằng lái bị tạm đình chỉ bao lâu?","o":["7 ngày","1 năm","30 ngày","Lần đầu thì không bao giờ bị tạm đình chỉ"],"h1":"Thời gian tạm đình chỉ tăng lên 60 rồi 90 ngày cho những lần vi phạm sau.","h2":"Ở District of Columbia, bằng lái tạm thời bị tạm đình chỉ 30 ngày cho lần vi phạm GRAD đầu tiên, 60 ngày cho lần thứ hai, và 90 ngày cho lần thứ ba trở đi.","p":"Đúng. Vi phạm GRAD lần đầu bị tạm đình chỉ 30 ngày."},"tl":{"q":"Sa District of Columbia, unang beses na lumabag sa patakaran ng GRAD ang provisional driver. Gaano katagal masususpinde ang lisensya?","o":["7 araw","1 taon","30 araw","Hindi ito kailanman sinususpinde sa unang beses"],"h1":"Tumataas ang suspensyon sa 60 at pagkatapos ay 90 araw sa mga susunod na paglabag.","h2":"Sa District of Columbia, masususpinde ang provisional license nang 30 araw sa unang paglabag sa GRAD, 60 araw sa ikalawa, at 90 araw sa ikatlo o higit pa.","p":"Tama. Ang unang paglabag sa GRAD ay 30 araw na suspensyon."},"ar":{"q":"في District of Columbia، خالف حامل الرخصة المؤقتة قاعدة من قواعد GRAD لأول مرة. ما مدة إيقاف الرخصة؟","o":["7 أيام","سنة واحدة (1)","30 يومًا","لا تُوقَف أبدًا في المرة الأولى"],"h1":"تزيد مدة الإيقاف إلى 60 ثم 90 يومًا في المخالفات التالية.","h2":"في District of Columbia تُوقَف الرخصة المؤقتة لمدة 30 يومًا في أول مخالفة لقواعد GRAD، و60 يومًا في الثانية، و90 يومًا في الثالثة أو أكثر.","p":"صحيح. أول مخالفة لقواعد GRAD تعني إيقافًا لمدة 30 يومًا."},"ref":{"doc":"DC","page":16}},{"id":"dc-040","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the shortest license revocation for a first conviction of driving under the influence?","o":["30 days","6 months","5 years","There is no revocation for a first offense"],"h1":"It grows to 1 year for a second offense and 2 years for a third.","h2":"In the District of Columbia, the minimum revocation for a first driving-under-the-influence offense is 6 months.","p":"Right. A first DUI means at least 6 months of revocation."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la revocación más corta de la licencia por una primera condena por manejar bajo la influencia?","o":["30 días","6 meses","5 años","No hay revocación por una primera infracción"],"h1":"Sube a 1 año por una segunda infracción y a 2 años por una tercera.","h2":"En el Distrito de Columbia, la revocación mínima por una primera infracción de manejar bajo la influencia es de 6 meses.","p":"Correcto. Una primera condena por DUI significa por lo menos 6 meses de revocación."},"zh":{"q":"在 District of Columbia，第一次被判醉酒驾驶，驾照最短会被吊销多久？","o":["30 天","6 个月","5 年","第一次不会被吊销"],"h1":"第二次增加到 1 年，第三次增加到 2 年。","h2":"在 District of Columbia，第一次醉酒驾驶，驾照最少会被吊销 6 个月。","p":"对。第一次 DUI 至少吊销 6 个月。"},"vi":{"q":"Ở District of Columbia, lần đầu bị kết tội lái xe khi say, bằng lái bị thu hồi ít nhất bao lâu?","o":["30 ngày","6 tháng","5 năm","Lần đầu thì không bị thu hồi"],"h1":"Thời gian tăng lên 1 năm cho lần thứ hai và 2 năm cho lần thứ ba.","h2":"Ở District of Columbia, thời gian thu hồi bằng lái ít nhất cho lần đầu lái xe khi say là 6 tháng.","p":"Đúng. DUI lần đầu bị thu hồi bằng lái ít nhất 6 tháng."},"tl":{"q":"Sa District of Columbia, ano ang pinakamaikling pagbawi ng lisensya sa unang conviction sa pagmamaneho nang lasing?","o":["30 araw","6 na buwan","5 taon","Walang pagbawi sa unang paglabag"],"h1":"Tumataas ito sa 1 taon sa ikalawang paglabag at 2 taon sa ikatlo.","h2":"Sa District of Columbia, ang pinakamaikling pagbawi ng lisensya sa unang paglabag sa pagmamaneho nang lasing ay 6 na buwan.","p":"Tama. Ang unang DUI ay hindi bababa sa 6 na buwang pagbawi ng lisensya."},"ar":{"q":"في District of Columbia، ما أقصر مدة لإلغاء الرخصة عند الإدانة الأولى بالقيادة تحت تأثير الكحول؟","o":["30 يومًا","6 أشهر","5 سنوات","لا يوجد إلغاء في المخالفة الأولى"],"h1":"تزيد المدة إلى سنة واحدة (1) في المخالفة الثانية وسنتين (2) في الثالثة.","h2":"في District of Columbia أقل مدة لإلغاء الرخصة في أول مخالفة قيادة تحت تأثير الكحول هي 6 أشهر.","p":"صحيح. أول DUI يعني إلغاء الرخصة 6 أشهر على الأقل."},"ref":{"doc":"DC","page":19}},{"id":"dc-041","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, a driver is convicted of driving under the influence. Which program must they join?","o":["A defensive driving video class","A free bus pass program","A volunteer road clean-up program","The Ignition Interlock Device (IID) Program"],"h1":"It puts a breath-testing device in the car.","h2":"In the District of Columbia, a driver convicted of an alcohol-related offense such as driving under the influence must enroll in the Ignition Interlock Device (IID) Program.","p":"Right. A DUI conviction means joining the IID Program."},"es":{"q":"En el Distrito de Columbia, un conductor es condenado por manejar bajo la influencia. ¿En qué programa debe inscribirse?","o":["Una clase de manejo defensivo en video","Un programa de pase gratis de autobús","Un programa voluntario de limpieza de calles","El Programa de Dispositivo de Bloqueo de Encendido (IID)"],"h1":"Pone en el carro un aparato que mide el aliento.","h2":"En el Distrito de Columbia, un conductor condenado por una infracción relacionada con el alcohol, como manejar bajo la influencia, debe inscribirse en el Programa de Dispositivo de Bloqueo de Encendido (IID).","p":"Correcto. Una condena por DUI significa entrar al Programa IID."},"zh":{"q":"在 District of Columbia，一名司机被判醉酒驾驶。他必须参加哪个项目？","o":["一门防御性驾驶视频课","一个免费公交卡项目","一个志愿清理道路项目","点火联锁装置（IID）项目"],"h1":"它会在车里装一个呼气检测装置。","h2":"在 District of Columbia，因醉酒驾驶等与酒精有关的违法行为被定罪的司机，必须参加点火联锁装置（IID）项目。","p":"对。被判 DUI 就要参加 IID 项目。"},"vi":{"q":"Ở District of Columbia, một người lái xe bị kết tội lái xe khi say. Họ phải tham gia chương trình nào?","o":["Một lớp học lái xe phòng vệ qua video","Một chương trình vé xe buýt miễn phí","Một chương trình tình nguyện dọn dẹp đường phố","Chương trình Thiết bị Khóa Khởi động (Ignition Interlock Device, IID)"],"h1":"Chương trình này gắn một thiết bị đo hơi thở vào xe.","h2":"Ở District of Columbia, người lái xe bị kết tội vi phạm liên quan đến rượu bia, như lái xe khi say, phải tham gia Chương trình Thiết bị Khóa Khởi động (IID).","p":"Đúng. Bị kết tội DUI thì phải tham gia Chương trình IID."},"tl":{"q":"Sa District of Columbia, nahatulan ang isang driver sa pagmamaneho nang lasing. Aling programa ang dapat niyang salihan?","o":["Isang video class sa defensive driving","Isang programa ng libreng bus pass","Isang volunteer na programa sa paglilinis ng kalsada","Ang Ignition Interlock Device (IID) Program"],"h1":"Naglalagay ito ng device na sumusuri ng hininga sa kotse.","h2":"Sa District of Columbia, ang driver na nahatulan sa paglabag na may kinalaman sa alak, gaya ng pagmamaneho nang lasing, ay dapat sumali sa Ignition Interlock Device (IID) Program.","p":"Tama. Kapag nahatulan sa DUI, dapat sumali sa IID Program."},"ar":{"q":"في District of Columbia، أُدين سائق بالقيادة تحت تأثير الكحول. في أي برنامج يجب أن يشترك؟","o":["درس فيديو عن القيادة الوقائية","برنامج بطاقة حافلة مجانية","برنامج تطوعي لتنظيف الطرق","برنامج جهاز قفل الإشعال (Ignition Interlock Device, IID)"],"h1":"يضع هذا البرنامج في السيارة جهازًا يفحص النَّفَس.","h2":"في District of Columbia السائق الذي يُدان بمخالفة لها علاقة بالكحول، مثل القيادة تحت تأثير الكحول، يجب أن يشترك في برنامج جهاز قفل الإشعال (IID).","p":"صحيح. الإدانة بـ DUI تعني الاشتراك في برنامج IID."},"ref":{"doc":"DC","page":19}},{"id":"dc-042","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how can a driver earn a Good Point on their driving record?","o":["Keep a valid DC license for a full calendar year with no pointable moving violations","Take a free safety video online","Pay every parking ticket on time","Drive under the speed limit for one month"],"h1":"It takes a clean year of driving.","h2":"In the District of Columbia, a driver who keeps a valid DC license for a full calendar year without any pointable moving violations may earn a Good Point.","p":"Right. A clean calendar year can earn a Good Point."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede un conductor ganar un Punto Bueno (Good Point) en su historial de manejo?","o":["Mantener una licencia válida de DC un año calendario completo sin infracciones de tránsito con puntos","Ver un video de seguridad gratis en línea","Pagar a tiempo todas las multas de estacionamiento","Manejar por debajo del límite de velocidad durante un mes"],"h1":"Hace falta un año limpio de manejo.","h2":"En el Distrito de Columbia, un conductor que mantiene una licencia válida de DC durante un año calendario completo sin infracciones de tránsito con puntos puede ganar un Punto Bueno.","p":"Correcto. Un año calendario limpio puede darle un Punto Bueno."},"zh":{"q":"在 District of Columbia，司机怎样才能在驾驶记录上得到一个 Good Point（好分）？","o":["一整个日历年持有有效的 DC 驾照，而且没有会扣分的行车违规","在网上看一个免费的安全视频","每张停车罚单都按时交","一个月都开得比限速慢"],"h1":"需要一整年干净的驾驶记录。","h2":"在 District of Columbia，一整个日历年持有有效的 DC 驾照、而且没有任何会扣分的行车违规的司机，可以得到一个 Good Point。","p":"对。一个干净的日历年可以得到一个 Good Point。"},"vi":{"q":"Ở District of Columbia, người lái xe có thể được một Good Point (điểm tốt) trong hồ sơ lái xe bằng cách nào?","o":["Giữ bằng lái DC hợp lệ trọn một năm dương lịch mà không có vi phạm khi lái xe nào bị tính điểm","Xem một video an toàn miễn phí trên mạng","Trả mọi vé phạt đỗ xe đúng hạn","Lái chậm hơn tốc độ giới hạn trong một tháng"],"h1":"Cần một năm lái xe không vi phạm.","h2":"Ở District of Columbia, người lái xe giữ bằng lái DC hợp lệ trọn một năm dương lịch mà không có vi phạm khi lái xe nào bị tính điểm có thể được một Good Point.","p":"Đúng. Một năm dương lịch không vi phạm có thể được một Good Point."},"tl":{"q":"Sa District of Columbia, paano makakakuha ang driver ng Good Point sa kanyang driving record?","o":["Panatilihing valid ang DC license nang isang buong calendar year nang walang moving violation na may puntos","Manood ng libreng safety video online","Bayaran nang nasa oras ang bawat parking ticket","Magmaneho nang mas mabagal sa speed limit nang isang buwan"],"h1":"Kailangan ng isang taon ng malinis na pagmamaneho.","h2":"Sa District of Columbia, ang driver na nagpanatiling valid ng DC license nang isang buong calendar year nang walang anumang moving violation na may puntos ay puwedeng makakuha ng Good Point.","p":"Tama. Ang malinis na calendar year ay puwedeng magbigay ng Good Point."},"ar":{"q":"في District of Columbia، كيف يمكن للسائق أن يكسب نقطة جيدة (Good Point) في سجل القيادة؟","o":["أن يحتفظ برخصة DC صالحة لسنة تقويمية كاملة دون أي مخالفة سير تُحسب عليها نقاط","أن يشاهد فيديو سلامة مجانيًا على الإنترنت","أن يدفع كل مخالفات الركن في وقتها","أن يقود أبطأ من حد السرعة لمدة شهر"],"h1":"يحتاج ذلك إلى سنة قيادة نظيفة.","h2":"في District of Columbia السائق الذي يحتفظ برخصة DC صالحة لسنة تقويمية كاملة دون أي مخالفة سير تُحسب عليها نقاط يمكن أن يكسب نقطة جيدة (Good Point).","p":"صحيح. سنة تقويمية نظيفة يمكن أن تكسبك نقطة جيدة."},"ref":{"doc":"DC","page":19}},{"id":"dc-043","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the rule about hanging things from your rear-view mirror?","o":["Small items are allowed if they are under 3 inches","Only parking permits may hang there","Nothing may be attached to or hang from it while you drive","Anything is allowed if you can still see"],"h1":"Think about what blocks your view of the road.","h2":"In the District of Columbia, having anything attached to or hanging from the rear-view mirror while driving is against the regulations.","p":"Right. Keep the rear-view mirror clear of hanging items."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la regla sobre colgar cosas del espejo retrovisor?","o":["Se permiten objetos pequeños de menos de 3 pulgadas","Solo se pueden colgar permisos de estacionamiento","No se puede colgar ni sujetar nada en él mientras maneja","Se permite cualquier cosa si todavía puede ver"],"h1":"Piense en lo que le tapa la vista del camino.","h2":"En el Distrito de Columbia, tener algo sujeto o colgado del espejo retrovisor mientras maneja va en contra de las normas.","p":"Correcto. No cuelgue nada del espejo retrovisor."},"zh":{"q":"在 District of Columbia，关于在后视镜上挂东西，规定是什么？","o":["小于 3 英寸的小东西可以挂","只有停车证可以挂在那里","开车时后视镜上不能贴或挂任何东西","只要还看得见，什么都可以挂"],"h1":"想一想什么会挡住你看路的视线。","h2":"在 District of Columbia，开车时在后视镜上贴或挂任何东西都违反规定。","p":"对。后视镜上不要挂东西。"},"vi":{"q":"Ở District of Columbia, quy định về việc treo đồ trên gương chiếu hậu là gì?","o":["Đồ nhỏ dưới 3 inch thì được phép","Chỉ được treo giấy phép đỗ xe","Không được gắn hoặc treo bất cứ thứ gì trên gương khi lái xe","Treo gì cũng được nếu bạn vẫn nhìn thấy"],"h1":"Hãy nghĩ đến những gì che tầm nhìn của bạn ra đường.","h2":"Ở District of Columbia, gắn hoặc treo bất cứ thứ gì trên gương chiếu hậu khi lái xe là trái quy định.","p":"Đúng. Đừng treo đồ trên gương chiếu hậu."},"tl":{"q":"Sa District of Columbia, ano ang patakaran tungkol sa pagsasabit ng mga bagay sa rear-view mirror?","o":["Puwede ang maliliit na bagay kung wala pang 3 pulgada","Mga parking permit lang ang puwedeng isabit doon","Walang anumang puwedeng ikabit o isabit dito habang nagmamaneho ka","Puwede ang kahit ano basta nakakakita ka pa"],"h1":"Isipin kung ano ang humaharang sa tanaw mo sa kalsada.","h2":"Sa District of Columbia, labag sa regulasyon ang pagkakabit o pagsasabit ng anumang bagay sa rear-view mirror habang nagmamaneho.","p":"Tama. Huwag sabitan ng kahit ano ang rear-view mirror."},"ar":{"q":"في District of Columbia، ما القاعدة بشأن تعليق الأشياء على المرآة الخلفية؟","o":["الأشياء الصغيرة مسموحة إذا كانت أقل من 3 بوصات","فقط تصاريح الركن يمكن تعليقها هناك","يجب ألّا يُثبَّت أو يُعلَّق عليها أي شيء أثناء القيادة","كل شيء مسموح ما دمت ترى"],"h1":"فكّر فيما يحجب رؤيتك للطريق.","h2":"في District of Columbia تثبيت أي شيء على المرآة الخلفية أو تعليقه منها أثناء القيادة مخالف للأنظمة.","p":"صحيح. أبقِ المرآة الخلفية خالية من الأشياء المعلّقة."},"ref":{"doc":"DC","page":19}},{"id":"dc-044","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, a fire truck is answering an emergency. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","As close as you like if you are careful","No closer than 500 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In the District of Columbia, you must not follow a fire truck closer than 500 feet when it is answering an emergency.","p":"Right. Stay at least 500 feet behind a fire truck on a call."},"es":{"q":"En el Distrito de Columbia, un camión de bomberos va a una emergencia. ¿A qué distancia lo puede seguir?","o":["No más cerca de 50 pies","No más cerca de 100 pies","Tan cerca como quiera si tiene cuidado","No más cerca de 500 pies"],"h1":"Es como una cancha de fútbol americano y media.","h2":"En el Distrito de Columbia, no debe seguir a un camión de bomberos a menos de 500 pies cuando va a una emergencia.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos en emergencia."},"zh":{"q":"在 District of Columbia，一辆消防车正在赶去处理紧急情况。你可以跟在它后面多近？","o":["不能近于 50 英尺","不能近于 100 英尺","只要小心，想多近都可以","不能近于 500 英尺"],"h1":"大约是一个半橄榄球场那么长。","h2":"在 District of Columbia，消防车在赶去处理紧急情况时，你不能跟在它后面 500 英尺以内。","p":"对。消防车出任务时，至少跟在它后面 500 英尺。"},"vi":{"q":"Ở District of Columbia, một xe cứu hỏa đang đi xử lý trường hợp khẩn cấp. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận","Không gần hơn 500 feet"],"h1":"Khoảng chiều dài của một sân bóng bầu dục rưỡi.","h2":"Ở District of Columbia, bạn không được chạy theo sau xe cứu hỏa gần hơn 500 feet khi nó đang đi xử lý trường hợp khẩn cấp.","p":"Đúng. Hãy ở cách ít nhất 500 feet phía sau xe cứu hỏa đang làm nhiệm vụ."},"tl":{"q":"Sa District of Columbia, may fire truck na rumeresponde sa emergency. Gaano kalapit ka puwedeng sumunod dito?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan","Kahit gaano kalapit basta maingat ka","Hindi lalapit sa 500 talampakan"],"h1":"Mga isa't kalahating haba ito ng football field.","h2":"Sa District of Columbia, hindi ka dapat sumunod sa fire truck nang mas malapit sa 500 talampakan kapag rumeresponde ito sa emergency.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod ng fire truck na rumeresponde."},"ar":{"q":"في District of Columbia، سيارة إطفاء في طريقها إلى حالة طارئة. كم يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","بالقرب الذي تريده إذا كنت حذرًا","ليس أقرب من 500 قدم"],"h1":"هي تقريبًا طول ملعب ونصف من ملاعب كرة القدم الأمريكية.","h2":"في District of Columbia يجب ألّا تسير خلف سيارة إطفاء على مسافة أقل من 500 قدم عندما تكون في طريقها إلى حالة طارئة.","p":"صحيح. ابقَ 500 قدم على الأقل خلف سيارة الإطفاء في مهمة."},"ref":{"doc":"DC","page":35}},{"id":"dc-045","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, you come to a block where fire engines or emergency vehicles are stopped. What should you do?","o":["Drive slowly through the block","Turn right or left instead of driving into the block","Honk and drive around them","Park in the block and wait"],"h1":"Driving into that block is against the traffic rules.","h2":"In the District of Columbia, you should not drive into a block where fire engines or emergency vehicles are stopped; turn right or left instead.","p":"Right. Turn away and do not enter that block."},"es":{"q":"En el Distrito de Columbia, usted llega a una cuadra donde hay camiones de bomberos o vehículos de emergencia detenidos. ¿Qué debe hacer?","o":["Pasar despacio por la cuadra","Doblar a la derecha o a la izquierda en vez de entrar a la cuadra","Tocar la bocina y rodearlos","Estacionarse en la cuadra y esperar"],"h1":"Entrar a esa cuadra va contra las reglas de tránsito.","h2":"En el Distrito de Columbia, no debe entrar a una cuadra donde hay camiones de bomberos o vehículos de emergencia detenidos; doble a la derecha o a la izquierda.","p":"Correcto. Doble y no entre a esa cuadra."},"zh":{"q":"在 District of Columbia，你来到一个街区，那里停着消防车或紧急车辆。你应该怎么做？","o":["慢慢开过这个街区","向右或向左转，不要开进这个街区","按喇叭，从它们旁边绕过去","在这个街区停车等着"],"h1":"开进那个街区违反交通规则。","h2":"在 District of Columbia，你不应该开进停着消防车或紧急车辆的街区，而应该向右或向左转。","p":"对。转开，不要进入那个街区。"},"vi":{"q":"Ở District of Columbia, bạn đến một dãy phố nơi xe cứu hỏa hoặc xe cấp cứu đang dừng. Bạn nên làm gì?","o":["Lái chậm qua dãy phố đó","Rẽ phải hoặc rẽ trái thay vì lái vào dãy phố đó","Bấm còi và lái vòng qua chúng","Đỗ xe trong dãy phố đó và chờ"],"h1":"Lái vào dãy phố đó là trái luật giao thông.","h2":"Ở District of Columbia, bạn không nên lái vào dãy phố nơi xe cứu hỏa hoặc xe cấp cứu đang dừng; hãy rẽ phải hoặc rẽ trái.","p":"Đúng. Hãy rẽ đi và không vào dãy phố đó."},"tl":{"q":"Sa District of Columbia, nakarating ka sa isang block kung saan nakahinto ang mga fire engine o emergency vehicle. Ano ang dapat mong gawin?","o":["Magmaneho nang dahan-dahan sa block","Lumiko pakanan o pakaliwa sa halip na pumasok sa block","Bumusina at umikot sa kanila","Pumarada sa block at maghintay"],"h1":"Labag sa mga patakaran sa trapiko ang pagpasok sa block na iyon.","h2":"Sa District of Columbia, hindi ka dapat pumasok sa block kung saan nakahinto ang mga fire engine o emergency vehicle; lumiko pakanan o pakaliwa sa halip.","p":"Tama. Lumiko palayo at huwag pumasok sa block na iyon."},"ar":{"q":"في District of Columbia، وصلت إلى مربع سكني (block) تقف فيه سيارات إطفاء أو سيارات طوارئ. ماذا يجب أن تفعل؟","o":["أن تقود ببطء عبر المربع","أن تنعطف يمينًا أو يسارًا بدل أن تدخل المربع","أن تستخدم البوق وتلتف حولها","أن تركن في المربع وتنتظر"],"h1":"الدخول إلى ذلك المربع مخالف لقواعد السير.","h2":"في District of Columbia يجب ألّا تدخل مربعًا تقف فيه سيارات إطفاء أو سيارات طوارئ؛ انعطف يمينًا أو يسارًا بدل ذلك.","p":"صحيح. انعطف بعيدًا ولا تدخل ذلك المربع."},"ref":{"doc":"DC","page":35}},{"id":"dc-046","scope":"DC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In the District of Columbia, a school vehicle is stopped with its red lights flashing. How far away must you stop?","o":["At least 20 feet from its front or rear","At least 5 feet from its front or rear","At least 100 feet from its front or rear","You only need to slow down"],"h1":"Leave a bit more than one car length.","h2":"In the District of Columbia, when a school vehicle is stopped with its red lights flashing, you must stop at least 20 feet from its front or rear.","p":"Right. Stop at least 20 feet from a stopped school vehicle."},"es":{"q":"En el Distrito de Columbia, un vehículo escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 20 pies de su parte delantera o trasera","Por lo menos a 5 pies de su parte delantera o trasera","Por lo menos a 100 pies de su parte delantera o trasera","Solo necesita bajar la velocidad"],"h1":"Deje un poco más que el largo de un carro.","h2":"En el Distrito de Columbia, cuando un vehículo escolar está detenido con sus luces rojas intermitentes, debe detenerse por lo menos a 20 pies de su parte delantera o trasera.","p":"Correcto. Deténgase por lo menos a 20 pies de un vehículo escolar detenido."},"zh":{"q":"在 District of Columbia，一辆校车停着，红灯在闪。你必须在离它多远的地方停车？","o":["离它的前面或后面至少 20 英尺","离它的前面或后面至少 5 英尺","离它的前面或后面至少 100 英尺","你只需要减速"],"h1":"留出比一辆车长一点的距离。","h2":"在 District of Columbia，校车停着并闪红灯时，你必须在离它的前面或后面至少 20 英尺的地方停车。","p":"对。在停着的校车前后至少 20 英尺停车。"},"vi":{"q":"Ở District of Columbia, một xe chở học sinh đang dừng và đèn đỏ đang nhấp nháy. Bạn phải dừng cách nó bao xa?","o":["Ít nhất 20 feet tính từ phía trước hoặc phía sau xe","Ít nhất 5 feet tính từ phía trước hoặc phía sau xe","Ít nhất 100 feet tính từ phía trước hoặc phía sau xe","Bạn chỉ cần chạy chậm lại"],"h1":"Hãy chừa khoảng hơn chiều dài một chiếc xe một chút.","h2":"Ở District of Columbia, khi xe chở học sinh dừng và đèn đỏ nhấp nháy, bạn phải dừng cách phía trước hoặc phía sau xe ít nhất 20 feet.","p":"Đúng. Hãy dừng cách xe chở học sinh đang dừng ít nhất 20 feet."},"tl":{"q":"Sa District of Columbia, nakahinto ang isang school vehicle at kumikislap ang pulang ilaw nito. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 20 talampakan mula sa harap o likod nito","Hindi bababa sa 5 talampakan mula sa harap o likod nito","Hindi bababa sa 100 talampakan mula sa harap o likod nito","Kailangan mo lang bumagal"],"h1":"Mag-iwan ng kaunti pa sa haba ng isang kotse.","h2":"Sa District of Columbia, kapag nakahinto ang school vehicle at kumikislap ang pulang ilaw nito, dapat kang huminto nang hindi bababa sa 20 talampakan mula sa harap o likod nito.","p":"Tama. Huminto nang hindi bababa sa 20 talampakan mula sa nakahintong school vehicle."},"ar":{"q":"في District of Columbia، مركبة مدرسية متوقفة وأضواؤها الحمراء تومض. على أي مسافة منها يجب أن تتوقف؟","o":["20 قدمًا على الأقل من أمامها أو من خلفها","5 أقدام على الأقل من أمامها أو من خلفها","100 قدم على الأقل من أمامها أو من خلفها","ليس عليك إلا أن تخفف السرعة"],"h1":"اترك مسافة أكثر قليلًا من طول سيارة واحدة.","h2":"في District of Columbia عندما تكون المركبة المدرسية متوقفة وأضواؤها الحمراء تومض، يجب أن تتوقف على بُعد 20 قدمًا على الأقل من أمامها أو من خلفها.","p":"صحيح. توقف على بُعد 20 قدمًا على الأقل من المركبة المدرسية المتوقفة."},"ref":{"doc":"DC","page":38}},{"id":"dc-047","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, a bus is stopped at an intersection to let riders on and off. May you turn right in front of it?","o":["Yes, if you signal first","Yes, if no riders are in the street","No; stay or merge behind the bus, or face a fine of at least $200","No, unless the light is green"],"h1":"District law protects people getting on and off the bus.","h2":"In the District of Columbia, it is illegal to turn right in front of a bus stopped at an intersection to load or unload riders, and the fine is at least $200.","p":"Right. Stay behind the bus; the fine is at least $200."},"es":{"q":"En el Distrito de Columbia, un autobús está detenido en una intersección para que suban y bajen pasajeros. ¿Puede doblar a la derecha delante de él?","o":["Sí, si pone la direccional primero","Sí, si no hay pasajeros en la calle","No; quédese o incorpórese detrás del autobús, o la multa es de por lo menos $200","No, a menos que el semáforo esté en verde"],"h1":"La ley del Distrito protege a las personas que suben y bajan del autobús.","h2":"En el Distrito de Columbia, es ilegal doblar a la derecha delante de un autobús detenido en una intersección para subir o bajar pasajeros, y la multa es de por lo menos $200.","p":"Correcto. Quédese detrás del autobús; la multa es de por lo menos $200."},"zh":{"q":"在 District of Columbia，一辆公交车停在路口让乘客上下车。你可以在它前面右转吗？","o":["可以，只要先打转向灯","可以，只要街上没有乘客","不可以；要留在公交车后面或并到它后面，否则至少罚款 $200","不可以，除非是绿灯"],"h1":"DC 的法律保护上下公交车的人。","h2":"在 District of Columbia，在停在路口让乘客上下车的公交车前面右转是违法的，罚款至少 $200。","p":"对。留在公交车后面；罚款至少 $200。"},"vi":{"q":"Ở District of Columbia, một xe buýt đang dừng ở giao lộ cho khách lên xuống. Bạn có được rẽ phải trước đầu xe buýt không?","o":["Có, nếu bạn bật đèn xi nhan trước","Có, nếu không có hành khách nào ở dưới đường","Không; hãy ở phía sau hoặc nhập làn phía sau xe buýt, nếu không sẽ bị phạt ít nhất $200","Không, trừ khi đèn xanh"],"h1":"Luật của DC bảo vệ người lên xuống xe buýt.","h2":"Ở District of Columbia, rẽ phải trước đầu xe buýt đang dừng ở giao lộ cho khách lên xuống là phạm luật, và tiền phạt ít nhất là $200.","p":"Đúng. Hãy ở phía sau xe buýt; tiền phạt ít nhất là $200."},"tl":{"q":"Sa District of Columbia, nakahinto ang isang bus sa intersection para magbaba at magsakay ng pasahero. Puwede ka bang kumanan sa harap nito?","o":["Oo, kung magsi-signal ka muna","Oo, kung walang pasahero sa kalsada","Hindi; manatili o pumasok sa likod ng bus, o pagmumultahin ka ng hindi bababa sa $200","Hindi, maliban kung green ang ilaw"],"h1":"Pinoprotektahan ng batas ng DC ang mga sumasakay at bumababa ng bus.","h2":"Sa District of Columbia, ilegal ang kumanan sa harap ng bus na nakahinto sa intersection para magsakay o magbaba ng pasahero, at ang multa ay hindi bababa sa $200.","p":"Tama. Manatili sa likod ng bus; ang multa ay hindi bababa sa $200."},"ar":{"q":"في District of Columbia، حافلة متوقفة عند تقاطع ليصعد الركاب وينزلوا. هل يجوز لك أن تنعطف يمينًا أمامها؟","o":["نعم، إذا أعطيت الإشارة أولًا","نعم، إذا لم يكن هناك ركاب في الشارع","لا؛ ابقَ خلف الحافلة أو اندمج خلفها، وإلا فالغرامة $200 على الأقل","لا، إلا إذا كانت الإشارة خضراء"],"h1":"قانون DC يحمي الناس الذين يصعدون إلى الحافلة وينزلون منها.","h2":"في District of Columbia الانعطاف يمينًا أمام حافلة متوقفة عند تقاطع لصعود الركاب أو نزولهم مخالف للقانون، والغرامة $200 على الأقل.","p":"صحيح. ابقَ خلف الحافلة؛ الغرامة $200 على الأقل."},"ref":{"doc":"DC","page":39}},{"id":"dc-048","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, there is no sign about turning across a bus lane. Where may you cross it to make a turn?","o":["Anywhere along the block","Within 40 feet of the intersection","Only after 9 p.m.","Never; you must turn from the bus lane's left side only"],"h1":"Enter the lane only close to the corner.","h2":"In the District of Columbia, when no sign says otherwise, you may cross a bus lane to turn within 40 feet of the intersection, after yielding to bicycles and buses in the lane.","p":"Right. Cross a bus lane to turn only within 40 feet of the intersection."},"es":{"q":"En el Distrito de Columbia, no hay ningún letrero sobre cruzar un carril de autobús para doblar. ¿Dónde puede cruzarlo para doblar?","o":["En cualquier parte de la cuadra","Dentro de los 40 pies antes de la intersección","Solo después de las 9 p.m.","Nunca; debe doblar solo desde el lado izquierdo del carril de autobús"],"h1":"Entre al carril solo cerca de la esquina.","h2":"En el Distrito de Columbia, si ningún letrero dice otra cosa, puede cruzar un carril de autobús para doblar dentro de los 40 pies antes de la intersección, después de ceder el paso a bicicletas y autobuses en el carril.","p":"Correcto. Cruce el carril de autobús para doblar solo dentro de los 40 pies antes de la intersección."},"zh":{"q":"在 District of Columbia，没有关于穿过公交专用道转弯的标志。你可以在哪里穿过它去转弯？","o":["这个街区的任何地方","离路口 40 英尺以内","只在晚上 9 点以后","永远不可以；你只能从公交专用道的左边转弯"],"h1":"只在靠近路口的地方进入这条车道。","h2":"在 District of Columbia，没有标志另有规定时，你可以在离路口 40 英尺以内穿过公交专用道转弯，但要先让道给车道里的自行车和公交车。","p":"对。只在离路口 40 英尺以内穿过公交专用道转弯。"},"vi":{"q":"Ở District of Columbia, không có biển báo nào về việc rẽ qua làn xe buýt. Bạn được băng qua làn đó để rẽ ở đâu?","o":["Bất cứ chỗ nào dọc theo dãy phố","Trong vòng 40 feet tính từ giao lộ","Chỉ sau 9 giờ tối","Không bao giờ; bạn chỉ được rẽ từ phía bên trái của làn xe buýt"],"h1":"Chỉ vào làn đó khi đã gần góc đường.","h2":"Ở District of Columbia, khi không có biển báo nói khác, bạn được băng qua làn xe buýt để rẽ trong vòng 40 feet tính từ giao lộ, sau khi nhường đường cho xe đạp và xe buýt trong làn.","p":"Đúng. Chỉ băng qua làn xe buýt để rẽ trong vòng 40 feet tính từ giao lộ."},"tl":{"q":"Sa District of Columbia, walang karatula tungkol sa pagliko patawid sa bus lane. Saan ka puwedeng tumawid dito para lumiko?","o":["Kahit saan sa kahabaan ng block","Sa loob ng 40 talampakan mula sa intersection","Pagkalipas lang ng 9 p.m.","Hindi kailanman; dapat kang lumiko mula sa kaliwang bahagi lang ng bus lane"],"h1":"Pumasok lang sa lane kapag malapit na sa kanto.","h2":"Sa District of Columbia, kapag walang karatulang nagsasabi ng iba, puwede kang tumawid sa bus lane para lumiko sa loob ng 40 talampakan mula sa intersection, pagkatapos magbigay-daan sa mga bisikleta at bus sa lane.","p":"Tama. Tumawid lang sa bus lane para lumiko sa loob ng 40 talampakan mula sa intersection."},"ar":{"q":"في District of Columbia، لا توجد لافتة عن الانعطاف عبر مسار الحافلات. أين يجوز لك أن تعبره لتنعطف؟","o":["في أي مكان على طول المربع","خلال 40 قدمًا من التقاطع","بعد الساعة 9 مساءً فقط","أبدًا؛ يجب أن تنعطف من الجهة اليسرى لمسار الحافلات فقط"],"h1":"ادخل المسار فقط عندما تكون قريبًا من الزاوية.","h2":"في District of Columbia عندما لا توجد لافتة تقول غير ذلك، يجوز لك أن تعبر مسار الحافلات لتنعطف خلال 40 قدمًا من التقاطع، بعد أن تعطي الأولوية للدراجات والحافلات في المسار.","p":"صحيح. اعبر مسار الحافلات لتنعطف فقط خلال 40 قدمًا من التقاطع."},"ref":{"doc":"DC","page":39}},{"id":"dc-049","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, a streetcar going your way has stopped. How should you pass it?","o":["On the right side, quickly","Between the streetcar and the curb","By driving on the tracks","With great care, on the left side, when it is safe"],"h1":"Riders may be getting on or off at the curb side.","h2":"In the District of Columbia, you pass a stopped streetcar going your way on its left side, with extreme care and only when it is safe.","p":"Right. Pass a stopped streetcar carefully on the left."},"es":{"q":"En el Distrito de Columbia, un tranvía que va en su misma dirección está detenido. ¿Cómo debe rebasarlo?","o":["Por el lado derecho, rápido","Entre el tranvía y la acera","Manejando sobre los rieles","Con mucho cuidado, por el lado izquierdo, cuando sea seguro"],"h1":"Puede haber pasajeros subiendo o bajando por el lado de la acera.","h2":"En el Distrito de Columbia, un tranvía detenido que va en su misma dirección se rebasa por su lado izquierdo, con muchísimo cuidado y solo cuando sea seguro.","p":"Correcto. Rebase un tranvía detenido con cuidado por la izquierda."},"zh":{"q":"在 District of Columbia，一辆和你同方向行驶的有轨电车停下了。你应该怎样超过它？","o":["从右边快速超过","从电车和路缘之间开过去","开在轨道上超过","非常小心地从左边超过，而且要在安全的时候"],"h1":"乘客可能正在靠路缘的一边上下车。","h2":"在 District of Columbia，超过和你同方向、已经停下的有轨电车时，你要从它的左边超过，要非常小心，而且只在安全的时候。","p":"对。小心地从左边超过停下的有轨电车。"},"vi":{"q":"Ở District of Columbia, một xe điện (streetcar) đi cùng chiều với bạn đã dừng lại. Bạn nên vượt nó như thế nào?","o":["Bên phải, thật nhanh","Giữa xe điện và lề đường","Bằng cách lái trên đường ray","Rất cẩn thận, ở bên trái, khi an toàn"],"h1":"Hành khách có thể đang lên hoặc xuống ở phía lề đường.","h2":"Ở District of Columbia, bạn vượt xe điện đang dừng đi cùng chiều ở phía bên trái của nó, hết sức cẩn thận và chỉ khi an toàn.","p":"Đúng. Hãy vượt xe điện đang dừng bên trái một cách cẩn thận."},"tl":{"q":"Sa District of Columbia, huminto ang isang streetcar na papunta sa direksyon mo. Paano mo ito dapat lampasan?","o":["Sa kanang bahagi, nang mabilis","Sa pagitan ng streetcar at ng curb","Sa pagmamaneho sa riles","Nang napakaingat, sa kaliwang bahagi, kapag ligtas"],"h1":"Puwedeng may mga pasaherong sumasakay o bumababa sa bahagi ng curb.","h2":"Sa District of Columbia, nilalampasan mo ang nakahintong streetcar na papunta sa direksyon mo sa kaliwang bahagi nito, nang napakaingat at kapag ligtas lang.","p":"Tama. Lampasan nang maingat sa kaliwa ang nakahintong streetcar."},"ar":{"q":"في District of Columbia، توقف ترام (streetcar) يسير في نفس اتجاهك. كيف يجب أن تتجاوزه؟","o":["من الجهة اليمنى، بسرعة","بين الترام والرصيف","بالقيادة على القضبان","بحذر شديد، من الجهة اليسرى، عندما يكون ذلك آمنًا"],"h1":"قد يكون الركاب يصعدون أو ينزلون من جهة الرصيف.","h2":"في District of Columbia تتجاوز الترام المتوقف الذي يسير في نفس اتجاهك من جهته اليسرى، بحذر شديد وفقط عندما يكون ذلك آمنًا.","p":"صحيح. تجاوز الترام المتوقف بحذر من اليسار."},"ref":{"doc":"DC","page":40}},{"id":"dc-050","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, how far ahead should you signal before you change lanes?","o":["At least 300 feet","At least 20 feet","At least 1 mile","Only as you start to move over"],"h1":"It is three times the distance used before a turn.","h2":"In the District of Columbia, you should signal at least 300 feet before you change lanes, and sooner is better.","p":"Right. Signal at least 300 feet before a lane change."},"es":{"q":"En el Distrito de Columbia, ¿con cuánta anticipación debe poner la direccional antes de cambiar de carril?","o":["Por lo menos 300 pies antes","Por lo menos 20 pies antes","Por lo menos 1 milla antes","Solo cuando empieza a cambiarse"],"h1":"Es tres veces la distancia que se usa antes de doblar.","h2":"En el Distrito de Columbia, debe poner la direccional por lo menos 300 pies antes de cambiar de carril, y es mejor hacerlo antes.","p":"Correcto. Ponga la direccional por lo menos 300 pies antes de cambiar de carril."},"zh":{"q":"在 District of Columbia，换车道前，你应该提前多远打转向灯？","o":["至少 300 英尺","至少 20 英尺","至少 1 英里","在开始移过去时才打"],"h1":"它是转弯前所用距离的三倍。","h2":"在 District of Columbia，你应该在换车道前至少 300 英尺打转向灯，越早越好。","p":"对。换车道前至少 300 英尺打转向灯。"},"vi":{"q":"Ở District of Columbia, bạn nên bật xi nhan trước bao xa trước khi chuyển làn?","o":["Ít nhất 300 feet","Ít nhất 20 feet","Ít nhất 1 dặm","Chỉ khi bạn bắt đầu chuyển sang"],"h1":"Đó là gấp ba lần khoảng cách dùng trước khi rẽ.","h2":"Ở District of Columbia, bạn nên bật xi nhan ít nhất 300 feet trước khi chuyển làn, và càng sớm càng tốt.","p":"Đúng. Hãy bật xi nhan ít nhất 300 feet trước khi chuyển làn."},"tl":{"q":"Sa District of Columbia, gaano kalayo bago ka lumipat ng lane ka dapat mag-signal?","o":["Hindi bababa sa 300 talampakan","Hindi bababa sa 20 talampakan","Hindi bababa sa 1 milya","Kapag nagsisimula ka nang lumipat"],"h1":"Tatlong beses ito ng layong ginagamit bago lumiko.","h2":"Sa District of Columbia, dapat kang mag-signal nang hindi bababa sa 300 talampakan bago ka lumipat ng lane, at mas mabuti kung mas maaga.","p":"Tama. Mag-signal nang hindi bababa sa 300 talampakan bago lumipat ng lane."},"ar":{"q":"في District of Columbia، على أي مسافة قبل تغيير المسار يجب أن تعطي الإشارة؟","o":["300 قدم على الأقل","20 قدمًا على الأقل","ميل واحد (1) على الأقل","فقط عندما تبدأ بالانتقال"],"h1":"هي ثلاثة أضعاف المسافة المستخدمة قبل الانعطاف.","h2":"في District of Columbia يجب أن تعطي الإشارة قبل تغيير المسار بـ 300 قدم على الأقل، والأبكر أفضل.","p":"صحيح. أعطِ الإشارة قبل تغيير المسار بـ 300 قدم على الأقل."},"ref":{"doc":"DC","page":42}},{"id":"dc-051","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, how close to a driveway or alley may you stand or park?","o":["Right up to the edge","No closer than 1 foot","No closer than 5 feet, and never in front of it","No closer than 50 feet"],"h1":"It is a short distance, but you may not block it.","h2":"In the District of Columbia, you may not stand or park in front of a driveway or alley, or within 5 feet of one.","p":"Right. Stay 5 feet from a driveway or alley."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia de una entrada de garaje o un callejón puede detenerse o estacionarse?","o":["Justo hasta el borde","No más cerca de 1 pie","No más cerca de 5 pies, y nunca enfrente","No más cerca de 50 pies"],"h1":"Es una distancia corta, pero no puede bloquearla.","h2":"En el Distrito de Columbia, no puede detenerse ni estacionarse enfrente de una entrada de garaje o un callejón, ni a menos de 5 pies de uno.","p":"Correcto. Quédese a 5 pies de una entrada de garaje o un callejón."},"zh":{"q":"在 District of Columbia，你可以在离车道入口或小巷多近的地方临时停靠或停车？","o":["紧靠边缘就可以","不能近于 1 英尺","不能近于 5 英尺，而且绝不能停在它前面","不能近于 50 英尺"],"h1":"这个距离很短，但你不能挡住它。","h2":"在 District of Columbia，你不能在车道入口或小巷前面临时停靠或停车，也不能在离它们 5 英尺以内停。","p":"对。离车道入口或小巷至少 5 英尺。"},"vi":{"q":"Ở District of Columbia, bạn được dừng hoặc đỗ xe gần lối xe ra vào (driveway) hoặc hẻm đến mức nào?","o":["Sát ngay mép","Không gần hơn 1 foot","Không gần hơn 5 feet, và không bao giờ ở ngay trước nó","Không gần hơn 50 feet"],"h1":"Khoảng cách ngắn, nhưng bạn không được chắn lối.","h2":"Ở District of Columbia, bạn không được dừng hoặc đỗ xe trước lối xe ra vào hoặc hẻm, hoặc trong vòng 5 feet tính từ đó.","p":"Đúng. Hãy cách lối xe ra vào hoặc hẻm 5 feet."},"tl":{"q":"Sa District of Columbia, gaano kalapit sa driveway o eskinita ka puwedeng huminto o pumarada?","o":["Hanggang mismo sa gilid","Hindi lalapit sa 1 talampakan","Hindi lalapit sa 5 talampakan, at hindi kailanman sa harap nito","Hindi lalapit sa 50 talampakan"],"h1":"Maikling layo ito, pero hindi mo ito puwedeng harangan.","h2":"Sa District of Columbia, hindi ka puwedeng huminto o pumarada sa harap ng driveway o eskinita, o sa loob ng 5 talampakan mula rito.","p":"Tama. Lumayo nang 5 talampakan sa driveway o eskinita."},"ar":{"q":"في District of Columbia، كم يمكنك أن تقترب من مدخل سيارات (driveway) أو زقاق عند التوقف أو الركن؟","o":["حتى الحافة تمامًا","ليس أقرب من قدم واحدة (1)","ليس أقرب من 5 أقدام، ولا أمامه أبدًا","ليس أقرب من 50 قدمًا"],"h1":"المسافة قصيرة، لكن لا يجوز لك أن تسدّه.","h2":"في District of Columbia لا يجوز لك التوقف أو الركن أمام مدخل سيارات أو زقاق، أو على بُعد أقل من 5 أقدام منه.","p":"صحيح. ابقَ على بُعد 5 أقدام من مدخل السيارات أو الزقاق."},"ref":{"doc":"DC","page":44}},{"id":"dc-052","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, you fail the knowledge test six times in a row. When may you take it again?","o":["Three calendar days after your last test","Thirty days after your last test","Twelve months after your first failed test","Right away, if you pay a new fee"],"h1":"After many fails in a row, the wait becomes much longer.","h2":"In the District of Columbia, after six failed knowledge tests in a row, you must wait until twelve months after your first failed test to try again.","p":"Right. Six fails in a row means waiting 12 months from the first fail."},"es":{"q":"En el Distrito de Columbia, usted reprueba el examen de conocimientos seis veces seguidas. ¿Cuándo puede volver a tomarlo?","o":["Tres días calendario después de su último examen","Treinta días después de su último examen","Doce meses después de su primer examen reprobado","De inmediato, si paga una nueva tarifa"],"h1":"Después de muchos fracasos seguidos, la espera es mucho más larga.","h2":"En el Distrito de Columbia, después de reprobar el examen de conocimientos seis veces seguidas, debe esperar doce meses desde su primer examen reprobado para intentarlo otra vez.","p":"Correcto. Seis fracasos seguidos significan esperar 12 meses desde el primero."},"ref":{"doc":"DC","page":12}},{"id":"dc-053","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, your license has been expired for more than 365 days, but not more than 545 days. What must you do to get it back?","o":["Pass the knowledge test or DC online traffic school","Pass the road skills test, but no knowledge test","Just pay the renewal fee; no test is needed","Wait six months, then apply like a new driver"],"h1":"After a year, you must show you still know the rules.","h2":"In the District of Columbia, if your license has been expired for more than 365 days, you must pass the knowledge test or the DC online traffic school course.","p":"Right. After a year expired, take the knowledge test or online traffic school."},"es":{"q":"En el Distrito de Columbia, su licencia lleva vencida más de 365 días, pero no más de 545 días. ¿Qué debe hacer para recuperarla?","o":["Aprobar el examen de conocimientos o el curso en línea de DC","Aprobar el examen práctico, pero no el de conocimientos","Solo pagar la renovación; no necesita examen","Esperar seis meses y solicitarla como conductor nuevo"],"h1":"Después de un año, debe demostrar que todavía conoce las reglas.","h2":"En el Distrito de Columbia, si su licencia lleva vencida más de 365 días, debe aprobar el examen de conocimientos o el curso de escuela de tránsito en línea de DC.","p":"Correcto. Después de un año vencida, tome el examen de conocimientos o la escuela de tránsito en línea."},"ref":{"doc":"DC","page":12}},{"id":"dc-054","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you fail the vision screening at the DMV. What must you do next?","o":["Take the road skills test instead","Try the screening again at a different DMV","Ask for a license for daytime driving only","Bring an Eye Report from your eye care professional"],"h1":"Your own eye doctor must fill out a form.","h2":"In the District of Columbia, if you fail the vision screening, you must turn in an Eye Report from your eye care professional.","p":"Right. A failed vision screening means bringing an Eye Report."},"es":{"q":"En el Distrito de Columbia, usted no pasa la prueba de la vista en el DMV. ¿Qué debe hacer después?","o":["Tomar el examen práctico de manejo en su lugar","Repetir la prueba en otra oficina del DMV","Pedir una licencia solo para manejar de día","Traer un Informe de la Vista de su profesional de la vista"],"h1":"Su propio doctor de los ojos debe llenar un formulario.","h2":"En el Distrito de Columbia, si no pasa la prueba de la vista, debe entregar un Informe de la Vista (Eye Report) de su profesional de la vista.","p":"Correcto. Si no pasa la prueba de la vista, traiga un Informe de la Vista."},"ref":{"doc":"DC","page":12}},{"id":"dc-055","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, you have a valid driver license from another country. Which tests must you pass to get a DC license?","o":["No tests; the license is simply swapped","The knowledge test and the eye exam","Only the road skills test","Only a written form and a fee"],"h1":"One test checks what you know, and the other checks how well you see.","h2":"In the District of Columbia, a person with a valid license from another country must pass the knowledge test and the eye exam to get a DC license.","p":"Right. A license from another country means taking the knowledge and eye exams."},"es":{"q":"En el Distrito de Columbia, usted tiene una licencia de manejo válida de otro país. ¿Qué exámenes debe aprobar para obtener una licencia de DC?","o":["Ninguno; la licencia simplemente se cambia","El examen de conocimientos y el examen de la vista","Solo el examen práctico de manejo","Solo un formulario escrito y una tarifa"],"h1":"Un examen revisa lo que usted sabe y el otro revisa qué tan bien ve.","h2":"En el Distrito de Columbia, una persona con una licencia válida de otro país debe aprobar el examen de conocimientos y el examen de la vista para obtener una licencia de DC.","p":"Correcto. Con una licencia de otro país, tome el examen de conocimientos y el de la vista."},"ref":{"doc":"DC","page":12}},{"id":"dc-056","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, you move from another state with a valid license of the same class. What usually happens with the road skills test?","o":["You must pass it within 10 days","You must pass it before the eye test","It is usually waived, so you skip it","You must take it in a DMV vehicle"],"h1":"Your license from the other state already shows you can drive.","h2":"In the District of Columbia, the road skills test is generally waived when you change a valid out-of-state license of the same class to a DC license.","p":"Right. A valid out-of-state license usually means no road test."},"es":{"q":"En el Distrito de Columbia, usted se muda de otro estado con una licencia válida de la misma clase. ¿Qué pasa normalmente con el examen práctico de manejo?","o":["Debe aprobarlo en un plazo de 10 días","Debe aprobarlo antes del examen de la vista","Normalmente no se exige, así que no lo toma","Debe tomarlo en un vehículo del DMV"],"h1":"Su licencia del otro estado ya demuestra que sabe manejar.","h2":"En el Distrito de Columbia, normalmente no se exige el examen práctico de manejo cuando cambia una licencia válida de otro estado, de la misma clase, por una licencia de DC.","p":"Correcto. Con una licencia válida de otro estado, normalmente no hay examen práctico."},"ref":{"doc":"DC","page":12}},{"id":"dc-057","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, you have a learner permit and drive yourself alone to your road skills test. What happens?","o":["You will not be allowed to take the test","You take the test and pay a small fine","You take the test as planned","You take the test, but a week later"],"h1":"A learner may not drive without a licensed adult, even to the test.","h2":"In the District of Columbia, if you drive to your road test without a fully licensed driver 21 or older, you will not be able to take the test.","p":"Right. Come with a fully licensed driver 21 or older, or you cannot test."},"es":{"q":"En el Distrito de Columbia, usted tiene un permiso de aprendiz y maneja solo hasta su examen práctico de manejo. ¿Qué pasa?","o":["No le permitirán tomar el examen","Toma el examen y paga una multa pequeña","Toma el examen como estaba planeado","Toma el examen, pero una semana después"],"h1":"Un aprendiz no puede manejar sin un adulto con licencia, ni siquiera para ir al examen.","h2":"En el Distrito de Columbia, si maneja hasta su examen práctico sin un conductor con licencia completa de 21 años o más, no podrá tomar el examen.","p":"Correcto. Venga con un conductor con licencia completa de 21 años o más, o no podrá tomar el examen."},"ref":{"doc":"DC","page":13}},{"id":"dc-058","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, the car you bring for your road test has a small spare (donut) tire on one wheel. Can you use it for the test?","o":["Yes, if the tire has enough air","Yes, if it is on a back wheel","Yes, if you drive under 25 mph","No, donut spare tires are not accepted"],"h1":"The test car must have regular tires in good shape.","h2":"In the District of Columbia, a car with a spare donut tire is not accepted for the road skills test; its tires must be in good condition and properly inflated.","p":"Right. No donut spare tires on the test car."},"es":{"q":"En el Distrito de Columbia, el carro que trae para su examen práctico tiene una llanta de repuesto pequeña (tipo dona) en una rueda. ¿Puede usarlo para el examen?","o":["Sí, si la llanta tiene suficiente aire","Sí, si está en una rueda de atrás","Sí, si maneja a menos de 25 mph","No, no se aceptan llantas de repuesto tipo dona"],"h1":"El carro del examen debe tener llantas normales en buen estado.","h2":"En el Distrito de Columbia, no se acepta un carro con una llanta de repuesto tipo dona para el examen práctico; sus llantas deben estar en buen estado y bien infladas.","p":"Correcto. Nada de llantas de repuesto tipo dona en el carro del examen."},"ref":{"doc":"DC","page":13}},{"id":"dc-059","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, your learner permit has expired. How do you get a new one?","o":["Renew it online for two more years","Pass the knowledge test again","Pay a late fee at the DMV","Have your supervising driver sign a form"],"h1":"A learner permit cannot be renewed.","h2":"In the District of Columbia, a learner permit cannot be renewed; once it expires, you must pass the knowledge test again to get a new one.","p":"Right. An expired learner permit means taking the knowledge test again."},"es":{"q":"En el Distrito de Columbia, su permiso de aprendiz se venció. ¿Cómo obtiene uno nuevo?","o":["Renovándolo en línea por dos años más","Aprobando otra vez el examen de conocimientos","Pagando un recargo por atraso en el DMV","Pidiendo a su conductor supervisor que firme un formulario"],"h1":"El permiso de aprendiz no se puede renovar.","h2":"En el Distrito de Columbia, el permiso de aprendiz no se puede renovar; cuando se vence, debe aprobar otra vez el examen de conocimientos para obtener uno nuevo.","p":"Correcto. Con el permiso vencido, debe tomar otra vez el examen de conocimientos."},"ref":{"doc":"DC","page":14}},{"id":"dc-060","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, a 16-year-old wants a learner permit. Besides the knowledge test and vision screening, what is needed?","o":["A letter from the school principal","Proof of 40 hours of practice driving","A consent form signed by a parent or guardian","A paid insurance policy in their own name"],"h1":"Drivers under 18 need an adult to say yes.","h2":"In the District of Columbia, a learner permit applicant under 18 must bring a consent form signed by a parent or guardian, in addition to passing the knowledge test and vision screening.","p":"Right. Under 18, a parent or guardian must sign a consent form."},"es":{"q":"En el Distrito de Columbia, un joven de 16 años quiere un permiso de aprendiz. Además del examen de conocimientos y la prueba de la vista, ¿qué necesita?","o":["Una carta del director de la escuela","Prueba de 40 horas de práctica de manejo","Un formulario de consentimiento firmado por su padre, madre o tutor","Una póliza de seguro pagada a su propio nombre"],"h1":"Los conductores menores de 18 años necesitan el permiso de un adulto.","h2":"En el Distrito de Columbia, quien solicita un permiso de aprendiz y es menor de 18 años debe traer un formulario de consentimiento firmado por su padre, madre o tutor, además de aprobar el examen de conocimientos y la prueba de la vista.","p":"Correcto. Si es menor de 18, su padre, madre o tutor debe firmar un consentimiento."},"ref":{"doc":"DC","page":14}},{"id":"dc-061","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, a 17-year-old has a provisional license. May they drive for pay, such as making deliveries?","o":["No, not until they turn 18","Yes, during daytime hours only","Yes, with a parent's written OK","Yes, if each trip is short"],"h1":"Think about the age when GRAD limits on paid driving end.","h2":"In the District of Columbia, a provisional driver under 18 may not drive a vehicle for pay.","p":"Right. No driving for pay before age 18."},"es":{"q":"En el Distrito de Columbia, un joven de 17 años tiene una licencia provisional. ¿Puede manejar por pago, por ejemplo haciendo entregas?","o":["No, no hasta que cumpla 18 años","Sí, pero solo durante el día","Sí, con permiso escrito de sus padres","Sí, si cada viaje es corto"],"h1":"Piense en la edad en que terminan los límites de GRAD para manejar por pago.","h2":"En el Distrito de Columbia, un conductor con licencia provisional menor de 18 años no puede manejar un vehículo por pago.","p":"Correcto. No puede manejar por pago antes de los 18 años."},"ref":{"doc":"DC","page":15}},{"id":"dc-062","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, how long must a provisional driver go with no violations before moving to the full license with conditions?","o":["3 months in a row","6 months in a row","24 months in a row","12 months in a row"],"h1":"It is one full year.","h2":"In the District of Columbia, a provisional driver must be violation-free for 12 months in a row before moving to the full license with conditions.","p":"Right. Twelve months in a row with no violations."},"es":{"q":"En el Distrito de Columbia, ¿cuánto tiempo debe pasar un conductor con licencia provisional sin infracciones antes de pasar a la licencia completa con condiciones?","o":["3 meses seguidos","6 meses seguidos","24 meses seguidos","12 meses seguidos"],"h1":"Es un año completo.","h2":"En el Distrito de Columbia, un conductor con licencia provisional debe pasar 12 meses seguidos sin infracciones antes de pasar a la licencia completa con condiciones.","p":"Correcto. Doce meses seguidos sin infracciones."},"ref":{"doc":"DC","page":15}},{"id":"dc-063","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, who may ride with a provisional driver?","o":["Up to three friends of any age, sitting in any seat","One licensed adult 21+ in front, plus siblings, children or parents","Only passengers under 21, as long as they wear belts","Anyone at all, as long as there are five people or fewer"],"h1":"Family members are an exception to the limit.","h2":"In the District of Columbia, a provisional driver may carry one fully licensed adult 21 or older in the front seat, plus any siblings, their own child, or a parent.","p":"Right. One licensed adult 21 or older in front, plus close family."},"es":{"q":"En el Distrito de Columbia, ¿quién puede viajar con un conductor con licencia provisional?","o":["Hasta tres amigos de cualquier edad, sentados en cualquier asiento","Un adulto de 21+ con licencia adelante, más hermanos, hijos o padres","Solo pasajeros menores de 21, siempre que usen cinturón","Cualquier persona, siempre que sean cinco o menos en total"],"h1":"Los familiares son una excepción al límite.","h2":"En el Distrito de Columbia, un conductor con licencia provisional puede llevar a un adulto de 21 años o más con licencia completa en el asiento delantero, más sus hermanos, su propio hijo o un padre o madre.","p":"Correcto. Un adulto de 21 o más con licencia adelante, más familia cercana."},"ref":{"doc":"DC","page":15}},{"id":"dc-064","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, you have a provisional license. It is 11:30 p.m. on a Tuesday in October, and you are driving home from your job. Is this allowed?","o":["No, you must be off the road by 9:00 p.m.","No, the hour limits have no exceptions","Yes, driving to or from work is allowed","Only if a friend under 21 is with you"],"h1":"The GRAD hour limits have a few exceptions, such as a job.","h2":"In the District of Columbia, a provisional driver may drive during the restricted hours when going to or from work.","p":"Right. Trips to or from work are an exception to the hour limits."},"es":{"q":"En el Distrito de Columbia, usted tiene una licencia provisional. Son las 11:30 p.m. de un martes de octubre y maneja a casa desde su trabajo. ¿Está permitido?","o":["No, debe dejar de manejar a las 9:00 p.m.","No, los límites de horario no tienen excepciones","Sí, manejar hacia o desde el trabajo está permitido","Solo si va con un amigo menor de 21 años"],"h1":"Los límites de horario de GRAD tienen algunas excepciones, como el trabajo.","h2":"En el Distrito de Columbia, un conductor con licencia provisional puede manejar durante las horas restringidas cuando va hacia o desde el trabajo.","p":"Correcto. Ir o volver del trabajo es una excepción a los límites de horario."},"ref":{"doc":"DC","page":15}},{"id":"dc-065","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, when may you cancel the insurance on your registered car?","o":["Any time you stop driving it for a month","After you turn in your tags to the DMV","As soon as you park it for the winter","When your registration has one year left"],"h1":"Insurance must last as long as the car is registered.","h2":"In the District of Columbia, insurance must stay in place as long as the car is registered, so do not cancel it until you surrender your tags to the DMV.","p":"Right. Keep insurance until your tags are turned in; a lapse brings fines."},"es":{"q":"En el Distrito de Columbia, ¿cuándo puede cancelar el seguro de su carro registrado?","o":["Cuando deje de manejarlo por un mes","Después de entregar sus placas al DMV","En cuanto lo guarde durante el invierno","Cuando a su registro le quede un año"],"h1":"El seguro debe durar mientras el carro esté registrado.","h2":"En el Distrito de Columbia, el seguro debe mantenerse mientras el carro esté registrado, así que no lo cancele hasta que entregue sus placas al DMV.","p":"Correcto. Mantenga el seguro hasta entregar las placas; un periodo sin seguro trae multas."},"ref":{"doc":"DC","page":19}},{"id":"dc-066","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you get a ticket for a pointable moving violation and simply pay it. What happens with points?","o":["No points are added if you pay on time","Points are added only if you go to court","Points are added only after a second ticket","Points are added, because paying admits the violation"],"h1":"Paying the ticket counts as saying you did it.","h2":"In the District of Columbia, paying a ticket is an admission of liability, so the DMV adds points for the violation.","p":"Right. Paying the ticket means the points go on your record."},"es":{"q":"En el Distrito de Columbia, usted recibe una multa por una infracción de tránsito que da puntos y simplemente la paga. ¿Qué pasa con los puntos?","o":["No se suman puntos si paga a tiempo","Solo se suman puntos si va a la corte","Solo se suman puntos después de una segunda multa","Se le suman puntos, porque pagar es admitir la infracción"],"h1":"Pagar la multa cuenta como decir que usted lo hizo.","h2":"En el Distrito de Columbia, pagar una multa es admitir la responsabilidad, así que el DMV le suma los puntos por la infracción.","p":"Correcto. Si paga la multa, los puntos van a su historial."},"ref":{"doc":"DC","page":19}},{"id":"dc-067","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what can happen if you do not pay child support?","o":["Your license and car registration can be suspended","You must take the road skills test again","The DMV adds 12 points to your record","Nothing; it does not affect driving"],"h1":"The DMV can take away more than just your license.","h2":"In the District of Columbia, your driver license and vehicle registration can be suspended if you fail to pay child support.","p":"Right. Unpaid child support can cost you your license and registration."},"es":{"q":"En el Distrito de Columbia, ¿qué puede pasar si usted no paga la manutención de sus hijos?","o":["Le pueden suspender la licencia y el registro del carro","Debe tomar otra vez el examen práctico de manejo","El DMV le suma 12 puntos a su historial","Nada; no afecta su manejo"],"h1":"El DMV puede quitarle más que solo la licencia.","h2":"En el Distrito de Columbia, le pueden suspender la licencia de manejo y el registro del vehículo si no paga la manutención de sus hijos.","p":"Correcto. No pagar la manutención puede costarle la licencia y el registro."},"ref":{"doc":"DC","page":19}},{"id":"dc-068","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, you damage a parked car with no one in it, and you cannot find the owner. What must you do?","o":["Drive on, since no one was hurt","Wait 10 minutes, then drive away","Leave a written note with your details on the car","Only call your insurance company later"],"h1":"The owner needs a way to find you.","h2":"In the District of Columbia, if you damage an empty vehicle and cannot find the owner, you must leave a written notice with your name, address, and vehicle and insurance details in a place on it where it is easy to see and will stay put.","p":"Right. Leave a written note with your information on the car."},"es":{"q":"En el Distrito de Columbia, usted daña un carro estacionado sin nadie adentro y no puede encontrar al dueño. ¿Qué debe hacer?","o":["Seguir manejando, ya que nadie salió herido","Esperar 10 minutos y luego irse","Dejar en el carro una nota escrita con sus datos","Solo llamar más tarde a su compañía de seguros"],"h1":"El dueño necesita una forma de encontrarlo a usted.","h2":"En el Distrito de Columbia, si daña un vehículo vacío y no puede encontrar al dueño, debe dejar una nota escrita con su nombre, dirección y datos del vehículo y del seguro en un lugar del carro donde se vea fácilmente y no se caiga.","p":"Correcto. Deje en el carro una nota escrita con sus datos."},"ref":{"doc":"DC","page":22}},{"id":"dc-069","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, a snow emergency has been declared. What must vehicles on snow emergency routes use?","o":["Fog lights and hazard lights","Chains, snow tires, or radial tires","Four-wheel drive","Tires with extra air in them"],"h1":"These help your tires grip the snow.","h2":"In the District of Columbia, when a snow emergency is declared, vehicles on snow emergency routes must use chains, snow tires, or radial tires.","p":"Right. Chains, snow tires, or radial tires on snow emergency routes."},"es":{"q":"En el Distrito de Columbia, se ha declarado una emergencia por nieve. ¿Qué deben usar los vehículos en las rutas de emergencia por nieve?","o":["Luces antiniebla y luces intermitentes","Cadenas, llantas para nieve o llantas radiales","Tracción en las cuatro ruedas","Llantas con más aire de lo normal"],"h1":"Esto ayuda a que las llantas se agarren a la nieve.","h2":"En el Distrito de Columbia, cuando se declara una emergencia por nieve, los vehículos en las rutas de emergencia por nieve deben usar cadenas, llantas para nieve o llantas radiales.","p":"Correcto. Cadenas, llantas para nieve o radiales en las rutas de emergencia por nieve."},"ref":{"doc":"DC","page":28}},{"id":"dc-070","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, a school vehicle with flashing red lights is stopped on the other side of a divided highway. Must you stop?","o":["Yes, until the red lights turn off","Yes, at least 20 feet away from it","Yes, but only on school days","No, but you should still drive with care"],"h1":"A median or divider separates you from the children.","h2":"In the District of Columbia, you do not have to stop for a school vehicle that is on the other side of a divided highway, but you should still use care.","p":"Right. On a divided highway, traffic on the other side need not stop."},"es":{"q":"En el Distrito de Columbia, un vehículo escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida. ¿Debe detenerse usted?","o":["Sí, hasta que se apaguen las luces rojas","Sí, por lo menos a 20 pies de él","Sí, pero solo en días de escuela","No, pero aun así debe manejar con cuidado"],"h1":"Una división o separador lo separa a usted de los niños.","h2":"En el Distrito de Columbia, no tiene que detenerse por un vehículo escolar que está al otro lado de una carretera dividida, pero aun así debe tener cuidado.","p":"Correcto. En una carretera dividida, el tráfico del otro lado no tiene que detenerse."},"ref":{"doc":"DC","page":38}},{"id":"dc-071","scope":"DC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In the District of Columbia, may you pass a motorcycle while sharing its lane?","o":["No, passing it within its lane is illegal","Yes, if the rider stays near the edge","Yes, on streets with a 20 mph limit","Yes, if you sound your horn first"],"h1":"A motorcycle has the right to use the whole lane.","h2":"In the District of Columbia, it is against the law to overtake or pass a motorcycle within the same lane.","p":"Right. Never pass a motorcycle inside its own lane."},"es":{"q":"En el Distrito de Columbia, ¿puede rebasar a una motocicleta compartiendo su mismo carril?","o":["No, rebasarla dentro de su carril es ilegal","Sí, si el motociclista va cerca del borde","Sí, en calles con límite de 20 mph","Sí, si primero toca la bocina"],"h1":"Una motocicleta tiene derecho a usar todo el carril.","h2":"En el Distrito de Columbia, es ilegal alcanzar o rebasar a una motocicleta dentro del mismo carril.","p":"Correcto. Nunca rebase a una motocicleta dentro de su propio carril."},"ref":{"doc":"DC","page":38}},{"id":"dc-072","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, besides buses, which of these may travel in a bus lane?","o":["Taxis that have passengers","Cars with three or more people","Bicycles and emergency vehicles","Delivery trucks that are unloading"],"h1":"Think of riders who are not in cars, and vehicles going to help people.","h2":"In the District of Columbia, bus lanes are for transit, tour, charter, and school buses, and bicycles, paratransit, and emergency vehicles may also use them.","p":"Right. Bicycles and emergency vehicles may use bus lanes too."},"es":{"q":"En el Distrito de Columbia, además de los autobuses, ¿cuál de estos puede circular por un carril de autobús?","o":["Los taxis que llevan pasajeros","Los carros con tres o más personas","Las bicicletas y los vehículos de emergencia","Los camiones de reparto que están descargando"],"h1":"Piense en quienes no van en carro y en los vehículos que van a ayudar.","h2":"En el Distrito de Columbia, los carriles de autobús son para autobuses de transporte público, de turismo, chárter y escolares, y también los pueden usar las bicicletas, el transporte especial (paratransit) y los vehículos de emergencia.","p":"Correcto. Las bicicletas y los vehículos de emergencia también pueden usar los carriles de autobús."},"ref":{"doc":"DC","page":39}},{"id":"dc-073","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, what can happen if you park or stop in a streetcar guideway or next to a streetcar platform?","o":["Nothing, as long as you stay in the car","You can be fined and your car towed or impounded","Nothing, if you leave within 5 minutes","You only get a written warning"],"h1":"Streetcars cannot steer around a car in their way.","h2":"In the District of Columbia, parking, stopping, or standing in a streetcar guideway or next to a streetcar platform is against the law, and the vehicle can be fined and removed or impounded.","p":"Right. Stay out of the streetcar guideway, or face a fine and a tow."},"es":{"q":"En el Distrito de Columbia, ¿qué le puede pasar si se estaciona o se detiene en la vía del tranvía o junto a una plataforma del tranvía?","o":["Nada, mientras usted se quede en el carro","Le pueden multar y remolcar o incautar el carro","Nada, si se va en menos de 5 minutos","Solo recibe una advertencia por escrito"],"h1":"El tranvía no puede desviarse para esquivar un carro.","h2":"En el Distrito de Columbia, estacionarse, detenerse o quedarse parado en la vía del tranvía o junto a una plataforma del tranvía es ilegal, y el vehículo puede recibir una multa y ser removido o incautado.","p":"Correcto. No se detenga en la vía del tranvía, o tendrá multa y grúa."},"ref":{"doc":"DC","page":40}},{"id":"dc-074","scope":"DC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the District of Columbia, how far before a turn must you start using your turn signal?","o":["At least 10 feet","At least 25 feet","At least 1,000 feet","At least 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In the District of Columbia, you must signal continuously for at least 100 feet before you turn, and longer at higher speeds.","p":"Right. Signal for at least 100 feet before a turn."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia antes de una vuelta debe empezar a usar la direccional?","o":["Por lo menos a 10 pies","Por lo menos a 25 pies","Por lo menos a 1,000 pies","Por lo menos a 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"En el Distrito de Columbia, debe señalar sin parar por lo menos 100 pies antes de dar la vuelta, y por más distancia a mayor velocidad.","p":"Correcto. Señale por lo menos 100 pies antes de dar la vuelta."},"ref":{"doc":"DC","page":41}},{"id":"dc-075","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, on a two-lane road, within what distance of an intersection or railroad crossing must you not pass?","o":["Within 100 feet","Within 10 feet","Within 25 feet","Within 1 mile"],"h1":"Think of about one third of a football field.","h2":"In the District of Columbia, on a two-lane road, you must not pass when crossing or within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En el Distrito de Columbia, en una carretera de dos carriles, ¿a qué distancia de un cruce de calles o de un cruce de tren no debe rebasar?","o":["A menos de 100 pies","A menos de 10 pies","A menos de 25 pies","A menos de 1 milla"],"h1":"Piense en más o menos un tercio de una cancha de fútbol americano.","h2":"En el Distrito de Columbia, en una carretera de dos carriles, no debe rebasar al atravesar un cruce de calles o un cruce de tren, ni a menos de 100 pies de ellos.","p":"Correcto. No rebase a menos de 100 pies de un cruce de calles o de tren."},"ref":{"doc":"DC","page":41}},{"id":"dc-076","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, you see a vehicle stopped on the shoulder of a highway. What should you do?","o":["Speed up and pass it quickly","Stop behind it to offer help","Slow down and move left, away from it","Honk to warn the people near it"],"h1":"Give the people at the side of the road more space.","h2":"In the District of Columbia, when you see a vehicle stopped on the shoulder, slow down and move to the left part of your lane or to the next lane if there is one.","p":"Right. Slow down and give a stopped vehicle more room."},"es":{"q":"En el Distrito de Columbia, usted ve un vehículo detenido en el acotamiento de una carretera. ¿Qué debe hacer?","o":["Acelerar y pasarlo rápido","Detenerse detrás para ofrecer ayuda","Bajar la velocidad y moverse a la izquierda, lejos de él","Tocar la bocina para avisar a las personas"],"h1":"Dé más espacio a las personas al lado de la carretera.","h2":"En el Distrito de Columbia, cuando vea un vehículo detenido en el acotamiento, baje la velocidad y muévase a la parte izquierda de su carril o al carril de al lado, si lo hay.","p":"Correcto. Baje la velocidad y dé más espacio al vehículo detenido."},"ref":{"doc":"DC","page":42}},{"id":"dc-077","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, during which hours must your headlights be on?","o":["From exactly sunset until exactly sunrise each day","From 30 minutes after sunset to 30 minutes before sunrise","From 9:00 p.m. until 6:00 a.m. on every day","Only on streets that have no streetlights"],"h1":"The rule starts a little after the sun goes down.","h2":"In the District of Columbia, you must turn on your headlights from one half hour after sunset until one half hour before sunrise.","p":"Right. Lights on from half an hour after sunset to half an hour before sunrise."},"es":{"q":"En el Distrito de Columbia, ¿durante qué horas debe tener las luces delanteras encendidas?","o":["Justo desde la puesta del sol hasta la salida del sol","De media hora tras la puesta del sol a media hora antes del amanecer","Desde las 9:00 p.m. hasta las 6:00 a.m. todos los días","Solo en calles que no tienen alumbrado público"],"h1":"La regla empieza un poco después de que se pone el sol.","h2":"En el Distrito de Columbia, debe encender las luces delanteras desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Luces encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida."},"ref":{"doc":"DC","page":42}},{"id":"dc-078","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, you are about to drive through a tunnel on a sunny day. What must you do?","o":["Turn on your headlights","Turn on your hazard lights","Keep your lights off","Flash your high beams"],"h1":"It is a rule even in the middle of the day.","h2":"In the District of Columbia, you must turn on your headlights when you drive in a tunnel.","p":"Right. Headlights on in every tunnel."},"es":{"q":"En el Distrito de Columbia, usted va a pasar por un túnel en un día soleado. ¿Qué debe hacer?","o":["Encender las luces delanteras","Encender las luces intermitentes","Dejar las luces apagadas","Hacer cambio de luces altas"],"h1":"Es una regla incluso a mediodía.","h2":"En el Distrito de Columbia, debe encender las luces delanteras cuando maneja dentro de un túnel.","p":"Correcto. Luces delanteras encendidas en todo túnel."},"ref":{"doc":"DC","page":42}},{"id":"dc-079","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, you are using high beams and a car is coming toward you. When must you switch to low beams?","o":["At least 50 feet before you meet it","At least 100 feet before you meet it","Only if the other driver flashes lights","At least 500 feet before you meet it"],"h1":"Bright lights can blind a driver from far away.","h2":"In the District of Columbia, you must switch to low beams at least 500 feet before you meet an oncoming vehicle.","p":"Right. Dim your lights at least 500 feet before an oncoming car."},"es":{"q":"En el Distrito de Columbia, usted usa las luces altas y viene un carro de frente. ¿Cuándo debe cambiar a luces bajas?","o":["Por lo menos 50 pies antes de cruzarse con él","Por lo menos 100 pies antes de cruzarse con él","Solo si el otro conductor le hace cambio de luces","Por lo menos 500 pies antes de cruzarse con él"],"h1":"Las luces altas pueden encandilar a un conductor desde lejos.","h2":"En el Distrito de Columbia, debe cambiar a luces bajas por lo menos 500 pies antes de cruzarse con un vehículo que viene de frente.","p":"Correcto. Baje las luces por lo menos 500 pies antes de un carro que viene de frente."},"ref":{"doc":"DC","page":42}},{"id":"dc-080","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, a stop sign stands at the side of the road. How close in front of it may you stand or park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 25 feet","No closer than 75 feet"],"h1":"Drivers coming up must be able to see the sign clearly.","h2":"In the District of Columbia, you must not stand or park within 25 feet in front of a stop sign, flashing signal, or traffic signal at the side of the road.","p":"Right. Stay at least 25 feet back from a roadside stop sign or signal."},"es":{"q":"En el Distrito de Columbia, hay una señal de alto al lado de la calle. ¿A qué distancia delante de ella puede detenerse o estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 75 pies"],"h1":"Los conductores que se acercan deben poder ver bien la señal.","h2":"En el Distrito de Columbia, no debe detenerse ni estacionarse a menos de 25 pies delante de una señal de alto, una luz intermitente o un semáforo al lado de la calle.","p":"Correcto. Quédese por lo menos a 25 pies de una señal de alto o semáforo al lado de la calle."},"ref":{"doc":"DC","page":44}},{"id":"dc-081","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, how close to the entrance of a fire station driveway may you stand or park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 100 feet","As close as you like if you stay inside"],"h1":"Fire trucks need room to get out fast.","h2":"In the District of Columbia, you must not stand or park within 20 feet of the entrance to a fire station driveway.","p":"Right. Keep at least 20 feet from a fire station driveway."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia de la entrada de una estación de bomberos puede detenerse o estacionarse?","o":["No más cerca de 5 pies","No más cerca de 20 pies","No más cerca de 100 pies","Tan cerca como quiera si se queda adentro"],"h1":"Los camiones de bomberos necesitan espacio para salir rápido.","h2":"En el Distrito de Columbia, no debe detenerse ni estacionarse a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de una estación de bomberos."},"ref":{"doc":"DC","page":45}},{"id":"dc-082","scope":"DC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the District of Columbia, how close to the nearest rail of a railroad crossing may you park, unless you are loading or unloading?","o":["No closer than 10 feet","No closer than 25 feet","No closer than 200 feet","No closer than 50 feet"],"h1":"It is more than two car lengths, but far less than a city block.","h2":"In the District of Columbia, you must not park within 50 feet of the nearest rail of a railroad crossing, except for a short stop to load or unload.","p":"Right. Park at least 50 feet from the nearest rail."},"es":{"q":"En el Distrito de Columbia, ¿a qué distancia del riel más cercano de un cruce de tren puede estacionarse, a menos que esté cargando o descargando?","o":["No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 200 pies","No más cerca de 50 pies"],"h1":"Es más que el largo de dos carros, pero mucho menos que una cuadra.","h2":"En el Distrito de Columbia, no debe estacionarse a menos de 50 pies del riel más cercano de un cruce de tren, salvo una parada corta para cargar o descargar.","p":"Correcto. Estaciónese por lo menos a 50 pies del riel más cercano."},"ref":{"doc":"DC","page":45}},{"id":"dc-083","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is the speed limit in an alley when no sign is posted?","o":["15 mph","5 mph","20 mph","25 mph"],"h1":"It is lower than the limit on regular city streets.","h2":"In the District of Columbia, the speed limit in an alley is 15 mph unless a sign shows a different limit.","p":"Right. Alleys are 15 mph unless posted."},"es":{"q":"En el Distrito de Columbia, ¿cuál es el límite de velocidad en un callejón si no hay señal?","o":["15 mph","5 mph","20 mph","25 mph"],"h1":"Es más bajo que el límite de las calles normales de la ciudad.","h2":"En el Distrito de Columbia, el límite de velocidad en un callejón es de 15 mph, a menos que una señal indique otro límite.","p":"Correcto. En los callejones son 15 mph si no hay señal."},"ref":{"doc":"DC","page":46}},{"id":"dc-084","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, you drive faster than a yellow advisory speed sign shows and then have a crash. What can happen?","o":["Nothing, because advisory signs are never enforced","Your license is revoked on the spot","You may get a ticket for going too fast for conditions","Only your insurance price can change"],"h1":"The sign is advice, but the general speed rule still applies.","h2":"In the District of Columbia, an advisory speed sign is not a law by itself, but if you go faster and crash, you may be found to have broken the general speed rule and get a ticket.","p":"Right. Ignoring an advisory speed can still lead to a ticket after a crash."},"es":{"q":"En el Distrito de Columbia, usted maneja más rápido de lo que indica una señal amarilla de velocidad recomendada y luego choca. ¿Qué puede pasar?","o":["Nada, porque esas señales nunca se hacen cumplir","Le revocan la licencia en ese momento","Le pueden multar por ir demasiado rápido para las condiciones","Solo puede cambiar el precio de su seguro"],"h1":"La señal es un consejo, pero la regla general de velocidad sigue valiendo.","h2":"En el Distrito de Columbia, una señal de velocidad recomendada no es una ley por sí sola, pero si va más rápido y choca, pueden decidir que violó la regla general de velocidad y multarlo.","p":"Correcto. No hacer caso a la velocidad recomendada puede traer una multa después de un choque."},"ref":{"doc":"DC","page":46}},{"id":"dc-085","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, a passenger cannot wear a seat belt for a medical reason. What is needed for them to ride without one?","o":["A note from a parent or family member","A doctor's written certificate kept in the vehicle","A sticker placed on the windshield","Nothing; they may simply ride unbuckled"],"h1":"A licensed physician must put it in writing.","h2":"In the District of Columbia, a person with a medical reason not to wear a seat belt needs a physician's written certificate that states the reason, and it must be carried in the vehicle.","p":"Right. The doctor's certificate must be in the vehicle."},"es":{"q":"En el Distrito de Columbia, un pasajero no puede usar el cinturón de seguridad por una razón médica. ¿Qué necesita para viajar sin él?","o":["Una nota de su padre, madre u otro familiar","Un certificado escrito de un médico, guardado en el vehículo","Una calcomanía pegada en el parabrisas","Nada; puede viajar sin abrocharse"],"h1":"Un médico con licencia debe ponerlo por escrito.","h2":"En el Distrito de Columbia, una persona con una razón médica para no usar el cinturón necesita un certificado escrito de un médico que explique la razón, y debe llevarlo en el vehículo.","p":"Correcto. El certificado del médico debe estar en el vehículo."},"ref":{"doc":"DC","page":48}},{"id":"dc-086","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, children under what age must ride in an infant, toddler, or booster seat?","o":["Under 5 years old","Under 10 years old","Under 8 years old","Under 13 years old"],"h1":"Many children still need a booster seat in early grade school.","h2":"In the District of Columbia, children under 8 years old must ride in a properly installed infant, toddler, or booster seat.","p":"Right. Children under 8 ride in a child safety seat or booster."},"es":{"q":"En el Distrito de Columbia, ¿los niños menores de qué edad deben viajar en un asiento para bebé, para niño pequeño o elevado (booster)?","o":["Menores de 5 años","Menores de 10 años","Menores de 8 años","Menores de 13 años"],"h1":"Muchos niños todavía necesitan un asiento elevado en los primeros años de primaria.","h2":"En el Distrito de Columbia, los niños menores de 8 años deben viajar en un asiento para bebé, para niño pequeño o elevado (booster), bien instalado.","p":"Correcto. Los niños menores de 8 años van en asiento de seguridad o elevado."},"ref":{"doc":"DC","page":null}},{"id":"dc-087","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, may you use your turn signal to tell the driver behind you that it is safe to pass?","o":["No, that is against the law","Yes, use your left signal","Yes, use your right signal","Yes, but only on highways"],"h1":"Turn signals are only for showing what you are about to do.","h2":"In the District of Columbia, it is against the law to use your turn signals to tell drivers behind you that they can pass.","p":"Right. Never use your signals to wave someone past."},"es":{"q":"En el Distrito de Columbia, ¿puede usar la direccional para avisar al conductor de atrás que puede rebasar sin peligro?","o":["No, eso es ilegal","Sí, usando la direccional izquierda","Sí, usando la direccional derecha","Sí, pero solo en las carreteras"],"h1":"Las direccionales solo sirven para mostrar lo que usted va a hacer.","h2":"En el Distrito de Columbia, es ilegal usar las direccionales para avisar a los conductores de atrás que pueden rebasar.","p":"Correcto. Nunca use las direccionales para indicar a alguien que pase."},"ref":{"doc":"DC","page":55}},{"id":"dc-088","scope":"DC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the District of Columbia, a center lane has a solid and a broken yellow line on each side. How far may you drive in it before you turn left?","o":["No more than 25 feet","No more than 1,000 feet","As far as you like","No more than 150 feet"],"h1":"It is about half the length of a football field.","h2":"In the District of Columbia, in a center left-turn lane, you may not travel more than 150 feet.","p":"Right. Use the center turn lane for no more than 150 feet."},"es":{"q":"En el Distrito de Columbia, un carril central tiene una línea amarilla continua y una discontinua a cada lado. ¿Qué distancia puede recorrer en él antes de dar vuelta a la izquierda?","o":["No más de 25 pies","No más de 1,000 pies","La distancia que quiera","No más de 150 pies"],"h1":"Es más o menos la mitad de una cancha de fútbol americano.","h2":"En el Distrito de Columbia, en un carril central para dar vuelta a la izquierda, no puede recorrer más de 150 pies.","p":"Correcto. Use el carril central de vuelta por no más de 150 pies."},"ref":{"doc":"DC","page":58}},{"id":"dc-089","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the fine for using a hand-held phone while driving?","o":["$25","$100","$50","$500"],"h1":"It is a round number in the hundreds.","h2":"In the District of Columbia, the fine for using a hand-held phone while driving is $100.","p":"Right. A hand-held phone while driving costs $100."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la multa por usar un teléfono en la mano mientras maneja?","o":["$25","$100","$50","$500"],"h1":"Es un número redondo de cientos.","h2":"En el Distrito de Columbia, la multa por usar un teléfono en la mano mientras maneja es de $100.","p":"Correcto. Usar el teléfono en la mano al manejar cuesta $100."},"ref":{"doc":"DC","page":null}},{"id":"dc-090","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, you get a ticket for a moving violation inside a work zone. How is the fine set?","o":["It is the same as anywhere else","It is half the usual fine","Only a warning is given","It is double the usual fine"],"h1":"Signs at the start of work zones warn about this.","h2":"In the District of Columbia, the fine for a moving violation in a work zone is double the usual amount.","p":"Right. Fines are doubled in work zones."},"es":{"q":"En el Distrito de Columbia, usted recibe una multa por una infracción de tránsito dentro de una zona de trabajo. ¿Cómo se fija la multa?","o":["Es igual que en cualquier otro lugar","Es la mitad de la multa normal","Solo le dan una advertencia","Es el doble de la multa normal"],"h1":"Las señales al inicio de las zonas de trabajo avisan de esto.","h2":"En el Distrito de Columbia, la multa por una infracción de tránsito en una zona de trabajo es el doble de la cantidad normal.","p":"Correcto. Las multas se duplican en las zonas de trabajo."},"ref":{"doc":"DC","page":null}},{"id":"dc-091","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, a driver with a DC license is arrested for impaired driving and refuses the chemical test. What does the law require?","o":["They must join the Ignition Interlock program","Nothing; the test is optional","They pay a $25 fine and go home","They must take a safety class only"],"h1":"Refusing the test has its own penalty.","h2":"In the District of Columbia, a DC license holder who is arrested and refuses chemical testing must enroll in the Ignition Interlock program.","p":"Right. Refusing the test means joining the Ignition Interlock program."},"es":{"q":"En el Distrito de Columbia, un conductor con licencia de DC es arrestado por manejar bajo los efectos y se niega a la prueba química. ¿Qué exige la ley?","o":["Debe entrar al programa Ignition Interlock","Nada; la prueba es opcional","Paga una multa de $25 y se va a casa","Solo debe tomar una clase de seguridad"],"h1":"Negarse a la prueba tiene su propio castigo.","h2":"En el Distrito de Columbia, un conductor con licencia de DC que es arrestado y se niega a la prueba química debe inscribirse en el programa de bloqueo de encendido (Ignition Interlock).","p":"Correcto. Negarse a la prueba significa entrar al programa de bloqueo de encendido."},"ref":{"doc":"DC","page":null}},{"id":"dc-092","scope":"DC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the District of Columbia, how many points do you get for going 11 to 15 mph over the speed limit?","o":["1 point","3 points","6 points","12 points"],"h1":"It is more than a small violation, but far from a revocation.","h2":"In the District of Columbia, going 11 to 15 mph over the speed limit adds 3 points to your driving record.","p":"Right. 11 to 15 mph over the limit means 3 points."},"es":{"q":"En el Distrito de Columbia, ¿cuántos puntos recibe por ir de 11 a 15 mph por encima del límite de velocidad?","o":["1 punto","3 puntos","6 puntos","12 puntos"],"h1":"Es más que una falta pequeña, pero está lejos de una revocación.","h2":"En el Distrito de Columbia, ir de 11 a 15 mph por encima del límite de velocidad suma 3 puntos a su historial de manejo.","p":"Correcto. De 11 a 15 mph sobre el límite son 3 puntos."},"ref":{"doc":"DC","page":null}},{"id":"dc-093","scope":"DC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In the District of Columbia, how many points do you get for not yielding to an emergency vehicle that is using its siren and lights?","o":["2 points","1 point","No points, only a warning","6 points"],"h1":"This is one of the more serious violations on the point list.","h2":"In the District of Columbia, failing to yield the right-of-way to an emergency vehicle adds 6 points to your record.","p":"Right. Not yielding to an emergency vehicle costs 6 points."},"es":{"q":"En el Distrito de Columbia, ¿cuántos puntos recibe por no ceder el paso a un vehículo de emergencia que usa su sirena y sus luces?","o":["2 puntos","1 punto","Ningún punto, solo una advertencia","6 puntos"],"h1":"Es una de las faltas más graves de la lista de puntos.","h2":"En el Distrito de Columbia, no ceder el paso a un vehículo de emergencia suma 6 puntos a su historial.","p":"Correcto. No ceder el paso a un vehículo de emergencia cuesta 6 puntos."},"ref":{"doc":"DC","page":null}},{"id":"dc-094","scope":"DC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In the District of Columbia, what is the fine for passing a school bus that has its red lights flashing or its stop arm out?","o":["$500","$50","$100","$25"],"h1":"It is one of the highest fines on the moving violation list.","h2":"In the District of Columbia, the fine for passing a stopped school bus with flashing lights or its stop arm out is $500.","p":"Right. Passing a stopped school bus costs $500."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la multa por pasar un autobús escolar que tiene las luces rojas encendidas o el brazo de alto extendido?","o":["$500","$50","$100","$25"],"h1":"Es una de las multas más altas de la lista de infracciones de tránsito.","h2":"En el Distrito de Columbia, la multa por pasar un autobús escolar detenido con luces intermitentes o con el brazo de alto extendido es de $500.","p":"Correcto. Pasar un autobús escolar detenido cuesta $500."},"ref":{"doc":"DC","page":null}},{"id":"dc-095","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, a learner permit holder drives alone, with no licensed driver in the car. How many points are added?","o":["1 point","2 points","5 points","No points"],"h1":"Driving without a supervisor is treated as a serious permit violation.","h2":"In the District of Columbia, driving on a learner permit without a licensed driver adds 5 points to the record.","p":"Right. Driving alone on a learner permit means 5 points."},"es":{"q":"En el Distrito de Columbia, una persona con permiso de aprendiz maneja sola, sin un conductor con licencia en el auto. ¿Cuántos puntos se suman?","o":["1 punto","2 puntos","5 puntos","Ningún punto"],"h1":"Manejar sin supervisor se trata como una falta grave del permiso.","h2":"En el Distrito de Columbia, manejar con permiso de aprendiz sin un conductor con licencia suma 5 puntos al historial.","p":"Correcto. Manejar solo con permiso de aprendiz son 5 puntos."},"ref":{"doc":"DC","page":null}},{"id":"dc-096","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, when no sign shows other times, during which hours is the 15 mph school zone limit in effect?","o":["8:00 a.m. to 3:00 p.m.","Only when children are outside","6:00 a.m. to 7:00 p.m.","All day and all night"],"h1":"The default hours cover the whole school day and the time around it.","h2":"In the District of Columbia, unless a sign says otherwise, the 15 mph school zone limit applies from 6:00 a.m. to 7:00 p.m.","p":"Right. School zones are 15 mph from 6 a.m. to 7 p.m. unless signs say otherwise."},"es":{"q":"En el Distrito de Columbia, cuando ninguna señal indica otro horario, ¿en qué horas rige el límite de 15 mph en las zonas escolares?","o":["De 8:00 a.m. a 3:00 p.m.","Solo cuando hay niños afuera","De 6:00 a.m. a 7:00 p.m.","Todo el día y toda la noche"],"h1":"El horario normal cubre todo el día escolar y el tiempo alrededor.","h2":"En el Distrito de Columbia, si una señal no dice otra cosa, el límite de 15 mph en zonas escolares rige de 6:00 a.m. a 7:00 p.m.","p":"Correcto. Las zonas escolares son de 15 mph de 6 a.m. a 7 p.m., salvo que las señales digan otra cosa."},"ref":{"doc":"DC","page":null}},{"id":"dc-097","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, how fast over the speed limit counts as reckless driving, even with no other bad driving?","o":["20 mph or more over the limit","5 mph or more over the limit","10 mph or more over the limit","50 mph or more over the limit"],"h1":"The law names one speed that is reckless on its own.","h2":"In the District of Columbia, driving 20 mph or more over the speed limit is reckless driving.","p":"Right. 20 mph or more over the limit is reckless driving."},"es":{"q":"En el Distrito de Columbia, ¿cuánto por encima del límite de velocidad cuenta como manejo imprudente, aunque no haya otra mala conducta?","o":["20 mph o más sobre el límite","5 mph o más sobre el límite","10 mph o más sobre el límite","50 mph o más sobre el límite"],"h1":"La ley nombra una velocidad que por sí sola es imprudente.","h2":"En el Distrito de Columbia, manejar a 20 mph o más por encima del límite de velocidad es manejo imprudente.","p":"Correcto. 20 mph o más sobre el límite es manejo imprudente."},"ref":{"doc":"DC","page":null}},{"id":"dc-098","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, when is a driver guilty of aggressive driving?","o":["When they honk the horn at another driver once","When they drive 1 mph over the limit","When they change lanes with a turn signal","When they break 3 or more listed traffic rules within one mile"],"h1":"It takes several violations close together.","h2":"In the District of Columbia, aggressive driving means breaking 3 or more of the listed traffic rules at once or within one mile of driving.","p":"Right. Three or more listed violations within one mile is aggressive driving."},"es":{"q":"En el Distrito de Columbia, ¿cuándo es culpable un conductor de manejo agresivo?","o":["Cuando toca la bocina a otro conductor una vez","Cuando maneja 1 mph sobre el límite","Cuando cambia de carril usando la señal","Cuando viola 3 o más reglas de la lista dentro de una milla"],"h1":"Hacen falta varias faltas seguidas y cercanas.","h2":"En el Distrito de Columbia, manejo agresivo significa violar 3 o más de las reglas de tránsito de la lista a la vez o dentro de una milla de manejo.","p":"Correcto. Tres o más faltas de la lista dentro de una milla es manejo agresivo."},"ref":{"doc":"DC","page":null}},{"id":"dc-099","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, a car is stopped at a crosswalk so a person can cross. What is the fine for passing that car?","o":["$25","$500","$50","$75"],"h1":"The fine is set high because the walker may be hidden by the stopped car.","h2":"In the District of Columbia, the fine for passing a vehicle that is stopped at a crosswalk for a pedestrian is $500.","p":"Right. Passing a car stopped for a pedestrian costs $500."},"es":{"q":"En el Distrito de Columbia, un auto está detenido en un cruce peatonal para que una persona cruce. ¿Cuál es la multa por pasar a ese auto?","o":["$25","$500","$50","$75"],"h1":"La multa es alta porque el auto detenido puede ocultar al peatón.","h2":"En el Distrito de Columbia, la multa por pasar a un vehículo detenido en un cruce peatonal por un peatón es de $500.","p":"Correcto. Pasar a un auto detenido por un peatón cuesta $500."},"ref":{"doc":"DC","page":null}},{"id":"dc-100","scope":"DC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In the District of Columbia, a person is walking across the street in a crosswalk. When must you stop and stay stopped?","o":["Only when they are right in front of your car","When they are in your lane or one lane away from it","Only when a police officer is there","Only when they wave at you to stop"],"h1":"You do not wait until the person reaches your bumper.","h2":"In the District of Columbia, you must stop and stay stopped when a pedestrian in a crosswalk is in your lane or within one lane of it.","p":"Right. Stop when the walker is in your lane or one lane away."},"es":{"q":"En el Distrito de Columbia, una persona cruza la calle por un cruce peatonal. ¿Cuándo debe usted detenerse y quedarse detenido?","o":["Solo cuando está justo delante de su auto","Cuando está en su carril o a un carril de distancia","Solo cuando hay un policía presente","Solo cuando le hace señas para que pare"],"h1":"No espere a que la persona llegue a su parachoques.","h2":"En el Distrito de Columbia, usted debe detenerse y quedarse detenido cuando un peatón en el cruce está en su carril o a un carril de distancia.","p":"Correcto. Pare cuando el peatón está en su carril o a un carril de distancia."},"ref":{"doc":"DC","page":null}},{"id":"dc-101","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, you are taking home an opened bottle of wine. Where may it legally be in your car?","o":["In a cup holder","On the front seat","In a passenger's hand","In the trunk"],"h1":"It must be where no one in a seat can reach it.","h2":"In the District of Columbia, an opened alcohol container may be carried in the trunk or a locked compartment, not where people in the seats can reach it.","p":"Right. An opened bottle belongs in the trunk."},"es":{"q":"En el Distrito de Columbia, usted lleva a casa una botella de vino abierta. ¿Dónde puede ir legalmente en su auto?","o":["En un portavasos","En el asiento delantero","En la mano de un pasajero","En el maletero (cajuela)"],"h1":"Debe ir donde nadie sentado pueda alcanzarla.","h2":"En el Distrito de Columbia, un envase de alcohol abierto puede ir en el maletero o en un compartimiento cerrado con llave, no donde lo alcancen las personas sentadas.","p":"Correcto. Una botella abierta va en el maletero."},"ref":{"doc":"DC","page":null}},{"id":"dc-102","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, you have a minor crash and no one is hurt. Your car can still move. What should you do?","o":["Turn on your flashers and move off the road when safe","Leave the car where it is until police arrive","Drive away and call the DMV the next day","Stop in the lane and wait inside the car"],"h1":"The rule is about keeping traffic moving safely.","h2":"In the District of Columbia, after a crash or breakdown, you must turn on your emergency flashers and move the car off the roadway as soon as it is safe.","p":"Right. Flashers on, then move out of traffic when safe."},"es":{"q":"En el Distrito de Columbia, usted tiene un choque leve y nadie está herido. Su auto todavía puede moverse. ¿Qué debe hacer?","o":["Encender las luces intermitentes y salir de la vía cuando sea seguro","Dejar el auto donde está hasta que llegue la policía","Irse y llamar al DMV al día siguiente","Parar en el carril y esperar dentro del auto"],"h1":"La regla busca que el tránsito siga con seguridad.","h2":"En el Distrito de Columbia, después de un choque o una avería, debe encender las luces intermitentes de emergencia y sacar el auto de la vía en cuanto sea seguro.","p":"Correcto. Encienda las intermitentes y salga del tránsito cuando sea seguro."},"ref":{"doc":"DC","page":null}},{"id":"dc-103","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, government workers are sent home 2 hours early because of a weather emergency. When do the traffic rules that usually start at 4:00 p.m. begin?","o":["At 4:00 p.m., as usual","At 6:00 p.m.","At 2:00 p.m.","They are canceled for the day"],"h1":"The rush-hour rules move earlier by the same amount of time.","h2":"In the District of Columbia, when federal and DC workers are dismissed early for a weather emergency, rules that normally start at 4:00 p.m. start that many hours earlier, so 2 hours early means 2:00 p.m.","p":"Right. Two hours early means the 4 p.m. rules start at 2 p.m."},"es":{"q":"En el Distrito de Columbia, a los empleados del gobierno los mandan a casa 2 horas antes por una emergencia del clima. ¿Cuándo empiezan las reglas de tránsito que normalmente comienzan a las 4:00 p.m.?","o":["A las 4:00 p.m., como siempre","A las 6:00 p.m.","A las 2:00 p.m.","Se cancelan ese día"],"h1":"Las reglas de la hora pico se adelantan el mismo tiempo.","h2":"En el Distrito de Columbia, cuando a los empleados federales y de DC los despiden temprano por una emergencia del clima, las reglas que normalmente empiezan a las 4:00 p.m. se adelantan esas horas, así que 2 horas antes significa las 2:00 p.m.","p":"Correcto. Dos horas antes significa que las reglas de las 4 p.m. empiezan a las 2 p.m."},"ref":{"doc":"DC","page":null}},{"id":"dc-104","scope":"DC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the District of Columbia, when may you use tires with metal studs?","o":["All year, with no limits","Only in January and February","Only from October 15 through April 15","Never; they are always banned"],"h1":"They are allowed only during the cold months.","h2":"In the District of Columbia, studded tires may be used only from October 15 through April 15 each year.","p":"Right. Studded tires are allowed October 15 to April 15."},"es":{"q":"En el Distrito de Columbia, ¿cuándo puede usar llantas con clavos de metal?","o":["Todo el año, sin límites","Solo en enero y febrero","Solo del 15 de octubre al 15 de abril","Nunca; siempre están prohibidas"],"h1":"Se permiten solo en los meses fríos.","h2":"En el Distrito de Columbia, las llantas con clavos solo pueden usarse del 15 de octubre al 15 de abril de cada año.","p":"Correcto. Las llantas con clavos se permiten del 15 de octubre al 15 de abril."},"ref":{"doc":"DC","page":null}},{"id":"dc-105","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, where is riding a bicycle on the sidewalk generally not allowed?","o":["In the Central Business District (downtown)","In every part of the District","On any street with a bus stop","Near any school or park"],"h1":"Sidewalk riding is allowed in most areas, but not in the busiest one.","h2":"In the District of Columbia, bicyclists may ride on most sidewalks if they cause no hazard, but not in the Central Business District unless a sidewalk is specially allowed.","p":"Right. No bike riding on downtown (Central Business District) sidewalks."},"es":{"q":"En el Distrito de Columbia, ¿dónde, por lo general, no se permite andar en bicicleta por la acera?","o":["En el Distrito Comercial Central (el centro)","En todas partes del Distrito","En cualquier calle con parada de autobús","Cerca de cualquier escuela o parque"],"h1":"Se permite andar por la acera en la mayoría de las zonas, pero no en la más concurrida.","h2":"En el Distrito de Columbia, los ciclistas pueden andar por la mayoría de las aceras si no crean peligro, pero no en el Distrito Comercial Central, salvo en aceras especialmente permitidas.","p":"Correcto. No se anda en bicicleta por las aceras del centro (Distrito Comercial Central)."},"ref":{"doc":"DC","page":null}},{"id":"dc-106","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, you are stopped in traffic. May a bicyclist pass your car on the right side?","o":["No, bicyclists may only pass on the left","No, bicyclists must wait behind cars","Only if the bicyclist rings a bell first","Yes, bicyclists may pass on the left or right when safe"],"h1":"Bicyclists have more passing choices than cars do.","h2":"In the District of Columbia, a bicyclist may pass other vehicles on the left or the right when it is safe, so check your right side before you turn or open a door.","p":"Right. Bicyclists may pass on either side when safe."},"es":{"q":"En el Distrito de Columbia, usted está detenido en el tránsito. ¿Puede un ciclista pasar su auto por el lado derecho?","o":["No, los ciclistas solo pueden pasar por la izquierda","No, los ciclistas deben esperar detrás de los autos","Solo si el ciclista toca un timbre primero","Sí, los ciclistas pueden pasar por la izquierda o la derecha si es seguro"],"h1":"Los ciclistas tienen más opciones para pasar que los autos.","h2":"En el Distrito de Columbia, un ciclista puede pasar a otros vehículos por la izquierda o por la derecha cuando es seguro, así que revise su lado derecho antes de girar o abrir una puerta.","p":"Correcto. Los ciclistas pueden pasar por cualquier lado si es seguro."},"ref":{"doc":"DC","page":null}},{"id":"dc-107","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, who must wear a helmet when riding on a bicycle?","o":["Only riders under 10","Riders and passengers under 16","Everyone of any age","No one; helmets are optional"],"h1":"The rule covers children and young teens.","h2":"In the District of Columbia, anyone under 16 who rides on a bicycle, as the rider or a passenger, must wear a fastened helmet.","p":"Right. Everyone under 16 on a bicycle must wear a helmet."},"es":{"q":"En el Distrito de Columbia, ¿quién debe usar casco al andar en bicicleta?","o":["Solo ciclistas menores de 10 años","Ciclistas y pasajeros menores de 16 años","Todas las personas de cualquier edad","Nadie; el casco es opcional"],"h1":"La regla cubre a niños y adolescentes jóvenes.","h2":"En el Distrito de Columbia, toda persona menor de 16 años que va en una bicicleta, como ciclista o pasajero, debe usar un casco abrochado.","p":"Correcto. Todos los menores de 16 en bicicleta deben usar casco."},"ref":{"doc":"DC","page":null}},{"id":"dc-108","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, a motorcycle has no windscreen. Besides a helmet, what must the rider wear?","o":["A reflective vest","Goggles, a face shield, or safety-glass glasses","Leather gloves and boots","Nothing else is required"],"h1":"The rule protects the rider's eyes.","h2":"In the District of Columbia, a motorcycle operator without an approved windscreen must wear goggles, a face shield, or glasses with safety-glass lenses.","p":"Right. No windscreen means eye protection is required."},"es":{"q":"En el Distrito de Columbia, una motocicleta no tiene parabrisas. Además del casco, ¿qué debe usar el conductor?","o":["Un chaleco reflectante","Gafas protectoras, una careta o lentes de vidrio de seguridad","Guantes y botas de cuero","No se requiere nada más"],"h1":"La regla protege los ojos del motociclista.","h2":"En el Distrito de Columbia, el conductor de una motocicleta sin parabrisas aprobado debe usar gafas protectoras, una careta o lentes con cristales de seguridad.","p":"Correcto. Sin parabrisas, se requiere protección para los ojos."},"ref":{"doc":"DC","page":null}},{"id":"dc-109","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, besides passing the motorcycle knowledge test, what must you complete within the last 6 months to get a motorcycle endorsement?","o":["A first aid class","40 hours of supervised car driving","A road test in a car","A motorcycle demonstration course"],"h1":"It is a hands-on course on a motorcycle.","h2":"In the District of Columbia, to get a motorcycle endorsement, you must pass the motorcycle knowledge test and complete a motorcycle demonstration course within the last 6 months.","p":"Right. You need the knowledge test plus a motorcycle course."},"es":{"q":"En el Distrito de Columbia, además de aprobar el examen de conocimientos de motocicleta, ¿qué debe completar en los últimos 6 meses para obtener el endoso de motocicleta?","o":["Una clase de primeros auxilios","40 horas de manejo supervisado en auto","Un examen práctico en un auto","Un curso práctico de motocicleta"],"h1":"Es un curso práctico sobre una motocicleta.","h2":"En el Distrito de Columbia, para obtener el endoso de motocicleta, debe aprobar el examen de conocimientos de motocicleta y completar un curso práctico de motocicleta en los últimos 6 meses.","p":"Correcto. Necesita el examen de conocimientos y un curso de motocicleta."},"ref":{"doc":"DC","page":null}},{"id":"dc-110","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, what eyesight do you need to meet the usual vision standard, with or without glasses?","o":["20/40 in one eye and at least 20/70 in the other","20/20 in both eyes","20/100 in at least one eye","20/200 in both eyes"],"h1":"One eye must be fairly sharp; the other may be weaker.","h2":"In the District of Columbia, you need at least 20/40 vision in one eye and no worse than 20/70 in the other eye, with or without corrective lenses.","p":"Right. 20/40 in one eye and 20/70 or better in the other."},"es":{"q":"En el Distrito de Columbia, ¿qué visión necesita para cumplir la norma habitual, con o sin lentes?","o":["20/40 en un ojo y al menos 20/70 en el otro","20/20 en ambos ojos","20/100 en al menos un ojo","20/200 en ambos ojos"],"h1":"Un ojo debe ver bastante bien; el otro puede ver menos.","h2":"En el Distrito de Columbia, usted necesita al menos 20/40 de visión en un ojo y no menos de 20/70 en el otro, con o sin lentes correctivos.","p":"Correcto. 20/40 en un ojo y 20/70 o mejor en el otro."},"ref":{"doc":"DC","page":null}},{"id":"dc-111","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, a licensed driver learns they have glaucoma or cataracts. How soon must they bring a medical eye report to the DMV?","o":["Within 1 year","At the next license renewal","Within 30 days","Only if they have a crash"],"h1":"The DMV wants to know soon, not years later.","h2":"In the District of Columbia, a driver who develops glaucoma or cataracts must bring a medical eye report from an ophthalmologist to the DMV within 30 days.","p":"Right. Report glaucoma or cataracts within 30 days."},"es":{"q":"En el Distrito de Columbia, un conductor con licencia se entera de que tiene glaucoma o cataratas. ¿En cuánto tiempo debe llevar un informe médico de la vista al DMV?","o":["Dentro de 1 año","En la próxima renovación","Dentro de 30 días","Solo si tiene un choque"],"h1":"El DMV quiere saberlo pronto, no años después.","h2":"En el Distrito de Columbia, un conductor que desarrolla glaucoma o cataratas debe llevar al DMV un informe médico de un oftalmólogo dentro de 30 días.","p":"Correcto. Informe el glaucoma o las cataratas dentro de 30 días."},"ref":{"doc":"DC","page":null}},{"id":"dc-112","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, when does a regular driver license usually expire?","o":["On your birthday in the 4th year","Exactly 2 years after it is issued","On your birthday in the 8th year","It never expires"],"h1":"DC licenses last a long time.","h2":"In the District of Columbia, a regular driver license usually expires on your birthday in the eighth year of the license term.","p":"Right. A DC license usually lasts until your birthday in the 8th year."},"es":{"q":"En el Distrito de Columbia, ¿cuándo vence normalmente una licencia de conducir regular?","o":["En su cumpleaños del 4.º año","Exactamente 2 años después de emitida","En su cumpleaños del 8.º año","Nunca vence"],"h1":"Las licencias de DC duran mucho tiempo.","h2":"En el Distrito de Columbia, una licencia de conducir regular normalmente vence en su cumpleaños del octavo año de vigencia.","p":"Correcto. Una licencia de DC normalmente dura hasta su cumpleaños del 8.º año."},"ref":{"doc":"DC","page":null}},{"id":"dc-113","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how often must you renew your driver license in person instead of online?","o":["At least every other renewal","Every single renewal","Only once in your life","Never; online is always fine"],"h1":"Online renewal is allowed, but not every time.","h2":"In the District of Columbia, you may renew online only for every other renewal period, so at least every other renewal must be in person.","p":"Right. Online renewal works every other time; the rest are in person."},"es":{"q":"En el Distrito de Columbia, ¿cada cuánto debe renovar su licencia en persona en lugar de en línea?","o":["Al menos una renovación sí y otra no","En cada renovación","Solo una vez en la vida","Nunca; en línea siempre se puede"],"h1":"Se puede renovar en línea, pero no todas las veces.","h2":"En el Distrito de Columbia, solo puede renovar en línea una renovación sí y otra no, así que al menos una de cada dos renovaciones debe ser en persona.","p":"Correcto. En línea se puede una vez sí y otra no; las demás son en persona."},"ref":{"doc":"DC","page":null}},{"id":"dc-114","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you pass the knowledge test. How long do you have to bring your documents to a DMV service center?","o":["3 calendar days","6 months","2 years","14 business days"],"h1":"It is a little under three weeks of working days.","h2":"In the District of Columbia, after you pass the knowledge test, you must visit a DMV service center with your documents within 14 business days, or you will have to test again.","p":"Right. You have 14 business days, or you must retest."},"es":{"q":"En el Distrito de Columbia, usted aprueba el examen de conocimientos. ¿Cuánto tiempo tiene para llevar sus documentos a un centro de servicio del DMV?","o":["3 días calendario","6 meses","2 años","14 días hábiles"],"h1":"Son un poco menos de tres semanas de días laborables.","h2":"En el Distrito de Columbia, después de aprobar el examen de conocimientos, debe ir a un centro de servicio del DMV con sus documentos dentro de 14 días hábiles, o tendrá que tomar el examen otra vez.","p":"Correcto. Tiene 14 días hábiles, o debe repetir el examen."},"ref":{"doc":"DC","page":null}},{"id":"dc-115","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, you use your phone during the knowledge test. What happens?","o":["You get a warning and keep going","You fail and must wait 60 days to test again","You may retest the same day","Your score is lowered by one question"],"h1":"Using a phone counts as cheating.","h2":"In the District of Columbia, using a phone, watch, or notes during the knowledge test is cheating; you fail and may not retest for 60 days.","p":"Right. Cheating means a fail and a 60-day wait."},"es":{"q":"En el Distrito de Columbia, usted usa su teléfono durante el examen de conocimientos. ¿Qué pasa?","o":["Recibe una advertencia y sigue","Reprueba y debe esperar 60 días para repetirlo","Puede repetirlo el mismo día","Le bajan una pregunta de la nota"],"h1":"Usar un teléfono cuenta como hacer trampa.","h2":"En el Distrito de Columbia, usar un teléfono, un reloj o notas durante el examen de conocimientos es hacer trampa; usted reprueba y no puede repetirlo por 60 días.","p":"Correcto. Hacer trampa significa reprobar y esperar 60 días."},"ref":{"doc":"DC","page":null}},{"id":"dc-116","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what kind of documents does the DMV accept when you apply for a driver license?","o":["Notarized photocopies","Original documents only","Photos on your phone","Copies faxed by a friend"],"h1":"Copies of any kind are turned away.","h2":"In the District of Columbia, you must bring original documents; photocopies, notarized copies, and altered documents are not accepted.","p":"Right. Bring originals, not copies."},"es":{"q":"En el Distrito de Columbia, ¿qué tipo de documentos acepta el DMV cuando usted solicita una licencia de conducir?","o":["Fotocopias notariadas","Solo documentos originales","Fotos en su teléfono","Copias enviadas por fax por un amigo"],"h1":"Las copias de cualquier tipo no se aceptan.","h2":"En el Distrito de Columbia, debe llevar documentos originales; no se aceptan fotocopias, copias notariadas ni documentos alterados.","p":"Correcto. Lleve originales, no copias."},"ref":{"doc":"DC","page":null}},{"id":"dc-117","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, you get a DC driver license while you still have a license from another state. What happens to the other license?","o":["You may keep using both","It becomes your backup license","It stays valid until it expires","It is cancelled"],"h1":"You may hold only one state's license at a time.","h2":"In the District of Columbia, when you get a DC driver license, any license or ID card issued to you by another state is cancelled.","p":"Right. Your old state license is cancelled."},"es":{"q":"En el Distrito de Columbia, usted obtiene una licencia de DC mientras todavía tiene una licencia de otro estado. ¿Qué pasa con la otra licencia?","o":["Puede seguir usando las dos","Se convierte en su licencia de respaldo","Sigue válida hasta que venza","Se cancela"],"h1":"Solo puede tener la licencia de un estado a la vez.","h2":"En el Distrito de Columbia, cuando usted obtiene una licencia de conducir de DC, se cancela cualquier licencia o identificación emitida por otro estado.","p":"Correcto. Su licencia del otro estado se cancela."},"ref":{"doc":"DC","page":null}},{"id":"dc-118","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, how long is a vehicle inspection valid for a personal car?","o":["2 years","6 months","1 year","10 years"],"h1":"Commercial vehicles need it more often than personal cars.","h2":"In the District of Columbia, the inspection for a personal vehicle is valid for 2 years.","p":"Right. A personal car inspection lasts 2 years."},"es":{"q":"En el Distrito de Columbia, ¿por cuánto tiempo es válida la inspección de un auto personal?","o":["2 años","6 meses","1 año","10 años"],"h1":"Los vehículos comerciales la necesitan más seguido que los autos personales.","h2":"En el Distrito de Columbia, la inspección de un vehículo personal es válida por 2 años.","p":"Correcto. La inspección de un auto personal dura 2 años."},"ref":{"doc":"DC","page":null}},{"id":"dc-119","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, how can you renew your vehicle registration?","o":["Only in person at a DMV office","Only at a police station","Online or by mail only","Only at the inspection station"],"h1":"You do not stand in line for this one.","h2":"In the District of Columbia, vehicle registrations cannot be renewed in person; they are renewed online or by mail.","p":"Right. Registration renewal is online or by mail."},"es":{"q":"En el Distrito de Columbia, ¿cómo puede renovar el registro de su vehículo?","o":["Solo en persona en una oficina del DMV","Solo en una estación de policía","Solo en línea o por correo","Solo en la estación de inspección"],"h1":"Para esto no tiene que hacer fila.","h2":"En el Distrito de Columbia, el registro del vehículo no se puede renovar en persona; se renueva en línea o por correo.","p":"Correcto. La renovación del registro es en línea o por correo."},"ref":{"doc":"DC","page":null}},{"id":"dc-120","scope":"DC","cat":"licensing","sign":null,"c":2,"en":{"q":"In the District of Columbia, what is the fine for driving with a clear plastic or glass cover over your license plate?","o":["$10","$25","$500","No fine if the plate is readable"],"h1":"Covers are banned even when the plate can still be read.","h2":"In the District of Columbia, driving with glass, plastic, or any other cover over your license plate brings a $500 fine.","p":"Right. A plate cover costs $500."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la multa por manejar con una cubierta de plástico o vidrio transparente sobre su placa?","o":["$10","$25","$500","Ninguna, si la placa se puede leer"],"h1":"Las cubiertas están prohibidas aunque la placa se pueda leer.","h2":"En el Distrito de Columbia, manejar con vidrio, plástico u otra cubierta sobre la placa tiene una multa de $500.","p":"Correcto. Una cubierta de placa cuesta $500."},"ref":{"doc":"DC","page":null}},{"id":"dc-121","scope":"DC","cat":"licensing","sign":null,"c":0,"en":{"q":"In the District of Columbia, you sell your car and are not getting another one. What must you do with your plates?","o":["Remove them and return them to the DMV within 5 business days","Leave them on the car for the buyer","Keep them at home for future use","Throw them away in the trash"],"h1":"The plates belong to you, not to the car or the buyer.","h2":"In the District of Columbia, when you sell your car, you must take off your plates and, unless you get another vehicle, return them with the registration card to the DMV within 5 business days.","p":"Right. Take the plates off and turn them in within 5 business days."},"es":{"q":"En el Distrito de Columbia, usted vende su auto y no va a comprar otro. ¿Qué debe hacer con sus placas?","o":["Quitarlas y devolverlas al DMV dentro de 5 días hábiles","Dejarlas en el auto para el comprador","Guardarlas en casa para usarlas después","Tirarlas a la basura"],"h1":"Las placas son suyas, no del auto ni del comprador.","h2":"En el Distrito de Columbia, cuando vende su auto, debe quitar las placas y, si no obtiene otro vehículo, devolverlas con la tarjeta de registro al DMV dentro de 5 días hábiles.","p":"Correcto. Quite las placas y entréguelas dentro de 5 días hábiles."},"ref":{"doc":"DC","page":null}},{"id":"dc-122","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, you carry loose debris in an open truck bed, piled higher than the sides. What must you do?","o":["Drive below 15 mph with flashers on","Nothing, if the trip is short","Put a red flag on top of the pile","Cover and secure it so nothing can blow out"],"h1":"Loose material must not be able to fly off.","h2":"In the District of Columbia, loose debris or cargo that could fall out must be covered and secured, unless it stays at least 6 inches below the top of the sides.","p":"Right. Cover and tie down a loose load."},"es":{"q":"En el Distrito de Columbia, usted lleva escombros sueltos en la caja abierta de una camioneta, amontonados más alto que los lados. ¿Qué debe hacer?","o":["Manejar a menos de 15 mph con intermitentes","Nada, si el viaje es corto","Poner una bandera roja encima del montón","Cubrirlos y asegurarlos para que nada salga volando"],"h1":"El material suelto no debe poder salir volando.","h2":"En el Distrito de Columbia, los escombros o la carga suelta que puedan caerse deben ir cubiertos y asegurados, salvo que queden al menos 6 pulgadas por debajo del borde de los lados.","p":"Correcto. Cubra y asegure una carga suelta."},"ref":{"doc":"DC","page":null}},{"id":"dc-123","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, besides possible jail time, what fine does the law set for a first DUI conviction?","o":["$50","$1,000","$200","$25,000"],"h1":"It is a four-digit amount.","h2":"In the District of Columbia, a first conviction for driving under the influence carries a $1,000 fine, up to 180 days in jail, or both.","p":"Right. A first DUI means a $1,000 fine and possible jail."},"es":{"q":"En el Distrito de Columbia, además de una posible cárcel, ¿qué multa fija la ley por una primera condena por DUI?","o":["$50","$1,000","$200","$25,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En el Distrito de Columbia, una primera condena por manejar bajo los efectos del alcohol o drogas tiene una multa de $1,000, hasta 180 días de cárcel, o ambas.","p":"Correcto. Un primer DUI significa una multa de $1,000 y posible cárcel."},"ref":{"doc":"DC","page":null}},{"id":"dc-124","scope":"DC","cat":"licensing","sign":null,"c":1,"en":{"q":"In the District of Columbia, what is the longest jail sentence for driving while your license is suspended or revoked?","o":["Up to 1 day","Up to 1 year","Up to 10 years","There is no jail, only a fine"],"h1":"It is a crime, not just a ticket.","h2":"In the District of Columbia, driving while your license is suspended or revoked can bring up to 1 year in jail, a fine, or both, for each offense.","p":"Right. Driving on a suspended license can mean up to 1 year in jail."},"es":{"q":"En el Distrito de Columbia, ¿cuál es la pena de cárcel más larga por manejar con la licencia suspendida o revocada?","o":["Hasta 1 día","Hasta 1 año","Hasta 10 años","No hay cárcel, solo multa"],"h1":"Es un delito, no solo una multa.","h2":"En el Distrito de Columbia, manejar con la licencia suspendida o revocada puede dar hasta 1 año de cárcel, una multa, o ambas, por cada vez.","p":"Correcto. Manejar con licencia suspendida puede significar hasta 1 año de cárcel."},"ref":{"doc":"DC","page":null}},{"id":"dc-125","scope":"DC","cat":"licensing","sign":null,"c":3,"en":{"q":"In the District of Columbia, a teen driver breaks a GRAD rule for the second time. How long is the permit or license suspended?","o":["7 days","30 days","2 years","60 days"],"h1":"The suspension grows with each new violation.","h2":"In the District of Columbia, a second GRAD violation brings a 60-day suspension of the permit or license.","p":"Right. A second GRAD violation means 60 days."},"es":{"q":"En el Distrito de Columbia, un conductor joven viola una regla de GRAD por segunda vez. ¿Por cuánto tiempo se suspende su permiso o licencia?","o":["7 días","30 días","2 años","60 días"],"h1":"La suspensión crece con cada nueva falta.","h2":"En el Distrito de Columbia, una segunda falta de GRAD trae una suspensión de 60 días del permiso o la licencia.","p":"Correcto. Una segunda falta de GRAD significa 60 días."},"ref":{"doc":"DC","page":null}},{"id":"dc-126","scope":"DC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the District of Columbia, may you make a U-turn across a bicycle lane?","o":["No, a U-turn across a bike lane is not allowed","Yes, if no bicyclist is in sight","Yes, but only at night","Yes, if you use your turn signal"],"h1":"Bike lanes get special protection from this move.","h2":"In the District of Columbia, no vehicle may make a U-turn across a bicycle lane.","p":"Right. No U-turns across a bike lane."},"es":{"q":"En el Distrito de Columbia, ¿puede hacer una vuelta en U atravesando un carril para bicicletas?","o":["No, no se permite atravesar un carril para bicicletas","Sí, si no se ve ningún ciclista","Sí, pero solo de noche","Sí, si usa la luz direccional"],"h1":"Los carriles para bicicletas tienen protección especial contra esta maniobra.","h2":"En el Distrito de Columbia, ningún vehículo puede hacer una vuelta en U atravesando un carril para bicicletas.","p":"Correcto. Nada de vueltas en U por un carril para bicicletas."},"ref":{"doc":"DC","page":null}},{"id":"dc-127","scope":"DC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the District of Columbia, where is it against the law to drive on the left side of the road to pass another vehicle?","o":["On any straight, open road","On a road with a broken center line","On a bridge or in a tunnel","On a one-way street"],"h1":"Think of places where there is no room to escape.","h2":"In the District of Columbia, you may not drive on the left side to pass on a bridge, viaduct, or tunnel, or within 100 feet of one.","p":"Right. No passing on the left on bridges or in tunnels."},"es":{"q":"En el Distrito de Columbia, ¿dónde es ilegal manejar por el lado izquierdo de la vía para pasar a otro vehículo?","o":["En cualquier camino recto y despejado","En una vía con línea central discontinua","En un puente o en un túnel","En una calle de un solo sentido"],"h1":"Piense en lugares donde no hay espacio para escapar.","h2":"En el Distrito de Columbia, no puede manejar por el lado izquierdo para pasar en un puente, viaducto o túnel, ni a menos de 100 pies de uno.","p":"Correcto. No se pasa por la izquierda en puentes ni túneles."},"ref":{"doc":"DC","page":null}},{"id":"dc-128","scope":"DC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In the District of Columbia, a transit bus at a stop signals that it is pulling back into traffic in front of you. What must you do?","o":["Speed up to pass it first","Honk so the bus waits","Yield and let the bus pull in","Change lanes without looking"],"h1":"Buses get the right-of-way when they signal to re-enter.","h2":"In the District of Columbia, drivers behind or next to a transit bus must yield to the bus when it signals that it is re-entering traffic.","p":"Right. Let the bus back into traffic."},"es":{"q":"En el Distrito de Columbia, un autobús de transporte público en una parada señala que va a volver al tránsito delante de usted. ¿Qué debe hacer?","o":["Acelerar para pasarlo primero","Tocar la bocina para que espere","Ceder el paso y dejar que el autobús entre","Cambiar de carril sin mirar"],"h1":"Los autobuses tienen el derecho de paso cuando señalan que vuelven al tránsito.","h2":"En el Distrito de Columbia, los conductores detrás o al lado de un autobús de transporte público deben cederle el paso cuando señala que vuelve al tránsito.","p":"Correcto. Deje que el autobús vuelva al tránsito."},"ref":{"doc":"DC","page":null}},{"id":"dc-129","scope":"DC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the District of Columbia, your car has more people than seat belts. Who must get the seats with belts first?","o":["Children 16 and under","The oldest passengers","The people who got in first","Adults in the front seat"],"h1":"Young passengers come first.","h2":"In the District of Columbia, the driver must make sure children 16 and under get the seats with seat belts before older passengers.","p":"Right. Kids 16 and under get the belted seats first."},"es":{"q":"En el Distrito de Columbia, su auto lleva más personas que cinturones. ¿Quién debe recibir primero los asientos con cinturón?","o":["Los niños de 16 años o menos","Los pasajeros de más edad","Las personas que subieron primero","Los adultos del asiento delantero"],"h1":"Los pasajeros jóvenes van primero.","h2":"En el Distrito de Columbia, el conductor debe asegurarse de que los niños de 16 años o menos reciban los asientos con cinturón antes que los pasajeros mayores.","p":"Correcto. Los niños de 16 o menos reciben primero los asientos con cinturón."},"ref":{"doc":"DC","page":null}},{"id":"dc-130","scope":"DC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the District of Columbia, a driver breaks the child safety seat law for the first time. What choice do they get?","o":["Pay $500 or lose the license","A warning with no fine at all","Spend one night in jail","Pay a $75 fine or take a $25 safety class"],"h1":"First-time offenders can learn instead of paying the full fine.","h2":"In the District of Columbia, a first-time child restraint violator may pay a $75 fine or attend a child restraint safety class that costs $25.","p":"Right. First offense: a $75 fine or a $25 safety class."},"es":{"q":"En el Distrito de Columbia, un conductor viola por primera vez la ley de asientos de seguridad para niños. ¿Qué opción tiene?","o":["Pagar $500 o perder la licencia","Una advertencia sin ninguna multa","Pasar una noche en la cárcel","Pagar $75 de multa o tomar una clase de $25"],"h1":"Quien lo hace por primera vez puede aprender en lugar de pagar toda la multa.","h2":"En el Distrito de Columbia, quien viola por primera vez la ley de asientos para niños puede pagar una multa de $75 o asistir a una clase de seguridad que cuesta $25.","p":"Correcto. Primera vez: multa de $75 o una clase de $25."},"ref":{"doc":"DC","page":null}},{"id":"dc-131","scope":"DC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In the District of Columbia, on a regular car (not a minivan), how much light must the front side windows let through?","o":["At least 5%","At least 70%","At least 20%","Any amount is fine"],"h1":"Front windows must stay quite clear.","h2":"In the District of Columbia, the windshield and front side windows of a regular car must let at least 70 percent of light through.","p":"Right. Front side windows must pass at least 70% of light."},"es":{"q":"En el Distrito de Columbia, en un auto regular (no una minivan), ¿cuánta luz deben dejar pasar las ventanas laterales delanteras?","o":["Al menos el 5%","Al menos el 70%","Al menos el 20%","Cualquier cantidad está bien"],"h1":"Las ventanas delanteras deben ser bastante claras.","h2":"En el Distrito de Columbia, el parabrisas y las ventanas laterales delanteras de un auto regular deben dejar pasar al menos el 70 por ciento de la luz.","p":"Correcto. Las ventanas laterales delanteras deben dejar pasar al menos el 70% de la luz."},"ref":{"doc":"DC","page":null}},{"id":"de-001","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what is the youngest age to get a Level 1 learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is a later age than in many other states.","h2":"In Delaware you can get a Level 1 learner's permit at 16, after you finish an approved driver education course.","p":"Right. Delaware starts the learner's permit at 16."},"es":{"q":"En Delaware, ¿cuál es la edad mínima para obtener el permiso de aprendiz de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es una edad mayor que en muchos otros estados.","h2":"En Delaware usted puede obtener el permiso de aprendiz de Nivel 1 a los 16 años, después de terminar un curso aprobado de educación vial.","p":"Correcto. En Delaware el permiso de aprendiz empieza a los 16."},"zh":{"q":"在 Delaware，最小几岁可以拿到 Level 1 学习驾照？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比很多其他州的年龄大。","h2":"在 Delaware，你完成认可的驾驶教育课程以后，16 岁可以拿到 Level 1 学习驾照。","p":"对。Delaware 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Delaware, tuổi nhỏ nhất để được cấp giấy phép tập lái Level 1 (Level 1 learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn so với nhiều tiểu bang khác.","h2":"Ở Delaware, bạn có thể được cấp giấy phép tập lái Level 1 khi 16 tuổi, sau khi học xong một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Delaware bắt đầu giấy phép tập lái từ 16 tuổi."},"tl":{"q":"Sa Delaware, ilang taon ang pinakabatang edad para makakuha ng Level 1 learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas matanda ang edad na ito kaysa sa maraming ibang estado.","h2":"Sa Delaware, puwede kang kumuha ng Level 1 learner's permit sa edad na 16, pagkatapos mong matapos ang isang aprubadong kurso sa driver education.","p":"Tama. Nagsisimula ang learner's permit sa Delaware sa edad na 16."},"ar":{"q":"في Delaware، ما أصغر عمر للحصول على رخصة متعلم من المستوى الأول (Level 1 learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر أكبر منه في كثير من الولايات الأخرى.","h2":"في Delaware يمكنك الحصول على رخصة متعلم من المستوى الأول في عمر 16 سنة، بعد أن تنهي دورة معتمدة لتعليم القيادة.","p":"صحيح. تبدأ رخصة المتعلم في Delaware في عمر 16 سنة."},"ref":{"doc":"DE","page":28}},{"id":"de-002","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what must a teen finish before getting a Level 1 learner's permit?","o":["An approved driver education course","A road test","A year of driving on a farm","A first aid course"],"h1":"Think of the classes that teach driving.","h2":"A Delaware teen must finish an approved driver education course before getting the Level 1 learner's permit.","p":"Right. Driver education comes first in Delaware."},"es":{"q":"En Delaware, ¿qué debe terminar un adolescente antes de obtener el permiso de aprendiz de Nivel 1?","o":["Un curso aprobado de educación vial","Un examen de manejo en la calle","Un año de manejo en una granja","Un curso de primeros auxilios"],"h1":"Piense en las clases que enseñan a manejar.","h2":"Un adolescente en Delaware debe terminar un curso aprobado de educación vial antes de obtener el permiso de aprendiz de Nivel 1.","p":"Correcto. En Delaware la educación vial va primero."},"zh":{"q":"在 Delaware，青少年拿 Level 1 学习驾照前必须完成什么？","o":["认可的驾驶教育课程","路考","在农场开车一年","急救课程"],"h1":"想一想教开车的课。","h2":"Delaware 的青少年拿 Level 1 学习驾照前，必须完成认可的驾驶教育课程。","p":"对。在 Delaware，先上驾驶教育课。"},"vi":{"q":"Ở Delaware, thiếu niên phải hoàn thành điều gì trước khi được cấp giấy phép tập lái Level 1?","o":["Một khóa giáo dục lái xe được chấp thuận (driver education)","Một bài thi lái xe trên đường","Một năm lái xe ở nông trại","Một khóa sơ cứu"],"h1":"Hãy nghĩ đến các lớp học dạy lái xe.","h2":"Thiếu niên ở Delaware phải học xong một khóa giáo dục lái xe được chấp thuận trước khi được cấp giấy phép tập lái Level 1.","p":"Đúng. Ở Delaware, giáo dục lái xe phải có trước."},"tl":{"q":"Sa Delaware, ano ang dapat tapusin ng isang teen bago makakuha ng Level 1 learner's permit?","o":["Isang aprubadong kurso sa driver education","Isang road test","Isang taon ng pagmamaneho sa bukid","Isang kurso sa first aid"],"h1":"Isipin ang mga klase na nagtuturo ng pagmamaneho.","h2":"Dapat tapusin ng isang teen sa Delaware ang isang aprubadong kurso sa driver education bago makakuha ng Level 1 learner's permit.","p":"Tama. Driver education muna sa Delaware."},"ar":{"q":"في Delaware، ماذا يجب أن ينهي المراهق قبل الحصول على رخصة متعلم من المستوى الأول؟","o":["دورة معتمدة لتعليم القيادة (driver education)","اختبار قيادة على الطريق","سنة من القيادة في مزرعة","دورة إسعافات أولية"],"h1":"فكّر في الدروس التي تعلّم القيادة.","h2":"يجب على المراهق في Delaware أن ينهي دورة معتمدة لتعليم القيادة قبل الحصول على رخصة متعلم من المستوى الأول.","p":"صحيح. تعليم القيادة يأتي أولًا في Delaware."},"ref":{"doc":"DE","page":28}},{"id":"de-003","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long does a Level 1 learner's permit let a teen drive?","o":["6 months","12 months","18 months","24 months"],"h1":"It is one full year.","h2":"A Delaware Level 1 learner's permit lets a teen drive under its rules for 12 months.","p":"Right. The Delaware permit lasts 12 months."},"es":{"q":"En Delaware, ¿por cuánto tiempo permite manejar el permiso de aprendiz de Nivel 1?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año completo.","h2":"El permiso de aprendiz de Nivel 1 de Delaware permite manejar bajo sus reglas durante 12 meses.","p":"Correcto. El permiso de Delaware dura 12 meses."},"zh":{"q":"在 Delaware，Level 1 学习驾照让青少年开车多久？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"它是整整一年。","h2":"Delaware 的 Level 1 学习驾照让青少年按它的规定开车 12 个月。","p":"对。Delaware 的学习驾照有效 12 个月。"},"vi":{"q":"Ở Delaware, giấy phép tập lái Level 1 cho phép thiếu niên lái xe trong bao lâu?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Đó là trọn một năm.","h2":"Giấy phép tập lái Level 1 ở Delaware cho phép thiếu niên lái xe theo các quy định của nó trong 12 tháng.","p":"Đúng. Giấy phép ở Delaware có hiệu lực 12 tháng."},"tl":{"q":"Sa Delaware, gaano katagal puwedeng magmaneho ang isang teen gamit ang Level 1 learner's permit?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Isang buong taon ito.","h2":"Pinapayagan ng Level 1 learner's permit sa Delaware ang isang teen na magmaneho ayon sa mga patakaran nito nang 12 buwan.","p":"Tama. Tumatagal nang 12 buwan ang permit sa Delaware."},"ar":{"q":"في Delaware، كم من الوقت تسمح رخصة المتعلم من المستوى الأول للمراهق بالقيادة؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"إنها سنة كاملة.","h2":"تسمح رخصة المتعلم من المستوى الأول في Delaware للمراهق بالقيادة حسب قواعدها لمدة 12 شهرًا.","p":"صحيح. رخصة Delaware تستمر 12 شهرًا."},"ref":{"doc":"DE","page":30}},{"id":"de-004","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a supervisor who is not the teen's parent or guardian must be at least how old?","o":["18","20","21","25"],"h1":"It is older than the age to buy alcohol.","h2":"In Delaware, a supervisor who is not a parent or guardian must be a licensed driver who is at least 25 years old.","p":"Right. The supervisor must be 25 or older."},"es":{"q":"En Delaware, un supervisor que no es el padre, la madre ni el tutor del adolescente debe tener por lo menos ¿qué edad?","o":["18","20","21","25"],"h1":"Es mayor que la edad para comprar alcohol.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El supervisor debe tener 25 años o más."},"zh":{"q":"在 Delaware，不是青少年父母或监护人的监督者，最少要几岁？","o":["18 岁","20 岁","21 岁","25 岁"],"h1":"它比可以买酒的年龄大。","h2":"在 Delaware，不是父母或监护人的监督者，必须是至少 25 岁、有驾照的司机。","p":"对。监督者必须 25 岁或以上。"},"vi":{"q":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ của thiếu niên phải ít nhất bao nhiêu tuổi?","o":["18","20","21","25"],"h1":"Tuổi này lớn hơn tuổi được mua rượu.","h2":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải là người có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người giám sát phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Delaware, ilang taon dapat ang supervisor na hindi magulang o guardian ng teen?","o":["18","20","21","25"],"h1":"Mas matanda ito kaysa sa edad para bumili ng alak.","h2":"Sa Delaware, ang supervisor na hindi magulang o guardian ay dapat lisensyadong driver na hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 taong gulang o higit pa ang supervisor."},"ar":{"q":"في Delaware، كم يجب أن يكون عمر المشرف الذي ليس أحد والدي المراهق أو وليّ أمره على الأقل؟","o":["18","20","21","25"],"h1":"إنه أكبر من عمر شراء الكحول.","h2":"في Delaware، يجب أن يكون المشرف الذي ليس أحد الوالدين أو وليّ الأمر سائقًا مرخّصًا عمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 25 سنة أو أكثر."},"ref":{"doc":"DE","page":29}},{"id":"de-005","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how long must a supervisor who is not a parent or guardian have held a driver license?","o":["1 year","3 years","5 years","10 years"],"h1":"It is half of ten years.","h2":"In Delaware, a supervisor who is not a parent or guardian must have held a Class D license for at least 5 years.","p":"Right. Five years of license experience is required."},"es":{"q":"En Delaware, ¿cuánto tiempo debe tener su licencia un supervisor que no es padre, madre ni tutor?","o":["1 año","3 años","5 años","10 años"],"h1":"Es la mitad de diez años.","h2":"En Delaware, un supervisor que no es padre, madre ni tutor debe haber tenido una licencia Clase D por lo menos 5 años.","p":"Correcto. Se requieren cinco años con licencia."},"zh":{"q":"在 Delaware，不是父母或监护人的监督者，必须持有驾照多久？","o":["1 年","3 年","5 年","10 年"],"h1":"它是十年的一半。","h2":"在 Delaware，不是父母或监护人的监督者，必须持有 Class D 驾照至少 5 年。","p":"对。需要五年的驾照经验。"},"vi":{"q":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải có bằng lái trong bao lâu?","o":["1 năm","3 năm","5 năm","10 năm"],"h1":"Đó là một nửa của mười năm.","h2":"Ở Delaware, người giám sát không phải là cha mẹ hoặc người giám hộ phải có bằng lái Class D ít nhất 5 năm.","p":"Đúng. Cần có bằng lái ít nhất năm năm."},"tl":{"q":"Sa Delaware, gaano katagal dapat may driver license ang supervisor na hindi magulang o guardian?","o":["1 taon","3 taon","5 taon","10 taon"],"h1":"Kalahati ito ng sampung taon.","h2":"Sa Delaware, ang supervisor na hindi magulang o guardian ay dapat may Class D license nang hindi bababa sa 5 taon.","p":"Tama. Kailangan ang limang taon ng pagkakaroon ng lisensya."},"ar":{"q":"في Delaware، منذ كم من الوقت يجب أن يحمل المشرف الذي ليس أحد الوالدين أو وليّ الأمر رخصة قيادة؟","o":["سنة واحدة","3 سنوات","5 سنوات","10 سنوات"],"h1":"إنها نصف عشر سنوات.","h2":"في Delaware، يجب أن يكون المشرف الذي ليس أحد الوالدين أو وليّ الأمر قد حمل رخصة Class D لمدة 5 سنوات على الأقل.","p":"صحيح. يلزم خمس سنوات من حمل الرخصة."},"ref":{"doc":"DE","page":29}},{"id":"de-006","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how many hours of supervised driving must a permit holder log before driving alone?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Delaware permit holder must log at least 50 hours of supervised driving before driving without a supervisor.","p":"Right. Delaware asks for 50 supervised hours."},"es":{"q":"En Delaware, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de manejar solo?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un aprendiz en Delaware debe registrar por lo menos 50 horas de manejo supervisado antes de manejar sin supervisor.","p":"Correcto. Delaware pide 50 horas supervisadas."},"zh":{"q":"在 Delaware，持学习驾照的人单独开车前，必须记录多少小时有人监督的驾驶？","o":["30 小时","50 小时","70 小时","100 小时"],"h1":"它是一百的一半。","h2":"Delaware 持学习驾照的人在没有监督者陪同开车前，必须记录至少 50 小时有人监督的驾驶。","p":"对。Delaware 要求 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Delaware, người có giấy phép tập lái phải ghi lại bao nhiêu giờ lái xe có giám sát trước khi được lái một mình?","o":["30 giờ","50 giờ","70 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Người có giấy phép tập lái ở Delaware phải ghi lại ít nhất 50 giờ lái xe có giám sát trước khi được lái mà không có người giám sát.","p":"Đúng. Delaware yêu cầu 50 giờ có giám sát."},"tl":{"q":"Sa Delaware, ilang oras ng supervised na pagmamaneho ang dapat itala ng may permit bago magmaneho nang mag-isa?","o":["30 oras","50 oras","70 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Ang may permit sa Delaware ay dapat magtala ng hindi bababa sa 50 oras ng supervised na pagmamaneho bago magmaneho nang walang supervisor.","p":"Tama. 50 supervised na oras ang hinihingi ng Delaware."},"ar":{"q":"في Delaware، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل حامل رخصة المتعلم قبل أن يقود وحده؟","o":["30 ساعة","50 ساعة","70 ساعة","100 ساعة"],"h1":"إنها نصف المئة.","h2":"يجب على حامل رخصة المتعلم في Delaware أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف قبل أن يقود بدون مشرف.","p":"صحيح. تطلب Delaware 50 ساعة تحت الإشراف."},"ref":{"doc":"DE","page":29}},{"id":"de-007","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many of the supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 25 hours","None"],"h1":"It is a round number, a small part of the total.","h2":"In Delaware, at least 10 of the 50 supervised practice hours must be driven at night.","p":"Right. Ten of the hours must be at night."},"es":{"q":"En Delaware, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 25 horas","Ninguna"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Delaware, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Delaware，有人监督的练习时间里，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 25 小时","不需要"],"h1":"它是一个整数，是全部时间的一小部分。","h2":"在 Delaware，50 小时有人监督的练习里，至少 10 小时必须在晚上开。","p":"对。其中十小时必须在晚上。"},"vi":{"q":"Ở Delaware, bao nhiêu giờ trong số giờ tập lái có giám sát phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 25 giờ","Không giờ nào"],"h1":"Đó là một số tròn, một phần nhỏ của tổng số giờ.","h2":"Ở Delaware, ít nhất 10 trong số 50 giờ tập lái có giám sát phải được lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Delaware, ilan sa mga oras ng supervised na pagsasanay ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 25 oras","Wala"],"h1":"Isa itong buong numero, maliit na bahagi ng kabuuan.","h2":"Sa Delaware, hindi bababa sa 10 sa 50 oras ng supervised na pagsasanay ang dapat imaneho sa gabi.","p":"Tama. Sampu sa mga oras ang dapat sa gabi."},"ar":{"q":"في Delaware، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل","25 ساعة على الأقل","لا شيء"],"h1":"إنه رقم مستدير، وجزء صغير من المجموع.","h2":"في Delaware، يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدريب تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"DE","page":29}},{"id":"de-008","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, for how long at the start of the learner's permit may a teen drive only with a supervisor?","o":["The first month","The first 6 months","The first 9 months","The whole 12 months"],"h1":"It is half of the permit time.","h2":"During the first 6 months of a Delaware learner's permit, the teen may drive only with a qualified supervisor.","p":"Right. The first six months are fully supervised."},"es":{"q":"En Delaware, ¿durante cuánto tiempo al comienzo del permiso de aprendiz puede manejar el adolescente solo con un supervisor?","o":["El primer mes","Los primeros 6 meses","Los primeros 9 meses","Los 12 meses completos"],"h1":"Es la mitad del tiempo del permiso.","h2":"Durante los primeros 6 meses del permiso de aprendiz de Delaware, el adolescente puede manejar solamente con un supervisor calificado.","p":"Correcto. Los primeros seis meses son con supervisión."},"zh":{"q":"在 Delaware，学习驾照开始后的多长时间内，青少年只能和监督者一起开车？","o":["第一个月","前 6 个月","前 9 个月","整整 12 个月"],"h1":"它是学习驾照期间的一半。","h2":"在 Delaware 学习驾照的前 6 个月，青少年只能和合格的监督者一起开车。","p":"对。前六个月要全程有人监督。"},"vi":{"q":"Ở Delaware, trong bao lâu đầu tiên của giấy phép tập lái, thiếu niên chỉ được lái xe khi có người giám sát?","o":["Tháng đầu tiên","6 tháng đầu tiên","9 tháng đầu tiên","Cả 12 tháng"],"h1":"Đó là một nửa thời gian của giấy phép.","h2":"Trong 6 tháng đầu tiên của giấy phép tập lái ở Delaware, thiếu niên chỉ được lái xe khi có người giám sát đủ điều kiện.","p":"Đúng. Sáu tháng đầu tiên phải luôn có giám sát."},"tl":{"q":"Sa Delaware, gaano katagal sa simula ng learner's permit puwedeng magmaneho ang teen kasama lang ang supervisor?","o":["Ang unang buwan","Ang unang 6 na buwan","Ang unang 9 na buwan","Ang buong 12 buwan"],"h1":"Kalahati ito ng panahon ng permit.","h2":"Sa unang 6 na buwan ng learner's permit sa Delaware, puwedeng magmaneho ang teen kasama lang ang isang kwalipikadong supervisor.","p":"Tama. Buong supervised ang unang anim na buwan."},"ar":{"q":"في Delaware، في أي مدة من بداية رخصة المتعلم يجوز للمراهق أن يقود فقط مع مشرف؟","o":["الشهر الأول","أول 6 أشهر","أول 9 أشهر","كل الـ 12 شهرًا"],"h1":"إنها نصف مدة الرخصة.","h2":"خلال أول 6 أشهر من رخصة المتعلم في Delaware، يجوز للمراهق أن يقود فقط مع مشرف مؤهَّل.","p":"صحيح. أول ستة أشهر تكون كلها تحت الإشراف."},"ref":{"doc":"DE","page":29}},{"id":"de-009","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, after the supervised period, during which hours may a permit holder drive alone?","o":["Any time of day or night","From 5 a.m. to midnight","From 8 a.m. to 8 p.m.","From 6 a.m. to 10 p.m."],"h1":"Driving alone ends at ten at night.","h2":"After the supervised period, a Delaware permit holder may drive alone from 6 a.m. to 10 p.m.","p":"Right. Alone only from 6 a.m. to 10 p.m."},"es":{"q":"En Delaware, después del período supervisado, ¿en qué horario puede manejar solo el aprendiz?","o":["A cualquier hora del día o de la noche","De 5 a.m. a medianoche","De 8 a.m. a 8 p.m.","De 6 a.m. a 10 p.m."],"h1":"Manejar solo termina a las diez de la noche.","h2":"Después del período supervisado, un aprendiz en Delaware puede manejar solo de 6 a.m. a 10 p.m.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"zh":{"q":"在 Delaware，监督期过了以后，持学习驾照的人在什么时间可以单独开车？","o":["白天晚上任何时间","早上 5 点到午夜","早上 8 点到晚上 8 点","早上 6 点到晚上 10 点"],"h1":"单独开车在晚上十点结束。","h2":"监督期过了以后，Delaware 持学习驾照的人可以在早上 6 点到晚上 10 点单独开车。","p":"对。只在早上 6 点到晚上 10 点单独开车。"},"vi":{"q":"Ở Delaware, sau giai đoạn có giám sát, người có giấy phép tập lái được lái một mình vào những giờ nào?","o":["Bất cứ lúc nào, ngày hay đêm","Từ 5 a.m. đến nửa đêm","Từ 8 a.m. đến 8 p.m.","Từ 6 a.m. đến 10 p.m."],"h1":"Việc lái một mình kết thúc lúc mười giờ tối.","h2":"Sau giai đoạn có giám sát, người có giấy phép tập lái ở Delaware được lái một mình từ 6 a.m. đến 10 p.m.","p":"Đúng. Chỉ được lái một mình từ 6 a.m. đến 10 p.m."},"tl":{"q":"Sa Delaware, pagkatapos ng supervised na panahon, anong oras puwedeng magmaneho nang mag-isa ang may permit?","o":["Kahit anong oras, araw o gabi","Mula 5 a.m. hanggang hatinggabi","Mula 8 a.m. hanggang 8 p.m.","Mula 6 a.m. hanggang 10 p.m."],"h1":"Natatapos ang pagmamaneho nang mag-isa sa alas-diyes ng gabi.","h2":"Pagkatapos ng supervised na panahon, puwedeng magmaneho nang mag-isa ang may permit sa Delaware mula 6 a.m. hanggang 10 p.m.","p":"Tama. Mag-isa lang mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في Delaware، بعد فترة الإشراف، في أي ساعات يجوز لحامل رخصة المتعلم أن يقود وحده؟","o":["في أي وقت من النهار أو الليل","من 5 a.m. إلى منتصف الليل","من 8 a.m. إلى 8 p.m.","من 6 a.m. إلى 10 p.m."],"h1":"القيادة وحدك تنتهي في الساعة العاشرة ليلًا.","h2":"بعد فترة الإشراف، يجوز لحامل رخصة المتعلم في Delaware أن يقود وحده من 6 a.m. إلى 10 p.m.","p":"صحيح. القيادة وحدك فقط من 6 a.m. إلى 10 p.m."},"ref":{"doc":"DE","page":30}},{"id":"de-010","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, a permit holder in the unsupervised stage wants to drive alone at 11 p.m. Which trip is allowed?","o":["Going to a friend's party","Driving around for fun","Going home from work","Going to the mall"],"h1":"Think of a job.","h2":"In Delaware, a permit holder may drive alone between 10 p.m. and 6 a.m. only for trips to and from work, church or school activities.","p":"Right. Work trips are an exception at night."},"es":{"q":"En Delaware, un aprendiz en la etapa sin supervisión quiere manejar solo a las 11 p.m. ¿Qué viaje está permitido?","o":["Ir a la fiesta de un amigo","Pasear en carro por diversión","Volver a casa del trabajo","Ir al centro comercial"],"h1":"Piense en un empleo.","h2":"En Delaware, un aprendiz puede manejar solo entre las 10 p.m. y las 6 a.m. solamente para ir o volver del trabajo, de la iglesia o de actividades escolares.","p":"Correcto. Los viajes del trabajo son una excepción de noche."},"zh":{"q":"在 Delaware，处于不需监督阶段的持学习驾照的人想在晚上 11 点单独开车。哪一种行程是允许的？","o":["去朋友的派对","开车兜风","下班回家","去购物中心"],"h1":"想一想工作。","h2":"在 Delaware，持学习驾照的人只有在上下班、去教会或学校活动及回来时，才可以在晚上 10 点到早上 6 点之间单独开车。","p":"对。工作的行程是夜间的例外。"},"vi":{"q":"Ở Delaware, một người có giấy phép tập lái đang ở giai đoạn không giám sát muốn lái một mình lúc 11 p.m. Chuyến đi nào được phép?","o":["Đi dự tiệc của bạn","Lái xe dạo chơi","Đi làm về nhà","Đi đến trung tâm mua sắm"],"h1":"Hãy nghĩ đến một công việc.","h2":"Ở Delaware, người có giấy phép tập lái chỉ được lái một mình từ 10 p.m. đến 6 a.m. khi đi đến hoặc về từ nơi làm việc, nhà thờ hoặc hoạt động của trường.","p":"Đúng. Đi làm là một ngoại lệ vào ban đêm."},"tl":{"q":"Sa Delaware, gustong magmaneho nang mag-isa sa 11 p.m. ang isang may permit na nasa unsupervised na yugto. Aling biyahe ang pinapayagan?","o":["Pagpunta sa party ng kaibigan","Pagmamaneho-maneho para magsaya","Pag-uwi mula sa trabaho","Pagpunta sa mall"],"h1":"Isipin ang trabaho.","h2":"Sa Delaware, puwedeng magmaneho nang mag-isa ang may permit mula 10 p.m. hanggang 6 a.m. para lang sa biyahe papunta at pauwi mula sa trabaho, simbahan o mga aktibidad ng paaralan.","p":"Tama. Exception sa gabi ang biyahe para sa trabaho."},"ar":{"q":"في Delaware، حامل رخصة متعلم في مرحلة القيادة بدون إشراف يريد أن يقود وحده في الساعة 11 p.m. أي رحلة مسموح بها؟","o":["الذهاب إلى حفلة صديق","القيادة في الأنحاء للتسلية","العودة إلى البيت من العمل","الذهاب إلى المركز التجاري"],"h1":"فكّر في الوظيفة.","h2":"في Delaware، يجوز لحامل رخصة المتعلم أن يقود وحده بين 10 p.m. و 6 a.m. فقط للذهاب إلى العمل أو الكنيسة أو أنشطة المدرسة أو العودة منها.","p":"صحيح. رحلات العمل استثناء في الليل."},"ref":{"doc":"DE","page":30}},{"id":"de-011","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many passengers may ride with a permit holder, besides the adult supervisor?","o":["One passenger","No passengers","Two passengers","As many as there are seat belts"],"h1":"The number is very small, but not zero.","h2":"A Delaware permit holder may carry no more than one passenger besides the adult supervisor. Immediate family members are the only exception, and only when the adult supervisor is in the car.","p":"Right. Only one other passenger is allowed."},"es":{"q":"En Delaware, ¿cuántos pasajeros pueden viajar con un aprendiz, además del supervisor adulto?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tantos como cinturones haya"],"h1":"El número es muy pequeño, pero no es cero.","h2":"Un aprendiz en Delaware puede llevar como máximo un pasajero además del supervisor adulto. Solo los familiares directos son la excepción, y solo cuando el supervisor adulto está en el auto.","p":"Correcto. Solo se permite un pasajero más."},"zh":{"q":"在 Delaware，除了成年监督者以外，持学习驾照的人可以载多少位乘客？","o":["一位乘客","不能载乘客","两位乘客","有几条安全带就载几位"],"h1":"这个数字很小，但不是零。","h2":"Delaware 持学习驾照的人，除了成年监督者以外，最多只能载一位乘客。直系家人是唯一的例外，而且只有成年监督者在车里时才可以。","p":"对。只能再载一位乘客。"},"vi":{"q":"Ở Delaware, ngoài người lớn giám sát, người có giấy phép tập lái được chở bao nhiêu hành khách?","o":["Một hành khách","Không hành khách nào","Hai hành khách","Bằng số dây an toàn trong xe"],"h1":"Con số rất nhỏ, nhưng không phải là không.","h2":"Người có giấy phép tập lái ở Delaware được chở không quá một hành khách ngoài người lớn giám sát. Chỉ người trong gia đình trực hệ là ngoại lệ, và chỉ khi người lớn giám sát có mặt trong xe.","p":"Đúng. Chỉ được chở thêm một hành khách."},"tl":{"q":"Sa Delaware, ilang pasahero ang puwedeng isakay ng may permit, bukod sa adult na supervisor?","o":["Isang pasahero","Walang pasahero","Dalawang pasahero","Kasindami ng seat belt"],"h1":"Napakaliit ng numero, pero hindi zero.","h2":"Ang may permit sa Delaware ay puwedeng magsakay ng hindi hihigit sa isang pasahero bukod sa adult na supervisor. Ang malalapit na miyembro ng pamilya lang ang exception, at kapag nasa sasakyan lang ang adult na supervisor.","p":"Tama. Isang ibang pasahero lang ang pinapayagan."},"ar":{"q":"في Delaware، كم راكبًا يجوز أن يركب مع حامل رخصة المتعلم، غير المشرف البالغ؟","o":["راكب واحد","لا ركاب","راكبان","بعدد أحزمة الأمان"],"h1":"العدد صغير جدًا، لكنه ليس صفرًا.","h2":"يجوز لحامل رخصة المتعلم في Delaware أن يحمل راكبًا واحدًا فقط غير المشرف البالغ. أفراد العائلة المباشرون هم الاستثناء الوحيد، وفقط عندما يكون المشرف البالغ في السيارة.","p":"صحيح. يُسمح براكب آخر واحد فقط."},"ref":{"doc":"DE","page":29}},{"id":"de-012","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","Only with a hands-free device","Only at red lights, holding the phone","Only on highways"],"h1":"Your hands stay off the phone.","h2":"In Delaware, an adult driver may talk on the phone while driving only with a hands-free device.","p":"Right. Delaware bans holding the phone while driving."},"es":{"q":"En Delaware, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Sosteniendo el teléfono en el oído","Solo con un dispositivo de manos libres","Solo en los semáforos en rojo, sosteniendo el teléfono","Solo en las autopistas"],"h1":"Sus manos no tocan el teléfono.","h2":"En Delaware, un conductor adulto puede hablar por teléfono mientras maneja solamente con un dispositivo de manos libres.","p":"Correcto. Delaware prohíbe sostener el teléfono al manejar."},"zh":{"q":"在 Delaware，成年司机开车时可以怎样打电话？","o":["把手机拿在耳边","只能用免持设备","只在红灯时，拿着手机","只在公路上"],"h1":"你的手不碰手机。","h2":"在 Delaware，成年司机开车时只能用免持设备打电话。","p":"对。Delaware 禁止开车时手拿手机。"},"vi":{"q":"Ở Delaware, tài xế người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Cầm điện thoại áp vào tai","Chỉ dùng thiết bị rảnh tay (hands-free)","Chỉ khi đèn đỏ, cầm điện thoại","Chỉ trên xa lộ"],"h1":"Tay bạn không cầm điện thoại.","h2":"Ở Delaware, tài xế người lớn chỉ được nói chuyện điện thoại khi lái xe nếu dùng thiết bị rảnh tay.","p":"Đúng. Delaware cấm cầm điện thoại khi lái xe."},"tl":{"q":"Sa Delaware, paano puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho?","o":["Hawak ang telepono sa tainga","Gamit lang ang hands-free na device","Sa red light lang, hawak ang telepono","Sa highway lang"],"h1":"Hindi hawak ng iyong kamay ang telepono.","h2":"Sa Delaware, puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho gamit lang ang hands-free na device.","p":"Tama. Bawal sa Delaware ang paghawak ng telepono habang nagmamaneho."},"ar":{"q":"في Delaware، كيف يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة؟","o":["وهو يمسك الهاتف على أذنه","فقط بجهاز لا يحتاج إلى اليدين (hands-free)","فقط عند الإشارة الحمراء، وهو يمسك الهاتف","فقط على الطرق السريعة"],"h1":"يداك لا تمسكان الهاتف.","h2":"في Delaware، يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة فقط بجهاز لا يحتاج إلى اليدين.","p":"صحيح. تمنع Delaware إمساك الهاتف أثناء القيادة."},"ref":{"doc":"DE","page":81}},{"id":"de-013","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.02 percent or more","0.05 percent or more","0.10 percent or more"],"h1":"It is much lower than the adult limit.","h2":"In Delaware, a driver under 21 with a blood alcohol level of 0.02 percent or more loses the license under the zero tolerance law.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Delaware, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Delaware, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más pierde la licencia por la ley de tolerancia cero.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"zh":{"q":"在 Delaware，21 岁以下的司机血液酒精浓度达到多少是违法的？","o":["0.08% 或更高","0.02% 或更高","0.05% 或更高","0.10% 或更高"],"h1":"它比成年人的限制低很多。","h2":"在 Delaware，根据零容忍法，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就会失去驾照。","p":"对。21 岁以下的限制是 0.02%。"},"vi":{"q":"Ở Delaware, nồng độ cồn trong máu bao nhiêu là bất hợp pháp đối với tài xế dưới 21 tuổi?","o":["0.08 phần trăm trở lên","0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Delaware, tài xế dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên sẽ bị mất bằng lái theo luật không khoan nhượng (zero tolerance).","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02 phần trăm."},"tl":{"q":"Sa Delaware, anong blood alcohol level ang ilegal para sa driver na wala pang 21 taong gulang?","o":["0.08 porsiyento o higit pa","0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Delaware, mawawalan ng lisensya ang driver na wala pang 21 taong gulang na may blood alcohol level na 0.02 porsiyento o higit pa, ayon sa zero tolerance law.","p":"Tama. 0.02 porsiyento ang limit para sa wala pang 21."},"ar":{"q":"في Delaware، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 في المئة أو أكثر","0.02 في المئة أو أكثر","0.05 في المئة أو أكثر","0.10 في المئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في Delaware، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 في المئة أو أكثر يفقد رخصته حسب قانون عدم التسامح (zero tolerance).","p":"صحيح. الحد لمن هم أقل من 21 سنة هو 0.02 في المئة."},"ref":{"doc":"DE","page":50}},{"id":"de-014","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how soon after passing the knowledge test can you take the car road test?","o":["The same day","30 days later","6 months later","1 year later"],"h1":"You need some time to practice first, about one month.","h2":"In Delaware you can take the Class D road test 30 days after you pass the knowledge test.","p":"Right. Delaware makes you wait 30 days before the road test."},"es":{"q":"En Delaware, ¿cuánto tiempo después de aprobar el examen teórico puede tomar el examen de manejo en carro?","o":["El mismo día","30 días después","6 meses después","1 año después"],"h1":"Usted necesita tiempo para practicar primero, más o menos un mes.","h2":"En Delaware usted puede tomar el examen de manejo de Clase D 30 días después de aprobar el examen teórico.","p":"Correcto. En Delaware hay que esperar 30 días antes del examen de manejo."},"zh":{"q":"在 Delaware，通过笔试以后，最快多久可以参加汽车路考？","o":["同一天","30 天以后","6 个月以后","1 年以后"],"h1":"你需要先练习一段时间，大约一个月。","h2":"在 Delaware，你通过笔试 30 天以后，可以参加 Class D 路考。","p":"对。Delaware 要你等 30 天才能路考。"},"vi":{"q":"Ở Delaware, sau khi đậu bài thi kiến thức bao lâu thì bạn có thể thi lái xe trên đường?","o":["Ngay trong ngày","30 ngày sau","6 tháng sau","1 năm sau"],"h1":"Bạn cần thời gian để tập trước, khoảng một tháng.","h2":"Ở Delaware, bạn có thể thi lái xe Class D trên đường 30 ngày sau khi đậu bài thi kiến thức.","p":"Đúng. Delaware bắt bạn chờ 30 ngày trước khi thi lái trên đường."},"tl":{"q":"Sa Delaware, gaano kabilis pagkatapos pumasa sa knowledge test puwede kang kumuha ng road test sa kotse?","o":["Sa parehong araw","30 araw pagkatapos","6 na buwan pagkatapos","1 taon pagkatapos"],"h1":"Kailangan mo munang magsanay nang ilang panahon, mga isang buwan.","h2":"Sa Delaware, puwede kang kumuha ng Class D road test 30 araw pagkatapos mong pumasa sa knowledge test.","p":"Tama. Pinaghihintay ka ng Delaware nang 30 araw bago ang road test."},"ar":{"q":"في Delaware، بعد كم من الوقت من نجاحك في الاختبار النظري يمكنك أن تأخذ اختبار القيادة على الطريق بالسيارة؟","o":["في اليوم نفسه","بعد 30 يومًا","بعد 6 أشهر","بعد سنة واحدة"],"h1":"تحتاج إلى بعض الوقت للتدريب أولًا، حوالي شهر.","h2":"في Delaware يمكنك أن تأخذ اختبار القيادة على الطريق لرخصة Class D بعد 30 يومًا من نجاحك في الاختبار النظري.","p":"صحيح. تجعلك Delaware تنتظر 30 يومًا قبل اختبار الطريق."},"ref":{"doc":"DE","page":41}},{"id":"de-015","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what does the DMV do when a driver reaches 8 points within two years?","o":["Takes away the license for a year","Sends the driver to jail","Takes away the car","Sends the driver a warning letter"],"h1":"At 8 points the first step is gentle.","h2":"In Delaware, when a driver reaches 8 points within two years, the DMV sends the driver an advisory letter as a warning.","p":"Right. At 8 points Delaware sends a warning letter first."},"es":{"q":"En Delaware, ¿qué hace el DMV cuando un conductor llega a 8 puntos en dos años?","o":["Le quita la licencia por un año","Manda al conductor a la cárcel","Le quita el carro","Le envía al conductor una carta de advertencia"],"h1":"Con 8 puntos, el primer paso es suave.","h2":"En Delaware, cuando un conductor llega a 8 puntos en dos años, el DMV le envía una carta de advertencia.","p":"Correcto. Con 8 puntos, Delaware primero envía una carta de advertencia."},"zh":{"q":"在 Delaware，司机在两年内累积到 8 分时，DMV 会怎么做？","o":["吊销驾照一年","把司机送进监狱","没收汽车","寄给司机一封警告信"],"h1":"到 8 分时，第一步是温和的。","h2":"在 Delaware，司机在两年内累积到 8 分时，DMV 会寄给司机一封提醒信作为警告。","p":"对。到 8 分时，Delaware 先寄警告信。"},"vi":{"q":"Ở Delaware, DMV làm gì khi một tài xế bị 8 điểm trong vòng hai năm?","o":["Lấy bằng lái trong một năm","Đưa tài xế vào tù","Lấy xe đi","Gửi cho tài xế một thư cảnh cáo"],"h1":"Ở mức 8 điểm, bước đầu tiên là nhẹ nhàng.","h2":"Ở Delaware, khi một tài xế bị 8 điểm trong vòng hai năm, DMV gửi cho tài xế một thư nhắc nhở để cảnh cáo.","p":"Đúng. Ở mức 8 điểm, Delaware gửi thư cảnh cáo trước."},"tl":{"q":"Sa Delaware, ano ang ginagawa ng DMV kapag umabot sa 8 puntos ang isang driver sa loob ng dalawang taon?","o":["Kinukuha ang lisensya nang isang taon","Ipinapakulong ang driver","Kinukuha ang kotse","Pinapadalhan ang driver ng sulat ng babala"],"h1":"Sa 8 puntos, banayad ang unang hakbang.","h2":"Sa Delaware, kapag umabot sa 8 puntos ang isang driver sa loob ng dalawang taon, pinapadalhan siya ng DMV ng advisory letter bilang babala.","p":"Tama. Sa 8 puntos, sulat ng babala muna ang ipinapadala ng Delaware."},"ar":{"q":"في Delaware، ماذا تفعل DMV عندما يصل السائق إلى 8 نقاط خلال سنتين؟","o":["تسحب الرخصة لمدة سنة","ترسل السائق إلى السجن","تأخذ السيارة","ترسل إلى السائق رسالة تحذير"],"h1":"عند 8 نقاط تكون الخطوة الأولى خفيفة.","h2":"في Delaware، عندما يصل السائق إلى 8 نقاط خلال سنتين، ترسل DMV إلى السائق رسالة تنبيه كتحذير.","p":"صحيح. عند 8 نقاط ترسل Delaware رسالة تحذير أولًا."},"ref":{"doc":"DE","page":47}},{"id":"de-016","scope":"DE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Delaware, a school bus is stopped with red lights flashing on the other side of a road with four or more lanes. What do you do?","o":["Stop and wait until the lights go off","Speed up to pass quickly","You do not have to stop, but go slowly","Honk and keep driving at the same speed"],"h1":"On a wide road, the rule is different for traffic going the other way.","h2":"In Delaware, if you are on the opposite side of a road with four or more lanes, you do not have to stop for the school bus, but you must go slowly.","p":"Right. On a road with four or more lanes, oncoming traffic may pass slowly."},"es":{"q":"En Delaware, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera de cuatro carriles o más. ¿Qué hace usted?","o":["Se detiene y espera a que se apaguen las luces","Acelera para pasar rápido","No tiene que detenerse, pero pasa despacio","Toca la bocina y sigue a la misma velocidad"],"h1":"En una carretera ancha, la regla es diferente para el tráfico que va en sentido contrario.","h2":"En Delaware, si usted está del lado opuesto de una carretera de cuatro carriles o más, no tiene que detenerse por el autobús escolar, pero debe pasar despacio.","p":"Correcto. En una carretera de cuatro carriles o más, el tráfico en sentido contrario puede pasar despacio."},"zh":{"q":"在 Delaware，一辆校车在四车道或更多车道道路的另一边停着，红灯在闪。你该怎么做？","o":["停车，等到灯熄灭","加速快点开过去","你不必停车，但要慢慢开","按喇叭，用同样速度继续开"],"h1":"在宽的道路上，对向车辆的规定不一样。","h2":"在 Delaware，如果你在四车道或更多车道道路的对面，你不必为校车停车，但必须慢慢开。","p":"对。在四车道或更多车道的道路上，对向车辆可以慢慢开过去。"},"vi":{"q":"Ở Delaware, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của con đường có bốn làn xe trở lên. Bạn làm gì?","o":["Dừng lại và chờ đến khi đèn tắt","Tăng tốc để vượt qua nhanh","Bạn không phải dừng, nhưng phải chạy chậm","Bấm còi và tiếp tục chạy cùng tốc độ"],"h1":"Trên đường rộng, quy định khác đối với xe chạy ngược chiều.","h2":"Ở Delaware, nếu bạn ở phía bên kia của con đường có bốn làn xe trở lên, bạn không phải dừng lại vì xe buýt trường học, nhưng bạn phải chạy chậm.","p":"Đúng. Trên đường có bốn làn xe trở lên, xe chạy ngược chiều có thể chạy chậm qua."},"tl":{"q":"Sa Delaware, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng kalsadang may apat o higit pang lane. Ano ang gagawin mo?","o":["Huminto at maghintay hanggang mamatay ang mga ilaw","Bilisan para makalampas agad","Hindi mo kailangang huminto, pero dahan-dahan ka","Bumusina at magpatuloy sa parehong bilis"],"h1":"Sa malapad na kalsada, iba ang patakaran para sa trapikong papunta sa kabilang direksyon.","h2":"Sa Delaware, kung nasa kabilang panig ka ng kalsadang may apat o higit pang lane, hindi mo kailangang huminto para sa school bus, pero dapat kang magdahan-dahan.","p":"Tama. Sa kalsadang may apat o higit pang lane, puwedeng dumaan nang dahan-dahan ang paparating na trapiko."},"ar":{"q":"في Delaware، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق فيه أربعة مسارات أو أكثر. ماذا تفعل؟","o":["تتوقف وتنتظر حتى تنطفئ الأضواء","تسرع لتمر بسرعة","ليس عليك أن تتوقف، لكن سِر ببطء","تطلق البوق وتستمر بالسرعة نفسها"],"h1":"على الطريق العريض، القاعدة مختلفة للسيارات القادمة من الاتجاه الآخر.","h2":"في Delaware، إذا كنت على الجانب المقابل من طريق فيه أربعة مسارات أو أكثر، فليس عليك أن تتوقف للحافلة المدرسية، لكن يجب أن تسير ببطء.","p":"صحيح. على طريق فيه أربعة مسارات أو أكثر، يجوز للسيارات القادمة من الاتجاه المقابل أن تمر ببطء."},"ref":{"doc":"DE","page":89}},{"id":"de-017","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, for how long is your license suspended the first time you are convicted of passing a stopped school bus?","o":["1 month","1 week","3 years","It is never suspended"],"h1":"It is a short time, but you cannot drive at all during it.","h2":"In Delaware, the first conviction for passing a stopped school bus brings a one-month license suspension. A fine, jail time, or both may also apply.","p":"Right. A first offense means one month without a license."},"es":{"q":"En Delaware, ¿por cuánto tiempo se suspende su licencia la primera vez que lo condenan por pasar un autobús escolar detenido?","o":["1 mes","1 semana","3 años","Nunca se suspende"],"h1":"Es poco tiempo, pero usted no puede manejar nada durante ese tiempo.","h2":"En Delaware, la primera condena por pasar un autobús escolar detenido trae una suspensión de la licencia de un mes. También puede haber una multa, cárcel o ambas.","p":"Correcto. La primera vez, usted pierde la licencia por un mes."},"zh":{"q":"在 Delaware，你第一次因为超过停着的校车被定罪，驾照会被暂停多久？","o":["1 个月","1 个星期","3 年","永远不会被暂停"],"h1":"时间不长，但在这段时间里你完全不能开车。","h2":"在 Delaware，第一次因为超过停着的校车被定罪，驾照会被暂停一个月。也可能会被罚款、坐牢，或两者都有。","p":"对。第一次违规就是一个月没有驾照。"},"vi":{"q":"Ở Delaware, lần đầu tiên bạn bị kết án vì vượt qua xe buýt trường học đang dừng, bằng lái của bạn bị treo trong bao lâu?","o":["1 tháng","1 tuần","3 năm","Không bao giờ bị treo"],"h1":"Đó là một thời gian ngắn, nhưng trong thời gian đó bạn hoàn toàn không được lái xe.","h2":"Ở Delaware, lần đầu tiên bị kết án vì vượt qua xe buýt trường học đang dừng, bằng lái của bạn bị treo một tháng. Bạn cũng có thể bị phạt tiền, bị ở tù, hoặc cả hai.","p":"Đúng. Vi phạm lần đầu nghĩa là một tháng không có bằng lái."},"tl":{"q":"Sa Delaware, gaano katagal masususpinde ang lisensiya mo sa unang beses na ma-convict ka sa paglampas sa nakahintong school bus?","o":["1 buwan","1 linggo","3 taon","Hindi ito sinususpinde kailanman"],"h1":"Maikling panahon ito, pero hindi ka talaga puwedeng magmaneho habang tumatagal ito.","h2":"Sa Delaware, ang unang conviction sa paglampas sa nakahintong school bus ay may isang buwang suspensiyon ng lisensiya. Puwede ring may multa, kulong, o pareho.","p":"Tama. Sa unang paglabag, isang buwan kang walang lisensiya."},"ar":{"q":"في Delaware، كم مدة إيقاف رخصتك في أول مرة تُدان فيها بتجاوز حافلة مدرسية متوقفة؟","o":["شهر واحد","أسبوع واحد","3 سنوات","لا يتم إيقافها أبدًا"],"h1":"إنها مدة قصيرة، لكنك لا تستطيع القيادة أبدًا خلالها.","h2":"في Delaware، أول إدانة بتجاوز حافلة مدرسية متوقفة تؤدي إلى إيقاف الرخصة لمدة شهر واحد. وقد تكون هناك أيضًا غرامة أو سجن أو كلاهما.","p":"صحيح. المخالفة الأولى تعني شهرًا واحدًا بدون رخصة."},"ref":{"doc":"DE","page":90}},{"id":"de-018","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, when must your headlights be on during the day?","o":["Only when you drive on a highway","Only when you drive over 55 mph","Any time your windshield wipers are on","Only when the radio says it is cloudy"],"h1":"Think about rain.","h2":"In Delaware, your headlights must be on any time you use your windshield wipers, even during the day.","p":"Right. Wipers on means headlights on in Delaware."},"es":{"q":"En Delaware, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo cuando maneja en la autopista","Solo cuando maneja a más de 55 mph","Cada vez que usa los limpiaparabrisas","Solo cuando la radio dice que está nublado"],"h1":"Piense en la lluvia.","h2":"En Delaware, sus luces delanteras deben estar encendidas cada vez que usa los limpiaparabrisas, aunque sea de día.","p":"Correcto. En Delaware, si usa los limpiaparabrisas, enciende las luces."},"zh":{"q":"在 Delaware，白天什么时候必须开大灯？","o":["只有在公路上开车时","只有车速超过 55 mph 时","只要开着雨刷的时候","只有收音机说是阴天时"],"h1":"想一想下雨。","h2":"在 Delaware，只要你用雨刷，即使是白天，也必须开大灯。","p":"对。在 Delaware，开雨刷就要开大灯。"},"vi":{"q":"Ở Delaware, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ khi bạn lái trên xa lộ","Chỉ khi bạn lái nhanh hơn 55 mph","Bất cứ khi nào cần gạt nước đang bật","Chỉ khi radio nói trời nhiều mây"],"h1":"Hãy nghĩ đến trời mưa.","h2":"Ở Delaware, bạn phải bật đèn pha bất cứ khi nào bạn dùng cần gạt nước, kể cả vào ban ngày.","p":"Đúng. Ở Delaware, bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Delaware, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nagmamaneho ka lang sa highway","Kapag lampas 55 mph lang ang takbo mo","Tuwing nakabukas ang windshield wipers mo","Kapag sinabi lang ng radyo na maulap"],"h1":"Isipin ang ulan.","h2":"Sa Delaware, dapat nakabukas ang headlights mo tuwing ginagamit mo ang windshield wipers, kahit sa araw.","p":"Tama. Sa Delaware, kapag bukas ang wipers, dapat bukas din ang headlights."},"ar":{"q":"في Delaware، متى يجب أن تكون أضواء سيارتك الأمامية مضاءة أثناء النهار؟","o":["فقط عندما تقود على طريق سريع","فقط عندما تقود بسرعة أكثر من 55 mph","في أي وقت تكون فيه مسّاحات الزجاج الأمامي شغّالة","فقط عندما يقول الراديو إن الجو غائم"],"h1":"فكّر في المطر.","h2":"في Delaware، يجب أن تكون أضواؤك الأمامية مضاءة في أي وقت تستعمل فيه مسّاحات الزجاج الأمامي، حتى أثناء النهار.","p":"صحيح. في Delaware، تشغيل المسّاحات يعني تشغيل الأضواء الأمامية."},"ref":{"doc":"DE","page":62}},{"id":"de-019","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, what is the least Personal Injury Protection (PIP) insurance a car must have for one person?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"It is less than $25,000.","h2":"In Delaware, car insurance must include at least $15,000 of Personal Injury Protection (PIP) for one person, and $30,000 for everyone hurt in one crash.","p":"Right. Delaware requires at least $15,000 of PIP for each person."},"es":{"q":"En Delaware, ¿cuál es el mínimo de seguro de Protección contra Lesiones Personales (PIP) que debe tener un carro por cada persona?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Es menos de $25,000.","h2":"En Delaware, el seguro del carro debe incluir por lo menos $15,000 de Protección contra Lesiones Personales (PIP) por persona, y $30,000 para todos los heridos en un choque.","p":"Correcto. Delaware exige por lo menos $15,000 de PIP por persona."},"zh":{"q":"在 Delaware，一辆车对每个人最少要有多少人身伤害保护（PIP）保险？","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"它少于 $25,000。","h2":"在 Delaware，汽车保险必须包括每人至少 $15,000 的人身伤害保护（PIP），以及一次车祸中所有受伤的人合计 $30,000。","p":"对。Delaware 要求每人至少 $15,000 的 PIP。"},"vi":{"q":"Ở Delaware, mỗi xe phải có bảo hiểm Bảo vệ Thương tích Cá nhân (PIP) ít nhất bao nhiêu cho một người?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Số tiền này ít hơn $25,000.","h2":"Ở Delaware, bảo hiểm xe phải có ít nhất $15,000 Bảo vệ Thương tích Cá nhân (PIP) cho một người, và $30,000 cho tất cả những người bị thương trong một vụ tai nạn.","p":"Đúng. Delaware yêu cầu ít nhất $15,000 PIP cho mỗi người."},"tl":{"q":"Sa Delaware, ano ang pinakamababang Personal Injury Protection (PIP) insurance na dapat mayroon ang kotse para sa isang tao?","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"Mas mababa ito sa $25,000.","h2":"Sa Delaware, dapat may hindi bababa sa $15,000 na Personal Injury Protection (PIP) ang car insurance para sa isang tao, at $30,000 para sa lahat ng nasaktan sa isang aksidente.","p":"Tama. Hinihingi ng Delaware ang hindi bababa sa $15,000 na PIP para sa bawat tao."},"ar":{"q":"في Delaware، ما أقل تأمين حماية من الإصابات الشخصية (PIP) يجب أن يكون للسيارة لشخص واحد؟","o":["$5,000","$15,000","$50,000","$100,000"],"h1":"إنه أقل من $25,000.","h2":"في Delaware، يجب أن يشمل تأمين السيارة $15,000 على الأقل من الحماية من الإصابات الشخصية (PIP) لشخص واحد، و $30,000 لكل المصابين في حادث واحد.","p":"صحيح. تطلب Delaware ما لا يقل عن $15,000 من PIP لكل شخص."},"ref":{"doc":"DE","page":63}},{"id":"de-020","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what is the smallest fine for driving a car with no insurance the first time?","o":["$50","$100","$500","$1,500"],"h1":"The fine is very high, more than $1,000.","h2":"In Delaware, the fine for driving an uninsured car is at least $1,500 for a first offense, and up to $2,000.","p":"Right. Driving without insurance costs at least $1,500 in Delaware."},"es":{"q":"En Delaware, ¿cuál es la multa más baja por manejar un carro sin seguro la primera vez?","o":["$50","$100","$500","$1,500"],"h1":"La multa es muy alta, más de $1,000.","h2":"En Delaware, la multa por manejar un carro sin seguro es de por lo menos $1,500 la primera vez, y puede llegar a $2,000.","p":"Correcto. Manejar sin seguro cuesta por lo menos $1,500 en Delaware."},"zh":{"q":"在 Delaware，第一次开没有保险的车，最低罚款是多少？","o":["$50","$100","$500","$1,500"],"h1":"罚款很高，超过 $1,000。","h2":"在 Delaware，第一次开没有保险的车，罚款至少 $1,500，最高 $2,000。","p":"对。在 Delaware，开没有保险的车至少要罚 $1,500。"},"vi":{"q":"Ở Delaware, tiền phạt thấp nhất khi lái xe không có bảo hiểm lần đầu là bao nhiêu?","o":["$50","$100","$500","$1,500"],"h1":"Tiền phạt rất cao, hơn $1,000.","h2":"Ở Delaware, tiền phạt khi lái xe không có bảo hiểm lần đầu là ít nhất $1,500, và có thể lên đến $2,000.","p":"Đúng. Ở Delaware, lái xe không có bảo hiểm bị phạt ít nhất $1,500."},"tl":{"q":"Sa Delaware, ano ang pinakamababang multa sa unang beses na pagmamaneho ng kotseng walang insurance?","o":["$50","$100","$500","$1,500"],"h1":"Napakataas ng multa, higit sa $1,000.","h2":"Sa Delaware, ang multa sa pagmamaneho ng kotseng walang insurance ay hindi bababa sa $1,500 sa unang paglabag, at hanggang $2,000.","p":"Tama. Sa Delaware, hindi bababa sa $1,500 ang multa sa pagmamaneho nang walang insurance."},"ar":{"q":"في Delaware، ما أقل غرامة لقيادة سيارة بدون تأمين في المرة الأولى؟","o":["$50","$100","$500","$1,500"],"h1":"الغرامة عالية جدًا، أكثر من $1,000.","h2":"في Delaware، غرامة قيادة سيارة بدون تأمين هي $1,500 على الأقل في المخالفة الأولى، وقد تصل إلى $2,000.","p":"صحيح. القيادة بدون تأمين تكلّف $1,500 على الأقل في Delaware."},"ref":{"doc":"DE","page":63}},{"id":"de-021","scope":"DE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit on a two-lane road?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"It is lower than the limit on divided roads, which is 55 mph.","h2":"In Delaware, the speed limit on a two-lane road is 50 mph unless a sign shows a different limit.","p":"Right. Two-lane roads in Delaware have a 50 mph limit."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una carretera de dos carriles?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Es menor que el límite en carreteras divididas, que es de 55 mph.","h2":"En Delaware, el límite de velocidad en una carretera de dos carriles es de 50 mph, a menos que una señal indique otro límite.","p":"Correcto. En Delaware las carreteras de dos carriles tienen un límite de 50 mph."},"zh":{"q":"在 Delaware，如果没有标示其他限速，双车道道路的限速是多少？","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"它比有中间分隔的道路的限速 55 mph 低。","h2":"在 Delaware，除非标志显示别的限速，双车道道路的限速是 50 mph。","p":"对。Delaware 双车道道路的限速是 50 mph。"},"vi":{"q":"Ở Delaware, nếu không có biển báo giới hạn khác, giới hạn tốc độ trên đường hai làn là bao nhiêu?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Nó thấp hơn giới hạn trên đường có dải phân cách, là 55 mph.","h2":"Ở Delaware, giới hạn tốc độ trên đường hai làn là 50 mph, trừ khi có biển báo cho thấy giới hạn khác.","p":"Đúng. Đường hai làn ở Delaware có giới hạn 50 mph."},"tl":{"q":"Sa Delaware, kung walang ibang limit na nakapaskil, ano ang speed limit sa kalsadang may dalawang lane?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Mas mababa ito kaysa sa limit sa mga divided road, na 55 mph.","h2":"Sa Delaware, 50 mph ang speed limit sa kalsadang may dalawang lane, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 50 mph ang limit sa mga kalsadang may dalawang lane sa Delaware."},"ar":{"q":"في Delaware، إذا لم يُكتب حد آخر، ما حد السرعة على طريق فيه مساران؟","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"إنه أقل من الحد على الطرق المقسومة، وهو 55 mph.","h2":"في Delaware، حد السرعة على طريق فيه مساران هو 50 mph، إلا إذا كانت هناك لافتة تُظهر حدًا مختلفًا.","p":"صحيح. الطرق ذات المسارين في Delaware حدها 50 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-022","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, what is the speed limit in a school zone when children are present?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"It is a little lower than the 25 mph limit in neighborhoods.","h2":"In Delaware, the speed limit in a school zone when children are present is 20 mph.","p":"Right. Slow to 20 mph in a Delaware school zone."},"es":{"q":"En Delaware, ¿cuál es el límite de velocidad en una zona escolar cuando hay niños presentes?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Es un poco menos que el límite de 25 mph en los vecindarios.","h2":"En Delaware, el límite de velocidad en una zona escolar cuando hay niños presentes es de 20 mph.","p":"Correcto. En una zona escolar de Delaware, baje a 20 mph."},"zh":{"q":"在 Delaware，有孩子在场时，学校区域的限速是多少？","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"它比住宅区的 25 mph 限速低一点。","h2":"在 Delaware，有孩子在场时，学校区域的限速是 20 mph。","p":"对。在 Delaware 的学校区域要减速到 20 mph。"},"vi":{"q":"Ở Delaware, giới hạn tốc độ trong khu vực trường học khi có trẻ em là bao nhiêu?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Nó thấp hơn một chút so với giới hạn 25 mph trong khu dân cư.","h2":"Ở Delaware, giới hạn tốc độ trong khu vực trường học khi có trẻ em là 20 mph.","p":"Đúng. Giảm xuống 20 mph trong khu vực trường học ở Delaware."},"tl":{"q":"Sa Delaware, ano ang speed limit sa school zone kapag may mga bata?","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"Medyo mas mababa ito kaysa sa 25 mph na limit sa mga neighborhood.","h2":"Sa Delaware, 20 mph ang speed limit sa school zone kapag may mga bata.","p":"Tama. Bagalan sa 20 mph sa school zone sa Delaware."},"ar":{"q":"في Delaware، ما حد السرعة في منطقة المدرسة عندما يكون الأطفال موجودين؟","o":["10 mph","15 mph","20 mph","30 mph"],"h1":"إنه أقل قليلًا من حد 25 mph في الأحياء السكنية.","h2":"في Delaware، حد السرعة في منطقة المدرسة عندما يكون الأطفال موجودين هو 20 mph.","p":"صحيح. خفّف سرعتك إلى 20 mph في منطقة المدرسة في Delaware."},"ref":{"doc":"DE","page":93}},{"id":"de-023","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a driver under 21 is caught driving after drinking alcohol. For a first offense, how long is the license revoked?","o":["1 week","2 months","5 years","It is not revoked"],"h1":"It is more than a few weeks but less than half a year.","h2":"Under Delaware's zero tolerance law, a driver under 21 who drives after drinking loses the license for two months for a first offense.","p":"Right. A first zero tolerance offense means two months without a license."},"es":{"q":"En Delaware, descubren a un conductor menor de 21 años manejando después de tomar alcohol. Si es la primera vez, ¿por cuánto tiempo le revocan la licencia?","o":["1 semana","2 meses","5 años","No se la revocan"],"h1":"Es más de unas semanas, pero menos de medio año.","h2":"Según la ley de tolerancia cero de Delaware, un conductor menor de 21 años que maneja después de tomar alcohol pierde la licencia por dos meses la primera vez.","p":"Correcto. La primera vez, la tolerancia cero significa dos meses sin licencia."},"zh":{"q":"在 Delaware，一个 21 岁以下的司机被发现喝酒后开车。第一次违规，驾照会被吊销多久？","o":["1 个星期","2 个月","5 年","不会被吊销"],"h1":"它比几个星期长，但比半年短。","h2":"根据 Delaware 的零容忍法，21 岁以下的司机喝酒后开车，第一次违规会失去驾照两个月。","p":"对。第一次零容忍违规就是两个月没有驾照。"},"vi":{"q":"Ở Delaware, một tài xế dưới 21 tuổi bị bắt khi lái xe sau khi uống rượu. Với vi phạm lần đầu, bằng lái bị thu hồi trong bao lâu?","o":["1 tuần","2 tháng","5 năm","Không bị thu hồi"],"h1":"Nó dài hơn vài tuần nhưng ngắn hơn nửa năm.","h2":"Theo luật không khoan nhượng (zero tolerance) của Delaware, tài xế dưới 21 tuổi lái xe sau khi uống rượu sẽ bị mất bằng lái hai tháng cho vi phạm lần đầu.","p":"Đúng. Vi phạm zero tolerance lần đầu nghĩa là hai tháng không có bằng lái."},"tl":{"q":"Sa Delaware, nahuli ang isang driver na wala pang 21 taong gulang na nagmamaneho pagkatapos uminom ng alak. Sa unang paglabag, gaano katagal binabawi ang lisensya?","o":["1 linggo","2 buwan","5 taon","Hindi ito binabawi"],"h1":"Mas mahaba ito sa ilang linggo pero mas maikli sa kalahating taon.","h2":"Ayon sa zero tolerance law ng Delaware, ang driver na wala pang 21 taong gulang na nagmaneho pagkatapos uminom ay mawawalan ng lisensya nang dalawang buwan sa unang paglabag.","p":"Tama. Sa unang zero tolerance na paglabag, dalawang buwan kang walang lisensya."},"ar":{"q":"في Delaware، تم ضبط سائق عمره أقل من 21 سنة يقود بعد شرب الكحول. في المخالفة الأولى، كم مدة سحب الرخصة؟","o":["أسبوع واحد","شهران","5 سنوات","لا تُسحب"],"h1":"إنها أكثر من بضعة أسابيع لكن أقل من نصف سنة.","h2":"حسب قانون عدم التسامح (zero tolerance) في Delaware، السائق الذي عمره أقل من 21 سنة ويقود بعد الشرب يفقد رخصته لمدة شهرين في المخالفة الأولى.","p":"صحيح. المخالفة الأولى لقانون عدم التسامح تعني شهرين بدون رخصة."},"ref":{"doc":"DE","page":54}},{"id":"de-024","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a crash on a public road causes property damage but no injuries. At what amount of damage must you report it to the police?","o":["$50 or more","$100 or more","$5,000 or more","$500 or more"],"h1":"It is a few hundred dollars.","h2":"In Delaware, you must report a crash on a public road to the police when the property damage looks like $500 or more.","p":"Right. Report crashes with $500 or more in damage in Delaware."},"es":{"q":"En Delaware, un choque en una vía pública causa daños materiales pero no hay heridos. ¿A partir de qué cantidad de daños debe reportarlo a la policía?","o":["$50 o más","$100 o más","$5,000 o más","$500 o más"],"h1":"Son unos cientos de dólares.","h2":"En Delaware, usted debe reportar a la policía un choque en una vía pública cuando los daños parecen ser de $500 o más.","p":"Correcto. En Delaware se reportan los choques con daños de $500 o más."},"zh":{"q":"在 Delaware，公共道路上发生车祸，造成财产损失但没有人受伤。损失达到多少时，你必须向警察报告？","o":["$50 或以上","$100 或以上","$5,000 或以上","$500 或以上"],"h1":"它是几百美元。","h2":"在 Delaware，公共道路上的车祸，如果财产损失看起来有 $500 或以上，你必须向警察报告。","p":"对。在 Delaware，损失 $500 或以上的车祸要报告。"},"vi":{"q":"Ở Delaware, một vụ tai nạn trên đường công cộng gây hư hại tài sản nhưng không ai bị thương. Thiệt hại bao nhiêu thì bạn phải báo cảnh sát?","o":["$50 trở lên","$100 trở lên","$5,000 trở lên","$500 trở lên"],"h1":"Đó là vài trăm đô la.","h2":"Ở Delaware, bạn phải báo cảnh sát về vụ tai nạn trên đường công cộng khi thiệt hại tài sản có vẻ từ $500 trở lên.","p":"Đúng. Ở Delaware, hãy báo các vụ tai nạn có thiệt hại từ $500 trở lên."},"tl":{"q":"Sa Delaware, may aksidente sa pampublikong kalsada na may sira sa ari-arian pero walang nasaktan. Sa anong halaga ng sira dapat mo itong i-report sa pulis?","o":["$50 o higit pa","$100 o higit pa","$5,000 o higit pa","$500 o higit pa"],"h1":"Ilang daang dolyar ito.","h2":"Sa Delaware, dapat mong i-report sa pulis ang aksidente sa pampublikong kalsada kapag mukhang $500 o higit pa ang sira sa ari-arian.","p":"Tama. Sa Delaware, i-report ang mga aksidenteng may sira na $500 o higit pa."},"ar":{"q":"في Delaware، حادث على طريق عام سبّب ضررًا في الممتلكات لكن بدون إصابات. عند أي قيمة للضرر يجب أن تبلّغ الشرطة؟","o":["$50 أو أكثر","$100 أو أكثر","$5,000 أو أكثر","$500 أو أكثر"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Delaware، يجب أن تبلّغ الشرطة عن حادث على طريق عام عندما يبدو أن الضرر في الممتلكات $500 أو أكثر.","p":"صحيح. في Delaware، بلّغ عن الحوادث التي فيها ضرر $500 أو أكثر."},"ref":{"doc":"DE","page":141}},{"id":"de-025","scope":"DE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Delaware, you are on a two-lane road and see a stopped police car with flashing lights. You cannot change lanes. What must you do?","o":["Slow down below the speed limit until you pass","Keep your speed and pass quickly","Stop behind the police car and wait","Drive on the shoulder to go around"],"h1":"If you cannot move away from it, change how fast you go.","h2":"In Delaware, on a two-lane road where you cannot move over, you must slow down below the posted speed limit until you have passed the stopped emergency vehicle.","p":"Right. If you cannot move over, slow down below the limit."},"es":{"q":"En Delaware, usted va por una carretera de dos carriles y ve un carro de policía detenido con luces intermitentes. No puede cambiar de carril. ¿Qué debe hacer?","o":["Bajar la velocidad por debajo del límite hasta pasarlo","Mantener su velocidad y pasar rápido","Detenerse detrás del carro de policía y esperar","Manejar por el acotamiento para rodearlo"],"h1":"Si no puede alejarse, cambie qué tan rápido va.","h2":"En Delaware, en una carretera de dos carriles donde no puede cambiar de carril, usted debe bajar la velocidad por debajo del límite señalado hasta pasar el vehículo de emergencia detenido.","p":"Correcto. Si no puede cambiar de carril, baje la velocidad por debajo del límite."},"zh":{"q":"在 Delaware，你在双车道道路上，看到一辆停着、闪着灯的警车。你不能换车道。你必须怎么做？","o":["减速到低于限速，直到开过去","保持速度，快点开过去","停在警车后面等","开到路肩上绕过去"],"h1":"如果你不能离它远一点，就改变你的速度。","h2":"在 Delaware，在不能换车道的双车道道路上，你必须减速到低于标示的限速，直到开过停着的紧急车辆。","p":"对。如果不能换车道，就减速到低于限速。"},"vi":{"q":"Ở Delaware, bạn đang ở trên đường hai làn và thấy một xe cảnh sát đang dừng, nháy đèn. Bạn không thể đổi làn. Bạn phải làm gì?","o":["Chạy chậm dưới giới hạn tốc độ cho đến khi bạn đi qua","Giữ tốc độ và vượt qua nhanh","Dừng sau xe cảnh sát và chờ","Chạy lên lề đường để đi vòng qua"],"h1":"Nếu bạn không thể tránh xa nó, hãy thay đổi tốc độ của bạn.","h2":"Ở Delaware, trên đường hai làn mà bạn không thể tránh sang làn khác, bạn phải chạy chậm dưới giới hạn tốc độ đã ghi cho đến khi bạn đã đi qua xe khẩn cấp đang dừng.","p":"Đúng. Nếu bạn không thể tránh sang làn khác, hãy chạy chậm dưới giới hạn."},"tl":{"q":"Sa Delaware, nasa kalsadang may dalawang lane ka at may nakita kang nakahintong police car na may kumikislap na ilaw. Hindi ka makalipat ng lane. Ano ang dapat mong gawin?","o":["Magdahan-dahan nang mas mababa sa speed limit hanggang makalampas ka","Panatilihin ang bilis at lumampas agad","Huminto sa likod ng police car at maghintay","Magmaneho sa shoulder para umikot"],"h1":"Kung hindi ka makalayo rito, baguhin ang bilis mo.","h2":"Sa Delaware, sa kalsadang may dalawang lane kung saan hindi ka makalipat, dapat kang magdahan-dahan nang mas mababa sa nakapaskil na speed limit hanggang malampasan mo ang nakahintong emergency vehicle.","p":"Tama. Kung hindi ka makalipat, magdahan-dahan nang mas mababa sa limit."},"ar":{"q":"في Delaware، أنت على طريق فيه مساران وترى سيارة شرطة متوقفة وأضواؤها تومض. لا تستطيع تغيير المسار. ماذا يجب أن تفعل؟","o":["تخفّف سرعتك إلى أقل من حد السرعة حتى تتجاوزها","تحافظ على سرعتك وتمر بسرعة","تتوقف خلف سيارة الشرطة وتنتظر","تقود على كتف الطريق لتلتفّ حولها"],"h1":"إذا لم تستطع الابتعاد عنها، غيّر سرعتك.","h2":"في Delaware، على طريق فيه مساران لا تستطيع فيه الابتعاد، يجب أن تخفّف سرعتك إلى أقل من حد السرعة المكتوب حتى تتجاوز سيارة الطوارئ المتوقفة.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف سرعتك إلى أقل من الحد."},"ref":{"doc":"DE","page":82}},{"id":"de-026","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, which child should not ride in the front passenger seat?","o":["A child who is 14 and 5 feet 8 inches tall","Any child who is wearing a seat belt","A child under 12 or shorter than 5 feet 5 inches","No child; any child may sit in front"],"h1":"The rule uses both an age and a height.","h2":"In Delaware, a child who is under 12 years old or shorter than 5 feet 5 inches should not ride in the front passenger seat.","p":"Right. Children under 12 or under 5 feet 5 inches ride in the back."},"es":{"q":"En Delaware, ¿qué niño no debe ir en el asiento delantero del pasajero?","o":["Un niño de 14 años que mide 5 pies 8 pulgadas","Cualquier niño que lleve el cinturón puesto","Un niño menor de 12 años o que mide menos de 5 pies 5 pulgadas","Ninguno; cualquier niño puede ir adelante"],"h1":"La regla usa una edad y una estatura.","h2":"En Delaware, un niño menor de 12 años o que mide menos de 5 pies 5 pulgadas no debe ir en el asiento delantero del pasajero.","p":"Correcto. Los niños menores de 12 años o de menos de 5 pies 5 pulgadas van atrás."},"zh":{"q":"在 Delaware，哪种孩子不应该坐在前排乘客座位？","o":["14 岁、身高 5 英尺 8 英寸的孩子","任何系着安全带的孩子","不到 12 岁或身高不到 5 英尺 5 英寸的孩子","没有；任何孩子都可以坐前面"],"h1":"这个规定同时看年龄和身高。","h2":"在 Delaware，不到 12 岁或身高不到 5 英尺 5 英寸的孩子不应该坐在前排乘客座位。","p":"对。不到 12 岁或不到 5 英尺 5 英寸的孩子坐后面。"},"vi":{"q":"Ở Delaware, trẻ em nào không nên ngồi ở ghế hành khách phía trước?","o":["Trẻ 14 tuổi và cao 5 feet 8 inches","Bất kỳ trẻ nào đang thắt dây an toàn","Trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches","Không có; trẻ nào cũng có thể ngồi phía trước"],"h1":"Quy định dùng cả tuổi và chiều cao.","h2":"Ở Delaware, trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches không nên ngồi ở ghế hành khách phía trước.","p":"Đúng. Trẻ dưới 12 tuổi hoặc thấp hơn 5 feet 5 inches ngồi ở phía sau."},"tl":{"q":"Sa Delaware, aling bata ang hindi dapat umupo sa front passenger seat?","o":["Batang 14 taong gulang at 5 feet 8 inches ang taas","Kahit sinong batang nakasuot ng seat belt","Batang wala pang 12 taong gulang o mas maliit sa 5 feet 5 inches","Wala; puwedeng umupo sa harap ang kahit sinong bata"],"h1":"Gumagamit ang patakaran ng edad at ng taas.","h2":"Sa Delaware, ang batang wala pang 12 taong gulang o mas maliit sa 5 feet 5 inches ay hindi dapat umupo sa front passenger seat.","p":"Tama. Sa likod umuupo ang mga batang wala pang 12 o mas maliit sa 5 feet 5 inches."},"ar":{"q":"في Delaware، أي طفل يجب ألّا يجلس في مقعد الراكب الأمامي؟","o":["طفل عمره 14 سنة وطوله 5 feet 8 inches","أي طفل يضع حزام الأمان","طفل عمره أقل من 12 سنة أو طوله أقل من 5 feet 5 inches","لا أحد؛ يمكن لأي طفل أن يجلس في الأمام"],"h1":"القاعدة تستعمل العمر والطول معًا.","h2":"في Delaware، الطفل الذي عمره أقل من 12 سنة أو طوله أقل من 5 feet 5 inches يجب ألّا يجلس في مقعد الراكب الأمامي.","p":"صحيح. الأطفال الذين عمرهم أقل من 12 سنة أو طولهم أقل من 5 feet 5 inches يجلسون في الخلف."},"ref":{"doc":"DE","page":109}},{"id":"de-027","scope":"DE","cat":"signals","sign":null,"c":2,"en":{"q":"In Delaware, how far ahead must you signal before you turn?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Delaware asks for a longer distance than many states.","h2":"In Delaware, you must signal for at least 300 feet before you turn, stop or change lanes.","p":"Right. Signal 300 feet ahead."},"es":{"q":"En Delaware, ¿con cuánta anticipación debe poner la direccional antes de dar vuelta?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Delaware pide una distancia más larga que muchos estados.","h2":"En Delaware, debe poner la direccional por lo menos 300 pies antes de dar vuelta, detenerse o cambiar de carril.","p":"Correcto. Ponga la direccional 300 pies antes."},"zh":{"q":"在 Delaware，转弯前要提前多远打转向灯？","o":["50 英尺","100 英尺","300 英尺","1,000 英尺"],"h1":"Delaware 要求的距离比很多州长。","h2":"在 Delaware，你在转弯、停车或换车道之前，至少要提前 300 英尺打转向灯。","p":"对。提前 300 英尺打转向灯。"},"vi":{"q":"Ở Delaware, bạn phải bật đèn xi nhan trước khi rẽ bao xa?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Delaware yêu cầu khoảng cách dài hơn nhiều tiểu bang.","h2":"Ở Delaware, bạn phải bật đèn xi nhan ít nhất 300 feet trước khi rẽ, dừng lại hoặc đổi làn.","p":"Đúng. Bật xi nhan trước 300 feet."},"tl":{"q":"Sa Delaware, gaano kalayo bago ka lumiko dapat kang mag-signal?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Mas mahabang distansya ang hinihingi ng Delaware kaysa sa maraming estado.","h2":"Sa Delaware, dapat kang mag-signal nang hindi bababa sa 300 feet bago ka lumiko, huminto o lumipat ng lane.","p":"Tama. Mag-signal 300 feet bago lumiko."},"ar":{"q":"في Delaware، على أي مسافة قبل المنعطف يجب أن تشغّل إشارة الانعطاف؟","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"تطلب Delaware مسافة أطول من كثير من الولايات.","h2":"في Delaware يجب أن تشغّل إشارة الانعطاف قبل 300 feet على الأقل من الانعطاف أو التوقف أو تغيير المسار.","p":"صحيح. شغّل الإشارة قبل 300 feet."},"ref":{"doc":"DE","page":81}},{"id":"de-028","scope":"DE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Delaware, you are passing a bicyclist on a road with two lanes in your direction. What does the law say?","o":["Leave at least 3 feet and move to the other lane if you can","Leave at least 1 foot and stay in your lane","Honk and pass close to the bike","Pass on the right side of the bike"],"h1":"There is a minimum distance, and an extra step on bigger roads.","h2":"In Delaware, you must leave at least three feet when passing a bicyclist, and on roads with more than one lane in your direction you should move to the next lane whenever possible.","p":"Right. At least 3 feet, and change lanes when you can."},"es":{"q":"En Delaware, va a rebasar a un ciclista en una vía con dos carriles en su dirección. ¿Qué dice la ley?","o":["Dejar por lo menos 3 pies y pasarse al otro carril si puede","Dejar por lo menos 1 pie y quedarse en su carril","Tocar la bocina y pasar cerca de la bicicleta","Rebasar por el lado derecho de la bicicleta"],"h1":"Hay una distancia mínima, y un paso más en vías grandes.","h2":"En Delaware, debe dejar por lo menos tres pies al rebasar a un ciclista, y en vías con más de un carril en su dirección debe pasarse al carril de al lado siempre que pueda.","p":"Correcto. Por lo menos 3 pies, y cámbiese de carril cuando pueda."},"zh":{"q":"在 Delaware，你在一条同方向有两条车道的路上超过一个骑自行车的人。法律怎么规定？","o":["至少留出 3 英尺，能换到另一条车道就换过去","至少留出 1 英尺，并留在自己的车道里","按喇叭，然后贴近自行车超过去","从自行车的右边超过去"],"h1":"有一个最小距离，在大一点的路上还要多做一步。","h2":"在 Delaware，超过骑自行车的人时至少要留出三英尺；如果你这个方向有不止一条车道，只要可以，就应该换到旁边的车道。","p":"对。至少 3 英尺，能换车道就换车道。"},"vi":{"q":"Ở Delaware, bạn đang vượt một người đi xe đạp trên con đường có hai làn cùng chiều với bạn. Luật nói gì?","o":["Chừa ít nhất 3 feet và chuyển sang làn kia nếu có thể","Chừa ít nhất 1 foot và ở trong làn của bạn","Bấm còi và vượt sát xe đạp","Vượt bên phải xe đạp"],"h1":"Có một khoảng cách tối thiểu, và thêm một bước trên đường lớn hơn.","h2":"Ở Delaware, khi vượt người đi xe đạp, bạn phải chừa ít nhất ba feet, và trên đường có hơn một làn cùng chiều, bạn nên chuyển sang làn bên cạnh bất cứ khi nào có thể.","p":"Đúng. Ít nhất 3 feet, và đổi làn khi có thể."},"tl":{"q":"Sa Delaware, nilalampasan mo ang isang nagbibisikleta sa daan na may dalawang lane sa direksyon mo. Ano ang sabi ng batas?","o":["Mag-iwan ng hindi bababa sa 3 feet at lumipat sa kabilang lane kung kaya mo","Mag-iwan ng hindi bababa sa 1 foot at manatili sa lane mo","Bumusina at lumampas nang malapit sa bisikleta","Lumampas sa kanang bahagi ng bisikleta"],"h1":"May pinakamaliit na distansya, at may dagdag na hakbang sa mas malalaking daan.","h2":"Sa Delaware, dapat kang mag-iwan ng hindi bababa sa tatlong feet kapag nilalampasan mo ang isang nagbibisikleta, at sa daan na may higit sa isang lane sa direksyon mo, dapat kang lumipat sa katabing lane kapag kaya.","p":"Tama. Hindi bababa sa 3 feet, at lumipat ng lane kapag kaya mo."},"ar":{"q":"في Delaware، أنت تتجاوز راكب دراجة هوائية على طريق فيه مساران في اتجاهك. ماذا يقول القانون؟","o":["اترك 3 feet على الأقل وانتقل إلى المسار الآخر إذا استطعت","اترك 1 foot على الأقل وابقَ في مسارك","اضغط على البوق وتجاوز قريبًا من الدراجة","تجاوز من الجهة اليمنى للدراجة"],"h1":"هناك مسافة دنيا، وخطوة إضافية على الطرق الأكبر.","h2":"في Delaware يجب أن تترك ثلاثة feet على الأقل عندما تتجاوز راكب دراجة هوائية، وعلى الطرق التي فيها أكثر من مسار في اتجاهك يجب أن تنتقل إلى المسار المجاور كلما أمكن ذلك.","p":"صحيح. 3 feet على الأقل، وغيّر المسار عندما تستطيع."},"ref":{"doc":"DE","page":81}},{"id":"de-029","scope":"DE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Delaware, how close to a fire hydrant may you stop or park?","o":["Up to 5 feet away","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Firefighters need room to reach the hydrant.","h2":"In Delaware, you may not stop or park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Delaware, ¿a qué distancia de un hidrante puede detenerse o estacionarse?","o":["Hasta 5 pies de distancia","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Delaware, usted no puede detenerse ni estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Delaware，你可以在离消防栓多近的地方停车或泊车？","o":["最近可以到 5 英尺","不能近于 15 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"消防员需要空间去用消防栓。","h2":"在 Delaware，你不可以在离消防栓 15 英尺以内的地方停车或泊车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Delaware, bạn được dừng hoặc đỗ xe gần trụ cứu hỏa đến mức nào?","o":["Cách đến 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Lính cứu hỏa cần chỗ để tới được trụ cứu hỏa.","h2":"Ở Delaware, bạn không được dừng hoặc đỗ xe trong vòng 15 feet cách trụ cứu hỏa.","p":"Đúng. Cách trụ cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Delaware, gaano kalapit sa fire hydrant puwede kang huminto o pumarada?","o":["Hanggang 5 feet ang layo","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant.","h2":"Sa Delaware, hindi ka puwedeng huminto o pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Delaware، كم يمكنك أن تقترب من صنبور إطفاء الحريق عندما تتوقف أو تركن سيارتك؟","o":["حتى مسافة 5 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet"],"h1":"يحتاج رجال الإطفاء إلى مكان للوصول إلى الصنبور.","h2":"في Delaware لا يجوز لك أن تتوقف أو تركن سيارتك على مسافة أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 feet على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"DE","page":92}},{"id":"de-030","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what is the minimum vision needed for a driver license, with or without glasses?","o":["20/100","20/70","20/20","20/40"],"h1":"It is the same standard many states use.","h2":"In Delaware, you need at least 20/40 vision, with or without glasses or contact lenses, to get a driver license.","p":"Right. The minimum is 20/40."},"es":{"q":"En Delaware, ¿cuál es la visión mínima para una licencia de conducir, con o sin anteojos?","o":["20/100","20/70","20/20","20/40"],"h1":"Es el mismo estándar que usan muchos estados.","h2":"En Delaware, necesita por lo menos una visión de 20/40, con o sin anteojos o lentes de contacto, para obtener una licencia de conducir.","p":"Correcto. El mínimo es 20/40."},"zh":{"q":"在 Delaware，戴或不戴眼镜，拿驾照最低需要多好的视力？","o":["20/100","20/70","20/20","20/40"],"h1":"这和很多州用的标准一样。","h2":"在 Delaware，不管戴不戴眼镜或隐形眼镜，你的视力至少要达到 20/40 才能拿到驾照。","p":"对。最低是 20/40。"},"vi":{"q":"Ở Delaware, thị lực tối thiểu để có bằng lái xe là bao nhiêu, có hoặc không có kính?","o":["20/100","20/70","20/20","20/40"],"h1":"Đây là cùng tiêu chuẩn mà nhiều tiểu bang dùng.","h2":"Ở Delaware, bạn cần thị lực ít nhất 20/40, có hoặc không có kính đeo hay kính áp tròng, để được cấp bằng lái xe.","p":"Đúng. Mức tối thiểu là 20/40."},"tl":{"q":"Sa Delaware, ano ang pinakamababang linaw ng paningin na kailangan para sa driver license, may salamin man o wala?","o":["20/100","20/70","20/20","20/40"],"h1":"Ito ang parehong pamantayan na ginagamit ng maraming estado.","h2":"Sa Delaware, kailangan mo ng paningin na hindi bababa sa 20/40, may salamin o contact lenses man o wala, para makakuha ng driver license.","p":"Tama. Ang pinakamababa ay 20/40."},"ar":{"q":"في Delaware، ما أدنى قوة نظر مطلوبة لرخصة القيادة، مع النظارات أو بدونها؟","o":["20/100","20/70","20/20","20/40"],"h1":"إنه المعيار نفسه الذي تستخدمه ولايات كثيرة.","h2":"في Delaware تحتاج إلى قوة نظر 20/40 على الأقل، مع النظارات أو العدسات اللاصقة أو بدونها، لتحصل على رخصة القيادة.","p":"صحيح. الحد الأدنى هو 20/40."},"ref":{"doc":"DE","page":40}},{"id":"de-031","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit in a business or residential district?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"It is a common town speed.","h2":"In Delaware, the speed limit in business and residential districts is 25 mph unless a different limit is posted.","p":"Right. It is 25 mph."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una zona comercial o residencial?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Es una velocidad común en los pueblos.","h2":"En Delaware, el límite de velocidad en zonas comerciales y residenciales es de 25 mph, salvo que haya otro límite señalado.","p":"Correcto. Es de 25 mph."},"zh":{"q":"在 Delaware，如果没有标出别的限速，商业区或住宅区的限速是多少？","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"这是城镇里常见的速度。","h2":"在 Delaware，除非标出了不同的限速，商业区和住宅区的限速是 25 mph。","p":"对。是 25 mph。"},"vi":{"q":"Ở Delaware, nếu không có biển báo tốc độ khác, tốc độ tối đa trong khu thương mại hoặc khu dân cư là bao nhiêu?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Đây là tốc độ thường gặp trong thị trấn.","h2":"Ở Delaware, tốc độ tối đa trong khu thương mại và khu dân cư là 25 mph, trừ khi có biển báo tốc độ khác.","p":"Đúng. Là 25 mph."},"tl":{"q":"Sa Delaware, kung walang ibang nakapaskil na limit, ano ang speed limit sa business o residential district?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Karaniwang bilis ito sa bayan.","h2":"Sa Delaware, 25 mph ang speed limit sa business at residential districts maliban kung may ibang limit na nakapaskil.","p":"Tama. 25 mph ito."},"ar":{"q":"في Delaware، إذا لم يكن هناك حد سرعة آخر مكتوب، ما حد السرعة في المنطقة التجارية أو السكنية؟","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"إنها سرعة شائعة في البلدات.","h2":"في Delaware حد السرعة في المناطق التجارية والسكنية هو 25 mph ما لم يكن هناك حد مختلف مكتوب.","p":"صحيح. إنه 25 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-032","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you just moved here from another state. How soon must you get a Delaware driver license?","o":["Within 30 days","Within 60 days","Within 90 days","Within 1 year"],"h1":"It is about two months.","h2":"In Delaware, a new resident must apply for a Delaware driver license within 60 days of moving here.","p":"Right. You have 60 days."},"es":{"q":"En Delaware, usted acaba de mudarse desde otro estado. ¿En cuánto tiempo debe obtener una licencia de conducir de Delaware?","o":["Dentro de 30 días","Dentro de 60 días","Dentro de 90 días","Dentro de 1 año"],"h1":"Son unos dos meses.","h2":"En Delaware, un nuevo residente debe solicitar una licencia de conducir de Delaware dentro de los 60 días después de mudarse.","p":"Correcto. Tiene 60 días."},"zh":{"q":"在 Delaware，你刚从别的州搬来。你必须在多久之内拿到 Delaware 驾照？","o":["30 天之内","60 天之内","90 天之内","1 年之内"],"h1":"大约是两个月。","h2":"在 Delaware，新居民必须在搬来后 60 天之内申请 Delaware 驾照。","p":"对。你有 60 天。"},"vi":{"q":"Ở Delaware, bạn vừa chuyển đến từ một tiểu bang khác. Bạn phải lấy bằng lái Delaware trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 90 ngày","Trong vòng 1 năm"],"h1":"Khoảng hai tháng.","h2":"Ở Delaware, cư dân mới phải xin bằng lái Delaware trong vòng 60 ngày sau khi chuyển đến.","p":"Đúng. Bạn có 60 ngày."},"tl":{"q":"Sa Delaware, kalilipat mo lang mula sa ibang estado. Gaano kabilis ka dapat kumuha ng Delaware driver license?","o":["Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 90 araw","Sa loob ng 1 taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa Delaware, dapat mag-apply ang bagong residente ng Delaware driver license sa loob ng 60 araw mula nang lumipat dito.","p":"Tama. May 60 araw ka."},"ar":{"q":"في Delaware، انتقلت للتو من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Delaware؟","o":["خلال 30 يومًا","خلال 60 يومًا","خلال 90 يومًا","خلال سنة واحدة (1)"],"h1":"المدة حوالي شهرين.","h2":"في Delaware، يجب على المقيم الجديد أن يقدّم طلبًا لرخصة قيادة من Delaware خلال 60 يومًا من انتقاله إليها.","p":"صحيح. لديك 60 يومًا."},"ref":{"doc":"DE","page":31}},{"id":"de-033","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how long is a regular Class D driver license valid?","o":["2 years","4 years","6 years","8 years"],"h1":"It lasts longer than in many states.","h2":"In Delaware, a regular Class D driver license is issued for 8 years.","p":"Right. It is valid for 8 years."},"es":{"q":"En Delaware, ¿por cuánto tiempo es válida una licencia de conducir Clase D normal?","o":["2 años","4 años","6 años","8 años"],"h1":"Dura más que en muchos estados.","h2":"En Delaware, una licencia de conducir Clase D normal se emite por 8 años.","p":"Correcto. Es válida por 8 años."},"zh":{"q":"在 Delaware，普通 Class D 驾照的有效期是多久？","o":["2 年","4 年","6 年","8 年"],"h1":"它比很多州的有效期长。","h2":"在 Delaware，普通 Class D 驾照的有效期是 8 年。","p":"对。有效期是 8 年。"},"vi":{"q":"Ở Delaware, bằng lái thường hạng D (Class D) có giá trị trong bao lâu?","o":["2 năm","4 năm","6 năm","8 năm"],"h1":"Thời gian này dài hơn ở nhiều tiểu bang.","h2":"Ở Delaware, bằng lái thường hạng D (Class D) được cấp có giá trị 8 năm.","p":"Đúng. Bằng có giá trị 8 năm."},"tl":{"q":"Sa Delaware, gaano katagal valid ang regular na Class D driver license?","o":["2 taon","4 na taon","6 na taon","8 taon"],"h1":"Mas matagal ito kaysa sa maraming estado.","h2":"Sa Delaware, ang regular na Class D driver license ay ibinibigay para sa 8 taon.","p":"Tama. Valid ito nang 8 taon."},"ar":{"q":"في Delaware، كم مدة صلاحية رخصة القيادة العادية من الفئة D (Class D)؟","o":["2 سنة","4 سنوات","6 سنوات","8 سنوات"],"h1":"مدتها أطول منها في كثير من الولايات.","h2":"في Delaware، تُصدر رخصة القيادة العادية من الفئة D لمدة 8 سنوات.","p":"صحيح. صلاحيتها 8 سنوات."},"ref":{"doc":"DE","page":32}},{"id":"de-034","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, a teen breaks the rules of the Level One learner's permit for the first time. What happens?","o":["A 2-month suspension","A warning letter only","A 1-year suspension","A small fine only"],"h1":"It is treated like driving without a license.","h2":"In Delaware, breaking the Level One permit rules counts as driving without a license, and the first offense brings a 2-month suspension.","p":"Right. The first time, it is a 2-month suspension."},"es":{"q":"En Delaware, un joven no cumple las reglas del permiso de aprendizaje de Nivel Uno por primera vez. ¿Qué pasa?","o":["Una suspensión de 2 meses","Solo una carta de advertencia","Una suspensión de 1 año","Solo una multa pequeña"],"h1":"Se trata como manejar sin licencia.","h2":"En Delaware, no cumplir las reglas del permiso de Nivel Uno cuenta como manejar sin licencia, y la primera vez trae una suspensión de 2 meses.","p":"Correcto. La primera vez es una suspensión de 2 meses."},"zh":{"q":"在 Delaware，一个青少年第一次违反 Level One 学习驾照的规定。会怎样？","o":["暂停驾驶资格 2 个月","只收到警告信","暂停驾驶资格 1 年","只罚一点钱"],"h1":"这被当作无照驾驶。","h2":"在 Delaware，违反 Level One 学习驾照的规定算作无照驾驶，第一次违规会被暂停驾驶资格 2 个月。","p":"对。第一次是暂停 2 个月。"},"vi":{"q":"Ở Delaware, một thiếu niên vi phạm quy định của giấy phép tập lái Level One lần đầu. Chuyện gì xảy ra?","o":["Bị đình chỉ 2 tháng","Chỉ nhận thư cảnh cáo","Bị đình chỉ 1 năm","Chỉ bị phạt tiền nhỏ"],"h1":"Việc này được xem như lái xe không có bằng.","h2":"Ở Delaware, vi phạm quy định của giấy phép tập lái Level One được tính là lái xe không có bằng, và lần vi phạm đầu tiên bị đình chỉ 2 tháng.","p":"Đúng. Lần đầu bị đình chỉ 2 tháng."},"tl":{"q":"Sa Delaware, unang beses na lumabag ang isang teen sa mga patakaran ng Level One learner's permit. Ano ang mangyayari?","o":["2 buwang suspension","Warning letter lang","1 taong suspension","Maliit na multa lang"],"h1":"Itinuturing ito na parang pagmamaneho nang walang lisensya.","h2":"Sa Delaware, ang paglabag sa mga patakaran ng Level One permit ay itinuturing na pagmamaneho nang walang lisensya, at 2 buwang suspension ang parusa sa unang paglabag.","p":"Tama. Sa unang beses, 2 buwang suspension."},"ar":{"q":"في Delaware، خالف مراهق قواعد رخصة المتعلم من المستوى الأول (Level One) لأول مرة. ماذا يحدث؟","o":["إيقاف لمدة شهرين (2)","رسالة تحذير فقط","إيقاف لمدة سنة واحدة (1)","غرامة صغيرة فقط"],"h1":"تُعامل كأنها قيادة بدون رخصة.","h2":"في Delaware، مخالفة قواعد رخصة المستوى الأول تُعد قيادة بدون رخصة، والمخالفة الأولى عقوبتها إيقاف لمدة شهرين (2).","p":"صحيح. في المرة الأولى يكون الإيقاف شهرين (2)."},"ref":{"doc":"DE","page":30}},{"id":"de-035","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, you fail the road test. How long must you wait before you take it again?","o":["Until the next day","At least 7 days","At least 30 days","At least 6 months"],"h1":"It gives you about a month to practice.","h2":"In Delaware, if you fail the road test, you must wait at least 30 days before you try again.","p":"Right. You wait at least 30 days."},"es":{"q":"En Delaware, usted no aprueba el examen de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Hasta el día siguiente","Por lo menos 7 días","Por lo menos 30 días","Por lo menos 6 meses"],"h1":"Le da como un mes para practicar.","h2":"En Delaware, si no aprueba el examen de manejo, debe esperar por lo menos 30 días antes de intentarlo otra vez.","p":"Correcto. Debe esperar por lo menos 30 días."},"zh":{"q":"在 Delaware，你没有通过路考。你要等多久才能再考？","o":["等到第二天","至少 7 天","至少 30 天","至少 6 个月"],"h1":"它给你大约一个月的时间练习。","h2":"在 Delaware，如果你路考没通过，必须等至少 30 天才能再考。","p":"对。你要等至少 30 天。"},"vi":{"q":"Ở Delaware, bạn thi trượt bài thi lái xe trên đường. Bạn phải đợi bao lâu mới được thi lại?","o":["Đến ngày hôm sau","Ít nhất 7 ngày","Ít nhất 30 ngày","Ít nhất 6 tháng"],"h1":"Bạn có khoảng một tháng để tập luyện.","h2":"Ở Delaware, nếu bạn thi trượt bài thi lái xe trên đường, bạn phải đợi ít nhất 30 ngày mới được thi lại.","p":"Đúng. Bạn đợi ít nhất 30 ngày."},"tl":{"q":"Sa Delaware, bumagsak ka sa road test. Gaano katagal ka dapat maghintay bago ka kumuha ulit?","o":["Hanggang sa susunod na araw","Hindi bababa sa 7 araw","Hindi bababa sa 30 araw","Hindi bababa sa 6 na buwan"],"h1":"Binibigyan ka nito ng mga isang buwan para mag-practice.","h2":"Sa Delaware, kapag bumagsak ka sa road test, dapat kang maghintay nang hindi bababa sa 30 araw bago ka sumubok ulit.","p":"Tama. Maghihintay ka nang hindi bababa sa 30 araw."},"ar":{"q":"في Delaware، رسبت في اختبار القيادة على الطريق. كم يجب أن تنتظر قبل أن تعيده؟","o":["حتى اليوم التالي","7 أيام على الأقل","30 يومًا على الأقل","6 أشهر على الأقل"],"h1":"تعطيك هذه المدة حوالي شهر للتدرّب.","h2":"في Delaware، إذا رسبت في اختبار القيادة على الطريق، يجب أن تنتظر 30 يومًا على الأقل قبل أن تحاول مرة أخرى.","p":"صحيح. تنتظر 30 يومًا على الأقل."},"ref":{"doc":"DE","page":43}},{"id":"de-036","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how much is the fee to reinstate a revoked driver license?","o":["$25","$50","$100","$200"],"h1":"A revoked license costs more to get back than a suspended one.","h2":"In Delaware, it costs $200 to reinstate a revoked license, while a suspended license costs $50.","p":"Right. The fee is $200."},"es":{"q":"En Delaware, ¿cuánto cuesta restablecer una licencia de conducir revocada?","o":["$25","$50","$100","$200"],"h1":"Recuperar una licencia revocada cuesta más que una suspendida.","h2":"En Delaware, cuesta $200 restablecer una licencia revocada, mientras que una licencia suspendida cuesta $50.","p":"Correcto. El cargo es de $200."},"zh":{"q":"在 Delaware，恢复被吊销（revoked）的驾照要交多少费用？","o":["$25","$50","$100","$200"],"h1":"恢复被吊销的驾照比恢复被暂停的驾照更贵。","h2":"在 Delaware，恢复被吊销的驾照要 $200，而恢复被暂停的驾照要 $50。","p":"对。费用是 $200。"},"vi":{"q":"Ở Delaware, lệ phí để phục hồi bằng lái bị thu hồi (revoked) là bao nhiêu?","o":["$25","$50","$100","$200"],"h1":"Lấy lại bằng bị thu hồi tốn nhiều tiền hơn bằng bị đình chỉ.","h2":"Ở Delaware, phục hồi bằng lái bị thu hồi tốn $200, còn bằng lái bị đình chỉ tốn $50.","p":"Đúng. Lệ phí là $200."},"tl":{"q":"Sa Delaware, magkano ang bayad para maibalik ang na-revoke na driver license?","o":["$25","$50","$100","$200"],"h1":"Mas mahal maibalik ang na-revoke na lisensya kaysa sa na-suspend.","h2":"Sa Delaware, $200 ang bayad para maibalik ang na-revoke na lisensya, samantalang $50 para sa na-suspend na lisensya.","p":"Tama. $200 ang bayad."},"ar":{"q":"في Delaware، كم رسوم إعادة رخصة قيادة مسحوبة (revoked)؟","o":["$25","$50","$100","$200"],"h1":"استعادة الرخصة المسحوبة تكلّف أكثر من استعادة الرخصة الموقوفة.","h2":"في Delaware، تكلّف إعادة الرخصة المسحوبة $200، بينما تكلّف إعادة الرخصة الموقوفة $50.","p":"صحيح. الرسوم $200."},"ref":{"doc":"DE","page":44}},{"id":"de-037","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many points do you get for driving 10 to 14 mph over the speed limit?","o":["4 points","2 points","6 points","8 points"],"h1":"It is more than for going just a little over the limit.","h2":"In Delaware, speeding 10 to 14 mph over the posted limit adds 4 points to your record.","p":"Right. It is 4 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por manejar de 10 a 14 mph sobre el límite de velocidad?","o":["4 puntos","2 puntos","6 puntos","8 puntos"],"h1":"Es más que por pasarse solo un poco del límite.","h2":"En Delaware, manejar de 10 a 14 mph sobre el límite señalado agrega 4 puntos a su historial.","p":"Correcto. Son 4 puntos."},"zh":{"q":"在 Delaware，超速 10 到 14 mph 会被记几分？","o":["4 分","2 分","6 分","8 分"],"h1":"比只超速一点点记的分更多。","h2":"在 Delaware，超过标出的限速 10 到 14 mph，会在你的记录上记 4 分。","p":"对。是 4 分。"},"vi":{"q":"Ở Delaware, bạn bị bao nhiêu điểm khi lái nhanh hơn giới hạn tốc độ từ 10 đến 14 mph?","o":["4 điểm","2 điểm","6 điểm","8 điểm"],"h1":"Nhiều hơn so với chỉ chạy quá giới hạn một chút.","h2":"Ở Delaware, chạy quá tốc độ cho phép từ 10 đến 14 mph sẽ bị ghi 4 điểm vào hồ sơ của bạn.","p":"Đúng. Là 4 điểm."},"tl":{"q":"Sa Delaware, ilang puntos ang makukuha mo kapag lumampas ka nang 10 hanggang 14 mph sa speed limit?","o":["4 na puntos","2 puntos","6 na puntos","8 puntos"],"h1":"Mas marami ito kaysa sa kaunting paglampas sa limit.","h2":"Sa Delaware, ang pagmamaneho nang 10 hanggang 14 mph na lampas sa nakapaskil na limit ay nagdadagdag ng 4 na puntos sa record mo.","p":"Tama. 4 na puntos ito."},"ar":{"q":"في Delaware، كم نقطة تحصل عليها إذا قدت أسرع من حد السرعة بـ 10 إلى 14 mph؟","o":["4 نقاط","2 نقطة","6 نقاط","8 نقاط"],"h1":"هي أكثر من النقاط لتجاوز الحد بقليل فقط.","h2":"في Delaware، تجاوز حد السرعة المكتوب بـ 10 إلى 14 mph يضيف 4 نقاط إلى سجلك.","p":"صحيح. إنها 4 نقاط."},"ref":{"doc":"DE","page":47}},{"id":"de-038","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, what must a driver do after reaching 12 points?","o":["Nothing, it is only a warning","Finish a behavior modification driving course within 90 days","Lose the license for 1 year","Retake the vision test only"],"h1":"It is a class, with a deadline.","h2":"In Delaware, a driver who reaches 12 points must complete a behavior modification driving course within 90 days, or face a 2-month suspension.","p":"Right. At 12 points you must take the course within 90 days."},"es":{"q":"En Delaware, ¿qué debe hacer un conductor al llegar a 12 puntos?","o":["Nada, es solo una advertencia","Terminar un curso de modificación de conducta al volante dentro de 90 días","Perder la licencia por 1 año","Solo repetir el examen de la vista"],"h1":"Es una clase, con una fecha límite.","h2":"En Delaware, un conductor que llega a 12 puntos debe completar un curso de modificación de conducta al volante dentro de 90 días, o tendrá una suspensión de 2 meses.","p":"Correcto. Con 12 puntos debe tomar el curso dentro de 90 días."},"zh":{"q":"在 Delaware，司机累积到 12 分后必须做什么？","o":["什么都不用做，只是警告","在 90 天之内完成行为矫正驾驶课程","失去驾照 1 年","只重新做视力检查"],"h1":"是一门课，而且有期限。","h2":"在 Delaware，累积到 12 分的司机必须在 90 天之内完成行为矫正驾驶课程，否则会被暂停驾驶资格 2 个月。","p":"对。到 12 分时，你必须在 90 天之内上这门课。"},"vi":{"q":"Ở Delaware, tài xế phải làm gì sau khi bị 12 điểm?","o":["Không cần làm gì, đó chỉ là cảnh cáo","Học xong một khóa lái xe điều chỉnh hành vi trong vòng 90 ngày","Bị mất bằng lái 1 năm","Chỉ thi lại bài kiểm tra thị lực"],"h1":"Đó là một lớp học, có thời hạn.","h2":"Ở Delaware, tài xế bị 12 điểm phải học xong một khóa lái xe điều chỉnh hành vi trong vòng 90 ngày, nếu không sẽ bị đình chỉ 2 tháng.","p":"Đúng. Khi bị 12 điểm, bạn phải học khóa này trong vòng 90 ngày."},"tl":{"q":"Sa Delaware, ano ang dapat gawin ng driver pagkatapos umabot sa 12 puntos?","o":["Wala, babala lang ito","Tapusin ang behavior modification driving course sa loob ng 90 araw","Mawalan ng lisensya nang 1 taon","Kumuha ulit ng vision test lang"],"h1":"Isa itong klase, at may deadline.","h2":"Sa Delaware, ang driver na umabot sa 12 puntos ay dapat tapusin ang behavior modification driving course sa loob ng 90 araw, o haharap siya sa 2 buwang suspension.","p":"Tama. Sa 12 puntos, dapat mong kunin ang kurso sa loob ng 90 araw."},"ar":{"q":"في Delaware، ماذا يجب على السائق أن يفعل بعد أن يصل إلى 12 نقطة؟","o":["لا شيء، إنه تحذير فقط","إنهاء دورة قيادة لتعديل السلوك خلال 90 يومًا","فقدان الرخصة لمدة سنة واحدة (1)","إعادة فحص النظر فقط"],"h1":"إنها دورة، ولها موعد نهائي.","h2":"في Delaware، يجب على السائق الذي يصل إلى 12 نقطة أن ينهي دورة قيادة لتعديل السلوك خلال 90 يومًا، وإلا تُوقف رخصته لمدة شهرين (2).","p":"صحيح. عند 12 نقطة يجب أن تأخذ الدورة خلال 90 يومًا."},"ref":{"doc":"DE","page":47}},{"id":"de-039","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, a driver is convicted of going 25 mph over the speed limit. What happens to the license?","o":["Nothing happens to it","It is revoked for life","It is suspended for 1 month","It is suspended for 5 years"],"h1":"It is a short suspension, and it grows with more speed.","h2":"In Delaware, driving 25 mph over the limit brings a 1-month license suspension, and it gets longer for each extra 5 mph.","p":"Right. It is a 1-month suspension."},"es":{"q":"En Delaware, un conductor es declarado culpable de manejar 25 mph sobre el límite de velocidad. ¿Qué pasa con su licencia?","o":["No le pasa nada","Se revoca de por vida","Se suspende por 1 mes","Se suspende por 5 años"],"h1":"Es una suspensión corta, y aumenta con más velocidad.","h2":"En Delaware, manejar 25 mph sobre el límite trae una suspensión de la licencia de 1 mes, y es más larga por cada 5 mph adicionales.","p":"Correcto. Es una suspensión de 1 mes."},"zh":{"q":"在 Delaware，一个司机因超速 25 mph 被定罪。驾照会怎样？","o":["什么都不会发生","终身吊销","暂停 1 个月","暂停 5 年"],"h1":"是短期暂停，速度越快时间越长。","h2":"在 Delaware，超速 25 mph 会被暂停驾照 1 个月，每多超 5 mph，暂停时间就更长。","p":"对。暂停 1 个月。"},"vi":{"q":"Ở Delaware, một tài xế bị kết tội chạy quá giới hạn tốc độ 25 mph. Bằng lái sẽ ra sao?","o":["Không có gì xảy ra","Bị thu hồi suốt đời","Bị đình chỉ 1 tháng","Bị đình chỉ 5 năm"],"h1":"Đó là đình chỉ ngắn, và tăng lên khi chạy nhanh hơn.","h2":"Ở Delaware, chạy quá giới hạn 25 mph sẽ bị đình chỉ bằng lái 1 tháng, và thời gian dài hơn cho mỗi 5 mph thêm.","p":"Đúng. Bị đình chỉ 1 tháng."},"tl":{"q":"Sa Delaware, nahatulan ang isang driver sa pagmamaneho nang 25 mph na lampas sa speed limit. Ano ang mangyayari sa lisensya?","o":["Walang mangyayari dito","Rerevoke ito habambuhay","Masususpend ito nang 1 buwan","Masususpend ito nang 5 taon"],"h1":"Maikling suspension ito, at humahaba kapag mas mabilis.","h2":"Sa Delaware, ang pagmamaneho nang 25 mph na lampas sa limit ay may 1 buwang suspension ng lisensya, at humahaba ito sa bawat dagdag na 5 mph.","p":"Tama. 1 buwang suspension ito."},"ar":{"q":"في Delaware، أُدين سائق بالقيادة أسرع من حد السرعة بـ 25 mph. ماذا يحدث للرخصة؟","o":["لا يحدث لها شيء","تُسحب مدى الحياة","تُوقف لمدة شهر واحد (1)","تُوقف لمدة 5 سنوات"],"h1":"إنه إيقاف قصير، ويطول مع زيادة السرعة.","h2":"في Delaware، القيادة أسرع من الحد بـ 25 mph عقوبتها إيقاف الرخصة لمدة شهر واحد (1)، ويطول الإيقاف مع كل 5 mph إضافية.","p":"صحيح. الإيقاف لمدة شهر واحد (1)."},"ref":{"doc":"DE","page":48}},{"id":"de-040","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what can an approved defensive driving course give you?","o":["A 3-point credit","A free license renewal","All your points erased","A higher speed limit"],"h1":"It helps with future penalties, not with points you already have.","h2":"In Delaware, finishing an approved defensive driving course can give you a 3-point credit toward future DMV penalties.","p":"Right. It gives a 3-point credit."},"es":{"q":"En Delaware, ¿qué le puede dar un curso aprobado de manejo defensivo?","o":["Un crédito de 3 puntos","Una renovación de licencia gratis","Que se borren todos sus puntos","Un límite de velocidad más alto"],"h1":"Ayuda con sanciones futuras, no con los puntos que ya tiene.","h2":"En Delaware, terminar un curso aprobado de manejo defensivo le puede dar un crédito de 3 puntos para sanciones futuras del DMV.","p":"Correcto. Da un crédito de 3 puntos."},"zh":{"q":"在 Delaware，完成认可的防御性驾驶课程可以给你什么？","o":["3 分的抵扣","免费更新驾照","清除你所有的分","更高的限速"],"h1":"它帮助的是以后的处罚，不是你已经有的分。","h2":"在 Delaware，完成认可的防御性驾驶课程，可以让你得到 3 分的抵扣，用于以后 DMV 的处罚。","p":"对。它给你 3 分的抵扣。"},"vi":{"q":"Ở Delaware, một khóa lái xe phòng thủ được chấp thuận có thể cho bạn điều gì?","o":["Được trừ 3 điểm","Gia hạn bằng lái miễn phí","Xóa hết điểm của bạn","Được chạy tốc độ cao hơn"],"h1":"Nó giúp với các hình phạt sau này, không phải với điểm bạn đã có.","h2":"Ở Delaware, học xong một khóa lái xe phòng thủ được chấp thuận có thể giúp bạn được trừ 3 điểm cho các hình phạt của DMV sau này.","p":"Đúng. Bạn được trừ 3 điểm."},"tl":{"q":"Sa Delaware, ano ang maibibigay sa iyo ng aprubadong defensive driving course?","o":["3-point credit","Libreng renewal ng lisensya","Mabubura ang lahat ng puntos mo","Mas mataas na speed limit"],"h1":"Nakakatulong ito sa mga parusa sa hinaharap, hindi sa mga puntos na meron ka na.","h2":"Sa Delaware, ang pagtatapos ng aprubadong defensive driving course ay puwedeng magbigay sa iyo ng 3-point credit para sa mga susunod na parusa ng DMV.","p":"Tama. Nagbibigay ito ng 3-point credit."},"ar":{"q":"في Delaware، ماذا يمكن أن تعطيك دورة قيادة دفاعية معتمدة؟","o":["رصيد 3 نقاط","تجديد مجاني للرخصة","مسح كل نقاطك","حد سرعة أعلى"],"h1":"إنها تساعد في العقوبات المستقبلية، لا في النقاط الموجودة عندك الآن.","h2":"في Delaware، إنهاء دورة قيادة دفاعية معتمدة يمكن أن يعطيك رصيد 3 نقاط يُخصم من عقوبات DMV في المستقبل.","p":"صحيح. إنها تعطي رصيد 3 نقاط."},"ref":{"doc":"DE","page":49}},{"id":"de-041","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, after an arrest for driving under the influence, how many days do you have to ask for a DMV hearing?","o":["5 days","15 days","30 days","60 days"],"h1":"It matches the length of the temporary license the officer gives you.","h2":"In Delaware, after a DUI arrest you get a 15-day temporary license and have 15 days to ask for an administrative hearing.","p":"Right. You have 15 days."},"es":{"q":"En Delaware, después de un arresto por manejar bajo la influencia, ¿cuántos días tiene para pedir una audiencia del DMV?","o":["5 días","15 días","30 días","60 días"],"h1":"Es igual al tiempo de la licencia temporal que le da el oficial.","h2":"En Delaware, después de un arresto por DUI usted recibe una licencia temporal de 15 días y tiene 15 días para pedir una audiencia administrativa.","p":"Correcto. Tiene 15 días."},"zh":{"q":"在 Delaware，因酒后或药后驾驶被逮捕后，你有几天时间申请 DMV 听证？","o":["5 天","15 天","30 天","60 天"],"h1":"它和警察给你的临时驾照的天数一样。","h2":"在 Delaware，因 DUI 被逮捕后，你会拿到 15 天的临时驾照，并有 15 天时间申请行政听证。","p":"对。你有 15 天。"},"vi":{"q":"Ở Delaware, sau khi bị bắt vì lái xe khi say rượu hoặc dùng chất kích thích, bạn có bao nhiêu ngày để xin phiên điều trần của DMV?","o":["5 ngày","15 ngày","30 ngày","60 ngày"],"h1":"Bằng với thời hạn của bằng lái tạm thời mà cảnh sát đưa cho bạn.","h2":"Ở Delaware, sau khi bị bắt vì DUI, bạn được cấp bằng lái tạm thời 15 ngày và có 15 ngày để xin phiên điều trần hành chính.","p":"Đúng. Bạn có 15 ngày."},"tl":{"q":"Sa Delaware, pagkatapos maaresto dahil sa pagmamaneho nang lasing o naka-droga, ilang araw ka mayroon para humingi ng DMV hearing?","o":["5 araw","15 araw","30 araw","60 araw"],"h1":"Kapareho ito ng haba ng pansamantalang lisensya na ibinibigay ng pulis.","h2":"Sa Delaware, pagkatapos ng pag-aresto dahil sa DUI, bibigyan ka ng 15 araw na pansamantalang lisensya at may 15 araw ka para humingi ng administrative hearing.","p":"Tama. May 15 araw ka."},"ar":{"q":"في Delaware، بعد القبض عليك بسبب القيادة تحت تأثير الكحول أو المخدرات، كم يومًا لديك لتطلب جلسة استماع من DMV؟","o":["5 أيام","15 يومًا","30 يومًا","60 يومًا"],"h1":"إنها نفس مدة الرخصة المؤقتة التي يعطيك إياها الشرطي.","h2":"في Delaware، بعد القبض عليك بسبب DUI تحصل على رخصة مؤقتة لمدة 15 يومًا، ولديك 15 يومًا لتطلب جلسة استماع إدارية.","p":"صحيح. لديك 15 يومًا."},"ref":{"doc":"DE","page":55}},{"id":"de-042","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a driver is convicted of a first DUI with a blood alcohol level under 0.15. How long does the DMV take away the license?","o":["1 month","6 months","5 years","12 months"],"h1":"It is a full year.","h2":"In Delaware, a first DUI conviction with a blood alcohol level under 0.15 means the DMV takes the license for 12 months.","p":"Right. It is 12 months."},"es":{"q":"En Delaware, un conductor es declarado culpable de un primer DUI con un nivel de alcohol en la sangre menor de 0.15. ¿Por cuánto tiempo le quita la licencia el DMV?","o":["1 mes","6 meses","5 años","12 meses"],"h1":"Es un año completo.","h2":"En Delaware, una primera condena por DUI con un nivel de alcohol en la sangre menor de 0.15 significa que el DMV le quita la licencia por 12 meses.","p":"Correcto. Son 12 meses."},"zh":{"q":"在 Delaware，一个司机第一次 DUI 被定罪，血液酒精浓度低于 0.15。DMV 会收走驾照多久？","o":["1 个月","6 个月","5 年","12 个月"],"h1":"是整整一年。","h2":"在 Delaware，第一次 DUI 定罪且血液酒精浓度低于 0.15，DMV 会收走驾照 12 个月。","p":"对。是 12 个月。"},"vi":{"q":"Ở Delaware, một tài xế bị kết tội DUI lần đầu với nồng độ cồn trong máu dưới 0.15. DMV lấy bằng lái trong bao lâu?","o":["1 tháng","6 tháng","5 năm","12 tháng"],"h1":"Đó là trọn một năm.","h2":"Ở Delaware, bị kết tội DUI lần đầu với nồng độ cồn trong máu dưới 0.15 thì DMV lấy bằng lái 12 tháng.","p":"Đúng. Là 12 tháng."},"tl":{"q":"Sa Delaware, nahatulan ang isang driver sa unang DUI na may blood alcohol level na mas mababa sa 0.15. Gaano katagal kukunin ng DMV ang lisensya?","o":["1 buwan","6 na buwan","5 taon","12 buwan"],"h1":"Isang buong taon ito.","h2":"Sa Delaware, ang unang DUI conviction na may blood alcohol level na mas mababa sa 0.15 ay nangangahulugang kukunin ng DMV ang lisensya nang 12 buwan.","p":"Tama. 12 buwan ito."},"ar":{"q":"في Delaware، أُدين سائق بأول DUI ونسبة الكحول في دمه أقل من 0.15. كم مدة سحب DMV للرخصة؟","o":["شهر واحد (1)","6 أشهر","5 سنوات","12 شهرًا"],"h1":"إنها سنة كاملة.","h2":"في Delaware، الإدانة الأولى بـ DUI مع نسبة كحول في الدم أقل من 0.15 تعني أن DMV تسحب الرخصة لمدة 12 شهرًا.","p":"صحيح. المدة 12 شهرًا."},"ref":{"doc":"DE","page":56}},{"id":"de-043","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a person under 21 is caught with alcohol for the first time. What is the fine?","o":["$25","$100","$500","$1,000"],"h1":"It goes up for a second offense.","h2":"In Delaware, a person under 21 who has or drinks alcohol is fined $100 for the first offense.","p":"Right. The first fine is $100."},"es":{"q":"En Delaware, a una persona menor de 21 años la encuentran con alcohol por primera vez. ¿Cuál es la multa?","o":["$25","$100","$500","$1,000"],"h1":"Sube en una segunda ofensa.","h2":"En Delaware, una persona menor de 21 años que tiene o toma alcohol recibe una multa de $100 la primera vez.","p":"Correcto. La primera multa es de $100."},"zh":{"q":"在 Delaware，一个 21 岁以下的人第一次被发现有酒。罚款是多少？","o":["$25","$100","$500","$1,000"],"h1":"第二次违规罚款会更高。","h2":"在 Delaware，21 岁以下的人持有或喝酒，第一次违规罚款 $100。","p":"对。第一次罚款是 $100。"},"vi":{"q":"Ở Delaware, một người dưới 21 tuổi bị bắt gặp có rượu lần đầu. Tiền phạt là bao nhiêu?","o":["$25","$100","$500","$1,000"],"h1":"Tiền phạt tăng lên ở lần vi phạm thứ hai.","h2":"Ở Delaware, người dưới 21 tuổi có hoặc uống rượu bị phạt $100 cho lần vi phạm đầu tiên.","p":"Đúng. Tiền phạt lần đầu là $100."},"tl":{"q":"Sa Delaware, nahuli sa unang beses na may alak ang isang taong wala pang 21 taong gulang. Magkano ang multa?","o":["$25","$100","$500","$1,000"],"h1":"Tumataas ito sa ikalawang paglabag.","h2":"Sa Delaware, ang taong wala pang 21 taong gulang na may hawak o umiinom ng alak ay pinagmumulta ng $100 sa unang paglabag.","p":"Tama. $100 ang unang multa."},"ar":{"q":"في Delaware، ضُبط شخص عمره أقل من 21 سنة ومعه كحول لأول مرة. كم الغرامة؟","o":["$25","$100","$500","$1,000"],"h1":"تزيد الغرامة في المخالفة الثانية.","h2":"في Delaware، الشخص الذي عمره أقل من 21 سنة ويحمل الكحول أو يشربه يُغرَّم $100 في المخالفة الأولى.","p":"صحيح. الغرامة الأولى $100."},"ref":{"doc":"DE","page":54}},{"id":"de-044","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, besides at night, when must your headlights be on?","o":["Only on the highway","Only when it is snowing","Any time you cannot see beyond 1,000 feet","Any time you have passengers"],"h1":"Think about how far ahead you can see.","h2":"In Delaware, your headlights must be on any time you cannot see clearly beyond 1,000 feet.","p":"Right. Use them when you cannot see past 1,000 feet."},"es":{"q":"En Delaware, además de la noche, ¿cuándo debe tener las luces delanteras encendidas?","o":["Solo en la autopista","Solo cuando está nevando","Siempre que no pueda ver más allá de 1,000 pies","Siempre que lleve pasajeros"],"h1":"Piense en qué tan lejos puede ver.","h2":"En Delaware, sus luces delanteras deben estar encendidas siempre que no pueda ver bien más allá de 1,000 pies.","p":"Correcto. Úselas cuando no pueda ver más allá de 1,000 pies."},"zh":{"q":"在 Delaware，除了晚上以外，什么时候必须开大灯？","o":["只在高速公路上","只在下雪时","任何看不清 1,000 英尺以外的时候","任何有乘客的时候"],"h1":"想一想你能看到前面多远。","h2":"在 Delaware，任何时候你看不清 1,000 英尺以外，都必须开大灯。","p":"对。看不清 1,000 英尺以外时要开灯。"},"vi":{"q":"Ở Delaware, ngoài ban đêm ra, khi nào bạn phải bật đèn pha?","o":["Chỉ trên xa lộ","Chỉ khi có tuyết rơi","Bất cứ khi nào bạn không thể nhìn xa hơn 1,000 feet","Bất cứ khi nào có hành khách"],"h1":"Hãy nghĩ xem bạn có thể nhìn xa đến đâu phía trước.","h2":"Ở Delaware, bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ xa hơn 1,000 feet.","p":"Đúng. Bật đèn khi bạn không thể nhìn xa hơn 1,000 feet."},"tl":{"q":"Sa Delaware, bukod sa gabi, kailan dapat nakabukas ang headlights mo?","o":["Sa highway lang","Kapag umuulan ng niyebe lang","Anumang oras na hindi ka makakita nang lampas sa 1,000 feet","Anumang oras na may pasahero ka"],"h1":"Isipin kung gaano kalayo ang nakikita mo sa unahan.","h2":"Sa Delaware, dapat nakabukas ang headlights mo anumang oras na hindi ka makakita nang malinaw nang lampas sa 1,000 feet.","p":"Tama. Gamitin ang mga ito kapag hindi ka makakita nang lampas sa 1,000 feet."},"ar":{"q":"في Delaware، غير الليل، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["على الطريق السريع فقط","عندما يتساقط الثلج فقط","في أي وقت لا تستطيع فيه أن ترى أبعد من 1,000 قدم","في أي وقت يكون معك ركاب"],"h1":"فكّر في المسافة التي تستطيع أن تراها أمامك.","h2":"في Delaware، يجب أن تكون المصابيح الأمامية مضاءة في أي وقت لا تستطيع فيه أن ترى بوضوح أبعد من 1,000 قدم.","p":"صحيح. استخدمها عندما لا تستطيع أن ترى أبعد من 1,000 قدم."},"ref":{"doc":"DE","page":62}},{"id":"de-045","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, you are following another car at night. Within what distance must you switch to low beams?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"It is shorter than the distance for a car coming toward you.","h2":"In Delaware, you must switch to low beams when you are within 200 feet of the car you are following.","p":"Right. Dim your lights within 200 feet."},"es":{"q":"En Delaware, usted va detrás de otro carro de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["200 pies","50 pies","500 pies","1,000 pies"],"h1":"Es menos que la distancia para un carro que viene de frente.","h2":"En Delaware, debe cambiar a luces bajas cuando esté a 200 pies o menos del carro que va adelante.","p":"Correcto. Baje las luces a 200 pies."},"zh":{"q":"在 Delaware，你晚上跟在另一辆车后面。在多远的距离之内你必须换成近光灯？","o":["200 英尺","50 英尺","500 英尺","1,000 英尺"],"h1":"它比对面来车时的距离短。","h2":"在 Delaware，当你离前面的车 200 英尺之内时，必须换成近光灯。","p":"对。在 200 英尺之内要把灯调暗。"},"vi":{"q":"Ở Delaware, bạn đang chạy sau một xe khác vào ban đêm. Trong khoảng cách nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"Khoảng cách này ngắn hơn khoảng cách với xe chạy ngược chiều.","h2":"Ở Delaware, bạn phải chuyển sang đèn cốt khi bạn ở trong vòng 200 feet của xe bạn đang chạy sau.","p":"Đúng. Giảm đèn trong vòng 200 feet."},"tl":{"q":"Sa Delaware, sumusunod ka sa ibang kotse sa gabi. Sa loob ng anong layo ka dapat lumipat sa low beams?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"Mas maikli ito kaysa sa layo para sa kotseng papalapit sa iyo.","h2":"Sa Delaware, dapat kang lumipat sa low beams kapag nasa loob ka ng 200 feet mula sa kotseng sinusundan mo.","p":"Tama. Hinaan ang ilaw sa loob ng 200 feet."},"ar":{"q":"في Delaware، أنت تسير خلف سيارة أخرى في الليل. ضمن أي مسافة يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["200 قدم","50 قدمًا","500 قدم","1,000 قدم"],"h1":"إنها أقصر من المسافة مع سيارة قادمة نحوك.","h2":"في Delaware، يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون ضمن 200 قدم من السيارة التي تسير خلفها.","p":"صحيح. خفّف أضواءك ضمن 200 قدم."},"ref":{"doc":"DE","page":62}},{"id":"de-046","scope":"DE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Delaware, when may you use studded tires?","o":["All year","November 1 to March 31","December 1 to February 28","October 15 to April 15"],"h1":"The season starts in the middle of October.","h2":"In Delaware, studded tires are legal from October 15 to April 15 and not allowed the rest of the year.","p":"Right. October 15 to April 15."},"es":{"q":"En Delaware, ¿cuándo puede usar llantas con clavos?","o":["Todo el año","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Del 15 de octubre al 15 de abril"],"h1":"La temporada empieza a mediados de octubre.","h2":"En Delaware, las llantas con clavos son legales del 15 de octubre al 15 de abril y no se permiten el resto del año.","p":"Correcto. Del 15 de octubre al 15 de abril."},"zh":{"q":"在 Delaware，什么时候可以使用带钉轮胎？","o":["全年","11 月 1 日到 3 月 31 日","12 月 1 日到 2 月 28 日","10 月 15 日到 4 月 15 日"],"h1":"这个季节从十月中开始。","h2":"在 Delaware，带钉轮胎从 10 月 15 日到 4 月 15 日是合法的，其他时间不准使用。","p":"对。10 月 15 日到 4 月 15 日。"},"vi":{"q":"Ở Delaware, khi nào bạn được dùng lốp xe có đinh?","o":["Cả năm","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 12 đến 28 tháng 2","Từ 15 tháng 10 đến 15 tháng 4"],"h1":"Mùa này bắt đầu vào giữa tháng 10.","h2":"Ở Delaware, lốp xe có đinh hợp pháp từ 15 tháng 10 đến 15 tháng 4 và không được dùng vào thời gian còn lại trong năm.","p":"Đúng. Từ 15 tháng 10 đến 15 tháng 4."},"tl":{"q":"Sa Delaware, kailan ka puwedeng gumamit ng studded tires?","o":["Buong taon","Nobyembre 1 hanggang Marso 31","Disyembre 1 hanggang Pebrero 28","Oktubre 15 hanggang Abril 15"],"h1":"Nagsisimula ang season sa kalagitnaan ng Oktubre.","h2":"Sa Delaware, legal ang studded tires mula Oktubre 15 hanggang Abril 15 at hindi pinapayagan sa natitirang bahagi ng taon.","p":"Tama. Oktubre 15 hanggang Abril 15."},"ar":{"q":"في Delaware، متى يُسمح لك باستخدام الإطارات ذات المسامير؟","o":["طوال السنة","من 1 نوفمبر إلى 31 مارس","من 1 ديسمبر إلى 28 فبراير","من 15 أكتوبر إلى 15 أبريل"],"h1":"يبدأ الموسم في منتصف أكتوبر.","h2":"في Delaware، الإطارات ذات المسامير مسموحة من 15 أكتوبر إلى 15 أبريل وممنوعة في باقي السنة.","p":"صحيح. من 15 أكتوبر إلى 15 أبريل."},"ref":{"doc":"DE","page":62}},{"id":"de-047","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what is the least liability insurance a car must have for injury or death of one person in a crash?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"It is half of the amount for two or more people.","h2":"In Delaware, a car must have at least $25,000 of coverage for injury or death of one person in any one crash.","p":"Right. The minimum is $25,000."},"es":{"q":"En Delaware, ¿cuál es el seguro de responsabilidad mínimo que debe tener un carro por lesiones o muerte de una persona en un choque?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"Es la mitad de la cantidad para dos o más personas.","h2":"En Delaware, un carro debe tener por lo menos $25,000 de cobertura por lesiones o muerte de una persona en un choque.","p":"Correcto. El mínimo es de $25,000."},"zh":{"q":"在 Delaware，一辆车对一次车祸中一个人受伤或死亡，最少必须有多少责任保险？","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"它是两人或更多人金额的一半。","h2":"在 Delaware，一辆车必须有至少 $25,000 的保险，用于任何一次车祸中一个人的受伤或死亡。","p":"对。最少是 $25,000。"},"vi":{"q":"Ở Delaware, bảo hiểm trách nhiệm tối thiểu một chiếc xe phải có cho thương tích hoặc tử vong của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"Bằng một nửa số tiền cho hai người trở lên.","h2":"Ở Delaware, một chiếc xe phải có bảo hiểm ít nhất $25,000 cho thương tích hoặc tử vong của một người trong bất kỳ vụ tai nạn nào.","p":"Đúng. Mức tối thiểu là $25,000."},"tl":{"q":"Sa Delaware, ano ang pinakamababang liability insurance na dapat meron ang kotse para sa pinsala o pagkamatay ng isang tao sa isang aksidente?","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"Kalahati ito ng halaga para sa dalawa o higit pang tao.","h2":"Sa Delaware, dapat may hindi bababa sa $25,000 na coverage ang kotse para sa pinsala o pagkamatay ng isang tao sa anumang isang aksidente.","p":"Tama. $25,000 ang pinakamababa."},"ar":{"q":"في Delaware، ما أقل تأمين مسؤولية يجب أن يكون للسيارة لإصابة أو وفاة شخص واحد في حادث؟","o":["$5,000","$100,000","$25,000","$250,000"],"h1":"إنه نصف المبلغ لشخصين أو أكثر.","h2":"في Delaware، يجب أن يكون للسيارة تأمين بقيمة $25,000 على الأقل لإصابة أو وفاة شخص واحد في أي حادث واحد.","p":"صحيح. الحد الأدنى $25,000."},"ref":{"doc":"DE","page":63}},{"id":"de-048","scope":"DE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Delaware, what speed limit does state law set for Route 1 and Interstate 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"It is the highest limit in the state speed table.","h2":"In Delaware, the speed limit on Route 1 and Interstate 495 is 65 mph.","p":"Right. It is 65 mph."},"es":{"q":"En Delaware, ¿qué límite de velocidad fija la ley estatal para la Ruta 1 y la Interestatal 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Es el límite más alto de la tabla de velocidades del estado.","h2":"En Delaware, el límite de velocidad en la Ruta 1 y la Interestatal 495 es de 65 mph.","p":"Correcto. Es de 65 mph."},"zh":{"q":"在 Delaware，州法律给 Route 1 和 Interstate 495 定的限速是多少？","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"它是州限速表中最高的限速。","h2":"在 Delaware，Route 1 和 Interstate 495 的限速是 65 mph。","p":"对。是 65 mph。"},"vi":{"q":"Ở Delaware, luật tiểu bang đặt giới hạn tốc độ nào cho Route 1 và Interstate 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Đó là giới hạn cao nhất trong bảng tốc độ của tiểu bang.","h2":"Ở Delaware, giới hạn tốc độ trên Route 1 và Interstate 495 là 65 mph.","p":"Đúng. Là 65 mph."},"tl":{"q":"Sa Delaware, anong speed limit ang itinakda ng batas ng estado para sa Route 1 at Interstate 495?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Ito ang pinakamataas na limit sa speed table ng estado.","h2":"Sa Delaware, 65 mph ang speed limit sa Route 1 at Interstate 495.","p":"Tama. 65 mph ito."},"ar":{"q":"في Delaware، ما حد السرعة الذي يحدده قانون الولاية لـ Route 1 و Interstate 495؟","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"إنه أعلى حد في جدول السرعات في الولاية.","h2":"في Delaware، حد السرعة على Route 1 و Interstate 495 هو 65 mph.","p":"صحيح. إنه 65 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-049","scope":"DE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Delaware, if no other limit is posted, what is the speed limit on a divided road or a road with four or more lanes?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"It is a little faster than on a two-lane road.","h2":"In Delaware, the speed limit on divided roads and roads with four or more lanes is 55 mph unless another limit is posted.","p":"Right. It is 55 mph."},"es":{"q":"En Delaware, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una carretera dividida o con cuatro carriles o más?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"Es un poco más rápido que en una carretera de dos carriles.","h2":"En Delaware, el límite de velocidad en carreteras divididas y carreteras con cuatro carriles o más es de 55 mph, salvo que haya otro límite señalado.","p":"Correcto. Es de 55 mph."},"zh":{"q":"在 Delaware，如果没有标出别的限速，有分隔带的道路或四条以上车道的道路限速是多少？","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"它比双车道道路快一点。","h2":"在 Delaware，除非标出别的限速，有分隔带的道路和四条以上车道的道路限速是 55 mph。","p":"对。是 55 mph。"},"vi":{"q":"Ở Delaware, nếu không có biển báo giới hạn khác, giới hạn tốc độ trên đường có dải phân cách hoặc đường có bốn làn trở lên là bao nhiêu?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"Nhanh hơn một chút so với đường hai làn.","h2":"Ở Delaware, giới hạn tốc độ trên đường có dải phân cách và đường có bốn làn trở lên là 55 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Là 55 mph."},"tl":{"q":"Sa Delaware, kung walang ibang limit na nakapaskil, ano ang speed limit sa divided road o sa kalsadang may apat o higit pang lane?","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"Medyo mas mabilis ito kaysa sa kalsadang may dalawang lane.","h2":"Sa Delaware, 55 mph ang speed limit sa divided roads at sa mga kalsadang may apat o higit pang lane maliban kung may ibang limit na nakapaskil.","p":"Tama. 55 mph ito."},"ar":{"q":"في Delaware، إذا لم يكن هناك حد آخر مكتوب، ما حد السرعة على طريق مقسوم أو طريق فيه أربعة مسارات أو أكثر؟","o":["55 mph","45 mph","50 mph","65 mph"],"h1":"إنه أسرع قليلًا من الطريق الذي فيه مساران.","h2":"في Delaware، حد السرعة على الطرق المقسومة والطرق التي فيها أربعة مسارات أو أكثر هو 55 mph ما لم يكن هناك حد آخر مكتوب.","p":"صحيح. إنه 55 mph."},"ref":{"doc":"DE","page":93}},{"id":"de-050","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, you are following a motorcycle at more than 40 mph. How much following distance should you keep?","o":["1 second","2 seconds","4 seconds","10 seconds"],"h1":"It doubles the distance used at lower speeds.","h2":"In Delaware, keep at least 4 seconds behind a motorcycle above 40 mph, and 2 seconds below 40 mph.","p":"Right. Keep 4 seconds behind."},"es":{"q":"En Delaware, usted va detrás de una motocicleta a más de 40 mph. ¿Qué distancia debe mantener?","o":["1 segundo","2 segundos","4 segundos","10 segundos"],"h1":"Es el doble de la distancia que se usa a velocidades más bajas.","h2":"En Delaware, mantenga por lo menos 4 segundos detrás de una motocicleta a más de 40 mph, y 2 segundos a menos de 40 mph.","p":"Correcto. Mantenga 4 segundos de distancia."},"zh":{"q":"在 Delaware，你以超过 40 mph 的速度跟在摩托车后面。你应该保持多少跟车距离？","o":["1 秒","2 秒","4 秒","10 秒"],"h1":"它是低速时距离的两倍。","h2":"在 Delaware，速度超过 40 mph 时，要在摩托车后面保持至少 4 秒；低于 40 mph 时保持 2 秒。","p":"对。保持 4 秒的距离。"},"vi":{"q":"Ở Delaware, bạn đang chạy sau một xe máy với tốc độ trên 40 mph. Bạn nên giữ khoảng cách bao nhiêu?","o":["1 giây","2 giây","4 giây","10 giây"],"h1":"Gấp đôi khoảng cách dùng khi chạy chậm hơn.","h2":"Ở Delaware, hãy giữ ít nhất 4 giây phía sau xe máy khi chạy trên 40 mph, và 2 giây khi chạy dưới 40 mph.","p":"Đúng. Giữ khoảng cách 4 giây."},"tl":{"q":"Sa Delaware, sumusunod ka sa isang motorsiklo nang mahigit 40 mph. Gaano kalayo ang dapat mong panatilihin?","o":["1 segundo","2 segundo","4 na segundo","10 segundo"],"h1":"Doble ito ng layo na ginagamit sa mas mabagal na bilis.","h2":"Sa Delaware, manatili nang hindi bababa sa 4 na segundo sa likod ng motorsiklo kapag lampas sa 40 mph, at 2 segundo kapag mas mababa sa 40 mph.","p":"Tama. Manatili nang 4 na segundo sa likod."},"ar":{"q":"في Delaware، أنت تسير خلف دراجة نارية بسرعة أكثر من 40 mph. ما مسافة المتابعة التي يجب أن تتركها؟","o":["ثانية واحدة (1)","2 ثانية","4 ثوانٍ","10 ثوانٍ"],"h1":"إنها ضعف المسافة في السرعات الأقل.","h2":"في Delaware، اترك 4 ثوانٍ على الأقل خلف الدراجة النارية عندما تكون سرعتك أكثر من 40 mph، و 2 ثانية عندما تكون أقل من 40 mph.","p":"صحيح. ابقَ 4 ثوانٍ خلفها."},"ref":{"doc":"DE","page":100}},{"id":"de-051","scope":"DE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Delaware, may you drive with headphones or earbuds in both ears?","o":["Yes, if the volume is low","Yes, but only in the daytime","Yes, if you are 21 or older","No, it is against the law"],"h1":"You need to hear horns and sirens.","h2":"In Delaware, it is illegal to drive with headphones or earphones that cover or go in both ears.","p":"Right. It is against the law."},"es":{"q":"En Delaware, ¿puede manejar con audífonos en los dos oídos?","o":["Sí, si el volumen está bajo","Sí, pero solo de día","Sí, si tiene 21 años o más","No, es contra la ley"],"h1":"Usted necesita oír bocinas y sirenas.","h2":"En Delaware, es ilegal manejar con audífonos que cubran o entren en los dos oídos.","p":"Correcto. Es contra la ley."},"zh":{"q":"在 Delaware，你可以两只耳朵都戴着耳机开车吗？","o":["可以，如果音量小","可以，但只在白天","可以，如果你 21 岁或以上","不可以，这是违法的"],"h1":"你需要听到喇叭声和警笛声。","h2":"在 Delaware，戴着盖住两只耳朵或塞进两只耳朵的耳机开车是违法的。","p":"对。这是违法的。"},"vi":{"q":"Ở Delaware, bạn có được lái xe khi đeo tai nghe ở cả hai tai không?","o":["Có, nếu âm lượng nhỏ","Có, nhưng chỉ vào ban ngày","Có, nếu bạn từ 21 tuổi trở lên","Không, việc đó là phạm luật"],"h1":"Bạn cần nghe được tiếng còi xe và còi hụ.","h2":"Ở Delaware, lái xe khi đeo tai nghe che hoặc nhét vào cả hai tai là phạm luật.","p":"Đúng. Việc đó là phạm luật."},"tl":{"q":"Sa Delaware, puwede ka bang magmaneho nang may headphones o earbuds sa dalawang tainga?","o":["Oo, kung mahina ang volume","Oo, pero sa araw lang","Oo, kung 21 taong gulang ka o mas matanda","Hindi, labag ito sa batas"],"h1":"Kailangan mong marinig ang mga busina at sirena.","h2":"Sa Delaware, ilegal ang pagmamaneho nang may headphones o earphones na nakatakip o nakapasok sa dalawang tainga.","p":"Tama. Labag ito sa batas."},"ar":{"q":"في Delaware، هل يُسمح لك بالقيادة وسماعات الرأس أو سماعات الأذن في أذنيك الاثنتين؟","o":["نعم، إذا كان الصوت منخفضًا","نعم، لكن في النهار فقط","نعم، إذا كان عمرك 21 سنة أو أكثر","لا، هذا مخالف للقانون"],"h1":"تحتاج أن تسمع أبواق السيارات وصفارات الإنذار.","h2":"في Delaware، القيادة بسماعات تغطي الأذنين الاثنتين أو توضع فيهما مخالفة للقانون.","p":"صحيح. هذا مخالف للقانون."},"ref":{"doc":"DE","page":116}},{"id":"de-052","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how early may you renew your Class D driver license before it expires?","o":["Up to 30 days before","Up to 60 days before","Up to 180 days before","Up to 2 years before"],"h1":"It is about six months.","h2":"In Delaware, you may renew your driver license at any time in the 180 days (six months) before it expires.","p":"Right. You may renew up to 180 days early."},"es":{"q":"En Delaware, ¿con cuánta anticipación puede renovar su licencia de conducir Clase D antes de que venza?","o":["Hasta 30 días antes","Hasta 60 días antes","Hasta 180 días antes","Hasta 2 años antes"],"h1":"Son unos seis meses.","h2":"En Delaware, usted puede renovar su licencia de conducir en cualquier momento durante los 180 días (seis meses) antes de que venza.","p":"Correcto. Puede renovarla hasta 180 días antes."},"ref":{"doc":"DE","page":32}},{"id":"de-053","scope":"DE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Delaware, a car is stopped on the shoulder with its hazard lights flashing. What does the move over law tell you to do?","o":["Move over a lane if you can, or slow down","Nothing; the law is only for police cars","Stop behind it until it drives away","Honk to warn the driver and keep going"],"h1":"The law covers more than police and fire vehicles.","h2":"In Delaware, the move over law also covers any stopped vehicle showing warning signals such as hazard lights or flares, so you change lanes if you can or slow to a safe speed.","p":"Right. Move over if you can, or slow down."},"es":{"q":"En Delaware, un carro está detenido en el acotamiento con las luces de emergencia encendidas. ¿Qué le indica la ley de \"move over\"?","o":["Cambiarse de carril si puede, o bajar la velocidad","Nada; la ley es solo para carros de policía","Detenerse detrás hasta que se vaya","Tocar la bocina y seguir"],"h1":"La ley cubre más que a la policía y los bomberos.","h2":"En Delaware, la ley de \"move over\" también cubre a cualquier vehículo detenido con señales de advertencia, como luces de emergencia o bengalas, así que usted debe cambiarse de carril si puede o bajar a una velocidad segura.","p":"Correcto. Cámbiese de carril si puede, o baje la velocidad."},"ref":{"doc":"DE","page":82}},{"id":"de-054","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you changed your name and updated it with Social Security. How long should you wait before going to the DMV?","o":["No wait at all","2 weeks","30 days","48 hours"],"h1":"The two computer systems need a short time to match.","h2":"In Delaware, you should wait 48 hours after updating Social Security before you go to the DMV to change your name.","p":"Right. Wait 48 hours."},"es":{"q":"En Delaware, usted cambió su nombre y lo actualizó en el Seguro Social. ¿Cuánto debe esperar antes de ir al DMV?","o":["No necesita esperar","2 semanas","30 días","48 horas"],"h1":"Los dos sistemas de computadora necesitan un poco de tiempo para coincidir.","h2":"En Delaware, usted debe esperar 48 horas después de actualizar el Seguro Social antes de ir al DMV a cambiar su nombre.","p":"Correcto. Espere 48 horas."},"ref":{"doc":"DE","page":33}},{"id":"de-055","scope":"DE","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Delaware, a school bus turns on its flashing yellow lights. About how long before the red lights come on?","o":["About 2 seconds","About 10 seconds","About 1 minute","About 5 minutes"],"h1":"It is a short warning, but more than a moment.","h2":"In Delaware, a school bus turns on its flashing yellow lights about 10 seconds before the red lights, so get ready to stop.","p":"Right. About 10 seconds."},"es":{"q":"En Delaware, un autobús escolar enciende sus luces amarillas intermitentes. ¿Más o menos cuánto tiempo antes se encienden las luces rojas?","o":["Unos 2 segundos","Unos 10 segundos","Como 1 minuto","Como 5 minutos"],"h1":"Es un aviso corto, pero más que un instante.","h2":"En Delaware, un autobús escolar enciende sus luces amarillas intermitentes unos 10 segundos antes de las luces rojas, así que prepárese para parar.","p":"Correcto. Unos 10 segundos."},"ref":{"doc":"DE","page":89}},{"id":"de-056","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you move here from another state and apply for a license. How many proofs of Delaware residency must you bring?","o":["One","Two","Three","None"],"h1":"More than one is needed, and they must come from different sources.","h2":"In Delaware, a new resident must bring two proofs of Delaware residency, such as a utility bill and a bank statement.","p":"Right. Bring two proofs of residency."},"es":{"q":"En Delaware, usted se muda desde otro estado y solicita una licencia. ¿Cuántas pruebas de residencia en Delaware debe llevar?","o":["Una","Dos","Tres","Ninguna"],"h1":"Se necesita más de una, y deben ser de fuentes distintas.","h2":"En Delaware, un nuevo residente debe llevar dos pruebas de residencia en Delaware, como una factura de servicios y un estado de cuenta del banco.","p":"Correcto. Lleve dos pruebas de residencia."},"ref":{"doc":"DE","page":31}},{"id":"de-057","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how long is a Driving Privilege Card (DPC) valid?","o":["1 year","2 years","4 years","8 years"],"h1":"It is half as long as a regular license.","h2":"In Delaware, a Driving Privilege Card costs $20 and is valid for 4 years.","p":"Right. A DPC is valid for 4 years."},"es":{"q":"En Delaware, ¿por cuánto tiempo es válida una Tarjeta de Privilegio de Manejo (DPC)?","o":["1 año","2 años","4 años","8 años"],"h1":"Dura la mitad que una licencia normal.","h2":"En Delaware, una Tarjeta de Privilegio de Manejo cuesta $20 y es válida por 4 años.","p":"Correcto. Una DPC es válida por 4 años."},"ref":{"doc":"DE","page":24}},{"id":"de-058","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, you are over 18 and have a regular learner's permit. How old must the licensed driver with you be?","o":["At least 21","At least 18","At least 25","At least 30"],"h1":"It is younger than the GDL supervisor age for teens.","h2":"In Delaware, a first-time learner over 18 must drive with a licensed driver who is at least 21 years old.","p":"Right. The licensed driver must be at least 21."},"es":{"q":"En Delaware, usted tiene más de 18 años y un permiso de aprendizaje normal. ¿Qué edad debe tener el conductor con licencia que va con usted?","o":["Por lo menos 21","Por lo menos 18","Por lo menos 25","Por lo menos 30"],"h1":"Es menor que la edad del supervisor del GDL para adolescentes.","h2":"En Delaware, un aprendiz mayor de 18 años debe manejar con un conductor con licencia que tenga por lo menos 21 años.","p":"Correcto. El conductor con licencia debe tener por lo menos 21 años."},"ref":{"doc":"DE","page":30}},{"id":"de-059","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you are a first-time applicant over 18. Within what time must you pass all your license exams?","o":["30 days","3 months","6 months","12 months"],"h1":"It is one year.","h2":"In Delaware, a first-time applicant over 18 must pass all the license exams within twelve months.","p":"Right. You have 12 months."},"es":{"q":"En Delaware, usted solicita licencia por primera vez y tiene más de 18 años. ¿En qué plazo debe aprobar todos sus exámenes?","o":["30 días","3 meses","6 meses","12 meses"],"h1":"Es un año.","h2":"En Delaware, una persona mayor de 18 años que solicita licencia por primera vez debe aprobar todos los exámenes dentro de doce meses.","p":"Correcto. Tiene 12 meses."},"ref":{"doc":"DE","page":30}},{"id":"de-060","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, a new resident has a valid driver license from another country. Holders from which country may skip the knowledge and road tests?","o":["Germany","Canada","Mexico","Brazil"],"h1":"Delaware has an agreement with this country, Taiwan, and France.","h2":"In Delaware, a reciprocity agreement lets license holders from Germany, Taiwan, and France skip the knowledge and road tests for a Class D license.","p":"Right. Germany is one of them."},"es":{"q":"En Delaware, un nuevo residente tiene una licencia válida de otro país. ¿Las personas de qué país pueden saltarse los exámenes teórico y práctico?","o":["Alemania","Canadá","México","Brasil"],"h1":"Delaware tiene un acuerdo con este país, Taiwán y Francia.","h2":"En Delaware, un acuerdo de reciprocidad permite que las personas con licencia de Alemania, Taiwán y Francia no tomen los exámenes teórico y práctico para una licencia Clase D.","p":"Correcto. Alemania es uno de ellos."},"ref":{"doc":"DE","page":31}},{"id":"de-061","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how long is a motorcycle learner permit valid?","o":["30 days","6 months","1 year","2 years"],"h1":"It can be extended once for the same length of time.","h2":"In Delaware, a motorcycle learner permit is valid for six months, and you may extend it once for six more months.","p":"Right. It is valid for 6 months."},"es":{"q":"En Delaware, ¿por cuánto tiempo es válido un permiso de aprendizaje de motocicleta?","o":["30 días","6 meses","1 año","2 años"],"h1":"Se puede extender una vez por el mismo tiempo.","h2":"En Delaware, un permiso de aprendizaje de motocicleta es válido por seis meses, y se puede extender una vez por seis meses más.","p":"Correcto. Es válido por 6 meses."},"ref":{"doc":"DE","page":39}},{"id":"de-062","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you have a motorcycle learner permit. Which of these may you do?","o":["Carry a passenger in daylight with a helmet","Ride on a local road after sunset","Ride on an interstate in daylight","Ride on a local road in daylight with a helmet"],"h1":"The permit has limits on passengers, darkness, and big highways.","h2":"In Delaware, a motorcycle permit holder may ride only in daylight, with a helmet and eye protection, with no passengers and not on interstate highways.","p":"Right. Daylight, local roads, and a helmet."},"es":{"q":"En Delaware, usted tiene un permiso de aprendizaje de motocicleta. ¿Cuál de estas cosas puede hacer?","o":["Llevar un pasajero de día con casco","Manejar en una calle local de noche","Manejar en una interestatal de día","Manejar en una calle local de día con casco"],"h1":"El permiso tiene límites de pasajeros, de oscuridad y de carreteras grandes.","h2":"En Delaware, quien tiene permiso de motocicleta solo puede manejar de día, con casco y protección para los ojos, sin pasajeros y no en carreteras interestatales.","p":"Correcto. De día, en calles locales y con casco."},"ref":{"doc":"DE","page":39}},{"id":"de-063","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, you just got your motorcycle endorsement. For how long must you and any passenger wear a helmet and eye protection?","o":["For the first 6 months","For the first year","For the first 2 years","Only until age 21"],"h1":"It covers your first couple of years as a rider.","h2":"In Delaware, a newly endorsed rider and anyone riding with them must wear a helmet and eye protection for the first 2 years.","p":"Right. For the first 2 years."},"es":{"q":"En Delaware, usted acaba de obtener su endoso de motocicleta. ¿Por cuánto tiempo deben usted y su pasajero usar casco y protección para los ojos?","o":["Los primeros 6 meses","El primer año","Los primeros 2 años","Solo hasta los 21 años"],"h1":"Cubre sus primeros dos años como motociclista.","h2":"En Delaware, un motociclista con endoso nuevo y cualquier persona que vaya con él deben usar casco y protección para los ojos durante los primeros 2 años.","p":"Correcto. Durante los primeros 2 años."},"ref":{"doc":"DE","page":39}},{"id":"de-064","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, on which weekday are road tests NOT given?","o":["Monday","Wednesday","Thursday","Friday"],"h1":"It is in the middle of the week.","h2":"In Delaware, road tests are given every weekday except Wednesday.","p":"Right. No road tests on Wednesday."},"es":{"q":"En Delaware, ¿qué día de la semana NO se dan exámenes de manejo?","o":["Lunes","Miércoles","Jueves","Viernes"],"h1":"Es a mitad de semana.","h2":"En Delaware, los exámenes de manejo se dan todos los días de semana menos el miércoles.","p":"Correcto. No hay exámenes de manejo los miércoles."},"ref":{"doc":"DE","page":41}},{"id":"de-065","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, you take your road test with a learner's permit. Why must the licensed driver who came with you stay at the DMV?","o":["To drive the car away if you do not pass","To sit in the back during the test","To sign your test score sheet","To answer the examiner's questions"],"h1":"Think about how the car gets home if the test goes badly.","h2":"In Delaware, a licensed driver must stay on site during your road test so they can drive the car away if you do not pass.","p":"Right. They drive the car away if you do not pass."},"es":{"q":"En Delaware, usted toma el examen de manejo con un permiso de aprendizaje. ¿Por qué debe quedarse en el DMV el conductor con licencia que vino con usted?","o":["Para llevarse el carro si usted no aprueba","Para sentarse atrás durante el examen","Para firmar su hoja de resultados","Para contestar las preguntas del examinador"],"h1":"Piense en cómo regresa el carro a casa si el examen sale mal.","h2":"En Delaware, un conductor con licencia debe quedarse en el lugar durante su examen de manejo para poder llevarse el carro si usted no aprueba.","p":"Correcto. Se lleva el carro si usted no aprueba."},"ref":{"doc":"DE","page":43}},{"id":"de-066","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, your vision tests a little worse than 20/40 but within 20/50. What may the DMV allow?","o":["A full license with no limits","Driving only with a passenger","Driving in daylight only","Driving only on local roads"],"h1":"The limit is about the time of day.","h2":"In Delaware, if your vision is between 20/40 and 20/50, the DMV may allow you to drive in daylight only.","p":"Right. Daylight-only driving may be allowed."},"es":{"q":"En Delaware, su vista resulta un poco peor que 20/40, pero dentro de 20/50. ¿Qué puede permitir el DMV?","o":["Una licencia completa sin límites","Manejar solo con un pasajero","Manejar solo de día","Manejar solo en calles locales"],"h1":"El límite tiene que ver con la hora del día.","h2":"En Delaware, si su vista está entre 20/40 y 20/50, el DMV puede permitirle manejar solo de día.","p":"Correcto. Puede permitirle manejar solo de día."},"ref":{"doc":"DE","page":41}},{"id":"de-067","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, your Class D license expired 2 years ago. Which tests must you take to get it back?","o":["No tests, only a fee","Only the road test","The vision, knowledge, and road tests","The vision and knowledge tests"],"h1":"The road test is added only after more than 5 years.","h2":"In Delaware, if your license has been expired for over a year, you must pass the vision and knowledge tests; after more than 5 years, you also take the road test.","p":"Right. Vision and knowledge tests."},"es":{"q":"En Delaware, su licencia Clase D venció hace 2 años. ¿Qué exámenes debe tomar para recuperarla?","o":["Ningún examen, solo pagar","Solo el examen de manejo","Los exámenes de vista, teórico y de manejo","Los exámenes de vista y teórico"],"h1":"El examen de manejo se agrega solo después de más de 5 años.","h2":"En Delaware, si su licencia lleva más de un año vencida, debe aprobar los exámenes de vista y teórico; después de más de 5 años, también toma el examen de manejo.","p":"Correcto. Los exámenes de vista y teórico."},"ref":{"doc":"DE","page":40}},{"id":"de-068","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, reading is hard for you. What may you ask for when you take the knowledge test?","o":["A family member to read it to you","An audio test with headphones","A test with fewer questions","A pass without taking the test"],"h1":"You would listen to the questions.","h2":"In Delaware, audio knowledge tests with headphones are available if you ask for one.","p":"Right. You may ask for an audio test."},"es":{"q":"En Delaware, a usted le cuesta leer. ¿Qué puede pedir cuando tome el examen teórico?","o":["Que un familiar se lo lea","Un examen con audio y audífonos","Un examen con menos preguntas","Aprobar sin tomar el examen"],"h1":"Usted escucharía las preguntas.","h2":"En Delaware, hay exámenes teóricos con audio y audífonos si usted los pide.","p":"Correcto. Puede pedir un examen con audio."},"ref":{"doc":"DE","page":11}},{"id":"de-069","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how many points do you get for running a stop sign or a red light?","o":["1 point","2 points","3 points","6 points"],"h1":"It is more than a minor moving violation, but less than reckless driving.","h2":"In Delaware, disregarding a stop sign or a red light adds 3 points to your record.","p":"Right. It is 3 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por no respetar una señal de alto o una luz roja?","o":["1 punto","2 puntos","3 puntos","6 puntos"],"h1":"Es más que una infracción menor, pero menos que manejar en forma imprudente.","h2":"En Delaware, no respetar una señal de alto o una luz roja agrega 3 puntos a su récord.","p":"Correcto. Son 3 puntos."},"ref":{"doc":"DE","page":47}},{"id":"de-070","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how many points do you get for passing a stopped school bus?","o":["2 points","3 points","4 points","6 points"],"h1":"It is in the highest group, with reckless driving.","h2":"In Delaware, passing a stopped school bus adds 6 points, the same as reckless driving.","p":"Right. It is 6 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por pasar un autobús escolar detenido?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Está en el grupo más alto, junto con manejar en forma imprudente.","h2":"En Delaware, pasar un autobús escolar detenido agrega 6 puntos, lo mismo que manejar en forma imprudente.","p":"Correcto. Son 6 puntos."},"ref":{"doc":"DE","page":47}},{"id":"de-071","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how does the DMV count your points in the second year after a violation?","o":["At half their value","At full value","At double value","They are not counted at all"],"h1":"Points count fully for 12 months, then less.","h2":"In Delaware, the DMV counts points at full value for the first 12 months after a violation and at half value for the next 12 months.","p":"Right. They count at half value."},"es":{"q":"En Delaware, ¿cómo cuenta el DMV sus puntos en el segundo año después de una infracción?","o":["A la mitad de su valor","A su valor completo","Al doble de su valor","Ya no se cuentan"],"h1":"Los puntos cuentan completos por 12 meses, y después menos.","h2":"En Delaware, el DMV cuenta los puntos a su valor completo durante los primeros 12 meses después de una infracción, y a la mitad durante los 12 meses siguientes.","p":"Correcto. Cuentan a la mitad de su valor."},"ref":{"doc":"DE","page":47}},{"id":"de-072","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what happens when a driver reaches 14 points?","o":["An advisory letter only","A 1-week suspension","A 4-month suspension","A 5-year revocation"],"h1":"It is a suspension of several months.","h2":"In Delaware, reaching 14 points brings a mandatory 4-month license suspension.","p":"Right. A 4-month suspension."},"es":{"q":"En Delaware, ¿qué pasa cuando un conductor llega a 14 puntos?","o":["Solo una carta de aviso","Una suspensión de 1 semana","Una suspensión de 4 meses","Una revocación de 5 años"],"h1":"Es una suspensión de varios meses.","h2":"En Delaware, llegar a 14 puntos trae una suspensión obligatoria de la licencia por 4 meses.","p":"Correcto. Una suspensión de 4 meses."},"ref":{"doc":"DE","page":47}},{"id":"de-073","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, you get your first speeding ticket in 3 years, for 8 mph over the limit, and you pay it online. How many points go on your record?","o":["No points","2 points","4 points","5 points"],"h1":"A first small speeding ticket paid by mail or online may get a point credit.","h2":"In Delaware, a first speeding ticket in 3 years for 1 to 14 mph over the limit gets no points if you pay it by mail or online.","p":"Right. No points are added."},"es":{"q":"En Delaware, usted recibe su primera multa por exceso de velocidad en 3 años, por 8 mph sobre el límite, y la paga por internet. ¿Cuántos puntos van a su récord?","o":["Ningún punto","2 puntos","4 puntos","5 puntos"],"h1":"Una primera multa pequeña pagada por correo o por internet puede recibir un crédito de puntos.","h2":"En Delaware, una primera multa en 3 años por ir de 1 a 14 mph sobre el límite no suma puntos si usted la paga por correo o por internet.","p":"Correcto. No se suman puntos."},"ref":{"doc":"DE","page":48}},{"id":"de-074","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how many serious offenses, like DUI or reckless driving, within 5 years can make you a habitual offender?","o":["Two","Three","Five","Ten"],"h1":"It is a small number of serious offenses.","h2":"In Delaware, any three serious offenses, such as DUI, reckless driving, or driving while suspended, within 5 years can make you a habitual offender.","p":"Right. Three serious offenses."},"es":{"q":"En Delaware, ¿cuántas infracciones graves, como manejar bajo la influencia o en forma imprudente, en 5 años pueden convertirlo en infractor habitual?","o":["Dos","Tres","Cinco","Diez"],"h1":"Es un número pequeño de infracciones graves.","h2":"En Delaware, tres infracciones graves cualesquiera, como manejar bajo la influencia, manejar en forma imprudente o manejar con la licencia suspendida, en 5 años pueden convertirlo en infractor habitual.","p":"Correcto. Tres infracciones graves."},"ref":{"doc":"DE","page":45}},{"id":"de-075","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a driver is convicted of driving while the license is suspended. What happens to the suspension?","o":["It ends early and turns into a warning","It stays exactly the same length","It becomes a lifetime revocation","It is extended by the same length, up to 1 year"],"h1":"The time without a license gets longer.","h2":"In Delaware, driving during a suspension extends the suspension by the same length of time, up to one year.","p":"Right. It is extended by the same length, up to 1 year."},"es":{"q":"En Delaware, un conductor es declarado culpable de manejar con la licencia suspendida. ¿Qué pasa con la suspensión?","o":["Termina antes como advertencia","Sigue exactamente igual","Se vuelve una revocación de por vida","Se alarga por el mismo tiempo, hasta 1 año"],"h1":"El tiempo sin licencia se hace más largo.","h2":"En Delaware, manejar durante una suspensión alarga la suspensión por el mismo tiempo, hasta un año.","p":"Correcto. Se alarga por el mismo tiempo, hasta 1 año."},"ref":{"doc":"DE","page":49}},{"id":"de-076","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, when is a driver guilty of aggressive driving?","o":["After any one speeding ticket on a highway","After 3 or more listed offenses in one episode","After honking the horn at another driver","After 2 parking tickets in the same month"],"h1":"It is several offenses, like speeding and tailgating, all at once.","h2":"In Delaware, a driver who commits three or more listed offenses, such as speeding, tailgating, or unsafe lane changes, in one continuous episode is guilty of aggressive driving.","p":"Right. Three or more offenses in one episode."},"es":{"q":"En Delaware, ¿cuándo es culpable un conductor de manejo agresivo?","o":["Con cualquier multa por velocidad en carretera","Con 3 o más infracciones de la lista en un episodio","Por tocarle la bocina a otro conductor","Por 2 multas de estacionamiento en el mismo mes"],"h1":"Son varias infracciones, como exceso de velocidad y seguir muy de cerca, todas a la vez.","h2":"En Delaware, un conductor que comete tres o más infracciones de la lista, como exceso de velocidad, seguir muy de cerca o cambiar de carril sin cuidado, en un mismo episodio continuo es culpable de manejo agresivo.","p":"Correcto. Tres o más infracciones en un mismo episodio."},"ref":{"doc":"DE","page":49}},{"id":"de-077","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, a teen under 18 is found guilty of driving under the influence (DUI). How long is the license revoked?","o":["Until age 21","For 30 days","Until age 18","For 6 months"],"h1":"It lasts until the age when drinking becomes legal.","h2":"In Delaware, a juvenile found guilty of DUI has the license revoked until age 21.","p":"Right. It is revoked until age 21."},"es":{"q":"En Delaware, un adolescente menor de 18 años es declarado culpable de manejar bajo la influencia (DUI). ¿Por cuánto tiempo se le revoca la licencia?","o":["Hasta los 21 años","Por 30 días","Hasta los 18 años","Por 6 meses"],"h1":"Dura hasta la edad en que tomar alcohol es legal.","h2":"En Delaware, a un menor declarado culpable de DUI se le revoca la licencia hasta que cumpla 21 años.","p":"Correcto. Se revoca hasta los 21 años."},"ref":{"doc":"DE","page":54}},{"id":"de-078","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, what fine can a court give for a first DUI conviction?","o":["$50 to $100","$100 to $300","$500 to $1,500","$5,000 to $10,000"],"h1":"The lowest amount is several hundred dollars.","h2":"In Delaware, a first DUI conviction brings a court fine of $500 to $1,500, and up to 12 months in jail is possible.","p":"Right. $500 to $1,500."},"es":{"q":"En Delaware, ¿qué multa puede dar un tribunal por una primera condena de DUI?","o":["De $50 a $100","De $100 a $300","De $500 a $1,500","De $5,000 a $10,000"],"h1":"La cantidad más baja es de varios cientos de dólares.","h2":"En Delaware, una primera condena de DUI trae una multa de $500 a $1,500, y es posible pasar hasta 12 meses en la cárcel.","p":"Correcto. De $500 a $1,500."},"ref":{"doc":"DE","page":56}},{"id":"de-079","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what kind of crime is a third DUI offense?","o":["A civil offense with a small fine","A parking violation","A warning with no penalty","A felony"],"h1":"It is the most serious type of crime.","h2":"In Delaware, a third DUI offense is a felony, with prison time of one to two years.","p":"Right. It is a felony."},"es":{"q":"En Delaware, ¿qué tipo de delito es una tercera infracción de DUI?","o":["Una falta civil con una multa pequeña","Una infracción de estacionamiento","Una advertencia sin castigo","Un delito grave (felonía)"],"h1":"Es el tipo de delito más serio.","h2":"En Delaware, una tercera infracción de DUI es un delito grave (felonía), con prisión de uno a dos años.","p":"Correcto. Es un delito grave."},"ref":{"doc":"DE","page":57}},{"id":"de-080","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you bring a car from another state and title it here. What document fee do you usually pay?","o":["1 percent of its value","5.25 percent of its value","10 percent of its value","A flat $5"],"h1":"It is a little over 5 percent.","h2":"In Delaware, titling a vehicle usually costs a document fee of 5.25 percent of its value, unless you paid a similar tax to another state within 90 days.","p":"Right. It is 5.25 percent."},"es":{"q":"En Delaware, usted trae un carro de otro estado y lo titula aquí. ¿Qué tarifa de documento paga normalmente?","o":["El 1 por ciento de su valor","El 5.25 por ciento de su valor","El 10 por ciento de su valor","Una tarifa fija de $5"],"h1":"Es un poco más del 5 por ciento.","h2":"En Delaware, titular un vehículo normalmente cuesta una tarifa de documento del 5.25 por ciento de su valor, a menos que usted haya pagado un impuesto parecido a otro estado en los últimos 90 días.","p":"Correcto. Es el 5.25 por ciento."},"ref":{"doc":"DE","page":66}},{"id":"de-081","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, your vehicle registration expires today. Is there a grace period?","o":["No, it expires at midnight today","Yes, 10 days","Yes, 30 days","Yes, until your birthday"],"h1":"The date on the sticker is the last day.","h2":"In Delaware, a registration expires at midnight on the date shown, and there is no grace period.","p":"Right. There is no grace period."},"es":{"q":"En Delaware, el registro de su vehículo vence hoy. ¿Hay un período de gracia?","o":["No, vence hoy a la medianoche","Sí, 10 días","Sí, 30 días","Sí, hasta su cumpleaños"],"h1":"La fecha de la calcomanía es el último día.","h2":"En Delaware, el registro vence a la medianoche de la fecha que aparece, y no hay período de gracia.","p":"Correcto. No hay período de gracia."},"ref":{"doc":"DE","page":68}},{"id":"de-082","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, which cars no longer need a DMV safety inspection to renew registration?","o":["Only electric cars","Cars driven less than 5,000 miles a year","Cars 7 model years old or newer","Cars older than 25 years"],"h1":"It depends on how new the car is.","h2":"In Delaware, vehicles that are seven model years old or newer do not need a safety inspection to renew their registration.","p":"Right. Cars 7 model years old or newer."},"es":{"q":"En Delaware, ¿qué carros ya no necesitan inspección de seguridad del DMV para renovar el registro?","o":["Solo los carros eléctricos","Los carros que recorren menos de 5,000 millas al año","Los carros de 7 años de modelo o más nuevos","Los carros de más de 25 años"],"h1":"Depende de qué tan nuevo es el carro.","h2":"En Delaware, los vehículos de siete años de modelo o más nuevos no necesitan inspección de seguridad para renovar su registro.","p":"Correcto. Los carros de 7 años de modelo o más nuevos."},"ref":{"doc":"DE","page":65}},{"id":"de-083","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you want to cancel the insurance on your car. What must you do first?","o":["Sell the car to a dealer","Turn in the plate to the DMV","Get a new driver license","Tell the police department"],"h1":"It is something attached to the back of the car.","h2":"In Delaware, you must turn in your license plate to the DMV before you cancel the car's insurance, or you will be fined.","p":"Right. Turn in the plate first."},"es":{"q":"En Delaware, usted quiere cancelar el seguro de su carro. ¿Qué debe hacer primero?","o":["Vender el carro a un concesionario","Entregar la placa al DMV","Sacar una licencia de conducir nueva","Avisar al departamento de policía"],"h1":"Es algo que va en la parte de atrás del carro.","h2":"En Delaware, usted debe entregar la placa al DMV antes de cancelar el seguro del carro, o recibirá multas.","p":"Correcto. Entregue primero la placa."},"ref":{"doc":"DE","page":64}},{"id":"de-084","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a driver is caught with no car insurance a second time within 3 years. What is the smallest fine?","o":["$500","$1,000","$1,500","$3,000"],"h1":"It is twice the smallest fine for a first offense.","h2":"In Delaware, a second uninsured offense within 3 years brings a fine of $3,000 to $4,000.","p":"Right. At least $3,000."},"es":{"q":"En Delaware, a un conductor lo encuentran sin seguro por segunda vez en 3 años. ¿Cuál es la multa más baja?","o":["$500","$1,000","$1,500","$3,000"],"h1":"Es el doble de la multa más baja por la primera vez.","h2":"En Delaware, una segunda infracción por no tener seguro en 3 años trae una multa de $3,000 a $4,000.","p":"Correcto. Por lo menos $3,000."},"ref":{"doc":"DE","page":63}},{"id":"de-085","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, on which windows is aftermarket window tint not allowed without a medical waiver?","o":["The front side windows next to the driver","The back seat side windows","The rear window","The top 5 inches of the windshield"],"h1":"The police need to see the driver from the side.","h2":"In Delaware, aftermarket tint is not allowed on the front side windows to the driver's left and right unless you carry an approved tint waiver, and the windshield may be tinted only in its top 5 inches.","p":"Right. Not on the front side windows."},"es":{"q":"En Delaware, ¿en qué ventanas no se permite poner polarizado sin un permiso médico?","o":["Las ventanas delanteras junto al conductor","Las ventanas laterales de atrás","La ventana trasera","Las 5 pulgadas de arriba del parabrisas"],"h1":"La policía necesita ver al conductor desde el lado.","h2":"En Delaware, no se permite el polarizado añadido en las ventanas delanteras a la izquierda y a la derecha del conductor a menos que lleve un permiso de polarizado aprobado, y el parabrisas solo puede polarizarse en sus 5 pulgadas de arriba.","p":"Correcto. No en las ventanas delanteras de los lados."},"ref":{"doc":"DE","page":62}},{"id":"de-086","scope":"DE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Delaware, a child is under age 2 and weighs under 30 pounds. What kind of seat does the law require?","o":["A booster seat","A rear-facing car seat","A seat belt alone","A forward-facing seat in the front"],"h1":"The child faces the back of the car.","h2":"In Delaware, a child under age 2 and under 30 pounds must ride in a rear-facing car seat.","p":"Right. A rear-facing car seat."},"es":{"q":"En Delaware, un niño tiene menos de 2 años y pesa menos de 30 libras. ¿Qué tipo de asiento exige la ley?","o":["Un asiento elevado (booster)","Un asiento de seguridad mirando hacia atrás","Solo el cinturón de seguridad","Un asiento mirando hacia adelante en el frente"],"h1":"El niño mira hacia la parte de atrás del carro.","h2":"En Delaware, un niño menor de 2 años y de menos de 30 libras debe ir en un asiento de seguridad mirando hacia atrás.","p":"Correcto. Un asiento mirando hacia atrás."},"ref":{"doc":"DE","page":109}},{"id":"de-087","scope":"DE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Delaware, a bicyclist comes to a stop sign at a quiet minor road with no other traffic. What does the law allow?","o":["The cyclist must get off and walk","The cyclist must wait for a car to wave them on","The cyclist may slow, yield, and go without a full stop","The cyclist may ride through without looking"],"h1":"The cyclist may treat it like a yield sign.","h2":"In Delaware, a bicyclist may treat a stop sign at a minor road like a yield sign: slow down, yield to traffic, then go without a full stop.","p":"Right. The cyclist may yield instead of stopping."},"es":{"q":"En Delaware, un ciclista llega a una señal de alto en una calle menor y tranquila, sin otro tráfico. ¿Qué permite la ley?","o":["El ciclista debe bajarse y caminar","El ciclista debe esperar que un carro le dé paso","Puede ceder el paso y seguir sin parar","El ciclista puede pasar sin mirar"],"h1":"El ciclista puede tratarla como una señal de ceder el paso.","h2":"En Delaware, un ciclista puede tratar una señal de alto en una calle menor como una señal de ceder el paso: bajar la velocidad, ceder el paso al tráfico y seguir sin parar por completo.","p":"Correcto. El ciclista puede ceder el paso en vez de parar."},"ref":{"doc":"DE","page":99}},{"id":"de-088","scope":"DE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Delaware, when may you honk your horn at a bicyclist?","o":["Whenever you want to pass the cyclist","When the cyclist is riding too slowly","Before every turn you make","Only to warn of a crash about to happen"],"h1":"Honking can startle a rider.","h2":"In Delaware, it is illegal to honk at a bicyclist except to warn of an imminent crash.","p":"Right. Only to warn of an imminent crash."},"es":{"q":"En Delaware, ¿cuándo puede tocar la bocina a un ciclista?","o":["Siempre que quiera pasar al ciclista","Cuando el ciclista va demasiado despacio","Antes de cada vuelta que da","Solo para avisar de un choque a punto de pasar"],"h1":"La bocina puede asustar al ciclista.","h2":"En Delaware, es ilegal tocar la bocina a un ciclista, excepto para avisar de un choque inminente.","p":"Correcto. Solo para avisar de un choque inminente."},"ref":{"doc":"DE","page":97}},{"id":"de-089","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, who must wear a bicycle helmet?","o":["Every rider under 18","Only riders under 12","Only adults on busy roads","No one, it is only advised"],"h1":"It covers all minors.","h2":"In Delaware, every bicycle rider under the age of 18 must wear a properly fitted and fastened helmet.","p":"Right. Every rider under 18."},"es":{"q":"En Delaware, ¿quién debe usar casco de bicicleta?","o":["Todo ciclista menor de 18 años","Solo los menores de 12 años","Solo los adultos en calles con mucho tráfico","Nadie, solo se recomienda"],"h1":"Cubre a todos los menores de edad.","h2":"En Delaware, todo ciclista menor de 18 años debe usar un casco bien ajustado y abrochado.","p":"Correcto. Todo ciclista menor de 18 años."},"ref":{"doc":"DE","page":99}},{"id":"de-090","scope":"DE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Delaware, a car ahead of you is stopped, waiting to turn left. May you use the shoulder to pass it on the right?","o":["No, never","Only on an interstate","Yes, but with extreme care","Only if you honk first"],"h1":"It is legal here, but other drivers will not expect you there.","h2":"In Delaware, you may use the shoulder to pass a left-turning vehicle on the right, but you must take extreme care.","p":"Right. It is allowed, with extreme care."},"es":{"q":"En Delaware, un carro adelante está detenido esperando dar vuelta a la izquierda. ¿Puede usar el acotamiento para pasarlo por la derecha?","o":["No, nunca","Solo en una carretera interestatal","Sí, pero con mucho cuidado","Solo si toca la bocina primero"],"h1":"Aquí es legal, pero los otros conductores no esperan verlo ahí.","h2":"En Delaware, usted puede usar el acotamiento para pasar por la derecha a un vehículo que va a dar vuelta a la izquierda, pero debe tener mucho cuidado.","p":"Correcto. Está permitido, con mucho cuidado."},"ref":{"doc":"DE","page":87}},{"id":"de-091","scope":"DE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Delaware, what happens to the fine for speeding in a work zone?","o":["It stays the same","It is doubled","It is cut in half","It becomes a warning"],"h1":"Work zones carry higher fines to protect workers.","h2":"In Delaware, fines for going over the speed limit in a work zone are doubled.","p":"Right. The fine is doubled."},"es":{"q":"En Delaware, ¿qué pasa con la multa por exceso de velocidad en una zona de obras?","o":["Sigue igual","Se duplica","Se reduce a la mitad","Se vuelve una advertencia"],"h1":"Las zonas de obras tienen multas más altas para proteger a los trabajadores.","h2":"En Delaware, las multas por pasar el límite de velocidad en una zona de obras se duplican.","p":"Correcto. La multa se duplica."},"ref":{"doc":"DE","page":79}},{"id":"de-092","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you renew your driver license after it has expired. What extra fee do you pay?","o":["No extra fee","A $10 late fee","A $50 late fee","A $100 late fee"],"h1":"It is a small fee, about the cost of a lunch.","h2":"In Delaware, a $10 late fee is charged when you renew your driver license after the expiration date.","p":"Right. The late fee is $10."},"es":{"q":"En Delaware, usted renueva su licencia de conducir después de que venció. ¿Qué cargo extra paga?","o":["Ningún cargo extra","Un cargo por atraso de $10","Un cargo por atraso de $50","Un cargo por atraso de $100"],"h1":"Es un cargo pequeño, como el costo de un almuerzo.","h2":"En Delaware, se cobra un cargo por atraso de $10 cuando usted renueva su licencia de conducir después de la fecha de vencimiento.","p":"Correcto. El cargo por atraso es de $10."},"ref":{"doc":"DE","page":32}},{"id":"de-093","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, your driver license was lost. How much does a replacement license cost?","o":["It is free","$5","$50","$20"],"h1":"It costs less than a new 8-year license.","h2":"In Delaware, a replacement for a lost, stolen, or destroyed license costs $20, online or at the DMV.","p":"Right. A replacement costs $20."},"es":{"q":"En Delaware, usted perdió su licencia de conducir. ¿Cuánto cuesta una licencia de reemplazo?","o":["Es gratis","$5","$50","$20"],"h1":"Cuesta menos que una licencia nueva de 8 años.","h2":"En Delaware, el reemplazo de una licencia perdida, robada o destruida cuesta $20, en línea o en el DMV.","p":"Correcto. El reemplazo cuesta $20."},"ref":{"doc":"DE","page":33}},{"id":"de-094","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, you legally changed your name. How soon must you go to the DMV to change it on your license?","o":["Within 30 days","Within 1 year","At your next renewal","Within 6 months"],"h1":"It is about one month.","h2":"In Delaware, you must go to the DMV in person within 30 days after a legal name change to update your license or ID card.","p":"Right. Go within 30 days."},"es":{"q":"En Delaware, usted cambió su nombre legalmente. ¿En cuánto tiempo debe ir al DMV para cambiarlo en su licencia?","o":["Dentro de 30 días","Dentro de 1 año","En su próxima renovación","Dentro de 6 meses"],"h1":"Es más o menos un mes.","h2":"En Delaware, usted debe ir en persona al DMV dentro de los 30 días después de un cambio legal de nombre para actualizar su licencia o tarjeta de identificación.","p":"Correcto. Vaya dentro de 30 días."},"ref":{"doc":"DE","page":33}},{"id":"de-095","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, you moved within the state and bring your current license to the DMV to update the address. What does the new license cost?","o":["$10","$20","Nothing","$50"],"h1":"You only pay if you do not have your current license.","h2":"In Delaware, the DMV replaces your license with the new address at no cost if you bring your current license.","p":"Right. It is free if you bring your current license."},"es":{"q":"En Delaware, usted se mudó dentro del estado y lleva su licencia actual al DMV para cambiar la dirección. ¿Cuánto cuesta la licencia nueva?","o":["$10","$20","Nada","$50"],"h1":"Solo paga si no tiene su licencia actual.","h2":"En Delaware, el DMV le da una licencia con la nueva dirección sin costo si usted lleva su licencia actual.","p":"Correcto. Es gratis si lleva su licencia actual."},"ref":{"doc":"DE","page":33}},{"id":"de-096","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you are 18 or older and getting your first license. What is true about the Graduated Driver License (GDL) program?","o":["You must always join it","It is optional for you","It is only for people over 25","It lasts 3 years for you"],"h1":"Adults have a choice.","h2":"In Delaware, the GDL program is optional at age 18 or older; if you opt out, you need no sponsor but must pass the eye, knowledge, and road exams at the DMV.","p":"Right. At 18 or older, the GDL program is optional."},"es":{"q":"En Delaware, usted tiene 18 años o más y va a sacar su primera licencia. ¿Qué es cierto sobre el programa de licencia graduada (GDL)?","o":["Siempre debe entrar en él","Para usted es opcional","Es solo para mayores de 25 años","Para usted dura 3 años"],"h1":"Los adultos pueden elegir.","h2":"En Delaware, el programa GDL es opcional a partir de los 18 años; si no entra, no necesita patrocinador, pero debe aprobar los exámenes de la vista, de conocimientos y de manejo en el DMV.","p":"Correcto. A los 18 años o más, el programa GDL es opcional."},"ref":{"doc":"DE","page":27}},{"id":"de-097","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a parent signs as sponsor for a teen in the GDL program. The teen causes a crash through careless driving. Who can be held responsible for the damages?","o":["Only the teen","Only the driving school","Only the state","The teen and the sponsor together"],"h1":"Signing the application is a serious promise.","h2":"In Delaware, the sponsor who signs the GDL application is jointly liable with the teen for damages caused by the teen's negligence.","p":"Right. The sponsor shares the responsibility."},"es":{"q":"En Delaware, un padre firma como patrocinador de un joven en el programa GDL. El joven causa un choque por manejar sin cuidado. ¿Quién puede ser responsable por los daños?","o":["Solo el joven","Solo la escuela de manejo","Solo el estado","El joven y el patrocinador juntos"],"h1":"Firmar la solicitud es una promesa seria.","h2":"En Delaware, el patrocinador que firma la solicitud del GDL es responsable junto con el joven por los daños causados por la negligencia del joven.","p":"Correcto. El patrocinador comparte la responsabilidad."},"ref":{"doc":"DE","page":28}},{"id":"de-098","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what may you NOT use a Driving Privilege Card (DPC) for?","o":["As proof of identity","Driving a car in Delaware","Driving to work","Driving with a passenger"],"h1":"The card is for one purpose only.","h2":"In Delaware, a Driving Privilege Card is valid for driving only and may not be used as a form of identification.","p":"Right. A DPC is not a valid ID."},"es":{"q":"En Delaware, ¿para qué NO puede usar una tarjeta de privilegio de manejo (DPC)?","o":["Como prueba de identidad","Para manejar un carro en Delaware","Para manejar al trabajo","Para manejar con un pasajero"],"h1":"La tarjeta sirve para una sola cosa.","h2":"En Delaware, la tarjeta de privilegio de manejo sirve solo para manejar y no se puede usar como identificación.","p":"Correcto. La DPC no es una identificación válida."},"ref":{"doc":"DE","page":24}},{"id":"de-099","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, you bring a letter as proof of residency. How recent must its postmark be?","o":["Within the last 7 days","Within the last year","Within the last 60 days","Any date is fine"],"h1":"It is about two months.","h2":"In Delaware, mail used as proof of residency must be delivered by the U.S. Postal Service and postmarked or received within the last 60 days.","p":"Right. It must be from the last 60 days."},"es":{"q":"En Delaware, usted lleva una carta como prueba de residencia. ¿Qué tan reciente debe ser el matasellos?","o":["De los últimos 7 días","Del último año","De los últimos 60 días","Cualquier fecha sirve"],"h1":"Son unos dos meses.","h2":"En Delaware, el correo que usa como prueba de residencia debe llegar por el Servicio Postal de EE. UU. y tener matasellos o haber sido recibido en los últimos 60 días.","p":"Correcto. Debe ser de los últimos 60 días."},"ref":{"doc":"DE","page":27}},{"id":"de-100","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you are temporarily out of state and your license needs extending. For how long can a one-time temporary license be issued?","o":["Up to 30 days","Up to 6 months","Up to 2 years","Up to 8 years"],"h1":"It is half a year at most.","h2":"In Delaware, a one-time temporary license for a driver who is out of state is issued for no more than six months.","p":"Right. Up to six months."},"es":{"q":"En Delaware, usted está fuera del estado por un tiempo y necesita extender su licencia. ¿Por cuánto tiempo se puede dar una licencia temporal de una sola vez?","o":["Hasta 30 días","Hasta 6 meses","Hasta 2 años","Hasta 8 años"],"h1":"Es medio año como máximo.","h2":"En Delaware, una licencia temporal de una sola vez para un conductor que está fuera del estado se da por no más de seis meses.","p":"Correcto. Hasta seis meses."},"ref":{"doc":"DE","page":39}},{"id":"de-101","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, how soon after passing the motorcycle knowledge exam may you take the motorcycle road exam?","o":["The same day","6 months","30 days","10 days"],"h1":"It is shorter than the wait for a car road test.","h2":"In Delaware, you may take the motorcycle road exam 10 days after you pass the motorcycle knowledge exam.","p":"Right. You wait 10 days."},"es":{"q":"En Delaware, ¿cuánto tiempo después de aprobar el examen de conocimientos de motocicleta puede tomar el examen de manejo de motocicleta?","o":["El mismo día","6 meses","30 días","10 días"],"h1":"Es menos que la espera para el examen de manejo de carro.","h2":"En Delaware, usted puede tomar el examen de manejo de motocicleta 10 días después de aprobar el examen de conocimientos de motocicleta.","p":"Correcto. Espera 10 días."},"ref":{"doc":"DE","page":41}},{"id":"de-102","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, during the car road test, how far will you be asked to back up?","o":["50 feet","10 feet","500 feet","One full block"],"h1":"It is about the length of three cars.","h2":"In Delaware, the road test includes backing your car 50 feet.","p":"Right. You back up 50 feet."},"es":{"q":"En Delaware, durante el examen de manejo, ¿qué distancia le pedirán que maneje en reversa?","o":["50 pies","10 pies","500 pies","Una cuadra entera"],"h1":"Es más o menos el largo de tres carros.","h2":"En Delaware, el examen de manejo incluye manejar su carro en reversa 50 pies.","p":"Correcto. Maneja en reversa 50 pies."},"ref":{"doc":"DE","page":42}},{"id":"de-103","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, you are licensed based on a doctor's report about a medical condition. By what date each year may the DMV require a new report?","o":["By January 1","Only when you renew every 8 years","By the last day of your birthday month","Within 10 days of any crash"],"h1":"The deadline is tied to your birthday.","h2":"In Delaware, a driver licensed on a medical report may have to send a new report every year by the last day of their birthday month, or the license is suspended.","p":"Right. By the end of your birthday month."},"es":{"q":"En Delaware, usted tiene licencia gracias a un informe médico sobre una condición de salud. ¿Para qué fecha de cada año puede pedirle el DMV un informe nuevo?","o":["Para el 1 de enero","Solo al renovar cada 8 años","Para el último día del mes de su cumpleaños","Dentro de 10 días de cualquier choque"],"h1":"La fecha límite depende de su cumpleaños.","h2":"En Delaware, un conductor con licencia basada en un informe médico puede tener que enviar un informe nuevo cada año a más tardar el último día del mes de su cumpleaños; si no, se suspende la licencia.","p":"Correcto. Para el final del mes de su cumpleaños."},"ref":{"doc":"DE","page":43}},{"id":"de-104","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how many reckless driving convictions within 12 months lead to a mandatory license revocation?","o":["One","Three","Five","Ten"],"h1":"It is more than one but fewer than five.","h2":"In Delaware, three reckless driving convictions within 12 consecutive months mean the license must be revoked.","p":"Right. Three convictions in 12 months."},"es":{"q":"En Delaware, ¿cuántas condenas por manejo imprudente en 12 meses causan la revocación obligatoria de la licencia?","o":["Una","Tres","Cinco","Diez"],"h1":"Es más de una pero menos de cinco.","h2":"En Delaware, tres condenas por manejo imprudente en 12 meses seguidos significan que la licencia se debe revocar.","p":"Correcto. Tres condenas en 12 meses."},"ref":{"doc":"DE","page":45}},{"id":"de-105","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, which of these acts can get your driver license suspended?","o":["Driving with the radio on","Using cruise control on a highway","Parking in a paid lot","Spinning your wheels or tearing up grass"],"h1":"Think of showing off with your car.","h2":"In Delaware, spinning your wheels and turfing, which means tearing up grass or yards with a vehicle, are reasons for license suspension.","p":"Right. Spinning wheels and turfing can cost you your license."},"es":{"q":"En Delaware, ¿cuál de estos actos puede causar la suspensión de su licencia de conducir?","o":["Manejar con el radio prendido","Usar el control de crucero en la autopista","Estacionar en un lote pagado","Hacer patinar las llantas o destrozar el césped"],"h1":"Piense en presumir con el carro.","h2":"En Delaware, hacer patinar las llantas y destrozar el césped o los jardines con un vehículo son motivos de suspensión de la licencia.","p":"Correcto. Patinar las llantas y destrozar el césped le pueden costar la licencia."},"ref":{"doc":"DE","page":46}},{"id":"de-106","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, how many points do you get for driving 1 to 9 mph over the speed limit?","o":["2 points","4 points","6 points","No points ever"],"h1":"It is the lowest number on the speeding list.","h2":"In Delaware, speeding 1 to 9 mph over the posted limit adds 2 points to your record.","p":"Right. It is 2 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por manejar de 1 a 9 mph sobre el límite de velocidad?","o":["2 puntos","4 puntos","6 puntos","Nunca hay puntos"],"h1":"Es el número más bajo en la lista de exceso de velocidad.","h2":"En Delaware, manejar de 1 a 9 mph sobre el límite marcado agrega 2 puntos a su historial.","p":"Correcto. Son 2 puntos."},"ref":{"doc":"DE","page":47}},{"id":"de-107","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how many points do you get for a reckless driving conviction?","o":["2 points","3 points","6 points","12 points"],"h1":"It is the same as for aggressive driving.","h2":"In Delaware, a reckless driving conviction adds 6 points to your record.","p":"Right. Reckless driving is 6 points."},"es":{"q":"En Delaware, ¿cuántos puntos recibe por una condena por manejo imprudente?","o":["2 puntos","3 puntos","6 puntos","12 puntos"],"h1":"Es lo mismo que por manejo agresivo.","h2":"En Delaware, una condena por manejo imprudente agrega 6 puntos a su historial.","p":"Correcto. El manejo imprudente son 6 puntos."},"ref":{"doc":"DE","page":47}},{"id":"de-108","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a driver is convicted of going 22 mph over the speed limit. What does the DMV send?","o":["A one-year suspension notice","An advisory letter","A new license","Nothing at all"],"h1":"At 25 mph over, a suspension starts. This is a little below that.","h2":"In Delaware, the DMV sends an advisory letter to a driver convicted of speeding 20 to 24 mph over the posted limit.","p":"Right. The driver gets an advisory letter."},"es":{"q":"En Delaware, un conductor es condenado por ir 22 mph sobre el límite de velocidad. ¿Qué le envía el DMV?","o":["Un aviso de suspensión por un año","Una carta de advertencia","Una licencia nueva","Nada"],"h1":"A 25 mph de más empieza una suspensión. Esto es un poco menos.","h2":"En Delaware, el DMV envía una carta de advertencia al conductor condenado por ir de 20 a 24 mph sobre el límite marcado.","p":"Correcto. El conductor recibe una carta de advertencia."},"ref":{"doc":"DE","page":48}},{"id":"de-109","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, a driver is convicted of driving 100 mph on a highway. How long is the license suspended?","o":["1 week","1 month","3 months","1 year"],"h1":"This is the most serious speeding level.","h2":"In Delaware, driving 100 mph on a highway, or 50 mph or more over the limit, brings a one-year suspension.","p":"Right. The suspension is one year."},"es":{"q":"En Delaware, un conductor es condenado por manejar a 100 mph en una carretera. ¿Por cuánto tiempo se suspende la licencia?","o":["1 semana","1 mes","3 meses","1 año"],"h1":"Es el nivel más grave de exceso de velocidad.","h2":"En Delaware, manejar a 100 mph en una carretera, o a 50 mph o más sobre el límite, causa una suspensión de un año.","p":"Correcto. La suspensión es de un año."},"ref":{"doc":"DE","page":48}},{"id":"de-110","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what fine can a driver get for a first aggressive driving offense?","o":["$100 to $300","$10 to $25","$1,000 to $2,000","$5,000"],"h1":"It is a few hundred dollars.","h2":"In Delaware, a first aggressive driving offense carries a fine of $100 to $300, plus a required behavior course.","p":"Right. The fine is $100 to $300."},"es":{"q":"En Delaware, ¿qué multa puede recibir un conductor por una primera infracción de manejo agresivo?","o":["De $100 a $300","De $10 a $25","De $1,000 a $2,000","$5,000"],"h1":"Son unos cientos de dólares.","h2":"En Delaware, una primera infracción de manejo agresivo tiene una multa de $100 a $300, además de un curso de conducta obligatorio.","p":"Correcto. La multa es de $100 a $300."},"ref":{"doc":"DE","page":49}},{"id":"de-111","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, how long is an approved behavior modification (attitudinal driving) course, at minimum?","o":["1 hour","2 hours","8 hours","40 hours"],"h1":"It is about one full working day.","h2":"In Delaware, an approved behavior modification driving course lasts at least eight hours.","p":"Right. At least eight hours."},"es":{"q":"En Delaware, ¿cuánto dura como mínimo un curso aprobado de modificación de conducta para conductores?","o":["1 hora","2 horas","8 horas","40 horas"],"h1":"Es más o menos un día completo de trabajo.","h2":"En Delaware, un curso aprobado de modificación de conducta para conductores dura por lo menos ocho horas.","p":"Correcto. Por lo menos ocho horas."},"ref":{"doc":"DE","page":49}},{"id":"de-112","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, you finished an approved defensive driving course. For how long does it stay valid?","o":["6 months","3 years","10 years","For life"],"h1":"It is a few years.","h2":"In Delaware, an approved defensive driving course stays valid for three years from the day you finish it.","p":"Right. It is valid for three years."},"es":{"q":"En Delaware, usted terminó un curso aprobado de manejo defensivo. ¿Por cuánto tiempo es válido?","o":["6 meses","3 años","10 años","De por vida"],"h1":"Son unos pocos años.","h2":"En Delaware, un curso aprobado de manejo defensivo es válido por tres años desde el día en que lo termina.","p":"Correcto. Es válido por tres años."},"ref":{"doc":"DE","page":49}},{"id":"de-113","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, what is the shortest jail sentence the law sets for a second DUI offense?","o":["No jail time","1 day","1 week","60 days"],"h1":"It is about two months.","h2":"In Delaware, a second DUI offense carries jail time of at least 60 days and up to 18 months.","p":"Right. At least 60 days."},"es":{"q":"En Delaware, ¿cuál es la pena de cárcel más corta que fija la ley por una segunda infracción de DUI?","o":["Ninguna cárcel","1 día","1 semana","60 días"],"h1":"Son unos dos meses.","h2":"En Delaware, una segunda infracción de DUI tiene una pena de cárcel de por lo menos 60 días y hasta 18 meses.","p":"Correcto. Por lo menos 60 días."},"ref":{"doc":"DE","page":57}},{"id":"de-114","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, for how long does the DMV take away the license for a fourth DUI conviction?","o":["60 months","12 months","18 months","6 months"],"h1":"It is five years.","h2":"In Delaware, the DMV revokes the license for 60 months, which is five years, for any fourth DUI conviction.","p":"Right. It is 60 months."},"es":{"q":"En Delaware, ¿por cuánto tiempo quita el DMV la licencia por una cuarta condena de DUI?","o":["60 meses","12 meses","18 meses","6 meses"],"h1":"Son cinco años.","h2":"En Delaware, el DMV revoca la licencia por 60 meses, o sea cinco años, por cualquier cuarta condena de DUI.","p":"Correcto. Son 60 meses."},"ref":{"doc":"DE","page":57}},{"id":"de-115","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, a driver under 21 is caught driving after drinking for the second time. How long is the license revoked?","o":["2 months","2 weeks","6 to 12 months","It is not revoked"],"h1":"It is longer than the two months for a first offense.","h2":"In Delaware, under the zero tolerance law, each offense after the first brings a revocation of at least 6 and up to 12 months.","p":"Right. It is 6 to 12 months."},"es":{"q":"En Delaware, un conductor menor de 21 años es sorprendido manejando después de beber por segunda vez. ¿Por cuánto tiempo se revoca la licencia?","o":["2 meses","2 semanas","De 6 a 12 meses","No se revoca"],"h1":"Es más que los dos meses de la primera vez.","h2":"En Delaware, según la ley de tolerancia cero, cada infracción después de la primera causa una revocación de por lo menos 6 y hasta 12 meses.","p":"Correcto. Son de 6 a 12 meses."},"ref":{"doc":"DE","page":54}},{"id":"de-116","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, a first-time DUI offender chooses the First Offense Election with an ignition interlock license. For how long must the device stay on?","o":["2 weeks","4 months","5 years","For life"],"h1":"It is a few months.","h2":"In Delaware, a person in the First Offense Election program with an ignition interlock license must keep the device for four months from the date the license is issued.","p":"Right. Four months."},"es":{"q":"En Delaware, una persona con su primera infracción de DUI elige el programa de primer infractor (FOE) con licencia de bloqueo de encendido. ¿Por cuánto tiempo debe tener el aparato?","o":["2 semanas","4 meses","5 años","De por vida"],"h1":"Son unos pocos meses.","h2":"En Delaware, una persona en el programa FOE con licencia de bloqueo de encendido debe tener el aparato por cuatro meses desde la fecha en que se emite la licencia.","p":"Correcto. Cuatro meses."},"ref":{"doc":"DE","page":56}},{"id":"de-117","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you pay the DMV with a check that bounces. What happens?","o":["Nothing, the DMV covers the cost","Your car is towed away the same day","You must take the road test again","A $25 penalty; suspension if unpaid in 10 days"],"h1":"There is a small fee and a short deadline.","h2":"In Delaware, a bounced payment to the DMV brings a $25 penalty, and if you do not pay within 10 days, your license or registration is suspended.","p":"Right. $25, paid within 10 days."},"es":{"q":"En Delaware, usted paga al DMV con un cheque sin fondos. ¿Qué pasa?","o":["Nada, el DMV cubre el costo","Remolcan su carro ese mismo día","Debe repetir el examen de manejo","Un cargo de $25; suspensión si no paga en 10 días"],"h1":"Hay un cargo pequeño y un plazo corto.","h2":"En Delaware, un pago rechazado al DMV tiene un cargo de $25, y si usted no paga en 10 días, se suspende su licencia o su registro.","p":"Correcto. $25, pagados en 10 días."},"ref":{"doc":"DE","page":16}},{"id":"de-118","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, from how far away must your car horn be heard under normal conditions?","o":["At least 200 feet","At least 20 feet","At least 1 mile","At least 5,000 feet"],"h1":"It is about two-thirds of a football field.","h2":"In Delaware, a car horn must be loud enough to be heard at least 200 feet away under normal conditions.","p":"Right. At least 200 feet."},"es":{"q":"En Delaware, ¿desde qué distancia se debe oír la bocina de su carro en condiciones normales?","o":["Por lo menos 200 pies","Por lo menos 20 pies","Por lo menos 1 milla","Por lo menos 5,000 pies"],"h1":"Es más o menos dos tercios de una cancha de fútbol americano.","h2":"En Delaware, la bocina de un carro debe oírse por lo menos a 200 pies de distancia en condiciones normales.","p":"Correcto. Por lo menos 200 pies."},"ref":{"doc":"DE","page":61}},{"id":"de-119","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, you tow another vehicle with a bar or chain. What is the longest the connection may be?","o":["5 feet","30 feet","15 feet","50 feet"],"h1":"It is about the length of a car.","h2":"In Delaware, the bar or other connection between a towing vehicle and the vehicle it tows may be no more than 15 feet long.","p":"Right. No more than 15 feet."},"es":{"q":"En Delaware, usted remolca otro vehículo con una barra o una cadena. ¿Cuál es el largo máximo de la conexión?","o":["5 pies","30 pies","15 pies","50 pies"],"h1":"Es más o menos el largo de un carro.","h2":"En Delaware, la barra u otra conexión entre el vehículo que remolca y el vehículo remolcado no puede medir más de 15 pies.","p":"Correcto. No más de 15 pies."},"ref":{"doc":"DE","page":62}},{"id":"de-120","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, what is true about your insurance identification card?","o":["It is valid for life","It may be paper or electronic","It must stay at home","Only the DMV may keep it"],"h1":"Your phone may work for this.","h2":"In Delaware, the insurance ID card must be carried in the vehicle, is reissued every six months, and may be paper or electronic.","p":"Right. Paper or electronic is fine."},"es":{"q":"En Delaware, ¿qué es cierto sobre su tarjeta de identificación del seguro?","o":["Es válida de por vida","Puede ser de papel o electrónica","Debe quedarse en la casa","Solo el DMV la puede guardar"],"h1":"Su teléfono puede servir para esto.","h2":"En Delaware, la tarjeta del seguro se debe llevar en el vehículo, se renueva cada seis meses y puede ser de papel o electrónica.","p":"Correcto. Puede ser de papel o electrónica."},"ref":{"doc":"DE","page":63}},{"id":"de-121","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you live here and take your car to a DMV lane for its safety inspection. How much does the inspection cost?","o":["$20","$40","$75","Nothing"],"h1":"Residents get a break on this.","h2":"In Delaware, there is no charge for a vehicle inspection for Delaware residents.","p":"Right. The inspection is free for residents."},"es":{"q":"En Delaware, usted vive aquí y lleva su carro a una línea del DMV para la inspección de seguridad. ¿Cuánto cuesta la inspección?","o":["$20","$40","$75","Nada"],"h1":"Los residentes tienen una ventaja en esto.","h2":"En Delaware, la inspección del vehículo no tiene costo para los residentes de Delaware.","p":"Correcto. La inspección es gratis para los residentes."},"ref":{"doc":"DE","page":64}},{"id":"de-122","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, what is the least tire tread depth needed to pass the vehicle inspection?","o":["2/32 inch","1/64 inch","6/32 inch","1/2 inch"],"h1":"It is measured in thirty-seconds of an inch.","h2":"In Delaware, tires must have a tread depth of at least 2/32 inch, measured in two adjacent treads, to pass inspection.","p":"Right. At least 2/32 inch."},"es":{"q":"En Delaware, ¿cuál es la profundidad mínima del dibujo de las llantas para pasar la inspección del vehículo?","o":["2/32 de pulgada","1/64 de pulgada","6/32 de pulgada","1/2 pulgada"],"h1":"Se mide en treintaidosavos de pulgada.","h2":"En Delaware, las llantas deben tener un dibujo de por lo menos 2/32 de pulgada, medido en dos ranuras vecinas, para pasar la inspección.","p":"Correcto. Por lo menos 2/32 de pulgada."},"ref":{"doc":"DE","page":64}},{"id":"de-123","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, your windshield has a crack. At what length does it make the car fail inspection?","o":["Any crack at all","Over 1 foot","Over 5 inches","Over 2 feet"],"h1":"It is about the width of a hand.","h2":"In Delaware, a windshield crack over five inches long, or a star chip over one inch, is an automatic inspection failure.","p":"Right. A crack over five inches fails."},"es":{"q":"En Delaware, su parabrisas tiene una grieta. ¿Con qué largo hace que el carro no pase la inspección?","o":["Cualquier grieta","Más de 1 pie","Más de 5 pulgadas","Más de 2 pies"],"h1":"Es más o menos el ancho de una mano.","h2":"En Delaware, una grieta en el parabrisas de más de cinco pulgadas, o una estrella de más de una pulgada, hace que el carro no pase la inspección.","p":"Correcto. Una grieta de más de cinco pulgadas no pasa."},"ref":{"doc":"DE","page":65}},{"id":"de-124","scope":"DE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Delaware, how early may you have your car inspected before its registration expires?","o":["Only on the expiration day","Up to 90 days before","Up to 1 year before","Only after it expires"],"h1":"It is about three months.","h2":"In Delaware, you may have your vehicle inspected any time in the 90 days before the registration expires, and no time is lost by going early.","p":"Right. Up to 90 days early."},"es":{"q":"En Delaware, ¿con cuánta anticipación puede inspeccionar su carro antes de que venza el registro?","o":["Solo el día que vence","Hasta 90 días antes","Hasta 1 año antes","Solo después de que vence"],"h1":"Son unos tres meses.","h2":"En Delaware, usted puede inspeccionar su vehículo en cualquier momento durante los 90 días antes de que venza el registro, y no pierde tiempo por ir antes.","p":"Correcto. Hasta 90 días antes."},"ref":{"doc":"DE","page":67}},{"id":"de-125","scope":"DE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Delaware, you renew your vehicle registration after it has expired. What late fee is charged?","o":["No late fee","$5","$100","$20"],"h1":"It is twice the late fee for a driver license.","h2":"In Delaware, a $20 late fee is charged for renewing a vehicle registration after it expires, except for active duty military.","p":"Right. The late fee is $20."},"es":{"q":"En Delaware, usted renueva el registro de su vehículo después de que venció. ¿Qué cargo por atraso se cobra?","o":["Ningún cargo","$5","$100","$20"],"h1":"Es el doble del cargo por atraso de la licencia de conducir.","h2":"En Delaware, se cobra un cargo por atraso de $20 por renovar el registro de un vehículo después de que vence, menos para militares en servicio activo.","p":"Correcto. El cargo por atraso es de $20."},"ref":{"doc":"DE","page":67}},{"id":"de-126","scope":"DE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Delaware, what fine can a court give for a first conviction of passing a stopped school bus with red lights flashing?","o":["$115 to $230","$10 to $25","$1,000 to $5,000","$50 exactly"],"h1":"It starts a little above $100.","h2":"In Delaware, a first conviction for passing a stopped school bus brings a fine of $115 to $230, or 30 to 60 days in jail, or both.","p":"Right. The fine is $115 to $230."},"es":{"q":"En Delaware, ¿qué multa puede dar un tribunal por una primera condena por pasar un autobús escolar detenido con luces rojas intermitentes?","o":["De $115 a $230","De $10 a $25","De $1,000 a $5,000","Exactamente $50"],"h1":"Empieza un poco arriba de $100.","h2":"En Delaware, una primera condena por pasar un autobús escolar detenido tiene una multa de $115 a $230, o de 30 a 60 días de cárcel, o ambas.","p":"Correcto. La multa es de $115 a $230."},"ref":{"doc":"DE","page":90}},{"id":"de-127","scope":"DE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Delaware, a driver is convicted a second time within 3 years of passing a stopped school bus. How long is the license suspended?","o":["1 week","1 month","6 months","5 years"],"h1":"It is half a year.","h2":"In Delaware, a second school bus passing offense within three years brings a six-month license suspension.","p":"Right. Six months."},"es":{"q":"En Delaware, un conductor es condenado por segunda vez en 3 años por pasar un autobús escolar detenido. ¿Por cuánto tiempo se suspende la licencia?","o":["1 semana","1 mes","6 meses","5 años"],"h1":"Es medio año.","h2":"En Delaware, una segunda infracción por pasar un autobús escolar en tres años causa una suspensión de la licencia por seis meses.","p":"Correcto. Seis meses."},"ref":{"doc":"DE","page":90}},{"id":"de-128","scope":"DE","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Delaware, how fast should you go as you approach a roundabout?","o":["35 to 40 mph","10 to 15 mph","The highway speed limit","25 to 30 mph"],"h1":"Roundabouts are made for slow speeds.","h2":"In Delaware, as you approach a roundabout you stay to the right of the splitter island and slow down to 10 to 15 mph.","p":"Right. Slow to 10 to 15 mph."},"es":{"q":"En Delaware, ¿a qué velocidad debe ir al acercarse a una glorieta?","o":["De 35 a 40 mph","De 10 a 15 mph","Al límite de la autopista","De 25 a 30 mph"],"h1":"Las glorietas están hechas para ir despacio.","h2":"En Delaware, al acercarse a una glorieta usted se mantiene a la derecha de la isla divisoria y baja la velocidad a 10 a 15 mph.","p":"Correcto. Baje a 10 a 15 mph."},"ref":{"doc":"DE","page":86}},{"id":"de-129","scope":"DE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Delaware, what must a person walking along a road at night carry?","o":["A whistle","A cell phone","An umbrella","A light or a reflector"],"h1":"Drivers need to be able to see them.","h2":"In Delaware, it is illegal to walk along a road at night without carrying a light or a reflector.","p":"Right. A light or a reflector."},"es":{"q":"En Delaware, ¿qué debe llevar una persona que camina por una carretera de noche?","o":["Un silbato","Un teléfono celular","Un paraguas","Una luz o un reflector"],"h1":"Los conductores necesitan poder verla.","h2":"En Delaware, es ilegal caminar por una carretera de noche sin llevar una luz o un reflector.","p":"Correcto. Una luz o un reflector."},"ref":{"doc":"DE","page":95}},{"id":"de-130","scope":"DE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Delaware, a bicyclist rides at night. From how far away must the white headlight be visible?","o":["500 feet","50 feet","100 feet","1 mile"],"h1":"It is a little more than one and a half football fields.","h2":"In Delaware, a bicycle ridden at night needs a white headlight visible for 500 feet and a red rear reflector visible for 600 feet.","p":"Right. 500 feet."},"es":{"q":"En Delaware, un ciclista anda de noche. ¿Desde qué distancia se debe ver la luz blanca delantera?","o":["500 pies","50 pies","100 pies","1 milla"],"h1":"Es un poco más que una cancha y media de fútbol americano.","h2":"En Delaware, una bicicleta de noche necesita una luz blanca delantera visible a 500 pies y un reflector rojo trasero visible a 600 pies.","p":"Correcto. 500 pies."},"ref":{"doc":"DE","page":98}},{"id":"de-131","scope":"DE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Delaware, besides permit holders and newly endorsed riders, which motorcycle riders must always wear a helmet?","o":["Only riders on interstates","Riders over 65","Riders under 19","Only riders at night"],"h1":"It depends on the rider's age, and it is about young riders.","h2":"In Delaware, motorcycle riders under 19 must wear a helmet and eye protection; older riders must still carry them.","p":"Right. Riders under 19 must wear a helmet."},"es":{"q":"En Delaware, además de quienes tienen permiso de aprendiz y los recién autorizados, ¿qué motociclistas siempre deben usar casco?","o":["Solo los que van en autopistas interestatales","Los mayores de 65 años","Los menores de 19 años","Solo los que andan de noche"],"h1":"Depende de la edad, y se trata de los jóvenes.","h2":"En Delaware, los motociclistas menores de 19 años deben usar casco y protección para los ojos; los mayores deben llevarlos consigo.","p":"Correcto. Los menores de 19 deben usar casco."},"ref":{"doc":"DE","page":101}},{"id":"ga-001","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to get a learner's permit (Class CP)?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It comes one year before you can take the road test for a Class D license.","h2":"In Georgia you can get a Class CP learner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The Georgia learner's permit starts at 15."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para obtener el permiso de aprendiz (Clase CP)?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder hacer el examen de manejo para la licencia Clase D.","h2":"En Georgia usted puede obtener el permiso de aprendiz Clase CP a los 15 años, después de aprobar los exámenes de la vista y de conocimientos.","p":"Correcto. El permiso de aprendiz en Georgia empieza a los 15."},"zh":{"q":"在 Georgia，最小几岁可以拿到学习驾照（Class CP）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比你可以参加 Class D 驾照路考的年龄早一年。","h2":"在 Georgia，你通过视力和笔试以后，15 岁就可以拿到 Class CP 学习驾照。","p":"对。Georgia 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Georgia, tuổi nhỏ nhất để được cấp giấy phép tập lái (learner's permit, Class CP) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Nó sớm hơn một năm so với tuổi được thi lái xe trên đường để lấy bằng Class D.","h2":"Ở Georgia, bạn có thể lấy giấy phép tập lái Class CP lúc 15 tuổi, sau khi đậu bài kiểm tra mắt và bài thi kiến thức.","p":"Đúng. Ở Georgia, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Georgia, ano ang pinakabatang edad para makakuha ng learner's permit (Class CP)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka puwedeng kumuha ng road test para sa Class D license.","h2":"Sa Georgia, puwede kang kumuha ng Class CP learner's permit sa edad na 15, pagkatapos mong pumasa sa vision test at knowledge test.","p":"Tama. Sa Georgia, nagsisimula ang learner's permit sa edad na 15."},"ar":{"q":"في Georgia، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit, Class CP)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"يأتي قبل سنة واحدة من العمر الذي يمكنك فيه أداء اختبار القيادة على الطريق لرخصة Class D.","h2":"في Georgia يمكنك الحصول على تصريح تعلّم القيادة Class CP في عمر 15 سنة، بعد أن تنجح في اختبار النظر واختبار المعرفة.","p":"صحيح. في Georgia يبدأ تصريح التعلّم من عمر 15 سنة."},"ref":{"doc":"GA","page":8}},{"id":"ga-002","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how old must the licensed person beside a learner's permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"A Georgia permit driver must have a licensed person who is at least 21 years old in the car.","p":"Right. The person with you must be 21 or older."},"es":{"q":"En Georgia, ¿qué edad debe tener la persona con licencia que acompaña a un conductor con permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para comprar alcohol legalmente.","h2":"Un conductor con permiso en Georgia debe llevar en el carro a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Georgia，坐在持学习驾照司机旁边、有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法买酒的年龄。","h2":"Georgia 持学习驾照的司机，车里必须有一位至少 21 岁、有驾照的人。","p":"对。陪你的人必须 21 岁或以上。"},"vi":{"q":"Ở Georgia, người có bằng lái ngồi cạnh người lái có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người đi kèm phải đủ tuổi để mua rượu hợp pháp.","h2":"Người lái có giấy phép tập lái ở Georgia phải có một người có bằng lái, ít nhất 21 tuổi, ngồi trong xe.","p":"Đúng. Người đi cùng bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Georgia, ilang taon dapat ang may lisensyang tao na katabi ng nagmamaneho na may learner's permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng kasama para legal na makabili ng alak.","h2":"Ang nagmamaneho na may permit sa Georgia ay dapat may kasamang may lisensya na hindi bababa sa 21 taong gulang sa loob ng kotse.","p":"Tama. Ang kasama mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Georgia، كم يجب أن يكون عمر الشخص الذي يحمل رخصة ويجلس بجانب سائق لديه تصريح تعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق كبيرًا بما يكفي لشراء الكحول بشكل قانوني.","h2":"يجب أن يكون مع سائق تصريح التعلّم في Georgia شخص يحمل رخصة ولا يقل عمره عن 21 سنة داخل السيارة.","p":"صحيح. يجب أن يكون الشخص الذي معك عمره 21 سنة أو أكثر."},"ref":{"doc":"GA","page":8}},{"id":"ga-003","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, where must the supervising adult sit when a learner's permit holder drives?","o":["In the seat next to the driver","In the back seat","Anywhere in the car","In a car following behind"],"h1":"The adult must be close enough to take control of the car.","h2":"In Georgia the supervising adult must sit in the seat next to the driver, ready to take control if needed.","p":"Right. The adult sits next to you."},"es":{"q":"En Georgia, ¿dónde debe sentarse el adulto que supervisa a un conductor con permiso de aprendiz?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El adulto debe estar lo bastante cerca para tomar el control del carro.","h2":"En Georgia el adulto que supervisa debe sentarse en el asiento al lado del conductor, listo para tomar el control si hace falta.","p":"Correcto. El adulto va sentado a su lado."},"zh":{"q":"在 Georgia，持学习驾照的人开车时，监督的成年人必须坐在哪里？","o":["司机旁边的座位","后排座位","车里任何地方","跟在后面的另一辆车里"],"h1":"这个成年人必须离得够近，可以控制这辆车。","h2":"在 Georgia，监督的成年人必须坐在司机旁边的座位，需要时随时可以控制车辆。","p":"对。成年人坐在你旁边。"},"vi":{"q":"Ở Georgia, khi người có giấy phép tập lái đang lái xe, người lớn giám sát phải ngồi ở đâu?","o":["Ở ghế ngồi cạnh người lái","Ở ghế sau","Bất kỳ chỗ nào trong xe","Trong một xe khác chạy phía sau"],"h1":"Người lớn phải ngồi đủ gần để điều khiển xe khi cần.","h2":"Ở Georgia, người lớn giám sát phải ngồi ở ghế cạnh người lái, sẵn sàng điều khiển xe nếu cần.","p":"Đúng. Người lớn ngồi cạnh bạn."},"tl":{"q":"Sa Georgia, saan dapat umupo ang nagbabantay na adult kapag nagmamaneho ang may learner's permit?","o":["Sa upuang katabi ng driver","Sa likod na upuan","Kahit saan sa kotse","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang adult para makontrol ang kotse.","h2":"Sa Georgia, ang nagbabantay na adult ay dapat umupo sa upuang katabi ng driver, handang kontrolin ang kotse kung kailangan.","p":"Tama. Ang adult ay nakaupo sa tabi mo."},"ar":{"q":"في Georgia، أين يجب أن يجلس الشخص البالغ المشرف عندما يقود صاحب تصريح التعلّم؟","o":["في المقعد الذي بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون البالغ قريبًا بما يكفي ليتحكم في السيارة.","h2":"في Georgia يجب أن يجلس البالغ المشرف في المقعد الذي بجانب السائق، مستعدًا للتحكم في السيارة عند الحاجة.","p":"صحيح. البالغ يجلس بجانبك."},"ref":{"doc":"GA","page":8}},{"id":"ga-004","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how long must a teen hold the learner's permit before taking the road test for a Class D license?","o":["3 months","6 months","One year and one day","Two years"],"h1":"It is a little more than one full year.","h2":"A Georgia teen must hold the learner's permit for one year and one day before taking the Class D road test.","p":"Right. One year and one day."},"es":{"q":"En Georgia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del examen de manejo para la licencia Clase D?","o":["3 meses","6 meses","Un año y un día","Dos años"],"h1":"Es un poco más de un año completo.","h2":"Un adolescente en Georgia debe tener el permiso de aprendiz durante un año y un día antes del examen de manejo para la licencia Clase D.","p":"Correcto. Un año y un día."},"zh":{"q":"在 Georgia，青少年必须持有学习驾照多久，才能参加 Class D 驾照路考？","o":["3 个月","6 个月","一年零一天","两年"],"h1":"它比整整一年多一点。","h2":"Georgia 的青少年必须持有学习驾照一年零一天，才能参加 Class D 路考。","p":"对。一年零一天。"},"vi":{"q":"Ở Georgia, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái xe trên đường để lấy bằng Class D?","o":["3 tháng","6 tháng","Một năm và một ngày","Hai năm"],"h1":"Nó dài hơn một năm tròn một chút.","h2":"Thanh thiếu niên ở Georgia phải giữ giấy phép tập lái một năm và một ngày trước khi thi lái xe trên đường để lấy bằng Class D.","p":"Đúng. Một năm và một ngày."},"tl":{"q":"Sa Georgia, gaano katagal dapat hawak ng teen ang learner's permit bago kumuha ng road test para sa Class D license?","o":["3 buwan","6 na buwan","Isang taon at isang araw","Dalawang taon"],"h1":"Medyo mahigit ito sa isang buong taon.","h2":"Ang teen sa Georgia ay dapat may hawak na learner's permit nang isang taon at isang araw bago kumuha ng road test para sa Class D.","p":"Tama. Isang taon at isang araw."},"ar":{"q":"في Georgia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل أداء اختبار القيادة على الطريق لرخصة Class D؟","o":["3 أشهر","6 أشهر","سنة واحدة ويوم واحد","سنتان"],"h1":"المدة أكثر قليلًا من سنة كاملة.","h2":"يجب على المراهق في Georgia أن يحمل تصريح التعلّم سنة واحدة ويومًا واحدًا قبل أداء اختبار القيادة على الطريق لرخصة Class D.","p":"صحيح. سنة واحدة ويوم واحد."},"ref":{"doc":"GA","page":8}},{"id":"ga-005","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, what is the youngest age to take the road test for a Class D license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It is one year after the youngest age for a learner's permit.","h2":"In Georgia you can take the road test for a Class D license once you turn 16 and have held your permit long enough.","p":"Right. The Class D road test starts at 16."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para hacer el examen de manejo para la licencia Clase D?","o":["15 años","16 años","17 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Georgia usted puede hacer el examen de manejo para la licencia Clase D cuando cumple 16 años y ha tenido el permiso el tiempo necesario.","p":"Correcto. El examen para la Clase D empieza a los 16."},"zh":{"q":"在 Georgia，最小几岁可以参加 Class D 驾照路考？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它比拿学习驾照的最小年龄晚一年。","h2":"在 Georgia，你满 16 岁、而且持有学习驾照够久以后，就可以参加 Class D 驾照路考。","p":"对。Class D 路考从 16 岁开始。"},"vi":{"q":"Ở Georgia, tuổi nhỏ nhất để thi lái xe trên đường lấy bằng Class D là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Nó là một năm sau tuổi nhỏ nhất để lấy giấy phép tập lái.","h2":"Ở Georgia, bạn có thể thi lái xe trên đường để lấy bằng Class D khi bạn đủ 16 tuổi và đã giữ giấy phép tập lái đủ lâu.","p":"Đúng. Thi lái xe Class D bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Georgia, ano ang pinakabatang edad para kumuha ng road test para sa Class D license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa learner's permit.","h2":"Sa Georgia, puwede kang kumuha ng road test para sa Class D license kapag 16 ka na at sapat na ang tagal ng paghawak mo ng permit.","p":"Tama. Ang road test para sa Class D ay nagsisimula sa 16."},"ar":{"q":"في Georgia، ما أصغر عمر لأداء اختبار القيادة على الطريق لرخصة Class D؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"يأتي بعد سنة واحدة من أصغر عمر لتصريح التعلّم.","h2":"في Georgia يمكنك أداء اختبار القيادة على الطريق لرخصة Class D عندما يصبح عمرك 16 سنة وتكون قد حملت التصريح مدة كافية.","p":"صحيح. اختبار القيادة لرخصة Class D يبدأ من عمر 16 سنة."},"ref":{"doc":"GA","page":8}},{"id":"ga-006","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how many hours of supervised driving must a 16- or 17-year-old complete for a Class D license?","o":["20 hours","30 hours","40 hours","65 hours"],"h1":"It is more than 30 and less than 50.","h2":"Under Joshua's Law, a Georgia teen needs at least 40 hours of supervised driving before getting a Class D license.","p":"Right. Georgia asks for 40 hours of supervised driving."},"es":{"q":"En Georgia, ¿cuántas horas de manejo supervisado debe completar un joven de 16 o 17 años para la licencia Clase D?","o":["20 horas","30 horas","40 horas","65 horas"],"h1":"Son más de 30 y menos de 50.","h2":"Según la Ley de Joshua, un adolescente en Georgia necesita por lo menos 40 horas de manejo supervisado antes de obtener la licencia Clase D.","p":"Correcto. Georgia pide 40 horas de manejo supervisado."},"zh":{"q":"在 Georgia，16 岁或 17 岁的人拿 Class D 驾照，必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","40 小时","65 小时"],"h1":"它比 30 多，比 50 少。","h2":"根据 Joshua's Law，Georgia 的青少年拿 Class D 驾照前，至少需要 40 小时有人监督的驾驶。","p":"对。Georgia 要求 40 小时有人监督的驾驶。"},"vi":{"q":"Ở Georgia, người 16 hoặc 17 tuổi phải lái xe có người giám sát bao nhiêu giờ để lấy bằng Class D?","o":["20 giờ","30 giờ","40 giờ","65 giờ"],"h1":"Nó nhiều hơn 30 và ít hơn 50.","h2":"Theo Luật Joshua (Joshua's Law), thanh thiếu niên ở Georgia cần ít nhất 40 giờ lái xe có người giám sát trước khi lấy bằng Class D.","p":"Đúng. Georgia yêu cầu 40 giờ lái xe có người giám sát."},"tl":{"q":"Sa Georgia, ilang oras ng pagmamaneho na may nagbabantay ang dapat tapusin ng 16 o 17 taong gulang para sa Class D license?","o":["20 oras","30 oras","40 oras","65 oras"],"h1":"Higit ito sa 30 at kulang sa 50.","h2":"Ayon sa Joshua's Law, ang teen sa Georgia ay kailangan ng hindi bababa sa 40 oras ng pagmamaneho na may nagbabantay bago makakuha ng Class D license.","p":"Tama. Humihingi ang Georgia ng 40 oras ng pagmamaneho na may nagbabantay."},"ar":{"q":"في Georgia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها من عمره 16 أو 17 سنة للحصول على رخصة Class D؟","o":["20 ساعة","30 ساعة","40 ساعة","65 ساعة"],"h1":"العدد أكثر من 30 وأقل من 50.","h2":"حسب قانون جوشوا (Joshua's Law)، يحتاج المراهق في Georgia إلى 40 ساعة على الأقل من القيادة تحت الإشراف قبل الحصول على رخصة Class D.","p":"صحيح. تطلب Georgia 40 ساعة من القيادة تحت الإشراف."},"ref":{"doc":"GA","page":8}},{"id":"ga-007","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many of the required supervised driving hours must be at night?","o":["6 hours","2 hours","10 hours","20 hours"],"h1":"It is a small part of the total, less than 10.","h2":"Of the 40 supervised hours a Georgia teen needs, at least 6 hours must be driven at night.","p":"Right. At least 6 of the hours are at night."},"es":{"q":"En Georgia, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["6 horas","2 horas","10 horas","20 horas"],"h1":"Es una parte pequeña del total, menos de 10.","h2":"De las 40 horas supervisadas que necesita un adolescente en Georgia, por lo menos 6 horas deben ser de noche.","p":"Correcto. Por lo menos 6 horas son de noche."},"zh":{"q":"在 Georgia，规定的有人监督驾驶时间里，有多少小时必须在晚上？","o":["6 小时","2 小时","10 小时","20 小时"],"h1":"它是全部时间的一小部分，少于 10。","h2":"在 Georgia 青少年需要的 40 小时有人监督的驾驶里，至少 6 小时必须在晚上开。","p":"对。至少 6 小时在晚上。"},"vi":{"q":"Ở Georgia, trong số giờ lái xe có người giám sát bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["6 giờ","2 giờ","10 giờ","20 giờ"],"h1":"Nó là một phần nhỏ của tổng số, ít hơn 10.","h2":"Trong 40 giờ lái xe có người giám sát mà thanh thiếu niên ở Georgia cần, ít nhất 6 giờ phải lái vào ban đêm.","p":"Đúng. Ít nhất 6 giờ là vào ban đêm."},"tl":{"q":"Sa Georgia, ilan sa mga kailangang oras ng pagmamaneho na may nagbabantay ang dapat sa gabi?","o":["6 na oras","2 oras","10 oras","20 oras"],"h1":"Maliit na bahagi ito ng kabuuan, kulang sa 10.","h2":"Sa 40 oras na may nagbabantay na kailangan ng teen sa Georgia, hindi bababa sa 6 na oras ang dapat sa gabi.","p":"Tama. Hindi bababa sa 6 na oras ang sa gabi."},"ar":{"q":"في Georgia، كم ساعة من ساعات القيادة تحت الإشراف المطلوبة يجب أن تكون في الليل؟","o":["6 ساعات","ساعتان (2)","10 ساعات","20 ساعة"],"h1":"هي جزء صغير من المجموع، أقل من 10.","h2":"من بين الـ 40 ساعة تحت الإشراف التي يحتاجها المراهق في Georgia، يجب أن تكون 6 ساعات على الأقل في الليل.","p":"صحيح. 6 ساعات على الأقل تكون في الليل."},"ref":{"doc":"GA","page":8}},{"id":"ga-008","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how long is the approved driver education course (classroom or online) that Joshua's Law requires?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is the largest number in the list.","h2":"Joshua's Law requires Georgia teens to complete a 30-hour approved driver education course, in a classroom or online.","p":"Right. The course is 30 hours."},"es":{"q":"En Georgia, ¿cuántas horas dura el curso aprobado de educación vial (en clase o en línea) que exige la Ley de Joshua?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el número más grande de la lista.","h2":"La Ley de Joshua exige que los adolescentes en Georgia completen un curso aprobado de educación vial de 30 horas, en clase o en línea.","p":"Correcto. El curso es de 30 horas."},"zh":{"q":"在 Georgia，Joshua's Law 要求的认可驾驶教育课程（课堂或网上）有多长？","o":["5 小时","10 小时","20 小时","30 小时"],"h1":"它是选项里最大的数字。","h2":"Joshua's Law 要求 Georgia 的青少年完成 30 小时认可的驾驶教育课程，在课堂或网上都可以。","p":"对。课程是 30 小时。"},"vi":{"q":"Ở Georgia, khóa học lái xe được chấp thuận (học trên lớp hoặc trực tuyến) mà Luật Joshua yêu cầu dài bao lâu?","o":["5 giờ","10 giờ","20 giờ","30 giờ"],"h1":"Nó là số lớn nhất trong danh sách.","h2":"Luật Joshua (Joshua's Law) yêu cầu thanh thiếu niên ở Georgia học xong một khóa học lái xe được chấp thuận dài 30 giờ, trên lớp hoặc trực tuyến.","p":"Đúng. Khóa học dài 30 giờ."},"tl":{"q":"Sa Georgia, gaano kahaba ang aprubadong driver education course (sa klase o online) na hinihingi ng Joshua's Law?","o":["5 oras","10 oras","20 oras","30 oras"],"h1":"Ito ang pinakamalaking numero sa listahan.","h2":"Hinihingi ng Joshua's Law na tapusin ng mga teen sa Georgia ang 30 oras na aprubadong driver education course, sa klase o online.","p":"Tama. 30 oras ang course."},"ar":{"q":"في Georgia، كم طول دورة تعليم القيادة المعتمدة (في الصف أو عبر الإنترنت) التي يطلبها قانون جوشوا؟","o":["5 ساعات","10 ساعات","20 ساعة","30 ساعة"],"h1":"هو أكبر رقم في القائمة.","h2":"يطلب قانون جوشوا (Joshua's Law) من المراهقين في Georgia إكمال دورة معتمدة لتعليم القيادة مدتها 30 ساعة، في الصف أو عبر الإنترنت.","p":"صحيح. الدورة مدتها 30 ساعة."},"ref":{"doc":"GA","page":8}},{"id":"ga-009","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, besides the driver education course, what behind-the-wheel training does Joshua's Law accept?","o":["1 hour with any adult","6 hours with a certified instructor, or the DDS parent-teen driving guide","A video course only","No behind-the-wheel training is needed"],"h1":"There are two ways to do it: one with a professional, one with a parent.","h2":"Joshua's Law accepts 6 hours of driving with a certified instructor, or completing the DDS parent-teen driving guide.","p":"Right. Six hours with an instructor, or the parent-teen guide."},"es":{"q":"En Georgia, además del curso de educación vial, ¿qué práctica al volante acepta la Ley de Joshua?","o":["1 hora con cualquier adulto","6 horas con un instructor certificado, o la guía de manejo para padres e hijos del DDS","Solo un curso en video","No hace falta práctica al volante"],"h1":"Hay dos maneras: una con un profesional y otra con un padre o madre.","h2":"La Ley de Joshua acepta 6 horas de manejo con un instructor certificado, o completar la guía de manejo para padres e hijos del DDS.","p":"Correcto. Seis horas con instructor, o la guía para padres e hijos."},"zh":{"q":"在 Georgia，除了驾驶教育课程，Joshua's Law 接受哪一种实际上车驾驶训练？","o":["和任何成年人开 1 小时","和有证书的教练开 6 小时，或完成 DDS 的家长与青少年驾驶指南","只有视频课程","不需要实际上车训练"],"h1":"有两种方法：一种和专业人员，一种和父母。","h2":"Joshua's Law 接受和有证书的教练开车 6 小时，或完成 DDS 的家长与青少年驾驶指南（parent-teen driving guide）。","p":"对。和教练开六小时，或完成家长与青少年指南。"},"vi":{"q":"Ở Georgia, ngoài khóa học lái xe, Luật Joshua chấp nhận cách tập lái thực tế nào?","o":["1 giờ với bất kỳ người lớn nào","6 giờ với huấn luyện viên có chứng chỉ, hoặc sách hướng dẫn lái xe cho cha mẹ và con của DDS","Chỉ một khóa học bằng video","Không cần tập lái thực tế"],"h1":"Có hai cách: một cách với người chuyên nghiệp, một cách với cha hoặc mẹ.","h2":"Luật Joshua chấp nhận 6 giờ lái xe với huấn luyện viên có chứng chỉ, hoặc hoàn thành sách hướng dẫn lái xe cho cha mẹ và con của DDS (parent-teen driving guide).","p":"Đúng. Sáu giờ với huấn luyện viên, hoặc sách hướng dẫn cho cha mẹ và con."},"tl":{"q":"Sa Georgia, bukod sa driver education course, anong behind-the-wheel training ang tinatanggap ng Joshua's Law?","o":["1 oras kasama ang kahit sinong adult","6 na oras kasama ang certified instructor, o ang DDS parent-teen driving guide","Video course lang","Hindi kailangan ng behind-the-wheel training"],"h1":"May dalawang paraan: isa kasama ang propesyonal, isa kasama ang magulang.","h2":"Tinatanggap ng Joshua's Law ang 6 na oras ng pagmamaneho kasama ang certified instructor, o ang pagtapos ng DDS parent-teen driving guide.","p":"Tama. Anim na oras kasama ang instructor, o ang parent-teen guide."},"ar":{"q":"في Georgia، إلى جانب دورة تعليم القيادة، ما التدريب العملي خلف المقود الذي يقبله قانون جوشوا؟","o":["ساعة واحدة مع أي شخص بالغ","6 ساعات مع مدرب معتمد، أو دليل القيادة للوالدين والمراهق من DDS","دورة فيديو فقط","لا حاجة إلى تدريب عملي"],"h1":"هناك طريقتان: واحدة مع شخص محترف، وواحدة مع أحد الوالدين.","h2":"يقبل قانون جوشوا 6 ساعات من القيادة مع مدرب معتمد، أو إكمال دليل القيادة للوالدين والمراهق من DDS (parent-teen driving guide).","p":"صحيح. ست ساعات مع مدرب، أو دليل الوالدين والمراهق."},"ref":{"doc":"GA","page":8}},{"id":"ga-010","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how does a teen show that the 40 hours of supervised driving were completed?","o":["The teen sends photos of the drives","A police officer rides along","A parent or guardian confirms it in writing at DDS","Nothing is needed"],"h1":"An adult who knows the teen gives their word in writing.","h2":"In Georgia no driving log is needed: a parent or guardian confirms in writing at DDS that the teen drove the 40 hours, including 6 at night.","p":"Right. A parent or guardian confirms the hours in writing."},"es":{"q":"En Georgia, ¿cómo demuestra un adolescente que completó las 40 horas de manejo supervisado?","o":["El adolescente envía fotos de los viajes","Un policía lo acompaña","Un padre o tutor lo confirma por escrito en el DDS","No hace falta nada"],"h1":"Un adulto que conoce al adolescente lo confirma por escrito.","h2":"En Georgia no se necesita un registro de manejo: un padre o tutor confirma por escrito en el DDS que el adolescente manejó las 40 horas, incluidas 6 de noche.","p":"Correcto. Un padre o tutor confirma las horas por escrito."},"zh":{"q":"在 Georgia，青少年怎样证明完成了 40 小时有人监督的驾驶？","o":["青少年寄开车的照片","警察同车","父母或监护人在 DDS 用书面方式确认","什么都不需要"],"h1":"一位了解这个青少年的成年人用书面方式保证。","h2":"在 Georgia 不需要驾驶记录本：父母或监护人在 DDS 用书面方式确认青少年开了 40 小时，其中 6 小时在晚上。","p":"对。父母或监护人用书面方式确认驾驶时间。"},"vi":{"q":"Ở Georgia, thanh thiếu niên chứng minh đã lái đủ 40 giờ có người giám sát bằng cách nào?","o":["Thanh thiếu niên gửi ảnh các lần lái xe","Một cảnh sát đi cùng xe","Cha mẹ hoặc người giám hộ xác nhận bằng văn bản tại DDS","Không cần gì cả"],"h1":"Một người lớn biết rõ thanh thiếu niên đó cam kết bằng văn bản.","h2":"Ở Georgia không cần sổ ghi chép lái xe: cha mẹ hoặc người giám hộ xác nhận bằng văn bản tại DDS rằng thanh thiếu niên đã lái 40 giờ, gồm 6 giờ ban đêm.","p":"Đúng. Cha mẹ hoặc người giám hộ xác nhận số giờ bằng văn bản."},"tl":{"q":"Sa Georgia, paano ipinapakita ng teen na natapos ang 40 oras ng pagmamaneho na may nagbabantay?","o":["Nagpapadala ang teen ng mga litrato ng pagmamaneho","Sumasakay ang isang pulis","Kinukumpirma ito nang nakasulat ng magulang o guardian sa DDS","Walang kailangan"],"h1":"Isang adult na kilala ang teen ang nagbibigay ng nakasulat na pangako.","h2":"Sa Georgia, hindi kailangan ng driving log: kinukumpirma nang nakasulat ng magulang o guardian sa DDS na nakapagmaneho ang teen ng 40 oras, kasama ang 6 sa gabi.","p":"Tama. Kinukumpirma ng magulang o guardian ang mga oras nang nakasulat."},"ar":{"q":"في Georgia، كيف يُثبت المراهق أنه أكمل الـ 40 ساعة من القيادة تحت الإشراف؟","o":["يرسل المراهق صورًا للرحلات","يركب معه شرطي","يؤكد أحد الوالدين أو الوصي ذلك كتابةً في DDS","لا يلزم شيء"],"h1":"شخص بالغ يعرف المراهق يتعهّد بذلك كتابةً.","h2":"في Georgia لا يلزم سجل للقيادة: يؤكد أحد الوالدين أو الوصي كتابةً في DDS أن المراهق قاد 40 ساعة، منها 6 ساعات في الليل.","p":"صحيح. أحد الوالدين أو الوصي يؤكد الساعات كتابةً."},"ref":{"doc":"GA","page":8}},{"id":"ga-011","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, what license must the adult who supervises practice driving hold?","o":["A valid license to drive a regular car (Class C)","A learner's permit","Any license from any country, even expired","No license is needed"],"h1":"It is the full adult license, and it must not be expired.","h2":"In Georgia the adult who supervises practice driving must be at least 21 and hold a valid license to drive a Class C vehicle, a regular car.","p":"Right. The supervisor needs a valid Class C license."},"es":{"q":"En Georgia, ¿qué licencia debe tener el adulto que supervisa la práctica de manejo?","o":["Una licencia vigente para manejar un carro normal (Clase C)","Un permiso de aprendiz","Cualquier licencia de cualquier país, aunque esté vencida","No necesita licencia"],"h1":"Es la licencia completa de adulto, y no puede estar vencida.","h2":"En Georgia el adulto que supervisa la práctica debe tener por lo menos 21 años y una licencia vigente para manejar un vehículo Clase C, un carro normal.","p":"Correcto. El supervisor necesita una licencia Clase C vigente."},"zh":{"q":"在 Georgia，监督练习开车的成年人必须持有什么驾照？","o":["可以开普通小汽车的有效驾照（Class C）","学习驾照","任何国家的任何驾照，过期的也可以","不需要驾照"],"h1":"它是成年人的正式驾照，而且不能过期。","h2":"在 Georgia，监督练习开车的成年人必须至少 21 岁，并持有可以开 Class C 车辆（普通小汽车）的有效驾照。","p":"对。监督的人需要有效的 Class C 驾照。"},"vi":{"q":"Ở Georgia, người lớn giám sát việc tập lái phải có bằng lái gì?","o":["Bằng lái còn hạn để lái xe hơi thường (Class C)","Một giấy phép tập lái","Bất kỳ bằng lái nào của nước nào, kể cả hết hạn","Không cần bằng lái"],"h1":"Đó là bằng lái đầy đủ của người lớn, và không được hết hạn.","h2":"Ở Georgia, người lớn giám sát việc tập lái phải ít nhất 21 tuổi và có bằng lái còn hạn để lái xe Class C, tức là xe hơi thường.","p":"Đúng. Người giám sát cần bằng lái Class C còn hạn."},"tl":{"q":"Sa Georgia, anong lisensya ang dapat hawak ng adult na nagbabantay sa praktis na pagmamaneho?","o":["Valid na lisensya para magmaneho ng karaniwang kotse (Class C)","Learner's permit","Kahit anong lisensya mula sa kahit anong bansa, kahit expired","Hindi kailangan ng lisensya"],"h1":"Ito ang buong lisensya ng adult, at hindi ito dapat expired.","h2":"Sa Georgia, ang adult na nagbabantay sa praktis na pagmamaneho ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya para magmaneho ng Class C na sasakyan, isang karaniwang kotse.","p":"Tama. Kailangan ng nagbabantay ang valid na Class C license."},"ar":{"q":"في Georgia، ما الرخصة التي يجب أن يحملها البالغ الذي يشرف على التدريب على القيادة؟","o":["رخصة سارية لقيادة سيارة عادية (Class C)","تصريح تعلّم القيادة","أي رخصة من أي بلد، حتى لو كانت منتهية","لا حاجة إلى رخصة"],"h1":"هي رخصة البالغين الكاملة، ويجب ألا تكون منتهية.","h2":"في Georgia يجب أن يكون البالغ الذي يشرف على التدريب على القيادة عمره 21 سنة على الأقل ويحمل رخصة سارية لقيادة مركبة Class C، أي سيارة عادية.","p":"صحيح. المشرف يحتاج إلى رخصة Class C سارية."},"ref":{"doc":"GA","page":8}},{"id":"ga-012","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, during the first six months with a Class D license, who may ride with the teen driver?","o":["Up to three friends","One friend under 21","Anyone, with no limit","Only immediate family members"],"h1":"At the start, the rule is the strictest it will ever be.","h2":"During the first six months with a Georgia Class D license, the only passengers allowed are immediate family members.","p":"Right. Only immediate family at first."},"es":{"q":"En Georgia, durante los primeros seis meses con licencia Clase D, ¿quién puede ir con el conductor adolescente?","o":["Hasta tres amigos","Un amigo menor de 21 años","Cualquier persona, sin límite","Solo familiares inmediatos"],"h1":"Al principio, la regla es la más estricta de todas.","h2":"Durante los primeros seis meses con licencia Clase D en Georgia, solo pueden ir como pasajeros los familiares inmediatos.","p":"Correcto. Al principio, solo familiares inmediatos."},"zh":{"q":"在 Georgia，拿到 Class D 驾照的前六个月，谁可以坐青少年司机的车？","o":["最多三位朋友","一位 21 岁以下的朋友","任何人，没有限制","只有直系家人"],"h1":"一开始的规定是最严格的。","h2":"拿到 Georgia Class D 驾照的前六个月，只允许直系家人坐车。","p":"对。一开始只能载直系家人。"},"vi":{"q":"Ở Georgia, trong sáu tháng đầu có bằng Class D, ai được ngồi cùng xe với người lái tuổi thiếu niên?","o":["Tối đa ba người bạn","Một người bạn dưới 21 tuổi","Bất kỳ ai, không giới hạn","Chỉ người thân trong gia đình gần (immediate family)"],"h1":"Lúc mới bắt đầu, quy định là nghiêm nhất.","h2":"Trong sáu tháng đầu có bằng Class D ở Georgia, chỉ người thân trong gia đình gần được ngồi cùng xe.","p":"Đúng. Lúc đầu chỉ có người thân trong gia đình gần."},"tl":{"q":"Sa Georgia, sa unang anim na buwan na may Class D license, sino ang puwedeng sumakay kasama ng teen na driver?","o":["Hanggang tatlong kaibigan","Isang kaibigan na wala pang 21","Kahit sino, walang limitasyon","Mga malapit na kapamilya lang (immediate family)"],"h1":"Sa simula, pinakamahigpit ang patakaran.","h2":"Sa unang anim na buwan na may Georgia Class D license, mga malapit na kapamilya lang ang puwedeng pasahero.","p":"Tama. Malapit na kapamilya lang sa simula."},"ar":{"q":"في Georgia، خلال الأشهر الستة الأولى برخصة Class D، من يمكنه الركوب مع السائق المراهق؟","o":["حتى ثلاثة أصدقاء","صديق واحد عمره أقل من 21 سنة","أي شخص، بلا حدود","أفراد العائلة المباشرة فقط (immediate family)"],"h1":"في البداية، تكون القاعدة في أشد حالاتها.","h2":"خلال الأشهر الستة الأولى برخصة Class D في Georgia، الركاب المسموح بهم هم أفراد العائلة المباشرة فقط.","p":"صحيح. أفراد العائلة المباشرة فقط في البداية."},"ref":{"doc":"GA","page":8}},{"id":"ga-013","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, during the second six months with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["None","One","Two","Five"],"h1":"The limit opens up a little, but only a little.","h2":"In the second six months with a Georgia Class D license, the teen may carry no more than one passenger under 21 who is not family.","p":"Right. One non-family passenger under 21."},"es":{"q":"En Georgia, durante el segundo semestre con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Ninguno","Uno","Dos","Cinco"],"h1":"El límite se abre un poco, pero muy poco.","h2":"En el segundo semestre con licencia Clase D en Georgia, el adolescente puede llevar como máximo un pasajero menor de 21 años que no sea familia.","p":"Correcto. Un pasajero menor de 21 que no es familia."},"zh":{"q":"在 Georgia，拿到 Class D 驾照的第二个六个月，青少年可以载多少位 21 岁以下、不是家人的乘客？","o":["一位都不行","一位","两位","五位"],"h1":"限制放宽了，但只放宽一点点。","h2":"拿到 Georgia Class D 驾照的第二个六个月，青少年最多只能载一位 21 岁以下、不是家人的乘客。","p":"对。一位 21 岁以下、不是家人的乘客。"},"vi":{"q":"Ở Georgia, trong sáu tháng thứ hai có bằng Class D, bao nhiêu hành khách dưới 21 tuổi không phải người nhà được ngồi cùng xe với thanh thiếu niên?","o":["Không ai","Một","Hai","Năm"],"h1":"Giới hạn được nới ra một chút, nhưng chỉ một chút.","h2":"Trong sáu tháng thứ hai có bằng Class D ở Georgia, thanh thiếu niên chỉ được chở tối đa một hành khách dưới 21 tuổi không phải người nhà.","p":"Đúng. Một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa Georgia, sa ikalawang anim na buwan na may Class D license, ilang pasahero na wala pang 21 at hindi kapamilya ang puwedeng sumakay kasama ng teen?","o":["Wala","Isa","Dalawa","Lima"],"h1":"Lumuluwag nang kaunti ang limitasyon, pero kaunti lang.","h2":"Sa ikalawang anim na buwan na may Georgia Class D license, hindi hihigit sa isang pasahero na wala pang 21 at hindi kapamilya ang puwedeng isakay ng teen.","p":"Tama. Isang pasahero na wala pang 21 at hindi kapamilya."},"ar":{"q":"في Georgia، خلال الأشهر الستة الثانية برخصة Class D، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكنه الركوب مع المراهق؟","o":["لا أحد","واحد","اثنان","خمسة"],"h1":"الحد يتّسع قليلًا، ولكن قليلًا فقط.","h2":"في الأشهر الستة الثانية برخصة Class D في Georgia، لا يجوز للمراهق أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. راكب واحد عمره أقل من 21 سنة وليس من العائلة."},"ref":{"doc":"GA","page":8}},{"id":"ga-014","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, after one year with a Class D license, how many passengers under 21 who are not family may ride with the teen?","o":["One","Two","Three","Any number"],"h1":"It is more than in the second six months, but there is still a limit.","h2":"After the first year with a Georgia Class D license, the teen may carry up to three passengers under 21 who are not family.","p":"Right. Up to three after the first year."},"es":{"q":"En Georgia, después de un año con licencia Clase D, ¿cuántos pasajeros menores de 21 años que no son familia pueden ir con el adolescente?","o":["Uno","Dos","Tres","Cualquier cantidad"],"h1":"Son más que en el segundo semestre, pero todavía hay un límite.","h2":"Después del primer año con licencia Clase D en Georgia, el adolescente puede llevar hasta tres pasajeros menores de 21 años que no sean familia.","p":"Correcto. Hasta tres después del primer año."},"zh":{"q":"在 Georgia，拿到 Class D 驾照一年以后，青少年可以载多少位 21 岁以下、不是家人的乘客？","o":["一位","两位","三位","任何人数"],"h1":"它比第二个六个月多，但还是有限制。","h2":"拿到 Georgia Class D 驾照一年以后，青少年最多可以载三位 21 岁以下、不是家人的乘客。","p":"对。第一年以后最多三位。"},"vi":{"q":"Ở Georgia, sau một năm có bằng Class D, bao nhiêu hành khách dưới 21 tuổi không phải người nhà được ngồi cùng xe với thanh thiếu niên?","o":["Một","Hai","Ba","Bao nhiêu cũng được"],"h1":"Nhiều hơn trong sáu tháng thứ hai, nhưng vẫn có giới hạn.","h2":"Sau năm đầu tiên có bằng Class D ở Georgia, thanh thiếu niên được chở tối đa ba hành khách dưới 21 tuổi không phải người nhà.","p":"Đúng. Tối đa ba người sau năm đầu tiên."},"tl":{"q":"Sa Georgia, pagkatapos ng isang taon na may Class D license, ilang pasahero na wala pang 21 at hindi kapamilya ang puwedeng sumakay kasama ng teen?","o":["Isa","Dalawa","Tatlo","Kahit ilan"],"h1":"Mas marami ito kaysa sa ikalawang anim na buwan, pero may limitasyon pa rin.","h2":"Pagkatapos ng unang taon na may Georgia Class D license, puwedeng magsakay ang teen ng hanggang tatlong pasahero na wala pang 21 at hindi kapamilya.","p":"Tama. Hanggang tatlo pagkatapos ng unang taon."},"ar":{"q":"في Georgia، بعد سنة واحدة برخصة Class D، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكنه الركوب مع المراهق؟","o":["واحد","اثنان","ثلاثة","أي عدد"],"h1":"العدد أكثر مما في الأشهر الستة الثانية، لكن ما زال هناك حد.","h2":"بعد السنة الأولى برخصة Class D في Georgia، يمكن للمراهق أن يحمل حتى ثلاثة ركاب أعمارهم أقل من 21 سنة وليسوا من العائلة.","p":"صحيح. حتى ثلاثة بعد السنة الأولى."},"ref":{"doc":"GA","page":8}},{"id":"ga-015","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, what does the hands-free law say about holding a phone while driving?","o":["You may not hold the phone or support it with any part of your body","You may hold it if you drive slowly","You may hold it on city streets only","You may hold it if you are over 21"],"h1":"The law is named after what your hands must be.","h2":"Georgia's hands-free law makes it illegal for any driver to hold a phone or support it with any part of the body while driving.","p":"Right. In Georgia the phone stays out of your hands."},"es":{"q":"En Georgia, ¿qué dice la ley de manos libres sobre sostener el teléfono mientras maneja?","o":["No puede sostener el teléfono ni apoyarlo con ninguna parte del cuerpo","Puede sostenerlo si maneja despacio","Puede sostenerlo solo en calles de la ciudad","Puede sostenerlo si tiene más de 21 años"],"h1":"El nombre de la ley dice cómo deben estar sus manos.","h2":"La ley de manos libres de Georgia prohíbe que cualquier conductor sostenga el teléfono o lo apoye con alguna parte del cuerpo mientras maneja.","p":"Correcto. En Georgia el teléfono no va en la mano."},"zh":{"q":"在 Georgia，免持（hands-free）法对开车时拿手机有什么规定？","o":["你不能拿着手机，也不能用身体任何部位撑着它","如果开得慢就可以拿着","只在市区街道可以拿着","如果你超过 21 岁就可以拿着"],"h1":"这条法律的名字说明了你的手必须怎样。","h2":"Georgia 的免持法规定，任何司机开车时用手拿着手机，或用身体任何部位撑着手机，都是违法的。","p":"对。在 Georgia，手机不能拿在手里。"},"vi":{"q":"Ở Georgia, luật rảnh tay (hands-free law) nói gì về việc cầm điện thoại khi lái xe?","o":["Bạn không được cầm điện thoại hay đỡ nó bằng bất kỳ phần nào của cơ thể","Bạn được cầm nếu lái chậm","Bạn được cầm chỉ trên đường trong thành phố","Bạn được cầm nếu trên 21 tuổi"],"h1":"Tên của luật nói về việc tay của bạn phải như thế nào.","h2":"Luật rảnh tay của Georgia cấm mọi người lái xe cầm điện thoại hoặc đỡ nó bằng bất kỳ phần nào của cơ thể khi đang lái.","p":"Đúng. Ở Georgia, điện thoại không được nằm trong tay bạn."},"tl":{"q":"Sa Georgia, ano ang sinasabi ng hands-free law tungkol sa paghawak ng telepono habang nagmamaneho?","o":["Hindi mo puwedeng hawakan ang telepono o suportahan ito ng kahit anong bahagi ng katawan mo","Puwede mo itong hawakan kung mabagal kang magmaneho","Puwede mo itong hawakan sa mga kalye sa lungsod lang","Puwede mo itong hawakan kung lampas 21 ka na"],"h1":"Ang pangalan ng batas ay tungkol sa kung paano dapat ang mga kamay mo.","h2":"Ayon sa hands-free law ng Georgia, bawal sa kahit sinong driver na hawakan ang telepono o suportahan ito ng kahit anong bahagi ng katawan habang nagmamaneho.","p":"Tama. Sa Georgia, hindi dapat nasa kamay mo ang telepono."},"ar":{"q":"في Georgia، ماذا يقول قانون القيادة بدون استخدام اليدين (hands-free law) عن حمل الهاتف أثناء القيادة؟","o":["لا يجوز لك أن تحمل الهاتف أو تسنده بأي جزء من جسمك","يجوز لك حمله إذا كنت تقود ببطء","يجوز لك حمله في شوارع المدينة فقط","يجوز لك حمله إذا كان عمرك أكثر من 21 سنة"],"h1":"اسم القانون يتحدث عن الحالة التي يجب أن تكون عليها يداك.","h2":"قانون hands-free في Georgia يمنع أي سائق من حمل الهاتف أو إسناده بأي جزء من الجسم أثناء القيادة.","p":"صحيح. في Georgia يبقى الهاتف خارج يديك."},"ref":{"doc":"GA","page":25}},{"id":"ga-016","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you use your phone for map directions while driving. Which way is allowed under the hands-free law?","o":["Holding it in your lap","Holding it in one hand","Resting it on your shoulder","In a phone holder or mount, without holding it"],"h1":"The phone must stay put without you holding it.","h2":"Georgia's hands-free law lets you use a phone for directions only when it sits in a holder or mount, not in your hand or on your body.","p":"Right. Put the phone in a holder or mount."},"es":{"q":"En Georgia, usted usa su teléfono para ver el mapa mientras maneja. ¿Qué manera permite la ley de manos libres?","o":["Sostenerlo en las piernas","Sostenerlo en una mano","Apoyarlo en el hombro","En un soporte o base, sin sostenerlo"],"h1":"El teléfono debe quedarse fijo sin que usted lo sostenga.","h2":"La ley de manos libres de Georgia le permite usar el teléfono para direcciones solo si está en un soporte o base, no en su mano ni sobre su cuerpo.","p":"Correcto. Ponga el teléfono en un soporte o base."},"zh":{"q":"在 Georgia，你开车时用手机看地图导航。根据免持法，哪一种方式是允许的？","o":["放在大腿上","用一只手拿着","靠在肩膀上","放在手机架或支架上，不用手拿"],"h1":"手机必须固定好，不用你拿着。","h2":"Georgia 的免持法只允许手机放在手机架或支架上时用来导航，不能拿在手里或放在身上。","p":"对。把手机放在手机架或支架上。"},"vi":{"q":"Ở Georgia, bạn dùng điện thoại để xem bản đồ chỉ đường khi lái xe. Cách nào được phép theo luật rảnh tay?","o":["Để nó trên đùi","Cầm nó bằng một tay","Kẹp nó trên vai","Đặt trong giá đỡ điện thoại, không cầm"],"h1":"Điện thoại phải nằm yên mà bạn không cần cầm.","h2":"Luật rảnh tay của Georgia chỉ cho phép dùng điện thoại để chỉ đường khi nó nằm trong giá đỡ, không ở trong tay hay trên người bạn.","p":"Đúng. Đặt điện thoại vào giá đỡ."},"tl":{"q":"Sa Georgia, ginagamit mo ang telepono para sa mapa at direksyon habang nagmamaneho. Aling paraan ang pinapayagan ng hands-free law?","o":["Nakapatong sa kandungan mo","Hawak ng isang kamay","Nakaipit sa balikat mo","Nasa phone holder o mount, hindi hawak"],"h1":"Dapat nakapirmi ang telepono nang hindi mo hinahawakan.","h2":"Pinapayagan ng hands-free law ng Georgia na gamitin ang telepono para sa direksyon kapag nasa holder o mount lang ito, hindi sa kamay o sa katawan mo.","p":"Tama. Ilagay ang telepono sa holder o mount."},"ar":{"q":"في Georgia، تستخدم هاتفك للخرائط والاتجاهات أثناء القيادة. ما الطريقة المسموح بها حسب قانون hands-free؟","o":["أن تضعه في حضنك","أن تحمله بيد واحدة","أن تسنده على كتفك","في حامل أو مثبّت للهاتف، دون أن تحمله"],"h1":"يجب أن يبقى الهاتف ثابتًا دون أن تحمله.","h2":"قانون hands-free في Georgia يسمح لك باستخدام الهاتف للاتجاهات فقط عندما يكون في حامل أو مثبّت، وليس في يدك أو على جسمك.","p":"صحيح. ضع الهاتف في حامل أو مثبّت."},"ref":{"doc":"GA","page":25}},{"id":"ga-017","scope":"GA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Georgia, you are driving the opposite way from a stopped school bus with flashing lights and stop signs out, on a divided highway. What must you do?","o":["Stop until the bus moves","Continue with caution; you do not have to stop","Speed up to pass quickly","Turn around"],"h1":"The divided highway is the only exception to the stopping rule.","h2":"In Georgia, drivers going the opposite way on a divided highway do not have to stop for a school bus, but they must drive with caution.","p":"Right. On a divided highway, oncoming traffic continues with caution."},"es":{"q":"En Georgia, usted va en dirección contraria a un autobús escolar detenido con luces intermitentes y señales de alto extendidas, en una carretera dividida. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Seguir con precaución; no tiene que detenerse","Acelerar para pasar rápido","Dar la vuelta"],"h1":"La carretera dividida es la única excepción a la regla de detenerse.","h2":"En Georgia, los conductores que van en dirección contraria en una carretera dividida no tienen que detenerse por un autobús escolar, pero deben manejar con precaución.","p":"Correcto. En carretera dividida, el tráfico contrario sigue con precaución."},"zh":{"q":"在 Georgia，在分隔公路上，你和一辆停着、灯在闪、伸出停车牌的校车方向相反。你必须怎么做？","o":["停车，直到校车开走","小心地继续开；你不必停车","加速快点开过去","掉头"],"h1":"分隔公路是停车规定唯一的例外。","h2":"在 Georgia，在分隔公路上方向相反的司机不必为校车停车，但必须小心开车。","p":"对。在分隔公路上，对面来的车小心地继续开。"},"vi":{"q":"Ở Georgia, bạn đang lái ngược chiều với một xe buýt trường học đang dừng, đèn nhấp nháy và biển STOP bật ra, trên đường cao tốc có dải phân cách. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Tiếp tục đi một cách cẩn thận; bạn không phải dừng","Tăng tốc để vượt qua nhanh","Quay đầu xe"],"h1":"Đường có dải phân cách là trường hợp ngoại lệ duy nhất của quy định phải dừng.","h2":"Ở Georgia, xe chạy ngược chiều trên đường có dải phân cách không phải dừng lại vì xe buýt trường học, nhưng phải lái thật cẩn thận.","p":"Đúng. Trên đường có dải phân cách, xe chạy ngược chiều tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Georgia, nagmamaneho ka sa kabilang direksyon ng isang nakahintong school bus na may kumikislap na ilaw at nakalabas na STOP sign, sa divided highway. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Magpatuloy nang maingat; hindi mo kailangang huminto","Bumilis para mabilis na makalampas","Umikot pabalik"],"h1":"Ang divided highway lang ang eksepsyon sa patakaran ng paghinto.","h2":"Sa Georgia, ang mga driver na nasa kabilang direksyon sa divided highway ay hindi kailangang huminto para sa school bus, pero dapat silang magmaneho nang maingat.","p":"Tama. Sa divided highway, ang paparating na trapiko ay nagpapatuloy nang maingat."},"ar":{"q":"في Georgia، أنت تقود في الاتجاه المعاكس لحافلة مدرسية متوقفة أضواؤها تومض ولافتات STOP مفتوحة، على طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["تتوقف حتى تتحرك الحافلة","تستمر بحذر؛ لا يلزمك التوقف","تسرع لتتجاوز بسرعة","تستدير وترجع"],"h1":"الطريق المقسوم بفاصل هو الاستثناء الوحيد من قاعدة التوقف.","h2":"في Georgia، السائقون الذين يسيرون في الاتجاه المعاكس على طريق مقسوم بفاصل لا يلزمهم التوقف للحافلة المدرسية، لكن يجب أن يقودوا بحذر.","p":"صحيح. على الطريق المقسوم بفاصل، تستمر حركة السير القادمة بحذر."},"ref":{"doc":"GA","page":44}},{"id":"ga-018","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, on a road that is not divided, a school bus stops with flashing lights and stop signs out. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic coming toward the bus","No one, if no children are seen"],"h1":"On a road with no division, nobody may pass the bus.","h2":"In Georgia, on a road that is not divided, vehicles going in either direction must stop and may not pass a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Georgia, en una calle que no está dividida, un autobús escolar se detiene con luces intermitentes y señales de alto extendidas. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, si no se ven niños"],"h1":"En una calle sin división, nadie puede pasar al autobús.","h2":"En Georgia, en una calle que no está dividida, los vehículos que van en cualquier dirección deben detenerse y no pueden pasar a un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"zh":{"q":"在 Georgia，在没有分隔的道路上，一辆校车停下来，灯在闪，伸出停车牌。谁必须停车？","o":["两个方向的车","只有校车后面的车","只有朝校车开过来的车","没人，如果看不到孩子"],"h1":"在没有分隔的道路上，谁都不能超过校车。","h2":"在 Georgia，在没有分隔的道路上，两个方向的车都必须停车，不能超过停着的校车。","p":"对。两个方向都要停车。"},"vi":{"q":"Ở Georgia, trên đường không có dải phân cách, một xe buýt trường học dừng lại với đèn nhấp nháy và biển STOP bật ra. Ai phải dừng?","o":["Xe ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe chạy về phía xe buýt","Không ai, nếu không thấy trẻ em"],"h1":"Trên đường không có dải phân cách, không ai được vượt xe buýt.","h2":"Ở Georgia, trên đường không có dải phân cách, xe chạy ở cả hai chiều phải dừng lại và không được vượt xe buýt trường học đang dừng.","p":"Đúng. Cả hai chiều đều dừng."},"tl":{"q":"Sa Georgia, sa kalsadang walang divider, huminto ang school bus na may kumikislap na ilaw at nakalabas na STOP sign. Sino ang dapat huminto?","o":["Trapiko sa parehong direksyon","Trapiko lang sa likod ng bus","Trapiko lang na papunta sa bus","Wala, kung walang nakikitang bata"],"h1":"Sa kalsadang walang divider, walang puwedeng lumampas sa bus.","h2":"Sa Georgia, sa kalsadang walang divider, ang mga sasakyan sa parehong direksyon ay dapat huminto at hindi puwedeng lumampas sa nakahintong school bus.","p":"Tama. Parehong direksyon ay humihinto."},"ar":{"q":"في Georgia، على طريق غير مقسوم بفاصل، تتوقف حافلة مدرسية أضواؤها تومض ولافتات STOP مفتوحة. من يجب أن يتوقف؟","o":["السيارات في الاتجاهين","السيارات خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد، إذا لم يُرَ أطفال"],"h1":"على طريق بلا فاصل، لا يجوز لأحد أن يتجاوز الحافلة.","h2":"في Georgia، على طريق غير مقسوم بفاصل، يجب على السيارات في الاتجاهين أن تتوقف ولا يجوز لها تجاوز حافلة مدرسية متوقفة.","p":"صحيح. الاتجاهان يتوقفان."},"ref":{"doc":"GA","page":44}},{"id":"ga-019","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, an emergency vehicle with flashing lights is parked on the shoulder. What does the Move Over Law require first, if it is safe?","o":["Honk to warn the workers","Stop in your lane","Move over one lane, away from the vehicle","Drive on the shoulder"],"h1":"The law's name tells you what to do.","h2":"Georgia's Move Over Law requires you to move over one lane, away from the stopped emergency vehicle, when it is safe to do so.","p":"Right. Move over one lane."},"es":{"q":"En Georgia, un vehículo de emergencia con luces intermitentes está estacionado en el acotamiento. ¿Qué exige primero la Ley de Cambio de Carril (Move Over), si es seguro?","o":["Tocar la bocina para avisar a los trabajadores","Detenerse en su carril","Cambiarse un carril, lejos del vehículo","Manejar por el acotamiento"],"h1":"El nombre de la ley le dice qué hacer.","h2":"La Ley de Cambio de Carril de Georgia exige que usted se cambie un carril, lejos del vehículo de emergencia detenido, cuando sea seguro hacerlo.","p":"Correcto. Cámbiese un carril."},"zh":{"q":"在 Georgia，一辆灯在闪的急救车辆停在路肩上。如果安全，Move Over Law 首先要求你做什么？","o":["按喇叭提醒工作人员","在你的车道停车","换开一条车道，离开那辆车","开到路肩上"],"h1":"这条法律的名字告诉你该怎么做。","h2":"Georgia 的 Move Over Law 要求你在安全时换开一条车道，离开停着的急救车辆。","p":"对。换开一条车道。"},"vi":{"q":"Ở Georgia, một xe cấp cứu hoặc xe khẩn cấp có đèn nhấp nháy đang đậu bên lề đường. Luật Tránh Sang Làn (Move Over Law) yêu cầu bạn làm gì trước tiên, nếu an toàn?","o":["Bấm còi để báo cho người làm việc","Dừng lại trong làn của bạn","Chuyển sang một làn, tránh xa xe đó","Lái trên lề đường"],"h1":"Tên của luật cho bạn biết phải làm gì.","h2":"Luật Move Over của Georgia yêu cầu bạn chuyển sang một làn, tránh xa xe khẩn cấp đang dừng, khi làm vậy là an toàn.","p":"Đúng. Chuyển sang một làn."},"tl":{"q":"Sa Georgia, may emergency vehicle na may kumikislap na ilaw na nakaparada sa gilid ng daan (shoulder). Ano ang unang hinihingi ng Move Over Law, kung ligtas?","o":["Bumusina para balaan ang mga trabahador","Huminto sa lane mo","Lumipat ng isang lane, palayo sa sasakyan","Magmaneho sa shoulder"],"h1":"Sinasabi ng pangalan ng batas kung ano ang gagawin.","h2":"Hinihingi ng Move Over Law ng Georgia na lumipat ka ng isang lane, palayo sa nakahintong emergency vehicle, kapag ligtas itong gawin.","p":"Tama. Lumipat ng isang lane."},"ar":{"q":"في Georgia، مركبة طوارئ أضواؤها تومض متوقفة على كتف الطريق (shoulder). ماذا يطلب قانون الابتعاد (Move Over Law) أولًا، إذا كان ذلك آمنًا؟","o":["أن تستخدم البوق لتحذير العاملين","أن تتوقف في مسارك","أن تنتقل مسارًا واحدًا بعيدًا عن المركبة","أن تقود على كتف الطريق"],"h1":"اسم القانون يخبرك بما يجب أن تفعل.","h2":"قانون Move Over في Georgia يطلب منك أن تنتقل مسارًا واحدًا بعيدًا عن مركبة الطوارئ المتوقفة، عندما يكون ذلك آمنًا.","p":"صحيح. انتقل مسارًا واحدًا."},"ref":{"doc":"GA","page":18}},{"id":"ga-020","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, traffic is too heavy to move over for a stopped emergency vehicle. What must you do?","o":["Keep your speed","Stop completely on the highway","Change lanes anyway","Slow down below the speed limit and be ready to stop"],"h1":"If you cannot get away from it, pass it gently.","h2":"When you cannot safely move over in Georgia, you must slow down below the posted speed limit and be prepared to stop.","p":"Right. Slow down and be ready to stop."},"es":{"q":"En Georgia, hay demasiado tráfico para cambiarse de carril por un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse por completo en la carretera","Cambiarse de carril de todos modos","Bajar la velocidad por debajo del límite y estar listo para detenerse"],"h1":"Si no puede alejarse, pase con suavidad.","h2":"Cuando no puede cambiarse de carril con seguridad en Georgia, usted debe bajar la velocidad por debajo del límite indicado y estar listo para detenerse.","p":"Correcto. Baje la velocidad y esté listo para detenerse."},"zh":{"q":"在 Georgia，车太多，无法为停着的急救车辆换道。你必须怎么做？","o":["保持速度","在公路上完全停车","还是硬要换道","减速到低于限速，并准备好停车"],"h1":"如果你无法离开它，就慢慢地开过去。","h2":"在 Georgia，当你无法安全换道时，你必须减速到低于标示的限速，并准备好停车。","p":"对。减速，准备好停车。"},"vi":{"q":"Ở Georgia, xe cộ quá đông nên bạn không thể chuyển làn để tránh một xe khẩn cấp đang dừng. Bạn phải làm gì?","o":["Giữ nguyên tốc độ","Dừng hẳn trên đường cao tốc","Vẫn cứ chuyển làn","Giảm tốc độ xuống dưới mức giới hạn và sẵn sàng dừng"],"h1":"Nếu bạn không thể tránh xa nó, hãy đi qua nó thật nhẹ nhàng.","h2":"Ở Georgia, khi bạn không thể chuyển làn một cách an toàn, bạn phải giảm tốc độ xuống dưới mức giới hạn ghi trên biển và sẵn sàng dừng lại.","p":"Đúng. Giảm tốc độ và sẵn sàng dừng."},"tl":{"q":"Sa Georgia, sobrang dami ng trapiko kaya hindi ka makalipat ng lane palayo sa nakahintong emergency vehicle. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo","Huminto nang tuluyan sa highway","Lumipat pa rin ng lane","Bumagal nang mas mababa sa speed limit at maging handang huminto"],"h1":"Kung hindi ka makalayo dito, dumaan nang dahan-dahan.","h2":"Kapag hindi ka ligtas na makalipat ng lane sa Georgia, dapat kang bumagal nang mas mababa sa nakapaskil na speed limit at maging handang huminto.","p":"Tama. Bumagal at maging handang huminto."},"ar":{"q":"في Georgia، الزحام شديد ولا يمكنك الانتقال بعيدًا عن مركبة طوارئ متوقفة. ماذا يجب أن تفعل؟","o":["تحافظ على سرعتك","تتوقف تمامًا على الطريق السريع","تغيّر المسار على أي حال","تخفف السرعة إلى أقل من الحد المسموح وتكون مستعدًا للتوقف"],"h1":"إذا لم تستطع الابتعاد عنها، فمرّ بجانبها بهدوء.","h2":"عندما لا تستطيع الانتقال بأمان في Georgia، يجب أن تخفف السرعة إلى أقل من الحد المكتوب على اللافتة وتكون مستعدًا للتوقف.","p":"صحيح. خفّف السرعة وكن مستعدًا للتوقف."},"ref":{"doc":"GA","page":18}},{"id":"ga-021","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, what is the legal blood alcohol limit for drivers under 21?","o":["0.00 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is much lower than the adult limit, but it is not zero.","h2":"In Georgia a driver under 21 is over the limit at a blood alcohol level of 0.02 percent, much lower than the 0.08 limit for adults.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Georgia, ¿cuál es el límite legal de alcohol en la sangre para conductores menores de 21 años?","o":["0.00 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite para adultos, pero no es cero.","h2":"En Georgia un conductor menor de 21 años pasa el límite con un nivel de alcohol en la sangre de 0.02 por ciento, mucho más bajo que el límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Georgia，21 岁以下司机的法定血液酒精浓度限制是多少？","o":["0.00%","0.02%","0.05%","0.08%"],"h1":"它比成年人的限制低很多，但不是零。","h2":"在 Georgia，21 岁以下的司机血液酒精浓度达到 0.02% 就超标了，这比成年人 0.08 的限制低很多。","p":"对。21 岁以下，限制是 0.02%。"},"vi":{"q":"Ở Georgia, giới hạn nồng độ cồn trong máu hợp pháp cho người lái dưới 21 tuổi là bao nhiêu?","o":["0.00 phần trăm","0.02 phần trăm","0.05 phần trăm","0.08 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn, nhưng không phải là số không.","h2":"Ở Georgia, người lái dưới 21 tuổi bị coi là vượt giới hạn khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Georgia, ano ang legal na limit ng alak sa dugo para sa mga driver na wala pang 21?","o":["0.00 porsyento","0.02 porsyento","0.05 porsyento","0.08 porsyento"],"h1":"Mas mababa ito nang malaki kaysa sa limit ng adult, pero hindi ito zero.","h2":"Sa Georgia, ang driver na wala pang 21 ay lampas sa limit kapag 0.02 porsyento ang alak sa dugo niya, mas mababa nang malaki kaysa sa 0.08 na limit para sa adult.","p":"Tama. Para sa wala pang 21, ang limit ay 0.02 porsyento."},"ar":{"q":"في Georgia، ما الحد القانوني لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة؟","o":["0.00 بالمئة","0.02 بالمئة","0.05 بالمئة","0.08 بالمئة"],"h1":"هو أقل بكثير من حد البالغين، لكنه ليس صفرًا.","h2":"في Georgia يكون السائق الذي عمره أقل من 21 سنة فوق الحد عندما تكون نسبة الكحول في دمه 0.02 بالمئة، وهي أقل بكثير من حد 0.08 للبالغين.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"GA","page":23}},{"id":"ga-022","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, a driver is convicted of going 85 mph or more on any road. What extra cost does the Super Speeder law add?","o":["No extra cost","A $20 state fee","A $200 state fee","A $2,000 state fee"],"h1":"It is added on top of the local fine, and it is a few hundred dollars.","h2":"In Georgia a Super Speeder pays a $200 state fee on top of any local fine.","p":"Right. Super Speeders pay an extra $200 state fee."},"es":{"q":"En Georgia, un conductor es condenado por ir a 85 mph o más en cualquier camino. ¿Qué costo adicional agrega la ley Super Speeder?","o":["Ningún costo adicional","Una tarifa estatal de $20","Una tarifa estatal de $200","Una tarifa estatal de $2,000"],"h1":"Se suma a la multa local, y son unos cientos de dólares.","h2":"En Georgia un Super Speeder paga una tarifa estatal de $200 además de cualquier multa local.","p":"Correcto. Los Super Speeders pagan una tarifa estatal adicional de $200."},"zh":{"q":"在 Georgia，一位司机因在任何道路上开到 85 mph 或以上被定罪。Super Speeder 法律会增加什么额外费用？","o":["没有额外费用","$20 的州费用","$200 的州费用","$2,000 的州费用"],"h1":"它是在地方罚款之外另加的，金额是几百美元。","h2":"在 Georgia，Super Speeder 除了地方罚款以外，还要付 $200 的州费用。","p":"对。Super Speeder 要多付 $200 的州费用。"},"vi":{"q":"Ở Georgia, một người lái bị kết tội chạy 85 mph trở lên trên bất kỳ con đường nào. Luật Super Speeder cộng thêm chi phí gì?","o":["Không có chi phí thêm","Một khoản phí tiểu bang $20","Một khoản phí tiểu bang $200","Một khoản phí tiểu bang $2,000"],"h1":"Nó được cộng thêm vào tiền phạt địa phương, và là vài trăm đô la.","h2":"Ở Georgia, một Super Speeder phải trả khoản phí tiểu bang $200, cộng thêm vào bất kỳ tiền phạt địa phương nào.","p":"Đúng. Super Speeder phải trả thêm khoản phí tiểu bang $200."},"tl":{"q":"Sa Georgia, nahatulan ang isang driver dahil tumakbo siya nang 85 mph o higit pa sa kahit anong kalsada. Anong dagdag na bayad ang idinadagdag ng batas na Super Speeder?","o":["Walang dagdag na bayad","Isang $20 na bayad sa estado","Isang $200 na bayad sa estado","Isang $2,000 na bayad sa estado"],"h1":"Idinadagdag ito sa lokal na multa, at ilang daang dolyar ito.","h2":"Sa Georgia, ang isang Super Speeder ay nagbabayad ng $200 na bayad sa estado bukod pa sa kahit anong lokal na multa.","p":"Tama. Ang mga Super Speeder ay nagbabayad ng dagdag na $200 na bayad sa estado."},"ar":{"q":"في Georgia، أُدين سائق لأنه قاد بسرعة 85 mph أو أكثر على أي طريق. ما التكلفة الإضافية التي يضيفها قانون Super Speeder؟","o":["لا توجد تكلفة إضافية","رسوم ولاية قدرها $20","رسوم ولاية قدرها $200","رسوم ولاية قدرها $2,000"],"h1":"تُضاف فوق الغرامة المحلية، وهي بضع مئات من الدولارات.","h2":"في Georgia يدفع الـ Super Speeder رسوم ولاية قدرها $200 فوق أي غرامة محلية.","p":"صحيح. يدفع الـ Super Speeder رسوم ولاية إضافية قدرها $200."},"ref":{"doc":"GA","page":21}},{"id":"ga-023","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, on a two-lane road, what speed makes a driver a Super Speeder?","o":["75 mph or more","60 mph or more","65 mph or more","90 mph or more"],"h1":"It is lower than the 85 mph that counts on any road.","h2":"In Georgia, driving 75 mph or more on a two-lane road makes you a Super Speeder.","p":"Right. On a two-lane road, 75 mph or more is Super Speeder territory."},"es":{"q":"En Georgia, en una carretera de dos carriles, ¿a qué velocidad un conductor se considera Super Speeder?","o":["75 mph o más","60 mph o más","65 mph o más","90 mph o más"],"h1":"Es menos que las 85 mph que cuentan en cualquier camino.","h2":"En Georgia, manejar a 75 mph o más en una carretera de dos carriles lo convierte en Super Speeder.","p":"Correcto. En una carretera de dos carriles, 75 mph o más es velocidad de Super Speeder."},"zh":{"q":"在 Georgia，在双车道道路上，开到什么速度会让司机成为 Super Speeder？","o":["75 mph 或以上","60 mph 或以上","65 mph 或以上","90 mph 或以上"],"h1":"它比在任何道路上都算数的 85 mph 低。","h2":"在 Georgia，在双车道道路上开到 75 mph 或以上，你就是 Super Speeder。","p":"对。在双车道道路上，75 mph 或以上就算 Super Speeder。"},"vi":{"q":"Ở Georgia, trên đường hai làn xe, chạy tốc độ nào thì người lái bị coi là Super Speeder?","o":["75 mph trở lên","60 mph trở lên","65 mph trở lên","90 mph trở lên"],"h1":"Nó thấp hơn mức 85 mph áp dụng trên mọi con đường.","h2":"Ở Georgia, chạy 75 mph trở lên trên đường hai làn xe thì bạn là Super Speeder.","p":"Đúng. Trên đường hai làn xe, 75 mph trở lên là mức Super Speeder."},"tl":{"q":"Sa Georgia, sa kalsadang may dalawang lane, anong bilis ang gumagawa sa isang driver na Super Speeder?","o":["75 mph o higit pa","60 mph o higit pa","65 mph o higit pa","90 mph o higit pa"],"h1":"Mas mababa ito kaysa sa 85 mph na binibilang sa kahit anong kalsada.","h2":"Sa Georgia, kapag nagmaneho ka nang 75 mph o higit pa sa kalsadang may dalawang lane, Super Speeder ka.","p":"Tama. Sa kalsadang may dalawang lane, ang 75 mph o higit pa ay bilis ng Super Speeder."},"ar":{"q":"في Georgia، على طريق بمسارين، ما السرعة التي تجعل السائق Super Speeder؟","o":["75 mph أو أكثر","60 mph أو أكثر","65 mph أو أكثر","90 mph أو أكثر"],"h1":"هي أقل من سرعة 85 mph التي تُحسب على أي طريق.","h2":"في Georgia، القيادة بسرعة 75 mph أو أكثر على طريق بمسارين تجعلك Super Speeder.","p":"صحيح. على طريق بمسارين، سرعة 75 mph أو أكثر هي سرعة Super Speeder."},"ref":{"doc":"GA","page":21}},{"id":"ga-024","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, what is the speed limit on a rural interstate when no other limit is posted?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"It is higher than the limit on an urban interstate.","h2":"In Georgia the speed limit on a rural interstate is 70 mph unless a sign shows another limit.","p":"Right. Rural interstates in Georgia are 70 mph unless posted otherwise."},"es":{"q":"En Georgia, ¿cuál es el límite de velocidad en una autopista interestatal rural cuando no hay otro límite indicado?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Es más alto que el límite en una interestatal urbana.","h2":"En Georgia el límite de velocidad en una interestatal rural es 70 mph, a menos que una señal indique otro límite.","p":"Correcto. Las interestatales rurales de Georgia son de 70 mph si no se indica otra cosa."},"zh":{"q":"在 Georgia，如果没有标示其他限速，乡村州际公路的限速是多少？","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"它比城市州际公路的限速高。","h2":"在 Georgia，乡村州际公路的限速是 70 mph，除非标志显示其他限速。","p":"对。在 Georgia，乡村州际公路限速 70 mph，除非另有标示。"},"vi":{"q":"Ở Georgia, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là bao nhiêu khi không có biển báo giới hạn khác?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Nó cao hơn giới hạn trên xa lộ liên tiểu bang trong thành phố.","h2":"Ở Georgia, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là 70 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Xa lộ liên tiểu bang ở vùng nông thôn tại Georgia là 70 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Georgia, ano ang speed limit sa rural na interstate kapag walang ibang limit na nakapaskil?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Mas mataas ito kaysa sa limit sa urban na interstate.","h2":"Sa Georgia, ang speed limit sa rural na interstate ay 70 mph maliban kung may karatula na nagpapakita ng ibang limit.","p":"Tama. Ang mga rural na interstate sa Georgia ay 70 mph maliban kung iba ang nakapaskil."},"ar":{"q":"في Georgia، ما حد السرعة على طريق سريع بين الولايات (interstate) في منطقة ريفية عندما لا توجد لافتة بحد آخر؟","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"هو أعلى من الحد على الطريق السريع بين الولايات داخل المدينة.","h2":"في Georgia حد السرعة على الطريق السريع بين الولايات في منطقة ريفية هو 70 mph، إلا إذا أظهرت لافتة حدًا آخر.","p":"صحيح. الطرق السريعة بين الولايات في المناطق الريفية في Georgia حدها 70 mph إلا إذا كُتب غير ذلك."},"ref":{"doc":"GA","page":21}},{"id":"ga-025","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, a child under what age must ride in a child safety seat that fits the child's height and weight?","o":["Under 4","Under 6","Under 12","Under 8"],"h1":"It is older than a preschool child, but younger than ten.","h2":"In Georgia a child under 8 years old must ride in a child safety seat that fits the child's height and weight.","p":"Right. Children under 8 need a proper child safety seat."},"es":{"q":"En Georgia, ¿un niño menor de qué edad debe viajar en un asiento de seguridad adecuado a su estatura y peso?","o":["Menor de 4 años","Menor de 6 años","Menor de 12 años","Menor de 8 años"],"h1":"Es mayor que un niño de preescolar, pero menor de diez años.","h2":"En Georgia un niño menor de 8 años debe viajar en un asiento de seguridad adecuado a su estatura y peso.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad adecuado."},"zh":{"q":"在 Georgia，几岁以下的儿童必须坐在适合其身高和体重的儿童安全座椅里？","o":["4 岁以下","6 岁以下","12 岁以下","8 岁以下"],"h1":"这个年龄比学龄前儿童大，但比十岁小。","h2":"在 Georgia，8 岁以下的儿童必须坐在适合其身高和体重的儿童安全座椅里。","p":"对。8 岁以下的儿童需要合适的儿童安全座椅。"},"vi":{"q":"Ở Georgia, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em phù hợp với chiều cao và cân nặng của trẻ?","o":["Dưới 4 tuổi","Dưới 6 tuổi","Dưới 12 tuổi","Dưới 8 tuổi"],"h1":"Tuổi này lớn hơn trẻ mẫu giáo, nhưng nhỏ hơn mười tuổi.","h2":"Ở Georgia, trẻ em dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em phù hợp với chiều cao và cân nặng của trẻ.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn cho trẻ em phù hợp."},"tl":{"q":"Sa Georgia, ang batang wala pang ilang taon ang dapat nakaupo sa child safety seat na akma sa taas at timbang ng bata?","o":["Wala pang 4","Wala pang 6","Wala pang 12","Wala pang 8"],"h1":"Mas matanda ito kaysa sa batang preschool, pero mas bata sa sampu.","h2":"Sa Georgia, ang batang wala pang 8 taong gulang ay dapat nakaupo sa child safety seat na akma sa taas at timbang ng bata.","p":"Tama. Ang mga batang wala pang 8 ay kailangan ng tamang child safety seat."},"ar":{"q":"في Georgia، الطفل الذي عمره أقل من كم سنة يجب أن يجلس في مقعد أمان للأطفال يناسب طوله ووزنه؟","o":["أقل من 4","أقل من 6","أقل من 12","أقل من 8"],"h1":"هو أكبر من طفل ما قبل المدرسة، لكنه أصغر من عشر سنوات.","h2":"في Georgia يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال يناسب طوله ووزنه.","p":"صحيح. الأطفال الذين أعمارهم أقل من 8 سنوات يحتاجون إلى مقعد أمان مناسب للأطفال."},"ref":{"doc":"GA","page":24}},{"id":"ga-026","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, who must wear a seat belt in any seat of a passenger vehicle, front or back?","o":["Only the driver","Only passengers over 65","Everyone under 18","Only people in the front seat"],"h1":"In the front seat everyone buckles up. For the back seat, think about age.","h2":"In Georgia everyone under 18 must wear a seat belt in any seat, and everyone in the front seat must wear one too.","p":"Right. Under 18, you buckle up in every seat."},"es":{"q":"En Georgia, ¿quién debe usar el cinturón de seguridad en cualquier asiento de un vehículo de pasajeros, adelante o atrás?","o":["Solo el conductor","Solo los pasajeros mayores de 65 años","Todos los menores de 18 años","Solo las personas del asiento delantero"],"h1":"En el asiento delantero todos se abrochan. Para el asiento trasero, piense en la edad.","h2":"En Georgia todos los menores de 18 años deben usar el cinturón en cualquier asiento, y todos en el asiento delantero también deben usarlo.","p":"Correcto. Si tiene menos de 18 años, se abrocha en cualquier asiento."},"zh":{"q":"在 Georgia，谁在乘用车的任何座位上（前座或后座）都必须系安全带？","o":["只有司机","只有 65 岁以上的乘客","所有 18 岁以下的人","只有坐在前座的人"],"h1":"前座的每个人都要系安全带。后座的话，想想年龄。","h2":"在 Georgia，所有 18 岁以下的人在任何座位上都必须系安全带，前座的每个人也都必须系。","p":"对。18 岁以下，每个座位都要系安全带。"},"vi":{"q":"Ở Georgia, ai phải thắt dây an toàn ở bất kỳ ghế nào trong xe chở khách, ghế trước hay ghế sau?","o":["Chỉ người lái","Chỉ hành khách trên 65 tuổi","Mọi người dưới 18 tuổi","Chỉ người ngồi ghế trước"],"h1":"Ở ghế trước ai cũng phải thắt dây. Còn ghế sau, hãy nghĩ đến tuổi.","h2":"Ở Georgia, mọi người dưới 18 tuổi phải thắt dây an toàn ở bất kỳ ghế nào, và mọi người ngồi ghế trước cũng phải thắt.","p":"Đúng. Dưới 18 tuổi, bạn thắt dây an toàn ở mọi ghế."},"tl":{"q":"Sa Georgia, sino ang dapat magsuot ng seat belt sa kahit anong upuan ng pampasaherong sasakyan, sa harap man o sa likod?","o":["Ang driver lang","Ang mga pasaherong lampas 65 lang","Lahat ng wala pang 18","Ang mga nasa harap na upuan lang"],"h1":"Sa harap na upuan, lahat ay nagsusuot ng seat belt. Para sa likod na upuan, isipin ang edad.","h2":"Sa Georgia, lahat ng wala pang 18 ay dapat magsuot ng seat belt sa kahit anong upuan, at lahat ng nasa harap na upuan ay dapat ding magsuot nito.","p":"Tama. Kapag wala ka pang 18, nagsusuot ka ng seat belt sa bawat upuan."},"ar":{"q":"في Georgia، من يجب أن يربط حزام الأمان في أي مقعد في سيارة الركاب، في الأمام أو في الخلف؟","o":["السائق فقط","الركاب الذين أعمارهم أكثر من 65 فقط","كل من عمره أقل من 18","من يجلسون في المقعد الأمامي فقط"],"h1":"في المقعد الأمامي يربط الجميع الحزام. أما المقعد الخلفي، ففكّر في العمر.","h2":"في Georgia يجب على كل من عمره أقل من 18 سنة أن يربط حزام الأمان في أي مقعد، ويجب على كل من في المقعد الأمامي أن يربطه أيضًا.","p":"صحيح. إذا كان عمرك أقل من 18، تربط الحزام في كل مقعد."},"ref":{"doc":"GA","page":24}},{"id":"ga-027","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, a driver under 21 is convicted of reckless driving. What happens to their driving privileges?","o":["Nothing, if it is a first offense","They are suspended","They get a warning only","They must retake the vision test"],"h1":"Young drivers face a stricter result for this offense.","h2":"In Georgia, a reckless driving conviction for a driver under 21 means all driving privileges are suspended.","p":"Right. Under 21, a reckless driving conviction leads to a suspension."},"es":{"q":"En Georgia, un conductor menor de 21 años es condenado por manejo imprudente. ¿Qué pasa con sus privilegios de manejo?","o":["Nada, si es la primera vez","Se suspenden","Solo recibe una advertencia","Debe repetir el examen de la vista"],"h1":"Los conductores jóvenes reciben un resultado más estricto por esta falta.","h2":"En Georgia, una condena por manejo imprudente para un conductor menor de 21 años significa que se suspenden todos sus privilegios de manejo.","p":"Correcto. Para menores de 21 años, una condena por manejo imprudente lleva a una suspensión."},"zh":{"q":"在 Georgia，一位 21 岁以下的司机因鲁莽驾驶被定罪。他的驾驶权利会怎样？","o":["如果是第一次违规，就没事","会被暂停","只会收到警告","必须重新做视力测试"],"h1":"年轻司机犯这种违规，结果会更严格。","h2":"在 Georgia，21 岁以下的司机如果被判鲁莽驾驶，所有驾驶权利都会被暂停。","p":"对。21 岁以下，鲁莽驾驶被定罪会导致驾照被暂停。"},"vi":{"q":"Ở Georgia, một người lái dưới 21 tuổi bị kết tội lái xe liều lĩnh. Quyền lái xe của người đó sẽ ra sao?","o":["Không sao, nếu là lần vi phạm đầu tiên","Bị đình chỉ","Chỉ bị cảnh cáo","Phải thi lại bài kiểm tra mắt"],"h1":"Người lái trẻ bị xử nặng hơn cho lỗi này.","h2":"Ở Georgia, nếu người lái dưới 21 tuổi bị kết tội lái xe liều lĩnh thì tất cả quyền lái xe sẽ bị đình chỉ.","p":"Đúng. Dưới 21 tuổi, bị kết tội lái xe liều lĩnh sẽ dẫn đến bị đình chỉ."},"tl":{"q":"Sa Georgia, nahatulan ng reckless driving ang isang driver na wala pang 21. Ano ang mangyayari sa kanyang karapatang magmaneho?","o":["Wala, kung ito ang unang paglabag","Sinususpinde ito","Babala lang ang makukuha niya","Kailangan niyang ulitin ang vision test"],"h1":"Mas mahigpit ang resulta para sa mga batang driver sa paglabag na ito.","h2":"Sa Georgia, kapag nahatulan ng reckless driving ang driver na wala pang 21, sinususpinde ang lahat ng karapatan niyang magmaneho.","p":"Tama. Kapag wala pang 21, ang hatol sa reckless driving ay nauuwi sa suspensyon."},"ar":{"q":"في Georgia، أُدين سائق عمره أقل من 21 سنة بالقيادة المتهورة. ماذا يحدث لحقه في القيادة؟","o":["لا شيء، إذا كانت أول مخالفة","يتم إيقافه","يحصل على تحذير فقط","يجب أن يعيد اختبار النظر"],"h1":"السائقون الصغار يواجهون نتيجة أشد لهذه المخالفة.","h2":"في Georgia، إذا أُدين سائق عمره أقل من 21 سنة بالقيادة المتهورة، يتم إيقاف كل حقوقه في القيادة.","p":"صحيح. لمن عمره أقل من 21 سنة، الإدانة بالقيادة المتهورة تؤدي إلى إيقاف الرخصة."},"ref":{"doc":"GA","page":23}},{"id":"ga-028","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, when you pass a bicycle in the same lane, how much space must you keep between your car and the bicycle?","o":["At least 1 foot","At least 3 feet","At least 6 feet","At least 10 feet"],"h1":"Think of about one long step to the side, the whole time you pass.","h2":"In Georgia, you must keep at least three feet between your car and a bicycle the whole time you pass it.","p":"Right. Keep at least three feet from a bicycle while passing."},"es":{"q":"En Georgia, al rebasar una bicicleta en el mismo carril, ¿cuánto espacio debe mantener entre su auto y la bicicleta?","o":["Al menos 1 pie","Al menos 3 pies","Al menos 6 pies","Al menos 10 pies"],"h1":"Piense en un paso largo hacia un lado, durante todo el rebase.","h2":"En Georgia, debe mantener al menos tres pies entre su auto y la bicicleta durante todo el rebase.","p":"Correcto. Mantenga al menos tres pies de la bicicleta al rebasarla."},"zh":{"q":"在 Georgia，当你在同一条车道上超过自行车时，你的车和自行车之间必须保持多少距离？","o":["至少 1 英尺","至少 3 英尺","至少 6 英尺","至少 10 英尺"],"h1":"想一想向旁边迈一大步的距离，而且超车的整个过程都要保持。","h2":"在 Georgia，你超过自行车的整个过程中，你的车和自行车之间必须保持至少 3 英尺的距离。","p":"对。超过自行车时，要和它保持至少 3 英尺的距离。"},"vi":{"q":"Ở Georgia, khi bạn vượt một xe đạp trong cùng làn đường, bạn phải giữ khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 3 feet","Ít nhất 6 feet","Ít nhất 10 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài sang bên, trong suốt lúc bạn vượt.","h2":"Ở Georgia, bạn phải giữ ít nhất 3 feet giữa xe của bạn và xe đạp trong suốt lúc bạn vượt nó.","p":"Đúng. Giữ ít nhất 3 feet với xe đạp khi vượt."},"tl":{"q":"Sa Georgia, kapag nilalampasan mo ang bisikleta sa parehong lane, gaano kalayo ang dapat mong panatilihin sa pagitan ng kotse mo at ng bisikleta?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 6 na talampakan","Hindi bababa sa 10 talampakan"],"h1":"Isipin ang isang mahabang hakbang patagilid, sa buong oras ng paglampas mo.","h2":"Sa Georgia, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng kotse mo at ng bisikleta sa buong oras na nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan mula sa bisikleta habang lumalampas."},"ar":{"q":"في Georgia، عندما تتجاوز درّاجة هوائية في نفس المسار، ما المسافة التي يجب أن تتركها بين سيارتك والدرّاجة؟","o":["قدم واحد (1 foot) على الأقل","3 أقدام على الأقل","6 أقدام على الأقل","10 أقدام على الأقل"],"h1":"فكّر في خطوة طويلة واحدة إلى الجانب، طوال وقت التجاوز.","h2":"في Georgia يجب أن تترك 3 أقدام على الأقل بين سيارتك والدرّاجة الهوائية طوال وقت تجاوزها.","p":"صحيح. اترك 3 أقدام على الأقل بينك وبين الدرّاجة عند التجاوز."},"ref":{"doc":"GA","page":19}},{"id":"ga-029","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, how close to a fire hydrant may you not park?","o":["Within 5 feet","Within 10 feet","Within 15 feet","Within 30 feet"],"h1":"Fire crews need room to reach the hydrant and connect a hose.","h2":"In Georgia, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En Georgia, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 5 pies","A menos de 10 pies","A menos de 15 pies","A menos de 30 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante y conectar la manguera.","h2":"En Georgia, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante al estacionarse."},"zh":{"q":"在 Georgia，你不可以在离消防栓多近的地方停车？","o":["5 英尺以内","10 英尺以内","15 英尺以内","30 英尺以内"],"h1":"消防员需要空间走到消防栓旁边并接上水管。","h2":"在 Georgia，你不可以在离消防栓 15 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Georgia, bạn không được đậu xe gần trụ nước cứu hỏa trong khoảng bao nhiêu?","o":["Trong vòng 5 feet","Trong vòng 10 feet","Trong vòng 15 feet","Trong vòng 30 feet"],"h1":"Lính cứu hỏa cần chỗ để đến trụ nước và nối ống nước.","h2":"Ở Georgia, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Georgia, gaano kalapit sa fire hydrant ang bawal kang pumarada?","o":["Sa loob ng 5 talampakan","Sa loob ng 10 talampakan","Sa loob ng 15 talampakan","Sa loob ng 30 talampakan"],"h1":"Kailangan ng mga bumbero ng espasyo para malapitan ang hydrant at maikabit ang hose.","h2":"Sa Georgia, bawal kang pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa fire hydrant kapag pumaparada."},"ar":{"q":"في Georgia، ما المسافة من صنبور إطفاء الحريق (fire hydrant) التي لا يجوز لك أن توقف سيارتك داخلها؟","o":["ضمن 5 أقدام","ضمن 10 أقدام","ضمن 15 قدمًا","ضمن 30 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور وتوصيل الخرطوم.","h2":"في Georgia لا يجوز لك أن توقف سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 15 قدمًا على الأقل عن صنبور إطفاء الحريق عندما توقف سيارتك."},"ref":{"doc":"GA","page":20}},{"id":"ga-030","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, you are driving in the left passing lane and faster traffic comes up behind you. What does the \"Slow Poke\" law say?","o":["Move to the right so the faster traffic can go by","Stay in the lane if you are at the speed limit","Speed up to match the faster traffic","Flash your brake lights to warn the driver"],"h1":"The left lane is meant for passing, no matter how fast you are going.","h2":"In Georgia, you must move out of the passing lane to let faster traffic go by, even if you are driving at the speed limit.","p":"Right. Move over to the right for faster traffic in the passing lane."},"es":{"q":"En Georgia, usted maneja en el carril izquierdo de rebase y viene tráfico más rápido detrás. ¿Qué dice la ley \"Slow Poke\"?","o":["Muévase a la derecha para que pase el tráfico más rápido","Quédese en el carril si va al límite de velocidad","Acelere para ir al ritmo del tráfico más rápido","Toque los frenos para avisar al conductor"],"h1":"El carril izquierdo es para rebasar, sin importar a qué velocidad vaya.","h2":"En Georgia, debe salir del carril de rebase para dejar pasar al tráfico más rápido, aunque vaya al límite de velocidad.","p":"Correcto. Muévase a la derecha para el tráfico más rápido en el carril de rebase."},"zh":{"q":"在 Georgia，你在左边的超车道上开车，后面有开得更快的车过来。\"Slow Poke\" 法律是怎么说的？","o":["向右边移，让更快的车过去","如果你在限速内，就留在这条车道上","加速，跟上更快的车","闪刹车灯提醒那个司机"],"h1":"不管你开多快，左边的车道都是用来超车的。","h2":"在 Georgia，你必须离开超车道，让更快的车过去，即使你正在按限速开车。","p":"对。在超车道上，要向右边移，让更快的车过去。"},"vi":{"q":"Ở Georgia, bạn đang lái trong làn vượt bên trái và xe chạy nhanh hơn đến phía sau bạn. Luật \"Slow Poke\" nói gì?","o":["Chuyển sang bên phải để xe nhanh hơn đi qua","Ở lại trong làn nếu bạn đang chạy đúng tốc độ giới hạn","Tăng tốc để theo kịp xe nhanh hơn","Nháy đèn phanh để cảnh báo tài xế đó"],"h1":"Làn bên trái là để vượt, dù bạn chạy nhanh đến đâu.","h2":"Ở Georgia, bạn phải ra khỏi làn vượt để xe nhanh hơn đi qua, ngay cả khi bạn đang chạy đúng tốc độ giới hạn.","p":"Đúng. Chuyển sang bên phải cho xe nhanh hơn trong làn vượt."},"tl":{"q":"Sa Georgia, nagmamaneho ka sa kaliwang passing lane at may mas mabilis na sasakyan na dumarating sa likod mo. Ano ang sinasabi ng batas na \"Slow Poke\"?","o":["Lumipat sa kanan para makadaan ang mas mabilis na sasakyan","Manatili sa lane kung nasa speed limit ka","Bumilis para makasabay sa mas mabilis na sasakyan","Pakislapin ang brake lights mo para bigyan ng babala ang driver"],"h1":"Ang kaliwang lane ay para sa paglampas, gaano man kabilis ang takbo mo.","h2":"Sa Georgia, dapat kang umalis sa passing lane para makadaan ang mas mabilis na sasakyan, kahit nasa speed limit ka.","p":"Tama. Lumipat sa kanan para sa mas mabilis na sasakyan sa passing lane."},"ar":{"q":"في Georgia، أنت تقود في مسار التجاوز الأيسر وتقترب منك من الخلف سيارات أسرع. ماذا يقول قانون \"Slow Poke\"؟","o":["انتقل إلى اليمين حتى تمرّ السيارات الأسرع","ابقَ في المسار إذا كنت تسير بالسرعة القصوى المسموحة","زِد سرعتك لتجاري السيارات الأسرع","اجعل أضواء الفرامل تومض لتحذير السائق"],"h1":"المسار الأيسر مخصّص للتجاوز، مهما كانت سرعتك.","h2":"في Georgia يجب أن تخرج من مسار التجاوز لتسمح للسيارات الأسرع بالمرور، حتى لو كنت تسير بالسرعة القصوى المسموحة.","p":"صحيح. انتقل إلى اليمين للسيارات الأسرع في مسار التجاوز."},"ref":{"doc":"GA","page":20}},{"id":"ga-031","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you fail the knowledge test for the second time. How long must you wait before you try that test again?","o":["Until the next day","30 days","3 days","7 days"],"h1":"After a first failure the wait is short. After the second, it is longer.","h2":"In Georgia, after a second or later failure, you must wait 7 days before taking that test again.","p":"Right. After a second failure, wait 7 days to retake the test."},"es":{"q":"En Georgia, usted reprueba el examen de conocimientos por segunda vez. ¿Cuánto debe esperar para volver a tomarlo?","o":["Hasta el día siguiente","30 días","3 días","7 días"],"h1":"Después del primer fracaso la espera es corta. Después del segundo, es más larga.","h2":"En Georgia, después de reprobar por segunda vez o más, debe esperar 7 días para volver a tomar ese examen.","p":"Correcto. Después de reprobar por segunda vez, espere 7 días para repetirlo."},"zh":{"q":"在 Georgia，你第二次没有通过笔试。你要等多久才能再考这个考试？","o":["等到第二天","30 天","3 天","7 天"],"h1":"第一次没通过，等的时间很短。第二次没通过，等的时间更长。","h2":"在 Georgia，第二次或以后没通过，你必须等 7 天才能再考这个考试。","p":"对。第二次没通过，要等 7 天再考。"},"vi":{"q":"Ở Georgia, bạn thi rớt bài thi kiến thức lần thứ hai. Bạn phải chờ bao lâu mới được thi lại bài đó?","o":["Đến ngày hôm sau","30 ngày","3 ngày","7 ngày"],"h1":"Sau lần rớt đầu tiên, thời gian chờ ngắn. Sau lần thứ hai, thời gian chờ dài hơn.","h2":"Ở Georgia, sau lần rớt thứ hai hoặc các lần sau, bạn phải chờ 7 ngày mới được thi lại bài đó.","p":"Đúng. Sau lần rớt thứ hai, chờ 7 ngày để thi lại."},"tl":{"q":"Sa Georgia, bumagsak ka sa knowledge test sa ikalawang beses. Gaano katagal ka dapat maghintay bago mo subukan ulit ang test na iyon?","o":["Hanggang sa susunod na araw","30 araw","3 araw","7 araw"],"h1":"Pagkatapos ng unang pagbagsak, maikli ang paghihintay. Pagkatapos ng ikalawa, mas matagal.","h2":"Sa Georgia, pagkatapos ng ikalawa o mas huling pagbagsak, dapat kang maghintay ng 7 araw bago kumuha ulit ng test na iyon.","p":"Tama. Pagkatapos ng ikalawang pagbagsak, maghintay ng 7 araw bago kumuha ulit."},"ar":{"q":"في Georgia، رسبت في اختبار المعرفة للمرة الثانية. كم يجب أن تنتظر قبل أن تحاول هذا الاختبار مرة أخرى؟","o":["حتى اليوم التالي","30 يومًا","3 أيام","7 أيام"],"h1":"بعد الرسوب الأول يكون الانتظار قصيرًا. وبعد الثاني يكون أطول.","h2":"في Georgia، بعد الرسوب للمرة الثانية أو أكثر، يجب أن تنتظر 7 أيام قبل أن تأخذ هذا الاختبار مرة أخرى.","p":"صحيح. بعد الرسوب الثاني، انتظر 7 أيام لتعيد الاختبار."},"ref":{"doc":"GA","page":13}},{"id":"ga-032","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how long is a Class C instructional permit (CP) valid?","o":["Up to 6 months","Up to 1 year","Up to 2 years","Up to 5 years"],"h1":"It lasts longer than the one year and one day a teen must hold it.","h2":"In Georgia, a Class C instructional permit is valid for up to 2 years.","p":"Right. The learner's permit is good for up to 2 years."},"es":{"q":"En Georgia, ¿por cuánto tiempo es válido el permiso de aprendizaje Clase C (CP)?","o":["Hasta 6 meses","Hasta 1 año","Hasta 2 años","Hasta 5 años"],"h1":"Dura más que el año y un día que un adolescente debe tenerlo.","h2":"En Georgia, el permiso de aprendizaje Clase C es válido hasta por 2 años.","p":"Correcto. El permiso de aprendizaje es válido hasta por 2 años."},"zh":{"q":"在 Georgia，Class C 学习驾照（CP）的有效期是多久？","o":["最多 6 个月","最多 1 年","最多 2 年","最多 5 年"],"h1":"它比青少年必须持有的一年零一天还要长。","h2":"在 Georgia，Class C 学习驾照的有效期最多是 2 年。","p":"对。学习驾照最多有效 2 年。"},"vi":{"q":"Ở Georgia, giấy phép tập lái Class C (CP) có giá trị trong bao lâu?","o":["Tối đa 6 tháng","Tối đa 1 năm","Tối đa 2 năm","Tối đa 5 năm"],"h1":"Nó dài hơn một năm và một ngày mà thanh thiếu niên phải giữ giấy phép.","h2":"Ở Georgia, giấy phép tập lái Class C có giá trị tối đa 2 năm.","p":"Đúng. Giấy phép tập lái có giá trị tối đa 2 năm."},"tl":{"q":"Sa Georgia, gaano katagal valid ang Class C instructional permit (CP)?","o":["Hanggang 6 na buwan","Hanggang 1 taon","Hanggang 2 taon","Hanggang 5 taon"],"h1":"Mas matagal ito kaysa sa isang taon at isang araw na dapat itong hawak ng isang teenager.","h2":"Sa Georgia, ang Class C instructional permit ay valid nang hanggang 2 taon.","p":"Tama. Valid ang learner's permit nang hanggang 2 taon."},"ar":{"q":"في Georgia، ما مدة صلاحية تصريح التعلّم Class C (CP)؟","o":["حتى 6 أشهر","حتى سنة واحدة (1)","حتى سنتين (2)","حتى 5 سنوات"],"h1":"مدته أطول من السنة واليوم الواحد التي يجب أن يحمله فيها المراهق.","h2":"في Georgia، تصريح التعلّم Class C صالح لمدة تصل إلى 2 سنة (سنتين).","p":"صحيح. تصريح التعلّم صالح لمدة تصل إلى سنتين (2)."},"ref":{"doc":"GA","page":8}},{"id":"ga-033","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, when you are issued a Class C driver's license, for how many years is it issued?","o":["4 years","8 years","5 years","10 years"],"h1":"It is a long term, more than five years.","h2":"In Georgia, a Class C driver's license is issued for 8 years.","p":"Right. A Class C license is issued for 8 years."},"es":{"q":"En Georgia, cuando le dan una licencia de conducir Clase C, ¿por cuántos años se la dan?","o":["4 años","8 años","5 años","10 años"],"h1":"Es un plazo largo, de más de cinco años.","h2":"En Georgia, la licencia de conducir Clase C se emite por 8 años.","p":"Correcto. La licencia Clase C se emite por 8 años."},"zh":{"q":"在 Georgia，你拿到 Class C 驾照时，它的有效期是几年？","o":["4 年","8 年","5 年","10 年"],"h1":"这是一段很长的时间，超过五年。","h2":"在 Georgia，Class C 驾照的有效期是 8 年。","p":"对。Class C 驾照的有效期是 8 年。"},"vi":{"q":"Ở Georgia, khi bạn được cấp bằng lái Class C, bằng có thời hạn bao nhiêu năm?","o":["4 năm","8 năm","5 năm","10 năm"],"h1":"Đó là một thời gian dài, hơn năm năm.","h2":"Ở Georgia, bằng lái Class C được cấp với thời hạn 8 năm.","p":"Đúng. Bằng lái Class C được cấp với thời hạn 8 năm."},"tl":{"q":"Sa Georgia, kapag binigyan ka ng Class C driver's license, ilang taon ito ibinibigay?","o":["4 na taon","8 taon","5 taon","10 taon"],"h1":"Mahabang panahon ito, higit sa limang taon.","h2":"Sa Georgia, ang Class C driver's license ay ibinibigay nang 8 taon.","p":"Tama. Ibinibigay ang Class C license nang 8 taon."},"ar":{"q":"في Georgia، عندما تحصل على رخصة قيادة Class C، لكم سنة تُصدر؟","o":["4 سنوات","8 سنوات","5 سنوات","10 سنوات"],"h1":"إنها مدة طويلة، أكثر من خمس سنوات.","h2":"في Georgia تُصدر رخصة القيادة Class C لمدة 8 سنوات.","p":"صحيح. تُصدر رخصة Class C لمدة 8 سنوات."},"ref":{"doc":"GA","page":9}},{"id":"ga-034","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you just became a resident and want to drive. How soon must you get a Georgia license or permit?","o":["Within 30 days","Within 90 days","Within 6 months","Within 1 year"],"h1":"The deadline is about one month.","h2":"In Georgia, a new resident must get a Georgia license or permit within 30 days.","p":"Right. New residents have 30 days to get a Georgia license or permit."},"es":{"q":"En Georgia, usted acaba de hacerse residente y quiere manejar. ¿En cuánto tiempo debe sacar una licencia o permiso de Georgia?","o":["En 30 días","En 90 días","En 6 meses","En 1 año"],"h1":"El plazo es de más o menos un mes.","h2":"En Georgia, un nuevo residente debe sacar una licencia o permiso de Georgia en 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para sacar una licencia o permiso de Georgia."},"zh":{"q":"在 Georgia，你刚成为居民，想要开车。你必须在多久之内拿到 Georgia 驾照或学习驾照？","o":["30 天内","90 天内","6 个月内","1 年内"],"h1":"期限大约是一个月。","h2":"在 Georgia，新居民必须在 30 天内拿到 Georgia 驾照或学习驾照。","p":"对。新居民有 30 天时间拿到 Georgia 驾照或学习驾照。"},"vi":{"q":"Ở Georgia, bạn vừa trở thành cư dân và muốn lái xe. Bạn phải lấy bằng lái hoặc giấy phép của Georgia trong thời gian bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 90 ngày","Trong vòng 6 tháng","Trong vòng 1 năm"],"h1":"Thời hạn là khoảng một tháng.","h2":"Ở Georgia, cư dân mới phải lấy bằng lái hoặc giấy phép của Georgia trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày để lấy bằng lái hoặc giấy phép của Georgia."},"tl":{"q":"Sa Georgia, bago ka pa lang naging residente at gusto mong magmaneho. Gaano kabilis ka dapat kumuha ng Georgia license o permit?","o":["Sa loob ng 30 araw","Sa loob ng 90 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon"],"h1":"Mga isang buwan ang palugit.","h2":"Sa Georgia, ang bagong residente ay dapat kumuha ng Georgia license o permit sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente para kumuha ng Georgia license o permit."},"ar":{"q":"في Georgia، أصبحت مقيمًا جديدًا وتريد أن تقود. خلال كم من الوقت يجب أن تحصل على رخصة أو تصريح من Georgia؟","o":["خلال 30 يومًا","خلال 90 يومًا","خلال 6 أشهر","خلال سنة واحدة (1)"],"h1":"المهلة حوالي شهر واحد.","h2":"في Georgia يجب على المقيم الجديد أن يحصل على رخصة أو تصريح من Georgia خلال 30 يومًا.","p":"صحيح. لدى المقيمين الجدد 30 يومًا للحصول على رخصة أو تصريح من Georgia."},"ref":{"doc":"GA","page":4}},{"id":"ga-035","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, what is the minimum vision needed for a regular (non-commercial) license?","o":["20/20 in both eyes","20/40 in both eyes","20/100 in one eye","20/60 in at least one eye"],"h1":"Only one eye has to meet the standard, and glasses or contacts may be used.","h2":"In Georgia, you need at least 20/60 vision in one eye, with or without glasses, for a regular license.","p":"Right. The minimum is 20/60 in one eye, with or without glasses."},"es":{"q":"En Georgia, ¿cuál es la visión mínima para una licencia regular (no comercial)?","o":["20/20 en ambos ojos","20/40 en ambos ojos","20/100 en un ojo","20/60 en al menos un ojo"],"h1":"Solo un ojo tiene que cumplir la norma, y se pueden usar lentes o lentes de contacto.","h2":"En Georgia, necesita por lo menos 20/60 de visión en un ojo, con o sin lentes, para una licencia regular.","p":"Correcto. El mínimo es 20/60 en un ojo, con o sin lentes."},"zh":{"q":"在 Georgia，普通（非商业）驾照最低需要什么视力？","o":["两只眼睛都是 20/20","两只眼睛都是 20/40","一只眼睛 20/100","至少一只眼睛 20/60"],"h1":"只需要一只眼睛达到标准，而且可以戴眼镜或隐形眼镜。","h2":"在 Georgia，普通驾照需要至少一只眼睛的视力达到 20/60，戴不戴眼镜都可以。","p":"对。最低要求是一只眼睛 20/60，戴不戴眼镜都可以。"},"vi":{"q":"Ở Georgia, thị lực tối thiểu cần có cho bằng lái thường (không phải bằng thương mại) là bao nhiêu?","o":["20/20 ở cả hai mắt","20/40 ở cả hai mắt","20/100 ở một mắt","20/60 ở ít nhất một mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn, và bạn có thể đeo kính hoặc kính áp tròng.","h2":"Ở Georgia, bạn cần thị lực ít nhất 20/60 ở một mắt, có hoặc không đeo kính, để lấy bằng lái thường.","p":"Đúng. Mức tối thiểu là 20/60 ở một mắt, có hoặc không đeo kính."},"tl":{"q":"Sa Georgia, ano ang pinakamababang paningin na kailangan para sa regular (hindi commercial) na license?","o":["20/20 sa dalawang mata","20/40 sa dalawang mata","20/100 sa isang mata","20/60 sa kahit isang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan, at puwedeng gumamit ng salamin o contact lens.","h2":"Sa Georgia, kailangan mo ng paningin na hindi bababa sa 20/60 sa isang mata, may salamin man o wala, para sa regular na license.","p":"Tama. Ang pinakamababa ay 20/60 sa isang mata, may salamin man o wala."},"ar":{"q":"في Georgia، ما أقل قوة نظر مطلوبة للرخصة العادية (غير التجارية)؟","o":["20/20 في العينين","20/40 في العينين","20/100 في عين واحدة","20/60 في عين واحدة على الأقل"],"h1":"يكفي أن تصل عين واحدة إلى المستوى المطلوب، ويمكن استخدام النظارات أو العدسات اللاصقة.","h2":"في Georgia تحتاج إلى نظر 20/60 على الأقل في عين واحدة، بالنظارات أو بدونها، للحصول على رخصة عادية.","p":"صحيح. الحد الأدنى هو 20/60 في عين واحدة، بالنظارات أو بدونها."},"ref":{"doc":"GA","page":4}},{"id":"ga-036","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, your driver's license has been expired for more than two years. What must you do to renew it?","o":["Pay a late fee only","Pass a vision test only","Pass vision, knowledge and road tests","Wait one year, then reapply"],"h1":"After that long, you must show again that you can see, know the rules and drive.","h2":"In Georgia, a license expired more than two years needs a vision test, a knowledge exam and a driving test to renew.","p":"Right. After more than two years, you take the vision, knowledge and road tests again."},"es":{"q":"En Georgia, su licencia de conducir lleva más de dos años vencida. ¿Qué debe hacer para renovarla?","o":["Pagar solo un recargo","Pasar solo un examen de la vista","Pasar los exámenes de la vista, de conocimientos y de manejo","Esperar un año y volver a solicitarla"],"h1":"Después de tanto tiempo, debe demostrar otra vez que ve bien, conoce las reglas y sabe manejar.","h2":"En Georgia, una licencia vencida por más de dos años requiere un examen de la vista, uno de conocimientos y uno de manejo para renovarla.","p":"Correcto. Después de más de dos años, vuelve a tomar los exámenes de la vista, de conocimientos y de manejo."},"zh":{"q":"在 Georgia，你的驾照已经过期超过两年。你必须做什么才能更新？","o":["只付滞纳金","只通过视力测试","通过视力测试、笔试和路考","等一年，然后重新申请"],"h1":"过了这么久，你必须再次证明你看得清、懂规则、会开车。","h2":"在 Georgia，驾照过期超过两年，更新时需要通过视力测试、笔试和路考。","p":"对。过期超过两年，你要重新参加视力测试、笔试和路考。"},"vi":{"q":"Ở Georgia, bằng lái của bạn đã hết hạn hơn hai năm. Bạn phải làm gì để gia hạn?","o":["Chỉ trả tiền phạt trễ hạn","Chỉ đậu bài kiểm tra mắt","Đậu bài kiểm tra mắt, bài thi kiến thức và bài thi lái xe trên đường","Chờ một năm, rồi nộp đơn lại"],"h1":"Sau thời gian dài như vậy, bạn phải chứng minh lại rằng bạn nhìn rõ, biết luật và biết lái xe.","h2":"Ở Georgia, bằng lái hết hạn hơn hai năm cần đậu bài kiểm tra mắt, bài thi kiến thức và bài thi lái xe để gia hạn.","p":"Đúng. Sau hơn hai năm, bạn thi lại bài kiểm tra mắt, bài thi kiến thức và bài thi lái xe trên đường."},"tl":{"q":"Sa Georgia, mahigit dalawang taon nang expired ang driver's license mo. Ano ang dapat mong gawin para ma-renew ito?","o":["Magbayad lang ng late fee","Pumasa lang sa vision test","Pumasa sa vision test, knowledge test at road test","Maghintay ng isang taon, saka mag-apply ulit"],"h1":"Pagkatapos ng ganoon katagal, dapat mong ipakita ulit na nakakakita ka, alam mo ang mga patakaran at marunong kang magmaneho.","h2":"Sa Georgia, ang license na mahigit dalawang taon nang expired ay kailangan ng vision test, knowledge exam at driving test para ma-renew.","p":"Tama. Pagkalipas ng mahigit dalawang taon, kukuha ka ulit ng vision test, knowledge test at road test."},"ar":{"q":"في Georgia، انتهت صلاحية رخصة قيادتك منذ أكثر من سنتين. ماذا يجب أن تفعل لتجديدها؟","o":["تدفع غرامة تأخير فقط","تنجح في اختبار النظر فقط","تنجح في اختبار النظر واختبار المعرفة واختبار القيادة على الطريق","تنتظر سنة واحدة، ثم تقدّم طلبًا من جديد"],"h1":"بعد كل هذا الوقت، يجب أن تُثبت من جديد أنك ترى جيدًا وتعرف القواعد وتستطيع القيادة.","h2":"في Georgia، الرخصة المنتهية منذ أكثر من سنتين تحتاج إلى اختبار النظر واختبار المعرفة واختبار القيادة لتجديدها.","p":"صحيح. بعد أكثر من سنتين، تعيد اختبار النظر واختبار المعرفة واختبار القيادة على الطريق."},"ref":{"doc":"GA","page":6}},{"id":"ga-037","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you move to a new home. How soon must you update your address with DDS?","o":["Within 60 days","Within 10 days","Within 6 months","At your next renewal"],"h1":"You have about two months.","h2":"In Georgia, you must update your address with DDS within 60 days of moving.","p":"Right. Update your address with DDS within 60 days."},"es":{"q":"En Georgia, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar su dirección con DDS?","o":["En 60 días","En 10 días","En 6 meses","En su próxima renovación"],"h1":"Tiene unos dos meses.","h2":"En Georgia, debe actualizar su dirección con DDS en un plazo de 60 días después de mudarse.","p":"Correcto. Actualice su dirección con DDS en 60 días."},"zh":{"q":"在 Georgia，你搬了新家。你必须在多久之内向 DDS 更新地址？","o":["60 天内","10 天内","6 个月内","下次更新驾照时"],"h1":"你大约有两个月时间。","h2":"在 Georgia，你必须在搬家后 60 天内向 DDS 更新地址。","p":"对。要在 60 天内向 DDS 更新地址。"},"vi":{"q":"Ở Georgia, bạn chuyển đến nhà mới. Bạn phải cập nhật địa chỉ với DDS trong thời gian bao lâu?","o":["Trong vòng 60 ngày","Trong vòng 10 ngày","Trong vòng 6 tháng","Vào lần gia hạn bằng lái tới"],"h1":"Bạn có khoảng hai tháng.","h2":"Ở Georgia, bạn phải cập nhật địa chỉ với DDS trong vòng 60 ngày sau khi chuyển nhà.","p":"Đúng. Cập nhật địa chỉ với DDS trong vòng 60 ngày."},"tl":{"q":"Sa Georgia, lumipat ka sa bagong bahay. Gaano kabilis mo dapat i-update ang address mo sa DDS?","o":["Sa loob ng 60 araw","Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa susunod mong renewal"],"h1":"Mga dalawang buwan ang mayroon ka.","h2":"Sa Georgia, dapat mong i-update ang address mo sa DDS sa loob ng 60 araw pagkatapos lumipat.","p":"Tama. I-update ang address mo sa DDS sa loob ng 60 araw."},"ar":{"q":"في Georgia، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تحدّث عنوانك لدى DDS؟","o":["خلال 60 يومًا","خلال 10 أيام","خلال 6 أشهر","عند تجديد رخصتك القادم"],"h1":"لديك حوالي شهرين.","h2":"في Georgia يجب أن تحدّث عنوانك لدى DDS خلال 60 يومًا من الانتقال.","p":"صحيح. حدّث عنوانك لدى DDS خلال 60 يومًا."},"ref":{"doc":"GA","page":16}},{"id":"ga-038","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, what is the minimum score needed to pass the Class C or D road test?","o":["50 percent","60 percent","70 percent","75 percent"],"h1":"It is the same share needed on each part of the knowledge test: 15 out of 20.","h2":"In Georgia, you need a score of at least 75 percent to pass the Class C or D road test.","p":"Right. You need at least 75 percent on the road test."},"es":{"q":"En Georgia, ¿cuál es la calificación mínima para aprobar el examen de manejo Clase C o D?","o":["50 por ciento","60 por ciento","70 por ciento","75 por ciento"],"h1":"Es la misma proporción que se pide en cada parte del examen de conocimientos: 15 de 20.","h2":"En Georgia, necesita por lo menos 75 por ciento para aprobar el examen de manejo Clase C o D.","p":"Correcto. Necesita por lo menos 75 por ciento en el examen de manejo."},"zh":{"q":"在 Georgia，通过 Class C 或 D 路考最低需要多少分？","o":["50%","60%","70%","75%"],"h1":"这和笔试每一部分需要的比例一样：20 题答对 15 题。","h2":"在 Georgia，你需要至少 75% 的分数才能通过 Class C 或 D 路考。","p":"对。路考至少需要 75%。"},"vi":{"q":"Ở Georgia, điểm tối thiểu để đậu bài thi lái xe trên đường Class C hoặc D là bao nhiêu?","o":["50 phần trăm","60 phần trăm","70 phần trăm","75 phần trăm"],"h1":"Đó là cùng tỉ lệ cần có ở mỗi phần của bài thi kiến thức: 15 trên 20.","h2":"Ở Georgia, bạn cần ít nhất 75 phần trăm để đậu bài thi lái xe trên đường Class C hoặc D.","p":"Đúng. Bạn cần ít nhất 75 phần trăm ở bài thi lái xe trên đường."},"tl":{"q":"Sa Georgia, ano ang pinakamababang score na kailangan para pumasa sa Class C o D road test?","o":["50 porsiyento","60 porsiyento","70 porsiyento","75 porsiyento"],"h1":"Ito rin ang bahaging kailangan sa bawat parte ng knowledge test: 15 sa 20.","h2":"Sa Georgia, kailangan mo ng score na hindi bababa sa 75 porsiyento para pumasa sa Class C o D road test.","p":"Tama. Kailangan mo ng hindi bababa sa 75 porsiyento sa road test."},"ar":{"q":"في Georgia، ما أقل نتيجة مطلوبة للنجاح في اختبار القيادة على الطريق Class C أو D؟","o":["50 بالمئة","60 بالمئة","70 بالمئة","75 بالمئة"],"h1":"إنها النسبة نفسها المطلوبة في كل جزء من اختبار المعرفة: 15 من 20.","h2":"في Georgia تحتاج إلى نتيجة 75 بالمئة على الأقل للنجاح في اختبار القيادة على الطريق Class C أو D.","p":"صحيح. تحتاج إلى 75 بالمئة على الأقل في اختبار القيادة على الطريق."},"ref":{"doc":"GA","page":13}},{"id":"ga-039","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, what is the penalty for a first conviction under the hands-free phone law?","o":["A warning only, with no points","1 point and a fine of up to $50","3 points and a fine of up to $150","6 points and a fine of up to $1,000"],"h1":"The penalty is small the first time and grows with each conviction.","h2":"In Georgia, a first hands-free law conviction brings 1 point and a fine of up to $50.","p":"Right. The first conviction is 1 point and up to $50."},"es":{"q":"En Georgia, ¿cuál es la sanción por una primera condena bajo la ley de manos libres?","o":["Solo una advertencia, sin puntos","1 punto y una multa de hasta $50","3 puntos y una multa de hasta $150","6 puntos y una multa de hasta $1,000"],"h1":"La sanción es pequeña la primera vez y aumenta con cada condena.","h2":"En Georgia, una primera condena por la ley de manos libres trae 1 punto y una multa de hasta $50.","p":"Correcto. La primera condena es 1 punto y hasta $50."},"zh":{"q":"在 Georgia，第一次违反免提手机法被定罪，会受到什么处罚？","o":["只有警告，不扣分","记 1 分，罚款最多 $50","记 3 分，罚款最多 $150","记 6 分，罚款最多 $1,000"],"h1":"第一次的处罚很轻，以后每次定罪会越来越重。","h2":"在 Georgia，第一次违反免提法被定罪，会记 1 分，罚款最多 $50。","p":"对。第一次定罪是记 1 分，罚款最多 $50。"},"vi":{"q":"Ở Georgia, hình phạt cho lần đầu bị kết tội vi phạm luật dùng điện thoại rảnh tay (hands-free) là gì?","o":["Chỉ cảnh cáo, không bị điểm","1 điểm và phạt tiền tối đa $50","3 điểm và phạt tiền tối đa $150","6 điểm và phạt tiền tối đa $1,000"],"h1":"Lần đầu hình phạt nhẹ, và nặng dần sau mỗi lần bị kết tội.","h2":"Ở Georgia, lần đầu bị kết tội vi phạm luật rảnh tay sẽ bị 1 điểm và phạt tiền tối đa $50.","p":"Đúng. Lần đầu bị kết tội là 1 điểm và tối đa $50."},"tl":{"q":"Sa Georgia, ano ang parusa sa unang conviction sa ilalim ng hands-free phone law?","o":["Babala lang, walang points","1 point at multa na hanggang $50","3 points at multa na hanggang $150","6 na points at multa na hanggang $1,000"],"h1":"Maliit ang parusa sa unang beses at lumalaki sa bawat conviction.","h2":"Sa Georgia, ang unang conviction sa hands-free law ay may 1 point at multa na hanggang $50.","p":"Tama. Ang unang conviction ay 1 point at hanggang $50."},"ar":{"q":"في Georgia، ما عقوبة أول إدانة بمخالفة قانون استخدام الهاتف دون اليدين (hands-free)؟","o":["إنذار فقط، دون نقاط","نقطة واحدة (1) وغرامة تصل إلى $50","3 نقاط وغرامة تصل إلى $150","6 نقاط وغرامة تصل إلى $1,000"],"h1":"العقوبة صغيرة في المرة الأولى وتزيد مع كل إدانة.","h2":"في Georgia، أول إدانة بمخالفة قانون hands-free تعني نقطة واحدة (1) وغرامة تصل إلى $50.","p":"صحيح. أول إدانة تعني نقطة واحدة (1) وغرامة تصل إلى $50."},"ref":{"doc":"GA","page":25}},{"id":"ga-040","scope":"GA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Georgia, what is the highest fine for a first violation of the Move Over Law?","o":["$100","$250","$500","$5,000"],"h1":"It is a few hundred dollars.","h2":"In Georgia, a first Move Over Law violation can bring a fine of up to $500.","p":"Right. A first offense can cost up to $500."},"es":{"q":"En Georgia, ¿cuál es la multa más alta por una primera infracción de la Ley de Cambio de Carril (Move Over)?","o":["$100","$250","$500","$5,000"],"h1":"Son unos cientos de dólares.","h2":"En Georgia, una primera infracción de la Ley Move Over puede traer una multa de hasta $500.","p":"Correcto. Una primera infracción puede costar hasta $500."},"zh":{"q":"在 Georgia，第一次违反让道法（Move Over Law），最高罚款是多少？","o":["$100","$250","$500","$5,000"],"h1":"是几百美元。","h2":"在 Georgia，第一次违反让道法（Move Over Law）最高可罚款 $500。","p":"对。第一次违规最多可罚 $500。"},"vi":{"q":"Ở Georgia, tiền phạt cao nhất cho lần đầu vi phạm luật nhường làn (Move Over Law) là bao nhiêu?","o":["$100","$250","$500","$5,000"],"h1":"Đó là vài trăm đô la.","h2":"Ở Georgia, lần đầu vi phạm luật Move Over Law có thể bị phạt tiền tối đa $500.","p":"Đúng. Lần vi phạm đầu tiên có thể bị phạt tối đa $500."},"tl":{"q":"Sa Georgia, ano ang pinakamataas na multa sa unang paglabag sa Move Over Law?","o":["$100","$250","$500","$5,000"],"h1":"Ilang daang dolyar ito.","h2":"Sa Georgia, ang unang paglabag sa Move Over Law ay puwedeng magmulta nang hanggang $500.","p":"Tama. Ang unang paglabag ay puwedeng umabot nang hanggang $500."},"ar":{"q":"في Georgia، ما أعلى غرامة لأول مخالفة لقانون الابتعاد عن المركبات المتوقفة (Move Over Law)؟","o":["$100","$250","$500","$5,000"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Georgia، أول مخالفة لقانون Move Over Law قد تؤدي إلى غرامة تصل إلى $500.","p":"صحيح. أول مخالفة قد تكلّف حتى $500."},"ref":{"doc":"GA","page":18}},{"id":"ga-041","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, on a two-lane road, how close to a railroad crossing may you not pass another vehicle?","o":["Within 100 feet","Within 25 feet","Within 50 feet","Within 500 feet"],"h1":"The same distance applies near a bridge or tunnel.","h2":"In Georgia, you may not pass on a two-lane road within 100 feet of a railroad crossing.","p":"Right. No passing within 100 feet of a railroad crossing."},"es":{"q":"En Georgia, en una carretera de dos carriles, ¿a qué distancia de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["A menos de 100 pies","A menos de 25 pies","A menos de 50 pies","A menos de 500 pies"],"h1":"La misma distancia se aplica cerca de un puente o un túnel.","h2":"En Georgia, no puede rebasar en una carretera de dos carriles a menos de 100 pies de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de un cruce de ferrocarril."},"zh":{"q":"在 Georgia，在双车道的路上，离铁路道口多近的范围内不可以超车？","o":["100 英尺以内","25 英尺以内","50 英尺以内","500 英尺以内"],"h1":"在桥或隧道附近也是同样的距离。","h2":"在 Georgia，在双车道的路上，离铁路道口 100 英尺以内不可以超车。","p":"对。离铁路道口 100 英尺以内不可以超车。"},"vi":{"q":"Ở Georgia, trên đường hai làn, trong khoảng cách bao gần đường ray xe lửa thì bạn không được vượt xe khác?","o":["Trong vòng 100 feet","Trong vòng 25 feet","Trong vòng 50 feet","Trong vòng 500 feet"],"h1":"Khoảng cách này cũng áp dụng gần cầu hoặc đường hầm.","h2":"Ở Georgia, bạn không được vượt xe trên đường hai làn trong vòng 100 feet trước chỗ băng qua đường ray xe lửa.","p":"Đúng. Không được vượt xe trong vòng 100 feet trước đường ray xe lửa."},"tl":{"q":"Sa Georgia, sa kalsadang may dalawang lane, gaano kalapit sa railroad crossing na hindi ka puwedeng mag-overtake ng ibang sasakyan?","o":["Sa loob ng 100 talampakan","Sa loob ng 25 talampakan","Sa loob ng 50 talampakan","Sa loob ng 500 talampakan"],"h1":"Ganito rin ang layo malapit sa tulay o tunnel.","h2":"Sa Georgia, hindi ka puwedeng mag-overtake sa kalsadang may dalawang lane sa loob ng 100 talampakan mula sa railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 talampakan mula sa railroad crossing."},"ar":{"q":"في Georgia، على طريق بمسارين، على أي مسافة من معبر السكة الحديدية لا يجوز لك تجاوز مركبة أخرى؟","o":["ضمن 100 قدم","ضمن 25 قدمًا","ضمن 50 قدمًا","ضمن 500 قدم"],"h1":"المسافة نفسها تنطبق قرب جسر أو نفق.","h2":"في Georgia لا يجوز لك التجاوز على طريق بمسارين ضمن 100 قدم من معبر السكة الحديدية.","p":"صحيح. ممنوع التجاوز ضمن 100 قدم من معبر السكة الحديدية."},"ref":{"doc":"GA","page":18}},{"id":"ga-042","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you want to pass a bicycle but cannot safely change lanes. How slow must you go while passing?","o":["5 mph under the posted limit","Exactly 15 mph","Half of the posted limit","At least 10 mph under the limit, or 25 mph if that is higher"],"h1":"There is a set number of miles per hour below the limit, with a lowest speed of its own.","h2":"In Georgia, if you cannot change lanes, you must slow to at least 10 mph under the limit, or 25 mph if that is higher, and keep 3 feet away.","p":"Right. Slow to at least 10 mph under the limit, or 25 mph if that is higher."},"es":{"q":"En Georgia, quiere rebasar a una bicicleta pero no puede cambiar de carril con seguridad. ¿Qué tan despacio debe ir al rebasar?","o":["5 mph menos que el límite","Exactamente 15 mph","La mitad del límite","Al menos 10 mph menos que el límite, o 25 mph si eso es más alto"],"h1":"Hay un número fijo de millas por hora por debajo del límite, con una velocidad mínima propia.","h2":"En Georgia, si no puede cambiar de carril, debe bajar al menos 10 mph del límite, o a 25 mph si eso es más alto, y mantener 3 pies de distancia.","p":"Correcto. Baje al menos 10 mph del límite, o a 25 mph si eso es más alto."},"zh":{"q":"在 Georgia，你想超过一辆自行车，但无法安全换道。超车时你必须开多慢？","o":["比标示限速低 5 mph","正好 15 mph","标示限速的一半","至少比限速低 10 mph，如果 25 mph 更高就用 25 mph"],"h1":"要比限速低一个固定的 mph 数，而且它自己也有一个最低速度。","h2":"在 Georgia，如果你无法换道，你必须减速到至少比限速低 10 mph，如果 25 mph 更高就减到 25 mph，并且保持 3 英尺的距离。","p":"对。减速到至少比限速低 10 mph，如果 25 mph 更高就用 25 mph。"},"vi":{"q":"Ở Georgia, bạn muốn vượt một xe đạp nhưng không thể chuyển làn an toàn. Bạn phải chạy chậm đến mức nào khi vượt?","o":["Thấp hơn mức giới hạn ghi trên biển 5 mph","Đúng 15 mph","Một nửa mức giới hạn ghi trên biển","Thấp hơn mức giới hạn ít nhất 10 mph, hoặc 25 mph nếu con số đó cao hơn"],"h1":"Có một số mph cố định thấp hơn mức giới hạn, và cũng có một tốc độ thấp nhất riêng.","h2":"Ở Georgia, nếu bạn không thể chuyển làn, bạn phải giảm tốc độ xuống thấp hơn mức giới hạn ít nhất 10 mph, hoặc 25 mph nếu con số đó cao hơn, và giữ khoảng cách 3 feet.","p":"Đúng. Giảm tốc độ xuống thấp hơn mức giới hạn ít nhất 10 mph, hoặc 25 mph nếu con số đó cao hơn."},"tl":{"q":"Sa Georgia, gusto mong lampasan ang isang bisikleta pero hindi ka ligtas na makalipat ng lane. Gaano kabagal ka dapat habang lumalampas?","o":["5 mph na mas mababa sa nakapaskil na limit","Eksaktong 15 mph","Kalahati ng nakapaskil na limit","Hindi bababa sa 10 mph na mas mababa sa limit, o 25 mph kung mas mataas iyon"],"h1":"May takdang bilang ng mph na mas mababa sa limit, at may sarili rin itong pinakamababang bilis.","h2":"Sa Georgia, kung hindi ka makalipat ng lane, dapat kang bumagal nang hindi bababa sa 10 mph na mas mababa sa limit, o 25 mph kung mas mataas iyon, at manatiling 3 talampakan ang layo.","p":"Tama. Bumagal nang hindi bababa sa 10 mph na mas mababa sa limit, o 25 mph kung mas mataas iyon."},"ar":{"q":"في Georgia، تريد تجاوز دراجة هوائية لكنك لا تستطيع تغيير المسار بأمان. إلى أي حد يجب أن تبطئ أثناء التجاوز؟","o":["أقل من الحد المكتوب على اللافتة بـ 5 mph","15 mph بالضبط","نصف الحد المكتوب على اللافتة","أقل من الحد بـ 10 mph على الأقل، أو 25 mph إذا كانت أعلى"],"h1":"هناك عدد ثابت من الأميال في الساعة تحت الحد، وله أيضًا سرعة دنيا خاصة به.","h2":"في Georgia، إذا لم تستطع تغيير المسار، يجب أن تخفف السرعة إلى أقل من الحد بـ 10 mph على الأقل، أو إلى 25 mph إذا كانت أعلى، وتبقى على بُعد 3 أقدام.","p":"صحيح. خفّف السرعة إلى أقل من الحد بـ 10 mph على الأقل، أو إلى 25 mph إذا كانت أعلى."},"ref":{"doc":"GA","page":19}},{"id":"ga-043","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, how close to a stop sign may you not park?","o":["Within 10 feet","Within 30 feet","Within 50 feet","Within 100 feet"],"h1":"The same distance applies to a yield sign or a traffic light.","h2":"In Georgia, you may not park within 30 feet of a stop sign, yield sign or traffic light.","p":"Right. Stay at least 30 feet from a stop sign when you park."},"es":{"q":"En Georgia, ¿a qué distancia de una señal de alto no puede estacionarse?","o":["A menos de 10 pies","A menos de 30 pies","A menos de 50 pies","A menos de 100 pies"],"h1":"La misma distancia se aplica a una señal de ceda el paso o un semáforo.","h2":"En Georgia, no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo.","p":"Correcto. Quédese al menos a 30 pies de una señal de alto al estacionarse."},"zh":{"q":"在 Georgia，离停车标志多近的范围内不可以停车？","o":["10 英尺以内","30 英尺以内","50 英尺以内","100 英尺以内"],"h1":"在让行标志或红绿灯附近也是同样的距离。","h2":"在 Georgia，离停车标志、让行标志或红绿灯 30 英尺以内不可以停车。","p":"对。停车时要离停车标志至少 30 英尺。"},"vi":{"q":"Ở Georgia, bạn không được đậu xe trong khoảng cách bao gần biển báo dừng (stop)?","o":["Trong vòng 10 feet","Trong vòng 30 feet","Trong vòng 50 feet","Trong vòng 100 feet"],"h1":"Khoảng cách này cũng áp dụng cho biển nhường đường hoặc đèn giao thông.","h2":"Ở Georgia, bạn không được đậu xe trong vòng 30 feet từ biển báo dừng, biển nhường đường hoặc đèn giao thông.","p":"Đúng. Khi đậu xe, hãy cách biển báo dừng ít nhất 30 feet."},"tl":{"q":"Sa Georgia, gaano kalapit sa stop sign na hindi ka puwedeng pumarada?","o":["Sa loob ng 10 talampakan","Sa loob ng 30 talampakan","Sa loob ng 50 talampakan","Sa loob ng 100 talampakan"],"h1":"Ganito rin ang layo para sa yield sign o traffic light.","h2":"Sa Georgia, hindi ka puwedeng pumarada sa loob ng 30 talampakan mula sa stop sign, yield sign o traffic light.","p":"Tama. Lumayo nang hindi bababa sa 30 talampakan mula sa stop sign kapag pumaparada ka."},"ar":{"q":"في Georgia، على أي مسافة من لافتة التوقف (stop) لا يجوز لك أن تركن سيارتك؟","o":["ضمن 10 أقدام","ضمن 30 قدمًا","ضمن 50 قدمًا","ضمن 100 قدم"],"h1":"المسافة نفسها تنطبق على لافتة إفساح الطريق أو إشارة المرور.","h2":"في Georgia لا يجوز لك أن تركن سيارتك ضمن 30 قدمًا من لافتة التوقف أو لافتة إفساح الطريق أو إشارة المرور.","p":"صحيح. ابقَ على بُعد 30 قدمًا على الأقل من لافتة التوقف عندما تركن."},"ref":{"doc":"GA","page":20}},{"id":"ga-044","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, what fine can a driver get for disobeying the posted speed limit in a work zone?","o":["$10 to $100","$25 to $500","$100 to $2,000","$5,000 to $10,000"],"h1":"It is a serious misdemeanor, and the fine can reach a few thousand dollars.","h2":"In Georgia, speeding against a posted work zone limit can bring a fine of $100 to $2,000, jail of up to 12 months, or both.","p":"Right. The fine is $100 to $2,000."},"es":{"q":"En Georgia, ¿qué multa puede recibir un conductor por no respetar el límite de velocidad en una zona de trabajo?","o":["De $10 a $100","De $25 a $500","De $100 a $2,000","De $5,000 a $10,000"],"h1":"Es un delito menor grave, y la multa puede llegar a unos miles de dólares.","h2":"En Georgia, exceder el límite indicado en una zona de trabajo puede traer una multa de $100 a $2,000, cárcel de hasta 12 meses, o ambas.","p":"Correcto. La multa es de $100 a $2,000."},"zh":{"q":"在 Georgia，司机在施工区不遵守标示的限速，会被罚款多少？","o":["$10 到 $100","$25 到 $500","$100 到 $2,000","$5,000 到 $10,000"],"h1":"这是严重的轻罪，罚款可以达到几千美元。","h2":"在 Georgia，在施工区超过标示的限速，可能被罚款 $100 到 $2,000，或坐牢最多 12 个月，或两者都有。","p":"对。罚款是 $100 到 $2,000。"},"vi":{"q":"Ở Georgia, tài xế có thể bị phạt bao nhiêu tiền nếu không tuân theo tốc độ giới hạn ghi trên biển trong khu vực công trường?","o":["$10 đến $100","$25 đến $500","$100 đến $2,000","$5,000 đến $10,000"],"h1":"Đây là một tội nhẹ nghiêm trọng, và tiền phạt có thể lên đến vài nghìn đô la.","h2":"Ở Georgia, chạy quá tốc độ giới hạn ghi trên biển trong khu vực công trường có thể bị phạt $100 đến $2,000, ngồi tù tối đa 12 tháng, hoặc cả hai.","p":"Đúng. Tiền phạt là $100 đến $2,000."},"tl":{"q":"Sa Georgia, anong multa ang puwedeng makuha ng driver na hindi sumunod sa nakapaskil na speed limit sa work zone?","o":["$10 hanggang $100","$25 hanggang $500","$100 hanggang $2,000","$5,000 hanggang $10,000"],"h1":"Isa itong mabigat na misdemeanor, at puwedeng umabot sa ilang libong dolyar ang multa.","h2":"Sa Georgia, ang pag-overspeed sa nakapaskil na limit sa work zone ay puwedeng magmulta ng $100 hanggang $2,000, makulong nang hanggang 12 buwan, o pareho.","p":"Tama. Ang multa ay $100 hanggang $2,000."},"ar":{"q":"في Georgia، ما الغرامة التي قد يحصل عليها السائق إذا خالف حد السرعة المكتوب في منطقة أعمال الطرق؟","o":["من $10 إلى $100","من $25 إلى $500","من $100 إلى $2,000","من $5,000 إلى $10,000"],"h1":"إنها جنحة خطيرة، والغرامة قد تصل إلى بضعة آلاف من الدولارات.","h2":"في Georgia، تجاوز حد السرعة المكتوب في منطقة أعمال الطرق قد يؤدي إلى غرامة من $100 إلى $2,000، أو السجن حتى 12 شهرًا، أو الاثنين معًا.","p":"صحيح. الغرامة من $100 إلى $2,000."},"ref":{"doc":"GA","page":22}},{"id":"ga-045","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 200 feet","No closer than 50 feet","No closer than 100 feet","No closer than 20 feet"],"h1":"Keep a long gap, about two-thirds of a football field.","h2":"In Georgia, you may not follow a fire truck answering an alarm closer than 200 feet.","p":"Right. Stay at least 200 feet behind a fire truck on a call."},"es":{"q":"En Georgia, un camión de bomberos va a atender una alarma de incendio. ¿A qué distancia detrás de él puede seguirlo?","o":["A no menos de 200 pies","A no menos de 50 pies","A no menos de 100 pies","A no menos de 20 pies"],"h1":"Deje un espacio largo, unos dos tercios de una cancha de fútbol americano.","h2":"En Georgia, no puede seguir a un camión de bomberos que atiende una alarma a menos de 200 pies.","p":"Correcto. Quédese al menos a 200 pies detrás de un camión de bomberos en servicio."},"zh":{"q":"在 Georgia，一辆消防车正赶去处理火警。你跟在它后面可以离多近？","o":["不少于 200 英尺","不少于 50 英尺","不少于 100 英尺","不少于 20 英尺"],"h1":"要保持很长的距离，大约是一个橄榄球场的三分之二。","h2":"在 Georgia，跟在去处理火警的消防车后面，距离不可以少于 200 英尺。","p":"对。跟在出勤的消防车后面，至少要保持 200 英尺。"},"vi":{"q":"Ở Georgia, một xe cứu hỏa đang chạy đến chỗ có báo cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 200 feet","Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 20 feet"],"h1":"Hãy giữ một khoảng cách dài, khoảng hai phần ba sân bóng bầu dục.","h2":"Ở Georgia, bạn không được chạy theo sau xe cứu hỏa đang đi chữa cháy gần hơn 200 feet.","p":"Đúng. Hãy ở cách xe cứu hỏa đang làm nhiệm vụ ít nhất 200 feet."},"tl":{"q":"Sa Georgia, papunta ang isang fire truck sa isang fire alarm. Gaano kalapit ka puwedeng sumunod sa likod nito?","o":["Hindi lalapit sa 200 talampakan","Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan","Hindi lalapit sa 20 talampakan"],"h1":"Panatilihin ang mahabang pagitan, mga dalawang-katlo ng football field.","h2":"Sa Georgia, hindi ka puwedeng sumunod nang mas malapit sa 200 talampakan sa fire truck na rumeresponde sa alarm.","p":"Tama. Manatili nang hindi bababa sa 200 talampakan sa likod ng fire truck na may tawag."},"ar":{"q":"في Georgia، سيارة إطفاء متجهة إلى إنذار حريق. إلى أي مسافة يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 200 قدم","ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","ليس أقرب من 20 قدمًا"],"h1":"اترك مسافة طويلة، حوالي ثلثي ملعب كرة القدم الأمريكية.","h2":"في Georgia لا يجوز لك أن تسير خلف سيارة إطفاء متجهة إلى إنذار على مسافة أقرب من 200 قدم.","p":"صحيح. ابقَ على بُعد 200 قدم على الأقل خلف سيارة الإطفاء في مهمة."},"ref":{"doc":"GA","page":24}},{"id":"ga-046","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, how far before your left turn may you enter the center turn lane?","o":["No more than 50 feet","No more than 100 feet","No more than 1,000 feet","No more than 300 feet"],"h1":"The lane is only for turning, so you may not use it as a long travel lane.","h2":"In Georgia, you may enter a center left-turn lane no more than 300 feet before your turn.","p":"Right. Enter the center turn lane no more than 300 feet before you turn."},"es":{"q":"En Georgia, ¿con cuánta anticipación a su vuelta a la izquierda puede entrar al carril central de vuelta?","o":["No más de 50 pies","No más de 100 pies","No más de 1,000 pies","No más de 300 pies"],"h1":"El carril es solo para dar vuelta, así que no se puede usar como carril para viajar.","h2":"En Georgia, puede entrar al carril central de vuelta a la izquierda no más de 300 pies antes de su vuelta.","p":"Correcto. Entre al carril central no más de 300 pies antes de dar vuelta."},"zh":{"q":"在 Georgia，在你左转之前多远可以开进中间转弯车道？","o":["不超过 50 英尺","不超过 100 英尺","不超过 1,000 英尺","不超过 300 英尺"],"h1":"这条车道只用来转弯，所以你不可以把它当作长距离行驶的车道。","h2":"在 Georgia，你可以在转弯前不超过 300 英尺的地方开进中间左转车道。","p":"对。在转弯前不超过 300 英尺的地方开进中间转弯车道。"},"vi":{"q":"Ở Georgia, trước khi rẽ trái bao xa thì bạn được vào làn rẽ ở giữa đường?","o":["Không quá 50 feet","Không quá 100 feet","Không quá 1,000 feet","Không quá 300 feet"],"h1":"Làn này chỉ dùng để rẽ, nên bạn không được dùng nó như một làn để chạy đường dài.","h2":"Ở Georgia, bạn được vào làn rẽ trái ở giữa đường không quá 300 feet trước chỗ rẽ.","p":"Đúng. Vào làn rẽ ở giữa đường không quá 300 feet trước khi rẽ."},"tl":{"q":"Sa Georgia, gaano kalayo bago ka kumaliwa puwede kang pumasok sa center turn lane?","o":["Hindi hihigit sa 50 talampakan","Hindi hihigit sa 100 talampakan","Hindi hihigit sa 1,000 talampakan","Hindi hihigit sa 300 talampakan"],"h1":"Para lang sa pagliko ang lane na ito, kaya hindi mo ito puwedeng gamitin bilang mahabang lane na dinadaanan.","h2":"Sa Georgia, puwede kang pumasok sa center left-turn lane nang hindi hihigit sa 300 talampakan bago ka lumiko.","p":"Tama. Pumasok sa center turn lane nang hindi hihigit sa 300 talampakan bago ka lumiko."},"ar":{"q":"في Georgia، قبل انعطافك إلى اليسار بكم مسافة يمكنك أن تدخل مسار الانعطاف في وسط الطريق؟","o":["ليس أكثر من 50 قدمًا","ليس أكثر من 100 قدم","ليس أكثر من 1,000 قدم","ليس أكثر من 300 قدم"],"h1":"هذا المسار للانعطاف فقط، لذلك لا يجوز لك استخدامه كمسار للسير مسافة طويلة.","h2":"في Georgia يمكنك أن تدخل مسار الانعطاف إلى اليسار في وسط الطريق قبل انعطافك بمسافة ليست أكثر من 300 قدم.","p":"صحيح. ادخل مسار الانعطاف في الوسط قبل الانعطاف بمسافة ليست أكثر من 300 قدم."},"ref":{"doc":"GA","page":37}},{"id":"ga-047","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, how many points within 24 months will get a driver's license suspended?","o":["10 points","15 points","20 points","25 points"],"h1":"It is more than 10, and the period is two years.","h2":"In Georgia, a license is suspended when the driver gets 15 or more points within 24 months.","p":"Right. 15 points in 24 months means a suspension."},"es":{"q":"En Georgia, ¿cuántos puntos en 24 meses hacen que se suspenda la licencia de un conductor?","o":["10 puntos","15 puntos","20 puntos","25 puntos"],"h1":"Son más de 10, y el período es de dos años.","h2":"En Georgia, se suspende la licencia cuando el conductor acumula 15 puntos o más en 24 meses.","p":"Correcto. 15 puntos en 24 meses significan una suspensión."},"zh":{"q":"在 Georgia，24 个月内累计多少分会被吊销驾照？","o":["10 分","15 分","20 分","25 分"],"h1":"它比 10 分多，而且时间段是两年。","h2":"在 Georgia，司机在 24 个月内累计 15 分或以上，驾照就会被吊销。","p":"对。24 个月内 15 分就会被吊销驾照。"},"vi":{"q":"Ở Georgia, bao nhiêu điểm trong vòng 24 tháng sẽ khiến bằng lái bị đình chỉ?","o":["10 điểm","15 điểm","20 điểm","25 điểm"],"h1":"Nhiều hơn 10, và thời gian là hai năm.","h2":"Ở Georgia, bằng lái bị đình chỉ khi tài xế bị 15 điểm trở lên trong vòng 24 tháng.","p":"Đúng. 15 điểm trong 24 tháng nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Georgia, ilang points sa loob ng 24 na buwan ang magpapa-suspend sa driver's license?","o":["10 points","15 points","20 points","25 points"],"h1":"Higit ito sa 10, at dalawang taon ang panahon.","h2":"Sa Georgia, sinu-suspend ang license kapag nakakuha ang driver ng 15 o higit pang points sa loob ng 24 na buwan.","p":"Tama. Ang 15 points sa loob ng 24 na buwan ay suspension."},"ar":{"q":"في Georgia، كم نقطة خلال 24 شهرًا تؤدي إلى إيقاف رخصة القيادة؟","o":["10 نقاط","15 نقطة","20 نقطة","25 نقطة"],"h1":"العدد أكثر من 10، والمدة سنتان.","h2":"في Georgia تُوقف الرخصة عندما يحصل السائق على 15 نقطة أو أكثر خلال 24 شهرًا.","p":"صحيح. 15 نقطة خلال 24 شهرًا تعني إيقاف الرخصة."},"ref":{"doc":"GA","page":48}},{"id":"ga-048","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, finishing a certified 6-hour defensive driving course can lower the points on your license. By how much, and how often?","o":["Up to 3 points, once a year","Up to 5 points, once every 2 years","Up to 7 points, once every 5 years","All points, as often as you like"],"h1":"You can use it only once in several years.","h2":"In Georgia, a certified 6-hour defensive driving course can remove up to 7 points, once every 5 years.","p":"Right. Up to 7 points, once every 5 years."},"es":{"q":"En Georgia, terminar un curso certificado de manejo defensivo de 6 horas puede bajar los puntos de su licencia. ¿Cuántos y cada cuánto?","o":["Hasta 3 puntos, una vez al año","Hasta 5 puntos, una vez cada 2 años","Hasta 7 puntos, una vez cada 5 años","Todos los puntos, cuantas veces quiera"],"h1":"Solo se puede usar una vez en varios años.","h2":"En Georgia, un curso certificado de manejo defensivo de 6 horas puede quitar hasta 7 puntos, una vez cada 5 años.","p":"Correcto. Hasta 7 puntos, una vez cada 5 años."},"zh":{"q":"在 Georgia，完成一个认证的 6 小时防御性驾驶课程，可以减少驾照上的分数。能减多少分，多久可以用一次？","o":["最多 3 分，每年一次","最多 5 分，每 2 年一次","最多 7 分，每 5 年一次","全部分数，想用几次都可以"],"h1":"几年之内只能用一次。","h2":"在 Georgia，认证的 6 小时防御性驾驶课程最多可以减掉 7 分，每 5 年一次。","p":"对。最多 7 分，每 5 年一次。"},"vi":{"q":"Ở Georgia, hoàn thành một khóa lái xe phòng vệ (defensive driving) 6 giờ được chứng nhận có thể giảm điểm trên bằng lái của bạn. Giảm được bao nhiêu, và bao lâu một lần?","o":["Tối đa 3 điểm, mỗi năm một lần","Tối đa 5 điểm, mỗi 2 năm một lần","Tối đa 7 điểm, mỗi 5 năm một lần","Tất cả số điểm, bao nhiêu lần cũng được"],"h1":"Bạn chỉ có thể dùng nó một lần trong vài năm.","h2":"Ở Georgia, một khóa lái xe phòng vệ 6 giờ được chứng nhận có thể xóa tối đa 7 điểm, mỗi 5 năm một lần.","p":"Đúng. Tối đa 7 điểm, mỗi 5 năm một lần."},"tl":{"q":"Sa Georgia, ang pagtatapos ng certified na 6 na oras na defensive driving course ay puwedeng magbawas ng points sa license mo. Gaano karami, at gaano kadalas?","o":["Hanggang 3 points, isang beses sa isang taon","Hanggang 5 points, isang beses bawat 2 taon","Hanggang 7 points, isang beses bawat 5 taon","Lahat ng points, kahit ilang beses mo gusto"],"h1":"Isang beses mo lang ito magagamit sa loob ng ilang taon.","h2":"Sa Georgia, ang certified na 6 na oras na defensive driving course ay puwedeng mag-alis ng hanggang 7 points, isang beses bawat 5 taon.","p":"Tama. Hanggang 7 points, isang beses bawat 5 taon."},"ar":{"q":"في Georgia، إنهاء دورة قيادة دفاعية معتمدة مدتها 6 ساعات يمكن أن يقلل النقاط على رخصتك. بكم، وكم مرة؟","o":["حتى 3 نقاط، مرة كل سنة","حتى 5 نقاط، مرة كل سنتين (2)","حتى 7 نقاط، مرة كل 5 سنوات","كل النقاط، كلما أردت"],"h1":"يمكنك استخدامها مرة واحدة فقط في عدة سنوات.","h2":"في Georgia، دورة القيادة الدفاعية المعتمدة لمدة 6 ساعات يمكن أن تزيل حتى 7 نقاط، مرة كل 5 سنوات.","p":"صحيح. حتى 7 نقاط، مرة كل 5 سنوات."},"ref":{"doc":"GA","page":48}},{"id":"ga-049","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many points does a conviction for speeding 24 to 33 mph over the limit add to your record?","o":["4 points","1 point","2 points","6 points"],"h1":"It is fewer than for speeding 34 mph or more over the limit.","h2":"In Georgia, speeding 24 to 33 mph over the posted limit adds 4 points to your record.","p":"Right. Speeding 24 to 33 mph over the limit is 4 points."},"es":{"q":"En Georgia, ¿cuántos puntos agrega a su historial una condena por exceder el límite de 24 a 33 mph?","o":["4 puntos","1 punto","2 puntos","6 puntos"],"h1":"Son menos que por exceder el límite por 34 mph o más.","h2":"En Georgia, exceder el límite por 24 a 33 mph agrega 4 puntos a su historial.","p":"Correcto. Exceder el límite por 24 a 33 mph son 4 puntos."},"zh":{"q":"在 Georgia，因超速 24 到 33 mph 被定罪，会在你的记录上加多少分？","o":["4 分","1 分","2 分","6 分"],"h1":"它比超速 34 mph 或以上的分数少。","h2":"在 Georgia，超过标示限速 24 到 33 mph，会在你的记录上加 4 分。","p":"对。超速 24 到 33 mph 是 4 分。"},"vi":{"q":"Ở Georgia, bị kết tội chạy quá tốc độ giới hạn từ 24 đến 33 mph sẽ bị cộng bao nhiêu điểm vào hồ sơ của bạn?","o":["4 điểm","1 điểm","2 điểm","6 điểm"],"h1":"Ít hơn so với chạy quá tốc độ từ 34 mph trở lên.","h2":"Ở Georgia, chạy quá tốc độ giới hạn ghi trên biển từ 24 đến 33 mph sẽ bị cộng 4 điểm vào hồ sơ của bạn.","p":"Đúng. Chạy quá tốc độ giới hạn từ 24 đến 33 mph là 4 điểm."},"tl":{"q":"Sa Georgia, ilang points ang idinadagdag sa record mo ng conviction sa pag-overspeed nang 24 hanggang 33 mph lampas sa limit?","o":["4 na points","1 point","2 points","6 na points"],"h1":"Mas kaunti ito kaysa sa pag-overspeed nang 34 mph o higit pa lampas sa limit.","h2":"Sa Georgia, ang pag-overspeed nang 24 hanggang 33 mph lampas sa nakapaskil na limit ay nagdadagdag ng 4 na points sa record mo.","p":"Tama. Ang pag-overspeed nang 24 hanggang 33 mph lampas sa limit ay 4 na points."},"ar":{"q":"في Georgia، كم نقطة تضيف إلى سجلك إدانةٌ بتجاوز حد السرعة بـ 24 إلى 33 mph؟","o":["4 نقاط","نقطة واحدة (1)","نقطتان (2)","6 نقاط"],"h1":"العدد أقل من نقاط تجاوز الحد بـ 34 mph أو أكثر.","h2":"في Georgia، تجاوز حد السرعة المكتوب بـ 24 إلى 33 mph يضيف 4 نقاط إلى سجلك.","p":"صحيح. تجاوز الحد بـ 24 إلى 33 mph يعني 4 نقاط."},"ref":{"doc":"GA","page":47}},{"id":"ga-050","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a driver refuses the state's test for alcohol or drugs. What happens to the license?","o":["Nothing, if the driver was not arrested","A $50 fine and no suspension","A 30-day suspension","A suspension of at least one year"],"h1":"Under implied consent, refusing has a long penalty.","h2":"In Georgia, refusing the state's chemical test brings a license suspension of at least one year.","p":"Right. Refusing the test means a suspension of at least one year."},"es":{"q":"En Georgia, un conductor se niega a la prueba estatal de alcohol o drogas. ¿Qué le pasa a la licencia?","o":["Nada, si no lo arrestaron","Una multa de $50 sin suspensión","Una suspensión de 30 días","Una suspensión de al menos un año"],"h1":"Bajo el consentimiento implícito, negarse tiene una sanción larga.","h2":"En Georgia, negarse a la prueba química del estado trae una suspensión de la licencia de al menos un año.","p":"Correcto. Negarse a la prueba significa una suspensión de al menos un año."},"zh":{"q":"在 Georgia，一名司机拒绝州政府的酒精或毒品检测。驾照会怎么样？","o":["如果司机没有被逮捕，什么事都没有","罚款 $50，不吊销驾照","吊销驾照 30 天","吊销驾照至少一年"],"h1":"根据默示同意法，拒绝检测的处罚很长。","h2":"在 Georgia，拒绝州政府的化学检测，驾照会被吊销至少一年。","p":"对。拒绝检测就会被吊销驾照至少一年。"},"vi":{"q":"Ở Georgia, một tài xế từ chối bài kiểm tra rượu bia hoặc ma túy của tiểu bang. Điều gì xảy ra với bằng lái?","o":["Không có gì, nếu tài xế không bị bắt","Phạt $50 và không bị đình chỉ","Bị đình chỉ 30 ngày","Bị đình chỉ ít nhất một năm"],"h1":"Theo luật đồng ý ngầm (implied consent), từ chối sẽ bị phạt trong thời gian dài.","h2":"Ở Georgia, từ chối bài kiểm tra hóa học của tiểu bang sẽ bị đình chỉ bằng lái ít nhất một năm.","p":"Đúng. Từ chối kiểm tra nghĩa là bị đình chỉ bằng lái ít nhất một năm."},"tl":{"q":"Sa Georgia, tumanggi ang isang driver sa test ng estado para sa alak o droga. Ano ang mangyayari sa license?","o":["Wala, kung hindi inaresto ang driver","Multang $50 at walang suspension","Suspension nang 30 araw","Suspension nang hindi bababa sa isang taon"],"h1":"Sa ilalim ng implied consent, mahaba ang parusa sa pagtanggi.","h2":"Sa Georgia, ang pagtanggi sa chemical test ng estado ay may license suspension na hindi bababa sa isang taon.","p":"Tama. Ang pagtanggi sa test ay suspension nang hindi bababa sa isang taon."},"ar":{"q":"في Georgia، رفض سائق اختبار الولاية للكحول أو المخدرات. ماذا يحدث للرخصة؟","o":["لا شيء، إذا لم يُعتقل السائق","غرامة $50 دون إيقاف","إيقاف لمدة 30 يومًا","إيقاف لمدة سنة واحدة على الأقل"],"h1":"بموجب قانون الموافقة الضمنية (implied consent)، عقوبة الرفض طويلة.","h2":"في Georgia، رفض الاختبار الكيميائي للولاية يؤدي إلى إيقاف الرخصة لمدة سنة واحدة على الأقل.","p":"صحيح. رفض الاختبار يعني إيقاف الرخصة لمدة سنة واحدة على الأقل."},"ref":{"doc":"GA","page":47}},{"id":"ga-051","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, you have a crash and no one is hurt. When must you report it to the police right away?","o":["Only if a car must be towed","When the damage is more than $500","Only if the other driver asks you to","When the damage is more than $5,000"],"h1":"It depends on the dollar amount of the damage.","h2":"In Georgia, you must notify the police right away when anyone is hurt or killed, or when property damage is more than $500.","p":"Right. Report it when damage is more than $500."},"es":{"q":"En Georgia, tiene un choque y nadie está herido. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si hay que remolcar un auto","Cuando el daño es de más de $500","Solo si el otro conductor se lo pide","Cuando el daño es de más de $5,000"],"h1":"Depende de cuánto dinero cuesta el daño.","h2":"En Georgia, debe avisar a la policía de inmediato cuando alguien resulta herido o muerto, o cuando el daño a la propiedad es de más de $500.","p":"Correcto. Repórtelo cuando el daño sea de más de $500."},"zh":{"q":"在 Georgia，你出了车祸，没有人受伤。什么情况下你必须马上报警？","o":["只有车子必须被拖走时","损失超过 $500 时","只有对方司机要求你时","损失超过 $5,000 时"],"h1":"这取决于损失的金额。","h2":"在 Georgia，有人受伤或死亡，或者财产损失超过 $500 时，你必须马上报警。","p":"对。损失超过 $500 时就要报警。"},"vi":{"q":"Ở Georgia, bạn bị tai nạn và không ai bị thương. Khi nào bạn phải báo cho cảnh sát ngay?","o":["Chỉ khi một xe phải bị kéo đi","Khi thiệt hại hơn $500","Chỉ khi tài xế kia yêu cầu bạn","Khi thiệt hại hơn $5,000"],"h1":"Điều này tùy vào số tiền thiệt hại.","h2":"Ở Georgia, bạn phải báo cho cảnh sát ngay khi có người bị thương hoặc chết, hoặc khi thiệt hại tài sản hơn $500.","p":"Đúng. Hãy báo cảnh sát khi thiệt hại hơn $500."},"tl":{"q":"Sa Georgia, naaksidente ka at walang nasaktan. Kailan mo dapat iulat agad ito sa pulis?","o":["Kung kailangan lang hilahin ang kotse","Kapag ang pinsala ay higit sa $500","Kung hilingin lang ito ng ibang driver","Kapag ang pinsala ay higit sa $5,000"],"h1":"Nakadepende ito sa halaga ng pinsala sa dolyar.","h2":"Sa Georgia, dapat mong ipaalam agad sa pulis kapag may nasaktan o namatay, o kapag ang pinsala sa ari-arian ay higit sa $500.","p":"Tama. Iulat ito kapag ang pinsala ay higit sa $500."},"ar":{"q":"في Georgia، تعرّضت لحادث ولم يُصب أحد. متى يجب أن تبلّغ الشرطة فورًا؟","o":["فقط إذا كان يجب سحب سيارة","عندما يكون الضرر أكثر من $500","فقط إذا طلب منك السائق الآخر ذلك","عندما يكون الضرر أكثر من $5,000"],"h1":"يعتمد ذلك على قيمة الضرر بالدولار.","h2":"في Georgia يجب أن تبلّغ الشرطة فورًا عندما يُصاب أحد أو يموت، أو عندما يكون الضرر في الممتلكات أكثر من $500.","p":"صحيح. بلّغ الشرطة عندما يكون الضرر أكثر من $500."},"ref":{"doc":"GA","page":50}},{"id":"ga-052","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how often must a driver age 64 or older pass a vision screening?","o":["Every year","Every 4 years","Every 8 years","Only once, at age 64"],"h1":"It matches the length of a regular license term.","h2":"In Georgia, drivers age 64 and older must pass a vision screening every 8 years.","p":"Right. Age 64 and older: a vision screening every 8 years."},"es":{"q":"En Georgia, ¿cada cuánto debe pasar un examen de la vista un conductor de 64 años o más?","o":["Cada año","Cada 4 años","Cada 8 años","Solo una vez, a los 64 años"],"h1":"Coincide con la duración de una licencia normal.","h2":"En Georgia, los conductores de 64 años o más deben pasar un examen de la vista cada 8 años.","p":"Correcto. Con 64 años o más: un examen de la vista cada 8 años."},"ref":{"doc":"GA","page":5}},{"id":"ga-053","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, a driver's license has a bioptic lenses restriction. How often must the driver give DDS updated medical information?","o":["Every 2 years","Every 5 years","Every 8 years","Never, once is enough"],"h1":"It is more often than the license is renewed.","h2":"In Georgia, a driver with a bioptic lenses restriction must give DDS updated medical information every 2 years.","p":"Right. Bioptic lenses: new medical information every 2 years."},"es":{"q":"En Georgia, una licencia tiene la restricción de lentes biópticos. ¿Cada cuánto debe el conductor dar a DDS información médica actualizada?","o":["Cada 2 años","Cada 5 años","Cada 8 años","Nunca, basta con una vez"],"h1":"Es más seguido que la renovación de la licencia.","h2":"En Georgia, un conductor con la restricción de lentes biópticos debe dar a DDS información médica actualizada cada 2 años.","p":"Correcto. Lentes biópticos: nueva información médica cada 2 años."},"ref":{"doc":"GA","page":5}},{"id":"ga-054","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, do you need a Class M motorcycle license to drive a three-wheel autocycle that has a steering wheel?","o":["Yes, always a Class M license","Yes, plus a motorcycle permit first","Only if it goes over 35 mph","No, a Class M license is not needed"],"h1":"An autocycle has a steering wheel, not handlebars.","h2":"In Georgia, a three-wheel autocycle with a steering wheel does not need a Class M motorcycle license.","p":"Right. An autocycle does not need a Class M license."},"es":{"q":"En Georgia, ¿necesita una licencia de motocicleta Clase M para manejar un autociclo de tres ruedas que tiene volante?","o":["Sí, siempre una licencia Clase M","Sí, y antes un permiso de motocicleta","Solo si pasa de 35 mph","No, no necesita una licencia Clase M"],"h1":"Un autociclo tiene volante, no manubrio.","h2":"En Georgia, un autociclo de tres ruedas con volante no necesita una licencia de motocicleta Clase M.","p":"Correcto. Un autociclo no necesita licencia Clase M."},"ref":{"doc":"GA","page":5}},{"id":"ga-055","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, for a Real ID you bring two documents that show where you live. How recent must they be?","o":["Dated within the last 30 days","Dated within the last 6 months","Dated within the last 2 years","Any date is fine"],"h1":"Think of a recent utility or phone bill.","h2":"In Georgia, the two documents that show your Georgia address for a Real ID must be dated within the last 6 months.","p":"Right. Proof of address must be from the last 6 months."},"es":{"q":"En Georgia, para una Real ID usted lleva dos documentos que muestran dónde vive. ¿Qué tan recientes deben ser?","o":["Con fecha de los últimos 30 días","Con fecha de los últimos 6 meses","Con fecha de los últimos 2 años","Cualquier fecha sirve"],"h1":"Piense en una factura reciente de luz o de teléfono.","h2":"En Georgia, los dos documentos que muestran su domicilio en Georgia para una Real ID deben tener fecha de los últimos 6 meses.","p":"Correcto. El comprobante de domicilio debe ser de los últimos 6 meses."},"ref":{"doc":"GA","page":6}},{"id":"ga-056","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, a parent signed a teen's permit application. What can that parent do until the teen turns 18?","o":["Nothing; the permit cannot be taken back","Ask DDS to revoke it, for any reason","Cancel it only if the teen gets a ticket","Cancel it only with a judge's order"],"h1":"The person who gave consent can also take it back.","h2":"In Georgia, the person who signed a teen's application may have the permit or license revoked, for any reason, until the teen turns 18.","p":"Right. The signer can revoke it for any reason until 18."},"es":{"q":"En Georgia, un padre firmó la solicitud del permiso de un adolescente. ¿Qué puede hacer ese padre hasta que el adolescente cumpla 18 años?","o":["Nada; el permiso no se puede quitar","Pedir a DDS que lo revoque, por cualquier motivo","Cancelarlo solo si el adolescente recibe una multa","Cancelarlo solo con orden de un juez"],"h1":"Quien dio su permiso también puede retirarlo.","h2":"En Georgia, la persona que firmó la solicitud de un adolescente puede pedir que se revoque el permiso o la licencia, por cualquier motivo, hasta que el adolescente cumpla 18 años.","p":"Correcto. Quien firmó puede revocarlo por cualquier motivo hasta los 18."},"ref":{"doc":"GA","page":8}},{"id":"ga-057","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, besides driver education, what program must a teen finish before getting a Class D license?","o":["A motorcycle safety course","The Alcohol and Drug Awareness Program (ADAP)","A first aid and CPR class","A defensive driving course for points"],"h1":"It is taught in most schools and is also online.","h2":"In Georgia, a teen must finish the Alcohol and Drug Awareness Program (ADAP) before getting a Class D license.","p":"Right. ADAP is required for a Class D license."},"es":{"q":"En Georgia, además de la educación vial, ¿qué programa debe terminar un adolescente antes de recibir una licencia Clase D?","o":["Un curso de seguridad en motocicleta","El Programa de Concientización sobre Alcohol y Drogas (ADAP)","Una clase de primeros auxilios y RCP","Un curso de manejo defensivo para puntos"],"h1":"Se enseña en la mayoría de las escuelas y también en línea.","h2":"En Georgia, un adolescente debe terminar el Programa de Concientización sobre Alcohol y Drogas (ADAP) antes de recibir una licencia Clase D.","p":"Correcto. ADAP es obligatorio para la licencia Clase D."},"ref":{"doc":"GA","page":8}},{"id":"ga-058","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you got your Class D license two months ago. Your cousin, who lives in your home, wants a ride. May the cousin ride with you?","o":["Yes, people living in your home count as family","No, only passengers over 21 may ride","Only if a licensed adult also rides","No, only parents and siblings may ride"],"h1":"Look at how Georgia defines immediate family.","h2":"In Georgia, immediate family for a Class D driver includes any person who lives at the driver's home, so the cousin may ride.","p":"Right. Anyone living in your home counts as immediate family."},"es":{"q":"En Georgia, recibió su licencia Clase D hace dos meses. Su primo, que vive en su casa, quiere que lo lleve. ¿Puede ir con usted?","o":["Sí, quienes viven en su casa cuentan como familia","No, solo pasajeros mayores de 21 años","Solo si también va un adulto con licencia","No, solo pueden ir los padres y hermanos"],"h1":"Fíjese en cómo define Georgia a la familia inmediata.","h2":"En Georgia, la familia inmediata de un conductor Clase D incluye a cualquier persona que vive en su casa, así que el primo puede ir con usted.","p":"Correcto. Quien vive en su casa cuenta como familia inmediata."},"ref":{"doc":"GA","page":8}},{"id":"ga-059","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, you have a Class D license. Your work shift ends at 12:30 a.m. May you drive yourself home?","o":["Yes, driving home from work is allowed","No, not between 12 a.m. and 5 a.m.","Yes, if a parent signs a note","Yes, if you have no passengers"],"h1":"The Class D night rule has no exceptions.","h2":"In Georgia, a Class D driver may not drive between 12:00 a.m. and 5:00 a.m., with no exceptions, not even for work.","p":"Right. No Class D driving from midnight to 5 a.m."},"es":{"q":"En Georgia, usted tiene licencia Clase D. Su turno de trabajo termina a las 12:30 a.m. ¿Puede manejar a su casa?","o":["Sí, se permite manejar del trabajo a casa","No, no entre las 12 a.m. y las 5 a.m.","Sí, si un padre firma una nota","Sí, si no lleva pasajeros"],"h1":"La regla nocturna de la Clase D no tiene excepciones.","h2":"En Georgia, un conductor Clase D no puede manejar entre las 12:00 a.m. y las 5:00 a.m., sin excepciones, ni siquiera por trabajo.","p":"Correcto. Nada de manejar con Clase D de medianoche a 5 a.m."},"ref":{"doc":"GA","page":8}},{"id":"ga-060","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, a Class D driver turns 18 and wants a Class C license. What must their record show for the past 12 months?","o":["At least 100 hours of driving","A finished defensive driving course","No convictions for major traffic violations","No parking tickets"],"h1":"Serious offenses that bring a suspension matter here.","h2":"In Georgia, a Class D driver needs 12 months free of convictions for major traffic violations before getting a Class C license.","p":"Right. No major traffic convictions in the last 12 months."},"es":{"q":"En Georgia, un conductor Clase D cumple 18 años y quiere una licencia Clase C. ¿Qué debe mostrar su historial de los últimos 12 meses?","o":["Al menos 100 horas de manejo","Un curso de manejo defensivo terminado","Ninguna condena por infracciones graves de tránsito","Ninguna multa de estacionamiento"],"h1":"Aquí importan las faltas graves que causan suspensión.","h2":"En Georgia, un conductor Clase D necesita 12 meses sin condenas por infracciones graves de tránsito antes de recibir una licencia Clase C.","p":"Correcto. Ninguna condena grave de tránsito en los últimos 12 meses."},"ref":{"doc":"GA","page":8}},{"id":"ga-061","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, you are 18 or older and apply for a Class C license without first getting a permit. What must you sign?","o":["That a parent agrees to your license","That you took a 30-hour driver education class","That you drove 40 supervised hours, 6 of them at night","Nothing; adults sign no affidavit"],"h1":"Adults sign about the same hours that teens need.","h2":"In Georgia, an adult who applies straight for a Class C license must sign that they completed 40 hours of supervised driving, including 6 at night.","p":"Right. 40 supervised hours, 6 at night, even for adults."},"es":{"q":"En Georgia, usted tiene 18 años o más y pide una licencia Clase C sin sacar antes un permiso. ¿Qué debe firmar?","o":["Que un padre está de acuerdo con su licencia","Que tomó una clase de educación vial de 30 horas","Que manejó 40 horas supervisadas, 6 de noche","Nada; los adultos no firman declaración"],"h1":"Los adultos firman sobre las mismas horas que necesitan los adolescentes.","h2":"En Georgia, un adulto que pide directamente una licencia Clase C debe firmar que completó 40 horas de manejo supervisado, incluidas 6 de noche.","p":"Correcto. 40 horas supervisadas, 6 de noche, también para adultos."},"ref":{"doc":"GA","page":9}},{"id":"ga-062","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a 17-year-old has enlisted in the military. What rule about the learner's permit can they skip?","o":["The vision test at the DDS center","The knowledge test on signs and rules","The road test with an examiner","Holding the permit for one year and one day"],"h1":"They still must pass the road test.","h2":"In Georgia, a 17-year-old with proof of military enlistment does not have to hold the permit for one year and one day.","p":"Right. Enlisted 17-year-olds skip the one year and one day wait."},"es":{"q":"En Georgia, un joven de 17 años se alistó en el ejército. ¿Qué regla del permiso de aprendiz puede saltarse?","o":["El examen de la vista en el centro de DDS","El examen de conocimientos de señales y reglas","El examen de manejo con un examinador","Tener el permiso por un año y un día"],"h1":"Igual debe pasar el examen de manejo.","h2":"En Georgia, un joven de 17 años con prueba de alistamiento militar no tiene que tener el permiso por un año y un día.","p":"Correcto. Los alistados de 17 años se saltan la espera de un año y un día."},"ref":{"doc":"GA","page":8}},{"id":"ga-063","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, which veterans may get a free veteran's license?","o":["Georgia veterans released with any discharge except dishonorable","Only veterans with a combat injury","Only veterans older than 65","Any veteran from any state, even a dishonorable discharge"],"h1":"Only one kind of discharge is left out.","h2":"In Georgia, veterans who live in Georgia, served on active duty and were released with any discharge other than dishonorable may get a free veteran's license.","p":"Right. Any discharge except dishonorable qualifies."},"es":{"q":"En Georgia, ¿qué veteranos pueden recibir una licencia de veterano gratis?","o":["Veteranos de Georgia con cualquier baja excepto deshonrosa","Solo veteranos heridos en combate","Solo veteranos mayores de 65 años","Cualquier veterano de cualquier estado, incluso con baja deshonrosa"],"h1":"Solo se excluye un tipo de baja.","h2":"En Georgia, los veteranos que viven en Georgia, sirvieron en servicio activo y recibieron cualquier baja que no sea deshonrosa pueden recibir una licencia de veterano gratis.","p":"Correcto. Sirve cualquier baja excepto la deshonrosa."},"ref":{"doc":"GA","page":10}},{"id":"ga-064","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you are 25 and move here with a valid license from another state. Which test must you pass to get a Georgia license?","o":["The knowledge test and the road test","Only the road test","Only the road signs test","Only a vision test"],"h1":"You turn in your old license and show your documents.","h2":"In Georgia, an adult with a valid license from another state turns it in, shows the required documents and passes a vision test.","p":"Right. Only a vision test is needed for the transfer."},"es":{"q":"En Georgia, usted tiene 25 años y se muda aquí con una licencia válida de otro estado. ¿Qué examen debe pasar para recibir una licencia de Georgia?","o":["El examen de conocimientos y el de manejo","Solo el examen de manejo","Solo el examen de señales","Solo un examen de la vista"],"h1":"Usted entrega su licencia anterior y muestra sus documentos.","h2":"En Georgia, un adulto con licencia válida de otro estado la entrega, muestra los documentos requeridos y pasa un examen de la vista.","p":"Correcto. Para el cambio solo se necesita un examen de la vista."},"ref":{"doc":"GA","page":11}},{"id":"ga-065","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, the knowledge exam is given on a walk-in basis. When must you start it?","o":["At least 30 minutes before the center closes","At least 2 hours before the center closes","Only in the morning","Only on Tuesdays"],"h1":"You need enough time to finish before closing.","h2":"In Georgia, you must begin the knowledge exam at least 30 minutes before the DDS center closes.","p":"Right. Start at least 30 minutes before closing."},"es":{"q":"En Georgia, el examen de conocimientos se da sin cita. ¿Cuándo debe empezarlo?","o":["Al menos 30 minutos antes de que cierre el centro","Al menos 2 horas antes de que cierre el centro","Solo por la mañana","Solo los martes"],"h1":"Necesita tiempo suficiente para terminar antes del cierre.","h2":"En Georgia, debe empezar el examen de conocimientos al menos 30 minutos antes de que cierre el centro de DDS.","p":"Correcto. Empiece al menos 30 minutos antes del cierre."},"ref":{"doc":"GA","page":12}},{"id":"ga-066","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, during the knowledge exam, you talk to a friend in the room. What happens?","o":["You get a warning and keep going","You lose 5 points","The exam counts as a failure","You must start over the same day"],"h1":"Talking to anyone but the examiner is misconduct.","h2":"In Georgia, talking to anyone other than the examiner during the knowledge exam is misconduct, and the exam is counted as a failure.","p":"Right. Misconduct means the exam counts as failed."},"es":{"q":"En Georgia, durante el examen de conocimientos, usted habla con un amigo en la sala. ¿Qué pasa?","o":["Recibe una advertencia y sigue","Pierde 5 puntos","El examen cuenta como reprobado","Debe empezar de nuevo el mismo día"],"h1":"Hablar con alguien que no sea el examinador es mala conducta.","h2":"En Georgia, hablar con alguien que no sea el examinador durante el examen de conocimientos es mala conducta, y el examen cuenta como reprobado.","p":"Correcto. La mala conducta hace que el examen cuente como reprobado."},"ref":{"doc":"GA","page":12}},{"id":"ga-067","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, the road rules part of the knowledge exam has 20 questions. How many must you answer correctly?","o":["12","15","18","20"],"h1":"It is three out of every four.","h2":"In Georgia, you must answer 15 of the 20 road rules questions correctly to pass that part.","p":"Right. 15 out of 20 to pass."},"es":{"q":"En Georgia, la parte de reglas de tránsito del examen de conocimientos tiene 20 preguntas. ¿Cuántas debe contestar bien?","o":["12","15","18","20"],"h1":"Son tres de cada cuatro.","h2":"En Georgia, debe contestar bien 15 de las 20 preguntas de reglas de tránsito para aprobar esa parte.","p":"Correcto. 15 de 20 para aprobar."},"ref":{"doc":"GA","page":12}},{"id":"ga-068","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, you take a virtual road test. Who must ride in the car with you?","o":["A DDS examiner in the front seat","Nobody; you must drive alone","A licensed adult age 21 or older","Any licensed friend age 16 or older"],"h1":"The examiner watches from far away by camera.","h2":"In Georgia, during a virtual road test, a parent, guardian or other responsible adult age 21 or older with a valid license must ride as a passenger.","p":"Right. A licensed adult 21 or older rides along."},"es":{"q":"En Georgia, usted toma un examen de manejo virtual. ¿Quién debe ir en el carro con usted?","o":["Un examinador de DDS en el asiento delantero","Nadie; debe manejar solo","Un adulto de 21 años o más con licencia","Cualquier amigo con licencia de 16 años o más"],"h1":"El examinador lo observa a distancia por cámara.","h2":"En Georgia, durante un examen de manejo virtual, un padre, tutor u otro adulto responsable de 21 años o más con licencia válida debe ir como pasajero.","p":"Correcto. Va un adulto de 21 años o más con licencia."},"ref":{"doc":"GA","page":12}},{"id":"ga-069","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you fail the Class C road test for the first time. When may you take it again?","o":["The next day","After 7 days","After 30 days","After 6 months"],"h1":"The wait is longer only after a second failure.","h2":"In Georgia, after a first failure of the knowledge or road test, you must wait until the next day to try that part again.","p":"Right. After a first failure, wait until the next day."},"es":{"q":"En Georgia, usted reprueba por primera vez el examen de manejo Clase C. ¿Cuándo puede tomarlo de nuevo?","o":["Al día siguiente","Después de 7 días","Después de 30 días","Después de 6 meses"],"h1":"La espera es más larga solo después de reprobar por segunda vez.","h2":"En Georgia, después de reprobar por primera vez el examen de conocimientos o de manejo, debe esperar hasta el día siguiente para intentar esa parte otra vez.","p":"Correcto. Después de reprobar la primera vez, espere al día siguiente."},"ref":{"doc":"GA","page":13}},{"id":"ga-070","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, who may renew a driver's license by mail?","o":["Anyone whose license expired 3 years ago","A full-time student going to school outside Georgia","Any driver between 18 and 21","Any driver who wants a Real ID"],"h1":"It is for people who must be away from the state.","h2":"In Georgia, renewal by mail is offered to people away from the state, such as full-time students at school outside Georgia and military members stationed out of state.","p":"Right. Out-of-state students can renew by mail."},"es":{"q":"En Georgia, ¿quién puede renovar la licencia de manejo por correo?","o":["Cualquiera cuya licencia venció hace 3 años","Un estudiante de tiempo completo que estudia fuera de Georgia","Cualquier conductor de 18 a 21 años","Cualquier conductor que quiera una Real ID"],"h1":"Es para personas que deben estar fuera del estado.","h2":"En Georgia, la renovación por correo se ofrece a personas fuera del estado, como estudiantes de tiempo completo que estudian fuera de Georgia y militares destinados fuera del estado.","p":"Correcto. Los estudiantes fuera del estado pueden renovar por correo."},"ref":{"doc":"GA","page":14}},{"id":"ga-071","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you got married and changed your last name. How must you change the name on your license?","o":["Online at the DDS website","By calling DDS on the phone","By mailing a letter to DDS","In person at a DDS center"],"h1":"An address can be changed online, but a name cannot.","h2":"In Georgia, a name change on a license must be done in person at a DDS Customer Service Center.","p":"Right. Name changes are done in person."},"es":{"q":"En Georgia, usted se casó y cambió su apellido. ¿Cómo debe cambiar el nombre en su licencia?","o":["En línea en el sitio de DDS","Llamando por teléfono a DDS","Enviando una carta por correo a DDS","En persona en un centro de DDS"],"h1":"La dirección se puede cambiar en línea, pero el nombre no.","h2":"En Georgia, el cambio de nombre en la licencia se debe hacer en persona en un Centro de Servicio al Cliente de DDS.","p":"Correcto. El cambio de nombre se hace en persona."},"ref":{"doc":"GA","page":16}},{"id":"ga-072","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, what do you need in your car to use a toll Express Lane, such as the I-85 Express Lanes?","o":["Exact change for a toll booth","A printed ticket from the entrance","A registered Peach Pass mounted in the car","Nothing; the lanes are free for everyone"],"h1":"It is a small device that pays the toll automatically.","h2":"In Georgia, tolled Express Lanes require a registered Peach Pass transponder mounted in the vehicle.","p":"Right. You need a registered Peach Pass."},"es":{"q":"En Georgia, ¿qué necesita en su carro para usar un carril Express de peaje, como los carriles Express de la I-85?","o":["Cambio exacto para una caseta de peaje","Un boleto impreso en la entrada","Un Peach Pass registrado y colocado en el carro","Nada; los carriles son gratis para todos"],"h1":"Es un aparato pequeño que paga el peaje automáticamente.","h2":"En Georgia, los carriles Express de peaje requieren un transpondedor Peach Pass registrado y colocado en el vehículo.","p":"Correcto. Necesita un Peach Pass registrado."},"ref":{"doc":"GA","page":23}},{"id":"ga-073","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, what is the highest fine for a first offense of breaking the HOV lane rules?","o":["$75","$250","$500","$1,000"],"h1":"It is the smallest amount in the list.","h2":"In Georgia, a first violation of HOV lane rules can bring a fine of up to $75.","p":"Right. Up to $75 for a first HOV offense."},"es":{"q":"En Georgia, ¿cuál es la multa más alta por una primera falta a las reglas del carril HOV?","o":["$75","$250","$500","$1,000"],"h1":"Es la cantidad más baja de la lista.","h2":"En Georgia, una primera falta a las reglas del carril HOV puede tener una multa de hasta $75.","p":"Correcto. Hasta $75 por una primera falta en el carril HOV."},"ref":{"doc":"GA","page":40}},{"id":"ga-074","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you live in one of the 13 metro Atlanta counties and own a 10-year-old gasoline car. How often must it pass an emissions inspection?","o":["Only when you sell the car","Every 5 years, at renewal","Every 2 years, in the spring","Every year, before you register it"],"h1":"It is tied to registering the car.","h2":"In Georgia, in the 13 metro Atlanta counties, gasoline cars and light trucks less than 25 model years old must pass an emissions inspection every year before registration; the newest 3 model years are exempt.","p":"Right. An emissions test every year before registration."},"es":{"q":"En Georgia, usted vive en uno de los 13 condados del área metropolitana de Atlanta y tiene un carro de gasolina de 10 años. ¿Cada cuánto debe pasar una inspección de emisiones?","o":["Solo cuando vende el carro","Cada 5 años, al renovar","Cada 2 años, en primavera","Cada año, antes de registrarlo"],"h1":"Está ligado al registro del carro.","h2":"En Georgia, en los 13 condados del área metropolitana de Atlanta, los carros y camionetas de gasolina de menos de 25 años de modelo deben pasar una inspección de emisiones cada año antes del registro; los 3 modelos más nuevos están exentos.","p":"Correcto. Una prueba de emisiones cada año antes del registro."},"ref":{"doc":"GA","page":41}},{"id":"ga-075","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a driver under 18 gets 4 points within 12 months. What happens?","o":["Nothing until 15 points","A required eye test","A warning letter only","The license is suspended"],"h1":"Teens have a much lower point limit than adults.","h2":"In Georgia, a driver under 18 who gets 4 or more points within 12 months has the license suspended.","p":"Right. Under 18, 4 points in 12 months means a suspension."},"es":{"q":"En Georgia, un conductor menor de 18 años acumula 4 puntos en 12 meses. ¿Qué pasa?","o":["Nada hasta los 15 puntos","Un examen de la vista obligatorio","Solo una carta de advertencia","Se suspende la licencia"],"h1":"Los adolescentes tienen un límite de puntos mucho más bajo que los adultos.","h2":"En Georgia, a un conductor menor de 18 años que acumula 4 puntos o más en 12 meses se le suspende la licencia.","p":"Correcto. Menor de 18, 4 puntos en 12 meses significan suspensión."},"ref":{"doc":"GA","page":48}},{"id":"ga-076","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, a 19-year-old is convicted for the first time of leaving the scene of a crash. How long is the license suspended?","o":["30 days","3 months","6 months","5 years"],"h1":"A second conviction doubles it to twelve months.","h2":"In Georgia, a driver under 21 convicted of hit and run for the first time has the license suspended for 6 months.","p":"Right. Six months for a first conviction under 21."},"es":{"q":"En Georgia, un joven de 19 años es condenado por primera vez por irse del lugar de un choque. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","3 meses","6 meses","5 años"],"h1":"Una segunda condena lo duplica a doce meses.","h2":"En Georgia, a un conductor menor de 21 años condenado por primera vez por huir de un choque se le suspende la licencia por 6 meses.","p":"Correcto. Seis meses por una primera condena antes de los 21."},"ref":{"doc":"GA","page":27}},{"id":"ga-077","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, a driver under 21 has a first DUI with a blood alcohol level of 0.08 or more. What is the shortest suspension?","o":["12 months","30 days","3 months","6 months"],"h1":"It is longer than for a level between 0.02 and 0.08.","h2":"In Georgia, a driver under 21 with a first DUI at 0.08 or more, or who refused testing, is suspended for at least 12 months.","p":"Right. At least 12 months, with no limited permit."},"es":{"q":"En Georgia, un conductor menor de 21 años tiene un primer DUI con un nivel de alcohol en la sangre de 0.08 o más. ¿Cuál es la suspensión más corta?","o":["12 meses","30 días","3 meses","6 meses"],"h1":"Es más larga que para un nivel entre 0.02 y 0.08.","h2":"En Georgia, a un conductor menor de 21 años con un primer DUI de 0.08 o más, o que se negó a la prueba, se le suspende la licencia por al menos 12 meses.","p":"Correcto. Al menos 12 meses, sin permiso limitado."},"ref":{"doc":"GA","page":27}},{"id":"ga-078","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how many points are added for having an open container of alcohol while driving?","o":["6 points","4 points","No points, only a fine","2 points"],"h1":"It is the same number as speeding 15 to 18 mph over.","h2":"In Georgia, having an open container of an alcoholic drink while driving adds 2 points to your record.","p":"Right. An open container adds 2 points."},"es":{"q":"En Georgia, ¿cuántos puntos se agregan por tener un envase abierto de alcohol mientras maneja?","o":["6 puntos","4 puntos","Ningún punto, solo una multa","2 puntos"],"h1":"Es el mismo número que por exceder la velocidad por 15 a 18 mph.","h2":"En Georgia, tener un envase abierto de bebida alcohólica mientras maneja agrega 2 puntos a su historial.","p":"Correcto. Un envase abierto agrega 2 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-079","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many points does a conviction for illegally passing a stopped school bus add?","o":["6 points","3 points","2 points","1 point"],"h1":"It is one of the highest point values in Georgia.","h2":"In Georgia, unlawfully passing a school bus adds 6 points to your driving record.","p":"Right. Passing a stopped school bus adds 6 points."},"es":{"q":"En Georgia, ¿cuántos puntos agrega una condena por rebasar ilegalmente un autobús escolar detenido?","o":["6 puntos","3 puntos","2 puntos","1 punto"],"h1":"Es uno de los valores de puntos más altos de Georgia.","h2":"En Georgia, rebasar ilegalmente un autobús escolar agrega 6 puntos a su historial de manejo.","p":"Correcto. Rebasar un autobús escolar detenido agrega 6 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-080","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, your license was suspended because you had too many points. What happens to your point total?","o":["It stays and keeps growing","It is cut in half","It is moved to your insurance record","It goes back to zero"],"h1":"The suspension itself is the penalty for those points.","h2":"In Georgia, when a license is suspended for too many points, the point total goes back to zero.","p":"Right. After a points suspension, the total is zero."},"es":{"q":"En Georgia, le suspendieron la licencia por tener demasiados puntos. ¿Qué pasa con su total de puntos?","o":["Se queda y sigue creciendo","Se reduce a la mitad","Pasa a su historial de seguro","Vuelve a cero"],"h1":"La suspensión misma es el castigo por esos puntos.","h2":"En Georgia, cuando se suspende una licencia por demasiados puntos, el total de puntos vuelve a cero.","p":"Correcto. Después de una suspensión por puntos, el total es cero."},"ref":{"doc":"GA","page":48}},{"id":"ga-081","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you get a ticket and finish a certified 6-hour defensive driving course before your court date. What may the court do?","o":["Cut the fine by 20 percent and add no points","Cancel the ticket completely, with no record","Double the fine but add no points","Add points but cancel the fine"],"h1":"Both the fine and the points are affected.","h2":"In Georgia, if you finish a certified 6-hour driver improvement course before court, the court reduces the fine by 20 percent and adds no points; this is allowed once every five years.","p":"Right. 20 percent off the fine and no points."},"es":{"q":"En Georgia, usted recibe una multa y termina un curso certificado de manejo defensivo de 6 horas antes de su cita en la corte. ¿Qué puede hacer la corte?","o":["Bajar la multa un 20 por ciento y no agregar puntos","Cancelar la multa por completo, sin historial","Duplicar la multa pero no agregar puntos","Agregar puntos pero cancelar la multa"],"h1":"Afecta tanto la multa como los puntos.","h2":"En Georgia, si termina un curso certificado de 6 horas antes de la corte, la corte baja la multa un 20 por ciento y no agrega puntos; esto se permite una vez cada cinco años.","p":"Correcto. 20 por ciento menos de multa y ningún punto."},"ref":{"doc":"GA","page":48}},{"id":"ga-082","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, you take the state's breath test after a DUI arrest. What else does the law allow you to do?","o":["Refuse the result if you disagree","Get extra tests of your own, at your own cost","Ask the officer to delete the result","Have the test done again for free the next day"],"h1":"You may get your own tests, but you pay for them.","h2":"In Georgia, after you take the required state tests, you may get additional tests at your own expense from qualified people you choose.","p":"Right. You may get your own extra tests, at your own cost."},"es":{"q":"En Georgia, usted toma la prueba de aliento del estado después de un arresto por DUI. ¿Qué más le permite la ley?","o":["Rechazar el resultado si no está de acuerdo","Hacerse pruebas adicionales, a su propio costo","Pedir al oficial que borre el resultado","Repetir la prueba gratis al día siguiente"],"h1":"Puede hacerse sus propias pruebas, pero usted las paga.","h2":"En Georgia, después de tomar las pruebas obligatorias del estado, puede hacerse pruebas adicionales a su propio costo con personas calificadas que usted elija.","p":"Correcto. Puede hacerse pruebas adicionales, a su propio costo."},"ref":{"doc":"GA","page":47}},{"id":"ga-083","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, a driver with a limited driving permit is convicted of a moving violation. What happens?","o":["Nothing changes; the permit stays valid","Permit revoked; suspension 6 months longer","Only a $50 fine is added to the ticket","The full license comes back early"],"h1":"Breaking traffic laws with this permit makes things worse.","h2":"In Georgia, a limited driving permit is revoked after a moving violation conviction, and the underlying suspension is extended by 6 months.","p":"Right. The permit is lost and 6 months are added."},"es":{"q":"En Georgia, un conductor con permiso limitado de manejo es condenado por una infracción de tránsito. ¿Qué pasa?","o":["No cambia nada; el permiso sigue válido","Permiso revocado; suspensión 6 meses más larga","Solo se agrega una multa de $50 al boleto","Recupera antes la licencia completa"],"h1":"Violar las leyes de tránsito con este permiso empeora la situación.","h2":"En Georgia, se revoca el permiso limitado de manejo después de una condena por infracción de tránsito, y la suspensión original se alarga 6 meses.","p":"Correcto. Se pierde el permiso y se agregan 6 meses."},"ref":{"doc":"GA","page":48}},{"id":"ga-084","scope":"GA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Georgia, besides emergency vehicles, which stopped vehicles does the Move Over Law cover?","o":["Only police cars with blue lights","Sanitation and utility service vehicles","Only school buses","Only tow trucks with red lights"],"h1":"The law was expanded to protect more roadside workers.","h2":"In Georgia, the Move Over Law covers emergency, sanitation and utility service vehicles stopped on the shoulder.","p":"Right. Sanitation and utility vehicles are covered too."},"es":{"q":"En Georgia, además de los vehículos de emergencia, ¿qué vehículos detenidos cubre la Ley de Moverse (Move Over)?","o":["Solo patrullas con luces azules","Vehículos de recolección de basura y de servicios públicos","Solo autobuses escolares","Solo grúas con luces rojas"],"h1":"La ley se amplió para proteger a más trabajadores en la orilla.","h2":"En Georgia, la Ley de Moverse cubre los vehículos de emergencia, de recolección de basura y de servicios públicos detenidos en el acotamiento.","p":"Correcto. También cubre vehículos de basura y de servicios públicos."},"ref":{"doc":"GA","page":18}},{"id":"ga-085","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, a driver behind you wants to pass. May you flash your turn signal to tell them it is safe to pass?","o":["Yes, but only at night on highways","Yes, it is the polite thing to do","Yes, but only with the right signal","No, that use of turn signals is illegal"],"h1":"Turn signals are only for your own turns and lane changes.","h2":"In Georgia, it is against the law to flash your turn signals as a courtesy or go-ahead-and-pass signal to drivers behind you.","p":"Right. Never use turn signals to wave someone past."},"es":{"q":"En Georgia, un conductor detrás de usted quiere rebasar. ¿Puede encender su direccional para avisarle que es seguro rebasar?","o":["Sí, pero solo de noche en carreteras","Sí, es lo más amable","Sí, pero solo con la direccional derecha","No, ese uso de las direccionales es ilegal"],"h1":"Las direccionales son solo para sus propias vueltas y cambios de carril.","h2":"En Georgia, es ilegal encender las direccionales como cortesía o como señal de que rebasen a los conductores de atrás.","p":"Correcto. Nunca use las direccionales para indicar que rebasen."},"ref":{"doc":"GA","page":19}},{"id":"ga-086","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, how close to a railroad crossing may you not park?","o":["Within 10 feet","Within 15 feet","Within 25 feet","Within 50 feet"],"h1":"It is more than 25 feet.","h2":"In Georgia, you may not park within 50 feet of a railroad crossing; you may stop there only for a moment to pick up or drop off a passenger.","p":"Right. No parking within 50 feet of a railroad crossing."},"es":{"q":"En Georgia, ¿a qué distancia de un cruce de tren no puede estacionarse?","o":["A menos de 10 pies","A menos de 15 pies","A menos de 25 pies","A menos de 50 pies"],"h1":"Es más de 25 pies.","h2":"En Georgia, no puede estacionarse a menos de 50 pies de un cruce de tren; solo puede detenerse allí un momento para recoger o dejar a un pasajero.","p":"Correcto. No se estacione a menos de 50 pies de un cruce de tren."},"ref":{"doc":"GA","page":20}},{"id":"ga-087","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, what is the penalty for staying in the passing lane while faster traffic overtakes you?","o":["A warning only","A fine up to $1,000 and/or 3 points","A fine of $25 and no points","A one-year suspension"],"h1":"It can cost both money and points.","h2":"In Georgia, staying in the passing lane while being overtaken by faster traffic can bring a fine up to $1,000, 3 points, or both.","p":"Right. Up to $1,000 and/or 3 points."},"es":{"q":"En Georgia, ¿cuál es la sanción por quedarse en el carril de rebase mientras lo alcanza tráfico más rápido?","o":["Solo una advertencia","Una multa de hasta $1,000 y/o 3 puntos","Una multa de $25 y ningún punto","Una suspensión de un año"],"h1":"Puede costar dinero y también puntos.","h2":"En Georgia, quedarse en el carril de rebase mientras lo alcanza tráfico más rápido puede causar una multa de hasta $1,000, 3 puntos, o ambos.","p":"Correcto. Hasta $1,000 y/o 3 puntos."},"ref":{"doc":"GA","page":21}},{"id":"ga-088","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, what is the speed limit on an unpaved county road when no other limit is posted?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is a little higher than the limit in a residential area.","h2":"In Georgia, the speed limit on an unpaved county road is 35 mph unless a sign says otherwise.","p":"Right. 35 mph on an unpaved county road."},"es":{"q":"En Georgia, ¿cuál es el límite de velocidad en un camino del condado sin pavimentar cuando no hay otro límite señalado?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es un poco más alto que el límite en una zona residencial.","h2":"En Georgia, el límite de velocidad en un camino del condado sin pavimentar es de 35 mph, a menos que una señal indique otra cosa.","p":"Correcto. 35 mph en un camino del condado sin pavimentar."},"ref":{"doc":"GA","page":21}},{"id":"ga-089","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, a fire truck has stopped to answer a fire alarm. How close to it may you not park?","o":["Within 500 feet","Within 50 feet","Within 100 feet","Within 200 feet"],"h1":"It is farther than the following distance behind a fire truck.","h2":"In Georgia, you may not park within 500 feet of a fire truck that has stopped to answer a fire alarm.","p":"Right. Park no closer than 500 feet."},"es":{"q":"En Georgia, un camión de bomberos se detuvo para atender una alarma de incendio. ¿A qué distancia de él no puede estacionarse?","o":["A menos de 500 pies","A menos de 50 pies","A menos de 100 pies","A menos de 200 pies"],"h1":"Es más lejos que la distancia para seguir a un camión de bomberos.","h2":"En Georgia, no puede estacionarse a menos de 500 pies de un camión de bomberos que se detuvo para atender una alarma de incendio.","p":"Correcto. No se estacione a menos de 500 pies."},"ref":{"doc":"GA","page":24}},{"id":"ga-090","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, when must your headlights be on?","o":["Only when street lights are off, from dusk until dawn","From sunset to sunrise only, but not when it rains","30 minutes after sunset to 30 minutes before sunrise, and in rain","Only on highways at night, never on city streets"],"h1":"Georgia adds a half hour on each side of the night, and rain matters too.","h2":"In Georgia, you must use headlights from one-half hour after sunset to one-half hour before sunrise, any time it is raining, and when it is hard to see.","p":"Right. Half an hour after sunset to half an hour before sunrise, and in rain."},"es":{"q":"En Georgia, ¿cuándo debe tener encendidos los faros?","o":["Solo cuando las luces de la calle están apagadas, de noche","Solo de la puesta del sol al amanecer, pero no con lluvia","De 30 minutos después del atardecer a 30 minutos antes del amanecer, y con lluvia","Solo en carreteras de noche, nunca en la ciudad"],"h1":"Georgia agrega media hora a cada lado de la noche, y la lluvia también cuenta.","h2":"En Georgia, debe usar los faros desde media hora después de la puesta del sol hasta media hora antes del amanecer, siempre que llueva y cuando se vea poco.","p":"Correcto. De media hora después de la puesta del sol a media hora antes del amanecer, y con lluvia."},"ref":{"doc":"GA","page":24}},{"id":"ga-091","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, can a police officer stop you only because you are not wearing a seat belt?","o":["No, only if you break another law too","Only on interstate highways","Yes, Georgia has a primary seat belt law","Only if you are under 18"],"h1":"Think about the word \"primary\".","h2":"In Georgia, the seat belt law is primary, so an officer may stop and cite you for not wearing a seat belt without seeing any other violation.","p":"Right. Not wearing a seat belt is enough for a stop."},"es":{"q":"En Georgia, ¿puede un policía detenerlo solo porque no usa el cinturón de seguridad?","o":["No, solo si también viola otra ley","Solo en carreteras interestatales","Sí, Georgia tiene una ley primaria de cinturón de seguridad","Solo si es menor de 18 años"],"h1":"Piense en la palabra \"primaria\".","h2":"En Georgia, la ley del cinturón de seguridad es primaria, así que un policía puede detenerlo y multarlo por no usar el cinturón sin ver ninguna otra infracción.","p":"Correcto. No usar el cinturón basta para que lo detengan."},"ref":{"doc":"GA","page":24}},{"id":"ga-092","scope":"GA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Georgia, a person is crossing at a crosswalk with no traffic light. When must you stop and stay stopped?","o":["Only when the person is right in front of your car","Only if the person waves at you","Only at night","When on your half of the road or one lane from it"],"h1":"Half of the road means all lanes going your direction.","h2":"In Georgia, you must stop and stay stopped for a person in a crosswalk who is on your half of the road, or approaching and within one lane of it.","p":"Right. Stop when the person is on your half or within one lane of it."},"es":{"q":"En Georgia, una persona cruza por un paso peatonal sin semáforo. ¿Cuándo debe detenerse y quedarse detenido?","o":["Solo cuando la persona está justo frente a su carro","Solo si la persona le hace una seña","Solo de noche","Cuando está en su mitad del camino o a un carril de ella"],"h1":"La mitad del camino son todos los carriles que van en su dirección.","h2":"En Georgia, debe detenerse y quedarse detenido por una persona en un paso peatonal que está en su mitad del camino, o que se acerca y está a un carril de ella.","p":"Correcto. Deténgase cuando la persona está en su mitad o a un carril de ella."},"ref":{"doc":"GA","page":42}},{"id":"ga-093","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, besides 20/60 vision in one eye, how wide must your side-to-side field of vision be for a regular license?","o":["At least 90 degrees","At least 120 degrees","At least 140 degrees","At least 180 degrees"],"h1":"It is a bit less than a straight line, which is 180 degrees.","h2":"In Georgia, a regular license needs a horizontal field of vision of at least 140 degrees.","p":"Right. The field of vision must be at least 140 degrees."},"es":{"q":"En Georgia, además de una vista de 20/60 en un ojo, ¿qué tan amplio debe ser su campo de visión de lado a lado para una licencia normal?","o":["Al menos 90 grados","Al menos 120 grados","Al menos 140 grados","Al menos 180 grados"],"h1":"Es un poco menos que una línea recta, que mide 180 grados.","h2":"En Georgia, una licencia normal requiere un campo de visión horizontal de al menos 140 grados.","p":"Correcto. El campo de visión debe ser de al menos 140 grados."},"ref":{"doc":"GA","page":4}},{"id":"ga-094","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, you moved to a new home. Besides visiting a DDS center, how else may you update your address?","o":["Online at the DDS website","The post office tells DDS for you","By telling your insurance company","By telling a police officer"],"h1":"DDS checks a new address with the postal service when you do it yourself.","h2":"In Georgia, you may change your address online at the DDS website, or in person at a DDS center.","p":"Right. You can update your address online with DDS."},"es":{"q":"En Georgia, usted se mudó a una casa nueva. Además de ir a un centro del DDS, ¿de qué otra forma puede actualizar su dirección?","o":["En línea, en el sitio web del DDS","El correo le avisa al DDS por usted","Avisándole a su compañía de seguros","Avisándole a un policía"],"h1":"El DDS verifica la nueva dirección con el servicio postal cuando usted la cambia.","h2":"En Georgia, puede cambiar su dirección en línea en el sitio web del DDS, o en persona en un centro del DDS.","p":"Correcto. Puede actualizar su dirección en línea con el DDS."},"ref":{"doc":"GA","page":16}},{"id":"ga-095","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, you change your last name when you marry. How soon must you get a license that shows the new name?","o":["Within 10 days","Within 30 days","Within 1 year","Within 60 days"],"h1":"It is about two months.","h2":"In Georgia, after a name change by marriage or other legal action, you must get a license with the correct name within 60 days.","p":"Right. Get a license with your new name within 60 days."},"es":{"q":"En Georgia, usted cambia su apellido al casarse. ¿En cuánto tiempo debe obtener una licencia con el nombre nuevo?","o":["En 10 días","En 30 días","En 1 año","En 60 días"],"h1":"Son unos dos meses.","h2":"En Georgia, después de cambiar de nombre por matrimonio u otro trámite legal, debe obtener una licencia con el nombre correcto en 60 días.","p":"Correcto. Obtenga una licencia con su nombre nuevo en 60 días."},"ref":{"doc":"GA","page":16}},{"id":"ga-096","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, a 15-year-old in foster care applies for a permit. Who may sign as the responsible adult?","o":["A friend who is 16 or older","A social worker who has worked with the teen","The DDS examiner giving the test","No one; the teen signs alone"],"h1":"The adult must be 18 or older and know the teen personally.","h2":"In Georgia, a social worker who has worked with the teen may sign as the responsible adult, with an employee ID or a letter from the state agency.","p":"Right. A social worker who knows the teen may sign."},"es":{"q":"En Georgia, un joven de 15 años en un hogar de crianza pide un permiso. ¿Quién puede firmar como adulto responsable?","o":["Un amigo de 16 años o más","Un trabajador social que ha trabajado con el joven","El examinador del DDS que da el examen","Nadie; el joven firma solo"],"h1":"El adulto debe tener 18 años o más y conocer al joven personalmente.","h2":"En Georgia, un trabajador social que ha trabajado con el joven puede firmar como adulto responsable, con una identificación de empleado o una carta de la agencia estatal.","p":"Correcto. Un trabajador social que conoce al joven puede firmar."},"ref":{"doc":"GA","page":26}},{"id":"ga-097","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, what is the youngest age to get a Class M motorcycle license?","o":["15","16","17","18"],"h1":"It is one year older than the youngest age for a Class D license.","h2":"In Georgia, you must be 17 years old to get a Class M motorcycle license.","p":"Right. A Class M license starts at age 17."},"es":{"q":"En Georgia, ¿cuál es la edad mínima para obtener una licencia de motocicleta Clase M?","o":["15","16","17","18"],"h1":"Es un año más que la edad mínima para una licencia Clase D.","h2":"En Georgia, debe tener 17 años para obtener una licencia de motocicleta Clase M.","p":"Correcto. La licencia Clase M empieza a los 17 años."},"ref":{"doc":"GA","page":26}},{"id":"ga-098","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a 19-year-old is convicted of reckless driving for the second time. How long is the license suspended?","o":["30 days","3 months","6 months","12 months"],"h1":"A first conviction brings 6 months. A second one brings more.","h2":"In Georgia, a driver under 21 who is convicted a second time of an offense like reckless driving has the license suspended for 12 months.","p":"Right. A second conviction under 21 means a 12-month suspension."},"es":{"q":"En Georgia, un joven de 19 años es condenado por segunda vez por manejo imprudente. ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","3 meses","6 meses","12 meses"],"h1":"Una primera condena trae 6 meses. Una segunda trae más.","h2":"En Georgia, a un conductor menor de 21 años condenado por segunda vez por una infracción como manejo imprudente se le suspende la licencia por 12 meses.","p":"Correcto. Una segunda condena antes de los 21 significa 12 meses de suspensión."},"ref":{"doc":"GA","page":27}},{"id":"ga-099","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, a driver under 21 has a suspended license. When may a limited driving permit be possible?","o":["Only for speeding 24 to 33 mph over, if 18 or older","For any offense, at any age at all","Only after a first DUI conviction","Only for drivers who are under 18"],"h1":"It applies to one kind of speeding, and the driver must be an adult.","h2":"In Georgia, a driver under 21 may get a limited permit only if the suspension came from speeding 24 to 33 mph over the limit and the driver is at least 18.","p":"Right. Only for speeding 24 to 33 mph over, and only at 18 or older."},"es":{"q":"En Georgia, un conductor menor de 21 años tiene la licencia suspendida. ¿Cuándo puede ser posible un permiso de manejo limitado?","o":["Solo por exceso de 24 a 33 mph, si tiene 18 años o más","Por cualquier infracción, a cualquier edad","Solo después de una primera condena por DUI","Solo para conductores menores de 18 años"],"h1":"Se aplica a un tipo de exceso de velocidad, y el conductor debe ser adulto.","h2":"En Georgia, un conductor menor de 21 años puede obtener un permiso limitado solo si la suspensión fue por manejar de 24 a 33 mph sobre el límite y tiene al menos 18 años.","p":"Correcto. Solo por exceso de 24 a 33 mph, y solo con 18 años o más."},"ref":{"doc":"GA","page":27}},{"id":"ga-100","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, a 20-year-old with no earlier convictions has a first DUI with a blood alcohol level of 0.05. What is the shortest suspension?","o":["3 months","6 months","12 months","18 months"],"h1":"The level is under 0.08, so it is shorter than a year.","h2":"In Georgia, a driver under 21 with a first DUI and a blood alcohol level from 0.02 to under 0.08 loses the license for at least 6 months.","p":"Right. At least 6 months for a level from 0.02 to under 0.08."},"es":{"q":"En Georgia, un joven de 20 años sin condenas anteriores tiene su primer DUI con un nivel de alcohol en la sangre de 0.05. ¿Cuál es la suspensión más corta?","o":["3 meses","6 meses","12 meses","18 meses"],"h1":"El nivel es menor de 0.08, así que es menos de un año.","h2":"En Georgia, un conductor menor de 21 años con su primer DUI y un nivel de alcohol de 0.02 a menos de 0.08 pierde la licencia por al menos 6 meses.","p":"Correcto. Al menos 6 meses con un nivel de 0.02 a menos de 0.08."},"ref":{"doc":"GA","page":27}},{"id":"ga-101","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a driver under 21 is convicted of a second DUI. What is the shortest suspension?","o":["6 months","9 months","12 months","18 months"],"h1":"It is longer than one year.","h2":"In Georgia, a driver under 21 with a second DUI loses the license for at least 18 months, with an ignition interlock permit possible after 120 days.","p":"Right. A second DUI under 21 means at least 18 months."},"es":{"q":"En Georgia, un conductor menor de 21 años es condenado por un segundo DUI. ¿Cuál es la suspensión más corta?","o":["6 meses","9 meses","12 meses","18 meses"],"h1":"Es más de un año.","h2":"En Georgia, un conductor menor de 21 años con un segundo DUI pierde la licencia por al menos 18 meses, con un posible permiso con bloqueo de encendido después de 120 días.","p":"Correcto. Un segundo DUI antes de los 21 significa al menos 18 meses."},"ref":{"doc":"GA","page":27}},{"id":"ga-102","scope":"GA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Georgia, you are passing on a two-lane road. You must be back in your lane before an oncoming car comes within what distance?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is about the length of 13 cars.","h2":"In Georgia, you must finish passing and be back in the right lane before oncoming traffic is within 200 feet of you.","p":"Right. Be back in your lane before oncoming traffic is within 200 feet."},"es":{"q":"En Georgia, usted está rebasando en un camino de dos carriles. ¿Antes de que un carro que viene de frente llegue a qué distancia debe estar de vuelta en su carril?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es más o menos el largo de 13 carros.","h2":"En Georgia, debe terminar de rebasar y volver al carril derecho antes de que el tráfico que viene de frente esté a 200 pies de usted.","p":"Correcto. Vuelva a su carril antes de que el tráfico de frente esté a 200 pies."},"ref":{"doc":"GA","page":18}},{"id":"ga-103","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, what is the highest fine for breaking the law on how to pass a bicycle?","o":["$250","$50","$500","$1,000"],"h1":"It is a misdemeanor with a fine in the low hundreds.","h2":"In Georgia, breaking the rules for passing a bicycle is a misdemeanor with a fine of up to $250.","p":"Right. The fine can be up to $250."},"es":{"q":"En Georgia, ¿cuál es la multa más alta por no cumplir la ley sobre cómo rebasar a una bicicleta?","o":["$250","$50","$500","$1,000"],"h1":"Es un delito menor con una multa de unos pocos cientos.","h2":"En Georgia, no cumplir las reglas para rebasar a una bicicleta es un delito menor con una multa de hasta $250.","p":"Correcto. La multa puede ser de hasta $250."},"ref":{"doc":"GA","page":19}},{"id":"ga-104","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, your car breaks down on a highway. If you cannot get it off the road, how far must other drivers be able to see it in each direction?","o":["50 feet","200 feet","100 feet","1,000 feet"],"h1":"It is the same distance used for passing on a two-lane road.","h2":"In Georgia, a disabled vehicle left on a highway must leave free passage and a clear view of it for 200 feet in each direction.","p":"Right. Others must see your car from 200 feet each way."},"es":{"q":"En Georgia, su carro se descompone en una carretera. Si no puede sacarlo del camino, ¿desde qué distancia deben poder verlo los otros conductores en cada dirección?","o":["50 pies","200 pies","100 pies","1,000 pies"],"h1":"Es la misma distancia que se usa para rebasar en un camino de dos carriles.","h2":"En Georgia, un vehículo descompuesto en una carretera debe dejar paso libre y verse claramente desde 200 pies en cada dirección.","p":"Correcto. Los demás deben ver su carro desde 200 pies en cada dirección."},"ref":{"doc":"GA","page":20}},{"id":"ga-105","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, what is the widest trailer allowed on the highways?","o":["7 feet","8 feet","8 feet, 6 inches","10 feet"],"h1":"It is a little more than 8 feet.","h2":"In Georgia, trailers wider than 8 feet, 6 inches are not allowed on the highways.","p":"Right. A trailer may be no wider than 8 feet, 6 inches."},"es":{"q":"En Georgia, ¿cuál es el remolque más ancho permitido en las carreteras?","o":["7 pies","8 pies","8 pies y 6 pulgadas","10 pies"],"h1":"Es un poco más de 8 pies.","h2":"En Georgia, no se permiten en las carreteras remolques de más de 8 pies y 6 pulgadas de ancho.","p":"Correcto. Un remolque no puede medir más de 8 pies y 6 pulgadas de ancho."},"ref":{"doc":"GA","page":23}},{"id":"ga-106","scope":"GA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Georgia, may you stop for a moment within 15 feet of a fire hydrant just to let a passenger out?","o":["No, never, not even for a moment","Yes, and you may park there up to 15 minutes","Only at night","Yes, only for a moment to drop off or pick up"],"h1":"Parking there is not allowed, but a very short stop is different.","h2":"In Georgia, you may not park within 15 feet of a fire hydrant, but you may stop there for a moment to pick up or drop off a passenger.","p":"Right. Only a quick stop for a passenger is allowed."},"es":{"q":"En Georgia, ¿puede detenerse un momento a menos de 15 pies de un hidrante solo para que baje un pasajero?","o":["No, nunca, ni por un momento","Sí, y puede estacionarse ahí hasta 15 minutos","Solo de noche","Sí, solo un momento para dejar o recoger a alguien"],"h1":"Estacionarse ahí no se permite, pero una parada muy corta es diferente.","h2":"En Georgia, no puede estacionarse a menos de 15 pies de un hidrante, pero sí puede detenerse un momento para recoger o dejar a un pasajero.","p":"Correcto. Solo se permite una parada rápida por un pasajero."},"ref":{"doc":"GA","page":20}},{"id":"ga-107","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, what is the speed limit on an urban interstate when no other limit is posted?","o":["65 mph","55 mph","60 mph","70 mph"],"h1":"It is 5 mph lower than on a rural interstate.","h2":"In Georgia, unless signs say otherwise, the speed limit is 65 mph on an urban interstate or a multi-lane divided highway.","p":"Right. Urban interstates: 65 mph unless posted."},"es":{"q":"En Georgia, ¿cuál es el límite de velocidad en una interestatal urbana cuando no hay otro límite señalado?","o":["65 mph","55 mph","60 mph","70 mph"],"h1":"Es 5 mph menos que en una interestatal rural.","h2":"En Georgia, si las señales no dicen otra cosa, el límite es de 65 mph en una interestatal urbana o en una carretera dividida de varios carriles.","p":"Correcto. Interestatales urbanas: 65 mph si no hay señal."},"ref":{"doc":"GA","page":21}},{"id":"ga-108","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, you drive on a paved two-lane country highway, not an interstate. No limit is posted. What is the speed limit?","o":["45 mph","55 mph","35 mph","65 mph"],"h1":"This is the general limit for all other areas.","h2":"In Georgia, when no limit is posted, the speed limit is 55 mph on roads that are not urban, interstate, divided multi-lane, or unpaved county roads.","p":"Right. All other areas: 55 mph."},"es":{"q":"En Georgia, usted maneja en una carretera rural pavimentada de dos carriles, que no es interestatal. No hay límite señalado. ¿Cuál es el límite de velocidad?","o":["45 mph","55 mph","35 mph","65 mph"],"h1":"Es el límite general para todas las demás zonas.","h2":"En Georgia, cuando no hay límite señalado, el límite es de 55 mph en caminos que no son urbanos, interestatales, divididos de varios carriles ni caminos de condado sin pavimentar.","p":"Correcto. Todas las demás zonas: 55 mph."},"ref":{"doc":"GA","page":21}},{"id":"ga-109","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, how many people must be in a carpool to use the I-85 Express Lanes without paying a toll?","o":["2 or more","3 or more","4 or more","5 or more"],"h1":"It is more than just a driver and one passenger.","h2":"In Georgia, carpools of three or more people may use the I-85 Express Lanes toll-free.","p":"Right. Three or more people ride the I-85 Express Lanes toll-free."},"es":{"q":"En Georgia, ¿cuántas personas debe tener un carro compartido para usar los carriles Express de la I-85 sin pagar peaje?","o":["2 o más","3 o más","4 o más","5 o más"],"h1":"Es más que solo el conductor y un pasajero.","h2":"En Georgia, los carros compartidos con tres o más personas pueden usar los carriles Express de la I-85 sin pagar peaje.","p":"Correcto. Con tres o más personas no se paga peaje en la I-85 Express."},"ref":{"doc":"GA","page":33}},{"id":"ga-110","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, a family is towing a house trailer on the highway. May someone ride inside the trailer?","o":["Yes, if they wear a seat belt","Yes, if the trip is short","No, riding in a towed trailer is not allowed","Only if they are adults"],"h1":"Think about what happens if the trailer comes loose.","h2":"In Georgia, no one may ride in a house trailer or any other towed trailer while it is being moved on a street or highway.","p":"Right. No one may ride in a trailer while it is towed."},"es":{"q":"En Georgia, una familia remolca una casa rodante por la carretera. ¿Puede alguien viajar dentro del remolque?","o":["Sí, si usa cinturón de seguridad","Sí, si el viaje es corto","No, no se permite viajar en un remolque arrastrado","Solo si son adultos"],"h1":"Piense en lo que pasa si el remolque se suelta.","h2":"En Georgia, nadie puede viajar en una casa rodante ni en otro remolque mientras lo mueven por una calle o carretera.","p":"Correcto. Nadie puede viajar en un remolque mientras lo arrastran."},"ref":{"doc":"GA","page":23}},{"id":"ga-111","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you are following another car at night. Within what distance must you switch to low beams?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"It is less than the distance used for oncoming cars, which is 500 feet.","h2":"In Georgia, you should dim your headlights when you are following within 200 feet of another vehicle.","p":"Right. Dim your lights within 200 feet of a car ahead."},"es":{"q":"En Georgia, usted va detrás de otro carro de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","1,000 pies","200 pies"],"h1":"Es menos que la distancia para carros que vienen de frente, que es 500 pies.","h2":"En Georgia, debe bajar las luces cuando va a menos de 200 pies detrás de otro vehículo.","p":"Correcto. Baje las luces a 200 pies del carro de adelante."},"ref":{"doc":"GA","page":24}},{"id":"ga-112","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, which adults must wear a seat belt under state law?","o":["Everyone in the front seat","Only the driver","Only people in the back seat","Only on interstates"],"h1":"For people under 18, every seat counts. For adults, think of one row.","h2":"In Georgia, every person in the front seat of a passenger vehicle must wear a seat belt, and everyone under 18 must wear one in any seat.","p":"Right. Everyone in the front seat must buckle up."},"es":{"q":"En Georgia, ¿qué adultos deben usar cinturón de seguridad según la ley estatal?","o":["Todos los del asiento delantero","Solo el conductor","Solo los del asiento trasero","Solo en las interestatales"],"h1":"Para los menores de 18, cuenta cualquier asiento. Para los adultos, piense en una fila.","h2":"En Georgia, toda persona en el asiento delantero de un vehículo de pasajeros debe usar cinturón, y todos los menores de 18 deben usarlo en cualquier asiento.","p":"Correcto. Todos en el asiento delantero deben abrocharse."},"ref":{"doc":"GA","page":24}},{"id":"ga-113","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, in which vehicle is the driver not required to put a child under 8 in a child safety seat?","o":["A pickup truck","A taxicab","A minivan","A rental car"],"h1":"The law makes an exception for a vehicle you pay to ride in.","h2":"In Georgia, the child safety seat rule for children under 8 does not apply in a taxicab or a public transit vehicle.","p":"Right. Taxis and public transit are the exception."},"es":{"q":"En Georgia, ¿en qué vehículo el conductor no está obligado a poner en un asiento de seguridad a un niño menor de 8 años?","o":["Una camioneta pickup","Un taxi","Una minivan","Un carro de alquiler"],"h1":"La ley hace una excepción para un vehículo en el que usted paga por viajar.","h2":"En Georgia, la regla del asiento de seguridad para niños menores de 8 años no se aplica en un taxi ni en un vehículo de transporte público.","p":"Correcto. Los taxis y el transporte público son la excepción."},"ref":{"doc":"GA","page":24}},{"id":"ga-114","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, what is the highest fine for throwing litter from a car?","o":["$100","$250","$500","$1,000"],"h1":"It is the same as the highest fine for reckless driving.","h2":"In Georgia, littering can bring a fine of up to $1,000 and up to 12 months in jail, and a judge may order the person to pick up litter.","p":"Right. Littering can cost up to $1,000."},"es":{"q":"En Georgia, ¿cuál es la multa más alta por tirar basura desde un carro?","o":["$100","$250","$500","$1,000"],"h1":"Es igual que la multa más alta por manejo imprudente.","h2":"En Georgia, tirar basura puede traer una multa de hasta $1,000 y hasta 12 meses de cárcel, y un juez puede ordenar a la persona recoger basura.","p":"Correcto. Tirar basura puede costar hasta $1,000."},"ref":{"doc":"GA","page":24}},{"id":"ga-115","scope":"GA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Georgia, what is the penalty for a third conviction under the hands-free phone law?","o":["1 point and up to $50","2 points and up to $100","3 points and up to $150","6 points and up to $500"],"h1":"The points and the fine grow with each conviction.","h2":"In Georgia, a third or later hands-free conviction brings 3 points and a fine of up to $150.","p":"Right. Third conviction: 3 points and up to $150."},"es":{"q":"En Georgia, ¿cuál es la sanción por una tercera condena bajo la ley de manos libres?","o":["1 punto y hasta $50","2 puntos y hasta $100","3 puntos y hasta $150","6 puntos y hasta $500"],"h1":"Los puntos y la multa aumentan con cada condena.","h2":"En Georgia, una tercera condena o más bajo la ley de manos libres trae 3 puntos y una multa de hasta $150.","p":"Correcto. Tercera condena: 3 puntos y hasta $150."},"ref":{"doc":"GA","page":25}},{"id":"ga-116","scope":"GA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Georgia, you are in the acceleration lane of an expressway. A solid white line separates you from the travel lane. What must you do?","o":["Stay in the acceleration lane until the solid line ends","Cross the solid line as soon as there is a gap","Stop and wait at the end of the ramp","Drive on the shoulder to pass"],"h1":"The triangle area between the lanes is called the gore.","h2":"In Georgia, drivers entering an expressway may not cross the solid white line of the gore and must stay in the acceleration lane until the line ends.","p":"Right. Wait until the solid white line ends before you merge."},"es":{"q":"En Georgia, usted está en el carril de aceleración de una autopista. Una línea blanca sólida lo separa del carril de tráfico. ¿Qué debe hacer?","o":["Seguir en el carril de aceleración hasta que termine la línea sólida","Cruzar la línea sólida apenas haya un espacio","Detenerse y esperar al final de la rampa","Manejar por el acotamiento para adelantar"],"h1":"La zona en forma de triángulo entre los carriles se llama \"gore\".","h2":"En Georgia, los conductores que entran a una autopista no pueden cruzar la línea blanca sólida del \"gore\" y deben seguir en el carril de aceleración hasta que la línea termine.","p":"Correcto. Espere a que termine la línea blanca sólida antes de incorporarse."},"ref":{"doc":"GA","page":40}},{"id":"ga-117","scope":"GA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Georgia, what penalty does a fourth or later HOV lane violation bring?","o":["A $75 fine only","Up to $150 and 1 point","Up to $1,000 and 6 points","An automatic suspension"],"h1":"This is the first time points are added for HOV violations.","h2":"In Georgia, a fourth or later HOV lane violation brings a fine of up to $150 plus one point on the driving record.","p":"Right. Fourth offense: up to $150 and 1 point."},"es":{"q":"En Georgia, ¿qué sanción trae una cuarta infracción o más en el carril HOV?","o":["Solo una multa de $75","Hasta $150 y 1 punto","Hasta $1,000 y 6 puntos","Una suspensión automática"],"h1":"Es la primera vez que se añaden puntos por infracciones en el carril HOV.","h2":"En Georgia, una cuarta infracción o más en el carril HOV trae una multa de hasta $150 más un punto en el historial.","p":"Correcto. Cuarta infracción: hasta $150 y 1 punto."},"ref":{"doc":"GA","page":40}},{"id":"ga-118","scope":"GA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Georgia, you stop for a person at a crosswalk on a road with several lanes. How far back from the crosswalk should you stop?","o":["Right at the crosswalk line","At least 3 feet","At least 50 feet","At least 10 feet"],"h1":"Leave enough room so a driver in the next lane can see the walker.","h2":"In Georgia, on a multi-lane road you should stop at least 10 feet before the crosswalk so drivers in the next lane can see the pedestrian.","p":"Right. Stop at least 10 feet back so others can see the walker."},"es":{"q":"En Georgia, usted se detiene por una persona en un paso peatonal en un camino de varios carriles. ¿A qué distancia del paso peatonal debe detenerse?","o":["Justo en la línea del paso peatonal","Al menos a 3 pies","Al menos a 50 pies","Al menos a 10 pies"],"h1":"Deje espacio para que un conductor en el carril de al lado pueda ver al peatón.","h2":"En Georgia, en un camino de varios carriles debe detenerse al menos 10 pies antes del paso peatonal para que los conductores del carril de al lado puedan ver al peatón.","p":"Correcto. Deténgase al menos a 10 pies para que otros vean al peatón."},"ref":{"doc":"GA","page":42}},{"id":"ga-119","scope":"GA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Georgia, a road has a bike lane, but a bicyclist is riding in your travel lane. Is that legal?","o":["Yes, bicyclists do not have to use the bike lane","No, they must always use the bike lane","Only on weekends","Only if the bike has lights"],"h1":"Bicyclists may use the full lane on most roads.","h2":"In Georgia, bicyclists may use every road except interstates and other limited-access highways, and they are not required to ride in a bike lane even when one is there.","p":"Right. A bicyclist does not have to use the bike lane."},"es":{"q":"En Georgia, un camino tiene carril para bicicletas, pero un ciclista va por su carril de tráfico. ¿Es legal?","o":["Sí, los ciclistas no están obligados a usar el carril para bicicletas","No, siempre deben usar el carril para bicicletas","Solo los fines de semana","Solo si la bicicleta tiene luces"],"h1":"Los ciclistas pueden usar el carril completo en la mayoría de los caminos.","h2":"En Georgia, los ciclistas pueden usar todos los caminos menos las interestatales y otras autopistas de acceso limitado, y no están obligados a usar el carril para bicicletas aunque exista.","p":"Correcto. Un ciclista no está obligado a usar el carril para bicicletas."},"ref":{"doc":"GA","page":42}},{"id":"ga-120","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, you hold a Georgia license and get a speeding conviction in another state. What happens?","o":["Nothing, it stays in the other state","You must take a new road test","It goes on your Georgia record as if it happened here","Only the fine counts, never points"],"h1":"Other states report convictions to Georgia.","h2":"In Georgia, convictions reported from other states are put on your Georgia driving record and treated as if they happened in Georgia.","p":"Right. Out-of-state convictions count on your Georgia record."},"es":{"q":"En Georgia, usted tiene licencia de Georgia y recibe una condena por exceso de velocidad en otro estado. ¿Qué pasa?","o":["Nada, se queda en el otro estado","Debe tomar un nuevo examen de manejo","Se anota en su historial de Georgia como si hubiera pasado aquí","Solo cuenta la multa, nunca los puntos"],"h1":"Los otros estados reportan las condenas a Georgia.","h2":"En Georgia, las condenas reportadas por otros estados se anotan en su historial de manejo de Georgia y se tratan como si hubieran pasado en Georgia.","p":"Correcto. Las condenas de otros estados cuentan en su historial de Georgia."},"ref":{"doc":"GA","page":46}},{"id":"ga-121","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, a driver refuses a blood test after a DUI arrest. Besides losing the license, how can the refusal be used?","o":["It cannot be used at all","It may be shown as evidence at trial","It cancels the DUI charge","It only matters for drivers under 21"],"h1":"Refusing does not make the case go away.","h2":"In Georgia, refusing a state blood or urine test may be offered as evidence at trial, and the license is suspended for at least one year.","p":"Right. The refusal may be used as evidence at trial."},"es":{"q":"En Georgia, un conductor se niega a una prueba de sangre después de ser arrestado por DUI. Además de perder la licencia, ¿cómo se puede usar esa negativa?","o":["No se puede usar de ninguna forma","Puede presentarse como prueba en el juicio","Anula el cargo de DUI","Solo importa para menores de 21 años"],"h1":"Negarse no hace que el caso desaparezca.","h2":"En Georgia, negarse a una prueba estatal de sangre o de orina puede presentarse como prueba en el juicio, y la licencia se suspende por al menos un año.","p":"Correcto. La negativa puede usarse como prueba en el juicio."},"ref":{"doc":"GA","page":47}},{"id":"ga-122","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, how many points does a reckless driving conviction add to your record?","o":["4 points","2 points","3 points","6 points"],"h1":"It is the same as speeding 24 to 33 mph over the limit.","h2":"In Georgia, a conviction for reckless driving adds 4 points to your driving record.","p":"Right. Reckless driving is 4 points."},"es":{"q":"En Georgia, ¿cuántos puntos añade a su historial una condena por manejo imprudente?","o":["4 puntos","2 puntos","3 puntos","6 puntos"],"h1":"Es igual que manejar de 24 a 33 mph sobre el límite.","h2":"En Georgia, una condena por manejo imprudente añade 4 puntos a su historial de manejo.","p":"Correcto. El manejo imprudente son 4 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-123","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, how many points does an aggressive driving conviction add to your record?","o":["2 points","3 points","4 points","6 points"],"h1":"It is the same as illegally passing a stopped school bus.","h2":"In Georgia, a conviction for aggressive driving adds 6 points to your driving record.","p":"Right. Aggressive driving is 6 points."},"es":{"q":"En Georgia, ¿cuántos puntos añade a su historial una condena por manejo agresivo?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Es igual que rebasar ilegalmente un autobús escolar detenido.","h2":"En Georgia, una condena por manejo agresivo añade 6 puntos a su historial de manejo.","p":"Correcto. El manejo agresivo son 6 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-124","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, how many points does a conviction for speeding 15 to 18 mph over the limit add?","o":["1 point","2 points","4 points","6 points"],"h1":"It is the lowest point value for speeding on the chart.","h2":"In Georgia, speeding 15 to 18 mph over the posted limit adds 2 points to your record.","p":"Right. 15 to 18 mph over is 2 points."},"es":{"q":"En Georgia, ¿cuántos puntos añade una condena por manejar de 15 a 18 mph sobre el límite?","o":["1 punto","2 puntos","4 puntos","6 puntos"],"h1":"Es el valor de puntos más bajo para exceso de velocidad en la tabla.","h2":"En Georgia, manejar de 15 a 18 mph sobre el límite señalado añade 2 puntos a su historial.","p":"Correcto. De 15 a 18 mph sobre el límite son 2 puntos."},"ref":{"doc":"GA","page":47}},{"id":"ga-125","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, the 24-month period for counting points starts from which date?","o":["The date you paid the fine","The date of your court hearing","The date the violation happened","The date DDS mailed a letter"],"h1":"Think of the day you were stopped.","h2":"In Georgia, the date the violation occurred is used to count the 24-month period for points (12 months for drivers under 18).","p":"Right. Points are counted from the date of the violation."},"es":{"q":"En Georgia, ¿desde qué fecha empieza el período de 24 meses para contar los puntos?","o":["La fecha en que pagó la multa","La fecha de su audiencia en la corte","La fecha en que ocurrió la infracción","La fecha en que el DDS envió una carta"],"h1":"Piense en el día en que lo detuvieron.","h2":"En Georgia, la fecha en que ocurrió la infracción se usa para contar el período de 24 meses de los puntos (12 meses para menores de 18 años).","p":"Correcto. Los puntos se cuentan desde la fecha de la infracción."},"ref":{"doc":"GA","page":48}},{"id":"ga-126","scope":"GA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Georgia, a 19-year-old pleads nolo contendere (no contest) to a 4-point offense. Does it count for the under-21 suspension?","o":["Yes, it counts as a conviction","No, it never counts","Only if the driver is under 18","Only if a crash happened"],"h1":"For drivers under 21, this kind of plea is treated the same as being found guilty.","h2":"In Georgia, a plea of nolo contendere counts as a conviction for the suspensions that apply to drivers under 21.","p":"Right. A no-contest plea counts as a conviction under 21."},"es":{"q":"En Georgia, un joven de 19 años se declara \"nolo contendere\" (sin oponerse) por una infracción de 4 puntos. ¿Cuenta para la suspensión de menores de 21?","o":["Sí, cuenta como una condena","No, nunca cuenta","Solo si el conductor es menor de 18","Solo si hubo un choque"],"h1":"Para menores de 21, este tipo de declaración se trata igual que ser declarado culpable.","h2":"En Georgia, una declaración de \"nolo contendere\" cuenta como condena para las suspensiones que se aplican a conductores menores de 21 años.","p":"Correcto. Esa declaración cuenta como condena antes de los 21."},"ref":{"doc":"GA","page":48}},{"id":"ga-127","scope":"GA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Georgia, a claim is filed against you under the Safety Responsibility Law after a crash. You had liability insurance. How can you avoid the suspension?","o":["Pay a $500 fee to DDS","Take a defensive driving course","Retake the road test","Have your insurance company file Form SR-21"],"h1":"Your insurance company sends a form to DDS.","h2":"In Georgia, if you had liability insurance at the time of the crash, your insurance company can file Form SR-21 with DDS to avoid the suspension.","p":"Right. Your insurer files Form SR-21."},"es":{"q":"En Georgia, después de un choque se presenta un reclamo contra usted bajo la Ley de Responsabilidad de Seguridad. Usted tenía seguro de responsabilidad civil. ¿Cómo puede evitar la suspensión?","o":["Pagar una tarifa de $500 al DDS","Tomar un curso de manejo defensivo","Repetir el examen de manejo","Pedir a su compañía de seguros que presente el Formulario SR-21"],"h1":"Su compañía de seguros envía un formulario al DDS.","h2":"En Georgia, si tenía seguro de responsabilidad civil cuando ocurrió el choque, su compañía de seguros puede presentar el Formulario SR-21 al DDS para evitar la suspensión.","p":"Correcto. Su aseguradora presenta el Formulario SR-21."},"ref":{"doc":"GA","page":48}},{"id":"ga-128","scope":"GA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Georgia, how many DUI (or similar serious) convictions within 5 years make a driver a Habitual Violator?","o":["1","2","3","5"],"h1":"It happens on the third time.","h2":"In Georgia, a driver is declared a Habitual Violator, and the license is revoked, on a third conviction of DUI or similar serious offenses within 5 years.","p":"Right. Three such convictions in 5 years make a Habitual Violator."},"es":{"q":"En Georgia, ¿cuántas condenas por DUI (u otras infracciones graves parecidas) en 5 años hacen que un conductor sea Infractor Habitual?","o":["1","2","3","5"],"h1":"Ocurre la tercera vez.","h2":"En Georgia, un conductor es declarado Infractor Habitual, y se le revoca la licencia, con una tercera condena por DUI u otras infracciones graves parecidas en 5 años.","p":"Correcto. Tres condenas así en 5 años hacen a un Infractor Habitual."},"ref":{"doc":"GA","page":48}},{"id":"ga-129","scope":"GA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Georgia, you have a limited driving permit during a suspension. Which trip does it allow?","o":["Driving to a friend's party","Driving to your job","A weekend road trip","Shopping at the mall"],"h1":"The permit covers needs like work, school and medical care.","h2":"In Georgia, a limited driving permit only allows trips such as going to work, school, medical care, court, or support meetings.","p":"Right. Driving to work is allowed with a limited permit."},"es":{"q":"En Georgia, usted tiene un permiso de manejo limitado durante una suspensión. ¿Qué viaje le permite?","o":["Ir a la fiesta de un amigo","Ir a su trabajo","Un paseo de fin de semana","Ir de compras al centro comercial"],"h1":"El permiso cubre necesidades como el trabajo, la escuela y la atención médica.","h2":"En Georgia, un permiso de manejo limitado solo permite viajes como ir al trabajo, a la escuela, a citas médicas, a la corte o a reuniones de apoyo.","p":"Correcto. Ir al trabajo se permite con un permiso limitado."},"ref":{"doc":"GA","page":48}},{"id":"ga-130","scope":"GA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Georgia, you stop to give emergency care at a crash. What does the Good Samaritan Law do?","o":["It makes you pay the victim's medical bills","It requires you to have first aid training","It makes you responsible for the crash","It protects you from civil damages for that care"],"h1":"The law is meant to encourage people to help.","h2":"In Georgia, the Good Samaritan Law protects anyone who gives emergency care at a crash from civil damages for what they do or fail to do.","p":"Right. The law protects people who help in an emergency."},"es":{"q":"En Georgia, usted se detiene a dar ayuda de emergencia en un choque. ¿Qué hace la Ley del Buen Samaritano?","o":["Lo obliga a pagar los gastos médicos de la víctima","Le exige tener entrenamiento de primeros auxilios","Lo hace responsable del choque","Lo protege de demandas civiles por esa ayuda"],"h1":"La ley busca animar a la gente a ayudar.","h2":"En Georgia, la Ley del Buen Samaritano protege a quien da ayuda de emergencia en un choque de demandas civiles por lo que haga o deje de hacer.","p":"Correcto. La ley protege a quienes ayudan en una emergencia."},"ref":{"doc":"GA","page":50}},{"id":"ga-131","scope":"GA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Georgia, you have a minor crash on an expressway. No one is badly hurt and both cars can be driven. What must the drivers do?","o":["Move the cars off the road to a safe place","Leave the cars where they are until police come","Drive home and call the police later","Stay in the cars with hazard lights on"],"h1":"Moving the cars does not mean you are at fault.","h2":"In Georgia, after a crash on a multi-lane highway or expressway with no apparent serious injury, drivers must move drivable cars to the shoulder, median, or another safe place.","p":"Right. Move drivable cars out of the road to a safe spot."},"es":{"q":"En Georgia, usted tiene un choque leve en una autopista. Nadie está herido de gravedad y los dos carros funcionan. ¿Qué deben hacer los conductores?","o":["Mover los carros fuera del camino a un lugar seguro","Dejar los carros donde están hasta que llegue la policía","Irse a casa y llamar a la policía después","Quedarse en los carros con las luces de emergencia"],"h1":"Mover los carros no significa que usted tenga la culpa.","h2":"En Georgia, después de un choque en una carretera de varios carriles o autopista sin heridas graves aparentes, los conductores deben mover los carros que funcionen al acotamiento, a la mediana o a otro lugar seguro.","p":"Correcto. Mueva los carros que funcionen fuera del camino a un lugar seguro."},"ref":{"doc":"GA","page":50}},{"id":"ga-132","scope":"GA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Georgia, you are driving down a long hill. May you shift into neutral and coast?","o":["Yes, it saves gas","No, coasting in neutral downhill is not allowed","Yes, but only on a straight road","Only if no cars are behind you"],"h1":"In neutral, the engine cannot help you control your speed.","h2":"In Georgia, a driver going down a hill must not coast with the gears or transmission in neutral.","p":"Right. Do not coast downhill in neutral."},"es":{"q":"En Georgia, usted baja una cuesta larga. ¿Puede poner el carro en neutral y bajar sin cambio?","o":["Sí, ahorra gasolina","No, no se permite bajar una cuesta en neutral","Sí, pero solo en un camino recto","Solo si no hay carros detrás de usted"],"h1":"En neutral, el motor no lo ayuda a controlar la velocidad.","h2":"En Georgia, un conductor que baja una cuesta no debe dejar el carro rodar con los cambios o la transmisión en neutral.","p":"Correcto. No baje una cuesta en neutral."},"ref":{"doc":"GA","page":23}},{"id":"hi-001","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year past a birthday.","h2":"In Hawaii you can get an instruction permit at 15 and a half years old.","p":"Right. The Hawaii permit starts at 15 and a half."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Hawái usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Hawái empieza a los 15 años y medio."},"zh":{"q":"在 Hawaii，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了生日以后再加半年。","h2":"在 Hawaii，你 15 岁半就可以拿到学习驾照。","p":"对。Hawaii 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Hawaii, tuổi nhỏ nhất để có giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật.","h2":"Ở Hawaii, bạn có thể có giấy phép tập lái khi được 15 tuổi rưỡi.","p":"Đúng. Ở Hawaii, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Hawaii, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan.","h2":"Sa Hawaii, puwede kang kumuha ng instruction permit sa edad na 15 at kalahati.","p":"Tama. Sa Hawaii, nagsisimula ang permit sa 15 at kalahati."},"ar":{"q":"في Hawaii، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد عيد ميلاد.","h2":"في Hawaii يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة ونصف.","p":"صحيح. في Hawaii يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"HI","page":13}},{"id":"hi-002","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how old must the licensed driver with a permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Hawaii permit holder may drive only with a licensed driver who is at least 21 years old.","p":"Right. The adult with you must be 21 or older."},"es":{"q":"En Hawái, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"Quien tiene un permiso en Hawái solo puede manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El adulto que lo acompaña debe tener 21 años o más."},"zh":{"q":"在 Hawaii，陪同持学习驾照的人开车、有驾照的司机必须几岁？","o":["至少 18 岁","至少 21 岁","至少 25 岁","至少 30 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Hawaii，持学习驾照的人只能和一位至少 21 岁、有驾照的司机一起开车。","p":"对。陪你的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Hawaii, người có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 30 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để được uống rượu hợp pháp.","h2":"Người có giấy phép tập lái ở Hawaii chỉ được lái xe cùng một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người lớn đi cùng bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Hawaii, ilang taon dapat ang lisensyadong driver na kasama ng may permit?","o":["Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 30"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak.","h2":"Ang may permit sa Hawaii ay puwedeng magmaneho lang kasama ang lisensyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o higit pa ang edad ng kasama mong adult."},"ar":{"q":"في Hawaii، كم يجب أن يكون عمر السائق المرخَّص الذي يرافق حامل التصريح؟","o":["18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل","30 سنة على الأقل"],"h1":"يجب أن يكون المرافق كبيرًا بما يكفي لشرب الكحول قانونيًا.","h2":"لا يجوز لحامل التصريح في Hawaii أن يقود إلا مع سائق مرخَّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون البالغ الذي معك عمره 21 سنة أو أكثر."},"ref":{"doc":"HI","page":11}},{"id":"hi-003","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, where must the supervising driver sit when a permit holder drives?","o":["In the front passenger seat","In the back seat behind the driver","Anywhere in the car","In the back seat on the right"],"h1":"The helper needs to see the road and reach the driver quickly.","h2":"The supervising driver must sit in the front passenger seat, beside the Hawaii permit holder.","p":"Right. The helper sits right beside you."},"es":{"q":"En Hawái, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento trasero detrás del conductor","En cualquier lugar del carro","En el asiento trasero a la derecha"],"h1":"El acompañante necesita ver la vía y alcanzar al conductor rápido.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero, al lado de quien tiene el permiso en Hawái.","p":"Correcto. El acompañante va a su lado."},"zh":{"q":"在 Hawaii，持学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位","司机后面的后排座位","车里任何地方","右边的后排座位"],"h1":"陪同的人需要看到道路，并能很快够到司机。","h2":"陪同的司机必须坐在前排乘客座位，在 Hawaii 持学习驾照的人旁边。","p":"对。陪同的人就坐在你旁边。"},"vi":{"q":"Ở Hawaii, khi người có giấy phép tập lái lái xe, người giám sát phải ngồi ở đâu?","o":["Ở ghế hành khách phía trước","Ở ghế sau, phía sau tài xế","Ở bất cứ chỗ nào trong xe","Ở ghế sau, bên phải"],"h1":"Người hướng dẫn cần nhìn thấy đường và giúp tài xế nhanh chóng.","h2":"Người giám sát phải ngồi ở ghế hành khách phía trước, bên cạnh người có giấy phép tập lái ở Hawaii.","p":"Đúng. Người hướng dẫn ngồi ngay bên cạnh bạn."},"tl":{"q":"Sa Hawaii, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa likod, sa likuran ng driver","Kahit saan sa kotse","Sa likod, sa kanan"],"h1":"Kailangang makita ng kasama ang daan at maabot agad ang driver.","h2":"Dapat umupo ang nagbabantay na driver sa upuan ng pasahero sa harap, katabi ng may permit sa Hawaii.","p":"Tama. Katabi mo mismo ang kasama mo."},"ar":{"q":"في Hawaii، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في مقعد الراكب الأمامي","في المقعد الخلفي خلف السائق","في أي مكان في السيارة","في المقعد الخلفي على اليمين"],"h1":"يحتاج المرافق أن يرى الطريق وأن يصل إلى السائق بسرعة.","h2":"يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي، بجانب حامل التصريح في Hawaii.","p":"صحيح. يجلس المرافق بجانبك مباشرة."},"ref":{"doc":"HI","page":11}},{"id":"hi-004","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how long must you hold an instruction permit before the road test?","o":["30 days","90 days","1 year","180 days"],"h1":"It is about half a year.","h2":"In Hawaii you must hold your instruction permit for at least 180 days before you take the road test.","p":"Right. You practice for at least 180 days first."},"es":{"q":"En Hawái, ¿cuánto tiempo debe tener el permiso de instrucción antes del examen de manejo?","o":["30 días","90 días","1 año","180 días"],"h1":"Es más o menos medio año.","h2":"En Hawái usted debe tener el permiso de instrucción por lo menos 180 días antes de presentar el examen de manejo.","p":"Correcto. Primero practica por lo menos 180 días."},"zh":{"q":"在 Hawaii，你必须持有学习驾照多久，才能参加路考？","o":["30 天","90 天","1 年","180 天"],"h1":"大约是半年。","h2":"在 Hawaii，你必须持有学习驾照至少 180 天，才能参加路考。","p":"对。你要先练习至少 180 天。"},"vi":{"q":"Ở Hawaii, bạn phải giữ giấy phép tập lái bao lâu trước khi thi lái xe trên đường?","o":["30 ngày","90 ngày","1 năm","180 ngày"],"h1":"Khoảng nửa năm.","h2":"Ở Hawaii, bạn phải giữ giấy phép tập lái ít nhất 180 ngày trước khi thi lái xe trên đường.","p":"Đúng. Bạn tập lái ít nhất 180 ngày trước."},"tl":{"q":"Sa Hawaii, gaano katagal mo dapat hawak ang instruction permit bago ang road test?","o":["30 araw","90 araw","1 taon","180 araw"],"h1":"Mga kalahating taon ito.","h2":"Sa Hawaii, dapat hawak mo ang iyong instruction permit nang hindi bababa sa 180 araw bago ka kumuha ng road test.","p":"Tama. Magsasanay ka muna nang hindi bababa sa 180 araw."},"ar":{"q":"في Hawaii، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل اختبار القيادة على الطريق؟","o":["30 يومًا","90 يومًا","سنة واحدة (1)","180 يومًا"],"h1":"هي حوالي نصف سنة.","h2":"في Hawaii يجب أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل قبل أن تأخذ اختبار القيادة على الطريق.","p":"صحيح. تتدرّب 180 يومًا على الأقل أولًا."},"ref":{"doc":"HI","page":13}},{"id":"hi-005","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the youngest age to get a provisional license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"It comes after a half year of practice with a permit from age 15 and a half.","h2":"In Hawaii the provisional license is available from age 16.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener una licencia provisional?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de medio año de práctica con un permiso desde los 15 años y medio.","h2":"En Hawái la licencia provisional se puede obtener desde los 16 años.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Hawaii，最小几岁可以拿到过渡驾照（provisional license）？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"它是在 15 岁半拿到学习驾照、练习半年以后。","h2":"在 Hawaii，16 岁起就可以拿到过渡驾照。","p":"对。过渡驾照从 16 岁开始。"},"vi":{"q":"Ở Hawaii, tuổi nhỏ nhất để có bằng lái tạm thời (provisional license) là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là sau nửa năm tập lái với giấy phép có từ lúc 15 tuổi rưỡi.","h2":"Ở Hawaii, bằng lái tạm thời có thể được cấp từ 16 tuổi.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Hawaii, ano ang pinakabatang edad para makakuha ng provisional license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Darating ito pagkatapos ng kalahating taon ng pagsasanay gamit ang permit mula edad 15 at kalahati.","h2":"Sa Hawaii, makukuha ang provisional license mula edad 16.","p":"Tama. Nagsisimula ang provisional license sa 16."},"ar":{"q":"في Hawaii، ما أصغر عمر للحصول على رخصة القيادة المؤقتة (provisional license)؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"تأتي بعد نصف سنة من التدريب بتصريح من عمر 15 سنة ونصف.","h2":"في Hawaii يمكن الحصول على رخصة القيادة المؤقتة من عمر 16 سنة.","p":"صحيح. تبدأ الرخصة المؤقتة في عمر 16 سنة."},"ref":{"doc":"HI","page":13}},{"id":"hi-006","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, during which hours does a provisional licensee need a parent or guardian in the car?","o":["9 p.m. to 5 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"It starts one hour before midnight.","h2":"A Hawaii provisional licensee who drives between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them, unless an exception applies.","p":"Right. The night limit is 11 p.m. to 5 a.m."},"es":{"q":"En Hawái, ¿en qué horas necesita un conductor con licencia provisional a su padre, madre o tutor en el carro?","o":["De 9 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"Un conductor con licencia provisional en Hawái que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia, salvo que aplique una excepción.","p":"Correcto. El límite de noche es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Hawaii，持过渡驾照的人在哪些时间开车，车里必须有父母或监护人？","o":["晚上 9 点到早上 5 点","午夜到早上 6 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"它从午夜前一个小时开始。","h2":"在 Hawaii，持过渡驾照的人在晚上 11 点到早上 5 点之间开车时，旁边的座位必须坐着一位有驾照的父母或监护人，除非符合例外情况。","p":"对。夜间限制是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Hawaii, trong những giờ nào người có bằng lái tạm thời cần cha mẹ hoặc người giám hộ ngồi trong xe?","o":["9 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Hawaii, người có bằng lái tạm thời lái xe từ 11 giờ tối đến 5 giờ sáng phải có cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế bên cạnh, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Giới hạn ban đêm là từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Hawaii, sa anong mga oras kailangan ng may provisional license ang magulang o guardian sa kotse?","o":["9 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito isang oras bago ang hatinggabi.","h2":"Ang may provisional license sa Hawaii na nagmamaneho mula 11 p.m. hanggang 5 a.m. ay dapat may katabing lisensyadong magulang o guardian, maliban kung may exception.","p":"Tama. Ang limitasyon sa gabi ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Hawaii، في أي ساعات يحتاج حامل الرخصة المؤقتة إلى أحد الوالدين أو الوصي في السيارة؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"حامل الرخصة المؤقتة في Hawaii الذي يقود بين 11 مساءً و5 صباحًا يجب أن يكون بجانبه أحد الوالدين أو وصي يحمل رخصة قيادة، إلا إذا انطبق استثناء.","p":"صحيح. حدّ الليل من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"HI","page":14}},{"id":"hi-007","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, who must ride beside a provisional licensee driving late at night?","o":["A licensed parent or guardian","Any passenger over 16","Any licensed friend","A driving school teacher only"],"h1":"It is a family adult who is responsible for the teen.","h2":"In Hawaii, a provisional licensee driving between 11 p.m. and 5 a.m. must have a licensed parent or guardian in the seat beside them.","p":"Right. A licensed parent or guardian rides along."},"es":{"q":"En Hawái, ¿quién debe ir al lado de un conductor con licencia provisional que maneja tarde en la noche?","o":["Su padre, madre o tutor con licencia","Cualquier pasajero mayor de 16","Cualquier amigo con licencia","Solo un instructor de manejo"],"h1":"Es un adulto de la familia que responde por el adolescente.","h2":"En Hawái, un conductor con licencia provisional que maneja entre las 11 p.m. y las 5 a.m. debe llevar al lado a su padre, madre o tutor con licencia.","p":"Correcto. Lo acompaña su padre, madre o tutor con licencia."},"zh":{"q":"在 Hawaii，持过渡驾照的人深夜开车时，谁必须坐在旁边？","o":["有驾照的父母或监护人","任何 16 岁以上的乘客","任何有驾照的朋友","只能是驾校老师"],"h1":"是对这个青少年负责的家里的成年人。","h2":"在 Hawaii，持过渡驾照的人在晚上 11 点到早上 5 点之间开车时，旁边的座位必须坐着一位有驾照的父母或监护人。","p":"对。要有一位有驾照的父母或监护人一起坐车。"},"vi":{"q":"Ở Hawaii, ai phải ngồi bên cạnh người có bằng lái tạm thời khi lái xe khuya?","o":["Cha mẹ hoặc người giám hộ có bằng lái","Bất kỳ hành khách nào trên 16 tuổi","Bất kỳ người bạn nào có bằng lái","Chỉ giáo viên trường dạy lái xe"],"h1":"Đó là người lớn trong gia đình chịu trách nhiệm về thiếu niên.","h2":"Ở Hawaii, người có bằng lái tạm thời lái xe từ 11 giờ tối đến 5 giờ sáng phải có cha mẹ hoặc người giám hộ có bằng lái ngồi ở ghế bên cạnh.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái đi cùng."},"tl":{"q":"Sa Hawaii, sino ang dapat katabi ng may provisional license na nagmamaneho nang hatinggabi?","o":["Isang lisensyadong magulang o guardian","Kahit sinong pasahero na higit sa 16","Kahit sinong kaibigang may lisensya","Guro lang ng driving school"],"h1":"Isa itong adult sa pamilya na responsable sa teenager.","h2":"Sa Hawaii, ang may provisional license na nagmamaneho mula 11 p.m. hanggang 5 a.m. ay dapat may katabing lisensyadong magulang o guardian.","p":"Tama. Kasama ang lisensyadong magulang o guardian."},"ar":{"q":"في Hawaii، من يجب أن يجلس بجانب حامل الرخصة المؤقتة الذي يقود في وقت متأخر من الليل؟","o":["أحد الوالدين أو وصي يحمل رخصة قيادة","أي راكب عمره فوق 16 سنة","أي صديق يحمل رخصة قيادة","معلّم مدرسة قيادة فقط"],"h1":"هو شخص بالغ من العائلة مسؤول عن المراهق.","h2":"في Hawaii، حامل الرخصة المؤقتة الذي يقود بين 11 مساءً و5 صباحًا يجب أن يكون بجانبه أحد الوالدين أو وصي يحمل رخصة قيادة.","p":"صحيح. يرافقك أحد الوالدين أو وصي يحمل رخصة."},"ref":{"doc":"HI","page":14}},{"id":"hi-008","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, when may a provisional licensee drive alone after 11 p.m.?","o":["Any time they feel awake","When going to a friend's house","When the roads are empty","Going straight to or from work, with a note from the employer in the car"],"h1":"Think of a trip that has paperwork behind it.","h2":"A Hawaii provisional licensee may drive alone at night when going directly to or from work, with documentation from the employer kept in the vehicle.","p":"Right. Work trips with a note are allowed."},"es":{"q":"En Hawái, ¿cuándo puede un conductor con licencia provisional manejar solo después de las 11 p.m.?","o":["Cuando se sienta despierto","Cuando va a la casa de un amigo","Cuando las calles están vacías","Directo al trabajo o de regreso, con una nota del empleador en el carro"],"h1":"Piense en un viaje que tiene un papel que lo respalda.","h2":"Un conductor con licencia provisional en Hawái puede manejar solo de noche cuando va directo al trabajo o regresa de él, con un documento del empleador dentro del vehículo.","p":"Correcto. Los viajes al trabajo con una nota están permitidos."},"zh":{"q":"在 Hawaii，持过渡驾照的人什么时候可以在晚上 11 点以后一个人开车？","o":["只要觉得不困，任何时候都可以","去朋友家的时候","路上没车的时候","直接去上班或下班回家，车里放着雇主写的证明"],"h1":"想一想哪种出行有书面文件支持。","h2":"在 Hawaii，持过渡驾照的人直接去上班或下班回家时，可以在夜里一个人开车，但车里要放着雇主开的证明文件。","p":"对。带着证明去上下班是可以的。"},"vi":{"q":"Ở Hawaii, khi nào người có bằng lái tạm thời được lái xe một mình sau 11 giờ tối?","o":["Bất cứ lúc nào họ thấy tỉnh táo","Khi đi đến nhà bạn","Khi đường vắng","Khi đi thẳng đến hoặc về từ chỗ làm, có giấy của chủ lao động trong xe"],"h1":"Hãy nghĩ đến một chuyến đi có giấy tờ chứng minh.","h2":"Ở Hawaii, người có bằng lái tạm thời được lái xe một mình vào ban đêm khi đi thẳng đến hoặc về từ chỗ làm, có giấy tờ của chủ lao động để trong xe.","p":"Đúng. Đi làm có giấy chứng nhận thì được phép."},"tl":{"q":"Sa Hawaii, kailan puwedeng magmaneho nang mag-isa ang may provisional license pagkalipas ng 11 p.m.?","o":["Kahit kailan basta gising pa sila","Kapag pupunta sa bahay ng kaibigan","Kapag walang laman ang daan","Diretso papunta o pauwi galing trabaho, may sulat mula sa employer sa kotse"],"h1":"Isipin ang biyahe na may papeles na patunay.","h2":"Ang may provisional license sa Hawaii ay puwedeng magmaneho nang mag-isa sa gabi kapag diretso papunta o pauwi galing trabaho, may dokumento mula sa employer na nasa sasakyan.","p":"Tama. Puwede ang biyahe sa trabaho kung may sulat."},"ar":{"q":"في Hawaii، متى يجوز لحامل الرخصة المؤقتة أن يقود وحده بعد 11 مساءً؟","o":["في أي وقت يشعر فيه أنه مستيقظ","عند الذهاب إلى بيت صديق","عندما تكون الطرق فارغة","عند الذهاب مباشرة إلى العمل أو العودة منه، مع ورقة من صاحب العمل في السيارة"],"h1":"فكّر في رحلة وراءها أوراق رسمية.","h2":"يجوز لحامل الرخصة المؤقتة في Hawaii أن يقود وحده في الليل عند الذهاب مباشرة إلى العمل أو العودة منه، مع وثيقة من صاحب العمل محفوظة في السيارة.","p":"صحيح. رحلات العمل مع ورقة مسموح بها."},"ref":{"doc":"HI","page":14}},{"id":"hi-009","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, how many passengers under 18 may a provisional licensee carry without a parent or guardian?","o":["None at all","One, unless the others live in the same household","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"Without a parent or guardian along, a Hawaii provisional licensee may carry no more than one person under 18, unless the others are household members.","p":"Right. Only one young passenger from outside the home."},"es":{"q":"En Hawái, ¿cuántos pasajeros menores de 18 puede llevar un conductor con licencia provisional sin su padre, madre o tutor?","o":["Ninguno","Uno, salvo que los demás vivan en la misma casa","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Sin su padre, madre o tutor en el carro, un conductor con licencia provisional en Hawái puede llevar como máximo a una persona menor de 18, salvo que los demás vivan en su misma casa.","p":"Correcto. Solo un pasajero joven de fuera de la casa."},"zh":{"q":"在 Hawaii，没有父母或监护人在车上时，持过渡驾照的人可以载几个 18 岁以下的乘客？","o":["一个都不可以","一个，除非其他人和司机住在同一个家里","两个","三个"],"h1":"数一数，只用一根手指。","h2":"在 Hawaii，没有父母或监护人陪同时，持过渡驾照的人最多只能载一个 18 岁以下的人，除非其他人是同一个家里的成员。","p":"对。家以外的年轻乘客只能载一个。"},"vi":{"q":"Ở Hawaii, người có bằng lái tạm thời được chở bao nhiêu hành khách dưới 18 tuổi khi không có cha mẹ hoặc người giám hộ?","o":["Không ai cả","Một người, trừ khi những người khác sống cùng nhà","Hai người","Ba người"],"h1":"Đếm trên một bàn tay, và chỉ dùng một ngón.","h2":"Khi không có cha mẹ hoặc người giám hộ đi cùng, người có bằng lái tạm thời ở Hawaii chỉ được chở tối đa một người dưới 18 tuổi, trừ khi những người khác sống cùng nhà.","p":"Đúng. Chỉ một hành khách trẻ không sống cùng nhà."},"tl":{"q":"Sa Hawaii, ilang pasaherong wala pang 18 ang puwedeng isakay ng may provisional license kung walang magulang o guardian?","o":["Wala talaga","Isa, maliban kung nakatira sa parehong bahay ang iba","Dalawa","Tatlo"],"h1":"Bumilang sa isang kamay, at isang daliri lang ang gamitin.","h2":"Kung walang kasamang magulang o guardian, ang may provisional license sa Hawaii ay puwedeng magsakay ng hindi hihigit sa isang taong wala pang 18, maliban kung kasama sa bahay ang iba.","p":"Tama. Isang batang pasahero lang mula sa labas ng bahay."},"ar":{"q":"في Hawaii، كم راكبًا عمره أقل من 18 سنة يجوز لحامل الرخصة المؤقتة أن ينقل دون أحد الوالدين أو الوصي؟","o":["لا أحد أبدًا","واحد، إلا إذا كان الآخرون يسكنون في نفس البيت","اثنان","ثلاثة"],"h1":"عُدّ على يد واحدة، واستخدم إصبعًا واحدًا فقط.","h2":"دون مرافقة أحد الوالدين أو الوصي، لا يجوز لحامل الرخصة المؤقتة في Hawaii أن ينقل أكثر من شخص واحد عمره أقل من 18 سنة، إلا إذا كان الآخرون من أهل البيت.","p":"صحيح. راكب صغير واحد فقط من خارج البيت."},"ref":{"doc":"HI","page":13}},{"id":"hi-010","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, which young passengers do not count toward a provisional licensee's passenger limit?","o":["Classmates","Teammates","Members of the driver's household","Neighbors"],"h1":"Think of the people who live under the same roof.","h2":"In Hawaii, passengers under 18 who are members of the provisional licensee's household do not count toward the one-passenger limit.","p":"Right. People from your own home do not count."},"es":{"q":"En Hawái, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de un conductor con licencia provisional?","o":["Compañeros de clase","Compañeros de equipo","Personas que viven en la casa del conductor","Vecinos"],"h1":"Piense en las personas que viven bajo el mismo techo.","h2":"En Hawái, los pasajeros menores de 18 que viven en la casa del conductor con licencia provisional no cuentan en el límite de un pasajero.","p":"Correcto. Las personas de su propia casa no cuentan."},"zh":{"q":"在 Hawaii，哪些年轻乘客不算在持过渡驾照的人的乘客人数限制里？","o":["同班同学","队友","和司机住在同一个家里的人","邻居"],"h1":"想一想住在同一个屋顶下的人。","h2":"在 Hawaii，和持过渡驾照的人住在同一个家里、18 岁以下的乘客，不算在一名乘客的限制里。","p":"对。你自己家里的人不算。"},"vi":{"q":"Ở Hawaii, những hành khách trẻ nào không bị tính vào giới hạn hành khách của người có bằng lái tạm thời?","o":["Bạn cùng lớp","Bạn cùng đội","Người sống cùng nhà với tài xế","Hàng xóm"],"h1":"Hãy nghĩ đến những người sống dưới cùng một mái nhà.","h2":"Ở Hawaii, hành khách dưới 18 tuổi sống cùng nhà với người có bằng lái tạm thời không bị tính vào giới hạn một hành khách.","p":"Đúng. Người trong nhà bạn không bị tính."},"tl":{"q":"Sa Hawaii, aling mga batang pasahero ang hindi binibilang sa limitasyon ng pasahero ng may provisional license?","o":["Mga kaklase","Mga kasama sa team","Mga kasama sa bahay ng driver","Mga kapitbahay"],"h1":"Isipin ang mga taong nakatira sa iisang bubong.","h2":"Sa Hawaii, ang mga pasaherong wala pang 18 na kasama sa bahay ng may provisional license ay hindi binibilang sa limitasyong isang pasahero.","p":"Tama. Hindi binibilang ang mga tao mula sa sarili mong bahay."},"ar":{"q":"في Hawaii، أي الركاب الصغار لا يُحسبون ضمن حدّ الركاب لحامل الرخصة المؤقتة؟","o":["زملاء الصف","زملاء الفريق","أفراد بيت السائق","الجيران"],"h1":"فكّر في الناس الذين يعيشون تحت سقف واحد.","h2":"في Hawaii، الركاب الذين عمرهم أقل من 18 سنة ومن أفراد بيت حامل الرخصة المؤقتة لا يُحسبون ضمن حدّ الراكب الواحد.","p":"صحيح. الناس من بيتك لا يُحسبون."},"ref":{"doc":"HI","page":13}},{"id":"hi-011","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, may an adult driver hold a phone and use it while driving?","o":["No, using a mobile electronic device while driving is banned","Yes, at any speed","Yes, but only on the highway","Yes, if no police are around"],"h1":"The rule covers every driver, not only teens.","h2":"Hawaii law says no person may drive a motor vehicle while using a mobile electronic device, so you must not hold and use your phone while driving.","p":"Right. Put the phone down while you drive."},"es":{"q":"En Hawái, ¿puede un conductor adulto sostener y usar un teléfono mientras maneja?","o":["No, usar un aparato electrónico móvil mientras maneja está prohibido","Sí, a cualquier velocidad","Sí, pero solo en la autopista","Sí, si no hay policía cerca"],"h1":"La regla es para todos los conductores, no solo los jóvenes.","h2":"La ley de Hawái dice que nadie puede manejar un vehículo mientras usa un aparato electrónico móvil, así que usted no debe sostener ni usar su teléfono al manejar.","p":"Correcto. Deje el teléfono mientras maneja."},"zh":{"q":"在 Hawaii，成年司机开车时可以手拿手机使用吗？","o":["不可以，开车时禁止使用移动电子设备","可以，什么速度都可以","可以，但只能在高速公路上","可以，只要附近没有警察"],"h1":"这个规定适用于所有司机，不只是青少年。","h2":"Hawaii 法律规定，任何人开车时都不能使用移动电子设备，所以你开车时不能手拿手机使用。","p":"对。开车时把手机放下。"},"vi":{"q":"Ở Hawaii, tài xế người lớn có được cầm điện thoại và dùng nó khi lái xe không?","o":["Không, cấm dùng thiết bị điện tử di động khi lái xe","Có, ở bất kỳ tốc độ nào","Có, nhưng chỉ trên xa lộ","Có, nếu không có cảnh sát gần đó"],"h1":"Luật này áp dụng cho mọi tài xế, không chỉ thiếu niên.","h2":"Luật Hawaii nói không ai được lái xe cơ giới trong khi dùng thiết bị điện tử di động, nên bạn không được cầm và dùng điện thoại khi lái xe.","p":"Đúng. Hãy bỏ điện thoại xuống khi lái xe."},"tl":{"q":"Sa Hawaii, puwede bang hawakan at gamitin ng adult na driver ang telepono habang nagmamaneho?","o":["Hindi, bawal gumamit ng mobile electronic device habang nagmamaneho","Oo, sa kahit anong bilis","Oo, pero sa highway lang","Oo, kung walang pulis sa paligid"],"h1":"Para sa lahat ng driver ang patakaran, hindi lang sa mga teenager.","h2":"Sinasabi ng batas ng Hawaii na walang taong puwedeng magmaneho ng sasakyan habang gumagamit ng mobile electronic device, kaya hindi mo dapat hawakan at gamitin ang telepono habang nagmamaneho.","p":"Tama. Ibaba ang telepono habang nagmamaneho."},"ar":{"q":"في Hawaii، هل يجوز للسائق البالغ أن يمسك الهاتف ويستخدمه أثناء القيادة؟","o":["لا، استخدام جهاز إلكتروني محمول أثناء القيادة ممنوع","نعم، بأي سرعة","نعم، لكن على الطريق السريع فقط","نعم، إذا لم تكن الشرطة قريبة"],"h1":"القاعدة تشمل كل السائقين، وليس المراهقين فقط.","h2":"يقول قانون Hawaii إنه لا يجوز لأي شخص أن يقود مركبة وهو يستخدم جهازًا إلكترونيًا محمولًا، لذلك يجب ألا تمسك هاتفك وتستخدمه أثناء القيادة.","p":"صحيح. ضع الهاتف جانبًا وأنت تقود."},"ref":{"doc":"HI","page":null}},{"id":"hi-012","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, may a 17-year-old driver use a hands-free phone while driving?","o":["Yes, any time","Yes, but only for music","Yes, if a parent is in the car","No, drivers under 18 may not use even a hands-free device"],"h1":"The rule for teens is stricter than the rule for adults.","h2":"In Hawaii, a driver under 18 may not use a hands-free mobile electronic device while driving, except to call 911.","p":"Right. Under 18, no phone at all while driving."},"es":{"q":"En Hawái, ¿puede un conductor de 17 años usar un teléfono de manos libres mientras maneja?","o":["Sí, en cualquier momento","Sí, pero solo para música","Sí, si va un padre en el carro","No, los menores de 18 no pueden usar ni siquiera un aparato de manos libres"],"h1":"La regla para jóvenes es más estricta que para adultos.","h2":"En Hawái, un conductor menor de 18 no puede usar un aparato electrónico móvil de manos libres mientras maneja, salvo para llamar al 911.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"zh":{"q":"在 Hawaii，17 岁的司机开车时可以用免提手机吗？","o":["可以，任何时候都可以","可以，但只能听音乐","可以，只要父母在车上","不可以，18 岁以下的司机连免提设备也不能用"],"h1":"对青少年的规定比对成年人更严格。","h2":"在 Hawaii，18 岁以下的司机开车时不能使用免提移动电子设备，只有打 911 除外。","p":"对。18 岁以下，开车时完全不能用手机。"},"vi":{"q":"Ở Hawaii, tài xế 17 tuổi có được dùng điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, bất cứ lúc nào","Có, nhưng chỉ để nghe nhạc","Có, nếu cha mẹ ngồi trong xe","Không, tài xế dưới 18 tuổi không được dùng cả thiết bị rảnh tay"],"h1":"Luật cho thiếu niên nghiêm hơn luật cho người lớn.","h2":"Ở Hawaii, tài xế dưới 18 tuổi không được dùng thiết bị điện tử di động rảnh tay khi lái xe, trừ khi gọi 911.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại chút nào khi lái xe."},"tl":{"q":"Sa Hawaii, puwede bang gumamit ng hands-free na telepono ang 17 taong gulang na driver habang nagmamaneho?","o":["Oo, kahit kailan","Oo, pero para sa musika lang","Oo, kung may magulang sa kotse","Hindi, ang mga driver na wala pang 18 ay hindi puwedeng gumamit kahit ng hands-free device"],"h1":"Mas mahigpit ang patakaran para sa teenager kaysa sa adult.","h2":"Sa Hawaii, ang driver na wala pang 18 ay hindi puwedeng gumamit ng hands-free mobile electronic device habang nagmamaneho, maliban sa pagtawag sa 911.","p":"Tama. Kung wala pang 18, bawal ang telepono habang nagmamaneho."},"ar":{"q":"في Hawaii، هل يجوز لسائق عمره 17 سنة أن يستخدم هاتفًا دون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، في أي وقت","نعم، لكن للموسيقى فقط","نعم، إذا كان أحد الوالدين في السيارة","لا، السائقون تحت 18 سنة لا يجوز لهم استخدام حتى جهاز دون استخدام اليدين"],"h1":"القاعدة للمراهقين أشدّ من القاعدة للبالغين.","h2":"في Hawaii، لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم جهازًا إلكترونيًا محمولًا دون استخدام اليدين أثناء القيادة، إلا للاتصال بالرقم 911.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء القيادة."},"ref":{"doc":"HI","page":null}},{"id":"hi-013","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, for what reason may a driver under 18 use a hands-free phone while driving?","o":["To answer a parent's text","To call 911 in an emergency","To check a map","To talk with a friend"],"h1":"It is the number you call when someone needs help right away.","h2":"A Hawaii driver under 18 may use a hands-free device while driving only to make a 911 emergency call.","p":"Right. Only a 911 emergency call."},"es":{"q":"En Hawái, ¿por qué razón puede un conductor menor de 18 usar un teléfono de manos libres al manejar?","o":["Para contestar un mensaje de sus padres","Para llamar al 911 en una emergencia","Para ver un mapa","Para hablar con un amigo"],"h1":"Es el número al que se llama cuando alguien necesita ayuda de inmediato.","h2":"Un conductor menor de 18 en Hawái solo puede usar un aparato de manos libres al manejar para hacer una llamada de emergencia al 911.","p":"Correcto. Solo una llamada de emergencia al 911."},"zh":{"q":"在 Hawaii，18 岁以下的司机开车时，因为什么原因可以用免提手机？","o":["回复父母的短信","在紧急情况下打 911","看地图","和朋友聊天"],"h1":"这是有人马上需要帮助时要打的号码。","h2":"在 Hawaii，18 岁以下的司机开车时只能用免提设备打 911 紧急电话。","p":"对。只能打 911 紧急电话。"},"vi":{"q":"Ở Hawaii, tài xế dưới 18 tuổi được dùng điện thoại rảnh tay khi lái xe vì lý do nào?","o":["Để trả lời tin nhắn của cha mẹ","Để gọi 911 khi khẩn cấp","Để xem bản đồ","Để nói chuyện với bạn"],"h1":"Đó là số bạn gọi khi có người cần giúp ngay.","h2":"Ở Hawaii, tài xế dưới 18 tuổi chỉ được dùng thiết bị rảnh tay khi lái xe để gọi 911 khẩn cấp.","p":"Đúng. Chỉ được gọi 911 khi khẩn cấp."},"tl":{"q":"Sa Hawaii, sa anong dahilan puwedeng gumamit ng hands-free na telepono ang driver na wala pang 18 habang nagmamaneho?","o":["Para sagutin ang text ng magulang","Para tumawag sa 911 sa emergency","Para tumingin ng mapa","Para makipag-usap sa kaibigan"],"h1":"Ito ang numerong tinatawagan kapag may nangangailangan agad ng tulong.","h2":"Ang driver sa Hawaii na wala pang 18 ay puwedeng gumamit ng hands-free device habang nagmamaneho para lang sa emergency na tawag sa 911.","p":"Tama. Emergency na tawag sa 911 lang."},"ar":{"q":"في Hawaii، لأي سبب يجوز للسائق تحت 18 سنة أن يستخدم هاتفًا دون استخدام اليدين أثناء القيادة؟","o":["للردّ على رسالة من أحد الوالدين","للاتصال بالرقم 911 في حالة طوارئ","للنظر في خريطة","للتحدث مع صديق"],"h1":"هو الرقم الذي تتصل به عندما يحتاج أحد إلى مساعدة فورًا.","h2":"يجوز للسائق في Hawaii الذي عمره أقل من 18 سنة أن يستخدم جهازًا دون استخدام اليدين أثناء القيادة فقط لإجراء اتصال طوارئ بالرقم 911.","p":"صحيح. فقط اتصال طوارئ بالرقم 911."},"ref":{"doc":"HI","page":null}},{"id":"hi-014","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where is the fine for using a phone while driving higher?","o":["On rural roads","In parking lots","In a school zone or a construction area","On the freeway at night"],"h1":"Think of places where children or road workers are close by.","h2":"In Hawaii, the fine for using a mobile device while driving is higher in a school zone or a construction area.","p":"Right. School zones and work zones cost more."},"es":{"q":"En Hawái, ¿dónde es más alta la multa por usar el teléfono mientras maneja?","o":["En caminos rurales","En estacionamientos","En una zona escolar o una zona de construcción","En la autopista de noche"],"h1":"Piense en lugares donde hay niños o trabajadores cerca.","h2":"En Hawái, la multa por usar un aparato móvil mientras maneja es más alta en una zona escolar o una zona de construcción.","p":"Correcto. Las zonas escolares y de obras cuestan más."},"zh":{"q":"在 Hawaii，在哪里开车用手机罚款更高？","o":["在乡村道路上","在停车场","在学校区域或施工区","晚上在高速公路上"],"h1":"想一想附近有小孩或道路工人的地方。","h2":"在 Hawaii，在学校区域或施工区开车时使用移动设备，罚款更高。","p":"对。学校区域和施工区罚得更多。"},"vi":{"q":"Ở Hawaii, tiền phạt dùng điện thoại khi lái xe cao hơn ở đâu?","o":["Trên đường nông thôn","Trong bãi đậu xe","Trong khu vực trường học hoặc khu công trường","Trên xa lộ vào ban đêm"],"h1":"Hãy nghĩ đến những nơi có trẻ em hoặc công nhân làm đường ở gần.","h2":"Ở Hawaii, tiền phạt dùng thiết bị di động khi lái xe cao hơn trong khu vực trường học hoặc khu công trường.","p":"Đúng. Khu vực trường học và khu công trường bị phạt nặng hơn."},"tl":{"q":"Sa Hawaii, saan mas mataas ang multa sa paggamit ng telepono habang nagmamaneho?","o":["Sa mga daan sa probinsya","Sa mga parking lot","Sa school zone o construction area","Sa freeway sa gabi"],"h1":"Isipin ang mga lugar na malapit ang mga bata o mga trabahador sa daan.","h2":"Sa Hawaii, mas mataas ang multa sa paggamit ng mobile device habang nagmamaneho sa school zone o construction area.","p":"Tama. Mas mahal ang multa sa school zone at work zone."},"ar":{"q":"في Hawaii، أين تكون غرامة استخدام الهاتف أثناء القيادة أعلى؟","o":["على الطرق الريفية","في مواقف السيارات","في منطقة مدرسة أو منطقة أعمال بناء","على الطريق السريع في الليل"],"h1":"فكّر في أماكن يكون فيها أطفال أو عمّال طرق قريبين.","h2":"في Hawaii، غرامة استخدام جهاز محمول أثناء القيادة أعلى في منطقة مدرسة أو منطقة أعمال بناء.","p":"صحيح. مناطق المدارس ومناطق الأعمال غرامتها أعلى."},"ref":{"doc":"HI","page":null}},{"id":"hi-015","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what is the usual fine for using a mobile device while driving?","o":["$300","$25","$50","$1,000"],"h1":"It is a few hundred dollars.","h2":"In Hawaii the usual fine for using a mobile electronic device while driving is $300.","p":"Right. The usual fine is $300."},"es":{"q":"En Hawái, ¿cuál es la multa normal por usar un aparato móvil mientras maneja?","o":["$300","$25","$50","$1,000"],"h1":"Son unos cientos de dólares.","h2":"En Hawái la multa normal por usar un aparato electrónico móvil mientras maneja es de $300.","p":"Correcto. La multa normal es de $300."},"zh":{"q":"在 Hawaii，开车时使用移动设备，一般罚款多少？","o":["$300","$25","$50","$1,000"],"h1":"是几百美元。","h2":"在 Hawaii，开车时使用移动电子设备，一般罚款 $300。","p":"对。一般罚款是 $300。"},"vi":{"q":"Ở Hawaii, tiền phạt thông thường khi dùng thiết bị di động lúc lái xe là bao nhiêu?","o":["$300","$25","$50","$1,000"],"h1":"Đó là vài trăm đô la.","h2":"Ở Hawaii, tiền phạt thông thường khi dùng thiết bị điện tử di động lúc lái xe là $300.","p":"Đúng. Tiền phạt thông thường là $300."},"tl":{"q":"Sa Hawaii, magkano ang karaniwang multa sa paggamit ng mobile device habang nagmamaneho?","o":["$300","$25","$50","$1,000"],"h1":"Ilang daang dolyar ito.","h2":"Sa Hawaii, ang karaniwang multa sa paggamit ng mobile electronic device habang nagmamaneho ay $300.","p":"Tama. Ang karaniwang multa ay $300."},"ar":{"q":"في Hawaii، ما الغرامة المعتادة لاستخدام جهاز محمول أثناء القيادة؟","o":["$300","$25","$50","$1,000"],"h1":"هي بضع مئات من الدولارات.","h2":"في Hawaii، الغرامة المعتادة لاستخدام جهاز إلكتروني محمول أثناء القيادة هي $300.","p":"صحيح. الغرامة المعتادة هي $300."},"ref":{"doc":"HI","page":null}},{"id":"hi-016","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, what must you do when you approach a stopped emergency vehicle with flashing lights?","o":["Keep your speed and honk","Flash your high beams at it","Speed up to pass it fast","Slow to a safe speed and move to the next lane if it is safe"],"h1":"Give the workers more space and more time.","h2":"Hawaii's move over law says to slow down to a safe and prudent speed and, when it is safe, move into the next lane away from the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Hawái, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido con luces intermitentes?","o":["Mantener la velocidad y tocar la bocina","Hacerle cambio de luces altas","Acelerar para pasarlo rápido","Bajar a una velocidad segura y cambiarse al carril de al lado si es seguro"],"h1":"Dé a los trabajadores más espacio y más tiempo.","h2":"La ley de Hawái para moverse de carril dice que debe bajar a una velocidad segura y prudente y, cuando sea seguro, cambiarse al carril de al lado, lejos del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Hawaii，当你靠近一辆停着、闪着灯的急救车辆时，你必须做什么？","o":["保持速度并按喇叭","对它闪远光灯","加速快点开过去","减速到安全速度，安全的话换到旁边的车道"],"h1":"给工作人员更多空间和更多时间。","h2":"Hawaii 的 move over 法规定，你要减速到安全、谨慎的速度，并在安全时换到离停着的急救车辆远一点的旁边车道。","p":"对。减速并换道让开。"},"vi":{"q":"Ở Hawaii, bạn phải làm gì khi đến gần một xe cấp cứu đang dừng và có đèn nhấp nháy?","o":["Giữ nguyên tốc độ và bấm còi","Nháy đèn pha vào xe đó","Tăng tốc để vượt qua nhanh","Giảm xuống tốc độ an toàn và chuyển sang làn bên cạnh nếu an toàn"],"h1":"Hãy cho nhân viên thêm khoảng cách và thêm thời gian.","h2":"Luật nhường làn (move over law) của Hawaii nói phải giảm xuống tốc độ an toàn và hợp lý, và khi an toàn thì chuyển sang làn bên cạnh, xa xe cấp cứu đang dừng.","p":"Đúng. Giảm tốc độ và chuyển làn."},"tl":{"q":"Sa Hawaii, ano ang dapat mong gawin kapag papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Panatilihin ang bilis at bumusina","I-flash ang high beams mo rito","Bumilis para mabilis itong malampasan","Bumagal sa ligtas na bilis at lumipat sa katabing lane kung ligtas"],"h1":"Bigyan ng mas maraming espasyo at oras ang mga trabahador.","h2":"Sinasabi ng move over law ng Hawaii na bumagal sa ligtas at maingat na bilis at, kapag ligtas, lumipat sa katabing lane palayo sa nakahintong emergency vehicle.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Hawaii، ماذا يجب أن تفعل عندما تقترب من مركبة طوارئ متوقفة وأضواؤها تومض؟","o":["حافظ على سرعتك واضغط على البوق","ومّض لها بالأضواء العالية","زِد السرعة لتتجاوزها بسرعة","خفّف إلى سرعة آمنة وانتقل إلى المسار المجاور إذا كان ذلك آمنًا"],"h1":"أعطِ العمّال مسافة أكبر ووقتًا أكثر.","h2":"يقول قانون الابتعاد (move over law) في Hawaii أن تخفّف السرعة إلى سرعة آمنة وحذرة، وأن تنتقل إلى المسار المجاور بعيدًا عن مركبة الطوارئ المتوقفة عندما يكون ذلك آمنًا.","p":"صحيح. خفّف السرعة وابتعد إلى مسار آخر."},"ref":{"doc":"HI","page":29}},{"id":"hi-017","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, which of these stopped vehicles with flashing lights is also covered by the move over law?","o":["A parked delivery van with no lights","A tow truck","A bus at a bus stop","A taxi waiting for a rider"],"h1":"Think of a truck that helps cars that break down.","h2":"Hawaii's move over law covers tow trucks as well as police, fire, ambulance and ocean safety vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Hawái, ¿cuál de estos vehículos detenidos con luces intermitentes también está cubierto por la ley para moverse de carril?","o":["Una camioneta de reparto estacionada sin luces","Una grúa","Un autobús en la parada","Un taxi esperando a un pasajero"],"h1":"Piense en un camión que ayuda a los carros que se descomponen.","h2":"La ley de Hawái para moverse de carril cubre las grúas, además de los vehículos de policía, bomberos, ambulancia y seguridad en el océano.","p":"Correcto. Las grúas también están cubiertas."},"zh":{"q":"在 Hawaii，下面哪种停着、闪着灯的车辆也受 move over 法保护？","o":["一辆没开灯、停着的送货车","拖车","停在公交车站的公交车","等乘客的出租车"],"h1":"想一想帮助故障车的那种卡车。","h2":"Hawaii 的 move over 法保护拖车，也保护警车、消防车、救护车和海上救援车辆。","p":"对。拖车也受保护。"},"vi":{"q":"Ở Hawaii, xe nào dưới đây đang dừng và có đèn nhấp nháy cũng thuộc luật nhường làn (move over law)?","o":["Xe tải giao hàng đang đậu, không có đèn","Xe kéo (tow truck)","Xe buýt ở trạm xe buýt","Taxi đang chờ khách"],"h1":"Hãy nghĩ đến loại xe tải giúp những xe bị hư.","h2":"Luật nhường làn của Hawaii áp dụng cho xe kéo, cũng như xe cảnh sát, xe cứu hỏa, xe cứu thương và xe cứu hộ biển (ocean safety).","p":"Đúng. Xe kéo cũng được bảo vệ."},"tl":{"q":"Sa Hawaii, alin sa mga nakahintong sasakyang ito na may kumikislap na ilaw ang sakop din ng move over law?","o":["Nakaparadang delivery van na walang ilaw","Tow truck","Bus sa bus stop","Taxi na naghihintay ng pasahero"],"h1":"Isipin ang trak na tumutulong sa mga sasakyang nasira.","h2":"Sakop ng move over law ng Hawaii ang mga tow truck, pati ang mga sasakyan ng pulis, bumbero, ambulansya at ocean safety.","p":"Tama. Sakop din ang mga tow truck."},"ar":{"q":"في Hawaii، أي من هذه المركبات المتوقفة وأضواؤها تومض يشملها أيضًا قانون الابتعاد (move over law)؟","o":["شاحنة توصيل متوقفة بلا أضواء","شاحنة سحب (tow truck)","حافلة في موقف الحافلات","سيارة أجرة تنتظر راكبًا"],"h1":"فكّر في شاحنة تساعد السيارات المعطّلة.","h2":"قانون الابتعاد في Hawaii يشمل شاحنات السحب، وكذلك مركبات الشرطة والإطفاء والإسعاف والسلامة البحرية (ocean safety).","p":"صحيح. شاحنات السحب مشمولة أيضًا."},"ref":{"doc":"HI","page":null}},{"id":"hi-018","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, what is the lowest blood alcohol level that is against the law for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"Hawaii calls this rule zero tolerance.","h2":"In Hawaii it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Hawái, ¿cuál es el nivel más bajo de alcohol en la sangre que es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"En Hawái esta regla se llama tolerancia cero.","h2":"En Hawái es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Hawaii，对 21 岁以下的司机来说，血液酒精浓度最低到多少就违法？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"Hawaii 把这个规定叫做零容忍。","h2":"在 Hawaii，21 岁以下的司机血液酒精浓度达到 0.02% 或更高时开车就是违法的。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Hawaii, nồng độ cồn trong máu thấp nhất là phạm luật đối với tài xế dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Hawaii gọi luật này là không khoan nhượng (zero tolerance).","h2":"Ở Hawaii, tài xế dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Hawaii, ano ang pinakamababang blood alcohol level na labag sa batas para sa driver na wala pang 21?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Tinatawag ito ng Hawaii na zero tolerance.","h2":"Sa Hawaii, labag sa batas para sa driver na wala pang 21 ang magmaneho nang may blood alcohol level na 0.02 porsiyento o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Hawaii، ما أقل نسبة كحول في الدم تكون مخالفة للقانون للسائق تحت 21 سنة؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"تسمّي Hawaii هذه القاعدة عدم التسامح (zero tolerance).","h2":"في Hawaii، من المخالف للقانون أن يقود سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02 بالمئة."},"ref":{"doc":"HI","page":56}},{"id":"hi-020","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, on a road split by a barrier, which drivers must stop for a school bus with flashing red lights?","o":["Only the driver right behind the bus","No one, because the road is divided","Only drivers in the left lane","Drivers in all lanes on the same side as the bus"],"h1":"The barrier protects the other side, not your side.","h2":"In Hawaii, when a road is divided by a barrier, drivers in every lane on the same side as the stopped school bus must stop.","p":"Right. Every lane on the bus's side stops."},"es":{"q":"En Hawái, en una vía dividida por una barrera, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo el conductor justo detrás del autobús","Nadie, porque la vía está dividida","Solo los del carril izquierdo","Los de todos los carriles del mismo lado del autobús"],"h1":"La barrera protege el otro lado, no su lado.","h2":"En Hawái, cuando una vía está dividida por una barrera, los conductores de todos los carriles del mismo lado del autobús escolar detenido deben detenerse.","p":"Correcto. Todos los carriles del lado del autobús se detienen."},"zh":{"q":"在 Hawaii，道路被隔离墩分开时，哪些司机必须为闪着红灯的校车停车？","o":["只有紧跟在校车后面的司机","没有人，因为道路被分开了","只有左车道的司机","和校车在同一边的所有车道上的司机"],"h1":"隔离墩保护的是另一边，不是你这一边。","h2":"在 Hawaii，道路被隔离墩分开时，和停着的校车在同一边的每条车道上的司机都必须停车。","p":"对。校车那一边的每条车道都要停。"},"vi":{"q":"Ở Hawaii, trên con đường có dải phân cách, những tài xế nào phải dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy?","o":["Chỉ tài xế ngay phía sau xe buýt","Không ai cả, vì đường có dải phân cách","Chỉ tài xế ở làn bên trái","Tài xế ở mọi làn cùng phía với xe buýt"],"h1":"Dải phân cách bảo vệ phía bên kia, không phải phía của bạn.","h2":"Ở Hawaii, khi đường có dải phân cách, tài xế ở mọi làn cùng phía với xe buýt trường học đang dừng phải dừng lại.","p":"Đúng. Mọi làn ở phía xe buýt đều phải dừng."},"tl":{"q":"Sa Hawaii, sa daan na hinati ng harang, aling mga driver ang dapat huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Ang driver lang na nasa likod mismo ng bus","Wala, dahil hinati ang daan","Ang mga driver lang sa kaliwang lane","Ang mga driver sa lahat ng lane sa parehong panig ng bus"],"h1":"Pinoprotektahan ng harang ang kabilang panig, hindi ang panig mo.","h2":"Sa Hawaii, kapag hinati ng harang ang daan, dapat huminto ang mga driver sa bawat lane sa parehong panig ng nakahintong school bus.","p":"Tama. Humihinto ang bawat lane sa panig ng bus."},"ar":{"q":"في Hawaii، على طريق يفصله حاجز، أي السائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["فقط السائق الذي خلف الحافلة مباشرة","لا أحد، لأن الطريق مقسوم","فقط السائقون في المسار الأيسر","السائقون في كل المسارات على نفس جهة الحافلة"],"h1":"الحاجز يحمي الجهة الأخرى، وليس جهتك.","h2":"في Hawaii، عندما يكون الطريق مقسومًا بحاجز، يجب أن يتوقف السائقون في كل مسار على نفس جهة الحافلة المدرسية المتوقفة.","p":"صحيح. كل مسار على جهة الحافلة يتوقف."},"ref":{"doc":"HI","page":null}},{"id":"hi-021","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, a crash causes property damage but no injuries. At what amount of damage must it be reported to the police right away?","o":["$1,000 or more","$3,000 or more","$5,000 or more","$10,000 or more"],"h1":"It is more than one thousand and less than five thousand dollars.","h2":"In Hawaii you must report a crash to the police right away if it causes $3,000 or more in property damage.","p":"Right. In Hawaii, $3,000 or more in damage must be reported to the police."},"es":{"q":"En Hawái, un choque causa daños a la propiedad pero no hay heridos. ¿A partir de qué cantidad de daños debe reportarlo de inmediato a la policía?","o":["$1,000 o más","$3,000 o más","$5,000 o más","$10,000 o más"],"h1":"Es más de mil y menos de cinco mil dólares.","h2":"En Hawái usted debe reportar un choque a la policía de inmediato si causa $3,000 o más en daños a la propiedad.","p":"Correcto. En Hawái, los daños de $3,000 o más se deben reportar a la policía."},"zh":{"q":"在 Hawaii，一场车祸造成财产损失，但没有人受伤。损失达到多少时必须马上报警？","o":["$1,000 或以上","$3,000 或以上","$5,000 或以上","$10,000 或以上"],"h1":"它比一千美元多，比五千美元少。","h2":"在 Hawaii，如果车祸造成 $3,000 或以上的财产损失，你必须马上报警。","p":"对。在 Hawaii，$3,000 或以上的损失必须报警。"},"vi":{"q":"Ở Hawaii, một vụ tai nạn làm hư hại tài sản nhưng không ai bị thương. Thiệt hại bao nhiêu thì phải báo cảnh sát ngay?","o":["$1,000 trở lên","$3,000 trở lên","$5,000 trở lên","$10,000 trở lên"],"h1":"Số tiền này nhiều hơn một nghìn và ít hơn năm nghìn đô la.","h2":"Ở Hawaii, bạn phải báo cảnh sát ngay nếu tai nạn gây thiệt hại tài sản từ $3,000 trở lên.","p":"Đúng. Ở Hawaii, thiệt hại từ $3,000 trở lên phải được báo cho cảnh sát."},"tl":{"q":"Sa Hawaii, may banggaan na sumira ng ari-arian pero walang nasaktan. Sa anong halaga ng pinsala dapat itong i-report agad sa pulis?","o":["$1,000 o higit pa","$3,000 o higit pa","$5,000 o higit pa","$10,000 o higit pa"],"h1":"Higit ito sa isang libo at kulang sa limang libong dolyar.","h2":"Sa Hawaii, dapat mong i-report agad sa pulis ang banggaan kung $3,000 o higit pa ang pinsala sa ari-arian.","p":"Tama. Sa Hawaii, dapat i-report sa pulis ang pinsalang $3,000 o higit pa."},"ar":{"q":"في Hawaii، تسبّب حادث في أضرار بالممتلكات دون إصابات. عند أي قيمة للأضرار يجب إبلاغ الشرطة فورًا؟","o":["$1,000 أو أكثر","$3,000 أو أكثر","$5,000 أو أكثر","$10,000 أو أكثر"],"h1":"هي أكثر من ألف دولار وأقل من خمسة آلاف دولار.","h2":"في Hawaii يجب أن تبلّغ الشرطة فورًا عن الحادث إذا سبّب أضرارًا بالممتلكات قيمتها $3,000 أو أكثر.","p":"صحيح. في Hawaii يجب إبلاغ الشرطة عن أضرار قيمتها $3,000 أو أكثر."},"ref":{"doc":"HI","page":52}},{"id":"hi-022","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"The limit for the whole crash is twice this amount, $40,000.","h2":"In Hawaii the minimum liability insurance for injury to one person is $20,000, with $40,000 for the whole crash.","p":"Right. Hawaii requires at least $20,000 for injury to one person."},"es":{"q":"En Hawái, ¿cuál es el seguro mínimo de responsabilidad civil por lesiones a una persona en un choque?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"El límite para todo el choque es el doble de esta cantidad, $40,000.","h2":"En Hawái el seguro mínimo de responsabilidad civil por lesiones a una persona es de $20,000, con $40,000 para todo el choque.","p":"Correcto. Hawái exige al menos $20,000 por lesiones a una persona."},"zh":{"q":"在 Hawaii，车祸中一个人受伤的最低责任保险是多少？","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"整场车祸的上限是这个金额的两倍，也就是 $40,000。","h2":"在 Hawaii，一个人受伤的最低责任保险是 $20,000，整场车祸是 $40,000。","p":"对。Hawaii 要求一个人受伤至少保 $20,000。"},"vi":{"q":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"Mức cho cả vụ tai nạn gấp đôi số tiền này, là $40,000.","h2":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người là $20,000, và $40,000 cho cả vụ tai nạn.","p":"Đúng. Hawaii yêu cầu ít nhất $20,000 cho thương tích của một người."},"tl":{"q":"Sa Hawaii, magkano ang pinakamababang liability insurance para sa pinsala sa katawan ng isang tao sa banggaan?","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"Ang limit para sa buong banggaan ay doble nito, $40,000.","h2":"Sa Hawaii, ang pinakamababang liability insurance para sa pinsala sa isang tao ay $20,000, at $40,000 para sa buong banggaan.","p":"Tama. Sa Hawaii, kailangan ng hindi bababa sa $20,000 para sa pinsala sa isang tao."},"ar":{"q":"في Hawaii، ما الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$15,000","$25,000","$20,000"],"h1":"الحد للحادث كله ضعف هذا المبلغ، أي $40,000.","h2":"في Hawaii الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد هو $20,000، و$40,000 للحادث كله.","p":"صحيح. تشترط Hawaii مبلغ $20,000 على الأقل عن إصابة شخص واحد."},"ref":{"doc":"HI","page":54}},{"id":"hi-023","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"It is the smallest of these amounts.","h2":"In Hawaii the minimum liability insurance for property damage is $10,000 per crash.","p":"Right. Hawaii requires at least $10,000 for property damage."},"es":{"q":"En Hawái, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Es la cantidad más pequeña de estas.","h2":"En Hawái el seguro mínimo de responsabilidad civil por daños a la propiedad es de $10,000 por choque.","p":"Correcto. Hawái exige al menos $10,000 por daños a la propiedad."},"zh":{"q":"在 Hawaii，一场车祸中对他人财产损失的最低责任保险是多少？","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"它是这些金额中最小的。","h2":"在 Hawaii，财产损失的最低责任保险是每场车祸 $10,000。","p":"对。Hawaii 要求财产损失至少保 $10,000。"},"vi":{"q":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Đó là số tiền nhỏ nhất trong các số này.","h2":"Ở Hawaii, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là $10,000 cho mỗi vụ tai nạn.","p":"Đúng. Hawaii yêu cầu ít nhất $10,000 cho thiệt hại tài sản."},"tl":{"q":"Sa Hawaii, magkano ang pinakamababang liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"Ito ang pinakamaliit sa mga halagang ito.","h2":"Sa Hawaii, ang pinakamababang liability insurance para sa pinsala sa ari-arian ay $10,000 bawat banggaan.","p":"Tama. Sa Hawaii, kailangan ng hindi bababa sa $10,000 para sa pinsala sa ari-arian."},"ar":{"q":"في Hawaii، ما الحد الأدنى لتأمين المسؤولية عن أضرار ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$20,000","$25,000","$40,000"],"h1":"هو أصغر هذه المبالغ.","h2":"في Hawaii الحد الأدنى لتأمين المسؤولية عن أضرار الممتلكات هو $10,000 لكل حادث.","p":"صحيح. تشترط Hawaii مبلغ $10,000 على الأقل عن أضرار الممتلكات."},"ref":{"doc":"HI","page":54}},{"id":"hi-024","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how often must a regular car pass a safety inspection?","o":["Only when it is sold","Every two years","At least once a year","Every six months"],"h1":"Only ambulances need it more often than this.","h2":"In Hawaii a car must pass a safety inspection at least once a year, though a brand-new car gets a longer first period.","p":"Right. Hawaii cars need a safety inspection at least once a year."},"es":{"q":"En Hawái, ¿cada cuánto tiempo debe pasar un auto común una inspección de seguridad?","o":["Solo cuando se vende","Cada dos años","Por lo menos una vez al año","Cada seis meses"],"h1":"Solo las ambulancias la necesitan con más frecuencia.","h2":"En Hawái un auto debe pasar una inspección de seguridad por lo menos una vez al año, aunque un auto nuevo tiene un primer plazo más largo.","p":"Correcto. En Hawái los autos necesitan una inspección de seguridad por lo menos una vez al año."},"zh":{"q":"在 Hawaii，一般汽车多久必须通过一次安全检查？","o":["只在卖车时","每两年一次","至少每年一次","每六个月一次"],"h1":"只有救护车需要比这更常检查。","h2":"在 Hawaii，汽车至少每年必须通过一次安全检查，不过全新的车第一次可以隔更久。","p":"对。Hawaii 的汽车至少每年要做一次安全检查。"},"vi":{"q":"Ở Hawaii, một chiếc xe hơi thông thường phải qua kiểm tra an toàn bao lâu một lần?","o":["Chỉ khi bán xe","Hai năm một lần","Ít nhất mỗi năm một lần","Sáu tháng một lần"],"h1":"Chỉ xe cứu thương cần kiểm tra thường xuyên hơn mức này.","h2":"Ở Hawaii, xe hơi phải qua kiểm tra an toàn ít nhất mỗi năm một lần, nhưng xe mới hoàn toàn được thời hạn đầu tiên dài hơn.","p":"Đúng. Ở Hawaii, xe hơi cần kiểm tra an toàn ít nhất mỗi năm một lần."},"tl":{"q":"Sa Hawaii, gaano kadalas dapat pumasa sa safety inspection ang isang karaniwang kotse?","o":["Kapag ibinebenta lang ito","Tuwing dalawang taon","Hindi bababa sa isang beses bawat taon","Tuwing anim na buwan"],"h1":"Mga ambulansya lang ang kailangang mas madalas dito.","h2":"Sa Hawaii, dapat pumasa ang kotse sa safety inspection nang hindi bababa sa isang beses bawat taon, pero mas mahaba ang unang panahon para sa bagong-bagong kotse.","p":"Tama. Sa Hawaii, kailangan ng kotse ang safety inspection nang hindi bababa sa isang beses bawat taon."},"ar":{"q":"في Hawaii، كم مرة يجب أن تجتاز السيارة العادية فحص السلامة؟","o":["فقط عند بيعها","كل سنتين","مرة واحدة في السنة على الأقل","كل ستة أشهر"],"h1":"سيارات الإسعاف فقط تحتاجه أكثر من ذلك.","h2":"في Hawaii يجب أن تجتاز السيارة فحص السلامة مرة واحدة في السنة على الأقل، لكن السيارة الجديدة تمامًا تحصل على مدة أولى أطول.","p":"صحيح. في Hawaii تحتاج السيارات إلى فحص السلامة مرة واحدة في السنة على الأقل."},"ref":{"doc":"HI","page":18}},{"id":"hi-025","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, your driver's license expired yesterday. May you still drive on it?","o":["Yes, for a 30-day grace period","No, it is not valid after it expires","Yes, until you get a renewal notice","Yes, if you renew within one year"],"h1":"Hawaii gives no extra time to drive after the date on the license.","h2":"In Hawaii a driver's license is not valid after its expiration date, because there is no grace period.","p":"Right. Hawaii has no grace period, so an expired license is not valid."},"es":{"q":"En Hawái, su licencia de conducir venció ayer. ¿Puede seguir manejando con ella?","o":["Sí, durante un periodo de gracia de 30 días","No, no es válida después de vencer","Sí, hasta que reciba un aviso de renovación","Sí, si la renueva dentro de un año"],"h1":"Hawái no da tiempo extra para manejar después de la fecha de la licencia.","h2":"En Hawái una licencia de conducir no es válida después de su fecha de vencimiento, porque no hay periodo de gracia.","p":"Correcto. Hawái no tiene periodo de gracia, así que una licencia vencida no es válida."},"zh":{"q":"在 Hawaii，你的驾照昨天过期了。你还可以用它开车吗？","o":["可以，有 30 天的宽限期","不可以，过期后就无效了","可以，直到你收到续期通知","可以，只要你在一年内续期"],"h1":"驾照上的日期过了以后，Hawaii 不给你额外的开车时间。","h2":"在 Hawaii，驾照过了到期日就无效，因为没有宽限期。","p":"对。Hawaii 没有宽限期，所以过期的驾照无效。"},"vi":{"q":"Ở Hawaii, bằng lái của bạn hết hạn hôm qua. Bạn còn được dùng nó để lái xe không?","o":["Được, có thời gian gia hạn 30 ngày","Không, bằng lái không còn hiệu lực sau khi hết hạn","Được, cho đến khi bạn nhận thông báo gia hạn","Được, nếu bạn gia hạn trong vòng một năm"],"h1":"Hawaii không cho thêm thời gian lái xe sau ngày ghi trên bằng lái.","h2":"Ở Hawaii, bằng lái không còn hiệu lực sau ngày hết hạn, vì không có thời gian ân hạn.","p":"Đúng. Hawaii không có thời gian ân hạn, nên bằng lái hết hạn không còn hiệu lực."},"tl":{"q":"Sa Hawaii, nag-expire kahapon ang driver's license mo. Puwede ka pa bang magmaneho gamit ito?","o":["Oo, may 30 araw na palugit","Hindi, wala na itong bisa pagkatapos mag-expire","Oo, hanggang makatanggap ka ng renewal notice","Oo, kung magre-renew ka sa loob ng isang taon"],"h1":"Walang dagdag na oras ang Hawaii para magmaneho pagkatapos ng petsa sa license.","h2":"Sa Hawaii, wala nang bisa ang driver's license pagkatapos ng expiration date nito, dahil walang palugit.","p":"Tama. Walang palugit sa Hawaii, kaya walang bisa ang expired na license."},"ar":{"q":"في Hawaii، انتهت رخصة قيادتك أمس. هل يمكنك أن تقود بها بعد؟","o":["نعم، توجد مهلة 30 يومًا","لا، لا تكون صالحة بعد انتهائها","نعم، حتى يصلك إشعار التجديد","نعم، إذا جدّدتها خلال سنة واحدة"],"h1":"لا تعطي Hawaii وقتًا إضافيًا للقيادة بعد التاريخ المكتوب على الرخصة.","h2":"في Hawaii لا تكون رخصة القيادة صالحة بعد تاريخ انتهائها، لأنه لا توجد مهلة.","p":"صحيح. لا توجد مهلة في Hawaii، لذلك الرخصة المنتهية غير صالحة."},"ref":{"doc":"HI","page":15}},{"id":"hi-026","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, up to what age must a child ride in a car seat with a harness?","o":["Under 1","Under 13","Under 16","Under 4"],"h1":"It is a very young age, before most children start school.","h2":"In Hawaii, a child under 4 must ride in a car seat with a harness. From 4 to under 10, state law requires a harness seat or a booster seat.","p":"Right. Children under 4 ride in a car seat with a harness."},"es":{"q":"En Hawái, ¿hasta qué edad debe un niño ir en un asiento de seguridad con arnés?","o":["Menores de 1","Menores de 13","Menores de 16","Menores de 4"],"h1":"Es una edad muy temprana, antes de que la mayoría de los niños empiecen la escuela.","h2":"En Hawái, un niño menor de 4 años debe ir en un asiento de seguridad con arnés. De 4 a menos de 10 años, la ley estatal exige un asiento con arnés o un asiento elevador.","p":"Correcto. Los niños menores de 4 años van en un asiento de seguridad con arnés."},"zh":{"q":"在 Hawaii，几岁以下的孩子必须坐在带安全带束带（harness）的儿童座椅里？","o":["1 岁以下","13 岁以下","16 岁以下","4 岁以下"],"h1":"这是很小的年龄，大多数孩子还没上学。","h2":"在 Hawaii，4 岁以下的孩子必须坐在带束带的儿童座椅里。4 岁到 10 岁以下，州法律要求坐带束带的座椅或增高座椅。","p":"对。4 岁以下的孩子要坐带束带的儿童座椅。"},"vi":{"q":"Ở Hawaii, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn có dây đai (harness)?","o":["Dưới 1 tuổi","Dưới 13 tuổi","Dưới 16 tuổi","Dưới 4 tuổi"],"h1":"Đó là tuổi rất nhỏ, trước khi hầu hết trẻ em đi học.","h2":"Ở Hawaii, trẻ em dưới 4 tuổi phải ngồi ghế an toàn có dây đai. Từ 4 đến dưới 10 tuổi, luật của tiểu bang yêu cầu ghế có dây đai hoặc ghế nâng (booster seat).","p":"Đúng. Trẻ em dưới 4 tuổi ngồi ghế an toàn có dây đai."},"tl":{"q":"Sa Hawaii, hanggang anong edad dapat sumakay ang bata sa car seat na may harness?","o":["Wala pang 1","Wala pang 13","Wala pang 16","Wala pang 4"],"h1":"Napakabatang edad ito, bago pumasok sa paaralan ang karamihan ng bata.","h2":"Sa Hawaii, ang batang wala pang 4 na taon ay dapat sumakay sa car seat na may harness. Mula 4 hanggang wala pang 10, hinihingi ng batas ng estado ang seat na may harness o booster seat.","p":"Tama. Ang mga batang wala pang 4 ay sumasakay sa car seat na may harness."},"ar":{"q":"في Hawaii، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة بحزام أمان خاص (harness)؟","o":["أقل من 1","أقل من 13","أقل من 16","أقل من 4"],"h1":"هو عمر صغير جدًا، قبل أن يبدأ معظم الأطفال المدرسة.","h2":"في Hawaii، يجب أن يجلس الطفل الذي عمره أقل من 4 سنوات في مقعد سيارة بحزام خاص. ومن 4 إلى أقل من 10 سنوات، يطلب قانون الولاية مقعدًا بحزام خاص أو مقعدًا رافعًا (booster seat).","p":"صحيح. الأطفال الذين عمرهم أقل من 4 سنوات يجلسون في مقعد سيارة بحزام خاص."},"ref":{"doc":"HI","page":20}},{"id":"hi-027","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what happens right away if you refuse an alcohol test or test at 0.08 or more?","o":["Your license is taken and you get a 30-day temporary permit","You get a warning and may keep driving","You must pay a $50 fine on the spot","Your car is inspected for safety"],"h1":"You get a short paper permit while your case goes forward.","h2":"In Hawaii, if you refuse an alcohol test or test at 0.08 or more, your license is taken away and you get a 30-day temporary driving permit.","p":"Right. Hawaii takes the license and gives a 30-day temporary permit."},"es":{"q":"En Hawái, ¿qué pasa de inmediato si usted se niega a una prueba de alcohol o su resultado es 0.08 o más?","o":["Le quitan la licencia y le dan un permiso temporal de 30 días","Le dan una advertencia y puede seguir manejando","Debe pagar una multa de $50 en el momento","Le hacen una inspección de seguridad al auto"],"h1":"Le dan un permiso corto en papel mientras sigue su caso.","h2":"En Hawái, si usted se niega a una prueba de alcohol o su resultado es 0.08 o más, le quitan la licencia y le dan un permiso temporal para manejar de 30 días.","p":"Correcto. Hawái quita la licencia y da un permiso temporal de 30 días."},"zh":{"q":"在 Hawaii，如果你拒绝酒精测试，或测试结果是 0.08 或以上，马上会发生什么？","o":["你的驾照被收走，你会拿到 30 天的临时驾驶许可","你会收到警告，可以继续开车","你必须当场付 $50 罚款","你的车会接受安全检查"],"h1":"你的案子进行时，你会拿到一张短期的纸质许可。","h2":"在 Hawaii，如果你拒绝酒精测试或测试结果是 0.08 或以上，你的驾照会被收走，你会拿到 30 天的临时驾驶许可。","p":"对。Hawaii 会收走驾照，并给你 30 天的临时许可。"},"vi":{"q":"Ở Hawaii, điều gì xảy ra ngay nếu bạn từ chối thử nồng độ cồn hoặc kết quả là 0.08 trở lên?","o":["Bằng lái của bạn bị thu và bạn nhận giấy phép lái xe tạm thời 30 ngày","Bạn bị cảnh cáo và được tiếp tục lái xe","Bạn phải nộp phạt $50 tại chỗ","Xe của bạn bị kiểm tra an toàn"],"h1":"Bạn nhận một giấy phép giấy ngắn hạn trong khi vụ việc của bạn được xử lý.","h2":"Ở Hawaii, nếu bạn từ chối thử nồng độ cồn hoặc kết quả là 0.08 trở lên, bằng lái của bạn bị thu và bạn nhận giấy phép lái xe tạm thời 30 ngày.","p":"Đúng. Hawaii thu bằng lái và cho giấy phép tạm thời 30 ngày."},"tl":{"q":"Sa Hawaii, ano ang mangyayari agad kung tatanggi ka sa alcohol test o 0.08 o higit pa ang resulta mo?","o":["Kukunin ang license mo at bibigyan ka ng 30 araw na temporary permit","Bibigyan ka ng babala at puwede kang magpatuloy sa pagmamaneho","Dapat kang magbayad ng $50 na multa sa mismong lugar","Iinspeksyunin ang kotse mo para sa kaligtasan"],"h1":"Bibigyan ka ng maikling papel na permit habang tumatakbo ang kaso mo.","h2":"Sa Hawaii, kung tatanggi ka sa alcohol test o 0.08 o higit pa ang resulta mo, kukunin ang license mo at bibigyan ka ng 30 araw na temporary driving permit.","p":"Tama. Kinukuha ng Hawaii ang license at nagbibigay ng 30 araw na temporary permit."},"ar":{"q":"في Hawaii، ماذا يحدث فورًا إذا رفضت فحص الكحول أو كانت النتيجة 0.08 أو أكثر؟","o":["تُسحب رخصتك وتحصل على تصريح قيادة مؤقت لمدة 30 يومًا","تحصل على تحذير ويمكنك الاستمرار في القيادة","يجب أن تدفع غرامة $50 في المكان","تُفحص سيارتك من أجل السلامة"],"h1":"تحصل على تصريح ورقي قصير بينما تسير قضيتك.","h2":"في Hawaii، إذا رفضت فحص الكحول أو كانت النتيجة 0.08 أو أكثر، تُسحب رخصتك وتحصل على تصريح قيادة مؤقت لمدة 30 يومًا.","p":"صحيح. تسحب Hawaii الرخصة وتعطي تصريحًا مؤقتًا لمدة 30 يومًا."},"ref":{"doc":"HI","page":55}},{"id":"hi-028","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, who in a car must wear a seat belt?","o":["Only the driver","Only people in the front seat","Everyone in the front and back seats","Only passengers under 18"],"h1":"Where you sit in the car does not matter.","h2":"In Hawaii everyone in the front and back seats must wear a seat belt or ride in a child restraint.","p":"Right. In Hawaii, every person in the car must be buckled up."},"es":{"q":"En Hawái, ¿quién debe usar el cinturón de seguridad en un auto?","o":["Solo el conductor","Solo las personas del asiento delantero","Todas las personas de los asientos delanteros y traseros","Solo los pasajeros menores de 18 años"],"h1":"No importa en qué parte del auto se siente.","h2":"En Hawái todas las personas de los asientos delanteros y traseros deben usar el cinturón de seguridad o ir en un asiento infantil.","p":"Correcto. En Hawái, todas las personas del auto deben abrocharse el cinturón."},"zh":{"q":"在 Hawaii，车里的哪些人必须系安全带？","o":["只有司机","只有前座的人","前座和后座的每个人","只有 18 岁以下的乘客"],"h1":"你坐在车里的哪个位置都一样。","h2":"在 Hawaii，前座和后座的每个人都必须系安全带，或坐儿童安全座椅。","p":"对。在 Hawaii，车里的每个人都必须系好安全带。"},"vi":{"q":"Ở Hawaii, ai trong xe phải thắt dây an toàn?","o":["Chỉ người lái xe","Chỉ người ngồi ghế trước","Mọi người ở ghế trước và ghế sau","Chỉ hành khách dưới 18 tuổi"],"h1":"Bạn ngồi ở chỗ nào trong xe cũng như nhau.","h2":"Ở Hawaii, mọi người ở ghế trước và ghế sau phải thắt dây an toàn hoặc ngồi ghế an toàn cho trẻ em.","p":"Đúng. Ở Hawaii, mọi người trong xe đều phải thắt dây an toàn."},"tl":{"q":"Sa Hawaii, sino sa kotse ang dapat magsuot ng seat belt?","o":["Ang driver lang","Ang mga nasa harapang upuan lang","Lahat ng nasa harap at likod na upuan","Ang mga pasaherong wala pang 18 lang"],"h1":"Hindi mahalaga kung saan ka nakaupo sa kotse.","h2":"Sa Hawaii, dapat magsuot ng seat belt o umupo sa child restraint ang lahat ng nasa harap at likod na upuan.","p":"Tama. Sa Hawaii, dapat naka-seat belt ang bawat tao sa kotse."},"ar":{"q":"في Hawaii، من في السيارة يجب أن يربط حزام الأمان؟","o":["السائق فقط","من في المقعد الأمامي فقط","كل من في المقاعد الأمامية والخلفية","الركاب تحت 18 سنة فقط"],"h1":"لا يهم أين تجلس في السيارة.","h2":"في Hawaii يجب على كل من في المقاعد الأمامية والخلفية أن يربط حزام الأمان أو يجلس في مقعد أمان للأطفال.","p":"صحيح. في Hawaii يجب أن يربط كل شخص في السيارة حزام الأمان."},"ref":{"doc":"HI","page":20}},{"id":"hi-029","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how early may you renew your driver's license before it expires?","o":["Up to 30 days before","Up to 60 days before","Up to six months before","Up to two years before"],"h1":"It is more than two months.","h2":"In Hawaii you may renew your driver's license up to six months before the expiration date.","p":"Right. You can renew up to six months before your license expires."},"es":{"q":"En Hawái, ¿con cuánta anticipación puede renovar su licencia de manejar antes de que venza?","o":["Hasta 30 días antes","Hasta 60 días antes","Hasta seis meses antes","Hasta dos años antes"],"h1":"Es más de dos meses.","h2":"En Hawái usted puede renovar su licencia de manejar hasta seis meses antes de la fecha de vencimiento.","p":"Correcto. Puede renovarla hasta seis meses antes de que venza."},"zh":{"q":"在 Hawaii，驾照到期前最早多久可以续期？","o":["最多提前 30 天","最多提前 60 天","最多提前六个月","最多提前两年"],"h1":"它比两个月还长。","h2":"在 Hawaii，你最早可以在驾照到期前六个月续期。","p":"对。驾照到期前六个月内都可以续期。"},"vi":{"q":"Ở Hawaii, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi bằng hết hạn?","o":["Tối đa 30 ngày trước","Tối đa 60 ngày trước","Tối đa sáu tháng trước","Tối đa hai năm trước"],"h1":"Thời gian này dài hơn hai tháng.","h2":"Ở Hawaii, bạn có thể gia hạn bằng lái sớm nhất sáu tháng trước ngày hết hạn.","p":"Đúng. Bạn có thể gia hạn tối đa sáu tháng trước khi bằng lái hết hạn."},"tl":{"q":"Sa Hawaii, gaano kaaga puwede mong i-renew ang driver's license mo bago ito mag-expire?","o":["Hanggang 30 araw bago","Hanggang 60 araw bago","Hanggang anim na buwan bago","Hanggang dalawang taon bago"],"h1":"Mas mahaba ito sa dalawang buwan.","h2":"Sa Hawaii, puwede mong i-renew ang driver's license mo hanggang anim na buwan bago ang petsa ng expiration.","p":"Tama. Puwede kang mag-renew hanggang anim na buwan bago mag-expire ang license mo."},"ar":{"q":"في Hawaii، كم مبكرًا يمكنك تجديد رخصة القيادة قبل انتهائها؟","o":["حتى 30 يومًا قبل الانتهاء","حتى 60 يومًا قبل الانتهاء","حتى ستة أشهر قبل الانتهاء","حتى سنتين قبل الانتهاء"],"h1":"المدة أطول من شهرين.","h2":"في Hawaii يمكنك تجديد رخصة القيادة حتى ستة أشهر قبل تاريخ انتهائها.","p":"صحيح. يمكنك التجديد حتى ستة أشهر قبل انتهاء رخصتك."},"ref":{"doc":"HI","page":15}},{"id":"hi-030","scope":"HI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Hawaii, a railroad crossing signal is flashing because a train is coming. How far from the nearest rail must you stop?","o":["At least 15 feet","At least 3 feet","At least 5 feet","At least 100 feet"],"h1":"Leave room so a train cannot hit the front of your car.","h2":"In Hawaii, when a railroad signal warns of a train, you must stop at least 15 feet from the nearest rail.","p":"Right. Stop at least 15 feet from the nearest rail."},"es":{"q":"En Hawái, la señal de un cruce de ferrocarril está prendida porque viene un tren. ¿A qué distancia del riel más cercano debe detenerse?","o":["Por lo menos a 15 pies","Por lo menos a 3 pies","Por lo menos a 5 pies","Por lo menos a 100 pies"],"h1":"Deje espacio para que el tren no golpee el frente de su carro.","h2":"En Hawái, cuando la señal del ferrocarril avisa que viene un tren, usted debe detenerse por lo menos a 15 pies del riel más cercano.","p":"Correcto. Deténgase por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Hawaii，铁路道口的信号灯在闪，因为有火车要来。你必须停在离最近的铁轨多远的地方？","o":["至少 15 英尺","至少 3 英尺","至少 5 英尺","至少 100 英尺"],"h1":"留出空间，让火车撞不到你的车头。","h2":"在 Hawaii，铁路信号警告有火车来时，你必须停在离最近的铁轨至少 15 英尺的地方。","p":"对。停在离最近的铁轨至少 15 英尺的地方。"},"vi":{"q":"Ở Hawaii, đèn báo ở chỗ giao với đường sắt đang nhấp nháy vì có tàu hỏa đang đến. Bạn phải dừng cách đường ray gần nhất bao xa?","o":["Ít nhất 15 feet","Ít nhất 3 feet","Ít nhất 5 feet","Ít nhất 100 feet"],"h1":"Chừa khoảng trống để tàu hỏa không đụng vào đầu xe của bạn.","h2":"Ở Hawaii, khi đèn báo đường sắt cảnh báo có tàu hỏa, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet.","p":"Đúng. Dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Hawaii, kumikislap ang signal sa tawiran ng tren dahil may paparating na tren. Gaano kalayo sa pinakamalapit na riles ka dapat huminto?","o":["Hindi bababa sa 15 feet","Hindi bababa sa 3 feet","Hindi bababa sa 5 feet","Hindi bababa sa 100 feet"],"h1":"Mag-iwan ng espasyo para hindi matamaan ng tren ang harap ng kotse mo.","h2":"Sa Hawaii, kapag nagbababala ang signal ng riles na may tren, dapat kang huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Hawaii، إشارة معبر السكة الحديدية تومض لأن قطارًا قادم. على أي مسافة من أقرب سكة يجب أن تتوقف؟","o":["15 feet على الأقل","3 feet على الأقل","5 feet على الأقل","100 feet على الأقل"],"h1":"اترك مسافة حتى لا يصطدم القطار بمقدمة سيارتك.","h2":"في Hawaii، عندما تحذّر إشارة السكة الحديدية من قطار، يجب أن تتوقف على بعد 15 feet على الأقل من أقرب سكة.","p":"صحيح. توقف على بعد 15 feet على الأقل من أقرب سكة."},"ref":{"doc":"HI","page":27}},{"id":"hi-031","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, how much space should you leave between your car and a bicycle rider when you pass?","o":["At least 1 foot","At least 3 feet","At least 10 feet","At least 20 feet"],"h1":"It is about the length of one long step.","h2":"In Hawaii you should leave at least 3 feet of space between your car and a bicycle rider until you have safely passed.","p":"Right. Leave at least 3 feet when you pass a bicycle rider."},"es":{"q":"En Hawái, ¿cuánto espacio debe dejar entre su carro y un ciclista cuando lo rebasa?","o":["Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 10 pies","Por lo menos 20 pies"],"h1":"Es más o menos el largo de un paso largo.","h2":"En Hawái usted debe dejar por lo menos 3 pies de espacio entre su carro y un ciclista hasta que lo haya rebasado con seguridad.","p":"Correcto. Deje por lo menos 3 pies cuando rebase a un ciclista."},"zh":{"q":"在 Hawaii，你超过骑自行车的人时，车子和他之间应该留多少空间？","o":["至少 1 英尺","至少 3 英尺","至少 10 英尺","至少 20 英尺"],"h1":"大约是迈一大步的长度。","h2":"在 Hawaii，你应该在车子和骑自行车的人之间留至少 3 英尺的空间，直到你安全超过他。","p":"对。超过骑自行车的人时，要留至少 3 英尺。"},"vi":{"q":"Ở Hawaii, khi vượt người đi xe đạp, bạn nên chừa bao nhiêu khoảng cách giữa xe của bạn và người đó?","o":["Ít nhất 1 feet","Ít nhất 3 feet","Ít nhất 10 feet","Ít nhất 20 feet"],"h1":"Khoảng bằng một bước chân dài.","h2":"Ở Hawaii, bạn nên chừa ít nhất 3 feet giữa xe của bạn và người đi xe đạp cho đến khi bạn vượt qua an toàn.","p":"Đúng. Chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Hawaii, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng nagbibisikleta kapag lumalampas ka?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet"],"h1":"Mga isang mahabang hakbang ito.","h2":"Sa Hawaii, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo sa pagitan ng kotse mo at ng nagbibisikleta hanggang ligtas kang makalampas.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet kapag lumalampas sa nagbibisikleta."},"ar":{"q":"في Hawaii، كم مسافة يجب أن تتركها بين سيارتك وراكب الدراجة عندما تتجاوزه؟","o":["1 foot على الأقل","3 feet على الأقل","10 feet على الأقل","20 feet على الأقل"],"h1":"إنها تقريبًا طول خطوة واحدة طويلة.","h2":"في Hawaii يجب أن تترك مسافة 3 feet على الأقل بين سيارتك وراكب الدراجة حتى تتجاوزه بأمان.","p":"صحيح. اترك 3 feet على الأقل عندما تتجاوز راكب دراجة."},"ref":{"doc":"HI","page":97}},{"id":"hi-032","scope":"HI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Hawaii, you want to pass on the left half of a two-lane road. How close to an intersection or railroad crossing may you do this?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 75 feet","No closer than 100 feet"],"h1":"You need room to finish passing well before the crossing.","h2":"In Hawaii you must not drive on the left half of the road within 100 feet of an intersection or a railroad crossing.","p":"Right. Do not use the left half of the road within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Hawái, usted quiere rebasar por la mitad izquierda de un camino de dos carriles. ¿Qué tan cerca de una intersección o de un cruce de ferrocarril puede hacerlo?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 75 pies","No más cerca de 100 pies"],"h1":"Necesita espacio para terminar de rebasar mucho antes del cruce.","h2":"En Hawái usted no debe manejar por la mitad izquierda del camino a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No use la mitad izquierda del camino a menos de 100 pies de una intersección o de un cruce de ferrocarril."},"zh":{"q":"在 Hawaii，你想在双车道道路的左半边超车。离路口或铁路道口多近就不能这样做？","o":["不能少于 25 英尺","不能少于 50 英尺","不能少于 75 英尺","不能少于 100 英尺"],"h1":"你需要在到达道口之前很早就完成超车。","h2":"在 Hawaii，离路口或铁路道口 100 英尺以内，你不可以开在道路的左半边。","p":"对。离路口或铁路道口 100 英尺以内，不要使用道路的左半边。"},"vi":{"q":"Ở Hawaii, bạn muốn vượt xe bằng cách đi vào nửa bên trái của đường hai làn. Bạn được làm vậy khi cách giao lộ hoặc chỗ giao với đường sắt gần nhất là bao nhiêu?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 75 feet","Không gần hơn 100 feet"],"h1":"Bạn cần đủ chỗ để vượt xong từ sớm, trước chỗ giao nhau.","h2":"Ở Hawaii, bạn không được lái ở nửa bên trái của đường trong vòng 100 feet trước giao lộ hoặc chỗ giao với đường sắt.","p":"Đúng. Không đi vào nửa bên trái của đường trong vòng 100 feet trước giao lộ hoặc chỗ giao với đường sắt."},"tl":{"q":"Sa Hawaii, gusto mong lumampas gamit ang kaliwang kalahati ng kalsadang may dalawang lane. Gaano kalapit sa intersection o tawiran ng tren ka puwedeng gumawa nito?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 75 feet","Hindi lalapit sa 100 feet"],"h1":"Kailangan mo ng espasyo para matapos ang paglampas bago pa ang tawiran.","h2":"Sa Hawaii, hindi ka puwedeng magmaneho sa kaliwang kalahati ng kalsada sa loob ng 100 feet mula sa intersection o tawiran ng tren.","p":"Tama. Huwag gamitin ang kaliwang kalahati ng kalsada sa loob ng 100 feet mula sa intersection o tawiran ng tren."},"ar":{"q":"في Hawaii، تريد أن تتجاوز باستخدام النصف الأيسر من طريق ذي مسارين. ما أقرب مسافة من تقاطع أو معبر سكة حديدية يمكنك فيها فعل ذلك؟","o":["ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 75 feet","ليس أقرب من 100 feet"],"h1":"تحتاج إلى مسافة كافية لتنهي التجاوز قبل المعبر بوقت كافٍ.","h2":"في Hawaii لا يجوز لك القيادة في النصف الأيسر من الطريق على بعد 100 feet أو أقل من تقاطع أو معبر سكة حديدية.","p":"صحيح. لا تستخدم النصف الأيسر من الطريق على بعد 100 feet أو أقل من تقاطع أو معبر سكة حديدية."},"ref":{"doc":"HI","page":26}},{"id":"hi-033","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, what is the youngest age to get a regular class 3 driver's license?","o":["17 years old","16 years old","18 years old","21 years old"],"h1":"It is one year older than the youngest age for a provisional license.","h2":"In Hawaii you must be at least 17 years old to get a class 3 driver's license.","p":"Right. A class 3 driver's license starts at age 17."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para obtener una licencia de manejar regular de clase 3?","o":["17 años","16 años","18 años","21 años"],"h1":"Es un año más que la edad mínima para la licencia provisional.","h2":"En Hawái usted debe tener al menos 17 años para obtener una licencia de manejar de clase 3.","p":"Correcto. La licencia de clase 3 empieza a los 17 años."},"zh":{"q":"在 Hawaii，最小几岁可以拿到普通的 3 类驾照（class 3 driver's license）？","o":["17 岁","16 岁","18 岁","21 岁"],"h1":"它比拿过渡驾照的最小年龄大一岁。","h2":"在 Hawaii，你必须至少 17 岁才能拿到 3 类驾照。","p":"对。3 类驾照从 17 岁开始。"},"vi":{"q":"Ở Hawaii, tuổi nhỏ nhất để có bằng lái thường hạng 3 (class 3 driver's license) là bao nhiêu?","o":["17 tuổi","16 tuổi","18 tuổi","21 tuổi"],"h1":"Đó là lớn hơn một tuổi so với tuổi nhỏ nhất để có bằng lái tạm thời.","h2":"Ở Hawaii, bạn phải ít nhất 17 tuổi mới có bằng lái hạng 3.","p":"Đúng. Bằng lái hạng 3 bắt đầu từ 17 tuổi."},"tl":{"q":"Sa Hawaii, ano ang pinakabatang edad para makakuha ng regular na class 3 driver's license?","o":["17 taong gulang","16 taong gulang","18 taong gulang","21 taong gulang"],"h1":"Isang taon itong mas matanda kaysa sa pinakabatang edad para sa provisional license.","h2":"Sa Hawaii, dapat hindi bababa sa 17 taong gulang ka para makakuha ng class 3 driver's license.","p":"Tama. Nagsisimula ang class 3 driver's license sa edad na 17."},"ar":{"q":"في Hawaii، ما أصغر عمر للحصول على رخصة قيادة عادية من الفئة 3 (class 3 driver's license)؟","o":["17 سنة","16 سنة","18 سنة","21 سنة"],"h1":"هو أكبر بسنة واحدة من أصغر عمر للرخصة المؤقتة.","h2":"في Hawaii يجب أن يكون عمرك 17 سنة على الأقل لتحصل على رخصة قيادة من الفئة 3.","p":"صحيح. رخصة القيادة من الفئة 3 تبدأ من عمر 17 سنة."},"ref":{"doc":"HI","page":12}},{"id":"hi-034","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, how long must you hold a provisional license before you can apply for a full driver's license?","o":["30 days","90 days","Six months","Two years"],"h1":"It is half a year.","h2":"In Hawaii you must hold a provisional license for six months before you can apply for a driver's license.","p":"Right. You keep the provisional license for six months first."},"es":{"q":"En Hawái, ¿cuánto tiempo debe tener una licencia provisional antes de solicitar la licencia de manejar completa?","o":["30 días","90 días","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Hawái usted debe tener la licencia provisional durante seis meses antes de solicitar la licencia de manejar.","p":"Correcto. Primero tiene la licencia provisional durante seis meses."},"zh":{"q":"在 Hawaii，你必须持有过渡驾照多久，才能申请正式驾照？","o":["30 天","90 天","六个月","两年"],"h1":"它是半年。","h2":"在 Hawaii，你必须持有过渡驾照六个月，才能申请驾照。","p":"对。你要先持有过渡驾照六个月。"},"vi":{"q":"Ở Hawaii, bạn phải giữ bằng lái tạm thời bao lâu trước khi có thể xin bằng lái chính thức?","o":["30 ngày","90 ngày","Sáu tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Hawaii, bạn phải giữ bằng lái tạm thời sáu tháng trước khi có thể xin bằng lái.","p":"Đúng. Bạn giữ bằng lái tạm thời sáu tháng trước."},"tl":{"q":"Sa Hawaii, gaano katagal mo dapat hawak ang provisional license bago ka puwedeng mag-apply para sa buong driver's license?","o":["30 araw","90 araw","Anim na buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Hawaii, dapat hawak mo ang provisional license nang anim na buwan bago ka puwedeng mag-apply para sa driver's license.","p":"Tama. Hawak mo muna ang provisional license nang anim na buwan."},"ar":{"q":"في Hawaii، كم مدة يجب أن تحمل الرخصة المؤقتة قبل أن تتقدّم بطلب رخصة قيادة كاملة؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في Hawaii يجب أن تحمل الرخصة المؤقتة ستة أشهر قبل أن تتقدّم بطلب رخصة القيادة.","p":"صحيح. تحمل الرخصة المؤقتة ستة أشهر أولًا."},"ref":{"doc":"HI","page":14}},{"id":"hi-035","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, which test must you pass every time before your driver's license is renewed?","o":["A road test","A vision test","A written test","A parallel parking test"],"h1":"It checks how well you see.","h2":"In Hawaii you must pass a vision test before your driver's license is renewed.","p":"Right. A vision test comes before every renewal."},"es":{"q":"En Hawái, ¿qué examen debe aprobar cada vez antes de que se renueve su licencia de manejar?","o":["Un examen de manejo","Un examen de la vista","Un examen escrito","Un examen de estacionamiento en paralelo"],"h1":"Revisa qué tan bien ve usted.","h2":"En Hawái usted debe aprobar un examen de la vista antes de que se renueve su licencia de manejar.","p":"Correcto. Antes de cada renovación hay un examen de la vista."},"zh":{"q":"在 Hawaii，每次更新驾照前，你都必须通过哪种考试？","o":["路考","视力检查","笔试","侧方停车考试"],"h1":"它检查你看得清不清楚。","h2":"在 Hawaii，更新驾照前你必须通过视力检查。","p":"对。每次更新前都要做视力检查。"},"vi":{"q":"Ở Hawaii, bạn phải đậu bài kiểm tra nào mỗi lần trước khi gia hạn bằng lái?","o":["Bài thi lái xe trên đường","Bài kiểm tra thị lực","Bài thi viết","Bài thi đậu xe song song"],"h1":"Nó kiểm tra bạn nhìn rõ đến mức nào.","h2":"Ở Hawaii, bạn phải đậu bài kiểm tra thị lực trước khi gia hạn bằng lái.","p":"Đúng. Trước mỗi lần gia hạn đều có bài kiểm tra thị lực."},"tl":{"q":"Sa Hawaii, aling test ang dapat mong maipasa tuwing bago i-renew ang iyong driver's license?","o":["Road test","Vision test","Nakasulat na test","Parallel parking test"],"h1":"Sinusuri nito kung gaano kalinaw ang paningin mo.","h2":"Sa Hawaii, dapat kang makapasa sa vision test bago i-renew ang iyong driver's license.","p":"Tama. May vision test bago ang bawat renewal."},"ar":{"q":"في Hawaii، أي اختبار يجب أن تنجح فيه في كل مرة قبل تجديد رخصة القيادة؟","o":["اختبار القيادة على الطريق","اختبار النظر","اختبار كتابي","اختبار الركن الموازي"],"h1":"يفحص مدى جودة نظرك.","h2":"في Hawaii يجب أن تنجح في اختبار النظر قبل تجديد رخصة القيادة.","p":"صحيح. يأتي اختبار النظر قبل كل تجديد."},"ref":{"doc":"HI","page":15}},{"id":"hi-036","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how many documents proving your home address in Hawaii must you bring for a REAL ID license or permit?","o":["None","One","Three","Two"],"h1":"A utility bill and a bank statement would be enough.","h2":"In Hawaii you must bring two documents that show your name and your home address in Hawaii.","p":"Right. You need two proofs of your Hawaii address."},"es":{"q":"En Hawái, ¿cuántos documentos que prueben su domicilio en Hawái debe llevar para una licencia o permiso REAL ID?","o":["Ninguno","Uno","Tres","Dos"],"h1":"Una factura de luz y un estado de cuenta del banco serían suficientes.","h2":"En Hawái usted debe llevar dos documentos que muestren su nombre y su domicilio en Hawái.","p":"Correcto. Necesita dos pruebas de su domicilio en Hawái."},"zh":{"q":"在 Hawaii，办 REAL ID 驾照或学习驾照时，你必须带几份证明你在 Hawaii 住址的文件？","o":["不用带","一份","三份","两份"],"h1":"一张水电费账单加一张银行对账单就够了。","h2":"在 Hawaii，你必须带两份写有你的名字和你在 Hawaii 住址的文件。","p":"对。你需要两份 Hawaii 住址证明。"},"vi":{"q":"Ở Hawaii, bạn phải mang bao nhiêu giấy tờ chứng minh địa chỉ nhà ở Hawaii để làm bằng lái hoặc giấy phép REAL ID?","o":["Không cần","Một","Ba","Hai"],"h1":"Một hóa đơn điện nước và một bản sao kê ngân hàng là đủ.","h2":"Ở Hawaii, bạn phải mang hai giấy tờ có tên bạn và địa chỉ nhà của bạn ở Hawaii.","p":"Đúng. Bạn cần hai giấy tờ chứng minh địa chỉ ở Hawaii."},"tl":{"q":"Sa Hawaii, ilang dokumentong nagpapatunay ng tirahan mo sa Hawaii ang dapat mong dalhin para sa REAL ID na lisensya o permit?","o":["Wala","Isa","Tatlo","Dalawa"],"h1":"Sapat na ang isang bill ng kuryente o tubig at isang bank statement.","h2":"Sa Hawaii, dapat kang magdala ng dalawang dokumentong nagpapakita ng pangalan mo at ng tirahan mo sa Hawaii.","p":"Tama. Kailangan mo ng dalawang patunay ng tirahan mo sa Hawaii."},"ar":{"q":"في Hawaii، كم وثيقة تُثبت عنوان سكنك في Hawaii يجب أن تُحضر للحصول على رخصة أو تصريح REAL ID؟","o":["ولا وثيقة","وثيقة واحدة","ثلاث وثائق","وثيقتان"],"h1":"فاتورة كهرباء أو ماء وكشف حساب بنكي يكفيان.","h2":"في Hawaii يجب أن تُحضر وثيقتين فيهما اسمك وعنوان سكنك في Hawaii.","p":"صحيح. تحتاج إلى إثباتين لعنوانك في Hawaii."},"ref":{"doc":"HI","page":11}},{"id":"hi-037","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, your license has expired. How long after the expiration date can you still get it back without applying as a new driver?","o":["Up to one year","Up to 10 days","Up to 30 days","Up to five years"],"h1":"It is twelve months; after the first 90 days a late fee is added.","h2":"In Hawaii you can renew or reactivate an expired license up to one year after the expiration date (with a late fee after the first 90 days); after one year it is invalid and you must apply as a new driver.","p":"Right. You have up to one year after it expires; after 90 days you pay a late fee."},"es":{"q":"En Hawái, su licencia venció. ¿Cuánto tiempo después de la fecha de vencimiento todavía puede recuperarla sin solicitarla como conductor nuevo?","o":["Hasta un año","Hasta 10 días","Hasta 30 días","Hasta cinco años"],"h1":"Son doce meses; después de los primeros 90 días se cobra un recargo.","h2":"En Hawái usted puede renovar o reactivar una licencia vencida hasta un año después de la fecha de vencimiento (con un recargo después de los primeros 90 días); después de un año ya no es válida y debe solicitarla como conductor nuevo.","p":"Correcto. Tiene hasta un año después del vencimiento; después de 90 días paga un recargo."},"ref":{"doc":"HI","page":15}},{"id":"hi-038","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a visitor has a foreign driver's license and an International Driving Permit. How long may they drive with them?","o":["30 days after arrival","Six months after arrival","One year after arrival in the U.S.","As long as the foreign license is valid"],"h1":"Count from the day they first entered the United States.","h2":"In Hawaii a foreign license with an International Driving Permit is valid for one year after arrival in the United States.","p":"Right. They may drive with them for one year after arriving in the U.S."},"es":{"q":"En Hawái, un visitante tiene una licencia extranjera y un Permiso Internacional de Conducir. ¿Por cuánto tiempo puede manejar con ellos?","o":["30 días después de llegar","Seis meses después de llegar","Un año después de llegar a EE. UU.","Mientras la licencia extranjera esté vigente"],"h1":"Cuente desde el día en que entró por primera vez a Estados Unidos.","h2":"En Hawái una licencia extranjera con un Permiso Internacional de Conducir es válida por un año después de llegar a Estados Unidos.","p":"Correcto. Puede manejar con ellos por un año después de llegar a EE. UU."},"zh":{"q":"在 Hawaii，一位访客有外国驾照和国际驾驶许可证（International Driving Permit）。他可以用它们开车多久？","o":["到达后 30 天","到达后六个月","到达美国后一年","只要外国驾照有效就可以"],"h1":"从他第一次进入美国那天开始算。","h2":"在 Hawaii，外国驾照加国际驾驶许可证在到达美国后一年内有效。","p":"对。他到达美国后一年内可以用它们开车。"},"vi":{"q":"Ở Hawaii, một du khách có bằng lái nước ngoài và Giấy phép Lái xe Quốc tế (International Driving Permit). Họ được lái xe với các giấy này bao lâu?","o":["30 ngày sau khi đến","Sáu tháng sau khi đến","Một năm sau khi đến Mỹ","Bao lâu cũng được, miễn bằng lái nước ngoài còn hạn"],"h1":"Hãy tính từ ngày họ vào nước Mỹ lần đầu.","h2":"Ở Hawaii, bằng lái nước ngoài có kèm Giấy phép Lái xe Quốc tế có hiệu lực một năm sau khi đến Mỹ.","p":"Đúng. Họ được lái xe với các giấy này một năm sau khi đến Mỹ."},"tl":{"q":"Sa Hawaii, may foreign driver's license at International Driving Permit ang isang bisita. Gaano katagal siya puwedeng magmaneho gamit ang mga ito?","o":["30 araw pagdating","Anim na buwan pagdating","Isang taon pagdating sa U.S.","Hangga't valid ang foreign license"],"h1":"Bilangin mula sa araw na una siyang pumasok sa United States.","h2":"Sa Hawaii, valid ang foreign license na may International Driving Permit nang isang taon pagdating sa United States.","p":"Tama. Puwede siyang magmaneho gamit ang mga ito nang isang taon pagdating sa U.S."},"ar":{"q":"في Hawaii، زائر لديه رخصة قيادة أجنبية وتصريح قيادة دولي (International Driving Permit). كم مدة يجوز له أن يقود بهما؟","o":["30 يومًا بعد الوصول","ستة أشهر بعد الوصول","سنة واحدة بعد الوصول إلى الولايات المتحدة","ما دامت الرخصة الأجنبية سارية"],"h1":"احسب من اليوم الذي دخل فيه الولايات المتحدة أول مرة.","h2":"في Hawaii تكون الرخصة الأجنبية مع تصريح القيادة الدولي صالحة لمدة سنة واحدة بعد الوصول إلى الولايات المتحدة.","p":"صحيح. يجوز له أن يقود بهما سنة واحدة بعد الوصول إلى الولايات المتحدة."},"ref":{"doc":"HI","page":10}},{"id":"hi-039","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, which of these can stop you from getting a driver's license?","o":["Owning more than one car","Having traffic tickets you have not taken care of","Living on a different island from the office","Wearing glasses"],"h1":"Think of something you still owe the court.","h2":"In Hawaii you cannot be licensed while you have outstanding traffic citations.","p":"Right. Unresolved traffic tickets can block your license."},"es":{"q":"En Hawái, ¿cuál de estas cosas puede impedirle obtener una licencia de manejar?","o":["Tener más de un carro","Tener multas de tránsito sin resolver","Vivir en otra isla que la oficina","Usar lentes"],"h1":"Piense en algo que todavía le debe a la corte.","h2":"En Hawái usted no puede obtener una licencia mientras tenga multas de tránsito pendientes.","p":"Correcto. Las multas de tránsito sin resolver pueden impedir su licencia."},"zh":{"q":"在 Hawaii，下面哪一项会让你拿不到驾照？","o":["有不止一辆车","有还没处理的交通罚单","住在和办公室不同的岛上","戴眼镜"],"h1":"想一想你还欠法院的东西。","h2":"在 Hawaii，如果你还有没处理的交通罚单，你就不能拿到驾照。","p":"对。没处理的交通罚单会让你拿不到驾照。"},"vi":{"q":"Ở Hawaii, điều nào dưới đây có thể khiến bạn không được cấp bằng lái?","o":["Có nhiều hơn một chiếc xe","Có vé phạt giao thông chưa giải quyết","Sống ở đảo khác với văn phòng","Đeo kính"],"h1":"Hãy nghĩ đến điều bạn vẫn còn nợ tòa án.","h2":"Ở Hawaii, bạn không thể được cấp bằng lái khi còn vé phạt giao thông chưa giải quyết.","p":"Đúng. Vé phạt giao thông chưa giải quyết có thể chặn bằng lái của bạn."},"tl":{"q":"Sa Hawaii, alin sa mga ito ang puwedeng pumigil sa iyo na makakuha ng driver's license?","o":["May higit sa isang kotse","May mga traffic ticket na hindi mo pa naaasikaso","Nakatira sa ibang isla kaysa sa opisina","Nakasuot ng salamin"],"h1":"Isipin ang isang bagay na may utang ka pa sa korte.","h2":"Sa Hawaii, hindi ka puwedeng bigyan ng lisensya habang may mga traffic citation kang hindi pa naaasikaso.","p":"Tama. Puwedeng pigilan ng hindi naaasikasong traffic ticket ang lisensya mo."},"ar":{"q":"في Hawaii، أي من هذه الأمور يمكن أن يمنعك من الحصول على رخصة القيادة؟","o":["امتلاك أكثر من سيارة","وجود مخالفات مرورية لم تُسوِّها بعد","السكن في جزيرة غير جزيرة المكتب","لبس النظارات"],"h1":"فكّر في شيء ما زلت مدينًا به للمحكمة.","h2":"في Hawaii لا يمكنك الحصول على رخصة ما دامت عليك مخالفات مرورية غير مُسوّاة.","p":"صحيح. المخالفات المرورية غير المُسوّاة يمكن أن تمنع رخصتك."},"ref":{"doc":"HI","page":10}},{"id":"hi-040","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, what is true about a limited purpose driver's license, given to people who do not provide a Social Security number?","o":["It lets you drive only at night","It is valid only on Oahu","It can be used to board a plane","It is good for driving only, not as federal ID"],"h1":"Its name says it has a limited use.","h2":"In Hawaii a limited purpose license is only a license to drive and cannot be used as ID for federal purposes such as boarding a plane.","p":"Right. It is for driving only, not for federal ID."},"es":{"q":"En Hawái, ¿qué es cierto sobre la licencia de propósito limitado, que se da a quienes no presentan un número de Seguro Social?","o":["Solo permite manejar de noche","Solo es válida en Oahu","Sirve para abordar un avión","Solo sirve para manejar, no como identificación federal"],"h1":"Su nombre dice que tiene un uso limitado.","h2":"En Hawái la licencia de propósito limitado solo es una licencia para manejar y no sirve como identificación federal, por ejemplo para abordar un avión.","p":"Correcto. Solo sirve para manejar, no como identificación federal."},"zh":{"q":"在 Hawaii，有一种给不提供社会安全号码（Social Security number）的人的限用驾照（limited purpose driver's license）。关于它，哪一句是对的？","o":["只能在晚上开车","只在 Oahu 有效","可以用来登机","只能用来开车，不能当联邦身份证明"],"h1":"它的名字说明它的用途有限。","h2":"在 Hawaii，限用驾照只是开车用的驾照，不能当作联邦用途的身份证明，例如登机。","p":"对。它只能用来开车，不能当联邦身份证明。"},"vi":{"q":"Ở Hawaii, điều nào đúng về bằng lái mục đích giới hạn (limited purpose driver's license), cấp cho người không cung cấp số An sinh Xã hội (Social Security number)?","o":["Chỉ cho phép lái xe ban đêm","Chỉ có hiệu lực ở Oahu","Có thể dùng để lên máy bay","Chỉ dùng để lái xe, không dùng làm giấy tờ tùy thân liên bang"],"h1":"Tên của nó cho biết nó có công dụng giới hạn.","h2":"Ở Hawaii, bằng lái mục đích giới hạn chỉ là giấy phép lái xe và không thể dùng làm giấy tờ tùy thân cho mục đích liên bang, như lên máy bay.","p":"Đúng. Nó chỉ dùng để lái xe, không dùng làm giấy tờ tùy thân liên bang."},"tl":{"q":"Sa Hawaii, ano ang totoo tungkol sa limited purpose driver's license, na ibinibigay sa mga taong hindi nagbibigay ng Social Security number?","o":["Puwede ka lang magmaneho sa gabi","Valid lang ito sa Oahu","Puwede itong gamitin para sumakay ng eroplano","Para lang ito sa pagmamaneho, hindi bilang federal ID"],"h1":"Sinasabi ng pangalan nito na limitado ang gamit nito.","h2":"Sa Hawaii, ang limited purpose license ay lisensya lang para magmaneho at hindi puwedeng gamitin bilang ID para sa federal na layunin, gaya ng pagsakay sa eroplano.","p":"Tama. Para lang ito sa pagmamaneho, hindi bilang federal ID."},"ar":{"q":"في Hawaii، ما الصحيح عن رخصة القيادة محدودة الغرض (limited purpose driver's license) التي تُعطى لمن لا يقدّم رقم الضمان الاجتماعي (Social Security number)؟","o":["تسمح لك بالقيادة ليلًا فقط","صالحة في Oahu فقط","يمكن استخدامها لركوب الطائرة","صالحة للقيادة فقط، وليست هوية فيدرالية"],"h1":"اسمها يقول إن استخدامها محدود.","h2":"في Hawaii الرخصة محدودة الغرض هي رخصة للقيادة فقط، ولا يمكن استخدامها هويةً لأغراض فيدرالية مثل ركوب الطائرة.","p":"صحيح. هي للقيادة فقط، وليست هوية فيدرالية."},"ref":{"doc":"HI","page":11}},{"id":"hi-041","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, who may ride in the car with you during your road test?","o":["Only the examiner; passengers are not allowed","One friend in the back seat","Your parent in the back seat","Anyone with a valid license"],"h1":"The test is just you and the person grading you.","h2":"In Hawaii passengers are not permitted during the road test, so only the examiner rides with you.","p":"Right. No passengers are allowed during the road test."},"es":{"q":"En Hawái, ¿quién puede ir en el carro con usted durante su examen de manejo?","o":["Solo el examinador; no se permiten pasajeros","Un amigo en el asiento de atrás","Su padre o madre en el asiento de atrás","Cualquier persona con licencia vigente"],"h1":"En el examen solo van usted y la persona que lo califica.","h2":"En Hawái no se permiten pasajeros durante el examen de manejo, así que solo el examinador va con usted.","p":"Correcto. No se permiten pasajeros durante el examen de manejo."},"zh":{"q":"在 Hawaii，路考时谁可以和你一起坐在车里？","o":["只有考官；不可以有乘客","后座一位朋友","后座你的父亲或母亲","任何有有效驾照的人"],"h1":"考试时车里只有你和给你打分的人。","h2":"在 Hawaii，路考时不允许有乘客，所以只有考官和你一起坐车。","p":"对。路考时不可以有乘客。"},"vi":{"q":"Ở Hawaii, ai được ngồi trong xe với bạn khi bạn thi lái xe trên đường?","o":["Chỉ giám khảo; không được có hành khách","Một người bạn ở ghế sau","Cha hoặc mẹ bạn ở ghế sau","Bất kỳ ai có bằng lái còn hạn"],"h1":"Bài thi chỉ có bạn và người chấm điểm bạn.","h2":"Ở Hawaii, không được có hành khách trong khi thi lái xe trên đường, nên chỉ giám khảo ngồi cùng bạn.","p":"Đúng. Không được có hành khách khi thi lái xe trên đường."},"tl":{"q":"Sa Hawaii, sino ang puwedeng sumakay sa kotse kasama mo habang road test?","o":["Ang examiner lang; bawal ang mga pasahero","Isang kaibigan sa likod na upuan","Ang magulang mo sa likod na upuan","Kahit sinong may valid na lisensya"],"h1":"Ikaw lang at ang taong nagbibigay ng marka ang nasa test.","h2":"Sa Hawaii, bawal ang mga pasahero habang road test, kaya ang examiner lang ang kasama mo sa kotse.","p":"Tama. Bawal ang mga pasahero habang road test."},"ar":{"q":"في Hawaii، من يجوز له أن يركب السيارة معك أثناء اختبار القيادة على الطريق؟","o":["الفاحص فقط؛ لا يُسمح بالركاب","صديق واحد في المقعد الخلفي","أحد والديك في المقعد الخلفي","أي شخص يحمل رخصة سارية"],"h1":"في الاختبار لا يوجد إلا أنت والشخص الذي يقيّمك.","h2":"في Hawaii لا يُسمح بالركاب أثناء اختبار القيادة على الطريق، لذلك يركب معك الفاحص فقط.","p":"صحيح. لا يُسمح بالركاب أثناء اختبار القيادة على الطريق."},"ref":{"doc":"HI","page":15}},{"id":"hi-042","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, car insurance must include basic benefits for medical and rehabilitation costs. Up to how much per person?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In Hawaii the basic insurance benefits cover up to $10,000 per person for medical and rehabilitation costs.","p":"Right. Basic benefits cover up to $10,000 per person."},"es":{"q":"En Hawái, el seguro del carro debe incluir beneficios básicos para gastos médicos y de rehabilitación. ¿Hasta cuánto por persona?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Hawái los beneficios básicos del seguro cubren hasta $10,000 por persona en gastos médicos y de rehabilitación.","p":"Correcto. Los beneficios básicos cubren hasta $10,000 por persona."},"zh":{"q":"在 Hawaii，汽车保险必须包括医疗和康复费用的基本保障。每人最多赔多少？","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"它和财产损失的最低金额一样。","h2":"在 Hawaii，基本保险保障每人最多支付 $10,000 的医疗和康复费用。","p":"对。基本保障每人最多 $10,000。"},"vi":{"q":"Ở Hawaii, bảo hiểm xe phải có quyền lợi cơ bản cho chi phí y tế và phục hồi chức năng. Tối đa bao nhiêu cho mỗi người?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"Đó là cùng số tiền với mức tối thiểu cho thiệt hại tài sản.","h2":"Ở Hawaii, quyền lợi bảo hiểm cơ bản trả tối đa $10,000 cho mỗi người cho chi phí y tế và phục hồi chức năng.","p":"Đúng. Quyền lợi cơ bản trả tối đa $10,000 cho mỗi người."},"tl":{"q":"Sa Hawaii, dapat may basic benefits ang insurance ng kotse para sa gastos sa pagpapagamot at rehabilitation. Hanggang magkano bawat tao?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"Pareho ito ng halaga ng minimum para sa pinsala sa ari-arian.","h2":"Sa Hawaii, sakop ng basic insurance benefits ang hanggang $10,000 bawat tao para sa gastos sa pagpapagamot at rehabilitation.","p":"Tama. Sakop ng basic benefits ang hanggang $10,000 bawat tao."},"ar":{"q":"في Hawaii، يجب أن يشمل تأمين السيارة مزايا أساسية لتكاليف العلاج وإعادة التأهيل. حتى كم لكل شخص؟","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"هو نفس المبلغ الأدنى لأضرار الممتلكات.","h2":"في Hawaii تغطي مزايا التأمين الأساسية حتى $10,000 لكل شخص لتكاليف العلاج وإعادة التأهيل.","p":"صحيح. المزايا الأساسية تغطي حتى $10,000 لكل شخص."},"ref":{"doc":"HI","page":54}},{"id":"hi-043","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the largest fine for each violation of the motor vehicle insurance law?","o":["$100","$5,000","$500","$50,000"],"h1":"It is a four-digit amount.","h2":"In Hawaii each violation of the motor vehicle insurance law can bring a fine of up to $5,000.","p":"Right. The fine can be as high as $5,000 for each violation."},"es":{"q":"En Hawái, ¿cuál es la multa más alta por cada infracción de la ley de seguro de vehículos?","o":["$100","$5,000","$500","$50,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Hawái cada infracción de la ley de seguro de vehículos puede tener una multa de hasta $5,000.","p":"Correcto. La multa puede llegar a $5,000 por cada infracción."},"zh":{"q":"在 Hawaii，每违反一次汽车保险法，最高罚款多少？","o":["$100","$5,000","$500","$50,000"],"h1":"它是一个四位数的金额。","h2":"在 Hawaii，每违反一次汽车保险法，最高可以罚款 $5,000。","p":"对。每次违规最高可以罚 $5,000。"},"vi":{"q":"Ở Hawaii, mức phạt cao nhất cho mỗi lần vi phạm luật bảo hiểm xe cơ giới là bao nhiêu?","o":["$100","$5,000","$500","$50,000"],"h1":"Đó là một số tiền có bốn chữ số.","h2":"Ở Hawaii, mỗi lần vi phạm luật bảo hiểm xe cơ giới có thể bị phạt đến $5,000.","p":"Đúng. Mỗi lần vi phạm có thể bị phạt đến $5,000."},"tl":{"q":"Sa Hawaii, ano ang pinakamalaking multa sa bawat paglabag sa batas ng insurance ng sasakyan?","o":["$100","$5,000","$500","$50,000"],"h1":"Apat na digit ang halaga nito.","h2":"Sa Hawaii, ang bawat paglabag sa batas ng insurance ng sasakyan ay puwedeng magmulta nang hanggang $5,000.","p":"Tama. Puwedeng umabot sa $5,000 ang multa sa bawat paglabag."},"ar":{"q":"في Hawaii، ما أكبر غرامة على كل مخالفة لقانون تأمين المركبات؟","o":["$100","$5,000","$500","$50,000"],"h1":"هو مبلغ من أربعة أرقام.","h2":"في Hawaii يمكن أن تصل غرامة كل مخالفة لقانون تأمين المركبات إلى $5,000.","p":"صحيح. يمكن أن تصل الغرامة إلى $5,000 على كل مخالفة."},"ref":{"doc":"HI","page":54}},{"id":"hi-044","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, after you are convicted of certain driving offenses, how long must you keep proof of insurance (form SR-22) on file?","o":["30 days","Six months","One year","Three years"],"h1":"It is more than two years.","h2":"In Hawaii, after a conviction for certain offenses, you must file and keep proof of financial responsibility for three years.","p":"Right. You must keep the SR-22 proof on file for three years."},"es":{"q":"En Hawái, después de ser declarado culpable de ciertas infracciones de tránsito, ¿por cuánto tiempo debe mantener registrada la prueba de seguro (formulario SR-22)?","o":["30 días","Seis meses","Un año","Tres años"],"h1":"Es más de dos años.","h2":"En Hawái, después de una condena por ciertas infracciones, usted debe presentar y mantener la prueba de responsabilidad financiera durante tres años.","p":"Correcto. Debe mantener la prueba SR-22 durante tres años."},"zh":{"q":"在 Hawaii，你因某些驾驶违法行为被定罪后，必须把保险证明（SR-22 表格）存档多久？","o":["30 天","六个月","一年","三年"],"h1":"它比两年长。","h2":"在 Hawaii，因某些违法行为被定罪后，你必须提交并保持财务责任证明三年。","p":"对。你必须把 SR-22 证明存档三年。"},"vi":{"q":"Ở Hawaii, sau khi bị kết tội một số vi phạm khi lái xe, bạn phải lưu hồ sơ bằng chứng bảo hiểm (mẫu SR-22) trong bao lâu?","o":["30 ngày","Sáu tháng","Một năm","Ba năm"],"h1":"Đó là hơn hai năm.","h2":"Ở Hawaii, sau khi bị kết tội một số vi phạm, bạn phải nộp và duy trì bằng chứng trách nhiệm tài chính trong ba năm.","p":"Đúng. Bạn phải lưu hồ sơ SR-22 trong ba năm."},"tl":{"q":"Sa Hawaii, pagkatapos kang mahatulan sa ilang paglabag sa pagmamaneho, gaano katagal mo dapat panatilihing naka-file ang patunay ng insurance (form SR-22)?","o":["30 araw","Anim na buwan","Isang taon","Tatlong taon"],"h1":"Higit ito sa dalawang taon.","h2":"Sa Hawaii, pagkatapos mahatulan sa ilang paglabag, dapat kang mag-file at panatilihin ang patunay ng financial responsibility nang tatlong taon.","p":"Tama. Dapat mong panatilihing naka-file ang SR-22 nang tatlong taon."},"ar":{"q":"في Hawaii، بعد إدانتك بمخالفات قيادة معيّنة، كم مدة يجب أن تُبقي إثبات التأمين (نموذج SR-22) مسجّلًا؟","o":["30 يومًا","ستة أشهر","سنة واحدة","ثلاث سنوات"],"h1":"هي أكثر من سنتين.","h2":"في Hawaii، بعد الإدانة بمخالفات معيّنة، يجب أن تقدّم إثبات المسؤولية المالية وتُبقيه مسجّلًا ثلاث سنوات.","p":"صحيح. يجب أن تُبقي إثبات SR-22 مسجّلًا ثلاث سنوات."},"ref":{"doc":"HI","page":53}},{"id":"hi-045","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, a driver's blood alcohol level is above 0.05 but below 0.08 percent. How may the driver be considered?","o":["Impaired","Completely sober","Legally safe to drive","Under the influence only if under 18"],"h1":"It is below the level for being under the influence, but it is not safe.","h2":"In Hawaii a driver with a blood alcohol level above 0.05 and below 0.08 percent may be considered impaired.","p":"Right. Between 0.05 and 0.08 a driver may be considered impaired."},"es":{"q":"En Hawái, el nivel de alcohol en la sangre de un conductor es mayor de 0.05 pero menor de 0.08 por ciento. ¿Cómo se puede considerar al conductor?","o":["Con capacidad disminuida","Totalmente sobrio","Legalmente seguro para manejar","Bajo la influencia solo si tiene menos de 18 años"],"h1":"Está por debajo del nivel de estar bajo la influencia, pero no es seguro.","h2":"En Hawái un conductor con un nivel de alcohol en la sangre mayor de 0.05 y menor de 0.08 por ciento puede considerarse con capacidad disminuida.","p":"Correcto. Entre 0.05 y 0.08 se puede considerar que el conductor tiene la capacidad disminuida."},"zh":{"q":"在 Hawaii，一个司机的血液酒精浓度高于 0.05% 但低于 0.08%。这个司机可能被认为是什么状态？","o":["能力受损","完全清醒","法律上可以安全开车","只有在 18 岁以下时才算酒后驾驶"],"h1":"它低于酒后驾驶的标准，但不安全。","h2":"在 Hawaii，血液酒精浓度高于 0.05% 并低于 0.08% 的司机，可能被认为能力受损。","p":"对。在 0.05 到 0.08 之间，司机可能被认为能力受损。"},"vi":{"q":"Ở Hawaii, nồng độ cồn trong máu của một tài xế trên 0.05 nhưng dưới 0.08 phần trăm. Tài xế đó có thể bị xem là thế nào?","o":["Bị suy giảm khả năng lái xe","Hoàn toàn tỉnh táo","Được phép lái xe an toàn theo luật","Chỉ bị xem là say rượu nếu dưới 18 tuổi"],"h1":"Nó thấp hơn mức bị xem là say rượu, nhưng không an toàn.","h2":"Ở Hawaii, tài xế có nồng độ cồn trong máu trên 0.05 và dưới 0.08 phần trăm có thể bị xem là bị suy giảm khả năng lái xe.","p":"Đúng. Từ 0.05 đến 0.08, tài xế có thể bị xem là bị suy giảm khả năng lái xe."},"tl":{"q":"Sa Hawaii, ang blood alcohol level ng isang driver ay higit sa 0.05 pero mas mababa sa 0.08 porsiyento. Paano puwedeng ituring ang driver?","o":["Impaired","Ganap na hindi lasing","Ligtas magmaneho ayon sa batas","Under the influence lang kung wala pang 18"],"h1":"Mas mababa ito sa antas ng under the influence, pero hindi ito ligtas.","h2":"Sa Hawaii, ang driver na may blood alcohol level na higit sa 0.05 at mas mababa sa 0.08 porsiyento ay puwedeng ituring na impaired.","p":"Tama. Sa pagitan ng 0.05 at 0.08, puwedeng ituring na impaired ang driver."},"ar":{"q":"في Hawaii، نسبة الكحول في دم سائق أعلى من 0.05 لكن أقل من 0.08 بالمئة. كيف يمكن أن يُعتبر هذا السائق؟","o":["ضعيف القدرة على القيادة","صاحٍ تمامًا","آمن للقيادة حسب القانون","تحت تأثير الكحول فقط إذا كان عمره أقل من 18 سنة"],"h1":"هي أقل من حدّ القيادة تحت تأثير الكحول، لكنها ليست آمنة.","h2":"في Hawaii يمكن أن يُعتبر السائق الذي نسبة الكحول في دمه أعلى من 0.05 وأقل من 0.08 بالمئة ضعيف القدرة على القيادة.","p":"صحيح. بين 0.05 و0.08 يمكن أن يُعتبر السائق ضعيف القدرة على القيادة."},"ref":{"doc":"HI","page":56}},{"id":"hi-046","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where is it against the law to drink or have an alcoholic drink in your possession?","o":["Only inside a moving car after midnight","Only within 100 feet of a school","On any public highway or public sidewalk","Only on freeways"],"h1":"It covers every public road and the walkways beside them.","h2":"In Hawaii it is against the law to drink or possess an alcoholic drink on any public highway or public sidewalk.","p":"Right. No drinking or possessing alcohol on public highways or sidewalks."},"es":{"q":"En Hawái, ¿dónde es ilegal tomar o tener en su poder una bebida alcohólica?","o":["Solo dentro de un carro en movimiento después de la medianoche","Solo a menos de 100 pies de una escuela","En cualquier carretera pública o acera pública","Solo en las autopistas"],"h1":"Incluye todas las vías públicas y las aceras a su lado.","h2":"En Hawái es ilegal tomar o tener una bebida alcohólica en cualquier carretera pública o acera pública.","p":"Correcto. No se puede tomar ni tener alcohol en carreteras ni aceras públicas."},"zh":{"q":"在 Hawaii，在哪里喝含酒精的饮料或带着含酒精的饮料是违法的？","o":["只有午夜以后在行驶的车里","只有在学校 100 英尺以内","在任何公共道路或公共人行道上","只有在高速公路上"],"h1":"它包括所有公共道路和旁边的人行道。","h2":"在 Hawaii，在任何公共道路或公共人行道上喝或带着含酒精的饮料都是违法的。","p":"对。在公共道路和人行道上不能喝酒，也不能带着酒。"},"vi":{"q":"Ở Hawaii, uống hoặc mang theo đồ uống có cồn ở đâu là phạm luật?","o":["Chỉ trong xe đang chạy sau nửa đêm","Chỉ trong vòng 100 feet quanh trường học","Trên bất kỳ đường công cộng hoặc vỉa hè công cộng nào","Chỉ trên xa lộ"],"h1":"Nó gồm mọi con đường công cộng và lối đi bộ bên cạnh.","h2":"Ở Hawaii, uống hoặc mang theo đồ uống có cồn trên bất kỳ đường công cộng hoặc vỉa hè công cộng nào là phạm luật.","p":"Đúng. Không được uống hoặc mang theo rượu bia trên đường công cộng hoặc vỉa hè."},"tl":{"q":"Sa Hawaii, saan labag sa batas ang uminom o magdala ng inuming may alak?","o":["Sa loob lang ng umaandar na kotse pagkalipas ng hatinggabi","Sa loob lang ng 100 talampakan mula sa paaralan","Sa kahit anong pampublikong highway o pampublikong bangketa","Sa mga freeway lang"],"h1":"Sakop nito ang bawat pampublikong daan at ang mga lakaran sa tabi nito.","h2":"Sa Hawaii, labag sa batas ang uminom o magdala ng inuming may alak sa kahit anong pampublikong highway o pampublikong bangketa.","p":"Tama. Bawal uminom o magdala ng alak sa mga pampublikong highway o bangketa."},"ar":{"q":"في Hawaii، أين يكون شرب مشروب كحولي أو حمله مخالفًا للقانون؟","o":["فقط داخل سيارة تسير بعد منتصف الليل","فقط على بعد أقل من 100 قدم من مدرسة","على أي طريق عام أو رصيف عام","فقط على الطرق السريعة"],"h1":"يشمل كل الطرق العامة والممرات التي بجانبها.","h2":"في Hawaii من المخالف للقانون أن تشرب مشروبًا كحوليًا أو تحمله على أي طريق عام أو رصيف عام.","p":"صحيح. يُمنع شرب الكحول أو حمله على الطرق العامة والأرصفة العامة."},"ref":{"doc":"HI","page":56}},{"id":"hi-047","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, it is against the law to leave a child alone in a car for five minutes or longer. Children under what age does this law protect?","o":["Under 4","Under 9","Under 13","Under 16"],"h1":"It is the age just before ten.","h2":"In Hawaii you may not leave a child under nine years old unattended in a car for five minutes or longer.","p":"Right. Never leave a child under nine alone in a car for five minutes or more."},"es":{"q":"En Hawái, es ilegal dejar a un niño solo en un carro por cinco minutos o más. ¿A los niños menores de qué edad protege esta ley?","o":["Menores de 4 años","Menores de 9 años","Menores de 13 años","Menores de 16 años"],"h1":"Es la edad justo antes de los diez.","h2":"En Hawái no se puede dejar a un niño menor de nueve años solo en un carro por cinco minutos o más.","p":"Correcto. Nunca deje a un niño menor de nueve años solo en un carro por cinco minutos o más."},"zh":{"q":"在 Hawaii，把孩子单独留在车里五分钟或更久是违法的。这条法律保护几岁以下的孩子？","o":["4 岁以下","9 岁以下","13 岁以下","16 岁以下"],"h1":"它是十岁前一年的年龄。","h2":"在 Hawaii，你不能把九岁以下的孩子单独留在车里五分钟或更久。","p":"对。绝对不要把九岁以下的孩子单独留在车里五分钟或更久。"},"vi":{"q":"Ở Hawaii, để trẻ em một mình trong xe từ năm phút trở lên là phạm luật. Luật này bảo vệ trẻ em dưới bao nhiêu tuổi?","o":["Dưới 4 tuổi","Dưới 9 tuổi","Dưới 13 tuổi","Dưới 16 tuổi"],"h1":"Đó là tuổi ngay trước mười tuổi.","h2":"Ở Hawaii, bạn không được để trẻ em dưới chín tuổi một mình trong xe từ năm phút trở lên.","p":"Đúng. Đừng bao giờ để trẻ em dưới chín tuổi một mình trong xe từ năm phút trở lên."},"tl":{"q":"Sa Hawaii, labag sa batas ang iwanang mag-isa ang bata sa kotse nang limang minuto o higit pa. Mga batang wala pang ilang taon ang pinoprotektahan ng batas na ito?","o":["Wala pang 4","Wala pang 9","Wala pang 13","Wala pang 16"],"h1":"Ito ang edad bago mag-sampu.","h2":"Sa Hawaii, hindi mo puwedeng iwanang walang bantay ang batang wala pang siyam na taong gulang sa kotse nang limang minuto o higit pa.","p":"Tama. Huwag kailanman iwanang mag-isa sa kotse ang batang wala pang siyam nang limang minuto o higit pa."},"ar":{"q":"في Hawaii، من المخالف للقانون ترك طفل وحده في السيارة خمس دقائق أو أكثر. الأطفال الذين عمرهم أقل من كم يحميهم هذا القانون؟","o":["أقل من 4 سنوات","أقل من 9 سنوات","أقل من 13 سنة","أقل من 16 سنة"],"h1":"هو العمر الذي قبل العاشرة مباشرة.","h2":"في Hawaii لا يجوز لك أن تترك طفلًا عمره أقل من تسع سنوات وحده في السيارة خمس دقائق أو أكثر.","p":"صحيح. لا تترك أبدًا طفلًا عمره أقل من تسع سنوات وحده في السيارة خمس دقائق أو أكثر."},"ref":{"doc":"HI","page":64}},{"id":"hi-048","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, how much can it cost you if you do not stop for a school bus with flashing red lights when the law requires it?","o":["$50","$150","$250","$1,000"],"h1":"It is a four-digit amount.","h2":"In Hawaii failing to stop for a school bus with flashing red lights when required can cost you $1,000.","p":"Right. Not stopping for a school bus can cost $1,000."},"es":{"q":"En Hawái, ¿cuánto le puede costar no detenerse ante un autobús escolar con luces rojas intermitentes cuando la ley lo exige?","o":["$50","$150","$250","$1,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Hawái no detenerse ante un autobús escolar con luces rojas intermitentes cuando se debe le puede costar $1,000.","p":"Correcto. No detenerse ante un autobús escolar puede costar $1,000."},"zh":{"q":"在 Hawaii，法律要求停车时，如果你没有为闪着红灯的校车停车，可能要付多少钱？","o":["$50","$150","$250","$1,000"],"h1":"它是一个四位数的金额。","h2":"在 Hawaii，法律要求停车时，如果你没有为闪着红灯的校车停车，可能要付 $1,000。","p":"对。不为校车停车可能要付 $1,000。"},"vi":{"q":"Ở Hawaii, nếu bạn không dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy khi luật bắt buộc, bạn có thể bị mất bao nhiêu tiền?","o":["$50","$150","$250","$1,000"],"h1":"Đó là một số tiền có bốn chữ số.","h2":"Ở Hawaii, không dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy khi luật bắt buộc có thể làm bạn mất $1,000.","p":"Đúng. Không dừng lại cho xe buýt trường học có thể mất $1,000."},"tl":{"q":"Sa Hawaii, magkano ang puwede mong bayaran kung hindi ka huminto para sa school bus na may kumikislap na pulang ilaw kapag hinihingi ito ng batas?","o":["$50","$150","$250","$1,000"],"h1":"Apat na digit ang halaga nito.","h2":"Sa Hawaii, ang hindi paghinto para sa school bus na may kumikislap na pulang ilaw kapag kailangan ay puwedeng magkahalaga sa iyo ng $1,000.","p":"Tama. Ang hindi paghinto para sa school bus ay puwedeng magkahalaga ng $1,000."},"ar":{"q":"في Hawaii، كم يمكن أن يكلّفك عدم التوقف لحافلة مدرسية أضواؤها الحمراء تومض عندما يطلب القانون ذلك؟","o":["$50","$150","$250","$1,000"],"h1":"هو مبلغ من أربعة أرقام.","h2":"في Hawaii، عدم التوقف لحافلة مدرسية أضواؤها الحمراء تومض عندما يجب ذلك يمكن أن يكلّفك $1,000.","p":"صحيح. عدم التوقف لحافلة مدرسية يمكن أن يكلّف $1,000."},"ref":{"doc":"HI","page":96}},{"id":"hi-049","scope":"HI","cat":"signals","sign":null,"c":0,"en":{"q":"In Hawaii, when may you turn left on a red light after stopping?","o":["From a one-way street onto another one-way street going left","From a two-way street when no cars are coming","Never; a left turn on red is always illegal","Only when a police officer is standing nearby"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Hawaii, after stopping, you may turn left on red from a one-way street onto a one-way street where traffic moves to the left, unless a sign prohibits it.","p":"Right. Left on red is allowed only from one one-way street onto another going left."},"es":{"q":"En Hawái, ¿cuándo puede dar vuelta a la izquierda con la luz roja después de detenerse?","o":["De una calle de un solo sentido a otra de un solo sentido que va a la izquierda","Desde una calle de doble sentido si no vienen carros","Nunca; la vuelta a la izquierda con luz roja siempre es ilegal","Solo cuando hay un policía parado cerca"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Hawái, después de detenerse, usted puede dar vuelta a la izquierda con luz roja de una calle de un solo sentido a otra de un solo sentido donde el tráfico va hacia la izquierda, si no hay un letrero que lo prohíba.","p":"Correcto. La vuelta a la izquierda con luz roja solo se permite de una calle de un solo sentido a otra que va a la izquierda."},"zh":{"q":"在 Hawaii，停车以后，什么时候可以在红灯时左转？","o":["从单行道转进另一条向左行驶的单行道","从双向道路转出，而且没有车过来时","永远不可以；红灯左转一直是违法的","只有警察站在附近时"],"h1":"两条路都必须只有一个方向的车流。","h2":"在 Hawaii，停车以后，你可以在红灯时从单行道左转进车流向左行驶的单行道，除非有标志禁止。","p":"对。只有从单行道转进另一条向左行驶的单行道时，才可以红灯左转。"},"vi":{"q":"Ở Hawaii, khi nào bạn được rẽ trái lúc đèn đỏ sau khi đã dừng lại?","o":["Từ đường một chiều vào một đường một chiều khác đi về bên trái","Từ đường hai chiều khi không có xe đến","Không bao giờ; rẽ trái lúc đèn đỏ luôn phạm luật","Chỉ khi có cảnh sát đứng gần đó"],"h1":"Cả hai con đường đều phải chỉ có xe chạy một chiều.","h2":"Ở Hawaii, sau khi dừng lại, bạn được rẽ trái lúc đèn đỏ từ đường một chiều vào đường một chiều có xe chạy về bên trái, trừ khi có biển báo cấm.","p":"Đúng. Rẽ trái lúc đèn đỏ chỉ được phép từ đường một chiều vào một đường một chiều khác đi về bên trái."},"tl":{"q":"Sa Hawaii, kailan ka puwedeng kumaliwa sa pulang ilaw pagkatapos huminto?","o":["Mula sa one-way na kalye papunta sa isa pang one-way na kalye na papakaliwa","Mula sa two-way na kalye kapag walang paparating na kotse","Hindi kailanman; laging labag sa batas ang pagkaliwa sa pula","Kapag may pulis lang na nakatayo sa malapit"],"h1":"Dapat iisang direksyon lang ang daloy ng trapiko sa parehong kalye.","h2":"Sa Hawaii, pagkatapos huminto, puwede kang kumaliwa sa pula mula sa one-way na kalye papunta sa one-way na kalye na papakaliwa ang trapiko, maliban kung may karatulang nagbabawal.","p":"Tama. Puwede lang kumaliwa sa pula mula sa isang one-way na kalye papunta sa isa pang papakaliwa."},"ar":{"q":"في Hawaii، متى يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء بعد التوقف؟","o":["من شارع باتجاه واحد إلى شارع آخر باتجاه واحد يسير نحو اليسار","من شارع باتجاهين عندما لا تأتي سيارات","أبدًا؛ الانعطاف يسارًا عند الإشارة الحمراء مخالف دائمًا","فقط عندما يقف شرطي في مكان قريب"],"h1":"يجب أن تسير السيارات في الشارعين باتجاه واحد فقط.","h2":"في Hawaii، بعد التوقف، يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء من شارع باتجاه واحد إلى شارع باتجاه واحد تسير فيه السيارات نحو اليسار، إلا إذا منعت ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الإشارة الحمراء مسموح فقط من شارع باتجاه واحد إلى آخر يسير نحو اليسار."},"ref":{"doc":"HI","page":39}},{"id":"hi-050","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, when you park along a curb, what is the farthest your car may be from the curb?","o":["24 inches","18 inches","12 inches","3 feet"],"h1":"It is one foot.","h2":"In Hawaii you may not park more than 12 inches from the curb.","p":"Right. Park no more than 12 inches from the curb."},"es":{"q":"En Hawái, cuando se estaciona junto a la acera, ¿a qué distancia máxima de la acera puede quedar su carro?","o":["24 pulgadas","18 pulgadas","12 pulgadas","3 pies"],"h1":"Es un pie.","h2":"En Hawái no se puede estacionar a más de 12 pulgadas de la acera.","p":"Correcto. Estaciónese a no más de 12 pulgadas de la acera."},"zh":{"q":"在 Hawaii，你沿着路边停车时，车离路边最远可以多远？","o":["24 英寸","18 英寸","12 英寸","3 英尺"],"h1":"它是一英尺。","h2":"在 Hawaii，你停车时离路边不能超过 12 英寸。","p":"对。停车时离路边不要超过 12 英寸。"},"vi":{"q":"Ở Hawaii, khi bạn đậu xe dọc theo lề đường, xe của bạn được cách lề đường xa nhất là bao nhiêu?","o":["24 inch","18 inch","12 inch","3 feet"],"h1":"Đó là một foot.","h2":"Ở Hawaii, bạn không được đậu xe cách lề đường hơn 12 inch.","p":"Đúng. Đậu xe cách lề đường không quá 12 inch."},"tl":{"q":"Sa Hawaii, kapag pumarada ka sa tabi ng gilid ng bangketa (curb), gaano kalayo ang pinakamalayong puwedeng layo ng kotse mo rito?","o":["24 pulgada","18 pulgada","12 pulgada","3 talampakan"],"h1":"Isang talampakan ito.","h2":"Sa Hawaii, hindi ka puwedeng pumarada nang higit sa 12 pulgada ang layo mula sa curb.","p":"Tama. Pumarada nang hindi hihigit sa 12 pulgada mula sa curb."},"ar":{"q":"في Hawaii، عندما تركن بجانب حافة الرصيف، ما أبعد مسافة يجوز أن تكون بين سيارتك وحافة الرصيف؟","o":["24 بوصة","18 بوصة","12 بوصة","3 أقدام"],"h1":"هي قدم واحدة.","h2":"في Hawaii لا يجوز لك أن تركن على بعد أكثر من 12 بوصة من حافة الرصيف.","p":"صحيح. اركن على بعد لا يزيد عن 12 بوصة من حافة الرصيف."},"ref":{"doc":"HI","page":28}},{"id":"hi-051","scope":"HI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Hawaii, how long may you leave your car parked in one spot on a public street without moving it?","o":["No more than 8 hours","No more than 24 hours","No more than 72 hours","As long as you like"],"h1":"It is one full day.","h2":"In Hawaii you may not park on a public street or highway for more than 24 hours in a row.","p":"Right. Parking on a public street is limited to 24 hours in a row."},"es":{"q":"En Hawái, ¿cuánto tiempo puede dejar su carro estacionado en el mismo lugar de una calle pública sin moverlo?","o":["No más de 8 horas","No más de 24 horas","No más de 72 horas","El tiempo que quiera"],"h1":"Es un día completo.","h2":"En Hawái no se puede estacionar en una calle o carretera pública por más de 24 horas seguidas.","p":"Correcto. Estacionarse en una calle pública está limitado a 24 horas seguidas."},"zh":{"q":"在 Hawaii，你可以把车停在公共街道的同一个地方、不移动，最长多久？","o":["不超过 8 小时","不超过 24 小时","不超过 72 小时","想停多久都可以"],"h1":"它是一整天。","h2":"在 Hawaii，你不能在公共街道或公路上连续停车超过 24 小时。","p":"对。在公共街道上连续停车最多 24 小时。"},"vi":{"q":"Ở Hawaii, bạn được để xe đậu ở một chỗ trên đường công cộng mà không di chuyển trong bao lâu?","o":["Không quá 8 giờ","Không quá 24 giờ","Không quá 72 giờ","Bao lâu cũng được"],"h1":"Đó là một ngày trọn vẹn.","h2":"Ở Hawaii, bạn không được đậu xe trên đường hoặc xa lộ công cộng quá 24 giờ liên tục.","p":"Đúng. Đậu xe trên đường công cộng chỉ được tối đa 24 giờ liên tục."},"tl":{"q":"Sa Hawaii, gaano katagal mo puwedeng iwanang nakaparada ang kotse mo sa iisang puwesto sa pampublikong kalye nang hindi ito inaalis?","o":["Hindi hihigit sa 8 oras","Hindi hihigit sa 24 oras","Hindi hihigit sa 72 oras","Kahit gaano katagal mo gusto"],"h1":"Isang buong araw ito.","h2":"Sa Hawaii, hindi ka puwedeng pumarada sa pampublikong kalye o highway nang higit sa 24 oras nang tuloy-tuloy.","p":"Tama. Hanggang 24 oras nang tuloy-tuloy lang ang pagparada sa pampublikong kalye."},"ar":{"q":"في Hawaii، كم مدة يجوز أن تترك سيارتك مركونة في المكان نفسه في شارع عام دون أن تحرّكها؟","o":["ليس أكثر من 8 ساعات","ليس أكثر من 24 ساعة","ليس أكثر من 72 ساعة","أي مدة تريدها"],"h1":"هي يوم كامل.","h2":"في Hawaii لا يجوز لك أن تركن في شارع عام أو طريق عام أكثر من 24 ساعة متواصلة.","p":"صحيح. الركن في الشارع العام محدود بـ 24 ساعة متواصلة."},"ref":{"doc":"HI","page":29}},{"id":"hi-052","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, outside business districts, how fast may a bicyclist ride on a sidewalk?","o":["15 mph or less","20 mph or less","Any speed, if the sidewalk is empty","10 mph or less, yielding to pedestrians"],"h1":"It is a slow speed, and people walking come first.","h2":"In Hawaii, outside business districts, a bicyclist may ride on a sidewalk at 10 mph or less and must yield to pedestrians.","p":"Right. On sidewalks outside business districts, bicycles go 10 mph or less and yield to people walking."},"es":{"q":"En Hawái, fuera de los distritos comerciales, ¿a qué velocidad puede ir un ciclista por la acera?","o":["15 mph o menos","20 mph o menos","A cualquier velocidad, si la acera está vacía","10 mph o menos, cediendo el paso a los peatones"],"h1":"Es una velocidad baja, y las personas que caminan van primero.","h2":"En Hawái, fuera de los distritos comerciales, un ciclista puede ir por la acera a 10 mph o menos y debe ceder el paso a los peatones.","p":"Correcto. En las aceras fuera de los distritos comerciales, las bicicletas van a 10 mph o menos y ceden el paso a los peatones."},"zh":{"q":"在 Hawaii，在商业区以外，骑自行车的人在人行道上可以骑多快？","o":["每小时 15 英里（15 mph）或更慢","20 mph 或更慢","人行道上没人时，多快都可以","10 mph 或更慢，并让行人先走"],"h1":"它是一个慢速度，而且走路的人优先。","h2":"在 Hawaii，在商业区以外，骑自行车的人可以在人行道上以 10 mph 或更慢的速度骑车，而且必须让行人先走。","p":"对。在商业区以外的人行道上，自行车速度是 10 mph 或更慢，并让走路的人先走。"},"vi":{"q":"Ở Hawaii, bên ngoài khu thương mại, người đi xe đạp được chạy trên vỉa hè nhanh bao nhiêu?","o":["15 mph trở xuống","20 mph trở xuống","Bao nhiêu cũng được, nếu vỉa hè không có ai","10 mph trở xuống, nhường đường cho người đi bộ"],"h1":"Đó là tốc độ chậm, và người đi bộ được ưu tiên.","h2":"Ở Hawaii, bên ngoài khu thương mại, người đi xe đạp được chạy trên vỉa hè với tốc độ 10 mph trở xuống và phải nhường đường cho người đi bộ.","p":"Đúng. Trên vỉa hè bên ngoài khu thương mại, xe đạp chạy 10 mph trở xuống và nhường đường cho người đi bộ."},"tl":{"q":"Sa Hawaii, sa labas ng mga business district, gaano kabilis puwedeng magbisikleta sa bangketa?","o":["15 mph o mas mabagal","20 mph o mas mabagal","Kahit anong bilis, kung walang tao sa bangketa","10 mph o mas mabagal, at pinauuna ang mga naglalakad"],"h1":"Mabagal na bilis ito, at nauuna ang mga taong naglalakad.","h2":"Sa Hawaii, sa labas ng mga business district, puwedeng magbisikleta sa bangketa sa 10 mph o mas mabagal, at dapat paunahin ang mga naglalakad.","p":"Tama. Sa mga bangketa sa labas ng business district, 10 mph o mas mabagal ang bisikleta at pinauuna ang mga naglalakad."},"ar":{"q":"في Hawaii، خارج المناطق التجارية، بأي سرعة يجوز لراكب الدراجة أن يسير على الرصيف؟","o":["15 mph أو أقل","20 mph أو أقل","أي سرعة، إذا كان الرصيف فارغًا","10 mph أو أقل، مع إعطاء الأولوية للمشاة"],"h1":"هي سرعة بطيئة، والأشخاص الذين يمشون أولًا.","h2":"في Hawaii، خارج المناطق التجارية، يجوز لراكب الدراجة أن يسير على الرصيف بسرعة 10 mph أو أقل، ويجب أن يعطي الأولوية للمشاة.","p":"صحيح. على الأرصفة خارج المناطق التجارية تسير الدراجات بسرعة 10 mph أو أقل وتعطي الأولوية للمشاة."},"ref":{"doc":"HI","page":98}},{"id":"hi-053","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a person is convicted of drunk driving while driving without a license. How long must they wait before they can be licensed?","o":["30 days","Six months","Two years","Ten years"],"h1":"It is longer than one year.","h2":"In Hawaii, a person convicted of drunk driving while unlicensed cannot be licensed for two years.","p":"Right. The wait is two years."},"es":{"q":"En Hawái, una persona es condenada por manejar ebria mientras manejaba sin licencia. ¿Cuánto tiempo debe esperar para poder obtener una licencia?","o":["30 días","Seis meses","Dos años","Diez años"],"h1":"Es más de un año.","h2":"En Hawái, una persona condenada por manejar ebria sin licencia no puede obtener una licencia durante dos años.","p":"Correcto. La espera es de dos años."},"ref":{"doc":"HI","page":10}},{"id":"hi-054","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, which license class do you need to ride a moped on the highway?","o":["Class 1","Class 2","Class 3","Class 4"],"h1":"Mopeds come first in the list of classes.","h2":"In Hawaii you need a class 1 license to ride a moped on the highway.","p":"Right. A moped needs a class 1 license."},"es":{"q":"En Hawái, ¿qué clase de licencia necesita para manejar un ciclomotor (moped) en la carretera?","o":["Clase 1","Clase 2","Clase 3","Clase 4"],"h1":"Los ciclomotores van primero en la lista de clases.","h2":"En Hawái usted necesita una licencia de clase 1 para manejar un ciclomotor en la carretera.","p":"Correcto. Un ciclomotor necesita licencia de clase 1."},"ref":{"doc":"HI","page":11}},{"id":"hi-055","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how old must you be before you can apply for a license class larger than class 3?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"It is the same age as the supervising driver for a permit holder.","h2":"In Hawaii you must be at least 21 years old to apply for any license class larger than class 3.","p":"Right. Larger license classes start at age 21."},"es":{"q":"En Hawái, ¿qué edad debe tener para solicitar una licencia de una clase mayor que la clase 3?","o":["Al menos 16 años","Al menos 18 años","Al menos 25 años","Al menos 21 años"],"h1":"Es la misma edad que debe tener quien supervisa a una persona con permiso.","h2":"En Hawái usted debe tener al menos 21 años para solicitar cualquier licencia de una clase mayor que la clase 3.","p":"Correcto. Las clases de licencia mayores empiezan a los 21 años."},"ref":{"doc":"HI","page":12}},{"id":"hi-056","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what must a teen complete before getting a provisional license?","o":["A short online video about seat belts, with no driving","A state-certified driver education course, in class and behind the wheel","A first aid and CPR class at a community center","A car repair course at a trade school"],"h1":"You need two certificates from it: one for the classroom part and one for driving.","h2":"In Hawaii a teen must complete a state-certified driver education course, with classroom and behind-the-wheel certificates, before getting a provisional license.","p":"Right. Driver education, in class and behind the wheel, comes first."},"es":{"q":"En Hawái, ¿qué debe completar un adolescente antes de obtener una licencia provisional?","o":["Un video corto en línea sobre cinturones, sin manejar","Un curso de educación vial certificado por el estado, en clase y al volante","Una clase de primeros auxilios y RCP en un centro comunitario","Un curso de reparación de autos en una escuela técnica"],"h1":"Necesita dos certificados del curso: uno de la parte en clase y otro de manejo.","h2":"En Hawái un adolescente debe completar un curso de educación vial certificado por el estado, con certificados de clase y de manejo, antes de obtener una licencia provisional.","p":"Correcto. Primero va la educación vial, en clase y al volante."},"ref":{"doc":"HI","page":13}},{"id":"hi-057","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a 16-year-old applies for a permit. Whose consent is needed, unless the teen is married or emancipated?","o":["Only a school counselor","Any adult relative","Each living parent or legal guardian","No one's consent is needed"],"h1":"Think of the people who have legal custody of the teen.","h2":"In Hawaii an applicant under 18 needs consent from each living parent or legal guardian, unless the teen is married or emancipated.","p":"Right. Each living parent or guardian must consent."},"es":{"q":"En Hawái, un joven de 16 años solicita un permiso. ¿De quién necesita consentimiento, a menos que esté casado o emancipado?","o":["Solo de un consejero escolar","De cualquier pariente adulto","De cada padre o madre vivo, o tutor legal","No necesita el consentimiento de nadie"],"h1":"Piense en las personas que tienen la custodia legal del joven.","h2":"En Hawái un solicitante menor de 18 años necesita el consentimiento de cada padre o madre vivo, o tutor legal, a menos que esté casado o emancipado.","p":"Correcto. Cada padre, madre o tutor vivo debe dar su consentimiento."},"ref":{"doc":"HI","page":13}},{"id":"hi-058","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, which vehicle may you NOT use for the class 3 road test?","o":["A small sedan","A pickup truck","A minivan","An autocycle"],"h1":"You may drive it with a class 3 license, but not for the test.","h2":"In Hawaii you may not use an autocycle for the class 3 road test, even though a class 3 license lets you drive one.","p":"Right. An autocycle cannot be used for the class 3 road test."},"es":{"q":"En Hawái, ¿qué vehículo NO puede usar para el examen de manejo de clase 3?","o":["Un sedán pequeño","Una camioneta pickup","Una minivan","Un autociclo"],"h1":"Puede manejarlo con licencia de clase 3, pero no para el examen.","h2":"En Hawái no puede usar un autociclo para el examen de manejo de clase 3, aunque la licencia de clase 3 le permite manejarlo.","p":"Correcto. No se puede usar un autociclo para el examen de clase 3."},"ref":{"doc":"HI","page":15}},{"id":"hi-059","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, how often must an ambulance pass a safety inspection?","o":["Every six months","Every two years","Once a year","Every five years"],"h1":"It is more often than a regular car.","h2":"In Hawaii an ambulance must pass a safety inspection every six months.","p":"Right. Ambulances are inspected every six months."},"es":{"q":"En Hawái, ¿cada cuánto debe pasar una inspección de seguridad una ambulancia?","o":["Cada seis meses","Cada dos años","Una vez al año","Cada cinco años"],"h1":"Es más seguido que un auto normal.","h2":"En Hawái una ambulancia debe pasar una inspección de seguridad cada seis meses.","p":"Correcto. Las ambulancias se inspeccionan cada seis meses."},"ref":{"doc":"HI","page":18}},{"id":"hi-060","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, a driver with no alcohol or drug offense in the past 10 years tests at 0.08 or more, but below 0.15. How long is the license revoked by the state?","o":["30 days","One year","90 days","Five years"],"h1":"It is longer than six months but shorter than two years.","h2":"In Hawaii, a driver with no prior alcohol or drug enforcement contact in 10 years who tests at 0.08 or more, but below the 0.15 'highly intoxicated' level, has the license revoked for one year.","p":"Right. A first administrative revocation lasts one year."},"es":{"q":"En Hawái, un conductor sin infracciones de alcohol o drogas en los últimos 10 años da 0.08 o más, pero menos de 0.15, en la prueba. ¿Por cuánto tiempo le revoca el estado la licencia?","o":["30 días","Un año","90 días","Cinco años"],"h1":"Es más de seis meses pero menos de dos años.","h2":"En Hawái, a un conductor sin antecedentes de alcohol o drogas en 10 años que da 0.08 o más, pero menos del nivel de 0.15 de 'altamente intoxicado', se le revoca la licencia por un año.","p":"Correcto. La primera revocación administrativa dura un año."},"ref":{"doc":"HI","page":null}},{"id":"hi-061","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, what must you show for your car to pass its safety inspection?","o":["Your high school diploma","A receipt for your last oil change","A Hawaii auto insurance identification card","A letter from your employer"],"h1":"It proves the car is covered if there is a crash.","h2":"In Hawaii you need a Hawaii auto insurance identification card for your car to pass the safety inspection.","p":"Right. No insurance card, no inspection sticker."},"es":{"q":"En Hawái, ¿qué debe mostrar para que su auto pase la inspección de seguridad?","o":["Su diploma de secundaria","Un recibo de su último cambio de aceite","Una tarjeta de identificación de seguro de auto de Hawái","Una carta de su empleador"],"h1":"Prueba que el auto tiene cobertura si hay un choque.","h2":"En Hawái necesita una tarjeta de identificación de seguro de auto de Hawái para que su auto pase la inspección de seguridad.","p":"Correcto. Sin tarjeta de seguro, no hay calcomanía de inspección."},"ref":{"doc":"HI","page":18}},{"id":"hi-062","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, you move to a new home. How soon must you give your new address for your car's registration?","o":["Within 24 hours","Within one year","Only when the registration expires","Within 30 days"],"h1":"It is about one month.","h2":"In Hawaii you must tell the county agency your new address within 30 days after you move.","p":"Right. You have 30 days to update the registration address."},"es":{"q":"En Hawái, usted se muda a una casa nueva. ¿En cuánto tiempo debe dar su nueva dirección para el registro de su auto?","o":["Dentro de 24 horas","Dentro de un año","Solo cuando venza el registro","Dentro de 30 días"],"h1":"Es más o menos un mes.","h2":"En Hawái debe informar su nueva dirección a la agencia del condado dentro de 30 días después de mudarse.","p":"Correcto. Tiene 30 días para actualizar la dirección del registro."},"ref":{"doc":"HI","page":21}},{"id":"hi-063","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, you bring a car registered in another state. What is the longest a temporary Hawaii permit for it can last?","o":["10 days","12 months","60 days","Three years"],"h1":"It is never more than one year.","h2":"In Hawaii a temporary permit for a car registered in another state can never be longer than 12 months.","p":"Right. The temporary permit lasts 12 months at most."},"es":{"q":"En Hawái, usted trae un auto registrado en otro estado. ¿Cuánto es lo máximo que puede durar un permiso temporal de Hawái para ese auto?","o":["10 días","12 meses","60 días","Tres años"],"h1":"Nunca es más de un año.","h2":"En Hawái un permiso temporal para un auto registrado en otro estado nunca puede durar más de 12 meses.","p":"Correcto. El permiso temporal dura 12 meses como máximo."},"ref":{"doc":"HI","page":23}},{"id":"hi-064","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, which of these vehicles needs a license plate only on the back?","o":["A motorcycle","A car","A pickup truck","A van"],"h1":"It has no good place in front for a plate.","h2":"In Hawaii motorcycles, trailers and semi-trailers show a plate only on the back; other vehicles need plates front and back.","p":"Right. A motorcycle needs only a rear plate."},"es":{"q":"En Hawái, ¿cuál de estos vehículos necesita placa solo en la parte de atrás?","o":["Una motocicleta","Un auto","Una camioneta pickup","Una van"],"h1":"No tiene un buen lugar adelante para una placa.","h2":"En Hawái las motocicletas, los remolques y los semirremolques llevan placa solo atrás; los demás vehículos necesitan placa adelante y atrás.","p":"Correcto. Una motocicleta solo necesita placa trasera."},"ref":{"doc":"HI","page":23}},{"id":"hi-065","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, on which road may you NOT drive on the left half to pass, unless signs allow it?","o":["A two-lane road with no oncoming cars","A three-lane road with no oncoming cars","A road with four or more lanes for moving traffic","A one-way street"],"h1":"Think of a wide road with many lanes.","h2":"In Hawaii you must not drive on the left half of a road that has four or more lanes for moving traffic, unless signs direct you to.","p":"Right. On roads with four or more lanes, stay off the left half."},"es":{"q":"En Hawái, ¿en qué camino NO puede manejar por la mitad izquierda para rebasar, a menos que las señales lo permitan?","o":["En un camino de dos carriles sin autos en sentido contrario","En un camino de tres carriles sin autos en sentido contrario","En un camino con cuatro o más carriles de tránsito","En una calle de un solo sentido"],"h1":"Piense en un camino ancho con muchos carriles.","h2":"En Hawái no debe manejar por la mitad izquierda de un camino con cuatro o más carriles de tránsito, a menos que las señales se lo indiquen.","p":"Correcto. En caminos de cuatro o más carriles, no use la mitad izquierda."},"ref":{"doc":"HI","page":26}},{"id":"hi-066","scope":"HI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Hawaii, a train sounds its horn as it approaches a crossing. Within what distance does this mean you must stop?","o":["Within 100 feet","Within 500 feet","Within 5 miles","Within 1,500 feet"],"h1":"It is more than a quarter mile.","h2":"In Hawaii you must stop at least 15 feet from the rail when a train within 1,500 feet gives an audible warning.","p":"Right. A train within 1,500 feet that sounds a warning means stop."},"es":{"q":"En Hawái, un tren toca la bocina al acercarse a un cruce. ¿Dentro de qué distancia significa esto que usted debe detenerse?","o":["Dentro de 100 pies","Dentro de 500 pies","Dentro de 5 millas","Dentro de 1,500 pies"],"h1":"Es más de un cuarto de milla.","h2":"En Hawái debe detenerse al menos a 15 pies del riel cuando un tren a 1,500 pies o menos da una señal sonora.","p":"Correcto. Un tren a 1,500 pies o menos que da una señal sonora significa que debe detenerse."},"ref":{"doc":"HI","page":27}},{"id":"hi-067","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, how many people in the front seat may count as interfering with the driver?","o":["More than one","More than three","More than two","More than five"],"h1":"A wide front bench can hold a few people, but not too many.","h2":"In Hawaii, driving with more than three people in the front seat may count as interference with the driver, which is not allowed.","p":"Right. More than three people in front can interfere with the driver."},"es":{"q":"En Hawái, ¿cuántas personas en el asiento delantero pueden considerarse una interferencia con el conductor?","o":["Más de una","Más de tres","Más de dos","Más de cinco"],"h1":"Un asiento delantero ancho cabe a algunas personas, pero no a demasiadas.","h2":"En Hawái, manejar con más de tres personas en el asiento delantero puede considerarse interferencia con el conductor, y eso no está permitido.","p":"Correcto. Más de tres personas adelante pueden interferir con el conductor."},"ref":{"doc":"HI","page":29}},{"id":"hi-068","scope":"HI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Hawaii, a funeral procession reaches an intersection. Who has the right of way?","o":["The funeral procession","Cars on the larger road","Whoever arrives first","Cars turning right"],"h1":"You should not drive between its cars.","h2":"In Hawaii funeral processions and convoys have the right of way at intersections.","p":"Right. Let the funeral procession go through."},"es":{"q":"En Hawái, un cortejo fúnebre llega a una intersección. ¿Quién tiene el derecho de paso?","o":["El cortejo fúnebre","Los autos del camino más grande","El que llegue primero","Los autos que giran a la derecha"],"h1":"No debe meterse entre sus autos.","h2":"En Hawái los cortejos fúnebres y los convoyes tienen el derecho de paso en las intersecciones.","p":"Correcto. Deje pasar al cortejo fúnebre."},"ref":{"doc":"HI","page":29}},{"id":"hi-069","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, how much clear road must you see ahead to pass near a hill or curve?","o":["50 to 100 feet","200 to 300 feet","700 to 1,000 feet","One to two miles"],"h1":"It is more than two football fields.","h2":"In Hawaii you must not pass near a hill or curve unless you can see 700 to 1,000 feet of clear road ahead.","p":"Right. You need 700 to 1,000 feet of clear road to pass there."},"es":{"q":"En Hawái, ¿cuánto camino libre debe ver adelante para rebasar cerca de una colina o curva?","o":["De 50 a 100 pies","De 200 a 300 pies","De 700 a 1,000 pies","De una a dos millas"],"h1":"Es más que dos canchas de fútbol americano.","h2":"En Hawái no debe rebasar cerca de una colina o curva a menos que vea de 700 a 1,000 pies de camino libre adelante.","p":"Correcto. Necesita de 700 a 1,000 pies de camino libre para rebasar allí."},"ref":{"doc":"HI","page":30}},{"id":"hi-070","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, you hit a parked car and nobody is in it. What must you do?","o":["Drive away if the damage looks small and no one saw it","Wait 10 minutes for the owner, then leave without a note","Just call your insurance company sometime later that week","Find the owner, or leave a written note with your name, address and what happened"],"h1":"The owner must be able to find out who you are.","h2":"In Hawaii, if you hit an unattended vehicle, you must stop and find the owner or leave a written note with your name, address and what happened.","p":"Right. Find the owner or leave a note with your details."},"es":{"q":"En Hawái, usted choca un auto estacionado y no hay nadie adentro. ¿Qué debe hacer?","o":["Irse si el daño parece pequeño y nadie lo vio","Esperar 10 minutos al dueño y luego irse sin dejar nota","Solo llamar a su aseguradora en algún momento de esa semana","Buscar al dueño, o dejar una nota escrita con su nombre, dirección y lo que pasó"],"h1":"El dueño debe poder saber quién es usted.","h2":"En Hawái, si choca un vehículo sin nadie adentro, debe detenerse y buscar al dueño o dejar una nota escrita con su nombre, dirección y lo que pasó.","p":"Correcto. Busque al dueño o deje una nota con sus datos."},"ref":{"doc":"HI","page":52}},{"id":"hi-071","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, when may you sue another driver for a crash injury that did not cause death or lasting harm?","o":["When medical bills are more than $5,000","At any time, for any injury","Only if the police gave a ticket","Never"],"h1":"It depends on how high the medical bills are.","h2":"In Hawaii you may sue for a bodily injury only if medical bills are more than $5,000, or the injury is permanent or serious, or causes death.","p":"Right. Medical bills must be over $5,000, unless the injury is very serious."},"es":{"q":"En Hawái, ¿cuándo puede demandar a otro conductor por una lesión de choque que no causó muerte ni daño permanente?","o":["Cuando las cuentas médicas pasan de $5,000","En cualquier momento, por cualquier lesión","Solo si la policía puso una multa","Nunca"],"h1":"Depende de qué tan altas son las cuentas médicas.","h2":"En Hawái puede demandar por una lesión solo si las cuentas médicas pasan de $5,000, o la lesión es permanente o grave, o causa la muerte.","p":"Correcto. Las cuentas médicas deben pasar de $5,000, a menos que la lesión sea muy grave."},"ref":{"doc":"HI","page":54}},{"id":"hi-072","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, where may you NOT keep an opened alcoholic drink while on a public road?","o":["In a locked trunk","At home","In the area where the driver or passengers sit","In a closed cooler in a pickup bed"],"h1":"Think of the part of the car where people ride.","h2":"In Hawaii you may not keep an opened alcoholic drink in the part of the vehicle where the driver or passengers sit.","p":"Right. No open containers where people sit."},"es":{"q":"En Hawái, ¿dónde NO puede tener una bebida alcohólica abierta mientras está en un camino público?","o":["En una cajuela cerrada con llave","En su casa","En el área donde se sientan el conductor o los pasajeros","En una hielera cerrada en la caja de una pickup"],"h1":"Piense en la parte del auto donde viajan las personas.","h2":"En Hawái no puede tener una bebida alcohólica abierta en la parte del vehículo donde se sientan el conductor o los pasajeros.","p":"Correcto. No lleve envases abiertos donde se sientan las personas."},"ref":{"doc":"HI","page":56}},{"id":"hi-073","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, a person with a white cane is crossing the road, but your light is green. What must you do?","o":["Go, because your light is green","Stop and let the person cross","Honk and drive around the person","Go if the person is not in your lane yet"],"h1":"The signal does not matter here.","h2":"In Hawaii you must stop for a blind person in the road, shown by a white cane or guide dog, no matter what the signal shows.","p":"Right. Always stop for a person with a white cane or guide dog."},"es":{"q":"En Hawái, una persona con un bastón blanco está cruzando la calle, pero su semáforo está en verde. ¿Qué debe hacer?","o":["Seguir, porque su semáforo está en verde","Detenerse y dejar que la persona cruce","Tocar la bocina y rodear a la persona","Seguir si la persona todavía no está en su carril"],"h1":"Aquí no importa el semáforo.","h2":"En Hawái debe detenerse ante una persona ciega en la calle, que se reconoce por un bastón blanco o un perro guía, sin importar lo que muestre el semáforo.","p":"Correcto. Siempre deténgase ante una persona con bastón blanco o perro guía."},"ref":{"doc":"HI","page":95}},{"id":"hi-074","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, at what loaded weight must a trailer have its own brakes?","o":["500 pounds or more","1,000 pounds or more","10,000 pounds or more","3,000 pounds or more"],"h1":"Brakes are also needed if it weighs more than half of the towing vehicle.","h2":"In Hawaii a loaded trailer that weighs 3,000 pounds or more, or more than half the towing vehicle's weight, must have brakes and breakaway protection.","p":"Right. At 3,000 pounds or more, the trailer needs brakes."},"es":{"q":"En Hawái, ¿a partir de qué peso con carga debe tener frenos propios un remolque?","o":["500 libras o más","1,000 libras o más","10,000 libras o más","3,000 libras o más"],"h1":"También necesita frenos si pesa más de la mitad del vehículo que lo jala.","h2":"En Hawái un remolque cargado que pesa 3,000 libras o más, o más de la mitad del peso del vehículo que lo jala, debe tener frenos y protección contra desenganche.","p":"Correcto. Con 3,000 libras o más, el remolque necesita frenos."},"ref":{"doc":"HI","page":87}},{"id":"hi-075","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what must a bicycle have when it is ridden at night?","o":["A headlight and a rear reflector","Only a bell","A horn and a flag","Nothing, if the rider wears white"],"h1":"One helps the rider see ahead; the other helps drivers behind see the bike.","h2":"In Hawaii a bicycle ridden at night must have a headlight and a rear reflector.","p":"Right. At night a bike needs a headlight and a rear reflector."},"es":{"q":"En Hawái, ¿qué debe tener una bicicleta cuando se usa de noche?","o":["Una luz delantera y un reflector trasero","Solo un timbre","Una bocina y una bandera","Nada, si el ciclista se viste de blanco"],"h1":"Una ayuda al ciclista a ver adelante; el otro ayuda a los conductores de atrás a ver la bicicleta.","h2":"En Hawái una bicicleta que se usa de noche debe tener una luz delantera y un reflector trasero.","p":"Correcto. De noche una bicicleta necesita luz delantera y reflector trasero."},"ref":{"doc":"HI","page":98}},{"id":"hi-076","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a 40-year-old gets a new driver's license. About how long is it good for?","o":["About one year","About four years","About eight years","For life"],"h1":"It is the longest period Hawaii gives.","h2":"In Hawaii a license issued to a driver aged 25 to 71 expires on the first birthday at least eight years after it is issued.","p":"Right. For most adults the license lasts about eight years."},"es":{"q":"En Hawái, una persona de 40 años recibe una licencia de manejar nueva. ¿Por cuánto tiempo vale, más o menos?","o":["Un año","Unos cuatro años","Unos ocho años","De por vida"],"h1":"Es el plazo más largo que da Hawái.","h2":"En Hawái una licencia para un conductor de 25 a 71 años vence en el primer cumpleaños que llega al menos ocho años después de su emisión.","p":"Correcto. Para la mayoría de los adultos la licencia dura unos ocho años."},"ref":{"doc":"HI","page":null}},{"id":"hi-077","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, a driver who is 80 or older renews a license. About how long is the new license good for?","o":["About six months","About two years","About eight years","About ten years"],"h1":"It is the shortest period in the law.","h2":"In Hawaii a license issued to a driver aged 80 or older expires on the first birthday at least two years after it is issued.","p":"Right. At 80 and older, the license lasts about two years."},"es":{"q":"En Hawái, un conductor de 80 años o más renueva su licencia. ¿Por cuánto tiempo vale la nueva licencia, más o menos?","o":["Unos seis meses","Unos dos años","Unos ocho años","Unos diez años"],"h1":"Es el plazo más corto de la ley.","h2":"En Hawái una licencia para un conductor de 80 años o más vence en el primer cumpleaños que llega al menos dos años después de su emisión.","p":"Correcto. A los 80 años o más, la licencia dura unos dos años."},"ref":{"doc":"HI","page":null}},{"id":"hi-078","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how long is a regular instruction permit good for?","o":["30 days","Six months","Five years","One year"],"h1":"It is the same length of time as a car registration lasts.","h2":"In Hawaii a regular instruction permit lets you drive with a supervisor for one year.","p":"Right. The instruction permit is good for one year."},"es":{"q":"En Hawái, ¿por cuánto tiempo vale un permiso de aprendizaje normal?","o":["30 días","Seis meses","Cinco años","Un año"],"h1":"Es el mismo tiempo que dura el registro de un auto.","h2":"En Hawái un permiso de aprendizaje normal le permite manejar con un supervisor durante un año.","p":"Correcto. El permiso de aprendizaje vale por un año."},"ref":{"doc":"HI","page":null}},{"id":"hi-079","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, what must you complete before you can get a motorcycle instruction permit?","o":["A basic motorcycle rider course approved by the state","A road test on a motorcycle you borrow","A full year of driving a car first","A motorcycle repair class at a shop"],"h1":"It is a training course for new riders.","h2":"In Hawaii you must complete a state-approved basic motorcycle rider course before you can get a motorcycle instruction permit.","p":"Right. The basic rider course comes before the motorcycle permit."},"es":{"q":"En Hawái, ¿qué debe completar antes de obtener un permiso de aprendizaje para motocicleta?","o":["Un curso básico de motociclismo aprobado por el estado","Un examen de manejo en una motocicleta prestada","Un año completo manejando auto primero","Una clase de reparación de motocicletas en un taller"],"h1":"Es un curso de entrenamiento para motociclistas nuevos.","h2":"En Hawái debe completar un curso básico de motociclismo aprobado por el estado antes de obtener un permiso de aprendizaje para motocicleta.","p":"Correcto. El curso básico va antes del permiso de motocicleta."},"ref":{"doc":"HI","page":null}},{"id":"hi-080","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, what is NOT allowed for a rider with a temporary motorcycle instruction permit?","o":["Riding on a quiet city street","Riding alone in the daytime","Riding after dark or carrying a passenger","Riding a small motor scooter"],"h1":"Think of the two riskiest things for a new rider.","h2":"In Hawaii a rider with a temporary motorcycle instruction permit may not ride during darkness or carry any passengers.","p":"Right. No riding after dark and no passengers on a permit."},"es":{"q":"En Hawái, ¿qué NO se permite a un motociclista con permiso temporal de aprendizaje?","o":["Manejar en una calle tranquila de la ciudad","Manejar solo durante el día","Manejar de noche o llevar un pasajero","Manejar una motoneta pequeña"],"h1":"Piense en las dos cosas más peligrosas para un motociclista nuevo.","h2":"En Hawái un motociclista con permiso temporal de aprendizaje no puede manejar en la oscuridad ni llevar pasajeros.","p":"Correcto. Con permiso, nada de manejar de noche ni de llevar pasajeros."},"ref":{"doc":"HI","page":null}},{"id":"hi-081","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, who must wear a helmet when riding a motorcycle or motor scooter?","o":["Only riders over 65","Only riders on freeways","Only passengers, not the rider","Riders and passengers under 18"],"h1":"The rule is based on age.","h2":"In Hawaii anyone under 18 who rides or is a passenger on a motorcycle or motor scooter must wear a helmet with the chin strap fastened.","p":"Right. Under 18, a helmet is required."},"es":{"q":"En Hawái, ¿quién debe usar casco al manejar o viajar en motocicleta o motoneta?","o":["Solo los conductores mayores de 65 años","Solo los conductores en autopistas","Solo los pasajeros, no el conductor","Conductores y pasajeros menores de 18 años"],"h1":"La regla depende de la edad.","h2":"En Hawái toda persona menor de 18 años que maneja o viaja como pasajero en motocicleta o motoneta debe usar casco con la correa abrochada.","p":"Correcto. Menores de 18 años deben usar casco."},"ref":{"doc":"HI","page":null}},{"id":"hi-082","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, a provisional licensee breaks the passenger or late-night rule for the first time. What happens to the license?","o":["Nothing; it is only a warning","It is suspended for three months","It is suspended for one week","It is revoked for five years"],"h1":"It is a season of the year.","h2":"In Hawaii a first violation of the provisional license rules leads to a three-month suspension.","p":"Right. A first violation means a three-month suspension."},"es":{"q":"En Hawái, alguien con licencia provisional rompe por primera vez la regla de pasajeros o de la noche. ¿Qué pasa con la licencia?","o":["Nada; es solo una advertencia","Se suspende por tres meses","Se suspende por una semana","Se revoca por cinco años"],"h1":"Es una estación del año.","h2":"En Hawái una primera violación de las reglas de la licencia provisional lleva a una suspensión de tres meses.","p":"Correcto. Una primera violación significa una suspensión de tres meses."},"ref":{"doc":"HI","page":null}},{"id":"hi-083","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, what is the fine for not wearing a seat belt, before extra surcharges?","o":["$45","$5","$500","$1,000"],"h1":"It is less than $50.","h2":"In Hawaii the fine for not wearing a seat belt is $45 for each violation, plus surcharges.","p":"Right. The seat belt fine is $45, plus surcharges."},"es":{"q":"En Hawái, ¿cuál es la multa por no usar el cinturón de seguridad, sin contar los recargos?","o":["$45","$5","$500","$1,000"],"h1":"Es menos de $50.","h2":"En Hawái la multa por no usar el cinturón de seguridad es de $45 por cada infracción, más recargos.","p":"Correcto. La multa es de $45, más recargos."},"ref":{"doc":"HI","page":null}},{"id":"hi-084","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, a child under what age must ride in a rear-facing car seat?","o":["Under 6 months","Under 4","Under 2","Under 8"],"h1":"Think of a toddler's second birthday.","h2":"In Hawaii a child under 2 years old must ride in a rear-facing car seat with a harness.","p":"Right. Children under 2 ride rear-facing."},"es":{"q":"En Hawái, ¿un niño menor de qué edad debe viajar en un asiento de seguridad mirando hacia atrás?","o":["Menor de 6 meses","Menor de 4 años","Menor de 2 años","Menor de 8 años"],"h1":"Piense en el segundo cumpleaños de un niño pequeño.","h2":"En Hawái un niño menor de 2 años debe viajar en un asiento de seguridad con arnés mirando hacia atrás.","p":"Correcto. Los menores de 2 años viajan mirando hacia atrás."},"ref":{"doc":"HI","page":null}},{"id":"hi-085","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, you drive an 8-year-old who is 4 feet 6 inches tall. How must the child ride?","o":["With only the regular seat belt","With no belt, if in the back seat","On an adult's lap","In a booster seat or a car seat with a harness"],"h1":"The child is not yet taller than 4 feet 9 inches.","h2":"In Hawaii a child from 4 to 9 years old must use a booster seat or a harness seat; only a child 7 or older who is over 4 feet 9 inches may use just the lap and shoulder belt.","p":"Right. This child still needs a booster or harness seat."},"es":{"q":"En Hawái, usted lleva a un niño de 8 años que mide 4 pies 6 pulgadas. ¿Cómo debe viajar el niño?","o":["Solo con el cinturón de seguridad normal","Sin cinturón, si va en el asiento de atrás","En las piernas de un adulto","En un asiento elevado (booster) o un asiento con arnés"],"h1":"El niño todavía no mide más de 4 pies 9 pulgadas.","h2":"En Hawái un niño de 4 a 9 años debe usar un asiento elevado o un asiento con arnés; solo un niño de 7 años o más que mide más de 4 pies 9 pulgadas puede usar solo el cinturón de cadera y hombro.","p":"Correcto. Este niño todavía necesita un asiento elevado o con arnés."},"ref":{"doc":"HI","page":null}},{"id":"hi-086","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, with window tint, at least how much light must the front side windows let through?","o":["About 5 percent","About 35 percent","About 15 percent","About 90 percent"],"h1":"It is about one third.","h2":"In Hawaii tinted front side windows must let through at least 35 percent of light, plus or minus 6 percent.","p":"Right. Front side windows must let in about 35 percent of light."},"es":{"q":"En Hawái, con vidrios polarizados, ¿cuánta luz deben dejar pasar como mínimo las ventanas laterales delanteras?","o":["Alrededor del 5 por ciento","Alrededor del 35 por ciento","Alrededor del 15 por ciento","Alrededor del 90 por ciento"],"h1":"Es más o menos un tercio.","h2":"En Hawái las ventanas laterales delanteras polarizadas deben dejar pasar al menos el 35 por ciento de la luz, con un margen de 6 por ciento.","p":"Correcto. Las ventanas laterales delanteras deben dejar pasar alrededor del 35 por ciento de la luz."},"ref":{"doc":"HI","page":null}},{"id":"hi-087","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, apart from emergencies and approved parades, who may never ride in the open bed of a pickup truck?","o":["Children 12 years old or younger","Adults over 65","Anyone sitting on the floor","Workers going to a job site"],"h1":"It protects young children.","h2":"In Hawaii no passenger 12 years old or younger may ride in a pickup truck bed, except in an emergency or an approved parade or exhibition.","p":"Right. Children 12 and under may not ride in a pickup bed."},"es":{"q":"En Hawái, fuera de emergencias y desfiles autorizados, ¿quién nunca puede viajar en la caja abierta de una camioneta pickup?","o":["Los niños de 12 años o menos","Los adultos mayores de 65 años","Cualquier persona sentada en el piso","Los trabajadores que van a una obra"],"h1":"Protege a los niños pequeños.","h2":"En Hawái ningún pasajero de 12 años o menos puede viajar en la caja de una pickup, salvo en una emergencia o un desfile o exhibición autorizados.","p":"Correcto. Los niños de 12 años o menos no pueden viajar en la caja de una pickup."},"ref":{"doc":"HI","page":null}},{"id":"hi-088","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, at what speed is it the crime of excessive speeding, no matter what the posted limit is?","o":["60 mph or more","70 mph or more","80 mph or more","100 mph or more"],"h1":"It is also excessive speeding to go 30 mph or more over the limit.","h2":"In Hawaii driving 80 mph or more is excessive speeding no matter what the posted limit is, and so is going 30 mph or more over the limit.","p":"Right. 80 mph or more is always excessive speeding."},"es":{"q":"En Hawái, ¿a qué velocidad se comete el delito de exceso de velocidad grave, sin importar el límite indicado?","o":["60 mph o más","70 mph o más","80 mph o más","100 mph o más"],"h1":"También es exceso grave ir 30 mph o más por encima del límite.","h2":"En Hawái manejar a 80 mph o más es exceso de velocidad grave sin importar el límite indicado, y también lo es ir 30 mph o más por encima del límite.","p":"Correcto. 80 mph o más siempre es exceso de velocidad grave."},"ref":{"doc":"HI","page":null}},{"id":"hi-089","scope":"HI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Hawaii, what is the fine for speeding in a school zone or construction area?","o":["$25","$75","$2,500","$250"],"h1":"It is a few hundred dollars, plus surcharges.","h2":"In Hawaii speeding in a school zone or construction area brings a $250 fine, plus surcharges.","p":"Right. The fine is $250, plus surcharges."},"es":{"q":"En Hawái, ¿cuál es la multa por exceso de velocidad en una zona escolar o de construcción?","o":["$25","$75","$2,500","$250"],"h1":"Son unos cientos de dólares, más recargos.","h2":"En Hawái el exceso de velocidad en una zona escolar o de construcción tiene una multa de $250, más recargos.","p":"Correcto. La multa es de $250, más recargos."},"ref":{"doc":"HI","page":null}},{"id":"hi-090","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, what is the fine the first time a driver fails to stop for a pedestrian in a crosswalk?","o":["$15","$150","$50","$1,500"],"h1":"It doubles for a second time within a year.","h2":"In Hawaii the fine for a first failure to stop for a pedestrian in a crosswalk is $150.","p":"Right. A first crosswalk violation costs $150."},"es":{"q":"En Hawái, ¿cuál es la multa la primera vez que un conductor no se detiene ante un peatón en un cruce peatonal?","o":["$15","$150","$50","$1,500"],"h1":"Se duplica si pasa otra vez dentro de un año.","h2":"En Hawái la multa por no detenerse ante un peatón en un cruce peatonal la primera vez es de $150.","p":"Correcto. Una primera infracción en el cruce peatonal cuesta $150."},"ref":{"doc":"HI","page":null}},{"id":"hi-091","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, a driver with no alcohol or drug offense in the past 10 years refuses an alcohol test. How long is the license revoked?","o":["Two years","Three months","Six months","One year"],"h1":"It is twice as long as for failing the test the first time.","h2":"In Hawaii a driver with no prior alcohol or drug enforcement contact in 10 years who refuses testing has the license revoked for two years.","p":"Right. Refusing the test means a two-year revocation."},"es":{"q":"En Hawái, un conductor sin infracciones de alcohol o drogas en los últimos 10 años se niega a hacerse la prueba de alcohol. ¿Por cuánto tiempo se le revoca la licencia?","o":["Dos años","Tres meses","Seis meses","Un año"],"h1":"Es el doble que por no pasar la prueba la primera vez.","h2":"En Hawái a un conductor sin antecedentes de alcohol o drogas en 10 años que se niega a la prueba se le revoca la licencia por dos años.","p":"Correcto. Negarse a la prueba significa una revocación de dos años."},"ref":{"doc":"HI","page":null}},{"id":"hi-092","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, you move here with a valid driver's license from another state. Which tests may be waived?","o":["The vision test only","No tests; you must take all of them","The knowledge test and the road test","The vision test and the road test"],"h1":"You must still show that you can see well enough to drive.","h2":"In Hawaii, the knowledge and road tests may be waived for an applicant who has a valid license from another state.","p":"Right. The knowledge and road tests may be waived."},"es":{"q":"En Hawái, usted se muda aquí con una licencia de manejo válida de otro estado. ¿Qué exámenes se le pueden dispensar?","o":["Solo el examen de la vista","Ninguno; debe tomar todos","El examen de conocimientos y el examen práctico de manejo","El examen de la vista y el examen práctico"],"h1":"Aún debe demostrar que ve lo suficiente para manejar.","h2":"En Hawái, se pueden dispensar el examen de conocimientos y el examen práctico a quien tiene una licencia válida de otro estado.","p":"Correcto. Se pueden dispensar el examen de conocimientos y el práctico."},"ref":{"doc":"HI","page":12}},{"id":"hi-093","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, a REAL ID license can be renewed by mail. At least how often must you renew in person so a new photo can be taken?","o":["Every 16 years","Every 2 years","Every 4 years","Every 30 years"],"h1":"It is the length of two eight-year licenses.","h2":"In Hawaii, a REAL ID license may be renewed by mail, but you must appear in person at least every 16 years for a new photo.","p":"Right. You must come in person at least every 16 years."},"es":{"q":"En Hawái, una licencia REAL ID se puede renovar por correo. ¿Cada cuánto tiempo, como mínimo, debe renovarla en persona para tomarle una foto nueva?","o":["Cada 16 años","Cada 2 años","Cada 4 años","Cada 30 años"],"h1":"Es la duración de dos licencias de ocho años.","h2":"En Hawái, una licencia REAL ID se puede renovar por correo, pero usted debe presentarse en persona por lo menos cada 16 años para una foto nueva.","p":"Correcto. Debe ir en persona por lo menos cada 16 años."},"ref":{"doc":"HI","page":11}},{"id":"hi-094","scope":"HI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Hawaii, how must you get to the testing station for your road test?","o":["Alone, driving on your instruction permit","By taxi; the examiner brings the car","With any passenger 16 or older","With a licensed driver who comes with you"],"h1":"You may not drive there alone on a permit.","h2":"In Hawaii, a licensed driver must come with you to the testing station for the road test.","p":"Right. A licensed driver must come with you."},"es":{"q":"En Hawái, ¿cómo debe llegar al lugar del examen práctico de manejo?","o":["Solo, manejando con su permiso de aprendizaje","En taxi; el examinador trae el auto","Con cualquier pasajero de 16 años o más","Con un conductor con licencia que lo acompañe"],"h1":"No puede manejar solo hasta allí con un permiso.","h2":"En Hawái, un conductor con licencia debe acompañarlo al lugar del examen práctico de manejo.","p":"Correcto. Un conductor con licencia debe acompañarlo."},"ref":{"doc":"HI","page":15}},{"id":"hi-095","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what must the car you bring for your road test have?","o":["A dealer plate and a full tank of gas","Current registration, safety inspection and insurance card","A second brake pedal for the examiner","A sign on the back that says STUDENT DRIVER"],"h1":"Think of the papers that show the car is legal and safe.","h2":"In Hawaii, the car for the road test must have a current registration, a current safety inspection certificate and an insurance identification card.","p":"Right. It needs registration, inspection and an insurance card."},"es":{"q":"En Hawái, ¿qué debe tener el auto que usted lleva al examen práctico de manejo?","o":["Placa de concesionario y el tanque lleno","Registro vigente, inspección de seguridad y tarjeta de seguro","Un segundo pedal de freno para el examinador","Un letrero atrás que diga STUDENT DRIVER"],"h1":"Piense en los papeles que muestran que el auto es legal y seguro.","h2":"En Hawái, el auto para el examen práctico debe tener registro vigente, certificado de inspección de seguridad vigente y tarjeta de identificación del seguro.","p":"Correcto. Necesita registro, inspección y tarjeta de seguro."},"ref":{"doc":"HI","page":15}},{"id":"hi-096","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, you get a citation for a traffic crime, not a traffic infraction. What is true?","o":["You must appear in court","You may simply pay it by mail","You may send a written statement instead","It is handled only by your insurer"],"h1":"Traffic crimes can lead to jail.","h2":"In Hawaii, a traffic crime citation requires a court appearance, because it can lead to jail.","p":"Right. A traffic crime means you must go to court."},"es":{"q":"En Hawái, usted recibe una citación por un delito de tránsito, no por una infracción de tránsito. ¿Qué es cierto?","o":["Debe presentarse ante el tribunal","Puede simplemente pagarla por correo","Puede enviar una declaración escrita en su lugar","Solo la resuelve su compañía de seguros"],"h1":"Los delitos de tránsito pueden llevar a la cárcel.","h2":"En Hawái, una citación por delito de tránsito exige presentarse ante el tribunal, porque puede llevar a la cárcel.","p":"Correcto. Un delito de tránsito significa que debe ir al tribunal."},"ref":{"doc":"HI","page":17}},{"id":"hi-097","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, which light is NOT allowed on a private car where people outside can see it?","o":["White headlights","Amber turn signals","A blue light","Red taillights"],"h1":"This color is kept for police and other emergency vehicles.","h2":"In Hawaii, a blue light visible outside the vehicle is not allowed, except on authorized emergency vehicles.","p":"Right. Blue lights are only for authorized emergency vehicles."},"es":{"q":"En Hawái, ¿qué luz NO se permite en un auto particular si la gente de afuera puede verla?","o":["Faros delanteros blancos","Luces direccionales ámbar","Una luz azul","Luces traseras rojas"],"h1":"Este color está reservado para la policía y otros vehículos de emergencia.","h2":"En Hawái, no se permite una luz azul visible desde afuera del vehículo, salvo en vehículos de emergencia autorizados.","p":"Correcto. Las luces azules son solo para vehículos de emergencia autorizados."},"ref":{"doc":"HI","page":18}},{"id":"hi-098","scope":"HI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Hawaii, on a narrow road, how much of the main traveled road must you leave for a car coming the other way?","o":["At least one quarter","At least half","Only room for its mirrors","The whole road; you must stop"],"h1":"Share the road fairly.","h2":"In Hawaii, on a narrow road you must leave at least half of the main traveled part of the road to vehicles coming from the opposite direction.","p":"Right. Leave at least half of the road."},"es":{"q":"En Hawái, en un camino angosto, ¿cuánto de la parte principal del camino debe dejar a un auto que viene en sentido contrario?","o":["Al menos una cuarta parte","Al menos la mitad","Solo espacio para sus espejos","Todo el camino; usted debe detenerse"],"h1":"Comparta el camino de forma justa.","h2":"En Hawái, en un camino angosto usted debe dejar al menos la mitad de la parte principal del camino a los vehículos que vienen en sentido contrario.","p":"Correcto. Deje al menos la mitad del camino."},"ref":{"doc":"HI","page":26}},{"id":"hi-099","scope":"HI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Hawaii, when you park, at least how much of the street's width must stay open for traffic?","o":["3 feet","5 feet","20 feet","10 feet"],"h1":"It is about the width of one traffic lane.","h2":"In Hawaii, you may not park anywhere that leaves less than 10 feet of the street's width free for traffic.","p":"Right. At least 10 feet must stay open for traffic."},"es":{"q":"En Hawái, cuando usted se estaciona, ¿cuánto del ancho de la calle debe quedar libre para el tránsito, como mínimo?","o":["3 pies (1 metro)","5 pies (1.5 metros)","20 pies (6 metros)","10 pies (3 metros)"],"h1":"Es más o menos el ancho de un carril.","h2":"En Hawái, no puede estacionarse en ningún lugar donde queden libres menos de 10 pies (3 metros) del ancho de la calle para el tránsito.","p":"Correcto. Deben quedar libres al menos 10 pies para el tránsito."},"ref":{"doc":"HI","page":28}},{"id":"hi-100","scope":"HI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Hawaii, which of these is NOT allowed on a public road?","o":["Parking your car there to show it for sale","Parking 6 inches from the curb","Parking in a marked space for one hour","Parking with your wheels turned to the curb"],"h1":"The road is not a used-car lot or a car wash.","h2":"In Hawaii, you may not use a public road to display a vehicle for sale, to wash it, or to repair it except in an emergency.","p":"Right. You may not display a car for sale on a public road."},"es":{"q":"En Hawái, ¿cuál de estas cosas NO se permite en una vía pública?","o":["Estacionar su auto allí para exhibirlo en venta","Estacionar a 6 pulgadas de la acera","Estacionar una hora en un espacio marcado","Estacionar con las ruedas giradas hacia la acera"],"h1":"La calle no es un lote de autos usados ni un lavado de autos.","h2":"En Hawái, no puede usar una vía pública para exhibir un vehículo en venta, lavarlo ni repararlo, salvo en una emergencia.","p":"Correcto. No puede exhibir un auto en venta en la vía pública."},"ref":{"doc":"HI","page":28}},{"id":"hi-101","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, a vehicle has a reflective orange triangle emblem on the back. What does it tell you?","o":["It is carrying explosives","It is a school bus","It is built to go 25 mph or less","It is a police vehicle"],"h1":"Reduce speed and approach with care.","h2":"In Hawaii, the slow-moving vehicle triangle is shown on vehicles built to travel 25 mph or less, so you should slow down and approach carefully.","p":"Right. It marks a vehicle built for 25 mph or less."},"es":{"q":"En Hawái, un vehículo lleva atrás un emblema triangular anaranjado y reflectante. ¿Qué le indica?","o":["Lleva explosivos","Es un autobús escolar","Está hecho para ir a 25 mph o menos","Es un vehículo de la policía"],"h1":"Baje la velocidad y acérquese con cuidado.","h2":"En Hawái, el triángulo de vehículo lento lo llevan los vehículos hechos para ir a 25 mph o menos, así que usted debe bajar la velocidad y acercarse con cuidado.","p":"Correcto. Marca un vehículo hecho para 25 mph o menos."},"ref":{"doc":"HI","page":30}},{"id":"hi-102","scope":"HI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Hawaii, when you are parallel parked, how close may your bumpers be to the cars in front and behind, unless the street is marked?","o":["No closer than 6 inches","No closer than 2 feet","Touching is fine if you are gentle","No closer than 10 feet"],"h1":"Leave room so the other drivers can get out.","h2":"In Hawaii, when parallel parked, your front and rear bumpers should be no closer than two feet to other vehicles unless the street is marked otherwise.","p":"Right. Keep at least 2 feet from the other cars."},"es":{"q":"En Hawái, cuando estaciona en paralelo, ¿qué tan cerca pueden estar sus parachoques de los autos de adelante y de atrás, si la calle no está marcada?","o":["No a menos de 6 pulgadas (15 cm)","No a menos de 2 pies (60 cm)","Pueden tocarse si lo hace con cuidado","No a menos de 10 pies (3 metros)"],"h1":"Deje espacio para que los otros conductores puedan salir.","h2":"En Hawái, al estacionar en paralelo, sus parachoques no deben quedar a menos de dos pies de otros vehículos, salvo que la calle esté marcada de otra forma.","p":"Correcto. Deje al menos 2 pies con los otros autos."},"ref":{"doc":"HI","page":72}},{"id":"hi-103","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, where must a trailer's safety chains be attached?","o":["To the hitch ball on the towing vehicle","To the rear bumper of the towing vehicle","To the trailer's tongue jack and its wheels","To the frames of the towing vehicle and the trailer"],"h1":"If the hitch breaks, the chains must still hold.","h2":"In Hawaii, trailer safety chains must be attached to the frame of the towing vehicle and of the trailer, not to a part of the hitch.","p":"Right. The chains go to the frames, not the hitch."},"es":{"q":"En Hawái, ¿dónde deben engancharse las cadenas de seguridad de un remolque?","o":["A la bola del enganche del vehículo que remolca","Al parachoques trasero del vehículo que remolca","Al gato de la lanza y a las ruedas del remolque","Al chasis del vehículo que remolca y al del remolque"],"h1":"Si el enganche se rompe, las cadenas deben seguir sujetando.","h2":"En Hawái, las cadenas de seguridad del remolque deben engancharse al chasis del vehículo que remolca y al del remolque, no a una parte del enganche.","p":"Correcto. Las cadenas van al chasis, no al enganche."},"ref":{"doc":"HI","page":87}},{"id":"hi-104","scope":"HI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Hawaii, how must bicycle riders ride on the roadway itself?","o":["Single file, one behind the other","Two side by side at all times","Three abreast if traffic is light","In the middle of the lane, in a group"],"h1":"Riding side by side is only for a bike lane or path wide enough not to slow traffic.","h2":"In Hawaii, bicyclists must ride single file on the roadway; they may ride two abreast only on a bike lane or path wide enough not to block traffic.","p":"Right. On the roadway, bicyclists ride single file."},"es":{"q":"En Hawái, ¿cómo deben circular los ciclistas en la calzada?","o":["En fila, uno detrás del otro","Dos lado a lado en todo momento","Tres lado a lado si hay poco tránsito","En el centro del carril, en grupo"],"h1":"Ir lado a lado es solo para un carril o sendero para bicicletas lo bastante ancho para no frenar el tránsito.","h2":"En Hawái, los ciclistas deben ir en fila en la calzada; pueden ir de dos en dos solo en un carril o sendero para bicicletas lo bastante ancho para no bloquear el tránsito.","p":"Correcto. En la calzada, los ciclistas van en fila."},"ref":{"doc":"HI","page":98}},{"id":"hi-105","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a police officer asks for your insurance card. May you show it on your phone?","o":["No, only a paper card is accepted","Only if you also give the officer your phone","Yes, an electronic insurance card on a phone is allowed","Only if the officer calls your insurer first"],"h1":"The officer may look only at the card on the screen.","h2":"In Hawaii, you may show your electronic insurance identification card on a mobile device, and the officer may view only that card.","p":"Right. You may show the insurance card on your phone."},"es":{"q":"En Hawái, un policía le pide su tarjeta de seguro. ¿Puede mostrarla en su teléfono?","o":["No, solo se acepta la tarjeta de papel","Solo si además le entrega el teléfono al policía","Sí, se permite la tarjeta de seguro electrónica en el teléfono","Solo si el policía llama primero a su aseguradora"],"h1":"El policía solo puede ver la tarjeta en la pantalla.","h2":"En Hawái, usted puede mostrar su tarjeta electrónica de identificación del seguro en un dispositivo móvil, y el policía solo puede ver esa tarjeta.","p":"Correcto. Puede mostrar la tarjeta de seguro en su teléfono."},"ref":{"doc":"HI","page":null}},{"id":"hi-106","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, when may an adult ride in the open bed of a pickup truck?","o":["Any time the truck goes slower than 35 miles per hour","Only if they stand up and hold on to the side rails","Only on country roads outside of towns and cities","Only if the cab is full, the tailgate is shut and they sit on the floor"],"h1":"Standing in the bed is never allowed.","h2":"In Hawaii, an adult may ride in a pickup bed only when no seat is free in the cab, the side racks and tailgate are secured, and the passenger sits on the floor.","p":"Right. The cab must be full, the tailgate closed, and the rider seated on the floor."},"es":{"q":"En Hawái, ¿cuándo puede un adulto ir en la caja abierta de una camioneta pickup?","o":["Siempre que la camioneta vaya a menos de 35 millas por hora","Solo si va de pie y bien agarrado de las barandas","Solo en caminos rurales fuera de pueblos y ciudades","Solo si la cabina está llena, la compuerta cerrada y va sentado en el piso"],"h1":"Ir de pie en la caja nunca está permitido.","h2":"En Hawái, un adulto puede ir en la caja de una pickup solo si no hay asiento libre en la cabina, las barandas y la compuerta están aseguradas y el pasajero va sentado en el piso.","p":"Correcto. La cabina debe estar llena, la compuerta cerrada y el pasajero sentado en el piso."},"ref":{"doc":"HI","page":null}},{"id":"hi-107","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, a driver leaves the scene of a crash in which a person was seriously hurt. What kind of offense is this?","o":["A parking violation","A felony, and the license is revoked","A small traffic fine only","No offense if the driver has insurance"],"h1":"It is one of the most serious traffic crimes.","h2":"In Hawaii, leaving the scene of a crash that caused serious injury or death is a class B felony, and the driver's license is revoked.","p":"Right. It is a felony, and the license is revoked."},"es":{"q":"En Hawái, un conductor se va del lugar de un choque en el que una persona resultó gravemente herida. ¿Qué tipo de delito es?","o":["Una infracción de estacionamiento","Un delito grave (felonía), y se revoca la licencia","Solo una multa de tránsito pequeña","Ningún delito si el conductor tiene seguro"],"h1":"Es uno de los delitos de tránsito más graves.","h2":"En Hawái, irse del lugar de un choque que causó heridas graves o la muerte es un delito grave de clase B, y se revoca la licencia del conductor.","p":"Correcto. Es un delito grave y se revoca la licencia."},"ref":{"doc":"HI","page":null}},{"id":"hi-108","scope":"HI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Hawaii, what is the fine for a pedestrian who breaks the law on crossing outside a crosswalk?","o":["$10","$25","$100","$1,000"],"h1":"It is the same amount for every such violation.","h2":"In Hawaii, a pedestrian who breaks the rules for crossing outside a crosswalk is fined $100.","p":"Right. The fine is $100."},"es":{"q":"En Hawái, ¿cuál es la multa para un peatón que viola la ley al cruzar fuera de un cruce peatonal?","o":["$10","$25","$100","$1,000"],"h1":"Es la misma cantidad para cada infracción de este tipo.","h2":"En Hawái, al peatón que viola las reglas para cruzar fuera de un cruce peatonal se le multa con $100.","p":"Correcto. La multa es de $100."},"ref":{"doc":"HI","page":null}},{"id":"hi-109","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, you are hauling loose trash and empty boxes in the back of a pickup. What must you do?","o":["Cover the whole load with a net, tarp or similar cover","Drive with your hazard lights on","Stay below 25 mph","Nothing, if the load is below the sides"],"h1":"Loose paper, rubbish, dirt, sand and gravel can blow out.","h2":"In Hawaii, a load that includes loose paper, rubbish, plastics, empty cartons, dirt, sand or gravel must be completely covered by a cargo net, tarp or similar cover.","p":"Right. The load must be fully covered."},"es":{"q":"En Hawái, usted lleva basura suelta y cajas vacías en la caja de una pickup. ¿Qué debe hacer?","o":["Cubrir toda la carga con una red, una lona o algo similar","Manejar con las luces de emergencia encendidas","Ir a menos de 25 mph","Nada, si la carga no pasa de los lados"],"h1":"El papel suelto, la basura, la tierra, la arena y la grava se pueden volar.","h2":"En Hawái, una carga con papel suelto, basura, plásticos, cajas vacías, tierra, arena o grava debe ir totalmente cubierta con una red, una lona o algo similar.","p":"Correcto. La carga debe ir totalmente cubierta."},"ref":{"doc":"HI","page":null}},{"id":"hi-110","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, a driver is convicted of drunk driving for the first time. What must be put on every vehicle the person drives during the revocation?","o":["A speed limiter set to 45 mph","A red STUDENT DRIVER sign","A GPS tracker for the police","An ignition interlock device"],"h1":"The driver must blow into it before the car will start.","h2":"In Hawaii, after a first conviction for driving under the influence, an ignition interlock device must be installed on all vehicles the person drives during the revocation period.","p":"Right. An ignition interlock device is required."},"es":{"q":"En Hawái, una persona es condenada por primera vez por manejar bajo los efectos del alcohol. ¿Qué se debe instalar en todo vehículo que maneje durante la revocación?","o":["Un limitador de velocidad a 45 mph","Un letrero rojo de STUDENT DRIVER","Un rastreador GPS para la policía","Un dispositivo de bloqueo de encendido (interlock)"],"h1":"El conductor debe soplar en él antes de que el auto arranque.","h2":"En Hawái, después de una primera condena por manejar bajo influencia, se debe instalar un dispositivo de bloqueo de encendido en todos los vehículos que la persona maneje durante la revocación.","p":"Correcto. Se exige un dispositivo de bloqueo de encendido."},"ref":{"doc":"HI","page":null}},{"id":"hi-111","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, an adult is convicted of drunk driving with a passenger under 15 in the car. What is added to the sentence?","o":["A warning letter only","A $500 fine and 48 hours in jail","A $50 fine","Nothing extra"],"h1":"The law adds both money and jail time.","h2":"In Hawaii, an adult convicted of drunk driving with a passenger younger than 15 gets an extra mandatory $500 fine and 48 hours of jail.","p":"Right. It adds a $500 fine and 48 hours in jail."},"es":{"q":"En Hawái, un adulto es condenado por manejar ebrio con un pasajero menor de 15 años en el auto. ¿Qué se agrega a la condena?","o":["Solo una carta de advertencia","Una multa de $500 y 48 horas de cárcel","Una multa de $50","Nada adicional"],"h1":"La ley agrega tanto dinero como tiempo en la cárcel.","h2":"En Hawái, un adulto condenado por manejar ebrio con un pasajero menor de 15 años recibe además una multa obligatoria de $500 y 48 horas de cárcel.","p":"Correcto. Se agregan una multa de $500 y 48 horas de cárcel."},"ref":{"doc":"HI","page":null}},{"id":"hi-112","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, at what blood alcohol level is a driver considered a highly intoxicated driver?","o":["0.02 or more","0.05 or more","0.15 or more","0.30 or more"],"h1":"It is almost twice the regular legal limit.","h2":"In Hawaii, a blood or breath alcohol level of 0.15 or more makes a driver a highly intoxicated driver, which brings tougher penalties.","p":"Right. 0.15 or more means highly intoxicated."},"es":{"q":"En Hawái, ¿a partir de qué nivel de alcohol en la sangre se considera a un conductor altamente intoxicado?","o":["0.02 o más","0.05 o más","0.15 o más","0.30 o más"],"h1":"Es casi el doble del límite legal normal.","h2":"En Hawái, un nivel de alcohol en la sangre o el aliento de 0.15 o más hace que un conductor se considere altamente intoxicado, con castigos más duros.","p":"Correcto. 0.15 o más significa altamente intoxicado."},"ref":{"doc":"HI","page":null}},{"id":"hi-113","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, a 17-year-old is caught driving with a measurable amount of alcohol for the first time. How long is the license suspended?","o":["180 days","7 days","30 days","5 years"],"h1":"It is about half a year.","h2":"In Hawaii, a driver under 21 caught driving with a measurable amount of alcohol for the first time gets a 180-day license suspension, and those under 18 attend an alcohol program with a parent.","p":"Right. The suspension is 180 days."},"es":{"q":"En Hawái, a un joven de 17 años lo detienen por primera vez manejando con una cantidad medible de alcohol. ¿Por cuánto tiempo se suspende su licencia?","o":["180 días","7 días","30 días","5 años"],"h1":"Es más o menos medio año.","h2":"En Hawái, a un conductor menor de 21 años detenido por primera vez manejando con una cantidad medible de alcohol se le suspende la licencia por 180 días, y los menores de 18 asisten a un programa sobre alcohol con un padre.","p":"Correcto. La suspensión es de 180 días."},"ref":{"doc":"HI","page":null}},{"id":"hi-114","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, you ride a motorcycle that has no windshield. What must you and your passenger wear?","o":["Reflective vests","Leather gloves","Boots that cover the ankles","Safety glasses, goggles or a face shield"],"h1":"Protect your eyes from wind, bugs and stones.","h2":"In Hawaii, the rider and passenger on a motorcycle or motor scooter without a windshield must wear safety glasses, goggles or a face shield.","p":"Right. Eye protection is required without a windshield."},"es":{"q":"En Hawái, usted maneja una motocicleta sin parabrisas. ¿Qué deben usar usted y su pasajero?","o":["Chalecos reflectantes","Guantes de cuero","Botas que cubran los tobillos","Lentes de seguridad, gafas protectoras o careta"],"h1":"Proteja sus ojos del viento, los insectos y las piedras.","h2":"En Hawái, el conductor y el pasajero de una motocicleta o motoneta sin parabrisas deben usar lentes de seguridad, gafas protectoras o careta.","p":"Correcto. Sin parabrisas se exige protección para los ojos."},"ref":{"doc":"HI","page":null}},{"id":"hi-115","scope":"HI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Hawaii, what is the youngest age to drive a moped on a public road?","o":["13","16","14","18"],"h1":"It is the same age as for a provisional driver's license.","h2":"In Hawaii, a person must be at least 16 years old to drive a moped on a highway, street or other public property.","p":"Right. You must be at least 16."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para manejar un ciclomotor (moped) en la vía pública?","o":["13 años","16 años","14 años","18 años"],"h1":"Es la misma edad que para una licencia provisional.","h2":"En Hawái, una persona debe tener al menos 16 años para manejar un ciclomotor en una carretera, calle u otra propiedad pública.","p":"Correcto. Debe tener al menos 16 años."},"ref":{"doc":"HI","page":null}},{"id":"hi-116","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, who must wear a helmet with a fastened chin strap when driving a moped?","o":["Only drivers under 18","Only drivers under 16","Every moped driver, of any age","Only at night"],"h1":"Since 2025 the age limit for this rule is gone.","h2":"In Hawaii, every person driving a moped must wear a safety helmet securely fastened with a chin strap, whatever their age.","p":"Right. Every moped driver must wear a helmet."},"es":{"q":"En Hawái, ¿quién debe usar casco con la correa del mentón abrochada al manejar un ciclomotor (moped)?","o":["Solo los menores de 18 años","Solo los menores de 16 años","Todo conductor de ciclomotor, de cualquier edad","Solo de noche"],"h1":"Desde 2025 esta regla ya no tiene límite de edad.","h2":"En Hawái, toda persona que maneje un ciclomotor debe usar un casco de seguridad bien abrochado con la correa del mentón, sin importar su edad.","p":"Correcto. Todo conductor de ciclomotor debe usar casco."},"ref":{"doc":"HI","page":null}},{"id":"hi-117","scope":"HI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Hawaii, on a regular two-wheeled motorcycle, a passenger must be at least what age?","o":["7 years old","3 years old","12 years old","16 years old"],"h1":"Young children may not ride on a motorcycle or motor scooter.","h2":"In Hawaii, a motorcycle or motor scooter driver may not carry a passenger under seven years old, except on certain enclosed three-wheeled electric models with seat belts.","p":"Right. Passengers must be at least 7."},"es":{"q":"En Hawái, en una motocicleta normal de dos ruedas, ¿qué edad mínima debe tener un pasajero?","o":["7 años","3 años","12 años","16 años"],"h1":"Los niños pequeños no pueden ir en motocicleta ni motoneta.","h2":"En Hawái, el conductor de una motocicleta o motoneta no puede llevar a un pasajero menor de siete años, salvo en ciertos modelos eléctricos cerrados de tres ruedas con cinturones.","p":"Correcto. Los pasajeros deben tener al menos 7 años."},"ref":{"doc":"HI","page":null}},{"id":"hi-118","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, when must your headlights be on while you drive?","o":["Only from midnight until 5 a.m.","Only when it is raining hard","From one hour after sunset until sunrise","From 30 minutes after sunset until 30 minutes before sunrise"],"h1":"The time starts a little after the sun goes down.","h2":"In Hawaii, headlights must be lighted from thirty minutes after sunset until thirty minutes before sunrise.","p":"Right. From 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Hawái, ¿cuándo debe llevar los faros encendidos al manejar?","o":["Solo de la medianoche a las 5 a.m.","Solo cuando llueve fuerte","Desde una hora después de la puesta del sol hasta la salida del sol","Desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol"],"h1":"El horario empieza un poco después de que se pone el sol.","h2":"En Hawái, los faros deben ir encendidos desde treinta minutos después de la puesta del sol hasta treinta minutos antes de la salida del sol.","p":"Correcto. Desde 30 minutos después de la puesta hasta 30 minutos antes de la salida del sol."},"ref":{"doc":"HI","page":null}},{"id":"hi-119","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, who must wear a bicycle helmet when riding on a street or bike path?","o":["Riders under 10","Riders under 16","Riders under 21","Every rider of any age"],"h1":"If a child breaks this rule, the parent pays the fine.","h2":"In Hawaii, bicycle riders under 16 must wear a properly fitted and fastened bicycle helmet on streets, bikeways and other public property.","p":"Right. Riders under 16 must wear a helmet."},"es":{"q":"En Hawái, ¿quién debe usar casco de bicicleta al andar por la calle o por un sendero para bicicletas?","o":["Los ciclistas menores de 10 años","Los ciclistas menores de 16 años","Los ciclistas menores de 21 años","Todo ciclista de cualquier edad"],"h1":"Si un niño no cumple esta regla, el padre paga la multa.","h2":"En Hawái, los ciclistas menores de 16 años deben usar un casco de bicicleta bien ajustado y abrochado en las calles, ciclovías y otras propiedades públicas.","p":"Correcto. Los menores de 16 años deben usar casco."},"ref":{"doc":"HI","page":null}},{"id":"hi-120","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, what is the youngest age to ride an electric foot scooter on a public street?","o":["10","12","15","18"],"h1":"Riders under 16 must also wear a helmet.","h2":"In Hawaii, no one under 15 may ride an electric foot scooter on a public street, and riders under 16 must wear a helmet.","p":"Right. You must be at least 15."},"es":{"q":"En Hawái, ¿cuál es la edad mínima para andar en un scooter eléctrico de pie en una calle pública?","o":["10 años","12 años","15 años","18 años"],"h1":"Los menores de 16 años también deben usar casco.","h2":"En Hawái, nadie menor de 15 años puede andar en un scooter eléctrico de pie en una calle pública, y los menores de 16 deben usar casco.","p":"Correcto. Debe tener al menos 15 años."},"ref":{"doc":"HI","page":null}},{"id":"hi-121","scope":"HI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Hawaii, a fire truck is answering an emergency. How close may you follow it?","o":["No closer than 500 feet","No closer than 50 feet","No closer than 100 feet","As close as you like if you are careful"],"h1":"The distance is about the length of one and a half football fields.","h2":"In Hawaii, you may not follow an emergency vehicle answering an emergency closer than 500 feet, or park within 500 feet of where it stopped for a fire alarm.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Hawái, un camión de bomberos va a una emergencia. ¿Qué tan cerca puede seguirlo?","o":["No a menos de 500 pies (150 metros)","No a menos de 50 pies (15 metros)","No a menos de 100 pies (30 metros)","Tan cerca como quiera si tiene cuidado"],"h1":"La distancia es como una cancha y media de fútbol americano.","h2":"En Hawái, no puede seguir a menos de 500 pies a un vehículo de emergencia que va a una emergencia, ni estacionarse a menos de 500 pies de donde se detuvo por una alarma de incendio.","p":"Correcto. Manténgase al menos a 500 pies."},"ref":{"doc":"HI","page":null}},{"id":"hi-122","scope":"HI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Hawaii, what is the fine for parking in a bicycle lane?","o":["$15","$35","$2,000","$200"],"h1":"It is a fixed fine of a few hundred dollars.","h2":"In Hawaii, parking a vehicle in a bicycle lane or bicycle path is fined $200.","p":"Right. The fine is $200."},"es":{"q":"En Hawái, ¿cuál es la multa por estacionarse en un carril para bicicletas?","o":["$15","$35","$2,000","$200"],"h1":"Es una multa fija de unos cientos de dólares.","h2":"En Hawái, estacionar un vehículo en un carril o sendero para bicicletas tiene una multa de $200.","p":"Correcto. La multa es de $200."},"ref":{"doc":"HI","page":null}},{"id":"hi-123","scope":"HI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Hawaii, which vehicle may be driven on the steep road between the Waipio Valley lookout and the valley floor?","o":["Any all-wheel drive car or SUV","A four-wheel drive vehicle with a low-range gear","Any car with new tires and good brakes","Any vehicle during daylight hours"],"h1":"All-wheel drive does not count for this road.","h2":"In Hawaii, only low-range four-wheel drive vehicles may be driven on the road between the Waipio Valley lookout and the valley floor; all-wheel drive does not qualify.","p":"Right. Only low-range four-wheel drive is allowed."},"es":{"q":"En Hawái, ¿qué vehículo se puede manejar en el camino empinado entre el mirador del valle de Waipio y el fondo del valle?","o":["Cualquier auto o SUV de tracción integral (AWD)","Un vehículo de doble tracción (4x4) con marcha baja","Cualquier auto con llantas nuevas y buenos frenos","Cualquier vehículo durante el día"],"h1":"La tracción integral (AWD) no cuenta para este camino.","h2":"En Hawái, solo los vehículos 4x4 con marcha baja pueden circular por el camino entre el mirador del valle de Waipio y el fondo del valle; la tracción integral no cuenta.","p":"Correcto. Solo se permite 4x4 con marcha baja."},"ref":{"doc":"HI","page":null}},{"id":"hi-124","scope":"HI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Hawaii, how close to a crosswalk or intersection may you park along the curb, even with no sign or painted curb?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","Right up to the crosswalk"],"h1":"The rule helps drivers see people about to cross.","h2":"In Hawaii, since January 1, 2026, you may not park along the curb within 20 feet of a crosswalk or intersection, even if there is no sign or curb marking.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Hawái, ¿qué tan cerca de un cruce peatonal o de una intersección puede estacionarse junto a la acera, aunque no haya letrero ni acera pintada?","o":["No a menos de 5 pies (1.5 metros)","No a menos de 10 pies (3 metros)","No a menos de 20 pies (6 metros)","Justo hasta el cruce peatonal"],"h1":"La regla ayuda a los conductores a ver a las personas que van a cruzar.","h2":"En Hawái, desde el 1 de enero de 2026, no puede estacionarse junto a la acera a menos de 20 pies de un cruce peatonal o de una intersección, aunque no haya letrero ni marca en la acera.","p":"Correcto. Manténgase al menos a 20 pies."},"ref":{"doc":"HI","page":null}},{"id":"hi-125","scope":"HI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Hawaii, what fine does a driver face for a first conviction of excessive speeding?","o":["$500 to $1,000","$25 to $50","$100 to $200","$5,000 to $10,000"],"h1":"The license is also suspended for a time.","h2":"In Hawaii, a first excessive speeding conviction brings a fine of $500 to $1,000, a license suspension and a driver retraining course.","p":"Right. The fine is $500 to $1,000."},"es":{"q":"En Hawái, ¿qué multa enfrenta un conductor por una primera condena por exceso de velocidad extremo?","o":["De $500 a $1,000","De $25 a $50","De $100 a $200","De $5,000 a $10,000"],"h1":"También se suspende la licencia por un tiempo.","h2":"En Hawái, una primera condena por exceso de velocidad extremo trae una multa de $500 a $1,000, la suspensión de la licencia y un curso de reeducación vial.","p":"Correcto. La multa es de $500 a $1,000."},"ref":{"doc":"HI","page":null}},{"id":"hi-126","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, besides a fine, what must a driver do after a first conviction for not putting a child in the right car seat?","o":["Buy a new car","Do 100 hours of community service","Retake the road test","Attend a child passenger safety class"],"h1":"The court wants the driver to learn how to use car seats.","h2":"In Hawaii, a first child restraint violation brings a fine of up to $100 and a required child passenger restraint safety class of no more than four hours.","p":"Right. The driver must attend a child passenger safety class."},"es":{"q":"En Hawái, además de una multa, ¿qué debe hacer un conductor después de una primera condena por no llevar a un niño en el asiento de seguridad correcto?","o":["Comprar un auto nuevo","Hacer 100 horas de servicio comunitario","Volver a tomar el examen práctico","Asistir a una clase sobre seguridad de niños en el auto"],"h1":"El tribunal quiere que el conductor aprenda a usar los asientos de seguridad.","h2":"En Hawái, una primera infracción de sillas de seguridad para niños trae una multa de hasta $100 y una clase obligatoria sobre sillas de seguridad de no más de cuatro horas.","p":"Correcto. El conductor debe asistir a una clase sobre seguridad de niños en el auto."},"ref":{"doc":"HI","page":null}},{"id":"hi-127","scope":"HI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Hawaii, a provisional licensee breaks the passenger or late-night rules a second time. What happens?","o":["A written warning is mailed home","The license is suspended for one week","The license is revoked for six months","The teen pays a $20 fine only"],"h1":"The first time it is a three-month suspension; the second is tougher.","h2":"In Hawaii, a second violation of the provisional license rules leads to a six-month revocation, unless the driver turns 18 sooner.","p":"Right. A second violation means a six-month revocation."},"es":{"q":"En Hawái, un conductor con licencia provisional viola por segunda vez las reglas de pasajeros o de horario nocturno. ¿Qué pasa?","o":["Se envía a su casa una advertencia escrita","Se le suspende la licencia por una semana","Se le revoca la licencia por seis meses","Solo paga una multa de $20"],"h1":"La primera vez es una suspensión de tres meses; la segunda es más dura.","h2":"En Hawái, una segunda violación de las reglas de la licencia provisional lleva a una revocación de seis meses, salvo que el conductor cumpla 18 años antes.","p":"Correcto. Una segunda violación significa una revocación de seis meses."},"ref":{"doc":"HI","page":null}},{"id":"hi-128","scope":"HI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Hawaii, a driver fails to stop for a pedestrian in a crosswalk for the second time within one year. What happens to the license?","o":["Nothing; only a warning","It is revoked for 90 days","It is revoked for five years","It must be renewed early"],"h1":"The fine also doubles to $300.","h2":"In Hawaii, a second crosswalk violation within one year brings a $300 fine and a 90-day license revocation.","p":"Right. The license is revoked for 90 days."},"es":{"q":"En Hawái, un conductor no se detiene ante un peatón en un cruce peatonal por segunda vez en un año. ¿Qué pasa con su licencia?","o":["Nada; solo una advertencia","Se revoca por 90 días","Se revoca por cinco años","Debe renovarla antes de tiempo"],"h1":"La multa también se duplica a $300.","h2":"En Hawái, una segunda infracción en un cruce peatonal en un año trae una multa de $300 y la revocación de la licencia por 90 días.","p":"Correcto. La licencia se revoca por 90 días."},"ref":{"doc":"HI","page":null}},{"id":"hi-129","scope":"HI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Hawaii, a car is brand new. How long after it is first sold may it go without a periodic safety inspection?","o":["Two years","Six months","Five years","Ten years"],"h1":"After that, it is inspected every year like other cars.","h2":"In Hawaii, a new car does not need a periodic safety inspection within two years of the date it was first sold; after that it is inspected every 12 months.","p":"Right. A new car can go two years before its next inspection."},"es":{"q":"En Hawái, un auto es totalmente nuevo. ¿Cuánto tiempo después de su primera venta puede pasar sin la inspección periódica de seguridad?","o":["Dos años","Seis meses","Cinco años","Diez años"],"h1":"Después se inspecciona cada año como los demás autos.","h2":"En Hawái, un auto nuevo no necesita la inspección periódica de seguridad dentro de los dos años desde su primera venta; después se inspecciona cada 12 meses.","p":"Correcto. Un auto nuevo puede pasar dos años sin su siguiente inspección."},"ref":{"doc":"HI","page":null}},{"id":"hi-130","scope":"HI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Hawaii, a person is convicted of throwing litter from a car for the first time. What is the fine?","o":["$10, with no other penalty at all","A written warning, with no fine","$5,000 and at least one year in jail","$100 to $500, plus 4 hours picking up litter"],"h1":"The court also gives the person work picking up litter or doing community service.","h2":"In Hawaii, a first conviction for littering from a vehicle brings a fine of $100 to $500 and four hours of picking up litter or community service.","p":"Right. The fine is $100 to $500, plus 4 hours of litter pickup."},"es":{"q":"En Hawái, una persona es condenada por primera vez por tirar basura desde un auto. ¿Cuál es la multa?","o":["$10, sin ningún otro castigo","Una advertencia escrita, sin multa","$5,000 y al menos un año de cárcel","De $100 a $500, más 4 horas recogiendo basura"],"h1":"El tribunal también le da trabajo recogiendo basura o servicio comunitario.","h2":"En Hawái, una primera condena por tirar basura desde un vehículo trae una multa de $100 a $500 y cuatro horas recogiendo basura o haciendo servicio comunitario.","p":"Correcto. La multa es de $100 a $500, más 4 horas recogiendo basura."},"ref":{"doc":"HI","page":null}},{"id":"hi-131","scope":"HI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Hawaii, you stop at a scenic lookout to enjoy the view. May you drink a beer there?","o":["Yes, as long as the engine is turned off","Yes, as long as you are not the driver","No, drinking alcohol at a scenic lookout is not allowed","Yes, but only after the sun has set"],"h1":"The law names scenic lookouts on purpose.","h2":"In Hawaii, no one may drink alcohol at a scenic lookout.","p":"Right. Drinking at a scenic lookout is not allowed."},"es":{"q":"En Hawái, usted se detiene en un mirador para disfrutar la vista. ¿Puede tomarse una cerveza allí?","o":["Sí, siempre que el motor esté apagado","Sí, siempre que usted no sea el conductor","No, no se permite tomar alcohol en un mirador","Sí, pero solo después de la puesta del sol"],"h1":"La ley menciona los miradores a propósito.","h2":"En Hawái, nadie puede tomar alcohol en un mirador.","p":"Correcto. No se permite tomar alcohol en un mirador."},"ref":{"doc":"HI","page":null}},{"id":"ia-001","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Iowa lets teens start practicing earlier than many states.","h2":"In Iowa you can get an instruction permit at 14 years old, with a parent or guardian's consent.","p":"Right. Iowa instruction permits start at 14."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Iowa permite empezar a practicar antes que muchos estados.","h2":"En Iowa usted puede obtener un permiso de instrucción a los 14 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. En Iowa el permiso de instrucción empieza a los 14."},"zh":{"q":"在 Iowa，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"Iowa 让青少年比很多州更早开始练习。","h2":"在 Iowa，经父母或监护人同意，你 14 岁就可以拿到学习驾照。","p":"对。Iowa 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Iowa cho thiếu niên bắt đầu tập lái sớm hơn nhiều tiểu bang khác.","h2":"Ở Iowa, bạn có thể lấy giấy phép tập lái khi 14 tuổi, với sự đồng ý của cha mẹ hoặc người giám hộ.","p":"Đúng. Ở Iowa, giấy phép tập lái bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Pinapayagan ng Iowa ang mga kabataan na magsimulang mag-ensayo nang mas maaga kaysa sa maraming estado.","h2":"Sa Iowa, maaari kang makakuha ng instruction permit sa edad na 14, nang may pahintulot ng magulang o tagapag-alaga.","p":"Tama. Sa Iowa, nagsisimula ang instruction permit sa edad na 14."},"ar":{"q":"في ولاية Iowa، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"تسمح Iowa للمراهقين ببدء التدريب في وقت أبكر من كثير من الولايات.","h2":"في Iowa يمكنك الحصول على تصريح تعلّم القيادة في سن 14 سنة، بموافقة أحد الوالدين أو الوصي.","p":"صحيح. تصريح تعلّم القيادة في Iowa يبدأ من سن 14."},"ref":{"doc":"IA","page":null}},{"id":"ia-002","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, how many hours of supervised driving must a teen complete before an intermediate license?","o":["10 hours","50 hours","20 hours","40 hours"],"h1":"It is a smaller number than in most states.","h2":"An Iowa teen must complete 20 hours of supervised driving before getting an intermediate license, and driver education driving counts toward them.","p":"Right. Iowa asks for 20 supervised hours."},"es":{"q":"En Iowa, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia intermedia?","o":["10 horas","50 horas","20 horas","40 horas"],"h1":"Es un número más bajo que en la mayoría de los estados.","h2":"Un adolescente en Iowa debe completar 20 horas de manejo supervisado antes de obtener la licencia intermedia, y el manejo en el curso de educación vial cuenta.","p":"Correcto. Iowa pide 20 horas supervisadas."},"zh":{"q":"在 Iowa，青少年拿中级驾照（intermediate license）前，必须完成多少小时有人陪同的驾驶？","o":["10 小时","50 小时","20 小时","40 小时"],"h1":"这个数字比大多数州少。","h2":"Iowa 的青少年拿中级驾照前，必须完成 20 小时有人陪同的驾驶，驾驶课上的驾驶时间也算在里面。","p":"对。Iowa 要求 20 小时有人陪同的驾驶。"},"vi":{"q":"Ở Iowa, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái trung gian (intermediate license)?","o":["10 giờ","50 giờ","20 giờ","40 giờ"],"h1":"Con số này nhỏ hơn so với hầu hết các tiểu bang.","h2":"Ở Iowa, thiếu niên phải lái xe có người giám sát 20 giờ trước khi lấy bằng lái trung gian, và giờ lái trong lớp học lái xe cũng được tính.","p":"Đúng. Iowa yêu cầu 20 giờ lái có người giám sát."},"tl":{"q":"Sa Iowa, ilang oras ng pagmamaneho na may gumagabay ang kailangang tapusin ng isang kabataan bago makakuha ng intermediate license?","o":["10 oras","50 oras","20 oras","40 oras"],"h1":"Mas maliit ang bilang na ito kaysa sa karamihan ng mga estado.","h2":"Kailangang tapusin ng isang kabataan sa Iowa ang 20 oras ng pagmamaneho na may gumagabay bago makakuha ng intermediate license, at kasama sa bilang ang pagmamaneho sa driver education.","p":"Tama. Humihingi ang Iowa ng 20 oras na may gumagabay."},"ar":{"q":"في Iowa، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["10 ساعات","50 ساعة","20 ساعة","40 ساعة"],"h1":"هذا العدد أقل مما في معظم الولايات.","h2":"يجب على المراهق في Iowa أن يكمل 20 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة المتوسطة، وساعات القيادة في دورة تعليم القيادة تُحسب منها.","p":"صحيح. تطلب Iowa عشرين ساعة تحت الإشراف."},"ref":{"doc":"IA","page":null}},{"id":"ia-003","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, how many of the supervised practice hours must be between sunset and sunrise?","o":["At least 2 hours","At least 5 hours","At least 10 hours","None are required"],"h1":"It is a small part of the total.","h2":"At least 2 of the 20 supervised hours in Iowa must be driven between sunset and sunrise.","p":"Right. Two hours must be after dark."},"es":{"q":"En Iowa, ¿cuántas de las horas de práctica supervisada deben ser entre la puesta y la salida del sol?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","No se exige ninguna"],"h1":"Es una parte pequeña del total.","h2":"Por lo menos 2 de las 20 horas supervisadas en Iowa deben manejarse entre la puesta y la salida del sol.","p":"Correcto. Dos horas deben ser de noche."},"zh":{"q":"在 Iowa，有人陪同的练习时间里，必须有多少小时是在日落到日出之间？","o":["至少 2 小时","至少 5 小时","至少 10 小时","不要求"],"h1":"这是总时间里的一小部分。","h2":"在 Iowa，20 小时有人陪同的驾驶中，至少 2 小时必须在日落到日出之间。","p":"对。必须有两个小时是在天黑以后开的。"},"vi":{"q":"Ở Iowa, trong số giờ tập lái có người giám sát, bao nhiêu giờ phải lái từ lúc mặt trời lặn đến lúc mặt trời mọc?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 10 giờ","Không bắt buộc"],"h1":"Đó là một phần nhỏ của tổng số giờ.","h2":"Ở Iowa, ít nhất 2 trong 20 giờ lái có người giám sát phải lái từ lúc mặt trời lặn đến lúc mặt trời mọc.","p":"Đúng. Phải lái hai giờ khi trời tối."},"tl":{"q":"Sa Iowa, ilan sa mga oras ng pag-eensayo na may gumagabay ang dapat gawin mula paglubog hanggang pagsikat ng araw?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Walang kailangan"],"h1":"Maliit na bahagi ito ng kabuuan.","h2":"Hindi bababa sa 2 sa 20 oras na may gumagabay sa Iowa ang dapat imaneho mula paglubog hanggang pagsikat ng araw.","p":"Tama. Dalawang oras ang dapat sa gabi."},"ar":{"q":"في Iowa، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون بين غروب الشمس وشروقها؟","o":["ساعتان على الأقل","5 ساعات على الأقل","10 ساعات على الأقل","لا يُشترط شيء"],"h1":"هي جزء صغير من المجموع.","h2":"يجب أن تكون ساعتان على الأقل من الساعات العشرين تحت الإشراف في Iowa بين غروب الشمس وشروقها.","p":"صحيح. يجب قيادة ساعتين بعد حلول الظلام."},"ref":{"doc":"IA","page":null}},{"id":"ia-004","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how long must a teen hold an instruction permit before getting an intermediate license?","o":["3 months","6 months","9 months","12 months"],"h1":"It is a full year of practice.","h2":"An Iowa teen must hold a valid instruction permit for a total of 12 months before applying for an intermediate license.","p":"Right. Twelve months with the permit."},"es":{"q":"En Iowa, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es un año completo de práctica.","h2":"Un adolescente en Iowa debe tener un permiso de instrucción válido por un total de 12 meses antes de solicitar la licencia intermedia.","p":"Correcto. Doce meses con el permiso."},"zh":{"q":"在 Iowa，青少年必须持有学习驾照多久，才能拿到中级驾照？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是整整一年的练习。","h2":"Iowa 的青少年必须总共持有有效的学习驾照 12 个月，才能申请中级驾照。","p":"对。持学习驾照十二个月。"},"vi":{"q":"Ở Iowa, thiếu niên phải giữ giấy phép tập lái (instruction permit) bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là một năm tập lái đầy đủ.","h2":"Ở Iowa, thiếu niên phải giữ giấy phép tập lái còn hiệu lực tổng cộng 12 tháng trước khi nộp đơn xin bằng lái trung gian.","p":"Đúng. Giữ giấy phép tập lái 12 tháng."},"tl":{"q":"Sa Iowa, gaano katagal dapat hawak ng isang kabataan ang instruction permit bago makakuha ng intermediate license?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Isang buong taon ito ng pag-eensayo.","h2":"Ang isang kabataan sa Iowa ay dapat may hawak na balidong instruction permit nang kabuuang 12 buwan bago mag-apply para sa intermediate license.","p":"Tama. Labindalawang buwan na may permit."},"ar":{"q":"في Iowa، كم مدة يجب أن يحمل المراهق تصريح تعلّم القيادة (instruction permit) قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"هي سنة كاملة من التدريب.","h2":"يجب على المراهق في Iowa أن يحمل تصريح تعلّم قيادة ساريًا لمدة 12 شهرًا في المجموع قبل التقدم بطلب الرخصة المتوسطة.","p":"صحيح. اثنا عشر شهرًا مع التصريح."},"ref":{"doc":"IA","page":null}},{"id":"ia-005","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what driving record does a teen need right before applying for an intermediate license?","o":["No record is checked","A clean record for at least 6 months in a row","A clean record for at least 1 month","No more than three tickets"],"h1":"The state looks at the last half year.","h2":"An Iowa teen needs a clean driving record for at least 6 months in a row right before applying for an intermediate license.","p":"Right. Six clean months in a row."},"es":{"q":"En Iowa, ¿qué historial de manejo necesita un adolescente justo antes de solicitar la licencia intermedia?","o":["No se revisa el historial","Un historial limpio por lo menos 6 meses seguidos","Un historial limpio por lo menos 1 mes","No más de tres multas"],"h1":"El estado revisa el último medio año.","h2":"Un adolescente en Iowa necesita un historial de manejo limpio por lo menos 6 meses seguidos justo antes de solicitar la licencia intermedia.","p":"Correcto. Seis meses seguidos sin problemas."},"zh":{"q":"在 Iowa，青少年在申请中级驾照之前，需要什么样的驾驶记录？","o":["不检查记录","连续至少 6 个月没有违规记录","至少 1 个月没有违规记录","罚单不超过三张"],"h1":"州政府看的是最近半年。","h2":"Iowa 的青少年在申请中级驾照之前，需要连续至少 6 个月没有违规的驾驶记录。","p":"对。连续六个月没有违规。"},"vi":{"q":"Ở Iowa, thiếu niên cần hồ sơ lái xe như thế nào ngay trước khi nộp đơn xin bằng lái trung gian (intermediate license)?","o":["Không kiểm tra hồ sơ","Hồ sơ sạch ít nhất 6 tháng liên tục","Hồ sơ sạch ít nhất 1 tháng","Không quá ba vé phạt"],"h1":"Tiểu bang xem xét nửa năm gần nhất.","h2":"Ở Iowa, thiếu niên cần hồ sơ lái xe sạch ít nhất 6 tháng liên tục ngay trước khi nộp đơn xin bằng lái trung gian.","p":"Đúng. Sáu tháng sạch liên tục."},"tl":{"q":"Sa Iowa, anong rekord sa pagmamaneho ang kailangan ng isang kabataan bago mismo mag-apply para sa intermediate license?","o":["Walang tinitingnang rekord","Malinis na rekord nang hindi bababa sa 6 na buwan nang sunod-sunod","Malinis na rekord nang hindi bababa sa 1 buwan","Hindi hihigit sa tatlong tiket"],"h1":"Tinitingnan ng estado ang huling kalahating taon.","h2":"Kailangan ng isang kabataan sa Iowa ng malinis na rekord sa pagmamaneho nang hindi bababa sa 6 na buwan nang sunod-sunod bago mismo mag-apply para sa intermediate license.","p":"Tama. Anim na malinis na buwan nang sunod-sunod."},"ar":{"q":"في Iowa، ما سجل القيادة الذي يحتاجه المراهق مباشرة قبل التقدم بطلب الرخصة المتوسطة (intermediate license)؟","o":["لا يتم فحص أي سجل","سجل نظيف لمدة 6 أشهر متتالية على الأقل","سجل نظيف لمدة شهر واحد على الأقل","ثلاث مخالفات كحد أقصى"],"h1":"تنظر الولاية إلى نصف السنة الأخير.","h2":"يحتاج المراهق في Iowa إلى سجل قيادة نظيف لمدة 6 أشهر متتالية على الأقل مباشرة قبل التقدم بطلب الرخصة المتوسطة.","p":"صحيح. ستة أشهر نظيفة متتالية."},"ref":{"doc":"IA","page":null}},{"id":"ia-006","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for an intermediate license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the first permit.","h2":"You must be at least 16 years old to get an intermediate license in Iowa.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia intermedia?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Llega dos años después del primer permiso.","h2":"Usted debe tener por lo menos 16 años para obtener la licencia intermedia en Iowa.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Iowa，最小几岁可以拿到中级驾照？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"它是在第一次拿学习驾照的两年以后。","h2":"在 Iowa，你必须至少 16 岁才能拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy bằng lái trung gian (intermediate license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Đó là hai năm sau giấy phép đầu tiên.","h2":"Bạn phải ít nhất 16 tuổi để lấy bằng lái trung gian ở Iowa.","p":"Đúng. Bằng lái trung gian bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para sa intermediate license?","o":["15 taong gulang","15 at kalahati","16 taong gulang","17 taong gulang"],"h1":"Dalawang taon ito pagkatapos ng unang permit.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng intermediate license sa Iowa.","p":"Tama. Nagsisimula ang intermediate license sa 16."},"ar":{"q":"في Iowa، ما أصغر عمر للحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"يأتي بعد سنتين من التصريح الأول.","h2":"يجب أن يكون عمرك 16 سنة على الأقل للحصول على الرخصة المتوسطة في Iowa.","p":"صحيح. الرخصة المتوسطة تبدأ من سن 16."},"ref":{"doc":"IA","page":null}},{"id":"ia-007","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, during which hours may an intermediate license holder not drive without adult supervision?","o":["12:30 a.m. to 5 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","9 p.m. to 6 a.m."],"h1":"The limit starts a little after midnight.","h2":"An Iowa intermediate license holder may not drive without adult supervision between 12:30 a.m. and 5 a.m., unless a waiver allows it.","p":"Right. 12:30 to 5 in the morning."},"es":{"q":"En Iowa, ¿en qué horario no puede manejar sin supervisión de un adulto quien tiene licencia intermedia?","o":["De 12:30 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"El límite empieza un poco después de la medianoche.","h2":"Quien tiene licencia intermedia en Iowa no puede manejar sin supervisión de un adulto entre las 12:30 a.m. y las 5 a.m., salvo que tenga una exención.","p":"Correcto. De 12:30 a 5 de la mañana."},"zh":{"q":"在 Iowa，持中级驾照的人在哪些时间不能在没有成年人陪同的情况下开车？","o":["凌晨 12:30 到早上 5 点","晚上 11 点到早上 5 点","午夜到早上 6 点","晚上 9 点到早上 6 点"],"h1":"这个限制在午夜过后不久开始。","h2":"在 Iowa，持中级驾照的人在凌晨 12:30 到早上 5 点之间不能在没有成年人陪同的情况下开车，除非有豁免书允许。","p":"对。凌晨 12:30 到早上 5 点。"},"vi":{"q":"Ở Iowa, người có bằng lái trung gian (intermediate license) không được lái xe mà không có người lớn giám sát trong những giờ nào?","o":["12:30 sáng đến 5 giờ sáng","11 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu sau nửa đêm một chút.","h2":"Ở Iowa, người có bằng lái trung gian không được lái xe mà không có người lớn giám sát từ 12:30 sáng đến 5 giờ sáng, trừ khi có giấy miễn trừ cho phép.","p":"Đúng. Từ 12:30 đến 5 giờ sáng."},"tl":{"q":"Sa Iowa, sa anong mga oras hindi maaaring magmaneho ang may intermediate license nang walang gumagabay na adulto?","o":["12:30 a.m. hanggang 5 a.m.","11 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","9 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon nang kaunti pagkalipas ng hatinggabi.","h2":"Ang may intermediate license sa Iowa ay hindi maaaring magmaneho nang walang gumagabay na adulto mula 12:30 a.m. hanggang 5 a.m., maliban kung may waiver na nagpapahintulot.","p":"Tama. 12:30 hanggang 5 ng umaga."},"ar":{"q":"في Iowa، في أي ساعات لا يجوز لحامل الرخصة المتوسطة (intermediate license) أن يقود دون إشراف شخص بالغ؟","o":["من 12:30 بعد منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل بقليل.","h2":"لا يجوز لحامل الرخصة المتوسطة في Iowa أن يقود دون إشراف شخص بالغ من 12:30 بعد منتصف الليل إلى 5 صباحًا، إلا إذا سمح له بذلك إعفاء موقّع.","p":"صحيح. من 12:30 إلى 5 صباحًا."},"ref":{"doc":"IA","page":null}},{"id":"ia-008","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how can an intermediate license holder legally drive alone after 12:30 a.m. for school or work?","o":["Show a school ID","Call a parent before driving","Drive only on city streets","Carry a waiver signed by a parent or guardian"],"h1":"A parent fills out a form for this.","h2":"A parent, guardian or custodian can sign a waiver for school or work driving, and the teen must carry it in the vehicle.","p":"Right. A signed waiver in the vehicle."},"es":{"q":"En Iowa, ¿cómo puede quien tiene licencia intermedia manejar solo después de las 12:30 a.m. por la escuela o el trabajo?","o":["Mostrar su credencial escolar","Llamar a un padre antes de manejar","Manejar solo por calles de la ciudad","Llevar una exención firmada por un padre o tutor"],"h1":"Un padre llena un formulario para esto.","h2":"Un padre, tutor o custodio puede firmar una exención para manejar por la escuela o el trabajo, y el adolescente debe llevarla en el vehículo.","p":"Correcto. Una exención firmada dentro del vehículo."},"zh":{"q":"在 Iowa，持中级驾照的人怎样才能合法地在凌晨 12:30 以后为上学或上班一个人开车？","o":["出示学生证","开车前给父母打电话","只在市区街道上开","带着父母或监护人签字的豁免书"],"h1":"这需要父母填一张表格。","h2":"父母、监护人或看护人可以为上学或上班开车签一份豁免书，青少年必须把它带在车里。","p":"对。车里要有签了字的豁免书。"},"vi":{"q":"Ở Iowa, người có bằng lái trung gian (intermediate license) có thể lái xe một mình một cách hợp pháp sau 12:30 sáng để đi học hoặc đi làm bằng cách nào?","o":["Xuất trình thẻ học sinh","Gọi cho cha mẹ trước khi lái","Chỉ lái trên đường trong thành phố","Mang theo giấy miễn trừ (waiver) có chữ ký của cha mẹ hoặc người giám hộ"],"h1":"Cha mẹ điền một mẫu đơn cho việc này.","h2":"Cha mẹ, người giám hộ hoặc người trông nom có thể ký giấy miễn trừ để lái xe đi học hoặc đi làm, và thiếu niên phải mang giấy này trong xe.","p":"Đúng. Mang giấy miễn trừ có chữ ký trong xe."},"tl":{"q":"Sa Iowa, paano legal na makakapagmaneho nang mag-isa ang may intermediate license pagkalipas ng 12:30 a.m. para sa paaralan o trabaho?","o":["Ipakita ang school ID","Tawagan ang magulang bago magmaneho","Magmaneho lamang sa mga kalye ng lungsod","Magdala ng waiver na pinirmahan ng magulang o tagapag-alaga"],"h1":"May form na pinupunan ang magulang para dito.","h2":"Maaaring pumirma ang magulang, tagapag-alaga o custodian ng waiver para sa pagmamaneho papunta sa paaralan o trabaho, at dapat itong dala ng kabataan sa sasakyan.","p":"Tama. Isang pinirmahang waiver sa sasakyan."},"ar":{"q":"في Iowa، كيف يمكن لحامل الرخصة المتوسطة (intermediate license) أن يقود وحده بشكل قانوني بعد 12:30 بعد منتصف الليل من أجل المدرسة أو العمل؟","o":["إظهار بطاقة المدرسة","الاتصال بأحد الوالدين قبل القيادة","القيادة في شوارع المدينة فقط","حمل إعفاء (waiver) موقّع من أحد الوالدين أو الوصي"],"h1":"يملأ أحد الوالدين نموذجًا لهذا الغرض.","h2":"يمكن لأحد الوالدين أو الوصي أو الكفيل أن يوقّع إعفاءً للقيادة من أجل المدرسة أو العمل، ويجب على المراهق أن يحمله في السيارة.","p":"صحيح. إعفاء موقّع في السيارة."},"ref":{"doc":"IA","page":null}},{"id":"ia-009","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, during the first 6 months with an intermediate license, how many unrelated passengers under 18 may ride along when no adult supervises?","o":["None","One","Two","Three"],"h1":"Brothers, sisters and household children do not count.","h2":"During the first 6 months, an Iowa intermediate license holder may carry only one unrelated passenger under 18, unless a parent allows more.","p":"Right. Only one unrelated minor."},"es":{"q":"En Iowa, durante los primeros 6 meses con licencia intermedia, ¿cuántos pasajeros menores de 18 años que no son familiares pueden ir con usted sin un adulto supervisando?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los hermanos y los niños que viven en su casa no cuentan.","h2":"Durante los primeros 6 meses, quien tiene licencia intermedia en Iowa puede llevar solo un pasajero menor de 18 años que no sea familiar, salvo que un padre permita más.","p":"Correcto. Solo un menor que no es familiar."},"zh":{"q":"在 Iowa，拿到中级驾照的头 6 个月里，没有成年人陪同时，可以载几个不是亲属、18 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"兄弟姐妹和家里的孩子不算。","h2":"在头 6 个月里，Iowa 持中级驾照的人只能载一个不是亲属、18 岁以下的乘客，除非父母允许载更多。","p":"对。只能载一个不是亲属的未成年人。"},"vi":{"q":"Ở Iowa, trong 6 tháng đầu có bằng lái trung gian (intermediate license), khi không có người lớn giám sát, được chở bao nhiêu hành khách dưới 18 tuổi không phải người thân?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Anh chị em và trẻ em trong cùng nhà không được tính.","h2":"Trong 6 tháng đầu, người có bằng lái trung gian ở Iowa chỉ được chở một hành khách dưới 18 tuổi không phải người thân, trừ khi cha mẹ cho phép nhiều hơn.","p":"Đúng. Chỉ một trẻ vị thành niên không phải người thân."},"tl":{"q":"Sa Iowa, sa unang 6 na buwan na may intermediate license, ilang pasaherong wala pang 18 na hindi kamag-anak ang maaaring isakay kapag walang gumagabay na adulto?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Hindi binibilang ang mga kapatid at mga batang kasama sa bahay.","h2":"Sa unang 6 na buwan, ang may intermediate license sa Iowa ay maaaring magsakay ng isang pasaherong wala pang 18 na hindi kamag-anak lamang, maliban kung pinapayagan ng magulang ang higit pa.","p":"Tama. Isang menor de edad lamang na hindi kamag-anak."},"ar":{"q":"في Iowa، خلال أول 6 أشهر مع الرخصة المتوسطة (intermediate license)، كم راكبًا دون 18 سنة من غير الأقارب يمكن أن يركب معك عندما لا يشرف شخص بالغ؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"الإخوة والأخوات والأطفال الذين يعيشون في البيت نفسه لا يُحسبون.","h2":"خلال أول 6 أشهر، يمكن لحامل الرخصة المتوسطة في Iowa أن يحمل راكبًا واحدًا فقط دون 18 سنة من غير الأقارب، إلا إذا سمح أحد الوالدين بأكثر.","p":"صحيح. قاصر واحد فقط من غير الأقارب."},"ref":{"doc":"IA","page":null}},{"id":"ia-010","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age for a minor school license?","o":["14 years old","15 years old","14 and a half","16 years old"],"h1":"It is halfway between two birthdays.","h2":"You can get an Iowa minor school license at 14 and a half, after driver education and six clean months with a permit.","p":"Right. Fourteen and a half."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para la licencia escolar de menor?","o":["14 años","15 años","14 años y medio","16 años"],"h1":"Está a la mitad entre dos cumpleaños.","h2":"Usted puede obtener la licencia escolar de menor en Iowa a los 14 años y medio, después de la educación vial y seis meses limpios con el permiso.","p":"Correcto. Catorce años y medio."},"zh":{"q":"在 Iowa，最小几岁可以拿到未成年人上学驾照（minor school license）？","o":["14 岁","15 岁","14 岁半","16 岁"],"h1":"它在两个生日的正中间。","h2":"在 Iowa，上完驾驶课、并持学习驾照六个月没有违规以后，你 14 岁半就可以拿到未成年人上学驾照。","p":"对。十四岁半。"},"vi":{"q":"Ở Iowa, tuổi nhỏ nhất để lấy bằng lái đi học cho trẻ vị thành niên (minor school license) là bao nhiêu?","o":["14 tuổi","15 tuổi","14 tuổi rưỡi","16 tuổi"],"h1":"Đó là ở giữa hai ngày sinh nhật.","h2":"Bạn có thể lấy bằng lái đi học cho trẻ vị thành niên ở Iowa khi 14 tuổi rưỡi, sau khi học lái xe và có sáu tháng sạch với giấy phép tập lái.","p":"Đúng. Mười bốn tuổi rưỡi."},"tl":{"q":"Sa Iowa, ano ang pinakabatang edad para sa minor school license?","o":["14 taong gulang","15 taong gulang","14 at kalahati","16 taong gulang"],"h1":"Nasa gitna ito ng dalawang kaarawan.","h2":"Maaari kang makakuha ng minor school license sa Iowa sa edad na 14 at kalahati, pagkatapos ng driver education at anim na malinis na buwan na may permit.","p":"Tama. Labing-apat at kalahati."},"ar":{"q":"في Iowa، ما أصغر عمر للحصول على رخصة المدرسة للقاصرين (minor school license)؟","o":["14 سنة","15 سنة","14 سنة ونصف","16 سنة"],"h1":"هو في منتصف المسافة بين عيدَي ميلاد.","h2":"يمكنك الحصول على رخصة المدرسة للقاصرين في Iowa في سن 14 سنة ونصف، بعد دورة تعليم القيادة وستة أشهر نظيفة مع التصريح.","p":"صحيح. أربع عشرة سنة ونصف."},"ref":{"doc":"IA","page":null}},{"id":"ia-011","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, with a minor school license (special minor's restricted license), how far may a teen drive alone to work?","o":["25 miles or less","Any distance","5 miles or less","100 miles or less"],"h1":"The trip to work has a distance limit.","h2":"With an Iowa special minor's restricted license, a teen may drive alone to work only when the trip is 25 miles or less.","p":"Right. The drive to work must be 25 miles or less."},"es":{"q":"En Iowa, con una licencia escolar para menores (licencia restringida especial para menores), ¿qué distancia puede manejar solo un adolescente para ir al trabajo?","o":["25 millas o menos","Cualquier distancia","5 millas o menos","100 millas o menos"],"h1":"El viaje al trabajo tiene un límite de distancia.","h2":"Con una licencia restringida especial para menores de Iowa, un adolescente puede manejar solo al trabajo únicamente si el viaje es de 25 millas o menos.","p":"Correcto. El viaje al trabajo debe ser de 25 millas o menos."},"zh":{"q":"在 Iowa，持未成年人上学驾照（special minor's restricted license）的青少年，最远可以一个人开车去多远的地方上班？","o":["25 英里或以内","多远都可以","5 英里或以内","100 英里或以内"],"h1":"开车去上班有距离限制。","h2":"在 Iowa，持 special minor's restricted license 的青少年，只有在上班路程是 25 英里或以内时，才可以一个人开车去上班。","p":"对。开车去上班的路程必须是 25 英里或以内。"},"vi":{"q":"Ở Iowa, với bằng lái đi học cho trẻ vị thành niên (special minor's restricted license), thiếu niên được lái xe một mình đi làm xa bao nhiêu?","o":["25 dặm trở xuống","Bất kỳ khoảng cách nào","5 dặm trở xuống","100 dặm trở xuống"],"h1":"Chuyến đi làm có giới hạn khoảng cách.","h2":"Với bằng lái đặc biệt có giới hạn cho trẻ vị thành niên ở Iowa, thiếu niên chỉ được lái xe một mình đi làm khi quãng đường là 25 dặm trở xuống.","p":"Đúng. Quãng đường đi làm phải từ 25 dặm trở xuống."},"tl":{"q":"Sa Iowa, gamit ang minor school license (special minor's restricted license), gaano kalayo maaaring magmaneho nang mag-isa ang isang kabataan papunta sa trabaho?","o":["25 milya o mas kaunti","Kahit anong layo","5 milya o mas kaunti","100 milya o mas kaunti"],"h1":"May limitasyon sa layo ang biyahe papunta sa trabaho.","h2":"Gamit ang special minor's restricted license sa Iowa, maaaring magmaneho nang mag-isa ang kabataan papunta sa trabaho kung 25 milya o mas kaunti lamang ang biyahe.","p":"Tama. Dapat 25 milya o mas kaunti ang biyahe papunta sa trabaho."},"ar":{"q":"في Iowa، مع رخصة المدرسة للقاصرين (special minor's restricted license)، ما المسافة التي يمكن للمراهق أن يقودها وحده إلى العمل؟","o":["25 ميلًا أو أقل","أي مسافة","5 أميال أو أقل","100 ميل أو أقل"],"h1":"للرحلة إلى العمل حد للمسافة.","h2":"مع رخصة القاصر الخاصة المقيّدة في Iowa، يمكن للمراهق أن يقود وحده إلى العمل فقط عندما تكون الرحلة 25 ميلًا أو أقل.","p":"صحيح. يجب أن تكون الرحلة إلى العمل 25 ميلًا أو أقل."},"ref":{"doc":"IA","page":null}},{"id":"ia-012","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how old must a family member be to supervise a teen with an instruction permit?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The same age as the legal drinking age.","h2":"In Iowa, an immediate family member who supervises a permit driver must be licensed and at least 21 years old.","p":"Right. A family member must be 21 or older."},"es":{"q":"En Iowa, ¿qué edad debe tener un familiar para supervisar a un adolescente con permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"Es la misma edad para tomar alcohol legalmente.","h2":"En Iowa, un familiar directo que supervisa a un conductor con permiso debe tener licencia y por lo menos 21 años.","p":"Correcto. El familiar debe tener 21 años o más."},"zh":{"q":"在 Iowa，陪同持学习驾照的青少年开车的家人必须几岁？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"和法定可以喝酒的年龄一样。","h2":"在 Iowa，陪同持学习驾照的人开车的直系亲属必须有驾照，而且至少 21 岁。","p":"对。家人必须 21 岁或以上。"},"vi":{"q":"Ở Iowa, người thân trong gia đình phải bao nhiêu tuổi để giám sát thiếu niên có giấy phép tập lái (instruction permit)?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Bằng với tuổi được phép uống rượu hợp pháp.","h2":"Ở Iowa, người thân trong gia đình giám sát người tập lái phải có bằng lái và ít nhất 21 tuổi.","p":"Đúng. Người thân phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Iowa, ilang taon dapat ang isang kapamilya para gumabay sa kabataang may instruction permit?","o":["16 o mas matanda","18 o mas matanda","25 o mas matanda","21 o mas matanda"],"h1":"Kapareho ng legal na edad para uminom ng alak.","h2":"Sa Iowa, ang malapit na kapamilya na gumagabay sa nagmamanehong may permit ay dapat may lisensya at hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o mas matanda ang kapamilya."},"ar":{"q":"في Iowa، كم يجب أن يكون عمر فرد العائلة الذي يشرف على مراهق يحمل تصريح تعلّم القيادة (instruction permit)؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"هو نفس السن القانونية لشرب الكحول.","h2":"في Iowa، يجب أن يكون فرد العائلة المباشر الذي يشرف على سائق يحمل تصريحًا حاملًا لرخصة قيادة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون فرد العائلة 21 سنة أو أكثر."},"ref":{"doc":"IA","page":null}},{"id":"ia-013","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a supervisor who is not family needs the parent's written permission. How old must that person be?","o":["18 or older","21 or older","25 or older","30 or older"],"h1":"It is older than for a family member.","h2":"In Iowa, a supervisor who is not family must be licensed, at least 25 years old and have written permission from the parent or guardian.","p":"Right. A non-family supervisor must be 25 or older."},"es":{"q":"En Iowa, un supervisor que no es familiar necesita permiso escrito del padre. ¿Qué edad debe tener esa persona?","o":["18 años o más","21 años o más","25 años o más","30 años o más"],"h1":"Es mayor que para un familiar.","h2":"En Iowa, un supervisor que no es familiar debe tener licencia, por lo menos 25 años y permiso escrito del padre o tutor.","p":"Correcto. Un supervisor que no es familiar debe tener 25 años o más."},"zh":{"q":"在 Iowa，不是家人的陪同者需要父母的书面许可。这个人必须几岁？","o":["18 岁或以上","21 岁或以上","25 岁或以上","30 岁或以上"],"h1":"比家人的年龄要求更大。","h2":"在 Iowa，不是家人的陪同者必须有驾照、至少 25 岁，并且有父母或监护人的书面许可。","p":"对。不是家人的陪同者必须 25 岁或以上。"},"vi":{"q":"Ở Iowa, người giám sát không phải người thân cần sự cho phép bằng văn bản của cha mẹ. Người đó phải bao nhiêu tuổi?","o":["18 tuổi trở lên","21 tuổi trở lên","25 tuổi trở lên","30 tuổi trở lên"],"h1":"Lớn tuổi hơn so với người thân trong gia đình.","h2":"Ở Iowa, người giám sát không phải người thân phải có bằng lái, ít nhất 25 tuổi và có sự cho phép bằng văn bản của cha mẹ hoặc người giám hộ.","p":"Đúng. Người giám sát không phải người thân phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Iowa, ang gumagabay na hindi kapamilya ay kailangan ng nakasulat na pahintulot ng magulang. Ilang taon dapat ang taong iyon?","o":["18 o mas matanda","21 o mas matanda","25 o mas matanda","30 o mas matanda"],"h1":"Mas matanda ito kaysa sa kapamilya.","h2":"Sa Iowa, ang gumagabay na hindi kapamilya ay dapat may lisensya, hindi bababa sa 25 taong gulang, at may nakasulat na pahintulot ng magulang o tagapag-alaga.","p":"Tama. Dapat 25 o mas matanda ang gumagabay na hindi kapamilya."},"ar":{"q":"في Iowa، المشرف الذي ليس من العائلة يحتاج إلى إذن مكتوب من أحد الوالدين. كم يجب أن يكون عمر هذا الشخص؟","o":["18 سنة أو أكثر","21 سنة أو أكثر","25 سنة أو أكثر","30 سنة أو أكثر"],"h1":"هو أكبر من عمر فرد العائلة.","h2":"في Iowa، يجب أن يكون المشرف الذي ليس من العائلة حاملًا لرخصة قيادة، وعمره 25 سنة على الأقل، ومعه إذن مكتوب من أحد الوالدين أو الوصي.","p":"صحيح. يجب أن يكون المشرف من خارج العائلة 25 سنة أو أكثر."},"ref":{"doc":"IA","page":null}},{"id":"ia-014","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Iowa a driver under 21 breaks the law with a blood alcohol level of 0.02 or more, and can lose their license.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Iowa, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Iowa un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más, y puede perder su licencia.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Iowa，对 21 岁以下的司机来说，血液酒精浓度多少是违法的？","o":["0.08 或更高","0.02 或更高","0.05 或更高","0.10 或更高"],"h1":"这比成年人的上限低很多。","h2":"在 Iowa，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法，而且可能会失去驾照。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Iowa, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.02 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Iowa, người lái xe dưới 21 tuổi phạm luật khi nồng độ cồn trong máu từ 0.02 trở lên, và có thể bị mất bằng lái.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Iowa, anong antas ng alak sa dugo ang ilegal para sa drayber na wala pang 21?","o":["0.08 o higit pa","0.02 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa Iowa, lumalabag sa batas ang drayber na wala pang 21 kapag ang antas ng alak sa dugo ay 0.02 o higit pa, at maaari siyang mawalan ng lisensya.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Iowa، ما نسبة الكحول في الدم التي تُعد مخالفة للقانون لسائق عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين.","h2":"في Iowa، يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر، ويمكن أن يفقد رخصته.","p":"صحيح. لمن هم دون 21 سنة، الحد هو 0.02."},"ref":{"doc":"IA","page":37}},{"id":"ia-015","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, since July 1, 2025, how may an adult driver use a phone while driving?","o":["Any way, if driving slowly","Holding it, for calls only","Texting at red lights only","Only hands-free or by voice"],"h1":"The law is called the hands-free law.","h2":"Since July 1, 2025, Iowa drivers may not hold a phone while driving, and may use it only hands-free or by voice.","p":"Right. Hands-free only."},"es":{"q":"En Iowa, desde el 1 de julio de 2025, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["De cualquier forma, si maneja despacio","Sosteniéndolo, solo para llamadas","Escribiendo mensajes solo en luz roja","Solo con manos libres o por voz"],"h1":"La ley se llama ley de manos libres.","h2":"Desde el 1 de julio de 2025, en Iowa los conductores no pueden sostener el teléfono mientras manejan, y solo pueden usarlo con manos libres o por voz.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 Iowa，从 2025 年 7 月 1 日起，成年司机开车时可以怎样使用手机？","o":["怎样都可以，只要开得慢","可以手拿，但只能打电话","只能在红灯时发短信","只能用免提或语音"],"h1":"这个法律叫做免提法。","h2":"从 2025 年 7 月 1 日起，Iowa 的司机开车时不能手拿手机，只能用免提或语音来使用。","p":"对。只能用免提。"},"vi":{"q":"Ở Iowa, từ ngày 1 tháng 7 năm 2025, người lái xe trưởng thành được dùng điện thoại khi lái xe như thế nào?","o":["Bất kỳ cách nào, nếu lái chậm","Cầm trên tay, chỉ để gọi","Chỉ nhắn tin khi đèn đỏ","Chỉ rảnh tay hoặc bằng giọng nói"],"h1":"Luật này được gọi là luật rảnh tay (hands-free).","h2":"Từ ngày 1 tháng 7 năm 2025, người lái xe ở Iowa không được cầm điện thoại khi lái xe, và chỉ được dùng điện thoại ở chế độ rảnh tay hoặc bằng giọng nói.","p":"Đúng. Chỉ được rảnh tay."},"tl":{"q":"Sa Iowa, mula Hulyo 1, 2025, paano maaaring gumamit ng telepono ang adultong drayber habang nagmamaneho?","o":["Kahit paano, kung mabagal ang takbo","Hawak ito, para sa tawag lamang","Pag-text sa pulang ilaw lamang","Hands-free o gamit ang boses lamang"],"h1":"Tinatawag ang batas na hands-free law.","h2":"Mula Hulyo 1, 2025, hindi maaaring hawakan ng mga drayber sa Iowa ang telepono habang nagmamaneho, at maaari lamang itong gamitin nang hands-free o gamit ang boses.","p":"Tama. Hands-free lamang."},"ar":{"q":"في Iowa، منذ 1 يوليو 2025، كيف يمكن للسائق البالغ أن يستخدم الهاتف أثناء القيادة؟","o":["بأي طريقة، إذا كان يقود ببطء","يمسكه بيده، للمكالمات فقط","إرسال الرسائل عند الإشارة الحمراء فقط","بدون استخدام اليدين أو بالصوت فقط"],"h1":"يسمى هذا القانون قانون عدم استخدام اليدين (hands-free).","h2":"منذ 1 يوليو 2025، لا يجوز للسائقين في Iowa أن يمسكوا الهاتف أثناء القيادة، ويمكنهم استخدامه فقط بدون اليدين أو بالصوت.","p":"صحيح. بدون استخدام اليدين فقط."},"ref":{"doc":"IA","page":36}},{"id":"ia-016","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, may a teen with an intermediate license use a phone or tablet while driving?","o":["No, only equipment built into the vehicle is allowed","Yes, if it is hands-free","Yes, for music only","Yes, at red lights"],"h1":"Even hands-free devices are not allowed for this license.","h2":"An Iowa intermediate license holder may not use a phone, tablet or other electronic device while driving; only equipment permanently installed in the vehicle is allowed.","p":"Right. No phones or tablets for teen drivers."},"es":{"q":"En Iowa, ¿puede un adolescente con licencia intermedia usar un teléfono o tableta mientras maneja?","o":["No, solo el equipo instalado en el vehículo","Sí, si es manos libres","Sí, solo para música","Sí, en luz roja"],"h1":"Ni siquiera los aparatos de manos libres están permitidos con esta licencia.","h2":"Quien tiene licencia intermedia en Iowa no puede usar teléfono, tableta ni otro aparato electrónico mientras maneja; solo se permite el equipo instalado de forma permanente en el vehículo.","p":"Correcto. Nada de teléfonos ni tabletas para conductores adolescentes."},"zh":{"q":"在 Iowa，持中级驾照的青少年开车时可以用手机或平板电脑吗？","o":["不可以，只能用车上自带的设备","可以，只要是免提","可以，但只能听音乐","可以，在红灯时"],"h1":"持这种驾照，连免提设备也不允许。","h2":"在 Iowa，持中级驾照的人开车时不能用手机、平板电脑或其他电子设备，只能用固定安装在车上的设备。","p":"对。青少年司机不能用手机或平板电脑。"},"vi":{"q":"Ở Iowa, thiếu niên có bằng lái trung gian (intermediate license) có được dùng điện thoại hoặc máy tính bảng khi lái xe không?","o":["Không, chỉ được dùng thiết bị gắn sẵn trong xe","Có, nếu rảnh tay","Có, chỉ để nghe nhạc","Có, khi đèn đỏ"],"h1":"Ngay cả thiết bị rảnh tay cũng không được phép với loại bằng lái này.","h2":"Ở Iowa, người có bằng lái trung gian không được dùng điện thoại, máy tính bảng hay thiết bị điện tử khác khi lái xe; chỉ được dùng thiết bị gắn cố định trong xe.","p":"Đúng. Người lái xe tuổi thiếu niên không được dùng điện thoại hay máy tính bảng."},"tl":{"q":"Sa Iowa, maaari bang gumamit ng telepono o tablet habang nagmamaneho ang kabataang may intermediate license?","o":["Hindi, kagamitang nakakabit sa sasakyan lamang ang pinapayagan","Oo, kung hands-free","Oo, para sa musika lamang","Oo, sa pulang ilaw"],"h1":"Kahit ang mga hands-free na device ay hindi pinapayagan para sa lisensyang ito.","h2":"Ang may intermediate license sa Iowa ay hindi maaaring gumamit ng telepono, tablet o ibang electronic device habang nagmamaneho; kagamitang permanenteng nakakabit sa sasakyan lamang ang pinapayagan.","p":"Tama. Walang telepono o tablet para sa mga kabataang drayber."},"ar":{"q":"في Iowa، هل يجوز للمراهق الذي يحمل الرخصة المتوسطة (intermediate license) أن يستخدم هاتفًا أو جهازًا لوحيًا أثناء القيادة؟","o":["لا، يُسمح فقط بالأجهزة المركّبة في السيارة","نعم، إذا كان بدون استخدام اليدين","نعم، للموسيقى فقط","نعم، عند الإشارة الحمراء"],"h1":"حتى الأجهزة التي تعمل بدون اليدين غير مسموح بها مع هذه الرخصة.","h2":"لا يجوز لحامل الرخصة المتوسطة في Iowa أن يستخدم هاتفًا أو جهازًا لوحيًا أو أي جهاز إلكتروني آخر أثناء القيادة؛ يُسمح فقط بالأجهزة المركّبة بشكل دائم في السيارة.","p":"صحيح. لا هواتف ولا أجهزة لوحية للسائقين المراهقين."},"ref":{"doc":"IA","page":36}},{"id":"ia-017","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, what must you do when you approach any stopped vehicle on the roadside with its hazard lights on?","o":["Honk and keep your speed","Stop behind it","Change lanes or slow down","Nothing; the law covers only police cars"],"h1":"Iowa's law is named for these two actions.","h2":"In Iowa you must change lanes or slow down when you approach any stopped vehicle with its hazard lights flashing, not only emergency vehicles.","p":"Right. Move over or slow down."},"es":{"q":"En Iowa, ¿qué debe hacer al acercarse a cualquier vehículo detenido al lado del camino con las luces intermitentes de emergencia encendidas?","o":["Tocar la bocina y seguir a la misma velocidad","Detenerse detrás de él","Cambiar de carril o reducir la velocidad","Nada; la ley solo aplica a patrullas"],"h1":"La ley de Iowa lleva el nombre de estas dos acciones.","h2":"En Iowa usted debe cambiar de carril o reducir la velocidad al acercarse a cualquier vehículo detenido con las luces intermitentes encendidas, no solo a vehículos de emergencia.","p":"Correcto. Cambiar de carril o bajar la velocidad."},"zh":{"q":"在 Iowa，当你靠近任何一辆停在路边、开着双闪灯的车辆时，你必须做什么？","o":["按喇叭并保持速度","停在它后面","换道或减速","什么都不用做，法律只保护警车"],"h1":"Iowa 的这条法律就是用这两个动作命名的。","h2":"在 Iowa，当你靠近任何一辆停着、闪着双闪灯的车辆时，你必须换道或减速，不只是遇到急救车辆时才这样。","p":"对。换道让开或减速。"},"vi":{"q":"Ở Iowa, bạn phải làm gì khi đến gần bất kỳ xe nào đang dừng bên đường và bật đèn khẩn cấp?","o":["Bấm còi và giữ tốc độ","Dừng lại phía sau xe đó","Đổi làn hoặc chạy chậm lại","Không làm gì; luật chỉ áp dụng cho xe cảnh sát"],"h1":"Luật của Iowa được đặt tên theo hai hành động này.","h2":"Ở Iowa, bạn phải đổi làn hoặc chạy chậm lại khi đến gần bất kỳ xe nào đang dừng và nhấp nháy đèn khẩn cấp, không chỉ xe cấp cứu.","p":"Đúng. Tránh sang làn khác hoặc chạy chậm lại."},"tl":{"q":"Sa Iowa, ano ang dapat mong gawin kapag papalapit ka sa anumang nakahintong sasakyan sa gilid ng daan na nakabukas ang hazard lights?","o":["Bumusina at panatilihin ang bilis","Huminto sa likod nito","Lumipat ng lane o magdahan-dahan","Wala; para lamang sa sasakyan ng pulis ang batas"],"h1":"Ipinangalan ang batas ng Iowa sa dalawang aksyong ito.","h2":"Sa Iowa, dapat kang lumipat ng lane o magdahan-dahan kapag papalapit ka sa anumang nakahintong sasakyan na kumikislap ang hazard lights, hindi lamang sa mga emergency vehicle.","p":"Tama. Lumipat ng lane o magdahan-dahan."},"ar":{"q":"في Iowa، ماذا يجب أن تفعل عندما تقترب من أي سيارة متوقفة على جانب الطريق وأضواء التحذير فيها مشتعلة؟","o":["استخدم البوق وحافظ على سرعتك","توقف خلفها","غيّر المسار أو خفّف السرعة","لا شيء؛ القانون يشمل سيارات الشرطة فقط"],"h1":"قانون Iowa مسمّى باسم هذين الفعلين.","h2":"في Iowa يجب أن تغيّر المسار أو تخفّف السرعة عندما تقترب من أي سيارة متوقفة وأضواء التحذير فيها تومض، وليس فقط سيارات الطوارئ.","p":"صحيح. ابتعد إلى مسار آخر أو خفّف السرعة."},"ref":{"doc":"IA","page":22}},{"id":"ia-018","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, a school bus stops with its stop arm out on a road with two or more lanes in each direction. You come from the opposite direction. What must you do?","o":["Stop until the arm is pulled in","You do not have to stop, but watch for children","Stop only if children are crossing","Stop and wait for the driver's signal"],"h1":"The road is wide enough to separate the two directions.","h2":"On an Iowa road with two or more lanes in each direction, traffic coming from the opposite direction does not have to stop for a school bus, but should still watch for children.","p":"Right. Oncoming traffic on a wide road may pass with care."},"es":{"q":"En Iowa, un autobús escolar se detiene con el brazo de alto extendido en un camino con dos o más carriles en cada sentido. Usted viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que recojan el brazo","No tiene que detenerse, pero esté atento a los niños","Detenerse solo si hay niños cruzando","Detenerse y esperar la señal del chofer"],"h1":"El camino es lo bastante ancho para separar los dos sentidos.","h2":"En un camino de Iowa con dos o más carriles en cada sentido, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar, pero debe estar atento a los niños.","p":"Correcto. En un camino ancho, el tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 Iowa，一辆校车在每个方向有两条或更多车道的路上停下，伸出了停车臂。你从对面方向开过来。你必须做什么？","o":["停车，直到停车臂收回","你不用停车，但要注意小孩","只有在小孩过马路时才停车","停车并等司机的手势"],"h1":"这条路够宽，可以把两个方向分开。","h2":"在 Iowa 每个方向有两条或更多车道的路上，从对面方向来的车不用为校车停车，但仍然要注意小孩。","p":"对。在宽的路上，对面来的车可以小心地开过去。"},"vi":{"q":"Ở Iowa, một xe buýt trường học dừng lại và giơ tay báo dừng (stop arm) trên đường có hai làn trở lên mỗi chiều. Bạn đi từ chiều ngược lại. Bạn phải làm gì?","o":["Dừng lại cho đến khi tay báo dừng thu vào","Bạn không phải dừng, nhưng hãy để ý trẻ em","Chỉ dừng nếu trẻ em đang băng qua đường","Dừng lại và chờ tài xế ra hiệu"],"h1":"Con đường đủ rộng để tách hai chiều xe.","h2":"Trên đường ở Iowa có hai làn trở lên mỗi chiều, xe đi từ chiều ngược lại không phải dừng cho xe buýt trường học, nhưng vẫn phải để ý trẻ em.","p":"Đúng. Xe chiều ngược lại trên đường rộng có thể đi qua cẩn thận."},"tl":{"q":"Sa Iowa, huminto ang isang school bus na nakalabas ang stop arm sa daang may dalawa o higit pang lane sa bawat direksyon. Galing ka sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang maibalik ang stop arm","Hindi mo kailangang huminto, pero mag-ingat sa mga bata","Huminto lamang kung may mga batang tumatawid","Huminto at hintayin ang senyas ng drayber"],"h1":"Sapat ang lapad ng daan para paghiwalayin ang dalawang direksyon.","h2":"Sa daan sa Iowa na may dalawa o higit pang lane sa bawat direksyon, ang trapikong galing sa kabilang direksyon ay hindi kailangang huminto para sa school bus, pero dapat pa ring mag-ingat sa mga bata.","p":"Tama. Ang trapiko mula sa kabilang direksyon sa malapad na daan ay maaaring dumaan nang maingat."},"ar":{"q":"في Iowa، توقفت حافلة مدرسية وذراع التوقف (stop arm) ممدودة على طريق فيه مساران أو أكثر في كل اتجاه. أنت قادم من الاتجاه المعاكس. ماذا يجب أن تفعل؟","o":["توقف حتى تُسحب الذراع","ليس عليك أن تتوقف، لكن انتبه للأطفال","توقف فقط إذا كان الأطفال يعبرون","توقف وانتظر إشارة السائق"],"h1":"الطريق واسع بما يكفي ليفصل بين الاتجاهين.","h2":"على طريق في Iowa فيه مساران أو أكثر في كل اتجاه، ليس على السيارات القادمة من الاتجاه المعاكس أن تتوقف للحافلة المدرسية، لكن يجب أن تنتبه للأطفال.","p":"صحيح. السيارات القادمة من الاتجاه المعاكس على طريق واسع يمكنها المرور بحذر."},"ref":{"doc":"IA","page":20}},{"id":"ia-019","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, on a road with three lanes or fewer, who must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers facing the bus","Only drivers in the turning lane","Every vehicle, from both directions"],"h1":"On a narrow road, nobody gets past.","h2":"On an Iowa road with three lanes or fewer, every vehicle from both directions, including turning lanes, must stop for a school bus with flashing red lights.","p":"Right. Everyone stops on a narrow road."},"es":{"q":"En Iowa, en un camino de tres carriles o menos, ¿quién debe detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los conductores de frente al autobús","Solo los conductores en el carril de giro","Todos los vehículos, de los dos sentidos"],"h1":"En un camino angosto, nadie pasa.","h2":"En un camino de Iowa de tres carriles o menos, todos los vehículos de los dos sentidos, incluso los del carril de giro, deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. En un camino angosto todos se detienen."},"zh":{"q":"在 Iowa，在三条车道或更少的路上，谁必须为闪着红灯的校车停车？","o":["只有校车后面的司机","只有面对校车的司机","只有转弯车道上的司机","两个方向的所有车辆"],"h1":"在窄的路上，谁都不能开过去。","h2":"在 Iowa 三条车道或更少的路上，两个方向的所有车辆，包括转弯车道上的车，都必须为闪着红灯的校车停车。","p":"对。在窄的路上，所有人都要停。"},"vi":{"q":"Ở Iowa, trên đường có ba làn trở xuống, ai phải dừng lại cho xe buýt trường học đang nhấp nháy đèn đỏ?","o":["Chỉ xe ở phía sau xe buýt","Chỉ xe đối diện xe buýt","Chỉ xe ở làn rẽ","Mọi xe, từ cả hai chiều"],"h1":"Trên đường hẹp, không ai được đi qua.","h2":"Trên đường ở Iowa có ba làn trở xuống, mọi xe từ cả hai chiều, kể cả làn rẽ, phải dừng lại cho xe buýt trường học đang nhấp nháy đèn đỏ.","p":"Đúng. Trên đường hẹp, mọi người đều dừng."},"tl":{"q":"Sa Iowa, sa daang may tatlong lane o mas kaunti, sino ang dapat huminto para sa school bus na kumikislap ang pulang ilaw?","o":["Mga drayber lamang sa likod ng bus","Mga drayber lamang na nakaharap sa bus","Mga drayber lamang sa turning lane","Bawat sasakyan, mula sa dalawang direksyon"],"h1":"Sa makitid na daan, walang makakalampas.","h2":"Sa daan sa Iowa na may tatlong lane o mas kaunti, bawat sasakyan mula sa dalawang direksyon, kasama ang mga turning lane, ay dapat huminto para sa school bus na kumikislap ang pulang ilaw.","p":"Tama. Lahat ay humihinto sa makitid na daan."},"ar":{"q":"في Iowa، على طريق فيه ثلاثة مسارات أو أقل، من يجب أن يتوقف لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["السائقون خلف الحافلة فقط","السائقون المقابلون للحافلة فقط","السائقون في مسار الانعطاف فقط","كل السيارات، من الاتجاهين"],"h1":"على الطريق الضيق، لا أحد يمر.","h2":"على طريق في Iowa فيه ثلاثة مسارات أو أقل، يجب على كل السيارات من الاتجاهين، بما فيها مسارات الانعطاف، أن تتوقف لحافلة مدرسية أضواؤها الحمراء تومض.","p":"صحيح. الجميع يتوقف على الطريق الضيق."},"ref":{"doc":"IA","page":20}},{"id":"ia-020","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, failing to stop for a school bus when required can cost you your license for up to how long?","o":["180 days","7 days","30 days","5 years"],"h1":"It is about half a year.","h2":"In Iowa, not stopping for a school bus when the law requires it can lead to a license suspension of up to 180 days.","p":"Right. Up to 180 days."},"es":{"q":"En Iowa, ¿hasta por cuánto tiempo le pueden suspender la licencia por no detenerse ante un autobús escolar cuando la ley lo exige?","o":["180 días","7 días","30 días","5 años"],"h1":"Es más o menos medio año.","h2":"En Iowa, no detenerse ante un autobús escolar cuando la ley lo exige puede causar una suspensión de la licencia de hasta 180 días.","p":"Correcto. Hasta 180 días."},"zh":{"q":"在 Iowa，按规定应该为校车停车却没有停，最长可能会被暂停驾照多久？","o":["180 天","7 天","30 天","5 年"],"h1":"大约是半年。","h2":"在 Iowa，法律要求停车时没有为校车停车，驾照最长可能被暂停 180 天。","p":"对。最长 180 天。"},"vi":{"q":"Ở Iowa, không dừng lại cho xe buýt trường học khi luật yêu cầu có thể khiến bạn mất bằng lái tối đa bao lâu?","o":["180 ngày","7 ngày","30 ngày","5 năm"],"h1":"Khoảng nửa năm.","h2":"Ở Iowa, không dừng lại cho xe buýt trường học khi luật yêu cầu có thể bị treo bằng lái tối đa 180 ngày.","p":"Đúng. Tối đa 180 ngày."},"tl":{"q":"Sa Iowa, ang hindi paghinto para sa school bus kapag kinakailangan ay maaaring magdulot ng pagkawala ng lisensya mo nang hanggang gaano katagal?","o":["180 araw","7 araw","30 araw","5 taon"],"h1":"Mga kalahating taon ito.","h2":"Sa Iowa, ang hindi paghinto para sa school bus kapag hinihingi ng batas ay maaaring magresulta sa suspensyon ng lisensya nang hanggang 180 araw.","p":"Tama. Hanggang 180 araw."},"ar":{"q":"في Iowa، عدم التوقف لحافلة مدرسية عندما يجب ذلك يمكن أن يُفقدك رخصتك لمدة تصل إلى كم؟","o":["180 يومًا","7 أيام","30 يومًا","5 سنوات"],"h1":"هي حوالي نصف سنة.","h2":"في Iowa، عدم التوقف لحافلة مدرسية عندما يطلب القانون ذلك يمكن أن يؤدي إلى إيقاف الرخصة لمدة تصل إلى 180 يومًا.","p":"صحيح. حتى 180 يومًا."},"ref":{"doc":"IA","page":20}},{"id":"ia-021","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, what is the highest posted speed limit on rural interstate highways?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Iowa's rural interstates are lower than some western states.","h2":"The highest posted speed limit in Iowa is 70 mph, on rural interstate highways.","p":"Right. 70 mph on rural interstates."},"es":{"q":"En Iowa, ¿cuál es el límite de velocidad más alto en las autopistas interestatales rurales?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Las interestatales rurales de Iowa tienen un límite más bajo que algunos estados del oeste.","h2":"El límite de velocidad más alto en Iowa es de 70 millas por hora, en las autopistas interestatales rurales.","p":"Correcto. 70 mph en interestatales rurales."},"zh":{"q":"在 Iowa，乡村州际高速公路上标示的最高限速是多少？","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Iowa 乡村州际公路的限速比一些西部州低。","h2":"Iowa 标示的最高限速是 70 mph，在乡村州际高速公路上。","p":"对。乡村州际公路是 70 mph。"},"vi":{"q":"Ở Iowa, tốc độ tối đa cao nhất được ghi trên biển ở xa lộ liên tiểu bang vùng nông thôn là bao nhiêu?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Xa lộ liên tiểu bang vùng nông thôn ở Iowa có tốc độ thấp hơn một số tiểu bang miền tây.","h2":"Tốc độ tối đa cao nhất được ghi trên biển ở Iowa là 70 mph, trên xa lộ liên tiểu bang vùng nông thôn.","p":"Đúng. 70 mph trên xa lộ liên tiểu bang vùng nông thôn."},"tl":{"q":"Sa Iowa, ano ang pinakamataas na nakapaskil na speed limit sa mga rural interstate highway?","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"Mas mababa ang mga rural interstate ng Iowa kaysa sa ilang estado sa kanluran.","h2":"Ang pinakamataas na nakapaskil na speed limit sa Iowa ay 70 mph, sa mga rural interstate highway.","p":"Tama. 70 mph sa mga rural interstate."},"ar":{"q":"في Iowa، ما أعلى حد سرعة مكتوب على اللافتات على الطرق السريعة بين الولايات في المناطق الريفية؟","o":["60 mph","65 mph","70 mph","75 mph"],"h1":"الطرق السريعة الريفية في Iowa أقل من بعض الولايات الغربية.","h2":"أعلى حد سرعة مكتوب على اللافتات في Iowa هو 70 mph، على الطرق السريعة بين الولايات في المناطق الريفية.","p":"صحيح. 70 mph على الطرق السريعة الريفية."},"ref":{"doc":"IA","page":42}},{"id":"ia-022","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, unless a sign says otherwise, what is the speed limit in a business district?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Business districts are busy with people on foot.","h2":"Unless a sign shows a different limit, the speed limit in an Iowa business district is 20 mph.","p":"Right. 20 mph in a business district."},"es":{"q":"En Iowa, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona comercial?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Las zonas comerciales tienen mucha gente a pie.","h2":"Si no hay una señal con otro límite, el límite de velocidad en una zona comercial de Iowa es de 20 millas por hora.","p":"Correcto. 20 mph en zona comercial."},"zh":{"q":"在 Iowa，如果没有标志另外说明，商业区的限速是多少？","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"商业区有很多走路的人。","h2":"在 Iowa，如果没有标志标示不同的限速，商业区的限速是 20 mph。","p":"对。商业区是 20 mph。"},"vi":{"q":"Ở Iowa, nếu không có biển báo khác, tốc độ tối đa trong khu thương mại là bao nhiêu?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Khu thương mại có nhiều người đi bộ.","h2":"Nếu không có biển báo ghi tốc độ khác, tốc độ tối đa trong khu thương mại ở Iowa là 20 mph.","p":"Đúng. 20 mph trong khu thương mại."},"tl":{"q":"Sa Iowa, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa business district?","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"Maraming taong naglalakad sa mga business district.","h2":"Maliban kung iba ang limitasyong ipinapakita ng karatula, ang speed limit sa business district sa Iowa ay 20 mph.","p":"Tama. 20 mph sa business district."},"ar":{"q":"في Iowa، ما لم تقل لافتة غير ذلك، ما حد السرعة في المنطقة التجارية؟","o":["15 mph","20 mph","30 mph","35 mph"],"h1":"المناطق التجارية مزدحمة بالمشاة.","h2":"ما لم تُظهر لافتة حدًا مختلفًا، فإن حد السرعة في المنطقة التجارية في Iowa هو 20 mph.","p":"صحيح. 20 mph في المنطقة التجارية."},"ref":{"doc":"IA","page":42}},{"id":"ia-023","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, how must a child under 6 years old ride in a car?","o":["With an adult seat belt only","On an adult's lap","In a child safety seat or booster seat","In the front seat with a seat belt"],"h1":"A seat belt alone is not enough for a child this young.","h2":"In Iowa a child under 6 years old must ride in a child safety seat or a booster seat, not just a seat belt.","p":"Right. Under 6, a safety seat or booster seat."},"es":{"q":"En Iowa, ¿cómo debe viajar en un auto un niño menor de 6 años?","o":["Solo con el cinturón de seguridad de adulto","En las piernas de un adulto","En un asiento de seguridad infantil o un asiento elevado","En el asiento delantero con cinturón"],"h1":"Para un niño tan pequeño, el cinturón solo no es suficiente.","h2":"En Iowa un niño menor de 6 años debe viajar en un asiento de seguridad infantil o en un asiento elevado, no solo con el cinturón de seguridad.","p":"Correcto. Menores de 6, asiento de seguridad o asiento elevado."},"zh":{"q":"在 Iowa，6 岁以下的儿童坐车时必须怎样乘坐？","o":["只系成人安全带","坐在大人腿上","坐在儿童安全座椅或增高座椅里","坐在前排并系安全带"],"h1":"对这么小的孩子来说，只系安全带是不够的。","h2":"在 Iowa，6 岁以下的儿童必须坐在儿童安全座椅或增高座椅里，不能只系安全带。","p":"对。6 岁以下要用安全座椅或增高座椅。"},"vi":{"q":"Ở Iowa, trẻ em dưới 6 tuổi phải ngồi trên xe như thế nào?","o":["Chỉ thắt dây an toàn của người lớn","Ngồi trên đùi người lớn","Ngồi trong ghế an toàn cho trẻ em hoặc ghế nâng","Ngồi ghế trước và thắt dây an toàn"],"h1":"Chỉ thắt dây an toàn thì không đủ cho trẻ nhỏ như vậy.","h2":"Ở Iowa, trẻ em dưới 6 tuổi phải ngồi trong ghế an toàn cho trẻ em hoặc ghế nâng, không chỉ thắt dây an toàn.","p":"Đúng. Dưới 6 tuổi phải ngồi ghế an toàn hoặc ghế nâng."},"tl":{"q":"Sa Iowa, paano dapat sumakay sa kotse ang batang wala pang 6 na taong gulang?","o":["Naka-seat belt na pang-adulto lamang","Nakakandong sa isang adulto","Nasa child safety seat o booster seat","Nasa upuan sa harap na naka-seat belt"],"h1":"Hindi sapat ang seat belt lamang para sa ganito kabatang bata.","h2":"Sa Iowa, ang batang wala pang 6 na taong gulang ay dapat nakasakay sa child safety seat o booster seat, hindi lang naka-seat belt.","p":"Tama. Kapag wala pang 6, safety seat o booster seat."},"ar":{"q":"في ولاية Iowa، كيف يجب أن يركب الطفل الذي عمره أقل من 6 سنوات في السيارة؟","o":["بحزام أمان الكبار فقط","في حضن شخص بالغ","في مقعد أمان للأطفال أو مقعد رافع","في المقعد الأمامي مع حزام الأمان"],"h1":"حزام الأمان وحده لا يكفي لطفل بهذا العمر الصغير.","h2":"في Iowa يجب أن يركب الطفل الذي عمره أقل من 6 سنوات في مقعد أمان للأطفال أو مقعد رافع، وليس بحزام الأمان فقط.","p":"صحيح. أقل من 6 سنوات: مقعد أمان أو مقعد رافع."},"ref":{"doc":"IA","page":35}},{"id":"ia-024","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, what happens if you refuse a breath test when a police officer asks?","o":["Your license is revoked for one year and you pay at least $1,250","Nothing, if you were not drinking","You get a warning the first time","Your license is suspended for one week"],"h1":"Refusing is treated more harshly than failing the test.","h2":"In Iowa, refusing a breath test means your license is revoked for one year and you must pay a fine of at least $1,250.","p":"Right. One year without a license and a fine of at least $1,250."},"es":{"q":"En Iowa, ¿qué pasa si usted se niega a una prueba de aliento cuando un policía se la pide?","o":["Le revocan la licencia por un año y paga al menos $1,250","Nada, si usted no había bebido","Recibe una advertencia la primera vez","Le suspenden la licencia por una semana"],"h1":"Negarse se castiga más fuerte que no pasar la prueba.","h2":"En Iowa, negarse a una prueba de aliento significa que le revocan la licencia por un año y debe pagar una multa de al menos $1,250.","p":"Correcto. Un año sin licencia y una multa de al menos $1,250."},"zh":{"q":"在 Iowa，如果警察要求你做呼气测试而你拒绝，会怎样？","o":["你的驾照被吊销一年，并且至少要付 $1,250","如果你没喝酒，就没事","第一次只会得到警告","你的驾照被暂停一周"],"h1":"拒绝测试的处罚比测试没通过还要重。","h2":"在 Iowa，拒绝做呼气测试，你的驾照会被吊销一年，并且至少要付 $1,250 的罚款。","p":"对。一年不能有驾照，罚款至少 $1,250。"},"vi":{"q":"Ở Iowa, điều gì xảy ra nếu bạn từ chối kiểm tra hơi thở khi cảnh sát yêu cầu?","o":["Bằng lái của bạn bị thu hồi một năm và bạn trả ít nhất $1,250","Không sao cả, nếu bạn không uống rượu","Lần đầu bạn chỉ bị cảnh cáo","Bằng lái của bạn bị đình chỉ một tuần"],"h1":"Từ chối bị xử phạt nặng hơn là không đạt bài kiểm tra.","h2":"Ở Iowa, từ chối kiểm tra hơi thở nghĩa là bằng lái của bạn bị thu hồi một năm và bạn phải trả tiền phạt ít nhất $1,250.","p":"Đúng. Một năm không có bằng lái và tiền phạt ít nhất $1,250."},"tl":{"q":"Sa Iowa, ano ang mangyayari kung tumanggi ka sa breath test kapag hiniling ng pulis?","o":["Babawiin ang iyong lisensya nang isang taon at magbabayad ka ng hindi bababa sa $1,250","Wala, kung hindi ka uminom","Babala lang sa unang pagkakataon","Masususpinde ang iyong lisensya nang isang linggo"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test.","h2":"Sa Iowa, kapag tumanggi ka sa breath test, babawiin ang iyong lisensya nang isang taon at magbabayad ka ng multa na hindi bababa sa $1,250.","p":"Tama. Isang taon na walang lisensya at multa na hindi bababa sa $1,250."},"ar":{"q":"في ولاية Iowa، ماذا يحدث إذا رفضت اختبار التنفس عندما يطلبه منك ضابط الشرطة؟","o":["تُلغى رخصتك لمدة سنة وتدفع $1,250 على الأقل","لا شيء، إذا لم تكن قد شربت","تحصل على إنذار في المرة الأولى","تُعلَّق رخصتك لمدة أسبوع"],"h1":"الرفض يُعاقَب عليه أشد من الرسوب في الاختبار.","h2":"في Iowa، رفض اختبار التنفس يعني أن رخصتك تُلغى لمدة سنة ويجب أن تدفع غرامة لا تقل عن $1,250.","p":"صحيح. سنة بلا رخصة وغرامة لا تقل عن $1,250."},"ref":{"doc":"IA","page":37}},{"id":"ia-025","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, a crash causes injury or more than $1,500 in damage. How soon must it be reported to the police?","o":["Within 30 days","Within 10 days","Only if your insurance asks","Within 72 hours"],"h1":"The deadline is counted in hours, not days.","h2":"In Iowa a crash with injury, death or more than $1,500 in property damage must be reported to the police within 72 hours, or you can lose your license.","p":"Right. Report it within 72 hours."},"es":{"q":"En Iowa, un choque causa heridos o más de $1,500 en daños. ¿En cuánto tiempo hay que reportarlo a la policía?","o":["En 30 días","En 10 días","Solo si su seguro lo pide","En 72 horas"],"h1":"El plazo se cuenta en horas, no en días.","h2":"En Iowa un choque con heridos, muertos o más de $1,500 en daños a la propiedad se debe reportar a la policía en 72 horas, o usted puede perder su licencia.","p":"Correcto. Hay que reportarlo en 72 horas."},"zh":{"q":"在 Iowa，一起车祸造成了人员受伤或超过 $1,500 的损失。必须在多长时间内向警察报告？","o":["30 天内","10 天内","只有保险公司要求时才报告","72 小时内"],"h1":"期限是按小时算的，不是按天算。","h2":"在 Iowa，造成受伤、死亡或超过 $1,500 财产损失的车祸，必须在 72 小时内向警察报告，否则你可能失去驾照。","p":"对。要在 72 小时内报告。"},"vi":{"q":"Ở Iowa, một vụ tai nạn gây thương tích hoặc thiệt hại hơn $1,500. Phải báo cho cảnh sát trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Chỉ khi công ty bảo hiểm yêu cầu","Trong vòng 72 giờ"],"h1":"Thời hạn được tính bằng giờ, không phải bằng ngày.","h2":"Ở Iowa, tai nạn gây thương tích, tử vong hoặc thiệt hại tài sản hơn $1,500 phải được báo cho cảnh sát trong vòng 72 giờ, nếu không bạn có thể bị mất bằng lái.","p":"Đúng. Báo cáo trong vòng 72 giờ."},"tl":{"q":"Sa Iowa, may banggaan na nagdulot ng pinsala sa tao o higit sa $1,500 na sira. Gaano kabilis ito dapat i-report sa pulis?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Kung hihilingin lang ng iyong insurance","Sa loob ng 72 oras"],"h1":"Binibilang ang deadline sa oras, hindi sa araw.","h2":"Sa Iowa, ang banggaan na may nasaktan, namatay o higit sa $1,500 na sira sa ari-arian ay dapat i-report sa pulis sa loob ng 72 oras, o maaaring mawala ang iyong lisensya.","p":"Tama. I-report ito sa loob ng 72 oras."},"ar":{"q":"في ولاية Iowa، تسبب حادث في إصابة أو في أضرار تزيد على $1,500. خلال كم من الوقت يجب إبلاغ الشرطة عنه؟","o":["خلال 30 يومًا","خلال 10 أيام","فقط إذا طلبت شركة التأمين","خلال 72 ساعة"],"h1":"المهلة تُحسب بالساعات، لا بالأيام.","h2":"في Iowa يجب إبلاغ الشرطة عن أي حادث فيه إصابة أو وفاة أو أضرار في الممتلكات تزيد على $1,500 خلال 72 ساعة، وإلا قد تفقد رخصتك.","p":"صحيح. أبلغ عنه خلال 72 ساعة."},"ref":{"doc":"IA","page":63}},{"id":"ia-026","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, what is the minimum speed on the interstate system?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Vehicles that cannot keep up with this speed are not allowed on the interstate.","h2":"On Iowa's interstate system the minimum speed is 40 mph, and vehicles that cannot go that fast are not allowed there.","p":"Right. The interstate minimum is 40 mph."},"es":{"q":"En Iowa, ¿cuál es la velocidad mínima en las autopistas interestatales?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Los vehículos que no pueden mantener esta velocidad no pueden usar la interestatal.","h2":"En las autopistas interestatales de Iowa la velocidad mínima es de 40 millas por hora, y los vehículos que no pueden ir así de rápido no pueden usarlas.","p":"Correcto. La mínima en la interestatal es 40 mph."},"zh":{"q":"在 Iowa，州际公路系统上的最低速度是多少？","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"达不到这个速度的车辆不准上州际公路。","h2":"在 Iowa 的州际公路系统上，最低速度是 40 mph，开不到这么快的车辆不准在那里行驶。","p":"对。州际公路最低速度是 40 mph。"},"vi":{"q":"Ở Iowa, tốc độ tối thiểu trên hệ thống xa lộ liên bang (interstate) là bao nhiêu?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Xe không chạy kịp tốc độ này thì không được đi trên xa lộ liên bang.","h2":"Trên hệ thống xa lộ liên bang ở Iowa, tốc độ tối thiểu là 40 mph, và xe không thể chạy nhanh như vậy thì không được đi ở đó.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang là 40 mph."},"tl":{"q":"Sa Iowa, ano ang pinakamababang bilis sa interstate system?","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"Hindi pinapayagan sa interstate ang mga sasakyang hindi makaabot sa bilis na ito.","h2":"Sa interstate system ng Iowa, ang pinakamababang bilis ay 40 mph, at hindi pinapayagan doon ang mga sasakyang hindi makatakbo nang ganoon kabilis.","p":"Tama. Ang pinakamababang bilis sa interstate ay 40 mph."},"ar":{"q":"في ولاية Iowa، ما الحد الأدنى للسرعة على شبكة الطرق السريعة بين الولايات (interstate)؟","o":["30 mph","40 mph","50 mph","55 mph"],"h1":"المركبات التي لا تستطيع السير بهذه السرعة غير مسموح لها على الطريق السريع بين الولايات.","h2":"على شبكة الطرق السريعة بين الولايات في Iowa الحد الأدنى للسرعة هو 40 mph، والمركبات التي لا تستطيع السير بهذه السرعة غير مسموح لها هناك.","p":"صحيح. الحد الأدنى على الطريق السريع بين الولايات هو 40 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-027","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, besides from sunset to sunrise, when does the law require your headlights to be on?","o":["Only on the interstate","Only when it is raining","When you can see 500 feet or less","When you drive more than 50 miles"],"h1":"Think of fog, heavy rain or snow.","h2":"Iowa law requires both headlights from sunset to sunrise and whenever you can see only 500 feet or less, such as in fog, heavy rain or snow.","p":"Right. Headlights on when visibility is 500 feet or less."},"es":{"q":"En Iowa, además de desde la puesta hasta la salida del sol, ¿cuándo exige la ley tener las luces delanteras encendidas?","o":["Solo en la interestatal","Solo cuando llueve","Cuando puede ver a 500 pies o menos","Cuando maneja más de 50 millas"],"h1":"Piense en niebla, lluvia fuerte o nieve.","h2":"La ley de Iowa exige las dos luces delanteras desde la puesta hasta la salida del sol y siempre que solo pueda ver a 500 pies o menos, por ejemplo con niebla, lluvia fuerte o nieve.","p":"Correcto. Luces encendidas cuando la visibilidad es de 500 pies o menos."},"zh":{"q":"在 Iowa，除了从日落到日出以外，法律还要求你在什么时候打开车头灯？","o":["只在州际公路上","只在下雨时","当你只能看清 500 英尺或更近时","当你开车超过 50 英里时"],"h1":"想一想大雾、大雨或下雪的时候。","h2":"Iowa 法律要求从日落到日出要打开两个车头灯，而且只要你只能看清 500 英尺或更近（比如大雾、大雨或下雪时）也要打开。","p":"对。能见度在 500 英尺或更近时要开车头灯。"},"vi":{"q":"Ở Iowa, ngoài thời gian từ lúc mặt trời lặn đến lúc mặt trời mọc, luật còn bắt bạn bật đèn pha khi nào?","o":["Chỉ khi đi trên xa lộ liên bang","Chỉ khi trời mưa","Khi bạn chỉ nhìn thấy được 500 feet hoặc ít hơn","Khi bạn lái xe hơn 50 dặm"],"h1":"Hãy nghĩ đến sương mù, mưa lớn hoặc tuyết.","h2":"Luật Iowa bắt bật cả hai đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc, và bất cứ khi nào bạn chỉ nhìn thấy được 500 feet hoặc ít hơn, như khi có sương mù, mưa lớn hoặc tuyết.","p":"Đúng. Bật đèn pha khi tầm nhìn từ 500 feet trở xuống."},"tl":{"q":"Sa Iowa, bukod sa mula paglubog hanggang pagsikat ng araw, kailan pa iniuutos ng batas na nakabukas ang iyong headlights?","o":["Sa interstate lamang","Kapag umuulan lamang","Kapag 500 talampakan o mas maikli lang ang kaya mong makita","Kapag nagmamaneho ka nang higit sa 50 milya"],"h1":"Isipin ang hamog, malakas na ulan o niyebe.","h2":"Iniuutos ng batas ng Iowa na nakabukas ang dalawang headlights mula paglubog hanggang pagsikat ng araw at tuwing 500 talampakan o mas maikli lang ang kaya mong makita, gaya ng sa hamog, malakas na ulan o niyebe.","p":"Tama. Buksan ang headlights kapag 500 talampakan o mas maikli ang nakikita."},"ar":{"q":"في ولاية Iowa، إلى جانب الفترة من غروب الشمس إلى شروقها، متى يُلزمك القانون بتشغيل المصابيح الأمامية؟","o":["على الطريق السريع بين الولايات فقط","عندما تمطر فقط","عندما لا تستطيع الرؤية إلا لمسافة 500 قدم أو أقل","عندما تقود أكثر من 50 ميلًا"],"h1":"فكّر في الضباب أو المطر الغزير أو الثلج.","h2":"قانون Iowa يُلزمك بتشغيل المصباحين الأماميين من غروب الشمس إلى شروقها، وكلما كانت رؤيتك 500 قدم أو أقل، مثل وقت الضباب أو المطر الغزير أو الثلج.","p":"صحيح. شغّل المصابيح الأمامية عندما تكون الرؤية 500 قدم أو أقل."},"ref":{"doc":"IA","page":49}},{"id":"ia-028","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, how close to a fire hydrant may you not park?","o":["Closer than 15 feet","Closer than 5 feet","Closer than 20 feet","Closer than 50 feet"],"h1":"In Iowa this distance is shorter than in many other states.","h2":"In Iowa, you may not park closer than five feet from a fire hydrant, or in a marked hydrant red zone.","p":"Right. In Iowa, stay at least five feet from a fire hydrant."},"es":{"q":"En Iowa, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 15 pies","A menos de 5 pies","A menos de 20 pies","A menos de 50 pies"],"h1":"En Iowa esta distancia es más corta que en muchos otros estados.","h2":"En Iowa, no puede estacionarse a menos de cinco pies de un hidrante, ni en una zona roja marcada para hidrantes.","p":"Correcto. En Iowa, quédese al menos a cinco pies de un hidrante."},"zh":{"q":"在 Iowa，离消防栓多近的地方不能停车？","o":["少于 15 英尺","少于 5 英尺","少于 20 英尺","少于 50 英尺"],"h1":"在 Iowa，这个距离比很多其他州短。","h2":"在 Iowa，你不能在离消防栓不到 5 英尺的地方停车，也不能停在标出的消防栓红色区域内。","p":"对。在 Iowa，要离消防栓至少 5 英尺。"},"vi":{"q":"Ở Iowa, bạn không được đậu xe gần trụ nước cứu hỏa hơn bao nhiêu?","o":["Gần hơn 15 feet","Gần hơn 5 feet","Gần hơn 20 feet","Gần hơn 50 feet"],"h1":"Ở Iowa, khoảng cách này ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Iowa, bạn không được đậu xe gần trụ nước cứu hỏa hơn 5 feet, hoặc trong vùng sơn đỏ có đánh dấu quanh trụ nước.","p":"Đúng. Ở Iowa, hãy đậu cách trụ nước cứu hỏa ít nhất 5 feet."},"tl":{"q":"Sa Iowa, gaano kalapit sa fire hydrant ang hindi ka puwedeng pumarada?","o":["Mas malapit sa 15 talampakan","Mas malapit sa 5 talampakan","Mas malapit sa 20 talampakan","Mas malapit sa 50 talampakan"],"h1":"Sa Iowa, mas maikli ang layong ito kaysa sa maraming ibang estado.","h2":"Sa Iowa, hindi ka puwedeng pumarada nang mas malapit sa 5 talampakan mula sa fire hydrant, o sa may markang pulang zone ng hydrant.","p":"Tama. Sa Iowa, lumayo nang hindi bababa sa 5 talampakan mula sa fire hydrant."},"ar":{"q":"في Iowa، ما المسافة من صنبور إطفاء الحريق التي لا يجوز أن تركن أقرب منها؟","o":["أقرب من 15 قدمًا","أقرب من 5 أقدام","أقرب من 20 قدمًا","أقرب من 50 قدمًا"],"h1":"في Iowa هذه المسافة أقصر مما هي عليه في كثير من الولايات الأخرى.","h2":"في Iowa لا يجوز لك أن تركن على مسافة أقل من 5 أقدام من صنبور إطفاء الحريق، ولا في المنطقة الحمراء المحددة حول الصنبور.","p":"صحيح. في Iowa ابقَ على بعد 5 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"IA","page":21}},{"id":"ia-029","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, you must park on a street with a curb. How close to the curb should your car be?","o":["Within 3 feet","Within 24 inches","Within 30 inches","Within 18 inches"],"h1":"It is less than half a yard.","h2":"In Iowa, when you park on a street with a curb, your car should be within 18 inches of the curb.","p":"Right. Park within 18 inches of the curb."},"es":{"q":"En Iowa, debe estacionarse en una calle con bordillo. ¿Qué tan cerca del bordillo debe quedar su auto?","o":["A no más de 3 pies","A no más de 24 pulgadas","A no más de 30 pulgadas","A no más de 18 pulgadas"],"h1":"Es menos de media yarda.","h2":"En Iowa, al estacionarse en una calle con bordillo, su auto debe quedar a no más de 18 pulgadas del bordillo.","p":"Correcto. Estaciónese a no más de 18 pulgadas del bordillo."},"zh":{"q":"在 Iowa，你要在有路缘的街上停车。你的车应该离路缘多近？","o":["3 英尺以内","24 英寸以内","30 英寸以内","18 英寸以内"],"h1":"这个距离不到半码。","h2":"在 Iowa，在有路缘的街上停车时，你的车应该在离路缘 18 英寸以内。","p":"对。停车时要在离路缘 18 英寸以内。"},"vi":{"q":"Ở Iowa, bạn phải đậu xe trên một con đường có lề. Xe của bạn nên cách lề bao xa?","o":["Trong vòng 3 feet","Trong vòng 24 inch","Trong vòng 30 inch","Trong vòng 18 inch"],"h1":"Khoảng cách này chưa tới nửa yard.","h2":"Ở Iowa, khi bạn đậu xe trên con đường có lề, xe của bạn nên cách lề không quá 18 inch.","p":"Đúng. Hãy đậu xe cách lề không quá 18 inch."},"tl":{"q":"Sa Iowa, kailangan mong pumarada sa kalyeng may gilid (curb). Gaano dapat kalapit ang kotse mo sa curb?","o":["Sa loob ng 3 talampakan","Sa loob ng 24 pulgada","Sa loob ng 30 pulgada","Sa loob ng 18 pulgada"],"h1":"Kulang ito sa kalahating yarda.","h2":"Sa Iowa, kapag pumarada ka sa kalyeng may curb, dapat nasa loob ng 18 pulgada mula sa curb ang kotse mo.","p":"Tama. Pumarada sa loob ng 18 pulgada mula sa curb."},"ar":{"q":"في Iowa، عليك أن تركن في شارع له رصيف. كم يجب أن تكون سيارتك قريبة من الرصيف؟","o":["في حدود 3 أقدام","في حدود 24 بوصة","في حدود 30 بوصة","في حدود 18 بوصة"],"h1":"المسافة أقل من نصف ياردة.","h2":"في Iowa، عندما تركن في شارع له رصيف، يجب أن تكون سيارتك على بعد 18 بوصة أو أقل من الرصيف.","p":"صحيح. اركن على بعد 18 بوصة أو أقل من الرصيف."},"ref":{"doc":"IA","page":21}},{"id":"ia-030","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, a passenger has an open can of beer in the car. What can happen?","o":["The driver and each passenger can be fined up to $200","Only the driver can be fined, up to $50","Nothing, if the driver is not drinking","The car is towed, but there is no fine"],"h1":"The open container law applies to everyone in the car, not only the driver.","h2":"In Iowa, an open container of alcohol in a car is a simple misdemeanor, with a fine of up to $200 for the driver and for each passenger.","p":"Right. The driver and every passenger can each be fined up to $200."},"es":{"q":"En Iowa, un pasajero tiene una lata de cerveza abierta en el auto. ¿Qué puede pasar?","o":["El conductor y cada pasajero pueden recibir una multa de hasta $200","Solo el conductor puede recibir una multa, de hasta $50","Nada, si el conductor no está bebiendo","Se remolca el auto, pero no hay multa"],"h1":"La ley de envases abiertos se aplica a todos en el auto, no solo al conductor.","h2":"En Iowa, llevar un envase abierto de alcohol en un auto es un delito menor, con una multa de hasta $200 para el conductor y para cada pasajero.","p":"Correcto. El conductor y cada pasajero pueden recibir una multa de hasta $200."},"zh":{"q":"在 Iowa，车上一名乘客拿着一罐已打开的啤酒。会发生什么？","o":["司机和每名乘客都可能被罚款，最多 $200","只有司机会被罚款，最多 $50","如果司机没有喝酒，就没事","车会被拖走，但不会罚款"],"h1":"开口容器法适用于车上的每个人，不只是司机。","h2":"在 Iowa，车里有打开的酒类容器属于轻罪，司机和每名乘客都可能被罚款，最多 $200。","p":"对。司机和每名乘客都可能各被罚款最多 $200。"},"vi":{"q":"Ở Iowa, một hành khách có một lon bia đã mở trong xe. Điều gì có thể xảy ra?","o":["Tài xế và mỗi hành khách có thể bị phạt đến $200","Chỉ tài xế bị phạt, đến $50","Không sao cả, nếu tài xế không uống","Xe bị kéo đi, nhưng không bị phạt tiền"],"h1":"Luật về đồ chứa rượu đã mở áp dụng cho mọi người trong xe, không chỉ tài xế.","h2":"Ở Iowa, có đồ chứa rượu đã mở trong xe là một tội nhẹ, với tiền phạt đến $200 cho tài xế và cho mỗi hành khách.","p":"Đúng. Tài xế và mỗi hành khách đều có thể bị phạt đến $200."},"tl":{"q":"Sa Iowa, may bukas na lata ng beer ang isang pasahero sa kotse. Ano ang puwedeng mangyari?","o":["Puwedeng pagmultahin ang driver at bawat pasahero nang hanggang $200","Ang driver lang ang puwedeng pagmultahin, hanggang $50","Wala, kung hindi umiinom ang driver","Hihilahin ang kotse, pero walang multa"],"h1":"Ang batas sa bukas na lalagyan ng alak ay para sa lahat ng nasa kotse, hindi lang sa driver.","h2":"Sa Iowa, ang bukas na lalagyan ng alak sa kotse ay isang simple misdemeanor, na may multang hanggang $200 para sa driver at para sa bawat pasahero.","p":"Tama. Puwedeng pagmultahin ang driver at bawat pasahero nang hanggang $200 bawat isa."},"ar":{"q":"في Iowa، مع أحد الركاب علبة بيرة مفتوحة في السيارة. ماذا يمكن أن يحدث؟","o":["يمكن تغريم السائق وكل راكب حتى $200","يمكن تغريم السائق فقط، حتى $50","لا شيء، إذا كان السائق لا يشرب","تُسحب السيارة، لكن بلا غرامة"],"h1":"قانون الحاوية المفتوحة ينطبق على كل من في السيارة، وليس على السائق فقط.","h2":"في Iowa، وجود حاوية كحول مفتوحة في السيارة مخالفة بسيطة (simple misdemeanor)، وغرامتها تصل إلى $200 للسائق ولكل راكب.","p":"صحيح. يمكن تغريم السائق وكل راكب حتى $200 لكل واحد."},"ref":{"doc":"IA","page":37}},{"id":"ia-031","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, you may not pass another vehicle within how many feet of an intersection or a railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Iowa, you may not pass another vehicle within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Iowa, ¿a cuántos pies de una intersección o de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es más o menos el largo de seis o siete autos.","h2":"En Iowa, no puede rebasar a otro vehículo a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de una intersección o cruce de ferrocarril."},"zh":{"q":"在 Iowa，在离路口或铁路道口多少英尺以内，你不能超车？","o":["25 英尺","50 英尺","100 英尺","500 英尺"],"h1":"大约是六七辆车的长度。","h2":"在 Iowa，在离路口或铁路道口 100 英尺以内，你不能超越其他车辆。","p":"对。在离路口或铁路道口 100 英尺以内不能超车。"},"vi":{"q":"Ở Iowa, bạn không được vượt xe khác trong vòng bao nhiêu feet tính từ giao lộ hoặc chỗ băng qua đường sắt?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe.","h2":"Ở Iowa, bạn không được vượt xe khác trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt.","p":"Đúng. Không được vượt xe trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt."},"tl":{"q":"Sa Iowa, hindi ka puwedeng mag-overtake sa ibang sasakyan sa loob ng ilang talampakan mula sa intersection o tawiran ng riles?","o":["25 talampakan","50 talampakan","100 talampakan","500 talampakan"],"h1":"Halos kasinghaba ito ng anim o pitong kotse.","h2":"Sa Iowa, hindi ka puwedeng mag-overtake sa ibang sasakyan sa loob ng 100 talampakan mula sa intersection o tawiran ng riles.","p":"Tama. Bawal mag-overtake sa loob ng 100 talampakan mula sa intersection o tawiran ng riles."},"ar":{"q":"في Iowa، لا يجوز لك تجاوز مركبة أخرى ضمن كم قدمًا من تقاطع أو معبر سكة حديدية؟","o":["25 قدمًا","50 قدمًا","100 قدم","500 قدم"],"h1":"إنها تقريبًا طول ست أو سبع سيارات.","h2":"في Iowa لا يجوز لك تجاوز مركبة أخرى ضمن 100 قدم من تقاطع أو معبر سكة حديدية.","p":"صحيح. لا تجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديدية."},"ref":{"doc":"IA","page":46}},{"id":"ia-032","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, the speed limit is 55 mph. At least how far before a turn must you start signaling?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"On faster roads, Iowa asks for a longer warning than on slow streets.","h2":"In Iowa you must signal at least 300 feet before a turn when the speed limit is over 45 mph, and at least 100 feet when it is 45 mph or less.","p":"Right. Over 45 mph, signal at least 300 feet ahead."},"es":{"q":"En Iowa, el límite de velocidad es de 55 mph. ¿Con cuánta anticipación como mínimo debe empezar a señalizar antes de girar?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"En caminos más rápidos, Iowa pide un aviso más largo que en calles lentas.","h2":"En Iowa usted debe señalizar por lo menos 300 pies antes de girar cuando el límite es de más de 45 mph, y por lo menos 100 pies cuando es de 45 mph o menos.","p":"Correcto. Con más de 45 mph, señalice por lo menos 300 pies antes."},"zh":{"q":"在 Iowa，限速是 55 mph。你至少要在转弯前多远开始打方向灯？","o":["50 英尺","100 英尺","300 英尺","1,000 英尺"],"h1":"在车速较快的道路上，Iowa 要求比慢速街道更早提示。","h2":"在 Iowa，限速超过 45 mph 时，你必须在转弯前至少 300 英尺打方向灯；限速 45 mph 或以下时，至少 100 英尺。","p":"对。超过 45 mph 时，至少提前 300 英尺打方向灯。"},"vi":{"q":"Ở Iowa, tốc độ tối đa là 55 mph. Bạn phải bắt đầu bật đèn xi nhan ít nhất bao xa trước khi rẽ?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Trên đường chạy nhanh, Iowa yêu cầu báo trước xa hơn so với đường chạy chậm.","h2":"Ở Iowa, bạn phải bật xi nhan ít nhất 300 feet trước khi rẽ khi tốc độ tối đa trên 45 mph, và ít nhất 100 feet khi tốc độ tối đa là 45 mph hoặc thấp hơn.","p":"Đúng. Trên 45 mph, bật xi nhan ít nhất 300 feet trước khi rẽ."},"tl":{"q":"Sa Iowa, ang speed limit ay 55 mph. Hindi bababa sa gaano kalayo bago lumiko dapat kang magsimulang mag-signal?","o":["50 talampakan","100 talampakan","300 talampakan","1,000 talampakan"],"h1":"Sa mas mabibilis na kalsada, mas mahabang babala ang hinihingi ng Iowa kaysa sa mababagal na kalye.","h2":"Sa Iowa, dapat kang mag-signal nang hindi bababa sa 300 talampakan bago lumiko kapag ang speed limit ay higit sa 45 mph, at hindi bababa sa 100 talampakan kapag ito ay 45 mph o mas mababa.","p":"Tama. Kapag higit sa 45 mph, mag-signal nang hindi bababa sa 300 talampakan bago lumiko."},"ar":{"q":"في Iowa، حد السرعة 55 mph. على أي مسافة على الأقل قبل المنعطف يجب أن تبدأ بإعطاء الإشارة؟","o":["50 قدمًا","100 قدم","300 قدم","1,000 قدم"],"h1":"على الطرق الأسرع، تطلب Iowa تنبيهًا أبكر مما في الشوارع البطيئة.","h2":"في Iowa يجب أن تعطي الإشارة قبل المنعطف بمسافة 300 قدم على الأقل عندما يكون حد السرعة أكثر من 45 mph، وبمسافة 100 قدم على الأقل عندما يكون 45 mph أو أقل.","p":"صحيح. فوق 45 mph، أعطِ الإشارة قبل المنعطف بـ 300 قدم على الأقل."},"ref":{"doc":"IA","page":43}},{"id":"ia-033","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, how far behind an emergency vehicle using its lights and siren must you stay?","o":["At least 500 feet","At least 50 feet","At least 100 feet","At least one car length"],"h1":"The distance is much longer than a city block is wide.","h2":"In Iowa you must stay at least 500 feet behind any emergency vehicle that is using its lights and siren.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Iowa, ¿a qué distancia detrás de un vehículo de emergencia con luces y sirena encendidas debe mantenerse?","o":["Por lo menos 500 pies","Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos el largo de un auto"],"h1":"La distancia es mucho mayor que el ancho de una cuadra.","h2":"En Iowa usted debe mantenerse por lo menos a 500 pies detrás de cualquier vehículo de emergencia que use sus luces y sirena.","p":"Correcto. Manténgase por lo menos a 500 pies."},"zh":{"q":"在 Iowa，开着警灯并鸣笛的紧急车辆，你必须在它后面保持多远？","o":["至少 500 英尺","至少 50 英尺","至少 100 英尺","至少一个车身长"],"h1":"这个距离比一个城市街区的宽度长得多。","h2":"在 Iowa，对任何开着警灯并鸣笛的紧急车辆，你必须在它后面保持至少 500 英尺。","p":"对。在后面保持至少 500 英尺。"},"vi":{"q":"Ở Iowa, bạn phải giữ khoảng cách bao xa phía sau xe khẩn cấp đang bật đèn và còi hụ?","o":["Ít nhất 500 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất một thân xe"],"h1":"Khoảng cách này dài hơn nhiều so với bề ngang một dãy phố.","h2":"Ở Iowa, bạn phải giữ khoảng cách ít nhất 500 feet phía sau bất kỳ xe khẩn cấp nào đang bật đèn và còi hụ.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet phía sau."},"tl":{"q":"Sa Iowa, gaano kalayo ka dapat manatili sa likod ng emergency vehicle na gumagamit ng ilaw at sirena?","o":["Hindi bababa sa 500 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa haba ng isang kotse"],"h1":"Mas mahaba ang layong ito kaysa sa lapad ng isang city block.","h2":"Sa Iowa, dapat kang manatili nang hindi bababa sa 500 talampakan sa likod ng anumang emergency vehicle na gumagamit ng ilaw at sirena.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod."},"ar":{"q":"في Iowa، على أي مسافة يجب أن تبقى خلف مركبة طوارئ تستخدم أضواءها وصفّارتها؟","o":["500 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","طول سيارة واحدة على الأقل"],"h1":"المسافة أطول بكثير من عرض مربع سكني في المدينة.","h2":"في Iowa يجب أن تبقى على بعد 500 قدم على الأقل خلف أي مركبة طوارئ تستخدم أضواءها وصفّارتها.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل."},"ref":{"doc":"IA","page":19}},{"id":"ia-034","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, how close to a railroad crossing may you not park?","o":["Closer than 5 feet","Closer than 10 feet","Closer than 20 feet","Closer than 50 feet"],"h1":"It is the longest of Iowa's no-parking distances.","h2":"In Iowa you may not park closer than 50 feet to a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Iowa, ¿a qué distancia de un cruce de ferrocarril no se puede estacionar?","o":["A menos de 5 pies","A menos de 10 pies","A menos de 20 pies","A menos de 50 pies"],"h1":"Es la más larga de las distancias para no estacionar en Iowa.","h2":"En Iowa no se puede estacionar a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Estacione por lo menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Iowa，离铁路道口多近的地方不能停车？","o":["少于 5 英尺","少于 10 英尺","少于 20 英尺","少于 50 英尺"],"h1":"这是 Iowa 禁止停车距离中最长的一个。","h2":"在 Iowa，你不能在离铁路道口少于 50 英尺的地方停车。","p":"对。停车要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Iowa, bạn không được đỗ xe gần chỗ băng qua đường ray xe lửa đến mức nào?","o":["Gần hơn 5 feet","Gần hơn 10 feet","Gần hơn 20 feet","Gần hơn 50 feet"],"h1":"Đây là khoảng cách cấm đỗ xe dài nhất ở Iowa.","h2":"Ở Iowa, bạn không được đỗ xe gần hơn 50 feet từ chỗ băng qua đường ray xe lửa.","p":"Đúng. Đỗ xe cách chỗ băng qua đường ray ít nhất 50 feet."},"tl":{"q":"Sa Iowa, gaano kalapit sa railroad crossing ang bawal kang pumarada?","o":["Mas malapit sa 5 talampakan","Mas malapit sa 10 talampakan","Mas malapit sa 20 talampakan","Mas malapit sa 50 talampakan"],"h1":"Ito ang pinakamahabang layo kung saan bawal pumarada sa Iowa.","h2":"Sa Iowa, bawal kang pumarada nang mas malapit sa 50 talampakan mula sa railroad crossing.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan mula sa railroad crossing."},"ar":{"q":"في Iowa، على أي مسافة من معبر سكة الحديد لا يجوز لك أن تركن سيارتك؟","o":["أقرب من 5 أقدام","أقرب من 10 أقدام","أقرب من 20 قدمًا","أقرب من 50 قدمًا"],"h1":"هي أطول مسافة يُمنع فيها الركن في Iowa.","h2":"في Iowa لا يجوز لك أن تركن سيارتك على مسافة أقرب من 50 قدمًا من معبر سكة الحديد.","p":"صحيح. اركن على بعد 50 قدمًا على الأقل من معبر سكة الحديد."},"ref":{"doc":"IA","page":21}},{"id":"ia-035","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, how close to the entrance of a fire station may you not park?","o":["Closer than 5 feet","Closer than 20 feet","Closer than 100 feet","Closer than 500 feet"],"h1":"Fire trucks need room to get out fast.","h2":"In Iowa you may not park closer than 20 feet to the entrance of a fire station.","p":"Right. Keep 20 feet away from a fire station entrance."},"es":{"q":"En Iowa, ¿a qué distancia de la entrada de una estación de bomberos no se puede estacionar?","o":["A menos de 5 pies","A menos de 20 pies","A menos de 100 pies","A menos de 500 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir rápido.","h2":"En Iowa no se puede estacionar a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Manténgase a 20 pies de la entrada de una estación de bomberos."},"zh":{"q":"在 Iowa，离消防站入口多近的地方不能停车？","o":["少于 5 英尺","少于 20 英尺","少于 100 英尺","少于 500 英尺"],"h1":"消防车需要空间快速开出来。","h2":"在 Iowa，你不能在离消防站入口少于 20 英尺的地方停车。","p":"对。离消防站入口至少 20 英尺。"},"vi":{"q":"Ở Iowa, bạn không được đỗ xe gần lối vào trạm cứu hỏa đến mức nào?","o":["Gần hơn 5 feet","Gần hơn 20 feet","Gần hơn 100 feet","Gần hơn 500 feet"],"h1":"Xe cứu hỏa cần chỗ để chạy ra nhanh.","h2":"Ở Iowa, bạn không được đỗ xe gần hơn 20 feet từ lối vào trạm cứu hỏa.","p":"Đúng. Giữ cách lối vào trạm cứu hỏa 20 feet."},"tl":{"q":"Sa Iowa, gaano kalapit sa pasukan ng fire station ang bawal kang pumarada?","o":["Mas malapit sa 5 talampakan","Mas malapit sa 20 talampakan","Mas malapit sa 100 talampakan","Mas malapit sa 500 talampakan"],"h1":"Kailangan ng mga fire truck ng espasyo para makalabas nang mabilis.","h2":"Sa Iowa, bawal kang pumarada nang mas malapit sa 20 talampakan mula sa pasukan ng fire station.","p":"Tama. Lumayo nang 20 talampakan mula sa pasukan ng fire station."},"ar":{"q":"في Iowa، على أي مسافة من مدخل محطة الإطفاء لا يجوز لك أن تركن سيارتك؟","o":["أقرب من 5 أقدام","أقرب من 20 قدمًا","أقرب من 100 قدم","أقرب من 500 قدم"],"h1":"سيارات الإطفاء تحتاج إلى مساحة لتخرج بسرعة.","h2":"في Iowa لا يجوز لك أن تركن سيارتك على مسافة أقرب من 20 قدمًا من مدخل محطة الإطفاء.","p":"صحيح. ابقَ على بعد 20 قدمًا من مدخل محطة الإطفاء."},"ref":{"doc":"IA","page":21}},{"id":"ia-036","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, how close to a stop sign may you not park?","o":["Closer than 10 feet","Closer than 30 feet","Closer than 50 feet","Closer than 100 feet"],"h1":"It is a short distance, but drivers still need to see the sign.","h2":"In Iowa you may not park closer than 10 feet to a stop sign.","p":"Right. Park at least 10 feet from a stop sign."},"es":{"q":"En Iowa, ¿a qué distancia de una señal de alto (stop) no se puede estacionar?","o":["A menos de 10 pies","A menos de 30 pies","A menos de 50 pies","A menos de 100 pies"],"h1":"Es una distancia corta, pero los conductores necesitan ver la señal.","h2":"En Iowa no se puede estacionar a menos de 10 pies de una señal de alto.","p":"Correcto. Estacione por lo menos a 10 pies de una señal de alto."},"zh":{"q":"在 Iowa，离停止标志（stop sign）多近的地方不能停车？","o":["少于 10 英尺","少于 30 英尺","少于 50 英尺","少于 100 英尺"],"h1":"距离很短，但司机还是需要看到这个标志。","h2":"在 Iowa，你不能在离停止标志少于 10 英尺的地方停车。","p":"对。停车要离停止标志至少 10 英尺。"},"vi":{"q":"Ở Iowa, bạn không được đỗ xe gần biển báo dừng (stop sign) đến mức nào?","o":["Gần hơn 10 feet","Gần hơn 30 feet","Gần hơn 50 feet","Gần hơn 100 feet"],"h1":"Đây là khoảng cách ngắn, nhưng người lái xe vẫn cần nhìn thấy biển báo.","h2":"Ở Iowa, bạn không được đỗ xe gần hơn 10 feet từ biển báo dừng.","p":"Đúng. Đỗ xe cách biển báo dừng ít nhất 10 feet."},"tl":{"q":"Sa Iowa, gaano kalapit sa stop sign ang bawal kang pumarada?","o":["Mas malapit sa 10 talampakan","Mas malapit sa 30 talampakan","Mas malapit sa 50 talampakan","Mas malapit sa 100 talampakan"],"h1":"Maikli ang layong ito, pero kailangan pa ring makita ng mga driver ang karatula.","h2":"Sa Iowa, bawal kang pumarada nang mas malapit sa 10 talampakan mula sa stop sign.","p":"Tama. Pumarada nang hindi bababa sa 10 talampakan mula sa stop sign."},"ar":{"q":"في Iowa، على أي مسافة من لافتة التوقف (stop sign) لا يجوز لك أن تركن سيارتك؟","o":["أقرب من 10 أقدام","أقرب من 30 قدمًا","أقرب من 50 قدمًا","أقرب من 100 قدم"],"h1":"إنها مسافة قصيرة، لكن السائقين ما زالوا بحاجة إلى رؤية اللافتة.","h2":"في Iowa لا يجوز لك أن تركن سيارتك على مسافة أقرب من 10 أقدام من لافتة التوقف.","p":"صحيح. اركن على بعد 10 أقدام على الأقل من لافتة التوقف."},"ref":{"doc":"IA","page":21}},{"id":"ia-037","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, you have a small crash. No one is hurt and your car still runs safely. What does the law say to do with your car?","o":["Leave it exactly where it stopped","Leave it until the insurance company sees it","Move it out of the traffic lanes","Drive it home before you call anyone"],"h1":"Iowa calls this law \"Steer It, Clear It.\"","h2":"In Iowa, after a crash with no injuries, you must move your car out of the traffic lanes if it can be driven and moved safely.","p":"Right. Steer it and clear it out of the traffic lanes."},"es":{"q":"En Iowa, usted tiene un choque pequeño. Nadie está herido y su auto todavía funciona bien. ¿Qué dice la ley que haga con su auto?","o":["Dejarlo exactamente donde quedó","Dejarlo hasta que lo vea la compañía de seguros","Sacarlo de los carriles de tráfico","Manejarlo a su casa antes de llamar a alguien"],"h1":"Iowa llama a esta ley \"Steer It, Clear It\" (muévalo, despeje el camino).","h2":"En Iowa, después de un choque sin heridos, usted debe sacar su auto de los carriles de tráfico si se puede manejar y mover con seguridad.","p":"Correcto. Saque el auto de los carriles de tráfico."},"zh":{"q":"在 Iowa，你发生了一起小车祸。没有人受伤，你的车还能安全行驶。法律说你应该怎么处理你的车？","o":["把车留在它停下的原地","把车留着，等保险公司来看","把车移出行车道","在打电话给任何人之前先把车开回家"],"h1":"Iowa 把这条法律叫做 \"Steer It, Clear It\"（开走它，清空车道）。","h2":"在 Iowa，发生没有人受伤的车祸后，如果车还能安全行驶和移动，你必须把车移出行车道。","p":"对。把车开走，移出行车道。"},"vi":{"q":"Ở Iowa, bạn gặp một vụ va chạm nhỏ. Không ai bị thương và xe của bạn vẫn chạy an toàn. Luật nói bạn phải làm gì với xe của mình?","o":["Để xe đúng chỗ nó dừng lại","Để xe đó cho đến khi công ty bảo hiểm đến xem","Di chuyển xe ra khỏi làn xe chạy","Lái xe về nhà trước khi gọi cho bất kỳ ai"],"h1":"Iowa gọi luật này là \"Steer It, Clear It\" (lái xe đi, dọn trống làn đường).","h2":"Ở Iowa, sau một vụ va chạm không có ai bị thương, bạn phải di chuyển xe ra khỏi làn xe chạy nếu xe còn lái và di chuyển được một cách an toàn.","p":"Đúng. Lái xe ra khỏi làn xe chạy."},"tl":{"q":"Sa Iowa, nagkaroon ka ng maliit na banggaan. Walang nasaktan at ligtas pang tumatakbo ang iyong kotse. Ano ang sinasabi ng batas na gawin mo sa iyong kotse?","o":["Iwan ito kung saan mismo ito tumigil","Iwan ito hanggang makita ng insurance company","Ilipat ito palabas ng mga traffic lane","Imaneho ito pauwi bago ka tumawag sa kahit sino"],"h1":"Tinatawag ng Iowa ang batas na ito na \"Steer It, Clear It.\"","h2":"Sa Iowa, pagkatapos ng banggaan na walang nasaktan, dapat mong ilipat ang iyong kotse palabas ng mga traffic lane kung ligtas pa itong maimaneho at mailipat.","p":"Tama. Imaneho ito palabas ng mga traffic lane."},"ar":{"q":"في Iowa، تعرّضت لحادث بسيط. لم يُصب أحد وسيارتك ما زالت تسير بأمان. ماذا يقول القانون أن تفعل بسيارتك؟","o":["اتركها في المكان الذي توقفت فيه تمامًا","اتركها حتى تراها شركة التأمين","انقلها خارج مسارات السير","قُدها إلى البيت قبل أن تتصل بأي أحد"],"h1":"تسمّي Iowa هذا القانون \"Steer It, Clear It\" (وجّهها وأخلِ الطريق).","h2":"في Iowa، بعد حادث بلا إصابات، يجب أن تنقل سيارتك خارج مسارات السير إذا كان يمكن قيادتها ونقلها بأمان.","p":"صحيح. وجّه سيارتك وأخرجها من مسارات السير."},"ref":{"doc":"IA","page":22}},{"id":"ia-038","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, how much light must the windshield and the windows next to the driver let through?","o":["At least 20 percent","At least 35 percent","At least 50 percent","At least 70 percent"],"h1":"Iowa allows only light tint on these windows.","h2":"In Iowa the windshield and the windows to the driver's right and left must let at least 70 percent of the light through.","p":"Right. They must let at least 70 percent of the light through."},"es":{"q":"En Iowa, ¿cuánta luz deben dejar pasar el parabrisas y las ventanas al lado del conductor?","o":["Por lo menos el 20 por ciento","Por lo menos el 35 por ciento","Por lo menos el 50 por ciento","Por lo menos el 70 por ciento"],"h1":"Iowa solo permite un polarizado claro en estas ventanas.","h2":"En Iowa el parabrisas y las ventanas a la derecha y a la izquierda del conductor deben dejar pasar por lo menos el 70 por ciento de la luz.","p":"Correcto. Deben dejar pasar por lo menos el 70 por ciento de la luz."},"zh":{"q":"在 Iowa，挡风玻璃和司机两侧的车窗必须让多少光透过？","o":["至少 20%","至少 35%","至少 50%","至少 70%"],"h1":"Iowa 只允许这些车窗贴很浅的膜。","h2":"在 Iowa，挡风玻璃和司机左右两侧的车窗必须让至少 70% 的光透过。","p":"对。它们必须让至少 70% 的光透过。"},"vi":{"q":"Ở Iowa, kính chắn gió và các cửa sổ bên cạnh người lái phải cho bao nhiêu ánh sáng đi qua?","o":["Ít nhất 20 phần trăm","Ít nhất 35 phần trăm","Ít nhất 50 phần trăm","Ít nhất 70 phần trăm"],"h1":"Iowa chỉ cho phép dán phim màu nhạt trên các cửa sổ này.","h2":"Ở Iowa, kính chắn gió và các cửa sổ bên phải và bên trái người lái phải cho ít nhất 70 phần trăm ánh sáng đi qua.","p":"Đúng. Chúng phải cho ít nhất 70 phần trăm ánh sáng đi qua."},"tl":{"q":"Sa Iowa, gaano karaming liwanag ang dapat palusutin ng windshield at ng mga bintana sa tabi ng driver?","o":["Hindi bababa sa 20 porsiyento","Hindi bababa sa 35 porsiyento","Hindi bababa sa 50 porsiyento","Hindi bababa sa 70 porsiyento"],"h1":"Manipis na tint lang ang pinapayagan ng Iowa sa mga bintanang ito.","h2":"Sa Iowa, ang windshield at ang mga bintana sa kanan at kaliwa ng driver ay dapat magpalusot ng hindi bababa sa 70 porsiyento ng liwanag.","p":"Tama. Dapat silang magpalusot ng hindi bababa sa 70 porsiyento ng liwanag."},"ar":{"q":"في Iowa، ما مقدار الضوء الذي يجب أن يسمح الزجاج الأمامي والنوافذ المجاورة للسائق بمروره؟","o":["20 بالمئة على الأقل","35 بالمئة على الأقل","50 بالمئة على الأقل","70 بالمئة على الأقل"],"h1":"تسمح Iowa فقط بتظليل خفيف على هذه النوافذ.","h2":"في Iowa يجب أن يسمح الزجاج الأمامي والنوافذ التي على يمين السائق ويساره بمرور 70 بالمئة على الأقل من الضوء.","p":"صحيح. يجب أن تسمح بمرور 70 بالمئة على الأقل من الضوء."},"ref":{"doc":"IA","page":24}},{"id":"ia-039","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, at least how far behind you must you be able to see in your rearview mirror?","o":["50 feet","200 feet","1,000 feet","One mile"],"h1":"If a load blocks this view, you need an outside mirror.","h2":"In Iowa you must be able to see at least 200 feet behind you in your rearview mirror, or have an outside mirror if a load blocks the view.","p":"Right. You must see at least 200 feet behind you."},"es":{"q":"En Iowa, ¿por lo menos a qué distancia detrás de usted debe poder ver por el espejo retrovisor?","o":["50 pies","200 pies","1,000 pies","Una milla"],"h1":"Si una carga tapa esta vista, usted necesita un espejo exterior.","h2":"En Iowa usted debe poder ver por lo menos 200 pies detrás de usted por el espejo retrovisor, o tener un espejo exterior si una carga tapa la vista.","p":"Correcto. Debe ver por lo menos 200 pies hacia atrás."},"zh":{"q":"在 Iowa，你必须能从后视镜里看到身后至少多远？","o":["50 英尺","200 英尺","1,000 英尺","一英里"],"h1":"如果货物挡住了视线，你需要一个车外后视镜。","h2":"在 Iowa，你必须能从后视镜里看到身后至少 200 英尺；如果货物挡住视线，就必须有车外后视镜。","p":"对。你必须能看到身后至少 200 英尺。"},"vi":{"q":"Ở Iowa, bạn phải có thể nhìn thấy ít nhất bao xa phía sau mình trong gương chiếu hậu?","o":["50 feet","200 feet","1,000 feet","Một dặm"],"h1":"Nếu hàng hóa che mất tầm nhìn này, bạn cần một gương bên ngoài.","h2":"Ở Iowa, bạn phải có thể nhìn thấy ít nhất 200 feet phía sau trong gương chiếu hậu, hoặc phải có gương bên ngoài nếu hàng hóa che mất tầm nhìn.","p":"Đúng. Bạn phải nhìn thấy ít nhất 200 feet phía sau."},"tl":{"q":"Sa Iowa, hindi bababa sa gaano kalayo sa likod mo ang dapat mong makita sa rearview mirror?","o":["50 talampakan","200 talampakan","1,000 talampakan","Isang milya"],"h1":"Kung may kargang humaharang sa tanaw na ito, kailangan mo ng salamin sa labas ng sasakyan.","h2":"Sa Iowa, dapat mong makita ang hindi bababa sa 200 talampakan sa likod mo sa rearview mirror, o dapat kang may salamin sa labas ng sasakyan kung may kargang humaharang sa tanaw.","p":"Tama. Dapat mong makita ang hindi bababa sa 200 talampakan sa likod mo."},"ar":{"q":"في Iowa، ما أقل مسافة خلفك يجب أن تتمكن من رؤيتها في مرآة الرؤية الخلفية؟","o":["50 قدمًا","200 قدم","1,000 قدم","ميل واحد"],"h1":"إذا حجبت حمولةٌ هذه الرؤية، فأنت بحاجة إلى مرآة خارجية.","h2":"في Iowa يجب أن تتمكن من رؤية 200 قدم على الأقل خلفك في مرآة الرؤية الخلفية، أو أن تكون لديك مرآة خارجية إذا حجبت حمولةٌ الرؤية.","p":"صحيح. يجب أن ترى 200 قدم على الأقل خلفك."},"ref":{"doc":"IA","page":25}},{"id":"ia-040","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, which back-seat passengers must wear a seat belt or ride in a child seat?","o":["Everyone under 18","Only children under 6","Only adults over 65","No one in the back seat"],"h1":"Front-seat riders always buckle up. In the back, the rule depends on age.","h2":"In Iowa every passenger under 18 must be buckled up or in a child restraint, in the back seat as well as the front.","p":"Right. Everyone under 18 must be buckled up, front and back."},"es":{"q":"En Iowa, ¿qué pasajeros del asiento trasero deben usar cinturón de seguridad o ir en un asiento para niños?","o":["Todos los menores de 18 años","Solo los niños menores de 6 años","Solo los adultos mayores de 65 años","Nadie en el asiento trasero"],"h1":"Los que van adelante siempre usan cinturón. Atrás, la regla depende de la edad.","h2":"En Iowa todo pasajero menor de 18 años debe llevar el cinturón puesto o ir en un sistema de seguridad para niños, tanto atrás como adelante.","p":"Correcto. Todos los menores de 18 deben ir abrochados, adelante y atrás."},"zh":{"q":"在 Iowa，哪些后座乘客必须系安全带或坐儿童座椅？","o":["所有未满 18 岁的人","只有未满 6 岁的儿童","只有 65 岁以上的成年人","后座的人都不用"],"h1":"前座乘客一定要系安全带。在后座，规定要看年龄。","h2":"在 Iowa，每一位未满 18 岁的乘客都必须系安全带或使用儿童约束座椅，后座和前座都一样。","p":"对。所有未满 18 岁的人，前座和后座都必须系好安全带。"},"vi":{"q":"Ở Iowa, những hành khách nào ngồi ghế sau phải thắt dây an toàn hoặc ngồi ghế trẻ em?","o":["Tất cả mọi người dưới 18 tuổi","Chỉ trẻ em dưới 6 tuổi","Chỉ người lớn trên 65 tuổi","Không ai ở ghế sau"],"h1":"Người ngồi ghế trước luôn phải thắt dây an toàn. Ở ghế sau, quy định tùy theo tuổi.","h2":"Ở Iowa, mọi hành khách dưới 18 tuổi đều phải thắt dây an toàn hoặc ngồi ghế an toàn cho trẻ em, ở ghế sau cũng như ghế trước.","p":"Đúng. Mọi người dưới 18 tuổi phải thắt dây an toàn, cả ghế trước và ghế sau."},"tl":{"q":"Sa Iowa, sinong mga pasahero sa likurang upuan ang dapat magsuot ng seat belt o sumakay sa child seat?","o":["Lahat ng wala pang 18","Mga batang wala pang 6 lang","Mga adult na lampas 65 lang","Wala sa likurang upuan"],"h1":"Laging nagsusuot ng seat belt ang mga nasa harapang upuan. Sa likod, nakadepende ang patakaran sa edad.","h2":"Sa Iowa, bawat pasaherong wala pang 18 ay dapat naka-seat belt o nasa child restraint, sa likurang upuan at sa harapang upuan.","p":"Tama. Lahat ng wala pang 18 ay dapat naka-seat belt, sa harap at sa likod."},"ar":{"q":"في Iowa، أي ركاب المقعد الخلفي يجب أن يربطوا حزام الأمان أو يجلسوا في مقعد أطفال؟","o":["كل من هم دون 18","الأطفال دون 6 فقط","البالغون فوق 65 فقط","لا أحد في المقعد الخلفي"],"h1":"ركاب المقعد الأمامي يربطون الحزام دائمًا. في الخلف، تعتمد القاعدة على العمر.","h2":"في Iowa يجب أن يربط كل راكب دون 18 حزام الأمان أو يجلس في مقعد أمان للأطفال، في المقعد الخلفي كما في الأمامي.","p":"صحيح. كل من هم دون 18 يجب أن يربطوا الحزام، في الأمام والخلف."},"ref":{"doc":"IA","page":34}},{"id":"ia-041","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a passenger under 18 is not wearing a seat belt. What is the fine for that passenger?","o":["A warning only","Up to $10","Up to $25","Up to $100"],"h1":"The fine for an unbuckled teen is twice the fine for an unbuckled adult.","h2":"In Iowa the seat belt fine is up to $50 for each passenger, and up to $100 for each passenger under 18.","p":"Right. Up to $100 for each unbuckled passenger under 18."},"es":{"q":"En Iowa, un pasajero menor de 18 años no lleva puesto el cinturón de seguridad. ¿Cuál es la multa por ese pasajero?","o":["Solo una advertencia","Hasta $10","Hasta $25","Hasta $100"],"h1":"La multa por un menor sin cinturón es el doble que la de un adulto sin cinturón.","h2":"En Iowa la multa por no usar el cinturón es de hasta $50 por cada pasajero, y de hasta $100 por cada pasajero menor de 18 años.","p":"Correcto. Hasta $100 por cada pasajero menor de 18 sin cinturón."},"zh":{"q":"在 Iowa，一名未满 18 岁的乘客没有系安全带。这名乘客的罚款是多少？","o":["只有警告","最多 $10","最多 $25","最多 $100"],"h1":"未系安全带的青少年的罚款，是未系安全带的成年人的两倍。","h2":"在 Iowa，没系安全带的罚款是每位乘客最多 $50，每位未满 18 岁的乘客最多 $100。","p":"对。每位没系安全带的未满 18 岁乘客最多 $100。"},"vi":{"q":"Ở Iowa, một hành khách dưới 18 tuổi không thắt dây an toàn. Tiền phạt cho hành khách đó là bao nhiêu?","o":["Chỉ cảnh cáo","Tối đa $10","Tối đa $25","Tối đa $100"],"h1":"Tiền phạt cho thiếu niên không thắt dây an toàn gấp đôi tiền phạt cho người lớn không thắt dây.","h2":"Ở Iowa, tiền phạt không thắt dây an toàn là tối đa $50 cho mỗi hành khách, và tối đa $100 cho mỗi hành khách dưới 18 tuổi.","p":"Đúng. Tối đa $100 cho mỗi hành khách dưới 18 tuổi không thắt dây an toàn."},"tl":{"q":"Sa Iowa, hindi naka-seat belt ang isang pasaherong wala pang 18. Magkano ang multa para sa pasaherong iyon?","o":["Babala lang","Hanggang $10","Hanggang $25","Hanggang $100"],"h1":"Doble ang multa para sa teen na hindi naka-seat belt kaysa sa multa para sa adult na hindi naka-seat belt.","h2":"Sa Iowa, ang multa sa hindi pagsusuot ng seat belt ay hanggang $50 para sa bawat pasahero, at hanggang $100 para sa bawat pasaherong wala pang 18.","p":"Tama. Hanggang $100 para sa bawat pasaherong wala pang 18 na hindi naka-seat belt."},"ar":{"q":"في Iowa، راكب دون 18 لا يربط حزام الأمان. ما الغرامة عن هذا الراكب؟","o":["إنذار فقط","حتى $10","حتى $25","حتى $100"],"h1":"غرامة المراهق غير المربوط بالحزام ضعف غرامة البالغ غير المربوط.","h2":"في Iowa تصل غرامة عدم ربط حزام الأمان إلى $50 عن كل راكب، وتصل إلى $100 عن كل راكب دون 18.","p":"صحيح. حتى $100 عن كل راكب دون 18 لا يربط الحزام."},"ref":{"doc":"IA","page":34}},{"id":"ia-042","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, a baby is under one year old and weighs less than 20 pounds. How must the baby ride?","o":["On an adult's lap with a seat belt","In a booster seat","In a rear-facing child seat","In a forward-facing seat belt"],"h1":"The baby's seat faces the back of the car.","h2":"In Iowa a child under one year old who weighs less than 20 pounds must ride in a rear-facing child restraint.","p":"Right. The baby must ride in a rear-facing seat."},"es":{"q":"En Iowa, un bebé tiene menos de un año y pesa menos de 20 libras. ¿Cómo debe viajar el bebé?","o":["En las piernas de un adulto con cinturón","En un asiento elevado (booster)","En un asiento para niños mirando hacia atrás","Con el cinturón del auto mirando hacia adelante"],"h1":"El asiento del bebé mira hacia la parte de atrás del auto.","h2":"En Iowa un niño menor de un año que pesa menos de 20 libras debe viajar en un asiento de seguridad mirando hacia atrás.","p":"Correcto. El bebé debe viajar en un asiento que mira hacia atrás."},"zh":{"q":"在 Iowa，一个婴儿不满一岁，体重不到 20 磅。婴儿必须怎样乘车？","o":["坐在大人腿上，系安全带","坐在增高座椅上","坐在后向儿童座椅里","用朝前的安全带"],"h1":"婴儿的座椅朝向车尾。","h2":"在 Iowa，不满一岁且体重不到 20 磅的儿童必须坐在后向的儿童约束座椅里。","p":"对。婴儿必须坐后向座椅。"},"vi":{"q":"Ở Iowa, một em bé dưới một tuổi và nặng dưới 20 pound. Em bé phải ngồi như thế nào?","o":["Ngồi trên đùi người lớn với dây an toàn","Ngồi ghế nâng (booster seat)","Ngồi ghế trẻ em quay mặt về phía sau","Thắt dây an toàn quay mặt về phía trước"],"h1":"Ghế của em bé quay về phía đuôi xe.","h2":"Ở Iowa, trẻ dưới một tuổi và nặng dưới 20 pound phải ngồi trong ghế an toàn trẻ em quay mặt về phía sau.","p":"Đúng. Em bé phải ngồi ghế quay mặt về phía sau."},"tl":{"q":"Sa Iowa, wala pang isang taon ang isang sanggol at mas magaan sa 20 pounds. Paano dapat sumakay ang sanggol?","o":["Sa kandungan ng adult na may seat belt","Sa booster seat","Sa child seat na nakaharap sa likod (rear-facing)","Sa seat belt na nakaharap sa harap"],"h1":"Nakaharap sa likod ng kotse ang upuan ng sanggol.","h2":"Sa Iowa, ang batang wala pang isang taon at mas magaan sa 20 pounds ay dapat sumakay sa child restraint na nakaharap sa likod (rear-facing).","p":"Tama. Dapat sumakay ang sanggol sa upuang nakaharap sa likod."},"ar":{"q":"في Iowa، طفل رضيع عمره أقل من سنة ووزنه أقل من 20 رطلًا. كيف يجب أن يركب الرضيع؟","o":["في حضن شخص بالغ مع حزام الأمان","في مقعد رافع (booster seat)","في مقعد أطفال مواجه للخلف","بحزام أمان مواجه للأمام"],"h1":"مقعد الرضيع يواجه مؤخرة السيارة.","h2":"في Iowa يجب أن يركب الطفل الذي عمره أقل من سنة ووزنه أقل من 20 رطلًا في مقعد أمان للأطفال مواجه للخلف.","p":"صحيح. يجب أن يركب الرضيع في مقعد مواجه للخلف."},"ref":{"doc":"IA","page":35}},{"id":"ia-043","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, a driver under 21 is caught with a blood alcohol level of 0.02 or more. At least how long is the license revoked?","o":["7 days","60 days","2 years","5 years"],"h1":"It is about two months. It becomes 180 days at 0.08 or more.","h2":"In Iowa a driver under 21 with a blood alcohol level of 0.02 or more loses the license for at least 60 days, and for at least 180 days at 0.08 or more.","p":"Right. At least 60 days."},"es":{"q":"En Iowa, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.02 o más. ¿Por lo menos cuánto tiempo le revocan la licencia?","o":["7 días","60 días","2 años","5 años"],"h1":"Son unos dos meses. Sube a 180 días con 0.08 o más.","h2":"En Iowa un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 o más pierde la licencia por lo menos 60 días, y por lo menos 180 días con 0.08 o más.","p":"Correcto. Por lo menos 60 días."},"zh":{"q":"在 Iowa，一名未满 21 岁的司机被查出血液酒精浓度达到 0.02 或以上。驾照至少被吊销多久？","o":["7 天","60 天","2 年","5 年"],"h1":"大约两个月。达到 0.08 或以上时，会变成 180 天。","h2":"在 Iowa，未满 21 岁的司机血液酒精浓度达到 0.02 或以上，驾照至少被吊销 60 天；达到 0.08 或以上，至少 180 天。","p":"对。至少 60 天。"},"vi":{"q":"Ở Iowa, một người lái xe dưới 21 tuổi bị phát hiện có nồng độ cồn trong máu từ 0.02 trở lên. Bằng lái bị thu hồi ít nhất bao lâu?","o":["7 ngày","60 ngày","2 năm","5 năm"],"h1":"Khoảng hai tháng. Từ 0.08 trở lên thì thành 180 ngày.","h2":"Ở Iowa, người lái xe dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên bị mất bằng lái ít nhất 60 ngày, và ít nhất 180 ngày nếu từ 0.08 trở lên.","p":"Đúng. Ít nhất 60 ngày."},"tl":{"q":"Sa Iowa, nahuli ang isang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa. Hindi bababa sa gaano katagal babawiin ang lisensya?","o":["7 araw","60 araw","2 taon","5 taon"],"h1":"Mga dalawang buwan ito. Nagiging 180 araw ito sa 0.08 o higit pa.","h2":"Sa Iowa, ang driver na wala pang 21 na may blood alcohol level na 0.02 o higit pa ay mawawalan ng lisensya nang hindi bababa sa 60 araw, at hindi bababa sa 180 araw sa 0.08 o higit pa.","p":"Tama. Hindi bababa sa 60 araw."},"ar":{"q":"في Iowa، ضُبط سائق دون 21 ونسبة الكحول في دمه 0.02 أو أكثر. ما أقل مدة تُلغى فيها رخصته؟","o":["7 أيام","60 يومًا","2 سنة","5 سنوات"],"h1":"حوالي شهرين. وتصبح 180 يومًا عند 0.08 أو أكثر.","h2":"في Iowa يفقد السائق الذي عمره دون 21 ونسبة الكحول في دمه 0.02 أو أكثر رخصته لمدة 60 يومًا على الأقل، ولمدة 180 يومًا على الأقل عند 0.08 أو أكثر.","p":"صحيح. 60 يومًا على الأقل."},"ref":{"doc":"IA","page":37}},{"id":"ia-044","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, an adult drives while intoxicated but is not found guilty in criminal court. What happens to the license?","o":["Nothing, because there was no conviction","It is suspended for 7 days","The driver only gets a warning letter","It is still revoked for at least 180 days"],"h1":"The license penalty does not wait for the court case.","h2":"In Iowa, even without a criminal conviction, driving while intoxicated leads to a license revocation of at least 180 days.","p":"Right. The license is still revoked for at least 180 days."},"es":{"q":"En Iowa, un adulto maneja intoxicado pero no lo declaran culpable en la corte penal. ¿Qué pasa con la licencia?","o":["Nada, porque no hubo condena","La suspenden por 7 días","Solo recibe una carta de advertencia","Igual se la revocan por lo menos 180 días"],"h1":"La sanción a la licencia no espera el caso en la corte.","h2":"En Iowa, aun sin una condena penal, manejar intoxicado lleva a la revocación de la licencia por lo menos 180 días.","p":"Correcto. Igual le revocan la licencia por lo menos 180 días."},"zh":{"q":"在 Iowa，一名成年人醉酒驾驶，但在刑事法庭上没有被判有罪。驾照会怎样？","o":["没事，因为没有被定罪","被暂停 7 天","司机只会收到一封警告信","仍然会被吊销至少 180 天"],"h1":"驾照的处罚不会等法庭案件结束。","h2":"在 Iowa，即使没有刑事定罪，醉酒驾驶也会让驾照被吊销至少 180 天。","p":"对。驾照仍然会被吊销至少 180 天。"},"vi":{"q":"Ở Iowa, một người lớn lái xe khi say rượu nhưng không bị tòa hình sự kết tội. Điều gì xảy ra với bằng lái?","o":["Không có gì, vì không bị kết tội","Bị đình chỉ 7 ngày","Người lái xe chỉ nhận thư cảnh cáo","Vẫn bị thu hồi ít nhất 180 ngày"],"h1":"Hình phạt về bằng lái không chờ vụ án ở tòa.","h2":"Ở Iowa, dù không bị kết tội hình sự, lái xe khi say rượu vẫn khiến bằng lái bị thu hồi ít nhất 180 ngày.","p":"Đúng. Bằng lái vẫn bị thu hồi ít nhất 180 ngày."},"tl":{"q":"Sa Iowa, nagmaneho ang isang adult habang lasing pero hindi napatunayang nagkasala sa criminal court. Ano ang mangyayari sa lisensya?","o":["Wala, dahil walang conviction","Masususpinde ito nang 7 araw","Babalang sulat lang ang matatanggap ng driver","Babawiin pa rin ito nang hindi bababa sa 180 araw"],"h1":"Hindi hinihintay ng parusa sa lisensya ang kaso sa korte.","h2":"Sa Iowa, kahit walang criminal conviction, ang pagmamaneho nang lasing ay humahantong sa pagbawi ng lisensya nang hindi bababa sa 180 araw.","p":"Tama. Babawiin pa rin ang lisensya nang hindi bababa sa 180 araw."},"ar":{"q":"في Iowa، شخص بالغ قاد وهو سكران لكن المحكمة الجنائية لم تُدِنه. ماذا يحدث لرخصته؟","o":["لا شيء، لأنه لم تكن هناك إدانة","تُعلَّق لمدة 7 أيام","يحصل السائق على رسالة إنذار فقط","تُلغى مع ذلك لمدة 180 يومًا على الأقل"],"h1":"عقوبة الرخصة لا تنتظر القضية في المحكمة.","h2":"في Iowa، حتى بدون إدانة جنائية، تؤدي القيادة وأنت سكران إلى إلغاء الرخصة لمدة 180 يومًا على الأقل.","p":"صحيح. تُلغى الرخصة مع ذلك لمدة 180 يومًا على الأقل."},"ref":{"doc":"IA","page":37}},{"id":"ia-045","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a driver under 18 loses the license for drunk driving (OWI). May the teen get a temporary restricted license?","o":["No, drivers under 18 cannot get one","Yes, after 7 days","Yes, to drive to school only","Yes, if a parent signs a form"],"h1":"Iowa is stricter with the youngest drivers here.","h2":"In Iowa a driver under 18 whose license is revoked for OWI cannot get a temporary restricted license.","p":"Right. Under 18, there is no temporary restricted license after an OWI."},"es":{"q":"En Iowa, a un conductor menor de 18 años le quitan la licencia por manejar ebrio (OWI). ¿Puede recibir una licencia temporal restringida?","o":["No, los menores de 18 no pueden recibirla","Sí, después de 7 días","Sí, solo para ir a la escuela","Sí, si un padre firma un formulario"],"h1":"Aquí Iowa es más estricto con los conductores más jóvenes.","h2":"En Iowa un conductor menor de 18 años a quien le revocan la licencia por OWI no puede recibir una licencia temporal restringida.","p":"Correcto. Los menores de 18 no reciben licencia temporal restringida después de un OWI."},"zh":{"q":"在 Iowa，一名未满 18 岁的司机因酒后驾驶（OWI）失去驾照。这个青少年可以拿到临时限制驾照吗？","o":["不可以，未满 18 岁的司机不能拿到","可以，7 天后","可以，只能开车去学校","可以，如果父母签一份表格"],"h1":"在这一点上，Iowa 对最年轻的司机更严格。","h2":"在 Iowa，未满 18 岁的司机如果因 OWI 被吊销驾照，不能拿到临时限制驾照。","p":"对。未满 18 岁，OWI 之后没有临时限制驾照。"},"vi":{"q":"Ở Iowa, một người lái xe dưới 18 tuổi bị mất bằng lái vì lái xe khi say rượu (OWI). Thiếu niên đó có thể lấy bằng lái hạn chế tạm thời không?","o":["Không, người lái xe dưới 18 tuổi không thể lấy","Có, sau 7 ngày","Có, chỉ để lái xe đến trường","Có, nếu cha mẹ ký một mẫu đơn"],"h1":"Ở điểm này, Iowa nghiêm khắc hơn với những người lái xe trẻ nhất.","h2":"Ở Iowa, người lái xe dưới 18 tuổi bị thu hồi bằng lái vì OWI không thể lấy bằng lái hạn chế tạm thời.","p":"Đúng. Dưới 18 tuổi, không có bằng lái hạn chế tạm thời sau OWI."},"tl":{"q":"Sa Iowa, nawalan ng lisensya ang isang driver na wala pang 18 dahil sa pagmamaneho nang lasing (OWI). Maaari bang makakuha ang teen ng temporary restricted license?","o":["Hindi, hindi makakakuha ang mga driver na wala pang 18","Oo, pagkalipas ng 7 araw","Oo, para magmaneho papunta sa paaralan lang","Oo, kung pipirma ang magulang sa isang form"],"h1":"Mas mahigpit ang Iowa sa pinakabatang mga driver dito.","h2":"Sa Iowa, ang driver na wala pang 18 na binawian ng lisensya dahil sa OWI ay hindi makakakuha ng temporary restricted license.","p":"Tama. Kapag wala pang 18, walang temporary restricted license pagkatapos ng OWI."},"ar":{"q":"في Iowa، سائق دون 18 فقد رخصته بسبب القيادة وهو سكران (OWI). هل يمكن لهذا المراهق الحصول على رخصة مقيّدة مؤقتة؟","o":["لا، السائقون دون 18 لا يمكنهم الحصول عليها","نعم، بعد 7 أيام","نعم، للقيادة إلى المدرسة فقط","نعم، إذا وقّع أحد الوالدين على استمارة"],"h1":"Iowa أشد صرامة هنا مع أصغر السائقين سنًا.","h2":"في Iowa، السائق دون 18 الذي أُلغيت رخصته بسبب OWI لا يمكنه الحصول على رخصة مقيّدة مؤقتة.","p":"صحيح. دون 18، لا توجد رخصة مقيّدة مؤقتة بعد OWI."},"ref":{"doc":"IA","page":37}},{"id":"ia-046","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, you see an orange reflective triangle on the back of a vehicle. How fast does that vehicle usually go?","o":["At least 55 mph","Exactly 45 mph","35 mph or less","Only 5 mph"],"h1":"You often see this sign on farm vehicles and horse-drawn wagons.","h2":"In Iowa an orange reflective triangle on the back of a vehicle means it travels at 35 mph or less.","p":"Right. It moves at 35 mph or less."},"es":{"q":"En Iowa, usted ve un triángulo anaranjado reflectante en la parte de atrás de un vehículo. ¿A qué velocidad suele ir ese vehículo?","o":["Por lo menos 55 mph","Exactamente 45 mph","35 mph o menos","Solo 5 mph"],"h1":"Esta señal se ve a menudo en vehículos agrícolas y carretas tiradas por caballos.","h2":"En Iowa un triángulo anaranjado reflectante en la parte de atrás de un vehículo significa que va a 35 millas por hora o menos.","p":"Correcto. Va a 35 mph o menos."},"zh":{"q":"在 Iowa，你看到一辆车后面有一个橙色反光三角形。这辆车通常开多快？","o":["至少 55 mph","正好 45 mph","35 mph 或更慢","只有 5 mph"],"h1":"你常常在农用车和马拉的车上看到这个标志。","h2":"在 Iowa，车后面的橙色反光三角形表示这辆车的速度是 35 mph 或更慢。","p":"对。它的速度是 35 mph 或更慢。"},"vi":{"q":"Ở Iowa, bạn thấy một hình tam giác phản quang màu cam phía sau một chiếc xe. Xe đó thường chạy nhanh bao nhiêu?","o":["Ít nhất 55 mph","Đúng 45 mph","35 mph hoặc chậm hơn","Chỉ 5 mph"],"h1":"Bạn thường thấy biển này trên xe nông trại và xe ngựa kéo.","h2":"Ở Iowa, hình tam giác phản quang màu cam phía sau một chiếc xe nghĩa là xe đó chạy 35 mph hoặc chậm hơn.","p":"Đúng. Xe đó chạy 35 mph hoặc chậm hơn."},"tl":{"q":"Sa Iowa, may nakita kang orange na reflective na tatsulok sa likod ng isang sasakyan. Gaano kabilis karaniwang tumakbo ang sasakyang iyon?","o":["Hindi bababa sa 55 mph","Eksaktong 45 mph","35 mph o mas mabagal","5 mph lang"],"h1":"Madalas mong makita ang karatulang ito sa mga sasakyang pangsaka at mga karitong hila ng kabayo.","h2":"Sa Iowa, ang orange na reflective na tatsulok sa likod ng sasakyan ay nangangahulugang tumatakbo ito nang 35 mph o mas mabagal.","p":"Tama. Tumatakbo ito nang 35 mph o mas mabagal."},"ar":{"q":"في Iowa، ترى مثلثًا برتقاليًا عاكسًا على مؤخرة مركبة. ما سرعة هذه المركبة عادةً؟","o":["55 mph على الأقل","45 mph بالضبط","35 mph أو أقل","5 mph فقط"],"h1":"ترى هذه اللافتة غالبًا على المركبات الزراعية والعربات التي تجرّها الخيول.","h2":"في Iowa، المثلث البرتقالي العاكس على مؤخرة مركبة يعني أنها تسير بسرعة 35 mph أو أقل.","p":"صحيح. تسير بسرعة 35 mph أو أقل."},"ref":{"doc":"IA","page":11}},{"id":"ia-047","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, how should you pass a person riding a bicycle?","o":["Stay in your lane and pass close by","Change lanes completely, as you would for a car","Honk and pass on the right","Drive on the shoulder to go around"],"h1":"Give the bicyclist the whole lane.","h2":"In Iowa, when you pass a bicyclist, you must change lanes completely and give the rider the whole lane, as you would for any other vehicle.","p":"Right. Change lanes completely to pass a bicycle."},"es":{"q":"En Iowa, ¿cómo debe rebasar a una persona que va en bicicleta?","o":["Quedarse en su carril y pasar muy cerca","Cambiar de carril por completo, como lo haría con un auto","Tocar la bocina y rebasar por la derecha","Manejar por el acotamiento para pasar"],"h1":"Déle al ciclista todo el carril.","h2":"En Iowa, cuando rebasa a un ciclista, usted debe cambiar de carril por completo y darle todo el carril, igual que con cualquier otro vehículo.","p":"Correcto. Cambie de carril por completo para rebasar una bicicleta."},"zh":{"q":"在 Iowa，你应该怎样超过骑自行车的人？","o":["留在自己的车道里，贴近超过","像超过汽车一样，完全换到另一条车道","按喇叭，从右边超过","开到路肩上绕过去"],"h1":"把整条车道让给骑车的人。","h2":"在 Iowa，超过骑自行车的人时，你必须完全换道，把整条车道让给骑车的人，就像超过其他任何车辆一样。","p":"对。超过自行车时要完全换道。"},"vi":{"q":"Ở Iowa, bạn nên vượt người đi xe đạp như thế nào?","o":["Ở lại trong làn của bạn và vượt sát bên","Chuyển hẳn sang làn khác, giống như khi vượt xe hơi","Bấm còi và vượt bên phải","Lái lên lề đường để vòng qua"],"h1":"Hãy nhường cả làn đường cho người đi xe đạp.","h2":"Ở Iowa, khi vượt người đi xe đạp, bạn phải chuyển hẳn sang làn khác và nhường cả làn đường cho người đó, giống như với bất kỳ xe nào khác.","p":"Đúng. Chuyển hẳn sang làn khác để vượt xe đạp."},"tl":{"q":"Sa Iowa, paano mo dapat lampasan ang taong nakasakay sa bisikleta?","o":["Manatili sa iyong lane at lumampas nang malapit","Lumipat nang buo ng lane, gaya ng gagawin mo sa kotse","Bumusina at lumampas sa kanan","Magmaneho sa shoulder para umikot"],"h1":"Ibigay sa nagbibisikleta ang buong lane.","h2":"Sa Iowa, kapag nilalampasan mo ang nagbibisikleta, dapat kang lumipat nang buo ng lane at ibigay sa kanya ang buong lane, gaya ng gagawin mo sa anumang ibang sasakyan.","p":"Tama. Lumipat nang buo ng lane para lampasan ang bisikleta."},"ar":{"q":"في Iowa، كيف يجب أن تتجاوز شخصًا يركب دراجة هوائية؟","o":["ابقَ في مسارك وتجاوزه من قريب","غيّر المسار بالكامل، كما تفعل مع سيارة","استخدم البوق وتجاوزه من اليمين","قُد على كتف الطريق لتلتفّ حوله"],"h1":"أعطِ راكب الدراجة المسار كله.","h2":"في Iowa، عندما تتجاوز راكب دراجة، يجب أن تغيّر المسار بالكامل وتعطيه المسار كله، كما تفعل مع أي مركبة أخرى.","p":"صحيح. غيّر المسار بالكامل لتتجاوز الدراجة."},"ref":{"doc":"IA","page":58}},{"id":"ia-048","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, how fast do snowplows usually go while they work?","o":["25 to 35 mph","5 to 10 mph","45 to 55 mph","60 to 70 mph"],"h1":"Many drivers hit plows from behind because plows are slower than they expect.","h2":"In Iowa snowplows usually work at 25 to 35 mph, so approach them with care.","p":"Right. Snowplows usually go 25 to 35 mph."},"es":{"q":"En Iowa, ¿a qué velocidad suelen ir las máquinas quitanieves mientras trabajan?","o":["De 25 a 35 mph","De 5 a 10 mph","De 45 a 55 mph","De 60 a 70 mph"],"h1":"Muchos conductores chocan por detrás con las quitanieves porque van más lento de lo que esperan.","h2":"En Iowa las máquinas quitanieves suelen trabajar a 25 a 35 millas por hora, así que acérquese con cuidado.","p":"Correcto. Las quitanieves suelen ir de 25 a 35 mph."},"zh":{"q":"在 Iowa，扫雪车工作时通常开多快？","o":["25 到 35 mph","5 到 10 mph","45 到 55 mph","60 到 70 mph"],"h1":"很多司机从后面撞上扫雪车，因为扫雪车比他们想的慢。","h2":"在 Iowa，扫雪车工作时通常开 25 到 35 mph，所以靠近时要小心。","p":"对。扫雪车通常开 25 到 35 mph。"},"vi":{"q":"Ở Iowa, xe ủi tuyết thường chạy nhanh bao nhiêu khi đang làm việc?","o":["25 đến 35 mph","5 đến 10 mph","45 đến 55 mph","60 đến 70 mph"],"h1":"Nhiều người lái xe đâm vào phía sau xe ủi tuyết vì xe ủi tuyết chậm hơn họ nghĩ.","h2":"Ở Iowa, xe ủi tuyết thường làm việc ở tốc độ 25 đến 35 mph, vì vậy hãy cẩn thận khi đến gần.","p":"Đúng. Xe ủi tuyết thường chạy 25 đến 35 mph."},"tl":{"q":"Sa Iowa, gaano kabilis karaniwang tumakbo ang mga snowplow habang nagtatrabaho?","o":["25 hanggang 35 mph","5 hanggang 10 mph","45 hanggang 55 mph","60 hanggang 70 mph"],"h1":"Maraming driver ang bumabangga sa likod ng snowplow dahil mas mabagal ito kaysa sa inaasahan nila.","h2":"Sa Iowa, karaniwang nagtatrabaho ang mga snowplow sa 25 hanggang 35 mph, kaya mag-ingat kapag lumalapit sa kanila.","p":"Tama. Karaniwang 25 hanggang 35 mph ang mga snowplow."},"ar":{"q":"في Iowa، ما سرعة كاسحات الثلج عادةً أثناء عملها؟","o":["من 25 إلى 35 mph","من 5 إلى 10 mph","من 45 إلى 55 mph","من 60 إلى 70 mph"],"h1":"كثير من السائقين يصطدمون بكاسحات الثلج من الخلف لأنها أبطأ مما يتوقعون.","h2":"في Iowa تعمل كاسحات الثلج عادةً بسرعة من 25 إلى 35 mph، لذلك اقترب منها بحذر.","p":"صحيح. كاسحات الثلج تسير عادةً من 25 إلى 35 mph."},"ref":{"doc":"IA","page":61}},{"id":"ia-049","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, one way to count as a resident for a driver's license is to live in the state without a break. For how long?","o":["1 year","6 months","90 days","30 days"],"h1":"It is about one month.","h2":"For an Iowa driver's license, living in Iowa for 30 days in a row is one of the ways to count as a resident.","p":"Right. 30 days in a row makes you a resident."},"es":{"q":"En Iowa, una forma de contar como residente para la licencia de manejar es vivir en el estado sin interrupción. ¿Por cuánto tiempo?","o":["1 año","6 meses","90 días","30 días"],"h1":"Es más o menos un mes.","h2":"Para la licencia de manejar de Iowa, vivir en Iowa 30 días seguidos es una de las formas de contar como residente.","p":"Correcto. Con 30 días seguidos usted es residente."},"zh":{"q":"在 Iowa，申请驾照时，算作居民的一种方式是不间断地住在这个州。要住多久？","o":["1 年","6 个月","90 天","30 天"],"h1":"大约一个月。","h2":"申请 Iowa 驾照时，连续在 Iowa 住 30 天是算作居民的方式之一。","p":"对。连续住 30 天就算居民。"},"vi":{"q":"Ở Iowa, một cách để được tính là cư dân khi xin bằng lái là sống liên tục trong tiểu bang. Trong bao lâu?","o":["1 năm","6 tháng","90 ngày","30 ngày"],"h1":"Khoảng một tháng.","h2":"Để xin bằng lái Iowa, sống ở Iowa liên tục 30 ngày là một trong những cách để được tính là cư dân.","p":"Đúng. Sống liên tục 30 ngày là bạn được tính là cư dân."},"tl":{"q":"Sa Iowa, isang paraan para maituring na residente para sa driver's license ay ang tumira sa estado nang tuloy-tuloy. Gaano katagal?","o":["1 taon","6 na buwan","90 araw","30 araw"],"h1":"Mga isang buwan ito.","h2":"Para sa Iowa driver's license, ang pagtira sa Iowa nang 30 araw na tuloy-tuloy ay isa sa mga paraan para maituring na residente.","p":"Tama. Ang 30 araw na tuloy-tuloy ay ginagawa kang residente."},"ar":{"q":"في Iowa، إحدى طرق اعتبارك مقيمًا للحصول على رخصة قيادة هي أن تعيش في الولاية دون انقطاع. لأي مدة؟","o":["1 سنة","6 أشهر","90 يومًا","30 يومًا"],"h1":"حوالي شهر واحد.","h2":"للحصول على رخصة قيادة من Iowa، العيش في Iowa لمدة 30 يومًا متتالية هو إحدى طرق اعتبارك مقيمًا.","p":"صحيح. 30 يومًا متتالية تجعلك مقيمًا."},"ref":{"doc":"IA","page":4}},{"id":"ia-050","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, you are pulling a trailer and no speed limit is posted. What is the general speed limit for a vehicle pulling another vehicle?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"It matches the limit for a suburban district.","h2":"In Iowa, when no limit is posted, a vehicle pulling another vehicle may go no faster than 45 mph.","p":"Right. The general limit when towing is 45 mph."},"es":{"q":"En Iowa, usted jala un remolque y no hay un límite de velocidad señalizado. ¿Cuál es el límite general para un vehículo que jala otro vehículo?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"Es el mismo límite que en una zona suburbana.","h2":"En Iowa, cuando no hay un límite señalizado, un vehículo que jala otro vehículo no puede ir a más de 45 millas por hora.","p":"Correcto. El límite general al remolcar es de 45 mph."},"zh":{"q":"在 Iowa，你在拖挂车，路上没有限速标志。拖着另一辆车的车辆，一般限速是多少？","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"它和郊区的限速一样。","h2":"在 Iowa，没有标示限速时，拖着另一辆车的车辆速度不能超过 45 mph。","p":"对。拖车时的一般限速是 45 mph。"},"vi":{"q":"Ở Iowa, bạn đang kéo một xe moóc và không có biển ghi tốc độ tối đa. Tốc độ tối đa chung cho xe đang kéo một xe khác là bao nhiêu?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"Nó bằng tốc độ tối đa của khu ngoại ô.","h2":"Ở Iowa, khi không có biển ghi tốc độ, xe đang kéo một xe khác không được chạy nhanh hơn 45 mph.","p":"Đúng. Tốc độ tối đa chung khi kéo xe là 45 mph."},"tl":{"q":"Sa Iowa, may hinihila kang trailer at walang nakapaskil na speed limit. Ano ang pangkalahatang speed limit para sa sasakyang may hinihilang ibang sasakyan?","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"Kapareho ito ng limit para sa suburban district.","h2":"Sa Iowa, kapag walang nakapaskil na limit, ang sasakyang may hinihilang ibang sasakyan ay hindi maaaring tumakbo nang mas mabilis sa 45 mph.","p":"Tama. Ang pangkalahatang limit kapag may hinihila ay 45 mph."},"ar":{"q":"في Iowa، أنت تسحب مقطورة ولا توجد لافتة لحد السرعة. ما حد السرعة العام لمركبة تسحب مركبة أخرى؟","o":["35 mph","45 mph","60 mph","70 mph"],"h1":"إنه يساوي حد السرعة في منطقة الضواحي.","h2":"في Iowa، عندما لا يكون هناك حد سرعة مكتوب، يجب ألّا تزيد سرعة المركبة التي تسحب مركبة أخرى على 45 mph.","p":"صحيح. الحد العام عند السحب هو 45 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-051","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, a rideshare driver (such as Uber or Lyft) is carrying a passenger toward railroad tracks. What must the driver do?","o":["Speed up to cross quickly","Stop only if a train is in sight","Stop 15 to 50 feet from the tracks before crossing","Stop right on the tracks to look"],"h1":"Iowa treats paid drivers like school buses here.","h2":"In Iowa drivers carrying passengers for hire, like school buses, must stop 15 to 50 feet from the railroad tracks before crossing, unless an officer or an EXEMPT sign says otherwise.","p":"Right. Stop 15 to 50 feet from the tracks, then cross."},"es":{"q":"En Iowa, un conductor de viajes compartidos (como Uber o Lyft) lleva a un pasajero y se acerca a unas vías del tren. ¿Qué debe hacer el conductor?","o":["Acelerar para cruzar rápido","Parar solo si se ve un tren","Parar a entre 15 y 50 pies de las vías antes de cruzar","Parar sobre las vías para mirar"],"h1":"Aquí Iowa trata a los conductores que cobran igual que a los autobuses escolares.","h2":"En Iowa los conductores que llevan pasajeros por pago, igual que los autobuses escolares, deben parar a entre 15 y 50 pies de las vías antes de cruzar, salvo que un policía o una señal EXEMPT indique otra cosa.","p":"Correcto. Pare a entre 15 y 50 pies de las vías y luego cruce."},"zh":{"q":"在 Iowa，一名网约车司机（例如 Uber 或 Lyft）载着乘客开向铁轨。司机必须怎么做？","o":["加速，快点通过","只有看到火车时才停","通过前在离铁轨 15 到 50 英尺的地方停车","停在铁轨上看一看"],"h1":"在这一点上，Iowa 把收费载客的司机当作校车一样对待。","h2":"在 Iowa，收费载客的司机和校车一样，通过前必须在离铁轨 15 到 50 英尺的地方停车，除非警察或 EXEMPT 标志另有说明。","p":"对。在离铁轨 15 到 50 英尺处停车，然后通过。"},"vi":{"q":"Ở Iowa, một tài xế xe công nghệ (như Uber hoặc Lyft) đang chở khách đến gần đường ray xe lửa. Tài xế phải làm gì?","o":["Tăng tốc để qua nhanh","Chỉ dừng nếu thấy xe lửa","Dừng cách đường ray 15 đến 50 feet trước khi băng qua","Dừng ngay trên đường ray để nhìn"],"h1":"Ở điểm này, Iowa đối xử với tài xế chở khách lấy tiền giống như xe buýt trường học.","h2":"Ở Iowa, tài xế chở khách lấy tiền, giống như xe buýt trường học, phải dừng cách đường ray 15 đến 50 feet trước khi băng qua, trừ khi cảnh sát hoặc biển EXEMPT cho biết khác.","p":"Đúng. Dừng cách đường ray 15 đến 50 feet, rồi băng qua."},"tl":{"q":"Sa Iowa, may sakay na pasahero ang isang rideshare driver (gaya ng Uber o Lyft) at papalapit sa riles ng tren. Ano ang dapat gawin ng driver?","o":["Bumilis para makatawid agad","Huminto lang kung may nakikitang tren","Huminto nang 15 hanggang 50 talampakan mula sa riles bago tumawid","Huminto mismo sa riles para tumingin"],"h1":"Itinuturing ng Iowa ang mga bayad na driver na parang school bus dito.","h2":"Sa Iowa, ang mga driver na may sakay na pasaherong nagbabayad, gaya ng mga school bus, ay dapat huminto nang 15 hanggang 50 talampakan mula sa riles bago tumawid, maliban kung iba ang sinasabi ng pulis o ng karatulang EXEMPT.","p":"Tama. Huminto nang 15 hanggang 50 talampakan mula sa riles, saka tumawid."},"ar":{"q":"في Iowa، سائق نقل تشاركي (مثل Uber أو Lyft) يقلّ راكبًا ويقترب من سكة حديد. ماذا يجب أن يفعل السائق؟","o":["أن يسرع ليعبر بسرعة","أن يتوقف فقط إذا رأى قطارًا","أن يتوقف على بعد 15 إلى 50 قدمًا من السكة قبل العبور","أن يتوقف فوق السكة مباشرة لينظر"],"h1":"تعامل Iowa هنا السائقين الذين يقلّون ركابًا بأجر مثل الحافلات المدرسية.","h2":"في Iowa يجب على السائقين الذين يقلّون ركابًا بأجر، مثل الحافلات المدرسية، أن يتوقفوا على بعد 15 إلى 50 قدمًا من سكة الحديد قبل العبور، ما لم يقل ضابط شرطة أو لافتة EXEMPT غير ذلك.","p":"صحيح. توقف على بعد 15 إلى 50 قدمًا من السكة، ثم اعبر."},"ref":{"doc":"IA","page":12}},{"id":"ia-052","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, which of these makes you an Iowa resident for a driver's license?","o":["You registered to vote in Iowa","You stayed in an Iowa hotel for a week","You bought gas in Iowa","You visited family in Iowa for a holiday"],"h1":"Think of a step that shows you plan to take part in life in the state.","h2":"In Iowa, registering to vote in the state is one of the things that makes you a resident for a driver's license.","p":"Right! Registering to vote in Iowa makes you a resident for licensing."},"es":{"q":"En Iowa, ¿cuál de estas cosas lo convierte en residente de Iowa para la licencia de conducir?","o":["Se registró para votar en Iowa","Se quedó una semana en un hotel de Iowa","Compró gasolina en Iowa","Visitó a su familia en Iowa en un día festivo"],"h1":"Piense en algo que muestra que usted participa en la vida del estado.","h2":"En Iowa, registrarse para votar en el estado es una de las cosas que lo convierten en residente para la licencia de conducir.","p":"¡Correcto! Registrarse para votar en Iowa lo hace residente para la licencia."},"ref":{"doc":"IA","page":4}},{"id":"ia-053","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a farmer drives farm equipment from the home farm to nearby farmland without a license. How far away may that farmland be?","o":["Within 10 miles","Within two miles","Within 25 miles","Anywhere in the same county"],"h1":"The distance is short, only a few minutes away.","h2":"In Iowa, you do not need a license to drive farm equipment between the home farm and farmland within two miles.","p":"Correct! The farmland must be within two miles."},"es":{"q":"En Iowa, un agricultor maneja maquinaria agrícola sin licencia desde su granja hasta un terreno cercano. ¿A qué distancia puede estar ese terreno?","o":["A menos de 10 millas","A menos de dos millas","A menos de 25 millas","En cualquier lugar del mismo condado"],"h1":"La distancia es corta, a pocos minutos.","h2":"En Iowa, no necesita licencia para manejar maquinaria agrícola entre la granja y un terreno que esté a menos de dos millas.","p":"¡Correcto! El terreno debe estar a menos de dos millas."},"ref":{"doc":"IA","page":4}},{"id":"ia-054","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a college student from another state has a valid license from home. Does the student need an Iowa license to drive while studying in Iowa?","o":["Yes, within 10 days of arriving","Yes, before the first semester ends","No, the valid home-state license is enough","No, but the student may drive only in daylight"],"h1":"Iowa makes an exception for visitors and students.","h2":"In Iowa, a visitor or student with a current license from their home state or country does not need an Iowa license.","p":"Well done! A current home-state license is enough for a student."},"es":{"q":"En Iowa, un estudiante universitario de otro estado tiene una licencia válida de su estado. ¿Necesita una licencia de Iowa para manejar mientras estudia en Iowa?","o":["Sí, en los 10 días después de llegar","Sí, antes de que termine el primer semestre","No, basta con la licencia válida de su estado","No, pero solo puede manejar de día"],"h1":"Iowa hace una excepción para visitantes y estudiantes.","h2":"En Iowa, un visitante o estudiante con una licencia vigente de su estado o país no necesita una licencia de Iowa.","p":"¡Muy bien! Basta con la licencia vigente de su estado."},"ref":{"doc":"IA","page":4}},{"id":"ia-055","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how may you carry proof of insurance in your car?","o":["Only on the original paper card","Only on a card stamped by the county","You do not need to carry proof of insurance","On a paper card or shown on your phone"],"h1":"Iowa accepts more than one format.","h2":"In Iowa, your insurance card may be printed on paper or shown in electronic form, such as on your phone.","p":"Right! Paper or electronic proof of insurance is accepted."},"es":{"q":"En Iowa, ¿cómo puede llevar el comprobante de seguro en su carro?","o":["Solo en la tarjeta original de papel","Solo en una tarjeta sellada por el condado","No necesita llevar comprobante de seguro","En una tarjeta de papel o en la pantalla de su teléfono"],"h1":"Iowa acepta más de un formato.","h2":"En Iowa, la tarjeta del seguro puede ser impresa en papel o mostrarse en forma electrónica, por ejemplo en su teléfono.","p":"¡Correcto! Se acepta el comprobante en papel o electrónico."},"ref":{"doc":"IA","page":5}},{"id":"ia-056","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen finished an Iowa-approved driver education course. Must the teen also pass a driving test at the license office?","o":["Usually not, because the course counts instead","Yes, every teen must take two driving tests","Yes, but only after turning 18","No, but the teen must retake the written test"],"h1":"Finishing the approved course has a benefit.","h2":"In Iowa, a driving test is not required when you have met the driver education course requirement, unless an instructor or parent asks for one.","p":"Correct! The approved course usually takes the place of the driving test."},"es":{"q":"En Iowa, un adolescente terminó un curso de manejo aprobado por Iowa. ¿También debe pasar una prueba de manejo en la oficina de licencias?","o":["Por lo general no, porque el curso cuenta en su lugar","Sí, todo adolescente debe hacer dos pruebas de manejo","Sí, pero solo después de cumplir 18 años","No, pero debe repetir el examen escrito"],"h1":"Terminar el curso aprobado tiene una ventaja.","h2":"En Iowa, no se exige la prueba de manejo cuando cumplió el requisito del curso de educación vial, salvo que un instructor o un padre la pida.","p":"¡Correcto! El curso aprobado normalmente reemplaza la prueba de manejo."},"ref":{"doc":"IA","page":5}},{"id":"ia-057","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what score do you need to pass the driver's knowledge test?","o":["60% or higher","80% or higher","70% or higher","90% or higher"],"h1":"It is the same as getting 4 out of every 5 questions right.","h2":"In Iowa, you need a score of 80% or higher to pass the knowledge test.","p":"Well done! You need 80% or more to pass."},"es":{"q":"En Iowa, ¿qué puntaje necesita para aprobar el examen teórico de manejo?","o":["60% o más","80% o más","70% o más","90% o más"],"h1":"Es lo mismo que acertar 4 de cada 5 preguntas.","h2":"En Iowa, necesita un puntaje de 80% o más para aprobar el examen teórico.","p":"¡Muy bien! Necesita 80% o más para aprobar."},"ref":{"doc":"IA","page":null}},{"id":"ia-058","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a 14-year-old takes the permit knowledge test at home. Who must give the test?","o":["An older sibling with a license","A neighbor who is a teacher","A parent","The student, with no one watching"],"h1":"An adult in the family applies to run the test.","h2":"In Iowa, when the permit knowledge test is taken at home, a parent must apply and give the test on a computer.","p":"Right! A parent gives the at-home test."},"es":{"q":"En Iowa, un joven de 14 años hace el examen teórico del permiso en casa. ¿Quién debe aplicar el examen?","o":["Un hermano mayor con licencia","Un vecino que es maestro","Uno de los padres","El propio estudiante, sin nadie que lo vigile"],"h1":"Un adulto de la familia pide permiso para aplicar el examen.","h2":"En Iowa, cuando el examen del permiso se hace en casa, uno de los padres debe solicitarlo y aplicarlo en una computadora.","p":"¡Correcto! Uno de los padres aplica el examen en casa."},"ref":{"doc":"IA","page":null}},{"id":"ia-059","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, at least how many hours of classroom instruction does an approved driver education course have?","o":["10 hours","20 hours","50 hours","30 hours"],"h1":"It is more than 20 but less than 50.","h2":"In Iowa, an approved driver education course has at least 30 hours of classroom instruction.","p":"Correct! The course has at least 30 classroom hours."},"es":{"q":"En Iowa, ¿cuántas horas de clase en el aula tiene, como mínimo, un curso aprobado de educación vial?","o":["10 horas","20 horas","50 horas","30 horas"],"h1":"Es más de 20 pero menos de 50.","h2":"En Iowa, un curso aprobado de educación vial tiene al menos 30 horas de clase en el aula.","p":"¡Correcto! El curso tiene al menos 30 horas de clase."},"ref":{"doc":"IA","page":null}},{"id":"ia-060","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, at least how many hours of real street or highway driving are part of an approved driver education course?","o":["3 hours","1 hour","12 hours","20 hours"],"h1":"It is a small number, less than 5.","h2":"In Iowa, an approved driver education course includes at least 3 hours of street or highway driving.","p":"Right! At least 3 hours are spent driving on real roads."},"es":{"q":"En Iowa, ¿cuántas horas de manejo real en calles o carreteras incluye, como mínimo, un curso aprobado de educación vial?","o":["3 horas","1 hora","12 horas","20 horas"],"h1":"Es un número pequeño, menos de 5.","h2":"En Iowa, un curso aprobado de educación vial incluye al menos 3 horas de manejo en calles o carreteras.","p":"¡Correcto! Al menos 3 horas se manejan en calles reales."},"ref":{"doc":"IA","page":null}},{"id":"ia-061","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, an approved driver education course must spend at least 4 classroom hours on which topics?","o":["Car repair and changing tires","Substance use and distracted driving","Parking and backing up","Buying and registering a car"],"h1":"These topics are about things that impair or pull your attention.","h2":"In Iowa, driver education must include at least 4 hours about substance use and distracted driving.","p":"Correct! Four hours cover substance use and distracted driving."},"es":{"q":"En Iowa, un curso aprobado de educación vial debe dedicar al menos 4 horas de clase a ¿qué temas?","o":["Reparar el carro y cambiar llantas","El consumo de sustancias y las distracciones al manejar","Estacionar y dar marcha atrás","Comprar y registrar un carro"],"h1":"Estos temas tratan de lo que afecta o desvía su atención.","h2":"En Iowa, la educación vial debe incluir al menos 4 horas sobre el consumo de sustancias y las distracciones al manejar.","p":"¡Correcto! Cuatro horas tratan sobre sustancias y distracciones."},"ref":{"doc":"IA","page":null}},{"id":"ia-062","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a parent teaches driver education to their own teen. How much driving must the teen log?","o":["10 hours, with 1 at night","20 hours, with 2 at night","30 hours, with 3 at night","50 hours, with 10 at night"],"h1":"It is more than the usual permit practice hours.","h2":"In Iowa, parent-taught driver education requires 30 hours of street or highway driving, including 3 hours at night.","p":"Well done! Parent-taught driver education needs 30 hours, 3 at night."},"es":{"q":"En Iowa, un padre enseña educación vial a su propio hijo adolescente. ¿Cuántas horas de manejo debe registrar el joven?","o":["10 horas, 1 de noche","20 horas, 2 de noche","30 horas, 3 de noche","50 horas, 10 de noche"],"h1":"Es más que las horas normales de práctica con el permiso.","h2":"En Iowa, la educación vial enseñada por los padres exige 30 horas de manejo en calles o carreteras, incluidas 3 horas de noche.","p":"¡Muy bien! Se necesitan 30 horas, 3 de ellas de noche."},"ref":{"doc":"IA","page":null}},{"id":"ia-063","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, an instruction permit issued to a teen can be valid for up to how long?","o":["6 months","1 year","2 years","4 years"],"h1":"It lasts longer than most people expect.","h2":"In Iowa, a teen's instruction permit can be valid for up to 4 years.","p":"Right! The permit can last up to 4 years."},"es":{"q":"En Iowa, ¿hasta cuánto tiempo puede ser válido el permiso de aprendizaje de un adolescente?","o":["6 meses","1 año","2 años","4 años"],"h1":"Dura más de lo que mucha gente piensa.","h2":"En Iowa, el permiso de aprendizaje de un adolescente puede ser válido hasta 4 años.","p":"¡Correcto! El permiso puede durar hasta 4 años."},"ref":{"doc":"IA","page":null}},{"id":"ia-064","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen with an instruction permit is driving with a parent. How many passengers may be in the car?","o":["No more than the number of seat belts","No more than two","As many as fit in the car","Only the supervising parent"],"h1":"Each person needs something to buckle.","h2":"In Iowa, a teen with an instruction permit may not carry more passengers than there are seat belts in the vehicle.","p":"Correct! Never more passengers than seat belts."},"es":{"q":"En Iowa, un adolescente con permiso de aprendizaje maneja con su padre. ¿Cuántos pasajeros puede llevar en el carro?","o":["No más que el número de cinturones de seguridad","No más de dos","Todos los que quepan en el carro","Solo al padre que lo supervisa"],"h1":"Cada persona necesita algo con qué abrocharse.","h2":"En Iowa, un adolescente con permiso de aprendizaje no puede llevar más pasajeros que cinturones de seguridad haya en el vehículo.","p":"¡Correcto! Nunca más pasajeros que cinturones."},"ref":{"doc":"IA","page":null}},{"id":"ia-065","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a teen practices on a motorcycle with a motorcycle instruction permit. Where must the supervising adult be?","o":["On the back seat of the same motorcycle","On or in a different vehicle, close enough to see and hear the teen","At home, reachable by phone","Standing at the end of the street"],"h1":"The adult cannot ride on the learner's motorcycle.","h2":"In Iowa, the supervisor of a motorcycle permit holder must ride on or in a different vehicle, within sight and hearing of the learner.","p":"Right! The supervisor follows in another vehicle, within sight and hearing."},"es":{"q":"En Iowa, un adolescente practica en motocicleta con un permiso de aprendizaje de motocicleta. ¿Dónde debe estar el adulto que lo supervisa?","o":["En el asiento trasero de la misma motocicleta","En otro vehículo, lo bastante cerca para verlo y oírlo","En casa, disponible por teléfono","Parado al final de la calle"],"h1":"El adulto no puede ir en la motocicleta del aprendiz.","h2":"En Iowa, quien supervisa a un aprendiz de motocicleta debe ir en otro vehículo, donde pueda verlo y oírlo.","p":"¡Correcto! El supervisor lo sigue en otro vehículo, a la vista y al oído."},"ref":{"doc":"IA","page":null}},{"id":"ia-066","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a 16-year-old wants a license that allows riding a motorcycle (class M). What must the teen complete first?","o":["A first-aid class","A motorcycle repair class","A motorcycle education course","A year of driving a car"],"h1":"Teens need special training for two wheels.","h2":"In Iowa, a person under 18 must complete an approved motorcycle education course before a class M license is issued.","p":"Correct! A motorcycle education course comes first."},"es":{"q":"En Iowa, un joven de 16 años quiere una licencia para manejar motocicleta (clase M). ¿Qué debe completar primero?","o":["Un curso de primeros auxilios","Un curso de reparación de motocicletas","Un curso de educación para motociclistas","Un año manejando carro"],"h1":"Los jóvenes necesitan entrenamiento especial para dos ruedas.","h2":"En Iowa, una persona menor de 18 años debe completar un curso aprobado de educación para motociclistas antes de recibir la licencia clase M.","p":"¡Correcto! Primero va el curso para motociclistas."},"ref":{"doc":"IA","page":null}},{"id":"ia-067","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, a teen with an instruction permit gets a second traffic conviction. What usually happens?","o":["Only a warning letter","The teen must retake driver education","Nothing, permits have no penalties","The permit is suspended for 30 days"],"h1":"The first time brings a warning; the second time is stronger.","h2":"In Iowa, a second offense while holding an instruction permit leads to a 30-day suspension of the permit.","p":"Right! A second offense means a 30-day suspension."},"es":{"q":"En Iowa, un adolescente con permiso de aprendizaje recibe su segunda infracción de tránsito. ¿Qué suele pasar?","o":["Solo una carta de advertencia","Debe repetir el curso de educación vial","Nada, los permisos no tienen sanciones","Le suspenden el permiso por 30 días"],"h1":"La primera vez hay una advertencia; la segunda es más seria.","h2":"En Iowa, una segunda falta con permiso de aprendizaje lleva a una suspensión del permiso por 30 días.","p":"¡Correcto! La segunda falta significa 30 días de suspensión."},"ref":{"doc":"IA","page":null}},{"id":"ia-068","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen with an instruction permit causes a crash. How much longer must the teen wait to move up to an intermediate license?","o":["6 months","1 month","2 years","No delay"],"h1":"The teen needs a fresh stretch of clean driving.","h2":"In Iowa, each conviction, crash or restriction violation on an instruction permit delays the intermediate license by 6 months.","p":"Correct! Each problem on a permit delays the next step by 6 months."},"es":{"q":"En Iowa, un adolescente con permiso de aprendizaje causa un choque. ¿Cuánto tiempo más debe esperar para pasar a la licencia intermedia?","o":["6 meses","1 mes","2 años","No hay demora"],"h1":"El joven necesita un nuevo periodo de manejo sin problemas.","h2":"En Iowa, cada infracción, choque o violación de restricciones con permiso de aprendizaje retrasa la licencia intermedia 6 meses.","p":"¡Correcto! Cada problema con el permiso retrasa el siguiente paso 6 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-069","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a teen with an intermediate license gets a moving violation. How long is the move to a full license delayed?","o":["3 months","12 months","6 months","It is not delayed"],"h1":"The delay is longer than on a permit.","h2":"In Iowa, each conviction, crash or restriction violation on an intermediate license delays the full license by 12 months.","p":"Right! On an intermediate license, the delay is 12 months."},"es":{"q":"En Iowa, un adolescente con licencia intermedia recibe una infracción de tránsito. ¿Cuánto se retrasa el paso a la licencia completa?","o":["3 meses","12 meses","6 meses","No se retrasa"],"h1":"La demora es más larga que con el permiso.","h2":"En Iowa, cada infracción, choque o violación de restricciones con licencia intermedia retrasa la licencia completa 12 meses.","p":"¡Correcto! Con licencia intermedia, la demora es de 12 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-070","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, what is the youngest age to get a full driver's license?","o":["16","18","17","16 and a half"],"h1":"It comes one year after the earliest intermediate license.","h2":"In Iowa, a full driver's license is available at age 17.","p":"Correct! A full license is available at 17."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para obtener una licencia de conducir completa?","o":["16","18","17","16 y medio"],"h1":"Llega un año después de la primera licencia intermedia posible.","h2":"En Iowa, la licencia de conducir completa se puede obtener a los 17 años.","p":"¡Correcto! La licencia completa se obtiene a los 17."},"ref":{"doc":"IA","page":null}},{"id":"ia-071","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, how many more hours of supervised driving must a teen log with an intermediate license before getting a full license?","o":["None","5 hours, all in daylight","20 hours, with 4 at night","10 hours, with 2 at night"],"h1":"It is half of the hours needed for the intermediate license.","h2":"In Iowa, a teen needs 10 more hours of supervised driving on the intermediate license, with at least 2 between sunset and sunrise, before a full license.","p":"Right! Ten more hours, 2 of them at night."},"es":{"q":"En Iowa, ¿cuántas horas más de manejo supervisado debe registrar un joven con licencia intermedia antes de obtener la licencia completa?","o":["Ninguna","5 horas, todas de día","20 horas, 4 de noche","10 horas, 2 de noche"],"h1":"Es la mitad de las horas exigidas para la licencia intermedia.","h2":"En Iowa, el joven necesita 10 horas más de manejo supervisado con la licencia intermedia, al menos 2 entre la puesta y la salida del sol, antes de la licencia completa.","p":"¡Correcto! Diez horas más, 2 de noche."},"ref":{"doc":"IA","page":null}},{"id":"ia-072","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, how long must a teen hold an intermediate license, with a clean record, before getting a full license?","o":["12 months in a row","3 months","6 months","24 months"],"h1":"It is one full year.","h2":"In Iowa, a teen must hold the intermediate license for at least 12 consecutive months, free of violations and crashes, before a full license.","p":"Correct! Twelve months in a row with a clean record."},"es":{"q":"En Iowa, ¿cuánto tiempo debe tener un joven la licencia intermedia, sin infracciones, antes de obtener la licencia completa?","o":["12 meses seguidos","3 meses","6 meses","24 meses"],"h1":"Es un año completo.","h2":"En Iowa, el joven debe tener la licencia intermedia al menos 12 meses seguidos, sin infracciones ni choques, antes de la licencia completa.","p":"¡Correcto! Doce meses seguidos sin problemas."},"ref":{"doc":"IA","page":null}},{"id":"ia-073","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what words are printed on the driver's license of a 19-year-old?","o":["Provisional driver","Under twenty-one","Learner","Restricted youth"],"h1":"The words point to the legal drinking age.","h2":"In Iowa, a driver's license issued to someone 18 to 20 years old shows the words under twenty-one.","p":"Right! It says under twenty-one."},"es":{"q":"En Iowa, ¿qué palabras aparecen en la licencia de conducir de una persona de 19 años?","o":["Conductor provisional","Under twenty-one (menor de veintiuno)","Aprendiz","Joven con restricciones"],"h1":"Las palabras se refieren a la edad legal para beber alcohol.","h2":"En Iowa, la licencia de una persona de 18 a 20 años lleva las palabras under twenty-one, es decir, menor de veintiuno.","p":"¡Correcto! Dice under twenty-one."},"ref":{"doc":"IA","page":null}},{"id":"ia-074","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, which license class is for driving a motor vehicle as a chauffeur (driving people for pay)?","o":["Class M","Class C","Class D","Class E"],"h1":"It is the letter that comes right after C.","h2":"In Iowa, a class D license is for operating a motor vehicle as a chauffeur.","p":"Correct! Class D is the chauffeur license."},"es":{"q":"En Iowa, ¿qué clase de licencia sirve para manejar un vehículo como chofer (llevar personas por pago)?","o":["Clase M","Clase C","Clase D","Clase E"],"h1":"Es la letra que sigue a la C.","h2":"En Iowa, la licencia clase D sirve para manejar un vehículo como chofer.","p":"¡Correcto! La clase D es la licencia de chofer."},"ref":{"doc":"IA","page":null}},{"id":"ia-075","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, what is the youngest age to get a license that is valid only for a moped (motorized bicycle)?","o":["12","16","18","14"],"h1":"It is the same age as the earliest instruction permit.","h2":"In Iowa, a license valid only for a moped can be issued at age 14.","p":"Right! A moped-only license is possible at 14."},"es":{"q":"En Iowa, ¿cuál es la edad mínima para obtener una licencia válida solo para ciclomotor (moped)?","o":["12","16","18","14"],"h1":"Es la misma edad del primer permiso de aprendizaje.","h2":"En Iowa, una licencia válida solo para ciclomotor se puede obtener a los 14 años.","p":"¡Correcto! La licencia de ciclomotor se puede obtener a los 14."},"ref":{"doc":"IA","page":null}},{"id":"ia-076","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a 15-year-old applies for a moped-only license. What else must the teen do besides the vision and written tests?","o":["Finish a moped education course","Show a job offer","Own the moped","Wait until the teen has a passport"],"h1":"Riders under 16 need some training first.","h2":"In Iowa, an applicant under 16 for a moped-only license must also complete an approved moped education course.","p":"Correct! Under 16, a moped education course is required."},"es":{"q":"En Iowa, un joven de 15 años solicita una licencia solo para ciclomotor. ¿Qué más debe hacer, además de las pruebas de la vista y el examen escrito?","o":["Terminar un curso de educación para ciclomotor","Mostrar una oferta de trabajo","Ser dueño del ciclomotor","Tener pasaporte"],"h1":"Los menores de 16 años necesitan entrenamiento primero.","h2":"En Iowa, quien solicita una licencia de ciclomotor y tiene menos de 16 años también debe completar un curso aprobado de educación para ciclomotor.","p":"¡Correcto! Antes de los 16 se exige el curso de ciclomotor."},"ref":{"doc":"IA","page":null}},{"id":"ia-077","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a rider with a moped-only license is convicted of a moving violation. What happens to that license?","o":["Nothing, mopeds are not cars","It is canceled, and the rider may reapply after 30 days","It is suspended for 2 years","The rider gets 6 points"],"h1":"A moped-only license is easy to lose.","h2":"In Iowa, a moped-only license is canceled after a moving violation conviction, and the rider may apply again 30 days later.","p":"Right! It is canceled, and you can reapply after 30 days."},"es":{"q":"En Iowa, un conductor con licencia solo para ciclomotor recibe una condena por una infracción de tránsito. ¿Qué pasa con esa licencia?","o":["Nada, los ciclomotores no son carros","Se cancela, y puede volver a solicitarla después de 30 días","Se suspende por 2 años","Recibe 6 puntos"],"h1":"Una licencia solo para ciclomotor se pierde con facilidad.","h2":"En Iowa, la licencia solo para ciclomotor se cancela después de una condena por infracción de tránsito, y se puede volver a solicitar 30 días después.","p":"¡Correcto! Se cancela y puede volver a solicitarla a los 30 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-078","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, may you carry a passenger on a moped (motorized bicycle) on the road?","o":["Yes, if the passenger wears a helmet","Yes, but only in daylight","No, a moped rider may not carry anyone else","Yes, if the passenger is under 12"],"h1":"A moped is meant for one person.","h2":"In Iowa, a person riding a moped on the highway may not carry any other person.","p":"Correct! No passengers on a moped."},"es":{"q":"En Iowa, ¿puede llevar un pasajero en un ciclomotor (moped) en la vía pública?","o":["Sí, si el pasajero usa casco","Sí, pero solo de día","No, quien maneja un ciclomotor no puede llevar a nadie más","Sí, si el pasajero tiene menos de 12 años"],"h1":"Un ciclomotor es para una sola persona.","h2":"En Iowa, quien maneja un ciclomotor en la carretera no puede llevar a otra persona.","p":"¡Correcto! No se llevan pasajeros en ciclomotor."},"ref":{"doc":"IA","page":null}},{"id":"ia-079","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, what must a moped (motorized bicycle) have on the back when ridden on a highway?","o":["A spare tire","A white license light only","A red flag 2 feet high","A bright triangular safety flag at least 5 feet above the ground"],"h1":"It helps other drivers see the small vehicle from far away.","h2":"In Iowa, a moped on a highway must have a triangular, Day-Glo safety flag that reaches at least 5 feet above the ground.","p":"Right! A bright flag at least 5 feet high."},"es":{"q":"En Iowa, ¿qué debe llevar atrás un ciclomotor (moped) cuando circula por una carretera?","o":["Una llanta de repuesto","Solo una luz blanca para la placa","Una bandera roja de 2 pies de alto","Una bandera triangular de color brillante, al menos a 5 pies del suelo"],"h1":"Ayuda a que otros conductores vean el vehículo pequeño desde lejos.","h2":"En Iowa, un ciclomotor en carretera debe llevar una bandera de seguridad triangular de color fluorescente que llegue al menos a 5 pies del suelo.","p":"¡Correcto! Una bandera brillante de al menos 5 pies de alto."},"ref":{"doc":"IA","page":null}},{"id":"ia-080","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a 30-year-old gets a regular driver's license. For how long is it usually valid?","o":["8 years","2 years","4 years","10 years"],"h1":"It is longer than five years.","h2":"In Iowa, a driver's license issued to someone from about 18 to 78 years old is usually valid for 8 years.","p":"Correct! It is usually valid for 8 years."},"es":{"q":"En Iowa, una persona de 30 años obtiene una licencia de conducir normal. ¿Por cuánto tiempo suele ser válida?","o":["8 años","2 años","4 años","10 años"],"h1":"Es más de cinco años.","h2":"En Iowa, la licencia de una persona de aproximadamente 18 a 78 años suele ser válida por 8 años.","p":"¡Correcto! Suele ser válida por 8 años."},"ref":{"doc":"IA","page":null}},{"id":"ia-081","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a driver who is 80 years old renews a license. For how long is the new license valid?","o":["8 years","2 years","5 years","Only 6 months"],"h1":"Older drivers renew more often.","h2":"In Iowa, a license issued to a driver 78 or older is valid for 2 years.","p":"Right! At 78 or older, the license lasts 2 years."},"es":{"q":"En Iowa, un conductor de 80 años renueva su licencia. ¿Por cuánto tiempo es válida la nueva licencia?","o":["8 años","2 años","5 años","Solo 6 meses"],"h1":"Los conductores mayores renuevan con más frecuencia.","h2":"En Iowa, la licencia de un conductor de 78 años o más es válida por 2 años.","p":"¡Correcto! A partir de los 78, la licencia dura 2 años."},"ref":{"doc":"IA","page":null}},{"id":"ia-082","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, your license expired 3 weeks ago. Is driving with it treated as driving with an invalid license?","o":["Yes, from the first day after it expires","Yes, after 7 days","No, there is a 60-day grace period","No, an expired license is always valid"],"h1":"Iowa gives you a short time to renew.","h2":"In Iowa, you are not considered to be driving with an invalid license during the 60 days after your license expires.","p":"Correct! There is a 60-day grace period."},"es":{"q":"En Iowa, su licencia venció hace 3 semanas. ¿Se considera que maneja con una licencia no válida?","o":["Sí, desde el primer día después del vencimiento","Sí, después de 7 días","No, hay un periodo de gracia de 60 días","No, una licencia vencida siempre es válida"],"h1":"Iowa le da un poco de tiempo para renovar.","h2":"En Iowa, no se considera que maneja con una licencia no válida durante los 60 días después del vencimiento.","p":"¡Correcto! Hay un periodo de gracia de 60 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-083","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, until how long after it expires can you renew a regular license without taking the driving or written test again?","o":["30 days","90 days","5 years","1 year"],"h1":"Think of one full year.","h2":"In Iowa, a regular license can be renewed without a driving test or written test within one year after it expires.","p":"Right! You have up to one year."},"es":{"q":"En Iowa, ¿hasta cuánto tiempo después del vencimiento puede renovar una licencia normal sin volver a hacer la prueba de manejo ni el examen escrito?","o":["30 días","90 días","5 años","1 año"],"h1":"Piense en un año completo.","h2":"En Iowa, una licencia normal se puede renovar sin prueba de manejo ni examen escrito dentro del año siguiente a su vencimiento.","p":"¡Correcto! Tiene hasta un año."},"ref":{"doc":"IA","page":null}},{"id":"ia-084","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, you renewed your license online last time. Can you renew online again this time?","o":["No, you cannot renew online two times in a row","Yes, you can always renew online","Yes, but only if you are over 65","No, online renewal is only for new drivers"],"h1":"Every other renewal needs a visit in person.","h2":"In Iowa, you may not renew online if your most recent renewal was also done online.","p":"Correct! You cannot renew online twice in a row."},"es":{"q":"En Iowa, la última vez renovó su licencia por internet. ¿Puede renovarla por internet otra vez?","o":["No, no puede renovar por internet dos veces seguidas","Sí, siempre puede renovar por internet","Sí, pero solo si tiene más de 65 años","No, la renovación por internet es solo para conductores nuevos"],"h1":"Una renovación de cada dos se hace en persona.","h2":"En Iowa, no puede renovar por internet si su renovación anterior también fue por internet.","p":"¡Correcto! No se puede renovar por internet dos veces seguidas."},"ref":{"doc":"IA","page":null}},{"id":"ia-085","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, you are out of state when your license is due for renewal. For how long can Iowa give you a temporary extension?","o":["Up to 2 years","Up to 6 months","Up to 10 days","Iowa does not give extensions"],"h1":"It is half a year at most.","h2":"In Iowa, a resident who is temporarily out of state may get a temporary license extension of up to 6 months.","p":"Right! An extension can last up to 6 months."},"es":{"q":"En Iowa, usted está fuera del estado cuando le toca renovar la licencia. ¿Por cuánto tiempo puede Iowa darle una extensión temporal?","o":["Hasta 2 años","Hasta 6 meses","Hasta 10 días","Iowa no da extensiones"],"h1":"Es medio año como máximo.","h2":"En Iowa, un residente que está temporalmente fuera del estado puede recibir una extensión temporal de la licencia de hasta 6 meses.","p":"¡Correcto! La extensión puede durar hasta 6 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-086","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, who may get a restricted work license?","o":["Any 14-year-old with a job offer","Adults whose license was revoked for OWI","A 16- or 17-year-old who finished driver education, is not in school, and needs to drive to work","Teens who want to drive friends to sports practice"],"h1":"It is for teens who left school and need to keep a job.","h2":"In Iowa, a restricted work license may go to a 16- or 17-year-old who finished driver education, is not attending school and needs to drive to work.","p":"Correct! It is for teens out of school who must drive to work."},"es":{"q":"En Iowa, ¿quién puede obtener una licencia restringida para trabajar?","o":["Cualquier joven de 14 años con una oferta de trabajo","Adultos a quienes les revocaron la licencia por manejar intoxicados","Un joven de 16 o 17 años que terminó la educación vial, no va a la escuela y necesita manejar al trabajo","Jóvenes que quieren llevar a sus amigos a practicar deportes"],"h1":"Es para jóvenes que dejaron la escuela y necesitan conservar un empleo.","h2":"En Iowa, una licencia restringida para trabajar puede darse a un joven de 16 o 17 años que terminó la educación vial, no asiste a la escuela y necesita manejar al trabajo.","p":"¡Correcto! Es para jóvenes fuera de la escuela que deben manejar al trabajo."},"ref":{"doc":"IA","page":null}},{"id":"ia-087","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, what is the scheduled fine for driving without a valid driver's license?","o":["$30","$70","$1,000","$260"],"h1":"It is a few hundred dollars.","h2":"In Iowa, the scheduled fine for driving without a valid driver's license is $260.","p":"Right! The scheduled fine is $260."},"es":{"q":"En Iowa, ¿cuál es la multa fija por manejar sin una licencia de conducir válida?","o":["$30","$70","$1,000","$260"],"h1":"Son unos cientos de dólares.","h2":"En Iowa, la multa fija por manejar sin una licencia de conducir válida es de $260.","p":"¡Correcto! La multa fija es de $260."},"ref":{"doc":"IA","page":null}},{"id":"ia-088","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, what is the minimum liability insurance for injury to one person in a crash?","o":["$20,000","$10,000","$50,000","$100,000"],"h1":"The three Iowa limits are 20, 40 and 15 thousand.","h2":"In Iowa, liability insurance must cover at least $20,000 for injury or death of one person in a crash.","p":"Correct! The minimum is $20,000 for one person."},"es":{"q":"En Iowa, ¿cuál es el seguro mínimo de responsabilidad civil por lesiones a una persona en un choque?","o":["$20,000","$10,000","$50,000","$100,000"],"h1":"Los tres límites de Iowa son 20, 40 y 15 mil.","h2":"En Iowa, el seguro de responsabilidad civil debe cubrir al menos $20,000 por lesiones o muerte de una persona en un choque.","p":"¡Correcto! El mínimo es $20,000 por persona."},"ref":{"doc":"IA","page":null}},{"id":"ia-089","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$5,000","$15,000","$25,000","$40,000"],"h1":"It is the smallest of the three Iowa limits.","h2":"In Iowa, liability insurance must cover at least $15,000 for damage to the property of others in one crash.","p":"Right! Property damage coverage starts at $15,000."},"es":{"q":"En Iowa, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$5,000","$15,000","$25,000","$40,000"],"h1":"Es el más pequeño de los tres límites de Iowa.","h2":"En Iowa, el seguro de responsabilidad civil debe cubrir al menos $15,000 por daños a la propiedad de otros en un choque.","p":"¡Correcto! La cobertura por daños a la propiedad empieza en $15,000."},"ref":{"doc":"IA","page":null}},{"id":"ia-090","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, you are stopped and cannot show proof of insurance, but there was no crash. What is the scheduled fine?","o":["$50","$135","$325","$1,250"],"h1":"It is more than $300.","h2":"In Iowa, the scheduled fine for driving without proof of insurance is $325 when no crash is involved.","p":"Correct! The scheduled fine is $325."},"es":{"q":"En Iowa, lo detienen y no puede mostrar comprobante de seguro, pero no hubo choque. ¿Cuál es la multa fija?","o":["$50","$135","$325","$1,250"],"h1":"Es más de $300.","h2":"En Iowa, la multa fija por manejar sin comprobante de seguro es de $325 cuando no hubo choque.","p":"¡Correcto! La multa fija es de $325."},"ref":{"doc":"IA","page":null}},{"id":"ia-091","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, a driver with no insurance is found guilty after a crash. What is the scheduled fine?","o":["$135","$325","$260","$645"],"h1":"It is about double the fine when there is no crash.","h2":"In Iowa, the scheduled fine for having no insurance is $645 when it is connected with a crash.","p":"Right! With a crash, the fine is $645."},"es":{"q":"En Iowa, un conductor sin seguro es declarado culpable después de un choque. ¿Cuál es la multa fija?","o":["$135","$325","$260","$645"],"h1":"Es más o menos el doble de la multa cuando no hay choque.","h2":"En Iowa, la multa fija por no tener seguro es de $645 cuando está relacionada con un choque.","p":"¡Correcto! Con choque, la multa es de $645."},"ref":{"doc":"IA","page":null}},{"id":"ia-092","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, an officer takes the license plates of a car with no insurance. How long may the car still be driven, and why?","o":["Up to 48 hours, only to remove it from the road","Up to 30 days, for any reason","Until the owner's birthday","It may not be moved at all, even by a tow truck"],"h1":"It is a short time, just to get the car off the road.","h2":"In Iowa, after an officer removes the plates of an uninsured car, it may be driven for up to 48 hours only to remove it from the highways.","p":"Correct! Up to 48 hours, only to get it off the road."},"es":{"q":"En Iowa, un agente quita las placas de un carro sin seguro. ¿Por cuánto tiempo se puede manejar todavía el carro, y para qué?","o":["Hasta 48 horas, solo para sacarlo de la carretera","Hasta 30 días, para cualquier fin","Hasta el cumpleaños del dueño","No se puede mover, ni siquiera con grúa"],"h1":"Es poco tiempo, solo para retirar el carro de la vía.","h2":"En Iowa, después de que un agente quita las placas a un carro sin seguro, se puede manejar hasta 48 horas solo para sacarlo de las carreteras.","p":"¡Correcto! Hasta 48 horas, solo para sacarlo de la vía."},"ref":{"doc":"IA","page":null}},{"id":"ia-093","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a driver has autism. What can the driver ask to have added to the license?","o":["A special parking permit sticker","An indicator that police can see on the license and in their database","A different license class","Nothing can be added"],"h1":"It helps an officer prepare during a traffic stop.","h2":"In Iowa, a driver with autism, or who is deaf or hard of hearing, may choose to add an indicator to the license that police can also see in their database.","p":"Right! An indicator can be added to help during traffic stops."},"es":{"q":"En Iowa, un conductor tiene autismo. ¿Qué puede pedir que se agregue a su licencia?","o":["Una calcomanía especial de estacionamiento","Un indicador que la policía puede ver en la licencia y en su base de datos","Una clase de licencia diferente","No se puede agregar nada"],"h1":"Ayuda al agente a prepararse durante una parada de tránsito.","h2":"En Iowa, un conductor con autismo, o sordo o con problemas de audición, puede pedir que se agregue un indicador a su licencia, que la policía también ve en su base de datos.","p":"¡Correcto! Se puede agregar un indicador para ayudar en las paradas de tránsito."},"ref":{"doc":"IA","page":64}},{"id":"ia-094","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, how long must a teen hold an instruction permit before getting a special minor's restricted license (school license)?","o":["1 month","3 months","6 months","12 months"],"h1":"It is half a year.","h2":"In Iowa, a teen must hold an instruction permit for at least 6 months, with a clean record, before getting a special minor's restricted license.","p":"Correct! The permit must be held for 6 months."},"es":{"q":"En Iowa, ¿cuánto tiempo debe tener un joven el permiso de aprendizaje antes de obtener la licencia restringida especial para menores (licencia escolar)?","o":["1 mes","3 meses","6 meses","12 meses"],"h1":"Es medio año.","h2":"En Iowa, el joven debe tener el permiso de aprendizaje al menos 6 meses, sin infracciones, antes de obtener la licencia restringida especial para menores.","p":"¡Correcto! El permiso se debe tener 6 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-095","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, school starts at 8 a.m. and ends at 3 p.m. When may a teen with a special minor's restricted license drive alone for school?","o":["Any time from 6 a.m. to 10 p.m.","Only from 7:45 to 8 a.m.","Any time on school days","From 7 to 8 a.m. and from 3 to 4 p.m."],"h1":"The window is one hour on each side.","h2":"In Iowa, a special minor's restricted license allows driving alone only in the hour before and the hour after school, activities or work.","p":"Right! One hour before and one hour after."},"es":{"q":"En Iowa, la escuela empieza a las 8 a.m. y termina a las 3 p.m. ¿Cuándo puede manejar solo, para ir a la escuela, un joven con licencia restringida especial para menores?","o":["A cualquier hora de 6 a.m. a 10 p.m.","Solo de 7:45 a 8 a.m.","A cualquier hora en días de clase","De 7 a 8 a.m. y de 3 a 4 p.m."],"h1":"El periodo es de una hora antes y una hora después.","h2":"En Iowa, la licencia restringida especial para menores permite manejar solo en la hora antes y la hora después de la escuela, las actividades o el trabajo.","p":"¡Correcto! Una hora antes y una hora después."},"ref":{"doc":"IA","page":null}},{"id":"ia-096","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen with a special minor's restricted license is driving to school and needs gas. Where may the teen stop?","o":["On the route, or at the closest gas station off the route","Only at a gas station next to the school","Anywhere within 50 miles","Nowhere; a parent must buy the gas"],"h1":"Refueling is allowed, but without a long detour.","h2":"In Iowa, a teen with a special minor's restricted license may stop for fuel along the route or at the closest station off the route.","p":"Correct! On the way, or at the nearest station."},"es":{"q":"En Iowa, un joven con licencia restringida especial para menores va a la escuela y necesita gasolina. ¿Dónde puede parar?","o":["En el camino, o en la gasolinera más cercana fuera de la ruta","Solo en una gasolinera junto a la escuela","En cualquier lugar a menos de 50 millas","En ningún lugar; un padre debe comprar la gasolina"],"h1":"Puede cargar gasolina, pero sin desviarse mucho.","h2":"En Iowa, un joven con licencia restringida especial para menores puede parar a cargar gasolina en la ruta o en la gasolinera más cercana fuera de ella.","p":"¡Correcto! En el camino, o en la estación más cercana."},"ref":{"doc":"IA","page":null}},{"id":"ia-097","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a public school student has a special minor's restricted license. Where may the student drive alone to school?","o":["To any school in Iowa","Within the school district where the student is enrolled","Only within 1 mile of home","Only on gravel roads"],"h1":"The limit follows school district lines.","h2":"In Iowa, a public school student with a special minor's restricted license may drive alone to school within the school district of enrollment.","p":"Right! Within the student's school district."},"es":{"q":"En Iowa, un estudiante de escuela pública tiene licencia restringida especial para menores. ¿Hasta dónde puede manejar solo a la escuela?","o":["A cualquier escuela de Iowa","Dentro del distrito escolar donde está inscrito","Solo a menos de 1 milla de su casa","Solo por caminos de grava"],"h1":"El límite sigue las líneas del distrito escolar.","h2":"En Iowa, un estudiante de escuela pública con licencia restringida especial para menores puede manejar solo a la escuela dentro del distrito escolar donde está inscrito.","p":"¡Correcto! Dentro de su distrito escolar."},"ref":{"doc":"IA","page":null}},{"id":"ia-098","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, may a teen with a special minor's restricted license pull a trailer while driving alone to work?","o":["Yes, if the trailer is small","Yes, on weekends only","No, towing another vehicle is not allowed","Yes, if the boss signs a note"],"h1":"This license has limits on the kind of vehicle.","h2":"In Iowa, a special minor's restricted license does not allow towing another vehicle or driving a vehicle with more than two axles.","p":"Correct! No towing with this license."},"es":{"q":"En Iowa, ¿puede un joven con licencia restringida especial para menores remolcar un tráiler cuando maneja solo al trabajo?","o":["Sí, si el tráiler es pequeño","Sí, solo los fines de semana","No, no se permite remolcar otro vehículo","Sí, si el jefe firma una nota"],"h1":"Esta licencia limita el tipo de vehículo.","h2":"En Iowa, la licencia restringida especial para menores no permite remolcar otro vehículo ni manejar un vehículo de más de dos ejes.","p":"¡Correcto! Con esta licencia no se remolca."},"ref":{"doc":"IA","page":null}},{"id":"ia-099","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, a teen with a special minor's restricted license lives part of the week with each parent. May the teen drive alone from one parent's home to the other?","o":["Yes, any time","Yes, if both homes are in Iowa","Yes, but only on weekends","No, the teen may not drive between residences"],"h1":"The license covers trips to school, activities and work, not between homes.","h2":"In Iowa, a teen with a special minor's restricted license may list up to three homes but may not drive alone between them.","p":"Right! Driving between homes is not allowed."},"es":{"q":"En Iowa, un joven con licencia restringida especial para menores vive parte de la semana con cada padre. ¿Puede manejar solo de la casa de un padre a la del otro?","o":["Sí, a cualquier hora","Sí, si ambas casas están en Iowa","Sí, pero solo los fines de semana","No, no puede manejar entre sus residencias"],"h1":"La licencia sirve para ir a la escuela, actividades y trabajo, no entre casas.","h2":"En Iowa, un joven con licencia restringida especial para menores puede anotar hasta tres casas, pero no puede manejar solo entre ellas.","p":"¡Correcto! No se permite manejar entre casas."},"ref":{"doc":"IA","page":null}},{"id":"ia-100","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen with a special minor's restricted license drives alone to a job. What must the teen carry in the vehicle?","o":["The parent's signed consent form for the job","A letter from the school principal","A copy of the parent's insurance bill","The car's purchase receipt"],"h1":"A parent approves the job location in writing.","h2":"In Iowa, a teen with a special minor's restricted license who drives to work must carry the parent's signed consent form and show it to an officer on request.","p":"Correct! The parent's consent form must be in the vehicle."},"es":{"q":"En Iowa, un joven con licencia restringida especial para menores maneja solo a su trabajo. ¿Qué debe llevar en el vehículo?","o":["El formulario de consentimiento firmado por su padre para ese trabajo","Una carta del director de la escuela","Una copia de la factura del seguro de los padres","El recibo de compra del carro"],"h1":"Un padre aprueba por escrito el lugar de trabajo.","h2":"En Iowa, un joven con licencia restringida especial para menores que maneja al trabajo debe llevar el formulario de consentimiento firmado por su padre y mostrarlo al agente si se lo pide.","p":"¡Correcto! El formulario de consentimiento debe estar en el vehículo."},"ref":{"doc":"IA","page":null}},{"id":"ia-101","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a teen with a special minor's restricted license wants to drive alone to an away game, just to watch. Is that allowed?","o":["Yes, if the game is within 25 miles","No, the teen may drive alone only to activities the teen takes part in","Yes, if a friend rides along","Yes, on Friday nights only"],"h1":"Watching is not the same as taking part.","h2":"In Iowa, a teen with a special minor's restricted license may not drive alone to another school's game just to watch; it covers activities the teen takes part in and events at the teen's own school.","p":"Right! Not to watch an away game."},"es":{"q":"En Iowa, un joven con licencia restringida especial para menores quiere manejar solo a un partido en otra escuela, solo para mirar. ¿Está permitido?","o":["Sí, si el partido está a menos de 25 millas","No, solo puede manejar solo a actividades en las que participa","Sí, si lo acompaña un amigo","Sí, pero solo los viernes por la noche"],"h1":"Mirar no es lo mismo que participar.","h2":"En Iowa, un joven con licencia restringida especial para menores no puede manejar solo al partido de otra escuela solo para mirar; la licencia cubre actividades en las que participa y eventos en su propia escuela.","p":"¡Correcto! No para mirar un partido fuera."},"ref":{"doc":"IA","page":null}},{"id":"ia-102","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, a teen with a special minor's restricted license gets a speeding ticket. What happens?","o":["Only a warning letter","A one-week suspension","A three-month suspension","Nothing until the teen turns 16"],"h1":"Every ticket on this license leads to the same length of suspension.","h2":"In Iowa, a ticket, a restriction violation or an at-fault crash on a special minor's restricted license leads to a three-month suspension.","p":"Correct! Each violation means a three-month suspension."},"es":{"q":"En Iowa, un joven con licencia restringida especial para menores recibe una multa por exceso de velocidad. ¿Qué pasa?","o":["Solo una carta de advertencia","Una suspensión de una semana","Una suspensión de tres meses","Nada hasta que cumpla 16 años"],"h1":"Cada multa con esta licencia lleva a la misma suspensión.","h2":"En Iowa, una multa, una violación de restricciones o un choque por su culpa con licencia restringida especial para menores lleva a una suspensión de tres meses.","p":"¡Correcto! Cada falta significa tres meses de suspensión."},"ref":{"doc":"IA","page":null}},{"id":"ia-103","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, after a suspension of a special minor's restricted license ends, what is the reinstatement fee?","o":["$100","$5","$250","$20"],"h1":"It is a small fee, plus the cost of a new license card.","h2":"In Iowa, getting a special minor's restricted license back after a suspension costs a $20 reinstatement fee, plus $10 for a duplicate license.","p":"Right! The reinstatement fee is $20."},"es":{"q":"En Iowa, cuando termina la suspensión de una licencia restringida especial para menores, ¿cuánto cuesta la reinstalación?","o":["$100","$5","$250","$20"],"h1":"Es un cargo pequeño, más el costo de una nueva tarjeta.","h2":"En Iowa, recuperar la licencia restringida especial para menores después de una suspensión cuesta $20 de reinstalación, más $10 por un duplicado.","p":"¡Correcto! La reinstalación cuesta $20."},"ref":{"doc":"IA","page":null}},{"id":"ia-104","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, a teen's special minor's restricted license was suspended once. How does that affect getting an intermediate license?","o":["The teen waits an extra 3 months after turning 16","There is no effect","The teen must wait until 18","The teen waits an extra 2 years"],"h1":"The delay is the same length as the suspension.","h2":"In Iowa, after a special minor's restricted license is suspended, the intermediate license is delayed by an extra three months after the 16th birthday for each violation.","p":"Correct! An extra 3 months after the 16th birthday."},"es":{"q":"En Iowa, a un joven le suspendieron una vez la licencia restringida especial para menores. ¿Cómo afecta esto a la licencia intermedia?","o":["Espera 3 meses más después de cumplir 16","No tiene efecto","Debe esperar hasta los 18","Espera 2 años más"],"h1":"La demora dura lo mismo que la suspensión.","h2":"En Iowa, después de una suspensión de la licencia restringida especial para menores, la licencia intermedia se retrasa tres meses más después de cumplir 16 años por cada falta.","p":"¡Correcto! Tres meses más después de cumplir 16."},"ref":{"doc":"IA","page":null}},{"id":"ia-105","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, a teen breaks a rule of an instruction permit or intermediate license, such as the passenger limit. What is the scheduled fine?","o":["$25","$70","$300","$1,000"],"h1":"It is less than $100.","h2":"In Iowa, the scheduled fine for breaking the restrictions of a teen instruction permit or intermediate license is $70.","p":"Right! The scheduled fine is $70."},"es":{"q":"En Iowa, un adolescente no cumple una regla de su permiso de aprendizaje o licencia intermedia, como el límite de pasajeros. ¿Cuál es la multa fija?","o":["$25","$70","$300","$1,000"],"h1":"Es menos de $100.","h2":"En Iowa, la multa fija por no cumplir las restricciones del permiso de aprendizaje o la licencia intermedia de un adolescente es de $70.","p":"¡Correcto! La multa fija es de $70."},"ref":{"doc":"IA","page":null}},{"id":"ia-106","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, how many moving violations within 12 months make you a habitual violator whose license can be suspended?","o":["One","Two","Three or more","Ten or more"],"h1":"It is more than two.","h2":"In Iowa, a habitual violator is a person convicted of three or more moving violations within 12 months, and the license can be suspended.","p":"Correct! Three or more in 12 months."},"es":{"q":"En Iowa, ¿cuántas infracciones de tránsito en 12 meses lo convierten en infractor habitual, con posible suspensión de la licencia?","o":["Una","Dos","Tres o más","Diez o más"],"h1":"Es más de dos.","h2":"En Iowa, un infractor habitual es una persona condenada por tres o más infracciones de tránsito en 12 meses, y su licencia se puede suspender.","p":"¡Correcto! Tres o más en 12 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-107","scope":"IA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Iowa, an adult is convicted of exactly three moving violations within 12 months. What is the minimum suspension?","o":["7 days","30 days","2 years","90 days"],"h1":"It is about three months.","h2":"In Iowa, three moving violation convictions within 12 months bring a minimum suspension of 90 days, unless a hearing officer lowers it.","p":"Right! The minimum is 90 days."},"es":{"q":"En Iowa, un adulto recibe exactamente tres condenas por infracciones de tránsito en 12 meses. ¿Cuál es la suspensión mínima?","o":["7 días","30 días","2 años","90 días"],"h1":"Son unos tres meses.","h2":"En Iowa, tres condenas por infracciones de tránsito en 12 meses llevan a una suspensión mínima de 90 días, salvo que un oficial de audiencias la reduzca.","p":"¡Correcto! El mínimo es de 90 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-108","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, a driver is convicted of going 25 mph over the speed limit. What can happen to the license?","o":["It can be suspended for at least 60 days","Nothing beyond the fine","It is revoked for life","It is suspended for 1 day"],"h1":"Going 25 mph or more over is treated as a serious violation.","h2":"In Iowa, speeding 25 mph or more over the limit is a serious violation, and the license can be suspended for at least 60 days.","p":"Correct! At least 60 days of suspension."},"es":{"q":"En Iowa, condenan a un conductor por ir 25 mph por encima del límite de velocidad. ¿Qué puede pasar con su licencia?","o":["Se puede suspender por al menos 60 días","Nada además de la multa","Se revoca de por vida","Se suspende por 1 día"],"h1":"Ir 25 mph o más por encima se trata como una falta grave.","h2":"En Iowa, ir 25 mph o más por encima del límite es una falta grave, y la licencia se puede suspender por al menos 60 días.","p":"¡Correcto! Al menos 60 días de suspensión."},"ref":{"doc":"IA","page":null}},{"id":"ia-109","scope":"IA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Iowa, which speeding tickets are not counted when deciding to suspend a license?","o":["All tickets on interstates","The first two in 12 months for 10 mph or less over, in zones from 35 to 55 mph","Any ticket paid within 30 days","Tickets from other states"],"h1":"Small speeding tickets on mid-speed roads get some leeway.","h2":"In Iowa, the first two speeding tickets in 12 months for 10 mph or less over the limit, in zones from 35 to 55 mph, are not counted toward a suspension.","p":"Right! The first two small ones in 35 to 55 mph zones are not counted."},"es":{"q":"En Iowa, ¿qué multas por exceso de velocidad no se cuentan al decidir suspender una licencia?","o":["Todas las multas en autopistas interestatales","Las dos primeras en 12 meses por 10 mph o menos sobre el límite, en zonas de 35 a 55 mph","Cualquier multa pagada en 30 días","Las multas de otros estados"],"h1":"Las multas pequeñas en vías de velocidad media tienen cierta tolerancia.","h2":"En Iowa, las dos primeras multas en 12 meses por 10 mph o menos sobre el límite, en zonas de 35 a 55 mph, no cuentan para una suspensión.","p":"¡Correcto! Las dos primeras multas pequeñas en zonas de 35 a 55 mph no cuentan."},"ref":{"doc":"IA","page":null}},{"id":"ia-110","scope":"IA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Iowa, you get a ticket for a broken tail light. How can you keep it from counting toward a license suspension?","o":["Pay double the fine","Take a defensive driving class within a year","Fix it within 72 hours and send proof to the DOT","Nothing; it always counts"],"h1":"Quick repairs are rewarded.","h2":"In Iowa, an equipment violation is not counted toward suspension if the repair is made within 72 hours and proof is sent right away to the Department of Transportation.","p":"Correct! Repair it within 72 hours and send proof."},"es":{"q":"En Iowa, le ponen una multa por una luz trasera rota. ¿Cómo evita que cuente para una suspensión de la licencia?","o":["Pagando el doble de la multa","Tomando un curso de manejo defensivo en un año","Reparándola en 72 horas y enviando la prueba al Departamento de Transporte","De ninguna forma; siempre cuenta"],"h1":"Las reparaciones rápidas tienen ventaja.","h2":"En Iowa, una falta de equipo no cuenta para la suspensión si se repara en 72 horas y se envía de inmediato la prueba al Departamento de Transporte.","p":"¡Correcto! Repárela en 72 horas y envíe la prueba."},"ref":{"doc":"IA","page":null}},{"id":"ia-111","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a driver's blood alcohol is 0.00, but a blood test finds a small amount of an illegal drug. Is this operating while intoxicated (OWI)?","o":["No, only alcohol counts","No, unless the driver crashed","Only if the amount is large","Yes, any amount of a controlled substance counts"],"h1":"Iowa sets no minimum amount for illegal drugs.","h2":"In Iowa, driving with any amount of a controlled substance in your system is operating while intoxicated.","p":"Right! Any amount of a controlled substance counts as OWI."},"es":{"q":"En Iowa, el alcohol en la sangre de un conductor es 0.00, pero un análisis encuentra una pequeña cantidad de una droga ilegal. ¿Es esto manejar intoxicado (OWI)?","o":["No, solo cuenta el alcohol","No, salvo que haya chocado","Solo si la cantidad es grande","Sí, cualquier cantidad de una sustancia controlada cuenta"],"h1":"Iowa no fija una cantidad mínima para las drogas ilegales.","h2":"En Iowa, manejar con cualquier cantidad de una sustancia controlada en el cuerpo es manejar intoxicado.","p":"¡Correcto! Cualquier cantidad de una sustancia controlada cuenta como OWI."},"ref":{"doc":"IA","page":37}},{"id":"ia-112","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, what is the minimum jail time for a first OWI (drunk driving) conviction?","o":["48 hours","No jail time","30 days","1 year"],"h1":"It is two days.","h2":"In Iowa, a first OWI conviction carries at least 48 hours in jail.","p":"Correct! At least 48 hours in jail."},"es":{"q":"En Iowa, ¿cuál es el tiempo mínimo de cárcel por una primera condena por manejar intoxicado (OWI)?","o":["48 horas","Nada de cárcel","30 días","1 año"],"h1":"Son dos días.","h2":"En Iowa, una primera condena por manejar intoxicado lleva al menos 48 horas de cárcel.","p":"¡Correcto! Al menos 48 horas de cárcel."},"ref":{"doc":"IA","page":null}},{"id":"ia-113","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, what fine does the court assess for a first OWI (drunk driving) conviction?","o":["$135","$1,250","$500","$10,000"],"h1":"It is more than one thousand dollars.","h2":"In Iowa, a first OWI conviction brings a fine of $1,250, which the court may partly waive in some cases.","p":"Right! The fine is $1,250."},"es":{"q":"En Iowa, ¿qué multa impone el tribunal por una primera condena por manejar intoxicado (OWI)?","o":["$135","$1,250","$500","$10,000"],"h1":"Es más de mil dólares.","h2":"En Iowa, una primera condena por manejar intoxicado lleva una multa de $1,250, que el tribunal puede reducir en algunos casos.","p":"¡Correcto! La multa es de $1,250."},"ref":{"doc":"IA","page":null}},{"id":"ia-114","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, what is the minimum jail time for a second OWI (drunk driving) offense?","o":["48 hours","1 day","7 days","6 months"],"h1":"It is one week.","h2":"In Iowa, a second OWI offense carries at least 7 days in jail.","p":"Correct! At least 7 days."},"es":{"q":"En Iowa, ¿cuál es el tiempo mínimo de cárcel por una segunda falta de manejar intoxicado (OWI)?","o":["48 horas","1 día","7 días","6 meses"],"h1":"Es una semana.","h2":"En Iowa, una segunda falta de manejar intoxicado lleva al menos 7 días de cárcel.","p":"¡Correcto! Al menos 7 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-115","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, what is the minimum fine for a second OWI (drunk driving) offense?","o":["$500","$1,250","$3,125","$1,875"],"h1":"It is between the first-offense fine and the third-offense fine.","h2":"In Iowa, a second OWI offense brings a fine of at least $1,875.","p":"Right! At least $1,875."},"es":{"q":"En Iowa, ¿cuál es la multa mínima por una segunda falta de manejar intoxicado (OWI)?","o":["$500","$1,250","$3,125","$1,875"],"h1":"Está entre la multa de la primera falta y la de la tercera.","h2":"En Iowa, una segunda falta de manejar intoxicado lleva una multa de al menos $1,875.","p":"¡Correcto! Al menos $1,875."},"ref":{"doc":"IA","page":null}},{"id":"ia-116","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, a driver is convicted of a third OWI (drunk driving) offense. How long is the license revoked?","o":["6 years","1 year","90 days","2 years"],"h1":"A third offense is a felony with a very long revocation.","h2":"In Iowa, a third OWI offense is a felony, and the driver's license is revoked for 6 years.","p":"Correct! The license is revoked for 6 years."},"es":{"q":"En Iowa, condenan a un conductor por una tercera falta de manejar intoxicado (OWI). ¿Por cuánto tiempo le revocan la licencia?","o":["6 años","1 año","90 días","2 años"],"h1":"La tercera falta es un delito grave con una revocación muy larga.","h2":"En Iowa, la tercera falta de manejar intoxicado es un delito grave, y la licencia se revoca por 6 años.","p":"¡Correcto! La licencia se revoca por 6 años."},"ref":{"doc":"IA","page":null}},{"id":"ia-117","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, a driver who already had an OWI revocation refuses a breath test again. How long is the license revoked?","o":["1 year","2 years","180 days","30 days"],"h1":"It is double the first refusal period.","h2":"In Iowa, refusing a chemical test after a previous OWI revocation leads to a 2-year revocation.","p":"Right! A repeat refusal means 2 years."},"es":{"q":"En Iowa, un conductor que ya tuvo una revocación por OWI se niega otra vez a la prueba de aliento. ¿Por cuánto tiempo le revocan la licencia?","o":["1 año","2 años","180 días","30 días"],"h1":"Es el doble del periodo por la primera negativa.","h2":"En Iowa, negarse a una prueba química después de una revocación anterior por OWI lleva a una revocación de 2 años.","p":"¡Correcto! Una negativa repetida significa 2 años."},"ref":{"doc":"IA","page":null}},{"id":"ia-118","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, a driver fails a breath test and the officer takes the license on the spot. How long is the temporary license the officer gives valid?","o":["24 hours","30 days","10 days","Until the trial"],"h1":"It is a little more than one week.","h2":"In Iowa, when an officer takes a license after a failed or refused test, the driver gets a temporary license valid for 10 days.","p":"Correct! The temporary license lasts 10 days."},"es":{"q":"En Iowa, un conductor no pasa la prueba de aliento y el agente le quita la licencia en el momento. ¿Por cuánto tiempo es válida la licencia temporal que le da el agente?","o":["24 horas","30 días","10 días","Hasta el juicio"],"h1":"Es un poco más de una semana.","h2":"En Iowa, cuando un agente quita la licencia después de una prueba fallida o rechazada, el conductor recibe una licencia temporal válida por 10 días.","p":"¡Correcto! La licencia temporal dura 10 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-119","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a driver whose license was revoked for OWI asks for a temporary restricted license. What must be installed first?","o":["A dash camera","A GPS tracker","New tires","An ignition interlock device in every vehicle the person drives"],"h1":"It is a device that checks your breath before the car starts.","h2":"In Iowa, a person revoked for OWI must install an ignition interlock device on all vehicles they drive before getting a temporary restricted license.","p":"Right! An ignition interlock device is required."},"es":{"q":"En Iowa, una persona con la licencia revocada por OWI pide una licencia temporal restringida. ¿Qué debe instalar primero?","o":["Una cámara en el tablero","Un rastreador GPS","Llantas nuevas","Un dispositivo de bloqueo de encendido en cada vehículo que maneje"],"h1":"Es un aparato que revisa su aliento antes de que arranque el carro.","h2":"En Iowa, una persona con la licencia revocada por OWI debe instalar un dispositivo de bloqueo de encendido en todos los vehículos que maneja antes de recibir una licencia temporal restringida.","p":"¡Correcto! Se exige el dispositivo de bloqueo de encendido."},"ref":{"doc":"IA","page":null}},{"id":"ia-120","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, a 19-year-old who already had one alcohol revocation is caught again driving with a blood alcohol of 0.04. How long is the license revoked?","o":["90 days","60 days","30 days","6 years"],"h1":"It is longer than the first time, which is 60 days.","h2":"In Iowa, a driver under 21 with a level from 0.02 to under 0.08 loses the license for 90 days if there was a previous revocation.","p":"Correct! A repeat under-21 revocation is 90 days."},"es":{"q":"En Iowa, un joven de 19 años que ya tuvo una revocación por alcohol es detenido otra vez manejando con 0.04 de alcohol en la sangre. ¿Por cuánto tiempo le revocan la licencia?","o":["90 días","60 días","30 días","6 años"],"h1":"Es más que la primera vez, que es de 60 días.","h2":"En Iowa, un conductor menor de 21 años con un nivel de 0.02 a menos de 0.08 pierde la licencia por 90 días si ya tuvo una revocación anterior.","p":"¡Correcto! La revocación repetida para menores de 21 es de 90 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-121","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, a driver from another state is visiting. Does Iowa's implied consent law for alcohol testing apply to this driver?","o":["No, only to Iowa license holders","Yes, it also applies to nonresidents driving in Iowa","Only if the driver stays more than 30 days","Only for commercial drivers"],"h1":"Driving on Iowa roads is what matters.","h2":"In Iowa, the implied consent law for alcohol and drug testing also applies to nonresident drivers traveling in the state.","p":"Right! It applies to visitors too."},"es":{"q":"En Iowa, un conductor de otro estado está de visita. ¿Se le aplica la ley de consentimiento implícito de Iowa para las pruebas de alcohol?","o":["No, solo a quienes tienen licencia de Iowa","Sí, también se aplica a los no residentes que manejan en Iowa","Solo si se queda más de 30 días","Solo a los conductores comerciales"],"h1":"Lo que importa es manejar en las carreteras de Iowa.","h2":"En Iowa, la ley de consentimiento implícito para pruebas de alcohol y drogas también se aplica a los conductores no residentes que viajan por el estado.","p":"¡Correcto! También se aplica a los visitantes."},"ref":{"doc":"IA","page":37}},{"id":"ia-122","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, your SUV has no trunk. Where may you carry an opened bottle of wine?","o":["In the glove compartment","Under the driver's seat","Behind the last upright seat","In a passenger's lap, if the cap is on"],"h1":"It must be away from where people sit and reach.","h2":"In Iowa, if a vehicle has no trunk, an open container of alcohol may be carried behind the last upright seat.","p":"Correct! Behind the last upright seat."},"es":{"q":"En Iowa, su camioneta no tiene cajuela. ¿Dónde puede llevar una botella de vino abierta?","o":["En la guantera","Debajo del asiento del conductor","Detrás del último asiento en posición vertical","En las piernas de un pasajero, si tiene la tapa puesta"],"h1":"Debe estar lejos de donde la gente se sienta y alcanza.","h2":"En Iowa, si el vehículo no tiene cajuela, un envase abierto de alcohol se puede llevar detrás del último asiento en posición vertical.","p":"¡Correcto! Detrás del último asiento vertical."},"ref":{"doc":"IA","page":null}},{"id":"ia-123","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Iowa driver's manual, being awake for 18 hours straight impairs you about as much as which blood alcohol level?","o":["0.01","0.02","0.20","0.08"],"h1":"It is the level that makes an adult legally drunk.","h2":"The Iowa driver's manual says being awake for 18 hours straight is as impairing as a blood alcohol level of 0.08.","p":"Right! Eighteen hours awake is like 0.08."},"es":{"q":"Según el manual de manejo de Iowa, estar despierto 18 horas seguidas lo afecta más o menos como ¿qué nivel de alcohol en la sangre?","o":["0.01","0.02","0.20","0.08"],"h1":"Es el nivel en que un adulto está legalmente ebrio.","h2":"El manual de manejo de Iowa dice que estar despierto 18 horas seguidas afecta tanto como un nivel de alcohol en la sangre de 0.08.","p":"¡Correcto! Dieciocho horas despierto es como 0.08."},"ref":{"doc":"IA","page":37}},{"id":"ia-124","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, at what blood alcohol level is a driver 21 or older legally operating while intoxicated?","o":["0.08 or more","0.05 or more","0.10 or more","0.15 or more"],"h1":"It is the same level used in most states.","h2":"In Iowa, a driver 21 or older is operating while intoxicated with a blood alcohol level of 0.08 or more.","p":"Correct! The adult limit is 0.08."},"es":{"q":"En Iowa, ¿con qué nivel de alcohol en la sangre un conductor de 21 años o más maneja intoxicado según la ley?","o":["0.08 o más","0.05 o más","0.10 o más","0.15 o más"],"h1":"Es el mismo nivel que se usa en la mayoría de los estados.","h2":"En Iowa, un conductor de 21 años o más maneja intoxicado con un nivel de alcohol en la sangre de 0.08 o más.","p":"¡Correcto! El límite para adultos es 0.08."},"ref":{"doc":"IA","page":37}},{"id":"ia-125","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, under the hands-free law, may you type an address into the GPS on your phone while driving?","o":["Yes, at speeds under 25 mph","No, you may not enter an address while driving","Yes, if the phone is in a mount","Yes, at a red light"],"h1":"Set your route before the car moves.","h2":"In Iowa, the hands-free law does not let you enter an address into a GPS on your phone while driving.","p":"Right! Enter the address before you drive."},"es":{"q":"En Iowa, según la ley de manos libres, ¿puede escribir una dirección en el GPS de su teléfono mientras maneja?","o":["Sí, a menos de 25 mph","No, no puede ingresar una dirección mientras maneja","Sí, si el teléfono está en un soporte","Sí, en un semáforo en rojo"],"h1":"Programe la ruta antes de que el carro se mueva.","h2":"En Iowa, la ley de manos libres no le permite ingresar una dirección en el GPS de su teléfono mientras maneja.","p":"¡Correcto! Ingrese la dirección antes de manejar."},"ref":{"doc":"IA","page":36}},{"id":"ia-126","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, may a driver make a video call while driving if the call is started by voice command?","o":["Yes, voice commands make it legal","Yes, if the screen is on the dashboard","No, video calls are not allowed even with voice commands","Only on the interstate"],"h1":"Hands-free does not cover watching video.","h2":"In Iowa, drivers may not stream videos or make video calls while driving, even with voice commands.","p":"Correct! No video calls while driving."},"es":{"q":"En Iowa, ¿puede un conductor hacer una videollamada mientras maneja si la inicia con un comando de voz?","o":["Sí, los comandos de voz la hacen legal","Sí, si la pantalla está en el tablero","No, las videollamadas no se permiten ni con comandos de voz","Solo en la autopista interestatal"],"h1":"Manos libres no incluye mirar video.","h2":"En Iowa, los conductores no pueden ver videos ni hacer videollamadas mientras manejan, ni siquiera con comandos de voz.","p":"¡Correcto! Nada de videollamadas al manejar."},"ref":{"doc":"IA","page":36}},{"id":"ia-127","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, when may a driver hold and use a phone while the car is moving?","o":["To read a short text","To check social media at low speed","To change songs on a playlist","To report an emergency"],"h1":"The law makes room for calling for help.","h2":"In Iowa, using a phone to report an emergency is one of the exceptions to the hands-free law.","p":"Right! Reporting an emergency is allowed."},"es":{"q":"En Iowa, ¿cuándo puede un conductor sostener y usar el teléfono con el carro en movimiento?","o":["Para leer un mensaje corto","Para revisar redes sociales a baja velocidad","Para cambiar canciones de una lista","Para reportar una emergencia"],"h1":"La ley permite pedir ayuda.","h2":"En Iowa, usar el teléfono para reportar una emergencia es una de las excepciones a la ley de manos libres.","p":"¡Correcto! Se permite reportar una emergencia."},"ref":{"doc":"IA","page":null}},{"id":"ia-128","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, what is the scheduled fine for holding and using a phone while driving?","o":["$100","$30","$500","$1,000"],"h1":"It is a round number in the low hundreds.","h2":"In Iowa, the scheduled fine for using an electronic device while driving, other than hands-free, is $100.","p":"Correct! The scheduled fine is $100."},"es":{"q":"En Iowa, ¿cuál es la multa fija por sostener y usar el teléfono mientras maneja?","o":["$100","$30","$500","$1,000"],"h1":"Es un número redondo de unos cientos.","h2":"En Iowa, la multa fija por usar un aparato electrónico al manejar, sin manos libres, es de $100.","p":"¡Correcto! La multa fija es de $100."},"ref":{"doc":"IA","page":null}},{"id":"ia-129","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, a ticket for using a phone without hands-free while driving is counted as what kind of violation?","o":["A parking violation","A moving violation","An equipment violation","It is not recorded"],"h1":"It counts like speeding or running a stop sign.","h2":"In Iowa, a hands-free law violation counts as a moving violation on your record.","p":"Right! It is a moving violation."},"es":{"q":"En Iowa, una multa por usar el teléfono sin manos libres al manejar ¿qué tipo de infracción es?","o":["Una infracción de estacionamiento","Una infracción de tránsito en movimiento","Una infracción de equipo","No se registra"],"h1":"Cuenta como exceder la velocidad o pasarse un alto.","h2":"En Iowa, no cumplir la ley de manos libres cuenta como una infracción de tránsito en movimiento en su historial.","p":"¡Correcto! Es una infracción en movimiento."},"ref":{"doc":"IA","page":null}},{"id":"ia-130","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, a 15-year-old with an instruction permit needs to call home during a practice drive. What must the teen do first?","o":["Use speakerphone and keep driving","Slow to 20 mph","Come to a complete stop off the traveled part of the road","Ask the supervising adult to hold the phone to the teen's ear"],"h1":"Teen drivers may not talk on the phone while driving at all.","h2":"In Iowa, a driver under 18 with a permit or teen license may not talk on the phone while driving unless the vehicle is completely stopped off the traveled roadway.","p":"Correct! Stop completely off the road first."},"es":{"q":"En Iowa, un joven de 15 años con permiso de aprendizaje necesita llamar a casa durante una práctica. ¿Qué debe hacer primero?","o":["Usar el altavoz y seguir manejando","Bajar a 20 mph","Detenerse por completo fuera de la parte transitada de la vía","Pedir al adulto que le sostenga el teléfono en la oreja"],"h1":"Los conductores jóvenes no pueden hablar por teléfono mientras manejan.","h2":"En Iowa, un conductor menor de 18 años con permiso o licencia juvenil no puede hablar por teléfono al manejar, salvo que el vehículo esté detenido por completo fuera de la vía transitada.","p":"¡Correcto! Primero deténgase por completo fuera de la vía."},"ref":{"doc":"IA","page":36}},{"id":"ia-131","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a distracted driver causes a crash that kills someone. Besides a possible homicide charge, what can the driver face?","o":["A warning letter only","A $25 fine","Points but no fine","More than $1,000 in fines and a license suspension"],"h1":"The penalties are heavy.","h2":"In Iowa, a distracted driver who causes a death can face more than $1,000 in fines, a license suspension and possibly a vehicular homicide charge.","p":"Right! Fines over $1,000 and a suspension."},"es":{"q":"En Iowa, un conductor distraído causa un choque en el que muere una persona. Además de un posible cargo por homicidio, ¿qué puede enfrentar?","o":["Solo una carta de advertencia","Una multa de $25","Puntos pero sin multa","Más de $1,000 en multas y la suspensión de la licencia"],"h1":"Las sanciones son fuertes.","h2":"En Iowa, un conductor distraído que causa una muerte puede enfrentar más de $1,000 en multas, la suspensión de la licencia y quizás un cargo por homicidio vehicular.","p":"¡Correcto! Multas de más de $1,000 y suspensión."},"ref":{"doc":"IA","page":36}},{"id":"ia-132","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Iowa, can a police officer stop you only because you are not wearing a seat belt?","o":["Yes, it is a primary offense","No, only if you commit another violation","Only at night","Only on the interstate"],"h1":"Not buckling up is enough on its own.","h2":"In Iowa, not wearing a seat belt is a primary offense, so an officer can stop you for that reason alone.","p":"Correct! It is a primary offense."},"es":{"q":"En Iowa, ¿puede un policía detenerlo solo porque no lleva puesto el cinturón de seguridad?","o":["Sí, es una falta primaria","No, solo si comete otra infracción","Solo de noche","Solo en la autopista interestatal"],"h1":"No abrocharse basta por sí solo.","h2":"En Iowa, no usar el cinturón de seguridad es una falta primaria, así que un agente puede detenerlo solo por eso.","p":"¡Correcto! Es una falta primaria."},"ref":{"doc":"IA","page":34}},{"id":"ia-133","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, may a 16-year-old ride in the open back (bed) of a moving pickup truck?","o":["Yes, on gravel roads","No, a child under 18 may not ride there","Yes, if sitting down","Yes, below 25 mph"],"h1":"The age limit is the same as for seat belts in the back seat.","h2":"In Iowa, a child under 18 may not ride in the back of a moving pickup truck.","p":"Right! No one under 18 may ride in the bed."},"es":{"q":"En Iowa, ¿puede un joven de 16 años viajar en la parte trasera abierta (la caja) de una camioneta pickup en movimiento?","o":["Sí, en caminos de grava","No, un menor de 18 años no puede viajar allí","Sí, si va sentado","Sí, a menos de 25 mph"],"h1":"El límite de edad es el mismo que para el cinturón en el asiento trasero.","h2":"En Iowa, un menor de 18 años no puede viajar en la parte trasera de una camioneta pickup en movimiento.","p":"¡Correcto! Nadie menor de 18 puede ir en la caja."},"ref":{"doc":"IA","page":35}},{"id":"ia-134","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, a 15-year-old front-seat passenger refuses to buckle up. Who is usually ticketed?","o":["The driver","The car owner","The 15-year-old passenger","No one"],"h1":"From age 14, passengers answer for themselves.","h2":"In Iowa, a passenger 14 or older who does not buckle up is charged instead of the driver, unless a disability keeps the passenger from fastening the belt.","p":"Correct! The passenger, 14 or older, gets the ticket."},"es":{"q":"En Iowa, un pasajero de 15 años en el asiento delantero se niega a abrocharse el cinturón. ¿A quién suelen multar?","o":["Al conductor","Al dueño del carro","Al pasajero de 15 años","A nadie"],"h1":"Desde los 14 años, los pasajeros responden por sí mismos.","h2":"En Iowa, un pasajero de 14 años o más que no se abrocha es multado en lugar del conductor, salvo que una discapacidad le impida abrocharse.","p":"¡Correcto! Multan al pasajero de 14 años o más."},"ref":{"doc":"IA","page":null}},{"id":"ia-135","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Iowa, a doctor certifies that a person cannot wear a seat belt for medical reasons. For how long can that certificate usually last?","o":["For life","5 years","30 days","Up to 12 months"],"h1":"It must be renewed each year.","h2":"In Iowa, a medical seat belt exemption certificate covers up to 12 months, after which a new one may be issued.","p":"Right! Up to 12 months."},"es":{"q":"En Iowa, un médico certifica que una persona no puede usar el cinturón de seguridad por razones médicas. ¿Cuánto puede durar normalmente ese certificado?","o":["Toda la vida","5 años","30 días","Hasta 12 meses"],"h1":"Se debe renovar cada año.","h2":"En Iowa, un certificado médico de exención del cinturón cubre hasta 12 meses; después se puede emitir uno nuevo.","p":"¡Correcto! Hasta 12 meses."},"ref":{"doc":"IA","page":null}},{"id":"ia-136","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Iowa driver's manual, a loose 20-pound object in a car at 60 mph can hit with how much force in a sudden stop?","o":["Well over 1,000 pounds","About 20 pounds","About 60 pounds","About 200 pounds"],"h1":"The force is many times the object's weight.","h2":"The Iowa driver's manual says a 20-pound object at 60 mph can strike with well over 1,000 pounds of force in a sudden stop, so secure loose items.","p":"Correct! Well over 1,000 pounds of force."},"es":{"q":"Según el manual de manejo de Iowa, un objeto suelto de 20 libras dentro de un carro a 60 mph puede golpear con ¿cuánta fuerza en una parada brusca?","o":["Mucho más de 1,000 libras","Unas 20 libras","Unas 60 libras","Unas 200 libras"],"h1":"La fuerza es muchas veces el peso del objeto.","h2":"El manual de manejo de Iowa dice que un objeto de 20 libras a 60 mph puede golpear con mucho más de 1,000 libras de fuerza en una parada brusca, así que asegure los objetos sueltos.","p":"¡Correcto! Mucho más de 1,000 libras de fuerza."},"ref":{"doc":"IA","page":35}},{"id":"ia-137","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"The Iowa driver's manual answers the myth that seat belts are only needed on long trips. Where do over half of all traffic deaths happen?","o":["On interstates far from home","Within 25 miles of home","In parking lots","In other states"],"h1":"Short, everyday trips are risky too.","h2":"The Iowa driver's manual says over half of all traffic deaths happen within 25 miles of home, so buckle up on every trip.","p":"Right! Within 25 miles of home."},"es":{"q":"El manual de manejo de Iowa responde al mito de que el cinturón solo hace falta en viajes largos. ¿Dónde ocurren más de la mitad de las muertes de tránsito?","o":["En autopistas lejos de casa","A menos de 25 millas de casa","En estacionamientos","En otros estados"],"h1":"Los viajes cortos de todos los días también son peligrosos.","h2":"El manual de manejo de Iowa dice que más de la mitad de las muertes de tránsito ocurren a menos de 25 millas de casa, así que abróchese en cada viaje.","p":"¡Correcto! A menos de 25 millas de casa."},"ref":{"doc":"IA","page":35}},{"id":"ia-138","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Iowa driver's manual, at least how far should your chest be from the steering wheel air bag?","o":["2 inches","5 inches","10 inches","24 inches"],"h1":"Think of about the length of a pencil.","h2":"The Iowa driver's manual says there should be at least 10 inches between the steering wheel and your chest.","p":"Correct! At least 10 inches."},"es":{"q":"Según el manual de manejo de Iowa, ¿a qué distancia mínima del volante, donde está la bolsa de aire, debe estar su pecho?","o":["2 pulgadas","5 pulgadas","10 pulgadas","24 pulgadas"],"h1":"Piense más o menos en el largo de un lápiz.","h2":"El manual de manejo de Iowa dice que debe haber al menos 10 pulgadas entre el volante y su pecho.","p":"¡Correcto! Al menos 10 pulgadas."},"ref":{"doc":"IA","page":25}},{"id":"ia-139","scope":"IA","cat":"signals","sign":null,"c":3,"en":{"q":"In Iowa, the speed limit is 35 mph. At least how far before a turn must you start signaling?","o":["25 feet","50 feet","300 feet","100 feet"],"h1":"On slower roads, the distance is shorter than on fast roads.","h2":"In Iowa, you must signal at least 100 feet before a turn when the speed limit is 45 mph or less.","p":"Right! At least 100 feet on roads of 45 mph or less."},"es":{"q":"En Iowa, el límite de velocidad es de 35 mph. ¿Con cuánta anticipación mínima antes de una vuelta debe poner la direccional?","o":["25 pies","50 pies","300 pies","100 pies"],"h1":"En vías más lentas, la distancia es menor que en vías rápidas.","h2":"En Iowa, debe poner la direccional al menos 100 pies antes de una vuelta cuando el límite es de 45 mph o menos.","p":"¡Correcto! Al menos 100 pies en vías de 45 mph o menos."},"ref":{"doc":"IA","page":43}},{"id":"ia-140","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, you are on a road with three lanes going your way. Which lanes should you normally drive in?","o":["The right or center lane, except to pass","Only the left lane","Any lane, it makes no difference","The shoulder when traffic is heavy"],"h1":"Keep the far left lane free.","h2":"In Iowa, on a road with three or more lanes in your direction, stay in the right or center lane except to pass.","p":"Correct! Right or center, except to pass."},"es":{"q":"En Iowa, va por una vía con tres carriles en su dirección. ¿En qué carriles debe manejar normalmente?","o":["En el derecho o el central, salvo para rebasar","Solo en el izquierdo","En cualquiera, da igual","Por el acotamiento cuando hay mucho tránsito"],"h1":"Deje libre el carril de la extrema izquierda.","h2":"En Iowa, en una vía con tres o más carriles en su dirección, use el carril derecho o el central salvo para rebasar.","p":"¡Correcto! Derecho o central, salvo para rebasar."},"ref":{"doc":"IA","page":16}},{"id":"ia-141","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, you are on a road with three or more lanes and a lot of traffic is entering from the right. Which lane is best to use?","o":["The right lane","The center lane","The shoulder","The left lane only"],"h1":"Give the merging cars room.","h2":"In Iowa, when there is a lot of entering traffic on a road with three or more lanes, it is best to use the center lane.","p":"Right! The center lane is best."},"es":{"q":"En Iowa, va por una vía de tres o más carriles y entran muchos carros por la derecha. ¿Qué carril es mejor usar?","o":["El carril derecho","El carril central","El acotamiento","Solo el carril izquierdo"],"h1":"Deje espacio a los carros que se incorporan.","h2":"En Iowa, cuando entran muchos carros a una vía de tres o más carriles, es mejor usar el carril central.","p":"¡Correcto! El carril central es el mejor."},"ref":{"doc":"IA","page":16}},{"id":"ia-142","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, when may a driver drive in a bicycle lane?","o":["Whenever no bicycles are in sight","To pass slow cars","Only when making a turn, after checking for bicyclists","To park for a few minutes"],"h1":"The lane is for bicycles, with one narrow exception.","h2":"In Iowa, motorists may drive in a bicycle lane only when making a turn, after looking carefully beside and behind for bicyclists.","p":"Correct! Only when turning, and with care."},"es":{"q":"En Iowa, ¿cuándo puede un conductor manejar en un carril para bicicletas?","o":["Siempre que no vea bicicletas","Para rebasar carros lentos","Solo al dar una vuelta, después de buscar ciclistas","Para estacionarse unos minutos"],"h1":"El carril es para bicicletas, con una sola excepción.","h2":"En Iowa, los conductores solo pueden entrar al carril para bicicletas al dar una vuelta, después de mirar bien al lado y atrás por si hay ciclistas.","p":"¡Correcto! Solo al dar vuelta, con cuidado."},"ref":{"doc":"IA","page":17}},{"id":"ia-143","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, part of a bicycle lane is painted green where it crosses your path. What should you do?","o":["Stop on the green paint to wait","Speed up to cross it quickly","Use it as a turn lane","Look for bicyclists and do not stop on the green pavement"],"h1":"Green marks a spot where cars and bikes meet.","h2":"In Iowa, look for bicyclists before crossing green bike-lane pavement, and do not stop on it.","p":"Right! Watch for bikes and never stop on the green."},"es":{"q":"En Iowa, una parte del carril para bicicletas está pintada de verde donde cruza su camino. ¿Qué debe hacer?","o":["Detenerse sobre la pintura verde para esperar","Acelerar para cruzar rápido","Usarla como carril para dar vuelta","Buscar ciclistas y no detenerse sobre el pavimento verde"],"h1":"El verde marca un lugar donde se cruzan carros y bicicletas.","h2":"En Iowa, busque ciclistas antes de cruzar el pavimento verde del carril para bicicletas y no se detenga sobre él.","p":"¡Correcto! Atento a las bicicletas y nunca se detenga en el verde."},"ref":{"doc":"IA","page":17}},{"id":"ia-144","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, a 2024 law updated the crosswalk rules. A person pushing a stroller is in a crosswalk. What must you do?","o":["Yield, as you would to a person walking","Go first, because strollers are vehicles","Honk so the person hurries","Yield only if the person is using a wheelchair"],"h1":"The law covers people using human-powered devices too.","h2":"In Iowa, you must yield to pedestrians and to people using human-powered devices, such as strollers, wheelchairs, skateboards and scooters.","p":"Correct! Yield to them like any pedestrian."},"es":{"q":"En Iowa, una ley de 2024 actualizó las reglas de los cruces peatonales. Una persona empuja una carriola en el cruce. ¿Qué debe hacer?","o":["Ceder el paso, como a una persona que camina","Pasar primero, porque las carriolas son vehículos","Tocar la bocina para que se apure","Ceder el paso solo si usa silla de ruedas"],"h1":"La ley también cubre a quienes usan aparatos movidos por fuerza humana.","h2":"En Iowa, debe ceder el paso a los peatones y a las personas que usan aparatos movidos por fuerza humana, como carriolas, sillas de ruedas, patinetas y scooters.","p":"¡Correcto! Ceda el paso como a cualquier peatón."},"ref":{"doc":"IA","page":10}},{"id":"ia-145","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, there is no traffic signal. A person riding a bicycle is crossing the road in a marked crosswalk. What must you do?","o":["Go, because bicyclists must always wait for cars","Yield, slowing or stopping if needed","Pass close behind the bicyclist","Flash your lights and continue"],"h1":"Iowa law names bicyclists in crosswalks along with pedestrians.","h2":"In Iowa, where no traffic signal is working, drivers must yield to a pedestrian or a person riding a bicycle crossing in a crosswalk.","p":"Right! Yield to the bicyclist in the crosswalk."},"es":{"q":"En Iowa, no hay semáforo. Una persona en bicicleta cruza la calle por un cruce peatonal marcado. ¿Qué debe hacer?","o":["Avanzar, porque los ciclistas siempre esperan a los carros","Ceder el paso, bajando la velocidad o deteniéndose si hace falta","Pasar muy cerca detrás del ciclista","Hacer cambio de luces y seguir"],"h1":"La ley de Iowa nombra a los ciclistas en los cruces junto con los peatones.","h2":"En Iowa, donde no funciona un semáforo, los conductores deben ceder el paso a un peatón o a una persona en bicicleta que cruza por un cruce peatonal.","p":"¡Correcto! Ceda el paso al ciclista en el cruce."},"ref":{"doc":"IA","page":null}},{"id":"ia-146","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, a person is walking along a country highway with no sidewalk. On which side does the law say they should walk?","o":["The right side, with traffic","In the middle of the lane","The left side, facing traffic","Either side; there is no rule"],"h1":"Walkers should see cars coming toward them.","h2":"In Iowa, pedestrians walking along a highway must walk on the left side, facing oncoming traffic.","p":"Correct! On the left, facing traffic."},"es":{"q":"En Iowa, una persona camina por una carretera rural sin banqueta. ¿De qué lado debe caminar según la ley?","o":["Del lado derecho, en el mismo sentido del tránsito","Por el centro del carril","Del lado izquierdo, de frente al tránsito","De cualquier lado; no hay regla"],"h1":"Quien camina debe ver los carros que vienen hacia él.","h2":"En Iowa, los peatones que caminan por una carretera deben ir del lado izquierdo, de frente al tránsito.","p":"¡Correcto! A la izquierda, de frente al tránsito."},"ref":{"doc":"IA","page":null}},{"id":"ia-147","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"According to the Iowa driver's manual, what is the number one cause of traffic deaths in Iowa?","o":["Bad weather","Deer on the road","Flat tires","Failure to yield the right-of-way"],"h1":"It is about who should go first.","h2":"The Iowa driver's manual says failure to yield the right-of-way is the number one cause of traffic-related deaths in Iowa.","p":"Right! Failure to yield is the top cause."},"es":{"q":"Según el manual de manejo de Iowa, ¿cuál es la principal causa de muertes de tránsito en Iowa?","o":["El mal tiempo","Los venados en la carretera","Las llantas ponchadas","No ceder el paso"],"h1":"Tiene que ver con quién debe pasar primero.","h2":"El manual de manejo de Iowa dice que no ceder el paso es la causa número uno de muertes de tránsito en Iowa.","p":"¡Correcto! No ceder el paso es la causa principal."},"ref":{"doc":"IA","page":18}},{"id":"ia-148","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, you are on a highway divided by a median. An ambulance with lights and siren is on the other side, going the opposite way. What must you do?","o":["You do not have to stop","Stop in your lane right away","Pull over and wait for it to pass","Cross the median to make room"],"h1":"The median separates you from the ambulance.","h2":"In Iowa, if you are on a road separated by a median and the emergency vehicle is on the other side, you do not have to stop.","p":"Correct! You do not have to stop."},"es":{"q":"En Iowa, va por una carretera dividida por un camellón. Una ambulancia con luces y sirena va del otro lado, en sentido contrario. ¿Qué debe hacer?","o":["No tiene que detenerse","Detenerse de inmediato en su carril","Orillarse y esperar a que pase","Cruzar el camellón para dejar espacio"],"h1":"El camellón lo separa de la ambulancia.","h2":"En Iowa, si va por una vía separada por un camellón y el vehículo de emergencia está del otro lado, no tiene que detenerse.","p":"¡Correcto! No tiene que detenerse."},"ref":{"doc":"IA","page":19}},{"id":"ia-149","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, a fire department vehicle comes up behind you with only flashing blue lights. What must you do?","o":["Nothing, blue lights are only a warning","Pull over to the right edge and stop until it passes","Speed up to stay ahead of it","Stop where you are, even in an intersection"],"h1":"In Iowa, blue lights on a fire vehicle mean the same as red ones.","h2":"In Iowa, you must yield to a fire department vehicle showing a blue light by pulling to the right edge, clear of intersections, and stopping until it passes.","p":"Right! Pull to the right and stop."},"es":{"q":"En Iowa, un vehículo del departamento de bomberos se acerca por detrás solo con luces azules intermitentes. ¿Qué debe hacer?","o":["Nada, las luces azules son solo un aviso","Orillarse a la derecha y detenerse hasta que pase","Acelerar para ir delante de él","Detenerse donde esté, aunque sea en un cruce"],"h1":"En Iowa, las luces azules de bomberos significan lo mismo que las rojas.","h2":"En Iowa, debe ceder el paso a un vehículo de bomberos con luz azul orillándose a la derecha, fuera de los cruces, y deteniéndose hasta que pase.","p":"¡Correcto! Oríllese a la derecha y deténgase."},"ref":{"doc":"IA","page":null}},{"id":"ia-150","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, you approach a stopped police car with flashing lights on a four-lane highway. If it is safe, where should you move?","o":["To the shoulder behind the police car","Into the lane right next to the police car","Into a lane that is not next to the police car","Into the oncoming lanes"],"h1":"Leave an empty lane between you and the stopped vehicle.","h2":"In Iowa, when approaching a stopped emergency vehicle with flashing lights, change into a lane that is not next to it if you can do so safely.","p":"Correct! Move to a lane not next to it."},"es":{"q":"En Iowa, se acerca a una patrulla detenida con luces intermitentes en una carretera de cuatro carriles. Si es seguro, ¿a dónde debe moverse?","o":["Al acotamiento detrás de la patrulla","Al carril justo al lado de la patrulla","A un carril que no esté junto a la patrulla","A los carriles del sentido contrario"],"h1":"Deje un carril vacío entre usted y el vehículo detenido.","h2":"En Iowa, al acercarse a un vehículo de emergencia detenido con luces intermitentes, cámbiese a un carril que no esté junto a él si puede hacerlo con seguridad.","p":"¡Correcto! Cámbiese a un carril que no esté a su lado."},"ref":{"doc":"IA","page":null}},{"id":"ia-151","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, you cannot safely change lanes when passing a stopped tow truck with flashing lights. How fast should you go?","o":["The posted speed limit","5 mph over the limit to get by quickly","Exactly 25 mph","A safe speed below the posted limit, ready to stop"],"h1":"Slowing down is required when you cannot move over.","h2":"In Iowa, if you cannot move over, you must slow to a reasonable speed below the posted limit and be ready to stop.","p":"Right! Slow below the limit and be ready to stop."},"es":{"q":"En Iowa, no puede cambiar de carril con seguridad al pasar junto a una grúa detenida con luces intermitentes. ¿A qué velocidad debe ir?","o":["Al límite de velocidad indicado","5 mph sobre el límite para pasar rápido","Exactamente a 25 mph","A una velocidad segura por debajo del límite, listo para detenerse"],"h1":"Si no puede cambiarse de carril, debe bajar la velocidad.","h2":"En Iowa, si no puede cambiarse de carril, debe bajar a una velocidad razonable por debajo del límite indicado y estar listo para detenerse.","p":"¡Correcto! Por debajo del límite y listo para detenerse."},"ref":{"doc":"IA","page":null}},{"id":"ia-152","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, which of these stopped vehicles with flashing lights is covered by the Move Over or Slow Down law?","o":["A garbage or recycling truck","A parked ice cream truck with music on","A car waiting at a drive-through","A bus at a bus stop with no flashing lights"],"h1":"The law covers more than police cars and ambulances.","h2":"In Iowa, the Move Over or Slow Down law includes stopped solid waste and recycling collection vehicles with flashing lights.","p":"Correct! Garbage and recycling trucks are covered."},"es":{"q":"En Iowa, ¿cuál de estos vehículos detenidos con luces intermitentes está cubierto por la ley de Cambiarse de Carril o Bajar la Velocidad?","o":["Un camión de basura o de reciclaje","Un camión de helados estacionado con música","Un carro esperando en un autoservicio","Un autobús en su parada sin luces intermitentes"],"h1":"La ley cubre más que patrullas y ambulancias.","h2":"En Iowa, la ley de Cambiarse de Carril o Bajar la Velocidad incluye los camiones de basura y de reciclaje detenidos con luces intermitentes.","p":"¡Correcto! Los camiones de basura y reciclaje están cubiertos."},"ref":{"doc":"IA","page":22}},{"id":"ia-153","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, a driver breaks the Move Over or Slow Down law and causes a crash that damages property but hurts no one. How long is the license suspended?","o":["7 days","90 days","5 years","It is not suspended"],"h1":"It is about three months.","h2":"In Iowa, a Move Over or Slow Down violation that causes property damage leads to a 90-day license suspension.","p":"Right! A 90-day suspension."},"es":{"q":"En Iowa, un conductor no cumple la ley de Cambiarse de Carril o Bajar la Velocidad y causa un choque con daños materiales, sin heridos. ¿Por cuánto tiempo le suspenden la licencia?","o":["7 días","90 días","5 años","No se la suspenden"],"h1":"Son unos tres meses.","h2":"En Iowa, no cumplir la ley de Cambiarse de Carril o Bajar la Velocidad y causar daños materiales lleva a una suspensión de 90 días.","p":"¡Correcto! Una suspensión de 90 días."},"ref":{"doc":"IA","page":null}},{"id":"ia-154","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"The Iowa driver's manual explains the Steer It-Clear It law. For every minute an interstate lane is blocked, how much does the risk of another crash rise?","o":["About 50 percent","About 10 percent","About 2.8 percent","It does not change"],"h1":"It is a small number, but it adds up minute by minute.","h2":"The Iowa driver's manual says each minute an interstate lane is blocked raises the risk of a secondary crash by roughly 2.8 percent.","p":"Correct! About 2.8 percent each minute."},"es":{"q":"El manual de manejo de Iowa explica la ley Steer It-Clear It (muévalo y despeje). Por cada minuto que un carril de autopista está bloqueado, ¿cuánto sube el riesgo de otro choque?","o":["Cerca de 50 por ciento","Cerca de 10 por ciento","Cerca de 2.8 por ciento","No cambia"],"h1":"Es un número pequeño, pero se suma minuto a minuto.","h2":"El manual de manejo de Iowa dice que cada minuto que un carril de autopista está bloqueado sube el riesgo de un segundo choque en cerca de 2.8 por ciento.","p":"¡Correcto! Cerca de 2.8 por ciento por minuto."},"ref":{"doc":"IA","page":22}},{"id":"ia-155","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, you are coming toward a school bus that has its amber (yellow) lights flashing. What is the highest speed you may drive?","o":["35 mph","45 mph","15 mph","20 mph"],"h1":"Amber lights mean the bus is about to stop.","h2":"In Iowa, when you meet a school bus with flashing amber lights, you must slow to 20 mph or less and be ready to stop.","p":"Right! No more than 20 mph."},"es":{"q":"En Iowa, se acerca de frente a un autobús escolar con luces ámbar (amarillas) intermitentes. ¿Cuál es la velocidad máxima a la que puede manejar?","o":["35 mph","45 mph","15 mph","20 mph"],"h1":"Las luces ámbar indican que el autobús va a detenerse.","h2":"En Iowa, al encontrarse con un autobús escolar con luces ámbar intermitentes, debe bajar a 20 mph o menos y estar listo para detenerse.","p":"¡Correcto! No más de 20 mph."},"ref":{"doc":"IA","page":20}},{"id":"ia-156","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, you stop behind a school bus with its stop arm out. How close to the bus may you stop?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 50 feet","As close as you like"],"h1":"Leave room for children walking near the bus.","h2":"In Iowa, when stopping behind a school bus with its stop arm out, stop no closer than 15 feet from the back of the bus.","p":"Correct! Stay at least 15 feet back."},"es":{"q":"En Iowa, se detiene detrás de un autobús escolar con el brazo de alto extendido. ¿Qué tan cerca del autobús puede detenerse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 50 pies","Tan cerca como quiera"],"h1":"Deje espacio para los niños que caminan cerca del autobús.","h2":"En Iowa, al detenerse detrás de un autobús escolar con el brazo de alto extendido, quédese al menos a 15 pies de la parte trasera.","p":"¡Correcto! Quédese al menos a 15 pies."},"ref":{"doc":"IA","page":20}},{"id":"ia-157","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, you are behind a school bus that is moving with its amber lights flashing. May you pass it?","o":["Yes, if no children are visible","No, you may not pass when red or amber lights are flashing","Yes, on a four-lane road","Yes, if you honk first"],"h1":"Amber is a warning that a stop is coming.","h2":"In Iowa, when approaching a school bus from behind, you may not pass it while its red or amber warning lights are flashing.","p":"Right! Do not pass while the lights flash."},"es":{"q":"En Iowa, va detrás de un autobús escolar en movimiento con luces ámbar intermitentes. ¿Puede rebasarlo?","o":["Sí, si no ve niños","No, no puede rebasar con luces rojas o ámbar intermitentes","Sí, en una carretera de cuatro carriles","Sí, si toca la bocina primero"],"h1":"El ámbar avisa que viene una parada.","h2":"En Iowa, al acercarse por detrás a un autobús escolar, no puede rebasarlo mientras tenga las luces de advertencia rojas o ámbar encendidas.","p":"¡Correcto! No rebase mientras parpadean las luces."},"ref":{"doc":"IA","page":20}},{"id":"ia-158","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, what is the fine range for a first conviction of illegally passing a stopped school bus?","o":["$30 to $50","$100 to $200","$345 to $930","$5,000 to $10,000"],"h1":"The lowest fine is more than $300.","h2":"In Iowa, a first conviction for illegally passing a stopped school bus brings a fine of $345 to $930, up to 30 days in jail, or both.","p":"Correct! $345 to $930."},"es":{"q":"En Iowa, ¿cuál es el rango de multa por una primera condena por rebasar ilegalmente un autobús escolar detenido?","o":["De $30 a $50","De $100 a $200","De $345 a $930","De $5,000 a $10,000"],"h1":"La multa más baja pasa de $300.","h2":"En Iowa, una primera condena por rebasar ilegalmente un autobús escolar detenido lleva una multa de $345 a $930, hasta 30 días de cárcel, o ambas.","p":"¡Correcto! De $345 a $930."},"ref":{"doc":"IA","page":null}},{"id":"ia-159","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, after a first conviction for passing a stopped school bus, what may the DOT allow instead of a license suspension?","o":["Paying double the fine","Writing a letter of apology","Washing school buses","Completing a driver improvement program at your own cost"],"h1":"It is a class about safer driving.","h2":"In Iowa, after a first school bus passing offense, the DOT may require a driver improvement program, at the driver's expense, instead of a suspension.","p":"Right! A driver improvement program."},"es":{"q":"En Iowa, después de una primera condena por rebasar un autobús escolar detenido, ¿qué puede permitir el Departamento de Transporte en lugar de suspender la licencia?","o":["Pagar el doble de la multa","Escribir una carta de disculpa","Lavar autobuses escolares","Completar un programa de mejora del conductor, pagado por usted"],"h1":"Es un curso para manejar con más seguridad.","h2":"En Iowa, después de una primera falta por rebasar un autobús escolar, el Departamento de Transporte puede exigir un programa de mejora del conductor, pagado por el conductor, en lugar de una suspensión.","p":"¡Correcto! Un programa de mejora del conductor."},"ref":{"doc":"IA","page":null}},{"id":"ia-160","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, on a road with a 55 mph limit, how far ahead of a stop does a school bus driver turn on the amber lights?","o":["300 to 500 feet","50 to 100 feet","1,000 feet","Only when fully stopped"],"h1":"On fast roads, drivers need more warning.","h2":"In Iowa, when the speed limit is 45 mph or more, a school bus turns on its amber lights 300 to 500 feet before the stop.","p":"Correct! 300 to 500 feet before the stop."},"es":{"q":"En Iowa, en una vía con límite de 55 mph, ¿con cuánta anticipación enciende el conductor del autobús escolar las luces ámbar antes de parar?","o":["De 300 a 500 pies","De 50 a 100 pies","1,000 pies","Solo cuando ya está detenido"],"h1":"En vías rápidas, los conductores necesitan más aviso.","h2":"En Iowa, cuando el límite es de 45 mph o más, el autobús escolar enciende las luces ámbar de 300 a 500 pies antes de la parada.","p":"¡Correcto! De 300 a 500 pies antes de la parada."},"ref":{"doc":"IA","page":null}},{"id":"ia-161","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, children get off a school bus and must cross the road. Where do they cross?","o":["Behind the bus","In front of the bus, when the driver signals","At the nearest corner, without waiting","Anywhere after the bus leaves"],"h1":"The bus driver must be able to see them.","h2":"In Iowa, children who must cross the road pass in front of the school bus and cross only when the bus driver signals.","p":"Right! In front of the bus, on the driver's signal."},"es":{"q":"En Iowa, unos niños bajan del autobús escolar y deben cruzar la calle. ¿Por dónde cruzan?","o":["Por detrás del autobús","Por delante del autobús, cuando el conductor les hace la señal","Por la esquina más cercana, sin esperar","Por cualquier lugar después de que se va el autobús"],"h1":"El conductor del autobús debe poder verlos.","h2":"En Iowa, los niños que deben cruzar pasan por delante del autobús escolar y cruzan solo cuando el conductor les hace la señal.","p":"¡Correcto! Por delante, con la señal del conductor."},"ref":{"doc":"IA","page":null}},{"id":"ia-162","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, you pass a car on a two-lane road with a 55 mph limit. You must be back in your lane before you get within how many feet of an oncoming vehicle?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"On faster roads you need a bigger cushion.","h2":"In Iowa, when the speed limit is over 30 mph, a passing driver must return to the right side before coming within 300 feet of an oncoming vehicle.","p":"Correct! Back in your lane before 300 feet."},"es":{"q":"En Iowa, rebasa a un carro en una carretera de dos carriles con límite de 55 mph. ¿Antes de llegar a cuántos pies de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"En vías más rápidas necesita más espacio.","h2":"En Iowa, cuando el límite es de más de 30 mph, quien rebasa debe volver al lado derecho antes de quedar a 300 pies de un vehículo que viene de frente.","p":"¡Correcto! De vuelta en su carril antes de 300 pies."},"ref":{"doc":"IA","page":null}},{"id":"ia-163","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, you pass a car on a street with a 25 mph limit. You must be back in your lane before you get within how many feet of an oncoming vehicle?","o":["10 feet","300 feet","500 feet","100 feet"],"h1":"On slow streets, the distance is shorter.","h2":"In Iowa, when the speed limit is 30 mph or less, a passing driver must return to the right side before coming within 100 feet of an oncoming vehicle.","p":"Right! Before 100 feet on slow streets."},"es":{"q":"En Iowa, rebasa a un carro en una calle con límite de 25 mph. ¿Antes de llegar a cuántos pies de un vehículo que viene de frente debe volver a su carril?","o":["10 pies","300 pies","500 pies","100 pies"],"h1":"En calles lentas, la distancia es menor.","h2":"En Iowa, cuando el límite es de 30 mph o menos, quien rebasa debe volver al lado derecho antes de quedar a 100 pies de un vehículo que viene de frente.","p":"¡Correcto! Antes de 100 pies en calles lentas."},"ref":{"doc":"IA","page":null}},{"id":"ia-164","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, you may not drive on the left side of the road near a hilltop or curve when your view ahead is blocked for about how far?","o":["700 feet","100 feet","200 feet","2 miles"],"h1":"It is a few hundred feet, less than 1,000.","h2":"In Iowa, you may not drive left of center near the top of a hill or on a curve where your view is blocked for about 700 feet.","p":"Correct! About 700 feet."},"es":{"q":"En Iowa, no puede manejar por el lado izquierdo de la vía cerca de la cima de una colina o en una curva cuando no puede ver hacia adelante unos ¿cuántos pies?","o":["700 pies","100 pies","200 pies","2 millas"],"h1":"Son unos cientos de pies, menos de 1,000.","h2":"En Iowa, no puede manejar a la izquierda del centro cerca de la cima de una colina o en una curva donde no se ve a unos 700 pies.","p":"¡Correcto! Unos 700 pies."},"ref":{"doc":"IA","page":null}},{"id":"ia-165","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, a sign warns of a narrow bridge ahead. Within how many feet of it may you not pass?","o":["50 feet","100 feet","500 feet","1,000 feet"],"h1":"It is the same distance as for intersections and railroad crossings.","h2":"In Iowa, you may not pass within 100 feet of a narrow bridge, viaduct or tunnel that has a warning sign.","p":"Right! Not within 100 feet."},"es":{"q":"En Iowa, un letrero avisa de un puente angosto adelante. ¿A menos de cuántos pies de él no puede rebasar?","o":["50 pies","100 pies","500 pies","1,000 pies"],"h1":"Es la misma distancia que para las intersecciones y los cruces de tren.","h2":"En Iowa, no puede rebasar a menos de 100 pies de un puente angosto, viaducto o túnel que tenga un letrero de aviso.","p":"¡Correcto! No a menos de 100 pies."},"ref":{"doc":"IA","page":46}},{"id":"ia-166","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, you may not make a U-turn on a curve or near a hilltop if other drivers cannot see your car from how far away?","o":["100 feet","200 feet","500 feet","1 mile"],"h1":"It is a few hundred feet.","h2":"In Iowa, you may not turn around on a curve or near the top of a hill where drivers from either direction cannot see your vehicle within 500 feet.","p":"Correct! 500 feet."},"es":{"q":"En Iowa, no puede dar una vuelta en U en una curva o cerca de la cima de una colina si otros conductores no pueden ver su carro desde ¿qué distancia?","o":["100 pies","200 pies","500 pies","1 milla"],"h1":"Son unos cientos de pies.","h2":"En Iowa, no puede dar la vuelta en una curva o cerca de la cima de una colina donde los conductores de cualquier dirección no puedan ver su vehículo a 500 pies.","p":"¡Correcto! 500 pies."},"ref":{"doc":"IA","page":null}},{"id":"ia-167","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, you must cross a rural four-lane divided highway from a side road with a stop sign. What is the safest way?","o":["Cross all four lanes at once when there is any gap","Wait until both directions are empty at the same time","Turn right and drive the wrong way to the next crossing","Cross the first two lanes, stop in the median, then cross the rest"],"h1":"Deal with one direction of traffic at a time.","h2":"In Iowa, when crossing or turning left onto a rural four-lane road, cross one direction, stop in the median, then cross or turn when the other direction is clear.","p":"Right! One direction at a time, using the median."},"es":{"q":"En Iowa, debe cruzar una carretera rural dividida de cuatro carriles desde un camino lateral con señal de alto. ¿Cuál es la forma más segura?","o":["Cruzar los cuatro carriles de una vez cuando haya un espacio","Esperar hasta que ambos sentidos estén vacíos al mismo tiempo","Dar vuelta a la derecha y manejar en sentido contrario hasta el siguiente cruce","Cruzar los dos primeros carriles, detenerse en el camellón y luego cruzar el resto"],"h1":"Ocúpese de un sentido del tránsito a la vez.","h2":"En Iowa, al cruzar o dar vuelta a la izquierda en una carretera rural de cuatro carriles, cruce un sentido, deténgase en el camellón y luego cruce o dé vuelta cuando el otro sentido esté libre.","p":"¡Correcto! Un sentido a la vez, usando el camellón."},"ref":{"doc":"IA","page":51}},{"id":"ia-168","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, you reach a reduced-conflict intersection on a four-lane highway and want to go left. What do you do?","o":["Turn right, move to the left lane, then make a U-turn at the marked median opening","Turn left across all lanes at once","Back up to the previous exit","Wait for a police officer to stop traffic"],"h1":"These intersections avoid crossing both directions at once.","h2":"In Iowa, at a reduced-conflict intersection, drivers who want to go left or straight turn right, merge left, and make a U-turn at a designated median opening.","p":"Correct! Right turn, then a U-turn at the median opening."},"es":{"q":"En Iowa, llega a una intersección de conflicto reducido en una carretera de cuatro carriles y quiere ir a la izquierda. ¿Qué hace?","o":["Da vuelta a la derecha, pasa al carril izquierdo y hace una vuelta en U en la abertura marcada del camellón","Da vuelta a la izquierda cruzando todos los carriles a la vez","Retrocede hasta la salida anterior","Espera a que un policía detenga el tránsito"],"h1":"Estas intersecciones evitan cruzar ambos sentidos a la vez.","h2":"En Iowa, en una intersección de conflicto reducido, quien quiere ir a la izquierda o seguir derecho da vuelta a la derecha, pasa al carril izquierdo y hace una vuelta en U en una abertura señalada del camellón.","p":"¡Correcto! Vuelta a la derecha y luego vuelta en U en el camellón."},"ref":{"doc":"IA","page":52}},{"id":"ia-169","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, what is unusual about driving through a diverging diamond interchange?","o":["You must stop at every lane","For a short stretch, traffic drives on the opposite side of the road","It has no traffic signals at all","Only trucks may use it"],"h1":"The lanes cross over and then cross back.","h2":"In Iowa, a diverging diamond interchange briefly moves drivers to the opposite side of the road before bringing them back.","p":"Right! You briefly drive on the opposite side."},"es":{"q":"En Iowa, ¿qué tiene de especial manejar por un intercambio de diamante divergente?","o":["Hay que detenerse en cada carril","Por un tramo corto, el tránsito circula por el lado contrario de la vía","No tiene ningún semáforo","Solo lo pueden usar camiones"],"h1":"Los carriles se cruzan y luego vuelven a cruzarse.","h2":"En Iowa, un intercambio de diamante divergente lleva por un momento a los conductores al lado contrario de la vía antes de regresarlos.","p":"¡Correcto! Por un momento maneja del lado contrario."},"ref":{"doc":"IA","page":53}},{"id":"ia-170","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, you are driving on a gravel road on a very dusty day. What should you do with your lights?","o":["Turn them off to save the battery","Use high beams","Turn on your low-beam headlights","Use only parking lights"],"h1":"You want others to see you through the dust.","h2":"In Iowa, use low-beam headlights on gravel roads in very dusty conditions so others can see you.","p":"Correct! Low beams in the dust."},"es":{"q":"En Iowa, maneja por un camino de grava en un día con mucho polvo. ¿Qué debe hacer con sus luces?","o":["Apagarlas para ahorrar batería","Usar las luces altas","Encender las luces bajas","Usar solo las luces de estacionamiento"],"h1":"Quiere que los demás lo vean a través del polvo.","h2":"En Iowa, use las luces bajas en caminos de grava cuando hay mucho polvo, para que los demás lo vean.","p":"¡Correcto! Luces bajas en el polvo."},"ref":{"doc":"IA","page":55}},{"id":"ia-171","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, what should you expect at most railroad crossings on rural gravel roads?","o":["Gates and flashing lights","A flagger on duty","A traffic signal","No lights, bells or gates"],"h1":"Country crossings are usually simple.","h2":"In Iowa, rural road railroad crossings usually have no flashing lights, bells, gates or pavement markings, so slow down, look both ways and be ready to stop.","p":"Right! Usually no lights, bells or gates."},"es":{"q":"En Iowa, ¿qué debe esperar en la mayoría de los cruces de tren de los caminos rurales de grava?","o":["Barreras y luces intermitentes","Un banderero de guardia","Un semáforo","Ni luces, ni campanas, ni barreras"],"h1":"Los cruces en el campo suelen ser sencillos.","h2":"En Iowa, los cruces de tren en caminos rurales casi nunca tienen luces, campanas, barreras ni marcas en el pavimento, así que baje la velocidad, mire a ambos lados y esté listo para detenerse.","p":"¡Correcto! Normalmente sin luces, campanas ni barreras."},"ref":{"doc":"IA","page":56}},{"id":"ia-172","scope":"IA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Iowa, you are on a rural gravel road and see a narrow bridge ahead with a car coming the other way. What should you expect?","o":["The bridge may fit only one vehicle, so be ready to stop","Both cars can always pass on the bridge","The car on the bridge must back up","You may speed up to cross first"],"h1":"Many country bridges are narrower than the road.","h2":"In Iowa, many bridges on rural gravel roads are narrower than the road and fit only one vehicle at a time, so be prepared to stop for oncoming traffic.","p":"Correct! Be ready to stop; it may fit only one vehicle."},"es":{"q":"En Iowa, va por un camino rural de grava y ve un puente angosto adelante con un carro que viene en sentido contrario. ¿Qué debe esperar?","o":["Que en el puente quepa solo un vehículo, así que esté listo para detenerse","Que siempre puedan pasar los dos carros en el puente","Que el carro del puente tenga que retroceder","Que puede acelerar para cruzar primero"],"h1":"Muchos puentes del campo son más angostos que el camino.","h2":"En Iowa, muchos puentes de caminos rurales de grava son más angostos que el camino y solo cabe un vehículo a la vez, así que esté listo para detenerse ante el tránsito de frente.","p":"¡Correcto! Esté listo para detenerse; puede caber solo uno."},"ref":{"doc":"IA","page":56}},{"id":"ia-173","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, a sign is posted across the street from a fire station entrance. Within how many feet of that entrance may you not park on the opposite side?","o":["20 feet","75 feet","10 feet","300 feet"],"h1":"It is longer than the 20 feet on the station's own side.","h2":"In Iowa, when signs are posted, you may not park on the side of the street opposite a fire station entrance within 75 feet of it.","p":"Right! Within 75 feet across from the entrance."},"es":{"q":"En Iowa, hay un letrero frente a la entrada de una estación de bomberos, del otro lado de la calle. ¿A menos de cuántos pies de esa entrada no puede estacionarse en el lado opuesto?","o":["20 pies","75 pies","10 pies","300 pies"],"h1":"Es más que los 20 pies del lado de la estación.","h2":"En Iowa, cuando hay letreros, no puede estacionarse en el lado de la calle opuesto a la entrada de una estación de bomberos a menos de 75 pies de ella.","p":"¡Correcto! A menos de 75 pies frente a la entrada."},"ref":{"doc":"IA","page":null}},{"id":"ia-174","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, you must stop on a paved highway outside a town and cannot get fully off the road. How much paved road must you leave clear for other traffic?","o":["5 feet","10 feet","At least 20 feet","Half of one lane"],"h1":"Enough room for other vehicles to pass freely.","h2":"In Iowa, a vehicle stopped on a paved highway outside a business or residence district must leave at least 20 feet of the pavement clear for other vehicles.","p":"Correct! At least 20 feet clear."},"es":{"q":"En Iowa, debe detenerse en una carretera pavimentada fuera de un pueblo y no puede salir por completo de la vía. ¿Cuánto pavimento debe dejar libre para el resto del tránsito?","o":["5 pies","10 pies","Al menos 20 pies","La mitad de un carril"],"h1":"Suficiente espacio para que otros pasen sin problema.","h2":"En Iowa, un vehículo detenido en una carretera pavimentada fuera de una zona comercial o residencial debe dejar libres al menos 20 pies de pavimento para los demás.","p":"¡Correcto! Al menos 20 pies libres."},"ref":{"doc":"IA","page":null}},{"id":"ia-175","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, a vehicle stopped on a highway outside a town must be visible to other drivers from how far away in each direction?","o":["50 feet","100 feet","1 mile","200 feet"],"h1":"Do not stop just over a hill or around a curve.","h2":"In Iowa, a vehicle stopped on a highway outside a business or residence district must have a clear view of 200 feet in each direction.","p":"Right! Visible from 200 feet each way."},"es":{"q":"En Iowa, un vehículo detenido en una carretera fuera de un pueblo debe ser visible para otros conductores desde ¿qué distancia en cada dirección?","o":["50 pies","100 pies","1 milla","200 pies"],"h1":"No se detenga justo pasando una colina ni detrás de una curva.","h2":"En Iowa, un vehículo detenido en una carretera fuera de una zona comercial o residencial debe verse claramente a 200 pies en cada dirección.","p":"¡Correcto! Visible a 200 pies en cada sentido."},"ref":{"doc":"IA","page":null}},{"id":"ia-176","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, may you park on a bridge on a highway outside city limits?","o":["No, parking there is not allowed","Yes, if your hazard lights are on","Yes, for up to 10 minutes","Yes, if the bridge has a shoulder"],"h1":"Bridges outside towns are on the no-parking list.","h2":"In Iowa, you may not park on any bridge outside city limits or in a highway tunnel.","p":"Correct! No parking on bridges outside city limits."},"es":{"q":"En Iowa, ¿puede estacionarse en un puente de una carretera fuera de los límites de la ciudad?","o":["No, no se permite estacionarse allí","Sí, si tiene encendidas las luces de emergencia","Sí, hasta 10 minutos","Sí, si el puente tiene acotamiento"],"h1":"Los puentes fuera de los pueblos están en la lista de lugares prohibidos.","h2":"En Iowa, no puede estacionarse en ningún puente fuera de los límites de la ciudad ni en un túnel de carretera.","p":"¡Correcto! No se estaciona en puentes fuera de la ciudad."},"ref":{"doc":"IA","page":21}},{"id":"ia-177","scope":"IA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Iowa, the lights are flashing at a railroad crossing as you drive up in your own car. Where must you stop?","o":["Right on the tracks, to see better","Between 15 and 50 feet from the nearest rail","At least 100 feet from the tracks","Wherever traffic stops"],"h1":"Not too close, and not too far.","h2":"In Iowa, when a railroad crossing signal warns of a train, every driver must stop between 15 and 50 feet from the nearest rail.","p":"Right! Between 15 and 50 feet from the nearest rail."},"es":{"q":"En Iowa, las luces de un cruce de tren están parpadeando cuando usted llega en su carro particular. ¿Dónde debe detenerse?","o":["Sobre las vías, para ver mejor","Entre 15 y 50 pies del riel más cercano","Al menos a 100 pies de las vías","Donde se detenga el tránsito"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Iowa, cuando la señal de un cruce de tren avisa que viene un tren, todo conductor debe detenerse entre 15 y 50 pies del riel más cercano.","p":"¡Correcto! Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"IA","page":null}},{"id":"ia-178","scope":"IA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Iowa, a school bus is approaching a railroad crossing marked with an EXEMPT sign, and no train signal is active. Must the bus stop?","o":["Yes, buses must always stop","Yes, but only with children on board","No, the EXEMPT sign means the usual stop is not required","No, but it must honk"],"h1":"The sign removes the required stop for special vehicles.","h2":"In Iowa, vehicles that normally must stop at railroad crossings, such as school buses, do not have to stop where the crossing has an EXEMPT sign.","p":"Correct! An EXEMPT sign means no required stop."},"es":{"q":"En Iowa, un autobús escolar se acerca a un cruce de tren con un letrero EXEMPT (exento), y no hay señal de tren activa. ¿Debe detenerse el autobús?","o":["Sí, los autobuses siempre deben detenerse","Sí, pero solo con niños a bordo","No, el letrero EXEMPT significa que no se exige la parada habitual","No, pero debe tocar la bocina"],"h1":"El letrero quita la parada obligatoria para vehículos especiales.","h2":"En Iowa, los vehículos que normalmente deben detenerse en los cruces de tren, como los autobuses escolares, no tienen que hacerlo donde el cruce tiene un letrero EXEMPT.","p":"¡Correcto! Un letrero EXEMPT significa que no hay parada obligatoria."},"ref":{"doc":"IA","page":12}},{"id":"ia-179","scope":"IA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Iowa, what is the scheduled fine for driving around a lowered railroad crossing gate?","o":["$30","$70","$1,000","$260"],"h1":"It is a few hundred dollars.","h2":"In Iowa, the scheduled fine for railroad crossing violations, such as going around a lowered gate, is $260.","p":"Right! The scheduled fine is $260."},"es":{"q":"En Iowa, ¿cuál es la multa fija por rodear una barrera baja en un cruce de tren?","o":["$30","$70","$1,000","$260"],"h1":"Son unos cientos de dólares.","h2":"En Iowa, la multa fija por infracciones en cruces de tren, como rodear una barrera baja, es de $260.","p":"¡Correcto! La multa fija es de $260."},"ref":{"doc":"IA","page":null}},{"id":"ia-180","scope":"IA","cat":"signals","sign":null,"c":0,"en":{"q":"In Iowa, what is the blue Emergency Notification System (ENS) sign at a railroad crossing for?","o":["It gives a phone number and crossing ID to report a problem at the crossing","It shows the train schedule","It marks a place to park","It tells you the train's speed"],"h1":"Use it if a car is stalled or the signals are broken.","h2":"In Iowa, the blue ENS sign at a railroad crossing gives a railroad phone number and a crossing ID number to report stalled vehicles, broken signals or other dangers.","p":"Correct! Call the number and give the crossing ID."},"es":{"q":"En Iowa, ¿para qué sirve el letrero azul del Sistema de Notificación de Emergencias (ENS) en un cruce de tren?","o":["Da un número de teléfono y el número del cruce para reportar un problema","Muestra el horario de los trenes","Marca un lugar para estacionarse","Indica la velocidad del tren"],"h1":"Úselo si hay un carro atascado o si las señales no funcionan.","h2":"En Iowa, el letrero azul ENS en un cruce de tren da un teléfono de la empresa del tren y un número del cruce para reportar vehículos atascados, señales dañadas u otros peligros.","p":"¡Correcto! Llame al número y dé el número del cruce."},"ref":{"doc":"IA","page":8}},{"id":"ia-181","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, you come up behind a snowplow at work on the highway. Which side should you never pass it on?","o":["The left side, in the open lane","The shoulder side, where the plow pushes snow","Either side is fine at low speed","You may never pass a plow at all"],"h1":"Think about where the plow throws the snow.","h2":"In Iowa, never pass a snowplow on the shoulder side, because plows move snow onto the shoulders.","p":"Right! Never pass on the shoulder side."},"es":{"q":"En Iowa, va detrás de un quitanieves que trabaja en la carretera. ¿Por qué lado nunca debe rebasarlo?","o":["Por la izquierda, en el carril libre","Por el lado del acotamiento, donde el quitanieves empuja la nieve","Por cualquier lado, si va despacio","Nunca se puede rebasar un quitanieves"],"h1":"Piense hacia dónde lanza la nieve el quitanieves.","h2":"En Iowa, nunca rebase un quitanieves por el lado del acotamiento, porque los quitanieves echan la nieve hacia los acotamientos.","p":"¡Correcto! Nunca por el lado del acotamiento."},"ref":{"doc":"IA","page":61}},{"id":"ia-182","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, what happens to the scheduled fine for a moving violation committed in a road work zone?","o":["It stays the same","It is cut in half","It is doubled","It becomes a warning only"],"h1":"Work zones carry extra penalties.","h2":"In Iowa, the scheduled fine for a moving violation is doubled when it happens in a road work zone.","p":"Correct! Fines double in work zones."},"es":{"q":"En Iowa, ¿qué pasa con la multa fija de una infracción de tránsito cometida en una zona de obras?","o":["Sigue igual","Se reduce a la mitad","Se duplica","Se vuelve solo una advertencia"],"h1":"Las zonas de obras tienen sanciones adicionales.","h2":"En Iowa, la multa fija de una infracción de tránsito se duplica cuando ocurre en una zona de obras en la carretera.","p":"¡Correcto! Las multas se duplican en zonas de obras."},"ref":{"doc":"IA","page":null}},{"id":"ia-183","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, you drive 8 mph over the posted limit in a road work zone. What is the scheduled fine?","o":["$30","$55","$1,285","$195"],"h1":"Work zone speeding fines start near $200.","h2":"In Iowa, the scheduled fine for speeding 10 mph or less over the limit in a road work zone is $195.","p":"Right! $195 for 10 mph or less over."},"es":{"q":"En Iowa, maneja 8 mph sobre el límite en una zona de obras. ¿Cuál es la multa fija?","o":["$30","$55","$1,285","$195"],"h1":"Las multas por velocidad en zonas de obras empiezan cerca de $200.","h2":"En Iowa, la multa fija por exceder el límite 10 mph o menos en una zona de obras es de $195.","p":"¡Correcto! $195 por 10 mph o menos."},"ref":{"doc":"IA","page":null}},{"id":"ia-184","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, a driver goes 30 mph over the posted limit in a road work zone. What is the scheduled fine?","o":["$1,285","$390","$645","$135"],"h1":"It is the highest work zone speeding fine, over one thousand dollars.","h2":"In Iowa, the scheduled fine for speeding more than 25 mph over the limit in a road work zone is $1,285.","p":"Correct! $1,285."},"es":{"q":"En Iowa, un conductor va 30 mph sobre el límite en una zona de obras. ¿Cuál es la multa fija?","o":["$1,285","$390","$645","$135"],"h1":"Es la multa más alta por velocidad en zonas de obras, de más de mil dólares.","h2":"En Iowa, la multa fija por exceder el límite en más de 25 mph en una zona de obras es de $1,285.","p":"¡Correcto! $1,285."},"ref":{"doc":"IA","page":null}},{"id":"ia-185","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, outside a work zone, what is the scheduled fine for driving 8 mph over the speed limit?","o":["$30","$55","$105","$195"],"h1":"It is a little more than $50.","h2":"In Iowa, the scheduled fine for speeding more than 5 but not more than 10 mph over the limit is $55.","p":"Right! $55 for 6 to 10 mph over."},"es":{"q":"En Iowa, fuera de una zona de obras, ¿cuál es la multa fija por manejar 8 mph sobre el límite de velocidad?","o":["$30","$55","$105","$195"],"h1":"Es un poco más de $50.","h2":"En Iowa, la multa fija por exceder el límite en más de 5 y hasta 10 mph es de $55.","p":"¡Correcto! $55 por 6 a 10 mph sobre el límite."},"ref":{"doc":"IA","page":null}},{"id":"ia-186","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, outside a work zone, the scheduled fine for speeding more than 20 mph over is $135 plus $5 for each mph over 20. What is it for going 30 mph over?","o":["$135","$150","$185","$300"],"h1":"Ten extra miles per hour at $5 each.","h2":"In Iowa, going 30 mph over the limit has a scheduled fine of $185, which is $135 plus $5 for each of the 10 mph above 20.","p":"Correct! $135 plus $50 makes $185."},"es":{"q":"En Iowa, fuera de una zona de obras, la multa fija por exceder el límite en más de 20 mph es de $135 más $5 por cada mph arriba de 20. ¿Cuánto es por ir 30 mph sobre el límite?","o":["$135","$150","$185","$300"],"h1":"Diez millas por hora extra, a $5 cada una.","h2":"En Iowa, ir 30 mph sobre el límite tiene una multa fija de $185, es decir, $135 más $5 por cada una de las 10 mph arriba de 20.","p":"¡Correcto! $135 más $50 son $185."},"ref":{"doc":"IA","page":null}},{"id":"ia-187","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, unless a sign says otherwise, what is the speed limit in a residential district or school district?","o":["15 mph","35 mph","20 mph","25 mph"],"h1":"It is 5 mph faster than a business district.","h2":"In Iowa, when no limit is posted, the speed limit is 25 mph in a residential district or school district.","p":"Right! 25 mph."},"es":{"q":"En Iowa, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona residencial o escolar?","o":["15 mph","35 mph","20 mph","25 mph"],"h1":"Es 5 mph más que en una zona comercial.","h2":"En Iowa, cuando no hay límite indicado, el límite es de 25 mph en una zona residencial o escolar.","p":"¡Correcto! 25 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-188","scope":"IA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Iowa, unless a sign says otherwise, what is the speed limit in a suburban district?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"It is the same as the limit for a vehicle pulling a trailer.","h2":"In Iowa, when no limit is posted, the speed limit in a suburban district is 45 mph.","p":"Correct! 45 mph."},"es":{"q":"En Iowa, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona suburbana?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"Es el mismo límite que para un vehículo que remolca un tráiler.","h2":"En Iowa, cuando no hay límite indicado, el límite en una zona suburbana es de 45 mph.","p":"¡Correcto! 45 mph."},"ref":{"doc":"IA","page":42}},{"id":"ia-189","scope":"IA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Iowa, you drive a car on an unpaved (gravel) county road after sunset, and no limit is posted. What is the speed limit?","o":["35 mph","50 mph","60 mph","70 mph"],"h1":"Gravel roads at night have a lower limit than in daytime.","h2":"In Iowa, the general speed limit on unsurfaced secondary roads from sunset until sunrise is 50 mph.","p":"Right! 50 mph at night on unpaved roads."},"es":{"q":"En Iowa, maneja un carro por un camino de condado sin pavimentar (grava) después de la puesta del sol, y no hay límite indicado. ¿Cuál es el límite de velocidad?","o":["35 mph","50 mph","60 mph","70 mph"],"h1":"En los caminos de grava, de noche el límite es menor que de día.","h2":"En Iowa, el límite general en caminos secundarios sin pavimentar desde la puesta hasta la salida del sol es de 50 mph.","p":"¡Correcto! 50 mph de noche en caminos sin pavimentar."},"ref":{"doc":"IA","page":42}},{"id":"ia-190","scope":"IA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Iowa, what is the speed limit on a fully controlled-access, divided, multilane highway that is not an interstate, unless a lower limit is posted?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"It is 5 mph lower than on interstates.","h2":"In Iowa, the speed limit on fully controlled-access, divided, multilane highways is 65 mph, while interstates are 70 mph.","p":"Correct! 65 mph."},"es":{"q":"En Iowa, ¿cuál es el límite de velocidad en una carretera dividida, de varios carriles y de acceso totalmente controlado que no es interestatal, salvo que se indique uno menor?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Es 5 mph menos que en las autopistas interestatales.","h2":"En Iowa, el límite en carreteras divididas, de varios carriles y de acceso totalmente controlado es de 65 mph, mientras que en las interestatales es de 70 mph.","p":"¡Correcto! 65 mph."},"ref":{"doc":"IA","page":null}},{"id":"ia-191","scope":"IA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Iowa driver's manual, what following distance should a beginning driver keep in normal conditions?","o":["One car length","1 second","2 seconds","At least 3 seconds"],"h1":"New drivers need a little more time than experienced drivers.","h2":"The Iowa driver's manual says an inexperienced or beginning driver should keep at least a three-second following distance in normal conditions.","p":"Right! At least 3 seconds."},"es":{"q":"Según el manual de manejo de Iowa, ¿qué distancia de seguimiento debe mantener un conductor principiante en condiciones normales?","o":["El largo de un carro","1 segundo","2 segundos","Al menos 3 segundos"],"h1":"Los conductores nuevos necesitan un poco más de tiempo que los experimentados.","h2":"El manual de manejo de Iowa dice que un conductor principiante o sin experiencia debe mantener al menos 3 segundos de distancia en condiciones normales.","p":"¡Correcto! Al menos 3 segundos."},"ref":{"doc":"IA","page":41}},{"id":"ia-192","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Iowa driver's manual, what following distance is recommended at 40 mph?","o":["4 to 5 seconds","1 second","2 seconds","10 seconds"],"h1":"At higher speeds you need more time to stop.","h2":"The Iowa driver's manual recommends a following distance of four to five seconds at 40 mph.","p":"Correct! Four to five seconds."},"es":{"q":"Según el manual de manejo de Iowa, ¿qué distancia de seguimiento se recomienda a 40 mph?","o":["De 4 a 5 segundos","1 segundo","2 segundos","10 segundos"],"h1":"A mayor velocidad, necesita más tiempo para detenerse.","h2":"El manual de manejo de Iowa recomienda una distancia de seguimiento de cuatro a cinco segundos a 40 mph.","p":"¡Correcto! De cuatro a cinco segundos."},"ref":{"doc":"IA","page":41}},{"id":"ia-193","scope":"IA","cat":"signals","sign":null,"c":1,"en":{"q":"In Iowa, a car behind you is following too closely and you must slow down where others may not expect it. What does the manual suggest?","o":["Brake hard once","Tap your brake pedal three or four times quickly","Turn on your high beams","Wave your arm out the window"],"h1":"Flashing your brake lights gets attention.","h2":"The Iowa driver's manual says to tap the brake pedal three or four times quickly to warn drivers behind you that you are about to slow down.","p":"Right! Tap the brakes three or four times."},"es":{"q":"En Iowa, un carro lo sigue muy de cerca y usted debe bajar la velocidad donde otros quizás no lo esperan. ¿Qué sugiere el manual?","o":["Frenar fuerte una vez","Pisar el freno tres o cuatro veces rápido","Encender las luces altas","Sacar el brazo por la ventana y agitarlo"],"h1":"Encender y apagar las luces de freno llama la atención.","h2":"El manual de manejo de Iowa dice que pise el pedal del freno tres o cuatro veces rápido para avisar a los de atrás que va a bajar la velocidad.","p":"¡Correcto! Pise el freno tres o cuatro veces."},"ref":{"doc":"IA","page":41}},{"id":"ia-194","scope":"IA","cat":"signals","sign":null,"c":2,"en":{"q":"In Iowa, you are using high beams at night. Within how many feet of an oncoming vehicle must you dim them?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"Iowa's distance is longer than many states use.","h2":"In Iowa, you must dim your high beams when an oncoming vehicle is within 1,000 feet.","p":"Correct! Dim within 1,000 feet."},"es":{"q":"En Iowa, usa las luces altas de noche. ¿A menos de cuántos pies de un vehículo que viene de frente debe bajarlas?","o":["200 pies","500 pies","1,000 pies","2,000 pies"],"h1":"La distancia de Iowa es mayor que la de muchos estados.","h2":"En Iowa, debe bajar las luces altas cuando un vehículo que viene de frente está a menos de 1,000 pies.","p":"¡Correcto! Bájelas a menos de 1,000 pies."},"ref":{"doc":"IA","page":null}},{"id":"ia-195","scope":"IA","cat":"signals","sign":null,"c":3,"en":{"q":"In Iowa, you are following another vehicle at night. Within how many feet behind it must you use low beams?","o":["100 feet","200 feet","1,000 feet","400 feet"],"h1":"It is less than half the distance for oncoming cars.","h2":"In Iowa, you must use low beams when following another vehicle within 400 feet, except while passing.","p":"Right! Use low beams within 400 feet."},"es":{"q":"En Iowa, de noche va detrás de otro vehículo. ¿A menos de cuántos pies de él debe usar las luces bajas?","o":["100 pies","200 pies","1,000 pies","400 pies"],"h1":"Es menos de la mitad de la distancia para los que vienen de frente.","h2":"En Iowa, debe usar las luces bajas cuando sigue a otro vehículo a menos de 400 pies, salvo mientras lo rebasa.","p":"¡Correcto! Luces bajas a menos de 400 pies."},"ref":{"doc":"IA","page":null}},{"id":"ia-196","scope":"IA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Iowa driver's manual, which months are the peak months for deer crashes in Iowa?","o":["October, November and May","January and February","June, July and August","March and April"],"h1":"Think of fall, plus one month in late spring.","h2":"The Iowa driver's manual says October, November and May are the peak months for deer collisions, though they can happen any time.","p":"Correct! October, November and May."},"es":{"q":"Según el manual de manejo de Iowa, ¿cuáles son los meses con más choques con venados en Iowa?","o":["Octubre, noviembre y mayo","Enero y febrero","Junio, julio y agosto","Marzo y abril"],"h1":"Piense en el otoño, más un mes al final de la primavera.","h2":"El manual de manejo de Iowa dice que octubre, noviembre y mayo son los meses con más choques con venados, aunque pueden ocurrir en cualquier momento.","p":"¡Correcto! Octubre, noviembre y mayo."},"ref":{"doc":"IA","page":57}},{"id":"ia-197","scope":"IA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Iowa, you see a dog trapped in a hot, closed car and it looks very sick. What does the Iowa driver's manual say about breaking a window?","o":["It is always illegal","It is legal in Iowa to break a window to give medical help to a person or animal trapped inside","Only police may do it","Only the owner may do it"],"h1":"Iowa allows people to act to save a life.","h2":"The Iowa driver's manual says it is legal in Iowa to break a vehicle's window to provide medical attention to a person or animal trapped inside.","p":"Right! It is legal to break a window to help."},"es":{"q":"En Iowa, ve a un perro encerrado en un carro caliente y se ve muy mal. ¿Qué dice el manual de manejo de Iowa sobre romper una ventana?","o":["Siempre es ilegal","En Iowa es legal romper una ventana para dar ayuda médica a una persona o animal atrapado","Solo la policía puede hacerlo","Solo el dueño puede hacerlo"],"h1":"Iowa permite actuar para salvar una vida.","h2":"El manual de manejo de Iowa dice que en Iowa es legal romper la ventana de un vehículo para dar atención médica a una persona o animal atrapado adentro.","p":"¡Correcto! Es legal romper una ventana para ayudar."},"ref":{"doc":"IA","page":59}},{"id":"ia-198","scope":"IA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Iowa, during which months may a regular car use studded tires?","o":["All year","June 1 to September 1","November 1 to April 1","Only in January"],"h1":"It matches the snowy season.","h2":"In Iowa, tires with studs or ice grips may be used from November 1 to April 1.","p":"Correct! November 1 to April 1."},"es":{"q":"En Iowa, ¿en qué meses puede un carro normal usar llantas con clavos?","o":["Todo el año","Del 1 de junio al 1 de septiembre","Del 1 de noviembre al 1 de abril","Solo en enero"],"h1":"Coincide con la temporada de nieve.","h2":"En Iowa, las llantas con clavos o con agarres para hielo se pueden usar del 1 de noviembre al 1 de abril.","p":"¡Correcto! Del 1 de noviembre al 1 de abril."},"ref":{"doc":"IA","page":null}},{"id":"ia-199","scope":"IA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Iowa, may a person ride a bicycle on an interstate or another fully controlled-access highway?","o":["Yes, on the shoulder","Yes, if wearing a helmet","Yes, during daylight","No, bicycles and pedestrians are not allowed there"],"h1":"These highways are only for motor vehicles.","h2":"In Iowa, riding a bicycle, using a pedestrian device or walking anywhere on a fully controlled-access highway, such as an interstate, is not allowed.","p":"Right! No bicycles or pedestrians on these highways."},"es":{"q":"En Iowa, ¿puede una persona andar en bicicleta por una autopista interestatal u otra carretera de acceso totalmente controlado?","o":["Sí, por el acotamiento","Sí, si usa casco","Sí, de día","No, allí no se permiten bicicletas ni peatones"],"h1":"Estas carreteras son solo para vehículos motorizados.","h2":"En Iowa, no se permite andar en bicicleta, usar aparatos de peatón ni caminar en ninguna parte de una carretera de acceso totalmente controlado, como una interestatal.","p":"¡Correcto! Ni bicicletas ni peatones en estas carreteras."},"ref":{"doc":"IA","page":null}},{"id":"ia-200","scope":"IA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Iowa, which car feature may you NOT use during your driving test?","o":["Adaptive cruise control","A backup camera","A blind spot warning","Lane departure warning"],"h1":"Safety warnings are allowed; convenience features that drive for you are not.","h2":"In Iowa, adaptive cruise control and automatic parallel parking may not be used during the driving test, while safety features like backup cameras are allowed.","p":"Correct! No adaptive cruise control on the test."},"es":{"q":"En Iowa, ¿qué función del carro NO puede usar durante la prueba de manejo?","o":["El control de crucero adaptativo","La cámara de reversa","El aviso de punto ciego","El aviso de salida de carril"],"h1":"Se permiten los avisos de seguridad, no las funciones de comodidad que manejan por usted.","h2":"En Iowa, no se puede usar el control de crucero adaptativo ni el estacionamiento automático en paralelo durante la prueba de manejo; las funciones de seguridad como la cámara de reversa sí se permiten.","p":"¡Correcto! Nada de control de crucero adaptativo en la prueba."},"ref":{"doc":"IA","page":26}},{"id":"id-001","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many questions are on the written knowledge test?","o":["20 questions","25 questions","40 questions","50 questions"],"h1":"It is more than 25 and fewer than 50.","h2":"The Idaho knowledge test has 40 questions, all taken from the driver's handbook.","p":"Right. The Idaho test has 40 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas tiene el examen escrito de conocimientos?","o":["20 preguntas","25 preguntas","40 preguntas","50 preguntas"],"h1":"Son más de 25 y menos de 50.","h2":"El examen de conocimientos de Idaho tiene 40 preguntas, todas tomadas del manual del conductor.","p":"Correcto. El examen de Idaho tiene 40 preguntas."},"zh":{"q":"在 Idaho，驾照笔试有多少道题？","o":["20 道题","25 道题","40 道题","50 道题"],"h1":"比 25 多，比 50 少。","h2":"Idaho 的驾照笔试有 40 道题，都来自驾驶手册。","p":"对。Idaho 的笔试有 40 道题。"},"vi":{"q":"Ở Idaho, bài thi kiến thức viết có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","40 câu hỏi","50 câu hỏi"],"h1":"Nhiều hơn 25 và ít hơn 50.","h2":"Bài thi kiến thức của Idaho có 40 câu hỏi, tất cả đều lấy từ sổ tay lái xe.","p":"Đúng. Bài thi của Idaho có 40 câu hỏi."},"tl":{"q":"Sa Idaho, ilang tanong ang nasa nakasulat na knowledge test?","o":["20 tanong","25 tanong","40 tanong","50 tanong"],"h1":"Higit ito sa 25 at kulang sa 50.","h2":"Ang knowledge test ng Idaho ay may 40 tanong, lahat ay kinuha mula sa driver's handbook.","p":"Tama. Ang test ng Idaho ay may 40 tanong."},"ar":{"q":"في Idaho، كم عدد الأسئلة في اختبار المعرفة الكتابي؟","o":["20 سؤالًا","25 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"العدد أكثر من 25 وأقل من 50.","h2":"اختبار المعرفة في Idaho فيه 40 سؤالًا، وكلها مأخوذة من دليل السائق.","p":"صحيح. اختبار Idaho فيه 40 سؤالًا."},"ref":{"doc":"ID","page":32}},{"id":"id-002","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many questions can you miss on the knowledge test and still pass?","o":["Up to 6","Up to 2","Up to 10","Up to 12"],"h1":"You need a high score, about 85 percent.","h2":"On the Idaho knowledge test you can miss up to 6 of the 40 questions, so you need 34 right answers to pass.","p":"Well done. You can miss up to 6 questions."},"es":{"q":"En Idaho, ¿cuántas preguntas puede fallar en el examen de conocimientos y aun así aprobar?","o":["Hasta 6","Hasta 2","Hasta 10","Hasta 12"],"h1":"Se necesita una nota alta, de alrededor del 85 por ciento.","h2":"En el examen de conocimientos de Idaho usted puede fallar hasta 6 de las 40 preguntas, así que necesita 34 respuestas correctas para aprobar.","p":"Muy bien. Puede fallar hasta 6 preguntas."},"zh":{"q":"在 Idaho，驾照笔试最多可以答错几道题还能通过？","o":["最多 6 道","最多 2 道","最多 10 道","最多 12 道"],"h1":"你需要很高的分数，大约 85%。","h2":"在 Idaho 的驾照笔试中，40 道题你最多可以答错 6 道，所以你需要答对 34 道才能通过。","p":"很好。你最多可以答错 6 道题。"},"vi":{"q":"Ở Idaho, bạn có thể trả lời sai bao nhiêu câu trong bài thi kiến thức mà vẫn đậu?","o":["Tối đa 6 câu","Tối đa 2 câu","Tối đa 10 câu","Tối đa 12 câu"],"h1":"Bạn cần điểm cao, khoảng 85 phần trăm.","h2":"Trong bài thi kiến thức của Idaho, bạn có thể sai tối đa 6 trên 40 câu, nên bạn cần 34 câu đúng để đậu.","p":"Giỏi lắm. Bạn có thể sai tối đa 6 câu."},"tl":{"q":"Sa Idaho, ilang tanong ang puwede mong mamali sa knowledge test at pumasa pa rin?","o":["Hanggang 6","Hanggang 2","Hanggang 10","Hanggang 12"],"h1":"Kailangan mo ng mataas na score, mga 85 porsiyento.","h2":"Sa knowledge test ng Idaho, puwede kang magkamali sa hanggang 6 sa 40 tanong, kaya kailangan mo ng 34 na tamang sagot para pumasa.","p":"Magaling. Puwede kang magkamali sa hanggang 6 na tanong."},"ar":{"q":"في Idaho، كم سؤالًا يمكن أن تخطئ فيه في اختبار المعرفة وتنجح مع ذلك؟","o":["حتى 6","حتى 2","حتى 10","حتى 12"],"h1":"تحتاج إلى درجة عالية، حوالي 85 بالمئة.","h2":"في اختبار المعرفة في Idaho يمكنك أن تخطئ في 6 أسئلة على الأكثر من 40، لذلك تحتاج إلى 34 إجابة صحيحة لتنجح.","p":"أحسنت. يمكنك أن تخطئ في 6 أسئلة على الأكثر."},"ref":{"doc":"ID","page":32}},{"id":"id-003","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, how long must a teen hold the supervised instruction permit, at a minimum?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half of a year.","h2":"An Idaho teen must hold the supervised instruction permit for at least six months without any violation.","p":"Right. The minimum is six months."},"es":{"q":"En Idaho, ¿por cuánto tiempo como mínimo debe un joven tener el permiso de instrucción supervisada?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es la mitad de un año.","h2":"Un joven en Idaho debe tener el permiso de instrucción supervisada por lo menos seis meses sin ninguna infracción.","p":"Correcto. El mínimo es de seis meses."},"zh":{"q":"在 Idaho，青少年必须持有有人陪同的学习驾照（supervised instruction permit）最少多久？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"Idaho 的青少年必须持有有人陪同的学习驾照至少六个月，而且没有任何违规。","p":"对。最少是六个月。"},"vi":{"q":"Ở Idaho, thiếu niên phải giữ giấy phép tập lái có giám sát (supervised instruction permit) ít nhất bao lâu?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Idaho, thiếu niên phải giữ giấy phép tập lái có giám sát ít nhất sáu tháng mà không có vi phạm nào.","p":"Đúng. Tối thiểu là sáu tháng."},"tl":{"q":"Sa Idaho, gaano katagal, hindi bababa, dapat hawak ng isang teen ang supervised instruction permit?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang isang teen sa Idaho ay dapat humawak ng supervised instruction permit nang hindi bababa sa anim na buwan nang walang anumang paglabag.","p":"Tama. Ang pinakamababa ay anim na buwan."},"ar":{"q":"في Idaho، ما أقل مدة يجب أن يحتفظ فيها المراهق بتصريح التعلّم تحت الإشراف (supervised instruction permit)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Idaho أن يحتفظ بتصريح التعلّم تحت الإشراف ستة أشهر على الأقل دون أي مخالفة.","p":"صحيح. أقل مدة هي ستة أشهر."},"ref":{"doc":"ID","page":19}},{"id":"id-004","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how old must the licensed driver beside a permit holder be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to buy alcohol legally.","h2":"In Idaho the supervising driver must hold a valid license, be at least 21 years old, and sit in the seat beside the permit holder.","p":"Correct. The supervisor must be 21 or older."},"es":{"q":"En Idaho, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene el permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener la edad para comprar alcohol legalmente.","h2":"En Idaho el conductor que supervisa debe tener licencia válida, por lo menos 21 años, y sentarse al lado de quien tiene el permiso.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Idaho，坐在持学习驾照的人旁边、有驾照的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法买酒的年龄。","h2":"在 Idaho，陪同的司机必须有有效驾照、至少 21 岁，并坐在持学习驾照的人旁边的座位上。","p":"正确。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở Idaho, người có bằng lái ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để mua rượu hợp pháp.","h2":"Ở Idaho, người giám sát phải có bằng lái hợp lệ, ít nhất 21 tuổi, và ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Chính xác. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Idaho, ilang taon dapat ang lisensyadong driver na katabi ng may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng katuwang para legal na makabili ng alak.","h2":"Sa Idaho, ang nagbabantay na driver ay dapat may valid na lisensya, hindi bababa sa 21 taong gulang, at nakaupo sa upuang katabi ng may hawak ng permit.","p":"Tama. Ang nagbabantay ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Idaho، كم يجب أن يكون عمر السائق المرخّص الذي يجلس بجانب حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في سنّ تسمح له بشراء الكحول قانونيًا.","h2":"في Idaho يجب أن يحمل السائق المشرف رخصة سارية، وأن يكون عمره 21 سنة على الأقل، وأن يجلس في المقعد المجاور لحامل التصريح.","p":"صحيح. يجب أن يكون المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"ID","page":19}},{"id":"id-005","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many hours of supervised driving must a teen complete with the instruction permit?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is more than 30 hours.","h2":"An Idaho teen must complete at least 50 hours of supervised driving while holding the instruction permit.","p":"Right. Idaho requires 50 supervised hours."},"es":{"q":"En Idaho, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Son más de 30 horas.","h2":"Un joven en Idaho debe completar por lo menos 50 horas de manejo supervisado mientras tiene el permiso de instrucción.","p":"Correcto. Idaho exige 50 horas supervisadas."},"zh":{"q":"在 Idaho，青少年持学习驾照期间，必须完成多少小时有人陪同的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"比 30 小时多。","h2":"Idaho 的青少年持学习驾照期间，必须完成至少 50 小时有人陪同的驾驶。","p":"对。Idaho 要求 50 小时有人陪同的驾驶。"},"vi":{"q":"Ở Idaho, thiếu niên phải lái xe có giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Nhiều hơn 30 giờ.","h2":"Ở Idaho, thiếu niên phải lái xe có giám sát ít nhất 50 giờ khi đang giữ giấy phép tập lái.","p":"Đúng. Idaho yêu cầu 50 giờ lái có giám sát."},"tl":{"q":"Sa Idaho, ilang oras ng supervised driving ang dapat tapusin ng isang teen habang may instruction permit?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Higit ito sa 30 oras.","h2":"Ang isang teen sa Idaho ay dapat makatapos ng hindi bababa sa 50 oras ng supervised driving habang hawak ang instruction permit.","p":"Tama. Ang Idaho ay nangangailangan ng 50 oras na may bantay."},"ar":{"q":"في Idaho، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق وهو يحمل تصريح التعلّم؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"العدد أكثر من 30 ساعة.","h2":"يجب على المراهق في Idaho أن يُكمل 50 ساعة على الأقل من القيادة تحت الإشراف وهو يحمل تصريح التعلّم.","p":"صحيح. Idaho تطلب 50 ساعة تحت الإشراف."},"ref":{"doc":"ID","page":19}},{"id":"id-006","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many of the supervised practice hours must be at night?","o":["10 hours","2 hours","5 hours","25 hours"],"h1":"It is a round number, smaller than 20.","h2":"At least 10 of the 50 supervised hours in Idaho must be driven at night.","p":"Correct. Ten of the hours must be at night."},"es":{"q":"En Idaho, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["10 horas","2 horas","5 horas","25 horas"],"h1":"Es un número redondo, menor que 20.","h2":"En Idaho, por lo menos 10 de las 50 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Idaho，有人陪同的练习时间里，必须有多少小时是在夜间？","o":["10 小时","2 小时","5 小时","25 小时"],"h1":"这是一个整数，比 20 小。","h2":"在 Idaho，50 小时有人陪同的驾驶中，至少 10 小时必须在夜间开。","p":"正确。其中十个小时必须在夜间。"},"vi":{"q":"Ở Idaho, bao nhiêu giờ tập lái có giám sát phải là vào ban đêm?","o":["10 giờ","2 giờ","5 giờ","25 giờ"],"h1":"Đó là một số tròn, nhỏ hơn 20.","h2":"Ở Idaho, ít nhất 10 trong 50 giờ lái có giám sát phải là lái vào ban đêm.","p":"Chính xác. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Idaho, ilan sa mga oras ng supervised practice ang dapat gawin sa gabi?","o":["10 oras","2 oras","5 oras","25 oras"],"h1":"Buong numero ito, mas maliit sa 20.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised driving sa Idaho ay dapat gawin sa gabi.","p":"Tama. Sampu sa mga oras ay dapat sa gabi."},"ar":{"q":"في Idaho، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","ساعتان (2)","5 ساعات","25 ساعة"],"h1":"هو عدد مُدوَّر، أقل من 20.","h2":"يجب أن تكون 10 ساعات على الأقل من الخمسين ساعة تحت الإشراف في Idaho قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"ID","page":19}},{"id":"id-007","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, what happens if a teen with a supervised instruction permit gets a traffic conviction?","o":["Nothing changes","The permit is canceled and the six months start over","The teen pays a fine and keeps the same permit","The teen gets the license sooner"],"h1":"The violation-free period has to be earned again.","h2":"In Idaho a traffic conviction cancels the supervised instruction permit, and the six-month period starts over with a new permit.","p":"Right. The six months start again."},"es":{"q":"En Idaho, ¿qué pasa si un joven con permiso de instrucción supervisada recibe una condena de tránsito?","o":["No cambia nada","Se cancela el permiso y los seis meses empiezan de nuevo","El joven paga una multa y conserva el mismo permiso","El joven obtiene la licencia antes"],"h1":"El período sin infracciones se tiene que ganar otra vez.","h2":"En Idaho una condena de tránsito cancela el permiso de instrucción supervisada, y el período de seis meses empieza de nuevo con un permiso nuevo.","p":"Correcto. Los seis meses empiezan otra vez."},"zh":{"q":"在 Idaho，持有人陪同学习驾照的青少年如果被判交通违规，会怎么样？","o":["什么都不变","学习驾照被取消，六个月重新开始算","青少年交罚款，保留原来的学习驾照","青少年可以更早拿到驾照"],"h1":"没有违规的那段时间必须重新挣回来。","h2":"在 Idaho，被判交通违规会让有人陪同的学习驾照被取消，换新的学习驾照后，六个月重新开始算。","p":"对。六个月重新开始算。"},"vi":{"q":"Ở Idaho, điều gì xảy ra nếu thiếu niên có giấy phép tập lái có giám sát bị kết tội vi phạm giao thông?","o":["Không có gì thay đổi","Giấy phép bị hủy và sáu tháng bắt đầu lại từ đầu","Thiếu niên đóng tiền phạt và giữ giấy phép cũ","Thiếu niên được lấy bằng lái sớm hơn"],"h1":"Thời gian không vi phạm phải được tính lại.","h2":"Ở Idaho, khi bị kết tội vi phạm giao thông thì giấy phép tập lái có giám sát bị hủy, và thời gian sáu tháng bắt đầu lại với giấy phép mới.","p":"Đúng. Sáu tháng bắt đầu lại."},"tl":{"q":"Sa Idaho, ano ang mangyayari kung ang teen na may supervised instruction permit ay ma-convict sa isang traffic violation?","o":["Walang magbabago","Kakanselahin ang permit at magsisimula ulit ang anim na buwan","Magbabayad ng multa ang teen at mananatili ang parehong permit","Mas maagang makakakuha ng lisensya ang teen"],"h1":"Kailangang kitain ulit ang panahong walang paglabag.","h2":"Sa Idaho, kinakansela ng traffic conviction ang supervised instruction permit, at magsisimula ulit ang anim na buwan sa bagong permit.","p":"Tama. Magsisimula ulit ang anim na buwan."},"ar":{"q":"في Idaho، ماذا يحدث إذا أُدين مراهق يحمل تصريح التعلّم تحت الإشراف بمخالفة مرورية؟","o":["لا يتغير شيء","يُلغى التصريح وتبدأ الأشهر الستة من جديد","يدفع المراهق غرامة ويحتفظ بنفس التصريح","يحصل المراهق على الرخصة أسرع"],"h1":"يجب كسب فترة بدون مخالفات من جديد.","h2":"في Idaho تؤدي الإدانة بمخالفة مرورية إلى إلغاء تصريح التعلّم تحت الإشراف، وتبدأ فترة الأشهر الستة من جديد مع تصريح جديد.","p":"صحيح. تبدأ الأشهر الستة من جديد."},"ref":{"doc":"ID","page":19}},{"id":"id-008","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, who must wear a seat belt while a teen drives with a supervised instruction permit?","o":["Only the driver","Only people in the front seat","Only children","Everyone in the vehicle"],"h1":"Think about every seat in the car.","h2":"While an Idaho teen drives on a supervised instruction permit, everyone in the vehicle must wear a seat belt.","p":"Correct. Everyone must be buckled."},"es":{"q":"En Idaho, ¿quién debe usar cinturón de seguridad mientras un joven maneja con permiso de instrucción supervisada?","o":["Solo el conductor","Solo las personas del asiento delantero","Solo los niños","Todas las personas en el vehículo"],"h1":"Piense en cada asiento del carro.","h2":"Mientras un joven en Idaho maneja con permiso de instrucción supervisada, todas las personas en el vehículo deben usar cinturón de seguridad.","p":"Correcto. Todos deben ir abrochados."},"zh":{"q":"在 Idaho，青少年持有人陪同的学习驾照开车时，谁必须系安全带？","o":["只有司机","只有前排的人","只有小孩","车里的每一个人"],"h1":"想一想车里的每个座位。","h2":"Idaho 的青少年持有人陪同的学习驾照开车时，车里的每一个人都必须系安全带。","p":"正确。每个人都必须系好安全带。"},"vi":{"q":"Ở Idaho, ai phải thắt dây an toàn khi thiếu niên lái xe với giấy phép tập lái có giám sát?","o":["Chỉ người lái","Chỉ người ngồi ghế trước","Chỉ trẻ em","Mọi người trong xe"],"h1":"Hãy nghĩ đến mọi ghế trong xe.","h2":"Khi thiếu niên ở Idaho lái xe với giấy phép tập lái có giám sát, mọi người trong xe đều phải thắt dây an toàn.","p":"Chính xác. Mọi người đều phải thắt dây."},"tl":{"q":"Sa Idaho, sino ang dapat magsuot ng seat belt habang nagmamaneho ang isang teen na may supervised instruction permit?","o":["Ang driver lang","Ang mga nasa harapang upuan lang","Ang mga bata lang","Lahat ng nasa sasakyan"],"h1":"Isipin ang bawat upuan sa kotse.","h2":"Habang nagmamaneho ang isang teen sa Idaho na may supervised instruction permit, lahat ng nasa sasakyan ay dapat magsuot ng seat belt.","p":"Tama. Lahat ay dapat naka-seat belt."},"ar":{"q":"في Idaho، مَن يجب أن يربط حزام الأمان عندما يقود مراهق بتصريح التعلّم تحت الإشراف؟","o":["السائق فقط","الجالسون في المقعد الأمامي فقط","الأطفال فقط","كل مَن في السيارة"],"h1":"فكّر في كل مقعد في السيارة.","h2":"عندما يقود مراهق في Idaho بتصريح التعلّم تحت الإشراف، يجب على كل مَن في السيارة أن يربط حزام الأمان.","p":"صحيح. يجب أن يربط الجميع الحزام."},"ref":{"doc":"ID","page":19}},{"id":"id-009","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what must a teen have with them while driving on a supervised instruction permit?","o":["A school ID","A passport","The permit itself","A letter from a teacher"],"h1":"It is the document that allows the practice driving.","h2":"An Idaho teen must carry the supervised instruction permit while driving.","p":"Right. Keep the permit with you."},"es":{"q":"En Idaho, ¿qué debe llevar consigo un joven mientras maneja con permiso de instrucción supervisada?","o":["Su identificación escolar","Su pasaporte","El permiso mismo","Una carta de un maestro"],"h1":"Es el documento que le permite practicar.","h2":"Un joven en Idaho debe llevar consigo el permiso de instrucción supervisada mientras maneja.","p":"Correcto. Lleve el permiso con usted."},"zh":{"q":"在 Idaho，青少年持有人陪同的学习驾照开车时，必须随身带着什么？","o":["学生证","护照","学习驾照本身","老师写的信"],"h1":"就是允许你练习开车的那份证件。","h2":"Idaho 的青少年开车时必须随身带着有人陪同的学习驾照。","p":"对。把学习驾照带在身上。"},"vi":{"q":"Ở Idaho, thiếu niên phải mang theo gì khi lái xe với giấy phép tập lái có giám sát?","o":["Thẻ học sinh","Hộ chiếu","Chính giấy phép tập lái","Thư của giáo viên"],"h1":"Đó là giấy tờ cho phép tập lái xe.","h2":"Thiếu niên ở Idaho phải mang theo giấy phép tập lái có giám sát khi lái xe.","p":"Đúng. Hãy mang giấy phép theo bên mình."},"tl":{"q":"Sa Idaho, ano ang dapat dala ng isang teen habang nagmamaneho na may supervised instruction permit?","o":["School ID","Pasaporte","Ang permit mismo","Sulat mula sa guro"],"h1":"Ito ang dokumentong nagpapahintulot sa pagsasanay sa pagmamaneho.","h2":"Ang isang teen sa Idaho ay dapat magdala ng supervised instruction permit habang nagmamaneho.","p":"Tama. Dalhin mo palagi ang permit."},"ar":{"q":"في Idaho، ماذا يجب أن يحمل المراهق معه عندما يقود بتصريح التعلّم تحت الإشراف؟","o":["بطاقة المدرسة","جواز السفر","التصريح نفسه","رسالة من معلّم"],"h1":"هو المستند الذي يسمح بالتدرّب على القيادة.","h2":"يجب على المراهق في Idaho أن يحمل تصريح التعلّم تحت الإشراف معه أثناء القيادة.","p":"صحيح. احمل التصريح معك."},"ref":{"doc":"ID","page":null}},{"id":"id-010","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, when may a licensed driver under 16 drive alone?","o":["Only during daylight hours","Only after sunset","Any time of day","Only on weekends"],"h1":"Night driving needs an adult in the front seat.","h2":"In Idaho a licensed driver under 16 may drive only in daylight hours, 5 a.m. to 10 p.m., unless a licensed person 21 or older sits in the front seat.","p":"Correct. Under 16 means daylight only."},"es":{"q":"En Idaho, ¿cuándo puede manejar solo un conductor con licencia menor de 16 años?","o":["Solo durante las horas de luz del día","Solo después de la puesta del sol","A cualquier hora","Solo los fines de semana"],"h1":"Para manejar de noche se necesita un adulto en el asiento delantero.","h2":"En Idaho un conductor con licencia menor de 16 años solo puede manejar en horas de luz del día, de 5 a.m. a 10 p.m., a menos que una persona con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Menor de 16 significa solo de día."},"zh":{"q":"在 Idaho，16 岁以下、有驾照的司机什么时候可以一个人开车？","o":["只能在白天时段","只能在日落以后","一天中任何时间，白天或夜间都可以","只能在周末"],"h1":"夜间开车需要一个成年人坐在前排。","h2":"在 Idaho，16 岁以下、有驾照的司机只能在白天时段开车，也就是早上 5 点到晚上 10 点，除非有一位 21 岁或以上、有驾照的人坐在前排。","p":"正确。16 岁以下只能在白天开车。"},"vi":{"q":"Ở Idaho, khi nào người có bằng lái dưới 16 tuổi được lái xe một mình?","o":["Chỉ vào giờ ban ngày","Chỉ sau khi mặt trời lặn","Bất cứ giờ nào trong ngày","Chỉ vào cuối tuần"],"h1":"Lái xe ban đêm cần một người lớn ở ghế trước.","h2":"Ở Idaho, người có bằng lái dưới 16 tuổi chỉ được lái vào giờ ban ngày, từ 5 a.m. đến 10 p.m., trừ khi có người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Chính xác. Dưới 16 tuổi thì chỉ lái ban ngày."},"tl":{"q":"Sa Idaho, kailan puwedeng magmaneho nang mag-isa ang lisensyadong driver na wala pang 16?","o":["Sa oras ng araw (daylight hours) lang","Pagkalubog lang ng araw","Anumang oras, araw man o gabi","Tuwing weekend lang"],"h1":"Ang pagmamaneho sa gabi ay nangangailangan ng adult sa harapang upuan.","h2":"Sa Idaho, ang lisensyadong driver na wala pang 16 ay puwedeng magmaneho lang sa daylight hours, 5 a.m. hanggang 10 p.m., maliban kung may lisensyadong tao na 21 o higit pa sa harapang upuan.","p":"Tama. Kapag wala pang 16, sa araw lang."},"ar":{"q":"في Idaho، متى يُسمح لسائق مرخّص عمره أقل من 16 سنة أن يقود وحده؟","o":["في ساعات النهار فقط","بعد غروب الشمس فقط","في أي وقت من اليوم","في عطلة نهاية الأسبوع فقط"],"h1":"القيادة في الليل تحتاج إلى شخص بالغ في المقعد الأمامي.","h2":"في Idaho يُسمح للسائق المرخّص الذي عمره أقل من 16 سنة أن يقود في ساعات النهار فقط، من 5 a.m. إلى 10 p.m.، إلا إذا جلس في المقعد الأمامي شخص مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. أقل من 16 سنة يعني النهار فقط."},"ref":{"doc":"ID","page":16}},{"id":"id-011","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how are daylight hours defined for drivers under 16?","o":["From sunrise to sunset","From half an hour before sunrise to half an hour after sunset","From 6 a.m. to 6 p.m.","From 5 a.m. to 10 p.m."],"h1":"Idaho law sets clock times, not sunrise and sunset.","h2":"In Idaho, daylight hours for a licensed driver under 16 run from 5 a.m. to 10 p.m. local time.","p":"Right. Daylight hours are 5 a.m. to 10 p.m."},"es":{"q":"En Idaho, ¿cómo se definen las horas de luz del día para conductores menores de 16 años?","o":["Desde la salida hasta la puesta del sol","Desde media hora antes de la salida del sol hasta media hora después de la puesta del sol","De 6 a.m. a 6 p.m.","De 5 a.m. a 10 p.m."],"h1":"La ley de Idaho usa horas del reloj, no la salida y la puesta del sol.","h2":"En Idaho, las horas de luz del día para un conductor con licencia menor de 16 años van de 5 a.m. a 10 p.m., hora local.","p":"Correcto. Las horas de luz del día son de 5 a.m. a 10 p.m."},"zh":{"q":"在 Idaho，对 16 岁以下的司机来说，“白天时段”是怎样规定的？","o":["从日出到日落","从日出前半小时到日落后半小时","从早上 6 点到晚上 6 点","从早上 5 点到晚上 10 点"],"h1":"Idaho 法律规定的是钟点，不是日出和日落。","h2":"在 Idaho，16 岁以下、有驾照的司机的白天时段，是当地时间早上 5 点到晚上 10 点。","p":"对。白天时段是早上 5 点到晚上 10 点。"},"vi":{"q":"Ở Idaho, giờ ban ngày được tính thế nào cho người lái dưới 16 tuổi?","o":["Từ lúc mặt trời mọc đến lúc mặt trời lặn","Từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn","Từ 6 a.m. đến 6 p.m.","Từ 5 a.m. đến 10 p.m."],"h1":"Luật Idaho dùng giờ đồng hồ, không dùng lúc mặt trời mọc và lặn.","h2":"Ở Idaho, giờ ban ngày cho người có bằng lái dưới 16 tuổi là từ 5 a.m. đến 10 p.m. theo giờ địa phương.","p":"Đúng. Giờ ban ngày là từ 5 a.m. đến 10 p.m."},"tl":{"q":"Sa Idaho, paano itinatakda ang daylight hours para sa mga driver na wala pang 16?","o":["Mula pagsikat hanggang paglubog ng araw","Mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw","Mula 6 a.m. hanggang 6 p.m.","Mula 5 a.m. hanggang 10 p.m."],"h1":"Oras sa orasan ang itinatakda ng batas ng Idaho, hindi ang pagsikat at paglubog ng araw.","h2":"Sa Idaho, ang daylight hours para sa lisensyadong driver na wala pang 16 ay mula 5 a.m. hanggang 10 p.m. sa lokal na oras.","p":"Tama. Ang daylight hours ay 5 a.m. hanggang 10 p.m."},"ar":{"q":"في Idaho، كيف تُحدَّد ساعات النهار للسائقين الذين أعمارهم أقل من 16 سنة؟","o":["من شروق الشمس إلى غروبها","من نصف ساعة قبل الشروق إلى نصف ساعة بعد الغروب","من 6 a.m. إلى 6 p.m.","من 5 a.m. إلى 10 p.m."],"h1":"قانون Idaho يحدد ساعات على الساعة، لا شروق الشمس وغروبها.","h2":"في Idaho، ساعات النهار للسائق المرخّص الذي عمره أقل من 16 سنة هي من 5 a.m. إلى 10 p.m. بالتوقيت المحلي.","p":"صحيح. ساعات النهار من 5 a.m. إلى 10 p.m."},"ref":{"doc":"ID","page":16}},{"id":"id-012","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, during the first six months of a license, how many passengers under 17 may a driver under 17 carry?","o":["None","One","Two","Three"],"h1":"The limit is the smallest number that is more than zero.","h2":"During the first six months, an Idaho driver under 17 may carry no more than one passenger under 17, not counting relatives.","p":"Correct. Only one passenger under 17."},"es":{"q":"En Idaho, durante los primeros seis meses de la licencia, ¿cuántos pasajeros menores de 17 años puede llevar un conductor menor de 17?","o":["Ninguno","Uno","Dos","Tres"],"h1":"El límite es el número más pequeño que es mayor que cero.","h2":"Durante los primeros seis meses, un conductor menor de 17 años en Idaho no puede llevar más de un pasajero menor de 17, sin contar a sus familiares.","p":"Correcto. Solo un pasajero menor de 17."},"zh":{"q":"在 Idaho，拿到驾照的头六个月里，17 岁以下的司机可以载几个 17 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"这个限制是比零大的最小的数。","h2":"在头六个月里，Idaho 17 岁以下的司机最多只能载一个 17 岁以下的乘客，亲属不算在内。","p":"正确。只能载一个 17 岁以下的乘客。"},"vi":{"q":"Ở Idaho, trong sáu tháng đầu có bằng lái, người lái dưới 17 tuổi được chở bao nhiêu hành khách dưới 17 tuổi?","o":["Không ai","Một","Hai","Ba"],"h1":"Giới hạn là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu, người lái dưới 17 tuổi ở Idaho chỉ được chở tối đa một hành khách dưới 17 tuổi, không tính người thân.","p":"Chính xác. Chỉ một hành khách dưới 17 tuổi."},"tl":{"q":"Sa Idaho, sa unang anim na buwan ng lisensya, ilang pasaherong wala pang 17 ang puwedeng isakay ng driver na wala pang 17?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ang limitasyon ay ang pinakamaliit na numerong higit sa zero.","h2":"Sa unang anim na buwan, ang driver sa Idaho na wala pang 17 ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 17, hindi kasama ang mga kamag-anak.","p":"Tama. Isang pasahero lang na wala pang 17."},"ar":{"q":"في Idaho، خلال الأشهر الستة الأولى من الرخصة، كم راكبًا عمره أقل من 17 سنة يمكن أن ينقل السائق الذي عمره أقل من 17 سنة؟","o":["ولا واحد","واحد","اثنان","ثلاثة"],"h1":"الحد هو أصغر عدد أكبر من صفر.","h2":"خلال الأشهر الستة الأولى، لا يجوز للسائق في Idaho الذي عمره أقل من 17 سنة أن ينقل أكثر من راكب واحد عمره أقل من 17 سنة، دون حساب الأقارب.","p":"صحيح. راكب واحد فقط عمره أقل من 17 سنة."},"ref":{"doc":"ID","page":16}},{"id":"id-013","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, which passenger does not count toward the one-passenger limit for a new driver under 17?","o":["A classmate","A teammate","A neighbor","The driver's brother or sister"],"h1":"The rule makes an exception for family.","h2":"In Idaho the one-passenger limit does not apply to passengers related to the driver by blood, adoption or marriage, such as a brother or sister.","p":"Right. Family members do not count."},"es":{"q":"En Idaho, ¿qué pasajero no cuenta para el límite de un pasajero de un conductor nuevo menor de 17 años?","o":["Un compañero de clase","Un compañero de equipo","Un vecino","El hermano o la hermana del conductor"],"h1":"La regla hace una excepción para la familia.","h2":"En Idaho el límite de un pasajero no se aplica a los pasajeros que son familiares del conductor por sangre, adopción o matrimonio, como un hermano o una hermana.","p":"Correcto. Los familiares no cuentan."},"zh":{"q":"在 Idaho，对 17 岁以下的新司机来说，哪个乘客不算在一名乘客的限制里？","o":["同班同学","队友","邻居","司机的兄弟或姐妹"],"h1":"这个规定对家人有例外。","h2":"在 Idaho，一名乘客的限制不适用于和司机有血缘、收养或婚姻关系的乘客，例如兄弟或姐妹。","p":"对。家人不算。"},"vi":{"q":"Ở Idaho, hành khách nào không bị tính vào giới hạn một hành khách đối với người mới lái dưới 17 tuổi?","o":["Một bạn cùng lớp","Một đồng đội","Một người hàng xóm","Anh chị em của người lái"],"h1":"Luật có ngoại lệ cho gia đình.","h2":"Ở Idaho, giới hạn một hành khách không áp dụng cho hành khách là người thân của người lái theo huyết thống, nhận nuôi hoặc hôn nhân, chẳng hạn anh chị em.","p":"Đúng. Người trong gia đình không bị tính."},"tl":{"q":"Sa Idaho, aling pasahero ang hindi binibilang sa limitasyong isang pasahero para sa bagong driver na wala pang 17?","o":["Isang kaklase","Isang kasama sa team","Isang kapitbahay","Ang kapatid ng driver"],"h1":"May exception ang patakaran para sa pamilya.","h2":"Sa Idaho, ang limitasyong isang pasahero ay hindi para sa mga pasaherong kamag-anak ng driver sa dugo, pag-aampon o kasal, gaya ng kapatid.","p":"Tama. Hindi binibilang ang mga kapamilya."},"ar":{"q":"في Idaho، أيّ راكب لا يُحسب ضمن حد الراكب الواحد للسائق الجديد الذي عمره أقل من 17 سنة؟","o":["زميل في الصف","زميل في الفريق","جار","أخو السائق أو أخته"],"h1":"القاعدة فيها استثناء للعائلة.","h2":"في Idaho لا ينطبق حد الراكب الواحد على الركاب الأقارب للسائق بالدم أو التبنّي أو الزواج، مثل الأخ أو الأخت.","p":"صحيح. أفراد العائلة لا يُحسبون."},"ref":{"doc":"ID","page":16}},{"id":"id-014","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, who must complete a driver training program to get a driver's license?","o":["Everyone, at any age","Only drivers over 65","Anyone under 17","Only drivers from another state"],"h1":"It depends on how young the applicant is.","h2":"In Idaho anyone under 17 must complete and pass an approved driver training program to get a driver's license.","p":"Correct. Under 17 needs driver training."},"es":{"q":"En Idaho, ¿quién debe completar un programa de educación vial para obtener la licencia de manejo?","o":["Todos, a cualquier edad","Solo los mayores de 65","Cualquier persona menor de 17 años","Solo los conductores de otro estado"],"h1":"Depende de qué tan joven sea la persona.","h2":"En Idaho toda persona menor de 17 años debe completar y aprobar un programa de educación vial aprobado para obtener la licencia de manejo.","p":"Correcto. Menor de 17 necesita educación vial."},"zh":{"q":"在 Idaho，谁必须完成驾驶培训课程才能拿到驾照？","o":["所有人，不管几岁","只有 65 岁以上的司机","任何 17 岁以下的人","只有从别的州来的司机"],"h1":"这要看申请人有多年轻。","h2":"在 Idaho，任何 17 岁以下的人都必须完成并通过经过批准的驾驶培训课程，才能拿到驾照。","p":"正确。17 岁以下需要驾驶培训。"},"vi":{"q":"Ở Idaho, ai phải hoàn thành khóa đào tạo lái xe (driver training program) để có bằng lái?","o":["Mọi người, ở mọi lứa tuổi","Chỉ người lái trên 65 tuổi","Bất cứ ai dưới 17 tuổi","Chỉ người lái từ tiểu bang khác"],"h1":"Điều này tùy vào người nộp đơn trẻ đến mức nào.","h2":"Ở Idaho, bất cứ ai dưới 17 tuổi đều phải hoàn thành và đậu một khóa đào tạo lái xe được chấp thuận để có bằng lái.","p":"Chính xác. Dưới 17 tuổi cần học lái xe."},"tl":{"q":"Sa Idaho, sino ang dapat makatapos ng driver training program para makakuha ng driver's license?","o":["Lahat, anumang edad","Mga driver na higit sa 65 lang","Sinumang wala pang 17","Mga driver mula sa ibang estado lang"],"h1":"Depende ito sa kung gaano kabata ang aplikante.","h2":"Sa Idaho, sinumang wala pang 17 ay dapat makatapos at pumasa sa isang aprubadong driver training program para makakuha ng driver's license.","p":"Tama. Ang wala pang 17 ay kailangan ng driver training."},"ar":{"q":"في Idaho، مَن يجب أن يُكمل برنامج تدريب على القيادة (driver training program) للحصول على رخصة القيادة؟","o":["الجميع، في أي عمر","السائقون فوق 65 سنة فقط","أي شخص عمره أقل من 17 سنة","السائقون من ولاية أخرى فقط"],"h1":"الأمر يعتمد على صغر سنّ المتقدّم.","h2":"في Idaho يجب على كل مَن عمره أقل من 17 سنة أن يُكمل برنامج تدريب على القيادة معتمدًا وينجح فيه للحصول على رخصة القيادة.","p":"صحيح. مَن عمره أقل من 17 سنة يحتاج إلى تدريب على القيادة."},"ref":{"doc":"ID","page":19}},{"id":"id-015","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, how many hours of classroom instruction are in an approved driver training program?","o":["30 hours","6 hours","12 hours","50 hours"],"h1":"It is five times the hours of behind-the-wheel driving, which are 6.","h2":"An approved Idaho driver training program has 30 hours of classroom instruction, plus 6 hours of observation and 6 hours behind the wheel.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Idaho, ¿cuántas horas de clase en el aula tiene un programa de educación vial aprobado?","o":["30 horas","6 horas","12 horas","50 horas"],"h1":"Es cinco veces las horas de manejo con el instructor, que son 6.","h2":"Un programa de educación vial aprobado en Idaho tiene 30 horas de clase en el aula, además de 6 horas de observación y 6 horas al volante.","p":"Correcto. Treinta horas en el aula."},"zh":{"q":"在 Idaho，经过批准的驾驶培训课程有多少小时课堂教学？","o":["30 小时","6 小时","12 小时","50 小时"],"h1":"它是实际上车驾驶时间（6 小时）的五倍。","h2":"Idaho 经过批准的驾驶培训课程有 30 小时课堂教学，另外还有 6 小时观察和 6 小时实际驾驶。","p":"对。课堂里三十个小时。"},"vi":{"q":"Ở Idaho, một khóa đào tạo lái xe được chấp thuận có bao nhiêu giờ học trên lớp?","o":["30 giờ","6 giờ","12 giờ","50 giờ"],"h1":"Gấp năm lần số giờ lái thực tế, là 6 giờ.","h2":"Một khóa đào tạo lái xe được chấp thuận ở Idaho có 30 giờ học trên lớp, cộng thêm 6 giờ quan sát và 6 giờ lái thực tế.","p":"Đúng. Ba mươi giờ học trên lớp."},"tl":{"q":"Sa Idaho, ilang oras ng pag-aaral sa classroom ang nasa isang aprubadong driver training program?","o":["30 oras","6 na oras","12 oras","50 oras"],"h1":"Limang beses ito ng oras ng aktuwal na pagmamaneho, na 6.","h2":"Ang isang aprubadong driver training program sa Idaho ay may 30 oras ng pag-aaral sa classroom, dagdag ang 6 na oras ng pagmamasid at 6 na oras ng aktuwal na pagmamaneho.","p":"Tama. Tatlumpung oras sa classroom."},"ar":{"q":"في Idaho، كم ساعة من الدروس في الصف يتضمن برنامج التدريب على القيادة المعتمد؟","o":["30 ساعة","6 ساعات","12 ساعة","50 ساعة"],"h1":"هي خمسة أضعاف ساعات القيادة الفعلية خلف المقود، وهي 6.","h2":"برنامج التدريب على القيادة المعتمد في Idaho فيه 30 ساعة من الدروس في الصف، بالإضافة إلى 6 ساعات من المراقبة و6 ساعات من القيادة الفعلية خلف المقود.","p":"صحيح. ثلاثون ساعة في الصف."},"ref":{"doc":"ID","page":19}},{"id":"id-016","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when may a driver hold a phone in their hand to use it?","o":["While stopped at a red light","While stopped at a stop sign","When parked out of the travel lanes","While driving slowly"],"h1":"Being stopped in traffic is not enough.","h2":"Idaho's hands-free law covers you even at a red light or stop sign; you may hold the phone only when the vehicle is stopped outside the travel lanes, or in an emergency.","p":"Correct. Park out of traffic first."},"es":{"q":"En Idaho, ¿cuándo puede un conductor tener el teléfono en la mano para usarlo?","o":["Cuando está detenido en un semáforo en rojo","Cuando está detenido en una señal de alto","Cuando está estacionado fuera de los carriles de circulación","Cuando maneja despacio"],"h1":"Estar detenido en el tráfico no es suficiente.","h2":"La ley de manos libres de Idaho se aplica incluso en un semáforo en rojo o en una señal de alto; usted solo puede tener el teléfono en la mano cuando el vehículo está detenido fuera de los carriles de circulación, o en una emergencia.","p":"Correcto. Primero estaciónese fuera del tráfico."},"zh":{"q":"在 Idaho，司机什么时候可以手拿手机使用？","o":["在红灯前停着的时候","在停车标志前停着的时候","车停在行车道以外的时候","开得很慢的时候"],"h1":"在车流里停下来还不够。","h2":"Idaho 的免提法就算在红灯或停车标志前也适用；只有车停在行车道以外，或者有紧急情况时，你才可以手拿手机。","p":"正确。先把车停到车流以外。"},"vi":{"q":"Ở Idaho, khi nào người lái được cầm điện thoại trên tay để sử dụng?","o":["Khi dừng ở đèn đỏ","Khi dừng ở biển báo STOP","Khi đậu xe bên ngoài làn đường lưu thông","Khi đang lái chậm"],"h1":"Dừng lại giữa dòng xe thì chưa đủ.","h2":"Luật rảnh tay (hands-free law) của Idaho áp dụng cả khi bạn dừng ở đèn đỏ hoặc biển báo STOP; bạn chỉ được cầm điện thoại khi xe dừng bên ngoài làn đường lưu thông, hoặc trong trường hợp khẩn cấp.","p":"Chính xác. Hãy đậu xe ra khỏi dòng xe trước."},"tl":{"q":"Sa Idaho, kailan puwedeng hawakan ng driver ang telepono sa kamay para gamitin ito?","o":["Habang nakahinto sa pulang ilaw","Habang nakahinto sa stop sign","Kapag naka-park sa labas ng mga travel lane","Habang mabagal na nagmamaneho"],"h1":"Hindi sapat ang nakahinto sa trapiko.","h2":"Saklaw ka ng hands-free law ng Idaho kahit nasa pulang ilaw o stop sign; puwede mo lang hawakan ang telepono kapag nakahinto ang sasakyan sa labas ng mga travel lane, o sa emergency.","p":"Tama. Mag-park muna sa labas ng trapiko."},"ar":{"q":"في Idaho، متى يجوز للسائق أن يمسك الهاتف بيده لاستخدامه؟","o":["عند التوقف عند إشارة حمراء","عند التوقف عند علامة STOP","عند الوقوف خارج مسارات السير","أثناء القيادة ببطء"],"h1":"التوقف وسط حركة المرور لا يكفي.","h2":"قانون عدم استخدام اليدين (hands-free law) في Idaho يشملك حتى عند الإشارة الحمراء أو علامة STOP؛ يجوز لك أن تمسك الهاتف فقط عندما تكون السيارة متوقفة خارج مسارات السير، أو في حالة طارئة.","p":"صحيح. قِف خارج حركة المرور أولًا."},"ref":{"doc":"ID","page":null}},{"id":"id-017","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how may a driver start a phone call while driving?","o":["By typing the full number","With one touch or a voice command","By holding the phone to the ear","Calls are never allowed"],"h1":"The law allows the smallest possible action.","h2":"Idaho's hands-free law lets a driver start or answer a call with one touch or a voice command.","p":"Right. One touch or your voice."},"es":{"q":"En Idaho, ¿cómo puede un conductor hacer una llamada mientras maneja?","o":["Marcando el número completo","Con un solo toque o un comando de voz","Sosteniendo el teléfono junto al oído","Las llamadas nunca se permiten"],"h1":"La ley permite la acción más pequeña posible.","h2":"La ley de manos libres de Idaho permite hacer o contestar una llamada con un solo toque o con un comando de voz.","p":"Correcto. Un toque o su voz."},"zh":{"q":"在 Idaho，司机开车时可以怎样开始打电话？","o":["输入完整的号码","按一下或用语音命令","把手机拿到耳朵旁边","任何时候都不能打电话"],"h1":"法律只允许最小的动作。","h2":"Idaho 的免提法允许司机按一下或用语音命令来打电话或接电话。","p":"对。按一下或用你的声音。"},"vi":{"q":"Ở Idaho, người lái có thể bắt đầu cuộc gọi điện thoại khi đang lái xe bằng cách nào?","o":["Bằng cách bấm toàn bộ số điện thoại","Bằng một lần chạm hoặc lệnh giọng nói","Bằng cách cầm điện thoại áp vào tai","Không bao giờ được gọi điện"],"h1":"Luật cho phép thao tác nhỏ nhất có thể.","h2":"Luật rảnh tay của Idaho cho phép người lái bắt đầu hoặc trả lời cuộc gọi bằng một lần chạm hoặc lệnh giọng nói.","p":"Đúng. Một lần chạm hoặc giọng nói của bạn."},"tl":{"q":"Sa Idaho, paano puwedeng magsimula ng tawag ang driver habang nagmamaneho?","o":["Sa pag-type ng buong numero","Sa isang pindot o voice command","Sa paghawak ng telepono sa tainga","Hindi kailanman pinapayagan ang tawag"],"h1":"Pinapayagan ng batas ang pinakamaliit na posibleng kilos.","h2":"Pinapayagan ng hands-free law ng Idaho ang driver na magsimula o sumagot ng tawag sa isang pindot o voice command.","p":"Tama. Isang pindot o ang boses mo."},"ar":{"q":"في Idaho، كيف يمكن للسائق أن يبدأ مكالمة هاتفية أثناء القيادة؟","o":["بكتابة الرقم كاملًا","بلمسة واحدة أو بأمر صوتي","بإمساك الهاتف على الأذن","المكالمات غير مسموحة أبدًا"],"h1":"القانون يسمح بأصغر حركة ممكنة.","h2":"قانون عدم استخدام اليدين في Idaho يسمح للسائق أن يبدأ مكالمة أو يرد عليها بلمسة واحدة أو بأمر صوتي.","p":"صحيح. لمسة واحدة أو صوتك."},"ref":{"doc":"ID","page":null}},{"id":"id-018","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, what is the fine for a first hands-free law violation, before court costs?","o":["$75","$25","$300","$1,000"],"h1":"The fine doubles for a second offense, to $150.","h2":"A first violation of Idaho's hands-free law is a $75 fine, plus court costs.","p":"Correct. The first fine is $75."},"es":{"q":"En Idaho, ¿cuál es la multa por una primera infracción de la ley de manos libres, sin contar los costos del tribunal?","o":["$75","$25","$300","$1,000"],"h1":"La multa se duplica en la segunda infracción, a $150.","h2":"Una primera infracción de la ley de manos libres en Idaho tiene una multa de $75, más los costos del tribunal.","p":"Correcto. La primera multa es de $75."},"zh":{"q":"在 Idaho，第一次违反免提法，不算法庭费用，罚款多少？","o":["$75","$25","$300","$1,000"],"h1":"第二次违规时罚款加倍，变成 $150。","h2":"第一次违反 Idaho 的免提法，罚款 $75，另外还要付法庭费用。","p":"正确。第一次罚款是 $75。"},"vi":{"q":"Ở Idaho, tiền phạt cho lần đầu vi phạm luật rảnh tay là bao nhiêu, chưa tính án phí?","o":["$75","$25","$300","$1,000"],"h1":"Tiền phạt tăng gấp đôi ở lần vi phạm thứ hai, thành $150.","h2":"Lần đầu vi phạm luật rảnh tay của Idaho bị phạt $75, cộng thêm án phí.","p":"Chính xác. Tiền phạt lần đầu là $75."},"tl":{"q":"Sa Idaho, magkano ang multa sa unang paglabag sa hands-free law, bago ang court costs?","o":["$75","$25","$300","$1,000"],"h1":"Dumodoble ang multa sa ikalawang paglabag, hanggang $150.","h2":"Ang unang paglabag sa hands-free law ng Idaho ay may multang $75, dagdag ang court costs.","p":"Tama. Ang unang multa ay $75."},"ar":{"q":"في Idaho، ما غرامة المخالفة الأولى لقانون عدم استخدام اليدين، قبل رسوم المحكمة؟","o":["$75","$25","$300","$1,000"],"h1":"الغرامة تتضاعف في المخالفة الثانية، فتصبح $150.","h2":"المخالفة الأولى لقانون عدم استخدام اليدين في Idaho غرامتها $75، بالإضافة إلى رسوم المحكمة.","p":"صحيح. الغرامة الأولى $75."},"ref":{"doc":"ID","page":null}},{"id":"id-019","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, which stopped vehicle with flashing lights is covered by the Move Over law?","o":["Only police cars","Only ambulances","Only fire trucks","Tow trucks and highway incident response vehicles too"],"h1":"Since 2019 the law protects more than just emergency vehicles.","h2":"Idaho's Move Over law covers police and emergency vehicles, and since 2019 also tow trucks and highway incident response vehicles.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Idaho, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley Move Over?","o":["Solo los carros de policía","Solo las ambulancias","Solo los camiones de bomberos","También las grúas y los vehículos de respuesta a incidentes en la carretera"],"h1":"Desde 2019 la ley protege a más que solo los vehículos de emergencia.","h2":"La ley Move Over de Idaho cubre a la policía y los vehículos de emergencia, y desde 2019 también a las grúas y los vehículos de respuesta a incidentes en la carretera.","p":"Correcto. Las grúas también están cubiertas."},"zh":{"q":"在 Idaho，哪种停着、闪着灯的车辆受 Move Over 法保护？","o":["只有警车","只有救护车","只有消防车","也包括拖车和公路事故处理车辆"],"h1":"从 2019 年起，这条法律保护的不只是急救车辆。","h2":"Idaho 的 Move Over 法保护警车和急救车辆，从 2019 年起也保护拖车和公路事故处理车辆。","p":"对。拖车也受保护。"},"vi":{"q":"Ở Idaho, xe nào đang dừng và có đèn nhấp nháy được bảo vệ bởi luật Move Over (luật tránh sang làn khác)?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương","Chỉ xe cứu hỏa","Cả xe kéo và xe ứng phó sự cố trên xa lộ"],"h1":"Từ năm 2019, luật bảo vệ nhiều hơn chỉ xe khẩn cấp.","h2":"Luật Move Over của Idaho áp dụng cho xe cảnh sát và xe khẩn cấp, và từ năm 2019 cũng áp dụng cho xe kéo và xe ứng phó sự cố trên xa lộ.","p":"Đúng. Xe kéo cũng được bảo vệ."},"tl":{"q":"Sa Idaho, aling nakahintong sasakyan na may kumikislap na ilaw ang saklaw ng Move Over law?","o":["Mga sasakyan ng pulis lang","Mga ambulansya lang","Mga trak ng bumbero lang","Pati mga tow truck at highway incident response vehicle"],"h1":"Mula 2019, higit pa sa mga emergency vehicle ang pinoprotektahan ng batas.","h2":"Saklaw ng Move Over law ng Idaho ang mga sasakyan ng pulis at emergency vehicle, at mula 2019 pati ang mga tow truck at highway incident response vehicle.","p":"Tama. Saklaw din ang mga tow truck."},"ar":{"q":"في Idaho، أيّ مركبة متوقفة وأضواؤها تومض يشملها قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف فقط","سيارات الإطفاء فقط","شاحنات السحب ومركبات الاستجابة لحوادث الطرق السريعة أيضًا"],"h1":"منذ 2019 يحمي القانون أكثر من مركبات الطوارئ فقط.","h2":"قانون Move Over في Idaho يشمل سيارات الشرطة ومركبات الطوارئ، ومنذ 2019 يشمل أيضًا شاحنات السحب ومركبات الاستجابة لحوادث الطرق السريعة.","p":"صحيح. شاحنات السحب مشمولة أيضًا."},"ref":{"doc":"ID","page":95}},{"id":"id-020","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, what blood alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.02 or more","0.05 or more","0.10 or more"],"h1":"It is far lower than the adult limit of 0.08.","h2":"In Idaho a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Idaho, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.02 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Idaho un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 Idaho，对 21 岁以下的司机来说，血液酒精浓度多少是违法的？","o":["0.08 或更高","0.02 或更高","0.05 或更高","0.10 或更高"],"h1":"这比成年人的上限 0.08 低很多。","h2":"在 Idaho，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法。","p":"正确。21 岁以下的上限是 0.02。"},"vi":{"q":"Ở Idaho, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái dưới 21 tuổi?","o":["0.08 trở lên","0.02 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Idaho, người lái dưới 21 tuổi phạm luật khi có nồng độ cồn trong máu từ 0.02 trở lên.","p":"Chính xác. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa Idaho, anong blood alcohol level ang ilegal para sa driver na wala pang 21?","o":["0.08 o higit pa","0.02 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult na 0.08.","h2":"Sa Idaho, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02 o higit pa.","p":"Tama. Ang limitasyon para sa wala pang 21 ay 0.02."},"ar":{"q":"في Idaho، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.02 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Idaho يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد لمن عمره أقل من 21 سنة هو 0.02."},"ref":{"doc":"ID","page":131}},{"id":"id-021","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, a driver under 21 is convicted for the first time of driving with an alcohol level of 0.02 or more but under 0.08. How long does the court suspend the license?","o":["A warning only","30 days","One year","Two weeks"],"h1":"It is a long time, a full twelve months.","h2":"In Idaho a first conviction for a driver under 21 with an alcohol level from 0.02 to under 0.08 brings a one-year license suspension, and the first 90 days allow no driving at all.","p":"Right. The suspension is one year."},"es":{"q":"En Idaho, un conductor menor de 21 años es condenado por primera vez por manejar con un nivel de alcohol de 0.02 o más, pero menor de 0.08. ¿Por cuánto tiempo suspende la licencia el tribunal?","o":["Solo una advertencia","30 días","Un año","Dos semanas"],"h1":"Es mucho tiempo, doce meses completos.","h2":"En Idaho, una primera condena de un conductor menor de 21 años con un nivel de alcohol de 0.02 a menos de 0.08 trae una suspensión de licencia de un año, y en los primeros 90 días no puede manejar de ninguna manera.","p":"Correcto. La suspensión es de un año."},"zh":{"q":"在 Idaho，一个 21 岁以下的司机第一次被判酒精浓度在 0.02 或以上、但低于 0.08 时开车。法庭会暂停驾照多久？","o":["只是警告","30 天","一年","两个星期"],"h1":"这是很长的时间，整整十二个月。","h2":"在 Idaho，21 岁以下的司机第一次被判酒精浓度在 0.02 到 0.08 以下时开车，驾照会被暂停一年，而且前 90 天完全不能开车。","p":"对。暂停一年。"},"vi":{"q":"Ở Idaho, một người lái dưới 21 tuổi bị kết tội lần đầu vì lái xe với nồng độ cồn từ 0.02 trở lên nhưng dưới 0.08. Tòa án đình chỉ bằng lái bao lâu?","o":["Chỉ cảnh cáo","30 ngày","Một năm","Hai tuần"],"h1":"Đó là thời gian dài, trọn mười hai tháng.","h2":"Ở Idaho, lần đầu bị kết tội đối với người lái dưới 21 tuổi có nồng độ cồn từ 0.02 đến dưới 0.08 sẽ bị đình chỉ bằng lái một năm, và trong 90 ngày đầu hoàn toàn không được lái xe.","p":"Đúng. Thời gian đình chỉ là một năm."},"tl":{"q":"Sa Idaho, ang driver na wala pang 21 ay na-convict sa unang pagkakataon dahil nagmaneho na may alcohol level na 0.02 o higit pa pero mas mababa sa 0.08. Gaano katagal sususpendihin ng korte ang lisensya?","o":["Babala lang","30 araw","Isang taon","Dalawang linggo"],"h1":"Mahabang panahon ito, buong labindalawang buwan.","h2":"Sa Idaho, ang unang conviction para sa driver na wala pang 21 na may alcohol level mula 0.02 hanggang mas mababa sa 0.08 ay may isang taong suspensyon ng lisensya, at sa unang 90 araw ay bawal talagang magmaneho.","p":"Tama. Isang taon ang suspensyon."},"ar":{"q":"في Idaho، أُدين سائق عمره أقل من 21 سنة لأول مرة بالقيادة بنسبة كحول 0.02 أو أكثر لكن أقل من 0.08. كم مدة توقيف الرخصة التي تحكم بها المحكمة؟","o":["إنذار فقط","30 يومًا","سنة واحدة","أسبوعان"],"h1":"هي مدة طويلة، اثنا عشر شهرًا كاملة.","h2":"في Idaho تؤدي الإدانة الأولى لسائق عمره أقل من 21 سنة بنسبة كحول من 0.02 إلى أقل من 0.08 إلى توقيف الرخصة سنة واحدة، وفي أول 90 يومًا لا يُسمح بالقيادة أبدًا.","p":"صحيح. مدة التوقيف سنة واحدة."},"ref":{"doc":"ID","page":null}},{"id":"id-022","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when must you report a crash to the police?","o":["Only when someone is killed","Only when a car must be towed","When someone is hurt or damage is more than $1,500","Only when damage is more than $5,000"],"h1":"Think of both people and property. The dollar amount is fairly low.","h2":"In Idaho, you must report a crash to the police when someone is hurt or the property damage is more than $1,500.","p":"Right. Injury or more than $1,500 in damage means a police report."},"es":{"q":"En Idaho, ¿cuándo debe usted reportar un choque a la policía?","o":["Solo cuando alguien muere","Solo cuando hay que remolcar un carro","Cuando alguien sale herido o el daño es de más de $1,500","Solo cuando el daño es de más de $5,000"],"h1":"Piense en las personas y en los bienes. La cantidad de dinero es bastante baja.","h2":"En Idaho, usted debe reportar un choque a la policía cuando alguien sale herido o el daño a la propiedad es de más de $1,500.","p":"Correcto. Una lesión o un daño de más de $1,500 significa un reporte a la policía."},"zh":{"q":"在 Idaho，什么时候必须向警察报告车祸？","o":["只有在有人死亡时","只有在车子需要拖走时","有人受伤或损失超过 $1,500 时","只有在损失超过 $5,000 时"],"h1":"想一想人，也想一想财物。这个金额相当低。","h2":"在 Idaho，当有人受伤或财物损失超过 $1,500 时，你必须向警察报告车祸。","p":"对。有人受伤或损失超过 $1,500，就要向警察报告。"},"vi":{"q":"Ở Idaho, khi nào bạn phải báo cáo tai nạn cho cảnh sát?","o":["Chỉ khi có người chết","Chỉ khi phải kéo xe đi","Khi có người bị thương hoặc thiệt hại hơn $1,500","Chỉ khi thiệt hại hơn $5,000"],"h1":"Hãy nghĩ đến cả con người lẫn tài sản. Số tiền khá thấp.","h2":"Ở Idaho, bạn phải báo cáo tai nạn cho cảnh sát khi có người bị thương hoặc thiệt hại tài sản hơn $1,500.","p":"Đúng. Có người bị thương hoặc thiệt hại hơn $1,500 thì phải báo cảnh sát."},"tl":{"q":"Sa Idaho, kailan mo dapat i-report sa pulis ang isang banggaan?","o":["Kapag may namatay lang","Kapag kailangang i-tow ang sasakyan lang","Kapag may nasaktan o ang pinsala ay higit sa $1,500","Kapag ang pinsala ay higit sa $5,000 lang"],"h1":"Isipin ang mga tao at ang mga ari-arian. Medyo mababa ang halaga ng pera.","h2":"Sa Idaho, dapat mong i-report sa pulis ang banggaan kapag may nasaktan o ang pinsala sa ari-arian ay higit sa $1,500.","p":"Tama. Kapag may nasaktan o higit sa $1,500 ang pinsala, kailangan ng police report."},"ar":{"q":"في Idaho، متى يجب أن تبلّغ الشرطة عن حادث؟","o":["فقط عندما يموت شخص","فقط عندما يجب سحب السيارة","عندما يُصاب شخص أو يكون الضرر أكثر من $1,500","فقط عندما يكون الضرر أكثر من $5,000"],"h1":"فكّر في الناس وفي الممتلكات معًا. المبلغ منخفض نوعًا ما.","h2":"في Idaho، يجب أن تبلّغ الشرطة عن الحادث عندما يُصاب شخص أو يكون الضرر في الممتلكات أكثر من $1,500.","p":"صحيح. الإصابة أو الضرر الذي يزيد على $1,500 يعني تقريرًا للشرطة."},"ref":{"doc":"ID","page":121}},{"id":"id-023","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, you have a minor crash on an interstate and no one is hurt. What does the Quick Clearance law say to do with your car?","o":["Move it safely to the shoulder, median or emergency lane","Leave it exactly where it stopped until police arrive","Leave it in the lane with the hazard lights on","Drive away and call the police from home"],"h1":"The goal is to keep traffic moving and prevent a second crash.","h2":"In Idaho, if a crash on an interstate or major divided highway causes no injury or death, you must safely move your car to the shoulder, median or emergency lane.","p":"Right. Clear the lane when no one is hurt."},"es":{"q":"En Idaho, usted tiene un choque leve en una autopista interestatal y nadie sale herido. ¿Qué dice la ley Quick Clearance que debe hacer con su carro?","o":["Moverlo con cuidado al acotamiento, la mediana o el carril de emergencia","Dejarlo exactamente donde se detuvo hasta que llegue la policía","Dejarlo en el carril con las luces de emergencia encendidas","Irse y llamar a la policía desde su casa"],"h1":"El objetivo es que el tráfico siga avanzando y evitar otro choque.","h2":"En Idaho, si un choque en una autopista interestatal o una carretera dividida principal no causa heridos ni muertes, usted debe mover su carro con cuidado al acotamiento, la mediana o el carril de emergencia.","p":"Correcto. Despeje el carril cuando nadie está herido."},"zh":{"q":"在 Idaho，你在州际公路上发生了小车祸，没有人受伤。Quick Clearance 法律说你应该怎么处理你的车？","o":["安全地把车移到路肩、中央隔离带或紧急车道","在警察到来之前，把车留在停下的地方不动","打开危险警示灯，把车留在车道上","开车离开，回家后再打电话给警察"],"h1":"目的是让交通保持畅通，防止发生第二次车祸。","h2":"在 Idaho，如果在州际公路或主要分隔公路上发生的车祸没有造成受伤或死亡，你必须把车安全地移到路肩、中央隔离带或紧急车道。","p":"对。没有人受伤时，要把车道让出来。"},"vi":{"q":"Ở Idaho, bạn gặp một tai nạn nhỏ trên xa lộ liên bang và không ai bị thương. Luật Quick Clearance nói bạn phải làm gì với xe của mình?","o":["Di chuyển xe an toàn vào lề đường, dải phân cách hoặc làn khẩn cấp","Để xe đúng chỗ nó dừng cho đến khi cảnh sát đến","Để xe trong làn đường và bật đèn cảnh báo","Lái xe đi và gọi cảnh sát từ nhà"],"h1":"Mục đích là giữ cho xe cộ tiếp tục di chuyển và tránh tai nạn thứ hai.","h2":"Ở Idaho, nếu tai nạn trên xa lộ liên bang hoặc đường lớn có dải phân cách không làm ai bị thương hay chết, bạn phải di chuyển xe an toàn vào lề đường, dải phân cách hoặc làn khẩn cấp.","p":"Đúng. Khi không ai bị thương, hãy dọn xe khỏi làn đường."},"tl":{"q":"Sa Idaho, nagkaroon ka ng maliit na banggaan sa interstate at walang nasaktan. Ano ang sinasabi ng Quick Clearance law na gawin mo sa iyong kotse?","o":["Ilipat ito nang ligtas sa shoulder, median o emergency lane","Iwan ito kung saan mismo ito huminto hanggang dumating ang pulis","Iwan ito sa lane nang nakabukas ang hazard lights","Umalis at tawagan ang pulis mula sa bahay"],"h1":"Ang layunin ay panatilihing umaandar ang trapiko at maiwasan ang ikalawang banggaan.","h2":"Sa Idaho, kung ang banggaan sa interstate o malaking divided highway ay walang nasaktan o namatay, dapat mong ilipat nang ligtas ang iyong kotse sa shoulder, median o emergency lane.","p":"Tama. Alisin ang kotse sa lane kapag walang nasaktan."},"ar":{"q":"في Idaho، وقع لك حادث بسيط على طريق سريع بين الولايات ولم يُصب أحد. ماذا يقول قانون Quick Clearance أن تفعل بسيارتك؟","o":["انقلها بأمان إلى كتف الطريق أو الجزيرة الوسطى أو حارة الطوارئ","اتركها في مكانها تمامًا حتى تصل الشرطة","اتركها في الحارة مع تشغيل أضواء التحذير","ابتعد بالسيارة واتصل بالشرطة من البيت"],"h1":"الهدف هو أن تستمر حركة المرور وأن تمنع حادثًا ثانيًا.","h2":"في Idaho، إذا وقع حادث على طريق سريع بين الولايات أو طريق رئيسي مقسوم ولم يسبب إصابة أو وفاة، يجب أن تنقل سيارتك بأمان إلى كتف الطريق أو الجزيرة الوسطى أو حارة الطوارئ.","p":"صحيح. أخلِ الحارة عندما لا يُصاب أحد."},"ref":{"doc":"ID","page":121}},{"id":"id-024","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, what happens to a driver who gets 12 to 17 points in 12 months?","o":["Only a warning letter","A 6-month suspension","A 90-day suspension","A 30-day suspension"],"h1":"A warning letter comes at 8 points. This is the next step up.","h2":"In Idaho, a driver who gets 12 to 17 points in any 12 months has the license suspended for 30 days.","p":"Right. 12 to 17 points in a year means a 30-day suspension."},"es":{"q":"En Idaho, ¿qué le pasa a un conductor que acumula de 12 a 17 puntos en 12 meses?","o":["Solo una carta de advertencia","Una suspensión de 6 meses","Una suspensión de 90 días","Una suspensión de 30 días"],"h1":"La carta de advertencia llega con 8 puntos. Este es el siguiente paso.","h2":"En Idaho, a un conductor que acumula de 12 a 17 puntos en cualquier período de 12 meses le suspenden la licencia por 30 días.","p":"Correcto. De 12 a 17 puntos en un año significa una suspensión de 30 días."},"zh":{"q":"在 Idaho，司机在 12 个月内得到 12 到 17 分，会怎么样？","o":["只收到一封警告信","吊销驾照 6 个月","吊销驾照 90 天","吊销驾照 30 天"],"h1":"8 分时会收到警告信。这是下一步。","h2":"在 Idaho，司机在任何 12 个月内得到 12 到 17 分，驾照会被吊销 30 天。","p":"对。一年内 12 到 17 分，就是吊销驾照 30 天。"},"vi":{"q":"Ở Idaho, điều gì xảy ra với tài xế bị 12 đến 17 điểm trong 12 tháng?","o":["Chỉ nhận một thư cảnh cáo","Bị treo bằng 6 tháng","Bị treo bằng 90 ngày","Bị treo bằng 30 ngày"],"h1":"Thư cảnh cáo đến khi có 8 điểm. Đây là bước tiếp theo.","h2":"Ở Idaho, tài xế bị 12 đến 17 điểm trong bất kỳ 12 tháng nào sẽ bị treo bằng lái 30 ngày.","p":"Đúng. 12 đến 17 điểm trong một năm là bị treo bằng 30 ngày."},"tl":{"q":"Sa Idaho, ano ang mangyayari sa driver na nakakuha ng 12 hanggang 17 points sa loob ng 12 buwan?","o":["Isang warning letter lang","6 na buwang suspension","90 araw na suspension","30 araw na suspension"],"h1":"Ang warning letter ay dumarating sa 8 points. Ito ang susunod na hakbang.","h2":"Sa Idaho, ang driver na nakakuha ng 12 hanggang 17 points sa anumang 12 buwan ay masususpinde ang lisensya nang 30 araw.","p":"Tama. 12 hanggang 17 points sa isang taon ay 30 araw na suspension."},"ar":{"q":"في Idaho، ماذا يحدث للسائق الذي يحصل على 12 إلى 17 نقطة خلال 12 شهرًا؟","o":["رسالة تحذير فقط","إيقاف الرخصة 6 أشهر","إيقاف الرخصة 90 يومًا","إيقاف الرخصة 30 يومًا"],"h1":"رسالة التحذير تأتي عند 8 نقاط. هذه هي الخطوة التالية.","h2":"في Idaho، السائق الذي يحصل على 12 إلى 17 نقطة خلال أي 12 شهرًا تُوقف رخصته 30 يومًا.","p":"صحيح. من 12 إلى 17 نقطة في سنة تعني إيقاف الرخصة 30 يومًا."},"ref":{"doc":"ID","page":123}},{"id":"id-025","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, how many points can an approved defensive driving course remove from your record?","o":["All of them","Up to 3 points","Up to 6 points","None, it only lowers the fine"],"h1":"The course helps, but only a little.","h2":"In Idaho, finishing an approved defensive driving course can remove up to 3 points from your record, once every three years.","p":"Right. The course removes up to 3 points."},"es":{"q":"En Idaho, ¿cuántos puntos puede quitar de su historial un curso de manejo defensivo aprobado?","o":["Todos","Hasta 3 puntos","Hasta 6 puntos","Ninguno, solo baja la multa"],"h1":"El curso ayuda, pero solo un poco.","h2":"En Idaho, terminar un curso de manejo defensivo aprobado puede quitar hasta 3 puntos de su historial, una vez cada tres años.","p":"Correcto. El curso quita hasta 3 puntos."},"zh":{"q":"在 Idaho，完成认可的防御性驾驶课程可以从你的记录中去掉多少分？","o":["全部","最多 3 分","最多 6 分","一分也不能，只能减少罚款"],"h1":"这个课程有帮助，但只是一点点。","h2":"在 Idaho，完成认可的防御性驾驶课程可以从你的记录中去掉最多 3 分，每三年一次。","p":"对。这个课程最多去掉 3 分。"},"vi":{"q":"Ở Idaho, một khóa học lái xe phòng vệ được chấp thuận có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["Tất cả","Tối đa 3 điểm","Tối đa 6 điểm","Không điểm nào, nó chỉ giảm tiền phạt"],"h1":"Khóa học có giúp, nhưng chỉ một chút.","h2":"Ở Idaho, hoàn thành một khóa học lái xe phòng vệ được chấp thuận có thể xóa tối đa 3 điểm khỏi hồ sơ của bạn, ba năm một lần.","p":"Đúng. Khóa học xóa tối đa 3 điểm."},"tl":{"q":"Sa Idaho, ilang points ang maaaring alisin sa iyong record ng isang aprubadong defensive driving course?","o":["Lahat","Hanggang 3 points","Hanggang 6 points","Wala, binababa lang nito ang multa"],"h1":"Nakakatulong ang course, pero kaunti lang.","h2":"Sa Idaho, ang pagtatapos ng aprubadong defensive driving course ay maaaring mag-alis ng hanggang 3 points sa iyong record, isang beses bawat tatlong taon.","p":"Tama. Nag-aalis ang course ng hanggang 3 points."},"ar":{"q":"في Idaho، كم نقطة يمكن أن تحذفها دورة قيادة دفاعية معتمدة من سجلك؟","o":["كل النقاط","حتى 3 نقاط","حتى 6 نقاط","لا شيء، فهي تخفض الغرامة فقط"],"h1":"الدورة تساعد، لكن قليلًا فقط.","h2":"في Idaho، إتمام دورة قيادة دفاعية معتمدة يمكن أن يحذف حتى 3 نقاط من سجلك، مرة واحدة كل ثلاث سنوات.","p":"صحيح. الدورة تحذف حتى 3 نقاط."},"ref":{"doc":"ID","page":123}},{"id":"id-026","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, children up to what age must ride in an approved child safety seat?","o":["2 years or younger","4 years or younger","6 years or younger","10 years or younger"],"h1":"It covers children until they are about in first grade.","h2":"In Idaho, children 6 years old or younger must ride in an approved child safety seat.","p":"Right. Age 6 and under means a child safety seat."},"es":{"q":"En Idaho, ¿hasta qué edad los niños deben viajar en un asiento de seguridad infantil aprobado?","o":["2 años o menos","4 años o menos","6 años o menos","10 años o menos"],"h1":"Cubre a los niños hasta más o menos el primer grado.","h2":"En Idaho, los niños de 6 años o menos deben viajar en un asiento de seguridad infantil aprobado.","p":"Correcto. Los niños de 6 años o menos van en un asiento de seguridad."},"zh":{"q":"在 Idaho，多大以下的儿童必须坐在认可的儿童安全座椅里？","o":["2 岁或以下","4 岁或以下","6 岁或以下","10 岁或以下"],"h1":"大约到孩子上一年级的时候。","h2":"在 Idaho，6 岁或以下的儿童必须坐在认可的儿童安全座椅里。","p":"对。6 岁及以下要坐儿童安全座椅。"},"vi":{"q":"Ở Idaho, trẻ em đến bao nhiêu tuổi phải ngồi ghế an toàn trẻ em được chấp thuận?","o":["2 tuổi trở xuống","4 tuổi trở xuống","6 tuổi trở xuống","10 tuổi trở xuống"],"h1":"Luật áp dụng cho trẻ em đến khoảng lúc vào lớp một.","h2":"Ở Idaho, trẻ em 6 tuổi trở xuống phải ngồi ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Từ 6 tuổi trở xuống phải ngồi ghế an toàn trẻ em."},"tl":{"q":"Sa Idaho, hanggang anong edad dapat sumakay ang mga bata sa aprubadong child safety seat?","o":["2 taon o mas bata","4 na taon o mas bata","6 na taon o mas bata","10 taon o mas bata"],"h1":"Saklaw nito ang mga bata hanggang mga nasa unang baitang sila.","h2":"Sa Idaho, ang mga batang 6 na taon o mas bata ay dapat sumakay sa aprubadong child safety seat.","p":"Tama. Edad 6 pababa ay kailangan ng child safety seat."},"ar":{"q":"في Idaho، حتى أي عمر يجب أن يجلس الأطفال في مقعد أمان معتمد للأطفال؟","o":["سنتان أو أقل","4 سنوات أو أقل","6 سنوات أو أقل","10 سنوات أو أقل"],"h1":"يشمل الأطفال حتى يصلوا تقريبًا إلى الصف الأول.","h2":"في Idaho، يجب أن يجلس الأطفال الذين عمرهم 6 سنوات أو أقل في مقعد أمان معتمد للأطفال.","p":"صحيح. عمر 6 سنوات أو أقل يعني مقعد أمان للأطفال."},"ref":{"doc":"ID","page":41}},{"id":"id-027","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, when must you turn on your headlights during the day?","o":["When you can see only 500 feet or less ahead","Only after 6 p.m.","Only on the interstate","Only when it is snowing"],"h1":"It depends on how far you can see, not on the clock.","h2":"In Idaho, you must turn on your headlights in the daytime when you can see only 500 feet or less, such as in fog, smoke, dust or rain.","p":"Right. 500 feet or less means headlights on."},"es":{"q":"En Idaho, ¿cuándo debe encender los faros durante el día?","o":["Cuando solo puede ver 500 pies o menos hacia adelante","Solo después de las 6 p.m.","Solo en la autopista interestatal","Solo cuando está nevando"],"h1":"Depende de qué tan lejos puede ver, no de la hora.","h2":"En Idaho, usted debe encender los faros de día cuando solo puede ver 500 pies o menos, por ejemplo con niebla, humo, polvo o lluvia.","p":"Correcto. Con 500 pies o menos de visibilidad, encienda los faros."},"zh":{"q":"在 Idaho，白天什么时候必须打开前灯？","o":["当你只能看到前方 500 英尺或更近时","只在下午 6 点以后","只在州际公路上","只在下雪时"],"h1":"这要看你能看多远，不是看时间。","h2":"在 Idaho，白天当你只能看到 500 英尺或更近时，例如在雾、烟、灰尘或雨中，你必须打开前灯。","p":"对。只能看到 500 英尺或更近时，就要开前灯。"},"vi":{"q":"Ở Idaho, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi bạn chỉ nhìn thấy phía trước 500 feet hoặc ít hơn","Chỉ sau 6 giờ chiều","Chỉ trên xa lộ liên bang","Chỉ khi trời có tuyết"],"h1":"Điều này tùy vào việc bạn nhìn thấy xa bao nhiêu, không phải giờ giấc.","h2":"Ở Idaho, bạn phải bật đèn pha vào ban ngày khi bạn chỉ nhìn thấy 500 feet hoặc ít hơn, ví dụ khi có sương mù, khói, bụi hoặc mưa.","p":"Đúng. Nhìn thấy 500 feet hoặc ít hơn thì phải bật đèn pha."},"tl":{"q":"Sa Idaho, kailan mo dapat buksan ang headlights sa araw?","o":["Kapag 500 feet o mas malapit lang ang nakikita mo sa unahan","Pagkatapos lang ng 6 p.m.","Sa interstate lang","Kapag umuulan lang ng niyebe"],"h1":"Nakadepende ito sa kung gaano kalayo ang nakikita mo, hindi sa oras.","h2":"Sa Idaho, dapat mong buksan ang headlights sa araw kapag 500 feet o mas malapit lang ang nakikita mo, gaya ng sa hamog, usok, alikabok o ulan.","p":"Tama. 500 feet o mas malapit ay ibig sabihing bukas ang headlights."},"ar":{"q":"في Idaho، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["عندما لا ترى أمامك إلا 500 قدم أو أقل","فقط بعد الساعة 6 مساءً","فقط على الطريق السريع بين الولايات","فقط عندما يتساقط الثلج"],"h1":"الأمر يعتمد على المسافة التي تراها، لا على الساعة.","h2":"في Idaho، يجب أن تشغّل المصابيح الأمامية في النهار عندما لا ترى إلا 500 قدم أو أقل، مثل وقت الضباب أو الدخان أو الغبار أو المطر.","p":"صحيح. 500 قدم أو أقل تعني تشغيل المصابيح الأمامية."},"ref":{"doc":"ID","page":110}},{"id":"id-028","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what is the minimum vision needed to get a driver's license?","o":["20/20 in both eyes","20/30 in both eyes","20/40 in at least one eye","20/100 in at least one eye"],"h1":"Glasses or contact lenses may be used, and only one eye has to meet it.","h2":"In Idaho, you need at least 20/40 vision in at least one eye, with or without glasses or contact lenses.","p":"Right. The minimum is 20/40 in at least one eye."},"es":{"q":"En Idaho, ¿cuál es la visión mínima para obtener una licencia de conducir?","o":["20/20 en ambos ojos","20/30 en ambos ojos","20/40 en al menos un ojo","20/100 en al menos un ojo"],"h1":"Se pueden usar lentes o lentes de contacto, y solo un ojo tiene que cumplirlo.","h2":"En Idaho, necesita una visión de al menos 20/40 en al menos un ojo, con o sin lentes o lentes de contacto.","p":"Correcto. El mínimo es 20/40 en al menos un ojo."},"zh":{"q":"在 Idaho，考驾照最低需要什么视力？","o":["双眼都是 20/20","双眼都是 20/30","至少一只眼睛 20/40","至少一只眼睛 20/100"],"h1":"可以戴眼镜或隐形眼镜，只要一只眼睛达到要求就可以。","h2":"在 Idaho，你至少一只眼睛的视力需要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。最低要求是至少一只眼睛 20/40。"},"vi":{"q":"Ở Idaho, thị lực tối thiểu cần có để lấy bằng lái xe là bao nhiêu?","o":["20/20 ở cả hai mắt","20/30 ở cả hai mắt","20/40 ở ít nhất một mắt","20/100 ở ít nhất một mắt"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng, và chỉ cần một mắt đạt yêu cầu.","h2":"Ở Idaho, bạn cần thị lực ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính hay kính áp tròng.","p":"Đúng. Mức tối thiểu là 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa Idaho, ano ang pinakamababang paningin na kailangan para makakuha ng driver's license?","o":["20/20 sa dalawang mata","20/30 sa dalawang mata","20/40 sa kahit isang mata","20/100 sa kahit isang mata"],"h1":"Puwedeng gumamit ng salamin o contact lenses, at isang mata lang ang kailangang umabot dito.","h2":"Sa Idaho, kailangan mo ng hindi bababa sa 20/40 na paningin sa kahit isang mata, may salamin o contact lenses man o wala.","p":"Tama. Ang pinakamababa ay 20/40 sa kahit isang mata."},"ar":{"q":"في Idaho، ما أقل درجة نظر مطلوبة للحصول على رخصة القيادة؟","o":["20/20 في العينين كلتيهما","20/30 في العينين كلتيهما","20/40 في عين واحدة على الأقل","20/100 في عين واحدة على الأقل"],"h1":"يمكن استخدام النظارات أو العدسات اللاصقة، ويكفي أن تحقق عين واحدة الشرط.","h2":"في Idaho، تحتاج إلى نظر 20/40 على الأقل في عين واحدة على الأقل، بالنظارات أو العدسات اللاصقة أو بدونها.","p":"صحيح. الحد الأدنى هو 20/40 في عين واحدة على الأقل."},"ref":{"doc":"ID","page":32}},{"id":"id-029","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how close to a fire hydrant may you not park?","o":["Within 5 feet","Within 15 feet","Within 30 feet","Within 50 feet"],"h1":"Fire crews need room to reach the hydrant and connect a hose.","h2":"In Idaho, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En Idaho, ¿a qué distancia de un hidrante no puede estacionarse?","o":["A menos de 5 pies","A menos de 15 pies","A menos de 30 pies","A menos de 50 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante y conectar la manguera.","h2":"En Idaho, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante al estacionarse."},"zh":{"q":"在 Idaho，在离消防栓多近的地方不可以停车？","o":["5 英尺以内","15 英尺以内","30 英尺以内","50 英尺以内"],"h1":"消防员需要空间走到消防栓并接上水管。","h2":"在 Idaho，你不可以在离消防栓 15 英尺以内的地方停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Idaho, bạn không được đậu xe cách trụ nước chữa cháy gần bao nhiêu?","o":["Trong vòng 5 feet","Trong vòng 15 feet","Trong vòng 30 feet","Trong vòng 50 feet"],"h1":"Lính cứu hỏa cần chỗ để đến trụ nước và nối ống nước.","h2":"Ở Idaho, bạn không được đậu xe trong vòng 15 feet cách trụ nước chữa cháy.","p":"Đúng. Khi đậu xe, hãy cách trụ nước chữa cháy ít nhất 15 feet."},"tl":{"q":"Sa Idaho, gaano kalapit sa fire hydrant ka hindi puwedeng pumarada?","o":["Sa loob ng 5 feet","Sa loob ng 15 feet","Sa loob ng 30 feet","Sa loob ng 50 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para malapitan ang hydrant at maikabit ang hose.","h2":"Sa Idaho, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant kapag pumarada ka."},"ar":{"q":"في Idaho، ما المسافة من صنبور إطفاء الحريق التي لا يجوز أن تركن سيارتك ضمنها؟","o":["ضمن 5 أقدام","ضمن 15 قدمًا","ضمن 30 قدمًا","ضمن 50 قدمًا"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور وتوصيل الخرطوم.","h2":"في Idaho، لا يجوز أن تركن سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من صنبور إطفاء الحريق عندما تركن سيارتك."},"ref":{"doc":"ID","page":81}},{"id":"id-030","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a 35-year-old renews a regular Class D license. How long can the renewal last?","o":["Two or six years","Only one year","Only two years","Four or eight years"],"h1":"Drivers from 21 to 62 get to choose between two lengths.","h2":"In Idaho, a renewal lasts four or eight years, and drivers from 21 to 62 may choose the eight-year renewal.","p":"Right. A renewal lasts four or eight years."},"es":{"q":"En Idaho, una persona de 35 años renueva una licencia regular Clase D. ¿Cuánto tiempo puede durar la renovación?","o":["Dos o seis años","Solo un año","Solo dos años","Cuatro u ocho años"],"h1":"Los conductores de 21 a 62 años pueden elegir entre dos duraciones.","h2":"En Idaho, una renovación dura cuatro u ocho años, y los conductores de 21 a 62 años pueden elegir la renovación de ocho años.","p":"Correcto. Una renovación dura cuatro u ocho años."},"zh":{"q":"在 Idaho，一位 35 岁的人更新普通 Class D 驾照。更新后的驾照可以用多久？","o":["两年或六年","只有一年","只有两年","四年或八年"],"h1":"21 到 62 岁的司机可以在两种期限中选择。","h2":"在 Idaho，更新后的驾照有效期是四年或八年，21 到 62 岁的司机可以选择八年。","p":"对。更新后的驾照有效期是四年或八年。"},"vi":{"q":"Ở Idaho, một người 35 tuổi gia hạn bằng lái Class D thông thường. Bằng gia hạn có thể có hiệu lực bao lâu?","o":["Hai hoặc sáu năm","Chỉ một năm","Chỉ hai năm","Bốn hoặc tám năm"],"h1":"Tài xế từ 21 đến 62 tuổi được chọn giữa hai thời hạn.","h2":"Ở Idaho, bằng gia hạn có hiệu lực bốn hoặc tám năm, và tài xế từ 21 đến 62 tuổi có thể chọn gia hạn tám năm.","p":"Đúng. Bằng gia hạn có hiệu lực bốn hoặc tám năm."},"tl":{"q":"Sa Idaho, nagre-renew ng regular na Class D license ang isang 35 taong gulang. Gaano katagal puwedeng tumagal ang renewal?","o":["Dalawa o anim na taon","Isang taon lang","Dalawang taon lang","Apat o walong taon"],"h1":"Ang mga driver na 21 hanggang 62 taong gulang ay puwedeng pumili sa pagitan ng dalawang haba.","h2":"Sa Idaho, ang renewal ay tumatagal nang apat o walong taon, at ang mga driver na 21 hanggang 62 taong gulang ay puwedeng pumili ng walong taong renewal.","p":"Tama. Ang renewal ay tumatagal nang apat o walong taon."},"ar":{"q":"في Idaho، شخص عمره 35 عامًا يجدّد رخصة قيادة عادية من فئة Class D. كم يمكن أن تدوم الرخصة بعد التجديد؟","o":["سنتين أو ست سنوات","سنة واحدة فقط","سنتين فقط","أربع سنوات أو ثماني سنوات"],"h1":"السائقون من عمر 21 إلى 62 يمكنهم الاختيار بين مدتين.","h2":"في Idaho، يدوم التجديد أربع سنوات أو ثماني سنوات، ويمكن للسائقين من عمر 21 إلى 62 اختيار التجديد لثماني سنوات.","p":"صحيح. يدوم التجديد أربع سنوات أو ثماني سنوات."},"ref":{"doc":"ID","page":30}},{"id":"id-031","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, you are taking an opened bottle of wine home in your car. Where must it be?","o":["In the trunk, or behind the last upright seat if there is no trunk","On the floor behind the driver's seat","In the glove box with the door closed","On the front seat, if the cork is pushed back in"],"h1":"It must be in a place no one in the seats can reach.","h2":"In Idaho, an open container of alcohol must be carried in the trunk, or behind the last upright seat if the vehicle has no trunk.","p":"Right. An open container goes in the trunk, or behind the last upright seat."},"es":{"q":"En Idaho, usted lleva a casa una botella de vino abierta en su auto. ¿Dónde debe ir?","o":["En la cajuela, o detrás del último asiento vertical si no hay cajuela","En el piso detrás del asiento del conductor","En la guantera con la puerta cerrada","En el asiento delantero, si se vuelve a poner el corcho"],"h1":"Debe ir en un lugar que nadie en los asientos pueda alcanzar.","h2":"En Idaho, un envase abierto de alcohol debe ir en la cajuela, o detrás del último asiento vertical si el vehículo no tiene cajuela.","p":"Correcto. Un envase abierto va en la cajuela, o detrás del último asiento vertical."},"zh":{"q":"在 Idaho，你开车把一瓶已经打开的葡萄酒带回家。它必须放在哪里？","o":["放在后备箱里；如果没有后备箱，就放在最后一排直立座椅的后面","放在驾驶座后面的地板上","放在手套箱里，并关上箱门","放在前座上，只要把软木塞塞回去"],"h1":"它必须放在座位上的人都拿不到的地方。","h2":"在 Idaho，打开的酒精饮料容器必须放在后备箱里；如果车辆没有后备箱，就必须放在最后一排直立座椅的后面。","p":"对。打开的酒要放在后备箱里，或放在最后一排直立座椅的后面。"},"vi":{"q":"Ở Idaho, bạn đang chở một chai rượu vang đã mở về nhà trong xe. Chai rượu phải được để ở đâu?","o":["Trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng nếu xe không có cốp","Trên sàn xe phía sau ghế tài xế","Trong hộc đựng găng tay với nắp đóng lại","Trên ghế trước, nếu nút chai đã được đẩy lại vào"],"h1":"Nó phải ở chỗ mà không ai ngồi trên ghế có thể với tới.","h2":"Ở Idaho, đồ uống có cồn đã mở phải được để trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng nếu xe không có cốp.","p":"Đúng. Đồ uống có cồn đã mở phải để trong cốp xe, hoặc phía sau hàng ghế dựng thẳng cuối cùng."},"tl":{"q":"Sa Idaho, nag-uuwi ka ng bukas na bote ng alak sa iyong kotse. Saan ito dapat nakalagay?","o":["Sa trunk, o sa likod ng huling nakatayong upuan kung walang trunk","Sa sahig sa likod ng upuan ng driver","Sa glove box na nakasara ang pinto","Sa upuan sa harap, kung naibalik na ang tapon"],"h1":"Dapat itong nasa lugar na hindi maaabot ng sinumang nakaupo.","h2":"Sa Idaho, ang bukas na lalagyan ng alak ay dapat dalhin sa trunk, o sa likod ng huling nakatayong upuan kung walang trunk ang sasakyan.","p":"Tama. Ang bukas na alak ay inilalagay sa trunk, o sa likod ng huling nakatayong upuan."},"ar":{"q":"في Idaho، أنت تنقل إلى البيت في سيارتك زجاجة نبيذ مفتوحة. أين يجب أن تكون؟","o":["في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم إذا لم يكن هناك صندوق","على الأرض خلف مقعد السائق","في درج القفازات وبابه مغلق","على المقعد الأمامي، إذا أعيدت السدادة إلى مكانها"],"h1":"يجب أن تكون في مكان لا يستطيع أي شخص جالس في المقاعد الوصول إليه.","h2":"في Idaho، يجب نقل وعاء الكحول المفتوح في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم إذا لم يكن للسيارة صندوق.","p":"صحيح. الوعاء المفتوح يوضع في صندوق السيارة الخلفي، أو خلف آخر مقعد قائم."},"ref":{"doc":"ID","page":130}},{"id":"id-032","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, you fail the knowledge test. How long must you wait before you can take it again?","o":["You can retake it the same day","Three days","Two weeks","30 days"],"h1":"The wait is short, less than one week.","h2":"In Idaho, after failing the knowledge test you must wait three days to retest, and you pay the test fee again.","p":"Right. You wait three days and pay the fee again."},"es":{"q":"En Idaho, usted no aprueba el examen de conocimientos. ¿Cuánto debe esperar para volver a tomarlo?","o":["Puede repetirlo el mismo día","Tres días","Dos semanas","30 días"],"h1":"La espera es corta, menos de una semana.","h2":"En Idaho, si no aprueba el examen de conocimientos, debe esperar tres días para repetirlo y pagar otra vez la tarifa.","p":"Correcto. Espera tres días y paga la tarifa otra vez."},"zh":{"q":"在 Idaho，你没有通过笔试。要等多久才能再考？","o":["当天就可以重考","三天","两个星期","30 天"],"h1":"等的时间很短，不到一个星期。","h2":"在 Idaho，笔试没通过后，你必须等三天才能重考，而且要再付一次考试费。","p":"对。你要等三天，并再付一次费用。"},"vi":{"q":"Ở Idaho, bạn thi trượt bài thi kiến thức. Bạn phải chờ bao lâu mới được thi lại?","o":["Bạn có thể thi lại ngay trong ngày","Ba ngày","Hai tuần","30 ngày"],"h1":"Thời gian chờ ngắn, ít hơn một tuần.","h2":"Ở Idaho, sau khi thi trượt bài thi kiến thức, bạn phải chờ ba ngày mới được thi lại, và phải trả lệ phí thi một lần nữa.","p":"Đúng. Bạn chờ ba ngày và trả lệ phí lại."},"tl":{"q":"Sa Idaho, bumagsak ka sa knowledge test. Gaano katagal ka dapat maghintay bago ka makakuha ulit?","o":["Puwede kang kumuha ulit sa parehong araw","Tatlong araw","Dalawang linggo","30 araw"],"h1":"Maikli ang paghihintay, wala pang isang linggo.","h2":"Sa Idaho, pagkatapos bumagsak sa knowledge test, dapat kang maghintay ng tatlong araw bago kumuha ulit, at babayaran mo ulit ang test fee.","p":"Tama. Maghihintay ka ng tatlong araw at magbabayad ulit ng fee."},"ar":{"q":"في Idaho، رسبت في اختبار المعرفة. كم يجب أن تنتظر قبل أن تعيده؟","o":["يمكنك أن تعيده في اليوم نفسه","ثلاثة أيام","أسبوعان","30 يومًا"],"h1":"الانتظار قصير، أقل من أسبوع.","h2":"في Idaho، بعد الرسوب في اختبار المعرفة يجب أن تنتظر ثلاثة أيام لتعيد الاختبار، وتدفع رسوم الاختبار مرة أخرى.","p":"صحيح. تنتظر ثلاثة أيام وتدفع الرسوم مرة أخرى."},"ref":{"doc":"ID","page":32}},{"id":"id-033","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, you just moved to the state with a valid license from another state. How soon must you apply for an Idaho license?","o":["Within 7 days","Within 90 days","Only when your old license expires","Within 30 days"],"h1":"It is about one month.","h2":"New Idaho residents must apply for an Idaho driver's license within 30 days, even if the old license has not expired.","p":"Right. New residents have 30 days."},"es":{"q":"En Idaho, usted acaba de mudarse al estado con una licencia válida de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Idaho?","o":["Dentro de 7 días","Dentro de 90 días","Solo cuando venza su licencia anterior","Dentro de 30 días"],"h1":"Es más o menos un mes.","h2":"Los nuevos residentes de Idaho deben solicitar una licencia de Idaho dentro de 30 días, aunque su licencia anterior no haya vencido.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Idaho，你刚搬到这个州，持有另一个州的有效驾照。你必须多快申请 Idaho 驾照？","o":["7 天内","90 天内","只有在旧驾照过期时","30 天内"],"h1":"大约一个月。","h2":"新搬到 Idaho 的居民必须在 30 天内申请 Idaho 驾照，即使旧驾照还没过期。","p":"对。新居民有 30 天时间。"},"vi":{"q":"Ở Idaho, bạn vừa chuyển đến tiểu bang với bằng lái còn hạn của một tiểu bang khác. Bạn phải xin bằng lái Idaho trong bao lâu?","o":["Trong vòng 7 ngày","Trong vòng 90 ngày","Chỉ khi bằng lái cũ hết hạn","Trong vòng 30 ngày"],"h1":"Khoảng một tháng.","h2":"Cư dân mới của Idaho phải xin bằng lái Idaho trong vòng 30 ngày, ngay cả khi bằng lái cũ chưa hết hạn.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa Idaho, kalilipat mo lang sa state na may valid na lisensya mula sa ibang state. Gaano kabilis ka dapat mag-apply ng lisensya ng Idaho?","o":["Sa loob ng 7 araw","Sa loob ng 90 araw","Kapag nag-expire lang ang luma mong lisensya","Sa loob ng 30 araw"],"h1":"Mga isang buwan ito.","h2":"Ang mga bagong residente ng Idaho ay dapat mag-apply ng driver's license ng Idaho sa loob ng 30 araw, kahit hindi pa expired ang lumang lisensya.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Idaho، انتقلت للتو إلى الولاية ومعك رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن تطلب رخصة Idaho؟","o":["خلال 7 أيام","خلال 90 يومًا","فقط عندما تنتهي رخصتك القديمة","خلال 30 يومًا"],"h1":"المدة حوالي شهر واحد.","h2":"يجب على السكان الجدد في Idaho أن يطلبوا رخصة قيادة من Idaho خلال 30 يومًا، حتى لو لم تنتهِ الرخصة القديمة.","p":"صحيح. لدى السكان الجدد 30 يومًا."},"ref":{"doc":"ID","page":4}},{"id":"id-034","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a 17-year-old practices with a Class D Instruction Permit. How old must the licensed driver with them be?","o":["At least 18","At least 16","At least 25","At least 30"],"h1":"The person must be an adult.","h2":"With a Class D Instruction Permit, the learner must drive with a licensed adult who is at least 18 years old.","p":"Right. The licensed driver must be at least 18."},"es":{"q":"En Idaho, un joven de 17 años practica con un permiso de instrucción Clase D. ¿Qué edad debe tener el conductor con licencia que lo acompaña?","o":["Al menos 18 años","Al menos 16 años","Al menos 25 años","Al menos 30 años"],"h1":"La persona debe ser adulta.","h2":"Con un permiso de instrucción Clase D, el aprendiz debe manejar con un adulto con licencia que tenga al menos 18 años.","p":"Correcto. El conductor con licencia debe tener al menos 18 años."},"zh":{"q":"在 Idaho，一个 17 岁的人用 Class D Instruction Permit 练车。陪同的持照司机至少要几岁？","o":["至少 18 岁","至少 16 岁","至少 25 岁","至少 30 岁"],"h1":"这个人必须是成年人。","h2":"持 Class D Instruction Permit 时，学车的人必须和一位至少 18 岁的持照成年人一起开车。","p":"对。持照司机必须至少 18 岁。"},"vi":{"q":"Ở Idaho, một người 17 tuổi tập lái với Class D Instruction Permit. Người lái có bằng đi cùng phải ít nhất bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 16 tuổi","Ít nhất 25 tuổi","Ít nhất 30 tuổi"],"h1":"Người đó phải là người lớn.","h2":"Với Class D Instruction Permit, người học lái phải lái cùng một người lớn có bằng lái và ít nhất 18 tuổi.","p":"Đúng. Người lái có bằng phải ít nhất 18 tuổi."},"tl":{"q":"Sa Idaho, isang 17 taong gulang ang nagpa-practice gamit ang Class D Instruction Permit. Ilang taon dapat ang lisensyadong driver na kasama niya?","o":["Hindi bababa sa 18","Hindi bababa sa 16","Hindi bababa sa 25","Hindi bababa sa 30"],"h1":"Dapat adult ang taong ito.","h2":"Sa Class D Instruction Permit, ang nag-aaral ay dapat magmaneho kasama ang isang lisensyadong adult na hindi bababa sa 18 taong gulang.","p":"Tama. Ang lisensyadong driver ay dapat hindi bababa sa 18."},"ar":{"q":"في Idaho، شخص عمره 17 سنة يتدرّب بتصريح Class D Instruction Permit. كم يجب أن يكون عمر السائق المرخَّص الذي معه؟","o":["18 سنة على الأقل","16 سنة على الأقل","25 سنة على الأقل","30 سنة على الأقل"],"h1":"يجب أن يكون هذا الشخص بالغًا.","h2":"مع تصريح Class D Instruction Permit، يجب أن يقود المتعلّم مع شخص بالغ مرخَّص عمره 18 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر السائق المرخَّص 18 سنة على الأقل."},"ref":{"doc":"ID","page":16}},{"id":"id-035","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, a driver is 19 years old. When does their driver's license expire?","o":["On their 20th birthday","Ten years after it was issued","Five days after their 21st birthday","On their 25th birthday"],"h1":"Look for the license that says \"Under 21.\"","h2":"In Idaho, a license for a driver aged 18 to 20 says \"Under 21\" and expires five days after the 21st birthday.","p":"Right. It expires five days after the 21st birthday."},"es":{"q":"En Idaho, un conductor tiene 19 años. ¿Cuándo vence su licencia de manejo?","o":["En su cumpleaños número 20","Diez años después de emitirse","Cinco días después de cumplir 21 años","En su cumpleaños número 25"],"h1":"Piense en la licencia que dice \"Under 21\" (menor de 21).","h2":"En Idaho, la licencia de un conductor de 18 a 20 años dice \"Under 21\" y vence cinco días después de cumplir 21 años.","p":"Correcto. Vence cinco días después de cumplir 21 años."},"zh":{"q":"在 Idaho，一位司机 19 岁。他的驾照什么时候过期？","o":["在他 20 岁生日那天","发照十年后","在他 21 岁生日后五天","在他 25 岁生日那天"],"h1":"看那张写着 \"Under 21\" 的驾照。","h2":"在 Idaho，18 到 20 岁司机的驾照上写着 \"Under 21\"，会在 21 岁生日后五天过期。","p":"对。驾照在 21 岁生日后五天过期。"},"vi":{"q":"Ở Idaho, một người lái 19 tuổi. Khi nào bằng lái của người đó hết hạn?","o":["Vào sinh nhật lần thứ 20","Mười năm sau khi được cấp","Năm ngày sau sinh nhật lần thứ 21","Vào sinh nhật lần thứ 25"],"h1":"Hãy tìm bằng lái có ghi \"Under 21.\"","h2":"Ở Idaho, bằng lái của người từ 18 đến 20 tuổi có ghi \"Under 21\" và hết hạn năm ngày sau sinh nhật lần thứ 21.","p":"Đúng. Bằng lái hết hạn năm ngày sau sinh nhật lần thứ 21."},"tl":{"q":"Sa Idaho, 19 taong gulang ang isang driver. Kailan mag-e-expire ang kanyang driver's license?","o":["Sa kanyang ika-20 kaarawan","Sampung taon matapos itong ibigay","Limang araw matapos ang kanyang ika-21 kaarawan","Sa kanyang ika-25 kaarawan"],"h1":"Hanapin ang lisensyang may nakasulat na \"Under 21.\"","h2":"Sa Idaho, ang lisensya ng driver na 18 hanggang 20 taong gulang ay may nakasulat na \"Under 21\" at mag-e-expire limang araw matapos ang ika-21 kaarawan.","p":"Tama. Mag-e-expire ito limang araw matapos ang ika-21 kaarawan."},"ar":{"q":"في Idaho، عمر سائق 19 سنة. متى تنتهي رخصة قيادته؟","o":["في عيد ميلاده العشرين","بعد عشر سنوات من إصدارها","بعد خمسة أيام من عيد ميلاده الحادي والعشرين","في عيد ميلاده الخامس والعشرين"],"h1":"ابحث عن الرخصة المكتوب عليها \"Under 21\".","h2":"في Idaho، رخصة السائق الذي عمره من 18 إلى 20 سنة مكتوب عليها \"Under 21\"، وتنتهي بعد خمسة أيام من عيد الميلاد الحادي والعشرين.","p":"صحيح. تنتهي بعد خمسة أيام من عيد الميلاد الحادي والعشرين."},"ref":{"doc":"ID","page":17}},{"id":"id-036","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, you will be out of state for a while when your license expires. How long can one extension last?","o":["Up to 30 days","Up to 3 months","Up to 5 years","Up to 12 months"],"h1":"Think of one full year.","h2":"An Idaho driver who is temporarily out of state can get an extension of up to 12 months for a $10 fee.","p":"Right. One extension lasts up to 12 months."},"es":{"q":"En Idaho, usted estará fuera del estado cuando venza su licencia. ¿Cuánto puede durar una prórroga?","o":["Hasta 30 días","Hasta 3 meses","Hasta 5 años","Hasta 12 meses"],"h1":"Piense en un año completo.","h2":"Un conductor de Idaho que está fuera del estado por un tiempo puede obtener una prórroga de hasta 12 meses por una tarifa de $10.","p":"Correcto. Una prórroga dura hasta 12 meses."},"zh":{"q":"在 Idaho，你的驾照到期时你会在州外待一段时间。一次延期最长可以多久？","o":["最多 30 天","最多 3 个月","最多 5 年","最多 12 个月"],"h1":"想想一整年。","h2":"暂时在州外的 Idaho 司机可以付 $10 的费用，得到最长 12 个月的延期。","p":"对。一次延期最长 12 个月。"},"vi":{"q":"Ở Idaho, bạn sẽ ở ngoài tiểu bang một thời gian khi bằng lái hết hạn. Một lần gia hạn có thể kéo dài bao lâu?","o":["Tối đa 30 ngày","Tối đa 3 tháng","Tối đa 5 năm","Tối đa 12 tháng"],"h1":"Hãy nghĩ đến trọn một năm.","h2":"Người lái ở Idaho tạm thời ở ngoài tiểu bang có thể được gia hạn tối đa 12 tháng với lệ phí $10.","p":"Đúng. Một lần gia hạn kéo dài tối đa 12 tháng."},"tl":{"q":"Sa Idaho, nasa labas ka ng state nang ilang panahon kapag nag-expire ang lisensya mo. Gaano katagal ang isang extension?","o":["Hanggang 30 araw","Hanggang 3 buwan","Hanggang 5 taon","Hanggang 12 buwan"],"h1":"Isipin ang isang buong taon.","h2":"Ang driver ng Idaho na pansamantalang nasa labas ng state ay puwedeng makakuha ng extension na hanggang 12 buwan sa bayad na $10.","p":"Tama. Hanggang 12 buwan ang isang extension."},"ar":{"q":"في Idaho، ستكون خارج الولاية لفترة عندما تنتهي رخصتك. كم يمكن أن يستمر التمديد الواحد؟","o":["حتى 30 يومًا","حتى 3 أشهر","حتى 5 سنوات","حتى 12 شهرًا"],"h1":"فكّر في سنة كاملة.","h2":"السائق في Idaho الموجود خارج الولاية مؤقتًا يمكنه أن يحصل على تمديد حتى 12 شهرًا مقابل رسوم $10.","p":"صحيح. التمديد الواحد يستمر حتى 12 شهرًا."},"ref":{"doc":"ID","page":31}},{"id":"id-037","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a licensed driver under 17 is convicted of a second moving violation. What happens?","o":["A warning letter","A 30-day suspension","A one-year suspension","A $50 fine and nothing more"],"h1":"The first conviction brings only a warning letter. The second is stronger.","h2":"Under Idaho's graduated license rules, a driver under 17 gets a 30-day suspension for a second moving violation conviction.","p":"Right. A second conviction means a 30-day suspension."},"es":{"q":"En Idaho, un conductor con licencia menor de 17 años recibe una segunda condena por una infracción de tránsito en movimiento. ¿Qué pasa?","o":["Una carta de advertencia","Una suspensión de 30 días","Una suspensión de un año","Una multa de $50 y nada más"],"h1":"La primera condena trae solo una carta de advertencia. La segunda es más fuerte.","h2":"Según las reglas de licencia gradual de Idaho, un conductor menor de 17 años recibe una suspensión de 30 días por una segunda condena por infracción en movimiento.","p":"Correcto. Una segunda condena significa una suspensión de 30 días."},"zh":{"q":"在 Idaho，一个 17 岁以下的持照司机第二次被判行车违规。会怎么样？","o":["一封警告信","暂停驾照 30 天","暂停驾照一年","罚款 $50，没有别的"],"h1":"第一次被判只会收到警告信。第二次更严重。","h2":"按照 Idaho 的分级驾照规定，17 岁以下的司机第二次被判行车违规，驾照会被暂停 30 天。","p":"对。第二次被判就是暂停 30 天。"},"vi":{"q":"Ở Idaho, một người lái có bằng dưới 17 tuổi bị kết tội vi phạm giao thông khi lái xe lần thứ hai. Điều gì xảy ra?","o":["Một thư cảnh cáo","Đình chỉ bằng lái 30 ngày","Đình chỉ bằng lái một năm","Phạt $50 và không gì khác"],"h1":"Lần bị kết tội đầu tiên chỉ bị thư cảnh cáo. Lần thứ hai nặng hơn.","h2":"Theo luật bằng lái theo cấp của Idaho, người lái dưới 17 tuổi bị đình chỉ bằng lái 30 ngày khi bị kết tội vi phạm giao thông lần thứ hai.","p":"Đúng. Lần bị kết tội thứ hai nghĩa là đình chỉ 30 ngày."},"tl":{"q":"Sa Idaho, ang isang lisensyadong driver na wala pang 17 ay na-convict sa ikalawang moving violation. Ano ang mangyayari?","o":["Isang warning letter","30 araw na suspensyon","Isang taong suspensyon","$50 na multa at wala nang iba"],"h1":"Ang unang conviction ay warning letter lang. Mas mabigat ang ikalawa.","h2":"Ayon sa graduated license rules ng Idaho, ang driver na wala pang 17 ay may 30 araw na suspensyon para sa ikalawang conviction sa moving violation.","p":"Tama. Ang ikalawang conviction ay 30 araw na suspensyon."},"ar":{"q":"في Idaho، أُدين سائق مرخَّص عمره أقل من 17 سنة بمخالفة قيادة ثانية. ماذا يحدث؟","o":["رسالة إنذار","توقيف الرخصة 30 يومًا","توقيف الرخصة سنة واحدة","غرامة $50 فقط ولا شيء غيرها"],"h1":"الإدانة الأولى تجلب رسالة إنذار فقط. والثانية أشد.","h2":"حسب قواعد الرخصة المتدرّجة في Idaho، السائق الذي عمره أقل من 17 سنة تُوقَف رخصته 30 يومًا عند الإدانة الثانية بمخالفة قيادة.","p":"صحيح. الإدانة الثانية تعني توقيف الرخصة 30 يومًا."},"ref":{"doc":"ID","page":125}},{"id":"id-038","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, an adult fails a breath test for alcohol for the first time. How long is the administrative license suspension?","o":["90 days","7 days","Two years","Five years"],"h1":"It is about three months.","h2":"In Idaho, a first failed alcohol test brings a 90-day administrative suspension, with no driving at all for the first 30 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Idaho, un adulto no pasa una prueba de aliento de alcohol por primera vez. ¿Cuánto dura la suspensión administrativa de la licencia?","o":["90 días","7 días","Dos años","Cinco años"],"h1":"Son unos tres meses.","h2":"En Idaho, la primera prueba de alcohol no aprobada trae una suspensión administrativa de 90 días, sin poder manejar nada durante los primeros 30 días.","p":"Correcto. La suspensión es de 90 días."},"zh":{"q":"在 Idaho，一个成年人第一次没有通过酒精呼气测试。行政暂停驾照多久？","o":["90 天","7 天","两年","五年"],"h1":"大约三个月。","h2":"在 Idaho，第一次酒精测试不合格，会被行政暂停驾照 90 天，前 30 天完全不能开车。","p":"对。暂停 90 天。"},"vi":{"q":"Ở Idaho, một người lớn không đạt bài kiểm tra hơi thở về rượu lần đầu tiên. Thời gian đình chỉ bằng lái hành chính là bao lâu?","o":["90 ngày","7 ngày","Hai năm","Năm năm"],"h1":"Khoảng ba tháng.","h2":"Ở Idaho, lần đầu không đạt bài kiểm tra rượu sẽ bị đình chỉ bằng lái hành chính 90 ngày, và trong 30 ngày đầu hoàn toàn không được lái xe.","p":"Đúng. Thời gian đình chỉ là 90 ngày."},"tl":{"q":"Sa Idaho, bumagsak ang isang adult sa breath test para sa alak sa unang pagkakataon. Gaano katagal ang administrative suspension ng lisensya?","o":["90 araw","7 araw","Dalawang taon","Limang taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa Idaho, ang unang bagsak sa alcohol test ay may 90 araw na administrative suspension, at bawal talagang magmaneho sa unang 30 araw.","p":"Tama. 90 araw ang suspensyon."},"ar":{"q":"في Idaho، رسب شخص بالغ في اختبار التنفّس للكحول لأول مرة. كم مدة التوقيف الإداري للرخصة؟","o":["90 يومًا","7 أيام","سنتان","خمس سنوات"],"h1":"المدة حوالي ثلاثة أشهر.","h2":"في Idaho، الرسوب الأول في اختبار الكحول يؤدي إلى توقيف إداري للرخصة مدته 90 يومًا، ولا يُسمح بالقيادة أبدًا في أول 30 يومًا.","p":"صحيح. مدة التوقيف 90 يومًا."},"ref":{"doc":"ID","page":126}},{"id":"id-039","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, you get a Notice of Suspension after failing an alcohol test. How long do you have to ask for a hearing?","o":["24 hours","60 days","7 days","One year"],"h1":"It is about one week.","h2":"In Idaho, you may ask for an administrative hearing within 7 days of the date on the Notice of Suspension.","p":"Right. You have 7 days to ask for a hearing."},"es":{"q":"En Idaho, usted recibe un Aviso de Suspensión después de no pasar una prueba de alcohol. ¿Cuánto tiempo tiene para pedir una audiencia?","o":["24 horas","60 días","7 días","Un año"],"h1":"Es más o menos una semana.","h2":"En Idaho, usted puede pedir una audiencia administrativa dentro de 7 días a partir de la fecha del Aviso de Suspensión.","p":"Correcto. Tiene 7 días para pedir una audiencia."},"zh":{"q":"在 Idaho，你酒精测试没通过后收到一份 Notice of Suspension。你有多久时间可以申请听证？","o":["24 小时","60 天","7 天","一年"],"h1":"大约一个星期。","h2":"在 Idaho，你可以在 Notice of Suspension 上的日期起 7 天内申请行政听证。","p":"对。你有 7 天时间申请听证。"},"vi":{"q":"Ở Idaho, bạn nhận được Notice of Suspension sau khi không đạt bài kiểm tra rượu. Bạn có bao lâu để yêu cầu một phiên điều trần?","o":["24 giờ","60 ngày","7 ngày","Một năm"],"h1":"Khoảng một tuần.","h2":"Ở Idaho, bạn có thể yêu cầu một phiên điều trần hành chính trong vòng 7 ngày kể từ ngày ghi trên Notice of Suspension.","p":"Đúng. Bạn có 7 ngày để yêu cầu điều trần."},"tl":{"q":"Sa Idaho, nakatanggap ka ng Notice of Suspension matapos bumagsak sa alcohol test. Gaano katagal ang mayroon ka para humingi ng hearing?","o":["24 oras","60 araw","7 araw","Isang taon"],"h1":"Mga isang linggo ito.","h2":"Sa Idaho, puwede kang humingi ng administrative hearing sa loob ng 7 araw mula sa petsa sa Notice of Suspension.","p":"Tama. May 7 araw ka para humingi ng hearing."},"ar":{"q":"في Idaho، وصلك Notice of Suspension بعد الرسوب في اختبار الكحول. كم لديك من الوقت لتطلب جلسة استماع؟","o":["24 ساعة","60 يومًا","7 أيام","سنة واحدة"],"h1":"المدة حوالي أسبوع واحد.","h2":"في Idaho، يمكنك أن تطلب جلسة استماع إدارية خلال 7 أيام من التاريخ المكتوب على Notice of Suspension.","p":"صحيح. لديك 7 أيام لتطلب جلسة استماع."},"ref":{"doc":"ID","page":125}},{"id":"id-040","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver refuses an officer's request for an alcohol or drug test. What civil penalty can they face, besides a suspension?","o":["$25","$100","$5,000","$250"],"h1":"It is more than $100 and less than $500.","h2":"Under Idaho's implied consent law, refusing the test can bring a license suspension and a civil penalty of $250.","p":"Right. The civil penalty is $250."},"es":{"q":"En Idaho, un conductor se niega a hacer la prueba de alcohol o drogas que pide un oficial. ¿Qué multa civil puede recibir, además de una suspensión?","o":["$25","$100","$5,000","$250"],"h1":"Es más de $100 y menos de $500.","h2":"Según la ley de consentimiento implícito de Idaho, negarse a la prueba puede traer una suspensión de la licencia y una multa civil de $250.","p":"Correcto. La multa civil es de $250."},"zh":{"q":"在 Idaho，一位司机拒绝警察要求的酒精或毒品测试。除了暂停驾照，他还可能面对什么民事罚款？","o":["$25","$100","$5,000","$250"],"h1":"比 $100 多，比 $500 少。","h2":"根据 Idaho 的默示同意法，拒绝测试可能会被暂停驾照，并被处以 $250 的民事罚款。","p":"对。民事罚款是 $250。"},"vi":{"q":"Ở Idaho, một người lái từ chối yêu cầu kiểm tra rượu hoặc ma túy của cảnh sát. Ngoài việc bị đình chỉ bằng lái, họ có thể bị phạt dân sự bao nhiêu?","o":["$25","$100","$5,000","$250"],"h1":"Nhiều hơn $100 và ít hơn $500.","h2":"Theo luật đồng ý ngầm của Idaho, từ chối kiểm tra có thể bị đình chỉ bằng lái và bị phạt dân sự $250.","p":"Đúng. Tiền phạt dân sự là $250."},"tl":{"q":"Sa Idaho, tumanggi ang isang driver sa hiling ng pulis na alcohol o drug test. Anong civil penalty ang puwede niyang harapin, bukod sa suspensyon?","o":["$25","$100","$5,000","$250"],"h1":"Higit ito sa $100 at kulang sa $500.","h2":"Ayon sa implied consent law ng Idaho, ang pagtanggi sa test ay puwedeng magdulot ng suspensyon ng lisensya at civil penalty na $250.","p":"Tama. $250 ang civil penalty."},"ar":{"q":"في Idaho، رفض سائق طلب الشرطي إجراء اختبار للكحول أو المخدرات. ما الغرامة المدنية التي قد يواجهها، إضافةً إلى توقيف الرخصة؟","o":["$25","$100","$5,000","$250"],"h1":"هي أكثر من $100 وأقل من $500.","h2":"حسب قانون الموافقة الضمنية في Idaho، رفض الاختبار قد يؤدي إلى توقيف الرخصة وغرامة مدنية قدرها $250.","p":"صحيح. الغرامة المدنية هي $250."},"ref":{"doc":"ID","page":126}},{"id":"id-041","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a driver refuses an alcohol test for the first time, and the court upholds the officer. How long is the license suspended?","o":["One year, with no driving at all","30 days, with work driving allowed","90 days","There is no suspension for a first refusal"],"h1":"A refusal is treated more harshly than failing the test.","h2":"In Idaho, a first test refusal brings a one-year suspension with absolutely no driving privileges.","p":"Right. A first refusal means one year with no driving."},"es":{"q":"En Idaho, un conductor se niega por primera vez a una prueba de alcohol, y el tribunal confirma lo que dijo el oficial. ¿Por cuánto tiempo se suspende la licencia?","o":["Un año, sin poder manejar nada","30 días, con permiso para manejar al trabajo","90 días","No hay suspensión por la primera negativa"],"h1":"Negarse se castiga más que no pasar la prueba.","h2":"En Idaho, la primera negativa a la prueba trae una suspensión de un año sin ningún privilegio de manejo.","p":"Correcto. La primera negativa significa un año sin manejar."},"zh":{"q":"在 Idaho，一位司机第一次拒绝酒精测试，法庭支持警察的决定。驾照会被暂停多久？","o":["一年，完全不能开车","30 天，可以开车去上班","90 天","第一次拒绝不会暂停驾照"],"h1":"拒绝测试比测试不合格处罚更重。","h2":"在 Idaho，第一次拒绝测试会被暂停驾照一年，而且完全没有任何开车的权利。","p":"对。第一次拒绝就是一年完全不能开车。"},"vi":{"q":"Ở Idaho, một người lái từ chối kiểm tra rượu lần đầu tiên, và tòa án đồng ý với cảnh sát. Bằng lái bị đình chỉ bao lâu?","o":["Một năm, hoàn toàn không được lái xe","30 ngày, được lái xe đi làm","90 ngày","Không bị đình chỉ khi từ chối lần đầu"],"h1":"Từ chối kiểm tra bị xử nặng hơn là không đạt bài kiểm tra.","h2":"Ở Idaho, lần đầu từ chối kiểm tra sẽ bị đình chỉ bằng lái một năm và hoàn toàn không có quyền lái xe.","p":"Đúng. Lần đầu từ chối nghĩa là một năm hoàn toàn không được lái xe."},"tl":{"q":"Sa Idaho, tumanggi ang isang driver sa alcohol test sa unang pagkakataon, at pumanig ang korte sa pulis. Gaano katagal sususpendihin ang lisensya?","o":["Isang taon, bawal talagang magmaneho","30 araw, puwedeng magmaneho papunta sa trabaho","90 araw","Walang suspensyon sa unang pagtanggi"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test.","h2":"Sa Idaho, ang unang pagtanggi sa test ay may isang taong suspensyon na walang anumang pribilehiyong magmaneho.","p":"Tama. Ang unang pagtanggi ay isang taon na bawal magmaneho."},"ar":{"q":"في Idaho، رفض سائق اختبار الكحول لأول مرة، وأيّدت المحكمة قرار الشرطي. كم مدة توقيف الرخصة؟","o":["سنة واحدة، بلا قيادة أبدًا","30 يومًا، مع السماح بالقيادة إلى العمل","90 يومًا","لا يوجد توقيف عند الرفض الأول"],"h1":"الرفض يُعاقَب بشدة أكبر من الرسوب في الاختبار.","h2":"في Idaho، الرفض الأول للاختبار يؤدي إلى توقيف الرخصة سنة واحدة، بلا أي حق في القيادة أبدًا.","p":"صحيح. الرفض الأول يعني سنة واحدة بلا قيادة."},"ref":{"doc":"ID","page":126}},{"id":"id-042","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, what is the speed limit for cars on an interstate when no other limit is posted?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"Some stretches may be posted even higher, at 80.","h2":"In Idaho, the speed limit on interstates is 75 mph unless a different limit is posted, and 80 mph may be allowed where posted.","p":"Right. It is 75 mph unless posted otherwise."},"es":{"q":"En Idaho, ¿cuál es el límite de velocidad para autos en una autopista interestatal cuando no hay otro límite señalado?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"Algunos tramos pueden tener un límite aún más alto, de 80.","h2":"En Idaho, el límite en las autopistas interestatales es de 75 mph, a menos que se indique otro, y puede ser de 80 mph donde esté señalado.","p":"Correcto. Es de 75 mph a menos que se indique otro."},"zh":{"q":"在 Idaho，没有标出其他限速时，汽车在州际公路上的限速是多少？","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"有些路段可能标出更高的限速，到 80。","h2":"在 Idaho，州际公路的限速是 75 mph，除非标出不同的限速，有标示的地方可能允许 80 mph。","p":"对。除非另有标示，限速是 75 mph。"},"vi":{"q":"Ở Idaho, tốc độ giới hạn cho xe hơi trên xa lộ liên bang là bao nhiêu khi không có biển báo giới hạn khác?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"Một số đoạn đường có thể có biển báo cao hơn, đến 80.","h2":"Ở Idaho, tốc độ giới hạn trên xa lộ liên bang là 75 mph trừ khi có biển báo giới hạn khác, và có thể được phép 80 mph ở nơi có biển báo.","p":"Đúng. Là 75 mph trừ khi có biển báo khác."},"tl":{"q":"Sa Idaho, ano ang speed limit ng mga kotse sa interstate kapag walang ibang limit na nakapaskil?","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"May ilang bahagi na puwedeng mas mataas pa ang nakapaskil, hanggang 80.","h2":"Sa Idaho, 75 mph ang speed limit sa mga interstate maliban kung may ibang limit na nakapaskil, at puwedeng payagan ang 80 mph kung saan ito nakapaskil.","p":"Tama. 75 mph ito maliban kung iba ang nakapaskil."},"ar":{"q":"في Idaho، ما حد السرعة للسيارات على الطريق السريع بين الولايات (interstate) عندما لا يوجد حد آخر مكتوب؟","o":["55 mph","65 mph","75 mph","85 mph"],"h1":"بعض الأجزاء قد يُكتب فيها حد أعلى، حتى 80.","h2":"في Idaho، حد السرعة على الطرق السريعة بين الولايات هو 75 ميلًا في الساعة (mph) ما لم يُكتب حد مختلف، وقد يُسمح بـ 80 mph حيث يكون ذلك مكتوبًا.","p":"صحيح. هو 75 mph ما لم يُكتب غير ذلك."},"ref":{"doc":"ID","page":68}},{"id":"id-043","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, what is the top speed in a residential, business or urban district when no sign says otherwise?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"It is less than 45 mph.","h2":"In Idaho, the maximum speed in any residential, business or urban district is 35 mph unless a different limit is posted.","p":"Right. It is 35 mph unless posted otherwise."},"es":{"q":"En Idaho, ¿cuál es la velocidad máxima en una zona residencial, comercial o urbana cuando ninguna señal indica otra?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Es menos de 45 mph.","h2":"En Idaho, la velocidad máxima en cualquier zona residencial, comercial o urbana es de 35 mph, a menos que se indique otro límite.","p":"Correcto. Es de 35 mph a menos que se indique otra."},"zh":{"q":"在 Idaho，没有标志另外规定时，在住宅区、商业区或市区的最高速度是多少？","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"比 45 mph 低。","h2":"在 Idaho，任何住宅区、商业区或市区的最高速度是 35 mph，除非标出不同的限速。","p":"对。除非另有标示，限速是 35 mph。"},"vi":{"q":"Ở Idaho, tốc độ tối đa trong khu dân cư, khu thương mại hoặc khu đô thị là bao nhiêu khi không có biển báo khác?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Thấp hơn 45 mph.","h2":"Ở Idaho, tốc độ tối đa trong mọi khu dân cư, khu thương mại hoặc khu đô thị là 35 mph trừ khi có biển báo giới hạn khác.","p":"Đúng. Là 35 mph trừ khi có biển báo khác."},"tl":{"q":"Sa Idaho, ano ang pinakamataas na bilis sa residential, business o urban district kapag walang karatulang nagsasabi ng iba?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Mas mababa ito sa 45 mph.","h2":"Sa Idaho, 35 mph ang pinakamataas na bilis sa anumang residential, business o urban district maliban kung may ibang limit na nakapaskil.","p":"Tama. 35 mph ito maliban kung iba ang nakapaskil."},"ar":{"q":"في Idaho، ما أعلى سرعة في منطقة سكنية أو تجارية أو حضرية عندما لا توجد لافتة تقول غير ذلك؟","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"هي أقل من 45 mph.","h2":"في Idaho، أعلى سرعة في أي منطقة سكنية أو تجارية أو حضرية هي 35 ميلًا في الساعة (mph) ما لم يُكتب حد مختلف.","p":"صحيح. هي 35 mph ما لم يُكتب غير ذلك."},"ref":{"doc":"ID","page":69}},{"id":"id-044","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, you are passing a slower car on a two-lane road posted at 55 mph or more. How much over the limit may you go while passing?","o":["Not at all","Up to 5 mph","Up to 25 mph","Up to 15 mph"],"h1":"It applies only while passing, and never in work zones.","h2":"In Idaho, a car not towing anything may go up to 15 mph over the limit to pass a slower vehicle on a two-lane road posted at 55 mph or more, then slow back down.","p":"Right. You may go up to 15 mph over while passing."},"es":{"q":"En Idaho, usted rebasa a un auto más lento en una carretera de dos carriles con límite de 55 mph o más. ¿Cuánto puede pasar del límite mientras rebasa?","o":["Nada","Hasta 5 mph","Hasta 25 mph","Hasta 15 mph"],"h1":"Se permite solo al rebasar, y nunca en zonas de obras.","h2":"En Idaho, un auto que no remolca nada puede ir hasta 15 mph sobre el límite para rebasar a un vehículo más lento en una carretera de dos carriles con límite de 55 mph o más, y luego debe volver a bajar la velocidad.","p":"Correcto. Puede ir hasta 15 mph sobre el límite al rebasar."},"zh":{"q":"在 Idaho，你在一条限速 55 mph 或以上的双车道路上超越一辆较慢的车。超车时你可以超过限速多少？","o":["完全不可以","最多 5 mph","最多 25 mph","最多 15 mph"],"h1":"这只适用于超车时，而且在施工区绝对不行。","h2":"在 Idaho，没有拖带任何东西的汽车，在限速 55 mph 或以上的双车道路上超越较慢的车时，最多可以超过限速 15 mph，超车后要再减速。","p":"对。超车时最多可以超过限速 15 mph。"},"vi":{"q":"Ở Idaho, bạn đang vượt một xe chậm hơn trên đường hai làn có giới hạn 55 mph trở lên. Khi vượt, bạn được chạy quá giới hạn bao nhiêu?","o":["Hoàn toàn không được","Tối đa 5 mph","Tối đa 25 mph","Tối đa 15 mph"],"h1":"Điều này chỉ áp dụng khi vượt xe, và không bao giờ trong khu công trường.","h2":"Ở Idaho, xe hơi không kéo theo gì có thể chạy quá giới hạn tối đa 15 mph để vượt một xe chậm hơn trên đường hai làn có giới hạn 55 mph trở lên, rồi giảm tốc độ trở lại.","p":"Đúng. Bạn được chạy quá tối đa 15 mph khi vượt xe."},"tl":{"q":"Sa Idaho, nag-o-overtake ka sa mas mabagal na kotse sa two-lane na kalsada na may nakapaskil na 55 mph o higit pa. Gaano kalaki ang puwede mong ilampas sa limit habang nag-o-overtake?","o":["Hindi talaga puwede","Hanggang 5 mph","Hanggang 25 mph","Hanggang 15 mph"],"h1":"Para lang ito habang nag-o-overtake, at hindi kailanman sa work zone.","h2":"Sa Idaho, ang kotseng walang hinihila ay puwedeng lumampas nang hanggang 15 mph sa limit para mag-overtake sa mas mabagal na sasakyan sa two-lane na kalsada na may nakapaskil na 55 mph o higit pa, at pagkatapos ay babagal ulit.","p":"Tama. Puwede kang lumampas nang hanggang 15 mph habang nag-o-overtake."},"ar":{"q":"في Idaho، أنت تتجاوز سيارة أبطأ على طريق بمسارين حدّ السرعة المكتوب عليه 55 mph أو أكثر. كم يجوز أن تزيد على الحد أثناء التجاوز؟","o":["لا يجوز أبدًا","حتى 5 mph","حتى 25 mph","حتى 15 mph"],"h1":"هذا ينطبق أثناء التجاوز فقط، ولا ينطبق أبدًا في مناطق الأشغال.","h2":"في Idaho، السيارة التي لا تسحب شيئًا يجوز أن تزيد حتى 15 mph على الحد لتتجاوز مركبة أبطأ على طريق بمسارين حدّه المكتوب 55 mph أو أكثر، ثم تعود فتخفّف السرعة.","p":"صحيح. يجوز أن تزيد حتى 15 mph أثناء التجاوز."},"ref":{"doc":"ID","page":77}},{"id":"id-045","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, how close to an intersection or a railroad crossing is passing not allowed, unless signs or markings say otherwise?","o":["Within 100 feet","Within 10 feet","Within 1,000 feet","Within one mile"],"h1":"It is about the length of six or seven cars.","h2":"In Idaho, you may not pass within 100 feet of an intersection or a railroad crossing, unless traffic control devices allow it.","p":"Right. No passing within 100 feet."},"es":{"q":"En Idaho, ¿a qué distancia de una intersección o de un cruce de ferrocarril no se permite rebasar, salvo que las señales o marcas indiquen otra cosa?","o":["A menos de 100 pies","A menos de 10 pies","A menos de 1,000 pies","A menos de una milla"],"h1":"Es más o menos el largo de seis o siete autos.","h2":"En Idaho, no puede rebasar a menos de 100 pies de una intersección o de un cruce de ferrocarril, salvo que los dispositivos de control de tránsito lo permitan.","p":"Correcto. No se rebasa a menos de 100 pies."},"zh":{"q":"在 Idaho，除非标志或标线另有规定，在离路口或铁路道口多近的地方不可以超车？","o":["100 英尺以内","10 英尺以内","1,000 英尺以内","一英里以内"],"h1":"大约是六到七辆车的长度。","h2":"在 Idaho，你不可以在离路口或铁路道口 100 英尺以内的地方超车，除非交通控制设施允许。","p":"对。100 英尺以内不可以超车。"},"vi":{"q":"Ở Idaho, không được vượt xe khi cách giao lộ hoặc chỗ băng qua đường sắt gần bao nhiêu, trừ khi biển báo hoặc vạch kẻ đường cho phép?","o":["Trong vòng 100 feet","Trong vòng 10 feet","Trong vòng 1,000 feet","Trong vòng một dặm"],"h1":"Khoảng chiều dài của sáu hoặc bảy xe hơi.","h2":"Ở Idaho, bạn không được vượt xe trong vòng 100 feet cách giao lộ hoặc chỗ băng qua đường sắt, trừ khi thiết bị điều khiển giao thông cho phép.","p":"Đúng. Không được vượt trong vòng 100 feet."},"tl":{"q":"Sa Idaho, gaano kalapit sa intersection o railroad crossing bawal mag-overtake, maliban kung iba ang sinasabi ng mga karatula o marka?","o":["Sa loob ng 100 feet","Sa loob ng 10 feet","Sa loob ng 1,000 feet","Sa loob ng isang milya"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Idaho, bawal kang mag-overtake sa loob ng 100 feet mula sa intersection o railroad crossing, maliban kung pinapayagan ito ng mga traffic control device.","p":"Tama. Bawal mag-overtake sa loob ng 100 feet."},"ar":{"q":"في Idaho، ما المسافة من التقاطع أو من معبر السكة الحديدية التي لا يُسمح بالتجاوز ضمنها، ما لم تقل اللافتات أو العلامات غير ذلك؟","o":["ضمن 100 قدم","ضمن 10 أقدام","ضمن 1,000 قدم","ضمن ميل واحد"],"h1":"هي تقريبًا طول ست أو سبع سيارات.","h2":"في Idaho، لا يجوز أن تتجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديدية، إلا إذا سمحت بذلك أجهزة التحكم في المرور.","p":"صحيح. لا تجاوز ضمن 100 قدم."},"ref":{"doc":"ID","page":76}},{"id":"id-046","scope":"ID","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Idaho, a school bus is stopped with red lights flashing on the other side of the road. When do you NOT have to stop?","o":["When you are in a hurry","When the bus is on a two-lane road","When the highway has four or more lanes, with two going each way","When no children are in sight"],"h1":"It depends on how many lanes the highway has.","h2":"In Idaho, you do not have to stop for a school bus on the other side if the highway has four or more lanes, with two lanes going in each direction.","p":"Right. On a highway with two lanes each way, the other side does not stop."},"es":{"q":"En Idaho, un autobús escolar está detenido con las luces rojas encendidas al otro lado de la carretera. ¿Cuándo NO tiene que detenerse?","o":["Cuando usted tiene prisa","Cuando el autobús está en una carretera de dos carriles","Cuando la carretera tiene cuatro carriles o más, con dos en cada sentido","Cuando no se ven niños"],"h1":"Depende de cuántos carriles tiene la carretera.","h2":"En Idaho, no tiene que detenerse por un autobús escolar al otro lado si la carretera tiene cuatro carriles o más, con dos carriles en cada sentido.","p":"Correcto. En una carretera con dos carriles en cada sentido, el otro lado no se detiene."},"zh":{"q":"在 Idaho，一辆校车停在马路对面，红灯在闪。什么时候你不需要停车？","o":["当你赶时间时","当校车在双车道路上时","当公路有四条或更多车道，每个方向两条时","当看不到孩子时"],"h1":"这取决于公路有几条车道。","h2":"在 Idaho，如果公路有四条或更多车道，每个方向有两条车道，你就不需要为对面的校车停车。","p":"对。在每个方向有两条车道的公路上，对面的车不用停。"},"vi":{"q":"Ở Idaho, một xe buýt trường học đang dừng với đèn đỏ nhấp nháy ở phía bên kia đường. Khi nào bạn KHÔNG phải dừng lại?","o":["Khi bạn đang vội","Khi xe buýt ở trên đường hai làn","Khi xa lộ có bốn làn trở lên, mỗi chiều hai làn","Khi không thấy trẻ em nào"],"h1":"Điều đó tùy vào số làn của xa lộ.","h2":"Ở Idaho, bạn không phải dừng lại vì xe buýt trường học ở phía bên kia nếu xa lộ có bốn làn trở lên, với hai làn đi mỗi chiều.","p":"Đúng. Trên xa lộ có hai làn mỗi chiều, xe ở phía bên kia không phải dừng."},"tl":{"q":"Sa Idaho, may school bus na nakahinto na kumikislap ang pulang ilaw sa kabilang panig ng kalsada. Kailan HINDI mo kailangang huminto?","o":["Kapag nagmamadali ka","Kapag nasa two-lane na kalsada ang bus","Kapag ang highway ay may apat o higit pang lane, dalawa sa bawat direksyon","Kapag walang batang nakikita"],"h1":"Depende ito sa dami ng lane ng highway.","h2":"Sa Idaho, hindi mo kailangang huminto para sa school bus sa kabilang panig kung ang highway ay may apat o higit pang lane, na may dalawang lane sa bawat direksyon.","p":"Tama. Sa highway na may dalawang lane bawat direksyon, hindi humihinto ang kabilang panig."},"ar":{"q":"في Idaho، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجهة الأخرى من الطريق. متى ليس عليك أن تتوقف؟","o":["عندما تكون مستعجلًا","عندما تكون الحافلة على طريق بمسارين","عندما يكون للطريق السريع أربعة مسارات أو أكثر، اثنان في كل اتجاه","عندما لا ترى أي أطفال"],"h1":"هذا يعتمد على عدد مسارات الطريق السريع.","h2":"في Idaho، ليس عليك أن تتوقف لحافلة مدرسية على الجهة الأخرى إذا كان للطريق السريع أربعة مسارات أو أكثر، مع مسارين في كل اتجاه.","p":"صحيح. على طريق سريع فيه مساران في كل اتجاه، لا تتوقف الجهة الأخرى."},"ref":{"doc":"ID","page":70}},{"id":"id-047","scope":"ID","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Idaho, what must a bicyclist do at a stop sign?","o":["Get off and walk the bike across","Slow down and yield, without a full stop","Stop fully and wait for a car to wave them on","Use the sidewalk to get around it"],"h1":"Idaho has a special stop sign rule for bicycles.","h2":"In Idaho, a bicyclist does not need to come to a complete stop at a stop sign, but must yield to vehicles at or near the intersection and then go on with care.","p":"Right. A bicyclist may yield at a stop sign without a full stop."},"es":{"q":"En Idaho, ¿qué debe hacer un ciclista en una señal de alto?","o":["Bajarse y cruzar caminando con la bicicleta","Bajar la velocidad y ceder el paso, sin detenerse por completo","Detenerse por completo y esperar que un auto le haga señas","Usar la acera para rodearla"],"h1":"Idaho tiene una regla especial de alto para bicicletas.","h2":"En Idaho, un ciclista no tiene que detenerse por completo en una señal de alto, pero debe ceder el paso a los vehículos en la intersección o cerca de ella y luego seguir con cuidado.","p":"Correcto. Un ciclista puede ceder el paso en una señal de alto sin detenerse por completo."},"zh":{"q":"在 Idaho，骑自行车的人在停车标志前必须怎么做？","o":["下车，推着自行车过去","减速并让行，不用完全停下","完全停下，等汽车示意他先走","走人行道绕过去"],"h1":"Idaho 对自行车有一个特别的停车标志规定。","h2":"在 Idaho，骑自行车的人在停车标志前不需要完全停下，但必须让路口或路口附近的车辆先走，然后小心前进。","p":"对。骑自行车的人在停车标志前可以让行，不用完全停下。"},"vi":{"q":"Ở Idaho, người đi xe đạp phải làm gì ở biển báo dừng?","o":["Xuống xe và dắt xe đạp qua","Chạy chậm lại và nhường đường, không cần dừng hẳn","Dừng hẳn và chờ một xe hơi ra hiệu cho đi","Đi lên vỉa hè để vòng qua"],"h1":"Idaho có một luật đặc biệt về biển báo dừng cho xe đạp.","h2":"Ở Idaho, người đi xe đạp không cần dừng hẳn ở biển báo dừng, nhưng phải nhường đường cho xe cộ ở tại hoặc gần giao lộ rồi mới cẩn thận đi tiếp.","p":"Đúng. Người đi xe đạp có thể nhường đường ở biển báo dừng mà không cần dừng hẳn."},"tl":{"q":"Sa Idaho, ano ang dapat gawin ng nagbibisikleta sa stop sign?","o":["Bumaba at itulak ang bisikleta pagtawid","Bumagal at magbigay-daan, nang hindi humihinto nang buo","Huminto nang buo at hintaying sumenyas ang kotse na tumuloy siya","Gamitin ang sidewalk para lampasan ito"],"h1":"May espesyal na patakaran ang Idaho sa stop sign para sa bisikleta.","h2":"Sa Idaho, hindi kailangang huminto nang buo ng nagbibisikleta sa stop sign, pero dapat siyang magbigay-daan sa mga sasakyan na nasa intersection o malapit dito at saka tumuloy nang maingat.","p":"Tama. Puwedeng magbigay-daan ang nagbibisikleta sa stop sign nang hindi humihinto nang buo."},"ar":{"q":"في Idaho، ماذا يجب أن يفعل راكب الدراجة عند لافتة التوقف؟","o":["ينزل ويمشي بالدراجة ليعبر","يخفّف السرعة ويعطي الأولوية، بلا توقف كامل","يتوقف تمامًا وينتظر أن تشير له سيارة بالمرور","يستخدم الرصيف ليلتفّ حولها"],"h1":"في Idaho قاعدة خاصة للدراجات عند لافتة التوقف.","h2":"في Idaho، ليس على راكب الدراجة أن يتوقف تمامًا عند لافتة التوقف، لكن يجب أن يعطي الأولوية للمركبات الموجودة في التقاطع أو قربه، ثم يتابع بحذر.","p":"صحيح. يمكن لراكب الدراجة أن يعطي الأولوية عند لافتة التوقف بلا توقف كامل."},"ref":{"doc":"ID","page":98}},{"id":"id-048","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, you are passing a bicyclist and cannot change lanes. What is the safe space to leave, at a minimum?","o":["6 inches","1 foot","2 feet","3 feet"],"h1":"Think of about one big step.","h2":"The Idaho handbook says to leave at least 3 feet when passing a bicyclist, and more space at higher speeds.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Idaho, usted rebasa a un ciclista y no puede cambiar de carril. ¿Cuál es el espacio mínimo seguro que debe dejar?","o":["6 pulgadas","1 pie","2 pies","3 pies"],"h1":"Piense en un paso largo.","h2":"El manual de Idaho dice que debe dejar al menos 3 pies al rebasar a un ciclista, y más espacio a mayor velocidad.","p":"Correcto. Deje al menos 3 pies."},"zh":{"q":"在 Idaho，你要超过一个骑自行车的人，但不能换车道。至少要留多少安全距离？","o":["6 英寸","1 英尺","2 英尺","3 英尺"],"h1":"想想大约一大步。","h2":"Idaho 驾驶手册说，超过骑自行车的人时至少要留 3 英尺，速度越快要留更多空间。","p":"对。至少留 3 英尺。"},"vi":{"q":"Ở Idaho, bạn đang vượt một người đi xe đạp và không thể đổi làn. Khoảng cách an toàn tối thiểu cần chừa là bao nhiêu?","o":["6 inch","1 foot","2 feet","3 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Sổ tay lái xe của Idaho nói phải chừa ít nhất 3 feet khi vượt người đi xe đạp, và chừa nhiều hơn khi chạy nhanh hơn.","p":"Đúng. Chừa ít nhất 3 feet."},"tl":{"q":"Sa Idaho, nag-o-overtake ka sa isang nagbibisikleta at hindi ka makalipat ng lane. Ano ang pinakamaliit na ligtas na espasyong dapat mong iwan?","o":["6 inches","1 foot","2 feet","3 feet"],"h1":"Isipin ang mga isang malaking hakbang.","h2":"Sinasabi ng handbook ng Idaho na mag-iwan ng hindi bababa sa 3 feet kapag nag-o-overtake sa nagbibisikleta, at mas malaking espasyo kapag mas mabilis.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet."},"ar":{"q":"في Idaho، أنت تتجاوز راكب دراجة ولا تستطيع أن تغيّر المسار. ما المسافة الآمنة التي يجب أن تتركها على الأقل؟","o":["6 بوصات","قدم واحد (1)","قدمان (2)","3 أقدام"],"h1":"فكّر في خطوة كبيرة واحدة تقريبًا.","h2":"يقول دليل Idaho أن تترك 3 أقدام على الأقل عندما تتجاوز راكب دراجة، ومسافة أكبر عند السرعات الأعلى.","p":"صحيح. اترك 3 أقدام على الأقل."},"ref":{"doc":"ID","page":98}},{"id":"id-049","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, a car is coming toward you at night. When must you dim your high beams?","o":["Within 500 feet of the car","Within 50 feet of the car","Only when the car is beside you","Only if the other driver flashes their lights"],"h1":"Think of the length of more than one and a half football fields.","h2":"In Idaho, you must dim your headlights within 500 feet of an oncoming vehicle, and within 200 feet of a vehicle you follow.","p":"Right. Dim them within 500 feet of an oncoming car."},"es":{"q":"En Idaho, un auto viene hacia usted de noche. ¿Cuándo debe bajar las luces altas?","o":["A menos de 500 pies del auto","A menos de 50 pies del auto","Solo cuando el auto está a su lado","Solo si el otro conductor le hace cambio de luces"],"h1":"Piense en más de una cancha y media de fútbol americano.","h2":"En Idaho, debe bajar las luces a menos de 500 pies de un vehículo que viene de frente, y a menos de 200 pies de un vehículo que va delante de usted.","p":"Correcto. Bájelas a menos de 500 pies de un auto que viene de frente."},"zh":{"q":"在 Idaho，晚上有一辆车朝你开过来。你必须什么时候把远光灯调暗？","o":["离那辆车 500 英尺以内时","离那辆车 50 英尺以内时","只有当那辆车在你旁边时","只有当对方司机闪灯时"],"h1":"想想比一个半足球场还长的距离。","h2":"在 Idaho，离迎面来车 500 英尺以内时，你必须把车灯调暗；跟在别的车后面 200 英尺以内时也要调暗。","p":"对。离迎面来车 500 英尺以内时要调暗。"},"vi":{"q":"Ở Idaho, một xe đang chạy về phía bạn vào ban đêm. Khi nào bạn phải hạ đèn pha xuống?","o":["Khi cách xe đó trong vòng 500 feet","Khi cách xe đó trong vòng 50 feet","Chỉ khi xe đó ở ngay bên cạnh bạn","Chỉ khi người lái kia nháy đèn"],"h1":"Hãy nghĩ đến chiều dài hơn một sân bóng bầu dục rưỡi.","h2":"Ở Idaho, bạn phải hạ đèn pha khi cách xe chạy ngược chiều trong vòng 500 feet, và khi cách xe bạn đang chạy theo sau trong vòng 200 feet.","p":"Đúng. Hạ đèn khi cách xe ngược chiều trong vòng 500 feet."},"tl":{"q":"Sa Idaho, may kotseng papalapit sa iyo sa gabi. Kailan mo dapat i-dim ang iyong high beams?","o":["Sa loob ng 500 feet mula sa kotse","Sa loob ng 50 feet mula sa kotse","Kapag nasa tabi mo na lang ang kotse","Kapag nag-flash lang ng ilaw ang ibang driver"],"h1":"Isipin ang haba na higit sa isa't kalahating football field.","h2":"Sa Idaho, dapat mong i-dim ang iyong headlights sa loob ng 500 feet mula sa paparating na sasakyan, at sa loob ng 200 feet mula sa sasakyang sinusundan mo.","p":"Tama. I-dim ang mga ito sa loob ng 500 feet mula sa paparating na kotse."},"ar":{"q":"في Idaho، سيارة قادمة نحوك في الليل. متى يجب أن تخفض الأضواء العالية؟","o":["ضمن 500 قدم من السيارة","ضمن 50 قدمًا من السيارة","فقط عندما تكون السيارة بجانبك","فقط إذا أومض السائق الآخر بأضوائه"],"h1":"فكّر في طول أكثر من ملعب كرة قدم ونصف.","h2":"في Idaho، يجب أن تخفض أضواءك ضمن 500 قدم من مركبة قادمة نحوك، وضمن 200 قدم من مركبة تسير خلفها.","p":"صحيح. اخفضها ضمن 500 قدم من سيارة قادمة نحوك."},"ref":{"doc":"ID","page":43}},{"id":"id-050","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, when may you use studded snow tires, unless ITD changes the dates?","o":["All year","Only in January and February","From October 1 to April 30","From May 1 to September 30"],"h1":"They are for the cold part of the year.","h2":"In Idaho, studded snow tires may be used from October 1 to April 30, and ITD sometimes adjusts the dates for weather.","p":"Right. Studded tires are allowed October 1 to April 30."},"es":{"q":"En Idaho, ¿cuándo puede usar llantas de nieve con clavos, si ITD no cambia las fechas?","o":["Todo el año","Solo en enero y febrero","Del 1 de octubre al 30 de abril","Del 1 de mayo al 30 de septiembre"],"h1":"Son para la parte fría del año.","h2":"En Idaho, las llantas de nieve con clavos se pueden usar del 1 de octubre al 30 de abril, y a veces ITD ajusta las fechas por el clima.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 30 de abril."},"zh":{"q":"在 Idaho，除非 ITD 改变日期，什么时候可以使用带钉的雪地轮胎？","o":["全年","只在一月和二月","从 10 月 1 日到 4 月 30 日","从 5 月 1 日到 9 月 30 日"],"h1":"它们是给一年中寒冷的时候用的。","h2":"在 Idaho，带钉的雪地轮胎可以从 10 月 1 日用到 4 月 30 日，ITD 有时会因为天气调整日期。","p":"对。带钉轮胎可以从 10 月 1 日用到 4 月 30 日。"},"vi":{"q":"Ở Idaho, khi nào bạn được dùng lốp tuyết có đinh, trừ khi ITD thay đổi ngày?","o":["Cả năm","Chỉ trong tháng 1 và tháng 2","Từ 1 tháng 10 đến 30 tháng 4","Từ 1 tháng 5 đến 30 tháng 9"],"h1":"Chúng dành cho thời gian lạnh trong năm.","h2":"Ở Idaho, lốp tuyết có đinh được dùng từ 1 tháng 10 đến 30 tháng 4, và đôi khi ITD điều chỉnh ngày theo thời tiết.","p":"Đúng. Lốp có đinh được phép từ 1 tháng 10 đến 30 tháng 4."},"tl":{"q":"Sa Idaho, kailan puwedeng gumamit ng studded snow tires, maliban kung babaguhin ng ITD ang mga petsa?","o":["Buong taon","Sa Enero at Pebrero lang","Mula Oktubre 1 hanggang Abril 30","Mula Mayo 1 hanggang Setyembre 30"],"h1":"Para ang mga ito sa malamig na bahagi ng taon.","h2":"Sa Idaho, puwedeng gamitin ang studded snow tires mula Oktubre 1 hanggang Abril 30, at minsan ay inaayos ng ITD ang mga petsa dahil sa panahon.","p":"Tama. Puwede ang studded tires mula Oktubre 1 hanggang Abril 30."},"ar":{"q":"في Idaho، متى يجوز أن تستخدم إطارات الثلج ذات المسامير، ما لم يغيّر ITD التواريخ؟","o":["طوال السنة","في يناير وفبراير فقط","من 1 أكتوبر إلى 30 أبريل","من 1 مايو إلى 30 سبتمبر"],"h1":"هي للجزء البارد من السنة.","h2":"في Idaho، يجوز استخدام إطارات الثلج ذات المسامير من 1 أكتوبر إلى 30 أبريل، وأحيانًا يعدّل ITD التواريخ بسبب الطقس.","p":"صحيح. الإطارات ذات المسامير مسموحة من 1 أكتوبر إلى 30 أبريل."},"ref":{"doc":"ID","page":42}},{"id":"id-051","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, you hit a cow on open range outside city limits and your car is damaged. Who pays for your car?","o":["The cow's owner must pay","The cow's owner is not liable for your damage","The county pays for all repairs","The state road department pays"],"h1":"On open range, livestock are allowed to roam free.","h2":"In Idaho, if you hit livestock on open range, the animal's owner is not liable for damage to you or your car, and you may owe for the animal if you were careless.","p":"Right. On open range, the owner does not pay for your damage."},"es":{"q":"En Idaho, usted choca con una vaca en campo abierto (open range) fuera de la ciudad y su auto se daña. ¿Quién paga por su auto?","o":["El dueño de la vaca debe pagar","El dueño de la vaca no es responsable de sus daños","El condado paga todas las reparaciones","El departamento de carreteras del estado paga"],"h1":"En campo abierto, el ganado puede andar suelto.","h2":"En Idaho, si choca con ganado en campo abierto, el dueño del animal no es responsable de los daños a usted o a su auto, y usted puede tener que pagar por el animal si fue descuidado.","p":"Correcto. En campo abierto, el dueño no paga por sus daños."},"zh":{"q":"在 Idaho，你在城市范围外的开放牧场上撞到一头牛，你的车坏了。谁来付修车的钱？","o":["牛的主人必须付钱","牛的主人不用为你的损失负责","县政府付全部修理费","州道路部门付钱"],"h1":"在开放牧场上，牲畜可以自由走动。","h2":"在 Idaho，如果你在开放牧场上撞到牲畜，动物的主人不用为你或你的车的损失负责；如果你开车不小心，你可能还要赔这只动物。","p":"对。在开放牧场上，主人不用赔你的损失。"},"vi":{"q":"Ở Idaho, bạn đâm phải một con bò trên vùng chăn thả tự do ngoài ranh giới thành phố và xe bạn bị hư. Ai trả tiền cho xe của bạn?","o":["Chủ con bò phải trả","Chủ con bò không chịu trách nhiệm về thiệt hại của bạn","Quận trả toàn bộ tiền sửa xe","Sở đường bộ tiểu bang trả"],"h1":"Trên vùng chăn thả tự do, gia súc được phép đi lại tự do.","h2":"Ở Idaho, nếu bạn đâm phải gia súc trên vùng chăn thả tự do, chủ con vật không chịu trách nhiệm về thiệt hại cho bạn hoặc xe của bạn, và bạn có thể phải bồi thường con vật nếu bạn bất cẩn.","p":"Đúng. Trên vùng chăn thả tự do, chủ con vật không trả tiền thiệt hại cho bạn."},"tl":{"q":"Sa Idaho, nakabangga ka ng baka sa open range sa labas ng city limits at nasira ang kotse mo. Sino ang magbabayad para sa kotse mo?","o":["Dapat magbayad ang may-ari ng baka","Hindi mananagot ang may-ari ng baka sa pinsala mo","Babayaran ng county ang lahat ng pagkukumpuni","Magbabayad ang departamento ng kalsada ng state"],"h1":"Sa open range, puwedeng gumala nang malaya ang mga hayop.","h2":"Sa Idaho, kung nakabangga ka ng hayop sa open range, hindi mananagot ang may-ari ng hayop sa pinsala sa iyo o sa kotse mo, at puwede kang magbayad para sa hayop kung naging pabaya ka.","p":"Tama. Sa open range, hindi babayaran ng may-ari ang pinsala mo."},"ar":{"q":"في Idaho، صدمت بقرة في منطقة رعي مفتوحة خارج حدود المدينة وتضرّرت سيارتك. من يدفع ثمن إصلاح سيارتك؟","o":["يجب أن يدفع صاحب البقرة","صاحب البقرة غير مسؤول عن الضرر الذي لحق بك","المقاطعة تدفع كل الإصلاحات","دائرة الطرق في الولاية تدفع"],"h1":"في منطقة الرعي المفتوحة، يُسمح للماشية بأن تتجوّل بحرية.","h2":"في Idaho، إذا صدمت ماشية في منطقة رعي مفتوحة، فصاحب الحيوان غير مسؤول عن الضرر الذي لحق بك أو بسيارتك، وقد تدفع أنت ثمن الحيوان إذا كنت مهملًا.","p":"صحيح. في منطقة الرعي المفتوحة، لا يدفع صاحب الحيوان ثمن الضرر الذي لحق بك."},"ref":{"doc":"ID","page":108}},{"id":"id-052","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what is the youngest age to get a Driver Training permit and start a driver training program?","o":["14","15","14 and a half","16"],"h1":"It is before age 15.","h2":"In Idaho, you can get a Driver Training permit at 14 and a half, and it lets you drive only with your driver training instructor.","p":"Right. The Driver Training permit starts at 14 and a half."},"es":{"q":"En Idaho, ¿cuál es la edad mínima para obtener un permiso de capacitación (Driver Training permit) y empezar un curso de manejo?","o":["14 años","15 años","14 años y medio","16 años"],"h1":"Es antes de los 15 años.","h2":"En Idaho, puede obtener un permiso de capacitación a los 14 años y medio, y con él solo puede manejar junto a su instructor de manejo.","p":"Correcto. El permiso de capacitación empieza a los 14 años y medio."},"ref":{"doc":"ID","page":15}},{"id":"id-053","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a Class D Instruction Permit (for ages 17 and up) can be renewed without retaking the knowledge test. How many times?","o":["One time","Two times","Three times","As many times as needed"],"h1":"The permit lasts six months, and this kind of renewal is limited.","h2":"In Idaho, a Class D Instruction Permit can be renewed one time without a new knowledge test, if you passed the test within the past 12 months.","p":"Right. It can be renewed once without a new test."},"es":{"q":"En Idaho, un permiso de instrucción Clase D (para mayores de 17 años) se puede renovar sin repetir el examen de conocimientos. ¿Cuántas veces?","o":["Una vez","Dos veces","Tres veces","Todas las veces que necesite"],"h1":"El permiso dura seis meses, y este tipo de renovación es limitada.","h2":"En Idaho, el permiso de instrucción Clase D se puede renovar una vez sin un nuevo examen de conocimientos, si aprobó el examen en los últimos 12 meses.","p":"Correcto. Se puede renovar una vez sin otro examen."},"ref":{"doc":"ID","page":16}},{"id":"id-054","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, who must complete an approved motorcycle rider training course to get a motorcycle instruction permit?","o":["Only riders over 65","Only riders with a past crash","Only riders of three-wheelers","Anyone under 21"],"h1":"It depends on the rider's age, and it covers younger riders.","h2":"In Idaho, anyone under 21 must pass a knowledge test and complete an approved Motorcycle Rider Training Course for a motorcycle instruction permit.","p":"Right. Riders under 21 must take the training course."},"es":{"q":"En Idaho, ¿quién debe completar un curso aprobado de entrenamiento para motociclistas para obtener un permiso de instrucción de motocicleta?","o":["Solo los mayores de 65 años","Solo quien tuvo un choque antes","Solo quien maneja triciclos","Toda persona menor de 21 años"],"h1":"Depende de la edad, y se aplica a los conductores más jóvenes.","h2":"En Idaho, toda persona menor de 21 años debe aprobar un examen de conocimientos y completar un curso aprobado de entrenamiento para motociclistas para obtener el permiso de instrucción de motocicleta.","p":"Correcto. Los menores de 21 años deben tomar el curso."},"ref":{"doc":"ID","page":18}},{"id":"id-055","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, your driver's license expired 26 months ago. What tests must you take to get a license again?","o":["No tests, just a renewal fee","The knowledge and skills tests","Only a vision screening","Only the knowledge test"],"h1":"After 25 months, you are treated almost like a new driver.","h2":"In Idaho, if your license has been expired for 25 months or more, you must take the knowledge test and the skills test again.","p":"Right. After 25 months you take both tests again."},"es":{"q":"En Idaho, su licencia de conducir venció hace 26 meses. ¿Qué exámenes debe tomar para obtener una licencia otra vez?","o":["Ninguno, solo paga la renovación","El de conocimientos y el práctico de manejo","Solo un examen de la vista","Solo el de conocimientos"],"h1":"Después de 25 meses, lo tratan casi como a un conductor nuevo.","h2":"En Idaho, si su licencia lleva 25 meses o más vencida, debe tomar otra vez el examen de conocimientos y el examen práctico de manejo.","p":"Correcto. Después de 25 meses toma los dos exámenes otra vez."},"ref":{"doc":"ID","page":30}},{"id":"id-056","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how recent must your proof of Idaho residency be, such as a utility bill or a lease?","o":["Dated within 30 days","Dated within 5 years","Dated within 1 year","It can have any date"],"h1":"It is more than a few months, but not several years.","h2":"In Idaho, documents that prove where you live, like a lease or a utility bill, must be dated within one year.","p":"Right. Residency papers must be from the last year."},"es":{"q":"En Idaho, ¿qué tan reciente debe ser su prueba de residencia en Idaho, como una factura de servicios o un contrato de alquiler?","o":["Con fecha de los últimos 30 días","Con fecha de los últimos 5 años","Con fecha del último año","Puede tener cualquier fecha"],"h1":"Es más de unos meses, pero no varios años.","h2":"En Idaho, los documentos que prueban dónde vive, como un contrato de alquiler o una factura de servicios, deben tener fecha del último año.","p":"Correcto. La prueba de residencia debe ser del último año."},"ref":{"doc":"ID","page":24}},{"id":"id-057","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a parent signed as the liability signer for a 16-year-old's license. What happens if the parent withdraws consent?","o":["The teen pays a small fine","Nothing until the teen is 18","The teen retakes the skills test","The license is canceled"],"h1":"The signer's consent is what allows the teen to hold the license.","h2":"In Idaho, while a driver is under 18, the liability signer may withdraw consent at any time, and ITD then cancels the driver's license.","p":"Right. Without the signer's consent, the license is canceled."},"es":{"q":"En Idaho, un padre firmó como responsable (liability signer) para la licencia de un joven de 16 años. ¿Qué pasa si el padre retira su consentimiento?","o":["El joven paga una multa pequeña","Nada hasta que cumpla 18 años","El joven repite el examen práctico","La licencia se cancela"],"h1":"El consentimiento del firmante es lo que permite que el joven tenga la licencia.","h2":"En Idaho, mientras el conductor sea menor de 18 años, el firmante responsable puede retirar su consentimiento en cualquier momento, y entonces ITD cancela la licencia.","p":"Correcto. Sin el consentimiento del firmante, la licencia se cancela."},"ref":{"doc":"ID","page":26}},{"id":"id-058","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, you move to a new home address. How soon must you tell ITD?","o":["Within 30 days","Within 10 days","Within 6 months","Only when you renew"],"h1":"It is about one month.","h2":"In Idaho, you must notify ITD of a new address within 30 days, in person, online, by mail or by email.","p":"Right. You have 30 days to report a new address."},"es":{"q":"En Idaho, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar a ITD?","o":["En 30 días","En 10 días","En 6 meses","Solo cuando renueve"],"h1":"Es más o menos un mes.","h2":"En Idaho, debe avisar a ITD de su nueva dirección en 30 días, en persona, en línea, por correo o por correo electrónico.","p":"Correcto. Tiene 30 días para avisar su nueva dirección."},"ref":{"doc":"ID","page":29}},{"id":"id-059","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a driver 21 or older wants to renew a Class D license in person. How early before it expires can they renew?","o":["Up to 30 days early","Up to 25 months early","Up to 6 months early","Only after it expires"],"h1":"It is a long time, more than two years.","h2":"In Idaho, drivers 21 and older may renew a Class D license in person up to 25 months before the expiration date.","p":"Right. You can renew up to 25 months early."},"es":{"q":"En Idaho, un conductor de 21 años o más quiere renovar en persona su licencia Clase D. ¿Con cuánta anticipación puede renovarla?","o":["Hasta 30 días antes","Hasta 25 meses antes","Hasta 6 meses antes","Solo después de que venza"],"h1":"Es mucho tiempo, más de dos años.","h2":"En Idaho, los conductores de 21 años o más pueden renovar en persona la licencia Clase D hasta 25 meses antes de la fecha de vencimiento.","p":"Correcto. Puede renovar hasta 25 meses antes."},"ref":{"doc":"ID","page":30}},{"id":"id-060","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, how many errors can you make on the driving skills test and still pass?","o":["3 or fewer","6 or fewer","12 or fewer","20 or fewer"],"h1":"It is about a dozen.","h2":"In Idaho, you pass the driving skills test with 12 or fewer errors, but one critical driving error ends the test as a fail.","p":"Right. Twelve or fewer errors is a pass."},"es":{"q":"En Idaho, ¿cuántos errores puede cometer en el examen práctico de manejo y todavía aprobar?","o":["3 o menos","6 o menos","12 o menos","20 o menos"],"h1":"Es más o menos una docena.","h2":"En Idaho, aprueba el examen práctico de manejo con 12 errores o menos, pero un solo error crítico termina el examen como reprobado.","p":"Correcto. Con 12 errores o menos, aprueba."},"ref":{"doc":"ID","page":33}},{"id":"id-061","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver gets 8 to 11 points on their record in 12 months. What does ITD do?","o":["Suspends the license 30 days","Suspends the license 6 months","Takes no action at all","Sends a warning letter"],"h1":"At this level there is no suspension yet.","h2":"In Idaho, a driver with 8 to 11 points in any 12 months gets a warning letter; 12 or more points brings a suspension.","p":"Right. Eight to 11 points brings a warning letter."},"es":{"q":"En Idaho, un conductor acumula de 8 a 11 puntos en su historial en 12 meses. ¿Qué hace ITD?","o":["Suspende la licencia 30 días","Suspende la licencia 6 meses","No hace nada","Envía una carta de advertencia"],"h1":"En este nivel todavía no hay suspensión.","h2":"En Idaho, un conductor con 8 a 11 puntos en cualquier período de 12 meses recibe una carta de advertencia; con 12 puntos o más, hay suspensión.","p":"Correcto. De 8 a 11 puntos, recibe una carta de advertencia."},"ref":{"doc":"ID","page":123}},{"id":"id-062","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, an officer offers you a Traffic Safety Education Course when giving you a ticket. Up to how many points can it remove?","o":["Up to 4 points","Up to 1 point","Up to 8 points","Every point on your record"],"h1":"It is a little more than a defensive driving course removes.","h2":"In Idaho, a Traffic Safety Education Course offered by the officer at the stop can remove up to 4 points, and you must finish it within 45 days.","p":"Right. It can remove up to 4 points."},"es":{"q":"En Idaho, un oficial le ofrece un curso de educación en seguridad vial (Traffic Safety Education Course) al darle una multa. ¿Hasta cuántos puntos puede quitar?","o":["Hasta 4 puntos","Hasta 1 punto","Hasta 8 puntos","Todos los puntos de su historial"],"h1":"Es un poco más de lo que quita un curso de manejo defensivo.","h2":"En Idaho, el curso de educación en seguridad vial que ofrece el oficial en la parada puede quitar hasta 4 puntos, y debe terminarlo en 45 días.","p":"Correcto. Puede quitar hasta 4 puntos."},"ref":{"doc":"ID","page":123}},{"id":"id-063","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a licensed driver under 17 is convicted of a third moving violation. How long is the suspension?","o":["30 days","60 days","7 days","One year"],"h1":"It is twice as long as the suspension for a second violation.","h2":"In Idaho, a driver under 17 gets a 60-day suspension, with no driving at all, for a third or later moving violation conviction.","p":"Right. A third violation means a 60-day suspension."},"es":{"q":"En Idaho, un conductor con licencia menor de 17 años es condenado por una tercera infracción de tránsito en movimiento. ¿Cuánto dura la suspensión?","o":["30 días","60 días","7 días","Un año"],"h1":"Es el doble de la suspensión por una segunda infracción.","h2":"En Idaho, un conductor menor de 17 años recibe una suspensión de 60 días, sin poder manejar nada, por una tercera infracción o más.","p":"Correcto. Una tercera infracción significa 60 días de suspensión."},"ref":{"doc":"ID","page":125}},{"id":"id-064","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, an adult's license was suspended for failing an alcohol test. What is required for one year after the suspension ends?","o":["A new skills test each month","Driving in daylight only","An ignition interlock device","A passenger 21 or older"],"h1":"It is a device that checks your breath before the car starts.","h2":"In Idaho, after an administrative suspension for failing an alcohol test, you must have an ignition interlock device on any vehicle you drive for one year.","p":"Right. An ignition interlock is required for one year."},"es":{"q":"En Idaho, a un adulto le suspendieron la licencia por no pasar una prueba de alcohol. ¿Qué se exige durante un año después de la suspensión?","o":["Un examen práctico nuevo cada mes","Manejar solo de día","Un dispositivo de bloqueo de encendido","Un pasajero de 21 años o más"],"h1":"Es un aparato que revisa su aliento antes de que arranque el carro.","h2":"En Idaho, después de una suspensión administrativa por no pasar una prueba de alcohol, debe tener un dispositivo de bloqueo de encendido en cualquier vehículo que maneje durante un año.","p":"Correcto. Se exige el bloqueo de encendido durante un año."},"ref":{"doc":"ID","page":126}},{"id":"id-065","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver refuses an alcohol test for the second time within 10 years. How long is the license suspended?","o":["90 days","Six months","One month","Two years"],"h1":"It is twice as long as the suspension for a first refusal.","h2":"In Idaho, a second test refusal within 10 years brings a two-year suspension with no driving privileges at all.","p":"Right. A second refusal means two years."},"es":{"q":"En Idaho, un conductor se niega por segunda vez en 10 años a una prueba de alcohol. ¿Por cuánto tiempo se suspende la licencia?","o":["90 días","Seis meses","Un mes","Dos años"],"h1":"Es el doble de la suspensión por la primera negativa.","h2":"En Idaho, una segunda negativa a la prueba en 10 años trae una suspensión de dos años, sin ningún permiso para manejar.","p":"Correcto. Una segunda negativa significa dos años."},"ref":{"doc":"ID","page":127}},{"id":"id-066","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, your license was suspended for driving under the influence. For how long must you show proof of insurance (an SR-22) after you get it back?","o":["Three years","Six months","One year","Ten years"],"h1":"It is a few years.","h2":"In Idaho, after a suspension for a serious offense like DUI or reckless driving, you must keep an SR-22 proof of insurance on file for three years.","p":"Right. You need an SR-22 for three years."},"es":{"q":"En Idaho, le suspendieron la licencia por manejar bajo la influencia. ¿Por cuánto tiempo debe mostrar prueba de seguro (un SR-22) después de recuperarla?","o":["Tres años","Seis meses","Un año","Diez años"],"h1":"Son unos pocos años.","h2":"En Idaho, después de una suspensión por un delito grave como manejar bajo la influencia o manejar de forma imprudente, debe mantener un SR-22 como prueba de seguro por tres años.","p":"Correcto. Necesita un SR-22 por tres años."},"ref":{"doc":"ID","page":128}},{"id":"id-067","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a driver breaks the no-insurance law for the first time. How long must they file proof of financial responsibility?","o":["Three years","One year","Five years","30 days"],"h1":"A second offense within five years makes it three times longer.","h2":"In Idaho, a first violation of the no-insurance law means you must file proof of financial responsibility for one year.","p":"Right. A first no-insurance offense means one year of proof."},"es":{"q":"En Idaho, un conductor viola por primera vez la ley de seguro obligatorio. ¿Por cuánto tiempo debe presentar prueba de responsabilidad financiera?","o":["Tres años","Un año","Cinco años","30 días"],"h1":"Una segunda falta en cinco años lo hace tres veces más largo.","h2":"En Idaho, la primera violación de la ley de seguro obligatorio significa que debe presentar prueba de responsabilidad financiera por un año.","p":"Correcto. La primera falta por no tener seguro significa un año de prueba."},"ref":{"doc":"ID","page":128}},{"id":"id-068","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what is the most jail time for a first DUI conviction?","o":["Up to ten days","Up to five years","Up to six months","No jail time at all"],"h1":"It is less than one year.","h2":"In Idaho, a first DUI conviction can bring up to six months in jail, a fine of up to $1,000, and a license suspension of 90 to 180 days (one year if the driver is under 21).","p":"Right. A first DUI can mean up to six months in jail."},"es":{"q":"En Idaho, ¿cuál es el máximo de cárcel por una primera condena por manejar bajo la influencia (DUI)?","o":["Hasta diez días","Hasta cinco años","Hasta seis meses","Ningún tiempo de cárcel"],"h1":"Es menos de un año.","h2":"En Idaho, una primera condena por DUI puede traer hasta seis meses de cárcel, una multa de hasta $1,000 y una suspensión de la licencia de 90 a 180 días (un año si el conductor es menor de 21).","p":"Correcto. Un primer DUI puede significar hasta seis meses de cárcel."},"ref":{"doc":"ID","page":132}},{"id":"id-069","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver is convicted of DUI for the third time within 10 years. What kind of crime is it?","o":["An infraction","A misdemeanor","A civil matter only","A felony"],"h1":"It is the most serious kind of crime.","h2":"In Idaho, a third DUI conviction within 10 years is a felony, with jail of 30 days to ten years for adults.","p":"Right. A third DUI in 10 years is a felony."},"es":{"q":"En Idaho, un conductor es condenado por tercera vez por DUI en 10 años. ¿Qué tipo de delito es?","o":["Una infracción","Un delito menor","Solo un asunto civil","Un delito grave (felony)"],"h1":"Es el tipo de delito más serio.","h2":"En Idaho, una tercera condena por DUI en 10 años es un delito grave (felony), con cárcel de 30 días a diez años para adultos.","p":"Correcto. Un tercer DUI en 10 años es un delito grave."},"ref":{"doc":"ID","page":132}},{"id":"id-070","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, an uninsured driver damaged your car and has not paid the court judgment. How long can ITD suspend that driver's license?","o":["Until paid, or up to 6 years","For 30 days only","For 1 year only","It cannot be suspended"],"h1":"It can last until you get your money, but there is a limit of several years.","h2":"In Idaho, after a court judgment, ITD may suspend an uninsured driver's license until you are paid, or for up to six years.","p":"Right. It can last until you are paid, up to six years."},"es":{"q":"En Idaho, un conductor sin seguro dañó su carro y no ha pagado lo que ordenó el tribunal. ¿Por cuánto tiempo puede ITD suspender la licencia de ese conductor?","o":["Hasta que pague, o hasta 6 años","Solo por 30 días","Solo por 1 año","No se puede suspender"],"h1":"Puede durar hasta que usted reciba su dinero, pero hay un límite de varios años.","h2":"En Idaho, después de una sentencia del tribunal, ITD puede suspender la licencia de un conductor sin seguro hasta que le pague a usted, o hasta por seis años.","p":"Correcto. Puede durar hasta que le paguen, hasta seis años."},"ref":{"doc":"ID","page":119}},{"id":"id-071","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how often must a passenger car pass a state safety inspection?","o":["Once every single year","There is no yearly inspection","Once every two years","Each time the car is sold"],"h1":"Idaho leaves this to the driver, but police can still stop an unsafe car.","h2":"Idaho does not require a yearly safety inspection, but an officer can give you a ticket if your vehicle is unsafe or missing equipment.","p":"Right. Idaho has no yearly safety inspection."},"es":{"q":"En Idaho, ¿cada cuánto debe pasar un carro de pasajeros una inspección de seguridad estatal?","o":["Una vez cada año","No hay inspección anual","Una vez cada dos años","Cada vez que se vende el carro"],"h1":"Idaho deja esto al conductor, pero la policía puede detener un carro inseguro.","h2":"Idaho no exige una inspección de seguridad anual, pero un oficial puede multarlo si su vehículo no es seguro o le falta equipo.","p":"Correcto. Idaho no tiene inspección de seguridad anual."},"ref":{"doc":"ID","page":38}},{"id":"id-072","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, the foot brakes must stop a car going 20 mph on dry pavement within what distance?","o":["10 feet","55 feet","25 feet","100 feet"],"h1":"The parking brake is allowed a longer distance, 55 feet.","h2":"In Idaho, foot brakes must stop a car going 20 mph on dry pavement within 25 feet; the parking brake must do it within 55 feet.","p":"Right. Foot brakes must stop within 25 feet."},"es":{"q":"En Idaho, ¿dentro de qué distancia deben los frenos de pie detener un carro que va a 20 mph en pavimento seco?","o":["10 pies","55 pies","25 pies","100 pies"],"h1":"Al freno de mano se le permite una distancia mayor, 55 pies.","h2":"En Idaho, los frenos de pie deben detener un carro que va a 20 mph en pavimento seco dentro de 25 pies; el freno de mano debe hacerlo dentro de 55 pies.","p":"Correcto. Los frenos de pie deben detenerlo dentro de 25 pies."},"ref":{"doc":"ID","page":38}},{"id":"id-073","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, your load sticks out 4 feet or more past the back of your vehicle in the daytime. What must you put on the end of it?","o":["A white flag at least 6 inches square","An orange cone tied to the load","A yellow sign that says WIDE LOAD","A red flag at least 18 inches square"],"h1":"It is a flag, and its color means danger or stop.","h2":"In Idaho, a load that extends 4 feet or more behind a vehicle needs a red flag at least 18 inches square at the end, and a red light at night.","p":"Right. Use a red flag at least 18 inches square."},"es":{"q":"En Idaho, su carga sobresale 4 pies o más por detrás de su vehículo durante el día. ¿Qué debe poner en la punta?","o":["Una bandera blanca de al menos 6 pulgadas por lado","Un cono anaranjado amarrado a la carga","Un letrero amarillo que diga WIDE LOAD","Una bandera roja de al menos 18 pulgadas por lado"],"h1":"Es una bandera, y su color significa peligro o alto.","h2":"En Idaho, una carga que sobresale 4 pies o más por detrás necesita una bandera roja de al menos 18 pulgadas por lado en la punta, y una luz roja de noche.","p":"Correcto. Use una bandera roja de al menos 18 pulgadas por lado."},"ref":{"doc":"ID","page":43}},{"id":"id-074","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, you leave your car unattended on the paved shoulder of a highway. By when must it be moved to avoid being towed?","o":["Before dark","Within 72 hours","Within one week","Only if it blocks a lane"],"h1":"A car on the shoulder is most dangerous when it is hard to see.","h2":"In Idaho, an unattended vehicle on the paved shoulder must be removed before dark, or it can be towed at the owner's cost.","p":"Right. Move it before dark."},"es":{"q":"En Idaho, usted deja su carro solo en el acotamiento pavimentado de una carretera. ¿Para cuándo debe moverlo para que no se lo lleve la grúa?","o":["Antes de que oscurezca","En 72 horas","En una semana","Solo si bloquea un carril"],"h1":"Un carro en el acotamiento es más peligroso cuando es difícil verlo.","h2":"En Idaho, un vehículo sin conductor en el acotamiento pavimentado debe moverse antes de que oscurezca, o la grúa puede llevárselo a costa del dueño.","p":"Correcto. Muévalo antes de que oscurezca."},"ref":{"doc":"ID","page":93}},{"id":"id-075","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how far behind a snowplow truck should you stay?","o":["One car length at any speed","Two car lengths for every 10 mph","50 feet at any speed","Half a car length for every 10 mph"],"h1":"The space grows with your speed, and it is more than one car length per 10 mph.","h2":"In Idaho, stay two car lengths behind a snowplow for every 10 mph you drive, because the sand it spreads can damage your car.","p":"Right. Two car lengths for every 10 mph."},"es":{"q":"En Idaho, ¿a qué distancia debe mantenerse detrás de un camión quitanieves?","o":["Un largo de carro a cualquier velocidad","Dos largos de carro por cada 10 mph","50 pies a cualquier velocidad","Medio largo de carro por cada 10 mph"],"h1":"El espacio aumenta con su velocidad, y es más de un largo de carro por cada 10 mph.","h2":"En Idaho, quédese dos largos de carro detrás de un quitanieves por cada 10 mph de su velocidad, porque la arena que esparce puede dañar su carro.","p":"Correcto. Dos largos de carro por cada 10 mph."},"ref":{"doc":"ID","page":110}},{"id":"id-076","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, your car breaks down on the highway and you have emergency flares. Where should you place them?","o":["Right next to your car","10 to 20 feet in front of your car","200 to 300 feet behind your car","Half a mile behind your car"],"h1":"They warn drivers coming up behind you, with time to react.","h2":"In Idaho, if your car stalls and you have flares, place them 200 to 300 feet behind your car to warn other drivers.","p":"Right. Put flares 200 to 300 feet behind your car."},"es":{"q":"En Idaho, su carro se descompone en la carretera y usted tiene bengalas de emergencia. ¿Dónde debe ponerlas?","o":["Justo al lado de su carro","De 10 a 20 pies delante de su carro","De 200 a 300 pies detrás de su carro","A media milla detrás de su carro"],"h1":"Avisan a los conductores que vienen detrás, con tiempo para reaccionar.","h2":"En Idaho, si su carro se descompone y tiene bengalas, póngalas de 200 a 300 pies detrás de su carro para avisar a los demás conductores.","p":"Correcto. Ponga las bengalas de 200 a 300 pies detrás de su carro."},"ref":{"doc":"ID","page":117}},{"id":"id-077","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, you stop at a crash and help an injured person in good faith. What does the Good Samaritan Law do for you?","o":["Makes you pay for their care","Requires a first aid card","Makes you liable for the crash","Protects you from civil lawsuits"],"h1":"The law is meant to encourage people to help.","h2":"In Idaho, the Good Samaritan Law protects you from civil liability when you help an injured person in good faith.","p":"Right. It protects you from being sued for helping."},"es":{"q":"En Idaho, usted se detiene en un choque y ayuda de buena fe a una persona herida. ¿Qué hace por usted la ley del Buen Samaritano?","o":["Lo obliga a pagar su atención","Le exige una tarjeta de primeros auxilios","Lo hace responsable del choque","Lo protege de demandas civiles"],"h1":"La ley busca animar a la gente a ayudar.","h2":"En Idaho, la ley del Buen Samaritano lo protege de responsabilidad civil cuando ayuda de buena fe a una persona herida.","p":"Correcto. Lo protege de demandas por ayudar."},"ref":{"doc":"ID","page":121}},{"id":"id-078","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, what is the top speed on a state highway when no other limit is posted?","o":["65 mph","55 mph","75 mph","80 mph"],"h1":"It is 10 mph less than the interstate limit.","h2":"In Idaho, the limit on state highways is 65 mph unless signs say otherwise; 70 mph is allowed only where posted.","p":"Right. State highways are 65 mph unless posted."},"es":{"q":"En Idaho, ¿cuál es la velocidad máxima en una carretera estatal cuando no hay otro límite señalado?","o":["65 mph","55 mph","75 mph","80 mph"],"h1":"Es 10 mph menos que el límite de la autopista interestatal.","h2":"En Idaho, el límite en las carreteras estatales es 65 mph, a menos que los letreros digan otra cosa; 70 mph se permite solo donde está señalado.","p":"Correcto. Las carreteras estatales son de 65 mph si no hay otro letrero."},"ref":{"doc":"ID","page":68}},{"id":"id-079","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, you are in the far left lane, driving slower than the traffic behind you. What does the law say?","o":["You may stay if you keep to the limit","Do not stay there and hold up traffic","Turn on your hazard lights there","Drive 10 mph below the limit there"],"h1":"The left lane is for faster traffic and passing.","h2":"In Idaho, you may not drive in the far left lane for a time that holds up other traffic moving at a lawful speed.","p":"Right. Do not block traffic in the far left lane."},"es":{"q":"En Idaho, usted va en el carril de la extrema izquierda, más despacio que el tráfico que viene detrás. ¿Qué dice la ley?","o":["Puede quedarse si respeta el límite","No se quede ahí retrasando el tráfico","Encienda sus luces de emergencia ahí","Maneje 10 mph menos que el límite ahí"],"h1":"El carril izquierdo es para el tráfico más rápido y para rebasar.","h2":"En Idaho, no puede manejar en el carril de la extrema izquierda por un tiempo que retrase al tráfico que va a una velocidad legal.","p":"Correcto. No bloquee el tráfico en el carril de la extrema izquierda."},"ref":{"doc":"ID","page":69}},{"id":"id-080","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, you plan to change lanes on a freeway. How long before you move must your turn signal be on?","o":["At least 1 second","At least 30 seconds","At least 5 seconds","Only as you move over"],"h1":"On fast roads the rule is counted in seconds, a short handful of them.","h2":"In Idaho, on freeways and highways you must signal at least five seconds before you turn or change lanes; in business or residential areas, at least 100 feet.","p":"Right. Signal at least five seconds on the freeway."},"es":{"q":"En Idaho, usted piensa cambiar de carril en una autopista. ¿Con cuánta anticipación debe encender la direccional?","o":["Al menos 1 segundo antes","Al menos 30 segundos antes","Al menos 5 segundos antes","Solo al momento de cambiarse"],"h1":"En las vías rápidas la regla se cuenta en segundos, unos pocos.","h2":"En Idaho, en autopistas y carreteras debe señalar al menos cinco segundos antes de girar o cambiar de carril; en zonas comerciales o residenciales, al menos 100 pies antes.","p":"Correcto. Señale al menos cinco segundos antes en la autopista."},"ref":{"doc":"ID","page":72}},{"id":"id-081","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, you may not make a U-turn on a curve or near the top of a hill if other drivers cannot see you within what distance?","o":["50 feet","150 feet","1 mile","500 feet"],"h1":"It is about a tenth of a mile.","h2":"In Idaho, U-turns are not allowed on a curve or near a hilltop where drivers from either direction cannot see your vehicle within 500 feet.","p":"Right. Others must be able to see you within 500 feet."},"es":{"q":"En Idaho, no puede hacer una vuelta en U en una curva o cerca de la cima de una colina si los otros conductores no pueden ver su vehículo a cierta distancia. ¿Cuál es esa distancia?","o":["50 pies","150 pies","1 milla","500 pies"],"h1":"Es más o menos una décima de milla.","h2":"En Idaho, no se permiten vueltas en U en una curva o cerca de la cima de una colina donde los conductores de cualquier dirección no puedan ver su vehículo dentro de 500 pies.","p":"Correcto. Los demás deben poder verlo dentro de 500 pies."},"ref":{"doc":"ID","page":73}},{"id":"id-082","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, you are passing on a two-lane road and a car is coming toward you. You must finish the pass before you get within what distance of it?","o":["200 feet","25 feet","50 feet","75 feet"],"h1":"It is more than the length of ten cars.","h2":"In Idaho, you must complete a pass before you come within 200 feet of oncoming traffic.","p":"Right. Finish the pass before you are within 200 feet."},"es":{"q":"En Idaho, usted está rebasando en una carretera de dos carriles y viene un carro de frente. ¿Antes de qué distancia de ese carro debe terminar de rebasar?","o":["200 pies","25 pies","50 pies","75 pies"],"h1":"Es más que el largo de diez carros.","h2":"En Idaho, debe terminar de rebasar antes de estar a 200 pies del tráfico que viene de frente.","p":"Correcto. Termine de rebasar antes de estar a 200 pies."},"ref":{"doc":"ID","page":78}},{"id":"id-083","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, you drive slowly on a two-lane highway and cars line up behind you. When must you pull off where safe to let them pass?","o":["When 10 or more are behind you","When 3 or more are behind you","Only if an officer tells you","Never, if you obey the limit"],"h1":"It takes only a few cars.","h2":"In Idaho, a slow vehicle that is holding up three or more vehicles in a rural area or on a two-lane highway must turn off where safe to let them pass.","p":"Right. Pull off when three or more vehicles are waiting."},"es":{"q":"En Idaho, usted maneja despacio en una carretera de dos carriles y se forma una fila de carros detrás. ¿Cuándo debe salirse donde sea seguro para dejarlos pasar?","o":["Cuando hay 10 o más detrás","Cuando hay 3 o más detrás","Solo si un oficial se lo dice","Nunca, si respeta el límite"],"h1":"Bastan unos pocos carros.","h2":"En Idaho, un vehículo lento que retrasa a tres o más vehículos en una zona rural o en una carretera de dos carriles debe salirse donde sea seguro para dejarlos pasar.","p":"Correcto. Sálgase cuando hay tres o más vehículos esperando."},"ref":{"doc":"ID","page":79}},{"id":"id-084","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, when you park parallel on a public road, how close to the curb or edge of the road must you be?","o":["Within 24 inches","Within 3 feet","Within 18 inches","Within 4 feet"],"h1":"It is a foot and a half.","h2":"In Idaho, you must park parallel to the curb or road edge, within 18 inches of it, facing the same way as traffic on your side.","p":"Right. Park within 18 inches of the curb."},"es":{"q":"En Idaho, cuando se estaciona en paralelo en una vía pública, ¿qué tan cerca de la acera o del borde del camino debe quedar?","o":["A 24 pulgadas o menos","A 3 pies o menos","A 18 pulgadas o menos","A 4 pies o menos"],"h1":"Es un pie y medio.","h2":"En Idaho, debe estacionarse en paralelo a la acera o al borde del camino, a 18 pulgadas o menos, en la misma dirección que el tráfico de su lado.","p":"Correcto. Estaciónese a 18 pulgadas o menos de la acera."},"ref":{"doc":"ID","page":80}},{"id":"id-085","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, what is the closest you may park to railroad tracks?","o":["10 feet away","25 feet away","100 feet away","50 feet away"],"h1":"It is more than the no-parking distance for a crosswalk.","h2":"In Idaho, parking is not allowed within 50 feet of railroad tracks.","p":"Right. Stay at least 50 feet from railroad tracks."},"es":{"q":"En Idaho, ¿qué tan cerca de las vías del tren puede estacionarse, como mínimo?","o":["A 10 pies","A 25 pies","A 100 pies","A 50 pies"],"h1":"Es más que la distancia prohibida junto a un cruce peatonal.","h2":"En Idaho, no se permite estacionarse a menos de 50 pies de las vías del tren.","p":"Correcto. Quédese al menos a 50 pies de las vías del tren."},"ref":{"doc":"ID","page":81}},{"id":"id-086","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, what is the closest you may park to a crosswalk?","o":["20 feet away","5 feet away","10 feet away","50 feet away"],"h1":"It is a bit more than the distance for a fire hydrant.","h2":"In Idaho, parking is not allowed within 20 feet of a crosswalk.","p":"Right. Stay at least 20 feet from a crosswalk."},"es":{"q":"En Idaho, ¿qué tan cerca de un cruce peatonal puede estacionarse, como mínimo?","o":["A 20 pies","A 5 pies","A 10 pies","A 50 pies"],"h1":"Es un poco más que la distancia para un hidrante.","h2":"En Idaho, no se permite estacionarse a menos de 20 pies de un cruce peatonal.","p":"Correcto. Quédese al menos a 20 pies de un cruce peatonal."},"ref":{"doc":"ID","page":81}},{"id":"id-087","scope":"ID","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Idaho, you are on a one-way street at a steady red light and want to turn left onto another one-way street. What may you do, unless a sign forbids it?","o":["Turn without stopping if it is clear","Turn after a full stop and yielding","Never turn left on a red light","Turn only with a green arrow"],"h1":"It works much like a right turn on red.","h2":"In Idaho, you may turn left on a steady red light from a one-way street onto a one-way street after you stop and yield to cross traffic, unless a sign says no.","p":"Right. Stop, yield, then you may turn left onto the one-way street."},"es":{"q":"En Idaho, usted está en una calle de un solo sentido con la luz roja fija y quiere girar a la izquierda hacia otra calle de un solo sentido. ¿Qué puede hacer, si ningún letrero lo prohíbe?","o":["Girar sin parar si no viene nadie","Girar después de parar por completo y ceder el paso","Nunca girar a la izquierda con luz roja","Girar solo con flecha verde"],"h1":"Funciona casi como girar a la derecha con luz roja.","h2":"En Idaho, puede girar a la izquierda con luz roja fija de una calle de un solo sentido a otra de un solo sentido después de parar y ceder el paso al tráfico que cruza, a menos que un letrero lo prohíba.","p":"Correcto. Pare, ceda el paso y puede girar a la izquierda hacia la calle de un solo sentido."},"ref":{"doc":"ID","page":73}},{"id":"id-088","scope":"ID","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Idaho, you must stop for a train at a railroad crossing. Where should you stop?","o":["1 to 5 feet from the nearest rail","5 to 10 feet from the nearest rail","15 to 50 feet from the nearest rail","100 to 200 feet from the nearest rail"],"h1":"Not too close to the train, and not so far back that you cannot see.","h2":"In Idaho, when you must stop at a railroad crossing, stop within 50 feet but no closer than 15 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Idaho, debe detenerse por un tren en un cruce de ferrocarril. ¿Dónde debe parar?","o":["De 1 a 5 pies del riel más cercano","De 5 a 10 pies del riel más cercano","De 15 a 50 pies del riel más cercano","De 100 a 200 pies del riel más cercano"],"h1":"Ni muy cerca del tren, ni tan lejos que no pueda ver.","h2":"En Idaho, cuando debe detenerse en un cruce de ferrocarril, pare a no más de 50 pies y a no menos de 15 pies del riel más cercano.","p":"Correcto. Pare de 15 a 50 pies del riel más cercano."},"ref":{"doc":"ID","page":60}},{"id":"id-089","scope":"ID","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Idaho, a bicyclist going straight comes to a steady red light. What may the bicyclist do?","o":["Ride through without slowing down","Wait for the green light every time","Get off and walk across only","Stop, yield, then go ahead with care"],"h1":"Idaho gives bicyclists a special rule at red lights, but they still must stop first.","h2":"In Idaho, a bicyclist may go through a steady red light after stopping and yielding to vehicles already in or close to the intersection.","p":"Right. A bicyclist may stop, yield, then go through with care."},"es":{"q":"En Idaho, un ciclista que va derecho llega a una luz roja fija. ¿Qué puede hacer el ciclista?","o":["Pasar sin bajar la velocidad","Esperar la luz verde siempre","Bajarse y cruzar caminando solamente","Parar, ceder el paso y luego seguir con cuidado"],"h1":"Idaho tiene una regla especial para ciclistas en la luz roja, pero igual deben parar primero.","h2":"En Idaho, un ciclista puede pasar una luz roja fija después de parar y ceder el paso a los vehículos que ya están en el cruce o cerca de él.","p":"Correcto. El ciclista puede parar, ceder el paso y seguir con cuidado."},"ref":{"doc":"ID","page":98}},{"id":"id-090","scope":"ID","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Idaho, a funeral procession is going through an intersection and your light turns green. What should you do?","o":["Yield and do not cut into the line","Go, because your light is green","Join the end of the procession","Honk so its drivers see you"],"h1":"The color of the traffic light does not change this rule.","h2":"In Idaho, always give a funeral procession the right-of-way, and do not drive between or join its vehicles unless a police officer allows it, whatever the light shows.","p":"Right. Yield to the procession and do not cut in."},"es":{"q":"En Idaho, un cortejo fúnebre está pasando por un cruce y su luz cambia a verde. ¿Qué debe hacer?","o":["Ceder el paso y no meterse en la fila","Avanzar, porque su luz está en verde","Unirse al final del cortejo","Tocar la bocina para que lo vean"],"h1":"El color del semáforo no cambia esta regla.","h2":"En Idaho, siempre ceda el paso a un cortejo fúnebre, y no se meta entre sus vehículos ni se una a ellos a menos que un policía lo permita, sin importar el color de la luz.","p":"Correcto. Ceda el paso al cortejo y no se meta en la fila."},"ref":{"doc":"ID","page":78}},{"id":"id-091","scope":"ID","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Idaho, ranch workers are moving a herd of cattle across the highway ahead of you. Who has the right-of-way?","o":["You, the driver","The livestock","Whoever got there first","Only large trucks"],"h1":"Idaho law protects animals that are being moved across a road.","h2":"In Idaho, livestock under controlled movement across a highway have the right-of-way, so slow down and cooperate with the workers.","p":"Right. The herd has the right-of-way."},"es":{"q":"En Idaho, unos trabajadores de un rancho están cruzando una manada de ganado por la carretera delante de usted. ¿Quién tiene el derecho de paso?","o":["Usted, el conductor","El ganado","Quien llegó primero","Solo los camiones grandes"],"h1":"La ley de Idaho protege a los animales que están siendo cruzados por un camino.","h2":"En Idaho, el ganado que se mueve de forma controlada por una carretera tiene el derecho de paso, así que baje la velocidad y coopere con los trabajadores.","p":"Correcto. La manada tiene el derecho de paso."},"ref":{"doc":"ID","page":108}},{"id":"id-092","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a teen is driving on a supervised instruction permit with a licensed adult beside them. Who else may sit in the front seat?","o":["One friend under 17","No one else","One family member of any age","Anyone wearing a seat belt"],"h1":"Think about keeping the supervisor's attention on the new driver.","h2":"In Idaho, during the supervised instruction period, the licensed adult sits beside the driver and no other passengers are allowed in the front seat.","p":"Right. Only the driver and the supervisor sit in front."},"es":{"q":"En Idaho, un adolescente maneja con un permiso de instrucción supervisada y un adulto con licencia a su lado. ¿Quién más puede ir en el asiento delantero?","o":["Un amigo menor de 17 años","Nadie más","Un familiar de cualquier edad","Cualquier persona con cinturón puesto"],"h1":"Piense en que el supervisor debe prestar toda su atención al nuevo conductor.","h2":"En Idaho, durante el periodo de instrucción supervisada, el adulto con licencia va al lado del conductor y no se permiten otros pasajeros en el asiento delantero.","p":"Correcto. Adelante solo van el conductor y el supervisor."},"ref":{"doc":"ID","page":19}},{"id":"id-093","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, you apply for an Idaho driver's license while you still hold a license from another state. What happens to the other license?","o":["You may keep both licenses","You must mail it back yourself","You must surrender it","It stays valid for one more year"],"h1":"Idaho follows the idea of one driver, one license, one record.","h2":"In Idaho, you must surrender any driver's license or ID card from another state when you apply for an Idaho driver's license.","p":"Right. You give up the other state's license."},"es":{"q":"En Idaho, usted solicita una licencia de Idaho y todavía tiene una licencia de otro estado. ¿Qué pasa con la otra licencia?","o":["Puede quedarse con las dos","Debe enviarla por correo usted mismo","Debe entregarla","Sigue siendo válida un año más"],"h1":"Idaho sigue la idea de un conductor, una licencia, un historial.","h2":"En Idaho, debe entregar cualquier licencia de conducir o tarjeta de identificación de otro estado cuando solicita una licencia de Idaho.","p":"Correcto. Usted entrega la licencia del otro estado."},"ref":{"doc":"ID","page":12}},{"id":"id-094","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a college student keeps residency in their home state and has a valid license from there. Do they need an Idaho license?","o":["No, not while they keep that residency","Yes, within 30 days of arriving","Yes, before the first school term ends","Only if they own a car in Idaho"],"h1":"Students who still claim another state as home are treated differently from new residents.","h2":"In Idaho, college students with a valid license from another state who claim residency in that state do not have to get an Idaho driver's license.","p":"Right. They can keep driving on their home-state license."},"es":{"q":"En Idaho, un estudiante universitario mantiene su residencia en su estado de origen y tiene una licencia válida de allí. ¿Necesita una licencia de Idaho?","o":["No, mientras mantenga esa residencia","Sí, dentro de los 30 días de llegar","Sí, antes de que termine el primer semestre","Solo si tiene un auto en Idaho"],"h1":"Los estudiantes que siguen declarando otro estado como su hogar se tratan distinto a los nuevos residentes.","h2":"En Idaho, los estudiantes universitarios con una licencia válida de otro estado que declaran su residencia en ese estado no tienen que sacar una licencia de Idaho.","p":"Correcto. Pueden seguir manejando con la licencia de su estado."},"ref":{"doc":"ID","page":4}},{"id":"id-095","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a driver is not a U.S. citizen or permanent resident, and their immigration papers show an end date. When does their license expire?","o":["After eight years, no matter what","Only on the day they leave the country","On their next birthday, every year","End of lawful stay or four years, if sooner"],"h1":"It depends on the federal papers the driver shows.","h2":"In Idaho, a non-citizen's license expires at the end of their lawful stay shown on their federal papers, or in four years, whichever comes first.","p":"Right. It is the end of the lawful stay or four years, whichever is sooner."},"es":{"q":"En Idaho, un conductor no es ciudadano ni residente permanente de EE. UU., y sus documentos de inmigración muestran una fecha final. ¿Cuándo vence su licencia?","o":["A los ocho años, sin importar nada","Solo el día en que salga del país","En su próximo cumpleaños, cada año","Fin de su estadía legal o cuatro años, si es antes"],"h1":"Depende de los documentos federales que muestra el conductor.","h2":"En Idaho, la licencia de una persona que no es ciudadana vence al final de su estadía legal según sus documentos federales, o en cuatro años, lo que ocurra primero.","p":"Correcto. Es el fin de la estadía legal o cuatro años, lo que llegue primero."},"ref":{"doc":"ID","page":25}},{"id":"id-096","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a 17-year-old applying for a license is married. Who may sign as their liability signer?","o":["Any friend who is 21 or older","Their spouse, if the spouse is at least 18","Their driving instructor","No one; married teens need no signer"],"h1":"Marriage adds one more person who can take on this duty.","h2":"In Idaho, if an applicant under 18 is married, their spouse may sign for them, as long as the spouse is at least 18 years old.","p":"Right. A spouse who is 18 or older may sign."},"es":{"q":"En Idaho, un joven de 17 años que solicita una licencia está casado. ¿Quién puede firmar como su responsable (liability signer)?","o":["Cualquier amigo de 21 años o más","Su cónyuge, si tiene al menos 18 años","Su instructor de manejo","Nadie; los jóvenes casados no necesitan firmante"],"h1":"El matrimonio agrega una persona más que puede asumir esta responsabilidad.","h2":"En Idaho, si un solicitante menor de 18 años está casado, su cónyuge puede firmar por él, siempre que el cónyuge tenga al menos 18 años.","p":"Correcto. Puede firmar un cónyuge de 18 años o más."},"ref":{"doc":"ID","page":26}},{"id":"id-097","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, what school paper must an applicant under 18 bring to get a license?","o":["A report card with a B average","A letter from a school coach","Proof of school enrollment and attendance, or graduation","Proof of a passed driver's ed final exam"],"h1":"It shows the teen is following the state's school attendance rules.","h2":"In Idaho, an applicant under 18 must show proof of enrollment and attendance in a recognized high school or equivalent program, or proof of graduation.","p":"Right. They must show they are in school or have graduated."},"es":{"q":"En Idaho, ¿qué documento escolar debe llevar un solicitante menor de 18 años para obtener una licencia?","o":["Una boleta de calificaciones con promedio B","Una carta de un entrenador de la escuela","Prueba de inscripción y asistencia escolar, o de graduación","Prueba de aprobar el examen final de manejo"],"h1":"Muestra que el joven cumple las reglas estatales de asistencia escolar.","h2":"En Idaho, un solicitante menor de 18 años debe mostrar prueba de inscripción y asistencia en una escuela secundaria reconocida o programa equivalente, o prueba de graduación.","p":"Correcto. Debe mostrar que estudia o que ya se graduó."},"ref":{"doc":"ID","page":26}},{"id":"id-098","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, you let a friend with no driver's license drive your car, and they crash. Who is responsible for the damage?","o":["Both the driver and you, the owner","Only the driver","Only your insurance company","No one, if it was an accident"],"h1":"Giving permission to an unlicensed driver carries a risk for the owner too.","h2":"In Idaho, if you allow an unlicensed person to drive your vehicle and there is a crash, both the driver and the owner are responsible for the damage, injury or death.","p":"Right. The owner shares the responsibility."},"es":{"q":"En Idaho, usted deja que un amigo sin licencia maneje su auto, y él choca. ¿Quién es responsable de los daños?","o":["Tanto el conductor como usted, el dueño","Solo el conductor del auto","Solo su compañía de seguros","Nadie, si fue un accidente"],"h1":"Dar permiso a un conductor sin licencia también es un riesgo para el dueño.","h2":"En Idaho, si usted permite que una persona sin licencia maneje su vehículo y hay un choque, tanto el conductor como el dueño son responsables de los daños, lesiones o muertes.","p":"Correcto. El dueño comparte la responsabilidad."},"ref":{"doc":"ID","page":30}},{"id":"id-099","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, when is a vision screening required for a driver's license?","o":["Only at the first license","Only after age 70","Only if you wear glasses","At every renewal"],"h1":"It is not a one-time check.","h2":"In Idaho, a vision screening is required at all license renewals, and a driver who fails may be asked to see an eye doctor.","p":"Right. Your vision is checked every time you renew."},"es":{"q":"En Idaho, ¿cuándo se requiere un examen de la vista para la licencia de conducir?","o":["Solo en la primera licencia","Solo después de los 70 años","Solo si usa anteojos","En cada renovación"],"h1":"No es una revisión de una sola vez.","h2":"En Idaho, se requiere un examen de la vista en todas las renovaciones de licencia, y a quien no lo pase se le puede pedir que vea a un oculista.","p":"Correcto. Se revisa su vista cada vez que renueva."},"ref":{"doc":"ID","page":30}},{"id":"id-100","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, a driver on active military duty is out of state when their license expires. How many extensions may they get during active duty?","o":["Only one extension","Two extensions at most","As many as needed","None during active duty"],"h1":"Military families get more room than other drivers.","h2":"In Idaho, active-duty military members and their dependents may apply for as many license extensions as needed during active duty, at $10 per application.","p":"Right. They may get as many extensions as they need."},"es":{"q":"En Idaho, un conductor en servicio militar activo está fuera del estado cuando vence su licencia. ¿Cuántas prórrogas puede obtener durante el servicio activo?","o":["Solo una prórroga","Dos prórrogas como máximo","Todas las que necesite","Ninguna durante el servicio"],"h1":"Las familias militares tienen más facilidades que otros conductores.","h2":"En Idaho, los militares en servicio activo y sus dependientes pueden pedir todas las prórrogas de licencia que necesiten durante el servicio activo, a $10 por solicitud.","p":"Correcto. Puede obtener todas las prórrogas que necesite."},"ref":{"doc":"ID","page":31}},{"id":"id-101","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, when can a Class D driving skills test be scheduled?","o":["Only in daylight and in acceptable weather","Any time, day or night","Only on weekends","Only after dark, to test headlight use"],"h1":"The test is given when the examiner can see the road well.","h2":"In Idaho, Class D skills tests may only be scheduled during daylight hours and in acceptable weather.","p":"Right. Skills tests happen in daylight and decent weather."},"es":{"q":"En Idaho, ¿cuándo se puede programar un examen práctico de manejo Clase D?","o":["Solo de día y con buen clima","A cualquier hora, de día o de noche","Solo los fines de semana","Solo de noche, para probar las luces"],"h1":"El examen se hace cuando el examinador puede ver bien el camino.","h2":"En Idaho, los exámenes prácticos Clase D solo se pueden programar durante el día y con un clima aceptable.","p":"Correcto. El examen práctico se hace de día y con buen clima."},"ref":{"doc":"ID","page":33}},{"id":"id-102","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, a 20-year-old wants to take the driving skills test in a rental car. Is that allowed?","o":["Yes, any rental car is fine","Yes, if a parent rented it","Only if the car is less than a year old","No, not for applicants under 25"],"h1":"There is an age limit for using a rental car on this test.","h2":"In Idaho, a rental car may not be used for the skills test if the applicant is not a licensed driver or is under 25 years old.","p":"Right. Applicants under 25 cannot use a rental car."},"es":{"q":"En Idaho, una persona de 20 años quiere hacer el examen práctico en un auto alquilado. ¿Está permitido?","o":["Sí, cualquier auto alquilado sirve","Sí, si lo alquiló uno de sus padres","Solo si el auto tiene menos de un año","No, no para solicitantes menores de 25 años"],"h1":"Hay un límite de edad para usar un auto alquilado en este examen.","h2":"En Idaho, no se puede usar un auto alquilado para el examen práctico si el solicitante no tiene licencia o tiene menos de 25 años.","p":"Correcto. Los menores de 25 años no pueden usar un auto alquilado."},"ref":{"doc":"ID","page":36}},{"id":"id-103","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, what must you do to get a motorcycle (M) endorsement on your license?","o":["Own a motorcycle for at least six months","Pass the M tests or finish an approved course","Pay the fee; no test is needed","Ride 50 hours with a licensed rider"],"h1":"There are two ways to show you can ride safely.","h2":"In Idaho, you must pass the motorcycle knowledge and skills tests, or complete an approved motorcycle rider training course, before you get an M endorsement.","p":"Right. Tests or an approved course lead to the M endorsement."},"es":{"q":"En Idaho, ¿qué debe hacer para obtener el endoso de motocicleta (M) en su licencia?","o":["Tener una motocicleta al menos seis meses","Aprobar los exámenes de moto o un curso aprobado","Pagar la tarifa; no hay examen","Manejar 50 horas con un motociclista con licencia"],"h1":"Hay dos maneras de demostrar que puede manejar con seguridad.","h2":"En Idaho, debe aprobar los exámenes teórico y práctico de motocicleta, o completar un curso aprobado de entrenamiento para motociclistas, antes de recibir el endoso M.","p":"Correcto. Los exámenes o un curso aprobado le dan el endoso M."},"ref":{"doc":"ID","page":20}},{"id":"id-104","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, a driver gets 18 to 23 points on their record within 24 months. What can ITD do?","o":["Send only a warning letter","Suspend the license for one week","Suspend the license for 90 days","Take away the license for life"],"h1":"It is a longer suspension than the one for 12 to 17 points.","h2":"In Idaho, 18 to 23 points within 24 months can bring a 90-day license suspension.","p":"Right. That many points can mean a 90-day suspension."},"es":{"q":"En Idaho, un conductor acumula de 18 a 23 puntos en su historial en 24 meses. ¿Qué puede hacer el ITD?","o":["Enviar solo una carta de advertencia","Suspender la licencia por una semana","Suspender la licencia por 90 días","Quitarle la licencia de por vida"],"h1":"Es una suspensión más larga que la de 12 a 17 puntos.","h2":"En Idaho, de 18 a 23 puntos en 24 meses pueden traer una suspensión de la licencia por 90 días.","p":"Correcto. Esa cantidad de puntos puede significar 90 días de suspensión."},"ref":{"doc":"ID","page":123}},{"id":"id-105","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a driver gets 24 or more points within 36 months. How long can the license be suspended?","o":["6 months","30 days","10 days","10 years"],"h1":"This is the highest step in the point table.","h2":"In Idaho, 24 or more points within 36 months can bring a six-month license suspension.","p":"Right. It can be a six-month suspension."},"es":{"q":"En Idaho, un conductor acumula 24 puntos o más en 36 meses. ¿Por cuánto tiempo pueden suspender su licencia?","o":["6 meses","30 días","10 días","10 años"],"h1":"Es el nivel más alto de la tabla de puntos.","h2":"En Idaho, 24 puntos o más en 36 meses pueden traer una suspensión de la licencia por seis meses.","p":"Correcto. Puede ser una suspensión de seis meses."},"ref":{"doc":"ID","page":123}},{"id":"id-106","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, how often can you have points removed from your record by taking a defensive driving or traffic safety course?","o":["Once a month","Every time you get a ticket","Only once in your life","Once every three years"],"h1":"There is a waiting period of a few years between uses.","h2":"In Idaho, points can be removed from your record by an approved course only once every three years.","p":"Right. Course point removal is allowed once every three years."},"es":{"q":"En Idaho, ¿con qué frecuencia puede quitar puntos de su historial tomando un curso de manejo defensivo o de seguridad vial?","o":["Una vez al mes","Cada vez que recibe una multa","Solo una vez en la vida","Una vez cada tres años"],"h1":"Hay que esperar algunos años entre un uso y otro.","h2":"En Idaho, se pueden quitar puntos de su historial con un curso aprobado solo una vez cada tres años.","p":"Correcto. Se puede hacer una vez cada tres años."},"ref":{"doc":"ID","page":123}},{"id":"id-107","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a licensed Idaho driver is convicted of speeding in another state. What happens?","o":["Nothing, since it was out of state","The conviction goes on their Idaho driving record","Only the other state keeps a record","They must retake the Idaho knowledge test"],"h1":"Idaho belongs to an agreement among states called the Driver License Compact.","h2":"In Idaho, under the Driver License Compact, a traffic conviction in another state is sent to Idaho and placed on your Idaho driving record.","p":"Right. Out-of-state convictions go on your Idaho record."},"es":{"q":"En Idaho, un conductor con licencia de Idaho es condenado por exceso de velocidad en otro estado. ¿Qué pasa?","o":["Nada, porque fue en otro estado","La condena se anota en su historial de manejo de Idaho","Solo el otro estado guarda el registro","Debe repetir el examen teórico de Idaho"],"h1":"Idaho es parte de un acuerdo entre estados llamado Driver License Compact.","h2":"En Idaho, según el Driver License Compact, una condena de tránsito en otro estado se envía a Idaho y se anota en su historial de manejo de Idaho.","p":"Correcto. Las condenas de otros estados quedan en su historial de Idaho."},"ref":{"doc":"ID","page":122}},{"id":"id-108","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, which of these can lead to the suspension of a young driver's license?","o":["Getting a low grade in math","Changing schools","Not attending school as required","Missing a school sports game"],"h1":"Idaho links teen driving to following the school attendance rules.","h2":"In Idaho, failing to attend school or to comply with school requirements is one of the reasons a license can be suspended.","p":"Right. Not meeting school attendance rules can cost a license."},"es":{"q":"En Idaho, ¿cuál de estas razones puede llevar a la suspensión de la licencia de un conductor joven?","o":["Sacar una nota baja en matemáticas","Cambiarse de escuela","No asistir a la escuela como se requiere","Faltar a un partido de la escuela"],"h1":"Idaho relaciona el manejo de los jóvenes con cumplir las reglas de asistencia escolar.","h2":"En Idaho, no asistir a la escuela o no cumplir los requisitos escolares es una de las razones por las que se puede suspender una licencia.","p":"Correcto. No cumplir la asistencia escolar puede costar la licencia."},"ref":{"doc":"ID","page":124}},{"id":"id-109","scope":"ID","cat":"licensing","sign":null,"c":0,"en":{"q":"In Idaho, a licensed driver under 17 is convicted of a first moving violation. What does ITD do under the GDL rules?","o":["Sends a warning letter","Suspends the license for 60 days","Cancels the license for a year","Nothing at all"],"h1":"Later convictions bring suspensions, but the first one is handled more lightly.","h2":"In Idaho, a driver under 17 gets a warning letter after a first moving violation conviction, warning that more violations can lead to suspension.","p":"Right. The first conviction brings a warning letter."},"es":{"q":"En Idaho, un conductor con licencia menor de 17 años es condenado por su primera infracción de tránsito en movimiento. ¿Qué hace el ITD según las reglas GDL?","o":["Envía una carta de advertencia","Suspende la licencia por 60 días","Cancela la licencia por un año","Nada"],"h1":"Las condenas siguientes traen suspensiones, pero la primera se trata con más suavidad.","h2":"En Idaho, un conductor menor de 17 años recibe una carta de advertencia después de su primera condena por una infracción en movimiento, avisando que más infracciones pueden llevar a una suspensión.","p":"Correcto. La primera condena trae una carta de advertencia."},"ref":{"doc":"ID","page":125}},{"id":"id-110","scope":"ID","cat":"licensing","sign":null,"c":3,"en":{"q":"In Idaho, an adult fails an alcohol test for the second time within five years. How long is the administrative suspension?","o":["30 days","90 days with a work permit","Six months","One year with no driving at all"],"h1":"It is longer than the 90 days for a first failure.","h2":"In Idaho, a second failed alcohol test within five years brings a one-year administrative suspension with no driving privileges of any kind.","p":"Right. It is a full year with no driving."},"es":{"q":"En Idaho, un adulto no pasa una prueba de alcohol por segunda vez en cinco años. ¿Cuánto dura la suspensión administrativa?","o":["30 días","90 días con permiso para trabajar","Seis meses","Un año sin poder manejar nada"],"h1":"Es más larga que los 90 días de la primera vez.","h2":"En Idaho, una segunda prueba de alcohol fallada en cinco años trae una suspensión administrativa de un año sin ningún privilegio de manejo.","p":"Correcto. Es un año completo sin manejar."},"ref":{"doc":"ID","page":126}},{"id":"id-111","scope":"ID","cat":"licensing","sign":null,"c":1,"en":{"q":"In Idaho, a court suspended your license. Where do you ask for a restricted permit to drive to work?","o":["Any county DMV office","The court that convicted you","Your insurance company","The police officer who stopped you"],"h1":"Ask the same authority that took the license away.","h2":"In Idaho, if a court suspended your license, you must ask that court for restricted driving privileges; if ITD suspended it, you apply to ITD in Boise.","p":"Right. You ask the court that convicted you."},"es":{"q":"En Idaho, un tribunal suspendió su licencia. ¿Dónde pide un permiso restringido para manejar al trabajo?","o":["En cualquier oficina del DMV del condado","Al tribunal que lo condenó","A su compañía de seguros","Al policía que lo detuvo"],"h1":"Pregunte a la misma autoridad que le quitó la licencia.","h2":"En Idaho, si un tribunal suspendió su licencia, debe pedir privilegios restringidos a ese tribunal; si la suspendió el ITD, se solicita al ITD en Boise.","p":"Correcto. Se lo pide al tribunal que lo condenó."},"ref":{"doc":"ID","page":127}},{"id":"id-112","scope":"ID","cat":"licensing","sign":null,"c":2,"en":{"q":"In Idaho, an adult is convicted of DUI for the second time within 10 years. How long is the license suspension?","o":["30 days","Five years","One year","No suspension, only a fine"],"h1":"It is longer than for a first conviction, which is 90 to 180 days.","h2":"In Idaho, an adult's second DUI conviction within 10 years brings a mandatory one-year license suspension, along with jail time of 10 days to one year.","p":"Right. The suspension is one year."},"es":{"q":"En Idaho, un adulto es condenado por manejar bajo la influencia (DUI) por segunda vez en 10 años. ¿Cuánto dura la suspensión de la licencia?","o":["30 días","Cinco años","Un año","No hay suspensión, solo una multa"],"h1":"Es más larga que la de una primera condena, que es de 90 a 180 días.","h2":"En Idaho, la segunda condena por DUI de un adulto en 10 años trae una suspensión obligatoria de un año, además de cárcel de 10 días a un año.","p":"Correcto. La suspensión es de un año."},"ref":{"doc":"ID","page":132}},{"id":"id-113","scope":"ID","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Idaho, an officer gives you a traffic ticket and asks you to sign it. What can happen if you refuse to sign?","o":["The ticket is canceled","The fine is cut in half","Nothing; signing is optional","You may be arrested"],"h1":"Signing is not the same as saying you are guilty.","h2":"In Idaho, signing a traffic ticket is not an admission of guilt, but refusing to sign it may result in your arrest.","p":"Right. Refusing to sign can lead to arrest."},"es":{"q":"En Idaho, un policía le da una multa y le pide que la firme. ¿Qué puede pasar si se niega a firmar?","o":["La multa se cancela","La multa baja a la mitad","Nada; firmar es opcional","Lo pueden arrestar"],"h1":"Firmar no es lo mismo que declararse culpable.","h2":"En Idaho, firmar una multa de tránsito no es admitir culpa, pero negarse a firmarla puede resultar en su arresto.","p":"Correcto. Negarse a firmar puede llevar a un arresto."},"ref":{"doc":"ID","page":133}},{"id":"id-114","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, an officer stops your car and you have a weapon in the vehicle. When should you tell the officer?","o":["Only if the officer asks","At the first contact","After you get your ticket","Never; it is private"],"h1":"Telling early helps keep the stop safe for everyone.","h2":"In Idaho, if you have a weapon in the vehicle during a traffic stop, tell the officer at the first contact.","p":"Right. Tell the officer right away."},"es":{"q":"En Idaho, un policía detiene su auto y usted lleva un arma en el vehículo. ¿Cuándo debe decírselo al policía?","o":["Solo si el policía pregunta","En el primer contacto","Después de recibir la multa","Nunca; es algo privado"],"h1":"Avisar temprano ayuda a que la parada sea segura para todos.","h2":"En Idaho, si lleva un arma en el vehículo durante una parada de tránsito, dígaselo al policía en el primer contacto.","p":"Correcto. Avísele al policía enseguida."},"ref":{"doc":"ID","page":133}},{"id":"id-115","scope":"ID","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Idaho, you hit a parked car with no one in it, and you cannot find the owner. What must you do?","o":["Drive away, since no one saw the crash","Wait by the car until night","Leave a note with your name and phone number","Call your insurance and leave"],"h1":"The owner needs a way to reach you.","h2":"In Idaho, if you damage an unattended vehicle and cannot find the owner, you must leave a note about the crash with your name and phone number.","p":"Right. Leave a note so the owner can contact you."},"es":{"q":"En Idaho, usted choca un auto estacionado sin nadie adentro y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse, porque nadie lo vio","Esperar junto al auto hasta la noche","Dejar una nota con su nombre y teléfono","Llamar a su seguro e irse"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Idaho, si daña un vehículo sin nadie adentro y no encuentra al dueño, debe dejar una nota sobre el choque con su nombre y número de teléfono.","p":"Correcto. Deje una nota para que el dueño lo contacte."},"ref":{"doc":"ID","page":119}},{"id":"id-116","scope":"ID","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Idaho, how far may a load stick out past the fenders of a car?","o":["None past the left; 6 inches at most on the right","Up to 2 feet on either side of the car","Up to 1 foot, but only on the left side","Any distance, as long as a flag is used"],"h1":"The rule is stricter on the side next to oncoming traffic.","h2":"In Idaho, a vehicle's load must not stick out past the fenders on the left side, or more than six inches past the fenders on the right side.","p":"Right. Nothing past the left fenders, and 6 inches at most on the right."},"es":{"q":"En Idaho, ¿cuánto puede sobresalir una carga por los lados de un auto, más allá de los guardabarros?","o":["Nada por la izquierda; 6 pulgadas máximo por la derecha","Hasta 2 pies por cualquier lado del auto","Hasta 1 pie, pero solo por la izquierda","Cualquier distancia si lleva una bandera"],"h1":"La regla es más estricta del lado del tránsito que viene de frente.","h2":"En Idaho, la carga de un vehículo no debe sobresalir de los guardabarros del lado izquierdo, ni más de seis pulgadas de los guardabarros del lado derecho.","p":"Correcto. Nada por la izquierda, y 6 pulgadas como máximo por la derecha."},"ref":{"doc":"ID","page":43}},{"id":"id-117","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, what is the closest you may park to a stop sign, yield sign or traffic signal?","o":["5 feet","10 feet","100 feet","30 feet"],"h1":"It is more than the 20 feet required from a crosswalk.","h2":"In Idaho, you may not park within 30 feet of a stop sign, yield sign or traffic signal.","p":"Right. Stay at least 30 feet away."},"es":{"q":"En Idaho, ¿a qué distancia mínima puede estacionarse de una señal de alto, de ceda el paso o de un semáforo?","o":["5 pies","10 pies","100 pies","30 pies"],"h1":"Es más que los 20 pies que se piden desde un cruce peatonal.","h2":"En Idaho, no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo.","p":"Correcto. Quédese al menos a 30 pies."},"ref":{"doc":"ID","page":81}},{"id":"id-118","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, what is the closest you may park to a fire station driveway?","o":["5 feet","20 feet","50 feet","200 feet"],"h1":"It is less than the distance required from railroad tracks.","h2":"In Idaho, you may not park within 20 feet of a fire station driveway.","p":"Right. Keep 20 feet away from a fire station driveway."},"es":{"q":"En Idaho, ¿a qué distancia mínima puede estacionarse de la entrada de una estación de bomberos?","o":["5 pies","20 pies","50 pies","200 pies"],"h1":"Es menos que la distancia que se pide desde las vías del tren.","h2":"En Idaho, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Quédese a 20 pies de la entrada de los bomberos."},"ref":{"doc":"ID","page":81}},{"id":"id-119","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, a car showing the disability symbol parks in a reserved disability space with a meter. What must the driver pay, and how long may they stay?","o":["Half price, for up to one hour","Full price, for up to two hours","Nothing, and for unlimited time","Nothing, but only for 30 minutes"],"h1":"Idaho gives these drivers a special benefit in reserved spaces.","h2":"In Idaho, a disabled person's car with the disability symbol may park in reserved spaces without paying and for unlimited time.","p":"Right. They park free with no time limit."},"es":{"q":"En Idaho, un auto con el símbolo de discapacidad se estaciona en un espacio reservado para personas con discapacidad que tiene parquímetro. ¿Cuánto debe pagar y cuánto tiempo puede quedarse?","o":["La mitad, hasta una hora","El precio completo, hasta dos horas","Nada, y sin límite de tiempo","Nada, pero solo 30 minutos"],"h1":"Idaho da a estos conductores un beneficio especial en los espacios reservados.","h2":"En Idaho, el auto de una persona con discapacidad que muestra el símbolo puede estacionarse en espacios reservados sin pagar y sin límite de tiempo.","p":"Correcto. Se estaciona gratis y sin límite de tiempo."},"ref":{"doc":"ID","page":82}},{"id":"id-120","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, you missed your exit on the freeway. May you back up on the shoulder to reach it?","o":["No, never, not even on the shoulder","Yes, if your hazard lights are on","Yes, if no cars are close behind","Only at night when traffic is light"],"h1":"Think about where the next exit is.","h2":"In Idaho, backing up is always prohibited on freeways, expressways and other controlled-access highways, including the shoulder, so go on to the next exit.","p":"Right. Never back up on a freeway; take the next exit."},"es":{"q":"En Idaho, usted se pasó de su salida en la autopista. ¿Puede retroceder por el acotamiento para llegar a ella?","o":["No, nunca, ni siquiera en el acotamiento","Sí, si tiene las luces de emergencia","Sí, si no hay autos cerca detrás","Solo de noche, con poco tránsito"],"h1":"Piense en dónde está la siguiente salida.","h2":"En Idaho, siempre está prohibido retroceder en autopistas, vías rápidas y otras carreteras de acceso controlado, incluido el acotamiento, así que siga hasta la siguiente salida.","p":"Correcto. Nunca retroceda en una autopista; tome la siguiente salida."},"ref":{"doc":"ID","page":82}},{"id":"id-121","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, what is the top speed on an urban interstate unless a sign says otherwise?","o":["55 mph","75 mph","80 mph","65 mph"],"h1":"It is lower than the limit on rural interstates.","h2":"In Idaho, the speed limit on urban interstate highways is up to 65 mph unless otherwise posted, while rural interstates may allow up to 80 mph where posted.","p":"Right. Urban interstates top out at 65 mph unless posted."},"es":{"q":"En Idaho, ¿cuál es la velocidad máxima en una autopista interestatal urbana si una señal no indica otra cosa?","o":["55 mph","75 mph","80 mph","65 mph"],"h1":"Es menor que el límite en las interestatales rurales.","h2":"En Idaho, el límite en las autopistas interestatales urbanas es de hasta 65 mph salvo otra señal, mientras que en las rurales puede ser de hasta 80 mph donde esté señalado.","p":"Correcto. En interestatales urbanas el máximo es 65 mph salvo otra señal."},"ref":{"doc":"ID","page":83}},{"id":"id-122","scope":"ID","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Idaho, you got on the freeway going the wrong direction. May you use a median crossover to turn around?","o":["Yes, if you signal first and go slowly","No, they are only for maintenance and emergency use","Yes, if traffic is light at the time","Only if a sign shows U-turns are allowed"],"h1":"Those openings in the median are not for regular drivers.","h2":"In Idaho, freeway median crossovers are only for highway maintenance and emergency vehicles, so other drivers must wait for the next exit to change direction.","p":"Right. Use the next exit, not the crossover."},"es":{"q":"En Idaho, usted entró a la autopista en la dirección equivocada. ¿Puede usar un cruce del camellón central para dar la vuelta?","o":["Sí, si pone la direccional y va despacio","No, son solo para mantenimiento y emergencias","Sí, si en ese momento hay poco tránsito","Solo si una señal permite vueltas en U"],"h1":"Esas aberturas en el camellón no son para conductores comunes.","h2":"En Idaho, los cruces del camellón central de la autopista son solo para vehículos de mantenimiento y de emergencia, así que los demás conductores deben esperar a la siguiente salida para cambiar de dirección.","p":"Correcto. Use la siguiente salida, no el cruce."},"ref":{"doc":"ID","page":84}},{"id":"id-123","scope":"ID","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Idaho, you are towing a trailer on a two-lane road posted at 65 mph. May you go over the limit to pass a slow car?","o":["Yes, by up to 15 mph","Yes, by up to 10 mph","No, the passing exception does not apply when towing","Yes, if the pass takes less than 10 seconds"],"h1":"The passing exception covers passenger cars, motorcycles and pickups that are not towing.","h2":"In Idaho, the rule that lets you go up to 15 mph over the limit while passing does not apply if you are towing another vehicle.","p":"Right. When towing, you may not speed up past the limit to pass."},"es":{"q":"En Idaho, usted remolca un tráiler en una carretera de dos carriles con límite de 65 mph. ¿Puede pasar el límite para rebasar a un auto lento?","o":["Sí, hasta 15 mph más","Sí, hasta 10 mph más","No, la excepción no se aplica si remolca","Sí, si rebasa en menos de 10 segundos"],"h1":"La excepción para rebasar es para autos, motocicletas y camionetas que no remolcan nada.","h2":"En Idaho, la regla que permite ir hasta 15 mph sobre el límite al rebasar no se aplica si usted remolca otro vehículo.","p":"Correcto. Si remolca, no puede pasar el límite para rebasar."},"ref":{"doc":"ID","page":77}},{"id":"id-124","scope":"ID","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Idaho, which vehicles in a funeral procession must have their warning lights flashing?","o":["The first and last vehicles","Only the hearse","Every vehicle in the line","Only the last vehicle"],"h1":"These lights mark where the procession begins and ends.","h2":"In Idaho, all vehicles in a funeral procession have headlights and taillights on, and the first and last vehicles also have warning lights flashing.","p":"Right. The first and last vehicles flash their warning lights."},"es":{"q":"En Idaho, ¿qué vehículos de un cortejo fúnebre deben llevar las luces de emergencia intermitentes?","o":["El primero y el último","Solo la carroza fúnebre","Todos los vehículos de la fila","Solo el último"],"h1":"Estas luces marcan dónde empieza y dónde termina el cortejo.","h2":"En Idaho, todos los vehículos de un cortejo fúnebre llevan encendidos los faros y las luces traseras, y el primero y el último además llevan las luces de emergencia intermitentes.","p":"Correcto. El primero y el último encienden las luces de emergencia."},"ref":{"doc":"ID","page":78}},{"id":"id-125","scope":"ID","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Idaho, when may a slow-moving vehicle built to go no faster than 25 mph use a public highway, in most cases?","o":["At any time, day or night","Only at night, in light traffic","Only on weekends and holidays","Only during daylight hours"],"h1":"Snow removal and some farm equipment with flashing lights are the exceptions.","h2":"In Idaho, slow-moving vehicles built for 25 mph or less may use public highways only in daylight, from 30 minutes before sunrise to 30 minutes after sunset, with some exceptions for snow removal and farm equipment.","p":"Right. They are limited to daylight hours."},"es":{"q":"En Idaho, ¿cuándo puede usar una carretera pública un vehículo lento diseñado para no pasar de 25 mph, en la mayoría de los casos?","o":["A cualquier hora, de día o de noche","Solo de noche, con poco tránsito","Solo fines de semana y días feriados","Solo durante las horas de luz del día"],"h1":"Las máquinas quitanieves y algunos equipos agrícolas con luces intermitentes son la excepción.","h2":"En Idaho, los vehículos lentos diseñados para 25 mph o menos solo pueden usar carreteras públicas de día, desde 30 minutos antes del amanecer hasta 30 minutos después del atardecer, con algunas excepciones para quitanieves y equipo agrícola.","p":"Correcto. Solo pueden circular durante el día."},"ref":{"doc":"ID","page":79}},{"id":"id-126","scope":"ID","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Idaho, a bicyclist wants to turn right at a steady red light. What does the law require?","o":["Stop fully and wait for green","Yield, but no full stop is needed","Get off and walk the bike across","Turn only if a car waves them on"],"h1":"Idaho has a special rule for bicyclists at red lights and stop signs.","h2":"In Idaho, a bicyclist turning right on a red light does not need to come to a complete stop, but must yield to vehicles already in or near the intersection.","p":"Right. They must yield, but they need not stop fully."},"es":{"q":"En Idaho, un ciclista quiere girar a la derecha con la luz roja fija. ¿Qué exige la ley?","o":["Parar por completo y esperar la luz verde","Ceder el paso, sin tener que parar por completo","Bajarse y cruzar caminando con la bicicleta","Girar solo si un auto le hace señas"],"h1":"Idaho tiene una regla especial para ciclistas en luces rojas y señales de alto.","h2":"En Idaho, un ciclista que gira a la derecha con luz roja no necesita parar por completo, pero debe ceder el paso a los vehículos que ya están en el cruce o cerca de él.","p":"Correcto. Debe ceder el paso, pero no tiene que parar por completo."},"ref":{"doc":"ID","page":99}},{"id":"id-127","scope":"ID","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Idaho, you are driving behind a truck carrying hazardous materials. What should you expect at a railroad crossing?","o":["It will stop, even if no train is coming","It will speed up to cross quickly","It will only stop if the gates are down","It will pull onto the shoulder"],"h1":"Look for the placards that show it carries dangerous cargo.","h2":"In Idaho, all vehicles carrying hazardous materials must stop at every railroad crossing, so be ready to stop if you follow one.","p":"Right. Hazmat vehicles stop at all railroad crossings."},"es":{"q":"En Idaho, usted maneja detrás de un camión que lleva materiales peligrosos. ¿Qué debe esperar en un cruce de ferrocarril?","o":["Que se detenga, aunque no venga ningún tren","Que acelere para cruzar rápido","Que solo pare si las barreras están abajo","Que se salga al acotamiento"],"h1":"Busque los letreros (placas) que muestran que lleva carga peligrosa.","h2":"En Idaho, todos los vehículos que llevan materiales peligrosos deben detenerse en todos los cruces de ferrocarril, así que prepárese para parar si va detrás de uno.","p":"Correcto. Los vehículos con materiales peligrosos paran en todos los cruces de tren."},"ref":{"doc":"ID","page":106}},{"id":"id-128","scope":"ID","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Idaho, a pilot vehicle with amber lights is coming toward you, leading an oversized load. What should you do?","o":["Speed up to get past quickly","Stop in the middle of your lane","Slow down and move as far right as you can","Flash your high beams at it"],"h1":"The large load behind it may take up more than its own lane.","h2":"In Idaho, when you meet an oncoming pilot vehicle, reduce your speed and position your vehicle as far to the right as possible.","p":"Right. Slow down and keep far to the right."},"es":{"q":"En Idaho, un vehículo piloto con luces ámbar viene hacia usted, guiando una carga extra grande. ¿Qué debe hacer?","o":["Acelerar para pasarlo rápido","Detenerse en medio de su carril","Bajar la velocidad e ir bien a la derecha","Hacerle cambio de luces altas"],"h1":"La carga grande que viene detrás puede ocupar más que su propio carril.","h2":"En Idaho, cuando se encuentra con un vehículo piloto que viene de frente, baje la velocidad y ponga su vehículo lo más a la derecha posible.","p":"Correcto. Baje la velocidad y manténgase bien a la derecha."},"ref":{"doc":"ID","page":106}},{"id":"id-129","scope":"ID","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Idaho, you reach a thru-turn intersection, where direct left turns are not allowed. How do you go left?","o":["Turn left from the far right lane","Wait for a gap and turn left anyway","Back up and use a side street instead","Go straight, U-turn ahead, then turn right"],"h1":"The turn is done in three moves, ending with a right turn.","h2":"In Idaho, at a thru-turn intersection you go straight through, make a U-turn at the next traffic signal as the markings show, head back, and then turn right.","p":"Right. Straight, U-turn, then a right turn."},"es":{"q":"En Idaho, usted llega a un cruce tipo \"thru-turn\", donde no se permiten vueltas directas a la izquierda. ¿Cómo va hacia la izquierda?","o":["Gira a la izquierda desde el carril de la derecha","Espera un espacio y gira a la izquierda igual","Retrocede y usa una calle lateral","Sigue derecho, da vuelta en U y gira a la derecha"],"h1":"La vuelta se hace en tres pasos y termina con un giro a la derecha.","h2":"En Idaho, en un cruce tipo thru-turn usted sigue derecho, da una vuelta en U en el siguiente semáforo como indican las marcas, regresa y luego gira a la derecha.","p":"Correcto. Derecho, vuelta en U y luego a la derecha."},"ref":{"doc":"ID","page":63}},{"id":"id-130","scope":"ID","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Idaho, you take a freeway exit by mistake at a single point urban interchange (SPUI). Can you drive straight across and get back on?","o":["No; turn onto the cross road, then turn around","Yes, go straight across to the other ramp","Yes, if the traffic light is green","Back up the exit ramp and try again"],"h1":"This kind of interchange does not let ramp traffic go straight through.","h2":"In Idaho, if you exit the freeway by mistake at a SPUI, you cannot go straight across; turn left or right onto the cross road and find a safe place to turn around.","p":"Right. Turn onto the cross road and turn around safely."},"es":{"q":"En Idaho, usted toma una salida de la autopista por error en un intercambio urbano de un solo punto (SPUI). ¿Puede cruzar derecho y volver a entrar?","o":["No; tome la calle transversal y dé la vuelta","Sí, cruce derecho hasta la otra rampa","Sí, si el semáforo está en verde","Retroceda por la rampa y vuelva a intentar"],"h1":"Este tipo de intercambio no deja que el tránsito de la rampa siga derecho.","h2":"En Idaho, si sale de la autopista por error en un SPUI, no puede cruzar derecho; gire a la izquierda o a la derecha en la calle transversal y busque un lugar seguro para dar la vuelta.","p":"Correcto. Tome la calle transversal y dé la vuelta con seguridad."},"ref":{"doc":"ID","page":64}},{"id":"id-131","scope":"ID","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Idaho, how far ahead must a car's high-beam headlights let the driver see people and vehicles?","o":["At least 50 feet","At least 350 feet","At least 100 feet","At least 1,000 feet"],"h1":"Low beams must light at least 100 feet; high beams reach much farther.","h2":"In Idaho, high beams must let the driver see people and vehicles at least 350 feet away, and low beams must light the road at least 100 feet ahead.","p":"Right. High beams must show at least 350 feet ahead."},"es":{"q":"En Idaho, ¿a qué distancia deben permitir las luces altas de un auto que el conductor vea personas y vehículos?","o":["Al menos 50 pies","Al menos 350 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"Las luces bajas deben alumbrar al menos 100 pies; las altas llegan mucho más lejos.","h2":"En Idaho, las luces altas deben permitir ver personas y vehículos a por lo menos 350 pies, y las luces bajas deben alumbrar el camino al menos 100 pies adelante.","p":"Correcto. Las luces altas deben alumbrar al menos 350 pies."},"ref":{"doc":"ID","page":38}},{"id":"il-001","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, how many questions are on the written knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is more than 30 but fewer than 40.","h2":"Illinois rules say the written test for a regular driver's license has at least 35 questions.","p":"Right. The Illinois test has 35 questions."},"es":{"q":"En Illinois, ¿cuántas preguntas tiene el examen escrito de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Son más de 30 pero menos de 40.","h2":"Las reglas de Illinois dicen que el examen escrito para una licencia de conducir regular tiene al menos 35 preguntas.","p":"Correcto. El examen de Illinois tiene 35 preguntas."},"zh":{"q":"在 Illinois，笔试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"比 30 多，但比 40 少。","h2":"Illinois 的规定说，普通驾照的笔试至少有 35 道题。","p":"对。Illinois 的考试有 35 道题。"},"vi":{"q":"Ở Illinois, bài thi kiến thức viết có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Nhiều hơn 30 nhưng ít hơn 40.","h2":"Quy định của Illinois nói rằng bài thi viết để lấy bằng lái thông thường có ít nhất 35 câu hỏi.","p":"Đúng. Bài thi ở Illinois có 35 câu hỏi."},"tl":{"q":"Sa Illinois, ilang tanong ang nasa written knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Higit ito sa 30 pero mas kaunti sa 40.","h2":"Sinasabi ng mga patakaran ng Illinois na ang written test para sa regular na driver's license ay may hindi bababa sa 35 tanong.","p":"Tama. May 35 tanong ang test sa Illinois."},"ar":{"q":"في Illinois، كم سؤالًا في اختبار المعرفة الكتابي؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"إنه أكثر من 30 وأقل من 40.","h2":"تقول قواعد Illinois إن الاختبار الكتابي لرخصة القيادة العادية فيه 35 سؤالًا على الأقل.","p":"صحيح. في اختبار Illinois يوجد 35 سؤالًا."},"ref":{"doc":"IL","page":null}},{"id":"il-002","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many of the written test questions must you answer correctly to pass?","o":["28","21","30","35"],"h1":"You need 80 percent of the questions right.","h2":"You must answer at least 28 of the 35 Illinois test questions correctly, which is 80 percent.","p":"Right. You need 28 correct answers to pass."},"es":{"q":"En Illinois, ¿cuántas preguntas del examen escrito debe contestar bien para aprobar?","o":["28","21","30","35"],"h1":"Necesita contestar bien el 80 por ciento de las preguntas.","h2":"Usted debe contestar bien por lo menos 28 de las 35 preguntas del examen de Illinois, que es el 80 por ciento.","p":"Correcto. Necesita 28 respuestas correctas para aprobar."},"zh":{"q":"在 Illinois，笔试必须答对多少道题才能通过？","o":["28","21","30","35"],"h1":"你需要答对 80% 的题。","h2":"35 道 Illinois 笔试题里，你必须至少答对 28 道，也就是 80%。","p":"对。你需要答对 28 道才能通过。"},"vi":{"q":"Ở Illinois, bạn phải trả lời đúng bao nhiêu câu trong bài thi viết để đậu?","o":["28","21","30","35"],"h1":"Bạn cần trả lời đúng 80 phần trăm số câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 28 trong 35 câu hỏi của bài thi Illinois, tức là 80 phần trăm.","p":"Đúng. Bạn cần 28 câu đúng để đậu."},"tl":{"q":"Sa Illinois, ilan sa mga tanong sa nakasulat na test ang dapat mong masagot nang tama para pumasa?","o":["28","21","30","35"],"h1":"Kailangan mong masagot nang tama ang 80 porsiyento ng mga tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 28 sa 35 tanong ng test sa Illinois, na 80 porsiyento.","p":"Tama. Kailangan mo ng 28 tamang sagot para pumasa."},"ar":{"q":"في Illinois، كم سؤالًا من أسئلة الاختبار الكتابي يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["28","21","30","35"],"h1":"تحتاج إلى إجابة 80 بالمئة من الأسئلة إجابة صحيحة.","h2":"يجب أن تجيب إجابة صحيحة عن 28 سؤالًا على الأقل من أسئلة اختبار Illinois الـ35، وهذا يساوي 80 بالمئة.","p":"صحيح. تحتاج إلى 28 إجابة صحيحة لتنجح."},"ref":{"doc":"IL","page":null}},{"id":"il-003","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what is the youngest age to take the written test for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the usual age for a first license.","h2":"In Illinois you can take the written test for an instruction permit at 15 years old.","p":"Right. In Illinois you can start at 15."},"es":{"q":"En Illinois, ¿cuál es la edad mínima para presentar el examen escrito del permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la edad habitual para la primera licencia.","h2":"En Illinois usted puede presentar el examen escrito del permiso de aprendiz a los 15 años.","p":"Correcto. En Illinois puede empezar a los 15."},"zh":{"q":"在 Illinois，最小几岁可以参加学习驾照（instruction permit）的笔试？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比一般第一次拿驾照的年龄早一年。","h2":"在 Illinois，你 15 岁就可以参加学习驾照的笔试。","p":"对。在 Illinois，你可以从 15 岁开始。"},"vi":{"q":"Ở Illinois, tuổi nhỏ nhất để thi viết lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước tuổi thường được lấy bằng lái đầu tiên.","h2":"Ở Illinois, bạn có thể thi viết để lấy giấy phép tập lái khi 15 tuổi.","p":"Đúng. Ở Illinois bạn có thể bắt đầu khi 15 tuổi."},"tl":{"q":"Sa Illinois, ano ang pinakabatang edad para kumuha ng nakasulat na test para sa instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang karaniwang edad para sa unang lisensya.","h2":"Sa Illinois, puwede kang kumuha ng nakasulat na test para sa instruction permit sa edad na 15.","p":"Tama. Sa Illinois, puwede kang magsimula sa 15."},"ar":{"q":"في Illinois، ما أصغر عمر لأداء الاختبار الكتابي للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل العمر المعتاد لأول رخصة.","h2":"في Illinois يمكنك أداء الاختبار الكتابي للحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. في Illinois يمكنك أن تبدأ في عمر 15 سنة."},"ref":{"doc":"IL","page":16}},{"id":"il-004","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how long must a driver under 18 hold the instruction permit before getting a license?","o":["3 months","6 months","12 months","9 months"],"h1":"It is longer than half a year but less than a full year.","h2":"An Illinois driver under 18 must hold the instruction permit for at least nine months before moving to a license.","p":"Right. The Illinois permit must be held for nine months."},"es":{"q":"En Illinois, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor menor de 18 años antes de obtener la licencia?","o":["3 meses","6 meses","12 meses","9 meses"],"h1":"Es más de medio año pero menos de un año completo.","h2":"Un conductor de Illinois menor de 18 años debe tener el permiso de aprendiz por lo menos nueve meses antes de pasar a la licencia.","p":"Correcto. En Illinois el permiso se debe tener nueve meses."},"zh":{"q":"在 Illinois，18 岁以下的司机必须持有学习驾照多久，才能拿到驾照？","o":["3 个月","6 个月","12 个月","9 个月"],"h1":"比半年长，但不到一整年。","h2":"在 Illinois，18 岁以下的司机必须持有学习驾照至少九个月，才能换成驾照。","p":"对。Illinois 的学习驾照必须持有九个月。"},"vi":{"q":"Ở Illinois, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["3 tháng","6 tháng","12 tháng","9 tháng"],"h1":"Lâu hơn nửa năm nhưng ít hơn một năm.","h2":"Người lái dưới 18 tuổi ở Illinois phải giữ giấy phép tập lái ít nhất chín tháng trước khi lấy bằng lái.","p":"Đúng. Ở Illinois phải giữ giấy phép tập lái chín tháng."},"tl":{"q":"Sa Illinois, gaano katagal dapat hawak ng driver na wala pang 18 ang instruction permit bago makakuha ng lisensya?","o":["3 buwan","6 na buwan","12 buwan","9 na buwan"],"h1":"Mas matagal ito sa kalahating taon pero kulang sa isang buong taon.","h2":"Ang driver sa Illinois na wala pang 18 ay dapat humawak ng instruction permit nang hindi bababa sa siyam na buwan bago lumipat sa lisensya.","p":"Tama. Dapat hawak ang permit sa Illinois nang siyam na buwan."},"ar":{"q":"في Illinois، كم مدة يجب أن يحمل السائق الذي عمره أقل من 18 سنة تصريح التعلّم قبل الحصول على رخصة؟","o":["3 أشهر","6 أشهر","12 شهرًا","9 أشهر"],"h1":"هي أطول من نصف سنة لكنها أقل من سنة كاملة.","h2":"يجب على السائق في Illinois الذي عمره أقل من 18 سنة أن يحمل تصريح التعلّم تسعة أشهر على الأقل قبل الانتقال إلى الرخصة.","p":"صحيح. يجب حمل التصريح في Illinois تسعة أشهر."},"ref":{"doc":"IL","page":16}},{"id":"il-005","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what happens to the nine-month permit period if the permit holder gets a moving violation?","o":["Nothing changes","The permit becomes a license early","A new nine-month wait begins","The holder only pays a fine"],"h1":"The violation sets you back, not forward.","h2":"In Illinois, a moving violation conviction during the permit phase means a new nine-month wait before you can apply for a license.","p":"Right. A violation means a new nine-month wait."},"es":{"q":"En Illinois, ¿qué pasa con el periodo de nueve meses del permiso si el titular recibe una infracción de tránsito en movimiento?","o":["No cambia nada","El permiso se convierte antes en licencia","Empieza una nueva espera de nueve meses","El titular solo paga una multa"],"h1":"La infracción lo hace retroceder, no avanzar.","h2":"En Illinois, una condena por infracción en movimiento durante la etapa del permiso significa una nueva espera de nueve meses antes de poder solicitar la licencia.","p":"Correcto. Una infracción significa una nueva espera de nueve meses."},"zh":{"q":"在 Illinois，如果持学习驾照的人有行车违规，九个月的学习驾照期会怎么样？","o":["什么都不变","学习驾照提前变成驾照","重新开始等九个月","持有人只交罚款"],"h1":"违规会让你后退，不会让你前进。","h2":"在 Illinois，学习驾照阶段被判行车违规，就要重新等九个月才能申请驾照。","p":"对。违规就要重新等九个月。"},"vi":{"q":"Ở Illinois, điều gì xảy ra với thời gian chín tháng giữ giấy phép nếu người có giấy phép tập lái bị phạt vi phạm khi đang lái xe?","o":["Không có gì thay đổi","Giấy phép trở thành bằng lái sớm hơn","Bắt đầu một thời gian chờ chín tháng mới","Người đó chỉ phải trả tiền phạt"],"h1":"Vi phạm làm bạn lùi lại, không phải tiến lên.","h2":"Ở Illinois, nếu bị kết tội vi phạm khi lái xe trong thời gian tập lái, bạn phải chờ lại chín tháng mới trước khi xin bằng lái.","p":"Đúng. Một lần vi phạm nghĩa là phải chờ lại chín tháng mới."},"tl":{"q":"Sa Illinois, ano ang mangyayari sa siyam na buwang panahon ng permit kung magkaroon ng moving violation ang may hawak ng permit?","o":["Walang magbabago","Magiging lisensya nang maaga ang permit","Magsisimula ang bagong siyam na buwang paghihintay","Multa lang ang babayaran ng may hawak"],"h1":"Pinauurong ka ng violation, hindi pinauusad.","h2":"Sa Illinois, kapag nahatulan ka ng moving violation habang nasa permit phase, magsisimula ang bagong siyam na buwang paghihintay bago ka makapag-apply ng lisensya.","p":"Tama. Ang isang violation ay nangangahulugan ng bagong siyam na buwang paghihintay."},"ar":{"q":"في Illinois، ماذا يحدث لمدة التصريح البالغة تسعة أشهر إذا ارتكب حامل التصريح مخالفة أثناء القيادة (moving violation)؟","o":["لا يتغير شيء","يصبح التصريح رخصة في وقت أبكر","تبدأ مدة انتظار جديدة من تسعة أشهر","يدفع حامل التصريح غرامة فقط"],"h1":"المخالفة تعيدك إلى الوراء، لا إلى الأمام.","h2":"في Illinois، إذا أُدنت بمخالفة أثناء القيادة في مرحلة التصريح، تبدأ مدة انتظار جديدة من تسعة أشهر قبل أن تتقدم بطلب للرخصة.","p":"صحيح. المخالفة تعني انتظارًا جديدًا من تسعة أشهر."},"ref":{"doc":"IL","page":null}},{"id":"il-006","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how many hours of supervised practice must a driver under 18 complete with the permit?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"An Illinois driver under 18 must complete at least 50 hours of supervised practice, including 10 hours at night.","p":"Right. Illinois requires 50 practice hours."},"es":{"q":"En Illinois, ¿cuántas horas de práctica supervisada debe completar con el permiso un conductor menor de 18 años?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un conductor de Illinois menor de 18 años debe completar por lo menos 50 horas de práctica supervisada, de las cuales 10 son de noche.","p":"Correcto. Illinois exige 50 horas de práctica."},"zh":{"q":"在 Illinois，18 岁以下的司机持学习驾照期间，必须完成多少小时有人陪同的练习？","o":["30 小时","50 小时","40 小时","100 小时"],"h1":"是一百的一半。","h2":"在 Illinois，18 岁以下的司机必须完成至少 50 小时有人陪同的练习，其中包括 10 小时夜间驾驶。","p":"对。Illinois 要求 50 小时练习。"},"vi":{"q":"Ở Illinois, người lái dưới 18 tuổi phải tập lái có người giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["30 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Người lái dưới 18 tuổi ở Illinois phải tập lái có người giám sát ít nhất 50 giờ, trong đó có 10 giờ vào ban đêm.","p":"Đúng. Illinois yêu cầu 50 giờ tập lái."},"tl":{"q":"Sa Illinois, ilang oras ng supervised practice ang dapat tapusin ng driver na wala pang 18 habang may permit?","o":["30 oras","50 oras","40 oras","100 oras"],"h1":"Kalahati ito ng isandaan.","h2":"Ang driver sa Illinois na wala pang 18 ay dapat makatapos ng hindi bababa sa 50 oras ng supervised practice, kasama ang 10 oras sa gabi.","p":"Tama. Kailangan ng Illinois ng 50 oras ng pagsasanay."},"ar":{"q":"في Illinois، كم ساعة من التدريب تحت الإشراف يجب أن يكملها السائق الذي عمره أقل من 18 سنة مع التصريح؟","o":["30 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هو نصف المئة.","h2":"يجب على السائق في Illinois الذي عمره أقل من 18 سنة أن يكمل 50 ساعة على الأقل من التدريب تحت الإشراف، منها 10 ساعات في الليل.","p":"صحيح. تطلب Illinois خمسين ساعة تدريب."},"ref":{"doc":"IL","page":16}},{"id":"il-007","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many of the 50 supervised practice hours must be at night?","o":["10 hours","5 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised practice hours in Illinois must be done at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Illinois, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["10 horas","5 horas","20 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica supervisada en Illinois deben hacerse de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 Illinois，50 小时有人陪同的练习中，必须有多少小时是在夜间？","o":["10 小时","5 小时","20 小时","25 小时"],"h1":"是总数的五分之一。","h2":"在 Illinois，50 小时有人陪同的练习中，至少 10 小时必须在夜间完成。","p":"对。十个小时必须在夜间。"},"vi":{"q":"Ở Illinois, trong 50 giờ tập lái có người giám sát, bao nhiêu giờ phải là vào ban đêm?","o":["10 giờ","5 giờ","20 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ở Illinois, ít nhất 10 trong 50 giờ tập lái có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Illinois, ilan sa 50 oras ng supervised practice ang dapat gawin sa gabi?","o":["10 oras","5 oras","20 oras","25 oras"],"h1":"Isang ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised practice sa Illinois ang dapat gawin sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في Illinois، كم ساعة من ساعات التدريب الخمسين تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","20 ساعة","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الخمسين تحت الإشراف في Illinois في الليل.","p":"صحيح. يجب أن تكون عشر ساعات في الليل."},"ref":{"doc":"IL","page":16}},{"id":"il-008","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, who may supervise a permit holder during practice?","o":["Any licensed driver 16 or older","Any licensed driver 18 or older","Only a driving instructor","A parent or a licensed adult 21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Illinois a permit holder must practice with a parent or a licensed adult who is at least 21 years old.","p":"Right. The supervisor must be a parent or a licensed adult 21 or older."},"es":{"q":"En Illinois, ¿quién puede supervisar a un conductor con permiso durante la práctica?","o":["Cualquier conductor con licencia de 16 años o más","Cualquier conductor con licencia de 18 años o más","Solo un instructor de manejo","Un padre o un adulto con licencia de 21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Illinois un conductor con permiso debe practicar con un padre o con un adulto con licencia que tenga por lo menos 21 años.","p":"Correcto. El supervisor debe ser un padre o un adulto con licencia de 21 años o más."},"zh":{"q":"在 Illinois，谁可以在练习时陪同持学习驾照的人？","o":["任何 16 岁或以上、有驾照的司机","任何 18 岁或以上、有驾照的司机","只有驾驶教练","父母，或 21 岁或以上、有驾照的成年人"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Illinois，持学习驾照的人必须和父母，或一位至少 21 岁、有驾照的成年人一起练习。","p":"对。陪同的人必须是父母，或 21 岁或以上、有驾照的成年人。"},"vi":{"q":"Ở Illinois, ai được phép giám sát người có giấy phép tập lái khi tập lái?","o":["Bất kỳ người có bằng lái nào từ 16 tuổi trở lên","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Chỉ thầy dạy lái xe","Cha mẹ hoặc một người lớn có bằng lái từ 21 tuổi trở lên"],"h1":"Người giám sát phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở Illinois, người có giấy phép tập lái phải tập với cha mẹ hoặc một người lớn có bằng lái ít nhất 21 tuổi.","p":"Đúng. Người giám sát phải là cha mẹ hoặc người lớn có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa Illinois, sino ang puwedeng magbantay sa may hawak ng permit habang nagsasanay?","o":["Sinumang may lisensya na 16 pataas","Sinumang may lisensya na 18 pataas","Isang driving instructor lang","Isang magulang o isang adult na may lisensya na 21 pataas"],"h1":"Dapat sapat ang edad ng nagbabantay para legal na uminom ng alak.","h2":"Sa Illinois, dapat magsanay ang may hawak ng permit kasama ang isang magulang o isang adult na may lisensya na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat magulang o adult na may lisensya na 21 pataas ang nagbabantay."},"ar":{"q":"في Illinois، من يجوز له الإشراف على حامل التصريح أثناء التدريب؟","o":["أي سائق مرخّص عمره 16 سنة أو أكثر","أي سائق مرخّص عمره 18 سنة أو أكثر","مدرّب القيادة فقط","أحد الوالدين أو شخص بالغ مرخّص عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون المشرف في العمر الذي يُسمح فيه قانونيًا بشرب الكحول.","h2":"في Illinois يجب أن يتدرب حامل التصريح مع أحد الوالدين أو مع شخص بالغ مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون المشرف أحد الوالدين أو شخصًا بالغًا مرخّصًا عمره 21 سنة أو أكثر."},"ref":{"doc":"IL","page":16}},{"id":"il-009","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, may a driver under 19 with a permit or graduated license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, except to call for help in an emergency","Yes, if a parent is in the car"],"h1":"The rule for young drivers is stricter than for adults.","h2":"An Illinois driver under 19 with a permit or graduated license may not use any phone while driving, hands-free included, except to report an emergency.","p":"Right. Young drivers may use a phone only in an emergency."},"es":{"q":"En Illinois, ¿puede un conductor menor de 19 años con permiso o licencia gradual usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en autopistas","No, excepto para pedir ayuda en una emergencia","Sí, si va un padre en el carro"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor de Illinois menor de 19 años con permiso o licencia gradual no puede usar ningún teléfono mientras maneja, ni siquiera manos libres, excepto para reportar una emergencia.","p":"Correcto. Los conductores jóvenes solo pueden usar el teléfono en una emergencia."},"zh":{"q":"在 Illinois，19 岁以下、持学习驾照或分级驾照的司机，开车时可以用免提手机吗？","o":["可以，免提任何时候都允许","可以，但只能在高速公路上","不可以，除非在紧急情况下打电话求助","可以，只要父母在车上"],"h1":"对年轻司机的规定比对成年人更严格。","h2":"在 Illinois，19 岁以下、持学习驾照或分级驾照的司机开车时不能用任何手机，包括免提，只有报告紧急情况除外。","p":"对。年轻司机只有在紧急情况下才能用手机。"},"vi":{"q":"Ở Illinois, người lái dưới 19 tuổi có giấy phép tập lái hoặc bằng lái theo cấp (graduated license) có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, trừ khi gọi xin giúp đỡ trong trường hợp khẩn cấp","Có, nếu có cha mẹ ngồi trong xe"],"h1":"Luật cho người lái trẻ nghiêm hơn luật cho người lớn.","h2":"Ở Illinois, người lái dưới 19 tuổi có giấy phép tập lái hoặc bằng lái theo cấp không được dùng bất kỳ điện thoại nào khi lái xe, kể cả rảnh tay, trừ khi báo trường hợp khẩn cấp.","p":"Đúng. Người lái trẻ chỉ được dùng điện thoại khi khẩn cấp."},"tl":{"q":"Sa Illinois, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang driver na wala pang 19 na may permit o graduated license?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, maliban kung tatawag para humingi ng tulong sa emergency","Oo, kung may magulang sa sasakyan"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa mga adult.","h2":"Sa Illinois, ang driver na wala pang 19 na may permit o graduated license ay hindi puwedeng gumamit ng anumang telepono habang nagmamaneho, kasama ang hands-free, maliban kung mag-uulat ng emergency.","p":"Tama. Puwedeng gumamit ng telepono ang mga batang driver sa emergency lang."},"ar":{"q":"في Illinois، هل يجوز للسائق الذي عمره أقل من 19 سنة ويحمل تصريحًا أو رخصة متدرجة (graduated license) أن يستخدم هاتفًا بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","لا، إلا للاتصال لطلب المساعدة في حالة طوارئ","نعم، إذا كان أحد الوالدين في السيارة"],"h1":"القاعدة للسائقين الصغار أشد من القاعدة للبالغين.","h2":"في Illinois، لا يجوز للسائق الذي عمره أقل من 19 سنة ويحمل تصريحًا أو رخصة متدرجة أن يستخدم أي هاتف أثناء القيادة، حتى بدون اليدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. يستخدم السائقون الصغار الهاتف في حالة الطوارئ فقط."},"ref":{"doc":"IL","page":18}},{"id":"il-010","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what kind of phone use is banned for all drivers while driving?","o":["Hands-free calls","Holding the phone in your hand","Voice commands","Listening to music through the car"],"h1":"Think about where the phone is.","h2":"Illinois bans all drivers from using a hand-held phone while driving. Drivers 19 and older may still use a hands-free phone.","p":"Right. Hand-held phone use is banned for every Illinois driver."},"es":{"q":"En Illinois, ¿qué uso del teléfono está prohibido para todos los conductores mientras manejan?","o":["Llamadas con manos libres","Sostener el teléfono en la mano","Comandos de voz","Escuchar música por el sistema del carro"],"h1":"Piense en dónde está el teléfono.","h2":"Illinois prohíbe a todos los conductores usar el teléfono en la mano mientras manejan. Los conductores de 19 años o más todavía pueden usar un teléfono manos libres.","p":"Correcto. Usar el teléfono en la mano está prohibido para todos en Illinois."},"zh":{"q":"在 Illinois，开车时哪种用手机的方式对所有司机都是禁止的？","o":["用免提打电话","手里拿着手机","语音命令","通过车上的音响听音乐"],"h1":"想一想手机在哪里。","h2":"Illinois 禁止所有司机开车时使用手持手机。19 岁及以上的司机仍然可以用免提手机。","p":"对。Illinois 的每一位司机都不能手持手机。"},"vi":{"q":"Ở Illinois, cách dùng điện thoại nào bị cấm đối với tất cả người lái khi đang lái xe?","o":["Gọi điện rảnh tay","Cầm điện thoại trên tay","Ra lệnh bằng giọng nói","Nghe nhạc qua loa xe"],"h1":"Hãy nghĩ xem điện thoại đang ở đâu.","h2":"Illinois cấm tất cả người lái dùng điện thoại cầm tay khi lái xe. Người lái từ 19 tuổi trở lên vẫn được dùng điện thoại rảnh tay.","p":"Đúng. Mọi người lái ở Illinois đều bị cấm dùng điện thoại cầm tay."},"tl":{"q":"Sa Illinois, anong uri ng paggamit ng telepono ang bawal sa lahat ng driver habang nagmamaneho?","o":["Mga hands-free na tawag","Paghawak ng telepono sa kamay","Mga voice command","Pakikinig ng musika sa sasakyan"],"h1":"Isipin kung nasaan ang telepono.","h2":"Ipinagbabawal ng Illinois sa lahat ng driver ang paggamit ng hand-held na telepono habang nagmamaneho. Puwede pa ring gumamit ng hands-free na telepono ang mga driver na 19 pataas.","p":"Tama. Bawal sa bawat driver sa Illinois ang hand-held na telepono."},"ar":{"q":"في Illinois، أي نوع من استخدام الهاتف ممنوع على كل السائقين أثناء القيادة؟","o":["المكالمات بدون استخدام اليدين","حمل الهاتف في يدك","الأوامر الصوتية","الاستماع إلى الموسيقى من خلال السيارة"],"h1":"فكّر أين يكون الهاتف.","h2":"تمنع Illinois كل السائقين من استخدام الهاتف المحمول باليد أثناء القيادة. ويجوز للسائقين الذين عمرهم 19 سنة أو أكثر أن يستخدموا هاتفًا بدون اليدين.","p":"صحيح. استخدام الهاتف باليد ممنوع على كل سائق في Illinois."},"ref":{"doc":"IL","page":22}},{"id":"il-011","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, during the first 12 months with a license, how many passengers under 20 may a driver under 18 carry?","o":["None at all","Two","Three","One, not counting brothers, sisters or the driver's children"],"h1":"Family members such as brothers and sisters do not count.","h2":"For the first 12 months of an Illinois license, a driver under 18 may carry only one passenger under 20, not counting siblings or the driver's own children.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Illinois, durante los primeros 12 meses con licencia, ¿cuántos pasajeros menores de 20 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Tres","Uno, sin contar hermanos ni hijos del conductor"],"h1":"Los familiares como hermanos y hermanas no cuentan.","h2":"Durante los primeros 12 meses de licencia en Illinois, un conductor menor de 18 años solo puede llevar un pasajero menor de 20, sin contar hermanos ni sus propios hijos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"zh":{"q":"在 Illinois，拿到驾照的头 12 个月里，18 岁以下的司机可以载几个 20 岁以下的乘客？","o":["一个都不可以","两个","三个","一个，兄弟姐妹或司机自己的孩子不算"],"h1":"兄弟姐妹这样的家人不算。","h2":"在 Illinois 拿到驾照的头 12 个月里，18 岁以下的司机只能载一个 20 岁以下的乘客，兄弟姐妹或司机自己的孩子不算。","p":"对。只能载一个不是家人的年轻乘客。"},"vi":{"q":"Ở Illinois, trong 12 tháng đầu có bằng lái, người lái dưới 18 tuổi được chở bao nhiêu hành khách dưới 20 tuổi?","o":["Không ai cả","Hai người","Ba người","Một người, không tính anh chị em hoặc con của người lái"],"h1":"Người trong gia đình như anh chị em không được tính.","h2":"Trong 12 tháng đầu có bằng lái ở Illinois, người lái dưới 18 tuổi chỉ được chở một hành khách dưới 20 tuổi, không tính anh chị em hoặc con của chính người lái.","p":"Đúng. Chỉ được chở một hành khách trẻ không phải người trong gia đình."},"tl":{"q":"Sa Illinois, sa unang 12 buwan na may lisensya, ilang pasaherong wala pang 20 ang puwedeng isakay ng driver na wala pang 18?","o":["Wala talaga","Dalawa","Tatlo","Isa, hindi kasama ang mga kapatid o mga anak ng driver"],"h1":"Hindi kasama sa bilang ang mga kapamilya gaya ng mga kapatid.","h2":"Sa unang 12 buwan ng lisensya sa Illinois, ang driver na wala pang 18 ay puwedeng magsakay ng isang pasaherong wala pang 20 lang, hindi kasama ang mga kapatid o ang sariling mga anak ng driver.","p":"Tama. Isang batang pasahero lang na hindi kapamilya."},"ar":{"q":"في Illinois، خلال أول 12 شهرًا مع الرخصة، كم راكبًا عمره أقل من 20 سنة يجوز للسائق الذي عمره أقل من 18 سنة أن ينقل؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد، دون حساب الإخوة والأخوات أو أولاد السائق"],"h1":"أفراد العائلة مثل الإخوة والأخوات لا يُحسبون.","h2":"خلال أول 12 شهرًا من رخصة Illinois، يجوز للسائق الذي عمره أقل من 18 سنة أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة، دون حساب الإخوة والأخوات أو أولاد السائق نفسه.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة."},"ref":{"doc":"IL","page":18}},{"id":"il-012","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, from Sunday to Thursday, when may a driver under 18 not drive, apart from the allowed exceptions?","o":["From 10 p.m. to 6 a.m.","From 8 p.m. to 6 a.m.","From midnight to 4 a.m.","From 1 a.m. to 5 a.m."],"h1":"It starts at ten at night on school nights.","h2":"In Illinois, a driver under 18 may not drive from 10 p.m. to 6 a.m., Sunday through Thursday, unless an exception applies, such as driving to or from work.","p":"Right. On weeknights the limit starts at 10 p.m."},"es":{"q":"En Illinois, de domingo a jueves, ¿en qué horario no puede manejar un conductor menor de 18 años, fuera de las excepciones permitidas?","o":["De 10 p.m. a 6 a.m.","De 8 p.m. a 6 a.m.","De medianoche a 4 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza a las diez de la noche en días de escuela.","h2":"En Illinois un conductor menor de 18 años no puede manejar de 10 p.m. a 6 a.m., de domingo a jueves, salvo una excepción, como ir o volver del trabajo.","p":"Correcto. Entre semana el límite empieza a las 10 p.m."},"zh":{"q":"在 Illinois，星期天到星期四，除了允许的例外情况，18 岁以下的司机什么时间不能开车？","o":["晚上 10 点到早上 6 点","晚上 8 点到早上 6 点","午夜到凌晨 4 点","凌晨 1 点到早上 5 点"],"h1":"在第二天要上学的晚上，从晚上十点开始。","h2":"在 Illinois，星期天到星期四，18 岁以下的司机晚上 10 点到早上 6 点不能开车，除非符合例外情况，例如开车上班或下班。","p":"对。平日晚上的限制从晚上 10 点开始。"},"vi":{"q":"Ở Illinois, từ Chủ Nhật đến thứ Năm, người lái dưới 18 tuổi không được lái xe vào giờ nào, ngoài các trường hợp ngoại lệ được phép?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 8 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Bắt đầu lúc mười giờ tối vào những đêm trước ngày đi học.","h2":"Ở Illinois, người lái dưới 18 tuổi không được lái xe từ 10 giờ tối đến 6 giờ sáng, từ Chủ Nhật đến thứ Năm, trừ khi có ngoại lệ, ví dụ như lái xe đi làm hoặc đi làm về.","p":"Đúng. Vào các đêm trong tuần, giới hạn bắt đầu lúc 10 giờ tối."},"tl":{"q":"Sa Illinois, mula Linggo hanggang Huwebes, kailan hindi puwedeng magmaneho ang driver na wala pang 18, maliban sa mga pinapayagang exception?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 8 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito sa alas-diyes ng gabi sa mga gabing may pasok kinabukasan.","h2":"Sa Illinois, ang driver na wala pang 18 ay hindi puwedeng magmaneho mula 10 p.m. hanggang 6 a.m., Linggo hanggang Huwebes, maliban kung may exception, gaya ng pagmamaneho papunta o pauwi mula sa trabaho.","p":"Tama. Sa mga gabi ng weekday, nagsisimula ang limitasyon sa 10 p.m."},"ar":{"q":"في Illinois، من الأحد إلى الخميس، متى لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقود، باستثناء الحالات المسموح بها؟","o":["من 10 مساءً إلى 6 صباحًا","من 8 مساءً إلى 6 صباحًا","من منتصف الليل إلى 4 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"يبدأ في الساعة العاشرة ليلًا في ليالي أيام الدراسة.","h2":"في Illinois، لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقود من 10 مساءً إلى 6 صباحًا، من الأحد إلى الخميس، إلا إذا انطبق استثناء، مثل القيادة إلى العمل أو منه.","p":"صحيح. في ليالي أيام الأسبوع يبدأ الحد في 10 مساءً."},"ref":{"doc":"IL","page":18}},{"id":"il-013","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, on Friday and Saturday nights, when does the night driving limit for drivers under 18 begin?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"It is one hour later than on school nights.","h2":"In Illinois the weekend night limit for drivers under 18 runs from 11 p.m. to 6 a.m. on Friday and Saturday nights.","p":"Right. On weekends the limit starts at 11 p.m."},"es":{"q":"En Illinois, los viernes y sábados por la noche, ¿a qué hora empieza el límite de manejo nocturno para menores de 18 años?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"Es una hora más tarde que en días de escuela.","h2":"En Illinois el límite nocturno de fin de semana para menores de 18 años va de 11 p.m. a 6 a.m. los viernes y sábados.","p":"Correcto. El fin de semana el límite empieza a las 11 p.m."},"zh":{"q":"在 Illinois，星期五和星期六晚上，18 岁以下司机的夜间驾驶限制从几点开始？","o":["晚上 9 点","晚上 10 点","晚上 11 点","凌晨 1 点"],"h1":"比第二天要上学的晚上晚一个小时。","h2":"在 Illinois，星期五和星期六晚上，18 岁以下司机的周末夜间限制是晚上 11 点到早上 6 点。","p":"对。周末的限制从晚上 11 点开始。"},"vi":{"q":"Ở Illinois, vào tối thứ Sáu và thứ Bảy, giới hạn lái xe ban đêm cho người dưới 18 tuổi bắt đầu lúc mấy giờ?","o":["9 giờ tối","10 giờ tối","11 giờ tối","1 giờ sáng"],"h1":"Trễ hơn một giờ so với những đêm trước ngày đi học.","h2":"Ở Illinois, giới hạn ban đêm cuối tuần cho người lái dưới 18 tuổi là từ 11 giờ tối đến 6 giờ sáng vào tối thứ Sáu và thứ Bảy.","p":"Đúng. Vào cuối tuần, giới hạn bắt đầu lúc 11 giờ tối."},"tl":{"q":"Sa Illinois, sa gabi ng Biyernes at Sabado, kailan nagsisimula ang limitasyon sa pagmamaneho sa gabi para sa mga driver na wala pang 18?","o":["9 p.m.","10 p.m.","11 p.m.","1 a.m."],"h1":"Isang oras itong mas huli kaysa sa mga gabing may pasok kinabukasan.","h2":"Sa Illinois, ang limitasyon sa gabi tuwing weekend para sa mga driver na wala pang 18 ay mula 11 p.m. hanggang 6 a.m. sa gabi ng Biyernes at Sabado.","p":"Tama. Tuwing weekend, nagsisimula ang limitasyon sa 11 p.m."},"ar":{"q":"في Illinois، في ليلتي الجمعة والسبت، متى يبدأ حد القيادة الليلية للسائقين الذين عمرهم أقل من 18 سنة؟","o":["9 مساءً","10 مساءً","11 مساءً","1 صباحًا"],"h1":"هو متأخر بساعة واحدة عن ليالي أيام الدراسة.","h2":"في Illinois يمتد حد الليل في نهاية الأسبوع للسائقين الذين عمرهم أقل من 18 سنة من 11 مساءً إلى 6 صباحًا في ليلتي الجمعة والسبت.","p":"صحيح. في نهاية الأسبوع يبدأ الحد في 11 مساءً."},"ref":{"doc":"IL","page":18}},{"id":"il-014","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, what does Scott's Law tell you to do when you approach a stopped vehicle with flashing emergency or hazard lights?","o":["Speed up to pass quickly","Slow down and change lanes if you safely can","Stop in your lane until it leaves","Honk to warn the people there"],"h1":"This law is also called the Move Over law.","h2":"Scott's Law in Illinois tells you to slow down, change lanes if possible, and pass with caution when a stopped vehicle shows flashing emergency or hazard lights.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Illinois, ¿qué le indica la Ley de Scott cuando se acerca a un vehículo detenido con luces de emergencia o intermitentes encendidas?","o":["Acelerar para pasar rápido","Bajar la velocidad y cambiar de carril si puede hacerlo con seguridad","Detenerse en su carril hasta que se vaya","Tocar el claxon para avisar a las personas"],"h1":"Esta ley también se llama ley de \"Move Over\" (cambie de carril).","h2":"La Ley de Scott en Illinois le indica bajar la velocidad, cambiar de carril si es posible y pasar con cuidado cuando un vehículo detenido tiene luces de emergencia o intermitentes.","p":"Correcto. Baje la velocidad y cámbiese de carril si puede hacerlo con seguridad."},"zh":{"q":"在 Illinois，当你靠近一辆闪着紧急灯或双闪灯的停着的车辆时，Scott's Law 要你做什么？","o":["加速快点开过去","减速，如果能安全换道就换道","在你的车道停下，直到它离开","按喇叭提醒那里的人"],"h1":"这条法律也叫做 Move Over 法。","h2":"Illinois 的 Scott's Law 要求，当停着的车辆闪着紧急灯或双闪灯时，你要减速，能换道就换道，并小心地开过去。","p":"对。能安全换道时，减速并换道让开。"},"vi":{"q":"Ở Illinois, Luật Scott (Scott's Law) bảo bạn làm gì khi đến gần một xe đang dừng có bật đèn khẩn cấp hoặc đèn cảnh báo nhấp nháy?","o":["Tăng tốc để vượt qua nhanh","Giảm tốc độ và đổi làn nếu có thể làm một cách an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Bóp còi để cảnh báo những người ở đó"],"h1":"Luật này cũng được gọi là luật Tránh Sang (Move Over).","h2":"Luật Scott ở Illinois bảo bạn giảm tốc độ, đổi làn nếu có thể, và đi qua cẩn thận khi một xe đang dừng bật đèn khẩn cấp hoặc đèn cảnh báo nhấp nháy.","p":"Đúng. Giảm tốc độ và tránh sang làn khác khi có thể làm an toàn."},"tl":{"q":"Sa Illinois, ano ang sinasabi ng Scott's Law na gawin mo kapag papalapit ka sa nakahintong sasakyan na may kumikislap na emergency o hazard lights?","o":["Bumilis para makalampas agad","Bumagal at lumipat ng lane kung ligtas mong magagawa","Huminto sa lane mo hanggang umalis ito","Bumusina para balaan ang mga tao roon"],"h1":"Tinatawag din ang batas na ito na Move Over law.","h2":"Sinasabi ng Scott's Law sa Illinois na bumagal ka, lumipat ng lane kung kaya, at dumaan nang maingat kapag may nakahintong sasakyan na may kumikislap na emergency o hazard lights.","p":"Tama. Bumagal at lumipat ng lane kapag ligtas mong magagawa."},"ar":{"q":"في Illinois، ماذا يطلب منك قانون سكوت (Scott's Law) أن تفعل عندما تقترب من مركبة متوقفة أضواء الطوارئ أو أضواء التحذير فيها تومض؟","o":["أسرع لتتجاوزها بسرعة","خفف السرعة وغيّر المسار إذا استطعت ذلك بأمان","توقف في مسارك حتى تغادر","استخدم البوق لتحذير الناس هناك"],"h1":"يُسمى هذا القانون أيضًا قانون الابتعاد (Move Over).","h2":"يطلب منك قانون سكوت في Illinois أن تخفف السرعة، وأن تغيّر المسار إذا أمكن، وأن تمر بحذر عندما تكون هناك مركبة متوقفة أضواء الطوارئ أو التحذير فيها تومض.","p":"صحيح. خفف السرعة وابتعد إلى مسار آخر عندما تستطيع ذلك بأمان."},"ref":{"doc":"IL","page":25}},{"id":"il-015","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, besides police and fire vehicles, which stopped vehicles does Scott's Law cover?","o":["Only tow trucks","Only buses","No other vehicles","Any vehicle with its hazard or warning lights flashing"],"h1":"Think of any car that has its flashers on.","h2":"In Illinois, the move-over rule also covers any stopped vehicle with its hazard or warning lights flashing, including ordinary cars and trucks.","p":"Right. Any stopped vehicle with flashing lights is covered."},"es":{"q":"En Illinois, además de policía y bomberos, ¿qué vehículos detenidos cubre la Ley de Scott?","o":["Solo grúas","Solo autobuses","Ningún otro vehículo","Cualquier vehículo con las luces intermitentes o de advertencia encendidas"],"h1":"Piense en cualquier carro con las luces intermitentes encendidas.","h2":"En Illinois, la regla de moverse a otro carril también cubre cualquier vehículo detenido con las luces intermitentes o de advertencia encendidas, incluidos carros y camiones comunes.","p":"Correcto. Cualquier vehículo detenido con luces intermitentes está cubierto."},"zh":{"q":"在 Illinois，除了警车和消防车，Scott's Law 还保护哪些停着的车辆？","o":["只有拖车","只有公交车","没有其他车辆","任何闪着双闪灯或警示灯的车辆"],"h1":"想一想任何开着闪灯的车。","h2":"在 Illinois，换道让开的规定也保护任何停着、闪着双闪灯或警示灯的车辆，包括普通的汽车和卡车。","p":"对。任何停着、闪着灯的车辆都受保护。"},"vi":{"q":"Ở Illinois, ngoài xe cảnh sát và xe cứu hỏa, Luật Scott còn áp dụng cho những xe đang dừng nào?","o":["Chỉ xe kéo","Chỉ xe buýt","Không có xe nào khác","Bất kỳ xe nào đang bật đèn cảnh báo nhấp nháy"],"h1":"Hãy nghĩ đến bất kỳ xe nào đang bật đèn nháy.","h2":"Ở Illinois, luật tránh sang cũng áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo nhấp nháy, kể cả xe hơi và xe tải bình thường.","p":"Đúng. Bất kỳ xe đang dừng nào có đèn nhấp nháy đều được áp dụng."},"tl":{"q":"Sa Illinois, bukod sa mga sasakyan ng pulis at bumbero, aling mga nakahintong sasakyan ang sakop ng Scott's Law?","o":["Mga tow truck lang","Mga bus lang","Walang ibang sasakyan","Anumang sasakyan na kumikislap ang hazard o warning lights"],"h1":"Isipin ang anumang kotse na nakabukas ang flashers.","h2":"Sa Illinois, sakop din ng move-over rule ang anumang nakahintong sasakyan na kumikislap ang hazard o warning lights, kasama ang mga karaniwang kotse at truck.","p":"Tama. Sakop ang anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Illinois، إلى جانب مركبات الشرطة والإطفاء، ما المركبات المتوقفة الأخرى التي يشملها قانون سكوت (Scott's Law)؟","o":["شاحنات السحب فقط","الحافلات فقط","لا توجد مركبات أخرى","أي مركبة أضواء التحذير فيها تومض"],"h1":"فكّر في أي سيارة أضواؤها الوامضة مشغّلة.","h2":"في Illinois، تشمل قاعدة الابتعاد أيضًا أي مركبة متوقفة أضواء التحذير فيها تومض، بما في ذلك السيارات والشاحنات العادية.","p":"صحيح. أي مركبة متوقفة أضواؤها تومض يشملها القانون."},"ref":{"doc":"IL","page":45}},{"id":"il-016","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, how far from a stopped school bus with its stop arm out must you stop?","o":["At least 20 feet","At least 5 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of a large car and a half.","h2":"In Illinois you must stop at least 20 feet before a school bus that has its red lights flashing and stop arm out.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Illinois, ¿a qué distancia de un autobús escolar detenido con el brazo de alto extendido debe detenerse?","o":["Por lo menos 20 pies","Por lo menos 5 pies","Por lo menos 50 pies","Por lo menos 100 pies"],"h1":"Es más o menos el largo de un carro grande y medio.","h2":"En Illinois usted debe detenerse por lo menos a 20 pies de un autobús escolar que tiene las luces rojas encendidas y el brazo de alto extendido.","p":"Correcto. Deténgase por lo menos a 20 pies."},"zh":{"q":"在 Illinois，你必须在离伸出停车臂的停着的校车多远的地方停车？","o":["至少 20 英尺","至少 5 英尺","至少 50 英尺","至少 100 英尺"],"h1":"大约是一辆半大汽车的长度。","h2":"在 Illinois，你必须在闪着红灯、伸出停车臂的校车前面至少 20 英尺的地方停车。","p":"对。至少在 20 英尺外停车。"},"vi":{"q":"Ở Illinois, bạn phải dừng lại cách xe buýt trường học đang dừng và giơ biển dừng (stop arm) bao xa?","o":["Ít nhất 20 feet","Ít nhất 5 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng chiều dài của một chiếc xe hơi lớn rưỡi.","h2":"Ở Illinois, bạn phải dừng lại cách ít nhất 20 feet trước xe buýt trường học đang bật đèn đỏ nhấp nháy và giơ biển dừng.","p":"Đúng. Dừng lại cách ít nhất 20 feet."},"tl":{"q":"Sa Illinois, gaano kalayo ka dapat huminto mula sa nakahintong school bus na nakalabas ang stop arm?","o":["Hindi bababa sa 20 feet","Hindi bababa sa 5 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet"],"h1":"Mga isa't kalahating haba ito ng malaking kotse.","h2":"Sa Illinois, dapat kang huminto nang hindi bababa sa 20 feet bago ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm.","p":"Tama. Huminto nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في Illinois، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة وذراع التوقف (stop arm) فيها ممدودة؟","o":["20 قدمًا على الأقل","5 أقدام على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"هي تقريبًا طول سيارة كبيرة ونصف.","h2":"في Illinois يجب أن تتوقف على بعد 20 قدمًا على الأقل قبل الحافلة المدرسية التي أضواؤها الحمراء تومض وذراع التوقف فيها ممدودة.","p":"صحيح. توقف على بعد 20 قدمًا على الأقل."},"ref":{"doc":"IL","page":null}},{"id":"il-017","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a school bus stops on a road with four or more lanes, two going each way. Who must stop?","o":["Everyone in both directions","Only drivers in the lane next to the bus","Only drivers going the same direction as the bus","No one, if the bus is on the shoulder"],"h1":"On a road this wide, the other side of the road is treated differently.","h2":"In Illinois, on a road with at least two lanes going each way, only drivers traveling in the same direction as the school bus must stop.","p":"Right. Only traffic going the same way as the bus must stop."},"es":{"q":"En Illinois, un autobús escolar se detiene en una vía de cuatro carriles o más, con dos en cada sentido. ¿Quién debe detenerse?","o":["Todos, en ambos sentidos","Solo los conductores en el carril junto al autobús","Solo los conductores que van en el mismo sentido que el autobús","Nadie, si el autobús está en el acotamiento"],"h1":"En una vía tan ancha, el otro lado del camino se trata de otra forma.","h2":"En Illinois, en una vía con por lo menos dos carriles en cada sentido, solo los conductores que van en el mismo sentido que el autobús escolar deben detenerse.","p":"Correcto. Solo el tráfico que va en el mismo sentido que el autobús debe detenerse."},"zh":{"q":"在 Illinois，一辆校车停在有四条或更多车道、每个方向两条车道的路上。谁必须停车？","o":["两个方向的所有人","只有校车旁边车道上的司机","只有和校车同方向行驶的司机","没有人，如果校车停在路肩上"],"h1":"在这么宽的路上，道路另一边的规定不一样。","h2":"在 Illinois，在每个方向至少有两条车道的路上，只有和校车同方向行驶的司机必须停车。","p":"对。只有和校车同方向的车必须停。"},"vi":{"q":"Ở Illinois, một xe buýt trường học dừng trên đường có bốn làn trở lên, mỗi chiều hai làn. Ai phải dừng lại?","o":["Mọi người ở cả hai chiều","Chỉ người lái ở làn sát xe buýt","Chỉ người lái đi cùng chiều với xe buýt","Không ai cả, nếu xe buýt đậu ở lề đường"],"h1":"Trên đường rộng như vậy, phía bên kia đường được đối xử khác.","h2":"Ở Illinois, trên đường có ít nhất hai làn mỗi chiều, chỉ người lái đi cùng chiều với xe buýt trường học mới phải dừng lại.","p":"Đúng. Chỉ xe đi cùng chiều với xe buýt mới phải dừng."},"tl":{"q":"Sa Illinois, huminto ang isang school bus sa kalsadang may apat o higit pang lane, dalawa sa bawat direksyon. Sino ang dapat huminto?","o":["Lahat sa dalawang direksyon","Ang mga driver lang sa lane na katabi ng bus","Ang mga driver lang na papunta sa parehong direksyon ng bus","Wala, kung nasa gilid ng daan ang bus"],"h1":"Sa ganito kalapad na kalsada, iba ang turing sa kabilang panig ng daan.","h2":"Sa Illinois, sa kalsadang may hindi bababa sa dalawang lane sa bawat direksyon, ang mga driver lang na papunta sa parehong direksyon ng school bus ang dapat huminto.","p":"Tama. Ang trapikong papunta lang sa parehong direksyon ng bus ang dapat huminto."},"ar":{"q":"في Illinois، توقفت حافلة مدرسية على طريق فيه أربعة مسارات أو أكثر، مساران في كل اتجاه. من يجب أن يتوقف؟","o":["الجميع في الاتجاهين","السائقون في المسار المجاور للحافلة فقط","السائقون الذين يسيرون في نفس اتجاه الحافلة فقط","لا أحد، إذا كانت الحافلة على كتف الطريق"],"h1":"في طريق بهذا العرض، يُعامَل الجانب الآخر من الطريق بشكل مختلف.","h2":"في Illinois، على طريق فيه مساران على الأقل في كل اتجاه، يجب أن يتوقف فقط السائقون الذين يسيرون في نفس اتجاه الحافلة المدرسية.","p":"صحيح. فقط السيارات التي تسير في نفس اتجاه الحافلة يجب أن تتوقف."},"ref":{"doc":"IL","page":32}},{"id":"il-018","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit in an urban district?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is a round number between 25 and 35.","h2":"Unless a sign says otherwise, the speed limit in an Illinois urban district is 30 miles per hour.","p":"Right. The Illinois urban limit is 30 mph."},"es":{"q":"En Illinois, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona urbana?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es un número redondo entre 25 y 35.","h2":"Si no hay un letrero que diga otra cosa, el límite de velocidad en una zona urbana de Illinois es de 30 millas por hora.","p":"Correcto. El límite urbano en Illinois es de 30 mph."},"zh":{"q":"在 Illinois，如果没有标志另外说明，市区的限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"是 25 和 35 之间的一个整数。","h2":"如果没有标志另外说明，Illinois 市区的限速是 30 mph。","p":"对。Illinois 市区的限速是 30 mph。"},"vi":{"q":"Ở Illinois, nếu không có biển báo nào khác, tốc độ giới hạn trong khu đô thị là bao nhiêu?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Đó là một số tròn giữa 25 và 35.","h2":"Nếu không có biển báo nào khác, tốc độ giới hạn trong khu đô thị ở Illinois là 30 dặm một giờ.","p":"Đúng. Giới hạn trong đô thị ở Illinois là 30 mph."},"tl":{"q":"Sa Illinois, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Isa itong buong numero sa pagitan ng 25 at 35.","h2":"Maliban kung iba ang sinasabi ng karatula, ang speed limit sa urban district sa Illinois ay 30 milya bawat oras.","p":"Tama. Ang limit sa urban na lugar sa Illinois ay 30 mph."},"ar":{"q":"في Illinois، ما لم تقل لافتة غير ذلك، ما حد السرعة في المنطقة الحضرية (urban district)؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"هو رقم مستدير بين 25 و35.","h2":"ما لم تقل لافتة غير ذلك، حد السرعة في المنطقة الحضرية في Illinois هو 30 ميلًا في الساعة.","p":"صحيح. الحد في المدن في Illinois هو 30 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-019","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, what is the speed limit in an alley?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is half of the urban limit.","h2":"The speed limit in an Illinois alley is 15 miles per hour.","p":"Right. Alleys in Illinois are 15 mph."},"es":{"q":"En Illinois, ¿cuál es el límite de velocidad en un callejón?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es la mitad del límite urbano.","h2":"El límite de velocidad en un callejón de Illinois es de 15 millas por hora.","p":"Correcto. En Illinois los callejones son de 15 mph."},"zh":{"q":"在 Illinois，小巷里的限速是多少？","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"是市区限速的一半。","h2":"Illinois 小巷里的限速是 15 mph。","p":"对。Illinois 的小巷是 15 mph。"},"vi":{"q":"Ở Illinois, tốc độ giới hạn trong hẻm là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Đó là một nửa giới hạn trong đô thị.","h2":"Tốc độ giới hạn trong hẻm ở Illinois là 15 dặm một giờ.","p":"Đúng. Hẻm ở Illinois là 15 mph."},"tl":{"q":"Sa Illinois, ano ang speed limit sa eskinita (alley)?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Kalahati ito ng limit sa urban na lugar.","h2":"Ang speed limit sa eskinita sa Illinois ay 15 milya bawat oras.","p":"Tama. 15 mph ang mga eskinita sa Illinois."},"ar":{"q":"في Illinois، ما حد السرعة في الزقاق (alley)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"هو نصف حد السرعة في المدينة.","h2":"حد السرعة في الزقاق في Illinois هو 15 ميلًا في الساعة.","p":"صحيح. الأزقة في Illinois حدها 15 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-020","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, outside urban districts, what is the general speed limit on roads that are not designated highways or interstates?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is ten less than the limit on designated four-lane divided highways.","h2":"Outside urban districts in Illinois, the general limit on ordinary roads that are not designated highways or interstates is 55 miles per hour.","p":"Right. Most rural Illinois roads are 55 mph."},"es":{"q":"En Illinois, fuera de las zonas urbanas, ¿cuál es el límite general en caminos que no son carreteras designadas ni interestatales?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es diez menos que el límite en carreteras divididas de cuatro carriles designadas.","h2":"Fuera de las zonas urbanas de Illinois, el límite general en caminos comunes que no son carreteras designadas ni interestatales es de 55 millas por hora.","p":"Correcto. La mayoría de los caminos rurales de Illinois son de 55 mph."},"zh":{"q":"在 Illinois，在市区以外，不是指定公路或州际公路的道路，一般限速是多少？","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"比指定的四车道分隔公路的限速少十。","h2":"在 Illinois 市区以外，不是指定公路或州际公路的普通道路，一般限速是 55 mph。","p":"对。Illinois 大多数乡村道路是 55 mph。"},"vi":{"q":"Ở Illinois, bên ngoài khu đô thị, tốc độ giới hạn chung trên những con đường không phải xa lộ được chỉ định hoặc xa lộ liên bang (interstate) là bao nhiêu?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Ít hơn mười so với giới hạn trên xa lộ bốn làn có dải phân cách được chỉ định.","h2":"Bên ngoài khu đô thị ở Illinois, giới hạn chung trên đường bình thường không phải xa lộ được chỉ định hoặc xa lộ liên bang là 55 dặm một giờ.","p":"Đúng. Phần lớn đường ở vùng nông thôn Illinois là 55 mph."},"tl":{"q":"Sa Illinois, sa labas ng mga urban district, ano ang pangkalahatang speed limit sa mga kalsadang hindi designated highway o interstate?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa mga designated na four-lane divided highway.","h2":"Sa labas ng mga urban district sa Illinois, ang pangkalahatang limit sa mga karaniwang kalsadang hindi designated highway o interstate ay 55 milya bawat oras.","p":"Tama. 55 mph ang karamihan ng mga kalsada sa probinsya ng Illinois."},"ar":{"q":"في Illinois، خارج المناطق الحضرية، ما حد السرعة العام على الطرق التي ليست طرقًا سريعة محددة أو طرقًا سريعة بين الولايات (interstate)؟","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"هو أقل بعشرة من الحد على الطرق السريعة المحددة ذات الأربعة مسارات والمقسومة.","h2":"خارج المناطق الحضرية في Illinois، الحد العام على الطرق العادية التي ليست طرقًا سريعة محددة أو طرقًا بين الولايات هو 55 ميلًا في الساعة.","p":"صحيح. معظم الطرق الريفية في Illinois حدها 55 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-021","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit on interstates and tollways?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"It is five more than the limit on four-lane highways.","h2":"Unless a sign says otherwise, the speed limit on Illinois interstates and tollways is 70 miles per hour.","p":"Right. Illinois interstates and tollways are 70 mph."},"es":{"q":"En Illinois, a menos que una señal indique otra cosa, ¿cuál es el límite de velocidad en las autopistas interestatales y de peaje?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Es cinco más que el límite en las carreteras de cuatro carriles.","h2":"A menos que una señal indique otra cosa, el límite de velocidad en las autopistas interestatales y de peaje de Illinois es de 70 millas por hora.","p":"Correcto. Las interestatales y autopistas de peaje de Illinois son de 70 mph."},"zh":{"q":"在 Illinois，如果没有标志另外说明，州际公路和收费公路的限速是多少？","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"比四车道公路的限速多五。","h2":"如果没有标志另外说明，Illinois 州际公路和收费公路的限速是 70 mph。","p":"对。Illinois 的州际公路和收费公路是 70 mph。"},"vi":{"q":"Ở Illinois, nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ liên bang (interstate) và đường thu phí (tollway) là bao nhiêu?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Nhiều hơn năm so với giới hạn trên xa lộ bốn làn.","h2":"Nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ liên bang và đường thu phí ở Illinois là 70 dặm một giờ.","p":"Đúng. Xa lộ liên bang và đường thu phí ở Illinois là 70 mph."},"tl":{"q":"Sa Illinois, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa mga interstate at tollway?","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"Lima itong mas mataas kaysa sa limit sa mga four-lane highway.","h2":"Maliban kung iba ang sinasabi ng karatula, ang speed limit sa mga interstate at tollway sa Illinois ay 70 milya bawat oras.","p":"Tama. 70 mph ang mga interstate at tollway sa Illinois."},"ar":{"q":"في Illinois، ما لم تقل لافتة غير ذلك، ما حد السرعة على الطرق السريعة بين الولايات (interstate) والطرق ذات الرسوم (tollway)؟","o":["70 mph","55 mph","65 mph","75 mph"],"h1":"هو أكثر بخمسة من الحد على الطرق السريعة ذات الأربعة مسارات.","h2":"ما لم تقل لافتة غير ذلك، حد السرعة على الطرق السريعة بين الولايات والطرق ذات الرسوم في Illinois هو 70 ميلًا في الساعة.","p":"صحيح. الطرق بين الولايات والطرق ذات الرسوم في Illinois حدها 70 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-022","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.05","Up to 0.02","None at all"],"h1":"Illinois calls this zero tolerance.","h2":"Under the Illinois zero tolerance law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Illinois, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.05","Hasta 0.02","Nada de alcohol"],"h1":"Illinois llama a esto tolerancia cero.","h2":"Según la ley de tolerancia cero de Illinois, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"zh":{"q":"在 Illinois，21 岁以下的司机血液里可以有多少酒精？","o":["最多 0.08","最多 0.05","最多 0.02","一点都不可以"],"h1":"Illinois 把这个规定叫做零容忍。","h2":"根据 Illinois 的零容忍法，21 岁以下的司机血液里有任何酒精都不能开车。","p":"对。21 岁以下，一点酒精都不可以。"},"vi":{"q":"Ở Illinois, người lái dưới 21 tuổi được có bao nhiêu cồn trong máu?","o":["Tối đa 0.08","Tối đa 0.05","Tối đa 0.02","Không có chút nào"],"h1":"Illinois gọi điều này là không khoan nhượng (zero tolerance).","h2":"Theo luật không khoan nhượng của Illinois, người lái dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, không được có chút cồn nào."},"tl":{"q":"Sa Illinois, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21?","o":["Hanggang 0.08","Hanggang 0.05","Hanggang 0.02","Wala talaga"],"h1":"Tinatawag ito ng Illinois na zero tolerance.","h2":"Ayon sa zero tolerance law ng Illinois, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa dugo.","p":"Tama. Kapag wala pang 21, bawal ang kahit kaunting alak."},"ar":{"q":"في Illinois، كم من الكحول يجوز أن يكون في دم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08","حتى 0.05","حتى 0.02","لا شيء أبدًا"],"h1":"تسمي Illinois هذا عدم التسامح (zero tolerance).","h2":"بموجب قانون عدم التسامح في Illinois، لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. تحت 21 سنة، لا كحول أبدًا."},"ref":{"doc":"IL","page":52}},{"id":"il-023","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what is the license suspension for a first zero tolerance violation by a driver under 21?","o":["One week","3 months","2 years","No suspension, only a warning"],"h1":"It is one quarter of a year.","h2":"In Illinois, a driver under 21 found with any alcohol while driving loses the license for at least three months.","p":"Right. A first violation means at least a three-month suspension."},"es":{"q":"En Illinois, ¿cuál es la suspensión de licencia por una primera violación de tolerancia cero de un conductor menor de 21?","o":["Una semana","3 meses","2 años","Ninguna, solo una advertencia"],"h1":"Es la cuarta parte de un año.","h2":"En Illinois, un conductor menor de 21 años que maneja con cualquier cantidad de alcohol pierde la licencia por al menos tres meses.","p":"Correcto. Una primera violación significa al menos tres meses de suspensión."},"zh":{"q":"在 Illinois，21 岁以下的司机第一次违反零容忍规定，驾照会被暂停多久？","o":["一个星期","3 个月","2 年","不暂停，只是警告"],"h1":"是四分之一年。","h2":"在 Illinois，21 岁以下的司机开车时被发现有任何酒精，驾照会被暂停至少三个月。","p":"对。第一次违规，驾照至少暂停三个月。"},"vi":{"q":"Ở Illinois, người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance) lần đầu bị treo bằng lái bao lâu?","o":["Một tuần","3 tháng","2 năm","Không bị treo, chỉ bị cảnh cáo"],"h1":"Đó là một phần tư của một năm.","h2":"Ở Illinois, người lái dưới 21 tuổi bị phát hiện có bất kỳ chút cồn nào khi lái xe sẽ bị mất bằng lái ít nhất ba tháng.","p":"Đúng. Vi phạm lần đầu nghĩa là bị treo bằng ít nhất ba tháng."},"tl":{"q":"Sa Illinois, gaano katagal ang suspensyon ng lisensya sa unang zero tolerance violation ng driver na wala pang 21?","o":["Isang linggo","3 buwan","2 taon","Walang suspensyon, babala lang"],"h1":"Isang-kapat ito ng isang taon.","h2":"Sa Illinois, ang driver na wala pang 21 na nahulihan ng kahit anong alak habang nagmamaneho ay mawawalan ng lisensya nang hindi bababa sa tatlong buwan.","p":"Tama. Ang unang violation ay nangangahulugan ng suspensyon na hindi bababa sa tatlong buwan."},"ar":{"q":"في Illinois، ما مدة إيقاف الرخصة في أول مخالفة لقانون عدم التسامح (zero tolerance) من سائق عمره أقل من 21 سنة؟","o":["أسبوع واحد","3 أشهر","سنتان","لا إيقاف، تحذير فقط"],"h1":"هي ربع سنة.","h2":"في Illinois، السائق الذي عمره أقل من 21 سنة ويوجد في دمه أي كحول أثناء القيادة يفقد رخصته ثلاثة أشهر على الأقل.","p":"صحيح. أول مخالفة تعني إيقاف الرخصة ثلاثة أشهر على الأقل."},"ref":{"doc":"IL","page":52}},{"id":"il-024","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, when all cars are insured and no one is hurt, above what amount of property damage must the driver file a crash report?","o":["$250","$500","$1,500","$5,000"],"h1":"It is between one thousand and two thousand dollars.","h2":"In Illinois, a driver must file a crash report when no one is hurt but the property damage is more than $1,500.","p":"Right. Damage over $1,500 means you must file a report."},"es":{"q":"En Illinois, cuando todos los autos tienen seguro y nadie está herido, ¿a partir de qué cantidad de daños a la propiedad debe el conductor presentar un informe del choque?","o":["$250","$500","$1,500","$5,000"],"h1":"Está entre mil y dos mil dólares.","h2":"En Illinois, el conductor debe presentar un informe del choque cuando nadie está herido pero los daños a la propiedad pasan de $1,500.","p":"Correcto. Con daños de más de $1,500 usted debe presentar un informe."},"zh":{"q":"在 Illinois，如果所有车辆都有保险，而且没有人受伤，财产损失超过多少钱时，司机必须提交事故报告？","o":["$250","$500","$1,500","$5,000"],"h1":"它在一千美元和两千美元之间。","h2":"在 Illinois，如果没有人受伤，但财产损失超过 $1,500，司机必须提交事故报告。","p":"对。损失超过 $1,500，你就必须提交报告。"},"vi":{"q":"Ở Illinois, khi tất cả xe đều có bảo hiểm và không ai bị thương, thiệt hại tài sản trên bao nhiêu thì tài xế phải nộp báo cáo tai nạn?","o":["$250","$500","$1,500","$5,000"],"h1":"Số tiền nằm trong khoảng từ một nghìn đến hai nghìn đô la.","h2":"Ở Illinois, tài xế phải nộp báo cáo tai nạn khi không ai bị thương nhưng thiệt hại tài sản trên $1,500.","p":"Đúng. Thiệt hại trên $1,500 thì bạn phải nộp báo cáo."},"tl":{"q":"Sa Illinois, kapag may insurance ang lahat ng sasakyan at walang nasaktan, lampas sa anong halaga ng pinsala sa ari-arian dapat mag-file ng crash report ang driver?","o":["$250","$500","$1,500","$5,000"],"h1":"Nasa pagitan ito ng isang libo at dalawang libong dolyar.","h2":"Sa Illinois, dapat mag-file ng crash report ang driver kapag walang nasaktan pero lampas sa $1,500 ang pinsala sa ari-arian.","p":"Tama. Kapag lampas sa $1,500 ang pinsala, dapat kang mag-file ng report."},"ar":{"q":"في Illinois، عندما تكون كل السيارات مؤمَّنة ولا يُصاب أحد، فوق أي مبلغ من الأضرار في الممتلكات يجب على السائق تقديم تقرير عن الحادث؟","o":["$250","$500","$1,500","$5,000"],"h1":"المبلغ بين ألف وألفي دولار.","h2":"في Illinois، يجب على السائق تقديم تقرير عن الحادث عندما لا يُصاب أحد ولكن الأضرار في الممتلكات أكثر من $1,500.","p":"صحيح. إذا كانت الأضرار أكثر من $1,500 فيجب أن تقدّم تقريرًا."},"ref":{"doc":"IL","page":54}},{"id":"il-025","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what is the minimum liability insurance a vehicle must carry?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Injury to one person is covered for twenty-five thousand dollars.","h2":"In Illinois, the minimum is $25,000 for one person hurt or killed, $50,000 for more than one person, and $20,000 for damage to property.","p":"Right. Illinois requires at least $25,000, $50,000 and $20,000 of coverage."},"es":{"q":"En Illinois, ¿cuál es el seguro de responsabilidad civil mínimo que debe tener un vehículo?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Las lesiones de una persona están cubiertas por veinticinco mil dólares.","h2":"En Illinois, el mínimo es $25,000 por una persona herida o muerta, $50,000 por más de una persona y $20,000 por daños a la propiedad.","p":"Correcto. Illinois exige al menos $25,000, $50,000 y $20,000 de cobertura."},"zh":{"q":"在 Illinois，车辆必须有的最低责任保险是多少？","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"一个人受伤的赔偿额是两万五千美元。","h2":"在 Illinois，最低保险是：一人受伤或死亡 $25,000，多于一人 $50,000，财产损失 $20,000。","p":"对。Illinois 要求至少 $25,000、$50,000 和 $20,000 的保险。"},"vi":{"q":"Ở Illinois, xe phải có bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Thương tích cho một người được bảo hiểm hai mươi lăm nghìn đô la.","h2":"Ở Illinois, mức tối thiểu là $25,000 khi một người bị thương hoặc chết, $50,000 khi nhiều hơn một người, và $20,000 cho thiệt hại tài sản.","p":"Đúng. Illinois yêu cầu bảo hiểm ít nhất $25,000, $50,000 và $20,000."},"tl":{"q":"Sa Illinois, ano ang pinakamababang liability insurance na dapat mayroon ang sasakyan?","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"Dalawampu't limang libong dolyar ang sakop para sa pinsala sa isang tao.","h2":"Sa Illinois, ang pinakamababa ay $25,000 para sa isang taong nasaktan o namatay, $50,000 para sa higit sa isang tao, at $20,000 para sa pinsala sa ari-arian.","p":"Tama. Hinihingi ng Illinois ang hindi bababa sa $25,000, $50,000 at $20,000 na coverage."},"ar":{"q":"في Illinois، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون للسيارة؟","o":["$25,000 / $50,000 / $20,000","$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$100,000 / $300,000 / $50,000"],"h1":"إصابة شخص واحد مغطاة بخمسة وعشرين ألف دولار.","h2":"في Illinois، الحد الأدنى هو $25,000 لإصابة أو وفاة شخص واحد، و$50,000 لأكثر من شخص، و$20,000 للأضرار في الممتلكات.","p":"صحيح. تطلب Illinois تأمينًا لا يقل عن $25,000 و$50,000 و$20,000."},"ref":{"doc":"IL","page":98}},{"id":"il-026","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, children under what age must ride in a child safety seat or booster seat?","o":["Under 2","Under 4","Under 12","Under 8"],"h1":"From this age on, the regular seat belt law applies.","h2":"In Illinois, all children under age 8 must be secured in a child safety seat or booster seat that fits them.","p":"Right. Children under 8 need a child safety seat or booster seat."},"es":{"q":"En Illinois, ¿los niños menores de qué edad deben ir en un asiento de seguridad infantil o un asiento elevado?","o":["Menores de 2","Menores de 4","Menores de 12","Menores de 8"],"h1":"A partir de esa edad se aplica la ley normal del cinturón de seguridad.","h2":"En Illinois, todos los niños menores de 8 años deben ir sujetos en un asiento de seguridad infantil o asiento elevado adecuado para ellos.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad infantil o asiento elevado."},"zh":{"q":"在 Illinois，多大年龄以下的儿童必须坐儿童安全座椅或增高座椅？","o":["2 岁以下","4 岁以下","12 岁以下","8 岁以下"],"h1":"从这个年龄开始，适用普通的安全带法律。","h2":"在 Illinois，所有 8 岁以下的儿童都必须坐在适合他们的儿童安全座椅或增高座椅里，并固定好。","p":"对。8 岁以下的儿童需要儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Illinois, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng?","o":["Dưới 2 tuổi","Dưới 4 tuổi","Dưới 12 tuổi","Dưới 8 tuổi"],"h1":"Từ tuổi này trở đi, luật dây an toàn thông thường được áp dụng.","h2":"Ở Illinois, tất cả trẻ em dưới 8 tuổi phải được giữ chặt trong ghế an toàn cho trẻ em hoặc ghế nâng vừa với các em.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn cho trẻ em hoặc ghế nâng."},"tl":{"q":"Sa Illinois, ang mga batang wala pa sa anong edad ang dapat nakaupo sa child safety seat o booster seat?","o":["Wala pang 2","Wala pang 4","Wala pang 12","Wala pang 8"],"h1":"Mula sa edad na ito, ang karaniwang batas sa seat belt na ang sinusunod.","h2":"Sa Illinois, lahat ng batang wala pang 8 taong gulang ay dapat nakakabit sa child safety seat o booster seat na akma sa kanila.","p":"Tama. Kailangan ng child safety seat o booster seat ang mga batang wala pang 8."},"ar":{"q":"في Illinois، الأطفال تحت أي عمر يجب أن يجلسوا في مقعد أمان للأطفال أو مقعد رافع؟","o":["تحت 2","تحت 4","تحت 12","تحت 8"],"h1":"من هذا العمر فما فوق، يُطبَّق قانون حزام الأمان العادي.","h2":"في Illinois، يجب تثبيت كل الأطفال تحت عمر 8 سنوات في مقعد أمان للأطفال أو مقعد رافع مناسب لهم.","p":"صحيح. الأطفال تحت 8 سنوات يحتاجون إلى مقعد أمان للأطفال أو مقعد رافع."},"ref":{"doc":"IL","page":23}},{"id":"il-027","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how many tries do you get to pass each exam after you pay the application fee?","o":["Two tries within six months","Three tries within one year","Five tries within one year","As many tries as you want"],"h1":"The time limit is one year from the day you paid.","h2":"In Illinois, you get three tries to pass each exam within one year from the date you paid the application fee.","p":"Right. You have three tries within one year."},"es":{"q":"En Illinois, ¿cuántos intentos tiene para aprobar cada examen después de pagar la tarifa de solicitud?","o":["Dos intentos en seis meses","Tres intentos en un año","Cinco intentos en un año","Todos los intentos que quiera"],"h1":"El plazo es de un año desde el día en que pagó.","h2":"En Illinois, usted tiene tres intentos para aprobar cada examen dentro de un año desde la fecha en que pagó la tarifa de solicitud.","p":"Correcto. Tiene tres intentos dentro de un año."},"zh":{"q":"在 Illinois，交了申请费以后，每项考试你有几次机会通过？","o":["六个月内两次","一年内三次","一年内五次","想考几次都可以"],"h1":"期限是从你交费那天起一年。","h2":"在 Illinois，从你交申请费那天起一年内，每项考试你有三次机会通过。","p":"对。你在一年内有三次机会。"},"vi":{"q":"Ở Illinois, sau khi trả phí nộp đơn, bạn có bao nhiêu lần thi để đậu mỗi bài thi?","o":["Hai lần trong vòng sáu tháng","Ba lần trong vòng một năm","Năm lần trong vòng một năm","Bao nhiêu lần cũng được"],"h1":"Thời hạn là một năm kể từ ngày bạn trả tiền.","h2":"Ở Illinois, bạn có ba lần thi để đậu mỗi bài thi trong vòng một năm kể từ ngày bạn trả phí nộp đơn.","p":"Đúng. Bạn có ba lần thi trong vòng một năm."},"tl":{"q":"Sa Illinois, ilang pagkakataon ang mayroon ka para pumasa sa bawat exam pagkatapos mong bayaran ang application fee?","o":["Dalawang pagkakataon sa loob ng anim na buwan","Tatlong pagkakataon sa loob ng isang taon","Limang pagkakataon sa loob ng isang taon","Kahit ilang beses mo gusto"],"h1":"Ang takdang panahon ay isang taon mula sa araw na nagbayad ka.","h2":"Sa Illinois, may tatlong pagkakataon ka para pumasa sa bawat exam sa loob ng isang taon mula sa petsa na binayaran mo ang application fee.","p":"Tama. May tatlong pagkakataon ka sa loob ng isang taon."},"ar":{"q":"في Illinois، كم محاولة لديك لتنجح في كل اختبار بعد أن تدفع رسوم الطلب؟","o":["محاولتان خلال ستة أشهر","ثلاث محاولات خلال سنة واحدة","خمس محاولات خلال سنة واحدة","عدد المحاولات الذي تريده"],"h1":"المهلة سنة واحدة من يوم الدفع.","h2":"في Illinois، لديك ثلاث محاولات لتنجح في كل اختبار خلال سنة واحدة من تاريخ دفع رسوم الطلب.","p":"صحيح. لديك ثلاث محاولات خلال سنة واحدة."},"ref":{"doc":"IL","page":13}},{"id":"il-028","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Fire trucks need room to hook up their hoses.","h2":"In Illinois, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Illinois, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Illinois, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Illinois，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"消防车需要地方接上水管。","h2":"在 Illinois，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Illinois, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Xe cứu hỏa cần chỗ để nối ống nước.","h2":"Ở Illinois, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Illinois, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 50 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para ikabit ang kanilang mga hose.","h2":"Sa Illinois, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في Illinois، إلى أي مدى يمكنك أن تركن سيارتك قرب حنفية إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مكان لتوصيل خراطيمها.","h2":"في Illinois لا يجوز لك أن تركن سيارتك على بعد أقل من 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من حنفية الإطفاء."},"ref":{"doc":"IL","page":35}},{"id":"il-030","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what happens if your vision tests between 20/41 and 20/70?","o":["You may drive only in daylight","You may not get a license at all","You may drive only on interstates","You get no limit on your license"],"h1":"The limit is about the time of day you may drive.","h2":"In Illinois, a driver whose vision is between 20/41 and 20/70 may drive only during daylight.","p":"Right. With that vision you may drive only in daylight."},"es":{"q":"En Illinois, ¿qué pasa si su prueba de la vista da entre 20/41 y 20/70?","o":["Solo puede manejar de día","No puede obtener licencia","Solo puede manejar en autopistas interestatales","Su licencia no tiene ningún límite"],"h1":"El límite tiene que ver con la hora del día en que puede manejar.","h2":"En Illinois, un conductor con una vista entre 20/41 y 20/70 solo puede manejar durante el día.","p":"Correcto. Con esa vista solo puede manejar de día."},"zh":{"q":"在 Illinois，如果你的视力检查结果在 20/41 到 20/70 之间，会怎么样？","o":["你只能在白天开车","你完全不能拿驾照","你只能在州际公路上开车","你的驾照没有任何限制"],"h1":"这个限制和你可以开车的时间有关。","h2":"在 Illinois，视力在 20/41 到 20/70 之间的司机只能在白天开车。","p":"对。这样的视力只能在白天开车。"},"vi":{"q":"Ở Illinois, điều gì xảy ra nếu kết quả kiểm tra thị lực của bạn nằm trong khoảng 20/41 đến 20/70?","o":["Bạn chỉ được lái xe vào ban ngày","Bạn hoàn toàn không được cấp bằng lái","Bạn chỉ được lái xe trên xa lộ liên bang","Bằng lái của bạn không có giới hạn nào"],"h1":"Giới hạn này liên quan đến thời gian trong ngày bạn được lái xe.","h2":"Ở Illinois, người lái xe có thị lực trong khoảng 20/41 đến 20/70 chỉ được lái xe vào ban ngày.","p":"Đúng. Với thị lực đó, bạn chỉ được lái xe vào ban ngày."},"tl":{"q":"Sa Illinois, ano ang mangyayari kung ang resulta ng vision test mo ay nasa pagitan ng 20/41 at 20/70?","o":["Puwede ka lang magmaneho kapag may liwanag ng araw","Hindi ka talaga makakakuha ng lisensya","Puwede ka lang magmaneho sa mga interstate","Walang limitasyon ang lisensya mo"],"h1":"Ang limitasyon ay tungkol sa oras ng araw na puwede kang magmaneho.","h2":"Sa Illinois, ang driver na may paningin na nasa pagitan ng 20/41 at 20/70 ay puwede lang magmaneho kapag may liwanag ng araw.","p":"Tama. Sa ganyang paningin, puwede ka lang magmaneho kapag may liwanag ng araw."},"ar":{"q":"في Illinois، ماذا يحدث إذا كانت نتيجة فحص نظرك بين 20/41 و 20/70؟","o":["يمكنك القيادة في النهار فقط","لا يمكنك الحصول على رخصة أبدًا","يمكنك القيادة على الطرق السريعة بين الولايات فقط","لا يوجد أي قيد على رخصتك"],"h1":"القيد له علاقة بالوقت من اليوم الذي يمكنك القيادة فيه.","h2":"في Illinois، السائق الذي نظره بين 20/41 و 20/70 يمكنه القيادة في النهار فقط.","p":"صحيح. مع هذا النظر يمكنك القيادة في النهار فقط."},"ref":{"doc":"IL","page":13}},{"id":"il-031","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, when you pass on a two-lane road, how far from an oncoming vehicle must you be back in your lane?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"The distance is more than half a football field.","h2":"In Illinois, you must be back in your own lane before you get within 200 feet of an oncoming vehicle.","p":"Right. Be back in your lane at least 200 feet before an oncoming vehicle."},"es":{"q":"En Illinois, al rebasar en un camino de dos carriles, ¿a qué distancia de un vehículo que viene de frente debe estar ya en su carril?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 500 pies"],"h1":"La distancia es más de la mitad de un campo de fútbol americano.","h2":"En Illinois, usted debe volver a su carril antes de quedar a menos de 200 pies de un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril al menos 200 pies antes del vehículo que viene."},"zh":{"q":"在 Illinois，你在双车道道路上超车时，必须在离对面来车多远之前回到自己的车道？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 500 英尺"],"h1":"这个距离比半个美式足球场还长。","h2":"在 Illinois，你必须在离对面来车 200 英尺以前回到自己的车道。","p":"对。在离对面来车至少 200 英尺时回到自己的车道。"},"vi":{"q":"Ở Illinois, khi vượt xe trên đường hai làn, bạn phải trở về làn của mình khi còn cách xe đi ngược chiều bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 500 feet"],"h1":"Khoảng cách này dài hơn nửa sân bóng bầu dục.","h2":"Ở Illinois, bạn phải trở về làn của mình trước khi đến gần xe đi ngược chiều trong vòng 200 feet.","p":"Đúng. Hãy trở về làn của mình khi còn cách xe đi ngược chiều ít nhất 200 feet."},"tl":{"q":"Sa Illinois, kapag nag-overtake ka sa kalsadang may dalawang lane, gaano kalayo sa paparating na sasakyan ka dapat nakabalik na sa lane mo?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 500 feet"],"h1":"Mas mahaba ang layo kaysa sa kalahati ng football field.","h2":"Sa Illinois, dapat nakabalik ka na sa sarili mong lane bago ka umabot sa loob ng 200 feet mula sa paparating na sasakyan.","p":"Tama. Bumalik sa lane mo nang hindi bababa sa 200 feet bago ang paparating na sasakyan."},"ar":{"q":"في Illinois، عندما تتجاوز على طريق له مساران، على أي مسافة من السيارة القادمة من الاتجاه المقابل يجب أن تكون قد رجعت إلى مسارك؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","500 قدم على الأقل"],"h1":"المسافة أكثر من نصف ملعب كرة القدم الأمريكية.","h2":"في Illinois يجب أن ترجع إلى مسارك قبل أن تصبح على بعد أقل من 200 قدم من السيارة القادمة من الاتجاه المقابل.","p":"صحيح. ارجع إلى مسارك قبل السيارة القادمة بـ 200 قدم على الأقل."},"ref":{"doc":"IL","page":28}},{"id":"il-032","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, you move here with a valid license from another state. How soon must you get an Illinois license?","o":["Within 10 days","Within 30 days","Within 90 days","Within 1 year"],"h1":"You get about three months, unless your old license runs out first.","h2":"A new Illinois resident must get an Illinois license within 90 days, or sooner if the old license expires first.","p":"Right. New residents have 90 days."},"es":{"q":"En Illinois, usted se muda aquí con una licencia válida de otro estado. ¿En cuánto tiempo debe sacar una licencia de Illinois?","o":["En 10 días","En 30 días","En 90 días","En 1 año"],"h1":"Tiene unos tres meses, a menos que su licencia anterior venza antes.","h2":"Un nuevo residente de Illinois debe sacar una licencia de Illinois en 90 días, o antes si la licencia anterior vence primero.","p":"Correcto. Los nuevos residentes tienen 90 días."},"zh":{"q":"在 Illinois，你带着另一个州的有效驾照搬到这里。你必须多快拿到 Illinois 驾照？","o":["10 天内","30 天内","90 天内","1 年内"],"h1":"大约有三个月，除非你的旧驾照先过期。","h2":"Illinois 的新居民必须在 90 天内拿到 Illinois 驾照；如果旧驾照更早过期，就要更早办。","p":"对。新居民有 90 天。"},"vi":{"q":"Ở Illinois, bạn chuyển đến đây với bằng lái còn hiệu lực của một tiểu bang khác. Bạn phải lấy bằng lái Illinois trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 90 ngày","Trong vòng 1 năm"],"h1":"Bạn có khoảng ba tháng, trừ khi bằng lái cũ hết hạn trước.","h2":"Cư dân mới của Illinois phải lấy bằng lái Illinois trong vòng 90 ngày, hoặc sớm hơn nếu bằng lái cũ hết hạn trước.","p":"Đúng. Cư dân mới có 90 ngày."},"tl":{"q":"Sa Illinois, lumipat ka rito na may valid na lisensya mula sa ibang estado. Gaano kabilis ka dapat kumuha ng lisensya ng Illinois?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 90 araw","Sa loob ng 1 taon"],"h1":"May mga tatlong buwan ka, maliban kung mauna nang mag-expire ang luma mong lisensya.","h2":"Ang bagong residente ng Illinois ay dapat kumuha ng lisensya ng Illinois sa loob ng 90 araw, o mas maaga kung mauna nang mag-expire ang lumang lisensya.","p":"Tama. May 90 araw ang mga bagong residente."},"ar":{"q":"في Illinois، انتقلت إلى هنا ومعك رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة Illinois؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 90 يومًا","خلال سنة واحدة"],"h1":"لديك نحو ثلاثة أشهر، إلا إذا انتهت رخصتك القديمة قبل ذلك.","h2":"يجب على المقيم الجديد في Illinois أن يحصل على رخصة Illinois خلال 90 يومًا، أو قبل ذلك إذا انتهت الرخصة القديمة أولًا.","p":"صحيح. لدى المقيمين الجدد 90 يومًا."},"ref":{"doc":"IL","page":5}},{"id":"il-033","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, after you move to a new address, how soon must you tell the Secretary of State?","o":["Within 10 days","Within 30 days","Within 60 days","Within 6 months"],"h1":"It is a short time, less than two weeks.","h2":"In Illinois, you must report a change of address to the Secretary of State within 10 days of moving.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Illinois, después de mudarse a una nueva dirección, ¿en cuánto tiempo debe avisar a la Secretaría de Estado?","o":["En 10 días","En 30 días","En 60 días","En 6 meses"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Illinois, usted debe informar un cambio de dirección a la Secretaría de Estado en 10 días después de mudarse.","p":"Correcto. Informe su nueva dirección en 10 días."},"zh":{"q":"在 Illinois，你搬到新地址以后，必须多快通知 Secretary of State？","o":["10 天内","30 天内","60 天内","6 个月内"],"h1":"时间很短，不到两个星期。","h2":"在 Illinois，你搬家以后必须在 10 天内把地址变更报告给 Secretary of State。","p":"对。要在 10 天内报告新地址。"},"vi":{"q":"Ở Illinois, sau khi chuyển đến địa chỉ mới, bạn phải báo cho Secretary of State trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 6 tháng"],"h1":"Đó là một khoảng thời gian ngắn, chưa đến hai tuần.","h2":"Ở Illinois, bạn phải báo việc đổi địa chỉ cho Secretary of State trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Illinois, pagkatapos mong lumipat sa bagong address, gaano kabilis mo dapat sabihan ang Secretary of State?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 6 na buwan"],"h1":"Maikling panahon ito, wala pang dalawang linggo.","h2":"Sa Illinois, dapat mong i-report sa Secretary of State ang pagbabago ng address sa loob ng 10 araw pagkatapos lumipat.","p":"Tama. I-report ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Illinois، بعد أن تنتقل إلى عنوان جديد، خلال كم من الوقت يجب أن تُبلغ Secretary of State؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","خلال 6 أشهر"],"h1":"إنها مدة قصيرة، أقل من أسبوعين.","h2":"في Illinois يجب أن تُبلغ Secretary of State بتغيير عنوانك خلال 10 أيام من انتقالك.","p":"صحيح. أبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"IL","page":6}},{"id":"il-034","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, for most adult drivers, how long is a driver's license valid?","o":["2 years","4 years","6 years","8 years"],"h1":"Drivers over 80 renew more often than most adults.","h2":"For most adult drivers in Illinois, a driver's license is valid for four years and expires on the driver's birthday.","p":"Right. Most Illinois licenses last four years."},"es":{"q":"En Illinois, para la mayoría de los conductores adultos, ¿por cuánto tiempo es válida la licencia de conducir?","o":["2 años","4 años","6 años","8 años"],"h1":"Los conductores mayores de 80 años renuevan más seguido que la mayoría de los adultos.","h2":"Para la mayoría de los conductores adultos en Illinois, la licencia de conducir es válida por cuatro años y vence el día del cumpleaños del conductor.","p":"Correcto. La mayoría de las licencias de Illinois duran cuatro años."},"zh":{"q":"在 Illinois，对大多数成年司机来说，驾照有效期是多久？","o":["2 年","4 年","6 年","8 年"],"h1":"80 岁以上的司机比大多数成年人更常换驾照。","h2":"在 Illinois，大多数成年司机的驾照有效期是四年，在司机生日那天到期。","p":"对。Illinois 大多数驾照有效四年。"},"vi":{"q":"Ở Illinois, với hầu hết người lái xe trưởng thành, bằng lái có hiệu lực bao lâu?","o":["2 năm","4 năm","6 năm","8 năm"],"h1":"Người lái trên 80 tuổi phải gia hạn thường xuyên hơn hầu hết người lớn.","h2":"Với hầu hết người lái xe trưởng thành ở Illinois, bằng lái có hiệu lực bốn năm và hết hạn vào ngày sinh nhật của người lái.","p":"Đúng. Hầu hết bằng lái Illinois có hiệu lực bốn năm."},"tl":{"q":"Sa Illinois, para sa karamihan ng adult na driver, gaano katagal valid ang driver's license?","o":["2 taon","4 na taon","6 na taon","8 taon"],"h1":"Mas madalas mag-renew ang mga driver na lampas 80 kaysa sa karamihan ng adult.","h2":"Para sa karamihan ng adult na driver sa Illinois, valid ang driver's license nang apat na taon at mag-e-expire ito sa kaarawan ng driver.","p":"Tama. Apat na taon ang karamihan ng lisensya sa Illinois."},"ar":{"q":"في Illinois، بالنسبة لمعظم السائقين البالغين، ما مدة صلاحية رخصة القيادة؟","o":["سنتان","4 سنوات","6 سنوات","8 سنوات"],"h1":"السائقون الذين أعمارهم فوق 80 سنة يجددون رخصتهم أكثر من معظم البالغين.","h2":"بالنسبة لمعظم السائقين البالغين في Illinois، رخصة القيادة صالحة لمدة أربع سنوات وتنتهي في يوم ميلاد السائق.","p":"صحيح. معظم رخص Illinois صالحة أربع سنوات."},"ref":{"doc":"IL","page":8}},{"id":"il-035","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, when does a license issued to a driver under 21 expire?","o":["3 months after the 21st birthday","On the 21st birthday","On the 18th birthday","1 year after the 21st birthday"],"h1":"It is a little while after the driver turns 21.","h2":"In Illinois, a license issued to a driver under 21 expires three months after the driver's 21st birthday.","p":"Right. It expires three months after turning 21."},"es":{"q":"En Illinois, ¿cuándo vence la licencia de un conductor menor de 21 años?","o":["3 meses después de cumplir 21 años","El día que cumple 21 años","El día que cumple 18 años","1 año después de cumplir 21 años"],"h1":"Es un poco después de que el conductor cumple 21 años.","h2":"En Illinois, la licencia de un conductor menor de 21 años vence tres meses después de que cumple 21 años.","p":"Correcto. Vence tres meses después de cumplir 21."},"zh":{"q":"在 Illinois，发给 21 岁以下司机的驾照什么时候到期？","o":["21 岁生日后 3 个月","21 岁生日那天","18 岁生日那天","21 岁生日后 1 年"],"h1":"是在司机满 21 岁以后不久。","h2":"在 Illinois，发给 21 岁以下司机的驾照在司机 21 岁生日后三个月到期。","p":"对。满 21 岁后三个月到期。"},"vi":{"q":"Ở Illinois, bằng lái cấp cho người lái dưới 21 tuổi hết hạn khi nào?","o":["3 tháng sau sinh nhật 21 tuổi","Vào sinh nhật 21 tuổi","Vào sinh nhật 18 tuổi","1 năm sau sinh nhật 21 tuổi"],"h1":"Đó là một thời gian ngắn sau khi người lái tròn 21 tuổi.","h2":"Ở Illinois, bằng lái cấp cho người lái dưới 21 tuổi hết hạn ba tháng sau sinh nhật 21 tuổi của người lái.","p":"Đúng. Bằng hết hạn ba tháng sau khi tròn 21 tuổi."},"tl":{"q":"Sa Illinois, kailan mag-e-expire ang lisensyang ibinigay sa driver na wala pang 21?","o":["3 buwan pagkatapos ng ika-21 kaarawan","Sa ika-21 kaarawan","Sa ika-18 kaarawan","1 taon pagkatapos ng ika-21 kaarawan"],"h1":"Hindi nagtatagal ito pagkatapos mag-21 ang driver.","h2":"Sa Illinois, ang lisensyang ibinigay sa driver na wala pang 21 ay mag-e-expire tatlong buwan pagkatapos ng ika-21 kaarawan ng driver.","p":"Tama. Mag-e-expire ito tatlong buwan pagkatapos mag-21."},"ar":{"q":"في Illinois، متى تنتهي الرخصة التي تُعطى لسائق عمره أقل من 21 سنة؟","o":["بعد 3 أشهر من عيد ميلاده الـ 21","في عيد ميلاده الـ 21","في عيد ميلاده الـ 18","بعد سنة واحدة من عيد ميلاده الـ 21"],"h1":"إنها بعد وقت قصير من بلوغ السائق 21 سنة.","h2":"في Illinois، الرخصة التي تُعطى لسائق عمره أقل من 21 سنة تنتهي بعد ثلاثة أشهر من عيد ميلاده الـ 21.","p":"صحيح. تنتهي بعد ثلاثة أشهر من بلوغ 21 سنة."},"ref":{"doc":"IL","page":8}},{"id":"il-036","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how long is an instruction permit valid for a driver under 18?","o":["6 months","12 months","18 months","24 months"],"h1":"It lasts longer than the nine months a teen must hold it. A permit for an adult 18 or older is shorter.","h2":"In Illinois, an instruction permit issued to a driver under 18 is valid for 24 months.","p":"Right. A teen's permit is good for 24 months."},"es":{"q":"En Illinois, ¿por cuánto tiempo es válido el permiso de aprendizaje de un conductor menor de 18 años?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Dura más que los nueve meses que un adolescente debe tenerlo. El permiso de un adulto de 18 años o más dura menos.","h2":"En Illinois, el permiso de aprendizaje de un conductor menor de 18 años es válido por 24 meses.","p":"Correcto. El permiso de un adolescente es válido por 24 meses."},"zh":{"q":"在 Illinois，18 岁以下司机的学习驾照有效期是多久？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"它比青少年必须持有的九个月更长。18 岁或以上成年人的学习驾照有效期更短。","h2":"在 Illinois，发给 18 岁以下司机的学习驾照有效期是 24 个月。","p":"对。青少年的学习驾照有效期是 24 个月。"},"vi":{"q":"Ở Illinois, giấy phép tập lái của người lái dưới 18 tuổi có giá trị trong bao lâu?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Nó dài hơn chín tháng mà người trẻ phải giữ giấy phép. Giấy phép của người lớn từ 18 tuổi trở lên thì ngắn hơn.","h2":"Ở Illinois, giấy phép tập lái cấp cho người lái dưới 18 tuổi có giá trị trong 24 tháng.","p":"Đúng. Giấy phép tập lái của người trẻ có giá trị 24 tháng."},"tl":{"q":"Sa Illinois, gaano katagal valid ang instruction permit ng driver na wala pang 18?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Mas mahaba ito kaysa sa siyam na buwang dapat hawakan ito ng teen. Mas maikli ang permit ng adult na 18 pataas.","h2":"Sa Illinois, valid nang 24 na buwan ang instruction permit na ibinigay sa driver na wala pang 18.","p":"Tama. Valid nang 24 na buwan ang permit ng teen."},"ar":{"q":"في Illinois، ما مدة صلاحية تصريح التعلّم للسائق الذي عمره أقل من 18 سنة؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"المدة أطول من الأشهر التسعة التي يجب أن يحمل فيها المراهق التصريح. أما تصريح البالغ الذي عمره 18 سنة أو أكثر فمدته أقصر.","h2":"في Illinois، تصريح التعلّم الذي يُعطى للسائق الذي عمره أقل من 18 سنة صالح لمدة 24 شهرًا.","p":"صحيح. تصريح المراهق صالح لمدة 24 شهرًا."},"ref":{"doc":"IL","page":16}},{"id":"il-037","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, an 18-year-old has never been licensed and never took driver education. What must they finish before getting a license?","o":["A 30-hour classroom course","A 6-hour adult driver education course","A short online safety video","Nothing, because they are 18"],"h1":"There is a special course for new drivers ages 18 to 20.","h2":"In Illinois, a first-time applicant age 18, 19 or 20 who never took driver education must complete a six-hour Adult Driver Education Course.","p":"Right. They need the 6-hour adult course."},"es":{"q":"En Illinois, una persona de 18 años nunca ha tenido licencia ni tomó educación vial. ¿Qué debe completar antes de obtener una licencia?","o":["Un curso de 30 horas en el aula","Un curso de educación vial para adultos de 6 horas","Un video corto de seguridad en línea","Nada, porque tiene 18 años"],"h1":"Hay un curso especial para conductores nuevos de 18 a 20 años.","h2":"En Illinois, una persona de 18, 19 o 20 años que solicita su primera licencia y nunca tomó educación vial debe completar un curso de educación vial para adultos de seis horas.","p":"Correcto. Necesita el curso para adultos de 6 horas."},"zh":{"q":"在 Illinois，一个 18 岁的人从来没有拿过驾照，也从来没有上过驾驶教育课。拿驾照以前，他必须完成什么？","o":["一门 30 小时的课堂课程","一门 6 小时的成人驾驶教育课程","一段简短的网上安全视频","什么都不用，因为他已经 18 岁"],"h1":"有一门专门为 18 到 20 岁新司机开的课程。","h2":"在 Illinois，第一次申请驾照、年龄 18、19 或 20 岁、而且从来没有上过驾驶教育课的人，必须完成六小时的成人驾驶教育课程（Adult Driver Education Course）。","p":"对。他们需要上 6 小时的成人课程。"},"vi":{"q":"Ở Illinois, một người 18 tuổi chưa bao giờ có bằng lái và chưa bao giờ học lái xe. Họ phải hoàn thành điều gì trước khi lấy bằng lái?","o":["Một khóa học 30 giờ trong lớp","Một khóa giáo dục lái xe cho người lớn 6 giờ","Một video an toàn ngắn trên mạng","Không cần gì, vì họ đã 18 tuổi"],"h1":"Có một khóa học đặc biệt cho người mới lái từ 18 đến 20 tuổi.","h2":"Ở Illinois, người nộp đơn lần đầu ở tuổi 18, 19 hoặc 20 mà chưa bao giờ học lái xe phải hoàn thành khóa giáo dục lái xe cho người lớn (Adult Driver Education Course) sáu giờ.","p":"Đúng. Họ cần khóa học 6 giờ cho người lớn."},"tl":{"q":"Sa Illinois, ang isang 18 taong gulang ay hindi pa nagkaroon ng lisensya at hindi pa kumuha ng driver education. Ano ang dapat niyang tapusin bago kumuha ng lisensya?","o":["Isang 30-oras na kurso sa classroom","Isang 6-na-oras na adult driver education course","Isang maikling online na safety video","Wala, dahil 18 na siya"],"h1":"May espesyal na kurso para sa mga bagong driver na edad 18 hanggang 20.","h2":"Sa Illinois, ang unang beses na aplikante na edad 18, 19 o 20 na hindi kailanman kumuha ng driver education ay dapat tumapos ng anim na oras na Adult Driver Education Course.","p":"Tama. Kailangan nila ang 6-na-oras na adult course."},"ar":{"q":"في Illinois، شخص عمره 18 سنة لم يحصل على رخصة من قبل ولم يأخذ دروس تعليم القيادة أبدًا. ماذا يجب أن يُكمل قبل الحصول على رخصة؟","o":["دورة في الصف مدتها 30 ساعة","دورة تعليم قيادة للبالغين مدتها 6 ساعات","فيديو قصير عن السلامة على الإنترنت","لا شيء، لأن عمره 18 سنة"],"h1":"توجد دورة خاصة للسائقين الجدد من عمر 18 إلى 20 سنة.","h2":"في Illinois، المتقدم لأول مرة الذي عمره 18 أو 19 أو 20 سنة ولم يأخذ دروس تعليم القيادة أبدًا يجب أن يُكمل دورة تعليم القيادة للبالغين (Adult Driver Education Course) ومدتها ست ساعات.","p":"صحيح. يحتاجون إلى دورة البالغين ذات الـ 6 ساعات."},"ref":{"doc":"IL","page":18}},{"id":"il-038","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a driver under 21 is convicted of two moving violations within 24 months. What happens?","o":["Only a warning letter","A fine, but no effect on the license","The license is revoked for life","A license suspension of at least 30 days"],"h1":"Young drivers lose their license sooner than adults do.","h2":"In Illinois, a driver under 21 with two or more moving violation convictions within 24 months faces a suspension of at least 30 days.","p":"Right. At least a 30-day suspension."},"es":{"q":"En Illinois, un conductor menor de 21 años es declarado culpable de dos infracciones de tránsito en 24 meses. ¿Qué pasa?","o":["Solo recibe una carta de advertencia","Paga una multa, sin efecto en la licencia","Le revocan la licencia de por vida","Le suspenden la licencia por al menos 30 días"],"h1":"Los conductores jóvenes pierden la licencia más pronto que los adultos.","h2":"En Illinois, un conductor menor de 21 años con dos o más condenas por infracciones de tránsito en 24 meses recibe una suspensión de al menos 30 días.","p":"Correcto. Una suspensión de al menos 30 días."},"zh":{"q":"在 Illinois，一个 21 岁以下的司机在 24 个月内因两次行车违规被定罪。会怎么样？","o":["只收到一封警告信","罚款，但不影响驾照","驾照被终身吊销","驾照被暂停至少 30 天"],"h1":"年轻司机比成年人更快失去驾照。","h2":"在 Illinois，21 岁以下的司机如果在 24 个月内有两次或更多行车违规定罪，驾照会被暂停至少 30 天。","p":"对。至少暂停 30 天。"},"vi":{"q":"Ở Illinois, một người lái dưới 21 tuổi bị kết tội hai lần vi phạm khi lái xe trong vòng 24 tháng. Điều gì xảy ra?","o":["Chỉ nhận một thư cảnh cáo","Bị phạt tiền, nhưng không ảnh hưởng đến bằng lái","Bị thu hồi bằng lái suốt đời","Bị đình chỉ bằng lái ít nhất 30 ngày"],"h1":"Người lái trẻ bị mất bằng lái nhanh hơn người lớn.","h2":"Ở Illinois, người lái dưới 21 tuổi bị kết tội hai lần vi phạm khi lái xe trở lên trong vòng 24 tháng sẽ bị đình chỉ bằng lái ít nhất 30 ngày.","p":"Đúng. Bị đình chỉ ít nhất 30 ngày."},"tl":{"q":"Sa Illinois, ang driver na wala pang 21 ay nahatulan ng dalawang moving violation sa loob ng 24 na buwan. Ano ang mangyayari?","o":["Isang warning letter lang","Multa, pero walang epekto sa lisensya","Babawiin ang lisensya habambuhay","Suspensyon ng lisensya nang hindi bababa sa 30 araw"],"h1":"Mas maagang nawawalan ng lisensya ang mga batang driver kaysa sa mga adult.","h2":"Sa Illinois, ang driver na wala pang 21 na may dalawa o higit pang conviction sa moving violation sa loob ng 24 na buwan ay masususpinde nang hindi bababa sa 30 araw.","p":"Tama. Suspensyon nang hindi bababa sa 30 araw."},"ar":{"q":"في Illinois، سائق عمره أقل من 21 سنة أُدين بمخالفتين مروريتين أثناء القيادة خلال 24 شهرًا. ماذا يحدث؟","o":["رسالة تحذير فقط","غرامة، ولكن بلا أثر على الرخصة","تُسحب الرخصة مدى الحياة","تُوقف الرخصة 30 يومًا على الأقل"],"h1":"السائقون الصغار يفقدون رخصتهم أسرع من البالغين.","h2":"في Illinois، السائق الذي عمره أقل من 21 سنة وأُدين بمخالفتين مروريتين أو أكثر خلال 24 شهرًا تُوقف رخصته 30 يومًا على الأقل.","p":"صحيح. إيقاف لمدة 30 يومًا على الأقل."},"ref":{"doc":"IL","page":20}},{"id":"il-039","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, unless a sign says otherwise, what is the speed limit on a highway with four lanes?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is lower than on interstates but higher than on other rural roads.","h2":"Unless a sign says otherwise, the speed limit on an Illinois highway with four lanes is 65 miles per hour.","p":"Right. Four-lane highways are 65 mph."},"es":{"q":"En Illinois, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una carretera de cuatro carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es menor que en las interestatales, pero mayor que en otras carreteras rurales.","h2":"Si no hay un letrero que diga otra cosa, el límite de velocidad en una carretera de cuatro carriles de Illinois es de 65 millas por hora.","p":"Correcto. Las carreteras de cuatro carriles son de 65 mph."},"zh":{"q":"在 Illinois，如果没有标志另外说明，四车道公路的限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"比州际公路低，但比其他乡村道路高。","h2":"如果没有标志另外说明，Illinois 四车道公路的限速是 65 mph。","p":"对。四车道公路限速 65 mph。"},"vi":{"q":"Ở Illinois, nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ có bốn làn xe là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Thấp hơn trên xa lộ liên bang nhưng cao hơn trên các đường nông thôn khác.","h2":"Nếu không có biển báo nào khác, tốc độ giới hạn trên xa lộ bốn làn xe ở Illinois là 65 dặm một giờ.","p":"Đúng. Xa lộ bốn làn xe là 65 mph."},"tl":{"q":"Sa Illinois, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa highway na may apat na lane?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa mga interstate pero mas mataas kaysa sa ibang kalsada sa probinsya.","h2":"Maliban kung iba ang sinasabi ng karatula, ang speed limit sa highway na may apat na lane sa Illinois ay 65 milya bawat oras.","p":"Tama. 65 mph ang mga highway na may apat na lane."},"ar":{"q":"في Illinois، ما لم تقل لافتة غير ذلك، ما حد السرعة على الطريق السريع الذي فيه أربعة مسارات؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"إنه أقل من حد الطرق السريعة بين الولايات، لكنه أعلى من حد الطرق الريفية الأخرى.","h2":"ما لم تقل لافتة غير ذلك، حد السرعة على الطريق السريع ذي الأربعة مسارات في Illinois هو 65 ميلًا في الساعة.","p":"صحيح. حد الطرق ذات الأربعة مسارات هو 65 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-040","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, what is the speed limit in a posted school zone on a school day when children are present?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"It is slower than the usual city limit of 30 mph.","h2":"In Illinois, you must slow to 20 miles per hour in a posted school zone on school days when children are present.","p":"Right. School zones are 20 mph."},"es":{"q":"En Illinois, ¿cuál es el límite de velocidad en una zona escolar señalizada, en un día de clases, cuando hay niños presentes?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Es más lento que el límite normal de la ciudad, que es de 30 mph.","h2":"En Illinois, usted debe bajar a 20 millas por hora en una zona escolar señalizada los días de clases cuando hay niños presentes.","p":"Correcto. Las zonas escolares son de 20 mph."},"zh":{"q":"在 Illinois，在上学日、有孩子在场时，有标志的学校区域限速是多少？","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"比一般市区限速 30 mph 慢。","h2":"在 Illinois，在上学日有孩子在场时，你必须在有标志的学校区域减速到 20 mph。","p":"对。学校区域限速 20 mph。"},"vi":{"q":"Ở Illinois, tốc độ giới hạn trong khu vực trường học có biển báo vào ngày đi học khi có trẻ em là bao nhiêu?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Chậm hơn giới hạn thông thường trong thành phố là 30 mph.","h2":"Ở Illinois, bạn phải giảm tốc độ xuống 20 dặm một giờ trong khu vực trường học có biển báo vào ngày đi học khi có trẻ em.","p":"Đúng. Khu vực trường học là 20 mph."},"tl":{"q":"Sa Illinois, ano ang speed limit sa may karatulang school zone sa araw ng pasok kapag may mga bata?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Mas mabagal ito kaysa sa karaniwang limit sa lungsod na 30 mph.","h2":"Sa Illinois, dapat kang bumagal sa 20 milya bawat oras sa may karatulang school zone sa araw ng pasok kapag may mga bata.","p":"Tama. 20 mph ang mga school zone."},"ar":{"q":"في Illinois، ما حد السرعة في منطقة مدرسية عليها لافتة، في يوم دراسي عندما يكون الأطفال موجودين؟","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"إنه أبطأ من الحد المعتاد في المدينة وهو 30 mph.","h2":"في Illinois يجب أن تُبطئ إلى 20 ميلًا في الساعة في المنطقة المدرسية التي عليها لافتة، في الأيام الدراسية عندما يكون الأطفال موجودين.","p":"صحيح. حد المناطق المدرسية هو 20 mph."},"ref":{"doc":"IL","page":24}},{"id":"il-041","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, when must you obey the posted speed limit in a construction zone?","o":["At all times, day and night","Only when workers are present","Only during daylight hours","Only on weekdays"],"h1":"Road work dangers do not go away when the workers go home.","h2":"In Illinois, you must obey the posted construction zone speed limit 24 hours a day, seven days a week, even when no workers are there.","p":"Right. The work zone limit applies all the time."},"es":{"q":"En Illinois, ¿cuándo debe obedecer el límite de velocidad señalizado en una zona de construcción?","o":["Siempre, de día y de noche","Solo cuando hay trabajadores","Solo durante el día","Solo de lunes a viernes"],"h1":"Los peligros de la obra no desaparecen cuando los trabajadores se van a casa.","h2":"En Illinois, usted debe obedecer el límite de velocidad señalizado en una zona de construcción las 24 horas del día, los siete días de la semana, aunque no haya trabajadores.","p":"Correcto. El límite de la zona de obras se aplica siempre."},"zh":{"q":"在 Illinois，什么时候必须遵守施工区域标出的限速？","o":["任何时候，白天和晚上都要","只在有工人在场时","只在白天","只在工作日"],"h1":"工人回家以后，道路施工的危险并没有消失。","h2":"在 Illinois，你必须一天 24 小时、一周七天都遵守施工区域标出的限速，即使那里没有工人。","p":"对。施工区域限速一直有效。"},"vi":{"q":"Ở Illinois, khi nào bạn phải tuân theo tốc độ giới hạn được báo trong khu vực công trường?","o":["Mọi lúc, cả ngày lẫn đêm","Chỉ khi có công nhân","Chỉ vào ban ngày","Chỉ vào các ngày trong tuần"],"h1":"Nguy hiểm của công trình trên đường không biến mất khi công nhân về nhà.","h2":"Ở Illinois, bạn phải tuân theo tốc độ giới hạn được báo trong khu vực công trường 24 giờ một ngày, bảy ngày một tuần, kể cả khi không có công nhân ở đó.","p":"Đúng. Giới hạn trong khu công trường áp dụng mọi lúc."},"tl":{"q":"Sa Illinois, kailan mo dapat sundin ang nakapaskil na speed limit sa construction zone?","o":["Sa lahat ng oras, araw at gabi","Kapag may mga trabahador lang","Sa oras ng araw lang","Sa mga weekday lang"],"h1":"Hindi nawawala ang panganib ng ginagawang kalsada kapag umuwi na ang mga trabahador.","h2":"Sa Illinois, dapat mong sundin ang nakapaskil na speed limit sa construction zone 24 na oras bawat araw, pitong araw bawat linggo, kahit walang mga trabahador doon.","p":"Tama. Laging umiiral ang limit sa work zone."},"ar":{"q":"في Illinois، متى يجب أن تلتزم بحد السرعة المكتوب في منطقة أعمال الطرق؟","o":["في كل الأوقات، ليلًا ونهارًا","فقط عندما يكون العمال موجودين","فقط في ساعات النهار","فقط في أيام العمل"],"h1":"أخطار أعمال الطرق لا تختفي عندما يذهب العمال إلى بيوتهم.","h2":"في Illinois يجب أن تلتزم بحد السرعة المكتوب في منطقة أعمال الطرق 24 ساعة في اليوم وسبعة أيام في الأسبوع، حتى عندما لا يوجد عمال هناك.","p":"صحيح. حد منطقة الأعمال يسري في كل الأوقات."},"ref":{"doc":"IL","page":25}},{"id":"il-043","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, on an interstate, when should you drive in the left lane?","o":["Whenever you like","When you are passing another vehicle","Only at night","When you are going below the speed limit"],"h1":"The left lane is not for cruising.","h2":"On an Illinois interstate, you may not drive in the left lane except to pass, apart from a few exceptions such as heavy traffic, bad weather or a hazard in the right lane.","p":"Right. The left lane is for passing."},"es":{"q":"En Illinois, en una carretera interestatal, ¿cuándo debe manejar en el carril izquierdo?","o":["Cuando usted quiera","Cuando está rebasando a otro vehículo","Solo de noche","Cuando va más despacio que el límite"],"h1":"El carril izquierdo no es para ir de paseo.","h2":"En una interestatal de Illinois, usted no puede manejar en el carril izquierdo excepto para rebasar, salvo algunas excepciones como tráfico pesado, mal tiempo o un peligro en el carril derecho.","p":"Correcto. El carril izquierdo es para rebasar."},"zh":{"q":"在 Illinois 的州际公路上，你什么时候应该开在左车道？","o":["想开就开","在你超过另一辆车的时候","只在晚上","在你开得比限速慢的时候"],"h1":"左车道不是用来一直慢慢开的。","h2":"在 Illinois 的州际公路上，除了超车，你不能开在左车道；只有少数例外，比如交通拥堵、天气不好或右车道有危险。","p":"对。左车道是用来超车的。"},"vi":{"q":"Ở Illinois, trên xa lộ liên bang, khi nào bạn nên lái ở làn bên trái?","o":["Bất cứ khi nào bạn muốn","Khi bạn đang vượt một xe khác","Chỉ vào ban đêm","Khi bạn đang chạy chậm hơn tốc độ giới hạn"],"h1":"Làn bên trái không phải để chạy thong thả.","h2":"Trên xa lộ liên bang ở Illinois, bạn không được lái ở làn bên trái trừ khi vượt xe, ngoại trừ vài trường hợp như xe đông, thời tiết xấu hoặc có nguy hiểm ở làn bên phải.","p":"Đúng. Làn bên trái là để vượt xe."},"tl":{"q":"Sa Illinois, sa interstate, kailan ka dapat magmaneho sa kaliwang lane?","o":["Kahit kailan mo gusto","Kapag nilalampasan mo ang ibang sasakyan","Sa gabi lang","Kapag mas mabagal ka kaysa sa speed limit"],"h1":"Hindi para sa paandar-andar lang ang kaliwang lane.","h2":"Sa interstate sa Illinois, hindi ka puwedeng magmaneho sa kaliwang lane maliban kung lumalampas ka, bukod sa ilang exception tulad ng mabigat na trapiko, masamang panahon o panganib sa kanang lane.","p":"Tama. Para sa paglampas ang kaliwang lane."},"ar":{"q":"في Illinois، على الطريق السريع بين الولايات، متى يجب أن تقود في المسار الأيسر؟","o":["متى شئت","عندما تتجاوز سيارة أخرى","في الليل فقط","عندما تسير أبطأ من حد السرعة"],"h1":"المسار الأيسر ليس للقيادة الهادئة المستمرة.","h2":"على الطريق السريع بين الولايات في Illinois، لا يجوز لك أن تقود في المسار الأيسر إلا للتجاوز، مع استثناءات قليلة مثل الزحام الشديد أو الطقس السيئ أو وجود خطر في المسار الأيمن.","p":"صحيح. المسار الأيسر للتجاوز."},"ref":{"doc":"IL","page":29}},{"id":"il-044","scope":"IL","cat":"signals","sign":null,"c":2,"en":{"q":"In Illinois, outside business and residential areas, how far before a turn must you start your turn signal?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"It is twice the distance required in town.","h2":"In Illinois, outside business and residential areas, you must signal for at least 200 feet before turning.","p":"Right. Signal at least 200 feet ahead outside town."},"es":{"q":"En Illinois, fuera de las zonas comerciales y residenciales, ¿a qué distancia antes de una vuelta debe poner la direccional?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 500 pies"],"h1":"Es el doble de la distancia que se pide en la ciudad.","h2":"En Illinois, fuera de las zonas comerciales y residenciales, usted debe poner la direccional al menos 200 pies antes de dar vuelta.","p":"Correcto. Fuera de la ciudad, señale al menos 200 pies antes."},"zh":{"q":"在 Illinois，在商业区和住宅区以外，你必须在转弯前多远开始打转向灯？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 500 英尺"],"h1":"是市区要求距离的两倍。","h2":"在 Illinois，在商业区和住宅区以外，你必须在转弯前至少 200 英尺打转向灯。","p":"对。在市区以外，要提前至少 200 英尺打灯。"},"vi":{"q":"Ở Illinois, bên ngoài khu kinh doanh và khu dân cư, bạn phải bật đèn xi nhan bao xa trước khi rẽ?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 500 feet"],"h1":"Gấp đôi khoảng cách bắt buộc trong thị trấn.","h2":"Ở Illinois, bên ngoài khu kinh doanh và khu dân cư, bạn phải bật đèn xi nhan ít nhất 200 feet trước khi rẽ.","p":"Đúng. Bên ngoài thị trấn, bật xi nhan trước ít nhất 200 feet."},"tl":{"q":"Sa Illinois, sa labas ng mga business at residential area, gaano kalayo bago lumiko ka dapat magsimulang mag-signal?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 500 feet"],"h1":"Doble ito ng distansyang kailangan sa bayan.","h2":"Sa Illinois, sa labas ng mga business at residential area, dapat kang mag-signal nang hindi bababa sa 200 feet bago lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 200 feet bago lumiko sa labas ng bayan."},"ar":{"q":"في Illinois، خارج المناطق التجارية والسكنية، قبل كم من المسافة يجب أن تبدأ إشارة الانعطاف؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","500 قدم على الأقل"],"h1":"إنها ضعف المسافة المطلوبة داخل المدينة.","h2":"في Illinois، خارج المناطق التجارية والسكنية، يجب أن تشغّل إشارة الانعطاف قبل 200 قدم على الأقل من الانعطاف.","p":"صحيح. خارج المدينة، شغّل الإشارة قبل 200 قدم على الأقل."},"ref":{"doc":"IL","page":30}},{"id":"il-045","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, what is the penalty for being convicted of passing a stopped school bus with its stop arm out?","o":["A $300 fine and a license suspension","A $50 fine and nothing more","A warning for the first time","Traffic school, with no fine"],"h1":"It costs money and also affects your license.","h2":"In Illinois, a conviction for passing a stopped school bus brings a mandatory $300 fine and a suspension of your driver's license.","p":"Right. A $300 fine and a suspension."},"es":{"q":"En Illinois, ¿cuál es la sanción por ser declarado culpable de rebasar un autobús escolar detenido con el brazo de alto extendido?","o":["Una multa de $300 y la suspensión de la licencia","Una multa de $50 y nada más","Una advertencia la primera vez","Escuela de tránsito, sin multa"],"h1":"Cuesta dinero y también afecta su licencia.","h2":"En Illinois, una condena por rebasar un autobús escolar detenido trae una multa obligatoria de $300 y la suspensión de su licencia de conducir.","p":"Correcto. Una multa de $300 y una suspensión."},"zh":{"q":"在 Illinois，如果因为超过伸出停车臂、已经停下的校车而被定罪，处罚是什么？","o":["罚款 $300，并暂停驾照","罚款 $50，没有别的处罚","第一次只给警告","上交通学校，不罚款"],"h1":"要花钱，也会影响你的驾照。","h2":"在 Illinois，因为超过停下的校车而被定罪，必须罚款 $300，驾照也会被暂停。","p":"对。罚款 $300，并暂停驾照。"},"vi":{"q":"Ở Illinois, hình phạt khi bị kết tội vượt qua xe buýt trường học đang dừng và giơ biển dừng là gì?","o":["Phạt $300 và đình chỉ bằng lái","Phạt $50 và không có gì khác","Cảnh cáo trong lần đầu","Học lớp luật giao thông, không bị phạt tiền"],"h1":"Bạn mất tiền và bằng lái cũng bị ảnh hưởng.","h2":"Ở Illinois, bị kết tội vượt qua xe buýt trường học đang dừng sẽ bị phạt bắt buộc $300 và bị đình chỉ bằng lái.","p":"Đúng. Phạt $300 và bị đình chỉ bằng lái."},"tl":{"q":"Sa Illinois, ano ang parusa kapag nahatulan ka sa paglampas sa nakahintong school bus na nakalabas ang stop arm?","o":["$300 na multa at suspensyon ng lisensya","$50 na multa at wala nang iba","Warning para sa unang beses","Traffic school, walang multa"],"h1":"Magbabayad ka ng pera at maaapektuhan din ang lisensya mo.","h2":"Sa Illinois, ang conviction sa paglampas sa nakahintong school bus ay may mandatory na $300 na multa at suspensyon ng iyong driver's license.","p":"Tama. $300 na multa at suspensyon."},"ar":{"q":"في Illinois، ما العقوبة إذا أُدنت بتجاوز حافلة مدرسية متوقفة وذراع التوقف فيها ممدودة؟","o":["غرامة $300 وإيقاف الرخصة","غرامة $50 ولا شيء غيرها","تحذير في المرة الأولى","مدرسة مرور، بلا غرامة"],"h1":"إنها تكلّفك مالًا وتؤثر أيضًا على رخصتك.","h2":"في Illinois، الإدانة بتجاوز حافلة مدرسية متوقفة تعني غرامة إلزامية قدرها $300 وإيقاف رخصة القيادة.","p":"صحيح. غرامة $300 وإيقاف الرخصة."},"ref":{"doc":"IL","page":33}},{"id":"il-046","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, how close to a STOP sign may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Other drivers need to see the sign clearly.","h2":"In Illinois, you may not park within 30 feet of a STOP sign, a YIELD sign or a traffic signal.","p":"Right. Stay at least 30 feet from a STOP sign."},"es":{"q":"En Illinois, ¿qué tan cerca de un letrero de ALTO puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los demás conductores necesitan ver bien el letrero.","h2":"En Illinois, usted no puede estacionarse a menos de 30 pies de un letrero de ALTO, un letrero de CEDA EL PASO o un semáforo.","p":"Correcto. Quédese al menos a 30 pies de un letrero de ALTO."},"zh":{"q":"在 Illinois，你可以把车停在离 STOP 标志多近的地方？","o":["不能近于 10 英尺","不能近于 20 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"其他司机需要清楚地看到标志。","h2":"在 Illinois，你不能把车停在离 STOP 标志、YIELD 标志或交通信号灯 30 英尺以内的地方。","p":"对。离 STOP 标志至少 30 英尺。"},"vi":{"q":"Ở Illinois, bạn được đỗ xe gần biển STOP đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Những người lái khác cần nhìn thấy biển báo rõ ràng.","h2":"Ở Illinois, bạn không được đỗ xe trong vòng 30 feet tính từ biển STOP, biển YIELD hoặc đèn giao thông.","p":"Đúng. Đỗ cách biển STOP ít nhất 30 feet."},"tl":{"q":"Sa Illinois, gaano kalapit sa STOP sign ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet"],"h1":"Kailangang makita nang malinaw ng ibang driver ang karatula.","h2":"Sa Illinois, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa STOP sign, YIELD sign o traffic signal.","p":"Tama. Lumayo nang hindi bababa sa 30 feet mula sa STOP sign."},"ar":{"q":"في Illinois، إلى أي مدى يجوز لك أن تركن سيارتك قريبًا من لافتة STOP؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"السائقون الآخرون يحتاجون إلى أن يروا اللافتة بوضوح.","h2":"في Illinois لا يجوز لك أن تركن سيارتك على بعد أقل من 30 قدمًا من لافتة STOP أو لافتة YIELD أو إشارة المرور.","p":"صحيح. ابقَ على بعد 30 قدمًا على الأقل من لافتة STOP."},"ref":{"doc":"IL","page":36}},{"id":"il-047","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what happens to your driving privileges if you are convicted of driving without the required insurance?","o":["Nothing, you only pay a fine","They are suspended for at least 3 months","They are suspended for 1 week","They are revoked for 10 years"],"h1":"It is more than a fine: you lose your license for a few months.","h2":"In Illinois, a conviction for driving without the required insurance means losing your driving privileges for at least three months.","p":"Right. At least a 3-month suspension."},"es":{"q":"En Illinois, ¿qué pasa con su privilegio de manejar si lo declaran culpable de manejar sin el seguro obligatorio?","o":["Nada, solo paga una multa","Se lo suspenden por al menos 3 meses","Se lo suspenden por 1 semana","Se lo revocan por 10 años"],"h1":"Es más que una multa: pierde la licencia por unos meses.","h2":"En Illinois, una condena por manejar sin el seguro obligatorio significa perder el privilegio de manejar por al menos tres meses.","p":"Correcto. Una suspensión de al menos 3 meses."},"zh":{"q":"在 Illinois，如果你因为没有按规定买保险开车而被定罪，你的驾驶权利会怎么样？","o":["什么都不会发生，只要交罚款","被暂停至少 3 个月","被暂停 1 个星期","被吊销 10 年"],"h1":"不只是罚款：你会有几个月不能开车。","h2":"在 Illinois，因为没有按规定买保险开车而被定罪，驾驶权利会被暂停至少三个月。","p":"对。至少暂停 3 个月。"},"vi":{"q":"Ở Illinois, điều gì xảy ra với quyền lái xe của bạn nếu bạn bị kết tội lái xe không có bảo hiểm bắt buộc?","o":["Không có gì, bạn chỉ trả tiền phạt","Bị đình chỉ ít nhất 3 tháng","Bị đình chỉ 1 tuần","Bị thu hồi 10 năm"],"h1":"Không chỉ là tiền phạt: bạn mất bằng lái trong vài tháng.","h2":"Ở Illinois, bị kết tội lái xe không có bảo hiểm bắt buộc nghĩa là bạn mất quyền lái xe ít nhất ba tháng.","p":"Đúng. Bị đình chỉ ít nhất 3 tháng."},"tl":{"q":"Sa Illinois, ano ang mangyayari sa iyong driving privileges kung mahatulan ka ng pagmamaneho nang walang kinakailangang insurance?","o":["Wala, multa lang ang babayaran mo","Masususpinde ito nang hindi bababa sa 3 buwan","Masususpinde ito nang 1 linggo","Babawiin ito nang 10 taon"],"h1":"Higit pa ito sa multa: mawawala ang lisensya mo nang ilang buwan.","h2":"Sa Illinois, kapag nahatulan ka ng pagmamaneho nang walang kinakailangang insurance, mawawala ang driving privileges mo nang hindi bababa sa tatlong buwan.","p":"Tama. Suspensyon nang hindi bababa sa 3 buwan."},"ar":{"q":"في Illinois، ماذا يحدث لحقك في القيادة إذا أُدنت بالقيادة بدون التأمين المطلوب؟","o":["لا شيء، تدفع غرامة فقط","يُوقف لمدة 3 أشهر على الأقل","يُوقف لمدة أسبوع واحد","يُلغى لمدة 10 سنوات"],"h1":"الأمر أكثر من غرامة: تفقد رخصتك لبضعة أشهر.","h2":"في Illinois، الإدانة بالقيادة بدون التأمين المطلوب تعني أن تفقد حقك في القيادة لمدة ثلاثة أشهر على الأقل.","p":"صحيح. إيقاف لمدة 3 أشهر على الأقل."},"ref":{"doc":"IL","page":55}},{"id":"il-048","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a first offender arrested for DUI has a test result of 0.08 or more. How long is the statutory summary suspension?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"In Illinois, a first offender whose test shows 0.08 or more gets a statutory summary suspension of six months.","p":"Right. Six months for a failed test."},"es":{"q":"En Illinois, una persona arrestada por primera vez por manejar bajo los efectos (DUI) tiene un resultado de 0.08 o más. ¿Cuánto dura la suspensión sumaria (statutory summary suspension)?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"En Illinois, una persona arrestada por primera vez cuyo examen muestra 0.08 o más recibe una suspensión sumaria de seis meses.","p":"Correcto. Seis meses por no pasar el examen."},"zh":{"q":"在 Illinois，一个初犯因为 DUI 被逮捕，测试结果是 0.08 或更高。法定简易暂停（statutory summary suspension）是多久？","o":["1 个月","3 个月","6 个月","2 年"],"h1":"是半年。","h2":"在 Illinois，测试结果是 0.08 或更高的初犯，会被法定简易暂停六个月。","p":"对。测试不合格是六个月。"},"vi":{"q":"Ở Illinois, một người vi phạm lần đầu bị bắt vì DUI có kết quả kiểm tra từ 0.08 trở lên. Thời gian đình chỉ theo luật định (statutory summary suspension) là bao lâu?","o":["1 tháng","3 tháng","6 tháng","2 năm"],"h1":"Đó là nửa năm.","h2":"Ở Illinois, người vi phạm lần đầu có kết quả kiểm tra từ 0.08 trở lên sẽ bị đình chỉ theo luật định sáu tháng.","p":"Đúng. Sáu tháng khi không đạt kiểm tra."},"tl":{"q":"Sa Illinois, ang isang first offender na inaresto dahil sa DUI ay may test result na 0.08 o higit pa. Gaano katagal ang statutory summary suspension?","o":["1 buwan","3 buwan","6 na buwan","2 taon"],"h1":"Kalahating taon ito.","h2":"Sa Illinois, ang first offender na ang test ay nagpakita ng 0.08 o higit pa ay makakakuha ng statutory summary suspension nang anim na buwan.","p":"Tama. Anim na buwan kapag bagsak sa test."},"ar":{"q":"في Illinois، شخص يرتكب المخالفة لأول مرة قُبض عليه بسبب DUI، ونتيجة اختباره 0.08 أو أكثر. ما مدة الإيقاف الفوري بحكم القانون (statutory summary suspension)؟","o":["شهر واحد","3 أشهر","6 أشهر","سنتان"],"h1":"إنها نصف سنة.","h2":"في Illinois، من يرتكب المخالفة لأول مرة وتُظهر نتيجة اختباره 0.08 أو أكثر يُوقف إيقافًا فوريًا بحكم القانون لمدة ستة أشهر.","p":"صحيح. ستة أشهر عند الرسوب في الاختبار."},"ref":{"doc":"IL","page":49}},{"id":"il-049","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a first offender arrested for DUI refuses the chemical test. How long is the license suspended?","o":["1 year","6 months","3 months","30 days"],"h1":"Refusing costs you more than failing the test.","h2":"In Illinois, a first offender who refuses chemical testing after a DUI arrest has driving privileges suspended for one year.","p":"Right. Refusing means a one-year suspension."},"es":{"q":"En Illinois, una persona arrestada por primera vez por DUI se niega a hacer la prueba química. ¿Por cuánto tiempo le suspenden la licencia?","o":["1 año","6 meses","3 meses","30 días"],"h1":"Negarse le cuesta más que no pasar la prueba.","h2":"En Illinois, una persona arrestada por primera vez por DUI que se niega a la prueba química pierde el privilegio de manejar por un año.","p":"Correcto. Negarse significa una suspensión de un año."},"zh":{"q":"在 Illinois，一个初犯因为 DUI 被逮捕后拒绝做化学测试。驾照会被暂停多久？","o":["1 年","6 个月","3 个月","30 天"],"h1":"拒绝测试比测试不合格的后果更重。","h2":"在 Illinois，初犯在 DUI 被逮捕后拒绝做化学测试，驾驶权利会被暂停一年。","p":"对。拒绝测试就暂停一年。"},"vi":{"q":"Ở Illinois, một người vi phạm lần đầu bị bắt vì DUI từ chối kiểm tra hóa học. Bằng lái bị đình chỉ bao lâu?","o":["1 năm","6 tháng","3 tháng","30 ngày"],"h1":"Từ chối kiểm tra bị phạt nặng hơn là không đạt kiểm tra.","h2":"Ở Illinois, người vi phạm lần đầu từ chối kiểm tra hóa học sau khi bị bắt vì DUI sẽ bị đình chỉ quyền lái xe một năm.","p":"Đúng. Từ chối kiểm tra nghĩa là bị đình chỉ một năm."},"tl":{"q":"Sa Illinois, ang isang first offender na inaresto dahil sa DUI ay tumangging magpa-chemical test. Gaano katagal masususpinde ang lisensya?","o":["1 taon","6 na buwan","3 buwan","30 araw"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test.","h2":"Sa Illinois, ang first offender na tumangging magpa-chemical test pagkatapos maaresto dahil sa DUI ay masususpinde ang driving privileges nang isang taon.","p":"Tama. Ang pagtanggi ay isang taong suspensyon."},"ar":{"q":"في Illinois، شخص يرتكب المخالفة لأول مرة قُبض عليه بسبب DUI ورفض الاختبار الكيميائي. كم مدة إيقاف الرخصة؟","o":["سنة واحدة","6 أشهر","3 أشهر","30 يومًا"],"h1":"رفض الاختبار يكلّفك أكثر من الرسوب فيه.","h2":"في Illinois، من يرتكب المخالفة لأول مرة ويرفض الاختبار الكيميائي بعد القبض عليه بسبب DUI يُوقف حقه في القيادة لمدة سنة واحدة.","p":"صحيح. الرفض يعني إيقافًا لمدة سنة."},"ref":{"doc":"IL","page":49}},{"id":"il-050","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, what is the least a driver loses for a first DUI conviction?","o":["A 30-day suspension","A 3-month suspension","A lifetime revocation","A revocation of at least 1 year"],"h1":"A DUI conviction takes the license away, not just for a few weeks.","h2":"In Illinois, a first DUI conviction brings a revocation of driving privileges for at least one year.","p":"Right. At least a one-year revocation."},"es":{"q":"En Illinois, ¿qué es lo mínimo que pierde un conductor por su primera condena por DUI?","o":["Una suspensión de 30 días","Una suspensión de 3 meses","Una revocación de por vida","Una revocación de al menos 1 año"],"h1":"Una condena por DUI le quita la licencia, y no solo por unas semanas.","h2":"En Illinois, una primera condena por DUI trae la revocación del privilegio de manejar por al menos un año.","p":"Correcto. Una revocación de al menos un año."},"zh":{"q":"在 Illinois，第一次 DUI 定罪，司机最少会失去什么？","o":["暂停 30 天","暂停 3 个月","终身吊销","吊销至少 1 年"],"h1":"DUI 定罪会拿走驾照，而且不只是几个星期。","h2":"在 Illinois，第一次 DUI 定罪会被吊销驾驶权利至少一年。","p":"对。至少吊销一年。"},"vi":{"q":"Ở Illinois, khi bị kết tội DUI lần đầu, người lái mất ít nhất là gì?","o":["Đình chỉ 30 ngày","Đình chỉ 3 tháng","Thu hồi suốt đời","Thu hồi ít nhất 1 năm"],"h1":"Bị kết tội DUI là mất bằng lái, không chỉ trong vài tuần.","h2":"Ở Illinois, bị kết tội DUI lần đầu sẽ bị thu hồi quyền lái xe ít nhất một năm.","p":"Đúng. Thu hồi ít nhất một năm."},"tl":{"q":"Sa Illinois, ano ang pinakamababang mawawala sa driver sa unang DUI conviction?","o":["30 araw na suspensyon","3 buwang suspensyon","Habambuhay na revocation","Revocation nang hindi bababa sa 1 taon"],"h1":"Kinukuha ng DUI conviction ang lisensya, at hindi lang nang ilang linggo.","h2":"Sa Illinois, ang unang DUI conviction ay may revocation ng driving privileges nang hindi bababa sa isang taon.","p":"Tama. Revocation nang hindi bababa sa isang taon."},"ar":{"q":"في Illinois، ما أقل ما يفقده السائق عند أول إدانة بـ DUI؟","o":["إيقاف 30 يومًا","إيقاف 3 أشهر","سحب الرخصة مدى الحياة","سحب الرخصة سنة واحدة على الأقل"],"h1":"الإدانة بـ DUI تأخذ الرخصة منك، وليس لبضعة أسابيع فقط.","h2":"في Illinois، أول إدانة بـ DUI تعني سحب حق القيادة سنة واحدة على الأقل.","p":"صحيح. سحب الرخصة سنة واحدة على الأقل."},"ref":{"doc":"IL","page":50}},{"id":"il-051","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a driver under 21 is convicted of DUI for the first time. What is the minimum revocation?","o":["2 years","1 year","6 months","3 months"],"h1":"It is longer than the minimum for an adult.","h2":"In Illinois, a driver under 21 convicted of DUI for the first time loses driving privileges for at least two years.","p":"Right. At least two years for a driver under 21."},"es":{"q":"En Illinois, un conductor menor de 21 años es declarado culpable de DUI por primera vez. ¿Cuál es la revocación mínima?","o":["2 años","1 año","6 meses","3 meses"],"h1":"Es más larga que el mínimo para un adulto.","h2":"En Illinois, un conductor menor de 21 años declarado culpable de DUI por primera vez pierde el privilegio de manejar por al menos dos años.","p":"Correcto. Al menos dos años para un conductor menor de 21."},"zh":{"q":"在 Illinois，一个 21 岁以下的司机第一次因 DUI 被定罪。最少吊销多久？","o":["2 年","1 年","6 个月","3 个月"],"h1":"比成年人的最低期限更长。","h2":"在 Illinois，21 岁以下的司机第一次因 DUI 被定罪，会失去驾驶权利至少两年。","p":"对。21 岁以下的司机至少两年。"},"vi":{"q":"Ở Illinois, một người lái dưới 21 tuổi bị kết tội DUI lần đầu. Thời gian thu hồi tối thiểu là bao lâu?","o":["2 năm","1 năm","6 tháng","3 tháng"],"h1":"Nó dài hơn mức tối thiểu cho người lớn.","h2":"Ở Illinois, người lái dưới 21 tuổi bị kết tội DUI lần đầu sẽ mất quyền lái xe ít nhất hai năm.","p":"Đúng. Ít nhất hai năm cho người lái dưới 21 tuổi."},"tl":{"q":"Sa Illinois, ang driver na wala pang 21 ay nahatulan ng DUI sa unang pagkakataon. Ano ang pinakamaikling revocation?","o":["2 taon","1 taon","6 na buwan","3 buwan"],"h1":"Mas matagal ito kaysa sa minimum para sa adult.","h2":"Sa Illinois, ang driver na wala pang 21 na nahatulan ng DUI sa unang pagkakataon ay mawawalan ng driving privileges nang hindi bababa sa dalawang taon.","p":"Tama. Hindi bababa sa dalawang taon para sa driver na wala pang 21."},"ar":{"q":"في Illinois، سائق عمره أقل من 21 سنة أُدين بـ DUI لأول مرة. ما أقل مدة لسحب الرخصة؟","o":["سنتان","سنة واحدة","6 أشهر","3 أشهر"],"h1":"إنها أطول من الحد الأدنى للبالغين.","h2":"في Illinois، السائق الذي عمره أقل من 21 سنة ويُدان بـ DUI لأول مرة يفقد حقه في القيادة سنتين على الأقل.","p":"صحيح. سنتان على الأقل للسائق الذي عمره أقل من 21 سنة."},"ref":{"doc":"IL","page":52}},{"id":"il-052","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how must cannabis be carried in a vehicle?","o":["In an open bag on the back seat","In a closed paper bag in the glove box","Anywhere, as long as no one uses it","In a sealed or resealable, odor-proof, child-resistant container that no one can reach"],"h1":"The container must keep in the smell, keep out small children, and be out of reach.","h2":"In Illinois, cannabis may be carried in a vehicle only in a secured, sealed or resealable, odor-proof, child-resistant container that no one in the vehicle can reach.","p":"Right. Sealed, odor-proof, child-resistant and out of reach."},"es":{"q":"En Illinois, ¿cómo se debe llevar el cannabis en un vehículo?","o":["En una bolsa abierta en el asiento de atrás","En una bolsa de papel cerrada en la guantera","En cualquier lugar, si nadie lo usa","En un envase sellado o que se vuelve a cerrar, a prueba de olores y de niños, fuera del alcance de todos"],"h1":"El envase debe guardar el olor, no dejar que los niños pequeños lo abran y estar fuera del alcance.","h2":"En Illinois, el cannabis solo se puede llevar en un vehículo en un envase asegurado, sellado o que se vuelve a cerrar, a prueba de olores y a prueba de niños, que nadie en el vehículo pueda alcanzar.","p":"Correcto. Sellado, a prueba de olores y de niños, y fuera del alcance."},"zh":{"q":"在 Illinois，车里应该怎样携带大麻（cannabis）？","o":["放在后座一个打开的袋子里","放在手套箱里一个封好的纸袋里","放在哪里都可以，只要没人使用","放在密封或可再封、防气味、防儿童打开、车里没人拿得到的容器里"],"h1":"容器必须锁住气味，防止小孩打开，并且放在拿不到的地方。","h2":"在 Illinois，车里的大麻只能放在一个固定好、密封或可再封、防气味、防儿童打开、车里没有人拿得到的容器里。","p":"对。密封、防气味、防儿童打开，而且拿不到。"},"vi":{"q":"Ở Illinois, cần sa (cannabis) phải được mang theo trong xe như thế nào?","o":["Trong một túi mở ở ghế sau","Trong một túi giấy đóng kín trong hộc đựng găng tay","Ở đâu cũng được, miễn là không ai dùng","Trong một hộp kín hoặc đóng lại được, không thoát mùi, trẻ em không mở được và không ai với tới được"],"h1":"Hộp phải giữ mùi bên trong, trẻ nhỏ không mở được và để ngoài tầm với.","h2":"Ở Illinois, cần sa chỉ được mang theo trong xe trong một hộp được cất giữ chắc chắn, kín hoặc đóng lại được, không thoát mùi, trẻ em không mở được và không ai trong xe với tới được.","p":"Đúng. Kín, không thoát mùi, trẻ em không mở được và ngoài tầm với."},"tl":{"q":"Sa Illinois, paano dapat dalhin ang cannabis sa sasakyan?","o":["Sa isang bukas na bag sa likod na upuan","Sa isang saradong paper bag sa glove box","Kahit saan, basta walang gumagamit nito","Sa isang sealed o resealable na lalagyan na hindi lumalabas ang amoy, hindi mabubuksan ng bata, at hindi maaabot ng sinuman"],"h1":"Dapat pigilan ng lalagyan ang amoy, hindi mabuksan ng maliliit na bata, at hindi maabot.","h2":"Sa Illinois, puwedeng dalhin ang cannabis sa sasakyan sa isang secured, sealed o resealable na lalagyan lamang na hindi lumalabas ang amoy, hindi mabubuksan ng bata, at hindi maaabot ng sinuman sa sasakyan.","p":"Tama. Sealed, hindi lumalabas ang amoy, hindi mabubuksan ng bata, at hindi maaabot."},"ar":{"q":"في Illinois، كيف يجب نقل القنّب (cannabis) في السيارة؟","o":["في كيس مفتوح على المقعد الخلفي","في كيس ورقي مغلق في درج السيارة","في أي مكان، ما دام لا أحد يستعمله","في وعاء محكم الإغلاق أو قابل لإعادة الإغلاق، يمنع الرائحة، لا يستطيع الأطفال فتحه، ولا يستطيع أحد الوصول إليه"],"h1":"يجب أن يحبس الوعاء الرائحة، وأن يمنع الأطفال الصغار من فتحه، وأن يكون بعيدًا عن متناول اليد.","h2":"في Illinois، لا يجوز نقل القنّب في السيارة إلا في وعاء مؤمَّن، محكم الإغلاق أو قابل لإعادة الإغلاق، يمنع الرائحة، لا يستطيع الأطفال فتحه، ولا يستطيع أحد في السيارة الوصول إليه.","p":"صحيح. محكم، يمنع الرائحة، لا يفتحه الأطفال، وبعيد عن المتناول."},"ref":{"doc":"IL","page":48}},{"id":"il-053","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, a teen is not enrolled in driver education. At what age may they get an instruction permit?","o":["17 years and 3 months","15 years old","16 years old","16 years and 6 months"],"h1":"Without driver education, the wait is longer than for teens who take the course.","h2":"In Illinois, a teen who is not in driver education may get an instruction permit at 17 years and 3 months.","p":"Right. Without driver education, the permit age is 17 years and 3 months."},"es":{"q":"En Illinois, un adolescente no está inscrito en educación vial. ¿A qué edad puede obtener un permiso de aprendizaje?","o":["17 años y 3 meses","15 años","16 años","16 años y 6 meses"],"h1":"Sin educación vial, la espera es más larga que para quienes toman el curso.","h2":"En Illinois, un adolescente que no está en educación vial puede obtener el permiso de aprendizaje a los 17 años y 3 meses.","p":"Correcto. Sin educación vial, la edad para el permiso es 17 años y 3 meses."},"ref":{"doc":"IL","page":null}},{"id":"il-054","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how long is an instruction permit valid for a person 18 or older?","o":["6 months","12 months","24 months","4 years"],"h1":"It is half as long as the permit for teens under 18.","h2":"In Illinois, an instruction permit for a person 18 or older is valid for 12 months.","p":"Right. An adult instruction permit lasts 12 months."},"es":{"q":"En Illinois, ¿por cuánto tiempo es válido el permiso de aprendizaje de una persona de 18 años o más?","o":["6 meses","12 meses","24 meses","4 años"],"h1":"Dura la mitad que el permiso para menores de 18 años.","h2":"En Illinois, el permiso de aprendizaje de una persona de 18 años o más es válido por 12 meses.","p":"Correcto. El permiso de aprendizaje para adultos dura 12 meses."},"ref":{"doc":"IL","page":null}},{"id":"il-055","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, where must the supervising adult sit when a permit holder is driving?","o":["Anywhere in the vehicle","Directly behind the driver","In the seat beside the driver","In any back seat with a belt"],"h1":"The adult must be close enough to help right away.","h2":"In Illinois, the supervising adult must sit in the seat beside the permit holder.","p":"Right. The supervisor sits beside the driver."},"es":{"q":"En Illinois, ¿dónde debe sentarse el adulto que supervisa cuando conduce alguien con permiso de aprendizaje?","o":["En cualquier lugar del vehículo","Justo detrás del conductor","En el asiento al lado del conductor","En cualquier asiento trasero con cinturón"],"h1":"El adulto debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Illinois, el adulto que supervisa debe sentarse en el asiento al lado de quien tiene el permiso.","p":"Correcto. El supervisor se sienta al lado del conductor."},"ref":{"doc":"IL","page":null}},{"id":"il-056","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a 16-year-old with a permit drives home from a job at 11:30 p.m. on a Tuesday, with no stops. Is this allowed?","o":["No, there are no exceptions to the night limit","Only if the job is less than 5 miles away","Only on weekends","Yes, driving home from work is an exception"],"h1":"The law lists a few trips that are allowed during the night hours.","h2":"In Illinois, a permit holder under 18 may drive during the night hours when going to or coming home from work without a detour or stop.","p":"Right. Going straight to or from work is an exception."},"es":{"q":"En Illinois, un joven de 16 años con permiso conduce a casa desde su trabajo a las 11:30 p.m. de un martes, sin paradas. ¿Está permitido?","o":["No, el límite nocturno no tiene excepciones","Solo si el trabajo queda a menos de 5 millas","Solo los fines de semana","Sí, volver del trabajo es una excepción"],"h1":"La ley menciona algunos viajes permitidos durante las horas nocturnas.","h2":"En Illinois, quien tiene permiso y es menor de 18 años puede conducir en horas nocturnas para ir o volver del trabajo sin desvíos ni paradas.","p":"Correcto. Ir o volver directo del trabajo es una excepción."},"ref":{"doc":"IL","page":null}},{"id":"il-057","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what is the youngest age to get a graduated driver's license?","o":["16","15","17","18"],"h1":"It is one year after the youngest permit age.","h2":"In Illinois, a teen must be at least 16 years old to get a graduated driver's license.","p":"Right. The youngest age for the license is 16."},"es":{"q":"En Illinois, ¿cuál es la edad mínima para obtener una licencia de conducir gradual?","o":["16","15","17","18"],"h1":"Es un año después de la edad mínima del permiso.","h2":"En Illinois, un adolescente debe tener al menos 16 años para obtener una licencia de conducir gradual.","p":"Correcto. La edad mínima para la licencia es 16 años."},"ref":{"doc":"IL","page":null}},{"id":"il-058","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what must come with a license application from a teen under 18 who is not emancipated?","o":["A letter from the teen's school principal","Written consent from a parent or guardian","Proof of the teen's own car insurance","A doctor's report"],"h1":"An adult who is responsible for the teen has to agree in writing.","h2":"In Illinois, a license application from a teen under 18 must include written consent from a parent or guardian, or another responsible adult if there is none.","p":"Right. A parent or guardian must give written consent."},"es":{"q":"En Illinois, ¿qué debe acompañar la solicitud de licencia de un adolescente menor de 18 años que no está emancipado?","o":["Una carta del director de la escuela","El consentimiento por escrito de un padre o tutor","Un seguro de auto a nombre del adolescente","Un informe médico"],"h1":"Un adulto responsable del adolescente debe aceptar por escrito.","h2":"En Illinois, la solicitud de licencia de un menor de 18 años debe incluir el consentimiento por escrito de un padre o tutor, o de otro adulto responsable si no lo hay.","p":"Correcto. Un padre o tutor debe dar su consentimiento por escrito."},"ref":{"doc":"IL","page":null}},{"id":"il-059","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, besides the permit time and practice hours, what else must a 16-year-old finish to get a license?","o":["A defensive driving course for adults","A first aid class","An approved driver education course","A motorcycle safety course"],"h1":"It is the course that teens usually take through school.","h2":"In Illinois, a driver under 18 must pass an approved driver education course before getting a license.","p":"Right. Teens must pass an approved driver education course."},"es":{"q":"En Illinois, además del tiempo con permiso y las horas de práctica, ¿qué más debe terminar un joven de 16 años para obtener la licencia?","o":["Un curso de manejo defensivo para adultos","Una clase de primeros auxilios","Un curso aprobado de educación vial","Un curso de seguridad en motocicleta"],"h1":"Es el curso que los adolescentes suelen tomar en la escuela.","h2":"En Illinois, un conductor menor de 18 años debe aprobar un curso aprobado de educación vial antes de obtener la licencia.","p":"Correcto. Los adolescentes deben aprobar un curso aprobado de educación vial."},"ref":{"doc":"IL","page":null}},{"id":"il-060","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a 16-year-old applies for a license but has a traffic ticket that the court has not decided yet. What happens?","o":["The license is issued with a warning","The ticket is dropped","The teen gets a license with no passengers allowed","The license is not issued until the ticket is decided"],"h1":"The case has to be finished first.","h2":"In Illinois, a teen under 18 cannot get a license while a traffic ticket is still waiting for a court decision.","p":"Right. An open ticket stops the license until it is decided."},"es":{"q":"En Illinois, un joven de 16 años solicita la licencia pero tiene una multa de tránsito que el tribunal aún no ha decidido. ¿Qué pasa?","o":["Se le da la licencia con una advertencia","La multa se anula","Recibe una licencia sin permitir pasajeros","No se le da la licencia hasta que se decida la multa"],"h1":"Primero hay que terminar el caso.","h2":"En Illinois, un menor de 18 años no puede obtener la licencia mientras una multa de tránsito espera la decisión del tribunal.","p":"Correcto. Una multa pendiente detiene la licencia hasta que se decida."},"ref":{"doc":"IL","page":null}},{"id":"il-061","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, a 16-year-old has stopped going to school and is a habitual truant. Can they get a driver's license?","o":["No, they must be in school or have graduated","Yes, school does not matter","Yes, if a parent signs","Yes, after age 16 and a half"],"h1":"Illinois links a teen license to school.","h2":"In Illinois, a license applicant under 18 must be enrolled in school or home instruction, working toward a diploma, or already graduated, and not a habitual truant.","p":"Right. A teen must be in school or have graduated."},"es":{"q":"En Illinois, un joven de 16 años dejó de ir a la escuela y falta de forma habitual. ¿Puede obtener una licencia de conducir?","o":["No, debe estar en la escuela o haberse graduado","Sí, la escuela no importa","Sí, si firma un padre","Sí, después de los 16 años y medio"],"h1":"Illinois relaciona la licencia de los adolescentes con la escuela.","h2":"En Illinois, quien solicita la licencia y es menor de 18 años debe estar inscrito en la escuela o en educación en casa, estudiar para un diploma o ya haberse graduado, y no faltar de forma habitual.","p":"Correcto. El adolescente debe estar en la escuela o haberse graduado."},"ref":{"doc":"IL","page":null}},{"id":"il-062","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, a 15-year-old is caught driving without any license or permit. What can happen later?","o":["Nothing, if no one was hurt","The teen can be refused a permit or license","The teen gets a license sooner","Only the parents pay a fine"],"h1":"Driving before you are allowed hurts your chances of getting a license.","h2":"In Illinois, a person under 18 who has driven without a valid license or permit can be refused a permit or license.","p":"Right. Driving without a permit can block a teen from getting one."},"es":{"q":"En Illinois, un joven de 15 años es sorprendido conduciendo sin licencia ni permiso. ¿Qué puede pasar después?","o":["Nada, si nadie salió herido","Se le puede negar el permiso o la licencia","Obtiene la licencia antes","Solo los padres pagan una multa"],"h1":"Conducir antes de tener permiso perjudica tus posibilidades de obtener la licencia.","h2":"En Illinois, a una persona menor de 18 años que conduce sin licencia o permiso válido se le puede negar el permiso o la licencia.","p":"Correcto. Conducir sin permiso puede impedir que un adolescente lo obtenga."},"ref":{"doc":"IL","page":null}},{"id":"il-063","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, how many passengers may a licensed driver under 18 carry in the front seat?","o":["Two","None","One","As many as there are seats"],"h1":"The rest must ride in the back with a seat belt each.","h2":"In Illinois, a licensed driver under 18 may have only one passenger in the front seat, and no more back-seat passengers than seat belts.","p":"Right. Only one passenger may ride in front."},"es":{"q":"En Illinois, ¿cuántos pasajeros puede llevar en el asiento delantero un conductor con licencia menor de 18 años?","o":["Dos","Ninguno","Uno","Tantos como asientos haya"],"h1":"Los demás deben ir atrás, cada uno con su cinturón.","h2":"En Illinois, un conductor con licencia menor de 18 años solo puede llevar un pasajero en el asiento delantero, y atrás no más pasajeros que cinturones.","p":"Correcto. Solo un pasajero puede ir adelante."},"ref":{"doc":"IL","page":null}},{"id":"il-064","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a 17-year-old has had a license for 2 months and is already driving one friend who is 16. Another friend, age 18, gets in. Who can be ticketed?","o":["Only the driver","No one, because one friend is 18","Only the parents of the driver","The driver and both teen passengers"],"h1":"In Illinois, teen passengers have duties under this rule too.","h2":"In Illinois, a passenger from 15 to 19 commits an offense by riding with a new teen driver when another passenger under 20 is present, so the driver and both teen passengers can be ticketed.","p":"Right. The driver and both teen passengers break the law."},"es":{"q":"En Illinois, un joven de 17 años tiene licencia desde hace 2 meses y ya lleva a un amigo de 16 años. Sube otro amigo de 18 años. ¿A quién pueden multar?","o":["Solo al conductor","A nadie, porque un amigo tiene 18","Solo a los padres del conductor","Al conductor y a los dos pasajeros adolescentes"],"h1":"En Illinois, los pasajeros adolescentes también tienen deberes en esta regla.","h2":"En Illinois, un pasajero de 15 a 19 años comete una infracción al viajar con un conductor adolescente nuevo cuando va otro pasajero menor de 20, así que pueden multar al conductor y a los dos pasajeros adolescentes.","p":"Correcto. El conductor y los dos pasajeros adolescentes infringen la ley."},"ref":{"doc":"IL","page":null}},{"id":"il-065","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, a teen driver is convicted of speeding during the first year with a license. What happens to the passenger limit?","o":["It stays until 6 months pass with no new violation","It ends right away","It is doubled to two years","It changes to no passengers at all for life"],"h1":"The limit lasts longer, until the driver shows a clean record for a while.","h2":"In Illinois, if a new teen driver is convicted of a moving violation in the first 12 months, the passenger limit stays until 6 months in a row pass with no new conviction.","p":"Right. The limit continues until 6 clean months pass."},"es":{"q":"En Illinois, un conductor adolescente es condenado por exceso de velocidad en su primer año con licencia. ¿Qué pasa con el límite de pasajeros?","o":["Sigue hasta que pasen 6 meses sin otra infracción","Termina de inmediato","Se duplica a dos años","Cambia a ningún pasajero para siempre"],"h1":"El límite dura más, hasta que el conductor muestre un historial limpio por un tiempo.","h2":"En Illinois, si un conductor adolescente nuevo es condenado por una infracción de tránsito en los primeros 12 meses, el límite de pasajeros sigue hasta que pasen 6 meses seguidos sin otra condena.","p":"Correcto. El límite sigue hasta que pasen 6 meses limpios."},"ref":{"doc":"IL","page":null}},{"id":"il-066","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, an 18-year-old needs the adult driver education course. How may it be taken?","o":["Only in a car with an instructor","In person or online from an approved provider","Only at a Secretary of State office","Only at a high school"],"h1":"The course is classroom learning and does not require driving.","h2":"In Illinois, the adult driver education course may be taken online from a provider the Secretary of State approves, and it does not require driving a car.","p":"Right. Approved providers may offer the course online."},"es":{"q":"En Illinois, una persona de 18 años necesita el curso de educación vial para adultos. ¿Cómo puede tomarlo?","o":["Solo en un auto con un instructor","En persona o en línea con un proveedor aprobado","Solo en una oficina de la Secretaría de Estado","Solo en una escuela secundaria"],"h1":"El curso es de aprendizaje en clase y no exige conducir.","h2":"En Illinois, el curso de educación vial para adultos puede tomarse en línea con un proveedor aprobado por la Secretaría de Estado, y no exige conducir un auto.","p":"Correcto. Los proveedores aprobados pueden ofrecer el curso en línea."},"ref":{"doc":"IL","page":null}},{"id":"il-067","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, when must you have your driver's license with you?","o":["Only on highways","Only when you drive out of state","At all times when you drive","Only at night"],"h1":"An officer may ask to see it at any traffic stop.","h2":"In Illinois, you must have your license or permit with you at all times when you drive and hand it to an officer who asks for it.","p":"Right. Carry your license every time you drive."},"es":{"q":"En Illinois, ¿cuándo debes llevar tu licencia de conducir contigo?","o":["Solo en las autopistas","Solo cuando conduces fuera del estado","Siempre que conduces","Solo de noche"],"h1":"Un policía puede pedírtela en cualquier parada de tránsito.","h2":"En Illinois, debes llevar tu licencia o permiso siempre que conduces y entregarlo al policía que lo pida.","p":"Correcto. Lleva tu licencia cada vez que conduces."},"ref":{"doc":"IL","page":null}},{"id":"il-068","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, your legal name changes. How soon must you apply for a corrected license?","o":["Within 10 days","Within 90 days","At your next renewal","Within 30 days"],"h1":"You have a bit longer than for an address change.","h2":"In Illinois, after your legal name changes, you must apply for a corrected license within 30 days.","p":"Right. You have 30 days to correct your name."},"es":{"q":"En Illinois, tu nombre legal cambia. ¿En cuánto tiempo debes pedir una licencia corregida?","o":["Dentro de 10 días","Dentro de 90 días","En tu próxima renovación","Dentro de 30 días"],"h1":"Tienes un poco más de tiempo que para un cambio de domicilio.","h2":"En Illinois, cuando cambia tu nombre legal, debes pedir una licencia corregida dentro de 30 días.","p":"Correcto. Tienes 30 días para corregir tu nombre."},"ref":{"doc":"IL","page":null}},{"id":"il-069","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how long is a license valid for a driver aged 81 to 86?","o":["2 years","1 year","4 years","8 years"],"h1":"It is half the usual term for adults.","h2":"In Illinois, a license issued to a driver aged 81 through 86 expires after 2 years.","p":"Right. Drivers aged 81 to 86 renew every 2 years."},"es":{"q":"En Illinois, ¿por cuánto tiempo es válida la licencia de un conductor de 81 a 86 años?","o":["2 años","1 año","4 años","8 años"],"h1":"Es la mitad del plazo habitual para adultos.","h2":"En Illinois, la licencia de un conductor de 81 a 86 años vence a los 2 años.","p":"Correcto. Los conductores de 81 a 86 años renuevan cada 2 años."},"ref":{"doc":"IL","page":null}},{"id":"il-070","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, how long is a license valid for a driver aged 87 or older?","o":["2 years","1 year","3 years","4 years"],"h1":"It is the shortest term for any age group.","h2":"In Illinois, a license issued to a driver 87 or older expires after 1 year.","p":"Right. Drivers 87 and older renew every year."},"es":{"q":"En Illinois, ¿por cuánto tiempo es válida la licencia de un conductor de 87 años o más?","o":["2 años","1 año","3 años","4 años"],"h1":"Es el plazo más corto de todos los grupos de edad.","h2":"En Illinois, la licencia de un conductor de 87 años o más vence al año.","p":"Correcto. Los conductores de 87 años o más renuevan cada año."},"ref":{"doc":"IL","page":null}},{"id":"il-071","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, from what age must a driver renew the license in person?","o":["65","70","79","90"],"h1":"It is close to 80.","h2":"In Illinois, every driver aged 79 or older must renew the license in person.","p":"Right. From 79, renewal is in person."},"es":{"q":"En Illinois, ¿desde qué edad un conductor debe renovar la licencia en persona?","o":["65","70","79","90"],"h1":"Está cerca de los 80.","h2":"En Illinois, todo conductor de 79 años o más debe renovar la licencia en persona.","p":"Correcto. Desde los 79, la renovación es en persona."},"ref":{"doc":"IL","page":null}},{"id":"il-072","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, at what age must a driver take a driving test to renew the license?","o":["75 or older","79 or older","81 or older","87 or older"],"h1":"It is the same age at which the license starts to last only one year.","h2":"In Illinois, a driver aged 87 or older must show safe driving in a road test to renew the license.","p":"Right. From 87, renewal includes a driving test."},"es":{"q":"En Illinois, ¿a qué edad debe un conductor hacer un examen práctico para renovar la licencia?","o":["75 años o más","79 años o más","81 años o más","87 años o más"],"h1":"Es la misma edad en que la licencia empieza a durar solo un año.","h2":"En Illinois, un conductor de 87 años o más debe demostrar que conduce con seguridad en un examen práctico para renovar la licencia.","p":"Correcto. Desde los 87, la renovación incluye un examen práctico."},"ref":{"doc":"IL","page":null}},{"id":"il-073","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, at least how often must every licensed driver be examined again?","o":["Every 8 years","Every 2 years","Every 4 years","Every 12 years"],"h1":"It is two license terms of 4 years.","h2":"In Illinois, the Secretary of State must examine every licensed driver at least once every 8 years.","p":"Right. Drivers are examined at least every 8 years."},"es":{"q":"En Illinois, ¿con qué frecuencia mínima se debe examinar de nuevo a cada conductor con licencia?","o":["Cada 8 años","Cada 2 años","Cada 4 años","Cada 12 años"],"h1":"Son dos períodos de licencia de 4 años.","h2":"En Illinois, la Secretaría de Estado debe examinar a cada conductor con licencia al menos una vez cada 8 años.","p":"Correcto. Se examina a los conductores al menos cada 8 años."},"ref":{"doc":"IL","page":null}},{"id":"il-074","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, besides English, in which language does the law say the written driver's test may be given on request?","o":["French","Spanish","Polish","German"],"h1":"It is the most common language after English in the United States.","h2":"In Illinois, the law says the written and spoken tests may be given in Spanish on request, and in other languages if the Secretary of State chooses.","p":"Right. The law names Spanish."},"es":{"q":"En Illinois, además del inglés, ¿en qué idioma dice la ley que se puede dar el examen escrito si se pide?","o":["Francés","Español","Polaco","Alemán"],"h1":"Es el idioma más común después del inglés en Estados Unidos.","h2":"En Illinois, la ley dice que los exámenes escritos y orales pueden darse en español si se piden, y en otros idiomas si la Secretaría de Estado lo decide.","p":"Correcto. La ley menciona el español."},"ref":{"doc":"IL","page":null}},{"id":"il-075","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, how long before your license expires does the Secretary of State send you a notice?","o":["7 days","90 days","30 days","6 months"],"h1":"It is about one month.","h2":"In Illinois, the Secretary of State sends a notice 30 days before your license expires.","p":"Right. The notice comes 30 days before."},"es":{"q":"En Illinois, ¿cuánto tiempo antes de que venza tu licencia te envía un aviso la Secretaría de Estado?","o":["7 días","90 días","30 días","6 meses"],"h1":"Es más o menos un mes.","h2":"En Illinois, la Secretaría de Estado envía un aviso 30 días antes de que venza tu licencia.","p":"Correcto. El aviso llega 30 días antes."},"ref":{"doc":"IL","page":null}},{"id":"il-076","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, what is the fee for an original 4-year driver's license for an adult under 69?","o":["$10","$60","$100","$30"],"h1":"It is less than $50.","h2":"In Illinois, the fee for an original 4-year driver's license is $30.","p":"Right. The 4-year license costs $30."},"es":{"q":"En Illinois, ¿cuánto cuesta una licencia de conducir original de 4 años para un adulto menor de 69 años?","o":["$10","$60","$100","$30"],"h1":"Es menos de $50.","h2":"En Illinois, la licencia de conducir original de 4 años cuesta $30.","p":"Correcto. La licencia de 4 años cuesta $30."},"ref":{"doc":"IL","page":null}},{"id":"il-077","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, what does a driver's license cost for a person aged 18, 19 or 20?","o":["$5","$20","$30","$50"],"h1":"Young adults pay much less than the regular fee.","h2":"In Illinois, an original or renewal license for an 18, 19 or 20-year-old costs $5.","p":"Right. It costs $5 at ages 18 to 20."},"es":{"q":"En Illinois, ¿cuánto cuesta la licencia de conducir para una persona de 18, 19 o 20 años?","o":["$5","$20","$30","$50"],"h1":"Los adultos jóvenes pagan mucho menos que la tarifa normal.","h2":"En Illinois, una licencia original o renovada para una persona de 18, 19 o 20 años cuesta $5.","p":"Correcto. Cuesta $5 entre los 18 y los 20 años."},"ref":{"doc":"IL","page":null}},{"id":"il-078","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what is the fee for a first instruction permit for a person who never held an Illinois permit or license?","o":["$5","$20","$30","$45"],"h1":"It is less than the 4-year license fee.","h2":"In Illinois, a first instruction permit costs $20 for a person under 69 who never held an Illinois permit or license.","p":"Right. A first permit costs $20."},"es":{"q":"En Illinois, ¿cuánto cuesta el primer permiso de aprendizaje para alguien que nunca tuvo permiso ni licencia de Illinois?","o":["$5","$20","$30","$45"],"h1":"Es menos que la licencia de 4 años.","h2":"En Illinois, el primer permiso de aprendizaje cuesta $20 para una persona menor de 69 años que nunca tuvo permiso ni licencia de Illinois.","p":"Correcto. El primer permiso cuesta $20."},"ref":{"doc":"IL","page":null}},{"id":"il-079","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what does a driver's license cost for a person aged 87 or older?","o":["$2","$5","Nothing, it is free","$30"],"h1":"The fee goes down with age and reaches the lowest amount possible.","h2":"In Illinois, a driver's license for a person aged 87 or older is free.","p":"Right. There is no fee at 87 and older."},"es":{"q":"En Illinois, ¿cuánto cuesta la licencia de conducir para una persona de 87 años o más?","o":["$2","$5","Nada, es gratis","$30"],"h1":"La tarifa baja con la edad y llega al monto más bajo posible.","h2":"En Illinois, la licencia de conducir para una persona de 87 años o más es gratis.","p":"Correcto. No se paga nada desde los 87 años."},"ref":{"doc":"IL","page":null}},{"id":"il-080","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, how is a license for a driver under 21 different from an adult's license?","o":["It has no photo","It is printed on paper","It looks exactly the same","It has a different look, so age is easy to see"],"h1":"Store clerks and officers can tell at a glance.","h2":"In Illinois, licenses for drivers under 21 are made to look different from licenses for drivers 21 and older.","p":"Right. Under-21 licenses have a different look."},"es":{"q":"En Illinois, ¿en qué se diferencia la licencia de un conductor menor de 21 años de la de un adulto?","o":["No tiene foto","Está impresa en papel","Se ve exactamente igual","Tiene un diseño distinto, para ver la edad fácilmente"],"h1":"Los empleados de tiendas y los policías lo notan con solo mirarla.","h2":"En Illinois, las licencias de los conductores menores de 21 años tienen un diseño distinto al de los conductores de 21 años o más.","p":"Correcto. Las licencias de menores de 21 tienen un diseño distinto."},"ref":{"doc":"IL","page":null}},{"id":"il-081","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, your license expires 3 months after your 21st birthday. When may you apply to renew it?","o":["Not until you turn 21","Any time after you turn 20","Only after it expires","One year before it expires"],"h1":"You need the adult license, so you must reach the adult age first.","h2":"In Illinois, a license that expires 3 months after the 21st birthday cannot be renewed until the driver turns 21.","p":"Right. You must turn 21 before you renew."},"es":{"q":"En Illinois, tu licencia vence 3 meses después de que cumples 21 años. ¿Cuándo puedes pedir la renovación?","o":["No antes de cumplir 21 años","En cualquier momento después de cumplir 20","Solo después de que venza","Un año antes de que venza"],"h1":"Necesitas la licencia de adulto, así que primero debes llegar a esa edad.","h2":"En Illinois, una licencia que vence 3 meses después de cumplir 21 años no se puede renovar hasta que el conductor cumpla 21.","p":"Correcto. Debes cumplir 21 años antes de renovar."},"ref":{"doc":"IL","page":null}},{"id":"il-082","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, you lend your driver's license to a friend. What is the least penalty for a first conviction?","o":["A written warning","A $500 fine or 50 hours of community service","A $50 fine","Nothing, if the friend does not drive"],"h1":"It is treated as a crime, not a small ticket.","h2":"In Illinois, lending your license to someone is a Class A misdemeanor with at least a $500 fine or 50 hours of community service.","p":"Right. The minimum is a $500 fine or 50 hours of service."},"es":{"q":"En Illinois, le prestas tu licencia de conducir a un amigo. ¿Cuál es la pena mínima por una primera condena?","o":["Una advertencia por escrito","Una multa de $500 o 50 horas de servicio comunitario","Una multa de $50","Nada, si el amigo no conduce"],"h1":"Se trata como un delito, no como una multa pequeña.","h2":"En Illinois, prestar tu licencia a otra persona es un delito menor de clase A con una multa de al menos $500 o 50 horas de servicio comunitario.","p":"Correcto. El mínimo es una multa de $500 o 50 horas de servicio."},"ref":{"doc":"IL","page":null}},{"id":"il-083","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what do you need to drive a moped on the road?","o":["A commercial driver's license","A motorcycle class only","A valid Illinois driver's license of any class","Nothing at all"],"h1":"A regular car license is enough.","h2":"In Illinois, you may drive a moped with a valid Illinois driver's license of any class.","p":"Right. Any valid Illinois license covers a moped."},"es":{"q":"En Illinois, ¿qué necesitas para conducir un ciclomotor (moped) en la calle?","o":["Una licencia comercial","Solo la clase de motocicleta","Una licencia de conducir válida de Illinois de cualquier clase","Nada"],"h1":"Una licencia normal de auto es suficiente.","h2":"En Illinois, puedes conducir un ciclomotor con una licencia de conducir válida de Illinois de cualquier clase.","p":"Correcto. Cualquier licencia válida de Illinois sirve para un ciclomotor."},"ref":{"doc":"IL","page":null}},{"id":"il-084","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, a 19-year-old wants a job driving children to and from a day camp. Is this allowed?","o":["Yes, with any license","Yes, if a parent rides along","Yes, but only in daylight","No, the driver must be at least 21 with a year of experience"],"h1":"Carrying children for a school or camp needs an older, experienced driver.","h2":"In Illinois, a driver under 21 or with less than one year of driving experience may not drive children to or from a school or camp.","p":"Right. You must be 21 with a year of experience."},"es":{"q":"En Illinois, una persona de 19 años quiere un trabajo llevando niños a un campamento de día. ¿Está permitido?","o":["Sí, con cualquier licencia","Sí, si va un padre","Sí, pero solo de día","No, el conductor debe tener al menos 21 años y un año de experiencia"],"h1":"Llevar niños para una escuela o un campamento exige un conductor mayor y con experiencia.","h2":"En Illinois, un conductor menor de 21 años o con menos de un año de experiencia no puede llevar niños a una escuela o campamento.","p":"Correcto. Debes tener 21 años y un año de experiencia."},"ref":{"doc":"IL","page":null}},{"id":"il-085","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, a 17-year-old wants to drive a car to carry passengers for pay. Is this allowed?","o":["No, a license for paid driving needs age 18","Yes, with a graduated license","Yes, on weekends only","Yes, if the passengers are adults"],"h1":"Driving for money has a minimum age.","h2":"In Illinois, a person under 18 cannot get a license to carry passengers or property for pay.","p":"Right. You must be 18 to drive for pay."},"es":{"q":"En Illinois, un joven de 17 años quiere conducir un auto para llevar pasajeros a cambio de pago. ¿Está permitido?","o":["No, la licencia para conducir por pago exige 18 años","Sí, con una licencia gradual","Sí, solo los fines de semana","Sí, si los pasajeros son adultos"],"h1":"Conducir por dinero tiene una edad mínima.","h2":"En Illinois, una persona menor de 18 años no puede obtener una licencia para llevar pasajeros o carga a cambio de pago.","p":"Correcto. Debes tener 18 años para conducir por pago."},"ref":{"doc":"IL","page":null}},{"id":"il-086","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what license do you need to drive an autocycle (a three-wheeled vehicle with a steering wheel)?","o":["A motorcycle Class M license","A valid Class D license","A commercial license","No license"],"h1":"It is the regular license for cars.","h2":"In Illinois, you need a valid Class D driver's license to drive an autocycle.","p":"Right. An autocycle needs a Class D license."},"es":{"q":"En Illinois, ¿qué licencia necesitas para conducir un autociclo (un vehículo de tres ruedas con volante)?","o":["Una licencia de motocicleta clase M","Una licencia válida clase D","Una licencia comercial","Ninguna licencia"],"h1":"Es la licencia normal para autos.","h2":"En Illinois, necesitas una licencia de conducir válida clase D para conducir un autociclo.","p":"Correcto. El autociclo exige licencia clase D."},"ref":{"doc":"IL","page":null}},{"id":"il-087","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, a 17-year-old wants a motorcycle license. What must they complete besides the teen license rules?","o":["A car road test only","A first aid course","A motorcycle training course approved by the state","Nothing extra"],"h1":"It is a special class for riding.","h2":"In Illinois, a person under 18 must complete a motorcycle training course approved by the Illinois Department of Transportation to get a motorcycle license.","p":"Right. Teens need an approved motorcycle course."},"es":{"q":"En Illinois, un joven de 17 años quiere licencia de motocicleta. ¿Qué debe completar además de las reglas para adolescentes?","o":["Solo un examen práctico en auto","Un curso de primeros auxilios","Un curso de motocicleta aprobado por el estado","Nada más"],"h1":"Es una clase especial para manejar motocicleta.","h2":"En Illinois, una persona menor de 18 años debe completar un curso de motocicleta aprobado por el Departamento de Transporte de Illinois para obtener la licencia de motocicleta.","p":"Correcto. Los adolescentes necesitan un curso de motocicleta aprobado."},"ref":{"doc":"IL","page":null}},{"id":"il-088","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, when may a person with a motorcycle instruction permit ride on the highway?","o":["Any time, alone","Only at night when traffic is light","Only on interstates","Only in daylight, with a licensed rider 21 or older"],"h1":"Darkness and riding alone are both ruled out.","h2":"In Illinois, a motorcycle instruction permit allows riding only in daylight, under the supervision of a licensed rider who is 21 or older.","p":"Right. Daylight only, with a licensed rider 21 or older."},"es":{"q":"En Illinois, ¿cuándo puede manejar en la vía una persona con permiso de aprendizaje de motocicleta?","o":["A cualquier hora, solo","Solo de noche cuando hay poco tráfico","Solo en autopistas interestatales","Solo de día, con un motociclista con licencia de 21 años o más"],"h1":"La oscuridad y manejar solo están descartados.","h2":"En Illinois, el permiso de aprendizaje de motocicleta solo permite manejar de día, con la supervisión de un motociclista con licencia de 21 años o más.","p":"Correcto. Solo de día, con un motociclista con licencia de 21 años o más."},"ref":{"doc":"IL","page":null}},{"id":"il-089","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, how many moving violation convictions within 12 months can lead to a license suspension for an adult driver?","o":["3","2","5","10"],"h1":"It is one more than the number that affects drivers under 21.","h2":"In Illinois, the Secretary of State may suspend or revoke a license after 3 moving violation convictions within any 12 months.","p":"Right. Three convictions in 12 months can cost you your license."},"es":{"q":"En Illinois, ¿cuántas condenas por infracciones de tránsito en 12 meses pueden llevar a suspender la licencia de un conductor adulto?","o":["3","2","5","10"],"h1":"Es una más que el número que afecta a los menores de 21 años.","h2":"En Illinois, la Secretaría de Estado puede suspender o revocar la licencia después de 3 condenas por infracciones de tránsito en cualquier período de 12 meses.","p":"Correcto. Tres condenas en 12 meses pueden costarte la licencia."},"ref":{"doc":"IL","page":null}},{"id":"il-090","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, a 19-year-old man applies for a driver's license. What does his signature on the application also do?","o":["It signs him up for jury duty","It registers him with the Selective Service System if he is not already registered","It registers him to vote in every election","It makes him an organ donor"],"h1":"It is a federal list for young men.","h2":"In Illinois, a man aged 18 to 25 who applies for a license is registered with the Selective Service System through his signature, if he is not already registered.","p":"Right. His signature also registers him with Selective Service."},"es":{"q":"En Illinois, un hombre de 19 años solicita una licencia de conducir. ¿Qué más hace su firma en la solicitud?","o":["Lo inscribe para servir como jurado","Lo inscribe en el Servicio Selectivo si aún no lo está","Lo inscribe para votar en todas las elecciones","Lo hace donante de órganos"],"h1":"Es una lista federal para hombres jóvenes.","h2":"En Illinois, un hombre de 18 a 25 años que solicita la licencia queda inscrito en el Servicio Selectivo con su firma, si aún no lo está.","p":"Correcto. Su firma también lo inscribe en el Servicio Selectivo."},"ref":{"doc":"IL","page":null}},{"id":"il-091","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what are applicants 16 or older offered when they get or renew a driver's license?","o":["A required blood test","A required donation to a charity","A free choice to join the organ and tissue donor registry","A discount on car insurance"],"h1":"It is a choice about helping others after death.","h2":"In Illinois, applicants 16 and older are offered the choice to join the organ and tissue donor registry, and they are under no pressure to join.","p":"Right. Joining the donor registry is offered, and it is your choice."},"es":{"q":"En Illinois, ¿qué se ofrece a los solicitantes de 16 años o más cuando obtienen o renuevan la licencia?","o":["Un análisis de sangre obligatorio","Una donación obligatoria a una organización benéfica","La libre opción de inscribirse en el registro de donantes de órganos y tejidos","Un descuento en el seguro del auto"],"h1":"Es una decisión sobre ayudar a otros después de la muerte.","h2":"En Illinois, a los solicitantes de 16 años o más se les ofrece inscribirse en el registro de donantes de órganos y tejidos, sin ninguna obligación.","p":"Correcto. Se ofrece el registro de donantes y la decisión es tuya."},"ref":{"doc":"IL","page":null}},{"id":"il-092","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, the parent who signed for a 16-year-old's license wants it cancelled. Can the parent do this?","o":["No, only a judge can cancel it","No, once issued it cannot be cancelled","Only if the teen agrees","Yes, by asking the Secretary of State in writing"],"h1":"The adult who gave consent can take it back.","h2":"In Illinois, the person who consented to a minor's license may have it cancelled with a signed written request to the Secretary of State.","p":"Right. The parent can ask in writing to cancel it."},"es":{"q":"En Illinois, el padre que firmó la licencia de un joven de 16 años quiere cancelarla. ¿Puede hacerlo?","o":["No, solo un juez puede cancelarla","No, una vez emitida no se puede cancelar","Solo si el joven está de acuerdo","Sí, pidiéndolo por escrito a la Secretaría de Estado"],"h1":"El adulto que dio su consentimiento puede retirarlo.","h2":"En Illinois, la persona que dio su consentimiento para la licencia de un menor puede pedir por escrito a la Secretaría de Estado que la cancele.","p":"Correcto. El padre puede pedir por escrito que se cancele."},"ref":{"doc":"IL","page":null}},{"id":"il-093","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, a 16-year-old is convicted of having illegal drugs while driving. How long is the license cancelled?","o":["One year or until age 18, whichever is longer","30 days","3 months","Until the next birthday"],"h1":"It lasts a long time, at least until adulthood.","h2":"In Illinois, a driver under 18 convicted of a cannabis or drug offense while driving loses the license for one year or until age 18, whichever is longer.","p":"Right. It is one year or until 18, whichever is longer."},"es":{"q":"En Illinois, un joven de 16 años es condenado por tener drogas ilegales mientras conducía. ¿Por cuánto tiempo se cancela la licencia?","o":["Un año o hasta los 18 años, lo que sea más largo","30 días","3 meses","Hasta su próximo cumpleaños"],"h1":"Dura mucho tiempo, por lo menos hasta la edad adulta.","h2":"En Illinois, un conductor menor de 18 años condenado por cannabis o drogas mientras conducía pierde la licencia por un año o hasta los 18 años, lo que sea más largo.","p":"Correcto. Es un año o hasta los 18, lo que sea más largo."},"ref":{"doc":"IL","page":null}},{"id":"il-094","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a 19-year-old driver is convicted for the first time of having an open alcohol container in the car. What can happen to the license?","o":["Nothing, a first time is only a warning","It can be suspended","It is upgraded to a full license","Only the passengers are punished"],"h1":"Young drivers face a loss of driving privileges even for a first time.","h2":"In Illinois, a driver under 21 convicted for the first time of carrying an open alcohol container can have the license suspended, and a second conviction leads to revocation.","p":"Right. Even a first open container conviction can suspend a young driver's license."},"es":{"q":"En Illinois, un conductor de 19 años es condenado por primera vez por llevar un envase abierto de alcohol en el auto. ¿Qué puede pasar con la licencia?","o":["Nada, la primera vez es solo una advertencia","Puede ser suspendida","Se cambia a una licencia completa","Solo se castiga a los pasajeros"],"h1":"Los conductores jóvenes pierden el privilegio de conducir incluso la primera vez.","h2":"En Illinois, a un conductor menor de 21 años condenado por primera vez por llevar un envase abierto de alcohol se le puede suspender la licencia, y una segunda condena lleva a la revocación.","p":"Correcto. Incluso la primera condena por envase abierto puede suspender la licencia de un joven."},"ref":{"doc":"IL","page":null}},{"id":"il-095","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, a driver is convicted of leaving the scene of a crash where someone was hurt. What happens to the license?","o":["It gets 2 points","It is suspended for 7 days","It must be revoked","Nothing, if the driver pays the fine"],"h1":"This is one of the most serious offenses for a driver.","h2":"In Illinois, a conviction for leaving the scene of a crash that caused injury or death means the license must be revoked.","p":"Right. The license is revoked."},"es":{"q":"En Illinois, un conductor es condenado por irse del lugar de un choque donde alguien resultó herido. ¿Qué pasa con la licencia?","o":["Recibe 2 puntos","Se suspende por 7 días","Debe ser revocada","Nada, si el conductor paga la multa"],"h1":"Es una de las faltas más graves para un conductor.","h2":"En Illinois, una condena por irse del lugar de un choque con heridos o muertos significa que la licencia debe ser revocada.","p":"Correcto. La licencia se revoca."},"ref":{"doc":"IL","page":null}},{"id":"il-096","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how many reckless driving convictions within 12 months lead to a mandatory license revocation?","o":["1","2","5","3"],"h1":"It is the same number as the moving violations that allow a suspension.","h2":"In Illinois, 3 reckless driving convictions within 12 months mean the license must be revoked.","p":"Right. Three reckless driving convictions in 12 months mean revocation."},"es":{"q":"En Illinois, ¿cuántas condenas por manejo imprudente en 12 meses llevan a la revocación obligatoria de la licencia?","o":["1","2","5","3"],"h1":"Es el mismo número de infracciones de tránsito que permite una suspensión.","h2":"En Illinois, 3 condenas por manejo imprudente en 12 meses significan que la licencia debe ser revocada.","p":"Correcto. Tres condenas por manejo imprudente en 12 meses significan revocación."},"ref":{"doc":"IL","page":null}},{"id":"il-097","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, what happens to a driver convicted of street racing for the first time?","o":["A fine of at least $250 and the license is revoked","A warning only","A $25 fine","2 points on the record and nothing else"],"h1":"The law treats racing on public roads as a crime that costs you your license.","h2":"In Illinois, a first street racing conviction is a Class A misdemeanor with at least a $250 fine, and the driver's license is revoked.","p":"Right. Street racing brings a fine of at least $250 and revocation."},"es":{"q":"En Illinois, ¿qué le pasa a un conductor condenado por primera vez por carreras en la calle?","o":["Una multa de al menos $250 y se revoca la licencia","Solo una advertencia","Una multa de $25","2 puntos en el historial y nada más"],"h1":"La ley trata las carreras en vías públicas como un delito que te cuesta la licencia.","h2":"En Illinois, una primera condena por carreras en la calle es un delito menor de clase A con una multa de al menos $250, y se revoca la licencia de conducir.","p":"Correcto. Las carreras en la calle traen una multa de al menos $250 y la revocación."},"ref":{"doc":"IL","page":null}},{"id":"il-098","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, what kind of offense is driving while your license is suspended?","o":["A parking ticket","A Class A misdemeanor, a crime","A petty offense with no record","It is not an offense if you drive carefully"],"h1":"It is more than a simple traffic ticket.","h2":"In Illinois, driving while your license is suspended or revoked is a Class A misdemeanor.","p":"Right. It is a Class A misdemeanor."},"es":{"q":"En Illinois, ¿qué tipo de falta es conducir con la licencia suspendida?","o":["Una multa de estacionamiento","Un delito menor de clase A","Una falta menor sin antecedentes","No es falta si conduces con cuidado"],"h1":"Es más que una simple multa de tránsito.","h2":"En Illinois, conducir con la licencia suspendida o revocada es un delito menor de clase A.","p":"Correcto. Es un delito menor de clase A."},"ref":{"doc":"IL","page":null}},{"id":"il-099","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, a driver in an injury crash did not stay at the scene. By when must the driver report the crash at a police station?","o":["Within 24 hours","Within 10 days","Within one-half hour","Within one week"],"h1":"The time is very short, less than an hour.","h2":"In Illinois, a driver who did not stay at the scene of an injury crash must report it at a police station or sheriff's office within one-half hour.","p":"Right. The report must be made within half an hour."},"es":{"q":"En Illinois, un conductor en un choque con heridos no se quedó en el lugar. ¿En cuánto tiempo debe reportar el choque en una estación de policía?","o":["Dentro de 24 horas","Dentro de 10 días","Dentro de media hora","Dentro de una semana"],"h1":"El tiempo es muy corto, menos de una hora.","h2":"En Illinois, un conductor que no se quedó en el lugar de un choque con heridos debe reportarlo en una estación de policía u oficina del sheriff dentro de media hora.","p":"Correcto. El reporte se debe hacer dentro de media hora."},"ref":{"doc":"IL","page":null}},{"id":"il-100","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, you have a small crash on a busy highway. No one is hurt and your car still runs. What may you do?","o":["Leave the scene and call later","Leave the cars in the lane until police arrive","Drive home and report it the next day","Move the car to a nearby safe place off the road and stay there"],"h1":"You must not block traffic, but you must not leave either.","h2":"In Illinois, after a crash with only vehicle damage, you may move your car off the highway to the nearest safe place, such as a shoulder or cross street, and stay there to exchange information.","p":"Right. Move to a safe spot nearby and stay there."},"es":{"q":"En Illinois, tienes un choque leve en una vía con mucho tráfico. Nadie está herido y tu auto funciona. ¿Qué puedes hacer?","o":["Irte y llamar después","Dejar los autos en el carril hasta que llegue la policía","Ir a casa y reportarlo al día siguiente","Mover el auto a un lugar seguro cercano fuera de la vía y quedarte allí"],"h1":"No debes bloquear el tráfico, pero tampoco debes irte.","h2":"En Illinois, después de un choque con solo daños a vehículos, puedes mover tu auto fuera de la vía al lugar seguro más cercano, como el acotamiento o una calle cercana, y quedarte allí para intercambiar datos.","p":"Correcto. Muévete a un lugar seguro cercano y quédate allí."},"ref":{"doc":"IL","page":null}},{"id":"il-101","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, you hit a parked car and cannot find its owner. What must you do?","o":["Leave a note with your name, address and plate number, and tell the police","Drive away, since no one saw it","Wait one hour and then leave","Only call your insurance company"],"h1":"The owner must be able to find you.","h2":"In Illinois, if you hit an unattended car and cannot find the owner, you must securely leave a written note with your name, address, registration number and the vehicle owner, and notify the police.","p":"Right. Leave a note and notify the police."},"es":{"q":"En Illinois, chocas un auto estacionado y no encuentras al dueño. ¿Qué debes hacer?","o":["Dejar una nota con tu nombre, dirección y número de placa, y avisar a la policía","Irte, porque nadie lo vio","Esperar una hora y luego irte","Solo llamar a tu compañía de seguros"],"h1":"El dueño debe poder encontrarte.","h2":"En Illinois, si chocas un auto sin nadie y no encuentras al dueño, debes dejar bien sujeta una nota escrita con tu nombre, dirección, número de registro y el dueño del vehículo, y avisar a la policía.","p":"Correcto. Deja una nota y avisa a la policía."},"ref":{"doc":"IL","page":null}},{"id":"il-102","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, your car bumps a school bus. There is a small dent and no one is hurt. Must you notify the police?","o":["No, only if damage is over $1,500","Yes, any school bus crash with damage must be reported","No, only if someone is hurt","Only if the bus driver asks"],"h1":"School buses have a stricter rule than other crashes.","h2":"In Illinois, police must be notified of any crash involving a school bus that causes any property damage, injury or death.","p":"Right. Any school bus crash with damage must be reported."},"es":{"q":"En Illinois, tu auto golpea un autobús escolar. Hay una pequeña abolladura y nadie está herido. ¿Debes avisar a la policía?","o":["No, solo si el daño pasa de $1,500","Sí, todo choque con autobús escolar que cause daños se debe reportar","No, solo si hay heridos","Solo si el conductor del autobús lo pide"],"h1":"Los autobuses escolares tienen una regla más estricta que otros choques.","h2":"En Illinois, se debe avisar a la policía de todo choque con un autobús escolar que cause cualquier daño, heridos o muertos.","p":"Correcto. Todo choque con autobús escolar con daños se debe reportar."},"ref":{"doc":"IL","page":null}},{"id":"il-103","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, one car in a crash has no insurance. Above what amount of damage must the crash be reported to police?","o":["$1,500","$2,500","$500","$5,000"],"h1":"It is much lower than the usual amount.","h2":"In Illinois, if any vehicle in a crash is not insured, police must be notified when the damage is more than $500.","p":"Right. With an uninsured vehicle, the amount is $500."},"es":{"q":"En Illinois, uno de los autos de un choque no tiene seguro. ¿A partir de qué monto de daños se debe reportar a la policía?","o":["$1,500","$2,500","$500","$5,000"],"h1":"Es mucho menos que el monto habitual.","h2":"En Illinois, si algún vehículo del choque no tiene seguro, se debe avisar a la policía cuando los daños superan los $500.","p":"Correcto. Con un vehículo sin seguro, el monto es $500."},"ref":{"doc":"IL","page":null}},{"id":"il-104","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, what is the fine for a first or second conviction of driving a car without liability insurance?","o":["$25 to $75","$100 to $250","There is no fine, only a warning","More than $500, up to $1,000"],"h1":"It starts just above five hundred dollars.","h2":"In Illinois, a driver convicted of driving without liability insurance must pay a fine of more than $500 and up to $1,000.","p":"Right. The fine is more than $500, up to $1,000."},"es":{"q":"En Illinois, ¿cuál es la multa por una primera o segunda condena por conducir sin seguro de responsabilidad civil?","o":["De $25 a $75","De $100 a $250","No hay multa, solo una advertencia","Más de $500, hasta $1,000"],"h1":"Empieza justo por encima de quinientos dólares.","h2":"En Illinois, un conductor condenado por conducir sin seguro de responsabilidad civil debe pagar una multa de más de $500 y hasta $1,000.","p":"Correcto. La multa es de más de $500, hasta $1,000."},"ref":{"doc":"IL","page":null}},{"id":"il-105","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, an officer asks for your proof of insurance and you do not show it. How is this treated?","o":["As if you were driving without insurance","As a parking ticket","It is not an offense","As a seat belt ticket"],"h1":"The officer cannot tell if you are insured without proof.","h2":"In Illinois, if you do not show proof of insurance when an officer asks, you are treated as driving an uninsured vehicle, unless you later prove in court that you were insured.","p":"Right. No proof is treated as no insurance."},"es":{"q":"En Illinois, un policía te pide el comprobante del seguro y no lo muestras. ¿Cómo se trata esto?","o":["Como si condujeras sin seguro","Como una multa de estacionamiento","No es una infracción","Como una multa por cinturón de seguridad"],"h1":"El policía no puede saber si tienes seguro sin el comprobante.","h2":"En Illinois, si no muestras el comprobante del seguro cuando un policía lo pide, se te trata como si condujeras sin seguro, salvo que luego pruebes en el tribunal que estabas asegurado.","p":"Correcto. Sin comprobante se trata como sin seguro."},"ref":{"doc":"IL","page":null}},{"id":"il-106","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, may you show your proof of insurance on your phone screen?","o":["No, only a paper card counts","Yes, an electronic insurance card is allowed","Only if the officer agrees to take your phone","Only for rental cars"],"h1":"Illinois accepts digital proof.","h2":"In Illinois, you may show proof of insurance as an electronic image on a phone or other device, and showing it does not let the officer look at anything else on the device.","p":"Right. A digital insurance card on your phone is accepted."},"es":{"q":"En Illinois, ¿puedes mostrar el comprobante del seguro en la pantalla de tu teléfono?","o":["No, solo cuenta la tarjeta de papel","Sí, se acepta la tarjeta de seguro electrónica","Solo si el policía acepta llevarse tu teléfono","Solo en autos de alquiler"],"h1":"Illinois acepta comprobantes digitales.","h2":"En Illinois, puedes mostrar el comprobante del seguro como imagen electrónica en un teléfono u otro aparato, y mostrarlo no permite que el policía revise nada más del aparato.","p":"Correcto. Se acepta la tarjeta de seguro digital en tu teléfono."},"ref":{"doc":"IL","page":null}},{"id":"il-107","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, a car's registration was suspended because it had no insurance. What is the fine for driving it anyway?","o":["$50 to $100","$250 to $500","$1,000 to $2,000","There is no fine"],"h1":"It is in the thousands of dollars.","h2":"In Illinois, driving a vehicle whose registration is suspended for lack of insurance brings a fine of $1,000 to $2,000.","p":"Right. The fine is $1,000 to $2,000."},"es":{"q":"En Illinois, el registro de un auto fue suspendido porque no tenía seguro. ¿Cuál es la multa por conducirlo de todos modos?","o":["De $50 a $100","De $250 a $500","De $1,000 a $2,000","No hay multa"],"h1":"Son miles de dólares.","h2":"En Illinois, conducir un vehículo con el registro suspendido por falta de seguro trae una multa de $1,000 a $2,000.","p":"Correcto. La multa es de $1,000 a $2,000."},"ref":{"doc":"IL","page":null}},{"id":"il-108","scope":"IL","cat":"licensing","sign":null,"c":3,"en":{"q":"In Illinois, you move here with a car registered in another state. How soon must you register it in Illinois?","o":["Within 90 days","Within 1 year","Only when the old registration expires","Within 30 days"],"h1":"It is sooner than the time you have to get an Illinois license.","h2":"In Illinois, a new resident must register a vehicle within 30 days, as long as it is properly registered in another state.","p":"Right. New residents have 30 days to register their vehicle."},"es":{"q":"En Illinois, te mudas con un auto registrado en otro estado. ¿En cuánto tiempo debes registrarlo en Illinois?","o":["Dentro de 90 días","Dentro de 1 año","Solo cuando venza el registro anterior","Dentro de 30 días"],"h1":"Es antes que el plazo para obtener la licencia de Illinois.","h2":"En Illinois, un nuevo residente debe registrar su vehículo dentro de 30 días, siempre que esté bien registrado en otro estado.","p":"Correcto. Los nuevos residentes tienen 30 días para registrar su vehículo."},"ref":{"doc":"IL","page":null}},{"id":"il-109","scope":"IL","cat":"licensing","sign":null,"c":0,"en":{"q":"In Illinois, where must license plates be on a passenger car?","o":["One on the front and one on the rear","Only on the rear","Only on the front","One inside the windshield"],"h1":"Illinois issues a pair of plates for cars.","h2":"In Illinois, a passenger car must have two license plates, one on the front and one on the rear.","p":"Right. Cars need front and rear plates."},"es":{"q":"En Illinois, ¿dónde deben ir las placas en un auto de pasajeros?","o":["Una adelante y una atrás","Solo atrás","Solo adelante","Una dentro del parabrisas"],"h1":"Illinois entrega un par de placas para los autos.","h2":"En Illinois, un auto de pasajeros debe tener dos placas, una adelante y una atrás.","p":"Correcto. Los autos necesitan placa adelante y atrás."},"ref":{"doc":"IL","page":null}},{"id":"il-110","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, you renewed your registration but the new sticker has not arrived. What lets you keep driving legally?","o":["Nothing, you must wait at home","The printed receipt from the Secretary of State, for 30 days","A handwritten note on the window","The old sticker for 6 more months"],"h1":"Keep the paper you got when you paid.","h2":"In Illinois, a printed receipt from the Secretary of State shows your registration for 30 days until the new sticker arrives.","p":"Right. The printed receipt works for 30 days."},"es":{"q":"En Illinois, renovaste el registro pero la nueva calcomanía no ha llegado. ¿Qué te permite seguir conduciendo legalmente?","o":["Nada, debes esperar en casa","El recibo impreso de la Secretaría de Estado, por 30 días","Una nota escrita a mano en la ventana","La calcomanía vieja por 6 meses más"],"h1":"Guarda el papel que te dieron al pagar.","h2":"En Illinois, un recibo impreso de la Secretaría de Estado demuestra tu registro por 30 días hasta que llegue la nueva calcomanía.","p":"Correcto. El recibo impreso sirve por 30 días."},"ref":{"doc":"IL","page":null}},{"id":"il-111","scope":"IL","cat":"licensing","sign":null,"c":2,"en":{"q":"In Illinois, what is the fee for a certificate of title for a regular passenger car?","o":["$15","$50","$165","$500"],"h1":"It is between $100 and $200.","h2":"In Illinois, a certificate of title for a regular vehicle costs $165.","p":"Right. A title costs $165."},"es":{"q":"En Illinois, ¿cuánto cuesta el certificado de título de un auto de pasajeros común?","o":["$15","$50","$165","$500"],"h1":"Está entre $100 y $200.","h2":"En Illinois, el certificado de título de un vehículo común cuesta $165.","p":"Correcto. El título cuesta $165."},"ref":{"doc":"IL","page":null}},{"id":"il-112","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, at what blood alcohol level or below does the law presume a driver was not under the influence of alcohol?","o":["0.08 or less","0.10 or less","0.02 or less","0.05 or less"],"h1":"It is a bit more than half of the legal limit.","h2":"In Illinois, a blood alcohol level of 0.05 or less creates a presumption that the driver was not under the influence of alcohol.","p":"Right. At 0.05 or less, the law presumes the driver was not under the influence."},"es":{"q":"En Illinois, ¿con qué nivel de alcohol en la sangre o menos presume la ley que el conductor no estaba bajo la influencia del alcohol?","o":["0.08 o menos","0.10 o menos","0.02 o menos","0.05 o menos"],"h1":"Es un poco más de la mitad del límite legal.","h2":"En Illinois, un nivel de alcohol en la sangre de 0.05 o menos crea la presunción de que el conductor no estaba bajo la influencia del alcohol.","p":"Correcto. Con 0.05 o menos, la ley presume que no estaba bajo la influencia."},"ref":{"doc":"IL","page":null}},{"id":"il-113","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, an adult driver has a blood alcohol level of 0.06. Can they still be charged with DUI?","o":["Yes, if other evidence shows they were impaired","No, anything under 0.08 is always legal","No, only drivers over 0.10 are charged","Only if they are under 18"],"h1":"A level under 0.08 does not mean you are safe to drive.","h2":"In Illinois, a blood alcohol level above 0.05 and below 0.08 can be used with other evidence to show a driver was under the influence.","p":"Right. Between 0.05 and 0.08 you can still be charged if impaired."},"es":{"q":"En Illinois, un conductor adulto tiene un nivel de alcohol en la sangre de 0.06. ¿Lo pueden acusar de manejar bajo la influencia?","o":["Sí, si otras pruebas muestran que estaba afectado","No, menos de 0.08 siempre es legal","No, solo se acusa a quienes pasan de 0.10","Solo si es menor de 18 años"],"h1":"Un nivel menor de 0.08 no significa que puedas conducir con seguridad.","h2":"En Illinois, un nivel de alcohol en la sangre de más de 0.05 y menos de 0.08 puede usarse junto con otras pruebas para mostrar que el conductor estaba bajo la influencia.","p":"Correcto. Entre 0.05 y 0.08 te pueden acusar si estás afectado."},"ref":{"doc":"IL","page":null}},{"id":"il-114","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what amount of THC in whole blood is the legal limit for driving under the influence of cannabis?","o":["1 nanogram or more per milliliter","5 nanograms or more per milliliter","20 nanograms or more per milliliter","There is no limit for cannabis"],"h1":"It is a single-digit number.","h2":"In Illinois, a THC level of 5 nanograms or more per milliliter of whole blood, or 10 or more in another body fluid, is over the limit for cannabis.","p":"Right. The limit is 5 nanograms per milliliter of whole blood."},"es":{"q":"En Illinois, ¿qué cantidad de THC en la sangre es el límite legal para conducir bajo la influencia del cannabis?","o":["1 nanogramo o más por mililitro","5 nanogramos o más por mililitro","20 nanogramos o más por mililitro","No hay límite para el cannabis"],"h1":"Es un número de una sola cifra.","h2":"En Illinois, un nivel de THC de 5 nanogramos o más por mililitro de sangre, o de 10 o más en otro fluido del cuerpo, supera el límite para el cannabis.","p":"Correcto. El límite es 5 nanogramos por mililitro de sangre."},"ref":{"doc":"IL","page":null}},{"id":"il-115","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, what kind of offense is a first DUI with no injuries or other aggravating factors?","o":["A petty traffic offense","A Class X felony","A Class A misdemeanor","An ordinance violation with no record"],"h1":"It is a crime, but not yet a felony.","h2":"In Illinois, a first DUI with no aggravating factors is a Class A misdemeanor.","p":"Right. A first DUI is a Class A misdemeanor."},"es":{"q":"En Illinois, ¿qué tipo de falta es un primer caso de manejar bajo la influencia sin heridos ni agravantes?","o":["Una falta de tránsito menor","Un delito grave de clase X","Un delito menor de clase A","Una violación municipal sin antecedentes"],"h1":"Es un delito, pero todavía no es un delito grave.","h2":"En Illinois, un primer caso de manejar bajo la influencia sin agravantes es un delito menor de clase A.","p":"Correcto. El primer caso es un delito menor de clase A."},"ref":{"doc":"IL","page":null}},{"id":"il-116","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, a driver commits DUI while carrying a child under 16. What extra penalties apply?","o":["Only a $100 fine","A warning if the child was buckled","No extra penalty","Up to 6 months in jail, at least $1,000 more in fines and 25 days of community service"],"h1":"The law adds heavy penalties to protect children.","h2":"In Illinois, a driver who commits DUI while carrying a passenger under 16 faces up to 6 months in jail, an extra fine of at least $1,000 and 25 days of community service in a program that helps children.","p":"Right. A child passenger brings jail time, at least $1,000 more and 25 days of service."},"es":{"q":"En Illinois, un conductor maneja bajo la influencia llevando a un niño menor de 16 años. ¿Qué penas extra se aplican?","o":["Solo una multa de $100","Una advertencia si el niño llevaba cinturón","Ninguna pena extra","Hasta 6 meses de cárcel, al menos $1,000 más de multa y 25 días de servicio comunitario"],"h1":"La ley agrega penas fuertes para proteger a los niños.","h2":"En Illinois, un conductor que maneja bajo la influencia con un pasajero menor de 16 años puede recibir hasta 6 meses de cárcel, una multa extra de al menos $1,000 y 25 días de servicio comunitario en un programa que ayuda a niños.","p":"Correcto. Un niño pasajero trae cárcel, al menos $1,000 más y 25 días de servicio."},"ref":{"doc":"IL","page":null}},{"id":"il-117","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a first-time DUI driver had a blood alcohol level of 0.16 or more. What must be added to the sentence?","o":["At least 100 hours of community service and a $500 fine","Only a written warning","A 10-day suspension and nothing else","A $25 fine"],"h1":"A level twice the limit brings extra required penalties.","h2":"In Illinois, a first DUI with a blood alcohol level of 0.16 or more adds at least 100 hours of community service and a minimum $500 fine.","p":"Right. At 0.16 or more, add 100 hours of service and a $500 fine."},"es":{"q":"En Illinois, un conductor en su primer caso de manejar bajo la influencia tenía un nivel de alcohol de 0.16 o más. ¿Qué se agrega a la condena?","o":["Al menos 100 horas de servicio comunitario y una multa de $500","Solo una advertencia por escrito","Una suspensión de 10 días y nada más","Una multa de $25"],"h1":"Un nivel del doble del límite trae penas extra obligatorias.","h2":"En Illinois, un primer caso de manejar bajo la influencia con un nivel de alcohol de 0.16 o más agrega al menos 100 horas de servicio comunitario y una multa mínima de $500.","p":"Correcto. Con 0.16 o más, se agregan 100 horas de servicio y una multa de $500."},"ref":{"doc":"IL","page":null}},{"id":"il-118","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, what is the minimum sentence for a second DUI conviction?","o":["A warning letter","5 days in jail or 240 hours of community service","A $50 fine","1 day of traffic school"],"h1":"The court cannot let a second offense go without time served or a lot of service hours.","h2":"In Illinois, a second DUI conviction carries at least 5 days in jail or 240 hours of community service.","p":"Right. The minimum is 5 days in jail or 240 hours of service."},"es":{"q":"En Illinois, ¿cuál es la condena mínima por un segundo caso de manejar bajo la influencia?","o":["Una carta de advertencia","5 días de cárcel o 240 horas de servicio comunitario","Una multa de $50","1 día de escuela de tránsito"],"h1":"El tribunal no puede dejar pasar un segundo caso sin cárcel o muchas horas de servicio.","h2":"En Illinois, una segunda condena por manejar bajo la influencia trae al menos 5 días de cárcel o 240 horas de servicio comunitario.","p":"Correcto. El mínimo es 5 días de cárcel o 240 horas de servicio."},"ref":{"doc":"IL","page":null}},{"id":"il-119","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, what kind of offense is a third DUI?","o":["A misdemeanor, the same as the first","A petty offense","A felony (aggravated DUI)","An ordinance violation"],"h1":"Repeat offenses move up to the most serious class of crimes.","h2":"In Illinois, a third DUI is aggravated DUI, a Class 2 felony.","p":"Right. A third DUI is a felony."},"es":{"q":"En Illinois, ¿qué tipo de falta es un tercer caso de manejar bajo la influencia?","o":["Un delito menor, igual que el primero","Una falta menor","Un delito grave (manejo agravado bajo la influencia)","Una violación municipal"],"h1":"Las faltas repetidas pasan a la clase de delitos más graves.","h2":"En Illinois, un tercer caso de manejar bajo la influencia es manejo agravado, un delito grave de clase 2.","p":"Correcto. El tercer caso es un delito grave."},"ref":{"doc":"IL","page":null}},{"id":"il-120","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, what does it mean that drivers have given \"implied consent\"?","o":["You agree to let police search your phone","You agree to pay any ticket without court","You agree to have your car inspected every year","By driving, you agree to chemical tests if arrested for DUI"],"h1":"It is about breath, blood or urine tests.","h2":"In Illinois, anyone who drives on public highways is considered to have agreed to breath, blood or urine tests if arrested for DUI.","p":"Right. Driving means you agree to chemical tests after a DUI arrest."},"es":{"q":"En Illinois, ¿qué significa que los conductores han dado su \"consentimiento implícito\"?","o":["Que aceptas que la policía revise tu teléfono","Que aceptas pagar cualquier multa sin ir al tribunal","Que aceptas inspeccionar tu auto cada año","Que al conducir aceptas pruebas químicas si te arrestan por manejar bajo la influencia"],"h1":"Se trata de pruebas de aliento, sangre u orina.","h2":"En Illinois, se considera que toda persona que conduce en vías públicas aceptó pruebas de aliento, sangre u orina si la arrestan por manejar bajo la influencia.","p":"Correcto. Conducir significa aceptar pruebas químicas tras un arresto por manejar bajo la influencia."},"ref":{"doc":"IL","page":null}},{"id":"il-121","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, after a driver is given notice of a statutory summary suspension for DUI, when does it start?","o":["On the 46th day after the notice","Right away","After 1 year","Only after a conviction in court"],"h1":"It begins about a month and a half later.","h2":"In Illinois, a statutory summary suspension takes effect on the 46th day after the driver is given notice.","p":"Right. It starts on the 46th day."},"es":{"q":"En Illinois, después de que un conductor recibe aviso de una suspensión sumaria por manejar bajo la influencia, ¿cuándo empieza?","o":["El día 46 después del aviso","De inmediato","Después de 1 año","Solo después de una condena en el tribunal"],"h1":"Empieza más o menos un mes y medio después.","h2":"En Illinois, la suspensión sumaria empieza el día 46 después de que el conductor recibe el aviso.","p":"Correcto. Empieza el día 46."},"ref":{"doc":"IL","page":null}},{"id":"il-122","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a driver who is not a first offender refuses a chemical test after a DUI arrest. How long is the summary suspension?","o":["6 months","3 years","1 year","30 days"],"h1":"It is much longer than the suspension for a first offender who refuses.","h2":"In Illinois, a driver who is not a first offender and refuses the chemical test gets a 3-year summary suspension.","p":"Right. A repeat offender who refuses is suspended for 3 years."},"es":{"q":"En Illinois, un conductor que no es infractor por primera vez se niega a una prueba química tras un arresto por manejar bajo la influencia. ¿Cuánto dura la suspensión sumaria?","o":["6 meses","3 años","1 año","30 días"],"h1":"Es mucho más larga que la de un infractor por primera vez que se niega.","h2":"En Illinois, un conductor que no es infractor por primera vez y se niega a la prueba química recibe una suspensión sumaria de 3 años.","p":"Correcto. Un reincidente que se niega queda suspendido 3 años."},"ref":{"doc":"IL","page":null}},{"id":"il-123","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a driver who is not a first offender tests at 0.08 or more after a DUI arrest. How long is the summary suspension?","o":["6 months","3 months","1 year","3 years"],"h1":"It is twice as long as for a first offender who fails the test.","h2":"In Illinois, a driver who is not a first offender and tests at 0.08 or more gets a 1-year summary suspension.","p":"Right. A repeat offender who fails the test is suspended for 1 year."},"es":{"q":"En Illinois, un conductor que no es infractor por primera vez da 0.08 o más tras un arresto por manejar bajo la influencia. ¿Cuánto dura la suspensión sumaria?","o":["6 meses","3 meses","1 año","3 años"],"h1":"Es el doble que para un infractor por primera vez que falla la prueba.","h2":"En Illinois, un conductor que no es infractor por primera vez y da 0.08 o más recibe una suspensión sumaria de 1 año.","p":"Correcto. Un reincidente que falla la prueba queda suspendido 1 año."},"ref":{"doc":"IL","page":null}},{"id":"il-124","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, a driver arrested for DUI after a crash that seriously injured another person refuses the chemical test. What happens?","o":["Only a warning","A 30-day suspension","Nothing, refusing is a right with no penalty","A statutory summary revocation of driving privileges"],"h1":"It is harsher than a suspension.","h2":"In Illinois, refusing the test after a crash that caused personal injury or death to another person leads to a statutory summary revocation.","p":"Right. Refusing after an injury crash means revocation."},"es":{"q":"En Illinois, un conductor arrestado por manejar bajo la influencia después de un choque que hirió gravemente a otra persona se niega a la prueba química. ¿Qué pasa?","o":["Solo una advertencia","Una suspensión de 30 días","Nada, negarse es un derecho sin pena","Una revocación sumaria del privilegio de conducir"],"h1":"Es más severo que una suspensión.","h2":"En Illinois, negarse a la prueba después de un choque que causó heridas o la muerte a otra persona lleva a una revocación sumaria.","p":"Correcto. Negarse después de un choque con heridos significa revocación."},"ref":{"doc":"IL","page":null}},{"id":"il-125","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a 19-year-old driver suspected of drinking refuses the chemical test for the first time. How long is the suspension?","o":["6 months","3 months","1 year","2 years"],"h1":"Refusing costs twice as long as testing over 0.00 for a first time.","h2":"In Illinois, a driver under 21 who refuses the alcohol test for the first time loses driving privileges for 6 months.","p":"Right. A first refusal under 21 means 6 months."},"es":{"q":"En Illinois, un conductor de 19 años sospechoso de haber bebido se niega por primera vez a la prueba química. ¿Cuánto dura la suspensión?","o":["6 meses","3 meses","1 año","2 años"],"h1":"Negarse cuesta el doble de tiempo que dar más de 0.00 por primera vez.","h2":"En Illinois, un conductor menor de 21 años que se niega por primera vez a la prueba de alcohol pierde el privilegio de conducir por 6 meses.","p":"Correcto. La primera negativa de un menor de 21 significa 6 meses."},"ref":{"doc":"IL","page":null}},{"id":"il-126","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a driver under 21 was suspended before under zero tolerance. Now they test above 0.00 again. How long is the new suspension?","o":["3 months","1 year","6 months","5 years"],"h1":"A second time costs four times as long as a first time.","h2":"In Illinois, a driver under 21 with a prior zero tolerance suspension who tests above 0.00 again is suspended for 1 year, or 2 years for refusing the test.","p":"Right. A second time over 0.00 means a 1-year suspension."},"es":{"q":"En Illinois, un conductor menor de 21 años ya fue suspendido antes por tolerancia cero. Ahora vuelve a dar más de 0.00. ¿Cuánto dura la nueva suspensión?","o":["3 meses","1 año","6 meses","5 años"],"h1":"Una segunda vez cuesta cuatro veces más que la primera.","h2":"En Illinois, un conductor menor de 21 años con una suspensión previa por tolerancia cero que vuelve a dar más de 0.00 queda suspendido 1 año, o 2 años si se niega a la prueba.","p":"Correcto. Una segunda vez con más de 0.00 significa 1 año de suspensión."},"ref":{"doc":"IL","page":null}},{"id":"il-127","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, how may alcohol be carried in the passenger area of a car on the road?","o":["In any closed cup","Open, if only passengers drink it","Only in its original container with the seal unbroken","Open, if the driver is over 21"],"h1":"If the seal has been broken, it does not belong in the passenger area.","h2":"In Illinois, alcohol in the passenger area of a vehicle must be in its original container with the seal unbroken, for the driver and for passengers.","p":"Right. Only sealed, original containers are allowed."},"es":{"q":"En Illinois, ¿cómo se puede llevar alcohol en el área de pasajeros de un auto en la vía?","o":["En cualquier vaso cerrado","Abierto, si solo beben los pasajeros","Solo en su envase original con el sello sin romper","Abierto, si el conductor tiene más de 21 años"],"h1":"Si el sello está roto, no debe estar en el área de pasajeros.","h2":"En Illinois, el alcohol en el área de pasajeros debe estar en su envase original con el sello sin romper, tanto para el conductor como para los pasajeros.","p":"Correcto. Solo se permiten envases originales sellados."},"ref":{"doc":"IL","page":null}},{"id":"il-128","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, in which vehicle may passengers have open alcohol, while the driver may not?","o":["A family car on a long trip","A pickup truck, in the cab","Any car parked on the shoulder","A limousine being used as a limousine"],"h1":"Think of a hired car with a partition between driver and passengers.","h2":"In Illinois, the open container law does not apply to passengers in a limousine, chartered bus or motor home, but the driver may never drink or have alcohol in the driver's area.","p":"Right. Limousine passengers are an exception, but never the driver."},"es":{"q":"En Illinois, ¿en qué vehículo pueden los pasajeros tener alcohol abierto, pero el conductor no?","o":["Un auto familiar en un viaje largo","Una camioneta pickup, en la cabina","Cualquier auto estacionado en el acotamiento","Una limusina usada como limusina"],"h1":"Piensa en un auto contratado con una separación entre conductor y pasajeros.","h2":"En Illinois, la ley de envases abiertos no se aplica a los pasajeros de una limusina, un autobús alquilado o una casa rodante, pero el conductor nunca puede beber ni tener alcohol en su área.","p":"Correcto. Los pasajeros de limusina son una excepción, pero nunca el conductor."},"ref":{"doc":"IL","page":null}},{"id":"il-129","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a driver speeds over a railroad crossing on purpose to make the car leave the ground. What is this?","o":["Reckless driving","A legal stunt if no one is near","Only a parking violation","Careless but not illegal"],"h1":"Illinois law names this exact act.","h2":"In Illinois, using an incline such as a hill, bridge approach or railroad crossing on purpose to make a vehicle airborne is reckless driving.","p":"Right. Making a car airborne on purpose is reckless driving."},"es":{"q":"En Illinois, un conductor acelera sobre un cruce de tren a propósito para que el auto se despegue del suelo. ¿Qué es esto?","o":["Manejo imprudente","Una acrobacia legal si no hay nadie cerca","Solo una falta de estacionamiento","Descuidado pero no ilegal"],"h1":"La ley de Illinois menciona este acto en particular.","h2":"En Illinois, usar a propósito una pendiente, como una colina, la entrada a un puente o un cruce de tren, para que el vehículo se despegue del suelo es manejo imprudente.","p":"Correcto. Hacer volar un auto a propósito es manejo imprudente."},"ref":{"doc":"IL","page":null}},{"id":"il-130","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a reckless driver causes bodily harm to a school crossing guard who is on duty. What is the offense?","o":["A petty offense","A felony","A warning","A misdemeanor with no jail possible"],"h1":"Hurting a child or a crossing guard makes the offense much more serious.","h2":"In Illinois, reckless driving that causes bodily harm to a child or to a school crossing guard on duty is a Class 4 felony.","p":"Right. It becomes a felony."},"es":{"q":"En Illinois, un conductor imprudente lastima a un guardia de cruce escolar que está trabajando. ¿Qué delito es?","o":["Una falta menor","Un delito grave","Una advertencia","Un delito menor sin cárcel posible"],"h1":"Lastimar a un niño o a un guardia de cruce hace la falta mucho más grave.","h2":"En Illinois, el manejo imprudente que lastima a un niño o a un guardia de cruce escolar que está trabajando es un delito grave de clase 4.","p":"Correcto. Se convierte en un delito grave."},"ref":{"doc":"IL","page":null}},{"id":"il-131","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, a driver goes 26 mph over the speed limit. What kind of offense is this?","o":["A petty offense with a small fine","Legal on interstates","A criminal misdemeanor, not just a ticket","A warning for a first time"],"h1":"Very high speeding is treated as a crime.","h2":"In Illinois, driving 26 to 34 mph over the limit is a Class B misdemeanor, and 35 mph or more over is a Class A misdemeanor.","p":"Right. Speeding 26 mph or more over the limit is a crime."},"es":{"q":"En Illinois, un conductor va 26 mph por encima del límite de velocidad. ¿Qué tipo de falta es?","o":["Una falta menor con multa pequeña","Es legal en autopistas interestatales","Un delito menor penal, no solo una multa","Una advertencia la primera vez"],"h1":"El exceso de velocidad muy alto se trata como un delito.","h2":"En Illinois, conducir de 26 a 34 mph por encima del límite es un delito menor de clase B, y 35 mph o más por encima es un delito menor de clase A.","p":"Correcto. Ir 26 mph o más por encima del límite es un delito."},"ref":{"doc":"IL","page":null}},{"id":"il-132","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, during which hours of a school day does the school zone speed limit apply when children are present?","o":["8 a.m. to 3 p.m.","7 a.m. to 7 p.m.","All day and all night","6:30 a.m. to 4 p.m."],"h1":"It starts before 7 in the morning and ends in the afternoon.","h2":"In Illinois, for the school zone speed limit, the law says a school day runs from 6:30 a.m. to 4 p.m.","p":"Right. The school day for speed limits is 6:30 a.m. to 4 p.m."},"es":{"q":"En Illinois, ¿en qué horario de un día escolar se aplica el límite de velocidad de zona escolar cuando hay niños?","o":["De 8 a.m. a 3 p.m.","De 7 a.m. a 7 p.m.","Todo el día y toda la noche","De 6:30 a.m. a 4 p.m."],"h1":"Empieza antes de las 7 de la mañana y termina en la tarde.","h2":"En Illinois, para el límite de velocidad de zona escolar, la ley dice que el día escolar va de 6:30 a.m. a 4 p.m.","p":"Correcto. El día escolar para los límites de velocidad va de 6:30 a.m. a 4 p.m."},"ref":{"doc":"IL","page":null}},{"id":"il-133","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, what is the minimum fine for a first violation of the school zone speed limit?","o":["$150","$25","$75","$1,000"],"h1":"It is half of the minimum for a second violation, which is $300.","h2":"In Illinois, the minimum fine for a first school zone speeding violation is $150, and $300 for a second.","p":"Right. The first minimum fine is $150."},"es":{"q":"En Illinois, ¿cuál es la multa mínima por una primera violación del límite de velocidad en zona escolar?","o":["$150","$25","$75","$1,000"],"h1":"Es la mitad del mínimo de una segunda violación, que es $300.","h2":"En Illinois, la multa mínima por una primera violación de velocidad en zona escolar es $150, y $300 por la segunda.","p":"Correcto. La primera multa mínima es $150."},"ref":{"doc":"IL","page":null}},{"id":"il-134","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, you are in a school speed zone in an unincorporated (rural, non-city) area. May you pass another vehicle?","o":["Yes, if you stay under 20 mph","No, it is also a no-passing zone","Yes, on the right side","Yes, outside school hours only"],"h1":"Outside cities, these zones carry an extra rule.","h2":"In Illinois, school speed zones in unincorporated areas are also no-passing zones.","p":"Right. Those school zones are no-passing zones."},"es":{"q":"En Illinois, estás en una zona escolar de velocidad en un área no incorporada (rural, fuera de la ciudad). ¿Puedes rebasar a otro vehículo?","o":["Sí, si vas a menos de 20 mph","No, también es zona de no rebasar","Sí, por la derecha","Sí, solo fuera del horario escolar"],"h1":"Fuera de las ciudades, estas zonas tienen una regla extra.","h2":"En Illinois, las zonas escolares de velocidad en áreas no incorporadas también son zonas de no rebasar.","p":"Correcto. Esas zonas escolares son zonas de no rebasar."},"ref":{"doc":"IL","page":null}},{"id":"il-135","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, what is the minimum fine for a first speeding violation in a construction or maintenance zone?","o":["$50","$100","$250","$5,000"],"h1":"A second violation has a minimum of $750.","h2":"In Illinois, speeding in a construction or maintenance zone has a minimum fine of $250 for a first violation and $750 for a second.","p":"Right. The first minimum fine is $250."},"es":{"q":"En Illinois, ¿cuál es la multa mínima por una primera violación de velocidad en una zona de construcción o mantenimiento?","o":["$50","$100","$250","$5,000"],"h1":"Una segunda violación tiene un mínimo de $750.","h2":"En Illinois, el exceso de velocidad en una zona de construcción o mantenimiento tiene una multa mínima de $250 la primera vez y $750 la segunda.","p":"Correcto. La primera multa mínima es $250."},"ref":{"doc":"IL","page":null}},{"id":"il-136","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, a driver is caught speeding in a work zone with workers present for the second time in 2 years. What else happens?","o":["Nothing beyond the fine","A 1-year revocation","A 7-day suspension","A 90-day license suspension"],"h1":"It is about three months.","h2":"In Illinois, a second work zone speeding violation within 2 years, both while workers were present, leads to a 90-day license suspension.","p":"Right. The license is suspended for 90 days."},"es":{"q":"En Illinois, un conductor es sorprendido por segunda vez en 2 años con exceso de velocidad en una zona de obras con trabajadores presentes. ¿Qué más pasa?","o":["Nada además de la multa","Una revocación de 1 año","Una suspensión de 7 días","Una suspensión de la licencia de 90 días"],"h1":"Son unos tres meses.","h2":"En Illinois, una segunda violación de velocidad en zona de obras en 2 años, ambas con trabajadores presentes, lleva a una suspensión de la licencia de 90 días.","p":"Correcto. La licencia se suspende por 90 días."},"ref":{"doc":"IL","page":null}},{"id":"il-137","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, on a posted park zone street, what is the speed limit when children are within 50 feet of traffic?","o":["20 mph or lower if posted","15 mph","25 mph","30 mph"],"h1":"It is the same number as the school zone limit.","h2":"In Illinois, on a posted park zone street, the speed limit is 20 mph, or lower if posted, on any day children are present within 50 feet of traffic.","p":"Right. Park zones are 20 mph when children are near."},"es":{"q":"En Illinois, en una calle señalizada como zona de parque, ¿cuál es el límite de velocidad cuando hay niños a menos de 50 pies del tráfico?","o":["20 mph, o menos si está señalizado","15 mph","25 mph","30 mph"],"h1":"Es el mismo número que el límite de zona escolar.","h2":"En Illinois, en una calle señalizada como zona de parque, el límite es 20 mph, o menos si está señalizado, cualquier día que haya niños a menos de 50 pies del tráfico.","p":"Correcto. Las zonas de parque son de 20 mph cuando hay niños cerca."},"ref":{"doc":"IL","page":null}},{"id":"il-138","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, you are on an interstate in the left lane, not passing. When is this still allowed?","o":["Whenever you drive the speed limit","When no other vehicle is directly behind you","Always, any lane may be used","Only at night"],"h1":"The rule is meant to keep the left lane open for those who want to pass.","h2":"In Illinois, the left lane on an interstate is for passing, but you may stay there when no other vehicle is directly behind you, or in a few other cases like heavy traffic or bad weather.","p":"Right. It is allowed when no one is directly behind you."},"es":{"q":"En Illinois, vas por el carril izquierdo de una autopista interestatal sin estar rebasando. ¿Cuándo está permitido de todos modos?","o":["Siempre que vayas al límite de velocidad","Cuando no hay otro vehículo justo detrás de ti","Siempre, se puede usar cualquier carril","Solo de noche"],"h1":"La regla busca dejar el carril izquierdo libre para quien quiere rebasar.","h2":"En Illinois, el carril izquierdo de una interestatal es para rebasar, pero puedes seguir en él cuando no hay otro vehículo justo detrás de ti, o en algunos otros casos como tráfico denso o mal tiempo.","p":"Correcto. Se permite cuando nadie va justo detrás de ti."},"ref":{"doc":"IL","page":null}},{"id":"il-139","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, on a road with three lanes and two-way traffic, when may you drive in the center lane?","o":["Any time you want to go faster","Only when towing a trailer","To pass when it is clear, or to get ready for a left turn","Never, it is for emergency vehicles only"],"h1":"Drivers from both directions may need this lane.","h2":"In Illinois, on a three-lane road with two-way traffic, you may use the center lane only to pass when it is clear or to prepare for a left turn, unless signs assign it to your direction.","p":"Right. Use the center lane only to pass or to turn left."},"es":{"q":"En Illinois, en una vía de tres carriles con tráfico en dos sentidos, ¿cuándo puedes conducir por el carril central?","o":["Cada vez que quieras ir más rápido","Solo cuando remolcas un tráiler","Para rebasar cuando está libre, o para prepararte a girar a la izquierda","Nunca, es solo para vehículos de emergencia"],"h1":"Los conductores de ambos sentidos pueden necesitar este carril.","h2":"En Illinois, en una vía de tres carriles con tráfico en dos sentidos, solo puedes usar el carril central para rebasar cuando está libre o para prepararte a girar a la izquierda, salvo que las señales lo asignen a tu sentido.","p":"Correcto. Usa el carril central solo para rebasar o girar a la izquierda."},"ref":{"doc":"IL","page":null}},{"id":"il-140","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, when may a regular car drive on the shoulder of the road?","o":["To pass slow traffic on the right","Whenever traffic is backed up","To reach an exit faster","Only to stop, or to speed up from a stop while merging"],"h1":"The shoulder is not an extra travel lane.","h2":"In Illinois, you may drive on the shoulder only to stop or to speed up from a stop while merging, and you may not pass other vehicles while on it.","p":"Right. The shoulder is only for stopping or merging from a stop."},"es":{"q":"En Illinois, ¿cuándo puede un auto común conducir por el acotamiento?","o":["Para rebasar por la derecha al tráfico lento","Siempre que haya mucho tráfico","Para llegar más rápido a una salida","Solo para detenerse, o para acelerar desde una parada al incorporarse"],"h1":"El acotamiento no es un carril extra.","h2":"En Illinois, solo puedes conducir por el acotamiento para detenerte o para acelerar desde una parada al incorporarte, y no puedes rebasar a otros vehículos mientras estás en él.","p":"Correcto. El acotamiento es solo para detenerse o incorporarse desde una parada."},"ref":{"doc":"IL","page":null}},{"id":"il-141","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, on a two-lane road, how close to an intersection or railroad crossing may you drive left of the center line to pass?","o":["Not within 100 feet","Not within 25 feet","Not within 500 feet","Any distance, if you can see"],"h1":"It is about the length of six or seven cars.","h2":"In Illinois, on a two-lane road you may not drive left of center within 100 feet of an intersection or railroad crossing.","p":"Right. Stay right within 100 feet of them."},"es":{"q":"En Illinois, en una vía de dos carriles, ¿qué tan cerca de una intersección o un cruce de tren puedes ir a la izquierda de la línea central para rebasar?","o":["No dentro de 100 pies","No dentro de 25 pies","No dentro de 500 pies","A cualquier distancia, si puedes ver"],"h1":"Es más o menos el largo de seis o siete autos.","h2":"En Illinois, en una vía de dos carriles no puedes ir a la izquierda del centro dentro de 100 pies de una intersección o un cruce de tren.","p":"Correcto. Mantente a la derecha dentro de 100 pies de ellos."},"ref":{"doc":"IL","page":null}},{"id":"il-142","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, your view is blocked as you come near a bridge or tunnel on a two-lane road. When may you not pass on the left?","o":["Within 10 feet of it","Within 100 feet of the bridge or tunnel","Only inside the tunnel","Never, passing is always allowed"],"h1":"It is the same distance as for intersections.","h2":"In Illinois, you may not drive left of center within 100 feet of a bridge, viaduct or tunnel when your view is blocked.","p":"Right. Not within 100 feet when your view is blocked."},"es":{"q":"En Illinois, tu vista está bloqueada al acercarte a un puente o túnel en una vía de dos carriles. ¿Cuándo no puedes rebasar por la izquierda?","o":["Dentro de 10 pies","Dentro de 100 pies del puente o túnel","Solo dentro del túnel","Nunca, rebasar siempre está permitido"],"h1":"Es la misma distancia que para las intersecciones.","h2":"En Illinois, no puedes ir a la izquierda del centro dentro de 100 pies de un puente, viaducto o túnel cuando tu vista está bloqueada.","p":"Correcto. No dentro de 100 pies cuando tu vista está bloqueada."},"ref":{"doc":"IL","page":null}},{"id":"il-143","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, you are behind a slow bicycle in a no-passing zone. When may you pass it?","o":["Never in a no-passing zone","Any time you honk first","When the bike goes under half the speed limit and you can pass safely without speeding","Only if the rider waves you on"],"h1":"Illinois has a special exception for slow bicycles.","h2":"In Illinois, you may pass a bicycle in a no-passing zone if it is going less than half the speed limit, you can pass without going over the limit, and there is enough clear room to the left.","p":"Right. Slow bicycles may be passed there when it is safe and legal."},"es":{"q":"En Illinois, vas detrás de una bicicleta lenta en una zona de no rebasar. ¿Cuándo puedes rebasarla?","o":["Nunca en una zona de no rebasar","Cada vez que toques el claxon primero","Cuando la bicicleta va a menos de la mitad del límite y puedes rebasar con seguridad sin exceder la velocidad","Solo si el ciclista te hace señas"],"h1":"Illinois tiene una excepción especial para bicicletas lentas.","h2":"En Illinois, puedes rebasar una bicicleta en una zona de no rebasar si va a menos de la mitad del límite de velocidad, puedes rebasar sin pasar el límite y hay suficiente espacio libre a la izquierda.","p":"Correcto. Allí se puede rebasar a bicicletas lentas cuando es seguro y legal."},"ref":{"doc":"IL","page":null}},{"id":"il-144","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, you are on a road with two lanes going your way and a bicycle is in the right lane ahead. How should you pass it?","o":["Stay in the lane and squeeze by","Honk until the rider moves over","Pass on the rider's right","Move into the other lane if it is safe"],"h1":"Use the extra lane when you have one.","h2":"In Illinois, when another lane going your way is available, you should change lanes before passing a bicycle, if it is safe, and keep at least 3 feet of space.","p":"Right. Change lanes to pass the bicycle when you can."},"es":{"q":"En Illinois, vas por una vía con dos carriles en tu sentido y hay una bicicleta en el carril derecho delante de ti. ¿Cómo debes rebasarla?","o":["Quedarte en el carril y pasar muy cerca","Tocar el claxon hasta que se aparte","Rebasar por la derecha del ciclista","Cambiarte al otro carril si es seguro"],"h1":"Usa el carril extra cuando lo tienes.","h2":"En Illinois, cuando hay otro carril disponible en tu sentido, debes cambiarte de carril antes de rebasar una bicicleta, si es seguro, y dejar al menos 3 pies de espacio.","p":"Correcto. Cámbiate de carril para rebasar la bicicleta cuando puedas."},"ref":{"doc":"IL","page":null}},{"id":"il-145","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, on a curve or near the top of a hill, you may not make a U-turn if other drivers cannot see you within how many feet?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is the same distance as dimming your lights for oncoming cars.","h2":"In Illinois, you may not make a U-turn on a curve or near a hilltop where drivers coming from either direction cannot see you within 500 feet.","p":"Right. You must be visible for 500 feet."},"es":{"q":"En Illinois, en una curva o cerca de la cima de una colina, no puedes dar una vuelta en U si otros conductores no te ven a cuántos pies?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es la misma distancia para bajar las luces ante autos que vienen de frente.","h2":"En Illinois, no puedes dar una vuelta en U en una curva o cerca de la cima de una colina si los conductores de cualquier sentido no pueden verte a 500 pies.","p":"Correcto. Deben poder verte a 500 pies."},"ref":{"doc":"IL","page":null}},{"id":"il-146","scope":"IL","cat":"signals","sign":null,"c":1,"en":{"q":"In Illinois, in a city business or residential area, how far before a turn must you signal?","o":["At least 25 feet","At least 100 feet","At least 300 feet","Only when you start turning"],"h1":"It is half the distance used on rural roads.","h2":"In Illinois, in a business or residence district you must signal for at least the last 100 feet before you turn or change lanes.","p":"Right. Signal at least 100 feet ahead in town."},"es":{"q":"En Illinois, en una zona comercial o residencial de la ciudad, ¿con cuánta anticipación debes señalizar antes de girar?","o":["Al menos 25 pies","Al menos 100 pies","Al menos 300 pies","Solo cuando empiezas a girar"],"h1":"Es la mitad de la distancia que se usa en caminos rurales.","h2":"En Illinois, en una zona comercial o residencial debes señalizar durante al menos los últimos 100 pies antes de girar o cambiar de carril.","p":"Correcto. Señaliza al menos 100 pies antes en la ciudad."},"ref":{"doc":"IL","page":null}},{"id":"il-147","scope":"IL","cat":"signals","sign":null,"c":2,"en":{"q":"In Illinois, may you flash your left turn signal to tell the driver behind you it is safe to pass?","o":["Yes, it is the polite thing to do","Yes, but only on two-lane roads","No, turn signals may not be used as a courtesy signal","Yes, but only at night"],"h1":"A turn signal should mean only that you are turning or moving over.","h2":"In Illinois, you may not flash a turn signal as a courtesy \"go ahead and pass\" signal to drivers behind you.","p":"Right. Turn signals are not courtesy signals."},"es":{"q":"En Illinois, ¿puedes encender la direccional izquierda para avisar al conductor de atrás que puede rebasar?","o":["Sí, es lo amable","Sí, pero solo en vías de dos carriles","No, las direccionales no se usan como señal de cortesía","Sí, pero solo de noche"],"h1":"La direccional solo debe indicar que vas a girar o moverte.","h2":"En Illinois, no puedes usar la direccional como señal de cortesía para decirle al conductor de atrás que rebase.","p":"Correcto. Las direccionales no son señales de cortesía."},"ref":{"doc":"IL","page":null}},{"id":"il-148","scope":"IL","cat":"signals","sign":null,"c":3,"en":{"q":"In Illinois, you are on a one-way street at a red light and want to turn left onto another one-way street. What may you do?","o":["Never turn left on red","Turn without stopping","Wait for a police officer to wave you on","Stop fully, yield, then turn left unless a sign forbids it"],"h1":"It works like a right turn on red.","h2":"In Illinois, after a full stop and yielding, you may turn left on red from a one-way street onto another one-way street, unless a sign forbids it.","p":"Right. Left on red from one-way to one-way is allowed after a stop."},"es":{"q":"En Illinois, estás en una calle de un solo sentido con luz roja y quieres girar a la izquierda hacia otra calle de un solo sentido. ¿Qué puedes hacer?","o":["Nunca girar a la izquierda en rojo","Girar sin parar","Esperar a que un policía te dé paso","Parar por completo, ceder el paso y girar a la izquierda, salvo que una señal lo prohíba"],"h1":"Funciona como el giro a la derecha en rojo.","h2":"En Illinois, después de parar por completo y ceder el paso, puedes girar a la izquierda en rojo de una calle de un solo sentido a otra de un solo sentido, salvo que una señal lo prohíba.","p":"Correcto. Se permite girar a la izquierda en rojo de un solo sentido a un solo sentido tras parar."},"ref":{"doc":"IL","page":null}},{"id":"il-149","scope":"IL","cat":"signals","sign":null,"c":0,"en":{"q":"In Illinois, a motorcyclist is stopped at a red light that does not change, maybe because it cannot detect the bike. After how long may the rider carefully go through?","o":["At least 120 seconds","30 seconds","60 seconds","Never, the rider must wait"],"h1":"It is two minutes.","h2":"In Illinois, a motorcycle or bicycle rider may carefully proceed through a red light that has not changed for at least 120 seconds, after stopping and yielding to traffic.","p":"Right. After at least 120 seconds the rider may proceed with care."},"es":{"q":"En Illinois, un motociclista está detenido en una luz roja que no cambia, quizá porque no detecta la moto. ¿Después de cuánto tiempo puede pasar con cuidado?","o":["Al menos 120 segundos","30 segundos","60 segundos","Nunca, debe esperar"],"h1":"Son dos minutos.","h2":"En Illinois, un motociclista o ciclista puede pasar con cuidado una luz roja que no ha cambiado en al menos 120 segundos, después de parar y ceder el paso.","p":"Correcto. Después de al menos 120 segundos puede pasar con cuidado."},"ref":{"doc":"IL","page":null}},{"id":"il-150","scope":"IL","cat":"signals","sign":null,"c":1,"en":{"q":"In Illinois, you come to a traffic signal that is completely dark because of a power outage. What must you do?","o":["Drive through without slowing","Stop as you would at a stop sign","Slow down but do not stop","Honk and keep going"],"h1":"Treat it like a common sign at an intersection.","h2":"In Illinois, when no signal light facing you is lit, you must stop before the intersection as you would at a stop sign.","p":"Right. A dark signal means stop as at a stop sign."},"es":{"q":"En Illinois, llegas a un semáforo completamente apagado por un corte de luz. ¿Qué debes hacer?","o":["Pasar sin frenar","Parar como en una señal de alto","Bajar la velocidad sin parar","Tocar el claxon y seguir"],"h1":"Trátalo como una señal común de intersección.","h2":"En Illinois, cuando ninguna luz del semáforo que te toca está encendida, debes parar antes de la intersección como en una señal de alto.","p":"Correcto. Un semáforo apagado significa parar como en un alto."},"ref":{"doc":"IL","page":null}},{"id":"il-151","scope":"IL","cat":"signals","sign":null,"c":2,"en":{"q":"In Illinois, a driver cuts through a gas station lot to avoid a red light at the corner. Is this legal?","o":["Yes, if the driver does not stop to buy gas","Yes, private lots are not covered by traffic laws","No, it is illegal to cut across private property to avoid a traffic control","Yes, but only to turn right"],"h1":"Traffic laws cover this shortcut.","h2":"In Illinois, it is against the law to leave the road and drive across private property to avoid a traffic signal or sign.","p":"Right. Cutting through a lot to avoid a light is illegal."},"es":{"q":"En Illinois, un conductor atraviesa el terreno de una gasolinera para evitar una luz roja en la esquina. ¿Es legal?","o":["Sí, si no se detiene a comprar gasolina","Sí, los terrenos privados no están cubiertos por las leyes de tránsito","No, es ilegal cruzar una propiedad privada para evitar un control de tránsito","Sí, pero solo para girar a la derecha"],"h1":"Las leyes de tránsito cubren este atajo.","h2":"En Illinois, es ilegal salir de la vía y cruzar una propiedad privada para evitar un semáforo o una señal.","p":"Correcto. Cruzar un terreno para evitar una luz es ilegal."},"ref":{"doc":"IL","page":null}},{"id":"il-152","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, when you must stop at a railroad crossing, where should you stop?","o":["Right next to the first rail","At least 100 feet away","Between 5 and 10 feet from the rail","Between 15 and 50 feet from the nearest rail"],"h1":"Not too close, not too far.","h2":"In Illinois, when you must stop at a railroad crossing, you stop within 50 feet but not closer than 15 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the rail."},"es":{"q":"En Illinois, cuando debes parar en un cruce de tren, ¿dónde debes detenerte?","o":["Justo al lado del primer riel","Al menos a 100 pies","Entre 5 y 10 pies del riel","Entre 15 y 50 pies del riel más cercano"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Illinois, cuando debes parar en un cruce de tren, te detienes a no más de 50 pies y no menos de 15 pies del riel más cercano.","p":"Correcto. Para entre 15 y 50 pies del riel."},"ref":{"doc":"IL","page":null}},{"id":"il-153","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, what is the fine for a first violation of the railroad crossing rules, such as going around a lowered gate?","o":["$500","$50","$150","$5,000"],"h1":"A second violation doubles it to $1,000.","h2":"In Illinois, a first railroad crossing violation brings a $500 fine, and a second brings a $1,000 fine.","p":"Right. The first fine is $500."},"es":{"q":"En Illinois, ¿cuál es la multa por una primera violación de las reglas de cruce de tren, como rodear una barrera baja?","o":["$500","$50","$150","$5,000"],"h1":"Una segunda violación la duplica a $1,000.","h2":"En Illinois, una primera violación en un cruce de tren trae una multa de $500, y una segunda, una multa de $1,000.","p":"Correcto. La primera multa es $500."},"ref":{"doc":"IL","page":null}},{"id":"il-154","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, what must a school bus driver do at every railroad crossing?","o":["Slow down only if lights are flashing","Stop, turn off fans and radio, and open the door and window to listen","Sound the horn and keep going","Change gears while crossing"],"h1":"The driver needs to hear a train coming.","h2":"In Illinois, a school bus must stop at every railroad crossing, and the driver must turn off noisy items like fans and the radio and open the service door and the driver's window.","p":"Right. The bus stops, gets quiet and opens up to listen."},"es":{"q":"En Illinois, ¿qué debe hacer el conductor de un autobús escolar en cada cruce de tren?","o":["Bajar la velocidad solo si hay luces encendidas","Parar, apagar ventiladores y radio, y abrir la puerta y la ventana para escuchar","Tocar la bocina y seguir","Cambiar de marcha al cruzar"],"h1":"El conductor necesita oír si viene un tren.","h2":"En Illinois, un autobús escolar debe parar en cada cruce de tren, y el conductor debe apagar aparatos ruidosos como ventiladores y radio y abrir la puerta de servicio y su ventana.","p":"Correcto. El autobús para, hace silencio y abre para escuchar."},"ref":{"doc":"IL","page":null}},{"id":"il-155","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a truck with hazardous material placards comes to a railroad crossing with no train in sight. What must it do?","o":["Cross at normal speed","Speed up to cross quickly","Stop, look and listen, then cross without shifting gears","Stop only if the gates are down"],"h1":"Trucks with dangerous cargo always stop at the tracks.","h2":"In Illinois, a vehicle placarded for hazardous materials must stop at every railroad crossing, look and listen, and then cross without shifting gears.","p":"Right. It must stop and cross without changing gears."},"es":{"q":"En Illinois, un camión con placas de materiales peligrosos llega a un cruce de tren sin ningún tren a la vista. ¿Qué debe hacer?","o":["Cruzar a velocidad normal","Acelerar para cruzar rápido","Parar, mirar y escuchar, y luego cruzar sin cambiar de marcha","Parar solo si las barreras están bajas"],"h1":"Los camiones con carga peligrosa siempre paran en las vías.","h2":"En Illinois, un vehículo con placas de materiales peligrosos debe parar en cada cruce de tren, mirar y escuchar, y luego cruzar sin cambiar de marcha.","p":"Correcto. Debe parar y cruzar sin cambiar de marcha."},"ref":{"doc":"IL","page":null}},{"id":"il-156","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 10 feet","No closer than 100 feet","No closer than 50 feet"],"h1":"It is the same as the farthest stopping point at a crossing.","h2":"In Illinois, you may not park within 50 feet of the nearest rail of a railroad crossing, except briefly while loading or unloading.","p":"Right. Park at least 50 feet from the rail."},"es":{"q":"En Illinois, ¿qué tan cerca del riel más cercano de un cruce de tren puedes estacionarte?","o":["A no menos de 15 pies","A no menos de 10 pies","A no menos de 100 pies","A no menos de 50 pies"],"h1":"Es igual a la distancia más lejana para parar en un cruce.","h2":"En Illinois, no puedes estacionarte a menos de 50 pies del riel más cercano de un cruce de tren, salvo un momento para cargar o descargar.","p":"Correcto. Estaciónate al menos a 50 pies del riel."},"ref":{"doc":"IL","page":null}},{"id":"il-157","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, what is the penalty for stopping or parking on railroad tracks?","o":["A $500 fine or 50 hours of community service","A $20 parking ticket","A warning only","Nothing if no train comes"],"h1":"The law sets a fixed, heavy penalty.","h2":"In Illinois, stopping, standing or parking on railroad tracks brings a mandatory $500 fine or 50 hours of community service.","p":"Right. It is a $500 fine or 50 hours of service."},"es":{"q":"En Illinois, ¿cuál es la pena por detenerse o estacionarse sobre las vías del tren?","o":["Una multa de $500 o 50 horas de servicio comunitario","Una multa de estacionamiento de $20","Solo una advertencia","Nada si no pasa un tren"],"h1":"La ley fija una pena alta.","h2":"En Illinois, detenerse o estacionarse sobre las vías del tren trae una multa obligatoria de $500 o 50 horas de servicio comunitario.","p":"Correcto. Es una multa de $500 o 50 horas de servicio."},"ref":{"doc":"IL","page":null}},{"id":"il-158","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 50 feet","Right up to the crosswalk line"],"h1":"It is more than the fire hydrant distance.","h2":"In Illinois, you may not stand or park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Illinois, ¿qué tan cerca de un cruce peatonal en una intersección puedes estacionarte?","o":["A no menos de 5 pies","A no menos de 20 pies","A no menos de 50 pies","Justo hasta la línea del cruce"],"h1":"Es más que la distancia de un hidrante.","h2":"En Illinois, no puedes detenerte ni estacionarte a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédate al menos a 20 pies del cruce peatonal."},"ref":{"doc":"IL","page":null}},{"id":"il-159","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, on the same side of the street, how close to a fire station driveway may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 200 feet"],"h1":"On the other side of the street the distance is 75 feet where posted.","h2":"In Illinois, you may not park within 20 feet of a fire station driveway, or within 75 feet of it on the opposite side of the street when signs are posted.","p":"Right. Keep 20 feet from the fire station driveway."},"es":{"q":"En Illinois, en el mismo lado de la calle, ¿qué tan cerca de la entrada de una estación de bomberos puedes estacionarte?","o":["A no menos de 5 pies","A no menos de 10 pies","A no menos de 20 pies","A no menos de 200 pies"],"h1":"En el otro lado de la calle la distancia es 75 pies donde haya señales.","h2":"En Illinois, no puedes estacionarte a menos de 20 pies de la entrada de una estación de bomberos, ni a menos de 75 pies en el lado opuesto de la calle cuando hay señales.","p":"Correcto. Mantén 20 pies de la entrada de la estación de bomberos."},"ref":{"doc":"IL","page":null}},{"id":"il-160","scope":"IL","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Illinois, when you parallel park on a two-way street, how close to the curb must your right wheels be?","o":["Within 24 inches","Within 3 feet","Touching the curb","Within 12 inches"],"h1":"It is one foot.","h2":"In Illinois, when you park on a two-way street, your right wheels must be parallel to and within 12 inches of the curb.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En Illinois, cuando te estacionas en paralelo en una calle de dos sentidos, ¿qué tan cerca de la acera deben quedar tus ruedas derechas?","o":["A no más de 24 pulgadas","A no más de 3 pies","Tocando la acera","A no más de 12 pulgadas"],"h1":"Es un pie.","h2":"En Illinois, cuando te estacionas en una calle de dos sentidos, tus ruedas derechas deben quedar paralelas y a no más de 12 pulgadas de la acera.","p":"Correcto. Estaciónate a no más de 12 pulgadas de la acera."},"ref":{"doc":"IL","page":null}},{"id":"il-161","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, you must stop on a rural highway because you cannot get off the road. From how far must your vehicle be clearly visible in each direction?","o":["200 feet","50 feet","100 feet","1,000 feet"],"h1":"Do not stop just over a hill or around a curve.","h2":"In Illinois, outside a business or residence district, a vehicle stopped on the road must leave room for traffic to pass and be clearly visible from 200 feet in each direction.","p":"Right. It must be visible from 200 feet each way."},"es":{"q":"En Illinois, debes detenerte en una carretera rural porque no puedes salir de la vía. ¿Desde qué distancia debe verse claramente tu vehículo en cada dirección?","o":["200 pies","50 pies","100 pies","1,000 pies"],"h1":"No te detengas justo pasando una colina o una curva.","h2":"En Illinois, fuera de zonas comerciales o residenciales, un vehículo detenido en la vía debe dejar espacio para que pase el tráfico y verse claramente desde 200 pies en cada dirección.","p":"Correcto. Debe verse desde 200 pies en cada dirección."},"ref":{"doc":"IL","page":null}},{"id":"il-162","scope":"IL","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Illinois, what is the state fine for parking in a disability parking space without a disability plate or placard?","o":["$25","$250","$50","$100"],"h1":"Cities may set it as high as $350.","h2":"In Illinois, parking in a space reserved for persons with disabilities without the proper plate or placard brings a $250 fine, and cities may set it up to $350.","p":"Right. The fine is $250."},"es":{"q":"En Illinois, ¿cuál es la multa estatal por estacionarse en un espacio para personas con discapacidad sin placa ni permiso de discapacidad?","o":["$25","$250","$50","$100"],"h1":"Las ciudades pueden subirla hasta $350.","h2":"En Illinois, estacionarse en un espacio reservado para personas con discapacidad sin la placa o el permiso correcto trae una multa de $250, y las ciudades pueden fijarla hasta $350.","p":"Correcto. La multa es $250."},"ref":{"doc":"IL","page":null}},{"id":"il-163","scope":"IL","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Illinois, you use your grandmother's disability placard to park, but she is not with you. What is the fine for a first violation?","o":["$50","$150","$600","No fine, it is a family placard"],"h1":"The placard only works when its holder gets in or out of the car.","h2":"In Illinois, using someone else's disability placard when that person is not with you brings a $600 fine for a first violation and $1,000 for a second.","p":"Right. The first fine is $600."},"es":{"q":"En Illinois, usas el permiso de discapacidad de tu abuela para estacionarte, pero ella no va contigo. ¿Cuál es la multa por la primera vez?","o":["$50","$150","$600","No hay multa, es un permiso familiar"],"h1":"El permiso solo sirve cuando su titular sube o baja del auto.","h2":"En Illinois, usar el permiso de discapacidad de otra persona cuando no va contigo trae una multa de $600 la primera vez y $1,000 la segunda.","p":"Correcto. La primera multa es $600."},"ref":{"doc":"IL","page":null}},{"id":"il-164","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, you start your locked car with a remote starter to warm it up and walk away. Is this an illegal unattended vehicle?","o":["Yes, any running car with no driver is illegal","Only legal on private property in summer","Only legal if the windows are open","No, a locked car started by remote does not count as unattended"],"h1":"Illinois law has a special exception for remote starters.","h2":"In Illinois, a locked car with its engine running after a remote start does not count as an unattended vehicle.","p":"Right. A locked, remote-started car is not unattended under the law."},"es":{"q":"En Illinois, enciendes tu auto cerrado con un arranque remoto para calentarlo y te alejas. ¿Es un vehículo desatendido ilegal?","o":["Sí, todo auto encendido sin conductor es ilegal","Solo es legal en propiedad privada en verano","Solo es legal si las ventanas están abiertas","No, un auto cerrado encendido a distancia no cuenta como desatendido"],"h1":"La ley de Illinois tiene una excepción especial para el arranque remoto.","h2":"En Illinois, un auto cerrado con el motor encendido por arranque remoto no cuenta como vehículo desatendido.","p":"Correcto. Un auto cerrado encendido a distancia no está desatendido según la ley."},"ref":{"doc":"IL","page":null}},{"id":"il-165","scope":"IL","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Illinois, you miss your exit on an expressway. May you back up on the shoulder to reach it?","o":["No, backing is not allowed on any part of an expressway","Yes, if you use hazard lights","Yes, if traffic is light","Yes, but only on the shoulder"],"h1":"Go on to the next exit instead.","h2":"In Illinois, you may not back up on the shoulder or roadway of a controlled-access highway.","p":"Right. Never back up on an expressway."},"es":{"q":"En Illinois, te pasas la salida en una autopista de acceso controlado. ¿Puedes ir en reversa por el acotamiento para llegar a ella?","o":["No, ir en reversa no se permite en ninguna parte de la autopista","Sí, si usas las luces intermitentes","Sí, si hay poco tráfico","Sí, pero solo por el acotamiento"],"h1":"Sigue hasta la próxima salida.","h2":"En Illinois, no puedes ir en reversa por el acotamiento ni por la vía de una autopista de acceso controlado.","p":"Correcto. Nunca vayas en reversa en una autopista."},"ref":{"doc":"IL","page":null}},{"id":"il-166","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, how long is the license suspension for a first conviction of passing a stopped school bus with its signals on?","o":["7 days","3 months","1 year","5 years"],"h1":"A second conviction within 5 years brings 1 year.","h2":"In Illinois, a first conviction for passing a stopped school bus brings a 3-month license suspension.","p":"Right. The first suspension is 3 months."},"es":{"q":"En Illinois, ¿cuánto dura la suspensión de la licencia por una primera condena por rebasar un autobús escolar detenido con sus señales encendidas?","o":["7 días","3 meses","1 año","5 años"],"h1":"Una segunda condena en 5 años trae 1 año.","h2":"En Illinois, una primera condena por rebasar un autobús escolar detenido trae una suspensión de la licencia de 3 meses.","p":"Correcto. La primera suspensión es de 3 meses."},"ref":{"doc":"IL","page":null}},{"id":"il-167","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a driver is convicted a second time within 5 years of passing a stopped school bus. What are the penalties?","o":["A 3-month suspension and a $300 fine","A warning and a $50 fine","A 1-year suspension and a $1,000 fine","Only community service"],"h1":"Both the suspension and the fine get bigger.","h2":"In Illinois, a second conviction within 5 years for passing a stopped school bus brings a 1-year suspension and a $1,000 fine.","p":"Right. One year and $1,000."},"es":{"q":"En Illinois, un conductor es condenado por segunda vez en 5 años por rebasar un autobús escolar detenido. ¿Cuáles son las penas?","o":["Una suspensión de 3 meses y una multa de $300","Una advertencia y una multa de $50","Una suspensión de 1 año y una multa de $1,000","Solo servicio comunitario"],"h1":"Tanto la suspensión como la multa aumentan.","h2":"En Illinois, una segunda condena en 5 años por rebasar un autobús escolar detenido trae una suspensión de 1 año y una multa de $1,000.","p":"Correcto. Un año y $1,000."},"ref":{"doc":"IL","page":null}},{"id":"il-168","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, a school bus in a town turns on its flashing amber (yellow) lights. What does it mean?","o":["It is about to turn left","You may pass it quickly","It is out of service","It will stop within about 100 feet to load or unload children"],"h1":"Amber lights come before the red lights and stop arm.","h2":"In Illinois, a school bus flashes its amber lights for at least the last 100 feet before it stops in an urban area, or 200 feet outside one, so get ready to stop.","p":"Right. Amber lights mean the bus is about to stop."},"es":{"q":"En Illinois, un autobús escolar en un pueblo enciende sus luces ámbar (amarillas) intermitentes. ¿Qué significa?","o":["Que va a girar a la izquierda","Que puedes rebasarlo rápido","Que está fuera de servicio","Que se detendrá en unos 100 pies para subir o bajar niños"],"h1":"Las luces ámbar vienen antes de las luces rojas y el brazo de alto.","h2":"En Illinois, un autobús escolar enciende sus luces ámbar al menos durante los últimos 100 pies antes de detenerse en zona urbana, o 200 pies fuera de ella, así que prepárate para parar.","p":"Correcto. Las luces ámbar indican que el autobús va a detenerse."},"ref":{"doc":"IL","page":null}},{"id":"il-169","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, a school bus with its stop arm out is stopped in a school parking lot. Must you stop?","o":["Yes, the rule applies in parking lots and on school property too","No, the rule applies only on public roads","Only if you are behind the bus","Only during school hours"],"h1":"The law covers any place where the bus picks up or drops off students.","h2":"In Illinois, you must stop for a school bus loading or unloading students on a highway, private road, parking lot, school property or any other place.","p":"Right. Stop for the bus wherever it is loading students."},"es":{"q":"En Illinois, un autobús escolar con el brazo de alto extendido está detenido en el estacionamiento de una escuela. ¿Debes parar?","o":["Sí, la regla también se aplica en estacionamientos y terrenos escolares","No, la regla solo se aplica en vías públicas","Solo si vas detrás del autobús","Solo en horario escolar"],"h1":"La ley cubre cualquier lugar donde el autobús sube o baja estudiantes.","h2":"En Illinois, debes parar ante un autobús escolar que sube o baja estudiantes en una carretera, camino privado, estacionamiento, terreno escolar o cualquier otro lugar.","p":"Correcto. Para ante el autobús dondequiera que suba o baje estudiantes."},"ref":{"doc":"IL","page":null}},{"id":"il-170","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, what is the fine range for a first violation of Scott's Law (not moving over or slowing for a stopped emergency vehicle)?","o":["$25 to $100","$250 to $10,000","$50 to $500","$1 million"],"h1":"The top of the range is very high.","h2":"In Illinois, a first violation of Scott's Law brings a fine of $250 to $10,000.","p":"Right. The fine is $250 to $10,000."},"es":{"q":"En Illinois, ¿cuál es el rango de multa por una primera violación de la Ley de Scott (no cambiarse de carril ni bajar la velocidad ante un vehículo de emergencia detenido)?","o":["De $25 a $100","De $250 a $10,000","De $50 a $500","$1 millón"],"h1":"El máximo del rango es muy alto.","h2":"En Illinois, una primera violación de la Ley de Scott trae una multa de $250 a $10,000.","p":"Correcto. La multa es de $250 a $10,000."},"ref":{"doc":"IL","page":null}},{"id":"il-171","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a driver violates Scott's Law and damages another vehicle. What happens to the license?","o":["Nothing beyond the fine","It is suspended for 2 days","It is suspended for 90 days to 1 year","It is revoked for life"],"h1":"Injury or death bring even longer suspensions.","h2":"In Illinois, a Scott's Law violation that damages another person's property brings a suspension of 90 days to 1 year, and longer if someone is hurt or killed.","p":"Right. Property damage means a 90-day to 1-year suspension."},"es":{"q":"En Illinois, un conductor viola la Ley de Scott y daña otro vehículo. ¿Qué pasa con la licencia?","o":["Nada además de la multa","Se suspende por 2 días","Se suspende de 90 días a 1 año","Se revoca de por vida"],"h1":"Las heridas o la muerte traen suspensiones aún más largas.","h2":"En Illinois, una violación de la Ley de Scott que daña la propiedad de otra persona trae una suspensión de 90 días a 1 año, y más larga si alguien resulta herido o muerto.","p":"Correcto. Los daños a la propiedad significan una suspensión de 90 días a 1 año."},"ref":{"doc":"IL","page":null}},{"id":"il-172","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, you enter a work zone on a four-lane highway and workers are present. What should you do?","o":["Keep your speed and lane","Honk to warn the workers","Drive on the shoulder","Move to a lane away from the workers if safe, or slow down"],"h1":"It works like the rule for stopped emergency vehicles.","h2":"In Illinois, when workers are present in a work zone, you must change to a lane not next to them if you safely can, or slow down if you cannot, and the fine can be $100 to $25,000.","p":"Right. Move away from the workers or slow down."},"es":{"q":"En Illinois, entras a una zona de obras en una carretera de cuatro carriles y hay trabajadores. ¿Qué debes hacer?","o":["Mantener tu velocidad y carril","Tocar el claxon para avisar a los trabajadores","Conducir por el acotamiento","Cambiarte a un carril lejos de los trabajadores si es seguro, o bajar la velocidad"],"h1":"Funciona como la regla para vehículos de emergencia detenidos.","h2":"En Illinois, cuando hay trabajadores en una zona de obras, debes cambiarte a un carril que no esté junto a ellos si puedes hacerlo con seguridad, o bajar la velocidad si no puedes, y la multa puede ser de $100 a $25,000.","p":"Correcto. Aléjate de los trabajadores o baja la velocidad."},"ref":{"doc":"IL","page":null}},{"id":"il-173","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, how close may you follow a fire truck that is responding to an alarm?","o":["No closer than 500 feet","No closer than 100 feet","No closer than 50 feet","Any distance, if you are careful"],"h1":"It is the same distance used for dimming headlights for oncoming cars.","h2":"In Illinois, you may not follow a fire truck answering an alarm closer than 500 feet, or stop within 500 feet of one stopped at a fire.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Illinois, ¿qué tan cerca puedes seguir a un camión de bomberos que responde a una alarma?","o":["A no menos de 500 pies","A no menos de 100 pies","A no menos de 50 pies","A cualquier distancia, si tienes cuidado"],"h1":"Es la misma distancia para bajar las luces ante autos que vienen de frente.","h2":"En Illinois, no puedes seguir a un camión de bomberos que responde a una alarma a menos de 500 pies, ni detenerte a menos de 500 pies de uno detenido en un incendio.","p":"Correcto. Quédate al menos a 500 pies."},"ref":{"doc":"IL","page":null}},{"id":"il-174","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, a fire hose is lying across the street. What should you do?","o":["Drive over it slowly","Do not drive over it unless the fire officer in charge allows it","Drive over it quickly","Honk until it is moved"],"h1":"Driving on a hose can break it while firefighters need water.","h2":"In Illinois, you may not drive over an unprotected fire hose unless the fire officer in command allows it.","p":"Right. Do not drive over a fire hose without permission."},"es":{"q":"En Illinois, hay una manguera de bomberos atravesada en la calle. ¿Qué debes hacer?","o":["Pasar por encima despacio","No pasar por encima salvo que el jefe de bomberos lo permita","Pasar por encima rápido","Tocar el claxon hasta que la quiten"],"h1":"Pasar sobre la manguera puede romperla cuando los bomberos necesitan agua.","h2":"En Illinois, no puedes pasar por encima de una manguera de bomberos sin protección salvo que el jefe de bomberos a cargo lo permita.","p":"Correcto. No pases sobre una manguera sin permiso."},"ref":{"doc":"IL","page":null}},{"id":"il-175","scope":"IL","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Illinois, a person using a white cane is crossing near you, not at a crosswalk. What must you do?","o":["Honk so they hurry","Go first, since they are outside a crosswalk","Yield to the person","Drive around them quickly"],"h1":"Illinois gives special protection to pedestrians with visible disabilities.","h2":"In Illinois, drivers must yield the right-of-way to any pedestrian with clearly visible disabilities.","p":"Right. Always yield to a pedestrian with a visible disability."},"es":{"q":"En Illinois, una persona con bastón blanco está cruzando cerca de ti, fuera de un cruce peatonal. ¿Qué debes hacer?","o":["Tocar el claxon para que se apure","Pasar primero, porque está fuera del cruce","Cederle el paso","Rodearla rápidamente"],"h1":"Illinois da protección especial a los peatones con discapacidades visibles.","h2":"En Illinois, los conductores deben ceder el paso a cualquier peatón con una discapacidad claramente visible.","p":"Correcto. Siempre cede el paso a un peatón con una discapacidad visible."},"ref":{"doc":"IL","page":null}},{"id":"il-176","scope":"IL","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Illinois, you are pulling into a driveway and a person is walking on the sidewalk. Who has the right-of-way?","o":["You, because you signaled","Whoever is faster","You, because you are in a vehicle","The person on the sidewalk"],"h1":"The sidewalk belongs to people on foot.","h2":"In Illinois, drivers must yield the right-of-way to any pedestrian on a sidewalk.","p":"Right. Yield to people on the sidewalk."},"es":{"q":"En Illinois, vas a entrar a una entrada de autos y una persona camina por la acera. ¿Quién tiene el derecho de paso?","o":["Tú, porque señalizaste","El que sea más rápido","Tú, porque vas en un vehículo","La persona en la acera"],"h1":"La acera es para las personas a pie.","h2":"En Illinois, los conductores deben ceder el paso a cualquier peatón que esté en la acera.","p":"Correcto. Cede el paso a quien va por la acera."},"ref":{"doc":"IL","page":null}},{"id":"il-177","scope":"IL","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Illinois, a person walks along a two-way road with no sidewalk and no shoulder. On which side should they walk?","o":["The left side, facing oncoming traffic","The right side, with traffic","In the middle of the lane","Either side, it does not matter"],"h1":"Walkers should be able to see the cars coming toward them.","h2":"In Illinois, where there is no sidewalk or shoulder, a pedestrian on a two-way road must walk near the left edge, facing traffic.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Illinois, una persona camina por una vía de dos sentidos sin acera ni acotamiento. ¿Por qué lado debe caminar?","o":["Por el lado izquierdo, de frente al tráfico","Por el lado derecho, en el sentido del tráfico","Por el centro del carril","Por cualquier lado, da igual"],"h1":"Quien camina debe poder ver los autos que vienen hacia él.","h2":"En Illinois, donde no hay acera ni acotamiento, un peatón en una vía de dos sentidos debe caminar cerca del borde izquierdo, de frente al tráfico.","p":"Correcto. Camina por la izquierda, de frente al tráfico."},"ref":{"doc":"IL","page":null}},{"id":"il-178","scope":"IL","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Illinois, a person on foot walks around a lowered railroad crossing gate. What is the fine for a first violation?","o":["$10","$250","$50","$2,500"],"h1":"A second violation doubles it to $500.","h2":"In Illinois, a pedestrian who goes around a closed railroad crossing gate can be fined $250 for a first violation and $500 for a second.","p":"Right. The first fine for a pedestrian is $250."},"es":{"q":"En Illinois, una persona a pie rodea una barrera baja de un cruce de tren. ¿Cuál es la multa por la primera vez?","o":["$10","$250","$50","$2,500"],"h1":"Una segunda vez la duplica a $500.","h2":"En Illinois, un peatón que rodea una barrera cerrada de un cruce de tren puede recibir una multa de $250 la primera vez y $500 la segunda.","p":"Correcto. La primera multa para un peatón es $250."},"ref":{"doc":"IL","page":null}},{"id":"il-179","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, what must a bicycle have to be ridden at night?","o":["Only a bell","A horn and a flag","A white front light seen from 500 feet and a red rear reflector or light","Nothing, if the rider wears light clothes"],"h1":"Think of what makes the bike visible from the front and the back.","h2":"In Illinois, a bicycle ridden at night must have a white front lamp visible from at least 500 feet and a red rear reflector, or a red rear light visible from 500 feet.","p":"Right. A white light in front and red reflector or light in back."},"es":{"q":"En Illinois, ¿qué debe tener una bicicleta para usarse de noche?","o":["Solo un timbre","Una bocina y una bandera","Una luz blanca delantera visible a 500 pies y un reflector o luz roja atrás","Nada, si el ciclista usa ropa clara"],"h1":"Piensa en lo que hace visible la bicicleta de frente y de atrás.","h2":"En Illinois, una bicicleta usada de noche debe tener una luz blanca delantera visible al menos a 500 pies y un reflector rojo atrás, o una luz roja trasera visible a 500 pies.","p":"Correcto. Luz blanca adelante y reflector o luz roja atrás."},"ref":{"doc":"IL","page":null}},{"id":"il-180","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how many bicycle riders may ride side by side on a roadway?","o":["Only 1","Up to 3","Any number","No more than 2"],"h1":"Riders may pair up, but not more.","h2":"In Illinois, bicycle riders may not ride more than 2 abreast on a roadway, except on paths or lanes set aside for them.","p":"Right. No more than 2 side by side."},"es":{"q":"En Illinois, ¿cuántos ciclistas pueden ir uno al lado del otro en la vía?","o":["Solo 1","Hasta 3","Cualquier número","No más de 2"],"h1":"Pueden ir en pareja, pero no más.","h2":"En Illinois, los ciclistas no pueden ir más de 2 lado a lado en la vía, salvo en senderos o carriles exclusivos para ellos.","p":"Correcto. No más de 2 lado a lado."},"ref":{"doc":"IL","page":null}},{"id":"il-181","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, how far before a turn must a bicycle rider signal?","o":["At least 100 feet","At least 10 feet","At least 500 feet","Bicycle riders never signal"],"h1":"It is the same distance as for cars in town.","h2":"In Illinois, a bicycle rider must signal during at least the last 100 feet before turning, but may use both hands when needed to control the bike.","p":"Right. Bicycle riders signal at least 100 feet before a turn."},"es":{"q":"En Illinois, ¿con cuánta anticipación debe señalizar un ciclista antes de girar?","o":["Al menos 100 pies","Al menos 10 pies","Al menos 500 pies","Los ciclistas nunca señalizan"],"h1":"Es la misma distancia que para los autos en la ciudad.","h2":"En Illinois, un ciclista debe señalizar durante al menos los últimos 100 pies antes de girar, pero puede usar ambas manos cuando las necesita para controlar la bicicleta.","p":"Correcto. Los ciclistas señalizan al menos 100 pies antes de girar."},"ref":{"doc":"IL","page":null}},{"id":"il-182","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a bicycle rider on a sidewalk comes up behind a person walking. What must the rider do?","o":["Pass quietly without slowing","Yield, and give a sound signal before passing","Ride into the street without looking","Ask the walker to step onto the grass"],"h1":"People on foot come first on a sidewalk.","h2":"In Illinois, a bicycle rider on a sidewalk must yield to pedestrians and give an audible signal, like a bell or voice, before passing them.","p":"Right. Yield and give a sound signal before passing."},"es":{"q":"En Illinois, un ciclista en la acera se acerca por detrás a una persona que camina. ¿Qué debe hacer?","o":["Pasar en silencio sin frenar","Cederle el paso y avisar con un sonido antes de pasar","Bajar a la calle sin mirar","Pedirle al peatón que se suba al pasto"],"h1":"En la acera, las personas a pie van primero.","h2":"En Illinois, un ciclista en la acera debe ceder el paso a los peatones y avisar con un sonido, como un timbre o la voz, antes de pasarlos.","p":"Correcto. Cede el paso y avisa con un sonido antes de pasar."},"ref":{"doc":"IL","page":null}},{"id":"il-183","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a town allows golf carts on its streets. On which streets may they be driven?","o":["Any street, including highways","Only interstates","Only streets posted at 35 mph or less, by a licensed driver","Any street, by anyone 12 or older"],"h1":"These vehicles are slow and not built for fast roads.","h2":"In Illinois, where a local government allows them, non-highway vehicles like golf carts may be driven only on streets posted at 35 mph or less, and the driver must have a valid driver's license.","p":"Right. Only on streets of 35 mph or less, with a licensed driver."},"es":{"q":"En Illinois, un pueblo permite carritos de golf en sus calles. ¿Por qué calles pueden circular?","o":["Por cualquier calle, incluidas las carreteras","Solo por autopistas interestatales","Solo por calles con límite de 35 mph o menos, con un conductor con licencia","Por cualquier calle, con cualquier persona de 12 años o más"],"h1":"Estos vehículos son lentos y no están hechos para vías rápidas.","h2":"En Illinois, donde el gobierno local lo permite, los vehículos no aptos para carretera, como los carritos de golf, solo pueden circular por calles con límite de 35 mph o menos, y el conductor debe tener licencia de conducir válida.","p":"Correcto. Solo por calles de 35 mph o menos, con un conductor con licencia."},"ref":{"doc":"IL","page":null}},{"id":"il-184","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, when may a motorcycle carry a small child as a passenger?","o":["Any time, if the child holds on","Only if the child sits in front of the rider","Never, passengers are not allowed","Only if the child can rest a foot on the footrest"],"h1":"The passenger must be big enough to reach a certain part of the bike.","h2":"In Illinois, a motorcycle may carry a passenger only if the passenger can rest a foot on the footrest while the motorcycle is moving.","p":"Right. The passenger must reach the footrests."},"es":{"q":"En Illinois, ¿cuándo puede una motocicleta llevar a un niño pequeño como pasajero?","o":["Siempre, si el niño se agarra","Solo si el niño va delante del conductor","Nunca, no se permiten pasajeros","Solo si el niño puede apoyar un pie en el reposapiés"],"h1":"El pasajero debe ser lo bastante grande para alcanzar cierta parte de la moto.","h2":"En Illinois, una motocicleta solo puede llevar un pasajero si este puede apoyar un pie en el reposapiés mientras la moto está en movimiento.","p":"Correcto. El pasajero debe alcanzar los reposapiés."},"ref":{"doc":"IL","page":null}},{"id":"il-185","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, what eye protection must a motorcycle rider use?","o":["Shatter-resistant glasses, goggles or a clear shield; contact lenses do not count","Contact lenses are enough","None, if the rider wears a helmet","Only sunglasses at night"],"h1":"Something in front of the eyes must stop flying objects.","h2":"In Illinois, motorcycle and moped riders and their passengers must wear shatter-resistant glasses, goggles or a transparent shield, and contact lenses are not acceptable eye protection.","p":"Right. Glasses, goggles or a shield, but not contact lenses."},"es":{"q":"En Illinois, ¿qué protección para los ojos debe usar un motociclista?","o":["Lentes resistentes a roturas, gafas protectoras o un protector transparente; los lentes de contacto no cuentan","Los lentes de contacto son suficientes","Ninguna, si usa casco","Solo lentes de sol de noche"],"h1":"Algo delante de los ojos debe detener los objetos que vuelan.","h2":"En Illinois, los conductores de motocicletas y ciclomotores y sus pasajeros deben usar lentes resistentes a roturas, gafas protectoras o un protector transparente, y los lentes de contacto no se aceptan como protección.","p":"Correcto. Lentes, gafas o protector, pero no lentes de contacto."},"ref":{"doc":"IL","page":null}},{"id":"il-186","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, may you shift into neutral and coast down a hill to save fuel?","o":["Yes, it is a good way to save fuel","No, coasting in neutral downhill is illegal","Yes, on hills under one mile","Yes, if no car is behind you"],"h1":"In neutral you have less control and no engine braking.","h2":"In Illinois, you may not coast down a hill with the gears or transmission in neutral.","p":"Right. Coasting downhill in neutral is not allowed."},"es":{"q":"En Illinois, ¿puedes poner neutral y bajar una cuesta sin tracción para ahorrar gasolina?","o":["Sí, es una buena forma de ahorrar gasolina","No, bajar en neutral es ilegal","Sí, en cuestas de menos de una milla","Sí, si no hay autos detrás"],"h1":"En neutral tienes menos control y no frenas con el motor.","h2":"En Illinois, no puedes bajar una cuesta con la transmisión en neutral.","p":"Correcto. No se permite bajar en neutral."},"ref":{"doc":"IL","page":null}},{"id":"il-187","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, may teenagers ride in a trailer being towed down the highway at 45 mph?","o":["Yes, if they sit down","Yes, if the trailer has sides","No, riding in a towed trailer is allowed only in narrow cases at 15 mph or less","Yes, during daylight"],"h1":"The speed limit for this exception is very low.","h2":"In Illinois, people may ride in a towed trailer only in an emergency, or at 15 mph or less for a parade or farm work or when the passenger is over 18.","p":"Right. Not at highway speed."},"es":{"q":"En Illinois, ¿pueden unos adolescentes viajar en un tráiler remolcado por la carretera a 45 mph?","o":["Sí, si van sentados","Sí, si el tráiler tiene paredes","No, viajar en un tráiler remolcado solo se permite en casos limitados a 15 mph o menos","Sí, de día"],"h1":"El límite de velocidad de esta excepción es muy bajo.","h2":"En Illinois, solo se puede viajar en un tráiler remolcado en una emergencia, o a 15 mph o menos en un desfile o trabajo agrícola, o cuando el pasajero es mayor de 18 años.","p":"Correcto. No a velocidad de carretera."},"ref":{"doc":"IL","page":null}},{"id":"il-188","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, who must wear a seat belt in a car on the road?","o":["Only the driver","Only people in the front seat","Only children","The driver and every passenger, front and back"],"h1":"The Illinois law covers everyone in the car.","h2":"In Illinois, the driver and every passenger, in the front and the back, must wear a properly fastened seat belt.","p":"Right. Everyone in the car must buckle up."},"es":{"q":"En Illinois, ¿quién debe usar cinturón de seguridad en un auto en la vía?","o":["Solo el conductor","Solo los del asiento delantero","Solo los niños","El conductor y todos los pasajeros, adelante y atrás"],"h1":"La ley de Illinois cubre a todos los que van en el auto.","h2":"En Illinois, el conductor y todos los pasajeros, adelante y atrás, deben usar el cinturón de seguridad bien abrochado.","p":"Correcto. Todos en el auto deben abrocharse."},"ref":{"doc":"IL","page":null}},{"id":"il-189","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, who is responsible for making sure a 12-year-old passenger wears a seat belt?","o":["The driver","Only the child","Only the child's school","No one, belts are optional at that age"],"h1":"The person behind the wheel is in charge.","h2":"In Illinois, the driver is responsible for securing children from 8 to under 16 in seat belts.","p":"Right. The driver must make sure the child is buckled."},"es":{"q":"En Illinois, ¿quién es responsable de que un pasajero de 12 años use el cinturón de seguridad?","o":["El conductor","Solo el niño","Solo la escuela del niño","Nadie, el cinturón es opcional a esa edad"],"h1":"La persona al volante está a cargo.","h2":"En Illinois, el conductor es responsable de abrochar el cinturón a los niños de 8 a menos de 16 años.","p":"Correcto. El conductor debe asegurarse de que el niño lleve el cinturón."},"ref":{"doc":"IL","page":null}},{"id":"il-190","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, a child under 2 rides in a car. How must the child be secured?","o":["In a front-facing booster seat","In a rear-facing car seat, unless the child is 40 pounds or 40 inches or more","With an adult seat belt","On an adult's lap"],"h1":"Very young children ride facing the back of the car.","h2":"In Illinois, a child under 2 must ride in a rear-facing car seat, unless the child weighs 40 pounds or more or is 40 inches or taller.","p":"Right. Under 2 means rear-facing, unless the child is 40 pounds or 40 inches."},"es":{"q":"En Illinois, un niño menor de 2 años viaja en un auto. ¿Cómo debe ir asegurado?","o":["En un asiento elevado mirando hacia adelante","En una silla mirando hacia atrás, salvo que pese 40 libras o mida 40 pulgadas o más","Con el cinturón de un adulto","En las piernas de un adulto"],"h1":"Los niños muy pequeños viajan mirando hacia la parte trasera del auto.","h2":"En Illinois, un niño menor de 2 años debe ir en una silla mirando hacia atrás, salvo que pese 40 libras o más o mida 40 pulgadas o más.","p":"Correcto. Menor de 2 años va mirando hacia atrás, salvo que pese 40 libras o mida 40 pulgadas."},"ref":{"doc":"IL","page":null}},{"id":"il-191","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a 17-year-old driver has three friends aged 16 to 18 in the car. Who must make sure they are buckled?","o":["Each friend's parents","Only the friends themselves","The 17-year-old driver","No one, they are almost adults"],"h1":"Young drivers carry this duty for their young passengers.","h2":"In Illinois, a driver under 18 is responsible for making sure every passenger under 19 wears a seat belt or is in a child restraint.","p":"Right. The young driver is responsible."},"es":{"q":"En Illinois, un conductor de 17 años lleva a tres amigos de 16 a 18 años. ¿Quién debe asegurarse de que lleven el cinturón?","o":["Los padres de cada amigo","Solo los amigos","El conductor de 17 años","Nadie, ya casi son adultos"],"h1":"Los conductores jóvenes tienen este deber con sus pasajeros jóvenes.","h2":"En Illinois, un conductor menor de 18 años es responsable de que cada pasajero menor de 19 años use el cinturón o vaya en una silla de seguridad.","p":"Correcto. El conductor joven es el responsable."},"ref":{"doc":"IL","page":null}},{"id":"il-192","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, it is daytime but raining hard enough that you need your windshield wipers. What about your headlights?","o":["They must stay off in daytime","Only parking lights are needed","Only high beams may be used","They must be on"],"h1":"Illinois links headlights to wipers.","h2":"In Illinois, headlights must be on from sunset to sunrise, whenever rain, snow or fog requires windshield wipers, and whenever you cannot see clearly 1,000 feet ahead.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Illinois, es de día pero llueve tanto que necesitas los limpiaparabrisas. ¿Qué pasa con tus faros?","o":["Deben estar apagados de día","Solo se necesitan las luces de estacionamiento","Solo se pueden usar las luces altas","Deben estar encendidos"],"h1":"Illinois relaciona los faros con los limpiaparabrisas.","h2":"En Illinois, los faros deben estar encendidos desde la puesta hasta la salida del sol, siempre que la lluvia, la nieve o la niebla exijan limpiaparabrisas, y cuando no puedes ver bien a 1,000 pies.","p":"Correcto. Limpiaparabrisas encendidos significa faros encendidos."},"ref":{"doc":"IL","page":null}},{"id":"il-193","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, a car is coming toward you at night. Within how many feet must you dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is more than the distance for a car you are following.","h2":"In Illinois, you must dim your high beams when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim within 500 feet of oncoming traffic."},"es":{"q":"En Illinois, un auto viene hacia ti de noche. ¿A cuántos pies debes bajar las luces altas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es más que la distancia para un auto que vas siguiendo.","h2":"En Illinois, debes bajar las luces altas cuando estás a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. Baja las luces a menos de 500 pies del tráfico de frente."},"ref":{"doc":"IL","page":null}},{"id":"il-194","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, you are following another car at night. Within how many feet must you dim your high beams?","o":["50 feet","300 feet","500 feet","1,000 feet"],"h1":"It is less than the distance for oncoming cars.","h2":"In Illinois, you must dim your high beams when you are less than 300 feet behind another vehicle.","p":"Right. Dim within 300 feet of the car ahead."},"es":{"q":"En Illinois, vas detrás de otro auto de noche. ¿A cuántos pies debes bajar las luces altas?","o":["50 pies","300 pies","500 pies","1,000 pies"],"h1":"Es menos que la distancia para autos que vienen de frente.","h2":"En Illinois, debes bajar las luces altas cuando estás a menos de 300 pies detrás de otro vehículo.","p":"Correcto. Baja las luces a menos de 300 pies del auto de adelante."},"ref":{"doc":"IL","page":null}},{"id":"il-195","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, your load sticks out 5 feet past the back of your truck during the day. What must you put on the end of it?","o":["A white towel","Nothing in daylight","A red flag at least 12 inches square","A small yellow sticker"],"h1":"At night a red light is needed instead.","h2":"In Illinois, a load that sticks out 4 feet or more past the rear needs a red flag at least 12 inches square in the daytime and a red light at night.","p":"Right. Use a red flag at least 12 inches square."},"es":{"q":"En Illinois, tu carga sobresale 5 pies por detrás de tu camioneta durante el día. ¿Qué debes poner en el extremo?","o":["Una toalla blanca","Nada de día","Una bandera roja de al menos 12 pulgadas por lado","Una pequeña calcomanía amarilla"],"h1":"De noche se necesita una luz roja.","h2":"En Illinois, una carga que sobresale 4 pies o más por detrás necesita una bandera roja de al menos 12 pulgadas por lado de día y una luz roja de noche.","p":"Correcto. Usa una bandera roja de al menos 12 pulgadas por lado."},"ref":{"doc":"IL","page":null}},{"id":"il-196","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, how much of the front windshield may have tinted film?","o":["The top half","The whole windshield, if it is light","None at all","Only the top 6 inches"],"h1":"It is a narrow strip at the top.","h2":"In Illinois, nonreflective tinted film may be used only along the top of the windshield, no more than 6 inches down.","p":"Right. Only the top 6 inches may be tinted."},"es":{"q":"En Illinois, ¿cuánto del parabrisas delantero puede tener película polarizada?","o":["La mitad de arriba","Todo el parabrisas, si es clara","Nada","Solo las 6 pulgadas de arriba"],"h1":"Es una franja angosta arriba.","h2":"En Illinois, la película polarizada no reflectante solo puede ir en la parte superior del parabrisas, a no más de 6 pulgadas hacia abajo.","p":"Correcto. Solo las 6 pulgadas de arriba pueden estar polarizadas."},"ref":{"doc":"IL","page":null}},{"id":"il-197","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, below what tread depth is a car tire considered unsafe?","o":["2/32 of an inch","1/2 of an inch","1/4 of an inch","1/100 of an inch"],"h1":"It is a very small number of thirty-seconds.","h2":"In Illinois, a car tire is unsafe when its tread depth is less than 2/32 of an inch.","p":"Right. Less than 2/32 of an inch is unsafe."},"es":{"q":"En Illinois, ¿con qué profundidad de dibujo una llanta de auto se considera insegura?","o":["Menos de 2/32 de pulgada","Menos de 1/2 pulgada","Menos de 1/4 de pulgada","Menos de 1/100 de pulgada"],"h1":"Es un número muy pequeño de treintaidosavos.","h2":"En Illinois, una llanta de auto es insegura cuando la profundidad del dibujo es menor de 2/32 de pulgada.","p":"Correcto. Menos de 2/32 de pulgada es inseguro."},"ref":{"doc":"IL","page":null}},{"id":"il-198","scope":"IL","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Illinois, may you drive while wearing headphones over both ears?","o":["Yes, at a low volume","No, but a one-ear phone earpiece is allowed","Yes, on highways only","Yes, if you are over 21"],"h1":"You need to hear sirens and horns.","h2":"In Illinois, drivers may not wear headset receivers, though a single-sided earpiece used with a phone is allowed.","p":"Right. No headphones, but a one-ear earpiece is allowed."},"es":{"q":"En Illinois, ¿puedes conducir con audífonos en ambos oídos?","o":["Sí, a bajo volumen","No, pero se permite un auricular de un solo oído para el teléfono","Sí, solo en autopistas","Sí, si tienes más de 21 años"],"h1":"Necesitas oír las sirenas y las bocinas.","h2":"En Illinois, los conductores no pueden usar audífonos, aunque se permite un auricular de un solo oído para el teléfono.","p":"Correcto. Nada de audífonos, pero se permite un auricular de un oído."},"ref":{"doc":"IL","page":null}},{"id":"il-199","scope":"IL","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Illinois, a driver of any age is within 500 feet of an emergency scene with flashing lights. What phone use is allowed?","o":["Any use while moving slowly","Texting only","Only hands-free or voice-operated use, or a call about an emergency","Watching a video"],"h1":"This rule also covers school zones and construction zones.","h2":"In Illinois, no driver may use a phone in a school zone, a construction zone or within 500 feet of an emergency scene, except in hands-free or voice-operated mode or to report an emergency.","p":"Right. Only hands-free use or an emergency call there."},"es":{"q":"En Illinois, un conductor de cualquier edad está a menos de 500 pies de una emergencia con luces encendidas. ¿Qué uso del teléfono se permite?","o":["Cualquier uso si va despacio","Solo enviar mensajes","Solo el uso de manos libres o por voz, o una llamada de emergencia","Ver un video"],"h1":"Esta regla también cubre zonas escolares y de construcción.","h2":"En Illinois, ningún conductor puede usar el teléfono en una zona escolar, una zona de construcción o a menos de 500 pies de una emergencia, salvo en modo manos libres o por voz o para reportar una emergencia.","p":"Correcto. Allí solo se permite manos libres o una llamada de emergencia."},"ref":{"doc":"IL","page":null}},{"id":"il-200","scope":"IL","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Illinois, when may an adult driver use a hand-held phone?","o":["At any red light","When driving under 25 mph","On empty country roads","When parked on the shoulder, or stopped in blocked traffic in park or neutral"],"h1":"The car must not be moving, and the gear matters.","h2":"In Illinois, a driver may use a hand-held phone when parked on the shoulder, or when stopped because traffic is blocked and the car is in neutral or park.","p":"Right. Only when parked on the shoulder or stopped in park or neutral in blocked traffic."},"es":{"q":"En Illinois, ¿cuándo puede un conductor adulto usar el teléfono en la mano?","o":["En cualquier luz roja","Cuando va a menos de 25 mph","En caminos rurales vacíos","Cuando está estacionado en el acotamiento, o detenido por tráfico bloqueado en park o neutral"],"h1":"El auto no debe moverse, y la marcha importa.","h2":"En Illinois, un conductor puede usar el teléfono en la mano cuando está estacionado en el acotamiento, o detenido porque el tráfico está bloqueado y el auto está en neutral o park.","p":"Correcto. Solo estacionado en el acotamiento, o detenido en park o neutral con el tráfico bloqueado."},"ref":{"doc":"IL","page":null}},{"id":"il-201","scope":"IL","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Illinois, what is the maximum fine for a first offense of using a hand-held phone while driving?","o":["$75","$10","$500","$1,000"],"h1":"It goes up by $25 with each new offense, to $150.","h2":"In Illinois, the maximum fine for a first hand-held phone offense is $75, and it rises to $150 for a fourth offense.","p":"Right. The first maximum fine is $75."},"es":{"q":"En Illinois, ¿cuál es la multa máxima por una primera vez usando el teléfono en la mano al conducir?","o":["$75","$10","$500","$1,000"],"h1":"Sube $25 con cada nueva falta, hasta $150.","h2":"En Illinois, la multa máxima por una primera falta usando el teléfono en la mano es $75, y sube hasta $150 la cuarta vez.","p":"Correcto. La primera multa máxima es $75."},"ref":{"doc":"IL","page":null}},{"id":"il-202","scope":"IL","cat":"licensing","sign":null,"c":1,"en":{"q":"In Illinois, after a crash, a tow truck you did not call stops and offers to tow your car. What does the law say?","o":["You must accept the first tow truck that arrives","Tow trucks may not stop to solicit unless called by police, the owner or the owner's agent","Any tow truck may stop and tow your car","Only the police may refuse a tow truck"],"h1":"Unrequested towing offers at crash scenes are against the law.","h2":"In Illinois, a tow truck may not stop at a crash scene to offer towing unless it was called by police, a highway agency, the vehicle owner or driver, or their agent such as an insurer.","p":"Right. Tow trucks may not solicit at a crash unless they were called."},"es":{"q":"En Illinois, después de un choque, una grúa que no llamaste se detiene y ofrece remolcar tu auto. ¿Qué dice la ley?","o":["Debes aceptar la primera grúa que llegue","Las grúas no pueden detenerse a ofrecer servicio salvo que las llame la policía, el dueño o su representante","Cualquier grúa puede detenerse y llevarse tu auto","Solo la policía puede rechazar una grúa"],"h1":"Las ofertas de remolque no pedidas en el lugar de un choque son ilegales.","h2":"En Illinois, una grúa no puede detenerse en el lugar de un choque para ofrecer remolque salvo que la haya llamado la policía, una agencia de carreteras, el dueño o conductor del vehículo, o su representante, como su aseguradora.","p":"Correcto. Las grúas no pueden ofrecer servicio en un choque si no las llamaron."},"ref":{"doc":"IL","page":null}},{"id":"in-001","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what is the youngest age to get a learner's permit if you are enrolled in driver education?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Driver education lets you start one year before the usual age.","h2":"In Indiana you can get a learner's permit at 15 if you are enrolled in an approved driver education course.","p":"Right. With driver education, the permit starts at 15."},"es":{"q":"En Indiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz si usted está inscrito en educación vial?","o":["14 años","15 años","16 años","17 años"],"h1":"La educación vial le permite empezar un año antes de la edad normal.","h2":"En Indiana usted puede obtener el permiso de aprendiz a los 15 años si está inscrito en un curso aprobado de educación vial.","p":"Correcto. Con educación vial, el permiso empieza a los 15."},"zh":{"q":"在 Indiana，如果你报名了驾驶课，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"上驾驶课可以让你比一般年龄早一年开始。","h2":"在 Indiana，如果你报名了经过批准的驾驶课，15 岁就可以拿到学习驾照。","p":"对。上驾驶课的话，学习驾照从 15 岁开始。"},"vi":{"q":"Ở Indiana, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu nếu bạn đang học lớp giáo dục lái xe (driver education)?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Lớp giáo dục lái xe cho phép bạn bắt đầu sớm hơn tuổi thông thường một năm.","h2":"Ở Indiana, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu bạn đã ghi danh vào một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Có học giáo dục lái xe, giấy phép bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Indiana, ano ang pinakabatang edad para makakuha ng learner's permit kung naka-enroll ka sa driver education?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Sa driver education, puwede kang magsimula nang isang taon bago ang karaniwang edad.","h2":"Sa Indiana, puwede kang kumuha ng learner's permit sa edad na 15 kung naka-enroll ka sa isang aprubadong driver education course.","p":"Tama. Kapag may driver education, nagsisimula ang permit sa 15."},"ar":{"q":"في Indiana، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit) إذا كنت مسجّلًا في دورة تعليم القيادة (driver education)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"دورة تعليم القيادة تسمح لك بالبدء قبل العمر المعتاد بسنة واحدة.","h2":"في Indiana يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا كنت مسجّلًا في دورة معتمدة لتعليم القيادة.","p":"صحيح. مع دورة تعليم القيادة يبدأ التصريح في عمر 15 سنة."},"ref":{"doc":"IN","page":3}},{"id":"in-002","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how old must you be to get a learner's permit without taking driver education?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year later than with driver education.","h2":"In Indiana you must be at least 16 to get a learner's permit without a driver education course.","p":"Correct. Without driver education, you wait until 16."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener un permiso de aprendiz sin tomar educación vial?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año más tarde que con educación vial.","h2":"En Indiana usted debe tener por lo menos 16 años para obtener el permiso de aprendiz sin un curso de educación vial.","p":"Correcto. Sin educación vial, hay que esperar hasta los 16."},"zh":{"q":"在 Indiana，不上驾驶课的话，你必须几岁才能拿到学习驾照？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"比上驾驶课晚一年。","h2":"在 Indiana，不上驾驶课的话，你必须至少 16 岁才能拿到学习驾照。","p":"正确。不上驾驶课，就要等到 16 岁。"},"vi":{"q":"Ở Indiana, bạn phải bao nhiêu tuổi để lấy giấy phép tập lái mà không học giáo dục lái xe?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là muộn hơn một năm so với khi có học giáo dục lái xe.","h2":"Ở Indiana, bạn phải ít nhất 16 tuổi để lấy giấy phép tập lái nếu không học khóa giáo dục lái xe.","p":"Đúng. Không học giáo dục lái xe thì bạn phải chờ đến 16 tuổi."},"tl":{"q":"Sa Indiana, ilang taon ka dapat para makakuha ng learner's permit nang walang driver education?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon itong mas huli kaysa kapag may driver education.","h2":"Sa Indiana, dapat ay hindi bababa sa 16 ka para makakuha ng learner's permit nang walang driver education course.","p":"Tama. Kapag walang driver education, maghihintay ka hanggang 16."},"ar":{"q":"في Indiana، كم يجب أن يكون عمرك للحصول على تصريح التعلّم دون دورة تعليم القيادة؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو متأخر بسنة واحدة عن العمر مع دورة تعليم القيادة.","h2":"في Indiana يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح التعلّم دون دورة تعليم القيادة.","p":"صحيح. دون دورة تعليم القيادة تنتظر حتى عمر 16 سنة."},"ref":{"doc":"IN","page":3}},{"id":"in-003","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how old must a relative be to supervise a learner under 18?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"Indiana asks for an older supervisor than many states do.","h2":"In Indiana a relative who supervises a learner under 18 must be a licensed driver who is at least 25 years old.","p":"Right. The relative must be 25 or older."},"es":{"q":"En Indiana, ¿qué edad debe tener un familiar para supervisar a un aprendiz menor de 18 años?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Indiana pide un supervisor de más edad que muchos otros estados.","h2":"En Indiana, un familiar que supervisa a un aprendiz menor de 18 años debe ser un conductor con licencia de por lo menos 25 años.","p":"Correcto. El familiar debe tener 25 años o más."},"zh":{"q":"在 Indiana，陪同 18 岁以下学习驾驶的人练车的亲属必须几岁？","o":["至少 18 岁","至少 19 岁","至少 21 岁","至少 25 岁"],"h1":"Indiana 要求的陪同者年龄比很多州都大。","h2":"在 Indiana，陪同 18 岁以下学习驾驶的人练车的亲属，必须是至少 25 岁、有驾照的司机。","p":"对。亲属必须 25 岁或以上。"},"vi":{"q":"Ở Indiana, người thân phải bao nhiêu tuổi để giám sát một người tập lái dưới 18 tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 19 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Indiana yêu cầu người giám sát lớn tuổi hơn so với nhiều tiểu bang khác.","h2":"Ở Indiana, người thân giám sát một người tập lái dưới 18 tuổi phải là người có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người thân phải từ 25 tuổi trở lên."},"tl":{"q":"Sa Indiana, ilang taon dapat ang isang kamag-anak para magbantay sa isang learner na wala pang 18?","o":["Hindi bababa sa 18","Hindi bababa sa 19","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Mas matandang tagabantay ang hinihingi ng Indiana kaysa sa maraming ibang estado.","h2":"Sa Indiana, ang kamag-anak na nagbabantay sa learner na wala pang 18 ay dapat may lisensya at hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 o mas matanda ang kamag-anak."},"ar":{"q":"في Indiana، كم يجب أن يكون عمر القريب الذي يشرف على متعلّم عمره أقل من 18 سنة؟","o":["18 سنة على الأقل","19 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"تطلب Indiana مشرفًا أكبر سنًّا مما تطلبه ولايات كثيرة.","h2":"في Indiana يجب أن يكون القريب الذي يشرف على متعلّم عمره أقل من 18 سنة سائقًا مرخّصًا وعمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر القريب 25 سنة أو أكثر."},"ref":{"doc":"IN","page":4}},{"id":"in-004","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a learner's spouse may supervise practice driving. How old must the spouse be?","o":["At least 21","At least 25","At least 18","At least 30"],"h1":"It is younger than the age for other relatives.","h2":"In Indiana a licensed spouse who is at least 21 may supervise a learner, while other relatives must be at least 25.","p":"Correct. A spouse must be 21 or older."},"es":{"q":"En Indiana, el cónyuge de un aprendiz puede supervisar la práctica. ¿Qué edad debe tener el cónyuge?","o":["Por lo menos 21","Por lo menos 25","Por lo menos 18","Por lo menos 30"],"h1":"Es menor que la edad pedida a otros familiares.","h2":"En Indiana, un cónyuge con licencia de por lo menos 21 años puede supervisar a un aprendiz; otros familiares deben tener por lo menos 25.","p":"Correcto. El cónyuge debe tener 21 años o más."},"zh":{"q":"在 Indiana，学习驾驶的人的配偶可以陪同练车。配偶必须几岁？","o":["至少 21 岁","至少 25 岁","至少 18 岁","至少 30 岁"],"h1":"比其他亲属的年龄要求小。","h2":"在 Indiana，至少 21 岁、有驾照的配偶可以陪同学习驾驶的人，其他亲属则必须至少 25 岁。","p":"正确。配偶必须 21 岁或以上。"},"vi":{"q":"Ở Indiana, vợ hoặc chồng của người tập lái có thể giám sát việc tập lái. Người vợ hoặc chồng đó phải bao nhiêu tuổi?","o":["Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 18 tuổi","Ít nhất 30 tuổi"],"h1":"Tuổi này nhỏ hơn tuổi yêu cầu cho những người thân khác.","h2":"Ở Indiana, vợ hoặc chồng có bằng lái và ít nhất 21 tuổi có thể giám sát người tập lái, còn những người thân khác phải ít nhất 25 tuổi.","p":"Đúng. Vợ hoặc chồng phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Indiana, puwedeng magbantay sa pag-eensayo ng pagmamaneho ang asawa ng learner. Ilang taon dapat ang asawa?","o":["Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 18","Hindi bababa sa 30"],"h1":"Mas bata ito kaysa sa edad para sa ibang kamag-anak.","h2":"Sa Indiana, ang asawang may lisensya at hindi bababa sa 21 ay puwedeng magbantay sa learner, pero ang ibang kamag-anak ay dapat hindi bababa sa 25.","p":"Tama. Dapat 21 o mas matanda ang asawa."},"ar":{"q":"في Indiana، يمكن لزوج المتعلّم أو زوجته الإشراف على التدريب على القيادة. كم يجب أن يكون عمر الزوج أو الزوجة؟","o":["21 سنة على الأقل","25 سنة على الأقل","18 سنة على الأقل","30 سنة على الأقل"],"h1":"هو أصغر من العمر المطلوب للأقارب الآخرين.","h2":"في Indiana يمكن للزوج أو الزوجة المرخّص الذي عمره 21 سنة على الأقل أن يشرف على المتعلّم، أما الأقارب الآخرون فيجب أن يكون عمرهم 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر الزوج أو الزوجة 21 سنة أو أكثر."},"ref":{"doc":"IN","page":4}},{"id":"in-005","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many hours of supervised driving must a new driver log before getting a license?","o":["20 hours","50 hours","40 hours","100 hours"],"h1":"It is a round number between 40 and 100.","h2":"In Indiana a new driver must log at least 50 hours of supervised driving practice before applying for a license.","p":"Right. Indiana asks for 50 logged hours."},"es":{"q":"En Indiana, ¿cuántas horas de manejo supervisado debe registrar un conductor nuevo antes de obtener la licencia?","o":["20 horas","50 horas","40 horas","100 horas"],"h1":"Es un número redondo entre 40 y 100.","h2":"En Indiana, un conductor nuevo debe registrar por lo menos 50 horas de práctica supervisada antes de solicitar la licencia.","p":"Correcto. Indiana pide 50 horas registradas."},"zh":{"q":"在 Indiana，新司机拿驾照前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","50 小时","40 小时","100 小时"],"h1":"是 40 和 100 之间的一个整数。","h2":"在 Indiana，新司机申请驾照前，必须记录至少 50 小时有人陪同的驾驶练习。","p":"对。Indiana 要求记录 50 小时。"},"vi":{"q":"Ở Indiana, người lái mới phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một số tròn ở giữa 40 và 100.","h2":"Ở Indiana, người lái mới phải ghi lại ít nhất 50 giờ tập lái có người giám sát trước khi nộp đơn xin bằng lái.","p":"Đúng. Indiana yêu cầu ghi lại 50 giờ."},"tl":{"q":"Sa Indiana, ilang oras ng binabantayang pagmamaneho ang dapat itala ng bagong driver bago kumuha ng lisensya?","o":["20 oras","50 oras","40 oras","100 oras"],"h1":"Isa itong buong numero sa pagitan ng 40 at 100.","h2":"Sa Indiana, ang bagong driver ay dapat magtala ng hindi bababa sa 50 oras ng binabantayang pag-eensayo bago mag-apply para sa lisensya.","p":"Tama. 50 oras na nakatala ang hinihingi ng Indiana."},"ar":{"q":"في Indiana، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل السائق الجديد قبل الحصول على الرخصة؟","o":["20 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هو رقم مدوَّر بين 40 و100.","h2":"في Indiana يجب أن يسجّل السائق الجديد 50 ساعة على الأقل من التدريب على القيادة تحت الإشراف قبل التقديم على الرخصة.","p":"صحيح. تطلب Indiana تسجيل 50 ساعة."},"ref":{"doc":"IN","page":9}},{"id":"in-006","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many of the logged supervised hours must be driven at night?","o":["At least 2 hours","At least 5 hours","At least 10 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"In Indiana at least 10 of the 50 supervised practice hours must be driven at night.","p":"Correct. Ten of the hours are at night."},"es":{"q":"En Indiana, ¿cuántas de las horas supervisadas registradas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"En Indiana, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"zh":{"q":"在 Indiana，记录的有人陪同驾驶时间中，必须有多少小时是在夜间开的？","o":["至少 2 小时","至少 5 小时","至少 10 小时","至少 25 小时"],"h1":"是总时间的五分之一。","h2":"在 Indiana，50 小时有人陪同的练习中，至少 10 小时必须在夜间开。","p":"正确。其中十个小时是在夜间。"},"vi":{"q":"Ở Indiana, trong số giờ lái có người giám sát được ghi lại, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 10 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm tổng số giờ.","h2":"Ở Indiana, ít nhất 10 trong 50 giờ tập lái có người giám sát phải lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Indiana, ilan sa mga nakatalang oras ng binabantayang pagmamaneho ang dapat gawin sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Hindi bababa sa 25 oras"],"h1":"Isang-ikalima ito ng kabuuang oras.","h2":"Sa Indiana, hindi bababa sa 10 sa 50 oras ng binabantayang pag-eensayo ang dapat gawin sa gabi.","p":"Tama. Sampu sa mga oras ay sa gabi."},"ar":{"q":"في Indiana، كم من ساعات القيادة المسجّلة تحت الإشراف يجب أن تكون في الليل؟","o":["ساعتان (2) على الأقل","5 ساعات على الأقل","10 ساعات على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع الساعات.","h2":"في Indiana يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدريب تحت الإشراف في الليل.","p":"صحيح. عشر ساعات تكون في الليل."},"ref":{"doc":"IN","page":9}},{"id":"in-007","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how long must you hold a learner's permit before you can get a probationary license?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about six months.","h2":"In Indiana you must hold your learner's permit for 180 days, about six months, before getting a probationary license.","p":"Right. You hold the permit for 180 days."},"es":{"q":"En Indiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener una licencia probatoria?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos seis meses.","h2":"En Indiana usted debe tener el permiso de aprendiz durante 180 días, unos seis meses, antes de obtener la licencia probatoria.","p":"Correcto. Se tiene el permiso por 180 días."},"zh":{"q":"在 Indiana，你必须持有学习驾照多久，才能拿到试用驾照（probationary license）？","o":["30 天","60 天","90 天","180 天"],"h1":"大约是六个月。","h2":"在 Indiana，你必须持有学习驾照 180 天，大约六个月，才能拿到试用驾照。","p":"对。你要持有学习驾照 180 天。"},"vi":{"q":"Ở Indiana, bạn phải giữ giấy phép tập lái bao lâu trước khi có thể lấy bằng lái thử thách (probationary license)?","o":["30 ngày","60 ngày","90 ngày","180 ngày"],"h1":"Đó là khoảng sáu tháng.","h2":"Ở Indiana, bạn phải giữ giấy phép tập lái 180 ngày, khoảng sáu tháng, trước khi lấy bằng lái thử thách.","p":"Đúng. Bạn giữ giấy phép tập lái 180 ngày."},"tl":{"q":"Sa Indiana, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng probationary license?","o":["30 araw","60 araw","90 araw","180 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa Indiana, dapat hawak mo ang learner's permit nang 180 araw, mga anim na buwan, bago kumuha ng probationary license.","p":"Tama. Hawak mo ang permit nang 180 araw."},"ar":{"q":"في Indiana، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على الرخصة التجريبية (probationary license)؟","o":["30 يومًا","60 يومًا","90 يومًا","180 يومًا"],"h1":"هي حوالي ستة أشهر.","h2":"في Indiana يجب أن تحمل تصريح التعلّم 180 يومًا، أي حوالي ستة أشهر، قبل الحصول على الرخصة التجريبية.","p":"صحيح. تحمل التصريح 180 يومًا."},"ref":{"doc":"IN","page":9}},{"id":"in-008","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how old must you be to get a probationary license if you did not complete driver education?","o":["16 years and 270 days","16 years exactly","15 years and 180 days","18 years exactly"],"h1":"It is later than 16, but well before 17 and a half.","h2":"In Indiana a driver who did not finish driver education must be at least 16 years and 270 days old for a probationary license.","p":"Correct. Without driver education, it is 16 years and 270 days."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener una licencia probatoria si no completó educación vial?","o":["16 años y 270 días","16 años exactos","15 años y 180 días","18 años exactos"],"h1":"Es después de los 16, pero bastante antes de los 17 y medio.","h2":"En Indiana, un conductor que no terminó educación vial debe tener por lo menos 16 años y 270 días para la licencia probatoria.","p":"Correcto. Sin educación vial, son 16 años y 270 días."},"zh":{"q":"在 Indiana，如果你没有完成驾驶课，必须几岁才能拿到试用驾照？","o":["16 岁又 270 天","正好 16 岁","15 岁又 180 天","正好 18 岁"],"h1":"比 16 岁晚，但比 17 岁半早很多。","h2":"在 Indiana，没有完成驾驶课的司机，必须至少 16 岁又 270 天才能拿到试用驾照。","p":"正确。不上驾驶课，就是 16 岁又 270 天。"},"vi":{"q":"Ở Indiana, bạn phải bao nhiêu tuổi để lấy bằng lái thử thách nếu bạn không hoàn thành giáo dục lái xe?","o":["16 tuổi và 270 ngày","Đúng 16 tuổi","15 tuổi và 180 ngày","Đúng 18 tuổi"],"h1":"Đó là sau 16 tuổi, nhưng còn khá xa mới đến 17 tuổi rưỡi.","h2":"Ở Indiana, người lái không hoàn thành giáo dục lái xe phải ít nhất 16 tuổi và 270 ngày để lấy bằng lái thử thách.","p":"Đúng. Không học giáo dục lái xe thì phải 16 tuổi và 270 ngày."},"tl":{"q":"Sa Indiana, ilang taon ka dapat para makakuha ng probationary license kung hindi mo natapos ang driver education?","o":["16 na taon at 270 araw","Eksaktong 16 na taon","15 taon at 180 araw","Eksaktong 18 taon"],"h1":"Mas huli ito sa 16, pero malayo pa sa 17 at kalahati.","h2":"Sa Indiana, ang driver na hindi nakatapos ng driver education ay dapat hindi bababa sa 16 na taon at 270 araw para sa probationary license.","p":"Tama. Kapag walang driver education, 16 na taon at 270 araw."},"ar":{"q":"في Indiana، كم يجب أن يكون عمرك للحصول على الرخصة التجريبية إذا لم تُكمل دورة تعليم القيادة؟","o":["16 سنة و270 يومًا","16 سنة بالضبط","15 سنة و180 يومًا","18 سنة بالضبط"],"h1":"هو بعد 16 سنة، لكنه قبل 17 سنة ونصف بوقت طويل.","h2":"في Indiana يجب أن يكون عمر السائق الذي لم يُكمل دورة تعليم القيادة 16 سنة و270 يومًا على الأقل للحصول على الرخصة التجريبية.","p":"صحيح. دون دورة تعليم القيادة يكون العمر 16 سنة و270 يومًا."},"ref":{"doc":"IN","page":9}},{"id":"in-009","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you not drive?","o":["From midnight to 5 a.m.","From 10 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From 1 a.m. to 5 a.m."],"h1":"The limit starts at a late evening hour, before midnight.","h2":"In Indiana, for the first 180 days of a probationary license, you may not drive between 10 p.m. and 5 a.m.","p":"Right. No driving from 10 p.m. to 5 a.m. at first."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo no puede manejar?","o":["De medianoche a 5 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"En Indiana, durante los primeros 180 días de la licencia probatoria, usted no puede manejar entre las 10 p.m. y las 5 a.m.","p":"Correcto. Al principio no se maneja de 10 p.m. a 5 a.m."},"zh":{"q":"在 Indiana，拿到试用驾照的头 180 天里，什么时间不能开车？","o":["午夜到早上 5 点","晚上 10 点到早上 5 点","晚上 9 点到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"这个限制从晚上比较晚的时候开始，在午夜之前。","h2":"在 Indiana，拿到试用驾照的头 180 天里，你不能在晚上 10 点到早上 5 点之间开车。","p":"对。一开始，晚上 10 点到早上 5 点不能开车。"},"vi":{"q":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, khi nào bạn không được lái xe?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 10 giờ tối đến 5 giờ sáng","Từ 9 giờ tối đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu vào một giờ muộn buổi tối, trước nửa đêm.","h2":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, bạn không được lái xe từ 10 giờ tối đến 5 giờ sáng.","p":"Đúng. Lúc đầu không được lái từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Indiana, sa unang 180 araw ng probationary license, kailan ka hindi puwedeng magmaneho?","o":["Mula hatinggabi hanggang 5 a.m.","Mula 10 p.m. hanggang 5 a.m.","Mula 9 p.m. hanggang 6 a.m.","Mula 1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon sa isang huling oras ng gabi, bago mag-hatinggabi.","h2":"Sa Indiana, sa unang 180 araw ng probationary license, hindi ka puwedeng magmaneho mula 10 p.m. hanggang 5 a.m.","p":"Tama. Sa simula, bawal magmaneho mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، متى لا يُسمح لك بالقيادة؟","o":["من منتصف الليل حتى 5 صباحًا","من 10 مساءً حتى 5 صباحًا","من 9 مساءً حتى 6 صباحًا","من 1 صباحًا حتى 5 صباحًا"],"h1":"يبدأ المنع في ساعة متأخرة من المساء، قبل منتصف الليل.","h2":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، لا يُسمح لك بالقيادة من 10 مساءً حتى 5 صباحًا.","p":"صحيح. في البداية لا قيادة من 10 مساءً حتى 5 صباحًا."},"ref":{"doc":"IN","page":10}},{"id":"in-010","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when may you not drive on Saturday and Sunday mornings?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 1 a.m. to 5 a.m.","From midnight to 6 a.m."],"h1":"On weekend mornings, the limit starts after midnight.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive from 1 a.m. to 5 a.m. on Saturday and Sunday mornings.","p":"Correct. On weekend mornings, no driving from 1 a.m. to 5 a.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿cuándo no puede manejar los sábados y domingos en la madrugada?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Los fines de semana, el límite empieza después de la medianoche.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar de 1 a.m. a 5 a.m. los sábados y domingos en la madrugada.","p":"Correcto. Los fines de semana, no puede manejar de 1 a.m. a 5 a.m."},"zh":{"q":"在 Indiana，拿到试用驾照满 180 天以后、到 18 岁之前，星期六和星期天早上什么时间不能开车？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","午夜到早上 6 点"],"h1":"在周末的早上，这个限制在午夜以后才开始。","h2":"在 Indiana，满 180 天以后、到 18 岁之前，持试用驾照的司机在星期六和星期天早上的凌晨 1 点到早上 5 点不能开车。","p":"正确。周末早上，凌晨 1 点到早上 5 点不能开车。"},"vi":{"q":"Ở Indiana, sau 180 ngày đầu tiên của bằng lái thử thách và cho đến 18 tuổi, khi nào bạn không được lái xe vào sáng thứ Bảy và Chủ nhật?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng"],"h1":"Vào sáng cuối tuần, giới hạn bắt đầu sau nửa đêm.","h2":"Ở Indiana, sau 180 ngày đầu tiên và cho đến 18 tuổi, người lái có bằng thử thách không được lái xe từ 1 giờ sáng đến 5 giờ sáng vào sáng thứ Bảy và Chủ nhật.","p":"Đúng. Vào sáng cuối tuần, không được lái từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Indiana, pagkatapos ng unang 180 araw ng probationary license at hanggang 18, kailan ka hindi puwedeng magmaneho sa umaga ng Sabado at Linggo?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m."],"h1":"Sa umaga ng weekend, nagsisimula ang limitasyon pagkatapos ng hatinggabi.","h2":"Sa Indiana, pagkatapos ng unang 180 araw at hanggang 18, ang probationary driver ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. sa umaga ng Sabado at Linggo.","p":"Tama. Sa umaga ng weekend, bawal magmaneho mula 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Indiana، بعد أول 180 يومًا من الرخصة التجريبية وحتى عمر 18 سنة، متى لا يُسمح لك بالقيادة صباح يومي السبت والأحد؟","o":["من 10 مساءً حتى 5 صباحًا","من 11 مساءً حتى 5 صباحًا","من 1 صباحًا حتى 5 صباحًا","من منتصف الليل حتى 6 صباحًا"],"h1":"في صباح عطلة نهاية الأسبوع يبدأ المنع بعد منتصف الليل.","h2":"في Indiana، بعد أول 180 يومًا وحتى عمر 18 سنة، لا يُسمح لسائق الرخصة التجريبية بالقيادة من 1 صباحًا حتى 5 صباحًا صباح يومي السبت والأحد.","p":"صحيح. في صباح عطلة نهاية الأسبوع لا قيادة من 1 صباحًا حتى 5 صباحًا."},"ref":{"doc":"IN","page":10}},{"id":"in-011","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, after the first 180 days of a probationary license and until 18, when does the limit start on Sunday through Thursday nights?","o":["After 9 p.m.","After 10 p.m.","After 1 a.m.","After 11 p.m."],"h1":"It is one hour later than the limit in the first 180 days.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive after 11 p.m. on Sunday through Thursday nights.","p":"Right. On school nights, the limit is 11 p.m."},"es":{"q":"En Indiana, después de los primeros 180 días de la licencia probatoria y hasta los 18, ¿a qué hora empieza el límite las noches de domingo a jueves?","o":["Después de las 9 p.m.","Después de las 10 p.m.","Después de la 1 a.m.","Después de las 11 p.m."],"h1":"Es una hora más tarde que el límite de los primeros 180 días.","h2":"En Indiana, después de los primeros 180 días y hasta los 18, un conductor probatorio no puede manejar después de las 11 p.m. de domingo a jueves.","p":"Correcto. Entre semana, el límite es a las 11 p.m."},"zh":{"q":"在 Indiana，拿到试用驾照满 180 天以后、到 18 岁之前，星期天到星期四晚上的限制从几点开始？","o":["晚上 9 点以后","晚上 10 点以后","凌晨 1 点以后","晚上 11 点以后"],"h1":"比头 180 天的限制晚一个小时。","h2":"在 Indiana，满 180 天以后、到 18 岁之前，持试用驾照的司机在星期天到星期四晚上 11 点以后不能开车。","p":"对。第二天要上学的晚上，限制是晚上 11 点。"},"vi":{"q":"Ở Indiana, sau 180 ngày đầu tiên của bằng lái thử thách và cho đến 18 tuổi, giới hạn bắt đầu lúc nào vào các đêm từ Chủ nhật đến thứ Năm?","o":["Sau 9 giờ tối","Sau 10 giờ tối","Sau 1 giờ sáng","Sau 11 giờ tối"],"h1":"Đó là muộn hơn một giờ so với giới hạn trong 180 ngày đầu tiên.","h2":"Ở Indiana, sau 180 ngày đầu tiên và cho đến 18 tuổi, người lái có bằng thử thách không được lái xe sau 11 giờ tối vào các đêm từ Chủ nhật đến thứ Năm.","p":"Đúng. Vào các đêm trước ngày đi học, giới hạn là 11 giờ tối."},"tl":{"q":"Sa Indiana, pagkatapos ng unang 180 araw ng probationary license at hanggang 18, kailan nagsisimula ang limitasyon sa gabi ng Linggo hanggang Huwebes?","o":["Pagkalipas ng 9 p.m.","Pagkalipas ng 10 p.m.","Pagkalipas ng 1 a.m.","Pagkalipas ng 11 p.m."],"h1":"Isang oras itong mas huli kaysa sa limitasyon sa unang 180 araw.","h2":"Sa Indiana, pagkatapos ng unang 180 araw at hanggang 18, ang probationary driver ay hindi puwedeng magmaneho pagkalipas ng 11 p.m. sa gabi ng Linggo hanggang Huwebes.","p":"Tama. Sa mga gabi bago ang araw ng pasok, 11 p.m. ang limitasyon."},"ar":{"q":"في Indiana، بعد أول 180 يومًا من الرخصة التجريبية وحتى عمر 18 سنة، متى يبدأ المنع في ليالي الأحد حتى الخميس؟","o":["بعد 9 مساءً","بعد 10 مساءً","بعد 1 صباحًا","بعد 11 مساءً"],"h1":"هو متأخر بساعة واحدة عن المنع في أول 180 يومًا.","h2":"في Indiana، بعد أول 180 يومًا وحتى عمر 18 سنة، لا يُسمح لسائق الرخصة التجريبية بالقيادة بعد 11 مساءً في ليالي الأحد حتى الخميس.","p":"صحيح. في ليالي أيام الدراسة يبدأ المنع الساعة 11 مساءً."},"ref":{"doc":"IN","page":10}},{"id":"in-012","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, which trip is allowed during the probationary night limits?","o":["Driving to or from work","Driving to a friend's party","Driving to buy snacks","Driving around for fun"],"h1":"The exceptions are for duties, not for fun.","h2":"In Indiana a probationary driver may drive during the night limits to or from work, a school-sanctioned activity or a religious event.","p":"Correct. Work trips are an exception."},"es":{"q":"En Indiana, ¿qué viaje está permitido durante el límite nocturno de la licencia probatoria?","o":["Ir o volver del trabajo","Ir a la fiesta de un amigo","Ir a comprar algo de comer","Dar una vuelta por diversión"],"h1":"Las excepciones son para obligaciones, no para diversión.","h2":"En Indiana, un conductor probatorio puede manejar durante el límite nocturno para ir o volver del trabajo, de una actividad aprobada por la escuela o de un evento religioso.","p":"Correcto. Ir al trabajo es una excepción."},"zh":{"q":"在 Indiana，在试用驾照的夜间限制时间里，哪种出行是允许的？","o":["开车去上班或下班回家","开车去朋友的派对","开车去买零食","开车到处玩"],"h1":"例外是为了必须做的事，不是为了玩。","h2":"在 Indiana，持试用驾照的司机可以在夜间限制时间里开车去上班或下班回家，或者去参加学校批准的活动或宗教活动。","p":"正确。上下班是一个例外。"},"vi":{"q":"Ở Indiana, chuyến đi nào được phép trong giờ giới hạn ban đêm của bằng lái thử thách?","o":["Lái xe đi làm hoặc đi làm về","Lái xe đến tiệc của bạn bè","Lái xe đi mua đồ ăn vặt","Lái xe đi vòng vòng cho vui"],"h1":"Các ngoại lệ là cho bổn phận, không phải để vui chơi.","h2":"Ở Indiana, người lái có bằng thử thách được lái xe trong giờ giới hạn ban đêm để đi làm hoặc đi làm về, đi một hoạt động do trường cho phép, hoặc đi một sự kiện tôn giáo.","p":"Đúng. Chuyến đi làm là một ngoại lệ."},"tl":{"q":"Sa Indiana, aling biyahe ang pinapayagan sa oras ng limitasyon sa gabi para sa probationary driver?","o":["Pagmamaneho papunta o pauwi galing sa trabaho","Pagmamaneho papunta sa party ng kaibigan","Pagmamaneho para bumili ng meryenda","Pag-iikot-ikot para lang magsaya"],"h1":"Ang mga eksepsiyon ay para sa mga tungkulin, hindi para sa kasiyahan.","h2":"Sa Indiana, ang probationary driver ay puwedeng magmaneho sa oras ng limitasyon sa gabi papunta o pauwi galing sa trabaho, sa aktibidad na aprubado ng paaralan, o sa isang relihiyosong okasyon.","p":"Tama. Eksepsiyon ang biyahe para sa trabaho."},"ar":{"q":"في Indiana، أيّ رحلة مسموحة خلال ساعات المنع الليلي للرخصة التجريبية؟","o":["القيادة إلى العمل أو منه","القيادة إلى حفلة صديق","القيادة لشراء وجبات خفيفة","القيادة في جولة للتسلية"],"h1":"الاستثناءات للواجبات، لا للتسلية.","h2":"في Indiana يُسمح لسائق الرخصة التجريبية بالقيادة خلال ساعات المنع الليلي إلى العمل أو منه، أو إلى نشاط توافق عليه المدرسة، أو إلى مناسبة دينية.","p":"صحيح. رحلات العمل استثناء."},"ref":{"doc":"IN","page":10}},{"id":"in-013","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, during the first 180 days of a probationary license, when may you carry a friend as a passenger?","o":["Any time during the day","Only when a qualified adult, such as a licensed driver 25 or older, is in the front seat","Only on weekends","Only if the friend has a license"],"h1":"Think of the same adult who could supervise a learner.","h2":"In Indiana, for the first 180 days, a probationary driver may carry passengers only when a qualified adult, such as a licensed driver at least 25 or a spouse at least 21, is in the front seat; some close family members are allowed.","p":"Right. A qualified adult must be in the front seat."},"es":{"q":"En Indiana, durante los primeros 180 días de la licencia probatoria, ¿cuándo puede llevar a un amigo como pasajero?","o":["En cualquier momento de día","Solo cuando un adulto autorizado, como un conductor con licencia de 25 años o más, va en el asiento delantero","Solo los fines de semana","Solo si el amigo tiene licencia"],"h1":"Piense en el mismo adulto que puede supervisar a un aprendiz.","h2":"En Indiana, durante los primeros 180 días, un conductor probatorio solo puede llevar pasajeros si va en el asiento delantero un adulto autorizado, como un conductor con licencia de por lo menos 25 años o un cónyuge de por lo menos 21; algunos familiares cercanos sí están permitidos.","p":"Correcto. Un adulto autorizado debe ir adelante."},"zh":{"q":"在 Indiana，拿到试用驾照的头 180 天里，什么时候可以载朋友当乘客？","o":["白天任何时间","只有当一位合格的成年人（例如 25 岁或以上、有驾照的司机）坐在前排时","只能在周末","只有当朋友有驾照时"],"h1":"想一想可以陪同学习驾驶的那位成年人。","h2":"在 Indiana，头 180 天里，持试用驾照的司机只有在一位合格的成年人坐在前排时才能载乘客，例如至少 25 岁、有驾照的司机，或至少 21 岁的配偶；有些近亲也可以坐车。","p":"对。前排必须坐着一位合格的成年人。"},"vi":{"q":"Ở Indiana, trong 180 ngày đầu tiên của bằng lái thử thách, khi nào bạn được chở một người bạn?","o":["Bất cứ lúc nào vào ban ngày","Chỉ khi có một người lớn đủ điều kiện, như người có bằng lái từ 25 tuổi trở lên, ngồi ở ghế trước","Chỉ vào cuối tuần","Chỉ khi người bạn có bằng lái"],"h1":"Hãy nghĩ đến chính người lớn có thể giám sát người tập lái.","h2":"Ở Indiana, trong 180 ngày đầu tiên, người lái có bằng thử thách chỉ được chở hành khách khi có một người lớn đủ điều kiện, như người có bằng lái ít nhất 25 tuổi hoặc vợ hay chồng ít nhất 21 tuổi, ngồi ở ghế trước; một số người thân trong gia đình gần gũi được phép.","p":"Đúng. Một người lớn đủ điều kiện phải ngồi ở ghế trước."},"tl":{"q":"Sa Indiana, sa unang 180 araw ng probationary license, kailan ka puwedeng magsakay ng kaibigan bilang pasahero?","o":["Kahit anong oras sa araw","Kapag may kuwalipikadong adult lang, gaya ng driver na may lisensya na 25 o mas matanda, sa upuan sa harap","Tuwing weekend lang","Kung may lisensya lang ang kaibigan"],"h1":"Isipin ang parehong adult na puwedeng magbantay sa isang learner.","h2":"Sa Indiana, sa unang 180 araw, ang probationary driver ay puwedeng magsakay ng pasahero kapag may kuwalipikadong adult lang, gaya ng driver na may lisensya na hindi bababa sa 25 o asawang hindi bababa sa 21, sa upuan sa harap; pinapayagan ang ilang malapit na kapamilya.","p":"Tama. Dapat may kuwalipikadong adult sa upuan sa harap."},"ar":{"q":"في Indiana، خلال أول 180 يومًا من الرخصة التجريبية، متى يُسمح لك بأن تُركب صديقًا معك كراكب؟","o":["في أي وقت خلال النهار","فقط عندما يجلس في المقعد الأمامي شخص بالغ مؤهَّل، مثل سائق مرخّص عمره 25 سنة أو أكثر","في عطلة نهاية الأسبوع فقط","فقط إذا كان الصديق يحمل رخصة"],"h1":"فكّر في الشخص البالغ نفسه الذي يمكنه الإشراف على المتعلّم.","h2":"في Indiana، خلال أول 180 يومًا، يمكن لسائق الرخصة التجريبية أن يُركب ركابًا فقط عندما يجلس في المقعد الأمامي شخص بالغ مؤهَّل، مثل سائق مرخّص عمره 25 سنة على الأقل أو زوج أو زوجة عمره 21 سنة على الأقل؛ ويُسمح ببعض أفراد العائلة المقرّبين.","p":"صحيح. يجب أن يجلس شخص بالغ مؤهَّل في المقعد الأمامي."},"ref":{"doc":"IN","page":10}},{"id":"in-014","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, when does a probationary driver's license expire?","o":["On your 18th birthday","One year after it is issued","30 days after your 21st birthday","On your 25th birthday"],"h1":"It lasts until a little after you can legally drink.","h2":"In Indiana a probationary driver's license expires 30 days after your 21st birthday, and the renewed license has no probationary limits.","p":"Correct. It ends 30 days after you turn 21."},"es":{"q":"En Indiana, ¿cuándo vence la licencia probatoria?","o":["Al cumplir 18 años","Un año después de recibirla","30 días después de cumplir 21 años","Al cumplir 25 años"],"h1":"Dura hasta poco después de la edad legal para tomar alcohol.","h2":"En Indiana la licencia probatoria vence 30 días después de que usted cumple 21 años, y la licencia renovada ya no tiene límites probatorios.","p":"Correcto. Vence 30 días después de cumplir 21."},"zh":{"q":"在 Indiana，试用驾照什么时候到期？","o":["在你 18 岁生日那天","发证一年以后","在你 21 岁生日后 30 天","在你 25 岁生日那天"],"h1":"它一直有效到你可以合法喝酒以后不久。","h2":"在 Indiana，试用驾照在你 21 岁生日后 30 天到期，换新的驾照就没有试用期的限制了。","p":"正确。它在你满 21 岁后 30 天结束。"},"vi":{"q":"Ở Indiana, bằng lái thử thách hết hạn khi nào?","o":["Vào sinh nhật 18 tuổi của bạn","Một năm sau khi được cấp","30 ngày sau sinh nhật 21 tuổi của bạn","Vào sinh nhật 25 tuổi của bạn"],"h1":"Nó kéo dài đến sau tuổi được phép uống rượu một chút.","h2":"Ở Indiana, bằng lái thử thách hết hạn 30 ngày sau sinh nhật 21 tuổi của bạn, và bằng lái được gia hạn không còn giới hạn thử thách.","p":"Đúng. Nó hết hạn 30 ngày sau khi bạn tròn 21 tuổi."},"tl":{"q":"Sa Indiana, kailan mag-e-expire ang probationary driver's license?","o":["Sa ika-18 kaarawan mo","Isang taon pagkatapos itong ibigay","30 araw pagkatapos ng ika-21 kaarawan mo","Sa ika-25 kaarawan mo"],"h1":"Tumatagal ito nang kaunti pagkatapos ng edad na legal nang uminom ng alak.","h2":"Sa Indiana, mag-e-expire ang probationary driver's license 30 araw pagkatapos ng ika-21 kaarawan mo, at ang nire-renew na lisensya ay wala nang probationary na limitasyon.","p":"Tama. Natatapos ito 30 araw pagkatapos mong mag-21."},"ar":{"q":"في Indiana، متى تنتهي صلاحية رخصة القيادة التجريبية؟","o":["في عيد ميلادك الـ 18","بعد سنة من إصدارها","بعد 30 يومًا من عيد ميلادك الـ 21","في عيد ميلادك الـ 25"],"h1":"تستمر حتى ما بعد العمر الذي يُسمح فيه قانونيًا بشرب الكحول بقليل.","h2":"في Indiana تنتهي صلاحية رخصة القيادة التجريبية بعد 30 يومًا من عيد ميلادك الـ 21، والرخصة المجدَّدة ليس فيها قيود تجريبية.","p":"صحيح. تنتهي بعد 30 يومًا من بلوغك 21 سنة."},"ref":{"doc":"IN","page":10}},{"id":"in-015","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, when may a probationary driver use a phone or other device while driving?","o":["Any time, if it is hands-free","Only at red lights","Only to use a map app","Only to call 911 in an emergency"],"h1":"There is only one exception, and it is for emergencies.","h2":"In Indiana a probationary driver may not use any telecommunication device while driving, even hands-free, except to call 911 in an emergency.","p":"Right. Only an emergency 911 call is allowed."},"es":{"q":"En Indiana, ¿cuándo puede un conductor probatorio usar un teléfono u otro aparato mientras maneja?","o":["En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para usar un mapa","Solo para llamar al 911 en una emergencia"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Indiana, un conductor probatorio no puede usar ningún aparato de telecomunicación mientras maneja, ni siquiera manos libres, salvo para llamar al 911 en una emergencia.","p":"Correcto. Solo se permite una llamada de emergencia al 911."},"zh":{"q":"在 Indiana，持试用驾照的司机开车时什么时候可以用手机或其他设备？","o":["任何时候，只要是免提","只能在红灯时","只能用地图软件","只能在紧急情况下打 911"],"h1":"只有一个例外，而且是为了紧急情况。","h2":"在 Indiana，持试用驾照的司机开车时不能使用任何通讯设备，免提也不行，只有在紧急情况下打 911 除外。","p":"对。只允许在紧急情况下打 911。"},"vi":{"q":"Ở Indiana, khi nào người lái có bằng thử thách được dùng điện thoại hoặc thiết bị khác trong lúc lái xe?","o":["Bất cứ lúc nào, nếu không cầm tay (hands-free)","Chỉ khi dừng đèn đỏ","Chỉ để dùng ứng dụng bản đồ","Chỉ để gọi 911 khi khẩn cấp"],"h1":"Chỉ có một ngoại lệ, và đó là cho trường hợp khẩn cấp.","h2":"Ở Indiana, người lái có bằng thử thách không được dùng bất kỳ thiết bị viễn thông nào khi lái xe, kể cả không cầm tay, trừ khi gọi 911 trong trường hợp khẩn cấp.","p":"Đúng. Chỉ được gọi 911 khi khẩn cấp."},"tl":{"q":"Sa Indiana, kailan puwedeng gumamit ng telepono o ibang device ang probationary driver habang nagmamaneho?","o":["Kahit kailan, kung hands-free","Sa red light lang","Para lang gumamit ng map app","Para lang tumawag sa 911 kapag emergency"],"h1":"Iisa lang ang eksepsiyon, at para ito sa emergency.","h2":"Sa Indiana, ang probationary driver ay hindi puwedeng gumamit ng kahit anong telecommunication device habang nagmamaneho, kahit hands-free, maliban kung tatawag sa 911 kapag emergency.","p":"Tama. Ang tawag lang sa 911 kapag emergency ang pinapayagan."},"ar":{"q":"في Indiana، متى يُسمح لسائق الرخصة التجريبية باستخدام الهاتف أو جهاز آخر أثناء القيادة؟","o":["في أي وقت، إذا كان دون استخدام اليدين (hands-free)","عند الإشارة الحمراء فقط","لاستخدام تطبيق الخرائط فقط","للاتصال بـ 911 في حالة الطوارئ فقط"],"h1":"هناك استثناء واحد فقط، وهو لحالات الطوارئ.","h2":"في Indiana لا يُسمح لسائق الرخصة التجريبية باستخدام أي جهاز اتصال أثناء القيادة، حتى دون استخدام اليدين، إلا للاتصال بـ 911 في حالة الطوارئ.","p":"صحيح. يُسمح فقط بالاتصال بـ 911 في الطوارئ."},"ref":{"doc":"IN","page":10}},{"id":"in-016","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, what does the hands-free law say about all drivers and their phones?","o":["You may not hold a phone in your hand while driving","You may hold a phone below the window","You may text at speeds under 25 mph","Only drivers under 18 must be hands-free"],"h1":"The law's name tells you where your hands should be.","h2":"In Indiana no driver may hold a phone or tablet in their hand while driving; hands-free use such as Bluetooth or a speakerphone is allowed.","p":"Correct. Indiana drivers must stay hands-free."},"es":{"q":"En Indiana, ¿qué dice la ley de manos libres sobre todos los conductores y sus teléfonos?","o":["No puede tener el teléfono en la mano mientras maneja","Puede tener el teléfono debajo de la ventana","Puede enviar mensajes a menos de 25 mph","Solo los menores de 18 deben usar manos libres"],"h1":"El nombre de la ley le dice dónde deben estar sus manos.","h2":"En Indiana ningún conductor puede tener un teléfono o tableta en la mano mientras maneja; se permite el uso manos libres, como Bluetooth o altavoz.","p":"Correcto. En Indiana se maneja con manos libres."},"zh":{"q":"在 Indiana，免提法对所有司机和他们的手机有什么规定？","o":["开车时你不能手里拿着手机","你可以把手机拿在车窗下面","速度低于 25 mph 时你可以发短信","只有 18 岁以下的司机必须用免提"],"h1":"这条法律的名字告诉你，你的手应该在哪里。","h2":"在 Indiana，任何司机开车时都不能手里拿着手机或平板电脑；可以用免提方式，例如蓝牙或扬声器。","p":"正确。Indiana 的司机必须用免提。"},"vi":{"q":"Ở Indiana, luật không cầm tay (hands-free law) nói gì về tất cả người lái xe và điện thoại của họ?","o":["Bạn không được cầm điện thoại trong tay khi lái xe","Bạn được cầm điện thoại thấp hơn cửa sổ","Bạn được nhắn tin khi chạy dưới 25 mph","Chỉ người lái dưới 18 tuổi mới phải không cầm tay"],"h1":"Tên của luật cho bạn biết tay bạn nên ở đâu.","h2":"Ở Indiana, không người lái nào được cầm điện thoại hoặc máy tính bảng trong tay khi lái xe; được phép dùng không cầm tay như Bluetooth hoặc loa ngoài.","p":"Đúng. Người lái ở Indiana phải dùng không cầm tay."},"tl":{"q":"Sa Indiana, ano ang sinasabi ng hands-free law tungkol sa lahat ng driver at sa kanilang telepono?","o":["Hindi mo puwedeng hawakan ang telepono sa kamay habang nagmamaneho","Puwede mong hawakan ang telepono sa ibaba ng bintana","Puwede kang mag-text kapag mas mabagal sa 25 mph","Ang mga driver lang na wala pang 18 ang dapat hands-free"],"h1":"Sinasabi ng pangalan ng batas kung nasaan dapat ang mga kamay mo.","h2":"Sa Indiana, walang driver na puwedeng humawak ng telepono o tablet sa kamay habang nagmamaneho; pinapayagan ang hands-free na paggamit gaya ng Bluetooth o speakerphone.","p":"Tama. Dapat hands-free ang mga driver sa Indiana."},"ar":{"q":"في Indiana، ماذا يقول قانون عدم استخدام اليدين (hands-free law) عن جميع السائقين وهواتفهم؟","o":["لا يُسمح لك بحمل الهاتف بيدك أثناء القيادة","يُسمح لك بحمل الهاتف تحت مستوى النافذة","يُسمح لك بكتابة الرسائل عندما تكون سرعتك أقل من 25 mph","السائقون الذين عمرهم أقل من 18 سنة فقط يجب ألا يستخدموا اليدين"],"h1":"اسم القانون يخبرك أين يجب أن تكون يداك.","h2":"في Indiana لا يُسمح لأي سائق بحمل هاتف أو جهاز لوحي بيده أثناء القيادة؛ ويُسمح بالاستخدام دون اليدين مثل Bluetooth أو مكبّر الصوت.","p":"صحيح. يجب أن يقود السائقون في Indiana دون استخدام اليدين للهاتف."},"ref":{"doc":"IN","page":45}},{"id":"in-017","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what score do you need on the knowledge exam?","o":["70 percent on the whole test","80 percent or higher on each section","60 percent on each section","100 percent on the signs section"],"h1":"There are two sections, and each must be passed on its own.","h2":"In Indiana you must answer at least 80 percent correctly on each section of the knowledge exam to pass.","p":"Right. You need 80 percent on each section."},"es":{"q":"En Indiana, ¿qué calificación necesita en el examen de conocimientos?","o":["70 por ciento en todo el examen","80 por ciento o más en cada sección","60 por ciento en cada sección","100 por ciento en la sección de señales"],"h1":"Hay dos secciones, y cada una se aprueba por separado.","h2":"En Indiana usted debe contestar bien por lo menos el 80 por ciento de cada sección del examen de conocimientos para aprobar.","p":"Correcto. Se necesita 80 por ciento en cada sección."},"zh":{"q":"在 Indiana，笔试需要考多少分？","o":["整个考试 70%","每个部分 80% 或更高","每个部分 60%","标志部分 100%"],"h1":"考试有两个部分，每个部分都要分别通过。","h2":"在 Indiana，笔试的每个部分你都必须答对至少 80% 才能通过。","p":"对。每个部分都需要 80%。"},"vi":{"q":"Ở Indiana, bạn cần bao nhiêu điểm trong bài thi kiến thức?","o":["70 phần trăm trên toàn bài thi","80 phần trăm trở lên ở mỗi phần","60 phần trăm ở mỗi phần","100 phần trăm ở phần biển báo"],"h1":"Có hai phần, và mỗi phần phải đậu riêng.","h2":"Ở Indiana, bạn phải trả lời đúng ít nhất 80 phần trăm ở mỗi phần của bài thi kiến thức để đậu.","p":"Đúng. Bạn cần 80 phần trăm ở mỗi phần."},"tl":{"q":"Sa Indiana, anong score ang kailangan mo sa knowledge exam?","o":["70 porsiyento sa buong test","80 porsiyento o higit pa sa bawat bahagi","60 porsiyento sa bawat bahagi","100 porsiyento sa bahagi ng mga karatula"],"h1":"May dalawang bahagi, at dapat maipasa ang bawat isa nang hiwalay.","h2":"Sa Indiana, dapat tama ang hindi bababa sa 80 porsiyento ng sagot mo sa bawat bahagi ng knowledge exam para pumasa.","p":"Tama. Kailangan mo ng 80 porsiyento sa bawat bahagi."},"ar":{"q":"في Indiana، ما الدرجة التي تحتاجها في امتحان المعرفة (knowledge exam)؟","o":["70 بالمئة في الامتحان كله","80 بالمئة أو أكثر في كل قسم","60 بالمئة في كل قسم","100 بالمئة في قسم الإشارات"],"h1":"هناك قسمان، ويجب النجاح في كل واحد منهما وحده.","h2":"في Indiana يجب أن تجيب إجابة صحيحة عن 80 بالمئة على الأقل في كل قسم من امتحان المعرفة لكي تنجح.","p":"صحيح. تحتاج إلى 80 بالمئة في كل قسم."},"ref":{"doc":"IN","page":63}},{"id":"in-018","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what two sections make up the knowledge exam?","o":["Vehicle repair and first aid","Parking and car insurance","Traffic rules and traffic signs","Night driving and map reading"],"h1":"One part is about what to do, the other about what you see beside the road.","h2":"In Indiana the knowledge exam has one section on traffic rules and driving maneuvers and one section on traffic signs.","p":"Correct. Rules and signs are the two sections."},"es":{"q":"En Indiana, ¿cuáles son las dos secciones del examen de conocimientos?","o":["Reparación de vehículos y primeros auxilios","Estacionamiento y seguro de auto","Reglas de tránsito y señales de tránsito","Manejo nocturno y lectura de mapas"],"h1":"Una parte trata de qué hacer, y la otra de lo que ve al lado del camino.","h2":"En Indiana el examen de conocimientos tiene una sección sobre reglas de tránsito y maniobras, y otra sobre señales de tránsito.","p":"Correcto. Reglas y señales son las dos secciones."},"zh":{"q":"在 Indiana，笔试由哪两个部分组成？","o":["汽车维修和急救","停车和汽车保险","交通规则和交通标志","夜间驾驶和看地图"],"h1":"一部分是关于要怎么做，另一部分是关于你在路边看到的东西。","h2":"在 Indiana，笔试有一个部分考交通规则和驾驶操作，另一个部分考交通标志。","p":"正确。规则和标志是两个部分。"},"vi":{"q":"Ở Indiana, bài thi kiến thức gồm hai phần nào?","o":["Sửa xe và sơ cứu","Đậu xe và bảo hiểm xe","Luật giao thông và biển báo giao thông","Lái xe ban đêm và đọc bản đồ"],"h1":"Một phần nói về việc phải làm gì, phần kia nói về những gì bạn thấy bên đường.","h2":"Ở Indiana, bài thi kiến thức có một phần về luật giao thông và cách lái xe, và một phần về biển báo giao thông.","p":"Đúng. Luật và biển báo là hai phần."},"tl":{"q":"Sa Indiana, anong dalawang bahagi ang bumubuo sa knowledge exam?","o":["Pagkumpuni ng sasakyan at first aid","Pagparada at insurance ng sasakyan","Mga patakaran sa trapiko at mga karatula sa trapiko","Pagmamaneho sa gabi at pagbasa ng mapa"],"h1":"Ang isang bahagi ay tungkol sa dapat gawin, ang isa naman ay tungkol sa nakikita mo sa tabi ng daan.","h2":"Sa Indiana, ang knowledge exam ay may isang bahagi tungkol sa mga patakaran sa trapiko at paraan ng pagmamaneho, at isang bahagi tungkol sa mga karatula sa trapiko.","p":"Tama. Patakaran at karatula ang dalawang bahagi."},"ar":{"q":"في Indiana، ما القسمان اللذان يتكوّن منهما امتحان المعرفة؟","o":["إصلاح السيارات والإسعافات الأولية","ركن السيارة وتأمين السيارة","قواعد المرور وإشارات المرور","القيادة الليلية وقراءة الخرائط"],"h1":"قسم عمّا يجب أن تفعله، والآخر عمّا تراه بجانب الطريق.","h2":"في Indiana يتكوّن امتحان المعرفة من قسم عن قواعد المرور وطرق القيادة، وقسم عن إشارات المرور.","p":"صحيح. القواعد والإشارات هما القسمان."},"ref":{"doc":"IN","page":63}},{"id":"in-019","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a 15-year-old in driver education may practice with a parent only after finishing how much of the classroom or online part?","o":["5 hours","10 hours","50 hours","30 hours"],"h1":"It is the same number as the days in most months.","h2":"In Indiana a 15-year-old in driver education must finish 30 hours of the classroom or online part before practicing with a parent or other supervisor.","p":"Right. Thirty hours of classroom or online work come first."},"es":{"q":"En Indiana, un joven de 15 años en educación vial puede practicar con un padre solo después de terminar ¿cuánto de la parte en clase o en línea?","o":["5 horas","10 horas","50 horas","30 horas"],"h1":"Es el mismo número que los días de casi todos los meses.","h2":"En Indiana, un joven de 15 años en educación vial debe terminar 30 horas de la parte en clase o en línea antes de practicar con un padre u otro supervisor.","p":"Correcto. Primero vienen 30 horas de clase o en línea."},"zh":{"q":"在 Indiana，上驾驶课的 15 岁学生，要完成课堂或网上部分的多少，才能和父母一起练车？","o":["5 小时","10 小时","50 小时","30 小时"],"h1":"和大多数月份的天数一样。","h2":"在 Indiana，上驾驶课的 15 岁学生必须先完成 30 小时课堂或网上部分，才能和父母或其他陪同者练车。","p":"对。先完成三十个小时的课堂或网上学习。"},"vi":{"q":"Ở Indiana, một người 15 tuổi đang học giáo dục lái xe chỉ được tập lái với cha mẹ sau khi học xong bao nhiêu giờ phần lớp học hoặc phần trực tuyến?","o":["5 giờ","10 giờ","50 giờ","30 giờ"],"h1":"Đó là bằng số ngày trong hầu hết các tháng.","h2":"Ở Indiana, một người 15 tuổi đang học giáo dục lái xe phải học xong 30 giờ phần lớp học hoặc trực tuyến trước khi tập lái với cha mẹ hoặc người giám sát khác.","p":"Đúng. Phải học xong 30 giờ lớp học hoặc trực tuyến trước."},"tl":{"q":"Sa Indiana, ang 15 taong gulang na nasa driver education ay puwedeng mag-ensayo kasama ang magulang pagkatapos lang matapos ang ilang oras ng bahagi sa classroom o online?","o":["5 oras","10 oras","50 oras","30 oras"],"h1":"Kapareho ito ng bilang ng araw sa karamihan ng buwan.","h2":"Sa Indiana, ang 15 taong gulang na nasa driver education ay dapat matapos ang 30 oras ng bahagi sa classroom o online bago mag-ensayo kasama ang magulang o ibang tagabantay.","p":"Tama. Unang tatapusin ang 30 oras sa classroom o online."},"ar":{"q":"في Indiana، يمكن لشخص عمره 15 سنة في دورة تعليم القيادة أن يتدرّب مع أحد الوالدين فقط بعد إنهاء كم من الجزء الصفّي أو الجزء عبر الإنترنت؟","o":["5 ساعات","10 ساعات","50 ساعة","30 ساعة"],"h1":"هو نفس عدد الأيام في معظم الشهور.","h2":"في Indiana يجب على من عمره 15 سنة في دورة تعليم القيادة أن يُنهي 30 ساعة من الجزء الصفّي أو الجزء عبر الإنترنت قبل التدرّب مع أحد الوالدين أو مشرف آخر.","p":"صحيح. تأتي أولًا 30 ساعة من الدراسة في الصف أو عبر الإنترنت."},"ref":{"doc":"IN","page":null}},{"id":"in-020","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, you approach a stopped tow truck with amber flashing lights and you cannot safely change lanes. What must you do?","o":["Slow to 10 mph below the speed limit","Keep your speed and honk","Slow to 5 mph below the speed limit","Stop completely in your lane"],"h1":"Indiana sets a number below the posted limit.","h2":"In Indiana, if you cannot move away from a stopped vehicle with flashing lights, you must slow to 10 mph below the speed limit and drive with caution.","p":"Correct. Slow down by 10 mph."},"es":{"q":"En Indiana, se acerca a una grúa detenida con luces ámbar intermitentes y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Bajar a 10 mph menos que el límite de velocidad","Mantener la velocidad y tocar la bocina","Bajar a 5 mph menos que el límite","Detenerse por completo en su carril"],"h1":"Indiana fija un número por debajo del límite.","h2":"En Indiana, si no puede alejarse de un vehículo detenido con luces intermitentes, debe bajar a 10 mph menos que el límite de velocidad y manejar con cuidado.","p":"Correcto. Baje 10 mph."},"zh":{"q":"在 Indiana，你靠近一辆停着、闪着琥珀色灯的拖车，而且你不能安全换道。你必须做什么？","o":["减速到比限速低 10 mph","保持速度并按喇叭","减速到比限速低 5 mph","在你的车道上完全停下"],"h1":"Indiana 规定了比标示限速低的一个数字。","h2":"在 Indiana，如果你不能离开停着、闪着灯的车辆，就必须减速到比限速低 10 mph，并小心驾驶。","p":"正确。减速 10 mph。"},"vi":{"q":"Ở Indiana, bạn đến gần một xe kéo đang dừng có đèn nhấp nháy màu vàng cam và bạn không thể đổi làn an toàn. Bạn phải làm gì?","o":["Giảm tốc độ xuống thấp hơn tốc độ giới hạn 10 mph","Giữ nguyên tốc độ và bấm còi","Giảm tốc độ xuống thấp hơn tốc độ giới hạn 5 mph","Dừng hẳn trong làn của bạn"],"h1":"Indiana quy định một con số thấp hơn tốc độ giới hạn được ghi trên biển.","h2":"Ở Indiana, nếu bạn không thể tránh xa một xe đang dừng có đèn nhấp nháy, bạn phải giảm tốc độ xuống thấp hơn tốc độ giới hạn 10 mph và lái xe cẩn thận.","p":"Đúng. Giảm tốc độ 10 mph."},"tl":{"q":"Sa Indiana, papalapit ka sa nakahintong tow truck na may kumikislap na amber na ilaw at hindi ka ligtas na makalipat ng lane. Ano ang dapat mong gawin?","o":["Bumagal hanggang 10 mph na mas mababa sa speed limit","Panatilihin ang bilis at bumusina","Bumagal hanggang 5 mph na mas mababa sa speed limit","Huminto nang tuluyan sa lane mo"],"h1":"May itinakdang numero ang Indiana na mas mababa sa nakapaskil na limit.","h2":"Sa Indiana, kung hindi ka makakalayo sa nakahintong sasakyan na may kumikislap na ilaw, dapat kang bumagal hanggang 10 mph na mas mababa sa speed limit at magmaneho nang maingat.","p":"Tama. Bumagal nang 10 mph."},"ar":{"q":"في Indiana، تقترب من شاحنة سحب متوقفة أضواؤها الكهرمانية تومض، ولا يمكنك تغيير المسار بأمان. ماذا يجب أن تفعل؟","o":["خفّف السرعة إلى 10 mph أقل من الحد الأقصى للسرعة","حافظ على سرعتك واستخدم البوق","خفّف السرعة إلى 5 mph أقل من الحد الأقصى للسرعة","توقّف تمامًا في مسارك"],"h1":"تحدّد Indiana رقمًا أقل من الحد المكتوب على اللافتة.","h2":"في Indiana، إذا لم تستطع الابتعاد عن مركبة متوقفة أضواؤها تومض، يجب أن تخفّف السرعة إلى 10 mph أقل من الحد الأقصى للسرعة وتقود بحذر.","p":"صحيح. خفّف السرعة بمقدار 10 mph."},"ref":{"doc":"IN","page":51}},{"id":"in-021","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, a school bus is stopped with its stop arm out on the other side of a road divided by a barrier or an unpaved median. What must you do?","o":["Stop and wait until the bus moves","You do not have to stop, but you must drive with care","Stop only if children are visible","Stop and then pass at 10 mph"],"h1":"The median or barrier separates you from the bus.","h2":"In Indiana you do not need to stop for a school bus on the other side of a road divided by a barrier or an unpaved median, but you must drive with care.","p":"Right. The divided highway lets you continue carefully."},"es":{"q":"En Indiana, un autobús escolar está detenido con el brazo de alto extendido al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar. ¿Qué debe hacer?","o":["Detenerse y esperar a que el autobús avance","No tiene que detenerse, pero debe manejar con cuidado","Detenerse solo si ve niños","Detenerse y luego pasar a 10 mph"],"h1":"La mediana o barrera lo separa del autobús.","h2":"En Indiana usted no tiene que detenerse por un autobús escolar al otro lado de una carretera dividida por una barrera o una mediana sin pavimentar, pero debe manejar con cuidado.","p":"Correcto. La carretera dividida le permite seguir con cuidado."},"zh":{"q":"在 Indiana，一辆校车伸出停车臂，停在被隔离墩或没铺路面的隔离带分开的道路另一边。你必须做什么？","o":["停车，等到校车开走","你不用停车，但必须小心驾驶","只有看到小孩时才停车","停车，然后以 10 mph 开过去"],"h1":"隔离带或隔离墩把你和校车分开了。","h2":"在 Indiana，校车在被隔离墩或没铺路面的隔离带分开的道路另一边时，你不用停车，但必须小心驾驶。","p":"对。在分隔公路上，你可以小心地继续开。"},"vi":{"q":"Ở Indiana, một xe buýt trường học đang dừng và giơ cần báo dừng (stop arm) ở phía bên kia của một con đường được ngăn cách bằng rào chắn hoặc dải phân cách không trải nhựa. Bạn phải làm gì?","o":["Dừng lại và chờ đến khi xe buýt chạy","Bạn không phải dừng, nhưng phải lái xe cẩn thận","Chỉ dừng nếu thấy trẻ em","Dừng lại rồi vượt qua với tốc độ 10 mph"],"h1":"Dải phân cách hoặc rào chắn ngăn cách bạn với xe buýt.","h2":"Ở Indiana, bạn không cần dừng lại cho xe buýt trường học ở phía bên kia của con đường được ngăn cách bằng rào chắn hoặc dải phân cách không trải nhựa, nhưng bạn phải lái xe cẩn thận.","p":"Đúng. Đường có phân cách cho phép bạn tiếp tục chạy một cách cẩn thận."},"tl":{"q":"Sa Indiana, may school bus na nakahinto at nakalabas ang stop arm sa kabilang panig ng daan na hinahati ng harang o ng median na hindi sementado. Ano ang dapat mong gawin?","o":["Huminto at maghintay hanggang umandar ang bus","Hindi mo kailangang huminto, pero dapat kang magmaneho nang maingat","Huminto lang kung may nakikitang mga bata","Huminto at saka lumampas sa 10 mph"],"h1":"Hinihiwalay ka ng median o harang mula sa bus.","h2":"Sa Indiana, hindi mo kailangang huminto para sa school bus sa kabilang panig ng daan na hinahati ng harang o ng median na hindi sementado, pero dapat kang magmaneho nang maingat.","p":"Tama. Sa hinating daan, puwede kang magpatuloy nang maingat."},"ar":{"q":"في Indiana، حافلة مدرسية متوقفة وذراع التوقف (stop arm) ممدود، على الجهة الأخرى من طريق مقسوم بحاجز أو بجزيرة وسطية غير معبّدة. ماذا يجب أن تفعل؟","o":["توقّف وانتظر حتى تتحرك الحافلة","ليس عليك أن تتوقف، لكن يجب أن تقود بحذر","توقّف فقط إذا رأيت أطفالًا","توقّف ثم تجاوز بسرعة 10 mph"],"h1":"الجزيرة الوسطية أو الحاجز يفصلك عن الحافلة.","h2":"في Indiana لا تحتاج إلى التوقف لحافلة مدرسية على الجهة الأخرى من طريق مقسوم بحاجز أو بجزيرة وسطية غير معبّدة، لكن يجب أن تقود بحذر.","p":"صحيح. الطريق المقسوم يسمح لك بالمتابعة بحذر."},"ref":{"doc":"IN","page":52}},{"id":"in-022","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, what blood alcohol level breaks the law for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Indiana a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. For drivers under 21 the limit is 0.02."},"es":{"q":"En Indiana, ¿qué nivel de alcohol en la sangre viola la ley para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Indiana, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Indiana，对 21 岁以下的司机来说，血液酒精浓度多少就违法？","o":["0.08 或更高","0.05 或更高","0.02 或更高","0.10 或更高"],"h1":"这比成年人的上限低很多。","h2":"在 Indiana，21 岁以下的司机血液酒精浓度达到 0.02 或更高就是违法。","p":"正确。21 岁以下的司机，上限是 0.02。"},"vi":{"q":"Ở Indiana, nồng độ cồn trong máu bao nhiêu là phạm luật đối với người lái dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Indiana, người lái dưới 21 tuổi phạm luật nếu nồng độ cồn trong máu là 0.02 trở lên.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Indiana, anong antas ng alak sa dugo ang labag sa batas para sa driver na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Indiana, lumalabag sa batas ang driver na wala pang 21 kapag ang antas ng alak sa dugo niya ay 0.02 o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, 0.02 ang limit."},"ar":{"q":"في Indiana، ما نسبة الكحول في الدم التي تُعدّ مخالفة للقانون للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Indiana يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 سنة الحد هو 0.02."},"ref":{"doc":"IN","page":null}},{"id":"in-023","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how long is a learner's permit valid?","o":["6 months","Two years","One year","Until you turn 18"],"h1":"It lasts longer than the time you must hold it before a license.","h2":"In Indiana a learner's permit is valid for two years from the day it is issued.","p":"Right. A learner's permit lasts two years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses","Dos años","Un año","Hasta que cumpla 18 años"],"h1":"Dura más que el tiempo que debe tenerlo antes de la licencia.","h2":"En Indiana el permiso de aprendizaje es válido por dos años desde el día en que se emite.","p":"Correcto. El permiso de aprendizaje dura dos años."},"zh":{"q":"在 Indiana，学习驾照（learner's permit）的有效期是多久？","o":["6 个月","两年","一年","到你满 18 岁为止"],"h1":"它比你拿驾照前必须持有它的时间更长。","h2":"在 Indiana，学习驾照从发放那天起有效两年。","p":"对。学习驾照有效两年。"},"vi":{"q":"Ở Indiana, giấy phép tập lái (learner's permit) có giá trị trong bao lâu?","o":["6 tháng","Hai năm","Một năm","Cho đến khi bạn 18 tuổi"],"h1":"Nó lâu hơn thời gian bạn phải giữ nó trước khi lấy bằng lái.","h2":"Ở Indiana, giấy phép tập lái có giá trị hai năm kể từ ngày được cấp.","p":"Đúng. Giấy phép tập lái có giá trị hai năm."},"tl":{"q":"Sa Indiana, gaano katagal valid ang learner's permit?","o":["6 na buwan","Dalawang taon","Isang taon","Hanggang mag-18 ka"],"h1":"Mas matagal ito kaysa sa panahong dapat mo itong hawak bago magka-lisensya.","h2":"Sa Indiana, valid ang learner's permit nang dalawang taon mula sa araw na ibinigay ito.","p":"Tama. Dalawang taon ang tagal ng learner's permit."},"ar":{"q":"في Indiana، كم مدة صلاحية تصريح التعلّم (learner's permit)؟","o":["6 أشهر","سنتان","سنة واحدة","حتى تبلغ 18 سنة"],"h1":"مدتها أطول من المدة التي يجب أن تحمله فيها قبل الرخصة.","h2":"في Indiana يكون تصريح التعلّم صالحًا لمدة سنتين من يوم إصداره.","p":"صحيح. تصريح التعلّم صالح لمدة سنتين."},"ref":{"doc":"IN","page":4}},{"id":"in-024","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you move to a new home. How soon must you tell the BMV and get an updated license?","o":["Within 1 year","At your next renewal","Within 7 days","Within 30 days"],"h1":"You have about one month.","h2":"In Indiana you must tell the BMV about a new legal address and get an updated license within 30 days of moving.","p":"Right. Update your address within 30 days."},"es":{"q":"En Indiana, usted se muda a una casa nueva. ¿En cuánto tiempo debe avisar al BMV y obtener una licencia actualizada?","o":["En 1 año","En su próxima renovación","En 7 días","En 30 días"],"h1":"Tiene más o menos un mes.","h2":"En Indiana usted debe avisar al BMV de su nueva dirección legal y obtener una licencia actualizada en los 30 días siguientes a la mudanza.","p":"Correcto. Actualice su dirección en 30 días."},"zh":{"q":"在 Indiana，你搬了新家。你必须在多久之内通知 BMV 并更新驾照？","o":["1 年之内","下次续期的时候","7 天之内","30 天之内"],"h1":"你大约有一个月的时间。","h2":"在 Indiana，搬家后你必须在 30 天之内把新的法定地址告诉 BMV，并拿到更新后的驾照。","p":"对。在 30 天之内更新你的地址。"},"vi":{"q":"Ở Indiana, bạn dọn đến nhà mới. Bạn phải báo cho BMV và lấy bằng lái cập nhật trong bao lâu?","o":["Trong vòng 1 năm","Vào lần gia hạn tới","Trong vòng 7 ngày","Trong vòng 30 ngày"],"h1":"Bạn có khoảng một tháng.","h2":"Ở Indiana, bạn phải báo cho BMV địa chỉ hợp pháp mới và lấy bằng lái cập nhật trong vòng 30 ngày sau khi dọn nhà.","p":"Đúng. Hãy cập nhật địa chỉ trong vòng 30 ngày."},"tl":{"q":"Sa Indiana, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihan ang BMV at kumuha ng updated na lisensya?","o":["Sa loob ng 1 taon","Sa susunod mong renewal","Sa loob ng 7 araw","Sa loob ng 30 araw"],"h1":"Mayroon kang mga isang buwan.","h2":"Sa Indiana, dapat mong sabihan ang BMV tungkol sa bago mong legal na address at kumuha ng updated na lisensya sa loob ng 30 araw mula nang lumipat ka.","p":"Tama. I-update ang address mo sa loob ng 30 araw."},"ar":{"q":"في Indiana، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ BMV وتحصل على رخصة محدّثة؟","o":["خلال سنة واحدة (1)","عند التجديد القادم","خلال 7 أيام","خلال 30 يومًا"],"h1":"لديك شهر تقريبًا.","h2":"في Indiana يجب أن تُبلغ BMV بعنوانك القانوني الجديد وتحصل على رخصة محدّثة خلال 30 يومًا من الانتقال.","p":"صحيح. حدّث عنوانك خلال 30 يومًا."},"ref":{"doc":"IN","page":20}},{"id":"in-025","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how long do points for a traffic violation stay active on your driving record?","o":["Two years from the conviction date","Six months","Ten years","For the rest of your life"],"h1":"It is more than one year but less than five.","h2":"In Indiana, points stay active on your driving record for two years from the date you were convicted.","p":"Right. Points stay active for two years."},"es":{"q":"En Indiana, ¿por cuánto tiempo siguen activos en su historial de manejo los puntos por una infracción de tránsito?","o":["Dos años desde la fecha de la condena","Seis meses","Diez años","Para toda la vida"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Indiana los puntos siguen activos en su historial de manejo por dos años desde la fecha de la condena.","p":"Correcto. Los puntos siguen activos por dos años."},"zh":{"q":"在 Indiana，交通违规的扣分在你的驾驶记录上有效多久？","o":["从定罪那天起两年","六个月","十年","一辈子"],"h1":"比一年长，但比五年短。","h2":"在 Indiana，扣分从你被定罪那天起在驾驶记录上有效两年。","p":"对。扣分有效两年。"},"vi":{"q":"Ở Indiana, điểm phạt vì vi phạm giao thông còn hiệu lực trong hồ sơ lái xe của bạn bao lâu?","o":["Hai năm kể từ ngày bị kết tội","Sáu tháng","Mười năm","Suốt đời"],"h1":"Lâu hơn một năm nhưng ít hơn năm năm.","h2":"Ở Indiana, điểm phạt còn hiệu lực trong hồ sơ lái xe của bạn hai năm kể từ ngày bạn bị kết tội.","p":"Đúng. Điểm phạt còn hiệu lực hai năm."},"tl":{"q":"Sa Indiana, gaano katagal aktibo sa driving record mo ang mga point para sa isang traffic violation?","o":["Dalawang taon mula sa petsa ng conviction","Anim na buwan","Sampung taon","Habambuhay"],"h1":"Higit ito sa isang taon pero kulang sa lima.","h2":"Sa Indiana, aktibo ang mga point sa driving record mo nang dalawang taon mula sa petsa na na-convict ka.","p":"Tama. Aktibo ang mga point nang dalawang taon."},"ar":{"q":"في Indiana، كم تبقى نقاط المخالفة المرورية فعّالة في سجل قيادتك؟","o":["سنتان من تاريخ الإدانة","ستة أشهر","عشر سنوات","طوال حياتك"],"h1":"أكثر من سنة واحدة لكن أقل من خمس سنوات.","h2":"في Indiana تبقى النقاط فعّالة في سجل قيادتك لمدة سنتين من تاريخ إدانتك.","p":"صحيح. تبقى النقاط فعّالة لمدة سنتين."},"ref":{"doc":"IN","page":21}},{"id":"in-026","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what is the minimum liability insurance a driver must carry?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"The first and last numbers are the same: $25,000.","h2":"Indiana's minimum liability insurance is 25/50/25: $25,000 for one person hurt, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. The minimum is 25/50/25."},"es":{"q":"En Indiana, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"El primer y el último número son iguales: $25,000.","h2":"El seguro de responsabilidad mínimo en Indiana es 25/50/25: $25,000 por una persona herida, $50,000 por dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo es 25/50/25."},"zh":{"q":"在 Indiana，司机必须买的最低责任保险是多少？","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"第一个和最后一个数字相同：$25,000。","h2":"Indiana 的最低责任保险是 25/50/25：一人受伤 $25,000，两人或更多人受伤 $50,000，财产损失 $25,000。","p":"对。最低是 25/50/25。"},"vi":{"q":"Ở Indiana, bảo hiểm trách nhiệm tối thiểu mà người lái phải có là bao nhiêu?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"Số đầu và số cuối giống nhau: $25,000.","h2":"Bảo hiểm trách nhiệm tối thiểu ở Indiana là 25/50/25: $25,000 cho một người bị thương, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu là 25/50/25."},"tl":{"q":"Sa Indiana, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"Pareho ang una at huling numero: $25,000.","h2":"Ang pinakamababang liability insurance sa Indiana ay 25/50/25: $25,000 para sa isang taong nasaktan, $50,000 para sa dalawa o higit pang tao, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang pinakamababa ay 25/50/25."},"ar":{"q":"في Indiana، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون لدى السائق؟","o":["10/20/10","50/100/50","25/50/25","15/30/5"],"h1":"الرقم الأول والرقم الأخير متساويان: $25,000.","h2":"الحد الأدنى لتأمين المسؤولية في Indiana هو 25/50/25: $25,000 لإصابة شخص واحد، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى هو 25/50/25."},"ref":{"doc":"IN","page":22}},{"id":"in-027","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many points do you get for driving 26 mph or more over the speed limit?","o":["2 points","6 points","4 points","1 point"],"h1":"The faster you go over the limit, the more points you get.","h2":"In Indiana, driving 26 mph or more over the speed limit puts 6 points on your driving record.","p":"Right. 26 mph or more over the limit is 6 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por manejar 26 mph o más por encima del límite de velocidad?","o":["2 puntos","6 puntos","4 puntos","1 punto"],"h1":"Mientras más rápido vaya sobre el límite, más puntos recibe.","h2":"En Indiana, manejar 26 millas por hora o más por encima del límite de velocidad le pone 6 puntos en su historial de manejo.","p":"Correcto. 26 mph o más sobre el límite son 6 puntos."},"zh":{"q":"在 Indiana，超速 26 mph 或更多，会被记几分？","o":["2 分","6 分","4 分","1 分"],"h1":"超速越多，记的分就越多。","h2":"在 Indiana，超过限速 26 mph 或更多，会在你的驾驶记录上记 6 分。","p":"对。超速 26 mph 或更多记 6 分。"},"vi":{"q":"Ở Indiana, bạn bị bao nhiêu điểm phạt khi lái nhanh hơn tốc độ giới hạn 26 mph trở lên?","o":["2 điểm","6 điểm","4 điểm","1 điểm"],"h1":"Bạn càng chạy quá tốc độ nhiều thì càng bị nhiều điểm.","h2":"Ở Indiana, lái nhanh hơn tốc độ giới hạn 26 mph trở lên sẽ bị ghi 6 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Quá tốc độ 26 mph trở lên là 6 điểm."},"tl":{"q":"Sa Indiana, ilang point ang makukuha mo kapag nagmaneho ka nang 26 mph o higit pa sa speed limit?","o":["2 point","6 point","4 point","1 point"],"h1":"Habang mas bumibilis ka lampas sa limit, mas maraming point ang makukuha mo.","h2":"Sa Indiana, ang pagmamaneho nang 26 mph o higit pa sa speed limit ay naglalagay ng 6 point sa driving record mo.","p":"Tama. Ang 26 mph o higit pa sa limit ay 6 point."},"ar":{"q":"في Indiana، كم نقطة تحصل عليها إذا قدت بسرعة تزيد على حد السرعة بمقدار 26 mph أو أكثر؟","o":["نقطتان (2)","6 نقاط","4 نقاط","نقطة واحدة (1)"],"h1":"كلما زادت سرعتك فوق الحد، زادت النقاط التي تحصل عليها.","h2":"في Indiana، القيادة بسرعة تزيد على حد السرعة بمقدار 26 mph أو أكثر تضع 6 نقاط في سجل قيادتك.","p":"صحيح. الزيادة 26 mph أو أكثر فوق الحد تساوي 6 نقاط."},"ref":{"doc":"IN","page":21}},{"id":"in-028","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, when you pass another vehicle, how far from an oncoming vehicle must you be back on the right side of the road?","o":["At least 25 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"The distance is about one third of a football field.","h2":"In Indiana, you must return to the right side of the road at least 100 feet before any oncoming vehicle.","p":"Right. Be back on the right at least 100 feet before an oncoming vehicle."},"es":{"q":"En Indiana, al rebasar a otro vehículo, ¿a qué distancia de un vehículo que viene de frente debe estar ya en el lado derecho del camino?","o":["Al menos 25 pies","Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"La distancia es como un tercio de un campo de fútbol americano.","h2":"En Indiana, usted debe volver al lado derecho del camino al menos 100 pies antes de cualquier vehículo que viene de frente.","p":"Correcto. Vuelva a la derecha al menos 100 pies antes del vehículo que viene."},"zh":{"q":"在 Indiana，超过另一辆车时，你必须在离对面来车多远的地方回到道路右侧？","o":["至少 25 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"这个距离大约是一个美式足球场长度的三分之一。","h2":"在 Indiana，你必须在离任何对面来车至少 100 英尺的地方回到道路右侧。","p":"对。在离对面来车至少 100 英尺时回到右侧。"},"vi":{"q":"Ở Indiana, khi vượt một xe khác, bạn phải trở về bên phải đường khi còn cách xe đi ngược chiều bao xa?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng cách này bằng khoảng một phần ba sân bóng bầu dục Mỹ.","h2":"Ở Indiana, bạn phải trở về bên phải đường khi còn cách bất kỳ xe đi ngược chiều nào ít nhất 100 feet.","p":"Đúng. Trở về bên phải khi còn cách xe ngược chiều ít nhất 100 feet."},"tl":{"q":"Sa Indiana, kapag nag-overtake ka ng ibang sasakyan, gaano kalayo dapat sa paparating na sasakyan ka nakabalik na sa kanang bahagi ng daan?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 1,000 feet"],"h1":"Ang layo ay mga isang katlo ng isang football field.","h2":"Sa Indiana, dapat nakabalik ka na sa kanang bahagi ng daan nang hindi bababa sa 100 feet bago ang anumang paparating na sasakyan.","p":"Tama. Bumalik sa kanan nang hindi bababa sa 100 feet bago ang paparating na sasakyan."},"ar":{"q":"في Indiana، عندما تتجاوز مركبة أخرى، على أي مسافة من المركبة القادمة من الاتجاه المعاكس يجب أن تكون قد عدت إلى الجانب الأيمن من الطريق؟","o":["25 feet على الأقل","50 feet على الأقل","100 feet على الأقل","1,000 feet على الأقل"],"h1":"هذه المسافة تساوي تقريبًا ثلث طول ملعب كرة قدم أمريكية.","h2":"في Indiana يجب أن تعود إلى الجانب الأيمن من الطريق قبل أي مركبة قادمة من الاتجاه المعاكس بمسافة 100 feet على الأقل.","p":"صحيح. عُد إلى اليمين قبل المركبة القادمة بمسافة 100 feet على الأقل."},"ref":{"doc":"IN","page":38}},{"id":"in-029","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, how does the speed limit in a highway work site compare with the usual limit for that area?","o":["It is at least 10 mph lower","It is exactly 5 mph lower","It is the same as the usual limit","It is always 25 mph"],"h1":"Work site limits are always lower by a set minimum amount.","h2":"In Indiana, a work site speed limit is always at least 10 mph below the usual maximum limit for that area.","p":"Right. Work site limits are at least 10 mph lower."},"es":{"q":"En Indiana, ¿cómo es el límite de velocidad en una zona de trabajo en la carretera comparado con el límite normal de esa área?","o":["Es al menos 10 mph más bajo","Es exactamente 5 mph más bajo","Es igual al límite normal","Siempre es de 25 mph"],"h1":"El límite en zonas de trabajo siempre es más bajo por una cantidad mínima fija.","h2":"En Indiana, el límite de velocidad en una zona de trabajo siempre es al menos 10 mph más bajo que el límite máximo normal de esa área.","p":"Correcto. En zonas de trabajo el límite es al menos 10 mph más bajo."},"zh":{"q":"在 Indiana，公路施工区的限速和这个地区平时的限速相比怎么样？","o":["至少低 10 mph","正好低 5 mph","和平时的限速一样","永远是 25 mph"],"h1":"施工区的限速总是比平时低，而且有一个最少要低的数。","h2":"在 Indiana，施工区的限速总是比这个地区平时的最高限速至少低 10 mph。","p":"对。施工区的限速至少低 10 mph。"},"vi":{"q":"Ở Indiana, tốc độ giới hạn trong khu công trường trên xa lộ so với tốc độ giới hạn thông thường của khu vực đó thì thế nào?","o":["Thấp hơn ít nhất 10 mph","Thấp hơn đúng 5 mph","Bằng tốc độ giới hạn thông thường","Luôn luôn là 25 mph"],"h1":"Tốc độ giới hạn ở khu công trường luôn thấp hơn ít nhất một mức nhất định.","h2":"Ở Indiana, tốc độ giới hạn ở khu công trường luôn thấp hơn tốc độ tối đa thông thường của khu vực đó ít nhất 10 mph.","p":"Đúng. Tốc độ giới hạn ở khu công trường thấp hơn ít nhất 10 mph."},"tl":{"q":"Sa Indiana, paano ikinukumpara ang speed limit sa work site sa highway sa karaniwang speed limit sa lugar na iyon?","o":["Mas mababa ito nang hindi bababa sa 10 mph","Mas mababa ito nang eksaktong 5 mph","Pareho ito sa karaniwang speed limit","Palagi itong 25 mph"],"h1":"Ang speed limit sa work site ay palaging mas mababa nang may takdang pinakamaliit na halaga.","h2":"Sa Indiana, ang speed limit sa work site ay palaging mas mababa nang hindi bababa sa 10 mph kaysa sa karaniwang maximum na speed limit sa lugar na iyon.","p":"Tama. Ang speed limit sa work site ay mas mababa nang hindi bababa sa 10 mph."},"ar":{"q":"في Indiana، كيف يُقارَن حد السرعة في منطقة أعمال على الطريق السريع بالحد المعتاد في تلك المنطقة؟","o":["أقل بمقدار 10 mph على الأقل","أقل بمقدار 5 mph بالضبط","هو نفس الحد المعتاد","هو دائمًا 25 mph"],"h1":"حد السرعة في منطقة الأعمال أقل دائمًا بمقدار أدنى محدّد.","h2":"في Indiana يكون حد السرعة في منطقة الأعمال دائمًا أقل بمقدار 10 mph على الأقل من الحد الأقصى المعتاد في تلك المنطقة.","p":"صحيح. حد السرعة في منطقة الأعمال أقل بمقدار 10 mph على الأقل."},"ref":{"doc":"IN","page":41}},{"id":"in-030","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 30 feet","No closer than 50 feet","No closer than 15 feet"],"h1":"Fire trucks need room to reach the hydrant.","h2":"In Indiana, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Indiana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 30 pies","No más cerca de 50 pies","No más cerca de 15 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Indiana, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Indiana，你可以把车停在离消防栓多近的地方？","o":["不能少于 5 英尺","不能少于 30 英尺","不能少于 50 英尺","不能少于 15 英尺"],"h1":"消防车需要空间才能用到消防栓。","h2":"在 Indiana，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Indiana, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 30 feet","Không gần hơn 50 feet","Không gần hơn 15 feet"],"h1":"Xe cứu hỏa cần chỗ để tới được trụ nước.","h2":"Ở Indiana, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước chữa cháy.","p":"Đúng. Hãy cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa Indiana, gaano kalapit sa fire hydrant ka puwedeng mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 15 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para maabot ang hydrant.","h2":"Sa Indiana, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في Indiana، إلى أي مدى يمكنك أن تركن قريبًا من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet","ليس أقرب من 15 feet"],"h1":"سيارات الإطفاء تحتاج إلى مساحة لتصل إلى الصنبور.","h2":"في Indiana لا يجوز لك أن تركن على بُعد أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من الصنبور."},"ref":{"doc":"IN","page":54}},{"id":"in-031","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, your license has been expired for 200 days. What must you do to renew it?","o":["Pay only the usual renewal fee online","Pay a penalty, pass a knowledge exam and a vision test","Pay a penalty and pass only a driving skills test","Wait one year, then retake driver education"],"h1":"After about six months, the BMV wants to check what you know and how you see.","h2":"In Indiana, if your license has been expired for at least 180 days but less than five years, you must pay a penalty and pass a knowledge exam and a vision screening.","p":"Right. Pay the penalty and pass the knowledge exam and vision screening."},"es":{"q":"En Indiana, su licencia lleva 200 días vencida. ¿Qué debe hacer para renovarla?","o":["Pagar solo la tarifa normal de renovación en línea","Pagar una multa, aprobar un examen de conocimientos y una prueba de la vista","Pagar una multa y aprobar solo un examen práctico de manejo","Esperar un año y tomar otra vez el curso de manejo"],"h1":"Después de unos seis meses, el BMV quiere revisar lo que usted sabe y cómo ve.","h2":"En Indiana, si su licencia lleva vencida al menos 180 días pero menos de cinco años, usted debe pagar una multa y aprobar un examen de conocimientos y una prueba de la vista.","p":"Correcto. Pague la multa y apruebe el examen de conocimientos y la prueba de la vista."},"zh":{"q":"在 Indiana，你的驾照已经过期 200 天了。你要怎样才能更新它？","o":["只要在网上付平常的更新费","付罚款，并通过知识考试和视力检查","付罚款，并只通过驾驶技能考试","等一年，然后重新上驾驶课"],"h1":"过了大约六个月，BMV 想检查你懂多少、看得清不清楚。","h2":"在 Indiana，如果你的驾照已经过期至少 180 天但不到五年，你必须付罚款，并通过知识考试和视力检查。","p":"对。付罚款，并通过知识考试和视力检查。"},"vi":{"q":"Ở Indiana, bằng lái của bạn đã hết hạn 200 ngày. Bạn phải làm gì để gia hạn?","o":["Chỉ trả phí gia hạn thông thường trên mạng","Trả tiền phạt, thi đậu bài thi kiến thức và kiểm tra thị lực","Trả tiền phạt và chỉ thi đậu bài thi kỹ năng lái xe","Chờ một năm, rồi học lại giáo dục lái xe"],"h1":"Sau khoảng sáu tháng, BMV muốn kiểm tra những gì bạn biết và mắt bạn nhìn ra sao.","h2":"Ở Indiana, nếu bằng lái của bạn đã hết hạn ít nhất 180 ngày nhưng chưa tới năm năm, bạn phải trả tiền phạt và thi đậu bài thi kiến thức và kiểm tra thị lực.","p":"Đúng. Trả tiền phạt và thi đậu bài thi kiến thức và kiểm tra thị lực."},"tl":{"q":"Sa Indiana, 200 araw nang expired ang lisensya mo. Ano ang dapat mong gawin para ma-renew ito?","o":["Bayaran lang ang karaniwang renewal fee online","Magbayad ng multa, pumasa sa knowledge exam at sa vision test","Magbayad ng multa at pumasa lang sa driving skills test","Maghintay ng isang taon, saka ulitin ang driver education"],"h1":"Pagkalipas ng mga anim na buwan, gusto ng BMV na suriin ang alam mo at kung gaano ka kalinaw makakita.","h2":"Sa Indiana, kung expired na ang lisensya mo nang hindi bababa sa 180 araw pero wala pang limang taon, dapat kang magbayad ng multa at pumasa sa knowledge exam at sa vision screening.","p":"Tama. Magbayad ng multa at pumasa sa knowledge exam at vision screening."},"ar":{"q":"في Indiana، انتهت صلاحية رخصتك منذ 200 يوم. ماذا يجب أن تفعل لتجديدها؟","o":["تدفع رسوم التجديد المعتادة فقط عبر الإنترنت","تدفع غرامة وتنجح في اختبار المعرفة وفحص النظر","تدفع غرامة وتنجح فقط في اختبار مهارات القيادة","تنتظر سنة واحدة ثم تعيد دورة تعليم القيادة"],"h1":"بعد نحو ستة أشهر، يريد BMV أن يتحقق مما تعرفه ومن قدرتك على الرؤية.","h2":"في Indiana، إذا انتهت صلاحية رخصتك منذ 180 يومًا على الأقل ولكن أقل من خمس سنوات، يجب أن تدفع غرامة وتنجح في اختبار المعرفة وفحص النظر.","p":"صحيح. ادفع الغرامة وانجح في اختبار المعرفة وفحص النظر."},"ref":{"doc":"IN","page":19}},{"id":"in-032","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you just moved here and became a resident. How long do you have to get an Indiana driver's license?","o":["30 days","10 days","60 days","One year"],"h1":"It is about two months.","h2":"In Indiana, a new resident has 60 days to get an Indiana driver's license.","p":"Right. New residents have 60 days."},"es":{"q":"En Indiana, usted acaba de mudarse y ahora es residente. ¿Cuánto tiempo tiene para sacar una licencia de manejar de Indiana?","o":["30 días","10 días","60 días","Un año"],"h1":"Son unos dos meses.","h2":"En Indiana, un nuevo residente tiene 60 días para sacar una licencia de manejar de Indiana.","p":"Correcto. Los nuevos residentes tienen 60 días."},"zh":{"q":"在 Indiana，你刚搬来这里，成为本州居民。你有多长时间去办 Indiana 驾照？","o":["30 天","10 天","60 天","一年"],"h1":"大约是两个月。","h2":"在 Indiana，新居民有 60 天的时间去办 Indiana 驾照。","p":"对。新居民有 60 天。"},"vi":{"q":"Ở Indiana, bạn vừa chuyển đến đây và trở thành cư dân. Bạn có bao lâu để lấy bằng lái xe Indiana?","o":["30 ngày","10 ngày","60 ngày","Một năm"],"h1":"Khoảng hai tháng.","h2":"Ở Indiana, cư dân mới có 60 ngày để lấy bằng lái xe Indiana.","p":"Đúng. Cư dân mới có 60 ngày."},"tl":{"q":"Sa Indiana, kalilipat mo lang dito at naging residente ka na. Gaano katagal ang mayroon ka para kumuha ng Indiana driver's license?","o":["30 araw","10 araw","60 araw","Isang taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa Indiana, may 60 araw ang bagong residente para kumuha ng Indiana driver's license.","p":"Tama. May 60 araw ang mga bagong residente."},"ar":{"q":"في Indiana، انتقلت إلى هنا حديثًا وأصبحت مقيمًا. كم من الوقت لديك للحصول على رخصة قيادة من Indiana؟","o":["30 يومًا","10 أيام","60 يومًا","سنة واحدة"],"h1":"المدة حوالي شهرين.","h2":"في Indiana، لدى المقيم الجديد 60 يومًا للحصول على رخصة قيادة من Indiana.","p":"صحيح. لدى المقيمين الجدد 60 يومًا."},"ref":{"doc":"IN","page":2}},{"id":"in-033","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how long is a regular driver's license valid for a driver younger than 75?","o":["Six years","Two years","Ten years","Four years"],"h1":"Older drivers renew more often than this.","h2":"In Indiana, a driver's license is valid for six years if you are younger than 75.","p":"Right. Under 75, a license lasts six years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válida una licencia de manejar normal para un conductor menor de 75 años?","o":["Seis años","Dos años","Diez años","Cuatro años"],"h1":"Los conductores mayores la renuevan más seguido.","h2":"En Indiana, una licencia de manejar es válida por seis años si usted tiene menos de 75 años.","p":"Correcto. Antes de los 75, la licencia dura seis años."},"zh":{"q":"在 Indiana，75 岁以下司机的普通驾照有效期是多久？","o":["六年","两年","十年","四年"],"h1":"年纪大的司机续期会比这更频繁。","h2":"在 Indiana，如果你不到 75 岁，驾照的有效期是六年。","p":"对。75 岁以下，驾照有效六年。"},"vi":{"q":"Ở Indiana, bằng lái xe thông thường của người lái dưới 75 tuổi có hiệu lực bao lâu?","o":["Sáu năm","Hai năm","Mười năm","Bốn năm"],"h1":"Người lái lớn tuổi phải gia hạn thường xuyên hơn mức này.","h2":"Ở Indiana, bằng lái xe có hiệu lực sáu năm nếu bạn dưới 75 tuổi.","p":"Đúng. Dưới 75 tuổi, bằng lái có hiệu lực sáu năm."},"tl":{"q":"Sa Indiana, gaano katagal valid ang regular na driver's license ng driver na wala pang 75 taong gulang?","o":["Anim na taon","Dalawang taon","Sampung taon","Apat na taon"],"h1":"Mas madalas mag-renew ang mga mas matandang driver kaysa rito.","h2":"Sa Indiana, valid nang anim na taon ang driver's license kung wala ka pang 75 taong gulang.","p":"Tama. Kapag wala pang 75, anim na taon ang lisensya."},"ar":{"q":"في Indiana، ما مدة صلاحية رخصة القيادة العادية للسائق الذي عمره أقل من 75 سنة؟","o":["ست سنوات","سنتان","عشر سنوات","أربع سنوات"],"h1":"السائقون الأكبر سنًّا يجدّدون أكثر من ذلك.","h2":"في Indiana، تكون رخصة القيادة صالحة لمدة ست سنوات إذا كان عمرك أقل من 75 سنة.","p":"صحيح. تحت عمر 75 سنة تبقى الرخصة صالحة ست سنوات."},"ref":{"doc":"IN","page":9}},{"id":"in-034","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you fail the knowledge exam. When may you take it again?","o":["After 30 days","After seven days","After six months","The next business day"],"h1":"The wait is very short.","h2":"In Indiana, if you fail the knowledge exam, you may take it again on the next business day.","p":"Right. You can retake it the next business day."},"es":{"q":"En Indiana, usted no aprueba el examen de conocimientos. ¿Cuándo puede tomarlo otra vez?","o":["Después de 30 días","Después de siete días","Después de seis meses","El siguiente día hábil"],"h1":"La espera es muy corta.","h2":"En Indiana, si no aprueba el examen de conocimientos, puede tomarlo otra vez el siguiente día hábil.","p":"Correcto. Puede repetirlo el siguiente día hábil."},"zh":{"q":"在 Indiana，你的笔试（knowledge exam）没有通过。你什么时候可以再考？","o":["30 天以后","七天以后","六个月以后","下一个工作日"],"h1":"等待的时间很短。","h2":"在 Indiana，如果你笔试没有通过，下一个工作日就可以再考。","p":"对。下一个工作日就可以重考。"},"vi":{"q":"Ở Indiana, bạn thi trượt bài thi lý thuyết (knowledge exam). Khi nào bạn được thi lại?","o":["Sau 30 ngày","Sau bảy ngày","Sau sáu tháng","Ngày làm việc kế tiếp"],"h1":"Thời gian chờ rất ngắn.","h2":"Ở Indiana, nếu bạn thi trượt bài thi lý thuyết, bạn được thi lại vào ngày làm việc kế tiếp.","p":"Đúng. Bạn được thi lại vào ngày làm việc kế tiếp."},"tl":{"q":"Sa Indiana, bumagsak ka sa knowledge exam. Kailan ka puwedeng kumuha ulit?","o":["Pagkalipas ng 30 araw","Pagkalipas ng pitong araw","Pagkalipas ng anim na buwan","Sa susunod na araw ng trabaho"],"h1":"Napakaikli ng paghihintay.","h2":"Sa Indiana, kapag bumagsak ka sa knowledge exam, puwede kang kumuha ulit sa susunod na araw ng trabaho.","p":"Tama. Puwede kang kumuha ulit sa susunod na araw ng trabaho."},"ar":{"q":"في Indiana، رسبت في الامتحان النظري (knowledge exam). متى يمكنك أن تتقدّم له مرة أخرى؟","o":["بعد 30 يومًا","بعد سبعة أيام","بعد ستة أشهر","في يوم العمل التالي"],"h1":"مدة الانتظار قصيرة جدًا.","h2":"في Indiana، إذا رسبت في الامتحان النظري يمكنك أن تتقدّم له مرة أخرى في يوم العمل التالي.","p":"صحيح. يمكنك إعادة الامتحان في يوم العمل التالي."},"ref":{"doc":"IN","page":5}},{"id":"in-035","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you fail the driving skills exam. How long must you wait before you take it again?","o":["Until the next day","Seven days","Six months","One year"],"h1":"It is about one week.","h2":"In Indiana, after you fail a driving skills exam, you must wait seven days before you take it again.","p":"Right. You wait seven days to retake the skills exam."},"es":{"q":"En Indiana, usted no aprueba el examen práctico de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Hasta el día siguiente","Siete días","Seis meses","Un año"],"h1":"Es como una semana.","h2":"En Indiana, si no aprueba un examen práctico de manejo, debe esperar siete días para tomarlo otra vez.","p":"Correcto. Espera siete días para repetir el examen práctico."},"zh":{"q":"在 Indiana，你的路考（driving skills exam）没有通过。你必须等多久才能再考？","o":["等到第二天","七天","六个月","一年"],"h1":"大约是一个星期。","h2":"在 Indiana，路考没有通过以后，你必须等七天才能再考。","p":"对。路考要等七天才能重考。"},"vi":{"q":"Ở Indiana, bạn thi trượt bài thi kỹ năng lái xe (driving skills exam). Bạn phải chờ bao lâu trước khi thi lại?","o":["Đến ngày hôm sau","Bảy ngày","Sáu tháng","Một năm"],"h1":"Khoảng một tuần.","h2":"Ở Indiana, sau khi thi trượt bài thi kỹ năng lái xe, bạn phải chờ bảy ngày rồi mới được thi lại.","p":"Đúng. Bạn chờ bảy ngày để thi lại bài kỹ năng."},"tl":{"q":"Sa Indiana, bumagsak ka sa driving skills exam. Gaano katagal ka dapat maghintay bago kumuha ulit?","o":["Hanggang sa susunod na araw","Pitong araw","Anim na buwan","Isang taon"],"h1":"Mga isang linggo ito.","h2":"Sa Indiana, pagkatapos mong bumagsak sa driving skills exam, dapat kang maghintay nang pitong araw bago kumuha ulit.","p":"Tama. Maghihintay ka nang pitong araw bago ulitin ang skills exam."},"ar":{"q":"في Indiana، رسبت في امتحان مهارات القيادة (driving skills exam). كم يجب أن تنتظر قبل أن تتقدّم له مرة أخرى؟","o":["حتى اليوم التالي","سبعة أيام","ستة أشهر","سنة واحدة"],"h1":"المدة حوالي أسبوع واحد.","h2":"في Indiana، بعد أن ترسب في امتحان مهارات القيادة، يجب أن تنتظر سبعة أيام قبل أن تتقدّم له مرة أخرى.","p":"صحيح. تنتظر سبعة أيام لإعادة امتحان المهارات."},"ref":{"doc":"IN","page":7}},{"id":"in-036","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many points do you get for a hand-held phone violation while driving?","o":["2 points","8 points","4 points","10 points"],"h1":"It is the same number of points as running a stop sign.","h2":"In Indiana, a violation for using a hand-held device while driving puts 4 points on your record.","p":"Right. A hand-held device violation is 4 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por una infracción de usar el teléfono en la mano mientras maneja?","o":["2 puntos","8 puntos","4 puntos","10 puntos"],"h1":"Son los mismos puntos que por no respetar una señal de alto.","h2":"En Indiana, una infracción por usar un aparato en la mano mientras maneja le pone 4 puntos en su historial.","p":"Correcto. Usar un aparato en la mano son 4 puntos."},"zh":{"q":"在 Indiana，开车时手持手机违规，会被记几分？","o":["2 分","8 分","4 分","10 分"],"h1":"和闯停车标志记的分一样多。","h2":"在 Indiana，开车时使用手持设备违规，会在你的记录上记 4 分。","p":"对。手持设备违规记 4 分。"},"vi":{"q":"Ở Indiana, bạn bị bao nhiêu điểm phạt khi vi phạm cầm điện thoại trên tay lúc lái xe?","o":["2 điểm","8 điểm","4 điểm","10 điểm"],"h1":"Số điểm bằng với lỗi chạy qua biển báo dừng (stop sign).","h2":"Ở Indiana, vi phạm dùng thiết bị cầm tay khi lái xe sẽ ghi 4 điểm vào hồ sơ của bạn.","p":"Đúng. Vi phạm thiết bị cầm tay là 4 điểm."},"tl":{"q":"Sa Indiana, ilang point ang makukuha mo para sa paglabag sa paghawak ng telepono habang nagmamaneho?","o":["2 point","8 point","4 point","10 point"],"h1":"Pareho ito sa bilang ng point sa paglampas sa stop sign.","h2":"Sa Indiana, ang paglabag sa paggamit ng hand-held device habang nagmamaneho ay naglalagay ng 4 point sa record mo.","p":"Tama. 4 point ang paglabag sa hand-held device."},"ar":{"q":"في Indiana، كم نقطة تحصل عليها بسبب مخالفة حمل الهاتف باليد أثناء القيادة؟","o":["نقطتان (2)","8 نقاط","4 نقاط","10 نقاط"],"h1":"هو نفس عدد النقاط لتجاوز إشارة التوقف (stop sign).","h2":"في Indiana، مخالفة استخدام جهاز محمول باليد أثناء القيادة تضيف 4 نقاط إلى سجلك.","p":"صحيح. مخالفة الجهاز المحمول باليد هي 4 نقاط."},"ref":{"doc":"IN","page":21}},{"id":"in-037","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, any driver may finish a BMV-approved Driver Safety Program course. What does it give you?","o":["A four-point credit on your record","A free license renewal","All points erased forever","A lower insurance minimum"],"h1":"It helps your point total.","h2":"In Indiana, finishing a BMV-approved Driver Safety Program course gives you a four-point credit, once every three years.","p":"Right. The course gives a four-point credit."},"es":{"q":"En Indiana, cualquier conductor puede terminar un curso del Programa de Seguridad del Conductor aprobado por el BMV. ¿Qué le da?","o":["Un crédito de cuatro puntos en su historial","Una renovación de licencia gratis","Borrar todos los puntos para siempre","Un mínimo de seguro más bajo"],"h1":"Ayuda con su total de puntos.","h2":"En Indiana, terminar un curso del Programa de Seguridad del Conductor aprobado por el BMV le da un crédito de cuatro puntos, una vez cada tres años.","p":"Correcto. El curso da un crédito de cuatro puntos."},"zh":{"q":"在 Indiana，任何司机都可以完成 BMV 批准的驾驶安全课程（Driver Safety Program）。它能给你什么？","o":["在你的记录上抵消四分","免费续期驾照","永远删除所有扣分","降低最低保险要求"],"h1":"它对你的总分有帮助。","h2":"在 Indiana，完成 BMV 批准的驾驶安全课程可以给你抵消四分，每三年可以用一次。","p":"对。这个课程可以抵消四分。"},"vi":{"q":"Ở Indiana, bất kỳ người lái xe nào cũng có thể hoàn thành khóa học An toàn Lái xe (Driver Safety Program) được BMV chấp thuận. Khóa học này cho bạn điều gì?","o":["Được trừ bớt bốn điểm trong hồ sơ","Gia hạn bằng lái miễn phí","Xóa hết điểm phạt mãi mãi","Mức bảo hiểm tối thiểu thấp hơn"],"h1":"Nó giúp giảm tổng số điểm của bạn.","h2":"Ở Indiana, hoàn thành khóa học An toàn Lái xe được BMV chấp thuận giúp bạn được trừ bớt bốn điểm, mỗi ba năm một lần.","p":"Đúng. Khóa học giúp trừ bớt bốn điểm."},"tl":{"q":"Sa Indiana, puwedeng tapusin ng sinumang driver ang Driver Safety Program course na aprubado ng BMV. Ano ang ibinibigay nito sa iyo?","o":["Isang four-point credit sa record mo","Libreng pag-renew ng lisensya","Pagbura ng lahat ng point magpakailanman","Mas mababang minimum na insurance"],"h1":"Nakakatulong ito sa kabuuang bilang ng point mo.","h2":"Sa Indiana, ang pagtatapos ng Driver Safety Program course na aprubado ng BMV ay nagbibigay sa iyo ng four-point credit, isang beses bawat tatlong taon.","p":"Tama. Nagbibigay ang course ng four-point credit."},"ar":{"q":"في Indiana، يمكن لأي سائق أن يُكمل دورة برنامج سلامة السائق (Driver Safety Program) المعتمدة من BMV. ماذا تعطيك هذه الدورة؟","o":["خصم أربع نقاط من سجلك","تجديد الرخصة مجانًا","مسح كل النقاط إلى الأبد","حدًّا أدنى أقل للتأمين"],"h1":"تساعد في مجموع نقاطك.","h2":"في Indiana، إكمال دورة برنامج سلامة السائق المعتمدة من BMV يعطيك خصم أربع نقاط، مرة واحدة كل ثلاث سنوات.","p":"صحيح. الدورة تعطيك خصم أربع نقاط."},"ref":{"doc":"IN","page":21}},{"id":"in-038","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a driver fails a chemical test for alcohol. How long will the driver's license be suspended?","o":["30 days","180 days","5 years","10 years"],"h1":"It is about half a year.","h2":"In Indiana, a driver who fails a chemical test faces a 180-day suspension of driving privileges.","p":"Right. Failing a chemical test means a 180-day suspension."},"es":{"q":"En Indiana, un conductor no pasa una prueba química de alcohol. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","180 días","5 años","10 años"],"h1":"Es como medio año.","h2":"En Indiana, un conductor que no pasa una prueba química enfrenta una suspensión de 180 días de su privilegio de manejar.","p":"Correcto. No pasar la prueba química significa 180 días de suspensión."},"zh":{"q":"在 Indiana，一名司机没有通过酒精化学测试。他的驾照会被暂停多久？","o":["30 天","180 天","5 年","10 年"],"h1":"大约是半年。","h2":"在 Indiana，没有通过化学测试的司机，驾驶权会被暂停 180 天。","p":"对。化学测试没通过，会被暂停 180 天。"},"vi":{"q":"Ở Indiana, một người lái xe không đạt bài kiểm tra hóa học về rượu bia (chemical test). Bằng lái của người đó sẽ bị đình chỉ bao lâu?","o":["30 ngày","180 ngày","5 năm","10 năm"],"h1":"Khoảng nửa năm.","h2":"Ở Indiana, người lái xe không đạt bài kiểm tra hóa học sẽ bị đình chỉ quyền lái xe 180 ngày.","p":"Đúng. Không đạt bài kiểm tra hóa học thì bị đình chỉ 180 ngày."},"tl":{"q":"Sa Indiana, bumagsak ang isang driver sa chemical test para sa alak. Gaano katagal masususpinde ang driver's license niya?","o":["30 araw","180 araw","5 taon","10 taon"],"h1":"Mga kalahating taon ito.","h2":"Sa Indiana, ang driver na bumagsak sa chemical test ay masususpinde ang pribilehiyong magmaneho nang 180 araw.","p":"Tama. Kapag bumagsak sa chemical test, 180 araw na suspensyon."},"ar":{"q":"في Indiana، رسب سائق في الفحص الكيميائي للكحول (chemical test). كم ستُعلَّق رخصة قيادته؟","o":["30 يومًا","180 يومًا","5 سنوات","10 سنوات"],"h1":"المدة حوالي نصف سنة.","h2":"في Indiana، السائق الذي يرسب في الفحص الكيميائي يُعلَّق حقه في القيادة لمدة 180 يومًا.","p":"صحيح. الرسوب في الفحص الكيميائي يعني تعليقًا لمدة 180 يومًا."},"ref":{"doc":"IN","page":24}},{"id":"in-039","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, a driver with an earlier drunk driving (OWI) conviction refuses a chemical test. How long is the suspension?","o":["90 days","1 year","180 days","2 years"],"h1":"The earlier conviction makes it longer than a first refusal.","h2":"In Indiana, a driver with a previous OWI conviction who refuses a chemical test faces a two-year suspension.","p":"Right. A refusal after an earlier OWI conviction means two years."},"es":{"q":"En Indiana, un conductor que ya tiene una condena anterior por manejar intoxicado (OWI) se niega a una prueba química. ¿Cuánto dura la suspensión?","o":["90 días","1 año","180 días","2 años"],"h1":"La condena anterior la hace más larga que una primera negativa.","h2":"En Indiana, un conductor con una condena anterior por OWI que se niega a una prueba química enfrenta una suspensión de dos años.","p":"Correcto. Negarse después de una condena por OWI significa dos años."},"zh":{"q":"在 Indiana，一名以前有过酒驾（OWI）定罪的司机拒绝做化学测试。暂停多久？","o":["90 天","1 年","180 天","2 年"],"h1":"因为以前有定罪，所以比第一次拒绝更长。","h2":"在 Indiana，以前有过 OWI 定罪的司机如果拒绝化学测试，驾照会被暂停两年。","p":"对。以前有 OWI 定罪又拒绝测试，是两年。"},"vi":{"q":"Ở Indiana, một người lái xe đã từng bị kết tội lái xe khi say (OWI) từ chối làm bài kiểm tra hóa học. Thời gian đình chỉ là bao lâu?","o":["90 ngày","1 năm","180 ngày","2 năm"],"h1":"Lần bị kết tội trước làm cho thời gian dài hơn lần từ chối đầu tiên.","h2":"Ở Indiana, người lái xe đã từng bị kết tội OWI mà từ chối bài kiểm tra hóa học sẽ bị đình chỉ hai năm.","p":"Đúng. Từ chối sau khi đã từng bị kết tội OWI là hai năm."},"tl":{"q":"Sa Indiana, tumanggi sa chemical test ang isang driver na may naunang conviction sa lasing na pagmamaneho (OWI). Gaano katagal ang suspensyon?","o":["90 araw","1 taon","180 araw","2 taon"],"h1":"Dahil sa naunang conviction, mas matagal ito kaysa sa unang pagtanggi.","h2":"Sa Indiana, ang driver na may naunang OWI conviction na tumanggi sa chemical test ay masususpinde nang dalawang taon.","p":"Tama. Ang pagtanggi pagkatapos ng naunang OWI conviction ay dalawang taon."},"ar":{"q":"في Indiana، سائق سبقت إدانته بالقيادة تحت تأثير الكحول (OWI) يرفض الفحص الكيميائي. كم مدة التعليق؟","o":["90 يومًا","سنة واحدة (1)","180 يومًا","سنتان (2)"],"h1":"الإدانة السابقة تجعل المدة أطول من أول رفض.","h2":"في Indiana، السائق الذي سبقت إدانته بـ OWI ويرفض الفحص الكيميائي يُعلَّق لمدة سنتين.","p":"صحيح. الرفض بعد إدانة سابقة بـ OWI يعني سنتين."},"ref":{"doc":"IN","page":24}},{"id":"in-040","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, your license was suspended for the first time for driving without insurance. What is the reinstatement fee?","o":["$250","$1,000","$50","$500"],"h1":"The fee goes up with each new suspension.","h2":"In Indiana, the reinstatement fee for a first no-insurance suspension is $250.","p":"Right. A first no-insurance suspension costs $250 to reinstate."},"es":{"q":"En Indiana, le suspendieron la licencia por primera vez por manejar sin seguro. ¿Cuánto cuesta la cuota para restablecerla?","o":["$250","$1,000","$50","$500"],"h1":"La cuota sube con cada nueva suspensión.","h2":"En Indiana, la cuota para restablecer la licencia después de una primera suspensión por no tener seguro es de $250.","p":"Correcto. La primera suspensión por no tener seguro cuesta $250."},"zh":{"q":"在 Indiana，你的驾照第一次因为没有保险开车而被暂停。恢复驾照的费用是多少？","o":["$250","$1,000","$50","$500"],"h1":"每多一次暂停，费用就会增加。","h2":"在 Indiana，第一次因为没有保险被暂停，恢复驾照的费用是 $250。","p":"对。第一次没保险被暂停，恢复要 $250。"},"vi":{"q":"Ở Indiana, bằng lái của bạn bị đình chỉ lần đầu vì lái xe không có bảo hiểm. Phí phục hồi bằng lái là bao nhiêu?","o":["$250","$1,000","$50","$500"],"h1":"Phí tăng lên mỗi lần bị đình chỉ mới.","h2":"Ở Indiana, phí phục hồi cho lần đình chỉ đầu tiên vì không có bảo hiểm là $250.","p":"Đúng. Lần đình chỉ đầu tiên vì không có bảo hiểm tốn $250 để phục hồi."},"tl":{"q":"Sa Indiana, nasuspinde ang lisensya mo sa unang pagkakataon dahil nagmaneho ka nang walang insurance. Magkano ang reinstatement fee?","o":["$250","$1,000","$50","$500"],"h1":"Tumataas ang bayad sa bawat bagong suspensyon.","h2":"Sa Indiana, $250 ang reinstatement fee para sa unang suspensyon dahil walang insurance.","p":"Tama. $250 ang bayad para maibalik ang lisensya sa unang suspensyon dahil walang insurance."},"ar":{"q":"في Indiana، عُلّقت رخصتك لأول مرة بسبب القيادة بدون تأمين. كم رسوم إعادة الرخصة؟","o":["$250","$1,000","$50","$500"],"h1":"الرسوم تزيد مع كل تعليق جديد.","h2":"في Indiana، رسوم إعادة الرخصة بعد أول تعليق بسبب عدم وجود تأمين هي $250.","p":"صحيح. إعادة الرخصة بعد أول تعليق بسبب عدم التأمين تكلّف $250."},"ref":{"doc":"IN","page":23}},{"id":"in-041","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you are 30 years old and have 6 active points on your record. What must you do to renew your license?","o":["Take a driving skills exam","Wait one year before renewing","Take the knowledge exam","Nothing extra; just pay the fee"],"h1":"It is a written test, not a road test.","h2":"In Indiana, a driver 21 or older with six or more active points must take the knowledge exam to renew a license.","p":"Right. Six or more active points means taking the knowledge exam."},"es":{"q":"En Indiana, usted tiene 30 años y 6 puntos activos en su historial. ¿Qué debe hacer para renovar su licencia?","o":["Tomar un examen práctico de manejo","Esperar un año antes de renovar","Tomar el examen de conocimientos","Nada más; solo pagar la cuota"],"h1":"Es un examen escrito, no de manejo.","h2":"En Indiana, un conductor de 21 años o más con seis o más puntos activos debe tomar el examen de conocimientos para renovar la licencia.","p":"Correcto. Seis o más puntos activos significa tomar el examen de conocimientos."},"zh":{"q":"在 Indiana，你 30 岁，记录上有 6 个有效扣分。你要续期驾照必须做什么？","o":["参加路考","等一年再续期","参加笔试","不用做别的，只要交费"],"h1":"这是笔试，不是路考。","h2":"在 Indiana，21 岁或以上、有六个或更多有效扣分的司机，续期驾照时必须参加笔试。","p":"对。有六个或更多有效扣分，就要参加笔试。"},"vi":{"q":"Ở Indiana, bạn 30 tuổi và có 6 điểm phạt còn hiệu lực trong hồ sơ. Bạn phải làm gì để gia hạn bằng lái?","o":["Thi kỹ năng lái xe","Chờ một năm rồi mới gia hạn","Thi lý thuyết","Không cần làm gì thêm; chỉ cần trả phí"],"h1":"Đó là bài thi viết, không phải thi lái trên đường.","h2":"Ở Indiana, người lái xe từ 21 tuổi trở lên có từ sáu điểm phạt còn hiệu lực trở lên phải thi lý thuyết để gia hạn bằng lái.","p":"Đúng. Có từ sáu điểm còn hiệu lực trở lên thì phải thi lý thuyết."},"tl":{"q":"Sa Indiana, 30 taong gulang ka at may 6 na aktibong point sa record mo. Ano ang dapat mong gawin para ma-renew ang lisensya mo?","o":["Kumuha ng driving skills exam","Maghintay nang isang taon bago mag-renew","Kumuha ng knowledge exam","Wala nang iba; magbayad lang ng fee"],"h1":"Ito ay nakasulat na test, hindi road test.","h2":"Sa Indiana, ang driver na 21 taong gulang pataas na may anim o higit pang aktibong point ay dapat kumuha ng knowledge exam para ma-renew ang lisensya.","p":"Tama. Kapag may anim o higit pang aktibong point, kukuha ka ng knowledge exam."},"ar":{"q":"في Indiana، عمرك 30 سنة ولديك 6 نقاط فعّالة في سجلك. ماذا يجب أن تفعل لتجديد رخصتك؟","o":["تتقدّم لامتحان مهارات القيادة","تنتظر سنة واحدة قبل التجديد","تتقدّم للامتحان النظري","لا شيء إضافي؛ تدفع الرسوم فقط"],"h1":"هو امتحان مكتوب، وليس امتحانًا على الطريق.","h2":"في Indiana، السائق الذي عمره 21 سنة أو أكثر ولديه ست نقاط فعّالة أو أكثر يجب أن يتقدّم للامتحان النظري لتجديد الرخصة.","p":"صحيح. ست نقاط فعّالة أو أكثر تعني أنك تتقدّم للامتحان النظري."},"ref":{"doc":"IN","page":19}},{"id":"in-042","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, what is the speed limit on a rural state divided highway when no other limit is posted?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"It is lower than the rural interstate limit.","h2":"In Indiana, the speed limit on a rural state divided highway is 60 mph unless another limit is posted.","p":"Right. A rural state divided highway is 60 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en una carretera estatal dividida en zona rural cuando no hay otro límite indicado?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"Es más bajo que el límite de una interestatal rural.","h2":"En Indiana, el límite de velocidad en una carretera estatal dividida en zona rural es de 60 millas por hora, a menos que haya otro límite indicado.","p":"Correcto. Una carretera estatal dividida rural es de 60 mph."},"zh":{"q":"在 Indiana，如果没有标出其他限速，乡村州立分隔公路的限速是多少？","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"它比乡村州际公路的限速低。","h2":"在 Indiana，乡村州立分隔公路的限速是 60 mph，除非标出了其他限速。","p":"对。乡村州立分隔公路是 60 mph。"},"vi":{"q":"Ở Indiana, tốc độ giới hạn trên xa lộ có dải phân cách của tiểu bang ở vùng nông thôn là bao nhiêu khi không có biển báo tốc độ khác?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"Thấp hơn tốc độ giới hạn trên xa lộ liên bang (interstate) ở vùng nông thôn.","h2":"Ở Indiana, tốc độ giới hạn trên xa lộ có dải phân cách của tiểu bang ở vùng nông thôn là 60 mph, trừ khi có biển báo tốc độ khác.","p":"Đúng. Xa lộ có dải phân cách của tiểu bang ở vùng nông thôn là 60 mph."},"tl":{"q":"Sa Indiana, ano ang speed limit sa rural state divided highway kapag walang ibang limit na nakapaskil?","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"Mas mababa ito sa limit sa rural interstate.","h2":"Sa Indiana, 60 mph ang speed limit sa rural state divided highway maliban kung may ibang limit na nakapaskil.","p":"Tama. 60 mph ang rural state divided highway."},"ar":{"q":"في Indiana، ما حد السرعة على طريق سريع مقسوم تابع للولاية في منطقة ريفية عندما لا توجد لافتة بحد آخر؟","o":["45 mph","60 mph","70 mph","50 mph"],"h1":"هو أقل من حد السرعة على الطريق السريع بين الولايات (interstate) في المناطق الريفية.","h2":"في Indiana، حد السرعة على طريق سريع مقسوم تابع للولاية في منطقة ريفية هو 60 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. الطريق السريع المقسوم التابع للولاية في منطقة ريفية حده 60 mph."},"ref":{"doc":"IN","page":40}},{"id":"in-043","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, what is the speed limit in an alley when no other limit is posted?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"It is the lowest of these choices.","h2":"In Indiana, the speed limit in an alley is 15 mph unless another limit is posted.","p":"Right. The alley limit is 15 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en un callejón cuando no hay otro límite indicado?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"Es el más bajo de estas opciones.","h2":"En Indiana, el límite de velocidad en un callejón es de 15 millas por hora, a menos que haya otro límite indicado.","p":"Correcto. En un callejón el límite es 15 mph."},"zh":{"q":"在 Indiana，如果没有标出其他限速，小巷里的限速是多少？","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"它是这些选项里最低的。","h2":"在 Indiana，小巷里的限速是 15 mph，除非标出了其他限速。","p":"对。小巷的限速是 15 mph。"},"vi":{"q":"Ở Indiana, tốc độ giới hạn trong hẻm là bao nhiêu khi không có biển báo tốc độ khác?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"Đó là con số thấp nhất trong các lựa chọn này.","h2":"Ở Indiana, tốc độ giới hạn trong hẻm là 15 mph, trừ khi có biển báo tốc độ khác.","p":"Đúng. Tốc độ giới hạn trong hẻm là 15 mph."},"tl":{"q":"Sa Indiana, ano ang speed limit sa eskinita (alley) kapag walang ibang limit na nakapaskil?","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"Ito ang pinakamababa sa mga pagpipiliang ito.","h2":"Sa Indiana, 15 mph ang speed limit sa eskinita maliban kung may ibang limit na nakapaskil.","p":"Tama. 15 mph ang limit sa eskinita."},"ar":{"q":"في Indiana، ما حد السرعة في الزقاق عندما لا توجد لافتة بحد آخر؟","o":["30 mph","25 mph","20 mph","15 mph"],"h1":"هو الأقل بين هذه الاختيارات.","h2":"في Indiana، حد السرعة في الزقاق هو 15 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. حد السرعة في الزقاق هو 15 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-044","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, you are driving behind another vehicle at night with high beams on. How close may you get before you must switch to low beams?","o":["Within 200 feet","Within 50 feet","Within 1,000 feet","Within 500 feet"],"h1":"The distance for a car ahead is shorter than for an oncoming car.","h2":"In Indiana, you must use low beams when you are following within 200 feet of another vehicle.","p":"Right. Dim your lights within 200 feet of the car ahead."},"es":{"q":"En Indiana, de noche usted maneja detrás de otro vehículo con las luces altas. ¿A qué distancia debe cambiar a luces bajas?","o":["A 200 pies o menos","A 50 pies o menos","A 1,000 pies o menos","A 500 pies o menos"],"h1":"La distancia para un auto adelante es menor que para uno que viene de frente.","h2":"En Indiana, debe usar luces bajas cuando va a 200 pies o menos detrás de otro vehículo.","p":"Correcto. Baje las luces a 200 pies del auto de adelante."},"zh":{"q":"在 Indiana，你晚上开着远光灯跟在另一辆车后面。离它多近时你必须换成近光灯？","o":["200 英尺之内","50 英尺之内","1,000 英尺之内","500 英尺之内"],"h1":"跟前车的距离比对面来车的距离短。","h2":"在 Indiana，当你跟在另一辆车后面 200 英尺之内时，必须用近光灯。","p":"对。离前车 200 英尺之内要换近光灯。"},"vi":{"q":"Ở Indiana, bạn đang lái sau một xe khác vào ban đêm và bật đèn pha (đèn chiếu xa). Bạn được đến gần bao nhiêu trước khi phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Trong vòng 200 feet","Trong vòng 50 feet","Trong vòng 1,000 feet","Trong vòng 500 feet"],"h1":"Khoảng cách với xe phía trước ngắn hơn khoảng cách với xe đi ngược chiều.","h2":"Ở Indiana, bạn phải dùng đèn cốt khi bạn đang chạy sau một xe khác trong vòng 200 feet.","p":"Đúng. Hạ đèn khi cách xe phía trước trong vòng 200 feet."},"tl":{"q":"Sa Indiana, nagmamaneho ka sa likod ng ibang sasakyan sa gabi na naka-high beam. Gaano kalapit ka puwedeng lumapit bago ka dapat lumipat sa low beam?","o":["Sa loob ng 200 feet","Sa loob ng 50 feet","Sa loob ng 1,000 feet","Sa loob ng 500 feet"],"h1":"Mas maikli ang layo para sa sasakyan sa unahan kaysa sa paparating na sasakyan.","h2":"Sa Indiana, dapat kang gumamit ng low beam kapag sumusunod ka sa ibang sasakyan sa loob ng 200 feet.","p":"Tama. Ibaba ang ilaw sa loob ng 200 feet ng sasakyan sa unahan."},"ar":{"q":"في Indiana، تقود ليلًا خلف مركبة أخرى والأضواء العالية مشغّلة. إلى أي مسافة يمكنك أن تقترب قبل أن يجب عليك التحويل إلى الأضواء المنخفضة؟","o":["ضمن 200 feet","ضمن 50 feet","ضمن 1,000 feet","ضمن 500 feet"],"h1":"المسافة للسيارة التي أمامك أقصر من المسافة للسيارة القادمة من الاتجاه المعاكس.","h2":"في Indiana، يجب أن تستخدم الأضواء المنخفضة عندما تسير خلف مركبة أخرى ضمن 200 feet.","p":"صحيح. خفّض أضواءك ضمن 200 feet من السيارة التي أمامك."},"ref":{"doc":"IN","page":44}},{"id":"in-045","scope":"IN","cat":"signals","sign":null,"c":2,"en":{"q":"In Indiana, a motorcycle rider is stuck at a red light that does not turn green. What may the rider do?","o":["Wait for green, no matter how long","Go after a 10-second stop","Go with care after stopping for at least two minutes","Turn on hazard lights and go at once"],"h1":"The rider must stop fully and wait a set time first.","h2":"In Indiana, a motorcycle rider at a red light that does not change may go with care after a complete stop of at least two minutes.","p":"Right. After a full stop of at least two minutes, the rider may go with care."},"es":{"q":"En Indiana, un motociclista está detenido en un semáforo en rojo que no cambia a verde. ¿Qué puede hacer?","o":["Esperar la luz verde, sin importar cuánto tarde","Avanzar después de parar 10 segundos","Avanzar con cuidado después de parar al menos dos minutos","Prender las luces de emergencia y avanzar enseguida"],"h1":"Primero debe parar por completo y esperar un tiempo fijo.","h2":"En Indiana, un motociclista en un semáforo en rojo que no cambia puede avanzar con cuidado después de parar por completo al menos dos minutos.","p":"Correcto. Después de parar al menos dos minutos, puede avanzar con cuidado."},"zh":{"q":"在 Indiana，一名摩托车骑手停在红灯前，红灯一直不变绿。骑手可以怎么做？","o":["不管多久都要等绿灯","停 10 秒以后就走","完全停车至少两分钟以后，小心通过","打开双闪灯，马上走"],"h1":"骑手必须先完全停车，并等一段规定的时间。","h2":"在 Indiana，摩托车骑手遇到一直不变的红灯时，完全停车至少两分钟以后，可以小心通过。","p":"对。完全停车至少两分钟以后，骑手可以小心通过。"},"vi":{"q":"Ở Indiana, một người lái xe máy bị kẹt ở đèn đỏ mà đèn không chuyển sang xanh. Người lái xe máy được làm gì?","o":["Chờ đèn xanh, dù lâu bao nhiêu","Đi sau khi dừng 10 giây","Đi một cách cẩn thận sau khi dừng ít nhất hai phút","Bật đèn khẩn cấp và đi ngay"],"h1":"Người lái phải dừng hẳn và chờ một khoảng thời gian nhất định trước.","h2":"Ở Indiana, người lái xe máy ở đèn đỏ không đổi màu được đi một cách cẩn thận sau khi dừng hẳn ít nhất hai phút.","p":"Đúng. Sau khi dừng hẳn ít nhất hai phút, người lái được đi một cách cẩn thận."},"tl":{"q":"Sa Indiana, naipit ang isang motorcycle rider sa red light na hindi nagiging green. Ano ang puwedeng gawin ng rider?","o":["Maghintay ng green, gaano man katagal","Umandar pagkatapos ng 10 segundong paghinto","Umandar nang maingat pagkatapos huminto nang hindi bababa sa dalawang minuto","Buksan ang hazard lights at umandar agad"],"h1":"Dapat munang huminto nang tuluyan ang rider at maghintay ng takdang oras.","h2":"Sa Indiana, ang motorcycle rider sa red light na hindi nagbabago ay puwedeng umandar nang maingat pagkatapos ng tuluyang paghinto nang hindi bababa sa dalawang minuto.","p":"Tama. Pagkatapos ng tuluyang paghinto nang hindi bababa sa dalawang minuto, puwedeng umandar nang maingat ang rider."},"ar":{"q":"في Indiana، سائق دراجة نارية عالق عند إشارة حمراء لا تتحوّل إلى خضراء. ماذا يمكن أن يفعل السائق؟","o":["ينتظر الإشارة الخضراء مهما طال الوقت","يتحرك بعد توقف 10 ثوانٍ","يتحرك بحذر بعد التوقف دقيقتين على الأقل","يشغّل أضواء الطوارئ ويتحرك فورًا"],"h1":"يجب أن يتوقف السائق تمامًا وينتظر وقتًا محدّدًا أولًا.","h2":"في Indiana، سائق الدراجة النارية عند إشارة حمراء لا تتغيّر يمكنه أن يتحرك بحذر بعد توقف كامل لمدة دقيقتين على الأقل.","p":"صحيح. بعد توقف كامل لمدة دقيقتين على الأقل، يمكن للسائق أن يتحرك بحذر."},"ref":{"doc":"IN","page":35}},{"id":"in-046","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a driver commits aggressive driving when, in one trip, the driver does at least how many acts such as tailgating, honking for no reason, or flashing headlights again and again?","o":["One","Three","Two","Five"],"h1":"It takes more than a pair of these acts.","h2":"In Indiana, a driver commits aggressive driving by doing at least three of the listed unsafe acts during one episode of driving.","p":"Right. Three or more of these acts in one trip is aggressive driving."},"es":{"q":"En Indiana, ¿cuántos actos como seguir muy de cerca, tocar la bocina sin razón o hacer cambio de luces una y otra vez debe hacer un conductor, como mínimo, en un mismo viaje para que sea manejo agresivo?","o":["Uno","Tres","Dos","Cinco"],"h1":"Se necesita más de un par de estos actos.","h2":"En Indiana, un conductor maneja de forma agresiva cuando hace al menos tres de los actos peligrosos de la lista en un mismo viaje.","p":"Correcto. Tres o más de estos actos en un viaje es manejo agresivo."},"zh":{"q":"在 Indiana，一名司机在一次行程中，至少做了几种这样的行为（比如跟车太近、无故按喇叭、或一次又一次闪大灯），就算是攻击性驾驶？","o":["一种","三种","两种","五种"],"h1":"不止两种这样的行为。","h2":"在 Indiana，一名司机在一次驾驶中做了至少三种列出的不安全行为，就算是攻击性驾驶。","p":"对。一次行程中做了三种或更多这样的行为，就是攻击性驾驶。"},"vi":{"q":"Ở Indiana, một người lái xe bị coi là lái xe hung hăng (aggressive driving) khi, trong một chuyến đi, người đó làm ít nhất bao nhiêu hành vi như bám đuôi quá sát, bấm còi không lý do, hoặc nháy đèn pha liên tục?","o":["Một","Ba","Hai","Năm"],"h1":"Cần nhiều hơn hai hành vi như vậy.","h2":"Ở Indiana, một người lái xe bị coi là lái xe hung hăng khi làm ít nhất ba hành vi không an toàn trong danh sách trong một lần lái xe.","p":"Đúng. Ba hành vi trở lên trong một chuyến đi là lái xe hung hăng."},"tl":{"q":"Sa Indiana, gumagawa ng aggressive driving ang isang driver kapag, sa isang biyahe, gumawa siya ng hindi bababa sa ilang gawain tulad ng pagbuntot nang masyadong malapit, pagbusina nang walang dahilan, o paulit-ulit na pag-flash ng headlights?","o":["Isa","Tatlo","Dalawa","Lima"],"h1":"Higit pa ito sa isang pares ng mga gawaing ito.","h2":"Sa Indiana, gumagawa ng aggressive driving ang driver kapag gumawa siya ng hindi bababa sa tatlo sa mga nakalistang hindi ligtas na gawain sa isang pagmamaneho.","p":"Tama. Tatlo o higit pa sa mga gawaing ito sa isang biyahe ay aggressive driving."},"ar":{"q":"في Indiana، يُعتبر السائق مرتكبًا للقيادة العدوانية (aggressive driving) عندما يقوم في رحلة واحدة بكم فعل على الأقل، مثل الاقتراب الشديد من السيارة التي أمامه، أو استخدام البوق بلا سبب، أو وميض المصابيح الأمامية مرة بعد مرة؟","o":["فعل واحد","ثلاثة أفعال","فعلان","خمسة أفعال"],"h1":"يلزم أكثر من فعلين من هذه الأفعال.","h2":"في Indiana، يُعتبر السائق مرتكبًا للقيادة العدوانية إذا قام بثلاثة على الأقل من الأفعال غير الآمنة المذكورة خلال قيادة واحدة.","p":"صحيح. ثلاثة أفعال أو أكثر من هذه في رحلة واحدة تُعتبر قيادة عدوانية."},"ref":{"doc":"IN","page":46}},{"id":"in-047","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, a driver recklessly passes a stopped school bus with its stop arm out, and no one is hurt. What kind of offense is this?","o":["A warning only","A parking ticket","A Class C infraction","A Class A misdemeanor"],"h1":"It is a crime, not just a ticket.","h2":"In Indiana, recklessly passing a school bus with its stop arm out is a Class A misdemeanor, and it becomes a felony if someone is hurt or killed.","p":"Right. Reckless passing of a stopped school bus is a Class A misdemeanor."},"es":{"q":"En Indiana, un conductor rebasa de forma imprudente un autobús escolar detenido con el brazo de alto extendido, y nadie sale herido. ¿Qué tipo de delito es?","o":["Solo una advertencia","Una multa de estacionamiento","Una infracción Clase C","Un delito menor Clase A"],"h1":"Es un delito, no solo una multa.","h2":"En Indiana, rebasar de forma imprudente un autobús escolar con el brazo de alto extendido es un delito menor Clase A, y pasa a ser un delito grave si alguien sale herido o muere.","p":"Correcto. Rebasar de forma imprudente un autobús escolar detenido es un delito menor Clase A."},"zh":{"q":"在 Indiana，一名司机鲁莽地超过一辆伸出停车臂（stop arm）的停着的校车，没有人受伤。这是哪一种违法行为？","o":["只是警告","停车罚单","C 级违规（Class C infraction）","A 级轻罪（Class A misdemeanor）"],"h1":"这是犯罪，不只是一张罚单。","h2":"在 Indiana，鲁莽地超过伸出停车臂的校车是 A 级轻罪（Class A misdemeanor），如果有人受伤或死亡，就会变成重罪（felony）。","p":"对。鲁莽超过停着的校车是 A 级轻罪。"},"vi":{"q":"Ở Indiana, một người lái xe vượt ẩu qua một xe buýt trường học đang dừng và đang mở cần báo dừng (stop arm), và không ai bị thương. Đây là loại vi phạm gì?","o":["Chỉ bị cảnh cáo","Một vé phạt đậu xe","Vi phạm hạng C (Class C infraction)","Tội nhẹ hạng A (Class A misdemeanor)"],"h1":"Đây là một tội hình sự, không chỉ là một vé phạt.","h2":"Ở Indiana, vượt ẩu qua xe buýt trường học đang mở cần báo dừng là tội nhẹ hạng A (Class A misdemeanor), và sẽ thành trọng tội (felony) nếu có người bị thương hoặc bị chết.","p":"Đúng. Vượt ẩu qua xe buýt trường học đang dừng là tội nhẹ hạng A."},"tl":{"q":"Sa Indiana, walang-ingat na nilampasan ng isang driver ang nakahintong school bus na nakalabas ang stop arm, at walang nasaktan. Anong uri ng paglabag ito?","o":["Babala lang","Isang parking ticket","Isang Class C infraction","Isang Class A misdemeanor"],"h1":"Isa itong krimen, hindi lang tiket.","h2":"Sa Indiana, ang walang-ingat na paglampas sa school bus na nakalabas ang stop arm ay isang Class A misdemeanor, at nagiging felony ito kapag may nasaktan o namatay.","p":"Tama. Ang walang-ingat na paglampas sa nakahintong school bus ay isang Class A misdemeanor."},"ar":{"q":"في Indiana، تجاوز سائق بتهوّر حافلة مدرسية متوقفة وذراع التوقف (stop arm) فيها ممدودة، ولم يُصَب أحد. ما نوع هذه المخالفة؟","o":["تحذير فقط","مخالفة وقوف","مخالفة من الفئة C (Class C infraction)","جنحة من الفئة A (Class A misdemeanor)"],"h1":"هذه جريمة، وليست مجرد مخالفة.","h2":"في Indiana، تجاوز حافلة مدرسية بتهوّر وذراع التوقف فيها ممدودة جنحة من الفئة A (Class A misdemeanor)، وتصبح جناية (felony) إذا أُصيب أحد أو مات.","p":"صحيح. تجاوز حافلة مدرسية متوقفة بتهوّر جنحة من الفئة A."},"ref":{"doc":"IN","page":52}},{"id":"in-048","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, on a regular road with no bike path, how many bicyclists may ride side by side?","o":["No more than two","Only one; never side by side","Up to four","Any number"],"h1":"Think of a pair.","h2":"In Indiana, bicyclists may not ride more than two side by side, except on paths or lanes set aside for bicycles.","p":"Right. No more than two side by side."},"es":{"q":"En Indiana, en un camino normal sin ciclovía, ¿cuántos ciclistas pueden ir uno al lado del otro?","o":["No más de dos","Solo uno; nunca lado a lado","Hasta cuatro","Cualquier número"],"h1":"Piense en una pareja.","h2":"En Indiana, los ciclistas no pueden ir más de dos lado a lado, excepto en caminos o carriles solo para bicicletas.","p":"Correcto. No más de dos lado a lado."},"zh":{"q":"在 Indiana，在没有自行车道的普通道路上，最多可以有几个骑自行车的人并排骑？","o":["最多两个","只能一个，绝对不能并排","最多四个","几个都可以"],"h1":"想想一对。","h2":"在 Indiana，骑自行车的人不能超过两个并排骑，专门给自行车用的道路或车道除外。","p":"对。最多两个人并排。"},"vi":{"q":"Ở Indiana, trên đường thông thường không có lối đi cho xe đạp, bao nhiêu người đi xe đạp được chạy song song với nhau?","o":["Không quá hai người","Chỉ một người; không bao giờ chạy song song","Tối đa bốn người","Bao nhiêu cũng được"],"h1":"Hãy nghĩ đến một cặp.","h2":"Ở Indiana, người đi xe đạp không được chạy song song quá hai người, trừ trên lối đi hoặc làn đường dành riêng cho xe đạp.","p":"Đúng. Không quá hai người chạy song song."},"tl":{"q":"Sa Indiana, sa karaniwang daan na walang bike path, ilang nagbibisikleta ang puwedeng magkatabi?","o":["Hindi hihigit sa dalawa","Isa lang; hindi kailanman magkatabi","Hanggang apat","Kahit ilan"],"h1":"Isipin ang isang pares.","h2":"Sa Indiana, hindi puwedeng magbisikleta nang higit sa dalawang magkatabi, maliban sa mga path o lane na nakalaan para sa bisikleta.","p":"Tama. Hindi hihigit sa dalawang magkatabi."},"ar":{"q":"في Indiana، على طريق عادي بدون ممر للدراجات، كم راكب دراجة يمكن أن يسيروا جنبًا إلى جنب؟","o":["اثنان كحدّ أقصى","واحد فقط؛ لا يسيران جنبًا إلى جنب أبدًا","حتى أربعة","أي عدد"],"h1":"فكّر في زوج.","h2":"في Indiana، يجب ألّا يسير أكثر من اثنين من راكبي الدراجات جنبًا إلى جنب، إلا على الممرات أو المسارات المخصّصة للدراجات.","p":"صحيح. اثنان كحدّ أقصى جنبًا إلى جنب."},"ref":{"doc":"IN","page":52}},{"id":"in-049","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, how much following time should you leave behind a motorcycle?","o":["About one second","Half a second","At least three or four seconds","No set gap; stay close so the rider sees you"],"h1":"Give more time than you might behind a car.","h2":"In Indiana, you should leave at least three or four seconds when following a motorcycle.","p":"Right. Leave at least three or four seconds behind a motorcycle."},"es":{"q":"En Indiana, ¿cuánto tiempo de distancia debe dejar detrás de una motocicleta?","o":["Como un segundo","Medio segundo","Al menos tres o cuatro segundos","Ninguno fijo; vaya cerca para que el motociclista lo vea"],"h1":"Deje más tiempo del que dejaría detrás de un auto.","h2":"En Indiana, debe dejar al menos tres o cuatro segundos cuando sigue a una motocicleta.","p":"Correcto. Deje al menos tres o cuatro segundos detrás de una motocicleta."},"zh":{"q":"在 Indiana，跟在摩托车后面时，你应该留多少跟车时间？","o":["大约一秒","半秒","至少三到四秒","没有固定距离，靠近一点让骑手看到你"],"h1":"要比跟在汽车后面时留更多时间。","h2":"在 Indiana，跟在摩托车后面时，你应该留至少三到四秒。","p":"对。跟在摩托车后面至少留三到四秒。"},"vi":{"q":"Ở Indiana, khi chạy sau một xe máy, bạn nên giữ khoảng cách thời gian bao nhiêu?","o":["Khoảng một giây","Nửa giây","Ít nhất ba hoặc bốn giây","Không có khoảng cách nhất định; chạy sát để người lái thấy bạn"],"h1":"Hãy để nhiều thời gian hơn so với khi chạy sau xe hơi.","h2":"Ở Indiana, bạn nên giữ ít nhất ba hoặc bốn giây khi chạy sau một xe máy.","p":"Đúng. Giữ ít nhất ba hoặc bốn giây sau xe máy."},"tl":{"q":"Sa Indiana, gaano karaming following time ang dapat mong iwan sa likod ng motorsiklo?","o":["Mga isang segundo","Kalahating segundo","Hindi bababa sa tatlo o apat na segundo","Walang takdang agwat; lumapit para makita ka ng rider"],"h1":"Magbigay ng mas mahabang oras kaysa sa likod ng kotse.","h2":"Sa Indiana, dapat kang mag-iwan ng hindi bababa sa tatlo o apat na segundo kapag sumusunod ka sa motorsiklo.","p":"Tama. Mag-iwan ng hindi bababa sa tatlo o apat na segundo sa likod ng motorsiklo."},"ar":{"q":"في Indiana، كم وقتًا يجب أن تترك عندما تسير خلف دراجة نارية؟","o":["حوالي ثانية واحدة","نصف ثانية","ثلاث أو أربع ثوانٍ على الأقل","لا توجد مسافة محدّدة؛ ابقَ قريبًا ليراك السائق"],"h1":"اترك وقتًا أكثر مما قد تتركه خلف سيارة.","h2":"في Indiana، يجب أن تترك ثلاث أو أربع ثوانٍ على الأقل عندما تسير خلف دراجة نارية.","p":"صحيح. اترك ثلاث أو أربع ثوانٍ على الأقل خلف الدراجة النارية."},"ref":{"doc":"IN","page":52}},{"id":"in-050","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, children younger than what age must ride in a child car seat or booster seat?","o":["Younger than 2","Younger than 4","Younger than 5","Younger than 8"],"h1":"The age is in the early school years.","h2":"In Indiana, passengers younger than eight must be secured in a child restraint, such as a car seat or booster seat.","p":"Right. Children under 8 need a car seat or booster seat."},"es":{"q":"En Indiana, ¿los niños menores de qué edad deben ir en un asiento de seguridad o asiento elevado?","o":["Menores de 2","Menores de 4","Menores de 5","Menores de 8"],"h1":"La edad está en los primeros años de escuela.","h2":"En Indiana, los pasajeros menores de ocho años deben ir asegurados en un sistema para niños, como un asiento de seguridad o un asiento elevado.","p":"Correcto. Los niños menores de 8 necesitan asiento de seguridad o elevado."},"zh":{"q":"在 Indiana，几岁以下的孩子必须坐儿童安全座椅或增高座椅？","o":["2 岁以下","4 岁以下","5 岁以下","8 岁以下"],"h1":"这个年龄是在刚上学的那几年。","h2":"在 Indiana，八岁以下的乘客必须用儿童约束装置固定好，比如儿童安全座椅或增高座椅。","p":"对。8 岁以下的孩子要坐儿童安全座椅或增高座椅。"},"vi":{"q":"Ở Indiana, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng (booster seat)?","o":["Dưới 2 tuổi","Dưới 4 tuổi","Dưới 5 tuổi","Dưới 8 tuổi"],"h1":"Độ tuổi này là những năm đầu đi học.","h2":"Ở Indiana, hành khách dưới tám tuổi phải được giữ an toàn bằng thiết bị dành cho trẻ em, như ghế an toàn hoặc ghế nâng.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn hoặc ghế nâng."},"tl":{"q":"Sa Indiana, ang mga batang wala pa sa anong edad ang dapat nakaupo sa child car seat o booster seat?","o":["Wala pang 2","Wala pang 4","Wala pang 5","Wala pang 8"],"h1":"Ang edad ay nasa mga unang taon ng pag-aaral.","h2":"Sa Indiana, ang mga pasaherong wala pang walong taong gulang ay dapat nakakabit sa child restraint, tulad ng car seat o booster seat.","p":"Tama. Kailangan ng car seat o booster seat ang mga batang wala pang 8."},"ar":{"q":"في Indiana، الأطفال الذين عمرهم أقل من كم سنة يجب أن يجلسوا في مقعد سيارة للأطفال أو مقعد رافع (booster seat)؟","o":["أقل من 2","أقل من 4","أقل من 5","أقل من 8"],"h1":"هذا العمر في السنوات الأولى من المدرسة.","h2":"في Indiana، الركاب الذين عمرهم أقل من ثماني سنوات يجب أن يُثبَّتوا في وسيلة أمان للأطفال، مثل مقعد سيارة للأطفال أو مقعد رافع.","p":"صحيح. الأطفال تحت 8 سنوات يحتاجون إلى مقعد سيارة للأطفال أو مقعد رافع."},"ref":{"doc":"IN","page":56}},{"id":"in-051","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, a police car signals you to pull over. What does the driver's manual suggest you do first to show the officer you see them?","o":["Get out and walk to the police car","Turn on your right turn signal","Stop at once in the center median","Call the officer on your phone"],"h1":"Use something already in your car that other drivers can see.","h2":"In Indiana, the manual suggests you turn on your right turn signal to show the officer you know they are there, then pull onto the right shoulder.","p":"Right. Turn on your right turn signal, then pull to the right."},"es":{"q":"En Indiana, una patrulla le indica que se orille. ¿Qué sugiere el manual que haga primero para mostrar al policía que lo vio?","o":["Bajarse y caminar hacia la patrulla","Prender la direccional derecha","Parar enseguida en el camellón central","Llamar al policía por teléfono"],"h1":"Use algo de su auto que los demás puedan ver.","h2":"En Indiana, el manual sugiere prender la direccional derecha para mostrar al policía que sabe que está ahí, y luego orillarse al acotamiento derecho.","p":"Correcto. Prenda la direccional derecha y luego oríllese a la derecha."},"zh":{"q":"在 Indiana，一辆警车示意你靠边停车。驾驶手册建议你先做什么，让警察知道你看到他们了？","o":["下车走到警车那里","打开你的右转向灯","马上停在中间的隔离带上","用手机打电话给警察"],"h1":"用你车上已经有的、其他司机能看到的东西。","h2":"在 Indiana，手册建议你打开右转向灯，让警察知道你看到他们了，然后把车开到右边的路肩上。","p":"对。打开右转向灯，然后靠右停。"},"vi":{"q":"Ở Indiana, một xe cảnh sát ra hiệu cho bạn tấp vào lề. Sổ tay lái xe khuyên bạn làm gì trước tiên để cho cảnh sát biết bạn đã thấy họ?","o":["Ra khỏi xe và đi bộ đến xe cảnh sát","Bật đèn xi-nhan phải","Dừng ngay trên dải phân cách giữa đường","Gọi điện thoại cho cảnh sát"],"h1":"Dùng thứ đã có sẵn trên xe mà người lái khác có thể thấy.","h2":"Ở Indiana, sổ tay khuyên bạn bật đèn xi-nhan phải để cho cảnh sát biết bạn đã thấy họ, rồi tấp vào lề bên phải.","p":"Đúng. Bật đèn xi-nhan phải, rồi tấp vào bên phải."},"tl":{"q":"Sa Indiana, sinenyasan ka ng isang police car na tumabi. Ano ang iminumungkahi ng driver's manual na gawin mo muna para ipakita sa pulis na nakikita mo sila?","o":["Bumaba at maglakad papunta sa police car","Buksan ang right turn signal mo","Huminto agad sa gitnang median","Tawagan ang pulis sa telepono mo"],"h1":"Gamitin ang isang bagay na nasa kotse mo na at nakikita ng ibang driver.","h2":"Sa Indiana, iminumungkahi ng manual na buksan mo ang right turn signal para ipakita sa pulis na alam mong nandiyan sila, at saka tumabi sa kanang shoulder.","p":"Tama. Buksan ang right turn signal, at saka tumabi sa kanan."},"ar":{"q":"في Indiana، تشير لك سيارة شرطة بأن تتوقف على جانب الطريق. ماذا يقترح دليل السائق أن تفعل أولًا لتُظهر للشرطي أنك تراه؟","o":["تنزل من السيارة وتمشي إلى سيارة الشرطة","تشغّل إشارة الانعطاف اليمنى","تتوقف فورًا على الجزيرة الوسطية","تتصل بالشرطي بهاتفك"],"h1":"استخدم شيئًا موجودًا في سيارتك ويمكن للسائقين الآخرين أن يروه.","h2":"في Indiana، يقترح الدليل أن تشغّل إشارة الانعطاف اليمنى لتُظهر للشرطي أنك تعرف أنه هناك، ثم تنتقل إلى الكتف الأيمن للطريق.","p":"صحيح. شغّل إشارة الانعطاف اليمنى، ثم انتقل إلى اليمين."},"ref":{"doc":"IN","page":60}},{"id":"in-052","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you are a new resident and have never held a driver's license anywhere. How long must you hold an Indiana learner's permit before you can apply for a license?","o":["180 days","30 days","90 days","One year"],"h1":"It is the same holding time Indiana uses for teens.","h2":"In Indiana, a new resident who has never held a valid license must hold an Indiana learner's permit for 180 days before applying for a driver's license.","p":"Right. You hold the permit for 180 days."},"es":{"q":"En Indiana, usted es residente nuevo y nunca ha tenido licencia de conducir en ningún lugar. ¿Cuánto tiempo debe tener un permiso de aprendizaje de Indiana antes de solicitar una licencia?","o":["180 días","30 días","90 días","Un año"],"h1":"Es el mismo tiempo de espera que Indiana usa para los adolescentes.","h2":"En Indiana, un residente nuevo que nunca ha tenido licencia válida debe tener un permiso de aprendizaje de Indiana por 180 días antes de solicitar la licencia de conducir.","p":"Correcto. Debe tener el permiso por 180 días."},"ref":{"doc":"IN","page":2}},{"id":"in-053","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you are 30 and just moved here. Your out-of-state license expired three years ago. What must you pass to get an Indiana license?","o":["Only a vision screening","A knowledge exam","A knowledge exam and a driving skills exam","Nothing; you can trade it in"],"h1":"The license expired less than five years ago.","h2":"In Indiana, if your out-of-state license has been expired for less than five years, you must pass a knowledge exam (plus the vision screening) to get an Indiana license.","p":"Correct. You take the knowledge exam."},"es":{"q":"En Indiana, usted tiene 30 años y acaba de mudarse aquí. Su licencia de otro estado venció hace tres años. ¿Qué debe aprobar para obtener una licencia de Indiana?","o":["Solo un examen de la vista","Un examen de conocimientos","Un examen de conocimientos y un examen práctico de manejo","Nada; puede cambiarla directamente"],"h1":"La licencia venció hace menos de cinco años.","h2":"En Indiana, si su licencia de otro estado venció hace menos de cinco años, debe aprobar un examen de conocimientos (además del examen de la vista) para obtener una licencia de Indiana.","p":"Correcto. Debe tomar el examen de conocimientos."},"ref":{"doc":"IN","page":2}},{"id":"in-054","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, a new resident's out-of-state license expired more than five years ago. What must the person pass?","o":["Only a vision screening","Only a knowledge exam","A knowledge exam and a driving skills exam","Only a driving skills exam"],"h1":"After more than five years, Indiana wants to see you drive again.","h2":"In Indiana, a new resident whose out-of-state license expired more than five years ago must pass both a knowledge exam and a driving skills exam.","p":"Right. Both the knowledge and the skills exams."},"es":{"q":"En Indiana, la licencia de otro estado de un residente nuevo venció hace más de cinco años. ¿Qué debe aprobar esa persona?","o":["Solo un examen de la vista","Solo un examen de conocimientos","Un examen de conocimientos y un examen práctico de manejo","Solo un examen práctico de manejo"],"h1":"Después de más de cinco años, Indiana quiere verlo manejar otra vez.","h2":"En Indiana, un residente nuevo cuya licencia de otro estado venció hace más de cinco años debe aprobar un examen de conocimientos y un examen práctico de manejo.","p":"Correcto. Ambos exámenes: conocimientos y manejo."},"ref":{"doc":"IN","page":2}},{"id":"in-055","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how can you tell at a glance that a license or permit belongs to someone under 21?","o":["It has a red border","It has no photo","It says PROBATION across the front","It is printed in a vertical (up-and-down) format"],"h1":"Think about the shape and direction of the card.","h2":"In Indiana, credentials for people under 21 are printed in a vertical format and show the dates the holder turns 18 and 21.","p":"Correct. Under-21 cards are vertical."},"es":{"q":"En Indiana, ¿cómo puede saber a simple vista que una licencia o permiso es de alguien menor de 21 años?","o":["Tiene un borde rojo","No tiene foto","Dice PROBATION en el frente","Está impreso en formato vertical (de arriba abajo)"],"h1":"Piense en la forma y la dirección de la tarjeta.","h2":"En Indiana, las credenciales de personas menores de 21 años se imprimen en formato vertical y muestran las fechas en que el titular cumple 18 y 21 años.","p":"Correcto. Las tarjetas de menores de 21 son verticales."},"ref":{"doc":"IN","page":1}},{"id":"in-056","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how can you tell if your license is Real ID compliant?","o":["It has a star in the upper right corner","It has a gold seal on the back","It has the word FEDERAL on the front","It has a blue photo background"],"h1":"Look at the top corner of the card.","h2":"In Indiana, a Real ID compliant credential has a star in the upper right corner.","p":"Right. Look for the star."},"es":{"q":"En Indiana, ¿cómo puede saber si su licencia cumple con Real ID?","o":["Tiene una estrella en la esquina superior derecha","Tiene un sello dorado atrás","Tiene la palabra FEDERAL en el frente","Tiene un fondo azul detrás de la foto"],"h1":"Mire la esquina de arriba de la tarjeta.","h2":"En Indiana, una credencial que cumple con Real ID tiene una estrella en la esquina superior derecha.","p":"Correcto. Busque la estrella."},"ref":{"doc":"IN","page":1}},{"id":"in-057","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, who can get a state identification card at no cost?","o":["Anyone who has a library card","A resident who is or will be 18 by the next general or municipal election","Only people older than 65","Only students in high school"],"h1":"It is connected to being able to vote.","h2":"In Indiana, an identification card is free for a resident who is 18, or will be 18 on or before the next general or municipal election.","p":"Correct. It is free for those old enough to vote."},"es":{"q":"En Indiana, ¿quién puede obtener una tarjeta de identificación estatal sin costo?","o":["Cualquier persona con tarjeta de biblioteca","Un residente que tiene o tendrá 18 años para la próxima elección general o municipal","Solo personas mayores de 65 años","Solo estudiantes de secundaria"],"h1":"Tiene que ver con poder votar.","h2":"En Indiana, la tarjeta de identificación es gratis para un residente que tiene 18 años o los cumplirá para la próxima elección general o municipal.","p":"Correcto. Es gratis para quienes pueden votar."},"ref":{"doc":"IN","page":1}},{"id":"in-058","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you are 15 and applying for a permit through driver education. How early may your Certificate of Driver Education Enrollment be dated?","o":["Up to one year before class starts","Up to six months before class starts","No earlier than three weeks before class starts","Any date after you finish the online class"],"h1":"The date must be close to the start of class.","h2":"In Indiana, the Certificate of Driver Education Enrollment must be dated no earlier than three weeks before the class starts.","p":"Right. No earlier than three weeks before class."},"es":{"q":"En Indiana, usted tiene 15 años y solicita un permiso por medio de la educación vial. ¿Con cuánta anticipación puede tener fecha su Certificado de Inscripción en Educación Vial?","o":["Hasta un año antes del inicio de la clase","Hasta seis meses antes del inicio de la clase","No antes de tres semanas antes del inicio de la clase","Cualquier fecha después de terminar la clase en línea"],"h1":"La fecha debe estar cerca del inicio de la clase.","h2":"En Indiana, el Certificado de Inscripción en Educación Vial debe tener una fecha no anterior a tres semanas antes del inicio de la clase.","p":"Correcto. No antes de tres semanas antes de la clase."},"ref":{"doc":"IN","page":3}},{"id":"in-059","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, an applicant under 18 for a learner's permit must give the BMV what?","o":["A letter from a teacher","A doctor's report","Proof of a part-time job","An emergency contact who is at least 18"],"h1":"The BMV wants someone to call if something happens.","h2":"In Indiana, a learner's permit applicant under 18 must provide an emergency contact who is at least 18 years old.","p":"Correct. An emergency contact 18 or older."},"es":{"q":"En Indiana, un solicitante de permiso de aprendizaje menor de 18 años debe darle al BMV, ¿qué cosa?","o":["Una carta de un maestro","Un informe médico","Prueba de un trabajo de medio tiempo","Un contacto de emergencia de al menos 18 años"],"h1":"El BMV quiere a alguien a quien llamar si pasa algo.","h2":"En Indiana, el solicitante de permiso de aprendizaje menor de 18 años debe dar un contacto de emergencia que tenga al menos 18 años.","p":"Correcto. Un contacto de emergencia de 18 años o más."},"ref":{"doc":"IN","page":3}},{"id":"in-060","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, where must the licensed adult sit when a learner with a permit is driving?","o":["In the front passenger seat","In the back seat behind the driver","Anywhere in the vehicle","In the back seat on the right"],"h1":"The adult must be able to help right away.","h2":"In Indiana, the licensed driver supervising a permit holder must sit in the front passenger seat.","p":"Right. In the front passenger seat."},"es":{"q":"En Indiana, ¿dónde debe sentarse el adulto con licencia cuando maneja un aprendiz con permiso?","o":["En el asiento delantero del pasajero","En el asiento de atrás, detrás del conductor","En cualquier lugar del vehículo","En el asiento de atrás a la derecha"],"h1":"El adulto debe poder ayudar de inmediato.","h2":"En Indiana, el conductor con licencia que supervisa a quien tiene permiso debe sentarse en el asiento delantero del pasajero.","p":"Correcto. En el asiento delantero del pasajero."},"ref":{"doc":"IN","page":4}},{"id":"in-061","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you are 19 and have a learner's permit. Who may supervise your practice driving?","o":["Only a parent","Any licensed driver who is at least 25, even if not related to you","Any licensed driver who is at least 18","Only a driving school instructor"],"h1":"At 19, the supervisor does not have to be a relative.","h2":"In Indiana, a permit holder 18 or older may practice with any licensed driver who is at least 25, or with a licensed spouse who is at least 21.","p":"Correct. Any licensed driver 25 or older."},"es":{"q":"En Indiana, usted tiene 19 años y un permiso de aprendizaje. ¿Quién puede supervisar su práctica de manejo?","o":["Solo uno de sus padres","Cualquier conductor con licencia de al menos 25 años, aunque no sea su familiar","Cualquier conductor con licencia de al menos 18 años","Solo un instructor de escuela de manejo"],"h1":"A los 19 años, el supervisor no tiene que ser un familiar.","h2":"En Indiana, quien tiene permiso y tiene 18 años o más puede practicar con cualquier conductor con licencia de al menos 25 años, o con su cónyuge con licencia de al menos 21.","p":"Correcto. Cualquier conductor con licencia de 25 años o más."},"ref":{"doc":"IN","page":4}},{"id":"in-062","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, your learner's permit has been expired for more than 180 days. What must you do to renew it?","o":["Just pay the fee online","Wait one full year","Take the knowledge exam again","Take only the driving skills exam"],"h1":"After that long, you must show what you know again.","h2":"In Indiana, if a learner's permit has been expired for more than 180 days, you must retake the knowledge exam to renew it.","p":"Right. You must retest."},"es":{"q":"En Indiana, su permiso de aprendizaje venció hace más de 180 días. ¿Qué debe hacer para renovarlo?","o":["Solo pagar la tarifa en línea","Esperar un año completo","Tomar otra vez el examen de conocimientos","Tomar solo el examen práctico de manejo"],"h1":"Después de tanto tiempo, debe mostrar otra vez lo que sabe.","h2":"En Indiana, si un permiso de aprendizaje venció hace más de 180 días, debe tomar otra vez el examen de conocimientos para renovarlo.","p":"Correcto. Debe volver a examinarse."},"ref":{"doc":"IN","page":4}},{"id":"in-063","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you renew your driver's license at a BMV branch. Must you pass a vision screening?","o":["No, only new drivers are tested","Only if you are older than 75","Only if you wear glasses","Yes, unless you are eligible to renew online"],"h1":"Indiana checks vision at the branch even for renewals.","h2":"In Indiana, every license or permit applicant must pass a vision screening, even when renewing, unless the person is eligible for online renewal.","p":"Correct. A vision screening is required at the branch."},"es":{"q":"En Indiana, usted renueva su licencia de conducir en una oficina del BMV. ¿Debe pasar un examen de la vista?","o":["No, solo se examina a los conductores nuevos","Solo si tiene más de 75 años","Solo si usa lentes","Sí, a menos que pueda renovar en línea"],"h1":"Indiana revisa la vista en la oficina incluso al renovar.","h2":"En Indiana, todo solicitante de licencia o permiso debe pasar un examen de la vista, incluso al renovar, a menos que pueda renovar en línea.","p":"Correcto. Se requiere examen de la vista en la oficina."},"ref":{"doc":"IN","page":4}},{"id":"in-064","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you want to take the computer knowledge exam today. When must you arrive at the BMV branch?","o":["At least 30 minutes before the branch closes","At least 2 hours before the branch closes","Any time before the branch closes","Only in the morning"],"h1":"The exam takes time, so do not come at the last minute.","h2":"In Indiana, you must arrive at least 30 minutes before the branch closes to take the knowledge exam that day.","p":"Right. At least 30 minutes before closing."},"es":{"q":"En Indiana, usted quiere tomar hoy el examen de conocimientos en computadora. ¿Cuándo debe llegar a la oficina del BMV?","o":["Al menos 30 minutos antes de que cierre la oficina","Al menos 2 horas antes de que cierre la oficina","A cualquier hora antes del cierre","Solo en la mañana"],"h1":"El examen toma tiempo, así que no llegue al último minuto.","h2":"En Indiana, debe llegar al menos 30 minutos antes de que cierre la oficina para tomar el examen de conocimientos ese día.","p":"Correcto. Al menos 30 minutos antes del cierre."},"ref":{"doc":"IN","page":5}},{"id":"in-065","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a BMV-licensed driver training course that can give the skills exam includes how much training?","o":["10 hours of class and 2 hours of driving","30 hours of class and 6 hours of behind-the-wheel driving","50 hours of class and 10 hours of driving","20 hours of class and 4 hours of driving"],"h1":"The driving part is a little more than five hours.","h2":"In Indiana, the driver training course includes 30 hours of theory (classroom or online) and six hours of behind-the-wheel training.","p":"Correct. 30 hours of class and 6 hours of driving."},"es":{"q":"En Indiana, un curso de manejo con licencia del BMV que puede dar el examen práctico incluye, ¿cuánto entrenamiento?","o":["10 horas de clase y 2 horas de manejo","30 horas de clase y 6 horas de manejo al volante","50 horas de clase y 10 horas de manejo","20 horas de clase y 4 horas de manejo"],"h1":"La parte de manejo es un poco más de cinco horas.","h2":"En Indiana, el curso de manejo incluye 30 horas de teoría (en clase o en línea) y seis horas de práctica al volante.","p":"Correcto. 30 horas de clase y 6 de manejo."},"ref":{"doc":"IN","page":5}},{"id":"in-066","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you passed the driving skills exam at your driver training school. How long do those results stay valid?","o":["30 days","Six months","Until your learner's permit expires","Forever"],"h1":"The result is tied to another document you hold.","h2":"In Indiana, a skills exam passed with a driver training school stays valid until your learner's permit expires.","p":"Right. Until your permit expires."},"es":{"q":"En Indiana, usted aprobó el examen práctico de manejo en su escuela de manejo. ¿Por cuánto tiempo sigue válido ese resultado?","o":["30 días","Seis meses","Hasta que venza su permiso de aprendizaje","Para siempre"],"h1":"El resultado está ligado a otro documento que usted tiene.","h2":"En Indiana, un examen práctico aprobado en una escuela de manejo sigue válido hasta que vence su permiso de aprendizaje.","p":"Correcto. Hasta que venza su permiso."},"ref":{"doc":"IN","page":5}},{"id":"in-067","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how far ahead can you schedule a driving skills exam with the BMV?","o":["Up to one year ahead","Up to six months ahead","Only on the same day","No more than three weeks ahead"],"h1":"It is a short window of a few weeks.","h2":"In Indiana, a BMV driving skills exam can be scheduled no more than three weeks and no less than 48 business hours ahead.","p":"Correct. No more than three weeks ahead."},"es":{"q":"En Indiana, ¿con cuánta anticipación puede programar un examen práctico de manejo con el BMV?","o":["Hasta un año antes","Hasta seis meses antes","Solo el mismo día","No más de tres semanas antes"],"h1":"Es un plazo corto de pocas semanas.","h2":"En Indiana, el examen práctico con el BMV se puede programar con no más de tres semanas y no menos de 48 horas hábiles de anticipación.","p":"Correcto. No más de tres semanas antes."},"ref":{"doc":"IN","page":5}},{"id":"in-068","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, what do you need to bring, and pay, for a driving skills exam given by the BMV?","o":["Your own vehicle; the exam is free","A BMV car; the exam costs $50","Your own vehicle and a $25 fee","Nothing; the BMV gives you a car for free"],"h1":"The BMV does not lend cars.","h2":"In Indiana, you must provide your own vehicle for the BMV driving skills exam, and the BMV does not charge for it.","p":"Right. Bring your own car; there is no charge."},"es":{"q":"En Indiana, ¿qué debe llevar, y cuánto debe pagar, para el examen práctico de manejo del BMV?","o":["Su propio vehículo; el examen es gratis","Un auto del BMV; el examen cuesta $50","Su propio vehículo y una tarifa de $25","Nada; el BMV le da un auto gratis"],"h1":"El BMV no presta autos.","h2":"En Indiana, debe llevar su propio vehículo al examen práctico del BMV, y el BMV no cobra por ese examen.","p":"Correcto. Lleve su propio auto; no se cobra."},"ref":{"doc":"IN","page":5}},{"id":"in-069","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, who may ride in your car during the BMV driving skills exam?","o":["Your parent, in the back seat","Only the BMV examiner or other authorized BMV staff","Your driving instructor","One friend, if they stay quiet"],"h1":"The exam must be fair and free of help.","h2":"In Indiana, no one but the BMV examiner or other authorized BMV staff may be in your vehicle during the driving skills exam.","p":"Correct. Only the examiner or BMV staff."},"es":{"q":"En Indiana, ¿quién puede ir en su auto durante el examen práctico de manejo del BMV?","o":["Uno de sus padres, en el asiento de atrás","Solo el examinador del BMV u otro personal autorizado del BMV","Su instructor de manejo","Un amigo, si se queda callado"],"h1":"El examen debe ser justo y sin ayuda.","h2":"En Indiana, nadie más que el examinador del BMV u otro personal autorizado del BMV puede ir en su vehículo durante el examen práctico.","p":"Correcto. Solo el examinador o personal del BMV."},"ref":{"doc":"IN","page":6}},{"id":"in-070","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, your car has a camera inside that records the cabin. What must you do for the driving skills exam?","o":["Point it at the road","Nothing; it may stay on","Turn it off for the exam (a backup camera may stay on)","Give the recording to the examiner"],"h1":"The rule does not cover the camera that helps you back up.","h2":"In Indiana, any interior cameras must be turned off during the driving skills exam, but a backup camera is allowed.","p":"Right. Turn off interior cameras."},"es":{"q":"En Indiana, su auto tiene una cámara interior que graba la cabina. ¿Qué debe hacer para el examen práctico de manejo?","o":["Apuntarla hacia la calle","Nada; puede seguir encendida","Apagarla durante el examen (la cámara de reversa puede quedar encendida)","Darle la grabación al examinador"],"h1":"La regla no incluye la cámara que le ayuda a dar reversa.","h2":"En Indiana, toda cámara interior debe estar apagada durante el examen práctico de manejo, pero la cámara de reversa está permitida.","p":"Correcto. Apague las cámaras interiores."},"ref":{"doc":"IN","page":6}},{"id":"in-071","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, which mistake makes you fail the driving skills exam right away?","o":["Adjusting your mirror before you start","Driving 5 mph under the limit in heavy traffic","Using your turn signal early","Not wearing your seat belt"],"h1":"It is a safety rule you follow before you even move.","h2":"In Indiana, failing to use a seat belt is an automatic failure on the driving skills exam, along with errors like speeding or backing over a curb.","p":"Correct. No seat belt means you fail."},"es":{"q":"En Indiana, ¿cuál error hace que usted repruebe de inmediato el examen práctico de manejo?","o":["Ajustar el espejo antes de empezar","Manejar 5 mph menos que el límite con tráfico pesado","Usar la direccional con tiempo","No usar el cinturón de seguridad"],"h1":"Es una regla de seguridad que se cumple antes de moverse.","h2":"En Indiana, no usar el cinturón de seguridad es reprobación automática en el examen práctico, igual que exceder la velocidad o subirse a la acera en reversa.","p":"Correcto. Sin cinturón, reprueba."},"ref":{"doc":"IN","page":7}},{"id":"in-072","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you have failed the driving skills exam for the third time while holding a learner's permit. How long must you wait to try again?","o":["Two months","Seven days","One year","Until the next business day"],"h1":"It is longer than the usual wait after a single failure.","h2":"In Indiana, after a third failed skills exam on a learner's permit, you must wait two months from the last failed exam.","p":"Right. Two months."},"es":{"q":"En Indiana, usted reprobó por tercera vez el examen práctico de manejo con permiso de aprendizaje. ¿Cuánto debe esperar para intentarlo otra vez?","o":["Dos meses","Siete días","Un año","Hasta el siguiente día hábil"],"h1":"Es más que la espera normal después de un solo intento fallido.","h2":"En Indiana, después de reprobar por tercera vez el examen práctico con permiso, debe esperar dos meses desde el último examen reprobado.","p":"Correcto. Dos meses."},"ref":{"doc":"IN","page":7}},{"id":"in-073","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, an adult must sign to accept financial responsibility for a teen under 18 who applies for a permit. Who is first in line under the law?","o":["Any adult the teen chooses","The parent who has custody of the teen","The teen's driving instructor","A grandparent"],"h1":"The law lists people in order, starting with the closest one at home.","h2":"In Indiana, the first choice to sign the financial liability statement is the parent who has custody of the minor (or that parent's designee).","p":"Correct. The custodial parent comes first."},"es":{"q":"En Indiana, un adulto debe firmar para aceptar la responsabilidad financiera de un menor de 18 años que solicita un permiso. ¿Quién es el primero según la ley?","o":["Cualquier adulto que el joven elija","El padre o la madre que tiene la custodia del joven","El instructor de manejo del joven","Un abuelo"],"h1":"La ley pone a las personas en orden, empezando por la más cercana en el hogar.","h2":"En Indiana, la primera opción para firmar la declaración de responsabilidad financiera es el padre o la madre que tiene la custodia del menor (o la persona que esa persona designe).","p":"Correcto. Primero el padre o la madre con custodia."},"ref":{"doc":"IN","page":8}},{"id":"in-074","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, the adult who signed financial liability for a teen driver files a request to withdraw it. What happens?","o":["Nothing changes until the teen turns 18","The teen pays a fine","The teen's permit or license is canceled","The teen must take the skills exam again"],"h1":"Without a signer, the teen cannot keep driving.","h2":"In Indiana, when the adult withdraws financial liability, the minor's permit or license is canceled until a new person signs.","p":"Right. The teen's permit or license is canceled."},"es":{"q":"En Indiana, el adulto que firmó la responsabilidad financiera de un joven conductor pide retirarla. ¿Qué pasa?","o":["Nada cambia hasta que el joven cumpla 18","El joven paga una multa","Se cancela el permiso o la licencia del joven","El joven debe tomar otra vez el examen práctico"],"h1":"Sin alguien que firme, el joven no puede seguir manejando.","h2":"En Indiana, cuando el adulto retira la responsabilidad financiera, se cancela el permiso o la licencia del menor hasta que otra persona firme.","p":"Correcto. Se cancela el permiso o la licencia."},"ref":{"doc":"IN","page":8}},{"id":"in-075","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how old must you be to get a commercial driver's license (CDL) with a school bus endorsement?","o":["16","18","25","21"],"h1":"It is older than the minimum age for a regular CDL.","h2":"In Indiana, you must be at least 21 to get a CDL with a school bus endorsement; a regular CDL starts at 18.","p":"Correct. At least 21."},"es":{"q":"En Indiana, ¿qué edad debe tener para obtener una licencia de conducir comercial (CDL) con endoso de autobús escolar?","o":["16","18","25","21"],"h1":"Es mayor que la edad mínima para una CDL común.","h2":"En Indiana, debe tener al menos 21 años para una CDL con endoso de autobús escolar; una CDL común empieza a los 18.","p":"Correcto. Al menos 21 años."},"ref":{"doc":"IN","page":8}},{"id":"in-076","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a 19-year-old has a commercial driver's license. Where may this driver operate a commercial vehicle?","o":["Only within Indiana (intrastate)","In any state","Only on interstate highways","Nowhere until age 25"],"h1":"Drivers under 21 have a limit on crossing state lines.","h2":"In Indiana, a CDL holder under 21 may drive a commercial motor vehicle only for intrastate commerce, which means within the state.","p":"Right. Only within Indiana."},"es":{"q":"En Indiana, una persona de 19 años tiene licencia de conducir comercial. ¿Dónde puede manejar un vehículo comercial?","o":["Solo dentro de Indiana (intraestatal)","En cualquier estado","Solo en autopistas interestatales","En ningún lugar hasta los 25 años"],"h1":"Los conductores menores de 21 tienen un límite para cruzar estados.","h2":"En Indiana, quien tiene CDL y es menor de 21 años solo puede manejar un vehículo comercial para comercio intraestatal, es decir, dentro del estado.","p":"Correcto. Solo dentro de Indiana."},"ref":{"doc":"IN","page":11}},{"id":"in-077","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, your learner's permit has restriction G (daylight driving only). What does that change about your supervised driving log?","o":["You need only 25 hours","You still need 50 hours, but the 10 night hours are not required","You do not need a log at all","You need 60 daytime hours"],"h1":"The total stays the same; only the night part changes.","h2":"In Indiana, a learner with a daytime-only restriction must still log 50 hours of supervised driving, but does not need the 10 night hours.","p":"Right. Still 50 hours, no night hours."},"es":{"q":"En Indiana, su permiso de aprendizaje tiene la restricción G (solo manejar de día). ¿Qué cambia en su registro de manejo supervisado?","o":["Solo necesita 25 horas","Sigue necesitando 50 horas, pero no se exigen las 10 horas de noche","No necesita ningún registro","Necesita 60 horas de día"],"h1":"El total es el mismo; solo cambia la parte de noche.","h2":"En Indiana, un aprendiz con restricción de manejo solo de día debe registrar igual 50 horas de manejo supervisado, pero no necesita las 10 horas nocturnas.","p":"Correcto. Siguen siendo 50 horas, sin horas de noche."},"ref":{"doc":"IN","page":9}},{"id":"in-078","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, an applicant under 18 hands in the log of supervised driving. Who must sign it?","o":["The driving school","The BMV examiner","A parent or legal guardian","The teen alone"],"h1":"It is the adult responsible for the teen at home.","h2":"In Indiana, the log of supervised driving practice (State Form 54706) must be signed by a parent or legal guardian when the applicant is under 18.","p":"Correct. A parent or legal guardian signs it."},"es":{"q":"En Indiana, un solicitante menor de 18 años entrega el registro de manejo supervisado. ¿Quién debe firmarlo?","o":["La escuela de manejo","El examinador del BMV","Uno de sus padres o su tutor legal","Solo el joven"],"h1":"Es el adulto responsable del joven en casa.","h2":"En Indiana, el registro de práctica de manejo supervisado (Formulario Estatal 54706) debe estar firmado por uno de los padres o el tutor legal cuando el solicitante es menor de 18 años.","p":"Correcto. Lo firma uno de los padres o el tutor legal."},"ref":{"doc":"IN","page":9}},{"id":"in-079","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you are 78 years old. How long is your renewed driver's license valid?","o":["Six years","One year","Five years","Three years"],"h1":"It is shorter than for younger drivers, but not the shortest.","h2":"In Indiana, a driver's license is valid for three years for drivers aged 75 through 84.","p":"Right. Three years."},"es":{"q":"En Indiana, usted tiene 78 años. ¿Por cuánto tiempo es válida su licencia renovada?","o":["Seis años","Un año","Cinco años","Tres años"],"h1":"Es más corta que para conductores jóvenes, pero no la más corta.","h2":"En Indiana, la licencia de conducir es válida por tres años para conductores de 75 a 84 años.","p":"Correcto. Tres años."},"ref":{"doc":"IN","page":9}},{"id":"in-080","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how long is a driver's license valid for a driver who is 85 or older?","o":["Two years","Three years","Four years","Six years"],"h1":"This is the shortest regular license period in Indiana.","h2":"In Indiana, a driver's license is valid for two years for a driver who is at least 85 years old.","p":"Correct. Two years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válida la licencia de un conductor de 85 años o más?","o":["Dos años","Tres años","Cuatro años","Seis años"],"h1":"Es el período normal más corto en Indiana.","h2":"En Indiana, la licencia de conducir es válida por dos años para un conductor de al menos 85 años.","p":"Correcto. Dos años."},"ref":{"doc":"IN","page":9}},{"id":"in-081","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how long is a commercial driver's license (CDL) valid?","o":["Two years","Four years","Six years","Eight years"],"h1":"It is shorter than a regular license for a young adult.","h2":"In Indiana, a commercial driver's license is valid for four years.","p":"Right. Four years."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válida una licencia de conducir comercial (CDL)?","o":["Dos años","Cuatro años","Seis años","Ocho años"],"h1":"Es más corta que una licencia común de un adulto joven.","h2":"En Indiana, la licencia de conducir comercial es válida por cuatro años.","p":"Correcto. Cuatro años."},"ref":{"doc":"IN","page":9}},{"id":"in-082","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, when is the earliest you may renew a probationary driver's license to get an unrestricted one?","o":["On your 18th birthday","30 days before you turn 21","When you are 21 years and one day old","When you are 25"],"h1":"You must already be 21.","h2":"In Indiana, you may not renew a probationary license until you are 21 years and one day old; then you get an unrestricted license.","p":"Correct. At 21 years and one day."},"es":{"q":"En Indiana, ¿cuándo es lo más pronto que puede renovar una licencia probatoria para obtener una sin restricciones?","o":["El día que cumple 18 años","30 días antes de cumplir 21","Cuando tiene 21 años y un día","Cuando tiene 25 años"],"h1":"Ya debe tener 21 años.","h2":"En Indiana, no puede renovar una licencia probatoria hasta tener 21 años y un día; entonces recibe una licencia sin restricciones.","p":"Correcto. A los 21 años y un día."},"ref":{"doc":"IN","page":10}},{"id":"in-083","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you have had your probationary license for two months. No adult is with you. Who may ride with you?","o":["Two friends from school","Any passenger under 18","A classmate who has a permit","Your younger brother or sister"],"h1":"Family members such as siblings are an exception.","h2":"In Indiana, during the first 180 days of a probationary license you may carry your child, stepchild, sibling (including step or half siblings) or spouse without another adult.","p":"Right. A brother or sister may ride with you."},"es":{"q":"En Indiana, usted tiene su licencia probatoria desde hace dos meses. No va ningún adulto con usted. ¿Quién puede ir con usted?","o":["Dos amigos de la escuela","Cualquier pasajero menor de 18 años","Un compañero de clase que tiene permiso","Su hermano o hermana menor"],"h1":"Los familiares como los hermanos son una excepción.","h2":"En Indiana, durante los primeros 180 días de la licencia probatoria puede llevar a su hijo, hijastro, hermano (incluidos hermanastros y medios hermanos) o cónyuge sin otro adulto.","p":"Correcto. Su hermano o hermana puede ir con usted."},"ref":{"doc":"IN","page":10}},{"id":"in-084","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you are 17 and have held a probationary license for more than 180 days. On Monday through Friday mornings, what is the earliest you may drive?","o":["5 a.m.","4 a.m.","6 a.m.","7 a.m."],"h1":"It is the same hour that ends the limit on weekend nights.","h2":"In Indiana, after the first 180 days and until 18, a probationary driver may not drive before 5 a.m. on Monday through Friday, except for allowed reasons.","p":"Correct. Not before 5 a.m."},"es":{"q":"En Indiana, usted tiene 17 años y tiene licencia probatoria desde hace más de 180 días. De lunes a viernes en la mañana, ¿a qué hora es lo más temprano que puede manejar?","o":["5 a.m.","4 a.m.","6 a.m.","7 a.m."],"h1":"Es la misma hora en que termina el límite de las noches de fin de semana.","h2":"En Indiana, después de los primeros 180 días y hasta los 18 años, un conductor probatorio no puede manejar antes de las 5 a.m. de lunes a viernes, salvo por razones permitidas.","p":"Correcto. No antes de las 5 a.m."},"ref":{"doc":"IN","page":10}},{"id":"in-085","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a 16-year-old drops out of high school. What can happen to the teen's driving privileges?","o":["Nothing; school and driving are separate","The BMV must suspend them after the school reports it","The teen must retake the knowledge exam","The teen gets 4 points"],"h1":"Indiana links school attendance to a teen's license.","h2":"In Indiana, the BMV must suspend a juvenile's driving privileges when the school reports that the student withdrew, was expelled, is a habitual truant, or was suspended a second time in a school year.","p":"Right. The BMV suspends them."},"es":{"q":"En Indiana, un joven de 16 años deja la escuela secundaria. ¿Qué puede pasar con sus privilegios de manejo?","o":["Nada; la escuela y el manejo son cosas separadas","El BMV debe suspenderlos cuando la escuela lo informa","Debe tomar otra vez el examen de conocimientos","Recibe 4 puntos"],"h1":"Indiana relaciona la asistencia escolar con la licencia del joven.","h2":"En Indiana, el BMV debe suspender los privilegios de manejo de un menor cuando la escuela informa que dejó la escuela, fue expulsado, falta a clases habitualmente o fue suspendido por segunda vez en un año escolar.","p":"Correcto. El BMV los suspende."},"ref":{"doc":"IN","page":10}},{"id":"in-086","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, after you apply for a new or renewed license, how does the permanent card reach you?","o":["You pick it up at the branch the next day","It is emailed to you","It is mailed within 14 calendar days to the address the BMV has on file","It is mailed to any address you write on an envelope"],"h1":"Keep your mailing address up to date; it will not be forwarded.","h2":"In Indiana, the permanent credential is mailed from a central location within 14 calendar days, only to the mailing address on file, and it is not forwarded.","p":"Correct. It is mailed within 14 days."},"es":{"q":"En Indiana, después de solicitar una licencia nueva o renovada, ¿cómo le llega la tarjeta permanente?","o":["La recoge en la oficina al día siguiente","Le llega por correo electrónico","Se la envían por correo dentro de 14 días calendario a la dirección que tiene el BMV","Se la envían a cualquier dirección que usted escriba en un sobre"],"h1":"Mantenga al día su dirección postal; no se reenvía.","h2":"En Indiana, la credencial permanente se envía por correo desde un lugar central dentro de 14 días calendario, solo a la dirección postal registrada, y no se reenvía.","p":"Correcto. Llega por correo dentro de 14 días."},"ref":{"doc":"IN","page":11}},{"id":"in-087","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a license shows restriction B. What does it mean?","o":["Daylight driving only","Ignition interlock required","Outside mirrors required","Glasses or contact lenses required when driving"],"h1":"It is the most common result of a vision screening.","h2":"In Indiana, restriction B means the driver must wear glasses or contact lenses when driving.","p":"Right. Glasses or contacts are required."},"es":{"q":"En Indiana, una licencia muestra la restricción B. ¿Qué significa?","o":["Solo manejar de día","Se requiere dispositivo de bloqueo de encendido","Se requieren espejos exteriores","Debe usar lentes o lentes de contacto al manejar"],"h1":"Es el resultado más común de un examen de la vista.","h2":"En Indiana, la restricción B significa que el conductor debe usar lentes o lentes de contacto al manejar.","p":"Correcto. Debe usar lentes o lentes de contacto."},"ref":{"doc":"IN","page":13}},{"id":"in-088","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a license shows restriction G. What does it mean?","o":["Daylight driving only","Glasses required","Motorcycle with sidecar only","Seat belt exempt"],"h1":"It limits the time of day you may drive.","h2":"In Indiana, restriction G means the driver may drive only during daylight.","p":"Correct. Daylight driving only."},"es":{"q":"En Indiana, una licencia muestra la restricción G. ¿Qué significa?","o":["Solo manejar de día","Se requieren lentes","Solo motocicleta con sidecar","Exento del cinturón de seguridad"],"h1":"Limita la hora del día en que puede manejar.","h2":"En Indiana, la restricción G significa que el conductor solo puede manejar con luz de día.","p":"Correcto. Solo de día."},"ref":{"doc":"IN","page":13}},{"id":"in-089","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a license shows restriction 6. What does it mean?","o":["Photo exempt","The car must have an ignition interlock device","The driver has a medical condition","The driver is a lawful temporary resident"],"h1":"The device tests the driver's breath before the car starts.","h2":"In Indiana, restriction 6 means the driver may drive only a vehicle with an ignition interlock device.","p":"Right. Ignition interlock device."},"es":{"q":"En Indiana, una licencia muestra la restricción 6. ¿Qué significa?","o":["Exento de foto","El auto debe tener un dispositivo de bloqueo de encendido","El conductor tiene una condición médica","El conductor es residente temporal legal"],"h1":"El dispositivo revisa el aliento del conductor antes de arrancar el auto.","h2":"En Indiana, la restricción 6 significa que el conductor solo puede manejar un vehículo con dispositivo de bloqueo de encendido (interlock).","p":"Correcto. Dispositivo de bloqueo de encendido."},"ref":{"doc":"IN","page":13}},{"id":"in-090","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what does endorsement L on a driver's license allow?","o":["Driving a limousine","Driving at night","Riding a motorcycle","Driving a large truck"],"h1":"The letter stands for a two-wheeled vehicle.","h2":"In Indiana, endorsement L on a driver's license is the motorcycle endorsement.","p":"Correct. L is for motorcycle."},"es":{"q":"En Indiana, ¿qué permite el endoso L en una licencia de conducir?","o":["Manejar una limusina","Manejar de noche","Manejar una motocicleta","Manejar un camión grande"],"h1":"La letra corresponde a un vehículo de dos ruedas.","h2":"En Indiana, el endoso L en la licencia de conducir es el endoso de motocicleta.","p":"Correcto. L es para motocicleta."},"ref":{"doc":"IN","page":13}},{"id":"in-091","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, what must you already have to get a motorcycle learner's permit?","o":["A car learner's permit","A motor driven cycle endorsement","A completed riding course","A valid Indiana driver's license"],"h1":"The motorcycle permit is added for people who already drive.","h2":"In Indiana, you must hold a valid Indiana driver's license and pass a motorcycle knowledge exam to get a motorcycle learner's permit.","p":"Right. A valid Indiana driver's license."},"es":{"q":"En Indiana, ¿qué debe tener ya para obtener un permiso de aprendizaje de motocicleta?","o":["Un permiso de aprendizaje de auto","Un endoso de ciclomotor (MDC)","Un curso de manejo de moto terminado","Una licencia de conducir de Indiana válida"],"h1":"El permiso de moto es para personas que ya manejan.","h2":"En Indiana, debe tener una licencia de conducir de Indiana válida y aprobar un examen de conocimientos de motocicleta para obtener el permiso de aprendizaje de motocicleta.","p":"Correcto. Una licencia de Indiana válida."},"ref":{"doc":"IN","page":14}},{"id":"in-092","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, when may you ride with a motorcycle learner's permit?","o":["From one-half hour before sunrise to one-half hour after sunset","Any time of day or night","Only between noon and 6 p.m.","Only at night when traffic is light"],"h1":"Riding is limited to the hours with light.","h2":"In Indiana, a motorcycle learner's permit holder may ride only from one-half hour before sunrise to one-half hour after sunset.","p":"Correct. Only in daylight hours, plus a half hour on each side."},"es":{"q":"En Indiana, ¿cuándo puede manejar con un permiso de aprendizaje de motocicleta?","o":["Desde media hora antes del amanecer hasta media hora después del atardecer","A cualquier hora del día o de la noche","Solo entre el mediodía y las 6 p.m.","Solo de noche, cuando hay poco tráfico"],"h1":"Solo se puede manejar en las horas con luz.","h2":"En Indiana, quien tiene permiso de aprendizaje de motocicleta solo puede manejar desde media hora antes del amanecer hasta media hora después del atardecer.","p":"Correcto. Solo con luz de día, más media hora antes y después."},"ref":{"doc":"IN","page":14}},{"id":"in-093","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what else must you do when riding with a motorcycle learner's permit?","o":["Carry one adult passenger","Wear a helmet and carry no passengers","Ride only on interstate highways","Keep your hazard lights on"],"h1":"One rule protects your head; the other keeps the bike lighter.","h2":"In Indiana, a motorcycle learner's permit holder must wear a helmet and may not carry passengers.","p":"Right. Helmet on, no passengers."},"es":{"q":"En Indiana, ¿qué más debe hacer al manejar con permiso de aprendizaje de motocicleta?","o":["Llevar a un pasajero adulto","Usar casco y no llevar pasajeros","Manejar solo en autopistas interestatales","Llevar encendidas las luces de emergencia"],"h1":"Una regla protege su cabeza; la otra mantiene la moto más ligera.","h2":"En Indiana, quien tiene permiso de aprendizaje de motocicleta debe usar casco y no puede llevar pasajeros.","p":"Correcto. Casco puesto, sin pasajeros."},"ref":{"doc":"IN","page":14}},{"id":"in-094","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how long is a motorcycle learner's permit valid?","o":["Six months","Two years","One year","Five years"],"h1":"It is shorter than the car learner's permit.","h2":"In Indiana, a motorcycle learner's permit is valid for one year from the date it is issued.","p":"Correct. One year."},"es":{"q":"En Indiana, ¿por cuánto tiempo es válido el permiso de aprendizaje de motocicleta?","o":["Seis meses","Dos años","Un año","Cinco años"],"h1":"Es más corto que el permiso de aprendizaje de auto.","h2":"En Indiana, el permiso de aprendizaje de motocicleta es válido por un año desde la fecha en que se emite.","p":"Correcto. Un año."},"ref":{"doc":"IN","page":14}},{"id":"in-095","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how many times may a motorcycle learner's permit be issued or renewed in a five-year period?","o":["Once","As many times as you like","Five times","No more than three times"],"h1":"After that, you must wait a year or take a safety course.","h2":"In Indiana, a motorcycle learner's permit may be issued or renewed no more than three times in five years.","p":"Right. No more than three times."},"es":{"q":"En Indiana, ¿cuántas veces se puede emitir o renovar un permiso de aprendizaje de motocicleta en un período de cinco años?","o":["Una vez","Todas las veces que quiera","Cinco veces","No más de tres veces"],"h1":"Después, debe esperar un año o tomar un curso de seguridad.","h2":"En Indiana, el permiso de aprendizaje de motocicleta se puede emitir o renovar no más de tres veces en cinco años.","p":"Correcto. No más de tres veces."},"ref":{"doc":"IN","page":14}},{"id":"in-096","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how can a driver of any age get a motorcycle endorsement?","o":["Finish a Ride Safe Indiana safety course, or pass the motorcycle knowledge and riding skills exams","Hold a car license for five years","Ride for 50 logged hours with a friend","Pay the endorsement fee only"],"h1":"There are two routes: a course or the BMV exams.","h2":"In Indiana, you get a motorcycle endorsement by completing an approved Ride Safe Indiana course or by passing both the motorcycle knowledge and riding skills exams.","p":"Correct. A Ride Safe Indiana course, or both exams."},"es":{"q":"En Indiana, ¿cómo puede un conductor de cualquier edad obtener el endoso de motocicleta?","o":["Terminar un curso de seguridad de Ride Safe Indiana, o aprobar los exámenes de conocimientos y de manejo de motocicleta","Tener licencia de auto por cinco años","Manejar 50 horas registradas con un amigo","Solo pagar la tarifa del endoso"],"h1":"Hay dos caminos: un curso o los exámenes del BMV.","h2":"En Indiana, se obtiene el endoso de motocicleta al terminar un curso aprobado de Ride Safe Indiana o al aprobar los exámenes de conocimientos y de manejo de motocicleta.","p":"Correcto. Un curso de Ride Safe Indiana, o ambos exámenes."},"ref":{"doc":"IN","page":14}},{"id":"in-097","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you are getting your first driver's license and want a motorcycle endorsement at the same time. What do you need?","o":["To be 18 and have a car for the test","To be at least 16 and have finished a motorcycle safety course","Only a passing grade on the car skills exam","A parent's motorcycle"],"h1":"There is a minimum age and a training step.","h2":"In Indiana, you can get a motorcycle endorsement with your first license if you are at least 16 and have completed a motorcycle safety course.","p":"Right. Be 16 or older and finish a safety course."},"es":{"q":"En Indiana, usted va a sacar su primera licencia y quiere el endoso de motocicleta al mismo tiempo. ¿Qué necesita?","o":["Tener 18 años y un auto para el examen","Tener al menos 16 años y haber terminado un curso de seguridad en motocicleta","Solo aprobar el examen práctico de auto","La motocicleta de uno de sus padres"],"h1":"Hay una edad mínima y un paso de entrenamiento.","h2":"En Indiana, puede obtener el endoso de motocicleta con su primera licencia si tiene al menos 16 años y terminó un curso de seguridad en motocicleta.","p":"Correcto. Tener 16 o más y terminar un curso de seguridad."},"ref":{"doc":"IN","page":14}},{"id":"in-098","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, a new resident has a valid motorcycle endorsement from another state. What must the person do to add it to an Indiana license?","o":["Take the riding skills exam","Wait one year","Pass the motorcycle knowledge exam","Nothing; it transfers automatically"],"h1":"The written part is still needed.","h2":"In Indiana, a new resident with a valid out-of-state motorcycle endorsement can add it to an Indiana license after passing the motorcycle knowledge exam.","p":"Correct. Pass the motorcycle knowledge exam."},"es":{"q":"En Indiana, un residente nuevo tiene un endoso de motocicleta válido de otro estado. ¿Qué debe hacer para agregarlo a una licencia de Indiana?","o":["Tomar el examen práctico de manejo de moto","Esperar un año","Aprobar el examen de conocimientos de motocicleta","Nada; se transfiere solo"],"h1":"La parte escrita todavía se necesita.","h2":"En Indiana, un residente nuevo con endoso de motocicleta válido de otro estado puede agregarlo a su licencia de Indiana después de aprobar el examen de conocimientos de motocicleta.","p":"Correcto. Apruebe el examen de conocimientos de motocicleta."},"ref":{"doc":"IN","page":14}},{"id":"in-099","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a motor driven cycle (MDC) may have an engine no larger than what?","o":["125 cubic centimeters","250 cubic centimeters","100 cubic centimeters","50 cubic centimeters"],"h1":"It is a very small engine, like a moped's.","h2":"In Indiana, a motor driven cycle has a cylinder capacity of no more than 50 cubic centimeters.","p":"Right. 50 cc or less."},"es":{"q":"En Indiana, un ciclomotor (motor driven cycle, MDC) puede tener un motor de no más de, ¿cuánto?","o":["125 centímetros cúbicos","250 centímetros cúbicos","100 centímetros cúbicos","50 centímetros cúbicos"],"h1":"Es un motor muy pequeño, como el de un moped.","h2":"En Indiana, un ciclomotor (MDC) tiene una cilindrada de no más de 50 centímetros cúbicos.","p":"Correcto. 50 cc o menos."},"ref":{"doc":"IN","page":15}},{"id":"in-100","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how old must you be to ride a motor driven cycle (MDC)?","o":["At least 15","At least 12","At least 16","At least 18"],"h1":"It is the same age as the youngest learner's permit.","h2":"In Indiana, you must be at least 15 years old to operate a motor driven cycle.","p":"Correct. At least 15."},"es":{"q":"En Indiana, ¿qué edad debe tener para manejar un ciclomotor (MDC)?","o":["Al menos 15 años","Al menos 12 años","Al menos 16 años","Al menos 18 años"],"h1":"Es la misma edad del permiso de aprendizaje más temprano.","h2":"En Indiana, debe tener al menos 15 años para manejar un ciclomotor (MDC).","p":"Correcto. Al menos 15 años."},"ref":{"doc":"IN","page":15}},{"id":"in-101","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you are 16 and ride a motor driven cycle (MDC). What must you wear?","o":["Only a reflective vest","A helmet and protective glasses, goggles, or a clear face shield","Nothing special","Gloves and boots only"],"h1":"Riders under 18 must protect both the head and the eyes.","h2":"In Indiana, an MDC rider under 18 must wear a helmet and protective glasses, goggles, or a transparent face shield.","p":"Right. A helmet and eye protection."},"es":{"q":"En Indiana, usted tiene 16 años y maneja un ciclomotor (MDC). ¿Qué debe usar?","o":["Solo un chaleco reflectante","Casco y lentes protectores, gafas o un protector facial transparente","Nada especial","Solo guantes y botas"],"h1":"Los menores de 18 deben proteger la cabeza y los ojos.","h2":"En Indiana, quien maneja un ciclomotor (MDC) y es menor de 18 años debe usar casco y lentes protectores, gafas o un protector facial transparente.","p":"Correcto. Casco y protección para los ojos."},"ref":{"doc":"IN","page":15}},{"id":"in-102","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, what is the top speed allowed for a motor driven cycle (MDC)?","o":["25 mph","45 mph","35 mph","55 mph"],"h1":"It is slower than most city streets with a 40 mph limit.","h2":"In Indiana, a motor driven cycle may be operated at no more than 35 miles per hour.","p":"Correct. No more than 35 mph."},"es":{"q":"En Indiana, ¿cuál es la velocidad máxima permitida para un ciclomotor (MDC)?","o":["25 mph","45 mph","35 mph","55 mph"],"h1":"Es más lenta que muchas calles con límite de 40 mph.","h2":"En Indiana, un ciclomotor (MDC) no puede ir a más de 35 millas por hora.","p":"Correcto. No más de 35 mph."},"ref":{"doc":"IN","page":15}},{"id":"in-103","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, where may you never ride a motor driven cycle (MDC)?","o":["On a county road","On a city street","Near the right edge of the road","On an interstate highway or a sidewalk"],"h1":"One place is too fast; the other is for people on foot.","h2":"In Indiana, a motor driven cycle may not be operated on an interstate highway or on a sidewalk.","p":"Right. Never on an interstate or a sidewalk."},"es":{"q":"En Indiana, ¿dónde nunca puede manejar un ciclomotor (MDC)?","o":["En un camino del condado","En una calle de la ciudad","Cerca del borde derecho del camino","En una autopista interestatal o en una acera"],"h1":"Un lugar es demasiado rápido; el otro es para peatones.","h2":"En Indiana, un ciclomotor (MDC) no se puede manejar en una autopista interestatal ni en una acera.","p":"Correcto. Nunca en una interestatal ni en la acera."},"ref":{"doc":"IN","page":15}},{"id":"in-104","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, which rule applies every time you ride a motor driven cycle (MDC)?","o":["The headlamp must be on, and you may not carry a passenger","You may carry one passenger under 12","You must ride in the left part of the lane","You may carry packages in one hand"],"h1":"Think about being seen and riding alone.","h2":"In Indiana, an MDC rider must have the headlamp on, may not carry passengers, and may not carry a package in hand.","p":"Correct. Headlamp on and no passengers."},"es":{"q":"En Indiana, ¿qué regla se aplica cada vez que maneja un ciclomotor (MDC)?","o":["El faro debe estar encendido y no puede llevar pasajeros","Puede llevar un pasajero menor de 12 años","Debe ir por la parte izquierda del carril","Puede llevar paquetes en una mano"],"h1":"Piense en ser visto y en ir solo.","h2":"En Indiana, quien maneja un ciclomotor (MDC) debe llevar el faro encendido, no puede llevar pasajeros y no puede llevar paquetes en la mano.","p":"Correcto. Faro encendido y sin pasajeros."},"ref":{"doc":"IN","page":15}},{"id":"in-105","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you have a valid driver's license. Do you need a separate endorsement to ride a motor driven cycle (MDC)?","o":["Yes, always","No, a valid learner's permit or driver's license is enough","Only if you are under 21","Only on weekends"],"h1":"The MDC endorsement is mainly for people with only an ID card.","h2":"In Indiana, you do not need an MDC endorsement if you hold a valid learner's permit or driver's license.","p":"Right. Your license or permit is enough."},"es":{"q":"En Indiana, usted tiene una licencia de conducir válida. ¿Necesita un endoso aparte para manejar un ciclomotor (MDC)?","o":["Sí, siempre","No, basta con un permiso de aprendizaje o una licencia válida","Solo si es menor de 21 años","Solo los fines de semana"],"h1":"El endoso MDC es más que nada para personas que solo tienen tarjeta de identificación.","h2":"En Indiana, no necesita endoso MDC si tiene un permiso de aprendizaje o una licencia de conducir válida.","p":"Correcto. Su licencia o permiso es suficiente."},"ref":{"doc":"IN","page":15}},{"id":"in-106","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, an autocycle is a three-wheeled vehicle with a steering wheel and pedals. What do you need to drive one?","o":["A motorcycle endorsement","A motorcycle learner's permit","A valid driver's license","A commercial driver's license"],"h1":"You drive it more like a car than a motorcycle.","h2":"In Indiana, you may drive an autocycle with a valid driver's license; a motorcycle permit or endorsement is not required.","p":"Correct. A valid driver's license."},"es":{"q":"En Indiana, un autociclo es un vehículo de tres ruedas con volante y pedales. ¿Qué necesita para manejarlo?","o":["Un endoso de motocicleta","Un permiso de aprendizaje de motocicleta","Una licencia de conducir válida","Una licencia de conducir comercial"],"h1":"Se maneja más como un auto que como una moto.","h2":"En Indiana, puede manejar un autociclo con una licencia de conducir válida; no necesita permiso ni endoso de motocicleta.","p":"Correcto. Una licencia de conducir válida."},"ref":{"doc":"IN","page":15}},{"id":"in-107","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, can you use an autocycle for your driver's license skills exam?","o":["Yes, if it has seat belts","Yes, if an adult rides along","Only during daylight","No, an autocycle may not be used for the skills exam"],"h1":"The exam vehicle must be a regular vehicle.","h2":"In Indiana, an autocycle may not be used for the driving skills exam for a driver's license.","p":"Right. It may not be used for the exam."},"es":{"q":"En Indiana, ¿puede usar un autociclo para el examen práctico de la licencia de conducir?","o":["Sí, si tiene cinturones de seguridad","Sí, si va un adulto con usted","Solo de día","No, no se puede usar un autociclo para el examen práctico"],"h1":"El vehículo del examen debe ser un vehículo común.","h2":"En Indiana, no se puede usar un autociclo para el examen práctico de manejo de la licencia de conducir.","p":"Correcto. No se puede usar para el examen."},"ref":{"doc":"IN","page":15}},{"id":"in-108","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, what must you have to get a for-hire endorsement (for example, to drive a ride-share or cab)?","o":["Be at least 18 and have held a valid Indiana license for at least one year","Be at least 16 and have a learner's permit","Be at least 25 and own a car","Have a CDL for five years"],"h1":"You need adult age and some driving experience.","h2":"In Indiana, a for-hire endorsement requires you to be at least 18 and to have held a valid Indiana driver's license for at least one year.","p":"Correct. Age 18 and one year with a license."},"es":{"q":"En Indiana, ¿qué necesita para obtener un endoso de transporte por contrato (for-hire), por ejemplo, para manejar un taxi o un servicio de viajes?","o":["Tener al menos 18 años y haber tenido una licencia de Indiana válida por al menos un año","Tener al menos 16 años y un permiso de aprendizaje","Tener al menos 25 años y ser dueño de un auto","Tener CDL por cinco años"],"h1":"Necesita ser adulto y tener algo de experiencia.","h2":"En Indiana, el endoso for-hire exige tener al menos 18 años y haber tenido una licencia de conducir de Indiana válida por al menos un año.","p":"Correcto. 18 años y un año con licencia."},"ref":{"doc":"IN","page":16}},{"id":"in-109","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a for-hire endorsement covers passenger vehicles designed to carry how many people?","o":["Any number of people","Fewer than 16, including the driver","Up to 30 people","Only one passenger"],"h1":"Bigger passenger vehicles need a commercial license.","h2":"In Indiana, a for-hire endorsement covers vehicles designed to carry fewer than 16 passengers, including the driver, for hire.","p":"Right. Fewer than 16 people, including the driver."},"es":{"q":"En Indiana, el endoso for-hire cubre vehículos de pasajeros diseñados para llevar, ¿cuántas personas?","o":["Cualquier cantidad de personas","Menos de 16, incluido el conductor","Hasta 30 personas","Solo un pasajero"],"h1":"Los vehículos de pasajeros más grandes requieren licencia comercial.","h2":"En Indiana, el endoso for-hire cubre vehículos diseñados para llevar menos de 16 pasajeros, incluido el conductor, a cambio de pago.","p":"Correcto. Menos de 16 personas, incluido el conductor."},"ref":{"doc":"IN","page":16}},{"id":"in-110","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how does your license show that you chose to be an organ donor?","o":["A green stripe on the back","The word DONOR in red across the photo","A small heart on the front","A star in the upper corner"],"h1":"It is a small symbol of caring.","h2":"In Indiana, if you choose to be an organ donor, a small heart is printed on the front of your credential.","p":"Correct. A small heart."},"es":{"q":"En Indiana, ¿cómo muestra su licencia que usted eligió ser donante de órganos?","o":["Una franja verde atrás","La palabra DONOR en rojo sobre la foto","Un pequeño corazón en el frente","Una estrella en la esquina de arriba"],"h1":"Es un pequeño símbolo de cariño.","h2":"En Indiana, si elige ser donante de órganos, se imprime un pequeño corazón en el frente de su credencial.","p":"Correcto. Un pequeño corazón."},"ref":{"doc":"IN","page":17}},{"id":"in-111","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, an adult 21 years old registers as an organ donor. Under the Donor Choice Law, can the family override this choice after death?","o":["Yes, the closest relative decides","Yes, if two relatives agree","Only a spouse can override it","No, for donors 18 or older the family cannot override it"],"h1":"The law respects an adult's own decision.","h2":"In Indiana, under the Donor Choice Law, family members cannot override the donation choice of a person who was 18 or older.","p":"Right. The family cannot override it."},"es":{"q":"En Indiana, un adulto de 21 años se registra como donante de órganos. Según la Ley de Elección del Donante, ¿puede la familia anular esa decisión después de su muerte?","o":["Sí, decide el pariente más cercano","Sí, si dos parientes están de acuerdo","Solo el cónyuge puede anularla","No, para donantes de 18 años o más la familia no puede anularla"],"h1":"La ley respeta la decisión propia de un adulto.","h2":"En Indiana, según la Ley de Elección del Donante (Donor Choice Law), la familia no puede anular la decisión de donar de una persona de 18 años o más.","p":"Correcto. La familia no puede anularla."},"ref":{"doc":"IN","page":17}},{"id":"in-112","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, what must the operator of a boat with an engine over 10 horsepower usually carry?","o":["A valid driver's license","A fishing license","A car registration","Nothing"],"h1":"Indiana ties boating with big engines to your driving license.","h2":"In Indiana, the operator of a watercraft with an engine over 10 horsepower must carry a valid driver's license (or, at 15 or older without a license, finish an approved boater course and carry an ID card).","p":"Correct. A valid driver's license."},"es":{"q":"En Indiana, ¿qué debe llevar normalmente quien maneja un bote con motor de más de 10 caballos de fuerza?","o":["Una licencia de conducir válida","Una licencia de pesca","El registro de un auto","Nada"],"h1":"Indiana relaciona los botes con motor grande con su licencia de conducir.","h2":"En Indiana, quien maneja una embarcación con motor de más de 10 caballos de fuerza debe llevar una licencia de conducir válida (o, si tiene 15 años o más sin licencia, terminar un curso aprobado de navegación y llevar su tarjeta de identificación).","p":"Correcto. Una licencia de conducir válida."},"ref":{"doc":"IN","page":17}},{"id":"in-113","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, your driver's license is suspended. May you operate a boat with a large engine?","o":["Yes, boats are not covered","No, you may not operate a watercraft while suspended","Only on private lakes","Only with an adult on board"],"h1":"Boating and driving privileges are linked in Indiana.","h2":"In Indiana, if your driver's license is suspended, you may not operate a watercraft.","p":"Right. No boating while suspended."},"es":{"q":"En Indiana, su licencia de conducir está suspendida. ¿Puede manejar un bote con motor grande?","o":["Sí, los botes no cuentan","No, no puede manejar una embarcación mientras está suspendido","Solo en lagos privados","Solo con un adulto a bordo"],"h1":"En Indiana, los privilegios de navegar y de manejar están relacionados.","h2":"En Indiana, si su licencia de conducir está suspendida, no puede manejar una embarcación.","p":"Correcto. No puede navegar mientras está suspendido."},"ref":{"doc":"IN","page":18}},{"id":"in-114","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how do you apply for a disability parking placard?","o":["Ask a police officer to sign a letter","Show your car registration only","Have a health care provider complete State Form 42070","Buy it at any store"],"h1":"A medical professional must confirm you qualify.","h2":"In Indiana, a health care provider (such as a physician) must complete State Form 42070 to show you qualify for a parking placard.","p":"Correct. A health care provider completes the form."},"es":{"q":"En Indiana, ¿cómo se solicita un permiso de estacionamiento para personas con discapacidad (placard)?","o":["Pedir a un policía que firme una carta","Mostrar solo el registro del auto","Pedir a un proveedor de salud que llene el Formulario Estatal 42070","Comprarlo en cualquier tienda"],"h1":"Un profesional de la salud debe confirmar que usted califica.","h2":"En Indiana, un proveedor de salud (como un médico) debe llenar el Formulario Estatal 42070 para mostrar que usted califica para el permiso de estacionamiento.","p":"Correcto. Un proveedor de salud llena el formulario."},"ref":{"doc":"IN","page":18}},{"id":"in-115","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, what is true about a parking placard for a permanent disability?","o":["It costs $50 a year","It expires after one year","It must be renewed every six months","It is free and does not expire unless the disability is no longer permanent"],"h1":"Permanent means it does not need renewing.","h2":"In Indiana, a permanent disability placard is free and does not expire unless a provider certifies the disability is no longer permanent.","p":"Right. Free, and it does not expire."},"es":{"q":"En Indiana, ¿qué es cierto sobre el permiso de estacionamiento por discapacidad permanente?","o":["Cuesta $50 al año","Vence después de un año","Se debe renovar cada seis meses","Es gratis y no vence, a menos que la discapacidad deje de ser permanente"],"h1":"Permanente significa que no hay que renovarlo.","h2":"En Indiana, el permiso por discapacidad permanente es gratis y no vence, a menos que un proveedor certifique que la discapacidad ya no es permanente.","p":"Correcto. Es gratis y no vence."},"ref":{"doc":"IN","page":18}},{"id":"in-116","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, when does a temporary disability parking placard expire?","o":["On the date the health care provider sets, or one year after it is issued, whichever comes first","After five years","When you sell your car","Never"],"h1":"There are two possible dates; the earlier one wins.","h2":"In Indiana, a temporary placard expires on the date set by the health care provider or one year after issue, whichever comes first.","p":"Correct. The provider's date or one year, whichever is first."},"es":{"q":"En Indiana, ¿cuándo vence un permiso temporal de estacionamiento por discapacidad?","o":["En la fecha que fija el proveedor de salud, o un año después de emitirse, lo que ocurra primero","Después de cinco años","Cuando vende su auto","Nunca"],"h1":"Hay dos fechas posibles; vale la que llegue antes.","h2":"En Indiana, el permiso temporal vence en la fecha que fija el proveedor de salud o un año después de emitirse, lo que ocurra primero.","p":"Correcto. La fecha del proveedor o un año, lo que llegue primero."},"ref":{"doc":"IN","page":18}},{"id":"in-117","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, you have a valid disability placard. May you park in the striped area next to an accessible parking space?","o":["Yes, if you have a placard","No, never, even with a placard","Only for 15 minutes","Only at night"],"h1":"That space is needed for wheelchairs and ramps.","h2":"In Indiana, parking in the diagonally striped area next to an accessible space is never allowed, even with a valid placard, because it is needed for wheelchairs and ramps.","p":"Right. Never, even with a placard."},"es":{"q":"En Indiana, usted tiene un permiso de estacionamiento por discapacidad válido. ¿Puede estacionar en el área con rayas junto a un espacio accesible?","o":["Sí, si tiene el permiso","No, nunca, ni siquiera con el permiso","Solo por 15 minutos","Solo de noche"],"h1":"Ese espacio se necesita para sillas de ruedas y rampas.","h2":"En Indiana, nunca se permite estacionar en el área con rayas diagonales junto a un espacio accesible, ni siquiera con un permiso válido, porque se necesita para sillas de ruedas y rampas.","p":"Correcto. Nunca, ni siquiera con permiso."},"ref":{"doc":"IN","page":55}},{"id":"in-118","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, when does a regular (not probationary) driver's license expire?","o":["On December 31 of the year","On the first day of your birth month","At midnight on your birthday","On the date you got your first license"],"h1":"It is tied to a personal date.","h2":"In Indiana, credentials other than a probationary license expire at midnight on your birthday.","p":"Correct. At midnight on your birthday."},"es":{"q":"En Indiana, ¿cuándo vence una licencia de conducir común (no probatoria)?","o":["El 31 de diciembre del año","El primer día del mes de su cumpleaños","A la medianoche del día de su cumpleaños","En la fecha de su primera licencia"],"h1":"Está ligada a una fecha personal.","h2":"En Indiana, las credenciales que no son licencia probatoria vencen a la medianoche del día de su cumpleaños.","p":"Correcto. A la medianoche de su cumpleaños."},"ref":{"doc":"IN","page":19}},{"id":"in-119","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, your license expires on your birthday, which falls on a Sunday when BMV branches are closed. When does it expire?","o":["At noon on Saturday","On the Friday before","It stays valid for 30 more days","At midnight on the next business day"],"h1":"Indiana gives you until the branches are open again.","h2":"In Indiana, if your birthday falls on a day when branches are closed, your credential expires at midnight on the next business day.","p":"Right. At midnight on the next business day."},"es":{"q":"En Indiana, su licencia vence en su cumpleaños, que cae en domingo, cuando las oficinas del BMV están cerradas. ¿Cuándo vence?","o":["Al mediodía del sábado","El viernes anterior","Sigue válida 30 días más","A la medianoche del siguiente día hábil"],"h1":"Indiana le da tiempo hasta que las oficinas abran otra vez.","h2":"En Indiana, si su cumpleaños cae en un día en que las oficinas están cerradas, su credencial vence a la medianoche del siguiente día hábil.","p":"Correcto. A la medianoche del siguiente día hábil."},"ref":{"doc":"IN","page":19}},{"id":"in-120","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, your driver's license has been expired for six years. What must you do to renew it?","o":["Pay a penalty and pass a knowledge exam, a driving skills exam and a vision screening","Only pay a penalty","Only pass a vision screening","Pay a penalty and pass a vision screening"],"h1":"After five years, you must show everything again, including driving.","h2":"In Indiana, renewing a license that has been expired for five years or more requires an administrative penalty, a knowledge exam, a driving skills exam and a vision screening.","p":"Correct. Penalty, knowledge exam, skills exam and vision screening."},"es":{"q":"En Indiana, su licencia de conducir venció hace seis años. ¿Qué debe hacer para renovarla?","o":["Pagar una multa administrativa y aprobar el examen de conocimientos, el examen práctico de manejo y el examen de la vista","Solo pagar una multa","Solo pasar el examen de la vista","Pagar una multa y pasar el examen de la vista"],"h1":"Después de cinco años, debe demostrar todo otra vez, incluido el manejo.","h2":"En Indiana, para renovar una licencia vencida hace cinco años o más hay que pagar una multa administrativa y aprobar el examen de conocimientos, el examen práctico de manejo y el examen de la vista.","p":"Correcto. Multa, examen de conocimientos, examen práctico y examen de la vista."},"ref":{"doc":"IN","page":19}},{"id":"in-121","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a U.S. citizen wants to renew a driver's license early. How far before it expires may they renew?","o":["Only in the last 30 days","Up to 24 months before","Up to five years before","Only after it expires"],"h1":"It is a long window of about two years.","h2":"In Indiana, U.S. citizens and people with permanent lawful status may renew a license or ID card up to 24 months before it expires.","p":"Right. Up to 24 months early."},"es":{"q":"En Indiana, un ciudadano de EE. UU. quiere renovar su licencia antes de tiempo. ¿Con cuánta anticipación puede renovarla?","o":["Solo en los últimos 30 días","Hasta 24 meses antes","Hasta cinco años antes","Solo después de que venza"],"h1":"Es un plazo largo de unos dos años.","h2":"En Indiana, los ciudadanos de EE. UU. y las personas con residencia legal permanente pueden renovar la licencia o la tarjeta de identificación hasta 24 meses antes de que venza.","p":"Correcto. Hasta 24 meses antes."},"ref":{"doc":"IN","page":19}},{"id":"in-122","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how early may you renew a learner's permit?","o":["Up to one year before it expires","Up to six months before it expires","Up to 30 days before it expires","Only after it has expired"],"h1":"The window is about one month.","h2":"In Indiana, a learner's permit may be renewed up to 30 days before it expires.","p":"Correct. Up to 30 days early."},"es":{"q":"En Indiana, ¿con cuánta anticipación puede renovar un permiso de aprendizaje?","o":["Hasta un año antes de que venza","Hasta seis meses antes de que venza","Hasta 30 días antes de que venza","Solo después de que haya vencido"],"h1":"El plazo es de más o menos un mes.","h2":"En Indiana, un permiso de aprendizaje se puede renovar hasta 30 días antes de que venza.","p":"Correcto. Hasta 30 días antes."},"ref":{"doc":"IN","page":19}},{"id":"in-123","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a soldier's license expired while serving outside the state. How long does it stay valid after discharge?","o":["7 days","One year","It is canceled right away","90 days"],"h1":"It gives about three months to get home and renew.","h2":"In Indiana, a license of someone serving in the armed forces outside the state stays valid for 90 days after discharge or after they stop living outside Indiana because of service.","p":"Right. 90 days."},"es":{"q":"En Indiana, la licencia de un militar venció mientras servía fuera del estado. ¿Por cuánto tiempo sigue válida después de su baja?","o":["7 días","Un año","Se cancela de inmediato","90 días"],"h1":"Da unos tres meses para volver y renovar.","h2":"En Indiana, la licencia de una persona que sirve en las fuerzas armadas fuera del estado sigue válida por 90 días después de su baja o después de que deja de vivir fuera de Indiana por el servicio.","p":"Correcto. 90 días."},"ref":{"doc":"IN","page":19}},{"id":"in-124","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you legally changed your name. What should you do first?","o":["Change it with the Social Security Administration, then visit a BMV branch within 30 days","Visit the BMV the same day","Change it online at myBMV only","Wait until your license expires"],"h1":"The BMV checks your name against Social Security records.","h2":"In Indiana, you first change your name with the Social Security Administration, wait at least one business day, then visit a BMV branch within 30 days to amend your credential.","p":"Correct. Social Security first, then the BMV within 30 days."},"es":{"q":"En Indiana, usted cambió legalmente su nombre. ¿Qué debe hacer primero?","o":["Cambiarlo en la Administración del Seguro Social y luego ir a una oficina del BMV dentro de 30 días","Ir al BMV el mismo día","Cambiarlo solo en línea en myBMV","Esperar a que venza su licencia"],"h1":"El BMV compara su nombre con los registros del Seguro Social.","h2":"En Indiana, primero cambia su nombre en la Administración del Seguro Social, espera al menos un día hábil y luego va a una oficina del BMV dentro de 30 días para modificar su credencial.","p":"Correcto. Primero el Seguro Social, luego el BMV dentro de 30 días."},"ref":{"doc":"IN","page":20}},{"id":"in-125","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, you lost your license and your name and address have not changed. How many times may you replace it online before you must visit a branch?","o":["Only once","Up to 10 times","Up to 3 times","As many times as you want"],"h1":"It is a fairly high number, but there is a limit.","h2":"In Indiana, you may replace your credential online a maximum of 10 times before you must visit a BMV branch.","p":"Right. Up to 10 times online."},"es":{"q":"En Indiana, usted perdió su licencia y su nombre y dirección no han cambiado. ¿Cuántas veces puede reemplazarla en línea antes de tener que ir a una oficina?","o":["Solo una vez","Hasta 10 veces","Hasta 3 veces","Todas las veces que quiera"],"h1":"Es un número bastante alto, pero hay un límite.","h2":"En Indiana, puede reemplazar su credencial en línea un máximo de 10 veces antes de tener que ir a una oficina del BMV.","p":"Correcto. Hasta 10 veces en línea."},"ref":{"doc":"IN","page":20}},{"id":"in-126","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how many points do you get for driving 1 to 15 mph over the speed limit?","o":["2 points","4 points","6 points","8 points"],"h1":"It is the lowest speeding level in Indiana's table.","h2":"In Indiana, driving 1 to 15 mph over the speed limit adds 2 points to your record.","p":"Correct. 2 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por manejar de 1 a 15 mph sobre el límite de velocidad?","o":["2 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Es el nivel más bajo de exceso de velocidad en la tabla de Indiana.","h2":"En Indiana, manejar de 1 a 15 mph sobre el límite agrega 2 puntos a su historial.","p":"Correcto. 2 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-127","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many points do you get for driving 16 to 25 mph over the speed limit?","o":["2 points","4 points","6 points","8 points"],"h1":"It is the middle speeding level.","h2":"In Indiana, driving 16 to 25 mph over the speed limit adds 4 points to your record.","p":"Right. 4 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por manejar de 16 a 25 mph sobre el límite de velocidad?","o":["2 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Es el nivel medio de exceso de velocidad.","h2":"En Indiana, manejar de 16 a 25 mph sobre el límite agrega 4 puntos a su historial.","p":"Correcto. 4 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-128","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many points do you get for failing to use your headlights when required?","o":["6 points","8 points","2 points","4 points"],"h1":"It is one of the smaller point values.","h2":"In Indiana, failure to use headlights adds 2 points to your driving record.","p":"Correct. 2 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por no usar los faros cuando se requieren?","o":["6 puntos","8 puntos","2 puntos","4 puntos"],"h1":"Es uno de los valores más bajos.","h2":"En Indiana, no usar los faros agrega 2 puntos a su historial de manejo.","p":"Correcto. 2 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-129","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, how many points do you get for running a stop sign or a yield sign?","o":["2 points","6 points","8 points","4 points"],"h1":"It is the same as a hand-held phone violation.","h2":"In Indiana, disregarding a stop sign or yield sign adds 4 points to your record.","p":"Right. 4 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por no respetar una señal de alto o de ceda el paso?","o":["2 puntos","6 puntos","8 puntos","4 puntos"],"h1":"Es lo mismo que por usar el teléfono en la mano.","h2":"En Indiana, no respetar una señal de alto o de ceda el paso agrega 4 puntos a su historial.","p":"Correcto. 4 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-130","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how many points do you get for failing to yield to an emergency vehicle?","o":["6 points","2 points","4 points","8 points"],"h1":"It is one of the higher values, the same as tailgating.","h2":"In Indiana, failing to yield to an emergency vehicle adds 6 points to your record.","p":"Correct. 6 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por no ceder el paso a un vehículo de emergencia?","o":["6 puntos","2 puntos","4 puntos","8 puntos"],"h1":"Es uno de los valores más altos, igual que seguir demasiado cerca.","h2":"En Indiana, no ceder el paso a un vehículo de emergencia agrega 6 puntos a su historial.","p":"Correcto. 6 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-131","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how many points do you get for following another vehicle too closely?","o":["2 points","6 points","4 points","8 points"],"h1":"Indiana treats tailgating as a serious violation.","h2":"In Indiana, following another vehicle too closely adds 6 points to your record.","p":"Right. 6 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por seguir a otro vehículo demasiado cerca?","o":["2 puntos","6 puntos","4 puntos","8 puntos"],"h1":"Indiana considera grave ir pegado a otro vehículo.","h2":"En Indiana, seguir a otro vehículo demasiado cerca agrega 6 puntos a su historial.","p":"Correcto. 6 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-132","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many points do you get for driving while your license is suspended?","o":["2 points","4 points","8 points","6 points"],"h1":"It is the highest value in the handbook's examples.","h2":"In Indiana, driving while suspended adds 8 points to your record and can also lead to criminal charges.","p":"Correct. 8 points."},"es":{"q":"En Indiana, ¿cuántos puntos recibe por manejar con la licencia suspendida?","o":["2 puntos","4 puntos","8 puntos","6 puntos"],"h1":"Es el valor más alto de los ejemplos del manual.","h2":"En Indiana, manejar con la licencia suspendida agrega 8 puntos a su historial y además puede llevar a cargos penales.","p":"Correcto. 8 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-133","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, which violation adds 8 points to your record?","o":["Failure to use headlights","Unsafe lane movement","No brake lights","A speed contest (racing) on the road"],"h1":"Racing on public roads is treated very seriously.","h2":"In Indiana, a speed contest on the road adds 8 points to your driving record.","p":"Right. A speed contest is 8 points."},"es":{"q":"En Indiana, ¿qué infracción agrega 8 puntos a su historial?","o":["No usar los faros","Cambio de carril inseguro","No tener luces de freno","Una competencia de velocidad (carrera) en la calle"],"h1":"Las carreras en vías públicas se toman muy en serio.","h2":"En Indiana, una competencia de velocidad en la calle agrega 8 puntos a su historial de manejo.","p":"Correcto. Una carrera son 8 puntos."},"ref":{"doc":"IN","page":21}},{"id":"in-134","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, how often can you receive the four-point credit for finishing a Driver Safety Program course?","o":["Once in a three-year period","Once a year","Every time you finish a course","Once in your lifetime"],"h1":"There is a limit so the credit cannot be used again and again.","h2":"In Indiana, each driver may receive one four-point Driver Safety Program credit during a three-year period.","p":"Correct. Once every three years."},"es":{"q":"En Indiana, ¿cada cuánto puede recibir el crédito de cuatro puntos por terminar un curso del Programa de Seguridad Vial (DSP)?","o":["Una vez en un período de tres años","Una vez al año","Cada vez que termina un curso","Una vez en la vida"],"h1":"Hay un límite para que el crédito no se use una y otra vez.","h2":"En Indiana, cada conductor puede recibir un crédito de cuatro puntos del Programa de Seguridad Vial durante un período de tres años.","p":"Correcto. Una vez cada tres años."},"ref":{"doc":"IN","page":21}},{"id":"in-135","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, the BMV mails you a notice that you must take a Driver Safety Program course. How long do you have to finish it?","o":["30 days","90 days","One year","Two years"],"h1":"It is about three months.","h2":"In Indiana, you must finish a required BMV-approved Driver Safety Program within 90 days of the notice, or your driving privileges will be suspended.","p":"Right. 90 days."},"es":{"q":"En Indiana, el BMV le envía un aviso de que debe tomar un curso del Programa de Seguridad Vial. ¿Cuánto tiempo tiene para terminarlo?","o":["30 días","90 días","Un año","Dos años"],"h1":"Son unos tres meses.","h2":"En Indiana, debe terminar el Programa de Seguridad Vial aprobado por el BMV dentro de 90 días desde el aviso, o le suspenderán los privilegios de manejo.","p":"Correcto. 90 días."},"ref":{"doc":"IN","page":21}},{"id":"in-136","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, a 30-year-old driver is convicted of two traffic offenses. When may the BMV require a Driver Safety Program course?","o":["After any single ticket","Only after a crash","When the two offenses happen within 12 months","Only after five offenses"],"h1":"For drivers 21 and older, the time between the tickets matters.","h2":"In Indiana, the BMV may require drivers 21 and older to take a Driver Safety Program course after two or more traffic offenses within 12 months.","p":"Correct. Two offenses within 12 months."},"es":{"q":"En Indiana, un conductor de 30 años recibe condena por dos infracciones de tránsito. ¿Cuándo puede el BMV exigirle un curso del Programa de Seguridad Vial?","o":["Después de cualquier multa","Solo después de un choque","Cuando las dos infracciones ocurren dentro de 12 meses","Solo después de cinco infracciones"],"h1":"Para conductores de 21 años o más, importa el tiempo entre las multas.","h2":"En Indiana, el BMV puede exigir a conductores de 21 años o más un curso del Programa de Seguridad Vial después de dos o más infracciones dentro de 12 meses.","p":"Correcto. Dos infracciones en 12 meses."},"ref":{"doc":"IN","page":21}},{"id":"in-137","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a judge orders you to take a driver safety course. When will it also give you the four-point credit?","o":["Always, for any course","Never","Only if you pay an extra fee","Only if the course is a BMV-approved Driver Safety Program"],"h1":"The BMV gives the credit only for its own approved courses.","h2":"In Indiana, a court-ordered course gives the four-point credit only if it is a BMV-approved Driver Safety Program.","p":"Right. Only a BMV-approved course earns the credit."},"es":{"q":"En Indiana, un juez le ordena tomar un curso de seguridad vial. ¿Cuándo le dará también el crédito de cuatro puntos?","o":["Siempre, con cualquier curso","Nunca","Solo si paga una tarifa extra","Solo si el curso es un Programa de Seguridad Vial aprobado por el BMV"],"h1":"El BMV solo da el crédito por sus propios cursos aprobados.","h2":"En Indiana, un curso ordenado por el tribunal da el crédito de cuatro puntos solo si es un Programa de Seguridad Vial aprobado por el BMV.","p":"Correcto. Solo un curso aprobado por el BMV da el crédito."},"ref":{"doc":"IN","page":22}},{"id":"in-138","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, the BMV asks you for proof of insurance after a crash. What is the correct way to give it?","o":["Your insurance company files a Certificate of Compliance electronically with the BMV","You mail a photo of your insurance card","You show your card at any police station","You sign a promise that you were insured"],"h1":"Your insurer sends it, not you.","h2":"In Indiana, proof of financial responsibility is a Certificate of Compliance (COC) that your insurance provider files electronically with the BMV.","p":"Correct. The insurer files a Certificate of Compliance."},"es":{"q":"En Indiana, el BMV le pide prueba de seguro después de un choque. ¿Cuál es la forma correcta de darla?","o":["Su compañía de seguros presenta electrónicamente un Certificado de Cumplimiento ante el BMV","Usted envía por correo una foto de su tarjeta de seguro","Usted muestra su tarjeta en cualquier estación de policía","Usted firma una promesa de que tenía seguro"],"h1":"La envía su aseguradora, no usted.","h2":"En Indiana, la prueba de responsabilidad financiera es un Certificado de Cumplimiento (COC) que su aseguradora presenta electrónicamente ante el BMV.","p":"Correcto. La aseguradora presenta un Certificado de Cumplimiento."},"ref":{"doc":"IN","page":22}},{"id":"in-139","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, the BMV mails you a request to verify your insurance. How long do you have before your driving privileges are suspended?","o":["10 days","90 days","One year","There is no time limit"],"h1":"It is about three months.","h2":"In Indiana, the Certificate of Compliance must be received and processed by the BMV within 90 days of the request, or your driving privileges will be suspended.","p":"Right. 90 days."},"es":{"q":"En Indiana, el BMV le envía una solicitud para verificar su seguro. ¿Cuánto tiempo tiene antes de que suspendan sus privilegios de manejo?","o":["10 días","90 días","Un año","No hay límite de tiempo"],"h1":"Son unos tres meses.","h2":"En Indiana, el BMV debe recibir y procesar el Certificado de Cumplimiento dentro de 90 días desde la solicitud, o le suspenderán los privilegios de manejo.","p":"Correcto. 90 días."},"ref":{"doc":"IN","page":22}},{"id":"in-140","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, a court suspends your license for driving without insurance. What must your insurer file before you can be reinstated?","o":["A police report","A letter from your employer","An SR22 form, proof of future financial responsibility","A copy of your car title"],"h1":"It is a special form that shows you will stay insured.","h2":"In Indiana, after a court suspension for driving without insurance, your insurance provider must electronically file an SR22 to reinstate your driving privileges.","p":"Correct. An SR22 form."},"es":{"q":"En Indiana, un tribunal suspende su licencia por manejar sin seguro. ¿Qué debe presentar su aseguradora para que lo restablezcan?","o":["Un informe de la policía","Una carta de su empleador","Un formulario SR22, prueba de responsabilidad financiera futura","Una copia del título de su auto"],"h1":"Es un formulario especial que muestra que seguirá asegurado.","h2":"En Indiana, después de una suspensión judicial por manejar sin seguro, su aseguradora debe presentar electrónicamente un SR22 para restablecer sus privilegios de manejo.","p":"Correcto. Un formulario SR22."},"ref":{"doc":"IN","page":22}},{"id":"in-141","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you have an indefinite suspension for having no insurance. How can it end?","o":["It ends by itself after 30 days","By paying a $50 fine only","By taking a driving test","By keeping an SR22 on file continuously for 180 days"],"h1":"You must show you stay insured for about six months.","h2":"In Indiana, an indefinite no-insurance suspension can be stayed when the BMV receives an SR22 and ends after the SR22 is kept continuously for 180 days.","p":"Right. Keep an SR22 for 180 days."},"es":{"q":"En Indiana, usted tiene una suspensión indefinida por no tener seguro. ¿Cómo puede terminar?","o":["Termina sola después de 30 días","Solo pagando una multa de $50","Tomando un examen de manejo","Manteniendo un SR22 registrado sin interrupción por 180 días"],"h1":"Debe mostrar que sigue asegurado por unos seis meses.","h2":"En Indiana, una suspensión indefinida por falta de seguro se puede detener cuando el BMV recibe un SR22 y termina después de mantener el SR22 sin interrupción por 180 días.","p":"Correcto. Mantenga un SR22 por 180 días."},"ref":{"doc":"IN","page":23}},{"id":"in-142","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, what is the reinstatement fee after a second suspension for driving without insurance?","o":["$500","$250","$1,000","$150"],"h1":"It is double the fee for a first suspension.","h2":"In Indiana, the reinstatement fee for a second no-insurance suspension is $500.","p":"Correct. $500."},"es":{"q":"En Indiana, ¿cuál es la tarifa de restablecimiento después de una segunda suspensión por manejar sin seguro?","o":["$500","$250","$1,000","$150"],"h1":"Es el doble de la tarifa de la primera suspensión.","h2":"En Indiana, la tarifa de restablecimiento por una segunda suspensión por falta de seguro es de $500.","p":"Correcto. $500."},"ref":{"doc":"IN","page":23}},{"id":"in-143","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, what is the reinstatement fee for a third or later no-insurance suspension?","o":["$500","$1,000","$750","$2,500"],"h1":"It doubles again after the second one.","h2":"In Indiana, the reinstatement fee for a third or later no-insurance suspension (one that happened after January 1, 2015) is $1,000.","p":"Right. $1,000."},"es":{"q":"En Indiana, ¿cuál es la tarifa de restablecimiento por una tercera suspensión, o posterior, por falta de seguro?","o":["$500","$1,000","$750","$2,500"],"h1":"Se duplica otra vez después de la segunda.","h2":"En Indiana, la tarifa de restablecimiento por una tercera suspensión o posterior por falta de seguro (ocurrida después del 1 de enero de 2015) es de $1,000.","p":"Correcto. $1,000."},"ref":{"doc":"IN","page":23}},{"id":"in-144","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, you have an SR22 requirement and your insurer sends the BMV an SR26 form. What does that mean?","o":["Your coverage was increased","You earned a safe-driver discount","Your SR22 insurance was canceled, so your license will be suspended","Your car was registered"],"h1":"An SR26 is the opposite of an SR22.","h2":"In Indiana, an SR26 tells the BMV that your SR22 insurance was canceled, so the BMV must suspend your driving privileges until a new SR22 is filed.","p":"Correct. The SR22 was canceled, so you will be suspended."},"es":{"q":"En Indiana, usted tiene el requisito de SR22 y su aseguradora envía al BMV un formulario SR26. ¿Qué significa?","o":["Aumentaron su cobertura","Recibió un descuento de buen conductor","Se canceló su seguro SR22, así que suspenderán su licencia","Se registró su auto"],"h1":"Un SR26 es lo contrario de un SR22.","h2":"En Indiana, un SR26 le avisa al BMV que se canceló su seguro SR22, así que el BMV debe suspender sus privilegios de manejo hasta recibir un nuevo SR22.","p":"Correcto. Se canceló el SR22 y lo suspenderán."},"ref":{"doc":"IN","page":23}},{"id":"in-145","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you get a traffic ticket and you do not go to court or pay it. What can happen?","o":["Nothing, if it was a small ticket","The ticket is canceled after a year","Only your insurance rate goes up","Your driving privileges can be suspended"],"h1":"Ignoring a ticket has a cost for your license.","h2":"In Indiana, failing to appear in court or to pay a traffic ticket after judgment may lead to suspension of your driving privileges.","p":"Right. Your license can be suspended."},"es":{"q":"En Indiana, usted recibe una multa de tránsito y no va al tribunal ni la paga. ¿Qué puede pasar?","o":["Nada, si era una multa pequeña","La multa se cancela después de un año","Solo sube el precio de su seguro","Pueden suspender sus privilegios de manejo"],"h1":"Ignorar una multa tiene consecuencias para su licencia.","h2":"En Indiana, no presentarse al tribunal o no pagar una multa de tránsito después del fallo puede llevar a la suspensión de sus privilegios de manejo.","p":"Correcto. Pueden suspender su licencia."},"ref":{"doc":"IN","page":23}},{"id":"in-146","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a driver with no earlier drunk driving conviction refuses a chemical test. How long is the license suspended?","o":["One year","90 days","180 days","Two years"],"h1":"Refusing is treated more harshly than failing the test.","h2":"In Indiana, a driver who refuses a chemical test faces a one-year suspension (two years with a prior OWI conviction).","p":"Correct. One year."},"es":{"q":"En Indiana, un conductor sin condena anterior por manejar ebrio se niega a una prueba química. ¿Por cuánto tiempo suspenden la licencia?","o":["Un año","90 días","180 días","Dos años"],"h1":"Negarse se castiga más que reprobar la prueba.","h2":"En Indiana, un conductor que se niega a una prueba química recibe una suspensión de un año (dos años si tiene una condena anterior por OWI).","p":"Correcto. Un año."},"ref":{"doc":"IN","page":24}},{"id":"in-147","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, which three things mainly decide a person's blood alcohol concentration (BAC)?","o":["Age, height and the type of car","How much alcohol, how fast it is drunk, and body weight","The time of day, food color and the weather","Only the kind of drink"],"h1":"Think about the amount, the speed and the size of the person.","h2":"In Indiana, the main factors in a person's BAC are the amount of alcohol, how quickly it is consumed, and the person's body weight.","p":"Right. Amount, speed of drinking and body weight."},"es":{"q":"En Indiana, ¿qué tres cosas determinan principalmente la concentración de alcohol en la sangre (BAC) de una persona?","o":["La edad, la estatura y el tipo de auto","Cuánto alcohol, qué tan rápido se toma y el peso del cuerpo","La hora del día, el color de la comida y el clima","Solo el tipo de bebida"],"h1":"Piense en la cantidad, la rapidez y el tamaño de la persona.","h2":"En Indiana, los factores principales del BAC de una persona son la cantidad de alcohol, qué tan rápido se toma y el peso del cuerpo.","p":"Correcto. Cantidad, rapidez y peso del cuerpo."},"ref":{"doc":"IN","page":23}},{"id":"in-148","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, a court orders an ignition interlock device after a drunk driving case. What does the device do?","o":["Tracks the car's location for police","Limits the car to 45 mph","Tests the driver's blood alcohol before the car can start","Locks the doors while driving"],"h1":"It checks the driver before the engine runs.","h2":"In Indiana, an ignition interlock device tests the driver's blood alcohol level before the car can be started.","p":"Correct. It tests the driver before the car starts."},"es":{"q":"En Indiana, un tribunal ordena un dispositivo de bloqueo de encendido después de un caso de manejo en estado de ebriedad. ¿Qué hace el dispositivo?","o":["Sigue la ubicación del auto para la policía","Limita el auto a 45 mph","Mide el alcohol en la sangre del conductor antes de que el auto pueda arrancar","Cierra las puertas mientras maneja"],"h1":"Revisa al conductor antes de que el motor funcione.","h2":"En Indiana, el dispositivo de bloqueo de encendido mide el nivel de alcohol del conductor antes de que el auto pueda arrancar.","p":"Correcto. Revisa al conductor antes de arrancar."},"ref":{"doc":"IN","page":24}},{"id":"in-149","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, you are convicted of operating a boat while intoxicated. What happens to your driving privileges?","o":["Nothing; boating is separate","You only pay a boating fine","You lose only your fishing license","They face the same penalties as drunk driving in a car"],"h1":"Indiana adds boating offenses to your driver record.","h2":"In Indiana, a conviction for operating a watercraft while intoxicated goes on your driver record and carries the same driving-privilege penalties as for a motor vehicle.","p":"Right. The same penalties as drunk driving."},"es":{"q":"En Indiana, recibe condena por manejar un bote en estado de ebriedad. ¿Qué pasa con sus privilegios de manejo?","o":["Nada; navegar es aparte","Solo paga una multa de navegación","Solo pierde su licencia de pesca","Reciben las mismas sanciones que por manejar ebrio un auto"],"h1":"Indiana agrega las infracciones en botes a su historial de manejo.","h2":"En Indiana, una condena por manejar una embarcación en estado de ebriedad pasa a su historial de manejo y tiene las mismas sanciones sobre sus privilegios de manejo que con un vehículo.","p":"Correcto. Las mismas sanciones que por manejar ebrio."},"ref":{"doc":"IN","page":24}},{"id":"in-150","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, you pay a BMV fee with a check that bounces. What happens?","o":["The BMV indefinitely suspends your driving privileges until you pay everything owed","Nothing; the BMV just sends a bill","You get 2 points","Your car registration is canceled only"],"h1":"Unpaid BMV payments affect your license.","h2":"In Indiana, if a payment to the BMV is not honored, the BMV indefinitely suspends your driving privileges until you pay the amount plus service, collection and reinstatement fees.","p":"Correct. Your driving privileges are suspended."},"es":{"q":"En Indiana, usted paga una tarifa del BMV con un cheque sin fondos. ¿Qué pasa?","o":["El BMV suspende indefinidamente sus privilegios de manejo hasta que pague todo lo que debe","Nada; el BMV solo le envía una factura","Recibe 2 puntos","Solo se cancela el registro de su auto"],"h1":"Los pagos no cubiertos al BMV afectan su licencia.","h2":"En Indiana, si un pago al BMV no es cubierto, el BMV suspende indefinidamente sus privilegios de manejo hasta que pague el monto más las tarifas de servicio, cobro y restablecimiento.","p":"Correcto. Le suspenden los privilegios de manejo."},"ref":{"doc":"IN","page":24}},{"id":"in-151","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, how can you see your driver record for free?","o":["Call the police","Log in to myBMV.com and open the Viewable Driver Record","Ask your insurance company","Visit the courthouse"],"h1":"It is online, through your BMV account.","h2":"In Indiana, you can view your driver record at no charge on myBMV.com; an Official Driver Record you can print costs $4.","p":"Right. On myBMV.com."},"es":{"q":"En Indiana, ¿cómo puede ver su historial de manejo gratis?","o":["Llamar a la policía","Entrar a myBMV.com y abrir el Viewable Driver Record","Preguntar a su compañía de seguros","Ir al juzgado"],"h1":"Es en línea, en su cuenta del BMV.","h2":"En Indiana, puede ver su historial de manejo sin costo en myBMV.com; un historial oficial (Official Driver Record) para imprimir cuesta $4.","p":"Correcto. En myBMV.com."},"ref":{"doc":"IN","page":24}},{"id":"in-152","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, a driver gets 10 traffic violations in 10 years, and one is a major offense like reckless driving. What happens?","o":["A warning letter","A 30-day suspension","A five-year suspension as a habitual traffic violator","A lifetime suspension"],"h1":"This is the habitual traffic violator rule for many tickets.","h2":"In Indiana, a driver with 10 or more violations in 10 years, including one major offense, is a habitual traffic violator and faces a five-year suspension.","p":"Correct. A five-year suspension."},"es":{"q":"En Indiana, un conductor recibe 10 infracciones de tránsito en 10 años, y una es grave, como manejo imprudente. ¿Qué pasa?","o":["Una carta de advertencia","Una suspensión de 30 días","Una suspensión de cinco años como infractor habitual","Una suspensión de por vida"],"h1":"Es la regla de infractor habitual por muchas multas.","h2":"En Indiana, un conductor con 10 o más infracciones en 10 años, incluida una grave, es infractor habitual de tránsito (HTV) y recibe una suspensión de cinco años.","p":"Correcto. Una suspensión de cinco años."},"ref":{"doc":"IN","page":26}},{"id":"in-153","scope":"IN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Indiana, a driver has three judgments in 10 years for offenses such as drunk driving or reckless driving. What is the suspension?","o":["One year","Two years","Five years","10 years"],"h1":"Three major offenses bring the longest fixed term in this list.","h2":"In Indiana, three major offense judgments within 10 years make you a habitual traffic violator with a 10-year suspension.","p":"Right. 10 years."},"es":{"q":"En Indiana, un conductor tiene tres fallos en 10 años por delitos como manejar ebrio o manejo imprudente. ¿Cuál es la suspensión?","o":["Un año","Dos años","Cinco años","10 años"],"h1":"Tres delitos graves traen el plazo fijo más largo de esta lista.","h2":"En Indiana, tres fallos por delitos graves dentro de 10 años lo convierten en infractor habitual con una suspensión de 10 años.","p":"Correcto. 10 años."},"ref":{"doc":"IN","page":25}},{"id":"in-154","scope":"IN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Indiana, a driver has two judgments within 10 years for drunk driving that caused a death. What is the suspension?","o":["For life","10 years","Five years","Two years"],"h1":"This is the most severe penalty in the habitual violator rules.","h2":"In Indiana, two judgments within 10 years for operating while intoxicated (or at .08 or more) resulting in death bring a lifetime suspension.","p":"Correct. For life."},"es":{"q":"En Indiana, un conductor tiene dos fallos dentro de 10 años por manejar ebrio causando una muerte. ¿Cuál es la suspensión?","o":["De por vida","10 años","Cinco años","Dos años"],"h1":"Es la sanción más severa de las reglas de infractor habitual.","h2":"En Indiana, dos fallos dentro de 10 años por manejar en estado de ebriedad (o con .08 o más) causando una muerte traen una suspensión de por vida.","p":"Correcto. De por vida."},"ref":{"doc":"IN","page":25}},{"id":"in-155","scope":"IN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Indiana, a court gives you specialized driving privileges (restriction 5). What must you do while driving?","o":["Drive only on weekends","Keep an SR22 on file and carry a copy of the court order","Drive only with a parent","Display a special plate"],"h1":"Police may ask to see proof of the court's permission.","h2":"In Indiana, a driver with specialized driving privileges must keep an SR22 on file and carry a copy of the court order, showing it to police on request.","p":"Right. Keep an SR22 and carry the court order."},"es":{"q":"En Indiana, un tribunal le da privilegios de manejo especiales (restricción 5). ¿Qué debe hacer al manejar?","o":["Manejar solo los fines de semana","Mantener un SR22 registrado y llevar una copia de la orden del tribunal","Manejar solo con uno de sus padres","Poner una placa especial"],"h1":"La policía puede pedirle prueba del permiso del tribunal.","h2":"En Indiana, un conductor con privilegios de manejo especiales debe mantener un SR22 registrado y llevar una copia de la orden del tribunal, y mostrarla a la policía si se la piden.","p":"Correcto. SR22 y copia de la orden."},"ref":{"doc":"IN","page":26}},{"id":"in-156","scope":"IN","cat":"signals","sign":null,"c":2,"en":{"q":"In Indiana, a vehicle ahead has an orange triangle with a red border on the back. What does it tell you?","o":["It carries hazardous materials","It is a police vehicle","It is a slow-moving vehicle that cannot go faster than 25 mph","It is about to turn left"],"h1":"You often see it on farm equipment.","h2":"In Indiana, the slow-moving vehicle emblem (orange center, red border) marks a vehicle that cannot exceed 25 mph, so slow down early.","p":"Correct. A slow vehicle, 25 mph or less."},"es":{"q":"En Indiana, un vehículo delante tiene atrás un triángulo anaranjado con borde rojo. ¿Qué le indica?","o":["Lleva materiales peligrosos","Es un vehículo de policía","Es un vehículo lento que no puede ir a más de 25 mph","Va a girar a la izquierda"],"h1":"Se ve a menudo en maquinaria agrícola.","h2":"En Indiana, el emblema de vehículo lento (centro anaranjado, borde rojo) marca un vehículo que no puede pasar de 25 mph, así que baje la velocidad con tiempo.","p":"Correcto. Un vehículo lento, de 25 mph o menos."},"ref":{"doc":"IN","page":30}},{"id":"in-157","scope":"IN","cat":"signals","sign":null,"c":3,"en":{"q":"In Indiana, when may you turn left at a red light?","o":["Never","When no cars are coming from the left","After honking","After a full stop, from a one-way street onto another one-way street"],"h1":"Both streets must go only one way.","h2":"In Indiana, you may turn left on red only from a one-way street onto a one-way street, after a full stop, when the way is clear and no sign forbids it.","p":"Right. One-way onto one-way, after a full stop."},"es":{"q":"En Indiana, ¿cuándo puede girar a la izquierda con la luz roja?","o":["Nunca","Cuando no vienen autos por la izquierda","Después de tocar la bocina","Después de detenerse por completo, de una calle de un solo sentido a otra de un solo sentido"],"h1":"Las dos calles deben ser de un solo sentido.","h2":"En Indiana, puede girar a la izquierda con luz roja solo de una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo, si el paso está libre y ninguna señal lo prohíbe.","p":"Correcto. De un solo sentido a un solo sentido, después de detenerse."},"ref":{"doc":"IN","page":34}},{"id":"in-158","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, you have a green light with no arrow and want to turn left. How many vehicles may move into the intersection at a time to turn left?","o":["Only one","Two","Three","As many as fit"],"h1":"The rule keeps the intersection from filling up.","h2":"In Indiana, when turning left on a green light without an arrow, you must yield to oncoming traffic, and only one vehicle at a time may move into the intersection to turn left.","p":"Correct. One vehicle at a time."},"es":{"q":"En Indiana, usted tiene luz verde sin flecha y quiere girar a la izquierda. ¿Cuántos vehículos pueden entrar a la intersección a la vez para girar a la izquierda?","o":["Solo uno","Dos","Tres","Todos los que quepan"],"h1":"La regla evita que la intersección se llene.","h2":"En Indiana, al girar a la izquierda con luz verde sin flecha, debe ceder el paso al tráfico que viene de frente, y solo un vehículo a la vez puede entrar a la intersección para girar a la izquierda.","p":"Correcto. Un vehículo a la vez."},"ref":{"doc":"IN","page":34}},{"id":"in-159","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, you and another driver reach an all-way stop at the same time. The other car is on your right. Who must yield?","o":["The driver on the right","You, because you are the driver on the left","The bigger vehicle","Whoever honks first"],"h1":"Indiana's rule names the vehicle on one side.","h2":"In Indiana, when two vehicles reach an all-way stop at the same time, the vehicle on the left yields to the vehicle on the right.","p":"Right. The driver on the left yields."},"es":{"q":"En Indiana, usted y otro conductor llegan al mismo tiempo a un alto en todas las direcciones. El otro auto está a su derecha. ¿Quién debe ceder el paso?","o":["El conductor de la derecha","Usted, porque es el conductor de la izquierda","El vehículo más grande","El que toque la bocina primero"],"h1":"La regla de Indiana nombra al vehículo de un lado.","h2":"En Indiana, cuando dos vehículos llegan al mismo tiempo a un alto en todas las direcciones, el vehículo de la izquierda cede el paso al de la derecha.","p":"Correcto. Cede el conductor de la izquierda."},"ref":{"doc":"IN","page":39}},{"id":"in-160","scope":"IN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Indiana, you come to an intersection where the traffic light is not working at all. What should you do?","o":["Drive through at normal speed","Honk and go","Stop first, then go with care, yielding as at an all-way stop","Wait until the light starts working"],"h1":"Treat it the way you treat an all-way stop.","h2":"In Indiana, at a non-operating signal you stop first, then go with caution after yielding to cross traffic already in the intersection, vehicles that stopped before you, a vehicle on your right that arrived at the same time, and pedestrians.","p":"Correct. Stop, then yield as at an all-way stop."},"es":{"q":"En Indiana, llega a una intersección donde el semáforo no funciona. ¿Qué debe hacer?","o":["Pasar a velocidad normal","Tocar la bocina y seguir","Detenerse primero y luego seguir con cuidado, cediendo el paso como en un alto en todas las direcciones","Esperar a que el semáforo vuelva a funcionar"],"h1":"Trátelo como un alto en todas las direcciones.","h2":"En Indiana, ante un semáforo que no funciona, primero se detiene y luego avanza con cuidado después de ceder el paso al tráfico que ya está en la intersección, a los vehículos que se detuvieron antes, a un vehículo a su derecha que llegó al mismo tiempo y a los peatones.","p":"Correcto. Deténgase y ceda como en un alto en todas las direcciones."},"ref":{"doc":"IN","page":35}},{"id":"in-161","scope":"IN","cat":"signals","sign":null,"c":3,"en":{"q":"In Indiana, motorcycle riders may go through a red light that will not change after waiting two minutes. Which vehicle may NOT use this rule?","o":["A motorcycle","A motor driven cycle","A bicycle at a bicycle signal","An autocycle"],"h1":"It is the three-wheeled vehicle with a steering wheel.","h2":"In Indiana, the two-minute rule for a red light that does not change applies to motorcycles and motor driven cycles (and bicycles at bicycle signals), but not to autocycles.","p":"Right. Autocycles may not use it."},"es":{"q":"En Indiana, quienes manejan motocicleta pueden pasar un semáforo en rojo que no cambia después de esperar dos minutos. ¿Qué vehículo NO puede usar esta regla?","o":["Una motocicleta","Un ciclomotor (MDC)","Una bicicleta en un semáforo para bicicletas","Un autociclo"],"h1":"Es el vehículo de tres ruedas con volante.","h2":"En Indiana, la regla de los dos minutos para un semáforo en rojo que no cambia se aplica a motocicletas y ciclomotores (y a bicicletas en semáforos para bicicletas), pero no a los autociclos.","p":"Correcto. Los autociclos no pueden usarla."},"ref":{"doc":"IN","page":35}},{"id":"in-162","scope":"IN","cat":"signals","sign":null,"c":0,"en":{"q":"In Indiana, you see a traffic signal that shows white rectangular bars instead of colored circles. Who does it control?","o":["Only buses or transit vehicles in a bus lane","All cars in the right lane","Only bicycles","Only trucks"],"h1":"It is meant for vehicles that run on routes.","h2":"In Indiana, a signal with white rectangular bars controls a bus or transit lane and applies only to bus or transit operators.","p":"Correct. Only buses or transit vehicles."},"es":{"q":"En Indiana, ve un semáforo que muestra barras blancas rectangulares en lugar de círculos de colores. ¿A quién controla?","o":["Solo a autobuses o vehículos de transporte público en un carril para autobuses","A todos los autos del carril derecho","Solo a bicicletas","Solo a camiones"],"h1":"Es para vehículos que siguen rutas.","h2":"En Indiana, un semáforo con barras blancas rectangulares controla un carril de autobuses o transporte público y solo se aplica a esos conductores.","p":"Correcto. Solo autobuses o transporte público."},"ref":{"doc":"IN","page":35}},{"id":"in-163","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, you are pulling out of a driveway or alley onto a street with no sign or signal. What must you do?","o":["Honk and pull out quickly","Stop and yield to other vehicles","Go first, since you were there first","Flash your headlights and go"],"h1":"Traffic already on the street goes first.","h2":"In Indiana, before entering a street from an alley or driveway, you must stop and yield the right of way to other vehicles.","p":"Right. Stop and yield."},"es":{"q":"En Indiana, usted sale de una entrada de garaje o un callejón a una calle sin señal ni semáforo. ¿Qué debe hacer?","o":["Tocar la bocina y salir rápido","Detenerse y ceder el paso a los otros vehículos","Salir primero, porque llegó antes","Hacer cambio de luces y salir"],"h1":"El tráfico que ya está en la calle pasa primero.","h2":"En Indiana, antes de entrar a una calle desde un callejón o una entrada de garaje, debe detenerse y ceder el paso a los otros vehículos.","p":"Correcto. Deténgase y ceda el paso."},"ref":{"doc":"IN","page":35}},{"id":"in-164","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, within what distance of an intersection, railroad crossing, bridge or tunnel is passing not allowed?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is about the length of a few cars lined up, times five.","h2":"In Indiana, you may not pass another vehicle within 100 feet of an intersection, railroad crossing, bridge, viaduct or tunnel.","p":"Correct. Within 100 feet."},"es":{"q":"En Indiana, ¿a qué distancia de una intersección, cruce de tren, puente o túnel no se permite rebasar?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es como la longitud de varios autos en fila, multiplicada por cinco.","h2":"En Indiana, no puede rebasar a otro vehículo a menos de 100 pies de una intersección, cruce de tren, puente, viaducto o túnel.","p":"Correcto. A menos de 100 pies."},"ref":{"doc":"IN","page":38}},{"id":"in-165","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, can you use hand signals instead of your turn signals during the driving skills exam?","o":["Yes, always","Yes, if it is daytime","Only for left turns","No, hand signals are not allowed on the skills exam"],"h1":"Hand signals are a backup when lights fail, not for the test.","h2":"In Indiana, hand signals may be used if your lighted signals fail, but you may not use hand signals on a driving skills exam.","p":"Right. Not on the skills exam."},"es":{"q":"En Indiana, ¿puede usar señales con la mano en lugar de las direccionales durante el examen práctico de manejo?","o":["Sí, siempre","Sí, si es de día","Solo para girar a la izquierda","No, no se permiten señales con la mano en el examen práctico"],"h1":"Las señales con la mano son de respaldo si fallan las luces, no para el examen.","h2":"En Indiana, puede usar señales con la mano si fallan sus direccionales, pero no puede usarlas en el examen práctico de manejo.","p":"Correcto. No en el examen práctico."},"ref":{"doc":"IN","page":39}},{"id":"in-166","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, you missed your exit on an interstate. May you make a U-turn through the median crossover?","o":["No; only emergency and highway maintenance vehicles may, so drive to the next exit","Yes, if no cars are coming","Yes, at night only","Yes, if you use your hazard lights"],"h1":"Those crossovers are for official vehicles.","h2":"In Indiana, only emergency and highway maintenance vehicles may make a U-turn across an interstate median or crossover; other drivers must go to the next exit.","p":"Correct. Go to the next exit."},"es":{"q":"En Indiana, se pasó de su salida en una autopista interestatal. ¿Puede dar vuelta en U por el cruce del camellón central?","o":["No; solo los vehículos de emergencia y de mantenimiento pueden hacerlo, así que siga hasta la próxima salida","Sí, si no vienen autos","Sí, solo de noche","Sí, si usa las luces de emergencia"],"h1":"Esos cruces son para vehículos oficiales.","h2":"En Indiana, solo los vehículos de emergencia y de mantenimiento de carreteras pueden dar vuelta en U por el camellón o cruce de una interestatal; los demás deben seguir hasta la próxima salida.","p":"Correcto. Siga hasta la próxima salida."},"ref":{"doc":"IN","page":46}},{"id":"in-167","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, at a median U-turn (J-turn) intersection, left turns are not allowed at the intersection itself. How do you go left?","o":["Turn left anyway when it is clear","Go straight or turn right, then make a U-turn at the median opening ahead","Back up to the side street","Use the shoulder to turn around"],"h1":"Signs guide you to turn around a little farther on.","h2":"In Indiana, at a median U-turn or J-turn intersection, you go through the intersection and make a U-turn at an upcoming median opening, following the signs.","p":"Right. Make the U-turn at the median opening ahead."},"es":{"q":"En Indiana, en una intersección de vuelta en U por el camellón (J-turn), no se permite girar a la izquierda en la intersección misma. ¿Cómo va a la izquierda?","o":["Gira a la izquierda igual cuando esté libre","Sigue derecho o gira a la derecha y luego da vuelta en U en la abertura del camellón más adelante","Da reversa hasta la calle lateral","Usa el acotamiento para dar la vuelta"],"h1":"Las señales lo guían para dar la vuelta un poco más adelante.","h2":"En Indiana, en una intersección de vuelta en U por el camellón (J-turn), pasa la intersección y da vuelta en U en una abertura del camellón más adelante, siguiendo las señales.","p":"Correcto. Dé la vuelta en U en la abertura más adelante."},"ref":{"doc":"IN","page":39}},{"id":"in-168","scope":"IN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Indiana, two large trucks enter a two-lane roundabout at the same time. Which one must yield?","o":["The truck in the left lane","The heavier truck","The truck in the right lane","Neither; both go side by side"],"h1":"Indiana law gives the inside (left) lane the priority.","h2":"In Indiana, if two large trucks are in a roundabout at the same time, the driver in the right lane must yield to the driver in the left lane.","p":"Correct. The truck in the right lane yields."},"es":{"q":"En Indiana, dos camiones grandes entran al mismo tiempo a una glorieta de dos carriles. ¿Cuál debe ceder el paso?","o":["El camión del carril izquierdo","El camión más pesado","El camión del carril derecho","Ninguno; los dos van lado a lado"],"h1":"La ley de Indiana da prioridad al carril interior (izquierdo).","h2":"En Indiana, si dos camiones grandes están en una glorieta al mismo tiempo, el conductor del carril derecho debe ceder el paso al del carril izquierdo.","p":"Correcto. Cede el camión del carril derecho."},"ref":{"doc":"IN","page":40}},{"id":"in-169","scope":"IN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Indiana, how is a traffic circle different from a roundabout?","o":["A traffic circle is always smaller","A traffic circle never has crosswalks","A traffic circle is only for trucks","A traffic circle may have traffic in both directions and stop signs at the entries"],"h1":"A roundabout always runs one way with yield signs.","h2":"In Indiana, a traffic circle may have both clockwise and counterclockwise traffic, and its entries may be controlled by stop signs instead of yield signs.","p":"Right. Traffic circles can have two directions and stop signs."},"es":{"q":"En Indiana, ¿en qué se diferencia un círculo de tráfico (traffic circle) de una glorieta (roundabout)?","o":["El círculo de tráfico siempre es más pequeño","El círculo de tráfico nunca tiene cruces peatonales","El círculo de tráfico es solo para camiones","El círculo de tráfico puede tener tráfico en ambos sentidos y señales de alto en las entradas"],"h1":"Una glorieta siempre va en un solo sentido con señales de ceda el paso.","h2":"En Indiana, un círculo de tráfico puede tener tráfico en el sentido del reloj y en contra, y sus entradas pueden tener señales de alto en lugar de ceda el paso.","p":"Correcto. Puede tener dos sentidos y señales de alto."},"ref":{"doc":"IN","page":40}},{"id":"in-170","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, what is the top speed for a car on a rural interstate when no other limit is posted?","o":["70 mph","65 mph","60 mph","75 mph"],"h1":"It is the highest limit for cars in the handbook.","h2":"In Indiana, passenger vehicles on a rural interstate may not exceed 70 mph or the posted limit.","p":"Correct. 70 mph."},"es":{"q":"En Indiana, ¿cuál es la velocidad máxima para un auto en una interestatal rural cuando no hay otro límite indicado?","o":["70 mph","65 mph","60 mph","75 mph"],"h1":"Es el límite más alto para autos en el manual.","h2":"En Indiana, los vehículos de pasajeros en una interestatal rural no pueden pasar de 70 mph o del límite indicado.","p":"Correcto. 70 mph."},"ref":{"doc":"IN","page":40}},{"id":"in-171","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, what is the top speed on a rural interstate for a truck with a declared gross weight over 26,000 pounds?","o":["55 mph","65 mph","70 mph","60 mph"],"h1":"It is 5 mph lower than the limit for cars.","h2":"In Indiana, trucks over 26,000 pounds may not exceed 65 mph on a rural interstate, unless a lower limit is posted.","p":"Right. 65 mph."},"es":{"q":"En Indiana, ¿cuál es la velocidad máxima en una interestatal rural para un camión con peso bruto declarado de más de 26,000 libras?","o":["55 mph","65 mph","70 mph","60 mph"],"h1":"Es 5 mph menos que el límite para autos.","h2":"En Indiana, los camiones de más de 26,000 libras no pueden pasar de 65 mph en una interestatal rural, salvo que se indique un límite menor.","p":"Correcto. 65 mph."},"ref":{"doc":"IN","page":40}},{"id":"in-172","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, what is the speed limit on an urban interstate when no other limit is posted?","o":["70 mph","65 mph","55 mph","45 mph"],"h1":"Interstates inside large cities have a lower limit than rural ones.","h2":"In Indiana, vehicles on an urban interstate may not exceed 55 mph or the posted limit.","p":"Correct. 55 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en una interestatal urbana cuando no hay otro límite indicado?","o":["70 mph","65 mph","55 mph","45 mph"],"h1":"Las interestatales dentro de ciudades grandes tienen un límite más bajo que las rurales.","h2":"En Indiana, los vehículos en una interestatal urbana no pueden pasar de 55 mph o del límite indicado.","p":"Correcto. 55 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-173","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, what is the usual speed limit in an urban residential area when no other limit is posted?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"It is double the alley limit.","h2":"In Indiana, most urban residential areas have a 30 mph limit unless another limit is posted.","p":"Right. 30 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad usual en una zona residencial urbana cuando no hay otro límite indicado?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Es el doble del límite en callejones.","h2":"En Indiana, la mayoría de las zonas residenciales urbanas tienen un límite de 30 mph, salvo que se indique otro límite.","p":"Correcto. 30 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-174","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, what is the speed limit on a county road when no other limit is posted?","o":["55 mph","45 mph","35 mph","65 mph"],"h1":"It is the same as on a non-divided state highway.","h2":"In Indiana, vehicles on county roads may not exceed 55 mph or the posted limit.","p":"Correct. 55 mph."},"es":{"q":"En Indiana, ¿cuál es el límite de velocidad en un camino del condado cuando no hay otro límite indicado?","o":["55 mph","45 mph","35 mph","65 mph"],"h1":"Es igual que en una carretera estatal sin división.","h2":"En Indiana, los vehículos en caminos del condado no pueden pasar de 55 mph o del límite indicado.","p":"Correcto. 55 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-175","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, when are school zone speed limits commonly in effect?","o":["Only from 8 a.m. to noon","From 7 a.m. to 4:30 p.m., Monday through Friday, or when the beacons flash","All day, every day of the year","Only on weekends"],"h1":"Think of a normal school day.","h2":"In Indiana, school zone limits commonly apply from 7 a.m. to 4:30 p.m., Monday through Friday, or when the school speed beacons are flashing.","p":"Right. 7 a.m. to 4:30 p.m. on school days, or when beacons flash."},"es":{"q":"En Indiana, ¿cuándo se aplican normalmente los límites de velocidad de zona escolar?","o":["Solo de 8 a.m. a mediodía","De 7 a.m. a 4:30 p.m., de lunes a viernes, o cuando las luces parpadean","Todo el día, todos los días del año","Solo los fines de semana"],"h1":"Piense en un día normal de escuela.","h2":"En Indiana, los límites de zona escolar se aplican normalmente de 7 a.m. a 4:30 p.m., de lunes a viernes, o cuando parpadean las luces de velocidad escolar.","p":"Correcto. De 7 a.m. a 4:30 p.m. en días de escuela, o con luces parpadeando."},"ref":{"doc":"IN","page":41}},{"id":"in-176","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, what is the top speed for a school bus on a road that is not an interstate or state highway?","o":["30 mph","55 mph","40 mph","50 mph"],"h1":"It is lower than the usual county road limit.","h2":"In Indiana, a school bus may not go faster than 40 mph on roads other than interstates and state highways, unless a lower limit is posted.","p":"Correct. 40 mph."},"es":{"q":"En Indiana, ¿cuál es la velocidad máxima de un autobús escolar en un camino que no es interestatal ni carretera estatal?","o":["30 mph","55 mph","40 mph","50 mph"],"h1":"Es más baja que el límite usual de los caminos del condado.","h2":"En Indiana, un autobús escolar no puede ir a más de 40 mph en caminos que no son interestatales ni carreteras estatales, salvo que se indique un límite menor.","p":"Correcto. 40 mph."},"ref":{"doc":"IN","page":41}},{"id":"in-177","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, what following distance does the driver's manual give as a good rule behind the vehicle ahead?","o":["Half a second","One car length","Ten seconds","At least two to three seconds"],"h1":"Count the seconds after the car ahead passes a fixed object.","h2":"In Indiana, the driver's manual says to stay at least two to three seconds behind the vehicle ahead.","p":"Right. At least two to three seconds."},"es":{"q":"En Indiana, ¿qué distancia de seguimiento da el manual como buena regla detrás del vehículo de adelante?","o":["Medio segundo","El largo de un auto","Diez segundos","Al menos dos a tres segundos"],"h1":"Cuente los segundos después de que el auto de adelante pasa un objeto fijo.","h2":"En Indiana, el manual del conductor dice que se mantenga al menos dos a tres segundos detrás del vehículo de adelante.","p":"Correcto. Al menos dos a tres segundos."},"ref":{"doc":"IN","page":41}},{"id":"in-178","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, the driver's manual shows how far a car travels in one second. About how far do you go each second at 55 mph?","o":["About 80 feet","About 20 feet","About 40 feet","About 150 feet"],"h1":"It is about four traffic lanes wide.","h2":"In Indiana, the driver's manual shows that at 55 mph a vehicle travels about 80 feet (80.7 feet) every second.","p":"Correct. About 80 feet each second."},"es":{"q":"En Indiana, el manual muestra cuánto avanza un auto en un segundo. ¿Más o menos cuánto avanza cada segundo a 55 mph?","o":["Unos 80 pies","Unos 20 pies","Unos 40 pies","Unos 150 pies"],"h1":"Es como el ancho de cuatro carriles.","h2":"En Indiana, el manual del conductor muestra que a 55 mph un vehículo avanza unos 80 pies (80.7 pies) cada segundo.","p":"Correcto. Unos 80 pies por segundo."},"ref":{"doc":"IN","page":41}},{"id":"in-179","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, when must you have your headlights on?","o":["Only after 10 p.m.","Between sunset and sunrise, and any time you cannot see clearly for 500 feet","Only when it rains","Only on interstates"],"h1":"There is a time rule and a visibility rule.","h2":"In Indiana, headlights must be on between sunset and sunrise and at any other time visibility is less than 500 feet.","p":"Right. Sunset to sunrise, and when visibility is under 500 feet."},"es":{"q":"En Indiana, ¿cuándo debe llevar encendidos los faros?","o":["Solo después de las 10 p.m.","Entre la puesta y la salida del sol, y siempre que no pueda ver claramente a 500 pies","Solo cuando llueve","Solo en las interestatales"],"h1":"Hay una regla de horario y una de visibilidad.","h2":"En Indiana, los faros deben estar encendidos entre la puesta y la salida del sol, y en cualquier otro momento en que la visibilidad sea de menos de 500 pies.","p":"Correcto. De la puesta a la salida del sol, y con visibilidad menor de 500 pies."},"ref":{"doc":"IN","page":44}},{"id":"in-180","scope":"IN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Indiana, a car is coming toward you at night and your high beams are on. Within what distance must you switch to low beams?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is more than the distance for a car you are following.","h2":"In Indiana, you must use low beams when you are within 500 feet of an oncoming vehicle.","p":"Correct. Within 500 feet."},"es":{"q":"En Indiana, de noche viene un auto hacia usted y usted lleva las luces altas. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es más que la distancia para un auto al que sigue.","h2":"En Indiana, debe usar luces bajas cuando está a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. A menos de 500 pies."},"ref":{"doc":"IN","page":44}},{"id":"in-181","scope":"IN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Indiana, the driver's manual compares drowsy driving to drunk driving. Going how long without sleep impairs you about as much as a .08 BAC?","o":["4 hours","8 hours","12 hours","18 hours"],"h1":"It is most of a full day.","h2":"In Indiana, the driver's manual notes that going 18 hours without sleep leaves a driver as impaired as a driver with a .08 BAC, the legal limit.","p":"Right. About 18 hours."},"es":{"q":"En Indiana, el manual compara manejar con sueño con manejar ebrio. ¿Cuánto tiempo sin dormir lo afecta más o menos como un BAC de .08?","o":["4 horas","8 horas","12 horas","18 horas"],"h1":"Es casi un día completo.","h2":"En Indiana, el manual del conductor indica que pasar 18 horas sin dormir deja a un conductor tan afectado como uno con BAC de .08, el límite legal.","p":"Correcto. Unas 18 horas."},"ref":{"doc":"IN","page":45}},{"id":"in-182","scope":"IN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Indiana, a section of interstate has two lanes in your direction. Which lane must trucks use?","o":["The right lane","The left lane","Either lane","The shoulder"],"h1":"Trucks are kept out of the passing lane.","h2":"In Indiana, trucks are restricted to the right lane where an interstate has two lanes in one direction, and to the right two lanes where it has three or more.","p":"Correct. The right lane."},"es":{"q":"En Indiana, un tramo de interestatal tiene dos carriles en su dirección. ¿Qué carril deben usar los camiones?","o":["El carril derecho","El carril izquierdo","Cualquiera de los dos","El acotamiento"],"h1":"Los camiones se mantienen fuera del carril de rebase.","h2":"En Indiana, los camiones deben usar el carril derecho donde la interestatal tiene dos carriles en una dirección, y los dos carriles de la derecha donde tiene tres o más.","p":"Correcto. El carril derecho."},"ref":{"doc":"IN","page":46}},{"id":"in-183","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, when may you stop or park on the shoulder of an interstate?","o":["To check a map","Only in an emergency or when your vehicle is disabled","To take a phone call","To rest for a few minutes"],"h1":"The shoulder is not a rest area.","h2":"In Indiana, you should not stop or park on an interstate shoulder except in an emergency or when your vehicle is disabled.","p":"Right. Only for an emergency or a breakdown."},"es":{"q":"En Indiana, ¿cuándo puede detenerse o estacionarse en el acotamiento de una interestatal?","o":["Para revisar un mapa","Solo en una emergencia o si su vehículo se descompuso","Para contestar una llamada","Para descansar unos minutos"],"h1":"El acotamiento no es un área de descanso.","h2":"En Indiana, no debe detenerse ni estacionarse en el acotamiento de una interestatal, salvo en una emergencia o si su vehículo se descompuso.","p":"Correcto. Solo por emergencia o avería."},"ref":{"doc":"IN","page":46}},{"id":"in-184","scope":"IN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Indiana, school buses and vehicles carrying passengers for hire must always stop at railroad crossings. How far from the nearest rail must they stop?","o":["5 to 10 feet","50 to 100 feet","15 to 50 feet","Right at the gate, any distance"],"h1":"Close enough to see and listen, but not too close.","h2":"In Indiana, vehicles required to stop at railroad crossings, such as school buses, must stop no closer than 15 feet and no farther than 50 feet from the nearest rail.","p":"Correct. Between 15 and 50 feet."},"es":{"q":"En Indiana, los autobuses escolares y los vehículos que llevan pasajeros por pago siempre deben detenerse en los cruces de tren. ¿A qué distancia del riel más cercano deben detenerse?","o":["De 5 a 10 pies","De 50 a 100 pies","De 15 a 50 pies","Junto a la barrera, a cualquier distancia"],"h1":"Lo bastante cerca para ver y oír, pero no demasiado.","h2":"En Indiana, los vehículos que deben detenerse en los cruces de tren, como los autobuses escolares, deben hacerlo a no menos de 15 pies ni más de 50 pies del riel más cercano.","p":"Correcto. Entre 15 y 50 pies."},"ref":{"doc":"IN","page":48}},{"id":"in-185","scope":"IN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Indiana, the railroad crossing lights start to flash and the gate begins to come down while you are on the tracks. About how much time do you have to get clear?","o":["About 2 minutes","About 5 seconds","About 1 minute","About 20 seconds"],"h1":"It is less than half a minute.","h2":"In Indiana, the driver's manual says you have about 20 seconds to get off the crossing once the lights flash and the gate starts to lower.","p":"Right. About 20 seconds."},"es":{"q":"En Indiana, las luces del cruce de tren empiezan a parpadear y la barrera empieza a bajar mientras usted está sobre las vías. ¿Más o menos cuánto tiempo tiene para salir?","o":["Unos 2 minutos","Unos 5 segundos","Un minuto","Unos 20 segundos"],"h1":"Es menos de medio minuto.","h2":"En Indiana, el manual del conductor dice que tiene unos 20 segundos para salir del cruce cuando las luces parpadean y la barrera empieza a bajar.","p":"Correcto. Unos 20 segundos."},"ref":{"doc":"IN","page":49}},{"id":"in-186","scope":"IN","cat":"signals","sign":null,"c":0,"en":{"q":"In Indiana, some trains run on tracks in the middle of a street. How do the traffic signals warn you that one is coming?","o":["The signals flash red in all directions","All signals turn green","The signals turn off","A white bar lights up"],"h1":"Treat it like any other crossing warning.","h2":"In Indiana, where trains run in the street, the traffic signals flash red in all directions when a train is approaching.","p":"Correct. Flashing red in all directions."},"es":{"q":"En Indiana, algunos trenes van por vías en medio de la calle. ¿Cómo le avisan los semáforos que viene uno?","o":["Los semáforos parpadean en rojo en todas las direcciones","Todos los semáforos se ponen en verde","Los semáforos se apagan","Se enciende una barra blanca"],"h1":"Trátelo como cualquier otra advertencia de cruce.","h2":"En Indiana, donde los trenes van por la calle, los semáforos parpadean en rojo en todas las direcciones cuando se acerca un tren.","p":"Correcto. Rojo intermitente en todas las direcciones."},"ref":{"doc":"IN","page":49}},{"id":"in-187","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, a fully loaded tractor-trailer with hot brakes is going 55 mph. About how far may it need to stop?","o":["About 50 feet","More than 400 feet","About 100 feet","About 200 feet"],"h1":"It is longer than a football field.","h2":"In Indiana, the driver's manual says a fully loaded tractor-trailer with hot brakes may need more than 400 feet to stop from 55 mph, while a car needs about 130 to 140 feet.","p":"Right. More than 400 feet."},"es":{"q":"En Indiana, un tractocamión con carga completa y frenos calientes va a 55 mph. ¿Más o menos qué distancia puede necesitar para detenerse?","o":["Unos 50 pies","Más de 400 pies","Unos 100 pies","Unos 200 pies"],"h1":"Es más largo que un campo de fútbol americano.","h2":"En Indiana, el manual dice que un tractocamión con carga completa y frenos calientes puede necesitar más de 400 pies para detenerse desde 55 mph, mientras que un auto necesita unos 130 a 140 pies.","p":"Correcto. Más de 400 pies."},"ref":{"doc":"IN","page":50}},{"id":"in-188","scope":"IN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Indiana, how far behind a tractor-trailer can its blind spot reach?","o":["About 10 feet","About 50 feet","Up to 200 feet","There is no blind spot behind it"],"h1":"It is much longer than the truck itself.","h2":"In Indiana, a tractor-trailer's blind spots reach up to 20 feet in front of the cab, along both sides, and up to 200 feet behind the truck.","p":"Correct. Up to 200 feet behind."},"es":{"q":"En Indiana, ¿hasta qué distancia detrás de un tractocamión puede llegar su punto ciego?","o":["Unos 10 pies","Unos 50 pies","Hasta 200 pies","No tiene punto ciego atrás"],"h1":"Es mucho más largo que el camión.","h2":"En Indiana, los puntos ciegos de un tractocamión llegan hasta 20 pies delante de la cabina, a ambos lados y hasta 200 pies detrás del camión.","p":"Correcto. Hasta 200 pies atrás."},"ref":{"doc":"IN","page":50}},{"id":"in-189","scope":"IN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Indiana, a driver does not move over or slow down for a stopped police car with flashing red and blue lights. What kind of violation is it?","o":["A warning only","A Class C infraction","A felony","A Class A infraction"],"h1":"It is a higher class than for tow trucks with amber lights.","h2":"In Indiana, failing to move over or slow down for a stopped emergency vehicle is a Class A infraction; for amber-light or hazard-light vehicles it is a Class B infraction.","p":"Right. A Class A infraction."},"es":{"q":"En Indiana, un conductor no se cambia de carril ni baja la velocidad ante una patrulla detenida con luces rojas y azules. ¿Qué tipo de infracción es?","o":["Solo una advertencia","Una infracción Clase C","Un delito grave (felony)","Una infracción Clase A"],"h1":"Es de clase más alta que con grúas con luces ámbar.","h2":"En Indiana, no cambiarse de carril o no bajar la velocidad ante un vehículo de emergencia detenido es una infracción Clase A; con vehículos con luces ámbar o de emergencia (hazard) es Clase B.","p":"Correcto. Una infracción Clase A."},"ref":{"doc":"IN","page":51}},{"id":"in-190","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, a driver passes a school bus with its stop arm out and hurts a child. What can this offense be?","o":["A Level 6 felony","A small fine only","A Class C infraction","Two points only"],"h1":"Hurting someone raises the offense from a misdemeanor to a felony.","h2":"In Indiana, ignoring a school bus stop arm is a Class A misdemeanor, a Level 6 felony if it causes bodily injury, and a Level 5 felony if it causes death.","p":"Correct. A Level 6 felony."},"es":{"q":"En Indiana, un conductor rebasa a un autobús escolar con el brazo de alto extendido y lastima a un niño. ¿Qué puede ser este delito?","o":["Un delito grave Nivel 6 (Level 6 felony)","Solo una multa pequeña","Una infracción Clase C","Solo dos puntos"],"h1":"Lastimar a alguien sube el delito de menor a grave.","h2":"En Indiana, no respetar el brazo de alto de un autobús escolar es un delito menor Clase A, un delito grave Nivel 6 si causa lesiones y un delito grave Nivel 5 si causa una muerte.","p":"Correcto. Un delito grave Nivel 6."},"ref":{"doc":"IN","page":52}},{"id":"in-191","scope":"IN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Indiana, how much room should you give a bicyclist when you pass?","o":["At least 1 foot","At least 3 feet","At least 10 feet","Just enough to get by"],"h1":"It is about the length of a yardstick.","h2":"In Indiana, you may pass a bicyclist only when there is a safe amount of room, at least three feet, and no danger from oncoming traffic.","p":"Right. At least three feet."},"es":{"q":"En Indiana, ¿cuánto espacio debe dejar a un ciclista al rebasarlo?","o":["Al menos 1 pie","Al menos 3 pies","Al menos 10 pies","Solo lo necesario para pasar"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Indiana, puede rebasar a un ciclista solo cuando hay espacio seguro, de al menos tres pies, y no hay peligro por el tráfico que viene de frente.","p":"Correcto. Al menos tres pies."},"ref":{"doc":"IN","page":52}},{"id":"in-192","scope":"IN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Indiana, a street has a bike lane, but a bicyclist is riding in the travel lane. What is true?","o":["The bicyclist must use the bike lane","The bicyclist must ride on the sidewalk","The bicyclist may use either the bike lane or the travel lane","You may honk to move the bicyclist over"],"h1":"Bicyclists have choices under Indiana law.","h2":"In Indiana, a bicyclist is not required to ride in a bike lane and has the right to use either the bike lane or the travel lane.","p":"Correct. The bicyclist may use either one."},"es":{"q":"En Indiana, una calle tiene carril para bicicletas, pero un ciclista va por el carril de circulación. ¿Qué es cierto?","o":["El ciclista debe usar el carril para bicicletas","El ciclista debe ir por la acera","El ciclista puede usar el carril para bicicletas o el carril de circulación","Usted puede tocar la bocina para que se mueva"],"h1":"Los ciclistas pueden elegir según la ley de Indiana.","h2":"En Indiana, un ciclista no está obligado a usar el carril para bicicletas y tiene derecho a usar ese carril o el carril de circulación.","p":"Correcto. Puede usar cualquiera de los dos."},"ref":{"doc":"IN","page":52}},{"id":"in-193","scope":"IN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Indiana, you plan to turn right at a corner with a bike lane next to the curb. What does Indiana say about the bike lane?","o":["Drive in the bike lane for the last block before the turn","Park in the bike lane while you wait","Speed up to pass any bicyclist first","Do not move into the bike lane to get ready for the turn; cross it only to turn"],"h1":"The bike lane is for bicycles, not for lining up a turn.","h2":"In Indiana, you must not move into a bicycle lane in preparation for a turn; you may cross it only when turning or entering or leaving an alley, driveway or private road.","p":"Right. Do not use the bike lane to prepare for the turn."},"es":{"q":"En Indiana, piensa girar a la derecha en una esquina con un carril para bicicletas junto a la acera. ¿Qué dice Indiana sobre ese carril?","o":["Manejar en el carril para bicicletas la última cuadra antes del giro","Estacionarse en el carril para bicicletas mientras espera","Acelerar para pasar primero a cualquier ciclista","No meterse al carril para bicicletas para prepararse a girar; solo cruzarlo al girar"],"h1":"El carril para bicicletas es para bicicletas, no para alinearse para girar.","h2":"En Indiana, no debe meterse a un carril para bicicletas para prepararse a girar; solo puede cruzarlo al girar o al entrar o salir de un callejón, una entrada de garaje o un camino privado.","p":"Correcto. No use el carril para bicicletas para prepararse a girar."},"ref":{"doc":"IN","page":53}},{"id":"in-194","scope":"IN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Indiana, a funeral procession is going through an intersection, and your light turns green. What should you do?","o":["Wait; the procession has the right of way","Go, because your light is green","Honk so they speed up","Cut into a gap in the procession"],"h1":"Official processions are an exception to the signals.","h2":"In Indiana, official processions such as funeral processions have the right of way even when a traffic signal shows otherwise.","p":"Correct. Let the procession pass."},"es":{"q":"En Indiana, un cortejo fúnebre cruza una intersección y su semáforo cambia a verde. ¿Qué debe hacer?","o":["Esperar; el cortejo tiene el derecho de paso","Avanzar, porque tiene luz verde","Tocar la bocina para que se apuren","Meterse en un espacio del cortejo"],"h1":"Los cortejos oficiales son una excepción a los semáforos.","h2":"En Indiana, los cortejos oficiales, como los fúnebres, tienen el derecho de paso aunque el semáforo indique otra cosa.","p":"Correcto. Deje pasar el cortejo."},"ref":{"doc":"IN","page":54}},{"id":"in-195","scope":"IN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Indiana, you start to parallel park. How far should your car be from the parked car beside you as you line up?","o":["Touching its mirror","At least two feet","About six feet","At least ten feet"],"h1":"Close, but with room so you do not scrape it.","h2":"In Indiana, to parallel park you pull up beside the car in front of the space, keeping at least two feet away, with your rear bumpers lined up.","p":"Right. At least two feet."},"es":{"q":"En Indiana, va a estacionarse en paralelo. ¿A qué distancia debe estar su auto del auto estacionado a su lado al alinearse?","o":["Tocando su espejo","Al menos dos pies","Unos seis pies","Al menos diez pies"],"h1":"Cerca, pero con espacio para no rozarlo.","h2":"En Indiana, para estacionarse en paralelo se pone al lado del auto que está delante del espacio, a por lo menos dos pies, con las defensas traseras alineadas.","p":"Correcto. Al menos dos pies."},"ref":{"doc":"IN","page":54}},{"id":"in-196","scope":"IN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Indiana, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","Away from the curb","It does not matter"],"h1":"If the car rolls back, the tires should catch the curb.","h2":"In Indiana, when you park facing uphill next to a curb, turn your wheels away from the curb; facing downhill, turn them toward the curb.","p":"Correct. Away from the curb."},"es":{"q":"En Indiana, se estaciona cuesta arriba junto a la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la acera","Derechas","En dirección contraria a la acera","No importa"],"h1":"Si el auto rueda hacia atrás, las llantas deben quedar contra la acera.","h2":"En Indiana, cuando se estaciona cuesta arriba junto a la acera, gire las ruedas en dirección contraria a la acera; cuesta abajo, gírelas hacia la acera.","p":"Correcto. En dirección contraria a la acera."},"ref":{"doc":"IN","page":54}},{"id":"in-197","scope":"IN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Indiana, where is parking not allowed?","o":["In a marked space in a parking lot","On a residential street with no signs","In your own driveway","Next to a curb painted yellow"],"h1":"Curb color can mark a no-parking area.","h2":"In Indiana, parking is not allowed next to yellow curbs, as well as on sidewalks, in crosswalks, on bridges and beside another parked vehicle.","p":"Right. Not next to a yellow curb."},"es":{"q":"En Indiana, ¿dónde no se permite estacionar?","o":["En un espacio marcado de un estacionamiento","En una calle residencial sin señales","En la entrada de su propia casa","Junto a una acera pintada de amarillo"],"h1":"El color de la acera puede marcar una zona sin estacionamiento.","h2":"En Indiana, no se permite estacionar junto a aceras pintadas de amarillo, ni en las aceras, en los cruces peatonales, en los puentes o al lado de otro vehículo estacionado.","p":"Correcto. No junto a una acera amarilla."},"ref":{"doc":"IN","page":54}},{"id":"in-198","scope":"IN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Indiana, you have a minor crash in a traffic lane. No one is hurt and no hazardous materials are involved. What should you do with your car?","o":["Move it off the road to a place as close to the crash as possible","Leave it exactly where it stopped until police arrive","Drive home and call later","Leave it and walk away"],"h1":"Clear the lane when it is safe and no one is hurt.","h2":"In Indiana, if a crash happens on the traveled part of a highway, the driver must move the vehicle off the road nearby, unless the crash involves hazardous materials, injury, death or someone trapped.","p":"Correct. Move it off the road nearby."},"es":{"q":"En Indiana, usted tiene un choque leve en un carril. Nadie está herido y no hay materiales peligrosos. ¿Qué debe hacer con su auto?","o":["Sacarlo del camino a un lugar lo más cerca posible del choque","Dejarlo justo donde quedó hasta que llegue la policía","Manejar a casa y llamar después","Dejarlo y alejarse caminando"],"h1":"Despeje el carril cuando sea seguro y nadie esté herido.","h2":"En Indiana, si un choque ocurre en la parte de circulación de una carretera, el conductor debe sacar el vehículo del camino cerca del lugar, salvo que haya materiales peligrosos, heridos, muertos o personas atrapadas.","p":"Correcto. Sáquelo del camino cerca del lugar."},"ref":{"doc":"IN","page":58}},{"id":"in-199","scope":"IN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Indiana, the driver's manual gives tips to prevent car theft. How should you leave your front wheels when you park?","o":["Pointed straight ahead","Turned sharply to the right, with the parking brake set","Turned sharply to the left","On the curb"],"h1":"Turned wheels make it harder to tow or drive the car away.","h2":"In Indiana, the driver's manual suggests parking with the front wheels turned sharply to the right and the emergency brake set to help prevent theft.","p":"Right. Turned sharply right, with the brake set."},"es":{"q":"En Indiana, el manual da consejos para evitar el robo de autos. ¿Cómo debe dejar las ruedas delanteras al estacionarse?","o":["Derechas hacia adelante","Giradas bien a la derecha, con el freno de mano puesto","Giradas bien a la izquierda","Sobre la acera"],"h1":"Las ruedas giradas hacen más difícil remolcar o llevarse el auto.","h2":"En Indiana, el manual del conductor sugiere estacionar con las ruedas delanteras giradas bien a la derecha y el freno de emergencia puesto para ayudar a evitar robos.","p":"Correcto. Giradas a la derecha, con el freno puesto."},"ref":{"doc":"IN","page":60}},{"id":"in-200","scope":"IN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Indiana, how many documents proving your Indiana residency must you bring for a new license, permit or ID card?","o":["None","One","Two","Four"],"h1":"You bring one each for identity, lawful status and Social Security, but more for residency.","h2":"In Indiana, a new credential needs one document for identity, one for lawful status, one for your Social Security number, and two documents proving Indiana residency.","p":"Correct. Two residency documents."},"es":{"q":"En Indiana, ¿cuántos documentos que prueben su residencia en Indiana debe llevar para una licencia, permiso o tarjeta de identificación nueva?","o":["Ninguno","Uno","Dos","Cuatro"],"h1":"Lleva uno para identidad, uno para estatus legal y uno para el Seguro Social, pero más para residencia.","h2":"En Indiana, una credencial nueva requiere un documento de identidad, uno de estatus legal, uno con su número de Seguro Social y dos documentos que prueben su residencia en Indiana.","p":"Correcto. Dos documentos de residencia."},"ref":{"doc":"IN","page":68}},{"id":"ks-001","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what is the youngest age to get an instruction permit?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"Kansas lets teens start earlier than most states.","h2":"In Kansas you can get an instruction permit at 14, one of the youngest permit ages in the country.","p":"Right. The Kansas permit starts at 14."},"es":{"q":"En Kansas, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["13 años","14 años","15 años","16 años"],"h1":"Kansas permite empezar más temprano que la mayoría de los estados.","h2":"En Kansas usted puede obtener el permiso de instrucción a los 14 años, una de las edades más bajas del país.","p":"Correcto. El permiso en Kansas empieza a los 14."},"zh":{"q":"在 Kansas，最小几岁可以拿到学习驾照（instruction permit）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"Kansas 让青少年比大多数州更早开始。","h2":"在 Kansas，你 14 岁就可以拿到学习驾照，这是全国最小的学习驾照年龄之一。","p":"对。Kansas 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở Kansas, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Kansas cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang khác.","h2":"Ở Kansas, bạn có thể lấy giấy phép tập lái khi 14 tuổi, là một trong những tuổi nhỏ nhất cả nước.","p":"Đúng. Giấy phép tập lái ở Kansas bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Kansas, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Mas maagang pinapayagan ng Kansas ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa Kansas, puwede kang kumuha ng instruction permit sa edad na 14, isa sa pinakabatang edad para sa permit sa buong bansa.","p":"Tama. Nagsisimula ang permit sa Kansas sa 14."},"ar":{"q":"في Kansas، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"تسمح Kansas للمراهقين بالبدء أبكر من معظم الولايات.","h2":"في Kansas يمكنك الحصول على تصريح التعلّم في عمر 14 سنة، وهو من أصغر أعمار التصريح في البلاد.","p":"صحيح. يبدأ التصريح في Kansas من عمر 14 سنة."},"ref":{"doc":"KS","page":12}},{"id":"ks-002","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how old must the licensed adult supervising a permit driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be old enough to drink legally.","h2":"A Kansas permit driver must be supervised by a licensed adult who is at least 21 years old.","p":"Right. The supervising adult must be 21 or older."},"es":{"q":"En Kansas, ¿qué edad debe tener el adulto con licencia que supervisa a un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kansas, un conductor con permiso debe ir supervisado por un adulto con licencia de por lo menos 21 años.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"zh":{"q":"在 Kansas，陪同持学习驾照的人开车、有驾照的成年人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Kansas，持学习驾照的人必须由一位至少 21 岁、有驾照的成年人陪同。","p":"对。陪同的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Kansas, người lớn có bằng lái đi kèm người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người kèm phải đủ tuổi để uống rượu hợp pháp.","h2":"Ở Kansas, người tập lái phải có một người lớn có bằng lái, ít nhất 21 tuổi, đi kèm.","p":"Đúng. Người lớn đi kèm phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Kansas, ilang taon dapat ang may-lisensyang adult na nagbabantay sa nagmamaneho na may permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak.","h2":"Sa Kansas, ang nagmamaneho na may permit ay dapat bantayan ng may-lisensyang adult na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 o higit pa ang adult na nagbabantay."},"ar":{"q":"في Kansas، كم يجب أن يكون عمر الشخص البالغ صاحب الرخصة الذي يرافق السائق المتعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Kansas يجب أن يرافق السائقَ المتعلّم شخصٌ بالغ يحمل رخصة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون المرافق البالغ في عمر 21 سنة أو أكثر."},"ref":{"doc":"KS","page":12}},{"id":"ks-003","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, who may sit in the front seat while a permit driver is at the wheel?","o":["Only the supervising driver","Any passenger over 12","Any licensed friend","Nobody, the front seat must be empty"],"h1":"The front seat is for the person who is teaching you.","h2":"In Kansas, no one except the supervising driver may sit in the front seat while a permit holder drives.","p":"Right. Only the supervising driver sits up front."},"es":{"q":"En Kansas, ¿quién puede ir en el asiento delantero mientras maneja un conductor con permiso?","o":["Solo el conductor que supervisa","Cualquier pasajero mayor de 12 años","Cualquier amigo con licencia","Nadie, el asiento delantero debe ir vacío"],"h1":"El asiento delantero es para la persona que le está enseñando.","h2":"En Kansas, nadie más que el conductor que supervisa puede ir en el asiento delantero mientras maneja quien tiene permiso.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 Kansas，持学习驾照的人开车时，谁可以坐在前排？","o":["只有陪同的司机","任何 12 岁以上的乘客","任何有驾照的朋友","没有人，前排必须空着"],"h1":"前排是给教你开车的人坐的。","h2":"在 Kansas，持学习驾照的人开车时，除了陪同的司机，任何人都不能坐在前排。","p":"对。只有陪同的司机坐在前排。"},"vi":{"q":"Ở Kansas, ai được ngồi ghế trước khi người có giấy phép tập lái đang lái xe?","o":["Chỉ người lái kèm","Bất kỳ hành khách nào trên 12 tuổi","Bất kỳ người bạn nào có bằng lái","Không ai cả, ghế trước phải để trống"],"h1":"Ghế trước dành cho người đang dạy bạn.","h2":"Ở Kansas, khi người có giấy phép tập lái đang lái, không ai được ngồi ghế trước ngoài người lái kèm.","p":"Đúng. Chỉ người lái kèm ngồi ghế trước."},"tl":{"q":"Sa Kansas, sino ang puwedeng umupo sa harapang upuan habang nagmamaneho ang may permit?","o":["Ang nagbabantay na driver lamang","Sinumang pasaherong higit 12 taong gulang","Sinumang kaibigang may lisensya","Wala, dapat walang tao sa harapang upuan"],"h1":"Ang harapang upuan ay para sa taong nagtuturo sa iyo.","h2":"Sa Kansas, walang ibang puwedeng umupo sa harapang upuan habang nagmamaneho ang may permit, maliban sa nagbabantay na driver.","p":"Tama. Ang nagbabantay na driver lamang ang nasa harap."},"ar":{"q":"في Kansas، من يمكنه الجلوس في المقعد الأمامي أثناء قيادة صاحب تصريح التعلّم؟","o":["السائق المرافق فقط","أي راكب عمره أكثر من 12 سنة","أي صديق يحمل رخصة","لا أحد، يجب أن يبقى المقعد الأمامي فارغًا"],"h1":"المقعد الأمامي للشخص الذي يعلّمك.","h2":"في Kansas لا يجوز لأحد غير السائق المرافق أن يجلس في المقعد الأمامي أثناء قيادة صاحب تصريح التعلّم.","p":"صحيح. السائق المرافق فقط يجلس في الأمام."},"ref":{"doc":"KS","page":12}},{"id":"ks-004","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how long must you hold an instruction permit before you can get a restricted license?","o":["10 days","6 months","One year","Two years"],"h1":"It is a full trip around the calendar.","h2":"In Kansas you must hold your instruction permit for at least one year before you can apply for a restricted license.","p":"Right. Kansas requires a full year on the permit."},"es":{"q":"En Kansas, ¿cuánto tiempo debe tener el permiso de instrucción antes de obtener una licencia restringida?","o":["10 días","6 meses","Un año","Dos años"],"h1":"Es una vuelta completa al calendario.","h2":"En Kansas usted debe tener el permiso de instrucción por lo menos un año antes de solicitar una licencia restringida.","p":"Correcto. Kansas exige un año completo con permiso."},"zh":{"q":"在 Kansas，你必须持有学习驾照多久，才能拿到限制驾照（restricted license）？","o":["10 天","6 个月","一年","两年"],"h1":"是日历上完整的一圈。","h2":"在 Kansas，你必须持有学习驾照至少一年，才能申请限制驾照。","p":"对。Kansas 要求持有学习驾照满一年。"},"vi":{"q":"Ở Kansas, bạn phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái hạn chế (restricted license)?","o":["10 ngày","6 tháng","Một năm","Hai năm"],"h1":"Đó là trọn một vòng lịch.","h2":"Ở Kansas, bạn phải giữ giấy phép tập lái ít nhất một năm trước khi xin bằng lái hạn chế.","p":"Đúng. Kansas yêu cầu giữ giấy phép tập lái trọn một năm."},"tl":{"q":"Sa Kansas, gaano katagal mo dapat hawak ang instruction permit bago ka makakuha ng restricted license?","o":["10 araw","6 na buwan","Isang taon","Dalawang taon"],"h1":"Isang buong ikot ito ng kalendaryo.","h2":"Sa Kansas, dapat hawak mo ang instruction permit nang hindi bababa sa isang taon bago ka makapag-apply ng restricted license.","p":"Tama. Isang buong taon sa permit ang hinihingi ng Kansas."},"ar":{"q":"في Kansas، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على الرخصة المقيّدة (restricted license)؟","o":["10 أيام","6 أشهر","سنة واحدة","سنتان"],"h1":"إنها دورة كاملة من التقويم.","h2":"في Kansas يجب أن تحمل تصريح التعلّم سنة واحدة على الأقل قبل أن تتقدّم بطلب الرخصة المقيّدة.","p":"صحيح. تطلب Kansas سنة كاملة على التصريح."},"ref":{"doc":"KS","page":12}},{"id":"ks-005","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many hours of adult-supervised driving does a 15-year-old need before getting a restricted license?","o":["10 hours","25 hours","50 hours","100 hours"],"h1":"It is half of the full amount needed later.","h2":"A 15-year-old in Kansas needs at least 25 hours of adult-supervised driving before getting a restricted license.","p":"Right. At 15, the first step is 25 hours."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado por un adulto necesita una persona de 15 años antes de obtener la licencia restringida?","o":["10 horas","25 horas","50 horas","100 horas"],"h1":"Es la mitad del total que se pide después.","h2":"En Kansas, una persona de 15 años necesita por lo menos 25 horas de manejo supervisado por un adulto antes de obtener la licencia restringida.","p":"Correcto. A los 15, el primer paso son 25 horas."},"zh":{"q":"在 Kansas，15 岁的人拿限制驾照前，需要多少小时有成年人陪同的驾驶？","o":["10 小时","25 小时","50 小时","100 小时"],"h1":"是以后需要的全部时间的一半。","h2":"在 Kansas，15 岁的人拿限制驾照前，需要至少 25 小时有成年人陪同的驾驶。","p":"对。15 岁时，第一步是 25 小时。"},"vi":{"q":"Ở Kansas, người 15 tuổi cần bao nhiêu giờ lái xe có người lớn đi kèm trước khi lấy bằng lái hạn chế?","o":["10 giờ","25 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa số giờ cần sau này.","h2":"Ở Kansas, người 15 tuổi cần ít nhất 25 giờ lái xe có người lớn đi kèm trước khi lấy bằng lái hạn chế.","p":"Đúng. Ở tuổi 15, bước đầu là 25 giờ."},"tl":{"q":"Sa Kansas, ilang oras ng pagmamaneho na may bantay na adult ang kailangan ng 15 taong gulang bago makakuha ng restricted license?","o":["10 oras","25 oras","50 oras","100 oras"],"h1":"Kalahati ito ng buong bilang na kailangan sa susunod.","h2":"Sa Kansas, ang 15 taong gulang ay kailangan ng hindi bababa sa 25 oras ng pagmamaneho na may bantay na adult bago makakuha ng restricted license.","p":"Tama. Sa edad na 15, 25 oras ang unang hakbang."},"ar":{"q":"في Kansas، كم ساعة من القيادة بمرافقة شخص بالغ يحتاجها من عمره 15 سنة قبل الحصول على الرخصة المقيّدة؟","o":["10 ساعات","25 ساعة","50 ساعة","100 ساعة"],"h1":"إنها نصف العدد الكامل المطلوب لاحقًا.","h2":"في Kansas يحتاج من عمره 15 سنة إلى 25 ساعة على الأقل من القيادة بمرافقة شخص بالغ قبل الحصول على الرخصة المقيّدة.","p":"صحيح. في عمر 15، الخطوة الأولى هي 25 ساعة."},"ref":{"doc":"KS","page":12}},{"id":"ks-006","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how many supervised driving hours does a teen need in total, and how many at night?","o":["25 hours, 5 at night","40 hours, 8 at night","50 hours, 10 at night","60 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Kansas teen needs 50 hours of adult-supervised driving in total, and at least 10 of those hours must be at night.","p":"Right. Fifty hours, with ten at night."},"es":{"q":"En Kansas, ¿cuántas horas de manejo supervisado necesita un adolescente en total, y cuántas de noche?","o":["25 horas, 5 de noche","40 horas, 8 de noche","50 horas, 10 de noche","60 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Kansas, un adolescente necesita 50 horas de manejo supervisado en total, y por lo menos 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, con diez de noche."},"zh":{"q":"在 Kansas，青少年总共需要多少小时有人陪同的驾驶，其中多少小时在夜间？","o":["25 小时，其中 5 小时在夜间","40 小时，其中 8 小时在夜间","50 小时，其中 10 小时在夜间","60 小时，其中 20 小时在夜间"],"h1":"夜间时间是总时间的五分之一。","h2":"Kansas 的青少年总共需要 50 小时有成年人陪同的驾驶，其中至少 10 小时必须在夜间。","p":"对。五十个小时，其中十个小时在夜间。"},"vi":{"q":"Ở Kansas, thanh thiếu niên cần tổng cộng bao nhiêu giờ lái xe có người kèm, và bao nhiêu giờ vào ban đêm?","o":["25 giờ, 5 giờ ban đêm","40 giờ, 8 giờ ban đêm","50 giờ, 10 giờ ban đêm","60 giờ, 20 giờ ban đêm"],"h1":"Số giờ ban đêm là một phần năm tổng số giờ.","h2":"Ở Kansas, thanh thiếu niên cần tổng cộng 50 giờ lái xe có người lớn đi kèm, trong đó ít nhất 10 giờ phải vào ban đêm.","p":"Đúng. Năm mươi giờ, mười giờ ban đêm."},"tl":{"q":"Sa Kansas, ilang oras ng pagmamaneho na may bantay ang kailangan ng kabataan sa kabuuan, at ilan dito sa gabi?","o":["25 oras, 5 sa gabi","40 oras, 8 sa gabi","50 oras, 10 sa gabi","60 oras, 20 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Kansas, kailangan ng kabataan ang 50 oras ng pagmamaneho na may bantay na adult sa kabuuan, at hindi bababa sa 10 oras dito ay dapat sa gabi.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Kansas، كم ساعة قيادة بمرافقة يحتاجها المراهق في المجموع، وكم منها في الليل؟","o":["25 ساعة، منها 5 في الليل","40 ساعة، منها 8 في الليل","50 ساعة، منها 10 في الليل","60 ساعة، منها 20 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Kansas يحتاج المراهق إلى 50 ساعة قيادة بمرافقة شخص بالغ في المجموع، ويجب أن تكون 10 ساعات منها على الأقل في الليل.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"KS","page":12}},{"id":"ks-007","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, do hours driven in a driver education course count toward the 50 supervised hours?","o":["Yes, all course time counts, even watching others drive","Only the night hours count","Only if a parent rides along","Yes, time behind the wheel counts if the instructor is 21 or older"],"h1":"Only real driving time with an adult of the right age counts.","h2":"In Kansas, time you spend behind the wheel in driver education counts toward the 50 hours when the instructor is at least 21, but time spent only watching does not count.","p":"Right. Behind-the-wheel time with an instructor 21 or older counts."},"es":{"q":"En Kansas, ¿cuentan las horas manejadas en un curso de educación vial para las 50 horas supervisadas?","o":["Sí, todo el tiempo del curso cuenta, incluso mirar a otros manejar","Solo cuentan las horas de noche","Solo si el padre va en el carro","Sí, el tiempo al volante cuenta si el instructor tiene 21 años o más"],"h1":"Solo cuenta el tiempo real manejando con un adulto de la edad correcta.","h2":"En Kansas, el tiempo que usted pasa al volante en educación vial cuenta para las 50 horas cuando el instructor tiene por lo menos 21 años, pero el tiempo que solo pasa mirando no cuenta.","p":"Correcto. El tiempo al volante con un instructor de 21 años o más sí cuenta."},"zh":{"q":"在 Kansas，驾驶课上开车的时间算在 50 小时有人陪同的驾驶里吗？","o":["算，所有上课时间都算，连看别人开车也算","只有夜间的时间算","只有父母一起坐车时才算","算，只要教练 21 岁或以上，实际开车的时间就算"],"h1":"只有和年龄合格的成年人一起真正开车的时间才算。","h2":"在 Kansas，如果教练至少 21 岁，你在驾驶课上实际开车的时间算在 50 小时里，但只是看别人开车的时间不算。","p":"对。和 21 岁或以上的教练一起实际开车的时间算。"},"vi":{"q":"Ở Kansas, giờ lái xe trong khóa học lái xe (driver education) có được tính vào 50 giờ có người kèm không?","o":["Có, mọi thời gian của khóa học đều được tính, kể cả khi xem người khác lái","Chỉ giờ ban đêm được tính","Chỉ khi có cha mẹ đi cùng","Có, thời gian bạn cầm lái được tính nếu người hướng dẫn từ 21 tuổi trở lên"],"h1":"Chỉ thời gian thật sự lái xe với người lớn đủ tuổi mới được tính.","h2":"Ở Kansas, thời gian bạn cầm lái trong khóa học lái xe được tính vào 50 giờ khi người hướng dẫn ít nhất 21 tuổi, nhưng thời gian chỉ ngồi xem thì không được tính.","p":"Đúng. Thời gian cầm lái với người hướng dẫn từ 21 tuổi trở lên được tính."},"tl":{"q":"Sa Kansas, binibilang ba ang mga oras ng pagmamaneho sa driver education course sa 50 oras na may bantay?","o":["Oo, binibilang ang lahat ng oras sa kurso, pati ang panonood sa ibang nagmamaneho","Ang mga oras sa gabi lang ang binibilang","Kung may kasamang magulang lang","Oo, binibilang ang oras na ikaw ang nagmamaneho kung 21 o higit pa ang instructor"],"h1":"Ang tunay na oras ng pagmamaneho kasama ang adult na tamang edad lang ang binibilang.","h2":"Sa Kansas, ang oras na ikaw ang nagmamaneho sa driver education ay binibilang sa 50 oras kung hindi bababa sa 21 ang instructor, pero hindi binibilang ang oras na nanonood ka lang.","p":"Tama. Binibilang ang oras sa manibela kasama ang instructor na 21 o higit pa."},"ar":{"q":"في Kansas، هل تُحسب ساعات القيادة في دورة تعليم القيادة (driver education) ضمن الخمسين ساعة بمرافقة؟","o":["نعم، يُحسب كل وقت الدورة، حتى مشاهدة الآخرين وهم يقودون","تُحسب ساعات الليل فقط","فقط إذا كان أحد الوالدين في السيارة","نعم، يُحسب وقت قيادتك أنت إذا كان عمر المدرّب 21 سنة أو أكثر"],"h1":"يُحسب فقط وقت القيادة الحقيقي مع شخص بالغ في العمر المناسب.","h2":"في Kansas يُحسب الوقت الذي تقود فيه أنت في دورة تعليم القيادة ضمن الخمسين ساعة إذا كان عمر المدرّب 21 سنة على الأقل، أما وقت المشاهدة فقط فلا يُحسب.","p":"صحيح. يُحسب وقت القيادة مع مدرّب عمره 21 سنة أو أكثر."},"ref":{"doc":"KS","page":null}},{"id":"ks-008","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, what happens if a teen never turns in the 50-hour affidavit?","o":["The license restrictions continue until age 17","The license is canceled","The teen must retake the knowledge test","Nothing changes"],"h1":"The limits stay in place for a while longer.","h2":"If a Kansas teen does not turn in the 50-hour affidavit, the restrictions on the license stay in place until age 17.","p":"Right. Without the affidavit, the limits last until 17."},"es":{"q":"En Kansas, ¿qué pasa si un adolescente nunca entrega la declaración jurada de las 50 horas?","o":["Las restricciones de la licencia siguen hasta los 17 años","Le cancelan la licencia","Debe repetir el examen de conocimientos","No cambia nada"],"h1":"Los límites siguen por más tiempo.","h2":"Si un adolescente en Kansas no entrega la declaración jurada de las 50 horas, las restricciones de su licencia siguen hasta los 17 años.","p":"Correcto. Sin la declaración, los límites duran hasta los 17."},"zh":{"q":"在 Kansas，如果青少年一直没有交 50 小时的宣誓书（affidavit），会怎么样？","o":["驾照的限制一直持续到 17 岁","驾照被取消","青少年必须重考笔试","什么都不变"],"h1":"这些限制会再保留一段时间。","h2":"如果 Kansas 的青少年没有交 50 小时的宣誓书，驾照上的限制会一直保留到 17 岁。","p":"对。没有宣誓书，限制会持续到 17 岁。"},"vi":{"q":"Ở Kansas, điều gì xảy ra nếu thanh thiếu niên không bao giờ nộp bản khai 50 giờ (50-hour affidavit)?","o":["Các hạn chế của bằng lái tiếp tục đến 17 tuổi","Bằng lái bị hủy","Phải thi lại phần lý thuyết","Không có gì thay đổi"],"h1":"Các giới hạn sẽ còn giữ thêm một thời gian.","h2":"Ở Kansas, nếu thanh thiếu niên không nộp bản khai 50 giờ, các hạn chế trên bằng lái sẽ tiếp tục đến 17 tuổi.","p":"Đúng. Không có bản khai, các giới hạn kéo dài đến 17 tuổi."},"tl":{"q":"Sa Kansas, ano ang mangyayari kung hindi kailanman ipapasa ng kabataan ang 50-hour affidavit?","o":["Tuloy ang mga restriksyon ng lisensya hanggang edad 17","Kakanselahin ang lisensya","Dapat ulitin ng kabataan ang knowledge test","Walang magbabago"],"h1":"Mananatili pa ang mga limitasyon nang mas matagal.","h2":"Sa Kansas, kung hindi ipapasa ng kabataan ang 50-hour affidavit, mananatili ang mga restriksyon ng lisensya hanggang edad 17.","p":"Tama. Kung walang affidavit, tatagal ang mga limitasyon hanggang 17."},"ar":{"q":"في Kansas، ماذا يحدث إذا لم يسلّم المراهق إقرار الخمسين ساعة (50-hour affidavit) أبدًا؟","o":["تستمر قيود الرخصة حتى عمر 17 سنة","تُلغى الرخصة","يجب على المراهق إعادة الامتحان النظري","لا يتغيّر شيء"],"h1":"تبقى القيود مدة أطول.","h2":"في Kansas إذا لم يسلّم المراهق إقرار الخمسين ساعة، تبقى القيود على الرخصة حتى عمر 17 سنة.","p":"صحيح. بدون الإقرار تستمر القيود حتى عمر 17."},"ref":{"doc":"KS","page":null}},{"id":"ks-009","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what must a 15-year-old complete, besides the permit year, to get a restricted license?","o":["A first aid course","An approved driver education course","A motorcycle course","Nothing else"],"h1":"It is a class about driving.","h2":"A 15-year-old in Kansas must complete an approved driver education course to get a restricted license.","p":"Right. Driver education is required at 15."},"es":{"q":"En Kansas, ¿qué debe completar una persona de 15 años, además del año con permiso, para obtener la licencia restringida?","o":["Un curso de primeros auxilios","Un curso aprobado de educación vial","Un curso de motocicleta","Nada más"],"h1":"Es una clase sobre manejo.","h2":"En Kansas, una persona de 15 años debe completar un curso aprobado de educación vial para obtener la licencia restringida.","p":"Correcto. A los 15 se exige educación vial."},"zh":{"q":"在 Kansas，15 岁的人除了持有学习驾照一年，还必须完成什么才能拿到限制驾照？","o":["急救课程","经过批准的驾驶课","摩托车课程","不需要别的"],"h1":"是一门关于开车的课。","h2":"在 Kansas，15 岁的人必须完成经过批准的驾驶课，才能拿到限制驾照。","p":"对。15 岁必须上驾驶课。"},"vi":{"q":"Ở Kansas, ngoài năm giữ giấy phép tập lái, người 15 tuổi phải hoàn thành gì để lấy bằng lái hạn chế?","o":["Một khóa sơ cứu","Một khóa học lái xe (driver education) được chấp thuận","Một khóa học xe máy","Không cần gì khác"],"h1":"Đó là một lớp học về lái xe.","h2":"Ở Kansas, người 15 tuổi phải hoàn thành một khóa học lái xe được chấp thuận để lấy bằng lái hạn chế.","p":"Đúng. Ở tuổi 15, phải học khóa lái xe."},"tl":{"q":"Sa Kansas, bukod sa isang taon sa permit, ano pa ang dapat tapusin ng 15 taong gulang para makakuha ng restricted license?","o":["Isang kurso sa first aid","Isang aprubadong driver education course","Isang kurso sa motorsiklo","Wala nang iba"],"h1":"Isa itong klase tungkol sa pagmamaneho.","h2":"Sa Kansas, dapat tapusin ng 15 taong gulang ang isang aprubadong driver education course para makakuha ng restricted license.","p":"Tama. Kailangan ang driver education sa edad na 15."},"ar":{"q":"في Kansas، ماذا يجب أن يُكمل من عمره 15 سنة، إلى جانب سنة التصريح، للحصول على الرخصة المقيّدة؟","o":["دورة إسعافات أولية","دورة معتمدة لتعليم القيادة (driver education)","دورة دراجة نارية","لا شيء آخر"],"h1":"إنها دروس عن القيادة.","h2":"في Kansas يجب على من عمره 15 سنة أن يُكمل دورة معتمدة لتعليم القيادة للحصول على الرخصة المقيّدة.","p":"صحيح. تعليم القيادة مطلوب في عمر 15."},"ref":{"doc":"KS","page":12}},{"id":"ks-010","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, a 15-year-old with a restricted license may drive alone to school how?","o":["Any route, any day","Only on weekends","By the most direct route on school days","Only with a sibling"],"h1":"Think of the shortest way between home and school.","h2":"A 15-year-old in Kansas with a restricted license may drive alone to school on school days, using the most direct route between home and school.","p":"Right. The direct route, on school days."},"es":{"q":"En Kansas, ¿cómo puede manejar sola a la escuela una persona de 15 años con licencia restringida?","o":["Por cualquier ruta, cualquier día","Solo los fines de semana","Por la ruta más directa en días de clase","Solo con un hermano"],"h1":"Piense en el camino más corto entre la casa y la escuela.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar sola a la escuela en días de clase, por la ruta más directa entre la casa y la escuela.","p":"Correcto. La ruta directa, en días de clase."},"zh":{"q":"在 Kansas，持限制驾照的 15 岁青少年可以怎样一个人开车去上学？","o":["任何路线，任何一天","只能在周末","在上学的日子走最直接的路线","只能和兄弟姐妹一起"],"h1":"想一想家和学校之间最短的路。","h2":"在 Kansas，持限制驾照的 15 岁青少年可以在上学的日子一个人开车去上学，走家和学校之间最直接的路线。","p":"对。上学的日子，走最直接的路线。"},"vi":{"q":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe một mình đến trường như thế nào?","o":["Bất kỳ đường nào, bất kỳ ngày nào","Chỉ vào cuối tuần","Đi đường thẳng nhất vào những ngày đi học","Chỉ khi có anh chị em đi cùng"],"h1":"Hãy nghĩ đến đường ngắn nhất giữa nhà và trường.","h2":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe một mình đến trường vào những ngày đi học, theo đường thẳng nhất giữa nhà và trường.","p":"Đúng. Đường thẳng nhất, vào ngày đi học."},"tl":{"q":"Sa Kansas, paano puwedeng magmaneho nang mag-isa papunta sa paaralan ang 15 taong gulang na may restricted license?","o":["Kahit anong ruta, kahit anong araw","Tuwing weekend lang","Sa pinakadiretsong ruta tuwing may pasok","Kung may kasamang kapatid lang"],"h1":"Isipin ang pinakamaikling daan mula bahay papuntang paaralan.","h2":"Sa Kansas, ang 15 taong gulang na may restricted license ay puwedeng magmaneho nang mag-isa papunta sa paaralan tuwing may pasok, sa pinakadiretsong ruta mula bahay papuntang paaralan.","p":"Tama. Ang diretsong ruta, tuwing may pasok."},"ar":{"q":"في Kansas، كيف يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود وحده إلى المدرسة؟","o":["أي طريق، في أي يوم","في عطلة نهاية الأسبوع فقط","بأقصر طريق مباشر في أيام الدراسة","فقط مع أخ أو أخت"],"h1":"فكّر في أقصر طريق بين البيت والمدرسة.","h2":"في Kansas يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود وحده إلى المدرسة في أيام الدراسة، بأقصر طريق مباشر بين البيت والمدرسة.","p":"صحيح. الطريق المباشر، في أيام الدراسة."},"ref":{"doc":"KS","page":13}},{"id":"ks-011","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, may a restricted driver under 16 carry friends who are minors?","o":["Yes, up to three","Yes, one friend","Yes, if the windows are closed","No, only siblings may ride as minor passengers"],"h1":"Brothers and sisters are the exception.","h2":"In Kansas, a restricted driver under 16 may not carry minor passengers who are not brothers or sisters.","p":"Right. Under 16, only sibling minors may ride."},"es":{"q":"En Kansas, ¿puede un conductor con licencia restringida menor de 16 años llevar amigos menores de edad?","o":["Sí, hasta tres","Sí, un amigo","Sí, si las ventanas van cerradas","No, solo hermanos pueden ir como pasajeros menores"],"h1":"Los hermanos son la excepción.","h2":"En Kansas, un conductor con licencia restringida menor de 16 años no puede llevar pasajeros menores de edad que no sean sus hermanos.","p":"Correcto. Antes de los 16, solo hermanos menores."},"zh":{"q":"在 Kansas，16 岁以下、持限制驾照的司机可以载未成年的朋友吗？","o":["可以，最多三个","可以，一个朋友","可以，只要车窗关着","不可以，只有兄弟姐妹可以作为未成年乘客坐车"],"h1":"兄弟姐妹是例外。","h2":"在 Kansas，16 岁以下、持限制驾照的司机不能载不是兄弟姐妹的未成年乘客。","p":"对。16 岁以下，只有未成年的兄弟姐妹可以坐车。"},"vi":{"q":"Ở Kansas, người có bằng lái hạn chế dưới 16 tuổi có được chở bạn bè chưa thành niên không?","o":["Có, tối đa ba người","Có, một người bạn","Có, nếu đóng cửa sổ","Không, chỉ anh chị em ruột được đi cùng làm hành khách chưa thành niên"],"h1":"Anh chị em là ngoại lệ.","h2":"Ở Kansas, người có bằng lái hạn chế dưới 16 tuổi không được chở hành khách chưa thành niên nếu đó không phải là anh chị em.","p":"Đúng. Dưới 16 tuổi, chỉ anh chị em chưa thành niên được đi cùng."},"tl":{"q":"Sa Kansas, puwede bang magsakay ng mga kaibigang menor de edad ang restricted driver na wala pang 16?","o":["Oo, hanggang tatlo","Oo, isang kaibigan","Oo, kung nakasara ang mga bintana","Hindi, mga kapatid lang ang puwedeng isakay na menor de edad"],"h1":"Ang mga kapatid ang eksepsiyon.","h2":"Sa Kansas, ang restricted driver na wala pang 16 ay hindi puwedeng magsakay ng menor de edad na pasahero na hindi niya kapatid.","p":"Tama. Kung wala pang 16, mga kapatid na menor de edad lang ang puwedeng isakay."},"ar":{"q":"في Kansas، هل يجوز لسائق برخصة مقيّدة عمره أقل من 16 سنة أن يركب معه أصدقاء قاصرين؟","o":["نعم، حتى ثلاثة","نعم، صديق واحد","نعم، إذا كانت النوافذ مغلقة","لا، فقط الإخوة والأخوات يمكنهم الركوب كركاب قاصرين"],"h1":"الإخوة والأخوات هم الاستثناء.","h2":"في Kansas لا يجوز لسائق برخصة مقيّدة عمره أقل من 16 سنة أن يُركب معه ركابًا قاصرين ليسوا إخوته أو أخواته.","p":"صحيح. تحت 16 سنة، فقط الإخوة القاصرون يمكنهم الركوب."},"ref":{"doc":"KS","page":13}},{"id":"ks-012","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, a 16-year-old with a restricted license may drive alone during which hours?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","Midnight to 5 a.m.","Any time at all"],"h1":"The window closes early in the evening.","h2":"A 16-year-old in Kansas with a restricted license may drive alone from 5 a.m. to 9 p.m., plus trips for work, school activities and religious services.","p":"Right. Five in the morning to nine at night."},"es":{"q":"En Kansas, ¿en qué horario puede manejar solo un joven de 16 años con licencia restringida?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De medianoche a 5 a.m.","A cualquier hora"],"h1":"El horario termina temprano en la noche.","h2":"En Kansas, un joven de 16 años con licencia restringida puede manejar solo de 5 a.m. a 9 p.m., además de viajes de trabajo, actividades escolares y servicios religiosos.","p":"Correcto. De cinco de la mañana a nueve de la noche."},"zh":{"q":"在 Kansas，持限制驾照的 16 岁青少年可以在什么时间一个人开车？","o":["早上 5 点到晚上 9 点","早上 6 点到晚上 10 点","午夜到早上 5 点","任何时间都可以"],"h1":"这个时间段在晚上很早就结束了。","h2":"在 Kansas，持限制驾照的 16 岁青少年可以在早上 5 点到晚上 9 点一个人开车，另外也可以为上班、学校活动和宗教活动开车。","p":"对。早上五点到晚上九点。"},"vi":{"q":"Ở Kansas, người 16 tuổi có bằng lái hạn chế được lái xe một mình trong khoảng giờ nào?","o":["5 giờ sáng đến 9 giờ tối","6 giờ sáng đến 10 giờ tối","Nửa đêm đến 5 giờ sáng","Bất cứ lúc nào"],"h1":"Khung giờ kết thúc sớm vào buổi tối.","h2":"Ở Kansas, người 16 tuổi có bằng lái hạn chế được lái xe một mình từ 5 giờ sáng đến 9 giờ tối, cộng thêm các chuyến đi làm, đi sinh hoạt ở trường và đi lễ tôn giáo.","p":"Đúng. Từ năm giờ sáng đến chín giờ tối."},"tl":{"q":"Sa Kansas, anong oras puwedeng magmaneho nang mag-isa ang 16 taong gulang na may restricted license?","o":["5 a.m. hanggang 9 p.m.","6 a.m. hanggang 10 p.m.","Hatinggabi hanggang 5 a.m.","Kahit anong oras"],"h1":"Maaga sa gabi nagsasara ang oras.","h2":"Sa Kansas, ang 16 taong gulang na may restricted license ay puwedeng magmaneho nang mag-isa mula 5 a.m. hanggang 9 p.m., pati mga biyahe para sa trabaho, gawain sa paaralan at pagsamba.","p":"Tama. Mula alas-singko ng umaga hanggang alas-nuwebe ng gabi."},"ar":{"q":"في Kansas، في أي ساعات يمكن لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يقود وحده؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى 10 مساءً","من منتصف الليل إلى 5 صباحًا","في أي وقت"],"h1":"تنتهي الفترة مبكرًا في المساء.","h2":"في Kansas يمكن لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يقود وحده من 5 صباحًا إلى 9 مساءً، بالإضافة إلى الرحلات إلى العمل وأنشطة المدرسة والشعائر الدينية.","p":"صحيح. من الخامسة صباحًا إلى التاسعة مساءً."},"ref":{"doc":"KS","page":13}},{"id":"ks-013","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many passengers under 18 who are not family may a newly restricted 16-year-old carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"For the first six months, a 16-year-old in Kansas with a restricted license may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Kansas, ¿cuántos pasajeros menores de 18 años que no son familia puede llevar un joven de 16 años con licencia restringida reciente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un joven de 16 años en Kansas con licencia restringida puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"zh":{"q":"在 Kansas，刚拿到限制驾照的 16 岁青少年可以载几个不是家人、18 岁以下的乘客？","o":["一个都不可以","一个","两个","三个"],"h1":"是比零大的最小的数。","h2":"在头六个月里，Kansas 持限制驾照的 16 岁青少年最多只能载一个不是直系亲属、18 岁以下的乘客。","p":"对。只能载一个不是家人、18 岁以下的乘客。"},"vi":{"q":"Ở Kansas, người 16 tuổi mới có bằng lái hạn chế được chở bao nhiêu hành khách dưới 18 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Kansas, trong sáu tháng đầu, người 16 tuổi có bằng lái hạn chế được chở không quá một hành khách dưới 18 tuổi không phải người trong gia đình gần.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Kansas, ilang pasaherong wala pang 18 na hindi kapamilya ang puwedeng isakay ng bagong restricted na 16 taong gulang?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Kansas, sa unang anim na buwan, ang 16 taong gulang na may restricted license ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 18 na hindi malapit na kapamilya.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi kapamilya."},"ar":{"q":"في Kansas، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن يُركب معه سائق عمره 16 سنة حصل حديثًا على رخصة مقيّدة؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"إنه أصغر عدد أكبر من الصفر.","h2":"في Kansas، خلال الأشهر الستة الأولى، لا يجوز لمن عمره 16 سنة ويحمل رخصة مقيّدة أن يُركب معه أكثر من راكب واحد عمره أقل من 18 سنة وليس من أفراد العائلة المباشرة.","p":"صحيح. راكب واحد فقط تحت 18 سنة من خارج العائلة."},"ref":{"doc":"KS","page":12}},{"id":"ks-014","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, when may a 15-year-old restricted driver drive at any time of day?","o":["On holidays","When another teen with a permit rides along","When a licensed adult sits in the front seat beside them","Never"],"h1":"An experienced adult must be right beside you.","h2":"A 15-year-old in Kansas with a restricted license may drive at any time when a licensed adult sits in the front seat beside them.","p":"Right. Any time, with a licensed adult beside you."},"es":{"q":"En Kansas, ¿cuándo puede manejar a cualquier hora una persona de 15 años con licencia restringida?","o":["En días festivos","Cuando va con otro joven que tiene permiso","Cuando un adulto con licencia va a su lado en el asiento delantero","Nunca"],"h1":"Un adulto con experiencia debe ir a su lado.","h2":"En Kansas, una persona de 15 años con licencia restringida puede manejar a cualquier hora si un adulto con licencia va a su lado en el asiento delantero.","p":"Correcto. A cualquier hora, con un adulto con licencia a su lado."},"zh":{"q":"在 Kansas，持限制驾照的 15 岁司机什么时候可以在一天中任何时间开车？","o":["在节假日","当另一个持学习驾照的青少年一起坐车时","当一位有驾照的成年人坐在旁边的前排座位时","任何时候都不可以"],"h1":"必须有一位有经验的成年人就在你旁边。","h2":"在 Kansas，持限制驾照的 15 岁青少年，在一位有驾照的成年人坐在旁边的前排座位时，可以在任何时间开车。","p":"对。有一位有驾照的成年人在你旁边时，任何时间都可以。"},"vi":{"q":"Ở Kansas, khi nào người 15 tuổi có bằng lái hạn chế được lái xe vào bất kỳ giờ nào trong ngày?","o":["Vào ngày lễ","Khi có một thanh thiếu niên khác có giấy phép tập lái đi cùng","Khi có một người lớn có bằng lái ngồi ghế trước bên cạnh","Không bao giờ"],"h1":"Một người lớn có kinh nghiệm phải ngồi ngay bên cạnh bạn.","h2":"Ở Kansas, người 15 tuổi có bằng lái hạn chế được lái xe bất cứ lúc nào khi có một người lớn có bằng lái ngồi ghế trước bên cạnh.","p":"Đúng. Bất cứ lúc nào, nếu có người lớn có bằng lái ngồi bên cạnh."},"tl":{"q":"Sa Kansas, kailan puwedeng magmaneho kahit anong oras ang 15 taong gulang na restricted driver?","o":["Tuwing holiday","Kung may kasamang ibang kabataan na may permit","Kung may may-lisensyang adult na nakaupo sa harapang upuan sa tabi niya","Hindi kailanman"],"h1":"Dapat may adult na may karanasan sa mismong tabi mo.","h2":"Sa Kansas, ang 15 taong gulang na may restricted license ay puwedeng magmaneho kahit anong oras kung may may-lisensyang adult na nakaupo sa harapang upuan sa tabi niya.","p":"Tama. Kahit anong oras, basta may may-lisensyang adult sa tabi mo."},"ar":{"q":"في Kansas، متى يمكن لسائق عمره 15 سنة ويحمل رخصة مقيّدة أن يقود في أي وقت من اليوم؟","o":["في أيام العطل","عندما يركب معه مراهق آخر يحمل تصريح تعلّم","عندما يجلس بجانبه في المقعد الأمامي شخص بالغ يحمل رخصة","أبدًا"],"h1":"يجب أن يكون شخص بالغ صاحب خبرة بجانبك مباشرة.","h2":"في Kansas يمكن لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود في أي وقت عندما يجلس بجانبه في المقعد الأمامي شخص بالغ يحمل رخصة.","p":"صحيح. في أي وقت، مع شخص بالغ يحمل رخصة بجانبك."},"ref":{"doc":"KS","page":13}},{"id":"ks-015","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, when may a teen with a permit or restricted license use a phone while driving?","o":["At red lights","For short texts","With a hands-free device","Only to report illegal activity or call for emergency help"],"h1":"Only a true emergency or a crime is an exception.","h2":"A Kansas teen with a permit or restricted license may not use a wireless device while driving, except to report illegal activity or call for medical or emergency help.","p":"Right. Only for emergencies or to report a crime."},"es":{"q":"En Kansas, ¿cuándo puede usar el teléfono mientras maneja un adolescente con permiso o licencia restringida?","o":["En los semáforos en rojo","Para mensajes cortos","Con un dispositivo manos libres","Solo para reportar un delito o pedir ayuda de emergencia"],"h1":"Solo una emergencia real o un delito son la excepción.","h2":"En Kansas, un adolescente con permiso o licencia restringida no puede usar un dispositivo inalámbrico mientras maneja, salvo para reportar un delito o pedir ayuda médica o de emergencia.","p":"Correcto. Solo para emergencias o para reportar un delito."},"zh":{"q":"在 Kansas，持学习驾照或限制驾照的青少年开车时什么时候可以用手机？","o":["在红灯时","发短的短信","用免提设备","只能报告违法活动或打电话求救"],"h1":"只有真正的紧急情况或犯罪才是例外。","h2":"在 Kansas，持学习驾照或限制驾照的青少年开车时不能使用无线设备，除非是报告违法活动，或打电话寻求医疗或紧急帮助。","p":"对。只能在紧急情况下或报告犯罪时用。"},"vi":{"q":"Ở Kansas, khi nào thanh thiếu niên có giấy phép tập lái hoặc bằng lái hạn chế được dùng điện thoại khi lái xe?","o":["Khi dừng đèn đỏ","Để nhắn tin ngắn","Khi dùng thiết bị rảnh tay","Chỉ để báo hành vi phạm pháp hoặc gọi cấp cứu"],"h1":"Chỉ trường hợp khẩn cấp thật sự hoặc tội phạm mới là ngoại lệ.","h2":"Ở Kansas, thanh thiếu niên có giấy phép tập lái hoặc bằng lái hạn chế không được dùng thiết bị không dây khi lái xe, trừ khi để báo hành vi phạm pháp hoặc gọi trợ giúp y tế hay cấp cứu.","p":"Đúng. Chỉ khi khẩn cấp hoặc để báo tội phạm."},"tl":{"q":"Sa Kansas, kailan puwedeng gumamit ng telepono habang nagmamaneho ang kabataan na may permit o restricted license?","o":["Sa red light","Para sa maiikling text","Gamit ang hands-free na device","Para lang mag-report ng ilegal na gawain o tumawag para sa emergency"],"h1":"Tunay na emergency o krimen lang ang eksepsiyon.","h2":"Sa Kansas, ang kabataan na may permit o restricted license ay hindi puwedeng gumamit ng wireless device habang nagmamaneho, maliban kung magre-report ng ilegal na gawain o tatawag para sa medikal o emergency na tulong.","p":"Tama. Para lang sa emergency o pag-report ng krimen."},"ar":{"q":"في Kansas، متى يمكن لمراهق يحمل تصريح تعلّم أو رخصة مقيّدة أن يستخدم الهاتف أثناء القيادة؟","o":["عند الإشارة الحمراء","لرسائل قصيرة","مع جهاز بدون استخدام اليدين (hands-free)","فقط للإبلاغ عن نشاط غير قانوني أو لطلب مساعدة طارئة"],"h1":"الاستثناء فقط لحالة طارئة حقيقية أو جريمة.","h2":"في Kansas لا يجوز لمراهق يحمل تصريح تعلّم أو رخصة مقيّدة أن يستخدم جهازًا لاسلكيًا أثناء القيادة، إلا للإبلاغ عن نشاط غير قانوني أو لطلب مساعدة طبية أو طارئة.","p":"صحيح. فقط في حالات الطوارئ أو للإبلاغ عن جريمة."},"ref":{"doc":"KS","page":12}},{"id":"ks-016","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, a driver under 21 breaks the law at what blood alcohol level?","o":[".02 or higher",".05 or higher",".08 or higher",".10 or higher"],"h1":"It is a very small amount, far below the adult limit.","h2":"In Kansas it is illegal for a driver under 21 to drive with a blood or breath alcohol level of .02 or higher.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Kansas, ¿con qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":[".02 o más",".05 o más",".08 o más",".10 o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite para adultos.","h2":"En Kansas es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre o el aliento de .02 o más.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Kansas，21 岁以下的司机血液酒精浓度达到多少就违法？","o":[".02 或更高",".05 或更高",".08 或更高",".10 或更高"],"h1":"这是很少的量，远低于成年人的上限。","h2":"在 Kansas，21 岁以下的司机血液或呼气酒精浓度达到 .02 或更高时开车是违法的。","p":"对。21 岁以下，上限是 .02。"},"vi":{"q":"Ở Kansas, người lái xe dưới 21 tuổi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":[".02 trở lên",".05 trở lên",".08 trở lên",".10 trở lên"],"h1":"Đó là một lượng rất nhỏ, thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Kansas, người dưới 21 tuổi lái xe với nồng độ cồn trong máu hoặc hơi thở từ .02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Kansas, sa anong blood alcohol level lumalabag sa batas ang driver na wala pang 21?","o":[".02 o higit pa",".05 o higit pa",".08 o higit pa",".10 o higit pa"],"h1":"Napakaliit na dami ito, mas mababa kaysa sa limitasyon ng adult.","h2":"Sa Kansas, bawal sa driver na wala pang 21 ang magmaneho na may alcohol level sa dugo o hininga na .02 o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay .02."},"ar":{"q":"في Kansas، عند أي نسبة كحول في الدم يخالف السائق الذي عمره أقل من 21 سنة القانون؟","o":[".02 أو أكثر",".05 أو أكثر",".08 أو أكثر",".10 أو أكثر"],"h1":"إنها كمية صغيرة جدًا، أقل بكثير من حدّ البالغين.","h2":"في Kansas يُمنع على السائق الذي عمره أقل من 21 سنة أن يقود ونسبة الكحول في دمه أو نَفَسه .02 أو أكثر.","p":"صحيح. تحت 21 سنة، الحدّ هو .02."},"ref":{"doc":"KS","page":23}},{"id":"ks-017","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, how long is the license suspension for a first time a driver under 21 tests between .02 and .08?","o":["7 days","14 days","30 days","One year"],"h1":"It is about one month.","h2":"In Kansas, a first offense by a driver under 21 with a result from .02 up to .08 brings a 30-day suspension.","p":"Right. The first suspension lasts 30 days."},"es":{"q":"En Kansas, ¿cuánto dura la suspensión la primera vez que un conductor menor de 21 años da entre .02 y .08?","o":["7 días","14 días","30 días","Un año"],"h1":"Es más o menos un mes.","h2":"En Kansas, la primera vez que un conductor menor de 21 años da entre .02 y .08, se le suspende la licencia por 30 días.","p":"Correcto. La primera suspensión dura 30 días."},"zh":{"q":"在 Kansas，21 岁以下的司机第一次被测出酒精浓度在 .02 到 .08 之间，驾照会被暂停多久？","o":["7 天","14 天","30 天","一年"],"h1":"大约是一个月。","h2":"在 Kansas，21 岁以下的司机第一次被测出酒精浓度在 .02 到 .08 以下，驾照会被暂停 30 天。","p":"对。第一次暂停 30 天。"},"vi":{"q":"Ở Kansas, lần đầu người lái xe dưới 21 tuổi có kết quả từ .02 đến .08 thì bị treo bằng lái bao lâu?","o":["7 ngày","14 ngày","30 ngày","Một năm"],"h1":"Khoảng một tháng.","h2":"Ở Kansas, lần vi phạm đầu tiên của người lái dưới 21 tuổi với kết quả từ .02 đến dưới .08 sẽ bị treo bằng lái 30 ngày.","p":"Đúng. Lần treo bằng đầu tiên kéo dài 30 ngày."},"tl":{"q":"Sa Kansas, gaano katagal ang suspensyon ng lisensya sa unang beses na ang driver na wala pang 21 ay may resultang mula .02 hanggang .08?","o":["7 araw","14 na araw","30 araw","Isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Kansas, ang unang paglabag ng driver na wala pang 21 na may resultang mula .02 hanggang .08 ay may 30 araw na suspensyon.","p":"Tama. 30 araw ang unang suspensyon."},"ar":{"q":"في Kansas، كم مدة إيقاف الرخصة في المرة الأولى التي تكون فيها نتيجة سائق عمره أقل من 21 سنة بين .02 و .08؟","o":["7 أيام","14 يومًا","30 يومًا","سنة واحدة"],"h1":"إنها حوالي شهر واحد.","h2":"في Kansas، المخالفة الأولى لسائق عمره أقل من 21 سنة بنتيجة من .02 إلى أقل من .08 تؤدي إلى إيقاف الرخصة 30 يومًا.","p":"صحيح. الإيقاف الأول مدته 30 يومًا."},"ref":{"doc":"KS","page":null}},{"id":"ks-018","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, what is the speed limit on a county or township road when no other limit is posted?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"It is ten less than the limit on other open highways.","h2":"In Kansas the speed limit on a county or township road is 55 mph unless a different limit is posted.","p":"Right. County and township roads are 55 mph."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en un camino de condado o municipio cuando no hay otro límite indicado?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Es diez menos que el límite de otras carreteras abiertas.","h2":"En Kansas el límite de velocidad en un camino de condado o municipio es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos de condado y municipio son de 55 mph."},"zh":{"q":"在 Kansas，如果没有标示其他限速，县道或乡镇道路的限速是多少？","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"比其他开阔公路的限速少十。","h2":"在 Kansas，县道或乡镇道路的限速是 55 mph，除非标示了不同的限速。","p":"对。县道和乡镇道路是 55 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa trên đường quận hoặc đường thị trấn (county or township road) là bao nhiêu khi không có biển báo khác?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Nó thấp hơn mười so với giới hạn trên các xa lộ thông thoáng khác.","h2":"Ở Kansas, tốc độ tối đa trên đường quận hoặc đường thị trấn là 55 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Đường quận và đường thị trấn là 55 mph."},"tl":{"q":"Sa Kansas, ano ang speed limit sa county o township road kapag walang ibang nakapaskil na limitasyon?","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"Sampu ang baba nito kaysa sa limitasyon sa ibang bukas na highway.","h2":"Sa Kansas, ang speed limit sa county o township road ay 55 mph maliban kung may ibang nakapaskil na limitasyon.","p":"Tama. 55 mph sa county at township road."},"ar":{"q":"في Kansas، ما حدّ السرعة على طريق المقاطعة أو البلدة (county or township road) إذا لم توجد لافتة بحدّ آخر؟","o":["45 mph","55 mph","65 mph","75 mph"],"h1":"إنه أقل بعشرة من الحدّ على الطرق السريعة المفتوحة الأخرى.","h2":"في Kansas حدّ السرعة على طريق المقاطعة أو البلدة هو 55 mph، إلا إذا كانت هناك لافتة بحدّ مختلف.","p":"صحيح. طرق المقاطعة والبلدة 55 mph."},"ref":{"doc":"KS","page":62}},{"id":"ks-019","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, where is 75 mph the speed limit?","o":["On every highway","On all county roads","In school zones at night","On divided multilane highways where it is posted"],"h1":"The highest limit only applies where a sign says so.","h2":"In Kansas, 75 mph is the limit only on divided multilane highways that the state has marked with that limit.","p":"Right. 75 mph only where it is posted."},"es":{"q":"En Kansas, ¿dónde es 75 mph el límite de velocidad?","o":["En todas las carreteras","En todos los caminos de condado","En zonas escolares de noche","En carreteras divididas de varios carriles donde esté indicado"],"h1":"El límite más alto solo aplica donde un letrero lo indica.","h2":"En Kansas, 75 mph es el límite solo en carreteras divididas de varios carriles donde el estado lo ha señalado.","p":"Correcto. 75 mph solo donde esté indicado."},"zh":{"q":"在 Kansas，在哪里限速是 75 mph？","o":["在每一条公路上","在所有县道上","晚上在学校区域","在标示了这个限速的多车道分隔公路上"],"h1":"最高的限速只在有标志说明的地方适用。","h2":"在 Kansas，75 mph 的限速只适用于州政府标示了这个限速的多车道分隔公路。","p":"对。只有标示的地方才是 75 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa 75 mph áp dụng ở đâu?","o":["Trên mọi xa lộ","Trên mọi đường quận","Trong khu trường học vào ban đêm","Trên xa lộ nhiều làn có dải phân cách, nơi có biển báo"],"h1":"Giới hạn cao nhất chỉ áp dụng nơi có biển báo.","h2":"Ở Kansas, 75 mph chỉ là giới hạn trên các xa lộ nhiều làn có dải phân cách mà tiểu bang đã gắn biển báo giới hạn đó.","p":"Đúng. 75 mph chỉ nơi có biển báo."},"tl":{"q":"Sa Kansas, saan 75 mph ang speed limit?","o":["Sa bawat highway","Sa lahat ng county road","Sa school zone sa gabi","Sa divided multilane highway kung saan ito nakapaskil"],"h1":"Ang pinakamataas na limitasyon ay para lang kung saan may karatula.","h2":"Sa Kansas, 75 mph ang limitasyon lang sa mga divided multilane highway na nilagyan ng estado ng karatulang may ganitong limitasyon.","p":"Tama. 75 mph kung saan lang ito nakapaskil."},"ar":{"q":"في Kansas، أين يكون حدّ السرعة 75 mph؟","o":["على كل طريق سريع","على كل طرق المقاطعة","في مناطق المدارس ليلًا","على الطرق السريعة متعددة المسارات المقسومة بفاصل، حيث توجد لافتة بذلك"],"h1":"أعلى حدّ ينطبق فقط حيث تقول اللافتة ذلك.","h2":"في Kansas يكون حدّ 75 mph فقط على الطرق السريعة متعددة المسارات المقسومة بفاصل التي وضعت عليها الولاية لافتة بهذا الحدّ.","p":"صحيح. 75 mph فقط حيث توجد لافتة."},"ref":{"doc":"KS","page":62}},{"id":"ks-020","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kansas, which stopped buses with their stop signals on require you to stop?","o":["School buses only","City transit buses","School buses, church buses and day care buses","Tour buses"],"h1":"It is more than just the yellow school bus.","h2":"In Kansas you must stop for a school bus, church bus or day care bus that is stopped to load or unload children.","p":"Right. School, church and day care buses."},"es":{"q":"En Kansas, ¿por cuáles autobuses detenidos con sus señales de parada encendidas debe usted detenerse?","o":["Solo autobuses escolares","Autobuses urbanos","Autobuses escolares, de iglesia y de guardería","Autobuses de turismo"],"h1":"Es más que solo el autobús escolar amarillo.","h2":"En Kansas usted debe detenerse ante un autobús escolar, de iglesia o de guardería que está detenido para subir o bajar niños.","p":"Correcto. Escolares, de iglesia y de guardería."},"zh":{"q":"在 Kansas，哪些停着并亮出停车信号的公交车要求你停车？","o":["只有校车","城市公交车","校车、教会巴士和托儿所巴士","旅游巴士"],"h1":"不只是黄色的校车。","h2":"在 Kansas，校车、教会巴士或托儿所巴士停下来让小孩上下车时，你必须停车。","p":"对。校车、教会巴士和托儿所巴士。"},"vi":{"q":"Ở Kansas, bạn phải dừng lại khi xe buýt nào đang dừng và bật đèn báo dừng?","o":["Chỉ xe buýt trường học","Xe buýt công cộng của thành phố","Xe buýt trường học, xe buýt nhà thờ và xe buýt nhà trẻ","Xe buýt du lịch"],"h1":"Không chỉ có xe buýt trường học màu vàng.","h2":"Ở Kansas, bạn phải dừng lại khi xe buýt trường học, xe buýt nhà thờ hoặc xe buýt nhà trẻ đang dừng để đón hoặc trả trẻ em.","p":"Đúng. Xe buýt trường học, nhà thờ và nhà trẻ."},"tl":{"q":"Sa Kansas, aling mga nakahintong bus na nakabukas ang stop signal ang kailangan mong hintuan?","o":["School bus lang","Mga city transit bus","School bus, church bus at day care bus","Mga tour bus"],"h1":"Hindi lang ang dilaw na school bus.","h2":"Sa Kansas, dapat kang huminto para sa school bus, church bus o day care bus na nakahinto para magsakay o magbaba ng mga bata.","p":"Tama. School, church at day care bus."},"ar":{"q":"في Kansas، أي حافلات متوقفة وإشارات التوقف فيها مضاءة يجب أن تتوقف لها؟","o":["الحافلات المدرسية فقط","حافلات النقل العام في المدينة","الحافلات المدرسية وحافلات الكنائس وحافلات دور الحضانة","الحافلات السياحية"],"h1":"الأمر لا يقتصر على الحافلة المدرسية الصفراء.","h2":"في Kansas يجب أن تتوقف للحافلة المدرسية أو حافلة الكنيسة أو حافلة دار الحضانة عندما تكون متوقفة لإركاب الأطفال أو إنزالهم.","p":"صحيح. حافلات المدارس والكنائس ودور الحضانة."},"ref":{"doc":"KS","page":18}},{"id":"ks-021","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kansas, a school bus is stopped on the other side of a divided highway. What must you do?","o":["You do not have to stop, but drive with care","Stop and wait until it moves","Honk and pass quickly","Stop only if children are visible"],"h1":"The divided road separates you from the bus.","h2":"In Kansas, if a school bus is stopped on the opposite roadway of a divided highway, you are not required to stop, though you should watch for children.","p":"Right. On a divided highway, oncoming traffic need not stop."},"es":{"q":"En Kansas, un autobús escolar está detenido al otro lado de una carretera dividida. ¿Qué debe hacer usted?","o":["No tiene que detenerse, pero maneje con cuidado","Detenerse y esperar hasta que avance","Tocar la bocina y pasar rápido","Detenerse solo si ve niños"],"h1":"La carretera dividida lo separa del autobús.","h2":"En Kansas, si un autobús escolar está detenido en el lado opuesto de una carretera dividida, usted no tiene que detenerse, aunque debe estar atento a los niños.","p":"Correcto. En carretera dividida, el tráfico contrario no se detiene."},"zh":{"q":"在 Kansas，一辆校车停在分隔公路的另一边。你必须做什么？","o":["你不用停车，但要小心驾驶","停车，等到它开走","按喇叭，快点开过去","只有看到小孩时才停车"],"h1":"分隔的道路把你和校车分开了。","h2":"在 Kansas，如果校车停在分隔公路对面的车道上，你不用停车，但应该注意小孩。","p":"对。在分隔公路上，对面来的车不用停车。"},"vi":{"q":"Ở Kansas, một xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Bạn không phải dừng, nhưng hãy lái cẩn thận","Dừng lại và chờ đến khi xe buýt chạy","Bấm còi và vượt nhanh","Chỉ dừng nếu thấy trẻ em"],"h1":"Dải phân cách ngăn bạn với xe buýt.","h2":"Ở Kansas, nếu xe buýt trường học dừng ở phía đường ngược chiều của xa lộ có dải phân cách, bạn không bắt buộc phải dừng, nhưng nên để ý trẻ em.","p":"Đúng. Trên xa lộ có dải phân cách, xe chạy ngược chiều không cần dừng."},"tl":{"q":"Sa Kansas, may school bus na nakahinto sa kabilang panig ng divided highway. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero magmaneho nang maingat","Huminto at maghintay hanggang umandar ito","Bumusina at lumampas nang mabilis","Huminto lang kung may nakikitang mga bata"],"h1":"Ang divider ng daan ang naghihiwalay sa iyo at sa bus.","h2":"Sa Kansas, kung nakahinto ang school bus sa kabilang daan ng divided highway, hindi mo kailangang huminto, pero bantayan mo ang mga bata.","p":"Tama. Sa divided highway, hindi kailangang huminto ang mga sasakyang kasalubong."},"ar":{"q":"في Kansas، حافلة مدرسية متوقفة على الجهة الأخرى من طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن قُد بحذر","توقف وانتظر حتى تتحرك","استخدم البوق وتجاوز بسرعة","توقف فقط إذا رأيت أطفالًا"],"h1":"الفاصل في الطريق يفصلك عن الحافلة.","h2":"في Kansas، إذا توقفت حافلة مدرسية على الجهة المقابلة من طريق سريع مقسوم بفاصل، فليس عليك أن تتوقف، لكن انتبه للأطفال.","p":"صحيح. على الطريق المقسوم بفاصل، ليس على السيارات القادمة من الاتجاه المعاكس أن تتوقف."},"ref":{"doc":"KS","page":18}},{"id":"ks-022","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, since July 2025, the move-over law covers which stopped vehicles?","o":["Only police cars","Any stopped vehicle with hazard lights on","Only tow trucks","Only school buses"],"h1":"The 2025 change widened the law to every kind of vehicle.","h2":"Since July 1, 2025, the Kansas move-over law covers any stopped vehicle showing hazard warning lights, so you must change lanes or slow down.","p":"Right. Any stopped vehicle with hazard lights."},"es":{"q":"En Kansas, desde julio de 2025, ¿a qué vehículos detenidos aplica la ley de cambiarse de carril?","o":["Solo a patrullas","A cualquier vehículo detenido con luces intermitentes","Solo a grúas","Solo a autobuses escolares"],"h1":"El cambio de 2025 amplió la ley a todo tipo de vehículo.","h2":"Desde el 1 de julio de 2025, la ley de Kansas aplica a cualquier vehículo detenido con luces intermitentes de emergencia, y usted debe cambiarse de carril o bajar la velocidad.","p":"Correcto. Cualquier vehículo detenido con intermitentes."},"zh":{"q":"在 Kansas，从 2025 年 7 月起，move-over 法保护哪些停着的车辆？","o":["只有警车","任何开着双闪灯、停着的车辆","只有拖车","只有校车"],"h1":"2025 年的修改把这条法律扩大到各种车辆。","h2":"从 2025 年 7 月 1 日起，Kansas 的 move-over 法保护任何开着双闪警示灯、停着的车辆，所以你必须换道或减速。","p":"对。任何开着双闪灯、停着的车辆。"},"vi":{"q":"Ở Kansas, từ tháng 7 năm 2025, luật nhường làn (move-over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Bất kỳ xe nào đang dừng và bật đèn cảnh báo","Chỉ xe kéo","Chỉ xe buýt trường học"],"h1":"Thay đổi năm 2025 mở rộng luật cho mọi loại xe.","h2":"Từ ngày 1 tháng 7 năm 2025, luật nhường làn của Kansas áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo, nên bạn phải chuyển làn hoặc giảm tốc độ.","p":"Đúng. Bất kỳ xe nào đang dừng và bật đèn cảnh báo."},"tl":{"q":"Sa Kansas, mula Hulyo 2025, aling mga nakahintong sasakyan ang sakop ng move-over law?","o":["Mga sasakyan ng pulis lang","Anumang nakahintong sasakyan na nakabukas ang hazard lights","Mga tow truck lang","Mga school bus lang"],"h1":"Pinalawak ng pagbabago noong 2025 ang batas para sa lahat ng uri ng sasakyan.","h2":"Mula Hulyo 1, 2025, sakop ng move-over law ng Kansas ang anumang nakahintong sasakyan na nakabukas ang hazard warning lights, kaya dapat kang lumipat ng lane o bumagal.","p":"Tama. Anumang nakahintong sasakyan na nakabukas ang hazard lights."},"ar":{"q":"في Kansas، منذ يوليو 2025، أي مركبات متوقفة يشملها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة فقط","أي مركبة متوقفة وأضواء التحذير فيها مضاءة","شاحنات السحب فقط","الحافلات المدرسية فقط"],"h1":"تغيير 2025 وسّع القانون ليشمل كل أنواع المركبات.","h2":"منذ 1 يوليو 2025، يشمل قانون الابتعاد في Kansas أي مركبة متوقفة تُظهر أضواء التحذير، لذلك يجب أن تغيّر المسار أو تخفّف السرعة.","p":"صحيح. أي مركبة متوقفة وأضواء التحذير فيها مضاءة."},"ref":{"doc":"KS","page":null}},{"id":"ks-023","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, can police stop a car only because the driver or front-seat passenger is not wearing a seat belt?","o":["No, never","Only at night","Only on interstates","Yes, it is a primary offense"],"h1":"Kansas made this rule stronger in 2010.","h2":"In Kansas, police may stop a car just because the driver or front-seat passenger is not wearing a seat belt.","p":"Right. In the front seat, it is a primary offense."},"es":{"q":"En Kansas, ¿puede la policía detener un carro solo porque el conductor o el pasajero de adelante no lleva el cinturón?","o":["No, nunca","Solo de noche","Solo en autopistas","Sí, es una infracción primaria"],"h1":"Kansas hizo esta regla más estricta en 2010.","h2":"En Kansas, la policía puede detener un carro solo porque el conductor o el pasajero de adelante no lleva puesto el cinturón de seguridad.","p":"Correcto. En el asiento delantero es una infracción primaria."},"zh":{"q":"在 Kansas，警察可以只因为司机或前排乘客没系安全带就让车停下吗？","o":["不可以，任何时候都不行","只在晚上","只在州际公路上","可以，这是主要违规（primary offense）"],"h1":"Kansas 在 2010 年把这个规定加强了。","h2":"在 Kansas，警察可以只因为司机或前排乘客没系安全带，就让车停下。","p":"对。在前排，这是主要违规。"},"vi":{"q":"Ở Kansas, cảnh sát có được chặn xe chỉ vì người lái hoặc hành khách ghế trước không thắt dây an toàn không?","o":["Không, không bao giờ","Chỉ vào ban đêm","Chỉ trên xa lộ liên bang","Có, đó là vi phạm chính (primary offense)"],"h1":"Kansas đã làm luật này chặt hơn vào năm 2010.","h2":"Ở Kansas, cảnh sát có thể chặn xe chỉ vì người lái hoặc hành khách ghế trước không thắt dây an toàn.","p":"Đúng. Ở ghế trước, đó là vi phạm chính."},"tl":{"q":"Sa Kansas, puwede bang patigilin ng pulis ang sasakyan dahil lang hindi naka-seat belt ang driver o ang pasahero sa harap?","o":["Hindi, hindi kailanman","Sa gabi lang","Sa interstate lang","Oo, ito ay primary offense"],"h1":"Pinatibay ng Kansas ang patakarang ito noong 2010.","h2":"Sa Kansas, puwedeng patigilin ng pulis ang sasakyan dahil lang hindi naka-seat belt ang driver o ang pasahero sa harap.","p":"Tama. Sa harapang upuan, ito ay primary offense."},"ar":{"q":"في Kansas، هل يمكن للشرطة إيقاف سيارة فقط لأن السائق أو الراكب الأمامي لا يضع حزام الأمان؟","o":["لا، أبدًا","في الليل فقط","على الطرق السريعة بين الولايات فقط","نعم، إنها مخالفة أساسية (primary offense)"],"h1":"جعلت Kansas هذه القاعدة أقوى في 2010.","h2":"في Kansas يمكن للشرطة إيقاف سيارة فقط لأن السائق أو الراكب في المقعد الأمامي لا يضع حزام الأمان.","p":"صحيح. في المقعد الأمامي، إنها مخالفة أساسية."},"ref":{"doc":"KS","page":null}},{"id":"ks-024","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, how many questions are on the knowledge test?","o":["20 questions","25 questions","40 questions","50 questions"],"h1":"It is a quarter of one hundred.","h2":"In Kansas, the knowledge test has 25 questions about traffic laws and road signs.","p":"Right. The Kansas knowledge test has 25 questions."},"es":{"q":"En Kansas, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","40 preguntas","50 preguntas"],"h1":"Es la cuarta parte de cien.","h2":"En Kansas, el examen de conocimientos tiene 25 preguntas sobre leyes de tránsito y señales de tránsito.","p":"Correcto. El examen de conocimientos de Kansas tiene 25 preguntas."},"zh":{"q":"在 Kansas，笔试（knowledge test）有多少道题？","o":["20 道题","25 道题","40 道题","50 道题"],"h1":"它是一百的四分之一。","h2":"在 Kansas，笔试有 25 道题，内容是交通法规和道路标志。","p":"对。Kansas 的笔试有 25 道题。"},"vi":{"q":"Ở Kansas, bài thi kiến thức (knowledge test) có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","40 câu hỏi","50 câu hỏi"],"h1":"Đó là một phần tư của một trăm.","h2":"Ở Kansas, bài thi kiến thức có 25 câu hỏi về luật giao thông và biển báo đường bộ.","p":"Đúng. Bài thi kiến thức ở Kansas có 25 câu hỏi."},"tl":{"q":"Sa Kansas, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","40 tanong","50 tanong"],"h1":"Ito ay isang-kapat ng isang daan.","h2":"Sa Kansas, may 25 tanong ang knowledge test tungkol sa mga batas trapiko at mga karatula sa daan.","p":"Tama. May 25 tanong ang knowledge test sa Kansas."},"ar":{"q":"في Kansas، كم سؤالًا في اختبار المعرفة (knowledge test)؟","o":["20 سؤالًا","25 سؤالًا","40 سؤالًا","50 سؤالًا"],"h1":"العدد هو ربع المئة.","h2":"في Kansas، يحتوي اختبار المعرفة على 25 سؤالًا عن قوانين المرور وإشارات الطريق.","p":"صحيح. اختبار المعرفة في Kansas فيه 25 سؤالًا."},"ref":{"doc":"KS","page":13}},{"id":"ks-025","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what happens after you fail the written test for the fourth time?","o":["You may try again the next working day","You must wait 30 days","You must take a driver education course first","You must wait at least six months"],"h1":"The wait is half a year.","h2":"In Kansas, after a fourth failed written test you must wait at least six months before you test again.","p":"Right. After four failures, you wait at least six months."},"es":{"q":"En Kansas, ¿qué pasa si reprueba el examen escrito por cuarta vez?","o":["Puede intentarlo de nuevo el siguiente día hábil","Debe esperar 30 días","Primero debe tomar un curso de educación vial","Debe esperar al menos seis meses"],"h1":"La espera es de medio año.","h2":"En Kansas, después de reprobar el examen escrito por cuarta vez, usted debe esperar al menos seis meses antes de volver a presentarlo.","p":"Correcto. Después de cuatro intentos fallidos, espera al menos seis meses."},"zh":{"q":"在 Kansas，笔试第四次没通过以后会怎样？","o":["你可以在下一个工作日再考","你必须等 30 天","你必须先上驾驶教育课","你必须至少等六个月"],"h1":"要等半年。","h2":"在 Kansas，笔试第四次没通过以后，你必须至少等六个月才能再考。","p":"对。考了四次没通过，要至少等六个月。"},"vi":{"q":"Ở Kansas, điều gì xảy ra sau khi bạn thi viết trượt lần thứ tư?","o":["Bạn có thể thi lại vào ngày làm việc kế tiếp","Bạn phải đợi 30 ngày","Bạn phải học một khóa giáo dục lái xe trước","Bạn phải đợi ít nhất sáu tháng"],"h1":"Thời gian chờ là nửa năm.","h2":"Ở Kansas, sau khi thi viết trượt lần thứ tư, bạn phải đợi ít nhất sáu tháng mới được thi lại.","p":"Đúng. Sau bốn lần trượt, bạn phải đợi ít nhất sáu tháng."},"tl":{"q":"Sa Kansas, ano ang mangyayari kapag bumagsak ka sa written test sa ikaapat na beses?","o":["Puwede kang sumubok ulit sa susunod na araw ng trabaho","Kailangan mong maghintay ng 30 araw","Kailangan mo munang kumuha ng driver education course","Kailangan mong maghintay nang hindi bababa sa anim na buwan"],"h1":"Kalahating taon ang paghihintay.","h2":"Sa Kansas, pagkatapos bumagsak sa written test sa ikaapat na beses, kailangan mong maghintay nang hindi bababa sa anim na buwan bago ka kumuha ulit ng test.","p":"Tama. Pagkatapos ng apat na pagbagsak, maghihintay ka nang hindi bababa sa anim na buwan."},"ar":{"q":"في Kansas، ماذا يحدث بعد أن ترسب في الاختبار الكتابي للمرة الرابعة؟","o":["يمكنك المحاولة مرة أخرى في يوم العمل التالي","يجب أن تنتظر 30 يومًا","يجب أن تأخذ دورة تعليم القيادة أولًا","يجب أن تنتظر ستة أشهر على الأقل"],"h1":"مدة الانتظار نصف سنة.","h2":"في Kansas، بعد الرسوب في الاختبار الكتابي للمرة الرابعة يجب أن تنتظر ستة أشهر على الأقل قبل أن تختبر مرة أخرى.","p":"صحيح. بعد أربع مرات رسوب، تنتظر ستة أشهر على الأقل."},"ref":{"doc":"KS","page":14}},{"id":"ks-026","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what happens the first time a driver refuses a test for alcohol or drugs?","o":["The license is suspended for 1 year","The driver gets a warning only","The license is suspended for 30 days","The license is taken away for life"],"h1":"It is a long suspension, but not for life.","h2":"In Kansas, refusing a test for alcohol or drugs the first time means a mandatory one-year license suspension.","p":"Right. A first refusal brings a one-year suspension."},"es":{"q":"En Kansas, ¿qué pasa la primera vez que un conductor se niega a hacerse una prueba de alcohol o drogas?","o":["La licencia se suspende por 1 año","El conductor solo recibe una advertencia","La licencia se suspende por 30 días","Le quitan la licencia de por vida"],"h1":"Es una suspensión larga, pero no de por vida.","h2":"En Kansas, negarse por primera vez a una prueba de alcohol o drogas significa una suspensión obligatoria de la licencia por un año.","p":"Correcto. Una primera negativa trae una suspensión de un año."},"zh":{"q":"在 Kansas，司机第一次拒绝做酒精或毒品检测会怎样？","o":["驾照被吊销 1 年","司机只会收到警告","驾照被吊销 30 天","驾照被终身取消"],"h1":"吊销时间很长，但不是终身。","h2":"在 Kansas，第一次拒绝做酒精或毒品检测，驾照必须被吊销一年。","p":"对。第一次拒绝检测，驾照会被吊销一年。"},"vi":{"q":"Ở Kansas, điều gì xảy ra khi tài xế từ chối kiểm tra rượu hoặc ma túy lần đầu tiên?","o":["Bằng lái bị đình chỉ 1 năm","Tài xế chỉ bị cảnh cáo","Bằng lái bị đình chỉ 30 ngày","Bằng lái bị thu hồi suốt đời"],"h1":"Đó là một thời gian đình chỉ dài, nhưng không phải suốt đời.","h2":"Ở Kansas, từ chối kiểm tra rượu hoặc ma túy lần đầu tiên thì bằng lái bắt buộc bị đình chỉ một năm.","p":"Đúng. Từ chối lần đầu thì bị đình chỉ bằng lái một năm."},"tl":{"q":"Sa Kansas, ano ang mangyayari sa unang beses na tumanggi ang driver sa test para sa alak o droga?","o":["Masususpinde ang lisensya nang 1 taon","Babala lang ang matatanggap ng driver","Masususpinde ang lisensya nang 30 araw","Babawiin ang lisensya habambuhay"],"h1":"Mahabang suspensyon ito, pero hindi habambuhay.","h2":"Sa Kansas, kapag tumanggi ka sa test para sa alak o droga sa unang beses, sapilitang masususpinde ang lisensya mo nang isang taon.","p":"Tama. Ang unang pagtanggi ay may suspensyon na isang taon."},"ar":{"q":"في Kansas، ماذا يحدث في المرة الأولى التي يرفض فيها السائق فحص الكحول أو المخدرات؟","o":["تُعلَّق الرخصة لمدة سنة واحدة","يحصل السائق على إنذار فقط","تُعلَّق الرخصة لمدة 30 يومًا","تُسحب الرخصة مدى الحياة"],"h1":"إنه تعليق طويل، لكنه ليس مدى الحياة.","h2":"في Kansas، رفض فحص الكحول أو المخدرات للمرة الأولى يعني تعليقًا إلزاميًا للرخصة لمدة سنة واحدة.","p":"صحيح. الرفض الأول يؤدي إلى تعليق الرخصة لمدة سنة."},"ref":{"doc":"KS","page":14}},{"id":"ks-027","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, a child aged 4 to 8 may use a seat belt instead of a booster seat in which case?","o":["When riding in the back seat","When the trip is short","When the child is taller than 4 feet 9 inches or weighs over 80 pounds","When a parent gives permission"],"h1":"It depends on the child's size, not on the trip.","h2":"In Kansas, a child aged 4 to 8 must use a child safety seat or booster seat unless the child is taller than 4 feet 9 inches or weighs more than 80 pounds.","p":"Right. Only a child over 4 feet 9 inches or 80 pounds may skip the booster."},"es":{"q":"En Kansas, ¿en qué caso un niño de 4 a 8 años puede usar el cinturón de seguridad en lugar de un asiento elevado?","o":["Cuando va en el asiento trasero","Cuando el viaje es corto","Cuando el niño mide más de 4 pies 9 pulgadas o pesa más de 80 libras","Cuando un padre le da permiso"],"h1":"Depende del tamaño del niño, no del viaje.","h2":"En Kansas, un niño de 4 a 8 años debe usar un asiento de seguridad infantil o asiento elevado, a menos que mida más de 4 pies 9 pulgadas o pese más de 80 libras.","p":"Correcto. Solo un niño de más de 4 pies 9 pulgadas o de 80 libras puede dejar el asiento elevado."},"zh":{"q":"在 Kansas，4 到 8 岁的孩子在哪种情况下可以用安全带代替增高座椅（booster seat）？","o":["坐在后座的时候","路程很短的时候","孩子身高超过 4 英尺 9 英寸或体重超过 80 磅的时候","家长同意的时候"],"h1":"要看孩子的身材，不看路程。","h2":"在 Kansas，4 到 8 岁的孩子必须使用儿童安全座椅或增高座椅，除非孩子身高超过 4 英尺 9 英寸或体重超过 80 磅。","p":"对。只有身高超过 4 英尺 9 英寸或体重超过 80 磅的孩子才可以不用增高座椅。"},"vi":{"q":"Ở Kansas, trẻ từ 4 đến 8 tuổi được dùng dây an toàn thay cho ghế nâng (booster seat) trong trường hợp nào?","o":["Khi ngồi ở ghế sau","Khi chuyến đi ngắn","Khi trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound","Khi cha mẹ cho phép"],"h1":"Điều này tùy vào vóc dáng của trẻ, không phải chuyến đi.","h2":"Ở Kansas, trẻ từ 4 đến 8 tuổi phải dùng ghế an toàn trẻ em hoặc ghế nâng, trừ khi trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound.","p":"Đúng. Chỉ trẻ cao hơn 4 feet 9 inch hoặc nặng hơn 80 pound mới được không dùng ghế nâng."},"tl":{"q":"Sa Kansas, kailan puwedeng gumamit ng seat belt sa halip na booster seat ang batang edad 4 hanggang 8?","o":["Kapag nakaupo sa likurang upuan","Kapag maikli ang biyahe","Kapag mas matangkad ang bata sa 4 feet 9 inches o mas mabigat sa 80 pounds","Kapag pumayag ang magulang"],"h1":"Nakadepende ito sa laki ng bata, hindi sa biyahe.","h2":"Sa Kansas, ang batang edad 4 hanggang 8 ay dapat gumamit ng child safety seat o booster seat, maliban kung mas matangkad siya sa 4 feet 9 inches o mas mabigat sa 80 pounds.","p":"Tama. Ang batang lampas 4 feet 9 inches o 80 pounds lang ang puwedeng hindi gumamit ng booster."},"ar":{"q":"في Kansas، متى يجوز لطفل عمره من 4 إلى 8 سنوات أن يستخدم حزام الأمان بدلًا من المقعد الرافع (booster seat)؟","o":["عند الجلوس في المقعد الخلفي","عندما تكون الرحلة قصيرة","عندما يكون طول الطفل أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا","عندما يعطي أحد الوالدين الإذن"],"h1":"الأمر يعتمد على حجم الطفل، لا على الرحلة.","h2":"في Kansas، يجب على الطفل الذي عمره من 4 إلى 8 سنوات أن يستخدم مقعد أمان للأطفال أو مقعدًا رافعًا، إلا إذا كان طوله أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا.","p":"صحيح. فقط الطفل الذي طوله أكثر من 4 أقدام و9 بوصات أو وزنه أكثر من 80 رطلًا يمكنه ألا يستخدم المقعد الرافع."},"ref":{"doc":"KS","page":16}},{"id":"ks-028","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 50 feet"],"h1":"Fire trucks need room to hook up to the hydrant.","h2":"In Kansas, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Kansas, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectarse al hidrante.","h2":"En Kansas, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Kansas，停车时离消防栓最近可以多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 50 英尺"],"h1":"消防车需要空间连接消防栓。","h2":"在 Kansas，你不能在离消防栓 15 英尺以内的地方停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Kansas, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 50 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vào trụ nước.","h2":"Ở Kansas, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước ít nhất 15 feet."},"tl":{"q":"Sa Kansas, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Kailangan ng mga fire truck ng puwang para makakabit sa hydrant.","h2":"Sa Kansas, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa hydrant."},"ar":{"q":"في Kansas، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل الخراطيم بالصنبور.","h2":"في Kansas لا يجوز لك أن تركن سيارتك على بُعد أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من الصنبور."},"ref":{"doc":"KS","page":19}},{"id":"ks-029","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what following distance does the handbook advise in bad weather or other poor conditions?","o":["Four seconds","One second","Two seconds","Three car lengths"],"h1":"It is double the time used in good conditions.","h2":"In Kansas, the handbook advises a two-second following distance in good conditions and four seconds in poor conditions.","p":"Right. Use four seconds when conditions are poor."},"es":{"q":"En Kansas, ¿qué distancia de seguimiento recomienda el manual con mal tiempo u otras malas condiciones?","o":["Cuatro segundos","Un segundo","Dos segundos","Tres largos de carro"],"h1":"Es el doble del tiempo que se usa con buenas condiciones.","h2":"En Kansas, el manual recomienda dos segundos de distancia con buenas condiciones y cuatro segundos con malas condiciones.","p":"Correcto. Use cuatro segundos cuando las condiciones son malas."},"zh":{"q":"在 Kansas，驾驶手册建议在坏天气或其他不良条件下保持多大的跟车距离？","o":["四秒","一秒","两秒","三个车身长度"],"h1":"这是良好条件下所用时间的两倍。","h2":"在 Kansas，驾驶手册建议在良好条件下保持两秒的跟车距离，在不良条件下保持四秒。","p":"对。条件不好时，保持四秒。"},"vi":{"q":"Ở Kansas, sổ tay lái xe khuyên giữ khoảng cách bao xa với xe phía trước khi thời tiết xấu hoặc điều kiện kém?","o":["Bốn giây","Một giây","Hai giây","Ba thân xe"],"h1":"Đó là gấp đôi thời gian dùng khi điều kiện tốt.","h2":"Ở Kansas, sổ tay khuyên giữ khoảng cách hai giây khi điều kiện tốt và bốn giây khi điều kiện kém.","p":"Đúng. Hãy giữ bốn giây khi điều kiện kém."},"tl":{"q":"Sa Kansas, anong layo sa sinusundang sasakyan ang ipinapayo ng handbook kapag masama ang panahon o iba pang mahirap na kondisyon?","o":["Apat na segundo","Isang segundo","Dalawang segundo","Tatlong haba ng kotse"],"h1":"Doble ito ng oras na ginagamit kapag maganda ang kondisyon.","h2":"Sa Kansas, ipinapayo ng handbook ang dalawang segundong layo kapag maganda ang kondisyon at apat na segundo kapag mahirap ang kondisyon.","p":"Tama. Gumamit ng apat na segundo kapag mahirap ang kondisyon."},"ar":{"q":"في Kansas، ما مسافة المتابعة التي ينصح بها دليل القيادة في الطقس السيئ أو الظروف الصعبة الأخرى؟","o":["أربع ثوانٍ","ثانية واحدة","ثانيتان","طول ثلاث سيارات"],"h1":"إنها ضعف الوقت المستخدم في الظروف الجيدة.","h2":"في Kansas ينصح دليل القيادة بمسافة متابعة ثانيتين في الظروف الجيدة وأربع ثوانٍ في الظروف الصعبة.","p":"صحيح. استخدم أربع ثوانٍ عندما تكون الظروف صعبة."},"ref":{"doc":"KS","page":17}},{"id":"ks-030","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what vision do you need to pass the screening for a license?","o":["20/20 in both eyes","20/40 in both eyes","20/70 in one eye","20/40 in at least one eye"],"h1":"Only one eye needs to meet the standard, with or without glasses.","h2":"In Kansas, you need vision of at least 20/40 in one eye, with or without glasses or contacts.","p":"Right. You need at least 20/40 in one eye."},"es":{"q":"En Kansas, ¿qué vista necesita para aprobar la prueba de la vista para la licencia?","o":["20/20 en los dos ojos","20/40 en los dos ojos","20/70 en un ojo","20/40 en al menos un ojo"],"h1":"Solo un ojo necesita cumplir el requisito, con o sin lentes.","h2":"En Kansas, usted necesita una vista de al menos 20/40 en un ojo, con o sin lentes o lentes de contacto.","p":"Correcto. Necesita al menos 20/40 en un ojo."},"zh":{"q":"在 Kansas，要通过驾照的视力检查，你需要什么样的视力？","o":["双眼 20/20","双眼 20/40","一只眼 20/70","至少一只眼 20/40"],"h1":"只需要一只眼睛达到标准，戴不戴眼镜都可以。","h2":"在 Kansas，你至少一只眼睛的视力需要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。你至少一只眼睛需要达到 20/40。"},"vi":{"q":"Ở Kansas, bạn cần thị lực như thế nào để qua bài kiểm tra mắt khi lấy bằng lái?","o":["20/20 ở cả hai mắt","20/40 ở cả hai mắt","20/70 ở một mắt","20/40 ở ít nhất một mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn, có hoặc không có kính.","h2":"Ở Kansas, bạn cần thị lực ít nhất 20/40 ở một mắt, có hoặc không có kính đeo hay kính áp tròng.","p":"Đúng. Bạn cần ít nhất 20/40 ở một mắt."},"tl":{"q":"Sa Kansas, anong paningin ang kailangan mo para pumasa sa vision screening para sa lisensya?","o":["20/20 sa dalawang mata","20/40 sa dalawang mata","20/70 sa isang mata","20/40 sa kahit isang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan, may salamin man o wala.","h2":"Sa Kansas, kailangan mo ng paningin na hindi bababa sa 20/40 sa isang mata, may salamin o contact lens man o wala.","p":"Tama. Kailangan mo ng hindi bababa sa 20/40 sa isang mata."},"ar":{"q":"في Kansas، ما قوة النظر التي تحتاجها لتنجح في فحص النظر للحصول على رخصة؟","o":["20/20 في العينين","20/40 في العينين","20/70 في عين واحدة","20/40 في عين واحدة على الأقل"],"h1":"يكفي أن تبلغ عين واحدة المعيار، بالنظارة أو بدونها.","h2":"في Kansas تحتاج إلى نظر لا يقل عن 20/40 في عين واحدة، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. تحتاج إلى 20/40 على الأقل في عين واحدة."},"ref":{"doc":"KS","page":13}},{"id":"ks-031","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, your driver's license has been expired for more than one year. What must you do to get it back?","o":["Pay only the $1 late penalty","Pass the vision, written, and driving tests","Pass only the vision test","Take a driver education course"],"h1":"After a long time, you must show everything again, as a new driver would.","h2":"In Kansas, if your license has been expired for more than one year, you must pass full testing: the vision, written, and driving tests.","p":"Right. After more than a year, you take all three tests."},"es":{"q":"En Kansas, su licencia de manejar lleva más de un año vencida. ¿Qué debe hacer para recuperarla?","o":["Pagar solo la multa de $1 por atraso","Aprobar las pruebas de la vista, escrita y de manejo","Aprobar solo la prueba de la vista","Tomar un curso de educación vial"],"h1":"Después de mucho tiempo, debe demostrar todo otra vez, como un conductor nuevo.","h2":"En Kansas, si su licencia lleva más de un año vencida, usted debe aprobar todas las pruebas: la de la vista, la escrita y la de manejo.","p":"Correcto. Después de más de un año, toma las tres pruebas."},"zh":{"q":"在 Kansas，你的驾照已经过期超过一年。要恢复驾照，你必须做什么？","o":["只交 $1 的逾期罚款","通过视力、笔试和路考","只通过视力检查","参加驾驶教育课程"],"h1":"过了很长时间后，你必须像新司机一样重新证明一切。","h2":"在 Kansas，如果你的驾照过期超过一年，你必须通过全部考试：视力、笔试和路考。","p":"对。过期超过一年，三项考试都要考。"},"vi":{"q":"Ở Kansas, bằng lái của bạn đã hết hạn hơn một năm. Bạn phải làm gì để lấy lại?","o":["Chỉ trả tiền phạt trễ hạn $1","Đậu bài kiểm tra mắt, thi viết và thi lái","Chỉ đậu bài kiểm tra mắt","Học một khóa giáo dục lái xe"],"h1":"Sau một thời gian dài, bạn phải chứng minh lại mọi thứ như một tài xế mới.","h2":"Ở Kansas, nếu bằng lái của bạn đã hết hạn hơn một năm, bạn phải thi đầy đủ: kiểm tra mắt, thi viết và thi lái.","p":"Đúng. Sau hơn một năm, bạn phải thi cả ba bài."},"tl":{"q":"Sa Kansas, mahigit isang taon nang expired ang lisensya mo. Ano ang dapat mong gawin para makuha itong muli?","o":["Bayaran lang ang $1 na multa sa pagkahuli","Pumasa sa vision, written, at driving test","Pumasa lang sa vision test","Kumuha ng driver education course"],"h1":"Pagkatapos ng mahabang panahon, kailangan mong ipakita muli ang lahat, gaya ng bagong driver.","h2":"Sa Kansas, kung mahigit isang taon nang expired ang lisensya mo, kailangan mong pumasa sa buong pagsusulit: ang vision, written, at driving test.","p":"Tama. Pagkalipas ng mahigit isang taon, kukunin mo ang tatlong test."},"ar":{"q":"في Kansas، انتهت صلاحية رخصة قيادتك منذ أكثر من سنة. ماذا يجب أن تفعل لاستعادتها؟","o":["دفع غرامة التأخير $1 فقط","النجاح في فحص النظر والاختبار الكتابي واختبار القيادة","النجاح في فحص النظر فقط","حضور دورة تعليم القيادة"],"h1":"بعد مدة طويلة، يجب أن تُثبت كل شيء من جديد، كما يفعل السائق الجديد.","h2":"في Kansas، إذا انتهت صلاحية رخصتك منذ أكثر من سنة، يجب أن تنجح في الاختبارات كاملة: فحص النظر والاختبار الكتابي واختبار القيادة.","p":"صحيح. بعد أكثر من سنة، تخضع للاختبارات الثلاثة."},"ref":{"doc":"KS","page":14}},{"id":"ks-032","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how soon after moving to the state must a new resident get a Kansas driver's license?","o":["Within 10 days","Within 1 year","Within 90 days","Only when the old license expires"],"h1":"It is about three months.","h2":"In Kansas, a new resident must get a Kansas driver's license within 90 days of moving to the state.","p":"Right. New residents have 90 days."},"es":{"q":"En Kansas, ¿en cuánto tiempo después de mudarse al estado debe un nuevo residente obtener una licencia de Kansas?","o":["En un plazo de 10 días","En un plazo de 1 año","En un plazo de 90 días","Solo cuando venza la licencia anterior"],"h1":"Son unos tres meses.","h2":"En Kansas, un nuevo residente debe obtener una licencia de conducir de Kansas en un plazo de 90 días después de mudarse al estado.","p":"Correcto. Los nuevos residentes tienen 90 días."},"zh":{"q":"在 Kansas，新居民搬到本州后，必须在多长时间内办理 Kansas 驾照？","o":["10 天内","1 年内","90 天内","只有在旧驾照过期时"],"h1":"大约是三个月。","h2":"在 Kansas，新居民必须在搬到本州后 90 天内办理 Kansas 驾照。","p":"对。新居民有 90 天时间。"},"vi":{"q":"Ở Kansas, cư dân mới phải lấy bằng lái Kansas trong bao lâu sau khi chuyển đến tiểu bang?","o":["Trong vòng 10 ngày","Trong vòng 1 năm","Trong vòng 90 ngày","Chỉ khi bằng lái cũ hết hạn"],"h1":"Khoảng ba tháng.","h2":"Ở Kansas, cư dân mới phải lấy bằng lái Kansas trong vòng 90 ngày sau khi chuyển đến tiểu bang.","p":"Đúng. Cư dân mới có 90 ngày."},"tl":{"q":"Sa Kansas, gaano katagal pagkalipat sa estado dapat kumuha ng Kansas driver's license ang bagong residente?","o":["Sa loob ng 10 araw","Sa loob ng 1 taon","Sa loob ng 90 araw","Kapag expired na lang ang lumang lisensya"],"h1":"Mga tatlong buwan ito.","h2":"Sa Kansas, dapat kumuha ang bagong residente ng Kansas driver's license sa loob ng 90 araw pagkalipat sa estado.","p":"Tama. May 90 araw ang mga bagong residente."},"ar":{"q":"في Kansas، خلال كم من الوقت بعد الانتقال إلى الولاية يجب على المقيم الجديد أن يحصل على رخصة قيادة من Kansas؟","o":["خلال 10 أيام","خلال سنة واحدة","خلال 90 يومًا","فقط عندما تنتهي صلاحية الرخصة القديمة"],"h1":"المدة حوالي ثلاثة أشهر.","h2":"في Kansas، يجب على المقيم الجديد أن يحصل على رخصة قيادة من Kansas خلال 90 يومًا من انتقاله إلى الولاية.","p":"صحيح. لدى المقيمين الجدد 90 يومًا."},"ref":{"doc":"KS","page":11}},{"id":"ks-033","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, how long is a Class C instruction permit valid?","o":["One year from the day it is issued","Six months from the day it is issued","Two years from the day it is issued","Until your 18th birthday"],"h1":"You renew it by passing the written test again.","h2":"In Kansas, a Class C instruction permit is valid for one year from the day it is issued.","p":"Right. The permit lasts one year."},"es":{"q":"En Kansas, ¿por cuánto tiempo es válido un permiso de aprendizaje Clase C?","o":["Un año desde el día en que se emite","Seis meses desde el día en que se emite","Dos años desde el día en que se emite","Hasta que usted cumpla 18 años"],"h1":"Se renueva aprobando otra vez el examen escrito.","h2":"En Kansas, un permiso de aprendizaje Clase C es válido por un año desde el día en que se emite.","p":"Correcto. El permiso dura un año."},"zh":{"q":"在 Kansas，C 类学习驾照的有效期是多长？","o":["从发放之日起一年","从发放之日起六个月","从发放之日起两年","直到你满 18 岁"],"h1":"再次通过笔试就可以续期。","h2":"在 Kansas，C 类学习驾照从发放之日起有效一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Kansas, giấy phép tập lái hạng C có hiệu lực bao lâu?","o":["Một năm kể từ ngày cấp","Sáu tháng kể từ ngày cấp","Hai năm kể từ ngày cấp","Đến sinh nhật 18 tuổi của bạn"],"h1":"Bạn gia hạn bằng cách thi viết đậu lại.","h2":"Ở Kansas, giấy phép tập lái hạng C có hiệu lực một năm kể từ ngày cấp.","p":"Đúng. Giấy phép tập lái có hiệu lực một năm."},"tl":{"q":"Sa Kansas, gaano katagal valid ang Class C instruction permit?","o":["Isang taon mula sa araw na ibinigay ito","Anim na buwan mula sa araw na ibinigay ito","Dalawang taon mula sa araw na ibinigay ito","Hanggang sa ika-18 kaarawan mo"],"h1":"Nire-renew mo ito sa pagpasa muli sa written test.","h2":"Sa Kansas, valid ang Class C instruction permit nang isang taon mula sa araw na ibinigay ito.","p":"Tama. Isang taon ang tagal ng permit."},"ar":{"q":"في Kansas، ما مدة صلاحية تصريح التعلّم من الفئة C؟","o":["سنة واحدة من يوم إصداره","ستة أشهر من يوم إصداره","سنتان من يوم إصداره","حتى عيد ميلادك الثامن عشر"],"h1":"تجدّده بالنجاح في الاختبار الكتابي مرة أخرى.","h2":"في Kansas، يكون تصريح التعلّم من الفئة C صالحًا لمدة سنة واحدة من يوم إصداره.","p":"صحيح. التصريح صالح لمدة سنة."},"ref":{"doc":"KS","page":14}},{"id":"ks-034","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, you fail the written test for the first time. When may you take it again?","o":["Only after waiting 30 days","Only after waiting six months","Only after taking a driving class","The next working day, after paying a small re-exam fee"],"h1":"Kansas lets you try again very soon.","h2":"In Kansas, you may retake a failed test as soon as the next working day, after paying a $1.50 re-exam fee.","p":"Right. You can try again the next working day."},"es":{"q":"En Kansas, usted no aprueba el examen escrito por primera vez. ¿Cuándo puede volver a tomarlo?","o":["Solo después de esperar 30 días","Solo después de esperar seis meses","Solo después de tomar una clase de manejo","El siguiente día hábil, después de pagar una pequeña tarifa"],"h1":"Kansas le permite intentarlo de nuevo muy pronto.","h2":"En Kansas, usted puede repetir un examen no aprobado desde el siguiente día hábil, después de pagar una tarifa de $1.50.","p":"Correcto. Puede intentarlo otra vez el siguiente día hábil."},"zh":{"q":"在 Kansas，你第一次笔试没有通过。你什么时候可以再考？","o":["只能等 30 天后","只能等六个月后","只能在上完驾驶课之后","下一个工作日，交一小笔补考费之后"],"h1":"Kansas 让你很快就能再试一次。","h2":"在 Kansas，考试没通过后，你最早可以在下一个工作日重考，但要先交 $1.50 的补考费。","p":"对。下一个工作日就可以再考。"},"vi":{"q":"Ở Kansas, bạn thi viết rớt lần đầu. Khi nào bạn được thi lại?","o":["Chỉ sau khi chờ 30 ngày","Chỉ sau khi chờ sáu tháng","Chỉ sau khi học một lớp lái xe","Ngày làm việc kế tiếp, sau khi trả một khoản phí thi lại nhỏ"],"h1":"Kansas cho bạn thi lại rất sớm.","h2":"Ở Kansas, bạn có thể thi lại bài đã rớt sớm nhất là vào ngày làm việc kế tiếp, sau khi trả phí thi lại $1.50.","p":"Đúng. Bạn có thể thi lại vào ngày làm việc kế tiếp."},"tl":{"q":"Sa Kansas, bumagsak ka sa written test sa unang pagkakataon. Kailan ka puwedeng kumuha ulit?","o":["Pagkatapos lang maghintay ng 30 araw","Pagkatapos lang maghintay ng anim na buwan","Pagkatapos lang kumuha ng driving class","Sa susunod na araw ng trabaho, pagkatapos magbayad ng maliit na re-exam fee"],"h1":"Pinapayagan ka ng Kansas na sumubok ulit nang napakabilis.","h2":"Sa Kansas, puwede mong ulitin ang test na binagsak mo kahit sa susunod na araw ng trabaho, pagkatapos magbayad ng $1.50 na re-exam fee.","p":"Tama. Puwede kang sumubok ulit sa susunod na araw ng trabaho."},"ar":{"q":"في Kansas، رسبت في الاختبار الكتابي للمرة الأولى. متى يمكنك إعادته؟","o":["فقط بعد الانتظار 30 يومًا","فقط بعد الانتظار ستة أشهر","فقط بعد حضور درس قيادة","في يوم العمل التالي، بعد دفع رسوم صغيرة لإعادة الاختبار"],"h1":"تسمح لك Kansas بالمحاولة مرة أخرى قريبًا جدًا.","h2":"في Kansas، يمكنك إعادة الاختبار الذي رسبت فيه ابتداءً من يوم العمل التالي، بعد دفع رسوم إعادة الاختبار $1.50.","p":"صحيح. يمكنك المحاولة مرة أخرى في يوم العمل التالي."},"ref":{"doc":"KS","page":14}},{"id":"ks-035","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what score do you need to pass the knowledge test?","o":["70 percent","80 percent","75 percent","90 percent"],"h1":"On a 25-question test, that is 20 right answers.","h2":"In Kansas, you must score 80 percent to pass the knowledge test.","p":"Right. You need 80 percent."},"es":{"q":"En Kansas, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["70 por ciento","80 por ciento","75 por ciento","90 por ciento"],"h1":"En un examen de 25 preguntas, son 20 respuestas correctas.","h2":"En Kansas, usted debe obtener un 80 por ciento para aprobar el examen de conocimientos.","p":"Correcto. Necesita un 80 por ciento."},"zh":{"q":"在 Kansas，笔试需要考到多少分才能通过？","o":["70%","80%","75%","90%"],"h1":"在 25 道题的考试中，就是答对 20 题。","h2":"在 Kansas，笔试必须考到 80% 才能通过。","p":"对。你需要 80%。"},"vi":{"q":"Ở Kansas, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["70 phần trăm","80 phần trăm","75 phần trăm","90 phần trăm"],"h1":"Với bài thi 25 câu, đó là 20 câu đúng.","h2":"Ở Kansas, bạn phải đạt 80 phần trăm để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 80 phần trăm."},"tl":{"q":"Sa Kansas, anong score ang kailangan mo para pumasa sa knowledge test?","o":["70 porsiyento","80 porsiyento","75 porsiyento","90 porsiyento"],"h1":"Sa test na may 25 tanong, 20 tamang sagot iyon.","h2":"Sa Kansas, kailangan mong makakuha ng 80 porsiyento para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 80 porsiyento."},"ar":{"q":"في Kansas، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة؟","o":["70 بالمئة","80 بالمئة","75 بالمئة","90 بالمئة"],"h1":"في اختبار من 25 سؤالًا، هذا يعني 20 إجابة صحيحة.","h2":"في Kansas، يجب أن تحصل على 80 بالمئة للنجاح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 80 بالمئة."},"ref":{"doc":"KS","page":94}},{"id":"ks-036","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, does a driver education course taken over the internet count for a license?","o":["Yes, any online course is accepted","Yes, if the course lasts at least 6 hours","No, internet courses are not accepted","Yes, but only for drivers 16 or older"],"h1":"Approved courses include time in a classroom and behind the wheel.","h2":"In Kansas, internet driver education courses are not accepted; only courses from approved school districts or approved private schools count.","p":"Right. Online driver education does not count in Kansas."},"es":{"q":"En Kansas, ¿cuenta para la licencia un curso de educación vial tomado por internet?","o":["Sí, se acepta cualquier curso en línea","Sí, si el curso dura al menos 6 horas","No, los cursos por internet no se aceptan","Sí, pero solo para conductores de 16 años o más"],"h1":"Los cursos aprobados incluyen tiempo en el salón y al volante.","h2":"En Kansas, los cursos de educación vial por internet no se aceptan; solo cuentan los cursos de distritos escolares aprobados o de escuelas privadas aprobadas.","p":"Correcto. La educación vial en línea no cuenta en Kansas."},"zh":{"q":"在 Kansas，在网上参加的驾驶教育课程可以用来申请驾照吗？","o":["可以，任何网上课程都接受","可以，只要课程至少 6 小时","不可以，网上课程不被接受","可以，但只限 16 岁或以上的司机"],"h1":"认可的课程包括课堂学习和实际驾驶。","h2":"在 Kansas，网上驾驶教育课程不被接受；只有认可的学区或认可的私立学校的课程才算数。","p":"对。在 Kansas，网上驾驶教育不算数。"},"vi":{"q":"Ở Kansas, khóa giáo dục lái xe học qua internet có được tính để lấy bằng lái không?","o":["Có, mọi khóa học trực tuyến đều được chấp nhận","Có, nếu khóa học kéo dài ít nhất 6 giờ","Không, khóa học qua internet không được chấp nhận","Có, nhưng chỉ cho tài xế từ 16 tuổi trở lên"],"h1":"Các khóa học được chấp thuận gồm thời gian trong lớp và thời gian cầm lái.","h2":"Ở Kansas, khóa giáo dục lái xe qua internet không được chấp nhận; chỉ khóa học của học khu được chấp thuận hoặc trường tư được chấp thuận mới được tính.","p":"Đúng. Giáo dục lái xe trực tuyến không được tính ở Kansas."},"tl":{"q":"Sa Kansas, binibilang ba para sa lisensya ang driver education course na kinuha sa internet?","o":["Oo, tinatanggap ang anumang online course","Oo, kung tumatagal ang course nang hindi bababa sa 6 na oras","Hindi, hindi tinatanggap ang mga internet course","Oo, pero para lang sa mga driver na 16 pataas"],"h1":"Kasama sa mga aprubadong course ang oras sa classroom at sa likod ng manibela.","h2":"Sa Kansas, hindi tinatanggap ang mga internet driver education course; ang mga course lang mula sa aprubadong school district o aprubadong private school ang binibilang.","p":"Tama. Hindi binibilang sa Kansas ang online driver education."},"ar":{"q":"في Kansas، هل تُحتسب دورة تعليم القيادة التي تُؤخذ عبر الإنترنت للحصول على رخصة؟","o":["نعم، تُقبل أي دورة عبر الإنترنت","نعم، إذا استمرت الدورة 6 ساعات على الأقل","لا، الدورات عبر الإنترنت غير مقبولة","نعم، ولكن فقط للسائقين بعمر 16 أو أكثر"],"h1":"الدورات المعتمدة تشمل وقتًا في الصف ووقتًا خلف المقود.","h2":"في Kansas، دورات تعليم القيادة عبر الإنترنت غير مقبولة؛ تُحتسب فقط الدورات من المناطق التعليمية المعتمدة أو المدارس الخاصة المعتمدة.","p":"صحيح. تعليم القيادة عبر الإنترنت لا يُحتسب في Kansas."},"ref":{"doc":"KS","page":9}},{"id":"ks-037","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, how many moving violations within 12 months can lead to a license suspension?","o":["Three","Five","Seven","Ten"],"h1":"It is a small number.","h2":"In Kansas, three moving violation convictions within 12 months can get your license suspended.","p":"Right. Three moving violations in a year can cost you your license."},"es":{"q":"En Kansas, ¿cuántas infracciones de tránsito en movimiento en 12 meses pueden causar la suspensión de la licencia?","o":["Tres","Cinco","Siete","Diez"],"h1":"Es un número pequeño.","h2":"En Kansas, tres condenas por infracciones en movimiento en 12 meses pueden causar la suspensión de su licencia.","p":"Correcto. Tres infracciones en un año pueden costarle la licencia."},"zh":{"q":"在 Kansas，12 个月内有几次行车违规就可能导致驾照被暂停？","o":["三次","五次","七次","十次"],"h1":"这个数字很小。","h2":"在 Kansas，12 个月内有三次行车违规定罪，你的驾照就可能被暂停。","p":"对。一年内三次行车违规就可能让你失去驾照。"},"vi":{"q":"Ở Kansas, bao nhiêu lần vi phạm khi lái xe trong vòng 12 tháng có thể khiến bằng lái bị đình chỉ?","o":["Ba lần","Năm lần","Bảy lần","Mười lần"],"h1":"Đó là một con số nhỏ.","h2":"Ở Kansas, bị kết án ba lần vi phạm khi lái xe trong vòng 12 tháng có thể khiến bằng lái của bạn bị đình chỉ.","p":"Đúng. Ba lần vi phạm trong một năm có thể làm bạn mất bằng lái."},"tl":{"q":"Sa Kansas, ilang moving violation sa loob ng 12 buwan ang puwedeng humantong sa suspensyon ng lisensya?","o":["Tatlo","Lima","Pito","Sampu"],"h1":"Maliit na bilang ito.","h2":"Sa Kansas, puwedeng ma-suspend ang lisensya mo dahil sa tatlong conviction sa moving violation sa loob ng 12 buwan.","p":"Tama. Puwede kang mawalan ng lisensya dahil sa tatlong moving violation sa isang taon."},"ar":{"q":"في Kansas، كم مخالفة أثناء القيادة خلال 12 شهرًا قد تؤدي إلى تعليق الرخصة؟","o":["ثلاث","خمس","سبع","عشر"],"h1":"إنه رقم صغير.","h2":"في Kansas، يمكن أن تؤدي ثلاث إدانات بمخالفات أثناء القيادة خلال 12 شهرًا إلى تعليق رخصتك.","p":"صحيح. ثلاث مخالفات أثناء القيادة في سنة قد تُفقدك رخصتك."},"ref":{"doc":"KS","page":14}},{"id":"ks-038","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, what happens if you do not keep liability insurance on your vehicle at all times?","o":["Nothing, as long as you drive carefully","You only get a warning","You must take the written test again","Your license is suspended with no set end date"],"h1":"Kansas treats a gap in insurance very seriously.","h2":"In Kansas, failing to keep continuous liability insurance on your vehicle leads to a mandatory suspension with no set end date.","p":"Right. A gap in insurance means an indefinite suspension."},"es":{"q":"En Kansas, ¿qué pasa si usted no mantiene siempre un seguro de responsabilidad civil en su vehículo?","o":["Nada, siempre que maneje con cuidado","Solo recibe una advertencia","Debe tomar otra vez el examen escrito","Su licencia se suspende sin fecha de fin"],"h1":"Kansas toma muy en serio una falta de seguro.","h2":"En Kansas, no mantener un seguro de responsabilidad civil continuo en su vehículo causa una suspensión obligatoria sin fecha de fin.","p":"Correcto. Una falta de seguro causa una suspensión indefinida."},"zh":{"q":"在 Kansas，如果你没有一直为车辆保持责任保险，会发生什么？","o":["没事，只要你小心驾驶","你只会收到警告","你必须重新参加笔试","你的驾照会被暂停，而且没有固定的结束日期"],"h1":"Kansas 非常重视保险中断。","h2":"在 Kansas，如果没有为车辆持续保持责任保险，驾照会被强制暂停，而且没有固定的结束日期。","p":"对。保险中断意味着无限期暂停驾照。"},"vi":{"q":"Ở Kansas, điều gì xảy ra nếu bạn không luôn luôn có bảo hiểm trách nhiệm cho xe của mình?","o":["Không sao, miễn là bạn lái cẩn thận","Bạn chỉ bị cảnh cáo","Bạn phải thi viết lại","Bằng lái của bạn bị đình chỉ mà không có ngày kết thúc cố định"],"h1":"Kansas xem việc gián đoạn bảo hiểm là rất nghiêm trọng.","h2":"Ở Kansas, không duy trì liên tục bảo hiểm trách nhiệm cho xe sẽ dẫn đến đình chỉ bắt buộc mà không có ngày kết thúc cố định.","p":"Đúng. Gián đoạn bảo hiểm nghĩa là bị đình chỉ vô thời hạn."},"tl":{"q":"Sa Kansas, ano ang mangyayari kung hindi ka laging may liability insurance sa sasakyan mo?","o":["Wala, basta maingat kang magmaneho","Babala lang ang makukuha mo","Kailangan mong kumuha ulit ng written test","Masu-suspend ang lisensya mo nang walang takdang petsa ng pagtatapos"],"h1":"Napakaseryoso ng tingin ng Kansas sa pagkawala ng insurance kahit sandali.","h2":"Sa Kansas, kapag hindi tuloy-tuloy ang liability insurance sa sasakyan mo, sapilitang masu-suspend ang lisensya mo nang walang takdang petsa ng pagtatapos.","p":"Tama. Ang pagkawala ng insurance ay nangangahulugan ng suspensyong walang takdang katapusan."},"ar":{"q":"في Kansas، ماذا يحدث إذا لم تحتفظ بتأمين المسؤولية على سيارتك في كل الأوقات؟","o":["لا شيء، ما دمت تقود بحذر","تحصل على تحذير فقط","يجب أن تعيد الاختبار الكتابي","تُعلَّق رخصتك دون تاريخ محدد لانتهاء التعليق"],"h1":"تتعامل Kansas بجدية كبيرة مع أي انقطاع في التأمين.","h2":"في Kansas، عدم الاحتفاظ بتأمين مسؤولية مستمر على سيارتك يؤدي إلى تعليق إلزامي للرخصة دون تاريخ محدد لانتهائه.","p":"صحيح. انقطاع التأمين يعني تعليقًا لمدة غير محددة."},"ref":{"doc":"KS","page":14}},{"id":"ks-039","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, what happens after a fifth test result of .08 or more, or a fifth refusal to be tested?","o":["A 90-day suspension","The license is revoked for life","A fine only","A 1-year suspension"],"h1":"This is the most serious result possible.","h2":"In Kansas, a fifth test result of .08 or higher, or a fifth test refusal, means permanent loss of your license.","p":"Right. The fifth time, the license is revoked for good."},"es":{"q":"En Kansas, ¿qué pasa después de un quinto resultado de prueba de .08 o más, o una quinta negativa a hacerse la prueba?","o":["Una suspensión de 90 días","La licencia se revoca de por vida","Solo una multa","Una suspensión de 1 año"],"h1":"Es el resultado más grave posible.","h2":"En Kansas, un quinto resultado de .08 o más, o una quinta negativa a la prueba, significa la pérdida permanente de su licencia.","p":"Correcto. La quinta vez, la licencia se revoca para siempre."},"zh":{"q":"在 Kansas，第五次检测结果达到 .08 或以上，或者第五次拒绝检测后，会发生什么？","o":["暂停驾照 90 天","驾照被终身吊销","只罚款","暂停驾照 1 年"],"h1":"这是最严重的结果。","h2":"在 Kansas，第五次检测结果达到 .08 或以上，或者第五次拒绝检测，你将永久失去驾照。","p":"对。第五次时，驾照会被永久吊销。"},"vi":{"q":"Ở Kansas, điều gì xảy ra sau lần thứ năm có kết quả kiểm tra từ .08 trở lên, hoặc lần thứ năm từ chối kiểm tra?","o":["Đình chỉ 90 ngày","Bằng lái bị thu hồi suốt đời","Chỉ bị phạt tiền","Đình chỉ 1 năm"],"h1":"Đây là hậu quả nặng nhất có thể.","h2":"Ở Kansas, lần thứ năm có kết quả kiểm tra từ .08 trở lên, hoặc lần thứ năm từ chối kiểm tra, nghĩa là bạn mất bằng lái vĩnh viễn.","p":"Đúng. Đến lần thứ năm, bằng lái bị thu hồi vĩnh viễn."},"tl":{"q":"Sa Kansas, ano ang mangyayari pagkatapos ng ikalimang test result na .08 o higit pa, o ikalimang pagtanggi na magpa-test?","o":["Suspensyon nang 90 araw","Habambuhay na revoke ang lisensya","Multa lang","Suspensyon nang 1 taon"],"h1":"Ito ang pinakamabigat na posibleng resulta.","h2":"Sa Kansas, ang ikalimang test result na .08 o higit pa, o ang ikalimang pagtanggi sa test, ay nangangahulugan ng permanenteng pagkawala ng lisensya mo.","p":"Tama. Sa ikalimang beses, permanenteng revoke ang lisensya."},"ar":{"q":"في Kansas، ماذا يحدث بعد نتيجة فحص خامسة تبلغ .08 أو أكثر، أو بعد الرفض الخامس لإجراء الفحص؟","o":["تعليق لمدة 90 يومًا","سحب الرخصة مدى الحياة","غرامة فقط","تعليق لمدة سنة واحدة"],"h1":"هذه أخطر نتيجة ممكنة.","h2":"في Kansas، نتيجة الفحص الخامسة البالغة .08 أو أكثر، أو الرفض الخامس لإجراء الفحص، تعني أنك تفقد رخصتك بشكل دائم.","p":"صحيح. في المرة الخامسة، تُسحب الرخصة نهائيًا."},"ref":{"doc":"KS","page":15}},{"id":"ks-040","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, what is the fine for a first conviction of driving under the influence?","o":["$100 to $250","$300 to $500","$750 to $1,000","$2,500 to $5,000"],"h1":"Court costs are added on top of this fine.","h2":"In Kansas, a first DUI conviction carries a fine of $750 to $1,000, plus court costs.","p":"Right. A first DUI costs $750 to $1,000 in fines."},"es":{"q":"En Kansas, ¿cuál es la multa por una primera condena por manejar bajo los efectos del alcohol o las drogas?","o":["De $100 a $250","De $300 a $500","De $750 a $1,000","De $2,500 a $5,000"],"h1":"A esta multa se le suman los costos del tribunal.","h2":"En Kansas, una primera condena por DUI tiene una multa de $750 a $1,000, más los costos del tribunal.","p":"Correcto. Un primer DUI cuesta de $750 a $1,000 de multa."},"zh":{"q":"在 Kansas，第一次酒后或药后驾驶（DUI）定罪的罚款是多少？","o":["$100 到 $250","$300 到 $500","$750 到 $1,000","$2,500 到 $5,000"],"h1":"除了这笔罚款，还要另付法庭费用。","h2":"在 Kansas，第一次 DUI 定罪的罚款是 $750 到 $1,000，另加法庭费用。","p":"对。第一次 DUI 罚款 $750 到 $1,000。"},"vi":{"q":"Ở Kansas, tiền phạt cho lần đầu bị kết án lái xe khi say rượu hoặc dùng chất kích thích (DUI) là bao nhiêu?","o":["$100 đến $250","$300 đến $500","$750 đến $1,000","$2,500 đến $5,000"],"h1":"Án phí của tòa được cộng thêm vào tiền phạt này.","h2":"Ở Kansas, lần đầu bị kết án DUI sẽ bị phạt từ $750 đến $1,000, cộng thêm án phí của tòa.","p":"Đúng. Lần đầu DUI bị phạt $750 đến $1,000."},"tl":{"q":"Sa Kansas, magkano ang multa sa unang conviction sa pagmamaneho nang lasing o lango (DUI)?","o":["$100 hanggang $250","$300 hanggang $500","$750 hanggang $1,000","$2,500 hanggang $5,000"],"h1":"Dinadagdag pa ang court costs sa multang ito.","h2":"Sa Kansas, ang unang DUI conviction ay may multang $750 hanggang $1,000, dagdag pa ang court costs.","p":"Tama. $750 hanggang $1,000 ang multa sa unang DUI."},"ar":{"q":"في Kansas، ما الغرامة على أول إدانة بالقيادة تحت تأثير الكحول أو المخدرات (DUI)؟","o":["من $100 إلى $250","من $300 إلى $500","من $750 إلى $1,000","من $2,500 إلى $5,000"],"h1":"تُضاف رسوم المحكمة فوق هذه الغرامة.","h2":"في Kansas، تكون غرامة أول إدانة DUI من $750 إلى $1,000، إضافة إلى رسوم المحكمة.","p":"صحيح. غرامة أول DUI من $750 إلى $1,000."},"ref":{"doc":"KS","page":24}},{"id":"ks-041","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, what is the speed limit in an urban district when no other limit is posted?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"It is the default limit for streets in towns and cities.","h2":"In Kansas, the speed limit in any urban district is 30 mph unless another limit is posted.","p":"Right. In town, the limit is 30 mph unless posted otherwise."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en una zona urbana cuando no hay otro límite indicado?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"Es el límite normal para las calles de pueblos y ciudades.","h2":"En Kansas, el límite de velocidad en cualquier zona urbana es de 30 mph, a menos que se indique otro límite.","p":"Correcto. En la ciudad, el límite es de 30 mph si no se indica otro."},"zh":{"q":"在 Kansas，城区在没有张贴其他限速时，限速是多少？","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"这是城镇街道的默认限速。","h2":"在 Kansas，任何城区的限速都是 30 mph，除非张贴了其他限速。","p":"对。在城镇里，除非另有标示，限速是 30 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa trong khu vực đô thị là bao nhiêu khi không có biển báo giới hạn khác?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"Đó là giới hạn mặc định cho đường phố trong thị trấn và thành phố.","h2":"Ở Kansas, tốc độ tối đa trong mọi khu vực đô thị là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Trong thị trấn, giới hạn là 30 mph trừ khi có biển báo khác."},"tl":{"q":"Sa Kansas, ano ang speed limit sa urban district kapag walang ibang limit na nakapaskil?","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"Ito ang default na limit sa mga kalye sa mga bayan at lungsod.","h2":"Sa Kansas, 30 mph ang speed limit sa anumang urban district maliban kung may ibang limit na nakapaskil.","p":"Tama. Sa bayan, 30 mph ang limit maliban kung iba ang nakapaskil."},"ar":{"q":"في Kansas، ما حد السرعة في المنطقة الحضرية عندما لا تكون هناك لافتة بحد آخر؟","o":["30 mph","20 mph","40 mph","45 mph"],"h1":"إنه الحد المعتاد لشوارع البلدات والمدن.","h2":"في Kansas، حد السرعة في أي منطقة حضرية هو 30 mph ما لم تكن هناك لافتة بحد آخر.","p":"صحيح. داخل المدينة، الحد هو 30 mph ما لم تقل لافتة غير ذلك."},"ref":{"doc":"KS","page":16}},{"id":"ks-042","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, what is the speed limit on a state or federal highway when no other limit is posted?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"It is higher than on county roads but lower than on posted divided highways.","h2":"In Kansas, the speed limit on a state or federal highway is 65 mph unless another limit is posted.","p":"Right. State and federal highways are 65 mph."},"es":{"q":"En Kansas, ¿cuál es el límite de velocidad en una carretera estatal o federal cuando no hay otro límite indicado?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"Es más alto que en los caminos del condado, pero más bajo que en las autopistas divididas señalizadas.","h2":"En Kansas, el límite de velocidad en una carretera estatal o federal es de 65 mph, a menos que se indique otro límite.","p":"Correcto. Las carreteras estatales y federales son de 65 mph."},"zh":{"q":"在 Kansas，州公路或联邦公路在没有张贴其他限速时，限速是多少？","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"它比县道的限速高，但比有标示的分隔公路低。","h2":"在 Kansas，州公路或联邦公路的限速是 65 mph，除非张贴了其他限速。","p":"对。州公路和联邦公路限速 65 mph。"},"vi":{"q":"Ở Kansas, tốc độ tối đa trên xa lộ tiểu bang hoặc liên bang là bao nhiêu khi không có biển báo giới hạn khác?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"Nó cao hơn so với đường quận nhưng thấp hơn so với xa lộ có dải phân cách có biển báo.","h2":"Ở Kansas, tốc độ tối đa trên xa lộ tiểu bang hoặc liên bang là 65 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Xa lộ tiểu bang và liên bang là 65 mph."},"tl":{"q":"Sa Kansas, ano ang speed limit sa state o federal highway kapag walang ibang limit na nakapaskil?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"Mas mataas ito kaysa sa mga county road pero mas mababa kaysa sa mga divided highway na may nakapaskil na limit.","h2":"Sa Kansas, 65 mph ang speed limit sa state o federal highway maliban kung may ibang limit na nakapaskil.","p":"Tama. 65 mph sa mga state at federal highway."},"ar":{"q":"في Kansas، ما حد السرعة على طريق سريع تابع للولاية أو فيدرالي عندما لا تكون هناك لافتة بحد آخر؟","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"إنه أعلى من حد طرق المقاطعات، لكنه أقل من حد الطرق السريعة المقسومة التي عليها لافتات.","h2":"في Kansas، حد السرعة على الطريق السريع التابع للولاية أو الفيدرالي هو 65 mph ما لم تكن هناك لافتة بحد آخر.","p":"صحيح. الطرق السريعة التابعة للولاية والفيدرالية حدها 65 mph."},"ref":{"doc":"KS","page":16}},{"id":"ks-043","scope":"KS","cat":"signals","sign":null,"c":1,"en":{"q":"In Kansas, at least how far before a turn must you start to signal?","o":["25 feet","100 feet","50 feet","500 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Kansas, you must give your signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Kansas, ¿al menos a qué distancia antes de girar debe empezar a señalar?","o":["25 pies","100 pies","50 pies","500 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"En Kansas, usted debe hacer la señal al menos 100 pies antes de girar.","p":"Correcto. Señale al menos 100 pies antes."},"zh":{"q":"在 Kansas，转弯前至少要提前多远开始打转向灯？","o":["25 英尺","100 英尺","50 英尺","500 英尺"],"h1":"大约是六七辆车的长度。","h2":"在 Kansas，你必须在转弯前至少 100 英尺打转向灯。","p":"对。至少提前 100 英尺打灯。"},"vi":{"q":"Ở Kansas, bạn phải bắt đầu bật đèn xi nhan ít nhất bao xa trước khi rẽ?","o":["25 feet","100 feet","50 feet","500 feet"],"h1":"Khoảng chiều dài của sáu hoặc bảy chiếc xe.","h2":"Ở Kansas, bạn phải bật đèn xi nhan ít nhất 100 feet trước khi rẽ.","p":"Đúng. Bật xi nhan ít nhất 100 feet trước."},"tl":{"q":"Sa Kansas, hindi bababa sa gaano kalayo bago lumiko dapat kang magsimulang mag-signal?","o":["25 talampakan","100 talampakan","50 talampakan","500 talampakan"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Kansas, dapat kang mag-signal nang hindi bababa sa 100 talampakan bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 100 talampakan bago lumiko."},"ar":{"q":"في Kansas، قبل المنعطف بمسافة لا تقل عن كم يجب أن تبدأ بإعطاء الإشارة؟","o":["25 قدمًا","100 قدم","50 قدمًا","500 قدم"],"h1":"إنها تقريبًا طول ست أو سبع سيارات.","h2":"في Kansas، يجب أن تعطي الإشارة قبل 100 قدم على الأقل من المنعطف.","p":"صحيح. أعطِ الإشارة قبل 100 قدم على الأقل."},"ref":{"doc":"KS","page":17}},{"id":"ks-044","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, you may not make a U-turn where other drivers cannot see you from how far away?","o":["100 feet","200 feet","500 feet","50 feet"],"h1":"Think of a distance longer than a football field.","h2":"In Kansas, do not make a U-turn anywhere other drivers cannot see you from at least 500 feet away.","p":"Right. You need to be visible for 500 feet to make a U-turn."},"es":{"q":"En Kansas, no puede dar una vuelta en U donde los otros conductores no puedan verlo desde ¿qué distancia?","o":["100 pies","200 pies","500 pies","50 pies"],"h1":"Piense en una distancia más larga que un campo de fútbol americano.","h2":"En Kansas, no dé una vuelta en U en un lugar donde los otros conductores no puedan verlo desde al menos 500 pies.","p":"Correcto. Deben poder verlo a 500 pies para dar una vuelta en U."},"zh":{"q":"在 Kansas，如果其他司机在多远的距离内看不到你，你就不可以掉头（U-turn）？","o":["100 英尺","200 英尺","500 英尺","50 英尺"],"h1":"想一想比一个橄榄球场还长的距离。","h2":"在 Kansas，如果其他司机不能在至少 500 英尺外看到你，就不要在那里掉头。","p":"对。要掉头，其他司机必须能在 500 英尺外看到你。"},"vi":{"q":"Ở Kansas, bạn không được quay đầu xe (U-turn) ở nơi tài xế khác không thể thấy bạn từ khoảng cách bao xa?","o":["100 feet","200 feet","500 feet","50 feet"],"h1":"Hãy nghĩ đến một khoảng cách dài hơn một sân bóng bầu dục.","h2":"Ở Kansas, đừng quay đầu xe ở bất cứ nơi nào mà tài xế khác không thể thấy bạn từ cách xa ít nhất 500 feet.","p":"Đúng. Bạn cần được nhìn thấy từ 500 feet để quay đầu xe."},"tl":{"q":"Sa Kansas, hindi ka puwedeng mag-U-turn kung saan hindi ka makikita ng ibang driver mula sa gaano kalayo?","o":["100 talampakan","200 talampakan","500 talampakan","50 talampakan"],"h1":"Isipin ang distansyang mas mahaba pa sa isang football field.","h2":"Sa Kansas, huwag mag-U-turn kahit saan na hindi ka makikita ng ibang driver mula sa layong hindi bababa sa 500 talampakan.","p":"Tama. Kailangan kang makita mula sa 500 talampakan para makapag-U-turn."},"ar":{"q":"في Kansas، يجب ألّا تقوم بالدوران للخلف (U-turn) حيث لا يستطيع السائقون الآخرون رؤيتك من أي مسافة؟","o":["100 قدم","200 قدم","500 قدم","50 قدمًا"],"h1":"فكّر في مسافة أطول من ملعب كرة قدم أمريكية.","h2":"في Kansas، يجب ألّا تقوم بالدوران للخلف في أي مكان لا يستطيع فيه السائقون الآخرون رؤيتك من مسافة 500 قدم على الأقل.","p":"صحيح. يجب أن تكون مرئيًا من مسافة 500 قدم لتقوم بالدوران للخلف."},"ref":{"doc":"KS","page":17}},{"id":"ks-045","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, on a two-lane road, you may not pass within how many feet of an intersection or railroad crossing?","o":["100 feet","25 feet","50 feet","1,000 feet"],"h1":"The same distance applies near a bridge or tunnel when your view is blocked.","h2":"In Kansas, you may not pass within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Kansas, en un camino de dos carriles, ¿a cuántos pies de una intersección o un cruce de ferrocarril no puede rebasar?","o":["100 pies","25 pies","50 pies","1,000 pies"],"h1":"La misma distancia se aplica cerca de un puente o túnel cuando no se ve bien.","h2":"En Kansas, usted no puede rebasar a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de una intersección o un cruce de tren."},"zh":{"q":"在 Kansas，在双车道道路上，距离路口或铁路道口多少英尺以内不可以超车？","o":["100 英尺","25 英尺","50 英尺","1,000 英尺"],"h1":"在视线被挡住时，桥梁或隧道附近也适用同样的距离。","h2":"在 Kansas，你不可以在距离路口或铁路道口 100 英尺以内超车。","p":"对。路口或铁路道口 100 英尺以内不可以超车。"},"vi":{"q":"Ở Kansas, trên đường hai làn xe, bạn không được vượt xe trong phạm vi bao nhiêu feet tính từ giao lộ hoặc chỗ băng qua đường ray xe lửa?","o":["100 feet","25 feet","50 feet","1,000 feet"],"h1":"Khoảng cách này cũng áp dụng gần cầu hoặc đường hầm khi tầm nhìn của bạn bị che khuất.","h2":"Ở Kansas, bạn không được vượt xe trong phạm vi 100 feet tính từ giao lộ hoặc chỗ băng qua đường ray xe lửa.","p":"Đúng. Không vượt xe trong phạm vi 100 feet tính từ giao lộ hoặc đường ray xe lửa."},"tl":{"q":"Sa Kansas, sa daang may dalawang lane, hindi ka puwedeng mag-overtake sa loob ng ilang talampakan mula sa intersection o railroad crossing?","o":["100 talampakan","25 talampakan","50 talampakan","1,000 talampakan"],"h1":"Pareho ang distansya malapit sa tulay o tunnel kapag may nakaharang sa tanaw mo.","h2":"Sa Kansas, hindi ka puwedeng mag-overtake sa loob ng 100 talampakan mula sa intersection o railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 talampakan mula sa intersection o railroad crossing."},"ar":{"q":"في Kansas، على طريق ذي مسارين، يجب ألّا تتجاوز ضمن كم قدمًا من تقاطع أو معبر سكة حديد؟","o":["100 قدم","25 قدمًا","50 قدمًا","1,000 قدم"],"h1":"تنطبق المسافة نفسها قرب جسر أو نفق عندما تكون رؤيتك محجوبة.","h2":"في Kansas، يجب ألّا تتجاوز ضمن مسافة 100 قدم من تقاطع أو معبر سكة حديد.","p":"صحيح. لا تجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديد."},"ref":{"doc":"KS","page":17}},{"id":"ks-046","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, when you pass on a two-lane road, you must be back in your lane before you come within what distance of an oncoming vehicle?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"It is twice the distance you signal before a turn.","h2":"In Kansas, you must return to your own lane before you come within 200 feet of a vehicle coming toward you.","p":"Right. Be back in your lane before you are 200 feet from oncoming traffic."},"es":{"q":"En Kansas, cuando rebasa en un camino de dos carriles, ¿antes de qué distancia de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","100 pies","1,000 pies","200 pies"],"h1":"Es el doble de la distancia a la que señala antes de girar.","h2":"En Kansas, usted debe volver a su carril antes de llegar a 200 pies de un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril antes de estar a 200 pies del tráfico que viene de frente."},"zh":{"q":"在 Kansas，在双车道道路上超车时，你必须在离对面来车多远之前回到自己的车道？","o":["50 英尺","100 英尺","1,000 英尺","200 英尺"],"h1":"这是转弯前打灯距离的两倍。","h2":"在 Kansas，你必须在离对面来车 200 英尺之前回到自己的车道。","p":"对。在离对面来车 200 英尺之前回到你的车道。"},"vi":{"q":"Ở Kansas, khi vượt xe trên đường hai làn xe, bạn phải trở về làn của mình trước khi cách xe chạy ngược chiều bao xa?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"Gấp đôi khoảng cách bạn bật xi nhan trước khi rẽ.","h2":"Ở Kansas, bạn phải trở về làn của mình trước khi cách xe chạy ngược chiều 200 feet.","p":"Đúng. Trở về làn của bạn trước khi cách xe ngược chiều 200 feet."},"tl":{"q":"Sa Kansas, kapag nag-overtake ka sa daang may dalawang lane, dapat nakabalik ka na sa lane mo bago ka umabot sa anong layo mula sa paparating na sasakyan?","o":["50 talampakan","100 talampakan","1,000 talampakan","200 talampakan"],"h1":"Doble ito ng distansya ng pag-signal mo bago lumiko.","h2":"Sa Kansas, dapat kang bumalik sa sarili mong lane bago ka umabot sa 200 talampakan mula sa sasakyang papunta sa iyo.","p":"Tama. Bumalik sa lane mo bago ka umabot sa 200 talampakan mula sa paparating na sasakyan."},"ar":{"q":"في Kansas، عندما تتجاوز على طريق ذي مسارين، يجب أن تعود إلى مسارك قبل أن تصل إلى أي مسافة من سيارة قادمة نحوك؟","o":["50 قدمًا","100 قدم","1,000 قدم","200 قدم"],"h1":"إنها ضعف المسافة التي تعطي فيها الإشارة قبل المنعطف.","h2":"في Kansas، يجب أن تعود إلى مسارك قبل أن تصبح على بُعد 200 قدم من سيارة قادمة نحوك.","p":"صحيح. عُد إلى مسارك قبل أن تصبح على بُعد 200 قدم من السيارات القادمة."},"ref":{"doc":"KS","page":17}},{"id":"ks-047","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, how must a child under 4 years old ride in a car?","o":["In a regular seat belt","In a federally approved child safety seat","On an adult's lap in the back seat","In a booster seat with a lap belt only"],"h1":"The youngest children need the most protection.","h2":"In Kansas, every child under 4 must ride in a federally approved child safety seat.","p":"Right. Children under 4 ride in an approved child safety seat."},"es":{"q":"En Kansas, ¿cómo debe viajar en el carro un niño menor de 4 años?","o":["Con un cinturón de seguridad normal","En un asiento de seguridad infantil aprobado por el gobierno federal","En las piernas de un adulto en el asiento trasero","En un asiento elevado solo con cinturón de cadera"],"h1":"Los niños más pequeños necesitan la mayor protección.","h2":"En Kansas, todo niño menor de 4 años debe viajar en un asiento de seguridad infantil aprobado por el gobierno federal.","p":"Correcto. Los menores de 4 años viajan en un asiento infantil aprobado."},"zh":{"q":"在 Kansas，4 岁以下的儿童坐车时必须怎样乘坐？","o":["系普通安全带","坐在联邦认可的儿童安全座椅里","坐在后座大人的腿上","坐在只用腰部安全带的增高座椅上"],"h1":"年龄最小的孩子需要最多的保护。","h2":"在 Kansas，每个 4 岁以下的儿童都必须坐在联邦认可的儿童安全座椅里。","p":"对。4 岁以下的儿童要坐认可的儿童安全座椅。"},"vi":{"q":"Ở Kansas, trẻ em dưới 4 tuổi phải ngồi trong xe như thế nào?","o":["Thắt dây an toàn thông thường","Ngồi trong ghế an toàn trẻ em được liên bang chấp thuận","Ngồi trên đùi người lớn ở ghế sau","Ngồi ghế nâng chỉ với dây an toàn ngang hông"],"h1":"Trẻ nhỏ nhất cần được bảo vệ nhiều nhất.","h2":"Ở Kansas, mọi trẻ em dưới 4 tuổi phải ngồi trong ghế an toàn trẻ em được liên bang chấp thuận.","p":"Đúng. Trẻ dưới 4 tuổi ngồi ghế an toàn trẻ em được chấp thuận."},"tl":{"q":"Sa Kansas, paano dapat sumakay sa kotse ang batang wala pang 4 na taong gulang?","o":["Naka-regular na seat belt","Nasa child safety seat na aprubado ng federal government","Nasa kandungan ng adult sa likurang upuan","Nasa booster seat na may lap belt lang"],"h1":"Ang pinakabatang mga bata ang nangangailangan ng pinakamaraming proteksyon.","h2":"Sa Kansas, dapat nakasakay ang bawat batang wala pang 4 na taong gulang sa child safety seat na aprubado ng federal government.","p":"Tama. Sa aprubadong child safety seat sumasakay ang mga batang wala pang 4."},"ar":{"q":"في Kansas، كيف يجب أن يركب الطفل الذي عمره أقل من 4 سنوات في السيارة؟","o":["بحزام أمان عادي","في مقعد أمان للأطفال معتمد فيدراليًا","في حضن شخص بالغ في المقعد الخلفي","في مقعد رافع مع حزام حضن فقط"],"h1":"الأطفال الأصغر سنًا يحتاجون إلى أكبر قدر من الحماية.","h2":"في Kansas، يجب أن يركب كل طفل عمره أقل من 4 سنوات في مقعد أمان للأطفال معتمد فيدراليًا.","p":"صحيح. الأطفال الأقل من 4 سنوات يركبون في مقعد أمان معتمد للأطفال."},"ref":{"doc":"KS","page":16}},{"id":"ks-048","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 25 feet","No closer than 50 feet","No closer than 15 feet"],"h1":"It is more than three times the distance you keep from a fire hydrant.","h2":"In Kansas, you may not park within 50 feet of the nearest rail at a railroad crossing.","p":"Right. Park at least 50 feet from the tracks."},"es":{"q":"En Kansas, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 15 pies"],"h1":"Es más de tres veces la distancia que debe dejar de un hidrante.","h2":"En Kansas, usted no puede estacionarse a menos de 50 pies del riel más cercano en un cruce de ferrocarril.","p":"Correcto. Estaciónese al menos a 50 pies de las vías."},"zh":{"q":"在 Kansas，你停车时离铁路道口最近的铁轨可以多近？","o":["不能近于 10 英尺","不能近于 25 英尺","不能近于 50 英尺","不能近于 15 英尺"],"h1":"这是你与消防栓保持距离的三倍多。","h2":"在 Kansas，你不可以在铁路道口最近铁轨 50 英尺以内停车。","p":"对。停车要离铁轨至少 50 英尺。"},"vi":{"q":"Ở Kansas, bạn được đậu xe gần đường ray gần nhất của chỗ băng qua đường xe lửa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 15 feet"],"h1":"Đó là hơn ba lần khoảng cách bạn giữ với trụ nước cứu hỏa.","h2":"Ở Kansas, bạn không được đậu xe trong phạm vi 50 feet tính từ đường ray gần nhất tại chỗ băng qua đường xe lửa.","p":"Đúng. Đậu xe cách đường ray ít nhất 50 feet."},"tl":{"q":"Sa Kansas, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng mag-park?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan","Hindi lalapit sa 15 talampakan"],"h1":"Mahigit tatlong beses ito ng layong pinapanatili mo mula sa fire hydrant.","h2":"Sa Kansas, hindi ka puwedeng mag-park sa loob ng 50 talampakan mula sa pinakamalapit na riles sa railroad crossing.","p":"Tama. Mag-park nang hindi bababa sa 50 talampakan mula sa riles."},"ar":{"q":"في Kansas، إلى أي حد يمكنك أن تركن قرب أقرب سكة في معبر سكة الحديد؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 15 قدمًا"],"h1":"إنها أكثر من ثلاثة أضعاف المسافة التي تتركها بعيدًا عن حنفية الإطفاء.","h2":"في Kansas، يجب ألّا تركن ضمن مسافة 50 قدمًا من أقرب سكة في معبر سكة الحديد.","p":"صحيح. اركن على بُعد 50 قدمًا على الأقل من السكة."},"ref":{"doc":"KS","page":19}},{"id":"ks-049","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, what does the law forbid every driver to do with a phone while driving?","o":["Write, send or read texts or emails","Use a GPS map","Listen to a weather report","Have a phone in the car"],"h1":"The law is about written messages.","h2":"In Kansas, no driver may use a phone or other device to write, send or read texts, emails or other written messages while driving.","p":"Right. Texting and email are against the law while driving."},"es":{"q":"En Kansas, ¿qué prohíbe la ley a todos los conductores hacer con el teléfono mientras manejan?","o":["Escribir, enviar o leer mensajes de texto o correos","Usar un mapa GPS","Escuchar un reporte del clima","Tener un teléfono en el carro"],"h1":"La ley trata de los mensajes escritos.","h2":"En Kansas, ningún conductor puede usar un teléfono u otro aparato para escribir, enviar o leer mensajes de texto, correos u otros mensajes escritos mientras maneja.","p":"Correcto. Mandar textos y correos está prohibido mientras maneja."},"zh":{"q":"在 Kansas，法律禁止所有司机在开车时用手机做什么？","o":["写、发送或阅读短信或电子邮件","使用 GPS 地图","收听天气预报","车里放着手机"],"h1":"这条法律是关于文字信息的。","h2":"在 Kansas，任何司机在开车时都不可以用手机或其他设备写、发送或阅读短信、电子邮件或其他文字信息。","p":"对。开车时发短信和电子邮件是违法的。"},"vi":{"q":"Ở Kansas, luật cấm mọi tài xế làm gì với điện thoại khi đang lái xe?","o":["Viết, gửi hoặc đọc tin nhắn hoặc email","Dùng bản đồ GPS","Nghe bản tin thời tiết","Để điện thoại trong xe"],"h1":"Luật này nói về tin nhắn bằng chữ.","h2":"Ở Kansas, không tài xế nào được dùng điện thoại hoặc thiết bị khác để viết, gửi hoặc đọc tin nhắn, email hoặc tin nhắn bằng chữ khác khi đang lái xe.","p":"Đúng. Nhắn tin và email khi lái xe là phạm luật."},"tl":{"q":"Sa Kansas, ano ang ipinagbabawal ng batas sa bawat driver na gawin sa telepono habang nagmamaneho?","o":["Sumulat, magpadala o magbasa ng text o email","Gumamit ng GPS map","Makinig ng weather report","Magkaroon ng telepono sa kotse"],"h1":"Tungkol sa mga nakasulat na mensahe ang batas.","h2":"Sa Kansas, walang driver na puwedeng gumamit ng telepono o ibang device para sumulat, magpadala o magbasa ng text, email o ibang nakasulat na mensahe habang nagmamaneho.","p":"Tama. Labag sa batas ang pag-text at pag-email habang nagmamaneho."},"ar":{"q":"في Kansas، ماذا يمنع القانون كل سائق من فعله بالهاتف أثناء القيادة؟","o":["كتابة أو إرسال أو قراءة الرسائل النصية أو البريد الإلكتروني","استخدام خريطة GPS","الاستماع إلى نشرة الطقس","وجود هاتف في السيارة"],"h1":"القانون يتعلق بالرسائل المكتوبة.","h2":"في Kansas، يجب ألّا يستخدم أي سائق هاتفًا أو جهازًا آخر لكتابة أو إرسال أو قراءة الرسائل النصية أو البريد الإلكتروني أو أي رسائل مكتوبة أخرى أثناء القيادة.","p":"صحيح. الرسائل النصية والبريد الإلكتروني أثناء القيادة مخالفان للقانون."},"ref":{"doc":"KS","page":19}},{"id":"ks-050","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, when must you turn on your headlights during the day?","o":["Only on Interstate highways","Only when you drive faster than 55 mph","Only inside tunnels","Whenever your windshield wipers are in use"],"h1":"Think about rain, sleet and snow.","h2":"In Kansas, you must turn on your headlights whenever you use your windshield wipers.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Kansas, ¿cuándo debe encender los faros durante el día?","o":["Solo en las autopistas interestatales","Solo cuando maneje a más de 55 mph","Solo dentro de los túneles","Siempre que use los limpiaparabrisas"],"h1":"Piense en la lluvia, el aguanieve y la nieve.","h2":"En Kansas, usted debe encender los faros siempre que use los limpiaparabrisas.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 Kansas，白天什么时候必须打开前灯？","o":["只在州际公路上","只在车速超过 55 mph 时","只在隧道里","每当你使用挡风玻璃雨刷时"],"h1":"想一想下雨、雨夹雪和下雪的时候。","h2":"在 Kansas，每当你使用挡风玻璃雨刷时，都必须打开前灯。","p":"对。开雨刷就要开前灯。"},"vi":{"q":"Ở Kansas, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ liên tiểu bang","Chỉ khi bạn lái nhanh hơn 55 mph","Chỉ trong đường hầm","Bất cứ khi nào bạn dùng cần gạt nước kính chắn gió"],"h1":"Hãy nghĩ đến mưa, mưa tuyết và tuyết.","h2":"Ở Kansas, bạn phải bật đèn pha bất cứ khi nào bạn dùng cần gạt nước kính chắn gió.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Kansas, kailan mo dapat buksan ang headlights mo sa araw?","o":["Sa Interstate highway lang","Kapag mas mabilis ka lang sa 55 mph","Sa loob lang ng tunnel","Tuwing ginagamit mo ang windshield wipers"],"h1":"Isipin ang ulan, sleet at niyebe.","h2":"Sa Kansas, dapat mong buksan ang headlights mo tuwing ginagamit mo ang windshield wipers.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Kansas، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["فقط على الطرق السريعة بين الولايات (Interstate)","فقط عندما تقود أسرع من 55 mph","فقط داخل الأنفاق","كلما استخدمت ماسحات الزجاج الأمامي"],"h1":"فكّر في المطر والمطر المتجمّد والثلج.","h2":"في Kansas، يجب أن تشغّل المصابيح الأمامية كلما استخدمت ماسحات الزجاج الأمامي.","p":"صحيح. عندما تعمل الماسحات، تعمل المصابيح الأمامية."},"ref":{"doc":"KS","page":67}},{"id":"ks-051","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, during which months may vehicles use studded snow tires?","o":["From September 1 to May 1","From November 1 to April 1","From December 1 to March 1","All year round"],"h1":"The season starts in late fall and ends in early spring.","h2":"In Kansas, vehicles may use studded snow tires from November 1 to April 1 each year.","p":"Right. Studded tires are allowed from November 1 to April 1."},"es":{"q":"En Kansas, ¿en qué meses pueden los vehículos usar llantas de nieve con clavos?","o":["Del 1 de septiembre al 1 de mayo","Del 1 de noviembre al 1 de abril","Del 1 de diciembre al 1 de marzo","Todo el año"],"h1":"La temporada empieza a fines del otoño y termina a principios de la primavera.","h2":"En Kansas, los vehículos pueden usar llantas de nieve con clavos del 1 de noviembre al 1 de abril de cada año.","p":"Correcto. Las llantas con clavos se permiten del 1 de noviembre al 1 de abril."},"zh":{"q":"在 Kansas，车辆在哪几个月可以使用带钉雪地轮胎？","o":["从 9 月 1 日到 5 月 1 日","从 11 月 1 日到 4 月 1 日","从 12 月 1 日到 3 月 1 日","全年都可以"],"h1":"这个季节从晚秋开始，到早春结束。","h2":"在 Kansas，车辆每年可以从 11 月 1 日到 4 月 1 日使用带钉雪地轮胎。","p":"对。带钉轮胎可以从 11 月 1 日用到 4 月 1 日。"},"vi":{"q":"Ở Kansas, xe được dùng lốp đinh đi tuyết trong những tháng nào?","o":["Từ ngày 1 tháng 9 đến ngày 1 tháng 5","Từ ngày 1 tháng 11 đến ngày 1 tháng 4","Từ ngày 1 tháng 12 đến ngày 1 tháng 3","Quanh năm"],"h1":"Mùa này bắt đầu vào cuối thu và kết thúc vào đầu xuân.","h2":"Ở Kansas, xe được dùng lốp đinh đi tuyết từ ngày 1 tháng 11 đến ngày 1 tháng 4 mỗi năm.","p":"Đúng. Lốp đinh được phép dùng từ ngày 1 tháng 11 đến ngày 1 tháng 4."},"tl":{"q":"Sa Kansas, sa anong mga buwan puwedeng gumamit ang mga sasakyan ng studded snow tires?","o":["Mula Setyembre 1 hanggang Mayo 1","Mula Nobyembre 1 hanggang Abril 1","Mula Disyembre 1 hanggang Marso 1","Buong taon"],"h1":"Nagsisimula ang panahong ito sa huling bahagi ng taglagas at natatapos sa simula ng tagsibol.","h2":"Sa Kansas, puwedeng gumamit ang mga sasakyan ng studded snow tires mula Nobyembre 1 hanggang Abril 1 bawat taon.","p":"Tama. Pinapayagan ang studded tires mula Nobyembre 1 hanggang Abril 1."},"ar":{"q":"في Kansas، في أي أشهر يمكن للسيارات استخدام إطارات الثلج ذات المسامير؟","o":["من 1 سبتمبر إلى 1 مايو","من 1 نوفمبر إلى 1 أبريل","من 1 ديسمبر إلى 1 مارس","طوال السنة"],"h1":"يبدأ الموسم في أواخر الخريف وينتهي في أوائل الربيع.","h2":"في Kansas، يمكن للسيارات استخدام إطارات الثلج ذات المسامير من 1 نوفمبر إلى 1 أبريل من كل سنة.","p":"صحيح. الإطارات ذات المسامير مسموحة من 1 نوفمبر إلى 1 أبريل."},"ref":{"doc":"KS","page":59}},{"id":"ks-052","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, which teens can apply for a farm permit?","o":["Teens aged 12 or 13","Teens aged 14 up to 17","Only teens aged 16 to 18","Only adults 18 and older"],"h1":"It starts at the same age as the regular instruction permit.","h2":"In Kansas, a farm permit is for teens who are at least 14 but not yet 17.","p":"Right. A Kansas farm permit is for ages 14 up to 17."},"es":{"q":"En Kansas, ¿qué jóvenes pueden solicitar un permiso agrícola (farm permit)?","o":["Jóvenes de 12 o 13 años","Jóvenes de 14 años hasta antes de los 17","Solo jóvenes de 16 a 18 años","Solo adultos de 18 años o más"],"h1":"Empieza a la misma edad que el permiso de instrucción normal.","h2":"En Kansas, el permiso agrícola es para jóvenes que tienen al menos 14 años pero todavía no cumplen 17.","p":"Correcto. El permiso agrícola de Kansas es para edades de 14 hasta antes de los 17."},"ref":{"doc":"KS","page":11}},{"id":"ks-053","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"For a Kansas farm permit, how large must the farm be?","o":["At least 5 acres","At least 10 acres","At least 20 acres","At least 40 acres"],"h1":"Think of a small field, bigger than ten acres.","h2":"For a Kansas farm permit, a farm means at least 20 acres used for agriculture.","p":"Right. The farm must be at least 20 acres."},"es":{"q":"Para un permiso agrícola de Kansas, ¿qué tamaño debe tener la granja?","o":["Al menos 5 acres","Al menos 10 acres","Al menos 20 acres","Al menos 40 acres"],"h1":"Piense en un campo pequeño, de más de diez acres.","h2":"Para un permiso agrícola de Kansas, una granja es un terreno de al menos 20 acres usado para la agricultura.","p":"Correcto. La granja debe tener al menos 20 acres."},"ref":{"doc":"KS","page":11}},{"id":"ks-054","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"A Kansas teen wants a farm permit because they are paid to work on a farm. Besides a parent, who must sign an affidavit?","o":["A school teacher","The county sheriff","A family doctor","The farm employer"],"h1":"Someone has to confirm the job is real.","h2":"In Kansas, if the teen is employed on a farm, the employer must sign an affidavit about that job, along with the parent or guardian.","p":"Right. The farm employer signs too."},"es":{"q":"Un joven de Kansas quiere un permiso agrícola porque le pagan por trabajar en una granja. Además de un padre, ¿quién debe firmar una declaración jurada?","o":["Un maestro de la escuela","El alguacil del condado","Un médico de la familia","El empleador de la granja"],"h1":"Alguien tiene que confirmar que el trabajo es real.","h2":"En Kansas, si el joven trabaja en una granja, el empleador debe firmar una declaración jurada sobre ese trabajo, junto con el padre o tutor.","p":"Correcto. El empleador de la granja también firma."},"ref":{"doc":"KS","page":11}},{"id":"ks-055","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, a 15-year-old with a farm permit wants to drive alone to an evening school dance. Is that allowed?","o":["No, school trips are only for attending classes","Yes, all school events are allowed","Yes, if the dance ends before 9 p.m.","Yes, if one friend rides along"],"h1":"The school trip rule is about going to class.","h2":"In Kansas, a 14- or 15-year-old with a farm permit may drive to and from school only to attend classes, not for school activities like a dance.","p":"Right. School activities are not covered at that age."},"es":{"q":"En Kansas, un joven de 15 años con permiso agrícola quiere manejar solo a un baile escolar por la noche. ¿Está permitido?","o":["No, los viajes a la escuela son solo para asistir a clases","Sí, se permiten todos los eventos escolares","Sí, si el baile termina antes de las 9 p.m.","Sí, si lo acompaña un amigo"],"h1":"La regla de la escuela se refiere a ir a clases.","h2":"En Kansas, un joven de 14 o 15 años con permiso agrícola puede manejar a la escuela y de regreso solo para asistir a clases, no para actividades escolares como un baile.","p":"Correcto. A esa edad no se cubren las actividades escolares."},"ref":{"doc":"KS","page":12}},{"id":"ks-056","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, when do all the age-based limits on a teen's restricted license end?","o":["As soon as the teen turns 16","At 16, once the restricted license has been held for 6 months","Only at age 18","After the teen finishes driver education"],"h1":"Both an age and a waiting time matter.","h2":"In Kansas, the age-based limits end once the driver is 16 and has held the restricted license for six months.","p":"Right. Age 16 plus six months with the license."},"es":{"q":"En Kansas, ¿cuándo terminan todos los límites por edad de la licencia restringida de un joven?","o":["En cuanto el joven cumple 16 años","A los 16, después de tener la licencia restringida por 6 meses","Solo a los 18 años","Cuando el joven termina la educación vial"],"h1":"Importan tanto la edad como un tiempo de espera.","h2":"En Kansas, los límites por edad terminan cuando el conductor tiene 16 años y ya tuvo la licencia restringida por seis meses.","p":"Correcto. 16 años más seis meses con la licencia."},"ref":{"doc":"KS","page":13}},{"id":"ks-057","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"A 14-year-old applies for a Kansas instruction permit. What must a parent or guardian do?","o":["Nothing, a teacher can sign for the teen","Take the same written test as the teen","Apply in writing and sign an affidavit","Pay a fine before the permit is issued"],"h1":"Under 16, the adult has paperwork to do.","h2":"In Kansas, a permit applicant under 16 needs a written application from a parent or guardian, who signs an affidavit at the licensing office.","p":"Right. The parent applies in writing and signs."},"es":{"q":"Un joven de 14 años solicita un permiso de instrucción en Kansas. ¿Qué debe hacer un padre o tutor?","o":["Nada, un maestro puede firmar por el joven","Tomar el mismo examen escrito que el joven","Solicitarlo por escrito y firmar una declaración jurada","Pagar una multa antes de que se emita el permiso"],"h1":"Antes de los 16 años, el adulto tiene trámites que hacer.","h2":"En Kansas, quien solicita el permiso antes de los 16 años necesita una solicitud por escrito de un padre o tutor, que firma una declaración jurada en la oficina de licencias.","p":"Correcto. El padre lo solicita por escrito y firma."},"ref":{"doc":"KS","page":12}},{"id":"ks-058","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how do you renew an instruction permit that is about to expire?","o":["Pay a fee online only","Take a new vision test only","Bring a letter from a parent","Pass the written test again"],"h1":"The permit was earned with a test.","h2":"In Kansas, every instruction permit is renewed by taking and passing the written test again.","p":"Right. You retake the written test."},"es":{"q":"En Kansas, ¿cómo se renueva un permiso de instrucción que está por vencer?","o":["Pagando una tarifa solo por internet","Tomando solo un nuevo examen de la vista","Llevando una carta de un padre","Aprobando otra vez el examen escrito"],"h1":"El permiso se ganó con un examen.","h2":"En Kansas, todo permiso de instrucción se renueva tomando y aprobando otra vez el examen escrito.","p":"Correcto. Se vuelve a tomar el examen escrito."},"ref":{"doc":"KS","page":14}},{"id":"ks-059","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, besides being at least 21, what else must the adult who supervises a permit driver have?","o":["At least one year of driving experience","A commercial license","A teaching certificate","At least ten years of driving experience"],"h1":"The adult needs some time behind the wheel, but not a lot.","h2":"In Kansas, the licensed adult supervising a permit driver must be at least 21 and have at least one year of driving experience.","p":"Right. At least one year of driving experience."},"es":{"q":"En Kansas, además de tener al menos 21 años, ¿qué más debe tener el adulto que supervisa a un conductor con permiso?","o":["Al menos un año de experiencia manejando","Una licencia comercial","Un certificado de maestro","Al menos diez años de experiencia manejando"],"h1":"El adulto necesita algo de tiempo al volante, pero no mucho.","h2":"En Kansas, el adulto con licencia que supervisa a un conductor con permiso debe tener al menos 21 años y al menos un año de experiencia manejando.","p":"Correcto. Al menos un año de experiencia manejando."},"ref":{"doc":"KS","page":12}},{"id":"ks-060","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, does the time you held a driver education permit slip (DE-99) count toward the one year with a permit needed for a restricted license?","o":["Yes, it counts double","No, only time with a state-issued permit counts","Yes, but only if it was over 6 months","Only for farm permits"],"h1":"The year must be on a permit the state issued.","h2":"In Kansas, the one year with a learner's permit must be on a state-issued permit; time on a driver education permit slip does not count.","p":"Right. Driver education slip time does not count."},"es":{"q":"En Kansas, ¿cuenta el tiempo con la hoja de permiso de educación vial (DE-99) para el año con permiso que se necesita para una licencia restringida?","o":["Sí, cuenta doble","No, solo cuenta el tiempo con un permiso emitido por el estado","Sí, pero solo si fue más de 6 meses","Solo para los permisos agrícolas"],"h1":"El año debe ser con un permiso que emitió el estado.","h2":"En Kansas, el año con permiso de aprendiz debe ser con un permiso emitido por el estado; el tiempo con la hoja de permiso de educación vial no cuenta.","p":"Correcto. El tiempo con la hoja de educación vial no cuenta."},"ref":{"doc":"KS","page":12}},{"id":"ks-061","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, what is the youngest age for a full Class C license with no teen restrictions?","o":["15","16","17","18"],"h1":"It is one year older than the restricted license at 16.","h2":"In Kansas, the minimum age for an unrestricted Class C driver's license is 17.","p":"Right. The unrestricted license starts at 17."},"es":{"q":"En Kansas, ¿cuál es la edad mínima para una licencia Clase C completa, sin restricciones para jóvenes?","o":["15","16","17","18"],"h1":"Es un año más que la licencia restringida de los 16.","h2":"En Kansas, la edad mínima para una licencia de conducir Clase C sin restricciones es 17 años.","p":"Correcto. La licencia sin restricciones empieza a los 17."},"ref":{"doc":"KS","page":13}},{"id":"ks-062","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how old must you be for a non-commercial Class A or B license?","o":["14","16","17","18"],"h1":"These licenses are for bigger vehicles, so you must be an adult.","h2":"In Kansas, you must be at least 18 years old for a non-commercial Class A or B license.","p":"Right. Non-commercial Class A or B starts at 18."},"es":{"q":"En Kansas, ¿qué edad necesita para una licencia no comercial Clase A o B?","o":["14","16","17","18"],"h1":"Estas licencias son para vehículos más grandes, así que debe ser adulto.","h2":"En Kansas, debe tener al menos 18 años para una licencia no comercial Clase A o B.","p":"Correcto. La Clase A o B no comercial empieza a los 18."},"ref":{"doc":"KS","page":9}},{"id":"ks-063","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, how old must you be for a commercial driver's license (CDL) to drive from state to state?","o":["18","19","21","25"],"h1":"Driving within Kansas only has a lower age.","h2":"In Kansas, you must be at least 21 for an interstate commercial license; 18 is enough for driving only within Kansas.","p":"Right. Interstate commercial driving starts at 21."},"es":{"q":"En Kansas, ¿qué edad necesita para una licencia comercial (CDL) para manejar de un estado a otro?","o":["18","19","21","25"],"h1":"Para manejar solo dentro de Kansas la edad es menor.","h2":"En Kansas, debe tener al menos 21 años para una licencia comercial interestatal; 18 bastan para manejar solo dentro de Kansas.","p":"Correcto. El manejo comercial interestatal empieza a los 21."},"ref":{"doc":"KS","page":9}},{"id":"ks-064","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, an approved private driver education school must offer at least how much instruction?","o":["8 hours in class and 6 hours behind the wheel","4 hours in class and 2 hours behind the wheel","20 hours online only","30 hours in class and no driving"],"h1":"There is class time and driving time, and the class time is a bit longer.","h2":"In Kansas, an approved private driver education school gives 8 hours of classroom teaching and 6 hours behind the wheel.","p":"Right. Eight hours in class and six behind the wheel."},"es":{"q":"En Kansas, ¿cuánta instrucción debe ofrecer como mínimo una escuela privada de educación vial aprobada?","o":["8 horas en clase y 6 horas al volante","4 horas en clase y 2 horas al volante","20 horas solo por internet","30 horas en clase y nada de manejo"],"h1":"Hay tiempo en clase y tiempo manejando, y el de clase es un poco más largo.","h2":"En Kansas, una escuela privada de educación vial aprobada da 8 horas de clase y 6 horas al volante.","p":"Correcto. Ocho horas en clase y seis al volante."},"ref":{"doc":"KS","page":9}},{"id":"ks-065","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, besides a driver's license office, where can you take the non-commercial knowledge test?","o":["At any local police station","Online, on the state's KnowToDrive site","At any car dealership in Kansas","By phone with a state examiner"],"h1":"The state offers a way to do it from home.","h2":"In Kansas, you can take the non-commercial knowledge test online at ks.knowtodrive.com and bring your passing results to the office.","p":"Right. The test can be taken online."},"es":{"q":"En Kansas, además de una oficina de licencias, ¿dónde puede tomar el examen de conocimientos no comercial?","o":["En cualquier estación de policía local","Por internet, en el sitio KnowToDrive del estado","En cualquier concesionario de autos de Kansas","Por teléfono con un examinador del estado"],"h1":"El estado ofrece una forma de hacerlo desde casa.","h2":"En Kansas, puede tomar el examen de conocimientos no comercial por internet en ks.knowtodrive.com y llevar su resultado aprobado a la oficina.","p":"Correcto. El examen se puede tomar por internet."},"ref":{"doc":"KS","page":9}},{"id":"ks-066","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, which of these can keep you from getting a driver's license?","o":["Owning an older car with high mileage","Living in a small rural town","Not owning a car of your own yet","Unpaid fines for moving violations"],"h1":"Think about tickets you have not settled.","h2":"In Kansas, you cannot get a driver's license while you have unpaid fines for moving traffic violations.","p":"Right. Unpaid moving-violation fines block a license."},"es":{"q":"En Kansas, ¿cuál de estas cosas puede impedirle obtener una licencia de conducir?","o":["Tener un auto viejo con muchas millas","Vivir en un pueblo rural pequeño","No tener todavía un auto propio","Multas sin pagar por infracciones de tránsito"],"h1":"Piense en multas que no ha pagado.","h2":"En Kansas, no puede obtener una licencia de conducir mientras tenga multas sin pagar por infracciones de tránsito en movimiento.","p":"Correcto. Las multas sin pagar impiden la licencia."},"ref":{"doc":"KS","page":11}},{"id":"ks-067","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"You are getting a Kansas driver's license. What must you do with any license or ID card you had before?","o":["Turn it in","Keep it as a spare","Mail it to your old state yourself","Cut it up at home"],"h1":"You can only hold one at a time.","h2":"In Kansas, you must turn in any driver's license or ID card you held before when you get your Kansas license.","p":"Right. You turn in the old card."},"es":{"q":"Usted está sacando una licencia de conducir de Kansas. ¿Qué debe hacer con cualquier licencia o tarjeta de identificación que tenía antes?","o":["Entregarla","Guardarla como repuesto","Enviarla usted mismo a su estado anterior","Cortarla en casa"],"h1":"Solo puede tener una a la vez.","h2":"En Kansas, debe entregar cualquier licencia o tarjeta de identificación que tenía antes cuando recibe su licencia de Kansas.","p":"Correcto. Se entrega la tarjeta anterior."},"ref":{"doc":"KS","page":11}},{"id":"ks-068","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, you pass the vision screening only with your glasses on. What happens?","o":["You must retake the vision test every year","Nothing changes, since glasses are optional","You get a restriction to wear them when driving","You may drive only during daylight hours"],"h1":"The license will show you need them.","h2":"In Kansas, if you need corrective lenses to pass, your license is restricted and you must wear them any time you drive.","p":"Right. You must wear them every time you drive."},"es":{"q":"En Kansas, usted pasa el examen de la vista solo con sus anteojos puestos. ¿Qué pasa?","o":["Debe repetir el examen de la vista cada año","Nada cambia, porque los anteojos son opcionales","Le ponen una restricción de usarlos al manejar","Solo puede manejar durante el día"],"h1":"La licencia mostrará que los necesita.","h2":"En Kansas, si necesita lentes correctivos para aprobar, su licencia queda restringida y debe usarlos cada vez que maneje.","p":"Correcto. Debe usarlos cada vez que maneje."},"ref":{"doc":"KS","page":13}},{"id":"ks-069","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, you do not pass the vision screening. An eye doctor fills out the state's eye form. How soon after the eye exam must you return it?","o":["Within 10 days","Within 90 days","Within 1 year","There is no time limit"],"h1":"It is about three months.","h2":"In Kansas, the eye examination form from an ophthalmologist or optometrist must be returned within 90 days of the eye exam.","p":"Right. Within 90 days."},"es":{"q":"En Kansas, usted no pasa el examen de la vista. Un médico de los ojos llena el formulario del estado. ¿En cuánto tiempo después del examen debe entregarlo?","o":["En 10 días","En 90 días","En 1 año","No hay límite de tiempo"],"h1":"Son unos tres meses.","h2":"En Kansas, el formulario del examen de la vista de un oftalmólogo u optometrista debe entregarse dentro de los 90 días del examen.","p":"Correcto. Dentro de 90 días."},"ref":{"doc":"KS","page":13}},{"id":"ks-070","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how long is a non-commercial Class A or B instruction permit valid?","o":["One year","Two years","Until your birthday","Six months"],"h1":"It is shorter than the Class C permit.","h2":"In Kansas, non-commercial Class A and B instruction permits are valid for six months.","p":"Right. Six months."},"es":{"q":"En Kansas, ¿por cuánto tiempo es válido un permiso de instrucción no comercial Clase A o B?","o":["Un año","Dos años","Hasta su cumpleaños","Seis meses"],"h1":"Es más corto que el permiso Clase C.","h2":"En Kansas, los permisos de instrucción no comerciales Clase A y B son válidos por seis meses.","p":"Correcto. Seis meses."},"ref":{"doc":"KS","page":14}},{"id":"ks-071","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, when does the Division of Vehicles send your license renewal notice?","o":["At least 30 days before it expires","On the day it expires","One week after it expires","Only if you ask for one"],"h1":"It comes about a month early.","h2":"In Kansas, the Division of Vehicles sends a renewal notice at least 30 days before your license expires, by mail or by email if you signed up.","p":"Right. At least 30 days before."},"es":{"q":"En Kansas, ¿cuándo envía la División de Vehículos el aviso para renovar su licencia?","o":["Al menos 30 días antes de que venza","El día en que vence","Una semana después de que vence","Solo si usted lo pide"],"h1":"Llega como un mes antes.","h2":"En Kansas, la División de Vehículos envía el aviso de renovación al menos 30 días antes de que venza su licencia, por correo o por email si usted se inscribió.","p":"Correcto. Al menos 30 días antes."},"ref":{"doc":"KS","page":14}},{"id":"ks-072","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, you renew your license a few weeks after it expired. What extra charge do you pay?","o":["$25","$10","$1.00","Nothing extra"],"h1":"It is a very small penalty.","h2":"In Kansas, there is an extra $1.00 penalty if your license has expired.","p":"Right. The late penalty is one dollar."},"es":{"q":"En Kansas, usted renueva su licencia unas semanas después de que venció. ¿Qué cargo extra paga?","o":["$25","$10","$1.00","Nada extra"],"h1":"Es una multa muy pequeña.","h2":"En Kansas, hay un cargo extra de $1.00 si su licencia ya venció.","p":"Correcto. El cargo por atraso es un dólar."},"ref":{"doc":"KS","page":14}},{"id":"ks-073","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"You live in western Kansas but are visiting Topeka. Can you renew your Kansas license there?","o":["No, only in your home county","Yes, at any Kansas driver's license office","Only if you have an appointment in your county","Only online"],"h1":"Where you live in Kansas does not matter.","h2":"In Kansas, you may renew your license at any driver's license office, no matter where in the state you live.","p":"Right. Any Kansas office will do."},"es":{"q":"Usted vive en el oeste de Kansas pero está de visita en Topeka. ¿Puede renovar allí su licencia de Kansas?","o":["No, solo en su condado","Sí, en cualquier oficina de licencias de Kansas","Solo si tiene cita en su condado","Solo por internet"],"h1":"No importa en qué parte de Kansas viva.","h2":"En Kansas, puede renovar su licencia en cualquier oficina de licencias, sin importar en qué parte del estado viva.","p":"Correcto. Sirve cualquier oficina de Kansas."},"ref":{"doc":"KS","page":14}},{"id":"ks-074","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, who must renew at a full-service driver's license station?","o":["Drivers who are over 65 years old","Drivers who wear glasses or contacts","New residents moving from another state","CDL holders and registered offenders"],"h1":"Two special groups cannot use just any office.","h2":"In Kansas, commercial license (CDL) holders and registered offenders must renew at a full-service driver's license station.","p":"Right. CDL holders and registered offenders."},"es":{"q":"En Kansas, ¿quiénes deben renovar en una oficina de licencias de servicio completo?","o":["Conductores mayores de 65 años","Conductores que usan anteojos o lentes de contacto","Residentes nuevos que llegan de otro estado","Titulares de CDL y delincuentes registrados"],"h1":"Dos grupos especiales no pueden usar cualquier oficina.","h2":"En Kansas, los titulares de licencia comercial (CDL) y los delincuentes registrados deben renovar en una oficina de licencias de servicio completo.","p":"Correcto. Titulares de CDL y delincuentes registrados."},"ref":{"doc":"KS","page":14}},{"id":"ks-075","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, a temporary resident gets a driver's license. When does it expire?","o":["When their lawful stay in the US ends","After exactly one year from issue","After eight years, like other licenses","It never expires while they live here"],"h1":"It is tied to their legal stay.","h2":"In Kansas, a license, permit or ID for a temporary resident expires when their authorization to be lawfully present in the United States ends.","p":"Right. It ends with their lawful stay."},"es":{"q":"En Kansas, un residente temporal obtiene una licencia de conducir. ¿Cuándo vence?","o":["Cuando termina su estancia legal en EE. UU.","Exactamente un año después de emitirse","Después de ocho años, como otras licencias","Nunca vence mientras viva aquí"],"h1":"Está ligada a su estancia legal.","h2":"En Kansas, la licencia, el permiso o la identificación de un residente temporal vence cuando termina su autorización para estar legalmente en Estados Unidos.","p":"Correcto. Termina con su estancia legal."},"ref":{"doc":"KS","page":14}},{"id":"ks-076","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, renewal usually does not need a written test. When can the examiner still require one?","o":["Never, renewal has no tests at all","When they doubt you can control a car safely","Only on your 50th birthday","Only if you moved to a new county"],"h1":"It depends on whether you seem able to drive safely.","h2":"In Kansas, an examiner may require a written or driving test at renewal if they suspect you cannot exercise ordinary and reasonable control of a vehicle.","p":"Right. If safe control seems in doubt."},"es":{"q":"En Kansas, renovar normalmente no requiere examen escrito. ¿Cuándo puede el examinador pedir uno de todos modos?","o":["Nunca, renovar no tiene ningún examen","Cuando duda que usted pueda controlar un auto con seguridad","Solo en su cumpleaños número 50","Solo si se mudó a otro condado"],"h1":"Depende de si usted parece capaz de manejar con seguridad.","h2":"En Kansas, el examinador puede pedir un examen escrito o de manejo al renovar si sospecha que usted no puede controlar un vehículo de manera normal y razonable.","p":"Correcto. Si hay dudas sobre el control seguro."},"ref":{"doc":"KS","page":14}},{"id":"ks-077","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, you got a traffic ticket and did not show up for your court date. What can happen to your license?","o":["A 10-day suspension","Nothing, if you pay later","A suspension with no set end date","A warning letter only"],"h1":"The suspension lasts until you deal with the case.","h2":"In Kansas, failing to appear for a court date leads to a mandatory indefinite suspension of your driving privileges.","p":"Right. It is an indefinite suspension."},"es":{"q":"En Kansas, usted recibió una multa de tránsito y no se presentó a su fecha en la corte. ¿Qué le puede pasar a su licencia?","o":["Una suspensión de 10 días","Nada, si paga después","Una suspensión sin fecha de fin","Solo una carta de advertencia"],"h1":"La suspensión dura hasta que usted resuelva el caso.","h2":"En Kansas, no presentarse a una fecha en la corte causa una suspensión obligatoria e indefinida de sus privilegios de manejo.","p":"Correcto. Es una suspensión indefinida."},"ref":{"doc":"KS","page":14}},{"id":"ks-078","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, which of these can get your driving privileges suspended?","o":["Driving with the radio on","Not reporting a traffic crash","Parking in a paid lot","Driving a borrowed car"],"h1":"Crashes come with a duty to tell the police.","h2":"In Kansas, failing to report a traffic crash is one of the violations that can get your driving privileges suspended.","p":"Right. Not reporting a crash can cost you your license."},"es":{"q":"En Kansas, ¿cuál de estas cosas puede causar la suspensión de sus privilegios de manejo?","o":["Manejar con la radio encendida","No reportar un choque de tránsito","Estacionar en un lote de pago","Manejar un auto prestado"],"h1":"Los choques traen la obligación de avisar a la policía.","h2":"En Kansas, no reportar un choque de tránsito es una de las infracciones que pueden causar la suspensión de sus privilegios de manejo.","p":"Correcto. No reportar un choque puede costarle la licencia."},"ref":{"doc":"KS","page":14}},{"id":"ks-079","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, a conviction for which of these can lead to your license being revoked?","o":["Driving with a dirty windshield","Forgetting your registration at home","Parking too far from the curb","Trying to get away from a police officer"],"h1":"It is a serious, dangerous act, not a small mistake.","h2":"In Kansas, attempting to elude a police officer is one of the convictions that can lead to revocation of your license.","p":"Right. Fleeing from police can lead to revocation."},"es":{"q":"En Kansas, ¿una condena por cuál de estas cosas puede llevar a la revocación de su licencia?","o":["Manejar con el parabrisas sucio","Olvidar su registro en casa","Estacionar demasiado lejos de la acera","Tratar de huir de un oficial de policía"],"h1":"Es un acto grave y peligroso, no un error pequeño.","h2":"En Kansas, intentar huir de un oficial de policía es una de las condenas que pueden llevar a la revocación de su licencia.","p":"Correcto. Huir de la policía puede llevar a la revocación."},"ref":{"doc":"KS","page":15}},{"id":"ks-080","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"A college student from Ohio pays out-of-state tuition at a Kansas university. Can they drive in Kansas on their valid Ohio license?","o":["Yes, if they are at least 16","No, they need a Kansas license within 10 days","Only on weekends","Only with a Kansas adult in the car"],"h1":"Non-resident students are one of the listed exceptions.","h2":"In Kansas, students who are non-residents for tuition may drive on their valid home-state license if they are at least 16.","p":"Right. They may use their valid home license."},"es":{"q":"Un estudiante de Ohio paga matrícula de fuera del estado en una universidad de Kansas. ¿Puede manejar en Kansas con su licencia válida de Ohio?","o":["Sí, si tiene al menos 16 años","No, necesita una licencia de Kansas en 10 días","Solo los fines de semana","Solo con un adulto de Kansas en el auto"],"h1":"Los estudiantes no residentes son una de las excepciones.","h2":"En Kansas, los estudiantes que no son residentes para la matrícula pueden manejar con su licencia válida de su estado si tienen al menos 16 años.","p":"Correcto. Puede usar su licencia válida de su estado."},"ref":{"doc":"KS","page":15}},{"id":"ks-081","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, a Class C license lets you drive vehicles of what size?","o":["Any vehicle of any weight","Only motorcycles","Vehicles rated under 26,001 pounds","Only vehicles over 26,001 pounds"],"h1":"Class C is the everyday license for cars, not big trucks.","h2":"In Kansas, a Class C license covers vehicles with a gross vehicle weight rating of less than 26,001 pounds.","p":"Right. Under 26,001 pounds."},"es":{"q":"En Kansas, ¿qué tamaño de vehículo le permite manejar una licencia Clase C?","o":["Cualquier vehículo de cualquier peso","Solo motocicletas","Vehículos con clasificación de menos de 26,001 libras","Solo vehículos de más de 26,001 libras"],"h1":"La Clase C es la licencia común para autos, no para camiones grandes.","h2":"En Kansas, la licencia Clase C cubre vehículos con un peso bruto vehicular nominal de menos de 26,001 libras.","p":"Correcto. Menos de 26,001 libras."},"ref":{"doc":"KS","page":15}},{"id":"ks-082","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, on what day does your driver's license expire?","o":["On January 1","On your birthday","On the day you first got it","It never expires"],"h1":"It is a date that is easy to remember.","h2":"In Kansas, your driver's license expires on your birthday.","p":"Right. It expires on your birthday."},"es":{"q":"En Kansas, ¿qué día vence su licencia de conducir?","o":["El 1 de enero","El día de su cumpleaños","El día en que la obtuvo por primera vez","Nunca vence"],"h1":"Es una fecha fácil de recordar.","h2":"En Kansas, su licencia de conducir vence el día de su cumpleaños.","p":"Correcto. Vence en su cumpleaños."},"ref":{"doc":"KS","page":15}},{"id":"ks-083","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, how much time do you get for the knowledge test?","o":["10 minutes for all questions","30 minutes for all questions","One hour, with a short break","No limit; usually 15 to 20 minutes"],"h1":"There is no clock running.","h2":"In Kansas, the knowledge test is not timed, but it usually takes 15 to 20 minutes.","p":"Right. It is untimed."},"es":{"q":"En Kansas, ¿cuánto tiempo le dan para el examen de conocimientos?","o":["10 minutos para todas las preguntas","30 minutos para todas las preguntas","Una hora, con un descanso corto","Sin límite; suele tomar de 15 a 20 minutos"],"h1":"No hay reloj corriendo.","h2":"En Kansas, el examen de conocimientos no tiene límite de tiempo, pero suele tomar de 15 a 20 minutos.","p":"Correcto. No tiene límite de tiempo."},"ref":{"doc":"KS","page":94}},{"id":"ks-084","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"A Kansas teen got an instruction permit at 16 and a half. When can they take the driving test?","o":["At 17, since that comes before a full year with the permit","Only after a full year with the permit","Right away","Only at 18"],"h1":"For drivers under 17, it is one year or age 17, whichever comes first.","h2":"In Kansas, a driver under 17 must hold the permit for one full year or until turning 17, whichever comes first, before the driving test.","p":"Right. Turning 17 comes first here."},"es":{"q":"Un joven de Kansas obtuvo su permiso de instrucción a los 16 años y medio. ¿Cuándo puede tomar el examen de manejo?","o":["A los 17, porque llega antes de cumplir un año con el permiso","Solo después de un año completo con el permiso","De inmediato","Solo a los 18"],"h1":"Para menores de 17, es un año o los 17 años, lo que llegue primero.","h2":"En Kansas, un conductor menor de 17 debe tener el permiso por un año completo o hasta cumplir 17, lo que llegue primero, antes del examen de manejo.","p":"Correcto. Aquí los 17 años llegan primero."},"ref":{"doc":"KS","page":94}},{"id":"ks-085","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, which tests make up the driver's license test after the knowledge test?","o":["Only a road test in traffic","A road test and a separate night test","A pre-trip check, a control skills test, and a road test","A first aid test and a road test"],"h1":"There are three parts, starting before you even drive.","h2":"In Kansas, you must pass the pre-trip vehicle safety inspection test, the basic vehicle control skills test and the road test.","p":"Right. Three tests: pre-trip, control skills and road."},"es":{"q":"En Kansas, ¿qué pruebas forman el examen de manejo después del examen de conocimientos?","o":["Solo una prueba en la calle con tráfico","Una prueba en la calle y otra de noche","Una revisión previa, una prueba de control y una prueba en la calle","Una prueba de primeros auxilios y una en la calle"],"h1":"Son tres partes, y una empieza antes de manejar.","h2":"En Kansas, debe aprobar la inspección de seguridad del vehículo antes de manejar, la prueba de control básico del vehículo y la prueba en la calle.","p":"Correcto. Tres pruebas: revisión, control y calle."},"ref":{"doc":"KS","page":94}},{"id":"ks-086","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kansas, what must you show the examiner before your driving test?","o":["Your school report card","Your valid instruction permit and proof of Kansas residence","A letter from your driving instructor","Your car's purchase receipt"],"h1":"One document proves you are learning, the other proves where you live.","h2":"In Kansas, you must present a valid instruction permit and proof of Kansas residence before the driving test.","p":"Right. Permit and proof of Kansas residence."},"es":{"q":"En Kansas, ¿qué debe mostrarle al examinador antes del examen de manejo?","o":["Su boleta de calificaciones","Su permiso de instrucción válido y un comprobante de residencia en Kansas","Una carta de su instructor","El recibo de compra de su auto"],"h1":"Un documento prueba que está aprendiendo y el otro dónde vive.","h2":"En Kansas, debe presentar un permiso de instrucción válido y un comprobante de residencia en Kansas antes del examen de manejo.","p":"Correcto. Permiso y comprobante de residencia."},"ref":{"doc":"KS","page":94}},{"id":"ks-087","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kansas, it is 90°F outside on the day of your driving test. What must work in your test car?","o":["The radio","The rear window wiper","The cruise control","The air conditioner"],"h1":"The examiner rides with you, so the inside must be a safe temperature.","h2":"In Kansas, when it is over 85°F outside, the air conditioner in the test vehicle must work properly.","p":"Right. Above 85°F the air conditioner must work."},"es":{"q":"En Kansas, hace 90°F afuera el día de su examen de manejo. ¿Qué debe funcionar en su auto de examen?","o":["La radio","El limpiaparabrisas trasero","El control de velocidad crucero","El aire acondicionado"],"h1":"El examinador va con usted, así que adentro debe haber una temperatura segura.","h2":"En Kansas, cuando hace más de 85°F afuera, el aire acondicionado del vehículo de examen debe funcionar bien.","p":"Correcto. Arriba de 85°F el aire acondicionado debe funcionar."},"ref":{"doc":"KS","page":97}},{"id":"ks-088","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, which of these makes you fail the road test right away?","o":["Not wearing your safety belt","Driving 5 mph under the limit","Asking the examiner to repeat a direction","Stopping smoothly behind a stop line"],"h1":"It is a basic safety habit you must show from the start.","h2":"In Kansas, not using your safety belt during the road test is an automatic failure.","p":"Right. No safety belt means an automatic failure."},"es":{"q":"En Kansas, ¿cuál de estas cosas lo hace reprobar de inmediato la prueba en la calle?","o":["No usar el cinturón de seguridad","Manejar 5 mph por debajo del límite","Pedir al examinador que repita una instrucción","Detenerse suavemente antes de la línea de alto"],"h1":"Es un hábito básico de seguridad que debe mostrar desde el inicio.","h2":"En Kansas, no usar el cinturón de seguridad durante la prueba en la calle es una falla automática.","p":"Correcto. No usar el cinturón es falla automática."},"ref":{"doc":"KS","page":107}},{"id":"ks-089","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In the Kansas basic control skills test, what counts as a \"reversal\" error?","o":["Using your mirrors","Stopping for a moment without changing direction","Stopping and changing direction to get a better position","Using your turn signal"],"h1":"It is about switching between forward and reverse.","h2":"In the Kansas control skills test, each time you stop and reverse direction to get a better position counts as an error.","p":"Right. Each change of direction is a reversal."},"es":{"q":"En la prueba de control básico de Kansas, ¿qué cuenta como error de \"reversa\" (reversal)?","o":["Usar los espejos","Detenerse un momento sin cambiar de dirección","Detenerse y cambiar de dirección para acomodarse mejor","Usar la direccional"],"h1":"Se trata de cambiar entre adelante y reversa.","h2":"En la prueba de control de Kansas, cada vez que se detiene y cambia de dirección para acomodarse mejor cuenta como un error.","p":"Correcto. Cada cambio de dirección es una reversa."},"ref":{"doc":"KS","page":100}},{"id":"ks-090","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"In the Kansas basic control skills test, which part of your car may touch a boundary line or cone without counting as an error?","o":["The front bumper","The side mirrors","The rear tires","No part at all"],"h1":"It is a part that sticks out from the sides.","h2":"In the Kansas control skills test, touching or crossing a boundary with any part of the vehicle except the mirrors counts as an encroachment error.","p":"Right. Only the mirrors do not count."},"es":{"q":"En la prueba de control básico de Kansas, ¿qué parte de su auto puede tocar una línea o un cono sin que cuente como error?","o":["La defensa delantera","Los espejos laterales","Las llantas traseras","Ninguna parte"],"h1":"Es una parte que sobresale de los lados.","h2":"En la prueba de control de Kansas, tocar o cruzar un límite con cualquier parte del vehículo, menos los espejos, cuenta como error de invasión.","p":"Correcto. Solo los espejos no cuentan."},"ref":{"doc":"KS","page":100}},{"id":"ks-091","scope":"KS","cat":"licensing","sign":null,"c":3,"en":{"q":"You move to a new address in Kansas. Whom should you contact about your vehicle tags?","o":["The Kansas Highway Patrol","Your insurance agent only","The post office","Your local County Treasurer"],"h1":"Tags are handled at the county level.","h2":"In Kansas, when you move, you contact your local County Treasurer about your vehicle tags.","p":"Right. The County Treasurer handles tags."},"es":{"q":"Usted se muda a otra dirección en Kansas. ¿A quién debe avisar sobre las placas de su vehículo?","o":["A la Patrulla de Caminos de Kansas","Solo a su agente de seguros","A la oficina de correos","Al Tesorero de su condado"],"h1":"Las placas se manejan a nivel del condado.","h2":"En Kansas, cuando se muda, debe avisar al Tesorero de su condado (County Treasurer) sobre las placas de su vehículo.","p":"Correcto. El Tesorero del condado se encarga de las placas."},"ref":{"doc":"KS","page":111}},{"id":"ks-092","scope":"KS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kansas, you are 18 and choose to be an organ donor when you get your license. Can your family undo that choice later?","o":["No, your own decision is legally binding","Yes, any relative can cancel it","Yes, but only a parent","Only if they pay a fee"],"h1":"Kansas uses first-person consent.","h2":"In Kansas, since July 2010, a donor decision made by a person 18 or older is legally binding, and no one else may reverse it.","p":"Right. Your decision stands."},"es":{"q":"En Kansas, usted tiene 18 años y elige ser donante de órganos al sacar su licencia. ¿Puede su familia deshacer esa decisión después?","o":["No, su propia decisión es legalmente obligatoria","Sí, cualquier pariente puede cancelarla","Sí, pero solo un padre","Solo si pagan una tarifa"],"h1":"Kansas usa el consentimiento en primera persona.","h2":"En Kansas, desde julio de 2010, la decisión de donar de una persona de 18 años o más es legalmente obligatoria y nadie más puede revertirla.","p":"Correcto. Su decisión se respeta."},"ref":{"doc":"KS","page":112}},{"id":"ks-093","scope":"KS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kansas, what is the minimum liability insurance a car owner must carry?","o":["$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"The amount for one person is a quarter of $100,000.","h2":"Under Kansas law, liability insurance must cover at least $25,000 for injury to one person, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. 25/50/25 is the Kansas minimum."},"es":{"q":"En Kansas, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener el dueño de un auto?","o":["$10,000 / $20,000 / $5,000","$15,000 / $30,000 / $10,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $100,000"],"h1":"La cantidad por una persona es la cuarta parte de $100,000.","h2":"Según la ley de Kansas, el seguro de responsabilidad civil debe cubrir al menos $25,000 por lesiones a una persona, $50,000 por dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. 25/50/25 es el mínimo en Kansas."},"ref":{"doc":"KS","page":null}},{"id":"ks-094","scope":"KS","cat":"licensing","sign":null,"c":1,"en":{"q":"Besides liability coverage, what must every Kansas car insurance policy include?","o":["Roadside assistance for breakdowns","Personal injury protection (PIP)","Rental car coverage after a crash","Coverage if the car is stolen"],"h1":"It pays for injuries to you and your passengers, no matter who caused the crash.","h2":"Under Kansas law, every auto liability policy must include personal injury protection (PIP) benefits.","p":"Right. PIP is required in Kansas."},"es":{"q":"Además de la responsabilidad civil, ¿qué debe incluir toda póliza de seguro de auto en Kansas?","o":["Asistencia en el camino por averías","Protección contra lesiones personales (PIP)","Cobertura de auto de renta tras un choque","Cobertura si le roban el auto"],"h1":"Paga lesiones suyas y de sus pasajeros, sin importar quién causó el choque.","h2":"Según la ley de Kansas, toda póliza de responsabilidad civil de auto debe incluir beneficios de protección contra lesiones personales (PIP).","p":"Correcto. El PIP es obligatorio en Kansas."},"ref":{"doc":"KS","page":null}},{"id":"ks-095","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, no police officer is at a crash scene and no one is hurt. When must you report the crash to the police right away?","o":["Only if a car must be towed","Only if it happened on an interstate","Never, if the drivers agree","When the damage looks like $1,000 or more"],"h1":"There is a dollar amount for damage.","h2":"Under Kansas law, if no officer is present, you must report a crash right away when anyone is hurt or killed, or when property damage appears to be $1,000 or more.","p":"Right. $1,000 or more in damage must be reported."},"es":{"q":"En Kansas, no hay policía en el lugar de un choque y nadie está herido. ¿Cuándo debe reportar el choque a la policía de inmediato?","o":["Solo si hay que remolcar un auto","Solo si ocurrió en una carretera interestatal","Nunca, si los conductores están de acuerdo","Cuando el daño parece ser de $1,000 o más"],"h1":"Hay una cantidad de dinero para los daños.","h2":"Según la ley de Kansas, si no hay un oficial presente, debe reportar el choque de inmediato cuando alguien está herido o muerto, o cuando los daños parecen ser de $1,000 o más.","p":"Correcto. Daños de $1,000 o más se deben reportar."},"ref":{"doc":"KS","page":null}},{"id":"ks-096","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, you have a minor crash on an interstate. No one is hurt, and your car can still be driven. What should you do?","o":["Move the car off the roadway if you can do it safely","Leave the car exactly where it stopped until police arrive","Stand in the lane to warn drivers","Push the other car to the median"],"h1":"Blocked lanes cause more crashes.","h2":"Under Kansas law, if no one is hurt and the vehicle can be driven safely, the driver should make every reasonable effort to move it off an interstate, U.S. highway or multilane road.","p":"Right. Move it out of traffic if it is safe."},"es":{"q":"En Kansas, usted tiene un choque leve en una carretera interestatal. Nadie está herido y su auto todavía se puede manejar. ¿Qué debe hacer?","o":["Sacar el auto de la carretera si puede hacerlo con seguridad","Dejar el auto donde se detuvo hasta que llegue la policía","Pararse en el carril para avisar a los conductores","Empujar el otro auto hacia la mediana"],"h1":"Los carriles bloqueados causan más choques.","h2":"Según la ley de Kansas, si nadie está herido y el vehículo se puede manejar con seguridad, el conductor debe hacer todo lo razonable para sacarlo de una interestatal, carretera federal o vía de varios carriles.","p":"Correcto. Sáquelo del tráfico si es seguro."},"ref":{"doc":"KS","page":null}},{"id":"ks-097","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, unless another limit is posted, what is the speed limit in a properly marked school zone?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"It is lower than the 30 mph city limit.","h2":"In Kansas, the maximum speed in a properly marked school zone is 20 mph unless another limit is posted.","p":"Right. 20 mph in a marked school zone."},"es":{"q":"En Kansas, si no hay otro límite señalado, ¿cuál es el límite de velocidad en una zona escolar bien marcada?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Es menor que el límite de 30 mph en la ciudad.","h2":"En Kansas, la velocidad máxima en una zona escolar bien marcada es 20 mph, a menos que se señale otro límite.","p":"Correcto. 20 mph en una zona escolar marcada."},"ref":{"doc":"KS","page":16}},{"id":"ks-098","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, no minimum speed is posted on a road. Can you still get in trouble for driving too slowly?","o":["No, driving slowly is always legal","Only on interstate highways","Yes, if you block the normal flow of traffic","Only if it is after dark"],"h1":"Being a roadblock is the problem.","h2":"In Kansas, even without a posted minimum, it is unlawful to drive so slowly that you impede the normal movement of traffic, unless slowing is needed for safety.","p":"Right. Blocking normal traffic by going too slow is illegal."},"es":{"q":"En Kansas, en un camino no hay velocidad mínima señalada. ¿Puede meterse en problemas por manejar demasiado despacio?","o":["No, manejar despacio siempre es legal","Solo en carreteras interestatales","Sí, si bloquea el flujo normal del tráfico","Solo si ya oscureció"],"h1":"El problema es convertirse en un obstáculo.","h2":"En Kansas, aunque no haya un mínimo señalado, es ilegal manejar tan despacio que impida el movimiento normal del tráfico, salvo que ir despacio sea necesario por seguridad.","p":"Correcto. Bloquear el tráfico normal por ir muy despacio es ilegal."},"ref":{"doc":"KS","page":16}},{"id":"ks-099","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"It is snowing hard on a Kansas road posted at 55 mph. You drive exactly 55 mph. Can you get a ticket?","o":["No, you are at the posted limit","Only if you cause a crash","Only on interstate highways","Yes, for driving too fast for conditions"],"h1":"Posted limits are meant for good conditions.","h2":"In Kansas, speed limits are set for ideal conditions; driving 55 mph in a snowstorm is not an acceptable speed, and you can be cited for driving too fast for conditions.","p":"Right. The limit is not a safe speed in a snowstorm."},"es":{"q":"Nieva mucho en un camino de Kansas con límite de 55 mph. Usted maneja exactamente a 55 mph. ¿Le pueden dar una multa?","o":["No, está en el límite señalado","Solo si causa un choque","Solo en carreteras interestatales","Sí, por ir demasiado rápido para las condiciones"],"h1":"Los límites señalados son para buenas condiciones.","h2":"En Kansas, los límites de velocidad son para condiciones ideales; manejar a 55 mph en una tormenta de nieve no es aceptable y le pueden multar por ir demasiado rápido para las condiciones.","p":"Correcto. El límite no es una velocidad segura en una tormenta de nieve."},"ref":{"doc":"KS","page":62}},{"id":"ks-100","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, an officer sees an adult in the back seat without a seat belt, and nothing else is wrong. Can the officer stop the car for that alone?","o":["No, not for that reason alone","Yes, any unbelted person is a reason","Yes, but only at night","Only on interstate highways"],"h1":"The primary rule covers front-seat adults and children anywhere.","h2":"Under Kansas law, police may stop a car for an unbelted adult in the front seat or an unbelted child anywhere, but not for an unbelted adult in the back seat alone.","p":"Right. A back-seat adult alone is not a reason to stop."},"es":{"q":"En Kansas, un oficial ve a un adulto sin cinturón en el asiento trasero, y no hay nada más mal. ¿Puede el oficial detener el auto solo por eso?","o":["No, no solo por esa razón","Sí, cualquier persona sin cinturón es razón","Sí, pero solo de noche","Solo en carreteras interestatales"],"h1":"La regla primaria cubre a los adultos de adelante y a los niños en cualquier asiento.","h2":"Según la ley de Kansas, la policía puede detener un auto por un adulto sin cinturón en el asiento delantero o un niño sin cinturón en cualquier lugar, pero no solo por un adulto sin cinturón atrás.","p":"Correcto. Un adulto sin cinturón atrás no basta para detener el auto."},"ref":{"doc":"KS","page":null}},{"id":"ks-101","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, what is the fine for an adult, 18 or older, who does not wear a seat belt?","o":["$10","$30","$100","$250"],"h1":"It is less than fifty dollars, with no court costs.","h2":"Under Kansas law, a person 18 or older who does not wear a seat belt is fined $30, with no court costs.","p":"Right. The adult fine is $30."},"es":{"q":"En Kansas, ¿cuál es la multa para un adulto de 18 años o más que no usa el cinturón de seguridad?","o":["$10","$30","$100","$250"],"h1":"Es menos de cincuenta dólares, sin costos de corte.","h2":"Según la ley de Kansas, a una persona de 18 años o más que no usa el cinturón se le multa con $30, sin costos de corte.","p":"Correcto. La multa para adultos es $30."},"ref":{"doc":"KS","page":null}},{"id":"ks-102","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, what is the seat belt fine for a passenger who is 14 to 17 years old?","o":["$10","$30","$60","$500"],"h1":"It is twice the adult fine.","h2":"Under Kansas law, an occupant aged 14 to 17 who does not wear a seat belt is fined $60.","p":"Right. $60 for ages 14 to 17."},"es":{"q":"En Kansas, ¿cuál es la multa por no usar el cinturón para un pasajero de 14 a 17 años?","o":["$10","$30","$60","$500"],"h1":"Es el doble de la multa para adultos.","h2":"Según la ley de Kansas, a un ocupante de 14 a 17 años que no usa el cinturón se le multa con $60.","p":"Correcto. $60 para edades de 14 a 17."},"ref":{"doc":"KS","page":null}},{"id":"ks-103","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, a driver gets a $60 ticket because a young child had no proper car seat. How can the fine be waived?","o":["By paying it within one week","By taking a safe driving class","By having the child's parent sign it","By proving they got an approved child seat"],"h1":"The goal is to get the child protected.","h2":"Under Kansas law, the $60 child restraint fine is waived if the driver shows the court proof of buying or getting an approved child safety seat.","p":"Right. Proof of a proper seat waives the fine."},"es":{"q":"En Kansas, un conductor recibe una multa de $60 porque un niño pequeño no tenía el asiento infantil adecuado. ¿Cómo se puede perdonar la multa?","o":["Pagándola en una semana","Tomando una clase de manejo seguro","Pidiendo al padre del niño que la firme","Probando que consiguió un asiento infantil aprobado"],"h1":"La meta es que el niño quede protegido.","h2":"Según la ley de Kansas, la multa de $60 por falta de asiento infantil se perdona si el conductor muestra a la corte prueba de que compró u obtuvo un asiento de seguridad infantil aprobado.","p":"Correcto. Con prueba del asiento adecuado se perdona la multa."},"ref":{"doc":"KS","page":null}},{"id":"ks-104","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, how must a child who is 8 years or older ride in a car?","o":["Wearing a seat belt","In a booster seat until age 12","On a parent's lap","In a rear-facing seat"],"h1":"At this age the child has moved past booster rules.","h2":"In Kansas, children 8 years old and older must be protected by a seat belt.","p":"Right. Age 8 and up use a seat belt."},"es":{"q":"En Kansas, ¿cómo debe viajar en un auto un niño de 8 años o más?","o":["Con el cinturón de seguridad puesto","En un asiento elevado hasta los 12 años","En las piernas de un padre","En un asiento mirando hacia atrás"],"h1":"A esta edad el niño ya pasó las reglas del asiento elevado.","h2":"En Kansas, los niños de 8 años o más deben ir protegidos con un cinturón de seguridad.","p":"Correcto. Desde los 8 años usan cinturón."},"ref":{"doc":"KS","page":16}},{"id":"ks-105","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, what is the safest place to put a child safety seat?","o":["The front passenger seat","The middle of the back seat","Behind the driver, against the door","In the cargo area"],"h1":"It is the spot farthest from the sides and the front.","h2":"The Kansas handbook says the safest position for a child safety seat is the middle of the back seat.","p":"Right. The middle of the back seat."},"es":{"q":"Según el manual de Kansas, ¿cuál es el lugar más seguro para poner un asiento de seguridad infantil?","o":["El asiento del pasajero de adelante","El centro del asiento trasero","Detrás del conductor, contra la puerta","En el área de carga"],"h1":"Es el lugar más lejos de los lados y del frente.","h2":"El manual de Kansas dice que el lugar más seguro para un asiento de seguridad infantil es el centro del asiento trasero.","p":"Correcto. El centro del asiento trasero."},"ref":{"doc":"KS","page":17}},{"id":"ks-106","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kansas, you are turning right from a four-lane divided highway. How should you do it?","o":["Swing wide into the far lane of the cross street","Turn right from the left lane","Move right early, then turn tightly into the right lane","Stop in your lane and wait for a big gap"],"h1":"Stay close to the right side the whole time.","h2":"In Kansas, to turn right from a four-lane divided highway, move into the right lane well before the turn and make a tight turn into the right lane of the cross street.","p":"Right. Early to the right lane, then a tight turn."},"es":{"q":"En Kansas, usted va a girar a la derecha desde una carretera dividida de cuatro carriles. ¿Cómo debe hacerlo?","o":["Abrirse hacia el carril más lejano de la otra calle","Girar a la derecha desde el carril izquierdo","Pasarse a la derecha con tiempo y girar cerrado al carril derecho","Detenerse en su carril y esperar un espacio grande"],"h1":"Manténgase cerca del lado derecho todo el tiempo.","h2":"En Kansas, para girar a la derecha desde una carretera dividida de cuatro carriles, pásese al carril derecho mucho antes y haga un giro cerrado hacia el carril derecho de la calle transversal.","p":"Correcto. Temprano al carril derecho y luego un giro cerrado."},"ref":{"doc":"KS","page":17}},{"id":"ks-107","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, you may not pass within how many feet of a bridge, viaduct or tunnel when your view is blocked?","o":["25 feet","50 feet","500 feet","100 feet"],"h1":"It is the same distance as for intersections and railroad crossings.","h2":"In Kansas, you may not pass within 100 feet of a bridge, viaduct or tunnel when your view is obstructed.","p":"Right. 100 feet."},"es":{"q":"En Kansas, ¿a cuántos pies de un puente, viaducto o túnel no puede rebasar cuando su vista está bloqueada?","o":["25 pies","50 pies","500 pies","100 pies"],"h1":"Es la misma distancia que para intersecciones y cruces de tren.","h2":"En Kansas, no puede rebasar a menos de 100 pies de un puente, viaducto o túnel cuando su vista está bloqueada.","p":"Correcto. 100 pies."},"ref":{"doc":"KS","page":17}},{"id":"ks-108","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, an emergency vehicle is stopped on the roadside with its lights on. Within what distance of it may you not pass another vehicle?","o":["100 feet","20 feet","50 feet","1,000 feet"],"h1":"It matches the other Kansas no-passing distances.","h2":"In Kansas, you may not pass another vehicle within 100 feet of an emergency vehicle stopped on the side of the road with its emergency lights on.","p":"Right. No passing within 100 feet."},"es":{"q":"En Kansas, un vehículo de emergencia está detenido al lado del camino con las luces encendidas. ¿A qué distancia de él no puede rebasar a otro vehículo?","o":["100 pies","20 pies","50 pies","1,000 pies"],"h1":"Coincide con las otras distancias de no rebasar en Kansas.","h2":"En Kansas, no puede rebasar a otro vehículo a menos de 100 pies de un vehículo de emergencia detenido al lado del camino con sus luces de emergencia encendidas.","p":"Correcto. No se rebasa a menos de 100 pies."},"ref":{"doc":"KS","page":17}},{"id":"ks-109","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, when may you pass another vehicle on the right?","o":["On any two-lane road with a slow car","On a one-way street or multilane road going your way","On the paved shoulder of the highway","Whenever the driver ahead is too slow"],"h1":"You need a real lane to the right, not a shoulder.","h2":"In Kansas, you may pass on the right on one-way streets and on highways marked for two or more lanes going the same direction, never on the shoulder except in an emergency or when directed.","p":"Right. Only where there is a lane going your way."},"es":{"q":"En Kansas, ¿cuándo puede rebasar a otro vehículo por la derecha?","o":["En cualquier camino de dos carriles con un auto lento","En una calle de un sentido o un camino de varios carriles en su dirección","Por el acotamiento pavimentado de la carretera","Siempre que el conductor de adelante vaya muy lento"],"h1":"Necesita un carril de verdad a la derecha, no un acotamiento.","h2":"En Kansas, puede rebasar por la derecha en calles de un solo sentido y en carreteras marcadas con dos o más carriles en la misma dirección, nunca por el acotamiento salvo en una emergencia o si se lo indican.","p":"Correcto. Solo donde hay un carril en su dirección."},"ref":{"doc":"KS","page":17}},{"id":"ks-110","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, in good driving conditions, what following distance does the handbook tell you to keep?","o":["One second","Three car lengths","At least two seconds","Ten seconds"],"h1":"Count \"one-thousand-one, one-thousand-two\".","h2":"In Kansas, the handbook says to use the two-second rule for a safe following distance in good conditions.","p":"Right. At least two seconds."},"es":{"q":"En Kansas, en buenas condiciones de manejo, ¿qué distancia de seguimiento indica el manual?","o":["Un segundo","Tres largos de auto","Al menos dos segundos","Diez segundos"],"h1":"Cuente \"mil uno, mil dos\".","h2":"En Kansas, el manual dice que use la regla de los dos segundos para una distancia segura en buenas condiciones.","p":"Correcto. Al menos dos segundos."},"ref":{"doc":"KS","page":17}},{"id":"ks-111","scope":"KS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In a Kansas business district, you drive out of a store's parking garage onto a street with a sidewalk. What must you do?","o":["Honk your horn and pull out","Slow down only if you see people","Stop only at the edge of the street","Stop before the sidewalk, then yield"],"h1":"Treat it like there is a stop sign before the sidewalk.","h2":"In Kansas, a driver coming out of an alley, driveway or building in a business or residential district must stop before the sidewalk and then yield the right-of-way.","p":"Right. Stop before the sidewalk and yield."},"es":{"q":"En un distrito comercial de Kansas, usted sale del estacionamiento de una tienda hacia una calle con banqueta. ¿Qué debe hacer?","o":["Tocar la bocina y salir","Bajar la velocidad solo si ve gente","Detenerse solo en la orilla de la calle","Detenerse antes de la banqueta y ceder el paso"],"h1":"Haga como si hubiera un alto antes de la banqueta.","h2":"En Kansas, quien sale de un callejón, una entrada o un edificio en un distrito comercial o residencial debe detenerse antes de la banqueta y luego ceder el paso.","p":"Correcto. Alto antes de la banqueta y ceda el paso."},"ref":{"doc":"KS","page":18}},{"id":"ks-112","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kansas, a road crew and its vehicles are working in the lane next to yours. What does the law require?","o":["Yield and move to a lane not next to them","Speed up so you pass them quickly","Honk your horn to warn the workers","Drive on the shoulder around them"],"h1":"Treat them much like a stopped emergency vehicle.","h2":"In Kansas, you must yield to construction vehicles and workers working on the road and move into a lane that is not next to them.","p":"Right. Yield and move over a lane."},"es":{"q":"En Kansas, un equipo de obras y sus vehículos trabajan en el carril junto al suyo. ¿Qué exige la ley?","o":["Ceder el paso y cambiarse a un carril que no esté junto a ellos","Acelerar para pasarlos rápido","Tocar la bocina para avisar a los trabajadores","Manejar por el acotamiento para rodearlos"],"h1":"Trátelos casi como a un vehículo de emergencia detenido.","h2":"En Kansas, debe ceder el paso a los vehículos y trabajadores de construcción que trabajan en el camino y cambiarse a un carril que no esté junto a ellos.","p":"Correcto. Ceda el paso y cámbiese de carril."},"ref":{"doc":"KS","page":18}},{"id":"ks-113","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, after an emergency vehicle with its siren on has passed you, how far behind it must you stay?","o":["At least 100 feet","At least 500 feet","At least 50 feet","At least one mile"],"h1":"Think of more than a city block.","h2":"In Kansas, after an emergency vehicle passes, you must stay at least 500 feet away from it.","p":"Right. At least 500 feet."},"es":{"q":"En Kansas, después de que pasa un vehículo de emergencia con la sirena encendida, ¿a qué distancia detrás de él debe mantenerse?","o":["Al menos 100 pies","Al menos 500 pies","Al menos 50 pies","Al menos una milla"],"h1":"Piense en más que una cuadra.","h2":"En Kansas, después de que pasa un vehículo de emergencia, debe mantenerse al menos a 500 pies de él.","p":"Correcto. Al menos 500 pies."},"ref":{"doc":"KS","page":85}},{"id":"ks-114","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kansas, a fire truck is pulling out of its station with its emergency lights flashing. What must you do?","o":["Honk your horn and keep going","Speed up to get past the station","Stop until it is out of your path","Pass it on the right side"],"h1":"You do not go until it is clear of you.","h2":"In Kansas, if an emergency vehicle is leaving or returning to its station with its lights flashing, you must stop until it is safely out of your path.","p":"Right. Stop until it is out of your way."},"es":{"q":"En Kansas, un camión de bomberos sale de su estación con las luces de emergencia encendidas. ¿Qué debe hacer?","o":["Tocar la bocina y seguir","Acelerar para pasar la estación","Detenerse hasta que salga de su camino","Rebasarlo por la derecha"],"h1":"No avance hasta que ya no esté en su camino.","h2":"En Kansas, si un vehículo de emergencia sale o regresa a su estación con las luces encendidas, debe detenerse hasta que ya no esté en su camino.","p":"Correcto. Deténgase hasta que se quite de su camino."},"ref":{"doc":"KS","page":85}},{"id":"ks-115","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, how far from the curb may your wheels be when you park along it?","o":["No more than 24 inches","No more than 18 inches","No more than 6 feet","No more than 12 inches"],"h1":"Think of one foot.","h2":"In Kansas, you may not park more than 12 inches from the curb.","p":"Right. No more than 12 inches."},"es":{"q":"En Kansas, ¿a qué distancia de la acera pueden quedar sus llantas al estacionarse junto a ella?","o":["No más de 24 pulgadas","No más de 18 pulgadas","No más de 6 pies","No más de 12 pulgadas"],"h1":"Piense en un pie.","h2":"En Kansas, no puede estacionarse a más de 12 pulgadas de la acera.","p":"Correcto. No más de 12 pulgadas."},"ref":{"doc":"KS","page":19}},{"id":"ks-116","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, how close may you park on the approach to a stop sign or traffic signal at the side of the road?","o":["No closer than 30 feet","No closer than 10 feet","No closer than 15 feet","No closer than 5 feet"],"h1":"It is twice the fire hydrant distance.","h2":"In Kansas, you may not park within 30 feet before a traffic signal, stop sign or flashing beacon at the side of the road.","p":"Right. No closer than 30 feet."},"es":{"q":"En Kansas, ¿qué tan cerca puede estacionarse antes de una señal de alto o un semáforo al lado del camino?","o":["No más cerca de 30 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 5 pies"],"h1":"Es el doble de la distancia del hidrante.","h2":"En Kansas, no puede estacionarse a menos de 30 pies antes de un semáforo, una señal de alto o una luz intermitente al lado del camino.","p":"Correcto. No más cerca de 30 pies."},"ref":{"doc":"KS","page":19}},{"id":"ks-117","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, you want to park on the same side of the street as a fire station driveway. How close may you park to it?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 50 feet","No closer than 75 feet"],"h1":"The fire trucks need room to swing out.","h2":"In Kansas, you may not park within 20 feet of a fire station driveway on the same side of the street.","p":"Right. No closer than 20 feet."},"es":{"q":"En Kansas, quiere estacionarse del mismo lado de la calle que la entrada de una estación de bomberos. ¿Qué tan cerca puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies","No más cerca de 75 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir.","h2":"En Kansas, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos del mismo lado de la calle.","p":"Correcto. No más cerca de 20 pies."},"ref":{"doc":"KS","page":19}},{"id":"ks-118","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, you want to park on the side of the street across from a fire station entrance. How far from the entrance must you stay?","o":["15 feet","30 feet","75 feet","500 feet"],"h1":"It is farther than on the station's own side.","h2":"In Kansas, on the side of the street opposite a fire station entrance, you may not park within 75 feet of it.","p":"Right. 75 feet on the opposite side."},"es":{"q":"En Kansas, quiere estacionarse en el lado de la calle de enfrente de la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe quedarse?","o":["15 pies","30 pies","75 pies","500 pies"],"h1":"Es más lejos que del lado de la estación.","h2":"En Kansas, en el lado de la calle opuesto a la entrada de una estación de bomberos, no puede estacionarse a menos de 75 pies de ella.","p":"Correcto. 75 pies del lado opuesto."},"ref":{"doc":"KS","page":19}},{"id":"ks-119","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Under Kansas law, is it illegal for an adult with a full license to talk on a phone while driving?","o":["Yes, all phone use is banned","Yes, but only on highways","Only if they do not use hands-free","No, but texting while driving is illegal"],"h1":"The Kansas ban is about written messages.","h2":"In Kansas, talking or dialing on a cell phone is not specifically illegal for a fully licensed adult, but writing, sending or reading texts is; the handbook still warns that any distraction is dangerous.","p":"Right. Talking is not banned for adults, but texting is."},"es":{"q":"Según la ley de Kansas, ¿es ilegal que un adulto con licencia completa hable por teléfono mientras maneja?","o":["Sí, se prohíbe todo uso del teléfono","Sí, pero solo en carreteras","Solo si no usa manos libres","No, pero enviar textos al manejar es ilegal"],"h1":"La prohibición de Kansas es sobre mensajes escritos.","h2":"En Kansas, hablar o marcar en el celular no está prohibido específicamente para un adulto con licencia completa, pero escribir, enviar o leer textos sí; el manual igual advierte que cualquier distracción es peligrosa.","p":"Correcto. Hablar no está prohibido para adultos, pero enviar textos sí."},"ref":{"doc":"KS","page":19}},{"id":"ks-120","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Under Kansas law, when may you read a text message in your car?","o":["When parked off the traveled roadway","While waiting at a red light","While moving in slow traffic","On a straight, empty highway"],"h1":"The car must be out of the traffic lanes.","h2":"Under Kansas law, the texting ban does not apply when the vehicle is stopped off the regular traveled part of the roadway.","p":"Right. Only when you are stopped off the road."},"es":{"q":"Según la ley de Kansas, ¿cuándo puede leer un mensaje de texto en su auto?","o":["Estacionado fuera de la parte transitada del camino","Mientras espera en un semáforo en rojo","Mientras avanza en tráfico lento","En una carretera recta y vacía"],"h1":"El auto debe estar fuera de los carriles de tránsito.","h2":"Según la ley de Kansas, la prohibición de textos no aplica cuando el vehículo está detenido fuera de la parte normal transitada del camino.","p":"Correcto. Solo cuando está detenido fuera del camino."},"ref":{"doc":"KS","page":null}},{"id":"ks-121","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Kansas law, where may an opened bottle of alcohol be carried in a car?","o":["In a cup holder, if the driver is sober","In the locked trunk","Under the driver's seat","In the glove box"],"h1":"It must be out of reach of everyone in the car.","h2":"Under Kansas law, an opened alcoholic beverage may be carried in a locked trunk or rear compartment, or, if there is no trunk, behind the last upright seat.","p":"Right. In the locked trunk."},"es":{"q":"Según la ley de Kansas, ¿dónde se puede llevar en un auto una botella de alcohol abierta?","o":["En un portavasos, si el conductor está sobrio","En la cajuela cerrada con llave","Debajo del asiento del conductor","En la guantera"],"h1":"Debe estar fuera del alcance de todos en el auto.","h2":"Según la ley de Kansas, una bebida alcohólica abierta se puede llevar en la cajuela o compartimiento trasero cerrado con llave o, si no hay cajuela, detrás del último asiento vertical.","p":"Correcto. En la cajuela cerrada con llave."},"ref":{"doc":"KS","page":null}},{"id":"ks-122","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Kansas law, what happens to your license after a second conviction for carrying an open container of alcohol?","o":["Nothing, it is only a fine","A 30-day warning period","It is suspended for one year","It is revoked for life"],"h1":"A repeat offense costs you your license for a while.","h2":"Under Kansas law, a second or later open container conviction leads to a one-year suspension of your driving privileges, or court-ordered restrictions instead.","p":"Right. A one-year suspension."},"es":{"q":"Según la ley de Kansas, ¿qué le pasa a su licencia después de una segunda condena por llevar un envase abierto de alcohol?","o":["Nada, es solo una multa","Un periodo de advertencia de 30 días","Se suspende por un año","Se revoca de por vida"],"h1":"Repetir la falta le cuesta la licencia por un tiempo.","h2":"Según la ley de Kansas, una segunda condena o más por envase abierto causa la suspensión de sus privilegios de manejo por un año, o restricciones que ordene la corte en su lugar.","p":"Correcto. Una suspensión de un año."},"ref":{"doc":"KS","page":null}},{"id":"ks-123","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"The Kansas handbook says most adults need how much sleep to stay alert during the day?","o":["3 to 4 hours","5 hours","10 to 12 hours","7 to 9 hours"],"h1":"It is a full night's sleep.","h2":"The Kansas handbook says most adults need 7 to 9 hours of sleep to stay properly alert during the day.","p":"Right. Seven to nine hours."},"es":{"q":"Según el manual de Kansas, ¿cuántas horas de sueño necesitan la mayoría de los adultos para estar alertas durante el día?","o":["3 a 4 horas","5 horas","10 a 12 horas","7 a 9 horas"],"h1":"Es una noche completa de sueño.","h2":"El manual de Kansas dice que la mayoría de los adultos necesitan de 7 a 9 horas de sueño para estar bien alertas durante el día.","p":"Correcto. De siete a nueve horas."},"ref":{"doc":"KS","page":21}},{"id":"ks-124","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"On a long trip, how often does the Kansas handbook suggest taking a break?","o":["About every 100 miles or 2 hours","Every 300 miles","Only when you need fuel","Every 15 minutes"],"h1":"Think of a couple of hours on the road.","h2":"The Kansas handbook suggests scheduling breaks about every 100 miles or every 2 hours on long trips.","p":"Right. About every 100 miles or 2 hours."},"es":{"q":"En un viaje largo, ¿cada cuánto sugiere el manual de Kansas tomar un descanso?","o":["Más o menos cada 100 millas o 2 horas","Cada 300 millas","Solo cuando necesite gasolina","Cada 15 minutos"],"h1":"Piense en un par de horas en el camino.","h2":"El manual de Kansas sugiere planear descansos más o menos cada 100 millas o cada 2 horas en viajes largos.","p":"Correcto. Más o menos cada 100 millas o 2 horas."},"ref":{"doc":"KS","page":21}},{"id":"ks-125","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kansas, you feel tired while driving and stop at a safe parking area. How long a nap does the handbook suggest?","o":["2 to 5 minutes","15 to 20 minutes","2 hours","At least 4 hours"],"h1":"A short nap, less than half an hour.","h2":"The Kansas handbook suggests a 15 to 20 minute nap in a safe parking area to fight fatigue.","p":"Right. A 15 to 20 minute nap."},"es":{"q":"En Kansas, usted se siente cansado mientras maneja y se detiene en un estacionamiento seguro. ¿Qué tan larga sugiere el manual que sea la siesta?","o":["2 a 5 minutos","15 a 20 minutos","2 horas","Al menos 4 horas"],"h1":"Una siesta corta, de menos de media hora.","h2":"El manual de Kansas sugiere una siesta de 15 a 20 minutos en un estacionamiento seguro para combatir el cansancio.","p":"Correcto. Una siesta de 15 a 20 minutos."},"ref":{"doc":"KS","page":21}},{"id":"ks-126","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"To avoid a fatigue-related crash, the Kansas handbook says to try not to drive during which hours?","o":["6 a.m. to 9 a.m.","Noon to 3 p.m.","Midnight to 6 a.m.","6 p.m. to 9 p.m."],"h1":"These are the hours when your body expects to sleep.","h2":"The Kansas handbook says to try not to drive late at night, between midnight and 6 a.m.","p":"Right. Midnight to 6 a.m."},"es":{"q":"Para evitar un choque por cansancio, ¿en qué horas dice el manual de Kansas que trate de no manejar?","o":["6 a.m. a 9 a.m.","Mediodía a 3 p.m.","Medianoche a 6 a.m.","6 p.m. a 9 p.m."],"h1":"Son las horas en que su cuerpo espera dormir.","h2":"El manual de Kansas dice que trate de no manejar tarde en la noche, entre la medianoche y las 6 a.m.","p":"Correcto. De medianoche a 6 a.m."},"ref":{"doc":"KS","page":21}},{"id":"ks-127","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Kansas handbook, alcohol and other impairing drugs are involved in about what share of all fatal crashes?","o":["5%","15%","90%","40%"],"h1":"It is a bit less than half.","h2":"The Kansas handbook says alcohol and other impairing drugs are involved in about 40% of all fatal crashes.","p":"Right. About 40%."},"es":{"q":"Según el manual de Kansas, ¿en qué parte de todos los choques mortales está involucrado el alcohol u otras drogas?","o":["5%","15%","90%","40%"],"h1":"Es un poco menos de la mitad.","h2":"El manual de Kansas dice que el alcohol y otras drogas que afectan están presentes en cerca del 40% de todos los choques mortales.","p":"Correcto. Cerca del 40%."},"ref":{"doc":"KS","page":22}},{"id":"ks-128","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Kansas handbook, at what blood alcohol level is vision already affected for all drivers?","o":[".02",".05",".08",".10"],"h1":"It is the same low number used for drivers under 21.","h2":"The Kansas handbook says vision is affected at a .02 blood alcohol concentration for all drivers.","p":"Right. Vision is affected at .02."},"es":{"q":"Según el manual de Kansas, ¿con qué nivel de alcohol en la sangre ya se afecta la vista de todos los conductores?","o":[".02",".05",".08",".10"],"h1":"Es el mismo número bajo que se usa para menores de 21.","h2":"El manual de Kansas dice que la vista se afecta con una concentración de alcohol en la sangre de .02 en todos los conductores.","p":"Correcto. La vista se afecta con .02."},"ref":{"doc":"KS","page":23}},{"id":"ks-129","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Your friend had four normal drinks. According to the Kansas handbook, how long should they wait before driving?","o":["One hour","Four hours or more","30 minutes, with coffee","Two hours, after a cold shower"],"h1":"The body clears about one drink each hour.","h2":"The Kansas handbook says it takes about an hour for the body to get rid of one normal drink, so after four drinks a person should wait four hours or more.","p":"Right. Four hours or more."},"es":{"q":"Su amigo tomó cuatro bebidas normales. Según el manual de Kansas, ¿cuánto debe esperar antes de manejar?","o":["Una hora","Cuatro horas o más","30 minutos, con café","Dos horas, después de una ducha fría"],"h1":"El cuerpo elimina más o menos una bebida por hora.","h2":"El manual de Kansas dice que el cuerpo tarda más o menos una hora en eliminar una bebida normal, así que después de cuatro bebidas hay que esperar cuatro horas o más.","p":"Correcto. Cuatro horas o más."},"ref":{"doc":"KS","page":23}},{"id":"ks-130","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kansas, an adult driver tests at .08 for the first time. What can happen to their license?","o":["Nothing, it is only a warning","It is revoked for life","It can be suspended for 30 days","It is suspended for 10 years"],"h1":"It is about one month.","h2":"In Kansas, a first test result of .08 or more can lead to a 30-day license suspension, followed by restrictions, plus possible criminal penalties.","p":"Right. A 30-day suspension."},"es":{"q":"En Kansas, un conductor adulto da .08 en una prueba por primera vez. ¿Qué le puede pasar a su licencia?","o":["Nada, es solo una advertencia","Se revoca de por vida","Se puede suspender por 30 días","Se suspende por 10 años"],"h1":"Es como un mes.","h2":"En Kansas, un primer resultado de .08 o más puede causar una suspensión de la licencia por 30 días, seguida de restricciones, además de posibles penas criminales.","p":"Correcto. Una suspensión de 30 días."},"ref":{"doc":"KS","page":23}},{"id":"ks-131","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kansas, what is the minimum sentence for a first DUI conviction, besides the fine?","o":["A warning letter from the court","One week of driver education","10 hours of community service","48 hours in jail or 100 hours of service"],"h1":"It is either two days behind bars or a lot of service hours.","h2":"In Kansas, a first DUI conviction brings at least 48 hours in jail or 100 hours of community service, plus a fine and a license suspension.","p":"Right. 48 hours in jail or 100 hours of service."},"es":{"q":"En Kansas, ¿cuál es la pena mínima por una primera condena por manejar bajo la influencia (DUI), además de la multa?","o":["Una carta de advertencia de la corte","Una semana de educación vial","10 horas de servicio comunitario","48 horas de cárcel o 100 horas de servicio"],"h1":"Son dos días en la cárcel o muchas horas de servicio.","h2":"En Kansas, una primera condena por DUI trae al menos 48 horas de cárcel o 100 horas de servicio comunitario, además de una multa y la suspensión de la licencia.","p":"Correcto. 48 horas de cárcel o 100 horas de servicio."},"ref":{"doc":"KS","page":24}},{"id":"ks-132","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kansas, after a first DUI conviction, what device will you have to use in your car?","o":["An ignition interlock device","A speed limiter on the engine","A camera mounted on the dashboard","A GPS tracker for the police"],"h1":"It checks your breath before the engine starts.","h2":"In Kansas, a driver convicted of a first DUI is also required to drive with an ignition interlock device.","p":"Right. An ignition interlock."},"es":{"q":"En Kansas, después de una primera condena por DUI, ¿qué aparato tendrá que usar en su auto?","o":["Un dispositivo de bloqueo de encendido","Un limitador de velocidad en el motor","Una cámara montada en el tablero","Un rastreador GPS para la policía"],"h1":"Revisa su aliento antes de que arranque el motor.","h2":"En Kansas, a un conductor condenado por un primer DUI también se le exige manejar con un dispositivo de bloqueo de encendido.","p":"Correcto. Un bloqueo de encendido."},"ref":{"doc":"KS","page":24}},{"id":"ks-133","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Kansas law, after the one-year suspension for a first refusal of an alcohol test, what comes next?","o":["Nothing, the full license comes back","Two years of driving only with an interlock","A second full year of suspension","A new road test, and nothing else"],"h1":"The restriction lasts twice as long as the suspension.","h2":"Under Kansas law, a first test refusal brings a one-year suspension, followed by two years of driving only a vehicle with an ignition interlock device.","p":"Right. Two years with an ignition interlock."},"es":{"q":"Según la ley de Kansas, después de la suspensión de un año por negarse por primera vez a una prueba de alcohol, ¿qué sigue?","o":["Nada, regresa la licencia completa","Dos años manejando solo con bloqueo de encendido","Otro año completo de suspensión","Un nuevo examen de manejo y nada más"],"h1":"La restricción dura el doble que la suspensión.","h2":"Según la ley de Kansas, la primera negativa a una prueba trae una suspensión de un año, seguida de dos años manejando solo un vehículo con dispositivo de bloqueo de encendido.","p":"Correcto. Dos años con bloqueo de encendido."},"ref":{"doc":"KS","page":null}},{"id":"ks-134","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Kansas law, a driver fails an alcohol test for the first time with a level of .15 or higher. How long is the suspension?","o":["30 days","90 days","One year","Five years"],"h1":"A very high level brings a much longer penalty than a first .08.","h2":"Under Kansas law, a first test failure at .15 or higher brings a one-year suspension, followed by one year with an ignition interlock.","p":"Right. One year."},"es":{"q":"Según la ley de Kansas, un conductor reprueba una prueba de alcohol por primera vez con un nivel de .15 o más. ¿Cuánto dura la suspensión?","o":["30 días","90 días","Un año","Cinco años"],"h1":"Un nivel muy alto trae una pena mucho más larga que un primer .08.","h2":"Según la ley de Kansas, reprobar la prueba por primera vez con .15 o más trae una suspensión de un año, seguida de un año con bloqueo de encendido.","p":"Correcto. Un año."},"ref":{"doc":"KS","page":null}},{"id":"ks-135","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"What does the Kansas implied consent law mean?","o":["You may refuse any test without penalty","Police need a warrant for every breath test","Only drivers under 21 can be tested","Your license means you agreed to be tested"],"h1":"You agreed to something when you got your license.","h2":"Under Kansas implied consent law, getting a driver's license means you have agreed to a lawfully requested test of your blood, breath or urine if you are suspected of impaired driving.","p":"Right. Your license means you agreed to be tested."},"es":{"q":"¿Qué significa la ley de consentimiento implícito de Kansas?","o":["Puede negarse a cualquier prueba sin castigo","La policía necesita una orden para cada prueba de aliento","Solo se puede hacer la prueba a menores de 21","Su licencia significa que aceptó la prueba"],"h1":"Usted aceptó algo cuando obtuvo su licencia.","h2":"Según la ley de consentimiento implícito de Kansas, obtener una licencia significa que usted aceptó una prueba legal de sangre, aliento u orina si se sospecha que maneja afectado.","p":"Correcto. Su licencia significa que aceptó la prueba."},"ref":{"doc":"KS","page":24}},{"id":"ks-136","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Kansas handbook says more than half of crashes that cause injury or death happen under which conditions?","o":["At under 40 mph and within 25 miles of home","Only on interstates at night","At over 70 mph far from home","Only in snow"],"h1":"Short, slow, everyday trips.","h2":"The Kansas handbook says more than half of crashes that cause injury or death happen at speeds under 40 mph and within 25 miles of home, so wear your belt on every trip.","p":"Right. Slow speeds, close to home."},"es":{"q":"Según el manual de Kansas, ¿en qué condiciones ocurren más de la mitad de los choques que causan lesiones o muertes?","o":["A menos de 40 mph y a menos de 25 millas de casa","Solo en interestatales de noche","A más de 70 mph lejos de casa","Solo con nieve"],"h1":"Viajes cortos, lentos, de todos los días.","h2":"El manual de Kansas dice que más de la mitad de los choques con lesiones o muertes ocurren a menos de 40 mph y a menos de 25 millas de casa, así que use el cinturón en cada viaje.","p":"Correcto. A poca velocidad y cerca de casa."},"ref":{"doc":"KS","page":27}},{"id":"ks-137","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"The Kansas handbook gives a distance to lower the risk of injury from an air bag. How far should the center of your chest be from the center of the steering wheel?","o":["At least 2 inches","At least 10 inches","Exactly 24 inches","It does not matter"],"h1":"About the length of a pencil.","h2":"The Kansas handbook says to adjust your seat so there are at least 10 inches between the center of your chest and the center of the steering wheel.","p":"Right. At least 10 inches."},"es":{"q":"El manual de Kansas da una distancia para bajar el riesgo de lesión por la bolsa de aire. ¿A qué distancia debe estar el centro de su pecho del centro del volante?","o":["Al menos 2 pulgadas","Al menos 10 pulgadas","Exactamente 24 pulgadas","No importa"],"h1":"Como el largo de un lápiz.","h2":"El manual de Kansas dice que ajuste su asiento para que haya al menos 10 pulgadas entre el centro de su pecho y el centro del volante.","p":"Correcto. Al menos 10 pulgadas."},"ref":{"doc":"KS","page":28}},{"id":"ks-138","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, children of what age should ride in the back seat to avoid air bag injuries?","o":["4 and under only","8 and under","12 and under","16 and under"],"h1":"It goes up to about the start of the teen years.","h2":"The Kansas handbook says children age 12 and under should sit in the back seat to avoid injury from an air bag.","p":"Right. 12 and under ride in back."},"es":{"q":"Según el manual de Kansas, ¿hasta qué edad deben viajar los niños en el asiento trasero para evitar lesiones por la bolsa de aire?","o":["Solo hasta los 4 años","Hasta los 8 años","Hasta los 12 años","Hasta los 16 años"],"h1":"Llega más o menos al inicio de la adolescencia.","h2":"El manual de Kansas dice que los niños de 12 años o menos deben ir en el asiento trasero para evitar lesiones por la bolsa de aire.","p":"Correcto. Hasta los 12 años van atrás."},"ref":{"doc":"KS","page":28}},{"id":"ks-139","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Kansas handbook, how long should an infant ride in a rear-facing seat?","o":["Until 3 months old","Until they can sit up alone","Until they weigh 10 pounds","Until at least age 1 and 20 pounds"],"h1":"Two things must both be true before turning the seat around.","h2":"The Kansas handbook says infants should ride rear-facing in the back seat from birth to at least age one and until they weigh at least 20 pounds.","p":"Right. At least one year and 20 pounds."},"es":{"q":"Según el manual de Kansas, ¿hasta cuándo debe viajar un bebé en un asiento mirando hacia atrás?","o":["Hasta los 3 meses","Hasta que puedan sentarse solos","Hasta que pesen 10 libras","Hasta al menos 1 año y 20 libras"],"h1":"Dos cosas deben cumplirse antes de voltear el asiento.","h2":"El manual de Kansas dice que los bebés deben ir mirando hacia atrás en el asiento trasero desde que nacen hasta tener al menos un año y pesar al menos 20 libras.","p":"Correcto. Al menos un año y 20 libras."},"ref":{"doc":"KS","page":28}},{"id":"ks-140","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Kansas handbook describes an \"enhanced\" side mirror setting. What does it add?","o":["About 12 to 16 degrees more view to each side","A view of your own car's sides","A clearer view straight behind","Nothing, it is only for trucks"],"h1":"You lean your head about 5 inches before setting each mirror.","h2":"The Kansas handbook says the enhanced mirror setting adds about 12 to 16 degrees of extra view on each side of the vehicle.","p":"Right. About 12 to 16 degrees more on each side."},"es":{"q":"El manual de Kansas describe un ajuste \"mejorado\" de los espejos laterales. ¿Qué agrega?","o":["Unos 12 a 16 grados más de vista a cada lado","Ver los costados de su propio auto","Una vista más clara justo detrás","Nada, es solo para camiones"],"h1":"Usted inclina la cabeza unas 5 pulgadas antes de ajustar cada espejo.","h2":"El manual de Kansas dice que el ajuste mejorado de los espejos agrega unos 12 a 16 grados de vista extra a cada lado del vehículo.","p":"Correcto. Unos 12 a 16 grados más a cada lado."},"ref":{"doc":"KS","page":26}},{"id":"ks-141","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, when is the traditional side mirror setting (seeing the edge of your own car) more useful?","o":["On empty, straight highways","When towing or backing in tight spots","Only when driving at night","Only in heavy rain or snow"],"h1":"It helps when you need to see right along your car's sides.","h2":"The Kansas handbook says the traditional mirror setting may be better when towing or backing in tight areas.","p":"Right. When towing or backing in tight spaces."},"es":{"q":"Según el manual de Kansas, ¿cuándo es más útil el ajuste tradicional de los espejos laterales (viendo el borde de su propio auto)?","o":["En carreteras vacías y rectas","Al remolcar o dar reversa en lugares estrechos","Solo al manejar de noche","Solo con lluvia o nieve fuerte"],"h1":"Ayuda cuando necesita ver justo a lo largo de los costados de su auto.","h2":"El manual de Kansas dice que el ajuste tradicional de los espejos puede ser mejor al remolcar o al dar reversa en lugares estrechos.","p":"Correcto. Al remolcar o dar reversa en lugares estrechos."},"ref":{"doc":"KS","page":29}},{"id":"ks-142","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"The Kansas handbook says to check what before you start your car's engine?","o":["That the radio is off","That the windows are down","That the parking brake is set","That the headlights are on high beam"],"h1":"It keeps the car from rolling.","h2":"The Kansas handbook says to make sure the parking brake is set before you start the vehicle.","p":"Right. Set the parking brake first."},"es":{"q":"Según el manual de Kansas, ¿qué debe revisar antes de arrancar el motor?","o":["Que la radio esté apagada","Que las ventanas estén abajo","Que el freno de mano esté puesto","Que los faros estén en luz alta"],"h1":"Evita que el auto se mueva.","h2":"El manual de Kansas dice que se asegure de que el freno de mano esté puesto antes de arrancar el vehículo.","p":"Correcto. Primero ponga el freno de mano."},"ref":{"doc":"KS","page":30}},{"id":"ks-143","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"For hand-to-hand (push-pull) steering, where does the Kansas handbook say to hold the wheel?","o":["At 10 and 2 o'clock","At 12 o'clock with one hand","At 9 and 3, crossing your arms","Near 7-8 and 4-5 o'clock"],"h1":"Lower on the wheel, so your arms stay clear of the air bag.","h2":"The Kansas handbook says for hand-to-hand steering, hold the wheel with the left hand between 7 and 8 o'clock and the right hand between 4 and 5 o'clock.","p":"Right. Seven-to-eight and four-to-five."},"es":{"q":"Para girar mano a mano (empujar y jalar), ¿dónde dice el manual de Kansas que tome el volante?","o":["A las 10 y las 2","A las 12 con una mano","A las 9 y las 3, cruzando los brazos","Cerca de las 7-8 y las 4-5"],"h1":"Más abajo en el volante, para que los brazos no estorben a la bolsa de aire.","h2":"El manual de Kansas dice que para girar mano a mano tome el volante con la mano izquierda entre las 7 y las 8 y la derecha entre las 4 y las 5.","p":"Correcto. Entre las 7 y 8, y entre las 4 y 5."},"ref":{"doc":"KS","page":31}},{"id":"ks-144","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Kansas handbook, when should you use hand-over-hand steering?","o":["At low speeds, like when parking","On the highway above 50 mph","Only when backing up","Never, it is not allowed"],"h1":"Big turns of the wheel at slow speed.","h2":"The Kansas handbook says to use hand-over-hand steering when turning at low speeds, such as at an intersection or when parking.","p":"Right. At low speeds."},"es":{"q":"Según el manual de Kansas, ¿cuándo debe usar la técnica de mano sobre mano para girar?","o":["A baja velocidad, como al estacionarse","En la carretera a más de 50 mph","Solo al dar reversa","Nunca, no se permite"],"h1":"Giros grandes del volante a poca velocidad.","h2":"El manual de Kansas dice que use la técnica de mano sobre mano al girar a baja velocidad, como en una intersección o al estacionarse.","p":"Correcto. A baja velocidad."},"ref":{"doc":"KS","page":31}},{"id":"ks-145","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"When swerving to avoid a hazard, the Kansas handbook says to limit your steering to no more than how much?","o":["45 degrees","180 degrees (half a turn)","360 degrees (a full turn)","Two full turns"],"h1":"More than half a turn often makes the car lose traction.","h2":"The Kansas handbook says to limit steering to no more than 180 degrees when evading a problem, because more input often causes traction loss.","p":"Right. No more than 180 degrees."},"es":{"q":"Al esquivar un peligro, ¿cuánto como máximo dice el manual de Kansas que gire el volante?","o":["45 grados","180 grados (media vuelta)","360 grados (una vuelta completa)","Dos vueltas completas"],"h1":"Más de media vuelta suele hacer que el auto pierda tracción.","h2":"El manual de Kansas dice que limite el giro a no más de 180 grados al esquivar un problema, porque girar más suele causar pérdida de tracción.","p":"Correcto. No más de 180 grados."},"ref":{"doc":"KS","page":31}},{"id":"ks-146","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, when is one-hand steering acceptable?","o":["On long, straight highways","Whenever you feel tired","Only when backing or using a control","Whenever you are drinking coffee"],"h1":"Your other hand should only leave the wheel for a short reach.","h2":"The Kansas handbook says to use one-hand steering only when backing or when reaching briefly for a vehicle control such as wipers or lights.","p":"Right. Only when backing or using a control."},"es":{"q":"Según el manual de Kansas, ¿cuándo se acepta manejar con una sola mano?","o":["En carreteras largas y rectas","Siempre que se sienta cansado","Solo al dar reversa o usar un control","Siempre que esté tomando café"],"h1":"La otra mano solo debe soltar el volante por un momento.","h2":"El manual de Kansas dice que use una sola mano solo al dar reversa o al alcanzar un momento un control del vehículo, como los limpiaparabrisas o las luces.","p":"Correcto. Solo al dar reversa o usar un control."},"ref":{"doc":"KS","page":31}},{"id":"ks-147","scope":"KS","cat":"signals","sign":null,"c":3,"en":{"q":"In Kansas, you are stopped at a red light on a one-way street and want to turn left onto another one-way street. What may you do?","o":["Never turn left on a red light","Turn left without stopping first","Wait for a green arrow only","Stop fully, then turn if allowed and clear"],"h1":"Kansas allows some left turns on red.","h2":"In Kansas, a left turn on red may be allowed from a one-way street onto another one-way street, after stopping and checking for traffic and pedestrians.","p":"Right. Stop, check, then turn if it is allowed."},"es":{"q":"En Kansas, usted está detenido en un semáforo en rojo en una calle de un solo sentido y quiere girar a la izquierda hacia otra calle de un solo sentido. ¿Qué puede hacer?","o":["Nunca girar a la izquierda en rojo","Girar a la izquierda sin detenerse","Esperar solo una flecha verde","Alto total y luego girar si se permite y está libre"],"h1":"Kansas permite algunos giros a la izquierda en rojo.","h2":"En Kansas, se puede permitir un giro a la izquierda en rojo de una calle de un solo sentido a otra de un solo sentido, después de detenerse y revisar el tráfico y los peatones.","p":"Correcto. Alto, revise y gire si está permitido."},"ref":{"doc":"KS","page":34}},{"id":"ks-148","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"The Kansas handbook gives which advice for driving a stick-shift car over railroad tracks?","o":["Do not shift gears while crossing, so you do not stall","Shift to a lower gear in the middle of the tracks","Shift to neutral and coast across","Stop on the tracks to look both ways"],"h1":"A stalled car on the tracks is the danger.","h2":"The Kansas handbook says it is wise not to shift gears while crossing railroad tracks, in case you stall.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"¿Qué consejo da el manual de Kansas para cruzar vías de tren con un auto de transmisión manual?","o":["No cambiar de velocidad al cruzar, para no apagar el motor","Bajar de velocidad a la mitad de las vías","Poner neutral y cruzar sin acelerar","Detenerse sobre las vías para mirar a los dos lados"],"h1":"El peligro es que el auto se apague sobre las vías.","h2":"El manual de Kansas dice que es mejor no cambiar de velocidad al cruzar las vías del tren, por si el motor se apaga.","p":"Correcto. No cambie de velocidad sobre las vías."},"ref":{"doc":"KS","page":37}},{"id":"ks-149","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kansas, what happens to the fine for speeding in a work zone?","o":["It is cut in half","It is doubled","It stays the same","It becomes a warning"],"h1":"Work zones protect workers, so the penalty is bigger.","h2":"The Kansas handbook says fines for speeding in a work zone are doubled.","p":"Right. Work zone speeding fines are doubled."},"es":{"q":"En Kansas, ¿qué pasa con la multa por exceso de velocidad en una zona de obras?","o":["Se reduce a la mitad","Se duplica","Queda igual","Se convierte en advertencia"],"h1":"Las zonas de obras protegen a los trabajadores, así que la multa es mayor.","h2":"El manual de Kansas dice que las multas por exceso de velocidad en una zona de obras se duplican.","p":"Correcto. La multa se duplica."},"ref":{"doc":"KS","page":39}},{"id":"ks-150","scope":"KS","cat":"signals","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, what does a flashing yellow X over a reversible lane mean?","o":["The lane is closed","You may drive straight in it","The lane may be used only for turning","Speed up to leave the lane"],"h1":"It is different from a steady yellow X.","h2":"The Kansas handbook says a flashing yellow X over a reversible lane means the lane is for turning only.","p":"Right. Turning only."},"es":{"q":"Según el manual de Kansas, ¿qué significa una X amarilla intermitente sobre un carril reversible?","o":["El carril está cerrado","Puede seguir derecho en él","El carril solo se puede usar para girar","Acelere para salir del carril"],"h1":"Es distinta de una X amarilla fija.","h2":"El manual de Kansas dice que una X amarilla intermitente sobre un carril reversible significa que el carril es solo para girar.","p":"Correcto. Solo para girar."},"ref":{"doc":"KS","page":45}},{"id":"ks-151","scope":"KS","cat":"signals","sign":null,"c":3,"en":{"q":"In Kansas, a lane sign says \"HOV 3\". Who may use that lane?","o":["Only city and school buses","Only cars with three doors","Any vehicle before 3 p.m.","Vehicles carrying at least three people"],"h1":"HOV means high occupancy vehicle.","h2":"In Kansas, an HOV 3 sign means there must be at least three people in the vehicle to use that lane.","p":"Right. At least three people."},"es":{"q":"En Kansas, la señal de un carril dice \"HOV 3\". ¿Quién puede usar ese carril?","o":["Solo autobuses urbanos y escolares","Solo autos de tres puertas","Cualquier vehículo antes de las 3 p.m.","Vehículos con al menos tres personas"],"h1":"HOV significa vehículo de alta ocupación.","h2":"En Kansas, una señal HOV 3 significa que debe haber al menos tres personas en el vehículo para usar ese carril.","p":"Correcto. Al menos tres personas."},"ref":{"doc":"KS","page":45}},{"id":"ks-152","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"You missed your turn on a Kansas street. May you back up in the travel lane to reach it?","o":["No, except to parallel park","Yes, if you use your hazard lights","Yes, if no car is right behind you","Only on one-way streets"],"h1":"Drivers behind you do not expect a car to come backward.","h2":"In Kansas, it is illegal to back up in any travel lane except to parallel park; if you miss a turn, go on to a safe place to turn around.","p":"Right. Do not back up; go on and turn around safely."},"es":{"q":"Usted se pasó de su vuelta en una calle de Kansas. ¿Puede dar reversa en el carril para llegar a ella?","o":["No, salvo para estacionarse en paralelo","Sí, si usa las luces intermitentes","Sí, si no hay un auto justo detrás","Solo en calles de un solo sentido"],"h1":"Los conductores de atrás no esperan un auto que viene en reversa.","h2":"En Kansas, es ilegal dar reversa en cualquier carril de circulación, salvo para estacionarse en paralelo; si se pasa de una vuelta, siga hasta un lugar seguro para dar la vuelta.","p":"Correcto. No dé reversa; siga y dé la vuelta con seguridad."},"ref":{"doc":"KS","page":45}},{"id":"ks-153","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"On a Kansas road with three or more lanes going your way and heavy traffic entering and exiting, which lane does the handbook suggest?","o":["The far left lane","The center lane","The far right lane","The shoulder"],"h1":"It keeps you away from merging traffic on one side and passing traffic on the other.","h2":"The Kansas handbook says that on a road with three or more lanes going the same way, use the center lane, especially when many cars are entering or exiting.","p":"Right. The center lane."},"es":{"q":"En un camino de Kansas con tres o más carriles en su dirección y mucho tráfico entrando y saliendo, ¿qué carril sugiere el manual?","o":["El carril de la extrema izquierda","El carril del centro","El carril de la extrema derecha","El acotamiento"],"h1":"Lo aleja del tráfico que entra por un lado y del que rebasa por el otro.","h2":"El manual de Kansas dice que en un camino con tres o más carriles en la misma dirección use el carril del centro, sobre todo cuando muchos autos entran o salen.","p":"Correcto. El carril del centro."},"ref":{"doc":"KS","page":46}},{"id":"ks-154","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"You are on a Kansas interstate going the wrong way to your destination. What should you do?","o":["Use the paved crossover in the median","Make a U-turn across the grass median","Go on to the next exit and turn around there","Back up on the shoulder"],"h1":"Median crossovers are only for emergency vehicles.","h2":"In Kansas, on the interstate you should go to the next exit and turn around; it is illegal to cross the median or use crossovers reserved for emergency vehicles.","p":"Right. Use the next exit."},"es":{"q":"Usted va por una interestatal de Kansas en la dirección equivocada. ¿Qué debe hacer?","o":["Usar el cruce pavimentado de la mediana","Dar vuelta en U por el pasto de la mediana","Seguir hasta la próxima salida y dar la vuelta allí","Dar reversa por el acotamiento"],"h1":"Los cruces de la mediana son solo para vehículos de emergencia.","h2":"En Kansas, en la interestatal debe seguir hasta la próxima salida y dar la vuelta; es ilegal cruzar la mediana o usar los cruces reservados para vehículos de emergencia.","p":"Correcto. Use la próxima salida."},"ref":{"doc":"KS","page":47}},{"id":"ks-155","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"According to the Kansas handbook, what is the safest way to turn around on a city street?","o":["A U-turn in the middle of the block","A three-point turn","Backing into an alley across traffic","Turning right and going around the block"],"h1":"It avoids most left turns across traffic.","h2":"The Kansas handbook says the safest way to change direction is to turn right and go around the block, which avoids most left turns across traffic.","p":"Right. Go around the block."},"es":{"q":"Según el manual de Kansas, ¿cuál es la forma más segura de dar la vuelta en una calle de la ciudad?","o":["Una vuelta en U a mitad de la cuadra","Una vuelta en tres movimientos","Dar reversa hacia un callejón cruzando el tráfico","Girar a la derecha y rodear la cuadra"],"h1":"Evita la mayoría de los giros a la izquierda cruzando el tráfico.","h2":"El manual de Kansas dice que la forma más segura de cambiar de dirección es girar a la derecha y rodear la cuadra, porque evita la mayoría de los giros a la izquierda cruzando el tráfico.","p":"Correcto. Rodee la cuadra."},"ref":{"doc":"KS","page":47}},{"id":"ks-156","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"For a two-point turnabout using a driveway, what does the Kansas handbook say is the safest way?","o":["Back into the driveway, then drive forward out of it","Drive forward into the driveway, then back out into the street","Back out of the driveway into a busy street","Use the driveway on a four-lane road"],"h1":"You want to see traffic well when you leave the driveway.","h2":"The Kansas handbook says the safest two-point turnabout is to back into the driveway, so you can see traffic better when you pull out, and to use it only on two-lane roads.","p":"Right. Back in, then drive out forward."},"es":{"q":"Para dar la vuelta en dos movimientos usando una entrada de casa, ¿cuál dice el manual de Kansas que es la forma más segura?","o":["Entrar en reversa a la entrada y luego salir hacia adelante","Entrar de frente a la entrada y luego salir en reversa a la calle","Salir en reversa de la entrada a una calle con mucho tráfico","Usar la entrada en un camino de cuatro carriles"],"h1":"Quiere ver bien el tráfico al salir de la entrada.","h2":"El manual de Kansas dice que la vuelta en dos movimientos más segura es entrar en reversa a la entrada, para ver mejor el tráfico al salir, y usarla solo en caminos de dos carriles.","p":"Correcto. Entre en reversa y salga de frente."},"ref":{"doc":"KS","page":48}},{"id":"ks-157","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, when should you use a three-point turnabout?","o":["Whenever you miss a turn","Only if a U-turn or the block won't work","On any four-lane highway","At busy intersections downtown"],"h1":"The handbook calls it the most difficult and dangerous way to turn around.","h2":"The Kansas handbook says a three-point turnabout is the most difficult and dangerous turnabout, to be used only when the road is too narrow for a U-turn and you cannot go around the block.","p":"Right. Only as a last choice."},"es":{"q":"Según el manual de Kansas, ¿cuándo debe dar la vuelta en tres movimientos?","o":["Siempre que se pase de una vuelta","Solo si no puede dar vuelta en U ni rodear la cuadra","En cualquier carretera de cuatro carriles","En intersecciones concurridas del centro"],"h1":"El manual dice que es la forma más difícil y peligrosa de dar la vuelta.","h2":"El manual de Kansas dice que la vuelta en tres movimientos es la más difícil y peligrosa, y se usa solo cuando el camino es demasiado angosto para una vuelta en U y no se puede rodear la cuadra.","p":"Correcto. Solo como última opción."},"ref":{"doc":"KS","page":48}},{"id":"ks-158","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, at an intersection where more than one lane may turn, when should you get into the lane you will turn from?","o":["In the middle of the intersection","Right at the stop line","At least one block before the turn","After you start turning"],"h1":"Plan well ahead of the corner.","h2":"The Kansas handbook says that when several lanes turn, you should identify and enter your turning lane at least one block before the turn.","p":"Right. At least one block ahead."},"es":{"q":"En Kansas, en una intersección donde más de un carril puede girar, ¿cuándo debe pasarse al carril desde el que va a girar?","o":["A mitad de la intersección","Justo en la línea de alto","Al menos una cuadra antes de la vuelta","Después de empezar a girar"],"h1":"Planee mucho antes de la esquina.","h2":"El manual de Kansas dice que cuando varios carriles giran, debe identificar y entrar a su carril de giro al menos una cuadra antes de la vuelta.","p":"Correcto. Al menos una cuadra antes."},"ref":{"doc":"KS","page":47}},{"id":"ks-159","scope":"KS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"When you enter a roundabout in Kansas, about how fast should you be going?","o":["5 mph or less","30 to 35 mph","The posted speed of the road","About 15 to 20 mph"],"h1":"You must handle a sharp curve.","h2":"The Kansas handbook says to slow to about 15 to 20 mph when entering a roundabout or traffic circle.","p":"Right. About 15 to 20 mph."},"es":{"q":"Al entrar a una glorieta en Kansas, ¿a qué velocidad aproximada debe ir?","o":["5 mph o menos","30 a 35 mph","La velocidad señalada del camino","Unas 15 a 20 mph"],"h1":"Debe tomar una curva cerrada.","h2":"El manual de Kansas dice que baje a unas 15 a 20 mph al entrar a una glorieta o círculo de tránsito.","p":"Correcto. Unas 15 a 20 mph."},"ref":{"doc":"KS","page":49}},{"id":"ks-160","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kansas, you and another car arrive at a traffic circle at the same time. The other car is on your right. What should you do?","o":["Yield to the car on your right","Go first, because you are on the left","Honk and go","Stop inside the circle"],"h1":"The usual same-time rule applies here too.","h2":"The Kansas handbook says that if another vehicle arrives at a traffic circle at the same time as you and is on your right, you should yield to it.","p":"Right. Yield to the car on your right."},"es":{"q":"En Kansas, usted y otro auto llegan a un círculo de tránsito al mismo tiempo. El otro auto está a su derecha. ¿Qué debe hacer?","o":["Ceder el paso al auto de su derecha","Pasar primero, porque usted está a la izquierda","Tocar la bocina y seguir","Detenerse dentro del círculo"],"h1":"Aquí también se usa la regla normal de llegar al mismo tiempo.","h2":"El manual de Kansas dice que si otro vehículo llega al círculo de tránsito al mismo tiempo que usted y está a su derecha, debe cederle el paso.","p":"Correcto. Ceda el paso al auto de la derecha."},"ref":{"doc":"KS","page":49}},{"id":"ks-161","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, a school bus has stopped with red lights flashing on the other side of a road that has a center turn lane. What must you do?","o":["Keep going, the turn lane separates you","Stop, because a center turn lane is not a barrier","Slow to 20 mph and pass","Stop only if children are crossing"],"h1":"Only a median or physical barrier lets opposite traffic keep going.","h2":"In Kansas, you must stop for a school bus when there is a center turning lane, whether the bus is on your side or the other side of the road.","p":"Right. You must stop."},"es":{"q":"En Kansas, un autobús escolar se detuvo con las luces rojas encendidas del otro lado de un camino que tiene un carril central para girar. ¿Qué debe hacer?","o":["Seguir, porque el carril de giro los separa","Detenerse, porque un carril central para girar no es una barrera","Bajar a 20 mph y pasar","Detenerse solo si hay niños cruzando"],"h1":"Solo una mediana o una barrera física permite seguir al tráfico contrario.","h2":"En Kansas, debe detenerse ante un autobús escolar cuando hay un carril central para girar, esté el autobús de su lado o del otro lado del camino.","p":"Correcto. Debe detenerse."},"ref":{"doc":"KS","page":51}},{"id":"ks-162","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kansas, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Straight ahead","Toward the curb","It does not matter"],"h1":"If the car rolls, the curb should stop it.","h2":"The Kansas handbook says that when parking downhill, turn your wheels toward the curb or road edge so the car would roll away from traffic.","p":"Right. Toward the curb."},"es":{"q":"En Kansas, usted se estaciona cuesta abajo junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Lejos de la acera","Derechas","Hacia la acera","No importa"],"h1":"Si el auto se mueve, la acera debe detenerlo.","h2":"El manual de Kansas dice que al estacionarse cuesta abajo gire las llantas hacia la acera o la orilla del camino, para que el auto se aleje del tráfico si rueda.","p":"Correcto. Hacia la acera."},"ref":{"doc":"KS","page":52}},{"id":"ks-163","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, you park facing uphill next to a curb. Which way should your front wheels point?","o":["Toward the curb","Straight ahead","It does not matter","Away from the curb"],"h1":"Let the car roll back gently until the tire touches the curb.","h2":"The Kansas handbook says that when parking uphill with a curb, turn the wheels away from the curb and let the car roll back until the tire touches it.","p":"Right. Away from the curb."},"es":{"q":"En Kansas, usted se estaciona cuesta arriba junto a una acera. ¿Hacia dónde deben apuntar las llantas delanteras?","o":["Hacia la acera","Derechas","No importa","Lejos de la acera"],"h1":"Deje que el auto ruede un poco hacia atrás hasta que la llanta toque la acera.","h2":"El manual de Kansas dice que al estacionarse cuesta arriba con acera gire las llantas lejos de la acera y deje que el auto ruede hacia atrás hasta que la llanta la toque.","p":"Correcto. Lejos de la acera."},"ref":{"doc":"KS","page":52}},{"id":"ks-164","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"According to the Kansas handbook, what does a white-painted curb mean?","o":["Only short stops are allowed","Loading zone","Fire zone, no parking","Parking for people with disabilities"],"h1":"It is the color for a quick stop.","h2":"The Kansas handbook says a white curb means only short stops are permitted.","p":"Right. Short stops only."},"es":{"q":"Según el manual de Kansas, ¿qué significa una acera pintada de blanco?","o":["Solo se permiten paradas cortas","Zona de carga","Zona de bomberos, no estacionarse","Estacionamiento para personas con discapacidad"],"h1":"Es el color de una parada rápida.","h2":"El manual de Kansas dice que una acera blanca significa que solo se permiten paradas cortas.","p":"Correcto. Solo paradas cortas."},"ref":{"doc":"KS","page":55}},{"id":"ks-165","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, what does a yellow-painted curb usually mean?","o":["Parking for people with disabilities","A loading zone or another restriction","Free parking all day","A fire zone"],"h1":"Think of trucks dropping off goods.","h2":"The Kansas handbook says a yellow curb shows a loading zone or some other restriction.","p":"Right. A loading zone or other limit."},"es":{"q":"Según el manual de Kansas, ¿qué significa normalmente una acera pintada de amarillo?","o":["Estacionamiento para personas con discapacidad","Una zona de carga u otra restricción","Estacionamiento gratis todo el día","Una zona de bomberos"],"h1":"Piense en camiones que dejan mercancía.","h2":"El manual de Kansas dice que una acera amarilla indica una zona de carga u otra restricción.","p":"Correcto. Zona de carga u otro límite."},"ref":{"doc":"KS","page":55}},{"id":"ks-166","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"The Kansas handbook says that when you walk to your car parked on the street, how should you approach the driver's door?","o":["From the back of the car, looking at the curb","From the sidewalk side, climbing over","From the front of the car, keys in hand, facing traffic","It does not matter"],"h1":"You want to see traffic coming toward you.","h2":"The Kansas handbook says to approach the driver's door from the front of the vehicle with your key in hand, so you can see oncoming traffic.","p":"Right. From the front, facing traffic."},"es":{"q":"El manual de Kansas dice que cuando camina a su auto estacionado en la calle, ¿cómo debe llegar a la puerta del conductor?","o":["Desde atrás del auto, mirando la acera","Desde el lado de la banqueta, pasando por encima","Desde el frente del auto, con la llave en la mano, mirando el tráfico","No importa"],"h1":"Quiere ver el tráfico que viene hacia usted.","h2":"El manual de Kansas dice que llegue a la puerta del conductor desde el frente del vehículo, con la llave en la mano, para ver el tráfico que viene.","p":"Correcto. Desde el frente, mirando el tráfico."},"ref":{"doc":"KS","page":52}},{"id":"ks-167","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"On the highway, how far ahead does the Kansas handbook say you should look?","o":["About 100 feet ahead","One or two car lengths","Two city blocks","A quarter mile or more"],"h1":"It is much farther than in town.","h2":"The Kansas handbook says that on the highway you should look at least a quarter of a mile ahead.","p":"Right. At least a quarter mile."},"es":{"q":"En la carretera, ¿qué tan lejos dice el manual de Kansas que debe mirar hacia adelante?","o":["Unos 100 pies adelante","Uno o dos largos de auto","Dos cuadras de la ciudad","Un cuarto de milla o más"],"h1":"Es mucho más lejos que en la ciudad.","h2":"El manual de Kansas dice que en la carretera debe mirar al menos un cuarto de milla hacia adelante.","p":"Correcto. Al menos un cuarto de milla."},"ref":{"doc":"KS","page":56}},{"id":"ks-168","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"The Kansas handbook says a good \"visual lead\" is how far ahead of your vehicle?","o":["20 to 30 seconds","2 to 3 seconds","1 minute","5 seconds"],"h1":"Use the counting method with a fixed object.","h2":"The Kansas handbook says a visual lead is an area 20 to 30 seconds ahead of the front of your vehicle.","p":"Right. 20 to 30 seconds ahead."},"es":{"q":"Según el manual de Kansas, ¿qué tan lejos delante de su vehículo está una buena \"vista anticipada\" (visual lead)?","o":["De 20 a 30 segundos","De 2 a 3 segundos","1 minuto","5 segundos"],"h1":"Use el método de contar con un objeto fijo.","h2":"El manual de Kansas dice que la vista anticipada es un área de 20 a 30 segundos delante del frente de su vehículo.","p":"Correcto. De 20 a 30 segundos."},"ref":{"doc":"KS","page":56}},{"id":"ks-169","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, at 60 mph you are driving too fast for your visibility if you cannot see at least how far ahead?","o":["100 feet","400 feet","150 feet","One mile"],"h1":"Stopping from 60 mph takes about 359 feet.","h2":"The Kansas handbook says that at 60 mph, if you cannot see at least 400 feet ahead, you are driving too fast for your visibility.","p":"Right. At least 400 feet."},"es":{"q":"Según el manual de Kansas, a 60 mph, ¿qué distancia mínima debe poder ver adelante para no ir demasiado rápido?","o":["100 pies","400 pies","150 pies","Una milla"],"h1":"Detenerse desde 60 mph toma unos 359 pies.","h2":"El manual de Kansas dice que a 60 mph, si no puede ver al menos 400 pies adelante, va demasiado rápido para lo que alcanza a ver.","p":"Correcto. Al menos 400 pies."},"ref":{"doc":"KS","page":57}},{"id":"ks-170","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, what is the average perception time for an alert driver?","o":["3 to 4 seconds","1 to 2 seconds","3/4 to 1 second","5 seconds"],"h1":"It is about one second or a little less.","h2":"The Kansas handbook says the average perception time for an alert driver is three-quarters of a second to one second.","p":"Right. About three-quarters of a second to one second."},"es":{"q":"Según el manual de Kansas, ¿cuál es el tiempo promedio de percepción de un conductor alerta?","o":["3 a 4 segundos","1 a 2 segundos","3/4 a 1 segundo","5 segundos"],"h1":"Es como un segundo o un poco menos.","h2":"El manual de Kansas dice que el tiempo promedio de percepción de un conductor alerta es de tres cuartos de segundo a un segundo.","p":"Correcto. De tres cuartos de segundo a un segundo."},"ref":{"doc":"KS","page":58}},{"id":"ks-171","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"According to the Kansas handbook, at 50 mph in ideal conditions, what is the minimum total stopping distance?","o":["About 55 feet","About 100 feet","About 158 feet","About 268 feet"],"h1":"Add seeing, reacting and braking together.","h2":"The Kansas handbook says that at 50 mph, counting perception, reaction and braking, your vehicle travels at least 268 feet before stopping.","p":"Right. About 268 feet."},"es":{"q":"Según el manual de Kansas, a 50 mph en condiciones ideales, ¿cuál es la distancia total mínima para detenerse?","o":["Unos 55 pies","Unos 100 pies","Unos 158 pies","Unos 268 pies"],"h1":"Sume ver, reaccionar y frenar.","h2":"El manual de Kansas dice que a 50 mph, sumando percepción, reacción y frenado, su vehículo recorre al menos 268 pies antes de detenerse.","p":"Correcto. Unos 268 pies."},"ref":{"doc":"KS","page":58}},{"id":"ks-172","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"On wet roads, how much does the Kansas handbook suggest you slow down below the recommended speed?","o":["About 10 mph","About 2 mph","About 30 mph","You do not need to slow down"],"h1":"A small but real cut in speed.","h2":"The Kansas handbook says to reduce your speed about 10 mph below recommended speeds on wet roads.","p":"Right. About 10 mph slower."},"es":{"q":"En caminos mojados, ¿cuánto sugiere el manual de Kansas que baje la velocidad por debajo de la recomendada?","o":["Unas 10 mph","Unas 2 mph","Unas 30 mph","No necesita bajar la velocidad"],"h1":"Una reducción pequeña pero real.","h2":"El manual de Kansas dice que baje la velocidad unas 10 mph por debajo de la recomendada en caminos mojados.","p":"Correcto. Unas 10 mph menos."},"ref":{"doc":"KS","page":59}},{"id":"ks-173","scope":"KS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, how much should you slow down when there is packed snow on the road?","o":["By about 5 mph","By half or more","By 10 mph","Not at all, if you have snow tires"],"h1":"It is a big cut, much more than for rain.","h2":"The Kansas handbook says to reduce your speed by half or more when there is packed snow on the road.","p":"Right. Half your speed or more."},"es":{"q":"Según el manual de Kansas, ¿cuánto debe bajar la velocidad cuando hay nieve compacta en el camino?","o":["Unas 5 mph","A la mitad o más","10 mph","Nada, si tiene llantas para nieve"],"h1":"Es una reducción grande, mucho más que con lluvia.","h2":"El manual de Kansas dice que baje su velocidad a la mitad o más cuando hay nieve compacta en el camino.","p":"Correcto. A la mitad o más."},"ref":{"doc":"KS","page":59}},{"id":"ks-174","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, above what speed do tires start to ride up on water and hydroplane?","o":["About 10 mph","About 20 mph","About 35 mph","About 70 mph"],"h1":"Below about 30 mph, modern tires keep stable traction.","h2":"The Kansas handbook says that above about 35 mph, tires start to ride up on pooled water and hydroplane; in heavy rain they can lose all traction at 45 to 50 mph.","p":"Right. Above about 35 mph."},"es":{"q":"Según el manual de Kansas, ¿a partir de qué velocidad las llantas empiezan a subirse sobre el agua y patinar (hidroplaneo)?","o":["Unas 10 mph","Unas 20 mph","Unas 35 mph","Unas 70 mph"],"h1":"Por debajo de unas 30 mph, las llantas modernas mantienen buena tracción.","h2":"El manual de Kansas dice que a más de unas 35 mph las llantas empiezan a subirse sobre el agua acumulada y a hidroplanear; con lluvia fuerte pueden perder toda la tracción a 45 o 50 mph.","p":"Correcto. A más de unas 35 mph."},"ref":{"doc":"KS","page":60}},{"id":"ks-175","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"According to the Kansas handbook, driving how much slower than the flow of traffic can be as dangerous as speeding?","o":["1 mph slower","5 mph slower","Any speed below the limit","More than 15 mph slower"],"h1":"Cars bunch up and take risks to pass you.","h2":"The Kansas handbook says driving more than 15 mph slower than the traffic flow can be just as dangerous as speeding.","p":"Right. More than 15 mph slower."},"es":{"q":"Según el manual de Kansas, ¿manejar qué tanto más despacio que el tráfico puede ser tan peligroso como ir con exceso de velocidad?","o":["1 mph más despacio","5 mph más despacio","Cualquier velocidad debajo del límite","Más de 15 mph más despacio"],"h1":"Los autos se amontonan y se arriesgan para rebasarlo.","h2":"El manual de Kansas dice que manejar más de 15 mph más despacio que el flujo del tráfico puede ser tan peligroso como el exceso de velocidad.","p":"Correcto. Más de 15 mph más despacio."},"ref":{"doc":"KS","page":60}},{"id":"ks-176","scope":"KS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Kansas handbook sums up using anti-lock brakes (ABS) in three words. What are they?","o":["Search, Stomp, Steer","Stop, Look, Listen","Pump, Pause, Pull","Slow, Shift, Stop"],"h1":"Look for space, press the pedal hard, and turn toward the space.","h2":"The Kansas handbook gives the basics for ABS as Search for open space, Stomp firmly on the brake, and Steer to the open space.","p":"Right. Search, Stomp, Steer."},"es":{"q":"El manual de Kansas resume el uso de los frenos antibloqueo (ABS) en tres palabras en inglés. ¿Cuáles son?","o":["Search, Stomp, Steer (buscar, pisar fuerte, dirigir)","Stop, Look, Listen (parar, mirar, escuchar)","Pump, Pause, Pull (bombear, pausar, jalar)","Slow, Shift, Stop (frenar, cambiar, parar)"],"h1":"Busque espacio, pise fuerte el pedal y gire hacia ese espacio.","h2":"El manual de Kansas da lo básico del ABS como Search, Stomp, Steer: buscar un espacio libre, pisar el freno con firmeza y dirigir el auto hacia ese espacio.","p":"Correcto. Search, Stomp, Steer."},"ref":{"doc":"KS","page":62}},{"id":"ks-177","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kansas, a driver is tailgating you and there is no empty lane to let them pass. How much should you add to your own following distance?","o":["Nothing","Half a second","Ten seconds","2 to 3 seconds"],"h1":"More room ahead gives you time to stop gently.","h2":"The Kansas handbook says that if you are followed too closely, increase your following distance by 2 to 3 seconds so you have more time and space to stop.","p":"Right. Add 2 to 3 seconds."},"es":{"q":"En Kansas, un conductor va pegado detrás de usted y no hay un carril libre para dejarlo pasar. ¿Cuánto debe aumentar su propia distancia de seguimiento?","o":["Nada","Medio segundo","Diez segundos","De 2 a 3 segundos"],"h1":"Más espacio adelante le da tiempo para frenar suavemente.","h2":"El manual de Kansas dice que si lo siguen demasiado cerca, aumente su distancia de seguimiento de 2 a 3 segundos para tener más tiempo y espacio para detenerse.","p":"Correcto. Aumente de 2 a 3 segundos."},"ref":{"doc":"KS","page":64}},{"id":"ks-178","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"When merging with traffic in Kansas, what size gap does the handbook say to look for?","o":["1 to 2 seconds","2 to 3 seconds","4 to 6 seconds","10 to 12 seconds"],"h1":"You move into the middle of it so both cars end up about 3 seconds apart.","h2":"The Kansas handbook says to choose a gap of 4 to 6 seconds when merging, changing lanes or entering a roadway.","p":"Right. A 4 to 6 second gap."},"es":{"q":"Al incorporarse al tráfico en Kansas, ¿de qué tamaño dice el manual que debe ser el espacio que busque?","o":["1 a 2 segundos","2 a 3 segundos","4 a 6 segundos","10 a 12 segundos"],"h1":"Usted entra a la mitad del espacio para que ambos autos queden a unos 3 segundos.","h2":"El manual de Kansas dice que elija un espacio de 4 a 6 segundos al incorporarse, cambiar de carril o entrar a un camino.","p":"Correcto. Un espacio de 4 a 6 segundos."},"ref":{"doc":"KS","page":64}},{"id":"ks-179","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"The Kansas handbook says passing can take as long as 20 to 30 seconds. What rule does it give because of this?","o":["Pass only one vehicle at a time","Always pass two cars at once to save time","Pass only at night","Pass on the shoulder when it is faster"],"h1":"Each extra vehicle makes the pass harder to judge.","h2":"The Kansas handbook says to pass only one vehicle at a time, because a pass can take 20 to 30 seconds and the time is hard to judge.","p":"Right. One vehicle at a time."},"es":{"q":"El manual de Kansas dice que rebasar puede tomar de 20 a 30 segundos. ¿Qué regla da por eso?","o":["Rebasar solo un vehículo a la vez","Rebasar siempre dos autos a la vez para ahorrar tiempo","Rebasar solo de noche","Rebasar por el acotamiento cuando es más rápido"],"h1":"Cada vehículo extra hace más difícil calcular la maniobra.","h2":"El manual de Kansas dice que rebase solo un vehículo a la vez, porque rebasar puede tomar de 20 a 30 segundos y ese tiempo es difícil de calcular.","p":"Correcto. Un vehículo a la vez."},"ref":{"doc":"KS","page":66}},{"id":"ks-180","scope":"KS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"On a two-lane Kansas highway at 55 mph, you should not start to pass when you are within what distance of a hill or curve ahead?","o":["100 feet","500 feet","One block","1/3 of a mile"],"h1":"Treat the hill or curve as if a car were coming from it.","h2":"The Kansas handbook says not to start passing within one-third of a mile of a hill or curve, because a car may be just out of sight.","p":"Right. Within one-third of a mile."},"es":{"q":"En una carretera de dos carriles de Kansas, a 55 mph, ¿a menos de qué distancia de una loma o curva no debe empezar a rebasar?","o":["100 pies","500 pies","Una cuadra","1/3 de milla"],"h1":"Trate la loma o la curva como si un auto viniera de ahí.","h2":"El manual de Kansas dice que no empiece a rebasar a menos de un tercio de milla de una loma o curva, porque un auto puede estar justo fuera de la vista.","p":"Correcto. A menos de un tercio de milla."},"ref":{"doc":"KS","page":66}},{"id":"ks-181","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Your car breaks down on a Kansas highway. How far behind it does the handbook say to place emergency flares?","o":["10 to 20 feet","50 feet","200 to 300 feet","One mile"],"h1":"Drivers need time to see them and change lanes.","h2":"The Kansas handbook says to place emergency flares about 200 to 300 feet behind your vehicle.","p":"Right. About 200 to 300 feet."},"es":{"q":"Su auto se descompone en una carretera de Kansas. ¿A qué distancia detrás de él dice el manual que ponga las bengalas de emergencia?","o":["10 a 20 pies","50 pies","200 a 300 pies","Una milla"],"h1":"Los conductores necesitan tiempo para verlas y cambiarse de carril.","h2":"El manual de Kansas dice que ponga las bengalas de emergencia unos 200 a 300 pies detrás de su vehículo.","p":"Correcto. Unos 200 a 300 pies."},"ref":{"doc":"KS","page":69}},{"id":"ks-182","scope":"KS","cat":"signals","sign":null,"c":0,"en":{"q":"At speeds above 40 mph, how far before a turn or lane change does the Kansas handbook advise you to signal?","o":["About 200 feet","About 50 feet","About 1,000 feet","Only as you start to turn"],"h1":"It is twice the 100-foot minimum.","h2":"The Kansas handbook advises signaling about 200 feet, or 3 to 5 seconds, before a turn or lane change at speeds above 40 mph.","p":"Right. About 200 feet."},"es":{"q":"A más de 40 mph, ¿con cuánta anticipación aconseja el manual de Kansas poner la direccional antes de girar o cambiar de carril?","o":["Unos 200 pies","Unos 50 pies","Unos 1,000 pies","Solo al empezar a girar"],"h1":"Es el doble del mínimo de 100 pies.","h2":"El manual de Kansas aconseja poner la direccional unos 200 pies, o de 3 a 5 segundos, antes de girar o cambiar de carril a más de 40 mph.","p":"Correcto. Unos 200 pies."},"ref":{"doc":"KS","page":69}},{"id":"ks-183","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Your right wheels drop off the pavement on a Kansas road. Before steering back, how slow does the handbook say to get?","o":["45 mph","35 mph","Keep your speed","25 mph or less"],"h1":"Slow down well before you try to get back on.","h2":"The Kansas handbook says to ease off the gas, brake gently, steer straight and slow to 25 mph or less, then turn the wheel about a quarter turn to get back on the pavement.","p":"Right. 25 mph or less."},"es":{"q":"Sus llantas derechas se salen del pavimento en un camino de Kansas. Antes de volver, ¿a qué velocidad dice el manual que baje?","o":["45 mph","35 mph","Mantenga su velocidad","25 mph o menos"],"h1":"Baje bien la velocidad antes de intentar volver.","h2":"El manual de Kansas dice que suelte el acelerador, frene suavemente, siga derecho y baje a 25 mph o menos; luego gire el volante como un cuarto de vuelta para volver al pavimento.","p":"Correcto. 25 mph o menos."},"ref":{"doc":"KS","page":76}},{"id":"ks-184","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, low beam headlights let you see about how far, so you can stop safely at about what speed?","o":["50 feet, about 20 mph","150 to 200 feet, about 45 mph","350 to 400 feet, about 65 mph","1,000 feet, about 75 mph"],"h1":"High beams reach about twice as far.","h2":"The Kansas handbook says low beams let you see clearly about 150 to 200 feet ahead, which allows a safe stop at about 45 mph.","p":"Right. 150 to 200 feet, about 45 mph."},"es":{"q":"Según el manual de Kansas, ¿qué tan lejos le dejan ver las luces bajas, y a qué velocidad puede detenerse con seguridad dentro de esa distancia?","o":["50 pies, unas 20 mph","150 a 200 pies, unas 45 mph","350 a 400 pies, unas 65 mph","1,000 pies, unas 75 mph"],"h1":"Las luces altas alcanzan como el doble.","h2":"El manual de Kansas dice que las luces bajas le dejan ver con claridad unos 150 a 200 pies adelante, lo que permite detenerse con seguridad a unas 45 mph.","p":"Correcto. 150 a 200 pies, unas 45 mph."},"ref":{"doc":"KS","page":77}},{"id":"ks-185","scope":"KS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"When driving at night on a road you do not know, how much extra following time does the Kansas handbook advise?","o":["None","Half a second","At least two extra seconds","At least ten extra seconds"],"h1":"Night alone adds one second; an unfamiliar road at night adds more.","h2":"The Kansas handbook advises adding at least one second for night driving and at least two seconds for unfamiliar roads at night.","p":"Right. At least two extra seconds."},"es":{"q":"Al manejar de noche por un camino que no conoce, ¿cuánto tiempo extra de seguimiento aconseja el manual de Kansas?","o":["Ninguno","Medio segundo","Al menos dos segundos extra","Al menos diez segundos extra"],"h1":"La noche sola suma un segundo; un camino desconocido de noche suma más.","h2":"El manual de Kansas aconseja agregar al menos un segundo para manejar de noche y al menos dos segundos en caminos desconocidos de noche.","p":"Correcto. Al menos dos segundos extra."},"ref":{"doc":"KS","page":77}},{"id":"ks-186","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, fog or blowing dust lets you see no more than 100 feet ahead. What is the fastest you can safely drive?","o":["30 mph","45 mph","55 mph","The posted limit"],"h1":"It is the same as the city speed limit.","h2":"The Kansas handbook says that when you cannot see farther than 100 feet ahead because of rain, snow, dust, smoke or fog, you cannot safely drive faster than 30 mph.","p":"Right. No faster than 30 mph."},"es":{"q":"En Kansas, la niebla o el polvo no le dejan ver más de 100 pies adelante. ¿Cuál es la velocidad máxima segura?","o":["30 mph","45 mph","55 mph","El límite señalado"],"h1":"Es igual al límite de velocidad en la ciudad.","h2":"El manual de Kansas dice que cuando no puede ver más de 100 pies adelante por lluvia, nieve, polvo, humo o niebla, no puede manejar con seguridad a más de 30 mph.","p":"Correcto. No más de 30 mph."},"ref":{"doc":"KS","page":77}},{"id":"ks-187","scope":"KS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kansas, you are walking on a road that has no sidewalk. Where should you walk?","o":["On the right side, with traffic","In the middle of the lane","On whichever side is shaded","On the left side, facing oncoming traffic"],"h1":"You want to see the cars coming at you.","h2":"The Kansas handbook says that if there is no sidewalk, pedestrians should walk on the left side of the street, facing oncoming traffic.","p":"Right. On the left, facing traffic."},"es":{"q":"En Kansas, usted camina por un camino que no tiene banqueta. ¿Por dónde debe caminar?","o":["Por el lado derecho, con el tráfico","Por el centro del carril","Por el lado que tenga sombra","Por el lado izquierdo, de frente al tráfico"],"h1":"Usted quiere ver los autos que vienen hacia usted.","h2":"El manual de Kansas dice que si no hay banqueta, los peatones deben caminar por el lado izquierdo de la calle, de frente al tráfico que viene.","p":"Correcto. Por la izquierda, de frente al tráfico."},"ref":{"doc":"KS","page":79}},{"id":"ks-188","scope":"KS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"Under Kansas's \"Dead Red\" rule, what may a bicyclist do at a red light that does not detect the bicycle?","o":["Cross after a fair wait, if safe","Ride through without stopping","Wait for a car to trigger the light","Ride on the sidewalk only"],"h1":"The light may never turn green for a bike.","h2":"The Kansas handbook says that under the Dead Red law, a bicyclist at a signal that will not respond may cross after waiting a reasonable time, as long as they do not impede cross traffic or cause a crash.","p":"Right. Wait a reasonable time, then cross safely."},"es":{"q":"Según la regla \"Dead Red\" de Kansas, ¿qué puede hacer un ciclista en un semáforo en rojo que no detecta la bicicleta?","o":["Cruzar tras una espera razonable, si es seguro","Pasar sin detenerse","Esperar a que un auto active el semáforo","Andar solo por la banqueta"],"h1":"El semáforo tal vez nunca se ponga en verde para una bicicleta.","h2":"El manual de Kansas dice que, según la ley Dead Red, un ciclista en un semáforo que no responde puede cruzar después de esperar un tiempo razonable, siempre que no estorbe al tráfico que cruza ni cause un choque.","p":"Correcto. Esperar un tiempo razonable y cruzar con cuidado."},"ref":{"doc":"KS","page":81}},{"id":"ks-189","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kansas, what light must a bicyclist use when riding at dusk?","o":["None, reflectors are enough","A headlight is required","Only a red taillight","Only flashing hazard lights"],"h1":"One light is required, another is strongly advised.","h2":"The Kansas handbook says a bicyclist must use a headlight at dusk, and a taillight is highly recommended.","p":"Right. A headlight is required."},"es":{"q":"En Kansas, ¿qué luz debe usar un ciclista al andar al atardecer?","o":["Ninguna, bastan los reflectores","Se exige una luz delantera","Solo una luz trasera roja","Solo luces intermitentes"],"h1":"Una luz es obligatoria y otra se recomienda mucho.","h2":"El manual de Kansas dice que el ciclista debe usar una luz delantera al atardecer y que se recomienda mucho una luz trasera.","p":"Correcto. La luz delantera es obligatoria."},"ref":{"doc":"KS","page":81}},{"id":"ks-190","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"The Kansas handbook describes the \"Dutch Reach\". What is it?","o":["A hand signal used by bicyclists","A way to check your tire tread","Opening your door with your far hand","A way to hold the steering wheel"],"h1":"It helps you avoid hitting cyclists with your door.","h2":"The Kansas handbook says the Dutch Reach means a driver opens the door with the right hand, which turns the body so you can see bicycles and traffic coming from behind.","p":"Right. Open the door with your far hand."},"es":{"q":"El manual de Kansas describe el \"Dutch Reach\". ¿Qué es?","o":["Una señal de mano de los ciclistas","Una forma de revisar el dibujo de las llantas","Abrir la puerta con la mano más lejana","Una forma de tomar el volante"],"h1":"Le ayuda a no golpear a ciclistas con la puerta.","h2":"El manual de Kansas dice que el Dutch Reach es abrir la puerta con la mano derecha, lo que gira el cuerpo para que vea las bicicletas y el tráfico que vienen por detrás.","p":"Correcto. Abra la puerta con la mano más lejana."},"ref":{"doc":"KS","page":82}},{"id":"ks-191","scope":"KS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"Under the Kansas handbook's description, a moped can have a top design speed of no more than how fast?","o":["15 mph","45 mph","55 mph","30 mph"],"h1":"It is the same as the city speed limit.","h2":"The Kansas handbook says a moped has a motor of no more than 3.5 brake horsepower, no more than 130 cc, an automatic transmission, and a top design speed of no more than 30 mph.","p":"Right. No more than 30 mph."},"es":{"q":"Según la descripción del manual de Kansas, ¿cuál es la velocidad máxima de diseño que puede tener un ciclomotor (moped)?","o":["15 mph","45 mph","55 mph","30 mph"],"h1":"Es igual al límite de velocidad en la ciudad.","h2":"El manual de Kansas dice que un ciclomotor tiene un motor de no más de 3.5 caballos de fuerza, no más de 130 cc, transmisión automática y una velocidad máxima de diseño de no más de 30 mph.","p":"Correcto. No más de 30 mph."},"ref":{"doc":"KS","page":83}},{"id":"ks-192","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, what following distance does the handbook advise behind a motorcycle?","o":["3 to 4 seconds or more","About 1 second","Two car lengths","About 10 seconds"],"h1":"Motorcycles can stop very quickly.","h2":"The Kansas handbook says to allow a 3 to 4 second following distance behind a motorcycle, scooter or moped, and more in wet conditions.","p":"Right. 3 to 4 seconds, more when wet."},"es":{"q":"En Kansas, ¿qué distancia de seguimiento aconseja el manual detrás de una motocicleta?","o":["3 a 4 segundos o más","Más o menos 1 segundo","Dos largos de auto","Unos 10 segundos"],"h1":"Las motocicletas pueden frenar muy rápido.","h2":"El manual de Kansas dice que deje una distancia de 3 a 4 segundos detrás de una motocicleta, scooter o ciclomotor, y más si el camino está mojado.","p":"Correcto. 3 a 4 segundos, más si está mojado."},"ref":{"doc":"KS","page":84}},{"id":"ks-193","scope":"KS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"According to the Kansas handbook, a loaded truck at 55 mph in ideal conditions needs at least how much distance to stop?","o":["100 feet","335 feet","50 feet","One mile"],"h1":"It is more than one and a half times a car's stopping distance.","h2":"The Kansas handbook says a loaded truck at 55 mph needs at least 335 feet to stop, so never cut in front of one.","p":"Right. At least 335 feet."},"es":{"q":"Según el manual de Kansas, ¿qué distancia mínima necesita un camión cargado a 55 mph en condiciones ideales para detenerse?","o":["100 pies","335 pies","50 pies","Una milla"],"h1":"Es más de una vez y media la distancia que necesita un auto.","h2":"El manual de Kansas dice que un camión cargado a 55 mph necesita al menos 335 pies para detenerse, así que nunca se le meta enfrente.","p":"Correcto. Al menos 335 pies."},"ref":{"doc":"KS","page":86}},{"id":"ks-194","scope":"KS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, how far behind a large truck can its rear blind spot reach?","o":["10 feet","50 feet","Up to 200 feet","Up to one mile"],"h1":"It is much longer than a car's blind spot behind.","h2":"The Kansas handbook says large vehicles have blind spots directly behind them that can extend up to 200 feet.","p":"Right. Up to 200 feet."},"es":{"q":"Según el manual de Kansas, ¿hasta qué distancia detrás de un camión grande puede llegar su punto ciego trasero?","o":["10 pies","50 pies","Hasta 200 pies","Hasta una milla"],"h1":"Es mucho más largo que el punto ciego trasero de un auto.","h2":"El manual de Kansas dice que los vehículos grandes tienen puntos ciegos justo detrás que pueden llegar hasta 200 pies.","p":"Correcto. Hasta 200 pies."},"ref":{"doc":"KS","page":86}},{"id":"ks-195","scope":"KS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kansas, a city transit bus stops ahead of you in the next lane to let people off. Must you stop?","o":["Yes, always, like for a school bus","Yes, whenever its lights flash","Only on school days","No, unless you are behind it"],"h1":"Transit buses are not school buses.","h2":"The Kansas handbook says that, unlike a school bus, you do not have to stop for a transit bus picking up or dropping off people unless you are behind it, but you should watch for passengers crossing.","p":"Right. You stop only if you are behind it."},"es":{"q":"En Kansas, un autobús urbano se detiene adelante en el carril de al lado para que bajen pasajeros. ¿Debe detenerse?","o":["Sí, siempre, como con un autobús escolar","Sí, siempre que tenga luces intermitentes","Solo en días de escuela","No, a menos que esté detrás de él"],"h1":"Los autobuses urbanos no son autobuses escolares.","h2":"El manual de Kansas dice que, a diferencia del autobús escolar, no tiene que detenerse ante un autobús urbano que sube o baja pasajeros, a menos que esté detrás de él, pero debe fijarse en los pasajeros que cruzan.","p":"Correcto. Solo se detiene si está detrás."},"ref":{"doc":"KS","page":87}},{"id":"ks-196","scope":"KS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kansas, an orange and red triangle on the back of a farm tractor means what?","o":["The vehicle usually travels at less than 25 mph","The vehicle carries hazardous materials","The driver is a student","The vehicle is about to turn left"],"h1":"It marks a slow-moving vehicle.","h2":"In Kansas, the orange and red slow-moving vehicle triangle means the vehicle is traveling at less than 25 mph.","p":"Right. It travels under 25 mph."},"es":{"q":"En Kansas, ¿qué significa un triángulo anaranjado y rojo en la parte trasera de un tractor?","o":["El vehículo suele ir a menos de 25 mph","El vehículo lleva materiales peligrosos","El conductor es un estudiante","El vehículo está por girar a la izquierda"],"h1":"Marca a un vehículo lento.","h2":"En Kansas, el triángulo anaranjado y rojo de vehículo lento significa que el vehículo va a menos de 25 mph.","p":"Correcto. Va a menos de 25 mph."},"ref":{"doc":"KS","page":88}},{"id":"ks-197","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"At night in Kansas, when should you dim your high beams for an oncoming car?","o":["When it is about 50 feet away","When you are within about one block of it","Only when it flashes its lights","Never on rural roads"],"h1":"Do it early, before the other driver is blinded.","h2":"The Kansas handbook says to dim your high beams whenever you come within about one block of an oncoming vehicle.","p":"Right. About one block away."},"es":{"q":"De noche en Kansas, ¿cuándo debe bajar las luces altas por un auto que viene de frente?","o":["Cuando esté a unos 50 pies","Cuando esté a más o menos una cuadra de él","Solo cuando le haga cambio de luces","Nunca en caminos rurales"],"h1":"Hágalo con tiempo, antes de deslumbrar al otro conductor.","h2":"El manual de Kansas dice que baje las luces altas siempre que esté a más o menos una cuadra de un vehículo que viene de frente.","p":"Correcto. Más o menos a una cuadra."},"ref":{"doc":"KS","page":91}},{"id":"ks-198","scope":"KS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kansas handbook, how deep must water be to reach the bottom of most passenger cars and cause loss of control or stalling?","o":["1 inch","2 inches","6 inches","3 feet"],"h1":"It is about half a foot.","h2":"The Kansas handbook says 6 inches of water will reach the bottom of most passenger cars, causing loss of control or stalling, and 2 feet of rushing water can carry away most vehicles.","p":"Right. About 6 inches."},"es":{"q":"Según el manual de Kansas, ¿qué profundidad de agua llega al fondo de la mayoría de los autos y puede hacer que pierda el control o se apague?","o":["1 pulgada","2 pulgadas","6 pulgadas","3 pies"],"h1":"Es como medio pie.","h2":"El manual de Kansas dice que 6 pulgadas de agua llegan al fondo de la mayoría de los autos y pueden causar pérdida de control o que se apague el motor, y 2 pies de agua en corriente pueden arrastrar a la mayoría de los vehículos.","p":"Correcto. Unas 6 pulgadas."},"ref":{"doc":"KS","page":91}},{"id":"ks-199","scope":"KS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"You are stranded in your car in a Kansas winter storm. How long does the handbook suggest running the engine for heat?","o":["Nonstop until help comes","Never, to save fuel","5 minutes every 6 hours","About 10 minutes each hour"],"h1":"Save fuel and avoid carbon monoxide.","h2":"The Kansas handbook suggests running the engine about 10 minutes each hour to warm up and charge the battery, keeping the exhaust pipe clear and one window partly open.","p":"Right. About 10 minutes each hour."},"es":{"q":"Usted queda varado en su auto en una tormenta de invierno en Kansas. ¿Cuánto tiempo sugiere el manual tener el motor encendido para calentarse?","o":["Sin parar hasta que llegue ayuda","Nunca, para ahorrar gasolina","5 minutos cada 6 horas","Unos 10 minutos cada hora"],"h1":"Ahorre gasolina y evite el monóxido de carbono.","h2":"El manual de Kansas sugiere encender el motor unos 10 minutos cada hora para calentarse y cargar la batería, con el tubo de escape libre y una ventana un poco abierta.","p":"Correcto. Unos 10 minutos cada hora."},"ref":{"doc":"KS","page":109}},{"id":"ks-200","scope":"KS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"You are driving in Kansas and see a tornado. What does the handbook say NOT to do?","o":["Leave the vehicle for a sturdy building","Shelter under a bridge or overpass","Drive out of the tornado's path","Look for a strong shelter nearby"],"h1":"Wind gets stronger in narrow spaces.","h2":"The Kansas handbook says not to shelter under bridges or overpasses, because winds can be stronger there and they give little protection from flying objects.","p":"Right. Do not hide under an overpass."},"es":{"q":"Usted maneja en Kansas y ve un tornado. ¿Qué dice el manual que NO debe hacer?","o":["Dejar el vehículo para ir a un edificio firme","Refugiarse debajo de un puente o paso elevado","Manejar fuera del camino del tornado","Buscar un refugio fuerte cercano"],"h1":"El viento se hace más fuerte en espacios angostos.","h2":"El manual de Kansas dice que no se refugie debajo de puentes o pasos elevados, porque el viento puede ser más fuerte ahí y protegen poco de los objetos que vuelan.","p":"Correcto. No se esconda debajo de un paso elevado."},"ref":{"doc":"KS","page":110}},{"id":"ky-001","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"A 2025 law lowered the age by one year, from 16.","h2":"You can get a Kentucky instruction permit at 15, because a 2025 law lowered the age from 16.","p":"Right. In Kentucky the permit starts at 15."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Una ley de 2025 bajó la edad un año, desde los 16.","h2":"Usted puede obtener un permiso de instrucción en Kentucky a los 15 años, porque una ley de 2025 bajó la edad desde los 16.","p":"Correcto. En Kentucky el permiso empieza a los 15."},"zh":{"q":"在 Kentucky，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"2025 年的一条法律把年龄从 16 岁降低了一年。","h2":"你 15 岁就可以拿到 Kentucky 的学习驾照，因为 2025 年的一条法律把年龄从 16 岁降低了。","p":"对。在 Kentucky，学习驾照从 15 岁开始。"},"vi":{"q":"Ở Kentucky, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Một luật năm 2025 đã hạ tuổi này xuống một năm, từ 16 tuổi.","h2":"Bạn có thể được cấp giấy phép tập lái ở Kentucky khi 15 tuổi, vì một luật năm 2025 đã hạ tuổi này từ 16 xuống.","p":"Đúng. Ở Kentucky, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Kentucky, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang batas noong 2025 ang nagbaba ng edad nang isang taon, mula 16.","h2":"Makakakuha ka ng Kentucky instruction permit sa edad na 15, dahil ibinaba ng isang batas noong 2025 ang edad mula 16.","p":"Tama. Sa Kentucky, nagsisimula ang permit sa edad na 15."},"ar":{"q":"في Kentucky، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"قانون صدر في 2025 خفّض العمر سنة واحدة، من 16.","h2":"يمكنك الحصول على تصريح تعلّم القيادة في Kentucky في عمر 15 سنة، لأن قانونًا صدر في 2025 خفّض العمر من 16.","p":"صحيح. في Kentucky يبدأ تصريح التعلّم من عمر 15 سنة."},"ref":{"doc":"KY","page":5}},{"id":"ky-002","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long must a driver under 21 hold the instruction permit before applying for a license?","o":["At least 30 days","At least 60 days","At least one year","At least 180 days"],"h1":"It is about six months.","h2":"A Kentucky driver under 21 must hold the instruction permit for at least 180 days, about six months, before applying for a license.","p":"Right. Under 21, you hold the permit at least 180 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso de instrucción un conductor menor de 21 años antes de solicitar la licencia?","o":["Por lo menos 30 días","Por lo menos 60 días","Por lo menos un año","Por lo menos 180 días"],"h1":"Son unos seis meses.","h2":"En Kentucky, un conductor menor de 21 años debe tener el permiso de instrucción por lo menos 180 días, unos seis meses, antes de solicitar la licencia.","p":"Correcto. Si es menor de 21, debe tener el permiso por lo menos 180 días."},"zh":{"q":"在 Kentucky，21 岁以下的司机必须持有学习驾照多久，才能申请驾照？","o":["至少 30 天","至少 60 天","至少一年","至少 180 天"],"h1":"大约是六个月。","h2":"在 Kentucky，21 岁以下的司机必须持有学习驾照至少 180 天，大约六个月，才能申请驾照。","p":"对。21 岁以下，学习驾照至少要持有 180 天。"},"vi":{"q":"Ở Kentucky, người lái dưới 21 tuổi phải giữ giấy phép tập lái bao lâu trước khi xin bằng lái?","o":["Ít nhất 30 ngày","Ít nhất 60 ngày","Ít nhất một năm","Ít nhất 180 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở Kentucky, người lái dưới 21 tuổi phải giữ giấy phép tập lái ít nhất 180 ngày, khoảng sáu tháng, trước khi xin bằng lái.","p":"Đúng. Dưới 21 tuổi, bạn giữ giấy phép tập lái ít nhất 180 ngày."},"tl":{"q":"Sa Kentucky, gaano katagal dapat hawak ng drayber na wala pang 21 ang instruction permit bago mag-apply ng lisensya?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 60 araw","Hindi bababa sa isang taon","Hindi bababa sa 180 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa Kentucky, ang drayber na wala pang 21 ay dapat humawak ng instruction permit nang hindi bababa sa 180 araw, mga anim na buwan, bago mag-apply ng lisensya.","p":"Tama. Kung wala ka pang 21, hawak mo ang permit nang hindi bababa sa 180 araw."},"ar":{"q":"في Kentucky، كم مدة يجب أن يحمل السائق الذي عمره أقل من 21 سنة تصريح التعلّم قبل أن يطلب رخصة القيادة؟","o":["30 يومًا على الأقل","60 يومًا على الأقل","سنة واحدة على الأقل","180 يومًا على الأقل"],"h1":"المدة حوالي ستة أشهر.","h2":"في Kentucky يجب أن يحمل السائق الذي عمره أقل من 21 سنة تصريح التعلّم 180 يومًا على الأقل، أي حوالي ستة أشهر، قبل أن يطلب رخصة القيادة.","p":"صحيح. إذا كان عمرك أقل من 21 سنة، تحمل التصريح 180 يومًا على الأقل."},"ref":{"doc":"KY","page":5}},{"id":"ky-003","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long must a permit holder who is 21 or older hold the permit before the road test?","o":["At least 30 days","At least 180 days","At least 7 days","At least one year"],"h1":"Adults wait much less than teens. It is about one month.","h2":"A Kentucky permit holder who is 21 or older must hold the permit for at least 30 days, much less than the 180 days for younger drivers.","p":"Right. Drivers 21 and older wait at least 30 days."},"es":{"q":"En Kentucky, ¿cuánto tiempo debe tener el permiso una persona de 21 años o más antes del examen de manejo?","o":["Por lo menos 30 días","Por lo menos 180 días","Por lo menos 7 días","Por lo menos un año"],"h1":"Los adultos esperan mucho menos que los jóvenes. Es como un mes.","h2":"En Kentucky, una persona de 21 años o más debe tener el permiso por lo menos 30 días, mucho menos que los 180 días de los conductores más jóvenes.","p":"Correcto. Las personas de 21 años o más esperan por lo menos 30 días."},"zh":{"q":"在 Kentucky，21 岁或以上持学习驾照的人，必须持有学习驾照多久才能参加路考？","o":["至少 30 天","至少 180 天","至少 7 天","至少一年"],"h1":"成年人要等的时间比青少年短很多。大约是一个月。","h2":"在 Kentucky，21 岁或以上持学习驾照的人，必须持有学习驾照至少 30 天，比年轻司机的 180 天短很多。","p":"对。21 岁及以上的司机至少要等 30 天。"},"vi":{"q":"Ở Kentucky, người có giấy phép tập lái từ 21 tuổi trở lên phải giữ giấy phép bao lâu trước khi thi lái xe?","o":["Ít nhất 30 ngày","Ít nhất 180 ngày","Ít nhất 7 ngày","Ít nhất một năm"],"h1":"Người lớn chờ ít hơn nhiều so với thiếu niên. Khoảng một tháng.","h2":"Ở Kentucky, người có giấy phép tập lái từ 21 tuổi trở lên phải giữ giấy phép ít nhất 30 ngày, ít hơn nhiều so với 180 ngày của người lái trẻ hơn.","p":"Đúng. Người lái từ 21 tuổi trở lên chờ ít nhất 30 ngày."},"tl":{"q":"Sa Kentucky, gaano katagal dapat hawak ng may permit na 21 taong gulang pataas ang permit bago ang road test?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 180 araw","Hindi bababa sa 7 araw","Hindi bababa sa isang taon"],"h1":"Mas maikli ang hinihintay ng matatanda kaysa sa mga tinedyer. Mga isang buwan ito.","h2":"Sa Kentucky, ang may permit na 21 taong gulang pataas ay dapat humawak ng permit nang hindi bababa sa 30 araw, mas maikli kaysa sa 180 araw para sa mas batang drayber.","p":"Tama. Ang mga drayber na 21 pataas ay naghihintay nang hindi bababa sa 30 araw."},"ar":{"q":"في Kentucky، كم مدة يجب أن يحمل صاحب التصريح الذي عمره 21 سنة أو أكثر التصريح قبل اختبار القيادة على الطريق؟","o":["30 يومًا على الأقل","180 يومًا على الأقل","7 أيام على الأقل","سنة واحدة على الأقل"],"h1":"الكبار ينتظرون أقل بكثير من المراهقين. المدة حوالي شهر.","h2":"في Kentucky يجب أن يحمل صاحب التصريح الذي عمره 21 سنة أو أكثر التصريح 30 يومًا على الأقل، وهذا أقل بكثير من 180 يومًا للسائقين الأصغر سنًا.","p":"صحيح. السائقون بعمر 21 سنة أو أكثر ينتظرون 30 يومًا على الأقل."},"ref":{"doc":"KY","page":9}},{"id":"ky-004","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the youngest age to get an intermediate license?","o":["15 years old","17 years old","16 years old","18 years old"],"h1":"It is one year after the youngest permit age.","h2":"You must be at least 16 to get a Kentucky intermediate license, even if you got your permit at 15.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Kentucky, ¿cuál es la edad mínima para obtener una licencia intermedia?","o":["15 años","17 años","16 años","18 años"],"h1":"Es un año después de la edad mínima del permiso.","h2":"Usted debe tener por lo menos 16 años para obtener una licencia intermedia en Kentucky, aunque haya sacado el permiso a los 15.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Kentucky，最小几岁可以拿到中级驾照（intermediate license）？","o":["15 岁","17 岁","16 岁","18 岁"],"h1":"比拿学习驾照的最小年龄晚一年。","h2":"在 Kentucky，你必须至少 16 岁才能拿到中级驾照，就算你 15 岁就拿到了学习驾照也一样。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Kentucky, tuổi nhỏ nhất để được cấp bằng lái trung cấp (intermediate license) là bao nhiêu?","o":["15 tuổi","17 tuổi","16 tuổi","18 tuổi"],"h1":"Một năm sau tuổi nhỏ nhất để có giấy phép tập lái.","h2":"Bạn phải ít nhất 16 tuổi để được cấp bằng lái trung cấp ở Kentucky, dù bạn đã có giấy phép tập lái từ 15 tuổi.","p":"Đúng. Bằng lái trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Kentucky, ano ang pinakabatang edad para makakuha ng intermediate license (pansamantalang lisensya)?","o":["15 taong gulang","17 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa permit.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng Kentucky intermediate license, kahit nakuha mo ang permit sa edad na 15.","p":"Tama. Nagsisimula ang intermediate license sa edad na 16."},"ar":{"q":"في Kentucky، ما أصغر عمر للحصول على الرخصة المتوسطة (intermediate license)؟","o":["15 سنة","17 سنة","16 سنة","18 سنة"],"h1":"العمر بعد سنة واحدة من أصغر عمر للحصول على التصريح.","h2":"يجب أن يكون عمرك 16 سنة على الأقل للحصول على الرخصة المتوسطة في Kentucky، حتى لو حصلت على التصريح في عمر 15 سنة.","p":"صحيح. الرخصة المتوسطة تبدأ من عمر 16 سنة."},"ref":{"doc":"KY","page":null}},{"id":"ky-005","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","60 hours","40 hours","100 hours"],"h1":"It is more than 50 and less than 70.","h2":"A Kentucky teen must complete 60 hours of supervised driving before the road test.","p":"Right. Kentucky asks for 60 supervised hours."},"es":{"q":"En Kentucky, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","60 horas","40 horas","100 horas"],"h1":"Son más de 50 y menos de 70.","h2":"En Kentucky, un joven debe completar 60 horas de manejo supervisado antes del examen de manejo.","p":"Correcto. Kentucky pide 60 horas supervisadas."},"zh":{"q":"在 Kentucky，青少年在路考前必须完成多少小时有人陪同的驾驶？","o":["30 小时","60 小时","40 小时","100 小时"],"h1":"比 50 多，比 70 少。","h2":"Kentucky 的青少年在路考前必须完成 60 小时有人陪同的驾驶。","p":"对。Kentucky 要求 60 小时有人陪同的驾驶。"},"vi":{"q":"Ở Kentucky, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi thi lái xe?","o":["30 giờ","60 giờ","40 giờ","100 giờ"],"h1":"Nhiều hơn 50 và ít hơn 70.","h2":"Ở Kentucky, thiếu niên phải hoàn thành 60 giờ lái xe có người giám sát trước khi thi lái xe.","p":"Đúng. Kentucky yêu cầu 60 giờ có người giám sát."},"tl":{"q":"Sa Kentucky, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng tinedyer bago ang road test?","o":["30 oras","60 oras","40 oras","100 oras"],"h1":"Higit sa 50 at mas mababa sa 70.","h2":"Sa Kentucky, dapat tapusin ng tinedyer ang 60 oras ng pagmamaneho na may gumagabay bago ang road test.","p":"Tama. Humihingi ang Kentucky ng 60 oras na may gumagabay."},"ar":{"q":"في Kentucky، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل اختبار القيادة على الطريق؟","o":["30 ساعة","60 ساعة","40 ساعة","100 ساعة"],"h1":"العدد أكثر من 50 وأقل من 70.","h2":"في Kentucky يجب أن يكمل المراهق 60 ساعة من القيادة تحت الإشراف قبل اختبار القيادة على الطريق.","p":"صحيح. تطلب Kentucky 60 ساعة تحت الإشراف."},"ref":{"doc":"KY","page":5}},{"id":"ky-006","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many of the supervised practice hours must be at night?","o":["5 hours","15 hours","20 hours","10 hours"],"h1":"It is one sixth of the 60 hours.","h2":"At least 10 of the 60 supervised hours in Kentucky must be driven at night.","p":"Right. Ten of the hours are at night."},"es":{"q":"En Kentucky, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","15 horas","20 horas","10 horas"],"h1":"Es la sexta parte de las 60 horas.","h2":"En Kentucky, por lo menos 10 de las 60 horas supervisadas deben ser de noche.","p":"Correcto. Diez de las horas son de noche."},"zh":{"q":"在 Kentucky，有人陪同的练习时间中，必须有多少小时是在夜间？","o":["5 小时","15 小时","20 小时","10 小时"],"h1":"是 60 小时的六分之一。","h2":"在 Kentucky，60 小时有人陪同的驾驶中，至少 10 小时必须在夜间开。","p":"对。其中十个小时是在夜间。"},"vi":{"q":"Ở Kentucky, bao nhiêu giờ trong số giờ tập lái có người giám sát phải là vào ban đêm?","o":["5 giờ","15 giờ","20 giờ","10 giờ"],"h1":"Đó là một phần sáu của 60 giờ.","h2":"Ở Kentucky, ít nhất 10 trong số 60 giờ lái xe có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa Kentucky, ilan sa mga oras ng pagsasanay na may gumagabay ang dapat sa gabi?","o":["5 oras","15 oras","20 oras","10 oras"],"h1":"Isang-ikaanim ito ng 60 oras.","h2":"Sa Kentucky, hindi bababa sa 10 sa 60 oras na may gumagabay ang dapat imaneho sa gabi.","p":"Tama. Sampu sa mga oras ay sa gabi."},"ar":{"q":"في Kentucky، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","15 ساعة","20 ساعة","10 ساعات"],"h1":"العدد هو سُدس الـ 60 ساعة.","h2":"في Kentucky يجب أن تكون 10 ساعات على الأقل من الـ 60 ساعة تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات تكون في الليل."},"ref":{"doc":"KY","page":5}},{"id":"ky-007","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how old must the licensed driver beside a permit holder be?","o":["At least 21","At least 16","At least 18","At least 25"],"h1":"The helper must be old enough to drink alcohol legally.","h2":"A Kentucky permit holder must drive with a licensed person who is at least 21, sitting in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Kentucky, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso?","o":["Por lo menos 21","Por lo menos 16","Por lo menos 18","Por lo menos 25"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Kentucky, quien tiene permiso debe manejar con una persona con licencia de por lo menos 21 años, sentada a su lado.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Kentucky，坐在持学习驾照的人旁边、有驾照的司机必须几岁？","o":["至少 21 岁","至少 16 岁","至少 18 岁","至少 25 岁"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 Kentucky，持学习驾照的人必须和一位至少 21 岁、有驾照的人一起开车，这个人坐在旁边的座位上。","p":"对。坐在你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Kentucky, người có bằng lái ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 21 tuổi","Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi"],"h1":"Người hướng dẫn phải đủ tuổi để uống rượu bia hợp pháp.","h2":"Ở Kentucky, người có giấy phép tập lái phải lái cùng một người có bằng lái ít nhất 21 tuổi, ngồi ở ghế bên cạnh.","p":"Đúng. Người ngồi bên cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Kentucky, ilang taon dapat ang may lisensyang drayber na katabi ng may permit?","o":["Hindi bababa sa 21","Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25"],"h1":"Dapat ay nasa legal na edad ang katulong para uminom ng alak.","h2":"Sa Kentucky, ang may permit ay dapat magmaneho kasama ang isang may lisensya na hindi bababa sa 21 taong gulang, na nakaupo sa upuang katabi niya.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang pataas."},"ar":{"q":"في Kentucky، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب صاحب التصريح؟","o":["21 سنة على الأقل","16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Kentucky يجب أن يقود صاحب التصريح مع شخص مرخَّص عمره 21 سنة على الأقل، يجلس في المقعد الذي بجانبه.","p":"صحيح. الشخص الذي بجانبك يجب أن يكون عمره 21 سنة أو أكثر."},"ref":{"doc":"KY","page":5}},{"id":"ky-008","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how does a teen show that the supervised practice hours were completed?","o":["With a note from a friend","With photos from a phone","With a practice driving log signed by a parent or guardian","Nothing is needed"],"h1":"It is a written record that a parent signs.","h2":"In Kentucky a parent or guardian signs a practice driving log that lists the 60 hours, and it is needed before the road test.","p":"Right. A practice driving log signed by a parent is needed."},"es":{"q":"En Kentucky, ¿cómo demuestra un joven que completó las horas de práctica supervisada?","o":["Con una nota de un amigo","Con fotos del teléfono","Con un registro de práctica firmado por un padre, madre o tutor","No se necesita nada"],"h1":"Es un registro escrito que firma un padre o una madre.","h2":"En Kentucky, un padre, madre o tutor firma un registro de práctica de manejo con las 60 horas, y se necesita antes del examen de manejo.","p":"Correcto. Se necesita un registro de práctica firmado por un padre o tutor."},"zh":{"q":"在 Kentucky，青少年怎样证明已经完成了有人陪同的练习时间？","o":["用朋友写的字条","用手机里的照片","用父母或监护人签字的练车记录","什么都不需要"],"h1":"这是父母签字的书面记录。","h2":"在 Kentucky，父母或监护人要在列出 60 小时的练车记录上签字，路考前需要这份记录。","p":"对。需要一份父母签字的练车记录。"},"vi":{"q":"Ở Kentucky, thiếu niên chứng minh đã hoàn thành số giờ tập lái có người giám sát bằng cách nào?","o":["Bằng một tờ giấy của bạn bè","Bằng ảnh chụp trên điện thoại","Bằng sổ ghi giờ tập lái có chữ ký của cha mẹ hoặc người giám hộ","Không cần gì cả"],"h1":"Đó là một bản ghi chép mà cha mẹ ký tên.","h2":"Ở Kentucky, cha mẹ hoặc người giám hộ ký vào sổ ghi giờ tập lái liệt kê 60 giờ, và sổ này cần có trước khi thi lái xe.","p":"Đúng. Cần có sổ ghi giờ tập lái có chữ ký của cha mẹ."},"tl":{"q":"Sa Kentucky, paano ipinapakita ng tinedyer na natapos niya ang mga oras ng pagsasanay na may gumagabay?","o":["Sa sulat mula sa isang kaibigan","Sa mga litrato mula sa telepono","Sa practice driving log (talaan ng pagsasanay) na pinirmahan ng magulang o tagapag-alaga","Walang kailangan"],"h1":"Isa itong nakasulat na talaan na pinipirmahan ng magulang.","h2":"Sa Kentucky, pumipirma ang magulang o tagapag-alaga sa practice driving log na naglilista ng 60 oras, at kailangan ito bago ang road test.","p":"Tama. Kailangan ang practice driving log na pinirmahan ng magulang."},"ar":{"q":"في Kentucky، كيف يُثبت المراهق أنه أكمل ساعات التدريب تحت الإشراف؟","o":["بورقة من صديق","بصور من الهاتف","بسجل تدريب على القيادة (practice driving log) موقَّع من أحد الوالدين أو الوصي","لا يلزم أي شيء"],"h1":"هو سجل مكتوب يوقّعه أحد الوالدين.","h2":"في Kentucky يوقّع أحد الوالدين أو الوصي على سجل تدريب على القيادة يذكر الـ 60 ساعة، وهذا السجل مطلوب قبل اختبار القيادة على الطريق.","p":"صحيح. سجل التدريب الموقَّع من أحد الوالدين مطلوب."},"ref":{"doc":"KY","page":6}},{"id":"ky-009","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when may a driver under 18 with an intermediate license not drive without good cause?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 6 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at midnight.","h2":"A Kentucky intermediate license holder under 18 may not drive between midnight and 6 a.m. unless there is good cause, such as school, work or an emergency.","p":"Right. No driving from midnight to 6 a.m. without good cause."},"es":{"q":"En Kentucky, ¿en qué horario no puede manejar sin un buen motivo un menor de 18 años con licencia intermedia?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 6 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a la medianoche.","h2":"En Kentucky, quien tiene licencia intermedia y es menor de 18 años no puede manejar entre la medianoche y las 6 a.m., salvo por un buen motivo como la escuela, el trabajo o una emergencia.","p":"Correcto. No se maneja de medianoche a 6 a.m. sin un buen motivo."},"zh":{"q":"在 Kentucky，18 岁以下、持中级驾照的司机，在没有正当理由时，什么时间不能开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 10 点到早上 6 点之间","晚上 11 点到早上 5 点之间"],"h1":"它从午夜开始。","h2":"在 Kentucky，18 岁以下、持中级驾照的人，在午夜到早上 6 点之间不能开车，除非有正当理由，例如上学、上班或紧急情况。","p":"对。没有正当理由，午夜到早上 6 点不能开车。"},"vi":{"q":"Ở Kentucky, người lái dưới 18 tuổi có bằng lái trung cấp không được lái xe vào giờ nào nếu không có lý do chính đáng?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu từ nửa đêm.","h2":"Ở Kentucky, người có bằng lái trung cấp dưới 18 tuổi không được lái xe từ nửa đêm đến 6 giờ sáng, trừ khi có lý do chính đáng như đi học, đi làm hoặc trường hợp khẩn cấp.","p":"Đúng. Không lái xe từ nửa đêm đến 6 giờ sáng nếu không có lý do chính đáng."},"tl":{"q":"Sa Kentucky, kailan hindi maaaring magmaneho nang walang mabuting dahilan ang drayber na wala pang 18 na may intermediate license?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Sa Kentucky, ang may intermediate license na wala pang 18 ay hindi maaaring magmaneho mula hatinggabi hanggang 6 a.m. maliban kung may mabuting dahilan, gaya ng paaralan, trabaho o emergency.","p":"Tama. Walang pagmamaneho mula hatinggabi hanggang 6 a.m. nang walang mabuting dahilan."},"ar":{"q":"في Kentucky، متى لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل رخصة متوسطة أن يقود بدون سبب وجيه؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ من منتصف الليل.","h2":"في Kentucky لا يجوز لحامل الرخصة المتوسطة الذي عمره أقل من 18 سنة أن يقود من منتصف الليل إلى 6 صباحًا إلا بسبب وجيه، مثل المدرسة أو العمل أو حالة طارئة.","p":"صحيح. لا قيادة من منتصف الليل إلى 6 صباحًا بدون سبب وجيه."},"ref":{"doc":"KY","page":6}},{"id":"ky-010","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how many unrelated passengers under 20 may an intermediate license holder carry?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A Kentucky intermediate license holder may carry no more than one unrelated passenger under 20, unless a driving instructor is in the car.","p":"Right. Only one unrelated passenger under 20."},"es":{"q":"En Kentucky, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar quien tiene licencia intermedia?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Kentucky, quien tiene licencia intermedia puede llevar no más de un pasajero menor de 20 años que no sea familiar, salvo que vaya un instructor de manejo en el auto.","p":"Correcto. Solo un pasajero menor de 20 que no sea familiar."},"zh":{"q":"在 Kentucky，持中级驾照的人可以载几个不是亲属、20 岁以下的乘客？","o":["一个都不可以","最多两个","最多三个","最多一个"],"h1":"是不等于零的最小的数。","h2":"在 Kentucky，持中级驾照的人最多只能载一个不是亲属、20 岁以下的乘客，除非车上有驾驶教练。","p":"对。只能载一个不是亲属、20 岁以下的乘客。"},"vi":{"q":"Ở Kentucky, người có bằng lái trung cấp được chở bao nhiêu hành khách dưới 20 tuổi không phải người thân?","o":["Không được chở ai","Không quá hai người","Không quá ba người","Không quá một người"],"h1":"Đó là số nhỏ nhất mà không phải là số không.","h2":"Ở Kentucky, người có bằng lái trung cấp được chở không quá một hành khách dưới 20 tuổi không phải người thân, trừ khi có giáo viên dạy lái xe trong xe.","p":"Đúng. Chỉ một hành khách dưới 20 tuổi không phải người thân."},"tl":{"q":"Sa Kentucky, ilang pasaherong wala pang 20 na hindi kamag-anak ang maaaring isakay ng may intermediate license?","o":["Wala talaga","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Hindi hihigit sa isa"],"h1":"Ito ang pinakamaliit na bilang na hindi zero.","h2":"Sa Kentucky, ang may intermediate license ay maaaring magsakay ng hindi hihigit sa isang pasaherong wala pang 20 na hindi kamag-anak, maliban kung may driving instructor sa sasakyan.","p":"Tama. Isang pasahero lang na wala pang 20 na hindi kamag-anak."},"ar":{"q":"في Kentucky، كم راكبًا عمره أقل من 20 سنة وليس من الأقارب يجوز لحامل الرخصة المتوسطة أن ينقله؟","o":["لا أحد أبدًا","ليس أكثر من اثنين","ليس أكثر من ثلاثة","ليس أكثر من واحد"],"h1":"هو أصغر عدد ليس صفرًا.","h2":"في Kentucky يجوز لحامل الرخصة المتوسطة أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة وليس من الأقارب، إلا إذا كان مدرّب القيادة في السيارة.","p":"صحيح. راكب واحد فقط عمره أقل من 20 سنة وليس من الأقارب."},"ref":{"doc":"KY","page":7}},{"id":"ky-011","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when may a driver under 18 use a phone while the car is moving?","o":["Only to report an emergency","When using a hands-free device","When stopped at a red light only","Any time on a highway"],"h1":"The law has no hands-free exception for this age group.","h2":"A Kentucky driver under 18 may not use a phone at all while the car is moving, hands-free included, except to report an emergency.","p":"Right. Under 18, the phone is only for emergencies."},"es":{"q":"En Kentucky, ¿cuándo puede usar el teléfono un conductor menor de 18 años mientras el auto está en movimiento?","o":["Solo para reportar una emergencia","Cuando usa un dispositivo de manos libres","Solo cuando está parado en un semáforo en rojo","En cualquier momento en la autopista"],"h1":"La ley no hace excepción para el manos libres a esta edad.","h2":"En Kentucky, un conductor menor de 18 años no puede usar el teléfono mientras el auto está en movimiento, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Si es menor de 18, el teléfono es solo para emergencias."},"zh":{"q":"在 Kentucky，18 岁以下的司机在车子行驶时，什么时候可以用手机？","o":["只能报告紧急情况","用免提设备时","只有在红灯前停着时","在高速公路上任何时候"],"h1":"对这个年龄的人，法律没有免提的例外。","h2":"在 Kentucky，18 岁以下的司机在车子行驶时完全不能用手机，包括免提，只有报告紧急情况除外。","p":"对。18 岁以下，手机只能用在紧急情况。"},"vi":{"q":"Ở Kentucky, khi nào người lái dưới 18 tuổi được dùng điện thoại lúc xe đang chạy?","o":["Chỉ để báo trường hợp khẩn cấp","Khi dùng thiết bị rảnh tay","Chỉ khi dừng ở đèn đỏ","Bất cứ lúc nào trên xa lộ"],"h1":"Luật không cho phép dùng thiết bị rảnh tay ở độ tuổi này.","h2":"Ở Kentucky, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại khi xe đang chạy, kể cả rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Dưới 18 tuổi, điện thoại chỉ dùng cho trường hợp khẩn cấp."},"tl":{"q":"Sa Kentucky, kailan maaaring gumamit ng telepono ang drayber na wala pang 18 habang umaandar ang sasakyan?","o":["Para lang mag-ulat ng emergency","Kapag gumagamit ng hands-free na device","Kapag nakahinto lang sa pulang ilaw","Anumang oras sa highway"],"h1":"Walang eksepsiyon para sa hands-free sa batas para sa edad na ito.","h2":"Sa Kentucky, ang drayber na wala pang 18 ay hindi maaaring gumamit ng telepono habang umaandar ang sasakyan, kasama ang hands-free, maliban para mag-ulat ng emergency.","p":"Tama. Kung wala ka pang 18, para lang sa emergency ang telepono."},"ar":{"q":"في Kentucky، متى يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أثناء سير السيارة؟","o":["فقط للإبلاغ عن حالة طارئة","عند استخدام جهاز بدون يدين (hands-free)","فقط عند التوقف عند الإشارة الحمراء","في أي وقت على الطريق السريع"],"h1":"القانون لا يستثني الأجهزة بدون يدين لهذه الفئة العمرية.","h2":"في Kentucky لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أبدًا أثناء سير السيارة، حتى بدون يدين، إلا للإبلاغ عن حالة طارئة.","p":"صحيح. إذا كان عمرك أقل من 18 سنة، الهاتف للحالات الطارئة فقط."},"ref":{"doc":"KY","page":null}},{"id":"ky-012","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.05 percent","0.08 percent","0.02 percent","0.10 percent"],"h1":"Kentucky calls this zero tolerance. It is the smallest number here.","h2":"A Kentucky driver under 21 breaks the zero tolerance law with a blood alcohol level of 0.02 percent.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Kentucky, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.05 por ciento","0.08 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Kentucky lo llama tolerancia cero. Es el número más pequeño.","h2":"En Kentucky, un conductor menor de 21 años viola la ley de tolerancia cero con un nivel de alcohol en la sangre de 0.02 por ciento.","p":"Correcto. Si es menor de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Kentucky，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.05%","0.08%","0.02%","0.10%"],"h1":"Kentucky 把这个叫做零容忍。它是这里最小的数字。","h2":"在 Kentucky，21 岁以下的司机血液酒精浓度达到 0.02%，就违反了零容忍法。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Kentucky, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":["0.05 phần trăm","0.08 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Kentucky gọi đây là không khoan nhượng (zero tolerance). Đó là con số nhỏ nhất ở đây.","h2":"Ở Kentucky, người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance) khi nồng độ cồn trong máu là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Kentucky, sa anong antas ng alak sa dugo lumalabag sa batas ang drayber na wala pang 21?","o":["0.05 porsiyento","0.08 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Tinatawag ito ng Kentucky na zero tolerance. Ito ang pinakamaliit na bilang dito.","h2":"Sa Kentucky, ang drayber na wala pang 21 ay lumalabag sa zero tolerance law kapag 0.02 porsiyento ang antas ng alak sa dugo.","p":"Tama. Kung wala ka pang 21, ang hangganan ay 0.02 porsiyento."},"ar":{"q":"في Kentucky، عند أي نسبة كحول في الدم يخالف السائق الذي عمره أقل من 21 سنة القانون؟","o":["0.05 بالمئة","0.08 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"تسمّي Kentucky هذا عدم التسامح مطلقًا (zero tolerance). إنه أصغر رقم هنا.","h2":"في Kentucky يخالف السائق الذي عمره أقل من 21 سنة قانون عدم التسامح مطلقًا (zero tolerance) عندما تكون نسبة الكحول في دمه 0.02 بالمئة.","p":"صحيح. إذا كان عمرك أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"KY","page":26}},{"id":"ky-013","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, what must you do when you approach a stopped emergency vehicle with flashing lights on the side of the road?","o":["Keep the same lane and speed","Move to the next lane away from it, or slow down if you cannot change lanes safely","Stop in your lane until it leaves","Honk to warn the workers"],"h1":"Give the workers more room, or go slower.","h2":"Kentucky law says to move to the lane away from a stopped emergency vehicle with flashing lights, and if that is not safe, to slow down and use caution.","p":"Right. Move over, or slow down."},"es":{"q":"En Kentucky, ¿qué debe hacer al acercarse a un vehículo de emergencia detenido al lado del camino con luces intermitentes?","o":["Seguir en el mismo carril y a la misma velocidad","Pasarse al carril de al lado, lejos de él, o bajar la velocidad si no puede cambiar de carril con seguridad","Detenerse en su carril hasta que se vaya","Tocar la bocina para avisar a los trabajadores"],"h1":"Dele más espacio a los trabajadores, o vaya más despacio.","h2":"La ley de Kentucky dice que debe pasarse al carril más lejano de un vehículo de emergencia detenido con luces intermitentes y, si no es seguro, bajar la velocidad con cuidado.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 Kentucky，当你靠近一辆停在路边、闪着灯的急救车辆时，你必须做什么？","o":["保持原来的车道和速度","换到离它远一点的旁边车道，如果不能安全换道就减速","在你的车道停下，直到它离开","按喇叭提醒工作人员"],"h1":"给工作人员更多空间，或者开慢一点。","h2":"Kentucky 法律规定，要换到离停着、闪着灯的急救车辆远一点的车道；如果这样不安全，就要减速并小心驾驶。","p":"对。换道让开，或者减速。"},"vi":{"q":"Ở Kentucky, bạn phải làm gì khi đến gần một xe cấp cứu đang dừng bên đường và có đèn nhấp nháy?","o":["Giữ nguyên làn và tốc độ","Chuyển sang làn bên cạnh, xa xe đó, hoặc chạy chậm lại nếu không thể đổi làn an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Bấm còi để báo cho nhân viên"],"h1":"Chừa thêm chỗ cho nhân viên, hoặc chạy chậm hơn.","h2":"Luật Kentucky nói phải chuyển sang làn xa xe cấp cứu đang dừng có đèn nhấp nháy, và nếu không an toàn thì phải chạy chậm lại và cẩn thận.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại."},"tl":{"q":"Sa Kentucky, ano ang dapat mong gawin kapag papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw sa gilid ng kalsada?","o":["Manatili sa parehong lane at bilis","Lumipat sa katabing lane na malayo rito, o bumagal kung hindi ligtas lumipat ng lane","Huminto sa lane mo hanggang umalis ito","Bumusina para bigyan ng babala ang mga manggagawa"],"h1":"Bigyan ng mas maraming espasyo ang mga manggagawa, o bumagal.","h2":"Sinasabi ng batas ng Kentucky na lumipat sa lane na malayo sa nakahintong emergency vehicle na may kumikislap na ilaw, at kung hindi ligtas, bumagal at mag-ingat.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في Kentucky، ماذا يجب أن تفعل عندما تقترب من مركبة طوارئ متوقفة على جانب الطريق وأضواؤها تومض؟","o":["ابقَ في نفس المسار وبنفس السرعة","انتقل إلى المسار المجاور البعيد عنها، أو خفّف السرعة إذا لم تستطع تغيير المسار بأمان","توقّف في مسارك حتى تغادر","استخدم البوق لتحذير العاملين"],"h1":"أعطِ العاملين مساحة أكبر، أو خفّف السرعة.","h2":"قانون Kentucky يقول أن تنتقل إلى المسار البعيد عن مركبة الطوارئ المتوقفة التي تومض أضواؤها، وإذا لم يكن ذلك آمنًا، أن تخفّف السرعة وتنتبه.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة."},"ref":{"doc":"KY","page":66}},{"id":"ky-014","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, since July 2026, a school bus is stopped with its stop arm out on the other side of a four-lane road with no median. What must you do?","o":["Keep driving, because the road has four lanes","Slow down and pass with care","Honk and pass","Stop, even though you are going the other way"],"h1":"The old four-lane exception was narrowed in 2026.","h2":"Since a 2026 Kentucky law, you must stop for a stopped school bus even on a four-lane road, unless a raised barrier or an unpaved median separates you from it.","p":"Right. A four-lane road alone is no longer an exception."},"es":{"q":"En Kentucky, desde julio de 2026, un autobús escolar está detenido con el brazo de alto extendido al otro lado de un camino de cuatro carriles sin camellón. ¿Qué debe hacer?","o":["Seguir manejando, porque el camino tiene cuatro carriles","Bajar la velocidad y pasar con cuidado","Tocar la bocina y pasar","Detenerse, aunque usted vaya en la dirección contraria"],"h1":"La antigua excepción de los cuatro carriles se redujo en 2026.","h2":"Desde una ley de Kentucky de 2026, usted debe detenerse ante un autobús escolar detenido aun en un camino de cuatro carriles, salvo que lo separe una barrera elevada o un camellón sin pavimentar.","p":"Correcto. Que el camino tenga cuatro carriles ya no es una excepción."},"zh":{"q":"在 Kentucky，从 2026 年 7 月起，一辆校车伸出停车臂，停在没有隔离带的四车道道路的另一边。你必须做什么？","o":["继续开，因为这条路有四条车道","减速并小心地开过去","按喇叭然后开过去","停车，就算你是往另一个方向开"],"h1":"原来四车道的例外在 2026 年被缩小了。","h2":"根据 2026 年的 Kentucky 法律，就算在四车道的路上，你也必须为停着的校车停车，除非有凸起的隔离墩或没铺路面的隔离带把你和校车分开。","p":"对。只是四车道的路已经不再是例外了。"},"vi":{"q":"Ở Kentucky, từ tháng 7 năm 2026, một xe buýt trường học đang dừng và đưa biển STOP ra ở phía bên kia của đường bốn làn không có dải phân cách. Bạn phải làm gì?","o":["Tiếp tục chạy, vì đường có bốn làn","Chạy chậm lại và vượt qua cẩn thận","Bấm còi và vượt qua","Dừng lại, dù bạn đang đi theo hướng ngược lại"],"h1":"Ngoại lệ cũ cho đường bốn làn đã bị thu hẹp vào năm 2026.","h2":"Theo một luật năm 2026 của Kentucky, bạn phải dừng lại khi xe buýt trường học dừng, kể cả trên đường bốn làn, trừ khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách bạn với xe buýt.","p":"Đúng. Chỉ đường bốn làn thôi thì không còn là ngoại lệ."},"tl":{"q":"Sa Kentucky, mula Hulyo 2026, may nakahintong school bus na nakalabas ang stop arm sa kabilang panig ng kalsadang may apat na lane at walang median. Ano ang dapat mong gawin?","o":["Magpatuloy sa pagmamaneho, dahil apat ang lane ng kalsada","Bumagal at dumaan nang maingat","Bumusina at dumaan","Huminto, kahit pasalungat ang direksyon mo"],"h1":"Pinakitid noong 2026 ang lumang eksepsiyon para sa kalsadang may apat na lane.","h2":"Dahil sa isang batas ng Kentucky noong 2026, dapat kang huminto para sa nakahintong school bus kahit sa kalsadang may apat na lane, maliban kung may nakaangat na harang o hindi sementadong median na naghihiwalay sa iyo rito.","p":"Tama. Ang kalsadang may apat na lane lang ay hindi na eksepsiyon."},"ar":{"q":"في Kentucky، منذ يوليو 2026، حافلة مدرسية متوقفة وذراع التوقف (stop arm) مفتوح على الجهة الأخرى من طريق بأربعة مسارات بدون فاصل في الوسط. ماذا يجب أن تفعل؟","o":["استمر في القيادة، لأن الطريق فيه أربعة مسارات","خفّف السرعة ومُرّ بحذر","استخدم البوق ومُرّ","توقّف، حتى لو كنت تسير في الاتجاه المعاكس"],"h1":"الاستثناء القديم للطرق ذات الأربعة مسارات أصبح أضيق في 2026.","h2":"منذ قانون Kentucky في 2026، يجب أن تتوقف للحافلة المدرسية المتوقفة حتى على طريق بأربعة مسارات، إلا إذا كان بينك وبينها حاجز مرتفع أو فاصل في الوسط غير معبَّد.","p":"صحيح. الطريق ذو الأربعة مسارات وحده لم يعد استثناءً."},"ref":{"doc":"KY","page":44}},{"id":"ky-015","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, when may traffic going the other way pass a stopped school bus without stopping?","o":["When a raised barrier or an unpaved median separates the two sides of the road","When the road has four lanes or more","When the bus has no children in sight","When the driver is in a hurry"],"h1":"Something physical must separate the two directions.","h2":"In Kentucky, traffic going the other way may pass a stopped school bus only when a raised barrier or an unpaved median separates the two sides of the road.","p":"Right. Only a barrier or an unpaved median makes it an exception."},"es":{"q":"En Kentucky, ¿cuándo puede el tráfico que va en dirección contraria pasar un autobús escolar detenido sin detenerse?","o":["Cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino","Cuando el camino tiene cuatro carriles o más","Cuando no se ven niños cerca del autobús","Cuando el conductor tiene prisa"],"h1":"Algo físico debe separar las dos direcciones.","h2":"En Kentucky, el tráfico en dirección contraria puede pasar un autobús escolar detenido solo cuando una barrera elevada o un camellón sin pavimentar separa los dos lados del camino.","p":"Correcto. Solo una barrera o un camellón sin pavimentar es una excepción."},"zh":{"q":"在 Kentucky，对面方向的车什么时候可以不停车，开过停着的校车？","o":["当凸起的隔离墩或没铺路面的隔离带把道路两边分开时","当道路有四条或更多车道时","当看不到校车有小孩时","当司机赶时间时"],"h1":"必须有实际的东西把两个方向分开。","h2":"在 Kentucky，只有当凸起的隔离墩或没铺路面的隔离带把道路两边分开时，对面方向的车才可以开过停着的校车。","p":"对。只有隔离墩或没铺路面的隔离带才算例外。"},"vi":{"q":"Ở Kentucky, khi nào xe đi theo hướng ngược lại được vượt qua xe buýt trường học đang dừng mà không cần dừng lại?","o":["Khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách hai bên đường","Khi đường có bốn làn trở lên","Khi không thấy trẻ em nào","Khi người lái đang vội"],"h1":"Phải có một vật cụ thể ngăn cách hai chiều xe chạy.","h2":"Ở Kentucky, xe đi theo hướng ngược lại chỉ được vượt qua xe buýt trường học đang dừng khi có rào chắn nổi hoặc dải phân cách không trải nhựa ngăn cách hai bên đường.","p":"Đúng. Chỉ rào chắn hoặc dải phân cách không trải nhựa mới là ngoại lệ."},"tl":{"q":"Sa Kentucky, kailan maaaring lampasan ng mga sasakyang pasalungat ang direksyon ang nakahintong school bus nang hindi humihinto?","o":["Kapag may nakaangat na harang o hindi sementadong median na naghihiwalay sa dalawang panig ng kalsada","Kapag may apat o higit pang lane ang kalsada","Kapag walang batang nakikita malapit sa bus","Kapag nagmamadali ang drayber"],"h1":"Dapat may pisikal na bagay na naghihiwalay sa dalawang direksyon.","h2":"Sa Kentucky, ang mga sasakyang pasalungat ang direksyon ay maaaring lumampas sa nakahintong school bus lamang kapag may nakaangat na harang o hindi sementadong median na naghihiwalay sa dalawang panig ng kalsada.","p":"Tama. Harang o hindi sementadong median lang ang eksepsiyon."},"ar":{"q":"في Kentucky، متى يجوز للسيارات القادمة من الاتجاه المعاكس أن تمرّ بجانب حافلة مدرسية متوقفة بدون أن تتوقف؟","o":["عندما يفصل حاجز مرتفع أو فاصل غير معبَّد في الوسط بين جهتي الطريق","عندما يكون في الطريق أربعة مسارات أو أكثر","عندما لا يُرى أي طفل قرب الحافلة","عندما يكون السائق مستعجلًا"],"h1":"يجب أن يفصل شيء مادي بين الاتجاهين.","h2":"في Kentucky يجوز للسيارات القادمة من الاتجاه المعاكس أن تمرّ بجانب حافلة مدرسية متوقفة فقط عندما يفصل حاجز مرتفع أو فاصل غير معبَّد في الوسط بين جهتي الطريق.","p":"صحيح. الحاجز أو الفاصل غير المعبَّد فقط هو الاستثناء."},"ref":{"doc":"KY","page":44}},{"id":"ky-016","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the usual speed limit on interstates when no other limit is posted for that section?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"Some rural sections are raised by 5 mph above this number.","h2":"Kentucky interstates are usually 65 mph, and some rural sections are posted at 70 mph after a safety study.","p":"Right. The usual interstate limit is 65 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad habitual en las autopistas interestatales cuando no hay otro límite para ese tramo?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"En algunos tramos rurales se sube 5 mph sobre este número.","h2":"Las autopistas interestatales de Kentucky suelen tener un límite de 65 mph, y algunos tramos rurales tienen 70 mph después de un estudio de seguridad.","p":"Correcto. El límite habitual en la interestatal es 65 mph."},"zh":{"q":"在 Kentucky，如果那一段路没有标示其他限速，州际公路一般的限速是多少？","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"有些乡村路段比这个数字高 5 mph。","h2":"Kentucky 的州际公路一般限速是 65 mph，有些乡村路段经过安全研究后标示为 70 mph。","p":"对。州际公路一般限速是 65 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa thông thường trên xa lộ liên bang (interstate) là bao nhiêu khi không có biển báo tốc độ khác cho đoạn đường đó?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"Một số đoạn ở vùng nông thôn được tăng thêm 5 mph so với con số này.","h2":"Xa lộ liên bang ở Kentucky thường là 65 mph, và một số đoạn ở vùng nông thôn có biển báo 70 mph sau khi nghiên cứu an toàn.","p":"Đúng. Tốc độ tối đa thông thường trên xa lộ liên bang là 65 mph."},"tl":{"q":"Sa Kentucky, ano ang karaniwang speed limit sa mga interstate kapag walang ibang limit na nakapaskil para sa bahaging iyon?","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"May ilang bahagi sa probinsya na itinaas nang 5 mph mula sa bilang na ito.","h2":"Karaniwang 65 mph ang mga interstate sa Kentucky, at may ilang bahagi sa probinsya na nakapaskil na 70 mph pagkatapos ng safety study.","p":"Tama. Ang karaniwang limit sa interstate ay 65 mph."},"ar":{"q":"في Kentucky، ما حد السرعة المعتاد على الطرق السريعة بين الولايات (interstate) عندما لا توجد لافتة بحد آخر لذلك الجزء؟","o":["55 mph","75 mph","65 mph","80 mph"],"h1":"بعض الأجزاء الريفية رُفع حدها 5 mph فوق هذا الرقم.","h2":"حد السرعة المعتاد على الطرق السريعة بين الولايات في Kentucky هو 65 mph، وبعض الأجزاء الريفية لها لافتات بـ 70 mph بعد دراسة للسلامة.","p":"صحيح. الحد المعتاد على الطرق السريعة بين الولايات هو 65 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-017","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, what is the highest speed limit posted on some rural interstate sections?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the usual interstate limit.","h2":"Some rural interstate sections in Kentucky are posted at 70 mph, 5 mph above the usual 65 mph.","p":"Right. Some rural sections allow 70 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de autopistas interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Son 5 mph más que el límite habitual de la interestatal.","h2":"Algunos tramos rurales de autopistas interestatales en Kentucky tienen un límite de 70 mph, 5 mph más que el habitual de 65 mph.","p":"Correcto. Algunos tramos rurales permiten 70 mph."},"zh":{"q":"在 Kentucky，有些乡村州际公路路段标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"比州际公路一般限速高 5 mph。","h2":"Kentucky 有些乡村州际公路路段标示为 70 mph，比一般的 65 mph 高 5 mph。","p":"对。有些乡村路段允许 70 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa cao nhất được ghi trên biển ở một số đoạn xa lộ liên bang vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Cao hơn 5 mph so với tốc độ tối đa thông thường trên xa lộ liên bang.","h2":"Một số đoạn xa lộ liên bang vùng nông thôn ở Kentucky có biển báo 70 mph, cao hơn 5 mph so với mức thông thường 65 mph.","p":"Đúng. Một số đoạn vùng nông thôn cho phép 70 mph."},"tl":{"q":"Sa Kentucky, ano ang pinakamataas na speed limit na nakapaskil sa ilang bahagi ng interstate sa probinsya?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito nang 5 mph kaysa sa karaniwang limit sa interstate.","h2":"May ilang bahagi ng interstate sa probinsya ng Kentucky na nakapaskil na 70 mph, 5 mph na mas mataas sa karaniwang 65 mph.","p":"Tama. May ilang bahagi sa probinsya na pinapayagan ang 70 mph."},"ar":{"q":"في Kentucky، ما أعلى حد سرعة مكتوب على لافتات بعض أجزاء الطرق السريعة بين الولايات في المناطق الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى بـ 5 mph من الحد المعتاد على الطرق السريعة بين الولايات.","h2":"بعض أجزاء الطرق السريعة بين الولايات في المناطق الريفية في Kentucky لها لافتات بـ 70 mph، أي أعلى بـ 5 mph من الحد المعتاد 65 mph.","p":"صحيح. بعض الأجزاء الريفية تسمح بـ 70 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-018","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how long is an instruction permit valid since the 2025 law?","o":["One year","Two years","Three years","Four years"],"h1":"The 2025 law added one year to the old three years.","h2":"Since the 2025 law, a Kentucky instruction permit is valid for four years instead of three.","p":"Right. The permit is now valid for four years."},"es":{"q":"En Kentucky, ¿por cuánto tiempo es válido el permiso de instrucción desde la ley de 2025?","o":["Un año","Dos años","Tres años","Cuatro años"],"h1":"La ley de 2025 sumó un año a los tres años de antes.","h2":"Desde la ley de 2025, el permiso de instrucción de Kentucky es válido por cuatro años en lugar de tres.","p":"Correcto. Ahora el permiso es válido por cuatro años."},"zh":{"q":"在 Kentucky，按照 2025 年的法律，学习驾照有效期是多久？","o":["一年","两年","三年","四年"],"h1":"2025 年的法律在原来的三年上加了一年。","h2":"按照 2025 年的法律，Kentucky 的学习驾照有效期是四年，不再是三年。","p":"对。学习驾照现在有效四年。"},"vi":{"q":"Ở Kentucky, theo luật năm 2025, giấy phép tập lái có giá trị bao lâu?","o":["Một năm","Hai năm","Ba năm","Bốn năm"],"h1":"Luật năm 2025 đã thêm một năm vào ba năm cũ.","h2":"Theo luật năm 2025, giấy phép tập lái ở Kentucky có giá trị bốn năm thay vì ba năm.","p":"Đúng. Giấy phép tập lái bây giờ có giá trị bốn năm."},"tl":{"q":"Sa Kentucky, gaano katagal may bisa ang instruction permit mula sa batas noong 2025?","o":["Isang taon","Dalawang taon","Tatlong taon","Apat na taon"],"h1":"Nagdagdag ang batas noong 2025 ng isang taon sa dating tatlong taon.","h2":"Mula sa batas noong 2025, may bisa ang Kentucky instruction permit nang apat na taon sa halip na tatlo.","p":"Tama. May bisa na ngayon ang permit nang apat na taon."},"ar":{"q":"في Kentucky، كم مدة صلاحية تصريح تعلّم القيادة منذ قانون 2025؟","o":["سنة واحدة","سنتان","ثلاث سنوات","أربع سنوات"],"h1":"قانون 2025 أضاف سنة واحدة إلى السنوات الثلاث القديمة.","h2":"منذ قانون 2025، أصبح تصريح تعلّم القيادة في Kentucky صالحًا لمدة أربع سنوات بدلًا من ثلاث.","p":"صحيح. التصريح الآن صالح لمدة أربع سنوات."},"ref":{"doc":"KY","page":null}},{"id":"ky-019","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, what score do you need to pass the written permit test?","o":["At least 80 percent","At least 60 percent","At least 70 percent","At least 90 percent"],"h1":"It is four out of every five answers.","h2":"You need at least 80 percent correct to pass the Kentucky written permit test.","p":"Right. The passing score is 80 percent."},"es":{"q":"En Kentucky, ¿qué puntaje necesita para aprobar el examen escrito del permiso?","o":["Por lo menos 80 por ciento","Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento"],"h1":"Son cuatro de cada cinco respuestas.","h2":"Usted necesita por lo menos 80 por ciento de respuestas correctas para aprobar el examen escrito del permiso en Kentucky.","p":"Correcto. Se aprueba con 80 por ciento."},"zh":{"q":"在 Kentucky，学习驾照笔试要考多少分才能通过？","o":["至少 80%","至少 60%","至少 70%","至少 90%"],"h1":"每五题要答对四题。","h2":"你需要答对至少 80%，才能通过 Kentucky 的学习驾照笔试。","p":"对。及格分数是 80%。"},"vi":{"q":"Ở Kentucky, bạn cần bao nhiêu điểm để đậu bài thi viết lấy giấy phép tập lái?","o":["Ít nhất 80 phần trăm","Ít nhất 60 phần trăm","Ít nhất 70 phần trăm","Ít nhất 90 phần trăm"],"h1":"Đúng bốn trong mỗi năm câu trả lời.","h2":"Bạn cần trả lời đúng ít nhất 80 phần trăm để đậu bài thi viết lấy giấy phép tập lái ở Kentucky.","p":"Đúng. Điểm đậu là 80 phần trăm."},"tl":{"q":"Sa Kentucky, anong score ang kailangan mo para pumasa sa nakasulat na permit test?","o":["Hindi bababa sa 80 porsiyento","Hindi bababa sa 60 porsiyento","Hindi bababa sa 70 porsiyento","Hindi bababa sa 90 porsiyento"],"h1":"Apat ito sa bawat limang sagot.","h2":"Kailangan mo ng hindi bababa sa 80 porsiyentong tamang sagot para pumasa sa nakasulat na permit test ng Kentucky.","p":"Tama. Ang passing score ay 80 porsiyento."},"ar":{"q":"في Kentucky، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي للتصريح؟","o":["80 بالمئة على الأقل","60 بالمئة على الأقل","70 بالمئة على الأقل","90 بالمئة على الأقل"],"h1":"أربع إجابات صحيحة من كل خمس.","h2":"تحتاج إلى 80 بالمئة على الأقل من الإجابات الصحيحة لتنجح في الاختبار الكتابي للتصريح في Kentucky.","p":"صحيح. درجة النجاح هي 80 بالمئة."},"ref":{"doc":"KY","page":11}},{"id":"ky-020","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, which agency gives the written and road tests for a driver license?","o":["The county sheriff","The local school district","The Kentucky State Police","A private insurance company"],"h1":"It is a statewide police agency.","h2":"In Kentucky, the Kentucky State Police give the written and road tests for a driver license.","p":"Right. The State Police run driver testing."},"es":{"q":"En Kentucky, ¿qué agencia toma los exámenes escrito y de manejo para la licencia?","o":["El alguacil del condado","El distrito escolar local","La Policía Estatal de Kentucky","Una compañía de seguros privada"],"h1":"Es una policía de todo el estado.","h2":"En Kentucky, la Policía Estatal de Kentucky toma los exámenes escrito y de manejo para la licencia.","p":"Correcto. La Policía Estatal se encarga de los exámenes."},"zh":{"q":"在 Kentucky，哪个机构负责驾照的笔试和路考？","o":["县警长（county sheriff）","当地学区","Kentucky State Police","私人保险公司"],"h1":"这是一个全州的警察机构。","h2":"在 Kentucky，驾照的笔试和路考是由 Kentucky State Police（州警察）负责的。","p":"对。州警察负责驾照考试。"},"vi":{"q":"Ở Kentucky, cơ quan nào tổ chức bài thi viết và thi lái xe để lấy bằng lái?","o":["Cảnh sát trưởng quận (county sheriff)","Học khu địa phương","Cảnh sát Tiểu bang Kentucky (Kentucky State Police)","Một công ty bảo hiểm tư nhân"],"h1":"Đó là một cơ quan cảnh sát của cả tiểu bang.","h2":"Ở Kentucky, Cảnh sát Tiểu bang Kentucky (Kentucky State Police) tổ chức bài thi viết và thi lái xe để lấy bằng lái.","p":"Đúng. Cảnh sát Tiểu bang phụ trách các bài thi lái xe."},"tl":{"q":"Sa Kentucky, aling ahensya ang nagbibigay ng nakasulat na test at road test para sa driver license?","o":["Ang county sheriff","Ang lokal na school district","Ang Kentucky State Police","Isang pribadong kompanya ng insurance"],"h1":"Isa itong ahensya ng pulis para sa buong estado.","h2":"Sa Kentucky, ang Kentucky State Police ang nagbibigay ng nakasulat na test at road test para sa driver license.","p":"Tama. Ang State Police ang nangangasiwa sa pagsusulit ng mga drayber."},"ar":{"q":"في Kentucky، أي جهة تُجري الاختبار الكتابي واختبار القيادة على الطريق لرخصة القيادة؟","o":["شريف المقاطعة (county sheriff)","المنطقة التعليمية المحلية","شرطة ولاية Kentucky (Kentucky State Police)","شركة تأمين خاصة"],"h1":"هي جهة شرطة للولاية كلها.","h2":"في Kentucky، شرطة ولاية Kentucky (Kentucky State Police) هي التي تُجري الاختبار الكتابي واختبار القيادة على الطريق لرخصة القيادة.","p":"صحيح. شرطة الولاية هي المسؤولة عن اختبارات السائقين."},"ref":{"doc":"KY","page":4}},{"id":"ky-021","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, can you take the standard written driver test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish","Only with a paid interpreter","Only after failing in English"],"h1":"Kentucky State Police list Spanish among the test languages.","h2":"Yes, the Kentucky State Police offer the standard written driver test in Spanish, and a Spanish driver manual is available too.","p":"Right. The standard test is offered in Spanish."},"es":{"q":"En Kentucky, ¿puede tomar en español el examen escrito estándar de manejo?","o":["No, solo en inglés","Sí, se ofrece en español","Solo con un intérprete pagado","Solo después de reprobar en inglés"],"h1":"La Policía Estatal de Kentucky incluye el español entre los idiomas del examen.","h2":"Sí, la Policía Estatal de Kentucky ofrece el examen escrito estándar de manejo en español, y también hay un manual del conductor en español.","p":"Correcto. El examen estándar se ofrece en español."},"zh":{"q":"在 Kentucky，你可以用西班牙语参加普通的驾照笔试吗？","o":["不可以，只能用英语","可以，有西班牙语考试","只能请付费的翻译","只能在英语考试不及格以后"],"h1":"Kentucky State Police 把西班牙语列为考试语言之一。","h2":"可以，Kentucky State Police 提供西班牙语的普通驾照笔试，也有西班牙语的驾驶手册。","p":"对。普通笔试有西班牙语版本。"},"vi":{"q":"Ở Kentucky, bạn có thể làm bài thi viết lái xe tiêu chuẩn bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, có bài thi bằng tiếng Tây Ban Nha","Chỉ khi có thông dịch viên trả tiền","Chỉ sau khi thi rớt bằng tiếng Anh"],"h1":"Cảnh sát Tiểu bang Kentucky (Kentucky State Police) có liệt kê tiếng Tây Ban Nha trong các ngôn ngữ thi.","h2":"Có, Cảnh sát Tiểu bang Kentucky (Kentucky State Police) có bài thi viết lái xe tiêu chuẩn bằng tiếng Tây Ban Nha, và cũng có sách hướng dẫn lái xe bằng tiếng Tây Ban Nha.","p":"Đúng. Bài thi tiêu chuẩn có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Kentucky, maaari mo bang kunin sa Spanish ang karaniwang nakasulat na driver test?","o":["Hindi, sa English lang","Oo, inaalok ito sa Spanish","Kung may bayad na interpreter lang","Pagkatapos lang bumagsak sa English"],"h1":"Kasama ang Spanish sa listahan ng Kentucky State Police ng mga wika ng test.","h2":"Oo, inaalok ng Kentucky State Police ang karaniwang nakasulat na driver test sa Spanish, at may driver manual din sa Spanish.","p":"Tama. Inaalok sa Spanish ang karaniwang test."},"ar":{"q":"في Kentucky، هل يمكنك أن تُجري الاختبار الكتابي العادي للقيادة باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، الاختبار متوفر بالإسبانية","فقط مع مترجم مدفوع الأجر","فقط بعد الرسوب بالإنجليزية"],"h1":"شرطة ولاية Kentucky (Kentucky State Police) تذكر الإسبانية ضمن لغات الاختبار.","h2":"نعم، شرطة ولاية Kentucky (Kentucky State Police) تقدّم الاختبار الكتابي العادي للقيادة بالإسبانية، ويوجد أيضًا دليل للسائقين بالإسبانية.","p":"صحيح. الاختبار العادي متوفر بالإسبانية."},"ref":{"doc":"KY","page":11}},{"id":"ky-022","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, how many points in two years can lead to a suspension for a driver 18 or older?","o":["6 points","12 points","18 points","24 points"],"h1":"Think of a dozen.","h2":"In Kentucky, a driver 18 or older who gets 12 points within two years may have the license suspended.","p":"Right. 12 points in two years can mean a suspension."},"es":{"q":"En Kentucky, ¿cuántos puntos en dos años pueden llevar a una suspensión para un conductor de 18 años o más?","o":["6 puntos","12 puntos","18 puntos","24 puntos"],"h1":"Piense en una docena.","h2":"En Kentucky, a un conductor de 18 años o más que acumula 12 puntos en dos años le pueden suspender la licencia.","p":"Correcto. 12 puntos en dos años pueden significar una suspensión."},"zh":{"q":"在 Kentucky，18 岁或以上的司机在两年内被记多少分，可能会被暂停驾照？","o":["6 分","12 分","18 分","24 分"],"h1":"想一想“一打”是多少。","h2":"在 Kentucky，18 岁或以上的司机如果在两年内被记 12 分，驾照可能会被暂停。","p":"对。两年内 12 分可能会导致驾照被暂停。"},"vi":{"q":"Ở Kentucky, tài xế từ 18 tuổi trở lên bị bao nhiêu điểm trong hai năm thì có thể bị đình chỉ bằng lái?","o":["6 điểm","12 điểm","18 điểm","24 điểm"],"h1":"Hãy nghĩ đến một tá.","h2":"Ở Kentucky, tài xế từ 18 tuổi trở lên bị 12 điểm trong vòng hai năm có thể bị đình chỉ bằng lái.","p":"Đúng. 12 điểm trong hai năm có thể dẫn đến đình chỉ bằng lái."},"tl":{"q":"Sa Kentucky, ilang puntos sa loob ng dalawang taon ang maaaring humantong sa suspensyon para sa drayber na 18 taong gulang pataas?","o":["6 na puntos","12 puntos","18 puntos","24 na puntos"],"h1":"Isipin ang isang dosena.","h2":"Sa Kentucky, ang drayber na 18 taong gulang pataas na makakuha ng 12 puntos sa loob ng dalawang taon ay maaaring masuspinde ang lisensya.","p":"Tama. Ang 12 puntos sa loob ng dalawang taon ay maaaring mangahulugan ng suspensyon."},"ar":{"q":"في Kentucky، كم نقطة خلال سنتين قد تؤدي إلى إيقاف رخصة سائق عمره 18 سنة أو أكثر؟","o":["6 نقاط","12 نقطة","18 نقطة","24 نقطة"],"h1":"فكّر في الدزينة.","h2":"في Kentucky، السائق الذي عمره 18 سنة أو أكثر ويحصل على 12 نقطة خلال سنتين قد تُوقَف رخصته.","p":"صحيح. 12 نقطة خلال سنتين قد تعني إيقاف الرخصة."},"ref":{"doc":"KY","page":17}},{"id":"ky-023","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, a driver under 18 can face a suspension after how many points in two years?","o":["3 points","12 points","10 points","7 points"],"h1":"Young drivers have a lower limit than adults.","h2":"In Kentucky, a driver under 18 who gets 7 points within two years can lose the license, while adults have a limit of 12.","p":"Right. Under 18, the limit is 7 points."},"es":{"q":"En Kentucky, ¿con cuántos puntos en dos años puede un conductor menor de 18 años enfrentar una suspensión?","o":["3 puntos","12 puntos","10 puntos","7 puntos"],"h1":"Los conductores jóvenes tienen un límite más bajo que los adultos.","h2":"En Kentucky, un conductor menor de 18 años que acumula 7 puntos en dos años puede perder la licencia, mientras que el límite para los adultos es 12.","p":"Correcto. Para menores de 18, el límite es 7 puntos."},"zh":{"q":"在 Kentucky，未满 18 岁的司机在两年内被记多少分，可能会被暂停驾照？","o":["3 分","12 分","10 分","7 分"],"h1":"年轻司机的分数上限比成年人低。","h2":"在 Kentucky，未满 18 岁的司机如果在两年内被记 7 分，可能会失去驾照，而成年人的上限是 12 分。","p":"对。未满 18 岁，上限是 7 分。"},"vi":{"q":"Ở Kentucky, tài xế dưới 18 tuổi có thể bị đình chỉ bằng lái sau bao nhiêu điểm trong hai năm?","o":["3 điểm","12 điểm","10 điểm","7 điểm"],"h1":"Tài xế trẻ có giới hạn thấp hơn người lớn.","h2":"Ở Kentucky, tài xế dưới 18 tuổi bị 7 điểm trong vòng hai năm có thể mất bằng lái, còn người lớn có giới hạn là 12 điểm.","p":"Đúng. Dưới 18 tuổi, giới hạn là 7 điểm."},"tl":{"q":"Sa Kentucky, ang drayber na wala pang 18 ay maaaring masuspinde pagkatapos ng ilang puntos sa loob ng dalawang taon?","o":["3 puntos","12 puntos","10 puntos","7 puntos"],"h1":"Mas mababa ang limitasyon ng mga batang drayber kaysa sa mga nasa hustong gulang.","h2":"Sa Kentucky, ang drayber na wala pang 18 na makakuha ng 7 puntos sa loob ng dalawang taon ay maaaring mawalan ng lisensya, habang 12 ang limitasyon ng mga nasa hustong gulang.","p":"Tama. Kapag wala pang 18, ang limitasyon ay 7 puntos."},"ar":{"q":"في Kentucky، بعد كم نقطة خلال سنتين قد تُوقَف رخصة سائق عمره أقل من 18 سنة؟","o":["3 نقاط","12 نقطة","10 نقاط","7 نقاط"],"h1":"حدّ السائقين الصغار أقل من حدّ البالغين.","h2":"في Kentucky، السائق الذي عمره أقل من 18 سنة ويحصل على 7 نقاط خلال سنتين قد يفقد رخصته، بينما حدّ البالغين هو 12 نقطة.","p":"صحيح. تحت 18 سنة، الحدّ هو 7 نقاط."},"ref":{"doc":"KY","page":17}},{"id":"ky-024","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long do points stay active after a traffic conviction?","o":["Two years","Six months","Five years","Ten years"],"h1":"It is the same length of time the point system looks back.","h2":"In Kentucky, points expire two years after the conviction, but the conviction stays on your record for five years.","p":"Right. Points last two years."},"es":{"q":"En Kentucky, ¿cuánto tiempo siguen activos los puntos después de una condena de tránsito?","o":["Dos años","Seis meses","Cinco años","Diez años"],"h1":"Es el mismo tiempo que revisa el sistema de puntos.","h2":"En Kentucky, los puntos vencen dos años después de la condena, pero la condena se queda en su historial por cinco años.","p":"Correcto. Los puntos duran dos años."},"zh":{"q":"在 Kentucky，交通违法定罪后，分数会保留多长时间？","o":["两年","六个月","五年","十年"],"h1":"这和计分制度往回看的时间一样长。","h2":"在 Kentucky，分数在定罪两年后失效，但定罪记录会在你的记录上保留五年。","p":"对。分数保留两年。"},"vi":{"q":"Ở Kentucky, điểm phạt còn hiệu lực bao lâu sau khi bị kết tội vi phạm giao thông?","o":["Hai năm","Sáu tháng","Năm năm","Mười năm"],"h1":"Đó là cùng khoảng thời gian mà hệ thống điểm xem xét lại.","h2":"Ở Kentucky, điểm phạt hết hiệu lực hai năm sau khi bị kết tội, nhưng bản án vẫn ở trong hồ sơ của bạn trong năm năm.","p":"Đúng. Điểm phạt kéo dài hai năm."},"tl":{"q":"Sa Kentucky, gaano katagal nananatiling aktibo ang mga puntos pagkatapos ng isang traffic conviction (pagkahatol sa paglabag sa trapiko)?","o":["Dalawang taon","Anim na buwan","Limang taon","Sampung taon"],"h1":"Pareho ito sa haba ng panahong tinitingnan ng point system.","h2":"Sa Kentucky, nawawalan ng bisa ang mga puntos dalawang taon pagkatapos ng conviction, pero nananatili ang conviction sa iyong record nang limang taon.","p":"Tama. Tumatagal ang mga puntos nang dalawang taon."},"ar":{"q":"في Kentucky، كم تبقى النقاط سارية بعد الإدانة بمخالفة مرورية؟","o":["سنتان","ستة أشهر","خمس سنوات","عشر سنوات"],"h1":"إنها نفس المدة التي ينظر إليها نظام النقاط إلى الوراء.","h2":"في Kentucky، تنتهي النقاط بعد سنتين من الإدانة، لكن الإدانة تبقى في سجلّك خمس سنوات.","p":"صحيح. النقاط تبقى سنتين."},"ref":{"doc":"KY","page":17}},{"id":"ky-025","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the minimum liability insurance for injury to one person in a crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"The same amount is also the minimum for property damage.","h2":"In Kentucky, liability insurance must cover at least $25,000 for injury to one person, $50,000 for all injuries in one crash, and $25,000 for property damage.","p":"Right. $25,000 for one person is the minimum."},"es":{"q":"En Kentucky, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"La misma cantidad es también el mínimo para daños a la propiedad.","h2":"En Kentucky, el seguro de responsabilidad debe cubrir al menos $25,000 por lesiones a una persona, $50,000 por todas las lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. $25,000 por una persona es el mínimo."},"zh":{"q":"在 Kentucky，车祸中一个人受伤的最低责任保险金额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"财产损失的最低金额也是这个数。","h2":"在 Kentucky，责任保险必须至少赔付一个人受伤 $25,000，一次车祸所有受伤 $50,000，以及财产损失 $25,000。","p":"对。一个人的最低金额是 $25,000。"},"vi":{"q":"Ở Kentucky, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Số tiền này cũng là mức tối thiểu cho thiệt hại tài sản.","h2":"Ở Kentucky, bảo hiểm trách nhiệm phải chi trả ít nhất $25,000 cho thương tích của một người, $50,000 cho tất cả thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000 cho một người là mức tối thiểu."},"tl":{"q":"Sa Kentucky, ano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang aksidente?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Ang parehong halaga ay ang pinakamababa rin para sa pinsala sa ari-arian.","h2":"Sa Kentucky, ang liability insurance ay dapat sumaklaw ng hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa lahat ng pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. $25,000 para sa isang tao ang pinakamababa."},"ar":{"q":"في Kentucky، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"المبلغ نفسه هو أيضًا الحدّ الأدنى لأضرار الممتلكات.","h2":"في Kentucky، يجب أن يغطي تأمين المسؤولية على الأقل $25,000 لإصابة شخص واحد، و$50,000 لكل الإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 لشخص واحد هو الحدّ الأدنى."},"ref":{"doc":"KY","page":19}},{"id":"ky-026","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what can happen to an owner or driver of a vehicle with no insurance?","o":["Only a written warning","A fine of $500 to $1,000, up to 90 days in jail, or both","A $50 fine and nothing more","Only a 7-day wait to register the car"],"h1":"Driving without insurance is a crime in Kentucky.","h2":"In Kentucky, the owner and driver of an uninsured vehicle can be fined $500 to $1,000, jailed for up to 90 days, or both, and the registration is revoked.","p":"Right. No insurance can mean a big fine or jail."},"es":{"q":"En Kentucky, ¿qué le puede pasar al dueño o al conductor de un vehículo sin seguro?","o":["Solo una advertencia por escrito","Una multa de $500 a $1,000, hasta 90 días de cárcel, o ambas","Una multa de $50 y nada más","Solo una espera de 7 días para registrar el carro"],"h1":"Manejar sin seguro es un delito en Kentucky.","h2":"En Kentucky, el dueño y el conductor de un vehículo sin seguro pueden recibir una multa de $500 a $1,000, hasta 90 días de cárcel, o ambas, y se revoca el registro.","p":"Correcto. No tener seguro puede significar una multa grande o cárcel."},"zh":{"q":"在 Kentucky，没有保险的车辆的车主或司机可能会怎样？","o":["只有书面警告","罚款 $500 到 $1,000，最多坐牢 90 天，或两者都有","罚款 $50，没有别的","只需等 7 天才能给车登记"],"h1":"在 Kentucky，没有保险开车是犯罪。","h2":"在 Kentucky，没有保险的车辆的车主和司机可能被罚款 $500 到 $1,000，最多坐牢 90 天，或两者都有，而且车辆登记会被吊销。","p":"对。没有保险可能意味着高额罚款或坐牢。"},"vi":{"q":"Ở Kentucky, chủ xe hoặc tài xế của xe không có bảo hiểm có thể bị gì?","o":["Chỉ bị cảnh cáo bằng văn bản","Bị phạt $500 đến $1,000, ngồi tù tới 90 ngày, hoặc cả hai","Bị phạt $50 và không gì khác","Chỉ phải chờ 7 ngày để đăng ký xe"],"h1":"Lái xe không có bảo hiểm là một tội ở Kentucky.","h2":"Ở Kentucky, chủ xe và tài xế của xe không có bảo hiểm có thể bị phạt $500 đến $1,000, ngồi tù tới 90 ngày, hoặc cả hai, và giấy đăng ký xe bị thu hồi.","p":"Đúng. Không có bảo hiểm có thể bị phạt nặng hoặc ngồi tù."},"tl":{"q":"Sa Kentucky, ano ang maaaring mangyari sa may-ari o drayber ng sasakyang walang insurance?","o":["Isang nakasulat na babala lamang","Multang $500 hanggang $1,000, hanggang 90 araw na pagkakakulong, o pareho","Multang $50 at wala nang iba","Paghihintay lamang nang 7 araw para mairehistro ang kotse"],"h1":"Krimen sa Kentucky ang pagmamaneho nang walang insurance.","h2":"Sa Kentucky, ang may-ari at drayber ng sasakyang walang insurance ay maaaring pagmultahin ng $500 hanggang $1,000, makulong nang hanggang 90 araw, o pareho, at binabawi ang rehistro.","p":"Tama. Ang walang insurance ay maaaring mangahulugan ng malaking multa o kulong."},"ar":{"q":"في Kentucky، ماذا قد يحدث لمالك أو سائق مركبة بلا تأمين؟","o":["إنذار مكتوب فقط","غرامة من $500 إلى $1,000، أو سجن حتى 90 يومًا، أو الاثنان معًا","غرامة $50 فقط ولا شيء آخر","انتظار 7 أيام فقط لتسجيل السيارة"],"h1":"القيادة بلا تأمين جريمة في Kentucky.","h2":"في Kentucky، يمكن تغريم مالك وسائق مركبة بلا تأمين من $500 إلى $1,000، أو سجنه حتى 90 يومًا، أو الاثنين معًا، ويُلغى تسجيل المركبة.","p":"صحيح. عدم وجود تأمين قد يعني غرامة كبيرة أو سجنًا."},"ref":{"doc":"KY","page":19}},{"id":"ky-027","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, if you fail the road skills test, how long must you wait before trying again?","o":["You may retry the same day","At least 30 days","At least one week","At least six months"],"h1":"The wait is short, just enough time to practice.","h2":"In Kentucky, after failing the road skills test you must wait at least one week before you try again.","p":"Right. Wait one week and practice."},"es":{"q":"En Kentucky, si no pasa el examen práctico de manejo, ¿cuánto tiempo debe esperar para intentarlo de nuevo?","o":["Puede intentarlo el mismo día","Al menos 30 días","Al menos una semana","Al menos seis meses"],"h1":"La espera es corta, justo el tiempo para practicar.","h2":"En Kentucky, después de no pasar el examen práctico de manejo, usted debe esperar al menos una semana antes de intentarlo de nuevo.","p":"Correcto. Espere una semana y practique."},"zh":{"q":"在 Kentucky，如果你没有通过路考（road skills test），要等多久才能再考？","o":["当天就可以再考","至少 30 天","至少一个星期","至少六个月"],"h1":"等待时间很短，刚好够你练习。","h2":"在 Kentucky，路考没通过后，你必须至少等一个星期才能再考。","p":"对。等一个星期，好好练习。"},"vi":{"q":"Ở Kentucky, nếu bạn thi trượt bài thi kỹ năng lái xe trên đường (road skills test), bạn phải chờ bao lâu mới được thi lại?","o":["Bạn có thể thi lại ngay trong ngày","Ít nhất 30 ngày","Ít nhất một tuần","Ít nhất sáu tháng"],"h1":"Thời gian chờ ngắn, vừa đủ để luyện tập.","h2":"Ở Kentucky, sau khi thi trượt bài thi kỹ năng lái xe trên đường, bạn phải chờ ít nhất một tuần mới được thi lại.","p":"Đúng. Chờ một tuần và luyện tập."},"tl":{"q":"Sa Kentucky, kung bumagsak ka sa road skills test (pagsusulit sa pagmamaneho sa kalsada), gaano katagal ka dapat maghintay bago sumubok ulit?","o":["Puwede kang sumubok ulit sa parehong araw","Hindi bababa sa 30 araw","Hindi bababa sa isang linggo","Hindi bababa sa anim na buwan"],"h1":"Maikli ang paghihintay, sapat lang para makapag-ensayo.","h2":"Sa Kentucky, pagkatapos bumagsak sa road skills test, kailangan mong maghintay nang hindi bababa sa isang linggo bago sumubok ulit.","p":"Tama. Maghintay nang isang linggo at mag-ensayo."},"ar":{"q":"في Kentucky، إذا رسبت في اختبار مهارات القيادة على الطريق (road skills test)، كم يجب أن تنتظر قبل المحاولة مرة أخرى؟","o":["يمكنك المحاولة مرة أخرى في اليوم نفسه","30 يومًا على الأقل","أسبوعًا واحدًا على الأقل","ستة أشهر على الأقل"],"h1":"الانتظار قصير، يكفي فقط للتدرّب.","h2":"في Kentucky، بعد الرسوب في اختبار مهارات القيادة على الطريق يجب أن تنتظر أسبوعًا واحدًا على الأقل قبل أن تحاول مرة أخرى.","p":"صحيح. انتظر أسبوعًا وتدرّب."},"ref":{"doc":"KY","page":6}},{"id":"ky-028","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, when you pass another vehicle, how far from an oncoming vehicle must the pass be finished?","o":["At least 50 feet","At least 200 feet","At least 100 feet","At least 1,000 feet"],"h1":"The distance is more than half a football field.","h2":"In Kentucky, you must finish a pass before you come within 200 feet of an oncoming vehicle.","p":"Right. Finish the pass at least 200 feet before an oncoming vehicle."},"es":{"q":"En Kentucky, al rebasar a otro vehículo, ¿a qué distancia de un vehículo que viene de frente debe terminar de rebasar?","o":["Al menos 50 pies","Al menos 200 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"La distancia es más de la mitad de un campo de fútbol americano.","h2":"En Kentucky, usted debe terminar de rebasar antes de quedar a menos de 200 pies de un vehículo que viene de frente.","p":"Correcto. Termine de rebasar al menos 200 pies antes del vehículo que viene."},"zh":{"q":"在 Kentucky，超车时，你必须在离对面来车多远之前完成超车？","o":["至少 50 英尺","至少 200 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"这个距离比半个美式足球场还长。","h2":"在 Kentucky，你必须在离对面来车 200 英尺之前完成超车。","p":"对。在对面来车前至少 200 英尺完成超车。"},"vi":{"q":"Ở Kentucky, khi vượt xe khác, bạn phải vượt xong khi còn cách xe chạy ngược chiều bao xa?","o":["Ít nhất 50 feet","Ít nhất 200 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng cách này dài hơn nửa sân bóng bầu dục Mỹ.","h2":"Ở Kentucky, bạn phải vượt xong trước khi đến gần xe chạy ngược chiều trong vòng 200 feet.","p":"Đúng. Hãy vượt xong khi còn cách xe ngược chiều ít nhất 200 feet."},"tl":{"q":"Sa Kentucky, kapag nag-o-overtake ka sa ibang sasakyan, gaano kalayo dapat sa paparating na sasakyan mo matapos ang pag-overtake?","o":["Hindi bababa sa 50 talampakan","Hindi bababa sa 200 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Mas mahaba ang layo kaysa kalahati ng isang football field.","h2":"Sa Kentucky, dapat mong tapusin ang pag-overtake bago ka umabot sa loob ng 200 talampakan mula sa paparating na sasakyan.","p":"Tama. Tapusin ang pag-overtake nang hindi bababa sa 200 talampakan bago ang paparating na sasakyan."},"ar":{"q":"في Kentucky، عندما تتجاوز سيارة أخرى، على أي مسافة من السيارة القادمة من الاتجاه المقابل يجب أن تُنهي التجاوز؟","o":["50 قدمًا على الأقل","200 قدم على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"المسافة أكثر من نصف ملعب كرة قدم أمريكية.","h2":"في Kentucky، يجب أن تُنهي التجاوز قبل أن تصبح على بُعد 200 قدم من السيارة القادمة من الاتجاه المقابل.","p":"صحيح. أنهِ التجاوز قبل السيارة القادمة بمسافة 200 قدم على الأقل."},"ref":{"doc":"KY","page":47}},{"id":"ky-029","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, on a road with one lane each way, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 6 feet","At least 3 feet"],"h1":"It is about the length of a yardstick.","h2":"In Kentucky, when there is only one lane in your direction, you must pass a bicycle on the left and keep at least 3 feet away.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Kentucky, en un camino con un carril en cada sentido, ¿cuánto espacio debe dejar al pasar a una bicicleta?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 6 pies","Al menos 3 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Kentucky, cuando hay un solo carril en su sentido, usted debe pasar a la bicicleta por la izquierda y dejar al menos 3 pies.","p":"Correcto. Deje al menos 3 pies a la bicicleta."},"zh":{"q":"在 Kentucky，在每个方向只有一条车道的路上，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 6 英尺","至少 3 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Kentucky，当你的方向只有一条车道时，你必须从左边超过自行车，并保持至少 3 英尺的距离。","p":"对。给自行车留出至少 3 英尺。"},"vi":{"q":"Ở Kentucky, trên đường mỗi chiều chỉ có một làn, bạn phải chừa bao nhiêu khoảng trống khi vượt xe đạp?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 6 feet","Ít nhất 3 feet"],"h1":"Khoảng bằng chiều dài một cây thước một yard.","h2":"Ở Kentucky, khi chiều của bạn chỉ có một làn, bạn phải vượt xe đạp bên trái và giữ cách ít nhất 3 feet.","p":"Đúng. Hãy chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Kentucky, sa daan na may isang lane bawat direksyon, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang bisikleta?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 6 na talampakan","Hindi bababa sa 3 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick (panukat na isang yarda).","h2":"Sa Kentucky, kapag iisa lang ang lane sa direksyon mo, dapat mong lampasan ang bisikleta sa kaliwa at lumayo nang hindi bababa sa 3 talampakan.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Kentucky، على طريق فيه مسار واحد في كل اتجاه، كم مسافة يجب أن تترك عندما تتجاوز دراجة هوائية؟","o":["قدم واحد على الأقل","قدمان على الأقل","6 أقدام على الأقل","3 أقدام على الأقل"],"h1":"إنها تقريبًا طول مسطرة طولها ياردة واحدة.","h2":"في Kentucky، عندما يكون في اتجاهك مسار واحد فقط، يجب أن تتجاوز الدراجة الهوائية من اليسار وتبتعد عنها 3 أقدام على الأقل.","p":"صحيح. اترك للدراجة الهوائية 3 أقدام على الأقل."},"ref":{"doc":"KY","page":48}},{"id":"ky-030","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, what is the smallest following distance the manual tells you to keep behind the vehicle ahead?","o":["One second","Two seconds","Four seconds","Ten seconds"],"h1":"It is longer than the two seconds many people use.","h2":"In Kentucky, the manual says to keep a following distance of at least 4 seconds behind the vehicle ahead.","p":"Right. Keep at least 4 seconds behind."},"es":{"q":"En Kentucky, ¿cuál es la distancia de seguimiento mínima que el manual le dice mantener detrás del vehículo de adelante?","o":["Un segundo","Dos segundos","Cuatro segundos","Diez segundos"],"h1":"Es más que los dos segundos que mucha gente usa.","h2":"En Kentucky, el manual dice que debe mantener una distancia de seguimiento de al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Mantenga al menos 4 segundos de distancia."},"zh":{"q":"在 Kentucky，驾驶手册要求你和前车保持的最小跟车距离是多少？","o":["一秒","两秒","四秒","十秒"],"h1":"它比很多人用的两秒更长。","h2":"在 Kentucky，驾驶手册说你要和前车保持至少 4 秒的跟车距离。","p":"对。和前车保持至少 4 秒的距离。"},"vi":{"q":"Ở Kentucky, sổ tay lái xe bảo bạn giữ khoảng cách tối thiểu bao nhiêu với xe phía trước?","o":["Một giây","Hai giây","Bốn giây","Mười giây"],"h1":"Nó dài hơn hai giây mà nhiều người vẫn dùng.","h2":"Ở Kentucky, sổ tay lái xe nói bạn phải giữ khoảng cách ít nhất 4 giây với xe phía trước.","p":"Đúng. Hãy giữ cách xe phía trước ít nhất 4 giây."},"tl":{"q":"Sa Kentucky, ano ang pinakamaikling layo sa likod ng sasakyan sa unahan na sinasabi ng manual na panatilihin mo?","o":["Isang segundo","Dalawang segundo","Apat na segundo","Sampung segundo"],"h1":"Mas mahaba ito kaysa sa dalawang segundo na ginagamit ng maraming tao.","h2":"Sa Kentucky, sinasabi ng manual na panatilihin ang layong hindi bababa sa 4 na segundo sa likod ng sasakyan sa unahan.","p":"Tama. Manatili nang hindi bababa sa 4 na segundo sa likod."},"ar":{"q":"في Kentucky، ما أقل مسافة متابعة يطلب منك الدليل أن تتركها خلف السيارة التي أمامك؟","o":["ثانية واحدة","ثانيتان","أربع ثوانٍ","عشر ثوانٍ"],"h1":"إنها أطول من الثانيتين اللتين يستخدمهما كثير من الناس.","h2":"في Kentucky، يقول الدليل أن تترك مسافة متابعة لا تقل عن 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. ابقَ خلف السيارة 4 ثوانٍ على الأقل."},"ref":{"doc":"KY","page":51}},{"id":"ky-031","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when can traffic fines be doubled in a highway work zone?","o":["When signs say fines are doubled and at least one worker is present","Only at night, even when no signs are posted","Any time, even after all the work is finished","Only when a police car is parked in the work zone"],"h1":"Two things must be true: the signs and the people.","h2":"In Kentucky, fines may be doubled in a highway work zone when signs say so and at least one worker is present.","p":"Right. Signs posted and a worker present means double fines."},"es":{"q":"En Kentucky, ¿cuándo se pueden duplicar las multas en una zona de trabajo en la carretera?","o":["Cuando hay letreros de multas dobles y al menos un trabajador presente","Solo de noche, aunque no haya ningún letrero","En cualquier momento, aunque el trabajo ya haya terminado","Solo cuando hay un carro de policía estacionado en la zona de trabajo"],"h1":"Dos cosas deben cumplirse: los letreros y las personas.","h2":"En Kentucky, las multas se pueden duplicar en una zona de trabajo en la carretera cuando hay letreros que lo indican y al menos un trabajador presente.","p":"Correcto. Con letreros y un trabajador presente, las multas son dobles."},"zh":{"q":"在 Kentucky，在公路施工区，什么时候交通罚款可以加倍？","o":["有标志写着罚款加倍，并且至少有一名工人在场时","只在晚上，即使没有任何标志","任何时候，即使施工已经全部结束","只有当施工区里停着一辆警车时"],"h1":"两件事必须同时成立：标志和人。","h2":"在 Kentucky，当公路施工区有标志写明罚款加倍，并且至少有一名工人在场时，罚款可以加倍。","p":"对。有标志并且有工人在场，罚款就加倍。"},"vi":{"q":"Ở Kentucky, khi nào tiền phạt giao thông có thể bị tăng gấp đôi trong khu vực thi công trên đường cao tốc?","o":["Khi có biển báo phạt gấp đôi và có ít nhất một công nhân đang làm việc","Chỉ vào ban đêm, kể cả khi không có biển báo","Bất cứ lúc nào, kể cả khi công việc đã xong hết","Chỉ khi có xe cảnh sát đỗ trong khu vực thi công"],"h1":"Phải có đủ hai điều: biển báo và con người.","h2":"Ở Kentucky, tiền phạt có thể bị tăng gấp đôi trong khu vực thi công trên đường cao tốc khi có biển báo như vậy và có ít nhất một công nhân đang làm việc.","p":"Đúng. Có biển báo và có công nhân thì tiền phạt tăng gấp đôi."},"tl":{"q":"Sa Kentucky, kailan puwedeng dobleng multa sa trapiko sa isang work zone sa highway?","o":["Kapag may karatulang nagsasabing doble ang multa at may kahit isang manggagawa roon","Sa gabi lang, kahit walang anumang karatula","Kahit kailan, kahit tapos na ang lahat ng trabaho","Kapag may nakaparadang sasakyan ng pulis sa work zone lang"],"h1":"Dalawang bagay ang dapat totoo: ang mga karatula at ang mga tao.","h2":"Sa Kentucky, puwedeng dobleng multa sa isang work zone sa highway kapag may karatulang nagsasabi nito at may kahit isang manggagawa roon.","p":"Tama. May karatula at may manggagawa roon ay nangangahulugang doble ang multa."},"ar":{"q":"في Kentucky، متى يمكن مضاعفة غرامات المرور في منطقة أعمال على الطريق السريع؟","o":["عندما توجد لافتات تقول إن الغرامات مضاعفة ويوجد عامل واحد على الأقل","في الليل فقط، حتى عندما لا توجد أي لافتات","في أي وقت، حتى بعد انتهاء كل الأعمال","فقط عندما تكون سيارة شرطة متوقفة في منطقة الأعمال"],"h1":"يجب أن يتحقق أمران: اللافتات والأشخاص.","h2":"في Kentucky، يمكن مضاعفة الغرامات في منطقة أعمال على الطريق السريع عندما توجد لافتات تقول ذلك ويوجد عامل واحد على الأقل.","p":"صحيح. وجود اللافتات ووجود عامل يعني غرامات مضاعفة."},"ref":{"doc":"KY","page":69}},{"id":"ky-032","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what eyesight do you need before you can take the written test?","o":["20/80, with or without glasses","20/20, without glasses","20/40, with or without glasses","20/200, with glasses"],"h1":"Glasses or contacts are allowed for the eye test.","h2":"In Kentucky, you need vision of at least 20/40, with or without glasses or contacts, before you can move on to the written test.","p":"Right. You need 20/40 vision, and glasses are allowed."},"es":{"q":"En Kentucky, ¿qué visión necesita antes de poder tomar el examen escrito?","o":["20/80, con o sin lentes","20/20, sin lentes","20/40, con o sin lentes","20/200, con lentes"],"h1":"Se permiten lentes o lentes de contacto en el examen de la vista.","h2":"En Kentucky, usted necesita una visión de al menos 20/40, con o sin lentes o lentes de contacto, antes de pasar al examen escrito.","p":"Correcto. Necesita una visión de 20/40, y se permiten lentes."},"zh":{"q":"在 Kentucky，参加笔试之前，你的视力需要达到多少？","o":["20/80，戴不戴眼镜都可以","20/20，不戴眼镜","20/40，戴不戴眼镜都可以","20/200，戴眼镜"],"h1":"视力检查时可以戴眼镜或隐形眼镜。","h2":"在 Kentucky，你的视力至少要达到 20/40（戴不戴眼镜或隐形眼镜都可以），才能参加笔试。","p":"对。你需要 20/40 的视力，可以戴眼镜。"},"vi":{"q":"Ở Kentucky, bạn cần thị lực như thế nào trước khi được làm bài thi viết?","o":["20/80, có hoặc không đeo kính","20/20, không đeo kính","20/40, có hoặc không đeo kính","20/200, có đeo kính"],"h1":"Bạn được đeo kính hoặc kính áp tròng khi kiểm tra mắt.","h2":"Ở Kentucky, bạn cần thị lực ít nhất 20/40, có hoặc không đeo kính hay kính áp tròng, thì mới được làm bài thi viết.","p":"Đúng. Bạn cần thị lực 20/40, và được đeo kính."},"tl":{"q":"Sa Kentucky, anong linaw ng paningin ang kailangan mo bago ka makakuha ng nakasulat na test?","o":["20/80, may salamin man o wala","20/20, walang salamin","20/40, may salamin man o wala","20/200, may salamin"],"h1":"Puwede ang salamin o contact lens sa eye test.","h2":"Sa Kentucky, kailangan mo ng paningin na hindi bababa sa 20/40, may salamin o contact lens man o wala, bago ka makapunta sa nakasulat na test.","p":"Tama. Kailangan mo ng 20/40 na paningin, at puwede ang salamin."},"ar":{"q":"في Kentucky، ما قوة النظر التي تحتاجها قبل أن تستطيع أداء الاختبار الكتابي؟","o":["20/80، بنظارة أو بدونها","20/20، بدون نظارة","20/40، بنظارة أو بدونها","20/200، بنظارة"],"h1":"يُسمح بالنظارة أو العدسات اللاصقة في فحص النظر.","h2":"في Kentucky، تحتاج إلى قوة نظر 20/40 على الأقل، بنظارة أو عدسات لاصقة أو بدونها، قبل أن تنتقل إلى الاختبار الكتابي.","p":"صحيح. تحتاج إلى نظر 20/40، والنظارة مسموح بها."},"ref":{"doc":"KY","page":10}},{"id":"ky-033","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, you just moved here and became a resident. How soon must you get a Kentucky driver's license?","o":["Within 30 days","Within 6 months","Within 1 year","When your old license expires"],"h1":"It is about one month.","h2":"In Kentucky, a new resident must get a Kentucky driver's license within 30 days of moving here.","p":"Right. New residents have 30 days to get a Kentucky license."},"es":{"q":"En Kentucky, usted acaba de mudarse y ahora es residente. ¿En cuánto tiempo debe obtener una licencia de manejo de Kentucky?","o":["En un plazo de 30 días","En un plazo de 6 meses","En un plazo de 1 año","Cuando venza su licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Kentucky, un nuevo residente debe obtener una licencia de manejo de Kentucky en un plazo de 30 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 30 días para obtener una licencia de Kentucky."},"zh":{"q":"在 Kentucky，你刚搬来并成为居民。你必须在多长时间内拿到 Kentucky 驾照？","o":["30 天内","6 个月内","1 年内","等你原来的驾照过期时"],"h1":"大约是一个月。","h2":"在 Kentucky，新居民必须在搬来后 30 天内拿到 Kentucky 驾照。","p":"对。新居民有 30 天时间拿 Kentucky 驾照。"},"vi":{"q":"Ở Kentucky, bạn vừa chuyển đến và trở thành cư dân. Bạn phải lấy bằng lái Kentucky trong thời gian bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 6 tháng","Trong vòng 1 năm","Khi bằng lái cũ của bạn hết hạn"],"h1":"Khoảng một tháng.","h2":"Ở Kentucky, cư dân mới phải lấy bằng lái Kentucky trong vòng 30 ngày sau khi chuyển đến.","p":"Đúng. Cư dân mới có 30 ngày để lấy bằng lái Kentucky."},"tl":{"q":"Sa Kentucky, kalilipat mo lang dito at naging residente ka. Gaano kabilis ka dapat kumuha ng Kentucky driver's license?","o":["Sa loob ng 30 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon","Kapag nag-expire na ang luma mong lisensya"],"h1":"Mga isang buwan ito.","h2":"Sa Kentucky, ang bagong residente ay dapat kumuha ng Kentucky driver's license sa loob ng 30 araw mula nang lumipat dito.","p":"Tama. May 30 araw ang mga bagong residente para kumuha ng Kentucky license."},"ar":{"q":"في Kentucky، انتقلت للتو وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Kentucky؟","o":["خلال 30 يومًا","خلال 6 أشهر","خلال سنة واحدة","عندما تنتهي رخصتك القديمة"],"h1":"المدة حوالي شهر واحد.","h2":"في Kentucky، يجب على المقيم الجديد أن يحصل على رخصة قيادة من Kentucky خلال 30 يومًا من انتقاله.","p":"صحيح. لدى المقيمين الجدد 30 يومًا للحصول على رخصة Kentucky."},"ref":{"doc":"KY","page":13}},{"id":"ky-034","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, after you change your address or name, how soon must you get a duplicate license?","o":["Within 1 year","At your next renewal","Within 60 days","Within 10 days"],"h1":"It is a short time, less than two weeks.","h2":"In Kentucky, you must get a duplicate license within 10 days after you change your address or name, or you can get a ticket.","p":"Right. Update your license within 10 days."},"es":{"q":"En Kentucky, después de cambiar su dirección o su nombre, ¿en cuánto tiempo debe obtener un duplicado de la licencia?","o":["En un plazo de 1 año","En su próxima renovación","En un plazo de 60 días","En un plazo de 10 días"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Kentucky, usted debe obtener un duplicado de la licencia en un plazo de 10 días después de cambiar su dirección o su nombre, o le pueden dar una multa.","p":"Correcto. Actualice su licencia en un plazo de 10 días."},"zh":{"q":"在 Kentucky，你改了地址或名字以后，必须在多长时间内补办一张新驾照（duplicate license）？","o":["1 年内","下次换证时","60 天内","10 天内"],"h1":"时间很短，不到两个星期。","h2":"在 Kentucky，你改了地址或名字以后，必须在 10 天内补办新驾照，否则可能会被开罚单。","p":"对。要在 10 天内更新驾照。"},"vi":{"q":"Ở Kentucky, sau khi đổi địa chỉ hoặc đổi tên, bạn phải lấy bằng lái thay thế (duplicate license) trong thời gian bao lâu?","o":["Trong vòng 1 năm","Vào lần gia hạn tới","Trong vòng 60 ngày","Trong vòng 10 ngày"],"h1":"Thời gian ngắn, chưa tới hai tuần.","h2":"Ở Kentucky, bạn phải lấy bằng lái thay thế trong vòng 10 ngày sau khi đổi địa chỉ hoặc đổi tên, nếu không bạn có thể bị phạt.","p":"Đúng. Hãy cập nhật bằng lái trong vòng 10 ngày."},"tl":{"q":"Sa Kentucky, pagkatapos mong magpalit ng address o pangalan, gaano kabilis ka dapat kumuha ng duplicate license?","o":["Sa loob ng 1 taon","Sa susunod mong renewal","Sa loob ng 60 araw","Sa loob ng 10 araw"],"h1":"Maikling panahon ito, kulang sa dalawang linggo.","h2":"Sa Kentucky, dapat kang kumuha ng duplicate license sa loob ng 10 araw pagkatapos mong magpalit ng address o pangalan, o puwede kang ma-ticket.","p":"Tama. I-update ang lisensya mo sa loob ng 10 araw."},"ar":{"q":"في Kentucky، بعد أن تغيّر عنوانك أو اسمك، خلال كم من الوقت يجب أن تحصل على نسخة بديلة من الرخصة (duplicate license)؟","o":["خلال سنة واحدة","عند التجديد القادم","خلال 60 يومًا","خلال 10 أيام"],"h1":"المدة قصيرة، أقل من أسبوعين.","h2":"في Kentucky، يجب أن تحصل على نسخة بديلة من الرخصة خلال 10 أيام بعد أن تغيّر عنوانك أو اسمك، وإلا قد تحصل على مخالفة.","p":"صحيح. حدّث رخصتك خلال 10 أيام."},"ref":{"doc":"KY","page":16}},{"id":"ky-035","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when does a driver's license issued to someone under 21 expire?","o":["On the driver's 18th birthday","90 days after the driver's 21st birthday","On the driver's 25th birthday","One year after it is issued"],"h1":"It lasts a little past a big birthday.","h2":"In Kentucky, a license for a driver under 21 expires 90 days after the driver's 21st birthday.","p":"Right. It expires 90 days after you turn 21."},"es":{"q":"En Kentucky, ¿cuándo vence una licencia de manejo emitida a una persona menor de 21 años?","o":["El día que el conductor cumple 18 años","90 días después de que el conductor cumple 21 años","El día que el conductor cumple 25 años","Un año después de emitida"],"h1":"Dura un poco más allá de un cumpleaños importante.","h2":"En Kentucky, la licencia de un conductor menor de 21 años vence 90 días después de que el conductor cumple 21 años.","p":"Correcto. Vence 90 días después de cumplir 21 años."},"zh":{"q":"在 Kentucky，发给 21 岁以下的人的驾照什么时候过期？","o":["在驾驶人 18 岁生日那天","在驾驶人 21 岁生日后 90 天","在驾驶人 25 岁生日那天","发证后一年"],"h1":"它在一个重要生日之后还能再用一小段时间。","h2":"在 Kentucky，21 岁以下驾驶人的驾照在驾驶人 21 岁生日后 90 天过期。","p":"对。驾照在你满 21 岁后 90 天过期。"},"vi":{"q":"Ở Kentucky, bằng lái cấp cho người dưới 21 tuổi hết hạn khi nào?","o":["Vào ngày sinh nhật 18 tuổi của người lái","90 ngày sau sinh nhật 21 tuổi của người lái","Vào ngày sinh nhật 25 tuổi của người lái","Một năm sau khi được cấp"],"h1":"Nó còn dùng được thêm một chút sau một ngày sinh nhật quan trọng.","h2":"Ở Kentucky, bằng lái của người dưới 21 tuổi hết hạn 90 ngày sau sinh nhật 21 tuổi của người lái.","p":"Đúng. Bằng lái hết hạn 90 ngày sau khi bạn tròn 21 tuổi."},"tl":{"q":"Sa Kentucky, kailan mag-e-expire ang driver's license na ibinigay sa taong wala pang 21?","o":["Sa ika-18 kaarawan ng driver","90 araw pagkatapos ng ika-21 kaarawan ng driver","Sa ika-25 kaarawan ng driver","Isang taon pagkatapos itong ibigay"],"h1":"Tumatagal ito nang kaunti lampas sa isang mahalagang kaarawan.","h2":"Sa Kentucky, ang lisensya ng driver na wala pang 21 ay mag-e-expire 90 araw pagkatapos ng ika-21 kaarawan ng driver.","p":"Tama. Mag-e-expire ito 90 araw pagkatapos mong mag-21."},"ar":{"q":"في Kentucky، متى تنتهي رخصة القيادة التي تُعطى لشخص عمره أقل من 21 سنة؟","o":["في يوم عيد ميلاد السائق الـ 18","بعد 90 يومًا من عيد ميلاد السائق الـ 21","في يوم عيد ميلاد السائق الـ 25","بعد سنة واحدة من إصدارها"],"h1":"تستمر وقتًا قصيرًا بعد عيد ميلاد مهم.","h2":"في Kentucky، تنتهي رخصة السائق الذي عمره أقل من 21 سنة بعد 90 يومًا من عيد ميلاده الـ 21.","p":"صحيح. تنتهي الرخصة بعد 90 يومًا من بلوغك 21 سنة."},"ref":{"doc":"KY","page":16}},{"id":"ky-036","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a permit holder under 18 is convicted of a moving violation. What happens?","o":["Nothing changes once the fine is paid","The permit is extended by one year","They must wait at least 180 days from the violation to get an intermediate license","They only have to retake the vision test"],"h1":"A violation delays the next step of the teen license program.","h2":"In Kentucky, a moving violation by a permit holder under 18 adds at least 180 days, counted from the violation date, before the teen can apply for an intermediate license.","p":"Right. A violation adds at least 180 more days to the permit stage."},"es":{"q":"En Kentucky, un menor de 18 años con permiso es declarado culpable de una infracción de tránsito en movimiento. ¿Qué pasa?","o":["Nada cambia una vez que paga la multa","El permiso se extiende por un año","Debe esperar al menos 180 días desde la infracción para obtener una licencia intermedia","Solo tiene que repetir el examen de la vista"],"h1":"Una infracción retrasa el siguiente paso del programa de licencias para adolescentes.","h2":"En Kentucky, una infracción en movimiento de un menor de 18 años con permiso agrega al menos 180 días, contados desde la fecha de la infracción, antes de poder solicitar una licencia intermedia.","p":"Correcto. Una infracción agrega al menos 180 días más a la etapa del permiso."},"zh":{"q":"在 Kentucky，一个 18 岁以下、持学习驾照的人被判定犯了行车违规（moving violation）。会怎么样？","o":["罚款交了以后什么都不变","学习驾照延长一年","必须从违规那天起等至少 180 天才能拿中级驾照","只需要重新做视力检查"],"h1":"违规会推迟青少年驾照计划的下一步。","h2":"在 Kentucky，18 岁以下持学习驾照的人如果犯了行车违规，要从违规日期算起再等至少 180 天，才能申请中级驾照。","p":"对。违规会让学习驾照阶段至少多 180 天。"},"vi":{"q":"Ở Kentucky, một người dưới 18 tuổi có giấy phép tập lái bị kết tội vi phạm khi đang lái xe (moving violation). Điều gì sẽ xảy ra?","o":["Không có gì thay đổi sau khi trả tiền phạt","Giấy phép tập lái được kéo dài thêm một năm","Họ phải chờ ít nhất 180 ngày kể từ ngày vi phạm mới được lấy bằng lái trung cấp","Họ chỉ phải kiểm tra mắt lại"],"h1":"Một lần vi phạm sẽ làm chậm bước tiếp theo của chương trình bằng lái cho thanh thiếu niên.","h2":"Ở Kentucky, nếu người dưới 18 tuổi có giấy phép tập lái vi phạm khi đang lái xe, họ phải chờ thêm ít nhất 180 ngày, tính từ ngày vi phạm, mới được xin bằng lái trung cấp.","p":"Đúng. Một lần vi phạm làm giai đoạn tập lái dài thêm ít nhất 180 ngày."},"tl":{"q":"Sa Kentucky, ang isang may permit na wala pang 18 ay nahatulan ng moving violation (paglabag habang nagmamaneho). Ano ang mangyayari?","o":["Walang magbabago kapag nabayaran na ang multa","Mapapahaba ang permit nang isang taon","Kailangan nilang maghintay nang hindi bababa sa 180 araw mula sa paglabag bago makakuha ng intermediate license","Kailangan lang nilang ulitin ang eye test"],"h1":"Naaantala ng paglabag ang susunod na hakbang ng teen license program.","h2":"Sa Kentucky, ang moving violation ng isang may permit na wala pang 18 ay nagdadagdag ng hindi bababa sa 180 araw, mula sa petsa ng paglabag, bago makapag-apply ang teen para sa intermediate license.","p":"Tama. Nagdadagdag ang paglabag ng hindi bababa sa 180 araw sa permit stage."},"ar":{"q":"في Kentucky، حامل تصريح تعلّم عمره أقل من 18 سنة أُدين بمخالفة أثناء القيادة (moving violation). ماذا يحدث؟","o":["لا يتغيّر شيء بعد دفع الغرامة","يُمدَّد التصريح سنة واحدة","يجب أن ينتظر 180 يومًا على الأقل من يوم المخالفة ليحصل على الرخصة المتوسطة","عليه فقط أن يعيد فحص النظر"],"h1":"المخالفة تؤخّر الخطوة التالية في برنامج رخص المراهقين.","h2":"في Kentucky، المخالفة أثناء القيادة من حامل تصريح عمره أقل من 18 سنة تضيف 180 يومًا على الأقل، تُحسب من يوم المخالفة، قبل أن يستطيع التقدّم للرخصة المتوسطة.","p":"صحيح. المخالفة تضيف 180 يومًا على الأقل إلى مرحلة التصريح."},"ref":{"doc":"KY","page":6}},{"id":"ky-037","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, the parent who signed the permit or license application of a teen under 18 withdraws responsibility. What happens?","o":["The permit or license is canceled until a new application is signed or the teen turns 18","The teen may keep driving with a written warning","The teen pays a fee and keeps the license","The license becomes a permit for 30 days"],"h1":"The parent's signature is what allows the teen to drive.","h2":"In Kentucky, when the signing parent or guardian withdraws responsibility, the teen's permit or license is canceled until another application is signed or the teen turns 18.","p":"Right. Without the parent's signature, the permit or license is canceled."},"es":{"q":"En Kentucky, el padre que firmó la solicitud de permiso o licencia de un joven menor de 18 años retira su responsabilidad. ¿Qué pasa?","o":["El permiso o la licencia se cancela hasta que se firme una nueva solicitud o el joven cumpla 18 años","El joven puede seguir manejando con una advertencia por escrito","El joven paga una cuota y conserva la licencia","La licencia se convierte en un permiso por 30 días"],"h1":"La firma del padre es lo que permite manejar al joven.","h2":"En Kentucky, cuando el padre o tutor que firmó retira su responsabilidad, el permiso o la licencia del joven se cancela hasta que se firme otra solicitud o el joven cumpla 18 años.","p":"Correcto. Sin la firma del padre, el permiso o la licencia se cancela."},"zh":{"q":"在 Kentucky，为未满 18 岁的青少年签署学习驾照或驾照申请的父母撤回了责任。会发生什么？","o":["学习驾照或驾照被取消，直到有人签署新的申请或青少年年满 18 岁","青少年收到一份书面警告后可以继续开车","青少年交一笔费用后可以保留驾照","驾照变成 30 天的学习驾照"],"h1":"父母的签名是青少年可以开车的条件。","h2":"在 Kentucky，当签字的父母或监护人撤回责任时，青少年的学习驾照或驾照会被取消，直到有人签署另一份申请或青少年年满 18 岁。","p":"对。没有父母的签名，学习驾照或驾照就会被取消。"},"vi":{"q":"Ở Kentucky, cha hoặc mẹ đã ký đơn xin giấy phép tập lái hoặc bằng lái cho thiếu niên dưới 18 tuổi rút lại trách nhiệm. Điều gì xảy ra?","o":["Giấy phép tập lái hoặc bằng lái bị hủy cho đến khi có người ký đơn mới hoặc thiếu niên đủ 18 tuổi","Thiếu niên có thể tiếp tục lái xe với một lời cảnh cáo bằng văn bản","Thiếu niên trả một khoản phí và giữ bằng lái","Bằng lái trở thành giấy phép tập lái trong 30 ngày"],"h1":"Chữ ký của cha mẹ là điều cho phép thiếu niên lái xe.","h2":"Ở Kentucky, khi cha mẹ hoặc người giám hộ đã ký rút lại trách nhiệm, giấy phép tập lái hoặc bằng lái của thiếu niên bị hủy cho đến khi có người ký đơn khác hoặc thiếu niên đủ 18 tuổi.","p":"Đúng. Không có chữ ký của cha mẹ, giấy phép tập lái hoặc bằng lái bị hủy."},"tl":{"q":"Sa Kentucky, binawi ng magulang na pumirma sa aplikasyon para sa permit o lisensya ng isang kabataang wala pang 18 ang kanyang pananagutan. Ano ang mangyayari?","o":["Kakanselahin ang permit o lisensya hanggang may pumirma ng bagong aplikasyon o mag-18 na ang kabataan","Puwedeng magpatuloy sa pagmamaneho ang kabataan nang may nakasulat na babala","Magbabayad ng bayarin ang kabataan at mananatili sa kanya ang lisensya","Magiging permit ang lisensya sa loob ng 30 araw"],"h1":"Ang pirma ng magulang ang nagpapahintulot sa kabataan na magmaneho.","h2":"Sa Kentucky, kapag binawi ng pumirmang magulang o tagapag-alaga ang pananagutan, kakanselahin ang permit o lisensya ng kabataan hanggang may pumirma ng ibang aplikasyon o mag-18 na ang kabataan.","p":"Tama. Kung walang pirma ng magulang, kakanselahin ang permit o lisensya."},"ar":{"q":"في Kentucky، سحب الوالد الذي وقّع طلب التصريح أو الرخصة لمراهق عمره أقل من 18 سنة مسؤوليته. ماذا يحدث؟","o":["يُلغى التصريح أو الرخصة إلى أن يُوقَّع طلب جديد أو يبلغ المراهق 18 سنة","يمكن للمراهق أن يستمر في القيادة مع إنذار مكتوب","يدفع المراهق رسومًا ويحتفظ بالرخصة","تصبح الرخصة تصريحًا لمدة 30 يومًا"],"h1":"توقيع الوالد هو ما يسمح للمراهق بالقيادة.","h2":"في Kentucky، عندما يسحب الوالد أو الوصي الذي وقّع مسؤوليته، يُلغى تصريح المراهق أو رخصته إلى أن يُوقَّع طلب آخر أو يبلغ المراهق 18 سنة.","p":"صحيح. بدون توقيع الوالد، يُلغى التصريح أو الرخصة."},"ref":{"doc":"KY","page":17}},{"id":"ky-038","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, police did not investigate your crash, and the damage is over $500. What must you do?","o":["Nothing, if no one was hurt","Call your insurance company only","Report it to the county clerk within 30 days","Send a written report to the Kentucky State Police within 10 days"],"h1":"The report goes to a state agency, and the deadline is short.","h2":"In Kentucky, if a crash causes more than $500 in damage and no officer investigates it, you must send a written report to the Kentucky State Police within 10 days.","p":"Right. File a written report with the State Police within 10 days."},"es":{"q":"En Kentucky, la policía no investigó su choque y los daños pasan de $500. ¿Qué debe hacer?","o":["Nada, si nadie resultó herido","Solo llamar a su compañía de seguros","Reportarlo al secretario del condado en un plazo de 30 días","Enviar un reporte por escrito a la Policía Estatal de Kentucky en un plazo de 10 días"],"h1":"El reporte va a una agencia del estado y el plazo es corto.","h2":"En Kentucky, si un choque causa más de $500 en daños y ningún oficial lo investiga, usted debe enviar un reporte por escrito a la Policía Estatal de Kentucky en un plazo de 10 días.","p":"Correcto. Envíe un reporte por escrito a la Policía Estatal en un plazo de 10 días."},"zh":{"q":"在 Kentucky，警察没有调查你的车祸，而损失超过 $500。你必须做什么？","o":["如果没人受伤，什么都不用做","只需要打电话给你的保险公司","在 30 天内报告给县书记官（county clerk）","在 10 天内把书面报告寄给 Kentucky State Police"],"h1":"报告要交给一个州的机构，而且期限很短。","h2":"在 Kentucky，如果车祸造成超过 $500 的损失，而且没有警察调查，你必须在 10 天内把书面报告寄给 Kentucky State Police（州警察）。","p":"对。要在 10 天内向州警察交书面报告。"},"vi":{"q":"Ở Kentucky, cảnh sát không điều tra vụ tai nạn của bạn, và thiệt hại hơn $500. Bạn phải làm gì?","o":["Không cần làm gì, nếu không ai bị thương","Chỉ cần gọi cho công ty bảo hiểm","Báo cho thư ký quận (county clerk) trong vòng 30 ngày","Gửi báo cáo bằng văn bản cho Cảnh sát Tiểu bang Kentucky (Kentucky State Police) trong vòng 10 ngày"],"h1":"Báo cáo được gửi đến một cơ quan của tiểu bang, và thời hạn ngắn.","h2":"Ở Kentucky, nếu một vụ tai nạn gây thiệt hại hơn $500 và không có cảnh sát nào điều tra, bạn phải gửi báo cáo bằng văn bản cho Cảnh sát Tiểu bang Kentucky trong vòng 10 ngày.","p":"Đúng. Gửi báo cáo bằng văn bản cho Cảnh sát Tiểu bang trong vòng 10 ngày."},"tl":{"q":"Sa Kentucky, hindi inimbestigahan ng pulis ang aksidente mo, at higit sa $500 ang pinsala. Ano ang dapat mong gawin?","o":["Wala, kung walang nasaktan","Tawagan lang ang insurance company mo","I-report ito sa county clerk sa loob ng 30 araw","Magpadala ng nakasulat na report sa Kentucky State Police sa loob ng 10 araw"],"h1":"Sa isang ahensya ng estado napupunta ang report, at maikli ang deadline.","h2":"Sa Kentucky, kung ang aksidente ay nagdulot ng higit sa $500 na pinsala at walang pulis na nag-imbestiga, dapat kang magpadala ng nakasulat na report sa Kentucky State Police sa loob ng 10 araw.","p":"Tama. Magpadala ng nakasulat na report sa State Police sa loob ng 10 araw."},"ar":{"q":"في Kentucky، الشرطة لم تحقّق في حادثك، والأضرار أكثر من $500. ماذا يجب أن تفعل؟","o":["لا شيء، إذا لم يُصب أحد","تتصل بشركة التأمين فقط","تبلّغ كاتب المقاطعة (county clerk) خلال 30 يومًا","ترسل تقريرًا مكتوبًا إلى شرطة ولاية Kentucky (Kentucky State Police) خلال 10 أيام"],"h1":"التقرير يذهب إلى جهة تابعة للولاية، والمهلة قصيرة.","h2":"في Kentucky، إذا سبّب الحادث أضرارًا أكثر من $500 ولم يحقّق فيه أي شرطي، يجب أن ترسل تقريرًا مكتوبًا إلى شرطة ولاية Kentucky خلال 10 أيام.","p":"صحيح. أرسل تقريرًا مكتوبًا إلى شرطة الولاية خلال 10 أيام."},"ref":{"doc":"KY","page":56}},{"id":"ky-039","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the fine for a first DUI conviction within 10 years?","o":["$50 to $100","$200 to $500","$1,000 to $2,000","$5,000 to $10,000"],"h1":"Court costs are added on top of this fine.","h2":"In Kentucky, a first DUI conviction within 10 years carries a fine of $200 to $500, plus court costs, and jail time is also possible.","p":"Right. A first DUI means a fine of $200 to $500."},"es":{"q":"En Kentucky, ¿cuál es la multa por una primera condena por manejar bajo los efectos del alcohol (DUI) en 10 años?","o":["De $50 a $100","De $200 a $500","De $1,000 a $2,000","De $5,000 a $10,000"],"h1":"Los costos del tribunal se suman a esta multa.","h2":"En Kentucky, una primera condena por DUI en 10 años tiene una multa de $200 a $500, más los costos del tribunal, y también puede haber cárcel.","p":"Correcto. Un primer DUI significa una multa de $200 a $500."},"zh":{"q":"在 Kentucky，10 年内第一次被判酒后或药后驾驶（DUI），罚款是多少？","o":["$50 到 $100","$200 到 $500","$1,000 到 $2,000","$5,000 到 $10,000"],"h1":"法庭费用会另外加在这笔罚款上。","h2":"在 Kentucky，10 年内第一次被判 DUI，罚款是 $200 到 $500，另加法庭费用，还可能坐牢。","p":"对。第一次 DUI 罚款 $200 到 $500。"},"vi":{"q":"Ở Kentucky, tiền phạt cho lần đầu bị kết tội lái xe khi say rượu hoặc dùng chất kích thích (DUI) trong vòng 10 năm là bao nhiêu?","o":["$50 đến $100","$200 đến $500","$1,000 đến $2,000","$5,000 đến $10,000"],"h1":"Án phí của tòa được cộng thêm vào tiền phạt này.","h2":"Ở Kentucky, lần đầu bị kết tội DUI trong vòng 10 năm sẽ bị phạt từ $200 đến $500, cộng thêm án phí của tòa, và cũng có thể bị ngồi tù.","p":"Đúng. Lần DUI đầu tiên bị phạt từ $200 đến $500."},"tl":{"q":"Sa Kentucky, magkano ang multa para sa unang DUI conviction (pagmamaneho nang lasing o lango) sa loob ng 10 taon?","o":["$50 hanggang $100","$200 hanggang $500","$1,000 hanggang $2,000","$5,000 hanggang $10,000"],"h1":"Idinadagdag pa ang court costs sa multang ito.","h2":"Sa Kentucky, ang unang DUI conviction sa loob ng 10 taon ay may multang $200 hanggang $500, dagdag ang court costs, at puwede ring makulong.","p":"Tama. Ang unang DUI ay may multang $200 hanggang $500."},"ar":{"q":"في Kentucky، ما الغرامة على أول إدانة بالقيادة تحت تأثير الكحول أو المخدرات (DUI) خلال 10 سنوات؟","o":["من $50 إلى $100","من $200 إلى $500","من $1,000 إلى $2,000","من $5,000 إلى $10,000"],"h1":"تُضاف رسوم المحكمة فوق هذه الغرامة.","h2":"في Kentucky، أول إدانة بـ DUI خلال 10 سنوات عقوبتها غرامة من $200 إلى $500، بالإضافة إلى رسوم المحكمة، ويمكن أيضًا السجن.","p":"صحيح. أول DUI غرامته من $200 إلى $500."},"ref":{"doc":"KY","page":27}},{"id":"ky-040","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, before you take a breath, blood, or urine test after a DUI stop, how long do you get to try to call a lawyer?","o":["No time at all","Up to 2 hours","10 to 15 minutes","24 hours"],"h1":"It is a short time, but it is more than a few seconds.","h2":"In Kentucky, you get at least 10 and no more than 15 minutes to try to contact a lawyer before the test.","p":"Right. You get 10 to 15 minutes to try to reach a lawyer."},"es":{"q":"En Kentucky, antes de hacerse una prueba de aliento, sangre u orina después de una parada por DUI, ¿cuánto tiempo tiene para intentar llamar a un abogado?","o":["Nada de tiempo","Hasta 2 horas","De 10 a 15 minutos","24 horas"],"h1":"Es poco tiempo, pero más que unos segundos.","h2":"En Kentucky, usted tiene al menos 10 y no más de 15 minutos para intentar comunicarse con un abogado antes de la prueba.","p":"Correcto. Tiene de 10 a 15 minutos para intentar hablar con un abogado."},"zh":{"q":"在 Kentucky，因 DUI 被拦下后，在做呼气、验血或验尿测试之前，你有多少时间可以试着联系律师？","o":["完全没有时间","最多 2 小时","10 到 15 分钟","24 小时"],"h1":"时间很短，但比几秒钟要长。","h2":"在 Kentucky，测试前你有至少 10 分钟、最多 15 分钟的时间试着联系律师。","p":"对。你有 10 到 15 分钟试着联系律师。"},"vi":{"q":"Ở Kentucky, sau khi bị chặn xe vì nghi DUI, trước khi làm xét nghiệm hơi thở, máu hoặc nước tiểu, bạn có bao nhiêu thời gian để cố gắng gọi luật sư?","o":["Không có chút thời gian nào","Tối đa 2 giờ","10 đến 15 phút","24 giờ"],"h1":"Thời gian ngắn, nhưng nhiều hơn vài giây.","h2":"Ở Kentucky, bạn có ít nhất 10 phút và không quá 15 phút để cố gắng liên lạc với luật sư trước khi xét nghiệm.","p":"Đúng. Bạn có 10 đến 15 phút để cố gắng liên lạc với luật sư."},"tl":{"q":"Sa Kentucky, pagkatapos kang pahintuin dahil sa DUI, bago ang breath, blood, o urine test, gaano katagal ang ibinibigay sa iyo para subukang tumawag sa abogado?","o":["Walang oras talaga","Hanggang 2 oras","10 hanggang 15 minuto","24 na oras"],"h1":"Maikli ang oras, pero higit ito sa ilang segundo.","h2":"Sa Kentucky, may hindi bababa sa 10 at hindi hihigit sa 15 minuto ka para subukang kontakin ang abogado bago ang test.","p":"Tama. May 10 hanggang 15 minuto ka para subukang kontakin ang abogado."},"ar":{"q":"في Kentucky، بعد إيقافك بسبب DUI، وقبل أن تجري اختبار النفَس أو الدم أو البول، كم من الوقت يُعطى لك لتحاول الاتصال بمحامٍ؟","o":["لا وقت أبدًا","حتى ساعتين (2)","من 10 إلى 15 دقيقة","24 ساعة"],"h1":"الوقت قصير، لكنه أكثر من بضع ثوانٍ.","h2":"في Kentucky، يُعطى لك 10 دقائق على الأقل و15 دقيقة على الأكثر لتحاول الاتصال بمحامٍ قبل الاختبار.","p":"صحيح. لديك من 10 إلى 15 دقيقة لتحاول الوصول إلى محامٍ."},"ref":{"doc":"KY","page":27}},{"id":"ky-041","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, which passenger makes a DUI an aggravating case with mandatory jail time?","o":["A passenger under 12 years old","Any adult passenger","A passenger in the back seat","A passenger who also has a license"],"h1":"The law protects young children riding with an impaired driver.","h2":"In Kentucky, driving under the influence with a passenger under 12 years old is an aggravating circumstance that brings mandatory jail time.","p":"Right. A child under 12 in the car makes a DUI much more serious."},"es":{"q":"En Kentucky, ¿qué pasajero convierte un DUI en un caso agravado con cárcel obligatoria?","o":["Un pasajero menor de 12 años","Cualquier pasajero adulto","Un pasajero en el asiento de atrás","Un pasajero que también tiene licencia"],"h1":"La ley protege a los niños pequeños que viajan con un conductor bajo los efectos del alcohol.","h2":"En Kentucky, manejar bajo los efectos del alcohol con un pasajero menor de 12 años es una circunstancia agravante que trae cárcel obligatoria.","p":"Correcto. Un niño menor de 12 años en el carro hace que un DUI sea mucho más grave."},"zh":{"q":"在 Kentucky，车上有哪种乘客会让 DUI 成为加重情节（aggravating），必须坐牢？","o":["12 岁以下的乘客","任何成年乘客","坐在后座的乘客","也有驾照的乘客"],"h1":"法律保护坐在受影响驾驶人车上的小孩子。","h2":"在 Kentucky，车上载着 12 岁以下的乘客时酒后或药后驾驶，是加重情节，必须坐牢。","p":"对。车上有 12 岁以下的孩子，DUI 就严重得多。"},"vi":{"q":"Ở Kentucky, hành khách nào làm cho tội DUI trở thành trường hợp tăng nặng (aggravating) và bắt buộc phải ngồi tù?","o":["Một hành khách dưới 12 tuổi","Bất kỳ hành khách người lớn nào","Một hành khách ngồi ghế sau","Một hành khách cũng có bằng lái"],"h1":"Luật bảo vệ trẻ nhỏ đi cùng người lái xe đang bị ảnh hưởng bởi rượu hoặc chất kích thích.","h2":"Ở Kentucky, lái xe khi say rượu hoặc dùng chất kích thích mà chở hành khách dưới 12 tuổi là tình tiết tăng nặng và bắt buộc phải ngồi tù.","p":"Đúng. Có trẻ dưới 12 tuổi trong xe làm tội DUI nặng hơn nhiều."},"tl":{"q":"Sa Kentucky, aling pasahero ang nagiging dahilan para maging aggravating (mas mabigat) ang DUI na may sapilitang pagkakulong?","o":["Pasaherong wala pang 12 taong gulang","Kahit sinong pasaherong adulto","Pasahero sa likurang upuan","Pasaherong may lisensya rin"],"h1":"Pinoprotektahan ng batas ang maliliit na batang sakay ng driver na lasing o lango.","h2":"Sa Kentucky, ang pagmamaneho nang lasing o lango na may pasaherong wala pang 12 taong gulang ay aggravating circumstance na may sapilitang pagkakulong.","p":"Tama. Mas mabigat ang DUI kapag may batang wala pang 12 sa sasakyan."},"ar":{"q":"في Kentucky، أي راكب يجعل الـ DUI حالة مشدّدة (aggravating) مع سجن إلزامي؟","o":["راكب عمره أقل من 12 سنة","أي راكب بالغ","راكب في المقعد الخلفي","راكب معه رخصة أيضًا"],"h1":"القانون يحمي الأطفال الصغار الذين يركبون مع سائق تحت تأثير الكحول أو المخدرات.","h2":"في Kentucky، القيادة تحت تأثير الكحول أو المخدرات مع راكب عمره أقل من 12 سنة ظرف مشدّد عقوبته سجن إلزامي.","p":"صحيح. وجود طفل عمره أقل من 12 سنة في السيارة يجعل الـ DUI أخطر بكثير."},"ref":{"doc":"KY","page":27}},{"id":"ky-042","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, a child is 40 inches tall or shorter. How must the child ride?","o":["With an adult seat belt only","On an adult's lap","In the front seat with the air bag on","In a child safety seat that meets federal standards"],"h1":"Small children need special equipment made for their size.","h2":"In Kentucky, a child 40 inches tall or shorter must be secured in a child restraint system that meets federal safety standards.","p":"Right. Children 40 inches or shorter ride in a child safety seat."},"es":{"q":"En Kentucky, un niño mide 40 pulgadas o menos. ¿Cómo debe viajar?","o":["Solo con el cinturón de seguridad de adulto","En las piernas de un adulto","En el asiento delantero con la bolsa de aire activada","En un asiento de seguridad para niños que cumpla las normas federales"],"h1":"Los niños pequeños necesitan un equipo especial hecho para su tamaño.","h2":"En Kentucky, un niño que mide 40 pulgadas o menos debe ir asegurado en un sistema de retención infantil que cumpla las normas federales de seguridad.","p":"Correcto. Los niños de 40 pulgadas o menos viajan en un asiento de seguridad para niños."},"zh":{"q":"在 Kentucky，一个孩子身高 40 英寸或更矮。孩子必须怎么坐车？","o":["只系成人安全带","坐在大人腿上","坐在前座，安全气囊开着","坐在符合联邦标准的儿童安全座椅里"],"h1":"小孩子需要专门为他们的身材设计的设备。","h2":"在 Kentucky，身高 40 英寸或更矮的孩子必须用符合联邦安全标准的儿童安全座椅固定好。","p":"对。40 英寸或更矮的孩子要坐儿童安全座椅。"},"vi":{"q":"Ở Kentucky, một đứa trẻ cao 40 inch trở xuống. Đứa trẻ phải ngồi xe như thế nào?","o":["Chỉ dùng dây an toàn của người lớn","Ngồi trên đùi người lớn","Ngồi ghế trước khi túi khí đang bật","Ngồi trong ghế an toàn cho trẻ em đạt tiêu chuẩn liên bang"],"h1":"Trẻ nhỏ cần thiết bị đặc biệt làm cho cỡ người của các em.","h2":"Ở Kentucky, trẻ cao 40 inch trở xuống phải được giữ chặt trong ghế an toàn cho trẻ em đạt tiêu chuẩn an toàn liên bang.","p":"Đúng. Trẻ cao 40 inch trở xuống phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Kentucky, ang isang bata ay 40 pulgada o mas maliit pa. Paano dapat sumakay ang bata?","o":["Gamit lang ang seat belt ng adulto","Nakakandong sa adulto","Sa harap na upuan habang naka-on ang air bag","Sa child safety seat na pasado sa federal standards"],"h1":"Kailangan ng maliliit na bata ng espesyal na gamit na para sa laki nila.","h2":"Sa Kentucky, ang batang 40 pulgada o mas maliit pa ay dapat nakakabit sa child restraint system na pasado sa federal safety standards.","p":"Tama. Ang batang 40 pulgada o mas maliit ay sumasakay sa child safety seat."},"ar":{"q":"في Kentucky، طفل طوله 40 بوصة أو أقل. كيف يجب أن يركب الطفل؟","o":["بحزام أمان الكبار فقط","في حضن شخص بالغ","في المقعد الأمامي والوسادة الهوائية تعمل","في مقعد أمان للأطفال يطابق المعايير الفيدرالية"],"h1":"الأطفال الصغار يحتاجون إلى معدات خاصة مصنوعة لحجمهم.","h2":"في Kentucky، الطفل الذي طوله 40 بوصة أو أقل يجب أن يُثبَّت في مقعد أمان للأطفال يطابق معايير السلامة الفيدرالية.","p":"صحيح. الأطفال بطول 40 بوصة أو أقل يركبون في مقعد أمان للأطفال."},"ref":{"doc":"KY","page":31}},{"id":"ky-043","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, a child taller than what height no longer has to use a booster seat?","o":["48 inches","57 inches","40 inches","66 inches"],"h1":"It is a little under 5 feet.","h2":"In Kentucky, a child of any age who is taller than 57 inches does not have to use a booster seat; children under 8 who are 40 to 57 inches tall must use one.","p":"Right. Over 57 inches, a booster seat is not required."},"es":{"q":"En Kentucky, ¿a partir de qué estatura un niño ya no tiene que usar un asiento elevado (booster)?","o":["48 pulgadas","57 pulgadas","40 pulgadas","66 pulgadas"],"h1":"Es un poco menos de 5 pies.","h2":"En Kentucky, un niño de cualquier edad que mide más de 57 pulgadas no tiene que usar asiento elevado; los menores de 8 años que miden de 40 a 57 pulgadas deben usarlo.","p":"Correcto. Con más de 57 pulgadas, no se requiere asiento elevado."},"zh":{"q":"在 Kentucky，孩子身高超过多少就不用再坐加高座椅（booster seat）？","o":["48 英寸","57 英寸","40 英寸","66 英寸"],"h1":"比 5 英尺矮一点。","h2":"在 Kentucky，任何年龄的孩子身高超过 57 英寸就不用坐加高座椅；8 岁以下、身高 40 到 57 英寸的孩子必须坐加高座椅。","p":"对。超过 57 英寸就不需要加高座椅。"},"vi":{"q":"Ở Kentucky, trẻ cao hơn bao nhiêu thì không còn phải dùng ghế nâng (booster seat)?","o":["48 inch","57 inch","40 inch","66 inch"],"h1":"Thấp hơn 5 feet một chút.","h2":"Ở Kentucky, trẻ ở bất kỳ tuổi nào cao hơn 57 inch thì không phải dùng ghế nâng; trẻ dưới 8 tuổi cao từ 40 đến 57 inch thì phải dùng.","p":"Đúng. Cao hơn 57 inch thì không bắt buộc dùng ghế nâng."},"tl":{"q":"Sa Kentucky, kapag mas matangkad ang bata sa anong taas, hindi na niya kailangang gumamit ng booster seat?","o":["48 pulgada","57 pulgada","40 pulgada","66 pulgada"],"h1":"Medyo mas mababa ito sa 5 feet.","h2":"Sa Kentucky, ang batang kahit anong edad na mas matangkad sa 57 pulgada ay hindi na kailangang gumamit ng booster seat; ang mga batang wala pang 8 na 40 hanggang 57 pulgada ang taas ay dapat gumamit nito.","p":"Tama. Kapag lampas 57 pulgada, hindi na kailangan ang booster seat."},"ar":{"q":"في Kentucky، الطفل الذي طوله أكثر من كم لا يعود عليه أن يستخدم مقعد الرفع (booster seat)؟","o":["48 بوصة","57 بوصة","40 بوصة","66 بوصة"],"h1":"هو أقل قليلًا من 5 أقدام.","h2":"في Kentucky، الطفل من أي عمر إذا كان طوله أكثر من 57 بوصة ليس عليه أن يستخدم مقعد الرفع؛ أما الأطفال تحت 8 سنوات وطولهم من 40 إلى 57 بوصة فيجب أن يستخدموه.","p":"صحيح. فوق 57 بوصة، مقعد الرفع غير مطلوب."},"ref":{"doc":"KY","page":31}},{"id":"ky-044","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, can a police officer stop you just for not wearing a seat belt?","o":["No, only after another traffic offense","No, seat belts are only a suggestion","Yes, the seat belt law is a primary law","Yes, but only on interstates"],"h1":"Think about whether the officer needs a second reason.","h2":"In Kentucky, the seat belt law is a primary law, so an officer can stop you just because you are not wearing a seat belt, with no other reason needed.","p":"Right. You can be stopped just for not buckling up."},"es":{"q":"En Kentucky, ¿puede un policía detenerlo solo por no usar el cinturón de seguridad?","o":["No, solo después de otra infracción de tránsito","No, el cinturón es solo una sugerencia","Sí, la ley del cinturón es una ley primaria","Sí, pero solo en las autopistas interestatales"],"h1":"Piense si el oficial necesita otra razón.","h2":"En Kentucky, la ley del cinturón de seguridad es una ley primaria, así que un oficial puede detenerlo solamente por no llevar puesto el cinturón, sin necesitar otra razón.","p":"Correcto. Lo pueden detener solo por no abrocharse el cinturón."},"zh":{"q":"在 Kentucky，警察可以只因为你没系安全带就让你停车吗？","o":["不可以，只有在另一项交通违规之后才可以","不可以，安全带只是一个建议","可以，安全带法是主要执法法律（primary law）","可以，但只在州际公路上"],"h1":"想一想警察是否需要第二个理由。","h2":"在 Kentucky，安全带法是主要执法法律（primary law），所以警察可以只因为你没系安全带就让你停车，不需要其他理由。","p":"对。只因为没系安全带，你就可能被拦下。"},"vi":{"q":"Ở Kentucky, cảnh sát có thể chặn xe bạn chỉ vì bạn không thắt dây an toàn không?","o":["Không, chỉ sau khi có một vi phạm giao thông khác","Không, dây an toàn chỉ là một lời khuyên","Có, luật dây an toàn là luật chính (primary law)","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem cảnh sát có cần thêm một lý do thứ hai không.","h2":"Ở Kentucky, luật dây an toàn là luật chính (primary law), nên cảnh sát có thể chặn xe bạn chỉ vì bạn không thắt dây an toàn, không cần lý do nào khác.","p":"Đúng. Bạn có thể bị chặn xe chỉ vì không thắt dây an toàn."},"tl":{"q":"Sa Kentucky, puwede ka bang patigilin ng pulis dahil lang hindi ka nakasuot ng seat belt?","o":["Hindi, pagkatapos lang ng ibang paglabag sa trapiko","Hindi, mungkahi lang ang seat belt","Oo, ang batas sa seat belt ay isang primary law","Oo, pero sa mga interstate lang"],"h1":"Isipin kung kailangan pa ng pulis ng ibang dahilan.","h2":"Sa Kentucky, ang batas sa seat belt ay isang primary law, kaya puwede kang patigilin ng pulis dahil lang hindi ka nakasuot ng seat belt, nang walang ibang dahilan.","p":"Tama. Puwede kang patigilin dahil lang hindi ka nag-seat belt."},"ar":{"q":"في Kentucky، هل يمكن لضابط الشرطة أن يوقفك فقط لأنك لا تربط حزام الأمان؟","o":["لا، فقط بعد مخالفة مرورية أخرى","لا، حزام الأمان مجرد اقتراح","نعم، قانون حزام الأمان قانون أساسي (primary law)","نعم، لكن على الطرق السريعة بين الولايات فقط"],"h1":"فكّر هل يحتاج الضابط إلى سبب ثانٍ.","h2":"في Kentucky، قانون حزام الأمان قانون أساسي (primary law)، لذلك يمكن للضابط أن يوقفك فقط لأنك لا تربط حزام الأمان، دون الحاجة إلى أي سبب آخر.","p":"صحيح. يمكن أن يوقفوك فقط لأنك لم تربط الحزام."},"ref":{"doc":"KY","page":30}},{"id":"ky-045","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, when may you turn left on a red light after you stop?","o":["Only from a one-way street onto another one-way street","At any intersection when no cars are coming","Only from a two-way street with a turn lane","Never, a left turn on red is always banned"],"h1":"Traffic on both streets must be moving in only one direction.","h2":"In Kentucky, after a full stop, you may turn left on red only from a one-way street onto another one-way street, when the way is clear.","p":"Right. Left on red is only from one one-way street onto another."},"es":{"q":"En Kentucky, ¿cuándo puede dar vuelta a la izquierda con la luz roja después de detenerse?","o":["Solo de una calle de un sentido a otra calle de un sentido","En cualquier intersección si no vienen carros","Solo desde una calle de doble sentido con carril de vuelta","Nunca, la vuelta a la izquierda en rojo siempre está prohibida"],"h1":"El tráfico en las dos calles debe ir en un solo sentido.","h2":"En Kentucky, después de detenerse por completo, puede dar vuelta a la izquierda en rojo solo de una calle de un sentido a otra calle de un sentido, cuando el camino esté libre.","p":"Correcto. La vuelta a la izquierda en rojo es solo de una calle de un sentido a otra."},"zh":{"q":"在 Kentucky，停车以后，什么时候可以在红灯时左转？","o":["只能从单行道转到另一条单行道","在任何路口，只要没有车过来","只能从有转弯车道的双向道路","永远不可以，红灯左转一直都是禁止的"],"h1":"两条路上的车都只能朝一个方向走。","h2":"在 Kentucky，完全停车以后，只有从单行道转到另一条单行道、而且路上没车时，才可以在红灯时左转。","p":"对。红灯左转只能从一条单行道转到另一条单行道。"},"vi":{"q":"Ở Kentucky, sau khi dừng lại, khi nào bạn được rẽ trái lúc đèn đỏ?","o":["Chỉ khi từ đường một chiều rẽ vào một đường một chiều khác","Ở bất kỳ giao lộ nào khi không có xe đang tới","Chỉ khi từ đường hai chiều có làn rẽ","Không bao giờ, rẽ trái khi đèn đỏ luôn bị cấm"],"h1":"Xe trên cả hai con đường chỉ được chạy theo một hướng.","h2":"Ở Kentucky, sau khi dừng hẳn, bạn chỉ được rẽ trái lúc đèn đỏ khi từ đường một chiều rẽ vào một đường một chiều khác, và khi đường trống.","p":"Đúng. Chỉ được rẽ trái lúc đèn đỏ từ đường một chiều vào đường một chiều khác."},"tl":{"q":"Sa Kentucky, kailan ka puwedeng kumaliwa kapag pula ang ilaw pagkatapos mong huminto?","o":["Mula lang sa one-way street papunta sa isa pang one-way street","Sa kahit anong intersection kapag walang paparating na sasakyan","Mula lang sa two-way street na may turn lane","Hindi kailanman, laging bawal ang pagkaliwa kapag pula"],"h1":"Dapat iisang direksyon lang ang daloy ng sasakyan sa parehong kalye.","h2":"Sa Kentucky, pagkatapos huminto nang buo, puwede kang kumaliwa kapag pula ang ilaw mula lang sa one-way street papunta sa isa pang one-way street, kapag maluwag ang daan.","p":"Tama. Ang pagkaliwa kapag pula ay mula lang sa isang one-way street papunta sa isa pa."},"ar":{"q":"في Kentucky، بعد أن تتوقف، متى يجوز لك أن تنعطف يسارًا والإشارة حمراء؟","o":["فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","عند أي تقاطع إذا لم تكن هناك سيارات قادمة","فقط من شارع باتجاهين فيه مسار للانعطاف","أبدًا، الانعطاف يسارًا والإشارة حمراء ممنوع دائمًا"],"h1":"السير في الشارعين يجب أن يكون في اتجاه واحد فقط.","h2":"في Kentucky، بعد التوقف التام، يجوز لك أن تنعطف يسارًا والإشارة حمراء فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد، عندما يكون الطريق خاليًا.","p":"صحيح. الانعطاف يسارًا والإشارة حمراء فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد."},"ref":{"doc":"KY","page":35}},{"id":"ky-046","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, how close may you follow an emergency vehicle?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","No closer than 1 mile"],"h1":"It is longer than a football field.","h2":"In Kentucky, it is against the law to follow an emergency vehicle closer than 500 feet.","p":"Right. Stay at least 500 feet behind an emergency vehicle."},"es":{"q":"En Kentucky, ¿qué tan cerca puede seguir a un vehículo de emergencia?","o":["No más cerca de 100 pies","No más cerca de 500 pies","No más cerca de 50 pies","No más cerca de 1 milla"],"h1":"Es más largo que un campo de fútbol americano.","h2":"En Kentucky, es ilegal seguir a un vehículo de emergencia a menos de 500 pies.","p":"Correcto. Manténgase al menos a 500 pies detrás de un vehículo de emergencia."},"zh":{"q":"在 Kentucky，跟在紧急车辆后面时，最近可以跟多近？","o":["不能近于 100 英尺","不能近于 500 英尺","不能近于 50 英尺","不能近于 1 英里"],"h1":"比一个橄榄球场还长。","h2":"在 Kentucky，跟在紧急车辆后面近于 500 英尺是违法的。","p":"对。要和紧急车辆保持至少 500 英尺的距离。"},"vi":{"q":"Ở Kentucky, bạn được chạy theo sau xe cấp cứu gần nhất là bao nhiêu?","o":["Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 50 feet","Không gần hơn 1 dặm"],"h1":"Dài hơn một sân bóng bầu dục.","h2":"Ở Kentucky, chạy theo sau xe cấp cứu gần hơn 500 feet là phạm luật.","p":"Đúng. Hãy ở cách sau xe cấp cứu ít nhất 500 feet."},"tl":{"q":"Sa Kentucky, gaano kalapit ka puwedeng sumunod sa emergency vehicle?","o":["Hindi lalapit sa 100 feet","Hindi lalapit sa 500 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 1 milya"],"h1":"Mas mahaba ito sa isang football field.","h2":"Sa Kentucky, labag sa batas ang sumunod sa emergency vehicle nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng emergency vehicle."},"ar":{"q":"في Kentucky، إلى أي مدى يجوز لك أن تقترب وأنت تسير خلف سيارة طوارئ؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 500 قدم","ليس أقرب من 50 قدم","ليس أقرب من 1 ميل"],"h1":"المسافة أطول من ملعب كرة قدم أمريكية.","h2":"في Kentucky، من المخالف للقانون أن تسير خلف سيارة طوارئ على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل خلف سيارة الطوارئ."},"ref":{"doc":"KY","page":65}},{"id":"ky-047","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, when does a funeral procession have the right-of-way at an intersection?","o":["Only when the light is green for it","Never, it must stop like other traffic","Only on interstate highways","When an escort vehicle with flashing yellow, red, or blue lights leads it"],"h1":"Look for the vehicle at the front of the procession.","h2":"In Kentucky, a funeral procession has the right-of-way at an intersection when it is led by an escort vehicle showing flashing yellow, red, or blue lights.","p":"Right. An escorted funeral procession may go through the intersection."},"es":{"q":"En Kentucky, ¿cuándo tiene el derecho de paso un cortejo fúnebre en una intersección?","o":["Solo cuando la luz está verde para el cortejo","Nunca, debe detenerse como el resto del tráfico","Solo en las autopistas interestatales","Cuando lo guía un vehículo de escolta con luces intermitentes amarillas, rojas o azules"],"h1":"Fíjese en el vehículo que va al frente del cortejo.","h2":"En Kentucky, un cortejo fúnebre tiene el derecho de paso en una intersección cuando lo guía un vehículo de escolta con luces intermitentes amarillas, rojas o azules.","p":"Correcto. Un cortejo fúnebre con escolta puede pasar por la intersección."},"zh":{"q":"在 Kentucky，送葬车队在路口什么时候有优先通行权？","o":["只有在它的方向是绿灯时","永远没有，它必须像其他车一样停下","只在州际公路上","由一辆闪着黄、红或蓝灯的护送车带领时"],"h1":"看看车队最前面的车。","h2":"在 Kentucky，送葬车队由一辆闪着黄灯、红灯或蓝灯的护送车带领时，在路口有优先通行权。","p":"对。有护送车带领的送葬车队可以通过路口。"},"vi":{"q":"Ở Kentucky, khi nào đoàn xe tang có quyền ưu tiên đi trước tại giao lộ?","o":["Chỉ khi đèn xanh cho đoàn xe","Không bao giờ, đoàn xe phải dừng như các xe khác","Chỉ trên xa lộ liên bang","Khi có một xe hộ tống bật đèn nháy vàng, đỏ hoặc xanh dương dẫn đầu"],"h1":"Hãy nhìn chiếc xe ở đầu đoàn xe tang.","h2":"Ở Kentucky, đoàn xe tang có quyền ưu tiên đi trước tại giao lộ khi được dẫn đầu bởi một xe hộ tống bật đèn nháy màu vàng, đỏ hoặc xanh dương.","p":"Đúng. Đoàn xe tang có xe hộ tống được đi qua giao lộ."},"tl":{"q":"Sa Kentucky, kailan may right-of-way ang funeral procession (prusisyon ng libing) sa intersection?","o":["Kapag berde lang ang ilaw para dito","Hindi kailanman, dapat itong huminto gaya ng ibang sasakyan","Sa mga interstate highway lang","Kapag pinangungunahan ito ng escort vehicle na may kumikislap na dilaw, pula, o asul na ilaw"],"h1":"Tingnan ang sasakyan sa unahan ng prusisyon.","h2":"Sa Kentucky, may right-of-way ang funeral procession sa intersection kapag pinangungunahan ito ng escort vehicle na may kumikislap na dilaw, pula, o asul na ilaw.","p":"Tama. Puwedeng dumaan sa intersection ang funeral procession na may escort."},"ar":{"q":"في Kentucky، متى يكون لموكب الجنازة حق المرور عند التقاطع؟","o":["فقط عندما تكون الإشارة خضراء له","أبدًا، يجب أن يتوقف مثل باقي السيارات","فقط على الطرق السريعة بين الولايات","عندما تقوده سيارة مرافقة بأضواء وامضة صفراء أو حمراء أو زرقاء"],"h1":"انظر إلى السيارة في مقدمة الموكب.","h2":"في Kentucky، لموكب الجنازة حق المرور عند التقاطع عندما تقوده سيارة مرافقة تُظهر أضواء وامضة صفراء أو حمراء أو زرقاء.","p":"صحيح. موكب الجنازة الذي ترافقه سيارة يجوز له أن يعبر التقاطع."},"ref":{"doc":"KY","page":68}},{"id":"ky-048","scope":"KY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Kentucky, what is the speed limit in a business or residential district when no limit is posted?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"It is lower than the limit on state highways.","h2":"In Kentucky, the speed limit in a business or residential district is 35 mph when no other limit is posted.","p":"Right. It is 35 mph in business and residential districts."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando no hay un límite indicado?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"Es menor que el límite en las carreteras estatales.","h2":"En Kentucky, el límite de velocidad en una zona comercial o residencial es de 35 mph cuando no hay otro límite indicado.","p":"Correcto. Es de 35 mph en zonas comerciales y residenciales."},"zh":{"q":"在 Kentucky，在商业区或住宅区，没有标示限速时，限速是多少？","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"比州公路上的限速低。","h2":"在 Kentucky，没有标示其他限速时，商业区或住宅区的限速是 35 mph。","p":"对。商业区和住宅区限速 35 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa trong khu thương mại hoặc khu dân cư là bao nhiêu khi không có biển báo tốc độ?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"Thấp hơn tốc độ tối đa trên quốc lộ của tiểu bang.","h2":"Ở Kentucky, tốc độ tối đa trong khu thương mại hoặc khu dân cư là 35 mph khi không có biển báo tốc độ khác.","p":"Đúng. Tốc độ tối đa là 35 mph trong khu thương mại và khu dân cư."},"tl":{"q":"Sa Kentucky, ano ang speed limit sa business o residential district kapag walang nakapaskil na limit?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"Mas mababa ito sa limit sa mga state highway.","h2":"Sa Kentucky, 35 mph ang speed limit sa business o residential district kapag walang ibang nakapaskil na limit.","p":"Tama. 35 mph ito sa mga business at residential district."},"ar":{"q":"في Kentucky، ما حدّ السرعة في منطقة تجارية أو سكنية عندما لا توجد لافتة بحدّ السرعة؟","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"هو أقل من حدّ السرعة على طرق الولاية السريعة.","h2":"في Kentucky، حدّ السرعة في منطقة تجارية أو سكنية هو 35 mph عندما لا توجد لافتة بحدّ آخر.","p":"صحيح. الحدّ هو 35 mph في المناطق التجارية والسكنية."},"ref":{"doc":"KY","page":49}},{"id":"ky-049","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the speed limit in a parking lot that is open to the public?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"It is less than half the limit in a residential district.","h2":"In Kentucky, the speed limit in an off-street parking lot open to the public is 15 mph, whether it is owned by the public or a private owner.","p":"Right. Keep it at 15 mph in public parking lots."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad en un estacionamiento abierto al público?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"Es menos de la mitad del límite en una zona residencial.","h2":"En Kentucky, el límite de velocidad en un estacionamiento fuera de la calle abierto al público es de 15 mph, sea de propiedad pública o privada.","p":"Correcto. Vaya a 15 mph en los estacionamientos públicos."},"zh":{"q":"在 Kentucky，对公众开放的停车场限速是多少？","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"不到住宅区限速的一半。","h2":"在 Kentucky，对公众开放的路外停车场限速是 15 mph，不管停车场是公家的还是私人的。","p":"对。在公共停车场要保持 15 mph。"},"vi":{"q":"Ở Kentucky, tốc độ tối đa trong bãi đậu xe mở cửa cho công chúng là bao nhiêu?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"Chưa tới một nửa tốc độ tối đa trong khu dân cư.","h2":"Ở Kentucky, tốc độ tối đa trong bãi đậu xe ngoài đường mở cửa cho công chúng là 15 mph, dù bãi đó thuộc nhà nước hay chủ tư nhân.","p":"Đúng. Hãy giữ 15 mph trong bãi đậu xe công cộng."},"tl":{"q":"Sa Kentucky, ano ang speed limit sa parking lot na bukas sa publiko?","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"Kulang ito sa kalahati ng limit sa residential district.","h2":"Sa Kentucky, 15 mph ang speed limit sa off-street parking lot na bukas sa publiko, pag-aari man ito ng gobyerno o ng pribadong may-ari.","p":"Tama. Panatilihin sa 15 mph sa mga pampublikong parking lot."},"ar":{"q":"في Kentucky، ما حدّ السرعة في موقف سيارات مفتوح للعامة؟","o":["5 mph","25 mph","15 mph","35 mph"],"h1":"هو أقل من نصف الحدّ في المنطقة السكنية.","h2":"في Kentucky، حدّ السرعة في موقف سيارات خارج الشارع ومفتوح للعامة هو 15 mph، سواء كان ملكًا عامًا أو لمالك خاص.","p":"صحيح. التزم بـ 15 mph في مواقف السيارات العامة."},"ref":{"doc":"KY","page":49}},{"id":"ky-050","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, heavy rain, snow, or fog lets you see no more than 100 feet ahead. What is the fastest you can safely drive?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"It is the same as many school zone limits.","h2":"In Kentucky, when you cannot see more than 100 feet ahead, you cannot safely drive faster than 25 mph, and you should use low beams.","p":"Right. With 100 feet of view or less, stay at 25 mph or slower."},"es":{"q":"En Kentucky, por lluvia fuerte, nieve o neblina, usted no puede ver más de 100 pies adelante. ¿Cuál es la velocidad máxima segura?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"Es igual que el límite de muchas zonas escolares.","h2":"En Kentucky, cuando no puede ver más de 100 pies adelante, no puede manejar con seguridad a más de 25 mph, y debe usar las luces bajas.","p":"Correcto. Si ve 100 pies o menos, vaya a 25 mph o menos."},"zh":{"q":"在 Kentucky，大雨、大雪或大雾让你只能看到前方不超过 100 英尺。你最快能安全地开多快？","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"和很多学校区的限速一样。","h2":"在 Kentucky，当你看不到 100 英尺以外时，安全行驶的速度不能超过 25 mph，而且应该开近光灯。","p":"对。能看到的距离只有 100 英尺或更短时，要保持 25 mph 或更慢。"},"vi":{"q":"Ở Kentucky, mưa lớn, tuyết hoặc sương mù làm bạn chỉ nhìn thấy không quá 100 feet phía trước. Tốc độ nhanh nhất bạn có thể lái an toàn là bao nhiêu?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"Bằng tốc độ tối đa ở nhiều khu trường học.","h2":"Ở Kentucky, khi bạn không nhìn thấy xa hơn 100 feet phía trước, bạn không thể lái an toàn nhanh hơn 25 mph, và bạn nên dùng đèn cốt (đèn chiếu gần).","p":"Đúng. Khi chỉ nhìn thấy 100 feet hoặc ít hơn, hãy chạy 25 mph hoặc chậm hơn."},"tl":{"q":"Sa Kentucky, dahil sa malakas na ulan, niyebe, o hamog, hindi ka makakita nang lampas sa 100 feet sa harap. Ano ang pinakamabilis na ligtas mong takbo?","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"Pareho ito sa limit sa maraming school zone.","h2":"Sa Kentucky, kapag hindi ka makakita nang lampas sa 100 feet sa harap, hindi ka ligtas na makakatakbo nang mas mabilis sa 25 mph, at dapat kang gumamit ng low beams.","p":"Tama. Kapag 100 feet o mas maikli ang tanaw mo, manatili sa 25 mph o mas mabagal."},"ar":{"q":"في Kentucky، المطر الغزير أو الثلج أو الضباب يجعلك لا ترى أكثر من 100 قدم أمامك. ما أعلى سرعة يمكنك أن تقود بها بأمان؟","o":["15 mph","25 mph","45 mph","35 mph"],"h1":"هي نفس حدّ السرعة في كثير من مناطق المدارس.","h2":"في Kentucky، عندما لا تستطيع أن ترى أكثر من 100 قدم أمامك، لا يمكنك أن تقود بأمان أسرع من 25 mph، ويجب أن تستخدم الأضواء المنخفضة.","p":"صحيح. إذا كانت الرؤية 100 قدم أو أقل، ابقَ على 25 mph أو أبطأ."},"ref":{"doc":"KY","page":50}},{"id":"ky-051","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, during which hours must your headlights be on?","o":["Only after 9 p.m.","From one hour after sunset to one hour before sunrise","Only when there are no street lights","From half an hour after sunset to half an hour before sunrise"],"h1":"The time is measured from sunset and sunrise.","h2":"In Kentucky, headlights must be on from half an hour after sunset until half an hour before sunrise.","p":"Right. Lights on from 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Kentucky, ¿durante qué horas deben estar encendidas sus luces delanteras?","o":["Solo después de las 9 p.m.","Desde una hora después de la puesta del sol hasta una hora antes del amanecer","Solo cuando no hay alumbrado público","Desde media hora después de la puesta del sol hasta media hora antes del amanecer"],"h1":"El tiempo se cuenta desde la puesta del sol y el amanecer.","h2":"En Kentucky, las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Luces encendidas desde 30 minutos después de la puesta del sol hasta 30 minutos antes del amanecer."},"zh":{"q":"在 Kentucky，哪段时间你的车头灯必须打开？","o":["只在晚上 9 点以后","从日落后一小时到日出前一小时","只在没有路灯的时候","从日落后半小时到日出前半小时"],"h1":"时间是从日落和日出算起的。","h2":"在 Kentucky，从日落后半小时到日出前半小时，车头灯必须打开。","p":"对。从日落后 30 分钟到日出前 30 分钟要开灯。"},"vi":{"q":"Ở Kentucky, đèn pha của bạn phải bật trong khoảng thời gian nào?","o":["Chỉ sau 9 giờ tối","Từ một giờ sau khi mặt trời lặn đến một giờ trước khi mặt trời mọc","Chỉ khi không có đèn đường","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc"],"h1":"Thời gian được tính từ lúc mặt trời lặn và lúc mặt trời mọc.","h2":"Ở Kentucky, đèn pha phải bật từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Bật đèn từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc."},"tl":{"q":"Sa Kentucky, sa anong mga oras dapat nakabukas ang headlights mo?","o":["Pagkatapos lang ng 9 p.m.","Mula isang oras pagkalubog ng araw hanggang isang oras bago sumikat ang araw","Kapag walang ilaw sa kalye lang","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw"],"h1":"Binibilang ang oras mula sa paglubog at pagsikat ng araw.","h2":"Sa Kentucky, dapat nakabukas ang headlights mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Bukas ang ilaw mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw."},"ar":{"q":"في Kentucky، في أي ساعات يجب أن تكون أضواء سيارتك الأمامية مضاءة؟","o":["فقط بعد الساعة 9 مساءً","من ساعة بعد غروب الشمس إلى ساعة قبل شروقها","فقط عندما لا توجد أضواء في الشارع","من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها"],"h1":"الوقت يُحسب من غروب الشمس وشروقها.","h2":"في Kentucky، يجب أن تكون الأضواء الأمامية مضاءة من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. الأضواء مضاءة من 30 دقيقة بعد الغروب إلى 30 دقيقة قبل الشروق."},"ref":{"doc":"KY","page":54}},{"id":"ky-052","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, when must you dim your high beams for an oncoming vehicle?","o":["When it is within 500 feet","When it is within 100 feet","When it is within 1 mile","Only when it flashes its lights at you"],"h1":"The distance is longer than a football field.","h2":"In Kentucky, you must dim your high beams within 500 feet of an oncoming vehicle, and within 300 feet of a vehicle you are following.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Kentucky, ¿cuándo debe bajar las luces altas por un vehículo que viene de frente?","o":["Cuando está a menos de 500 pies","Cuando está a menos de 100 pies","Cuando está a menos de 1 milla","Solo cuando le hace cambio de luces"],"h1":"La distancia es más larga que un campo de fútbol americano.","h2":"En Kentucky, debe bajar las luces altas a menos de 500 pies de un vehículo que viene de frente, y a menos de 300 pies de un vehículo que va siguiendo.","p":"Correcto. Baje las luces a menos de 500 pies del tráfico que viene de frente."},"zh":{"q":"在 Kentucky，对面有车开过来时，你必须在什么时候把远光灯调成近光灯？","o":["在它离你 500 英尺以内时","在它离你 100 英尺以内时","在它离你 1 英里以内时","只有在它对你闪灯时"],"h1":"这个距离比一个橄榄球场还长。","h2":"在 Kentucky，对面来车在 500 英尺以内时，你必须把远光灯调暗；跟在别的车后面 300 英尺以内时，也必须调暗。","p":"对。对面来车在 500 英尺以内时要调暗车灯。"},"vi":{"q":"Ở Kentucky, khi nào bạn phải hạ đèn pha (đèn chiếu xa) cho xe đi ngược chiều?","o":["Khi xe đó ở trong vòng 500 feet","Khi xe đó ở trong vòng 100 feet","Khi xe đó ở trong vòng 1 dặm","Chỉ khi xe đó nháy đèn với bạn"],"h1":"Khoảng cách này dài hơn một sân bóng bầu dục.","h2":"Ở Kentucky, bạn phải hạ đèn pha khi cách xe đi ngược chiều trong vòng 500 feet, và khi cách xe bạn đang chạy theo sau trong vòng 300 feet.","p":"Đúng. Hạ đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Kentucky, kailan mo dapat i-dim ang high beams mo para sa paparating na sasakyan?","o":["Kapag nasa loob ito ng 500 feet","Kapag nasa loob ito ng 100 feet","Kapag nasa loob ito ng 1 milya","Kapag kinislapan ka lang nito ng ilaw"],"h1":"Mas mahaba ang layo kaysa sa isang football field.","h2":"Sa Kentucky, dapat mong i-dim ang high beams mo kapag nasa loob ng 500 feet ang paparating na sasakyan, at kapag nasa loob ng 300 feet ang sasakyang sinusundan mo.","p":"Tama. I-dim ang ilaw mo kapag nasa loob ng 500 feet ang paparating na sasakyan."},"ar":{"q":"في Kentucky، متى يجب أن تخفّض الأضواء العالية لسيارة قادمة من الاتجاه المقابل؟","o":["عندما تكون على بعد 500 قدم أو أقل","عندما تكون على بعد 100 قدم أو أقل","عندما تكون على بعد 1 ميل أو أقل","فقط عندما تومض بأضوائها نحوك"],"h1":"المسافة أطول من ملعب كرة قدم أمريكية.","h2":"في Kentucky، يجب أن تخفّض الأضواء العالية عندما تكون على بعد 500 قدم أو أقل من سيارة قادمة، وعلى بعد 300 قدم أو أقل من سيارة تسير خلفها.","p":"صحيح. خفّض أضواءك عندما تكون السيارة القادمة على بعد 500 قدم أو أقل."},"ref":{"doc":"KY","page":68}},{"id":"ky-053","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, which license class is the basic operator's license for a car?","o":["Class D","Class A","Class E","Class M"],"h1":"It is the class most Kentucky drivers hold, and it comes after the commercial classes.","h2":"In Kentucky, the Class D license is the basic operator's license that most drivers use for a car.","p":"Right. Class D is the regular operator's license."},"es":{"q":"En Kentucky, ¿qué clase de licencia es la licencia básica de conductor para un auto?","o":["Clase D","Clase A","Clase E","Clase M"],"h1":"Es la clase que tiene la mayoría de los conductores de Kentucky y viene después de las clases comerciales.","h2":"En Kentucky, la licencia Clase D es la licencia básica de conductor que la mayoría usa para manejar un auto.","p":"Correcto. La Clase D es la licencia normal de conductor."},"ref":{"doc":"KY","page":1}},{"id":"ky-054","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what can you drive with a Class E license?","o":["A motorcycle","A moped only","A school bus","Any car or light truck"],"h1":"It is the smallest vehicle class in the state.","h2":"In Kentucky, a Class E license is only for mopeds.","p":"Right. Class E is for mopeds only."},"es":{"q":"En Kentucky, ¿qué puede manejar con una licencia Clase E?","o":["Una motocicleta","Solo un ciclomotor (moped)","Un autobús escolar","Cualquier auto o camioneta liviana"],"h1":"Es la clase para el vehículo más pequeño del estado.","h2":"En Kentucky, la licencia Clase E es solo para ciclomotores (mopeds).","p":"Correcto. La Clase E es solo para ciclomotores."},"ref":{"doc":"KY","page":1}},{"id":"ky-055","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, which license classes are commercial driver's licenses?","o":["Classes D and E","Classes D and M","Classes A, B, and C","Classes M and E"],"h1":"These are the first three letters of the alphabet.","h2":"In Kentucky, Classes A, B, and C are the commercial driver's license classes.","p":"Right. A, B, and C are the commercial classes."},"es":{"q":"En Kentucky, ¿qué clases de licencia son licencias de conducir comerciales?","o":["Clases D y E","Clases D y M","Clases A, B y C","Clases M y E"],"h1":"Son las tres primeras letras del alfabeto.","h2":"En Kentucky, las Clases A, B y C son las licencias de conducir comerciales.","p":"Correcto. A, B y C son las clases comerciales."},"ref":{"doc":"KY","page":1}},{"id":"ky-056","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what is the top speed a vehicle can be built for and still count as a moped?","o":["20 mph","30 mph","45 mph","55 mph"],"h1":"It is a low speed, the same as many city side streets.","h2":"In Kentucky, a moped can be capable of no more than 30 miles per hour.","p":"Right. A moped tops out at 30 mph."},"es":{"q":"En Kentucky, ¿cuál es la velocidad máxima que puede alcanzar un vehículo para que todavía cuente como ciclomotor (moped)?","o":["20 mph","30 mph","45 mph","55 mph"],"h1":"Es una velocidad baja, como la de muchas calles de la ciudad.","h2":"En Kentucky, un ciclomotor no puede alcanzar más de 30 millas por hora.","p":"Correcto. Un ciclomotor llega como máximo a 30 mph."},"ref":{"doc":"KY","page":2}},{"id":"ky-057","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, you have no license of any kind and want a Class E moped license. Which tests must you pass?","o":["Only a road skills test","The vision, knowledge, and road skills tests","No tests, only a fee","The vision test and the general knowledge test"],"h1":"No permit and no road test are needed for this class.","h2":"In Kentucky, a Class E moped license needs only the vision test and the general knowledge test; no permit or skills test is required.","p":"Right. Vision and knowledge tests are enough for Class E."},"es":{"q":"En Kentucky, usted no tiene ninguna licencia y quiere una licencia Clase E para ciclomotor. ¿Qué exámenes debe aprobar?","o":["Solo un examen práctico de manejo","Los exámenes de la vista, de conocimientos y práctico de manejo","Ninguno, solo pagar una tarifa","El examen de la vista y el examen de conocimientos generales"],"h1":"Para esta clase no se necesita permiso ni examen práctico.","h2":"En Kentucky, la licencia Clase E para ciclomotor solo requiere el examen de la vista y el de conocimientos generales; no se necesita permiso ni examen práctico.","p":"Correcto. Para la Clase E bastan los exámenes de la vista y de conocimientos."},"ref":{"doc":"KY","page":2}},{"id":"ky-058","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how old must you be to ride a moped on the road?","o":["At least 16","At least 14","At least 15","At least 18"],"h1":"It is one year older than the youngest age to apply for a learner's permit.","h2":"In Kentucky, you must be at least 16 years old to ride a moped on the road.","p":"Right. Moped riders must be at least 16."},"es":{"q":"En Kentucky, ¿qué edad debe tener para manejar un ciclomotor (moped) en la vía?","o":["Al menos 16 años","Al menos 14 años","Al menos 15 años","Al menos 18 años"],"h1":"Es un año más que la edad mínima para pedir el permiso de aprendizaje.","h2":"En Kentucky, debe tener al menos 16 años para manejar un ciclomotor en la vía.","p":"Correcto. Hay que tener al menos 16 años."},"ref":{"doc":"KY","page":2}},{"id":"ky-059","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, must a moped rider wear a helmet?","o":["Yes, always","No, but a helmet and eye protection are strongly advised","Only on roads faster than 35 mph","Only if the rider is under 21"],"h1":"The manual recommends it, but the law does not require it for mopeds.","h2":"In Kentucky, moped riders are not required to wear a helmet or eye protection, but both are strongly recommended.","p":"Right. Not required, but strongly recommended."},"es":{"q":"En Kentucky, ¿debe usar casco quien maneja un ciclomotor (moped)?","o":["Sí, siempre","No, pero se recomienda mucho usar casco y protección para los ojos","Solo en vías de más de 35 mph","Solo si es menor de 21 años"],"h1":"El manual lo recomienda, pero la ley no lo exige para ciclomotores.","h2":"En Kentucky, no se exige casco ni protección para los ojos a quienes manejan ciclomotores, pero se recomiendan mucho.","p":"Correcto. No es obligatorio, pero se recomienda mucho."},"ref":{"doc":"KY","page":3}},{"id":"ky-060","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, where may a moped never be ridden?","o":["On any city street","On a two-lane country road","On a limited-access highway with a minimum speed above 30 mph","On a street with a bike lane"],"h1":"Think of fast roads where traffic must keep up a set speed.","h2":"In Kentucky, a moped may not be ridden on a limited-access highway where the minimum speed is more than 30 mph.","p":"Right. Mopeds stay off fast limited-access highways."},"es":{"q":"En Kentucky, ¿por dónde nunca se puede manejar un ciclomotor (moped)?","o":["Por ninguna calle de la ciudad","Por una carretera rural de dos carriles","Por una autopista de acceso limitado con velocidad mínima de más de 30 mph","Por una calle con carril para bicicletas"],"h1":"Piense en vías rápidas donde el tráfico debe mantener cierta velocidad.","h2":"En Kentucky, no se puede manejar un ciclomotor en una autopista de acceso limitado donde la velocidad mínima es de más de 30 mph.","p":"Correcto. Los ciclomotores no van por autopistas rápidas de acceso limitado."},"ref":{"doc":"KY","page":3}},{"id":"ky-061","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, who may apply for a motorcycle instruction permit?","o":["A person with a valid intermediate license, or anyone 18 or older","Anyone 14 or older","Only people who already have a full license for 2 years","Only people 21 or older"],"h1":"A teen needs to be past the learner's permit stage first.","h2":"In Kentucky, a person with a valid intermediate license, or anyone at least 18, may apply for a motorcycle instruction permit.","p":"Right. Intermediate license holders and anyone 18 or older can apply."},"es":{"q":"En Kentucky, ¿quién puede solicitar un permiso de aprendizaje para motocicleta?","o":["Una persona con licencia intermedia válida, o cualquiera de 18 años o más","Cualquiera de 14 años o más","Solo quien tiene licencia completa desde hace 2 años","Solo personas de 21 años o más"],"h1":"Un adolescente primero tiene que pasar la etapa del permiso de aprendizaje.","h2":"En Kentucky, puede solicitar un permiso de aprendizaje para motocicleta quien tiene licencia intermedia válida o cualquier persona de al menos 18 años.","p":"Correcto. Quien tiene licencia intermedia o tiene 18 años o más."},"ref":{"doc":"KY","page":3}},{"id":"ky-062","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, a 17-year-old's parent already signed for a car license. What is needed for a motorcycle permit?","o":["A parent or guardian must sign the motorcycle permit application too","Nothing more; the first signature counts","A note from the school","A signature from any adult over 21"],"h1":"Riding a motorcycle is a separate responsibility.","h2":"In Kentucky, a minor's motorcycle permit application must be signed by a parent or guardian, even if they already signed for a car or moped license.","p":"Right. The parent must sign again for the motorcycle permit."},"es":{"q":"En Kentucky, el padre de un joven de 17 años ya firmó para su licencia de auto. ¿Qué se necesita para un permiso de motocicleta?","o":["El padre, la madre o el tutor debe firmar también la solicitud del permiso de motocicleta","Nada más; la primera firma cuenta","Una nota de la escuela","La firma de cualquier adulto mayor de 21 años"],"h1":"Manejar motocicleta es una responsabilidad aparte.","h2":"En Kentucky, la solicitud de permiso de motocicleta de un menor debe ir firmada por su padre, madre o tutor, aunque ya hayan firmado para la licencia de auto o ciclomotor.","p":"Correcto. El padre o tutor debe firmar otra vez para la motocicleta."},"ref":{"doc":"KY","page":3}},{"id":"ky-063","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what lets a new rider skip the motorcycle written and skills tests?","o":["Riding for one year on private land","Holding a car license for five years","Finishing an approved RideSmartKY rider training course","Passing a bicycle safety class"],"h1":"The state runs a rider safety program for this.","h2":"In Kentucky, showing proof that you completed an approved RideSmartKY rider training course excuses you from the motorcycle written and skills tests.","p":"Right. An approved RideSmartKY course replaces those tests."},"es":{"q":"En Kentucky, ¿qué permite a un motociclista nuevo no tomar los exámenes escrito y práctico de motocicleta?","o":["Manejar un año en terreno privado","Tener licencia de auto por cinco años","Terminar un curso aprobado de RideSmartKY para motociclistas","Aprobar una clase de seguridad en bicicleta"],"h1":"El estado tiene un programa de seguridad para motociclistas.","h2":"En Kentucky, si demuestra que terminó un curso aprobado de RideSmartKY, no tiene que tomar los exámenes escrito y práctico de motocicleta.","p":"Correcto. Un curso aprobado de RideSmartKY reemplaza esos exámenes."},"ref":{"doc":"KY","page":4}},{"id":"ky-064","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, do you need a motorcycle permit to sign up for a RideSmartKY rider course?","o":["Yes, a permit is required first","Yes, and a full license too","Only if you are under 21","No, the course is open without a permit or license"],"h1":"The course is open to anyone interested.","h2":"In Kentucky, you do not need a motorcycle permit or license to sign up for RideSmartKY rider training.","p":"Right. No permit is needed to take the course."},"es":{"q":"En Kentucky, ¿necesita un permiso de motocicleta para inscribirse en un curso de RideSmartKY?","o":["Sí, primero se necesita el permiso","Sí, y también una licencia completa","Solo si es menor de 21 años","No, el curso está abierto sin permiso ni licencia"],"h1":"El curso está abierto a cualquier interesado.","h2":"En Kentucky, no necesita permiso ni licencia de motocicleta para inscribirse en un curso de RideSmartKY.","p":"Correcto. No se necesita permiso para tomar el curso."},"ref":{"doc":"KY","page":3}},{"id":"ky-065","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, a person lives in Indiana, works in Kentucky, and has a valid Indiana license. Do they need a Kentucky license?","o":["Yes, within 30 days of starting work","No, a nonresident working in Kentucky may use a valid license from another state","Yes, but only to drive a work vehicle","Only if they work more than 40 hours a week"],"h1":"The rule is about where you live, not where you work.","h2":"In Kentucky, a nonresident who works in the state and holds a valid license from another state does not need a Kentucky license.","p":"Right. Nonresident workers can use their valid home-state license."},"es":{"q":"En Kentucky, una persona vive en Indiana, trabaja en Kentucky y tiene una licencia válida de Indiana. ¿Necesita una licencia de Kentucky?","o":["Sí, dentro de 30 días de empezar a trabajar","No, quien no es residente y trabaja en Kentucky puede usar una licencia válida de otro estado","Sí, pero solo para manejar un vehículo del trabajo","Solo si trabaja más de 40 horas por semana"],"h1":"La regla depende de dónde vive, no de dónde trabaja.","h2":"En Kentucky, quien no es residente, trabaja en el estado y tiene una licencia válida de otro estado no necesita licencia de Kentucky.","p":"Correcto. Los trabajadores no residentes pueden usar la licencia válida de su estado."},"ref":{"doc":"KY","page":2}},{"id":"ky-066","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a soldier on active duty is stationed here with a valid license from another state. Must the soldier get a Kentucky license?","o":["Yes, within 10 days","Yes, before driving on base","No, active-duty members and their dependents may use a valid license from another state","Only if the soldier buys a car here"],"h1":"The law makes an exception for military families.","h2":"In Kentucky, active-duty military members and their dependents with a valid license from another state do not need a Kentucky license.","p":"Right. Active-duty members and their families can keep their valid license."},"es":{"q":"En Kentucky, un soldado en servicio activo está asignado aquí y tiene una licencia válida de otro estado. ¿Debe sacar una licencia de Kentucky?","o":["Sí, dentro de 10 días","Sí, antes de manejar en la base","No, los militares en servicio activo y sus dependientes pueden usar una licencia válida de otro estado","Solo si compra un auto aquí"],"h1":"La ley hace una excepción para las familias militares.","h2":"En Kentucky, los militares en servicio activo y sus dependientes con licencia válida de otro estado no necesitan licencia de Kentucky.","p":"Correcto. Los militares activos y sus familias pueden usar su licencia válida."},"ref":{"doc":"KY","page":2}},{"id":"ky-067","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, a parent signs a teen's permit application. What does that signature mean?","o":["Nothing beyond giving permission","The parent shares legal responsibility for damages the teen causes","The parent must ride along on every trip","The parent pays the teen's tickets only"],"h1":"Signing is about more than permission; it is about money and damages.","h2":"In Kentucky, a parent or guardian who signs a minor's application becomes jointly liable with the teen for damages.","p":"Right. The signer shares responsibility for damages."},"es":{"q":"En Kentucky, un padre firma la solicitud de permiso de su hijo adolescente. ¿Qué significa esa firma?","o":["Solo que da permiso","El padre comparte la responsabilidad legal por los daños que cause el joven","El padre debe ir en cada viaje","El padre paga solo las multas del joven"],"h1":"Firmar es más que dar permiso; tiene que ver con dinero y daños.","h2":"En Kentucky, el padre, la madre o el tutor que firma la solicitud de un menor es responsable junto con el joven por los daños.","p":"Correcto. Quien firma comparte la responsabilidad por los daños."},"ref":{"doc":"KY","page":4}},{"id":"ky-068","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, where must the parent or guardian sign a teen's application?","o":["At the testing location, where an official can witness the signature","Online, from any device","At home, then mail it in","At the teen's school office"],"h1":"Someone needs to see the signature and check guardianship.","h2":"In Kentucky, the parent or guardian must sign the teen's application at the testing location so an official can witness it and verify guardianship.","p":"Right. The signature is witnessed at the testing location."},"es":{"q":"En Kentucky, ¿dónde debe firmar el padre o tutor la solicitud de un adolescente?","o":["En el lugar del examen, donde un funcionario puede ser testigo de la firma","En línea, desde cualquier aparato","En casa, y luego enviarla por correo","En la oficina de la escuela del joven"],"h1":"Alguien tiene que ver la firma y verificar la tutela.","h2":"En Kentucky, el padre o tutor debe firmar la solicitud del adolescente en el lugar del examen, para que un funcionario sea testigo y verifique la tutela.","p":"Correcto. La firma se hace con testigo en el lugar del examen."},"ref":{"doc":"KY","page":4}},{"id":"ky-069","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, you bring a photocopy of your birth certificate to apply for a permit. What happens?","o":["It is not accepted; you need the original or a certified copy","It is accepted with a parent's signature","It is accepted for drivers under 18 only","It is accepted if it is clear"],"h1":"Required documents must be originals or certified copies.","h2":"In Kentucky, photocopies are not accepted for any required document; bring the original birth certificate or a certified copy.","p":"Right. No photocopies; bring the original or a certified copy."},"es":{"q":"En Kentucky, usted lleva una fotocopia de su acta de nacimiento para pedir un permiso. ¿Qué pasa?","o":["No la aceptan; necesita el original o una copia certificada","La aceptan con la firma de un padre","La aceptan solo para menores de 18 años","La aceptan si se ve clara"],"h1":"Los documentos requeridos deben ser originales o copias certificadas.","h2":"En Kentucky, no se aceptan fotocopias de ningún documento requerido; lleve el acta de nacimiento original o una copia certificada.","p":"Correcto. Nada de fotocopias; lleve el original o una copia certificada."},"ref":{"doc":"KY","page":5}},{"id":"ky-070","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, what school form must a teen under 18 bring to apply for a permit?","o":["A School Compliance Verification Form","A report card with all A's","A letter from a teacher","A driver education certificate"],"h1":"It is tied to the No Pass/No Drive law.","h2":"In Kentucky, a teen under 18 must bring a School Compliance Verification Form from their school, under the No Pass/No Drive law.","p":"Right. The School Compliance Verification Form is required."},"es":{"q":"En Kentucky, ¿qué formulario escolar debe llevar un joven menor de 18 años para pedir un permiso?","o":["Un formulario de verificación de cumplimiento escolar (School Compliance Verification Form)","Una boleta de calificaciones con todas A","Una carta de un maestro","Un certificado de educación vial"],"h1":"Tiene que ver con la ley No Pass/No Drive (si no apruebas, no manejas).","h2":"En Kentucky, un joven menor de 18 años debe llevar el formulario de verificación de cumplimiento escolar de su escuela, según la ley No Pass/No Drive.","p":"Correcto. Se requiere el formulario de verificación de cumplimiento escolar."},"ref":{"doc":"KY","page":5}},{"id":"ky-071","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, where must the licensed adult sit when a permit holder is driving?","o":["In the back seat behind the driver","In the front passenger seat beside the driver","Anywhere in the car","In a second car following behind"],"h1":"The adult needs to be close enough to help right away.","h2":"In Kentucky, the licensed driver who is 21 or older must sit in the front passenger seat beside the permit holder.","p":"Right. The supervising adult sits in the front passenger seat."},"es":{"q":"En Kentucky, ¿dónde debe sentarse el adulto con licencia cuando maneja alguien con permiso?","o":["En el asiento de atrás, detrás del conductor","En el asiento delantero del pasajero, al lado del conductor","En cualquier lugar del auto","En otro auto que va detrás"],"h1":"El adulto debe estar lo bastante cerca para ayudar enseguida.","h2":"En Kentucky, el conductor con licencia de 21 años o más debe ir en el asiento delantero del pasajero, al lado de quien tiene el permiso.","p":"Correcto. El adulto que supervisa va en el asiento delantero del pasajero."},"ref":{"doc":"KY","page":5}},{"id":"ky-072","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a teen's permit is suspended under the No Pass/No Drive law. What happens to the 180-day permit period?","o":["It keeps counting as normal","It is cut in half","Days while suspended do not count toward the 180 days","It starts over at one year"],"h1":"Time without driving privileges is not practice time.","h2":"In Kentucky, a teen gets no credit toward the 180-day permit period while suspended under the No Pass/No Drive law.","p":"Right. Suspended days do not count toward the 180 days."},"es":{"q":"En Kentucky, el permiso de un joven se suspende por la ley No Pass/No Drive. ¿Qué pasa con el periodo de 180 días del permiso?","o":["Sigue contando normal","Se reduce a la mitad","Los días de suspensión no cuentan para los 180 días","Vuelve a empezar y dura un año"],"h1":"El tiempo sin privilegio de manejar no cuenta como práctica.","h2":"En Kentucky, el joven no recibe crédito para el periodo de 180 días del permiso mientras está suspendido por la ley No Pass/No Drive.","p":"Correcto. Los días de suspensión no cuentan para los 180 días."},"ref":{"doc":"KY","page":5}},{"id":"ky-073","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, you want to use a rental car for your road test. What is required?","o":["Your name must be on the rental contract as a driver","The rental company must send an employee","Rental cars are never allowed","A parent must sign the rental contract only"],"h1":"The examiner checks who is allowed to drive that car.","h2":"In Kentucky, a rental car may be used for the road test only if the applicant's name is on the rental contract as a driver.","p":"Right. Your name must be on the rental contract."},"es":{"q":"En Kentucky, quiere usar un auto rentado para su examen práctico. ¿Qué se requiere?","o":["Su nombre debe estar en el contrato de renta como conductor","La compañía de renta debe enviar a un empleado","Nunca se permiten autos rentados","Solo que un padre firme el contrato de renta"],"h1":"El examinador revisa quién está autorizado a manejar ese auto.","h2":"En Kentucky, se puede usar un auto rentado para el examen práctico solo si el nombre del solicitante aparece en el contrato de renta como conductor.","p":"Correcto. Su nombre debe estar en el contrato de renta."},"ref":{"doc":"KY","page":6}},{"id":"ky-074","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, which of these is accepted as proof of insurance for the road test car?","o":["A written binder from an insurance agent saying insurance is in force","A photo of a friend's insurance card","A receipt for gas","A verbal promise from the owner"],"h1":"It must come from the insurance company or an agent.","h2":"In Kentucky, proof of insurance for the road test can be an insurance card, a current policy, or a written binder from an agent saying insurance is in force.","p":"Right. A written binder from an agent is accepted."},"es":{"q":"En Kentucky, ¿cuál de estos se acepta como prueba de seguro del auto para el examen práctico?","o":["Un documento provisional (binder) por escrito de un agente que diga que el seguro está vigente","Una foto de la tarjeta de seguro de un amigo","Un recibo de gasolina","Una promesa verbal del dueño"],"h1":"Debe venir de la compañía de seguros o de un agente.","h2":"En Kentucky, la prueba de seguro para el examen práctico puede ser la tarjeta de seguro, la póliza vigente o un documento provisional por escrito de un agente que diga que el seguro está vigente.","p":"Correcto. Se acepta el documento provisional por escrito de un agente."},"ref":{"doc":"KY","page":6}},{"id":"ky-075","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a permit holder drives alone to the road test site. What happens?","o":["Nothing, if they arrive on time","They get extra points on the test","It is against the law, and the test will be rescheduled","They must pay a small fee and test anyway"],"h1":"A permit holder always needs a licensed adult beside them.","h2":"In Kentucky, it is unlawful for a permit holder to drive to the road test without a licensed driver 21 or older beside them, and the test will be rescheduled.","p":"Right. Driving there alone is illegal and the test is rescheduled."},"es":{"q":"En Kentucky, alguien con permiso maneja solo hasta el lugar del examen práctico. ¿Qué pasa?","o":["Nada, si llega a tiempo","Recibe puntos extra en el examen","Es contra la ley y el examen se reprograma","Paga una pequeña tarifa y presenta el examen igual"],"h1":"Quien tiene permiso siempre necesita a un adulto con licencia al lado.","h2":"En Kentucky, es ilegal que alguien con permiso maneje hasta el examen práctico sin un conductor con licencia de 21 años o más a su lado, y el examen se reprograma.","p":"Correcto. Llegar manejando solo es ilegal y el examen se reprograma."},"ref":{"doc":"KY","page":6}},{"id":"ky-076","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, a teen passes the road test. What does the examiner do to the permit?","o":["Punches a hole in it","Takes it away and gives nothing until the card arrives","Writes the test score on the back","Places an Intermediate License sticker on it"],"h1":"The permit itself is updated on the spot.","h2":"In Kentucky, after a teen passes the road test, the State Police examiner places an Intermediate License sticker on the permit.","p":"Right. The examiner adds an Intermediate License sticker."},"es":{"q":"En Kentucky, un joven aprueba el examen práctico. ¿Qué hace el examinador con el permiso?","o":["Le hace un agujero","Se lo quita y no le da nada hasta que llegue la tarjeta","Escribe la calificación atrás","Le pone una calcomanía de licencia intermedia (Intermediate License)"],"h1":"El mismo permiso se actualiza en ese momento.","h2":"En Kentucky, cuando un joven aprueba el examen práctico, el examinador de la Policía Estatal le pone una calcomanía de licencia intermedia al permiso.","p":"Correcto. El examinador agrega una calcomanía de licencia intermedia."},"ref":{"doc":"KY","page":6}},{"id":"ky-077","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, what two things must a teen finish before moving from the intermediate license to a full license?","o":["Hold the intermediate license for 180 days and complete a driver education course","Turn 21 and pass a new written test","Drive 100 hours and pass a new road test","Hold the license for 30 days and pay a fee"],"h1":"One is time; the other is a course.","h2":"In Kentucky, a teen must hold the intermediate license for 180 days and complete a required driver education course before getting a full license.","p":"Right. 180 days on the intermediate license plus driver education."},"es":{"q":"En Kentucky, ¿qué dos cosas debe terminar un joven antes de pasar de la licencia intermedia a la licencia completa?","o":["Tener la licencia intermedia por 180 días y terminar un curso de educación vial","Cumplir 21 años y aprobar otro examen escrito","Manejar 100 horas y aprobar otro examen práctico","Tener la licencia por 30 días y pagar una tarifa"],"h1":"Una es tiempo y la otra es un curso.","h2":"En Kentucky, el joven debe tener la licencia intermedia por 180 días y terminar un curso de educación vial obligatorio antes de recibir la licencia completa.","p":"Correcto. 180 días con licencia intermedia y educación vial."},"ref":{"doc":"KY","page":6}},{"id":"ky-078","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, a teen with an intermediate license gets a moving violation. What happens?","o":["Nothing changes","At least 180 more days are added before the teen can apply for a full license","The teen must retake the written test","The teen goes back to a learner's permit for one week"],"h1":"The waiting time for the next stage gets longer.","h2":"In Kentucky, a violation on the intermediate license adds at least 180 days from the date of the violation before the teen can apply for a full license.","p":"Right. A violation adds at least 180 days."},"es":{"q":"En Kentucky, un joven con licencia intermedia comete una infracción de tránsito en movimiento. ¿Qué pasa?","o":["No cambia nada","Se agregan al menos 180 días más antes de que pueda pedir la licencia completa","Debe repetir el examen escrito","Vuelve al permiso de aprendizaje por una semana"],"h1":"El tiempo de espera para la siguiente etapa se alarga.","h2":"En Kentucky, una infracción con licencia intermedia agrega al menos 180 días desde la fecha de la infracción antes de que el joven pueda pedir la licencia completa.","p":"Correcto. Una infracción agrega al menos 180 días."},"ref":{"doc":"KY","page":7}},{"id":"ky-079","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, by when must a driver whose permit was issued under 18 enroll in an approved driver training program?","o":["Before the first road test","Within 30 days of getting the permit","Before their 18th birthday","Before their 21st birthday"],"h1":"The deadline is tied to becoming an adult.","h2":"In Kentucky, a driver whose permit was issued under age 18 must enroll in an approved driver training program before turning 18.","p":"Right. Enroll before the 18th birthday."},"es":{"q":"En Kentucky, ¿para cuándo debe inscribirse en un programa aprobado de capacitación vial quien recibió su permiso antes de los 18 años?","o":["Antes de su primer examen práctico","Dentro de 30 días de recibir el permiso","Antes de cumplir 18 años","Antes de cumplir 21 años"],"h1":"La fecha límite tiene que ver con llegar a la mayoría de edad.","h2":"En Kentucky, quien recibió su permiso antes de los 18 años debe inscribirse en un programa aprobado de capacitación vial antes de cumplir 18.","p":"Correcto. Hay que inscribirse antes de cumplir 18."},"ref":{"doc":"KY","page":7}},{"id":"ky-080","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how much does the classroom version of the state's teen driver education course cost?","o":["$11","$25","$50","It is free"],"h1":"The online version has a small fee, but the classroom one does not.","h2":"In Kentucky, the classroom version of the state driver education course is free for Kentucky drivers; the online version costs $12.50.","p":"Right. The classroom version is free."},"es":{"q":"En Kentucky, ¿cuánto cuesta la versión en salón de clases del curso estatal de educación vial para jóvenes?","o":["$11","$25","$50","Es gratis"],"h1":"La versión en línea cuesta un poco, pero la del salón no.","h2":"En Kentucky, la versión en salón de clases del curso estatal de educación vial es gratis para los conductores de Kentucky; la versión en línea cuesta $12.50.","p":"Correcto. La versión en salón es gratis."},"ref":{"doc":"KY","page":7}},{"id":"ky-081","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, how recent must your proof of Kentucky residency be when you apply for a permit?","o":["Dated within the last five years","Any date is fine","Dated within the last 30 days","Dated less than one year ago"],"h1":"Think of a recent bill or bank statement from this year.","h2":"In Kentucky, a proof of residency must be dated less than one year before you apply.","p":"Right. Less than one year old."},"es":{"q":"En Kentucky, ¿qué tan reciente debe ser su prueba de residencia en Kentucky cuando pide un permiso?","o":["Con fecha de los últimos cinco años","Cualquier fecha sirve","Con fecha de los últimos 30 días","Con fecha de hace menos de un año"],"h1":"Piense en una factura o un estado de cuenta reciente de este año.","h2":"En Kentucky, la prueba de residencia debe tener fecha de menos de un año antes de la solicitud.","p":"Correcto. De menos de un año."},"ref":{"doc":"KY","page":8}},{"id":"ky-082","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how many proofs of residency do you need for a REAL ID?","o":["Two","One","Three","None"],"h1":"A standard license needs one; a REAL ID needs more.","h2":"In Kentucky, a REAL ID requires two proofs of residency; a standard license requires one.","p":"Right. Two proofs of residency for a REAL ID."},"es":{"q":"En Kentucky, ¿cuántas pruebas de residencia necesita para una REAL ID?","o":["Dos","Una","Tres","Ninguna"],"h1":"Para la licencia normal se necesita una; para la REAL ID, más.","h2":"En Kentucky, la REAL ID requiere dos pruebas de residencia; la licencia normal requiere una.","p":"Correcto. Dos pruebas de residencia para la REAL ID."},"ref":{"doc":"KY","page":8}},{"id":"ky-083","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, your legal name changed. What must you do before applying for your driver's license?","o":["Nothing, the state updates it","Update your name on your Social Security card","Get a letter from your employer","Change your name on your car title"],"h1":"The federal record must match first.","h2":"In Kentucky, your name must be updated on your Social Security card before you apply for a driver's license.","p":"Right. Update your Social Security card first."},"es":{"q":"En Kentucky, su nombre legal cambió. ¿Qué debe hacer antes de pedir su licencia de conducir?","o":["Nada, el estado lo actualiza","Actualizar su nombre en su tarjeta de Seguro Social","Pedir una carta a su empleador","Cambiar su nombre en el título del auto"],"h1":"Primero debe coincidir el registro federal.","h2":"En Kentucky, su nombre debe estar actualizado en su tarjeta de Seguro Social antes de pedir la licencia de conducir.","p":"Correcto. Primero actualice su tarjeta de Seguro Social."},"ref":{"doc":"KY","page":8}},{"id":"ky-084","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, a permit expired and was not renewed within one year after the expiration date. What must the holder do?","o":["Pay a late fee only","Take only the road test","Retake the written and vision tests","Wait until age 25"],"h1":"After a long gap, you must show again that you know the rules and can see well.","h2":"In Kentucky, if a permit is not renewed within one year of its expiration date, the written and vision tests must be taken again.","p":"Right. Retake the written and vision tests."},"es":{"q":"En Kentucky, un permiso venció y no se renovó dentro de un año después de vencer. ¿Qué debe hacer su dueño?","o":["Solo pagar un recargo","Tomar solo el examen práctico","Repetir los exámenes escrito y de la vista","Esperar hasta los 25 años"],"h1":"Después de mucho tiempo, debe demostrar otra vez que conoce las reglas y ve bien.","h2":"En Kentucky, si un permiso no se renueva dentro de un año de su vencimiento, hay que repetir los exámenes escrito y de la vista.","p":"Correcto. Debe repetir los exámenes escrito y de la vista."},"ref":{"doc":"KY","page":9}},{"id":"ky-085","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, you fail the 20/40 eye screening and a vision specialist examines you. What vision then lets you test for a permit?","o":["20/100 or better","20/200 or better","20/80 or better","20/60 or better"],"h1":"It is a little lower than the first screening standard.","h2":"In Kentucky, after a referral to a vision specialist, an applicant whose vision is 20/60 or better may test for a permit or license.","p":"Right. 20/60 or better after the specialist's exam."},"es":{"q":"En Kentucky, usted no pasa la prueba de la vista de 20/40 y un especialista lo examina. ¿Qué vista le permite entonces presentar el examen del permiso?","o":["20/100 o mejor","20/200 o mejor","20/80 o mejor","20/60 o mejor"],"h1":"Es un poco más bajo que el estándar de la primera prueba.","h2":"En Kentucky, después de ver a un especialista de la vista, el solicitante con vista de 20/60 o mejor puede presentar el examen para el permiso o la licencia.","p":"Correcto. 20/60 o mejor después del examen del especialista."},"ref":{"doc":"KY","page":10}},{"id":"ky-086","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, you need glasses to pass the vision test. What happens to your license?","o":["It carries a restriction that you must wear corrective lenses when driving","Nothing; glasses are optional","You may drive only in daylight","You must retest every year"],"h1":"Your license will show a condition you must follow.","h2":"In Kentucky, if you need corrective lenses to meet the vision standard, your license is restricted so you must wear them when driving.","p":"Right. You must wear your corrective lenses to drive."},"es":{"q":"En Kentucky, usted necesita lentes para pasar la prueba de la vista. ¿Qué pasa con su licencia?","o":["Tendrá una restricción: debe usar lentes correctivos al manejar","Nada; los lentes son opcionales","Solo podrá manejar de día","Debe repetir el examen cada año"],"h1":"Su licencia mostrará una condición que debe cumplir.","h2":"En Kentucky, si necesita lentes correctivos para cumplir el estándar de la vista, su licencia tendrá una restricción y deberá usarlos al manejar.","p":"Correcto. Debe usar sus lentes correctivos para manejar."},"ref":{"doc":"KY","page":10}},{"id":"ky-087","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, your written test is given to you orally. Which part must you answer from your own knowledge?","o":["The alcohol questions","The road signs part","The insurance questions","The first ten questions"],"h1":"Recognizing what you see on the road cannot be explained to you.","h2":"In Kentucky, when the written test is given orally, the road signs part must be answered from the applicant's own knowledge and understanding.","p":"Right. The signs part is answered on your own."},"es":{"q":"En Kentucky, le hacen el examen escrito en forma oral. ¿Qué parte debe contestar con su propio conocimiento?","o":["Las preguntas sobre alcohol","La parte de las señales de tránsito","Las preguntas sobre seguros","Las primeras diez preguntas"],"h1":"Reconocer lo que ve en la vía no se lo pueden explicar.","h2":"En Kentucky, cuando el examen escrito se hace en forma oral, la parte de las señales debe contestarse con el propio conocimiento del solicitante.","p":"Correcto. La parte de señales la contesta usted solo."},"ref":{"doc":"KY","page":11}},{"id":"ky-088","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, do you need a special appointment to hear the written test read aloud on the testing tablet?","o":["Yes, always","Yes, two weeks ahead","No, the audio feature on the tablets needs no special appointment","Audio tests are not offered"],"h1":"Every testing office has tablets that can read the test aloud.","h2":"In Kentucky, testing offices have tablets that present the test aloud in English and several other languages, and you do not need a special appointment to use them.","p":"Right. No special appointment is needed for the audio test."},"es":{"q":"En Kentucky, ¿necesita una cita especial para escuchar en voz alta el examen escrito en la tableta del examen?","o":["Sí, siempre","Sí, con dos semanas de anticipación","No, la función de audio de las tabletas no necesita cita especial","No se ofrecen exámenes en audio"],"h1":"Todas las oficinas tienen tabletas que pueden leer el examen en voz alta.","h2":"En Kentucky, las oficinas de examen tienen tabletas que leen el examen en voz alta en inglés y en varios otros idiomas, y no necesita cita especial para usarlas.","p":"Correcto. No se necesita cita especial para el examen en audio."},"ref":{"doc":"KY","page":11}},{"id":"ky-089","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, can an interpreter ride in the car during your road test?","o":["Yes, in the back seat","Yes, if the examiner agrees","Only for applicants under 18","No, but an interpreter may help before and after the test"],"h1":"Only the examiner rides with you.","h2":"In Kentucky, interpreters are not allowed in the vehicle during the road test, but one may help before and after the test.","p":"Right. No interpreter in the car, only before and after."},"es":{"q":"En Kentucky, ¿puede ir un intérprete en el auto durante su examen práctico?","o":["Sí, en el asiento de atrás","Sí, si el examinador está de acuerdo","Solo para menores de 18 años","No, pero un intérprete puede ayudar antes y después del examen"],"h1":"Solo el examinador va con usted.","h2":"En Kentucky, los intérpretes no pueden ir en el vehículo durante el examen práctico, pero uno puede ayudar antes y después del examen.","p":"Correcto. No hay intérprete en el auto, solo antes y después."},"ref":{"doc":"KY","page":11}},{"id":"ky-090","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, during the road test you fail to follow the examiner's instructions. How many times leads to disqualification?","o":["Once","Two times","Four times","Five times"],"h1":"It is a small number, more than one.","h2":"In Kentucky, failing to follow the examiner's instructions two times during the road test leads to disqualification.","p":"Right. Two times means disqualification."},"es":{"q":"En Kentucky, durante el examen práctico usted no sigue las instrucciones del examinador. ¿Cuántas veces causan la descalificación?","o":["Una vez","Dos veces","Cuatro veces","Cinco veces"],"h1":"Es un número pequeño, más de uno.","h2":"En Kentucky, no seguir las instrucciones del examinador dos veces durante el examen práctico causa la descalificación.","p":"Correcto. Dos veces causan la descalificación."},"ref":{"doc":"KY","page":13}},{"id":"ky-091","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, you move here with an out-of-state license that expired six months ago. What testing is required?","o":["Written, vision, and road tests","Only the road test","No testing, as long as it expired less than one year ago","Only the vision test"],"h1":"A license that is valid or only recently expired transfers easily.","h2":"In Kentucky, an out-of-state license that is valid or expired less than one year can be transferred without testing.","p":"Right. No testing if it expired less than one year ago."},"es":{"q":"En Kentucky, usted se muda aquí con una licencia de otro estado que venció hace seis meses. ¿Qué exámenes se requieren?","o":["Escrito, de la vista y práctico","Solo el práctico","Ninguno, siempre que haya vencido hace menos de un año","Solo el de la vista"],"h1":"Una licencia vigente o vencida hace poco se transfiere fácilmente.","h2":"En Kentucky, una licencia de otro estado que está vigente o venció hace menos de un año se puede transferir sin exámenes.","p":"Correcto. Sin exámenes si venció hace menos de un año."},"ref":{"doc":"KY","page":13}},{"id":"ky-092","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, your out-of-state license expired more than one year ago. What must you do to get a Kentucky license?","o":["Nothing extra; just pay the fee","Take only the road test","Wait one more year","Get a full driver history record or clearance letter and take the written and eye exams"],"h1":"You must show your record and pass some tests again.","h2":"In Kentucky, if your out-of-state license expired more than one year ago, you need a certified driver history record or clearance letter and must pass the written and eye exams.","p":"Right. Driver record plus written and eye exams."},"es":{"q":"En Kentucky, su licencia de otro estado venció hace más de un año. ¿Qué debe hacer para sacar la licencia de Kentucky?","o":["Nada más; solo pagar la tarifa","Tomar solo el examen práctico","Esperar un año más","Conseguir su historial de manejo completo o una carta de autorización y tomar los exámenes escrito y de la vista"],"h1":"Debe mostrar su historial y aprobar otra vez algunos exámenes.","h2":"En Kentucky, si su licencia de otro estado venció hace más de un año, necesita un historial de manejo certificado o una carta de autorización, y debe aprobar los exámenes escrito y de la vista.","p":"Correcto. Historial de manejo y exámenes escrito y de la vista."},"ref":{"doc":"KY","page":13}},{"id":"ky-093","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, a teen moves here with a learner's permit from another state. What must happen before they can apply for a Kentucky license?","o":["They must transfer it and be issued a Kentucky permit first","They can apply for a full license right away","They must wait until age 18","They must drive 60 more hours with the old permit"],"h1":"You move up through Kentucky's stages from the permit level.","h2":"In Kentucky, out-of-state permit holders must transfer their permit and be issued a Kentucky permit before applying for a Kentucky license.","p":"Right. Transfer to a Kentucky permit first."},"es":{"q":"En Kentucky, un joven se muda aquí con un permiso de aprendizaje de otro estado. ¿Qué debe pasar antes de que pueda pedir una licencia de Kentucky?","o":["Debe transferirlo y recibir primero un permiso de Kentucky","Puede pedir enseguida la licencia completa","Debe esperar hasta los 18 años","Debe manejar 60 horas más con el permiso viejo"],"h1":"Se avanza por las etapas de Kentucky desde el nivel de permiso.","h2":"En Kentucky, quien trae un permiso de otro estado debe transferirlo y recibir un permiso de Kentucky antes de pedir una licencia de Kentucky.","p":"Correcto. Primero se transfiere a un permiso de Kentucky."},"ref":{"doc":"KY","page":14}},{"id":"ky-094","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, a U.S. citizen from Ohio attends college in Kentucky. When may they keep driving on their valid Ohio license?","o":["When they are enrolled in a Kentucky school and carry the school's student ID","Never; they must switch within 30 days","Only during summer break","Only if they live off campus"],"h1":"They need to show they are a student here.","h2":"In Kentucky, a U.S. citizen enrolled full- or part-time at a Kentucky college may drive on a valid out-of-state license while carrying their student ID card.","p":"Right. Enrolled and carrying the student ID."},"es":{"q":"En Kentucky, un ciudadano estadounidense de Ohio estudia en una universidad de Kentucky. ¿Cuándo puede seguir manejando con su licencia válida de Ohio?","o":["Cuando está inscrito en una escuela de Kentucky y lleva su credencial de estudiante","Nunca; debe cambiarla en 30 días","Solo en vacaciones de verano","Solo si vive fuera del campus"],"h1":"Tiene que demostrar que es estudiante aquí.","h2":"En Kentucky, un ciudadano estadounidense inscrito tiempo completo o parcial en una universidad de Kentucky puede manejar con su licencia válida de otro estado si lleva su credencial de estudiante.","p":"Correcto. Inscrito y con su credencial de estudiante."},"ref":{"doc":"KY","page":14}},{"id":"ky-095","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how long may a visitor drive on a valid foreign license with an International Driving Permit, if their country is part of license reciprocity?","o":["30 days","90 days","Up to one year from the date of entry into the U.S.","Up to five years"],"h1":"It is counted from when they entered the country.","h2":"In Kentucky, a non-U.S. citizen from a reciprocity country may drive on a valid foreign license and International Driving Permit for up to one year from entering the U.S.","p":"Right. Up to one year from entry."},"es":{"q":"En Kentucky, ¿por cuánto tiempo puede manejar un visitante con licencia extranjera válida y Permiso Internacional de Conducir, si su país tiene reciprocidad de licencias?","o":["30 días","90 días","Hasta un año desde la fecha de entrada a EE. UU.","Hasta cinco años"],"h1":"Se cuenta desde que entró al país.","h2":"En Kentucky, un extranjero de un país con reciprocidad puede manejar con su licencia extranjera válida y su Permiso Internacional de Conducir hasta un año desde que entró a EE. UU.","p":"Correcto. Hasta un año desde la entrada."},"ref":{"doc":"KY","page":14}},{"id":"ky-096","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, when does the license of a driver age 21 or older expire?","o":["On the driver's birthday","31 days after the driver's birthday","At the end of the calendar year","Six months after the birthday"],"h1":"It is about a month after the birthday.","h2":"In Kentucky, a license for a driver 21 or older expires 31 days after the driver's birthday.","p":"Right. 31 days after the birthday."},"es":{"q":"En Kentucky, ¿cuándo vence la licencia de un conductor de 21 años o más?","o":["El día de su cumpleaños","31 días después de su cumpleaños","Al final del año","Seis meses después del cumpleaños"],"h1":"Es como un mes después del cumpleaños.","h2":"En Kentucky, la licencia de un conductor de 21 años o más vence 31 días después de su cumpleaños.","p":"Correcto. 31 días después del cumpleaños."},"ref":{"doc":"KY","page":16}},{"id":"ky-097","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how early can a driver 21 or older renew their license?","o":["Up to one month before it expires","Up to two years before it expires","Up to six months before it expires","Only on the expiration date"],"h1":"It is half a year.","h2":"In Kentucky, a driver 21 or older may renew up to six months before the license expires.","p":"Right. Up to six months early."},"es":{"q":"En Kentucky, ¿con cuánta anticipación puede renovar su licencia un conductor de 21 años o más?","o":["Hasta un mes antes de que venza","Hasta dos años antes de que venza","Hasta seis meses antes de que venza","Solo el día que vence"],"h1":"Es medio año.","h2":"En Kentucky, un conductor de 21 años o más puede renovar hasta seis meses antes de que venza la licencia.","p":"Correcto. Hasta seis meses antes."},"ref":{"doc":"KY","page":16}},{"id":"ky-098","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, your license has been expired for six years. What must you do?","o":["Renew online with no tests","Pay a late fee only","Take only the vision test","Start over as a new driver"],"h1":"After a very long gap, you go back to the beginning.","h2":"In Kentucky, a driver whose license has been expired more than five years must start over as a new driver; under five years, no testing is needed.","p":"Right. More than five years means starting over."},"es":{"q":"En Kentucky, su licencia lleva seis años vencida. ¿Qué debe hacer?","o":["Renovarla en línea sin exámenes","Solo pagar un recargo","Tomar solo el examen de la vista","Empezar de nuevo como conductor nuevo"],"h1":"Después de tanto tiempo, se vuelve al principio.","h2":"En Kentucky, quien tiene la licencia vencida por más de cinco años debe empezar de nuevo como conductor nuevo; con menos de cinco años, no necesita exámenes.","p":"Correcto. Más de cinco años significa empezar de nuevo."},"ref":{"doc":"KY","page":16}},{"id":"ky-099","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how long is an operator's license valid?","o":["Four or eight years","One year","Two or three years","Ten years"],"h1":"The longer option is only for new standard licenses and REAL IDs.","h2":"In Kentucky, an operator's license is valid for four or eight years; eight-year credentials are for new standard licenses and REAL IDs.","p":"Right. Four or eight years."},"es":{"q":"En Kentucky, ¿por cuánto tiempo es válida una licencia de conductor?","o":["Cuatro u ocho años","Un año","Dos o tres años","Diez años"],"h1":"La opción más larga es solo para licencias normales nuevas y REAL ID.","h2":"En Kentucky, la licencia de conductor es válida por cuatro u ocho años; la de ocho años es para licencias normales nuevas y REAL ID.","p":"Correcto. Cuatro u ocho años."},"ref":{"doc":"KY","page":16}},{"id":"ky-100","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how many reckless driving convictions within 12 months can lead to a license suspension?","o":["One","Two","Three","Six"],"h1":"It is a small number, more than two.","h2":"In Kentucky, three reckless driving convictions within 12 months can lead to the suspension or revocation of your license.","p":"Right. Three in 12 months."},"es":{"q":"En Kentucky, ¿cuántas condenas por manejo imprudente en 12 meses pueden causar la suspensión de la licencia?","o":["Una","Dos","Tres","Seis"],"h1":"Es un número pequeño, más de dos.","h2":"En Kentucky, tres condenas por manejo imprudente en 12 meses pueden causar la suspensión o revocación de la licencia.","p":"Correcto. Tres en 12 meses."},"ref":{"doc":"KY","page":16}},{"id":"ky-101","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, which of these can get your driver's license suspended, even though it has nothing to do with driving?","o":["Missing a doctor's appointment","Owing a library fine","Changing jobs","Failing to pay child support"],"h1":"It is a family court obligation.","h2":"In Kentucky, failing to pay child support is one of the reasons your driver's license may be suspended.","p":"Right. Unpaid child support can lead to a suspension."},"es":{"q":"En Kentucky, ¿cuál de estos puede causar la suspensión de su licencia aunque no tiene que ver con manejar?","o":["Faltar a una cita médica","Deber una multa de la biblioteca","Cambiar de trabajo","No pagar la manutención de los hijos"],"h1":"Es una obligación de un tribunal de familia.","h2":"En Kentucky, no pagar la manutención de los hijos es una de las razones por las que pueden suspender su licencia.","p":"Correcto. No pagar la manutención puede causar una suspensión."},"ref":{"doc":"KY","page":16}},{"id":"ky-102","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, points expire after two years. How long does the conviction itself stay on your driving record?","o":["Two years","Five years","Ten years","For life"],"h1":"It stays longer than the points do.","h2":"In Kentucky, points expire two years after the conviction, but the conviction stays on your driving record for five years.","p":"Right. The conviction stays five years."},"es":{"q":"En Kentucky, los puntos vencen a los dos años. ¿Cuánto tiempo queda la condena en su historial de manejo?","o":["Dos años","Cinco años","Diez años","Toda la vida"],"h1":"Queda más tiempo que los puntos.","h2":"En Kentucky, los puntos vencen dos años después de la condena, pero la condena queda en su historial de manejo por cinco años.","p":"Correcto. La condena queda cinco años."},"ref":{"doc":"KY","page":17}},{"id":"ky-103","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, an adult reaches 12 points for the first time and skips the hearing. How long is the suspension?","o":["One month","Two years","Six months","Five years"],"h1":"It is half a year for a first time.","h2":"In Kentucky, failing to appear at the hearing for a first 12-point accumulation results in a six-month suspension.","p":"Right. Six months for the first time."},"es":{"q":"En Kentucky, un adulto llega a 12 puntos por primera vez y no va a la audiencia. ¿Cuánto dura la suspensión?","o":["Un mes","Dos años","Seis meses","Cinco años"],"h1":"Es medio año la primera vez.","h2":"En Kentucky, no presentarse a la audiencia por llegar a 12 puntos por primera vez causa una suspensión de seis meses.","p":"Correcto. Seis meses la primera vez."},"ref":{"doc":"KY","page":17}},{"id":"ky-104","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, a driver reaches 12 points for the second time and skips the hearing. How long is the suspension?","o":["Three months","Six months","Five years","One year"],"h1":"It doubles from the first time.","h2":"In Kentucky, failing to appear at the hearing for a second 12-point accumulation results in a one-year suspension.","p":"Right. One year for the second time."},"es":{"q":"En Kentucky, un conductor llega a 12 puntos por segunda vez y no va a la audiencia. ¿Cuánto dura la suspensión?","o":["Tres meses","Seis meses","Cinco años","Un año"],"h1":"Es el doble que la primera vez.","h2":"En Kentucky, no presentarse a la audiencia por llegar a 12 puntos por segunda vez causa una suspensión de un año.","p":"Correcto. Un año la segunda vez."},"ref":{"doc":"KY","page":17}},{"id":"ky-105","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, how often may a driver attend State Traffic School?","o":["Once every 12 months","Once every month","Twice a year","As often as they like"],"h1":"It is once a year at most.","h2":"In Kentucky, a driver can complete State Traffic School only once every 12 months.","p":"Right. Once every 12 months."},"es":{"q":"En Kentucky, ¿cada cuánto puede un conductor ir a la Escuela Estatal de Tránsito (State Traffic School)?","o":["Una vez cada 12 meses","Una vez al mes","Dos veces al año","Las veces que quiera"],"h1":"Es como máximo una vez al año.","h2":"En Kentucky, un conductor solo puede completar la Escuela Estatal de Tránsito una vez cada 12 meses.","p":"Correcto. Una vez cada 12 meses."},"ref":{"doc":"KY","page":18}},{"id":"ky-106","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, what must every person convicted of DUI complete before driving privileges can be reinstated?","o":["A new road test only","An assessment and an approved alcohol education or treatment program","A first aid class","Community service at a hospital"],"h1":"It starts with an assessment, then a program.","h2":"In Kentucky, every DUI offender must be assessed and must complete an approved alcohol education or treatment program before the license can be reinstated.","p":"Right. Assessment plus an approved education or treatment program."},"es":{"q":"En Kentucky, ¿qué debe completar toda persona condenada por DUI antes de que le devuelvan el privilegio de manejar?","o":["Solo un nuevo examen práctico","Una evaluación y un programa aprobado de educación o tratamiento sobre el alcohol","Una clase de primeros auxilios","Servicio comunitario en un hospital"],"h1":"Empieza con una evaluación y luego un programa.","h2":"En Kentucky, todo condenado por DUI debe ser evaluado y completar un programa aprobado de educación o tratamiento sobre el alcohol antes de que le devuelvan la licencia.","p":"Correcto. Evaluación y un programa aprobado."},"ref":{"doc":"KY","page":18}},{"id":"ky-107","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, where do you register a motor vehicle?","o":["At any State Police post","At the Department of Revenue in Frankfort","With the county clerk in the county where you live","At the dealership only"],"h1":"It is a county office.","h2":"In Kentucky, the owner must register a vehicle with the county clerk in the owner's county of residence.","p":"Right. With your county clerk."},"es":{"q":"En Kentucky, ¿dónde se registra un vehículo?","o":["En cualquier puesto de la Policía Estatal","En el Departamento de Ingresos en Frankfort","Con el secretario del condado (county clerk) donde usted vive","Solo en el concesionario"],"h1":"Es una oficina del condado.","h2":"En Kentucky, el dueño debe registrar el vehículo con el secretario del condado donde vive.","p":"Correcto. Con el secretario de su condado."},"ref":{"doc":"KY","page":19}},{"id":"ky-108","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, you buy a car or bring one in from another state. How soon must you apply to register it?","o":["Within 30 days","Within 60 days","Within one year","Within 15 days"],"h1":"It is about two weeks.","h2":"In Kentucky, a person who buys a vehicle or brings one in from another state must apply for registration within 15 days.","p":"Right. Within 15 days."},"es":{"q":"En Kentucky, usted compra un auto o trae uno de otro estado. ¿En cuánto tiempo debe pedir su registro?","o":["Dentro de 30 días","Dentro de 60 días","Dentro de un año","Dentro de 15 días"],"h1":"Son unas dos semanas.","h2":"En Kentucky, quien compra un vehículo o lo trae de otro estado debe pedir el registro dentro de 15 días.","p":"Correcto. Dentro de 15 días."},"ref":{"doc":"KY","page":19}},{"id":"ky-109","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, is there a grace period after your vehicle registration expires?","o":["No, you must renew on or before the expiration date","Yes, 30 days","Yes, 10 days","Yes, until your next birthday"],"h1":"The deadline is firm.","h2":"In Kentucky, there is no grace period for renewing your registration; renew on or before the date it expires.","p":"Right. No grace period."},"es":{"q":"En Kentucky, ¿hay un periodo de gracia después de que vence el registro de su vehículo?","o":["No, debe renovarlo en la fecha de vencimiento o antes","Sí, 30 días","Sí, 10 días","Sí, hasta su próximo cumpleaños"],"h1":"La fecha límite es firme.","h2":"En Kentucky, no hay periodo de gracia para renovar el registro; renuévelo en la fecha de vencimiento o antes.","p":"Correcto. No hay periodo de gracia."},"ref":{"doc":"KY","page":19}},{"id":"ky-110","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what is the minimum liability coverage for injuries to all people in one crash?","o":["$25,000","$30,000","$50,000","$100,000"],"h1":"It is twice the amount for one person.","h2":"In Kentucky, the minimum liability coverage is $50,000 for bodily injury to all persons in one accident.","p":"Right. $50,000 for all people in one crash."},"es":{"q":"En Kentucky, ¿cuál es la cobertura mínima de responsabilidad por lesiones a todas las personas en un choque?","o":["$25,000","$30,000","$50,000","$100,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"En Kentucky, la cobertura mínima de responsabilidad es de $50,000 por lesiones a todas las personas en un accidente.","p":"Correcto. $50,000 para todas las personas en un choque."},"ref":{"doc":"KY","page":19}},{"id":"ky-111","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, what is the minimum liability coverage for property damage in one crash?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"It matches the amount for one injured person.","h2":"In Kentucky, the minimum liability coverage for property damage in one accident is $25,000.","p":"Right. $25,000 for property damage."},"es":{"q":"En Kentucky, ¿cuál es la cobertura mínima de responsabilidad por daños a la propiedad en un choque?","o":["$5,000","$10,000","$15,000","$25,000"],"h1":"Es igual a la cantidad para una persona lesionada.","h2":"En Kentucky, la cobertura mínima de responsabilidad por daños a la propiedad en un accidente es de $25,000.","p":"Correcto. $25,000 por daños a la propiedad."},"ref":{"doc":"KY","page":19}},{"id":"ky-112","scope":"KY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Kentucky, which vehicle's policy does not have to include basic reparations benefits?","o":["A pickup truck","A motorcycle","A minivan","A sedan"],"h1":"It is the vehicle with two wheels.","h2":"In Kentucky, an insurance policy must include basic reparations benefits unless the insured vehicle is a motorcycle.","p":"Right. Motorcycles are the exception."},"es":{"q":"En Kentucky, ¿la póliza de qué vehículo no tiene que incluir beneficios básicos de reparación (basic reparations benefits)?","o":["Una camioneta pickup","Una motocicleta","Una minivan","Un sedán"],"h1":"Es el vehículo de dos ruedas.","h2":"En Kentucky, la póliza de seguro debe incluir beneficios básicos de reparación, salvo que el vehículo asegurado sea una motocicleta.","p":"Correcto. Las motocicletas son la excepción."},"ref":{"doc":"KY","page":19}},{"id":"ky-113","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, in what form can you carry proof of insurance in your car?","o":["Only an original paper policy","Only a sticker on the windshield","A paper insurance card or one shown on a phone or other device","No proof is needed in the car"],"h1":"Both old and new ways are allowed.","h2":"In Kentucky, written proof of insurance can be a paper insurance card or a card shown on a portable electronic device.","p":"Right. Paper or electronic card."},"es":{"q":"En Kentucky, ¿en qué forma puede llevar la prueba de seguro en su auto?","o":["Solo la póliza original en papel","Solo una calcomanía en el parabrisas","Una tarjeta de seguro en papel o mostrada en un teléfono u otro aparato","No se necesita prueba en el auto"],"h1":"Se permiten la forma antigua y la nueva.","h2":"En Kentucky, la prueba escrita de seguro puede ser una tarjeta en papel o una tarjeta mostrada en un aparato electrónico portátil.","p":"Correcto. Tarjeta en papel o electrónica."},"ref":{"doc":"KY","page":19}},{"id":"ky-114","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, an owner stops paying for insurance on a registered car. What happens to the registration?","o":["It is revoked","It stays valid until the next renewal","It moves to the next driver in the family","It is kept but marked inactive"],"h1":"The state cancels the car's legal right to be on the road.","h2":"In Kentucky, an owner who fails to keep insurance on a registered vehicle will have the vehicle's registration revoked.","p":"Right. The registration is revoked."},"es":{"q":"En Kentucky, un dueño deja de pagar el seguro de un auto registrado. ¿Qué pasa con el registro?","o":["Se revoca","Sigue válido hasta la próxima renovación","Pasa al siguiente conductor de la familia","Se conserva pero marcado como inactivo"],"h1":"El estado cancela el derecho legal del auto a estar en la vía.","h2":"En Kentucky, al dueño que no mantiene el seguro de un vehículo registrado le revocan el registro del vehículo.","p":"Correcto. Le revocan el registro."},"ref":{"doc":"KY","page":19}},{"id":"ky-115","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"On a long trip, how often does the Kentucky manual suggest you stop for a break?","o":["Every 300 miles","Only when you need fuel","Every 6 hours","About every 100 miles or 2 hours"],"h1":"Think of a short drive time, a couple of hours.","h2":"The Kentucky manual says to plan to stop about every 100 miles or every 2 hours on long trips.","p":"Right. About every 100 miles or 2 hours."},"es":{"q":"En un viaje largo, ¿cada cuánto sugiere el manual de Kentucky parar a descansar?","o":["Cada 300 millas","Solo cuando necesita gasolina","Cada 6 horas","Más o menos cada 100 millas o cada 2 horas"],"h1":"Piense en poco tiempo de manejo, un par de horas.","h2":"El manual de Kentucky dice que en viajes largos planee parar más o menos cada 100 millas o cada 2 horas.","p":"Correcto. Más o menos cada 100 millas o 2 horas."},"ref":{"doc":"KY","page":22}},{"id":"ky-116","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, you start to feel tired while driving. What does the manual suggest?","o":["Pull off at the next exit or rest area for a 15- to 20-minute nap","Open the window and keep going","Turn up the radio","Drive faster to get home sooner"],"h1":"A short rest beats trying to push through.","h2":"The Kentucky manual says that if you feel tired, stop at the next exit or rest area and take a 15- to 20-minute nap, or find a place to sleep.","p":"Right. Pull off and take a short nap."},"es":{"q":"En Kentucky, empieza a sentir sueño mientras maneja. ¿Qué sugiere el manual?","o":["Salir en la próxima salida o área de descanso y dormir de 15 a 20 minutos","Abrir la ventana y seguir","Subir el volumen de la radio","Manejar más rápido para llegar antes"],"h1":"Un descanso corto es mejor que aguantar.","h2":"El manual de Kentucky dice que si siente sueño, pare en la próxima salida o área de descanso y duerma de 15 a 20 minutos, o busque dónde dormir.","p":"Correcto. Pare y duerma un rato."},"ref":{"doc":"KY","page":22}},{"id":"ky-117","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"The Kentucky manual says reading or sending a text takes your eyes off the road for about how long?","o":["1 second","4.6 seconds","15 seconds","30 seconds"],"h1":"At 55 mph that is the length of a football field.","h2":"The Kentucky manual says a text takes your eyes off the road for about 4.6 seconds, like driving a football field's length at 55 mph.","p":"Right. About 4.6 seconds."},"es":{"q":"El manual de Kentucky dice que leer o enviar un mensaje de texto quita la vista de la vía por más o menos cuánto tiempo?","o":["1 segundo","4.6 segundos","15 segundos","30 segundos"],"h1":"A 55 mph es el largo de una cancha de fútbol americano.","h2":"El manual de Kentucky dice que un mensaje de texto le quita la vista de la vía unos 4.6 segundos, como recorrer el largo de una cancha de fútbol americano a 55 mph.","p":"Correcto. Unos 4.6 segundos."},"ref":{"doc":"KY","page":23}},{"id":"ky-118","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, another driver starts a road rage incident with you. What should you do?","o":["Safely pull off in a well-lit public place and call the police","Follow them to get their plate","Stop in the lane and argue","Brake hard in front of them"],"h1":"Do not fight back; get to safety and get help.","h2":"In Kentucky, if you are in a road rage incident, do not retaliate; pull off safely in a well-lit public area and call the police.","p":"Right. Get to a well-lit public place and call police."},"es":{"q":"En Kentucky, otro conductor empieza un incidente de furia al volante con usted. ¿Qué debe hacer?","o":["Salir con cuidado a un lugar público e iluminado y llamar a la policía","Seguirlo para ver su placa","Parar en el carril y discutir","Frenar fuerte delante de él"],"h1":"No responda; póngase a salvo y pida ayuda.","h2":"En Kentucky, si está en un incidente de furia al volante, no responda; salga con cuidado a un lugar público e iluminado y llame a la policía.","p":"Correcto. Vaya a un lugar público iluminado y llame a la policía."},"ref":{"doc":"KY","page":24}},{"id":"ky-119","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, at what blood alcohol concentration is a driver 21 or older automatically breaking the DUI law?","o":["0.05 or above","0.08 or above","0.10 or above","0.15 or above"],"h1":"It is the same limit used in most states for adults.","h2":"In Kentucky, a driver 21 or older violates the DUI law with an alcohol concentration of 0.08 or above, and can be charged below that if impaired.","p":"Right. 0.08 or above."},"es":{"q":"En Kentucky, ¿con qué concentración de alcohol en la sangre un conductor de 21 años o más viola automáticamente la ley de DUI?","o":["0.05 o más","0.08 o más","0.10 o más","0.15 o más"],"h1":"Es el mismo límite que usan la mayoría de los estados para adultos.","h2":"En Kentucky, un conductor de 21 años o más viola la ley de DUI con una concentración de alcohol de 0.08 o más, y lo pueden acusar con menos si está afectado.","p":"Correcto. 0.08 o más."},"ref":{"doc":"KY","page":26}},{"id":"ky-120","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, a first alcohol DUI conviction within 10 years brings how much jail time?","o":["None at all","1 to 5 years","6 to 12 months","48 hours to 30 days"],"h1":"The minimum is two days.","h2":"In Kentucky, a first alcohol DUI conviction within 10 years brings 48 hours to 30 days in the county jail, plus a fine.","p":"Right. 48 hours to 30 days."},"es":{"q":"En Kentucky, una primera condena por DUI con alcohol en 10 años trae cuánta cárcel?","o":["Nada","1 a 5 años","6 a 12 meses","48 horas a 30 días"],"h1":"El mínimo son dos días.","h2":"En Kentucky, una primera condena por DUI con alcohol en 10 años trae de 48 horas a 30 días en la cárcel del condado, además de una multa.","p":"Correcto. 48 horas a 30 días."},"ref":{"doc":"KY","page":27}},{"id":"ky-121","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, under the implied consent law, what tests have you agreed to take by driving?","o":["Only a breath test","A lawfully requested test of your blood, breath, urine, or a combination","Only an eye test","Only a walking test"],"h1":"There are three kinds of body samples.","h2":"In Kentucky, by driving you have agreed to a lawfully requested test of your blood, breath, urine, or any combination of them.","p":"Right. Blood, breath, or urine tests."},"es":{"q":"En Kentucky, según la ley de consentimiento implícito, ¿a qué pruebas aceptó someterse al manejar?","o":["Solo a la prueba de aliento","A una prueba legal de sangre, aliento, orina o una combinación","Solo a una prueba de la vista","Solo a una prueba de caminar"],"h1":"Son tres tipos de muestras del cuerpo.","h2":"En Kentucky, al manejar usted acepta una prueba solicitada legalmente de sangre, aliento, orina o cualquier combinación de ellas.","p":"Correcto. Pruebas de sangre, aliento u orina."},"ref":{"doc":"KY","page":26}},{"id":"ky-122","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, you have a license from another state and are arrested for DUI here. Whose implied consent law applies?","o":["Your home state's law","Federal law only","Kentucky's law, where you were arrested","Neither, since your license is not from Kentucky"],"h1":"It is the place of the arrest that matters.","h2":"In Kentucky, implied consent law applies in the state where you are arrested, not the state that issued your license.","p":"Right. The law of the state where you are arrested applies."},"es":{"q":"En Kentucky, usted tiene licencia de otro estado y lo arrestan aquí por DUI. ¿Qué ley de consentimiento implícito se aplica?","o":["La ley de su estado","Solo la ley federal","La ley de Kentucky, donde lo arrestaron","Ninguna, porque su licencia no es de Kentucky"],"h1":"Lo que importa es el lugar del arresto.","h2":"En Kentucky, la ley de consentimiento implícito que se aplica es la del estado donde lo arrestan, no la del estado que dio su licencia.","p":"Correcto. Se aplica la ley del estado donde lo arrestan."},"ref":{"doc":"KY","page":26}},{"id":"ky-123","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, a driver refuses a breath test and is later convicted of a second DUI within 10 years. What happens to the mandatory jail time?","o":["It is cut in half","It stays the same","It is replaced by a fine","It is twice as long as if the driver had taken the test"],"h1":"Refusing makes the penalty heavier, not lighter.","h2":"In Kentucky, refusing the test and then being convicted of a second or later DUI within 10 years doubles the mandatory minimum jail sentence.","p":"Right. The minimum jail time doubles."},"es":{"q":"En Kentucky, un conductor se niega a la prueba de aliento y luego lo condenan por un segundo DUI en 10 años. ¿Qué pasa con la cárcel obligatoria?","o":["Se reduce a la mitad","Queda igual","Se cambia por una multa","Es el doble que si hubiera hecho la prueba"],"h1":"Negarse hace la pena más dura, no más leve.","h2":"En Kentucky, negarse a la prueba y luego ser condenado por un segundo DUI o más en 10 años duplica la sentencia mínima obligatoria de cárcel.","p":"Correcto. La cárcel mínima se duplica."},"ref":{"doc":"KY","page":26}},{"id":"ky-124","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, after a DUI arrest, what kind of license might you get right away so you can keep driving?","o":["A Class E moped license","An ignition interlock license","A learner's permit","A commercial license"],"h1":"It works with a device that checks your breath.","h2":"In Kentucky, even though your license will be suspended, you may be eligible right away for an ignition interlock license that lets you drive during the suspension.","p":"Right. An ignition interlock license."},"es":{"q":"En Kentucky, después de un arresto por DUI, ¿qué tipo de licencia podría recibir enseguida para seguir manejando?","o":["Una licencia Clase E de ciclomotor","Una licencia con bloqueo de encendido (ignition interlock)","Un permiso de aprendizaje","Una licencia comercial"],"h1":"Funciona con un aparato que revisa su aliento.","h2":"En Kentucky, aunque le suspenderán la licencia, podría recibir enseguida una licencia con bloqueo de encendido que le permite manejar durante la suspensión.","p":"Correcto. Una licencia con bloqueo de encendido."},"ref":{"doc":"KY","page":27}},{"id":"ky-125","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, a DUI driver was going more than how many mph over the speed limit, making it an aggravating case with mandatory jail?","o":["5 mph","10 mph","30 mph","50 mph"],"h1":"It is a very high speed over the limit.","h2":"In Kentucky, driving more than 30 mph over the posted limit while under the influence is an aggravating circumstance that requires jail time.","p":"Right. More than 30 mph over the limit."},"es":{"q":"En Kentucky, un conductor ebrio iba a más de cuántas mph sobre el límite, lo que hace el caso agravado con cárcel obligatoria?","o":["5 mph","10 mph","30 mph","50 mph"],"h1":"Es una velocidad muy alta sobre el límite.","h2":"En Kentucky, manejar ebrio a más de 30 mph sobre el límite indicado es una circunstancia agravante que exige cárcel.","p":"Correcto. Más de 30 mph sobre el límite."},"ref":{"doc":"KY","page":27}},{"id":"ky-126","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, what blood or breath alcohol level makes a DUI an aggravating case with mandatory jail?","o":["0.02 or higher","0.05 or higher","0.08 or higher","0.15 or higher"],"h1":"It is nearly twice the regular adult limit.","h2":"In Kentucky, a DUI with an alcohol concentration of 0.15 or higher within two hours of driving is an aggravating circumstance with mandatory jail time.","p":"Right. 0.15 or higher."},"es":{"q":"En Kentucky, ¿qué nivel de alcohol en la sangre o el aliento hace que un DUI sea un caso agravado con cárcel obligatoria?","o":["0.02 o más","0.05 o más","0.08 o más","0.15 o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"En Kentucky, un DUI con concentración de alcohol de 0.15 o más dentro de dos horas después de manejar es una circunstancia agravante con cárcel obligatoria.","p":"Correcto. 0.15 o más."},"ref":{"doc":"KY","page":27}},{"id":"ky-127","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, which of these makes a DUI an aggravating case with mandatory jail?","o":["Driving the wrong way on a limited-access highway","Driving with the radio on","Driving at night","Driving a rental car"],"h1":"Think of the most dangerous direction to drive on a highway.","h2":"In Kentucky, driving the wrong way on a limited-access highway while under the influence is an aggravating circumstance with mandatory jail time.","p":"Right. Wrong-way driving on a limited-access highway."},"es":{"q":"En Kentucky, ¿cuál de estos hace que un DUI sea un caso agravado con cárcel obligatoria?","o":["Manejar en sentido contrario en una autopista de acceso limitado","Manejar con la radio prendida","Manejar de noche","Manejar un auto rentado"],"h1":"Piense en la dirección más peligrosa para manejar en una autopista.","h2":"En Kentucky, manejar ebrio en sentido contrario en una autopista de acceso limitado es una circunstancia agravante con cárcel obligatoria.","p":"Correcto. Manejar en sentido contrario en una autopista de acceso limitado."},"ref":{"doc":"KY","page":27}},{"id":"ky-128","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, what may a driver convicted of DUI have to give up to the court during the license suspension?","o":["Their house keys","Their vehicle license plates, unless they have an interlock or hardship license","Their birth certificate","Their phone"],"h1":"It is something attached to the car.","h2":"In Kentucky, drivers convicted of DUI forfeit their license plates to the court during the suspension, unless they have an ignition interlock or hardship license.","p":"Right. They give up their license plates."},"es":{"q":"En Kentucky, ¿qué podría tener que entregar al tribunal un conductor condenado por DUI durante la suspensión de su licencia?","o":["Las llaves de su casa","Las placas de su vehículo, salvo que tenga licencia con bloqueo de encendido o de dificultad (hardship)","Su acta de nacimiento","Su teléfono"],"h1":"Es algo que va pegado al auto.","h2":"En Kentucky, los conductores condenados por DUI entregan sus placas al tribunal durante la suspensión, salvo que tengan licencia con bloqueo de encendido o de dificultad.","p":"Correcto. Entregan las placas."},"ref":{"doc":"KY","page":27}},{"id":"ky-129","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"How far from the steering wheel does the Kentucky manual say your chest should be?","o":["2 inches","4 inches","24 inches","10 inches"],"h1":"It is about the length of a hand and a half.","h2":"The Kentucky manual says there should be 10 inches between your chest and the steering wheel.","p":"Right. About 10 inches."},"es":{"q":"¿A qué distancia del volante dice el manual de Kentucky que debe estar su pecho?","o":["2 pulgadas","4 pulgadas","24 pulgadas","10 pulgadas"],"h1":"Es como el largo de una mano y media.","h2":"El manual de Kentucky dice que debe haber 10 pulgadas entre su pecho y el volante.","p":"Correcto. Unas 10 pulgadas."},"ref":{"doc":"KY","page":28}},{"id":"ky-130","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, the seat belt law applies to vehicles made after what year?","o":["1965","1981","1995","2010"],"h1":"It is the early 1980s.","h2":"In Kentucky, the driver and all passengers must wear seat belts in any motor vehicle made after 1981.","p":"Right. Vehicles made after 1981."},"es":{"q":"En Kentucky, ¿la ley del cinturón de seguridad se aplica a vehículos fabricados después de qué año?","o":["1965","1981","1995","2010"],"h1":"Es a principios de los años ochenta.","h2":"En Kentucky, el conductor y todos los pasajeros deben usar cinturón en cualquier vehículo fabricado después de 1981.","p":"Correcto. Vehículos fabricados después de 1981."},"ref":{"doc":"KY","page":29}},{"id":"ky-131","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, where should children 12 and under ride?","o":["In the back seat, with a seat belt or child restraint","In the cargo area","In the front seat","On an adult's lap"],"h1":"Air bags in front can hurt small passengers.","h2":"In Kentucky, children 12 years of age and under should ride in the back seat in a seat belt or child restraint system.","p":"Right. In the back seat, buckled up."},"es":{"q":"En Kentucky, ¿dónde deben ir los niños de 12 años o menos?","o":["En el asiento de atrás, con cinturón o sistema de retención infantil","En el área de carga","En el asiento delantero","En las piernas de un adulto"],"h1":"Las bolsas de aire de adelante pueden lastimar a pasajeros pequeños.","h2":"En Kentucky, los niños de 12 años o menos deben ir en el asiento de atrás con cinturón o en un sistema de retención infantil.","p":"Correcto. En el asiento de atrás, abrochados."},"ref":{"doc":"KY","page":30}},{"id":"ky-132","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, what is the fine for breaking the child restraint law?","o":["$250","$100","$500","$50, plus a $10 fee for the brain injury trust fund"],"h1":"It is a small fine plus a small extra fee.","h2":"In Kentucky, a child restraint law violation brings a $50 fine plus a $10 fee that goes to the Traumatic Brain Injury Trust Fund.","p":"Right. $50 plus a $10 fee."},"es":{"q":"En Kentucky, ¿cuál es la multa por violar la ley de asientos de seguridad infantil?","o":["$250","$100","$500","$50, más $10 para el fondo de lesiones cerebrales"],"h1":"Es una multa pequeña más un cargo pequeño.","h2":"En Kentucky, violar la ley de asientos de seguridad infantil trae una multa de $50 más un cargo de $10 que va al fondo para lesiones cerebrales traumáticas.","p":"Correcto. $50 más un cargo de $10."},"ref":{"doc":"KY","page":31}},{"id":"ky-133","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, a child is 45 inches tall. Up to what age must the child ride in a booster seat?","o":["Under 8 years old","Under 4 years old","Under 12 years old","Under 16 years old"],"h1":"The booster rule covers young children between 40 and 57 inches.","h2":"In Kentucky, a child under 8 years old who is between 40 and 57 inches tall must ride in a booster seat.","p":"Right. Under 8 and between 40 and 57 inches."},"es":{"q":"En Kentucky, un niño mide 45 pulgadas. ¿Hasta qué edad debe ir en un asiento elevado (booster)?","o":["Menos de 8 años","Menos de 4 años","Menos de 12 años","Menos de 16 años"],"h1":"La regla del asiento elevado cubre a niños pequeños de entre 40 y 57 pulgadas.","h2":"En Kentucky, un niño menor de 8 años que mide entre 40 y 57 pulgadas debe ir en un asiento elevado.","p":"Correcto. Menor de 8 años y entre 40 y 57 pulgadas."},"ref":{"doc":"KY","page":31}},{"id":"ky-134","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, when is a load in your truck or trailer considered secure?","o":["When it is covered with any cloth","When it is under the tailgate height","When nothing can slide, shift, fall, sift onto the road, or blow away","When you drive under 45 mph"],"h1":"Every piece must stay put, even dust and small bits.","h2":"In Kentucky, a load is secure only when nothing can slide, shift, fall, or sift onto the roadway or become airborne.","p":"Right. Nothing can move off the vehicle."},"es":{"q":"En Kentucky, ¿cuándo se considera segura la carga de su camioneta o tráiler?","o":["Cuando está cubierta con cualquier tela","Cuando no pasa de la altura de la compuerta","Cuando nada puede deslizarse, moverse, caer, regarse en la vía o volar","Cuando maneja a menos de 45 mph"],"h1":"Cada pieza debe quedarse en su lugar, hasta el polvo y los pedacitos.","h2":"En Kentucky, la carga es segura solo cuando nada puede deslizarse, moverse, caer o regarse en la vía, ni salir volando.","p":"Correcto. Nada puede salirse del vehículo."},"ref":{"doc":"KY","page":31}},{"id":"ky-135","scope":"KY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Kentucky, which car features may you not use during the driving test?","o":["Turn signals","Windshield wipers","Headlights","Parking assist and cruise control"],"h1":"The examiner wants to see your own skills, not the car's.","h2":"In Kentucky, you will not be allowed to use certain safety features, such as parking assist and cruise control, during the driving test.","p":"Right. No parking assist or cruise control on the test."},"es":{"q":"En Kentucky, ¿qué funciones del auto no puede usar durante el examen de manejo?","o":["Las direccionales","Los limpiaparabrisas","Las luces delanteras","La asistencia para estacionar y el control de crucero"],"h1":"El examinador quiere ver sus habilidades, no las del auto.","h2":"En Kentucky, durante el examen de manejo no le permitirán usar algunas funciones de seguridad, como la asistencia para estacionar y el control de crucero.","p":"Correcto. Sin asistencia para estacionar ni control de crucero."},"ref":{"doc":"KY","page":32}},{"id":"ky-136","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, on high beam, how far ahead must your headlights show a person?","o":["350 feet","100 feet","200 feet","1,000 feet"],"h1":"Low beams must reach 100 feet; high beams reach much farther.","h2":"In Kentucky, high beams must light the road well enough to show a person 350 feet ahead; low beams must show 100 feet ahead.","p":"Right. 350 feet on high beam."},"es":{"q":"En Kentucky, con las luces altas, ¿a qué distancia deben mostrar sus faros a una persona?","o":["350 pies","100 pies","200 pies","1,000 pies"],"h1":"Las luces bajas deben llegar a 100 pies; las altas llegan mucho más lejos.","h2":"En Kentucky, las luces altas deben alumbrar lo suficiente para mostrar a una persona a 350 pies; las bajas, a 100 pies.","p":"Correcto. 350 pies con luces altas."},"ref":{"doc":"KY","page":12}},{"id":"ky-137","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, from how far behind must your red taillight be visible?","o":["100 feet","500 feet","50 feet","2 miles"],"h1":"It is the same distance used for dimming high beams for oncoming cars.","h2":"In Kentucky, the red taillight must be lit and placed so it can be seen from 500 feet behind the vehicle.","p":"Right. 500 feet behind."},"es":{"q":"En Kentucky, ¿desde qué distancia detrás del vehículo debe verse su luz trasera roja?","o":["100 pies","500 pies","50 pies","2 millas"],"h1":"Es la misma distancia que se usa para bajar las luces altas ante autos que vienen de frente.","h2":"En Kentucky, la luz trasera roja debe estar encendida y colocada para que se vea desde 500 pies detrás del vehículo.","p":"Correcto. 500 pies detrás."},"ref":{"doc":"KY","page":12}},{"id":"ky-138","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, what may be on your windshield besides required certificates?","o":["Any decals you like","A full tint film","Sun screening along a strip at the top","A phone mount in the center"],"h1":"Only a narrow band is allowed, high up.","h2":"In Kentucky, only certificates required by law and sun screening along a strip at the top of the windshield are allowed.","p":"Right. Only a tint strip at the top."},"es":{"q":"En Kentucky, ¿qué puede tener en el parabrisas además de los certificados obligatorios?","o":["Las calcomanías que quiera","Una película polarizada completa","Una franja polarizada en la parte de arriba","Un soporte de teléfono en el centro"],"h1":"Solo se permite una franja angosta, arriba.","h2":"En Kentucky, en el parabrisas solo se permiten los certificados exigidos por ley y una franja polarizada en la parte de arriba.","p":"Correcto. Solo una franja polarizada arriba."},"ref":{"doc":"KY","page":12}},{"id":"ky-139","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Where does the Kentucky manual say to place your hands on the steering wheel?","o":["At 10 and 2 o'clock","At 9 and 3 o'clock, on the outside of the wheel","Both hands at 12 o'clock","One hand at 6 o'clock"],"h1":"The old 10-and-2 position is risky with air bags.","h2":"The Kentucky manual says to hold the outside of the wheel at the 9 and 3 o'clock positions; 10 and 2 is no longer recommended because of air bags.","p":"Right. 9 and 3 o'clock."},"es":{"q":"¿Dónde dice el manual de Kentucky que ponga las manos en el volante?","o":["A las 10 y las 2","A las 9 y las 3, por fuera del volante","Las dos manos a las 12","Una mano a las 6"],"h1":"La vieja posición de 10 y 2 es riesgosa con bolsas de aire.","h2":"El manual de Kentucky dice que tome el volante por fuera en las posiciones de las 9 y las 3; ya no se recomienda 10 y 2 por las bolsas de aire.","p":"Correcto. A las 9 y las 3."},"ref":{"doc":"KY","page":33}},{"id":"ky-140","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, you are on a minor road meeting a main road with no signs. Who should yield?","o":["The driver on the main road","Whoever is driving faster","The larger vehicle","You, the driver on the minor road"],"h1":"The busier road usually gets priority.","h2":"In Kentucky, drivers on a minor road must yield to drivers on a main road.","p":"Right. The minor road yields to the main road."},"es":{"q":"En Kentucky, usted va por una vía secundaria que llega a una vía principal sin señales. ¿Quién debe ceder el paso?","o":["El conductor de la vía principal","El que va más rápido","El vehículo más grande","Usted, el conductor de la vía secundaria"],"h1":"La vía con más tráfico suele tener prioridad.","h2":"En Kentucky, los conductores de una vía secundaria deben ceder el paso a los de una vía principal.","p":"Correcto. La vía secundaria cede el paso a la principal."},"ref":{"doc":"KY","page":34}},{"id":"ky-141","scope":"KY","cat":"signals","sign":null,"c":0,"en":{"q":"In some Kentucky cities, traffic lights hang sideways. Where is the red light?","o":["On the left","On the right","In the middle","It changes by city"],"h1":"Green is on the opposite end from red.","h2":"In Kentucky, on a horizontal traffic light, red is on the left, yellow in the middle, and green on the right.","p":"Right. Red is on the left."},"es":{"q":"En algunas ciudades de Kentucky, los semáforos están de lado. ¿Dónde está la luz roja?","o":["A la izquierda","A la derecha","En el medio","Depende de la ciudad"],"h1":"El verde está en el otro extremo del rojo.","h2":"En Kentucky, en un semáforo horizontal, el rojo está a la izquierda, el amarillo en el medio y el verde a la derecha.","p":"Correcto. El rojo está a la izquierda."},"ref":{"doc":"KY","page":34}},{"id":"ky-142","scope":"KY","cat":"signals","sign":null,"c":1,"en":{"q":"In Kentucky, you entered an intersection on yellow and the light turns red while you are in it. What should you do?","o":["Stop where you are","Clear the intersection; it is legal because you entered on yellow","Back up to the stop line","Turn on your hazards and wait"],"h1":"Getting out of the intersection is safer than stopping in it.","h2":"In Kentucky, a vehicle that entered the intersection on yellow may clear it on red, but entering after the light turns red is against the law.","p":"Right. Finish crossing; you entered on yellow."},"es":{"q":"En Kentucky, entró a una intersección con luz amarilla y se pone roja mientras está adentro. ¿Qué debe hacer?","o":["Pararse donde está","Terminar de cruzar; es legal porque entró con amarilla","Retroceder hasta la línea de parada","Prender las luces de emergencia y esperar"],"h1":"Salir de la intersección es más seguro que pararse adentro.","h2":"En Kentucky, un vehículo que entró a la intersección con amarilla puede terminar de cruzar con roja, pero entrar después de que se pone roja es ilegal.","p":"Correcto. Termine de cruzar; entró con amarilla."},"ref":{"doc":"KY","page":35}},{"id":"ky-143","scope":"KY","cat":"signals","sign":null,"c":2,"en":{"q":"According to the Kentucky manual, what do two flashing red lights at the side of the road usually mark?","o":["A school zone","A fire station","A railroad crossing","A toll booth"],"h1":"Trains are involved.","h2":"The Kentucky manual says two flashing red lights mark a railroad crossing: stop, and go only after the lights stop and no train is coming.","p":"Right. A railroad crossing."},"es":{"q":"Según el manual de Kentucky, ¿qué indican normalmente dos luces rojas intermitentes al lado de la vía?","o":["Una zona escolar","Una estación de bomberos","Un cruce de ferrocarril","Una caseta de peaje"],"h1":"Hay trenes de por medio.","h2":"El manual de Kentucky dice que dos luces rojas intermitentes marcan un cruce de ferrocarril: pare y siga solo cuando las luces se apaguen y no venga ningún tren.","p":"Correcto. Un cruce de ferrocarril."},"ref":{"doc":"KY","page":35}},{"id":"ky-144","scope":"KY","cat":"signals","sign":null,"c":3,"en":{"q":"According to the Kentucky manual, the white X-shaped crossbuck sign at a railroad crossing means the same as which sign?","o":["A speed limit sign","A no-passing sign","A stop sign","A yield sign"],"h1":"You must slow and give way to trains.","h2":"The Kentucky manual says the crossbuck sign at a railroad crossing is a regulatory sign that means the same as a yield sign.","p":"Right. A crossbuck means the same as a yield sign."},"es":{"q":"Según el manual de Kentucky, la señal blanca en forma de X (crossbuck) en un cruce de tren significa lo mismo que qué señal?","o":["Una señal de límite de velocidad","Una señal de no rebasar","Una señal de alto","Una señal de ceda el paso"],"h1":"Debe bajar la velocidad y dar paso a los trenes.","h2":"El manual de Kentucky dice que la señal en X de un cruce de tren es una señal reglamentaria que significa lo mismo que ceda el paso.","p":"Correcto. La X significa lo mismo que ceda el paso."},"ref":{"doc":"KY","page":35}},{"id":"ky-145","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, your car stalls on the tracks and a train is coming. Which way should you run?","o":["Away from the tracks, toward the direction the train is coming from","Along the tracks, away from the train","Back into your car","Across the tracks in the train's direction of travel"],"h1":"Flying debris goes the way the train is moving.","h2":"The Kentucky manual says to leave the car right away and run away from the tracks toward the direction the train is coming from, to avoid flying debris.","p":"Right. Run toward the train's direction, away from the tracks."},"es":{"q":"En Kentucky, su auto se apaga sobre las vías y viene un tren. ¿Hacia dónde debe correr?","o":["Lejos de las vías, hacia el lado de donde viene el tren","Por las vías, alejándose del tren","De vuelta a su auto","Cruzando las vías en la dirección en que va el tren"],"h1":"Los pedazos salen volando en la dirección en que va el tren.","h2":"El manual de Kentucky dice que salga enseguida del auto y corra lejos de las vías hacia el lado de donde viene el tren, para evitar pedazos que salgan volando.","p":"Correcto. Corra hacia el lado de donde viene el tren, lejos de las vías."},"ref":{"doc":"KY","page":37}},{"id":"ky-146","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, how may you use a shared center left-turn lane?","o":["Only for left turns, from either direction","As a through lane in heavy traffic","For parking briefly","For passing slow cars"],"h1":"Its name tells you its only purpose.","h2":"In Kentucky, a shared center left-turn lane is only for left-turning vehicles from either direction, not for through traffic or passing.","p":"Right. Left turns only."},"es":{"q":"En Kentucky, ¿cómo puede usar un carril central compartido para vueltas a la izquierda?","o":["Solo para dar vuelta a la izquierda, desde ambas direcciones","Como carril normal cuando hay mucho tráfico","Para estacionarse un rato","Para rebasar autos lentos"],"h1":"Su nombre dice para qué sirve.","h2":"En Kentucky, el carril central compartido es solo para vehículos que dan vuelta a la izquierda desde ambas direcciones, no para pasar de largo ni para rebasar.","p":"Correcto. Solo vueltas a la izquierda."},"ref":{"doc":"KY","page":38}},{"id":"ky-147","scope":"KY","cat":"signals","sign":null,"c":1,"en":{"q":"In Kentucky, how far before an intersection should you signal a turn?","o":["50 feet","100 feet","500 feet","At the corner"],"h1":"It is about the length of six or seven cars.","h2":"In Kentucky, signal 100 feet before you turn at an intersection.","p":"Right. 100 feet before the turn."},"es":{"q":"En Kentucky, ¿con cuánta anticipación antes de una intersección debe poner la direccional para dar vuelta?","o":["50 pies","100 pies","500 pies","En la esquina"],"h1":"Es como el largo de seis o siete autos.","h2":"En Kentucky, ponga la direccional 100 pies antes de dar vuelta en una intersección.","p":"Correcto. 100 pies antes de la vuelta."},"ref":{"doc":"KY","page":42}},{"id":"ky-148","scope":"KY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kentucky, before using a driveway to turn around (a turnabout), how far should your car be visible in each direction?","o":["50 feet","100 feet","500 feet","1 mile"],"h1":"Other drivers need plenty of warning.","h2":"In Kentucky, before a turnabout, make sure your car can be seen for 500 feet in either direction.","p":"Right. 500 feet each way."},"es":{"q":"En Kentucky, antes de usar una entrada de cochera para dar la vuelta (turnabout), ¿desde qué distancia debe verse su auto en cada dirección?","o":["50 pies","100 pies","500 pies","1 milla"],"h1":"Los otros conductores necesitan bastante aviso.","h2":"En Kentucky, antes de dar la vuelta en una entrada, asegúrese de que su auto se vea desde 500 pies en ambas direcciones.","p":"Correcto. 500 pies en cada dirección."},"ref":{"doc":"KY","page":43}},{"id":"ky-149","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, besides school buses, what other bus must you stop for when it is loading or unloading with its stop arm out?","o":["City transit buses","Tour buses","Airport shuttles","Church buses"],"h1":"It is a bus used by a place of worship.","h2":"In Kentucky, you must stop for a school or church bus that is stopped to load or unload passengers with its stop arm and lights on.","p":"Right. Church buses too."},"es":{"q":"En Kentucky, además de los autobuses escolares, ¿por qué otro autobús debe detenerse cuando sube o baja pasajeros con la señal de alto extendida?","o":["Autobuses urbanos","Autobuses de turismo","Transportes del aeropuerto","Autobuses de iglesia"],"h1":"Es un autobús que usa un lugar de culto.","h2":"En Kentucky, debe detenerse ante un autobús escolar o de iglesia que está parado para subir o bajar pasajeros con la señal de alto y las luces encendidas.","p":"Correcto. También los autobuses de iglesia."},"ref":{"doc":"KY","page":44}},{"id":"ky-150","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, you stopped for a school bus. When may you go?","o":["When everyone is clear of the road and the bus starts moving","As soon as the stop arm starts to fold","After waiting 30 seconds","When the children reach the sidewalk, even if the bus is still stopped with lights on"],"h1":"Wait for two things: people clear and the bus moving.","h2":"In Kentucky, you must stay stopped until all people are clear of the roadway and the bus is in motion.","p":"Right. Wait until people are clear and the bus moves."},"es":{"q":"En Kentucky, se detuvo por un autobús escolar. ¿Cuándo puede seguir?","o":["Cuando todos están fuera de la vía y el autobús empieza a moverse","En cuanto la señal de alto empieza a doblarse","Después de esperar 30 segundos","Cuando los niños llegan a la banqueta, aunque el autobús siga parado con luces"],"h1":"Espere dos cosas: que no haya gente en la vía y que el autobús se mueva.","h2":"En Kentucky, debe quedarse detenido hasta que todas las personas estén fuera de la vía y el autobús esté en movimiento.","p":"Correcto. Espere a que no haya gente en la vía y el autobús se mueva."},"ref":{"doc":"KY","page":44}},{"id":"ky-151","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, what does the law require when you leave your parked vehicle?","o":["Leave the engine running if you will be back soon","Turn off the engine and remove the key","Leave the windows down","Leave the hazard lights on"],"h1":"This keeps the car from being moved by someone else.","h2":"In Kentucky, the law requires you to turn off the engine and remove the key when you leave a vehicle.","p":"Right. Engine off and key out."},"es":{"q":"En Kentucky, ¿qué exige la ley cuando deja su vehículo estacionado?","o":["Dejar el motor prendido si vuelve pronto","Apagar el motor y sacar la llave","Dejar las ventanas abiertas","Dejar las luces de emergencia prendidas"],"h1":"Así nadie más puede mover el auto.","h2":"En Kentucky, la ley exige que apague el motor y saque la llave cuando deja un vehículo.","p":"Correcto. Motor apagado y llave afuera."},"ref":{"doc":"KY","page":45}},{"id":"ky-152","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, on a road with three or more lanes in your direction, what are the middle lanes for?","o":["Trucks only","Passing only","Through traffic","Turning right"],"h1":"Left is for passing, right is for entering and exiting.","h2":"In Kentucky, when there are three or more lanes in one direction, the middle lane or lanes are for through traffic.","p":"Right. Middle lanes are for through traffic."},"es":{"q":"En Kentucky, en una vía con tres o más carriles en su dirección, ¿para qué son los carriles del medio?","o":["Solo para camiones","Solo para rebasar","Para el tráfico que sigue de largo","Para dar vuelta a la derecha"],"h1":"El izquierdo es para rebasar y el derecho para entrar y salir.","h2":"En Kentucky, cuando hay tres o más carriles en una dirección, el carril o los carriles del medio son para el tráfico que sigue de largo.","p":"Correcto. Los del medio son para seguir de largo."},"ref":{"doc":"KY","page":46}},{"id":"ky-153","scope":"KY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kentucky, can you stay in the left lane of a limited-access highway when you are not passing?","o":["Yes, at any speed","Yes, if you drive the speed limit","Yes, but only at night","No, remaining in the left lane is illegal"],"h1":"The left lane is reserved for passing.","h2":"In Kentucky, remaining in the left lane on a limited-access highway is illegal; it is for passing.","p":"Right. Staying in the left lane is illegal."},"es":{"q":"En Kentucky, ¿puede quedarse en el carril izquierdo de una autopista de acceso limitado cuando no está rebasando?","o":["Sí, a cualquier velocidad","Sí, si va al límite de velocidad","Sí, pero solo de noche","No, quedarse en el carril izquierdo es ilegal"],"h1":"El carril izquierdo es para rebasar.","h2":"En Kentucky, quedarse en el carril izquierdo de una autopista de acceso limitado es ilegal; ese carril es para rebasar.","p":"Correcto. Quedarse en el carril izquierdo es ilegal."},"ref":{"doc":"KY","page":46}},{"id":"ky-154","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, may you pass a car on the right by driving onto the shoulder?","o":["Yes, whenever the shoulder is paved","Only if the car being passed has come to a complete stop and it is safe","Yes, if you honk first","Yes, on any road with two lanes"],"h1":"Leaving the roadway to pass is allowed only in one narrow case.","h2":"In Kentucky, you may not pass on the right by driving off the roadway unless the vehicle being passed has come to a complete stop and it is safe.","p":"Right. Only if the other vehicle has stopped and it is safe."},"es":{"q":"En Kentucky, ¿puede rebasar a un auto por la derecha manejando por el acotamiento?","o":["Sí, siempre que el acotamiento esté pavimentado","Solo si el auto que rebasa se detuvo por completo y es seguro","Sí, si toca el claxon antes","Sí, en cualquier vía de dos carriles"],"h1":"Salirse de la vía para rebasar solo se permite en un caso muy limitado.","h2":"En Kentucky, no puede rebasar por la derecha saliéndose de la vía, salvo que el vehículo que rebasa se haya detenido por completo y sea seguro.","p":"Correcto. Solo si el otro vehículo se detuvo y es seguro."},"ref":{"doc":"KY","page":47}},{"id":"ky-155","scope":"KY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kentucky, you are still in the left lane passing when you reach the start of a no-passing zone. What does that mean?","o":["It is fine if you finish quickly","It is fine if no one is coming","You are breaking the law; the pass must be finished before the zone begins","It is only a warning zone"],"h1":"The pass has to be complete before the zone starts.","h2":"In Kentucky, a pass must be completed before reaching the beginning of a no-passing zone; still being in the left lane there is a violation.","p":"Right. You must finish passing before the zone begins."},"es":{"q":"En Kentucky, todavía está en el carril izquierdo rebasando cuando llega al inicio de una zona de no rebasar. ¿Qué significa eso?","o":["Está bien si termina rápido","Está bien si no viene nadie","Está violando la ley; debe terminar de rebasar antes de que empiece la zona","Es solo una zona de advertencia"],"h1":"Debe terminar de rebasar antes de que empiece la zona.","h2":"En Kentucky, hay que terminar de rebasar antes del inicio de una zona de no rebasar; seguir en el carril izquierdo ahí es una infracción.","p":"Correcto. Debe terminar de rebasar antes de que empiece la zona."},"ref":{"doc":"KY","page":47}},{"id":"ky-156","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, another car is about to pass you. What does the law require you to do?","o":["Speed up to keep your place","Move to the left to block","Flash your lights","Stay in your lane and give way to the right"],"h1":"Help the passing driver get by safely.","h2":"In Kentucky, a driver who is about to be passed must give way to the right in favor of the passing vehicle.","p":"Right. Give way to the right."},"es":{"q":"En Kentucky, otro auto está por rebasarlo. ¿Qué exige la ley que haga?","o":["Acelerar para no perder su lugar","Moverse a la izquierda para bloquearlo","Hacer cambio de luces","Seguir en su carril y orillarse a la derecha"],"h1":"Ayude a que el otro conductor pase con seguridad.","h2":"En Kentucky, el conductor que va a ser rebasado debe orillarse a la derecha para dar paso al vehículo que rebasa.","p":"Correcto. Orillarse a la derecha."},"ref":{"doc":"KY","page":48}},{"id":"ky-157","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, you are on a road with two lanes in your direction and you come up behind a bicycle. How should you pass?","o":["Move into the lane to your left, if it is open and safe","Squeeze past in the same lane","Honk and wait for the cyclist to move off the road","Pass on the cyclist's right"],"h1":"With an extra lane available, use it.","h2":"In Kentucky, when there is more than one lane in your direction, move into the lane to your left, if it is available and safe, to pass a bicycle.","p":"Right. Move over to the next lane to the left."},"es":{"q":"En Kentucky, va por una vía con dos carriles en su dirección y alcanza a una bicicleta. ¿Cómo debe rebasarla?","o":["Pasarse al carril de la izquierda, si está libre y es seguro","Pasar apretado en el mismo carril","Tocar el claxon y esperar a que el ciclista salga de la vía","Rebasar por la derecha del ciclista"],"h1":"Si hay otro carril disponible, úselo.","h2":"En Kentucky, cuando hay más de un carril en su dirección, para rebasar a una bicicleta pásese al carril de la izquierda si está libre y es seguro.","p":"Correcto. Cámbiese al carril de la izquierda."},"ref":{"doc":"KY","page":48}},{"id":"ky-158","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, may you cross the center line in a no-passing zone to pass a bicycle?","o":["Never","Yes, if the left side is clear far enough to pass safely without bothering oncoming traffic","Yes, at any time","Only on a bridge"],"h1":"The law makes a special exception for bicycles and low-speed scooters.","h2":"In Kentucky, you may drive left of the center line, even in a no-passing zone, to pass a bicycle or electric low-speed scooter if the left side is clear far enough to pass safely.","p":"Right. Allowed when the way is clear far enough."},"es":{"q":"En Kentucky, ¿puede cruzar la línea central en una zona de no rebasar para rebasar a una bicicleta?","o":["Nunca","Sí, si el lado izquierdo está libre por suficiente distancia para rebasar sin afectar a quienes vienen de frente","Sí, en cualquier momento","Solo en un puente"],"h1":"La ley hace una excepción especial para bicicletas y scooters eléctricos de baja velocidad.","h2":"En Kentucky, puede pasar a la izquierda de la línea central, aun en zona de no rebasar, para rebasar a una bicicleta o scooter eléctrico de baja velocidad si el lado izquierdo está libre por suficiente distancia.","p":"Correcto. Se permite cuando el camino está libre por suficiente distancia."},"ref":{"doc":"KY","page":48}},{"id":"ky-159","scope":"KY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Kentucky, what is the speed limit on state highways that are not interstates or parkways, when none is posted?","o":["45 mph","50 mph","55 mph","60 mph"],"h1":"It is 10 mph below the interstate limit.","h2":"In Kentucky, the speed limit on all other state highways is 55 mph when no other limit is posted.","p":"Right. 55 mph."},"es":{"q":"En Kentucky, ¿cuál es el límite de velocidad en las carreteras estatales que no son interestatales ni parkways, cuando no hay otro indicado?","o":["45 mph","50 mph","55 mph","60 mph"],"h1":"Es 10 mph menos que el límite en las interestatales.","h2":"En Kentucky, el límite de velocidad en todas las demás carreteras estatales es de 55 mph cuando no hay otro indicado.","p":"Correcto. 55 mph."},"ref":{"doc":"KY","page":49}},{"id":"ky-160","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"How far ahead does the Kentucky manual say you should try to look while driving?","o":["2 to 3 seconds","5 seconds","1 minute","20 to 30 seconds"],"h1":"Looking well ahead gives you time to plan.","h2":"The Kentucky manual says you should try to look at what is happening 20 to 30 seconds in front of your car.","p":"Right. 20 to 30 seconds ahead."},"es":{"q":"¿Qué tan adelante dice el manual de Kentucky que trate de mirar mientras maneja?","o":["2 a 3 segundos","5 segundos","1 minuto","20 a 30 segundos"],"h1":"Mirar bien adelante le da tiempo para planear.","h2":"El manual de Kentucky dice que trate de ver lo que pasa de 20 a 30 segundos delante de su auto.","p":"Correcto. De 20 a 30 segundos adelante."},"ref":{"doc":"KY","page":49}},{"id":"ky-161","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kentucky manual, about how far does it take to brake to a stop from 50 mph on dry pavement with good brakes?","o":["About 30 feet","About 60 feet","About 158 feet","About 600 feet"],"h1":"It is about half the length of a football field.","h2":"The Kentucky manual says braking from 50 mph on dry pavement with good brakes can take about 158 feet.","p":"Right. About 158 feet."},"es":{"q":"Según el manual de Kentucky, ¿más o menos qué distancia se necesita para frenar hasta parar desde 50 mph en pavimento seco con buenos frenos?","o":["Unos 30 pies","Unos 60 pies","Unos 158 pies","Unos 600 pies"],"h1":"Es como la mitad de una cancha de fútbol americano.","h2":"El manual de Kentucky dice que frenar desde 50 mph en pavimento seco con buenos frenos puede tomar unos 158 pies.","p":"Correcto. Unos 158 pies."},"ref":{"doc":"KY","page":51}},{"id":"ky-162","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, how much should you add to your following distance when driving at night?","o":["Nothing; keep the same distance","Half a second","Ten seconds","At least one more second"],"h1":"Darkness makes hazards harder to see, so add a little time.","h2":"The Kentucky manual says to add at least one more second of following distance at night, and at least two more on unfamiliar roads at night.","p":"Right. At least one extra second at night."},"es":{"q":"En Kentucky, ¿cuánto debe aumentar su distancia de seguimiento cuando maneja de noche?","o":["Nada; mantenga la misma distancia","Medio segundo","Diez segundos","Al menos un segundo más"],"h1":"La oscuridad hace más difícil ver los peligros, así que agregue un poco de tiempo.","h2":"El manual de Kentucky dice que agregue al menos un segundo más de distancia de seguimiento de noche, y al menos dos más en vías desconocidas de noche.","p":"Correcto. Al menos un segundo extra de noche."},"ref":{"doc":"KY","page":67}},{"id":"ky-163","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, you are driving at night on a road you do not know. How much extra following time should you add?","o":["At least two more seconds","Half a second","No extra time","Six more seconds"],"h1":"It is more than you add on familiar roads at night.","h2":"The Kentucky manual says to add at least two more seconds of following distance when driving on unfamiliar roads at night.","p":"Right. At least two extra seconds."},"es":{"q":"En Kentucky, maneja de noche por una vía que no conoce. ¿Cuánto tiempo extra de seguimiento debe agregar?","o":["Al menos dos segundos más","Medio segundo","Nada extra","Seis segundos más"],"h1":"Es más de lo que agrega de noche en vías conocidas.","h2":"El manual de Kentucky dice que agregue al menos dos segundos más de distancia de seguimiento cuando maneja de noche por vías desconocidas.","p":"Correcto. Al menos dos segundos extra."},"ref":{"doc":"KY","page":67}},{"id":"ky-164","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, within how many feet of a vehicle you are following must you dim your high beams?","o":["100 feet","300 feet","1,000 feet","50 feet"],"h1":"It is less than the distance used for oncoming cars.","h2":"In Kentucky, dim your lights within 300 feet of a vehicle you are following, and within 500 feet of an oncoming vehicle.","p":"Right. 300 feet when following."},"es":{"q":"En Kentucky, ¿a cuántos pies de un vehículo que va delante debe bajar sus luces altas?","o":["100 pies","300 pies","1,000 pies","50 pies"],"h1":"Es menos que la distancia para autos que vienen de frente.","h2":"En Kentucky, baje las luces cuando esté a 300 pies de un vehículo que va delante, y a 500 pies de uno que viene de frente.","p":"Correcto. 300 pies cuando sigue a otro."},"ref":{"doc":"KY","page":67}},{"id":"ky-165","scope":"KY","cat":"signals","sign":null,"c":3,"en":{"q":"In Kentucky, your car's turn signals stop working. May you use hand signals instead?","o":["Yes, always","Yes, during the day","Only on rural roads","No, your vehicle must have working mechanical signals"],"h1":"The manual says a car's signals must be built in and working.","h2":"In Kentucky, your vehicle must have working mechanical turn signals; hand signals cannot be used instead.","p":"Right. Mechanical signals are required."},"es":{"q":"En Kentucky, las direccionales de su auto dejan de funcionar. ¿Puede usar señales con la mano en su lugar?","o":["Sí, siempre","Sí, de día","Solo en vías rurales","No, su vehículo debe tener direccionales mecánicas que funcionen"],"h1":"El manual dice que las señales del auto deben ser de fábrica y funcionar.","h2":"En Kentucky, su vehículo debe tener direccionales mecánicas que funcionen; no se pueden usar señales con la mano en su lugar.","p":"Correcto. Se requieren direccionales mecánicas."},"ref":{"doc":"KY","page":53}},{"id":"ky-166","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, your car starts skidding sideways. Which way should you turn the steering wheel?","o":["Hard to the opposite side of the skid","Do not touch the wheel","In the direction the back of the car is skidding","Back and forth quickly"],"h1":"Line up the front of the car with the back.","h2":"The Kentucky manual says that if you skid sideways, turn the wheel in the direction the back of the vehicle is skidding so the front lines up with the back.","p":"Right. Turn toward where the back is sliding."},"es":{"q":"En Kentucky, su auto empieza a patinar de lado. ¿Hacia dónde debe girar el volante?","o":["Fuerte hacia el lado contrario del patinazo","No tocar el volante","Hacia el lado al que patina la parte de atrás del auto","De un lado a otro rápidamente"],"h1":"Alinee el frente del auto con la parte de atrás.","h2":"El manual de Kentucky dice que si patina de lado, gire el volante hacia donde se desliza la parte de atrás del vehículo para que el frente se alinee con ella.","p":"Correcto. Gire hacia donde se desliza la parte de atrás."},"ref":{"doc":"KY","page":55}},{"id":"ky-167","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, you have a minor crash and no one is hurt. What does state law say to do with the damaged cars?","o":["Leave them exactly where they stopped until police arrive","Move them to the shoulder of the road","Push them into the nearest parking lot only","Drive them home first"],"h1":"Clear the travel lanes when nobody is injured.","h2":"In Kentucky, when a crash causes no injuries, the law says to move the damaged vehicles to the shoulder of the road.","p":"Right. Move them to the shoulder."},"es":{"q":"En Kentucky, tiene un choque menor y nadie está herido. ¿Qué dice la ley del estado que haga con los autos dañados?","o":["Dejarlos exactamente donde quedaron hasta que llegue la policía","Moverlos al acotamiento de la vía","Empujarlos solo al estacionamiento más cercano","Llevarlos primero a casa"],"h1":"Despeje los carriles cuando no hay heridos.","h2":"En Kentucky, cuando un choque no causa heridos, la ley dice que mueva los vehículos dañados al acotamiento de la vía.","p":"Correcto. Muévalos al acotamiento."},"ref":{"doc":"KY","page":55}},{"id":"ky-168","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, you hit a parked car and cannot find the owner. What should you do?","o":["Drive away; no one saw","Wait one hour, then leave","Leave a note where it can be seen with your name, address, license number, plate number, and the date and time","Call your parents only"],"h1":"The owner must be able to reach you.","h2":"In Kentucky, if you hit a parked vehicle and cannot find the owner, leave a visible note with your name, address, driver's license number, plate number, and the date and time.","p":"Right. Leave a note with your information."},"es":{"q":"En Kentucky, choca con un auto estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse; nadie vio","Esperar una hora y luego irse","Dejar una nota visible con su nombre, dirección, número de licencia, número de placa y la fecha y hora","Llamar solo a sus padres"],"h1":"El dueño debe poder comunicarse con usted.","h2":"En Kentucky, si choca con un vehículo estacionado y no encuentra al dueño, deje una nota visible con su nombre, dirección, número de licencia, número de placa y la fecha y hora.","p":"Correcto. Deje una nota con sus datos."},"ref":{"doc":"KY","page":55}},{"id":"ky-169","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, a police officer investigated your crash. Should you also file a civilian collision report?","o":["Yes, always within 10 days","Yes, within 24 hours","Only if the damage is over $100","No, do not file a civilian report when an officer investigated"],"h1":"The civilian report is for crashes police did not investigate.","h2":"In Kentucky, do not complete a civilian collision report if a law enforcement officer investigated the crash.","p":"Right. No civilian report when police investigated."},"es":{"q":"En Kentucky, un policía investigó su choque. ¿Debe también llenar un reporte civil de choque?","o":["Sí, siempre dentro de 10 días","Sí, dentro de 24 horas","Solo si los daños pasan de $100","No, no llene un reporte civil si un oficial investigó"],"h1":"El reporte civil es para choques que la policía no investigó.","h2":"En Kentucky, no llene un reporte civil de choque si un oficial de policía investigó el choque.","p":"Correcto. Sin reporte civil cuando investigó la policía."},"ref":{"doc":"KY","page":56}},{"id":"ky-170","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, what must every driver in a crash do right away?","o":["Stop, find out if anyone is hurt or anything is damaged, and give reasonable help","Leave if their car still runs","Call only their insurance company","Move the injured people right away"],"h1":"The law requires you to stop and help.","h2":"In Kentucky, the driver of any vehicle in a crash must stop right away, find out the extent of any injury or damage, and give reasonable help.","p":"Right. Stop, check, and give reasonable help."},"es":{"q":"En Kentucky, ¿qué debe hacer enseguida todo conductor que tiene un choque?","o":["Detenerse, averiguar si hay heridos o daños y dar ayuda razonable","Irse si su auto todavía funciona","Llamar solo a su compañía de seguros","Mover enseguida a los heridos"],"h1":"La ley exige que se detenga y ayude.","h2":"En Kentucky, el conductor de cualquier vehículo en un choque debe detenerse enseguida, averiguar si hay heridos o daños y dar ayuda razonable.","p":"Correcto. Detenerse, revisar y dar ayuda razonable."},"ref":{"doc":"KY","page":56}},{"id":"ky-171","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, your car breaks down on the highway. How far behind it does the manual say to place flares?","o":["About 200 to 300 feet","About 10 feet","About 50 feet","About 1 mile"],"h1":"Other drivers need time to change lanes.","h2":"The Kentucky manual says to place emergency flares about 200 to 300 feet behind your disabled vehicle.","p":"Right. About 200 to 300 feet behind."},"es":{"q":"En Kentucky, su auto se descompone en la carretera. ¿A qué distancia detrás dice el manual que ponga las bengalas?","o":["Unos 200 a 300 pies","Unos 10 pies","Unos 50 pies","Una milla"],"h1":"Los otros conductores necesitan tiempo para cambiar de carril.","h2":"El manual de Kentucky dice que ponga bengalas de emergencia a unos 200 a 300 pies detrás de su vehículo descompuesto.","p":"Correcto. Unos 200 a 300 pies detrás."},"ref":{"doc":"KY","page":57}},{"id":"ky-172","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, a pedestrian crosses mid-block, away from any marked or unmarked crosswalk. Who must yield?","o":["The drivers must always stop","The pedestrian must yield to vehicles, though drivers should still be ready to stop","Whoever is faster","No one"],"h1":"The law places the duty on the person outside the crosswalk, but you still avoid hitting them.","h2":"In Kentucky, a pedestrian crossing outside a marked or unmarked crosswalk must yield to vehicles, but drivers should always be prepared to stop for them.","p":"Right. The pedestrian must yield, and you still stay ready to stop."},"es":{"q":"En Kentucky, un peatón cruza a media cuadra, lejos de cualquier cruce marcado o sin marcar. ¿Quién debe ceder el paso?","o":["Los conductores siempre deben parar","El peatón debe ceder el paso a los vehículos, aunque los conductores deben estar listos para parar","El que va más rápido","Nadie"],"h1":"La ley pone la obligación en quien está fuera del cruce, pero usted igual debe evitar atropellarlo.","h2":"En Kentucky, el peatón que cruza fuera de un cruce marcado o sin marcar debe ceder el paso a los vehículos, pero los conductores siempre deben estar listos para parar.","p":"Correcto. El peatón debe ceder, y usted igual está listo para parar."},"ref":{"doc":"KY","page":58}},{"id":"ky-173","scope":"KY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kentucky, what is the fine for failing to yield to a blind pedestrian with a white cane or assistance dog?","o":["$25","$50","Up to $250","$1,000"],"h1":"It is a few hundred dollars at most.","h2":"In Kentucky, failing to yield the right-of-way to a blind pedestrian with a white cane or assistance dog can bring a fine of up to $250.","p":"Right. Up to $250."},"es":{"q":"En Kentucky, ¿cuál es la multa por no ceder el paso a un peatón ciego con bastón blanco o perro de asistencia?","o":["$25","$50","Hasta $250","$1,000"],"h1":"Son unos cientos de dólares como máximo.","h2":"En Kentucky, no ceder el paso a un peatón ciego con bastón blanco o perro de asistencia puede costar una multa de hasta $250.","p":"Correcto. Hasta $250."},"ref":{"doc":"KY","page":58}},{"id":"ky-174","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, at a stop light with a blind pedestrian nearby, how far from the crosswalk should you stop?","o":["At least 20 feet back","In the middle of the crosswalk","Wherever you like","No more than 5 feet from it, unless there is an advanced stop line"],"h1":"A blind person uses the sound of your car as a guide.","h2":"The Kentucky manual says not to stop more than 5 feet from the crosswalk, unless there is an advanced stop line, so a blind pedestrian can hear your vehicle.","p":"Right. No more than 5 feet away."},"es":{"q":"En Kentucky, en un semáforo con un peatón ciego cerca, ¿a qué distancia del cruce peatonal debe detenerse?","o":["Al menos 20 pies antes","En medio del cruce","Donde quiera","A no más de 5 pies, salvo que haya una línea de parada adelantada"],"h1":"Una persona ciega usa el sonido de su auto como guía.","h2":"El manual de Kentucky dice que no se detenga a más de 5 pies del cruce peatonal, salvo que haya una línea de parada adelantada, para que un peatón ciego pueda oír su vehículo.","p":"Correcto. A no más de 5 pies."},"ref":{"doc":"KY","page":58}},{"id":"ky-175","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, you are waiting for a blind pedestrian. They step back and pull in their cane. What does that mean?","o":["It is a clear sign that you should go","They want you to honk","They need you to get out and help","They are about to cross"],"h1":"The person is telling you they are not crossing now.","h2":"The Kentucky manual says that when a blind pedestrian steps back and pulls in the cane, it is a clear sign that you should go.","p":"Right. It means you should go."},"es":{"q":"En Kentucky, está esperando a un peatón ciego. Da un paso atrás y recoge su bastón. ¿Qué significa?","o":["Es una señal clara de que usted debe seguir","Quiere que toque el claxon","Necesita que baje a ayudarlo","Está por cruzar"],"h1":"La persona le indica que no va a cruzar ahora.","h2":"El manual de Kentucky dice que cuando un peatón ciego da un paso atrás y recoge el bastón, es una señal clara de que usted debe seguir.","p":"Correcto. Significa que usted debe seguir."},"ref":{"doc":"KY","page":59}},{"id":"ky-176","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, when may you drive or park in a designated bike lane?","o":["Any time it is empty","Only to enter or leave an alley or driveway, on official duty, when police direct you, or in an emergency","To pass a slow car on the right","To wait for a parking space"],"h1":"The lane belongs to cyclists except in a few cases.","h2":"In Kentucky, do not stop, park, or drive in a bike lane unless you are entering or leaving an alley or driveway, on official duty, directed by police, or in an emergency.","p":"Right. Only in those few special cases."},"es":{"q":"En Kentucky, ¿cuándo puede manejar o estacionarse en un carril designado para bicicletas?","o":["Siempre que esté vacío","Solo para entrar o salir de un callejón o una entrada, en servicio oficial, si la policía se lo indica, o en una emergencia","Para rebasar por la derecha a un auto lento","Para esperar un lugar de estacionamiento"],"h1":"El carril es de los ciclistas salvo en pocos casos.","h2":"En Kentucky, no se detenga, estacione ni maneje en un carril para bicicletas salvo para entrar o salir de un callejón o una entrada, en servicio oficial, por indicación de la policía o en una emergencia.","p":"Correcto. Solo en esos pocos casos especiales."},"ref":{"doc":"KY","page":59}},{"id":"ky-177","scope":"KY","cat":"signals","sign":null,"c":2,"en":{"q":"In Kentucky, for how many feet before a turn must a bicyclist give a turn signal?","o":["10 feet","25 feet","The last 50 feet","200 feet"],"h1":"It is shorter than the 100 feet required for cars.","h2":"In Kentucky, a bicyclist must signal for the last 50 feet traveled before turning.","p":"Right. The last 50 feet."},"es":{"q":"En Kentucky, ¿durante cuántos pies antes de dar vuelta debe hacer la señal un ciclista?","o":["10 pies","25 pies","Los últimos 50 pies","200 pies"],"h1":"Es menos que los 100 pies que se exigen a los autos.","h2":"En Kentucky, el ciclista debe hacer la señal durante los últimos 50 pies antes de dar vuelta.","p":"Correcto. Los últimos 50 pies."},"ref":{"doc":"KY","page":59}},{"id":"ky-178","scope":"KY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kentucky, where may bicycles never be ridden?","o":["On city streets","On country roads","On roads with bike lanes","On interstates and parkways"],"h1":"These are the state's fastest roads.","h2":"In Kentucky, bicyclists must never ride on interstates or parkways.","p":"Right. Never on interstates or parkways."},"es":{"q":"En Kentucky, ¿por dónde nunca se puede andar en bicicleta?","o":["Por calles de la ciudad","Por caminos rurales","Por vías con carril para bicicletas","Por interestatales y parkways"],"h1":"Son las vías más rápidas del estado.","h2":"En Kentucky, los ciclistas nunca deben andar por interestatales ni parkways.","p":"Correcto. Nunca por interestatales ni parkways."},"ref":{"doc":"KY","page":60}},{"id":"ky-179","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, what lighting must a bicycle have at night?","o":["A white light in front and a red reflector or light in back","Only a red light in front","Only reflectors on the pedals","No lights are required"],"h1":"White faces forward, red faces back, like a car.","h2":"In Kentucky, a bicycle ridden at night needs a white light visible from the front and a red reflector or light visible from the rear.","p":"Right. White in front, red in back."},"es":{"q":"En Kentucky, ¿qué luces debe tener una bicicleta de noche?","o":["Una luz blanca adelante y un reflector o luz roja atrás","Solo una luz roja adelante","Solo reflectores en los pedales","No se exigen luces"],"h1":"Blanco hacia adelante y rojo hacia atrás, como un auto.","h2":"En Kentucky, una bicicleta de noche necesita una luz blanca visible desde adelante y un reflector o luz roja visible desde atrás.","p":"Correcto. Blanco adelante, rojo atrás."},"ref":{"doc":"KY","page":60}},{"id":"ky-180","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, how many bicyclists may ride side by side when it would block normal traffic?","o":["Three","No more than two","Four","Any number"],"h1":"Think of a pair.","h2":"In Kentucky, bicyclists must never ride more than two abreast in a way that interferes with normal traffic.","p":"Right. No more than two side by side."},"es":{"q":"En Kentucky, ¿cuántos ciclistas pueden ir lado a lado cuando estorbarían al tráfico normal?","o":["Tres","No más de dos","Cuatro","Cualquier número"],"h1":"Piense en una pareja.","h2":"En Kentucky, los ciclistas nunca deben ir más de dos lado a lado de una forma que estorbe al tráfico normal.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"KY","page":61}},{"id":"ky-181","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, how old must you be to ride an electric low-speed scooter on a highway, bike lane, or bike path?","o":["12","14","16","21"],"h1":"It is the same age as a regular driver's license.","h2":"In Kentucky, a person 16 or older may ride an electric low-speed scooter on a highway, bike lane, or bike path.","p":"Right. 16 or older."},"es":{"q":"En Kentucky, ¿qué edad debe tener para usar un scooter eléctrico de baja velocidad en una carretera, carril o ciclovía?","o":["12","14","16","21"],"h1":"Es la misma edad que para una licencia normal.","h2":"En Kentucky, una persona de 16 años o más puede usar un scooter eléctrico de baja velocidad en una carretera, un carril para bicicletas o una ciclovía.","p":"Correcto. 16 años o más."},"ref":{"doc":"KY","page":61}},{"id":"ky-182","scope":"KY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Kentucky, an electric low-speed scooter is designed for a top speed of how much on level pavement?","o":["10 mph","35 mph","45 mph","20 mph"],"h1":"It is slower than a moped's 30 mph.","h2":"In Kentucky, an electric low-speed scooter is designed to go no faster than 20 mph on a paved level surface.","p":"Right. 20 mph."},"es":{"q":"En Kentucky, ¿para qué velocidad máxima en pavimento plano está diseñado un scooter eléctrico de baja velocidad?","o":["10 mph","35 mph","45 mph","20 mph"],"h1":"Es más lento que los 30 mph de un ciclomotor.","h2":"En Kentucky, un scooter eléctrico de baja velocidad está diseñado para no pasar de 20 mph en pavimento plano.","p":"Correcto. 20 mph."},"ref":{"doc":"KY","page":61}},{"id":"ky-183","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Kentucky manual, how far does a loaded truck going 55 mph need to stop under ideal conditions?","o":["About 100 feet","At least 335 feet","About 50 feet","About 2 miles"],"h1":"It is more than one and a half times a car's distance.","h2":"The Kentucky manual says a loaded truck at 55 mph needs at least 335 feet to stop, more than one and a half times a car's stopping distance.","p":"Right. At least 335 feet."},"es":{"q":"Según el manual de Kentucky, ¿qué distancia necesita un camión cargado a 55 mph para parar en condiciones ideales?","o":["Unos 100 pies","Al menos 335 pies","Unos 50 pies","Unas 2 millas"],"h1":"Es más de una vez y media la distancia de un auto.","h2":"El manual de Kentucky dice que un camión cargado a 55 mph necesita al menos 335 pies para parar, más de una vez y media la distancia de un auto.","p":"Correcto. Al menos 335 pies."},"ref":{"doc":"KY","page":62}},{"id":"ky-184","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Kentucky manual, how far behind a large truck can its rear blind spot reach?","o":["About 10 feet","About 30 feet","Up to 200 feet","Up to 1 mile"],"h1":"It is a long zone, much longer than the truck itself.","h2":"The Kentucky manual says a large vehicle's blind spot directly behind it can reach up to 200 feet.","p":"Right. Up to 200 feet."},"es":{"q":"Según el manual de Kentucky, ¿hasta qué distancia detrás de un camión grande puede llegar su punto ciego trasero?","o":["Unos 10 pies","Unos 30 pies","Hasta 200 pies","Hasta 1 milla"],"h1":"Es una zona larga, mucho más que el camión mismo.","h2":"El manual de Kentucky dice que el punto ciego detrás de un vehículo grande puede llegar hasta 200 pies.","p":"Correcto. Hasta 200 pies."},"ref":{"doc":"KY","page":62}},{"id":"ky-185","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Kentucky manual, on which side does a large truck have the bigger blind spot?","o":["The left side, by the driver","Directly in front","On the roof","The right side, from behind the cab along the length of the truck"],"h1":"It is the side away from the truck driver's seat.","h2":"The Kentucky manual says trucks have a larger blind spot on the right side, starting behind the cab and running up to the length of the truck.","p":"Right. The right side is the bigger blind spot."},"es":{"q":"Según el manual de Kentucky, ¿de qué lado tiene un camión grande el punto ciego más grande?","o":["Del lado izquierdo, junto al conductor","Justo enfrente","En el techo","Del lado derecho, desde detrás de la cabina a lo largo del camión"],"h1":"Es el lado contrario al asiento del camionero.","h2":"El manual de Kentucky dice que los camiones tienen un punto ciego más grande del lado derecho, que empieza detrás de la cabina y llega a todo el largo del camión.","p":"Correcto. El lado derecho tiene el punto ciego más grande."},"ref":{"doc":"KY","page":62}},{"id":"ky-186","scope":"KY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Kentucky, which vehicles must stop at every railroad crossing, so you should be ready to stop behind them?","o":["Motorcycles","Vehicles carrying hazardous materials","Pickup trucks","Taxis"],"h1":"They are marked with signs showing what they carry.","h2":"The Kentucky manual says vehicles carrying hazardous materials must stop at all railroad crossings, so be prepared to stop behind them.","p":"Right. Hazardous materials vehicles."},"es":{"q":"En Kentucky, ¿qué vehículos deben detenerse en todos los cruces de tren, por lo que usted debe estar listo para parar detrás de ellos?","o":["Las motocicletas","Los vehículos que llevan materiales peligrosos","Las camionetas pickup","Los taxis"],"h1":"Llevan letreros que muestran lo que transportan.","h2":"El manual de Kentucky dice que los vehículos que llevan materiales peligrosos deben detenerse en todos los cruces de tren, así que esté listo para parar detrás de ellos.","p":"Correcto. Vehículos con materiales peligrosos."},"ref":{"doc":"KY","page":63}},{"id":"ky-187","scope":"KY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kentucky, a vehicle with a flashing blue light comes up behind you. What must you do?","o":["Speed up to clear the way","Stop right where you are, even in an intersection","Drive to the right side of the road, clear of any intersection, and stop","Keep going at the same speed"],"h1":"Kentucky law names red or blue flashing lights and sirens.","h2":"In Kentucky, when a vehicle with a flashing red or blue light or a siren approaches, drive to the right side of the road, clear of any intersection, and stop until it passes.","p":"Right. Pull to the right, clear of the intersection, and stop."},"es":{"q":"En Kentucky, un vehículo con luz azul intermitente se acerca por detrás. ¿Qué debe hacer?","o":["Acelerar para abrir paso","Pararse donde está, aunque sea en una intersección","Orillarse al lado derecho de la vía, fuera de cualquier intersección, y detenerse","Seguir a la misma velocidad"],"h1":"La ley de Kentucky menciona luces intermitentes rojas o azules y sirenas.","h2":"En Kentucky, cuando se acerca un vehículo con luz roja o azul intermitente o con sirena, oríllese al lado derecho de la vía, fuera de cualquier intersección, y deténgase hasta que pase.","p":"Correcto. Orillarse a la derecha, fuera de la intersección, y detenerse."},"ref":{"doc":"KY","page":63}},{"id":"ky-188","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, police pull you over. What should you do with your hands while the officer walks up?","o":["Dig through the glove box for your papers","Hold your phone up to record","Wave them out the window","Keep them on the steering wheel and limit your movements"],"h1":"Avoid looking like you are hiding or searching for something.","h2":"The Kentucky manual says to keep your hands on the steering wheel and limit movements, and to tell the officer where your documents are before reaching for them.","p":"Right. Hands on the wheel."},"es":{"q":"En Kentucky, la policía lo detiene. ¿Qué debe hacer con sus manos mientras el oficial se acerca?","o":["Buscar sus papeles en la guantera","Levantar el teléfono para grabar","Sacarlas por la ventana","Dejarlas en el volante y moverse lo menos posible"],"h1":"Evite parecer que esconde o busca algo.","h2":"El manual de Kentucky dice que deje las manos en el volante y se mueva poco, y que le diga al oficial dónde están sus documentos antes de tomarlos.","p":"Correcto. Manos en el volante."},"ref":{"doc":"KY","page":64}},{"id":"ky-189","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Kentucky, an orange and red triangle on the back of a vehicle means it usually travels at less than what speed?","o":["10 mph","25 mph","45 mph","55 mph"],"h1":"It is the slow-moving vehicle sign used by farm and construction equipment.","h2":"In Kentucky, the orange and red slow-moving vehicle triangle means the vehicle travels at less than 25 mph.","p":"Right. Less than 25 mph."},"es":{"q":"En Kentucky, un triángulo anaranjado y rojo en la parte de atrás de un vehículo significa que normalmente va a menos de qué velocidad?","o":["10 mph","25 mph","45 mph","55 mph"],"h1":"Es la señal de vehículo lento que usan los equipos agrícolas y de construcción.","h2":"En Kentucky, el triángulo anaranjado y rojo de vehículo lento significa que el vehículo va a menos de 25 mph.","p":"Correcto. Menos de 25 mph."},"ref":{"doc":"KY","page":65}},{"id":"ky-190","scope":"KY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Kentucky, you come up behind a horse-drawn buggy. What should you avoid doing as you pass?","o":["Slowing down","Giving extra space","Honking or revving your engine","Watching for left turns"],"h1":"Loud noises can scare the horse.","h2":"In Kentucky, pass an animal-drawn vehicle with caution and do not honk or rev your engine, because it may scare the horse and cause a crash.","p":"Right. No honking or revving."},"es":{"q":"En Kentucky, alcanza a una carreta tirada por un caballo. ¿Qué debe evitar al rebasarla?","o":["Bajar la velocidad","Dar espacio extra","Tocar el claxon o acelerar el motor en vacío","Fijarse si va a dar vuelta a la izquierda"],"h1":"Los ruidos fuertes pueden asustar al caballo.","h2":"En Kentucky, rebase con cuidado a un vehículo tirado por animales y no toque el claxon ni acelere el motor, porque puede asustar al caballo y causar un choque.","p":"Correcto. Sin claxon ni acelerones."},"ref":{"doc":"KY","page":65}},{"id":"ky-191","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Kentucky, an ATV crosses a two-lane public highway. What is the rule?","o":["It may ride along the highway for up to 5 miles","It may cross at any angle","It may not cross at all","It must cross close to a 90-degree angle and not travel more than two-tenths of a mile on the road"],"h1":"The crossing must be short and as straight across as possible.","h2":"In Kentucky, an ATV may cross a two-lane public highway at close to a 90-degree angle and may not travel on it more than two-tenths of a mile.","p":"Right. Cross nearly straight across, no more than two-tenths of a mile."},"es":{"q":"En Kentucky, un vehículo todoterreno (ATV) cruza una carretera pública de dos carriles. ¿Cuál es la regla?","o":["Puede ir por la carretera hasta 5 millas","Puede cruzar en cualquier ángulo","No puede cruzar nunca","Debe cruzar casi en ángulo de 90 grados y no recorrer más de dos décimas de milla por la vía"],"h1":"El cruce debe ser corto y lo más derecho posible.","h2":"En Kentucky, un ATV puede cruzar una carretera pública de dos carriles casi en ángulo de 90 grados y no puede recorrer más de dos décimas de milla por ella.","p":"Correcto. Cruzar casi derecho y no más de dos décimas de milla."},"ref":{"doc":"KY","page":66}},{"id":"ky-192","scope":"KY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Kentucky, a 14-year-old wants to ride an ATV. What is required?","o":["Direct parental supervision and an approved helmet","A learner's permit","Nothing, if on public roads","A motorcycle license"],"h1":"Young riders need an adult and head protection.","h2":"In Kentucky, a person under 16 may operate an ATV only under direct parental supervision and while wearing approved protective headgear.","p":"Right. Parental supervision and a helmet."},"es":{"q":"En Kentucky, un joven de 14 años quiere manejar un ATV. ¿Qué se requiere?","o":["Supervisión directa de un padre y un casco aprobado","Un permiso de aprendizaje","Nada, si va por vías públicas","Una licencia de motocicleta"],"h1":"Los jóvenes necesitan a un adulto y protección para la cabeza.","h2":"En Kentucky, una persona menor de 16 años solo puede manejar un ATV con supervisión directa de su padre o madre y usando un casco aprobado.","p":"Correcto. Supervisión de un padre y casco."},"ref":{"doc":"KY","page":66}},{"id":"ky-193","scope":"KY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Kentucky, a funeral procession led by an escort with flashing lights is going through an intersection. What must you not do?","o":["Wait for it to pass","Pull over if directed by police","Drive your car between vehicles in the procession","Stay stopped at your light"],"h1":"Do not cut into the line.","h2":"In Kentucky, you must not drive between the vehicles of a funeral procession unless a police or safety officer allows it.","p":"Right. Never drive between procession vehicles."},"es":{"q":"En Kentucky, un cortejo fúnebre guiado por un vehículo escolta con luces intermitentes cruza una intersección. ¿Qué no debe hacer?","o":["Esperar a que pase","Orillarse si la policía lo indica","Meter su auto entre los vehículos del cortejo","Quedarse parado en su semáforo"],"h1":"No se meta en la fila.","h2":"En Kentucky, no debe meterse entre los vehículos de un cortejo fúnebre, salvo que un policía u oficial de seguridad lo permita.","p":"Correcto. Nunca se meta entre los vehículos del cortejo."},"ref":{"doc":"KY","page":67}},{"id":"ky-194","scope":"KY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Kentucky, where may you pass a funeral procession without being told to by an officer?","o":["On any city street","In a school zone","At an intersection","On a road outside city limits, or on an interstate or state parkway"],"h1":"Passing is limited to roads outside towns and to big highways.","h2":"In Kentucky, you may pass a funeral procession only when an officer directs you, or when it is outside city limits or on an interstate or state parkway.","p":"Right. Outside city limits, or on an interstate or parkway."},"es":{"q":"En Kentucky, ¿dónde puede rebasar un cortejo fúnebre sin que un oficial se lo indique?","o":["En cualquier calle de la ciudad","En una zona escolar","En una intersección","En una vía fuera de los límites de la ciudad, o en una interestatal o parkway estatal"],"h1":"Rebasar se permite solo fuera de las ciudades y en las vías grandes.","h2":"En Kentucky, puede rebasar un cortejo fúnebre solo si un oficial se lo indica, o si va fuera de los límites de la ciudad o por una interestatal o parkway estatal.","p":"Correcto. Fuera de la ciudad, o en interestatal o parkway."},"ref":{"doc":"KY","page":68}},{"id":"ky-195","scope":"KY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Kentucky, what is the possible penalty for breaking the funeral procession rules?","o":["A $250 fine or 90 days in jail","A warning only","A $10 fine","Loss of your license for life"],"h1":"It is the same fine as for not yielding to a blind pedestrian.","h2":"In Kentucky, violating the funeral procession law can bring a $250 fine or 90 days in jail.","p":"Right. $250 or 90 days."},"es":{"q":"En Kentucky, ¿cuál es la posible pena por no respetar las reglas de los cortejos fúnebres?","o":["Una multa de $250 o 90 días de cárcel","Solo una advertencia","Una multa de $10","Perder la licencia de por vida"],"h1":"Es la misma multa que por no ceder el paso a un peatón ciego.","h2":"En Kentucky, violar la ley de cortejos fúnebres puede costar una multa de $250 o 90 días de cárcel.","p":"Correcto. $250 o 90 días."},"ref":{"doc":"KY","page":68}},{"id":"ky-196","scope":"KY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Kentucky, two cars reach a single-lane rural bridge from opposite ends. Who generally goes first?","o":["The larger vehicle","The first driver to reach the bridge","The driver going uphill","The driver who honks first"],"h1":"Take turns, starting with whoever arrives first.","h2":"In Kentucky, at a narrow or single-lane bridge, drivers take turns, and generally the first driver to the bridge has the right-of-way.","p":"Right. The first to arrive goes first."},"es":{"q":"En Kentucky, dos autos llegan a un puente rural de un solo carril por lados opuestos. ¿Quién pasa primero, en general?","o":["El vehículo más grande","El primer conductor que llega al puente","El que va de subida","El que toca el claxon primero"],"h1":"Se turnan, empezando por quien llega primero.","h2":"En Kentucky, en un puente angosto o de un solo carril, los conductores se turnan, y en general el primero que llega al puente tiene el derecho de paso.","p":"Correcto. Pasa primero el que llega primero."},"ref":{"doc":"KY","page":68}},{"id":"ky-197","scope":"KY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Kentucky, what license do you need to drive an autocycle?","o":["A motorcycle license","A commercial license","A valid operator's license; no motorcycle license or endorsement is needed","A moped license"],"h1":"It is driven with a steering wheel and pedals, like a car.","h2":"In Kentucky, an autocycle driver does not need a motorcycle license or endorsement; a valid operator's license is enough, and no helmet is required.","p":"Right. A regular operator's license is enough."},"es":{"q":"En Kentucky, ¿qué licencia necesita para manejar un autociclo (autocycle)?","o":["Una licencia de motocicleta","Una licencia comercial","Una licencia de conductor válida; no se necesita licencia ni endoso de motocicleta","Una licencia de ciclomotor"],"h1":"Se maneja con volante y pedales, como un auto.","h2":"En Kentucky, quien maneja un autociclo no necesita licencia ni endoso de motocicleta; basta una licencia de conductor válida, y no se exige casco.","p":"Correcto. Basta la licencia normal de conductor."},"ref":{"doc":"KY","page":69}},{"id":"ky-198","scope":"KY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Kentucky manual, how should the cargo weight in a trailer be split?","o":["50 percent front, 50 percent back","40 percent front, 60 percent back","All of it at the very back","About 60 percent in the front and 40 percent in the back"],"h1":"Heavier in front reduces sway.","h2":"The Kentucky manual says about 60 percent of a trailer's cargo weight should go in the front, nearest the towing vehicle, and 40 percent in the back.","p":"Right. 60 percent front, 40 percent back."},"es":{"q":"Según el manual de Kentucky, ¿cómo debe repartirse el peso de la carga en un tráiler?","o":["50 por ciento adelante y 50 atrás","40 por ciento adelante y 60 atrás","Todo bien atrás","Más o menos 60 por ciento adelante y 40 atrás"],"h1":"Más peso adelante reduce el bamboleo.","h2":"El manual de Kentucky dice que más o menos el 60 por ciento del peso de la carga del tráiler debe ir adelante, cerca del vehículo que remolca, y el 40 por ciento atrás.","p":"Correcto. 60 por ciento adelante y 40 atrás."},"ref":{"doc":"KY","page":69}},{"id":"ky-199","scope":"KY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Kentucky, the trailer you are towing begins to sway. What does the manual say to do?","o":["Steer straight and slow down gradually without braking","Brake hard right away","Speed up to straighten it","Turn sharply to the shoulder"],"h1":"Never increase speed; ease off.","h2":"The Kentucky manual says that if a trailer sways or whips, steer straight and reduce speed gradually without applying the brakes, and never speed up.","p":"Right. Steer straight and slow gradually."},"es":{"q":"En Kentucky, el tráiler que remolca empieza a bambolearse. ¿Qué dice el manual que haga?","o":["Mantener el volante derecho y bajar la velocidad poco a poco sin frenar","Frenar fuerte enseguida","Acelerar para enderezarlo","Girar bruscamente hacia el acotamiento"],"h1":"Nunca acelere; suelte el acelerador.","h2":"El manual de Kentucky dice que si el tráiler se bambolea o coletea, mantenga el volante derecho y baje la velocidad poco a poco sin frenar, y nunca acelere.","p":"Correcto. Volante derecho y bajar la velocidad poco a poco."},"ref":{"doc":"KY","page":70}},{"id":"ky-200","scope":"KY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Kentucky manual, what is the highest recommended speed for most vehicle and trailer combinations?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"It is the same as the limit on most non-interstate state highways.","h2":"The Kentucky manual says the maximum recommended speed for most vehicle and trailer combinations is 55 mph, and never more than the posted limit.","p":"Right. 55 mph."},"es":{"q":"Según el manual de Kentucky, ¿cuál es la velocidad máxima recomendada para la mayoría de las combinaciones de vehículo y tráiler?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Es igual al límite en la mayoría de las carreteras estatales que no son interestatales.","h2":"El manual de Kentucky dice que la velocidad máxima recomendada para la mayoría de las combinaciones de vehículo y tráiler es de 55 mph, y nunca más que el límite indicado.","p":"Correcto. 55 mph."},"ref":{"doc":"KY","page":70}},{"id":"la-001","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Louisiana you can get a learner's permit at 15, after a driver education course and the knowledge and vision tests.","p":"Right. The Louisiana learner's permit starts at 15."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Luisiana usted puede obtener el permiso de aprendiz a los 15 años, después de un curso de manejo y los exámenes teórico y de la vista.","p":"Correcto. El permiso de aprendiz en Luisiana empieza a los 15."},"zh":{"q":"在 Louisiana，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比中级驾照早一年。","h2":"在 Louisiana，上完驾驶课并通过笔试和视力检查后，你 15 岁就可以拿到学习驾照。","p":"对。Louisiana 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Louisiana, tuổi nhỏ nhất để có giấy phép học lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước bằng lái trung gian.","h2":"Ở Louisiana, bạn có thể có giấy phép học lái lúc 15 tuổi, sau khi học khóa giáo dục lái xe và thi kiến thức và thị lực.","p":"Đúng. Giấy phép học lái ở Louisiana bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Louisiana, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Sa Louisiana, puwede kang kumuha ng learner's permit sa edad na 15, pagkatapos ng kurso sa driver education at ng knowledge test at vision test.","p":"Tama. Nagsisimula ang learner's permit ng Louisiana sa edad na 15."},"ar":{"q":"في Louisiana، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو قبل الرخصة المتوسطة بسنة واحدة.","h2":"في Louisiana يمكنك الحصول على تصريح تعلّم القيادة في سن 15، بعد دورة تعليم القيادة واختبار المعرفة واختبار النظر.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Louisiana في سن 15."},"ref":{"doc":"LA","page":7}},{"id":"la-002","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how long is the approved driver education course a teen must finish before the learner's permit?","o":["8 hours","16 hours","24 hours","38 hours"],"h1":"It is a little under 40 hours.","h2":"In Louisiana a teen must finish a 38-hour driver education course before the learner's permit: 30 hours in class and 8 hours behind the wheel.","p":"Right. The course is 38 hours."},"es":{"q":"En Luisiana, ¿cuántas horas dura el curso de manejo aprobado que un joven debe terminar antes del permiso de aprendiz?","o":["8 horas","16 horas","24 horas","38 horas"],"h1":"Son un poco menos de 40 horas.","h2":"En Luisiana un adolescente debe terminar un curso de manejo de 38 horas antes del permiso de aprendiz: 30 horas en clase y 8 horas al volante.","p":"Correcto. El curso es de 38 horas."},"zh":{"q":"在 Louisiana，青少年拿学习驾照前必须完成的、经过批准的驾驶课有多长？","o":["8 小时","16 小时","24 小时","38 小时"],"h1":"比 40 小时少一点。","h2":"在 Louisiana，青少年拿学习驾照前必须完成 38 小时的驾驶课：30 小时课堂学习，8 小时实际开车。","p":"对。这门课是 38 小时。"},"vi":{"q":"Ở Louisiana, khóa giáo dục lái xe được chấp thuận mà thiếu niên phải học xong trước khi có giấy phép học lái dài bao nhiêu giờ?","o":["8 giờ","16 giờ","24 giờ","38 giờ"],"h1":"Nó ít hơn 40 giờ một chút.","h2":"Ở Louisiana, thiếu niên phải học xong khóa giáo dục lái xe 38 giờ trước khi có giấy phép học lái: 30 giờ trong lớp và 8 giờ lái xe thật.","p":"Đúng. Khóa học dài 38 giờ."},"tl":{"q":"Sa Louisiana, gaano katagal ang aprubadong kurso sa driver education na dapat tapusin ng isang tinedyer bago ang learner's permit?","o":["8 oras","16 oras","24 oras","38 oras"],"h1":"Kaunti itong kulang sa 40 oras.","h2":"Sa Louisiana, dapat tapusin ng tinedyer ang 38 oras na kurso sa driver education bago ang learner's permit: 30 oras sa klase at 8 oras sa pagmamaneho.","p":"Tama. 38 oras ang kurso."},"ar":{"q":"في Louisiana، كم ساعة مدة دورة تعليم القيادة المعتمدة التي يجب أن يكملها المراهق قبل تصريح تعلّم القيادة؟","o":["8 ساعات","16 ساعة","24 ساعة","38 ساعة"],"h1":"هي أقل قليلًا من 40 ساعة.","h2":"في Louisiana يجب أن يكمل المراهق دورة تعليم قيادة مدتها 38 ساعة قبل تصريح تعلّم القيادة: 30 ساعة في الصف و8 ساعات خلف المقود.","p":"صحيح. مدة الدورة 38 ساعة."},"ref":{"doc":"LA","page":7}},{"id":"la-003","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how long must you hold a learner's permit before you can get an intermediate license?","o":["At least 180 days","At least 30 days","At least 90 days","At least two years"],"h1":"It is about six months.","h2":"In Louisiana you must hold the learner's permit for at least 180 days before you can get an intermediate license.","p":"Right. Hold the permit at least 180 days."},"es":{"q":"En Luisiana, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Por lo menos 180 días","Por lo menos 30 días","Por lo menos 90 días","Por lo menos dos años"],"h1":"Son unos seis meses.","h2":"En Luisiana usted debe tener el permiso de aprendiz por lo menos 180 días antes de obtener la licencia intermedia.","p":"Correcto. Debe tener el permiso por lo menos 180 días."},"zh":{"q":"在 Louisiana，你必须持有学习驾照多久，才能拿到中级驾照（intermediate license）？","o":["至少 180 天","至少 30 天","至少 90 天","至少两年"],"h1":"大约是六个月。","h2":"在 Louisiana，你必须持有学习驾照至少 180 天，才能拿到中级驾照。","p":"对。学习驾照至少持有 180 天。"},"vi":{"q":"Ở Louisiana, bạn phải giữ giấy phép học lái bao lâu trước khi có thể có bằng lái trung gian (intermediate license)?","o":["Ít nhất 180 ngày","Ít nhất 30 ngày","Ít nhất 90 ngày","Ít nhất hai năm"],"h1":"Khoảng sáu tháng.","h2":"Ở Louisiana, bạn phải giữ giấy phép học lái ít nhất 180 ngày trước khi có thể có bằng lái trung gian.","p":"Đúng. Giữ giấy phép ít nhất 180 ngày."},"tl":{"q":"Sa Louisiana, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng intermediate license?","o":["Hindi bababa sa 180 araw","Hindi bababa sa 30 araw","Hindi bababa sa 90 araw","Hindi bababa sa dalawang taon"],"h1":"Mga anim na buwan ito.","h2":"Sa Louisiana, dapat mong hawak ang learner's permit nang hindi bababa sa 180 araw bago ka makakuha ng intermediate license.","p":"Tama. Hawakan ang permit nang hindi bababa sa 180 araw."},"ar":{"q":"في Louisiana، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل أن تحصل على الرخصة المتوسطة (intermediate license)؟","o":["180 يومًا على الأقل","30 يومًا على الأقل","90 يومًا على الأقل","سنتان على الأقل"],"h1":"هي حوالي ستة أشهر.","h2":"في Louisiana يجب أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل قبل أن تحصل على الرخصة المتوسطة.","p":"صحيح. احمل التصريح 180 يومًا على الأقل."},"ref":{"doc":"LA","page":7}},{"id":"la-004","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how old must a licensed adult be to supervise a driver with a learner's permit?","o":["At least 18","At least 25","At least 21","At least 30"],"h1":"It is the legal drinking age.","h2":"In Louisiana a learner must drive with a licensed adult who is at least 21, or with a licensed brother or sister who is at least 18.","p":"Right. A supervising adult must be 21 or older."},"es":{"q":"En Luisiana, ¿qué edad debe tener un adulto con licencia para supervisar a un conductor con permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad legal para tomar alcohol.","h2":"En Luisiana un aprendiz debe manejar con un adulto con licencia de por lo menos 21 años, o con un hermano o hermana con licencia de por lo menos 18.","p":"Correcto. El adulto que supervisa debe tener 21 años o más."},"zh":{"q":"在 Louisiana，陪同持学习驾照的司机开车、有驾照的成年人必须几岁？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 30 岁"],"h1":"是法定可以喝酒的年龄。","h2":"在 Louisiana，学习驾驶的人必须和一位至少 21 岁、有驾照的成年人一起开车，或者和一位至少 18 岁、有驾照的兄弟姐妹一起开车。","p":"对。陪同的成年人必须 21 岁或以上。"},"vi":{"q":"Ở Louisiana, người lớn có bằng lái phải bao nhiêu tuổi để giám sát người lái có giấy phép học lái?","o":["Ít nhất 18","Ít nhất 25","Ít nhất 21","Ít nhất 30"],"h1":"Đó là tuổi được phép uống rượu theo luật.","h2":"Ở Louisiana, người học lái phải lái cùng một người lớn có bằng lái từ 21 tuổi trở lên, hoặc cùng anh chị em có bằng lái từ 18 tuổi trở lên.","p":"Đúng. Người lớn giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Louisiana, ilang taon dapat ang isang adult na may lisensya para bantayan ang driver na may learner's permit?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 30"],"h1":"Ito ang legal na edad para uminom ng alak.","h2":"Sa Louisiana, dapat magmaneho ang learner kasama ang adult na may lisensya na hindi bababa sa 21 taong gulang, o kasama ang kapatid na may lisensya na hindi bababa sa 18 taong gulang.","p":"Tama. Dapat 21 o mas matanda ang adult na nagbabantay."},"ar":{"q":"في Louisiana، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ليشرف على سائق يحمل تصريح تعلّم القيادة؟","o":["18 على الأقل","25 على الأقل","21 على الأقل","30 على الأقل"],"h1":"هو السن القانوني لشرب الكحول.","h2":"في Louisiana يجب أن يقود المتعلّم مع شخص بالغ يحمل رخصة وعمره 21 سنة على الأقل، أو مع أخ أو أخت يحمل رخصة وعمره 18 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ المشرف 21 سنة أو أكثر."},"ref":{"doc":"LA","page":7}},{"id":"la-005","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which family member may supervise a learner even though he or she is younger than 21?","o":["A licensed cousin who is 16","A licensed brother or sister who is at least 18","A grandparent without a license","Any sibling of any age"],"h1":"This person has a license and is an adult, but is not yet 21.","h2":"In Louisiana a licensed brother or sister who is at least 18 may supervise a learner's permit driver.","p":"Right. A licensed sibling 18 or older may ride with you."},"es":{"q":"En Luisiana, ¿qué familiar puede supervisar a un aprendiz aunque tenga menos de 21 años?","o":["Un primo con licencia de 16 años","Un hermano o hermana con licencia de por lo menos 18 años","Un abuelo sin licencia","Cualquier hermano de cualquier edad"],"h1":"Esta persona tiene licencia y es adulta, pero todavía no tiene 21.","h2":"En Luisiana un hermano o hermana con licencia de por lo menos 18 años puede supervisar a un conductor con permiso de aprendiz.","p":"Correcto. Un hermano con licencia de 18 años o más puede acompañarle."},"zh":{"q":"在 Louisiana，哪位家人虽然不到 21 岁，也可以陪同学习驾驶的人？","o":["16 岁、有驾照的表兄弟姐妹","至少 18 岁、有驾照的兄弟姐妹","没有驾照的祖父母","任何年龄的兄弟姐妹"],"h1":"这个人有驾照，也是成年人，但还不到 21 岁。","h2":"在 Louisiana，至少 18 岁、有驾照的兄弟姐妹可以陪同持学习驾照的司机。","p":"对。18 岁或以上、有驾照的兄弟姐妹可以和你一起坐车。"},"vi":{"q":"Ở Louisiana, người thân nào trong gia đình được giám sát người học lái dù chưa đủ 21 tuổi?","o":["Anh chị em họ 16 tuổi có bằng lái","Anh chị em ruột có bằng lái, ít nhất 18 tuổi","Ông bà không có bằng lái","Bất kỳ anh chị em nào ở bất kỳ tuổi nào"],"h1":"Người này có bằng lái và là người lớn, nhưng chưa đủ 21 tuổi.","h2":"Ở Louisiana, anh chị em ruột có bằng lái và ít nhất 18 tuổi được giám sát người lái có giấy phép học lái.","p":"Đúng. Anh chị em có bằng lái từ 18 tuổi trở lên có thể ngồi cùng bạn."},"tl":{"q":"Sa Louisiana, sinong kapamilya ang puwedeng magbantay sa learner kahit wala pa siyang 21 taong gulang?","o":["Pinsan na may lisensya na 16 taong gulang","Kapatid na may lisensya na hindi bababa sa 18 taong gulang","Lolo o lola na walang lisensya","Kahit sinong kapatid sa kahit anong edad"],"h1":"May lisensya ang taong ito at adult na, pero wala pang 21.","h2":"Sa Louisiana, puwedeng magbantay sa driver na may learner's permit ang kapatid na may lisensya at hindi bababa sa 18 taong gulang.","p":"Tama. Puwedeng sumama sa iyo ang kapatid na may lisensya na 18 o mas matanda."},"ar":{"q":"في Louisiana، أي فرد من العائلة يمكنه الإشراف على المتعلّم مع أن عمره أقل من 21 سنة؟","o":["ابن عم أو خال يحمل رخصة وعمره 16","أخ أو أخت يحمل رخصة وعمره 18 سنة على الأقل","جد أو جدة بلا رخصة","أي أخ أو أخت بأي عمر"],"h1":"هذا الشخص يحمل رخصة وهو بالغ، لكنه لم يبلغ 21 بعد.","h2":"في Louisiana يمكن للأخ أو الأخت الذي يحمل رخصة وعمره 18 سنة على الأقل أن يشرف على سائق يحمل تصريح تعلّم القيادة.","p":"صحيح. يمكن لأخ أو أخت يحمل رخصة وعمره 18 أو أكثر أن يركب معك."},"ref":{"doc":"LA","page":7}},{"id":"la-006","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how many hours of supervised driving must a learner log before the intermediate license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"It is the same total many states use, half of one hundred.","h2":"In Louisiana a learner must log 50 hours of supervised driving before getting an intermediate license.","p":"Right. 50 supervised hours."},"es":{"q":"En Luisiana, ¿cuántas horas de manejo supervisado debe registrar un aprendiz antes de la licencia intermedia?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Es el mismo total que usan muchos estados, la mitad de cien.","h2":"En Luisiana un aprendiz debe registrar 50 horas de manejo supervisado antes de obtener la licencia intermedia.","p":"Correcto. 50 horas supervisadas."},"zh":{"q":"在 Louisiana，学习驾驶的人拿中级驾照前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"和很多州用的总数一样，是一百的一半。","h2":"在 Louisiana，学习驾驶的人拿中级驾照前，必须记录 50 小时有人陪同的驾驶。","p":"对。50 小时有人陪同的驾驶。"},"vi":{"q":"Ở Louisiana, người học lái phải ghi lại bao nhiêu giờ lái xe có giám sát trước khi có bằng lái trung gian?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Đó là con số nhiều tiểu bang dùng, một nửa của một trăm.","h2":"Ở Louisiana, người học lái phải ghi lại 50 giờ lái xe có giám sát trước khi có bằng lái trung gian.","p":"Đúng. 50 giờ có giám sát."},"tl":{"q":"Sa Louisiana, ilang oras ng binabantayang pagmamaneho ang dapat itala ng learner bago ang intermediate license?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Ito ang parehong kabuuan na ginagamit ng maraming estado, kalahati ng isandaan.","h2":"Sa Louisiana, dapat magtala ang learner ng 50 oras ng binabantayang pagmamaneho bago makakuha ng intermediate license.","p":"Tama. 50 oras na may bantay."},"ar":{"q":"في Louisiana، كم ساعة من القيادة تحت الإشراف يجب أن يسجّلها المتعلّم قبل الرخصة المتوسطة؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"هو نفس المجموع الذي تستخدمه ولايات كثيرة، نصف المئة.","h2":"في Louisiana يجب أن يسجّل المتعلّم 50 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 50 ساعة تحت الإشراف."},"ref":{"doc":"LA","page":7}},{"id":"la-007","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how many of the supervised practice hours must be at night?","o":["15 hours","5 hours","10 hours","25 hours"],"h1":"It is a little less than one third of the 50 hours.","h2":"In Louisiana 15 of the 50 supervised practice hours must be driven at night.","p":"Right. 15 of the hours are at night."},"es":{"q":"En Luisiana, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["15 horas","5 horas","10 horas","25 horas"],"h1":"Es un poco menos de un tercio de las 50 horas.","h2":"En Luisiana 15 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. 15 de las horas son de noche."},"zh":{"q":"在 Louisiana，有人陪同的练习时间中，必须有多少小时是在夜间？","o":["15 小时","5 小时","10 小时","25 小时"],"h1":"比 50 小时的三分之一少一点。","h2":"在 Louisiana，50 小时有人陪同的练习中，有 15 小时必须在夜间开。","p":"对。其中 15 小时是在夜间。"},"vi":{"q":"Ở Louisiana, bao nhiêu giờ trong số giờ tập lái có giám sát phải lái vào ban đêm?","o":["15 giờ","5 giờ","10 giờ","25 giờ"],"h1":"Nó ít hơn một phần ba của 50 giờ một chút.","h2":"Ở Louisiana, 15 giờ trong 50 giờ tập lái có giám sát phải lái vào ban đêm.","p":"Đúng. 15 giờ là vào ban đêm."},"tl":{"q":"Sa Louisiana, ilan sa mga oras ng binabantayang pagsasanay ang dapat sa gabi?","o":["15 oras","5 oras","10 oras","25 oras"],"h1":"Kaunti itong kulang sa isang katlo ng 50 oras.","h2":"Sa Louisiana, 15 sa 50 oras ng binabantayang pagsasanay ang dapat imaneho sa gabi.","p":"Tama. 15 sa mga oras ay sa gabi."},"ar":{"q":"في Louisiana، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["15 ساعة","5 ساعات","10 ساعات","25 ساعة"],"h1":"هي أقل قليلًا من ثلث الـ 50 ساعة.","h2":"في Louisiana يجب أن تكون 15 ساعة من الـ 50 ساعة من التدريب تحت الإشراف قيادة في الليل.","p":"صحيح. 15 ساعة منها في الليل."},"ref":{"doc":"LA","page":7}},{"id":"la-008","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, who may type or read a text message on a phone held in the hand while driving?","o":["Drivers 18 and older","Drivers on a highway only","No driver, of any age","Drivers on an empty road"],"h1":"The rule is the same for every age.","h2":"In Louisiana no driver of any age may write, send or read a text message on a hand-held phone while driving.","p":"Right. No driver may text while driving."},"es":{"q":"En Luisiana, ¿quién puede escribir o leer un mensaje de texto en un teléfono sostenido en la mano mientras maneja?","o":["Los conductores de 18 años o más","Solo los conductores en la carretera","Ningún conductor, de ninguna edad","Los conductores en una calle vacía"],"h1":"La regla es igual para todas las edades.","h2":"En Luisiana ningún conductor, de ninguna edad, puede escribir, enviar ni leer un mensaje de texto en un teléfono en la mano mientras maneja.","p":"Correcto. Ningún conductor puede enviar textos mientras maneja."},"zh":{"q":"在 Louisiana，谁可以在开车时用手拿着手机打字或看短信？","o":["18 岁及以上的司机","只有在公路上的司机","任何年龄的司机都不可以","在空路上的司机"],"h1":"这条规定对所有年龄都一样。","h2":"在 Louisiana，任何年龄的司机在开车时都不可以用手拿着的手机写、发或看短信。","p":"对。任何司机开车时都不可以发短信。"},"vi":{"q":"Ở Louisiana, ai được gõ hoặc đọc tin nhắn trên điện thoại cầm trên tay khi đang lái xe?","o":["Tài xế từ 18 tuổi trở lên","Chỉ tài xế trên xa lộ","Không tài xế nào, ở bất kỳ tuổi nào","Tài xế trên đường vắng"],"h1":"Quy định này giống nhau cho mọi lứa tuổi.","h2":"Ở Louisiana, không tài xế nào, ở bất kỳ tuổi nào, được viết, gửi hoặc đọc tin nhắn trên điện thoại cầm tay khi đang lái xe.","p":"Đúng. Không tài xế nào được nhắn tin khi đang lái xe."},"tl":{"q":"Sa Louisiana, sino ang puwedeng mag-type o magbasa ng text message sa teleponong hawak sa kamay habang nagmamaneho?","o":["Mga driver na 18 taong gulang pataas","Mga driver sa highway lang","Walang driver, anuman ang edad","Mga driver sa kalsadang walang ibang sasakyan"],"h1":"Pareho ang patakaran para sa lahat ng edad.","h2":"Sa Louisiana, walang driver, anuman ang edad, ang puwedeng sumulat, magpadala o magbasa ng text message sa teleponong hawak sa kamay habang nagmamaneho.","p":"Tama. Walang driver ang puwedeng mag-text habang nagmamaneho."},"ar":{"q":"في Louisiana، مَن يُسمح له بكتابة رسالة نصية أو قراءتها على هاتف في يده أثناء القيادة؟","o":["السائقون في سن 18 فما فوق","السائقون على الطريق السريع فقط","لا أحد من السائقين، في أي عمر","السائقون على طريق فارغ"],"h1":"القاعدة واحدة لكل الأعمار.","h2":"في Louisiana يجب ألّا يكتب أي سائق، في أي عمر، رسالة نصية أو يرسلها أو يقرأها على هاتف في يده أثناء القيادة.","p":"صحيح. يجب ألّا يرسل أي سائق رسائل نصية أثناء القيادة."},"ref":{"doc":"LA","page":78}},{"id":"la-009","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, during which hours may an intermediate license holder not drive without a qualified adult?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","Midnight to 6 a.m.","1 a.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"In Louisiana an intermediate license holder may not drive from 11 p.m. to 5 a.m. unless a qualified licensed adult is in the car.","p":"Right. The restricted hours are 11 p.m. to 5 a.m."},"es":{"q":"En Luisiana, ¿en qué horario no puede manejar sin un adulto calificado quien tiene licencia intermedia?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Luisiana quien tiene licencia intermedia no puede manejar de 11 p.m. a 5 a.m. salvo que vaya en el carro un adulto con licencia calificado.","p":"Correcto. El horario restringido es de 11 p.m. a 5 a.m."},"zh":{"q":"在 Louisiana，持中级驾照的人在哪些时间，没有合格的成年人陪同就不能开车？","o":["晚上 9 点到早上 6 点","晚上 11 点到早上 5 点","午夜到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"它从午夜前一个小时开始。","h2":"在 Louisiana，持中级驾照的人在晚上 11 点到早上 5 点不能开车，除非车上有一位合格、有驾照的成年人。","p":"对。限制时间是晚上 11 点到早上 5 点。"},"vi":{"q":"Ở Louisiana, người có bằng lái trung gian không được lái xe mà không có người lớn đủ điều kiện trong những giờ nào?","o":["9 giờ tối đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Nó bắt đầu một giờ trước nửa đêm.","h2":"Ở Louisiana, người có bằng lái trung gian không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có một người lớn đủ điều kiện có bằng lái ngồi trong xe.","p":"Đúng. Giờ bị hạn chế là 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Louisiana, sa anong mga oras hindi puwedeng magmaneho ang may intermediate license nang walang kwalipikadong adult?","o":["9 p.m. hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Louisiana, hindi puwedeng magmaneho ang may intermediate license mula 11 p.m. hanggang 5 a.m. maliban kung may kwalipikadong adult na may lisensya sa loob ng sasakyan.","p":"Tama. Ang bawal na oras ay 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Louisiana، في أي ساعات لا يُسمح لحامل الرخصة المتوسطة بالقيادة دون شخص بالغ مؤهّل؟","o":["من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة.","h2":"في Louisiana لا يُسمح لحامل الرخصة المتوسطة بالقيادة من 11 مساءً إلى 5 صباحًا إلا إذا كان في السيارة شخص بالغ مؤهّل يحمل رخصة.","p":"صحيح. الساعات الممنوعة من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"LA","page":7}},{"id":"la-010","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, who may ride with an intermediate license holder so the teen may drive between 11 p.m. and 5 a.m.?","o":["Any friend over 16","A passenger with a permit","No one; driving at those hours is never allowed","A licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older"],"h1":"It is the same kind of person who may supervise a learner.","h2":"In Louisiana an intermediate driver may drive between 11 p.m. and 5 a.m. with a licensed parent or guardian, a licensed adult 21 or older, or a licensed sibling 18 or older.","p":"Right. A qualified licensed adult makes night driving allowed."},"es":{"q":"En Luisiana, ¿quién debe ir con un conductor con licencia intermedia para que pueda manejar entre 11 p.m. y 5 a.m.?","o":["Cualquier amigo mayor de 16","Un pasajero con permiso","Nadie; nunca se permite manejar a esas horas","Su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más"],"h1":"Es el mismo tipo de persona que puede supervisar a un aprendiz.","h2":"En Luisiana un conductor con licencia intermedia puede manejar entre 11 p.m. y 5 a.m. con su padre, madre o tutor con licencia, un adulto con licencia de 21 años o más, o un hermano con licencia de 18 años o más.","p":"Correcto. Un adulto calificado con licencia permite manejar de noche."},"zh":{"q":"在 Louisiana，谁和持中级驾照的青少年一起坐车，青少年就可以在晚上 11 点到早上 5 点之间开车？","o":["任何 16 岁以上的朋友","持学习驾照的乘客","没有人；这些时间永远不能开车","有驾照的父母或监护人、21 岁或以上有驾照的成年人，或 18 岁或以上有驾照的兄弟姐妹"],"h1":"和可以陪同学习驾驶的人是同一类人。","h2":"在 Louisiana，持中级驾照的司机可以在晚上 11 点到早上 5 点之间开车，只要和有驾照的父母或监护人、21 岁或以上有驾照的成年人，或 18 岁或以上有驾照的兄弟姐妹一起。","p":"对。有合格、有驾照的成年人在车上，就可以在夜间开车。"},"vi":{"q":"Ở Louisiana, ai có thể ngồi cùng người có bằng lái trung gian để thiếu niên được lái xe từ 11 giờ tối đến 5 giờ sáng?","o":["Bất kỳ người bạn nào trên 16 tuổi","Một hành khách có giấy phép học lái","Không ai; lái vào những giờ đó không bao giờ được phép","Cha mẹ hoặc người giám hộ có bằng lái, người lớn có bằng lái từ 21 tuổi trở lên, hoặc anh chị em có bằng lái từ 18 tuổi trở lên"],"h1":"Đó là cùng loại người có thể giám sát người học lái.","h2":"Ở Louisiana, người lái có bằng trung gian được lái từ 11 giờ tối đến 5 giờ sáng nếu có cha mẹ hoặc người giám hộ có bằng lái, người lớn có bằng lái từ 21 tuổi trở lên, hoặc anh chị em có bằng lái từ 18 tuổi trở lên.","p":"Đúng. Có người lớn đủ điều kiện có bằng lái thì được lái ban đêm."},"tl":{"q":"Sa Louisiana, sino ang puwedeng sumakay kasama ng may intermediate license para makapagmaneho ang tinedyer sa pagitan ng 11 p.m. at 5 a.m.?","o":["Kahit sinong kaibigan na lampas 16","Pasaherong may permit","Wala; hindi kailanman puwedeng magmaneho sa mga oras na iyon","Magulang o tagapag-alaga na may lisensya, adult na may lisensya na 21 pataas, o kapatid na may lisensya na 18 pataas"],"h1":"Ito ang parehong uri ng tao na puwedeng magbantay sa learner.","h2":"Sa Louisiana, puwedeng magmaneho ang intermediate driver sa pagitan ng 11 p.m. at 5 a.m. kung kasama ang magulang o tagapag-alaga na may lisensya, adult na may lisensya na 21 pataas, o kapatid na may lisensya na 18 pataas.","p":"Tama. Kapag may kwalipikadong adult na may lisensya, puwede ang pagmamaneho sa gabi."},"ar":{"q":"في Louisiana، من يمكنه أن يركب مع حامل الرخصة المتوسطة ليُسمح للمراهق بالقيادة بين 11 مساءً و5 صباحًا؟","o":["أي صديق عمره فوق 16","راكب يحمل تصريحًا","لا أحد؛ القيادة في هذه الساعات ممنوعة دائمًا","أحد الوالدين أو وليّ أمر يحمل رخصة، أو بالغ يحمل رخصة وعمره 21 أو أكثر، أو أخ أو أخت يحمل رخصة وعمره 18 أو أكثر"],"h1":"هو نفس نوع الشخص الذي يمكنه الإشراف على المتعلّم.","h2":"في Louisiana يُسمح لسائق الرخصة المتوسطة بالقيادة بين 11 مساءً و5 صباحًا مع أحد الوالدين أو وليّ أمر يحمل رخصة، أو بالغ يحمل رخصة وعمره 21 أو أكثر، أو أخ أو أخت يحمل رخصة وعمره 18 أو أكثر.","p":"صحيح. وجود بالغ مؤهّل يحمل رخصة يجعل القيادة الليلية مسموحة."},"ref":{"doc":"LA","page":7}},{"id":"la-011","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, between 6 p.m. and 5 a.m., how many passengers under 21 who are not immediate family may an intermediate driver carry?","o":["No more than one","No more than three","Any number","No more than two"],"h1":"The limit applies in the evening and at night.","h2":"In Louisiana an intermediate driver may carry no more than one passenger under 21, not counting immediate family, between 6 p.m. and 5 a.m.","p":"Right. Only one young passenger in the evening and at night."},"es":{"q":"En Luisiana, entre las 6 p.m. y las 5 a.m., ¿cuántos pasajeros menores de 21 que no son familia inmediata puede llevar un conductor con licencia intermedia?","o":["No más de uno","No más de tres","Cualquier cantidad","No más de dos"],"h1":"El límite se aplica en la tarde y de noche.","h2":"En Luisiana un conductor con licencia intermedia no puede llevar más de un pasajero menor de 21, sin contar la familia inmediata, entre las 6 p.m. y las 5 a.m.","p":"Correcto. Solo un pasajero joven en la tarde y de noche."},"zh":{"q":"在 Louisiana，在晚上 6 点到早上 5 点之间，持中级驾照的司机可以载几个不是直系亲属、21 岁以下的乘客？","o":["最多一个","最多三个","多少个都可以","最多两个"],"h1":"这个限制适用于傍晚和夜间。","h2":"在 Louisiana，在晚上 6 点到早上 5 点之间，持中级驾照的司机最多只能载一个 21 岁以下的乘客，直系亲属不算在内。","p":"对。傍晚和夜间只能载一个年轻乘客。"},"vi":{"q":"Ở Louisiana, từ 6 giờ tối đến 5 giờ sáng, người lái có bằng trung gian được chở bao nhiêu hành khách dưới 21 tuổi không phải người nhà trực hệ?","o":["Không quá một người","Không quá ba người","Bao nhiêu cũng được","Không quá hai người"],"h1":"Giới hạn này áp dụng vào buổi tối và ban đêm.","h2":"Ở Louisiana, từ 6 giờ tối đến 5 giờ sáng, người lái có bằng trung gian được chở không quá một hành khách dưới 21 tuổi, không tính người nhà trực hệ.","p":"Đúng. Chỉ một hành khách trẻ vào buổi tối và ban đêm."},"tl":{"q":"Sa Louisiana, mula 6 p.m. hanggang 5 a.m., ilang pasaherong wala pang 21 na hindi malapit na kapamilya ang puwedeng isakay ng intermediate driver?","o":["Hindi hihigit sa isa","Hindi hihigit sa tatlo","Kahit ilan","Hindi hihigit sa dalawa"],"h1":"Ang limitasyon ay para sa gabi at hatinggabi.","h2":"Sa Louisiana, mula 6 p.m. hanggang 5 a.m., puwedeng magsakay ang intermediate driver ng hindi hihigit sa isang pasaherong wala pang 21, hindi kasama ang malapit na kapamilya.","p":"Tama. Isang batang pasahero lang sa gabi."},"ar":{"q":"في Louisiana، بين 6 مساءً و5 صباحًا، كم راكبًا عمره أقل من 21 وليس من العائلة المباشرة يمكن لسائق الرخصة المتوسطة أن ينقله؟","o":["راكب واحد على الأكثر","ثلاثة ركاب على الأكثر","أي عدد","راكبان على الأكثر"],"h1":"الحد يُطبّق في المساء وفي الليل.","h2":"في Louisiana يمكن لسائق الرخصة المتوسطة أن ينقل راكبًا واحدًا على الأكثر عمره أقل من 21، دون حساب العائلة المباشرة، بين 6 مساءً و5 صباحًا.","p":"صحيح. راكب صغير واحد فقط في المساء وفي الليل."},"ref":{"doc":"LA","page":7}},{"id":"la-012","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, at what age can a driver move up to a full Class E license?","o":["16","18","17","21"],"h1":"It is one year after the intermediate license.","h2":"In Louisiana a driver can get a full Class E license at 17.","p":"Right. The full Class E license comes at 17."},"es":{"q":"En Luisiana, ¿a qué edad puede un conductor pasar a la licencia completa Clase E?","o":["16","18","17","21"],"h1":"Es un año después de la licencia intermedia.","h2":"En Luisiana un conductor puede obtener la licencia completa Clase E a los 17 años.","p":"Correcto. La licencia completa Clase E llega a los 17."},"zh":{"q":"在 Louisiana，司机几岁可以升级到正式的 Class E 驾照？","o":["16 岁","18 岁","17 岁","21 岁"],"h1":"是在拿到中级驾照一年以后。","h2":"在 Louisiana，司机 17 岁就可以拿到正式的 Class E 驾照。","p":"对。正式的 Class E 驾照在 17 岁。"},"vi":{"q":"Ở Louisiana, người lái được lên bằng lái đầy đủ hạng E (Class E) lúc mấy tuổi?","o":["16","18","17","21"],"h1":"Đó là một năm sau bằng lái trung gian.","h2":"Ở Louisiana, người lái có thể có bằng lái đầy đủ hạng E lúc 17 tuổi.","p":"Đúng. Bằng lái đầy đủ hạng E có lúc 17 tuổi."},"tl":{"q":"Sa Louisiana, sa anong edad puwedeng umakyat ang driver sa buong Class E license?","o":["16","18","17","21"],"h1":"Isang taon ito pagkatapos ng intermediate license.","h2":"Sa Louisiana, puwedeng makakuha ang driver ng buong Class E license sa edad na 17.","p":"Tama. Ang buong Class E license ay sa edad na 17."},"ar":{"q":"في Louisiana، في أي عمر يمكن للسائق أن ينتقل إلى رخصة كاملة من الفئة E (Class E)؟","o":["16","18","17","21"],"h1":"هو بعد الرخصة المتوسطة بسنة واحدة.","h2":"في Louisiana يمكن للسائق أن يحصل على رخصة كاملة من الفئة E في سن 17.","p":"صحيح. الرخصة الكاملة من الفئة E تأتي في سن 17."},"ref":{"doc":"LA","page":7}},{"id":"la-013","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which record must a learner have to move up to an intermediate license?","o":["At least one safe-driving award","No at-fault crashes and no moving violations while on the permit","A perfect score on the knowledge test","At least two years with the permit"],"h1":"Think about what happened on the road during the permit.","h2":"In Louisiana a learner needs no at-fault crashes and no moving violations on the permit to get an intermediate license.","p":"Right. A clean permit record is required."},"es":{"q":"En Luisiana, ¿qué historial debe tener un aprendiz para pasar a la licencia intermedia?","o":["Por lo menos un premio de manejo seguro","Ningún choque por su culpa y ninguna infracción de tránsito con el permiso","Una calificación perfecta en el examen teórico","Por lo menos dos años con el permiso"],"h1":"Piense en lo que pasó en la carretera durante el permiso.","h2":"En Luisiana un aprendiz no debe tener choques por su culpa ni infracciones de tránsito con el permiso para obtener la licencia intermedia.","p":"Correcto. Se requiere un historial limpio con el permiso."},"zh":{"q":"在 Louisiana，学习驾驶的人必须有什么样的记录，才能升级到中级驾照？","o":["至少一个安全驾驶奖","持学习驾照期间没有自己有责任的车祸，也没有行车违规","笔试满分","持学习驾照至少两年"],"h1":"想一想持学习驾照期间在路上发生过什么。","h2":"在 Louisiana，学习驾驶的人持学习驾照期间不能有自己有责任的车祸，也不能有行车违规，才能拿到中级驾照。","p":"对。学习驾照期间的记录必须干净。"},"vi":{"q":"Ở Louisiana, người học lái phải có hồ sơ lái xe như thế nào để lên bằng lái trung gian?","o":["Ít nhất một giải thưởng lái xe an toàn","Không có tai nạn do lỗi của mình và không vi phạm luật khi đang lái trong thời gian có giấy phép học lái","Điểm tuyệt đối trong bài thi kiến thức","Có giấy phép học lái ít nhất hai năm"],"h1":"Hãy nghĩ đến những gì đã xảy ra trên đường trong thời gian có giấy phép.","h2":"Ở Louisiana, người học lái cần không có tai nạn do lỗi của mình và không vi phạm luật khi đang lái trong thời gian có giấy phép, để có bằng lái trung gian.","p":"Đúng. Cần hồ sơ sạch trong thời gian có giấy phép học lái."},"tl":{"q":"Sa Louisiana, anong record ang dapat mayroon ang learner para umakyat sa intermediate license?","o":["Hindi bababa sa isang parangal sa ligtas na pagmamaneho","Walang aksidenteng siya ang may sala at walang paglabag sa pagmamaneho habang may permit","Perpektong iskor sa knowledge test","Hindi bababa sa dalawang taon na may permit"],"h1":"Isipin kung ano ang nangyari sa kalsada habang may permit.","h2":"Sa Louisiana, kailangan ng learner na walang aksidenteng siya ang may sala at walang paglabag sa pagmamaneho habang may permit para makakuha ng intermediate license.","p":"Tama. Kailangan ang malinis na record habang may permit."},"ar":{"q":"في Louisiana، ما السجل الذي يجب أن يكون لدى المتعلّم لينتقل إلى الرخصة المتوسطة؟","o":["جائزة واحدة على الأقل للقيادة الآمنة","لا حوادث يكون هو المخطئ فيها ولا مخالفات قيادة خلال فترة التصريح","درجة كاملة في اختبار المعرفة","سنتان على الأقل مع التصريح"],"h1":"فكّر فيما حدث على الطريق خلال فترة التصريح.","h2":"في Louisiana يحتاج المتعلّم إلى ألا تكون لديه حوادث هو المخطئ فيها ولا مخالفات قيادة خلال فترة التصريح ليحصل على الرخصة المتوسطة.","p":"صحيح. يجب أن يكون سجل التصريح نظيفًا."},"ref":{"doc":"LA","page":null}},{"id":"la-014","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, at what blood alcohol level is it illegal for a driver under 21 to drive?","o":["0.08 percent","0.10 percent","0.05 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Louisiana it is illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Luisiana, ¿con qué nivel de alcohol en la sangre es ilegal que maneje un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.05 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Luisiana es ilegal que un conductor menor de 21 maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Louisiana，21 岁以下的司机血液酒精浓度达到多少时开车是违法的？","o":["0.08%","0.10%","0.05%","0.02%"],"h1":"这比成年人的上限 0.08 低很多。","h2":"在 Louisiana，21 岁以下的司机血液酒精浓度达到 0.02% 或更高时开车是违法的。","p":"对。21 岁以下的司机，上限是 0.02。"},"vi":{"q":"Ở Louisiana, người lái dưới 21 tuổi lái xe với nồng độ cồn trong máu từ mức nào là phạm pháp?","o":["0.08 phần trăm","0.10 phần trăm","0.05 phần trăm","0.02 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Louisiana, người lái dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm pháp.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Louisiana, sa anong antas ng alak sa dugo bawal magmaneho ang driver na wala pang 21?","o":["0.08 porsiyento","0.10 porsiyento","0.05 porsiyento","0.02 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult na 0.08.","h2":"Sa Louisiana, bawal magmaneho ang driver na wala pang 21 kung ang antas ng alak sa dugo ay 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Louisiana، عند أي نسبة كحول في الدم تكون القيادة ممنوعة قانونًا على السائق الذي عمره أقل من 21؟","o":["0.08 بالمئة","0.10 بالمئة","0.05 بالمئة","0.02 بالمئة"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Louisiana القيادة ممنوعة قانونًا على السائق الذي عمره أقل من 21 إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 الحد هو 0.02."},"ref":{"doc":"LA","page":123}},{"id":"la-015","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, what does the law say about adult drivers and phones?","o":["Most phone use is banned while driving, but hands-free calls and navigation are allowed","All phone use is allowed","Texting is allowed below 25 mph","Phones are allowed only on interstates"],"h1":"Your hands should stay off the phone.","h2":"In Louisiana most phone use while driving is banned, but hands-free calls and navigation are still allowed.","p":"Right. Hands off the phone; hands-free is allowed."},"es":{"q":"En Luisiana, ¿qué dice la ley sobre los conductores adultos y los teléfonos?","o":["Se prohíbe casi todo uso del teléfono al manejar, pero se permiten llamadas con manos libres y la navegación","Se permite todo uso del teléfono","Se permite enviar mensajes por debajo de 25 mph","Solo se permite en las autopistas interestatales"],"h1":"Sus manos no deben tocar el teléfono.","h2":"En Luisiana se prohíbe casi todo uso del teléfono mientras maneja, pero todavía se permiten las llamadas con manos libres y la navegación.","p":"Correcto. Sin el teléfono en la mano; manos libres sí está permitido."},"zh":{"q":"在 Louisiana，法律对成年司机和手机有什么规定？","o":["开车时大多数手机用法都被禁止，但可以用免提打电话和导航","所有手机用法都可以","速度低于 25 mph 时可以发短信","只有在州际公路上可以用手机"],"h1":"你的手应该离开手机。","h2":"在 Louisiana，开车时大多数手机用法都被禁止，但仍然可以用免提打电话和导航。","p":"对。手不要碰手机；可以用免提。"},"vi":{"q":"Ở Louisiana, luật nói gì về người lái xe trưởng thành và điện thoại?","o":["Hầu hết việc dùng điện thoại bị cấm khi lái xe, nhưng gọi rảnh tay và chỉ đường thì được phép","Mọi việc dùng điện thoại đều được phép","Nhắn tin được phép khi chạy dưới 25 mph","Chỉ được dùng điện thoại trên xa lộ liên bang"],"h1":"Tay bạn không nên cầm điện thoại.","h2":"Ở Louisiana, hầu hết việc dùng điện thoại khi lái xe bị cấm, nhưng gọi rảnh tay và chỉ đường vẫn được phép.","p":"Đúng. Không cầm điện thoại; rảnh tay thì được phép."},"tl":{"q":"Sa Louisiana, ano ang sinasabi ng batas tungkol sa mga adult na driver at telepono?","o":["Bawal ang karamihan ng paggamit ng telepono habang nagmamaneho, pero puwede ang hands-free na tawag at navigation","Puwede ang lahat ng paggamit ng telepono","Puwedeng mag-text kapag mas mabagal sa 25 mph","Puwede lang ang telepono sa interstate"],"h1":"Dapat hindi hawak ng kamay mo ang telepono.","h2":"Sa Louisiana, bawal ang karamihan ng paggamit ng telepono habang nagmamaneho, pero puwede pa rin ang hands-free na tawag at navigation.","p":"Tama. Huwag hawakan ang telepono; puwede ang hands-free."},"ar":{"q":"في Louisiana، ماذا يقول القانون عن السائقين البالغين والهواتف؟","o":["معظم استخدام الهاتف ممنوع أثناء القيادة، لكن المكالمات دون استخدام اليدين والملاحة مسموحة","كل استخدام للهاتف مسموح","المراسلة مسموحة تحت 25 mph","الهواتف مسموحة على الطرق السريعة بين الولايات فقط"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"في Louisiana معظم استخدام الهاتف أثناء القيادة ممنوع، لكن المكالمات دون استخدام اليدين والملاحة ما زالت مسموحة.","p":"صحيح. لا تمسك الهاتف بيدك؛ الاستخدام دون اليدين مسموح."},"ref":{"doc":"LA","page":78}},{"id":"la-016","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving outside a school or construction zone, when there is no crash?","o":["$25","$500","$100","$1,000"],"h1":"In a school or construction zone the fine is $250.","h2":"In Louisiana the fine for using a hand-held phone while driving outside a school or construction zone is $100, and it doubles if there is a crash.","p":"Right. The fine is $100 outside those zones."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción, si no hay choque?","o":["$25","$500","$100","$1,000"],"h1":"En una zona escolar o de construcción la multa es de $250.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja fuera de una zona escolar o de construcción es de $100, y se duplica si hay un choque.","p":"Correcto. La multa es de $100 fuera de esas zonas."},"zh":{"q":"在 Louisiana，在学校区域或施工区以外开车时手持手机，没有发生车祸，罚款多少？","o":["$25","$500","$100","$1,000"],"h1":"在学校区域或施工区，罚款是 $250。","h2":"在 Louisiana，在学校区域或施工区以外开车时手持手机，罚款是 $100，如果发生车祸，罚款加倍。","p":"对。在这些区域以外，罚款是 $100。"},"vi":{"q":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe bên ngoài khu trường học hoặc khu công trường, khi không có tai nạn, là bao nhiêu?","o":["$25","$500","$100","$1,000"],"h1":"Trong khu trường học hoặc khu công trường, tiền phạt là $250.","h2":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe bên ngoài khu trường học hoặc khu công trường là $100, và gấp đôi nếu có tai nạn.","p":"Đúng. Tiền phạt là $100 bên ngoài những khu đó."},"tl":{"q":"Sa Louisiana, magkano ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa labas ng school zone o construction zone, kapag walang aksidente?","o":["$25","$500","$100","$1,000"],"h1":"Sa school zone o construction zone, $250 ang multa.","h2":"Sa Louisiana, $100 ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa labas ng school zone o construction zone, at doble ito kapag may aksidente.","p":"Tama. $100 ang multa sa labas ng mga zone na iyon."},"ar":{"q":"في Louisiana، كم غرامة استخدام هاتف باليد أثناء القيادة خارج منطقة مدرسة أو منطقة أعمال بناء، عندما لا يكون هناك حادث؟","o":["$25","$500","$100","$1,000"],"h1":"في منطقة المدرسة أو منطقة أعمال البناء الغرامة $250.","h2":"في Louisiana غرامة استخدام هاتف باليد أثناء القيادة خارج منطقة مدرسة أو منطقة أعمال بناء هي $100، وتتضاعف إذا كان هناك حادث.","p":"صحيح. الغرامة $100 خارج هذه المناطق."},"ref":{"doc":"LA","page":null}},{"id":"la-017","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the fine for using a hand-held phone while driving in a school or construction zone, when there is no crash?","o":["$75","$250","$50","$2,000"],"h1":"It is more than twice the $100 fine outside those zones.","h2":"In Louisiana the fine for using a hand-held phone while driving in a school or construction zone is $250.","p":"Right. The fine is $250 in a school or work zone."},"es":{"q":"En Luisiana, ¿cuál es la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción, si no hay choque?","o":["$75","$250","$50","$2,000"],"h1":"Es más del doble de la multa de $100 fuera de esas zonas.","h2":"En Luisiana la multa por usar un teléfono en la mano mientras maneja en una zona escolar o de construcción es de $250.","p":"Correcto. La multa es de $250 en una zona escolar o de obras."},"zh":{"q":"在 Louisiana，在学校区域或施工区开车时手持手机，没有发生车祸，罚款多少？","o":["$75","$250","$50","$2,000"],"h1":"比这些区域以外的 $100 罚款的两倍还多。","h2":"在 Louisiana，在学校区域或施工区开车时手持手机，罚款是 $250。","p":"对。在学校区域或施工区，罚款是 $250。"},"vi":{"q":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe trong khu trường học hoặc khu công trường, khi không có tai nạn, là bao nhiêu?","o":["$75","$250","$50","$2,000"],"h1":"Nó nhiều hơn gấp đôi tiền phạt $100 bên ngoài những khu đó.","h2":"Ở Louisiana, tiền phạt cho việc cầm điện thoại khi lái xe trong khu trường học hoặc khu công trường là $250.","p":"Đúng. Tiền phạt là $250 trong khu trường học hoặc khu công trường."},"tl":{"q":"Sa Louisiana, magkano ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa school zone o construction zone, kapag walang aksidente?","o":["$75","$250","$50","$2,000"],"h1":"Higit ito sa doble ng $100 na multa sa labas ng mga zone na iyon.","h2":"Sa Louisiana, $250 ang multa sa paggamit ng hawak na telepono habang nagmamaneho sa school zone o construction zone.","p":"Tama. $250 ang multa sa school zone o work zone."},"ar":{"q":"في Louisiana، كم غرامة استخدام هاتف باليد أثناء القيادة في منطقة مدرسة أو منطقة أعمال بناء، عندما لا يكون هناك حادث؟","o":["$75","$250","$50","$2,000"],"h1":"هي أكثر من ضعف غرامة $100 خارج هذه المناطق.","h2":"في Louisiana غرامة استخدام هاتف باليد أثناء القيادة في منطقة مدرسة أو منطقة أعمال بناء هي $250.","p":"صحيح. الغرامة $250 في منطقة مدرسة أو منطقة عمل."},"ref":{"doc":"LA","page":null}},{"id":"la-018","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, which stopped vehicles does the expanded Move Over law cover, in addition to emergency vehicles?","o":["Only police cars","Only school buses","Only tow trucks","Disabled vehicles showing hazard lights, flashing lights or another warning device"],"h1":"Think of any car broken down at the side of the road with its warning lights on.","h2":"In Louisiana the expanded Move Over law also covers disabled or stopped vehicles that show hazard lights, flashing lights or another emergency warning device.","p":"Right. Move over for any stopped vehicle showing warning lights."},"es":{"q":"En Luisiana, ¿qué vehículos detenidos cubre la ley ampliada \"Move Over\", además de los vehículos de emergencia?","o":["Solo las patrullas de policía","Solo los autobuses escolares","Solo las grúas","Vehículos descompuestos con luces de emergencia, luces intermitentes u otro aviso de peligro"],"h1":"Piense en cualquier carro descompuesto al lado de la carretera con sus luces de aviso encendidas.","h2":"En Luisiana la ley ampliada \"Move Over\" también cubre los vehículos descompuestos o detenidos que muestran luces de emergencia, luces intermitentes u otro aviso de peligro.","p":"Correcto. Cámbiese de carril ante cualquier vehículo detenido con luces de aviso."},"zh":{"q":"在 Louisiana，扩大后的 Move Over 法除了急救车辆以外，还保护哪些停着的车辆？","o":["只有警车","只有校车","只有拖车","开着双闪灯、闪灯或其他警示装置的故障车辆"],"h1":"想一想任何在路边坏了、开着警示灯的车。","h2":"在 Louisiana，扩大后的 Move Over 法也保护开着双闪灯、闪灯或其他紧急警示装置的故障车辆或停着的车辆。","p":"对。遇到任何开着警示灯、停着的车辆都要换道让开。"},"vi":{"q":"Ở Louisiana, luật Tránh Sang Làn Khác (Move Over law) mở rộng áp dụng cho những xe đang dừng nào, ngoài xe khẩn cấp?","o":["Chỉ xe cảnh sát","Chỉ xe buýt trường học","Chỉ xe kéo","Xe bị hỏng đang bật đèn cảnh báo, đèn nhấp nháy hoặc thiết bị cảnh báo khác"],"h1":"Hãy nghĩ đến bất kỳ xe nào bị hỏng bên lề đường và đang bật đèn cảnh báo.","h2":"Ở Louisiana, luật Tránh Sang Làn Khác mở rộng cũng áp dụng cho xe bị hỏng hoặc đang dừng có bật đèn cảnh báo, đèn nhấp nháy hoặc thiết bị cảnh báo khẩn cấp khác.","p":"Đúng. Tránh sang làn khác khi gặp bất kỳ xe đang dừng nào bật đèn cảnh báo."},"tl":{"q":"Sa Louisiana, aling mga nakahintong sasakyan ang sakop ng pinalawak na Move Over law, bukod sa mga emergency vehicle?","o":["Mga sasakyan ng pulis lang","Mga school bus lang","Mga tow truck lang","Mga sirang sasakyan na may hazard lights, kumikislap na ilaw o ibang babalang gamit"],"h1":"Isipin ang kahit anong sirang kotse sa gilid ng kalsada na nakabukas ang babalang ilaw.","h2":"Sa Louisiana, sakop din ng pinalawak na Move Over law ang mga sira o nakahintong sasakyan na may hazard lights, kumikislap na ilaw o ibang babalang gamit para sa emergency.","p":"Tama. Lumipat ng lane para sa kahit anong nakahintong sasakyan na may babalang ilaw."},"ar":{"q":"في Louisiana، ما المركبات المتوقفة التي يشملها قانون الابتعاد (Move Over law) الموسّع، إضافة إلى مركبات الطوارئ؟","o":["سيارات الشرطة فقط","الحافلات المدرسية فقط","شاحنات السحب فقط","المركبات المعطّلة التي تشغّل أضواء التحذير أو أضواء وامضة أو أداة تحذير أخرى"],"h1":"فكّر في أي سيارة معطّلة على جانب الطريق وأضواء التحذير فيها مشغّلة.","h2":"في Louisiana يشمل قانون الابتعاد الموسّع أيضًا المركبات المعطّلة أو المتوقفة التي تشغّل أضواء التحذير أو أضواء وامضة أو أداة تحذير طوارئ أخرى.","p":"صحيح. ابتعد عن أي مركبة متوقفة تشغّل أضواء التحذير."},"ref":{"doc":"LA","page":null}},{"id":"la-019","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, what should you do under the Move Over law on a two-lane road where you cannot change lanes?","o":["Slow down","Keep the same speed","Honk your horn","Stop in your lane"],"h1":"If you cannot move away, change something else.","h2":"In Louisiana, when you cannot change lanes, such as on a two-lane road, you must slow down as you pass the stopped vehicle.","p":"Right. If you cannot move over, slow down."},"es":{"q":"En Luisiana, según la ley \"Move Over\", ¿qué debe hacer en una carretera de dos carriles donde no puede cambiarse de carril?","o":["Bajar la velocidad","Seguir a la misma velocidad","Tocar la bocina","Detenerse en su carril"],"h1":"Si no puede alejarse, cambie otra cosa.","h2":"En Luisiana, cuando no puede cambiarse de carril, por ejemplo en una carretera de dos carriles, debe bajar la velocidad al pasar el vehículo detenido.","p":"Correcto. Si no puede cambiarse de carril, baje la velocidad."},"zh":{"q":"在 Louisiana，在不能换道的双车道道路上，按照 Move Over 法你应该做什么？","o":["减速","保持原来的速度","按喇叭","在你的车道停下"],"h1":"如果你不能离开，就改变别的东西。","h2":"在 Louisiana，当你不能换道时，例如在双车道道路上，你开过停着的车辆时必须减速。","p":"对。如果不能换道让开，就减速。"},"vi":{"q":"Ở Louisiana, theo luật Tránh Sang Làn Khác, bạn nên làm gì trên đường hai làn khi không thể đổi làn?","o":["Chạy chậm lại","Giữ nguyên tốc độ","Bóp còi","Dừng lại trong làn của mình"],"h1":"Nếu không thể tránh ra xa, hãy thay đổi điều khác.","h2":"Ở Louisiana, khi bạn không thể đổi làn, ví dụ trên đường hai làn, bạn phải chạy chậm lại khi đi qua xe đang dừng.","p":"Đúng. Nếu không thể tránh sang làn khác, hãy chạy chậm lại."},"tl":{"q":"Sa Louisiana, ano ang dapat mong gawin ayon sa Move Over law sa kalsadang may dalawang lane kung saan hindi ka makalipat ng lane?","o":["Bagalan ang takbo","Panatilihin ang parehong bilis","Bumusina","Huminto sa iyong lane"],"h1":"Kung hindi ka makalayo, baguhin ang ibang bagay.","h2":"Sa Louisiana, kapag hindi ka makalipat ng lane, gaya sa kalsadang may dalawang lane, dapat mong bagalan ang takbo habang dumadaan sa nakahintong sasakyan.","p":"Tama. Kung hindi ka makalipat ng lane, bagalan ang takbo."},"ar":{"q":"في Louisiana، ماذا يجب أن تفعل حسب قانون الابتعاد على طريق بمسارين لا يمكنك فيه تغيير المسار؟","o":["خفّف السرعة","حافظ على السرعة نفسها","استخدم البوق","توقّف في مسارك"],"h1":"إذا لم تستطع الابتعاد، غيّر شيئًا آخر.","h2":"في Louisiana، عندما لا تستطيع تغيير المسار، مثل طريق بمسارين، يجب أن تخفّف السرعة وأنت تمر بجانب المركبة المتوقفة.","p":"صحيح. إذا لم تستطع الابتعاد، خفّف السرعة."},"ref":{"doc":"LA","page":30}},{"id":"la-020","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what is the youngest age to get an intermediate license?","o":["15","17","16","18"],"h1":"It is one year after the earliest learner's permit.","h2":"In Louisiana you can get an intermediate license at 16, after holding the learner's permit for at least 180 days.","p":"Right. The intermediate license starts at 16."},"es":{"q":"En Luisiana, ¿cuál es la edad mínima para obtener la licencia intermedia?","o":["15","17","16","18"],"h1":"Es un año después de la edad mínima para el permiso de aprendiz.","h2":"En Luisiana usted puede obtener la licencia intermedia a los 16 años, después de tener el permiso de aprendiz por lo menos 180 días.","p":"Correcto. La licencia intermedia empieza a los 16."},"zh":{"q":"在 Louisiana，最小几岁可以拿到中级驾照？","o":["15 岁","17 岁","16 岁","18 岁"],"h1":"比最早拿学习驾照的年龄晚一年。","h2":"在 Louisiana，持有学习驾照至少 180 天后，你 16 岁就可以拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Louisiana, tuổi nhỏ nhất để có bằng lái trung gian là bao nhiêu?","o":["15","17","16","18"],"h1":"Đó là một năm sau tuổi sớm nhất để có giấy phép học lái.","h2":"Ở Louisiana, bạn có thể có bằng lái trung gian lúc 16 tuổi, sau khi giữ giấy phép học lái ít nhất 180 ngày.","p":"Đúng. Bằng lái trung gian bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Louisiana, ano ang pinakabatang edad para makakuha ng intermediate license?","o":["15","17","16","18"],"h1":"Isang taon ito pagkatapos ng pinakamaagang learner's permit.","h2":"Sa Louisiana, puwede kang kumuha ng intermediate license sa edad na 16, pagkatapos mong hawakan ang learner's permit nang hindi bababa sa 180 araw.","p":"Tama. Nagsisimula ang intermediate license sa edad na 16."},"ar":{"q":"في Louisiana، ما أصغر عمر للحصول على الرخصة المتوسطة؟","o":["15","17","16","18"],"h1":"هو بعد أبكر عمر لتصريح تعلّم القيادة بسنة واحدة.","h2":"في Louisiana يمكنك الحصول على الرخصة المتوسطة في سن 16، بعد أن تحمل تصريح تعلّم القيادة 180 يومًا على الأقل.","p":"صحيح. تبدأ الرخصة المتوسطة في سن 16."},"ref":{"doc":"LA","page":7}},{"id":"la-021","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what score do you need to pass the knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"You must get most of the questions right, but not nearly all.","h2":"In Louisiana you must answer at least 80 percent of the knowledge test questions correctly to pass.","p":"Right. The passing score is 80 percent."},"es":{"q":"En Luisiana, ¿qué puntaje necesita para aprobar el examen teórico?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Debe contestar bien la mayoría de las preguntas, pero no casi todas.","h2":"En Luisiana usted debe contestar bien al menos el 80 por ciento de las preguntas del examen teórico para aprobar.","p":"Correcto. El puntaje para aprobar es 80 por ciento."},"zh":{"q":"在 Louisiana，笔试（knowledge test）要考多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"大部分题目要答对，但不用几乎全对。","h2":"在 Louisiana，笔试至少要答对 80% 的题目才能通过。","p":"对。及格分数是 80%。"},"vi":{"q":"Ở Louisiana, bạn cần bao nhiêu điểm để đậu bài thi kiến thức (knowledge test)?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Bạn phải trả lời đúng phần lớn câu hỏi, nhưng không cần gần như tất cả.","h2":"Ở Louisiana, bạn phải trả lời đúng ít nhất 80 phần trăm câu hỏi của bài thi kiến thức để đậu.","p":"Đúng. Điểm đậu là 80 phần trăm."},"tl":{"q":"Sa Louisiana, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Dapat tama ang karamihan ng tanong, pero hindi halos lahat.","h2":"Sa Louisiana, dapat tama ang sagot mo sa hindi bababa sa 80 porsiyento ng mga tanong sa knowledge test para pumasa.","p":"Tama. Ang passing score ay 80 porsiyento."},"ar":{"q":"في Louisiana، ما الدرجة التي تحتاجها لتنجح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"يجب أن تجيب عن معظم الأسئلة بشكل صحيح، لكن ليس عن كلها تقريبًا.","h2":"في Louisiana يجب أن تجيب بشكل صحيح عن 80 بالمئة على الأقل من أسئلة اختبار المعرفة لتنجح.","p":"صحيح. درجة النجاح هي 80 بالمئة."},"ref":{"doc":"LA","page":8}},{"id":"la-022","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, until what age should a child ride in a rear-facing car seat?","o":["At least age 2","At least 6 months","At least age 4","At least age 1"],"h1":"It is longer than the first year of life.","h2":"In Louisiana a child rides in a rear-facing car seat from birth until at least age 2.","p":"Right. Rear-facing until at least age 2."},"es":{"q":"En Luisiana, ¿hasta qué edad debe viajar un niño en un asiento de seguridad mirando hacia atrás?","o":["Al menos hasta los 2 años","Al menos hasta los 6 meses","Al menos hasta los 4 años","Al menos hasta 1 año"],"h1":"Es más que el primer año de vida.","h2":"En Luisiana un niño viaja en un asiento de seguridad mirando hacia atrás desde que nace hasta al menos los 2 años.","p":"Correcto. Mirando hacia atrás hasta al menos los 2 años."},"zh":{"q":"在 Louisiana，孩子应该坐后向式儿童安全座椅坐到几岁？","o":["至少 2 岁","至少 6 个月","至少 4 岁","至少 1 岁"],"h1":"比出生后的第一年更久。","h2":"在 Louisiana，孩子从出生起就坐后向式儿童安全座椅，至少坐到 2 岁。","p":"对。后向式座椅至少坐到 2 岁。"},"vi":{"q":"Ở Louisiana, trẻ em nên ngồi ghế ô tô quay về phía sau đến bao nhiêu tuổi?","o":["Ít nhất 2 tuổi","Ít nhất 6 tháng","Ít nhất 4 tuổi","Ít nhất 1 tuổi"],"h1":"Lâu hơn năm đầu tiên của cuộc đời.","h2":"Ở Louisiana, trẻ em ngồi ghế ô tô quay về phía sau từ lúc mới sinh đến ít nhất 2 tuổi.","p":"Đúng. Quay về phía sau đến ít nhất 2 tuổi."},"tl":{"q":"Sa Louisiana, hanggang anong edad dapat nakaupo ang bata sa car seat na nakaharap sa likod?","o":["Hanggang edad 2 man lang","Hanggang 6 na buwan man lang","Hanggang edad 4 man lang","Hanggang edad 1 man lang"],"h1":"Mas matagal ito kaysa sa unang taon ng buhay.","h2":"Sa Louisiana, nakaupo ang bata sa car seat na nakaharap sa likod mula pagkapanganak hanggang edad 2 man lang.","p":"Tama. Nakaharap sa likod hanggang edad 2 man lang."},"ar":{"q":"في Louisiana، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف؟","o":["سن 2 على الأقل","6 أشهر على الأقل","سن 4 على الأقل","سن 1 على الأقل"],"h1":"هو أطول من السنة الأولى من العمر.","h2":"في Louisiana يجلس الطفل في مقعد سيارة مواجه للخلف من الولادة حتى سن 2 على الأقل.","p":"صحيح. المقعد المواجه للخلف حتى سن 2 على الأقل."},"ref":{"doc":"LA","page":40}},{"id":"la-023","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, children younger than what age should ride in the back seat when one is available?","o":["8","10","16","13"],"h1":"It is a teen age, but a young one.","h2":"In Louisiana children younger than 13 must ride in the back seat, buckled in, when a back seat is available.","p":"Right. Under 13 rides in the back seat."},"es":{"q":"En Luisiana, ¿los niños menores de qué edad deben viajar en el asiento de atrás cuando hay uno disponible?","o":["8","10","16","13"],"h1":"Es una edad de adolescente, pero joven.","h2":"En Luisiana los niños menores de 13 años deben viajar en el asiento de atrás, con el cinturón puesto, cuando hay asiento de atrás disponible.","p":"Correcto. Los menores de 13 van en el asiento de atrás."},"zh":{"q":"在 Louisiana，有后座时，几岁以下的孩子应该坐在后座？","o":["8","10","16","13"],"h1":"是青少年的年龄，但比较小。","h2":"在 Louisiana，有后座时，13 岁以下的孩子必须坐在后座并系好安全带。","p":"对。13 岁以下坐后座。"},"vi":{"q":"Ở Louisiana, trẻ em dưới bao nhiêu tuổi nên ngồi ở ghế sau khi có ghế sau?","o":["8","10","16","13"],"h1":"Đó là tuổi thiếu niên, nhưng còn nhỏ.","h2":"Ở Louisiana, trẻ em dưới 13 tuổi phải ngồi ở ghế sau và thắt dây an toàn khi có ghế sau.","p":"Đúng. Dưới 13 tuổi ngồi ghế sau."},"tl":{"q":"Sa Louisiana, ang mga batang mas bata sa anong edad ang dapat umupo sa likurang upuan kapag mayroon nito?","o":["8","10","16","13"],"h1":"Edad ito ng teenager, pero bata pa.","h2":"Sa Louisiana, ang mga batang mas bata sa 13 ay dapat umupo sa likurang upuan, nakasuot ng seat belt, kapag may likurang upuan.","p":"Tama. Ang mas bata sa 13 ay umuupo sa likod."},"ar":{"q":"في Louisiana، الأطفال الأصغر من أي عمر يجب أن يجلسوا في المقعد الخلفي عندما يكون متاحًا؟","o":["8","10","16","13"],"h1":"هو عمر مراهق، لكنه صغير.","h2":"في Louisiana يجب على الأطفال الأصغر من 13 سنة الجلوس في المقعد الخلفي مع ربط الحزام، عندما يكون هناك مقعد خلفي.","p":"صحيح. من هو أصغر من 13 يجلس في المقعد الخلفي."},"ref":{"doc":"LA","page":40}},{"id":"la-024","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, where must your proof of insurance be kept?","o":["At home in a safe place","In the vehicle at all times","Only with your insurance agent","At the Office of Motor Vehicles"],"h1":"An officer may ask to see it during a stop.","h2":"In Louisiana the law says your insurance card must be in the vehicle at all times.","p":"Right. Keep the insurance card in the vehicle."},"es":{"q":"En Luisiana, ¿dónde debe guardar su comprobante de seguro?","o":["En casa, en un lugar seguro","En el vehículo en todo momento","Solo con su agente de seguros","En la Oficina de Vehículos Motorizados"],"h1":"Un policía puede pedir verlo cuando lo detiene.","h2":"En Luisiana la ley dice que su tarjeta de seguro debe estar en el vehículo en todo momento.","p":"Correcto. Guarde la tarjeta de seguro en el vehículo."},"zh":{"q":"在 Louisiana，你的保险证明必须放在哪里？","o":["放在家里安全的地方","一直放在车里","只放在保险经纪人那里","放在机动车辆办公室（Office of Motor Vehicles）"],"h1":"警察拦车时可能会要求看。","h2":"在 Louisiana，法律规定你的保险卡必须一直放在车里。","p":"对。把保险卡放在车里。"},"vi":{"q":"Ở Louisiana, giấy chứng nhận bảo hiểm của bạn phải được để ở đâu?","o":["Ở nhà, tại một nơi an toàn","Trong xe mọi lúc","Chỉ ở chỗ đại lý bảo hiểm của bạn","Tại Văn phòng Xe cơ giới (Office of Motor Vehicles)"],"h1":"Cảnh sát có thể yêu cầu xem khi chặn xe.","h2":"Ở Louisiana, luật quy định thẻ bảo hiểm của bạn phải luôn ở trong xe.","p":"Đúng. Hãy để thẻ bảo hiểm trong xe."},"tl":{"q":"Sa Louisiana, saan dapat nakalagay ang patunay ng iyong insurance?","o":["Sa bahay, sa ligtas na lugar","Sa sasakyan sa lahat ng oras","Sa insurance agent mo lang","Sa Office of Motor Vehicles"],"h1":"Puwede itong hingin ng pulis kapag pinara ka.","h2":"Sa Louisiana, sinasabi ng batas na dapat nasa sasakyan ang insurance card mo sa lahat ng oras.","p":"Tama. Itago ang insurance card sa sasakyan."},"ar":{"q":"في Louisiana، أين يجب أن تحتفظ بإثبات التأمين؟","o":["في البيت في مكان آمن","في السيارة طوال الوقت","مع وكيل التأمين فقط","في مكتب المركبات (Office of Motor Vehicles)"],"h1":"قد يطلب الشرطي رؤيته عندما يوقفك.","h2":"في Louisiana يقول القانون إن بطاقة التأمين يجب أن تكون في السيارة طوال الوقت.","p":"صحيح. احتفظ ببطاقة التأمين في السيارة."},"ref":{"doc":"LA","page":7}},{"id":"la-025","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, which shorter course may a new driver age 18 or older take instead of the 38-hour driver education course?","o":["A 2-hour online video","A 4-hour defensive driving class","A 6-hour pre-licensing course plus 8 hours behind the wheel","No course is needed at all"],"h1":"Adults still need some classroom time and some time driving.","h2":"In Louisiana a new driver age 18 or older may take a 6-hour pre-licensing course and an 8-hour behind-the-wheel course instead of the 38-hour course.","p":"Right. Adults may take 6 hours of class plus 8 hours of driving."},"es":{"q":"En Luisiana, ¿qué curso más corto puede tomar un conductor nuevo de 18 años o más en lugar del curso de educación vial de 38 horas?","o":["Un video en línea de 2 horas","Una clase de manejo defensivo de 4 horas","Un curso previo a la licencia de 6 horas más 8 horas al volante","No necesita ningún curso"],"h1":"Los adultos también necesitan algo de clase y algo de práctica manejando.","h2":"En Luisiana un conductor nuevo de 18 años o más puede tomar un curso previo a la licencia de 6 horas y un curso al volante de 8 horas en lugar del curso de 38 horas.","p":"Correcto. Los adultos pueden tomar 6 horas de clase más 8 horas manejando."},"zh":{"q":"在 Louisiana，18 岁或以上的新司机可以上哪种较短的课程，来代替 38 小时的驾驶教育课程？","o":["2 小时的网上视频","4 小时的防御性驾驶课","6 小时的考照前课程，加上 8 小时的实际驾驶","完全不需要上课"],"h1":"成年人仍然需要一些课堂时间和一些开车时间。","h2":"在 Louisiana，18 岁或以上的新司机可以上 6 小时的考照前课程和 8 小时的实际驾驶课程，来代替 38 小时的课程。","p":"对。成年人可以上 6 小时的课，再加 8 小时的开车。"},"vi":{"q":"Ở Louisiana, người mới lái xe từ 18 tuổi trở lên có thể học khóa ngắn hơn nào thay cho khóa giáo dục lái xe 38 giờ?","o":["Một video trực tuyến 2 giờ","Một lớp lái xe phòng thủ 4 giờ","Một khóa trước khi cấp bằng 6 giờ cộng 8 giờ lái xe thực tế","Không cần học khóa nào cả"],"h1":"Người lớn vẫn cần một ít thời gian học trên lớp và một ít thời gian lái xe.","h2":"Ở Louisiana, người mới lái xe từ 18 tuổi trở lên có thể học khóa trước khi cấp bằng 6 giờ và khóa lái xe thực tế 8 giờ thay cho khóa 38 giờ.","p":"Đúng. Người lớn có thể học 6 giờ trên lớp cộng 8 giờ lái xe."},"tl":{"q":"Sa Louisiana, anong mas maikling kurso ang puwedeng kunin ng bagong driver na edad 18 pataas sa halip na ang 38-oras na kurso sa driver education?","o":["Isang 2-oras na online video","Isang 4-oras na klase sa defensive driving","Isang 6-oras na pre-licensing course at 8 oras ng aktuwal na pagmamaneho","Hindi na kailangan ng anumang kurso"],"h1":"Kailangan pa rin ng mga adult ng kaunting oras sa klase at kaunting oras sa pagmamaneho.","h2":"Sa Louisiana, puwedeng kumuha ang bagong driver na edad 18 pataas ng 6-oras na pre-licensing course at 8-oras na behind-the-wheel course sa halip na ang 38-oras na kurso.","p":"Tama. Puwedeng kumuha ang mga adult ng 6 na oras ng klase at 8 oras ng pagmamaneho."},"ar":{"q":"في Louisiana، ما الدورة الأقصر التي يمكن للسائق الجديد البالغ 18 سنة أو أكثر أن يأخذها بدل دورة تعليم القيادة التي مدتها 38 ساعة؟","o":["فيديو على الإنترنت مدته ساعتان (2)","درس قيادة دفاعية مدته 4 ساعات","دورة ما قبل الرخصة مدتها 6 ساعات، مع 8 ساعات قيادة فعلية","لا حاجة لأي دورة"],"h1":"البالغون ما زالوا يحتاجون بعض الوقت في الصف وبعض الوقت في القيادة.","h2":"في Louisiana يمكن للسائق الجديد البالغ 18 سنة أو أكثر أن يأخذ دورة ما قبل الرخصة مدتها 6 ساعات ودورة قيادة فعلية مدتها 8 ساعات، بدل دورة الـ 38 ساعة.","p":"صحيح. يمكن للبالغين أخذ 6 ساعات من الدروس مع 8 ساعات من القيادة."},"ref":{"doc":"LA","page":7}},{"id":"la-026","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, what can happen to the driving privilege of a 16-year-old who drops out of school before graduating?","o":["It can be taken away","Nothing happens","The teen must retake the vision test","The teen pays a small fee"],"h1":"The state links staying in school with keeping a license.","h2":"In Louisiana a driver age 15 to 17 who leaves school before graduating, or is often absent or late, can lose the driving privilege.","p":"Right. Dropping out can cost a teen the license."},"es":{"q":"En Luisiana, ¿qué le puede pasar al privilegio de manejar de un joven de 16 años que deja la escuela antes de graduarse?","o":["Se lo pueden quitar","No pasa nada","El joven debe repetir el examen de la vista","El joven paga una cuota pequeña"],"h1":"El estado relaciona seguir en la escuela con conservar la licencia.","h2":"En Luisiana un conductor de 15 a 17 años que deja la escuela antes de graduarse, o que falta o llega tarde con frecuencia, puede perder el privilegio de manejar.","p":"Correcto. Dejar la escuela le puede costar la licencia a un joven."},"zh":{"q":"在 Louisiana，16 岁的人如果没毕业就退学，他的驾驶权可能会怎样？","o":["可能被取消","什么都不会发生","必须重新做视力检查","交一小笔费用"],"h1":"州政府把继续上学和保留驾照联系在一起。","h2":"在 Louisiana，15 到 17 岁的司机如果没毕业就离开学校，或者经常缺课或迟到，可能会失去驾驶权。","p":"对。退学可能让青少年失去驾照。"},"vi":{"q":"Ở Louisiana, điều gì có thể xảy ra với quyền lái xe của một thiếu niên 16 tuổi bỏ học trước khi tốt nghiệp?","o":["Có thể bị tước","Không có gì xảy ra","Thiếu niên phải thi lại thị lực","Thiếu niên trả một khoản phí nhỏ"],"h1":"Tiểu bang gắn việc tiếp tục đi học với việc giữ bằng lái.","h2":"Ở Louisiana, người lái xe từ 15 đến 17 tuổi bỏ học trước khi tốt nghiệp, hoặc thường xuyên vắng mặt hay đi trễ, có thể mất quyền lái xe.","p":"Đúng. Bỏ học có thể làm thiếu niên mất bằng lái."},"tl":{"q":"Sa Louisiana, ano ang puwedeng mangyari sa pribilehiyong magmaneho ng isang 16 na taong gulang na huminto sa pag-aaral bago magtapos?","o":["Puwede itong bawiin","Walang mangyayari","Kailangang ulitin ng teen ang vision test","Magbabayad ang teen ng maliit na bayad"],"h1":"Iniuugnay ng estado ang pananatili sa paaralan sa pagpapanatili ng lisensya.","h2":"Sa Louisiana, ang driver na edad 15 hanggang 17 na umalis sa paaralan bago magtapos, o madalas lumiban o mahuli, ay puwedeng mawalan ng pribilehiyong magmaneho.","p":"Tama. Ang paghinto sa pag-aaral ay puwedeng magpawala ng lisensya ng teen."},"ar":{"q":"في Louisiana، ماذا يمكن أن يحدث لحق القيادة لشاب عمره 16 سنة يترك المدرسة قبل التخرج؟","o":["يمكن أن يُسحب منه","لا يحدث شيء","يجب أن يعيد اختبار النظر","يدفع رسومًا صغيرة"],"h1":"الولاية تربط البقاء في المدرسة بالاحتفاظ بالرخصة.","h2":"في Louisiana السائق الذي عمره من 15 إلى 17 سنة ويترك المدرسة قبل التخرج، أو يغيب أو يتأخر كثيرًا، يمكن أن يفقد حق القيادة.","p":"صحيح. ترك المدرسة قد يكلّف الشاب رخصته."},"ref":{"doc":"LA","page":12}},{"id":"la-027","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the penalty for a first offense of simple littering?","o":["A $25 fine","A $150 fine or 8 hours of community service","A $900 fine or 20 hours of community service","A written warning only"],"h1":"The second offense costs much more than the first.","h2":"In Louisiana a first offense of simple littering brings a $150 fine or 8 hours of community service.","p":"Right. A first offense is $150 or 8 hours of service."},"es":{"q":"En Luisiana, ¿cuál es la sanción por una primera infracción de tirar basura?","o":["Una multa de $25","Una multa de $150 u 8 horas de servicio comunitario","Una multa de $900 o 20 horas de servicio comunitario","Solo una advertencia por escrito"],"h1":"La segunda infracción cuesta mucho más que la primera.","h2":"En Luisiana una primera infracción de tirar basura trae una multa de $150 u 8 horas de servicio comunitario.","p":"Correcto. Una primera infracción es $150 u 8 horas de servicio."},"zh":{"q":"在 Louisiana，第一次乱扔垃圾（simple littering）会受到什么处罚？","o":["罚款 $25","罚款 $150 或 8 小时社区服务","罚款 $900 或 20 小时社区服务","只有书面警告"],"h1":"第二次违规的处罚比第一次重很多。","h2":"在 Louisiana，第一次乱扔垃圾会被罚款 $150 或做 8 小时社区服务。","p":"对。第一次是 $150 或 8 小时服务。"},"vi":{"q":"Ở Louisiana, hình phạt cho lần đầu xả rác thông thường (simple littering) là gì?","o":["Phạt $25","Phạt $150 hoặc 8 giờ lao động công ích","Phạt $900 hoặc 20 giờ lao động công ích","Chỉ cảnh cáo bằng văn bản"],"h1":"Lần vi phạm thứ hai bị phạt nặng hơn nhiều so với lần đầu.","h2":"Ở Louisiana, lần đầu xả rác thông thường bị phạt $150 hoặc 8 giờ lao động công ích.","p":"Đúng. Lần đầu là $150 hoặc 8 giờ lao động công ích."},"tl":{"q":"Sa Louisiana, ano ang parusa sa unang paglabag ng simpleng pagkakalat (simple littering)?","o":["Multang $25","Multang $150 o 8 oras ng community service","Multang $900 o 20 oras ng community service","Nakasulat na babala lang"],"h1":"Mas mahal nang malaki ang ikalawang paglabag kaysa sa una.","h2":"Sa Louisiana, ang unang paglabag ng simpleng pagkakalat ay may multang $150 o 8 oras ng community service.","p":"Tama. Ang unang paglabag ay $150 o 8 oras ng serbisyo."},"ar":{"q":"في Louisiana، ما عقوبة المخالفة الأولى لرمي النفايات البسيط (simple littering)؟","o":["غرامة $25","غرامة $150 أو 8 ساعات من خدمة المجتمع","غرامة $900 أو 20 ساعة من خدمة المجتمع","إنذار مكتوب فقط"],"h1":"المخالفة الثانية تكلّف أكثر بكثير من الأولى.","h2":"في Louisiana عقوبة المخالفة الأولى لرمي النفايات البسيط هي غرامة $150 أو 8 ساعات من خدمة المجتمع.","p":"صحيح. المخالفة الأولى $150 أو 8 ساعات من الخدمة."},"ref":{"doc":"LA","page":14}},{"id":"la-028","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the minimum vision standard on the eye screening?","o":["20/20","20/40","20/70","20/100"],"h1":"You do not need perfect vision, but you need fairly good vision.","h2":"In Louisiana, the eye screening checks that your vision meets the minimum standard of 20/40.","p":"Right. The minimum is 20/40."},"es":{"q":"En Luisiana, ¿cuál es la visión mínima que se exige en el examen de la vista?","o":["20/20","20/40","20/70","20/100"],"h1":"No necesita una visión perfecta, pero sí bastante buena.","h2":"En Luisiana, el examen de la vista comprueba que su visión cumpla el mínimo de 20/40.","p":"Correcto. El mínimo es 20/40."},"zh":{"q":"在 Louisiana，视力检查的最低标准是多少？","o":["20/20","20/40","20/70","20/100"],"h1":"你不需要完美的视力，但视力要相当好。","h2":"在 Louisiana，视力检查要求你的视力达到最低标准 20/40。","p":"对。最低标准是 20/40。"},"vi":{"q":"Ở Louisiana, tiêu chuẩn thị lực tối thiểu trong bài kiểm tra mắt là bao nhiêu?","o":["20/20","20/40","20/70","20/100"],"h1":"Bạn không cần thị lực hoàn hảo, nhưng cần thị lực khá tốt.","h2":"Ở Louisiana, bài kiểm tra mắt xem thị lực của bạn có đạt tiêu chuẩn tối thiểu là 20/40 hay không.","p":"Đúng. Mức tối thiểu là 20/40."},"tl":{"q":"Sa Louisiana, ano ang pinakamababang pamantayan ng paningin sa pagsusuri ng mata?","o":["20/20","20/40","20/70","20/100"],"h1":"Hindi mo kailangan ng perpektong paningin, pero kailangan mo ng medyo malinaw na paningin.","h2":"Sa Louisiana, sinusuri ng eye screening kung umaabot ang paningin mo sa pinakamababang pamantayan na 20/40.","p":"Tama. Ang pinakamababa ay 20/40."},"ar":{"q":"في Louisiana، ما الحد الأدنى المطلوب للنظر في فحص العين؟","o":["20/20","20/40","20/70","20/100"],"h1":"لا تحتاج إلى نظر كامل، لكنك تحتاج إلى نظر جيد إلى حد ما.","h2":"في Louisiana يتأكد فحص العين من أن نظرك يبلغ الحد الأدنى المطلوب وهو 20/40.","p":"صحيح. الحد الأدنى هو 20/40."},"ref":{"doc":"LA","page":8}},{"id":"la-029","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how long is a driver's license good for before it expires?","o":["Two years","Four years","Six years","Ten years"],"h1":"It lasts more than four years.","h2":"In Louisiana, a driver's license expires six years from your nearest birthday, and you may renew it up to 180 days early.","p":"Right. A license lasts six years."},"es":{"q":"En Luisiana, ¿por cuánto tiempo es válida una licencia de conducir antes de vencer?","o":["Dos años","Cuatro años","Seis años","Diez años"],"h1":"Dura más de cuatro años.","h2":"En Luisiana, la licencia de conducir vence seis años después de su cumpleaños más cercano, y puede renovarla hasta 180 días antes.","p":"Correcto. La licencia dura seis años."},"zh":{"q":"在 Louisiana，驾照有效期多久才会过期？","o":["两年","四年","六年","十年"],"h1":"它的有效期超过四年。","h2":"在 Louisiana，驾照从你最近的生日起六年后过期，你最早可以提前 180 天续期。","p":"对。驾照有效期是六年。"},"vi":{"q":"Ở Louisiana, bằng lái xe có giá trị bao lâu trước khi hết hạn?","o":["Hai năm","Bốn năm","Sáu năm","Mười năm"],"h1":"Nó có giá trị lâu hơn bốn năm.","h2":"Ở Louisiana, bằng lái xe hết hạn sau sáu năm tính từ ngày sinh nhật gần nhất của bạn, và bạn có thể gia hạn sớm tới 180 ngày.","p":"Đúng. Bằng lái có giá trị sáu năm."},"tl":{"q":"Sa Louisiana, gaano katagal may bisa ang driver's license bago ito mag-expire?","o":["Dalawang taon","Apat na taon","Anim na taon","Sampung taon"],"h1":"Mas matagal ito kaysa apat na taon.","h2":"Sa Louisiana, nag-e-expire ang driver's license anim na taon mula sa pinakamalapit mong kaarawan, at puwede mo itong i-renew hanggang 180 araw nang mas maaga.","p":"Tama. Anim na taon ang bisa ng lisensya."},"ar":{"q":"في Louisiana، كم مدة صلاحية رخصة القيادة قبل أن تنتهي؟","o":["سنتان","أربع سنوات","ست سنوات","عشر سنوات"],"h1":"مدتها أطول من أربع سنوات.","h2":"في Louisiana تنتهي رخصة القيادة بعد ست سنوات من أقرب يوم ميلاد لك، ويمكنك تجديدها قبل موعدها بما يصل إلى 180 يومًا.","p":"صحيح. الرخصة صالحة لمدة ست سنوات."},"ref":{"doc":"LA","page":10}},{"id":"la-030","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, how close to a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is farther than the distance for a fire hydrant.","h2":"In Louisiana, you may not park within 50 feet of a railroad crossing.","p":"Right. Stay at least 50 feet away from the tracks."},"es":{"q":"En Luisiana, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No a menos de 50 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 100 pies"],"h1":"Es más lejos que la distancia para un hidrante.","h2":"En Luisiana, no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Quédese al menos a 50 pies de las vías."},"zh":{"q":"在 Louisiana，你可以在离铁路道口多近的地方停车？","o":["不少于 50 英尺","不少于 15 英尺","不少于 25 英尺","不少于 100 英尺"],"h1":"这个距离比消防栓的距离更远。","h2":"在 Louisiana，你不可以在铁路道口 50 英尺以内停车。","p":"对。离铁轨至少要 50 英尺。"},"vi":{"q":"Ở Louisiana, bạn được đậu xe gần đường ray xe lửa tới mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 100 feet"],"h1":"Khoảng cách này xa hơn khoảng cách với vòi nước chữa cháy.","h2":"Ở Louisiana, bạn không được đậu xe trong vòng 50 feet tính từ chỗ băng qua đường ray xe lửa.","p":"Đúng. Hãy cách đường ray ít nhất 50 feet."},"tl":{"q":"Sa Louisiana, gaano kalapit sa tawiran ng riles ng tren ka puwedeng pumarada?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 100 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa Louisiana, bawal pumarada sa loob ng 50 talampakan mula sa tawiran ng riles ng tren.","p":"Tama. Lumayo nang hindi bababa sa 50 talampakan mula sa riles."},"ar":{"q":"في Louisiana، ما أقرب مسافة يُسمح لك فيها بالوقوف من معبر سكة الحديد؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 100 قدم"],"h1":"هذه المسافة أبعد من المسافة المطلوبة عن صنبور الإطفاء.","h2":"في Louisiana لا يجوز لك الوقوف على بعد أقل من 50 قدمًا من معبر سكة الحديد.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من السكة."},"ref":{"doc":"LA","page":70}},{"id":"la-031","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, a car is coming toward you at night. Within what distance must you switch to low beams?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is a longer distance than the one for following a car.","h2":"In Louisiana, you must use low beams when an oncoming vehicle is within 500 feet, or when you follow a vehicle within 200 feet.","p":"Right. Dim your lights within 500 feet of an oncoming car."},"es":{"q":"En Luisiana, de noche viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es una distancia mayor que la que se usa al seguir a otro carro.","h2":"En Luisiana, debe usar luces bajas cuando un vehículo que viene de frente está a menos de 500 pies, o cuando sigue a un vehículo a menos de 200 pies.","p":"Correcto. Baje las luces a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Louisiana，晚上有车迎面开来。在多远距离内你必须换成近光灯？","o":["100 英尺","200 英尺","300 英尺","500 英尺"],"h1":"这个距离比跟车时的距离更长。","h2":"在 Louisiana，迎面来车在 500 英尺以内时，或者你在前车后面 200 英尺以内跟车时，你必须使用近光灯。","p":"对。迎面来车在 500 英尺以内时要调暗车灯。"},"vi":{"q":"Ở Louisiana, ban đêm có xe chạy ngược chiều về phía bạn. Trong khoảng cách nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"Khoảng cách này dài hơn khoảng cách khi chạy theo sau một xe.","h2":"Ở Louisiana, bạn phải dùng đèn cốt khi xe ngược chiều ở trong vòng 500 feet, hoặc khi bạn chạy theo sau một xe trong vòng 200 feet.","p":"Đúng. Hạ đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Louisiana, may sasakyang paparating sa iyo sa gabi. Sa loob ng anong layo ka dapat lumipat sa low beams?","o":["100 talampakan","200 talampakan","300 talampakan","500 talampakan"],"h1":"Mas mahaba ang layong ito kaysa sa layo kapag sumusunod sa isang sasakyan.","h2":"Sa Louisiana, dapat kang gumamit ng low beams kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan, o kapag sumusunod ka sa isang sasakyan sa loob ng 200 talampakan.","p":"Tama. Hinaan ang ilaw kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan."},"ar":{"q":"في Louisiana، تقترب منك سيارة من الاتجاه المقابل في الليل. ضمن أي مسافة يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["100 قدم","200 قدم","300 قدم","500 قدم"],"h1":"هذه المسافة أطول من المسافة عند السير خلف سيارة.","h2":"في Louisiana يجب أن تستخدم الأضواء المنخفضة عندما تكون السيارة المقابلة على بعد 500 قدم أو أقل، أو عندما تسير خلف سيارة على بعد 200 قدم أو أقل.","p":"صحيح. خفّض الأضواء عندما تكون السيارة المقابلة على بعد 500 قدم."},"ref":{"doc":"LA","page":75}},{"id":"la-032","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, you just moved here from another state. How long do you have to get a Louisiana driver's license?","o":["10 days","30 days","60 days","90 days"],"h1":"It is about one month.","h2":"In Louisiana, new residents have 30 days after moving in to get a Louisiana driver's license.","p":"Right. New residents have 30 days."},"es":{"q":"En Luisiana, usted acaba de mudarse desde otro estado. ¿Cuánto tiempo tiene para obtener una licencia de conducir de Luisiana?","o":["10 días","30 días","60 días","90 días"],"h1":"Es más o menos un mes.","h2":"En Luisiana, los nuevos residentes tienen 30 días después de mudarse para obtener una licencia de conducir de Luisiana.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Louisiana，你刚从别的州搬来。你有多长时间去办 Louisiana 驾照？","o":["10 天","30 天","60 天","90 天"],"h1":"大约一个月。","h2":"在 Louisiana，新居民搬来后有 30 天时间去办 Louisiana 驾照。","p":"对。新居民有 30 天。"},"vi":{"q":"Ở Louisiana, bạn vừa chuyển đến từ một tiểu bang khác. Bạn có bao lâu để lấy bằng lái Louisiana?","o":["10 ngày","30 ngày","60 ngày","90 ngày"],"h1":"Khoảng một tháng.","h2":"Ở Louisiana, cư dân mới có 30 ngày sau khi chuyển đến để lấy bằng lái Louisiana.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa Louisiana, kalilipat mo lang dito mula sa ibang estado. Gaano katagal ang mayroon ka para kumuha ng Louisiana driver's license?","o":["10 araw","30 araw","60 araw","90 araw"],"h1":"Mga isang buwan ito.","h2":"Sa Louisiana, may 30 araw ang mga bagong residente pagkalipat nila para kumuha ng Louisiana driver's license.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Louisiana، انتقلت للتو إلى هنا من ولاية أخرى. كم من الوقت لديك للحصول على رخصة قيادة من Louisiana؟","o":["10 أيام","30 يومًا","60 يومًا","90 يومًا"],"h1":"المدة نحو شهر واحد.","h2":"في Louisiana لدى السكان الجدد 30 يومًا بعد انتقالهم للحصول على رخصة قيادة من Louisiana.","p":"صحيح. لدى السكان الجدد 30 يومًا."},"ref":{"doc":"LA","page":1}},{"id":"la-033","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you move to a new home. How soon must you change the address on your license?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In Louisiana, you must change the address on your license within 10 days after you move.","p":"Right. Update your address within 10 days."},"es":{"q":"En Luisiana, usted se muda a una casa nueva. ¿En cuánto tiempo debe cambiar la dirección en su licencia?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En Luisiana, debe cambiar la dirección en su licencia dentro de los 10 días después de mudarse.","p":"Correcto. Actualice su dirección en 10 días."},"zh":{"q":"在 Louisiana，你搬了新家。你必须在多长时间内更改驾照上的地址？","o":["10 天内","30 天内","60 天内","下次换证时"],"h1":"不到两个星期。","h2":"在 Louisiana，你搬家后必须在 10 天内更改驾照上的地址。","p":"对。要在 10 天内更新地址。"},"vi":{"q":"Ở Louisiana, bạn chuyển đến nhà mới. Bạn phải đổi địa chỉ trên bằng lái trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Khi gia hạn bằng lần tới"],"h1":"Ít hơn hai tuần.","h2":"Ở Louisiana, bạn phải đổi địa chỉ trên bằng lái trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Cập nhật địa chỉ trong vòng 10 ngày."},"tl":{"q":"Sa Louisiana, lumipat ka sa bagong bahay. Gaano kabilis mo dapat palitan ang address sa iyong lisensya?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa susunod mong renewal"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sa Louisiana, dapat mong palitan ang address sa iyong lisensya sa loob ng 10 araw pagkalipat mo.","p":"Tama. I-update ang address sa loob ng 10 araw."},"ar":{"q":"في Louisiana، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تغيّر العنوان على رخصتك؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عند تجديد الرخصة القادم"],"h1":"المدة أقل من أسبوعين.","h2":"في Louisiana يجب أن تغيّر العنوان على رخصتك خلال 10 أيام بعد انتقالك.","p":"صحيح. غيّر عنوانك خلال 10 أيام."},"ref":{"doc":"LA","page":10}},{"id":"la-034","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how long does a DWI conviction stay on your public driving record?","o":["2 years","5 years","10 years","For life"],"h1":"It stays twice as long as other traffic convictions.","h2":"In Louisiana, a DWI conviction stays on your driving record for 10 years; most other convictions stay for 5 years.","p":"Right. A DWI stays on your record for 10 years."},"es":{"q":"En Luisiana, ¿cuánto tiempo queda una condena por DWI (manejar en estado de ebriedad) en su historial de manejo público?","o":["2 años","5 años","10 años","Toda la vida"],"h1":"Queda el doble de tiempo que otras condenas de tránsito.","h2":"En Luisiana, una condena por DWI queda en su historial de manejo por 10 años; la mayoría de las otras condenas quedan por 5 años.","p":"Correcto. Un DWI queda en su historial por 10 años."},"zh":{"q":"在 Louisiana，DWI（酒后驾驶）定罪会在你的公开驾驶记录上保留多久？","o":["2 年","5 年","10 年","终身"],"h1":"它保留的时间是其他交通定罪的两倍。","h2":"在 Louisiana，DWI 定罪会在你的驾驶记录上保留 10 年；大多数其他定罪保留 5 年。","p":"对。DWI 会在记录上保留 10 年。"},"vi":{"q":"Ở Louisiana, một bản án DWI (lái xe khi say rượu) ở lại trên hồ sơ lái xe công khai của bạn bao lâu?","o":["2 năm","5 năm","10 năm","Suốt đời"],"h1":"Nó ở lại lâu gấp đôi các bản án giao thông khác.","h2":"Ở Louisiana, bản án DWI ở lại trên hồ sơ lái xe của bạn 10 năm; hầu hết các bản án khác ở lại 5 năm.","p":"Đúng. DWI ở lại trên hồ sơ của bạn 10 năm."},"tl":{"q":"Sa Louisiana, gaano katagal mananatili sa iyong pampublikong driving record ang conviction sa DWI (pagmamaneho nang lasing)?","o":["2 taon","5 taon","10 taon","Habambuhay"],"h1":"Doble ang tagal nito kaysa sa ibang traffic conviction.","h2":"Sa Louisiana, mananatili ang DWI conviction sa iyong driving record nang 10 taon; ang karamihan ng ibang conviction ay nananatili nang 5 taon.","p":"Tama. Mananatili ang DWI sa iyong record nang 10 taon."},"ar":{"q":"في Louisiana، كم تبقى إدانة DWI (القيادة تحت تأثير الكحول) في سجل قيادتك العام؟","o":["2 سنة","5 سنوات","10 سنوات","مدى الحياة"],"h1":"تبقى ضعف مدة إدانات المرور الأخرى.","h2":"في Louisiana تبقى إدانة DWI في سجل قيادتك 10 سنوات، ومعظم الإدانات الأخرى تبقى 5 سنوات.","p":"صحيح. تبقى إدانة DWI في سجلك 10 سنوات."},"ref":{"doc":"LA","page":11}},{"id":"la-035","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, how many reckless driving convictions within 12 months can make you lose your license?","o":["One","Five","Four","Three"],"h1":"It is fewer than four.","h2":"In Louisiana, three reckless driving convictions within 12 months can cost you your driver's license.","p":"Right. Three reckless driving convictions in 12 months can cost you your license."},"es":{"q":"En Luisiana, ¿cuántas condenas por manejo imprudente en 12 meses pueden hacerle perder su licencia?","o":["Una","Cinco","Cuatro","Tres"],"h1":"Son menos de cuatro.","h2":"En Luisiana, tres condenas por manejo imprudente en 12 meses pueden hacerle perder su licencia de conducir.","p":"Correcto. Tres condenas por manejo imprudente en 12 meses pueden costarle la licencia."},"zh":{"q":"在 Louisiana，12 个月内几次鲁莽驾驶定罪会让你失去驾照？","o":["一次","五次","四次","三次"],"h1":"少于四次。","h2":"在 Louisiana，12 个月内三次鲁莽驾驶定罪会让你失去驾照。","p":"对。12 个月内三次鲁莽驾驶定罪会让你失去驾照。"},"vi":{"q":"Ở Louisiana, bao nhiêu bản án lái xe ẩu trong vòng 12 tháng có thể làm bạn mất bằng lái?","o":["Một","Năm","Bốn","Ba"],"h1":"Ít hơn bốn.","h2":"Ở Louisiana, ba bản án lái xe ẩu trong vòng 12 tháng có thể làm bạn mất bằng lái.","p":"Đúng. Ba bản án lái xe ẩu trong 12 tháng có thể làm bạn mất bằng lái."},"tl":{"q":"Sa Louisiana, ilang conviction sa reckless driving (pabayang pagmamaneho) sa loob ng 12 buwan ang puwedeng magpawala ng iyong lisensya?","o":["Isa","Lima","Apat","Tatlo"],"h1":"Kulang ito sa apat.","h2":"Sa Louisiana, ang tatlong conviction sa reckless driving sa loob ng 12 buwan ay puwedeng magpawala ng iyong driver's license.","p":"Tama. Ang tatlong conviction sa reckless driving sa 12 buwan ay puwedeng magpawala ng iyong lisensya."},"ar":{"q":"في Louisiana، كم إدانة بالقيادة المتهورة خلال 12 شهرًا يمكن أن تُفقدك رخصتك؟","o":["واحدة","خمس","أربع","ثلاث"],"h1":"العدد أقل من أربع.","h2":"في Louisiana يمكن أن تُفقدك ثلاث إدانات بالقيادة المتهورة خلال 12 شهرًا رخصة القيادة.","p":"صحيح. ثلاث إدانات بالقيادة المتهورة خلال 12 شهرًا يمكن أن تُفقدك رخصتك."},"ref":{"doc":"LA","page":12}},{"id":"la-036","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, an officer arrests you for drunk driving and you refuse the alcohol test. This is your first refusal. How long is your license suspended?","o":["90 days","365 days","30 days","730 days"],"h1":"It is a full year.","h2":"In Louisiana, refusing the alcohol test the first time suspends your driving privileges for 365 days.","p":"Right. A first refusal means a 365-day suspension."},"es":{"q":"En Luisiana, un oficial lo arresta por manejar ebrio y usted se niega a la prueba de alcohol. Es la primera vez que se niega. ¿Por cuánto tiempo suspenden su licencia?","o":["90 días","365 días","30 días","730 días"],"h1":"Es un año completo.","h2":"En Luisiana, negarse a la prueba de alcohol por primera vez suspende su privilegio de manejar por 365 días.","p":"Correcto. La primera negativa significa una suspensión de 365 días."},"zh":{"q":"在 Louisiana，警察因酒后驾驶逮捕你，你拒绝做酒精测试。这是你第一次拒绝。你的驾照会被暂停多久？","o":["90 天","365 天","30 天","730 天"],"h1":"整整一年。","h2":"在 Louisiana，第一次拒绝酒精测试会让你的驾驶权被暂停 365 天。","p":"对。第一次拒绝就是暂停 365 天。"},"vi":{"q":"Ở Louisiana, cảnh sát bắt bạn vì lái xe khi say rượu và bạn từ chối thử nồng độ cồn. Đây là lần từ chối đầu tiên. Bằng lái của bạn bị đình chỉ bao lâu?","o":["90 ngày","365 ngày","30 ngày","730 ngày"],"h1":"Trọn một năm.","h2":"Ở Louisiana, từ chối thử nồng độ cồn lần đầu sẽ làm quyền lái xe của bạn bị đình chỉ 365 ngày.","p":"Đúng. Từ chối lần đầu nghĩa là bị đình chỉ 365 ngày."},"tl":{"q":"Sa Louisiana, inaresto ka ng pulis dahil sa pagmamaneho nang lasing at tumanggi ka sa alcohol test. Ito ang una mong pagtanggi. Gaano katagal masususpinde ang iyong lisensya?","o":["90 araw","365 araw","30 araw","730 araw"],"h1":"Isang buong taon ito.","h2":"Sa Louisiana, ang unang pagtanggi sa alcohol test ay nagsususpinde ng iyong karapatang magmaneho nang 365 araw.","p":"Tama. Ang unang pagtanggi ay 365 araw na suspensyon."},"ar":{"q":"في Louisiana، قبض عليك شرطي بسبب القيادة تحت تأثير الكحول ورفضت اختبار الكحول. هذا أول رفض لك. كم مدة إيقاف رخصتك؟","o":["90 يومًا","365 يومًا","30 يومًا","730 يومًا"],"h1":"المدة سنة كاملة.","h2":"في Louisiana رفض اختبار الكحول أول مرة يوقف حقك في القيادة 365 يومًا.","p":"صحيح. أول رفض يعني إيقافًا لمدة 365 يومًا."},"ref":{"doc":"LA","page":126}},{"id":"la-037","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you are 21 or older and take the alcohol test. It shows 0.08 to 0.149 percent. How long is your license suspended?","o":["180 days","30 days","730 days","10 days"],"h1":"It is about six months.","h2":"In Louisiana, a driver 21 or older whose test shows 0.08 to 0.149 percent has driving privileges suspended for 180 days.","p":"Right. That result means a 180-day suspension."},"es":{"q":"En Luisiana, usted tiene 21 años o más y se hace la prueba de alcohol. El resultado es de 0.08 a 0.149 por ciento. ¿Por cuánto tiempo suspenden su licencia?","o":["180 días","30 días","730 días","10 días"],"h1":"Son unos seis meses.","h2":"En Luisiana, a un conductor de 21 años o más con un resultado de 0.08 a 0.149 por ciento le suspenden el privilegio de manejar por 180 días.","p":"Correcto. Ese resultado significa una suspensión de 180 días."},"zh":{"q":"在 Louisiana，你 21 岁或以上，做了酒精测试。结果是 0.08% 到 0.149%。你的驾照会被暂停多久？","o":["180 天","30 天","730 天","10 天"],"h1":"大约六个月。","h2":"在 Louisiana，21 岁或以上的司机测试结果为 0.08% 到 0.149% 时，驾驶权会被暂停 180 天。","p":"对。这个结果就是暂停 180 天。"},"vi":{"q":"Ở Louisiana, bạn từ 21 tuổi trở lên và làm bài thử nồng độ cồn. Kết quả là 0.08 đến 0.149 phần trăm. Bằng lái của bạn bị đình chỉ bao lâu?","o":["180 ngày","30 ngày","730 ngày","10 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở Louisiana, người lái từ 21 tuổi trở lên có kết quả thử từ 0.08 đến 0.149 phần trăm sẽ bị đình chỉ quyền lái xe 180 ngày.","p":"Đúng. Kết quả đó nghĩa là bị đình chỉ 180 ngày."},"tl":{"q":"Sa Louisiana, 21 ka o mas matanda at kumuha ka ng alcohol test. Ang resulta ay 0.08 hanggang 0.149 porsiyento. Gaano katagal masususpinde ang iyong lisensya?","o":["180 araw","30 araw","730 araw","10 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa Louisiana, ang driver na 21 o mas matanda na ang test ay 0.08 hanggang 0.149 porsiyento ay masususpinde ang karapatang magmaneho nang 180 araw.","p":"Tama. Ang resultang iyon ay 180 araw na suspensyon."},"ar":{"q":"في Louisiana، عمرك 21 سنة أو أكثر وأجريت اختبار الكحول. أظهر الاختبار من 0.08 إلى 0.149 بالمئة. كم مدة إيقاف رخصتك؟","o":["180 يومًا","30 يومًا","730 يومًا","10 أيام"],"h1":"المدة نحو ستة أشهر.","h2":"في Louisiana السائق الذي عمره 21 سنة أو أكثر ويُظهر اختباره من 0.08 إلى 0.149 بالمئة يُوقف حقه في القيادة 180 يومًا.","p":"صحيح. هذه النتيجة تعني إيقافًا لمدة 180 يومًا."},"ref":{"doc":"LA","page":126}},{"id":"la-038","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what does the law say about wearing headphones while you drive?","o":["They are allowed in both ears at low volume","They are banned only at night","You may not wear them in both ears","They are allowed if you are over 21"],"h1":"One ear is allowed.","h2":"In Louisiana, you may not wear headphones in both ears while driving, but one ear alone is allowed.","p":"Right. Never cover both ears while driving."},"es":{"q":"En Luisiana, ¿qué dice la ley sobre usar audífonos mientras maneja?","o":["Se permiten en los dos oídos con volumen bajo","Están prohibidos solo de noche","No puede usarlos en los dos oídos","Se permiten si tiene más de 21 años"],"h1":"Se permite en un oído.","h2":"En Luisiana, no puede usar audífonos en los dos oídos mientras maneja, pero sí se permite en un solo oído.","p":"Correcto. Nunca se cubra los dos oídos al manejar."},"zh":{"q":"在 Louisiana，关于开车时戴耳机，法律怎么说？","o":["音量小时两只耳朵都可以戴","只在晚上禁止","你不可以两只耳朵都戴","超过 21 岁就可以"],"h1":"一只耳朵是可以的。","h2":"在 Louisiana，开车时你不可以两只耳朵都戴耳机，但只戴一只耳朵是可以的。","p":"对。开车时绝不能把两只耳朵都盖住。"},"vi":{"q":"Ở Louisiana, luật nói gì về việc đeo tai nghe khi lái xe?","o":["Được đeo cả hai tai nếu âm lượng nhỏ","Chỉ bị cấm vào ban đêm","Bạn không được đeo cả hai tai","Được phép nếu bạn trên 21 tuổi"],"h1":"Một tai thì được phép.","h2":"Ở Louisiana, bạn không được đeo tai nghe ở cả hai tai khi lái xe, nhưng chỉ một tai thì được phép.","p":"Đúng. Không bao giờ che cả hai tai khi lái xe."},"tl":{"q":"Sa Louisiana, ano ang sinasabi ng batas tungkol sa pagsusuot ng headphones habang nagmamaneho?","o":["Puwede sa dalawang tainga kung mahina ang volume","Bawal lang sa gabi","Bawal mong isuot ang mga ito sa dalawang tainga","Puwede kung lampas 21 ka na"],"h1":"Puwede ang isang tainga.","h2":"Sa Louisiana, bawal kang magsuot ng headphones sa dalawang tainga habang nagmamaneho, pero puwede ang isang tainga lang.","p":"Tama. Huwag kailanman takpan ang dalawang tainga habang nagmamaneho."},"ar":{"q":"في Louisiana، ماذا يقول القانون عن وضع سماعات الأذن أثناء القيادة؟","o":["مسموحة في الأذنين معًا بصوت منخفض","ممنوعة في الليل فقط","لا يجوز لك وضعها في الأذنين معًا","مسموحة إذا كان عمرك أكثر من 21"],"h1":"أذن واحدة مسموحة.","h2":"في Louisiana لا يجوز لك وضع سماعات في الأذنين معًا أثناء القيادة، لكن أذنًا واحدة فقط مسموحة.","p":"صحيح. لا تغطِّ أذنيك الاثنتين أبدًا أثناء القيادة."},"ref":{"doc":"LA","page":97}},{"id":"la-039","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, what happens each time you are convicted of driving while your license is suspended?","o":["You get a warning only","Your suspension ends sooner","You must retake the vision test","Your suspension is extended by one year"],"h1":"It makes the suspension longer.","h2":"In Louisiana, each conviction for driving under suspension adds one more year to your suspension.","p":"Right. Each conviction adds one year."},"es":{"q":"En Luisiana, ¿qué pasa cada vez que lo condenan por manejar con la licencia suspendida?","o":["Solo recibe una advertencia","Su suspensión termina antes","Debe repetir el examen de la vista","Su suspensión se alarga un año"],"h1":"Hace que la suspensión dure más.","h2":"En Luisiana, cada condena por manejar con la licencia suspendida le agrega un año más a su suspensión.","p":"Correcto. Cada condena agrega un año."},"zh":{"q":"在 Louisiana，每次你因在驾照被暂停期间开车而被定罪，会发生什么？","o":["你只会收到警告","你的暂停会提早结束","你必须重新做视力检查","你的暂停会延长一年"],"h1":"它会让暂停时间更长。","h2":"在 Louisiana，每次因在暂停期间开车而被定罪，你的暂停就会再加一年。","p":"对。每次定罪加一年。"},"vi":{"q":"Ở Louisiana, điều gì xảy ra mỗi lần bạn bị kết án vì lái xe khi bằng lái đang bị đình chỉ?","o":["Bạn chỉ bị cảnh cáo","Thời gian đình chỉ kết thúc sớm hơn","Bạn phải thi lại thị lực","Thời gian đình chỉ bị kéo dài thêm một năm"],"h1":"Nó làm thời gian đình chỉ dài hơn.","h2":"Ở Louisiana, mỗi bản án vì lái xe khi đang bị đình chỉ sẽ cộng thêm một năm vào thời gian đình chỉ của bạn.","p":"Đúng. Mỗi bản án cộng thêm một năm."},"tl":{"q":"Sa Louisiana, ano ang mangyayari sa bawat conviction mo sa pagmamaneho habang suspendido ang iyong lisensya?","o":["Babala lang ang makukuha mo","Mas maagang matatapos ang suspensyon mo","Kailangan mong ulitin ang vision test","Madadagdagan ng isang taon ang suspensyon mo"],"h1":"Pinahahaba nito ang suspensyon.","h2":"Sa Louisiana, ang bawat conviction sa pagmamaneho habang suspendido ay nagdadagdag ng isa pang taon sa iyong suspensyon.","p":"Tama. Bawat conviction ay nagdadagdag ng isang taon."},"ar":{"q":"في Louisiana، ماذا يحدث في كل مرة تُدان فيها بالقيادة أثناء إيقاف رخصتك؟","o":["تحصل على تحذير فقط","ينتهي الإيقاف أسرع","يجب أن تعيد اختبار النظر","يُمدَّد الإيقاف سنة واحدة"],"h1":"تجعل الإيقاف أطول.","h2":"في Louisiana كل إدانة بالقيادة أثناء الإيقاف تضيف سنة أخرى إلى مدة إيقافك.","p":"صحيح. كل إدانة تضيف سنة واحدة."},"ref":{"doc":"LA","page":127}},{"id":"la-040","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, what happens to traffic fines in a construction zone?","o":["They are cut in half","They are doubled","They stay the same","They are tripled"],"h1":"Work zones carry a bigger penalty.","h2":"In Louisiana, traffic fines are doubled in construction zones.","p":"Right. Fines are doubled in work zones."},"es":{"q":"En Luisiana, ¿qué pasa con las multas de tránsito en una zona de construcción?","o":["Se reducen a la mitad","Se duplican","Siguen iguales","Se triplican"],"h1":"Las zonas de trabajo tienen una pena mayor.","h2":"En Luisiana, las multas de tránsito se duplican en las zonas de construcción.","p":"Correcto. Las multas se duplican en zonas de trabajo."},"zh":{"q":"在 Louisiana，在施工区内交通罚款会怎样？","o":["减半","加倍","不变","变成三倍"],"h1":"施工区的处罚更重。","h2":"在 Louisiana，施工区内的交通罚款加倍。","p":"对。施工区的罚款加倍。"},"vi":{"q":"Ở Louisiana, tiền phạt giao thông trong khu vực công trường thì sao?","o":["Giảm một nửa","Tăng gấp đôi","Giữ nguyên","Tăng gấp ba"],"h1":"Khu vực công trường bị phạt nặng hơn.","h2":"Ở Louisiana, tiền phạt giao thông trong khu vực công trường được tăng gấp đôi.","p":"Đúng. Tiền phạt tăng gấp đôi trong khu vực công trường."},"tl":{"q":"Sa Louisiana, ano ang nangyayari sa mga multa sa trapiko sa construction zone?","o":["Nababawasan ng kalahati","Dinodoble","Hindi nagbabago","Tinatriple"],"h1":"Mas mabigat ang parusa sa work zone.","h2":"Sa Louisiana, dinodoble ang mga multa sa trapiko sa mga construction zone.","p":"Tama. Dinodoble ang mga multa sa work zone."},"ar":{"q":"في Louisiana، ماذا يحدث لمخالفات المرور في منطقة الإنشاءات؟","o":["تُخفَّض إلى النصف","تتضاعف","تبقى كما هي","تصبح ثلاثة أضعاف"],"h1":"مناطق العمل عقوبتها أكبر.","h2":"في Louisiana تتضاعف غرامات المرور في مناطق الإنشاءات.","p":"صحيح. الغرامات تتضاعف في مناطق العمل."},"ref":{"doc":"LA","page":31}},{"id":"la-041","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, if no sign shows a different limit, what is the highest speed allowed on an interstate?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"It is between 65 and 75.","h2":"In Louisiana, the highest speed allowed on an interstate is 70 mph unless a sign shows a different limit.","p":"Right. The interstate limit is 70 mph unless posted otherwise."},"es":{"q":"En Luisiana, si ningún letrero indica otro límite, ¿cuál es la velocidad más alta permitida en una autopista interestatal?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"Está entre 65 y 75.","h2":"En Luisiana, la velocidad más alta permitida en una autopista interestatal es de 70 mph, a menos que un letrero indique otro límite.","p":"Correcto. El límite en la interestatal es de 70 mph, salvo que se indique otro."},"zh":{"q":"在 Louisiana，如果没有标志显示别的限速，州际公路上最高可以开多快？","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"在 65 和 75 之间。","h2":"在 Louisiana，除非标志显示别的限速，州际公路上的最高速度是 70 mph。","p":"对。除非另有标示，州际公路限速是 70 mph。"},"vi":{"q":"Ở Louisiana, nếu không có biển báo cho giới hạn khác, tốc độ cao nhất được phép trên xa lộ liên tiểu bang là bao nhiêu?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"Nó ở giữa 65 và 75.","h2":"Ở Louisiana, tốc độ cao nhất được phép trên xa lộ liên tiểu bang là 70 mph, trừ khi biển báo cho giới hạn khác.","p":"Đúng. Giới hạn trên xa lộ liên tiểu bang là 70 mph nếu không có biển báo khác."},"tl":{"q":"Sa Louisiana, kung walang karatula na nagpapakita ng ibang limit, ano ang pinakamataas na bilis na pinapayagan sa interstate?","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"Nasa pagitan ito ng 65 at 75.","h2":"Sa Louisiana, ang pinakamataas na bilis na pinapayagan sa interstate ay 70 mph, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 70 mph ang limit sa interstate maliban kung iba ang nakapaskil."},"ar":{"q":"في Louisiana، إذا لم تكن هناك لافتة تُظهر حدًّا آخر، ما أعلى سرعة مسموحة على الطريق السريع بين الولايات؟","o":["55 mph","65 mph","70 mph","80 mph"],"h1":"هي بين 65 و75.","h2":"في Louisiana أعلى سرعة مسموحة على الطريق السريع بين الولايات هي 70 mph، إلا إذا أظهرت لافتة حدًّا آخر.","p":"صحيح. الحد على الطريق السريع بين الولايات 70 mph ما لم تُظهر لافتة غير ذلك."},"ref":{"doc":"LA","page":100}},{"id":"la-042","scope":"LA","cat":"signals","sign":null,"c":0,"en":{"q":"In Louisiana, how far before a turn must you start giving your turn signal?","o":["At least 100 feet","At least 25 feet","At least 50 feet","At least 300 feet"],"h1":"It is about the length of a few houses.","h2":"In Louisiana, you must signal for at least 100 feet before you turn.","p":"Right. Signal for at least 100 feet before a turn."},"es":{"q":"En Luisiana, ¿a qué distancia antes de dar vuelta debe empezar a usar la direccional?","o":["Por lo menos 100 pies","Por lo menos 25 pies","Por lo menos 50 pies","Por lo menos 300 pies"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Luisiana, debe usar la direccional por lo menos 100 pies antes de dar vuelta.","p":"Correcto. Use la direccional por lo menos 100 pies antes de dar vuelta."},"zh":{"q":"在 Louisiana，转弯前多远必须开始打转向灯？","o":["至少 100 英尺","至少 25 英尺","至少 50 英尺","至少 300 英尺"],"h1":"大约几栋房子的长度。","h2":"在 Louisiana，转弯前你必须打转向灯至少 100 英尺。","p":"对。转弯前至少打灯 100 英尺。"},"vi":{"q":"Ở Louisiana, bạn phải bắt đầu bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 100 feet","Ít nhất 25 feet","Ít nhất 50 feet","Ít nhất 300 feet"],"h1":"Khoảng chiều dài của vài căn nhà.","h2":"Ở Louisiana, bạn phải bật đèn xi nhan ít nhất 100 feet trước khi rẽ.","p":"Đúng. Bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Louisiana, gaano kalayo bago lumiko dapat kang magsimulang mag-signal?","o":["Hindi bababa sa 100 talampakan","Hindi bababa sa 25 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 300 talampakan"],"h1":"Mga haba ito ng ilang bahay.","h2":"Sa Louisiana, dapat kang mag-signal nang hindi bababa sa 100 talampakan bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 100 talampakan bago lumiko."},"ar":{"q":"في Louisiana، على أي بعد قبل المنعطف يجب أن تبدأ بتشغيل إشارة الانعطاف؟","o":["100 قدم على الأقل","25 قدمًا على الأقل","50 قدمًا على الأقل","300 قدم على الأقل"],"h1":"المسافة نحو طول بضعة بيوت.","h2":"في Louisiana يجب أن تشغّل الإشارة لمسافة 100 قدم على الأقل قبل أن تنعطف.","p":"صحيح. شغّل الإشارة لمسافة 100 قدم على الأقل قبل الانعطاف."},"ref":{"doc":"LA","page":92}},{"id":"la-043","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, how far may you drive in a shared center left-turn lane?","o":["Up to half a mile","Up to 1,000 feet","As far as you like","No more than 200 feet"],"h1":"It is a short distance, only enough to get ready to turn.","h2":"In Louisiana, you may not drive more than 200 feet in a shared center left-turn lane.","p":"Right. Use no more than 200 feet of the center turn lane."},"es":{"q":"En Luisiana, ¿qué distancia puede recorrer en un carril central compartido para dar vuelta a la izquierda?","o":["Hasta media milla","Hasta 1,000 pies","Toda la que quiera","No más de 200 pies"],"h1":"Es una distancia corta, solo para prepararse para la vuelta.","h2":"En Luisiana, no puede recorrer más de 200 pies en un carril central compartido para dar vuelta a la izquierda.","p":"Correcto. No use más de 200 pies del carril central."},"zh":{"q":"在 Louisiana，你在中间共用左转车道里最多可以开多远？","o":["最多半英里","最多 1,000 英尺","想开多远都行","不超过 200 英尺"],"h1":"距离很短，只够准备转弯。","h2":"在 Louisiana，你在中间共用左转车道里开车不可以超过 200 英尺。","p":"对。中间转弯车道最多只用 200 英尺。"},"vi":{"q":"Ở Louisiana, bạn được chạy bao xa trong làn rẽ trái chung ở giữa đường?","o":["Tối đa nửa dặm","Tối đa 1,000 feet","Bao xa cũng được","Không quá 200 feet"],"h1":"Đó là một khoảng ngắn, chỉ đủ để chuẩn bị rẽ.","h2":"Ở Louisiana, bạn không được chạy quá 200 feet trong làn rẽ trái chung ở giữa đường.","p":"Đúng. Dùng làn rẽ ở giữa không quá 200 feet."},"tl":{"q":"Sa Louisiana, gaano kalayo ka puwedeng magmaneho sa shared center left-turn lane (pinagsasaluhang lane sa gitna para sa pagliko pakaliwa)?","o":["Hanggang kalahating milya","Hanggang 1,000 talampakan","Kahit gaano kalayo","Hindi lalampas sa 200 talampakan"],"h1":"Maikling distansya lang ito, sapat lang para maghanda sa pagliko.","h2":"Sa Louisiana, bawal kang magmaneho nang lampas sa 200 talampakan sa shared center left-turn lane.","p":"Tama. Huwag gumamit nang lampas sa 200 talampakan ng center turn lane."},"ar":{"q":"في Louisiana، ما المسافة التي يجوز لك قيادتها في مسار الانعطاف إلى اليسار المشترك في وسط الطريق؟","o":["حتى نصف ميل","حتى 1,000 قدم","أي مسافة تريدها","ليس أكثر من 200 قدم"],"h1":"المسافة قصيرة، تكفي فقط للاستعداد للانعطاف.","h2":"في Louisiana لا يجوز لك أن تقود أكثر من 200 قدم في مسار الانعطاف إلى اليسار المشترك في الوسط.","p":"صحيح. لا تستخدم أكثر من 200 قدم من مسار الانعطاف في الوسط."},"ref":{"doc":"LA","page":91}},{"id":"la-044","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, a school bus is stopped to load or unload children. How far from the bus must you stop?","o":["At least 5 feet","At least 10 feet","At least 30 feet","At least 100 feet"],"h1":"It is more than 20 feet.","h2":"In Louisiana, you must stop at least 30 feet from a school bus that is stopped to load or unload children.","p":"Right. Stop at least 30 feet from the bus."},"es":{"q":"En Luisiana, un autobús escolar está detenido para subir o bajar niños. ¿A qué distancia del autobús debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 10 pies","Por lo menos a 30 pies","Por lo menos a 100 pies"],"h1":"Es más de 20 pies.","h2":"En Luisiana, debe detenerse por lo menos a 30 pies de un autobús escolar detenido para subir o bajar niños.","p":"Correcto. Deténgase por lo menos a 30 pies del autobús."},"zh":{"q":"在 Louisiana，一辆校车停下来让孩子上下车。你必须在离校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 30 英尺","至少 100 英尺"],"h1":"超过 20 英尺。","h2":"在 Louisiana，校车停下来让孩子上下车时，你必须在离校车至少 30 英尺的地方停车。","p":"对。在离校车至少 30 英尺的地方停车。"},"vi":{"q":"Ở Louisiana, một xe buýt trường học đang dừng để đón hoặc thả trẻ em. Bạn phải dừng cách xe buýt bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 30 feet","Ít nhất 100 feet"],"h1":"Hơn 20 feet.","h2":"Ở Louisiana, bạn phải dừng cách ít nhất 30 feet so với xe buýt trường học đang dừng để đón hoặc thả trẻ em.","p":"Đúng. Dừng cách xe buýt ít nhất 30 feet."},"tl":{"q":"Sa Louisiana, nakahinto ang school bus para magsakay o magbaba ng mga bata. Gaano kalayo sa bus ka dapat huminto?","o":["Hindi bababa sa 5 talampakan","Hindi bababa sa 10 talampakan","Hindi bababa sa 30 talampakan","Hindi bababa sa 100 talampakan"],"h1":"Higit ito sa 20 talampakan.","h2":"Sa Louisiana, dapat kang huminto nang hindi bababa sa 30 talampakan mula sa school bus na nakahinto para magsakay o magbaba ng mga bata.","p":"Tama. Huminto nang hindi bababa sa 30 talampakan mula sa bus."},"ar":{"q":"في Louisiana، حافلة مدرسية متوقفة لإركاب الأطفال أو إنزالهم. على أي بعد من الحافلة يجب أن تتوقف؟","o":["5 أقدام على الأقل","10 أقدام على الأقل","30 قدمًا على الأقل","100 قدم على الأقل"],"h1":"المسافة أكثر من 20 قدمًا.","h2":"في Louisiana يجب أن تتوقف على بعد 30 قدمًا على الأقل من حافلة مدرسية متوقفة لإركاب الأطفال أو إنزالهم.","p":"صحيح. توقف على بعد 30 قدمًا على الأقل من الحافلة."},"ref":{"doc":"LA","page":88}},{"id":"la-045","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, the lights are flashing at a railroad crossing and a train is coming. Where must you stop?","o":["Right at the first rail","Between 15 and 50 feet from the nearest rail","Between 50 and 100 feet from the nearest rail","Anywhere you can see the train"],"h1":"Not too close and not too far.","h2":"In Louisiana, you must stop no closer than 15 feet and no farther than 50 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Luisiana, las luces de un cruce de ferrocarril están destellando y viene un tren. ¿Dónde debe detenerse?","o":["Justo en el primer riel","Entre 15 y 50 pies del riel más cercano","Entre 50 y 100 pies del riel más cercano","En cualquier lugar donde vea el tren"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Luisiana, debe detenerse a no menos de 15 pies y a no más de 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Louisiana，铁路道口的灯在闪，火车正在开过来。你必须停在哪里？","o":["就停在第一条铁轨旁","离最近的铁轨 15 到 50 英尺之间","离最近的铁轨 50 到 100 英尺之间","任何能看到火车的地方"],"h1":"不能太近，也不能太远。","h2":"在 Louisiana，你必须停在离最近的铁轨不少于 15 英尺、不超过 50 英尺的地方。","p":"对。停在离最近的铁轨 15 到 50 英尺之间。"},"vi":{"q":"Ở Louisiana, đèn đang nhấp nháy ở chỗ băng qua đường ray và có xe lửa đang tới. Bạn phải dừng ở đâu?","o":["Ngay tại đường ray đầu tiên","Cách đường ray gần nhất từ 15 đến 50 feet","Cách đường ray gần nhất từ 50 đến 100 feet","Bất cứ chỗ nào bạn thấy được xe lửa"],"h1":"Không quá gần và không quá xa.","h2":"Ở Louisiana, bạn phải dừng cách đường ray gần nhất không gần hơn 15 feet và không xa hơn 50 feet.","p":"Đúng. Dừng cách đường ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Louisiana, kumikislap ang mga ilaw sa tawiran ng riles at may paparating na tren. Saan ka dapat huminto?","o":["Mismo sa unang riles","Sa pagitan ng 15 at 50 talampakan mula sa pinakamalapit na riles","Sa pagitan ng 50 at 100 talampakan mula sa pinakamalapit na riles","Kahit saan na nakikita mo ang tren"],"h1":"Hindi masyadong malapit at hindi masyadong malayo.","h2":"Sa Louisiana, dapat kang huminto nang hindi lalapit sa 15 talampakan at hindi lalayo sa 50 talampakan mula sa pinakamalapit na riles.","p":"Tama. Huminto sa pagitan ng 15 at 50 talampakan mula sa pinakamalapit na riles."},"ar":{"q":"في Louisiana، الأضواء تومض عند معبر سكة الحديد وقطار قادم. أين يجب أن تتوقف؟","o":["عند السكة الأولى مباشرة","بين 15 و50 قدمًا من أقرب سكة","بين 50 و100 قدم من أقرب سكة","في أي مكان ترى منه القطار"],"h1":"ليس قريبًا جدًا وليس بعيدًا جدًا.","h2":"في Louisiana يجب أن تتوقف على بعد ليس أقل من 15 قدمًا وليس أكثر من 50 قدمًا من أقرب سكة.","p":"صحيح. توقف على بعد بين 15 و50 قدمًا من أقرب سكة."},"ref":{"doc":"LA","page":94}},{"id":"la-046","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, how close to an intersection, railroad crossing, bridge or tunnel may you pass another vehicle?","o":["No closer than 100 feet","No closer than 25 feet","No closer than 50 feet","Any distance, if the road is clear"],"h1":"It is more than 50 feet.","h2":"In Louisiana, you may not pass another vehicle within 100 feet of an intersection, railroad crossing, bridge or tunnel.","p":"Right. Do not pass within 100 feet of those places."},"es":{"q":"En Luisiana, ¿qué tan cerca de una intersección, un cruce de ferrocarril, un puente o un túnel puede rebasar a otro vehículo?","o":["No a menos de 100 pies","No a menos de 25 pies","No a menos de 50 pies","A cualquier distancia, si el camino está libre"],"h1":"Es más de 50 pies.","h2":"En Luisiana, no puede rebasar a otro vehículo a menos de 100 pies de una intersección, un cruce de ferrocarril, un puente o un túnel.","p":"Correcto. No rebase a menos de 100 pies de esos lugares."},"zh":{"q":"在 Louisiana，在离路口、铁路道口、桥或隧道多近的地方你可以超车？","o":["不少于 100 英尺","不少于 25 英尺","不少于 50 英尺","只要路上没车，多近都行"],"h1":"超过 50 英尺。","h2":"在 Louisiana，你不可以在路口、铁路道口、桥或隧道 100 英尺以内超车。","p":"对。不要在这些地方 100 英尺以内超车。"},"vi":{"q":"Ở Louisiana, bạn được vượt xe khác khi cách giao lộ, chỗ băng qua đường ray, cầu hoặc đường hầm bao gần?","o":["Không gần hơn 100 feet","Không gần hơn 25 feet","Không gần hơn 50 feet","Khoảng cách nào cũng được, nếu đường trống"],"h1":"Hơn 50 feet.","h2":"Ở Louisiana, bạn không được vượt xe khác trong vòng 100 feet tính từ giao lộ, chỗ băng qua đường ray, cầu hoặc đường hầm.","p":"Đúng. Không vượt xe trong vòng 100 feet từ những chỗ đó."},"tl":{"q":"Sa Louisiana, gaano kalapit sa intersection, tawiran ng riles, tulay o tunnel ka puwedeng mag-overtake ng ibang sasakyan?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan","Kahit anong distansya, kung maluwag ang daan"],"h1":"Higit ito sa 50 talampakan.","h2":"Sa Louisiana, bawal kang mag-overtake ng ibang sasakyan sa loob ng 100 talampakan mula sa intersection, tawiran ng riles, tulay o tunnel.","p":"Tama. Huwag mag-overtake sa loob ng 100 talampakan mula sa mga lugar na iyon."},"ar":{"q":"في Louisiana، على أي قرب من تقاطع أو معبر سكة حديد أو جسر أو نفق يجوز لك أن تتجاوز سيارة أخرى؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا","أي مسافة، إذا كان الطريق خاليًا"],"h1":"المسافة أكثر من 50 قدمًا.","h2":"في Louisiana لا يجوز لك تجاوز سيارة أخرى على بعد أقل من 100 قدم من تقاطع أو معبر سكة حديد أو جسر أو نفق.","p":"صحيح. لا تتجاوز على بعد أقل من 100 قدم من هذه الأماكن."},"ref":{"doc":"LA","page":71}},{"id":"la-047","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 15 feet"],"h1":"It is less than the distance for a railroad crossing.","h2":"In Louisiana, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Luisiana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies","No a menos de 15 pies"],"h1":"Es menos que la distancia para un cruce de ferrocarril.","h2":"En Luisiana, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 Louisiana，你可以在离消防栓多近的地方停车？","o":["不少于 5 英尺","不少于 10 英尺","不少于 30 英尺","不少于 15 英尺"],"h1":"比铁路道口的距离短。","h2":"在 Louisiana，你不可以在消防栓 15 英尺以内停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Louisiana, bạn được đậu xe cách trụ nước cứu hỏa bao gần?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 30 feet","Không gần hơn 15 feet"],"h1":"Ít hơn khoảng cách ở chỗ băng qua đường ray.","h2":"Ở Louisiana, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Đậu cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Louisiana, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 30 talampakan","Hindi lalapit sa 15 talampakan"],"h1":"Mas maikli ito kaysa sa distansya para sa tawiran ng riles.","h2":"Sa Louisiana, bawal pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa hydrant."},"ar":{"q":"في Louisiana، على أي قرب من صنبور إطفاء الحريق يجوز لك أن تقف بسيارتك؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 15 قدمًا"],"h1":"المسافة أقل من مسافة معبر سكة الحديد.","h2":"في Louisiana لا يجوز لك الوقوف على بعد أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من صنبور الإطفاء."},"ref":{"doc":"LA","page":70}},{"id":"la-048","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, how much space must you leave when you pass a bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Louisiana, you must leave at least 3 feet between your car and a bicycle you are passing.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Luisiana, ¿cuánto espacio debe dejar cuando rebasa a una bicicleta?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 3 pies","Por lo menos 10 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Luisiana, debe dejar por lo menos 3 pies entre su carro y la bicicleta que está rebasando.","p":"Correcto. Deje a la bicicleta por lo menos 3 pies."},"zh":{"q":"在 Louisiana，你超过自行车时必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"大约一把码尺那么长。","h2":"在 Louisiana，你超过自行车时，你的车和自行车之间必须留出至少 3 英尺。","p":"对。给自行车留至少 3 英尺。"},"vi":{"q":"Ở Louisiana, bạn phải chừa khoảng cách bao nhiêu khi vượt xe đạp?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Khoảng chiều dài của một cây thước yard.","h2":"Ở Louisiana, bạn phải chừa ít nhất 3 feet giữa xe của bạn và chiếc xe đạp bạn đang vượt.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Louisiana, gaano kalaking espasyo ang dapat mong iwan kapag nag-o-overtake ka sa bisikleta?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 10 talampakan"],"h1":"Mga haba ito ng isang yardstick.","h2":"Sa Louisiana, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng iyong kotse at ng bisikletang inu-overtake mo.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Louisiana، ما المسافة التي يجب أن تتركها عندما تتجاوز دراجة هوائية؟","o":["قدم واحدة (1) على الأقل","قدمان (2) على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"المسافة نحو طول مسطرة الياردة.","h2":"في Louisiana يجب أن تترك 3 أقدام على الأقل بين سيارتك والدراجة الهوائية التي تتجاوزها.","p":"صحيح. اترك للدراجة الهوائية 3 أقدام على الأقل."},"ref":{"doc":"LA","page":80}},{"id":"la-049","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, children under what age must wear an approved helmet when they ride a bicycle?","o":["12","8","16","18"],"h1":"It is the age just before becoming a teenager.","h2":"In Louisiana, children under age 12 must wear an approved helmet when riding a bicycle or riding on one as a passenger.","p":"Right. Children under 12 must wear a bicycle helmet."},"es":{"q":"En Luisiana, ¿los niños menores de qué edad deben usar un casco aprobado cuando andan en bicicleta?","o":["12","8","16","18"],"h1":"Es la edad justo antes de ser adolescente.","h2":"En Luisiana, los niños menores de 12 años deben usar un casco aprobado cuando manejan una bicicleta o van en ella como pasajeros.","p":"Correcto. Los niños menores de 12 años deben usar casco de bicicleta."},"zh":{"q":"在 Louisiana，几岁以下的孩子骑自行车时必须戴合格的头盔？","o":["12","8","16","18"],"h1":"就是刚好成为青少年之前的年龄。","h2":"在 Louisiana，12 岁以下的孩子骑自行车或坐在自行车上当乘客时，必须戴合格的头盔。","p":"对。12 岁以下的孩子必须戴自行车头盔。"},"vi":{"q":"Ở Louisiana, trẻ em dưới bao nhiêu tuổi phải đội mũ bảo hiểm đạt chuẩn khi đi xe đạp?","o":["12","8","16","18"],"h1":"Đó là tuổi ngay trước khi thành thiếu niên.","h2":"Ở Louisiana, trẻ em dưới 12 tuổi phải đội mũ bảo hiểm đạt chuẩn khi đi xe đạp hoặc ngồi trên xe đạp như hành khách.","p":"Đúng. Trẻ em dưới 12 tuổi phải đội mũ bảo hiểm xe đạp."},"tl":{"q":"Sa Louisiana, ang mga batang wala pang ilang taon ang dapat magsuot ng aprubadong helmet kapag nagbibisikleta?","o":["12","8","16","18"],"h1":"Ito ang edad bago maging teenager.","h2":"Sa Louisiana, ang mga batang wala pang 12 taong gulang ay dapat magsuot ng aprubadong helmet kapag nagbibisikleta o sumasakay bilang pasahero sa bisikleta.","p":"Tama. Ang mga batang wala pang 12 ay dapat magsuot ng helmet sa bisikleta."},"ar":{"q":"في Louisiana، الأطفال الذين أعمارهم أقل من كم يجب أن يلبسوا خوذة معتمدة عندما يركبون دراجة هوائية؟","o":["12","8","16","18"],"h1":"هو العمر الذي يسبق سن المراهقة مباشرة.","h2":"في Louisiana يجب على الأطفال الذين أعمارهم أقل من 12 سنة أن يلبسوا خوذة معتمدة عندما يقودون دراجة هوائية أو يركبون عليها كركّاب.","p":"صحيح. يجب على الأطفال تحت 12 سنة لبس خوذة الدراجة."},"ref":{"doc":"LA","page":81}},{"id":"la-050","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, who may ride in the open bed of a pickup truck on an interstate highway?","o":["Anyone 12 or older","Anyone 18 or older","Adults wearing a seat belt","No one, of any age"],"h1":"The interstate rule has no age exception.","h2":"In Louisiana, no one of any age may ride in the open bed of a truck on an interstate highway.","p":"Right. No one may ride in an open truck bed on the interstate."},"es":{"q":"En Luisiana, ¿quién puede ir en la caja abierta de una camioneta pickup en una autopista interestatal?","o":["Cualquier persona de 12 años o más","Cualquier persona de 18 años o más","Los adultos con cinturón de seguridad","Nadie, de ninguna edad"],"h1":"La regla de la interestatal no tiene excepción de edad.","h2":"En Luisiana, nadie, de ninguna edad, puede ir en la caja abierta de un camión en una autopista interestatal.","p":"Correcto. Nadie puede ir en la caja abierta en la interestatal."},"zh":{"q":"在 Louisiana，在州际公路上谁可以坐在皮卡车敞开的后斗里？","o":["12 岁或以上的人","18 岁或以上的人","系安全带的成年人","任何年龄的人都不可以"],"h1":"州际公路的规定没有年龄例外。","h2":"在 Louisiana，在州际公路上任何年龄的人都不可以坐在卡车敞开的后斗里。","p":"对。在州际公路上，任何人都不可以坐在敞开的卡车后斗里。"},"vi":{"q":"Ở Louisiana, ai được ngồi trong thùng sau để hở của xe bán tải trên xa lộ liên tiểu bang?","o":["Bất kỳ ai từ 12 tuổi trở lên","Bất kỳ ai từ 18 tuổi trở lên","Người lớn có thắt dây an toàn","Không ai cả, ở bất kỳ tuổi nào"],"h1":"Luật trên xa lộ liên tiểu bang không có ngoại lệ về tuổi.","h2":"Ở Louisiana, không ai ở bất kỳ tuổi nào được ngồi trong thùng sau để hở của xe tải trên xa lộ liên tiểu bang.","p":"Đúng. Không ai được ngồi trong thùng xe tải để hở trên xa lộ liên tiểu bang."},"tl":{"q":"Sa Louisiana, sino ang puwedeng sumakay sa bukas na likuran (bed) ng pickup truck sa interstate highway?","o":["Kahit sino na 12 o mas matanda","Kahit sino na 18 o mas matanda","Mga adult na naka-seat belt","Wala, kahit anong edad"],"h1":"Walang exception sa edad ang patakaran sa interstate.","h2":"Sa Louisiana, walang sinuman, kahit anong edad, ang puwedeng sumakay sa bukas na likuran ng truck sa interstate highway.","p":"Tama. Walang puwedeng sumakay sa bukas na likuran ng truck sa interstate."},"ar":{"q":"في Louisiana، من يجوز له الركوب في الصندوق الخلفي المكشوف لشاحنة بيك أب على الطريق السريع بين الولايات؟","o":["أي شخص عمره 12 سنة أو أكثر","أي شخص عمره 18 سنة أو أكثر","البالغون الذين يربطون حزام الأمان","لا أحد، من أي عمر"],"h1":"قاعدة الطريق السريع بين الولايات ليس فيها استثناء للعمر.","h2":"في Louisiana لا يجوز لأي شخص من أي عمر أن يركب في الصندوق الخلفي المكشوف لشاحنة على الطريق السريع بين الولايات.","p":"صحيح. لا يجوز لأحد أن يركب في صندوق شاحنة مكشوف على الطريق السريع بين الولايات."},"ref":{"doc":"LA","page":96}},{"id":"la-051","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, how close may you follow a fire truck or other emergency vehicle that is answering a call?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","Any distance, if you keep up"],"h1":"It is much farther than a few car lengths.","h2":"In Louisiana, it is against the law to follow an emergency vehicle answering a call closer than 500 feet.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En Luisiana, ¿qué tan cerca puede seguir a un camión de bomberos u otro vehículo de emergencia que atiende una llamada?","o":["No a menos de 100 pies","No a menos de 500 pies","No a menos de 50 pies","A cualquier distancia, si mantiene la velocidad"],"h1":"Es mucho más que unos cuantos largos de carro.","h2":"En Luisiana, es ilegal seguir a menos de 500 pies a un vehículo de emergencia que atiende una llamada.","p":"Correcto. Quédese al menos a 500 pies detrás."},"zh":{"q":"在 Louisiana，你可以跟在正在出警的消防车或其他紧急车辆后面多近？","o":["不少于 100 英尺","不少于 500 英尺","不少于 50 英尺","多近都行，只要跟得上"],"h1":"比几个车身的长度远得多。","h2":"在 Louisiana，跟在正在出警的紧急车辆后面 500 英尺以内是违法的。","p":"对。至少保持在后面 500 英尺。"},"vi":{"q":"Ở Louisiana, bạn được chạy theo sau xe cứu hỏa hoặc xe khẩn cấp khác đang đi làm nhiệm vụ gần đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 50 feet","Khoảng cách nào cũng được, nếu bạn theo kịp"],"h1":"Xa hơn nhiều so với chiều dài vài chiếc xe.","h2":"Ở Louisiana, chạy theo sau xe khẩn cấp đang đi làm nhiệm vụ gần hơn 500 feet là phạm pháp.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet phía sau."},"tl":{"q":"Sa Louisiana, gaano kalapit ka puwedeng sumunod sa fire truck o ibang emergency vehicle na rumeresponde sa tawag?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 500 talampakan","Hindi lalapit sa 50 talampakan","Kahit anong distansya, basta nakakasabay ka"],"h1":"Mas malayo ito kaysa sa haba ng ilang kotse.","h2":"Sa Louisiana, labag sa batas ang sumunod sa emergency vehicle na rumeresponde sa tawag nang mas malapit sa 500 talampakan.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likuran."},"ar":{"q":"في Louisiana، على أي قرب يجوز لك أن تسير خلف سيارة إطفاء أو سيارة طوارئ أخرى تستجيب لنداء؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 500 قدم","ليس أقرب من 50 قدمًا","أي مسافة، إذا كنت تلحق بها"],"h1":"المسافة أبعد بكثير من طول بضع سيارات.","h2":"في Louisiana السير خلف سيارة طوارئ تستجيب لنداء على بعد أقل من 500 قدم ممنوع قانونًا.","p":"صحيح. ابقَ خلفها على بعد 500 قدم على الأقل."},"ref":{"doc":"LA","page":97}},{"id":"la-052","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, you live in another state and have a valid license from there. How long may you drive in Louisiana with it?","o":["30 days","60 days","90 days","One year"],"h1":"Think of a visit of about three months.","h2":"In Louisiana, a non-resident with a valid license from another state may drive for 90 days.","p":"Right! A visitor may drive for 90 days."},"es":{"q":"En Louisiana, usted vive en otro estado y tiene una licencia válida de allí. ¿Por cuánto tiempo puede manejar en Louisiana con ella?","o":["30 días","60 días","90 días","Un año"],"h1":"Piense en una visita de unos tres meses.","h2":"En Louisiana, una persona no residente con una licencia válida de otro estado puede manejar durante 90 días.","p":"¡Correcto! Un visitante puede manejar durante 90 días."},"ref":{"doc":"LA","page":1}},{"id":"la-053","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, which license class is for a regular single vehicle that weighs under 10,001 pounds?","o":["Class E","Class D","Class C","Class A"],"h1":"It is the license most new drivers get.","h2":"In Louisiana, a Class E license is for a single motor vehicle under 10,001 pounds, like a regular car.","p":"Yes! Class E is the regular car license."},"es":{"q":"En Louisiana, ¿qué clase de licencia es para un vehículo sencillo que pesa menos de 10,001 libras?","o":["Clase E","Clase D","Clase C","Clase A"],"h1":"Es la licencia que obtiene la mayoría de los conductores nuevos.","h2":"En Louisiana, la licencia Clase E es para un vehículo motorizado sencillo de menos de 10,001 libras, como un carro común.","p":"¡Sí! La Clase E es la licencia para carros comunes."},"ref":{"doc":"LA","page":2}},{"id":"la-054","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, which license do you need to drive a single work vehicle of 10,001 to 26,000 pounds that does not carry hazardous materials?","o":["Class E","Class M","Class A","Class D"],"h1":"It is called the chauffeur's license.","h2":"In Louisiana, a Class D (chauffeur's) license covers a single vehicle used in business from 10,001 to 26,000 pounds.","p":"Correct! That is a Class D license."},"es":{"q":"En Louisiana, ¿qué licencia necesita para manejar un vehículo de trabajo sencillo de 10,001 a 26,000 libras que no lleva materiales peligrosos?","o":["Clase E","Clase M","Clase A","Clase D"],"h1":"Se llama licencia de chofer.","h2":"En Louisiana, la licencia Clase D (de chofer) cubre un vehículo sencillo de uso comercial de 10,001 a 26,000 libras.","p":"¡Correcto! Es una licencia Clase D."},"ref":{"doc":"LA","page":1}},{"id":"la-055","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the youngest age to get a Class D (chauffeur's) license?","o":["16","17","18","21"],"h1":"It is one year after the intermediate license age.","h2":"In Louisiana, you must be at least 17 years old to get a Class D license.","p":"Right! The minimum age for Class D is 17."},"es":{"q":"En Louisiana, ¿cuál es la edad mínima para obtener una licencia Clase D (de chofer)?","o":["16","17","18","21"],"h1":"Es un año después de la edad de la licencia intermedia.","h2":"En Louisiana, debe tener al menos 17 años para obtener una licencia Clase D.","p":"¡Correcto! La edad mínima para la Clase D es 17 años."},"ref":{"doc":"LA","page":128}},{"id":"la-056","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, when may a student use a Temporary Instruction Permit (TIP)?","o":["Any time a licensed adult is in the car","Only while enrolled in a driver education or pre-licensing course","Only to drive to and from school","Only after turning 17"],"h1":"It is tied to a course.","h2":"In Louisiana, a Temporary Instruction Permit may be used only while the student is enrolled in a driver education or pre-licensing course.","p":"Yes! A TIP is only for students in a course."},"es":{"q":"En Louisiana, ¿cuándo puede un estudiante usar un Permiso Temporal de Instrucción (TIP)?","o":["En cualquier momento con un adulto con licencia en el carro","Solo mientras esté inscrito en un curso de educación vial o de prelicencia","Solo para ir y volver de la escuela","Solo después de cumplir 17 años"],"h1":"Está ligado a un curso.","h2":"En Louisiana, el Permiso Temporal de Instrucción solo se puede usar mientras el estudiante esté inscrito en un curso de educación vial o de prelicencia.","p":"¡Sí! El TIP es solo para estudiantes de un curso."},"ref":{"doc":"LA","page":2}},{"id":"la-057","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what must a student get before any behind-the-wheel lesson or license test?","o":["An intermediate license","A vehicle registration","A Temporary Instruction Permit (TIP)","A Class D license"],"h1":"It is a permit for students.","h2":"In Louisiana, a student must get a Temporary Instruction Permit before the knowledge test, the skills test or any behind-the-wheel instruction.","p":"Correct! First you get a TIP."},"es":{"q":"En Louisiana, ¿qué debe obtener un estudiante antes de cualquier clase práctica al volante o examen de licencia?","o":["Una licencia intermedia","Un registro de vehículo","Un Permiso Temporal de Instrucción (TIP)","Una licencia Clase D"],"h1":"Es un permiso para estudiantes.","h2":"En Louisiana, el estudiante debe obtener un Permiso Temporal de Instrucción antes del examen de conocimientos, del examen práctico o de cualquier clase al volante.","p":"¡Correcto! Primero se obtiene el TIP."},"ref":{"doc":"LA","page":3}},{"id":"la-058","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you bring a notarized photocopy of your birth certificate to the OMV. Will it be accepted?","o":["No, only originals or certified copies are accepted","Yes, because it is notarized","Yes, if it is in color","Yes, if you also bring a utility bill"],"h1":"A stamp from a notary is not enough.","h2":"In Louisiana, identity documents must be originals or certified copies; photocopies are not accepted, even if notarized.","p":"Right! Bring the original or a certified copy."},"es":{"q":"En Louisiana, usted lleva a la OMV una fotocopia notariada de su acta de nacimiento. ¿La aceptarán?","o":["No, solo se aceptan originales o copias certificadas","Sí, porque está notariada","Sí, si es a color","Sí, si también lleva una factura de servicios"],"h1":"El sello de un notario no es suficiente.","h2":"En Louisiana, los documentos de identidad deben ser originales o copias certificadas; no se aceptan fotocopias, aunque estén notariadas.","p":"¡Correcto! Lleve el original o una copia certificada."},"ref":{"doc":"LA","page":2}},{"id":"la-059","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, which set of identity documents may a first-time applicant bring?","o":["One secondary document only","Three secondary documents","One primary document only","One primary and two secondary documents"],"h1":"You need more than one document, and at least one primary.","h2":"In Louisiana, a first-time applicant brings one primary and two secondary documents, or two primary documents.","p":"Correct! One primary and two secondary documents work."},"es":{"q":"En Louisiana, ¿qué grupo de documentos de identidad puede llevar una persona que solicita por primera vez?","o":["Solo un documento secundario","Tres documentos secundarios","Solo un documento primario","Un documento primario y dos secundarios"],"h1":"Necesita más de un documento y al menos uno primario.","h2":"En Louisiana, quien solicita por primera vez lleva un documento primario y dos secundarios, o dos documentos primarios.","p":"¡Correcto! Un documento primario y dos secundarios sirven."},"ref":{"doc":"LA","page":2}},{"id":"la-060","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, a teen's parents share joint custody. Who may sign the teen's license application?","o":["Either parent, whichever comes to the office","Only the domiciliary parent, the one the teen mainly lives with","Both parents together, in person","Any adult relative with a valid ID"],"h1":"Think of the parent at the teen's main home.","h2":"In Louisiana, when parents have joint custody, only the domiciliary parent may sign a minor's license application.","p":"Yes! Only the domiciliary parent signs."},"es":{"q":"En Louisiana, los padres de un adolescente tienen custodia compartida. ¿Quién puede firmar la solicitud de licencia del adolescente?","o":["Cualquiera de los padres, el que vaya a la oficina","Solo el padre o la madre domiciliario, con quien el adolescente vive principalmente","Los dos padres juntos, en persona","Cualquier pariente adulto con identificación válida"],"h1":"Piense en el padre o la madre del hogar principal.","h2":"En Louisiana, cuando los padres tienen custodia compartida, solo el padre o la madre domiciliario puede firmar la solicitud de licencia de un menor.","p":"¡Sí! Solo firma el padre o la madre domiciliario."},"ref":{"doc":"LA","page":3}},{"id":"la-061","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, you move here with a valid license from another state. What happens to that license when you apply?","o":["You keep it as a backup","It stays valid for one more year","You must surrender it, because you may hold only one license","It is stamped and given back to you"],"h1":"You may not have two licenses.","h2":"In Louisiana, you must surrender your out-of-state license, because it is unlawful to have more than one driver's license.","p":"Correct! You hand in the old license."},"es":{"q":"En Louisiana, usted se muda aquí con una licencia válida de otro estado. ¿Qué pasa con esa licencia cuando solicita la nueva?","o":["La guarda como respaldo","Sigue siendo válida por un año más","Debe entregarla, porque solo puede tener una licencia","Se la sellan y se la devuelven"],"h1":"No puede tener dos licencias.","h2":"En Louisiana, debe entregar su licencia de otro estado, porque es ilegal tener más de una licencia de conducir.","p":"¡Correcto! Usted entrega la licencia anterior."},"ref":{"doc":"LA","page":3}},{"id":"la-062","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you are moving from another state but lost your old license. What must you bring to apply?","o":["A letter of clearance or an official driving record from that state","A photo of your old license","A letter from your employer","Nothing; the OMV will look it up"],"h1":"You need an official paper from your last state.","h2":"In Louisiana, if you do not have your out-of-state license, you must bring a letter of clearance or an official driving record from your last state.","p":"Right! Bring a clearance letter or your driving record."},"es":{"q":"En Louisiana, usted viene de otro estado pero perdió su licencia anterior. ¿Qué debe llevar para solicitar?","o":["Una carta de autorización o un historial de manejo oficial de ese estado","Una foto de su licencia anterior","Una carta de su empleador","Nada; la OMV lo buscará"],"h1":"Necesita un papel oficial de su último estado.","h2":"En Louisiana, si no tiene su licencia de otro estado, debe llevar una carta de autorización o un historial de manejo oficial de su último estado.","p":"¡Correcto! Lleve la carta o su historial de manejo."},"ref":{"doc":"LA","page":3}},{"id":"la-063","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, which applicants must give a Social Security number so they can be signed up with the Selective Service?","o":["All women over 18","Anyone over 65","Only commercial drivers","Male U.S. citizens and immigrants ages 15 to 26"],"h1":"The Selective Service registers young men.","h2":"In Louisiana, male U.S. citizens and immigrants ages 15 to 26 must give their Social Security number for the Selective Service when they apply.","p":"Yes! It applies to males ages 15 to 26."},"es":{"q":"En Louisiana, ¿qué solicitantes deben dar su número de Seguro Social para quedar inscritos en el Servicio Selectivo?","o":["Todas las mujeres mayores de 18","Cualquier persona mayor de 65","Solo los conductores comerciales","Hombres ciudadanos e inmigrantes de 15 a 26 años"],"h1":"El Servicio Selectivo inscribe a hombres jóvenes.","h2":"En Louisiana, los hombres ciudadanos e inmigrantes de 15 a 26 años deben dar su número de Seguro Social para el Servicio Selectivo al solicitar.","p":"¡Sí! Aplica a hombres de 15 a 26 años."},"ref":{"doc":"LA","page":3}},{"id":"la-064","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, how old must you be to drive a commercial vehicle across state lines or to carry hazardous materials?","o":["21","18","19","25"],"h1":"It is older than the age to drive a commercial vehicle only inside the state.","h2":"In Louisiana, you must be at least 21 to drive a commercial vehicle between states or to get a hazardous materials endorsement.","p":"Correct! The age is 21."},"es":{"q":"En Louisiana, ¿qué edad debe tener para manejar un vehículo comercial entre estados o para llevar materiales peligrosos?","o":["21","18","19","25"],"h1":"Es mayor que la edad para manejar un vehículo comercial solo dentro del estado.","h2":"En Louisiana, debe tener al menos 21 años para manejar un vehículo comercial entre estados o para obtener el endoso de materiales peligrosos.","p":"¡Correcto! La edad es 21 años."},"ref":{"doc":"LA","page":4}},{"id":"la-065","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what is the graduated licensing law for teens called?","o":["The Safe Teen Act","The Louisiana Learner Law","The R.Y.A.N. Act (Reduce Youth Accidents Now)","The Teen Driver Promise"],"h1":"It is named after a 15-year-old who died in a crash.","h2":"In Louisiana, the graduated licensing program is the R.Y.A.N. Act, which stands for Reduce Youth Accidents Now.","p":"Right! It is the R.Y.A.N. Act."},"es":{"q":"En Louisiana, ¿cómo se llama la ley de licencias graduales para adolescentes?","o":["La Ley del Adolescente Seguro","La Ley del Aprendiz de Louisiana","La Ley R.Y.A.N. (Reduce Youth Accidents Now)","La Promesa del Conductor Joven"],"h1":"Lleva el nombre de un joven de 15 años que murió en un choque.","h2":"En Louisiana, el programa de licencias graduales es la Ley R.Y.A.N., que significa reducir los accidentes de jóvenes ahora.","p":"¡Correcto! Es la Ley R.Y.A.N."},"ref":{"doc":"LA","page":6}},{"id":"la-066","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what score must a teen earn on the road skills driving test to get an intermediate license?","o":["70 percent","80 percent","90 percent","100 percent"],"h1":"It is the same score as the written test.","h2":"In Louisiana, a teen must pass the road skills test with at least 80 percent to get an intermediate license.","p":"Yes! The road test pass mark is 80 percent."},"es":{"q":"En Louisiana, ¿qué puntaje debe sacar un adolescente en el examen práctico de manejo para obtener la licencia intermedia?","o":["70 por ciento","80 por ciento","90 por ciento","100 por ciento"],"h1":"Es el mismo puntaje que el del examen escrito.","h2":"En Louisiana, un adolescente debe aprobar el examen práctico de manejo con al menos 80 por ciento para obtener la licencia intermedia.","p":"¡Sí! El examen práctico se aprueba con 80 por ciento."},"ref":{"doc":"LA","page":7}},{"id":"la-067","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, who signs the statement that a teen has finished the required supervised driving hours?","o":["The driving test examiner","The teen's school principal","An insurance agent","A parent or legal guardian"],"h1":"It is the adult responsible for the teen.","h2":"In Louisiana, a parent or legal guardian signs a statement that the teen has the required supervised driving hours.","p":"Correct! A parent or legal guardian signs it."},"es":{"q":"En Louisiana, ¿quién firma la declaración de que un adolescente completó las horas de manejo supervisado?","o":["El examinador del examen de manejo","El director de la escuela","Un agente de seguros","El padre, la madre o el tutor legal"],"h1":"Es el adulto responsable del adolescente.","h2":"En Louisiana, el padre, la madre o el tutor legal firma una declaración de que el adolescente tiene las horas de manejo supervisado requeridas.","p":"¡Correcto! Lo firma el padre, la madre o el tutor legal."},"ref":{"doc":"LA","page":7}},{"id":"la-068","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, a 16-year-old moves here and has held a license or permit from another state for at least 180 days. What may the teen be able to do?","o":["Skip the learner's permit stage and get an intermediate license","Get a full license with no limits","Keep driving on the old state's permit for two years","Get a Class D license"],"h1":"The teen already did the permit time in another state.","h2":"In Louisiana, a 16-year-old from another state who has held a license or permit for 180 days may skip the learner stage and get an intermediate license.","p":"Right! The teen may go straight to an intermediate license."},"es":{"q":"En Louisiana, un joven de 16 años se muda aquí y ha tenido una licencia o permiso de otro estado por al menos 180 días. ¿Qué podría hacer?","o":["Saltar la etapa del permiso de aprendiz y obtener una licencia intermedia","Obtener una licencia completa sin límites","Seguir manejando con el permiso del otro estado por dos años","Obtener una licencia Clase D"],"h1":"El joven ya cumplió el tiempo de permiso en otro estado.","h2":"En Louisiana, un joven de 16 años de otro estado que ha tenido licencia o permiso por 180 días puede saltar la etapa de aprendiz y obtener una licencia intermedia.","p":"¡Correcto! Puede pasar directo a la licencia intermedia."},"ref":{"doc":"LA","page":7}},{"id":"la-069","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, what does the NAIC number on an insurance card show a police officer?","o":["The size of the car's engine and its model year","How many crashes you have had in five years","That the insurance company is allowed to do business in Louisiana","The date your driver's license must be renewed"],"h1":"It is about the insurance company.","h2":"In Louisiana, the NAIC number on proof of insurance shows that the company is authorized to do business in Louisiana.","p":"Yes! It shows the insurer is authorized in Louisiana."},"es":{"q":"En Louisiana, ¿qué le muestra a un policía el número NAIC en la tarjeta de seguro?","o":["El tamaño del motor del carro y su año de modelo","Cuántos choques ha tenido en cinco años","Que la compañía de seguros está autorizada para operar en Louisiana","La fecha en que debe renovar su licencia de conducir"],"h1":"Tiene que ver con la compañía de seguros.","h2":"En Louisiana, el número NAIC en la prueba de seguro muestra que la compañía está autorizada para operar en Louisiana.","p":"¡Sí! Muestra que la aseguradora está autorizada en Louisiana."},"ref":{"doc":"LA","page":7}},{"id":"la-070","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, your driver's license shows the restriction code 01. What does it mean?","o":["You may drive only in daylight","You must wear glasses or contact lenses when you drive","You may not drive on interstates","You must use a hearing aid"],"h1":"It is about your eyes.","h2":"In Louisiana, restriction code 01 means you must wear corrective lenses, such as glasses or contacts, while driving.","p":"Correct! Code 01 means wear your glasses or contacts."},"es":{"q":"En Louisiana, su licencia muestra la restricción con el código 01. ¿Qué significa?","o":["Solo puede manejar de día","Debe usar anteojos o lentes de contacto cuando maneja","No puede manejar en autopistas interestatales","Debe usar un audífono"],"h1":"Tiene que ver con la vista.","h2":"En Louisiana, el código de restricción 01 significa que debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar.","p":"¡Correcto! El código 01 significa usar anteojos o lentes de contacto."},"ref":{"doc":"LA","page":8}},{"id":"la-071","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you fail the eye screening at the OMV. What happens next?","o":["You get a vision report for an eye specialist of your choice to fill out","You can never get a license","You must wait one year to try again","You must take the road test twice"],"h1":"A professional can check your eyes.","h2":"In Louisiana, if you fail the eye screening, you are given a vision report to be completed by a vision specialist you choose.","p":"Right! An eye specialist fills out a vision report."},"es":{"q":"En Louisiana, usted no pasa el examen de la vista en la OMV. ¿Qué sigue?","o":["Le dan un informe de visión para que lo llene un especialista de la vista que usted elija","Nunca podrá obtener una licencia","Debe esperar un año para intentarlo de nuevo","Debe tomar el examen práctico dos veces"],"h1":"Un profesional puede revisar sus ojos.","h2":"En Louisiana, si no pasa el examen de la vista, le dan un informe de visión que debe llenar un especialista de la vista que usted elija.","p":"¡Correcto! Un especialista de la vista llena el informe."},"ref":{"doc":"LA","page":8}},{"id":"la-072","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, you bring your own car to an OMV road test. Which of these must it have?","o":["Tinted windows and a remote starter","A backup camera and parking sensors","Cruise control and a lane departure warning","A valid inspection sticker, current registration and a working speedometer"],"h1":"The car must be legal and safe to drive.","h2":"In Louisiana, a car used for the OMV road test must have a valid inspection sticker, a current plate and registration, and a working speedometer.","p":"Yes! The car must be inspected, registered and have a working speedometer."},"es":{"q":"En Louisiana, usted lleva su propio carro al examen práctico de la OMV. ¿Qué debe tener?","o":["Vidrios polarizados y arranque a control remoto","Una cámara de reversa y sensores de estacionamiento","Control crucero y aviso de salida de carril","Calcomanía de inspección vigente, registro al día y velocímetro que funcione"],"h1":"El carro debe ser legal y seguro.","h2":"En Louisiana, el carro para el examen práctico de la OMV debe tener calcomanía de inspección vigente, placa y registro al día, y un velocímetro que funcione.","p":"¡Sí! El carro debe estar inspeccionado, registrado y con velocímetro funcionando."},"ref":{"doc":"LA","page":9}},{"id":"la-073","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, who may ride in the car during your road skills test?","o":["Your parent or guardian, who must sign for you","Any licensed adult 21 or older","Only you, the examiner, and an interpreter if needed","Your driving instructor from the course"],"h1":"Very few people are allowed.","h2":"In Louisiana, only the applicant, the OMV examiner and an interpreter, if needed, may be in the car during the road skills test.","p":"Correct! Only you, the examiner and an interpreter."},"es":{"q":"En Louisiana, ¿quién puede ir en el carro durante su examen práctico de manejo?","o":["Su padre, madre o tutor, que debe firmar por usted","Cualquier adulto con licencia de 21 años o más","Solo usted, el examinador y un intérprete si hace falta","Su instructor de manejo del curso"],"h1":"Se permiten muy pocas personas.","h2":"En Louisiana, solo el solicitante, el examinador de la OMV y un intérprete, si hace falta, pueden ir en el carro durante el examen práctico.","p":"¡Correcto! Solo usted, el examinador y un intérprete."},"ref":{"doc":"LA","page":9}},{"id":"la-074","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which of these makes you fail the road skills test?","o":["Driving slowly in a school zone","Breaking a traffic law or having a collision","Asking the examiner to repeat a direction","Signaling early before a turn"],"h1":"Think of a serious mistake.","h2":"In Louisiana, you fail the road skills test for breaking any traffic law, a dangerous action, a collision, refusing instructions or too many small mistakes.","p":"Right! A traffic violation or a collision fails the test."},"es":{"q":"En Louisiana, ¿cuál de estas cosas hace que repruebe el examen práctico de manejo?","o":["Manejar despacio en una zona escolar","Violar una ley de tránsito o tener un choque","Pedir al examinador que repita una indicación","Poner la direccional con tiempo antes de girar"],"h1":"Piense en un error grave.","h2":"En Louisiana, se reprueba el examen práctico por violar cualquier ley de tránsito, una acción peligrosa, un choque, no seguir instrucciones o muchos errores pequeños.","p":"¡Correcto! Una infracción o un choque reprueban el examen."},"ref":{"doc":"LA","page":10}},{"id":"la-075","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you fail the road test and you do not have a permit. What may the OMV give you?","o":["A permit so you can practice","A full license with a warning","A fine","A one-year ban from testing"],"h1":"You need more practice before you come back.","h2":"In Louisiana, if you fail the road test and do not have a permit, you may be issued one so you can practice before you retest.","p":"Yes! You may get a permit to practice."},"es":{"q":"En Louisiana, usted reprueba el examen práctico y no tiene permiso. ¿Qué le puede dar la OMV?","o":["Un permiso para que practique","Una licencia completa con una advertencia","Una multa","Un año sin poder hacer el examen"],"h1":"Necesita más práctica antes de volver.","h2":"En Louisiana, si reprueba el examen práctico y no tiene permiso, le pueden dar uno para que practique antes de repetir el examen.","p":"¡Sí! Le pueden dar un permiso para practicar."},"ref":{"doc":"LA","page":10}},{"id":"la-076","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, what happens to road skills tests at the OMV during bad weather?","o":["They are given on a closed course","They are made shorter","They are given only on interstates","They are put on hold until the weather is better"],"h1":"Safety comes first.","h2":"In Louisiana, road skills tests given at the Office of Motor Vehicles are suspended during bad weather.","p":"Correct! The tests are suspended in bad weather."},"es":{"q":"En Louisiana, ¿qué pasa con los exámenes prácticos de manejo de la OMV cuando hace mal tiempo?","o":["Se hacen en una pista cerrada","Se hacen más cortos","Solo se hacen en autopistas interestatales","Se suspenden hasta que mejore el tiempo"],"h1":"La seguridad es primero.","h2":"En Louisiana, los exámenes prácticos de manejo de la Oficina de Vehículos Motorizados se suspenden cuando hace mal tiempo.","p":"¡Correcto! Se suspenden con mal tiempo."},"ref":{"doc":"LA","page":10}},{"id":"la-077","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how early may you renew your driver's license before it expires?","o":["Up to 30 days before","Up to 90 days before","Up to 180 days before","Up to one year before"],"h1":"It is about six months.","h2":"In Louisiana, you may renew your driver's license any time within 180 days before it expires.","p":"Right! You may renew up to 180 days early."},"es":{"q":"En Louisiana, ¿con cuánta anticipación puede renovar su licencia antes de que venza?","o":["Hasta 30 días antes","Hasta 90 días antes","Hasta 180 días antes","Hasta un año antes"],"h1":"Son unos seis meses.","h2":"En Louisiana, puede renovar su licencia en cualquier momento dentro de los 180 días antes de que venza.","p":"¡Correcto! Puede renovar hasta 180 días antes."},"ref":{"doc":"LA","page":10}},{"id":"la-078","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, which test must you pass before your driver's license is renewed?","o":["A vision exam","A written knowledge test","A road skills test","A drug test"],"h1":"It checks how well you see.","h2":"In Louisiana, you must pass the vision exam before your license is renewed.","p":"Yes! You pass a vision exam to renew."},"es":{"q":"En Louisiana, ¿qué examen debe aprobar antes de que le renueven la licencia?","o":["Un examen de la vista","Un examen escrito de conocimientos","Un examen práctico de manejo","Una prueba de drogas"],"h1":"Revisa qué tan bien ve.","h2":"En Louisiana, debe aprobar el examen de la vista antes de que le renueven la licencia.","p":"¡Sí! Para renovar se aprueba un examen de la vista."},"ref":{"doc":"LA","page":10}},{"id":"la-079","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, a member of the armed forces serving outside the state is discharged. How long does a valid Louisiana license stay good after discharge?","o":["10 days","30 days","One year","60 days"],"h1":"It is about two months.","h2":"In Louisiana, the license of a service member serving outside the state stays valid for 60 days after discharge.","p":"Correct! It stays valid for 60 days."},"es":{"q":"En Louisiana, un miembro de las fuerzas armadas que sirve fuera del estado recibe la baja. ¿Por cuánto tiempo sigue válida su licencia de Louisiana después de la baja?","o":["10 días","30 días","Un año","60 días"],"h1":"Son unos dos meses.","h2":"En Louisiana, la licencia de un militar que sirve fuera del estado sigue válida por 60 días después de la baja.","p":"¡Correcto! Sigue válida por 60 días."},"ref":{"doc":"LA","page":10}},{"id":"la-080","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which drivers with a Class D or E license may be invited to renew by mail or internet?","o":["Only drivers 70 or older","Residents under age 70","Only new residents","Only commercial drivers"],"h1":"Older drivers renew in person.","h2":"In Louisiana, residents under 70 with a Class D or E license may be selected to renew by mail or internet.","p":"Right! Drivers under 70 may be invited."},"es":{"q":"En Louisiana, ¿qué conductores con licencia Clase D o E pueden ser invitados a renovar por correo o internet?","o":["Solo los de 70 años o más","Los residentes menores de 70 años","Solo los residentes nuevos","Solo los conductores comerciales"],"h1":"Los conductores mayores renuevan en persona.","h2":"En Louisiana, los residentes menores de 70 años con licencia Clase D o E pueden ser elegidos para renovar por correo o internet.","p":"¡Correcto! Pueden ser invitados los menores de 70 años."},"ref":{"doc":"LA","page":10}},{"id":"la-081","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, can you renew your license by mail or internet every time?","o":["Yes, every time","Only once in your life","No, not for two renewal cycles in a row","Only after age 70"],"h1":"Every other time you visit an office.","h2":"In Louisiana, you will not be invited to renew by mail or internet for two renewal cycles in a row.","p":"Correct! Not two times in a row."},"es":{"q":"En Louisiana, ¿puede renovar su licencia por correo o internet todas las veces?","o":["Sí, todas las veces","Solo una vez en la vida","No, no dos renovaciones seguidas","Solo después de los 70 años"],"h1":"Una vez de cada dos va a una oficina.","h2":"En Louisiana, no lo invitarán a renovar por correo o internet dos renovaciones seguidas.","p":"¡Correcto! No dos veces seguidas."},"ref":{"doc":"LA","page":10}},{"id":"la-082","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you got married and want your new name on your license. What should you bring to the OMV?","o":["A certified copy of your marriage license","A wedding photo","A letter from a friend","A utility bill with the new name"],"h1":"It must be an official, certified record.","h2":"In Louisiana, to change your name on your license you present a certified copy of a marriage license, a certified birth certificate, or a court order.","p":"Yes! Bring a certified copy of the marriage license."},"es":{"q":"En Louisiana, usted se casó y quiere su nuevo nombre en la licencia. ¿Qué debe llevar a la OMV?","o":["Una copia certificada de su licencia de matrimonio","Una foto de la boda","Una carta de un amigo","Una factura de servicios con el nuevo nombre"],"h1":"Debe ser un documento oficial certificado.","h2":"En Louisiana, para cambiar el nombre en la licencia presenta una copia certificada de la licencia de matrimonio, un acta de nacimiento certificada o una orden judicial.","p":"¡Sí! Lleve una copia certificada de la licencia de matrimonio."},"ref":{"doc":"LA","page":11}},{"id":"la-083","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, your license was stolen. How do you apply for a duplicate?","o":["By mail only","In person at a motor vehicle office","By phone only","Through the police department"],"h1":"You must show up yourself.","h2":"In Louisiana, you must apply in person at a motor vehicle office for a duplicate license.","p":"Right! You apply in person."},"es":{"q":"En Louisiana, le robaron la licencia. ¿Cómo solicita un duplicado?","o":["Solo por correo","En persona en una oficina de vehículos motorizados","Solo por teléfono","Por medio de la policía"],"h1":"Debe ir usted mismo.","h2":"En Louisiana, debe solicitar el duplicado de licencia en persona en una oficina de vehículos motorizados.","p":"¡Correcto! Se solicita en persona."},"ref":{"doc":"LA","page":11}},{"id":"la-084","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, a 65-year-old is applying for a driver's license for the first time. What must the person turn in?","o":["A letter from a family member","A driving course certificate from another state","A school transcript","A detailed report from a physician or vision specialist"],"h1":"It is a medical report.","h2":"In Louisiana, people over 60 applying for a license for the first time must submit a detailed report from a physician or vision specialist.","p":"Correct! A medical or vision report is required."},"es":{"q":"En Louisiana, una persona de 65 años solicita licencia de conducir por primera vez. ¿Qué debe entregar?","o":["Una carta de un familiar","Un certificado de curso de manejo de otro estado","Un expediente escolar","Un informe detallado de un médico o especialista de la vista"],"h1":"Es un informe médico.","h2":"En Louisiana, las personas mayores de 60 años que solicitan licencia por primera vez deben entregar un informe detallado de un médico o especialista de la vista.","p":"¡Correcto! Se requiere un informe médico o de la vista."},"ref":{"doc":"LA","page":11}},{"id":"la-085","scope":"LA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Louisiana, how long does the OMV keep ordinary traffic convictions and crashes on your public driving record?","o":["One year","Three years","Five years","Ten years"],"h1":"DWI stays longer than this.","h2":"In Louisiana, the OMV keeps traffic convictions and collisions on your public record for five years.","p":"Yes! Most entries stay for five years."},"es":{"q":"En Louisiana, ¿por cuánto tiempo guarda la OMV las condenas de tránsito comunes y los choques en su historial público?","o":["Un año","Tres años","Cinco años","Diez años"],"h1":"El DWI se guarda por más tiempo.","h2":"En Louisiana, la OMV guarda las condenas de tránsito y los choques en su historial público por cinco años.","p":"¡Sí! La mayoría se guarda por cinco años."},"ref":{"doc":"LA","page":11}},{"id":"la-086","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, does a personal identification card let you drive?","o":["No, it only proves who you are","Yes, in daylight only","Yes, with a licensed adult","Yes, for 90 days"],"h1":"It is not a license.","h2":"In Louisiana, a personal identification card is proof of identity but does not give you the privilege to drive.","p":"Right! An ID card is not a driver's license."},"es":{"q":"En Louisiana, ¿una tarjeta de identificación personal le permite manejar?","o":["No, solo prueba quién es usted","Sí, solo de día","Sí, con un adulto con licencia","Sí, por 90 días"],"h1":"No es una licencia.","h2":"En Louisiana, la tarjeta de identificación personal prueba su identidad, pero no le da el privilegio de manejar.","p":"¡Correcto! La tarjeta de identificación no es una licencia de conducir."},"ref":{"doc":"LA","page":11}},{"id":"la-087","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which of these can cost you your driving privilege even though it is not a driving offense?","o":["Changing jobs","Not paying child support or state income taxes","Moving to a new parish","Selling your car"],"h1":"Think of money you owe by law.","h2":"In Louisiana, failing to pay child support or state income taxes can cause you to lose your driving privilege.","p":"Correct! Unpaid child support or state taxes can cost you your license."},"es":{"q":"En Louisiana, ¿cuál de estas cosas puede quitarle el privilegio de manejar aunque no sea una falta de manejo?","o":["Cambiar de trabajo","No pagar la manutención de los hijos o los impuestos estatales","Mudarse a otra parroquia","Vender su carro"],"h1":"Piense en dinero que debe por ley.","h2":"En Louisiana, no pagar la manutención de los hijos o los impuestos estatales sobre la renta puede hacer que pierda el privilegio de manejar.","p":"¡Correcto! No pagar la manutención o los impuestos estatales puede costarle la licencia."},"ref":{"doc":"LA","page":12}},{"id":"la-088","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, you get a traffic ticket and never answer the charge. What can happen?","o":["Nothing; it expires","Your car gets a new plate","Your insurance is canceled at once","Your driving privilege can be suspended"],"h1":"Ignoring a ticket has a cost.","h2":"In Louisiana, failing to answer a traffic law charge can lead to the suspension of your driving privilege.","p":"Right! Your privilege can be suspended."},"es":{"q":"En Louisiana, le ponen una multa de tránsito y nunca responde al cargo. ¿Qué puede pasar?","o":["Nada; se vence","Su carro recibe una placa nueva","Le cancelan el seguro de inmediato","Le pueden suspender el privilegio de manejar"],"h1":"Ignorar una multa tiene consecuencias.","h2":"En Louisiana, no responder a un cargo de tránsito puede llevar a la suspensión de su privilegio de manejar.","p":"¡Correcto! Le pueden suspender el privilegio."},"ref":{"doc":"LA","page":12}},{"id":"la-089","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, trash blows out of the back of your pickup truck by accident. What kind of littering is this?","o":["Simple littering","Intentional littering","Gross littering","It is not littering"],"h1":"It was not on purpose.","h2":"In Louisiana, unintentional littering, like trash flying out of a pickup bed, is called simple littering.","p":"Yes! That is simple littering."},"es":{"q":"En Louisiana, se le vuela basura de la parte de atrás de su camioneta sin querer. ¿Qué tipo de tirar basura es?","o":["Tirar basura simple","Tirar basura intencional","Tirar basura grave","No es tirar basura"],"h1":"No fue a propósito.","h2":"En Louisiana, tirar basura sin intención, como basura que se vuela de una camioneta, se llama tirar basura simple.","p":"¡Sí! Es tirar basura simple."},"ref":{"doc":"LA","page":13}},{"id":"la-090","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what is gross littering?","o":["Dropping one gum wrapper","Trash blowing from a truck by accident","Dumping large amounts of trash or making an illegal dump site","Leaving a soda can on a picnic table"],"h1":"It is the most serious kind.","h2":"In Louisiana, gross littering means dumping large amounts of trash or creating an illegal dump site.","p":"Correct! Gross littering is large-scale dumping."},"es":{"q":"En Louisiana, ¿qué es tirar basura grave?","o":["Tirar una envoltura de chicle","Basura que se vuela de un camión sin querer","Tirar grandes cantidades de basura o crear un basurero ilegal","Dejar una lata de refresco en una mesa de picnic"],"h1":"Es el tipo más serio.","h2":"En Louisiana, tirar basura grave es botar grandes cantidades de basura o crear un basurero ilegal.","p":"¡Correcto! Es botar basura en gran cantidad."},"ref":{"doc":"LA","page":13}},{"id":"la-091","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what is the penalty for a second offense of simple littering?","o":["A $150 fine or 8 hours of community service","A $900 fine or 20 hours of community service","A $50 fine or 2 hours of community service","A $5,000 fine or 100 hours of community service"],"h1":"It is much higher than the first offense.","h2":"In Louisiana, a second simple littering offense brings a $900 fine or 20 hours of community service.","p":"Right! It is $900 or 20 hours."},"es":{"q":"En Louisiana, ¿cuál es la sanción por una segunda falta de tirar basura simple?","o":["Multa de $150 u 8 horas de servicio comunitario","Multa de $900 o 20 horas de servicio comunitario","Multa de $50 o 2 horas de servicio comunitario","Multa de $5,000 o 100 horas de servicio comunitario"],"h1":"Es mucho más alta que la primera vez.","h2":"En Louisiana, una segunda falta de tirar basura simple trae una multa de $900 o 20 horas de servicio comunitario.","p":"¡Correcto! Son $900 o 20 horas."},"ref":{"doc":"LA","page":14}},{"id":"la-092","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, your passenger throws trash out of the car window. Who can be cited?","o":["Only the passenger","No one, if the trash was small","The car's owner, only if not in the car","You, the driver"],"h1":"The driver answers for everyone in the vehicle.","h2":"In Louisiana, the driver is responsible for all litter that leaves the vehicle, including litter thrown by passengers, and can be cited.","p":"Correct! The driver can be cited."},"es":{"q":"En Louisiana, su pasajero tira basura por la ventana del carro. ¿A quién le pueden poner una multa?","o":["Solo al pasajero","A nadie, si la basura era pequeña","Al dueño del carro, solo si no iba en el carro","A usted, el conductor"],"h1":"El conductor responde por todos en el vehículo.","h2":"En Louisiana, el conductor es responsable de toda la basura que sale del vehículo, incluso la que tiran los pasajeros, y lo pueden multar.","p":"¡Correcto! Pueden multar al conductor."},"ref":{"doc":"LA","page":14}},{"id":"la-093","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, you see someone throw trash from a car. What number can you call to report it?","o":["*577","511","855-LA-LITTER","411"],"h1":"The number spells out the problem.","h2":"In Louisiana, you can report littering to the litter hotline at 855-LA-LITTER, calling only when you are parked.","p":"Yes! Call 855-LA-LITTER after you park."},"es":{"q":"En Louisiana, ve a alguien tirar basura desde un carro. ¿A qué número puede llamar para reportarlo?","o":["*577","511","855-LA-LITTER","411"],"h1":"El número deletrea el problema en inglés.","h2":"En Louisiana, puede reportar a quien tira basura a la línea 855-LA-LITTER, llamando solo cuando esté estacionado.","p":"¡Sí! Llame al 855-LA-LITTER después de estacionarse."},"ref":{"doc":"LA","page":14}},{"id":"la-094","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, you are carrying a load in the bed of your pickup truck. What does the law require?","o":["The load must be covered or secured so nothing falls out","Only loads over 1,000 pounds must be tied down","You must drive under 35 mph","A passenger must watch the load"],"h1":"Nothing should be able to fly out.","h2":"In Louisiana, a loaded truck bed must be covered or secured so debris and cargo cannot fall out.","p":"Right! Cover or secure the load."},"es":{"q":"En Louisiana, usted lleva una carga en la parte de atrás de su camioneta. ¿Qué exige la ley?","o":["La carga debe ir cubierta o asegurada para que nada se caiga","Solo las cargas de más de 1,000 libras se deben amarrar","Debe manejar a menos de 35 mph","Un pasajero debe vigilar la carga"],"h1":"Nada debe poder salir volando.","h2":"En Louisiana, la carga en la parte de atrás de una camioneta debe ir cubierta o asegurada para que no se caigan objetos.","p":"¡Correcto! Cubra o asegure la carga."},"ref":{"doc":"LA","page":14}},{"id":"la-095","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, how does your driver's license show that you signed up as an organ donor?","o":["A gold star","A red heart","The letter D","A blue cross"],"h1":"It is a symbol of love and life.","h2":"In Louisiana, an organ donor is marked on the front of the license or ID card with a red heart.","p":"Correct! A red heart marks a donor."},"es":{"q":"En Louisiana, ¿cómo muestra su licencia que usted se inscribió como donante de órganos?","o":["Una estrella dorada","Un corazón rojo","La letra D","Una cruz azul"],"h1":"Es un símbolo de amor y vida.","h2":"En Louisiana, el donante de órganos se marca en el frente de la licencia o tarjeta de identificación con un corazón rojo.","p":"¡Correcto! Un corazón rojo marca al donante."},"ref":{"doc":"LA","page":15}},{"id":"la-096","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, which of these is one of the four leading causes of traffic deaths named in the state driver's guide?","o":["Flat tires","Hail storms","Potholes","Not wearing a seat belt"],"h1":"The others on the list are alcohol, distraction and aggressive driving.","h2":"In Louisiana, the four leading causes of traffic deaths are alcohol, distraction, aggressive driving and not wearing a seat belt.","p":"Right! Not wearing a seat belt is one of them."},"es":{"q":"En Louisiana, ¿cuál de estas es una de las cuatro causas principales de muertes en el tránsito según la guía del estado?","o":["Llantas ponchadas","Tormentas de granizo","Baches","No usar el cinturón de seguridad"],"h1":"Las otras de la lista son el alcohol, las distracciones y el manejo agresivo.","h2":"En Louisiana, las cuatro causas principales de muertes en el tránsito son el alcohol, las distracciones, el manejo agresivo y no usar el cinturón de seguridad.","p":"¡Correcto! No usar el cinturón es una de ellas."},"ref":{"doc":"LA","page":19}},{"id":"la-097","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, what is a parish road?","o":["A road run by the federal government","A private road for churches","A road regulated and maintained by a parish","A toll road"],"h1":"Louisiana uses parishes instead of counties.","h2":"In Louisiana, a parish road is a road regulated and maintained by a parish.","p":"Yes! A parish takes care of a parish road."},"es":{"q":"En Louisiana, ¿qué es un camino parroquial (parish road)?","o":["Un camino manejado por el gobierno federal","Un camino privado para iglesias","Un camino regulado y mantenido por una parroquia","Un camino de peaje"],"h1":"Louisiana usa parroquias en lugar de condados.","h2":"En Louisiana, un camino parroquial es un camino regulado y mantenido por una parroquia.","p":"¡Sí! La parroquia cuida el camino parroquial."},"ref":{"doc":"LA","page":20}},{"id":"la-098","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, what can you dial to tell the State Police about a driver who seems drunk or reckless?","o":["*LSP (*577)","411","*311","1-800-DRIVE"],"h1":"The letters stand for Louisiana State Police.","h2":"In Louisiana, you can report a suspicious or reckless driver to the State Police by dialing *LSP (*577).","p":"Correct! Dial *577."},"es":{"q":"En Louisiana, ¿qué número puede marcar para avisar a la Policía Estatal sobre un conductor que parece borracho o imprudente?","o":["*LSP (*577)","411","*311","1-800-DRIVE"],"h1":"Las letras son de Louisiana State Police.","h2":"En Louisiana, puede reportar a un conductor sospechoso o imprudente a la Policía Estatal marcando *LSP (*577).","p":"¡Correcto! Marque *577."},"ref":{"doc":"LA","page":54}},{"id":"la-099","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, on a road with two or more lanes going your way, which lane should you normally use?","o":["The left lane, so you can see farther ahead","The right lane, unless you are passing, turning left, or the right lanes are crowded","Any lane, as long as you keep up with traffic","The center lane, to stay away from both edges"],"h1":"State law prefers one side.","h2":"In Louisiana, vehicles should travel in the right-hand lane except when passing, getting ready for a left turn, or when the right lanes are congested.","p":"Right! Keep right except in those cases."},"es":{"q":"En Louisiana, en un camino con dos o más carriles en su dirección, ¿qué carril debe usar normalmente?","o":["El carril izquierdo, para ver más lejos","El carril derecho, salvo para rebasar, girar a la izquierda o si los carriles derechos están congestionados","Cualquier carril, mientras vaya al ritmo del tránsito","El carril del centro, para alejarse de las orillas"],"h1":"La ley del estado prefiere un lado.","h2":"En Louisiana, los vehículos deben ir por el carril derecho salvo para rebasar, prepararse para girar a la izquierda o cuando los carriles derechos están congestionados.","p":"¡Correcto! Manténgase a la derecha salvo en esos casos."},"ref":{"doc":"LA","page":35}},{"id":"la-100","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, you are driving in the left lane. What does the law say about your speed there?","o":["You must go 10 mph over the limit","You must match the speed limit exactly","You may not drive slower than the vehicles to your right","Any speed is fine in the left lane"],"h1":"Slow traffic belongs on the right.","h2":"In Louisiana, a vehicle in the left lane may not be driven slower than vehicles traveling to its right.","p":"Correct! Do not go slower than traffic on your right."},"es":{"q":"En Louisiana, usted maneja por el carril izquierdo. ¿Qué dice la ley sobre su velocidad allí?","o":["Debe ir 10 mph por encima del límite","Debe ir exactamente al límite","No puede ir más despacio que los vehículos a su derecha","Cualquier velocidad está bien en el carril izquierdo"],"h1":"El tránsito lento va a la derecha.","h2":"En Louisiana, un vehículo en el carril izquierdo no puede ir más despacio que los vehículos que van a su derecha.","p":"¡Correcto! No vaya más lento que el tránsito a su derecha."},"ref":{"doc":"LA","page":35}},{"id":"la-101","scope":"LA","cat":"signals","sign":null,"c":3,"en":{"q":"In Louisiana, a work zone barricade has diagonal stripes that slope down toward the left. What do they tell you?","o":["Stop at the barricade","Bear to the right","Speed up to get past the work","Bear to the left"],"h1":"Follow the way the stripes slope down.","h2":"In Louisiana, stripes on a barricade that slope down to the left mean you should bear to the left.","p":"Right! Bear to the left."},"es":{"q":"En Louisiana, una barricada de zona de trabajo tiene franjas diagonales que bajan hacia la izquierda. ¿Qué le indican?","o":["Detenerse en la barricada","Desviarse a la derecha","Acelerar para pasar la obra","Desviarse a la izquierda"],"h1":"Siga hacia donde bajan las franjas.","h2":"En Louisiana, las franjas de una barricada que bajan hacia la izquierda indican que debe desviarse a la izquierda.","p":"¡Correcto! Desvíese a la izquierda."},"ref":{"doc":"LA","page":32}},{"id":"la-102","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, about how fast should you drive when you enter a roundabout or traffic circle?","o":["About 5 mph","About 15 to 20 mph","About 30 to 35 mph","The posted highway speed"],"h1":"You must take a sharp curve.","h2":"In Louisiana, you should slow to about 15 to 20 mph when you enter a roundabout or traffic circle.","p":"Right! Slow to about 15 to 20 mph."},"es":{"q":"En Louisiana, ¿a qué velocidad aproximada debe entrar a una rotonda o glorieta?","o":["Unas 5 mph","Unas 15 a 20 mph","Unas 30 a 35 mph","La velocidad de la carretera"],"h1":"Debe tomar una curva cerrada.","h2":"En Louisiana, debe bajar a unas 15 a 20 mph al entrar a una rotonda o glorieta.","p":"¡Correcto! Baje a unas 15 a 20 mph."},"ref":{"doc":"LA","page":91}},{"id":"la-103","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, you and another car reach a traffic circle at the same time. Which car should you yield to?","o":["The car on your left","The larger vehicle","The car on your right","No one; the faster car goes first"],"h1":"It is the same side as at a four-way stop.","h2":"In Louisiana, if another vehicle arrives at a traffic circle at the same time as you, yield to it if it is on your right.","p":"Correct! Yield to the car on your right."},"es":{"q":"En Louisiana, usted y otro carro llegan a una glorieta al mismo tiempo. ¿A qué carro debe cederle el paso?","o":["Al carro de su izquierda","Al vehículo más grande","Al carro de su derecha","A nadie; pasa el más rápido"],"h1":"Es el mismo lado que en un alto de cuatro vías.","h2":"En Louisiana, si otro vehículo llega a una glorieta al mismo tiempo que usted, cédale el paso si está a su derecha.","p":"¡Correcto! Ceda el paso al carro de su derecha."},"ref":{"doc":"LA","page":92}},{"id":"la-104","scope":"LA","cat":"signals","sign":null,"c":3,"en":{"q":"In Louisiana, you will go three-quarters of the way around a roundabout to turn left. How should you signal?","o":["Do not signal at all until you leave","Signal right the whole time you are in it","Turn on your hazard lights while circling","Signal left on the approach, then signal right before your exit"],"h1":"You change signals once you are almost at your exit.","h2":"In Louisiana, to turn left at a roundabout you signal left on the approach, then signal right after going three-quarters of the way around to take the exit.","p":"Right! Left first, then right to exit."},"es":{"q":"En Louisiana, usted dará tres cuartos de vuelta en una rotonda para girar a la izquierda. ¿Cómo debe señalar?","o":["No señalar nada hasta salir","Señalar a la derecha todo el tiempo dentro de la rotonda","Encender las luces de emergencia mientras da la vuelta","Señalar a la izquierda al llegar y luego a la derecha antes de salir"],"h1":"Cambia de señal cuando ya casi llega a su salida.","h2":"En Louisiana, para girar a la izquierda en una rotonda señala a la izquierda al llegar y luego a la derecha después de tres cuartos de vuelta para salir.","p":"¡Correcto! Primero a la izquierda y luego a la derecha para salir."},"ref":{"doc":"LA","page":92}},{"id":"la-105","scope":"LA","cat":"signals","sign":null,"c":0,"en":{"q":"In Louisiana, you plan to go straight through a roundabout. Do you need to signal as you approach it?","o":["No, no signal is needed while approaching","Yes, signal left","Yes, signal right","Yes, turn on your hazard lights"],"h1":"You are not turning off to either side.","h2":"In Louisiana, if you are going straight through a traffic circle or roundabout, no signal is needed while you approach.","p":"Correct! No signal is needed on the approach."},"es":{"q":"En Louisiana, usted piensa seguir derecho por una rotonda. ¿Necesita señalar al acercarse?","o":["No, no hace falta señal al acercarse","Sí, señalar a la izquierda","Sí, señalar a la derecha","Sí, encender las luces de emergencia"],"h1":"No va a desviarse a ningún lado.","h2":"En Louisiana, si va a seguir derecho por una glorieta o rotonda, no hace falta señalar mientras se acerca.","p":"¡Correcto! No hace falta señal al acercarse."},"ref":{"doc":"LA","page":92}},{"id":"la-106","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, who must be buckled up in a car, van or pickup truck?","o":["Only the driver","Everyone, in the front and back seats","Only people in the front seat","Only children under 13"],"h1":"The law is not only for the front seat.","h2":"In Louisiana, the safety belt law requires all occupants in both the front and back seats of cars, vans and pickup trucks to be buckled.","p":"Right! Everyone must buckle up."},"es":{"q":"En Louisiana, ¿quién debe abrocharse el cinturón en un carro, una van o una camioneta?","o":["Solo el conductor","Todos, en los asientos de adelante y de atrás","Solo quienes van adelante","Solo los niños menores de 13"],"h1":"La ley no es solo para el asiento de adelante.","h2":"En Louisiana, la ley exige que todos los ocupantes, en los asientos de adelante y de atrás de carros, vans y camionetas, lleven el cinturón abrochado.","p":"¡Correcto! Todos deben abrocharse."},"ref":{"doc":"LA","page":39}},{"id":"la-107","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, a 3-year-old has outgrown the rear-facing car seat. What should the child ride in?","o":["The vehicle's seat belt alone","A booster seat","A forward-facing car seat","An adult's lap"],"h1":"Children ages 2 to 4 face the front in a car seat.","h2":"In Louisiana, children from 2 to 4 years old ride in a forward-facing, federally approved car seat.","p":"Correct! A forward-facing car seat."},"es":{"q":"En Louisiana, un niño de 3 años ya no cabe en la silla orientada hacia atrás. ¿En qué debe viajar?","o":["Solo con el cinturón del vehículo","En un asiento elevado (booster)","En una silla de auto orientada hacia adelante","En las piernas de un adulto"],"h1":"Los niños de 2 a 4 años van mirando hacia adelante en una silla.","h2":"En Louisiana, los niños de 2 a 4 años viajan en una silla de auto aprobada orientada hacia adelante.","p":"¡Correcto! Una silla orientada hacia adelante."},"ref":{"doc":"LA","page":40}},{"id":"la-108","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, a child is 6 years old. Which restraint does the law call for?","o":["A booster seat with the seat belt","A rear-facing car seat","A lap belt only","No restraint if in the back seat"],"h1":"Children ages 4 to 9 sit higher so the belt fits.","h2":"In Louisiana, children from 4 to 9 years old ride in a booster seat with the seat belt.","p":"Right! A booster seat."},"es":{"q":"En Louisiana, un niño tiene 6 años. ¿Qué sistema de retención exige la ley?","o":["Un asiento elevado (booster) con el cinturón","Una silla orientada hacia atrás","Solo el cinturón de cadera","Ninguno si va atrás"],"h1":"Los niños de 4 a 9 años van más altos para que el cinturón les quede bien.","h2":"En Louisiana, los niños de 4 a 9 años viajan en un asiento elevado (booster) con el cinturón de seguridad.","p":"¡Correcto! Un asiento elevado."},"ref":{"doc":"LA","page":40}},{"id":"la-109","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, at what age may a child ride using the vehicle's lap and shoulder belt instead of a booster seat?","o":["4","6","13","9"],"h1":"It is the age when booster seat use ends.","h2":"In Louisiana, at 9 years old a child may ride with a lap and shoulder seat belt fastened correctly on the vehicle seat.","p":"Correct! At age 9."},"es":{"q":"En Louisiana, ¿a qué edad puede un niño usar el cinturón de cadera y hombro del vehículo en lugar del asiento elevado?","o":["4","6","13","9"],"h1":"Es la edad en que termina el uso del asiento elevado.","h2":"En Louisiana, a los 9 años un niño puede viajar con el cinturón de cadera y hombro bien abrochado en el asiento del vehículo.","p":"¡Correcto! A los 9 años."},"ref":{"doc":"LA","page":40}},{"id":"la-110","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, a child fits two car seat groups by age and size. Which group should you use?","o":["The one that costs less","The more protective one","The one that is easier to buckle","The one for older children"],"h1":"Choose more safety.","h2":"In Louisiana, a child who falls into more than one age or size group must use the more protective one.","p":"Right! Use the more protective group."},"es":{"q":"En Louisiana, un niño cabe en dos grupos de sillas por edad y tamaño. ¿Cuál debe usar?","o":["El que cuesta menos","El que protege más","El que es más fácil de abrochar","El de niños mayores"],"h1":"Elija más seguridad.","h2":"En Louisiana, un niño que cabe en más de un grupo por edad o tamaño debe usar el que protege más.","p":"¡Correcto! Use el grupo que protege más."},"ref":{"doc":"LA","page":41}},{"id":"la-111","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, how far should you sit from a steering wheel that has an air bag?","o":["At least 2 inches","At least 5 inches","At least 10 inches","At least 24 inches"],"h1":"About the length of a pencil or a bit less.","h2":"In Louisiana, the driver's guide says to sit at least 10 inches away from a steering wheel with an air bag.","p":"Correct! At least 10 inches."},"es":{"q":"Según la guía de Louisiana, ¿a qué distancia debe sentarse de un volante con bolsa de aire?","o":["Al menos 2 pulgadas","Al menos 5 pulgadas","Al menos 10 pulgadas","Al menos 24 pulgadas"],"h1":"Más o menos el largo de un lápiz o un poco menos.","h2":"En Louisiana, la guía de manejo dice que debe sentarse al menos a 10 pulgadas de un volante con bolsa de aire.","p":"¡Correcto! Al menos 10 pulgadas."},"ref":{"doc":"LA","page":41}},{"id":"la-112","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, some pickup trucks have a passenger air bag on-off switch. What is the off position for?","o":["Saving fuel","Making the air bag stronger","Silencing the seat belt alarm","Carrying a child 12 or under in the front passenger seat"],"h1":"Air bags can hurt small passengers.","h2":"In Louisiana, the passenger air bag switch is turned off so a child age 12 or under can ride in the front passenger seat of a vehicle with no or small rear seats.","p":"Right! It is for a child 12 or under in front."},"es":{"q":"Según la guía de Louisiana, algunas camionetas tienen un interruptor para apagar la bolsa de aire del pasajero. ¿Para qué es la posición de apagado?","o":["Para ahorrar gasolina","Para que la bolsa sea más fuerte","Para callar la alarma del cinturón","Para llevar a un niño de 12 años o menos en el asiento delantero"],"h1":"Las bolsas de aire pueden lastimar a pasajeros pequeños.","h2":"En Louisiana, la bolsa de aire del pasajero se apaga para que un niño de 12 años o menos pueda ir adelante en un vehículo sin asiento trasero o con uno pequeño.","p":"¡Correcto! Es para un niño de 12 años o menos adelante."},"ref":{"doc":"LA","page":41}},{"id":"la-113","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, how much tread depth should your tires have at a minimum?","o":["At least 1/16 of an inch","At least 1/2 of an inch","At least 1 inch","There is no minimum"],"h1":"It is a very small fraction of an inch.","h2":"In Louisiana, the driver's guide says tires should have at least 1/16 of an inch of tread depth.","p":"Correct! At least 1/16 of an inch."},"es":{"q":"Según la guía de Louisiana, ¿qué profundidad mínima de dibujo deben tener sus llantas?","o":["Al menos 1/16 de pulgada","Al menos 1/2 pulgada","Al menos 1 pulgada","No hay mínimo"],"h1":"Es una fracción muy pequeña de pulgada.","h2":"En Louisiana, la guía de manejo dice que las llantas deben tener al menos 1/16 de pulgada de profundidad de dibujo.","p":"¡Correcto! Al menos 1/16 de pulgada."},"ref":{"doc":"LA","page":44}},{"id":"la-114","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, about how much does tire pressure go up for every 10 degrees Fahrenheit the air warms?","o":["About 5 pounds","About 1 pound","About 10 pounds","It does not change"],"h1":"It is a small change.","h2":"In Louisiana, the driver's guide says tire pressure rises about one pound for every 10-degree Fahrenheit rise in air temperature.","p":"Right! About one pound."},"es":{"q":"Según la guía de Louisiana, ¿cuánto sube más o menos la presión de las llantas por cada 10 grados Fahrenheit que se calienta el aire?","o":["Unas 5 libras","Una libra","Unas 10 libras","No cambia"],"h1":"Es un cambio pequeño.","h2":"En Louisiana, la guía de manejo dice que la presión de las llantas sube más o menos una libra por cada 10 grados Fahrenheit que sube la temperatura.","p":"¡Correcto! Una libra más o menos."},"ref":{"doc":"LA","page":51}},{"id":"la-115","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, when should you use hand-over-hand steering?","o":["On the interstate at high speed","When changing lanes on a highway","At low speeds, such as turning at an intersection or parking","Only when backing in a straight line"],"h1":"It is for big turns of the wheel at slow speed.","h2":"In Louisiana, the driver's guide says to use hand-over-hand steering at low speeds, such as at an intersection or when parking.","p":"Correct! Use it at low speeds."},"es":{"q":"Según la guía de Louisiana, ¿cuándo debe girar el volante mano sobre mano?","o":["En la interestatal a alta velocidad","Al cambiar de carril en una carretera","A baja velocidad, como al girar en una intersección o al estacionarse","Solo al dar reversa en línea recta"],"h1":"Es para girar mucho el volante a baja velocidad.","h2":"En Louisiana, la guía de manejo dice que se gira mano sobre mano a baja velocidad, como en una intersección o al estacionarse.","p":"¡Correcto! Se usa a baja velocidad."},"ref":{"doc":"LA","page":49}},{"id":"la-116","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, when you steer quickly to avoid a hazard, what is the most you should turn the steering wheel?","o":["A full turn (360 degrees)","Two full turns","As far as it will go","No more than half a turn (180 degrees)"],"h1":"Too much steering makes the car lose grip.","h2":"In Louisiana, the driver's guide says to limit evasive steering to no more than 180 degrees, or the car may lose traction and cross into other lanes.","p":"Right! No more than half a turn."},"es":{"q":"Según la guía de Louisiana, cuando gira rápido para esquivar un peligro, ¿cuánto es lo máximo que debe girar el volante?","o":["Una vuelta completa (360 grados)","Dos vueltas completas","Hasta donde llegue","No más de media vuelta (180 grados)"],"h1":"Girar demasiado hace que el carro pierda agarre.","h2":"En Louisiana, la guía de manejo dice que al esquivar no debe girar el volante más de 180 grados, o el carro puede perder tracción y cruzar a otros carriles.","p":"¡Correcto! No más de media vuelta."},"ref":{"doc":"LA","page":49}},{"id":"la-117","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, how often should a driver take a rest break on a long drive?","o":["About every two hours","Every six hours","Only when you feel sleepy","Once a day"],"h1":"Stop before you feel tired.","h2":"In Louisiana, the driver's guide says a driver should rest about every two hours.","p":"Correct! Rest about every two hours."},"es":{"q":"Según la guía de Louisiana, ¿cada cuánto debe descansar un conductor en un viaje largo?","o":["Más o menos cada dos horas","Cada seis horas","Solo cuando sienta sueño","Una vez al día"],"h1":"Pare antes de sentirse cansado.","h2":"En Louisiana, la guía de manejo dice que el conductor debe descansar más o menos cada dos horas.","p":"¡Correcto! Descanse cada dos horas más o menos."},"ref":{"doc":"LA","page":56}},{"id":"la-118","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, if one person does all the driving, what is the most driving to plan for in one day?","o":["2 to 3 hours","12 to 14 hours","6 to 8 hours","There is no limit"],"h1":"It is less than a full work shift plus overtime.","h2":"In Louisiana, the driver's guide says 6 to 8 hours of driving in one day should be the limit when one person does all the driving.","p":"Right! Plan for 6 to 8 hours at most."},"es":{"q":"Según la guía de Louisiana, si una sola persona maneja todo el viaje, ¿cuánto es lo máximo que debe planear manejar en un día?","o":["2 a 3 horas","12 a 14 horas","6 a 8 horas","No hay límite"],"h1":"Es menos que una jornada con horas extra.","h2":"En Louisiana, la guía de manejo dice que si una persona maneja todo, el límite debe ser de 6 a 8 horas al día.","p":"¡Correcto! Planee 6 a 8 horas como máximo."},"ref":{"doc":"LA","page":108}},{"id":"la-119","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, which hours should you try to avoid driving to prevent drowsy driving?","o":["Noon to 3 p.m.","Midnight to 6 a.m.","6 a.m. to 9 a.m.","4 p.m. to 7 p.m."],"h1":"These are the body's natural sleep hours.","h2":"In Louisiana, the driver's guide suggests limiting driving between midnight and 6 a.m. to avoid drowsy driving.","p":"Correct! Midnight to 6 a.m."},"es":{"q":"Según la guía de Louisiana, ¿en qué horas debe tratar de no manejar para evitar manejar con sueño?","o":["Del mediodía a las 3 p.m.","De la medianoche a las 6 a.m.","De las 6 a.m. a las 9 a.m.","De las 4 p.m. a las 7 p.m."],"h1":"Son las horas naturales de sueño del cuerpo.","h2":"En Louisiana, la guía de manejo sugiere limitar el manejo entre la medianoche y las 6 a.m. para evitar manejar con sueño.","p":"¡Correcto! De la medianoche a las 6 a.m."},"ref":{"doc":"LA","page":57}},{"id":"la-120","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, how far ahead should your eyes look down the road (your visual lead)?","o":["2 to 3 seconds","About 5 seconds","Just past your hood","20 to 30 seconds"],"h1":"Look far ahead so you have time to prepare.","h2":"In Louisiana, the driver's guide says your visual lead should be 20 to 30 seconds ahead of your vehicle.","p":"Right! Look 20 to 30 seconds ahead."},"es":{"q":"Según la guía de Louisiana, ¿qué tan adelante en el camino debe mirar (su anticipación visual)?","o":["2 a 3 segundos","Unos 5 segundos","Justo delante del cofre","20 a 30 segundos"],"h1":"Mire lejos para tener tiempo de prepararse.","h2":"En Louisiana, la guía de manejo dice que debe mirar de 20 a 30 segundos por delante de su vehículo.","p":"¡Correcto! Mire de 20 a 30 segundos adelante."},"ref":{"doc":"LA","page":61}},{"id":"la-121","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, you are driving 60 mph. How far ahead must you be able to see, or you are going too fast for your visibility?","o":["At least 400 feet","At least 100 feet","At least 50 feet","At least one mile"],"h1":"It takes about 359 feet to stop from 60 mph.","h2":"In Louisiana, the driver's guide says that at 60 mph, if you cannot see at least 400 feet ahead, you are driving too fast for your visibility.","p":"Correct! At least 400 feet."},"es":{"q":"Según la guía de Louisiana, usted maneja a 60 mph. ¿Qué tan lejos debe poder ver, o va demasiado rápido para su visibilidad?","o":["Al menos 400 pies","Al menos 100 pies","Al menos 50 pies","Al menos una milla"],"h1":"Para parar desde 60 mph se necesitan unos 359 pies.","h2":"En Louisiana, la guía de manejo dice que a 60 mph, si no puede ver al menos 400 pies adelante, va demasiado rápido para su visibilidad.","p":"¡Correcto! Al menos 400 pies."},"ref":{"doc":"LA","page":62}},{"id":"la-122","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, what size gap in traffic should you look for before you change lanes?","o":["1 second","2 seconds","4 to 5 seconds","10 seconds"],"h1":"It is a little longer than your following distance.","h2":"In Louisiana, the driver's guide says to find a 4 to 5 second gap in traffic before you change lanes.","p":"Right! Look for a 4 to 5 second gap."},"es":{"q":"Según la guía de Louisiana, ¿qué espacio en el tránsito debe buscar antes de cambiar de carril?","o":["1 segundo","2 segundos","4 a 5 segundos","10 segundos"],"h1":"Es un poco más que su distancia de seguimiento.","h2":"En Louisiana, la guía de manejo dice que debe buscar un espacio de 4 a 5 segundos en el tránsito antes de cambiar de carril.","p":"¡Correcto! Busque un espacio de 4 a 5 segundos."},"ref":{"doc":"LA","page":63}},{"id":"la-123","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, about how far does a car travel in total to stop from 50 mph on dry pavement?","o":["About 100 feet","At least 268 feet","About 55 feet","About 1,000 feet"],"h1":"It includes seeing, reacting and braking.","h2":"In Louisiana, the driver's guide says total stopping distance at 50 mph is at least 268 feet in ideal conditions.","p":"Correct! At least 268 feet."},"es":{"q":"Según la guía de Louisiana, ¿qué distancia total recorre más o menos un carro para detenerse desde 50 mph en pavimento seco?","o":["Unos 100 pies","Al menos 268 pies","Unos 55 pies","Unos 1,000 pies"],"h1":"Incluye ver, reaccionar y frenar.","h2":"En Louisiana, la guía de manejo dice que la distancia total para detenerse a 50 mph es de al menos 268 pies en condiciones ideales.","p":"¡Correcto! Al menos 268 pies."},"ref":{"doc":"LA","page":65}},{"id":"la-124","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, what is the basic following distance rule in normal conditions?","o":["1 second","2 seconds","6 seconds","3 seconds"],"h1":"Count one-one-thousand, two-one-thousand ...","h2":"In Louisiana, the driver's guide uses the three-second rule for following distance in normal conditions.","p":"Right! Use the three-second rule."},"es":{"q":"Según la guía de Louisiana, ¿cuál es la regla básica de distancia de seguimiento en condiciones normales?","o":["1 segundo","2 segundos","6 segundos","3 segundos"],"h1":"Cuente uno-mil, dos-mil ...","h2":"En Louisiana, la guía de manejo usa la regla de los tres segundos para la distancia de seguimiento en condiciones normales.","p":"¡Correcto! Use la regla de los tres segundos."},"ref":{"doc":"LA","page":65}},{"id":"la-125","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, what following distance should you use in bad weather or on wet pavement?","o":["At least 4 seconds","1 second","2 seconds","The same as on a dry day"],"h1":"Add to the normal three seconds.","h2":"In Louisiana, the driver's guide says to increase your following distance to four seconds in bad weather or on wet pavement.","p":"Correct! At least four seconds."},"es":{"q":"Según la guía de Louisiana, ¿qué distancia de seguimiento debe usar con mal tiempo o pavimento mojado?","o":["Al menos 4 segundos","1 segundo","2 segundos","La misma que en un día seco"],"h1":"Agregue a los tres segundos normales.","h2":"En Louisiana, la guía de manejo dice que debe aumentar la distancia de seguimiento a cuatro segundos con mal tiempo o pavimento mojado.","p":"¡Correcto! Al menos cuatro segundos."},"ref":{"doc":"LA","page":66}},{"id":"la-126","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, you are driving at night on a road you do not know. How much should you add to your following distance?","o":["Nothing","Half a second","At least two seconds","At least ten seconds"],"h1":"At night on any road, add at least one second; on an unfamiliar road, add more.","h2":"In Louisiana, the driver's guide says to add at least two seconds to your following distance when driving on unfamiliar roads at night.","p":"Right! Add at least two seconds."},"es":{"q":"Según la guía de Louisiana, usted maneja de noche por un camino que no conoce. ¿Cuánto debe agregar a su distancia de seguimiento?","o":["Nada","Medio segundo","Al menos dos segundos","Al menos diez segundos"],"h1":"De noche en cualquier camino agregue al menos un segundo; en uno desconocido, más.","h2":"En Louisiana, la guía de manejo dice que debe agregar al menos dos segundos a su distancia de seguimiento al manejar de noche en caminos que no conoce.","p":"¡Correcto! Agregue al menos dos segundos."},"ref":{"doc":"LA","page":75}},{"id":"la-127","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, on what kind of road should a three-point turnabout be used?","o":["On a four-lane highway with a wide median","Only on a two-lane road that is too narrow for a U-turn","On an interstate ramp when you miss your exit","In the middle of a busy intersection"],"h1":"It is the hardest and most dangerous way to turn around.","h2":"In Louisiana, the driver's guide says a three-point turnabout should be used only on a two-lane road when it is too narrow for a U-turn and you cannot go around the block.","p":"Right! Only on a narrow two-lane road."},"es":{"q":"Según la guía de Louisiana, ¿en qué tipo de camino se debe dar una vuelta en tres movimientos?","o":["En una carretera de cuatro carriles con camellón ancho","Solo en un camino de dos carriles demasiado angosto para una vuelta en U","En una rampa de la interestatal si se pasó la salida","En medio de una intersección con mucho tránsito"],"h1":"Es la forma más difícil y peligrosa de dar la vuelta.","h2":"En Louisiana, la guía de manejo dice que la vuelta en tres movimientos solo se usa en un camino de dos carriles demasiado angosto para una vuelta en U y cuando no puede rodear la cuadra.","p":"¡Correcto! Solo en un camino angosto de dos carriles."},"ref":{"doc":"LA","page":67}},{"id":"la-128","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, when should you set the parking brake?","o":["Every time you park, on flat ground or on a hill","Only on steep hills","Only in a car with a manual transmission","Only when parking overnight"],"h1":"The guide says it is not just for hills.","h2":"In Louisiana, the driver's guide says to use the parking brake every time you park, whether the car is automatic or manual and the ground is flat or hilly.","p":"Correct! Set it every time you park."},"es":{"q":"Según la guía de Louisiana, ¿cuándo debe poner el freno de mano?","o":["Cada vez que se estacione, en plano o en pendiente","Solo en pendientes empinadas","Solo en carros de transmisión manual","Solo al estacionarse de noche"],"h1":"La guía dice que no es solo para pendientes.","h2":"En Louisiana, la guía de manejo dice que debe usar el freno de mano cada vez que se estacione, sea el carro automático o manual y el terreno plano o inclinado.","p":"¡Correcto! Póngalo cada vez que se estacione."},"ref":{"doc":"LA","page":67}},{"id":"la-129","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Straight ahead","Away from the curb","Toward the middle of the street","Toward the curb"],"h1":"If the car rolls, the curb should stop it.","h2":"In Louisiana, when parking downhill next to a curb, turn your front wheels toward the curb and shift into reverse or park.","p":"Right! Turn the wheels toward the curb."},"es":{"q":"En Louisiana, se estaciona cuesta abajo junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Derechas","Lejos de la acera","Hacia el centro de la calle","Hacia la acera"],"h1":"Si el carro rueda, la acera lo debe detener.","h2":"En Louisiana, al estacionarse cuesta abajo junto a una acera, gire las llantas delanteras hacia la acera y ponga reversa o park.","p":"¡Correcto! Gire las llantas hacia la acera."},"ref":{"doc":"LA","page":68}},{"id":"la-130","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","Away from the curb","It does not matter"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In Louisiana, when parking uphill next to a curb, turn your front wheels away from the curb and shift into low gear or park.","p":"Correct! Turn the wheels away from the curb."},"es":{"q":"En Louisiana, se estaciona cuesta arriba junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la acera","Derechas","Lejos de la acera","No importa"],"h1":"Si el carro rueda hacia atrás, la parte de atrás de la llanta debe topar con la acera.","h2":"En Louisiana, al estacionarse cuesta arriba junto a una acera, gire las llantas delanteras lejos de la acera y ponga una velocidad baja o park.","p":"¡Correcto! Gire las llantas lejos de la acera."},"ref":{"doc":"LA","page":68}},{"id":"la-131","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, when you parallel park, how close to the curb must your right wheels be?","o":["Within 6 inches","Within 18 inches","Within 3 feet","Within 5 feet"],"h1":"It is a foot and a half.","h2":"In Louisiana, when parallel parked, your right wheels must be within 18 inches of the right-hand curb.","p":"Right! Within 18 inches."},"es":{"q":"En Louisiana, al estacionarse en paralelo, ¿qué tan cerca de la acera deben quedar sus llantas derechas?","o":["A 6 pulgadas o menos","A 18 pulgadas o menos","A 3 pies o menos","A 5 pies o menos"],"h1":"Es un pie y medio.","h2":"En Louisiana, al estacionarse en paralelo, sus llantas derechas deben quedar a 18 pulgadas o menos de la acera derecha.","p":"¡Correcto! A 18 pulgadas o menos."},"ref":{"doc":"LA","page":70}},{"id":"la-132","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, how close to a crosswalk at an intersection may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 10 feet","No closer than 50 feet"],"h1":"It is more than a car length.","h2":"In Louisiana, you may not park within 20 feet of a crosswalk at an intersection.","p":"Correct! Stay at least 20 feet away."},"es":{"q":"En Louisiana, ¿qué tan cerca de un cruce peatonal en una intersección se puede estacionar?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 50 pies"],"h1":"Es más que el largo de un carro.","h2":"En Louisiana, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"¡Correcto! Quédese al menos a 20 pies."},"ref":{"doc":"LA","page":70}},{"id":"la-133","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, you want to park on the opposite side of the street from a fire station driveway. How far from the driveway must you park?","o":["At least 10 feet","At least 20 feet","At least 75 feet","At least 200 feet"],"h1":"Fire trucks need room to swing out; it is farther than on the same side.","h2":"In Louisiana, you may not park within 75 feet of a fire station driveway on the opposite side of the street, or within 20 feet on the same side.","p":"Right! At least 75 feet across the street."},"es":{"q":"En Louisiana, quiere estacionarse en el lado opuesto de la calle frente a la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe estacionarse?","o":["Al menos 10 pies","Al menos 20 pies","Al menos 75 pies","Al menos 200 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir; es más que en el mismo lado.","h2":"En Louisiana, no puede estacionarse a menos de 75 pies de la entrada de una estación de bomberos en el lado opuesto de la calle, ni a menos de 20 pies en el mismo lado.","p":"¡Correcto! Al menos 75 pies al otro lado de la calle."},"ref":{"doc":"LA","page":70}},{"id":"la-134","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, how close to a stop sign or traffic signal at the side of the road may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Other drivers must be able to see the sign.","h2":"In Louisiana, you may not park within 20 feet of a stop sign, yield sign, flashing beacon or traffic signal at the side of the road.","p":"Correct! No closer than 20 feet."},"es":{"q":"En Louisiana, ¿qué tan cerca de una señal de alto o un semáforo al lado del camino se puede estacionar?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 50 pies","No más cerca de 20 pies"],"h1":"Los demás conductores deben poder ver la señal.","h2":"En Louisiana, no puede estacionarse a menos de 20 pies de una señal de alto, de ceda el paso, de una luz intermitente o de un semáforo al lado del camino.","p":"¡Correcto! No más cerca de 20 pies."},"ref":{"doc":"LA","page":70}},{"id":"la-135","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, where does the law forbid parking?","o":["In a marked space in a parking lot","On a bridge, an overpass or in a tunnel","At a curb with no signs or markings","In your own driveway"],"h1":"Think of places where a stopped car blocks traffic with no way around.","h2":"In Louisiana, it is against the law to park on a bridge, an overpass or in a tunnel.","p":"Right! No parking on bridges, overpasses or in tunnels."},"es":{"q":"En Louisiana, ¿dónde prohíbe la ley estacionarse?","o":["En un espacio marcado de un estacionamiento","En un puente, un paso elevado o un túnel","En una acera sin señales ni marcas","En su propia entrada de casa"],"h1":"Piense en lugares donde un carro parado bloquea el paso sin salida.","h2":"En Louisiana, es ilegal estacionarse en un puente, un paso elevado o un túnel.","p":"¡Correcto! No se estacione en puentes, pasos elevados ni túneles."},"ref":{"doc":"LA","page":70}},{"id":"la-136","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, a curb is painted yellow. What does it usually mean?","o":["A fire zone","Parking for people with disabilities","A loading zone or another restriction","Short stops only"],"h1":"Trucks often unload at these curbs.","h2":"In Louisiana, a yellow curb marks a loading zone or some other parking restriction.","p":"Correct! Yellow means a loading zone or other limit."},"es":{"q":"En Louisiana, una acera está pintada de amarillo. ¿Qué suele significar?","o":["Zona de bomberos","Estacionamiento para personas con discapacidad","Zona de carga u otra restricción","Solo paradas cortas"],"h1":"Los camiones suelen descargar en estas aceras.","h2":"En Louisiana, una acera amarilla marca una zona de carga u otra restricción para estacionarse.","p":"¡Correcto! El amarillo indica zona de carga u otro límite."},"ref":{"doc":"LA","page":70}},{"id":"la-137","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, a curb is painted white. What does it usually mean?","o":["Only short stops are allowed","A loading zone","A fire zone","Accessible parking only"],"h1":"Think quick drop-off.","h2":"In Louisiana, a white curb means only short stops are permitted.","p":"Right! White means short stops only."},"es":{"q":"En Louisiana, una acera está pintada de blanco. ¿Qué suele significar?","o":["Solo se permiten paradas cortas","Zona de carga","Zona de bomberos","Solo estacionamiento accesible"],"h1":"Piense en dejar a alguien rápido.","h2":"En Louisiana, una acera blanca significa que solo se permiten paradas cortas.","p":"¡Correcto! Blanco significa solo paradas cortas."},"ref":{"doc":"LA","page":70}},{"id":"la-138","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, you pass a car on a two-lane road. How far from any oncoming vehicle must you be when you finish the pass?","o":["At least 10 feet","At least 25 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Louisiana, you must complete a pass before coming within 100 feet of any vehicle coming from the opposite direction.","p":"Correct! At least 100 feet."},"es":{"q":"En Louisiana, usted rebasa a un carro en un camino de dos carriles. ¿A qué distancia de un vehículo que viene de frente debe terminar de rebasar?","o":["Al menos 10 pies","Al menos 25 pies","Al menos 50 pies","Al menos 100 pies"],"h1":"Es el largo de unos seis o siete carros.","h2":"En Louisiana, debe terminar de rebasar antes de quedar a menos de 100 pies de cualquier vehículo que viene en sentido contrario.","p":"¡Correcto! Al menos 100 pies."},"ref":{"doc":"LA","page":71}},{"id":"la-139","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana, may you pass another vehicle by driving on the shoulder?","o":["Yes, if the shoulder is paved","No, passing on the shoulder is against the law","Yes, on the right side only","Yes, in heavy traffic"],"h1":"The shoulder is not a travel lane.","h2":"In Louisiana, it is unsafe and against the law to pass another vehicle on the shoulder, paved or not.","p":"Right! Never pass on the shoulder."},"es":{"q":"En Louisiana, ¿puede rebasar a otro vehículo manejando por el acotamiento?","o":["Sí, si el acotamiento está pavimentado","No, rebasar por el acotamiento es ilegal","Sí, solo por la derecha","Sí, con tránsito pesado"],"h1":"El acotamiento no es un carril de circulación.","h2":"En Louisiana, rebasar a otro vehículo por el acotamiento, pavimentado o no, es peligroso e ilegal.","p":"¡Correcto! Nunca rebase por el acotamiento."},"ref":{"doc":"LA","page":71}},{"id":"la-140","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, when may you pass another vehicle on the right?","o":["When there are two or more lanes going in your direction","Any time the driver ahead is slow","Only at night","Never, in any case"],"h1":"You need a lane on the right to do it.","h2":"In Louisiana, you may pass on the right when there are two or more lanes of traffic moving in the same direction.","p":"Correct! Only with two or more lanes going your way."},"es":{"q":"En Louisiana, ¿cuándo puede rebasar a otro vehículo por la derecha?","o":["Cuando hay dos o más carriles en su dirección","Siempre que el conductor de adelante vaya lento","Solo de noche","Nunca, en ningún caso"],"h1":"Necesita un carril a la derecha para hacerlo.","h2":"En Louisiana, puede rebasar por la derecha cuando hay dos o más carriles de tránsito en la misma dirección.","p":"¡Correcto! Solo con dos o más carriles en su dirección."},"ref":{"doc":"LA","page":72}},{"id":"la-141","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, an oncoming vehicle more than about how many seconds away looks like it is standing still?","o":["5 seconds","10 seconds","25 seconds","60 seconds"],"h1":"If you can see it getting closer, it is nearer than this.","h2":"In Louisiana, the driver's guide says an oncoming vehicle more than 25 seconds away generally appears to be standing still.","p":"Right! About 25 seconds."},"es":{"q":"Según la guía de Louisiana, ¿a partir de cuántos segundos de distancia parece estar detenido un vehículo que viene de frente?","o":["5 segundos","10 segundos","25 segundos","60 segundos"],"h1":"Si lo ve acercarse, está más cerca que eso.","h2":"En Louisiana, la guía de manejo dice que un vehículo que viene de frente a más de 25 segundos suele parecer detenido.","p":"¡Correcto! Unos 25 segundos."},"ref":{"doc":"LA","page":73}},{"id":"la-142","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, you should not try to pass if you cannot see at least how far ahead?","o":["100 feet","200 feet","One block","A quarter mile"],"h1":"It is a long distance, about 1,300 feet.","h2":"In Louisiana, the driver's guide says not to attempt a pass if you cannot see at least a quarter mile ahead.","p":"Correct! A quarter mile."},"es":{"q":"Según la guía de Louisiana, ¿qué distancia mínima debe poder ver adelante para intentar rebasar?","o":["100 pies","200 pies","Una cuadra","Un cuarto de milla"],"h1":"Es una distancia larga, unos 1,300 pies.","h2":"En Louisiana, la guía de manejo dice que no intente rebasar si no puede ver al menos un cuarto de milla adelante.","p":"¡Correcto! Un cuarto de milla."},"ref":{"doc":"LA","page":88}},{"id":"la-143","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, at about what speed can partial hydroplaning begin on a wet road?","o":["15 mph","35 mph","65 mph","80 mph"],"h1":"Below this speed, good tires wipe the water away.","h2":"In Louisiana, the driver's guide says partial hydroplaning starts at about 35 mph and gets worse as speed increases.","p":"Right! About 35 mph."},"es":{"q":"Según la guía de Louisiana, ¿a qué velocidad aproximada puede empezar el hidroplaneo parcial en un camino mojado?","o":["15 mph","35 mph","65 mph","80 mph"],"h1":"Por debajo de esta velocidad, las llantas buenas quitan el agua.","h2":"En Louisiana, la guía de manejo dice que el hidroplaneo parcial empieza a unas 35 mph y empeora al subir la velocidad.","p":"¡Correcto! Unas 35 mph."},"ref":{"doc":"LA","page":74}},{"id":"la-144","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, about how far ahead do your low beam headlights let you see clearly?","o":["150 to 200 feet","About 50 feet","350 to 400 feet","About 1,000 feet"],"h1":"High beams let you see about twice as far.","h2":"In Louisiana, the driver's guide says low beam headlights let you see clearly about 150 to 200 feet ahead.","p":"Correct! About 150 to 200 feet."},"es":{"q":"Según la guía de Louisiana, ¿qué tan lejos le permiten ver con claridad las luces bajas?","o":["150 a 200 pies","Unos 50 pies","350 a 400 pies","Unos 1,000 pies"],"h1":"Las luces altas dejan ver más o menos el doble.","h2":"En Louisiana, la guía de manejo dice que las luces bajas permiten ver con claridad unos 150 a 200 pies adelante.","p":"¡Correcto! Unos 150 a 200 pies."},"ref":{"doc":"LA","page":75}},{"id":"la-145","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, when must your headlights be on?","o":["Only after 9 p.m.","Only on roads with no streetlights","From sunset to sunrise","Only when it rains"],"h1":"Parking lights alone are not enough.","h2":"In Louisiana, the law requires headlights, not just parking lights, to be on between sunset and sunrise.","p":"Right! From sunset to sunrise."},"es":{"q":"En Louisiana, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Solo después de las 9 p.m.","Solo en caminos sin alumbrado","Desde la puesta hasta la salida del sol","Solo cuando llueve"],"h1":"Las luces de estacionamiento solas no bastan.","h2":"En Louisiana, la ley exige que las luces delanteras, no solo las de estacionamiento, estén encendidas desde la puesta hasta la salida del sol.","p":"¡Correcto! Desde la puesta hasta la salida del sol."},"ref":{"doc":"LA","page":75}},{"id":"la-146","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, you are following another vehicle at night. Within what distance of it must you use low beams?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"It is shorter than the distance for oncoming cars.","h2":"In Louisiana, you must use low beams when following within 200 feet of another vehicle.","p":"Correct! Within 200 feet when following."},"es":{"q":"En Louisiana, usted va detrás de otro vehículo de noche. ¿A qué distancia de él debe usar luces bajas?","o":["50 pies","100 pies","1,000 pies","200 pies"],"h1":"Es menos que la distancia para carros que vienen de frente.","h2":"En Louisiana, debe usar luces bajas cuando va a 200 pies o menos detrás de otro vehículo.","p":"¡Correcto! A 200 pies o menos al seguir a otro."},"ref":{"doc":"LA","page":75}},{"id":"la-147","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, it is raining and you need your windshield wipers. What else does the law require?","o":["Hazard flashers","Low beam headlights","Fog lights only","Parking lights only"],"h1":"Other drivers need to see you in the rain.","h2":"In Louisiana, the law requires your headlights to be on, on low beam, whenever your windshield wipers are needed.","p":"Right! Wipers on means low beams on."},"es":{"q":"En Louisiana, está lloviendo y necesita los limpiaparabrisas. ¿Qué más exige la ley?","o":["Las luces intermitentes de emergencia","Las luces bajas","Solo las luces antiniebla","Solo las luces de estacionamiento"],"h1":"Los demás deben verlo bajo la lluvia.","h2":"En Louisiana, la ley exige tener las luces delanteras encendidas en bajas siempre que necesite los limpiaparabrisas.","p":"¡Correcto! Con limpiaparabrisas, luces bajas encendidas."},"ref":{"doc":"LA","page":97}},{"id":"la-148","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, you must turn on your headlights when the weather makes your vehicle hard to see clearly from how far away?","o":["500 feet","50 feet","100 feet","One mile"],"h1":"It is the same distance used for dimming for oncoming cars.","h2":"In Louisiana, headlights must be on when weather makes it hard for others to see your vehicle clearly from 500 feet away.","p":"Correct! 500 feet."},"es":{"q":"En Louisiana, debe encender las luces delanteras cuando el tiempo hace difícil ver su vehículo con claridad. ¿Desde qué distancia?","o":["500 pies","50 pies","100 pies","Una milla"],"h1":"Es la misma distancia que se usa para bajar las luces ante carros de frente.","h2":"En Louisiana, las luces delanteras deben estar encendidas cuando el tiempo hace difícil que otros vean su vehículo con claridad a 500 pies.","p":"¡Correcto! 500 pies."},"ref":{"doc":"LA","page":75}},{"id":"la-149","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, a blind pedestrian with a white cane is waiting at a crosswalk. Where should you stop?","o":["At least 20 feet back so you do not scare the person","In the middle of the crosswalk","No more than five feet from the crosswalk, so the person can hear your engine","Anywhere, and honk so the person knows you are there"],"h1":"The person uses sound to know where cars are.","h2":"In Louisiana, the driver's guide says not to stop more than five feet from the crosswalk, because a visually impaired pedestrian uses the sound of your engine as a guide.","p":"Right! Stop within five feet of the crosswalk."},"es":{"q":"Según la guía de Louisiana, un peatón ciego con bastón blanco espera en un cruce peatonal. ¿Dónde debe detenerse?","o":["Al menos a 20 pies para no asustarlo","En medio del cruce peatonal","A no más de cinco pies del cruce, para que pueda oír su motor","En cualquier lugar, y tocar el claxon para avisarle"],"h1":"La persona usa el sonido para saber dónde están los carros.","h2":"En Louisiana, la guía de manejo dice que no se detenga a más de cinco pies del cruce, porque un peatón con discapacidad visual se guía por el sonido de su motor.","p":"¡Correcto! Deténgase a cinco pies o menos del cruce."},"ref":{"doc":"LA","page":77}},{"id":"la-150","scope":"LA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Louisiana, you are turning right on a red light and a pedestrian is crossing in front of you. Who has the right of way?","o":["You, because you stopped first","Whoever is moving faster","You, if the light is about to turn green","The pedestrian"],"h1":"A right turn on red is allowed only after you yield.","h2":"In Louisiana, pedestrians have the right of way over a vehicle making a right turn on red.","p":"Correct! The pedestrian goes first."},"es":{"q":"En Louisiana, usted gira a la derecha con luz roja y un peatón cruza frente a usted. ¿Quién tiene el derecho de paso?","o":["Usted, porque se detuvo primero","Quien vaya más rápido","Usted, si la luz está por cambiar a verde","El peatón"],"h1":"El giro a la derecha con luz roja solo se permite después de ceder el paso.","h2":"En Louisiana, los peatones tienen el derecho de paso sobre un vehículo que gira a la derecha con luz roja.","p":"¡Correcto! El peatón pasa primero."},"ref":{"doc":"LA","page":76}},{"id":"la-151","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what lights must a bicycle have when it is ridden at night?","o":["A red front light and a white rear light","A white front light and a red rear light or reflector","Only reflectors on the pedals","A flashing blue light"],"h1":"Front lights are white and rear lights are red, like on a car.","h2":"In Louisiana, a bicycle ridden at night must have a white front light and a red rear light or reflector visible from behind.","p":"Right! White in front, red in back."},"es":{"q":"En Louisiana, ¿qué luces debe tener una bicicleta que se usa de noche?","o":["Una luz roja adelante y una blanca atrás","Una luz blanca adelante y una luz o reflector rojo atrás","Solo reflectores en los pedales","Una luz azul intermitente"],"h1":"Adelante blanca y atrás roja, como en un carro.","h2":"En Louisiana, una bicicleta que se usa de noche debe tener una luz blanca adelante y una luz o reflector rojo visible desde atrás.","p":"¡Correcto! Blanca adelante y roja atrás."},"ref":{"doc":"LA","page":81}},{"id":"la-152","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, how many bicyclists may ride side by side on a regular road?","o":["Any number","Only one","No more than two","No more than four"],"h1":"Think of a pair.","h2":"In Louisiana, bicyclists must not ride more than two abreast, except on paths set aside only for bicycles.","p":"Right! No more than two side by side."},"es":{"q":"En Louisiana, ¿cuántos ciclistas pueden ir uno al lado del otro en un camino común?","o":["Cualquier número","Solo uno","No más de dos","No más de cuatro"],"h1":"Piense en una pareja.","h2":"En Louisiana, los ciclistas no deben ir más de dos lado a lado, salvo en vías solo para bicicletas.","p":"¡Correcto! No más de dos lado a lado."},"ref":{"doc":"LA","page":97}},{"id":"la-153","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, a small child rides as a passenger on a bicycle. When must the child be in an approved restraining seat?","o":["When the child weighs less than 40 pounds or is shorter than 40 inches","Only on highways","Only at night","Only if the child is under 1 year old"],"h1":"The rule uses the number 40 twice.","h2":"In Louisiana, a child who weighs less than 40 pounds or is less than 40 inches tall must be secured in an approved restraining seat to ride on a bicycle.","p":"Correct! Under 40 pounds or 40 inches."},"es":{"q":"En Louisiana, un niño pequeño va de pasajero en una bicicleta. ¿Cuándo debe ir en un asiento de seguridad aprobado?","o":["Cuando pesa menos de 40 libras o mide menos de 40 pulgadas","Solo en carreteras","Solo de noche","Solo si tiene menos de 1 año"],"h1":"La regla usa el número 40 dos veces.","h2":"En Louisiana, un niño que pesa menos de 40 libras o mide menos de 40 pulgadas debe ir sujeto en un asiento de seguridad aprobado para viajar en bicicleta.","p":"¡Correcto! Menos de 40 libras o 40 pulgadas."},"ref":{"doc":"LA","page":97}},{"id":"la-154","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, what does the law require of the person steering a bicycle?","o":["Both hands on the handlebars at all times","A license plate on the bicycle","A horn on the handlebars","At least one hand on the handlebars at all times"],"h1":"The rider must stay in control.","h2":"In Louisiana, the person controlling a bicycle must keep at least one hand on the handlebars at all times.","p":"Right! At least one hand on the handlebars."},"es":{"q":"En Louisiana, ¿qué exige la ley a la persona que maneja una bicicleta?","o":["Las dos manos en el manubrio siempre","Una placa en la bicicleta","Un claxon en el manubrio","Al menos una mano en el manubrio siempre"],"h1":"El ciclista debe mantener el control.","h2":"En Louisiana, la persona que maneja una bicicleta debe tener al menos una mano en el manubrio en todo momento.","p":"¡Correcto! Al menos una mano en el manubrio."},"ref":{"doc":"LA","page":97}},{"id":"la-155","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, how much of a traffic lane is a motorcycle allowed to use?","o":["Half of the lane","The full width of the lane","Only the right third","Only the shoulder"],"h1":"Do not share a lane with a motorcycle.","h2":"In Louisiana, motorcycles are allowed the full width of a lane, so you should not share a lane with one.","p":"Correct! The full lane."},"es":{"q":"En Louisiana, ¿qué parte de un carril puede usar una motocicleta?","o":["La mitad del carril","Todo el ancho del carril","Solo el tercio derecho","Solo el acotamiento"],"h1":"No comparta el carril con una motocicleta.","h2":"En Louisiana, las motocicletas tienen derecho a todo el ancho del carril, así que no debe compartir el carril con una.","p":"¡Correcto! Todo el carril."},"ref":{"doc":"LA","page":82}},{"id":"la-156","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, how much following distance should you leave behind a motorcycle?","o":["At least 4 seconds","1 second","2 seconds","Half a second"],"h1":"It is more than the normal three seconds.","h2":"In Louisiana, the driver's guide says to allow at least a four-second following distance behind a motorcycle.","p":"Right! At least four seconds."},"es":{"q":"Según la guía de Louisiana, ¿qué distancia de seguimiento debe dejar detrás de una motocicleta?","o":["Al menos 4 segundos","1 segundo","2 segundos","Medio segundo"],"h1":"Es más que los tres segundos normales.","h2":"En Louisiana, la guía de manejo dice que debe dejar al menos cuatro segundos de distancia detrás de una motocicleta.","p":"¡Correcto! Al menos cuatro segundos."},"ref":{"doc":"LA","page":82}},{"id":"la-157","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, how much distance does a loaded tractor-trailer going 55 mph on a dry road need, at least, to stop?","o":["About 50 feet","About 100 feet","At least 290 feet","About 2 miles"],"h1":"It is close to the length of a football field.","h2":"In Louisiana, the driver's guide says a loaded tractor-trailer at 55 mph on a dry road needs at least 290 feet to stop.","p":"Correct! At least 290 feet."},"es":{"q":"Según la guía de Louisiana, ¿qué distancia mínima necesita un tráiler cargado a 55 mph en un camino seco para detenerse?","o":["Unos 50 pies","Unos 100 pies","Al menos 290 pies","Unas 2 millas"],"h1":"Es casi el largo de una cancha de fútbol americano.","h2":"En Louisiana, la guía de manejo dice que un tráiler cargado a 55 mph en un camino seco necesita al menos 290 pies para detenerse.","p":"¡Correcto! Al menos 290 pies."},"ref":{"doc":"LA","page":83}},{"id":"la-158","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, in good weather, what gap should you leave behind a large truck?","o":["1 second","2 seconds","Half a second","At least 4 to 5 seconds"],"h1":"You need room to see around it and avoid road spray.","h2":"In Louisiana, the driver's guide says to leave at least four to five seconds behind a truck in good conditions, and more in poor conditions.","p":"Right! At least 4 to 5 seconds."},"es":{"q":"Según la guía de Louisiana, con buen tiempo, ¿qué espacio debe dejar detrás de un camión grande?","o":["1 segundo","2 segundos","Medio segundo","Al menos 4 a 5 segundos"],"h1":"Necesita espacio para ver más allá y evitar el agua que levanta.","h2":"En Louisiana, la guía de manejo dice que debe dejar al menos cuatro a cinco segundos detrás de un camión con buen tiempo, y más con mal tiempo.","p":"¡Correcto! Al menos 4 a 5 segundos."},"ref":{"doc":"LA","page":84}},{"id":"la-159","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, you reach an intersection where the traffic light is completely dark and not working. What should you do?","o":["Drive through if the cross street looks empty","Treat it as an all-way (four-way) stop","Yield only to trucks","Honk and keep going"],"h1":"Everyone must stop.","h2":"In Louisiana, when a traffic signal is not working, the intersection becomes an all-way or four-way stop.","p":"Correct! Treat it as an all-way stop."},"es":{"q":"En Louisiana, llega a una intersección donde el semáforo está apagado y no funciona. ¿Qué debe hacer?","o":["Pasar si la calle transversal parece vacía","Tratarla como un alto en todas las direcciones","Ceder el paso solo a camiones","Tocar el claxon y seguir"],"h1":"Todos deben detenerse.","h2":"En Louisiana, cuando un semáforo no funciona, la intersección pasa a ser un alto en todas las direcciones.","p":"¡Correcto! Trátela como un alto en todas las direcciones."},"ref":{"doc":"LA","page":86}},{"id":"la-160","scope":"LA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Louisiana, two vehicles reach a four-way stop at the same time. Which driver must yield?","o":["The driver on the left yields to the driver on the right","The driver on the right yields to the driver on the left","The driver of the smaller car","The driver going straight"],"h1":"Look to your right.","h2":"In Louisiana, when two vehicles reach an intersection at the same time, the driver on the left must yield to the vehicle on the right.","p":"Right! The left driver yields to the right."},"es":{"q":"En Louisiana, dos vehículos llegan al mismo tiempo a un alto de cuatro vías. ¿Qué conductor debe ceder el paso?","o":["El de la izquierda cede el paso al de la derecha","El de la derecha cede el paso al de la izquierda","El del carro más pequeño","El que va derecho"],"h1":"Mire a su derecha.","h2":"En Louisiana, cuando dos vehículos llegan al mismo tiempo a una intersección, el conductor de la izquierda debe ceder el paso al vehículo de la derecha.","p":"¡Correcto! El de la izquierda cede el paso al de la derecha."},"ref":{"doc":"LA","page":93}},{"id":"la-161","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, you are on a dirt road that meets a paved road. Who has the right of way?","o":["You, if you got there first","The larger vehicle","Traffic on the paved road","Traffic turning left"],"h1":"The bigger, paved road comes first.","h2":"In Louisiana, a driver on an unpaved road that meets a paved road must yield the right of way to traffic on the paved road.","p":"Correct! Traffic on the paved road goes first."},"es":{"q":"En Louisiana, usted va por un camino de tierra que llega a un camino pavimentado. ¿Quién tiene el derecho de paso?","o":["Usted, si llegó primero","El vehículo más grande","El tránsito del camino pavimentado","El tránsito que gira a la izquierda"],"h1":"El camino pavimentado va primero.","h2":"En Louisiana, el conductor en un camino sin pavimentar que llega a uno pavimentado debe ceder el paso al tránsito del camino pavimentado.","p":"¡Correcto! El tránsito del camino pavimentado pasa primero."},"ref":{"doc":"LA","page":93}},{"id":"la-162","scope":"LA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Louisiana, you are on a road that ends at a T intersection. Who must yield?","o":["Traffic on the through road","Whoever arrives second","No one; it is an open intersection","You, to vehicles on the through road"],"h1":"Your road is the one that ends.","h2":"In Louisiana, at a T intersection you must yield to vehicles on the through road.","p":"Right! You yield to the through road."},"es":{"q":"En Louisiana, usted va por un camino que termina en una intersección en T. ¿Quién debe ceder el paso?","o":["El tránsito del camino que sigue","Quien llegue segundo","Nadie; es una intersección libre","Usted, a los vehículos del camino que sigue"],"h1":"Su camino es el que termina.","h2":"En Louisiana, en una intersección en T usted debe ceder el paso a los vehículos del camino que continúa.","p":"¡Correcto! Usted cede el paso al camino que continúa."},"ref":{"doc":"LA","page":93}},{"id":"la-163","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, how far before a stop does a school bus driver turn on the flashing yellow lights?","o":["10 to 50 feet","100 to 500 feet","More than 1,000 feet","Only after the bus stops"],"h1":"Yellow lights are an early warning.","h2":"In Louisiana, school bus drivers turn on the flashing yellow lights at least 100 feet but no more than 500 feet before the bus stop.","p":"Correct! 100 to 500 feet before the stop."},"es":{"q":"En Louisiana, ¿a qué distancia antes de una parada enciende el chofer del autobús escolar las luces amarillas intermitentes?","o":["10 a 50 pies","100 a 500 pies","Más de 1,000 pies","Solo después de detenerse"],"h1":"Las luces amarillas son un aviso previo.","h2":"En Louisiana, los choferes de autobús escolar encienden las luces amarillas intermitentes al menos 100 pies y no más de 500 pies antes de la parada.","p":"¡Correcto! De 100 a 500 pies antes de la parada."},"ref":{"doc":"LA","page":88}},{"id":"la-164","scope":"LA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Louisiana, a school bus is stopped with red lights flashing on the other side of a highway divided by a grassy median. What must you do?","o":["You do not have to stop, but drive with care","Stop at least 30 feet away","Stop and wait until the bus leaves","Pull onto the shoulder and wait"],"h1":"The median keeps traffic apart.","h2":"In Louisiana, you are not required to stop for a school bus stopped on the opposite side of a road separated by a median, ditch or barrier.","p":"Right! You need not stop, but stay careful."},"es":{"q":"En Louisiana, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una carretera dividida por un camellón de pasto. ¿Qué debe hacer?","o":["No tiene que detenerse, pero maneje con cuidado","Detenerse al menos a 30 pies","Detenerse y esperar a que el autobús se vaya","Salirse al acotamiento y esperar"],"h1":"El camellón separa el tránsito.","h2":"En Louisiana, no está obligado a detenerse por un autobús escolar detenido al otro lado de un camino separado por un camellón, una zanja o una barrera.","p":"¡Correcto! No tiene que detenerse, pero tenga cuidado."},"ref":{"doc":"LA","page":88}},{"id":"la-165","scope":"LA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Louisiana, you are on a four-lane road with a center two-way left turn lane. A school bus stops on the other side with red lights flashing. What must you do?","o":["Stop at least 30 feet away","Stop and wait for the children to cross","Pass the bus on the left only","You are not required to stop, but stay alert"],"h1":"On four- or five-lane roads, the center turn lane counts as a separation.","h2":"In Louisiana, drivers on the opposite side of a four- or five-lane road separated by a two-way left turn lane are not required to stop for a stopped school bus.","p":"Correct! You need not stop, but stay alert."},"es":{"q":"En Louisiana, usted va por un camino de cuatro carriles con un carril central para girar a la izquierda en ambos sentidos. Un autobús escolar se detiene del otro lado con luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse al menos a 30 pies","Detenerse y esperar a que crucen los niños","Rebasar el autobús solo por la izquierda","No está obligado a detenerse, pero manténgase atento"],"h1":"En caminos de cuatro o cinco carriles, el carril central de giro cuenta como separación.","h2":"En Louisiana, los conductores del lado opuesto de un camino de cuatro o cinco carriles separado por un carril central de giro a la izquierda no están obligados a detenerse por un autobús escolar detenido.","p":"¡Correcto! No tiene que detenerse, pero manténgase atento."},"ref":{"doc":"LA","page":89}},{"id":"la-166","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, a road has one lane in each direction plus a center two-way left turn lane. A school bus stops on the other side with red lights flashing. What must you do?","o":["Keep going, because the turn lane divides the road","Slow to 25 mph and pass","Stop, because this road is not a divided highway","Use the turn lane to go around the bus"],"h1":"With only one lane each way, the center lane does not count as a divider.","h2":"In Louisiana, a road with one lane in each direction and a two-way left turn lane is not a divided highway, so drivers in both directions must stop for the school bus.","p":"Right! You must stop."},"es":{"q":"En Louisiana, un camino tiene un carril en cada dirección y un carril central para girar a la izquierda. Un autobús escolar se detiene del otro lado con luces rojas intermitentes. ¿Qué debe hacer?","o":["Seguir, porque el carril de giro divide el camino","Bajar a 25 mph y pasar","Detenerse, porque este camino no es una carretera dividida","Usar el carril de giro para rodear el autobús"],"h1":"Con un solo carril por lado, el carril central no cuenta como división.","h2":"En Louisiana, un camino con un carril por dirección y un carril central de giro no es una carretera dividida, así que los conductores de ambos sentidos deben detenerse por el autobús escolar.","p":"¡Correcto! Debe detenerse."},"ref":{"doc":"LA","page":89}},{"id":"la-167","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, when do you NOT have to stop for a school bus with flashing red lights on your side of the road?","o":["When you are late for work or school","When it is fully off the road in a loading zone where no one may cross the road","When you do not see any children near the bus","When you are driving behind the bus in its lane"],"h1":"The bus must be fully off the roadway.","h2":"In Louisiana, you do not have to stop when the school bus is in a loading zone completely off the roadway where pedestrians are not allowed to cross the road.","p":"Correct! Only when it is fully off the road in such a loading zone."},"es":{"q":"En Louisiana, ¿cuándo NO tiene que detenerse por un autobús escolar con luces rojas intermitentes en su lado del camino?","o":["Cuando va tarde al trabajo o a la escuela","Cuando está totalmente fuera del camino en una zona de carga donde nadie puede cruzar el camino","Cuando no ve niños cerca del autobús","Cuando va detrás del autobús en su carril"],"h1":"El autobús debe estar totalmente fuera del camino.","h2":"En Louisiana, no tiene que detenerse cuando el autobús escolar está en una zona de carga totalmente fuera del camino donde los peatones no pueden cruzar.","p":"¡Correcto! Solo cuando está totalmente fuera del camino en esa zona de carga."},"ref":{"doc":"LA","page":88}},{"id":"la-168","scope":"LA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Louisiana, you may not turn around on a hill or curve if drivers coming from either direction cannot see your vehicle within how many feet?","o":["500 feet","50 feet","100 feet","5,000 feet"],"h1":"It is the same distance used for dimming headlights for oncoming cars.","h2":"In Louisiana, you may not turn around on a hill or curve where drivers approaching from either direction cannot see your vehicle within 500 feet.","p":"Right! 500 feet."},"es":{"q":"En Louisiana, no puede dar la vuelta en una cuesta o curva si los conductores que vienen de cualquier dirección no pueden ver su vehículo. ¿Dentro de cuántos pies?","o":["500 pies","50 pies","100 pies","5,000 pies"],"h1":"Es la misma distancia que se usa para bajar las luces ante carros de frente.","h2":"En Louisiana, no puede dar la vuelta en una cuesta o curva donde los conductores que vienen de cualquier dirección no pueden ver su vehículo a 500 pies.","p":"¡Correcto! 500 pies."},"ref":{"doc":"LA","page":90}},{"id":"la-169","scope":"LA","cat":"signals","sign":null,"c":3,"en":{"q":"In Louisiana, the driver ahead flashes the left turn signal to tell you it is safe to pass. Is this allowed?","o":["Yes, that is a proper use of the signal","Yes, but only on highways","Yes, but only at night","No, using a turn signal to tell another driver to pass is illegal"],"h1":"Turn signals are only for your own moves.","h2":"In Louisiana, it is illegal to flash your turn signal as a signal for another vehicle to pass you.","p":"Correct! It is not allowed."},"es":{"q":"En Louisiana, el conductor de adelante pone la direccional izquierda para avisarle que puede rebasar. ¿Está permitido?","o":["Sí, es un uso correcto de la direccional","Sí, pero solo en carreteras","Sí, pero solo de noche","No, usar la direccional para indicar a otro que rebase es ilegal"],"h1":"Las direccionales son solo para sus propios movimientos.","h2":"En Louisiana, es ilegal usar la direccional como señal para que otro vehículo lo rebase.","p":"¡Correcto! No está permitido."},"ref":{"doc":"LA","page":92}},{"id":"la-170","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, which of these vehicles must stop at railroad crossings?","o":["Motorcycles and mopeds of any size","Pickup trucks pulling small trailers","School buses and vehicles carrying explosives or flammable liquids","Rental cars and moving vans"],"h1":"Be ready to stop behind them.","h2":"In Louisiana, vehicles carrying passengers for hire, school buses, and vehicles carrying explosives or flammable liquids must stop at railroad crossings.","p":"Right! School buses and hazardous loads must stop."},"es":{"q":"En Louisiana, ¿cuáles de estos vehículos deben detenerse en los cruces de tren?","o":["Las motocicletas y motonetas de cualquier tamaño","Las camionetas pickup con remolques pequeños","Los autobuses escolares y los vehículos con explosivos o líquidos inflamables","Los carros rentados y las camionetas de mudanza"],"h1":"Esté listo para detenerse detrás de ellos.","h2":"En Louisiana, los vehículos que llevan pasajeros por pago, los autobuses escolares y los vehículos con explosivos o líquidos inflamables deben detenerse en los cruces de tren.","p":"¡Correcto! Los autobuses escolares y las cargas peligrosas deben detenerse."},"ref":{"doc":"LA","page":94}},{"id":"la-171","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, you drive a car with a manual transmission across railroad tracks. What should you do?","o":["Shift to neutral on the tracks","Shift before the tracks and do not change gears while crossing","Shift to a higher gear on the tracks","Stop on the tracks to look"],"h1":"A stall on the tracks is dangerous.","h2":"In Louisiana, the driver's guide says to shift before reaching the tracks and never change gears while crossing them.","p":"Correct! Do not shift on the tracks."},"es":{"q":"Según la guía de Louisiana, usted maneja un carro de transmisión manual y cruza vías del tren. ¿Qué debe hacer?","o":["Poner neutral sobre las vías","Cambiar de velocidad antes de las vías y no cambiar mientras cruza","Subir de velocidad sobre las vías","Detenerse sobre las vías para mirar"],"h1":"Apagarse sobre las vías es peligroso.","h2":"En Louisiana, la guía de manejo dice que cambie de velocidad antes de llegar a las vías y nunca mientras las cruza.","p":"¡Correcto! No cambie de velocidad sobre las vías."},"ref":{"doc":"LA","page":95}},{"id":"la-172","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana, how many people may ride in the front seat of a moving vehicle?","o":["No more than three","No more than two","No more than four","Any number, if all wear belts"],"h1":"The driver counts as one.","h2":"In Louisiana, it is against the law for more than three people to ride in the front seat of a moving vehicle.","p":"Right! No more than three."},"es":{"q":"En Louisiana, ¿cuántas personas pueden ir en el asiento de adelante de un vehículo en movimiento?","o":["No más de tres","No más de dos","No más de cuatro","Cualquier número, si todos usan cinturón"],"h1":"El conductor cuenta como uno.","h2":"En Louisiana, es ilegal que más de tres personas vayan en el asiento de adelante de un vehículo en movimiento.","p":"¡Correcto! No más de tres."},"ref":{"doc":"LA","page":96}},{"id":"la-173","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, who may never ride in the open bed of a pickup truck, on any road?","o":["Adults over 65","Teens 16 and 17","Riders without a helmet","Children under 12"],"h1":"It is a young age group.","h2":"In Louisiana, no child under 12 may ride as a passenger in the open bed of a truck.","p":"Correct! Children under 12."},"es":{"q":"En Louisiana, ¿quién nunca puede ir en la caja abierta de una camioneta pickup, en ningún camino?","o":["Adultos mayores de 65","Jóvenes de 16 y 17","Pasajeros sin casco","Niños menores de 12"],"h1":"Es un grupo de edad joven.","h2":"En Louisiana, ningún niño menor de 12 años puede ir como pasajero en la caja abierta de una camioneta.","p":"¡Correcto! Los niños menores de 12."},"ref":{"doc":"LA","page":96}},{"id":"la-174","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, may you put material you cannot see through on your windshield or front side windows?","o":["Yes, any time","Yes, on the windshield only","No, unless a physician prescribes it","Yes, on the front side windows only"],"h1":"There is a medical exception.","h2":"In Louisiana, non-transparent material on the front windshield or front side windows is illegal unless prescribed by a physician.","p":"Right! Only with a physician's prescription."},"es":{"q":"En Louisiana, ¿puede poner material que no deja ver a través en el parabrisas o en las ventanas delanteras laterales?","o":["Sí, en cualquier momento","Sí, solo en el parabrisas","No, a menos que un médico lo indique","Sí, solo en las ventanas delanteras laterales"],"h1":"Hay una excepción médica.","h2":"En Louisiana, el material no transparente en el parabrisas o en las ventanas delanteras laterales es ilegal a menos que lo indique un médico.","p":"¡Correcto! Solo con indicación médica."},"ref":{"doc":"LA","page":96}},{"id":"la-175","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, a house trailer is being towed on the highway. May people ride inside it?","o":["Yes, if everyone wears a seat belt","No, riding in a house trailer while it is moved is not allowed","Yes, but only adults 18 and older","Yes, if the truck stays under 45 mph"],"h1":"It is not built to protect riders on the road.","h2":"In Louisiana, riding in a house trailer is not allowed while it is being moved on a highway.","p":"Correct! No one may ride in it."},"es":{"q":"En Louisiana, se remolca una casa rodante (house trailer) por la carretera. ¿Pueden ir personas adentro?","o":["Sí, si todos usan cinturón","No, no se permite ir en una casa rodante mientras la mueven","Sí, pero solo adultos de 18 años o más","Sí, si el camión va a menos de 45 mph"],"h1":"No está hecha para proteger a pasajeros en la carretera.","h2":"En Louisiana, no se permite viajar dentro de una casa rodante mientras la mueven por una carretera.","p":"¡Correcto! Nadie puede ir adentro."},"ref":{"doc":"LA","page":96}},{"id":"la-176","scope":"LA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Louisiana, you are driving in a funeral procession. What must your vehicle show?","o":["Headlights on and emergency flashers flashing","Parking lights only, with no flashers","No lights at all during the day","High beams only, with no flashers"],"h1":"Other drivers must see you belong to the procession.","h2":"In Louisiana, each driver in a funeral procession must have headlights on and emergency lights flashing, and other drivers must yield to the procession.","p":"Right! Headlights and flashers on."},"es":{"q":"En Louisiana, usted va en un cortejo fúnebre. ¿Qué debe mostrar su vehículo?","o":["Luces delanteras encendidas y luces de emergencia intermitentes","Solo luces de estacionamiento, sin intermitentes","Ninguna luz durante el día","Solo luces altas, sin intermitentes"],"h1":"Los demás deben ver que usted va en el cortejo.","h2":"En Louisiana, cada conductor de un cortejo fúnebre debe llevar las luces delanteras encendidas y las de emergencia intermitentes, y los demás deben cederle el paso al cortejo.","p":"¡Correcto! Luces delanteras y de emergencia encendidas."},"ref":{"doc":"LA","page":97}},{"id":"la-177","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, a fire truck has stopped to answer a call. Where may you not park?","o":["In any parking lot in town","Within the block where the emergency vehicle has stopped","More than a mile away","On a different street"],"h1":"Leave the area around the emergency clear.","h2":"In Louisiana, you must not follow an emergency vehicle and park within the block where it has stopped.","p":"Correct! Do not park in that block."},"es":{"q":"En Louisiana, un camión de bomberos se detuvo para atender una llamada. ¿Dónde no puede estacionarse?","o":["En cualquier estacionamiento de la ciudad","Dentro de la cuadra donde se detuvo el vehículo de emergencia","A más de una milla","En otra calle"],"h1":"Deje libre el área alrededor de la emergencia.","h2":"En Louisiana, no debe seguir a un vehículo de emergencia ni estacionarse en la cuadra donde se detuvo.","p":"¡Correcto! No se estacione en esa cuadra."},"ref":{"doc":"LA","page":97}},{"id":"la-178","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, a fire department hose lies across the street with nothing protecting it. What should you do?","o":["Drive over it slowly","Drive over it quickly","Do not cross it unless a fire department official says you may","Honk until firefighters move it"],"h1":"Firefighters need that water.","h2":"In Louisiana, you may not drive over an unprotected fire hose unless a fire department official gives consent.","p":"Right! Do not cross it without permission."},"es":{"q":"En Louisiana, una manguera de bomberos cruza la calle sin protección. ¿Qué debe hacer?","o":["Pasar por encima despacio","Pasar por encima rápido","No cruzarla a menos que un oficial de bomberos lo permita","Tocar el claxon hasta que la muevan"],"h1":"Los bomberos necesitan esa agua.","h2":"En Louisiana, no puede pasar sobre una manguera de bomberos sin protección a menos que un oficial de bomberos lo permita.","p":"¡Correcto! No la cruce sin permiso."},"ref":{"doc":"LA","page":97}},{"id":"la-179","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, you are arrested for drunk driving and refuse the alcohol test for the second time. How long is your license suspended?","o":["730 days (two years)","90 days","180 days","365 days"],"h1":"It is twice as long as for a first refusal.","h2":"In Louisiana, a second or later refusal to take the alcohol test brings a 730-day suspension of your driving privileges.","p":"Correct! 730 days."},"es":{"q":"En Louisiana, lo arrestan por manejar ebrio y se niega a la prueba de alcohol por segunda vez. ¿Por cuánto tiempo le suspenden la licencia?","o":["730 días (dos años)","90 días","180 días","365 días"],"h1":"Es el doble que por la primera negativa.","h2":"En Louisiana, una segunda negativa o más a la prueba de alcohol trae una suspensión de 730 días del privilegio de manejar.","p":"¡Correcto! 730 días."},"ref":{"doc":"LA","page":126}},{"id":"la-180","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, how big a gap in traffic do you need to merge onto the interstate?","o":["1 second","2 seconds","10 seconds","4 seconds"],"h1":"It gives you and the car behind each a two-second space.","h2":"In Louisiana, the driver's guide says you need a gap of four seconds to merge into traffic.","p":"Right! A four-second gap."},"es":{"q":"Según la guía de Louisiana, ¿qué espacio en el tránsito necesita para incorporarse a la interestatal?","o":["1 segundo","2 segundos","10 segundos","4 segundos"],"h1":"Le da a usted y al carro de atrás dos segundos de espacio a cada uno.","h2":"En Louisiana, la guía de manejo dice que necesita un espacio de cuatro segundos para incorporarse al tránsito.","p":"¡Correcto! Un espacio de cuatro segundos."},"ref":{"doc":"LA","page":101}},{"id":"la-181","scope":"LA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, on an interstate with three or more lanes in one direction, what is the far left lane mainly for?","o":["Entering and exiting","Passing","Slow trucks","Stopping in an emergency"],"h1":"The right lane is for entering and exiting, the middle for travel.","h2":"In Louisiana, the driver's guide says that on an interstate with three or more lanes, the right lane is for entering and exiting, the middle for travel, and the far left lane for passing.","p":"Correct! The far left lane is for passing."},"es":{"q":"Según la guía de Louisiana, en una interestatal con tres o más carriles en un sentido, ¿para qué es principalmente el carril de la extrema izquierda?","o":["Para entrar y salir","Para rebasar","Para camiones lentos","Para detenerse en emergencias"],"h1":"El carril derecho es para entrar y salir, el del centro para circular.","h2":"En Louisiana, la guía de manejo dice que en una interestatal de tres o más carriles, el derecho es para entrar y salir, el del centro para circular y el de la extrema izquierda para rebasar.","p":"¡Correcto! El de la extrema izquierda es para rebasar."},"ref":{"doc":"LA","page":101}},{"id":"la-182","scope":"LA","cat":"signals","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, how long should you signal before leaving the interstate at an exit?","o":["About five seconds","About one second","About 30 seconds","No signal is needed"],"h1":"Give drivers behind you time to notice.","h2":"In Louisiana, the driver's guide says to signal your intention to exit for about five seconds.","p":"Right! About five seconds."},"es":{"q":"Según la guía de Louisiana, ¿cuánto tiempo debe señalar antes de salir de la interestatal?","o":["Unos cinco segundos","Un segundo","Unos 30 segundos","No hace falta señalar"],"h1":"Dé tiempo a los de atrás para darse cuenta.","h2":"En Louisiana, la guía de manejo dice que debe señalar su salida durante unos cinco segundos.","p":"¡Correcto! Unos cinco segundos."},"ref":{"doc":"LA","page":102}},{"id":"la-183","scope":"LA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Louisiana, an orange-and-red triangle on the back of a farm or construction vehicle means it travels at less than what speed?","o":["10 mph","15 mph","25 mph","45 mph"],"h1":"It is a slow-moving vehicle sign.","h2":"In Louisiana, the orange and red slow-moving vehicle triangle means the vehicle travels at less than 25 mph.","p":"Correct! Less than 25 mph."},"es":{"q":"En Louisiana, un triángulo naranja y rojo en la parte de atrás de un vehículo agrícola o de construcción indica que es un vehículo lento. ¿A menos de qué velocidad va?","o":["10 mph","15 mph","25 mph","45 mph"],"h1":"Es la señal de vehículo lento.","h2":"En Louisiana, el triángulo naranja y rojo de vehículo lento indica que el vehículo va a menos de 25 mph.","p":"¡Correcto! A menos de 25 mph."},"ref":{"doc":"LA","page":105}},{"id":"la-184","scope":"LA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Louisiana, you are 21 or older and your alcohol test shows 0.15 percent or more. How long is your license suspended?","o":["90 days","180 days","365 days","Two years (730 days)"],"h1":"A very high reading brings a much longer suspension.","h2":"In Louisiana, if you are 21 or older and the test shows 0.15 percent or more, your driving privileges are suspended for two years (730 days).","p":"Right! Two years."},"es":{"q":"En Louisiana, usted tiene 21 años o más y su prueba de alcohol marca 0.15 por ciento o más. ¿Por cuánto tiempo le suspenden la licencia?","o":["90 días","180 días","365 días","Dos años (730 días)"],"h1":"Una lectura muy alta trae una suspensión mucho más larga.","h2":"En Louisiana, si tiene 21 años o más y la prueba marca 0.15 por ciento o más, le suspenden el privilegio de manejar por dos años (730 días).","p":"¡Correcto! Dos años."},"ref":{"doc":"LA","page":126}},{"id":"la-185","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, what is the longest loss of your driver's license for a first DWI conviction?","o":["90 days","One year (365 days)","Three years","Ten years"],"h1":"Later convictions bring two and then three years.","h2":"In Louisiana, a first DWI conviction can mean loss of your driver's license for one year (365 days).","p":"Correct! One year."},"es":{"q":"En Louisiana, ¿cuál es la pérdida más larga de licencia por una primera condena de DWI?","o":["90 días","Un año (365 días)","Tres años","Diez años"],"h1":"Las condenas siguientes traen dos y luego tres años.","h2":"En Louisiana, una primera condena de DWI puede significar la pérdida de la licencia por un año (365 días).","p":"¡Correcto! Un año."},"ref":{"doc":"LA","page":124}},{"id":"la-186","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, your wheels drop off the pavement and the shoulder is much lower. About how slow should you get before turning back onto the road?","o":["About 40 mph","About 25 mph","About 10 mph","Do not slow down; steer back at once"],"h1":"Very slow, then check traffic both ways.","h2":"In Louisiana, the driver's guide says that if the shoulder is much lower than the pavement, slow to a very slow speed, about 10 mph, before turning back onto the road.","p":"Right! About 10 mph."},"es":{"q":"Según la guía de Louisiana, sus llantas se salen del pavimento y el acotamiento está mucho más bajo. ¿A qué velocidad aproximada debe bajar antes de volver al camino?","o":["Unas 40 mph","Unas 25 mph","Unas 10 mph","No baje la velocidad; regrese de inmediato"],"h1":"Muy despacio, y luego mire el tránsito en ambos sentidos.","h2":"En Louisiana, la guía de manejo dice que si el acotamiento está mucho más bajo que el pavimento, baje a una velocidad muy lenta, unas 10 mph, antes de volver al camino.","p":"¡Correcto! Unas 10 mph."},"ref":{"doc":"LA","page":116}},{"id":"la-187","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana's driver guide, after a tire blowout, about what speed should you slow to before you use the brakes?","o":["About 60 mph","About 30 mph","About 5 mph","Brake hard right away"],"h1":"Hold the wheel firmly and let the car slow on its own first.","h2":"In Louisiana, the driver's guide says not to use the brakes after a blowout until you have slowed to a safer speed of around 30 mph.","p":"Correct! About 30 mph."},"es":{"q":"Según la guía de Louisiana, después de que revienta una llanta, ¿a qué velocidad aproximada debe bajar antes de usar los frenos?","o":["Unas 60 mph","Unas 30 mph","Unas 5 mph","Frenar fuerte de inmediato"],"h1":"Sujete bien el volante y deje que el carro baje la velocidad solo.","h2":"En Louisiana, la guía de manejo dice que no use los frenos después de que revienta una llanta hasta bajar a una velocidad más segura, de unas 30 mph.","p":"¡Correcto! Unas 30 mph."},"ref":{"doc":"LA","page":117}},{"id":"la-188","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana's driver guide, your car breaks down at night and you have flares. How far behind your car should you place them?","o":["10 feet","25 feet","50 feet","At least 100 feet"],"h1":"Give drivers time to see the warning.","h2":"In Louisiana, the driver's guide says to put flares at least 100 feet behind your car.","p":"Right! At least 100 feet."},"es":{"q":"Según la guía de Louisiana, su carro se descompone de noche y usted tiene bengalas. ¿A qué distancia detrás de su carro debe ponerlas?","o":["10 pies","25 pies","50 pies","Al menos 100 pies"],"h1":"Dé tiempo a los conductores para ver el aviso.","h2":"En Louisiana, la guía de manejo dice que ponga las bengalas al menos a 100 pies detrás de su carro.","p":"¡Correcto! Al menos 100 pies."},"ref":{"doc":"LA","page":118}},{"id":"la-189","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, your car breaks down. How can you show officers or tow trucks that you need help?","o":["Raise the hood and tie a white cloth to the antenna or hang it from a window","Stand in the road and wave","Flash your high beams at passing cars","Walk along the interstate to find help"],"h1":"Use a signal that can be seen from the road.","h2":"In Louisiana, the driver's guide says to raise your hood and tie a white cloth to the antenna or hang it out a window so officers or tow truck operators know you need help.","p":"Correct! Raise the hood and show a white cloth."},"es":{"q":"Según la guía de Louisiana, su carro se descompone. ¿Cómo puede mostrar a la policía o a las grúas que necesita ayuda?","o":["Levantar el cofre y amarrar un trapo blanco a la antena o colgarlo de una ventana","Pararse en el camino y hacer señas","Hacer cambio de luces a los carros que pasan","Caminar por la interestatal buscando ayuda"],"h1":"Use una señal que se vea desde el camino.","h2":"En Louisiana, la guía de manejo dice que levante el cofre y amarre un trapo blanco a la antena o lo cuelgue de una ventana para que la policía o las grúas sepan que necesita ayuda.","p":"¡Correcto! Levante el cofre y muestre un trapo blanco."},"ref":{"doc":"LA","page":118}},{"id":"la-190","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana's driver guide, about how long does a car usually float after it goes into water?","o":["5 to 10 minutes","2 to 3 minutes","30 to 60 seconds","Several hours"],"h1":"You have very little time, so get out right away.","h2":"In Louisiana, the driver's guide says a vehicle that enters water will float on the surface for only 30 to 60 seconds.","p":"Right! Only 30 to 60 seconds."},"es":{"q":"Según la guía de Louisiana, ¿cuánto tiempo flota más o menos un carro después de caer al agua?","o":["5 a 10 minutos","2 a 3 minutos","30 a 60 segundos","Varias horas"],"h1":"Tiene muy poco tiempo, así que salga de inmediato.","h2":"En Louisiana, la guía de manejo dice que un vehículo que cae al agua flota en la superficie solo de 30 a 60 segundos.","p":"¡Correcto! Solo de 30 a 60 segundos."},"ref":{"doc":"LA","page":119}},{"id":"la-191","scope":"LA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Louisiana, which DWI conviction is the first one that is a felony?","o":["The first","The third","The fifth","None; DWI is never a felony"],"h1":"The first two are misdemeanors.","h2":"In Louisiana, a third DWI conviction is a felony, with one to five years in prison and a three-year loss of your license.","p":"Correct! The third conviction is a felony."},"es":{"q":"En Louisiana, ¿cuál condena de DWI es la primera que se considera delito grave (felony)?","o":["La primera","La tercera","La quinta","Ninguna; el DWI nunca es delito grave"],"h1":"Las dos primeras son delitos menores.","h2":"En Louisiana, la tercera condena de DWI es un delito grave, con uno a cinco años de prisión y la pérdida de la licencia por tres años.","p":"¡Correcto! La tercera condena es delito grave."},"ref":{"doc":"LA","page":124}},{"id":"la-192","scope":"LA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Louisiana, how does the penalty for driving under the influence of drugs compare with the penalty for alcohol?","o":["It is lighter","It is a warning only","It applies only to illegal drugs","It is the same"],"h1":"It also covers some prescription and over-the-counter medicines.","h2":"In Louisiana, the law gives the same penalty for driving under the influence of drugs, including some prescription and over-the-counter medicines, as for alcohol.","p":"Right! The penalty is the same."},"es":{"q":"En Louisiana, ¿cómo se compara la sanción por manejar bajo los efectos de drogas con la del alcohol?","o":["Es más leve","Es solo una advertencia","Solo aplica a drogas ilegales","Es la misma"],"h1":"También incluye algunas medicinas recetadas y de venta libre.","h2":"En Louisiana, la ley da la misma sanción por manejar bajo los efectos de drogas, incluso algunas medicinas recetadas y de venta libre, que por el alcohol.","p":"¡Correcto! La sanción es la misma."},"ref":{"doc":"LA","page":125}},{"id":"la-193","scope":"LA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Louisiana, an officer stops you and you cannot show proof of insurance. What can happen?","o":["Your license plate is seized and you have three days to show proof at a motor vehicle office","You get a warning and nothing else","You must buy insurance from the officer","Your driver's license is canceled for ten years"],"h1":"You get a short time, not counting weekends and holidays.","h2":"In Louisiana, if you cannot show proof of insurance at a stop, your plate is seized, the vehicle may be impounded, and you have three days, not counting weekends and holidays, to show proof at a motor vehicle office.","p":"Correct! The plate is seized and you have three days."},"es":{"q":"En Louisiana, un policía lo detiene y usted no puede mostrar prueba de seguro. ¿Qué puede pasar?","o":["Le quitan la placa y tiene tres días para mostrar la prueba en una oficina de vehículos motorizados","Le dan una advertencia y nada más","Debe comprarle el seguro al policía","Le cancelan la licencia por diez años"],"h1":"Le dan poco tiempo, sin contar fines de semana ni feriados.","h2":"En Louisiana, si no puede mostrar prueba de seguro en una parada, le quitan la placa, pueden incautar el vehículo y tiene tres días, sin contar fines de semana ni feriados, para mostrar la prueba en una oficina de vehículos motorizados.","p":"¡Correcto! Le quitan la placa y tiene tres días."},"ref":{"doc":"LA","page":136}},{"id":"la-194","scope":"LA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Louisiana, after a crash, what must each driver give the others involved?","o":["Name, address and plate number, and the license if asked","Only a phone number, nothing else","Only the name of their insurance company","Nothing at all until a lawyer arrives"],"h1":"The others need to know who you are and which car was yours.","h2":"In Louisiana, drivers in a crash must give their name, address and vehicle license number and, if asked, show their driver's license to anyone involved.","p":"Right! Name, address, plate number, and license if asked."},"es":{"q":"En Louisiana, después de un choque, ¿qué debe dar cada conductor a los demás involucrados?","o":["Nombre, dirección y número de placa, y la licencia si se la piden","Solo un número de teléfono, nada más","Solo el nombre de su compañía de seguros","Nada en absoluto hasta que llegue un abogado"],"h1":"Los demás deben saber quién es usted y cuál era su carro.","h2":"En Louisiana, los conductores en un choque deben dar su nombre, dirección y número de placa y, si se lo piden, mostrar su licencia a cualquier persona involucrada.","p":"¡Correcto! Nombre, dirección, placa y licencia si se la piden."},"ref":{"doc":"LA","page":120}},{"id":"la-195","scope":"LA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Louisiana, you hit a parked car and no one is around. What must you do?","o":["Drive away if the damage looks small","Wait a few minutes, then leave if no one comes","Notify the police, try to find the owner, and leave a note with your contact information","Leave a note with only your first name on it"],"h1":"The owner must be able to reach you.","h2":"In Louisiana, if you damage an unattended vehicle or property, you must notify the police, try to find the owner, and leave a note with your name, address and phone number where the owner will see it.","p":"Correct! Call the police and leave a full note."},"es":{"q":"En Louisiana, usted choca un carro estacionado y no hay nadie. ¿Qué debe hacer?","o":["Irse si el daño parece pequeño","Esperar unos minutos e irse si nadie llega","Avisar a la policía, buscar al dueño y dejar una nota con sus datos de contacto","Dejar una nota solo con su primer nombre"],"h1":"El dueño debe poder comunicarse con usted.","h2":"En Louisiana, si daña un vehículo sin nadie o una propiedad, debe avisar a la policía, tratar de encontrar al dueño y dejar una nota con su nombre, dirección y teléfono donde el dueño la vea.","p":"¡Correcto! Avise a la policía y deje una nota completa."},"ref":{"doc":"LA","page":120}},{"id":"la-196","scope":"LA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Louisiana, what does the Move It, Move It, Move It - Steer It Clear law ask drivers to do with vehicles stopped in the roadway?","o":["Leave them exactly where they stopped","Move them off the roadway to the nearest shoulder","Push them into the median","Wait in the lane for a tow truck"],"h1":"Clearing the road prevents traffic jams and second crashes.","h2":"In Louisiana, the Move It - Steer It Clear law (R.S. 32:141(D)) makes drivers responsible for moving vehicles from the roadway to the nearest shoulder.","p":"Right! Move them to the shoulder."},"es":{"q":"En Louisiana, ¿qué pide la ley Move It, Move It, Move It - Steer It Clear a los conductores con vehículos detenidos en el camino?","o":["Dejarlos exactamente donde quedaron","Sacarlos del camino al acotamiento más cercano","Empujarlos al camellón","Esperar a la grúa en el carril"],"h1":"Despejar el camino evita embotellamientos y otros choques.","h2":"En Louisiana, la ley Move It - Steer It Clear (R.S. 32:141(D)) hace responsables a los conductores de sacar los vehículos del camino al acotamiento más cercano.","p":"¡Correcto! Sáquelos al acotamiento."},"ref":{"doc":"LA","page":121}},{"id":"la-197","scope":"LA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Louisiana, you are on a highway with two or more lanes going your way and come up on a stopped emergency vehicle with lights on. What should you do if it is safe?","o":["Speed up to pass it quickly","Stay in the lane next to it","Stop in your lane","Move into a lane that is not next to the emergency vehicle"],"h1":"Give the people working there a full lane of space.","h2":"In Louisiana, on a road with two or more lanes in your direction, you must change into a lane not next to the stopped emergency vehicle if it is safe, or else slow to a safe speed.","p":"Correct! Move to a lane not next to it."},"es":{"q":"En Louisiana, va por una carretera con dos o más carriles en su dirección y se acerca a un vehículo de emergencia detenido con luces encendidas. ¿Qué debe hacer si es seguro?","o":["Acelerar para pasarlo rápido","Seguir en el carril de al lado","Detenerse en su carril","Pasarse a un carril que no esté junto al vehículo de emergencia"],"h1":"Dé un carril completo de espacio a quienes trabajan ahí.","h2":"En Louisiana, en un camino con dos o más carriles en su dirección, debe pasarse a un carril que no esté junto al vehículo de emergencia detenido si es seguro, o si no, bajar a una velocidad segura.","p":"¡Correcto! Pásese a un carril que no esté al lado."},"ref":{"doc":"LA","page":121}},{"id":"la-198","scope":"LA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Louisiana, what is the legal alcohol limit for a person driving a commercial motor vehicle?","o":["0.08 percent","0.02 percent","0.04 percent","0.10 percent"],"h1":"It is half the limit for other adult drivers.","h2":"In Louisiana, the legal blood alcohol limit for operating a commercial motor vehicle is 0.04 percent.","p":"Right! 0.04 percent."},"es":{"q":"En Louisiana, ¿cuál es el límite legal de alcohol para quien maneja un vehículo comercial?","o":["0.08 por ciento","0.02 por ciento","0.04 por ciento","0.10 por ciento"],"h1":"Es la mitad del límite de los demás conductores adultos.","h2":"En Louisiana, el límite legal de alcohol en la sangre para manejar un vehículo comercial es 0.04 por ciento.","p":"¡Correcto! 0.04 por ciento."},"ref":{"doc":"LA","page":123}},{"id":"la-199","scope":"LA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Louisiana's driver guide, about how much alcohol does the body remove from the blood each hour?","o":["0.015 percent","0.15 percent","0.08 percent","0.5 percent"],"h1":"It is a very small amount, so it takes many hours.","h2":"In Louisiana, the driver's guide says the body can process about 0.015 percent of alcohol per hour.","p":"Correct! About 0.015 percent per hour."},"es":{"q":"Según la guía de Louisiana, ¿cuánto alcohol elimina más o menos el cuerpo de la sangre cada hora?","o":["0.015 por ciento","0.15 por ciento","0.08 por ciento","0.5 por ciento"],"h1":"Es muy poco, por eso toma muchas horas.","h2":"En Louisiana, la guía de manejo dice que el cuerpo puede procesar unos 0.015 por ciento de alcohol por hora.","p":"¡Correcto! Unos 0.015 por ciento por hora."},"ref":{"doc":"LA","page":123}},{"id":"la-200","scope":"LA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Louisiana, what does the open container law forbid in a vehicle?","o":["Carrying sealed bottles in the trunk","Having an open alcoholic drink container or drinking alcohol","Bringing bottled water","Keeping empty soda cans in a bag"],"h1":"It applies even if the driver is not drinking.","h2":"In Louisiana, the open container law forbids having any open alcoholic beverage container or drinking alcohol in a vehicle.","p":"Right! No open alcohol containers and no drinking."},"es":{"q":"En Louisiana, ¿qué prohíbe en un vehículo la ley de envases abiertos?","o":["Llevar botellas cerradas en la cajuela","Tener un envase abierto de bebida alcohólica o beber alcohol","Llevar agua embotellada","Guardar latas vacías de refresco en una bolsa"],"h1":"Aplica aunque el conductor no esté bebiendo.","h2":"En Louisiana, la ley de envases abiertos prohíbe tener cualquier envase abierto de bebida alcohólica o beber alcohol en un vehículo.","p":"¡Correcto! Nada de envases abiertos de alcohol ni beber."},"ref":{"doc":"LA","page":124}},{"id":"ma-001","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Massachusetts you can apply for a learner's permit at age 16, which is later than in many other states.","p":"Right. The Massachusetts learner's permit starts at age 16."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Massachusetts usted puede solicitar el permiso de aprendiz a los 16 años, más tarde que en muchos otros estados.","p":"Correcto. El permiso de aprendiz en Massachusetts empieza a los 16 años."},"zh":{"q":"在 Massachusetts，最小几岁可以申请学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比很多其他州晚。","h2":"在 Massachusetts，你 16 岁才可以申请学习驾照，比很多其他州晚。","p":"对。Massachusetts 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Massachusetts, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn so với nhiều tiểu bang khác.","h2":"Ở Massachusetts, bạn có thể nộp đơn xin giấy phép tập lái khi 16 tuổi, muộn hơn so với nhiều tiểu bang khác.","p":"Đúng. Giấy phép tập lái ở Massachusetts bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Massachusetts, ano ang pinakabatang edad para mag-apply ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli ito kaysa sa maraming ibang estado.","h2":"Sa Massachusetts, puwede kang mag-apply ng learner's permit sa edad na 16, na mas huli kaysa sa maraming ibang estado.","p":"Tama. Nagsisimula ang learner's permit sa Massachusetts sa edad na 16."},"ar":{"q":"في Massachusetts، ما أصغر عمر للتقدّم بطلب تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر متأخر مقارنة بولايات كثيرة أخرى.","h2":"في Massachusetts يمكنك التقدّم بطلب تصريح تعلّم القيادة في عمر 16 سنة، وهذا متأخر مقارنة بولايات كثيرة أخرى.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Massachusetts في عمر 16 سنة."},"ref":{"doc":"MA","page":15}},{"id":"ma-002","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, who must sit beside a learner's permit holder while driving?","o":["A licensed driver 21+ with 1 year of experience","Any licensed driver age 18 or older","Any adult, licensed or not","A licensed driver 25+ with 5 years of experience"],"h1":"The helper must be over 21 and must have driven for some time.","h2":"A Massachusetts permit holder must drive with a licensed driver who is at least 21 and has at least one year of driving experience in the seat beside them, so an experienced adult can help.","p":"Right. The helper is 21 or older with a year of experience."},"es":{"q":"En Massachusetts, ¿quién debe ir sentado al lado de quien tiene permiso de aprendiz?","o":["Un conductor con licencia de 21+ y 1 año de experiencia","Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25+ y 5 años de experiencia"],"h1":"El acompañante debe tener más de 21 años y haber manejado un tiempo.","h2":"En Massachusetts quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años y un año de experiencia en el asiento de al lado, para que un adulto con experiencia lo ayude.","p":"Correcto. El acompañante tiene 21 años o más y un año de experiencia."},"zh":{"q":"在 Massachusetts，持学习驾照的人开车时，谁必须坐在旁边？","o":["21 岁以上、有 1 年驾驶经验的有驾照司机","任何 18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","25 岁以上、有 5 年驾驶经验的有驾照司机"],"h1":"陪同的人必须超过 21 岁，而且必须开车开了一段时间。","h2":"在 Massachusetts，持学习驾照的人必须和一位至少 21 岁、至少有一年驾驶经验、有驾照的司机一起开车，这个人坐在旁边的座位上，这样有经验的成年人可以帮忙。","p":"对。陪同的人 21 岁或以上，有一年驾驶经验。"},"vi":{"q":"Ở Massachusetts, ai phải ngồi bên cạnh người có giấy phép tập lái khi lái xe?","o":["Người có bằng lái, từ 21 tuổi trở lên, có 1 năm kinh nghiệm","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Người có bằng lái, từ 25 tuổi trở lên, có 5 năm kinh nghiệm"],"h1":"Người hướng dẫn phải trên 21 tuổi và đã lái xe được một thời gian.","h2":"Người có giấy phép tập lái ở Massachusetts phải lái xe với một người có bằng lái, ít nhất 21 tuổi và có ít nhất một năm kinh nghiệm lái xe, ngồi ở ghế bên cạnh, để một người lớn có kinh nghiệm có thể giúp đỡ.","p":"Đúng. Người hướng dẫn từ 21 tuổi trở lên và có một năm kinh nghiệm."},"tl":{"q":"Sa Massachusetts, sino ang dapat umupo sa tabi ng may hawak ng learner's permit habang nagmamaneho?","o":["Isang may lisensyang driver na 21 pataas na may 1 taong karanasan","Kahit sinong may lisensyang driver na 18 pataas","Kahit sinong adult, may lisensya man o wala","Isang may lisensyang driver na 25 pataas na may 5 taong karanasan"],"h1":"Ang kasama ay dapat lampas 21 at matagal-tagal nang nagmamaneho.","h2":"Ang may hawak ng permit sa Massachusetts ay dapat magmaneho kasama ang isang may lisensyang driver na hindi bababa sa 21 taong gulang at may hindi bababa sa isang taong karanasan sa pagmamaneho, na nakaupo sa tabi niya, para may makatulong na adult na may karanasan.","p":"Tama. Ang kasama ay 21 pataas at may isang taong karanasan."},"ar":{"q":"في Massachusetts، من يجب أن يجلس بجانب حامل تصريح تعلّم القيادة أثناء القيادة؟","o":["سائق مرخّص عمره 21 سنة أو أكثر ولديه خبرة سنة واحدة","أي سائق مرخّص عمره 18 سنة أو أكثر","أي شخص بالغ، مرخّص أو غير مرخّص","سائق مرخّص عمره 25 سنة أو أكثر ولديه خبرة 5 سنوات"],"h1":"يجب أن يكون المرافق فوق 21 سنة وأن يكون قد قاد السيارة لبعض الوقت.","h2":"يجب على حامل التصريح في Massachusetts أن يقود مع سائق مرخّص عمره 21 سنة على الأقل ولديه خبرة قيادة سنة واحدة على الأقل، يجلس في المقعد المجاور، حتى يساعده شخص بالغ ذو خبرة.","p":"صحيح. المرافق عمره 21 سنة أو أكثر ولديه خبرة سنة."},"ref":{"doc":"MA","page":18}},{"id":"ma-003","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a permit holder under 18 may not drive during which hours unless a parent or guardian is in the car?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 11 p.m. to 6 a.m.","From midnight to 5 a.m."],"h1":"It starts when the date changes.","h2":"A Massachusetts permit holder under 18 may not drive between midnight and 5 a.m. unless a parent or guardian is with them, because late-night driving is the riskiest for new drivers.","p":"Right. No driving from midnight to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar un aprendiz menor de 18 años si no va con él un padre o tutor?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"Empieza cuando cambia la fecha.","h2":"En Massachusetts un aprendiz menor de 18 años no puede manejar entre la medianoche y las 5 a.m. si no va con él un padre o tutor, porque manejar de madrugada es lo más riesgoso para un conductor nuevo.","p":"Correcto. No se maneja de medianoche a 5 a.m. sin un padre o tutor."},"zh":{"q":"在 Massachusetts，18 岁以下持学习驾照的人，除非父母或监护人在车上，哪些时间不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","晚上 11 点到早上 6 点","午夜到早上 5 点"],"h1":"它从日期改变的时候开始。","h2":"在 Massachusetts，18 岁以下持学习驾照的人，在午夜到早上 5 点之间不能开车，除非父母或监护人一起，因为深夜开车对新司机最危险。","p":"对。没有父母或监护人，午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Massachusetts, người có giấy phép tập lái dưới 18 tuổi không được lái xe trong những giờ nào, trừ khi có cha mẹ hoặc người giám hộ trong xe?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 5 giờ sáng"],"h1":"Thời gian này bắt đầu khi sang ngày mới.","h2":"Người có giấy phép tập lái ở Massachusetts dưới 18 tuổi không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có cha mẹ hoặc người giám hộ đi cùng, vì lái xe khuya là nguy hiểm nhất đối với người mới lái.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ."},"tl":{"q":"Sa Massachusetts, sa anong oras hindi puwedeng magmaneho ang may hawak ng permit na wala pang 18, maliban kung may magulang o guardian sa sasakyan?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ito kapag nagpalit ang petsa.","h2":"Ang may hawak ng permit sa Massachusetts na wala pang 18 ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m. maliban kung kasama ang magulang o guardian, dahil pinakadelikado ang pagmamaneho sa hatinggabi para sa mga bagong driver.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. kung walang magulang o guardian."},"ar":{"q":"في Massachusetts، في أي ساعات لا يجوز لحامل التصريح الذي عمره أقل من 18 سنة أن يقود، إلا إذا كان أحد الوالدين أو الوصي في السيارة؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"تبدأ عندما يتغيّر التاريخ.","h2":"لا يجوز لحامل التصريح في Massachusetts الذي عمره أقل من 18 سنة أن يقود بين منتصف الليل و5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي، لأن القيادة في آخر الليل هي الأخطر على السائقين الجدد.","p":"صحيح. ممنوع القيادة من منتصف الليل إلى 5 صباحًا بدون أحد الوالدين أو الوصي."},"ref":{"doc":"MA","page":18}},{"id":"ma-004","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is a learner's permit valid?","o":["Up to one year","Up to two years","Up to four years","Up to five years"],"h1":"It lasts longer than one year.","h2":"A Massachusetts learner's permit is valid for up to two years, which gives enough time to finish driver education and practice.","p":"Right. The permit is valid for up to two years."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo es válido el permiso de aprendiz?","o":["Hasta un año","Hasta dos años","Hasta cuatro años","Hasta cinco años"],"h1":"Dura más de un año.","h2":"En Massachusetts el permiso de aprendiz es válido hasta por dos años, lo que da tiempo suficiente para terminar la educación vial y practicar.","p":"Correcto. El permiso es válido hasta por dos años."},"zh":{"q":"在 Massachusetts，学习驾照有效期是多久？","o":["最多一年","最多两年","最多四年","最多五年"],"h1":"它比一年长。","h2":"Massachusetts 的学习驾照有效期最多两年，这样有足够的时间完成驾驶课和练习。","p":"对。学习驾照有效期最多两年。"},"vi":{"q":"Ở Massachusetts, giấy phép tập lái có hiệu lực trong bao lâu?","o":["Tối đa một năm","Tối đa hai năm","Tối đa bốn năm","Tối đa năm năm"],"h1":"Thời hạn dài hơn một năm.","h2":"Giấy phép tập lái ở Massachusetts có hiệu lực tối đa hai năm, đủ thời gian để học xong khóa giáo dục lái xe và tập lái.","p":"Đúng. Giấy phép có hiệu lực tối đa hai năm."},"tl":{"q":"Sa Massachusetts, gaano katagal valid ang learner's permit?","o":["Hanggang isang taon","Hanggang dalawang taon","Hanggang apat na taon","Hanggang limang taon"],"h1":"Mas matagal ito sa isang taon.","h2":"Ang learner's permit sa Massachusetts ay valid nang hanggang dalawang taon, kaya may sapat na oras para tapusin ang driver education at mag-practice.","p":"Tama. Valid ang permit nang hanggang dalawang taon."},"ar":{"q":"في Massachusetts، ما مدة صلاحية تصريح تعلّم القيادة؟","o":["حتى سنة واحدة","حتى سنتين","حتى أربع سنوات","حتى خمس سنوات"],"h1":"المدة أطول من سنة واحدة.","h2":"تصريح تعلّم القيادة في Massachusetts صالح حتى سنتين، وهذا وقت كافٍ لإنهاء دروس تعليم القيادة والتدرّب.","p":"صحيح. التصريح صالح حتى سنتين."},"ref":{"doc":"MA","page":15}},{"id":"ma-005","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how many questions must you answer correctly to pass the 25-question learner's permit exam?","o":["15 questions","16 questions","18 questions","20 questions"],"h1":"It is fewer than 20.","h2":"To pass the Massachusetts learner's permit exam you must answer at least 18 of the 25 questions correctly within the time allowed.","p":"Right. You need 18 correct answers out of 25."},"es":{"q":"En Massachusetts, ¿cuántas preguntas debe contestar bien para aprobar el examen de permiso de aprendiz de 25 preguntas?","o":["15 preguntas","16 preguntas","18 preguntas","20 preguntas"],"h1":"Son menos de 20.","h2":"Para aprobar el examen de permiso de aprendiz de Massachusetts usted debe contestar bien por lo menos 18 de las 25 preguntas dentro del tiempo permitido.","p":"Correcto. Necesita 18 respuestas correctas de 25."},"zh":{"q":"在 Massachusetts，25 道题的学习驾照考试，必须答对几道题才能通过？","o":["15 道题","16 道题","18 道题","20 道题"],"h1":"比 20 少。","h2":"要通过 Massachusetts 的学习驾照考试，你必须在规定时间内答对 25 道题中的至少 18 道。","p":"对。25 道题你需要答对 18 道。"},"vi":{"q":"Ở Massachusetts, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi giấy phép tập lái có 25 câu hỏi?","o":["15 câu","16 câu","18 câu","20 câu"],"h1":"Số câu ít hơn 20.","h2":"Để đậu bài thi giấy phép tập lái ở Massachusetts, bạn phải trả lời đúng ít nhất 18 trong 25 câu trong thời gian cho phép.","p":"Đúng. Bạn cần trả lời đúng 18 trên 25 câu."},"tl":{"q":"Sa Massachusetts, ilang tanong ang dapat mong masagot nang tama para pumasa sa 25-tanong na learner's permit exam?","o":["15 tanong","16 tanong","18 tanong","20 tanong"],"h1":"Mas kaunti ito sa 20.","h2":"Para pumasa sa learner's permit exam ng Massachusetts, dapat mong masagot nang tama ang hindi bababa sa 18 sa 25 tanong sa loob ng ibinigay na oras.","p":"Tama. Kailangan mo ng 18 tamang sagot sa 25."},"ar":{"q":"في Massachusetts، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في امتحان تصريح تعلّم القيادة المكوّن من 25 سؤالًا؟","o":["15 سؤالًا","16 سؤالًا","18 سؤالًا","20 سؤالًا"],"h1":"العدد أقل من 20.","h2":"لتنجح في امتحان تصريح تعلّم القيادة في Massachusetts يجب أن تجيب إجابة صحيحة عن 18 سؤالًا على الأقل من 25 خلال الوقت المسموح.","p":"صحيح. تحتاج إلى 18 إجابة صحيحة من 25."},"ref":{"doc":"MA","page":16}},{"id":"ma-006","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, can you take the learner's permit exam in Spanish?","o":["Yes, Spanish is offered","No, it is English only","Only after failing in English","Only with a private tutor"],"h1":"The RMV offers the exam in many languages.","h2":"The Massachusetts learner's permit exam is offered in Spanish and many other languages, so you can take it in the language you read best.","p":"Right. You can take the Massachusetts permit exam in Spanish."},"es":{"q":"En Massachusetts, ¿se puede tomar el examen de permiso de aprendiz en español?","o":["Sí, se ofrece en español","No, solo en inglés","Solo si reprueba en inglés","Solo con un tutor privado"],"h1":"El RMV ofrece el examen en muchos idiomas.","h2":"En Massachusetts el examen de permiso de aprendiz se ofrece en español y en muchos otros idiomas, así que usted puede tomarlo en el idioma que lee mejor.","p":"Correcto. Puede tomar el examen de permiso de Massachusetts en español."},"zh":{"q":"在 Massachusetts，你可以用西班牙语参加学习驾照考试吗？","o":["可以，有西班牙语","不可以，只有英语","只能在英语考试不及格以后","只能请私人老师陪同"],"h1":"RMV 提供很多种语言的考试。","h2":"Massachusetts 的学习驾照考试有西班牙语和很多其他语言，所以你可以用你读得最好的语言参加考试。","p":"对。你可以用西班牙语参加 Massachusetts 的学习驾照考试。"},"vi":{"q":"Ở Massachusetts, bạn có thể thi giấy phép tập lái bằng tiếng Tây Ban Nha không?","o":["Có, có bài thi tiếng Tây Ban Nha","Không, chỉ có tiếng Anh","Chỉ sau khi thi rớt bằng tiếng Anh","Chỉ khi có gia sư riêng"],"h1":"RMV có bài thi bằng nhiều ngôn ngữ.","h2":"Bài thi giấy phép tập lái ở Massachusetts có bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác, nên bạn có thể thi bằng ngôn ngữ bạn đọc tốt nhất.","p":"Đúng. Bạn có thể thi giấy phép tập lái ở Massachusetts bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Massachusetts, puwede mo bang kunin ang learner's permit exam sa Spanish?","o":["Oo, may Spanish","Hindi, English lang","Pagkatapos lang bumagsak sa English","Kung may private tutor lang"],"h1":"Nag-aalok ang RMV ng exam sa maraming wika.","h2":"Ang learner's permit exam ng Massachusetts ay inaalok sa Spanish at sa maraming ibang wika, kaya puwede mo itong kunin sa wikang pinakamahusay mong nababasa.","p":"Tama. Puwede mong kunin ang permit exam ng Massachusetts sa Spanish."},"ar":{"q":"في Massachusetts، هل يمكنك أن تؤدي امتحان تصريح تعلّم القيادة باللغة الإسبانية؟","o":["نعم، الإسبانية متاحة","لا، بالإنجليزية فقط","فقط بعد الرسوب بالإنجليزية","فقط مع مدرّس خاص"],"h1":"تقدّم RMV الامتحان بلغات كثيرة.","h2":"امتحان تصريح تعلّم القيادة في Massachusetts متاح بالإسبانية وبلغات كثيرة أخرى، فيمكنك أن تؤديه باللغة التي تقرؤها أفضل.","p":"صحيح. يمكنك أن تؤدي امتحان التصريح في Massachusetts بالإسبانية."},"ref":{"doc":"MA","page":17}},{"id":"ma-007","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how long must you hold a learner's permit before the road test for a Junior Operator License?","o":["At least 1 month","At least 3 months","At least 12 months","At least 6 months"],"h1":"It is half a year, without a break.","h2":"In Massachusetts you must hold a valid learner's permit for at least six months in a row before the Junior Operator road test, and a suspension starts that time over.","p":"Right. Six months in a row with the permit."},"es":{"q":"En Massachusetts, ¿cuánto tiempo debe tener el permiso de aprendiz antes del examen de manejo para la licencia de operador joven (JOL)?","o":["Por lo menos 1 mes","Por lo menos 3 meses","Por lo menos 12 meses","Por lo menos 6 meses"],"h1":"Es medio año, sin interrupción.","h2":"En Massachusetts usted debe tener un permiso de aprendiz válido por lo menos seis meses seguidos antes del examen de manejo para la JOL, y una suspensión hace que ese tiempo empiece de nuevo.","p":"Correcto. Seis meses seguidos con el permiso."},"zh":{"q":"在 Massachusetts，你必须持有学习驾照多久，才能参加 Junior Operator License 的路考？","o":["至少 1 个月","至少 3 个月","至少 12 个月","至少 6 个月"],"h1":"是半年，中间不能中断。","h2":"在 Massachusetts，你必须连续持有有效的学习驾照至少六个月，才能参加 Junior Operator 路考；如果驾照被暂停，时间要重新算。","p":"对。连续持有学习驾照六个月。"},"vi":{"q":"Ở Massachusetts, bạn phải có giấy phép tập lái bao lâu trước khi thi lái thực hành để lấy bằng lái cho người trẻ (Junior Operator License)?","o":["Ít nhất 1 tháng","Ít nhất 3 tháng","Ít nhất 12 tháng","Ít nhất 6 tháng"],"h1":"Đó là nửa năm, không gián đoạn.","h2":"Ở Massachusetts, bạn phải có giấy phép tập lái hợp lệ ít nhất sáu tháng liên tục trước khi thi lái thực hành cho Junior Operator, và nếu bị treo giấy phép thì phải tính lại từ đầu.","p":"Đúng. Sáu tháng liên tục với giấy phép tập lái."},"tl":{"q":"Sa Massachusetts, gaano katagal mo dapat hawak ang learner's permit bago ang road test para sa Junior Operator License?","o":["Hindi bababa sa 1 buwan","Hindi bababa sa 3 buwan","Hindi bababa sa 12 buwan","Hindi bababa sa 6 na buwan"],"h1":"Kalahating taon ito, nang walang patlang.","h2":"Sa Massachusetts, dapat hawak mo ang valid na learner's permit nang hindi bababa sa anim na magkakasunod na buwan bago ang Junior Operator road test, at kapag na-suspend ito, magsisimula ulit ang bilang.","p":"Tama. Anim na magkakasunod na buwan na may permit."},"ar":{"q":"في Massachusetts، كم مدة يجب أن تحمل تصريح تعلّم القيادة قبل اختبار القيادة العملي لرخصة السائق الصغير (Junior Operator License)؟","o":["شهر واحد على الأقل","3 أشهر على الأقل","12 شهرًا على الأقل","6 أشهر على الأقل"],"h1":"نصف سنة، بدون انقطاع.","h2":"في Massachusetts يجب أن تحمل تصريح تعلّم قيادة صالحًا لمدة ستة أشهر متتالية على الأقل قبل اختبار القيادة العملي لـ Junior Operator، وإذا أُوقف التصريح تبدأ المدة من جديد.","p":"صحيح. ستة أشهر متتالية مع التصريح."},"ref":{"doc":"MA","page":9}},{"id":"ma-008","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of supervised driving must a parent or guardian certify for a Junior Operator License?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is fewer than 50 hours.","h2":"A Massachusetts Junior Operator applicant needs at least 40 hours of supervised driving, certified by a parent or guardian, in addition to driver education.","p":"Right. Forty hours of supervised driving."},"es":{"q":"En Massachusetts, ¿cuántas horas de manejo supervisado debe certificar un padre o tutor para la licencia de operador joven (JOL)?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50 horas.","h2":"En Massachusetts quien solicita la JOL necesita por lo menos 40 horas de manejo supervisado, certificadas por un padre o tutor, además de la educación vial.","p":"Correcto. Cuarenta horas de manejo supervisado."},"zh":{"q":"在 Massachusetts，申请 Junior Operator License，父母或监护人必须证明完成了多少小时有人陪同的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"比 50 小时少。","h2":"在 Massachusetts，申请 Junior Operator 的人除了上驾驶课，还需要至少 40 小时有人陪同的驾驶，由父母或监护人证明。","p":"对。四十个小时有人陪同的驾驶。"},"vi":{"q":"Ở Massachusetts, cha mẹ hoặc người giám hộ phải xác nhận bao nhiêu giờ lái xe có người giám sát để lấy Junior Operator License?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Số giờ ít hơn 50.","h2":"Người xin Junior Operator License ở Massachusetts cần ít nhất 40 giờ lái xe có người giám sát, được cha mẹ hoặc người giám hộ xác nhận, ngoài khóa giáo dục lái xe.","p":"Đúng. Bốn mươi giờ lái xe có người giám sát."},"tl":{"q":"Sa Massachusetts, ilang oras ng supervised driving ang dapat patunayan ng magulang o guardian para sa Junior Operator License?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa 50 oras.","h2":"Ang nag-a-apply ng Junior Operator License sa Massachusetts ay kailangan ng hindi bababa sa 40 oras ng supervised driving, na pinatunayan ng magulang o guardian, bukod pa sa driver education.","p":"Tama. Apatnapung oras ng supervised driving."},"ar":{"q":"في Massachusetts، كم ساعة من القيادة تحت الإشراف يجب أن يشهد بها أحد الوالدين أو الوصي للحصول على Junior Operator License؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"العدد أقل من 50 ساعة.","h2":"يحتاج المتقدّم لـ Junior Operator License في Massachusetts إلى 40 ساعة على الأقل من القيادة تحت الإشراف، يشهد بها أحد الوالدين أو الوصي، بالإضافة إلى دروس تعليم القيادة.","p":"صحيح. أربعون ساعة من القيادة تحت الإشراف."},"ref":{"doc":"MA","page":10}},{"id":"ma-009","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, the supervised driving hours drop to how many if the teen completes a driver skills development program?","o":["10 hours","20 hours","30 hours","35 hours"],"h1":"It is 10 hours less than the usual amount.","h2":"In Massachusetts a teen who completes a driver skills development program needs 30 supervised hours instead of 40.","p":"Right. Thirty hours after a driver skills program."},"es":{"q":"En Massachusetts, si el joven completa un programa de desarrollo de destrezas de manejo, ¿a cuántas horas baja el manejo supervisado?","o":["10 horas","20 horas","30 horas","35 horas"],"h1":"Son 10 horas menos de lo normal.","h2":"En Massachusetts un joven que completa un programa de desarrollo de destrezas de manejo necesita 30 horas supervisadas en lugar de 40.","p":"Correcto. Treinta horas después de un programa de destrezas."},"zh":{"q":"在 Massachusetts，如果青少年完成了驾驶技能培训课程，有人陪同的驾驶时间会减少到多少小时？","o":["10 小时","20 小时","30 小时","35 小时"],"h1":"比一般要求少 10 小时。","h2":"在 Massachusetts，完成驾驶技能培训课程的青少年，需要 30 小时有人陪同的驾驶，而不是 40 小时。","p":"对。上完驾驶技能课程后是三十个小时。"},"vi":{"q":"Ở Massachusetts, nếu thanh thiếu niên học xong một chương trình phát triển kỹ năng lái xe (driver skills development program), số giờ lái xe có người giám sát giảm xuống còn bao nhiêu?","o":["10 giờ","20 giờ","30 giờ","35 giờ"],"h1":"Ít hơn số giờ thông thường 10 giờ.","h2":"Ở Massachusetts, thanh thiếu niên học xong một chương trình phát triển kỹ năng lái xe cần 30 giờ có người giám sát thay vì 40 giờ.","p":"Đúng. Ba mươi giờ sau khi học xong chương trình kỹ năng lái xe."},"tl":{"q":"Sa Massachusetts, ilan na lang ang oras ng supervised driving kung natapos ng teen ang isang driver skills development program?","o":["10 oras","20 oras","30 oras","35 oras"],"h1":"Mas kaunti ito nang 10 oras kaysa sa karaniwan.","h2":"Sa Massachusetts, ang teen na nakatapos ng driver skills development program ay kailangan ng 30 supervised na oras sa halip na 40.","p":"Tama. Tatlumpung oras pagkatapos ng driver skills program."},"ar":{"q":"في Massachusetts، إلى كم تنخفض ساعات القيادة تحت الإشراف إذا أنهى المراهق برنامجًا لتطوير مهارات القيادة (driver skills development program)؟","o":["10 ساعات","20 ساعة","30 ساعة","35 ساعة"],"h1":"أقل من العدد المعتاد بـ 10 ساعات.","h2":"في Massachusetts يحتاج المراهق الذي أنهى برنامجًا لتطوير مهارات القيادة إلى 30 ساعة تحت الإشراف بدلًا من 40.","p":"صحيح. ثلاثون ساعة بعد برنامج مهارات القيادة."},"ref":{"doc":"MA","page":10}},{"id":"ma-010","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how many hours of classroom instruction does driver education include for teens?","o":["20 hours","30 hours","40 hours","12 hours"],"h1":"It is the same number as the reduced supervised hours.","h2":"Massachusetts driver education for teens includes 30 hours of classroom instruction on state traffic law and safe driving.","p":"Right. Thirty hours in the classroom."},"es":{"q":"En Massachusetts, ¿cuántas horas de clase en el aula incluye la educación vial para jóvenes?","o":["20 horas","30 horas","40 horas","12 horas"],"h1":"Es el mismo número que las horas supervisadas reducidas.","h2":"En Massachusetts la educación vial para jóvenes incluye 30 horas de clase en el aula sobre las leyes de tránsito del estado y el manejo seguro.","p":"Correcto. Treinta horas en el aula."},"zh":{"q":"在 Massachusetts，青少年的驾驶课包括多少小时课堂教学？","o":["20 小时","30 小时","40 小时","12 小时"],"h1":"和减少后的有人陪同时间一样。","h2":"在 Massachusetts，青少年的驾驶课包括 30 小时课堂教学，讲州交通法和安全驾驶。","p":"对。课堂里三十个小时。"},"vi":{"q":"Ở Massachusetts, khóa giáo dục lái xe cho thanh thiếu niên có bao nhiêu giờ học trên lớp?","o":["20 giờ","30 giờ","40 giờ","12 giờ"],"h1":"Bằng với số giờ có người giám sát đã được giảm.","h2":"Khóa giáo dục lái xe cho thanh thiếu niên ở Massachusetts có 30 giờ học trên lớp về luật giao thông của tiểu bang và cách lái xe an toàn.","p":"Đúng. Ba mươi giờ học trên lớp."},"tl":{"q":"Sa Massachusetts, ilang oras ng pag-aaral sa classroom ang kasama sa driver education para sa mga teen?","o":["20 oras","30 oras","40 oras","12 oras"],"h1":"Pareho ito sa nabawasang bilang ng supervised na oras.","h2":"Ang driver education para sa mga teen sa Massachusetts ay may 30 oras ng pag-aaral sa classroom tungkol sa batas trapiko ng estado at ligtas na pagmamaneho.","p":"Tama. Tatlumpung oras sa classroom."},"ar":{"q":"في Massachusetts، كم ساعة من الدروس في الصف تشمل دروس تعليم القيادة للمراهقين؟","o":["20 ساعة","30 ساعة","40 ساعة","12 ساعة"],"h1":"هو نفس عدد ساعات القيادة تحت الإشراف بعد تخفيضها.","h2":"تشمل دروس تعليم القيادة للمراهقين في Massachusetts 30 ساعة من الدروس في الصف عن قوانين المرور في الولاية والقيادة الآمنة.","p":"صحيح. ثلاثون ساعة في الصف."},"ref":{"doc":"MA","page":10}},{"id":"ma-011","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, how many hours of behind-the-wheel training with a driving school are required in teen driver education?","o":["12 hours","6 hours","18 hours","30 hours"],"h1":"The on-road part is 18 hours in all, and 6 of those are watching another student.","h2":"Massachusetts teen driver education requires at least 12 hours of behind-the-wheel training, plus 6 hours of watching another student drive.","p":"Right. Twelve hours behind the wheel."},"es":{"q":"En Massachusetts, ¿cuántas horas de práctica al volante con una escuela de manejo exige la educación vial para jóvenes?","o":["12 horas","6 horas","18 horas","30 horas"],"h1":"La parte en la calle suma 18 horas, y 6 de ellas son para observar a otro estudiante.","h2":"En Massachusetts la educación vial para jóvenes exige por lo menos 12 horas al volante, más 6 horas observando a otro estudiante manejar.","p":"Correcto. Doce horas al volante."},"zh":{"q":"在 Massachusetts，青少年驾驶课要求在驾校实际开车培训多少小时？","o":["12 小时","6 小时","18 小时","30 小时"],"h1":"上路部分一共是 18 小时，其中 6 小时是看另一个学生开车。","h2":"在 Massachusetts，青少年驾驶课要求至少 12 小时实际开车培训，另外还有 6 小时看另一个学生开车。","p":"对。实际开车十二个小时。"},"vi":{"q":"Ở Massachusetts, khóa giáo dục lái xe cho thanh thiếu niên yêu cầu bao nhiêu giờ tập lái thực tế với trường dạy lái xe?","o":["12 giờ","6 giờ","18 giờ","30 giờ"],"h1":"Phần trên đường tổng cộng 18 giờ, trong đó 6 giờ là ngồi xem học viên khác lái.","h2":"Khóa giáo dục lái xe cho thanh thiếu niên ở Massachusetts yêu cầu ít nhất 12 giờ tập lái thực tế, cộng thêm 6 giờ ngồi xem học viên khác lái.","p":"Đúng. Mười hai giờ tự cầm lái."},"tl":{"q":"Sa Massachusetts, ilang oras ng behind-the-wheel training kasama ang driving school ang kailangan sa teen driver education?","o":["12 oras","6 na oras","18 oras","30 oras"],"h1":"Ang bahagi sa kalsada ay 18 oras lahat, at 6 doon ay panonood sa ibang estudyante.","h2":"Ang teen driver education sa Massachusetts ay nangangailangan ng hindi bababa sa 12 oras ng behind-the-wheel training, dagdag ang 6 na oras ng panonood sa ibang estudyanteng nagmamaneho.","p":"Tama. Labindalawang oras sa manibela."},"ar":{"q":"في Massachusetts، كم ساعة من التدريب العملي خلف المقود مع مدرسة قيادة مطلوبة في دروس تعليم القيادة للمراهقين؟","o":["12 ساعة","6 ساعات","18 ساعة","30 ساعة"],"h1":"الجزء على الطريق 18 ساعة في المجموع، منها 6 ساعات لمشاهدة طالب آخر.","h2":"تتطلّب دروس تعليم القيادة للمراهقين في Massachusetts 12 ساعة على الأقل من التدريب العملي خلف المقود، بالإضافة إلى 6 ساعات لمشاهدة طالب آخر يقود.","p":"صحيح. اثنتا عشرة ساعة خلف المقود."},"ref":{"doc":"MA","page":10}},{"id":"ma-012","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what must a parent or guardian of a teen in driver education usually complete?","o":["A written road test","A 10-hour driving course","A first-aid class","A 2-hour parent class"],"h1":"It is a short class about the driver education course.","h2":"In Massachusetts a parent or guardian must take a 2-hour class about the driver education course, unless they took one in the past five years.","p":"Right. Parents take a 2-hour class."},"es":{"q":"En Massachusetts, ¿qué debe completar normalmente el padre o tutor de un joven en educación vial?","o":["Un examen escrito de manejo","Un curso de manejo de 10 horas","Una clase de primeros auxilios","Una clase para padres de 2 horas"],"h1":"Es una clase corta sobre el curso de educación vial.","h2":"En Massachusetts el padre o tutor debe tomar una clase de 2 horas sobre el curso de educación vial, a menos que haya tomado una en los últimos cinco años.","p":"Correcto. Los padres toman una clase de 2 horas."},"zh":{"q":"在 Massachusetts，上驾驶课的青少年的父母或监护人，一般必须完成什么？","o":["路考笔试","10 小时的驾驶课","急救课","2 小时的家长课"],"h1":"这是一门关于驾驶课的短课。","h2":"在 Massachusetts，父母或监护人必须上一门关于驾驶课的 2 小时课程，除非他们在过去五年里上过。","p":"对。父母要上 2 小时的课。"},"vi":{"q":"Ở Massachusetts, cha mẹ hoặc người giám hộ của thanh thiếu niên đang học lái xe thường phải hoàn thành điều gì?","o":["Một bài thi viết về lái xe","Một khóa lái xe 10 giờ","Một lớp sơ cứu","Một lớp 2 giờ dành cho phụ huynh"],"h1":"Đó là một lớp ngắn về khóa giáo dục lái xe.","h2":"Ở Massachusetts, cha mẹ hoặc người giám hộ phải học một lớp 2 giờ về khóa giáo dục lái xe, trừ khi họ đã học lớp này trong năm năm qua.","p":"Đúng. Phụ huynh học một lớp 2 giờ."},"tl":{"q":"Sa Massachusetts, ano ang karaniwang dapat tapusin ng magulang o guardian ng teen na nasa driver education?","o":["Isang written road test","Isang 10-oras na driving course","Isang first-aid class","Isang 2-oras na parent class"],"h1":"Isa itong maikling klase tungkol sa driver education course.","h2":"Sa Massachusetts, dapat kumuha ang magulang o guardian ng 2-oras na klase tungkol sa driver education course, maliban kung kumuha na sila nito sa nakaraang limang taon.","p":"Tama. Kumukuha ang mga magulang ng 2-oras na klase."},"ar":{"q":"في Massachusetts، ماذا يجب عادةً على أحد الوالدين أو الوصي لمراهق يدرس تعليم القيادة أن يُنهي؟","o":["اختبار طريق كتابي","دورة قيادة مدتها 10 ساعات","درس في الإسعافات الأولية","درس للوالدين مدته ساعتان"],"h1":"هو درس قصير عن دورة تعليم القيادة.","h2":"في Massachusetts يجب على أحد الوالدين أو الوصي أن يحضر درسًا مدته ساعتان عن دورة تعليم القيادة، إلا إذا حضر درسًا مثله في السنوات الخمس الماضية.","p":"صحيح. يحضر الوالدان درسًا مدته ساعتان."},"ref":{"doc":"MA","page":10}},{"id":"ma-013","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a Junior Operator License holder may not drive during which hours unless a parent or guardian is in the car?","o":["From midnight to 6 a.m.","From 11 p.m. to 5 a.m.","From 12:30 a.m. to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"It starts half an hour after midnight.","h2":"A Massachusetts Junior Operator may not drive between 12:30 a.m. and 5 a.m. unless a parent or legal guardian is with them.","p":"Right. No driving from 12:30 to 5 a.m. without a parent or guardian."},"es":{"q":"En Massachusetts, ¿en qué horario no puede manejar quien tiene licencia de operador joven (JOL) si no va con él un padre o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 12:30 a.m. a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"Empieza media hora después de la medianoche.","h2":"En Massachusetts un operador joven no puede manejar entre las 12:30 a.m. y las 5 a.m. si no va con él un padre o tutor legal.","p":"Correcto. No se maneja de 12:30 a 5 a.m. sin un padre o tutor."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人，除非父母或监护人在车上，哪些时间不能开车？","o":["午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 12:30 到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"它从午夜后半小时开始。","h2":"在 Massachusetts，持 Junior Operator License 的人在凌晨 12:30 到早上 5 点之间不能开车，除非父母或法定监护人一起。","p":"对。没有父母或监护人，凌晨 12:30 到 5 点不能开车。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License không được lái xe trong những giờ nào, trừ khi có cha mẹ hoặc người giám hộ trong xe?","o":["Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 12:30 sáng đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Thời gian này bắt đầu nửa tiếng sau nửa đêm.","h2":"Người có Junior Operator License ở Massachusetts không được lái xe từ 12:30 sáng đến 5 giờ sáng, trừ khi có cha mẹ hoặc người giám hộ hợp pháp đi cùng.","p":"Đúng. Không lái xe từ 12:30 đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ."},"tl":{"q":"Sa Massachusetts, sa anong oras hindi puwedeng magmaneho ang may Junior Operator License, maliban kung may magulang o guardian sa sasakyan?","o":["Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 12:30 a.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ito kalahating oras pagkatapos ng hatinggabi.","h2":"Ang Junior Operator sa Massachusetts ay hindi puwedeng magmaneho mula 12:30 a.m. hanggang 5 a.m. maliban kung kasama ang magulang o legal guardian.","p":"Tama. Bawal magmaneho mula 12:30 hanggang 5 a.m. kung walang magulang o guardian."},"ar":{"q":"في Massachusetts، في أي ساعات لا يجوز لحامل Junior Operator License أن يقود، إلا إذا كان أحد الوالدين أو الوصي في السيارة؟","o":["من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 12:30 بعد منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"تبدأ بعد منتصف الليل بنصف ساعة.","h2":"لا يجوز لحامل Junior Operator License في Massachusetts أن يقود بين 12:30 بعد منتصف الليل و5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي القانوني.","p":"صحيح. ممنوع القيادة من 12:30 إلى 5 صباحًا بدون أحد الوالدين أو الوصي."},"ref":{"doc":"MA","page":10}},{"id":"ma-014","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, during the first six months with a Junior Operator License, who may not ride with you unless an adult 21+ is beside you?","o":["Passengers under 18 who are not family","Any passenger over age 65","Your brothers and sisters","Any passenger at all"],"h1":"The rule is about young friends, not family.","h2":"For the first six months, a Massachusetts Junior Operator may not carry passengers under 18 who are not immediate family unless a licensed adult age 21 or older is beside them.","p":"Right. No young non-family passengers in the first six months."},"es":{"q":"En Massachusetts, durante los primeros seis meses con licencia de operador joven, ¿quién no puede ir con usted si no hay un adulto de 21+ a su lado?","o":["Pasajeros menores de 18 que no son familia","Cualquier pasajero mayor de 65 años","Sus hermanos y hermanas","Ningún pasajero en absoluto"],"h1":"La regla es sobre amigos jóvenes, no sobre la familia.","h2":"Durante los primeros seis meses, un operador joven en Massachusetts no puede llevar pasajeros menores de 18 que no sean familia directa, a menos que vaya a su lado un adulto con licencia de 21 años o más.","p":"Correcto. Nada de pasajeros jóvenes que no son familia los primeros seis meses."},"zh":{"q":"在 Massachusetts，拿到 Junior Operator License 的头六个月里，除非有一位 21 岁以上的成年人坐在你旁边，谁不能和你一起坐车？","o":["不是家人、18 岁以下的乘客","任何 65 岁以上的乘客","你的兄弟姐妹","任何乘客都不行"],"h1":"这个规定是关于年轻朋友的，不是家人。","h2":"在头六个月里，Massachusetts 持 Junior Operator License 的人不能载不是直系亲属、18 岁以下的乘客，除非一位 21 岁或以上、有驾照的成年人坐在旁边。","p":"对。头六个月不能载不是家人的年轻乘客。"},"vi":{"q":"Ở Massachusetts, trong sáu tháng đầu có Junior Operator License, ai không được đi xe với bạn, trừ khi có một người lớn từ 21 tuổi trở lên ngồi bên cạnh?","o":["Hành khách dưới 18 tuổi không phải người trong gia đình","Bất kỳ hành khách nào trên 65 tuổi","Anh chị em của bạn","Bất kỳ hành khách nào"],"h1":"Quy định này nói về bạn bè trẻ tuổi, không phải gia đình.","h2":"Trong sáu tháng đầu, người có Junior Operator License ở Massachusetts không được chở hành khách dưới 18 tuổi không phải người thân trong gia đình, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên ngồi bên cạnh.","p":"Đúng. Không chở hành khách trẻ tuổi không phải người nhà trong sáu tháng đầu."},"tl":{"q":"Sa Massachusetts, sa unang anim na buwan na may Junior Operator License, sino ang hindi puwedeng sumakay sa iyo maliban kung may adult na 21 pataas sa tabi mo?","o":["Mga pasaherong wala pang 18 na hindi kapamilya","Kahit sinong pasaherong lampas 65","Ang iyong mga kapatid","Kahit sinong pasahero"],"h1":"Tungkol ang patakaran sa mga batang kaibigan, hindi sa pamilya.","h2":"Sa unang anim na buwan, ang Junior Operator sa Massachusetts ay hindi puwedeng magsakay ng mga pasaherong wala pang 18 na hindi kasapi ng malapit na pamilya, maliban kung may may lisensyang adult na 21 pataas sa tabi niya.","p":"Tama. Bawal ang batang pasaherong hindi kapamilya sa unang anim na buwan."},"ar":{"q":"في Massachusetts، في الأشهر الستة الأولى مع Junior Operator License، من لا يجوز أن يركب معك إلا إذا كان بجانبك شخص بالغ عمره 21 سنة أو أكثر؟","o":["الركاب الذين عمرهم أقل من 18 سنة وليسوا من العائلة","أي راكب عمره أكثر من 65 سنة","إخوتك وأخواتك","أي راكب على الإطلاق"],"h1":"القاعدة عن الأصدقاء الصغار، وليست عن العائلة.","h2":"في الأشهر الستة الأولى، لا يجوز لحامل Junior Operator License في Massachusetts أن يحمل ركابًا عمرهم أقل من 18 سنة وليسوا من العائلة المباشرة، إلا إذا كان بجانبه شخص بالغ مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. ممنوع الركاب الصغار من غير العائلة في الأشهر الستة الأولى."},"ref":{"doc":"MA","page":10}},{"id":"ma-015","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the license suspension for a Junior Operator's first speeding offense?","o":["30 days","60 days","1 year","90 days"],"h1":"It is about three months.","h2":"In Massachusetts a Junior Operator's first speeding offense brings a 90-day license suspension, and a second offense brings one year.","p":"Right. A first speeding offense means 90 days without a license."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión de la licencia de un operador joven por su primera multa por exceso de velocidad?","o":["30 días","60 días","1 año","90 días"],"h1":"Son unos tres meses.","h2":"En Massachusetts la primera infracción por exceso de velocidad de un operador joven trae una suspensión de 90 días, y la segunda trae un año.","p":"Correcto. La primera multa por velocidad significa 90 días sin licencia."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人第一次超速，驾照会被暂停多久？","o":["30 天","60 天","1 年","90 天"],"h1":"大约是三个月。","h2":"在 Massachusetts，持 Junior Operator License 的人第一次超速，驾照会被暂停 90 天，第二次会被暂停一年。","p":"对。第一次超速，90 天没有驾照。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License vi phạm chạy quá tốc độ lần đầu sẽ bị treo bằng lái bao lâu?","o":["30 ngày","60 ngày","1 năm","90 ngày"],"h1":"Khoảng ba tháng.","h2":"Ở Massachusetts, người có Junior Operator License vi phạm chạy quá tốc độ lần đầu bị treo bằng lái 90 ngày, và lần thứ hai bị treo một năm.","p":"Đúng. Chạy quá tốc độ lần đầu là 90 ngày không có bằng lái."},"tl":{"q":"Sa Massachusetts, gaano katagal ang suspensyon ng lisensya para sa unang speeding offense ng Junior Operator?","o":["30 araw","60 araw","1 taon","90 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa Massachusetts, ang unang speeding offense ng Junior Operator ay may 90-araw na suspensyon ng lisensya, at ang ikalawa ay isang taon.","p":"Tama. Ang unang speeding offense ay 90 araw na walang lisensya."},"ar":{"q":"في Massachusetts، ما مدة إيقاف الرخصة لأول مخالفة سرعة لحامل Junior Operator License؟","o":["30 يومًا","60 يومًا","سنة واحدة","90 يومًا"],"h1":"حوالي ثلاثة أشهر.","h2":"في Massachusetts تؤدي أول مخالفة سرعة لحامل Junior Operator License إلى إيقاف الرخصة 90 يومًا، والمخالفة الثانية تؤدي إلى إيقافها سنة واحدة.","p":"صحيح. أول مخالفة سرعة تعني 90 يومًا بدون رخصة."},"ref":{"doc":"MA","page":11}},{"id":"ma-016","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the suspension for a Junior Operator's first passenger or night-time violation?","o":["30 days","60 days","90 days","180 days"],"h1":"It is two months.","h2":"A Massachusetts Junior Operator who breaks the passenger or night-time rule for the first time loses the license for 60 days.","p":"Right. Sixty days for a first passenger or night violation."},"es":{"q":"En Massachusetts, ¿cuál es la suspensión por la primera infracción de pasajeros o de horario nocturno de un operador joven?","o":["30 días","60 días","90 días","180 días"],"h1":"Son dos meses.","h2":"En Massachusetts un operador joven que no cumple por primera vez la regla de pasajeros o de horario nocturno pierde la licencia por 60 días.","p":"Correcto. Sesenta días por la primera infracción de pasajeros o de noche."},"zh":{"q":"在 Massachusetts，持 Junior Operator License 的人第一次违反乘客或夜间规定，驾照会被暂停多久？","o":["30 天","60 天","90 天","180 天"],"h1":"是两个月。","h2":"在 Massachusetts，持 Junior Operator License 的人第一次违反乘客或夜间规定，会失去驾照 60 天。","p":"对。第一次违反乘客或夜间规定，暂停六十天。"},"vi":{"q":"Ở Massachusetts, người có Junior Operator License vi phạm quy định về hành khách hoặc lái xe ban đêm lần đầu sẽ bị treo bằng lái bao lâu?","o":["30 ngày","60 ngày","90 ngày","180 ngày"],"h1":"Đó là hai tháng.","h2":"Người có Junior Operator License ở Massachusetts vi phạm quy định về hành khách hoặc lái xe ban đêm lần đầu sẽ bị mất bằng lái 60 ngày.","p":"Đúng. Sáu mươi ngày cho lần đầu vi phạm quy định về hành khách hoặc ban đêm."},"tl":{"q":"Sa Massachusetts, gaano katagal ang suspensyon para sa unang paglabag ng Junior Operator sa patakaran sa pasahero o sa gabi?","o":["30 araw","60 araw","90 araw","180 araw"],"h1":"Dalawang buwan ito.","h2":"Ang Junior Operator sa Massachusetts na unang lumabag sa patakaran sa pasahero o sa gabi ay mawawalan ng lisensya nang 60 araw.","p":"Tama. Animnapung araw para sa unang paglabag sa pasahero o sa gabi."},"ar":{"q":"في Massachusetts، ما مدة الإيقاف لأول مخالفة لقاعدة الركاب أو القيادة الليلية لحامل Junior Operator License؟","o":["30 يومًا","60 يومًا","90 يومًا","180 يومًا"],"h1":"شهران.","h2":"حامل Junior Operator License في Massachusetts الذي يخالف قاعدة الركاب أو القيادة الليلية لأول مرة يفقد الرخصة لمدة 60 يومًا.","p":"صحيح. ستون يومًا لأول مخالفة للركاب أو الليل."},"ref":{"doc":"MA","page":11}},{"id":"ma-017","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, may a driver under 18 talk on a phone in hands-free mode while driving?","o":["Yes, with a headset only","Yes, on the highway only","No, except to report an emergency","Yes, if a parent calls"],"h1":"Drivers under 18 have a stricter rule than adults.","h2":"In Massachusetts a driver under 18 may not use any phone or mobile device while driving, even hands-free, except to report an emergency.","p":"Right. Drivers under 18 may not use a phone at all, except for emergencies."},"es":{"q":"En Massachusetts, ¿puede un conductor menor de 18 años hablar por teléfono en modo manos libres mientras maneja?","o":["Sí, solo con auriculares","Sí, solo en la autopista","No, salvo para reportar una emergencia","Sí, si llaman sus padres"],"h1":"Los menores de 18 tienen una regla más estricta que los adultos.","h2":"En Massachusetts un conductor menor de 18 años no puede usar ningún teléfono ni aparato móvil mientras maneja, ni siquiera con manos libres, salvo para reportar una emergencia.","p":"Correcto. Los menores de 18 no usan el teléfono, salvo en emergencias."},"zh":{"q":"在 Massachusetts，18 岁以下的司机开车时可以用免提模式打电话吗？","o":["可以，但只能用耳机","可以，但只能在高速公路上","不可以，除非报告紧急情况","可以，如果是父母打来的"],"h1":"18 岁以下的司机，规定比成年人更严格。","h2":"在 Massachusetts，18 岁以下的司机开车时不能使用任何手机或移动设备，免提也不行，只有报告紧急情况除外。","p":"对。18 岁以下的司机完全不能用手机，紧急情况除外。"},"vi":{"q":"Ở Massachusetts, người lái xe dưới 18 tuổi có được nói chuyện điện thoại ở chế độ rảnh tay khi lái xe không?","o":["Có, chỉ khi dùng tai nghe","Có, chỉ trên xa lộ","Không, trừ khi để báo trường hợp khẩn cấp","Có, nếu cha mẹ gọi"],"h1":"Người lái xe dưới 18 tuổi có quy định nghiêm hơn người lớn.","h2":"Ở Massachusetts, người lái xe dưới 18 tuổi không được dùng bất kỳ điện thoại hoặc thiết bị di động nào khi lái xe, kể cả chế độ rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Người lái xe dưới 18 tuổi hoàn toàn không được dùng điện thoại, trừ trường hợp khẩn cấp."},"tl":{"q":"Sa Massachusetts, puwede bang makipag-usap sa phone nang hands-free ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, gamit lang ang headset","Oo, sa highway lang","Hindi, maliban para mag-report ng emergency","Oo, kung magulang ang tumawag"],"h1":"Mas mahigpit ang patakaran para sa mga driver na wala pang 18 kaysa sa mga adult.","h2":"Sa Massachusetts, ang driver na wala pang 18 ay hindi puwedeng gumamit ng anumang phone o mobile device habang nagmamaneho, kahit hands-free, maliban para mag-report ng emergency.","p":"Tama. Bawal talaga sa phone ang mga driver na wala pang 18, maliban sa emergency."},"ar":{"q":"في Massachusetts، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتحدث في الهاتف بوضع عدم استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، مع سماعة رأس فقط","نعم، على الطريق السريع فقط","لا، إلا للإبلاغ عن حالة طوارئ","نعم، إذا اتصل أحد الوالدين"],"h1":"للسائقين تحت 18 سنة قاعدة أشد من البالغين.","h2":"في Massachusetts لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم أي هاتف أو جهاز محمول أثناء القيادة، حتى بوضع hands-free، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. السائقون تحت 18 سنة لا يستخدمون الهاتف أبدًا، إلا في حالات الطوارئ."},"ref":{"doc":"MA","page":40}},{"id":"ma-018","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, how may an adult driver use a phone while driving?","o":["Only in hands-free mode","Holding it at red lights","Holding it on quiet streets","Holding it for short calls"],"h1":"Your hands stay on the wheel.","h2":"Massachusetts law lets adult drivers use a phone only in hands-free mode, with the phone mounted, and allows a single touch to start hands-free mode.","p":"Right. Adults may use a phone only hands-free."},"es":{"q":"En Massachusetts, ¿cómo puede un conductor adulto usar el teléfono mientras maneja?","o":["Solo en modo manos libres","Sosteniéndolo en los semáforos","Sosteniéndolo en calles tranquilas","Sosteniéndolo en llamadas cortas"],"h1":"Sus manos se quedan en el volante.","h2":"La ley de Massachusetts permite a los adultos usar el teléfono solo en modo manos libres, con el teléfono sujeto en un soporte, y permite tocarlo una vez para activar ese modo.","p":"Correcto. Los adultos usan el teléfono solo con manos libres."},"zh":{"q":"在 Massachusetts，成年司机开车时可以怎样使用手机？","o":["只能用免提模式","红灯时拿在手里","在安静的街道上拿在手里","短时间通话时拿在手里"],"h1":"你的手要一直放在方向盘上。","h2":"Massachusetts 法律只允许成年司机用免提模式使用手机，手机要固定在支架上，可以按一下来开启免提模式。","p":"对。成年人只能用免提使用手机。"},"vi":{"q":"Ở Massachusetts, người lái xe trưởng thành được dùng điện thoại khi lái xe như thế nào?","o":["Chỉ ở chế độ rảnh tay","Cầm trên tay khi gặp đèn đỏ","Cầm trên tay trên đường vắng","Cầm trên tay cho cuộc gọi ngắn"],"h1":"Tay bạn luôn ở trên vô lăng.","h2":"Luật Massachusetts chỉ cho phép người lái xe trưởng thành dùng điện thoại ở chế độ rảnh tay, với điện thoại được gắn cố định, và cho phép chạm một lần để bật chế độ rảnh tay.","p":"Đúng. Người lớn chỉ được dùng điện thoại ở chế độ rảnh tay."},"tl":{"q":"Sa Massachusetts, paano puwedeng gumamit ng phone ang adult na driver habang nagmamaneho?","o":["Sa hands-free mode lang","Hawak ito sa red light","Hawak ito sa tahimik na kalye","Hawak ito para sa maikling tawag"],"h1":"Nananatili ang mga kamay mo sa manibela.","h2":"Pinapayagan ng batas ng Massachusetts ang mga adult na driver na gumamit ng phone sa hands-free mode lang, na nakakabit ang phone, at pinapayagan ang isang pindot para buksan ang hands-free mode.","p":"Tama. Puwedeng gumamit ng phone ang mga adult nang hands-free lang."},"ar":{"q":"في Massachusetts، كيف يجوز للسائق البالغ أن يستخدم الهاتف أثناء القيادة؟","o":["بوضع عدم استخدام اليدين (hands-free) فقط","يمسكه في يده عند الإشارة الحمراء","يمسكه في يده في الشوارع الهادئة","يمسكه في يده للمكالمات القصيرة"],"h1":"يداك تبقيان على المقود.","h2":"يسمح قانون Massachusetts للسائقين البالغين باستخدام الهاتف بوضع عدم استخدام اليدين (hands-free) فقط، مع تثبيت الهاتف في حامل، ويسمح بلمسة واحدة لتشغيل هذا الوضع.","p":"صحيح. البالغون يستخدمون الهاتف بوضع عدم استخدام اليدين (hands-free) فقط."},"ref":{"doc":"MA","page":39}},{"id":"ma-019","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, a blood alcohol level of what amount or more is a violation for a driver under 21?","o":["0.01 percent","0.02 percent","0.05 percent","0.08 percent"],"h1":"It is far below the adult limit.","h2":"In Massachusetts a driver under 21 with a blood alcohol level of 0.02 percent or more faces a license suspension, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Massachusetts, ¿a partir de qué nivel de alcohol en la sangre comete una infracción un conductor menor de 21 años?","o":["0.01 por ciento","0.02 por ciento","0.05 por ciento","0.08 por ciento"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Massachusetts un conductor menor de 21 años con 0.02 por ciento de alcohol en la sangre o más recibe una suspensión de licencia, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Massachusetts，21 岁以下的司机血液酒精浓度达到多少或以上就是违规？","o":["0.01%","0.02%","0.05%","0.08%"],"h1":"这远低于成年人的上限。","h2":"在 Massachusetts，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，驾照会被暂停，因为年轻司机完全不应该喝酒。","p":"对。21 岁以下，上限是 0.02%。"},"vi":{"q":"Ở Massachusetts, nồng độ cồn trong máu từ mức nào trở lên là vi phạm đối với người lái xe dưới 21 tuổi?","o":["0.01 phần trăm","0.02 phần trăm","0.05 phần trăm","0.08 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Massachusetts, người lái xe dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên sẽ bị treo bằng lái, vì người lái xe trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Massachusetts, anong blood alcohol level o higit pa ang paglabag para sa driver na wala pang 21?","o":["0.01 porsiyento","0.02 porsiyento","0.05 porsiyento","0.08 porsiyento"],"h1":"Mas mababa ito nang malayo sa limit para sa adult.","h2":"Sa Massachusetts, ang driver na wala pang 21 na may blood alcohol level na 0.02 porsiyento o higit pa ay masu-suspend ang lisensya, dahil hindi dapat uminom ng alak ang mga batang driver.","p":"Tama. Kapag wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في Massachusetts، أي نسبة كحول في الدم أو أكثر تُعتبر مخالفة للسائق الذي عمره أقل من 21 سنة؟","o":["0.01 بالمئة","0.02 بالمئة","0.05 بالمئة","0.08 بالمئة"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Massachusetts يواجه السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر إيقاف رخصته، لأن السائقين الصغار يجب ألّا يشربوا الكحول أبدًا.","p":"صحيح. تحت 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"MA","page":73}},{"id":"ma-020","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a thickly settled or business district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Some towns choose a lower limit, but the state default is a little higher.","h2":"The Massachusetts default limit in a thickly settled or business district is 30 mph, although some cities and towns lower it to 25 mph on local roads.","p":"Right. The default in thickly settled areas is 30 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona densamente poblada o comercial?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Algunos pueblos ponen un límite más bajo, pero el del estado es un poco más alto.","h2":"En Massachusetts el límite normal en una zona densamente poblada o comercial es de 30 mph, aunque algunas ciudades y pueblos lo bajan a 25 mph en calles locales.","p":"Correcto. En zonas densamente pobladas el límite normal es 30 mph."},"zh":{"q":"在 Massachusetts，如果没有标志另外说明，人口稠密区或商业区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"有些城镇选择更低的限速，但州的默认限速高一点。","h2":"Massachusetts 人口稠密区或商业区的默认限速是 30 mph，不过有些城镇在当地道路上把它降到 25 mph。","p":"对。人口稠密区的默认限速是 30 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trong khu dân cư đông đúc (thickly settled) hoặc khu thương mại là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Một số thị trấn chọn giới hạn thấp hơn, nhưng mức mặc định của tiểu bang cao hơn một chút.","h2":"Tốc độ tối đa mặc định ở Massachusetts trong khu dân cư đông đúc hoặc khu thương mại là 30 mph, mặc dù một số thành phố và thị trấn giảm xuống 25 mph trên đường địa phương.","p":"Đúng. Mức mặc định trong khu dân cư đông đúc là 30 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang sinasabi ng sign, ano ang speed limit sa thickly settled (masikip sa bahay) o business district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"May mga bayan na pumipili ng mas mababang limit, pero medyo mas mataas ang default ng estado.","h2":"Ang default na limit sa Massachusetts sa thickly settled o business district ay 30 mph, bagaman may mga lungsod at bayan na ibinababa ito sa 25 mph sa mga lokal na kalsada.","p":"Tama. Ang default sa thickly settled na lugar ay 30 mph."},"ar":{"q":"في Massachusetts، إذا لم تقل لافتة غير ذلك، ما الحد الأقصى للسرعة في منطقة سكنية مكتظة (thickly settled) أو منطقة تجارية؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"بعض البلدات تختار حدًا أقل، لكن الحد العام للولاية أعلى قليلًا.","h2":"الحد العام للسرعة في Massachusetts في منطقة سكنية مكتظة أو منطقة تجارية هو 30 mph، مع أن بعض المدن والبلدات تخفّضه إلى 25 mph على الطرق المحلية.","p":"صحيح. الحد العام في المناطق السكنية المكتظة هو 30 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-021","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, unless a sign says otherwise, what is the speed limit in a school zone?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"It is lower than the limit in a thickly settled district.","h2":"In Massachusetts the speed limit in a school zone is 20 mph, so slow down and watch for children.","p":"Right. School zones are 20 mph."},"es":{"q":"En Massachusetts, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una zona escolar?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Es más bajo que el límite de una zona densamente poblada.","h2":"En Massachusetts el límite de velocidad en una zona escolar es de 20 mph, así que baje la velocidad y esté atento a los niños.","p":"Correcto. Las zonas escolares tienen 20 mph."},"zh":{"q":"在 Massachusetts，如果没有标志另外说明，学校区域的限速是多少？","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"比人口稠密区的限速低。","h2":"在 Massachusetts，学校区域的限速是 20 mph，所以要减速并注意小孩。","p":"对。学校区域是 20 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trong khu vực trường học là bao nhiêu?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Thấp hơn giới hạn trong khu dân cư đông đúc.","h2":"Ở Massachusetts, tốc độ tối đa trong khu vực trường học là 20 mph, vì vậy hãy chạy chậm lại và chú ý trẻ em.","p":"Đúng. Khu vực trường học là 20 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang sinasabi ng sign, ano ang speed limit sa school zone?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Mas mababa ito kaysa sa limit sa thickly settled district.","h2":"Sa Massachusetts, ang speed limit sa school zone ay 20 mph, kaya bagalan at bantayan ang mga bata.","p":"Tama. Ang school zone ay 20 mph."},"ar":{"q":"في Massachusetts، إذا لم تقل لافتة غير ذلك، ما الحد الأقصى للسرعة في منطقة المدرسة؟","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"هو أقل من الحد في المنطقة السكنية المكتظة.","h2":"في Massachusetts الحد الأقصى للسرعة في منطقة المدرسة هو 20 mph، لذلك خفّف سرعتك وانتبه للأطفال.","p":"صحيح. مناطق المدارس 20 mph."},"ref":{"doc":"MA","page":80}},{"id":"ma-022","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on a divided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"It is 10 mph more than on an undivided highway in the same kind of area.","h2":"The Massachusetts default limit on a divided highway outside a thickly settled or business district is 50 mph unless a sign shows a different limit.","p":"Right. Divided highways outside town centers default to 50 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera dividida fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Es 10 mph más que en una carretera sin división en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera dividida fuera de una zona densamente poblada o comercial es de 50 mph si no hay una señal con otro límite.","p":"Correcto. Las carreteras divididas fuera de los centros tienen 50 mph."},"zh":{"q":"在 Massachusetts，如果没有其他标示，人口稠密区或商业区以外的分隔公路限速是多少？","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"比同类地区没有分隔的公路高 10 mph。","h2":"在 Massachusetts，人口稠密区或商业区以外的分隔公路，默认限速是 50 mph，除非标志标示了不同的限速。","p":"对。城镇中心以外的分隔公路默认是 50 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trên xa lộ có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là bao nhiêu?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Cao hơn 10 mph so với xa lộ không có dải phân cách trong cùng loại khu vực.","h2":"Tốc độ tối đa mặc định ở Massachusetts trên xa lộ có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là 50 mph, trừ khi biển báo ghi giới hạn khác.","p":"Đúng. Xa lộ có dải phân cách bên ngoài trung tâm thị trấn mặc định là 50 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang nakapaskil, ano ang speed limit sa divided highway sa labas ng thickly settled o business district?","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"Mas mataas ito nang 10 mph kaysa sa undivided highway sa parehong uri ng lugar.","h2":"Ang default na limit sa Massachusetts sa divided highway sa labas ng thickly settled o business district ay 50 mph, maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. Ang divided highway sa labas ng sentro ng bayan ay default na 50 mph."},"ar":{"q":"في Massachusetts، إذا لم تُنشر لافتة غير ذلك، ما الحد الأقصى للسرعة على طريق سريع مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية؟","o":["40 mph","45 mph","50 mph","55 mph"],"h1":"هو أعلى بـ 10 mph من الطريق السريع غير المقسوم في نفس نوع المنطقة.","h2":"الحد العام للسرعة في Massachusetts على طريق سريع مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية هو 50 mph، إلا إذا أظهرت لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة المقسومة خارج وسط البلدات حدها العام 50 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-023","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, unless posted otherwise, what is the speed limit on an undivided highway outside a thickly settled or business district?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"It is 10 mph less than on a divided highway in the same kind of area.","h2":"The Massachusetts default limit on an undivided highway outside a thickly settled or business district is 40 mph, because there is nothing between you and oncoming traffic.","p":"Right. Undivided highways outside town centers default to 40 mph."},"es":{"q":"En Massachusetts, si no hay otra señal, ¿cuál es el límite de velocidad en una carretera sin división fuera de una zona densamente poblada o comercial?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Es 10 mph menos que en una carretera dividida en el mismo tipo de zona.","h2":"En Massachusetts el límite normal en una carretera sin división fuera de una zona densamente poblada o comercial es de 40 mph, porque no hay nada entre usted y el tráfico contrario.","p":"Correcto. Las carreteras sin división fuera de los centros tienen 40 mph."},"zh":{"q":"在 Massachusetts，如果没有其他标示，人口稠密区或商业区以外没有分隔的公路限速是多少？","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"比同类地区的分隔公路低 10 mph。","h2":"在 Massachusetts，人口稠密区或商业区以外没有分隔的公路，默认限速是 40 mph，因为你和对面来的车之间没有任何东西隔开。","p":"对。城镇中心以外没有分隔的公路默认是 40 mph。"},"vi":{"q":"Ở Massachusetts, nếu không có biển báo khác, tốc độ tối đa trên xa lộ không có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là bao nhiêu?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Thấp hơn 10 mph so với xa lộ có dải phân cách trong cùng loại khu vực.","h2":"Tốc độ tối đa mặc định ở Massachusetts trên xa lộ không có dải phân cách bên ngoài khu dân cư đông đúc hoặc khu thương mại là 40 mph, vì không có gì ngăn giữa bạn và xe chạy ngược chiều.","p":"Đúng. Xa lộ không có dải phân cách bên ngoài trung tâm thị trấn mặc định là 40 mph."},"tl":{"q":"Sa Massachusetts, maliban kung iba ang nakapaskil, ano ang speed limit sa undivided highway sa labas ng thickly settled o business district?","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"Mas mababa ito nang 10 mph kaysa sa divided highway sa parehong uri ng lugar.","h2":"Ang default na limit sa Massachusetts sa undivided highway sa labas ng thickly settled o business district ay 40 mph, dahil walang nakapagitan sa iyo at sa paparating na trapiko.","p":"Tama. Ang undivided highway sa labas ng sentro ng bayan ay default na 40 mph."},"ar":{"q":"في Massachusetts، إذا لم تُنشر لافتة غير ذلك، ما الحد الأقصى للسرعة على طريق سريع غير مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية؟","o":["40 mph","45 mph","50 mph","35 mph"],"h1":"هو أقل بـ 10 mph من الطريق السريع المقسوم في نفس نوع المنطقة.","h2":"الحد العام للسرعة في Massachusetts على طريق سريع غير مقسوم خارج منطقة سكنية مكتظة أو منطقة تجارية هو 40 mph، لأنه لا يوجد شيء بينك وبين السيارات القادمة من الاتجاه المعاكس.","p":"صحيح. الطرق السريعة غير المقسومة خارج وسط البلدات حدها العام 40 mph."},"ref":{"doc":"MA","page":79}},{"id":"ma-024","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, when you enter a rotary, who has the right-of-way?","o":["You, because you are entering","Vehicles already in the rotary","The larger vehicle","The vehicle on your left only if it honks"],"h1":"Think about who is already moving around the circle.","h2":"Massachusetts law says a driver entering a rotary must yield to vehicles already in the rotary, so traffic inside keeps moving safely.","p":"Right. Yield to vehicles already in the rotary."},"es":{"q":"En Massachusetts, al entrar a una rotonda (rotary), ¿quién tiene el derecho de paso?","o":["Usted, porque está entrando","Los vehículos que ya están en la rotonda","El vehículo más grande","El de su izquierda solo si toca la bocina"],"h1":"Piense en quién ya va dando la vuelta.","h2":"La ley de Massachusetts dice que quien entra a una rotonda debe ceder el paso a los vehículos que ya están dentro, para que el tráfico de adentro siga con seguridad.","p":"Correcto. Ceda el paso a los vehículos que ya están en la rotonda."},"zh":{"q":"在 Massachusetts，你进入环岛（rotary）时，谁有优先通行权？","o":["你，因为你正在进入","已经在环岛里的车辆","比较大的车辆","左边的车，但只有它按喇叭时"],"h1":"想一想谁已经在环岛里绕着走。","h2":"Massachusetts 法律规定，进入环岛的司机必须让已经在环岛里的车辆先走，这样里面的车可以安全地继续走。","p":"对。让已经在环岛里的车辆先走。"},"vi":{"q":"Ở Massachusetts, khi bạn chạy vào vòng xoay (rotary), ai được quyền ưu tiên?","o":["Bạn, vì bạn đang chạy vào","Các xe đã ở trong vòng xoay","Xe lớn hơn","Xe bên trái bạn, chỉ khi nó bấm còi"],"h1":"Hãy nghĩ xem ai đang chạy vòng quanh rồi.","h2":"Luật Massachusetts nói rằng người lái xe chạy vào vòng xoay phải nhường đường cho các xe đã ở trong vòng xoay, để xe bên trong tiếp tục chạy an toàn.","p":"Đúng. Nhường đường cho các xe đã ở trong vòng xoay."},"tl":{"q":"Sa Massachusetts, kapag pumapasok ka sa rotary, sino ang may right-of-way?","o":["Ikaw, dahil pumapasok ka","Ang mga sasakyang nasa loob na ng rotary","Ang mas malaking sasakyan","Ang sasakyan sa kaliwa mo, kung bumusina lang ito"],"h1":"Isipin kung sino na ang umiikot sa bilog.","h2":"Sinasabi ng batas ng Massachusetts na ang driver na pumapasok sa rotary ay dapat magbigay-daan sa mga sasakyang nasa loob na ng rotary, para ligtas na tuloy-tuloy ang trapiko sa loob.","p":"Tama. Magbigay-daan sa mga sasakyang nasa loob na ng rotary."},"ar":{"q":"في Massachusetts، عندما تدخل دوّارًا (rotary)، من له حق الأولوية؟","o":["أنت، لأنك تدخل","السيارات الموجودة داخل الدوّار","السيارة الأكبر","السيارة على يسارك، فقط إذا أطلقت البوق"],"h1":"فكّر في من يدور حول الدائرة بالفعل.","h2":"يقول قانون Massachusetts إن السائق الذي يدخل الدوّار يجب أن يعطي الأولوية للسيارات الموجودة داخل الدوّار، حتى تستمر حركة المرور في الداخل بأمان.","p":"صحيح. أعطِ الأولوية للسيارات الموجودة داخل الدوّار."},"ref":{"doc":"MA","page":101}},{"id":"ma-025","scope":"MA","cat":"signals","sign":null,"c":3,"en":{"q":"In Massachusetts, after a full stop at a red light, which turn is allowed if no sign forbids it and you yield?","o":["A left turn onto a two-way street","A U-turn","A left turn from any street","A right turn"],"h1":"Most states allow this same turn on red.","h2":"In Massachusetts you may turn right on a red light after stopping and yielding to people and traffic, unless a sign says no turn on red.","p":"Right. A right turn on red is allowed after a stop, unless a sign forbids it."},"es":{"q":"En Massachusetts, después de parar por completo en un semáforo en rojo, ¿qué giro se permite si ninguna señal lo prohíbe y usted cede el paso?","o":["Girar a la izquierda a una calle de doble sentido","Dar vuelta en U","Girar a la izquierda desde cualquier calle","Girar a la derecha"],"h1":"Casi todos los estados permiten este mismo giro en rojo.","h2":"En Massachusetts usted puede girar a la derecha con la luz roja después de parar y ceder el paso a las personas y al tráfico, a menos que una señal lo prohíba.","p":"Correcto. Se permite girar a la derecha en rojo después de parar, si no hay señal que lo prohíba."},"zh":{"q":"在 Massachusetts，在红灯前完全停下以后，如果没有标志禁止并且你让行，可以怎样转弯？","o":["左转进入双向街道","掉头","从任何街道左转","右转"],"h1":"大多数州都允许红灯时这样转弯。","h2":"在 Massachusetts，你在红灯前停车并让行人和车辆先走后，可以右转，除非有标志写着红灯不能转弯。","p":"对。停车后可以红灯右转，除非有标志禁止。"},"vi":{"q":"Ở Massachusetts, sau khi dừng hẳn ở đèn đỏ, bạn được rẽ hướng nào nếu không có biển báo cấm và bạn nhường đường?","o":["Rẽ trái vào đường hai chiều","Quay đầu xe (U-turn)","Rẽ trái từ bất kỳ đường nào","Rẽ phải"],"h1":"Hầu hết các tiểu bang cho phép rẽ hướng này khi đèn đỏ.","h2":"Ở Massachusetts, bạn được rẽ phải khi đèn đỏ sau khi dừng lại và nhường đường cho người đi bộ và xe cộ, trừ khi có biển báo cấm rẽ khi đèn đỏ.","p":"Đúng. Được rẽ phải khi đèn đỏ sau khi dừng lại, trừ khi có biển báo cấm."},"tl":{"q":"Sa Massachusetts, pagkatapos ng full stop sa red light, anong liko ang puwede kung walang sign na nagbabawal at nagbigay-daan ka?","o":["Kaliwang liko papunta sa two-way street","U-turn","Kaliwang liko mula sa kahit anong kalye","Kanang liko"],"h1":"Pinapayagan ng karamihan ng estado ang ganitong liko sa red.","h2":"Sa Massachusetts, puwede kang kumanan sa red light pagkatapos huminto at magbigay-daan sa mga tao at trapiko, maliban kung may sign na nagsasabing bawal lumiko sa red.","p":"Tama. Puwede ang kanang liko sa red pagkatapos huminto, maliban kung may sign na nagbabawal."},"ar":{"q":"في Massachusetts، بعد توقف كامل عند الإشارة الحمراء، أي انعطاف مسموح إذا لم تمنعه لافتة وأعطيت الأولوية؟","o":["انعطاف إلى اليسار نحو شارع باتجاهين","الدوران للخلف (U-turn)","انعطاف إلى اليسار من أي شارع","انعطاف إلى اليمين"],"h1":"معظم الولايات تسمح بنفس هذا الانعطاف عند الإشارة الحمراء.","h2":"في Massachusetts يمكنك الانعطاف إلى اليمين عند الإشارة الحمراء بعد التوقف وإعطاء الأولوية للمشاة والسيارات، إلا إذا قالت لافتة إن الانعطاف عند الإشارة الحمراء ممنوع.","p":"صحيح. الانعطاف إلى اليمين عند الإشارة الحمراء مسموح بعد التوقف، إلا إذا منعته لافتة."},"ref":{"doc":"MA","page":81}},{"id":"ma-026","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, when must your headlights be on?","o":["Only on highways","Only after 10 p.m.","Whenever your wipers are needed","Only in tunnels"],"h1":"Think about rain and snow.","h2":"Massachusetts law says your headlights must be on whenever you need your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Massachusetts, ¿cuándo debe tener las luces delanteras encendidas?","o":["Solo en las autopistas","Solo después de las 10 p.m.","Siempre que necesite los limpiaparabrisas","Solo en los túneles"],"h1":"Piense en la lluvia y la nieve.","h2":"La ley de Massachusetts dice que debe encender las luces delanteras siempre que necesite los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda las luces."},"zh":{"q":"在 Massachusetts，什么时候必须打开车头灯？","o":["只在高速公路上","只在晚上 10 点以后","每当需要用雨刷的时候","只在隧道里"],"h1":"想一想下雨和下雪。","h2":"Massachusetts 法律规定，每当你需要用挡风玻璃雨刷时，就必须打开车头灯，日间行车灯不算。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở Massachusetts, khi nào bạn phải bật đèn pha?","o":["Chỉ trên xa lộ","Chỉ sau 10 giờ tối","Bất cứ khi nào cần dùng cần gạt nước","Chỉ trong đường hầm"],"h1":"Hãy nghĩ đến mưa và tuyết.","h2":"Luật Massachusetts nói rằng bạn phải bật đèn pha bất cứ khi nào cần dùng cần gạt nước kính chắn gió, và đèn chạy ban ngày không được tính.","p":"Đúng. Bật cần gạt nước thì phải bật đèn pha."},"tl":{"q":"Sa Massachusetts, kailan dapat nakabukas ang iyong headlights?","o":["Sa highway lang","Pagkalipas lang ng 10 p.m.","Tuwing kailangan mo ang wipers","Sa tunnel lang"],"h1":"Isipin ang ulan at niyebe.","h2":"Sinasabi ng batas ng Massachusetts na dapat nakabukas ang headlights mo tuwing kailangan mo ang windshield wipers, at hindi binibilang ang daytime running lights.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Massachusetts، متى يجب أن تكون المصابيح الأمامية مضاءة؟","o":["على الطرق السريعة فقط","بعد 10 مساءً فقط","كلما احتجت إلى مسّاحات الزجاج","في الأنفاق فقط"],"h1":"فكّر في المطر والثلج.","h2":"يقول قانون Massachusetts إن المصابيح الأمامية يجب أن تكون مضاءة كلما احتجت إلى مسّاحات الزجاج الأمامي، وأضواء النهار لا تُحسب.","p":"صحيح. المسّاحات تعمل يعني المصابيح الأمامية مضاءة."},"ref":{"doc":"MA","page":45}},{"id":"ma-027","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, when may you drive past a school bus that is stopped with red lights flashing?","o":["When you are going the opposite way on a highway divided by a barrier","When you are going the opposite way on any two-lane road","When no children can be seen","When you honk first"],"h1":"There is only one exception, and it needs something between you and the bus.","h2":"In Massachusetts drivers from both directions must stop for a school bus with flashing red lights, and the only exception is opposite traffic on a highway divided by a physical barrier.","p":"Right. Only a divided highway with a barrier lets opposite traffic continue."},"es":{"q":"En Massachusetts, ¿cuándo puede pasar junto a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando va en sentido contrario en una carretera dividida por una barrera","Cuando va en sentido contrario en cualquier camino de dos carriles","Cuando no se ve a ningún niño","Cuando toca la bocina antes"],"h1":"Hay una sola excepción, y necesita algo entre usted y el autobús.","h2":"En Massachusetts los conductores de ambas direcciones deben parar ante un autobús escolar con luces rojas intermitentes, y la única excepción es el tráfico contrario en una carretera dividida por una barrera física.","p":"Correcto. Solo en una carretera dividida por una barrera sigue el tráfico contrario."},"zh":{"q":"在 Massachusetts，什么时候你可以开过一辆闪着红灯停着的校车？","o":["当你在有隔离墩的分隔公路上往相反方向开时","当你在任何双车道道路上往相反方向开时","当看不到小孩时","当你先按了喇叭时"],"h1":"只有一个例外，而且你和校车之间要有东西隔开。","h2":"在 Massachusetts，两个方向的司机都必须为闪着红灯的校车停车，唯一的例外是在有实体隔离墩的分隔公路上往相反方向开的车。","p":"对。只有在有隔离墩的分隔公路上，对面的车才可以继续开。"},"vi":{"q":"Ở Massachusetts, khi nào bạn được chạy qua một xe buýt trường học đang dừng với đèn đỏ nhấp nháy?","o":["Khi bạn chạy ngược chiều trên xa lộ có rào chắn ngăn cách","Khi bạn chạy ngược chiều trên bất kỳ đường hai làn nào","Khi không thấy trẻ em nào","Khi bạn bấm còi trước"],"h1":"Chỉ có một trường hợp ngoại lệ, và cần có thứ gì đó ngăn giữa bạn và xe buýt.","h2":"Ở Massachusetts, xe từ cả hai hướng phải dừng lại khi xe buýt trường học có đèn đỏ nhấp nháy, và ngoại lệ duy nhất là xe chạy ngược chiều trên xa lộ có rào chắn ngăn cách.","p":"Đúng. Chỉ xa lộ có rào chắn ngăn cách mới cho xe ngược chiều tiếp tục chạy."},"tl":{"q":"Sa Massachusetts, kailan ka puwedeng dumaan sa school bus na nakahinto na may kumikislap na pulang ilaw?","o":["Kapag pasalungat ka sa highway na hinahati ng barrier","Kapag pasalungat ka sa kahit anong two-lane na kalsada","Kapag walang batang nakikita","Kapag bumusina ka muna"],"h1":"Iisa lang ang exception, at kailangan nito ng nakapagitan sa iyo at sa bus.","h2":"Sa Massachusetts, dapat huminto ang mga driver mula sa dalawang direksyon para sa school bus na may kumikislap na pulang ilaw, at ang tanging exception ay ang pasalungat na trapiko sa highway na hinahati ng pisikal na barrier.","p":"Tama. Ang divided highway lang na may barrier ang nagpapatuloy sa pasalungat na trapiko."},"ar":{"q":"في Massachusetts، متى يجوز لك أن تمر بجانب حافلة مدرسية متوقفة وأضواؤها الحمراء تومض؟","o":["عندما تسير في الاتجاه المعاكس على طريق سريع يفصله حاجز","عندما تسير في الاتجاه المعاكس على أي طريق بمسارين","عندما لا ترى أي أطفال","عندما تطلق البوق أولًا"],"h1":"يوجد استثناء واحد فقط، ويحتاج إلى شيء يفصل بينك وبين الحافلة.","h2":"في Massachusetts يجب على السائقين من الاتجاهين التوقف أمام حافلة مدرسية أضواؤها الحمراء تومض، والاستثناء الوحيد هو السيارات في الاتجاه المعاكس على طريق سريع يفصله حاجز مادي.","p":"صحيح. فقط الطريق السريع الذي يفصله حاجز يسمح للسيارات في الاتجاه المعاكس بالاستمرار."},"ref":{"doc":"MA","page":105}},{"id":"ma-028","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, how close may you drive behind a school bus?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 200 feet","No closer than 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"Massachusetts law says you may not drive within 100 feet behind a school bus, so you have room to stop when it stops for children.","p":"Right. Stay at least 100 feet behind a school bus."},"es":{"q":"En Massachusetts, ¿qué tan cerca puede manejar detrás de un autobús escolar?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 200 pies","No más cerca de 100 pies"],"h1":"Es más o menos el largo de seis o siete carros.","h2":"La ley de Massachusetts dice que usted no puede manejar a menos de 100 pies detrás de un autobús escolar, para tener espacio para parar cuando se detenga por los niños.","p":"Correcto. Manténgase por lo menos a 100 pies detrás de un autobús escolar."},"zh":{"q":"在 Massachusetts，你在校车后面开车，最近可以离多近？","o":["不能少于 25 英尺","不能少于 50 英尺","不能少于 200 英尺","不能少于 100 英尺"],"h1":"大约是六、七辆车的长度。","h2":"Massachusetts 法律规定，你不能在校车后面 100 英尺以内开车，这样校车为小孩停车时，你有空间停下来。","p":"对。在校车后面至少保持 100 英尺。"},"vi":{"q":"Ở Massachusetts, bạn được chạy gần phía sau xe buýt trường học đến mức nào?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 200 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe hơi.","h2":"Luật Massachusetts nói rằng bạn không được chạy trong vòng 100 feet phía sau xe buýt trường học, để bạn có đủ chỗ dừng lại khi xe buýt dừng đón trả trẻ em.","p":"Đúng. Giữ khoảng cách ít nhất 100 feet phía sau xe buýt trường học."},"tl":{"q":"Sa Massachusetts, gaano kalapit ka puwedeng magmaneho sa likod ng school bus?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 200 feet","Hindi lalapit sa 100 feet"],"h1":"Mga kasinghaba ito ng anim o pitong kotse.","h2":"Sinasabi ng batas ng Massachusetts na hindi ka puwedeng magmaneho sa loob ng 100 feet sa likod ng school bus, para may lugar kang huminto kapag huminto ito para sa mga bata.","p":"Tama. Manatili nang hindi bababa sa 100 feet sa likod ng school bus."},"ar":{"q":"في Massachusetts، إلى أي مدى يجوز لك أن تقترب أثناء القيادة خلف حافلة مدرسية؟","o":["ليس أقرب من 25 قدمًا (feet)","ليس أقرب من 50 قدمًا (feet)","ليس أقرب من 200 قدم (feet)","ليس أقرب من 100 قدم (feet)"],"h1":"المسافة تقارب طول ست أو سبع سيارات.","h2":"يقول قانون Massachusetts إنه لا يجوز لك أن تقود على مسافة أقل من 100 قدم (feet) خلف حافلة مدرسية، حتى يكون لديك مكان للتوقف عندما تتوقف للأطفال.","p":"صحيح. ابقَ على بعد 100 قدم (feet) على الأقل خلف الحافلة المدرسية."},"ref":{"doc":"MA","page":null}},{"id":"ma-029","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, what does the Move Over law ask you to do near a stopped emergency vehicle with flashing lights?","o":["Stop in your lane until it leaves","Move to a lane not next to it, or slow down","Flash your lights and keep your speed","Drive on the shoulder past it"],"h1":"You give the vehicle more room, or less speed.","h2":"The Massachusetts Move Over law asks you to change to a lane that is not next to a stopped emergency, maintenance, or tow vehicle, or to slow down if you cannot change lanes safely.","p":"Right. Move over a lane, or slow down if you cannot."},"es":{"q":"En Massachusetts, ¿qué le pide la ley Move Over cerca de un vehículo de emergencia detenido con luces intermitentes?","o":["Parar en su carril hasta que se vaya","Pasar a un carril que no esté al lado, o bajar la velocidad","Hacer cambio de luces y seguir igual","Pasar por el acotamiento"],"h1":"Usted le da más espacio al vehículo, o pasa más despacio.","h2":"La ley Move Over de Massachusetts le pide pasar a un carril que no esté junto a un vehículo de emergencia, de mantenimiento o grúa detenido, o bajar la velocidad si no puede cambiarse de carril con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Massachusetts，在闪着灯停着的急救车辆附近，Move Over 法要你做什么？","o":["在你的车道停下，直到它离开","换到不紧挨着它的车道，或者减速","闪车灯并保持速度","从路肩开过去"],"h1":"你给这辆车更多空间，或者开得更慢。","h2":"Massachusetts 的 Move Over 法要求你换到不紧挨着停着的急救车、维修车或拖车的车道，如果不能安全换道，就要减速。","p":"对。换一条车道让开，如果不能就减速。"},"vi":{"q":"Ở Massachusetts, luật Nhường Làn (Move Over law) yêu cầu bạn làm gì khi đến gần một xe khẩn cấp đang dừng với đèn nhấp nháy?","o":["Dừng lại trong làn của bạn cho đến khi xe đó rời đi","Chuyển sang làn không sát bên xe đó, hoặc chạy chậm lại","Nháy đèn và giữ nguyên tốc độ","Chạy trên lề đường để vượt qua xe đó"],"h1":"Bạn cho xe đó thêm khoảng trống, hoặc giảm tốc độ.","h2":"Luật Move Over của Massachusetts yêu cầu bạn chuyển sang làn không sát bên xe khẩn cấp, xe bảo trì hoặc xe kéo đang dừng, hoặc chạy chậm lại nếu bạn không thể đổi làn an toàn.","p":"Đúng. Chuyển sang một làn khác, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Massachusetts, ano ang ipinagagawa sa iyo ng Move Over law malapit sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Huminto sa lane mo hanggang umalis ito","Lumipat sa lane na hindi katabi nito, o bumagal","I-flash ang ilaw mo at panatilihin ang bilis","Magmaneho sa shoulder para lampasan ito"],"h1":"Binibigyan mo ang sasakyan ng mas maraming espasyo, o binabawasan mo ang bilis.","h2":"Ipinagagawa ng Move Over law ng Massachusetts na lumipat ka sa lane na hindi katabi ng nakahintong emergency, maintenance, o tow vehicle, o bumagal kung hindi ka ligtas na makalipat ng lane.","p":"Tama. Lumipat ng isang lane, o bumagal kung hindi puwede."},"ar":{"q":"في Massachusetts، ماذا يطلب منك قانون الابتعاد (Move Over law) قرب سيارة طوارئ متوقفة وأضواؤها تومض؟","o":["أن تتوقف في مسارك حتى تغادر","أن تنتقل إلى مسار غير مجاور لها، أو تخفّف سرعتك","أن تومض بأضوائك وتحافظ على سرعتك","أن تقود على كتف الطريق لتتجاوزها"],"h1":"تعطي السيارة مساحة أكبر، أو تخفّف سرعتك.","h2":"يطلب منك قانون Move Over في Massachusetts أن تنتقل إلى مسار غير مجاور لسيارة طوارئ أو صيانة أو سحب متوقفة، أو أن تخفّف سرعتك إذا لم تستطع تغيير المسار بأمان.","p":"صحيح. انتقل مسارًا واحدًا، أو خفّف سرعتك إذا لم تستطع."},"ref":{"doc":"MA","page":104}},{"id":"ma-030","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, which coverage is one of the required parts of every auto insurance policy?","o":["Collision coverage","Comprehensive coverage","Personal injury protection (PIP)","Rental car coverage"],"h1":"Massachusetts is a no-fault state for this coverage.","h2":"Personal injury protection (PIP) is required on every Massachusetts auto policy and pays certain injury costs no matter who caused the crash, while collision and comprehensive are optional.","p":"Right. PIP is required in Massachusetts."},"es":{"q":"En Massachusetts, ¿qué cobertura es una de las partes obligatorias de toda póliza de seguro de auto?","o":["Cobertura de choque (collision)","Cobertura amplia (comprehensive)","Protección por lesiones personales (PIP)","Cobertura de auto de alquiler"],"h1":"Massachusetts es un estado “sin culpa” para esta cobertura.","h2":"La protección por lesiones personales (PIP) es obligatoria en toda póliza de auto de Massachusetts y paga ciertos gastos por lesiones sin importar quién causó el choque, mientras que la de choque y la amplia son opcionales.","p":"Correcto. La PIP es obligatoria en Massachusetts."},"zh":{"q":"在 Massachusetts，哪种保险是每份汽车保险单必须有的部分之一？","o":["碰撞险（collision）","综合险（comprehensive）","人身伤害保障（PIP）","租车险"],"h1":"在这种保险上，Massachusetts 是不论过错（no-fault）的州。","h2":"在 Massachusetts，每份汽车保险单都必须有人身伤害保障（PIP），不管是谁造成车祸，它都会支付某些受伤费用；碰撞险和综合险则是可选的。","p":"对。在 Massachusetts，PIP 是必须有的。"},"vi":{"q":"Ở Massachusetts, loại bảo hiểm nào là một phần bắt buộc của mọi hợp đồng bảo hiểm xe?","o":["Bảo hiểm va chạm (collision)","Bảo hiểm toàn diện (comprehensive)","Bảo hiểm thương tích cá nhân (personal injury protection, PIP)","Bảo hiểm xe thuê"],"h1":"Massachusetts là tiểu bang không xét lỗi (no-fault) đối với loại bảo hiểm này.","h2":"Bảo hiểm thương tích cá nhân (PIP) là bắt buộc trong mọi hợp đồng bảo hiểm xe ở Massachusetts và trả một số chi phí thương tích bất kể ai gây ra tai nạn, còn bảo hiểm va chạm và toàn diện thì không bắt buộc.","p":"Đúng. PIP là bắt buộc ở Massachusetts."},"tl":{"q":"Sa Massachusetts, anong coverage ang isa sa mga kailangang bahagi ng bawat auto insurance policy?","o":["Collision coverage","Comprehensive coverage","Personal injury protection (PIP)","Rental car coverage"],"h1":"Ang Massachusetts ay no-fault state para sa coverage na ito.","h2":"Ang personal injury protection (PIP) ay kailangan sa bawat auto policy sa Massachusetts at nagbabayad ng ilang gastos sa pinsala kahit sino ang nagsanhi ng banggaan, habang optional ang collision at comprehensive.","p":"Tama. Kailangan ang PIP sa Massachusetts."},"ar":{"q":"في Massachusetts، أي تغطية هي جزء إلزامي من كل وثيقة تأمين سيارة؟","o":["تغطية الاصطدام (collision)","التغطية الشاملة (comprehensive)","تغطية الحماية من الإصابات الشخصية (personal injury protection, PIP)","تغطية السيارة المستأجرة"],"h1":"Massachusetts ولاية بدون تحديد خطأ (no-fault) لهذه التغطية.","h2":"تغطية الحماية من الإصابات الشخصية (PIP) إلزامية في كل وثيقة تأمين سيارة في Massachusetts، وتدفع بعض تكاليف الإصابات بغض النظر عمّن تسبّب في الحادث، أما تغطية الاصطدام والتغطية الشاملة فهي اختيارية.","p":"صحيح. PIP إلزامية في Massachusetts."},"ref":{"doc":"MA","page":null}},{"id":"ma-031","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fewest surchargeable events within 2 years that means you must take a Driver Retraining course?","o":["3 events","2 events","5 events","7 events"],"h1":"It is a small number, more than two.","h2":"In Massachusetts, 3 surchargeable events within 2 years, such as at-fault crashes or traffic violations, mean you must finish a Driver Retraining course within 90 days or lose your license.","p":"Right. Three surchargeable events in 2 years mean a retraining course, or a suspension."},"es":{"q":"En Massachusetts, ¿cuál es el menor número de incidentes con recargo en 2 años que lo obliga a tomar un curso de reentrenamiento para conductores?","o":["3 incidentes","2 incidentes","5 incidentes","7 incidentes"],"h1":"Es un número pequeño, mayor que dos.","h2":"En Massachusetts, 3 incidentes con recargo en 2 años, como choques con culpa o infracciones de tránsito, lo obligan a terminar un curso de reentrenamiento para conductores en 90 días o perderá su licencia.","p":"Correcto. Tres incidentes con recargo en 2 años significan un curso de reentrenamiento, o una suspensión."},"zh":{"q":"在 Massachusetts，2 年内最少有多少次会加收保费的事件（surchargeable events），你就必须上 Driver Retraining 课程？","o":["3 次","2 次","5 次","7 次"],"h1":"这是一个小数字，比两多。","h2":"在 Massachusetts，2 年内有 3 次会加收保费的事件，例如自己有责任的车祸或交通违规，你就必须在 90 天内完成 Driver Retraining 课程，否则会失去驾照。","p":"对。2 年内有三次加收保费的事件，就要上再培训课程，否则驾照会被暂停。"},"vi":{"q":"Ở Massachusetts, số lần vi phạm bị tính phụ phí (surchargeable events) ít nhất trong vòng 2 năm là bao nhiêu thì bạn phải học khóa Đào tạo lại người lái xe (Driver Retraining)?","o":["3 lần","2 lần","5 lần","7 lần"],"h1":"Đó là một số nhỏ, nhiều hơn hai.","h2":"Ở Massachusetts, 3 lần vi phạm bị tính phụ phí trong vòng 2 năm, như tai nạn do lỗi của bạn hoặc vi phạm luật giao thông, nghĩa là bạn phải học xong khóa Driver Retraining trong vòng 90 ngày, nếu không sẽ mất bằng lái.","p":"Đúng. Ba lần vi phạm bị tính phụ phí trong 2 năm nghĩa là phải học khóa đào tạo lại, nếu không sẽ bị treo bằng lái."},"tl":{"q":"Sa Massachusetts, ano ang pinakakaunting surchargeable events sa loob ng 2 taon na nangangahulugang dapat kang kumuha ng Driver Retraining course?","o":["3 events","2 events","5 events","7 events"],"h1":"Maliit na bilang ito, higit sa dalawa.","h2":"Sa Massachusetts, ang 3 surchargeable events sa loob ng 2 taon, gaya ng banggaang ikaw ang may sala o mga traffic violation, ay nangangahulugang dapat mong tapusin ang Driver Retraining course sa loob ng 90 araw o mawawala ang lisensya mo.","p":"Tama. Ang tatlong surchargeable events sa 2 taon ay nangangahulugang retraining course, o suspensyon."},"ar":{"q":"في Massachusetts، ما أقل عدد من المخالفات التي تستوجب رسومًا إضافية (surchargeable events) خلال سنتين يعني أنك يجب أن تأخذ دورة إعادة تدريب السائق (Driver Retraining)؟","o":["3 مخالفات","مخالفتان (2)","5 مخالفات","7 مخالفات"],"h1":"عدد صغير، أكثر من اثنين.","h2":"في Massachusetts، 3 مخالفات تستوجب رسومًا إضافية خلال سنتين، مثل حوادث تكون أنت المخطئ فيها أو مخالفات مرورية، تعني أنك يجب أن تُنهي دورة Driver Retraining خلال 90 يومًا وإلا تفقد رخصتك.","p":"صحيح. ثلاث مخالفات تستوجب رسومًا إضافية خلال سنتين تعني دورة إعادة تدريب، أو إيقاف الرخصة."},"ref":{"doc":"MA","page":59}},{"id":"ma-032","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the longest time a driver's license is valid before it must be renewed?","o":["Two years","Five years","Eight years","Ten years"],"h1":"It is more than a few years, but less than ten.","h2":"In Massachusetts, a driver's license is valid for up to five years and usually expires on your birthday.","p":"Right. A Massachusetts license lasts up to five years."},"es":{"q":"En Massachusetts, ¿cuánto tiempo como máximo es válida una licencia de conducir antes de renovarla?","o":["Dos años","Cinco años","Ocho años","Diez años"],"h1":"Son más de unos pocos años, pero menos de diez.","h2":"En Massachusetts, una licencia de conducir es válida hasta por cinco años y por lo general vence el día de su cumpleaños.","p":"Correcto. Una licencia de Massachusetts dura hasta cinco años."},"zh":{"q":"在 Massachusetts，驾照最长有效多久就必须更新？","o":["两年","五年","八年","十年"],"h1":"比几年长，但不到十年。","h2":"在 Massachusetts，驾照最长有效五年，通常在你的生日那天到期。","p":"对。Massachusetts 的驾照最长有效五年。"},"vi":{"q":"Ở Massachusetts, bằng lái xe có hiệu lực lâu nhất là bao lâu trước khi phải gia hạn?","o":["Hai năm","Năm năm","Tám năm","Mười năm"],"h1":"Lâu hơn vài năm, nhưng chưa tới mười năm.","h2":"Ở Massachusetts, bằng lái xe có hiệu lực tối đa năm năm và thường hết hạn vào ngày sinh nhật của bạn.","p":"Đúng. Bằng lái ở Massachusetts có hiệu lực tối đa năm năm."},"tl":{"q":"Sa Massachusetts, ano ang pinakamahabang panahon na valid ang driver's license bago ito kailangang i-renew?","o":["Dalawang taon","Limang taon","Walong taon","Sampung taon"],"h1":"Mas mahaba ito sa ilang taon, pero kulang sa sampu.","h2":"Sa Massachusetts, ang driver's license ay valid nang hanggang limang taon at kadalasang nag-e-expire sa iyong kaarawan.","p":"Tama. Ang lisensya sa Massachusetts ay tumatagal nang hanggang limang taon."},"ar":{"q":"في Massachusetts، ما أطول مدة تبقى فيها رخصة القيادة صالحة قبل أن يجب تجديدها؟","o":["سنتان","خمس سنوات","ثماني سنوات","عشر سنوات"],"h1":"أكثر من بضع سنوات، لكن أقل من عشر.","h2":"في Massachusetts تبقى رخصة القيادة صالحة حتى خمس سنوات، وتنتهي عادةً في يوم عيد ميلادك.","p":"صحيح. تبقى رخصة Massachusetts صالحة حتى خمس سنوات."},"ref":{"doc":"MA","page":7}},{"id":"ma-033","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what vision is needed in your better eye, with glasses if you wear them, for a full Class D license?","o":["20/100","20/70","20/60","20/40"],"h1":"It is the best of these four numbers.","h2":"In Massachusetts, a full Class D license needs at least 20/40 vision in your better eye, with glasses or contacts if you use them.","p":"Right. You need at least 20/40 in your better eye."},"es":{"q":"En Massachusetts, ¿qué visión necesita en su mejor ojo, con lentes si los usa, para una licencia Clase D completa?","o":["20/100","20/70","20/60","20/40"],"h1":"Es el mejor de estos cuatro números.","h2":"En Massachusetts, una licencia Clase D completa requiere al menos una visión de 20/40 en su mejor ojo, con lentes o lentes de contacto si los usa.","p":"Correcto. Necesita al menos 20/40 en su mejor ojo."},"zh":{"q":"在 Massachusetts，要拿正式 Class D 驾照，你较好的那只眼睛需要多好的视力（如果你戴眼镜，就戴着眼镜）？","o":["20/100","20/70","20/60","20/40"],"h1":"是这四个数字里最好的。","h2":"在 Massachusetts，正式 Class D 驾照要求你较好的那只眼睛视力至少 20/40，如果你戴眼镜或隐形眼镜，就戴着测。","p":"对。你较好的那只眼睛视力至少要 20/40。"},"vi":{"q":"Ở Massachusetts, để có bằng lái Class D đầy đủ, mắt tốt hơn của bạn cần thị lực bao nhiêu (đeo kính nếu bạn có đeo)?","o":["20/100","20/70","20/60","20/40"],"h1":"Đó là con số tốt nhất trong bốn con số này.","h2":"Ở Massachusetts, bằng lái Class D đầy đủ cần thị lực ít nhất 20/40 ở mắt tốt hơn của bạn, đeo kính hoặc kính áp tròng nếu bạn có dùng.","p":"Đúng. Mắt tốt hơn của bạn cần ít nhất 20/40."},"tl":{"q":"Sa Massachusetts, anong paningin ang kailangan sa mas malinaw mong mata, nakasalamin kung nagsasalamin ka, para sa buong Class D license?","o":["20/100","20/70","20/60","20/40"],"h1":"Ito ang pinakamahusay sa apat na numerong ito.","h2":"Sa Massachusetts, ang buong Class D license ay nangangailangan ng paningin na hindi bababa sa 20/40 sa mas malinaw mong mata, nakasalamin o naka-contact lens kung gumagamit ka nito.","p":"Tama. Kailangan mo ng hindi bababa sa 20/40 sa mas malinaw mong mata."},"ar":{"q":"في Massachusetts، ما قوة النظر المطلوبة في عينك الأقوى، مع النظارة إن كنت تلبسها، للحصول على رخصة Class D كاملة؟","o":["20/100","20/70","20/60","20/40"],"h1":"إنه أفضل رقم من هذه الأرقام الأربعة.","h2":"في Massachusetts تحتاج رخصة Class D الكاملة إلى نظر لا يقل عن 20/40 في عينك الأقوى، مع النظارة أو العدسات اللاصقة إن كنت تستعملها.","p":"صحيح. تحتاج إلى 20/40 على الأقل في عينك الأقوى."},"ref":{"doc":"MA","page":5}},{"id":"ma-034","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, if you fail the road test, how long must you wait before you can take it again?","o":["At least 14 days","At least 3 days","At least 90 days","At least 6 months"],"h1":"It is about two weeks.","h2":"In Massachusetts, if you fail the road test or miss your appointment, you must wait at least 14 days before you test again.","p":"Right. You wait at least 14 days to retake the road test."},"es":{"q":"En Massachusetts, si no aprueba el examen de manejo, ¿cuánto tiempo debe esperar para tomarlo otra vez?","o":["Al menos 14 días","Al menos 3 días","Al menos 90 días","Al menos 6 meses"],"h1":"Son unas dos semanas.","h2":"En Massachusetts, si no aprueba el examen de manejo o no se presenta a su cita, debe esperar al menos 14 días para volver a tomarlo.","p":"Correcto. Debe esperar al menos 14 días para repetir el examen de manejo."},"zh":{"q":"在 Massachusetts，如果路考没通过，你必须等多久才能再考？","o":["至少 14 天","至少 3 天","至少 90 天","至少 6 个月"],"h1":"大约两个星期。","h2":"在 Massachusetts，如果你路考没通过或错过了预约，你必须等至少 14 天才能再考。","p":"对。你要等至少 14 天才能重考路考。"},"vi":{"q":"Ở Massachusetts, nếu bạn thi trượt phần lái xe trên đường, bạn phải chờ bao lâu mới được thi lại?","o":["Ít nhất 14 ngày","Ít nhất 3 ngày","Ít nhất 90 ngày","Ít nhất 6 tháng"],"h1":"Khoảng hai tuần.","h2":"Ở Massachusetts, nếu bạn thi trượt phần lái xe trên đường hoặc lỡ buổi hẹn thi, bạn phải chờ ít nhất 14 ngày rồi mới được thi lại.","p":"Đúng. Bạn phải chờ ít nhất 14 ngày để thi lại phần lái xe."},"tl":{"q":"Sa Massachusetts, kapag bumagsak ka sa road test, gaano katagal ka dapat maghintay bago ka makapag-test ulit?","o":["Hindi bababa sa 14 na araw","Hindi bababa sa 3 araw","Hindi bababa sa 90 araw","Hindi bababa sa 6 na buwan"],"h1":"Mga dalawang linggo ito.","h2":"Sa Massachusetts, kapag bumagsak ka sa road test o hindi ka nakarating sa appointment mo, dapat kang maghintay nang hindi bababa sa 14 na araw bago ka mag-test ulit.","p":"Tama. Maghihintay ka nang hindi bababa sa 14 na araw para ulitin ang road test."},"ar":{"q":"في Massachusetts، إذا رسبت في اختبار القيادة على الطريق، كم يجب أن تنتظر قبل أن تؤديه مرة أخرى؟","o":["14 يومًا على الأقل","3 أيام على الأقل","90 يومًا على الأقل","6 أشهر على الأقل"],"h1":"حوالي أسبوعين.","h2":"في Massachusetts، إذا رسبت في اختبار القيادة على الطريق أو فاتك موعدك، يجب أن تنتظر 14 يومًا على الأقل قبل أن تؤدي الاختبار مرة أخرى.","p":"صحيح. تنتظر 14 يومًا على الأقل لإعادة اختبار القيادة على الطريق."},"ref":{"doc":"MA","page":20}},{"id":"ma-035","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the fine for a first offense of using a hand-held phone while driving?","o":["$25","$50","$100","$500"],"h1":"The fine goes up for a second and third offense. The first is the lowest of those.","h2":"In Massachusetts, a first offense for using a hand-held phone while driving is a $100 fine; it rises to $250 and then $500.","p":"Right. The first hand-held phone offense costs $100."},"es":{"q":"En Massachusetts, ¿cuál es la multa por una primera infracción de usar un teléfono en la mano mientras maneja?","o":["$25","$50","$100","$500"],"h1":"La multa sube en la segunda y la tercera infracción. La primera es la más baja de ellas.","h2":"En Massachusetts, la primera infracción por usar un teléfono en la mano mientras maneja tiene una multa de $100; luego sube a $250 y después a $500.","p":"Correcto. La primera infracción por usar el teléfono en la mano cuesta $100."},"zh":{"q":"在 Massachusetts，开车时手拿手机，第一次违规罚款多少？","o":["$25","$50","$100","$500"],"h1":"第二次和第三次违规罚得更多。第一次是其中最少的。","h2":"在 Massachusetts，开车时手拿手机第一次违规罚款 $100，之后会提高到 $250，然后是 $500。","p":"对。第一次手拿手机违规罚款 $100。"},"vi":{"q":"Ở Massachusetts, lần vi phạm đầu tiên vì cầm điện thoại trên tay khi lái xe bị phạt bao nhiêu?","o":["$25","$50","$100","$500"],"h1":"Tiền phạt tăng lên ở lần vi phạm thứ hai và thứ ba. Lần đầu là thấp nhất trong các lần đó.","h2":"Ở Massachusetts, lần vi phạm đầu tiên vì cầm điện thoại trên tay khi lái xe bị phạt $100; sau đó tăng lên $250 rồi $500.","p":"Đúng. Lần đầu cầm điện thoại khi lái xe bị phạt $100."},"tl":{"q":"Sa Massachusetts, magkano ang multa sa unang paglabag sa paggamit ng hawak na cellphone habang nagmamaneho?","o":["$25","$50","$100","$500"],"h1":"Tumataas ang multa sa ikalawa at ikatlong paglabag. Ang una ang pinakamababa sa mga iyon.","h2":"Sa Massachusetts, ang unang paglabag sa paggamit ng hawak na cellphone habang nagmamaneho ay may multang $100; tumataas ito sa $250 at pagkatapos ay $500.","p":"Tama. $100 ang multa sa unang paglabag sa hawak na cellphone."},"ar":{"q":"في Massachusetts، ما الغرامة على المخالفة الأولى لاستعمال الهاتف باليد أثناء القيادة؟","o":["$25","$50","$100","$500"],"h1":"ترتفع الغرامة في المخالفة الثانية والثالثة. الأولى هي الأقل بينها.","h2":"في Massachusetts، غرامة المخالفة الأولى لاستعمال الهاتف باليد أثناء القيادة هي $100، ثم ترتفع إلى $250 ثم إلى $500.","p":"صحيح. المخالفة الأولى لاستعمال الهاتف باليد غرامتها $100."},"ref":{"doc":"MA","page":40}},{"id":"ma-036","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the fine for a driver who is not wearing a seat belt?","o":["$10","$25","$150","$300"],"h1":"It is a small fine, less than $50.","h2":"In Massachusetts, a driver who is not wearing a seat belt can be fined $25, and the same fine applies to passengers 16 and older.","p":"Right. Not wearing a seat belt can cost $25."},"es":{"q":"En Massachusetts, ¿cuál es la multa para un conductor que no usa el cinturón de seguridad?","o":["$10","$25","$150","$300"],"h1":"Es una multa pequeña, menos de $50.","h2":"En Massachusetts, un conductor que no usa el cinturón de seguridad puede recibir una multa de $25, y la misma multa se aplica a los pasajeros de 16 años o más.","p":"Correcto. No usar el cinturón de seguridad puede costar $25."},"zh":{"q":"在 Massachusetts，司机不系安全带罚款多少？","o":["$10","$25","$150","$300"],"h1":"是一笔小罚款，不到 $50。","h2":"在 Massachusetts，司机不系安全带可能被罚 $25，16 岁及以上的乘客也是一样的罚款。","p":"对。不系安全带可能被罚 $25。"},"vi":{"q":"Ở Massachusetts, tài xế không thắt dây an toàn bị phạt bao nhiêu?","o":["$10","$25","$150","$300"],"h1":"Đó là tiền phạt nhỏ, dưới $50.","h2":"Ở Massachusetts, tài xế không thắt dây an toàn có thể bị phạt $25, và hành khách từ 16 tuổi trở lên cũng bị phạt như vậy.","p":"Đúng. Không thắt dây an toàn có thể bị phạt $25."},"tl":{"q":"Sa Massachusetts, magkano ang multa sa driver na hindi nakasuot ng seat belt?","o":["$10","$25","$150","$300"],"h1":"Maliit na multa ito, kulang sa $50.","h2":"Sa Massachusetts, ang driver na hindi nakasuot ng seat belt ay puwedeng multahan ng $25, at ganoon din ang multa sa mga pasaherong 16 taong gulang pataas.","p":"Tama. Puwedeng $25 ang multa kapag hindi nakasuot ng seat belt."},"ar":{"q":"في Massachusetts، ما الغرامة على السائق الذي لا يضع حزام الأمان؟","o":["$10","$25","$150","$300"],"h1":"غرامة صغيرة، أقل من $50.","h2":"في Massachusetts، يمكن تغريم السائق الذي لا يضع حزام الأمان $25، والغرامة نفسها تنطبق على الركاب في عمر 16 سنة فأكثر.","p":"صحيح. عدم وضع حزام الأمان قد يكلّفك $25."},"ref":{"doc":"MA","page":35}},{"id":"ma-037","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, a child must ride in an approved child safety seat until which point?","o":["Age 8 or 57 inches tall","Age 4 or 40 inches tall","Age 6 or 48 inches tall","Age 12 or 60 inches tall"],"h1":"Think of a child in the second or third grade, a little under five feet tall.","h2":"In Massachusetts, a child must ride in an approved child safety seat until the child is at least 8 years old or at least 57 inches tall.","p":"Right. A child seat is needed until age 8 or 57 inches."},"es":{"q":"En Massachusetts, ¿hasta cuándo debe viajar un niño en un asiento de seguridad infantil aprobado?","o":["Hasta los 8 años o 57 pulgadas de estatura","Hasta los 4 años o 40 pulgadas de estatura","Hasta los 6 años o 48 pulgadas de estatura","Hasta los 12 años o 60 pulgadas de estatura"],"h1":"Piense en un niño de segundo o tercer grado, de un poco menos de cinco pies de estatura.","h2":"En Massachusetts, un niño debe viajar en un asiento de seguridad infantil aprobado hasta que tenga al menos 8 años o mida al menos 57 pulgadas.","p":"Correcto. Se necesita un asiento infantil hasta los 8 años o 57 pulgadas."},"zh":{"q":"在 Massachusetts，孩子必须坐在合格的儿童安全座椅里，直到什么时候？","o":["8 岁或身高 57 英寸","4 岁或身高 40 英寸","6 岁或身高 48 英寸","12 岁或身高 60 英寸"],"h1":"想想上二年级或三年级的孩子，身高比五英尺矮一点。","h2":"在 Massachusetts，孩子必须坐在合格的儿童安全座椅里，直到至少 8 岁或身高至少 57 英寸。","p":"对。到 8 岁或 57 英寸之前都需要儿童座椅。"},"vi":{"q":"Ở Massachusetts, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến khi nào?","o":["8 tuổi hoặc cao 57 inch","4 tuổi hoặc cao 40 inch","6 tuổi hoặc cao 48 inch","12 tuổi hoặc cao 60 inch"],"h1":"Hãy nghĩ đến một đứa trẻ học lớp hai hoặc lớp ba, cao gần năm feet.","h2":"Ở Massachusetts, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến khi ít nhất 8 tuổi hoặc cao ít nhất 57 inch.","p":"Đúng. Cần ghế trẻ em cho đến 8 tuổi hoặc 57 inch."},"tl":{"q":"Sa Massachusetts, hanggang kailan dapat nakasakay ang bata sa aprubadong child safety seat?","o":["Edad 8 o 57 inches ang taas","Edad 4 o 40 inches ang taas","Edad 6 o 48 inches ang taas","Edad 12 o 60 inches ang taas"],"h1":"Isipin ang batang nasa ikalawa o ikatlong grado, medyo mas maliit sa limang feet.","h2":"Sa Massachusetts, dapat nakasakay ang bata sa aprubadong child safety seat hanggang siya ay hindi bababa sa 8 taong gulang o hindi bababa sa 57 inches ang taas.","p":"Tama. Kailangan ng child seat hanggang edad 8 o 57 inches."},"ar":{"q":"في Massachusetts، حتى متى يجب أن يجلس الطفل في مقعد أمان معتمد للأطفال؟","o":["عمر 8 سنوات أو طول 57 بوصة (inches)","عمر 4 سنوات أو طول 40 بوصة (inches)","عمر 6 سنوات أو طول 48 بوصة (inches)","عمر 12 سنة أو طول 60 بوصة (inches)"],"h1":"فكّر في طفل في الصف الثاني أو الثالث، طوله أقل قليلًا من خمسة أقدام (feet).","h2":"في Massachusetts يجب أن يجلس الطفل في مقعد أمان معتمد للأطفال حتى يبلغ 8 سنوات على الأقل أو يصل طوله إلى 57 بوصة (inches) على الأقل.","p":"صحيح. يلزم مقعد الطفل حتى عمر 8 سنوات أو طول 57 بوصة."},"ref":{"doc":"MA","page":36}},{"id":"ma-038","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, when you pass a bicyclist, a pedestrian or a road worker, how much space must you leave?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 4 feet"],"h1":"It is the largest of these choices.","h2":"In Massachusetts, when you pass a vulnerable road user, such as a bicyclist, pedestrian or road worker, you must leave at least four feet of space.","p":"Right. Leave at least four feet when you pass."},"es":{"q":"En Massachusetts, cuando rebasa a un ciclista, un peatón o un trabajador de la vía, ¿cuánto espacio debe dejar?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 3 pies","Al menos 4 pies"],"h1":"Es la mayor de estas opciones.","h2":"En Massachusetts, cuando rebasa a un usuario vulnerable de la vía, como un ciclista, un peatón o un trabajador de la vía, debe dejar al menos cuatro pies de espacio.","p":"Correcto. Deje al menos cuatro pies al rebasar."},"zh":{"q":"在 Massachusetts，超过骑自行车的人、行人或道路工人时，你必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 4 英尺"],"h1":"是这些选项里最大的。","h2":"在 Massachusetts，超过骑自行车的人、行人或道路工人等容易受伤的道路使用者时，你必须留出至少四英尺的空间。","p":"对。超车时至少留出四英尺。"},"vi":{"q":"Ở Massachusetts, khi vượt qua người đi xe đạp, người đi bộ hoặc công nhân làm đường, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 4 feet"],"h1":"Đó là lựa chọn lớn nhất.","h2":"Ở Massachusetts, khi vượt qua người dễ bị tổn thương trên đường, như người đi xe đạp, người đi bộ hoặc công nhân làm đường, bạn phải chừa ít nhất bốn feet.","p":"Đúng. Chừa ít nhất bốn feet khi vượt."},"tl":{"q":"Sa Massachusetts, kapag lumalampas ka sa nagbibisikleta, naglalakad o road worker, gaano kalaking espasyo ang dapat mong iwan?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 3 feet","Hindi bababa sa 4 feet"],"h1":"Ito ang pinakamalaki sa mga pagpipilian.","h2":"Sa Massachusetts, kapag lumalampas ka sa vulnerable road user, gaya ng nagbibisikleta, naglalakad o road worker, dapat kang mag-iwan ng hindi bababa sa apat na feet na espasyo.","p":"Tama. Mag-iwan ng hindi bababa sa apat na feet kapag lumalampas."},"ar":{"q":"في Massachusetts، عندما تتجاوز راكب دراجة أو شخصًا يمشي أو عاملًا على الطريق، كم مسافة يجب أن تترك؟","o":["قدم واحدة (1 foot) على الأقل","قدمان (2 feet) على الأقل","3 أقدام (feet) على الأقل","4 أقدام (feet) على الأقل"],"h1":"إنها أكبر مسافة بين هذه الخيارات.","h2":"في Massachusetts، عندما تتجاوز مستخدمًا ضعيفًا للطريق، مثل راكب دراجة أو شخص يمشي أو عامل على الطريق، يجب أن تترك مسافة أربعة أقدام (feet) على الأقل.","p":"صحيح. اترك أربعة أقدام على الأقل عندما تتجاوز."},"ref":{"doc":"MA","page":49}},{"id":"ma-039","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, what happens to the fine if you are caught speeding in a posted work zone?","o":["It stays the same","It goes up by $10","It is doubled","It is cut in half"],"h1":"Work zones protect people on foot, so the penalty is much higher.","h2":"In Massachusetts, the speeding fine is doubled when you are caught speeding in a posted work zone.","p":"Right. Speeding fines are doubled in work zones."},"es":{"q":"En Massachusetts, ¿qué pasa con la multa si lo detienen por exceso de velocidad en una zona de obras señalizada?","o":["Sigue igual","Sube $10","Se duplica","Se reduce a la mitad"],"h1":"Las zonas de obras protegen a personas a pie, así que la sanción es mucho mayor.","h2":"En Massachusetts, la multa por exceso de velocidad se duplica cuando lo detienen en una zona de obras señalizada.","p":"Correcto. Las multas por velocidad se duplican en las zonas de obras."},"zh":{"q":"在 Massachusetts，如果你在标明的施工区超速被抓到，罚款会怎样？","o":["保持不变","增加 $10","加倍","减半"],"h1":"施工区保护步行的人，所以处罚重很多。","h2":"在 Massachusetts，在标明的施工区超速被抓到，超速罚款会加倍。","p":"对。在施工区超速罚款加倍。"},"vi":{"q":"Ở Massachusetts, tiền phạt sẽ thế nào nếu bạn bị bắt chạy quá tốc độ trong khu vực công trường có biển báo?","o":["Vẫn như cũ","Tăng thêm $10","Bị nhân đôi","Bị giảm một nửa"],"h1":"Khu vực công trường bảo vệ người đi bộ, nên hình phạt nặng hơn nhiều.","h2":"Ở Massachusetts, tiền phạt chạy quá tốc độ bị nhân đôi khi bạn bị bắt chạy quá tốc độ trong khu vực công trường có biển báo.","p":"Đúng. Tiền phạt chạy quá tốc độ bị nhân đôi trong khu vực công trường."},"tl":{"q":"Sa Massachusetts, ano ang nangyayari sa multa kapag nahuli kang nag-o-overspeed sa may-karatulang work zone?","o":["Pareho pa rin","Tumataas nang $10","Nadodoble","Nahahati sa kalahati"],"h1":"Pinoprotektahan ng work zone ang mga taong naglalakad, kaya mas mabigat ang parusa.","h2":"Sa Massachusetts, nadodoble ang multa sa overspeeding kapag nahuli kang nag-o-overspeed sa may-karatulang work zone.","p":"Tama. Nadodoble ang multa sa overspeeding sa work zone."},"ar":{"q":"في Massachusetts، ماذا يحدث للغرامة إذا ضُبطت مسرعًا في منطقة أعمال طرق عليها لافتة؟","o":["تبقى كما هي","تزيد $10","تتضاعف","تنقص إلى النصف"],"h1":"مناطق أعمال الطرق تحمي الناس الذين يمشون، لذلك العقوبة أكبر بكثير.","h2":"في Massachusetts تتضاعف غرامة السرعة عندما تُضبط مسرعًا في منطقة أعمال طرق عليها لافتة.","p":"صحيح. غرامات السرعة تتضاعف في مناطق أعمال الطرق."},"ref":{"doc":"MA","page":57}},{"id":"ma-040","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what happens if you are found guilty of three speeding violations within 12 months?","o":["Your license is suspended for 30 days","You get a written warning only","Your license is suspended for 5 years","You must retake the permit exam only"],"h1":"Your license is taken away for about a month.","h2":"In Massachusetts, three speeding violations within a 12-month period mean your license is automatically suspended for 30 days.","p":"Right. Three speeding violations in 12 months bring a 30-day suspension."},"es":{"q":"En Massachusetts, ¿qué pasa si lo declaran culpable de tres infracciones por exceso de velocidad en 12 meses?","o":["Le suspenden la licencia por 30 días","Solo recibe una advertencia escrita","Le suspenden la licencia por 5 años","Solo debe repetir el examen del permiso"],"h1":"Le quitan la licencia por más o menos un mes.","h2":"En Massachusetts, tres infracciones por exceso de velocidad en un período de 12 meses hacen que le suspendan la licencia automáticamente por 30 días.","p":"Correcto. Tres infracciones por velocidad en 12 meses traen una suspensión de 30 días."},"zh":{"q":"在 Massachusetts，如果你在 12 个月内有三次超速被判有罪，会怎样？","o":["你的驾照被暂停 30 天","你只会收到书面警告","你的驾照被暂停 5 年","你只需要重考学习驾照考试"],"h1":"你的驾照会被收走大约一个月。","h2":"在 Massachusetts，12 个月内有三次超速违规，你的驾照会自动被暂停 30 天。","p":"对。12 个月内三次超速会被暂停驾照 30 天。"},"vi":{"q":"Ở Massachusetts, điều gì xảy ra nếu bạn bị kết tội ba lần chạy quá tốc độ trong vòng 12 tháng?","o":["Bằng lái của bạn bị đình chỉ 30 ngày","Bạn chỉ bị cảnh cáo bằng văn bản","Bằng lái của bạn bị đình chỉ 5 năm","Bạn chỉ phải thi lại bài thi giấy phép tập lái"],"h1":"Bằng lái của bạn bị lấy đi khoảng một tháng.","h2":"Ở Massachusetts, ba lần vi phạm chạy quá tốc độ trong vòng 12 tháng nghĩa là bằng lái của bạn tự động bị đình chỉ 30 ngày.","p":"Đúng. Ba lần chạy quá tốc độ trong 12 tháng bị đình chỉ bằng lái 30 ngày."},"tl":{"q":"Sa Massachusetts, ano ang mangyayari kapag napatunayang nagkasala ka sa tatlong paglabag sa speeding sa loob ng 12 buwan?","o":["Masususpinde ang lisensya mo nang 30 araw","Nakasulat na babala lang ang matatanggap mo","Masususpinde ang lisensya mo nang 5 taon","Kailangan mo lang ulitin ang permit exam"],"h1":"Kukunin ang lisensya mo nang mga isang buwan.","h2":"Sa Massachusetts, ang tatlong paglabag sa speeding sa loob ng 12 buwan ay nangangahulugang awtomatikong masususpinde ang lisensya mo nang 30 araw.","p":"Tama. Ang tatlong paglabag sa speeding sa loob ng 12 buwan ay may 30 araw na suspensyon."},"ar":{"q":"في Massachusetts، ماذا يحدث إذا أُدنت بثلاث مخالفات سرعة خلال 12 شهرًا؟","o":["تُعلَّق رخصتك 30 يومًا","تحصل على إنذار مكتوب فقط","تُعلَّق رخصتك 5 سنوات","يجب أن تعيد امتحان التصريح فقط"],"h1":"تُسحب رخصتك لمدة شهر تقريبًا.","h2":"في Massachusetts، ثلاث مخالفات سرعة خلال 12 شهرًا تعني أن رخصتك تُعلَّق تلقائيًا لمدة 30 يومًا.","p":"صحيح. ثلاث مخالفات سرعة خلال 12 شهرًا تعني تعليق الرخصة 30 يومًا."},"ref":{"doc":"MA","page":57}},{"id":"ma-041","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is your license suspended if you have seven surchargeable events within three years?","o":["7 days","60 days","3 years","For life"],"h1":"It is about two months.","h2":"In Massachusetts, seven surchargeable events, such as at-fault crashes and moving violations, within three years mean an automatic 60-day license suspension.","p":"Right. Seven surchargeable events in three years bring a 60-day suspension."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo le suspenden la licencia si tiene siete incidentes con recargo en tres años?","o":["7 días","60 días","3 años","De por vida"],"h1":"Son unos dos meses.","h2":"En Massachusetts, siete incidentes con recargo, como choques con culpa e infracciones de tránsito, en tres años causan una suspensión automática de la licencia por 60 días.","p":"Correcto. Siete incidentes con recargo en tres años traen una suspensión de 60 días."},"zh":{"q":"在 Massachusetts，如果你在三年内有七次会加收保费的事件，驾照会被暂停多久？","o":["7 天","60 天","3 年","终身"],"h1":"大约两个月。","h2":"在 Massachusetts，三年内有七次会加收保费的事件，例如自己有责任的车祸和行车违规，你的驾照会自动被暂停 60 天。","p":"对。三年内七次会加收保费的事件会被暂停驾照 60 天。"},"vi":{"q":"Ở Massachusetts, bằng lái của bạn bị đình chỉ bao lâu nếu bạn có bảy lần vi phạm bị tính phụ phí trong vòng ba năm?","o":["7 ngày","60 ngày","3 năm","Suốt đời"],"h1":"Khoảng hai tháng.","h2":"Ở Massachusetts, bảy lần vi phạm bị tính phụ phí trong vòng ba năm, như tai nạn do lỗi của bạn và vi phạm khi đang lái xe, nghĩa là bằng lái tự động bị đình chỉ 60 ngày.","p":"Đúng. Bảy lần vi phạm bị tính phụ phí trong ba năm bị đình chỉ bằng lái 60 ngày."},"tl":{"q":"Sa Massachusetts, gaano katagal masususpinde ang lisensya mo kapag may pitong surchargeable events ka sa loob ng tatlong taon?","o":["7 araw","60 araw","3 taon","Habambuhay"],"h1":"Mga dalawang buwan ito.","h2":"Sa Massachusetts, ang pitong surchargeable events sa loob ng tatlong taon, gaya ng banggaang ikaw ang may sala at mga moving violation, ay nangangahulugang awtomatikong 60 araw na suspensyon ng lisensya.","p":"Tama. Ang pitong surchargeable events sa loob ng tatlong taon ay may 60 araw na suspensyon."},"ar":{"q":"في Massachusetts، كم مدة تعليق رخصتك إذا كانت لديك سبع مخالفات تستوجب رسومًا إضافية خلال ثلاث سنوات؟","o":["7 أيام","60 يومًا","3 سنوات","مدى الحياة"],"h1":"حوالي شهرين.","h2":"في Massachusetts، سبع مخالفات تستوجب رسومًا إضافية خلال ثلاث سنوات، مثل حوادث تكون أنت المخطئ فيها ومخالفات أثناء القيادة، تعني تعليق الرخصة تلقائيًا لمدة 60 يومًا.","p":"صحيح. سبع مخالفات تستوجب رسومًا إضافية خلال ثلاث سنوات تعني تعليق الرخصة 60 يومًا."},"ref":{"doc":"MA","page":62}},{"id":"ma-042","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how long is the license suspension for a first conviction of operating under the influence (OUI)?","o":["30 days","90 days","Five years","One year"],"h1":"It is longer than a few months, but much less than five years.","h2":"In Massachusetts, a first OUI conviction brings a one-year license suspension, although the court may allow an alcohol education program to shorten it.","p":"Right. A first OUI conviction means a one-year suspension."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión de la licencia por una primera condena por manejar bajo la influencia (OUI)?","o":["30 días","90 días","Cinco años","Un año"],"h1":"Es más de unos pocos meses, pero mucho menos de cinco años.","h2":"En Massachusetts, una primera condena por OUI trae una suspensión de la licencia por un año, aunque el tribunal puede permitir un programa de educación sobre el alcohol para acortarla.","p":"Correcto. Una primera condena por OUI significa una suspensión de un año."},"zh":{"q":"在 Massachusetts，第一次因酒后或药后驾驶（OUI）被定罪，驾照会被暂停多久？","o":["30 天","90 天","五年","一年"],"h1":"比几个月长，但比五年短很多。","h2":"在 Massachusetts，第一次 OUI 定罪会被暂停驾照一年，不过法院可能允许你参加酒精教育课程来缩短时间。","p":"对。第一次 OUI 定罪会被暂停驾照一年。"},"vi":{"q":"Ở Massachusetts, lần đầu bị kết tội lái xe khi say rượu hoặc dùng chất kích thích (OUI) thì bằng lái bị đình chỉ bao lâu?","o":["30 ngày","90 ngày","Năm năm","Một năm"],"h1":"Lâu hơn vài tháng, nhưng ngắn hơn nhiều so với năm năm.","h2":"Ở Massachusetts, lần đầu bị kết tội OUI thì bằng lái bị đình chỉ một năm, tuy tòa án có thể cho phép học một chương trình giáo dục về rượu để rút ngắn thời gian.","p":"Đúng. Lần đầu bị kết tội OUI thì bị đình chỉ một năm."},"tl":{"q":"Sa Massachusetts, gaano katagal ang suspensyon ng lisensya sa unang conviction sa pagmamaneho nang lasing o nasa impluwensya (OUI)?","o":["30 araw","90 araw","Limang taon","Isang taon"],"h1":"Mas mahaba ito sa ilang buwan, pero mas maikli nang husto sa limang taon.","h2":"Sa Massachusetts, ang unang OUI conviction ay may isang taong suspensyon ng lisensya, pero puwedeng payagan ng korte ang alcohol education program para paikliin ito.","p":"Tama. Ang unang OUI conviction ay may isang taong suspensyon."},"ar":{"q":"في Massachusetts، كم مدة تعليق الرخصة عند الإدانة الأولى بالقيادة تحت تأثير الكحول أو المخدرات (OUI)؟","o":["30 يومًا","90 يومًا","خمس سنوات","سنة واحدة"],"h1":"أطول من بضعة أشهر، لكن أقصر بكثير من خمس سنوات.","h2":"في Massachusetts، الإدانة الأولى بـ OUI تعني تعليق الرخصة سنة واحدة، مع أن المحكمة قد تسمح ببرنامج توعية عن الكحول لتقصير المدة.","p":"صحيح. الإدانة الأولى بـ OUI تعني تعليق الرخصة سنة واحدة."},"ref":{"doc":"MA","page":68}},{"id":"ma-043","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a driver over 21 with no earlier OUI offense refuses a breath or blood test. How long is the license suspended?","o":["7 days","30 days","180 days","10 years"],"h1":"It is about six months.","h2":"In Massachusetts, a driver over 21 with no prior OUI offense who refuses a chemical test loses the license for 180 days.","p":"Right. Refusing the test brings a 180-day suspension for a first-time adult driver."},"es":{"q":"En Massachusetts, un conductor mayor de 21 años sin infracciones previas de OUI se niega a una prueba de aliento o de sangre. ¿Por cuánto tiempo le suspenden la licencia?","o":["7 días","30 días","180 días","10 años"],"h1":"Son unos seis meses.","h2":"En Massachusetts, un conductor mayor de 21 años sin infracciones previas de OUI que se niega a una prueba química pierde la licencia por 180 días.","p":"Correcto. Negarse a la prueba trae una suspensión de 180 días para un adulto sin infracciones previas."},"zh":{"q":"在 Massachusetts，一个 21 岁以上、以前没有 OUI 违规的司机拒绝呼气或验血检测。驾照会被暂停多久？","o":["7 天","30 天","180 天","10 年"],"h1":"大约六个月。","h2":"在 Massachusetts，21 岁以上、以前没有 OUI 违规的司机如果拒绝化学检测，驾照会被暂停 180 天。","p":"对。第一次违规的成年司机拒绝检测会被暂停驾照 180 天。"},"vi":{"q":"Ở Massachusetts, một tài xế trên 21 tuổi chưa từng vi phạm OUI từ chối thử hơi thở hoặc thử máu. Bằng lái bị đình chỉ bao lâu?","o":["7 ngày","30 ngày","180 ngày","10 năm"],"h1":"Khoảng sáu tháng.","h2":"Ở Massachusetts, tài xế trên 21 tuổi chưa từng vi phạm OUI mà từ chối thử nghiệm hóa học thì bị mất bằng lái 180 ngày.","p":"Đúng. Tài xế người lớn vi phạm lần đầu từ chối thử nghiệm thì bị đình chỉ 180 ngày."},"tl":{"q":"Sa Massachusetts, isang driver na lampas 21 at walang naunang OUI offense ang tumanggi sa breath o blood test. Gaano katagal masususpinde ang lisensya?","o":["7 araw","30 araw","180 araw","10 taon"],"h1":"Mga anim na buwan ito.","h2":"Sa Massachusetts, ang driver na lampas 21 at walang naunang OUI offense na tumanggi sa chemical test ay mawawalan ng lisensya nang 180 araw.","p":"Tama. Ang pagtanggi sa test ay may 180 araw na suspensyon para sa adult driver na first-time."},"ar":{"q":"في Massachusetts، سائق عمره أكثر من 21 سنة وليس لديه مخالفة OUI سابقة يرفض فحص النفَس أو الدم. كم مدة تعليق رخصته؟","o":["7 أيام","30 يومًا","180 يومًا","10 سنوات"],"h1":"حوالي ستة أشهر.","h2":"في Massachusetts، السائق الذي عمره أكثر من 21 سنة وليس لديه مخالفة OUI سابقة ويرفض الفحص الكيميائي يفقد رخصته لمدة 180 يومًا.","p":"صحيح. رفض الفحص يعني تعليق الرخصة 180 يومًا للسائق البالغ في المرة الأولى."},"ref":{"doc":"MA","page":70}},{"id":"ma-044","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, after a crash with an injury or $1,000 or more in damage, how soon must you file a written crash report with the RMV?","o":["Within 5 days","Within 30 days","Within 60 days","Within 6 months"],"h1":"It is less than one week.","h2":"In Massachusetts, you must file a written crash report with the RMV within five days of a crash that hurt or killed someone or caused $1,000 or more in damage.","p":"Right. The crash report is due within five days."},"es":{"q":"En Massachusetts, después de un choque con heridos o con daños de $1,000 o más, ¿en qué plazo debe presentar un informe escrito del choque al RMV?","o":["En 5 días","En 30 días","En 60 días","En 6 meses"],"h1":"Es menos de una semana.","h2":"En Massachusetts, debe presentar un informe escrito al RMV en un plazo de cinco días después de un choque que hirió o mató a alguien o que causó daños de $1,000 o más.","p":"Correcto. El informe del choque se debe presentar en cinco días."},"zh":{"q":"在 Massachusetts，发生有人受伤或损失 $1,000 或以上的车祸后，你必须在多久内向 RMV 交书面车祸报告？","o":["5 天内","30 天内","60 天内","6 个月内"],"h1":"不到一个星期。","h2":"在 Massachusetts，如果车祸让人受伤或死亡，或造成 $1,000 或以上的损失，你必须在五天内向 RMV 交书面车祸报告。","p":"对。车祸报告必须在五天内交。"},"vi":{"q":"Ở Massachusetts, sau một tai nạn có người bị thương hoặc thiệt hại từ $1,000 trở lên, bạn phải nộp báo cáo tai nạn bằng văn bản cho RMV trong bao lâu?","o":["Trong vòng 5 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 6 tháng"],"h1":"Chưa tới một tuần.","h2":"Ở Massachusetts, bạn phải nộp báo cáo tai nạn bằng văn bản cho RMV trong vòng năm ngày sau một tai nạn làm người bị thương hoặc chết, hoặc gây thiệt hại từ $1,000 trở lên.","p":"Đúng. Phải nộp báo cáo tai nạn trong vòng năm ngày."},"tl":{"q":"Sa Massachusetts, pagkatapos ng banggaan na may nasaktan o $1,000 o higit pang pinsala, gaano kabilis mo dapat i-file ang nakasulat na crash report sa RMV?","o":["Sa loob ng 5 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 6 na buwan"],"h1":"Kulang ito sa isang linggo.","h2":"Sa Massachusetts, dapat mong i-file ang nakasulat na crash report sa RMV sa loob ng limang araw pagkatapos ng banggaan na may nasaktan o namatay o nagdulot ng $1,000 o higit pang pinsala.","p":"Tama. Dapat i-file ang crash report sa loob ng limang araw."},"ar":{"q":"في Massachusetts، بعد حادث فيه إصابة أو أضرار بقيمة $1,000 أو أكثر، خلال كم من الوقت يجب أن تقدّم تقريرًا مكتوبًا عن الحادث إلى RMV؟","o":["خلال 5 أيام","خلال 30 يومًا","خلال 60 يومًا","خلال 6 أشهر"],"h1":"أقل من أسبوع واحد.","h2":"في Massachusetts يجب أن تقدّم تقريرًا مكتوبًا عن الحادث إلى RMV خلال خمسة أيام من حادث أصاب شخصًا أو قتله أو سبّب أضرارًا بقيمة $1,000 أو أكثر.","p":"صحيح. يجب تقديم تقرير الحادث خلال خمسة أيام."},"ref":{"doc":"MA","page":131}},{"id":"ma-045","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, you must switch from high beams to low beams when an oncoming vehicle is within what distance?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"It is more than the length of a football field.","h2":"In Massachusetts, you must dim your high beams when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim your high beams within 500 feet of oncoming traffic."},"es":{"q":"En Massachusetts, ¿a qué distancia de un vehículo que viene de frente debe cambiar de luces altas a luces bajas?","o":["100 pies","500 pies","50 pies","2,000 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Massachusetts, debe bajar las luces altas cuando está a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces altas a 500 pies del tráfico que viene de frente."},"zh":{"q":"在 Massachusetts，对面来车在多少距离以内时，你必须从远光灯换成近光灯？","o":["100 英尺","500 英尺","50 英尺","2,000 英尺"],"h1":"比一个美式足球场还长。","h2":"在 Massachusetts，当你离对面来车 500 英尺以内时，你必须把远光灯调暗。","p":"对。离对面来车 500 英尺以内要调暗远光灯。"},"vi":{"q":"Ở Massachusetts, bạn phải chuyển từ đèn pha (đèn chiếu xa) sang đèn cốt (đèn chiếu gần) khi xe chạy ngược chiều ở trong khoảng cách nào?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"Dài hơn một sân bóng bầu dục Mỹ.","h2":"Ở Massachusetts, bạn phải giảm đèn pha khi bạn ở trong vòng 500 feet của xe chạy ngược chiều.","p":"Đúng. Giảm đèn pha trong vòng 500 feet khi có xe ngược chiều."},"tl":{"q":"Sa Massachusetts, dapat kang lumipat mula high beams papuntang low beams kapag ang paparating na sasakyan ay nasa loob ng anong layo?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"Mas mahaba ito sa haba ng isang football field.","h2":"Sa Massachusetts, dapat mong hinaan ang high beams mo kapag nasa loob ka ng 500 feet ng paparating na sasakyan.","p":"Tama. Hinaan ang high beams sa loob ng 500 feet ng paparating na trapiko."},"ar":{"q":"في Massachusetts، يجب أن تحوّل من الضوء العالي إلى الضوء المنخفض عندما تكون سيارة قادمة نحوك ضمن أي مسافة؟","o":["100 قدم (feet)","500 قدم (feet)","50 قدمًا (feet)","2,000 قدم (feet)"],"h1":"أطول من طول ملعب كرة قدم أمريكية.","h2":"في Massachusetts يجب أن تخفّض الضوء العالي عندما تكون على بُعد 500 قدم (feet) أو أقل من سيارة قادمة نحوك.","p":"صحيح. خفّض الضوء العالي ضمن 500 قدم من السيارات القادمة."},"ref":{"doc":"MA","page":46}},{"id":"ma-046","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, how close may you follow an emergency vehicle that is answering an alarm?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 150 feet","No closer than 300 feet"],"h1":"It is the farthest of these choices.","h2":"In Massachusetts, it is illegal to follow closer than 300 feet behind an emergency vehicle that is responding to an alarm.","p":"Right. Stay at least 300 feet behind an emergency vehicle on a call."},"es":{"q":"En Massachusetts, ¿qué tan cerca puede seguir a un vehículo de emergencia que responde a una alarma?","o":["No a menos de 50 pies","No a menos de 100 pies","No a menos de 150 pies","No a menos de 300 pies"],"h1":"Es la mayor de estas opciones.","h2":"En Massachusetts, es ilegal seguir a menos de 300 pies detrás de un vehículo de emergencia que responde a una alarma.","p":"Correcto. Manténgase al menos a 300 pies detrás de un vehículo de emergencia que atiende una llamada."},"zh":{"q":"在 Massachusetts，跟在正在出警的紧急车辆后面，你最近可以离多近？","o":["不能少于 50 英尺","不能少于 100 英尺","不能少于 150 英尺","不能少于 300 英尺"],"h1":"是这些选项里最远的。","h2":"在 Massachusetts，跟在正在出警的紧急车辆后面不到 300 英尺是违法的。","p":"对。跟在出警的紧急车辆后面至少 300 英尺。"},"vi":{"q":"Ở Massachusetts, bạn được chạy theo sau một xe cấp cứu đang đi làm nhiệm vụ ở khoảng cách gần nhất là bao nhiêu?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 150 feet","Không gần hơn 300 feet"],"h1":"Đó là lựa chọn xa nhất.","h2":"Ở Massachusetts, chạy theo sau gần hơn 300 feet một xe cấp cứu đang đi làm nhiệm vụ là phạm luật.","p":"Đúng. Giữ khoảng cách ít nhất 300 feet sau xe cấp cứu đang làm nhiệm vụ."},"tl":{"q":"Sa Massachusetts, gaano kalapit ka puwedeng sumunod sa emergency vehicle na rumeresponde sa alarma?","o":["Hindi lalapit sa 50 feet","Hindi lalapit sa 100 feet","Hindi lalapit sa 150 feet","Hindi lalapit sa 300 feet"],"h1":"Ito ang pinakamalayo sa mga pagpipilian.","h2":"Sa Massachusetts, bawal sumunod nang mas malapit sa 300 feet sa likod ng emergency vehicle na rumeresponde sa alarma.","p":"Tama. Manatili nang hindi bababa sa 300 feet sa likod ng emergency vehicle na may tawag."},"ar":{"q":"في Massachusetts، إلى أي حد يمكنك أن تقترب وأنت تسير خلف سيارة طوارئ تستجيب لنداء؟","o":["ليس أقرب من 50 قدمًا (feet)","ليس أقرب من 100 قدم (feet)","ليس أقرب من 150 قدمًا (feet)","ليس أقرب من 300 قدم (feet)"],"h1":"إنها أبعد مسافة بين هذه الخيارات.","h2":"في Massachusetts يُمنع قانونًا أن تسير على مسافة أقل من 300 قدم (feet) خلف سيارة طوارئ تستجيب لنداء.","p":"صحيح. ابقَ على بُعد 300 قدم على الأقل خلف سيارة الطوارئ في مهمة."},"ref":{"doc":"MA","page":120}},{"id":"ma-047","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, how close to an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is about the length of one large car.","h2":"In Massachusetts, you may not park within 20 feet of an intersection.","p":"Right. Park at least 20 feet from an intersection."},"es":{"q":"En Massachusetts, ¿qué tan cerca de una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 100 pies"],"h1":"Es más o menos el largo de un carro grande.","h2":"En Massachusetts, no puede estacionarse a menos de 20 pies de una intersección.","p":"Correcto. Estaciónese al menos a 20 pies de una intersección."},"zh":{"q":"在 Massachusetts，你可以在离路口多近的地方停车？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 20 英尺","不能少于 100 英尺"],"h1":"大约是一辆大车的长度。","h2":"在 Massachusetts，你不能在离路口 20 英尺以内停车。","p":"对。停车要离路口至少 20 英尺。"},"vi":{"q":"Ở Massachusetts, bạn được đậu xe gần ngã tư nhất là bao nhiêu?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe lớn.","h2":"Ở Massachusetts, bạn không được đậu xe trong vòng 20 feet của ngã tư.","p":"Đúng. Đậu xe cách ngã tư ít nhất 20 feet."},"tl":{"q":"Sa Massachusetts, gaano kalapit sa intersection ka puwedeng mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 100 feet"],"h1":"Mga haba ito ng isang malaking kotse.","h2":"Sa Massachusetts, hindi ka puwedeng mag-park sa loob ng 20 feet ng intersection.","p":"Tama. Mag-park nang hindi bababa sa 20 feet mula sa intersection."},"ar":{"q":"في Massachusetts، إلى أي حد يمكنك أن تركن سيارتك قريبًا من التقاطع؟","o":["ليس أقرب من 5 أقدام (feet)","ليس أقرب من 10 أقدام (feet)","ليس أقرب من 20 قدمًا (feet)","ليس أقرب من 100 قدم (feet)"],"h1":"حوالي طول سيارة كبيرة واحدة.","h2":"في Massachusetts لا يجوز لك أن تركن سيارتك على مسافة أقل من 20 قدمًا (feet) من التقاطع.","p":"صحيح. اركن على بُعد 20 قدمًا على الأقل من التقاطع."},"ref":{"doc":"MA","page":110}},{"id":"ma-048","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, when the lights flash at a railroad crossing, where must you stop?","o":["At least 15 feet before the gate or light post","Right on the first rail","At least 2 feet before the gate","Anywhere you can see the train"],"h1":"Stop well back from the gate, about one car length away.","h2":"In Massachusetts, when the lights flash at a railroad crossing, you must stop at least 15 feet before the gate or light post and stay stopped until the gate goes up and the lights stop.","p":"Right. Stop at least 15 feet before the gate or light post."},"es":{"q":"En Massachusetts, cuando las luces destellan en un cruce de ferrocarril, ¿dónde debe detenerse?","o":["Al menos a 15 pies antes de la barrera o del poste de luces","Justo sobre el primer riel","Al menos a 2 pies antes de la barrera","En cualquier lugar donde vea el tren"],"h1":"Deténgase bien atrás de la barrera, a más o menos el largo de un carro.","h2":"En Massachusetts, cuando las luces destellan en un cruce de ferrocarril, debe detenerse al menos a 15 pies antes de la barrera o del poste de luces y quedarse detenido hasta que la barrera suba y las luces se apaguen.","p":"Correcto. Deténgase al menos a 15 pies antes de la barrera o del poste de luces."},"zh":{"q":"在 Massachusetts，铁路道口的灯在闪时，你必须在哪里停车？","o":["在栏杆或灯柱前至少 15 英尺","就停在第一条铁轨上","在栏杆前至少 2 英尺","任何能看到火车的地方"],"h1":"停在离栏杆远一点的地方，大约一辆车的长度。","h2":"在 Massachusetts，铁路道口的灯在闪时，你必须在栏杆或灯柱前至少 15 英尺停车，一直等到栏杆升起、灯不再闪。","p":"对。在栏杆或灯柱前至少 15 英尺停车。"},"vi":{"q":"Ở Massachusetts, khi đèn nhấp nháy ở chỗ băng qua đường sắt, bạn phải dừng ở đâu?","o":["Cách thanh chắn hoặc cột đèn ít nhất 15 feet","Ngay trên đường ray đầu tiên","Cách thanh chắn ít nhất 2 feet","Bất cứ chỗ nào bạn thấy được xe lửa"],"h1":"Dừng cách xa thanh chắn, khoảng một chiều dài xe.","h2":"Ở Massachusetts, khi đèn nhấp nháy ở chỗ băng qua đường sắt, bạn phải dừng cách thanh chắn hoặc cột đèn ít nhất 15 feet và đứng yên cho đến khi thanh chắn nâng lên và đèn tắt.","p":"Đúng. Dừng cách thanh chắn hoặc cột đèn ít nhất 15 feet."},"tl":{"q":"Sa Massachusetts, kapag kumikislap ang mga ilaw sa railroad crossing, saan ka dapat huminto?","o":["Hindi bababa sa 15 feet bago ang gate o poste ng ilaw","Mismo sa unang riles","Hindi bababa sa 2 feet bago ang gate","Kahit saan na nakikita mo ang tren"],"h1":"Huminto nang malayo sa gate, mga isang haba ng kotse.","h2":"Sa Massachusetts, kapag kumikislap ang mga ilaw sa railroad crossing, dapat kang huminto nang hindi bababa sa 15 feet bago ang gate o poste ng ilaw at manatiling nakahinto hanggang tumaas ang gate at tumigil ang mga ilaw.","p":"Tama. Huminto nang hindi bababa sa 15 feet bago ang gate o poste ng ilaw."},"ar":{"q":"في Massachusetts، عندما تومض الأضواء عند معبر سكة الحديد، أين يجب أن تتوقف؟","o":["قبل الحاجز أو عمود الإشارة بـ 15 قدمًا (feet) على الأقل","فوق القضيب الأول مباشرة","قبل الحاجز بقدمين (2 feet) على الأقل","في أي مكان ترى منه القطار"],"h1":"توقّف بعيدًا عن الحاجز، بطول سيارة واحدة تقريبًا.","h2":"في Massachusetts، عندما تومض الأضواء عند معبر سكة الحديد، يجب أن تتوقف قبل الحاجز أو عمود الإشارة بـ 15 قدمًا (feet) على الأقل، وتبقى متوقفًا حتى يرتفع الحاجز وتتوقف الأضواء.","p":"صحيح. توقّف قبل الحاجز أو عمود الإشارة بـ 15 قدمًا على الأقل."},"ref":{"doc":"MA","page":87}},{"id":"ma-049","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, how long does state law let a stopped vehicle's engine idle?","o":["No more than 30 minutes","No more than 5 minutes","No more than 1 hour","As long as you want"],"h1":"It is only a few minutes.","h2":"In Massachusetts, state law does not allow a vehicle to idle for more than five minutes.","p":"Right. Idling is limited to five minutes."},"es":{"q":"En Massachusetts, ¿cuánto tiempo permite la ley estatal que el motor de un vehículo detenido quede encendido en marcha mínima?","o":["No más de 30 minutos","No más de 5 minutos","No más de 1 hora","Todo el tiempo que quiera"],"h1":"Son solo unos pocos minutos.","h2":"En Massachusetts, la ley estatal no permite dejar un vehículo encendido en marcha mínima por más de cinco minutos.","p":"Correcto. El motor encendido sin moverse se limita a cinco minutos."},"zh":{"q":"在 Massachusetts，州法律允许停着的车辆让引擎空转多久？","o":["不超过 30 分钟","不超过 5 分钟","不超过 1 小时","想多久都可以"],"h1":"只有几分钟。","h2":"在 Massachusetts，州法律不允许车辆空转超过五分钟。","p":"对。空转最多五分钟。"},"vi":{"q":"Ở Massachusetts, luật tiểu bang cho phép xe đang đậu để máy chạy không (nổ máy tại chỗ) bao lâu?","o":["Không quá 30 phút","Không quá 5 phút","Không quá 1 giờ","Bao lâu cũng được"],"h1":"Chỉ vài phút thôi.","h2":"Ở Massachusetts, luật tiểu bang không cho phép xe nổ máy tại chỗ quá năm phút.","p":"Đúng. Nổ máy tại chỗ chỉ được tối đa năm phút."},"tl":{"q":"Sa Massachusetts, gaano katagal pinapayagan ng batas ng estado na naka-idle ang makina ng nakahintong sasakyan?","o":["Hindi lalampas sa 30 minuto","Hindi lalampas sa 5 minuto","Hindi lalampas sa 1 oras","Kahit gaano katagal mo gusto"],"h1":"Ilang minuto lang ito.","h2":"Sa Massachusetts, hindi pinapayagan ng batas ng estado na naka-idle ang sasakyan nang higit sa limang minuto.","p":"Tama. Hanggang limang minuto lang ang idling."},"ar":{"q":"في Massachusetts، كم من الوقت يسمح قانون الولاية بأن يبقى محرك سيارة متوقفة يعمل وهي واقفة؟","o":["ليس أكثر من 30 دقيقة","ليس أكثر من 5 دقائق","ليس أكثر من ساعة واحدة (1)","المدة التي تريدها"],"h1":"بضع دقائق فقط.","h2":"في Massachusetts لا يسمح قانون الولاية بأن يبقى محرك السيارة يعمل وهي واقفة أكثر من خمس دقائق.","p":"صحيح. تشغيل المحرك والسيارة واقفة محدود بخمس دقائق."},"ref":{"doc":"MA","page":132}},{"id":"ma-050","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, to pass by crossing a broken yellow line, how far ahead must you be able to see clearly?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 400 feet"],"h1":"It is the longest of these distances.","h2":"In Massachusetts, you must be able to see clearly at least 400 feet ahead before you cross a broken yellow line to pass.","p":"Right. You need a clear view of at least 400 feet to pass."},"es":{"q":"En Massachusetts, para rebasar cruzando una línea amarilla discontinua, ¿hasta qué distancia adelante debe poder ver con claridad?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 200 pies","Al menos 400 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Massachusetts, debe poder ver con claridad al menos 400 pies adelante antes de cruzar una línea amarilla discontinua para rebasar.","p":"Correcto. Necesita ver con claridad al menos 400 pies para rebasar."},"zh":{"q":"在 Massachusetts，要越过黄色虚线超车，你必须能清楚看到前方多远？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 400 英尺"],"h1":"是这些距离里最长的。","h2":"在 Massachusetts，越过黄色虚线超车之前，你必须能清楚看到前方至少 400 英尺。","p":"对。超车时你需要清楚看到前方至少 400 英尺。"},"vi":{"q":"Ở Massachusetts, để vượt xe bằng cách băng qua vạch vàng đứt khúc, bạn phải nhìn rõ phía trước bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 400 feet"],"h1":"Đó là khoảng cách dài nhất trong các lựa chọn.","h2":"Ở Massachusetts, bạn phải nhìn rõ phía trước ít nhất 400 feet trước khi băng qua vạch vàng đứt khúc để vượt xe.","p":"Đúng. Bạn cần nhìn rõ ít nhất 400 feet để vượt xe."},"tl":{"q":"Sa Massachusetts, para lumampas sa pamamagitan ng pagtawid sa putol-putol na dilaw na linya, gaano kalayo sa unahan ang dapat mong makita nang malinaw?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 400 feet"],"h1":"Ito ang pinakamahabang layo sa mga ito.","h2":"Sa Massachusetts, dapat mong makita nang malinaw ang hindi bababa sa 400 feet sa unahan bago ka tumawid sa putol-putol na dilaw na linya para lumampas.","p":"Tama. Kailangan mo ng malinaw na tanaw na hindi bababa sa 400 feet para lumampas."},"ar":{"q":"في Massachusetts، لكي تتجاوز بعبور خط أصفر متقطع، إلى أي مسافة أمامك يجب أن ترى بوضوح؟","o":["50 قدمًا (feet) على الأقل","100 قدم (feet) على الأقل","200 قدم (feet) على الأقل","400 قدم (feet) على الأقل"],"h1":"إنها أطول مسافة بين هذه المسافات.","h2":"في Massachusetts يجب أن ترى بوضوح 400 قدم (feet) على الأقل أمامك قبل أن تعبر خطًا أصفر متقطعًا لتتجاوز.","p":"صحيح. تحتاج إلى رؤية واضحة لمسافة 400 قدم على الأقل لتتجاوز."},"ref":{"doc":"MA","page":103}},{"id":"ma-051","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what fine can you get for having an open alcoholic drink in your vehicle?","o":["$5 to $20","$25 to $50","$100 to $500","$10,000 or more"],"h1":"It starts at about one hundred dollars.","h2":"In Massachusetts, having an open alcoholic drink in your vehicle, even if someone else holds it, can bring a fine of $100 to $500.","p":"Right. An open container can cost $100 to $500."},"es":{"q":"En Massachusetts, ¿qué multa puede recibir por tener una bebida alcohólica abierta en su vehículo?","o":["De $5 a $20","De $25 a $50","De $100 a $500","$10,000 o más"],"h1":"Empieza en unos cien dólares.","h2":"En Massachusetts, tener una bebida alcohólica abierta en su vehículo, aunque la sostenga otra persona, puede traer una multa de $100 a $500.","p":"Correcto. Un envase abierto puede costar de $100 a $500."},"zh":{"q":"在 Massachusetts，车里有打开的酒类饮料，可能被罚多少？","o":["$5 到 $20","$25 到 $50","$100 到 $500","$10,000 或以上"],"h1":"大约从一百美元开始。","h2":"在 Massachusetts，车里有打开的酒类饮料，即使是别人拿着，也可能被罚 $100 到 $500。","p":"对。打开的酒类容器可能被罚 $100 到 $500。"},"vi":{"q":"Ở Massachusetts, bạn có thể bị phạt bao nhiêu nếu có đồ uống có cồn đã mở trong xe?","o":["$5 đến $20","$25 đến $50","$100 đến $500","$10,000 trở lên"],"h1":"Bắt đầu từ khoảng một trăm đô la.","h2":"Ở Massachusetts, có đồ uống có cồn đã mở trong xe, dù là người khác cầm, có thể bị phạt từ $100 đến $500.","p":"Đúng. Đồ uống có cồn đã mở có thể bị phạt $100 đến $500."},"tl":{"q":"Sa Massachusetts, anong multa ang puwede mong makuha kapag may bukas na inuming may alkohol sa sasakyan mo?","o":["$5 hanggang $20","$25 hanggang $50","$100 hanggang $500","$10,000 o higit pa"],"h1":"Nagsisimula ito sa mga isang daang dolyar.","h2":"Sa Massachusetts, ang pagkakaroon ng bukas na inuming may alkohol sa sasakyan mo, kahit ibang tao ang may hawak nito, ay puwedeng magdulot ng multang $100 hanggang $500.","p":"Tama. Puwedeng $100 hanggang $500 ang multa sa bukas na lalagyan ng alak."},"ar":{"q":"في Massachusetts، ما الغرامة التي قد تُفرض عليك إذا كان في سيارتك مشروب كحولي مفتوح؟","o":["من $5 إلى $20","من $25 إلى $50","من $100 إلى $500","$10,000 أو أكثر"],"h1":"تبدأ من حوالي مئة دولار.","h2":"في Massachusetts، وجود مشروب كحولي مفتوح في سيارتك، حتى لو كان شخص آخر يحمله، قد يؤدي إلى غرامة من $100 إلى $500.","p":"صحيح. الوعاء الكحولي المفتوح قد يكلّفك من $100 إلى $500."},"ref":{"doc":"MA","page":74}},{"id":"ma-052","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the youngest age at which a person may drive a motor vehicle on a public road?","o":["14 years old","16 years old","15 years old","17 years old"],"h1":"It is the same age at which you may first apply for a learner's permit.","h2":"In Massachusetts, nobody under 16 years old may drive a motor vehicle on a public road.","p":"Right! You must be at least 16 to drive on a public road."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima para manejar un vehículo motorizado en una vía pública?","o":["14 años","16 años","15 años","17 años"],"h1":"Es la misma edad en la que puedes pedir el permiso de aprendizaje.","h2":"En Massachusetts, nadie menor de 16 años puede manejar un vehículo motorizado en una vía pública.","p":"¡Correcto! Debes tener al menos 16 años para manejar en una vía pública."},"ref":{"doc":"MA","page":null}},{"id":"ma-053","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a permit holder drives alone, with no qualified adult beside them. What happens to the permit for a first offense?","o":["A written warning only","A $25 fine only","It is suspended for 60 days","It is suspended for 2 years"],"h1":"The state treats this as driving without a license, and the permit is taken away for a while.","h2":"In Massachusetts, a permit holder caught driving without a qualified supervisor has the permit suspended for 60 days for a first offense.","p":"Correct! A first offense means a 60-day permit suspension."},"es":{"q":"En Massachusetts, una persona con permiso maneja sola, sin un adulto calificado a su lado. ¿Qué pasa con el permiso en una primera infracción?","o":["Solo una advertencia por escrito","Solo una multa de $25","Se suspende por 60 días","Se suspende por 2 años"],"h1":"El estado lo trata como manejar sin licencia, y te quitan el permiso por un tiempo.","h2":"En Massachusetts, a quien maneja con permiso sin un supervisor calificado se le suspende el permiso por 60 días en una primera infracción.","p":"¡Correcto! Una primera infracción significa 60 días de suspensión del permiso."},"ref":{"doc":"MA","page":null}},{"id":"ma-054","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a learner's permit is valid for two years. How many road tests may the holder take in the first year?","o":["Two","Three","Unlimited","Six"],"h1":"The limit is the same for each of the two years.","h2":"In Massachusetts, a two-year learner's permit allows no more than six road tests in the first year and six in the second year.","p":"Yes! Up to six road tests in each year of the permit."},"es":{"q":"En Massachusetts, un permiso de aprendizaje vale por dos años. ¿Cuántos exámenes de manejo puede tomar la persona en el primer año?","o":["Dos","Tres","Sin límite","Seis"],"h1":"El límite es el mismo en cada uno de los dos años.","h2":"En Massachusetts, un permiso de dos años permite como máximo seis exámenes de manejo en el primer año y seis en el segundo.","p":"¡Sí! Hasta seis exámenes de manejo en cada año del permiso."},"ref":{"doc":"MA","page":null}},{"id":"ma-055","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what is true for a person riding with a motorcycle learner's permit?","o":["They may not carry any passenger","They may carry one adult passenger","They may carry a passenger in daylight","They may carry a passenger who has a license"],"h1":"Think about who else may be on the bike while you are still learning.","h2":"In Massachusetts, a motorcycle learner's permit does not allow you to carry any passenger.","p":"Correct! No passengers at all with a motorcycle permit."},"es":{"q":"En Massachusetts, ¿qué es cierto para una persona que maneja con permiso de aprendizaje de motocicleta?","o":["No puede llevar ningún pasajero","Puede llevar un pasajero adulto","Puede llevar un pasajero de día","Puede llevar un pasajero con licencia"],"h1":"Piensa en quién más puede ir en la moto mientras todavía aprendes.","h2":"En Massachusetts, el permiso de aprendizaje de motocicleta no permite llevar ningún pasajero.","p":"¡Correcto! Nada de pasajeros con permiso de motocicleta."},"ref":{"doc":"MA","page":null}},{"id":"ma-056","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, when may a person with a motorcycle learner's permit ride?","o":["Any time, day or night","Only between sunrise and sunset","Only on weekends","Only before 10 p.m."],"h1":"Darkness makes riding harder for new riders.","h2":"In Massachusetts, a motorcycle learner's permit does not allow riding after sunset or before sunrise.","p":"Right! Motorcycle permit holders ride only in daylight."},"es":{"q":"En Massachusetts, ¿cuándo puede manejar una persona con permiso de aprendizaje de motocicleta?","o":["A cualquier hora, de día o de noche","Solo entre la salida y la puesta del sol","Solo los fines de semana","Solo antes de las 10 p.m."],"h1":"La oscuridad hace más difícil manejar para quienes empiezan.","h2":"En Massachusetts, el permiso de aprendizaje de motocicleta no permite manejar después de la puesta del sol ni antes de la salida del sol.","p":"¡Correcto! Con permiso de motocicleta solo se maneja de día."},"ref":{"doc":"MA","page":null}},{"id":"ma-057","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a motorcycle permit holder fails the riding test twice. What must they do before the next test?","o":["Wait one full year","Pay a $500 fee","Complete an approved rider training course","Get a new learner's permit"],"h1":"The state wants more training, not just more waiting.","h2":"In Massachusetts, a motorcycle permit holder who fails the riding test twice must complete an approved rider training course before scheduling another test.","p":"Correct! Two failed tests means taking an approved rider training course."},"es":{"q":"En Massachusetts, una persona con permiso de motocicleta reprueba el examen de manejo dos veces. ¿Qué debe hacer antes del siguiente examen?","o":["Esperar un año completo","Pagar una tarifa de $500","Completar un curso aprobado de entrenamiento para motociclistas","Sacar un nuevo permiso de aprendizaje"],"h1":"El estado quiere más entrenamiento, no solo más espera.","h2":"En Massachusetts, quien tiene permiso de motocicleta y reprueba el examen dos veces debe completar un curso aprobado de entrenamiento antes de programar otro examen.","p":"¡Correcto! Dos exámenes reprobados significan tomar un curso aprobado para motociclistas."},"ref":{"doc":"MA","page":null}},{"id":"ma-058","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the youngest age to get a Junior Operator License?","o":["16 years old","17 years old","18 years old","16 and a half years old"],"h1":"It is six months after the earliest age for a learner's permit.","h2":"In Massachusetts, you must be at least 16 and a half years old to get a Junior Operator License.","p":"Yes! The Junior Operator License starts at 16 and a half."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima para obtener una Licencia de Conductor Joven (Junior Operator License)?","o":["16 años","17 años","18 años","16 años y medio"],"h1":"Son seis meses después de la edad mínima para el permiso de aprendizaje.","h2":"En Massachusetts, debes tener al menos 16 años y medio para obtener una Licencia de Conductor Joven.","p":"¡Sí! La Licencia de Conductor Joven empieza a los 16 años y medio."},"ref":{"doc":"MA","page":null}},{"id":"ma-059","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what kind of driving record must a teen keep during the six months with a learner's permit to get a Junior Operator License?","o":["No surchargeable incidents and no alcohol or drug convictions","No more than two speeding tickets","No more than one at-fault crash","Any record, as long as fines are paid"],"h1":"The record needs to stay clean the whole time.","h2":"In Massachusetts, a teen must hold the permit for six months with no surchargeable incidents and no alcohol or drug convictions before getting a Junior Operator License.","p":"Right! The permit months must be free of surchargeable incidents and alcohol or drug convictions."},"es":{"q":"En Massachusetts, ¿qué historial de manejo debe mantener un adolescente durante los seis meses con permiso para obtener la Licencia de Conductor Joven?","o":["Ningún incidente con recargo y ninguna condena por alcohol o drogas","No más de dos multas por velocidad","No más de un choque por su culpa","Cualquier historial, si paga las multas"],"h1":"El historial debe estar limpio todo el tiempo.","h2":"En Massachusetts, un adolescente debe tener el permiso seis meses sin incidentes con recargo y sin condenas por alcohol o drogas antes de obtener la Licencia de Conductor Joven.","p":"¡Correcto! Los meses con permiso deben estar libres de incidentes con recargo y de condenas por alcohol o drogas."},"ref":{"doc":"MA","page":null}},{"id":"ma-060","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts teen driver education, how many hours must a student spend watching another student drive?","o":["2 hours","6 hours","12 hours","10 hours"],"h1":"It is half the number of hours the student spends driving with the instructor.","h2":"In Massachusetts, teen driver education includes at least 6 hours of observing another student driver.","p":"Correct! Six hours of watching another student drive."},"es":{"q":"En la educación vial para adolescentes en Massachusetts, ¿cuántas horas debe pasar un estudiante observando a otro estudiante manejar?","o":["2 horas","6 horas","12 horas","10 horas"],"h1":"Es la mitad de las horas que el estudiante maneja con el instructor.","h2":"En Massachusetts, la educación vial para adolescentes incluye al menos 6 horas observando a otro estudiante manejar.","p":"¡Correcto! Seis horas observando a otro estudiante manejar."},"ref":{"doc":"MA","page":null}},{"id":"ma-061","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts teen driver education, how much on-road driving with an instructor may a student do in one day?","o":["Two sessions of 3 hours","As much as the school allows","One session of up to 2 hours","One session of up to 4 hours"],"h1":"The law keeps each lesson short and allows only one per day.","h2":"In Massachusetts, a driver education student may have only one on-road session per day, and no session may last more than 2 hours.","p":"Right! One session a day, no longer than 2 hours."},"es":{"q":"En la educación vial para adolescentes en Massachusetts, ¿cuánto puede manejar en la calle un estudiante con su instructor en un día?","o":["Dos sesiones de 3 horas","Lo que permita la escuela","Una sesión de hasta 2 horas","Una sesión de hasta 4 horas"],"h1":"La ley mantiene cada clase corta y permite solo una al día.","h2":"En Massachusetts, un estudiante de educación vial puede tener solo una sesión en la calle por día, y ninguna sesión puede durar más de 2 horas.","p":"¡Correcto! Una sesión al día, de no más de 2 horas."},"ref":{"doc":"MA","page":null}},{"id":"ma-062","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a parent already took the 2-hour driver education parent class for an older child. When may they skip it for a younger child?","o":["Never; it is required each time","If the class was within the past 10 years","If the parent has a clean record","If the class was within the past 5 years"],"h1":"The earlier class counts for a limited number of years.","h2":"In Massachusetts, a parent or guardian does not have to repeat the parent class if they took it within the past 5 years.","p":"Correct! The parent class counts for 5 years."},"es":{"q":"En Massachusetts, un padre ya tomó la clase de 2 horas para padres de la educación vial con un hijo mayor. ¿Cuándo puede no tomarla para un hijo menor?","o":["Nunca; se requiere cada vez","Si la tomó en los últimos 10 años","Si el padre tiene un historial limpio","Si la tomó en los últimos 5 años"],"h1":"La clase anterior cuenta por un número limitado de años.","h2":"En Massachusetts, el padre o tutor no tiene que repetir la clase para padres si la tomó en los últimos 5 años.","p":"¡Correcto! La clase para padres vale por 5 años."},"ref":{"doc":"MA","page":null}},{"id":"ma-063","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, who must sign the application for a Junior Operator License along with the teen?","o":["A parent or guardian","The driving school instructor","A police officer","The school principal"],"h1":"Think about who is responsible for a minor.","h2":"In Massachusetts, the Junior Operator License application must be signed by both the teen and a parent or guardian.","p":"Right! A parent or guardian signs too."},"es":{"q":"En Massachusetts, ¿quién debe firmar la solicitud de la Licencia de Conductor Joven junto con el adolescente?","o":["Un padre, madre o tutor","El instructor de la escuela de manejo","Un policía","El director de la escuela"],"h1":"Piensa en quién es responsable de un menor.","h2":"En Massachusetts, la solicitud de la Licencia de Conductor Joven debe estar firmada por el adolescente y por un padre, madre o tutor.","p":"¡Correcto! Un padre, madre o tutor también firma."},"ref":{"doc":"MA","page":null}},{"id":"ma-064","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, a Junior Operator breaks the passenger rule for the second time. How long is the license suspended?","o":["60 days","180 days","30 days","3 years"],"h1":"It is longer than the 60 days for a first offense, but less than a year.","h2":"In Massachusetts, a second violation of the Junior Operator passenger rule brings a 180-day license suspension.","p":"Correct! A second passenger violation means 180 days."},"es":{"q":"En Massachusetts, un Conductor Joven viola por segunda vez la regla de pasajeros. ¿Por cuánto tiempo se suspende la licencia?","o":["60 días","180 días","30 días","3 años"],"h1":"Es más que los 60 días de la primera vez, pero menos de un año.","h2":"En Massachusetts, una segunda violación de la regla de pasajeros del Conductor Joven trae una suspensión de 180 días.","p":"¡Correcto! Una segunda violación de pasajeros significa 180 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-065","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a Junior Operator's license is suspended during the first six months. What happens to the six-month passenger limit?","o":["It ends on the original date anyway","It is cancelled","The clock stops and resumes after the suspension","It is doubled to one year"],"h1":"Time without a license does not count toward the six months.","h2":"In Massachusetts, the passenger limit is paused during a suspension, so the six months continue only after the license is back.","p":"Right! The passenger-limit clock stops during a suspension."},"es":{"q":"En Massachusetts, la licencia de un Conductor Joven se suspende durante los primeros seis meses. ¿Qué pasa con el límite de pasajeros de seis meses?","o":["Termina en la fecha original de todos modos","Se cancela","El reloj se detiene y sigue después de la suspensión","Se duplica a un año"],"h1":"El tiempo sin licencia no cuenta para los seis meses.","h2":"En Massachusetts, el límite de pasajeros se pausa durante una suspensión, así que los seis meses siguen solo cuando recuperas la licencia.","p":"¡Correcto! El reloj del límite de pasajeros se detiene durante la suspensión."},"ref":{"doc":"MA","page":null}},{"id":"ma-066","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, during which part of the Junior Operator night limit will police stop a teen only if there is another violation?","o":["From 12:30 to 5 a.m., all of it","From 1 to 4 a.m.","From 11 p.m. to midnight","From 12:30 to 1 a.m. and 4 to 5 a.m."],"h1":"The first and last half hour or hour of the limit are treated differently.","h2":"In Massachusetts, between 12:30 and 1 a.m. and between 4 and 5 a.m., police enforce the Junior Operator night limit only when the teen is stopped for another violation.","p":"Correct! The edges of the night limit are enforced only with another violation."},"es":{"q":"En Massachusetts, ¿en qué parte del límite nocturno del Conductor Joven la policía solo detiene al adolescente si hay otra infracción?","o":["De 12:30 a 5 a.m., todo el horario","De 1 a 4 a.m.","De 11 p.m. a medianoche","De 12:30 a 1 a.m. y de 4 a 5 a.m."],"h1":"Los extremos del horario se tratan de forma distinta.","h2":"En Massachusetts, entre las 12:30 y la 1 a.m. y entre las 4 y las 5 a.m., la policía aplica el límite nocturno del Conductor Joven solo si detiene al adolescente por otra infracción.","p":"¡Correcto! Los extremos del horario nocturno solo se aplican junto con otra infracción."},"ref":{"doc":"MA","page":null}},{"id":"ma-067","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what must a Junior Operator have with them every time they drive?","o":["Their license","A parent's written note","Their birth certificate","A driving school certificate"],"h1":"It is the card that shows you may drive.","h2":"In Massachusetts, a Junior Operator must have the license with them at all times while driving.","p":"Right! Always carry your license."},"es":{"q":"En Massachusetts, ¿qué debe llevar consigo un Conductor Joven cada vez que maneja?","o":["Su licencia","Una nota escrita de un padre","Su acta de nacimiento","Un certificado de la escuela de manejo"],"h1":"Es la tarjeta que muestra que puedes manejar.","h2":"En Massachusetts, un Conductor Joven debe llevar su licencia en todo momento cuando maneja.","p":"¡Correcto! Lleva siempre tu licencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-068","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, which vehicle may a Junior Operator never drive?","o":["A pickup truck","A vehicle that needs a commercial driver's license","A car with a manual transmission","A rented car"],"h1":"Think of large trucks and buses that need a special license.","h2":"In Massachusetts, a Junior Operator may not drive any vehicle that requires a commercial driver's license (CDL).","p":"Correct! No CDL vehicles for Junior Operators."},"es":{"q":"En Massachusetts, ¿qué vehículo nunca puede manejar un Conductor Joven?","o":["Una camioneta pickup","Un vehículo que requiere licencia de conducir comercial","Un auto con transmisión manual","Un auto rentado"],"h1":"Piensa en camiones grandes y autobuses que piden una licencia especial.","h2":"En Massachusetts, un Conductor Joven no puede manejar ningún vehículo que requiera licencia de conducir comercial (CDL).","p":"¡Correcto! Nada de vehículos CDL para Conductores Jóvenes."},"ref":{"doc":"MA","page":null}},{"id":"ma-069","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what must a person under 18 complete to get a motorcycle license?","o":["Only a written motorcycle test","A one-year wait after the car license","An approved motorcycle basic rider course","A course at a high school"],"h1":"Teens need formal training for motorcycles too.","h2":"In Massachusetts, a person under 18 must meet the Junior Operator rules and complete an approved motorcycle basic rider course to get a motorcycle license.","p":"Right! Teens must finish an approved basic rider course."},"es":{"q":"En Massachusetts, ¿qué debe completar una persona menor de 18 años para obtener licencia de motocicleta?","o":["Solo un examen escrito de motocicleta","Esperar un año después de la licencia de auto","Un curso básico aprobado para motociclistas","Un curso en la escuela secundaria"],"h1":"Los adolescentes también necesitan entrenamiento formal para motocicletas.","h2":"En Massachusetts, una persona menor de 18 años debe cumplir las reglas del Conductor Joven y completar un curso básico aprobado para motociclistas para obtener licencia de motocicleta.","p":"¡Correcto! Los adolescentes deben terminar un curso básico aprobado para motociclistas."},"ref":{"doc":"MA","page":null}},{"id":"ma-070","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a Junior Operator is convicted of speeding for the second time. How long is the license suspended?","o":["30 days","90 days","180 days","One year"],"h1":"A first offense is 90 days. A repeat offense is much longer.","h2":"In Massachusetts, a Junior Operator's license is suspended for one year for a second or later speeding offense.","p":"Correct! A repeat speeding offense means a one-year suspension."},"es":{"q":"En Massachusetts, un Conductor Joven es condenado por exceso de velocidad por segunda vez. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","90 días","180 días","Un año"],"h1":"La primera vez son 90 días. Una segunda vez es mucho más.","h2":"En Massachusetts, la licencia de un Conductor Joven se suspende por un año por una segunda infracción de velocidad o posterior.","p":"¡Correcto! Una segunda infracción de velocidad significa un año de suspensión."},"ref":{"doc":"MA","page":null}},{"id":"ma-071","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what reinstatement fee does a Junior Operator pay after a speeding suspension?","o":["$500","$100","$50","$1,000"],"h1":"It is much higher than most license fees.","h2":"In Massachusetts, a Junior Operator pays a $500 reinstatement fee to get the license back after a speeding suspension.","p":"Right! The reinstatement fee is $500."},"es":{"q":"En Massachusetts, ¿qué tarifa de restablecimiento paga un Conductor Joven después de una suspensión por velocidad?","o":["$500","$100","$50","$1,000"],"h1":"Es mucho más alta que la mayoría de las tarifas de licencia.","h2":"En Massachusetts, un Conductor Joven paga $500 para recuperar la licencia después de una suspensión por exceso de velocidad.","p":"¡Correcto! La tarifa de restablecimiento es de $500."},"ref":{"doc":"MA","page":null}},{"id":"ma-072","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, which program must a Junior Operator complete after a speeding conviction?","o":["A first aid class","The State Courts Against Road Rage program","A defensive driving video","A community service day"],"h1":"Its name is about anger on the road.","h2":"In Massachusetts, a Junior Operator convicted of speeding must complete the State Courts Against Road Rage (SCARR) program.","p":"Correct! The State Courts Against Road Rage program is required."},"es":{"q":"En Massachusetts, ¿qué programa debe completar un Conductor Joven después de una condena por exceso de velocidad?","o":["Una clase de primeros auxilios","El programa State Courts Against Road Rage (contra la furia al volante)","Un video de manejo defensivo","Un día de servicio comunitario"],"h1":"Su nombre habla del enojo en la carretera.","h2":"En Massachusetts, un Conductor Joven condenado por exceso de velocidad debe completar el programa State Courts Against Road Rage (SCARR), contra la furia al volante.","p":"¡Correcto! Se requiere el programa contra la furia al volante (SCARR)."},"ref":{"doc":"MA","page":null}},{"id":"ma-073","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, before a Junior Operator gets the license back after a speeding suspension, what test must they pass again?","o":["The vision test","The written permit test","The road test","A drug test"],"h1":"The state wants to see the teen drive again.","h2":"In Massachusetts, a Junior Operator must pass a new road test before the license is reinstated after a speeding suspension.","p":"Right! The teen must retake the road test."},"es":{"q":"En Massachusetts, antes de que un Conductor Joven recupere la licencia tras una suspensión por velocidad, ¿qué examen debe aprobar otra vez?","o":["El examen de la vista","El examen escrito del permiso","El examen de manejo","Una prueba de drogas"],"h1":"El estado quiere ver manejar al adolescente otra vez.","h2":"En Massachusetts, un Conductor Joven debe aprobar un nuevo examen de manejo antes de recuperar la licencia tras una suspensión por exceso de velocidad.","p":"¡Correcto! El adolescente debe repetir el examen de manejo."},"ref":{"doc":"MA","page":null}},{"id":"ma-074","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, a 17-year-old is caught using a phone while driving for the first time. What is the penalty?","o":["A warning only","A $25 fine","A $500 fine and 1-year suspension","A $100 fine and a 60-day suspension"],"h1":"It includes both a fine and time without a license.","h2":"In Massachusetts, a driver under 18 caught using a phone for the first time gets a $100 fine and a 60-day license or permit suspension.","p":"Correct! $100 and 60 days without a license."},"es":{"q":"En Massachusetts, a un joven de 17 años lo detienen por primera vez usando el teléfono mientras maneja. ¿Cuál es la sanción?","o":["Solo una advertencia","Una multa de $25","Una multa de $500 y un año de suspensión","Una multa de $100 y 60 días de suspensión"],"h1":"Incluye una multa y tiempo sin licencia.","h2":"En Massachusetts, a un conductor menor de 18 años que usa el teléfono por primera vez se le pone una multa de $100 y se le suspende la licencia o el permiso por 60 días.","p":"¡Correcto! $100 y 60 días sin licencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-075","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, a driver under 18 loses the license for a first phone violation. What else must they finish before getting it back?","o":["A program that works on young drivers' attitudes","A college driving class","Ten hours of community service","A new learner's permit test"],"h1":"It is a course aimed at changing how young drivers think.","h2":"In Massachusetts, a driver under 18 suspended for a first phone violation must also complete a program that encourages attitude changes in young drivers.","p":"Right! An attitude program for young drivers is required."},"es":{"q":"En Massachusetts, un conductor menor de 18 años pierde la licencia por una primera infracción con el teléfono. ¿Qué más debe terminar antes de recuperarla?","o":["Un programa sobre la actitud de los conductores jóvenes","Una clase universitaria de manejo","Diez horas de servicio comunitario","Un nuevo examen del permiso"],"h1":"Es un curso para cambiar la forma de pensar de los conductores jóvenes.","h2":"En Massachusetts, un conductor menor de 18 años suspendido por una primera infracción con el teléfono también debe completar un programa que fomenta cambios de actitud en los conductores jóvenes.","p":"¡Correcto! Se requiere un programa de actitud para conductores jóvenes."},"ref":{"doc":"MA","page":null}},{"id":"ma-076","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how does a driver's license look different for a person under 21?","o":["It has no photo","It has a distinctive design","It is printed on paper","It shows the parent's name"],"h1":"It helps stores see quickly who is too young to buy alcohol.","h2":"In Massachusetts, licenses for people under 21 have a distinctive look so anyone can tell the holder is under the drinking age.","p":"Correct! Under-21 licenses have a distinctive design."},"es":{"q":"En Massachusetts, ¿en qué se diferencia la licencia de una persona menor de 21 años?","o":["No tiene foto","Tiene un diseño distinto","Está impresa en papel","Muestra el nombre del padre"],"h1":"Ayuda a las tiendas a ver rápido quién es muy joven para comprar alcohol.","h2":"En Massachusetts, las licencias de personas menores de 21 años tienen un diseño distinto para que se note que la persona no tiene la edad para beber alcohol.","p":"¡Correcto! Las licencias de menores de 21 tienen un diseño distinto."},"ref":{"doc":"MA","page":null}},{"id":"ma-077","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how must a driver aged 75 or older renew a license?","o":["Online only","By mail","In person at an RMV office","Through a doctor's office"],"h1":"Older drivers must show up themselves.","h2":"In Massachusetts, a driver aged 75 or older must renew the license in person at an RMV branch office.","p":"Right! At 75 and older, renewal is in person."},"es":{"q":"En Massachusetts, ¿cómo debe renovar su licencia un conductor de 75 años o más?","o":["Solo en línea","Por correo","En persona en una oficina del RMV","En el consultorio de un médico"],"h1":"Los conductores mayores deben presentarse en persona.","h2":"En Massachusetts, un conductor de 75 años o más debe renovar la licencia en persona en una oficina del RMV.","p":"¡Correcto! A partir de los 75 años, la renovación es en persona."},"ref":{"doc":"MA","page":null}},{"id":"ma-078","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, you move to a new home. How soon must you tell the RMV your new address?","o":["Within 7 days","Within 6 months","At your next renewal","Within 30 days"],"h1":"It is about one month.","h2":"In Massachusetts, license, permit and registration holders must report a change of name or address to the RMV within 30 days.","p":"Correct! Report a new address within 30 days."},"es":{"q":"En Massachusetts, te mudas a una casa nueva. ¿En cuánto tiempo debes avisar tu nueva dirección al RMV?","o":["En 7 días","En 6 meses","En tu próxima renovación","En 30 días"],"h1":"Es más o menos un mes.","h2":"En Massachusetts, quienes tienen licencia, permiso o registro deben avisar al RMV un cambio de nombre o dirección dentro de 30 días.","p":"¡Correcto! Avisa tu nueva dirección dentro de 30 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-079","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, can a resident who cannot show proof of lawful presence in the US get a driver's license?","o":["Yes, a standard Massachusetts license, if all other rules are met","No, never","Only a learner's permit","Yes, but only a REAL ID license"],"h1":"The state offers two kinds of license, and only one needs proof of lawful presence.","h2":"In Massachusetts, a resident without proof of lawful presence can get a standard Massachusetts license by proving identity, date of birth and state residency and meeting all other rules.","p":"Right! A standard Massachusetts license is available."},"es":{"q":"En Massachusetts, ¿puede un residente que no puede mostrar prueba de presencia legal en EE. UU. obtener una licencia de conducir?","o":["Sí, una licencia estándar de Massachusetts, si cumple las demás reglas","No, nunca","Solo un permiso de aprendizaje","Sí, pero solo una licencia REAL ID"],"h1":"El estado ofrece dos tipos de licencia, y solo uno pide prueba de presencia legal.","h2":"En Massachusetts, un residente sin prueba de presencia legal puede obtener una licencia estándar de Massachusetts si prueba su identidad, fecha de nacimiento y residencia en el estado, y cumple las demás reglas.","p":"¡Correcto! Puede obtener una licencia estándar de Massachusetts."},"ref":{"doc":"MA","page":null}},{"id":"ma-080","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what can a standard (non-REAL ID) Massachusetts license NOT be used for?","o":["Driving a car","Federal identification","Proving your age at a store","Renting a car"],"h1":"Think of ID checks run by the US government.","h2":"In Massachusetts, a standard license that is not REAL ID compliant is marked as not valid for federal identification.","p":"Correct! It is not valid for federal identification."},"es":{"q":"En Massachusetts, ¿para qué NO sirve una licencia estándar de Massachusetts (no REAL ID)?","o":["Para manejar un auto","Para identificación federal","Para probar tu edad en una tienda","Para rentar un auto"],"h1":"Piensa en los controles de identidad del gobierno de EE. UU.","h2":"En Massachusetts, una licencia estándar que no cumple con REAL ID lleva una marca que dice que no vale como identificación federal.","p":"¡Correcto! No vale como identificación federal."},"ref":{"doc":"MA","page":null}},{"id":"ma-081","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, the RMV gives you a receipt because your new license is not ready. How long does the receipt count as your license?","o":["7 days","30 days","60 days","One year"],"h1":"It is about two months.","h2":"In Massachusetts, an RMV receipt given in place of a license or registration counts as the real document for 60 days.","p":"Right! The receipt works for 60 days."},"es":{"q":"En Massachusetts, el RMV te da un recibo porque tu licencia nueva no está lista. ¿Por cuánto tiempo vale el recibo como licencia?","o":["7 días","30 días","60 días","Un año"],"h1":"Son unos dos meses.","h2":"En Massachusetts, el recibo que da el RMV en lugar de la licencia o el registro vale como el documento real por 60 días.","p":"¡Correcto! El recibo vale por 60 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-082","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, you just received your new license in the mail. When does it become valid?","o":["When you first drive with it","After 10 days","After you show it to police","Once you sign it"],"h1":"There is a space on the card for something only you can add.","h2":"In Massachusetts, a license is not valid until the holder signs it in the space provided.","p":"Correct! Sign your license right away."},"es":{"q":"En Massachusetts, acabas de recibir tu nueva licencia por correo. ¿Cuándo es válida?","o":["Cuando manejas con ella por primera vez","Después de 10 días","Después de mostrarla a la policía","Cuando la firmas"],"h1":"La tarjeta tiene un espacio para algo que solo tú puedes poner.","h2":"En Massachusetts, una licencia no es válida hasta que la persona la firma en el espacio indicado.","p":"¡Correcto! Firma tu licencia enseguida."},"ref":{"doc":"MA","page":null}},{"id":"ma-083","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, instead of taking the vision test at the RMV, what may a license applicant usually bring?","o":["A vision screening certificate signed by an eye doctor","A note from a pharmacist","An old pair of glasses","A school nurse's letter"],"h1":"It must come from an optometrist or ophthalmologist.","h2":"In Massachusetts, an applicant may usually give the RMV a vision screening certificate signed by an optometrist or ophthalmologist instead of taking the vision test there.","p":"Right! An eye doctor's signed certificate can be used."},"es":{"q":"En Massachusetts, en lugar de hacer el examen de la vista en el RMV, ¿qué puede presentar normalmente quien pide licencia?","o":["Un certificado de la vista firmado por un médico de los ojos","Una nota de un farmacéutico","Unos lentes viejos","Una carta de la enfermera escolar"],"h1":"Debe venir de un optometrista u oftalmólogo.","h2":"En Massachusetts, quien pide licencia normalmente puede dar al RMV un certificado de la vista firmado por un optometrista u oftalmólogo en lugar de hacer el examen allí.","p":"¡Correcto! Sirve un certificado firmado por un médico de los ojos."},"ref":{"doc":"MA","page":null}},{"id":"ma-084","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the highest fine for a first conviction of driving without ever having been licensed?","o":["$35","$100","$500","$5,000"],"h1":"It is a few hundred dollars.","h2":"In Massachusetts, driving without having been issued a license can bring a fine of up to $500 for a first offense.","p":"Right! Up to $500 for a first offense."},"es":{"q":"En Massachusetts, ¿cuál es la multa más alta por una primera condena por manejar sin haber tenido nunca licencia?","o":["$35","$100","$500","$5,000"],"h1":"Son unos cientos de dólares.","h2":"En Massachusetts, manejar sin que te hayan dado una licencia puede costar una multa de hasta $500 en una primera infracción.","p":"¡Correcto! Hasta $500 la primera vez."},"ref":{"doc":"MA","page":null}},{"id":"ma-085","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, you knowingly let a friend with a suspended license drive your car. What can happen to you for a first offense?","o":["Nothing; only the driver is punished","A $25 fine","A warning letter","A fine of up to $1,000 or up to 1 year in jail"],"h1":"The owner who allows it is also punished.","h2":"In Massachusetts, an owner who knowingly lets an unlicensed or suspended person drive can get a fine of up to $1,000 or up to one year in jail for a first offense.","p":"Correct! The owner can face up to $1,000 or a year in jail."},"es":{"q":"En Massachusetts, a sabiendas dejas que un amigo con licencia suspendida maneje tu auto. ¿Qué te puede pasar en una primera infracción?","o":["Nada; solo se castiga al conductor","Una multa de $25","Una carta de advertencia","Una multa de hasta $1,000 o hasta 1 año de cárcel"],"h1":"El dueño que lo permite también recibe castigo.","h2":"En Massachusetts, el dueño que a sabiendas deja manejar a alguien sin licencia o con licencia suspendida puede recibir una multa de hasta $1,000 o hasta un año de cárcel en una primera infracción.","p":"¡Correcto! El dueño puede recibir hasta $1,000 o un año de cárcel."},"ref":{"doc":"MA","page":null}},{"id":"ma-086","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, a visitor drives with a valid foreign license that has no English on it. What else must they carry?","o":["An international driving permit or a photo document with an English translation","A Massachusetts learner's permit","A letter from their embassy","Nothing else"],"h1":"Police need to be able to read the license.","h2":"In Massachusetts, a nonresident whose license has no English translation must also carry an international driving permit or a photo document with an English translation.","p":"Right! An international permit or an English translation is needed."},"es":{"q":"En Massachusetts, un visitante maneja con una licencia extranjera válida que no tiene nada en inglés. ¿Qué más debe llevar?","o":["Un permiso internacional de conducir o un documento con foto y traducción al inglés","Un permiso de aprendizaje de Massachusetts","Una carta de su embajada","Nada más"],"h1":"La policía necesita poder leer la licencia.","h2":"En Massachusetts, un no residente cuya licencia no tiene traducción al inglés también debe llevar un permiso internacional de conducir o un documento con foto y traducción al inglés.","p":"¡Correcto! Se necesita un permiso internacional o una traducción al inglés."},"ref":{"doc":"MA","page":null}},{"id":"ma-087","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the fine range for a first conviction of driving while your license is suspended?","o":["$50 to $100","$500 to $1,000","$5,000 to $10,000","$100 to $200"],"h1":"It starts at several hundred dollars.","h2":"In Massachusetts, a first conviction for driving after your license was suspended or revoked brings a fine of $500 to $1,000, up to 10 days in jail, or both.","p":"Correct! $500 to $1,000 for a first offense."},"es":{"q":"En Massachusetts, ¿cuál es el rango de la multa por una primera condena por manejar con la licencia suspendida?","o":["De $50 a $100","De $500 a $1,000","De $5,000 a $10,000","De $100 a $200"],"h1":"Empieza en varios cientos de dólares.","h2":"En Massachusetts, una primera condena por manejar con la licencia suspendida o revocada trae una multa de $500 a $1,000, hasta 10 días de cárcel, o ambas cosas.","p":"¡Correcto! De $500 a $1,000 en una primera infracción."},"ref":{"doc":"MA","page":null}},{"id":"ma-088","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how many major convictions, such as OUI or leaving the scene of a crash, within five years make you a habitual traffic offender?","o":["One","Two","Three","Ten"],"h1":"It is a small number of very serious offenses.","h2":"In Massachusetts, three or more major convictions within five years make a driver a habitual traffic offender.","p":"Right! Three major convictions in five years."},"es":{"q":"En Massachusetts, ¿cuántas condenas graves, como manejar ebrio o huir de un choque, en cinco años te convierten en infractor habitual de tránsito?","o":["Una","Dos","Tres","Diez"],"h1":"Es un número pequeño de infracciones muy graves.","h2":"En Massachusetts, tres o más condenas graves en cinco años convierten a un conductor en infractor habitual de tránsito.","p":"¡Correcto! Tres condenas graves en cinco años."},"ref":{"doc":"MA","page":null}},{"id":"ma-089","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a driver is declared a habitual traffic offender. How long is the license revoked?","o":["6 months","1 year","2 years","4 years"],"h1":"It lasts several years, though a hardship hearing is possible after one year.","h2":"In Massachusetts, a habitual traffic offender's license is revoked for four years, and they must finish a driver improvement course.","p":"Correct! The revocation lasts four years."},"es":{"q":"En Massachusetts, a un conductor lo declaran infractor habitual de tránsito. ¿Por cuánto tiempo se revoca su licencia?","o":["6 meses","1 año","2 años","4 años"],"h1":"Dura varios años, aunque después de un año se puede pedir una audiencia por necesidad.","h2":"En Massachusetts, la licencia de un infractor habitual de tránsito se revoca por cuatro años, y debe terminar un curso para mejorar su manejo.","p":"¡Correcto! La revocación dura cuatro años."},"ref":{"doc":"MA","page":null}},{"id":"ma-090","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fine for refusing to show your license to a police officer who asks for it?","o":["$100","$10","$1,000","$35"],"h1":"It is a round number in the low hundreds.","h2":"In Massachusetts, refusing to stop for police, give your name and address, or show your license or registration brings a $100 fine.","p":"Right! The fine is $100."},"es":{"q":"En Massachusetts, ¿cuál es la multa por negarte a mostrar tu licencia a un policía que te la pide?","o":["$100","$10","$1,000","$35"],"h1":"Es un número redondo de unos cien dólares.","h2":"En Massachusetts, negarte a parar ante la policía, dar tu nombre y dirección, o mostrar tu licencia o registro trae una multa de $100.","p":"¡Correcto! La multa es de $100."},"ref":{"doc":"MA","page":null}},{"id":"ma-091","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, you hit a parked car and the owner comes out. What must you show the owner if they ask?","o":["Your insurance bill","Your license and registration","Your home address only","Nothing; wait for police"],"h1":"It is the same documents an officer would ask for.","h2":"In Massachusetts, a driver who hits a person or property must show their license and registration to the injured person or the owner if asked.","p":"Correct! Show your license and registration when asked."},"es":{"q":"En Massachusetts, chocas un auto estacionado y sale el dueño. ¿Qué debes mostrarle si te lo pide?","o":["Tu factura del seguro","Tu licencia y tu registro","Solo tu dirección","Nada; espera a la policía"],"h1":"Son los mismos documentos que pediría un policía.","h2":"En Massachusetts, el conductor que choca a una persona o una propiedad debe mostrar su licencia y su registro a la persona herida o al dueño si se lo piden.","p":"¡Correcto! Muestra tu licencia y tu registro si te los piden."},"ref":{"doc":"MA","page":null}},{"id":"ma-092","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, you get a ticket for a civil traffic violation. How long do you have to pay it or ask for a hearing?","o":["5 days","10 days","20 days","90 days"],"h1":"It is close to three weeks.","h2":"In Massachusetts, you have 20 days from the date of a civil traffic ticket to pay it or request a hearing.","p":"Right! You have 20 days."},"es":{"q":"En Massachusetts, te ponen una multa por una infracción civil de tránsito. ¿Cuánto tiempo tienes para pagarla o pedir una audiencia?","o":["5 días","10 días","20 días","90 días"],"h1":"Son casi tres semanas.","h2":"En Massachusetts, tienes 20 días desde la fecha de la multa civil de tránsito para pagarla o pedir una audiencia.","p":"¡Correcto! Tienes 20 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-093","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, you hit a car in a parking lot and drive away without leaving your name or plate number. What can the penalty be?","o":["Nothing if the damage is small","A $10 fine","A warning letter","A fine of $20 to $200 and up to 2 years in jail"],"h1":"Leaving without identifying yourself is a crime even with no injuries.","h2":"In Massachusetts, leaving after damaging another vehicle or property without giving your name, address and plate number can bring a $20 to $200 fine and from 2 weeks to 2 years in jail.","p":"Correct! It can mean a fine and even jail time."},"es":{"q":"En Massachusetts, chocas un auto en un estacionamiento y te vas sin dejar tu nombre ni tu número de placa. ¿Cuál puede ser la sanción?","o":["Nada si el daño es pequeño","Una multa de $10","Una carta de advertencia","Una multa de $20 a $200 y hasta 2 años de cárcel"],"h1":"Irte sin identificarte es un delito aunque no haya heridos.","h2":"En Massachusetts, irte después de dañar otro vehículo o propiedad sin dar tu nombre, dirección y número de placa puede traer una multa de $20 a $200 y de 2 semanas a 2 años de cárcel.","p":"¡Correcto! Puede significar multa y hasta cárcel."},"ref":{"doc":"MA","page":null}},{"id":"ma-094","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, a driver is convicted for the first time of leaving the scene of a crash where someone was hurt. How long before they can get a new license?","o":["One year","30 days","60 days","90 days"],"h1":"It is a full year.","h2":"In Massachusetts, a first conviction for leaving the scene of a crash that injured someone means no new license for one year.","p":"Right! One year without a license."},"es":{"q":"En Massachusetts, a un conductor lo condenan por primera vez por huir de un choque donde alguien salió herido. ¿Cuánto tiempo debe esperar para una nueva licencia?","o":["Un año","30 días","60 días","90 días"],"h1":"Es un año completo.","h2":"En Massachusetts, una primera condena por huir de un choque con heridos significa no tener una nueva licencia por un año.","p":"¡Correcto! Un año sin licencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-095","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, besides the RMV, who else must get a copy of your written crash report?","o":["Your employer","The police department where the crash happened","Your doctor","The other driver's bank"],"h1":"It is the local agency that handles the road where the crash was.","h2":"In Massachusetts, you send your written crash report to the RMV and a copy to the police department where the crash happened.","p":"Correct! A copy goes to the local police."},"es":{"q":"En Massachusetts, además del RMV, ¿quién más debe recibir una copia de tu reporte escrito del choque?","o":["Tu empleador","El departamento de policía del lugar del choque","Tu médico","El banco del otro conductor"],"h1":"Es la agencia local a cargo del camino donde pasó el choque.","h2":"En Massachusetts, envías tu reporte escrito del choque al RMV y una copia al departamento de policía del lugar donde ocurrió.","p":"¡Correcto! Una copia va a la policía local."},"ref":{"doc":"MA","page":null}},{"id":"ma-096","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the minimum bodily injury coverage per person in a required auto insurance policy?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"The per-accident minimum is twice this amount.","h2":"In Massachusetts, required bodily injury coverage must be at least $25,000 per person and $50,000 per accident.","p":"Right! At least $25,000 per person."},"es":{"q":"En Massachusetts, ¿cuál es la cobertura mínima por lesiones corporales por persona en el seguro de auto obligatorio?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"El mínimo por accidente es el doble de esta cantidad.","h2":"En Massachusetts, la cobertura obligatoria por lesiones corporales debe ser de al menos $25,000 por persona y $50,000 por accidente.","p":"¡Correcto! Al menos $25,000 por persona."},"ref":{"doc":"MA","page":null}},{"id":"ma-097","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, how much personal injury protection (PIP) must an auto policy provide for each person?","o":["$1,000","$2,500","$50,000","$8,000"],"h1":"It is a few thousand dollars and pays no matter who caused the crash.","h2":"In Massachusetts, personal injury protection must pay at least $8,000 per person, no matter who was at fault.","p":"Correct! PIP pays at least $8,000 per person."},"es":{"q":"En Massachusetts, ¿cuánta protección por lesiones personales (PIP) debe dar una póliza de auto por persona?","o":["$1,000","$2,500","$50,000","$8,000"],"h1":"Son unos miles de dólares y paga sin importar quién causó el choque.","h2":"En Massachusetts, la protección por lesiones personales debe pagar al menos $8,000 por persona, sin importar quién tuvo la culpa.","p":"¡Correcto! El PIP paga al menos $8,000 por persona."},"ref":{"doc":"MA","page":null}},{"id":"ma-098","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, what fine can you get for driving a car that has no required insurance?","o":["$500 to $5,000","$25 to $50","$100 only","$50 to $200"],"h1":"It can reach several thousand dollars.","h2":"In Massachusetts, driving an uninsured motor vehicle can bring a fine of $500 to $5,000, up to one year in jail, or both.","p":"Right! $500 to $5,000."},"es":{"q":"En Massachusetts, ¿qué multa te pueden poner por manejar un auto sin el seguro obligatorio?","o":["De $500 a $5,000","De $25 a $50","Solo $100","De $50 a $200"],"h1":"Puede llegar a varios miles de dólares.","h2":"En Massachusetts, manejar un vehículo sin seguro puede traer una multa de $500 a $5,000, hasta un año de cárcel, o ambas cosas.","p":"¡Correcto! De $500 a $5,000."},"ref":{"doc":"MA","page":null}},{"id":"ma-099","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, after a first conviction for driving without insurance, how long is the license suspended?","o":["30 days","60 days","1 year","5 years"],"h1":"It is two months.","h2":"In Massachusetts, a first conviction for driving without insurance brings a 60-day license suspension.","p":"Correct! 60 days for a first conviction."},"es":{"q":"En Massachusetts, después de una primera condena por manejar sin seguro, ¿por cuánto tiempo se suspende la licencia?","o":["30 días","60 días","1 año","5 años"],"h1":"Son dos meses.","h2":"En Massachusetts, una primera condena por manejar sin seguro trae una suspensión de la licencia de 60 días.","p":"¡Correcto! 60 días por una primera condena."},"ref":{"doc":"MA","page":null}},{"id":"ma-100","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a driver is convicted of driving without insurance twice within six years. How long is the license suspended?","o":["60 days","6 months","1 year","10 years"],"h1":"A repeat offense is much longer than the first 60 days.","h2":"In Massachusetts, a second conviction for driving without insurance within six years brings a one-year license suspension.","p":"Right! A repeat within six years means one year."},"es":{"q":"En Massachusetts, a un conductor lo condenan dos veces en seis años por manejar sin seguro. ¿Por cuánto tiempo se suspende la licencia?","o":["60 días","6 meses","1 año","10 años"],"h1":"Repetir es mucho más que los 60 días de la primera vez.","h2":"En Massachusetts, una segunda condena por manejar sin seguro en seis años trae una suspensión de la licencia de un año.","p":"¡Correcto! Repetir en seis años significa un año."},"ref":{"doc":"MA","page":null}},{"id":"ma-101","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, a driver aged 21 or older is legally drunk at what blood alcohol level?","o":["0.05 percent or more","0.08 percent or more","0.10 percent or more","0.12 percent or more"],"h1":"It is the same limit used in most states for adult drivers.","h2":"In Massachusetts, a driver 21 or older with a blood alcohol level of 0.08 percent or more is operating under the influence.","p":"Right! 0.08 percent is the adult limit."},"es":{"q":"En Massachusetts, ¿con qué nivel de alcohol en la sangre se considera ebrio a un conductor de 21 años o más?","o":["0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más","0.12 por ciento o más"],"h1":"Es el mismo límite que usa la mayoría de los estados para adultos.","h2":"En Massachusetts, un conductor de 21 años o más con un nivel de alcohol en la sangre de 0.08 por ciento o más está manejando bajo la influencia.","p":"¡Correcto! 0.08 por ciento es el límite para adultos."},"ref":{"doc":"MA","page":null}},{"id":"ma-102","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the fine range for a first conviction of operating under the influence (OUI)?","o":["$50 to $250","$100 to $1,000","$500 to $5,000","$10,000 to $50,000"],"h1":"It starts at several hundred dollars and can reach thousands.","h2":"In Massachusetts, a first OUI conviction carries a fine of $500 to $5,000, up to two and a half years in jail, or both.","p":"Correct! $500 to $5,000 for a first OUI."},"es":{"q":"En Massachusetts, ¿cuál es el rango de la multa por una primera condena por manejar bajo la influencia (OUI)?","o":["De $50 a $250","De $100 a $1,000","De $500 a $5,000","De $10,000 a $50,000"],"h1":"Empieza en varios cientos de dólares y puede llegar a miles.","h2":"En Massachusetts, una primera condena por OUI trae una multa de $500 a $5,000, hasta dos años y medio de cárcel, o ambas cosas.","p":"¡Correcto! De $500 a $5,000 por un primer OUI."},"ref":{"doc":"MA","page":null}},{"id":"ma-103","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the longest jail sentence for a first OUI conviction?","o":["10 days","30 days","6 months","2 and a half years"],"h1":"It is more than two years.","h2":"In Massachusetts, a first OUI conviction can bring up to two and a half years in jail.","p":"Right! Up to two and a half years."},"es":{"q":"En Massachusetts, ¿cuál es la condena de cárcel más larga por un primer OUI?","o":["10 días","30 días","6 meses","2 años y medio"],"h1":"Es más de dos años.","h2":"En Massachusetts, una primera condena por OUI puede traer hasta dos años y medio de cárcel.","p":"¡Correcto! Hasta dos años y medio."},"ref":{"doc":"MA","page":null}},{"id":"ma-104","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the shortest jail time a person must actually serve for a second OUI conviction?","o":["30 days","No jail time","1 day","5 years"],"h1":"The sentence is at least 60 days, and part of it cannot be cut or suspended.","h2":"In Massachusetts, a second OUI brings a jail sentence of at least 60 days, and at least 30 days must be served.","p":"Correct! At least 30 days must be served."},"es":{"q":"En Massachusetts, ¿cuál es el tiempo mínimo de cárcel que se debe cumplir por una segunda condena por OUI?","o":["30 días","Nada de cárcel","1 día","5 años"],"h1":"La condena es de al menos 60 días, y una parte no se puede reducir ni suspender.","h2":"En Massachusetts, un segundo OUI trae una condena de al menos 60 días de cárcel, y se deben cumplir al menos 30 días.","p":"¡Correcto! Se deben cumplir al menos 30 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-105","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is the license revoked for a second OUI conviction?","o":["1 year","2 years","6 months","Life"],"h1":"A first conviction is one year. The second doubles it.","h2":"In Massachusetts, a second OUI conviction means the license is revoked for two years.","p":"Right! Two years for a second OUI."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo se revoca la licencia por una segunda condena por OUI?","o":["1 año","2 años","6 meses","De por vida"],"h1":"La primera condena es un año. La segunda lo duplica.","h2":"En Massachusetts, una segunda condena por OUI significa que la licencia se revoca por dos años.","p":"¡Correcto! Dos años por un segundo OUI."},"ref":{"doc":"MA","page":null}},{"id":"ma-106","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, how long is the license revoked for a third OUI conviction?","o":["2 years","4 years","8 years","20 years"],"h1":"It is many years, much longer than for a second offense.","h2":"In Massachusetts, a third OUI conviction means the license is revoked for eight years.","p":"Correct! Eight years for a third OUI."},"es":{"q":"En Massachusetts, ¿por cuánto tiempo se revoca la licencia por una tercera condena por OUI?","o":["2 años","4 años","8 años","20 años"],"h1":"Son muchos años, mucho más que por una segunda vez.","h2":"En Massachusetts, una tercera condena por OUI significa que la licencia se revoca por ocho años.","p":"¡Correcto! Ocho años por un tercer OUI."},"ref":{"doc":"MA","page":null}},{"id":"ma-107","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, a driver under 21 refuses a breath test after an OUI arrest. How long is the license suspended?","o":["3 years","90 days","180 days","30 days"],"h1":"Young drivers get a much longer suspension than the 180 days for adults.","h2":"In Massachusetts, a driver under 21 who refuses a breath or blood test has the license suspended for three years.","p":"Correct! Three years for drivers under 21."},"es":{"q":"En Massachusetts, un conductor menor de 21 años se niega a la prueba de aliento después de un arresto por OUI. ¿Por cuánto tiempo se suspende la licencia?","o":["3 años","90 días","180 días","30 días"],"h1":"A los jóvenes se les suspende mucho más que los 180 días para adultos.","h2":"En Massachusetts, a un conductor menor de 21 años que se niega a la prueba de aliento o de sangre se le suspende la licencia por tres años.","p":"¡Correcto! Tres años para menores de 21."},"ref":{"doc":"MA","page":null}},{"id":"ma-108","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, a driver with three or more earlier OUI convictions refuses a breath test. How long is the license suspended?","o":["5 years","For life","10 years","1 year"],"h1":"This is the harshest refusal penalty in the law.","h2":"In Massachusetts, a driver with three or more earlier OUI offenses who refuses a breath or blood test loses the license for life.","p":"Right! The suspension is for life."},"es":{"q":"En Massachusetts, un conductor con tres o más condenas anteriores por OUI se niega a la prueba de aliento. ¿Por cuánto tiempo se suspende la licencia?","o":["5 años","De por vida","10 años","1 año"],"h1":"Es la sanción más dura de la ley por negarse.","h2":"En Massachusetts, un conductor con tres o más infracciones anteriores por OUI que se niega a la prueba de aliento o de sangre pierde la licencia de por vida.","p":"¡Correcto! La suspensión es de por vida."},"ref":{"doc":"MA","page":null}},{"id":"ma-109","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, an adult driver takes a breath test after an OUI arrest and blows 0.08 or more. What happens to the license right away?","o":["Nothing until the trial ends","It is stamped with a warning","The officer takes it and it is suspended for up to 30 days","It is suspended for 5 years"],"h1":"The suspension starts at once but is short-term.","h2":"In Massachusetts, when a breath test shows 0.08 or more, the officer takes the license and it is suspended until the case ends, for no more than 30 days.","p":"Correct! It is taken right away and suspended for up to 30 days."},"es":{"q":"En Massachusetts, un conductor adulto hace la prueba de aliento tras un arresto por OUI y marca 0.08 o más. ¿Qué pasa con la licencia de inmediato?","o":["Nada hasta que termine el juicio","Le ponen un sello de advertencia","El policía se la quita y queda suspendida hasta 30 días","Se suspende por 5 años"],"h1":"La suspensión empieza enseguida, pero es corta.","h2":"En Massachusetts, cuando la prueba de aliento marca 0.08 o más, el policía se queda con la licencia y queda suspendida hasta que termine el caso, por no más de 30 días.","p":"¡Correcto! Se la quitan enseguida y queda suspendida hasta 30 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-110","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, after a police breath test for OUI, what extra test may you ask for?","o":["A second test by the same officer","A test at the RMV","A urine test at a pharmacy","A test by a doctor you choose, at your own cost"],"h1":"You can get your own test, but you pay for it.","h2":"In Massachusetts, a person arrested for OUI may have another test done by a physician of their own choice at their own expense.","p":"Right! You may get your own test from a doctor you choose and pay for it."},"es":{"q":"En Massachusetts, después de la prueba de aliento de la policía por OUI, ¿qué prueba adicional puedes pedir?","o":["Una segunda prueba con el mismo policía","Una prueba en el RMV","Una prueba de orina en una farmacia","Una prueba con un médico que tú elijas, pagada por ti"],"h1":"Puedes hacerte tu propia prueba, pero la pagas tú.","h2":"En Massachusetts, una persona arrestada por OUI puede hacerse otra prueba con un médico de su elección, pagándola ella misma.","p":"¡Correcto! Puedes hacerte tu propia prueba con un médico que elijas y pagarla tú."},"ref":{"doc":"MA","page":null}},{"id":"ma-111","scope":"MA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Massachusetts, an adult first offender is placed in the OUI alcohol education program. How long is the license suspended?","o":["45 to 90 days","1 to 2 years","10 days","No suspension at all"],"h1":"It is a few months at most.","h2":"In Massachusetts, an adult first offender placed in the alcohol education program has the license suspended for 45 to 90 days.","p":"Correct! The suspension is 45 to 90 days."},"es":{"q":"En Massachusetts, a un adulto en su primera infracción lo ponen en el programa de educación sobre alcohol por OUI. ¿Por cuánto tiempo se suspende la licencia?","o":["De 45 a 90 días","De 1 a 2 años","10 días","No hay suspensión"],"h1":"Son unos pocos meses como máximo.","h2":"En Massachusetts, a un adulto en su primera infracción que entra al programa de educación sobre alcohol se le suspende la licencia de 45 a 90 días.","p":"¡Correcto! La suspensión es de 45 a 90 días."},"ref":{"doc":"MA","page":null}},{"id":"ma-112","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, a first offender under 21 is placed in the OUI alcohol education program. How long is the license suspended?","o":["45 days","210 days","90 days","2 years"],"h1":"Younger drivers get a longer suspension than the 45 to 90 days for adults.","h2":"In Massachusetts, a first offender under 21 in the OUI alcohol program has the license suspended for 210 days.","p":"Right! 210 days for drivers under 21."},"es":{"q":"En Massachusetts, a un menor de 21 años en su primera infracción lo ponen en el programa de educación sobre alcohol por OUI. ¿Por cuánto tiempo se suspende la licencia?","o":["45 días","210 días","90 días","2 años"],"h1":"A los más jóvenes se les suspende más que los 45 a 90 días de los adultos.","h2":"En Massachusetts, a un menor de 21 años en su primera infracción en el programa de alcohol por OUI se le suspende la licencia por 210 días.","p":"¡Correcto! 210 días para menores de 21."},"ref":{"doc":"MA","page":null}},{"id":"ma-113","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a 19-year-old driver is found with a blood alcohol level of 0.02 or more. How long does the RMV suspend the license?","o":["30 days","90 days","180 days","3 years"],"h1":"It is about half a year.","h2":"In Massachusetts, the RMV suspends the license of a driver aged 18 to 20 with 0.02 or more for 180 days.","p":"Correct! 180 days for a driver aged 18 to 20."},"es":{"q":"En Massachusetts, a un conductor de 19 años le encuentran un nivel de alcohol en la sangre de 0.02 o más. ¿Por cuánto tiempo suspende el RMV la licencia?","o":["30 días","90 días","180 días","3 años"],"h1":"Es más o menos medio año.","h2":"En Massachusetts, el RMV suspende por 180 días la licencia de un conductor de 18 a 20 años con 0.02 o más.","p":"¡Correcto! 180 días para un conductor de 18 a 20 años."},"ref":{"doc":"MA","page":null}},{"id":"ma-114","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, a 17-year-old driver is found with a blood alcohol level of 0.02 or more. How long does the RMV suspend the license?","o":["30 days","60 days","180 days","One year"],"h1":"Drivers under 18 get twice as long as drivers aged 18 to 20.","h2":"In Massachusetts, the RMV suspends the license of a driver under 18 with 0.02 or more for one year.","p":"Right! One year for a driver under 18."},"es":{"q":"En Massachusetts, a un conductor de 17 años le encuentran un nivel de alcohol en la sangre de 0.02 o más. ¿Por cuánto tiempo suspende el RMV la licencia?","o":["30 días","60 días","180 días","Un año"],"h1":"A los menores de 18 se les suspende el doble que a los de 18 a 20 años.","h2":"En Massachusetts, el RMV suspende por un año la licencia de un conductor menor de 18 años con 0.02 o más.","p":"¡Correcto! Un año para un conductor menor de 18."},"ref":{"doc":"MA","page":null}},{"id":"ma-115","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, OUI becomes the extra crime of child endangerment when a child of what age is in the vehicle?","o":["14 or younger","18 or younger","10 or younger","5 or younger"],"h1":"It covers children up to their early teens.","h2":"In Massachusetts, driving under the influence with a child 14 years old or younger in the vehicle is also child endangerment, with extra penalties.","p":"Correct! A child 14 or younger."},"es":{"q":"En Massachusetts, manejar bajo la influencia se vuelve además el delito de poner en peligro a un menor cuando en el vehículo va un niño de ¿qué edad?","o":["14 años o menos","18 años o menos","10 años o menos","5 años o menos"],"h1":"Incluye a niños hasta el inicio de la adolescencia.","h2":"En Massachusetts, manejar bajo la influencia con un niño de 14 años o menos en el vehículo también es poner en peligro a un menor, con sanciones adicionales.","p":"¡Correcto! Un niño de 14 años o menos."},"ref":{"doc":"MA","page":null}},{"id":"ma-116","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, how long is the extra license suspension for a first conviction of OUI child endangerment?","o":["90 days","1 year","5 years","30 days"],"h1":"It is a full year, added to the OUI penalties.","h2":"In Massachusetts, a first conviction of OUI child endangerment brings an extra one-year license suspension.","p":"Right! An extra year without a license."},"es":{"q":"En Massachusetts, ¿cuánto dura la suspensión adicional de la licencia por una primera condena por poner en peligro a un menor al manejar bajo la influencia?","o":["90 días","1 año","5 años","30 días"],"h1":"Es un año completo, además de las sanciones por OUI.","h2":"En Massachusetts, una primera condena por poner en peligro a un menor al manejar bajo la influencia trae una suspensión adicional de la licencia de un año.","p":"¡Correcto! Un año más sin licencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-117","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, where may you carry an opened bottle of wine in your car?","o":["In the cup holder","Under the driver's seat","In the trunk","In an unlocked glove box"],"h1":"It must be out of reach of everyone in the seats.","h2":"In Massachusetts, an open alcohol container may be carried in the trunk or a locked glove compartment, not in the passenger area.","p":"Correct! Put it in the trunk."},"es":{"q":"En Massachusetts, ¿dónde puedes llevar una botella de vino abierta en tu auto?","o":["En el portavasos","Debajo del asiento del conductor","En la cajuela (maletero)","En la guantera sin llave"],"h1":"Debe estar fuera del alcance de todos los que van sentados.","h2":"En Massachusetts, un envase de alcohol abierto se puede llevar en la cajuela o en una guantera cerrada con llave, no en el área de pasajeros.","p":"¡Correcto! Ponlo en la cajuela."},"ref":{"doc":"MA","page":null}},{"id":"ma-118","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, when may an adult driver look at a phone screen while driving?","o":["To view a navigation map on a phone mounted on the dash, windshield or console","To read a short text at a red light","To check email in slow traffic","Never, not even for a map"],"h1":"Only one kind of screen use is allowed, and the phone must be mounted.","h2":"In Massachusetts, a driver may view a navigation map on a device mounted on the windshield, dashboard or center console, but may not read texts or watch videos.","p":"Correct! Only a map on a mounted phone."},"es":{"q":"En Massachusetts, ¿cuándo puede un conductor adulto mirar la pantalla del teléfono mientras maneja?","o":["Para ver un mapa de navegación en un teléfono montado en el tablero, parabrisas o consola","Para leer un mensaje corto en un semáforo en rojo","Para revisar el correo en tráfico lento","Nunca, ni siquiera para un mapa"],"h1":"Solo se permite un tipo de uso de la pantalla, y el teléfono debe estar montado.","h2":"En Massachusetts, el conductor puede ver un mapa de navegación en un aparato montado en el parabrisas, el tablero o la consola central, pero no puede leer mensajes ni ver videos.","p":"¡Correcto! Solo un mapa en un teléfono montado."},"ref":{"doc":"MA","page":null}},{"id":"ma-119","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, you are stopped at a red light in a travel lane. May you hold your phone to read a message?","o":["Yes, if the car is not moving","No, you are still operating the vehicle","Yes, if the engine is off","Yes, for under 10 seconds"],"h1":"The law only exempts a car parked out of the travel lanes.","h2":"In Massachusetts, a driver stopped in a travel lane, such as at a red light, is still operating the vehicle and may not hold or read a phone.","p":"Right! A red light stop still counts as driving."},"es":{"q":"En Massachusetts, estás detenido en un semáforo en rojo en un carril de circulación. ¿Puedes tomar tu teléfono para leer un mensaje?","o":["Sí, si el auto no se mueve","No, sigues operando el vehículo","Sí, si el motor está apagado","Sí, por menos de 10 segundos"],"h1":"La ley solo exceptúa un auto estacionado fuera de los carriles.","h2":"En Massachusetts, un conductor detenido en un carril de circulación, como en un semáforo en rojo, sigue operando el vehículo y no puede tomar ni leer el teléfono.","p":"¡Correcto! Detenerse en un semáforo sigue contando como manejar."},"ref":{"doc":"MA","page":null}},{"id":"ma-120","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the fine for a second hands-free law violation?","o":["$100","$150","$250","$1,000"],"h1":"The first is $100 and the third is $500.","h2":"In Massachusetts, a second violation of the hands-free law brings a $250 fine and a required distracted driving program.","p":"Correct! $250 and a distracted driving program."},"es":{"q":"En Massachusetts, ¿cuál es la multa por una segunda infracción de la ley de manos libres?","o":["$100","$150","$250","$1,000"],"h1":"La primera es $100 y la tercera es $500.","h2":"En Massachusetts, una segunda infracción de la ley de manos libres trae una multa de $250 y un programa obligatorio sobre manejo distraído.","p":"¡Correcto! $250 y un programa sobre manejo distraído."},"ref":{"doc":"MA","page":null}},{"id":"ma-121","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, which hands-free law violation becomes a surchargeable incident that can raise your insurance?","o":["The first","The second","None of them ever","The third or later"],"h1":"The first two do not count against your insurance.","h2":"In Massachusetts, a third or later hands-free violation is a surchargeable incident and can raise your insurance.","p":"Right! The third and later violations are surchargeable."},"es":{"q":"En Massachusetts, ¿qué infracción de la ley de manos libres se vuelve un incidente con recargo que puede subir tu seguro?","o":["La primera","La segunda","Ninguna, nunca","La tercera o posteriores"],"h1":"Las dos primeras no cuentan contra tu seguro.","h2":"En Massachusetts, la tercera infracción de manos libres o una posterior es un incidente con recargo y puede subir tu seguro.","p":"¡Correcto! La tercera y las siguientes tienen recargo."},"ref":{"doc":"MA","page":null}},{"id":"ma-122","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fine for a school bus driver who uses a phone, even hands-free, while driving the bus?","o":["$500","$50","$100","$25"],"h1":"It is the same amount as the third-offense fine for other drivers.","h2":"In Massachusetts, a school bus or public transit driver who uses a phone, even hands-free, while operating gets a $500 fine.","p":"Correct! $500 for a bus driver using a phone."},"es":{"q":"En Massachusetts, ¿cuál es la multa para un conductor de autobús escolar que usa el teléfono, aun con manos libres, mientras maneja el autobús?","o":["$500","$50","$100","$25"],"h1":"Es la misma cantidad que la multa por tercera vez para otros conductores.","h2":"En Massachusetts, un conductor de autobús escolar o de transporte público que usa el teléfono, aun con manos libres, mientras maneja recibe una multa de $500.","p":"¡Correcto! $500 para un conductor de autobús que usa el teléfono."},"ref":{"doc":"MA","page":null}},{"id":"ma-123","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, may you drive while wearing headphones to listen to music?","o":["Yes, with one ear covered","No, headphones are not allowed while driving","Yes, at low volume","Yes, on highways only"],"h1":"Hearing horns and sirens matters.","h2":"In Massachusetts, you may not drive while wearing headphones, except those used to communicate about controlling the vehicle's movement.","p":"Right! No headphones while driving."},"es":{"q":"En Massachusetts, ¿puedes manejar con audífonos para escuchar música?","o":["Sí, con un oído tapado","No, no se permiten audífonos al manejar","Sí, a volumen bajo","Sí, solo en autopistas"],"h1":"Es importante oír bocinas y sirenas.","h2":"En Massachusetts, no puedes manejar con audífonos, salvo los que se usan para comunicarse sobre cómo mover el vehículo.","p":"¡Correcto! Nada de audífonos al manejar."},"ref":{"doc":"MA","page":null}},{"id":"ma-124","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, an ice cream truck with flashing amber lights is parked ahead. How fast may you drive within one-tenth of a mile of it?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Children may run toward the truck. The limit is lower than a school zone.","h2":"In Massachusetts, driving faster than 15 mph within one-tenth of a mile of a vendor truck showing flashing amber lights is treated as unsafe speed.","p":"Correct! No faster than 15 mph near the truck."},"es":{"q":"En Massachusetts, hay un camión de helados estacionado adelante con luces ámbar intermitentes. ¿A qué velocidad puedes manejar a menos de una décima de milla de él?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Los niños pueden correr hacia el camión. El límite es menor que en una zona escolar.","h2":"En Massachusetts, manejar a más de 15 mph a menos de una décima de milla de un camión vendedor con luces ámbar intermitentes se considera velocidad insegura.","p":"¡Correcto! No más de 15 mph cerca del camión."},"ref":{"doc":"MA","page":null}},{"id":"ma-125","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the top speed for a school bus carrying children, except on a limited-access highway?","o":["30 mph","50 mph","55 mph","40 mph"],"h1":"It is the same as the default limit on an undivided road outside thickly settled areas.","h2":"In Massachusetts, a school bus carrying children may not go faster than 40 mph, except on a limited-access highway.","p":"Right! 40 mph for a school bus with children."},"es":{"q":"En Massachusetts, ¿cuál es la velocidad máxima de un autobús escolar que lleva niños, salvo en una autopista de acceso limitado?","o":["30 mph","50 mph","55 mph","40 mph"],"h1":"Es igual al límite normal en un camino no dividido fuera de zonas densamente pobladas.","h2":"En Massachusetts, un autobús escolar que lleva niños no puede ir a más de 40 mph, salvo en una autopista de acceso limitado.","p":"¡Correcto! 40 mph para un autobús escolar con niños."},"ref":{"doc":"MA","page":null}},{"id":"ma-126","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, what speed limit does state law set on the Massachusetts Turnpike (I-90) between the New York border and Westfield?","o":["65 mph","70 mph","75 mph","60 mph"],"h1":"It is the same limit the law sets on parts of I-91 and I-95.","h2":"In Massachusetts, state law sets a 65 mph limit on I-90 from the New York border to Westfield, and on named stretches of I-91 and I-95.","p":"Correct! The law sets 65 mph there."},"es":{"q":"En Massachusetts, ¿qué límite de velocidad fija la ley estatal en la autopista de peaje de Massachusetts (I-90) entre la frontera con Nueva York y Westfield?","o":["65 mph","70 mph","75 mph","60 mph"],"h1":"Es el mismo límite que la ley fija en partes de la I-91 y la I-95.","h2":"En Massachusetts, la ley estatal fija un límite de 65 mph en la I-90 desde la frontera con Nueva York hasta Westfield, y en ciertos tramos de la I-91 y la I-95.","p":"¡Correcto! La ley fija 65 mph allí."},"ref":{"doc":"MA","page":null}},{"id":"ma-127","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, a city may adopt a special lower default limit for thickly settled or business districts on its own roads. What is it?","o":["20 mph","25 mph","15 mph","35 mph"],"h1":"It is 5 mph below the usual 30 mph.","h2":"In Massachusetts, a city or town that accepts the law may set a 25 mph limit in thickly settled or business districts on roads that are not state highways.","p":"Right! Cities and towns may choose 25 mph."},"es":{"q":"En Massachusetts, una ciudad puede adoptar un límite especial más bajo para zonas densamente pobladas o comerciales en sus propias calles. ¿Cuál es?","o":["20 mph","25 mph","15 mph","35 mph"],"h1":"Es 5 mph menos que las 30 mph de siempre.","h2":"En Massachusetts, una ciudad o pueblo que acepta la ley puede fijar un límite de 25 mph en zonas densamente pobladas o comerciales en calles que no son carreteras estatales.","p":"¡Correcto! Las ciudades y pueblos pueden elegir 25 mph."},"ref":{"doc":"MA","page":null}},{"id":"ma-128","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, a road counts as \"thickly settled\" when houses or buildings along it are, on average, closer than what distance apart for a quarter mile?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is twice 100 feet.","h2":"In Massachusetts, an area is thickly settled when buildings along the road average less than 200 feet apart for a quarter mile or more.","p":"Correct! Less than 200 feet apart on average."},"es":{"q":"En Massachusetts, una calle se considera \"densamente poblada\" cuando las casas o edificios a lo largo de ella están, en promedio, a menos de ¿qué distancia entre sí por un cuarto de milla?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es el doble de 100 pies.","h2":"En Massachusetts, una zona es densamente poblada cuando los edificios junto a la calle están, en promedio, a menos de 200 pies entre sí por un cuarto de milla o más.","p":"¡Correcto! A menos de 200 pies en promedio."},"ref":{"doc":"MA","page":null}},{"id":"ma-129","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, how is the speeding fine increased when you go more than 10 mph over the limit?","o":["It doubles","A flat $25 is added","Nothing is added","$10 for each mph above the first 10"],"h1":"It grows with every mile per hour.","h2":"In Massachusetts, the speeding fine is at least $50, plus $10 for each mph you were going beyond 10 mph over the limit.","p":"Right! $10 more for each extra mph."},"es":{"q":"En Massachusetts, ¿cómo aumenta la multa por velocidad cuando vas a más de 10 mph sobre el límite?","o":["Se duplica","Se suman $25 fijos","No se suma nada","$10 por cada mph después de las primeras 10"],"h1":"Crece con cada milla por hora.","h2":"En Massachusetts, la multa por velocidad es de al menos $50, más $10 por cada mph que ibas por encima de 10 mph sobre el límite.","p":"¡Correcto! $10 más por cada mph extra."},"ref":{"doc":"MA","page":null}},{"id":"ma-130","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, on a road with more than one lane in your direction, which lane should you normally drive in?","o":["The far-left lane","The lane nearest the right side","Any lane you like","The center lane only"],"h1":"You leave this lane to pass or to get ready for a left turn.","h2":"In Massachusetts, you must drive in the lane nearest the right side of the road, except when passing or getting ready to turn left.","p":"Right! Keep to the right lane."},"es":{"q":"En Massachusetts, en una calle con más de un carril en tu dirección, ¿en qué carril debes manejar normalmente?","o":["El carril de la extrema izquierda","El carril más cercano al lado derecho","El carril que quieras","Solo el carril del centro"],"h1":"Sales de este carril para rebasar o para prepararte a girar a la izquierda.","h2":"En Massachusetts, debes manejar en el carril más cercano al lado derecho, salvo cuando rebasas o te preparas para girar a la izquierda.","p":"¡Correcto! Mantente en el carril derecho."},"ref":{"doc":"MA","page":null}},{"id":"ma-131","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, on a highway with more than one passing lane in the same direction, where must heavy trucks over 2.5 tons normally drive?","o":["In the left lane","In any lane","In the right-hand travel lane","On the shoulder"],"h1":"Big trucks stay out of the way of faster traffic.","h2":"In Massachusetts, heavy commercial vehicles over 2.5 tons must normally use the right-hand travel lane on highways with more than one passing lane, and pass only in the next lane over.","p":"Correct! Heavy trucks keep to the right-hand lane."},"es":{"q":"En Massachusetts, en una autopista con más de un carril para rebasar en la misma dirección, ¿por dónde deben manejar normalmente los camiones pesados de más de 2.5 toneladas?","o":["Por el carril izquierdo","Por cualquier carril","Por el carril derecho de circulación","Por el acotamiento"],"h1":"Los camiones grandes se apartan del tráfico más rápido.","h2":"En Massachusetts, los vehículos comerciales pesados de más de 2.5 toneladas deben usar normalmente el carril derecho en autopistas con más de un carril para rebasar, y rebasar solo por el carril de al lado.","p":"¡Correcto! Los camiones pesados van por el carril derecho."},"ref":{"doc":"MA","page":null}},{"id":"ma-132","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, when may you pass another vehicle on the right?","o":["Whenever the right lane is empty","On any two-lane road","Never, under any condition","When it is turning left, or on a one-way road with room for two lines"],"h1":"There must be enough road, and the other car must be out of the way.","h2":"In Massachusetts, you may pass on the right when the road is clear and wide enough and the other vehicle is turning left, or on a one-way road.","p":"Right! Only when the car ahead turns left or on a wide one-way road."},"es":{"q":"En Massachusetts, ¿cuándo puedes rebasar a otro vehículo por la derecha?","o":["Siempre que el carril derecho esté libre","En cualquier camino de dos carriles","Nunca, en ningún caso","Cuando va a girar a la izquierda, o en una vía de un sentido con espacio para dos filas"],"h1":"Debe haber suficiente espacio, y el otro auto debe estar fuera del camino.","h2":"En Massachusetts, puedes rebasar por la derecha cuando el camino está libre y es lo bastante ancho y el otro vehículo gira a la izquierda, o en una vía de un solo sentido.","p":"¡Correcto! Solo cuando el auto de adelante gira a la izquierda o en una vía ancha de un sentido."},"ref":{"doc":"MA","page":null}},{"id":"ma-133","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, a car is passing you and signals. What must you do?","o":["Move right and do not speed up until it has passed","Speed up to keep your place","Move to the left","Brake hard"],"h1":"Make it easy for the other driver to get by.","h2":"In Massachusetts, a driver being passed must give way to the right and must not speed up until the passing vehicle has completely gone by.","p":"Correct! Keep right and do not speed up."},"es":{"q":"En Massachusetts, un auto te está rebasando y hace una señal. ¿Qué debes hacer?","o":["Moverte a la derecha y no acelerar hasta que haya pasado","Acelerar para mantener tu lugar","Moverte a la izquierda","Frenar fuerte"],"h1":"Facilítale el paso al otro conductor.","h2":"En Massachusetts, el conductor al que rebasan debe ceder hacia la derecha y no debe acelerar hasta que el otro vehículo haya pasado por completo.","p":"¡Correcto! Mantente a la derecha y no aceleres."},"ref":{"doc":"MA","page":null}},{"id":"ma-134","scope":"MA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Massachusetts, you cannot pass a bicyclist safely within your lane. What does the law allow?","o":["Honking until the cyclist moves over","Using part or all of the next lane, even crossing the center line, when safe","Passing within 1 foot at low speed","Speeding up to pass quickly"],"h1":"You may leave your lane if it is safe.","h2":"In Massachusetts, if you cannot pass a vulnerable user safely in your lane, you must use part or all of the next lane, crossing the center line if needed, when it is safe and within the speed limit.","p":"Right! Use the next lane when it is safe."},"es":{"q":"En Massachusetts, no puedes rebasar a un ciclista con seguridad dentro de tu carril. ¿Qué permite la ley?","o":["Tocar la bocina hasta que el ciclista se aparte","Usar parte o todo el carril de al lado, aun cruzando la línea central, cuando sea seguro","Rebasar a 1 pie de distancia a baja velocidad","Acelerar para rebasar rápido"],"h1":"Puedes salir de tu carril si es seguro.","h2":"En Massachusetts, si no puedes rebasar con seguridad a un usuario vulnerable en tu carril, debes usar parte o todo el carril de al lado, cruzando la línea central si hace falta, cuando sea seguro y sin pasar el límite de velocidad.","p":"¡Correcto! Usa el otro carril cuando sea seguro."},"ref":{"doc":"MA","page":null}},{"id":"ma-135","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, may you cross a solid center line to turn left into a driveway?","o":["No, never","Only at night","Yes, when turning left into or out of a private way","Only with a police escort"],"h1":"The law makes an exception for turning to or from private property.","h2":"In Massachusetts, you may cross a solid center line to make a left turn into or out of a private way, such as a driveway.","p":"Correct! A left turn into or out of a driveway may cross it."},"es":{"q":"En Massachusetts, ¿puedes cruzar una línea central continua para girar a la izquierda hacia una entrada de casa?","o":["No, nunca","Solo de noche","Sí, al girar a la izquierda para entrar o salir de un camino privado","Solo con escolta policial"],"h1":"La ley hace una excepción para entrar o salir de una propiedad privada.","h2":"En Massachusetts, puedes cruzar una línea central continua para girar a la izquierda al entrar o salir de un camino privado, como una entrada de casa.","p":"¡Correcto! Al girar a la izquierda para entrar o salir de una entrada de casa se puede cruzar."},"ref":{"doc":"MA","page":null}},{"id":"ma-136","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, what is a lane rule for motorcycle riders?","o":["Up to four may ride side by side","They may pass cars within the same lane","They must ride on the shoulder","No more than two may ride side by side"],"h1":"Riders may pair up, but not more.","h2":"In Massachusetts, motorcycles may not ride more than two abreast, must ride single file when passing, and may not pass a car within the same lane.","p":"Right! No more than two motorcycles side by side."},"es":{"q":"En Massachusetts, ¿cuál es una regla de carriles para los motociclistas?","o":["Hasta cuatro pueden ir lado a lado","Pueden rebasar autos dentro del mismo carril","Deben ir por el acotamiento","No más de dos pueden ir lado a lado"],"h1":"Pueden ir en pareja, pero no más.","h2":"En Massachusetts, las motocicletas no pueden ir más de dos lado a lado, deben ir en fila al rebasar y no pueden rebasar a un auto dentro del mismo carril.","p":"¡Correcto! No más de dos motocicletas lado a lado."},"ref":{"doc":"MA","page":null}},{"id":"ma-137","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, may you stop or park in a marked bike lane to drop off a passenger?","o":["No, only in an emergency","Yes, for up to 5 minutes","Yes, if you turn on your hazard lights","Yes, at night"],"h1":"Bike lanes are for bicycles only.","h2":"In Massachusetts, you may not stand or park a vehicle in a designated bike lane except in an emergency.","p":"Correct! Only in an emergency."},"es":{"q":"En Massachusetts, ¿puedes detenerte o estacionarte en un carril para bicicletas marcado para dejar a un pasajero?","o":["No, solo en una emergencia","Sí, por hasta 5 minutos","Sí, si pones las luces intermitentes","Sí, de noche"],"h1":"Los carriles para bicicletas son solo para bicicletas.","h2":"En Massachusetts, no puedes detenerte ni estacionar un vehículo en un carril designado para bicicletas, salvo en una emergencia.","p":"¡Correcto! Solo en una emergencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-138","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, how should you make a right turn?","o":["From the center of the road","From the lane nearest the right curb, staying close to it","From any lane with a signal","From the left lane"],"h1":"Stay as far right as you can.","h2":"In Massachusetts, a right turn must be made from the lane nearest the right side of the road, as close as practical to the right curb or edge.","p":"Right! Turn from the rightmost lane, close to the curb."},"es":{"q":"En Massachusetts, ¿cómo debes girar a la derecha?","o":["Desde el centro de la calle","Desde el carril más cercano a la acera derecha, pegado a ella","Desde cualquier carril con señal","Desde el carril izquierdo"],"h1":"Mantente lo más a la derecha que puedas.","h2":"En Massachusetts, un giro a la derecha se hace desde el carril más cercano al lado derecho, lo más cerca posible de la acera o del borde derecho.","p":"¡Correcto! Gira desde el carril más a la derecha, cerca de la acera."},"ref":{"doc":"MA","page":null}},{"id":"ma-139","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, you just passed a bicyclist and now want to turn right. What does the law say?","o":["Turn right away; you are ahead","Honk, then turn","Turn only if you can do it at a safe distance from the cyclist","Speed up before turning"],"h1":"Cutting across a cyclist you just passed causes many crashes.","h2":"In Massachusetts, after passing a bicyclist, you may not turn right at an intersection or driveway unless you can do it at a safe distance and speed.","p":"Correct! Do not cut off the cyclist."},"es":{"q":"En Massachusetts, acabas de rebasar a un ciclista y ahora quieres girar a la derecha. ¿Qué dice la ley?","o":["Gira enseguida; vas adelante","Toca la bocina y gira","Gira solo si puedes hacerlo a una distancia segura del ciclista","Acelera antes de girar"],"h1":"Cruzarte frente a un ciclista que acabas de rebasar causa muchos choques.","h2":"En Massachusetts, después de rebasar a un ciclista no puedes girar a la derecha en una intersección o entrada salvo que puedas hacerlo a una distancia y velocidad seguras.","p":"¡Correcto! No le cierres el paso al ciclista."},"ref":{"doc":"MA","page":null}},{"id":"ma-140","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, you are turning left. An oncoming bicyclist is riding to the right of the oncoming cars. What must you do?","o":["Turn, because bikes must ride in the middle","Turn after the cars, ignoring the bike","Flash your lights at the cyclist","Yield to the bicyclist as you would to any oncoming vehicle"],"h1":"Being at the right edge does not take away a cyclist's right-of-way.","h2":"In Massachusetts, a driver turning left must yield to oncoming traffic, including a bicyclist riding to the right of other vehicles.","p":"Right! Yield to the oncoming cyclist."},"es":{"q":"En Massachusetts, vas a girar a la izquierda. Un ciclista viene de frente por la derecha de los autos que vienen. ¿Qué debes hacer?","o":["Girar, porque las bicicletas deben ir por el centro","Girar después de los autos, sin fijarte en la bici","Hacerle cambio de luces al ciclista","Ceder el paso al ciclista como a cualquier vehículo que viene de frente"],"h1":"Ir por la orilla derecha no le quita al ciclista su derecho de paso.","h2":"En Massachusetts, quien gira a la izquierda debe ceder el paso al tráfico que viene de frente, incluido un ciclista que va a la derecha de los otros vehículos.","p":"¡Correcto! Cede el paso al ciclista que viene de frente."},"ref":{"doc":"MA","page":null}},{"id":"ma-141","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the fine for opening a car door into the path of a bicyclist when it was not safe?","o":["Up to $100","Up to $10","Up to $1,000","No fine, only a warning"],"h1":"It is about the same as many traffic fines.","h2":"In Massachusetts, opening a vehicle door when it is not safe to do so, such as into a bicyclist's path, can bring a fine of up to $100.","p":"Correct! Up to $100."},"es":{"q":"En Massachusetts, ¿cuál es la multa por abrir la puerta del auto en el camino de un ciclista cuando no era seguro?","o":["Hasta $100","Hasta $10","Hasta $1,000","No hay multa, solo advertencia"],"h1":"Es parecida a muchas multas de tránsito.","h2":"En Massachusetts, abrir la puerta de un vehículo cuando no es seguro, por ejemplo en el camino de un ciclista, puede costar una multa de hasta $100.","p":"¡Correcto! Hasta $100."},"ref":{"doc":"MA","page":null}},{"id":"ma-142","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, which of these counts as a \"vulnerable user\" you must pass with at least 4 feet of space?","o":["A delivery truck","A person riding a horse","A motorcycle on the highway","A parked car"],"h1":"It includes people on foot, on bikes, in wheelchairs and on animals.","h2":"In Massachusetts, vulnerable users include pedestrians, road workers, bicyclists, wheelchair users, people riding horses and farm tractors.","p":"Right! A horse rider is a vulnerable user."},"es":{"q":"En Massachusetts, ¿cuál de estos cuenta como \"usuario vulnerable\" al que debes rebasar dejando al menos 4 pies?","o":["Un camión de reparto","Una persona a caballo","Una motocicleta en la autopista","Un auto estacionado"],"h1":"Incluye a personas a pie, en bicicleta, en silla de ruedas y sobre animales.","h2":"En Massachusetts, los usuarios vulnerables incluyen peatones, trabajadores en la vía, ciclistas, personas en silla de ruedas, personas a caballo y tractores agrícolas.","p":"¡Correcto! Una persona a caballo es un usuario vulnerable."},"ref":{"doc":"MA","page":null}},{"id":"ma-143","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, a person riding a horse signals you to stop because the horse looks frightened. What must you do?","o":["Honk so the horse moves","Pass quickly","Stop your vehicle right away","Flash your high beams"],"h1":"A scared animal can be dangerous; give it time.","h2":"In Massachusetts, you must stop right away when the person in charge of a frightened horse or other animal signals you to stop.","p":"Correct! Stop right away."},"es":{"q":"En Massachusetts, una persona a caballo te hace señal de parar porque el caballo se ve asustado. ¿Qué debes hacer?","o":["Tocar la bocina para que el caballo se mueva","Pasar rápido","Detener tu vehículo enseguida","Poner las luces altas"],"h1":"Un animal asustado puede ser peligroso; dale tiempo.","h2":"En Massachusetts, debes detenerte enseguida cuando la persona a cargo de un caballo u otro animal asustado te hace señal de parar.","p":"¡Correcto! Detente enseguida."},"ref":{"doc":"MA","page":null}},{"id":"ma-144","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, a streetcar has stopped to let riders on and off. How close may you drive to its lowest step?","o":["Any distance if you are slow","2 feet","4 feet","No closer than 8 feet"],"h1":"Riders step down into the street, so leave a wide gap.","h2":"In Massachusetts, you may not drive within 8 feet of the step of a stopped streetcar that riders are using, unless a safety zone or a traffic officer allows it.","p":"Right! Stay at least 8 feet away."},"es":{"q":"En Massachusetts, un tranvía se detuvo para que suban y bajen pasajeros. ¿A qué distancia de su escalón más bajo puedes pasar?","o":["A cualquier distancia si vas despacio","A 2 pies","A 4 pies","No más cerca de 8 pies"],"h1":"Los pasajeros bajan a la calle, así que deja buen espacio.","h2":"En Massachusetts, no puedes pasar a menos de 8 pies del escalón de un tranvía detenido que usan los pasajeros, salvo que haya una zona de seguridad o lo indique un agente de tránsito.","p":"¡Correcto! Mantente al menos a 8 pies."},"ref":{"doc":"MA","page":null}},{"id":"ma-145","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, what fine can a driver get for not stopping for a blind pedestrian with a white cane or guide dog?","o":["$100 to $500","$10 to $20","$1,000 to $5,000","$25"],"h1":"It starts at one hundred dollars.","h2":"In Massachusetts, failing to stop for a blind pedestrian using a white cane or a guide dog can bring a fine of $100 to $500.","p":"Correct! $100 to $500."},"es":{"q":"En Massachusetts, ¿qué multa puede recibir un conductor que no se detiene ante un peatón ciego con bastón blanco o perro guía?","o":["De $100 a $500","De $10 a $20","De $1,000 a $5,000","$25"],"h1":"Empieza en cien dólares.","h2":"En Massachusetts, no detenerse ante un peatón ciego con bastón blanco o perro guía puede costar una multa de $100 a $500.","p":"¡Correcto! De $100 a $500."},"ref":{"doc":"MA","page":null}},{"id":"ma-146","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, besides an all-white cane, which cane color tells drivers a pedestrian is blind or partly blind?","o":["Yellow with black stripes","White with a red tip","Orange","Blue with a white tip"],"h1":"The colors are white and red.","h2":"In Massachusetts, a cane that is white, or white tipped with red, held up by a pedestrian shows the person is blind or partly blind.","p":"Right! White tipped with red."},"es":{"q":"En Massachusetts, además del bastón completamente blanco, ¿qué color de bastón indica que un peatón es ciego o casi ciego?","o":["Amarillo con rayas negras","Blanco con la punta roja","Anaranjado","Azul con la punta blanca"],"h1":"Los colores son blanco y rojo.","h2":"En Massachusetts, un bastón blanco, o blanco con la punta roja, levantado por un peatón indica que la persona es ciega o casi ciega.","p":"¡Correcto! Blanco con la punta roja."},"ref":{"doc":"MA","page":null}},{"id":"ma-147","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, at a marked crosswalk with no signal, a pedestrian is on the other half of the road. When must you yield?","o":["Only once they reach your lane","Only if they wave at you","When they are within 10 feet of your half of the road","Never; they must wait"],"h1":"You must stop before they actually reach your side.","h2":"In Massachusetts, you must yield to a pedestrian in a marked crosswalk who is on your half of the road or within 10 feet of it.","p":"Correct! Yield when they are within 10 feet of your half."},"es":{"q":"En Massachusetts, en un cruce peatonal marcado sin semáforo, un peatón está en la otra mitad de la calle. ¿Cuándo debes cederle el paso?","o":["Solo cuando llegue a tu carril","Solo si te hace señas","Cuando esté a 10 pies o menos de tu mitad de la calle","Nunca; debe esperar"],"h1":"Debes parar antes de que llegue a tu lado.","h2":"En Massachusetts, debes ceder el paso a un peatón en un cruce marcado que está en tu mitad de la calle o a 10 pies o menos de ella.","p":"¡Correcto! Cede el paso cuando esté a 10 pies o menos de tu mitad."},"ref":{"doc":"MA","page":null}},{"id":"ma-148","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the highest fine for not yielding to a pedestrian in a marked crosswalk?","o":["$20","$50","$1,000","$200"],"h1":"It is a couple of hundred dollars.","h2":"In Massachusetts, failing to yield to a pedestrian in a marked crosswalk can bring a fine of up to $200.","p":"Right! Up to $200."},"es":{"q":"En Massachusetts, ¿cuál es la multa más alta por no ceder el paso a un peatón en un cruce peatonal marcado?","o":["$20","$50","$1,000","$200"],"h1":"Son un par de cientos de dólares.","h2":"En Massachusetts, no ceder el paso a un peatón en un cruce peatonal marcado puede costar una multa de hasta $200.","p":"¡Correcto! Hasta $200."},"ref":{"doc":"MA","page":null}},{"id":"ma-149","scope":"MA","cat":"signals","sign":null,"c":0,"en":{"q":"In Massachusetts, you are stopped at a red light on a one-way street. When may you turn left on red?","o":["When turning onto another one-way street, after stopping and yielding, if no sign forbids it","Never; left on red is always illegal","Whenever no cars are coming","Only if a green arrow is showing"],"h1":"Left on red works only between two specific kinds of streets.","h2":"In Massachusetts, after a full stop, you may turn left on red from a one-way street onto another one-way street, yielding to people and traffic, unless a sign forbids it.","p":"Correct! One-way onto one-way, after a stop."},"es":{"q":"En Massachusetts, estás detenido en un semáforo en rojo en una calle de un solo sentido. ¿Cuándo puedes girar a la izquierda en rojo?","o":["Al girar hacia otra calle de un solo sentido, después de parar y ceder el paso, si ninguna señal lo prohíbe","Nunca; girar a la izquierda en rojo siempre es ilegal","Siempre que no vengan autos","Solo si hay una flecha verde"],"h1":"Girar a la izquierda en rojo solo vale entre dos tipos de calles.","h2":"En Massachusetts, después de parar por completo, puedes girar a la izquierda en rojo desde una calle de un solo sentido hacia otra de un solo sentido, cediendo el paso a peatones y tráfico, salvo que una señal lo prohíba.","p":"¡Correcto! De un solo sentido a un solo sentido, después de parar."},"ref":{"doc":"MA","page":null}},{"id":"ma-150","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, your light is green, but traffic is backed up past the intersection. What does the law say?","o":["Go, because green means go","Enter halfway and wait","Do not enter; a green light is no excuse for blocking it","Honk until cars move"],"h1":"You must be able to get all the way through.","h2":"In Massachusetts, you may not enter an intersection you cannot get through; a green light is no defense, and you must wait for another signal cycle if needed.","p":"Correct! Wait until you can clear it."},"es":{"q":"En Massachusetts, tu semáforo está en verde, pero el tráfico está detenido más allá de la intersección. ¿Qué dice la ley?","o":["Avanza, porque verde significa avanzar","Entra hasta la mitad y espera","No entres; la luz verde no es excusa para bloquearla","Toca la bocina hasta que se muevan"],"h1":"Debes poder pasar por completo.","h2":"En Massachusetts, no puedes entrar a una intersección que no puedes cruzar; la luz verde no es defensa, y debes esperar otro ciclo del semáforo si hace falta.","p":"¡Correcto! Espera hasta poder cruzarla."},"ref":{"doc":"MA","page":null}},{"id":"ma-151","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, you drive past a yield sign without stopping and hit a car in the intersection. How does the law view this?","o":["As evidence that you failed to yield","As the other driver's fault","As no one's fault","As a matter only for insurance"],"h1":"The crash itself says something about what you did.","h2":"In Massachusetts, a collision after driving past a yield sign without stopping is treated as evidence that you failed to yield the right-of-way.","p":"Correct! It counts as evidence you failed to yield."},"es":{"q":"En Massachusetts, pasas una señal de ceda el paso sin detenerte y chocas un auto en la intersección. ¿Cómo lo ve la ley?","o":["Como prueba de que no cediste el paso","Como culpa del otro conductor","Como culpa de nadie","Como un asunto solo del seguro"],"h1":"El choque mismo dice algo de lo que hiciste.","h2":"En Massachusetts, un choque después de pasar una señal de ceda el paso sin detenerte se toma como prueba de que no cediste el derecho de paso.","p":"¡Correcto! Cuenta como prueba de que no cediste el paso."},"ref":{"doc":"MA","page":null}},{"id":"ma-152","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, fire hoses are lying across the street. When may you drive over them?","o":["Whenever you go slowly","Only with consent from a firefighter","Only if the fire is out","Only in a small car"],"h1":"Firefighters are in charge of their equipment.","h2":"In Massachusetts, you may not drive over a fire department hose without the consent of a member of the fire department.","p":"Right! Only with a firefighter's consent."},"es":{"q":"En Massachusetts, hay mangueras de bomberos atravesadas en la calle. ¿Cuándo puedes pasar por encima de ellas?","o":["Siempre que vayas despacio","Solo con permiso de un bombero","Solo si el fuego ya se apagó","Solo en un auto pequeño"],"h1":"Los bomberos están a cargo de su equipo.","h2":"En Massachusetts, no puedes pasar con tu vehículo sobre una manguera de bomberos sin permiso de un miembro del departamento de bomberos.","p":"¡Correcto! Solo con permiso de un bombero."},"ref":{"doc":"MA","page":null}},{"id":"ma-153","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, how close to a fire may you drive or park your vehicle?","o":["100 feet","300 feet","800 feet","50 feet"],"h1":"It is the length of several city blocks.","h2":"In Massachusetts, you may not drive or park within 800 feet of a fire.","p":"Correct! Stay at least 800 feet away."},"es":{"q":"En Massachusetts, ¿a qué distancia de un incendio puedes manejar o estacionar tu vehículo?","o":["100 pies","300 pies","800 pies","50 pies"],"h1":"Es el largo de varias cuadras.","h2":"En Massachusetts, no puedes manejar ni estacionar a menos de 800 pies de un incendio.","p":"¡Correcto! Mantente al menos a 800 pies."},"ref":{"doc":"MA","page":null}},{"id":"ma-154","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, besides police cars, fire trucks and ambulances, which stopped vehicles with flashing lights does the Move Over law protect?","o":["Only school buses","Only state police cars","Mail trucks","Highway maintenance vehicles and tow trucks"],"h1":"It also covers workers who fix roads and help broken-down cars.","h2":"In Massachusetts, the Move Over law also covers stopped highway maintenance vehicles and recovery vehicles such as tow trucks with flashing lights.","p":"Right! Road maintenance vehicles and tow trucks too."},"es":{"q":"En Massachusetts, además de patrullas, camiones de bomberos y ambulancias, ¿qué vehículos detenidos con luces intermitentes protege la ley Move Over?","o":["Solo autobuses escolares","Solo patrullas estatales","Camiones del correo","Vehículos de mantenimiento vial y grúas"],"h1":"También cubre a quienes arreglan caminos y ayudan a autos descompuestos.","h2":"En Massachusetts, la ley Move Over también cubre vehículos de mantenimiento vial y vehículos de rescate, como grúas, detenidos con luces intermitentes.","p":"¡Correcto! También vehículos de mantenimiento vial y grúas."},"ref":{"doc":"MA","page":null}},{"id":"ma-155","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the lowest fine for a first offense of passing a stopped school bus with flashing red lights?","o":["$100","$250","$50","$2,000"],"h1":"It is a few hundred dollars.","h2":"In Massachusetts, passing a stopped school bus with flashing red lights brings a fine of at least $250 for a first offense.","p":"Right! At least $250."},"es":{"q":"En Massachusetts, ¿cuál es la multa más baja por una primera vez de rebasar un autobús escolar detenido con luces rojas intermitentes?","o":["$100","$250","$50","$2,000"],"h1":"Son unos cientos de dólares.","h2":"En Massachusetts, rebasar un autobús escolar detenido con luces rojas intermitentes trae una multa de al menos $250 en una primera infracción.","p":"¡Correcto! Al menos $250."},"ref":{"doc":"MA","page":null}},{"id":"ma-156","scope":"MA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Massachusetts, a driver is convicted a second time of passing a stopped school bus. What happens to the license?","o":["Nothing changes","It gets a warning mark","It is revoked, with no new license for 6 months","It is suspended for 7 days"],"h1":"A second conviction costs you the license for half a year.","h2":"In Massachusetts, a second conviction for passing a stopped school bus means the license is revoked, with no new license for six months, plus a $500 to $1,000 fine.","p":"Correct! Revoked for six months."},"es":{"q":"En Massachusetts, a un conductor lo condenan por segunda vez por rebasar un autobús escolar detenido. ¿Qué pasa con la licencia?","o":["No cambia nada","Le ponen una marca de advertencia","Se revoca, sin nueva licencia por 6 meses","Se suspende por 7 días"],"h1":"Una segunda condena te deja sin licencia medio año.","h2":"En Massachusetts, una segunda condena por rebasar un autobús escolar detenido significa que la licencia se revoca, sin nueva licencia por seis meses, más una multa de $500 a $1,000.","p":"¡Correcto! Se revoca por seis meses."},"ref":{"doc":"MA","page":null}},{"id":"ma-157","scope":"MA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Massachusetts, red lights are flashing at a railroad crossing. What is the farthest from the nearest rail you may stop?","o":["100 feet","15 feet","10 feet","50 feet"],"h1":"You must stop between 15 feet and this distance.","h2":"In Massachusetts, you must stop no less than 15 feet and no more than 50 feet from the nearest rail when crossing lights flash.","p":"Right! Between 15 and 50 feet from the nearest rail."},"es":{"q":"En Massachusetts, hay luces rojas intermitentes en un cruce de ferrocarril. ¿A qué distancia máxima del riel más cercano puedes detenerte?","o":["100 pies","15 pies","10 pies","50 pies"],"h1":"Debes detenerte entre 15 pies y esta distancia.","h2":"En Massachusetts, debes detenerte a no menos de 15 pies y no más de 50 pies del riel más cercano cuando las luces del cruce parpadean.","p":"¡Correcto! Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"MA","page":null}},{"id":"ma-158","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, which vehicles must always stop at a railroad crossing, even with no train signals on?","o":["School buses and vehicles carrying explosives or flammable liquids","All pickup trucks","Motorcycles","Cars towing trailers"],"h1":"Think of vehicles carrying children or dangerous cargo.","h2":"In Massachusetts, school buses and vehicles carrying explosives or flammable liquids must always stop 15 to 50 feet before a railroad crossing.","p":"Correct! School buses and hazardous cargo vehicles always stop."},"es":{"q":"En Massachusetts, ¿qué vehículos deben detenerse siempre en un cruce de ferrocarril, aunque no haya señales de tren encendidas?","o":["Autobuses escolares y vehículos con explosivos o líquidos inflamables","Todas las camionetas pickup","Motocicletas","Autos que remolcan un tráiler"],"h1":"Piensa en vehículos que llevan niños o carga peligrosa.","h2":"En Massachusetts, los autobuses escolares y los vehículos con explosivos o líquidos inflamables deben detenerse siempre de 15 a 50 pies antes de un cruce de ferrocarril.","p":"¡Correcto! Los autobuses escolares y los de carga peligrosa siempre se detienen."},"ref":{"doc":"MA","page":null}},{"id":"ma-159","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, what fine can a car driver get for breaking the railroad crossing rules?","o":["$10 to $20","$100 to $200","$1,000 to $2,000","$5,000"],"h1":"It is a few hundred dollars at most, or community service.","h2":"In Massachusetts, a car driver who breaks the railroad crossing rules can be fined $100 to $200 or ordered to do 50 hours of community service.","p":"Right! $100 to $200, or community service."},"es":{"q":"En Massachusetts, ¿qué multa puede recibir un conductor de auto por violar las reglas del cruce de ferrocarril?","o":["De $10 a $20","De $100 a $200","De $1,000 a $2,000","$5,000"],"h1":"Son unos cientos de dólares como máximo, o servicio comunitario.","h2":"En Massachusetts, un conductor de auto que viola las reglas del cruce de ferrocarril puede recibir una multa de $100 a $200 o 50 horas de servicio comunitario.","p":"¡Correcto! De $100 a $200, o servicio comunitario."},"ref":{"doc":"MA","page":null}},{"id":"ma-160","scope":"MA","cat":"signals","sign":null,"c":3,"en":{"q":"In Massachusetts, between which times must your headlights be on?","o":["From sunset to sunrise exactly","From 8 p.m. to 6 a.m.","Only when it is fully dark","From half an hour after sunset to half an hour before sunrise"],"h1":"There is a half-hour margin on each end.","h2":"In Massachusetts, headlights and taillights must be on from half an hour after sunset to half an hour before sunrise.","p":"Right! Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Massachusetts, ¿entre qué horas deben estar encendidas tus luces delanteras?","o":["Exactamente de la puesta a la salida del sol","De 8 p.m. a 6 a.m.","Solo cuando está completamente oscuro","De media hora después de la puesta del sol a media hora antes de la salida del sol"],"h1":"Hay un margen de media hora en cada extremo.","h2":"En Massachusetts, las luces delanteras y traseras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"¡Correcto! De media hora después de la puesta a media hora antes de la salida del sol."},"ref":{"doc":"MA","page":null}},{"id":"ma-161","scope":"MA","cat":"signals","sign":null,"c":0,"en":{"q":"In Massachusetts, in daytime fog, you must turn on your headlights when you cannot clearly see people or vehicles at what distance?","o":["500 feet","50 feet","100 feet","1 mile"],"h1":"It is the same distance used for dimming high beams.","h2":"In Massachusetts, you must turn on your headlights whenever poor light or weather keeps you from clearly seeing people or vehicles 500 feet away.","p":"Correct! When you cannot see clearly at 500 feet."},"es":{"q":"En Massachusetts, con neblina de día, debes encender las luces delanteras cuando no puedes ver claramente a personas o vehículos a ¿qué distancia?","o":["500 pies","50 pies","100 pies","1 milla"],"h1":"Es la misma distancia que se usa para bajar las luces altas.","h2":"En Massachusetts, debes encender las luces delanteras siempre que la poca luz o el clima no te dejen ver claramente a personas o vehículos a 500 pies.","p":"¡Correcto! Cuando no ves claramente a 500 pies."},"ref":{"doc":"MA","page":null}},{"id":"ma-162","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, how much light must tinted side and rear windows let through at minimum?","o":["10 percent","35 percent","70 percent","5 percent"],"h1":"It is about one third.","h2":"In Massachusetts, window tint on side and rear windows must let at least 35 percent of visible light through.","p":"Right! At least 35 percent."},"es":{"q":"En Massachusetts, ¿cuánta luz deben dejar pasar como mínimo las ventanas laterales y trasera polarizadas?","o":["10 por ciento","35 por ciento","70 por ciento","5 por ciento"],"h1":"Es más o menos un tercio.","h2":"En Massachusetts, el polarizado de las ventanas laterales y trasera debe dejar pasar al menos el 35 por ciento de la luz visible.","p":"¡Correcto! Al menos el 35 por ciento."},"ref":{"doc":"MA","page":null}},{"id":"ma-163","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, how much of the windshield may have a tinted strip?","o":["The whole windshield","The bottom half","Only the top 6 inches","The top 12 inches"],"h1":"It is a narrow band at the very top.","h2":"In Massachusetts, a tinted strip is allowed only along the top 6 inches of the windshield, and it may not block the driver's forward view.","p":"Correct! Only the top 6 inches."},"es":{"q":"En Massachusetts, ¿qué parte del parabrisas puede tener una franja polarizada?","o":["Todo el parabrisas","La mitad de abajo","Solo las 6 pulgadas de arriba","Las 12 pulgadas de arriba"],"h1":"Es una franja angosta en la parte más alta.","h2":"En Massachusetts, solo se permite una franja polarizada en las 6 pulgadas de arriba del parabrisas, y no puede tapar la vista hacia el frente del conductor.","p":"¡Correcto! Solo las 6 pulgadas de arriba."},"ref":{"doc":"MA","page":null}},{"id":"ma-164","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, what is the highest fine for illegal window tint?","o":["$25","$50","$5,000","$250"],"h1":"It is a few hundred dollars.","h2":"In Massachusetts, illegal window tint can bring a fine of up to $250, and a third conviction can lead to a license suspension of up to 90 days.","p":"Right! Up to $250."},"es":{"q":"En Massachusetts, ¿cuál es la multa más alta por polarizado ilegal en las ventanas?","o":["$25","$50","$5,000","$250"],"h1":"Son unos cientos de dólares.","h2":"En Massachusetts, el polarizado ilegal puede costar una multa de hasta $250, y una tercera condena puede llevar a una suspensión de la licencia de hasta 90 días.","p":"¡Correcto! Hasta $250."},"ref":{"doc":"MA","page":null}},{"id":"ma-165","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, in daylight, your load sticks out 4 feet or more past the back of your vehicle. What must you put at its end?","o":["A red flag at least 12 inches square","A white rag","A yellow light","Nothing in daylight"],"h1":"At night it would be a red light instead.","h2":"In Massachusetts, a load that extends 4 feet or more beyond the vehicle must show a red flag at least 12 inches square at its end in daylight.","p":"Correct! A red flag at least 12 inches square."},"es":{"q":"En Massachusetts, de día, tu carga sobresale 4 pies o más por detrás del vehículo. ¿Qué debes poner en su extremo?","o":["Una bandera roja de al menos 12 pulgadas por lado","Un trapo blanco","Una luz amarilla","Nada de día"],"h1":"De noche sería una luz roja.","h2":"En Massachusetts, una carga que sobresale 4 pies o más del vehículo debe llevar de día una bandera roja de al menos 12 pulgadas por lado en su extremo.","p":"¡Correcto! Una bandera roja de al menos 12 pulgadas por lado."},"ref":{"doc":"MA","page":null}},{"id":"ma-166","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, at night, a load sticks out 4 feet or more past your vehicle. What must mark its end?","o":["A white reflector","A red light visible from 500 feet","A red flag only","An orange cone"],"h1":"It must be visible from far away at the sides and rear.","h2":"In Massachusetts, at night a load extending 4 feet or more must show a red light at its end, visible from at least 500 feet to the sides and rear.","p":"Right! A red light visible from 500 feet."},"es":{"q":"En Massachusetts, de noche, una carga sobresale 4 pies o más de tu vehículo. ¿Qué debe marcar su extremo?","o":["Un reflector blanco","Una luz roja visible desde 500 pies","Solo una bandera roja","Un cono anaranjado"],"h1":"Debe verse desde lejos por los lados y por detrás.","h2":"En Massachusetts, de noche una carga que sobresale 4 pies o más debe llevar una luz roja en su extremo, visible desde al menos 500 pies por los lados y por detrás.","p":"¡Correcto! Una luz roja visible desde 500 pies."},"ref":{"doc":"MA","page":null}},{"id":"ma-167","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, when may you use your hazard warning flashers?","o":["Whenever you drive in rain","When parking illegally for a minute","When your vehicle is disabled or stopped in an emergency","When driving slowly in traffic"],"h1":"They are for a vehicle that cannot move normally.","h2":"In Massachusetts, hazard flashers are to be used only when the vehicle is disabled or stopped in an emergency on or beside the road.","p":"Correct! Only when disabled or stopped in an emergency."},"es":{"q":"En Massachusetts, ¿cuándo puedes usar las luces intermitentes de emergencia?","o":["Siempre que manejes con lluvia","Al estacionarte mal por un minuto","Cuando tu vehículo está descompuesto o detenido por una emergencia","Al manejar despacio en el tráfico"],"h1":"Son para un vehículo que no puede moverse normalmente.","h2":"En Massachusetts, las luces intermitentes de emergencia se usan solo cuando el vehículo está descompuesto o detenido por una emergencia en la calle o a un lado.","p":"¡Correcto! Solo cuando está descompuesto o detenido por una emergencia."},"ref":{"doc":"MA","page":null}},{"id":"ma-168","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, who on a motorcycle must wear a helmet?","o":["Only riders under 18","Only the operator","Only passengers","The operator and every passenger"],"h1":"Massachusetts does not make an age exception for regular riding.","h2":"In Massachusetts, every motorcycle operator and every passenger must wear an approved helmet.","p":"Right! Everyone on the motorcycle wears a helmet."},"es":{"q":"En Massachusetts, ¿quién debe usar casco en una motocicleta?","o":["Solo los menores de 18","Solo el conductor","Solo los pasajeros","El conductor y todos los pasajeros"],"h1":"Massachusetts no hace excepción por edad al andar normalmente.","h2":"En Massachusetts, todo conductor de motocicleta y todo pasajero deben usar un casco aprobado.","p":"¡Correcto! Todos en la motocicleta usan casco."},"ref":{"doc":"MA","page":null}},{"id":"ma-169","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, a motorcycle has no windshield. What must the rider wear?","o":["Glasses, goggles or a face shield","A reflective vest","Leather gloves","Nothing extra"],"h1":"Wind, bugs and stones can hit your eyes.","h2":"In Massachusetts, a rider on a motorcycle without a windshield must wear glasses, goggles or a protective face shield.","p":"Correct! Eye protection is required."},"es":{"q":"En Massachusetts, una motocicleta no tiene parabrisas. ¿Qué debe usar el conductor?","o":["Lentes, gafas protectoras o careta","Un chaleco reflectante","Guantes de cuero","Nada extra"],"h1":"El viento, los insectos y las piedras pueden darte en los ojos.","h2":"En Massachusetts, quien maneja una motocicleta sin parabrisas debe usar lentes, gafas protectoras o una careta protectora.","p":"¡Correcto! Se requiere protección para los ojos."},"ref":{"doc":"MA","page":null}},{"id":"ma-170","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, where may a passenger ride on a motorcycle built for two?","o":["In front of the operator","On a proper seat behind the operator, with footrests","Sideways on the gas tank","Standing on the footrests"],"h1":"The passenger never sits ahead of the rider.","h2":"In Massachusetts, a motorcycle passenger must ride on a seat meant for a passenger, behind the operator or in a sidecar, and never in front of the operator.","p":"Right! Behind the operator, on a proper seat."},"es":{"q":"En Massachusetts, ¿dónde puede ir un pasajero en una motocicleta hecha para dos?","o":["Delante del conductor","En un asiento adecuado detrás del conductor, con reposapiés","De lado sobre el tanque","De pie sobre los reposapiés"],"h1":"El pasajero nunca va delante del conductor.","h2":"En Massachusetts, el pasajero de una motocicleta debe ir en un asiento para pasajero, detrás del conductor o en un sidecar, y nunca delante del conductor.","p":"¡Correcto! Detrás del conductor, en un asiento adecuado."},"ref":{"doc":"MA","page":null}},{"id":"ma-171","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, besides the hitch, what must hold a trailer (other than a semi-trailer) to the towing vehicle?","o":["Rope","A bungee cord","Safety chains","Nothing else"],"h1":"They keep the trailer attached if the hitch fails.","h2":"In Massachusetts, a trailer must be fastened to the towing vehicle with safety chains in addition to the regular hitch.","p":"Correct! Safety chains are required."},"es":{"q":"En Massachusetts, además del enganche, ¿qué debe sujetar un tráiler (que no sea semirremolque) al vehículo que lo remolca?","o":["Una cuerda","Un pulpo elástico","Cadenas de seguridad","Nada más"],"h1":"Mantienen el tráiler unido si el enganche falla.","h2":"En Massachusetts, un tráiler debe ir sujeto al vehículo que lo remolca con cadenas de seguridad además del enganche normal.","p":"¡Correcto! Se requieren cadenas de seguridad."},"ref":{"doc":"MA","page":null}},{"id":"ma-172","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, during which months are studded snow tires NOT allowed on public roads?","o":["December 1 to March 1","All year","January only","May 1 to November 1"],"h1":"They are allowed only in the cold half of the year.","h2":"In Massachusetts, metal-studded tires may not be used on public roads between May 1 and November 1, unless the RMV allows earlier use because of weather.","p":"Right! Not from May 1 to November 1."},"es":{"q":"En Massachusetts, ¿en qué meses NO se permiten las llantas con clavos en las vías públicas?","o":["Del 1 de diciembre al 1 de marzo","Todo el año","Solo en enero","Del 1 de mayo al 1 de noviembre"],"h1":"Solo se permiten en la mitad fría del año.","h2":"En Massachusetts, las llantas con clavos de metal no se pueden usar en vías públicas entre el 1 de mayo y el 1 de noviembre, salvo que el RMV permita usarlas antes por el clima.","p":"¡Correcto! No del 1 de mayo al 1 de noviembre."},"ref":{"doc":"MA","page":null}},{"id":"ma-173","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the fine for driving without a valid inspection sticker?","o":["$10","$50","$500","$1,000"],"h1":"It is less than $100.","h2":"In Massachusetts, driving a vehicle without the required inspection sticker brings a $50 fine.","p":"Right! The fine is $50."},"es":{"q":"En Massachusetts, ¿cuál es la multa por manejar sin una calcomanía de inspección válida?","o":["$10","$50","$500","$1,000"],"h1":"Es menos de $100.","h2":"En Massachusetts, manejar un vehículo sin la calcomanía de inspección requerida trae una multa de $50.","p":"¡Correcto! La multa es de $50."},"ref":{"doc":"MA","page":null}},{"id":"ma-174","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, where must a car show its license plates when the RMV issues two plates?","o":["Only on the back","Only on the front","On the dashboard","One on the front and one on the back"],"h1":"Both ends of the car need one.","h2":"In Massachusetts, when two plates are issued, one must be on the front and one on the back of the vehicle.","p":"Right! Front and back."},"es":{"q":"En Massachusetts, ¿dónde debe llevar un auto sus placas cuando el RMV entrega dos?","o":["Solo atrás","Solo adelante","En el tablero","Una adelante y otra atrás"],"h1":"Los dos extremos del auto llevan una.","h2":"En Massachusetts, cuando se entregan dos placas, una debe ir adelante y otra atrás del vehículo.","p":"¡Correcto! Adelante y atrás."},"ref":{"doc":"MA","page":null}},{"id":"ma-175","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, before you walk away from your parked car on a street, what must you do?","o":["Leave it running if you are quick","Lock the doors only","Stop the engine, set the brake and take the key","Turn on the hazard lights"],"h1":"An unattended car must not be able to move or be driven off.","h2":"In Massachusetts, before leaving a vehicle unattended on a way, you must stop the engine, set the brakes and remove the key.","p":"Correct! Engine off, brake set, key out."},"es":{"q":"En Massachusetts, antes de alejarte de tu auto estacionado en la calle, ¿qué debes hacer?","o":["Dejarlo encendido si vuelves rápido","Solo cerrar las puertas","Apagar el motor, poner el freno y sacar la llave","Poner las luces intermitentes"],"h1":"Un auto solo no debe poder moverse ni ser manejado.","h2":"En Massachusetts, antes de dejar un vehículo solo en la calle, debes apagar el motor, poner los frenos y sacar la llave.","p":"¡Correcto! Motor apagado, freno puesto, llave fuera."},"ref":{"doc":"MA","page":null}},{"id":"ma-176","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, children under 12 are riding in the open bed of a pickup truck. What does the law allow?","o":["Any speed on back roads","Up to 25 mph for any distance","Unlimited driving if they sit down","No more than 5 mph if you go farther than 5 miles"],"h1":"The numbers 5 and 5 are the key.","h2":"In Massachusetts, you may not drive more than 5 miles at more than 5 mph with children under 12 in the bed of a pickup, except in a parade or with farm or owner-repair plates.","p":"Right! Over 5 miles, no faster than 5 mph."},"es":{"q":"En Massachusetts, niños menores de 12 años van en la caja abierta de una camioneta pickup. ¿Qué permite la ley?","o":["Cualquier velocidad en caminos rurales","Hasta 25 mph a cualquier distancia","Manejar sin límite si van sentados","No más de 5 mph si vas a más de 5 millas"],"h1":"Los números 5 y 5 son la clave.","h2":"En Massachusetts, no puedes manejar más de 5 millas a más de 5 mph con niños menores de 12 años en la caja de una pickup, salvo en un desfile o con placas de granja o de reparación.","p":"¡Correcto! Más de 5 millas, no más rápido de 5 mph."},"ref":{"doc":"MA","page":null}},{"id":"ma-177","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, may a person ride inside a camper trailer while it is being towed?","o":["No, people may not ride in a moving trailer","Yes, if they wear a seat belt","Yes, on short trips","Yes, if they are adults"],"h1":"A towed trailer is not built to protect riders.","h2":"In Massachusetts, no one may ride in a trailer or semi-trailer while it is being towed or moving, except firefighters on duty or people with special permission.","p":"Correct! No riding in a moving trailer."},"es":{"q":"En Massachusetts, ¿puede una persona ir dentro de un tráiler-casa mientras lo remolcan?","o":["No, nadie puede ir en un tráiler en movimiento","Sí, si usa cinturón","Sí, en viajes cortos","Sí, si son adultos"],"h1":"Un tráiler remolcado no está hecho para proteger a quien va adentro.","h2":"En Massachusetts, nadie puede ir en un tráiler o semirremolque mientras lo remolcan o está en movimiento, salvo bomberos en servicio o personas con permiso especial.","p":"¡Correcto! Nadie va en un tráiler en movimiento."},"ref":{"doc":"MA","page":null}},{"id":"ma-178","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, can police stop you just for not wearing a seat belt?","o":["Yes, any time","No, only if they stopped you for another violation","Only on highways","Only at night"],"h1":"Seat belt tickets come along with another reason for the stop.","h2":"In Massachusetts, the seat belt law is enforced only when a driver has been stopped for another motor vehicle violation or offense.","p":"Right! Only with another violation."},"es":{"q":"En Massachusetts, ¿puede la policía detenerte solo por no usar el cinturón de seguridad?","o":["Sí, en cualquier momento","No, solo si te detuvo por otra infracción","Solo en autopistas","Solo de noche"],"h1":"La multa por cinturón viene junto con otro motivo para detenerte.","h2":"En Massachusetts, la ley del cinturón de seguridad solo se aplica cuando al conductor lo detuvieron por otra infracción de tránsito u otro delito.","p":"¡Correcto! Solo junto con otra infracción."},"ref":{"doc":"MA","page":null}},{"id":"ma-179","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, a 14-year-old passenger is not wearing a seat belt. What happens to the driver?","o":["Nothing","A warning","A $100 fine","An extra $25 fine"],"h1":"The driver answers for unbelted passengers aged 12 to 15.","h2":"In Massachusetts, the driver gets an extra $25 fine for each passenger aged 12 to 15 who is not wearing a seat belt.","p":"Right! The driver pays an extra $25."},"es":{"q":"En Massachusetts, un pasajero de 14 años no usa el cinturón de seguridad. ¿Qué le pasa al conductor?","o":["Nada","Una advertencia","Una multa de $100","Una multa adicional de $25"],"h1":"El conductor responde por los pasajeros de 12 a 15 años sin cinturón.","h2":"En Massachusetts, el conductor recibe una multa adicional de $25 por cada pasajero de 12 a 15 años que no usa el cinturón de seguridad.","p":"¡Correcto! El conductor paga $25 más."},"ref":{"doc":"MA","page":null}},{"id":"ma-180","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, a child has outgrown the child safety seat but is under 13. What must the child use?","o":["A properly adjusted seat belt","Nothing, if in the back seat","A pillow under the lap belt","The front seat air bag"],"h1":"Once out of the child seat, the next step is the regular belt.","h2":"In Massachusetts, a passenger under 13 who does not need a child safety seat must wear a properly adjusted and fastened seat belt.","p":"Correct! A properly adjusted seat belt."},"es":{"q":"En Massachusetts, un niño ya no necesita asiento de seguridad infantil, pero tiene menos de 13 años. ¿Qué debe usar?","o":["Un cinturón de seguridad bien ajustado","Nada, si va atrás","Una almohada bajo el cinturón","La bolsa de aire del asiento delantero"],"h1":"Después del asiento infantil, el siguiente paso es el cinturón normal.","h2":"En Massachusetts, un pasajero menor de 13 años que no necesita asiento infantil debe usar el cinturón de seguridad bien ajustado y abrochado.","p":"¡Correcto! Un cinturón de seguridad bien ajustado."},"ref":{"doc":"MA","page":null}},{"id":"ma-181","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the highest fine for a driver whose young child is not in a required child safety seat?","o":["$5","$25","$250","$500"],"h1":"It is the same as the seat belt fine.","h2":"In Massachusetts, a driver who does not secure a child as the child passenger law requires can be fined up to $25.","p":"Right! Up to $25."},"es":{"q":"En Massachusetts, ¿cuál es la multa más alta para un conductor cuyo niño pequeño no va en el asiento de seguridad requerido?","o":["$5","$25","$250","$500"],"h1":"Es igual a la multa por cinturón.","h2":"En Massachusetts, el conductor que no asegura a un niño como lo pide la ley de pasajeros infantiles puede recibir una multa de hasta $25.","p":"¡Correcto! Hasta $25."},"ref":{"doc":"MA","page":null}},{"id":"ma-182","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the highest fine for a first offense of idling your engine for more than 5 minutes?","o":["$10","$25","$100","$500"],"h1":"Later offenses can cost up to $500.","h2":"In Massachusetts, unnecessary idling for more than 5 minutes can bring a fine of up to $100 for a first offense and up to $500 after that.","p":"Correct! Up to $100 the first time."},"es":{"q":"En Massachusetts, ¿cuál es la multa más alta por una primera vez de dejar el motor encendido sin moverse por más de 5 minutos?","o":["$10","$25","$100","$500"],"h1":"Las siguientes veces pueden costar hasta $500.","h2":"En Massachusetts, dejar el motor encendido sin necesidad por más de 5 minutos puede costar hasta $100 la primera vez y hasta $500 después.","p":"¡Correcto! Hasta $100 la primera vez."},"ref":{"doc":"MA","page":null}},{"id":"ma-183","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, the anti-idling rule for school grounds also covers the area within how many feet of a school?","o":["10 feet","500 feet","1,000 feet","100 feet"],"h1":"It reaches past the property line by about a third of a football field.","h2":"In Massachusetts, school grounds for the idling law include the school property and the area within 100 feet of it.","p":"Right! Within 100 feet of the school."},"es":{"q":"En Massachusetts, la regla contra dejar el motor encendido en terrenos escolares también cubre el área a cuántos pies de una escuela?","o":["10 pies","500 pies","1,000 pies","100 pies"],"h1":"Llega más allá del terreno, como un tercio de una cancha de fútbol americano.","h2":"En Massachusetts, para la ley contra dejar el motor encendido, los terrenos escolares incluyen la propiedad de la escuela y el área a 100 pies o menos de ella.","p":"¡Correcto! Hasta 100 pies de la escuela."},"ref":{"doc":"MA","page":null}},{"id":"ma-184","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what do you need to ride a moped (motorized bicycle) on a public road?","o":["Nothing; anyone may ride one","A valid driver's license or learner's permit","Only a bicycle helmet","A motorcycle license"],"h1":"Mopeds are not just bicycles under the law.","h2":"In Massachusetts, you must be at least 16 and have a valid driver's license or learner's permit to ride a moped on a public road.","p":"Right! A license or learner's permit is required."},"es":{"q":"En Massachusetts, ¿qué necesitas para andar en un ciclomotor (bicicleta motorizada) en una vía pública?","o":["Nada; cualquiera puede usarlo","Una licencia de conducir o un permiso de aprendizaje válido","Solo un casco de bicicleta","Una licencia de motocicleta"],"h1":"Para la ley, los ciclomotores no son solo bicicletas.","h2":"En Massachusetts, debes tener al menos 16 años y una licencia de conducir o un permiso de aprendizaje válido para andar en ciclomotor en una vía pública.","p":"¡Correcto! Se requiere licencia o permiso de aprendizaje."},"ref":{"doc":"MA","page":null}},{"id":"ma-185","scope":"MA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Massachusetts, what is the top speed allowed for a moped (motorized bicycle)?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is a little slower than a typical town speed limit.","h2":"In Massachusetts, a moped may not be ridden faster than 25 mph.","p":"Correct! No faster than 25 mph."},"es":{"q":"En Massachusetts, ¿cuál es la velocidad máxima permitida para un ciclomotor (bicicleta motorizada)?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es un poco menos que un límite típico en un pueblo.","h2":"En Massachusetts, un ciclomotor no puede ir a más de 25 mph.","p":"¡Correcto! No más de 25 mph."},"ref":{"doc":"MA","page":null}},{"id":"ma-186","scope":"MA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Massachusetts, where may a moped (motorized bicycle) NOT be ridden?","o":["In a bike lane next to the road","On a city street","On a two-lane country road","On an off-street recreational bike path"],"h1":"Mopeds may use lanes beside traffic, but not separate paths.","h2":"In Massachusetts, mopeds may use bike lanes next to roads but may not be ridden on off-street recreational bicycle paths.","p":"Right! Not on off-street bike paths."},"es":{"q":"En Massachusetts, ¿dónde NO se puede andar en ciclomotor (bicicleta motorizada)?","o":["En un carril para bicicletas junto a la calle","En una calle de la ciudad","En un camino rural de dos carriles","En un sendero recreativo para bicicletas separado de la calle"],"h1":"Los ciclomotores pueden usar carriles junto al tráfico, pero no senderos separados.","h2":"En Massachusetts, los ciclomotores pueden usar carriles para bicicletas junto a las calles, pero no senderos recreativos para bicicletas separados de la calle.","p":"¡Correcto! No en senderos para bicicletas separados de la calle."},"ref":{"doc":"MA","page":null}},{"id":"ma-187","scope":"MA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Massachusetts, what is the top speed allowed for a motorized scooter on a public road?","o":["20 mph","10 mph","30 mph","40 mph"],"h1":"It is the same as the default school zone limit.","h2":"In Massachusetts, a motorized scooter may not be ridden faster than 20 mph.","p":"Correct! No faster than 20 mph."},"es":{"q":"En Massachusetts, ¿cuál es la velocidad máxima permitida para un scooter motorizado en una vía pública?","o":["20 mph","10 mph","30 mph","40 mph"],"h1":"Es igual al límite normal de una zona escolar.","h2":"En Massachusetts, un scooter motorizado no puede ir a más de 20 mph.","p":"¡Correcto! No más de 20 mph."},"ref":{"doc":"MA","page":null}},{"id":"ma-188","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, when may you ride a motorized scooter on a public road?","o":["Any time with a headlight","Only between sunrise and sunset","Only on weekends","Only after dark"],"h1":"Small scooters are hard to see at night.","h2":"In Massachusetts, a motorized scooter may not be ridden on a public road after sunset or before sunrise.","p":"Right! Only in daylight."},"es":{"q":"En Massachusetts, ¿cuándo puedes andar en scooter motorizado en una vía pública?","o":["A cualquier hora con luz delantera","Solo entre la salida y la puesta del sol","Solo los fines de semana","Solo de noche"],"h1":"Los scooters pequeños son difíciles de ver de noche.","h2":"En Massachusetts, no se puede andar en scooter motorizado en una vía pública después de la puesta del sol ni antes de la salida del sol.","p":"¡Correcto! Solo de día."},"ref":{"doc":"MA","page":null}},{"id":"ma-189","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, may a motorized scooter rider carry a passenger?","o":["Yes, one adult","Yes, a child under 12","No, passengers are not allowed","Yes, if both wear helmets"],"h1":"The scooter is for one person only.","h2":"In Massachusetts, a motorized scooter rider may not let anyone ride as a passenger.","p":"Correct! No passengers on a motorized scooter."},"es":{"q":"En Massachusetts, ¿puede quien anda en scooter motorizado llevar un pasajero?","o":["Sí, un adulto","Sí, un niño menor de 12","No, no se permiten pasajeros","Sí, si ambos usan casco"],"h1":"El scooter es para una sola persona.","h2":"En Massachusetts, quien anda en scooter motorizado no puede llevar a nadie como pasajero.","p":"¡Correcto! Nada de pasajeros en un scooter motorizado."},"ref":{"doc":"MA","page":null}},{"id":"ma-190","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, up to what age must bicycle riders and passengers wear a helmet?","o":["12 and under","14 and under","18 and under","16 and under"],"h1":"It covers riders up to the age when most teens can get a permit.","h2":"In Massachusetts, bicycle riders and passengers 16 years old or younger must wear a properly fitted, approved helmet.","p":"Right! Riders 16 and under."},"es":{"q":"En Massachusetts, ¿hasta qué edad deben usar casco quienes andan o van de pasajeros en bicicleta?","o":["12 años o menos","14 años o menos","18 años o menos","16 años o menos"],"h1":"Cubre hasta la edad en que la mayoría de los adolescentes puede sacar el permiso.","h2":"En Massachusetts, los ciclistas y pasajeros de bicicleta de 16 años o menos deben usar un casco aprobado y bien ajustado.","p":"¡Correcto! Ciclistas de 16 años o menos."},"ref":{"doc":"MA","page":null}},{"id":"ma-191","scope":"MA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Massachusetts, where may a bicyclist ride on the sidewalk?","o":["Outside business districts when needed for safety, unless a local rule forbids it","Anywhere at any time","Only downtown","Never"],"h1":"It depends on the area and on safety.","h2":"In Massachusetts, a bicyclist may ride on sidewalks outside business districts when needed for safety, unless local rules forbid it, and must yield to pedestrians.","p":"Correct! Outside business districts, when needed for safety."},"es":{"q":"En Massachusetts, ¿dónde puede un ciclista andar por la banqueta (acera)?","o":["Fuera de zonas comerciales cuando sea necesario por seguridad, salvo que una regla local lo prohíba","En cualquier lugar y momento","Solo en el centro","Nunca"],"h1":"Depende de la zona y de la seguridad.","h2":"En Massachusetts, un ciclista puede andar por la acera fuera de zonas comerciales cuando sea necesario por seguridad, salvo que las reglas locales lo prohíban, y debe ceder el paso a los peatones.","p":"¡Correcto! Fuera de zonas comerciales, cuando sea necesario por seguridad."},"ref":{"doc":"MA","page":null}},{"id":"ma-192","scope":"MA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Massachusetts, a bicyclist on a sidewalk comes up behind a person walking. What must the cyclist do?","o":["Ride into the street without looking","Give an audible signal before passing and yield","Ring a siren","Pass silently and fast"],"h1":"Let the walker know you are there.","h2":"In Massachusetts, a bicyclist on a sidewalk must yield to pedestrians and give an audible signal before passing them.","p":"Right! Give a sound and yield."},"es":{"q":"En Massachusetts, un ciclista en la acera se acerca por detrás a una persona que camina. ¿Qué debe hacer el ciclista?","o":["Bajarse a la calle sin mirar","Dar una señal que se oiga antes de pasar y ceder el paso","Usar una sirena","Pasar rápido y en silencio"],"h1":"Avísale a la persona que estás ahí.","h2":"En Massachusetts, un ciclista en la acera debe ceder el paso a los peatones y dar una señal que se oiga antes de rebasarlos.","p":"¡Correcto! Avisa con un sonido y cede el paso."},"ref":{"doc":"MA","page":null}},{"id":"ma-193","scope":"MA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Massachusetts, how many bicyclists may ride side by side?","o":["As many as fit","Only one, always","No more than 2","Up to 4"],"h1":"Riders may pair up, but in one lane on multi-lane roads.","h2":"In Massachusetts, bicyclists may not ride more than 2 abreast, and on a road with more than one lane in their direction they must stay within one lane.","p":"Correct! No more than 2 side by side."},"es":{"q":"En Massachusetts, ¿cuántos ciclistas pueden ir lado a lado?","o":["Los que quepan","Solo uno, siempre","No más de 2","Hasta 4"],"h1":"Pueden ir en pareja, pero en un solo carril si hay varios.","h2":"En Massachusetts, los ciclistas no pueden ir más de 2 lado a lado, y en una calle con más de un carril en su dirección deben quedarse dentro de un carril.","p":"¡Correcto! No más de 2 lado a lado."},"ref":{"doc":"MA","page":null}},{"id":"ma-194","scope":"MA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Massachusetts, at night, from how far away must a bicycle's white front light be visible?","o":["50 feet","100 feet","1 mile","500 feet"],"h1":"It is the same distance used for dimming your high beams.","h2":"In Massachusetts, from half an hour after sunset to half an hour before sunrise, a bicycle must show a white front light visible from at least 500 feet.","p":"Right! At least 500 feet."},"es":{"q":"En Massachusetts, de noche, ¿desde qué distancia debe verse la luz blanca delantera de una bicicleta?","o":["50 pies","100 pies","1 milla","500 pies"],"h1":"Es la misma distancia que se usa para bajar las luces altas.","h2":"En Massachusetts, desde media hora después de la puesta del sol hasta media hora antes de la salida, una bicicleta debe llevar una luz blanca delantera visible desde al menos 500 pies.","p":"¡Correcto! Al menos 500 pies."},"ref":{"doc":"MA","page":null}},{"id":"ma-195","scope":"MA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Massachusetts, at night, what must a bicycle show to the rear?","o":["A red light and a red reflector","A white light","A green reflector","Nothing if the rider wears white"],"h1":"The rear color is the same as a car's taillights.","h2":"In Massachusetts, at night a bicycle must show a red rear light and a red reflector, visible from at least 600 feet in a car's low beams.","p":"Correct! A red light and a red reflector."},"es":{"q":"En Massachusetts, de noche, ¿qué debe llevar una bicicleta atrás?","o":["Una luz roja y un reflector rojo","Una luz blanca","Un reflector verde","Nada si el ciclista viste de blanco"],"h1":"El color de atrás es el mismo de las luces traseras de un auto.","h2":"En Massachusetts, de noche una bicicleta debe llevar una luz roja trasera y un reflector rojo, visibles desde al menos 600 pies con las luces bajas de un auto.","p":"¡Correcto! Una luz roja y un reflector rojo."},"ref":{"doc":"MA","page":null}},{"id":"ma-196","scope":"MA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Massachusetts, what is the youngest child who may ride as a passenger on a bicycle?","o":["Any age in a backpack","1 year old, in a proper baby seat","5 years old","8 years old"],"h1":"Babies under a certain age may not ride on a bike at all.","h2":"In Massachusetts, no child under 1 year old may be carried on a bicycle, and children 1 to 4 must ride in a proper baby seat with a harness.","p":"Right! At least 1 year old, in a proper baby seat."},"es":{"q":"En Massachusetts, ¿cuál es la edad mínima de un niño para ir de pasajero en bicicleta?","o":["Cualquier edad en una mochila","1 año, en un asiento infantil adecuado","5 años","8 años"],"h1":"Los bebés menores de cierta edad no pueden ir en bicicleta.","h2":"En Massachusetts, no se puede llevar en bicicleta a un niño menor de 1 año, y los niños de 1 a 4 años deben ir en un asiento infantil adecuado con arnés.","p":"¡Correcto! Al menos 1 año, en un asiento infantil adecuado."},"ref":{"doc":"MA","page":null}},{"id":"ma-197","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, a bicyclist is in a crash with property damage. Above what amount must the cyclist report it to the local police?","o":["$1,000","$500","$100","$5,000"],"h1":"The amount is much lower than for car crashes.","h2":"In Massachusetts, a bicyclist must report to the local police any crash with an injury or with property damage of more than $100.","p":"Correct! More than $100."},"es":{"q":"En Massachusetts, un ciclista tiene un choque con daños materiales. ¿A partir de qué cantidad debe reportarlo a la policía local?","o":["$1,000","$500","$100","$5,000"],"h1":"La cantidad es mucho menor que para choques de autos.","h2":"En Massachusetts, un ciclista debe reportar a la policía local cualquier choque con heridos o con daños materiales de más de $100.","p":"¡Correcto! Más de $100."},"ref":{"doc":"MA","page":null}},{"id":"ma-198","scope":"MA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Massachusetts, which documents must you have with you or in the car every time you drive?","o":["Your birth certificate","Your insurance bill","Your title","Your license and the vehicle's registration"],"h1":"Police may ask for both when they stop you.","h2":"In Massachusetts, a driver must carry the license and the vehicle's registration certificate on their person or in an easy-to-reach place in the vehicle.","p":"Right! License and registration."},"es":{"q":"En Massachusetts, ¿qué documentos debes llevar contigo o en el auto cada vez que manejas?","o":["Tu acta de nacimiento","Tu factura del seguro","El título del auto","Tu licencia y el registro del vehículo"],"h1":"La policía puede pedir los dos cuando te detiene.","h2":"En Massachusetts, el conductor debe llevar su licencia y el certificado de registro del vehículo consigo o en un lugar fácil de alcanzar en el vehículo.","p":"¡Correcto! Licencia y registro."},"ref":{"doc":"MA","page":null}},{"id":"ma-199","scope":"MA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Massachusetts, what must a learner's permit holder have with them while driving?","o":["A copy of the driver's manual","The learner's permit itself","A letter from the school","A parent's license"],"h1":"It is the document that lets you practice.","h2":"In Massachusetts, a learner may drive only while having the learner's permit in their immediate possession.","p":"Right! Keep the permit with you."},"es":{"q":"En Massachusetts, ¿qué debe llevar consigo quien maneja con permiso de aprendizaje?","o":["Una copia del manual del conductor","El propio permiso de aprendizaje","Una carta de la escuela","La licencia de uno de sus padres"],"h1":"Es el documento que te deja practicar.","h2":"En Massachusetts, un aprendiz solo puede manejar si lleva consigo su permiso de aprendizaje.","p":"¡Correcto! Lleva el permiso contigo."},"ref":{"doc":"MA","page":null}},{"id":"ma-200","scope":"MA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Massachusetts, may the driver of a motor home keep an open alcoholic drink in the living area?","o":["Yes, the living area is exempt for everyone","Yes, if the vehicle is parked","No, the driver may never have an open container","Yes, if it is beer"],"h1":"Passengers in the living quarters are treated differently than the driver.","h2":"In Massachusetts, the living quarters of a motor home are exempt for passengers, but the driver may never possess an open container of alcohol.","p":"Correct! The driver may never have an open container."},"es":{"q":"En Massachusetts, ¿puede el conductor de una casa rodante tener una bebida alcohólica abierta en el área de vivienda?","o":["Sí, el área de vivienda está exenta para todos","Sí, si el vehículo está estacionado","No, el conductor nunca puede tener un envase abierto","Sí, si es cerveza"],"h1":"Los pasajeros en el área de vivienda se tratan distinto que el conductor.","h2":"En Massachusetts, el área de vivienda de una casa rodante está exenta para los pasajeros, pero el conductor nunca puede tener un envase abierto de alcohol.","p":"¡Correcto! El conductor nunca puede tener un envase abierto."},"ref":{"doc":"MA","page":null}},{"id":"md-001","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what is the youngest age to get a learner's permit?","o":["15 years old","15 years and 6 months","15 years and 9 months","16 years old"],"h1":"It is three months before the 16th birthday.","h2":"In Maryland, you must be at least 15 years and 9 months old to get a learner's permit.","p":"Right. Maryland starts at 15 years and 9 months."},"es":{"q":"En Maryland, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["15 años","15 años y 6 meses","15 años y 9 meses","16 años"],"h1":"Es tres meses antes de cumplir 16.","h2":"En Maryland, usted debe tener por lo menos 15 años y 9 meses para obtener un permiso de aprendiz.","p":"Correcto. Maryland empieza a los 15 años y 9 meses."},"zh":{"q":"在 Maryland，最小几岁可以拿到学习驾照（learner's permit）？","o":["15 岁","15 岁又 6 个月","15 岁又 9 个月","16 岁"],"h1":"是 16 岁生日前三个月。","h2":"在 Maryland，你必须至少 15 岁又 9 个月，才能拿到学习驾照。","p":"对。Maryland 从 15 岁又 9 个月开始。"},"vi":{"q":"Ở Maryland, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["15 tuổi","15 tuổi 6 tháng","15 tuổi 9 tháng","16 tuổi"],"h1":"Đó là ba tháng trước sinh nhật 16 tuổi.","h2":"Ở Maryland, bạn phải ít nhất 15 tuổi 9 tháng để lấy giấy phép tập lái.","p":"Đúng. Ở Maryland, bắt đầu từ 15 tuổi 9 tháng."},"tl":{"q":"Sa Maryland, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["15 taong gulang","15 taon at 6 na buwan","15 taon at 9 na buwan","16 taong gulang"],"h1":"Tatlong buwan ito bago ang ika-16 na kaarawan.","h2":"Sa Maryland, dapat ay hindi bababa sa 15 taon at 9 na buwan ang edad mo para makakuha ng learner's permit.","p":"Tama. Nagsisimula ang Maryland sa 15 taon at 9 na buwan."},"ar":{"q":"في Maryland، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["15 سنة","15 سنة و6 أشهر","15 سنة و9 أشهر","16 سنة"],"h1":"هو ثلاثة أشهر قبل عيد الميلاد السادس عشر.","h2":"في Maryland يجب أن يكون عمرك 15 سنة و9 أشهر على الأقل للحصول على تصريح التعلّم.","p":"صحيح. في Maryland يبدأ التصريح من عمر 15 سنة و9 أشهر."},"ref":{"doc":"MD","page":9}},{"id":"md-002","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how many of the 25 knowledge test questions must you answer correctly to pass?","o":["18","22","20","25"],"h1":"You may miss no more than three.","h2":"In Maryland, you must answer at least 22 of the 25 knowledge test questions correctly to pass.","p":"Right. 22 out of 25 passes in Maryland."},"es":{"q":"En Maryland, ¿cuántas de las 25 preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["18","22","20","25"],"h1":"Puede fallar como máximo tres.","h2":"En Maryland, usted debe contestar bien por lo menos 22 de las 25 preguntas del examen de conocimientos para aprobar.","p":"Correcto. En Maryland se aprueba con 22 de 25."},"zh":{"q":"在 Maryland，25 道笔试题中，必须答对几道才能通过？","o":["18","22","20","25"],"h1":"你最多只能答错三道。","h2":"在 Maryland，25 道笔试题中你必须至少答对 22 道才能通过。","p":"对。在 Maryland，25 道答对 22 道就通过。"},"vi":{"q":"Ở Maryland, bạn phải trả lời đúng bao nhiêu câu trong 25 câu của bài thi kiến thức để đậu?","o":["18","22","20","25"],"h1":"Bạn được sai không quá ba câu.","h2":"Ở Maryland, bạn phải trả lời đúng ít nhất 22 trong 25 câu của bài thi kiến thức để đậu.","p":"Đúng. Ở Maryland, đúng 22 trên 25 câu là đậu."},"tl":{"q":"Sa Maryland, ilan sa 25 tanong ng knowledge test ang dapat mong masagot nang tama para pumasa?","o":["18","22","20","25"],"h1":"Hindi ka puwedeng magkamali nang higit sa tatlo.","h2":"Sa Maryland, dapat mong masagot nang tama ang hindi bababa sa 22 sa 25 tanong ng knowledge test para pumasa.","p":"Tama. Pasado ang 22 sa 25 sa Maryland."},"ar":{"q":"في Maryland، كم سؤالًا من أسئلة اختبار المعرفة الـ25 يجب أن تجيب عنها إجابة صحيحة لتنجح؟","o":["18","22","20","25"],"h1":"لا يمكنك أن تخطئ في أكثر من ثلاثة أسئلة.","h2":"في Maryland يجب أن تجيب إجابة صحيحة عن 22 سؤالًا على الأقل من أسئلة اختبار المعرفة الـ25 لتنجح.","p":"صحيح. في Maryland تنجح بـ22 من 25."},"ref":{"doc":"MD","page":null}},{"id":"md-003","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, who may supervise a driver with a learner's permit?","o":["Any licensed driver 18 or older","Any adult, licensed or not","A licensed driver 25 or older","A driver 21 or older who has held a license for at least 3 years"],"h1":"Both an age and a number of years with a license matter.","h2":"In Maryland, the supervising driver must be at least 21 years old and must have held a valid license for at least 3 years.","p":"Right. 21 or older, with at least 3 years licensed."},"es":{"q":"En Maryland, ¿quién puede supervisar a un conductor con permiso de aprendiz?","o":["Cualquier conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 25 años o más","Un conductor de 21 años o más que ha tenido licencia por lo menos 3 años"],"h1":"Importan la edad y también los años con licencia.","h2":"En Maryland, el conductor que supervisa debe tener por lo menos 21 años y haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. 21 años o más, con por lo menos 3 años de licencia."},"zh":{"q":"在 Maryland，谁可以陪同持学习驾照的司机？","o":["任何 18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","25 岁或以上、有驾照的司机","21 岁或以上、持有驾照至少 3 年的司机"],"h1":"年龄和持有驾照的年数都很重要。","h2":"在 Maryland，陪同的司机必须至少 21 岁，而且必须持有有效驾照至少 3 年。","p":"对。21 岁或以上，至少持有驾照 3 年。"},"vi":{"q":"Ở Maryland, ai được phép giám sát người lái có giấy phép tập lái?","o":["Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Người có bằng lái từ 25 tuổi trở lên","Người từ 21 tuổi trở lên đã có bằng lái ít nhất 3 năm"],"h1":"Cả tuổi và số năm có bằng lái đều quan trọng.","h2":"Ở Maryland, người giám sát phải ít nhất 21 tuổi và đã có bằng lái hợp lệ ít nhất 3 năm.","p":"Đúng. Từ 21 tuổi trở lên, và có bằng lái ít nhất 3 năm."},"tl":{"q":"Sa Maryland, sino ang puwedeng magbantay sa driver na may learner's permit?","o":["Kahit sinong may lisensya na 18 taong gulang pataas","Kahit sinong adulto, may lisensya man o wala","Driver na may lisensya na 25 taong gulang pataas","Driver na 21 taong gulang pataas na may lisensya nang hindi bababa sa 3 taon"],"h1":"Mahalaga ang edad at ang bilang ng taon na may lisensya.","h2":"Sa Maryland, ang nagbabantay na driver ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya nang hindi bababa sa 3 taon.","p":"Tama. 21 pataas, at may lisensya nang hindi bababa sa 3 taon."},"ar":{"q":"في Maryland، من يمكنه أن يرافق ويشرف على سائق يحمل تصريح التعلّم؟","o":["أي سائق لديه رخصة عمره 18 سنة أو أكثر","أي شخص بالغ، لديه رخصة أو ليس لديه","سائق لديه رخصة عمره 25 سنة أو أكثر","سائق عمره 21 سنة أو أكثر ولديه رخصة منذ 3 سنوات على الأقل"],"h1":"العمر وعدد سنوات حمل الرخصة كلاهما مهم.","h2":"في Maryland يجب أن يكون السائق المشرف عمره 21 سنة على الأقل ولديه رخصة سارية منذ 3 سنوات على الأقل.","p":"صحيح. 21 سنة أو أكثر، ولديه رخصة منذ 3 سنوات على الأقل."},"ref":{"doc":"MD","page":51}},{"id":"md-004","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, where must the supervising driver sit when a learner is driving?","o":["In the front passenger seat, with no one else in the front","In any back seat","Anywhere in the car","Behind the driver"],"h1":"The supervisor needs to be right beside the learner.","h2":"In Maryland, the supervising driver must sit in the front passenger seat, and no one else may sit in the front.","p":"Right. The supervisor sits up front, beside you."},"es":{"q":"En Maryland, ¿dónde debe sentarse el conductor que supervisa cuando maneja un aprendiz?","o":["En el asiento del pasajero delantero, sin nadie más adelante","En cualquier asiento de atrás","En cualquier lugar del auto","Detrás del conductor"],"h1":"El supervisor debe estar justo al lado del aprendiz.","h2":"En Maryland, el conductor que supervisa debe sentarse en el asiento del pasajero delantero, y nadie más puede ir adelante.","p":"Correcto. El supervisor va adelante, a su lado."},"zh":{"q":"在 Maryland，学习驾驶的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位，前排不能坐其他人","任何后排座位","车里任何地方","司机后面"],"h1":"陪同的人需要就在学习驾驶的人旁边。","h2":"在 Maryland，陪同的司机必须坐在前排乘客座位，前排不能坐其他人。","p":"对。陪同的人坐在前排，在你旁边。"},"vi":{"q":"Ở Maryland, người giám sát phải ngồi ở đâu khi người tập lái đang lái xe?","o":["Ở ghế hành khách phía trước, và không ai khác ngồi phía trước","Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Phía sau người lái"],"h1":"Người giám sát cần ngồi ngay bên cạnh người tập lái.","h2":"Ở Maryland, người giám sát phải ngồi ở ghế hành khách phía trước, và không ai khác được ngồi phía trước.","p":"Đúng. Người giám sát ngồi phía trước, bên cạnh bạn."},"tl":{"q":"Sa Maryland, saan dapat umupo ang nagbabantay na driver habang nagmamaneho ang learner?","o":["Sa upuan ng pasahero sa harap, at walang ibang nasa harap","Sa kahit anong upuan sa likod","Kahit saan sa kotse","Sa likod ng driver"],"h1":"Kailangang nasa tabi mismo ng learner ang nagbabantay.","h2":"Sa Maryland, dapat umupo ang nagbabantay na driver sa upuan ng pasahero sa harap, at walang ibang puwedeng umupo sa harap.","p":"Tama. Sa harap umuupo ang nagbabantay, sa tabi mo."},"ar":{"q":"في Maryland، أين يجب أن يجلس السائق المشرف عندما يقود المتعلّم؟","o":["في مقعد الراكب الأمامي، ولا يجلس أحد غيره في الأمام","في أي مقعد خلفي","في أي مكان في السيارة","خلف السائق"],"h1":"يجب أن يكون المشرف بجانب المتعلّم مباشرة.","h2":"في Maryland يجب أن يجلس السائق المشرف في مقعد الراكب الأمامي، ولا يجوز أن يجلس أحد غيره في الأمام.","p":"صحيح. المشرف يجلس في الأمام بجانبك."},"ref":{"doc":"MD","page":51}},{"id":"md-005","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how many hours of supervised practice must a new driver log with a learner's permit?","o":["30 hours, including 5 at night","40 hours, including 10 at night","60 hours, including 10 at night","100 hours, including 20 at night"],"h1":"It is the highest of the usual numbers, with 10 of them at night.","h2":"In Maryland, a learner must log 60 hours of supervised practice, and 10 of those hours must be at night.","p":"Right. 60 hours, 10 at night."},"es":{"q":"En Maryland, ¿cuántas horas de práctica supervisada debe registrar un conductor nuevo con permiso de aprendiz?","o":["30 horas, 5 de ellas de noche","40 horas, 10 de ellas de noche","60 horas, 10 de ellas de noche","100 horas, 20 de ellas de noche"],"h1":"Es el número más alto de los habituales, con 10 de ellas de noche.","h2":"En Maryland, un aprendiz debe registrar 60 horas de práctica supervisada, y 10 de esas horas deben ser de noche.","p":"Correcto. 60 horas, 10 de noche."},"zh":{"q":"在 Maryland，新司机持学习驾照期间，必须记录多少小时有人陪同的练习？","o":["30 小时，其中 5 小时在夜间","40 小时，其中 10 小时在夜间","60 小时，其中 10 小时在夜间","100 小时，其中 20 小时在夜间"],"h1":"这是常见数字里最高的，其中 10 小时在夜间。","h2":"在 Maryland，学习驾驶的人必须记录 60 小时有人陪同的练习，其中 10 小时必须在夜间。","p":"对。60 小时，其中 10 小时在夜间。"},"vi":{"q":"Ở Maryland, người lái mới có giấy phép tập lái phải ghi lại bao nhiêu giờ tập lái có giám sát?","o":["30 giờ, trong đó 5 giờ vào ban đêm","40 giờ, trong đó 10 giờ vào ban đêm","60 giờ, trong đó 10 giờ vào ban đêm","100 giờ, trong đó 20 giờ vào ban đêm"],"h1":"Đó là con số cao nhất trong các con số thường gặp, với 10 giờ vào ban đêm.","h2":"Ở Maryland, người tập lái phải ghi lại 60 giờ tập lái có giám sát, và 10 giờ trong số đó phải vào ban đêm.","p":"Đúng. 60 giờ, 10 giờ vào ban đêm."},"tl":{"q":"Sa Maryland, ilang oras ng praktis na may bantay ang dapat itala ng bagong driver na may learner's permit?","o":["30 oras, kasama ang 5 sa gabi","40 oras, kasama ang 10 sa gabi","60 oras, kasama ang 10 sa gabi","100 oras, kasama ang 20 sa gabi"],"h1":"Ito ang pinakamataas sa mga karaniwang bilang, at 10 dito ay sa gabi.","h2":"Sa Maryland, dapat magtala ang learner ng 60 oras ng praktis na may bantay, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. 60 oras, 10 sa gabi."},"ar":{"q":"في Maryland، كم ساعة من التدريب تحت الإشراف يجب أن يسجّلها السائق الجديد الذي يحمل تصريح التعلّم؟","o":["30 ساعة، منها 5 في الليل","40 ساعة، منها 10 في الليل","60 ساعة، منها 10 في الليل","100 ساعة، منها 20 في الليل"],"h1":"هو أعلى رقم بين الأرقام المعتادة، و10 ساعات منه في الليل.","h2":"في Maryland يجب أن يسجّل المتعلّم 60 ساعة من التدريب تحت الإشراف، ويجب أن تكون 10 ساعات منها في الليل.","p":"صحيح. 60 ساعة، منها 10 في الليل."},"ref":{"doc":"MD","page":10}},{"id":"md-006","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, which practice hours count as night driving?","o":["From 9:00 p.m. to 6:00 a.m.","From 30 minutes before sunset to 30 minutes after sunrise","From midnight to 5:00 a.m.","Any time the headlights are on"],"h1":"The answer follows the sun, not the clock.","h2":"In Maryland, night practice is driving from 30 minutes before sunset until 30 minutes after sunrise.","p":"Right. Night practice follows sunset and sunrise."},"es":{"q":"En Maryland, ¿qué horas de práctica cuentan como manejo nocturno?","o":["De 9:00 p.m. a 6:00 a.m.","Desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer","De medianoche a 5:00 a.m.","Cualquier momento con las luces encendidas"],"h1":"La respuesta sigue al sol, no al reloj.","h2":"En Maryland, la práctica nocturna es manejar desde 30 minutos antes de la puesta del sol hasta 30 minutos después del amanecer.","p":"Correcto. La práctica nocturna sigue la puesta del sol y el amanecer."},"zh":{"q":"在 Maryland，哪些练习时间算是夜间驾驶？","o":["晚上 9:00 到早上 6:00","日落前 30 分钟到日出后 30 分钟","午夜到早上 5:00","任何开着车头灯的时候"],"h1":"答案跟着太阳走，不是跟着时钟。","h2":"在 Maryland，夜间练习是指从日落前 30 分钟到日出后 30 分钟之间的驾驶。","p":"对。夜间练习按日落和日出来算。"},"vi":{"q":"Ở Maryland, những giờ tập lái nào được tính là lái xe ban đêm?","o":["Từ 9:00 tối đến 6:00 sáng","Từ 30 phút trước khi mặt trời lặn đến 30 phút sau khi mặt trời mọc","Từ nửa đêm đến 5:00 sáng","Bất cứ lúc nào bật đèn pha"],"h1":"Câu trả lời theo mặt trời, không theo đồng hồ.","h2":"Ở Maryland, tập lái ban đêm là lái xe từ 30 phút trước khi mặt trời lặn đến 30 phút sau khi mặt trời mọc.","p":"Đúng. Tập lái ban đêm tính theo lúc mặt trời lặn và mọc."},"tl":{"q":"Sa Maryland, aling mga oras ng praktis ang binibilang na pagmamaneho sa gabi?","o":["Mula 9:00 p.m. hanggang 6:00 a.m.","Mula 30 minuto bago lumubog ang araw hanggang 30 minuto pagkasikat ng araw","Mula hatinggabi hanggang 5:00 a.m.","Anumang oras na nakabukas ang headlights"],"h1":"Sumusunod ang sagot sa araw, hindi sa orasan.","h2":"Sa Maryland, ang praktis sa gabi ay pagmamaneho mula 30 minuto bago lumubog ang araw hanggang 30 minuto pagkasikat ng araw.","p":"Tama. Sumusunod ang praktis sa gabi sa paglubog at pagsikat ng araw."},"ar":{"q":"في Maryland، أي ساعات التدريب تُحسب قيادةً ليلية؟","o":["من 9:00 مساءً إلى 6:00 صباحًا","من 30 دقيقة قبل غروب الشمس إلى 30 دقيقة بعد شروق الشمس","من منتصف الليل إلى 5:00 صباحًا","أي وقت تكون فيه الأضواء الأمامية مضاءة"],"h1":"الجواب يتبع الشمس، لا الساعة.","h2":"في Maryland التدريب الليلي هو القيادة من 30 دقيقة قبل غروب الشمس حتى 30 دقيقة بعد شروق الشمس.","p":"صحيح. التدريب الليلي يتبع الغروب والشروق."},"ref":{"doc":"MD","page":10}},{"id":"md-007","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how long must a driver under 18 hold a learner's permit before getting a provisional license?","o":["45 days","3 months","6 months","9 months"],"h1":"It is the longest of the choices, three quarters of a year.","h2":"In Maryland, a driver under 18 must hold the learner's permit for at least 9 months before getting a provisional license.","p":"Right. Nine months for teens in Maryland."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener un conductor menor de 18 años el permiso de aprendiz antes de obtener una licencia provisional?","o":["45 días","3 meses","6 meses","9 meses"],"h1":"Es la opción más larga, tres cuartos de año.","h2":"En Maryland, un conductor menor de 18 años debe tener el permiso de aprendiz por lo menos 9 meses antes de obtener una licencia provisional.","p":"Correcto. Nueve meses para los jóvenes en Maryland."},"zh":{"q":"在 Maryland，18 岁以下的司机必须持有学习驾照多久，才能拿到过渡驾照（provisional license）？","o":["45 天","3 个月","6 个月","9 个月"],"h1":"这是选项里最长的，是四分之三年。","h2":"在 Maryland，18 岁以下的司机必须持有学习驾照至少 9 个月，才能拿到过渡驾照。","p":"对。Maryland 的青少年要九个月。"},"vi":{"q":"Ở Maryland, người lái dưới 18 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời (provisional license)?","o":["45 ngày","3 tháng","6 tháng","9 tháng"],"h1":"Đó là lựa chọn dài nhất, ba phần tư năm.","h2":"Ở Maryland, người lái dưới 18 tuổi phải giữ giấy phép tập lái ít nhất 9 tháng trước khi lấy bằng lái tạm thời.","p":"Đúng. Ở Maryland, thanh thiếu niên phải chờ chín tháng."},"tl":{"q":"Sa Maryland, gaano katagal dapat hawak ng driver na wala pang 18 ang learner's permit bago makakuha ng provisional license?","o":["45 araw","3 buwan","6 na buwan","9 na buwan"],"h1":"Ito ang pinakamahaba sa mga pagpipilian, tatlong-kapat ng isang taon.","h2":"Sa Maryland, dapat hawak ng driver na wala pang 18 ang learner's permit nang hindi bababa sa 9 na buwan bago makakuha ng provisional license.","p":"Tama. Siyam na buwan para sa mga kabataan sa Maryland."},"ar":{"q":"في Maryland، كم يجب أن يحتفظ السائق الذي عمره أقل من 18 سنة بتصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["45 يومًا","3 أشهر","6 أشهر","9 أشهر"],"h1":"هو أطول خيار، ثلاثة أرباع السنة.","h2":"في Maryland يجب أن يحتفظ السائق الذي عمره أقل من 18 سنة بتصريح التعلّم 9 أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. تسعة أشهر للمراهقين في Maryland."},"ref":{"doc":"MD","page":10}},{"id":"md-008","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long must a new driver aged 25 or older hold a learner's permit before getting a provisional license?","o":["45 days","9 months","1 year","No waiting period"],"h1":"Older drivers wait much less than teens, but there is still a wait.","h2":"In Maryland, a new driver aged 25 or older must hold the learner's permit for at least 45 days.","p":"Right. 45 days for drivers 25 and older."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor nuevo de 25 años o más antes de obtener una licencia provisional?","o":["45 días","9 meses","1 año","No hay tiempo de espera"],"h1":"Los mayores esperan mucho menos que los jóvenes, pero sí hay una espera.","h2":"En Maryland, un conductor nuevo de 25 años o más debe tener el permiso de aprendiz por lo menos 45 días.","p":"Correcto. 45 días para conductores de 25 años o más."},"zh":{"q":"在 Maryland，25 岁或以上的新司机必须持有学习驾照多久，才能拿到过渡驾照？","o":["45 天","9 个月","1 年","不用等"],"h1":"年纪大的司机等的时间比青少年短很多，但还是要等。","h2":"在 Maryland，25 岁或以上的新司机必须持有学习驾照至少 45 天。","p":"对。25 岁及以上的司机要 45 天。"},"vi":{"q":"Ở Maryland, người lái mới từ 25 tuổi trở lên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời (provisional license)?","o":["45 ngày","9 tháng","1 năm","Không phải chờ"],"h1":"Người lớn tuổi chờ ít hơn nhiều so với thanh thiếu niên, nhưng vẫn phải chờ.","h2":"Ở Maryland, người lái mới từ 25 tuổi trở lên phải giữ giấy phép tập lái ít nhất 45 ngày.","p":"Đúng. 45 ngày cho người lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Maryland, gaano katagal dapat hawak ng bagong driver na 25 taong gulang pataas ang learner's permit bago makakuha ng provisional license?","o":["45 araw","9 na buwan","1 taon","Walang hihintayin"],"h1":"Mas maikli ang hinihintay ng mas matatandang driver kaysa sa kabataan, pero may hinihintay pa rin.","h2":"Sa Maryland, dapat hawak ng bagong driver na 25 taong gulang pataas ang learner's permit nang hindi bababa sa 45 araw.","p":"Tama. 45 araw para sa mga driver na 25 pataas."},"ar":{"q":"في Maryland، كم يجب أن يحتفظ السائق الجديد الذي عمره 25 سنة أو أكثر بتصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["45 يومًا","9 أشهر","سنة واحدة","لا توجد مدة انتظار"],"h1":"السائقون الأكبر سنًا ينتظرون أقل بكثير من المراهقين، لكن ما زال هناك انتظار.","h2":"في Maryland يجب أن يحتفظ السائق الجديد الذي عمره 25 سنة أو أكثر بتصريح التعلّم 45 يومًا على الأقل.","p":"صحيح. 45 يومًا للسائقين الذين عمرهم 25 سنة أو أكثر."},"ref":{"doc":"MD","page":10}},{"id":"md-009","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what happens if a learner is convicted of a moving violation while holding the permit?","o":["Nothing changes","The permit is upgraded early","The waiting time restarts, with at least 9 months from the conviction","Only a fine is paid"],"h1":"The clock does not keep running as before.","h2":"In Maryland, a moving violation conviction restarts the waiting time, so the learner must wait at least 9 months from the date of the conviction.","p":"Right. A violation resets the clock to 9 months."},"es":{"q":"En Maryland, ¿qué pasa si un aprendiz es condenado por una infracción de tránsito en movimiento mientras tiene el permiso?","o":["Nada cambia","El permiso se mejora antes de tiempo","El tiempo de espera vuelve a empezar, con por lo menos 9 meses desde la condena","Solo se paga una multa"],"h1":"El reloj no sigue corriendo como antes.","h2":"En Maryland, una condena por infracción en movimiento reinicia la espera, y el aprendiz debe esperar por lo menos 9 meses desde la fecha de la condena.","p":"Correcto. Una infracción reinicia la cuenta a 9 meses."},"zh":{"q":"在 Maryland，学习驾驶的人持学习驾照期间被判行车违规，会怎么样？","o":["什么都不变","学习驾照提前升级","等待时间重新开始，从被判那天起至少 9 个月","只交罚款"],"h1":"时间不会像以前那样继续算下去。","h2":"在 Maryland，被判行车违规会让等待时间重新开始，所以学习驾驶的人必须从被判那天起至少再等 9 个月。","p":"对。违规会让时间重新回到 9 个月。"},"vi":{"q":"Ở Maryland, điều gì xảy ra nếu người tập lái bị kết tội vi phạm khi đang lái xe trong thời gian có giấy phép tập lái?","o":["Không có gì thay đổi","Giấy phép được nâng cấp sớm","Thời gian chờ bắt đầu lại, ít nhất 9 tháng kể từ ngày bị kết tội","Chỉ phải nộp tiền phạt"],"h1":"Thời gian không tiếp tục tính như trước.","h2":"Ở Maryland, bị kết tội vi phạm khi đang lái xe sẽ làm thời gian chờ bắt đầu lại, nên người tập lái phải chờ ít nhất 9 tháng kể từ ngày bị kết tội.","p":"Đúng. Một vi phạm đưa thời gian chờ về lại 9 tháng."},"tl":{"q":"Sa Maryland, ano ang mangyayari kung mahatulan ang learner ng moving violation habang hawak ang permit?","o":["Walang magbabago","Maagang maa-upgrade ang permit","Magsisimula ulit ang paghihintay, hindi bababa sa 9 na buwan mula sa hatol","Multa lang ang babayaran"],"h1":"Hindi na tuloy-tuloy ang bilang ng oras gaya ng dati.","h2":"Sa Maryland, kapag nahatulan ng moving violation, magsisimula ulit ang paghihintay, kaya dapat maghintay ang learner nang hindi bababa sa 9 na buwan mula sa petsa ng hatol.","p":"Tama. Ibinabalik ng violation ang bilang sa 9 na buwan."},"ar":{"q":"في Maryland، ماذا يحدث إذا أُدين المتعلّم بمخالفة أثناء القيادة (moving violation) وهو يحمل التصريح؟","o":["لا يتغيّر شيء","تتم ترقية التصريح مبكرًا","تبدأ مدة الانتظار من جديد، 9 أشهر على الأقل من تاريخ الإدانة","يدفع غرامة فقط"],"h1":"العدّ لا يستمر كما كان من قبل.","h2":"في Maryland الإدانة بمخالفة أثناء القيادة تجعل مدة الانتظار تبدأ من جديد، فيجب أن ينتظر المتعلّم 9 أشهر على الأقل من تاريخ الإدانة.","p":"صحيح. المخالفة تعيد العدّ إلى 9 أشهر."},"ref":{"doc":"MD","page":10}},{"id":"md-010","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how much driver education must a new driver complete?","o":["10 hours in class and 2 hours behind the wheel","30 hours in class and 6 hours behind the wheel","No driver education is required","6 hours in class and 30 hours behind the wheel"],"h1":"The classroom part is much longer than the time behind the wheel.","h2":"In Maryland, the certified driver education program requires at least 30 hours of classroom instruction and 6 hours of behind-the-wheel training.","p":"Right. 30 hours in class and 6 behind the wheel."},"es":{"q":"En Maryland, ¿cuánta educación vial debe completar un conductor nuevo?","o":["10 horas en clase y 2 horas al volante","30 horas en clase y 6 horas al volante","No se requiere educación vial","6 horas en clase y 30 horas al volante"],"h1":"La parte en clase es mucho más larga que el tiempo al volante.","h2":"En Maryland, el programa certificado de educación vial exige por lo menos 30 horas de clase y 6 horas de práctica al volante.","p":"Correcto. 30 horas en clase y 6 al volante."},"zh":{"q":"在 Maryland，新司机必须完成多少驾驶课？","o":["课堂 10 小时，实际开车 2 小时","课堂 30 小时，实际开车 6 小时","不需要上驾驶课","课堂 6 小时，实际开车 30 小时"],"h1":"课堂部分比实际开车的时间长很多。","h2":"在 Maryland，经过认证的驾驶课要求至少 30 小时课堂教学和 6 小时实际开车培训。","p":"对。课堂 30 小时，实际开车 6 小时。"},"vi":{"q":"Ở Maryland, người lái mới phải hoàn thành bao nhiêu giờ học lái xe (driver education)?","o":["10 giờ trong lớp và 2 giờ lái xe thực tế","30 giờ trong lớp và 6 giờ lái xe thực tế","Không bắt buộc học lái xe","6 giờ trong lớp và 30 giờ lái xe thực tế"],"h1":"Phần học trong lớp dài hơn nhiều so với thời gian lái xe thực tế.","h2":"Ở Maryland, chương trình học lái xe được chứng nhận đòi hỏi ít nhất 30 giờ học trong lớp và 6 giờ lái xe thực tế.","p":"Đúng. 30 giờ trong lớp và 6 giờ lái xe thực tế."},"tl":{"q":"Sa Maryland, gaano karaming driver education ang dapat tapusin ng bagong driver?","o":["10 oras sa klase at 2 oras sa manibela","30 oras sa klase at 6 na oras sa manibela","Hindi kailangan ang driver education","6 na oras sa klase at 30 oras sa manibela"],"h1":"Mas mahaba ang bahagi sa klase kaysa sa oras sa manibela.","h2":"Sa Maryland, ang certified na driver education program ay nangangailangan ng hindi bababa sa 30 oras ng pag-aaral sa klase at 6 na oras ng pagsasanay sa manibela.","p":"Tama. 30 oras sa klase at 6 sa manibela."},"ar":{"q":"في Maryland، كم من تعليم القيادة (driver education) يجب أن يُكمل السائق الجديد؟","o":["10 ساعات في الصف وساعتان خلف المقود","30 ساعة في الصف و6 ساعات خلف المقود","تعليم القيادة غير مطلوب","6 ساعات في الصف و30 ساعة خلف المقود"],"h1":"جزء الصف أطول بكثير من الوقت خلف المقود.","h2":"في Maryland يتطلب برنامج تعليم القيادة المعتمد 30 ساعة على الأقل من الدروس في الصف و6 ساعات من التدريب خلف المقود.","p":"صحيح. 30 ساعة في الصف و6 خلف المقود."},"ref":{"doc":"MD","page":null}},{"id":"md-011","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, may a learner's permit holder use a phone with Bluetooth while driving?","o":["Yes, hands-free is allowed","Yes, for short calls","Yes, if the supervisor allows it","No, only to call 911 in an emergency"],"h1":"The rule for learners covers every kind of phone use.","h2":"In Maryland, a learner's permit holder may not use a phone while driving, even with Bluetooth or hands-free, except to call 911 in an emergency.","p":"Right. Learners in Maryland do not use the phone at all."},"es":{"q":"En Maryland, ¿puede una persona con permiso de aprendiz usar un teléfono con Bluetooth mientras maneja?","o":["Sí, manos libres está permitido","Sí, para llamadas cortas","Sí, si el supervisor lo permite","No, solo para llamar al 911 en una emergencia"],"h1":"La regla para aprendices cubre todo uso del teléfono.","h2":"En Maryland, quien tiene permiso de aprendiz no puede usar el teléfono mientras maneja, ni con Bluetooth ni manos libres, excepto para llamar al 911 en una emergencia.","p":"Correcto. Los aprendices en Maryland no usan el teléfono para nada."},"zh":{"q":"在 Maryland，持学习驾照的人开车时可以用蓝牙打电话吗？","o":["可以，免提是允许的","可以，短时间通话可以","可以，只要陪同的人同意","不可以，只能在紧急情况下打 911"],"h1":"对学习驾驶的人的规定包括所有手机用法。","h2":"在 Maryland，持学习驾照的人开车时不能用手机，用蓝牙或免提也不行，只有在紧急情况下打 911 除外。","p":"对。Maryland 学习驾驶的人完全不用手机。"},"vi":{"q":"Ở Maryland, người có giấy phép tập lái có được dùng điện thoại với Bluetooth khi đang lái xe không?","o":["Có, được dùng rảnh tay","Có, cho các cuộc gọi ngắn","Có, nếu người giám sát cho phép","Không, chỉ được gọi 911 khi khẩn cấp"],"h1":"Quy định cho người tập lái áp dụng cho mọi cách dùng điện thoại.","h2":"Ở Maryland, người có giấy phép tập lái không được dùng điện thoại khi lái xe, kể cả với Bluetooth hay rảnh tay, trừ khi gọi 911 lúc khẩn cấp.","p":"Đúng. Ở Maryland, người tập lái hoàn toàn không dùng điện thoại."},"tl":{"q":"Sa Maryland, puwede bang gumamit ng phone na may Bluetooth habang nagmamaneho ang may hawak ng learner's permit?","o":["Oo, puwede ang hands-free","Oo, para sa maiikling tawag","Oo, kung papayag ang nagbabantay","Hindi, maliban sa pagtawag sa 911 sa emergency"],"h1":"Sakop ng patakaran para sa learners ang lahat ng uri ng paggamit ng phone.","h2":"Sa Maryland, hindi puwedeng gumamit ng phone habang nagmamaneho ang may hawak ng learner's permit, kahit Bluetooth o hands-free, maliban sa pagtawag sa 911 sa emergency.","p":"Tama. Hindi talaga gumagamit ng phone ang learners sa Maryland."},"ar":{"q":"في Maryland، هل يجوز لحامل تصريح التعلّم أن يستعمل الهاتف عبر Bluetooth أثناء القيادة؟","o":["نعم، بدون استعمال اليدين مسموح","نعم، للمكالمات القصيرة","نعم، إذا سمح المشرف بذلك","لا، إلا للاتصال بـ911 في حالة طوارئ"],"h1":"القاعدة الخاصة بالمتعلّمين تشمل كل أنواع استعمال الهاتف.","h2":"في Maryland لا يجوز لحامل تصريح التعلّم أن يستعمل الهاتف أثناء القيادة، حتى عبر Bluetooth أو بدون استعمال اليدين، إلا للاتصال بـ911 في حالة طوارئ.","p":"صحيح. المتعلّمون في Maryland لا يستعملون الهاتف أبدًا."},"ref":{"doc":"MD","page":47}},{"id":"md-012","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, during which hours may a provisional driver under 18 not drive without a supervising driver?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"The limit starts at the very start of a new day.","h2":"In Maryland, a provisional driver under 18 may not drive between midnight and 5:00 in the morning without a supervising driver, unless going to or from work, school activities, volunteer programs or sports.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Maryland, ¿en qué horario no puede manejar sin supervisor un conductor provisional menor de 18 años?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"El límite empieza justo al comenzar un nuevo día.","h2":"En Maryland, un conductor provisional menor de 18 años no puede manejar entre la medianoche y las 5:00 de la mañana sin supervisor, salvo para ir o volver del trabajo, actividades escolares, voluntariado o deportes.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机，在哪些时间没有陪同的司机就不能开车？","o":["午夜到早上 5:00","晚上 9:00 到早上 6:00","晚上 10:00 到早上 5:00","没有夜间限制"],"h1":"这个限制从新的一天刚开始时开始。","h2":"在 Maryland，18 岁以下持过渡驾照的司机，没有陪同的司机时，不能在午夜到早上 5:00 之间开车，除非是去上班或下班、去学校活动、志愿活动或体育活动，或者从那里回来。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi không được lái xe mà không có người giám sát trong những giờ nào?","o":["Từ nửa đêm đến 5:00 sáng","Từ 9:00 tối đến 6:00 sáng","Từ 10:00 tối đến 5:00 sáng","Không có giới hạn ban đêm"],"h1":"Giới hạn bắt đầu ngay đầu một ngày mới.","h2":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi không được lái xe từ nửa đêm đến 5:00 sáng mà không có người giám sát, trừ khi đi làm hoặc về, đi hoặc về từ hoạt động của trường, chương trình tình nguyện hoặc thể thao.","p":"Đúng. Từ nửa đêm đến 5 giờ sáng thì không được lái."},"tl":{"q":"Sa Maryland, sa anong mga oras hindi puwedeng magmaneho nang walang nagbabantay ang provisional driver na wala pang 18?","o":["Hatinggabi hanggang 5:00 a.m.","9:00 p.m. hanggang 6:00 a.m.","10:00 p.m. hanggang 5:00 a.m.","Walang limitasyon sa gabi"],"h1":"Nagsisimula ang limitasyon sa mismong simula ng bagong araw.","h2":"Sa Maryland, hindi puwedeng magmaneho ang provisional driver na wala pang 18 mula hatinggabi hanggang 5:00 ng umaga nang walang nagbabantay, maliban kung papunta o pauwi sa trabaho, gawain sa paaralan, volunteer program o sports.","p":"Tama. Bawal ang hatinggabi hanggang 5 a.m."},"ar":{"q":"في Maryland، في أي ساعات لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن يقود بدون سائق مشرف؟","o":["من منتصف الليل إلى 5:00 صباحًا","من 9:00 مساءً إلى 6:00 صباحًا","من 10:00 مساءً إلى 5:00 صباحًا","لا يوجد حدّ ليلي"],"h1":"الحدّ يبدأ في أول لحظة من يوم جديد.","h2":"في Maryland لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن يقود بين منتصف الليل و5:00 صباحًا بدون سائق مشرف، إلا إذا كان ذاهبًا إلى العمل أو أنشطة المدرسة أو برامج التطوع أو الرياضة، أو عائدًا منها.","p":"صحيح. من منتصف الليل إلى 5 صباحًا ممنوع."},"ref":{"doc":"MD","page":47}},{"id":"md-013","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, for how long may a provisional driver under 18 not carry passengers under 18 who are not immediate family, without a supervising driver?","o":["The first 30 days","The first 151 days","The first year","Until age 21"],"h1":"It is about five months.","h2":"In Maryland, for the first 151 days, a provisional driver under 18 may not carry passengers under 18 other than immediate family unless a supervising driver is present.","p":"Right. The first 151 days, about five months."},"es":{"q":"En Maryland, ¿durante cuánto tiempo un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, sin un supervisor?","o":["Los primeros 30 días","Los primeros 151 días","El primer año","Hasta los 21 años"],"h1":"Son unos cinco meses.","h2":"En Maryland, durante los primeros 151 días, un conductor provisional menor de 18 años no puede llevar pasajeros menores de 18 que no sean familia inmediata, salvo que vaya un supervisor.","p":"Correcto. Los primeros 151 días, unos cinco meses."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机，在没有陪同司机时，多久之内不能载不是直系亲属、18 岁以下的乘客？","o":["头 30 天","头 151 天","头一年","到 21 岁为止"],"h1":"大约是五个月。","h2":"在 Maryland，头 151 天里，18 岁以下持过渡驾照的司机不能载直系亲属以外、18 岁以下的乘客，除非有陪同的司机在车上。","p":"对。头 151 天，大约五个月。"},"vi":{"q":"Ở Maryland, trong bao lâu người lái có bằng lái tạm thời dưới 18 tuổi không được chở hành khách dưới 18 tuổi không phải người thân trong gia đình, khi không có người giám sát?","o":["30 ngày đầu tiên","151 ngày đầu tiên","Năm đầu tiên","Cho đến 21 tuổi"],"h1":"Khoảng năm tháng.","h2":"Ở Maryland, trong 151 ngày đầu tiên, người lái có bằng lái tạm thời dưới 18 tuổi không được chở hành khách dưới 18 tuổi, trừ người thân trong gia đình, nếu không có người giám sát.","p":"Đúng. 151 ngày đầu tiên, khoảng năm tháng."},"tl":{"q":"Sa Maryland, gaano katagal hindi puwedeng magsakay ang provisional driver na wala pang 18 ng mga pasaherong wala pang 18 na hindi malapit na kapamilya, nang walang nagbabantay?","o":["Unang 30 araw","Unang 151 araw","Unang taon","Hanggang edad 21"],"h1":"Mga limang buwan ito.","h2":"Sa Maryland, sa unang 151 araw, hindi puwedeng magsakay ang provisional driver na wala pang 18 ng mga pasaherong wala pang 18 maliban sa malapit na kapamilya, kung walang nagbabantay.","p":"Tama. Ang unang 151 araw, mga limang buwan."},"ar":{"q":"في Maryland، لأي مدة لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن ينقل ركّابًا أعمارهم أقل من 18 سنة ليسوا من العائلة القريبة، بدون سائق مشرف؟","o":["أول 30 يومًا","أول 151 يومًا","السنة الأولى","حتى عمر 21 سنة"],"h1":"هي حوالي خمسة أشهر.","h2":"في Maryland، خلال أول 151 يومًا، لا يجوز للسائق صاحب الرخصة المؤقتة الذي عمره أقل من 18 سنة أن ينقل ركّابًا أعمارهم أقل من 18 سنة غير العائلة القريبة إلا بوجود سائق مشرف.","p":"صحيح. أول 151 يومًا، حوالي خمسة أشهر."},"ref":{"doc":"MD","page":47}},{"id":"md-014","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, how much alcohol may a driver under 21 have in the blood while driving?","o":["Up to 0.08","Up to 0.05","None at all","Up to 0.10"],"h1":"People under 21 may not drink alcohol at all.","h2":"In Maryland, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, the limit is zero."},"es":{"q":"En Maryland, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años mientras maneja?","o":["Hasta 0.08","Hasta 0.05","Nada","Hasta 0.10"],"h1":"Las personas menores de 21 años no pueden tomar nada de alcohol.","h2":"En Maryland, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Si es menor de 21 años, el límite es cero."},"zh":{"q":"在 Maryland，21 岁以下的司机开车时血液里可以有多少酒精？","o":["最多 0.08","最多 0.05","一点都不可以","最多 0.10"],"h1":"21 岁以下的人完全不能喝酒。","h2":"在 Maryland，21 岁以下的司机血液里有任何酒精都不能开车。","p":"对。21 岁以下，上限是零。"},"vi":{"q":"Ở Maryland, người lái dưới 21 tuổi được có bao nhiêu cồn trong máu khi lái xe?","o":["Tối đa 0.08","Tối đa 0.05","Hoàn toàn không có","Tối đa 0.10"],"h1":"Người dưới 21 tuổi hoàn toàn không được uống rượu bia.","h2":"Ở Maryland, người lái dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, giới hạn là không."},"tl":{"q":"Sa Maryland, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21 habang nagmamaneho?","o":["Hanggang 0.08","Hanggang 0.05","Wala talaga","Hanggang 0.10"],"h1":"Hindi puwedeng uminom ng alak ang mga wala pang 21.","h2":"Sa Maryland, hindi puwedeng magmaneho ang driver na wala pang 21 kung may kahit kaunting alak sa dugo.","p":"Tama. Para sa wala pang 21, zero ang limitasyon."},"ar":{"q":"في Maryland، كم من الكحول يجوز أن يكون في دم السائق الذي عمره أقل من 21 سنة أثناء القيادة؟","o":["حتى 0.08","حتى 0.05","لا شيء أبدًا","حتى 0.10"],"h1":"من عمرهم أقل من 21 سنة لا يجوز لهم شرب الكحول أبدًا.","h2":"في Maryland لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. أقل من 21 سنة، الحدّ هو صفر."},"ref":{"doc":"MD","page":33}},{"id":"md-015","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maryland, which stopped vehicles does the Move Over law cover?","o":["Only police cars","Only ambulances and fire trucks","Only tow trucks","Any stopped vehicle showing hazard lights, flares or cones"],"h1":"The law covers more than emergency vehicles.","h2":"In Maryland, you must move over, or slow down if you cannot, for any stopped vehicle showing hazard lights, road flares or traffic cones.","p":"Right. Any stopped vehicle with warning signals."},"es":{"q":"En Maryland, ¿qué vehículos detenidos cubre la ley Move Over (cámbiese de carril)?","o":["Solo patrullas de policía","Solo ambulancias y bomberos","Solo grúas","Cualquier vehículo detenido con luces intermitentes, bengalas o conos"],"h1":"La ley cubre más que los vehículos de emergencia.","h2":"En Maryland, usted debe cambiarse de carril, o bajar la velocidad si no puede, ante cualquier vehículo detenido con luces de emergencia, bengalas o conos.","p":"Correcto. Cualquier vehículo detenido con señales de advertencia."},"zh":{"q":"在 Maryland，Move Over 法保护哪些停着的车辆？","o":["只有警车","只有救护车和消防车","只有拖车","任何开着双闪灯、摆着照明弹或锥形路标的停着的车辆"],"h1":"这条法律保护的不只是急救车辆。","h2":"在 Maryland，遇到任何开着双闪灯、摆着道路照明弹或交通锥的停着的车辆，你都必须换道让开，如果不能换道就要减速。","p":"对。任何有警示信号、停着的车辆。"},"vi":{"q":"Ở Maryland, luật Tránh Sang Làn Khác (Move Over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe kéo","Bất kỳ xe đang dừng nào bật đèn cảnh báo, đặt pháo sáng hoặc cọc nón giao thông"],"h1":"Luật này áp dụng cho nhiều hơn xe khẩn cấp.","h2":"Ở Maryland, bạn phải tránh sang làn khác, hoặc chạy chậm lại nếu không thể tránh, khi gặp bất kỳ xe đang dừng nào bật đèn cảnh báo, đặt pháo sáng hoặc cọc nón giao thông.","p":"Đúng. Bất kỳ xe đang dừng nào có tín hiệu cảnh báo."},"tl":{"q":"Sa Maryland, aling mga nakahintong sasakyan ang sakop ng Move Over law?","o":["Mga sasakyan lang ng pulis","Mga ambulansya at trak ng bumbero lang","Mga tow truck lang","Kahit anong nakahintong sasakyan na may hazard lights, flares o cones"],"h1":"Sakop ng batas ang higit pa sa mga emergency vehicle.","h2":"Sa Maryland, dapat kang lumipat ng lane, o bumagal kung hindi ka makalipat, para sa kahit anong nakahintong sasakyan na may hazard lights, road flares o traffic cones.","p":"Tama. Kahit anong nakahintong sasakyan na may babalang senyas."},"ar":{"q":"في Maryland، ما المركبات المتوقفة التي يشملها قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","شاحنات السحب فقط","أي مركبة متوقفة تُظهر أضواء التحذير أو مشاعل الطريق أو أقماع المرور"],"h1":"القانون يشمل أكثر من مركبات الطوارئ.","h2":"في Maryland يجب أن تنتقل إلى مسار آخر، أو تخفّف السرعة إذا لم تستطع، عند أي مركبة متوقفة تُظهر أضواء التحذير أو مشاعل الطريق أو أقماع المرور.","p":"صحيح. أي مركبة متوقفة عليها إشارات تحذير."},"ref":{"doc":"MD","page":45}},{"id":"md-016","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, a school bus stops with red lights flashing on a road split by a physical barrier. Who must stop?","o":["Traffic on the same side of the barrier as the bus","Traffic on both sides of the barrier","Only traffic on the other side of the barrier","No one, because of the barrier"],"h1":"Traffic on the far side of the barrier keeps going.","h2":"In Maryland, on a road divided by a physical barrier, traffic on the bus's side must stop, and traffic on the other side does not stop.","p":"Right. Only traffic on the bus's side of the barrier stops."},"es":{"q":"En Maryland, un autobús escolar se detiene con las luces rojas intermitentes en una carretera dividida por una barrera física. ¿Quién debe detenerse?","o":["El tráfico del mismo lado de la barrera que el autobús","El tráfico de ambos lados de la barrera","Solo el tráfico del otro lado de la barrera","Nadie, por la barrera"],"h1":"El tráfico del otro lado de la barrera sigue su camino.","h2":"En Maryland, en una carretera dividida por una barrera física, el tráfico del lado del autobús debe detenerse, y el tráfico del otro lado no se detiene.","p":"Correcto. Solo se detiene el tráfico del lado del autobús."},"zh":{"q":"在 Maryland，一辆校车在被实体隔离墩分开的道路上闪着红灯停下。谁必须停车？","o":["和校车在隔离墩同一边的车","隔离墩两边的车","只有隔离墩另一边的车","没有人，因为有隔离墩"],"h1":"隔离墩远的那一边的车可以继续开。","h2":"在 Maryland，在被实体隔离墩分开的道路上，校车那一边的车必须停车，另一边的车不用停。","p":"对。只有隔离墩校车那一边的车要停。"},"vi":{"q":"Ở Maryland, một xe buýt trường học dừng lại và nháy đèn đỏ trên con đường được chia đôi bằng dải phân cách cứng. Ai phải dừng lại?","o":["Xe cùng phía dải phân cách với xe buýt","Xe ở cả hai phía dải phân cách","Chỉ xe ở phía bên kia dải phân cách","Không ai cả, vì có dải phân cách"],"h1":"Xe ở phía bên kia dải phân cách tiếp tục đi.","h2":"Ở Maryland, trên con đường có dải phân cách cứng, xe cùng phía với xe buýt phải dừng lại, còn xe ở phía bên kia không cần dừng.","p":"Đúng. Chỉ xe cùng phía dải phân cách với xe buýt phải dừng."},"tl":{"q":"Sa Maryland, huminto ang school bus na kumikislap ang pulang ilaw sa daang hinati ng pisikal na harang. Sino ang dapat huminto?","o":["Ang mga sasakyan sa parehong panig ng harang kung nasaan ang bus","Ang mga sasakyan sa magkabilang panig ng harang","Ang mga sasakyan lang sa kabilang panig ng harang","Wala, dahil sa harang"],"h1":"Tuloy ang mga sasakyan sa kabilang panig ng harang.","h2":"Sa Maryland, sa daang hinati ng pisikal na harang, dapat huminto ang mga sasakyan sa panig ng bus, at hindi humihinto ang mga sasakyan sa kabilang panig.","p":"Tama. Ang mga sasakyan lang sa panig ng bus ang humihinto."},"ar":{"q":"في Maryland، توقفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق مقسوم بحاجز مادي. من يجب أن يتوقف؟","o":["المركبات في نفس جهة الحاجز التي فيها الحافلة","المركبات في جهتي الحاجز","المركبات في الجهة الأخرى من الحاجز فقط","لا أحد، بسبب الحاجز"],"h1":"المركبات في الجهة البعيدة من الحاجز تستمر في السير.","h2":"في Maryland، على طريق مقسوم بحاجز مادي، يجب أن تتوقف المركبات في جهة الحافلة، ولا تتوقف المركبات في الجهة الأخرى.","p":"صحيح. تتوقف فقط المركبات في جهة الحافلة من الحاجز."},"ref":{"doc":"MD","page":39}},{"id":"md-017","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, may an adult driver hold a cell phone to talk while driving?","o":["Yes, at any time","No, a hands-free device is required","Yes, but only on local streets","Yes, if driving under 30 mph"],"h1":"Your hands should stay on the wheel.","h2":"In Maryland, an adult driver may not hold a cell phone to talk while driving and must use a hands-free device, except to call 911.","p":"Right. Adults in Maryland must go hands-free."},"es":{"q":"En Maryland, ¿puede un conductor adulto sostener el celular para hablar mientras maneja?","o":["Sí, en cualquier momento","No, se requiere un dispositivo de manos libres","Sí, pero solo en calles locales","Sí, si va a menos de 30 mph"],"h1":"Sus manos deben quedarse en el volante.","h2":"En Maryland, un conductor adulto no puede sostener el celular para hablar mientras maneja y debe usar manos libres, excepto para llamar al 911.","p":"Correcto. Los adultos en Maryland deben usar manos libres."},"zh":{"q":"在 Maryland，成年司机开车时可以手拿手机通话吗？","o":["可以，任何时候都可以","不可以，必须用免提设备","可以，但只能在当地街道上","可以，只要车速低于 30 mph"],"h1":"你的手应该一直放在方向盘上。","h2":"在 Maryland，成年司机开车时不能手拿手机通话，必须用免提设备，打 911 除外。","p":"对。Maryland 的成年人必须用免提。"},"vi":{"q":"Ở Maryland, người lái trưởng thành có được cầm điện thoại để nói chuyện khi đang lái xe không?","o":["Có, bất cứ lúc nào","Không, phải dùng thiết bị rảnh tay","Có, nhưng chỉ trên đường trong khu vực","Có, nếu lái dưới 30 mph"],"h1":"Tay bạn nên giữ trên vô lăng.","h2":"Ở Maryland, người lái trưởng thành không được cầm điện thoại để nói chuyện khi lái xe và phải dùng thiết bị rảnh tay, trừ khi gọi 911.","p":"Đúng. Ở Maryland, người lớn phải dùng rảnh tay."},"tl":{"q":"Sa Maryland, puwede bang hawakan ng adultong driver ang cell phone para makipag-usap habang nagmamaneho?","o":["Oo, kahit kailan","Hindi, kailangan ng hands-free device","Oo, pero sa mga lokal na kalye lang","Oo, kung wala pang 30 mph ang takbo"],"h1":"Dapat nasa manibela ang mga kamay mo.","h2":"Sa Maryland, hindi puwedeng hawakan ng adultong driver ang cell phone para makipag-usap habang nagmamaneho at dapat gumamit ng hands-free device, maliban sa pagtawag sa 911.","p":"Tama. Dapat hands-free ang mga adulto sa Maryland."},"ar":{"q":"في Maryland، هل يجوز للسائق البالغ أن يمسك الهاتف المحمول بيده ليتكلم أثناء القيادة؟","o":["نعم، في أي وقت","لا، يجب استعمال جهاز بدون استعمال اليدين","نعم، ولكن في الشوارع المحلية فقط","نعم، إذا كانت السرعة أقل من 30 mph"],"h1":"يجب أن تبقى يداك على المقود.","h2":"في Maryland لا يجوز للسائق البالغ أن يمسك الهاتف المحمول بيده ليتكلم أثناء القيادة، ويجب أن يستعمل جهازًا بدون استعمال اليدين، إلا للاتصال بـ911.","p":"صحيح. البالغون في Maryland يجب أن يتكلموا بدون استعمال اليدين."},"ref":{"doc":"MD","page":35}},{"id":"md-018","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how long must you hold a provisional license before you can get a full driver's license?","o":["6 months","12 months","18 months","24 months"],"h1":"It is longer than one year.","h2":"In Maryland, you must hold a provisional license for at least 18 months before you can get a full driver's license.","p":"Right. The provisional stage lasts at least 18 months."},"es":{"q":"En Maryland, ¿cuánto tiempo debe tener una licencia provisional antes de obtener una licencia de conducir completa?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es más de un año.","h2":"En Maryland, debe tener una licencia provisional por lo menos 18 meses antes de obtener una licencia de conducir completa.","p":"Correcto. La etapa provisional dura por lo menos 18 meses."},"zh":{"q":"在 Maryland，必须持有过渡驾照（provisional license）多久，才能拿到正式驾照？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"比一年更长。","h2":"在 Maryland，你必须持有过渡驾照至少 18 个月，才能拿到正式驾照。","p":"对。过渡阶段至少 18 个月。"},"vi":{"q":"Ở Maryland, bạn phải giữ bằng lái tạm thời (provisional license) bao lâu trước khi lấy bằng lái chính thức?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Lâu hơn một năm.","h2":"Ở Maryland, bạn phải giữ bằng lái tạm thời ít nhất 18 tháng trước khi lấy bằng lái chính thức.","p":"Đúng. Giai đoạn bằng lái tạm thời kéo dài ít nhất 18 tháng."},"tl":{"q":"Sa Maryland, gaano katagal mo dapat hawak ang provisional license bago ka makakuha ng buong driver's license?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Mas matagal ito sa isang taon.","h2":"Sa Maryland, dapat mong hawak ang provisional license nang hindi bababa sa 18 buwan bago ka makakuha ng buong driver's license.","p":"Tama. Tumatagal nang hindi bababa sa 18 buwan ang provisional na yugto."},"ar":{"q":"في Maryland، كم يجب أن تحتفظ بالرخصة المؤقتة (provisional license) قبل أن تحصل على رخصة قيادة كاملة؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"المدة أطول من سنة واحدة.","h2":"في Maryland يجب أن تحتفظ بالرخصة المؤقتة 18 شهرًا على الأقل قبل أن تحصل على رخصة قيادة كاملة.","p":"صحيح. مرحلة الرخصة المؤقتة تستمر 18 شهرًا على الأقل."},"ref":{"doc":"MD","page":10}},{"id":"md-019","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long is a Type 1 learner's permit valid?","o":["Up to 2 years","Up to 6 months","Up to 1 year","Up to 5 years"],"h1":"It gives you plenty of time to practice.","h2":"In Maryland, a Type 1 learner's permit is valid for up to 2 years.","p":"Right. The learner's permit lasts up to 2 years."},"es":{"q":"En Maryland, ¿por cuánto tiempo es válido un permiso de aprendizaje Tipo 1?","o":["Hasta 2 años","Hasta 6 meses","Hasta 1 año","Hasta 5 años"],"h1":"Le da bastante tiempo para practicar.","h2":"En Maryland, un permiso de aprendizaje Tipo 1 es válido por hasta 2 años.","p":"Correcto. El permiso de aprendizaje dura hasta 2 años."},"zh":{"q":"在 Maryland，Type 1 学习驾照（learner's permit）的有效期是多久？","o":["最多 2 年","最多 6 个月","最多 1 年","最多 5 年"],"h1":"它给你足够的时间练习。","h2":"在 Maryland，Type 1 学习驾照的有效期最多 2 年。","p":"对。学习驾照最多有效 2 年。"},"vi":{"q":"Ở Maryland, giấy phép tập lái Type 1 (learner's permit) có hiệu lực bao lâu?","o":["Tối đa 2 năm","Tối đa 6 tháng","Tối đa 1 năm","Tối đa 5 năm"],"h1":"Nó cho bạn nhiều thời gian để tập.","h2":"Ở Maryland, giấy phép tập lái Type 1 có hiệu lực tối đa 2 năm.","p":"Đúng. Giấy phép tập lái có hiệu lực tối đa 2 năm."},"tl":{"q":"Sa Maryland, gaano katagal may bisa ang Type 1 learner's permit?","o":["Hanggang 2 taon","Hanggang 6 na buwan","Hanggang 1 taon","Hanggang 5 taon"],"h1":"Binibigyan ka nito ng maraming oras para magsanay.","h2":"Sa Maryland, may bisa ang Type 1 learner's permit nang hanggang 2 taon.","p":"Tama. May bisa ang learner's permit nang hanggang 2 taon."},"ar":{"q":"في Maryland، ما مدة صلاحية تصريح التعلّم من النوع Type 1 (learner's permit)؟","o":["حتى سنتين (2)","حتى 6 أشهر","حتى سنة واحدة (1)","حتى 5 سنوات"],"h1":"يعطيك وقتًا كافيًا للتدرّب.","h2":"في Maryland يكون تصريح التعلّم من النوع Type 1 صالحًا لمدة تصل إلى سنتين (2).","p":"صحيح. تصريح التعلّم صالح حتى سنتين (2)."},"ref":{"doc":"MD","page":9}},{"id":"md-020","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how much time do you have to finish the 25-question knowledge test?","o":["10 minutes","45 minutes","1 hour","20 minutes"],"h1":"It is less than half an hour.","h2":"In Maryland, you have 20 minutes to finish the 25-question knowledge test.","p":"Right. You get 20 minutes for the test."},"es":{"q":"En Maryland, ¿cuánto tiempo tiene para terminar el examen de conocimientos de 25 preguntas?","o":["10 minutos","45 minutos","1 hora","20 minutos"],"h1":"Es menos de media hora.","h2":"En Maryland, tiene 20 minutos para terminar el examen de conocimientos de 25 preguntas.","p":"Correcto. Tiene 20 minutos para el examen."},"zh":{"q":"在 Maryland，完成 25 道题的笔试有多少时间？","o":["10 分钟","45 分钟","1 小时","20 分钟"],"h1":"不到半小时。","h2":"在 Maryland，你有 20 分钟完成 25 道题的笔试。","p":"对。笔试有 20 分钟。"},"vi":{"q":"Ở Maryland, bạn có bao nhiêu thời gian để làm xong bài thi kiến thức 25 câu?","o":["10 phút","45 phút","1 giờ","20 phút"],"h1":"Ít hơn nửa giờ.","h2":"Ở Maryland, bạn có 20 phút để làm xong bài thi kiến thức 25 câu.","p":"Đúng. Bạn có 20 phút để làm bài thi."},"tl":{"q":"Sa Maryland, gaano karaming oras ang mayroon ka para tapusin ang knowledge test na may 25 tanong?","o":["10 minuto","45 minuto","1 oras","20 minuto"],"h1":"Mas maikli ito sa kalahating oras.","h2":"Sa Maryland, mayroon kang 20 minuto para tapusin ang knowledge test na may 25 tanong.","p":"Tama. May 20 minuto ka para sa test."},"ar":{"q":"في Maryland، كم من الوقت لديك لإنهاء اختبار المعرفة المكوّن من 25 سؤالًا؟","o":["10 دقائق","45 دقيقة","ساعة واحدة (1)","20 دقيقة"],"h1":"أقل من نصف ساعة.","h2":"في Maryland لديك 20 دقيقة لإنهاء اختبار المعرفة المكوّن من 25 سؤالًا.","p":"صحيح. لديك 20 دقيقة للاختبار."},"ref":{"doc":"MD","page":7}},{"id":"md-021","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, it is raining and you turn on your windshield wipers. What must you also turn on?","o":["Your hazard lights","Your headlights","Your high beams","Your interior lights"],"h1":"Other drivers need to see you in bad weather.","h2":"In Maryland, the law says you must turn on your headlights when you use your windshield wipers in bad weather.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Maryland, está lloviendo y usted enciende los limpiaparabrisas. ¿Qué más debe encender?","o":["Las luces de emergencia","Los faros delanteros","Las luces altas","Las luces interiores"],"h1":"Los demás conductores necesitan verlo con mal tiempo.","h2":"En Maryland, la ley dice que debe encender los faros delanteros cuando usa los limpiaparabrisas con mal tiempo.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 Maryland，下雨时你打开了雨刷。你还必须打开什么？","o":["危险警示灯","大灯","远光灯","车内灯"],"h1":"天气不好时，其他司机需要看到你。","h2":"在 Maryland，法律规定，天气不好使用雨刷时，你必须打开大灯。","p":"对。开雨刷，就要开大灯。"},"vi":{"q":"Ở Maryland, trời đang mưa và bạn bật cần gạt nước. Bạn cũng phải bật gì?","o":["Đèn báo nguy hiểm","Đèn pha","Đèn chiếu xa","Đèn trong xe"],"h1":"Người lái khác cần thấy bạn khi thời tiết xấu.","h2":"Ở Maryland, luật nói rằng bạn phải bật đèn pha khi dùng cần gạt nước lúc thời tiết xấu.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Maryland, umuulan at binuksan mo ang windshield wipers. Ano pa ang dapat mong buksan?","o":["Ang hazard lights mo","Ang headlights mo","Ang high beams mo","Ang mga ilaw sa loob ng sasakyan"],"h1":"Kailangan kang makita ng ibang driver kapag masama ang panahon.","h2":"Sa Maryland, sinasabi ng batas na dapat mong buksan ang headlights kapag gumagamit ka ng windshield wipers sa masamang panahon.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Maryland، الجو ممطر وشغّلت ماسحات الزجاج الأمامي. ماذا يجب أن تشغّل أيضًا؟","o":["أضواء التحذير (الطوارئ)","المصابيح الأمامية","الأضواء العالية","أضواء داخل السيارة"],"h1":"يحتاج السائقون الآخرون إلى رؤيتك في الطقس السيئ.","h2":"في Maryland يقول القانون إنه يجب أن تشغّل المصابيح الأمامية عندما تستخدم ماسحات الزجاج في الطقس السيئ.","p":"صحيح. إذا شغّلت الماسحات فشغّل المصابيح الأمامية."},"ref":{"doc":"MD","page":27}},{"id":"md-022","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, you must turn on your headlights when you cannot clearly see how far ahead?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"It is a long distance, about three football fields.","h2":"In Maryland, you must turn on your headlights whenever there is not enough light to see clearly at least 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, use your headlights."},"es":{"q":"En Maryland, debe encender los faros si no puede ver claramente hasta cierta distancia hacia adelante. ¿Cuál es esa distancia?","o":["200 pies","500 pies","1,000 pies","2,000 pies"],"h1":"Es una distancia larga, como tres campos de fútbol americano.","h2":"En Maryland, debe encender los faros siempre que no haya luz suficiente para ver claramente por lo menos 1,000 pies hacia adelante.","p":"Correcto. Si no puede ver 1,000 pies hacia adelante, use los faros."},"zh":{"q":"在 Maryland，当你看不清前方多远时，必须打开大灯？","o":["200 英尺","500 英尺","1,000 英尺","2,000 英尺"],"h1":"这是很长的距离，大约三个橄榄球场。","h2":"在 Maryland，只要光线不够，看不清前方至少 1,000 英尺，你就必须打开大灯。","p":"对。看不清前方 1,000 英尺，就要开大灯。"},"vi":{"q":"Ở Maryland, bạn phải bật đèn pha khi không thể nhìn rõ phía trước bao xa?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"Đó là một khoảng cách dài, khoảng ba sân bóng bầu dục.","h2":"Ở Maryland, bạn phải bật đèn pha bất cứ khi nào không đủ ánh sáng để nhìn rõ ít nhất 1,000 feet phía trước.","p":"Đúng. Nếu không thể nhìn thấy 1,000 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Maryland, dapat mong buksan ang headlights kapag hindi mo malinaw na makita ang daan hanggang gaano kalayo?","o":["200 talampakan","500 talampakan","1,000 talampakan","2,000 talampakan"],"h1":"Malayo ito, mga tatlong football field.","h2":"Sa Maryland, dapat mong buksan ang headlights tuwing kulang ang liwanag para malinaw na makita ang hindi bababa sa 1,000 talampakan sa unahan.","p":"Tama. Kung hindi mo makita ang 1,000 talampakan sa unahan, gamitin ang headlights."},"ar":{"q":"في Maryland، يجب أن تشغّل المصابيح الأمامية عندما لا تستطيع أن ترى بوضوح إلى أي مسافة أمامك؟","o":["200 قدم","500 قدم","1,000 قدم","2,000 قدم"],"h1":"إنها مسافة طويلة، نحو ثلاثة ملاعب كرة قدم أمريكية.","h2":"في Maryland يجب أن تشغّل المصابيح الأمامية كلما لم يكن الضوء كافيًا لترى بوضوح 1,000 قدم على الأقل أمامك.","p":"صحيح. إذا لم تستطع أن ترى 1,000 قدم أمامك فشغّل المصابيح الأمامية."},"ref":{"doc":"MD","page":27}},{"id":"md-023","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, what is the penalty for breaking the Move Over law when no crash happens?","o":["A $110 fine and 1 point","A $50 fine and no points","A $500 fine and 5 points","A warning only"],"h1":"Points are added to your driving record.","h2":"In Maryland, breaking the Move Over law without causing a crash brings a $110 fine and 1 point on your license.","p":"Right. It is a $110 fine and 1 point."},"es":{"q":"En Maryland, ¿cuál es la multa por no cumplir la ley Move Over (moverse de carril) si no hay choque?","o":["Una multa de $110 y 1 punto","Una multa de $50 y ningún punto","Una multa de $500 y 5 puntos","Solo una advertencia"],"h1":"Se agregan puntos a su historial de manejo.","h2":"En Maryland, no cumplir la ley Move Over sin causar un choque trae una multa de $110 y 1 punto en su licencia.","p":"Correcto. Es una multa de $110 y 1 punto."},"zh":{"q":"在 Maryland，违反 Move Over 法但没有发生车祸，会受到什么处罚？","o":["罚款 $110，扣 1 分","罚款 $50，不扣分","罚款 $500，扣 5 分","只有警告"],"h1":"你的驾驶记录上会被记分。","h2":"在 Maryland，违反 Move Over 法但没有造成车祸，会被罚款 $110，并在驾照上记 1 分。","p":"对。罚款 $110，记 1 分。"},"vi":{"q":"Ở Maryland, hình phạt cho việc vi phạm luật Tránh Sang Làn Khác (Move Over law) khi không xảy ra tai nạn là gì?","o":["Phạt $110 và 1 điểm","Phạt $50 và không bị điểm","Phạt $500 và 5 điểm","Chỉ bị cảnh cáo"],"h1":"Điểm bị ghi vào hồ sơ lái xe của bạn.","h2":"Ở Maryland, vi phạm luật Tránh Sang Làn Khác mà không gây tai nạn sẽ bị phạt $110 và bị ghi 1 điểm vào bằng lái.","p":"Đúng. Phạt $110 và 1 điểm."},"tl":{"q":"Sa Maryland, ano ang parusa sa paglabag sa Move Over law kapag walang nangyaring banggaan?","o":["Multang $110 at 1 puntos","Multang $50 at walang puntos","Multang $500 at 5 puntos","Babala lang"],"h1":"Nadaragdagan ng mga puntos ang driving record mo.","h2":"Sa Maryland, ang paglabag sa Move Over law nang walang banggaan ay may multang $110 at 1 puntos sa lisensya mo.","p":"Tama. Multang $110 at 1 puntos ito."},"ar":{"q":"في Maryland، ما عقوبة مخالفة قانون الابتعاد (Move Over law) عندما لا يقع حادث؟","o":["غرامة $110 ونقطة واحدة (1)","غرامة $50 بدون نقاط","غرامة $500 و5 نقاط","إنذار فقط"],"h1":"تُضاف نقاط إلى سجل قيادتك.","h2":"في Maryland تؤدي مخالفة قانون الابتعاد بدون التسبب في حادث إلى غرامة $110 ونقطة واحدة (1) على رخصتك.","p":"صحيح. العقوبة غرامة $110 ونقطة واحدة (1)."},"ref":{"doc":"MD","page":45}},{"id":"md-024","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a provisional driver under 18 is convicted of a second moving violation. What happens?","o":["Only a warning letter is sent","A 30-day suspension, then 90 days of driving only for work or school","The license is revoked for 5 years","A $25 fine and nothing else"],"h1":"The penalty grows with each offense.","h2":"In Maryland, a second moving violation for a provisional driver under 18 brings a 30-day suspension, followed by 90 days of driving only for work or school.","p":"Right. A second offense means a 30-day suspension and a 90-day work-or-school limit."},"es":{"q":"En Maryland, un conductor provisional menor de 18 años recibe una condena por una segunda infracción de tránsito. ¿Qué pasa?","o":["Solo se envía una carta de advertencia","Una suspensión de 30 días, luego 90 días de manejar solo para trabajo o escuela","La licencia se revoca por 5 años","Una multa de $25 y nada más"],"h1":"La pena aumenta con cada infracción.","h2":"En Maryland, una segunda infracción de tránsito de un conductor provisional menor de 18 años trae una suspensión de 30 días, seguida de 90 días de manejar solo para trabajo o escuela.","p":"Correcto. Una segunda infracción significa 30 días de suspensión y 90 días con límite de trabajo o escuela."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机第二次因行驶违章被定罪。会发生什么？","o":["只会寄一封警告信","吊销驾照 30 天，然后 90 天只能为上班或上学开车","驾照被撤销 5 年","罚款 $25，没有别的"],"h1":"每次违规，处罚都会更重。","h2":"在 Maryland，18 岁以下持过渡驾照的司机第二次行驶违章，会被吊销驾照 30 天，之后 90 天只能为上班或上学开车。","p":"对。第二次违规是吊销 30 天，再加 90 天只能上班或上学开车。"},"vi":{"q":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi bị kết tội vi phạm giao thông lần thứ hai. Điều gì xảy ra?","o":["Chỉ bị gửi thư cảnh cáo","Bị treo bằng 30 ngày, sau đó 90 ngày chỉ được lái xe để đi làm hoặc đi học","Bị thu hồi bằng lái 5 năm","Phạt $25 và không có gì khác"],"h1":"Hình phạt tăng lên với mỗi lần vi phạm.","h2":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi vi phạm giao thông lần thứ hai sẽ bị treo bằng 30 ngày, sau đó 90 ngày chỉ được lái xe để đi làm hoặc đi học.","p":"Đúng. Vi phạm lần thứ hai là treo bằng 30 ngày và 90 ngày chỉ lái để đi làm hoặc đi học."},"tl":{"q":"Sa Maryland, nahatulan ang isang provisional driver na wala pang 18 sa ikalawang moving violation. Ano ang mangyayari?","o":["Padadalhan lang ng sulat ng babala","Suspensyon nang 30 araw, pagkatapos ay 90 araw na pagmamaneho para lang sa trabaho o paaralan","Babawiin ang lisensya nang 5 taon","Multang $25 at wala nang iba"],"h1":"Lumalaki ang parusa sa bawat paglabag.","h2":"Sa Maryland, ang ikalawang moving violation ng provisional driver na wala pang 18 ay may suspensyon nang 30 araw, at pagkatapos ay 90 araw na pagmamaneho para lang sa trabaho o paaralan.","p":"Tama. Ang ikalawang paglabag ay suspensyon nang 30 araw at 90 araw na limitasyon sa trabaho o paaralan."},"ar":{"q":"في Maryland، أُدين سائق صاحب رخصة مؤقتة عمره أقل من 18 سنة بمخالفة مرورية ثانية أثناء القيادة. ماذا يحدث؟","o":["تُرسل رسالة تحذير فقط","إيقاف الرخصة 30 يومًا، ثم 90 يومًا من القيادة للعمل أو المدرسة فقط","تُلغى الرخصة لمدة 5 سنوات","غرامة $25 ولا شيء غيرها"],"h1":"تزيد العقوبة مع كل مخالفة.","h2":"في Maryland تؤدي المخالفة المرورية الثانية لسائق صاحب رخصة مؤقتة عمره أقل من 18 سنة إلى إيقاف الرخصة 30 يومًا، ثم 90 يومًا من القيادة للعمل أو المدرسة فقط.","p":"صحيح. المخالفة الثانية تعني إيقافًا لمدة 30 يومًا، ثم 90 يومًا للعمل أو المدرسة فقط."},"ref":{"doc":"MD","page":49}},{"id":"md-025","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, which children must ride in a child safety seat?","o":["Only children under 2","Only children under 4","Children under 12 who weigh under 100 pounds","Children under 8, unless they are 4 feet 9 inches or taller"],"h1":"Think of both age and height.","h2":"In Maryland, children under 8 must ride in a child safety seat, unless they are 4 feet 9 inches or taller.","p":"Right. Under 8 means a safety seat, unless the child is 4 feet 9 inches or taller."},"es":{"q":"En Maryland, ¿qué niños deben viajar en un asiento de seguridad para niños?","o":["Solo los menores de 2 años","Solo los menores de 4 años","Los menores de 12 años que pesan menos de 100 libras","Los menores de 8 años, a menos que midan 4 pies 9 pulgadas o más"],"h1":"Piense en la edad y en la estatura.","h2":"En Maryland, los niños menores de 8 años deben viajar en un asiento de seguridad, a menos que midan 4 pies 9 pulgadas o más.","p":"Correcto. Los menores de 8 años usan asiento de seguridad, a menos que midan 4 pies 9 pulgadas o más."},"zh":{"q":"在 Maryland，哪些孩子必须坐儿童安全座椅？","o":["只有 2 岁以下的孩子","只有 4 岁以下的孩子","12 岁以下、体重不到 100 磅的孩子","8 岁以下的孩子，除非身高达到 4 英尺 9 英寸或以上"],"h1":"同时想想年龄和身高。","h2":"在 Maryland，8 岁以下的孩子必须坐儿童安全座椅，除非身高达到 4 英尺 9 英寸或以上。","p":"对。8 岁以下要坐安全座椅，除非孩子身高达到 4 英尺 9 英寸或以上。"},"vi":{"q":"Ở Maryland, những trẻ em nào phải ngồi ghế an toàn cho trẻ em?","o":["Chỉ trẻ dưới 2 tuổi","Chỉ trẻ dưới 4 tuổi","Trẻ dưới 12 tuổi nặng dưới 100 pound","Trẻ dưới 8 tuổi, trừ khi cao từ 4 feet 9 inch trở lên"],"h1":"Hãy nghĩ đến cả tuổi và chiều cao.","h2":"Ở Maryland, trẻ dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em, trừ khi cao từ 4 feet 9 inch trở lên.","p":"Đúng. Dưới 8 tuổi thì ngồi ghế an toàn, trừ khi trẻ cao từ 4 feet 9 inch trở lên."},"tl":{"q":"Sa Maryland, aling mga bata ang dapat nakaupo sa child safety seat?","o":["Mga batang wala pang 2 lang","Mga batang wala pang 4 lang","Mga batang wala pang 12 na wala pang 100 libra ang timbang","Mga batang wala pang 8, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad sila"],"h1":"Isipin ang edad at ang taas.","h2":"Sa Maryland, dapat nakaupo sa child safety seat ang mga batang wala pang 8, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad sila.","p":"Tama. Kapag wala pang 8, safety seat, maliban kung 4 na talampakan at 9 na pulgada o mas matangkad ang bata."},"ar":{"q":"في Maryland، أي الأطفال يجب أن يجلسوا في مقعد أمان للأطفال؟","o":["الأطفال الذين أعمارهم أقل من سنتين (2) فقط","الأطفال الذين أعمارهم أقل من 4 سنوات فقط","الأطفال الذين أعمارهم أقل من 12 سنة ووزنهم أقل من 100 رطل","الأطفال الذين أعمارهم أقل من 8 سنوات، إلا إذا كان طولهم 4 أقدام و9 بوصات أو أكثر"],"h1":"فكّر في العمر والطول معًا.","h2":"في Maryland يجب أن يجلس الأطفال الذين أعمارهم أقل من 8 سنوات في مقعد أمان للأطفال، إلا إذا كان طولهم 4 أقدام و9 بوصات أو أكثر.","p":"صحيح. أقل من 8 سنوات يعني مقعد أمان، إلا إذا كان طول الطفل 4 أقدام و9 بوصات أو أكثر."},"ref":{"doc":"MD","page":52}},{"id":"md-026","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, what is the rule about earphones while driving?","o":["You may wear them in both ears at low volume","They are allowed only on highways","You may not wear them in both ears","They are allowed only for drivers over 21"],"h1":"You need to hear sirens and horns around you.","h2":"In Maryland, covering both ears with earphones, a headset or earplugs while driving is not allowed. Hearing aids are fine.","p":"Right. Never cover both ears while driving."},"es":{"q":"En Maryland, ¿cuál es la regla sobre los audífonos al manejar?","o":["Puede usarlos en ambos oídos a bajo volumen","Solo se permiten en las autopistas","No puede usarlos en ambos oídos","Solo se permiten a conductores mayores de 21 años"],"h1":"Necesita oír las sirenas y bocinas a su alrededor.","h2":"En Maryland, no se permite manejar con los dos oídos tapados por audífonos, auriculares o tapones. Los aparatos auditivos sí se permiten.","p":"Correcto. Nunca se tape ambos oídos al manejar."},"zh":{"q":"在 Maryland，开车时戴耳机有什么规定？","o":["音量小的话，两只耳朵都可以戴","只在高速公路上可以戴","两只耳朵不能都戴","只有 21 岁以上的司机可以戴"],"h1":"你需要听到周围的警笛声和喇叭声。","h2":"在 Maryland，开车时不可以用耳机、头戴式耳机或耳塞把两只耳朵都盖住。助听器可以戴。","p":"对。开车时绝不要把两只耳朵都盖住。"},"vi":{"q":"Ở Maryland, quy định về tai nghe khi lái xe là gì?","o":["Bạn có thể đeo ở cả hai tai nếu để âm lượng nhỏ","Chỉ được phép trên xa lộ","Bạn không được đeo ở cả hai tai","Chỉ được phép cho tài xế trên 21 tuổi"],"h1":"Bạn cần nghe được còi hụ và tiếng còi xe xung quanh.","h2":"Ở Maryland, không được che cả hai tai bằng tai nghe, headset hoặc nút bịt tai khi lái xe. Máy trợ thính thì được phép.","p":"Đúng. Không bao giờ che cả hai tai khi lái xe."},"tl":{"q":"Sa Maryland, ano ang patakaran tungkol sa earphones habang nagmamaneho?","o":["Puwede mong isuot sa dalawang tainga kung mahina ang volume","Pinapayagan lang sa mga highway","Hindi mo puwedeng isuot sa dalawang tainga","Pinapayagan lang sa mga driver na lampas 21"],"h1":"Kailangan mong marinig ang mga sirena at busina sa paligid mo.","h2":"Sa Maryland, hindi pinapayagang takpan ang dalawang tainga ng earphones, headset o earplugs habang nagmamaneho. Puwede ang hearing aids.","p":"Tama. Huwag kailanman takpan ang dalawang tainga habang nagmamaneho."},"ar":{"q":"في Maryland، ما القاعدة بخصوص سماعات الأذن أثناء القيادة؟","o":["يمكنك وضعها في الأذنين بصوت منخفض","مسموح بها على الطرق السريعة فقط","لا يُسمح لك بوضعها في الأذنين معًا","مسموح بها فقط للسائقين فوق 21 سنة"],"h1":"تحتاج أن تسمع صفارات الإنذار وأبواق السيارات حولك.","h2":"في Maryland، لا يُسمح بتغطية الأذنين معًا بسماعات أذن أو سماعة رأس أو سدادات أذن أثناء القيادة. أما أجهزة السمع فمسموح بها.","p":"صحيح. لا تغطِّ أذنيك الاثنتين أبدًا أثناء القيادة."},"ref":{"doc":"MD","page":53}},{"id":"md-027","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, what visual acuity do you need in each eye to qualify for a driver's license?","o":["At least 20/100","At least 20/40","At least 20/10","At least 20/200"],"h1":"Glasses or contact lenses may be used to reach it.","h2":"In Maryland, you need visual acuity of at least 20/40 in each eye, with glasses or contacts if needed, to qualify for a driver's license.","p":"Right. You need at least 20/40 in each eye."},"es":{"q":"En Maryland, ¿qué agudeza visual necesita en cada ojo para calificar para una licencia de conducir?","o":["Por lo menos 20/100","Por lo menos 20/40","Por lo menos 20/10","Por lo menos 20/200"],"h1":"Puede usar anteojos o lentes de contacto para lograrla.","h2":"En Maryland, usted necesita una agudeza visual de por lo menos 20/40 en cada ojo, con anteojos o lentes de contacto si hace falta, para calificar para una licencia de conducir.","p":"Correcto. Necesita por lo menos 20/40 en cada ojo."},"zh":{"q":"在 Maryland，每只眼睛的视力至少要达到多少，才能拿到驾照？","o":["至少 20/100","至少 20/40","至少 20/10","至少 20/200"],"h1":"可以戴眼镜或隐形眼镜来达到这个标准。","h2":"在 Maryland，每只眼睛的视力必须至少达到 20/40（需要时可以戴眼镜或隐形眼镜），才能拿到驾照。","p":"对。每只眼睛至少要 20/40。"},"vi":{"q":"Ở Maryland, mỗi mắt cần thị lực ít nhất bao nhiêu để được cấp bằng lái xe?","o":["Ít nhất 20/100","Ít nhất 20/40","Ít nhất 20/10","Ít nhất 20/200"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng để đạt mức này.","h2":"Ở Maryland, mỗi mắt của bạn phải có thị lực ít nhất 20/40, có thể đeo kính hoặc kính áp tròng nếu cần, để được cấp bằng lái xe.","p":"Đúng. Mỗi mắt cần ít nhất 20/40."},"tl":{"q":"Sa Maryland, gaano kalinaw ang paningin na kailangan sa bawat mata para makakuha ng driver's license?","o":["Hindi bababa sa 20/100","Hindi bababa sa 20/40","Hindi bababa sa 20/10","Hindi bababa sa 20/200"],"h1":"Puwedeng gumamit ng salamin sa mata o contact lens para maabot ito.","h2":"Sa Maryland, kailangan mo ng paningin na hindi bababa sa 20/40 sa bawat mata, gamit ang salamin o contact lens kung kailangan, para makakuha ng driver's license.","p":"Tama. Kailangan ng hindi bababa sa 20/40 sa bawat mata."},"ar":{"q":"في Maryland، ما حدّة البصر التي تحتاجها في كل عين للحصول على رخصة القيادة؟","o":["20/100 على الأقل","20/40 على الأقل","20/10 على الأقل","20/200 على الأقل"],"h1":"يمكنك استخدام النظارات أو العدسات اللاصقة للوصول إليها.","h2":"في Maryland تحتاج إلى حدّة بصر 20/40 على الأقل في كل عين، مع النظارات أو العدسات اللاصقة إذا لزم الأمر، للحصول على رخصة القيادة.","p":"صحيح. تحتاج إلى 20/40 على الأقل في كل عين."},"ref":{"doc":"MD","page":7}},{"id":"md-028","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, how much space must you leave between your vehicle and a bicycle when you pass it?","o":["At least 1 foot","At least 10 feet","At least 2 feet","At least 3 feet"],"h1":"Think of about one long step.","h2":"In Maryland, you must leave at least 3 feet between your vehicle and a bicycle when you pass it, even in a bike lane or on the shoulder.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Maryland, ¿cuánto espacio debe dejar entre su vehículo y una bicicleta al pasarla?","o":["Por lo menos 1 pie","Por lo menos 10 pies","Por lo menos 2 pies","Por lo menos 3 pies"],"h1":"Piense en un paso largo.","h2":"En Maryland, usted debe dejar por lo menos 3 pies entre su vehículo y una bicicleta al pasarla, también en un carril para bicicletas o en el acotamiento.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Maryland，超过一辆自行车时，你的车和自行车之间必须留多少距离？","o":["至少 1 英尺","至少 10 英尺","至少 2 英尺","至少 3 英尺"],"h1":"大约是一大步的长度。","h2":"在 Maryland，超过自行车时，你的车和自行车之间必须至少留 3 英尺，即使自行车在自行车道或路肩上也一样。","p":"对。至少留 3 英尺。"},"vi":{"q":"Ở Maryland, khi vượt một xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 1 foot","Ít nhất 10 feet","Ít nhất 2 feet","Ít nhất 3 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Maryland, khi vượt xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và xe đạp, kể cả khi xe đạp ở trong làn xe đạp hoặc trên lề đường.","p":"Đúng. Chừa ít nhất 3 feet."},"tl":{"q":"Sa Maryland, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng sasakyan mo at ng bisikleta kapag inuunahan mo ito?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 10 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 3 talampakan"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Maryland, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng sasakyan mo at ng bisikleta kapag inuunahan mo ito, kahit nasa bike lane o nasa gilid ng daan ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Maryland، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية عندما تتجاوزها؟","o":["قدم واحدة (1) على الأقل","10 أقدام على الأقل","قدمان (2) على الأقل","3 أقدام على الأقل"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Maryland يجب أن تترك 3 أقدام على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها، حتى لو كانت في مسار الدراجات أو على كتف الطريق.","p":"صحيح. اترك 3 أقدام على الأقل."},"ref":{"doc":"MD","page":40}},{"id":"md-029","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["At least 500 feet before you reach it","When it is 50 feet away","Only after it passes you","At least 2 miles before you reach it"],"h1":"It is the length of more than one football field.","h2":"In Maryland, you must switch to low beams at least 500 feet before you reach a vehicle coming toward you.","p":"Right. Switch at least 500 feet before it."},"es":{"q":"En Maryland, usted usa las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Por lo menos 500 pies antes de llegar a él","Cuando esté a 50 pies","Solo después de que le pase","Por lo menos 2 millas antes de llegar a él"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Maryland, usted debe cambiar a luces bajas por lo menos 500 pies antes de llegar a un vehículo que viene de frente.","p":"Correcto. Cambie por lo menos 500 pies antes."},"zh":{"q":"在 Maryland，你晚上开着远光灯，有一辆车迎面开来。你必须在什么时候换成近光灯？","o":["在离它至少 500 英尺之前","在它离你 50 英尺时","只在它开过你之后","在离它至少 2 英里之前"],"h1":"这比一个橄榄球场还长。","h2":"在 Maryland，你必须在离迎面来车至少 500 英尺之前换成近光灯。","p":"对。至少在 500 英尺之前换灯。"},"vi":{"q":"Ở Maryland, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Có một xe đang chạy về phía bạn. Khi nào bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Ít nhất 500 feet trước khi gặp xe đó","Khi xe đó cách 50 feet","Chỉ sau khi xe đó đã chạy qua","Ít nhất 2 dặm trước khi gặp xe đó"],"h1":"Khoảng cách này dài hơn một sân bóng bầu dục.","h2":"Ở Maryland, bạn phải chuyển sang đèn cốt ít nhất 500 feet trước khi gặp xe đang chạy về phía bạn.","p":"Đúng. Chuyển đèn ít nhất 500 feet trước khi gặp xe."},"tl":{"q":"Sa Maryland, gumagamit ka ng high beam sa gabi. May sasakyang paparating sa iyo. Kailan mo dapat ilipat sa low beam?","o":["Hindi bababa sa 500 talampakan bago mo ito marating","Kapag 50 talampakan na lang ang layo nito","Pagkatapos lang itong makalampas sa iyo","Hindi bababa sa 2 milya bago mo ito marating"],"h1":"Mas mahaba ito kaysa sa isang football field.","h2":"Sa Maryland, dapat kang lumipat sa low beam nang hindi bababa sa 500 talampakan bago mo marating ang sasakyang paparating sa iyo.","p":"Tama. Lumipat nang hindi bababa sa 500 talampakan bago ito."},"ar":{"q":"في Maryland، أنت تستخدم الأضواء العالية في الليل، وهناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["قبل الوصول إليها بـ 500 قدم على الأقل","عندما تكون على بعد 50 قدمًا","فقط بعد أن تتجاوزك","قبل الوصول إليها بميلين (2) على الأقل"],"h1":"هي أطول من ملعب كرة قدم أمريكية واحد.","h2":"في Maryland يجب أن تنتقل إلى الأضواء المنخفضة قبل الوصول إلى السيارة القادمة نحوك بـ 500 قدم على الأقل.","p":"صحيح. انتقل إلى الأضواء المنخفضة قبلها بـ 500 قدم على الأقل."},"ref":{"doc":"MD","page":27}},{"id":"md-030","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, which of these counts as an open container of alcohol in the passenger area?","o":["A sealed bottle in the trunk","A closed case of soda","A six-pack with some cans missing or empty","An empty water bottle in a cup holder"],"h1":"Think about a package that has already been opened.","h2":"In Maryland, a six-pack with open, empty or missing cans or bottles can count as an open container, and it is illegal in the passenger area.","p":"Right. A six-pack with missing or empty cans can count as open."},"es":{"q":"En Maryland, ¿cuál de estos cuenta como un envase abierto de alcohol en el área de pasajeros?","o":["Una botella sellada en el maletero","Una caja cerrada de refrescos","Un paquete de seis con algunas latas que faltan o están vacías","Una botella de agua vacía en un portavasos"],"h1":"Piense en un paquete que ya se abrió.","h2":"En Maryland, un paquete de seis con latas o botellas abiertas, vacías o que faltan puede contar como un envase abierto, y es ilegal en el área de pasajeros.","p":"Correcto. Un paquete de seis con latas que faltan o vacías puede contar como abierto."},"zh":{"q":"在 Maryland，下面哪一种在乘客区里算是打开的酒类容器？","o":["后备箱里一瓶密封的酒","一箱没打开的汽水","一组六罐装，里面有的罐子不见了或是空的","杯架上一个空水瓶"],"h1":"想想已经被打开过的包装。","h2":"在 Maryland，一组六罐装里如果有打开、空的或不见了的罐子或瓶子，就可能算是打开的酒类容器，放在乘客区是违法的。","p":"对。少了罐子或有空罐的六罐装可能算是打开的容器。"},"vi":{"q":"Ở Maryland, vật nào sau đây được tính là đồ chứa rượu bia đã mở trong khu vực hành khách?","o":["Một chai còn niêm phong trong cốp xe","Một thùng nước ngọt còn đóng","Một lốc sáu lon bị thiếu lon hoặc có lon rỗng","Một chai nước rỗng trong chỗ để ly"],"h1":"Hãy nghĩ đến một gói hàng đã bị mở ra.","h2":"Ở Maryland, một lốc sáu lon có lon hoặc chai đã mở, rỗng hoặc bị thiếu có thể được tính là đồ chứa đã mở, và để nó trong khu vực hành khách là phạm luật.","p":"Đúng. Một lốc sáu lon bị thiếu lon hoặc có lon rỗng có thể được tính là đã mở."},"tl":{"q":"Sa Maryland, alin dito ang itinuturing na bukas na lalagyan ng alak sa bahagi ng mga pasahero?","o":["Isang selyadong bote sa trunk","Isang saradong kahon ng soda","Isang six-pack na may nawawala o walang lamang lata","Isang walang lamang bote ng tubig sa lalagyan ng baso"],"h1":"Isipin ang isang pakete na nabuksan na.","h2":"Sa Maryland, ang isang six-pack na may bukas, walang laman, o nawawalang lata o bote ay puwedeng ituring na bukas na lalagyan, at bawal ito sa bahagi ng mga pasahero.","p":"Tama. Ang six-pack na may nawawala o walang lamang lata ay puwedeng ituring na bukas."},"ar":{"q":"في Maryland، أيّ مما يلي يُعتبر وعاءً مفتوحًا للكحول في مكان الركّاب؟","o":["زجاجة مغلقة بإحكام في صندوق السيارة","صندوق مغلق من المشروبات الغازية","علبة من ست عبوات فيها عبوات ناقصة أو فارغة","زجاجة ماء فارغة في حامل الأكواب"],"h1":"فكّر في عبوة تم فتحها من قبل.","h2":"في Maryland يمكن أن تُعتبر علبة الست عبوات التي فيها عبوات أو زجاجات مفتوحة أو فارغة أو ناقصة وعاءً مفتوحًا، ووجودها في مكان الركّاب مخالف للقانون.","p":"صحيح. علبة الست عبوات التي فيها عبوات ناقصة أو فارغة يمكن أن تُعتبر مفتوحة."},"ref":{"doc":"MD","page":33}},{"id":"md-031","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maryland, how close to an intersection or railroad crossing may you be when you pass another vehicle?","o":["Within 10 feet","Not within 100 feet","Within 50 feet","Any distance, if you signal"],"h1":"It is about the length of six or seven cars.","h2":"In Maryland, you may not pass when you are crossing or within 100 feet of an intersection or a railroad crossing.","p":"Right. Do not pass within 100 feet of them."},"es":{"q":"En Maryland, ¿qué tan cerca de una intersección o un cruce de ferrocarril puede estar al pasar a otro vehículo?","o":["A 10 pies","No a menos de 100 pies","A 50 pies","A cualquier distancia, si usa la señal"],"h1":"Es como el largo de seis o siete carros.","h2":"En Maryland, no puede pasar a otro vehículo al cruzar una intersección o un cruce de ferrocarril, ni a menos de 100 pies de ellos.","p":"Correcto. No pase a menos de 100 pies de ellos."},"zh":{"q":"在 Maryland，超车时你离路口或铁路道口可以有多近？","o":["10 英尺以内","不可以在 100 英尺以内","50 英尺以内","只要打灯，多近都可以"],"h1":"大约是六七辆车的长度。","h2":"在 Maryland，正在通过路口或铁路道口时，或离它们 100 英尺以内时，你不可以超车。","p":"对。离它们 100 英尺以内不要超车。"},"vi":{"q":"Ở Maryland, khi vượt xe khác, bạn được phép ở gần giao lộ hoặc chỗ băng qua đường sắt đến mức nào?","o":["Trong vòng 10 feet","Không được trong vòng 100 feet","Trong vòng 50 feet","Khoảng cách nào cũng được, nếu bạn bật đèn xi nhan"],"h1":"Khoảng cách đó dài bằng khoảng sáu hoặc bảy chiếc xe.","h2":"Ở Maryland, bạn không được vượt xe khi đang băng qua hoặc ở trong vòng 100 feet của một giao lộ hoặc chỗ băng qua đường sắt.","p":"Đúng. Không vượt xe trong vòng 100 feet của những chỗ đó."},"tl":{"q":"Sa Maryland, gaano ka kalapit sa intersection o tawiran ng tren kapag nag-oovertake ka sa ibang sasakyan?","o":["Sa loob ng 10 talampakan","Hindi sa loob ng 100 talampakan","Sa loob ng 50 talampakan","Kahit anong layo, kung magsesenyas ka"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Maryland, hindi ka puwedeng mag-overtake habang tumatawid ka o nasa loob ng 100 talampakan ng isang intersection o tawiran ng tren.","p":"Tama. Huwag mag-overtake sa loob ng 100 talampakan ng mga ito."},"ar":{"q":"في Maryland، ما مدى قربك من التقاطع أو من معبر السكة الحديدية عندما تتجاوز سيارة أخرى؟","o":["في حدود 10 أقدام","ليس في حدود 100 قدم","في حدود 50 قدمًا","أي مسافة، إذا أعطيت إشارة"],"h1":"هي تقريبًا طول ست أو سبع سيارات.","h2":"في Maryland لا يجوز لك أن تتجاوز وأنت تعبر تقاطعًا أو معبر سكة حديدية، أو وأنت في حدود 100 قدم منهما.","p":"صحيح. لا تتجاوز في حدود 100 قدم منهما."},"ref":{"doc":"MD","page":16}},{"id":"md-032","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a licensed driver gets a Type 2 learner's permit for a different class of license. How long must they hold it before taking the driving test?","o":["At least 14 days","At least 9 months","At least 45 days","At least 6 months"],"h1":"It is a short wait, because this person can already drive.","h2":"In Maryland, you may take the driving test once you have held a Type 2 learner's permit for at least 14 days.","p":"Right. A Type 2 permit must be held at least 14 days before the driving test."},"es":{"q":"En Maryland, un conductor con licencia obtiene un permiso de aprendizaje Tipo 2 para otra clase de licencia. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["Al menos 14 días","Al menos 9 meses","Al menos 45 días","Al menos 6 meses"],"h1":"Es una espera corta, porque esta persona ya sabe manejar.","h2":"En Maryland, puede tomar el examen de manejo cuando haya tenido el permiso de aprendizaje Tipo 2 por al menos 14 días.","p":"Correcto. El permiso Tipo 2 se debe tener al menos 14 días antes del examen de manejo."},"zh":{"q":"在 Maryland，已有驾照的司机为了另一类驾照拿到 Type 2 学习驾照（learner's permit）。必须持有多久才能参加路考？","o":["至少 14 天","至少 9 个月","至少 45 天","至少 6 个月"],"h1":"等待时间很短，因为这个人已经会开车。","h2":"在 Maryland，持有 Type 2 学习驾照至少 14 天后，你就可以参加路考。","p":"对。Type 2 学习驾照必须持有至少 14 天，才能参加路考。"},"vi":{"q":"Ở Maryland, một người đã có bằng lái lấy giấy phép tập lái Type 2 (learner's permit) cho một hạng bằng lái khác. Họ phải giữ giấy phép này bao lâu trước khi thi lái xe?","o":["Ít nhất 14 ngày","Ít nhất 9 tháng","Ít nhất 45 ngày","Ít nhất 6 tháng"],"h1":"Thời gian chờ ngắn, vì người này đã biết lái xe.","h2":"Ở Maryland, bạn được thi lái xe khi đã giữ giấy phép tập lái Type 2 ít nhất 14 ngày.","p":"Đúng. Giấy phép Type 2 phải được giữ ít nhất 14 ngày trước khi thi lái xe."},"tl":{"q":"Sa Maryland, kumuha ng Type 2 learner's permit ang isang driver na may lisensya na, para sa ibang klase ng lisensya. Gaano katagal dapat niya itong hawak bago kumuha ng driving test?","o":["Hindi bababa sa 14 na araw","Hindi bababa sa 9 na buwan","Hindi bababa sa 45 araw","Hindi bababa sa 6 na buwan"],"h1":"Maikli ang paghihintay, dahil marunong nang magmaneho ang taong ito.","h2":"Sa Maryland, puwede ka nang kumuha ng driving test kapag hawak mo na ang Type 2 learner's permit nang hindi bababa sa 14 na araw.","p":"Tama. Dapat hawak ang Type 2 permit nang hindi bababa sa 14 na araw bago ang driving test."},"ar":{"q":"في Maryland، حصل سائق لديه رخصة على تصريح تعلّم من النوع Type 2 (learner's permit) لفئة رخصة أخرى. كم يجب أن يحتفظ به قبل اختبار القيادة؟","o":["14 يومًا على الأقل","9 أشهر على الأقل","45 يومًا على الأقل","6 أشهر على الأقل"],"h1":"الانتظار قصير، لأن هذا الشخص يعرف القيادة من قبل.","h2":"في Maryland يمكنك أن تتقدّم لاختبار القيادة بعد أن تحتفظ بتصريح التعلّم من النوع Type 2 مدة 14 يومًا على الأقل.","p":"صحيح. يجب الاحتفاظ بتصريح Type 2 مدة 14 يومًا على الأقل قبل اختبار القيادة."},"ref":{"doc":"MD","page":9}},{"id":"md-033","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how many documents proving that you live in Maryland must you bring when you apply for a license?","o":["One","Two","Three","None, if you have a passport"],"h1":"It is more than one.","h2":"In Maryland, you must bring two documents that prove you live in Maryland when you apply.","p":"Right. Bring two proofs that you live in Maryland."},"es":{"q":"En Maryland, ¿cuántos documentos que prueben que vive en Maryland debe traer cuando solicita una licencia?","o":["Uno","Dos","Tres","Ninguno, si tiene pasaporte"],"h1":"Es más de uno.","h2":"En Maryland, debe traer dos documentos que prueben que vive en Maryland cuando hace la solicitud.","p":"Correcto. Traiga dos pruebas de que vive en Maryland."},"zh":{"q":"在 Maryland，申请驾照时，你必须带几份证明你住在 Maryland 的文件？","o":["一份","两份","三份","不用带，如果你有护照"],"h1":"不止一份。","h2":"在 Maryland，申请时你必须带两份证明你住在 Maryland 的文件。","p":"对。要带两份证明你住在 Maryland 的文件。"},"vi":{"q":"Ở Maryland, khi nộp đơn xin bằng lái, bạn phải mang bao nhiêu giấy tờ chứng minh bạn sống ở Maryland?","o":["Một","Hai","Ba","Không cần, nếu bạn có hộ chiếu"],"h1":"Nhiều hơn một.","h2":"Ở Maryland, khi nộp đơn bạn phải mang hai giấy tờ chứng minh bạn sống ở Maryland.","p":"Đúng. Hãy mang hai giấy tờ chứng minh bạn sống ở Maryland."},"tl":{"q":"Sa Maryland, ilang dokumentong nagpapatunay na nakatira ka sa Maryland ang dapat mong dalhin kapag nag-aplay ka ng lisensya?","o":["Isa","Dalawa","Tatlo","Wala, kung may pasaporte ka"],"h1":"Higit sa isa.","h2":"Sa Maryland, dapat kang magdala ng dalawang dokumentong nagpapatunay na nakatira ka sa Maryland kapag nag-aplay ka.","p":"Tama. Magdala ng dalawang patunay na nakatira ka sa Maryland."},"ar":{"q":"في Maryland، كم وثيقة تثبت أنك تسكن في Maryland يجب أن تحضرها عندما تقدّم طلب الرخصة؟","o":["وثيقة واحدة","وثيقتان","ثلاث وثائق","لا شيء، إذا كان معك جواز سفر"],"h1":"أكثر من واحدة.","h2":"في Maryland يجب أن تحضر وثيقتين تثبتان أنك تسكن في Maryland عندما تقدّم الطلب.","p":"صحيح. أحضر وثيقتين تثبتان أنك تسكن في Maryland."},"ref":{"doc":"MD","page":9}},{"id":"md-034","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a new driver is 25 or older. How many hours of supervised practice must they log with a learner's permit?","o":["60 hours, including 10 at night","40 hours, including 5 at night","14 hours, including 3 at night","No practice hours at all"],"h1":"Older beginners need far fewer hours than teens.","h2":"In Maryland, a new driver 25 or older must log at least 14 hours of supervised practice, with at least 3 of them at night.","p":"Right. Drivers 25 or older need 14 hours, including 3 at night."},"es":{"q":"En Maryland, un conductor nuevo tiene 25 años o más. ¿Cuántas horas de práctica supervisada debe registrar con el permiso de aprendizaje?","o":["60 horas, incluidas 10 de noche","40 horas, incluidas 5 de noche","14 horas, incluidas 3 de noche","Ninguna hora de práctica"],"h1":"Los principiantes mayores necesitan muchas menos horas que los adolescentes.","h2":"En Maryland, un conductor nuevo de 25 años o más debe registrar al menos 14 horas de práctica supervisada, y al menos 3 de ellas de noche.","p":"Correcto. Los conductores de 25 años o más necesitan 14 horas, incluidas 3 de noche."},"zh":{"q":"在 Maryland，一名新司机 25 岁或以上。持学习驾照期间，必须记录多少小时有人陪同的练习？","o":["60 小时，其中 10 小时在夜间","40 小时，其中 5 小时在夜间","14 小时，其中 3 小时在夜间","完全不需要练习时数"],"h1":"年纪大的新手需要的时数比青少年少很多。","h2":"在 Maryland，25 岁或以上的新司机必须记录至少 14 小时有人陪同的练习，其中至少 3 小时在夜间。","p":"对。25 岁或以上的司机需要 14 小时，其中 3 小时在夜间。"},"vi":{"q":"Ở Maryland, một người lái mới từ 25 tuổi trở lên. Họ phải ghi lại bao nhiêu giờ tập lái có giám sát với giấy phép tập lái?","o":["60 giờ, trong đó 10 giờ vào ban đêm","40 giờ, trong đó 5 giờ vào ban đêm","14 giờ, trong đó 3 giờ vào ban đêm","Không cần giờ tập lái nào"],"h1":"Người mới học lái lớn tuổi cần ít giờ hơn nhiều so với thanh thiếu niên.","h2":"Ở Maryland, người lái mới từ 25 tuổi trở lên phải ghi lại ít nhất 14 giờ tập lái có giám sát, trong đó ít nhất 3 giờ vào ban đêm.","p":"Đúng. Người lái từ 25 tuổi trở lên cần 14 giờ, trong đó 3 giờ vào ban đêm."},"tl":{"q":"Sa Maryland, 25 taong gulang pataas ang isang bagong driver. Ilang oras ng praktis na may bantay ang dapat niyang itala habang may learner's permit?","o":["60 oras, kasama ang 10 sa gabi","40 oras, kasama ang 5 sa gabi","14 na oras, kasama ang 3 sa gabi","Walang kailangang oras ng praktis"],"h1":"Mas kaunti ang kailangang oras ng mas matatandang baguhan kaysa sa mga teenager.","h2":"Sa Maryland, ang bagong driver na 25 taong gulang pataas ay dapat magtala ng hindi bababa sa 14 na oras ng praktis na may bantay, at hindi bababa sa 3 sa mga ito ay sa gabi.","p":"Tama. Ang mga driver na 25 pataas ay kailangan ng 14 na oras, kasama ang 3 sa gabi."},"ar":{"q":"في Maryland، سائق جديد عمره 25 سنة أو أكثر. كم ساعة من التدريب تحت الإشراف يجب أن يسجّلها وهو يحمل تصريح التعلّم؟","o":["60 ساعة، منها 10 في الليل","40 ساعة، منها 5 في الليل","14 ساعة، منها 3 في الليل","لا يحتاج إلى أي ساعات تدريب"],"h1":"المبتدئون الأكبر سنًّا يحتاجون إلى ساعات أقل بكثير من المراهقين.","h2":"في Maryland يجب أن يسجّل السائق الجديد الذي عمره 25 سنة أو أكثر 14 ساعة على الأقل من التدريب تحت الإشراف، منها 3 ساعات على الأقل في الليل.","p":"صحيح. السائقون الذين أعمارهم 25 سنة أو أكثر يحتاجون إلى 14 ساعة، منها 3 في الليل."},"ref":{"doc":"MD","page":10}},{"id":"md-035","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a new driver is 20 years old. How long must they hold a learner's permit, with no violations, before getting a provisional license?","o":["45 days","9 months","1 year","3 months"],"h1":"It is shorter than for teens under 18, but longer than for drivers 25 or older.","h2":"In Maryland, a new driver aged 19 to 24, or 18 with a high school diploma or GED, must hold the permit for at least 3 months without a violation.","p":"Right. From 19 to 24, the permit must be held at least 3 months."},"es":{"q":"En Maryland, un conductor nuevo tiene 20 años. ¿Cuánto tiempo debe tener el permiso de aprendizaje, sin infracciones, antes de obtener una licencia provisional?","o":["45 días","9 meses","1 año","3 meses"],"h1":"Es menos que para los menores de 18, pero más que para los de 25 años o más.","h2":"En Maryland, un conductor nuevo de 19 a 24 años, o de 18 con diploma de secundaria o GED, debe tener el permiso al menos 3 meses sin infracciones.","p":"Correcto. De 19 a 24 años, el permiso se debe tener al menos 3 meses."},"zh":{"q":"在 Maryland，一名新司机 20 岁。他必须持有学习驾照多久、而且没有违规，才能拿到过渡驾照（provisional license）？","o":["45 天","9 个月","1 年","3 个月"],"h1":"比 18 岁以下的青少年短，但比 25 岁或以上的司机长。","h2":"在 Maryland，19 到 24 岁的新司机，或有高中毕业证书或 GED 的 18 岁新司机，必须持有学习驾照至少 3 个月，而且没有违规。","p":"对。19 到 24 岁的人必须持有学习驾照至少 3 个月。"},"vi":{"q":"Ở Maryland, một người lái mới 20 tuổi. Họ phải giữ giấy phép tập lái bao lâu, không có vi phạm nào, trước khi lấy bằng lái tạm thời (provisional license)?","o":["45 ngày","9 tháng","1 năm","3 tháng"],"h1":"Ngắn hơn so với thanh thiếu niên dưới 18 tuổi, nhưng dài hơn so với người lái từ 25 tuổi trở lên.","h2":"Ở Maryland, người lái mới từ 19 đến 24 tuổi, hoặc 18 tuổi có bằng tốt nghiệp trung học hay GED, phải giữ giấy phép tập lái ít nhất 3 tháng mà không có vi phạm nào.","p":"Đúng. Từ 19 đến 24 tuổi, phải giữ giấy phép tập lái ít nhất 3 tháng."},"tl":{"q":"Sa Maryland, 20 taong gulang ang isang bagong driver. Gaano katagal dapat niyang hawak ang learner's permit, nang walang violation, bago makakuha ng provisional license?","o":["45 araw","9 na buwan","1 taon","3 buwan"],"h1":"Mas maikli ito kaysa sa mga teenager na wala pang 18, pero mas mahaba kaysa sa mga driver na 25 pataas.","h2":"Sa Maryland, ang bagong driver na 19 hanggang 24 taong gulang, o 18 na may high school diploma o GED, ay dapat hawak ang permit nang hindi bababa sa 3 buwan nang walang violation.","p":"Tama. Mula 19 hanggang 24, dapat hawak ang permit nang hindi bababa sa 3 buwan."},"ar":{"q":"في Maryland، سائق جديد عمره 20 سنة. كم يجب أن يحتفظ بتصريح التعلّم، بدون أي مخالفة، قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["45 يومًا","9 أشهر","سنة واحدة (1)","3 أشهر"],"h1":"المدة أقصر مما هي للمراهقين الذين أعمارهم أقل من 18 سنة، لكنها أطول مما هي للسائقين الذين أعمارهم 25 سنة أو أكثر.","h2":"في Maryland يجب أن يحتفظ السائق الجديد الذي عمره من 19 إلى 24 سنة، أو عمره 18 سنة ومعه شهادة الثانوية أو GED، بتصريح التعلّم 3 أشهر على الأقل بدون أي مخالفة.","p":"صحيح. من 19 إلى 24 سنة يجب الاحتفاظ بالتصريح 3 أشهر على الأقل."},"ref":{"doc":"MD","page":10}},{"id":"md-036","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, how much gas must be in the car you bring to the driving skills test?","o":["Any amount","At least half a tank","A full tank","At least a quarter tank"],"h1":"The tank cannot be close to empty.","h2":"In Maryland, the car you use for the driving skills test must have at least half a tank of gas.","p":"Right. Bring the car with at least half a tank of gas."},"es":{"q":"En Maryland, ¿cuánta gasolina debe tener el carro que lleva al examen de manejo?","o":["Cualquier cantidad","Al menos medio tanque","El tanque lleno","Al menos un cuarto de tanque"],"h1":"El tanque no puede estar casi vacío.","h2":"En Maryland, el carro que usa para el examen de manejo debe tener al menos medio tanque de gasolina.","p":"Correcto. Lleve el carro con al menos medio tanque de gasolina."},"zh":{"q":"在 Maryland，你带去参加路考（driving skills test）的车，油箱里必须有多少油？","o":["多少都可以","至少半箱","满箱","至少四分之一箱"],"h1":"油箱不能快空了。","h2":"在 Maryland，你参加路考用的车必须至少有半箱油。","p":"对。带去的车至少要有半箱油。"},"vi":{"q":"Ở Maryland, chiếc xe bạn mang đến bài thi kỹ năng lái xe phải có bao nhiêu xăng?","o":["Bao nhiêu cũng được","Ít nhất nửa bình","Đầy bình","Ít nhất một phần tư bình"],"h1":"Bình xăng không được gần cạn.","h2":"Ở Maryland, chiếc xe bạn dùng cho bài thi kỹ năng lái xe phải có ít nhất nửa bình xăng.","p":"Đúng. Hãy mang xe có ít nhất nửa bình xăng."},"tl":{"q":"Sa Maryland, gaano karaming gasolina ang dapat nasa kotseng dadalhin mo sa driving skills test?","o":["Kahit gaano","Hindi bababa sa kalahating tangke","Punong tangke","Hindi bababa sa sangkapat na tangke"],"h1":"Hindi puwedeng halos wala nang laman ang tangke.","h2":"Sa Maryland, ang kotseng gagamitin mo sa driving skills test ay dapat may hindi bababa sa kalahating tangke ng gasolina.","p":"Tama. Dalhin ang kotse na may hindi bababa sa kalahating tangke ng gasolina."},"ar":{"q":"في Maryland، كم من الوقود يجب أن يكون في السيارة التي تحضرها إلى اختبار مهارات القيادة؟","o":["أي كمية","نصف خزان على الأقل","خزان ممتلئ","ربع خزان على الأقل"],"h1":"لا يمكن أن يكون الخزان شبه فارغ.","h2":"في Maryland يجب أن يكون في السيارة التي تستعملها في اختبار مهارات القيادة نصف خزان من الوقود على الأقل.","p":"صحيح. أحضر السيارة وفيها نصف خزان من الوقود على الأقل."},"ref":{"doc":"MD","page":8}},{"id":"md-037","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, which of these must you do during the driving skills test?","o":["Parallel park between two cars","Drive on an interstate highway","Change a flat tire","Pull-in parking, back-in parking and a three-point turn"],"h1":"Parallel parking is no longer part of the test.","h2":"In Maryland, the driving test checks pull-in parking, back-in parking and a three-point turn; parallel parking is no longer required.","p":"Right. You will do pull-in parking, back-in parking and a three-point turn."},"es":{"q":"En Maryland, ¿cuál de estas cosas debe hacer durante el examen de manejo?","o":["Estacionarse en paralelo entre dos carros","Manejar en una autopista interestatal","Cambiar una llanta ponchada","Estacionarse de frente, estacionarse en reversa y dar una vuelta en tres puntos"],"h1":"El estacionamiento en paralelo ya no es parte del examen.","h2":"En Maryland, el examen de manejo revisa estacionarse de frente, estacionarse en reversa y la vuelta en tres puntos; ya no se exige el estacionamiento en paralelo.","p":"Correcto. Se estacionará de frente y en reversa, y dará una vuelta en tres puntos."},"zh":{"q":"在 Maryland，路考时你必须做下面哪一项？","o":["在两辆车之间侧方停车","在州际高速公路上开车","换一个瘪了的轮胎","车头进入停车、倒车进入停车和三点掉头"],"h1":"侧方停车已经不在考试里了。","h2":"在 Maryland，路考要考车头进入停车、倒车进入停车和三点掉头；侧方停车已经不需要考了。","p":"对。你要做车头进入停车、倒车进入停车和三点掉头。"},"vi":{"q":"Ở Maryland, bạn phải làm điều nào sau đây trong bài thi kỹ năng lái xe?","o":["Đậu xe song song giữa hai xe","Lái xe trên xa lộ liên bang","Thay một bánh xe bị xẹp","Đậu xe tiến vào, đậu xe lùi vào và quay đầu ba điểm"],"h1":"Đậu xe song song không còn nằm trong bài thi nữa.","h2":"Ở Maryland, bài thi lái xe kiểm tra đậu xe tiến vào, đậu xe lùi vào và quay đầu ba điểm; đậu xe song song không còn bắt buộc nữa.","p":"Đúng. Bạn sẽ đậu xe tiến vào, đậu xe lùi vào và quay đầu ba điểm."},"tl":{"q":"Sa Maryland, alin sa mga ito ang dapat mong gawin sa driving skills test?","o":["Mag-parallel park sa pagitan ng dalawang kotse","Magmaneho sa interstate highway","Magpalit ng flat na gulong","Pull-in parking, back-in parking at three-point turn"],"h1":"Hindi na kasama sa test ang parallel parking.","h2":"Sa Maryland, sinusuri sa driving test ang pull-in parking, back-in parking at three-point turn; hindi na kailangan ang parallel parking.","p":"Tama. Gagawin mo ang pull-in parking, back-in parking at three-point turn."},"ar":{"q":"في Maryland، أي مما يلي يجب أن تفعله أثناء اختبار مهارات القيادة؟","o":["الركن الموازي بين سيارتين","القيادة على طريق سريع بين الولايات (interstate)","تغيير إطار مثقوب","الركن بالدخول من الأمام، والركن بالرجوع إلى الخلف، والدوران بثلاث حركات"],"h1":"الركن الموازي لم يعد جزءًا من الاختبار.","h2":"في Maryland يفحص اختبار القيادة الركن بالدخول من الأمام، والركن بالرجوع إلى الخلف، والدوران بثلاث حركات؛ والركن الموازي لم يعد مطلوبًا.","p":"صحيح. ستقوم بالركن بالدخول من الأمام، والركن بالرجوع إلى الخلف، والدوران بثلاث حركات."},"ref":{"doc":"MD","page":53}},{"id":"md-038","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, the knowledge test is offered in your language. How many times must you take it before you may use an interpreter?","o":["At least 5 times","At least 2 times","At least 10 times","You may use an interpreter the first time"],"h1":"You must try on your own several times first.","h2":"In Maryland, if the knowledge test is offered in your language, you must take it at least 5 times before you may use an interpreter.","p":"Right. Take it at least 5 times in your language before using an interpreter."},"es":{"q":"En Maryland, el examen de conocimientos se ofrece en su idioma. ¿Cuántas veces debe tomarlo antes de poder usar un intérprete?","o":["Al menos 5 veces","Al menos 2 veces","Al menos 10 veces","Puede usar un intérprete desde la primera vez"],"h1":"Primero debe intentarlo usted solo varias veces.","h2":"En Maryland, si el examen de conocimientos se ofrece en su idioma, debe tomarlo al menos 5 veces antes de poder usar un intérprete.","p":"Correcto. Tómelo al menos 5 veces en su idioma antes de usar un intérprete."},"zh":{"q":"在 Maryland，笔试（knowledge test）有你的语言版本。你必须考几次，才可以用翻译员？","o":["至少 5 次","至少 2 次","至少 10 次","第一次就可以用翻译员"],"h1":"你必须先自己试好几次。","h2":"在 Maryland，如果笔试有你的语言版本，你必须至少考 5 次，才可以用翻译员。","p":"对。先用你的语言考至少 5 次，才可以用翻译员。"},"vi":{"q":"Ở Maryland, bài thi lý thuyết (knowledge test) có bằng ngôn ngữ của bạn. Bạn phải thi bao nhiêu lần trước khi được dùng thông dịch viên?","o":["Ít nhất 5 lần","Ít nhất 2 lần","Ít nhất 10 lần","Bạn được dùng thông dịch viên ngay lần đầu"],"h1":"Bạn phải tự thi vài lần trước.","h2":"Ở Maryland, nếu bài thi lý thuyết có bằng ngôn ngữ của bạn, bạn phải thi ít nhất 5 lần trước khi được dùng thông dịch viên.","p":"Đúng. Hãy thi ít nhất 5 lần bằng ngôn ngữ của bạn trước khi dùng thông dịch viên."},"tl":{"q":"Sa Maryland, may knowledge test sa wika mo. Ilang beses mo itong dapat kunin bago ka puwedeng gumamit ng interpreter?","o":["Hindi bababa sa 5 beses","Hindi bababa sa 2 beses","Hindi bababa sa 10 beses","Puwede kang gumamit ng interpreter sa unang beses"],"h1":"Dapat mo munang subukan nang mag-isa nang ilang beses.","h2":"Sa Maryland, kung may knowledge test sa wika mo, dapat mo itong kunin nang hindi bababa sa 5 beses bago ka puwedeng gumamit ng interpreter.","p":"Tama. Kunin ito nang hindi bababa sa 5 beses sa wika mo bago gumamit ng interpreter."},"ar":{"q":"في Maryland، الاختبار النظري (knowledge test) متوفّر بلغتك. كم مرة يجب أن تتقدّم له قبل أن يجوز لك استعمال مترجم؟","o":["5 مرات على الأقل","مرتين (2) على الأقل","10 مرات على الأقل","يجوز لك استعمال مترجم من المرة الأولى"],"h1":"يجب أن تحاول وحدك عدة مرات أولًا.","h2":"في Maryland، إذا كان الاختبار النظري متوفّرًا بلغتك، يجب أن تتقدّم له 5 مرات على الأقل قبل أن يجوز لك استعمال مترجم.","p":"صحيح. تقدّم للاختبار بلغتك 5 مرات على الأقل قبل استعمال مترجم."},"ref":{"doc":"MD","page":12}},{"id":"md-039","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a provisional license holder who is 18 or older is convicted of a first moving violation. What penalty does the MVA add?","o":["The license is revoked","A 30-day suspension","A driver improvement program","No added penalty"],"h1":"The first time, it is a class, not a suspension.","h2":"In Maryland, a provisional driver 18 or older with a first moving violation must complete a driver improvement program.","p":"Right. A first offense means a driver improvement program."},"es":{"q":"En Maryland, un conductor con licencia provisional de 18 años o más es condenado por una primera infracción de tránsito en movimiento. ¿Qué sanción agrega la MVA?","o":["Le revocan la licencia","Una suspensión de 30 días","Un programa de mejoramiento para conductores","Ninguna sanción adicional"],"h1":"La primera vez es una clase, no una suspensión.","h2":"En Maryland, un conductor provisional de 18 años o más con una primera infracción en movimiento debe completar un programa de mejoramiento para conductores.","p":"Correcto. Una primera infracción significa un programa de mejoramiento para conductores."},"zh":{"q":"在 Maryland，18 岁或以上持过渡驾照的司机第一次因行驶违章被定罪。MVA 会加上什么处罚？","o":["驾照被撤销","吊销驾照 30 天","参加驾驶改进课程（driver improvement program）","没有额外处罚"],"h1":"第一次是上课，不是吊销驾照。","h2":"在 Maryland，18 岁或以上持过渡驾照的司机第一次行驶违章，必须完成驾驶改进课程。","p":"对。第一次违章要上驾驶改进课程。"},"vi":{"q":"Ở Maryland, người có bằng lái tạm thời từ 18 tuổi trở lên bị kết tội vi phạm giao thông lần đầu. MVA thêm hình phạt gì?","o":["Bằng lái bị thu hồi","Bị treo bằng 30 ngày","Một chương trình cải thiện kỹ năng lái xe (driver improvement program)","Không có hình phạt thêm"],"h1":"Lần đầu tiên là một lớp học, không phải treo bằng.","h2":"Ở Maryland, người lái có bằng lái tạm thời từ 18 tuổi trở lên vi phạm giao thông lần đầu phải hoàn thành một chương trình cải thiện kỹ năng lái xe.","p":"Đúng. Vi phạm lần đầu nghĩa là phải học chương trình cải thiện kỹ năng lái xe."},"tl":{"q":"Sa Maryland, nahatulan ang isang provisional license holder na 18 pataas sa unang moving violation. Anong parusa ang idinadagdag ng MVA?","o":["Babawiin ang lisensya","Suspensyon nang 30 araw","Isang driver improvement program","Walang dagdag na parusa"],"h1":"Sa unang beses, klase ito, hindi suspensyon.","h2":"Sa Maryland, ang provisional driver na 18 pataas na may unang moving violation ay dapat tapusin ang isang driver improvement program.","p":"Tama. Ang unang violation ay nangangahulugang driver improvement program."},"ar":{"q":"في Maryland، أُدين صاحب رخصة مؤقتة عمره 18 سنة أو أكثر بأول مخالفة مرورية أثناء القيادة. ما العقوبة التي تضيفها MVA؟","o":["سحب الرخصة نهائيًا","إيقاف الرخصة 30 يومًا","برنامج لتحسين القيادة (driver improvement program)","لا عقوبة إضافية"],"h1":"في المرة الأولى تكون العقوبة دورة دراسية، لا إيقاف الرخصة.","h2":"في Maryland يجب على السائق صاحب الرخصة المؤقتة الذي عمره 18 سنة أو أكثر، إذا ارتكب أول مخالفة مرورية أثناء القيادة، أن يُكمل برنامجًا لتحسين القيادة.","p":"صحيح. المخالفة الأولى تعني برنامجًا لتحسين القيادة."},"ref":{"doc":"MD","page":49}},{"id":"md-040","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a provisional driver under 18 is convicted of a fourth moving violation. What happens?","o":["A warning letter only","The license is revoked, and all licensing tests must be passed again","A 30-day suspension","A $50 fine only"],"h1":"It is the most serious step for a young driver.","h2":"In Maryland, a fourth moving violation by a provisional driver under 18 means the license is revoked, and all licensing tests must be passed again to get it back.","p":"Right. The license is revoked and every licensing test must be retaken."},"es":{"q":"En Maryland, un conductor provisional menor de 18 años es condenado por una cuarta infracción en movimiento. ¿Qué pasa?","o":["Solo una carta de advertencia","Le revocan la licencia y debe aprobar otra vez todos los exámenes","Una suspensión de 30 días","Solo una multa de $50"],"h1":"Es el paso más serio para un conductor joven.","h2":"En Maryland, con una cuarta infracción en movimiento, a un conductor provisional menor de 18 años le revocan la licencia, y debe aprobar otra vez todos los exámenes para recuperarla.","p":"Correcto. Le revocan la licencia y debe repetir todos los exámenes."},"zh":{"q":"在 Maryland，18 岁以下持过渡驾照的司机第四次因行驶违章被定罪。会发生什么？","o":["只收到一封警告信","驾照被撤销，所有驾照考试都必须重新通过","吊销驾照 30 天","只罚款 $50"],"h1":"对年轻司机来说，这是最严重的一步。","h2":"在 Maryland，18 岁以下持过渡驾照的司机第四次行驶违章，驾照会被撤销，要拿回驾照必须重新通过所有驾照考试。","p":"对。驾照被撤销，每一项驾照考试都必须重考。"},"vi":{"q":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi bị kết tội vi phạm giao thông lần thứ tư. Điều gì xảy ra?","o":["Chỉ nhận một thư cảnh cáo","Bằng lái bị thu hồi, và phải thi đậu lại tất cả các bài thi lấy bằng","Bị treo bằng 30 ngày","Chỉ bị phạt $50"],"h1":"Đây là bước nghiêm khắc nhất đối với người lái trẻ.","h2":"Ở Maryland, người lái có bằng lái tạm thời dưới 18 tuổi vi phạm giao thông lần thứ tư sẽ bị thu hồi bằng lái, và phải thi đậu lại tất cả các bài thi lấy bằng để lấy lại bằng.","p":"Đúng. Bằng lái bị thu hồi và phải thi lại mọi bài thi lấy bằng."},"tl":{"q":"Sa Maryland, nahatulan ang isang provisional driver na wala pang 18 sa ikaapat na moving violation. Ano ang mangyayari?","o":["Isang sulat ng babala lang","Babawiin ang lisensya, at dapat ipasa ulit ang lahat ng test para sa lisensya","Suspensyon nang 30 araw","Multang $50 lang"],"h1":"Ito ang pinakamabigat na hakbang para sa batang driver.","h2":"Sa Maryland, kapag may ikaapat na moving violation ang provisional driver na wala pang 18, babawiin ang lisensya, at dapat ipasa ulit ang lahat ng test para sa lisensya para makuha ito ulit.","p":"Tama. Babawiin ang lisensya at dapat kunin ulit ang bawat test para sa lisensya."},"ar":{"q":"في Maryland، أُدين سائق صاحب رخصة مؤقتة عمره أقل من 18 سنة بمخالفة مرورية رابعة أثناء القيادة. ماذا يحدث؟","o":["رسالة تحذير فقط","تُسحب الرخصة نهائيًا، ويجب النجاح في كل اختبارات الرخصة من جديد","إيقاف الرخصة 30 يومًا","غرامة $50 فقط"],"h1":"هذه أشد خطوة بالنسبة إلى السائق الشاب.","h2":"في Maryland، إذا ارتكب سائق صاحب رخصة مؤقتة عمره أقل من 18 سنة مخالفة مرورية رابعة أثناء القيادة، تُسحب رخصته نهائيًا، ويجب أن ينجح في كل اختبارات الرخصة من جديد ليستعيدها.","p":"صحيح. تُسحب الرخصة نهائيًا ويجب إعادة كل اختبارات الرخصة."},"ref":{"doc":"MD","page":49}},{"id":"md-041","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, what fine can you face if you do not keep insurance on a vehicle?","o":["Up to $100 one time","Up to $500 one time","Only a warning the first time","Up to $2,500 per vehicle each year"],"h1":"The fine is counted for each vehicle and each year.","h2":"In Maryland, if you do not keep insurance on your vehicles, you can be fined up to $2,500 per vehicle each year.","p":"Right. It can cost up to $2,500 per vehicle each year."},"es":{"q":"En Maryland, ¿qué multa puede recibir si no mantiene un seguro en un vehículo?","o":["Hasta $100 una sola vez","Hasta $500 una sola vez","Solo una advertencia la primera vez","Hasta $2,500 por vehículo cada año"],"h1":"La multa se cuenta por cada vehículo y por cada año.","h2":"En Maryland, si no mantiene seguro en sus vehículos, le pueden multar con hasta $2,500 por vehículo cada año.","p":"Correcto. Puede costar hasta $2,500 por vehículo cada año."},"zh":{"q":"在 Maryland，如果你的车没有保持保险，你可能被罚多少钱？","o":["一次最多 $100","一次最多 $500","第一次只是警告","每辆车每年最多 $2,500"],"h1":"罚款按每辆车、每年来算。","h2":"在 Maryland，如果你的车没有保持保险，每辆车每年最多可以被罚 $2,500。","p":"对。每辆车每年最多可能要罚 $2,500。"},"vi":{"q":"Ở Maryland, bạn có thể bị phạt bao nhiêu nếu không duy trì bảo hiểm cho xe?","o":["Tối đa $100 một lần","Tối đa $500 một lần","Chỉ cảnh cáo lần đầu","Tối đa $2,500 cho mỗi xe mỗi năm"],"h1":"Tiền phạt được tính cho mỗi xe và mỗi năm.","h2":"Ở Maryland, nếu bạn không duy trì bảo hiểm cho xe, bạn có thể bị phạt tối đa $2,500 cho mỗi xe mỗi năm.","p":"Đúng. Có thể bị phạt tối đa $2,500 cho mỗi xe mỗi năm."},"tl":{"q":"Sa Maryland, anong multa ang puwede mong harapin kung hindi mo pinapanatili ang insurance ng sasakyan?","o":["Hanggang $100 nang isang beses","Hanggang $500 nang isang beses","Babala lang sa unang beses","Hanggang $2,500 bawat sasakyan bawat taon"],"h1":"Binibilang ang multa para sa bawat sasakyan at bawat taon.","h2":"Sa Maryland, kung hindi mo pinapanatili ang insurance ng mga sasakyan mo, puwede kang multahan nang hanggang $2,500 bawat sasakyan bawat taon.","p":"Tama. Puwede itong umabot nang hanggang $2,500 bawat sasakyan bawat taon."},"ar":{"q":"في Maryland، ما الغرامة التي قد تدفعها إذا لم تُبقِ التأمين ساريًا على سيارتك؟","o":["حتى $100 مرة واحدة","حتى $500 مرة واحدة","تحذير فقط في المرة الأولى","حتى $2,500 عن كل سيارة في كل سنة"],"h1":"تُحسب الغرامة عن كل سيارة وعن كل سنة.","h2":"في Maryland، إذا لم تُبقِ التأمين ساريًا على سياراتك، فقد تُغرَّم حتى $2,500 عن كل سيارة في كل سنة.","p":"صحيح. قد تصل الغرامة إلى $2,500 عن كل سيارة في كل سنة."},"ref":{"doc":"MD","page":53}},{"id":"md-042","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a driver is convicted of leaving the scene of a crash that caused a serious injury. What can happen?","o":["License revoked, up to 5 years in prison and up to a $5,000 fine","A $110 fine and 1 point","A warning and a safety class","A 30-day suspension only"],"h1":"The penalties are severe: the license is taken away and prison is possible.","h2":"In Maryland, leaving the scene of a crash with a serious injury means your license is revoked, and you could get up to 5 years in prison and a fine up to $5,000.","p":"Right. Revocation, up to 5 years in prison and up to $5,000."},"es":{"q":"En Maryland, un conductor es condenado por huir del lugar de un choque que causó una lesión grave. ¿Qué puede pasar?","o":["Le revocan la licencia, hasta 5 años de cárcel y una multa de hasta $5,000","Una multa de $110 y 1 punto","Una advertencia y una clase de seguridad","Solo una suspensión de 30 días"],"h1":"Las sanciones son graves: le quitan la licencia y puede ir a la cárcel.","h2":"En Maryland, huir del lugar de un choque con una lesión grave significa que le revocan la licencia, y puede recibir hasta 5 años de cárcel y una multa de hasta $5,000.","p":"Correcto. Revocación, hasta 5 años de cárcel y hasta $5,000."},"zh":{"q":"在 Maryland，一名司机因离开造成重伤的车祸现场被定罪。可能会怎么样？","o":["驾照被撤销，最多坐牢 5 年，最多罚款 $5,000","罚款 $110，记 1 分","警告并上安全课","只吊销驾照 30 天"],"h1":"处罚很重：驾照会被收走，还可能坐牢。","h2":"在 Maryland，离开有人重伤的车祸现场，驾照会被撤销，而且你可能坐牢最多 5 年，罚款最多 $5,000。","p":"对。撤销驾照，最多坐牢 5 年，最多罚款 $5,000。"},"vi":{"q":"Ở Maryland, một người lái bị kết tội bỏ chạy khỏi hiện trường một vụ tai nạn gây thương tích nặng. Điều gì có thể xảy ra?","o":["Bị thu hồi bằng lái, tù đến 5 năm và phạt đến $5,000","Phạt $110 và 1 điểm","Cảnh cáo và một lớp học an toàn","Chỉ bị treo bằng 30 ngày"],"h1":"Hình phạt rất nặng: bị lấy bằng lái và có thể phải ngồi tù.","h2":"Ở Maryland, bỏ chạy khỏi hiện trường một vụ tai nạn có người bị thương nặng nghĩa là bằng lái của bạn bị thu hồi, và bạn có thể bị tù đến 5 năm và phạt đến $5,000.","p":"Đúng. Bị thu hồi bằng lái, tù đến 5 năm và phạt đến $5,000."},"tl":{"q":"Sa Maryland, nahatulan ang isang driver ng pag-alis sa lugar ng banggaan na nagdulot ng malubhang pinsala. Ano ang puwedeng mangyari?","o":["Babawiin ang lisensya, hanggang 5 taon sa kulungan at multang hanggang $5,000","Multang $110 at 1 point","Isang babala at safety class","Suspensyon nang 30 araw lang"],"h1":"Mabigat ang mga parusa: kukunin ang lisensya at puwedeng makulong.","h2":"Sa Maryland, kapag umalis ka sa lugar ng banggaan na may malubhang nasaktan, babawiin ang lisensya mo, at puwede kang makulong nang hanggang 5 taon at multahan nang hanggang $5,000.","p":"Tama. Pagbawi ng lisensya, hanggang 5 taon sa kulungan at hanggang $5,000."},"ar":{"q":"في Maryland، أُدين سائق بمغادرة مكان حادث سبّب إصابة خطيرة. ماذا يمكن أن يحدث؟","o":["سحب الرخصة نهائيًا، والسجن حتى 5 سنوات، وغرامة حتى $5,000","غرامة $110 ونقطة واحدة (1)","تحذير ودورة في السلامة","إيقاف الرخصة 30 يومًا فقط"],"h1":"العقوبات شديدة: تُؤخذ منك الرخصة ويمكن أن تُسجن.","h2":"في Maryland، إذا غادرت مكان حادث فيه إصابة خطيرة، تُسحب رخصتك نهائيًا، ويمكن أن تُسجن حتى 5 سنوات وأن تُغرَّم حتى $5,000.","p":"صحيح. سحب الرخصة، والسجن حتى 5 سنوات، وغرامة حتى $5,000."},"ref":{"doc":"MD","page":43}},{"id":"md-043","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, a driver is convicted of drunk or drugged driving with a child in the vehicle. What can the judge do?","o":["Lower the fine, because no one was hurt","Only give a warning","Double the fine and jail time","Take away 1 point"],"h1":"Having a child in the car makes it worse, not better.","h2":"In Maryland, if you are convicted of drunk or drugged driving with a child in the vehicle, the judge can double your fine and jail time.","p":"Right. The judge can double the fine and the jail time."},"es":{"q":"En Maryland, un conductor es condenado por manejar borracho o drogado con un niño en el vehículo. ¿Qué puede hacer el juez?","o":["Bajar la multa, porque nadie se lastimó","Solo dar una advertencia","Duplicar la multa y el tiempo de cárcel","Quitar 1 punto"],"h1":"Llevar a un niño en el carro lo hace peor, no mejor.","h2":"En Maryland, si lo condenan por manejar borracho o drogado con un niño en el vehículo, el juez puede duplicar su multa y su tiempo de cárcel.","p":"Correcto. El juez puede duplicar la multa y el tiempo de cárcel."},"zh":{"q":"在 Maryland，一名司机因车上有孩子时酒后或药后驾驶被定罪。法官可以怎么做？","o":["因为没有人受伤，降低罚款","只给警告","把罚款和监禁时间加倍","减掉 1 分"],"h1":"车上有孩子会让情况更糟，不是更好。","h2":"在 Maryland，如果你因车上有孩子时酒后或药后驾驶被定罪，法官可以把你的罚款和监禁时间加倍。","p":"对。法官可以把罚款和监禁时间加倍。"},"vi":{"q":"Ở Maryland, một người lái bị kết tội lái xe khi say rượu hoặc dùng ma túy trong lúc có trẻ em trên xe. Thẩm phán có thể làm gì?","o":["Giảm tiền phạt, vì không ai bị thương","Chỉ cảnh cáo","Tăng gấp đôi tiền phạt và thời gian ngồi tù","Xóa bớt 1 điểm"],"h1":"Có trẻ em trên xe làm cho tội nặng hơn, không phải nhẹ hơn.","h2":"Ở Maryland, nếu bạn bị kết tội lái xe khi say rượu hoặc dùng ma túy trong lúc có trẻ em trên xe, thẩm phán có thể tăng gấp đôi tiền phạt và thời gian ngồi tù của bạn.","p":"Đúng. Thẩm phán có thể tăng gấp đôi tiền phạt và thời gian ngồi tù."},"tl":{"q":"Sa Maryland, nahatulan ang isang driver ng pagmamaneho nang lasing o lango sa droga habang may bata sa sasakyan. Ano ang puwedeng gawin ng hukom?","o":["Babaan ang multa, dahil walang nasaktan","Magbigay lang ng babala","Doblehin ang multa at ang tagal ng kulong","Bawasan ng 1 point"],"h1":"Mas lumalala ang kaso kapag may bata sa kotse, hindi gumagaan.","h2":"Sa Maryland, kung nahatulan ka ng pagmamaneho nang lasing o lango sa droga habang may bata sa sasakyan, puwedeng doblehin ng hukom ang multa mo at ang tagal ng kulong mo.","p":"Tama. Puwedeng doblehin ng hukom ang multa at ang tagal ng kulong."},"ar":{"q":"في Maryland، أُدين سائق بالقيادة تحت تأثير الكحول أو المخدرات وفي السيارة طفل. ماذا يمكن أن يفعل القاضي؟","o":["يخفّض الغرامة، لأن أحدًا لم يُصب","يعطي تحذيرًا فقط","يضاعف الغرامة ومدة السجن","يمحو نقطة واحدة (1)"],"h1":"وجود طفل في السيارة يجعل الأمر أسوأ، لا أفضل.","h2":"في Maryland، إذا أُدنت بالقيادة تحت تأثير الكحول أو المخدرات وفي السيارة طفل، يمكن للقاضي أن يضاعف غرامتك ومدة سجنك.","p":"صحيح. يمكن للقاضي أن يضاعف الغرامة ومدة السجن."},"ref":{"doc":"MD","page":34}},{"id":"md-044","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you hit and injure a dog with your car. What must you do?","o":["Drive on if the dog runs away","Wait until the next day to report it","Call only your insurance company","Call the police right away"],"h1":"Dogs, cats, horses and cows count as domestic animals.","h2":"In Maryland, if you hit and injure a domestic animal such as a dog, you must call the police right away.","p":"Right. Call the police right away."},"es":{"q":"En Maryland, usted atropella y lastima a un perro con su carro. ¿Qué debe hacer?","o":["Seguir manejando si el perro se va corriendo","Esperar hasta el día siguiente para reportarlo","Llamar solo a su compañía de seguros","Llamar a la policía de inmediato"],"h1":"Los perros, gatos, caballos y vacas son animales domésticos.","h2":"En Maryland, si atropella y lastima a un animal doméstico, como un perro, debe llamar a la policía de inmediato.","p":"Correcto. Llame a la policía de inmediato."},"zh":{"q":"在 Maryland，你开车撞伤了一只狗。你必须怎么做？","o":["如果狗跑掉了，就继续开","等到第二天再报告","只打电话给你的保险公司","马上打电话报警"],"h1":"狗、猫、马和牛都算家养动物。","h2":"在 Maryland，如果你撞伤了狗这样的家养动物，你必须马上打电话报警。","p":"对。马上打电话报警。"},"vi":{"q":"Ở Maryland, bạn lái xe đụng và làm bị thương một con chó. Bạn phải làm gì?","o":["Lái đi tiếp nếu con chó chạy mất","Chờ đến ngày hôm sau mới báo","Chỉ gọi cho công ty bảo hiểm của bạn","Gọi cảnh sát ngay"],"h1":"Chó, mèo, ngựa và bò được tính là vật nuôi.","h2":"Ở Maryland, nếu bạn đụng và làm bị thương một vật nuôi như con chó, bạn phải gọi cảnh sát ngay.","p":"Đúng. Hãy gọi cảnh sát ngay."},"tl":{"q":"Sa Maryland, nabangga at nasaktan mo ang isang aso gamit ang kotse mo. Ano ang dapat mong gawin?","o":["Magpatuloy sa pagmamaneho kung tumakbo palayo ang aso","Maghintay hanggang kinabukasan bago ito i-report","Tawagan lang ang insurance company mo","Tawagan agad ang pulis"],"h1":"Itinuturing na alagang hayop ang aso, pusa, kabayo at baka.","h2":"Sa Maryland, kung nabangga at nasaktan mo ang isang alagang hayop gaya ng aso, dapat mong tawagan agad ang pulis.","p":"Tama. Tawagan agad ang pulis."},"ar":{"q":"في Maryland، صدمت كلبًا بسيارتك وأصبته. ماذا يجب أن تفعل؟","o":["تتابع القيادة إذا هرب الكلب","تنتظر حتى اليوم التالي لتبلّغ عنه","تتصل بشركة التأمين فقط","تتصل بالشرطة فورًا"],"h1":"الكلاب والقطط والخيول والأبقار تُعدّ حيوانات مستأنسة.","h2":"في Maryland، إذا صدمت حيوانًا مستأنسًا مثل الكلب وأصبته، يجب أن تتصل بالشرطة فورًا.","p":"صحيح. اتصل بالشرطة فورًا."},"ref":{"doc":"MD","page":44}},{"id":"md-045","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, what do flashing blue lights in a work zone mean?","o":["A police officer wants you to pull over","Speed cameras are active","The work zone has ended","Highway maintenance vehicles are ahead"],"h1":"Flashing green lights are for maintenance vehicles. Blue is about your speed.","h2":"In Maryland, flashing blue lights in a work zone mean the speed cameras are active.","p":"Right. Blue lights mean the speed cameras are on."},"es":{"q":"En Maryland, ¿qué significan las luces azules intermitentes en una zona de trabajo?","o":["Un policía quiere que usted se detenga","Las cámaras de velocidad están activas","La zona de trabajo terminó","Hay vehículos de mantenimiento de carreteras más adelante"],"h1":"Las luces verdes intermitentes son de vehículos de mantenimiento. Las azules tienen que ver con su velocidad.","h2":"En Maryland, las luces azules intermitentes en una zona de trabajo significan que las cámaras de velocidad están activas.","p":"Correcto. Las luces azules significan que las cámaras de velocidad están encendidas."},"zh":{"q":"在 Maryland，施工区里闪烁的蓝灯是什么意思？","o":["警察要你靠边停车","测速摄像头正在工作","施工区结束了","前面有公路维修车辆"],"h1":"闪烁的绿灯是给维修车辆用的。蓝灯和你的车速有关。","h2":"在 Maryland，施工区里闪烁的蓝灯表示测速摄像头正在工作。","p":"对。蓝灯表示测速摄像头开着。"},"vi":{"q":"Ở Maryland, đèn xanh dương nhấp nháy trong khu vực công trường có nghĩa là gì?","o":["Cảnh sát muốn bạn tấp vào lề","Camera bắn tốc độ đang hoạt động","Khu vực công trường đã hết","Phía trước có xe bảo trì đường cao tốc"],"h1":"Đèn xanh lá nhấp nháy là của xe bảo trì. Màu xanh dương liên quan đến tốc độ của bạn.","h2":"Ở Maryland, đèn xanh dương nhấp nháy trong khu vực công trường có nghĩa là camera bắn tốc độ đang hoạt động.","p":"Đúng. Đèn xanh dương nghĩa là camera bắn tốc độ đang bật."},"tl":{"q":"Sa Maryland, ano ang ibig sabihin ng kumikislap na asul na ilaw sa work zone?","o":["Gusto ng pulis na tumabi ka","Aktibo ang mga speed camera","Tapos na ang work zone","May mga sasakyan ng highway maintenance sa unahan"],"h1":"Ang kumikislap na berdeng ilaw ay para sa mga maintenance vehicle. Ang asul ay tungkol sa bilis mo.","h2":"Sa Maryland, ang kumikislap na asul na ilaw sa work zone ay nangangahulugang aktibo ang mga speed camera.","p":"Tama. Ang asul na ilaw ay nangangahulugang naka-on ang mga speed camera."},"ar":{"q":"في Maryland، ماذا تعني الأضواء الزرقاء الوامضة في منطقة أعمال الطرق؟","o":["شرطي يريد منك أن تتوقف على جانب الطريق","كاميرات السرعة تعمل","منطقة الأعمال انتهت","مركبات صيانة الطريق السريع أمامك"],"h1":"الأضواء الخضراء الوامضة هي لمركبات الصيانة. أما الزرقاء فتتعلّق بسرعتك.","h2":"في Maryland، الأضواء الزرقاء الوامضة في منطقة أعمال الطرق تعني أن كاميرات السرعة تعمل.","p":"صحيح. الأضواء الزرقاء تعني أن كاميرات السرعة مشغّلة."},"ref":{"doc":"MD","page":31}},{"id":"md-046","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maryland, what is the smallest following distance the MVA recommends in ideal conditions?","o":["3 to 4 seconds","1 second","1 to 2 seconds","10 seconds"],"h1":"Count \"one thousand\" from the moment the car ahead passes a fixed object.","h2":"In Maryland, the MVA recommends following at least 3 to 4 seconds behind the car ahead in ideal conditions.","p":"Right. Stay at least 3 to 4 seconds behind."},"es":{"q":"En Maryland, ¿cuál es la distancia mínima de seguimiento que recomienda la MVA en condiciones ideales?","o":["De 3 a 4 segundos","1 segundo","De 1 a 2 segundos","10 segundos"],"h1":"Cuente \"mil uno\" desde que el carro de adelante pasa un objeto fijo.","h2":"En Maryland, la MVA recomienda ir al menos de 3 a 4 segundos detrás del carro de adelante en condiciones ideales.","p":"Correcto. Manténgase al menos de 3 a 4 segundos detrás."},"zh":{"q":"在 Maryland，在理想条件下，MVA 建议的最小跟车距离是多少？","o":["3 到 4 秒","1 秒","1 到 2 秒","10 秒"],"h1":"从前车经过一个固定物体的那一刻开始数“一千零一、一千零二……”。","h2":"在 Maryland，MVA 建议在理想条件下，至少跟在前车后面 3 到 4 秒。","p":"对。至少保持在前车后面 3 到 4 秒。"},"vi":{"q":"Ở Maryland, khoảng cách theo sau nhỏ nhất mà MVA khuyên trong điều kiện lý tưởng là bao nhiêu?","o":["3 đến 4 giây","1 giây","1 đến 2 giây","10 giây"],"h1":"Hãy đếm \"một nghìn lẻ một, một nghìn lẻ hai…\" từ lúc xe phía trước chạy qua một vật cố định.","h2":"Ở Maryland, MVA khuyên nên chạy cách xe phía trước ít nhất 3 đến 4 giây trong điều kiện lý tưởng.","p":"Đúng. Hãy giữ khoảng cách ít nhất 3 đến 4 giây phía sau."},"tl":{"q":"Sa Maryland, ano ang pinakamaikling following distance na inirerekomenda ng MVA sa magandang kondisyon?","o":["3 hanggang 4 na segundo","1 segundo","1 hanggang 2 segundo","10 segundo"],"h1":"Magbilang ng \"one thousand one, one thousand two\" mula nang dumaan ang kotse sa unahan sa isang bagay na hindi gumagalaw.","h2":"Sa Maryland, inirerekomenda ng MVA na sumunod nang hindi bababa sa 3 hanggang 4 na segundo sa likod ng kotse sa unahan kapag maganda ang kondisyon.","p":"Tama. Manatili nang hindi bababa sa 3 hanggang 4 na segundo sa likod."},"ar":{"q":"في Maryland، ما أقل مسافة متابعة توصي بها MVA في الظروف المثالية؟","o":["من 3 إلى 4 ثوانٍ","ثانية واحدة (1)","من 1 إلى 2 ثانية","10 ثوانٍ"],"h1":"عُدّ \"ألف وواحد، ألف واثنان…\" من اللحظة التي تمرّ فيها السيارة التي أمامك بجانب شيء ثابت.","h2":"في Maryland، توصي MVA بأن تبقى خلف السيارة التي أمامك بمسافة 3 إلى 4 ثوانٍ على الأقل في الظروف المثالية.","p":"صحيح. ابقَ خلفها بمسافة 3 إلى 4 ثوانٍ على الأقل."},"ref":{"doc":"MD","page":15}},{"id":"md-047","scope":"MD","cat":"signals","sign":null,"c":2,"en":{"q":"In Maryland, when may you turn left on a steady red light after a complete stop?","o":["Never","From any street, if no cars are coming","From a one-way street onto another one-way street","Only when a police officer is present"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Maryland, unless a sign forbids it, you may turn left on red after a full stop only from a one-way street onto another one-way street.","p":"Right. Left on red is only from one one-way street onto another."},"es":{"q":"En Maryland, ¿cuándo puede girar a la izquierda con la luz roja fija después de detenerse por completo?","o":["Nunca","Desde cualquier calle, si no vienen carros","De una calle de un solo sentido a otra calle de un solo sentido","Solo cuando hay un policía presente"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Maryland, si no hay una señal que lo prohíba, puede girar a la izquierda con luz roja después de detenerse por completo solo de una calle de un solo sentido a otra de un solo sentido.","p":"Correcto. A la izquierda con luz roja solo de una calle de un solo sentido a otra."},"zh":{"q":"在 Maryland，完全停车后，什么时候可以在常亮的红灯时左转？","o":["永远不可以","从任何街道都可以，只要没有车来","从一条单行道转进另一条单行道","只有警察在场的时候"],"h1":"两条街都必须是只往一个方向走的。","h2":"在 Maryland，除非有标志禁止，完全停车后，只有从一条单行道转进另一条单行道时，才可以红灯左转。","p":"对。红灯左转只能从一条单行道转进另一条单行道。"},"vi":{"q":"Ở Maryland, khi nào bạn được rẽ trái lúc đèn đỏ đứng yên sau khi đã dừng hẳn?","o":["Không bao giờ","Từ bất kỳ đường nào, nếu không có xe đến","Từ một đường một chiều vào một đường một chiều khác","Chỉ khi có cảnh sát ở đó"],"h1":"Cả hai con đường đều phải chỉ cho xe chạy một chiều.","h2":"Ở Maryland, trừ khi có biển cấm, bạn chỉ được rẽ trái lúc đèn đỏ sau khi dừng hẳn khi đi từ một đường một chiều vào một đường một chiều khác.","p":"Đúng. Chỉ được rẽ trái lúc đèn đỏ từ một đường một chiều vào một đường một chiều khác."},"tl":{"q":"Sa Maryland, kailan ka puwedeng kumaliwa sa steady na pulang ilaw pagkatapos ng buong paghinto?","o":["Hindi kailanman","Mula sa kahit anong kalye, kung walang paparating na sasakyan","Mula sa one-way na kalye papunta sa isa pang one-way na kalye","Kapag may pulis lang"],"h1":"Dapat iisang direksyon lang ang daloy ng trapiko sa parehong kalye.","h2":"Sa Maryland, maliban kung may karatulang nagbabawal, puwede kang kumaliwa sa pula pagkatapos ng buong paghinto mula lang sa one-way na kalye papunta sa isa pang one-way na kalye.","p":"Tama. Ang pagkaliwa sa pula ay mula lang sa isang one-way na kalye papunta sa isa pa."},"ar":{"q":"في Maryland، متى يجوز لك أن تنعطف يسارًا عند الضوء الأحمر الثابت بعد التوقف الكامل؟","o":["أبدًا","من أي شارع، إذا لم تكن هناك سيارات قادمة","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","فقط عندما يكون شرطي موجودًا"],"h1":"يجب أن يكون السير في الشارعين في اتجاه واحد فقط.","h2":"في Maryland، ما لم تمنع ذلك لافتة، يجوز لك أن تنعطف يسارًا عند الضوء الأحمر بعد التوقف الكامل فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد.","p":"صحيح. الانعطاف يسارًا عند الأحمر يكون فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد."},"ref":{"doc":"MD","page":17}},{"id":"md-048","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, you are driving in a funeral procession with your headlights and hazard lights on. What may you do at a red light?","o":["You must stop and let the procession split up","You may go only after honking","You must stop and wait for a green light","You may go through it with the procession"],"h1":"Other drivers must yield to the procession, even on green.","h2":"In Maryland, a car in a funeral procession with its lights on may go through a red light with the procession.","p":"Right. With your lights on, you may follow the procession through the red light."},"es":{"q":"En Maryland, usted maneja en un cortejo fúnebre con las luces delanteras y las luces de emergencia encendidas. ¿Qué puede hacer en un semáforo en rojo?","o":["Debe detenerse y dejar que el cortejo se divida","Puede pasar solo después de tocar la bocina","Debe detenerse y esperar la luz verde","Puede pasar el semáforo junto con el cortejo"],"h1":"Los demás conductores deben ceder el paso al cortejo, aun con luz verde.","h2":"En Maryland, un carro en un cortejo fúnebre con las luces encendidas puede pasar un semáforo en rojo junto con el cortejo.","p":"Correcto. Con las luces encendidas, puede seguir al cortejo con la luz roja."},"zh":{"q":"在 Maryland，你在送葬车队里开车，开着前灯和危险警示灯。遇到红灯时你可以怎么做？","o":["你必须停车，让车队分开","你只有按喇叭后才可以走","你必须停车等绿灯","你可以跟着车队开过去"],"h1":"其他司机必须让送葬车队先走，即使他们是绿灯。","h2":"在 Maryland，送葬车队里开着灯的车，可以跟着车队开过红灯。","p":"对。开着灯时，你可以跟着车队开过红灯。"},"vi":{"q":"Ở Maryland, bạn đang lái xe trong đoàn xe đưa tang, có bật đèn pha và đèn khẩn cấp. Bạn được làm gì khi gặp đèn đỏ?","o":["Bạn phải dừng lại và để đoàn xe bị tách ra","Bạn chỉ được đi sau khi bấm còi","Bạn phải dừng lại và chờ đèn xanh","Bạn được đi qua cùng với đoàn xe"],"h1":"Những người lái khác phải nhường đường cho đoàn xe, kể cả khi họ có đèn xanh.","h2":"Ở Maryland, xe trong đoàn xe đưa tang có bật đèn được đi qua đèn đỏ cùng với đoàn xe.","p":"Đúng. Khi bật đèn, bạn được đi theo đoàn xe qua đèn đỏ."},"tl":{"q":"Sa Maryland, nagmamaneho ka sa funeral procession na naka-on ang headlights at hazard lights mo. Ano ang puwede mong gawin sa pulang ilaw?","o":["Dapat kang huminto at hayaang mahati ang procession","Puwede ka lang tumuloy pagkatapos bumusina","Dapat kang huminto at maghintay ng berdeng ilaw","Puwede kang tumuloy kasama ng procession"],"h1":"Dapat magbigay-daan sa procession ang ibang driver, kahit berde ang ilaw nila.","h2":"Sa Maryland, ang kotse sa funeral procession na naka-on ang mga ilaw ay puwedeng tumuloy sa pulang ilaw kasama ng procession.","p":"Tama. Kapag naka-on ang mga ilaw mo, puwede kang sumunod sa procession kahit pula ang ilaw."},"ar":{"q":"في Maryland، أنت تقود في موكب جنازة والأضواء الأمامية وأضواء الطوارئ مشغّلة. ماذا يجوز لك أن تفعل عند الضوء الأحمر؟","o":["يجب أن تتوقف وتترك الموكب ينقسم","يجوز لك أن تمر فقط بعد استعمال البوق","يجب أن تتوقف وتنتظر الضوء الأخضر","يجوز لك أن تمر مع الموكب"],"h1":"يجب على السائقين الآخرين أن يفسحوا الطريق للموكب، حتى لو كان الضوء أخضر لهم.","h2":"في Maryland، يجوز للسيارة التي في موكب جنازة وأضواؤها مشغّلة أن تمر في الضوء الأحمر مع الموكب.","p":"صحيح. وأضواؤك مشغّلة، يجوز لك أن تتبع الموكب وتمر في الضوء الأحمر."},"ref":{"doc":"MD","page":32}},{"id":"md-049","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, which vehicles must stop before every railroad crossing, even when no train is coming?","o":["Buses, school buses and trucks carrying hazardous materials","Motorcycles and mopeds","All cars with passengers","Only vehicles towing a trailer"],"h1":"These vehicles carry many people or dangerous loads.","h2":"In Maryland, buses, school buses and trucks carrying hazardous materials must stop before every railroad crossing, so be ready for them to stop.","p":"Right. Buses, school buses and hazardous-materials trucks stop at every crossing."},"es":{"q":"En Maryland, ¿qué vehículos deben detenerse antes de cada cruce de ferrocarril, aunque no venga un tren?","o":["Los autobuses, los autobuses escolares y los camiones que llevan materiales peligrosos","Las motocicletas y los ciclomotores","Todos los carros con pasajeros","Solo los vehículos que remolcan un tráiler"],"h1":"Estos vehículos llevan a muchas personas o cargas peligrosas.","h2":"En Maryland, los autobuses, los autobuses escolares y los camiones que llevan materiales peligrosos deben detenerse antes de cada cruce de ferrocarril, así que esté listo para que se detengan.","p":"Correcto. Los autobuses, los autobuses escolares y los camiones con materiales peligrosos se detienen en cada cruce."},"zh":{"q":"在 Maryland，哪些车辆在每个铁路道口前都必须停车，即使没有火车来？","o":["公交车、校车和运载危险物品的卡车","摩托车和轻便摩托车","所有载有乘客的汽车","只有拖着拖车的车辆"],"h1":"这些车辆载很多人，或者载危险的货物。","h2":"在 Maryland，公交车、校车和运载危险物品的卡车在每个铁路道口前都必须停车，所以要准备好它们会停下来。","p":"对。公交车、校车和危险物品卡车在每个道口都会停车。"},"vi":{"q":"Ở Maryland, những xe nào phải dừng lại trước mọi chỗ băng qua đường sắt, kể cả khi không có tàu đến?","o":["Xe buýt, xe buýt trường học và xe tải chở vật liệu nguy hiểm","Xe máy và xe gắn máy nhỏ (moped)","Tất cả xe hơi có chở hành khách","Chỉ những xe đang kéo rơ-moóc"],"h1":"Những xe này chở nhiều người hoặc chở hàng nguy hiểm.","h2":"Ở Maryland, xe buýt, xe buýt trường học và xe tải chở vật liệu nguy hiểm phải dừng lại trước mọi chỗ băng qua đường sắt, vì vậy hãy sẵn sàng khi chúng dừng lại.","p":"Đúng. Xe buýt, xe buýt trường học và xe tải chở vật liệu nguy hiểm dừng lại ở mọi chỗ băng qua đường sắt."},"tl":{"q":"Sa Maryland, aling mga sasakyan ang dapat huminto bago ang bawat tawiran ng tren, kahit walang paparating na tren?","o":["Mga bus, school bus at trak na may kargang mapanganib na materyales","Mga motorsiklo at moped","Lahat ng kotseng may pasahero","Mga sasakyang may hilang trailer lang"],"h1":"Maraming tao o mapanganib na karga ang dala ng mga sasakyang ito.","h2":"Sa Maryland, ang mga bus, school bus at trak na may kargang mapanganib na materyales ay dapat huminto bago ang bawat tawiran ng tren, kaya maging handa na huminto sila.","p":"Tama. Humihinto sa bawat tawiran ang mga bus, school bus at trak na may mapanganib na materyales."},"ar":{"q":"في Maryland، أي المركبات يجب أن تتوقف قبل كل معبر سكة حديدية، حتى عندما لا يكون هناك قطار قادم؟","o":["الحافلات والحافلات المدرسية والشاحنات التي تنقل مواد خطرة","الدراجات النارية والدراجات الصغيرة (mopeds)","كل السيارات التي فيها ركّاب","المركبات التي تجرّ مقطورة فقط"],"h1":"هذه المركبات تنقل أشخاصًا كثيرين أو حمولات خطرة.","h2":"في Maryland، يجب أن تتوقف الحافلات والحافلات المدرسية والشاحنات التي تنقل مواد خطرة قبل كل معبر سكة حديدية، فكن مستعدًا لتوقّفها.","p":"صحيح. الحافلات والحافلات المدرسية وشاحنات المواد الخطرة تتوقف عند كل معبر."},"ref":{"doc":"MD","page":30}},{"id":"md-050","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, how must a child younger than 2 ride in a car?","o":["In a booster seat facing forward","In a rear-facing child safety seat","On an adult's lap with a seat belt","In the front seat with the air bag on"],"h1":"The youngest children face the back of the car.","h2":"In Maryland, a child younger than 2 must ride in a rear-facing child safety seat until reaching the height or weight the seat maker sets.","p":"Right. Children under 2 ride in a rear-facing seat."},"es":{"q":"En Maryland, ¿cómo debe viajar en un carro un niño menor de 2 años?","o":["En un asiento elevado mirando hacia adelante","En un asiento de seguridad para niños mirando hacia atrás","En las piernas de un adulto con el cinturón","En el asiento delantero con la bolsa de aire activada"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Maryland, un niño menor de 2 años debe viajar en un asiento de seguridad mirando hacia atrás hasta llegar a la estatura o el peso que indica el fabricante del asiento.","p":"Correcto. Los niños menores de 2 años viajan en un asiento mirando hacia atrás."},"zh":{"q":"在 Maryland，2 岁以下的孩子坐车时必须怎么坐？","o":["坐在面向前方的增高座椅上","坐在面向后方的儿童安全座椅上","坐在大人腿上，系上安全带","坐在前座，安全气囊打开"],"h1":"年纪最小的孩子面向车的后方。","h2":"在 Maryland，2 岁以下的孩子必须坐在面向后方的儿童安全座椅上，直到达到座椅厂家规定的身高或体重。","p":"对。2 岁以下的孩子坐面向后方的座椅。"},"vi":{"q":"Ở Maryland, trẻ dưới 2 tuổi phải ngồi trên xe như thế nào?","o":["Trên ghế nâng (booster seat) quay mặt về phía trước","Trên ghế an toàn cho trẻ em quay mặt về phía sau","Trên đùi người lớn có thắt dây an toàn","Ở ghế trước với túi khí đang bật"],"h1":"Những trẻ nhỏ nhất ngồi quay mặt về phía sau xe.","h2":"Ở Maryland, trẻ dưới 2 tuổi phải ngồi trên ghế an toàn cho trẻ em quay mặt về phía sau cho đến khi đạt chiều cao hoặc cân nặng mà nhà sản xuất ghế quy định.","p":"Đúng. Trẻ dưới 2 tuổi ngồi ghế quay mặt về phía sau."},"tl":{"q":"Sa Maryland, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang?","o":["Sa booster seat na nakaharap sa unahan","Sa rear-facing child safety seat (nakaharap sa likod)","Sa kandungan ng adult na may seat belt","Sa upuan sa harap na naka-on ang air bag"],"h1":"Nakaharap sa likod ng kotse ang pinakamaliliit na bata.","h2":"Sa Maryland, ang batang wala pang 2 taong gulang ay dapat nakasakay sa child safety seat na nakaharap sa likod hanggang maabot niya ang taas o bigat na itinakda ng gumawa ng upuan.","p":"Tama. Ang mga batang wala pang 2 ay nakasakay sa upuang nakaharap sa likod."},"ar":{"q":"في Maryland، كيف يجب أن يركب الطفل الذي عمره أقل من سنتين (2) في السيارة؟","o":["في مقعد رافع (booster seat) متّجه إلى الأمام","في مقعد أمان للأطفال متّجه إلى الخلف","في حضن شخص بالغ مع حزام الأمان","في المقعد الأمامي والوسادة الهوائية مشغّلة"],"h1":"أصغر الأطفال يكونون متّجهين إلى خلف السيارة.","h2":"في Maryland، يجب أن يركب الطفل الذي عمره أقل من سنتين (2) في مقعد أمان للأطفال متّجه إلى الخلف، حتى يصل إلى الطول أو الوزن الذي تحدّده الشركة المصنّعة للمقعد.","p":"صحيح. الأطفال الذين أعمارهم أقل من سنتين (2) يركبون في مقعد متّجه إلى الخلف."},"ref":{"doc":"MD","page":52}},{"id":"md-051","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, on which roads may mopeds and motor scooters be ridden?","o":["Only on sidewalks and bike paths","On any road, including interstates","On roads with a posted speed limit of 50 mph or less","Only on roads with a speed limit of 25 mph or less"],"h1":"They are kept off the fastest roads.","h2":"In Maryland, mopeds and motor scooters may be ridden on any road with a posted speed limit of 50 mph or less.","p":"Right. Mopeds and scooters may use roads posted at 50 mph or less."},"es":{"q":"En Maryland, ¿en qué carreteras se pueden manejar los ciclomotores y las motonetas?","o":["Solo en las aceras y los caminos para bicicletas","En cualquier carretera, incluso las interestatales","En carreteras con un límite de velocidad de 50 mph o menos","Solo en carreteras con un límite de 25 mph o menos"],"h1":"Se mantienen fuera de las carreteras más rápidas.","h2":"En Maryland, los ciclomotores y las motonetas se pueden manejar en cualquier carretera con un límite de velocidad de 50 mph o menos.","p":"Correcto. Los ciclomotores y las motonetas pueden usar carreteras con límite de 50 mph o menos."},"zh":{"q":"在 Maryland，轻便摩托车（moped）和小型摩托车（motor scooter）可以在哪些道路上骑？","o":["只能在人行道和自行车道上","任何道路都可以，包括州际公路","标明限速 50 mph 或以下的道路","只能在限速 25 mph 或以下的道路上"],"h1":"它们不能上最快的道路。","h2":"在 Maryland，轻便摩托车和小型摩托车可以在任何标明限速 50 mph 或以下的道路上骑。","p":"对。轻便摩托车和小型摩托车可以上标明限速 50 mph 或以下的道路。"},"vi":{"q":"Ở Maryland, xe gắn máy nhỏ (moped) và xe tay ga (motor scooter) được chạy trên những con đường nào?","o":["Chỉ trên vỉa hè và đường dành cho xe đạp","Trên bất kỳ đường nào, kể cả xa lộ liên bang","Trên những con đường có biển giới hạn tốc độ 50 mph trở xuống","Chỉ trên những con đường có giới hạn tốc độ 25 mph trở xuống"],"h1":"Chúng không được chạy trên những con đường nhanh nhất.","h2":"Ở Maryland, xe gắn máy nhỏ và xe tay ga được chạy trên bất kỳ con đường nào có biển giới hạn tốc độ 50 mph trở xuống.","p":"Đúng. Xe gắn máy nhỏ và xe tay ga được chạy trên đường có biển 50 mph trở xuống."},"tl":{"q":"Sa Maryland, sa aling mga kalsada puwedeng gamitin ang mga moped at motor scooter?","o":["Sa mga bangketa at bike path lang","Sa kahit anong kalsada, kasama ang mga interstate","Sa mga kalsadang may nakapaskil na speed limit na 50 mph o mas mababa","Sa mga kalsadang may speed limit na 25 mph o mas mababa lang"],"h1":"Hindi sila pinapayagan sa pinakamabibilis na kalsada.","h2":"Sa Maryland, puwedeng gamitin ang mga moped at motor scooter sa kahit anong kalsadang may nakapaskil na speed limit na 50 mph o mas mababa.","p":"Tama. Puwedeng gamitin ng mga moped at scooter ang mga kalsadang may nakapaskil na 50 mph o mas mababa."},"ar":{"q":"في Maryland، على أي طرق يجوز ركوب الدراجات الصغيرة (mopeds) والسكوترات الآلية (motor scooters)؟","o":["على الأرصفة ومسارات الدراجات فقط","على أي طريق، بما في ذلك الطرق السريعة بين الولايات","على الطرق التي تحمل لافتة حد سرعة 50 mph أو أقل","فقط على الطرق التي حد السرعة فيها 25 mph أو أقل"],"h1":"يُمنع ركوبها على أسرع الطرق.","h2":"في Maryland، يجوز ركوب الدراجات الصغيرة والسكوترات الآلية على أي طريق يحمل لافتة حد سرعة 50 mph أو أقل.","p":"صحيح. يجوز للدراجات الصغيرة والسكوترات استعمال الطرق التي تحمل لافتة 50 mph أو أقل."},"ref":{"doc":"MD","page":41}},{"id":"md-052","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, how wide must your continuous field of vision be to qualify for a driver's license?","o":["At least 90 degrees","At least 110 degrees","At least 140 degrees","At least 180 degrees"],"h1":"It is a little more than a right angle and a half.","h2":"In Maryland, you need a continuous field of vision of at least 140 degrees to qualify for a license.","p":"Right! Maryland asks for a field of vision of at least 140 degrees."},"es":{"q":"En Maryland, ¿qué tan amplio debe ser su campo visual continuo para obtener una licencia de conducir?","o":["Al menos 90 grados","Al menos 110 grados","Al menos 140 grados","Al menos 180 grados"],"h1":"Es un poco más que un ángulo recto y medio.","h2":"En Maryland, usted necesita un campo visual continuo de al menos 140 grados para obtener la licencia.","p":"¡Correcto! Maryland pide un campo visual de al menos 140 grados."},"ref":{"doc":"MD","page":7}},{"id":"md-053","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, where does the driving skills test take place?","o":["On public roads and on a special course at the test site","Only on a closed course at the MVA","Only on a highway near the MVA","Only in a driving simulator at the MVA"],"h1":"The test has two parts in two different places.","h2":"In Maryland, the driving skills test includes driving on public roads and a special course at the testing location.","p":"Yes! The test uses both public roads and a course at the test site."},"es":{"q":"En Maryland, ¿dónde se hace el examen práctico de manejo?","o":["En vías públicas y en una pista especial del lugar del examen","Solo en una pista cerrada de la MVA","Solo en una autopista cerca de la MVA","Solo en un simulador de manejo de la MVA"],"h1":"El examen tiene dos partes en dos lugares distintos.","h2":"En Maryland, el examen práctico incluye manejar en vías públicas y en una pista especial del lugar del examen.","p":"¡Sí! El examen usa vías públicas y una pista en el lugar del examen."},"ref":{"doc":"MD","page":7}},{"id":"md-054","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, who may ride in the car during your driving skills test?","o":["You, the examiner and your supervising driver","You, the examiner and one family member","Anyone you choose, if they wear a seat belt","Only you, the examiner and an MVA-approved interpreter if needed"],"h1":"The supervising driver comes to the test site but waits outside the car.","h2":"In Maryland, only you and the examiner may be in the car during the skills test, plus an MVA-approved interpreter if you need one.","p":"Correct! Only you, the examiner and an approved interpreter may ride along."},"es":{"q":"En Maryland, ¿quién puede ir en el carro durante su examen práctico de manejo?","o":["Usted, el examinador y su conductor supervisor","Usted, el examinador y un familiar","Cualquier persona que usted elija, si usa el cinturón","Solo usted, el examinador y un intérprete aprobado por la MVA si lo necesita"],"h1":"El conductor supervisor va al lugar del examen, pero espera fuera del carro.","h2":"En Maryland, durante el examen práctico solo pueden ir usted y el examinador, más un intérprete aprobado por la MVA si lo necesita.","p":"¡Correcto! Solo van usted, el examinador y un intérprete aprobado."},"ref":{"doc":"MD","page":8}},{"id":"md-055","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, your car for the driving skills test has a crack across the windshield in front of you. What happens?","o":["You may use it if the crack is taped","The car cannot be used for the test","You may use it if you bring a mechanic's note","The examiner will lower your score a little"],"h1":"The car must give you a clear view to the front.","h2":"In Maryland, a test car must not have cracks or other things on the windshield that could block your view, so that car cannot be used.","p":"Right! A cracked windshield keeps the car out of the test."},"es":{"q":"En Maryland, el carro para su examen práctico tiene una grieta en el parabrisas frente a usted. ¿Qué pasa?","o":["Puede usarlo si tapa la grieta con cinta","No se puede usar ese carro para el examen","Puede usarlo si trae una nota de un mecánico","El examinador le bajará un poco la nota"],"h1":"El carro debe darle una vista clara hacia el frente.","h2":"En Maryland, el carro del examen no debe tener grietas ni otras cosas en el parabrisas que afecten la vista, así que ese carro no se puede usar.","p":"¡Correcto! Un parabrisas agrietado deja al carro fuera del examen."},"ref":{"doc":"MD","page":8}},{"id":"md-056","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, who must come with you to the driving skills test site?","o":["A parent, even if you are an adult","A supervising driver","Your driving school instructor","A lawyer or notary"],"h1":"You arrive with a learner's permit, so you cannot drive there alone.","h2":"In Maryland, a supervising driver must come with you to the driving test site.","p":"Yes! A supervising driver must come with you to the test."},"es":{"q":"En Maryland, ¿quién debe acompañarlo al lugar del examen práctico de manejo?","o":["Uno de sus padres, aunque usted sea adulto","Un conductor supervisor","Su instructor de la escuela de manejo","Un abogado o un notario"],"h1":"Usted llega con un permiso de aprendizaje, así que no puede manejar solo hasta allí.","h2":"En Maryland, un conductor supervisor debe acompañarlo al lugar del examen práctico.","p":"¡Sí! Un conductor supervisor debe ir con usted al examen."},"ref":{"doc":"MD","page":8}},{"id":"md-057","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, according to the Driver's Manual, what penalty can littering on the road bring?","o":["A fine up to $50 and no jail time","A warning letter from the MVA only","A fine up to $15,000 or 3 years in prison","A fine up to $1,500 or 30 days in prison"],"h1":"It is more than a thousand dollars, or about a month in prison.","h2":"In Maryland, the Driver's Manual warns that littering can bring a fine of up to $1,500 or 30 days in prison.","p":"Correct! Littering can cost up to $1,500 or 30 days in prison."},"es":{"q":"En Maryland, según el manual del conductor, ¿qué sanción puede traer tirar basura en la carretera?","o":["Una multa de hasta $50 y nada de cárcel","Solo una carta de advertencia de la MVA","Una multa de hasta $15,000 o 3 años de cárcel","Una multa de hasta $1,500 o 30 días de cárcel"],"h1":"Es más de mil dólares, o cerca de un mes de cárcel.","h2":"En Maryland, el manual del conductor advierte que tirar basura puede costar una multa de hasta $1,500 o 30 días de cárcel.","p":"¡Correcto! Tirar basura puede costar hasta $1,500 o 30 días de cárcel."},"ref":{"doc":"MD","page":8}},{"id":"md-058","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, which license class lets you drive regular cars, pickup trucks and vans?","o":["Class C","Class A","Class M","Class H"],"h1":"It is the noncommercial driver's license most people get.","h2":"In Maryland, the noncommercial license for cars, pickup trucks and vans is called a Class C license.","p":"Right! Class C is the regular noncommercial license."},"es":{"q":"En Maryland, ¿qué clase de licencia le permite manejar carros comunes, camionetas pickup y vans?","o":["Clase C","Clase A","Clase M","Clase H"],"h1":"Es la licencia no comercial que tiene la mayoría de la gente.","h2":"En Maryland, la licencia no comercial para carros, camionetas pickup y vans se llama licencia Clase C.","p":"¡Correcto! La Clase C es la licencia no comercial común."},"ref":{"doc":"MD","page":9}},{"id":"md-059","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, which copy of your birth certificate will the MVA accept when you apply?","o":["A clear photocopy","A notarized photocopy","The original or a copy certified by the agency that issued it","A photo of it on your phone"],"h1":"The MVA wants the real record or one stamped by the office that made it.","h2":"In Maryland, you must bring original documents or copies certified by the agency that issued them; photocopies and notarized copies are not accepted.","p":"Correct! Only originals or agency-certified copies are accepted."},"es":{"q":"En Maryland, ¿qué copia de su acta de nacimiento aceptará la MVA cuando haga su solicitud?","o":["Una fotocopia clara","Una fotocopia notariada","El original o una copia certificada por la oficina que lo emitió","Una foto del acta en su teléfono"],"h1":"La MVA quiere el documento real o uno sellado por la oficina que lo hizo.","h2":"En Maryland, debe llevar documentos originales o copias certificadas por la oficina que los emitió; no se aceptan fotocopias ni copias notariadas.","p":"¡Correcto! Solo se aceptan originales o copias certificadas."},"ref":{"doc":"MD","page":9}},{"id":"md-060","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a licensed driver wants a Type 2 learner's permit for a different class of license. What is the youngest age to apply?","o":["15 years and 9 months","16 years","16 years and 6 months","18 years"],"h1":"It is half a year past a 16th birthday.","h2":"In Maryland, you must be at least 16 years and 6 months old to get a Type 2 learner's permit.","p":"Yes! The Type 2 permit starts at 16 years and 6 months."},"es":{"q":"En Maryland, un conductor con licencia quiere un permiso de aprendizaje Tipo 2 para otra clase de licencia. ¿Cuál es la edad mínima para solicitarlo?","o":["15 años y 9 meses","16 años","16 años y 6 meses","18 años"],"h1":"Es medio año después de cumplir 16.","h2":"En Maryland, debe tener al menos 16 años y 6 meses para obtener un permiso de aprendizaje Tipo 2.","p":"¡Sí! El permiso Tipo 2 empieza a los 16 años y 6 meses."},"ref":{"doc":"MD","page":9}},{"id":"md-061","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, how long is a Type 2 learner's permit valid?","o":["Up to 180 days","Up to 30 days","Up to 1 year","Up to 2 years"],"h1":"It is about six months.","h2":"In Maryland, a Type 2 learner's permit lasts for up to 180 days.","p":"Correct! A Type 2 permit lasts up to 180 days."},"es":{"q":"En Maryland, ¿por cuánto tiempo es válido un permiso de aprendizaje Tipo 2?","o":["Hasta 180 días","Hasta 30 días","Hasta 1 año","Hasta 2 años"],"h1":"Son unos seis meses.","h2":"En Maryland, un permiso de aprendizaje Tipo 2 dura hasta 180 días.","p":"¡Correcto! El permiso Tipo 2 dura hasta 180 días."},"ref":{"doc":"MD","page":9}},{"id":"md-062","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a 15-year-old applies for a learner's permit. Which extra form must they bring?","o":["A letter from a family doctor","A signed note from a neighbor","A report card with all passing grades","A Learner's Permit School Attendance Certification form"],"h1":"It shows the school confirms you attend.","h2":"In Maryland, an applicant under 16 must bring a completed Learner's Permit School Attendance Certification form (DL-300).","p":"Right! Under 16, you need the school attendance certification form."},"es":{"q":"En Maryland, una persona de 15 años solicita un permiso de aprendizaje. ¿Qué formulario adicional debe traer?","o":["Una carta del médico de la familia","Una nota firmada por un vecino","Una boleta con todas las materias aprobadas","Un formulario de Certificación de Asistencia Escolar para el permiso"],"h1":"Muestra que la escuela confirma que usted asiste a clases.","h2":"En Maryland, quien tiene menos de 16 años debe traer el formulario completo de Certificación de Asistencia Escolar para el permiso (DL-300).","p":"¡Correcto! Antes de los 16, necesita la certificación de asistencia escolar."},"ref":{"doc":"MD","page":9}},{"id":"md-063","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, where does a learner record the supervised practice hours?","o":["On the back of the learner's permit","In the Practice and Skills Log","In a letter to the MVA each month","In an app run by the driving school only"],"h1":"The MVA website has the form, and you hand it in later.","h2":"In Maryland, learners record their practice hours in the Practice and Skills Log and submit it, signed, before the provisional license.","p":"Yes! Practice hours go in the Practice and Skills Log."},"es":{"q":"En Maryland, ¿dónde anota el aprendiz sus horas de práctica supervisada?","o":["En la parte de atrás del permiso de aprendizaje","En el Registro de Práctica y Habilidades (Practice and Skills Log)","En una carta mensual a la MVA","Solo en una aplicación de la escuela de manejo"],"h1":"El formulario está en el sitio web de la MVA y se entrega después.","h2":"En Maryland, los aprendices anotan sus horas en el Registro de Práctica y Habilidades y lo entregan firmado antes de la licencia provisional.","p":"¡Sí! Las horas se anotan en el Registro de Práctica y Habilidades."},"ref":{"doc":"MD","page":10}},{"id":"md-064","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, what is the youngest age to get a full (not provisional) driver's license?","o":["17","18","16 and a half","21"],"h1":"It is the age when you become an adult.","h2":"In Maryland, you must be at least 18 years old to get a full driver's license.","p":"Correct! A full Maryland license starts at 18."},"es":{"q":"En Maryland, ¿cuál es la edad mínima para obtener una licencia de conducir completa (no provisional)?","o":["17 años","18 años","16 años y medio","21 años"],"h1":"Es la edad en que usted se hace adulto.","h2":"En Maryland, debe tener al menos 18 años para obtener una licencia de conducir completa.","p":"¡Correcto! La licencia completa en Maryland empieza a los 18."},"ref":{"doc":"MD","page":11}},{"id":"md-065","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a provisional driver wants a full license. For how long must their record be free of moving violations?","o":["The past 6 months","The past 3 years","The past 30 days","The past 18 months"],"h1":"It is the same length as the provisional stage itself.","h2":"In Maryland, you may not have any moving violation convictions or probation before judgment within the past 18 months to get a full license.","p":"Right! You need 18 months with no moving violations."},"es":{"q":"En Maryland, un conductor provisional quiere la licencia completa. ¿Por cuánto tiempo debe estar su récord libre de infracciones de tránsito en movimiento?","o":["Los últimos 6 meses","Los últimos 3 años","Los últimos 30 días","Los últimos 18 meses"],"h1":"Es el mismo tiempo que dura la etapa provisional.","h2":"En Maryland, no puede tener condenas ni libertad condicional antes del fallo por infracciones en movimiento en los últimos 18 meses para obtener la licencia completa.","p":"¡Correcto! Necesita 18 meses sin infracciones en movimiento."},"ref":{"doc":"MD","page":11}},{"id":"md-066","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, you meet every requirement to move from a provisional license to a full license. What happens next?","o":["The MVA switches it automatically and mails you a card","You must take the knowledge test again","You must book a new driving skills test","You must visit a court to sign a form"],"h1":"You do not need to go anywhere.","h2":"In Maryland, the MVA automatically changes your provisional license to a full license and mails you a card that you carry with your provisional license.","p":"Yes! The MVA does it automatically and mails you a card."},"es":{"q":"En Maryland, usted cumple todos los requisitos para pasar de la licencia provisional a la completa. ¿Qué pasa después?","o":["La MVA la cambia automáticamente y le envía una tarjeta por correo","Debe tomar otra vez el examen teórico","Debe sacar cita para otro examen práctico","Debe ir a un tribunal a firmar un formulario"],"h1":"No tiene que ir a ninguna parte.","h2":"En Maryland, la MVA cambia automáticamente su licencia provisional a completa y le envía por correo una tarjeta que usted lleva junto con la licencia provisional.","p":"¡Sí! La MVA lo hace sola y le envía una tarjeta."},"ref":{"doc":"MD","page":11}},{"id":"md-067","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a 17-year-old is married. Who may co-sign their license application?","o":["Any friend who is 16 or older","No one; married teens cannot apply","Their husband or wife, if the spouse is 18 or older","Only the high school principal"],"h1":"Proof of the marriage is needed, and the spouse must be an adult.","h2":"In Maryland, a married minor's husband or wife may co-sign if the spouse is 18 or older and proof of marriage is shown.","p":"Correct! An adult spouse may co-sign."},"es":{"q":"En Maryland, una persona de 17 años está casada. ¿Quién puede firmar como corresponsable su solicitud de licencia?","o":["Cualquier amigo de 16 años o más","Nadie; los adolescentes casados no pueden solicitar","Su esposo o esposa, si tiene 18 años o más","Solo el director de la escuela secundaria"],"h1":"Se necesita prueba del matrimonio, y el cónyuge debe ser adulto.","h2":"En Maryland, el esposo o la esposa de un menor casado puede firmar como corresponsable si tiene 18 años o más y se muestra prueba del matrimonio.","p":"¡Correcto! Un cónyuge adulto puede firmar."},"ref":{"doc":"MD","page":11}},{"id":"md-068","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, a 16-year-old has no parent, legal guardian or spouse. Who may co-sign the license application?","o":["Another 16-year-old friend","No one; they must wait until 18","A responsible adult, such as an employer","Any MVA employee at the counter"],"h1":"Proof is needed, such as the parents' death certificates or emancipation papers.","h2":"In Maryland, if a minor has no parent, guardian or spouse, a responsible adult such as an employer may co-sign, with proof.","p":"Right! A responsible adult, like an employer, may co-sign."},"es":{"q":"En Maryland, una persona de 16 años no tiene padres, tutor legal ni cónyuge. ¿Quién puede firmar como corresponsable su solicitud?","o":["Otro amigo de 16 años","Nadie; debe esperar hasta los 18","Un adulto responsable, como un empleador","Cualquier empleado de la MVA en la ventanilla"],"h1":"Se necesita una prueba, como las actas de defunción de los padres o papeles de emancipación.","h2":"En Maryland, si un menor no tiene padres, tutor ni cónyuge, un adulto responsable como un empleador puede firmar, con pruebas.","p":"¡Correcto! Un adulto responsable, como un empleador, puede firmar."},"ref":{"doc":"MD","page":11}},{"id":"md-069","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a parent who co-signed for a 17-year-old wants the teen's license canceled. What must the parent do?","o":["Send a written request to the MVA's Administrative Adjudication Division","Call the police and report the teen","Take the license card and cut it up","Tell the driving school to cancel it"],"h1":"It must be in writing, to a special MVA office.","h2":"In Maryland, a co-signer may cancel a minor's license by sending a written request to the MVA's Administrative Adjudication Division.","p":"Yes! The co-signer sends a written request to that MVA division."},"es":{"q":"En Maryland, uno de los padres que firmó por un joven de 17 años quiere cancelar su licencia. ¿Qué debe hacer?","o":["Enviar una solicitud por escrito a la División de Adjudicación Administrativa de la MVA","Llamar a la policía y denunciar al joven","Quitarle la tarjeta de la licencia y cortarla","Pedirle a la escuela de manejo que la cancele"],"h1":"Debe ser por escrito, a una oficina especial de la MVA.","h2":"En Maryland, quien firmó como corresponsable puede cancelar la licencia de un menor con una solicitud por escrito a la División de Adjudicación Administrativa de la MVA.","p":"¡Sí! Se envía una solicitud escrita a esa división de la MVA."},"ref":{"doc":"MD","page":11}},{"id":"md-070","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a co-signer cancels a minor's license. How long does it stay canceled?","o":["For 30 days only","For 1 year, then it returns by itself","Forever, with no way to get a new one","Until the driver turns 18, unless someone co-signs a new application"],"h1":"A birthday ends it, or a new co-signer can.","h2":"In Maryland, a license canceled by the co-signer stays canceled until the driver turns 18, unless a qualified co-signer signs a new application.","p":"Correct! It stays canceled until 18, unless there is a new co-signer."},"es":{"q":"En Maryland, un corresponsable cancela la licencia de un menor. ¿Por cuánto tiempo sigue cancelada?","o":["Solo por 30 días","Por 1 año, y luego vuelve sola","Para siempre, sin forma de obtener otra","Hasta que el conductor cumpla 18, salvo que alguien firme una nueva solicitud"],"h1":"Un cumpleaños la termina, o un nuevo corresponsable.","h2":"En Maryland, una licencia cancelada por el corresponsable sigue cancelada hasta que el conductor cumpla 18, salvo que un corresponsable calificado firme una nueva solicitud.","p":"¡Correcto! Sigue cancelada hasta los 18, salvo con un nuevo corresponsable."},"ref":{"doc":"MD","page":11}},{"id":"md-071","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, you have a driver's license from another country. Besides the vision, knowledge and driving tests, what must you complete?","o":["A 30-hour classroom driver education course","A 3-hour roadway safety driving education program","60 hours of supervised practice","A 6-month learner's permit period"],"h1":"It is a short course, just a few hours long.","h2":"In Maryland, drivers with a license from another country must also complete an MVA-approved 3-hour roadway safety driving education program.","p":"Right! You also need the 3-hour roadway safety program."},"es":{"q":"En Maryland, usted tiene una licencia de otro país. Además de los exámenes de la vista, teórico y práctico, ¿qué debe completar?","o":["Un curso de manejo de 30 horas en el aula","Un programa de educación vial de 3 horas","60 horas de práctica supervisada","Un periodo de 6 meses con permiso de aprendizaje"],"h1":"Es un curso corto, de pocas horas.","h2":"En Maryland, quienes tienen licencia de otro país también deben completar un programa de educación vial de 3 horas aprobado por la MVA.","p":"¡Correcto! También necesita el programa de seguridad vial de 3 horas."},"ref":{"doc":"MD","page":11}},{"id":"md-072","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, your foreign driver's license is not in English. What must you also have?","o":["A letter from your employer","An International License or an approved English translation","A photocopy signed by a friend who speaks English","Nothing more; any language is accepted"],"h1":"The MVA needs to read it in English.","h2":"In Maryland, if your license from another country is not in English, you must also have an International License or a translation into English by an approved provider, court translator or your country's embassy.","p":"Yes! You need an International License or an approved translation."},"es":{"q":"En Maryland, su licencia extranjera no está en inglés. ¿Qué más debe tener?","o":["Una carta de su empleador","Una Licencia Internacional o una traducción al inglés aprobada","Una fotocopia firmada por un amigo que habla inglés","Nada más; se acepta cualquier idioma"],"h1":"La MVA necesita leerla en inglés.","h2":"En Maryland, si su licencia de otro país no está en inglés, también debe tener una Licencia Internacional o una traducción al inglés hecha por un proveedor aprobado, un traductor judicial o la embajada de su país.","p":"¡Sí! Necesita una Licencia Internacional o una traducción aprobada."},"ref":{"doc":"MD","page":11}},{"id":"md-073","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, you use an interpreter at the MVA for your test. Who pays the interpreter?","o":["The MVA pays the interpreter","The interpreter works for free by law","Your driving school must pay","You do; the MVA charges no fee of its own"],"h1":"The MVA adds no fee, but the interpreter's work is not free.","h2":"In Maryland, the MVA does not charge a fee for using an interpreter, but you must pay the interpreter for their services.","p":"Correct! You pay the interpreter yourself."},"es":{"q":"En Maryland, usted usa un intérprete en la MVA para su examen. ¿Quién le paga al intérprete?","o":["La MVA le paga al intérprete","El intérprete trabaja gratis por ley","Su escuela de manejo debe pagar","Usted; la MVA no cobra ninguna tarifa propia"],"h1":"La MVA no agrega una tarifa, pero el trabajo del intérprete no es gratis.","h2":"En Maryland, la MVA no cobra por usar un intérprete, pero usted debe pagarle al intérprete por sus servicios.","p":"¡Correcto! Usted le paga al intérprete."},"ref":{"doc":"MD","page":12}},{"id":"md-074","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, which of these may an interpreter who helps with your knowledge test NOT do for you?","o":["Certify your Maryland address","Show a photo ID to MVA staff","Translate the test questions for you","Be on the MVA's approved list"],"h1":"An interpreter for testing may not provide other services to the person being tested.","h2":"In Maryland, an interpreter for your test may not provide other services, such as certifying your residence, running driving school business or issuing lease papers.","p":"Right! A testing interpreter cannot certify your residence."},"es":{"q":"En Maryland, ¿qué de lo siguiente NO puede hacer por usted el intérprete que lo ayuda con el examen teórico?","o":["Certificar su domicilio en Maryland","Mostrar una identificación con foto al personal de la MVA","Traducirle las preguntas del examen","Estar en la lista aprobada de la MVA"],"h1":"Un intérprete de examen no puede dar otros servicios a la persona examinada.","h2":"En Maryland, el intérprete de su examen no puede darle otros servicios, como certificar su domicilio, hacer trámites de escuela de manejo o emitir contratos de alquiler.","p":"¡Correcto! El intérprete del examen no puede certificar su domicilio."},"ref":{"doc":"MD","page":12}},{"id":"md-075","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what is the Developmental Disability Disclosure Card?","o":["A card every driver with a disability must carry","A parking permit for people with disabilities","A voluntary blue card you may carry with your license","A card the police give after a traffic stop"],"h1":"You decide whether you want one, and no medical proof is asked.","h2":"In Maryland, the Developmental Disability Disclosure Card is a voluntary blue card you may carry with your license to share how best to communicate with you.","p":"Yes! It is a voluntary blue card you may carry."},"es":{"q":"En Maryland, ¿qué es la Tarjeta de Divulgación de Discapacidad del Desarrollo?","o":["Una tarjeta obligatoria para todo conductor con discapacidad","Un permiso de estacionamiento para personas con discapacidad","Una tarjeta azul voluntaria que puede llevar con su licencia","Una tarjeta que da la policía después de una parada"],"h1":"Usted decide si la quiere, y no le piden pruebas médicas.","h2":"En Maryland, la Tarjeta de Divulgación de Discapacidad del Desarrollo es una tarjeta azul voluntaria que puede llevar con su licencia para explicar cómo comunicarse mejor con usted.","p":"¡Sí! Es una tarjeta azul voluntaria que puede llevar."},"ref":{"doc":"MD","page":12}},{"id":"md-076","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, which papers must you have with you every time you drive?","o":["Your birth certificate and passport","Your Social Security card and a utility bill","Your permit or license and the vehicle registration card","Your car title and repair records"],"h1":"One shows you may drive; the other belongs to the car.","h2":"In Maryland, you must have a valid learner's permit or driver's license and the vehicle registration card with you when you drive.","p":"Correct! Carry your permit or license and the registration card."},"es":{"q":"En Maryland, ¿qué documentos debe llevar cada vez que maneja?","o":["Su acta de nacimiento y su pasaporte","Su tarjeta del Seguro Social y una factura de servicios","Su permiso o licencia y la tarjeta de registro del vehículo","El título del carro y los recibos de reparación"],"h1":"Uno muestra que usted puede manejar; el otro es del carro.","h2":"En Maryland, debe llevar un permiso de aprendizaje o una licencia válida y la tarjeta de registro del vehículo cuando maneja.","p":"¡Correcto! Lleve su permiso o licencia y la tarjeta de registro."},"ref":{"doc":"MD","page":13}},{"id":"md-077","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maryland, you are following a delivery van that stops often. How much following distance does the MVA suggest?","o":["4 to 5 seconds, or more if needed","1 to 2 seconds","2 to 3 seconds","One car length for each 20 mph"],"h1":"It is more than the normal 3 to 4 seconds.","h2":"In Maryland, when you follow vehicles that stop often, such as buses and delivery vans, you should increase your following distance to 4 or 5 seconds, or more.","p":"Right! Behind vehicles that stop often, keep 4 to 5 seconds or more."},"es":{"q":"En Maryland, usted va detrás de una camioneta de reparto que se detiene seguido. ¿Qué distancia de seguimiento sugiere la MVA?","o":["De 4 a 5 segundos, o más si hace falta","De 1 a 2 segundos","De 2 a 3 segundos","El largo de un carro por cada 20 mph"],"h1":"Es más que los 3 a 4 segundos normales.","h2":"En Maryland, cuando sigue vehículos que paran seguido, como autobuses y camionetas de reparto, debe aumentar la distancia a 4 o 5 segundos, o más.","p":"¡Correcto! Detrás de vehículos que paran seguido, deje 4 a 5 segundos o más."},"ref":{"doc":"MD","page":15}},{"id":"md-078","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, U-turns are allowed where you are. Which lane should you turn into?","o":["The left lane closest to the center line","Any lane that looks empty","The shoulder, then merge back in","The outside, right-hand lane going the other way"],"h1":"Finish the turn in the lane farthest from the middle.","h2":"In Maryland, after signaling left and yielding to oncoming traffic, you should turn into the outside, right-hand lane going in the opposite direction.","p":"Correct! Turn into the outside, right-hand lane."},"es":{"q":"En Maryland, se permiten las vueltas en U donde usted está. ¿A qué carril debe entrar?","o":["Al carril izquierdo más cerca de la línea central","A cualquier carril que se vea vacío","Al acotamiento, y luego volver a entrar","Al carril exterior, el de la derecha, en sentido contrario"],"h1":"Termine la vuelta en el carril más lejos del centro.","h2":"En Maryland, después de señalar a la izquierda y ceder el paso al tráfico que viene, debe entrar al carril exterior de la derecha que va en sentido contrario.","p":"¡Correcto! Entre al carril exterior de la derecha."},"ref":{"doc":"MD","page":15}},{"id":"md-079","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maryland, when may you pass another car on the right?","o":["Whenever the car ahead is going under the speed limit","When it is about to turn left and you can stay on the road safely","When you can use the paved shoulder","Only at night, when the lane is clear"],"h1":"You must stay on the roadway, never on the shoulder.","h2":"In Maryland, you may pass on the right if it is safe and you stay on the road, for example when the other vehicle is about to turn left or on an open road with two or more lanes going your way.","p":"Yes! You may pass on the right of a car turning left, staying on the road."},"es":{"q":"En Maryland, ¿cuándo puede rebasar a otro carro por la derecha?","o":["Siempre que el carro de adelante vaya más lento que el límite","Cuando va a girar a la izquierda y usted puede seguir en la vía con seguridad","Cuando puede usar el acotamiento pavimentado","Solo de noche, cuando el carril está libre"],"h1":"Debe quedarse en la vía, nunca en el acotamiento.","h2":"En Maryland, puede rebasar por la derecha si es seguro y se queda en la vía, por ejemplo cuando el otro vehículo va a girar a la izquierda o en una vía libre con dos o más carriles en su sentido.","p":"¡Sí! Puede rebasar por la derecha a un carro que gira a la izquierda, sin salir de la vía."},"ref":{"doc":"MD","page":16}},{"id":"md-080","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maryland, your view is blocked as you come within 100 feet of a tunnel. May you pass the car ahead?","o":["Yes, if you honk first","No, passing is not allowed there","Yes, if the car ahead is slow","Yes, if it is daytime"],"h1":"You cannot see what is coming out of the tunnel.","h2":"In Maryland, you may not pass when your view is blocked within 100 feet of a bridge, elevated road or tunnel.","p":"Correct! No passing within 100 feet of a tunnel when your view is blocked."},"es":{"q":"En Maryland, su vista está tapada al acercarse a menos de 100 pies de un túnel. ¿Puede rebasar al carro de adelante?","o":["Sí, si toca la bocina antes","No, ahí no se permite rebasar","Sí, si el carro de adelante va lento","Sí, si es de día"],"h1":"No puede ver lo que sale del túnel.","h2":"En Maryland, no puede rebasar cuando su vista está tapada a menos de 100 pies de un puente, una vía elevada o un túnel.","p":"¡Correcto! No se rebasa a menos de 100 pies de un túnel sin buena vista."},"ref":{"doc":"MD","page":16}},{"id":"md-081","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maryland, traffic is slow and the shoulder is empty. May you drive on the shoulder to pass?","o":["Yes, on the right shoulder only","Yes, on the left shoulder only","Yes, if you use your hazard lights","No, passing on the shoulder is not allowed on either side"],"h1":"The shoulder is not a travel lane.","h2":"In Maryland, you may not pass on the shoulder of the road, either on the right or the left.","p":"Right! Never pass on the shoulder."},"es":{"q":"En Maryland, el tráfico va lento y el acotamiento está vacío. ¿Puede manejar por el acotamiento para rebasar?","o":["Sí, solo por el acotamiento derecho","Sí, solo por el acotamiento izquierdo","Sí, si usa las luces intermitentes","No, no se permite rebasar por el acotamiento de ningún lado"],"h1":"El acotamiento no es un carril de circulación.","h2":"En Maryland, no puede rebasar por el acotamiento, ni por la derecha ni por la izquierda.","p":"¡Correcto! Nunca rebase por el acotamiento."},"ref":{"doc":"MD","page":16}},{"id":"md-082","scope":"MD","cat":"signals","sign":null,"c":0,"en":{"q":"In Maryland, you come to a traffic signal that is not working at all. What must you do?","o":["Stop, yield to others in the intersection, then go when safe","Slow down and drive through without stopping","Treat it as a green light if no one is coming","Wait until the signal starts working again"],"h1":"Treat it much like a stop sign.","h2":"In Maryland, at a traffic signal that is not working, you must stop at the stop line, crosswalk or intersection, yield to vehicles and pedestrians, and go only when it is safe.","p":"Yes! Stop, yield, and go only when it is safe."},"es":{"q":"En Maryland, llega a un semáforo que no funciona para nada. ¿Qué debe hacer?","o":["Detenerse, ceder el paso a quienes están en el cruce y seguir cuando sea seguro","Bajar la velocidad y pasar sin detenerse","Tratarlo como luz verde si no viene nadie","Esperar hasta que el semáforo vuelva a funcionar"],"h1":"Trátelo casi como una señal de alto.","h2":"En Maryland, en un semáforo que no funciona, debe detenerse en la línea de alto, el cruce peatonal o la intersección, ceder el paso a vehículos y peatones, y seguir solo cuando sea seguro.","p":"¡Sí! Deténgase, ceda el paso y siga solo cuando sea seguro."},"ref":{"doc":"MD","page":17}},{"id":"md-083","scope":"MD","cat":"signals","sign":null,"c":2,"en":{"q":"In Maryland, to skip a red light, a driver cuts through a gas station lot at the corner. Is this allowed?","o":["Yes, if the driver does not stop at the pumps","Yes, if the light has been red for a long time","No, you may not cross private property to avoid a traffic control device","Yes, if no one is in the parking lot"],"h1":"Leaving the road to get around a signal is against the rules.","h2":"In Maryland, you may not drive across private property or leave the road to avoid obeying a traffic signal, sign or marking.","p":"Correct! Cutting through a lot to avoid a signal is not allowed."},"es":{"q":"En Maryland, para evitar una luz roja, un conductor atraviesa una gasolinera en la esquina. ¿Está permitido?","o":["Sí, si no se detiene en las bombas","Sí, si la luz lleva mucho tiempo en rojo","No, no puede cruzar propiedad privada para evitar un dispositivo de tránsito","Sí, si no hay nadie en el estacionamiento"],"h1":"Salir de la vía para esquivar un semáforo va contra las reglas.","h2":"En Maryland, no puede atravesar propiedad privada ni salir de la vía para evitar un semáforo, una señal o una marca vial.","p":"¡Correcto! No se permite atravesar un lote para evitar un semáforo."},"ref":{"doc":"MD","page":17}},{"id":"md-084","scope":"MD","cat":"signals","sign":null,"c":2,"en":{"q":"In Maryland, a flashing yellow X is shown over a center lane. What may you use the lane for?","o":["Passing slow cars at highway speed","Parking for a short time","A left turn, sharing it with drivers turning from the other way","Driving straight for a long distance"],"h1":"Drivers from both directions may be in this lane.","h2":"In Maryland, a flashing yellow X or two-way left-turn arrows mean you may use the lane to turn left, and you will likely share it with left-turning drivers from the opposite direction.","p":"Yes! It is a left-turn lane shared with the other direction."},"es":{"q":"En Maryland, sobre un carril central se ve una X amarilla intermitente. ¿Para qué puede usar ese carril?","o":["Para rebasar carros lentos a velocidad de autopista","Para estacionarse un rato","Para girar a la izquierda, compartiéndolo con quienes giran desde el otro sentido","Para seguir derecho una larga distancia"],"h1":"Puede haber conductores de ambos sentidos en este carril.","h2":"En Maryland, una X amarilla intermitente o flechas de giro a la izquierda en dos sentidos significan que puede usar el carril para girar a la izquierda, y probablemente lo comparta con quienes giran desde el sentido contrario.","p":"¡Sí! Es un carril para girar a la izquierda compartido con el otro sentido."},"ref":{"doc":"MD","page":18}},{"id":"md-085","scope":"MD","cat":"signals","sign":null,"c":0,"en":{"q":"In Maryland, which signs use a black background?","o":["One Way signs and signs that change their message","Speed limit signs","School zone signs","Hospital and gas signs"],"h1":"One kind points a direction; the other kind is electronic.","h2":"In Maryland, black is used for One Way signs and for signs that change messages.","p":"Correct! Black is for One Way and changeable message signs."},"es":{"q":"En Maryland, ¿qué señales usan fondo negro?","o":["Las señales de Una Vía y las que cambian de mensaje","Las señales de límite de velocidad","Las señales de zona escolar","Las señales de hospital y gasolina"],"h1":"Una indica un sentido; la otra es electrónica.","h2":"En Maryland, el negro se usa en las señales de Una Vía y en las señales de mensaje variable.","p":"¡Correcto! El negro es para Una Vía y mensajes variables."},"ref":{"doc":"MD","page":20}},{"id":"md-086","scope":"MD","cat":"signals","sign":null,"c":3,"en":{"q":"In Maryland, what does a trapezoid-shaped sign usually mark?","o":["A school zone","A railroad crossing ahead","A no-passing zone","Recreation and cultural areas and National Forest Routes"],"h1":"It has four sides, wider at the top than the bottom, and points you to places to visit.","h2":"In Maryland, trapezoid signs mark recreation and cultural interest areas and National Forest Routes.","p":"Right! Trapezoids mark recreation areas and National Forest Routes."},"es":{"q":"En Maryland, ¿qué suele indicar una señal con forma de trapecio?","o":["Una zona escolar","Un cruce de tren más adelante","Una zona donde no se puede rebasar","Áreas recreativas y culturales y Rutas de Bosques Nacionales"],"h1":"Tiene cuatro lados, más ancha arriba que abajo, y lo guía a lugares para visitar.","h2":"En Maryland, las señales en forma de trapecio marcan áreas recreativas y culturales y Rutas de Bosques Nacionales.","p":"¡Correcto! Los trapecios marcan áreas recreativas y Rutas de Bosques Nacionales."},"ref":{"doc":"MD","page":20}},{"id":"md-087","scope":"MD","cat":"signals","sign":null,"c":1,"en":{"q":"In Maryland, double solid yellow lines run down the center. May you cross them to turn left into a driveway?","o":["No, never for any reason","Yes, a left turn across them is allowed","Only if a police officer waves you on","Only between midnight and 5 a.m."],"h1":"The lines stop passing, not turning.","h2":"In Maryland, passing is not allowed across double solid yellow lines, but you may cross them to make a left turn, such as into a driveway.","p":"Yes! You may turn left across double solid yellow lines."},"es":{"q":"En Maryland, hay doble línea amarilla continua en el centro. ¿Puede cruzarla para girar a la izquierda hacia una entrada de garaje?","o":["No, nunca por ningún motivo","Sí, se permite girar a la izquierda cruzándola","Solo si un policía le hace una seña","Solo entre la medianoche y las 5 a.m."],"h1":"Las líneas prohíben rebasar, no girar.","h2":"En Maryland, no se permite rebasar cruzando la doble línea amarilla continua, pero sí puede cruzarla para girar a la izquierda, por ejemplo hacia una entrada de garaje.","p":"¡Sí! Puede girar a la izquierda cruzando la doble línea amarilla."},"ref":{"doc":"MD","page":24}},{"id":"md-088","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, the MVA cites federal data on crashes. Compared with a road limited to 40 mph or less, how much more likely is a crash on a 65 mph road to be deadly?","o":["About the same","Nearly 5 times as likely","About 50 percent more likely","About 20 times as likely"],"h1":"The difference is large, much more than double.","h2":"In Maryland, the Driver's Manual says a crash on a road with a 65 mph limit or higher is nearly 5 times as likely to cause a death as a crash on a road limited to 40 mph or less.","p":"Correct! It is nearly 5 times as likely to be deadly."},"es":{"q":"En Maryland, la MVA cita datos federales sobre choques. Comparado con una vía de 40 mph o menos, ¿cuánto más probable es que un choque en una vía de 65 mph sea mortal?","o":["Más o menos igual","Casi 5 veces más probable","Cerca de un 50 por ciento más","Cerca de 20 veces más"],"h1":"La diferencia es grande, mucho más del doble.","h2":"En Maryland, el manual dice que un choque en una vía con límite de 65 mph o más tiene casi 5 veces más probabilidad de causar una muerte que en una vía de 40 mph o menos.","p":"¡Correcto! Es casi 5 veces más probable que sea mortal."},"ref":{"doc":"MD","page":26}},{"id":"md-089","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you are driving with high beams behind another car. When must you switch to low beams?","o":["When you are 1,000 feet behind it","Only when it is raining","Only if the other driver flashes the lights","When you are 300 feet or less behind it"],"h1":"It is about the length of a football field.","h2":"In Maryland, you must switch to low beams when you follow a vehicle that is 300 feet or less in front of you.","p":"Right! Dim your lights within 300 feet of a car ahead."},"es":{"q":"En Maryland, maneja con luces altas detrás de otro carro. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando está a 1,000 pies detrás de él","Solo cuando llueve","Solo si el otro conductor le hace cambio de luces","Cuando está a 300 pies o menos detrás de él"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En Maryland, debe cambiar a luces bajas cuando sigue a un vehículo que está a 300 pies o menos delante de usted.","p":"¡Correcto! Baje las luces a 300 pies o menos de un carro adelante."},"ref":{"doc":"MD","page":27}},{"id":"md-090","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, the MVA advises using low beam headlights in which of these places, even in daytime?","o":["When entering a tunnel or a construction area","When parked at a gas pump","When driving in a sunny parking lot","When stopped at a toll booth with the engine off"],"h1":"It helps workers and other drivers see you.","h2":"In Maryland, the MVA advises using low beams when entering a tunnel or a construction area, so other drivers and workers can see you.","p":"Yes! Use low beams in tunnels and construction areas."},"es":{"q":"En Maryland, la MVA aconseja usar las luces bajas en cuál de estos lugares, aun de día?","o":["Al entrar a un túnel o a una zona de construcción","Al estar estacionado en una bomba de gasolina","Al manejar en un estacionamiento soleado","Al estar detenido en una caseta de peaje con el motor apagado"],"h1":"Ayuda a que los trabajadores y otros conductores lo vean.","h2":"En Maryland, la MVA aconseja usar las luces bajas al entrar a un túnel o a una zona de construcción, para que otros conductores y trabajadores lo vean.","p":"¡Sí! Use luces bajas en túneles y zonas de construcción."},"ref":{"doc":"MD","page":27}},{"id":"md-091","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, a snow emergency is declared. What should you use on a designated snow emergency route?","o":["Fog lights only","Hazard lights the whole time","Chains, snow tires or radial tires","Nothing special, if you drive slowly"],"h1":"Think about what helps tires grip snow.","h2":"In Maryland, when a snow emergency is declared, you should use chains, snow tires or radial tires on designated snow emergency routes.","p":"Correct! Use chains, snow tires or radials on snow emergency routes."},"es":{"q":"En Maryland, se declara una emergencia por nieve. ¿Qué debería usar en una ruta designada de emergencia por nieve?","o":["Solo luces antiniebla","Las luces intermitentes todo el tiempo","Cadenas, llantas para nieve o llantas radiales","Nada especial, si maneja despacio"],"h1":"Piense en lo que ayuda a las llantas a agarrarse en la nieve.","h2":"En Maryland, cuando se declara una emergencia por nieve, debe usar cadenas, llantas para nieve o llantas radiales en las rutas designadas de emergencia por nieve.","p":"¡Correcto! Use cadenas, llantas para nieve o radiales en esas rutas."},"ref":{"doc":"MD","page":29}},{"id":"md-092","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, the MVA suggests a winter emergency kit for your car. Which item in it helps your tires grip snow and ice?","o":["A bottle of water","An extra phone charger","Kitty litter or sand","A road map"],"h1":"You would spread it under the tires.","h2":"In Maryland, the MVA suggests keeping kitty litter or sand in your emergency kit for traction on snow and ice.","p":"Right! Kitty litter or sand helps with traction."},"es":{"q":"En Maryland, la MVA sugiere un kit de emergencia de invierno en el carro. ¿Qué artículo ayuda a que las llantas se agarren en la nieve y el hielo?","o":["Una botella de agua","Un cargador extra para el teléfono","Arena para gatos o arena común","Un mapa de carreteras"],"h1":"Se echa debajo de las llantas.","h2":"En Maryland, la MVA sugiere llevar arena para gatos o arena en el kit de emergencia para tener tracción en nieve y hielo.","p":"¡Correcto! La arena para gatos o la arena ayudan con la tracción."},"ref":{"doc":"MD","page":29}},{"id":"md-093","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, what does the MVA advise you to keep full when driving in snow and ice?","o":["Your gas tank and windshield washer fluid","Your trunk, for extra weight","Your tires, above the normal pressure","Your cup holders, with hot drinks"],"h1":"One keeps you warm if you get stuck; the other keeps your view clear.","h2":"In Maryland, the MVA advises keeping your gas tank and windshield washer fluid full in winter weather.","p":"Yes! Keep the gas tank and washer fluid full."},"es":{"q":"En Maryland, ¿qué le aconseja la MVA mantener lleno cuando maneja con nieve y hielo?","o":["El tanque de gasolina y el líquido limpiaparabrisas","La cajuela, para tener más peso","Las llantas, por encima de la presión normal","Los portavasos, con bebidas calientes"],"h1":"Uno lo mantiene caliente si se queda atascado; el otro mantiene clara la vista.","h2":"En Maryland, la MVA aconseja mantener llenos el tanque de gasolina y el líquido limpiaparabrisas en invierno.","p":"¡Sí! Mantenga llenos el tanque y el líquido limpiaparabrisas."},"ref":{"doc":"MD","page":29}},{"id":"md-094","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you see a safety problem at a railroad crossing. How should you report it?","o":["Leave a note on the crossbuck sign","Wait for the next train and wave at the engineer","Tell the MVA at your next license renewal","Use the phone number on the blue and white Emergency Notification System sign"],"h1":"A special sign at the crossing has the contact information.","h2":"In Maryland, you report emergencies and safety problems at railroad crossings using the information on the blue and white Emergency Notification System (ENS) sign.","p":"Correct! Use the blue and white ENS sign at the crossing."},"es":{"q":"En Maryland, ve un problema de seguridad en un cruce de tren. ¿Cómo debe reportarlo?","o":["Dejando una nota en la señal en forma de X","Esperando el próximo tren y haciéndole señas al maquinista","Avisándole a la MVA en su próxima renovación","Usando el número del letrero azul y blanco del Sistema de Notificación de Emergencias"],"h1":"Un letrero especial en el cruce tiene los datos de contacto.","h2":"En Maryland, las emergencias y problemas de seguridad en cruces de tren se reportan con los datos del letrero azul y blanco del Sistema de Notificación de Emergencias (ENS).","p":"¡Correcto! Use el letrero azul y blanco ENS del cruce."},"ref":{"doc":"MD","page":30}},{"id":"md-095","scope":"MD","cat":"signals","sign":null,"c":1,"en":{"q":"In Maryland, you see flashing amber (yellow) lights in a work zone. What do they mean?","o":["Speed cameras are active","The work zone is active and workers are present","A highway maintenance vehicle is ahead","The work zone has ended"],"h1":"Blue means cameras and green means maintenance vehicles.","h2":"In Maryland, flashing amber or yellow lights in a work zone mean the zone is active and workers are present.","p":"Right! Flashing amber means workers are present."},"es":{"q":"En Maryland, ve luces ámbar (amarillas) intermitentes en una zona de obras. ¿Qué significan?","o":["Hay cámaras de velocidad activas","La zona de obras está activa y hay trabajadores","Hay un vehículo de mantenimiento vial adelante","La zona de obras terminó"],"h1":"El azul es de cámaras y el verde es de vehículos de mantenimiento.","h2":"En Maryland, las luces ámbar o amarillas intermitentes en una zona de obras significan que la zona está activa y hay trabajadores.","p":"¡Correcto! El ámbar intermitente indica que hay trabajadores."},"ref":{"doc":"MD","page":31}},{"id":"md-096","scope":"MD","cat":"signals","sign":null,"c":1,"en":{"q":"In Maryland, what do flashing green lights on a vehicle near a work zone usually show?","o":["An active speed camera","A highway maintenance vehicle or service equipment","A police car stopping traffic","A school bus loading children"],"h1":"Blue lights mean cameras; these belong to road crews.","h2":"In Maryland, flashing green lights are found on highway maintenance vehicles and service equipment in and before work zones.","p":"Yes! Flashing green lights mark highway maintenance vehicles."},"es":{"q":"En Maryland, ¿qué indican por lo general las luces verdes intermitentes en un vehículo cerca de una zona de obras?","o":["Una cámara de velocidad activa","Un vehículo de mantenimiento vial o equipo de servicio","Una patrulla deteniendo el tránsito","Un autobús escolar subiendo niños"],"h1":"Las luces azules son de cámaras; estas son de cuadrillas de carretera.","h2":"En Maryland, las luces verdes intermitentes están en vehículos de mantenimiento vial y equipo de servicio dentro y antes de las zonas de obras.","p":"¡Sí! Las luces verdes intermitentes marcan vehículos de mantenimiento vial."},"ref":{"doc":"MD","page":31}},{"id":"md-097","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, you are in a traffic circle with more than one lane. When should you move to the outside lane to exit?","o":["As soon as you enter the circle","Only after you pass your exit","Any time, without a signal","After you pass the exit before the one you want"],"h1":"Signal right and move over one exit early.","h2":"In Maryland, in a multi-lane traffic circle you stay in your lane, then turn on your right signal and move to the outside lane after you pass the exit before the one you plan to take.","p":"Correct! Move out after passing the exit before yours."},"es":{"q":"En Maryland, está en una glorieta de más de un carril. ¿Cuándo debe pasar al carril exterior para salir?","o":["Apenas entra a la glorieta","Solo después de pasar su salida","En cualquier momento, sin señalar","Después de pasar la salida anterior a la que quiere"],"h1":"Señale a la derecha y cámbiese una salida antes.","h2":"En Maryland, en una glorieta de varios carriles se queda en su carril, y luego pone la direccional derecha y pasa al carril exterior después de la salida anterior a la que va a tomar.","p":"¡Correcto! Cámbiese después de pasar la salida anterior a la suya."},"ref":{"doc":"MD","page":31}},{"id":"md-098","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, you come to a traffic circle and no cars are in it. What should you do at the yield line?","o":["Enter without waiting, watching for people in the crosswalk","Come to a full stop and count to five","Wait for a car to enter first","Honk before entering"],"h1":"You only need to wait for a gap when there is traffic.","h2":"In Maryland, you do not need to wait to enter a traffic circle if there is no traffic in it, but you still yield to pedestrians in the crosswalk.","p":"Right! If the circle is empty, you may enter without waiting."},"es":{"q":"En Maryland, llega a una glorieta y no hay carros adentro. ¿Qué debe hacer en la línea de ceda el paso?","o":["Entrar sin esperar, atento a peatones en el cruce","Detenerse por completo y contar hasta cinco","Esperar a que entre otro carro primero","Tocar la bocina antes de entrar"],"h1":"Solo necesita esperar un espacio cuando hay tránsito.","h2":"En Maryland, no necesita esperar para entrar a una glorieta si no hay tránsito en ella, pero sí debe ceder el paso a los peatones en el cruce.","p":"¡Correcto! Si la glorieta está vacía, puede entrar sin esperar."},"ref":{"doc":"MD","page":31}},{"id":"md-099","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, you miss your exit on an interstate. What should you do?","o":["Stop on the shoulder and back up to the exit","Make a U-turn through the median","Keep going and use a later exit to come back","Stop in the lane and wait for a gap to back up"],"h1":"Backing up on a highway is never allowed.","h2":"In Maryland, if you exit at the wrong place or miss an exit, keep going and find a way to re-enter; never stop and back up on any part of the highway.","p":"Yes! Never back up; take the next exit."},"es":{"q":"En Maryland, se le pasa la salida en una interestatal. ¿Qué debe hacer?","o":["Detenerse en el acotamiento y retroceder hasta la salida","Dar vuelta en U por el camellón","Seguir y usar una salida más adelante para regresar","Parar en el carril y esperar un espacio para retroceder"],"h1":"Retroceder en una autopista nunca se permite.","h2":"En Maryland, si se le pasa la salida, siga y busque cómo volver; nunca se detenga ni retroceda en ninguna parte de la autopista.","p":"¡Sí! Nunca retroceda; tome la siguiente salida."},"ref":{"doc":"MD","page":32}},{"id":"md-100","scope":"MD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maryland, your light is green, but a funeral procession is crossing in front of you. What must you do?","o":["Go, because you have the green light","Honk so the procession stops for you","Yield until all vehicles in the procession have passed","Cut in between two cars of the procession"],"h1":"The procession has the right-of-way even against your green.","h2":"In Maryland, even with a green signal, other drivers must yield to a funeral procession until all of its vehicles have passed, unless they can go safely without crossing its path.","p":"Correct! Yield to the whole procession, even on green."},"es":{"q":"En Maryland, su luz está en verde, pero un cortejo fúnebre está cruzando frente a usted. ¿Qué debe hacer?","o":["Avanzar, porque tiene luz verde","Tocar la bocina para que el cortejo se detenga","Ceder el paso hasta que pasen todos los vehículos del cortejo","Meterse entre dos carros del cortejo"],"h1":"El cortejo tiene el derecho de paso aunque usted tenga verde.","h2":"En Maryland, aun con luz verde, los demás conductores deben ceder el paso a un cortejo fúnebre hasta que pasen todos sus vehículos, salvo que puedan avanzar con seguridad sin cruzar su camino.","p":"¡Correcto! Ceda el paso a todo el cortejo, aun en verde."},"ref":{"doc":"MD","page":32}},{"id":"md-101","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maryland, a vehicle has an orange and red triangle sign on the back. How fast is it usually going?","o":["25 mph or less","40 mph or less","Exactly 55 mph","10 mph or less, by law"],"h1":"It is a slow-moving vehicle sign, as on farm equipment.","h2":"In Maryland, the slow-moving vehicle sign warns that the vehicle travels 25 miles per hour or less.","p":"Right! That sign means 25 mph or less."},"es":{"q":"En Maryland, un vehículo lleva atrás un triángulo anaranjado y rojo. ¿A qué velocidad suele ir?","o":["A 25 mph o menos","A 40 mph o menos","Exactamente a 55 mph","A 10 mph o menos, por ley"],"h1":"Es la señal de vehículo lento, como en la maquinaria agrícola.","h2":"En Maryland, la señal de vehículo lento avisa que ese vehículo va a 25 millas por hora o menos.","p":"¡Correcto! Esa señal indica 25 mph o menos."},"ref":{"doc":"MD","page":32}},{"id":"md-102","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you must follow a slow farm tractor while you wait for a safe place to pass. What does the MVA suggest?","o":["Honk often so the tractor pulls over","Pass on the shoulder right away","Turn off your headlights","Turn on your emergency flashers to warn drivers behind you"],"h1":"Help the drivers coming up behind you notice the slow traffic.","h2":"In Maryland, if you must follow a slow-moving vehicle while waiting to pass, use your emergency flashers to warn others coming up behind you.","p":"Yes! Use your flashers to warn drivers behind you."},"es":{"q":"En Maryland, tiene que seguir a un tractor lento mientras espera un lugar seguro para rebasar. ¿Qué sugiere la MVA?","o":["Tocar la bocina seguido para que el tractor se orille","Rebasar por el acotamiento de inmediato","Apagar los faros","Encender las luces intermitentes de emergencia para avisar a quienes vienen atrás"],"h1":"Ayude a que los conductores que vienen atrás noten el tránsito lento.","h2":"En Maryland, si tiene que seguir a un vehículo lento mientras espera para rebasar, use las luces intermitentes de emergencia para avisar a quienes vienen atrás.","p":"¡Sí! Use las intermitentes para avisar a los de atrás."},"ref":{"doc":"MD","page":32}},{"id":"md-103","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, at what blood alcohol concentration (BAC) is an adult driver considered to be driving under the influence?","o":["0.02 or higher","0.08 or higher","0.05 or higher","0.10 or higher"],"h1":"It is the same per se limit used across most of the country.","h2":"In Maryland, a driver is considered to be driving under the influence of alcohol with a BAC of 0.08 or higher.","p":"Correct! In Maryland, 0.08 or higher is driving under the influence."},"es":{"q":"En Maryland, ¿con qué concentración de alcohol en la sangre (BAC) se considera que un conductor adulto maneja bajo la influencia?","o":["0.02 o más","0.08 o más","0.05 o más","0.10 o más"],"h1":"Es el mismo límite que se usa en casi todo el país.","h2":"En Maryland, se considera que una persona maneja bajo la influencia del alcohol con un BAC de 0.08 o más.","p":"¡Correcto! En Maryland, 0.08 o más es manejar bajo la influencia."},"ref":{"doc":"MD","page":33}},{"id":"md-104","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, which part of a car counts as the passenger area for the open container law?","o":["Only the glove box","The seats and any place people can easily reach from them","Only the driver's seat","The locked trunk"],"h1":"Think about where someone sitting in the car could reach.","h2":"In Maryland, the passenger area includes the driver and passenger seats and any place the driver or passengers can easily reach from where they sit.","p":"Right! It includes the seats and anywhere people can easily reach."},"es":{"q":"En Maryland, ¿qué parte del carro cuenta como área de pasajeros para la ley de envases abiertos?","o":["Solo la guantera","Los asientos y cualquier lugar que se alcance fácilmente desde ellos","Solo el asiento del conductor","La cajuela cerrada con llave"],"h1":"Piense hasta dónde puede alcanzar alguien sentado en el carro.","h2":"En Maryland, el área de pasajeros incluye los asientos del conductor y de los pasajeros y cualquier lugar que se alcance fácilmente desde donde están sentados.","p":"¡Correcto! Incluye los asientos y todo lo que se alcanza fácilmente."},"ref":{"doc":"MD","page":33}},{"id":"md-105","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you take a prescription medicine whose label says not to drive. You drive anyway, and it impairs you. What can happen?","o":["Nothing, because the medicine is legal","Only a warning, because a doctor prescribed it","Only a parking ticket","You could be charged with a criminal offense"],"h1":"A legal medicine can still lead to charges if it makes you unsafe.","h2":"In Maryland, if you drive after taking a medicine that warns you not to and it impairs your driving, you could be charged with a criminal offense.","p":"Yes! You could face criminal charges, even with a legal prescription."},"es":{"q":"En Maryland, toma un medicamento recetado cuya etiqueta dice que no maneje. Usted maneja igual y lo afecta. ¿Qué puede pasar?","o":["Nada, porque el medicamento es legal","Solo una advertencia, porque lo recetó un médico","Solo una multa de estacionamiento","Lo pueden acusar de un delito"],"h1":"Un medicamento legal igual puede llevar a cargos si lo vuelve inseguro.","h2":"En Maryland, si maneja después de tomar un medicamento que advierte no manejar y eso afecta su manejo, lo pueden acusar de un delito.","p":"¡Sí! Puede enfrentar cargos, aunque la receta sea legal."},"ref":{"doc":"MD","page":33}},{"id":"md-106","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, according to the MVA, what causes more police-reported crashes than anything else?","o":["Distracted driving","Driving in snow","Flat tires","Driving at night"],"h1":"It is about taking your eyes, hands or mind away from driving.","h2":"In Maryland, the MVA says distracted driving causes more crashes reported to the police than anything else.","p":"Correct! Distracted driving causes the most police-reported crashes."},"es":{"q":"En Maryland, según la MVA, ¿qué causa más choques reportados a la policía que cualquier otra cosa?","o":["Manejar distraído","Manejar en la nieve","Las llantas ponchadas","Manejar de noche"],"h1":"Se trata de quitar los ojos, las manos o la mente del manejo.","h2":"En Maryland, la MVA dice que manejar distraído causa más choques reportados a la policía que cualquier otra cosa.","p":"¡Correcto! Manejar distraído causa la mayoría de los choques reportados."},"ref":{"doc":"MD","page":34}},{"id":"md-107","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, about what share of fatal crashes does the MVA say are caused by distracted driving?","o":["One-tenth","Nine out of ten","One-third","One in a hundred"],"h1":"It is a little more than one in four.","h2":"In Maryland, the MVA says one-third of fatal crashes are caused by distracted driving.","p":"Right! About one-third of fatal crashes come from distraction."},"es":{"q":"En Maryland, ¿qué parte de los choques mortales dice la MVA que causa manejar distraído?","o":["Un décimo","Nueve de cada diez","Un tercio","Uno de cada cien"],"h1":"Es un poco más de uno de cada cuatro.","h2":"En Maryland, la MVA dice que un tercio de los choques mortales son causados por manejar distraído.","p":"¡Correcto! Cerca de un tercio de los choques mortales vienen de distracciones."},"ref":{"doc":"MD","page":36}},{"id":"md-108","scope":"MD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maryland, there is no traffic signal and a person is crossing at an intersection with no painted crosswalk. What must you do?","o":["Keep going, because there are no painted lines","Honk so the person hurries","Stop for the person, because an unmarked crosswalk still counts","Stop only if a police officer is there"],"h1":"Most intersections have a crosswalk even when it is not painted.","h2":"In Maryland, when there is no traffic signal, you must stop for pedestrians in a marked or unmarked crosswalk, and most intersections have a crosswalk even if it is not marked.","p":"Yes! Stop for pedestrians in unmarked crosswalks too."},"es":{"q":"En Maryland, no hay semáforo y una persona cruza en una intersección sin cruce peatonal pintado. ¿Qué debe hacer?","o":["Seguir, porque no hay líneas pintadas","Tocar la bocina para que se apure","Detenerse, porque un cruce sin marcar igual cuenta","Detenerse solo si hay un policía"],"h1":"La mayoría de las intersecciones tienen cruce peatonal aunque no esté pintado.","h2":"En Maryland, cuando no hay semáforo, debe detenerse por los peatones en un cruce marcado o sin marcar, y la mayoría de las intersecciones tienen cruce aunque no esté pintado.","p":"¡Sí! También se detiene en cruces sin marcar."},"ref":{"doc":"MD","page":37}},{"id":"md-109","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, an ambulance with its siren and lights on is ahead of you, going your way. When may you pass it?","o":["Only if it stops or a police officer tells you to","When it slows below the speed limit","When you have a clear passing lane","Never, even if it stops"],"h1":"Two exceptions are allowed.","h2":"In Maryland, you may not pass an emergency vehicle going your way with its signals on unless it stops or a police officer tells you to pass.","p":"Right! Pass only if it stops or an officer directs you."},"es":{"q":"En Maryland, una ambulancia con sirena y luces encendidas va delante de usted en su mismo sentido. ¿Cuándo puede rebasarla?","o":["Solo si se detiene o un policía le indica que lo haga","Cuando baje de la velocidad límite","Cuando tenga un carril libre para rebasar","Nunca, aunque se detenga"],"h1":"Hay dos excepciones.","h2":"En Maryland, no puede rebasar a un vehículo de emergencia que va en su mismo sentido con las señales encendidas, salvo que se detenga o un policía le indique rebasarlo.","p":"¡Correcto! Rebase solo si se detiene o un policía lo indica."},"ref":{"doc":"MD","page":37}},{"id":"md-110","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, the MVA warns that a fully loaded truck can weigh more than how much?","o":["8,000 pounds","20,000 pounds","200,000 pounds","80,000 pounds"],"h1":"Most cars weigh only about 2,000 pounds.","h2":"In Maryland, the MVA says fully loaded trucks can weigh more than 80,000 pounds and may need the length of a football field to stop.","p":"Yes! A loaded truck can weigh over 80,000 pounds."},"es":{"q":"En Maryland, la MVA advierte que un camión cargado por completo puede pesar más de cuánto?","o":["8,000 libras","20,000 libras","200,000 libras","80,000 libras"],"h1":"La mayoría de los carros pesan solo unas 2,000 libras.","h2":"En Maryland, la MVA dice que los camiones cargados pueden pesar más de 80,000 libras y necesitar el largo de un campo de fútbol americano para detenerse.","p":"¡Sí! Un camión cargado puede pesar más de 80,000 libras."},"ref":{"doc":"MD","page":38}},{"id":"md-111","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, how far out to the side does a large truck's right-side blind spot reach?","o":["Only half a lane","About three lanes","Only the lane next to the cab","No blind spot on the right side"],"h1":"It is the biggest no-zone around the truck.","h2":"In Maryland, the MVA says a truck's right-side blind spot runs the length of the trailer and extends out three lanes.","p":"Correct! The right-side blind spot extends out three lanes."},"es":{"q":"En Maryland, ¿hasta dónde llega hacia el lado el punto ciego derecho de un camión grande?","o":["Solo medio carril","Unos tres carriles","Solo el carril junto a la cabina","No hay punto ciego del lado derecho"],"h1":"Es la zona ciega más grande alrededor del camión.","h2":"En Maryland, la MVA dice que el punto ciego derecho de un camión va a lo largo del remolque y se extiende tres carriles.","p":"¡Correcto! El punto ciego derecho abarca tres carriles."},"ref":{"doc":"MD","page":38}},{"id":"md-112","scope":"MD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maryland, you come up behind a stopped school bus with flashing red lights. How far back must you stop?","o":["At least 5 feet from the bus","At least 20 feet from the bus","At least 50 feet from the bus","At least 100 feet from the bus"],"h1":"It is about the length of one and a half cars.","h2":"In Maryland, you must stop at least 20 feet from the back of a school bus that has stopped with its red lights flashing, or 20 feet from the front if you are facing it.","p":"Right! Stop at least 20 feet away from the bus."},"es":{"q":"En Maryland, llega por detrás a un autobús escolar detenido con luces rojas intermitentes. ¿A qué distancia debe detenerse?","o":["Al menos a 5 pies del autobús","Al menos a 20 pies del autobús","Al menos a 50 pies del autobús","Al menos a 100 pies del autobús"],"h1":"Es más o menos el largo de un carro y medio.","h2":"En Maryland, debe detenerse al menos a 20 pies de la parte de atrás de un autobús escolar detenido con luces rojas intermitentes, o a 20 pies del frente si viene de frente.","p":"¡Correcto! Deténgase al menos a 20 pies del autobús."},"ref":{"doc":"MD","page":38}},{"id":"md-113","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, you are stopped for a school bus with flashing red lights. When may you start moving again?","o":["When the last child reaches the sidewalk","After waiting 30 seconds","When the bus driver waves at you","When the bus starts moving or turns off its red lights"],"h1":"Watch the bus itself, not the children or a clock.","h2":"In Maryland, you may not move again until the school bus starts moving or turns off its flashing red lights.","p":"Yes! Wait until the bus moves or its red lights go off."},"es":{"q":"En Maryland, está detenido por un autobús escolar con luces rojas intermitentes. ¿Cuándo puede volver a avanzar?","o":["Cuando el último niño llegue a la acera","Después de esperar 30 segundos","Cuando el chofer del autobús le haga una seña","Cuando el autobús arranque o apague las luces rojas"],"h1":"Fíjese en el autobús, no en los niños ni en un reloj.","h2":"En Maryland, no puede volver a avanzar hasta que el autobús escolar arranque o apague sus luces rojas intermitentes.","p":"¡Sí! Espere a que el autobús arranque o apague las luces rojas."},"ref":{"doc":"MD","page":39}},{"id":"md-114","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, the MVA says a motorcyclist is how much more likely than a car driver to be hurt in a crash?","o":["Six times","Twice","Ten times","About the same"],"h1":"It is several times more likely.","h2":"In Maryland, the MVA says a motorcyclist is six times more likely than a car driver to be hurt in a crash.","p":"Correct! A motorcyclist is six times more likely to be hurt."},"es":{"q":"En Maryland, la MVA dice que un motociclista tiene cuántas veces más probabilidad que un conductor de carro de lesionarse en un choque?","o":["Seis veces","El doble","Diez veces","Más o menos la misma"],"h1":"Es varias veces más probable.","h2":"En Maryland, la MVA dice que un motociclista tiene seis veces más probabilidad que un conductor de carro de lesionarse en un choque.","p":"¡Correcto! Un motociclista tiene seis veces más riesgo de lesionarse."},"ref":{"doc":"MD","page":39}},{"id":"md-115","scope":"MD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maryland, a motorcycle is riding in your lane on a two-lane highway. May you share the lane with it?","o":["Yes, if you stay to the right side","Yes, if the motorcycle is slow","No, a motorcycle is allowed the whole lane","Yes, on any road with wide lanes"],"h1":"Motorcyclists move within the lane to avoid hazards and be seen.","h2":"In Maryland, you must not share a lane with a motorcycle, because motorcyclists are allowed to use the whole lane.","p":"Right! Do not share a lane with a motorcycle."},"es":{"q":"En Maryland, una motocicleta va en su carril en una carretera de dos carriles. ¿Puede compartir el carril con ella?","o":["Sí, si usted se mantiene a la derecha","Sí, si la motocicleta va lenta","No, la motocicleta tiene derecho a todo el carril","Sí, en cualquier vía con carriles anchos"],"h1":"Los motociclistas se mueven en el carril para evitar peligros y ser vistos.","h2":"En Maryland, no debe compartir un carril con una motocicleta, porque el motociclista tiene derecho a usar todo el carril.","p":"¡Correcto! No comparta el carril con una motocicleta."},"ref":{"doc":"MD","page":39}},{"id":"md-116","scope":"MD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maryland, a motorcyclist is passing you. What should you do?","o":["Speed up so the rider cannot cut in","Move into the rider's path to block","Keep your speed and let the rider finish passing","Brake hard right away"],"h1":"Make the pass easy and predictable.","h2":"In Maryland, if a motorcyclist is passing you, simply keep your speed and let the rider complete the pass.","p":"Yes! Keep your speed and let the rider pass."},"es":{"q":"En Maryland, un motociclista lo está rebasando. ¿Qué debe hacer?","o":["Acelerar para que no se le meta adelante","Moverse hacia su camino para bloquearlo","Mantener su velocidad y dejar que termine de rebasar","Frenar fuerte de inmediato"],"h1":"Haga que el rebase sea fácil y predecible.","h2":"En Maryland, si un motociclista lo rebasa, mantenga su velocidad y deje que termine de rebasar.","p":"¡Sí! Mantenga la velocidad y deje que rebase."},"ref":{"doc":"MD","page":39}},{"id":"md-117","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, on which roads should you NOT expect to find bicyclists?","o":["Interstate highways and toll bridges and tunnels","Two-lane country roads","City streets with bike lanes","Roads near schools"],"h1":"Bicyclists may ride on almost every other kind of road.","h2":"In Maryland, you should expect bicyclists on all types of roads except interstate highways and bridges and tunnels with tolls.","p":"Correct! Bicycles are not expected on interstates or toll bridges and tunnels."},"es":{"q":"En Maryland, ¿en qué vías NO debe esperar encontrar ciclistas?","o":["En autopistas interestatales y en puentes y túneles de peaje","En carreteras rurales de dos carriles","En calles de la ciudad con ciclovías","En calles cerca de escuelas"],"h1":"Los ciclistas pueden andar en casi todo otro tipo de vía.","h2":"En Maryland, debe esperar ciclistas en todo tipo de vía menos en autopistas interestatales y en puentes y túneles de peaje.","p":"¡Correcto! No se esperan bicicletas en interestatales ni en puentes y túneles de peaje."},"ref":{"doc":"MD","page":40}},{"id":"md-118","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, a bicyclist is riding in the middle of a narrow lane, well below the speed of traffic. Is this allowed?","o":["No, bicycles must always use the shoulder","No, bicycles may never slow down traffic","Only on Sundays and holidays","Yes, if the lane is too narrow for a car to pass safely"],"h1":"The rule is about whether a car could pass safely within the lane.","h2":"In Maryland, a bicyclist may use the full lane, even while going much slower than traffic, when the lane is too narrow for a motor vehicle to pass the bicycle safely.","p":"Right! A bicyclist may take the full lane when it is too narrow to share."},"es":{"q":"En Maryland, un ciclista va en medio de un carril angosto, mucho más lento que el tránsito. ¿Está permitido?","o":["No, las bicicletas siempre deben ir por el acotamiento","No, las bicicletas nunca pueden frenar el tránsito","Solo los domingos y días feriados","Sí, si el carril es muy angosto para que un carro lo rebase con seguridad"],"h1":"La regla depende de si un carro podría rebasarlo con seguridad dentro del carril.","h2":"En Maryland, un ciclista puede usar todo el carril, aunque vaya mucho más lento que el tránsito, si el carril es muy angosto para que un vehículo lo rebase con seguridad.","p":"¡Correcto! El ciclista puede usar todo el carril si es muy angosto para compartir."},"ref":{"doc":"MD","page":40}},{"id":"md-119","scope":"MD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maryland, you are turning right and a bicyclist is going straight beside you. Who has the right-of-way?","o":["You, because you signaled first","The bicyclist","Whoever is going faster","You, because cars are larger"],"h1":"When a car turns, the bicycle going straight goes first.","h2":"In Maryland, bicyclists have the right-of-way when a motor vehicle is making a turn, so you must yield to them.","p":"Yes! Yield to the bicyclist when you turn."},"es":{"q":"En Maryland, usted gira a la derecha y un ciclista sigue derecho a su lado. ¿Quién tiene el derecho de paso?","o":["Usted, porque señaló primero","El ciclista","El que vaya más rápido","Usted, porque los carros son más grandes"],"h1":"Cuando un carro gira, la bicicleta que sigue derecho pasa primero.","h2":"En Maryland, los ciclistas tienen el derecho de paso cuando un vehículo está girando, así que usted debe cederles el paso.","p":"¡Sí! Ceda el paso al ciclista cuando gira."},"ref":{"doc":"MD","page":40}},{"id":"md-120","scope":"MD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maryland, you must cross a bike lane to turn into a driveway. A bicyclist is riding in it. What must you do?","o":["Cross first because you are turning","Yield to the bicyclist before you cross","Honk so the bicyclist stops","Speed up to get across sooner"],"h1":"The bike lane belongs to the bicyclist first.","h2":"In Maryland, when you enter or cross a bike lane or shoulder, you must yield the right-of-way to bicyclists riding in it.","p":"Correct! Yield to bicyclists before crossing a bike lane."},"es":{"q":"En Maryland, tiene que cruzar una ciclovía para entrar a una entrada de garaje. Hay un ciclista en ella. ¿Qué debe hacer?","o":["Cruzar primero porque usted está girando","Cederle el paso al ciclista antes de cruzar","Tocar la bocina para que el ciclista se detenga","Acelerar para cruzar más rápido"],"h1":"La ciclovía es primero del ciclista.","h2":"En Maryland, al entrar o cruzar una ciclovía o acotamiento, debe ceder el paso a los ciclistas que van en ellos.","p":"¡Correcto! Ceda el paso a los ciclistas antes de cruzar una ciclovía."},"ref":{"doc":"MD","page":40}},{"id":"md-121","scope":"MD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maryland, a bicyclist is crossing the street in a crosswalk. How should you treat them?","o":["As a car that must wait for you","As someone breaking the law","As traffic that must yield to turning cars","With the same right-of-way as a pedestrian"],"h1":"In a crosswalk, a bicycle is treated like a person walking.","h2":"In Maryland, bicycles have the same right-of-way as pedestrians in a crosswalk.","p":"Right! In a crosswalk, a bicyclist has a pedestrian's right-of-way."},"es":{"q":"En Maryland, un ciclista cruza la calle por un cruce peatonal. ¿Cómo debe tratarlo?","o":["Como un carro que debe esperarlo a usted","Como alguien que viola la ley","Como tránsito que debe ceder a los carros que giran","Con el mismo derecho de paso que un peatón"],"h1":"En el cruce peatonal, una bicicleta se trata como una persona a pie.","h2":"En Maryland, las bicicletas tienen el mismo derecho de paso que los peatones en un cruce peatonal.","p":"¡Correcto! En el cruce, el ciclista tiene el derecho de paso de un peatón."},"ref":{"doc":"MD","page":40}},{"id":"md-122","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, may people ride bicycles on sidewalks?","o":["Yes, statewide, unless a local law bans it","No, never anywhere in the state","Only riders over 18","Only in Baltimore City"],"h1":"The state allows it, but cities and counties can make their own rule.","h2":"In Maryland, bicycles are allowed on sidewalks throughout the state, but local governments can prohibit it, and riders must yield to pedestrians.","p":"Yes! Sidewalk riding is allowed unless a local law says no."},"es":{"q":"En Maryland, ¿se puede andar en bicicleta por las aceras?","o":["Sí, en todo el estado, salvo que una ley local lo prohíba","No, nunca en ninguna parte del estado","Solo los mayores de 18","Solo en la ciudad de Baltimore"],"h1":"El estado lo permite, pero las ciudades y condados pueden tener su propia regla.","h2":"En Maryland, se permiten las bicicletas en las aceras en todo el estado, pero los gobiernos locales pueden prohibirlo, y los ciclistas deben ceder el paso a los peatones.","p":"¡Sí! Se permite en las aceras salvo que una ley local lo prohíba."},"ref":{"doc":"MD","page":40}},{"id":"md-123","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, you come up behind a bicyclist. What does the MVA say about using your horn?","o":["Honk twice so the rider moves right","Honk once when you are right beside the rider","Do not honk; slow down instead","Honk only at night"],"h1":"Bicyclists can usually hear you, and a loud noise can startle them.","h2":"In Maryland, as you approach a bicyclist you should slow down and not honk your horn, because a loud noise can startle the rider and cause a crash.","p":"Correct! Slow down and do not honk."},"es":{"q":"En Maryland, se acerca por detrás a un ciclista. ¿Qué dice la MVA sobre usar la bocina?","o":["Tocar dos veces para que se mueva a la derecha","Tocar una vez cuando esté justo a su lado","No tocar la bocina; en cambio, bajar la velocidad","Tocar solo de noche"],"h1":"Los ciclistas suelen oírlo, y un ruido fuerte puede asustarlos.","h2":"En Maryland, al acercarse a un ciclista debe bajar la velocidad y no tocar la bocina, porque un ruido fuerte puede asustarlo y causar un choque.","p":"¡Correcto! Baje la velocidad y no toque la bocina."},"ref":{"doc":"MD","page":40}},{"id":"md-124","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, how fast does the MVA say experienced bicyclists may ride?","o":["No faster than 10 mph","No faster than 15 mph","As fast as 35 mph","As fast as 60 mph"],"h1":"It is faster than many people expect, close to a city speed limit.","h2":"In Maryland, the MVA warns that experienced bicyclists often ride very fast, as fast as 35 mph, and may be closer than you think.","p":"Right! Experienced riders can reach 35 mph."},"es":{"q":"En Maryland, ¿a qué velocidad dice la MVA que pueden ir los ciclistas con experiencia?","o":["No más de 10 mph","No más de 15 mph","Hasta 35 mph","Hasta 60 mph"],"h1":"Es más rápido de lo que muchos piensan, cerca de un límite de ciudad.","h2":"En Maryland, la MVA advierte que los ciclistas con experiencia a menudo van muy rápido, hasta 35 mph, y pueden estar más cerca de lo que usted cree.","p":"¡Correcto! Los ciclistas con experiencia pueden llegar a 35 mph."},"ref":{"doc":"MD","page":41}},{"id":"md-125","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, you just passed a bicyclist riding in the bike lane. You want to turn right. What should you avoid?","o":["Turning right from the through lane right after passing the bicycle","Checking your right mirror","Using your turn signal","Slowing down before the turn"],"h1":"The rider you passed may now be right beside your right door.","h2":"In Maryland, you should never make a right turn from a through lane right after passing a bicycle on a shoulder or in a bike lane.","p":"Yes! Do not turn right just after passing a bicycle."},"es":{"q":"En Maryland, acaba de rebasar a un ciclista que va por la ciclovía. Quiere girar a la derecha. ¿Qué debe evitar?","o":["Girar a la derecha desde el carril de paso justo después de rebasar la bicicleta","Revisar el espejo derecho","Usar la direccional","Bajar la velocidad antes de girar"],"h1":"El ciclista que rebasó puede estar justo junto a su puerta derecha.","h2":"En Maryland, nunca debe girar a la derecha desde un carril de paso justo después de rebasar a una bicicleta en el acotamiento o en una ciclovía.","p":"¡Sí! No gire a la derecha justo después de rebasar una bicicleta."},"ref":{"doc":"MD","page":41}},{"id":"md-126","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you are using high beams at night and see a bicyclist ahead. What should you do?","o":["Keep high beams so the rider sees you","Flash your high beams several times","Turn off all your lights","Switch to low beams as you approach"],"h1":"Bright lights can blind the rider.","h2":"In Maryland, when approaching a bicycle at night, you should use your low beam headlights.","p":"Correct! Use low beams when approaching a bicyclist."},"es":{"q":"En Maryland, maneja de noche con luces altas y ve a un ciclista adelante. ¿Qué debe hacer?","o":["Seguir con las altas para que lo vea","Hacerle cambio de luces varias veces","Apagar todas las luces","Cambiar a luces bajas al acercarse"],"h1":"Las luces fuertes pueden encandilar al ciclista.","h2":"En Maryland, al acercarse a una bicicleta de noche, debe usar las luces bajas.","p":"¡Correcto! Use luces bajas al acercarse a un ciclista."},"ref":{"doc":"MD","page":41}},{"id":"md-127","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maryland, where may mopeds and motor scooters ride on an allowed road?","o":["Only on sidewalks","On the road or the shoulder, alone or side by side","Only in the left lane","Only in bike lanes"],"h1":"They should still stay as far right as they safely can.","h2":"In Maryland, mopeds and scooters may ride on the road or on the shoulder, alone or side by side, staying as close to the right as they safely can.","p":"Right! Mopeds may use the road or shoulder, alone or side by side."},"es":{"q":"En Maryland, ¿por dónde pueden ir los ciclomotores y motonetas en una vía permitida?","o":["Solo por las aceras","Por la vía o el acotamiento, solos o lado a lado","Solo por el carril izquierdo","Solo por las ciclovías"],"h1":"Igual deben ir lo más a la derecha que puedan con seguridad.","h2":"En Maryland, los ciclomotores y motonetas pueden ir por la vía o el acotamiento, solos o lado a lado, lo más a la derecha que puedan con seguridad.","p":"¡Correcto! Pueden usar la vía o el acotamiento, solos o lado a lado."},"ref":{"doc":"MD","page":41}},{"id":"md-128","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, the MVA says driver assistance features (ADAS) prevent what share of crashes when used properly?","o":["4%","40%","90%","100%"],"h1":"It is a large share, but far from all crashes.","h2":"In Maryland, the MVA says Advanced Driver Assistance Systems prevent 40% of crashes when used properly, but you are still responsible for driving safely.","p":"Yes! ADAS prevents about 40% of crashes, but you stay in charge."},"es":{"q":"En Maryland, la MVA dice que los sistemas de asistencia al conductor (ADAS) previenen qué parte de los choques cuando se usan bien?","o":["El 4%","El 40%","El 90%","El 100%"],"h1":"Es una parte grande, pero lejos de todos los choques.","h2":"En Maryland, la MVA dice que los Sistemas Avanzados de Asistencia al Conductor previenen el 40% de los choques si se usan bien, pero usted sigue siendo responsable de manejar con seguridad.","p":"¡Sí! ADAS previene cerca del 40% de los choques, pero usted sigue a cargo."},"ref":{"doc":"MD","page":42}},{"id":"md-129","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you are in a crash and someone is hurt. Besides calling 911 and staying at the scene, what should you do with the vehicles?","o":["Push them to the shoulder right away","Drive them to the nearest parking lot","Move them only if they are blocking a driveway","Do not move them"],"h1":"With injuries, the scene stays as it is until help arrives.","h2":"In Maryland, after a crash where someone is injured, you must stay at the scene, call 911, and not move the vehicles.","p":"Correct! With injuries, do not move the vehicles."},"es":{"q":"En Maryland, tiene un choque y hay una persona herida. Además de llamar al 911 y quedarse en el lugar, ¿qué debe hacer con los vehículos?","o":["Empujarlos al acotamiento de inmediato","Llevarlos al estacionamiento más cercano","Moverlos solo si tapan una entrada de garaje","No moverlos"],"h1":"Con heridos, el lugar se deja como está hasta que llegue ayuda.","h2":"En Maryland, después de un choque con heridos, debe quedarse en el lugar, llamar al 911 y no mover los vehículos.","p":"¡Correcto! Con heridos, no mueva los vehículos."},"ref":{"doc":"MD","page":43}},{"id":"md-130","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, what is leaving the scene of a crash where someone dies?","o":["A felony, with up to 10 years in prison and a $10,000 fine","A minor traffic ticket","A misdemeanor with a $100 fine","A civil matter with no criminal penalty"],"h1":"It is the most serious kind of crime.","h2":"In Maryland, leaving the scene of a crash where someone dies is a felony punishable by up to 10 years in prison and a fine of up to $10,000.","p":"Right! It is a felony: up to 10 years and $10,000."},"es":{"q":"En Maryland, ¿qué es huir del lugar de un choque donde alguien muere?","o":["Un delito grave, con hasta 10 años de cárcel y una multa de $10,000","Una infracción de tránsito menor","Un delito menor con multa de $100","Un asunto civil sin pena criminal"],"h1":"Es la clase de delito más seria.","h2":"En Maryland, huir del lugar de un choque donde alguien muere es un delito grave con hasta 10 años de cárcel y una multa de hasta $10,000.","p":"¡Correcto! Es un delito grave: hasta 10 años y $10,000."},"ref":{"doc":"MD","page":43}},{"id":"md-131","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, you have a crash with no injuries, but your car cannot move. What should you do?","o":["Leave the car and walk home","Try to stop traffic so you can push the car","Call 911, give the location, and stay away from traffic","Cross the road to talk with the other driver"],"h1":"Say no one is hurt, but you need police help.","h2":"In Maryland, if no one is injured but a vehicle cannot be moved, call 911, give the location, say there are no injuries but you need police help, and stay away from traffic.","p":"Yes! Call 911 and stay away from traffic."},"es":{"q":"En Maryland, tiene un choque sin heridos, pero su carro no puede moverse. ¿Qué debe hacer?","o":["Dejar el carro y caminar a su casa","Intentar parar el tránsito para empujar el carro","Llamar al 911, dar la ubicación y alejarse del tránsito","Cruzar la vía para hablar con el otro conductor"],"h1":"Diga que nadie está herido, pero que necesita ayuda de la policía.","h2":"En Maryland, si nadie está herido pero un vehículo no puede moverse, llame al 911, dé la ubicación, diga que no hay heridos pero necesita a la policía, y aléjese del tránsito.","p":"¡Sí! Llame al 911 y aléjese del tránsito."},"ref":{"doc":"MD","page":43}},{"id":"md-132","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, you have a small crash with no injuries, and both cars can still be driven. What should you do first?","o":["Leave the cars where they stopped until police arrive","Drive home and call the other driver later","Move the cars off the road, close to where the crash happened","Stay in your car in the travel lane"],"h1":"Clearing the road keeps everyone safe and prevents backups.","h2":"In Maryland, if there are no injuries and your vehicle can move, move it off the road as close as possible to where the crash happened, then exchange information.","p":"Correct! Move the cars off the road near the crash site."},"es":{"q":"En Maryland, tiene un choque leve sin heridos, y los dos carros todavía se pueden manejar. ¿Qué debe hacer primero?","o":["Dejar los carros donde quedaron hasta que llegue la policía","Irse a casa y llamar al otro conductor después","Sacar los carros de la vía, cerca de donde fue el choque","Quedarse en su carro en el carril"],"h1":"Despejar la vía protege a todos y evita embotellamientos.","h2":"En Maryland, si no hay heridos y su vehículo puede moverse, sáquelo de la vía lo más cerca posible del lugar del choque y luego intercambie datos.","p":"¡Correcto! Saque los carros de la vía cerca del lugar."},"ref":{"doc":"MD","page":43}},{"id":"md-133","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, after a crash with no injuries, the other driver has no license. What should you do?","o":["Call the police","Just exchange phone numbers","Let the driver go if they pay cash","Take the other driver's keys"],"h1":"This is one of the times you must always call the police.","h2":"In Maryland, you must always call the police after a crash when a driver does not have a license, along with other cases such as injuries or a driver who seems impaired.","p":"Right! Call the police when a driver has no license."},"es":{"q":"En Maryland, después de un choque sin heridos, el otro conductor no tiene licencia. ¿Qué debe hacer?","o":["Llamar a la policía","Solo intercambiar números de teléfono","Dejarlo ir si le paga en efectivo","Quitarle las llaves al otro conductor"],"h1":"Es una de las veces en que siempre debe llamar a la policía.","h2":"En Maryland, siempre debe llamar a la policía después de un choque cuando un conductor no tiene licencia, junto con otros casos como heridos o un conductor que parece intoxicado.","p":"¡Correcto! Llame a la policía si un conductor no tiene licencia."},"ref":{"doc":"MD","page":44}},{"id":"md-134","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, you back into a parked car and cannot find its owner. What must you do?","o":["Drive away if the damage looks small","Wait in your car for 24 hours","Call the MVA and ask them to find the owner","Leave a note with your contact information where the owner will find it"],"h1":"Try to find the owner first; if you cannot, they still need a way to reach you.","h2":"In Maryland, if you hit an unattended vehicle, stop and try to find the owner; if you cannot, leave a note with your contact information where it is easy to find.","p":"Yes! Leave a note with your contact information."},"es":{"q":"En Maryland, choca en reversa contra un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse si el daño parece pequeño","Esperar en su carro 24 horas","Llamar a la MVA para que busque al dueño","Dejar una nota con sus datos de contacto donde el dueño la vea"],"h1":"Primero intente encontrar al dueño; si no puede, igual necesita una forma de contactarlo.","h2":"En Maryland, si choca contra un vehículo sin nadie, deténgase y busque al dueño; si no lo encuentra, deje una nota con sus datos de contacto en un lugar fácil de ver.","p":"¡Sí! Deje una nota con sus datos de contacto."},"ref":{"doc":"MD","page":44}},{"id":"md-135","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, your car breaks down near a highway exit. Where should you never stop?","o":["On the far right shoulder","In the painted triangle-shaped zone where the ramp leaves the road","In a parking lot off the exit","At the end of the exit ramp, off the road"],"h1":"That painted area looks empty, but traffic moves on both sides of it.","h2":"In Maryland, you should never stop or park in the triangle-shaped painted zones where a ramp exits the road.","p":"Correct! Never stop in the painted triangle at an exit."},"es":{"q":"En Maryland, su carro se descompone cerca de una salida de autopista. ¿Dónde nunca debe detenerse?","o":["En el acotamiento del extremo derecho","En la zona pintada en forma de triángulo donde la rampa sale de la vía","En un estacionamiento fuera de la salida","Al final de la rampa de salida, fuera de la vía"],"h1":"Esa zona pintada parece vacía, pero hay tránsito a ambos lados.","h2":"En Maryland, nunca debe detenerse ni estacionarse en las zonas pintadas en forma de triángulo donde una rampa sale de la vía.","p":"¡Correcto! Nunca se detenga en el triángulo pintado de una salida."},"ref":{"doc":"MD","page":44}},{"id":"md-136","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, your car is stalled on the shoulder and it is safe to stay inside. What does the MVA advise?","o":["Unbuckle and lie down across the seats","Stay buckled and face forward","Stand behind the car to wave at traffic","Sit on the hood so others see you"],"h1":"The car's safety features protect you only if you use them.","h2":"In Maryland, if you can stay in your disabled vehicle, stay buckled and face forward so the car's safety features can protect you if it is hit.","p":"Right! Stay buckled and face forward."},"es":{"q":"En Maryland, su carro está varado en el acotamiento y es seguro quedarse adentro. ¿Qué aconseja la MVA?","o":["Quitarse el cinturón y acostarse en los asientos","Mantener el cinturón puesto y mirar hacia adelante","Pararse detrás del carro y hacer señas al tránsito","Sentarse sobre el cofre para que lo vean"],"h1":"Las protecciones del carro solo sirven si usted las usa.","h2":"En Maryland, si puede quedarse en su vehículo descompuesto, mantenga el cinturón puesto y mire hacia adelante para que las protecciones del carro lo cuiden si lo chocan.","p":"¡Correcto! Cinturón puesto y mirada al frente."},"ref":{"doc":"MD","page":44}},{"id":"md-137","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, it is not safe to stay in your broken-down car on the highway. Where should you wait?","o":["Right beside your car, so help can find you","In front of your car, to guard it","In the travel lane, waving a light","Away from the road, behind a guardrail or barrier, facing traffic"],"h1":"Get away from the car and keep watching the traffic.","h2":"In Maryland, if you must leave your disabled vehicle, move quickly away from the road, get behind an embankment, barrier or guardrail, and face oncoming traffic.","p":"Yes! Wait behind a barrier, away from the road, facing traffic."},"es":{"q":"En Maryland, no es seguro quedarse en su carro descompuesto en la autopista. ¿Dónde debe esperar?","o":["Justo al lado de su carro, para que lo encuentren","Delante de su carro, para cuidarlo","En el carril, haciendo señas con una luz","Lejos de la vía, detrás de una barrera o defensa, mirando hacia el tránsito"],"h1":"Aléjese del carro y siga mirando el tránsito.","h2":"En Maryland, si tiene que salir de su vehículo descompuesto, aléjese rápido de la vía, póngase detrás de un talud, barrera o defensa, y mire hacia el tránsito que viene.","p":"¡Sí! Espere detrás de una barrera, lejos de la vía, mirando el tránsito."},"ref":{"doc":"MD","page":44}},{"id":"md-138","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, a police officer pulls you over. What should you do with your hands?","o":["Keep them in plain view, best on the steering wheel","Reach under the seat for your papers right away","Keep them in your lap, out of sight","Hold your phone up to record"],"h1":"Avoid any movement that looks like you are hiding something.","h2":"In Maryland, during a traffic stop you should keep your hands in plain view, best on the steering wheel, and avoid movements that look like reaching for something.","p":"Correct! Keep your hands in view, on the wheel."},"es":{"q":"En Maryland, un policía lo detiene. ¿Qué debe hacer con las manos?","o":["Mantenerlas a la vista, mejor sobre el volante","Buscar enseguida sus papeles debajo del asiento","Tenerlas sobre las piernas, fuera de la vista","Levantar el teléfono para grabar"],"h1":"Evite cualquier movimiento que parezca que esconde algo.","h2":"En Maryland, en una parada de tránsito debe mantener las manos a la vista, mejor sobre el volante, y evitar movimientos que parezcan buscar algo.","p":"¡Correcto! Manos a la vista, sobre el volante."},"ref":{"doc":"MD","page":45}},{"id":"md-139","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, an officer stops you and you disagree with the ticket. What should you do?","o":["Argue until the officer changes the ticket","Refuse to sign anything and drive off","Do not argue; you can make your case in court","Get out of the car to discuss it"],"h1":"There is a proper place to explain your side.","h2":"In Maryland, if an officer gives you a citation, do not argue about it; you will have your chance to make your case if you go to court.","p":"Right! Do not argue; take it to court."},"es":{"q":"En Maryland, un policía lo detiene y usted no está de acuerdo con la multa. ¿Qué debe hacer?","o":["Discutir hasta que el policía cambie la multa","Negarse a firmar e irse","No discutir; puede defenderse en el tribunal","Bajarse del carro para hablarlo"],"h1":"Hay un lugar adecuado para explicar su versión.","h2":"En Maryland, si un policía le da una citación, no discuta; tendrá la oportunidad de defenderse si va al tribunal.","p":"¡Correcto! No discuta; defiéndase en el tribunal."},"ref":{"doc":"MD","page":45}},{"id":"md-140","scope":"MD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maryland, a driver breaks the Move Over law and causes a crash, but no one is badly hurt. What is the penalty?","o":["A $110 fine and 1 point","A $750 fine and 3 points","A $150 fine and 3 points","A warning letter only"],"h1":"It is more than the basic penalty but less than when someone is badly hurt.","h2":"In Maryland, breaking the Move Over law and causing a crash brings a $150 fine and 3 points.","p":"Yes! Causing a crash brings a $150 fine and 3 points."},"es":{"q":"En Maryland, un conductor viola la ley Move Over y causa un choque, pero nadie resulta gravemente herido. ¿Cuál es la sanción?","o":["Una multa de $110 y 1 punto","Una multa de $750 y 3 puntos","Una multa de $150 y 3 puntos","Solo una carta de advertencia"],"h1":"Es más que la sanción básica, pero menos que cuando alguien sale gravemente herido.","h2":"En Maryland, violar la ley Move Over y causar un choque trae una multa de $150 y 3 puntos.","p":"¡Sí! Causar un choque trae $150 de multa y 3 puntos."},"ref":{"doc":"MD","page":45}},{"id":"md-141","scope":"MD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maryland, a Move Over violation leads to a death or serious injury. What is the penalty?","o":["A $750 fine and 3 points","A $110 fine and 1 point","A $150 fine and 1 point","A $50 fine and no points"],"h1":"It is the highest of the three Move Over penalties.","h2":"In Maryland, a Move Over violation that results in death or serious injury brings a $750 fine and 3 points.","p":"Correct! It brings a $750 fine and 3 points."},"es":{"q":"En Maryland, una violación de la ley Move Over termina en una muerte o una lesión grave. ¿Cuál es la sanción?","o":["Una multa de $750 y 3 puntos","Una multa de $110 y 1 punto","Una multa de $150 y 1 punto","Una multa de $50 y ningún punto"],"h1":"Es la más alta de las tres sanciones de Move Over.","h2":"En Maryland, una violación de la ley Move Over que causa una muerte o lesión grave trae una multa de $750 y 3 puntos.","p":"¡Correcto! Trae $750 de multa y 3 puntos."},"ref":{"doc":"MD","page":45}},{"id":"md-142","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a 17-year-old with a provisional license drives friends who are not buckled up. Which restriction is broken?","o":["None, only the driver needs a belt","The night restriction","The phone restriction","The seat belt restriction: everyone in the car must be belted"],"h1":"For provisional drivers under 18, the rule covers every person in the car.","h2":"In Maryland, a provisional driver under 18 must always wear a seat belt, and every passenger must use a seat belt or child safety seat.","p":"Right! Everyone in a provisional driver's car must be buckled."},"es":{"q":"En Maryland, un joven de 17 años con licencia provisional lleva amigos sin cinturón. ¿Qué restricción viola?","o":["Ninguna, solo el conductor necesita cinturón","La restricción de noche","La restricción del teléfono","La del cinturón: todos en el carro deben llevarlo puesto"],"h1":"Para conductores provisionales menores de 18, la regla incluye a todos en el carro.","h2":"En Maryland, un conductor provisional menor de 18 siempre debe usar el cinturón, y cada pasajero debe usar cinturón o asiento de seguridad infantil.","p":"¡Correcto! Todos en el carro de un conductor provisional deben ir abrochados."},"ref":{"doc":"MD","page":47}},{"id":"md-143","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a 16-year-old in the first 151 days of a provisional license wants to drive a 15-year-old cousin who lives in the same home. Is this allowed?","o":["No, cousins are never immediate family","Yes, a relative living at your address counts as immediate family","Only with a note from the cousin's parents","Only on weekends"],"h1":"Where the relative lives matters.","h2":"In Maryland, immediate family for the passenger restriction includes any relative who lives at your address, so that cousin may ride.","p":"Yes! A relative who lives with you counts as immediate family."},"es":{"q":"En Maryland, un joven de 16 años, en los primeros 151 días con licencia provisional, quiere llevar a un primo de 15 años que vive en su misma casa. ¿Está permitido?","o":["No, los primos nunca son familia inmediata","Sí, un pariente que vive en su domicilio cuenta como familia inmediata","Solo con una nota de los padres del primo","Solo los fines de semana"],"h1":"Importa dónde vive el pariente.","h2":"En Maryland, la familia inmediata para la restricción de pasajeros incluye a cualquier pariente que viva en su domicilio, así que ese primo puede ir con usted.","p":"¡Sí! Un pariente que vive con usted cuenta como familia inmediata."},"ref":{"doc":"MD","page":47}},{"id":"md-144","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a 17-year-old provisional driver wants to drive alone at 1 a.m. For which trip is this allowed?","o":["Driving to a friend's house to study","Driving home from an official school activity","Driving to buy a snack","Driving around to practice"],"h1":"The exceptions are work, school activities, organized volunteering and athletic events.","h2":"In Maryland, a provisional driver under 18 may drive alone between midnight and 5 a.m. only for a job, an organized volunteer program, an official school activity, or an athletic event or training they take part in.","p":"Correct! A school activity is one of the allowed exceptions."},"es":{"q":"En Maryland, un conductor provisional de 17 años quiere manejar solo a la 1 a.m. ¿Para qué viaje se permite?","o":["Ir a casa de un amigo a estudiar","Regresar a casa de una actividad escolar oficial","Ir a comprar algo de comer","Dar vueltas para practicar"],"h1":"Las excepciones son trabajo, actividades escolares, voluntariado organizado y eventos deportivos.","h2":"En Maryland, un conductor provisional menor de 18 puede manejar solo entre la medianoche y las 5 a.m. solo por trabajo, un programa de voluntariado organizado, una actividad escolar oficial o un evento o entrenamiento deportivo en el que participa.","p":"¡Correcto! Una actividad escolar es una de las excepciones."},"ref":{"doc":"MD","page":47}},{"id":"md-145","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, where does the implied consent law apply to drivers?","o":["Only on interstate highways","Only on roads with a posted speed limit","Only inside city limits","On public roads and on private property used by the public"],"h1":"It also covers places like shopping center parking lots.","h2":"In Maryland, if you drive or try to drive on a road or on private property used by the public, you agree to take a drug or alcohol test if an officer asks.","p":"Right! It covers roads and private property open to the public."},"es":{"q":"En Maryland, ¿dónde se aplica a los conductores la ley de consentimiento implícito?","o":["Solo en autopistas interestatales","Solo en vías con límite de velocidad","Solo dentro de las ciudades","En vías públicas y en propiedad privada usada por el público"],"h1":"También incluye lugares como los estacionamientos de centros comerciales.","h2":"En Maryland, si maneja o intenta manejar en una vía o en propiedad privada usada por el público, acepta hacerse una prueba de drogas o alcohol si un policía se lo pide.","p":"¡Correcto! Incluye vías y propiedad privada abierta al público."},"ref":{"doc":"MD","page":47}},{"id":"md-146","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, a 19-year-old lies about their age to buy beer. Besides other penalties, what can happen to their driving?","o":["The driver's license may be suspended","Nothing, because it is not a driving offense","They must retake the driving test only","They get a warning letter only"],"h1":"The MVA can act even though no car was involved.","h2":"In Maryland, lying about your age to buy, have or get alcohol can lead to your driver's license being suspended, on top of other penalties.","p":"Yes! The license may be suspended."},"es":{"q":"En Maryland, una persona de 19 años miente sobre su edad para comprar cerveza. Además de otras sanciones, ¿qué le puede pasar a su licencia?","o":["Le pueden suspender la licencia de conducir","Nada, porque no es una falta de manejo","Solo debe repetir el examen práctico","Solo recibe una carta de advertencia"],"h1":"La MVA puede actuar aunque no haya un carro de por medio.","h2":"En Maryland, mentir sobre su edad para comprar, tener u obtener alcohol puede llevar a la suspensión de su licencia, además de otras sanciones.","p":"¡Sí! Le pueden suspender la licencia."},"ref":{"doc":"MD","page":48}},{"id":"md-147","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, your license is suspended. When does the suspension period begin?","o":["On the day of the traffic stop","On your next birthday","When the MVA receives your license","When you pay any fine"],"h1":"Turning in the license starts the clock.","h2":"In Maryland, you must give your license to the MVA, and the suspension or revocation period begins when the MVA receives it.","p":"Correct! It begins when the MVA receives your license."},"es":{"q":"En Maryland, le suspenden la licencia. ¿Cuándo empieza el periodo de suspensión?","o":["El día de la parada de tránsito","En su próximo cumpleaños","Cuando la MVA recibe su licencia","Cuando paga cualquier multa"],"h1":"Entregar la licencia pone en marcha el reloj.","h2":"En Maryland, debe entregar su licencia a la MVA, y el periodo de suspensión o revocación empieza cuando la MVA la recibe.","p":"¡Correcto! Empieza cuando la MVA recibe su licencia."},"ref":{"doc":"MD","page":48}},{"id":"md-148","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, the MVA lets a suspended driver drive only to and from work and school. What is this called?","o":["A learner's permit","A provisional license","A restricted license","A commercial license"],"h1":"Driving is allowed only for certain purposes.","h2":"In Maryland, the MVA may give a suspended driver a restricted license that allows driving only for specific purposes, such as work and school.","p":"Right! That is a restricted license."},"es":{"q":"En Maryland, la MVA deja que un conductor suspendido maneje solo de ida y vuelta al trabajo y la escuela. ¿Cómo se llama esto?","o":["Un permiso de aprendizaje","Una licencia provisional","Una licencia restringida","Una licencia comercial"],"h1":"Solo se permite manejar para ciertos fines.","h2":"En Maryland, la MVA puede darle a un conductor suspendido una licencia restringida que permite manejar solo para fines específicos, como el trabajo y la escuela.","p":"¡Correcto! Es una licencia restringida."},"ref":{"doc":"MD","page":48}},{"id":"md-149","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, which action against a license is the most severe?","o":["Cancellation","Suspension","Revocation","A warning letter"],"h1":"It means the driving privilege is ended and not given back.","h2":"In Maryland, cancellation is more severe than a suspension or a revocation; it ends the driving privilege and it is not reinstated.","p":"Yes! Cancellation is the most severe."},"es":{"q":"En Maryland, ¿cuál medida contra una licencia es la más severa?","o":["La cancelación","La suspensión","La revocación","Una carta de advertencia"],"h1":"Significa que el privilegio de manejar termina y no se devuelve.","h2":"En Maryland, la cancelación es más severa que la suspensión o la revocación; termina el privilegio de manejar y no se restablece.","p":"¡Sí! La cancelación es la más severa."},"ref":{"doc":"MD","page":48}},{"id":"md-150","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, the MVA finds that a driver gave false information to get a license. What may the MVA do?","o":["Only send a reminder letter","Give the driver extra points for honesty","Extend the license by one year","Cancel the license"],"h1":"This is one of the reasons for the most severe action.","h2":"In Maryland, the MVA may cancel a license if the driver did not give required or correct information on the application or committed fraud to get it.","p":"Correct! The MVA may cancel the license."},"es":{"q":"En Maryland, la MVA descubre que un conductor dio información falsa para obtener la licencia. ¿Qué puede hacer la MVA?","o":["Solo enviarle una carta de recordatorio","Darle puntos extra por honestidad","Extender la licencia un año","Cancelar la licencia"],"h1":"Es uno de los motivos de la medida más severa.","h2":"En Maryland, la MVA puede cancelar una licencia si el conductor no dio información requerida o correcta en la solicitud o cometió fraude para obtenerla.","p":"¡Correcto! La MVA puede cancelar la licencia."},"ref":{"doc":"MD","page":48}},{"id":"md-151","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a 19-year-old with a provisional license is convicted of a second moving violation. What does the MVA do?","o":["Sends a warning letter only","Suspends the license for 30 days","Revokes the license for 5 years","Requires a new learner's permit"],"h1":"For adult provisional drivers, the first offense means a program; the second means a short suspension.","h2":"In Maryland, a provisional driver 18 or older with a second moving violation conviction or PBJ gets a 30-day license suspension.","p":"Right! A second offense brings a 30-day suspension."},"es":{"q":"En Maryland, una persona de 19 años con licencia provisional es condenada por una segunda infracción en movimiento. ¿Qué hace la MVA?","o":["Solo envía una carta de advertencia","Suspende la licencia por 30 días","Revoca la licencia por 5 años","Exige un nuevo permiso de aprendizaje"],"h1":"Para conductores provisionales adultos, la primera falta es un programa; la segunda, una suspensión corta.","h2":"En Maryland, un conductor provisional de 18 años o más con una segunda condena o PBJ por infracción en movimiento recibe una suspensión de 30 días.","p":"¡Correcto! La segunda falta trae 30 días de suspensión."},"ref":{"doc":"MD","page":49}},{"id":"md-152","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, a provisional driver under 18 is convicted of a third moving violation. What happens?","o":["Only a driver improvement program","A 180-day suspension, a young driver program and a 180-day work and school restriction","A 30-day suspension only","The license is revoked and all tests must be retaken"],"h1":"It is the step before revocation.","h2":"In Maryland, a provisional driver under 18 with a third offense gets a 180-day suspension, must attend a driver improvement program for young drivers, and has a 180-day employment and education only restriction.","p":"Yes! A third offense brings 180 days of suspension plus a program and restriction."},"es":{"q":"En Maryland, un conductor provisional menor de 18 es condenado por una tercera infracción en movimiento. ¿Qué pasa?","o":["Solo un programa de mejoramiento del conductor","Suspensión de 180 días, un programa para jóvenes y 180 días de restricción a trabajo y escuela","Solo una suspensión de 30 días","Se revoca la licencia y debe repetir todos los exámenes"],"h1":"Es el paso anterior a la revocación.","h2":"En Maryland, un conductor provisional menor de 18 con una tercera falta recibe 180 días de suspensión, debe asistir a un programa de mejoramiento para conductores jóvenes y tiene 180 días de restricción solo para trabajo y estudios.","p":"¡Sí! La tercera falta trae 180 días de suspensión, un programa y una restricción."},"ref":{"doc":"MD","page":49}},{"id":"md-153","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a provisional driver is convicted of a moving violation. What starts over after each conviction?","o":["The 60 hours of practice driving","The driver education course","The vision screening","The 18-month conviction-free period needed for a full license"],"h1":"It is the clean-record time you must finish before the full license.","h2":"In Maryland, after each moving violation conviction or PBJ on a provisional license, the driver must begin a new 18-month conviction-free period.","p":"Correct! A new 18-month conviction-free period begins."},"es":{"q":"En Maryland, un conductor provisional es condenado por una infracción en movimiento. ¿Qué empieza de nuevo después de cada condena?","o":["Las 60 horas de práctica","El curso de educación vial","El examen de la vista","El periodo de 18 meses sin condenas necesario para la licencia completa"],"h1":"Es el tiempo con récord limpio que debe cumplir antes de la licencia completa.","h2":"En Maryland, después de cada condena o PBJ por infracción en movimiento con licencia provisional, el conductor debe empezar un nuevo periodo de 18 meses sin condenas.","p":"¡Correcto! Empieza un nuevo periodo de 18 meses sin condenas."},"ref":{"doc":"MD","page":49}},{"id":"md-154","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, you have a valid disability placard. Where may you still NOT park?","o":["In front of a curb cut or on the striped access aisle","In a marked disability parking space","In a regular parking space","In a public garage space"],"h1":"Those areas are needed by people using wheelchairs.","h2":"In Maryland, even with a disability plate or placard, you may not block any part of a curb cut or park on the access aisle next to a disability space.","p":"Right! Never block a curb cut or access aisle, even with a placard."},"es":{"q":"En Maryland, tiene un permiso válido de estacionamiento para personas con discapacidad. ¿Dónde sigue sin poder estacionarse?","o":["Frente a una rampa de la acera o en el pasillo de acceso rayado","En un espacio marcado para personas con discapacidad","En un espacio de estacionamiento común","En un espacio de un garaje público"],"h1":"Esas áreas las necesitan las personas en silla de ruedas.","h2":"En Maryland, aun con placa o permiso de discapacidad, no puede tapar ninguna parte de una rampa de acera ni estacionarse en el pasillo de acceso junto a un espacio para personas con discapacidad.","p":"¡Correcto! Nunca tape una rampa ni un pasillo de acceso, aun con permiso."},"ref":{"doc":"MD","page":49}},{"id":"md-155","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, what device may a driver caught drinking and driving have to install in the car?","o":["A speed limiter set to 45 mph","A dash camera that records every trip","An ignition interlock that blocks starting if alcohol is detected","A GPS tracker for the police"],"h1":"It is a breath test built into the car's starting system.","h2":"In Maryland, a driver caught drinking and driving will have to install an ignition interlock, a breathalyzer car lock that keeps the car from starting if alcohol is detected.","p":"Yes! An ignition interlock that detects alcohol."},"es":{"q":"En Maryland, ¿qué aparato puede tener que instalar en el carro un conductor sorprendido manejando después de beber?","o":["Un limitador de velocidad a 45 mph","Una cámara que graba cada viaje","Un bloqueo de encendido que impide arrancar si detecta alcohol","Un rastreador GPS para la policía"],"h1":"Es una prueba de aliento conectada al arranque del carro.","h2":"En Maryland, un conductor sorprendido manejando después de beber deberá instalar un bloqueo de encendido, un alcoholímetro que impide que el carro arranque si detecta alcohol.","p":"¡Sí! Un bloqueo de encendido que detecta alcohol."},"ref":{"doc":"MD","page":50}},{"id":"md-156","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maryland, you already have a license and are later diagnosed with epilepsy. When must you tell the MVA?","o":["Only at your next renewal","Only if you have a crash","When it is diagnosed","Never, it is private"],"h1":"You do not wait for renewal if the condition is new.","h2":"In Maryland, if a reportable medical condition such as epilepsy is diagnosed after you get your license, you must notify the MVA when it is diagnosed.","p":"Correct! Tell the MVA when it is diagnosed."},"es":{"q":"En Maryland, ya tiene licencia y después le diagnostican epilepsia. ¿Cuándo debe avisarle a la MVA?","o":["Solo en su próxima renovación","Solo si tiene un choque","Cuando se lo diagnostican","Nunca, es privado"],"h1":"No espera a la renovación si la condición es nueva.","h2":"En Maryland, si le diagnostican una condición médica reportable, como la epilepsia, después de obtener la licencia, debe avisarle a la MVA cuando se la diagnostican.","p":"¡Correcto! Avise a la MVA cuando se la diagnostiquen."},"ref":{"doc":"MD","page":51}},{"id":"md-157","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, which eye problem must be reported to the MVA?","o":["One that keeps you from seeing at least 20/70 in one eye with correction","Needing glasses to read a menu","Wearing contact lenses","Being color blind to red and green only"],"h1":"The limit is about corrected vision in at least one eye or a 110-degree field.","h2":"In Maryland, you must report an eye problem that keeps you from a corrected visual acuity of at least 20/70 in at least one eye or a binocular field of vision of at least 110 degrees.","p":"Right! Report it if corrected vision is worse than 20/70 in both eyes."},"es":{"q":"En Maryland, ¿qué problema de la vista debe reportarse a la MVA?","o":["Uno que le impide ver al menos 20/70 en un ojo con corrección","Necesitar lentes para leer un menú","Usar lentes de contacto","No distinguir solo el rojo del verde"],"h1":"El límite es sobre la vista corregida en al menos un ojo o un campo de 110 grados.","h2":"En Maryland, debe reportar un problema de la vista que le impida tener una agudeza corregida de al menos 20/70 en al menos un ojo o un campo visual binocular de al menos 110 grados.","p":"¡Correcto! Se reporta si con corrección ve peor que 20/70 en ambos ojos."},"ref":{"doc":"MD","page":51}},{"id":"md-158","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a learner's permit holder is practicing on a motorcycle. Where must the supervising driver be?","o":["On the same motorcycle, as a passenger","Waiting at home by phone","Seated beside the learner on the motorcycle","Supervising, but not seated beside the learner"],"h1":"The beside-you rule has one exception.","h2":"In Maryland, the supervising driver must be seated beside the learner unless the vehicle is a motorcycle.","p":"Yes! The seated-beside rule does not apply to motorcycles."},"es":{"q":"En Maryland, una persona con permiso de aprendizaje practica en motocicleta. ¿Dónde debe estar el conductor supervisor?","o":["En la misma motocicleta, como pasajero","Esperando en casa por teléfono","Sentado junto al aprendiz en la motocicleta","Supervisando, pero sin ir sentado junto al aprendiz"],"h1":"La regla de ir sentado al lado tiene una excepción.","h2":"En Maryland, el conductor supervisor debe ir sentado junto al aprendiz, salvo que el vehículo sea una motocicleta.","p":"¡Sí! La regla de ir sentado al lado no se aplica a motocicletas."},"ref":{"doc":"MD","page":51}},{"id":"md-159","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, at what age may a minor sign up as an organ donor with a parent's written consent?","o":["12","16","14","18"],"h1":"Anyone 18 or older may sign up alone.","h2":"In Maryland, minors who are at least 16 may be organ donors if a parent or guardian agrees in writing.","p":"Correct! At 16, with written parent consent."},"es":{"q":"En Maryland, ¿a qué edad puede un menor registrarse como donante de órganos con permiso escrito de sus padres?","o":["12 años","16 años","14 años","18 años"],"h1":"Desde los 18, cualquiera puede registrarse solo.","h2":"En Maryland, los menores de al menos 16 años pueden ser donantes de órganos si uno de sus padres o su tutor lo autoriza por escrito.","p":"¡Correcto! A los 16, con permiso escrito de los padres."},"ref":{"doc":"MD","page":51}},{"id":"md-160","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maryland, what may you also do at the MVA when you get a driver's license, under the federal \"Motor Voter\" law?","o":["Renew your passport","Register to vote or update your voter information","Apply for a fishing license","File your state taxes"],"h1":"The law's nickname gives a clue.","h2":"In Maryland, the federal Motor Voter law requires the MVA to let eligible customers register to vote or update their voting information when they get a license or ID card.","p":"Right! You may register to vote at the MVA."},"es":{"q":"En Maryland, ¿qué más puede hacer en la MVA al obtener la licencia, según la ley federal conocida como \"Motor Voter\"?","o":["Renovar su pasaporte","Registrarse para votar o actualizar sus datos de votante","Solicitar una licencia de pesca","Presentar sus impuestos estatales"],"h1":"El apodo de la ley da una pista.","h2":"En Maryland, la ley federal Motor Voter exige que la MVA deje a los clientes que califican registrarse para votar o actualizar sus datos cuando obtienen la licencia o la tarjeta de identificación.","p":"¡Correcto! Puede registrarse para votar en la MVA."},"ref":{"doc":"MD","page":52}},{"id":"md-161","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, a police officer asks for your insurance card. Your card is on your phone. Is that OK?","o":["No, only a paper card is accepted","Only if you also show the bill","Only on weekends","Yes, the card may be in electronic form"],"h1":"The card must be with you, but it does not have to be paper.","h2":"In Maryland, you must always have a valid insurance identification card with you when driving, and it may be electronic; refusing to show it can bring a fine.","p":"Correct! An electronic insurance card is allowed."},"es":{"q":"En Maryland, un policía le pide su tarjeta del seguro. La tiene en el teléfono. ¿Está bien?","o":["No, solo se acepta en papel","Solo si también muestra la factura","Solo los fines de semana","Sí, la tarjeta puede ser electrónica"],"h1":"Debe llevar la tarjeta, pero no tiene que ser de papel.","h2":"En Maryland, siempre debe llevar una tarjeta de seguro válida al manejar, y puede ser electrónica; negarse a mostrarla puede costarle una multa.","p":"¡Correcto! Se permite la tarjeta de seguro electrónica."},"ref":{"doc":"MD","page":52}},{"id":"md-162","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, how much space does the MVA suggest keeping between your chest and the steering wheel air bag?","o":["10 to 12 inches","2 to 3 inches","4 to 6 inches","At least 3 feet"],"h1":"Sit far enough back to give the air bag room to open, about a foot.","h2":"In Maryland, the MVA suggests sitting as far back as possible and keeping 10 to 12 inches between your chest and the steering wheel.","p":"Yes! Keep 10 to 12 inches from the steering wheel."},"es":{"q":"En Maryland, ¿cuánto espacio sugiere la MVA dejar entre su pecho y la bolsa de aire del volante?","o":["De 10 a 12 pulgadas","De 2 a 3 pulgadas","De 4 a 6 pulgadas","Al menos 3 pies"],"h1":"Siéntese lo bastante atrás para que la bolsa de aire tenga lugar, cerca de un pie.","h2":"En Maryland, la MVA sugiere sentarse lo más atrás posible y dejar de 10 a 12 pulgadas entre el pecho y el volante.","p":"¡Sí! Deje de 10 a 12 pulgadas del volante."},"ref":{"doc":"MD","page":52}},{"id":"md-163","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, until what age does the MVA say children should ride buckled up in a back seat?","o":["Under 5","Under 8","Under 13","Under 18"],"h1":"It is the age when a child becomes a teenager.","h2":"In Maryland, the MVA says children under age 13 should ride buckled up in a rear seat, in a child safety seat or with a seat belt.","p":"Correct! Children under 13 should ride in the back seat."},"es":{"q":"En Maryland, ¿hasta qué edad dice la MVA que los niños deben ir abrochados en el asiento de atrás?","o":["Menores de 5 años","Menores de 8 años","Menores de 13 años","Menores de 18 años"],"h1":"Es la edad en que un niño se vuelve adolescente.","h2":"En Maryland, la MVA dice que los niños menores de 13 años deben ir abrochados en un asiento trasero, en un asiento de seguridad o con el cinturón.","p":"¡Correcto! Los menores de 13 deben ir atrás."},"ref":{"doc":"MD","page":52}},{"id":"md-164","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, a family cannot afford a car seat. Which program can help them rent one at low cost?","o":["The MVA driver improvement program","The Motor Voter program","Kids In Safety Seats (KISS) at the Maryland Department of Health","The Emergency Notification System"],"h1":"Its name spells a short, friendly word.","h2":"In Maryland, families who cannot afford a child safety seat can contact Kids In Safety Seats (KISS) at the Maryland Department of Health, which helps rent seats at low cost.","p":"Right! KISS helps families get low-cost car seats."},"es":{"q":"En Maryland, una familia no puede pagar un asiento de seguridad infantil. ¿Qué programa puede ayudarla a rentar uno a bajo costo?","o":["El programa de mejoramiento del conductor de la MVA","El programa Motor Voter","Kids In Safety Seats (KISS) del Departamento de Salud de Maryland","El Sistema de Notificación de Emergencias"],"h1":"Su nombre forma una palabra corta y amistosa en inglés.","h2":"En Maryland, las familias que no pueden comprar un asiento de seguridad infantil pueden contactar a Kids In Safety Seats (KISS) del Departamento de Salud de Maryland, que ayuda a rentar asientos a bajo costo.","p":"¡Correcto! KISS ayuda a conseguir asientos de bajo costo."},"ref":{"doc":"MD","page":52}},{"id":"md-165","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maryland, is parallel parking part of the driving skills test?","o":["No, it is no longer required on the test","Yes, it is the first thing tested","Yes, but only for drivers under 18","Only if you fail the three-point turn"],"h1":"You still learn it in driver education, and a reverse two-point turn checks the same skills.","h2":"In Maryland, parallel parking is no longer required on the driving test, though you learn it in driver education.","p":"Yes! Parallel parking is not on the Maryland test."},"es":{"q":"En Maryland, ¿el estacionamiento en paralelo es parte del examen práctico?","o":["No, ya no se exige en el examen","Sí, es lo primero que se evalúa","Sí, pero solo para menores de 18","Solo si falla la vuelta en tres puntos"],"h1":"Igual se aprende en la educación vial, y una vuelta de dos puntos en reversa evalúa las mismas habilidades.","h2":"En Maryland, el estacionamiento en paralelo ya no se exige en el examen práctico, aunque se aprende en la educación vial.","p":"¡Sí! El estacionamiento en paralelo no está en el examen de Maryland."},"ref":{"doc":"MD","page":53}},{"id":"md-166","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maryland, how big is the space for pull-in and back-in parking on the driving test?","o":["8 feet by 16 feet","12 feet by 30 feet","16 feet by 20 feet","10 feet by 20 feet"],"h1":"The three-point turn uses a wider space.","h2":"In Maryland, the pull-in and back-in parking on the driving test is done in a 10 by 20 foot space, and the three-point turn in a 16 by 20 foot space.","p":"Correct! The parking space is 10 by 20 feet."},"es":{"q":"En Maryland, ¿de qué tamaño es el espacio para estacionarse de frente y en reversa en el examen práctico?","o":["8 pies por 16 pies","12 pies por 30 pies","16 pies por 20 pies","10 pies por 20 pies"],"h1":"La vuelta en tres puntos usa un espacio más ancho.","h2":"En Maryland, el estacionamiento de frente y en reversa del examen se hace en un espacio de 10 por 20 pies, y la vuelta en tres puntos en uno de 16 por 20 pies.","p":"¡Correcto! El espacio es de 10 por 20 pies."},"ref":{"doc":"MD","page":53}},{"id":"md-167","scope":"MD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maryland, how may a bicyclist make a left turn?","o":["Only by riding across against traffic","Like a car from the left side of the lane, or by walking the bike across a crosswalk","Only from the right edge of the road","Bicyclists may not turn left in Maryland"],"h1":"There are two choices: ride like a vehicle or cross like a pedestrian.","h2":"In Maryland, a bicyclist may turn left like a motor vehicle by moving to the left side of the lane or left-turn lane, or cross like a pedestrian by walking the bike in a crosswalk.","p":"Right! Turn like a car, or walk across like a pedestrian."},"es":{"q":"En Maryland, ¿cómo puede girar a la izquierda un ciclista?","o":["Solo cruzando en contra del tránsito","Como un carro desde el lado izquierdo del carril, o caminando con la bici por el cruce peatonal","Solo desde la orilla derecha de la vía","Los ciclistas no pueden girar a la izquierda en Maryland"],"h1":"Hay dos opciones: andar como vehículo o cruzar como peatón.","h2":"En Maryland, un ciclista puede girar a la izquierda como un vehículo, pasando al lado izquierdo del carril o al carril de giro, o cruzar como peatón caminando con la bicicleta por el cruce.","p":"¡Correcto! Gira como un carro o cruza caminando como peatón."},"ref":{"doc":"MD","page":53}},{"id":"md-168","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maryland, a bicycle is ridden at night. From how far away must its rear red reflector be visible?","o":["50 feet","600 feet","100 feet","2,000 feet"],"h1":"The white headlight must be seen from 500 feet; the reflector a bit farther.","h2":"In Maryland, a bicycle ridden at night needs a white headlight visible from 500 feet and a red rear reflector visible from 600 feet.","p":"Yes! The red reflector must be visible from 600 feet."},"es":{"q":"En Maryland, una bicicleta se usa de noche. ¿Desde qué distancia debe verse su reflector rojo trasero?","o":["50 pies","600 pies","100 pies","2,000 pies"],"h1":"La luz blanca delantera debe verse desde 500 pies; el reflector, un poco más lejos.","h2":"En Maryland, una bicicleta de noche necesita una luz blanca delantera visible desde 500 pies y un reflector rojo trasero visible desde 600 pies.","p":"¡Sí! El reflector rojo debe verse desde 600 pies."},"ref":{"doc":"MD","page":54}},{"id":"md-169","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maryland, who must wear a helmet on a bicycle?","o":["Only riders over 65","Only riders on highways","No one; helmets are only suggested","Anyone under 16, including passengers"],"h1":"The rule covers young riders, even if they are not steering.","h2":"In Maryland, helmets are required for anyone under 16 riding on a bicycle, including passengers, and are strongly recommended for all ages.","p":"Correct! Riders under 16, including passengers, must wear helmets."},"es":{"q":"En Maryland, ¿quién debe usar casco en bicicleta?","o":["Solo los mayores de 65","Solo quienes van por autopistas","Nadie; el casco solo se recomienda","Toda persona menor de 16, incluidos los pasajeros"],"h1":"La regla cubre a los más jóvenes, aunque no vayan manejando.","h2":"En Maryland, el casco es obligatorio para toda persona menor de 16 que vaya en bicicleta, incluidos los pasajeros, y se recomienda mucho a todas las edades.","p":"¡Correcto! Los menores de 16, incluidos los pasajeros, deben usar casco."},"ref":{"doc":"MD","page":54}},{"id":"md-170","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, a bicycle's brakes must stop it within what distance from 10 mph on dry, level, clean pavement?","o":["15 feet","5 feet","40 feet","100 feet"],"h1":"It is about the length of a large car.","h2":"In Maryland, every bicycle must have brakes that can stop it within 15 feet from 10 miles per hour on dry, level, clean pavement.","p":"Right! The brakes must stop the bike within 15 feet."},"es":{"q":"En Maryland, los frenos de una bicicleta deben detenerla a qué distancia desde 10 mph en pavimento seco, plano y limpio?","o":["15 pies","5 pies","40 pies","100 pies"],"h1":"Es más o menos el largo de un carro grande.","h2":"En Maryland, toda bicicleta debe tener frenos que la detengan dentro de 15 pies desde 10 millas por hora en pavimento seco, plano y limpio.","p":"¡Correcto! Los frenos deben detenerla dentro de 15 pies."},"ref":{"doc":"MD","page":54}},{"id":"md-171","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, an electric bicycle may have a motor rated at most how many watts?","o":["250 watts","1,500 watts","750 watts","5,000 watts"],"h1":"It is less than one thousand.","h2":"In Maryland, an electric bicycle has fully working pedals, two or three wheels, and an electric motor rated at 750 watts or less.","p":"Yes! An e-bike motor may be 750 watts or less."},"es":{"q":"En Maryland, ¿hasta cuántos vatios puede tener el motor de una bicicleta eléctrica?","o":["250 vatios","1,500 vatios","750 vatios","5,000 vatios"],"h1":"Es menos de mil.","h2":"En Maryland, una bicicleta eléctrica tiene pedales que funcionan, dos o tres ruedas y un motor eléctrico de 750 vatios o menos.","p":"¡Sí! El motor de una bici eléctrica puede ser de 750 vatios o menos."},"ref":{"doc":"MD","page":54}},{"id":"md-172","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maryland, a Class 3 electric bicycle stops helping the rider at what speed?","o":["15 mph","20 mph","28 mph","35 mph"],"h1":"Classes 1 and 2 stop at 20 mph; Class 3 goes a bit faster.","h2":"In Maryland, a Class 3 electric bicycle gives motor assistance only while the rider pedals and stops at 28 miles per hour.","p":"Correct! Class 3 assistance stops at 28 mph."},"es":{"q":"En Maryland, ¿a qué velocidad deja de ayudar al ciclista una bicicleta eléctrica Clase 3?","o":["15 mph","20 mph","28 mph","35 mph"],"h1":"Las Clases 1 y 2 paran a 20 mph; la Clase 3 llega un poco más rápido.","h2":"En Maryland, una bicicleta eléctrica Clase 3 da asistencia del motor solo mientras se pedalea y deja de ayudar a 28 millas por hora.","p":"¡Correcto! La Clase 3 deja de ayudar a 28 mph."},"ref":{"doc":"MD","page":54}},{"id":"md-173","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maryland, how fast can an electric low-speed vehicle, such as a stand-up electric scooter for one rider, operate?","o":["Up to 20 mph","Up to 10 mph","Up to 35 mph","Up to 45 mph"],"h1":"It is the same top assisted speed as Class 1 and 2 e-bikes.","h2":"In Maryland, an electric low-speed vehicle carries only its operator, weighs less than 100 pounds, and can operate at up to 20 miles per hour.","p":"Right! Electric low-speed vehicles go up to 20 mph."},"es":{"q":"En Maryland, ¿a qué velocidad puede ir un vehículo eléctrico de baja velocidad, como una patineta eléctrica de pie para una persona?","o":["Hasta 20 mph","Hasta 10 mph","Hasta 35 mph","Hasta 45 mph"],"h1":"Es la misma velocidad máxima asistida de las bicis eléctricas Clase 1 y 2.","h2":"En Maryland, un vehículo eléctrico de baja velocidad lleva solo a quien lo maneja, pesa menos de 100 libras y puede ir hasta 20 millas por hora.","p":"¡Correcto! Estos vehículos van hasta 20 mph."},"ref":{"doc":"MD","page":54}},{"id":"md-174","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Under Maryland law, unless a sign says otherwise, what is the speed limit on any highway in a business district?","o":["25 mph","40 mph","45 mph","30 mph"],"h1":"It is the same as on undivided roads in a residential district.","h2":"Under Maryland law, the maximum speed on all highways in a business district is 30 mph unless another limit is posted.","p":"Correct! It is 30 mph in a business district."},"es":{"q":"Según la ley de Maryland, salvo que una señal diga otra cosa, ¿cuál es el límite de velocidad en cualquier vía de una zona comercial?","o":["25 mph","40 mph","45 mph","30 mph"],"h1":"Es igual que en vías no divididas de una zona residencial.","h2":"Según la ley de Maryland, la velocidad máxima en todas las vías de una zona comercial es de 30 mph, salvo que haya otro límite señalizado.","p":"¡Correcto! Es de 30 mph en una zona comercial."},"ref":{"doc":"MD","page":null}},{"id":"md-175","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"Under Maryland law, unless a sign says otherwise, what is the speed limit on a divided highway in a residential district?","o":["25 mph","35 mph","30 mph","45 mph"],"h1":"It is 5 mph more than on an undivided residential road.","h2":"Under Maryland law, the maximum speed on a divided highway in a residential district is 35 mph unless another limit is posted.","p":"Right! It is 35 mph on a divided road in a residential district."},"es":{"q":"Según la ley de Maryland, salvo que una señal diga otra cosa, ¿cuál es el límite de velocidad en una vía dividida de una zona residencial?","o":["25 mph","35 mph","30 mph","45 mph"],"h1":"Es 5 mph más que en una vía residencial no dividida.","h2":"Según la ley de Maryland, la velocidad máxima en una vía dividida de una zona residencial es de 35 mph, salvo que haya otro límite señalizado.","p":"¡Correcto! Es de 35 mph en una vía dividida residencial."},"ref":{"doc":"MD","page":null}},{"id":"md-176","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"Under Maryland law, unless a sign says otherwise, what is the speed limit on an undivided highway outside business and residential districts?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"A divided highway in the same kind of area allows 5 mph more.","h2":"Under Maryland law, the maximum speed on an undivided highway outside business and residential districts is 50 mph unless another limit is posted.","p":"Yes! It is 50 mph on an undivided highway there."},"es":{"q":"Según la ley de Maryland, salvo que una señal diga otra cosa, ¿cuál es el límite de velocidad en una carretera no dividida fuera de zonas comerciales y residenciales?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Una carretera dividida en el mismo tipo de zona permite 5 mph más.","h2":"Según la ley de Maryland, la velocidad máxima en una carretera no dividida fuera de zonas comerciales y residenciales es de 50 mph, salvo que haya otro límite señalizado.","p":"¡Sí! Es de 50 mph en una carretera no dividida allí."},"ref":{"doc":"MD","page":null}},{"id":"md-177","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Under Maryland law, unless a sign says otherwise, what is the speed limit on a divided highway outside business and residential districts?","o":["50 mph","60 mph","70 mph","55 mph"],"h1":"Higher limits are allowed only on interstates and expressways when posted.","h2":"Under Maryland law, the maximum speed on a divided highway outside business and residential districts is 55 mph unless another limit is posted.","p":"Correct! It is 55 mph on a divided highway there."},"es":{"q":"Según la ley de Maryland, salvo que una señal diga otra cosa, ¿cuál es el límite de velocidad en una carretera dividida fuera de zonas comerciales y residenciales?","o":["50 mph","60 mph","70 mph","55 mph"],"h1":"Los límites más altos solo se permiten en interestatales y vías rápidas cuando están señalizados.","h2":"Según la ley de Maryland, la velocidad máxima en una carretera dividida fuera de zonas comerciales y residenciales es de 55 mph, salvo que haya otro límite señalizado.","p":"¡Correcto! Es de 55 mph en una carretera dividida allí."},"ref":{"doc":"MD","page":null}},{"id":"md-178","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"Under Maryland law, what is the highest speed limit that may be set on any highway in the state?","o":["70 mph","65 mph","75 mph","80 mph"],"h1":"Limits above 55 mph are allowed only on interstates and expressways.","h2":"Under Maryland law, no highway in the state may have a speed limit above 70 mph, and limits above 55 mph are allowed only on interstates and expressways.","p":"Right! The highest possible limit in Maryland is 70 mph."},"es":{"q":"Según la ley de Maryland, ¿cuál es el límite de velocidad más alto que se puede fijar en cualquier carretera del estado?","o":["70 mph","65 mph","75 mph","80 mph"],"h1":"Los límites de más de 55 mph solo se permiten en interestatales y vías rápidas.","h2":"Según la ley de Maryland, ninguna carretera del estado puede tener un límite de más de 70 mph, y los límites de más de 55 mph solo se permiten en interestatales y vías rápidas.","p":"¡Correcto! El límite más alto posible en Maryland es de 70 mph."},"ref":{"doc":"MD","page":null}},{"id":"md-179","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"Under Maryland law, how many points are added for speeding 10 mph or more over the posted limit (but less than 30 over)?","o":["1 point","5 points","2 points","8 points"],"h1":"Going a little over brings 1 point; this is the next step up.","h2":"Under Maryland law, speeding 10 mph or more over the posted limit adds 2 points to your record.","p":"Yes! It adds 2 points."},"es":{"q":"Según la ley de Maryland, ¿cuántos puntos se suman por ir 10 mph o más por encima del límite (pero menos de 30)?","o":["1 punto","5 puntos","2 puntos","8 puntos"],"h1":"Pasarse un poco da 1 punto; este es el siguiente nivel.","h2":"Según la ley de Maryland, exceder el límite por 10 mph o más suma 2 puntos a su récord.","p":"¡Sí! Suma 2 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-180","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"Under Maryland law, how many points are added for speeding 30 mph or more over the posted limit?","o":["2 points","3 points","6 points","12 points"],"h1":"It is the same as for reckless driving.","h2":"Under Maryland law, speeding 30 mph or more over the posted limit adds 6 points, the same as reckless driving.","p":"Correct! It adds 6 points."},"es":{"q":"Según la ley de Maryland, ¿cuántos puntos se suman por ir 30 mph o más por encima del límite?","o":["2 puntos","3 puntos","6 puntos","12 puntos"],"h1":"Es igual que por manejar en forma temeraria.","h2":"Según la ley de Maryland, exceder el límite por 30 mph o más suma 6 puntos, igual que manejar en forma temeraria.","p":"¡Correcto! Suma 6 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-181","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"Under Maryland law, how many points are added for failing to stop for a school bus with flashing red lights?","o":["3 points","1 point","6 points","12 points"],"h1":"It is the same as for a moving violation that contributes to a crash.","h2":"Under Maryland law, failing to stop for a school vehicle with flashing red lights adds 3 points to your record.","p":"Right! It adds 3 points."},"es":{"q":"Según la ley de Maryland, ¿cuántos puntos se suman por no detenerse ante un autobús escolar con luces rojas intermitentes?","o":["3 puntos","1 punto","6 puntos","12 puntos"],"h1":"Es igual que por una infracción en movimiento que contribuye a un choque.","h2":"Según la ley de Maryland, no detenerse ante un vehículo escolar con luces rojas intermitentes suma 3 puntos a su récord.","p":"¡Correcto! Suma 3 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-182","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"Under Maryland law, how many points are added for driving on a learner's permit without a supervising driver?","o":["1 point","2 points","12 points","5 points"],"h1":"It is the same as for driving with no license at all.","h2":"Under Maryland law, driving on a learner's permit unaccompanied adds 5 points, the same as driving while not licensed.","p":"Yes! It adds 5 points."},"es":{"q":"Según la ley de Maryland, ¿cuántos puntos se suman por manejar con permiso de aprendizaje sin conductor supervisor?","o":["1 punto","2 puntos","12 puntos","5 puntos"],"h1":"Es igual que por manejar sin ninguna licencia.","h2":"Según la ley de Maryland, manejar con permiso de aprendizaje sin acompañante suma 5 puntos, igual que manejar sin licencia.","p":"¡Sí! Suma 5 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-183","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"Under Maryland law, how many points does a conviction for driving under the influence of alcohol add?","o":["3 points","12 points","6 points","8 points"],"h1":"It is the top number on the points table.","h2":"Under Maryland law, a conviction for driving under the influence of alcohol, or under the influence per se, adds 12 points.","p":"Correct! DUI adds 12 points."},"es":{"q":"Según la ley de Maryland, ¿cuántos puntos suma una condena por manejar bajo la influencia del alcohol?","o":["3 puntos","12 puntos","6 puntos","8 puntos"],"h1":"Es el número más alto de la tabla de puntos.","h2":"Según la ley de Maryland, una condena por manejar bajo la influencia del alcohol, o bajo la influencia per se, suma 12 puntos.","p":"¡Correcto! Manejar bajo la influencia suma 12 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-184","scope":"MD","cat":"licensing","sign":null,"c":1,"en":{"q":"Under Maryland law, what does the MVA do when a driver reaches 3 points within 2 years?","o":["Suspends the license","Sends a warning letter","Revokes the license","Requires a new road test"],"h1":"It is the first, mildest step.","h2":"Under Maryland law, the MVA sends a warning letter to a driver who reaches 3 points within any 2-year period.","p":"Right! At 3 points, the MVA sends a warning letter."},"es":{"q":"Según la ley de Maryland, ¿qué hace la MVA cuando un conductor llega a 3 puntos en 2 años?","o":["Suspende la licencia","Envía una carta de advertencia","Revoca la licencia","Exige un nuevo examen práctico"],"h1":"Es el primer paso, el más leve.","h2":"Según la ley de Maryland, la MVA envía una carta de advertencia al conductor que llega a 3 puntos en cualquier periodo de 2 años.","p":"¡Correcto! Con 3 puntos, la MVA envía una carta de advertencia."},"ref":{"doc":"MD","page":null}},{"id":"md-185","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"Under Maryland law, a driver reaches 5 points within 2 years. What must they do?","o":["Give up the license for one year","Retake the knowledge test only","Nothing until 12 points","Attend a driver improvement program"],"h1":"It is a class, not a suspension.","h2":"Under Maryland law, the MVA requires a driver who reaches 5 points within 2 years to attend a driver improvement program.","p":"Yes! At 5 points, a driver improvement program is required."},"es":{"q":"Según la ley de Maryland, un conductor llega a 5 puntos en 2 años. ¿Qué debe hacer?","o":["Entregar la licencia por un año","Repetir solo el examen teórico","Nada hasta llegar a 12 puntos","Asistir a un programa de mejoramiento del conductor"],"h1":"Es un curso, no una suspensión.","h2":"Según la ley de Maryland, la MVA exige que el conductor que llega a 5 puntos en 2 años asista a un programa de mejoramiento del conductor.","p":"¡Sí! Con 5 puntos se exige un programa de mejoramiento."},"ref":{"doc":"MD","page":null}},{"id":"md-186","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"Under Maryland law, at how many points within 2 years is a driver's license suspended?","o":["8 points","3 points","5 points","15 points"],"h1":"It comes after the warning letter and the driver improvement program.","h2":"Under Maryland law, the MVA suspends the license of a driver who reaches 8 points within any 2-year period.","p":"Correct! The license is suspended at 8 points."},"es":{"q":"Según la ley de Maryland, ¿con cuántos puntos en 2 años se suspende la licencia?","o":["8 puntos","3 puntos","5 puntos","15 puntos"],"h1":"Viene después de la carta de advertencia y del programa de mejoramiento.","h2":"Según la ley de Maryland, la MVA suspende la licencia del conductor que llega a 8 puntos en cualquier periodo de 2 años.","p":"¡Correcto! La licencia se suspende con 8 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-187","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"Under Maryland law, at how many points within 2 years is a driver's license revoked?","o":["8 points","10 points","12 points","20 points"],"h1":"It is the same number a single DUI conviction adds.","h2":"Under Maryland law, the MVA revokes the license of a driver who reaches 12 points within any 2-year period.","p":"Right! The license is revoked at 12 points."},"es":{"q":"Según la ley de Maryland, ¿con cuántos puntos en 2 años se revoca la licencia?","o":["8 puntos","10 puntos","12 puntos","20 puntos"],"h1":"Es el mismo número que suma una sola condena por manejar bajo la influencia.","h2":"Según la ley de Maryland, la MVA revoca la licencia del conductor que llega a 12 puntos en cualquier periodo de 2 años.","p":"¡Correcto! La licencia se revoca con 12 puntos."},"ref":{"doc":"MD","page":null}},{"id":"md-188","scope":"MD","cat":"licensing","sign":null,"c":2,"en":{"q":"Under Maryland law, a provisional driver under 18 gets 5 or more points within 12 months for the first time. What happens?","o":["A warning letter is sent","The license is revoked for 5 years","The license is suspended for 6 months","Nothing until age 18"],"h1":"The penalty is about half a year.","h2":"Under Maryland law, the MVA suspends the license of a provisional driver under 18 who gets 5 or more points in 12 months, for 6 months on a first offense and 1 year after that.","p":"Yes! The first time, the suspension is 6 months."},"es":{"q":"Según la ley de Maryland, un conductor provisional menor de 18 llega por primera vez a 5 puntos o más en 12 meses. ¿Qué pasa?","o":["Se envía una carta de advertencia","Se revoca la licencia por 5 años","Se suspende la licencia por 6 meses","Nada hasta cumplir 18"],"h1":"La sanción dura cerca de medio año.","h2":"Según la ley de Maryland, la MVA suspende la licencia de un conductor provisional menor de 18 que llega a 5 puntos o más en 12 meses, por 6 meses la primera vez y por 1 año las siguientes.","p":"¡Sí! La primera vez, la suspensión es de 6 meses."},"ref":{"doc":"MD","page":null}},{"id":"md-189","scope":"MD","cat":"licensing","sign":null,"c":0,"en":{"q":"Under Maryland law, what is the minimum liability insurance for injuries to one person in a crash?","o":["$30,000","$15,000","$20,000","$50,000"],"h1":"For two or more people, the minimum is double this amount.","h2":"Under Maryland law, vehicle liability insurance must cover at least $30,000 for injury or death of one person and $60,000 for two or more people.","p":"Correct! The minimum is $30,000 for one person."},"es":{"q":"Según la ley de Maryland, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$30,000","$15,000","$20,000","$50,000"],"h1":"Para dos o más personas, el mínimo es el doble de esta cantidad.","h2":"Según la ley de Maryland, el seguro de responsabilidad debe cubrir al menos $30,000 por lesiones o muerte de una persona y $60,000 para dos o más personas.","p":"¡Correcto! El mínimo es de $30,000 por persona."},"ref":{"doc":"MD","page":null}},{"id":"md-190","scope":"MD","cat":"licensing","sign":null,"c":3,"en":{"q":"Under Maryland law, what is the minimum insurance for damage to other people's property in a crash?","o":["$5,000","$10,000","$30,000","$15,000"],"h1":"It is half of the minimum for injuries to one person.","h2":"Under Maryland law, vehicle liability insurance must cover at least $15,000 for damage to the property of others.","p":"Right! The property damage minimum is $15,000."},"es":{"q":"Según la ley de Maryland, ¿cuál es el seguro mínimo por daños a la propiedad de otras personas en un choque?","o":["$5,000","$10,000","$30,000","$15,000"],"h1":"Es la mitad del mínimo por lesiones a una persona.","h2":"Según la ley de Maryland, el seguro de responsabilidad debe cubrir al menos $15,000 por daños a la propiedad de otros.","p":"¡Correcto! El mínimo por daños a la propiedad es de $15,000."},"ref":{"doc":"MD","page":null}},{"id":"md-191","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Maryland law, you are in a crash where someone is hurt, and no police officer files a report. Within how many days must you send a written report to the MVA?","o":["3 days","15 days","30 days","60 days"],"h1":"It is about two weeks.","h2":"Under Maryland law, a driver in a crash that injures or kills someone must send a written report to the MVA within 15 days, unless a police officer investigated and filed a report.","p":"Yes! The report is due within 15 days."},"es":{"q":"Según la ley de Maryland, tiene un choque con una persona herida y ningún policía hace un reporte. ¿En cuántos días debe enviar un reporte escrito a la MVA?","o":["3 días","15 días","30 días","60 días"],"h1":"Son unas dos semanas.","h2":"Según la ley de Maryland, el conductor en un choque con heridos o muertos debe enviar un reporte escrito a la MVA en un plazo de 15 días, salvo que un policía haya investigado y presentado un reporte.","p":"¡Sí! El reporte se debe enviar en 15 días."},"ref":{"doc":"MD","page":null}},{"id":"md-192","scope":"MD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"Under Maryland law, what is the highest fine for a first offense of holding a phone to talk while driving?","o":["$25","$75","$500","$1,000"],"h1":"Later offenses cost $125 and then $175.","h2":"Under Maryland law, using a hand-held phone while driving brings a fine of up to $75 for a first offense, and no points unless it contributes to a crash.","p":"Correct! A first offense can cost up to $75."},"es":{"q":"Según la ley de Maryland, ¿cuál es la multa máxima por una primera falta de sostener el teléfono para hablar mientras maneja?","o":["$25","$75","$500","$1,000"],"h1":"Las faltas siguientes cuestan $125 y luego $175.","h2":"Según la ley de Maryland, usar un teléfono en la mano al manejar trae una multa de hasta $75 la primera vez, y ningún punto salvo que contribuya a un choque.","p":"¡Correcto! La primera falta puede costar hasta $75."},"ref":{"doc":"MD","page":null}},{"id":"md-193","scope":"MD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"Under Maryland law, a 17-year-old is caught texting while driving. For how long may the MVA suspend the license?","o":["Up to 7 days","Up to 1 year","Up to 5 years","Up to 90 days"],"h1":"It is about three months.","h2":"Under Maryland law, the MVA may suspend the license of a driver under 18 who texts while driving for up to 90 days, and may allow driving only for work or school.","p":"Right! The suspension can last up to 90 days."},"es":{"q":"Según la ley de Maryland, atrapan a una persona de 17 años enviando mensajes de texto mientras maneja. ¿Por cuánto tiempo puede la MVA suspenderle la licencia?","o":["Hasta 7 días","Hasta 1 año","Hasta 5 años","Hasta 90 días"],"h1":"Son unos tres meses.","h2":"Según la ley de Maryland, la MVA puede suspender por hasta 90 días la licencia de un conductor menor de 18 que envía mensajes al manejar, y puede permitirle manejar solo para trabajo o escuela.","p":"¡Correcto! La suspensión puede durar hasta 90 días."},"ref":{"doc":"MD","page":null}},{"id":"md-194","scope":"MD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Under Maryland law, a driver refuses an alcohol test for the first time. How long does the MVA suspend the license?","o":["270 days","30 days","90 days","5 years"],"h1":"It is longer than the 180 days for a first test result of 0.08 or more.","h2":"Under Maryland law, a first refusal to take an alcohol or drug test brings a 270-day license suspension, and a second refusal brings 2 years.","p":"Yes! A first refusal means a 270-day suspension."},"es":{"q":"Según la ley de Maryland, un conductor se niega por primera vez a una prueba de alcohol. ¿Por cuánto tiempo suspende la MVA la licencia?","o":["270 días","30 días","90 días","5 años"],"h1":"Es más que los 180 días por un primer resultado de 0.08 o más.","h2":"Según la ley de Maryland, la primera negativa a una prueba de alcohol o drogas trae 270 días de suspensión, y la segunda trae 2 años.","p":"¡Sí! La primera negativa significa 270 días de suspensión."},"ref":{"doc":"MD","page":null}},{"id":"md-195","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Maryland law, an officer takes your license after you fail or refuse an alcohol test. How long does the temporary license let you keep driving?","o":["24 hours","7 days","45 days","1 year"],"h1":"It is about a month and a half.","h2":"Under Maryland law, the officer issues a temporary license that lets you keep driving for 45 days, and you can ask for a hearing within 10 days.","p":"Correct! The temporary license lasts 45 days."},"es":{"q":"Según la ley de Maryland, un policía le quita la licencia después de que falla o se niega a una prueba de alcohol. ¿Por cuánto tiempo le permite seguir manejando la licencia temporal?","o":["24 horas","7 días","45 días","1 año"],"h1":"Es cerca de mes y medio.","h2":"Según la ley de Maryland, el policía le da una licencia temporal para seguir manejando por 45 días, y usted puede pedir una audiencia en un plazo de 10 días.","p":"¡Correcto! La licencia temporal dura 45 días."},"ref":{"doc":"MD","page":null}},{"id":"md-196","scope":"MD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Maryland law, a driver's test shows a BAC of 0.07. What does that show in court?","o":["That the driver was completely sober","Nothing at all, because it is under 0.08","That the driver was driving while impaired by alcohol","That the driver broke only a parking law"],"h1":"Maryland has a lesser alcohol offense below the 0.08 limit.","h2":"Under Maryland law, a BAC of at least 0.07 but less than 0.08 is evidence that the person was driving while impaired by alcohol.","p":"Right! 0.07 is evidence of driving while impaired."},"es":{"q":"Según la ley de Maryland, la prueba de un conductor muestra un BAC de 0.07. ¿Qué demuestra eso en el tribunal?","o":["Que estaba completamente sobrio","Nada, porque es menos de 0.08","Que manejaba con sus facultades disminuidas por el alcohol","Que violó solo una ley de estacionamiento"],"h1":"Maryland tiene una falta de alcohol menor por debajo del límite de 0.08.","h2":"Según la ley de Maryland, un BAC de al menos 0.07 pero menos de 0.08 es prueba de que la persona manejaba con sus facultades disminuidas por el alcohol.","p":"¡Correcto! 0.07 es prueba de manejar con facultades disminuidas."},"ref":{"doc":"MD","page":null}},{"id":"md-197","scope":"MD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"Under Maryland law, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is about the length of one car.","h2":"Under Maryland law, you may not stand or park a vehicle within 15 feet of a fire hydrant.","p":"Yes! Stay at least 15 feet from a fire hydrant."},"es":{"q":"Según la ley de Maryland, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 30 pies","No a menos de 50 pies"],"h1":"Es más o menos el largo de un carro.","h2":"Según la ley de Maryland, no puede detenerse ni estacionarse a menos de 15 pies de un hidrante.","p":"¡Sí! Quédese al menos a 15 pies del hidrante."},"ref":{"doc":"MD","page":null}},{"id":"md-198","scope":"MD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"Under Maryland law, how far back must you park from a stop sign on the side of the road?","o":["At least 5 feet before it","At least 10 feet before it","At least 100 feet before it","At least 30 feet before it"],"h1":"The same distance applies before a yield sign or a traffic signal.","h2":"Under Maryland law, you may not stand or park within 30 feet on the approach to a stop sign, yield sign, flashing signal or traffic signal at the side of the road.","p":"Correct! Park at least 30 feet before a stop sign."},"es":{"q":"Según la ley de Maryland, ¿a qué distancia antes de una señal de alto al lado de la vía debe estacionarse?","o":["Al menos 5 pies antes","Al menos 10 pies antes","Al menos 100 pies antes","Al menos 30 pies antes"],"h1":"La misma distancia se aplica antes de un ceda el paso o un semáforo.","h2":"Según la ley de Maryland, no puede detenerse ni estacionarse a menos de 30 pies antes de una señal de alto, de ceda el paso, una luz intermitente o un semáforo al lado de la vía.","p":"¡Correcto! Estaciónese al menos 30 pies antes de un alto."},"ref":{"doc":"MD","page":null}},{"id":"md-199","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"Under Maryland law, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 50 feet","No closer than 20 feet","No closer than 500 feet"],"h1":"It is farther than the distance from a stop sign.","h2":"Under Maryland law, you may not park a vehicle within 50 feet of the nearest rail of a railroad grade crossing.","p":"Right! Park at least 50 feet from the nearest rail."},"es":{"q":"Según la ley de Maryland, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies","No a menos de 500 pies"],"h1":"Es más que la distancia de una señal de alto.","h2":"Según la ley de Maryland, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"¡Correcto! Estaciónese al menos a 50 pies del riel más cercano."},"ref":{"doc":"MD","page":null}},{"id":"md-200","scope":"MD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"Under Maryland law, you parallel park on a two-way street. How close to the curb must your right wheels be?","o":["Within 24 inches","Within 12 inches","Within 3 feet","Touching the curb"],"h1":"It is about one foot.","h2":"Under Maryland law, a vehicle parked on a two-way road must be parallel to the right curb, with its right wheels within 12 inches of the curb or edge.","p":"Yes! Your wheels must be within 12 inches of the curb."},"es":{"q":"Según la ley de Maryland, se estaciona en paralelo en una calle de doble sentido. ¿Qué tan cerca de la acera deben quedar sus ruedas derechas?","o":["A 24 pulgadas o menos","A 12 pulgadas o menos","A 3 pies o menos","Tocando la acera"],"h1":"Es más o menos un pie.","h2":"Según la ley de Maryland, un vehículo estacionado en una vía de doble sentido debe quedar paralelo a la acera derecha, con las ruedas derechas a 12 pulgadas o menos de la acera o la orilla.","p":"¡Sí! Las ruedas deben quedar a 12 pulgadas o menos de la acera."},"ref":{"doc":"MD","page":null}},{"id":"me-001","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the intermediate license.","h2":"In Maine you can get a learner's permit at 15. If you are under 18, you must also take an approved driver education course.","p":"Right. The Maine learner's permit starts at 15."},"es":{"q":"En Maine, ¿cuál es la edad mínima para obtener el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia intermedia.","h2":"En Maine usted puede obtener el permiso de aprendiz a los 15 años. Si tiene menos de 18 años, también debe tomar un curso aprobado de educación vial.","p":"Correcto. El permiso de aprendiz en Maine empieza a los 15."},"zh":{"q":"在 Maine，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比中级驾照早一年。","h2":"在 Maine，你 15 岁就可以拿到学习驾照。如果你未满 18 岁，还必须上一门批准的驾驶教育课程。","p":"对。Maine 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Maine, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này sớm hơn một năm so với bằng lái trung gian.","h2":"Ở Maine, bạn có thể có giấy phép tập lái khi 15 tuổi. Nếu bạn dưới 18 tuổi, bạn cũng phải học một khóa giáo dục lái xe (driver education) được chấp thuận.","p":"Đúng. Giấy phép tập lái ở Maine bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Maine, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Sa Maine, puwede kang makakuha ng learner's permit sa edad na 15. Kung wala ka pang 18, dapat ka ring kumuha ng aprubadong kurso sa driver education.","p":"Tama. Nagsisimula ang learner's permit sa Maine sa edad na 15."},"ar":{"q":"في Maine، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هذا العمر قبل الرخصة المتوسطة بسنة واحدة.","h2":"في Maine يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة. وإذا كان عمرك أقل من 18 سنة، يجب أيضًا أن تأخذ دورة تعليم قيادة (driver education) معتمدة.","p":"صحيح. يبدأ تصريح تعلّم القيادة في Maine في عمر 15 سنة."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-002","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how many hours of practice driving must a permit holder under 21 log?","o":["30 hours","50 hours","70 hours","100 hours"],"h1":"It is more than in many states, but less than one hundred.","h2":"A Maine permit holder under 21 must log 70 hours of practice driving.","p":"Right. Maine asks for 70 hours."},"es":{"q":"En Maine, ¿cuántas horas de práctica de manejo debe registrar un aprendiz menor de 21 años?","o":["30 horas","50 horas","70 horas","100 horas"],"h1":"Es más que en muchos estados, pero menos de cien.","h2":"Un aprendiz en Maine menor de 21 años debe registrar 70 horas de práctica de manejo.","p":"Correcto. Maine pide 70 horas."},"zh":{"q":"在 Maine，21 岁以下持学习驾照的人必须记录多少小时的练习驾驶？","o":["30 小时","50 小时","70 小时","100 小时"],"h1":"它比很多州多，但不到一百。","h2":"在 Maine，21 岁以下持学习驾照的人必须记录 70 小时的练习驾驶。","p":"对。Maine 要求 70 小时。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải ghi lại bao nhiêu giờ tập lái?","o":["30 giờ","50 giờ","70 giờ","100 giờ"],"h1":"Số này nhiều hơn ở nhiều tiểu bang, nhưng ít hơn một trăm.","h2":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải ghi lại 70 giờ tập lái.","p":"Đúng. Maine yêu cầu 70 giờ."},"tl":{"q":"Sa Maine, ilang oras ng praktis sa pagmamaneho ang dapat itala ng may hawak ng permit na wala pang 21?","o":["30 oras","50 oras","70 oras","100 oras"],"h1":"Mas marami ito kaysa sa maraming estado, pero mas kaunti sa isang daan.","h2":"Sa Maine, ang may hawak ng permit na wala pang 21 ay dapat magtala ng 70 oras ng praktis sa pagmamaneho.","p":"Tama. Humihingi ang Maine ng 70 oras."},"ar":{"q":"في Maine، كم ساعة من التدريب على القيادة يجب أن يسجّلها حامل التصريح الذي عمره أقل من 21 سنة؟","o":["30 ساعة","50 ساعة","70 ساعة","100 ساعة"],"h1":"هذا أكثر من ولايات كثيرة، لكنه أقل من مئة.","h2":"في Maine يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يسجّل 70 ساعة من التدريب على القيادة.","p":"صحيح. تطلب Maine سبعين ساعة."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-003","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many of the 70 practice hours must be driven after dark?","o":["10 hours","5 hours","20 hours","35 hours"],"h1":"It is a round number, a small part of the total.","h2":"In Maine, 10 of the 70 practice hours must be driven after dark.","p":"Right. Ten of the hours must be after dark."},"es":{"q":"En Maine, ¿cuántas de las 70 horas de práctica deben ser después del anochecer?","o":["10 horas","5 horas","20 horas","35 horas"],"h1":"Es un número redondo, una parte pequeña del total.","h2":"En Maine, 10 de las 70 horas de práctica deben ser después del anochecer.","p":"Correcto. Diez de las horas deben ser de noche."},"zh":{"q":"在 Maine，70 小时练习中有多少小时必须在天黑以后开？","o":["10 小时","5 小时","20 小时","35 小时"],"h1":"这是一个整数，只占总数的一小部分。","h2":"在 Maine，70 小时练习中有 10 小时必须在天黑以后开。","p":"对。其中 10 小时必须在天黑以后。"},"vi":{"q":"Ở Maine, trong 70 giờ tập lái, bao nhiêu giờ phải lái sau khi trời tối?","o":["10 giờ","5 giờ","20 giờ","35 giờ"],"h1":"Đây là một số tròn, một phần nhỏ của tổng số giờ.","h2":"Ở Maine, 10 trong 70 giờ tập lái phải được lái sau khi trời tối.","p":"Đúng. Mười giờ phải lái sau khi trời tối."},"tl":{"q":"Sa Maine, ilan sa 70 oras ng praktis ang dapat gawin pagkatapos dumilim?","o":["10 oras","5 oras","20 oras","35 oras"],"h1":"Isa itong buong numero, maliit na bahagi ng kabuuan.","h2":"Sa Maine, 10 sa 70 oras ng praktis ang dapat gawin pagkatapos dumilim.","p":"Tama. Sampu sa mga oras ang dapat pagkatapos dumilim."},"ar":{"q":"في Maine، كم ساعة من ساعات التدريب السبعين يجب أن تكون بعد حلول الظلام؟","o":["10 ساعات","5 ساعات","20 ساعة","35 ساعة"],"h1":"هو رقم مستدير، وجزء صغير من المجموع.","h2":"في Maine يجب أن تكون 10 ساعات من ساعات التدريب السبعين بعد حلول الظلام.","p":"صحيح. عشر ساعات يجب أن تكون بعد حلول الظلام."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-004","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, when may the 70 practice hours start to count?","o":["At age 14","After the road test","After the first year of high school","After the learner's permit is issued"],"h1":"You need a permit to drive on the road.","h2":"In Maine, the 70 practice hours must begin after the learner's permit is issued.","p":"Right. Hours count only once you have the permit."},"es":{"q":"En Maine, ¿cuándo empiezan a contar las 70 horas de práctica?","o":["A los 14 años","Después del examen de manejo","Después del primer año de secundaria","Después de recibir el permiso de aprendiz"],"h1":"Usted necesita un permiso para manejar en la calle.","h2":"En Maine, las 70 horas de práctica deben empezar después de recibir el permiso de aprendiz.","p":"Correcto. Las horas cuentan solo cuando ya tiene el permiso."},"zh":{"q":"在 Maine，70 小时的练习从什么时候开始算？","o":["从 14 岁开始","路考以后","高中第一年以后","拿到学习驾照以后"],"h1":"你需要有学习驾照才能在路上开车。","h2":"在 Maine，70 小时的练习必须在拿到学习驾照以后才开始算。","p":"对。只有拿到学习驾照以后，练习时间才算数。"},"vi":{"q":"Ở Maine, khi nào 70 giờ tập lái bắt đầu được tính?","o":["Khi 14 tuổi","Sau bài thi lái xe trên đường","Sau năm học đầu tiên ở trung học","Sau khi được cấp giấy phép tập lái"],"h1":"Bạn cần có giấy phép mới được lái xe trên đường.","h2":"Ở Maine, 70 giờ tập lái phải bắt đầu sau khi được cấp giấy phép tập lái.","p":"Đúng. Số giờ chỉ được tính khi bạn đã có giấy phép."},"tl":{"q":"Sa Maine, kailan nagsisimulang mabilang ang 70 oras ng praktis?","o":["Sa edad na 14","Pagkatapos ng road test","Pagkatapos ng unang taon sa high school","Pagkatapos maibigay ang learner's permit"],"h1":"Kailangan mo ng permit para magmaneho sa kalsada.","h2":"Sa Maine, ang 70 oras ng praktis ay dapat magsimula pagkatapos maibigay ang learner's permit.","p":"Tama. Nabibilang lang ang mga oras kapag may permit ka na."},"ar":{"q":"في Maine، متى تبدأ ساعات التدريب السبعون في الاحتساب؟","o":["في عمر 14 سنة","بعد اختبار القيادة على الطريق","بعد السنة الأولى في المدرسة الثانوية","بعد إصدار تصريح تعلّم القيادة"],"h1":"تحتاج إلى تصريح لتقود على الطريق.","h2":"في Maine يجب أن تبدأ ساعات التدريب السبعون بعد إصدار تصريح تعلّم القيادة.","p":"صحيح. لا تُحتسب الساعات إلا بعد حصولك على التصريح."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-005","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how long must a permit holder under 21 hold the permit before the road test?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"In Maine, a permit holder under 21 must hold the permit for 6 months before applying for the road test.","p":"Right. Six months with the permit first."},"es":{"q":"En Maine, ¿cuánto tiempo debe tener el permiso un aprendiz menor de 21 años antes del examen de manejo?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"En Maine, un aprendiz menor de 21 años debe tener el permiso 6 meses antes de solicitar el examen de manejo.","p":"Correcto. Primero, seis meses con el permiso."},"zh":{"q":"在 Maine，21 岁以下持学习驾照的人，路考前必须持有学习驾照多久？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"在 Maine，21 岁以下持学习驾照的人必须先持有学习驾照 6 个月，才能申请路考。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải giữ giấy phép bao lâu trước bài thi lái xe trên đường?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Maine, người có giấy phép tập lái dưới 21 tuổi phải giữ giấy phép 6 tháng trước khi đăng ký thi lái xe trên đường.","p":"Đúng. Phải giữ giấy phép sáu tháng trước."},"tl":{"q":"Sa Maine, gaano katagal dapat hawak ng may permit na wala pang 21 ang permit bago ang road test?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Sa Maine, ang may hawak ng permit na wala pang 21 ay dapat hawak ang permit nang 6 na buwan bago mag-apply para sa road test.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في Maine، كم مدة يجب أن يحمل صاحب التصريح الذي عمره أقل من 21 سنة التصريحَ قبل اختبار القيادة على الطريق؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"إنها نصف سنة.","h2":"في Maine يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يحمل التصريح 6 أشهر قبل التقدّم لاختبار القيادة على الطريق.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-006","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how old must the supervising driver of a permit holder be?","o":["At least 16","At least 18","At least 20","At least 25"],"h1":"It is younger than in many other states.","h2":"In Maine, the supervising driver must be at least 20 years old and have held a license for at least 2 years.","p":"Right. The supervisor must be 20 or older."},"es":{"q":"En Maine, ¿qué edad debe tener el conductor que supervisa a un aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 20","Por lo menos 25"],"h1":"Es menor que en muchos otros estados.","h2":"En Maine, el conductor que supervisa debe tener por lo menos 20 años y haber tenido licencia por lo menos 2 años.","p":"Correcto. El supervisor debe tener 20 años o más."},"zh":{"q":"在 Maine，陪同持学习驾照的人开车的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 20 岁","至少 25 岁"],"h1":"它比很多其他州的要求年轻。","h2":"在 Maine，陪同的司机必须至少 20 岁，而且持有驾照至少 2 年。","p":"对。陪同的人必须 20 岁或以上。"},"vi":{"q":"Ở Maine, người lái xe giám sát người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 20 tuổi","Ít nhất 25 tuổi"],"h1":"Tuổi này trẻ hơn so với nhiều tiểu bang khác.","h2":"Ở Maine, người lái xe giám sát phải ít nhất 20 tuổi và đã có bằng lái ít nhất 2 năm.","p":"Đúng. Người giám sát phải từ 20 tuổi trở lên."},"tl":{"q":"Sa Maine, ilang taon dapat ang driver na nagbabantay sa may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 20","Hindi bababa sa 25"],"h1":"Mas bata ito kaysa sa maraming ibang estado.","h2":"Sa Maine, ang nagbabantay na driver ay dapat hindi bababa sa 20 taong gulang at may lisensya nang hindi bababa sa 2 taon.","p":"Tama. Ang nagbabantay ay dapat 20 pataas."},"ar":{"q":"في Maine، كم يجب أن يكون عمر السائق المشرف على حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","20 سنة على الأقل","25 سنة على الأقل"],"h1":"هذا العمر أصغر مما في ولايات كثيرة أخرى.","h2":"في Maine يجب أن يكون عمر السائق المشرف 20 سنة على الأقل، وأن يكون معه رخصة منذ سنتين (2) على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 20 سنة أو أكثر."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-007","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long must the supervising driver of a permit holder have held a license?","o":["At least 2 years","At least 6 months","At least 5 years","At least 10 years"],"h1":"It is a short number of years.","h2":"In Maine, the supervising driver must have held a license for at least 2 years.","p":"Right. Two years of license experience is required."},"es":{"q":"En Maine, ¿cuánto tiempo debe haber tenido licencia el conductor que supervisa a un aprendiz?","o":["Por lo menos 2 años","Por lo menos 6 meses","Por lo menos 5 años","Por lo menos 10 años"],"h1":"Es un número pequeño de años.","h2":"En Maine, el conductor que supervisa debe haber tenido licencia por lo menos 2 años.","p":"Correcto. Se requieren dos años con licencia."},"zh":{"q":"在 Maine，陪同持学习驾照的人开车的司机必须持有驾照多久？","o":["至少 2 年","至少 6 个月","至少 5 年","至少 10 年"],"h1":"只要短短几年。","h2":"在 Maine，陪同的司机必须持有驾照至少 2 年。","p":"对。需要有两年的驾照经验。"},"vi":{"q":"Ở Maine, người lái xe giám sát người có giấy phép tập lái phải có bằng lái bao lâu?","o":["Ít nhất 2 năm","Ít nhất 6 tháng","Ít nhất 5 năm","Ít nhất 10 năm"],"h1":"Đó là một số năm ít.","h2":"Ở Maine, người lái xe giám sát phải có bằng lái ít nhất 2 năm.","p":"Đúng. Cần có bằng lái ít nhất hai năm."},"tl":{"q":"Sa Maine, gaano katagal dapat may lisensya ang driver na nagbabantay sa may hawak ng permit?","o":["Hindi bababa sa 2 taon","Hindi bababa sa 6 na buwan","Hindi bababa sa 5 taon","Hindi bababa sa 10 taon"],"h1":"Kaunting taon lang ito.","h2":"Sa Maine, ang nagbabantay na driver ay dapat may lisensya nang hindi bababa sa 2 taon.","p":"Tama. Kailangan ang dalawang taon na may lisensya."},"ar":{"q":"في Maine، منذ كم مدة يجب أن يحمل السائق المشرف على حامل التصريح رخصة قيادة؟","o":["سنتان (2) على الأقل","6 أشهر على الأقل","5 سنوات على الأقل","10 سنوات على الأقل"],"h1":"إنه عدد قليل من السنوات.","h2":"في Maine يجب أن يكون السائق المشرف حاملًا لرخصة قيادة منذ سنتين (2) على الأقل.","p":"صحيح. يلزم سنتان من الخبرة برخصة القيادة."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-008","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, may a driver with a learner's permit use a cell phone while driving?","o":["Yes, if it is hands-free","No, a cell phone may not be used","Yes, at red lights","Yes, if the supervisor allows it"],"h1":"Permit holders have a stricter rule than adult drivers.","h2":"In Maine, a driver with a learner's permit may not use a cell phone while driving, not even hands-free.","p":"Right. No cell phone at all while driving on a permit."},"es":{"q":"En Maine, ¿puede un conductor con permiso de aprendiz usar el celular mientras maneja?","o":["Sí, si es de manos libres","No, no puede usar el celular","Sí, en los semáforos en rojo","Sí, si el supervisor lo permite"],"h1":"Los aprendices tienen una regla más estricta que los conductores adultos.","h2":"En Maine, un conductor con permiso de aprendiz no puede usar el celular mientras maneja, ni siquiera con manos libres.","p":"Correcto. Nada de celular al manejar con permiso de aprendiz."},"zh":{"q":"在 Maine，持学习驾照的司机开车时可以用手机吗？","o":["可以，如果是免提","不可以，不能用手机","可以，在红灯时","可以，如果陪同的人允许"],"h1":"持学习驾照的人比成年司机的规定更严格。","h2":"在 Maine，持学习驾照的司机开车时不能用手机，免提也不行。","p":"对。持学习驾照开车时，完全不能用手机。"},"vi":{"q":"Ở Maine, người có giấy phép tập lái có được dùng điện thoại di động khi lái xe không?","o":["Có, nếu không cầm tay (hands-free)","Không, không được dùng điện thoại di động","Có, khi dừng đèn đỏ","Có, nếu người giám sát cho phép"],"h1":"Người có giấy phép tập lái có quy định nghiêm hơn người lớn.","h2":"Ở Maine, người có giấy phép tập lái không được dùng điện thoại di động khi lái xe, kể cả không cầm tay (hands-free).","p":"Đúng. Không dùng điện thoại di động khi lái xe với giấy phép tập lái."},"tl":{"q":"Sa Maine, puwede bang gumamit ng cell phone habang nagmamaneho ang driver na may learner's permit?","o":["Oo, kung hands-free","Hindi, bawal gumamit ng cell phone","Oo, kapag nasa red light","Oo, kung papayag ang nagbabantay"],"h1":"Mas mahigpit ang patakaran para sa may permit kaysa sa mga adult na driver.","h2":"Sa Maine, ang driver na may learner's permit ay bawal gumamit ng cell phone habang nagmamaneho, kahit hands-free.","p":"Tama. Walang cell phone habang nagmamaneho na may permit."},"ar":{"q":"في Maine، هل يجوز للسائق الذي يحمل تصريح تعلّم القيادة استخدام الهاتف المحمول أثناء القيادة؟","o":["نعم، إذا كان بدون استخدام اليدين (hands-free)","لا، لا يجوز استخدام الهاتف المحمول","نعم، عند الإشارة الحمراء","نعم، إذا سمح المشرف بذلك"],"h1":"لحاملي التصريح قاعدة أشد من السائقين البالغين.","h2":"في Maine لا يجوز للسائق الذي يحمل تصريح تعلّم القيادة استخدام الهاتف المحمول أثناء القيادة، ولا حتى بدون استخدام اليدين (hands-free).","p":"صحيح. لا هاتف محمول أبدًا أثناء القيادة بالتصريح."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-009","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, for how long do the intermediate license restrictions last?","o":["90 days","180 days","365 days","270 days"],"h1":"It is about nine months.","h2":"In Maine, the intermediate license restrictions last 270 days from the day the license is issued.","p":"Right. The restrictions last 270 days."},"es":{"q":"En Maine, ¿cuánto duran las restricciones de la licencia intermedia?","o":["90 días","180 días","365 días","270 días"],"h1":"Son unos nueve meses.","h2":"En Maine, las restricciones de la licencia intermedia duran 270 días desde el día en que se emite la licencia.","p":"Correcto. Las restricciones duran 270 días."},"zh":{"q":"在 Maine，中级驾照的限制会持续多久？","o":["90 天","180 天","365 天","270 天"],"h1":"大约九个月。","h2":"在 Maine，中级驾照的限制从拿到驾照那天起持续 270 天。","p":"对。限制持续 270 天。"},"vi":{"q":"Ở Maine, các hạn chế của bằng lái trung gian (intermediate license) kéo dài bao lâu?","o":["90 ngày","180 ngày","365 ngày","270 ngày"],"h1":"Khoảng chín tháng.","h2":"Ở Maine, các hạn chế của bằng lái trung gian kéo dài 270 ngày kể từ ngày được cấp bằng.","p":"Đúng. Các hạn chế kéo dài 270 ngày."},"tl":{"q":"Sa Maine, gaano katagal ang mga paghihigpit ng intermediate license?","o":["90 araw","180 araw","365 araw","270 araw"],"h1":"Mga siyam na buwan ito.","h2":"Sa Maine, ang mga paghihigpit ng intermediate license ay tumatagal nang 270 araw mula sa araw na ibinigay ang lisensya.","p":"Tama. Tumatagal ang mga paghihigpit nang 270 araw."},"ar":{"q":"في Maine، كم تستمر قيود الرخصة المتوسطة (intermediate license)؟","o":["90 يومًا","180 يومًا","365 يومًا","270 يومًا"],"h1":"إنها حوالي تسعة أشهر.","h2":"في Maine تستمر قيود الرخصة المتوسطة 270 يومًا من يوم إصدار الرخصة.","p":"صحيح. تستمر القيود 270 يومًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-010","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, who may ride as a passenger with an intermediate license holder when no qualified adult driver is along?","o":["Any friends","Up to two friends","Only immediate family members","Only people over 18"],"h1":"Think of the people in your family.","h2":"In Maine, an intermediate license holder may carry only immediate family members as passengers unless a qualified licensed driver is along.","p":"Right. Only family, unless a qualified driver is along."},"es":{"q":"En Maine, ¿quién puede viajar como pasajero con el titular de una licencia intermedia cuando no va un conductor adulto calificado?","o":["Cualquier amigo","Hasta dos amigos","Solo familiares directos","Solo personas mayores de 18"],"h1":"Piense en las personas de su familia.","h2":"En Maine, el titular de una licencia intermedia puede llevar solo a familiares directos como pasajeros, salvo que vaya un conductor con licencia calificado.","p":"Correcto. Solo familiares, salvo que vaya un conductor calificado."},"zh":{"q":"在 Maine，没有合格的成年司机同车时，谁可以坐持中级驾照的人开的车？","o":["任何朋友","最多两个朋友","只有直系家人","只有 18 岁以上的人"],"h1":"想一想你家里的人。","h2":"在 Maine，持中级驾照的人只能载直系家人，除非有合格的、有驾照的司机同车。","p":"对。只能载家人，除非有合格的司机同车。"},"vi":{"q":"Ở Maine, ai được ngồi xe với người có bằng lái trung gian khi không có người lớn có bằng lái đủ điều kiện đi cùng?","o":["Bạn bè nào cũng được","Tối đa hai người bạn","Chỉ người thân trong gia đình gần","Chỉ người trên 18 tuổi"],"h1":"Hãy nghĩ đến những người trong gia đình bạn.","h2":"Ở Maine, người có bằng lái trung gian chỉ được chở người thân trong gia đình gần, trừ khi có người lái xe có bằng lái đủ điều kiện đi cùng.","p":"Đúng. Chỉ chở gia đình, trừ khi có người lái xe đủ điều kiện đi cùng."},"tl":{"q":"Sa Maine, sino ang puwedeng sumakay bilang pasahero kasama ang may intermediate license kapag walang kasamang kwalipikadong adult na driver?","o":["Kahit sinong kaibigan","Hanggang dalawang kaibigan","Mga malapit na kapamilya lang","Mga taong lampas 18 lang"],"h1":"Isipin ang mga tao sa iyong pamilya.","h2":"Sa Maine, ang may intermediate license ay puwedeng magsakay ng malalapit na kapamilya lang, maliban kung may kasamang kwalipikadong may lisensyang driver.","p":"Tama. Pamilya lang, maliban kung may kasamang kwalipikadong driver."},"ar":{"q":"في Maine، من يجوز له الركوب كراكب مع حامل الرخصة المتوسطة عندما لا يكون معه سائق بالغ مؤهَّل؟","o":["أي أصدقاء","صديقان على الأكثر","أفراد العائلة المقرّبون فقط","الأشخاص فوق 18 سنة فقط"],"h1":"فكّر في الأشخاص في عائلتك.","h2":"في Maine لا يجوز لحامل الرخصة المتوسطة أن ينقل ركّابًا إلا أفراد العائلة المقرّبين، إلا إذا كان معه سائق مؤهَّل يحمل رخصة.","p":"صحيح. العائلة فقط، إلا إذا كان معك سائق مؤهَّل."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-011","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what happens to intermediate license restrictions after a violation of those rules?","o":["Nothing changes","They are extended by another 270 days","They end right away","They become a fine only"],"h1":"Breaking the rules makes them last longer.","h2":"In Maine, a driver who breaks the intermediate license rules has the restrictions extended by another 270 days.","p":"Right. A violation adds 270 more days."},"es":{"q":"En Maine, ¿qué pasa con las restricciones de la licencia intermedia después de violar esas reglas?","o":["No cambia nada","Se extienden por otros 270 días","Terminan de inmediato","Se convierten solo en una multa"],"h1":"Violar las reglas hace que duren más.","h2":"En Maine, a un conductor que viola las reglas de la licencia intermedia se le extienden las restricciones por otros 270 días.","p":"Correcto. Una violación agrega 270 días más."},"zh":{"q":"在 Maine，违反中级驾照的规定以后，这些限制会怎样？","o":["什么都不变","再延长 270 天","马上结束","只要罚款"],"h1":"违反规定会让限制持续更久。","h2":"在 Maine，违反中级驾照规定的司机，限制会再延长 270 天。","p":"对。违规会再加 270 天。"},"vi":{"q":"Ở Maine, điều gì xảy ra với các hạn chế của bằng lái trung gian khi vi phạm các quy định đó?","o":["Không có gì thay đổi","Bị kéo dài thêm 270 ngày","Kết thúc ngay lập tức","Chỉ còn là tiền phạt"],"h1":"Vi phạm quy định làm các hạn chế kéo dài lâu hơn.","h2":"Ở Maine, người lái xe vi phạm quy định của bằng lái trung gian sẽ bị kéo dài các hạn chế thêm 270 ngày.","p":"Đúng. Một lần vi phạm thêm 270 ngày nữa."},"tl":{"q":"Sa Maine, ano ang nangyayari sa mga paghihigpit ng intermediate license kapag nilabag ang mga patakarang iyon?","o":["Walang nagbabago","Pinahahaba pa nang 270 araw","Natatapos agad","Multa na lang"],"h1":"Kapag lumabag ka, mas tatagal ang mga ito.","h2":"Sa Maine, ang driver na lumabag sa mga patakaran ng intermediate license ay pinahahaba ang mga paghihigpit nang 270 araw pa.","p":"Tama. Isang paglabag ay nagdadagdag ng 270 araw."},"ar":{"q":"في Maine، ماذا يحدث لقيود الرخصة المتوسطة بعد مخالفة تلك القواعد؟","o":["لا يتغيّر شيء","تُمدَّد 270 يومًا أخرى","تنتهي فورًا","تصبح غرامة فقط"],"h1":"مخالفة القواعد تجعلها تستمر مدة أطول.","h2":"في Maine السائق الذي يخالف قواعد الرخصة المتوسطة تُمدَّد قيوده 270 يومًا أخرى.","p":"صحيح. المخالفة تضيف 270 يومًا أخرى."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-012","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, how may an adult driver make a phone call while driving?","o":["Hands-free, without holding the phone","Holding the phone to the ear","Only by texting","Holding the phone at a stop sign"],"h1":"Your hands stay off the device.","h2":"In Maine, a driver 18 or older with a full license may not hold a phone while driving, but may make calls hands-free.","p":"Right. Maine bans holding the phone while driving."},"es":{"q":"En Maine, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con manos libres, sin sostener el teléfono","Sosteniendo el teléfono en el oído","Solo con mensajes de texto","Sosteniendo el teléfono en una señal de alto"],"h1":"Sus manos no tocan el aparato.","h2":"En Maine, un conductor de 18 años o más con licencia completa no puede sostener el teléfono mientras maneja, pero puede hacer llamadas con manos libres.","p":"Correcto. Maine prohíbe sostener el teléfono al manejar."},"zh":{"q":"在 Maine，成年司机开车时可以怎样打电话？","o":["用免提，不拿着手机","把手机拿到耳边","只能发短信","在停车标志前拿着手机"],"h1":"你的手不碰这个设备。","h2":"在 Maine，18 岁或以上、持正式驾照的司机开车时不能手拿手机，但可以用免提打电话。","p":"对。Maine 禁止开车时手拿手机。"},"vi":{"q":"Ở Maine, người lớn có thể gọi điện thoại khi lái xe bằng cách nào?","o":["Không cầm tay (hands-free), không cầm điện thoại","Cầm điện thoại áp vào tai","Chỉ bằng cách nhắn tin","Cầm điện thoại khi dừng ở biển STOP"],"h1":"Tay bạn không chạm vào thiết bị.","h2":"Ở Maine, người lái xe từ 18 tuổi trở lên có bằng lái đầy đủ không được cầm điện thoại khi lái xe, nhưng có thể gọi điện không cầm tay (hands-free).","p":"Đúng. Maine cấm cầm điện thoại khi lái xe."},"tl":{"q":"Sa Maine, paano puwedeng tumawag sa telepono ang adult na driver habang nagmamaneho?","o":["Hands-free, nang hindi hawak ang telepono","Hawak ang telepono sa tainga","Sa pag-text lang","Hawak ang telepono sa STOP sign"],"h1":"Hindi hawak ng iyong mga kamay ang device.","h2":"Sa Maine, ang driver na 18 pataas na may buong lisensya ay bawal humawak ng telepono habang nagmamaneho, pero puwedeng tumawag nang hands-free.","p":"Tama. Bawal sa Maine ang paghawak ng telepono habang nagmamaneho."},"ar":{"q":"في Maine، كيف يمكن للسائق البالغ أن يجري مكالمة هاتفية أثناء القيادة؟","o":["بدون استخدام اليدين (hands-free)، دون حمل الهاتف","بحمل الهاتف على الأذن","بالرسائل النصية فقط","بحمل الهاتف عند علامة STOP"],"h1":"يداك تبقيان بعيدتين عن الجهاز.","h2":"في Maine لا يجوز للسائق الذي عمره 18 سنة أو أكثر ويحمل رخصة كاملة أن يمسك الهاتف أثناء القيادة، لكن يمكنه إجراء المكالمات بدون استخدام اليدين (hands-free).","p":"صحيح. تمنع Maine إمساك الهاتف أثناء القيادة."},"ref":{"doc":"ME","page":null}},{"id":"me-013","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, what happens to a driver under 21 found driving with any measurable amount of alcohol?","o":["Only a warning","A 30-day suspension","Nothing, if below 0.08 percent","The license is suspended for at least one year"],"h1":"Maine has zero tolerance for young drivers.","h2":"In Maine, a driver under 21 with any amount of alcohol loses the license for at least one year.","p":"Right. Under 21, any alcohol means losing the license for at least a year."},"es":{"q":"En Maine, ¿qué le pasa a un conductor menor de 21 años que maneja con cualquier cantidad medible de alcohol?","o":["Solo una advertencia","Una suspensión de 30 días","Nada, si está por debajo de 0.08 por ciento","Se le suspende la licencia por al menos un año"],"h1":"Maine tiene tolerancia cero para los conductores jóvenes.","h2":"En Maine, un conductor menor de 21 años con cualquier cantidad de alcohol pierde la licencia por al menos un año.","p":"Correcto. Menor de 21, cualquier alcohol significa perder la licencia por al menos un año."},"zh":{"q":"在 Maine，21 岁以下的司机开车时被查出体内有任何可测量的酒精，会怎样？","o":["只是警告","暂停驾照 30 天","如果低于 0.08% 就没事","驾照被暂停至少一年"],"h1":"Maine 对年轻司机实行零容忍。","h2":"在 Maine，21 岁以下的司机只要体内有任何酒精，就会失去驾照至少一年。","p":"对。21 岁以下，只要有酒精，就会失去驾照至少一年。"},"vi":{"q":"Ở Maine, điều gì xảy ra với người lái xe dưới 21 tuổi bị phát hiện lái xe có bất kỳ lượng cồn nào đo được?","o":["Chỉ bị cảnh cáo","Bị đình chỉ 30 ngày","Không có gì, nếu dưới 0.08 phần trăm","Bằng lái bị đình chỉ ít nhất một năm"],"h1":"Maine không khoan nhượng (zero tolerance) với tài xế trẻ.","h2":"Ở Maine, người lái xe dưới 21 tuổi có bất kỳ lượng cồn nào sẽ mất bằng lái ít nhất một năm.","p":"Đúng. Dưới 21 tuổi, có chút cồn nào cũng mất bằng lái ít nhất một năm."},"tl":{"q":"Sa Maine, ano ang mangyayari sa driver na wala pang 21 na nahuling nagmamaneho na may kahit kaunting alak na nasusukat?","o":["Babala lang","30 araw na suspensyon","Wala, kung mas mababa sa 0.08 porsyento","Masususpinde ang lisensya nang hindi bababa sa isang taon"],"h1":"Zero tolerance ang Maine para sa mga batang driver.","h2":"Sa Maine, ang driver na wala pang 21 na may kahit anong dami ng alak ay mawawalan ng lisensya nang hindi bababa sa isang taon.","p":"Tama. Wala pang 21, kahit kaunting alak ay pagkawala ng lisensya nang hindi bababa sa isang taon."},"ar":{"q":"في Maine، ماذا يحدث للسائق الذي عمره أقل من 21 سنة إذا وُجد يقود مع أي كمية كحول يمكن قياسها؟","o":["تحذير فقط","إيقاف الرخصة 30 يومًا","لا شيء، إذا كانت أقل من 0.08 بالمئة","تُوقف الرخصة سنة واحدة على الأقل"],"h1":"Maine لا تتسامح أبدًا (zero tolerance) مع السائقين الشباب.","h2":"في Maine السائق الذي عمره أقل من 21 سنة ومعه أي كمية من الكحول يفقد رخصته سنة واحدة على الأقل.","p":"صحيح. تحت 21 سنة، أي كمية كحول تعني فقدان الرخصة سنة على الأقل."},"ref":{"doc":"ME","page":"3-14"}},{"id":"me-014","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, during which hours may a newly licensed driver under 18 not drive?","o":["From 9 p.m. to 5 a.m.","From 10 p.m. to 6 a.m.","From 12 a.m. to 5 a.m.","From 1 a.m. to 6 a.m."],"h1":"The limit starts at midnight.","h2":"In Maine, a licensed driver under 18 may not drive between 12 a.m. and 5 a.m. during the first 270 days.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Maine, ¿en qué horario no puede manejar un conductor menor de 18 años con licencia nueva?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 12 a.m. a 5 a.m.","De 1 a.m. a 6 a.m."],"h1":"El límite empieza a la medianoche.","h2":"En Maine, un conductor con licencia menor de 18 años no puede manejar entre las 12 a.m. y las 5 a.m. durante los primeros 270 días.","p":"Correcto. No se maneja de la medianoche a las 5 a.m."},"zh":{"q":"在 Maine，18 岁以下刚拿到驾照的司机在哪些时间不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","午夜 12 点到早上 5 点","凌晨 1 点到早上 6 点"],"h1":"这个限制从午夜开始。","h2":"在 Maine，18 岁以下有驾照的司机在头 270 天里，午夜 12 点到早上 5 点之间不能开车。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Maine, người lái xe dưới 18 tuổi mới có bằng lái không được lái xe vào những giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 12 giờ đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu lúc nửa đêm.","h2":"Ở Maine, người lái xe dưới 18 tuổi có bằng lái không được lái xe từ 12 giờ đêm đến 5 giờ sáng trong 270 ngày đầu tiên.","p":"Đúng. Không được lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Maine, anong oras bawal magmaneho ang bagong lisensyadong driver na wala pang 18?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m.","Mula 12 a.m. hanggang 5 a.m.","Mula 1 a.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon sa hatinggabi.","h2":"Sa Maine, ang lisensyadong driver na wala pang 18 ay bawal magmaneho mula 12 a.m. hanggang 5 a.m. sa unang 270 araw.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Maine، في أي ساعات لا يجوز للسائق الجديد الذي عمره أقل من 18 سنة أن يقود؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 12 منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 6 صباحًا"],"h1":"يبدأ المنع عند منتصف الليل.","h2":"في Maine لا يجوز للسائق الذي يحمل رخصة وعمره أقل من 18 سنة أن يقود بين 12 منتصف الليل و5 صباحًا خلال أول 270 يومًا.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-015","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long is the first license of a new driver under 21 provisional?","o":["2 years","6 months","1 year","3 years"],"h1":"It is longer than for a new driver who is 21 or older.","h2":"In Maine, the first license of a new driver under 21 is provisional for 2 years. For a new driver 21 or older, it is 1 year.","p":"Right. The provisional period is 2 years for drivers under 21."},"es":{"q":"En Maine, ¿por cuánto tiempo es provisional la primera licencia de un conductor nuevo menor de 21 años?","o":["2 años","6 meses","1 año","3 años"],"h1":"Es más tiempo que para un conductor nuevo de 21 años o más.","h2":"En Maine, la primera licencia de un conductor nuevo menor de 21 años es provisional por 2 años. Para un conductor nuevo de 21 años o más, es 1 año.","p":"Correcto. El periodo provisional es de 2 años para menores de 21."},"zh":{"q":"在 Maine，21 岁以下新司机的第一张驾照是临时驾照（provisional）多久？","o":["2 年","6 个月","1 年","3 年"],"h1":"它比 21 岁或以上的新司机更长。","h2":"在 Maine，21 岁以下新司机的第一张驾照有 2 年是临时驾照。21 岁或以上的新司机是 1 年。","p":"对。21 岁以下的司机，临时期是 2 年。"},"vi":{"q":"Ở Maine, bằng lái đầu tiên của người lái xe mới dưới 21 tuổi là bằng tạm thời (provisional) trong bao lâu?","o":["2 năm","6 tháng","1 năm","3 năm"],"h1":"Thời gian này dài hơn so với người lái xe mới từ 21 tuổi trở lên.","h2":"Ở Maine, bằng lái đầu tiên của người lái xe mới dưới 21 tuổi là bằng tạm thời trong 2 năm. Với người lái xe mới từ 21 tuổi trở lên, thời gian là 1 năm.","p":"Đúng. Thời gian tạm thời là 2 năm cho người lái xe dưới 21 tuổi."},"tl":{"q":"Sa Maine, gaano katagal provisional ang unang lisensya ng bagong driver na wala pang 21?","o":["2 taon","6 na buwan","1 taon","3 taon"],"h1":"Mas matagal ito kaysa sa bagong driver na 21 pataas.","h2":"Sa Maine, ang unang lisensya ng bagong driver na wala pang 21 ay provisional nang 2 taon. Para sa bagong driver na 21 pataas, 1 taon ito.","p":"Tama. 2 taon ang provisional na panahon para sa mga driver na wala pang 21."},"ar":{"q":"في Maine، كم مدة تكون الرخصة الأولى للسائق الجديد الذي عمره أقل من 21 سنة رخصة مؤقتة (provisional)؟","o":["سنتان (2)","6 أشهر","سنة واحدة (1)","3 سنوات"],"h1":"هذه المدة أطول منها للسائق الجديد الذي عمره 21 سنة أو أكثر.","h2":"في Maine تكون الرخصة الأولى للسائق الجديد الذي عمره أقل من 21 سنة رخصة مؤقتة لمدة سنتين (2). أما للسائق الجديد الذي عمره 21 سنة أو أكثر فالمدة سنة واحدة (1).","p":"صحيح. المدة المؤقتة سنتان (2) للسائقين الذين أعمارهم أقل من 21 سنة."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-016","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what happens the first time a driver with a provisional license is convicted of a moving violation?","o":["Only a written warning","A 10-day suspension","A 1-year suspension","A 30-day suspension"],"h1":"It is about one month without driving.","h2":"In Maine, a first moving violation on a provisional license leads to a 30-day license suspension. Later offenses bring tougher penalties.","p":"Right. The license is suspended for 30 days."},"es":{"q":"En Maine, ¿qué pasa la primera vez que un conductor con licencia provisional es condenado por una infracción de tránsito en movimiento?","o":["Solo una advertencia escrita","Una suspensión de 10 días","Una suspensión de 1 año","Una suspensión de 30 días"],"h1":"Es como un mes sin manejar.","h2":"En Maine, una primera infracción en movimiento con licencia provisional lleva a una suspensión de la licencia por 30 días. Las siguientes infracciones tienen castigos más duros.","p":"Correcto. La licencia se suspende por 30 días."},"zh":{"q":"在 Maine，持临时驾照的司机第一次因行车违规被定罪，会怎样？","o":["只有书面警告","暂停驾照 10 天","暂停驾照 1 年","暂停驾照 30 天"],"h1":"大约一个月不能开车。","h2":"在 Maine，持临时驾照的人第一次行车违规，驾照会被暂停 30 天。以后再违规，处罚会更重。","p":"对。驾照被暂停 30 天。"},"vi":{"q":"Ở Maine, điều gì xảy ra khi người có bằng lái tạm thời (provisional) bị kết tội vi phạm khi đang lái xe lần đầu tiên?","o":["Chỉ bị cảnh cáo bằng văn bản","Bị đình chỉ 10 ngày","Bị đình chỉ 1 năm","Bị đình chỉ 30 ngày"],"h1":"Khoảng một tháng không được lái xe.","h2":"Ở Maine, vi phạm khi đang lái xe lần đầu với bằng lái tạm thời sẽ bị đình chỉ bằng lái 30 ngày. Các lần vi phạm sau sẽ bị phạt nặng hơn.","p":"Đúng. Bằng lái bị đình chỉ 30 ngày."},"tl":{"q":"Sa Maine, ano ang mangyayari sa unang beses na mahatulan ang driver na may provisional license ng moving violation?","o":["Nakasulat na babala lang","10 araw na suspensyon","1 taon na suspensyon","30 araw na suspensyon"],"h1":"Mga isang buwan ito na walang pagmamaneho.","h2":"Sa Maine, ang unang moving violation sa provisional license ay nagdudulot ng 30 araw na suspensyon ng lisensya. Mas mabigat ang parusa sa mga susunod na paglabag.","p":"Tama. Masususpinde ang lisensya nang 30 araw."},"ar":{"q":"في Maine، ماذا يحدث في المرة الأولى التي يُدان فيها سائق يحمل رخصة مؤقتة (provisional) بمخالفة أثناء القيادة؟","o":["تحذير مكتوب فقط","إيقاف الرخصة 10 أيام","إيقاف الرخصة سنة واحدة (1)","إيقاف الرخصة 30 يومًا"],"h1":"إنها حوالي شهر واحد بدون قيادة.","h2":"في Maine تؤدي أول مخالفة أثناء القيادة برخصة مؤقتة إلى إيقاف الرخصة 30 يومًا. والمخالفات التالية عقوبتها أشد.","p":"صحيح. تُوقف الرخصة 30 يومًا."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-017","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how many demerit points lead to a license suspension?","o":["6 points","12 points","18 points","24 points"],"h1":"A warning comes at half this number.","h2":"In Maine, a driver whose record reaches 12 or more demerit points has the license suspended. A warning is sent at 6 points.","p":"Right. 12 points means a suspension."},"es":{"q":"En Maine, ¿cuántos puntos de demérito llevan a la suspensión de la licencia?","o":["6 puntos","12 puntos","18 puntos","24 puntos"],"h1":"Se envía una advertencia a la mitad de este número.","h2":"En Maine, si el récord de un conductor llega a 12 puntos de demérito o más, su licencia se suspende. Se envía una advertencia a los 6 puntos.","p":"Correcto. 12 puntos significan una suspensión."},"zh":{"q":"在 Maine，多少扣分（demerit points）会导致驾照被暂停？","o":["6 分","12 分","18 分","24 分"],"h1":"到这个数字的一半时会收到警告。","h2":"在 Maine，司机的记录达到 12 分或更多，驾照就会被暂停。到 6 分时会寄来警告。","p":"对。12 分就会被暂停驾照。"},"vi":{"q":"Ở Maine, bao nhiêu điểm phạt (demerit points) thì bị đình chỉ bằng lái?","o":["6 điểm","12 điểm","18 điểm","24 điểm"],"h1":"Bạn bị cảnh cáo khi có một nửa số điểm này.","h2":"Ở Maine, người lái xe có hồ sơ từ 12 điểm phạt trở lên sẽ bị đình chỉ bằng lái. Thư cảnh cáo được gửi khi có 6 điểm.","p":"Đúng. 12 điểm thì bị đình chỉ."},"tl":{"q":"Sa Maine, ilang demerit point ang nagdudulot ng suspensyon ng lisensya?","o":["6 na puntos","12 puntos","18 puntos","24 na puntos"],"h1":"May babala sa kalahati ng numerong ito.","h2":"Sa Maine, ang driver na umabot sa 12 o higit pang demerit point sa record ay masususpinde ang lisensya. May babalang ipinapadala sa 6 na puntos.","p":"Tama. Ang 12 puntos ay suspensyon."},"ar":{"q":"في Maine، كم نقطة مخالفة (demerit points) تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط","12 نقطة","18 نقطة","24 نقطة"],"h1":"يأتي التحذير عند نصف هذا العدد.","h2":"في Maine السائق الذي يصل سجله إلى 12 نقطة مخالفة أو أكثر تُوقف رخصته. ويُرسَل تحذير عند 6 نقاط.","p":"صحيح. 12 نقطة تعني إيقاف الرخصة."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-018","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, when are demerit points removed from a driver's record?","o":["After 6 months","Never","When they are one year old","After 5 years"],"h1":"Points in Maine do not last long.","h2":"In Maine, demerit points are removed from a driver's record when they are one year old.","p":"Right. Points drop off after one year."},"es":{"q":"En Maine, ¿cuándo se borran los puntos de demérito del récord de un conductor?","o":["Después de 6 meses","Nunca","Cuando cumplen un año","Después de 5 años"],"h1":"En Maine los puntos no duran mucho.","h2":"En Maine, los puntos de demérito se borran del récord del conductor cuando cumplen un año.","p":"Correcto. Los puntos se borran después de un año."},"zh":{"q":"在 Maine，扣分什么时候会从司机的记录中删除？","o":["6 个月以后","永远不会","满一年的时候","5 年以后"],"h1":"Maine 的扣分不会保留很久。","h2":"在 Maine，扣分满一年时就会从司机的记录中删除。","p":"对。扣分一年后就会删除。"},"vi":{"q":"Ở Maine, khi nào điểm phạt được xóa khỏi hồ sơ của người lái xe?","o":["Sau 6 tháng","Không bao giờ","Khi điểm đã được một năm","Sau 5 năm"],"h1":"Điểm phạt ở Maine không giữ lâu.","h2":"Ở Maine, điểm phạt được xóa khỏi hồ sơ của người lái xe khi điểm đã được một năm.","p":"Đúng. Điểm phạt được xóa sau một năm."},"tl":{"q":"Sa Maine, kailan inaalis ang demerit point sa record ng driver?","o":["Pagkatapos ng 6 na buwan","Hindi kailanman","Kapag isang taon na ang mga ito","Pagkatapos ng 5 taon"],"h1":"Hindi nagtatagal ang mga puntos sa Maine.","h2":"Sa Maine, inaalis ang demerit point sa record ng driver kapag isang taon na ang mga ito.","p":"Tama. Nawawala ang mga puntos pagkatapos ng isang taon."},"ar":{"q":"في Maine، متى تُحذف نقاط المخالفة من سجل السائق؟","o":["بعد 6 أشهر","لا تُحذف أبدًا","عندما يمر عليها سنة واحدة","بعد 5 سنوات"],"h1":"النقاط في Maine لا تبقى مدة طويلة.","h2":"في Maine تُحذف نقاط المخالفة من سجل السائق عندما يمر عليها سنة واحدة.","p":"صحيح. تُحذف النقاط بعد سنة واحدة."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-019","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many points are taken off a driver's record for finishing an approved driver improvement course?","o":["3 points","1 point","6 points","All points"],"h1":"It is a small number, and it can happen only once in 12 months.","h2":"In Maine, finishing the Maine Driving Dynamics Course or another approved driver improvement course takes 3 points off your total, once in any 12 months.","p":"Right. The course removes 3 points."},"es":{"q":"En Maine, ¿cuántos puntos se quitan del récord por terminar un curso aprobado de mejoramiento para conductores?","o":["3 puntos","1 punto","6 puntos","Todos los puntos"],"h1":"Es un número pequeño y solo se puede hacer una vez cada 12 meses.","h2":"En Maine, terminar el curso Maine Driving Dynamics u otro curso aprobado de mejoramiento le quita 3 puntos de su total, una vez en cualquier periodo de 12 meses.","p":"Correcto. El curso quita 3 puntos."},"zh":{"q":"在 Maine，完成一门批准的驾驶改进课程，可以从司机的记录中减掉几分？","o":["3 分","1 分","6 分","全部的分"],"h1":"这是一个小数字，而且 12 个月里只能有一次。","h2":"在 Maine，完成 Maine Driving Dynamics Course 或其他批准的驾驶改进课程，可以从总分中减掉 3 分，任何 12 个月内只能一次。","p":"对。这门课程可以减掉 3 分。"},"vi":{"q":"Ở Maine, hoàn thành một khóa cải thiện kỹ năng lái xe được chấp thuận sẽ được trừ bao nhiêu điểm trong hồ sơ của người lái xe?","o":["3 điểm","1 điểm","6 điểm","Tất cả các điểm"],"h1":"Đó là một số nhỏ, và chỉ được một lần trong 12 tháng.","h2":"Ở Maine, hoàn thành Maine Driving Dynamics Course hoặc một khóa cải thiện kỹ năng lái xe khác được chấp thuận sẽ trừ 3 điểm trong tổng số điểm của bạn, một lần trong bất kỳ 12 tháng nào.","p":"Đúng. Khóa học trừ 3 điểm."},"tl":{"q":"Sa Maine, ilang puntos ang inaalis sa record ng driver kapag natapos ang aprubadong driver improvement course?","o":["3 puntos","1 punto","6 na puntos","Lahat ng puntos"],"h1":"Maliit na numero ito, at isang beses lang puwede sa loob ng 12 buwan.","h2":"Sa Maine, ang pagtatapos ng Maine Driving Dynamics Course o ibang aprubadong driver improvement course ay nag-aalis ng 3 puntos sa iyong kabuuan, isang beses sa anumang 12 buwan.","p":"Tama. Nag-aalis ang kurso ng 3 puntos."},"ar":{"q":"في Maine، كم نقطة تُحذف من سجل السائق عند إنهاء دورة معتمدة لتحسين القيادة؟","o":["3 نقاط","نقطة واحدة (1)","6 نقاط","كل النقاط"],"h1":"إنه عدد صغير، ولا يمكن أن يحدث إلا مرة واحدة في 12 شهرًا.","h2":"في Maine إنهاء دورة Maine Driving Dynamics Course أو دورة أخرى معتمدة لتحسين القيادة يحذف 3 نقاط من مجموع نقاطك، مرة واحدة في أي 12 شهرًا.","p":"صحيح. الدورة تحذف 3 نقاط."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-020","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, how soon must you tell the Bureau of Motor Vehicles that your name or address has changed?","o":["Within 7 days","Within 10 days","Within 90 days","Within 30 days"],"h1":"You have about one month.","h2":"In Maine, you must tell the Bureau of Motor Vehicles within 30 days after your name or address changes.","p":"Right. You have 30 days to report the change."},"es":{"q":"En Maine, ¿en cuánto tiempo debe avisar a la Oficina de Vehículos Motorizados (BMV) si cambió su nombre o dirección?","o":["En 7 días","En 10 días","En 90 días","En 30 días"],"h1":"Tiene más o menos un mes.","h2":"En Maine, usted debe avisar a la Oficina de Vehículos Motorizados (BMV) dentro de los 30 días después de cambiar su nombre o dirección.","p":"Correcto. Tiene 30 días para avisar del cambio."},"zh":{"q":"在 Maine，你的名字或地址改变后，必须在多久内告诉 Bureau of Motor Vehicles（机动车管理局）？","o":["7 天内","10 天内","90 天内","30 天内"],"h1":"你大约有一个月的时间。","h2":"在 Maine，你的名字或地址改变后，必须在 30 天内告诉 Bureau of Motor Vehicles。","p":"对。你有 30 天的时间报告这个改变。"},"vi":{"q":"Ở Maine, bạn phải báo cho Bureau of Motor Vehicles (Sở Xe Cơ Giới) trong bao lâu khi bạn đổi tên hoặc địa chỉ?","o":["Trong vòng 7 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày","Trong vòng 30 ngày"],"h1":"Bạn có khoảng một tháng.","h2":"Ở Maine, bạn phải báo cho Bureau of Motor Vehicles trong vòng 30 ngày sau khi bạn đổi tên hoặc địa chỉ.","p":"Đúng. Bạn có 30 ngày để báo thay đổi."},"tl":{"q":"Sa Maine, gaano kabilis mo dapat sabihin sa Bureau of Motor Vehicles na nagbago ang pangalan o address mo?","o":["Sa loob ng 7 araw","Sa loob ng 10 araw","Sa loob ng 90 araw","Sa loob ng 30 araw"],"h1":"Mga isang buwan ang mayroon ka.","h2":"Sa Maine, dapat mong sabihin sa Bureau of Motor Vehicles sa loob ng 30 araw pagkatapos magbago ang pangalan o address mo.","p":"Tama. May 30 araw ka para iulat ang pagbabago."},"ar":{"q":"في Maine، خلال كم من الوقت يجب أن تُبلغ Bureau of Motor Vehicles (مكتب المركبات) بأن اسمك أو عنوانك قد تغيّر؟","o":["خلال 7 أيام","خلال 10 أيام","خلال 90 يومًا","خلال 30 يومًا"],"h1":"لديك حوالي شهر واحد.","h2":"في Maine يجب أن تُبلغ Bureau of Motor Vehicles خلال 30 يومًا بعد تغيّر اسمك أو عنوانك.","p":"صحيح. لديك 30 يومًا للإبلاغ عن التغيير."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-021","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, an adult is convicted of OUI for the first time with an alcohol level of 0.08 to 0.14. How long is the license lost?","o":["At least 30 days","At least 150 days","At least 2 years","At least 5 years"],"h1":"It is about five months.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.08 to 0.14 means losing the license for at least 150 days, plus a fine of at least $500.","p":"Right. The license is lost for at least 150 days."},"es":{"q":"En Maine, un adulto es condenado por primera vez por manejar bajo la influencia (OUI) con un nivel de alcohol de 0.08 a 0.14. ¿Por cuánto tiempo pierde la licencia?","o":["Por lo menos 30 días","Por lo menos 150 días","Por lo menos 2 años","Por lo menos 5 años"],"h1":"Son como cinco meses.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14 significa perder la licencia por lo menos 150 días, además de una multa de por lo menos $500.","p":"Correcto. Se pierde la licencia por lo menos 150 días."},"zh":{"q":"在 Maine，一个成年人第一次因酒后或药后驾驶（OUI）被定罪，酒精浓度是 0.08 到 0.14。会失去驾照多久？","o":["至少 30 天","至少 150 天","至少 2 年","至少 5 年"],"h1":"大约五个月。","h2":"在 Maine，第一次 OUI 定罪、酒精浓度 0.08 到 0.14，会失去驾照至少 150 天，还要罚款至少 $500。","p":"对。驾照会失去至少 150 天。"},"vi":{"q":"Ở Maine, một người lớn bị kết tội lái xe khi say rượu hoặc dùng chất kích thích (OUI) lần đầu với nồng độ cồn từ 0.08 đến 0.14. Bằng lái bị mất bao lâu?","o":["Ít nhất 30 ngày","Ít nhất 150 ngày","Ít nhất 2 năm","Ít nhất 5 năm"],"h1":"Khoảng năm tháng.","h2":"Ở Maine, bị kết tội OUI lần đầu với nồng độ cồn từ 0.08 đến 0.14 sẽ mất bằng lái ít nhất 150 ngày, cộng với tiền phạt ít nhất $500.","p":"Đúng. Bằng lái bị mất ít nhất 150 ngày."},"tl":{"q":"Sa Maine, nahatulan ang isang adult ng OUI (pagmamaneho nang lasing o lango) sa unang pagkakataon na may alcohol level na 0.08 hanggang 0.14. Gaano katagal mawawala ang lisensya?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 150 araw","Hindi bababa sa 2 taon","Hindi bababa sa 5 taon"],"h1":"Mga limang buwan ito.","h2":"Sa Maine, ang unang hatol ng OUI na may alcohol level na 0.08 hanggang 0.14 ay nangangahulugang mawawala ang lisensya nang hindi bababa sa 150 araw, at multang hindi bababa sa $500.","p":"Tama. Mawawala ang lisensya nang hindi bababa sa 150 araw."},"ar":{"q":"في Maine، أُدين شخص بالغ لأول مرة بالقيادة تحت تأثير الكحول أو المخدرات (OUI) ونسبة الكحول عنده من 0.08 إلى 0.14. كم مدة يفقد الرخصة؟","o":["30 يومًا على الأقل","150 يومًا على الأقل","سنتان (2) على الأقل","5 سنوات على الأقل"],"h1":"إنها حوالي خمسة أشهر.","h2":"في Maine أول إدانة بـ OUI مع نسبة كحول من 0.08 إلى 0.14 تعني فقدان الرخصة 150 يومًا على الأقل، بالإضافة إلى غرامة لا تقل عن $500.","p":"صحيح. يفقد الرخصة 150 يومًا على الأقل."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-022","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, when must the drivers in a crash report it to the police or sheriff?","o":["Only if a car must be towed","Only if a driver gets a ticket","If anyone is hurt or damage is $2,000 or more","If damage is $500 or more"],"h1":"Think about injuries and the cost of the damage.","h2":"In Maine, a crash must be reported to the police or sheriff if anyone is hurt or if the property damage is $2,000 or more.","p":"Right. Injury or $2,000 in damage means you must report it."},"es":{"q":"En Maine, ¿cuándo deben los conductores de un choque reportarlo a la policía o al sheriff?","o":["Solo si hay que remolcar un carro","Solo si un conductor recibe una multa","Si alguien sale herido o el daño es de $2,000 o más","Si el daño es de $500 o más"],"h1":"Piense en los heridos y en el costo del daño.","h2":"En Maine, un choque se debe reportar a la policía o al sheriff si alguien sale herido o si el daño a la propiedad es de $2,000 o más.","p":"Correcto. Con heridos o $2,000 de daño, hay que reportarlo."},"zh":{"q":"在 Maine，发生车祸后，司机在什么情况下必须向警察或警长（sheriff）报告？","o":["只有车子必须被拖走时","只有司机拿到罚单时","有人受伤，或损失达到 $2,000 或更多时","损失达到 $500 或更多时"],"h1":"想一想受伤和损失的费用。","h2":"在 Maine，如果有人受伤，或者财产损失达到 $2,000 或更多，就必须向警察或警长报告车祸。","p":"对。有人受伤或损失达到 $2,000，就必须报告。"},"vi":{"q":"Ở Maine, khi nào những người lái xe trong một vụ tai nạn phải báo cho cảnh sát hoặc cảnh sát quận (sheriff)?","o":["Chỉ khi xe phải bị kéo đi","Chỉ khi một người lái xe bị phạt","Nếu có người bị thương hoặc thiệt hại từ $2,000 trở lên","Nếu thiệt hại từ $500 trở lên"],"h1":"Hãy nghĩ đến người bị thương và chi phí thiệt hại.","h2":"Ở Maine, phải báo vụ tai nạn cho cảnh sát hoặc cảnh sát quận nếu có người bị thương hoặc nếu thiệt hại tài sản từ $2,000 trở lên.","p":"Đúng. Có người bị thương hoặc thiệt hại $2,000 thì bạn phải báo."},"tl":{"q":"Sa Maine, kailan dapat iulat ng mga driver sa isang banggaan ito sa pulis o sheriff?","o":["Kung kailangang i-tow ang kotse lang","Kung may driver na na-ticket lang","Kung may nasaktan o ang pinsala ay $2,000 o higit pa","Kung ang pinsala ay $500 o higit pa"],"h1":"Isipin ang mga pinsala sa tao at ang halaga ng sira.","h2":"Sa Maine, dapat iulat sa pulis o sheriff ang banggaan kung may nasaktan o kung ang pinsala sa ari-arian ay $2,000 o higit pa.","p":"Tama. Kapag may nasaktan o $2,000 ang pinsala, dapat mo itong iulat."},"ar":{"q":"في Maine، متى يجب على السائقين في حادث أن يبلّغوا الشرطة أو الشريف (sheriff)؟","o":["فقط إذا كان يجب سحب سيارة","فقط إذا حصل سائق على مخالفة","إذا أُصيب أحد أو كان الضرر $2,000 أو أكثر","إذا كان الضرر $500 أو أكثر"],"h1":"فكّر في الإصابات وفي تكلفة الضرر.","h2":"في Maine يجب إبلاغ الشرطة أو الشريف عن الحادث إذا أُصيب أحد أو إذا كان الضرر في الممتلكات $2,000 أو أكثر.","p":"صحيح. إصابة أو ضرر بقيمة $2,000 يعني أنه يجب عليك الإبلاغ."},"ref":{"doc":"ME","page":"9-3"}},{"id":"me-023","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, when must you turn on your headlights during the day?","o":["When your wipers are on all the time","Only on the highway","Only when it is snowing","Only after 4 p.m."],"h1":"Think about rainy, gray days.","h2":"In Maine, you must turn on your headlights whenever your windshield wipers are in constant use, or when you cannot see 1,000 feet ahead.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Maine, ¿cuándo debe encender las luces delanteras durante el día?","o":["Cuando los limpiaparabrisas están siempre prendidos","Solo en la autopista","Solo cuando está nevando","Solo después de las 4 p.m."],"h1":"Piense en los días grises y de lluvia.","h2":"En Maine, usted debe encender las luces delanteras cada vez que use los limpiaparabrisas sin parar, o cuando no pueda ver a 1,000 pies adelante.","p":"Correcto. Limpiaparabrisas prendidos, luces prendidas."},"zh":{"q":"在 Maine，白天什么时候必须开大灯？","o":["雨刷一直开着的时候","只在高速公路上","只在下雪的时候","只在下午 4 点以后"],"h1":"想一想下雨、阴暗的日子。","h2":"在 Maine，只要挡风玻璃的雨刷一直在用，或者你看不清前方 1,000 英尺，就必须开大灯。","p":"对。开雨刷就要开大灯。"},"vi":{"q":"Ở Maine, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi cần gạt nước của bạn bật liên tục","Chỉ trên xa lộ","Chỉ khi trời có tuyết","Chỉ sau 4 giờ chiều"],"h1":"Hãy nghĩ đến những ngày mưa, trời xám.","h2":"Ở Maine, bạn phải bật đèn pha bất cứ khi nào cần gạt nước kính chắn gió được dùng liên tục, hoặc khi bạn không thể nhìn thấy 1,000 feet phía trước.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Maine, kailan mo dapat buksan ang headlights sa araw?","o":["Kapag tuloy-tuloy na nakabukas ang wipers mo","Sa highway lang","Kapag umuulan ng niyebe lang","Pagkatapos ng 4 p.m. lang"],"h1":"Isipin ang maulan at makulimlim na mga araw.","h2":"Sa Maine, dapat mong buksan ang headlights tuwing tuloy-tuloy na ginagamit ang windshield wipers, o kapag hindi mo makita ang 1,000 feet sa unahan.","p":"Tama. Kapag bukas ang wipers, bukas din ang headlights."},"ar":{"q":"في Maine، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["عندما تكون المسّاحات تعمل طوال الوقت","على الطريق السريع فقط","عندما يتساقط الثلج فقط","بعد 4 مساءً فقط"],"h1":"فكّر في الأيام الماطرة والرمادية.","h2":"في Maine يجب أن تشغّل المصابيح الأمامية كلما كانت مسّاحات الزجاج الأمامي تعمل بشكل مستمر، أو عندما لا تستطيع أن ترى 1,000 قدم أمامك.","p":"صحيح. المسّاحات تعمل يعني المصابيح الأمامية تعمل."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-024","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, what is the top speed outside a business, residential or built-up area when no speed limit is posted?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"It is 20 mph more than the limit in town.","h2":"In Maine, unless a sign says otherwise, the top speed outside business, residential and built-up areas is 45 mph.","p":"Right. The unposted limit outside town is 45 mph."},"es":{"q":"En Maine, ¿cuál es la velocidad máxima fuera de una zona comercial, residencial o poblada cuando no hay un límite señalado?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Son 20 mph más que el límite en el pueblo.","h2":"En Maine, a menos que una señal diga otra cosa, la velocidad máxima fuera de zonas comerciales, residenciales y pobladas es de 45 mph.","p":"Correcto. Sin señal, el límite fuera del pueblo es de 45 mph."},"zh":{"q":"在 Maine，在商业区、住宅区或建成区以外，没有限速标志时，最高车速是多少？","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"它比镇上的限速多 20 mph。","h2":"在 Maine，除非标志另有规定，在商业区、住宅区和建成区以外，最高车速是 45 mph。","p":"对。镇外没有标志时，限速是 45 mph。"},"vi":{"q":"Ở Maine, tốc độ tối đa bên ngoài khu thương mại, khu dân cư hoặc khu đông nhà cửa là bao nhiêu khi không có biển giới hạn tốc độ?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Nhiều hơn giới hạn trong thị trấn 20 mph.","h2":"Ở Maine, trừ khi có biển báo khác, tốc độ tối đa bên ngoài khu thương mại, khu dân cư và khu đông nhà cửa là 45 mph.","p":"Đúng. Giới hạn khi không có biển báo bên ngoài thị trấn là 45 mph."},"tl":{"q":"Sa Maine, ano ang pinakamataas na bilis sa labas ng business, residential o built-up area kapag walang nakapaskil na speed limit?","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"Mas mataas ito nang 20 mph kaysa sa limit sa bayan.","h2":"Sa Maine, maliban kung iba ang sinasabi ng karatula, ang pinakamataas na bilis sa labas ng business, residential at built-up area ay 45 mph.","p":"Tama. 45 mph ang limit sa labas ng bayan kapag walang karatula."},"ar":{"q":"في Maine، ما أقصى سرعة خارج المناطق التجارية أو السكنية أو المبنية عندما لا تكون هناك لافتة لحد السرعة؟","o":["35 mph","55 mph","65 mph","45 mph"],"h1":"إنها أكثر من الحد داخل البلدة بـ 20 mph.","h2":"في Maine، إلا إذا قالت لافتة غير ذلك، أقصى سرعة خارج المناطق التجارية والسكنية والمبنية هي 45 mph.","p":"صحيح. الحد بدون لافتة خارج البلدة هو 45 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-025","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a child must ride in a child safety seat if the child weighs less than how much?","o":["40 pounds","55 pounds","80 pounds","100 pounds"],"h1":"It is a little more than 50 pounds.","h2":"In Maine, a child who weighs less than 55 pounds must be buckled into a child safety seat.","p":"Right. Under 55 pounds means a child safety seat."},"es":{"q":"En Maine, ¿por debajo de qué peso debe ir un niño en un asiento de seguridad infantil?","o":["40 libras","55 libras","80 libras","100 libras"],"h1":"Es un poco más de 50 libras.","h2":"En Maine, un niño que pesa menos de 55 libras debe ir abrochado en un asiento de seguridad infantil.","p":"Correcto. Menos de 55 libras significa asiento de seguridad infantil."},"zh":{"q":"在 Maine，孩子的体重低于多少时必须坐儿童安全座椅？","o":["40 磅","55 磅","80 磅","100 磅"],"h1":"比 50 磅多一点。","h2":"在 Maine，体重低于 55 磅的孩子必须系好坐在儿童安全座椅里。","p":"对。低于 55 磅就要坐儿童安全座椅。"},"vi":{"q":"Ở Maine, trẻ em phải ngồi ghế an toàn cho trẻ em nếu trẻ nặng dưới bao nhiêu?","o":["40 pound","55 pound","80 pound","100 pound"],"h1":"Hơn 50 pound một chút.","h2":"Ở Maine, trẻ em nặng dưới 55 pound phải được thắt dây trong ghế an toàn cho trẻ em.","p":"Đúng. Dưới 55 pound thì phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Maine, dapat sumakay ang bata sa child safety seat kung ang timbang niya ay mas mababa sa ilan?","o":["40 pounds","55 pounds","80 pounds","100 pounds"],"h1":"Medyo higit ito sa 50 pounds.","h2":"Sa Maine, ang batang mas mababa sa 55 pounds ang timbang ay dapat nakakabit sa child safety seat.","p":"Tama. Kapag mas mababa sa 55 pounds, child safety seat."},"ar":{"q":"في Maine، يجب أن يركب الطفل في مقعد أمان للأطفال إذا كان وزنه أقل من كم؟","o":["40 رطلًا","55 رطلًا","80 رطلًا","100 رطل"],"h1":"إنه أكثر قليلًا من 50 رطلًا.","h2":"في Maine يجب ربط الطفل الذي وزنه أقل من 55 رطلًا في مقعد أمان للأطفال.","p":"صحيح. أقل من 55 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"ME","page":"4-4"}},{"id":"me-026","scope":"ME","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maine, a driver is convicted of passing a stopped school bus with its red lights flashing. How long may the license be suspended?","o":["7 days","1 year","30 days","6 months"],"h1":"It is about one month.","h2":"In Maine, a driver convicted of passing a stopped school bus with flashing red lights may have the license suspended for 30 days.","p":"Right. The suspension can be 30 days."},"es":{"q":"En Maine, un conductor es condenado por pasar un autobús escolar detenido con las luces rojas intermitentes. ¿Por cuánto tiempo se le puede suspender la licencia?","o":["7 días","1 año","30 días","6 meses"],"h1":"Es como un mes.","h2":"En Maine, a un conductor condenado por pasar un autobús escolar detenido con luces rojas intermitentes se le puede suspender la licencia por 30 días.","p":"Correcto. La suspensión puede ser de 30 días."},"zh":{"q":"在 Maine，一个司机因超过停着、红灯在闪的校车而被定罪。驾照可能被暂停多久？","o":["7 天","1 年","30 天","6 个月"],"h1":"大约一个月。","h2":"在 Maine，因超过停着、红灯在闪的校车而被定罪的司机，驾照可能被暂停 30 天。","p":"对。暂停可能是 30 天。"},"vi":{"q":"Ở Maine, một người lái xe bị kết tội vượt qua xe buýt trường học đang dừng và nhấp nháy đèn đỏ. Bằng lái có thể bị đình chỉ bao lâu?","o":["7 ngày","1 năm","30 ngày","6 tháng"],"h1":"Khoảng một tháng.","h2":"Ở Maine, người lái xe bị kết tội vượt qua xe buýt trường học đang dừng và nhấp nháy đèn đỏ có thể bị đình chỉ bằng lái 30 ngày.","p":"Đúng. Thời gian đình chỉ có thể là 30 ngày."},"tl":{"q":"Sa Maine, nahatulan ang isang driver ng paglampas sa nakahintong school bus na kumikislap ang pulang ilaw. Gaano katagal puwedeng masuspinde ang lisensya?","o":["7 araw","1 taon","30 araw","6 na buwan"],"h1":"Mga isang buwan ito.","h2":"Sa Maine, ang driver na nahatulan ng paglampas sa nakahintong school bus na kumikislap ang pulang ilaw ay puwedeng masuspinde ang lisensya nang 30 araw.","p":"Tama. Puwedeng 30 araw ang suspensyon."},"ar":{"q":"في Maine، أُدين سائق بتجاوز حافلة مدرسية متوقفة وأضواؤها الحمراء تومض. كم مدة يمكن أن تُوقف رخصته؟","o":["7 أيام","سنة واحدة (1)","30 يومًا","6 أشهر"],"h1":"إنها حوالي شهر واحد.","h2":"في Maine السائق الذي يُدان بتجاوز حافلة مدرسية متوقفة وأضواؤها الحمراء تومض يمكن أن تُوقف رخصته 30 يومًا.","p":"صحيح. يمكن أن يكون الإيقاف 30 يومًا."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-027","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, how much space must you leave between your car and a bicycle when you pass it?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"Think of about one long step.","h2":"In Maine, you must leave at least 3 feet between the right side of your car and the bicycle when you pass it.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Maine, ¿cuánto espacio debe dejar entre su carro y una bicicleta al pasarla?","o":["1 pie","2 pies","3 pies","6 pies"],"h1":"Piense en un paso largo.","h2":"En Maine, usted debe dejar por lo menos 3 pies entre el lado derecho de su carro y la bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Maine，超过自行车时，你的车和自行车之间必须留多少空间？","o":["1 英尺","2 英尺","3 英尺","6 英尺"],"h1":"大约是一大步的长度。","h2":"在 Maine，超过自行车时，你的车右侧和自行车之间必须至少留 3 英尺。","p":"对。至少留 3 英尺。"},"vi":{"q":"Ở Maine, khi vượt một xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và xe đạp?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Maine, khi vượt một xe đạp, bạn phải chừa ít nhất 3 feet giữa bên phải xe của bạn và xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Maine, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["1 talampakan","2 talampakan","3 talampakan","6 talampakan"],"h1":"Isipin ang isang mahabang hakbang.","h2":"Sa Maine, dapat kang mag-iwan ng hindi bababa sa 3 talampakan sa pagitan ng kanang gilid ng kotse mo at ng bisikleta kapag nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan."},"ar":{"q":"في Maine، كم مسافة يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["1 قدم","2 قدم","3 أقدام","6 أقدام"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Maine، يجب أن تترك 3 أقدام على الأقل بين الجانب الأيمن لسيارتك والدراجة عندما تتجاوزها.","p":"صحيح. اترك 3 أقدام على الأقل."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-028","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a driver under 65 gets a new picture license. Until when is it valid?","o":["Until the sixth birthday after it is issued","Until the second birthday after it is issued","Until the tenth birthday after it is issued","Until the end of the same year"],"h1":"It lasts several years, but less than ten.","h2":"In Maine, a picture license for a driver under 65 is valid until the sixth birthday after the date it is issued.","p":"Right. It lasts until the sixth birthday after it is issued."},"es":{"q":"En Maine, un conductor menor de 65 años recibe una licencia nueva con foto. ¿Hasta cuándo es válida?","o":["Hasta el sexto cumpleaños después de emitirla","Hasta el segundo cumpleaños después de emitirla","Hasta el décimo cumpleaños después de emitirla","Hasta el final del mismo año"],"h1":"Dura varios años, pero menos de diez.","h2":"En Maine, la licencia con foto de un conductor menor de 65 años es válida hasta el sexto cumpleaños después de la fecha en que se emite.","p":"Correcto. Dura hasta el sexto cumpleaños después de emitirla."},"zh":{"q":"在 Maine，一位未满 65 岁的司机拿到一张新的带照片的驾照。它有效到什么时候？","o":["到发证后的第六个生日","到发证后的第二个生日","到发证后的第十个生日","到同一年年底"],"h1":"它能用好几年，但不到十年。","h2":"在 Maine，未满 65 岁司机的带照片驾照，有效期到发证日期后的第六个生日。","p":"对。它有效到发证后的第六个生日。"},"vi":{"q":"Ở Maine, một người lái xe dưới 65 tuổi nhận bằng lái mới có ảnh. Bằng này có giá trị đến khi nào?","o":["Đến sinh nhật thứ sáu sau ngày cấp","Đến sinh nhật thứ hai sau ngày cấp","Đến sinh nhật thứ mười sau ngày cấp","Đến cuối cùng năm đó"],"h1":"Bằng dùng được vài năm, nhưng ít hơn mười năm.","h2":"Ở Maine, bằng lái có ảnh của người lái xe dưới 65 tuổi có giá trị đến sinh nhật thứ sáu sau ngày cấp.","p":"Đúng. Bằng có giá trị đến sinh nhật thứ sáu sau ngày cấp."},"tl":{"q":"Sa Maine, may driver na wala pang 65 na nakakuha ng bagong lisensya na may litrato. Hanggang kailan ito valid?","o":["Hanggang sa ikaanim na kaarawan matapos itong ibigay","Hanggang sa ikalawang kaarawan matapos itong ibigay","Hanggang sa ikasampung kaarawan matapos itong ibigay","Hanggang sa katapusan ng parehong taon"],"h1":"Tumatagal ito nang ilang taon, pero kulang sa sampu.","h2":"Sa Maine, ang lisensyang may litrato ng driver na wala pang 65 ay valid hanggang sa ikaanim na kaarawan matapos ang petsa ng pagbibigay nito.","p":"Tama. Tumatagal ito hanggang sa ikaanim na kaarawan matapos itong ibigay."},"ar":{"q":"في Maine، حصل سائق عمره أقل من 65 سنة على رخصة جديدة بصورة. حتى متى تكون صالحة؟","o":["حتى عيد الميلاد السادس بعد إصدارها","حتى عيد الميلاد الثاني بعد إصدارها","حتى عيد الميلاد العاشر بعد إصدارها","حتى نهاية السنة نفسها"],"h1":"تدوم عدة سنوات، لكن أقل من عشر.","h2":"في Maine، رخصة القيادة بصورة للسائق الذي عمره أقل من 65 سنة صالحة حتى عيد الميلاد السادس بعد تاريخ إصدارها.","p":"صحيح. تبقى صالحة حتى عيد الميلاد السادس بعد إصدارها."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-029","scope":"ME","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maine, a person with a white cane or a guide dog is in the road. How far away must you stop?","o":["At least 2 feet","At least 5 feet","At least 50 feet","At least 10 feet"],"h1":"It is about the length of two adult people lying down.","h2":"In Maine, you must stop at least 10 feet away from a person with a white cane or guide dog and wait until the person is safe.","p":"Right. Stop at least 10 feet away and wait."},"es":{"q":"En Maine, una persona con bastón blanco o perro guía está en la calle. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 2 pies","Por lo menos a 5 pies","Por lo menos a 50 pies","Por lo menos a 10 pies"],"h1":"Es como el largo de dos adultos acostados.","h2":"En Maine, usted debe detenerse por lo menos a 10 pies de una persona con bastón blanco o perro guía y esperar hasta que esté a salvo.","p":"Correcto. Deténgase por lo menos a 10 pies y espere."},"zh":{"q":"在 Maine，一个拿白色手杖或带导盲犬的人在路上。你必须在多远的地方停车？","o":["至少 2 英尺","至少 5 英尺","至少 50 英尺","至少 10 英尺"],"h1":"大约是两个成年人躺下的长度。","h2":"在 Maine，你必须在离拿白色手杖或带导盲犬的人至少 10 英尺的地方停车，并等到这个人安全为止。","p":"对。在至少 10 英尺外停车并等待。"},"vi":{"q":"Ở Maine, một người cầm gậy trắng hoặc đi cùng chó dẫn đường đang ở trên đường. Bạn phải dừng xe cách bao xa?","o":["Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 50 feet","Ít nhất 10 feet"],"h1":"Khoảng bằng chiều dài của hai người lớn nằm xuống.","h2":"Ở Maine, bạn phải dừng xe cách người cầm gậy trắng hoặc đi cùng chó dẫn đường ít nhất 10 feet và chờ đến khi người đó an toàn.","p":"Đúng. Dừng cách ít nhất 10 feet và chờ."},"tl":{"q":"Sa Maine, may taong may puting tungkod o may guide dog na nasa kalsada. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 2 talampakan","Hindi bababa sa 5 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 10 talampakan"],"h1":"Halos kasinghaba ito ng dalawang taong nasa hustong gulang na nakahiga.","h2":"Sa Maine, dapat kang huminto nang hindi bababa sa 10 talampakan ang layo mula sa taong may puting tungkod o guide dog, at maghintay hanggang ligtas na ang tao.","p":"Tama. Huminto nang hindi bababa sa 10 talampakan ang layo at maghintay."},"ar":{"q":"في Maine، شخص يحمل عصا بيضاء أو معه كلب مرشد موجود في الطريق. على أي بُعد يجب أن تتوقف؟","o":["2 قدم على الأقل","5 أقدام على الأقل","50 قدمًا على الأقل","10 أقدام على الأقل"],"h1":"المسافة تقريبًا بطول شخصين بالغين مستلقيين.","h2":"في Maine، يجب أن تتوقف على بُعد 10 أقدام على الأقل من الشخص الذي يحمل عصا بيضاء أو معه كلب مرشد، وأن تنتظر حتى يصبح في أمان.","p":"صحيح. توقّف على بُعد 10 أقدام على الأقل وانتظر."},"ref":{"doc":"ME","page":"6-12"}},{"id":"me-030","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a passenger in the front seat opens a can of beer while you drive on a public road. What is true?","o":["It is legal because the driver is not drinking","It breaks the law for the driver","It is legal if the passenger is 21 or older","It is only illegal at night"],"h1":"The open container law covers the whole passenger area.","h2":"In Maine, the driver breaks the law if the driver or a passenger drinks alcohol or has an open alcohol container in the passenger area.","p":"Right. An open container in the passenger area breaks the law."},"es":{"q":"En Maine, un pasajero en el asiento delantero abre una lata de cerveza mientras usted maneja en una vía pública. ¿Qué es cierto?","o":["Es legal porque el conductor no está tomando","El conductor está violando la ley","Es legal si el pasajero tiene 21 años o más","Solo es ilegal de noche"],"h1":"La ley de envases abiertos cubre toda el área de pasajeros.","h2":"En Maine, el conductor viola la ley si él o un pasajero toma alcohol o tiene un envase abierto de alcohol en el área de pasajeros.","p":"Correcto. Un envase abierto en el área de pasajeros viola la ley."},"zh":{"q":"在 Maine，你在公共道路上开车时，前座的乘客打开了一罐啤酒。哪一项是对的？","o":["这是合法的，因为司机没有喝酒","这让司机违法","如果乘客 21 岁或以上，这是合法的","只有在晚上才违法"],"h1":"开口容器法适用于整个乘客区域。","h2":"在 Maine，如果司机或乘客在乘客区域喝酒，或者有打开的酒类容器，司机就违法。","p":"对。乘客区域里有打开的酒类容器就是违法。"},"vi":{"q":"Ở Maine, một hành khách ngồi ghế trước mở một lon bia trong khi bạn lái xe trên đường công cộng. Điều nào đúng?","o":["Hợp pháp vì người lái xe không uống","Người lái xe đang vi phạm luật","Hợp pháp nếu hành khách từ 21 tuổi trở lên","Chỉ bất hợp pháp vào ban đêm"],"h1":"Luật về đồ chứa rượu đã mở áp dụng cho toàn bộ khu vực hành khách.","h2":"Ở Maine, người lái xe vi phạm luật nếu người lái hoặc hành khách uống rượu bia hoặc có đồ chứa rượu bia đã mở trong khu vực hành khách.","p":"Đúng. Đồ chứa rượu bia đã mở trong khu vực hành khách là vi phạm luật."},"tl":{"q":"Sa Maine, binuksan ng pasahero sa upuan sa harap ang isang lata ng beer habang nagmamaneho ka sa pampublikong kalsada. Ano ang totoo?","o":["Legal ito dahil hindi umiinom ang driver","Lumalabag sa batas ang driver","Legal ito kung ang pasahero ay 21 taong gulang o higit pa","Ilegal lang ito sa gabi"],"h1":"Saklaw ng open container law ang buong lugar ng mga pasahero.","h2":"Sa Maine, lumalabag sa batas ang driver kung ang driver o isang pasahero ay umiinom ng alak o may bukas na lalagyan ng alak sa lugar ng mga pasahero.","p":"Tama. Labag sa batas ang bukas na lalagyan ng alak sa lugar ng mga pasahero."},"ar":{"q":"في Maine، فتح راكب في المقعد الأمامي علبة بيرة وأنت تقود على طريق عام. ما الصحيح؟","o":["هذا قانوني لأن السائق لا يشرب","السائق يخالف القانون","هذا قانوني إذا كان عمر الراكب 21 سنة أو أكثر","هذا غير قانوني في الليل فقط"],"h1":"قانون الحاويات المفتوحة يشمل كل منطقة الركاب.","h2":"في Maine، يخالف السائق القانون إذا شرب هو أو أحد الركاب الكحول، أو إذا كانت في منطقة الركاب حاوية كحول مفتوحة.","p":"صحيح. حاوية الكحول المفتوحة في منطقة الركاب مخالفة للقانون."},"ref":{"doc":"ME","page":"3-13"}},{"id":"me-031","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, what is the lowest fine for parking in the striped access aisle next to a disability parking space?","o":["$25","$50","$200","$75"],"h1":"It is more than $100.","h2":"In Maine, parking in the access aisle next to a disability parking space is a traffic infraction with a fine of at least $200.","p":"Right. The fine is at least $200."},"es":{"q":"En Maine, ¿cuál es la multa más baja por estacionarse en el pasillo de acceso con rayas junto a un espacio para personas con discapacidad?","o":["$25","$50","$200","$75"],"h1":"Es más de $100.","h2":"En Maine, estacionarse en el pasillo de acceso junto a un espacio para personas con discapacidad es una infracción de tránsito con una multa de por lo menos $200.","p":"Correcto. La multa es de por lo menos $200."},"zh":{"q":"在 Maine，把车停在残障停车位旁边画斜线的通道上，最低罚款是多少？","o":["$25","$50","$200","$75"],"h1":"它超过 $100。","h2":"在 Maine，把车停在残障停车位旁边的通道上是交通违规，罚款至少 $200。","p":"对。罚款至少 $200。"},"vi":{"q":"Ở Maine, tiền phạt thấp nhất khi đậu xe trong lối đi có vạch kẻ bên cạnh chỗ đậu xe cho người khuyết tật là bao nhiêu?","o":["$25","$50","$200","$75"],"h1":"Số tiền này nhiều hơn $100.","h2":"Ở Maine, đậu xe trong lối đi bên cạnh chỗ đậu xe cho người khuyết tật là vi phạm giao thông, với tiền phạt ít nhất $200.","p":"Đúng. Tiền phạt ít nhất là $200."},"tl":{"q":"Sa Maine, magkano ang pinakamababang multa sa pagparada sa may guhit na access aisle sa tabi ng parking space para sa may kapansanan?","o":["$25","$50","$200","$75"],"h1":"Higit ito sa $100.","h2":"Sa Maine, ang pagparada sa access aisle sa tabi ng parking space para sa may kapansanan ay isang traffic infraction na may multang hindi bababa sa $200.","p":"Tama. Ang multa ay hindi bababa sa $200."},"ar":{"q":"في Maine، ما أقل غرامة لركن السيارة في الممر المخطّط بجانب موقف ذوي الإعاقة؟","o":["$25","$50","$200","$75"],"h1":"المبلغ أكثر من $100.","h2":"في Maine، ركن السيارة في الممر بجانب موقف ذوي الإعاقة مخالفة مرورية غرامتها $200 على الأقل.","p":"صحيح. الغرامة $200 على الأقل."},"ref":{"doc":"ME","page":"7-10"}},{"id":"me-032","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how long is a learner's permit usually valid?","o":["6 months","1 year","2 years","5 years"],"h1":"It lasts much longer than the 6 months you must hold it before the road test.","h2":"In Maine, a learner's permit is usually valid for 2 years.","p":"Right. A permit usually lasts 2 years."},"es":{"q":"En Maine, ¿por cuánto tiempo suele ser válido un permiso de aprendizaje?","o":["6 meses","1 año","2 años","5 años"],"h1":"Dura mucho más que los 6 meses que debe tenerlo antes del examen de manejo.","h2":"En Maine, un permiso de aprendizaje suele ser válido por 2 años.","p":"Correcto. Un permiso suele durar 2 años."},"zh":{"q":"在 Maine，学习驾照（learner's permit）通常有效多久？","o":["6 个月","1 年","2 年","5 年"],"h1":"它比路考前必须持有的 6 个月长得多。","h2":"在 Maine，学习驾照通常有效 2 年。","p":"对。学习驾照通常有效 2 年。"},"vi":{"q":"Ở Maine, giấy phép tập lái (learner's permit) thường có hiệu lực bao lâu?","o":["6 tháng","1 năm","2 năm","5 năm"],"h1":"Nó dài hơn nhiều so với 6 tháng bạn phải giữ giấy phép trước khi thi lái thực hành.","h2":"Ở Maine, giấy phép tập lái thường có hiệu lực trong 2 năm.","p":"Đúng. Giấy phép tập lái thường có hiệu lực 2 năm."},"tl":{"q":"Sa Maine, gaano katagal karaniwang may bisa ang learner's permit?","o":["6 na buwan","1 taon","2 taon","5 taon"],"h1":"Mas matagal ito kaysa sa 6 na buwan na dapat mong hawak ang permit bago ang road test.","h2":"Sa Maine, ang learner's permit ay karaniwang may bisa nang 2 taon.","p":"Tama. Karaniwang tumatagal nang 2 taon ang permit."},"ar":{"q":"في Maine، كم مدة صلاحية تصريح تعلّم القيادة (learner's permit) عادةً؟","o":["6 أشهر","سنة واحدة (1)","سنتان (2)","5 سنوات"],"h1":"إنها أطول بكثير من مدة 6 أشهر التي يجب أن تحمل فيها التصريح قبل اختبار القيادة.","h2":"في Maine تكون صلاحية تصريح تعلّم القيادة عادةً سنتين (2).","p":"صحيح. التصريح صالح عادةً لمدة سنتين (2)."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-033","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a new resident has a valid driver's license from another state. How soon must they apply for a Maine license?","o":["Within 30 days","Within 6 months","Within 1 year","When the old license expires"],"h1":"It is about one month.","h2":"In Maine, a new resident must give up the out-of-state license and apply for a Maine license within 30 days of moving here.","p":"Right. New residents have 30 days."},"es":{"q":"En Maine, un nuevo residente tiene una licencia de manejo válida de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Maine?","o":["Dentro de 30 días","Dentro de 6 meses","Dentro de 1 año","Cuando venza la licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Maine, un nuevo residente debe entregar la licencia de otro estado y solicitar una licencia de Maine dentro de los 30 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Maine，一位新居民持有其他州的有效驾照。他必须在多久之内申请 Maine 驾照？","o":["30 天之内","6 个月之内","1 年之内","旧驾照过期的时候"],"h1":"大约是一个月。","h2":"在 Maine，新居民必须在搬来后 30 天之内交出外州驾照，并申请 Maine 驾照。","p":"对。新居民有 30 天。"},"vi":{"q":"Ở Maine, một cư dân mới có bằng lái còn hiệu lực của tiểu bang khác. Người đó phải xin bằng lái Maine trong thời gian bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 6 tháng","Trong vòng 1 năm","Khi bằng lái cũ hết hạn"],"h1":"Khoảng một tháng.","h2":"Ở Maine, cư dân mới phải nộp lại bằng lái của tiểu bang khác và xin bằng lái Maine trong vòng 30 ngày sau khi chuyển đến.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa Maine, may valid na driver's license mula sa ibang estado ang isang bagong residente. Gaano kabilis dapat siyang mag-apply para sa Maine license?","o":["Sa loob ng 30 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon","Kapag nag-expire na ang lumang lisensya"],"h1":"Mga isang buwan ito.","h2":"Sa Maine, dapat isuko ng bagong residente ang lisensya mula sa ibang estado at mag-apply para sa Maine license sa loob ng 30 araw pagkalipat dito.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Maine، مقيم جديد لديه رخصة قيادة صالحة من ولاية أخرى. خلال كم من الوقت يجب أن يطلب رخصة Maine؟","o":["خلال 30 يومًا","خلال 6 أشهر","خلال سنة واحدة (1)","عندما تنتهي الرخصة القديمة"],"h1":"إنها شهر واحد تقريبًا.","h2":"في Maine يجب على المقيم الجديد أن يسلّم رخصة الولاية الأخرى ويطلب رخصة Maine خلال 30 يومًا من انتقاله إليها.","p":"صحيح. لدى المقيمين الجدد 30 يومًا."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-034","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a person did not take an approved driver education course. What is the youngest age at which they can get a driver's license?","o":["15","16","17","18"],"h1":"With driver education, the youngest age is 16. Without it, you must wait longer.","h2":"In Maine, a person who has not finished an approved driver education course must be at least 18 to get a driver's license.","p":"Right. Without driver education, you must be 18."},"es":{"q":"En Maine, una persona no tomó un curso aprobado de educación vial. ¿Cuál es la edad mínima para que obtenga una licencia de manejo?","o":["15","16","17","18"],"h1":"Con educación vial, la edad mínima es 16. Sin ella, debe esperar más.","h2":"En Maine, una persona que no ha terminado un curso aprobado de educación vial debe tener por lo menos 18 años para obtener una licencia de manejo.","p":"Correcto. Sin educación vial, debe tener 18 años."},"zh":{"q":"在 Maine，一个人没有上过批准的驾驶教育课程。他最小几岁可以拿到驾照？","o":["15","16","17","18"],"h1":"上过驾驶教育课程，最小是 16 岁。没上过，就要等更久。","h2":"在 Maine，没有完成批准的驾驶教育课程的人，必须年满 18 岁才能拿到驾照。","p":"对。没有驾驶教育课程，必须满 18 岁。"},"vi":{"q":"Ở Maine, một người không học khóa giáo dục lái xe (driver education) được chấp thuận. Tuổi nhỏ nhất để người đó có bằng lái là bao nhiêu?","o":["15","16","17","18"],"h1":"Nếu có học giáo dục lái xe, tuổi nhỏ nhất là 16. Nếu không học, bạn phải chờ lâu hơn.","h2":"Ở Maine, người chưa hoàn thành khóa giáo dục lái xe được chấp thuận phải ít nhất 18 tuổi mới có bằng lái.","p":"Đúng. Không học giáo dục lái xe thì phải 18 tuổi."},"tl":{"q":"Sa Maine, hindi kumuha ang isang tao ng aprubadong kurso sa driver education. Ano ang pinakabatang edad para makakuha siya ng driver's license?","o":["15","16","17","18"],"h1":"Kung may driver education, 16 ang pinakabatang edad. Kung wala, kailangan mong maghintay nang mas matagal.","h2":"Sa Maine, ang taong hindi nakatapos ng aprubadong kurso sa driver education ay dapat hindi bababa sa 18 taong gulang para makakuha ng driver's license.","p":"Tama. Kung walang driver education, dapat 18 ka na."},"ar":{"q":"في Maine، شخص لم يأخذ دورة تعليم قيادة (driver education) معتمدة. ما أصغر عمر يمكنه فيه الحصول على رخصة قيادة؟","o":["15","16","17","18"],"h1":"مع دورة تعليم القيادة، أصغر عمر هو 16. ومن دونها يجب أن تنتظر مدة أطول.","h2":"في Maine الشخص الذي لم ينهِ دورة تعليم قيادة معتمدة يجب أن يكون عمره 18 سنة على الأقل ليحصل على رخصة قيادة.","p":"صحيح. من دون دورة تعليم القيادة يجب أن يكون عمرك 18 سنة."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-035","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a driver is convicted of going 30 mph or more over the speed limit. How long may the license be suspended?","o":["7 days","30 days","1 year","3 years"],"h1":"It is about one month.","h2":"In Maine, a conviction for speeding 30 mph or more over the limit may bring a 30-day license suspension.","p":"Right. It may mean a 30-day suspension."},"es":{"q":"En Maine, un conductor es declarado culpable de manejar a 30 mph o más por encima del límite de velocidad. ¿Por cuánto tiempo pueden suspenderle la licencia?","o":["7 días","30 días","1 año","3 años"],"h1":"Es más o menos un mes.","h2":"En Maine, una condena por manejar a 30 mph o más por encima del límite puede causar una suspensión de la licencia de 30 días.","p":"Correcto. Puede causar una suspensión de 30 días."},"zh":{"q":"在 Maine，一名司机因超过限速 30 mph 或以上被定罪。驾照可能会被暂停多久？","o":["7 天","30 天","1 年","3 年"],"h1":"大约是一个月。","h2":"在 Maine，因超过限速 30 mph 或以上被定罪，驾照可能会被暂停 30 天。","p":"对。可能会被暂停 30 天。"},"vi":{"q":"Ở Maine, một người lái xe bị kết tội chạy quá giới hạn tốc độ từ 30 mph trở lên. Bằng lái có thể bị đình chỉ bao lâu?","o":["7 ngày","30 ngày","1 năm","3 năm"],"h1":"Khoảng một tháng.","h2":"Ở Maine, bị kết tội chạy quá giới hạn tốc độ từ 30 mph trở lên có thể bị đình chỉ bằng lái 30 ngày.","p":"Đúng. Có thể bị đình chỉ 30 ngày."},"tl":{"q":"Sa Maine, nahatulan ang isang driver sa pagmamaneho nang 30 mph o higit pa na lampas sa speed limit. Gaano katagal puwedeng masuspinde ang lisensya?","o":["7 araw","30 araw","1 taon","3 taon"],"h1":"Mga isang buwan ito.","h2":"Sa Maine, ang paghatol sa pagmamaneho nang 30 mph o higit pa na lampas sa limit ay puwedeng magdulot ng 30 araw na suspensyon ng lisensya.","p":"Tama. Puwede itong maging 30 araw na suspensyon."},"ar":{"q":"في Maine، أُدين سائق بالقيادة بسرعة تزيد 30 mph أو أكثر عن حد السرعة. كم مدة قد تُوقف فيها رخصته؟","o":["7 أيام","30 يومًا","سنة واحدة (1)","3 سنوات"],"h1":"إنها شهر واحد تقريبًا.","h2":"في Maine الإدانة بالقيادة بسرعة تزيد 30 mph أو أكثر عن الحد قد تؤدي إلى إيقاف الرخصة 30 يومًا.","p":"صحيح. قد تعني إيقاف الرخصة 30 يومًا."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-036","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, at how many demerit points does the Secretary of State send a driver a warning?","o":["3 points","6 points","9 points","12 points"],"h1":"It is half of the number that leads to a suspension.","h2":"In Maine, a driver gets a warning at 6 demerit points, and the license is suspended at 12 points.","p":"Right. The warning comes at 6 points."},"es":{"q":"En Maine, ¿con cuántos puntos de demérito le envía la Secretaría de Estado una advertencia al conductor?","o":["3 puntos","6 puntos","9 puntos","12 puntos"],"h1":"Es la mitad del número que causa una suspensión.","h2":"En Maine, el conductor recibe una advertencia con 6 puntos de demérito, y la licencia se suspende con 12 puntos.","p":"Correcto. La advertencia llega con 6 puntos."},"zh":{"q":"在 Maine，司机的扣分到多少时，州务卿（Secretary of State）会寄来警告？","o":["3 分","6 分","9 分","12 分"],"h1":"它是导致暂停驾照分数的一半。","h2":"在 Maine，司机到 6 分扣分时会收到警告，到 12 分时驾照会被暂停。","p":"对。到 6 分时会收到警告。"},"vi":{"q":"Ở Maine, khi có bao nhiêu điểm phạt (demerit points) thì Bộ trưởng Tiểu bang (Secretary of State) gửi thư cảnh cáo cho người lái xe?","o":["3 điểm","6 điểm","9 điểm","12 điểm"],"h1":"Đó là một nửa số điểm dẫn đến bị đình chỉ.","h2":"Ở Maine, người lái xe bị cảnh cáo khi có 6 điểm phạt, và bị đình chỉ bằng lái khi có 12 điểm.","p":"Đúng. Thư cảnh cáo đến khi có 6 điểm."},"tl":{"q":"Sa Maine, sa ilang demerit point nagpapadala ang Secretary of State ng babala sa driver?","o":["3 puntos","6 na puntos","9 na puntos","12 puntos"],"h1":"Kalahati ito ng numerong nagdudulot ng suspensyon.","h2":"Sa Maine, nakakatanggap ng babala ang driver sa 6 na demerit point, at masususpinde ang lisensya sa 12 puntos.","p":"Tama. Dumarating ang babala sa 6 na puntos."},"ar":{"q":"في Maine، عند كم نقطة مخالفة (demerit points) يرسل وزير الولاية (Secretary of State) تحذيرًا إلى السائق؟","o":["3 نقاط","6 نقاط","9 نقاط","12 نقطة"],"h1":"إنه نصف العدد الذي يؤدي إلى إيقاف الرخصة.","h2":"في Maine يحصل السائق على تحذير عند 6 نقاط مخالفة، وتُوقف الرخصة عند 12 نقطة.","p":"صحيح. يأتي التحذير عند 6 نقاط."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-037","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver earns one violation-free credit point for each calendar year with no convictions or suspensions. What is the most a driver can build up?","o":["1 point","2 points","3 points","4 points"],"h1":"It is more than 3.","h2":"In Maine, a driver can build up to 4 violation-free credit points, one for each calendar year with no convictions or suspensions.","p":"Right. The most is 4 credit points."},"es":{"q":"En Maine, un conductor gana un punto de crédito por cada año calendario sin condenas ni suspensiones. ¿Cuál es el máximo que puede acumular?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Es más de 3.","h2":"En Maine, un conductor puede acumular hasta 4 puntos de crédito, uno por cada año calendario sin condenas ni suspensiones.","p":"Correcto. El máximo es 4 puntos de crédito."},"zh":{"q":"在 Maine，司机每个日历年没有定罪或暂停，就会得到一个无违规奖励分（credit point）。司机最多能累积几分？","o":["1 分","2 分","3 分","4 分"],"h1":"它比 3 多。","h2":"在 Maine，司机最多能累积 4 个无违规奖励分，每个没有定罪或暂停的日历年得一分。","p":"对。最多是 4 个奖励分。"},"vi":{"q":"Ở Maine, người lái xe được một điểm thưởng không vi phạm (credit point) cho mỗi năm dương lịch không bị kết tội hay đình chỉ. Người lái xe có thể tích lũy tối đa bao nhiêu điểm?","o":["1 điểm","2 điểm","3 điểm","4 điểm"],"h1":"Nhiều hơn 3.","h2":"Ở Maine, người lái xe có thể tích lũy tối đa 4 điểm thưởng không vi phạm, mỗi điểm cho một năm dương lịch không bị kết tội hay đình chỉ.","p":"Đúng. Tối đa là 4 điểm thưởng."},"tl":{"q":"Sa Maine, nakakakuha ang driver ng isang violation-free credit point sa bawat calendar year na walang paghatol o suspensyon. Ano ang pinakamaraming puwedeng maipon ng driver?","o":["1 punto","2 puntos","3 puntos","4 na puntos"],"h1":"Higit ito sa 3.","h2":"Sa Maine, puwedeng makaipon ang driver ng hanggang 4 na violation-free credit point, isa sa bawat calendar year na walang paghatol o suspensyon.","p":"Tama. 4 na credit point ang pinakamarami."},"ar":{"q":"في Maine، يكسب السائق نقطة رصيد واحدة بلا مخالفات (credit point) عن كل سنة ميلادية بلا إدانات أو إيقاف. ما أكبر عدد يمكن أن يجمعه السائق؟","o":["نقطة واحدة (1)","نقطتان (2)","3 نقاط","4 نقاط"],"h1":"إنه أكثر من 3.","h2":"في Maine يمكن للسائق أن يجمع حتى 4 نقاط رصيد بلا مخالفات، نقطة عن كل سنة ميلادية بلا إدانات أو إيقاف.","p":"صحيح. الحد الأقصى 4 نقاط رصيد."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-038","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, an adult is convicted of OUI for the first time with an alcohol level of 0.15 or higher. What is the shortest jail time?","o":["48 hours","No jail time","12 hours","24 hours"],"h1":"It is two full days.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.15 or higher means at least 48 hours in jail.","p":"Right. The minimum is 48 hours in jail."},"es":{"q":"En Maine, un adulto es declarado culpable de OUI (manejar bajo la influencia) por primera vez con un nivel de alcohol de 0.15 o más. ¿Cuál es el tiempo mínimo en la cárcel?","o":["48 horas","Nada de cárcel","12 horas","24 horas"],"h1":"Son dos días completos.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.15 o más significa por lo menos 48 horas en la cárcel.","p":"Correcto. El mínimo es 48 horas en la cárcel."},"zh":{"q":"在 Maine，一名成年人第一次因 OUI（酒后或药后驾驶）被定罪，酒精浓度为 0.15 或更高。最短要坐牢多久？","o":["48 小时","不用坐牢","12 小时","24 小时"],"h1":"是整整两天。","h2":"在 Maine，第一次 OUI 定罪而酒精浓度为 0.15 或更高，至少要坐牢 48 小时。","p":"对。最少要坐牢 48 小时。"},"vi":{"q":"Ở Maine, một người lớn bị kết tội OUI (lái xe khi say rượu hoặc dùng chất kích thích) lần đầu với nồng độ cồn từ 0.15 trở lên. Thời gian ngồi tù ngắn nhất là bao lâu?","o":["48 giờ","Không phải ngồi tù","12 giờ","24 giờ"],"h1":"Đó là hai ngày trọn.","h2":"Ở Maine, bị kết tội OUI lần đầu với nồng độ cồn từ 0.15 trở lên nghĩa là phải ngồi tù ít nhất 48 giờ.","p":"Đúng. Tối thiểu là 48 giờ ngồi tù."},"tl":{"q":"Sa Maine, nahatulan ang isang adult ng OUI (pagmamaneho nang lasing o nasa impluwensya) sa unang pagkakataon na may alcohol level na 0.15 o higit pa. Ano ang pinakamaikling panahon sa kulungan?","o":["48 oras","Walang kulong","12 oras","24 oras"],"h1":"Dalawang buong araw ito.","h2":"Sa Maine, ang unang paghatol ng OUI na may alcohol level na 0.15 o higit pa ay nangangahulugang hindi bababa sa 48 oras sa kulungan.","p":"Tama. 48 oras sa kulungan ang pinakamababa."},"ar":{"q":"في Maine، أُدين شخص بالغ بتهمة OUI (القيادة تحت تأثير الكحول أو المخدرات) لأول مرة بنسبة كحول 0.15 أو أكثر. ما أقل مدة سجن؟","o":["48 ساعة","لا سجن","12 ساعة","24 ساعة"],"h1":"إنها يومان كاملان.","h2":"في Maine الإدانة الأولى بتهمة OUI بنسبة كحول 0.15 أو أكثر تعني السجن 48 ساعة على الأقل.","p":"صحيح. الحد الأدنى هو 48 ساعة في السجن."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-039","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, what is the lowest fine for a first OUI conviction with an alcohol level of 0.08 to 0.14 and no test refusal?","o":["$50","$250","$500","$100"],"h1":"It is several hundred dollars.","h2":"In Maine, a first OUI conviction with an alcohol level of 0.08 to 0.14 brings a fine of at least $500.","p":"Right. The fine is at least $500."},"es":{"q":"En Maine, ¿cuál es la multa más baja por una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14, sin negarse a la prueba?","o":["$50","$250","$500","$100"],"h1":"Son varios cientos de dólares.","h2":"En Maine, una primera condena por OUI con un nivel de alcohol de 0.08 a 0.14 trae una multa de por lo menos $500.","p":"Correcto. La multa es de por lo menos $500."},"zh":{"q":"在 Maine，第一次 OUI 定罪，酒精浓度为 0.08 到 0.14，而且没有拒绝检测，最低罚款是多少？","o":["$50","$250","$500","$100"],"h1":"是几百美元。","h2":"在 Maine，第一次 OUI 定罪而酒精浓度为 0.08 到 0.14，罚款至少是 $500。","p":"对。罚款至少是 $500。"},"vi":{"q":"Ở Maine, mức phạt thấp nhất cho lần đầu bị kết tội OUI với nồng độ cồn từ 0.08 đến 0.14 và không từ chối kiểm tra là bao nhiêu?","o":["$50","$250","$500","$100"],"h1":"Đó là vài trăm đô la.","h2":"Ở Maine, lần đầu bị kết tội OUI với nồng độ cồn từ 0.08 đến 0.14 bị phạt ít nhất $500.","p":"Đúng. Tiền phạt ít nhất là $500."},"tl":{"q":"Sa Maine, ano ang pinakamababang multa sa unang paghatol ng OUI na may alcohol level na 0.08 hanggang 0.14 at walang pagtanggi sa test?","o":["$50","$250","$500","$100"],"h1":"Ilang daang dolyar ito.","h2":"Sa Maine, ang unang paghatol ng OUI na may alcohol level na 0.08 hanggang 0.14 ay may multang hindi bababa sa $500.","p":"Tama. Hindi bababa sa $500 ang multa."},"ar":{"q":"في Maine، ما أقل غرامة للإدانة الأولى بتهمة OUI بنسبة كحول من 0.08 إلى 0.14 من دون رفض الفحص؟","o":["$50","$250","$500","$100"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Maine الإدانة الأولى بتهمة OUI بنسبة كحول من 0.08 إلى 0.14 تعني غرامة لا تقل عن $500.","p":"صحيح. الغرامة لا تقل عن $500."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-040","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, after a first OUI conviction, the driver gets back a conditional license that allows no alcohol at all while driving. How long does that condition last?","o":["30 days","6 months","10 years","1 year"],"h1":"The much longer period is for a second conviction.","h2":"In Maine, after a first OUI conviction, the reinstated license is conditional for one year.","p":"Right. The condition lasts one year."},"es":{"q":"En Maine, después de una primera condena por OUI, el conductor recupera una licencia condicional que no permite nada de alcohol al manejar. ¿Cuánto dura esa condición?","o":["30 días","6 meses","10 años","1 año"],"h1":"El período mucho más largo es para una segunda condena.","h2":"En Maine, después de una primera condena por OUI, la licencia restablecida es condicional por un año.","p":"Correcto. La condición dura un año."},"zh":{"q":"在 Maine，第一次 OUI 定罪后，司机拿回的是有条件驾照，开车时完全不能有酒精。这个条件持续多久？","o":["30 天","6 个月","10 年","1 年"],"h1":"长得多的期限是给第二次定罪的。","h2":"在 Maine，第一次 OUI 定罪后，恢复的驾照有条件限制一年。","p":"对。这个条件持续一年。"},"vi":{"q":"Ở Maine, sau lần đầu bị kết tội OUI, người lái xe được cấp lại bằng lái có điều kiện, không được có chút cồn nào khi lái xe. Điều kiện này kéo dài bao lâu?","o":["30 ngày","6 tháng","10 năm","1 năm"],"h1":"Thời gian dài hơn nhiều là dành cho lần bị kết tội thứ hai.","h2":"Ở Maine, sau lần đầu bị kết tội OUI, bằng lái được cấp lại có điều kiện trong một năm.","p":"Đúng. Điều kiện kéo dài một năm."},"tl":{"q":"Sa Maine, pagkatapos ng unang paghatol ng OUI, ibinabalik sa driver ang conditional license na hindi pumapayag ng kahit anong alak habang nagmamaneho. Gaano katagal ang kondisyong ito?","o":["30 araw","6 na buwan","10 taon","1 taon"],"h1":"Ang mas mahabang panahon ay para sa ikalawang paghatol.","h2":"Sa Maine, pagkatapos ng unang paghatol ng OUI, conditional ang ibinalik na lisensya nang isang taon.","p":"Tama. Isang taon ang kondisyon."},"ar":{"q":"في Maine، بعد الإدانة الأولى بتهمة OUI، يستعيد السائق رخصة مشروطة لا تسمح بأي كحول أبدًا أثناء القيادة. كم مدة هذا الشرط؟","o":["30 يومًا","6 أشهر","10 سنوات","سنة واحدة (1)"],"h1":"المدة الأطول بكثير هي للإدانة الثانية.","h2":"في Maine بعد الإدانة الأولى بتهمة OUI، تكون الرخصة المستعادة مشروطة لمدة سنة واحدة.","p":"صحيح. يستمر الشرط سنة واحدة."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-041","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a 6-year-old child weighs 65 pounds. How must the child ride in the car?","o":["In a regular seat belt only","In a federally approved booster seat","In a rear-facing infant seat","On an adult's lap with a belt"],"h1":"The child is under 8 and weighs between 55 and 80 pounds.","h2":"In Maine, a child under 8 who weighs at least 55 but less than 80 pounds must ride in a federally approved child restraint system, such as a booster seat.","p":"Right. This child needs a booster seat."},"es":{"q":"En Maine, un niño de 6 años pesa 65 libras. ¿Cómo debe viajar en el carro?","o":["Solo con el cinturón de seguridad normal","En un asiento elevador aprobado por el gobierno federal","En un asiento para bebé mirando hacia atrás","En las piernas de un adulto con cinturón"],"h1":"El niño tiene menos de 8 años y pesa entre 55 y 80 libras.","h2":"En Maine, un niño menor de 8 años que pesa por lo menos 55 pero menos de 80 libras debe viajar en un sistema de retención infantil aprobado por el gobierno federal, como un asiento elevador.","p":"Correcto. Este niño necesita un asiento elevador."},"zh":{"q":"在 Maine，一个 6 岁的孩子体重 65 磅。孩子在车里必须怎么坐？","o":["只系普通的安全带","坐在联邦批准的加高座椅（booster seat）上","坐在朝后的婴儿座椅上","系着安全带坐在大人腿上"],"h1":"这个孩子不到 8 岁，体重在 55 到 80 磅之间。","h2":"在 Maine，不到 8 岁、体重至少 55 磅但不到 80 磅的孩子，必须坐在联邦批准的儿童约束系统里，例如加高座椅。","p":"对。这个孩子需要加高座椅。"},"vi":{"q":"Ở Maine, một em bé 6 tuổi nặng 65 pound. Em phải ngồi trong xe như thế nào?","o":["Chỉ thắt dây an toàn thông thường","Ngồi ghế nâng (booster seat) được liên bang chấp thuận","Ngồi ghế trẻ sơ sinh quay mặt về phía sau","Ngồi trên đùi người lớn có thắt dây"],"h1":"Em bé dưới 8 tuổi và nặng từ 55 đến 80 pound.","h2":"Ở Maine, trẻ dưới 8 tuổi nặng ít nhất 55 pound nhưng dưới 80 pound phải ngồi trong hệ thống ghế an toàn cho trẻ em được liên bang chấp thuận, ví dụ như ghế nâng.","p":"Đúng. Em bé này cần ghế nâng."},"tl":{"q":"Sa Maine, 65 pounds ang timbang ng isang 6 na taong gulang na bata. Paano dapat sumakay ang bata sa kotse?","o":["Sa regular na seat belt lang","Sa booster seat na aprubado ng federal","Sa infant seat na nakaharap sa likod","Sa kandungan ng adult na may belt"],"h1":"Wala pang 8 taong gulang ang bata at 55 hanggang 80 pounds ang timbang.","h2":"Sa Maine, ang batang wala pang 8 taong gulang na hindi bababa sa 55 pero wala pang 80 pounds ang timbang ay dapat sumakay sa child restraint system na aprubado ng federal, gaya ng booster seat.","p":"Tama. Kailangan ng batang ito ng booster seat."},"ar":{"q":"في Maine، طفل عمره 6 سنوات ووزنه 65 رطلًا. كيف يجب أن يركب الطفل في السيارة؟","o":["بحزام الأمان العادي فقط","في مقعد رافع (booster seat) معتمد فيدراليًا","في مقعد رضيع يواجه الخلف","في حضن شخص بالغ مع حزام"],"h1":"عمر الطفل أقل من 8 سنوات ووزنه بين 55 و80 رطلًا.","h2":"في Maine يجب أن يركب الطفل الذي عمره أقل من 8 سنوات ووزنه 55 رطلًا على الأقل وأقل من 80 رطلًا في نظام تثبيت للأطفال معتمد فيدراليًا، مثل المقعد الرافع.","p":"صحيح. هذا الطفل يحتاج إلى مقعد رافع."},"ref":{"doc":"ME","page":"4-5"}},{"id":"me-042","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, what is the speed limit when passing a school during recess or when children are going to or from school?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"It is lower than the 25 mph limit in town.","h2":"In Maine, the speed limit near a school during recess or school arrival and dismissal times is 15 mph.","p":"Right. It is 15 mph."},"es":{"q":"En Maine, ¿cuál es el límite de velocidad al pasar por una escuela durante el recreo o cuando los niños van o vienen de la escuela?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"Es más bajo que el límite de 25 mph en la ciudad.","h2":"En Maine, el límite de velocidad cerca de una escuela durante el recreo o en las horas de entrada y salida es de 15 mph.","p":"Correcto. Es de 15 mph."},"zh":{"q":"在 Maine，在课间休息或孩子上学、放学时经过学校，限速是多少？","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"它比市区的 25 mph 限速低。","h2":"在 Maine，在课间休息或上学、放学时间，学校附近的限速是 15 mph。","p":"对。是 15 mph。"},"vi":{"q":"Ở Maine, giới hạn tốc độ khi đi qua trường học trong giờ ra chơi hoặc khi trẻ em đi học hay tan học là bao nhiêu?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"Thấp hơn giới hạn 25 mph trong thị trấn.","h2":"Ở Maine, giới hạn tốc độ gần trường học trong giờ ra chơi hoặc giờ đến trường và tan học là 15 mph.","p":"Đúng. Là 15 mph."},"tl":{"q":"Sa Maine, ano ang speed limit kapag dumadaan sa paaralan habang recess o kapag papasok o pauwi ang mga bata?","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"Mas mababa ito sa 25 mph na limit sa bayan.","h2":"Sa Maine, 15 mph ang speed limit malapit sa paaralan habang recess o sa oras ng pagpasok at pag-uwi ng mga bata.","p":"Tama. 15 mph ito."},"ar":{"q":"في Maine، ما حد السرعة عند المرور بمدرسة أثناء الاستراحة أو عندما يذهب الأطفال إلى المدرسة أو يعودون منها؟","o":["15 mph","20 mph","25 mph","10 mph"],"h1":"إنه أقل من حد 25 mph داخل المدينة.","h2":"في Maine حد السرعة قرب المدرسة أثناء الاستراحة أو وقت وصول الطلاب وانصرافهم هو 15 mph.","p":"صحيح. إنه 15 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-043","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, what is the top speed in a business or residential area when no speed limit is posted?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"It is lower than 30 mph.","h2":"In Maine, the top speed in a business district, residential district or built-up area is 25 mph unless a sign says otherwise.","p":"Right. It is 25 mph."},"es":{"q":"En Maine, ¿cuál es la velocidad máxima en una zona comercial o residencial cuando no hay un límite de velocidad señalado?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Es menos de 30 mph.","h2":"En Maine, la velocidad máxima en una zona comercial, residencial o urbanizada es de 25 mph, a menos que una señal indique otra cosa.","p":"Correcto. Es de 25 mph."},"zh":{"q":"在 Maine，商业区或住宅区没有标出限速时，最高速度是多少？","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"它比 30 mph 低。","h2":"在 Maine，除非有标志另外说明，商业区、住宅区或建筑密集区的最高速度是 25 mph。","p":"对。是 25 mph。"},"vi":{"q":"Ở Maine, tốc độ tối đa trong khu thương mại hoặc khu dân cư khi không có biển giới hạn tốc độ là bao nhiêu?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Thấp hơn 30 mph.","h2":"Ở Maine, tốc độ tối đa trong khu thương mại, khu dân cư hoặc khu đông nhà cửa là 25 mph, trừ khi có biển báo khác.","p":"Đúng. Là 25 mph."},"tl":{"q":"Sa Maine, ano ang pinakamataas na bilis sa business o residential area kapag walang nakapaskil na speed limit?","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"Mas mababa ito sa 30 mph.","h2":"Sa Maine, 25 mph ang pinakamataas na bilis sa business district, residential district o built-up area maliban kung iba ang sinasabi ng karatula.","p":"Tama. 25 mph ito."},"ar":{"q":"في Maine، ما أعلى سرعة في منطقة تجارية أو سكنية عندما لا يوجد حد سرعة مكتوب؟","o":["15 mph","35 mph","25 mph","30 mph"],"h1":"إنها أقل من 30 mph.","h2":"في Maine أعلى سرعة في المنطقة التجارية أو السكنية أو المنطقة المبنية هي 25 mph ما لم تقل لافتة غير ذلك.","p":"صحيح. إنها 25 mph."},"ref":{"doc":"ME","page":"8-7"}},{"id":"me-044","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, what following distance does the driver manual tell you to keep behind the vehicle ahead?","o":["1 second","2 seconds","At least 4 seconds","At least 10 seconds"],"h1":"Count \"one-thousand-one\" and keep going past three.","h2":"In Maine, the driver manual says to keep at least 4 seconds between your car and the vehicle in front.","p":"Right. Keep at least 4 seconds."},"es":{"q":"En Maine, ¿qué distancia de seguimiento le indica el manual del conductor que mantenga detrás del vehículo de adelante?","o":["1 segundo","2 segundos","Por lo menos 4 segundos","Por lo menos 10 segundos"],"h1":"Cuente \"mil uno\" y siga después del tres.","h2":"En Maine, el manual del conductor dice que debe mantener por lo menos 4 segundos entre su carro y el vehículo de adelante.","p":"Correcto. Mantenga por lo menos 4 segundos."},"zh":{"q":"在 Maine，驾驶手册要你和前车保持多少跟车距离？","o":["1 秒","2 秒","至少 4 秒","至少 10 秒"],"h1":"数“一千零一”，数过三之后还要继续数。","h2":"在 Maine，驾驶手册说你的车和前车之间要保持至少 4 秒。","p":"对。保持至少 4 秒。"},"vi":{"q":"Ở Maine, sổ tay lái xe bảo bạn giữ khoảng cách bao nhiêu với xe phía trước?","o":["1 giây","2 giây","Ít nhất 4 giây","Ít nhất 10 giây"],"h1":"Đếm \"một nghìn lẻ một\" và tiếp tục đếm quá ba.","h2":"Ở Maine, sổ tay lái xe nói phải giữ ít nhất 4 giây giữa xe của bạn và xe phía trước.","p":"Đúng. Giữ ít nhất 4 giây."},"tl":{"q":"Sa Maine, anong following distance ang sinasabi ng driver manual na panatilihin mo sa likod ng sasakyan sa unahan?","o":["1 segundo","2 segundo","Hindi bababa sa 4 na segundo","Hindi bababa sa 10 segundo"],"h1":"Magbilang ng \"one-thousand-one\" at magpatuloy lampas sa tatlo.","h2":"Sa Maine, sinasabi ng driver manual na panatilihin ang hindi bababa sa 4 na segundo sa pagitan ng iyong kotse at ng sasakyan sa unahan.","p":"Tama. Panatilihin ang hindi bababa sa 4 na segundo."},"ar":{"q":"في Maine، ما مسافة المتابعة التي يطلب منك دليل السائق أن تتركها خلف المركبة التي أمامك؟","o":["ثانية واحدة (1)","ثانيتان (2)","4 ثوانٍ على الأقل","10 ثوانٍ على الأقل"],"h1":"عُدّ \"ألف وواحد\" واستمر بعد الثلاثة.","h2":"في Maine يقول دليل السائق إن عليك أن تترك 4 ثوانٍ على الأقل بين سيارتك والمركبة التي أمامك.","p":"صحيح. اترك 4 ثوانٍ على الأقل."},"ref":{"doc":"ME","page":"8-11"}},{"id":"me-045","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, you must turn on your headlights when it is too dark, foggy or snowy to see how far ahead?","o":["1,000 feet","100 feet","300 feet","5,000 feet"],"h1":"It is more than 500 feet.","h2":"In Maine, you must turn on your headlights whenever you cannot see 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, turn on your headlights."},"es":{"q":"En Maine, si por oscuridad, neblina o nieve no puede ver hasta cierta distancia hacia adelante, debe encender las luces delanteras. ¿Cuál es esa distancia?","o":["1,000 pies","100 pies","300 pies","5,000 pies"],"h1":"Es más de 500 pies.","h2":"En Maine, debe encender las luces delanteras siempre que no pueda ver 1,000 pies hacia adelante.","p":"Correcto. Si no puede ver 1,000 pies hacia adelante, encienda las luces."},"zh":{"q":"在 Maine，天太黑、有雾或下雪，看不到前方多远时，你必须打开前大灯？","o":["1,000 英尺","100 英尺","300 英尺","5,000 英尺"],"h1":"它比 500 英尺多。","h2":"在 Maine，只要你看不到前方 1,000 英尺，就必须打开前大灯。","p":"对。看不到前方 1,000 英尺，就打开前大灯。"},"vi":{"q":"Ở Maine, bạn phải bật đèn pha khi trời quá tối, có sương mù hoặc tuyết đến mức không thấy được bao xa phía trước?","o":["1,000 feet","100 feet","300 feet","5,000 feet"],"h1":"Hơn 500 feet.","h2":"Ở Maine, bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn thấy 1,000 feet phía trước.","p":"Đúng. Nếu không thấy được 1,000 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Maine, dapat mong buksan ang headlights kapag sobrang dilim, maulap o maniyebe para makita ang gaano kalayo sa unahan?","o":["1,000 talampakan","100 talampakan","300 talampakan","5,000 talampakan"],"h1":"Higit ito sa 500 talampakan.","h2":"Sa Maine, dapat mong buksan ang headlights tuwing hindi mo makita ang 1,000 talampakan sa unahan.","p":"Tama. Kung hindi mo makita ang 1,000 talampakan sa unahan, buksan ang headlights."},"ar":{"q":"في Maine، يجب أن تشغّل المصابيح الأمامية عندما يكون الظلام أو الضباب أو الثلج شديدًا بحيث لا ترى إلى أي مسافة أمامك؟","o":["1,000 قدم","100 قدم","300 قدم","5,000 قدم"],"h1":"إنها أكثر من 500 قدم.","h2":"في Maine يجب أن تشغّل المصابيح الأمامية كلما لم تستطع أن ترى 1,000 قدم أمامك.","p":"صحيح. إذا لم تستطع أن ترى 1,000 قدم أمامك، شغّل المصابيح الأمامية."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-046","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, when you park next to a curb, what is the farthest your car may be from the curb?","o":["6 feet","3 feet","30 inches","18 inches"],"h1":"It is less than two feet.","h2":"In Maine, when you park next to a curb, park as close to it as you can and no more than 18 inches away.","p":"Right. Park no more than 18 inches from the curb."},"es":{"q":"En Maine, cuando se estaciona junto a la acera, ¿cuál es la distancia máxima a la que puede quedar su carro de la acera?","o":["6 pies","3 pies","30 pulgadas","18 pulgadas"],"h1":"Es menos de dos pies.","h2":"En Maine, cuando se estaciona junto a la acera, debe quedar lo más cerca posible y a no más de 18 pulgadas.","p":"Correcto. Estaciónese a no más de 18 pulgadas de la acera."},"zh":{"q":"在 Maine，你靠路边石停车时，车离路边石最远可以多远？","o":["6 英尺","3 英尺","30 英寸","18 英寸"],"h1":"它不到两英尺。","h2":"在 Maine，你靠路边石停车时，要尽量靠近，离路边石不能超过 18 英寸。","p":"对。停车时离路边石不超过 18 英寸。"},"vi":{"q":"Ở Maine, khi bạn đậu xe sát lề đường, xe của bạn được cách lề đường xa nhất là bao nhiêu?","o":["6 feet","3 feet","30 inch","18 inch"],"h1":"Ít hơn hai feet.","h2":"Ở Maine, khi bạn đậu xe sát lề đường, hãy đậu càng gần càng tốt và không cách xa quá 18 inch.","p":"Đúng. Đậu xe cách lề đường không quá 18 inch."},"tl":{"q":"Sa Maine, kapag pumarada ka sa tabi ng curb, ano ang pinakamalayong puwedeng layo ng kotse mo sa curb?","o":["6 na talampakan","3 talampakan","30 pulgada","18 pulgada"],"h1":"Mas maikli ito sa dalawang talampakan.","h2":"Sa Maine, kapag pumarada ka sa tabi ng curb, pumarada nang pinakamalapit hangga't kaya at hindi lalayo nang higit sa 18 pulgada.","p":"Tama. Pumarada nang hindi lalayo nang higit sa 18 pulgada mula sa curb."},"ar":{"q":"في Maine، عندما تركن بجانب الرصيف، ما أبعد مسافة مسموح أن تكون فيها سيارتك عن الرصيف؟","o":["6 أقدام","3 أقدام","30 بوصة","18 بوصة"],"h1":"إنها أقل من قدمين.","h2":"في Maine عندما تركن بجانب الرصيف، اركن أقرب ما يمكن إليه وعلى بعد لا يزيد على 18 بوصة.","p":"صحيح. اركن على بعد لا يزيد على 18 بوصة من الرصيف."},"ref":{"doc":"ME","page":"7-9"}},{"id":"me-047","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","As close as you like if you are careful"],"h1":"It is several hundred feet.","h2":"In Maine, it is against the law to follow within 500 feet of a fire truck that is going to a fire alarm.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Maine, un camión de bomberos va a atender una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No a menos de 100 pies","No a menos de 500 pies","No a menos de 50 pies","Tan cerca como quiera si tiene cuidado"],"h1":"Son varios cientos de pies.","h2":"En Maine, es ilegal seguir a menos de 500 pies a un camión de bomberos que va a atender una alarma de incendio.","p":"Correcto. Manténgase por lo menos a 500 pies."},"zh":{"q":"在 Maine，一辆消防车正赶去火警现场。你最近可以跟在它后面多近？","o":["不能近于 100 英尺","不能近于 500 英尺","不能近于 50 英尺","只要小心，多近都可以"],"h1":"是几百英尺。","h2":"在 Maine，跟在赶去火警现场的消防车后面 500 英尺之内是违法的。","p":"对。要保持至少 500 英尺的距离。"},"vi":{"q":"Ở Maine, một xe cứu hỏa đang chạy đến nơi có báo cháy. Bạn được đi theo sau xe đó gần đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 50 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận"],"h1":"Vài trăm feet.","h2":"Ở Maine, đi theo sau xe cứu hỏa đang chạy đến nơi báo cháy trong vòng 500 feet là phạm luật.","p":"Đúng. Hãy giữ khoảng cách ít nhất 500 feet."},"tl":{"q":"Sa Maine, papunta sa fire alarm ang isang fire truck. Gaano kalapit puwede kang sumunod sa likod nito?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 500 talampakan","Hindi lalapit sa 50 talampakan","Kahit gaano kalapit basta mag-ingat ka"],"h1":"Ilang daang talampakan ito.","h2":"Sa Maine, labag sa batas ang sumunod sa loob ng 500 talampakan sa fire truck na papunta sa fire alarm.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod."},"ar":{"q":"في Maine، شاحنة إطفاء متجهة إلى إنذار حريق. إلى أي مدى يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 500 قدم","ليس أقرب من 50 قدمًا","بقدر ما تريد إذا كنت حذرًا"],"h1":"إنها بضع مئات من الأقدام.","h2":"في Maine السير خلف شاحنة إطفاء متجهة إلى إنذار حريق على مسافة أقل من 500 قدم مخالف للقانون.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل."},"ref":{"doc":"ME","page":"10-9"}},{"id":"me-048","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, the red lights are flashing at a railroad crossing. Where must you stop?","o":["At least 15 feet from the crossing","Right at the edge of the first rail","At least 5 feet from the crossing","Nowhere, if you slow down and look"],"h1":"Leave room between your car and the tracks.","h2":"In Maine, when the red lights flash at a railroad crossing, you must stop at least 15 feet from the crossing and wait.","p":"Right. Stop at least 15 feet away."},"es":{"q":"En Maine, las luces rojas están intermitentes en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Por lo menos a 15 pies del cruce","Justo en el borde del primer riel","Por lo menos a 5 pies del cruce","En ningún lugar, si baja la velocidad y mira"],"h1":"Deje espacio entre su carro y las vías.","h2":"En Maine, cuando las luces rojas están intermitentes en un cruce de ferrocarril, debe detenerse por lo menos a 15 pies del cruce y esperar.","p":"Correcto. Deténgase por lo menos a 15 pies."},"zh":{"q":"在 Maine，铁路道口的红灯在闪。你必须在哪里停车？","o":["离道口至少 15 英尺","就在第一条铁轨的边上","离道口至少 5 英尺","不用停，只要减速并看清楚"],"h1":"在你的车和铁轨之间留出空间。","h2":"在 Maine，铁路道口的红灯闪烁时，你必须在离道口至少 15 英尺的地方停车并等待。","p":"对。在至少 15 英尺外停车。"},"vi":{"q":"Ở Maine, đèn đỏ đang nhấp nháy tại chỗ giao với đường xe lửa. Bạn phải dừng lại ở đâu?","o":["Cách chỗ giao ít nhất 15 feet","Ngay sát mép đường ray đầu tiên","Cách chỗ giao ít nhất 5 feet","Không cần dừng, nếu bạn chạy chậm và nhìn"],"h1":"Chừa khoảng trống giữa xe của bạn và đường ray.","h2":"Ở Maine, khi đèn đỏ nhấp nháy tại chỗ giao với đường xe lửa, bạn phải dừng lại cách chỗ giao ít nhất 15 feet và chờ.","p":"Đúng. Dừng lại cách ít nhất 15 feet."},"tl":{"q":"Sa Maine, kumikislap ang pulang ilaw sa railroad crossing. Saan ka dapat huminto?","o":["Hindi bababa sa 15 talampakan mula sa crossing","Mismo sa gilid ng unang riles","Hindi bababa sa 5 talampakan mula sa crossing","Hindi na kailangan, basta magbagal at tumingin"],"h1":"Mag-iwan ng espasyo sa pagitan ng kotse mo at ng riles.","h2":"Sa Maine, kapag kumikislap ang pulang ilaw sa railroad crossing, dapat kang huminto nang hindi bababa sa 15 talampakan mula sa crossing at maghintay.","p":"Tama. Huminto nang hindi bababa sa 15 talampakan ang layo."},"ar":{"q":"في Maine، الأضواء الحمراء تومض عند معبر سكة حديد. أين يجب أن تتوقف؟","o":["على بعد 15 قدمًا على الأقل من المعبر","عند حافة القضيب الأول مباشرة","على بعد 5 أقدام على الأقل من المعبر","لا تتوقف، إذا أبطأت ونظرت"],"h1":"اترك مسافة بين سيارتك والقضبان.","h2":"في Maine عندما تومض الأضواء الحمراء عند معبر سكة حديد، يجب أن تتوقف على بعد 15 قدمًا على الأقل من المعبر وتنتظر.","p":"صحيح. توقف على بعد 15 قدمًا على الأقل."},"ref":{"doc":"ME","page":"8-3"}},{"id":"me-049","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, you are passing a car on a two-lane road. By when must you finish the pass?","o":["Before the next intersection only","Within 30 seconds","After the no passing zone ends","Before you reach the start of a no passing zone"],"h1":"Think about where the solid line on your side begins.","h2":"In Maine, the law says you must finish a pass before you reach the beginning of a no passing zone.","p":"Right. Finish passing before the no passing zone begins."},"es":{"q":"En Maine, usted está rebasando a un carro en una carretera de dos carriles. ¿Para cuándo debe terminar de rebasar?","o":["Solo antes de la próxima intersección","Dentro de 30 segundos","Después de que termine la zona de no rebasar","Antes de llegar al comienzo de una zona de no rebasar"],"h1":"Piense en dónde empieza la línea continua de su lado.","h2":"En Maine, la ley dice que debe terminar de rebasar antes de llegar al comienzo de una zona de no rebasar.","p":"Correcto. Termine de rebasar antes de que empiece la zona de no rebasar."},"zh":{"q":"在 Maine，你在双车道道路上超车。你必须在什么时候之前完成超车？","o":["只要在下一个路口之前","30 秒之内","禁止超车区结束以后","在到达禁止超车区的起点之前"],"h1":"想一想你这一边的实线从哪里开始。","h2":"在 Maine，法律规定你必须在到达禁止超车区的起点之前完成超车。","p":"对。在禁止超车区开始之前完成超车。"},"vi":{"q":"Ở Maine, bạn đang vượt một xe trên đường hai làn. Bạn phải vượt xong trước khi nào?","o":["Chỉ cần trước giao lộ kế tiếp","Trong vòng 30 giây","Sau khi hết khu vực cấm vượt","Trước khi bạn đến chỗ bắt đầu khu vực cấm vượt"],"h1":"Hãy nghĩ xem vạch liền phía bên bạn bắt đầu ở đâu.","h2":"Ở Maine, luật nói bạn phải vượt xong trước khi đến chỗ bắt đầu của khu vực cấm vượt.","p":"Đúng. Vượt xong trước khi khu vực cấm vượt bắt đầu."},"tl":{"q":"Sa Maine, nag-o-overtake ka ng kotse sa kalsadang may dalawang lane. Kailan mo dapat matapos ang pag-overtake?","o":["Bago lang ang susunod na intersection","Sa loob ng 30 segundo","Pagkatapos ng no passing zone","Bago ka umabot sa simula ng no passing zone"],"h1":"Isipin kung saan nagsisimula ang tuloy-tuloy na linya sa iyong gilid.","h2":"Sa Maine, sinasabi ng batas na dapat mong tapusin ang pag-overtake bago ka umabot sa simula ng no passing zone.","p":"Tama. Tapusin ang pag-overtake bago magsimula ang no passing zone."},"ar":{"q":"في Maine، أنت تتجاوز سيارة على طريق ذي مسارين. متى يجب أن تنهي التجاوز؟","o":["قبل التقاطع التالي فقط","خلال 30 ثانية","بعد انتهاء منطقة منع التجاوز","قبل أن تصل إلى بداية منطقة منع التجاوز"],"h1":"فكّر أين يبدأ الخط المتصل في جهتك.","h2":"في Maine يقول القانون إنه يجب أن تنهي التجاوز قبل أن تصل إلى بداية منطقة منع التجاوز.","p":"صحيح. أنهِ التجاوز قبل أن تبدأ منطقة منع التجاوز."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-050","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a 16-year-old rides in a pickup truck to go shopping. Where must the teen ride?","o":["In the open cargo bed","Inside the passenger compartment","Anywhere, if the truck goes slowly","In the bed, if an adult rides there too"],"h1":"The rule covers passengers under 19.","h2":"In Maine, a passenger under 19 in a pickup truck must ride inside the passenger compartment, except in a few cases such as work or a parade.","p":"Right. The teen must ride inside the cab."},"es":{"q":"En Maine, un joven de 16 años va en una camioneta pickup de compras. ¿Dónde debe viajar?","o":["En la caja de carga abierta","Dentro de la cabina de pasajeros","En cualquier lugar, si la camioneta va despacio","En la caja, si un adulto también va allí"],"h1":"La regla cubre a los pasajeros menores de 19 años.","h2":"En Maine, un pasajero menor de 19 años en una camioneta pickup debe viajar dentro de la cabina de pasajeros, salvo en algunos casos como el trabajo o un desfile.","p":"Correcto. El joven debe viajar dentro de la cabina."},"zh":{"q":"在 Maine，一个 16 岁的青少年坐皮卡车去买东西。他必须坐在哪里？","o":["坐在敞开的货斗里","坐在乘客车厢里面","坐哪里都行，只要车开得慢","坐在货斗里，只要有大人也坐在那里"],"h1":"这条规定适用于不到 19 岁的乘客。","h2":"在 Maine，坐皮卡车的不到 19 岁的乘客必须坐在乘客车厢里面，只有少数情况例外，例如工作或游行。","p":"对。这个青少年必须坐在驾驶室里面。"},"vi":{"q":"Ở Maine, một thiếu niên 16 tuổi đi xe bán tải (pickup) để đi mua sắm. Thiếu niên đó phải ngồi ở đâu?","o":["Trong thùng chở hàng hở","Bên trong khoang hành khách","Ở đâu cũng được, nếu xe chạy chậm","Trong thùng xe, nếu có người lớn ngồi ở đó"],"h1":"Quy định này áp dụng cho hành khách dưới 19 tuổi.","h2":"Ở Maine, hành khách dưới 19 tuổi trên xe bán tải phải ngồi bên trong khoang hành khách, trừ một vài trường hợp như khi làm việc hoặc diễu hành.","p":"Đúng. Thiếu niên phải ngồi bên trong cabin."},"tl":{"q":"Sa Maine, sumakay ang isang 16 na taong gulang sa pickup truck para mamili. Saan dapat sumakay ang teenager?","o":["Sa bukas na cargo bed","Sa loob ng passenger compartment","Kahit saan, kung mabagal ang truck","Sa bed, kung may adult din doon"],"h1":"Saklaw ng patakaran ang mga pasaherong wala pang 19 taong gulang.","h2":"Sa Maine, ang pasaherong wala pang 19 taong gulang sa pickup truck ay dapat sumakay sa loob ng passenger compartment, maliban sa ilang kaso gaya ng trabaho o parada.","p":"Tama. Dapat sumakay ang teenager sa loob ng cab."},"ar":{"q":"في Maine، شاب عمره 16 سنة يركب شاحنة صغيرة (pickup) للذهاب إلى التسوق. أين يجب أن يركب؟","o":["في صندوق الحمولة المكشوف","داخل مقصورة الركاب","في أي مكان، إذا كانت الشاحنة بطيئة","في الصندوق، إذا ركب معه شخص بالغ هناك"],"h1":"القاعدة تشمل الركاب الذين عمرهم أقل من 19 سنة.","h2":"في Maine يجب أن يركب الراكب الذي عمره أقل من 19 سنة في الشاحنة الصغيرة داخل مقصورة الركاب، إلا في حالات قليلة مثل العمل أو الاستعراض.","p":"صحيح. يجب أن يركب الشاب داخل المقصورة."},"ref":{"doc":"ME","page":"11-8"}},{"id":"me-051","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, in which months do crashes with moose increase the most?","o":["January and February","December and March","May and June","July and August"],"h1":"It is late spring.","h2":"In Maine, crashes with moose rise sharply in May and June, though they can happen in any month.","p":"Right. May and June are the peak months for moose crashes."},"es":{"q":"En Maine, ¿en qué meses aumentan más los choques con alces (moose)?","o":["Enero y febrero","Diciembre y marzo","Mayo y junio","Julio y agosto"],"h1":"Es a finales de la primavera.","h2":"En Maine, los choques con alces aumentan mucho en mayo y junio, aunque pueden ocurrir en cualquier mes.","p":"Correcto. Mayo y junio son los meses con más choques con alces."},"zh":{"q":"在 Maine，哪几个月和驼鹿（moose）相撞的事故增加得最多？","o":["一月和二月","十二月和三月","五月和六月","七月和八月"],"h1":"是春天快结束的时候。","h2":"在 Maine，和驼鹿相撞的事故在五月和六月大幅增加，不过任何月份都可能发生。","p":"对。五月和六月是驼鹿事故最多的月份。"},"vi":{"q":"Ở Maine, tai nạn đụng nai sừng tấm (moose) tăng nhiều nhất vào những tháng nào?","o":["Tháng Một và tháng Hai","Tháng Mười Hai và tháng Ba","Tháng Năm và tháng Sáu","Tháng Bảy và tháng Tám"],"h1":"Đó là cuối mùa xuân.","h2":"Ở Maine, tai nạn đụng nai sừng tấm tăng mạnh vào tháng Năm và tháng Sáu, dù có thể xảy ra vào bất kỳ tháng nào.","p":"Đúng. Tháng Năm và tháng Sáu là những tháng có nhiều tai nạn đụng nai sừng tấm nhất."},"tl":{"q":"Sa Maine, sa anong mga buwan pinakadumarami ang banggaan sa moose?","o":["Enero at Pebrero","Disyembre at Marso","Mayo at Hunyo","Hulyo at Agosto"],"h1":"Huling bahagi ito ng tagsibol.","h2":"Sa Maine, biglang dumarami ang banggaan sa moose sa Mayo at Hunyo, kahit puwede itong mangyari sa anumang buwan.","p":"Tama. Mayo at Hunyo ang mga buwan na pinakamarami ang banggaan sa moose."},"ar":{"q":"في Maine، في أي أشهر تزيد حوادث الاصطدام بحيوان الموظ (moose) أكثر من غيرها؟","o":["يناير وفبراير","ديسمبر ومارس","مايو ويونيو","يوليو وأغسطس"],"h1":"إنها في آخر الربيع.","h2":"في Maine تزيد حوادث الاصطدام بحيوان الموظ كثيرًا في مايو ويونيو، مع أنها قد تحدث في أي شهر.","p":"صحيح. مايو ويونيو هما الشهران اللذان تكثر فيهما حوادث الموظ."},"ref":{"doc":"ME","page":"11-7"}},{"id":"me-052","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a 17-year-old visitor has a valid driver's license from their home state. May they drive in Maine?","o":["No, they must first pass a Maine road test","No, they must get a Maine learner's permit","Yes, a non-resident 16 or older with a valid home-state license may drive","Only if a Maine-licensed adult rides with them"],"h1":"Think about visitors who keep their home-state license.","h2":"In Maine, a non-resident who is at least 16 and holds a valid license or permit from their home state may drive without a Maine license.","p":"Right. A visitor 16 or older with a valid home-state license may drive in Maine."},"es":{"q":"En Maine, un visitante de 17 años tiene una licencia de conducir válida de su estado. ¿Puede manejar en Maine?","o":["No, primero debe aprobar un examen de manejo de Maine","No, debe obtener un permiso de aprendizaje de Maine","Sí, un no residente de 16 años o más con licencia válida de su estado puede manejar","Solo si lo acompaña un adulto con licencia de Maine"],"h1":"Piensa en los visitantes que conservan la licencia de su estado.","h2":"En Maine, un no residente de al menos 16 años con una licencia o permiso válido de su estado puede manejar sin licencia de Maine.","p":"Correcto. Un visitante de 16 años o más con licencia válida de su estado puede manejar en Maine."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-053","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a 16-year-old wants a learner's permit. What must they complete first, besides the written test?","o":["An approved driver education course","A 20-hour first aid class","A road test with an examiner","A year of bicycle safety training"],"h1":"It is a course that teaches driving.","h2":"In Maine, a person under 18 must complete an approved driver education course to get a learner's permit.","p":"Correct. Applicants under 18 need an approved driver education course."},"es":{"q":"En Maine, un joven de 16 años quiere un permiso de aprendizaje. Además del examen escrito, ¿qué debe completar primero?","o":["Un curso aprobado de educación vial","Una clase de primeros auxilios de 20 horas","Un examen de manejo con un examinador","Un año de capacitación en seguridad en bicicleta"],"h1":"Es un curso que enseña a manejar.","h2":"En Maine, una persona menor de 18 años debe completar un curso aprobado de educación vial para obtener el permiso de aprendizaje.","p":"Correcto. Los solicitantes menores de 18 años necesitan un curso aprobado de educación vial."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-054","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, you are driving a pickup truck with a learner's permit. What kind of license must your supervising driver hold?","o":["A commercial driver's license","Any license from any country","A motorcycle endorsement","A license for the class of vehicle you are driving"],"h1":"The supervisor must be allowed to drive the same kind of vehicle.","h2":"In Maine, the licensed driver supervising a permit holder must be licensed to drive the class of vehicle being driven.","p":"Right. The supervisor must be licensed for that class of vehicle."},"es":{"q":"En Maine, manejas una camioneta pickup con permiso de aprendizaje. ¿Qué tipo de licencia debe tener tu supervisor?","o":["Una licencia de conducir comercial","Cualquier licencia de cualquier país","Un endoso para motocicleta","Una licencia para la clase de vehículo que manejas"],"h1":"El supervisor debe poder manejar el mismo tipo de vehículo.","h2":"En Maine, el conductor con licencia que supervisa a quien tiene permiso debe tener licencia para la clase de vehículo que se maneja.","p":"Correcto. El supervisor debe tener licencia para esa clase de vehículo."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-055","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, up to what age must a license applicant show a birth certificate or passport to prove their date of birth?","o":["Up to age 18","Up to and including age 22","Up to and including age 30","Only under age 16"],"h1":"It is one year past 21.","h2":"In Maine, applicants up to and including age 22 must show a birth certificate or passport to prove their date of birth.","p":"Correct. Applicants 22 and younger need a birth certificate or passport."},"es":{"q":"En Maine, ¿hasta qué edad debe un solicitante mostrar un acta de nacimiento o un pasaporte para probar su fecha de nacimiento?","o":["Hasta los 18 años","Hasta los 22 años inclusive","Hasta los 30 años inclusive","Solo antes de los 16 años"],"h1":"Es un año después de los 21.","h2":"En Maine, los solicitantes de hasta 22 años inclusive deben mostrar un acta de nacimiento o un pasaporte para probar su fecha de nacimiento.","p":"Correcto. Los solicitantes de 22 años o menos necesitan acta de nacimiento o pasaporte."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-056","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, you bring a photocopy of your birth certificate to the license office. When is it accepted?","o":["When a notary has signed it","When it is printed in color","When it has the embossed seal or stamp of the issuing agency","When a parent signs the back"],"h1":"Notarized copies are not good enough.","h2":"In Maine, a photocopy of a birth certificate is accepted only if it has the embossed seal or stamp of the agency that issued it; notarized copies are not accepted.","p":"Right. It needs the issuing agency's embossed seal or stamp."},"es":{"q":"En Maine, llevas una fotocopia de tu acta de nacimiento a la oficina de licencias. ¿Cuándo la aceptan?","o":["Cuando un notario la ha firmado","Cuando está impresa a color","Cuando tiene el sello en relieve o timbre de la agencia que la emitió","Cuando uno de tus padres firma el reverso"],"h1":"Las copias notariadas no son suficientes.","h2":"En Maine, una fotocopia del acta de nacimiento se acepta solo si tiene el sello en relieve o timbre de la agencia que la emitió; las copias notariadas no se aceptan.","p":"Correcto. Necesita el sello en relieve o timbre de la agencia que la emitió."},"ref":{"doc":"ME","page":"1-2"}},{"id":"me-057","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how many classes of driver's license are there?","o":["3","2","4","5"],"h1":"They are named with letters A, B and C.","h2":"In Maine, there are 3 classes of driver's license: A, B and C.","p":"Correct. Maine has 3 license classes."},"es":{"q":"En Maine, ¿cuántas clases de licencia de conducir hay?","o":["3","2","4","5"],"h1":"Se nombran con las letras A, B y C.","h2":"En Maine hay 3 clases de licencia de conducir: A, B y C.","p":"Correcto. Maine tiene 3 clases de licencia."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-058","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, which license class is the standard license issued to most drivers of cars?","o":["Class A","Class B","Class D","Class C"],"h1":"It is the last of Maine's three letters.","h2":"In Maine, Class C is the standard license issued to most drivers.","p":"Right. Most drivers hold a Class C license."},"es":{"q":"En Maine, ¿qué clase de licencia es la estándar que se da a la mayoría de los conductores de autos?","o":["Clase A","Clase B","Clase D","Clase C"],"h1":"Es la última de las tres letras de Maine.","h2":"En Maine, la Clase C es la licencia estándar que se da a la mayoría de los conductores.","p":"Correcto. La mayoría de los conductores tiene licencia Clase C."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-059","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, which license class covers a single vehicle with a gross vehicle weight rating of 26,001 pounds or more?","o":["Class C","Class B","Class D","Class M"],"h1":"It is a commercial class, but not the one for combinations.","h2":"In Maine, a Class B license covers a single vehicle rated at 26,001 pounds or more.","p":"Correct. Class B covers heavy single vehicles."},"es":{"q":"En Maine, ¿qué clase de licencia cubre un solo vehículo con un peso bruto nominal de 26,001 libras o más?","o":["Clase C","Clase B","Clase D","Clase M"],"h1":"Es una clase comercial, pero no la de combinaciones.","h2":"En Maine, la licencia Clase B cubre un solo vehículo con un peso nominal de 26,001 libras o más.","p":"Correcto. La Clase B cubre vehículos sencillos pesados."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-060","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, how are school bus, passenger bus and motorcycle driving handled on a license?","o":["Each one is its own license class","They need no extra test","They need a special endorsement and a test","They are allowed on any Class C license"],"h1":"They are added on top of a class.","h2":"In Maine, school buses, passenger buses and motorcycles are not separate classes; each needs a special endorsement and a test for that vehicle.","p":"Right. They need an endorsement and a test."},"es":{"q":"En Maine, ¿cómo se maneja en la licencia el conducir autobús escolar, autobús de pasajeros y motocicleta?","o":["Cada uno es una clase de licencia propia","No necesitan examen adicional","Necesitan un endoso especial y un examen","Están permitidos con cualquier licencia Clase C"],"h1":"Se agregan a una clase.","h2":"En Maine, los autobuses escolares, autobuses de pasajeros y motocicletas no son clases separadas; cada uno necesita un endoso especial y un examen para ese vehículo.","p":"Correcto. Necesitan un endoso y un examen."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-061","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what is the youngest age to apply for a school bus driver's license?","o":["18","19","20","21"],"h1":"It is the same age as the legal drinking age.","h2":"In Maine, a school bus license applicant must be at least 21 and have at least one year of licensed driving experience.","p":"Correct. School bus drivers must be at least 21."},"es":{"q":"En Maine, ¿cuál es la edad mínima para solicitar una licencia de conductor de autobús escolar?","o":["18","19","20","21"],"h1":"Es la misma edad mínima para beber alcohol.","h2":"En Maine, quien solicita licencia de autobús escolar debe tener al menos 21 años y un año o más de experiencia con licencia.","p":"Correcto. Los conductores de autobús escolar deben tener al menos 21 años."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-062","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a person was convicted of OUI 8 years ago. Can they get a school bus operator's license?","o":["No, an OUI in the past ten years makes them ineligible","Yes, after a new road test","Yes, if they pay a higher fee","Yes, once they turn 25"],"h1":"Count back ten years.","h2":"In Maine, anyone convicted of OUI within the past ten years cannot get a school bus operator's license.","p":"Right. An OUI in the past ten years rules them out."},"es":{"q":"En Maine, una persona fue condenada por OUI hace 8 años. ¿Puede obtener licencia de operador de autobús escolar?","o":["No, una condena por OUI en los últimos diez años la descalifica","Sí, después de un nuevo examen de manejo","Sí, si paga una tarifa más alta","Sí, cuando cumpla 25 años"],"h1":"Cuenta diez años hacia atrás.","h2":"En Maine, nadie condenado por OUI en los últimos diez años puede obtener licencia de operador de autobús escolar.","p":"Correcto. Una condena por OUI en los últimos diez años la descalifica."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-063","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, which license may be used to drive a moped?","o":["Only a motorcycle license","A license of any class","Only a Class A license","Only a commercial license"],"h1":"Mopeds are small and slow.","h2":"In Maine, a moped may be driven on a driver's license of any class.","p":"Correct. Any license class allows a moped."},"es":{"q":"En Maine, ¿qué licencia se puede usar para manejar un ciclomotor (moped)?","o":["Solo una licencia de motocicleta","Una licencia de cualquier clase","Solo una licencia Clase A","Solo una licencia comercial"],"h1":"Los ciclomotores son pequeños y lentos.","h2":"En Maine, se puede manejar un ciclomotor con una licencia de conducir de cualquier clase.","p":"Correcto. Cualquier clase de licencia permite manejar un ciclomotor."},"ref":{"doc":"ME","page":"1-3"}},{"id":"me-064","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a teen has no parent, stepparent, guardian or spouse. Who else may certify the teen's practice driving hours?","o":["A classmate","The teen alone","An employer","A neighbor under 18"],"h1":"Think of an adult who knows the teen through work.","h2":"In Maine, when a teen has no parent, stepparent, guardian or spouse, an employer may certify the practice driving time.","p":"Right. An employer may certify the hours."},"es":{"q":"En Maine, un adolescente no tiene padre, padrastro, tutor ni cónyuge. ¿Quién más puede certificar sus horas de práctica?","o":["Un compañero de clase","El propio adolescente","Un empleador","Un vecino menor de 18 años"],"h1":"Piensa en un adulto que lo conoce por el trabajo.","h2":"En Maine, cuando un adolescente no tiene padre, padrastro, tutor ni cónyuge, un empleador puede certificar las horas de práctica.","p":"Correcto. Un empleador puede certificar las horas."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-065","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, where do you send the road test request form or driving log when you are ready for the road test?","o":["To your driver education school","To your local police station","To your town office","To the Motor Vehicles main office in Augusta"],"h1":"It is the state capital.","h2":"In Maine, you mail the road test request form or driving log to the Bureau of Motor Vehicles main office in Augusta.","p":"Correct. It goes to the main office in Augusta."},"es":{"q":"En Maine, ¿a dónde envías el formulario de solicitud del examen de manejo o el registro de práctica cuando estás listo?","o":["A tu escuela de manejo","A tu estación de policía local","A la oficina de tu municipio","A la oficina principal de Vehículos Motorizados en Augusta"],"h1":"Es la capital del estado.","h2":"En Maine, envías por correo el formulario de solicitud o el registro de práctica a la oficina principal de la BMV en Augusta.","p":"Correcto. Se envía a la oficina principal en Augusta."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-066","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, what vehicle do you use for the road test?","o":["Your own vehicle, registered and inspected","A vehicle loaned by the examiner","A state police cruiser","Any vehicle, even if not inspected"],"h1":"You bring it, and you bring its registration.","h2":"In Maine, you must provide your own properly registered and inspected vehicle for the road test.","p":"Right. You bring your own registered, inspected vehicle."},"es":{"q":"En Maine, ¿qué vehículo usas para el examen de manejo?","o":["Tu propio vehículo, registrado e inspeccionado","Un vehículo prestado por el examinador","Una patrulla de la policía estatal","Cualquier vehículo, aunque no esté inspeccionado"],"h1":"Tú lo llevas, junto con su registro.","h2":"En Maine, debes llevar tu propio vehículo, debidamente registrado e inspeccionado, para el examen de manejo.","p":"Correcto. Llevas tu propio vehículo registrado e inspeccionado."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-067","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, your road test is scheduled on a day with snow and ice. What can you do?","o":["Nothing; you must take the test","Choose to reschedule at no fee","Pay a fee to reschedule","Take the test in the examiner's car"],"h1":"Maine allows a free change for bad winter weather.","h2":"In Maine, if snow or ice hits on your road test day, you may choose to reschedule at no fee.","p":"Correct. You can reschedule for free."},"es":{"q":"En Maine, tu examen de manejo es un día con nieve y hielo. ¿Qué puedes hacer?","o":["Nada; debes presentar el examen","Elegir cambiar la fecha sin costo","Pagar una tarifa para cambiar la fecha","Presentar el examen en el auto del examinador"],"h1":"Maine permite un cambio gratis por mal tiempo de invierno.","h2":"En Maine, si hay nieve o hielo el día de tu examen de manejo, puedes elegir cambiar la fecha sin costo.","p":"Correcto. Puedes cambiar la fecha gratis."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-068","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a 17-year-old with a new license wants to drive a foreign exchange student who lives with the family. Is that allowed?","o":["No, only parents count as family","No, never during the first year","Yes, a foreign exchange student living with the family counts as immediate family","Only with a note from the school"],"h1":"Maine's list of immediate family is broad.","h2":"In Maine, a foreign exchange student living with the family counts as immediate family, so a newly licensed teen may carry that student.","p":"Right. A live-in exchange student counts as family."},"es":{"q":"En Maine, un joven de 17 años con licencia nueva quiere llevar a un estudiante de intercambio que vive con su familia. ¿Está permitido?","o":["No, solo los padres cuentan como familia","No, nunca durante el primer año","Sí, un estudiante de intercambio que vive con la familia cuenta como familia inmediata","Solo con una nota de la escuela"],"h1":"La lista de familia inmediata en Maine es amplia.","h2":"En Maine, un estudiante de intercambio que vive con la familia cuenta como familia inmediata, así que el joven con licencia nueva puede llevarlo.","p":"Correcto. Un estudiante de intercambio que vive en casa cuenta como familia."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-069","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a 17-year-old breaks the new-driver passenger rule just before turning 18. What is true about the 270-day extension?","o":["It ends on the 18th birthday","It is cancelled at 18","It only applies to drivers 16 or younger","It may extend past the 18th birthday"],"h1":"Turning 18 does not wipe it out.","h2":"In Maine, the 270-day extension after a violation may run past the driver's 18th birthday.","p":"Correct. The extension can go beyond the 18th birthday."},"es":{"q":"En Maine, un joven de 17 años rompe la regla de pasajeros para conductores nuevos poco antes de cumplir 18. ¿Qué es cierto sobre la extensión de 270 días?","o":["Termina al cumplir 18 años","Se cancela a los 18","Solo aplica a conductores de 16 años o menos","Puede continuar después de cumplir 18 años"],"h1":"Cumplir 18 no la borra.","h2":"En Maine, la extensión de 270 días después de una infracción puede continuar después del cumpleaños 18 del conductor.","p":"Correcto. La extensión puede ir más allá de los 18 años."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-070","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a person gets their first driver's license at age 25. How long is that license provisional?","o":["1 year","2 years","6 months","3 years"],"h1":"It is shorter than for drivers under 21.","h2":"In Maine, a first license is provisional for one year when the new driver is 21 or older.","p":"Right. For new drivers 21 or older it is one year."},"es":{"q":"En Maine, una persona obtiene su primera licencia a los 25 años. ¿Por cuánto tiempo es provisional esa licencia?","o":["1 año","2 años","6 meses","3 años"],"h1":"Es menos tiempo que para menores de 21.","h2":"En Maine, la primera licencia es provisional por un año cuando el nuevo conductor tiene 21 años o más.","p":"Correcto. Para conductores nuevos de 21 años o más es un año."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-071","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, which topic gets special emphasis on the written license test?","o":["Car repair","Maine's drinking and driving laws","State history","Fuel economy"],"h1":"Maine wants new drivers to know about alcohol.","h2":"In Maine, the written test places special emphasis on understanding Maine's drinking and driving laws.","p":"Correct. Drinking and driving laws get special emphasis."},"es":{"q":"En Maine, ¿qué tema recibe atención especial en el examen escrito de licencia?","o":["Reparación de autos","Las leyes de Maine sobre beber y manejar","La historia del estado","El ahorro de combustible"],"h1":"Maine quiere que los conductores nuevos sepan sobre el alcohol.","h2":"En Maine, el examen escrito pone especial énfasis en entender las leyes de Maine sobre beber y manejar.","p":"Correcto. Las leyes sobre beber y manejar reciben atención especial."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-072","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, the vision screening for a license checks how clearly you see and what else?","o":["Your color of eyes","Your night driving record","Your side (peripheral) vision","Your reading speed"],"h1":"It is how far you can see to each side while looking ahead.","h2":"In Maine, the vision screening measures visual acuity and peripheral vision, which is how far you see to the sides while looking straight ahead.","p":"Right. It checks clearness and side vision."},"es":{"q":"En Maine, la prueba de la vista para la licencia mide qué tan claro ves y ¿qué más?","o":["El color de tus ojos","Tu historial de manejo de noche","Tu visión lateral (periférica)","Tu velocidad de lectura"],"h1":"Es cuánto ves hacia los lados mientras miras al frente.","h2":"En Maine, la prueba de la vista mide la agudeza visual y la visión periférica, es decir, cuánto ves a los lados mientras miras al frente.","p":"Correcto. Mide la claridad y la visión lateral."},"ref":{"doc":"ME","page":"1-4"}},{"id":"me-073","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, when is the road test given to a new applicant?","o":["Before the written test","Before the vision screening","On the same day the permit is issued","Only after all other tests are passed"],"h1":"It comes last.","h2":"In Maine, the road test is not given until all the other tests have been passed.","p":"Correct. The road test comes after all other tests."},"es":{"q":"En Maine, ¿cuándo se da el examen de manejo a un nuevo solicitante?","o":["Antes del examen escrito","Antes de la prueba de la vista","El mismo día que se emite el permiso","Solo después de aprobar todos los demás exámenes"],"h1":"Va al final.","h2":"En Maine, el examen de manejo no se da hasta que se aprueban todos los demás exámenes.","p":"Correcto. El examen de manejo va después de todos los demás."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-074","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, an adult moves from another state with a valid passenger car license. Which tests may be waived?","o":["The written and road tests","Only the vision screening","None; every test is required","Only the road test, never the written test"],"h1":"A valid license from another state shows they already passed similar tests.","h2":"In Maine, applicants with a valid out-of-state license may have the written and road tests waived.","p":"Right. The written and road tests may be waived."},"es":{"q":"En Maine, un adulto se muda de otro estado con una licencia válida para autos. ¿Qué exámenes se pueden omitir?","o":["El examen escrito y el de manejo","Solo la prueba de la vista","Ninguno; se requieren todos","Solo el de manejo, nunca el escrito"],"h1":"Una licencia válida de otro estado muestra que ya aprobó exámenes similares.","h2":"En Maine, a quien tiene una licencia válida de otro estado se le pueden omitir el examen escrito y el de manejo.","p":"Correcto. Se pueden omitir el examen escrito y el de manejo."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-075","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a 16-year-old moves in with a valid out-of-state license. What may they need to show before getting a Maine license?","o":["Proof of a job","Proof that they finished an approved driver education course","A letter from their old school","Proof of car ownership"],"h1":"It is about the course young drivers take.","h2":"In Maine, a 16- or 17-year-old transferring an out-of-state license may need to show they completed an approved driver education course.","p":"Correct. They may need proof of driver education."},"es":{"q":"En Maine, un joven de 16 años se muda con una licencia válida de otro estado. ¿Qué podría tener que mostrar antes de obtener la licencia de Maine?","o":["Prueba de empleo","Prueba de que terminó un curso aprobado de educación vial","Una carta de su escuela anterior","Prueba de que es dueño de un auto"],"h1":"Tiene que ver con el curso que toman los conductores jóvenes.","h2":"En Maine, un joven de 16 o 17 años que transfiere una licencia de otro estado puede tener que mostrar que completó un curso aprobado de educación vial.","p":"Correcto. Puede necesitar prueba de educación vial."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-076","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, you need a commercial driver's license to drive a vehicle designed to carry more than how many passengers, counting the driver?","o":["8","10","15","25"],"h1":"It is a large van or a bus.","h2":"In Maine, a commercial driver's license is needed for a vehicle designed to carry more than 15 passengers, including the driver.","p":"Right. More than 15 passengers, including the driver, needs a CDL."},"es":{"q":"En Maine, se necesita licencia de conducir comercial para un vehículo diseñado para llevar más de cuántos pasajeros, contando al conductor?","o":["8","10","15","25"],"h1":"Es una camioneta grande o un autobús.","h2":"En Maine, se necesita licencia comercial para un vehículo diseñado para llevar más de 15 pasajeros, incluido el conductor.","p":"Correcto. Más de 15 pasajeros, incluido el conductor, requiere licencia comercial."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-077","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what happens if you make a false statement on your license application?","o":["You get a warning letter","You must retake the written test","You pay a small fee","Your license is revoked right away"],"h1":"The penalty is serious and immediate.","h2":"In Maine, any misstatement on a license application results in immediate revocation of the license, and court action may follow.","p":"Correct. A false statement means immediate revocation."},"es":{"q":"En Maine, ¿qué pasa si das información falsa en tu solicitud de licencia?","o":["Recibes una carta de advertencia","Debes repetir el examen escrito","Pagas una tarifa pequeña","Te revocan la licencia de inmediato"],"h1":"La sanción es seria e inmediata.","h2":"En Maine, cualquier declaración falsa en la solicitud de licencia causa la revocación inmediata de la licencia, y puede haber acción judicial.","p":"Correcto. Una declaración falsa significa revocación inmediata."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-078","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a 17-year-old is married to a 19-year-old. Who may sign the 17-year-old's permit application?","o":["A parent, a legal guardian, or the spouse","Only a parent","Only a driving instructor","The 17-year-old alone"],"h1":"A spouse who is 18 or older counts.","h2":"In Maine, a minor's application must be signed by a parent or legal guardian with custody, or by the minor's spouse if the spouse is 18 or older.","p":"Right. A parent, guardian, or an adult spouse may sign."},"es":{"q":"En Maine, una joven de 17 años está casada con alguien de 19. ¿Quién puede firmar su solicitud de permiso?","o":["Uno de sus padres, un tutor legal o el cónyuge","Solo uno de sus padres","Solo un instructor de manejo","La joven de 17 años sola"],"h1":"Un cónyuge de 18 años o más cuenta.","h2":"En Maine, la solicitud de un menor debe firmarla un padre o tutor legal con custodia, o el cónyuge del menor si tiene 18 años o más.","p":"Correcto. Puede firmar un padre, un tutor o un cónyuge adulto."},"ref":{"doc":"ME","page":"1-5"}},{"id":"me-079","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a parent signed their teen's permit application. Later the parent thinks the teen is not ready. What can the parent do?","o":["Nothing until the permit expires","File a notarized written request to suspend the permit","Call the police to take the permit","Ask the school to cancel it"],"h1":"The person who signed has a special power.","h2":"In Maine, the person who signed a minor's application may file a notarized written request with the Secretary of State to suspend the minor's license or permit.","p":"Correct. The signer may ask, in a notarized letter, for a suspension."},"es":{"q":"En Maine, un padre firmó la solicitud de permiso de su hijo adolescente. Después cree que el joven no está listo. ¿Qué puede hacer?","o":["Nada hasta que venza el permiso","Presentar una solicitud escrita y notariada para suspender el permiso","Llamar a la policía para que se lleve el permiso","Pedir a la escuela que lo cancele"],"h1":"Quien firmó tiene un poder especial.","h2":"En Maine, la persona que firmó la solicitud de un menor puede presentar ante el Secretario de Estado una solicitud escrita y notariada para suspender la licencia o permiso del menor.","p":"Correcto. Quien firmó puede pedir la suspensión en una carta notariada."},"ref":{"doc":"ME","page":"1-7"}},{"id":"me-080","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a driver who is 65 or older gets a new picture license. Until when is it valid?","o":["Until the second birthday after it is issued","Until the sixth birthday after it is issued","Until the fourth birthday after it is issued","For life"],"h1":"It is shorter than the usual six years.","h2":"In Maine, a picture license issued to a driver 65 or older is valid until the fourth birthday after it is issued.","p":"Right. For drivers 65 and older it lasts to the fourth birthday."},"es":{"q":"En Maine, un conductor de 65 años o más recibe una nueva licencia con foto. ¿Hasta cuándo es válida?","o":["Hasta el segundo cumpleaños después de emitida","Hasta el sexto cumpleaños después de emitida","Hasta el cuarto cumpleaños después de emitida","De por vida"],"h1":"Es menos que los seis años habituales.","h2":"En Maine, la licencia con foto de un conductor de 65 años o más es válida hasta el cuarto cumpleaños después de emitida.","p":"Correcto. Para mayores de 65 dura hasta el cuarto cumpleaños."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-081","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, about how long before your license expires is a renewal notice mailed to you?","o":["7 days","90 days","1 year","45 days"],"h1":"It is about a month and a half.","h2":"In Maine, a renewal notice is mailed about 45 days before a driver's license expires, to the latest address on file.","p":"Correct. The notice comes about 45 days ahead."},"es":{"q":"En Maine, ¿cuánto tiempo antes de que venza tu licencia te envían un aviso de renovación?","o":["7 días","90 días","1 año","45 días"],"h1":"Es como mes y medio.","h2":"En Maine, el aviso de renovación se envía unos 45 días antes de que venza la licencia, a la dirección más reciente registrada.","p":"Correcto. El aviso llega unos 45 días antes."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-082","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a friend asks to borrow your driver's license for a night out. What does Maine law say?","o":["It is illegal to lend your license to anyone","It is fine if they are over 21","It is fine for one day","It is fine if you are with them"],"h1":"Your license is only for you.","h2":"In Maine, it is illegal to lend your driver's license to anyone else, and loaning a license can lead to a suspension.","p":"Right. Lending your license is illegal."},"es":{"q":"En Maine, un amigo te pide prestada tu licencia de conducir para salir una noche. ¿Qué dice la ley de Maine?","o":["Es ilegal prestar tu licencia a cualquier persona","Está bien si tiene más de 21 años","Está bien por un día","Está bien si tú vas con él"],"h1":"Tu licencia es solo para ti.","h2":"En Maine, es ilegal prestar tu licencia de conducir a otra persona, y prestarla puede causar una suspensión.","p":"Correcto. Prestar tu licencia es ilegal."},"ref":{"doc":"ME","page":"1-6"}},{"id":"me-083","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, who may send the Secretary of State a written report that can lead to a license suspension?","o":["Only a judge","A law enforcement officer or another member of the public","Only your insurance company","Only a driving instructor"],"h1":"It is not limited to officials.","h2":"In Maine, the Secretary of State may suspend a license after a written adverse report about your driving from a law enforcement officer or any other member of the public.","p":"Correct. Police or any member of the public may report."},"es":{"q":"En Maine, ¿quién puede enviar al Secretario de Estado un informe escrito que puede llevar a suspender una licencia?","o":["Solo un juez","Un agente de la ley u otra persona del público","Solo tu compañía de seguros","Solo un instructor de manejo"],"h1":"No se limita a funcionarios.","h2":"En Maine, el Secretario de Estado puede suspender una licencia después de un informe escrito negativo sobre tu manejo de un agente de la ley o de cualquier otra persona del público.","p":"Correcto. La policía o cualquier persona del público puede informar."},"ref":{"doc":"ME","page":"1-7"}},{"id":"me-084","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a driver is convicted of vehicular manslaughter with no alcohol involved. How long is the license revoked?","o":["At least 6 months","At least 1 year","At least 5 years","At least 30 days"],"h1":"It is several years.","h2":"In Maine, vehicular manslaughter brings a revocation of at least 5 years, and the revocation is permanent if alcohol was involved.","p":"Right. At least 5 years, or for life with alcohol."},"es":{"q":"En Maine, un conductor es condenado por homicidio vehicular sin alcohol de por medio. ¿Por cuánto tiempo se revoca la licencia?","o":["Al menos 6 meses","Al menos 1 año","Al menos 5 años","Al menos 30 días"],"h1":"Son varios años.","h2":"En Maine, el homicidio vehicular trae una revocación de al menos 5 años, y es permanente si hubo alcohol.","p":"Correcto. Al menos 5 años, o de por vida con alcohol."},"ref":{"doc":"ME","page":"1-7"}},{"id":"me-085","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver is declared a habitual offender. How long is the license revoked?","o":["At least 30 days","At least 60 days","At least 90 days","At least one year"],"h1":"It is the longest of these choices.","h2":"In Maine, a habitual offender has the license revoked for at least one year.","p":"Correct. A habitual offender loses the license for at least one year."},"es":{"q":"En Maine, a un conductor se le declara infractor habitual. ¿Por cuánto tiempo se revoca su licencia?","o":["Al menos 30 días","Al menos 60 días","Al menos 90 días","Al menos un año"],"h1":"Es la opción más larga.","h2":"En Maine, al infractor habitual se le revoca la licencia por al menos un año.","p":"Correcto. Un infractor habitual pierde la licencia por al menos un año."},"ref":{"doc":"ME","page":"1-7"}},{"id":"me-086","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a driver is convicted of street racing. For how long may the license be suspended?","o":["Up to 90 days","Up to 10 days","Up to 30 days","Up to 15 days"],"h1":"It is about three months.","h2":"In Maine, a conviction for eluding police, passing a roadblock or street racing may bring a suspension of up to 90 days.","p":"Right. Street racing can cost up to 90 days."},"es":{"q":"En Maine, un conductor es condenado por carreras en la calle. ¿Por cuánto tiempo se le puede suspender la licencia?","o":["Hasta 90 días","Hasta 10 días","Hasta 30 días","Hasta 15 días"],"h1":"Son unos tres meses.","h2":"En Maine, una condena por huir de la policía, pasar un retén o hacer carreras en la calle puede traer una suspensión de hasta 90 días.","p":"Correcto. Las carreras en la calle pueden costar hasta 90 días."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-087","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a driver is convicted of driving while their license is suspended. How long may the new suspension be?","o":["10 days","60 days","1 year","5 years"],"h1":"It is two months.","h2":"In Maine, a person convicted of operating after suspension may have the license suspended for 60 days.","p":"Correct. Operating after suspension can bring 60 more days."},"es":{"q":"En Maine, un conductor es condenado por manejar con la licencia suspendida. ¿Cuánto puede durar la nueva suspensión?","o":["10 días","60 días","1 año","5 años"],"h1":"Son dos meses.","h2":"En Maine, una persona condenada por manejar con la licencia suspendida puede recibir una suspensión de 60 días.","p":"Correcto. Manejar con licencia suspendida puede traer 60 días más."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-088","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a 16-year-old with a learner's permit drives alone to school and is convicted. How long may the license be suspended?","o":["5 days","1 year","30 days","Nothing happens the first time"],"h1":"It is about a month.","h2":"In Maine, operating alone on a learner's permit is one of the offenses that may bring a 30-day suspension.","p":"Right. Driving alone on a permit can mean a 30-day suspension."},"es":{"q":"En Maine, un joven de 16 años con permiso de aprendizaje maneja solo a la escuela y es condenado. ¿Por cuánto tiempo pueden suspenderle la licencia?","o":["5 días","1 año","30 días","No pasa nada la primera vez"],"h1":"Es como un mes.","h2":"En Maine, manejar solo con un permiso de aprendizaje es una de las infracciones que pueden traer una suspensión de 30 días.","p":"Correcto. Manejar solo con permiso puede significar 30 días de suspensión."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-089","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, a 19-year-old is caught using a fake ID to buy liquor for the second time. How long must the license be suspended?","o":["90 days","10 days","30 days","2 years"],"h1":"It is longer than for a first offense but less than a year.","h2":"In Maine, a second offense of using false identification to get liquor requires a 90-day license suspension; a first offense may bring 30 days.","p":"Right. A second offense means 90 days."},"es":{"q":"En Maine, a un joven de 19 años lo descubren por segunda vez usando una identificación falsa para comprar licor. ¿Por cuánto tiempo deben suspenderle la licencia?","o":["90 días","10 días","30 días","2 años"],"h1":"Es más que la primera vez, pero menos de un año.","h2":"En Maine, una segunda infracción por usar identificación falsa para obtener licor exige una suspensión de 90 días; la primera puede traer 30 días.","p":"Correcto. La segunda vez son 90 días."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-090","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how many demerit points does an offense of using a fake ID to obtain liquor carry?","o":["2 points","6 points","10 points","12 points"],"h1":"It is the number that brings a warning letter.","h2":"In Maine, using false identification to obtain liquor carries six demerit points.","p":"Correct. It carries 6 points."},"es":{"q":"En Maine, ¿cuántos puntos de demérito trae usar una identificación falsa para obtener licor?","o":["2 puntos","6 puntos","10 puntos","12 puntos"],"h1":"Es el número que trae una carta de advertencia.","h2":"En Maine, usar una identificación falsa para obtener licor trae seis puntos de demérito.","p":"Correcto. Trae 6 puntos."},"ref":{"doc":"ME","page":"1-8"}},{"id":"me-091","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, your license is suspended for demerit points and you disagree. What are you entitled to?","o":["A refund of your fines","A new license right away","A hearing by the Secretary of State's office","Nothing; there is no appeal"],"h1":"You can tell your side of the story.","h2":"In Maine, a driver whose license is suspended is entitled to a hearing by the Secretary of State's office, and the decision may be appealed to Superior Court.","p":"Right. You may ask for a hearing."},"es":{"q":"En Maine, te suspenden la licencia por puntos de demérito y no estás de acuerdo. ¿A qué tienes derecho?","o":["A que te devuelvan las multas","A una licencia nueva de inmediato","A una audiencia en la oficina del Secretario de Estado","A nada; no hay apelación"],"h1":"Puedes contar tu versión.","h2":"En Maine, el conductor con licencia suspendida tiene derecho a una audiencia en la oficina del Secretario de Estado, y la decisión se puede apelar ante el Tribunal Superior.","p":"Correcto. Puedes pedir una audiencia."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-092","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver tries to escape police at a reckless speed, causing a high-speed chase. What kind of crime is this?","o":["A traffic infraction only","A Class E crime","A civil violation","A Class C crime"],"h1":"It becomes Class B if someone is seriously hurt.","h2":"In Maine, eluding a police officer with a reckless high-speed chase is a Class C crime, and a Class B crime if someone suffers serious bodily injury.","p":"Correct. It is a Class C crime."},"es":{"q":"En Maine, un conductor trata de escapar de la policía a velocidad imprudente y causa una persecución a alta velocidad. ¿Qué tipo de delito es?","o":["Solo una infracción de tránsito","Un delito Clase E","Una infracción civil","Un delito Clase C"],"h1":"Pasa a Clase B si alguien resulta gravemente herido.","h2":"En Maine, huir de un policía con una persecución imprudente a alta velocidad es un delito Clase C, y Clase B si alguien sufre lesiones graves.","p":"Correcto. Es un delito Clase C."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-093","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, how long is the Maine Driving Dynamics course?","o":["Five hours","One hour","Two full days","Twenty hours"],"h1":"It fits into one afternoon or evening.","h2":"In Maine, the Driving Dynamics course is an approved five-hour program about driving hazards and how to avoid them.","p":"Right. It is a five-hour course."},"es":{"q":"En Maine, ¿cuánto dura el curso Maine Driving Dynamics?","o":["Cinco horas","Una hora","Dos días completos","Veinte horas"],"h1":"Cabe en una tarde o una noche.","h2":"En Maine, el curso Driving Dynamics es un programa aprobado de cinco horas sobre los peligros al manejar y cómo evitarlos.","p":"Correcto. Es un curso de cinco horas."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-094","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, how often can a driver improvement course take points off your record?","o":["Every time you take it","Only once in any twelve-month period","Once every five years","Only once in a lifetime"],"h1":"There is a waiting time of one year.","h2":"In Maine, points are deducted for a driver improvement course only once in any twelve-month period.","p":"Correct. Only once in any twelve months."},"es":{"q":"En Maine, ¿cada cuánto puede un curso de mejoramiento para conductores quitar puntos de tu historial?","o":["Cada vez que lo tomas","Solo una vez en cualquier período de doce meses","Una vez cada cinco años","Solo una vez en la vida"],"h1":"Hay que esperar un año.","h2":"En Maine, los puntos por un curso de mejoramiento se descuentan solo una vez en cualquier período de doce meses.","p":"Correcto. Solo una vez en doce meses."},"ref":{"doc":"ME","page":"1-9"}},{"id":"me-095","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, a driver's license was suspended three times within three years. What may happen next?","o":["The suspensions are cancelled","A warning letter only","A further suspension of up to 120 days","A free driving course"],"h1":"It is about four months.","h2":"In Maine, a person suspended three times within three years may get a further suspension of up to 120 days.","p":"Right. Up to 120 more days."},"es":{"q":"En Maine, a un conductor le suspendieron la licencia tres veces en tres años. ¿Qué puede pasar después?","o":["Se cancelan las suspensiones","Solo una carta de advertencia","Otra suspensión de hasta 120 días","Un curso de manejo gratis"],"h1":"Son como cuatro meses.","h2":"En Maine, a una persona suspendida tres veces en tres años le pueden dar otra suspensión de hasta 120 días.","p":"Correcto. Hasta 120 días más."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-096","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver misses a court date for a traffic ticket. How long does the license suspension last?","o":["Exactly 30 days","Exactly 6 months","There is no suspension","Until the driver appears in court or pays the fine"],"h1":"The driver controls when it ends.","h2":"In Maine, a driver who fails to appear in court or pay the fine is suspended until the appearance is made or the fine is paid.","p":"Correct. It lasts until the driver appears or pays."},"es":{"q":"En Maine, un conductor no se presenta a la corte por una multa de tránsito. ¿Cuánto dura la suspensión de su licencia?","o":["Exactamente 30 días","Exactamente 6 meses","No hay suspensión","Hasta que se presente en la corte o pague la multa"],"h1":"El conductor decide cuándo termina.","h2":"En Maine, al conductor que no se presenta a la corte o no paga la multa se le suspende la licencia hasta que se presente o pague.","p":"Correcto. Dura hasta que se presente o pague."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-097","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, what is the shortest suspension for a conviction of driving to endanger?","o":["30 days","7 days","1 day","2 years"],"h1":"It is about one month.","h2":"In Maine, driving to endanger brings a mandatory suspension of at least 30 days.","p":"Right. At least 30 days."},"es":{"q":"En Maine, ¿cuál es la suspensión más corta por una condena de manejar poniendo en peligro (driving to endanger)?","o":["30 días","7 días","1 día","2 años"],"h1":"Es como un mes.","h2":"En Maine, manejar poniendo en peligro trae una suspensión obligatoria de al menos 30 días.","p":"Correcto. Al menos 30 días."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-098","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a 17-year-old is caught with liquor in the car. What is the shortest license suspension?","o":["7 days","30 days","180 days","There is no suspension"],"h1":"It is about one month.","h2":"In Maine, illegal transportation, possession or drinking of liquor by a minor in a motor vehicle brings a suspension of at least 30 days.","p":"Correct. At least 30 days."},"es":{"q":"En Maine, a un joven de 17 años lo encuentran con licor en el auto. ¿Cuál es la suspensión de licencia más corta?","o":["7 días","30 días","180 días","No hay suspensión"],"h1":"Es como un mes.","h2":"En Maine, que un menor transporte, tenga o beba licor ilegalmente en un vehículo trae una suspensión de al menos 30 días.","p":"Correcto. Al menos 30 días."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-099","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, you cause damage in a crash and have no liability insurance. How long are your license and registration suspended?","o":["For 10 days","For one year exactly","Until you file proof of insurance with the Secretary of State","They are not suspended"],"h1":"It ends when you show something.","h2":"In Maine, if you are responsible for crash damage and have no liability insurance, your license and registration are suspended until proof of insurance is filed with the Secretary of State.","p":"Right. Until you file proof of insurance."},"es":{"q":"En Maine, causas daños en un choque y no tienes seguro de responsabilidad civil. ¿Por cuánto tiempo suspenden tu licencia y tu registro?","o":["Por 10 días","Por un año exacto","Hasta que presentes prueba de seguro ante el Secretario de Estado","No los suspenden"],"h1":"Termina cuando muestras algo.","h2":"En Maine, si eres responsable de daños en un choque y no tienes seguro de responsabilidad civil, tu licencia y tu registro se suspenden hasta que presentes prueba de seguro ante el Secretario de Estado.","p":"Correcto. Hasta que presentes prueba de seguro."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-100","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, a driver uses a car to commit a Class D crime such as reckless conduct, creating a risk of serious injury. How long is the license revoked?","o":["30 days","6 months","5 years","2 years"],"h1":"Class A, B or C crimes bring 3 years; Class E brings 1 year.","h2":"In Maine, when a vehicle is used to commit a designated Class D crime, the license is revoked for two years.","p":"Correct. A Class D crime brings a two-year revocation."},"es":{"q":"En Maine, un conductor usa un auto para cometer un delito Clase D, como conducta imprudente, creando riesgo de lesiones graves. ¿Por cuánto tiempo se revoca la licencia?","o":["30 días","6 meses","5 años","2 años"],"h1":"Los delitos Clase A, B o C traen 3 años; la Clase E trae 1 año.","h2":"En Maine, cuando se usa un vehículo para cometer un delito designado Clase D, la licencia se revoca por dos años.","p":"Correcto. Un delito Clase D trae dos años de revocación."},"ref":{"doc":"ME","page":"1-10"}},{"id":"me-101","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, where should you keep your vehicle's certificate of title?","o":["In a safe place, never in the vehicle","In the glove box","Under the driver's seat","Taped to the windshield"],"h1":"A thief should not find it with the car.","h2":"In Maine, keep the certificate of title in a safe place and never in the vehicle.","p":"Right. Keep the title somewhere safe, not in the car."},"es":{"q":"En Maine, ¿dónde debes guardar el certificado de título de tu vehículo?","o":["En un lugar seguro, nunca en el vehículo","En la guantera","Debajo del asiento del conductor","Pegado al parabrisas"],"h1":"Un ladrón no debe encontrarlo junto con el auto.","h2":"En Maine, guarda el certificado de título en un lugar seguro y nunca dentro del vehículo.","p":"Correcto. Guarda el título en un lugar seguro, no en el auto."},"ref":{"doc":"ME","page":"2-1"}},{"id":"me-102","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, you borrowed money from a bank to buy your car. Who receives the title?","o":["You do","The bank or credit union that lent the money","The town office","The car's insurance company"],"h1":"The lender wants to protect its loan.","h2":"In Maine, if you borrowed money for the car, the bank or credit union that lent the money gets the title.","p":"Correct. The lender holds the title."},"es":{"q":"En Maine, pediste dinero prestado a un banco para comprar tu auto. ¿Quién recibe el título?","o":["Tú","El banco o cooperativa de crédito que prestó el dinero","La oficina del municipio","La compañía de seguros del auto"],"h1":"El prestamista quiere proteger su préstamo.","h2":"En Maine, si pediste dinero para el auto, el banco o cooperativa de crédito que lo prestó recibe el título.","p":"Correcto. El prestamista guarda el título."},"ref":{"doc":"ME","page":"2-1"}},{"id":"me-103","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, which of these vehicles does not need a title?","o":["A 5-year-old car","A 600 cc motorcycle","A vehicle more than 25 years old","A new pickup truck"],"h1":"Think about very old vehicles.","h2":"In Maine, vehicles more than 25 years old, motorcycles under 300 cc and trailers of 3,000 pounds or less unloaded do not need a title.","p":"Right. Vehicles over 25 years old need no title."},"es":{"q":"En Maine, ¿cuál de estos vehículos no necesita título?","o":["Un auto de 5 años","Una motocicleta de 600 cc","Un vehículo de más de 25 años","Una camioneta pickup nueva"],"h1":"Piensa en vehículos muy viejos.","h2":"En Maine, los vehículos de más de 25 años, las motocicletas de menos de 300 cc y los remolques de 3,000 libras o menos sin carga no necesitan título.","p":"Correcto. Los vehículos de más de 25 años no necesitan título."},"ref":{"doc":"ME","page":"2-1"}},{"id":"me-104","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what is the first step in registering your motor vehicle?","o":["Getting a safety inspection","Buying new plates online","Taking a road test","Paying the excise tax to your town's tax collector"],"h1":"It is a tax paid locally.","h2":"In Maine, paying the excise tax to a municipal tax collector is the first step in registering a motor vehicle.","p":"Correct. Pay the excise tax first."},"es":{"q":"En Maine, ¿cuál es el primer paso para registrar tu vehículo?","o":["Hacer la inspección de seguridad","Comprar placas nuevas en línea","Presentar un examen de manejo","Pagar el impuesto de consumo (excise tax) al recaudador de tu municipio"],"h1":"Es un impuesto que se paga en tu localidad.","h2":"En Maine, pagar el impuesto de consumo (excise tax) al recaudador del municipio es el primer paso para registrar un vehículo.","p":"Correcto. Primero se paga el excise tax."},"ref":{"doc":"ME","page":"2-2"}},{"id":"me-105","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, what two things set the amount of excise tax on a vehicle?","o":["Its age and factory list price","Its color and number of doors","The owner's age and income","Its fuel type and seat count"],"h1":"Newer, more expensive vehicles pay more.","h2":"In Maine, the excise tax depends on the vehicle's age and its factory list price.","p":"Right. Age and factory list price."},"es":{"q":"En Maine, ¿qué dos cosas determinan el monto del impuesto de consumo (excise tax) de un vehículo?","o":["Su antigüedad y su precio de lista de fábrica","Su color y número de puertas","La edad e ingresos del dueño","Su tipo de combustible y número de asientos"],"h1":"Los vehículos más nuevos y caros pagan más.","h2":"En Maine, el excise tax depende de la antigüedad del vehículo y de su precio de lista de fábrica.","p":"Correcto. La antigüedad y el precio de lista de fábrica."},"ref":{"doc":"ME","page":"2-2"}},{"id":"me-106","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, a 17-year-old registers a car in their own name. Who else must sign the registration form?","o":["A police officer","A parent or guardian","A car dealer","A school principal"],"h1":"Someone responsible for the minor.","h2":"In Maine, if you are under 18, a parent or guardian must also sign the registration form.","p":"Correct. A parent or guardian must sign too."},"es":{"q":"En Maine, un joven de 17 años registra un auto a su nombre. ¿Quién más debe firmar el formulario de registro?","o":["Un policía","Uno de sus padres o su tutor","Un vendedor de autos","El director de la escuela"],"h1":"Alguien responsable del menor.","h2":"En Maine, si tienes menos de 18 años, uno de tus padres o tu tutor también debe firmar el formulario de registro.","p":"Correcto. Uno de los padres o el tutor también debe firmar."},"ref":{"doc":"ME","page":"2-2"}},{"id":"me-107","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, what is the registration fee for a passenger car, according to the driver's manual?","o":["$10","$100","$35","$250"],"h1":"It is the same as for a small pickup.","h2":"In Maine, the driver's manual lists the passenger vehicle registration fee as $35, valid for one year.","p":"Right. It is $35 for one year."},"es":{"q":"En Maine, ¿cuánto cuesta el registro de un auto de pasajeros, según el manual del conductor?","o":["$10","$100","$35","$250"],"h1":"Es lo mismo que para una pickup pequeña.","h2":"En Maine, el manual del conductor indica que el registro de un vehículo de pasajeros cuesta $35 y vale por un año.","p":"Correcto. Son $35 por un año."},"ref":{"doc":"ME","page":"2-2"}},{"id":"me-108","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, when you register a vehicle in Maine for the first time, which form is used to find out if sales tax is due?","o":["The title application","The insurance card","The inspection sticker","A Use Tax Certificate"],"h1":"Its name includes the word tax.","h2":"In Maine, a first-time registration must come with a Use Tax Certificate, which shows whether any Maine sales tax is due.","p":"Correct. The Use Tax Certificate."},"es":{"q":"En Maine, cuando registras un vehículo en Maine por primera vez, ¿qué formulario se usa para saber si se debe impuesto sobre la venta?","o":["La solicitud de título","La tarjeta del seguro","La calcomanía de inspección","Un Certificado de Impuesto de Uso (Use Tax Certificate)"],"h1":"Su nombre incluye la palabra impuesto.","h2":"En Maine, el primer registro debe ir con un Use Tax Certificate, que muestra si se debe impuesto sobre la venta de Maine.","p":"Correcto. El Use Tax Certificate."},"ref":{"doc":"ME","page":"2-2"}},{"id":"me-109","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, you just moved to the state. How soon must you apply to register your vehicle?","o":["Within 30 days","Within 7 days","Within 6 months","Within 1 year"],"h1":"It is the same time limit as for transferring your license.","h2":"In Maine, you must apply for a Maine vehicle registration within 30 days of establishing residency.","p":"Right. Within 30 days."},"es":{"q":"En Maine, te acabas de mudar al estado. ¿En cuánto tiempo debes solicitar el registro de tu vehículo?","o":["Dentro de 30 días","Dentro de 7 días","Dentro de 6 meses","Dentro de 1 año"],"h1":"Es el mismo plazo que para transferir tu licencia.","h2":"En Maine, debes solicitar el registro de tu vehículo dentro de los 30 días de establecer tu residencia.","p":"Correcto. Dentro de 30 días."},"ref":{"doc":"ME","page":"2-3"}},{"id":"me-110","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, you borrow a friend's car. Whose duty is it to make sure the car is insured while you drive it?","o":["Only the owner's","Yours too; any vehicle you drive must be insured","Nobody's, if the trip is short","Only the insurance company's"],"h1":"Maine puts the duty on owners and operators.","h2":"In Maine, every owner and every operator must maintain liability insurance, and any vehicle you drive must be insured even if you do not own it.","p":"Correct. Drivers share the duty; the car you drive must be insured."},"es":{"q":"En Maine, pides prestado el auto de un amigo. ¿De quién es el deber de asegurarse de que el auto tenga seguro mientras lo manejas?","o":["Solo del dueño","También tuyo; todo vehículo que manejes debe tener seguro","De nadie, si el viaje es corto","Solo de la compañía de seguros"],"h1":"Maine pone el deber en dueños y conductores.","h2":"En Maine, todo dueño y todo conductor debe tener seguro de responsabilidad civil, y todo vehículo que manejes debe estar asegurado aunque no sea tuyo.","p":"Correcto. El conductor también es responsable; el auto que manejas debe tener seguro."},"ref":{"doc":"ME","page":"2-3"}},{"id":"me-111","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, you are found to have failed to show evidence of insurance when required. What will you be required to file?","o":["A new title","A driving log","An SR-22 insurance certificate","A medical report"],"h1":"It is a special proof of financial responsibility.","h2":"In Maine, if you are adjudicated of failing to produce evidence of insurance, you must file proof of financial responsibility with an SR-22 certificate or face suspension.","p":"Right. You must file an SR-22."},"es":{"q":"En Maine, se determina que no mostraste prueba de seguro cuando te la pidieron. ¿Qué tendrás que presentar?","o":["Un título nuevo","Un registro de práctica","Un certificado de seguro SR-22","Un informe médico"],"h1":"Es una prueba especial de responsabilidad financiera.","h2":"En Maine, si se determina que no mostraste prueba de seguro, debes presentar prueba de responsabilidad financiera con un certificado SR-22 o enfrentar una suspensión.","p":"Correcto. Debes presentar un SR-22."},"ref":{"doc":"ME","page":"2-3"}},{"id":"me-112","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what kind of coverage is included by law in every auto liability policy?","o":["Roadside towing","Rental car coverage","Collision coverage","Uninsured motorist coverage"],"h1":"It protects you from drivers who have no insurance.","h2":"In Maine, by law every auto liability policy includes uninsured motorist coverage.","p":"Correct. Uninsured motorist coverage is included."},"es":{"q":"En Maine, ¿qué tipo de cobertura incluye por ley toda póliza de responsabilidad civil para autos?","o":["Servicio de grúa","Cobertura de auto de alquiler","Cobertura de choque","Cobertura contra conductores sin seguro"],"h1":"Te protege de conductores que no tienen seguro.","h2":"En Maine, por ley toda póliza de responsabilidad civil para autos incluye cobertura contra conductores sin seguro (uninsured motorist).","p":"Correcto. Se incluye la cobertura contra conductores sin seguro."},"ref":{"doc":"ME","page":"2-3"}},{"id":"me-113","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, you cannot get car insurance through regular companies. Where can you still get coverage?","o":["The Maine Automobile Insurance Plan","The Bureau of Motor Vehicles","Your town office","You cannot get any coverage"],"h1":"It is a shared market all insurers must join.","h2":"In Maine, anyone unable to get insurance through regular channels can get coverage through the Maine Automobile Insurance Plan.","p":"Right. The Maine Automobile Insurance Plan."},"es":{"q":"En Maine, no puedes conseguir seguro de auto con las compañías normales. ¿Dónde puedes obtener cobertura?","o":["En el Plan de Seguro de Automóviles de Maine (Maine Automobile Insurance Plan)","En la Oficina de Vehículos Motorizados","En la oficina de tu municipio","No puedes obtener ninguna cobertura"],"h1":"Es un mercado compartido al que deben unirse todas las aseguradoras.","h2":"En Maine, quien no puede obtener seguro por los medios normales puede obtener cobertura a través del Maine Automobile Insurance Plan.","p":"Correcto. El Maine Automobile Insurance Plan."},"ref":{"doc":"ME","page":"2-3"}},{"id":"me-114","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, what is the minimum liability coverage for injury to or death of one person?","o":["$25,000","$50,000","$10,000","$300,000"],"h1":"It is twice the property damage minimum.","h2":"In Maine, the minimum liability insurance is $50,000 for injury or death of one person, $100,000 per accident, and $25,000 for property damage.","p":"Correct. $50,000 for one person."},"es":{"q":"En Maine, ¿cuál es la cobertura mínima de responsabilidad civil por lesiones o muerte de una persona?","o":["$25,000","$50,000","$10,000","$300,000"],"h1":"Es el doble del mínimo por daños a la propiedad.","h2":"En Maine, el seguro mínimo de responsabilidad civil es de $50,000 por lesiones o muerte de una persona, $100,000 por accidente y $25,000 por daños a la propiedad.","p":"Correcto. $50,000 por una persona."},"ref":{"doc":"ME","page":null}},{"id":"me-115","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, what is the minimum medical payments coverage a car insurance policy must include?","o":["$500","$1,000","$2,000","$10,000"],"h1":"It is a small amount, in the low thousands.","h2":"In Maine, a liability policy must include at least $2,000 in medical payments coverage.","p":"Right. At least $2,000 in medical payments."},"es":{"q":"En Maine, ¿cuál es la cobertura mínima de gastos médicos que debe incluir una póliza de seguro de auto?","o":["$500","$1,000","$2,000","$10,000"],"h1":"Es una cantidad pequeña, de pocos miles.","h2":"En Maine, una póliza de responsabilidad civil debe incluir al menos $2,000 de cobertura de gastos médicos.","p":"Correcto. Al menos $2,000 de gastos médicos."},"ref":{"doc":"ME","page":null}},{"id":"me-116","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, how often must a registered vehicle be inspected at an official inspection station?","o":["Every 2 years","Every 5 years","Only when sold","Once a year"],"h1":"It is yearly.","h2":"In Maine, vehicles with a Maine registration must be inspected at an official inspection station once a year.","p":"Correct. Once a year."},"es":{"q":"En Maine, ¿cada cuánto se debe inspeccionar un vehículo registrado en una estación oficial de inspección?","o":["Cada 2 años","Cada 5 años","Solo cuando se vende","Una vez al año"],"h1":"Es cada año.","h2":"En Maine, los vehículos con registro de Maine deben inspeccionarse en una estación oficial una vez al año.","p":"Correcto. Una vez al año."},"ref":{"doc":"ME","page":"2-4"}},{"id":"me-117","scope":"ME","cat":"licensing","sign":null,"c":0,"en":{"q":"In Maine, to pass inspection, from how far away must your horn be heard?","o":["200 feet","20 feet","50 feet","1,000 feet"],"h1":"It is about two-thirds of a football field.","h2":"In Maine, a vehicle's horn must be loud enough to be heard from 200 feet away to pass inspection.","p":"Right. 200 feet."},"es":{"q":"En Maine, para pasar la inspección, ¿desde qué distancia se debe oír tu bocina?","o":["200 pies","20 pies","50 pies","1,000 pies"],"h1":"Son como dos tercios de una cancha de fútbol americano.","h2":"En Maine, la bocina del vehículo debe oírse desde 200 pies de distancia para pasar la inspección.","p":"Correcto. 200 pies."},"ref":{"doc":"ME","page":"2-4"}},{"id":"me-118","scope":"ME","cat":"licensing","sign":null,"c":1,"en":{"q":"In Maine, to pass inspection, the foot brake must stop the vehicle going 20 mph within what distance?","o":["10 feet","30 feet","60 feet","100 feet"],"h1":"It is about two car lengths.","h2":"In Maine, the foot brake must be able to stop the vehicle within 30 feet from 20 mph to pass inspection.","p":"Correct. Within 30 feet."},"es":{"q":"En Maine, para pasar la inspección, el freno de pie debe detener el vehículo a 20 mph dentro de qué distancia?","o":["10 pies","30 pies","60 pies","100 pies"],"h1":"Son como dos largos de auto.","h2":"En Maine, el freno de pie debe poder detener el vehículo dentro de 30 pies desde 20 mph para pasar la inspección.","p":"Correcto. Dentro de 30 pies."},"ref":{"doc":"ME","page":"2-4"}},{"id":"me-119","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, what is the least tire tread a passenger car needs to pass inspection?","o":["1/32 of an inch","4/32 of an inch","2/32 of an inch","6/32 of an inch"],"h1":"Heavy commercial vehicles need twice as much.","h2":"In Maine, tires must have at least 2/32 of an inch of tread to pass inspection; commercial vehicles of 10,000 pounds need 4/32.","p":"Right. 2/32 of an inch."},"es":{"q":"En Maine, ¿cuál es la profundidad mínima del dibujo de las llantas que necesita un auto para pasar la inspección?","o":["1/32 de pulgada","4/32 de pulgada","2/32 de pulgada","6/32 de pulgada"],"h1":"Los vehículos comerciales pesados necesitan el doble.","h2":"En Maine, las llantas deben tener al menos 2/32 de pulgada de dibujo para pasar la inspección; los vehículos comerciales de 10,000 libras necesitan 4/32.","p":"Correcto. 2/32 de pulgada."},"ref":{"doc":"ME","page":"2-4"}},{"id":"me-120","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, you arrive for your road test and the glove compartment door will not stay closed. What happens?","o":["The examiner tapes it shut","You get extra points","Nothing, it does not matter","The test will not be given in that vehicle"],"h1":"The vehicle check is part of the exam.","h2":"In Maine, the road test will not be given if any door does not work, a seat is not secured, or the glove compartment door is not fastened closed.","p":"Correct. The test will not be given."},"es":{"q":"En Maine, llegas a tu examen de manejo y la puerta de la guantera no se queda cerrada. ¿Qué pasa?","o":["El examinador la cierra con cinta","Recibes puntos extra","Nada, no importa","No se hará el examen en ese vehículo"],"h1":"La revisión del vehículo es parte del examen.","h2":"En Maine, el examen de manejo no se hace si alguna puerta no funciona, un asiento no está bien sujeto o la guantera no queda cerrada.","p":"Correcto. No se hará el examen."},"ref":{"doc":"ME","page":"2-4"}},{"id":"me-121","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, how much can your steering wheel turn without moving the wheels before it has too much play?","o":["Two inches or more","A quarter inch","Half a turn","There is no limit"],"h1":"It is a small but noticeable amount.","h2":"In Maine, the driver's manual says a steering wheel that turns two inches or more without moving the vehicle has too much play.","p":"Right. Two inches or more is too much play."},"es":{"q":"En Maine, ¿cuánto puede girar el volante sin mover las ruedas antes de que tenga demasiado juego?","o":["Dos pulgadas o más","Un cuarto de pulgada","Media vuelta","No hay límite"],"h1":"Es poco, pero se nota.","h2":"En Maine, el manual del conductor dice que un volante que gira dos pulgadas o más sin mover el vehículo tiene demasiado juego.","p":"Correcto. Dos pulgadas o más es demasiado juego."},"ref":{"doc":"ME","page":"2-5"}},{"id":"me-122","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a gasoline car may not give off visible smoke, other than water vapor, for more than how many seconds in a row?","o":["1 second","5 seconds","30 seconds","60 seconds"],"h1":"Count to five.","h2":"In Maine, a gasoline-powered vehicle may not emit visible smoke, other than water vapor, for more than 5 seconds in a row.","p":"Correct. No more than 5 seconds in a row."},"es":{"q":"En Maine, un auto de gasolina no puede echar humo visible, aparte de vapor de agua, por más de cuántos segundos seguidos?","o":["1 segundo","5 segundos","30 segundos","60 segundos"],"h1":"Cuenta hasta cinco.","h2":"En Maine, un vehículo de gasolina no puede echar humo visible, aparte de vapor de agua, por más de 5 segundos seguidos.","p":"Correcto. No más de 5 segundos seguidos."},"ref":{"doc":"ME","page":"2-5"}},{"id":"me-123","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, you push down on the front of your car and it bounces several times. What does the manual say this may mean?","o":["Your tires need air","Your oil is low","You may need new shocks","Your brakes are wet"],"h1":"It has to do with the suspension.","h2":"In Maine, the manual says that if your car bounces more than twice when you push down on it, you may need new shocks.","p":"Right. You may need new shocks."},"es":{"q":"En Maine, empujas hacia abajo la parte delantera de tu auto y rebota varias veces. ¿Qué puede significar, según el manual?","o":["A las llantas les falta aire","Te falta aceite","Puede que necesites amortiguadores nuevos","Los frenos están mojados"],"h1":"Tiene que ver con la suspensión.","h2":"En Maine, el manual dice que si el auto rebota más de dos veces al empujarlo hacia abajo, puede que necesites amortiguadores nuevos.","p":"Correcto. Puede que necesites amortiguadores nuevos."},"ref":{"doc":"ME","page":"2-5"}},{"id":"me-124","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, your car stereo can be heard 40 feet away and is over 85 decibels. What is the fine for a first offense?","o":["$10","$500","$1,000","$50"],"h1":"It doubles for a second offense.","h2":"In Maine, playing a sound system audible beyond 25 feet and over 85 decibels is a traffic infraction with a $50 fine for a first offense, $100 for a second and $150 after that.","p":"Correct. $50 for a first offense."},"es":{"q":"En Maine, el estéreo de tu auto se oye a 40 pies y pasa de 85 decibeles. ¿Cuál es la multa la primera vez?","o":["$10","$500","$1,000","$50"],"h1":"Se duplica la segunda vez.","h2":"En Maine, usar un equipo de sonido que se oye a más de 25 pies y pasa de 85 decibeles es una infracción con multa de $50 la primera vez, $100 la segunda y $150 después.","p":"Correcto. $50 la primera vez."},"ref":{"doc":"ME","page":"2-6"}},{"id":"me-125","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, on a long trip, how often does the driver's manual suggest taking a break?","o":["Every two hours or 100 miles","Every six hours","Every 300 miles","Only when you feel sleepy"],"h1":"It is a short time or distance.","h2":"In Maine, the driver's manual suggests a break every two hours or 100 miles, and sooner if you feel drowsy.","p":"Right. Every two hours or 100 miles."},"es":{"q":"En Maine, en un viaje largo, ¿cada cuánto sugiere el manual del conductor tomar un descanso?","o":["Cada dos horas o 100 millas","Cada seis horas","Cada 300 millas","Solo cuando tengas sueño"],"h1":"Es poco tiempo o distancia.","h2":"En Maine, el manual del conductor sugiere un descanso cada dos horas o 100 millas, y antes si sientes sueño.","p":"Correcto. Cada dos horas o 100 millas."},"ref":{"doc":"ME","page":"3-3"}},{"id":"me-126","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a drowsy driver can have a micro-sleep without knowing it. About how long does a micro-sleep last?","o":["Less than half a second","4 to 5 seconds","1 to 2 minutes","About 10 minutes"],"h1":"Long enough to travel the length of a football field at highway speed.","h2":"In Maine, the driver's manual says micro-sleeps last only four to five seconds, which can be deadly at 55 mph.","p":"Correct. About 4 to 5 seconds."},"es":{"q":"En Maine, un conductor con sueño puede tener un microsueño sin darse cuenta. ¿Cuánto dura más o menos un microsueño?","o":["Menos de medio segundo","De 4 a 5 segundos","De 1 a 2 minutos","Unos 10 minutos"],"h1":"Lo suficiente para recorrer una cancha de fútbol americano en carretera.","h2":"En Maine, el manual del conductor dice que los microsueños duran solo de cuatro a cinco segundos, lo que puede ser mortal a 55 mph.","p":"Correcto. De 4 a 5 segundos."},"ref":{"doc":"ME","page":"3-2"}},{"id":"me-127","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, a driver is upset and keeps thinking about an argument. Which type of distraction is this?","o":["Visual","Manual","Cognitive","Mechanical"],"h1":"It is in the mind.","h2":"In Maine, the driver's manual names three types of distraction: visual, manual and cognitive; thoughts and feelings like anger or worry are cognitive.","p":"Right. It is a cognitive distraction."},"es":{"q":"En Maine, un conductor está molesto y sigue pensando en una discusión. ¿Qué tipo de distracción es esta?","o":["Visual","Manual","Cognitiva","Mecánica"],"h1":"Está en la mente.","h2":"En Maine, el manual del conductor nombra tres tipos de distracción: visual, manual y cognitiva; los pensamientos y emociones como el enojo o la preocupación son cognitivos.","p":"Correcto. Es una distracción cognitiva."},"ref":{"doc":"ME","page":"3-4"}},{"id":"me-128","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, the driver's manual says quick glances at mirrors and gauges are safe if they last less than how long?","o":["Five seconds","Three seconds","Two seconds","One second"],"h1":"It is very short.","h2":"In Maine, the driver's manual says short glances at mirrors, gauges and installed devices can be safe if they last less than one second and relate to driving.","p":"Correct. Less than one second."},"es":{"q":"En Maine, el manual del conductor dice que mirar rápido los espejos e indicadores es seguro si dura menos de cuánto?","o":["Cinco segundos","Tres segundos","Dos segundos","Un segundo"],"h1":"Es muy corto.","h2":"En Maine, el manual del conductor dice que mirar brevemente espejos, indicadores y aparatos instalados puede ser seguro si dura menos de un segundo y tiene que ver con manejar.","p":"Correcto. Menos de un segundo."},"ref":{"doc":"ME","page":"3-4"}},{"id":"me-129","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, an adult driver is caught holding a phone to talk while driving for the first time. What is the fine?","o":["$50","$5","$1,000","$2,500"],"h1":"A second offense costs $250.","h2":"In Maine, using a hand-held phone or device while driving is a traffic infraction with a $50 fine for a first offense and $250 for later offenses.","p":"Right. $50 for a first offense."},"es":{"q":"En Maine, a un conductor adulto lo descubren por primera vez sosteniendo el teléfono para hablar mientras maneja. ¿Cuál es la multa?","o":["$50","$5","$1,000","$2,500"],"h1":"La segunda vez cuesta $250.","h2":"En Maine, usar un teléfono o aparato en la mano mientras manejas es una infracción con multa de $50 la primera vez y $250 las siguientes.","p":"Correcto. $50 la primera vez."},"ref":{"doc":"ME","page":null}},{"id":"me-130","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, what is the lowest fine for a first offense of texting while driving?","o":["$50","$250","$25","$100"],"h1":"It is higher than the fine for just holding a phone.","h2":"In Maine, texting while driving is a traffic infraction with a fine of at least $250 for a first offense.","p":"Correct. At least $250."},"es":{"q":"En Maine, ¿cuál es la multa mínima la primera vez por enviar mensajes de texto mientras manejas?","o":["$50","$250","$25","$100"],"h1":"Es más alta que la multa por solo sostener el teléfono.","h2":"En Maine, enviar mensajes de texto mientras manejas es una infracción con multa de al menos $250 la primera vez.","p":"Correcto. Al menos $250."},"ref":{"doc":"ME","page":null}},{"id":"me-131","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, a driver is found texting while driving for the second time within 3 years. Besides a fine of at least $500, what happens?","o":["Nothing more","A warning letter","A license suspension of at least 30 days","A free safety class"],"h1":"The Secretary of State acts without a hearing.","h2":"In Maine, a second texting violation within 3 years brings a fine of at least $500 and a license suspension of at least 30 days.","p":"Right. At least a 30-day suspension."},"es":{"q":"En Maine, a un conductor lo descubren enviando mensajes de texto mientras maneja por segunda vez en 3 años. Además de una multa de al menos $500, ¿qué pasa?","o":["Nada más","Una carta de advertencia","Una suspensión de licencia de al menos 30 días","Una clase de seguridad gratis"],"h1":"El Secretario de Estado actúa sin audiencia.","h2":"En Maine, una segunda infracción por mensajes de texto en 3 años trae una multa de al menos $500 y una suspensión de licencia de al menos 30 días.","p":"Correcto. Al menos 30 días de suspensión."},"ref":{"doc":"ME","page":null}},{"id":"me-132","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, at what alcohol level does the driver's manual say vision is already affected for all drivers?","o":["0.08","0.15","0.10","0.02"],"h1":"It is a very small amount, far below the legal limit for adults.","h2":"In Maine, the driver's manual says vision is affected at an alcohol level of 0.02 for all drivers.","p":"Correct. Vision is affected at 0.02."},"es":{"q":"En Maine, ¿a qué nivel de alcohol dice el manual del conductor que la vista ya se afecta en todos los conductores?","o":["0.08","0.15","0.10","0.02"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite legal para adultos.","h2":"En Maine, el manual del conductor dice que la vista se afecta con un nivel de alcohol de 0.02 en todos los conductores.","p":"Correcto. La vista se afecta con 0.02."},"ref":{"doc":"ME","page":"3-6"}},{"id":"me-133","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the driver's manual says it normally takes about how long for your eyes to recover from headlight glare?","o":["About 7 seconds","About 1 second","About 1 minute","About 30 seconds"],"h1":"At 55 mph you travel almost two football fields in that time.","h2":"In Maine, the driver's manual says eyes normally need about seven seconds to recover from headlight glare, and longer after drinking.","p":"Right. About 7 seconds."},"es":{"q":"En Maine, según el manual del conductor, ¿cuánto tardan normalmente tus ojos en recuperarse del deslumbramiento de los faros?","o":["Unos 7 segundos","Como 1 segundo","Como 1 minuto","Unos 30 segundos"],"h1":"A 55 mph recorres casi dos canchas de fútbol americano en ese tiempo.","h2":"En Maine, el manual del conductor dice que los ojos normalmente necesitan unos siete segundos para recuperarse del deslumbramiento, y más después de beber.","p":"Correcto. Unos 7 segundos."},"ref":{"doc":"ME","page":"3-7"}},{"id":"me-134","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, the driver's manual compares crash risk to alcohol level. At 0.15, about how many times higher is the chance of a crash?","o":["2 times","25 times","6 times","100 times"],"h1":"At 0.10 it is 6 times.","h2":"In Maine, the driver's manual says the chance of a crash is about 6 times higher at 0.10 and about 25 times higher at 0.15.","p":"Correct. About 25 times higher."},"es":{"q":"En Maine, el manual del conductor compara el riesgo de choque con el nivel de alcohol. Con 0.15, ¿cuántas veces más alta es la probabilidad de chocar?","o":["2 veces","25 veces","6 veces","100 veces"],"h1":"Con 0.10 son 6 veces.","h2":"En Maine, el manual del conductor dice que la probabilidad de chocar es unas 6 veces mayor con 0.10 y unas 25 veces mayor con 0.15.","p":"Correcto. Unas 25 veces mayor."},"ref":{"doc":"ME","page":"3-8"}},{"id":"me-135","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, the driver's manual says a 12-ounce can of beer has about the same alcohol as which drink?","o":["A 12-ounce glass of wine","Three shots of liquor","A 4-ounce glass of table wine","Half a shot of liquor"],"h1":"Beer is not weaker than other drinks.","h2":"In Maine, the driver's manual says a 12-ounce beer has about the same alcohol as a 1-ounce shot of 100-proof liquor, a 4-ounce glass of wine or a 10-ounce wine cooler.","p":"Right. About the same as a 4-ounce glass of wine."},"es":{"q":"En Maine, según el manual del conductor, una lata de cerveza de 12 onzas tiene más o menos el mismo alcohol que ¿qué bebida?","o":["Una copa de vino de 12 onzas","Tres tragos de licor","Una copa de vino de mesa de 4 onzas","Medio trago de licor"],"h1":"La cerveza no es más suave que otras bebidas.","h2":"En Maine, el manual del conductor dice que una cerveza de 12 onzas tiene casi el mismo alcohol que un trago de 1 onza de licor de 100 grados, una copa de vino de 4 onzas o un wine cooler de 10 onzas.","p":"Correcto. Casi lo mismo que una copa de vino de 4 onzas."},"ref":{"doc":"ME","page":"3-8"}},{"id":"me-136","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, a driver is arrested with an alcohol level of 0.09. When does the Secretary of State suspend the license?","o":["Only after a jury trial","Only after a second offense","Only if there was a crash","Right away, before any court appearance"],"h1":"It is based on the police report and the test result.","h2":"In Maine, the Secretary of State suspends the license right away, based on the police report and test result, before any court appearance.","p":"Correct. The suspension comes before court."},"es":{"q":"En Maine, arrestan a un conductor con nivel de alcohol de 0.09. ¿Cuándo suspende la licencia el Secretario de Estado?","o":["Solo después de un juicio con jurado","Solo después de una segunda infracción","Solo si hubo un choque","De inmediato, antes de cualquier comparecencia en la corte"],"h1":"Se basa en el informe policial y el resultado de la prueba.","h2":"En Maine, el Secretario de Estado suspende la licencia de inmediato, según el informe policial y el resultado de la prueba, antes de cualquier comparecencia en la corte.","p":"Correcto. La suspensión llega antes de la corte."},"ref":{"doc":"ME","page":"3-9"}},{"id":"me-137","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the officer decides a breath test is not reasonable. What test must the driver take instead?","o":["A blood test, possibly by a physician of the driver's choice","A urine test at home","No test at all","A second breath test the next day"],"h1":"It measures alcohol in a sample from a vein.","h2":"In Maine, if the breath test is not given, the driver must take a blood test, which may be given by a physician of the driver's choice if one is reasonably available.","p":"Right. A blood test, possibly by the driver's own physician."},"es":{"q":"En Maine, el agente decide que no es razonable hacer la prueba de aliento. ¿Qué prueba debe hacerse el conductor?","o":["Una prueba de sangre, posiblemente por un médico que el conductor elija","Una prueba de orina en casa","Ninguna prueba","Otra prueba de aliento al día siguiente"],"h1":"Mide el alcohol en una muestra de una vena.","h2":"En Maine, si no se hace la prueba de aliento, el conductor debe hacerse una prueba de sangre, que puede hacer un médico de su elección si está razonablemente disponible.","p":"Correcto. Una prueba de sangre, posiblemente con su propio médico."},"ref":{"doc":"ME","page":"3-9"}},{"id":"me-138","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a driver refuses a requested alcohol test. For up to how long may the Secretary of State suspend the license?","o":["30 days","Six years","Six months","One week"],"h1":"It is an administrative suspension, and it can be very long.","h2":"In Maine, under implied consent, refusing an alcohol test brings an immediate administrative suspension of up to six years.","p":"Correct. Up to six years."},"es":{"q":"En Maine, un conductor se niega a una prueba de alcohol solicitada. ¿Hasta por cuánto tiempo puede el Secretario de Estado suspenderle la licencia?","o":["30 días","Seis años","Seis meses","Una semana"],"h1":"Es una suspensión administrativa y puede ser muy larga.","h2":"En Maine, por el consentimiento implícito, negarse a una prueba de alcohol trae una suspensión administrativa inmediata de hasta seis años.","p":"Correcto. Hasta seis años."},"ref":{"doc":"ME","page":"3-9"}},{"id":"me-139","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, a driver refused an alcohol test and is later found not guilty of OUI. What happens to the refusal suspension?","o":["It is cancelled","It is cut in half","It stays in effect","It turns into a fine"],"h1":"It is separate from the court case.","h2":"In Maine, the administrative suspension for refusing a test stays in effect even if the driver is later found not guilty of OUI.","p":"Right. The suspension stays."},"es":{"q":"En Maine, un conductor se negó a la prueba de alcohol y luego lo declaran inocente de OUI. ¿Qué pasa con la suspensión por negarse?","o":["Se cancela","Se reduce a la mitad","Sigue vigente","Se convierte en multa"],"h1":"Es aparte del caso en la corte.","h2":"En Maine, la suspensión administrativa por negarse a la prueba sigue vigente aunque después declaren al conductor inocente de OUI.","p":"Correcto. La suspensión sigue."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-140","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, what is the lowest fine for a first OUI conviction when the driver also refused the alcohol test?","o":["$100","$500","$2,000","$600"],"h1":"It is $100 more than without a refusal.","h2":"In Maine, a first OUI conviction carries a fine of at least $500, or at least $600 if the driver refused the test.","p":"Correct. At least $600 with a refusal."},"es":{"q":"En Maine, ¿cuál es la multa mínima por una primera condena de OUI cuando el conductor también se negó a la prueba de alcohol?","o":["$100","$500","$2,000","$600"],"h1":"Son $100 más que sin negarse.","h2":"En Maine, una primera condena de OUI trae una multa de al menos $500, o al menos $600 si el conductor se negó a la prueba.","p":"Correcto. Al menos $600 si se negó."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-141","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, a first-time OUI offender refused the alcohol test. What is the shortest jail time?","o":["96 hours","24 hours","12 hours","No jail time"],"h1":"It is double the 48 hours for a high alcohol level.","h2":"In Maine, a first OUI conviction with a test refusal brings at least 96 hours in jail.","p":"Right. At least 96 hours."},"es":{"q":"En Maine, alguien condenado por primera vez por OUI se negó a la prueba de alcohol. ¿Cuál es el tiempo mínimo en la cárcel?","o":["96 horas","24 horas","12 horas","Nada de cárcel"],"h1":"Es el doble de las 48 horas por nivel alto de alcohol.","h2":"En Maine, una primera condena de OUI con negativa a la prueba trae al menos 96 horas de cárcel.","p":"Correcto. Al menos 96 horas."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-142","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a driver is convicted of a first OUI at 0.09 while going 35 mph over the speed limit. What else does the speed add?","o":["Nothing more","At least 48 hours in jail","A free license after 30 days","Only a warning"],"h1":"Going 30 mph or more over the limit is an aggravating factor.","h2":"In Maine, a first OUI with speeding 30 mph or more over the limit brings at least 48 hours in jail, the same as a high alcohol level.","p":"Correct. At least 48 hours in jail."},"es":{"q":"En Maine, condenan a un conductor por un primer OUI con 0.09 mientras iba 35 mph sobre el límite. ¿Qué más agrega la velocidad?","o":["Nada más","Al menos 48 horas de cárcel","Una licencia gratis después de 30 días","Solo una advertencia"],"h1":"Ir 30 mph o más sobre el límite es un agravante.","h2":"En Maine, un primer OUI con exceso de 30 mph o más sobre el límite trae al menos 48 horas de cárcel, igual que un nivel alto de alcohol.","p":"Correcto. Al menos 48 horas de cárcel."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-143","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, can a driver get a work license during the minimum suspension for an OUI conviction?","o":["Yes, after one week","Yes, if they have a job","No, there is no work or limited license during that time","Only on weekends"],"h1":"Offenders are fully barred from driving at first.","h2":"In Maine, there is no work or limited license during the minimum suspension for an OUI conviction.","p":"Right. No work license at all."},"es":{"q":"En Maine, ¿puede un conductor obtener una licencia para ir al trabajo durante la suspensión mínima por una condena de OUI?","o":["Sí, después de una semana","Sí, si tiene empleo","No, no hay licencia de trabajo ni limitada en ese tiempo","Solo los fines de semana"],"h1":"Al principio los infractores no pueden manejar en absoluto.","h2":"En Maine, no hay licencia de trabajo ni limitada durante la suspensión mínima por una condena de OUI.","p":"Correcto. No hay licencia de trabajo."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-144","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, what must a person convicted of a second OUI show before the license is reinstated?","o":["A new birth certificate","A road test score","A letter from an employer","Proof of liability insurance"],"h1":"It is about insurance.","h2":"In Maine, second and later OUI offenders must show proof of liability insurance before their license is reinstated.","p":"Correct. Proof of liability insurance."},"es":{"q":"En Maine, ¿qué debe mostrar una persona condenada por un segundo OUI antes de que le devuelvan la licencia?","o":["Un acta de nacimiento nueva","Un resultado de examen de manejo","Una carta de su empleador","Prueba de seguro de responsabilidad civil"],"h1":"Tiene que ver con el seguro.","h2":"En Maine, quienes tienen un segundo OUI o más deben mostrar prueba de seguro de responsabilidad civil antes de recuperar la licencia.","p":"Correcto. Prueba de seguro de responsabilidad civil."},"ref":{"doc":"ME","page":"3-10"}},{"id":"me-145","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, a driver convicted of OUI had a passenger under 21 in the car. How much extra suspension is added?","o":["275 days","30 days","10 days","5 years"],"h1":"It is a little over nine months.","h2":"In Maine, 275 days are added to the OUI or refusal suspension if a passenger under 21 was in the vehicle.","p":"Right. 275 extra days."},"es":{"q":"En Maine, un conductor condenado por OUI llevaba un pasajero menor de 21 años. ¿Cuánta suspensión adicional se agrega?","o":["275 días","30 días","10 días","5 años"],"h1":"Es un poco más de nueve meses.","h2":"En Maine, se agregan 275 días a la suspensión por OUI o por negarse a la prueba si iba un pasajero menor de 21 años en el vehículo.","p":"Correcto. 275 días más."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-146","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, after a second OUI conviction, how long is the reinstated license conditional on no alcohol use while driving?","o":["1 year","10 years","2 years","6 months"],"h1":"After a first conviction it is one year; after a second it is much longer.","h2":"In Maine, after a second or later OUI conviction, the reinstated license is conditional for ten years.","p":"Correct. Ten years."},"es":{"q":"En Maine, después de una segunda condena de OUI, ¿por cuánto tiempo la licencia devuelta queda condicionada a no tener alcohol al manejar?","o":["1 año","10 años","2 años","6 meses"],"h1":"Después de la primera condena es un año; después de la segunda es mucho más.","h2":"En Maine, después de una segunda condena de OUI o más, la licencia devuelta es condicional por diez años.","p":"Correcto. Diez años."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-147","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, a driver with a conditional license after OUI is caught driving with a small amount of alcohol. What happens?","o":["A warning only","A $50 fine","A one-year suspension without a preliminary hearing","Nothing if it is under 0.08"],"h1":"Conditional means no alcohol at all.","h2":"In Maine, a conditional licensee who drives with any amount of alcohol has the license suspended for one year without a preliminary hearing.","p":"Right. A one-year suspension."},"es":{"q":"En Maine, a un conductor con licencia condicional por OUI lo encuentran manejando con un poco de alcohol. ¿Qué pasa?","o":["Solo una advertencia","Una multa de $50","Una suspensión de un año sin audiencia previa","Nada si es menos de 0.08"],"h1":"Condicional significa nada de alcohol.","h2":"En Maine, a quien tiene licencia condicional y maneja con cualquier cantidad de alcohol se le suspende la licencia por un año sin audiencia previa.","p":"Correcto. Una suspensión de un año."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-148","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, a driver with a conditional license after OUI refuses an alcohol test. How long is the added suspension?","o":["30 days","90 days","6 months","Two years"],"h1":"It is added on top of any earlier suspension.","h2":"In Maine, a conditional licensee who refuses an alcohol test has the license suspended for two years, added to any earlier OUI suspension.","p":"Correct. Two years."},"es":{"q":"En Maine, un conductor con licencia condicional por OUI se niega a una prueba de alcohol. ¿Cuánto dura la suspensión adicional?","o":["30 días","90 días","6 meses","Dos años"],"h1":"Se suma a cualquier suspensión anterior.","h2":"En Maine, a quien tiene licencia condicional y se niega a una prueba de alcohol se le suspende la licencia por dos años, sumados a cualquier suspensión anterior por OUI.","p":"Correcto. Dos años."},"ref":{"doc":"ME","page":"3-11"}},{"id":"me-149","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, a driver is arrested for OUI. What may also happen to the vehicle?","o":["It may be seized, and the driver pays towing and storage","It is always returned the same day","It is painted a warning color","Nothing happens to the vehicle"],"h1":"You could lose more than your license.","h2":"In Maine, a person arrested for OUI may have the vehicle seized and must pay towing and storage fees, along with a fine and jail time.","p":"Right. The vehicle may be seized."},"es":{"q":"En Maine, arrestan a un conductor por OUI. ¿Qué más puede pasar con su vehículo?","o":["Pueden incautarlo, y el conductor paga la grúa y el almacenaje","Siempre se lo devuelven el mismo día","Lo pintan de un color de advertencia","No le pasa nada al vehículo"],"h1":"Podrías perder más que tu licencia.","h2":"En Maine, a una persona arrestada por OUI le pueden incautar el vehículo y debe pagar la grúa y el almacenaje, además de multa y cárcel.","p":"Correcto. Pueden incautar el vehículo."},"ref":{"doc":"ME","page":"3-12"}},{"id":"me-150","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, every driver in a crash where someone died must take a chemical test. What happens to a driver who fails to do so?","o":["A $25 fine","A one-year license suspension","A warning letter","Nothing"],"h1":"It is a full year.","h2":"In Maine, every driver in a fatal crash, or one where death is likely, must take a chemical test, and failing to do so brings a one-year suspension.","p":"Correct. A one-year suspension."},"es":{"q":"En Maine, todo conductor en un choque donde murió alguien debe hacerse una prueba química. ¿Qué le pasa al conductor que no lo hace?","o":["Una multa de $25","Una suspensión de licencia de un año","Una carta de advertencia","Nada"],"h1":"Es un año completo.","h2":"En Maine, todo conductor en un choque mortal, o donde es probable que alguien muera, debe hacerse una prueba química, y no hacerlo trae una suspensión de un año.","p":"Correcto. Una suspensión de un año."},"ref":{"doc":"ME","page":"3-12"}},{"id":"me-151","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, a passenger has an open can of beer in a vehicle that has no trunk. Where may it be kept legally?","o":["In the cup holder","On the floor by the passenger's feet","Behind the last upright seat","In the glove box"],"h1":"It must be away from where people sit.","h2":"In Maine, in a vehicle without a trunk, an open alcohol container may be kept behind the last upright seat or in an area not normally occupied by people.","p":"Right. Behind the last upright seat."},"es":{"q":"En Maine, un pasajero lleva una lata de cerveza abierta en un vehículo sin cajuela. ¿Dónde se puede llevar legalmente?","o":["En el portavasos","En el piso junto a los pies del pasajero","Detrás del último asiento vertical","En la guantera"],"h1":"Debe estar lejos de donde se sienta la gente.","h2":"En Maine, en un vehículo sin cajuela, un envase de alcohol abierto se puede llevar detrás del último asiento vertical o en un área donde normalmente no van personas.","p":"Correcto. Detrás del último asiento vertical."},"ref":{"doc":"ME","page":"3-13"}},{"id":"me-152","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, according to the driver's manual, one drink over the legal limit could cost a driver more than what amount in total?","o":["$100","$500","$1,500","$7,000"],"h1":"Add up the lawyer, fine, insurance and more.","h2":"In Maine, the driver's manual estimates that one OUI can cost well over $7,000 once fines, lawyer fees, insurance and other costs are added up.","p":"Correct. More than $7,000."},"es":{"q":"En Maine, según el manual del conductor, un trago de más sobre el límite legal le podría costar a un conductor más de qué cantidad en total?","o":["$100","$500","$1,500","$7,000"],"h1":"Suma abogado, multa, seguro y más.","h2":"En Maine, el manual del conductor calcula que un OUI puede costar mucho más de $7,000 sumando multas, abogado, seguro y otros gastos.","p":"Correcto. Más de $7,000."},"ref":{"doc":"ME","page":"3-13"}},{"id":"me-153","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, when may a 19-year-old legally carry alcohol in a car?","o":["Only for work or at the request of a parent or guardian","Any time the bottles are closed","Only on weekends","Never, under any condition"],"h1":"There are two narrow exceptions.","h2":"In Maine, a person under 21 may not transport alcohol in a motor vehicle unless it is part of their job or at the request of a parent or guardian.","p":"Right. Only for work or at a parent's request."},"es":{"q":"En Maine, ¿cuándo puede legalmente un joven de 19 años llevar alcohol en un auto?","o":["Solo por su trabajo o a pedido de su padre, madre o tutor","Siempre que las botellas estén cerradas","Solo los fines de semana","Nunca, bajo ninguna condición"],"h1":"Hay dos excepciones muy limitadas.","h2":"En Maine, una persona menor de 21 años no puede transportar alcohol en un vehículo salvo que sea parte de su trabajo o a pedido de su padre, madre o tutor.","p":"Correcto. Solo por trabajo o a pedido de los padres."},"ref":{"doc":"ME","page":"3-14"}},{"id":"me-154","scope":"ME","cat":"licensing","sign":null,"c":2,"en":{"q":"In Maine, for the OUI laws, until what age are all licenses issued to young drivers considered provisional?","o":["Until age 18","Until age 19","Until age 21","Until age 25"],"h1":"It is the legal drinking age.","h2":"In Maine, for the OUI laws, every license issued to a person under 21 is provisional and subject to immediate suspension until that person turns 21.","p":"Right. Until age 21."},"es":{"q":"En Maine, para las leyes de OUI, ¿hasta qué edad se consideran provisionales todas las licencias de los conductores jóvenes?","o":["Hasta los 18 años","Hasta los 19 años","Hasta los 21 años","Hasta los 25 años"],"h1":"Es la edad legal para beber.","h2":"En Maine, para las leyes de OUI, toda licencia de una persona menor de 21 años es provisional y se puede suspender de inmediato hasta que cumpla 21.","p":"Correcto. Hasta los 21 años."},"ref":{"doc":"ME","page":"3-14"}},{"id":"me-155","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, a driver has a long-term medical condition that could affect driving. Who helps decide whether they can drive safely?","o":["Only the driver","Only a family member","Their insurance agent","The Bureau of Motor Vehicles shares in the decision"],"h1":"For short illnesses you decide; for long-term conditions you do not decide alone.","h2":"In Maine, for long-term conditions that could affect driving, the Bureau of Motor Vehicles shares in the decision about whether and how the person may drive.","p":"Correct. The BMV shares in the decision."},"es":{"q":"En Maine, un conductor tiene una condición médica de largo plazo que podría afectar su manejo. ¿Quién ayuda a decidir si puede manejar con seguridad?","o":["Solo el conductor","Solo un familiar","Su agente de seguros","La Oficina de Vehículos Motorizados participa en la decisión"],"h1":"En enfermedades cortas decides tú; en condiciones de largo plazo no decides solo.","h2":"En Maine, en condiciones de largo plazo que podrían afectar el manejo, la Oficina de Vehículos Motorizados participa en la decisión sobre si la persona puede manejar y cómo.","p":"Correcto. La BMV participa en la decisión."},"ref":{"doc":"ME","page":"3-15"}},{"id":"me-156","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the driver's manual says to leave how much space between your chest and the steering wheel because of the air bag?","o":["10 inches","2 inches","4 inches","24 inches"],"h1":"It is a bit less than a foot.","h2":"In Maine, the driver's manual says to leave 10 inches between your chest and the steering wheel because of the air bag.","p":"Right. 10 inches."},"es":{"q":"En Maine, el manual del conductor dice que dejes cuánto espacio entre tu pecho y el volante por la bolsa de aire?","o":["10 pulgadas","2 pulgadas","4 pulgadas","24 pulgadas"],"h1":"Es un poco menos de un pie.","h2":"En Maine, el manual del conductor dice que dejes 10 pulgadas entre tu pecho y el volante por la bolsa de aire.","p":"Correcto. 10 pulgadas."},"ref":{"doc":"ME","page":"4-1"}},{"id":"me-157","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, the driver's manual says lap and shoulder belts, used properly, cut the risk of serious or fatal injury by about how much?","o":["5 to 10 percent","15 to 20 percent","90 to 95 percent","40 to 55 percent"],"h1":"It is close to half.","h2":"In Maine, the driver's manual says lap and shoulder belts used properly reduce the risk of serious or fatal injury by 40 to 55 percent.","p":"Correct. About 40 to 55 percent."},"es":{"q":"En Maine, según el manual del conductor, ¿cuánto reducen los cinturones de regazo y hombro, bien usados, el riesgo de lesiones graves o mortales?","o":["Del 5 al 10 por ciento","Del 15 al 20 por ciento","Del 90 al 95 por ciento","Del 40 al 55 por ciento"],"h1":"Es cerca de la mitad.","h2":"En Maine, el manual del conductor dice que los cinturones de regazo y hombro bien usados reducen el riesgo de lesiones graves o mortales del 40 al 55 por ciento.","p":"Correcto. Del 40 al 55 por ciento."},"ref":{"doc":"ME","page":"4-3"}},{"id":"me-158","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the driver's manual says children of what age and younger should always ride in the back seat?","o":["12","5","8","16"],"h1":"It is the age just before the teen years.","h2":"In Maine, the driver's manual says all children age 12 and younger should ride in the back seat.","p":"Right. Age 12 and younger."},"es":{"q":"En Maine, según el manual del conductor, ¿los niños de qué edad o menores deben ir siempre en el asiento de atrás?","o":["12","5","8","16"],"h1":"Es la edad justo antes de la adolescencia.","h2":"En Maine, el manual del conductor dice que todos los niños de 12 años o menos deben ir en el asiento de atrás.","p":"Correcto. 12 años o menos."},"ref":{"doc":"ME","page":"4-4"}},{"id":"me-159","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, a 10-year-old weighs 85 pounds. What must the child use in the car?","o":["A rear-facing car seat","A seat belt","No restraint at all","A child safety seat with a harness"],"h1":"The child is older than 8 and heavier than 80 pounds.","h2":"In Maine, a child under 18 who is older than 8 or taller than 4 feet 9 inches must be properly secured in a seat belt.","p":"Correct. A seat belt."},"es":{"q":"En Maine, un niño de 10 años pesa 85 libras. ¿Qué debe usar en el auto?","o":["Un asiento orientado hacia atrás","El cinturón de seguridad","Nada","Un asiento de seguridad infantil con arnés"],"h1":"El niño tiene más de 8 años y pesa más de 80 libras.","h2":"En Maine, un menor de 18 años que tiene más de 8 años o mide más de 4 pies 9 pulgadas debe ir bien asegurado con el cinturón de seguridad.","p":"Correcto. El cinturón de seguridad."},"ref":{"doc":"ME","page":"4-5"}},{"id":"me-160","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, which worker is not required to wear a seat belt while doing their job?","o":["A pizza delivery driver","A school bus passenger","A rural mail carrier delivering mail","A taxi passenger"],"h1":"They stop at many mailboxes.","h2":"In Maine, a rural mail carrier of the U.S. Postal Service does not have to wear a seat belt while delivering mail; newspaper delivery people have a similar exception.","p":"Right. A rural mail carrier on the route."},"es":{"q":"En Maine, ¿qué trabajador no tiene que usar el cinturón de seguridad mientras hace su trabajo?","o":["Un repartidor de pizza","Un pasajero de autobús escolar","Un cartero rural entregando correo","Un pasajero de taxi"],"h1":"Se detiene en muchos buzones.","h2":"En Maine, un cartero rural del Servicio Postal no tiene que usar el cinturón mientras entrega correo; los repartidores de periódicos tienen una excepción parecida.","p":"Correcto. Un cartero rural en su ruta."},"ref":{"doc":"ME","page":"4-5"}},{"id":"me-161","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, who is responsible for buckling up a paying passenger in a taxicab?","o":["The taxi driver","The taxi company owner","The police","Not the taxi driver; the driver is not responsible"],"h1":"Maine makes an exception for drivers for hire.","h2":"In Maine, the driver of a taxicab or limousine is not responsible for securing a passenger who pays a fee in a seat belt.","p":"Correct. The taxi driver is not responsible."},"es":{"q":"En Maine, ¿quién es responsable de abrochar el cinturón de un pasajero que paga en un taxi?","o":["El taxista","El dueño de la compañía de taxis","La policía","No el taxista; el conductor no es responsable"],"h1":"Maine hace una excepción para los conductores de alquiler.","h2":"En Maine, el conductor de un taxi o limusina no es responsable de abrochar el cinturón de un pasajero que paga.","p":"Correcto. El taxista no es responsable."},"ref":{"doc":"ME","page":"4-5"}},{"id":"me-162","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, you must stop where the driver behind will not expect it. What does the manual say to do?","o":["Tap the brake pedal three or four times quickly","Honk the horn twice","Turn on the high beams","Stick your hand out the window"],"h1":"Your brake lights can blink a warning.","h2":"In Maine, the driver's manual says to tap the brake pedal three or four times quickly to warn the driver behind before an unexpected stop.","p":"Right. Tap the brake pedal three or four times."},"es":{"q":"En Maine, debes detenerte donde el conductor de atrás no lo espera. ¿Qué dice el manual que hagas?","o":["Tocar el pedal del freno tres o cuatro veces rápido","Tocar la bocina dos veces","Prender las luces altas","Sacar la mano por la ventana"],"h1":"Las luces de freno pueden parpadear como aviso.","h2":"En Maine, el manual del conductor dice que toques el pedal del freno tres o cuatro veces rápido para avisar al conductor de atrás antes de una parada inesperada.","p":"Correcto. Toca el pedal del freno tres o cuatro veces."},"ref":{"doc":"ME","page":"5-3"}},{"id":"me-163","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, the driver's manual says not to let your engine idle for more than how long when starting or stopping?","o":["10 minutes","5 minutes","One minute","Half an hour"],"h1":"Idling burns about a cup of gas every six minutes.","h2":"In Maine, the driver's manual says not to idle for more than one minute, because the average car burns about a cup of gas every six minutes when idling.","p":"Right. One minute."},"es":{"q":"En Maine, el manual del conductor dice que no dejes el motor encendido sin moverte por más de cuánto tiempo al arrancar o detenerte?","o":["10 minutos","5 minutos","Un minuto","Media hora"],"h1":"Un auto en marcha sin moverse gasta como una taza de gasolina cada seis minutos.","h2":"En Maine, el manual del conductor dice que no dejes el motor en marcha sin moverte por más de un minuto, porque el auto promedio gasta como una taza de gasolina cada seis minutos.","p":"Correcto. Un minuto."},"ref":{"doc":"ME","page":"5-4"}},{"id":"me-164","scope":"ME","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maine, a driver does not pull over and stop for an ambulance using its siren and flashing lights. What is this?","o":["Only a parking ticket","A warning","A civil violation with no fine","A Class E crime"],"h1":"Maine treats it as a crime, not just an infraction.","h2":"In Maine, failing to pull to the right and stop for an emergency vehicle using its siren and flashing lights is a Class E crime.","p":"Correct. It is a Class E crime."},"es":{"q":"En Maine, un conductor no se orilla ni se detiene ante una ambulancia con sirena y luces intermitentes. ¿Qué es esto?","o":["Solo una multa de estacionamiento","Una advertencia","Una infracción civil sin multa","Un delito Clase E"],"h1":"Maine lo trata como delito, no solo como infracción.","h2":"En Maine, no orillarse a la derecha y detenerse ante un vehículo de emergencia con sirena y luces intermitentes es un delito Clase E.","p":"Correcto. Es un delito Clase E."},"ref":{"doc":"ME","page":"6-2"}},{"id":"me-165","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, you are turning left and a person on roller skis is coming from the opposite direction. What must you do?","o":["Yield to the roller skier","Turn first because you are larger","Honk and go","Flash your lights and turn"],"h1":"Maine treats roller skiers like bicyclists here.","h2":"In Maine, a driver turning left must yield to bicycle and roller ski operators coming from the opposite direction.","p":"Right. Yield to the roller skier."},"es":{"q":"En Maine, vas a girar a la izquierda y viene una persona en esquís de ruedas (roller skis) en sentido contrario. ¿Qué debes hacer?","o":["Ceder el paso a la persona en esquís de ruedas","Girar primero porque eres más grande","Tocar la bocina y seguir","Hacer cambio de luces y girar"],"h1":"Aquí Maine trata a quien usa esquís de ruedas como a un ciclista.","h2":"En Maine, el conductor que gira a la izquierda debe ceder el paso a ciclistas y personas en esquís de ruedas que vienen en sentido contrario.","p":"Correcto. Cede el paso a la persona en esquís de ruedas."},"ref":{"doc":"ME","page":"6-2"}},{"id":"me-166","scope":"ME","cat":"signals","sign":null,"c":1,"en":{"q":"In Maine, the light ahead is red, so you cut through a gas station lot to turn the corner. Is this legal?","o":["Yes, if you drive slowly","No, you may not drive through a parking area to avoid a traffic control","Yes, if no one is parked there","Only at night"],"h1":"Think about why the signal is there.","h2":"In Maine, a driver may not go through a parking area to avoid obeying a traffic signal or other traffic control device.","p":"Correct. Cutting through a lot to avoid the light is illegal."},"es":{"q":"En Maine, el semáforo de adelante está en rojo, así que atraviesas el estacionamiento de una gasolinera para dar la vuelta. ¿Es legal?","o":["Sí, si vas despacio","No, no puedes atravesar un estacionamiento para evitar un control de tránsito","Sí, si no hay nadie estacionado","Solo de noche"],"h1":"Piensa en por qué está el semáforo.","h2":"En Maine, un conductor no puede atravesar un estacionamiento para evitar obedecer un semáforo u otro control de tránsito.","p":"Correcto. Atravesar un estacionamiento para evitar el semáforo es ilegal."},"ref":{"doc":"ME","page":"6-3"}},{"id":"me-167","scope":"ME","cat":"signals","sign":null,"c":2,"en":{"q":"In Maine, what does a flashing yellow X over a lane mean?","o":["Do not drive in this lane","Clear the lane; it will turn red","The lane may only be used for a left turn","Speed up and pass"],"h1":"It is about turning.","h2":"In Maine, a flashing yellow X over a lane means the lane may be used only for a left turn.","p":"Right. Left turns only."},"es":{"q":"En Maine, ¿qué significa una X amarilla intermitente sobre un carril?","o":["No manejes en este carril","Desocupa el carril; se pondrá en rojo","El carril solo se puede usar para girar a la izquierda","Acelera y rebasa"],"h1":"Tiene que ver con girar.","h2":"En Maine, una X amarilla intermitente sobre un carril significa que ese carril solo se puede usar para girar a la izquierda.","p":"Correcto. Solo para girar a la izquierda."},"ref":{"doc":"ME","page":"6-4"}},{"id":"me-168","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, on a part of the Maine Turnpike or I-95 with three lanes each way, where may large trucks drive?","o":["In any lane","Only in the left lane","Only in the middle lane","Only in the two right-hand lanes"],"h1":"Pickup trucks are not included in this rule.","h2":"In Maine, on three-lane sections of the Maine Turnpike or I-95, trucks other than pickups may use only the two right-hand lanes.","p":"Correct. Only the two right-hand lanes."},"es":{"q":"En Maine, en un tramo del Maine Turnpike o la I-95 con tres carriles por sentido, ¿por dónde pueden ir los camiones grandes?","o":["Por cualquier carril","Solo por el carril izquierdo","Solo por el carril del medio","Solo por los dos carriles de la derecha"],"h1":"Las camionetas pickup no entran en esta regla.","h2":"En Maine, en los tramos de tres carriles del Maine Turnpike o la I-95, los camiones que no son pickup solo pueden usar los dos carriles de la derecha.","p":"Correcto. Solo los dos carriles de la derecha."},"ref":{"doc":"ME","page":"6-9"}},{"id":"me-169","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, what is the fine range for failing to yield to a pedestrian using a white cane or a guide dog?","o":["$50 to $1,000","$5 to $25","$10 to $100","$2,000 to $5,000"],"h1":"The top amount is a thousand dollars.","h2":"In Maine, failing to yield to a visually impaired pedestrian is a traffic infraction with a fine of at least $50 and up to $1,000.","p":"Right. $50 to $1,000."},"es":{"q":"En Maine, ¿cuál es el rango de la multa por no ceder el paso a un peatón con bastón blanco o perro guía?","o":["De $50 a $1,000","De $5 a $25","De $10 a $100","De $2,000 a $5,000"],"h1":"La cantidad más alta es de mil dólares.","h2":"En Maine, no ceder el paso a un peatón con discapacidad visual es una infracción con multa de al menos $50 y hasta $1,000.","p":"Correcto. De $50 a $1,000."},"ref":{"doc":"ME","page":"6-12"}},{"id":"me-170","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, you are in a large rotary and plan to leave within the next two exits. Which lane does the manual suggest?","o":["The leftmost lane","The rightmost lane","The center lane","Any lane"],"h1":"You will leave soon, and exits are to the right.","h2":"In Maine, the driver's manual suggests using the rightmost lane of a rotary if you will exit within two exits, unless signs or markings say otherwise.","p":"Correct. The rightmost lane."},"es":{"q":"En Maine, estás en una rotonda grande y piensas salir en una de las dos próximas salidas. ¿Qué carril sugiere el manual?","o":["El carril de más a la izquierda","El carril de más a la derecha","El carril del centro","Cualquier carril"],"h1":"Saldrás pronto, y las salidas están a la derecha.","h2":"En Maine, el manual del conductor sugiere usar el carril de más a la derecha de una rotonda si vas a salir dentro de dos salidas, salvo que señales o marcas indiquen otra cosa.","p":"Correcto. El carril de más a la derecha."},"ref":{"doc":"ME","page":"7-3"}},{"id":"me-171","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, at least how far ahead should you signal before changing lanes?","o":["10 feet","25 feet","100 feet","1,000 feet"],"h1":"It is about the length of six cars.","h2":"In Maine, the driver's manual says to signal at least 100 feet before changing lanes.","p":"Right. At least 100 feet."},"es":{"q":"En Maine, ¿con cuánta anticipación mínima debes poner la direccional antes de cambiar de carril?","o":["10 pies","25 pies","100 pies","1,000 pies"],"h1":"Es como el largo de seis autos.","h2":"En Maine, el manual del conductor dice que pongas la direccional al menos 100 pies antes de cambiar de carril.","p":"Correcto. Al menos 100 pies."},"ref":{"doc":"ME","page":"7-4"}},{"id":"me-172","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, at highway speeds of 50 to 55 mph, about how long does it take to pass another car safely?","o":["2 to 3 seconds","4 to 5 seconds","30 seconds","10 to 12 seconds"],"h1":"It takes longer than most people think.","h2":"In Maine, the driver's manual says you need about 10 to 12 seconds to pass safely at 50 to 55 mph.","p":"Correct. About 10 to 12 seconds."},"es":{"q":"En Maine, a velocidades de carretera de 50 a 55 mph, ¿cuánto tiempo toma más o menos rebasar a otro auto con seguridad?","o":["De 2 a 3 segundos","De 4 a 5 segundos","30 segundos","De 10 a 12 segundos"],"h1":"Toma más de lo que mucha gente cree.","h2":"En Maine, el manual del conductor dice que necesitas unos 10 a 12 segundos para rebasar con seguridad a 50 a 55 mph.","p":"Correcto. Unos 10 a 12 segundos."},"ref":{"doc":"ME","page":"7-6"}},{"id":"me-173","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, you should not start to pass on a two-lane road if you are within what distance of a hill or curve?","o":["One-third of a mile","100 feet","One block","Two miles"],"h1":"Treat a hill or curve like an oncoming car.","h2":"In Maine, the driver's manual says not to start a pass within one-third of a mile of a hill or curve.","p":"Right. One-third of a mile."},"es":{"q":"En Maine, no debes empezar a rebasar en una carretera de dos carriles si estás a menos de qué distancia de una colina o curva?","o":["Un tercio de milla","100 pies","Una cuadra","Dos millas"],"h1":"Trata una colina o curva como si fuera un auto que viene de frente.","h2":"En Maine, el manual del conductor dice que no empieces a rebasar a menos de un tercio de milla de una colina o curva.","p":"Correcto. Un tercio de milla."},"ref":{"doc":"ME","page":"7-7"}},{"id":"me-174","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, a school bus with flashing red lights is stopped in a school parking lot. What must you do?","o":["Pass slowly on the left","Stop and wait; passing it there is illegal","Honk and go around","Rules do not apply in parking lots"],"h1":"Maine's school bus rule also covers school property and parking areas.","h2":"In Maine, it is illegal to pass a stopped school bus with flashing red lights on school property, on any undivided highway, or in a parking area.","p":"Correct. You must stop, even in a parking area."},"es":{"q":"En Maine, un autobús escolar con luces rojas intermitentes está detenido en el estacionamiento de una escuela. ¿Qué debes hacer?","o":["Rebasar despacio por la izquierda","Detenerte y esperar; rebasarlo ahí es ilegal","Tocar la bocina y rodearlo","Las reglas no aplican en estacionamientos"],"h1":"La regla de Maine también cubre terrenos escolares y estacionamientos.","h2":"En Maine, es ilegal rebasar un autobús escolar detenido con luces rojas intermitentes en terrenos escolares, en cualquier carretera no dividida o en un estacionamiento.","p":"Correcto. Debes detenerte, aun en un estacionamiento."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-175","scope":"ME","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Maine, you are stopped for a school bus with red lights flashing. When may you go?","o":["After counting to ten","When the children reach the sidewalk","When the bus starts moving or the bus driver signals you","After honking once"],"h1":"The bus or its driver tells you.","h2":"In Maine, after stopping for a school bus with flashing red lights, you may not go until the bus moves again or the bus driver signals you to go.","p":"Right. When the bus moves or the driver signals."},"es":{"q":"En Maine, estás detenido por un autobús escolar con luces rojas intermitentes. ¿Cuándo puedes seguir?","o":["Después de contar hasta diez","Cuando los niños lleguen a la acera","Cuando el autobús empiece a moverse o el conductor del autobús te haga señal","Después de tocar la bocina una vez"],"h1":"Te lo indica el autobús o su conductor.","h2":"En Maine, después de detenerte por un autobús escolar con luces rojas intermitentes, no puedes seguir hasta que el autobús se mueva o su conductor te haga señal.","p":"Correcto. Cuando el autobús se mueva o el conductor te haga señal."},"ref":{"doc":"ME","page":"7-8"}},{"id":"me-176","scope":"ME","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Maine, a school bus with red lights flashing is stopped on the other side of a highway with a solid divider. What must you do?","o":["Stop until the lights go off","Stop and wait for a signal","Back up","You do not have to stop"],"h1":"A solid divider separates you from the bus.","h2":"In Maine, if a solid divider separates your side of the road from a stopped school bus, you do not have to stop.","p":"Correct. You do not have to stop."},"es":{"q":"En Maine, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera con un divisor sólido. ¿Qué debes hacer?","o":["Detenerte hasta que se apaguen las luces","Detenerte y esperar una señal","Ir en reversa","No tienes que detenerte"],"h1":"Un divisor sólido te separa del autobús.","h2":"En Maine, si un divisor sólido separa tu lado de la carretera de un autobús escolar detenido, no tienes que detenerte.","p":"Correcto. No tienes que detenerte."},"ref":{"doc":"ME","page":"7-9"}},{"id":"me-177","scope":"ME","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Maine, when you parallel park, at least how much space should you leave between your car and the cars in front and behind?","o":["Two feet","Six inches","Ten feet","One foot"],"h1":"It is about the length of two rulers laid end to end.","h2":"In Maine, the driver's manual says to leave at least two feet between your car and the vehicles parked in front and behind.","p":"Right. At least two feet."},"es":{"q":"En Maine, cuando te estacionas en paralelo, ¿cuánto espacio mínimo debes dejar entre tu auto y los autos de adelante y de atrás?","o":["Dos pies","Seis pulgadas","Diez pies","Un pie"],"h1":"Es más o menos el largo de dos reglas puestas una tras otra.","h2":"En Maine, el manual del conductor dice que dejes al menos dos pies entre tu auto y los vehículos estacionados adelante y atrás.","p":"Correcto. Al menos dos pies."},"ref":{"doc":"ME","page":"7-9"}},{"id":"me-178","scope":"ME","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Maine, how close to a fire hydrant may you park?","o":["5 feet","No closer than 10 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is shorter than the distance for a crosswalk.","h2":"In Maine, you may not park within 10 feet of a fire hydrant.","p":"Correct. No closer than 10 feet."},"es":{"q":"En Maine, ¿qué tan cerca de un hidrante puedes estacionarte?","o":["A 5 pies","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es menos que la distancia de un cruce peatonal.","h2":"En Maine, no puedes estacionarte a menos de 10 pies de un hidrante.","p":"Correcto. No más cerca de 10 pies."},"ref":{"doc":"ME","page":"7-10"}},{"id":"me-179","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, how close to a crosswalk may you park?","o":["5 feet","10 feet","No closer than 15 feet","No closer than 50 feet"],"h1":"It is the same as for a fire station driveway.","h2":"In Maine, you may not park within 15 feet of a crosswalk or within 15 feet of a fire station driveway.","p":"Right. No closer than 15 feet."},"es":{"q":"En Maine, ¿qué tan cerca de un cruce peatonal puedes estacionarte?","o":["5 pies","10 pies","No más cerca de 15 pies","No más cerca de 50 pies"],"h1":"Es lo mismo que para la entrada de una estación de bomberos.","h2":"En Maine, no puedes estacionarte a menos de 15 pies de un cruce peatonal ni a menos de 15 pies de la entrada de una estación de bomberos.","p":"Correcto. No más cerca de 15 pies."},"ref":{"doc":"ME","page":"7-10"}},{"id":"me-180","scope":"ME","cat":"licensing","sign":null,"c":3,"en":{"q":"In Maine, what is the fine for parking in a disability parking space without the special permit or plates?","o":["$10","$25","$1,000","$100"],"h1":"Misusing disability plates or placards has the same fine.","h2":"In Maine, parking in a space reserved for persons with disabilities without the permit or plates brings a $100 fine.","p":"Correct. $100."},"es":{"q":"En Maine, ¿cuál es la multa por estacionarte en un espacio para personas con discapacidad sin el permiso o las placas especiales?","o":["$10","$25","$1,000","$100"],"h1":"El mal uso de placas o tarjetas para discapacidad tiene la misma multa.","h2":"En Maine, estacionarte en un espacio reservado para personas con discapacidad sin el permiso o las placas trae una multa de $100.","p":"Correcto. $100."},"ref":{"doc":"ME","page":"7-10"}},{"id":"me-181","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, you see a tow truck stopped on the shoulder with its lights flashing. What must you do?","o":["Pass in a lane not next to it if possible, or slow down to a careful speed","Keep your speed and lane","Stop behind it until it leaves","Honk to warn the driver"],"h1":"Maine's move-over law covers more than police cars.","h2":"In Maine, when passing a stopped emergency vehicle or public service vehicle such as a tow truck using its lights, you must use a lane not next to it if possible, or else pass at a careful, safe speed.","p":"Right. Move over a lane if you can, or slow down."},"es":{"q":"En Maine, ves una grúa detenida en el acotamiento con sus luces intermitentes. ¿Qué debes hacer?","o":["Pasar por un carril que no esté junto a ella si es posible, o bajar a una velocidad prudente","Mantener tu velocidad y tu carril","Detenerte detrás de ella hasta que se vaya","Tocar la bocina para avisar al conductor"],"h1":"La ley de Maine para cambiarse de carril cubre más que patrullas.","h2":"En Maine, al pasar un vehículo de emergencia o de servicio público detenido, como una grúa con sus luces encendidas, debes usar un carril que no esté junto a él si es posible, o pasar a una velocidad prudente y segura.","p":"Correcto. Cámbiate de carril si puedes, o baja la velocidad."},"ref":{"doc":"ME","page":null}},{"id":"me-182","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, what is the minimum fine for breaking the move-over law at a stopped emergency vehicle?","o":["$25","$275","$50","$75"],"h1":"It is a few hundred dollars.","h2":"In Maine, breaking the move-over law for a stopped emergency or public service vehicle is a traffic infraction with a minimum fine of $275.","p":"Correct. At least $275."},"es":{"q":"En Maine, ¿cuál es la multa mínima por no cumplir la ley de cambiarse de carril ante un vehículo de emergencia detenido?","o":["$25","$275","$50","$75"],"h1":"Son unos cientos de dólares.","h2":"En Maine, no cumplir la ley de cambiarse de carril ante un vehículo de emergencia o de servicio público detenido es una infracción con multa mínima de $275.","p":"Correcto. Al menos $275."},"ref":{"doc":"ME","page":null}},{"id":"me-183","scope":"ME","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Maine, the 15 mph school zone limit applies during school opening and closing hours. What time window does that cover?","o":["Only the hour school starts","From 6 a.m. to 6 p.m.","From half an hour before school starts to half an hour after it ends","All day, every day of the year"],"h1":"It adds 30 minutes on each side of the school day.","h2":"In Maine, school opening and closing hours run from half an hour before the school day starts to half an hour after it ends.","p":"Right. Half an hour before start to half an hour after the end."},"es":{"q":"En Maine, el límite de 15 mph en zona escolar aplica en las horas de entrada y salida. ¿Qué horario cubre eso?","o":["Solo la hora en que empiezan las clases","De 6 a.m. a 6 p.m.","Desde media hora antes de que empiecen las clases hasta media hora después de que terminen","Todo el día, todos los días del año"],"h1":"Suma 30 minutos antes y después de la jornada escolar.","h2":"En Maine, las horas de entrada y salida van desde media hora antes de que empiece la jornada escolar hasta media hora después de que termine.","p":"Correcto. Media hora antes del inicio hasta media hora después del final."},"ref":{"doc":"ME","page":"8-3"}},{"id":"me-184","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, what happens to the fine for speeding in a school zone?","o":["It is cut in half","It stays the same","It is replaced by a warning","It is twice the usual fine"],"h1":"Maine wants drivers extra careful near schools.","h2":"In Maine, the fine for going over the posted speed limit in a school zone is twice the usual fine.","p":"Correct. The fine is doubled."},"es":{"q":"En Maine, ¿qué pasa con la multa por exceso de velocidad en una zona escolar?","o":["Se reduce a la mitad","Queda igual","Se cambia por una advertencia","Es el doble de la multa normal"],"h1":"Maine quiere que los conductores tengan más cuidado cerca de las escuelas.","h2":"En Maine, la multa por pasar el límite de velocidad en una zona escolar es el doble de la multa normal.","p":"Correcto. La multa se duplica."},"ref":{"doc":"ME","page":"8-8"}},{"id":"me-185","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the road is wet. By about how much does the driver's manual say to slow down?","o":["5 to 10 mph","1 to 2 mph","To half speed","To a crawl"],"h1":"Packed snow needs half speed; wet roads need less of a drop.","h2":"In Maine, the driver's manual says to slow down 5 to 10 mph on a wet road, to half speed on packed snow, and to a crawl on ice.","p":"Right. Slow down 5 to 10 mph."},"es":{"q":"En Maine, la carretera está mojada. ¿Cuánto dice el manual del conductor que debes bajar la velocidad?","o":["De 5 a 10 mph","De 1 a 2 mph","A la mitad de la velocidad","A paso muy lento"],"h1":"La nieve compacta pide la mitad de la velocidad; lo mojado pide bajar menos.","h2":"En Maine, el manual del conductor dice que bajes de 5 a 10 mph en carretera mojada, a la mitad de la velocidad con nieve compacta y a paso muy lento con hielo.","p":"Correcto. Baja de 5 a 10 mph."},"ref":{"doc":"ME","page":"8-6"}},{"id":"me-186","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, the driver's manual says your headlights let you see clearly only about how far ahead?","o":["50 feet","250 feet","1,000 feet","A mile"],"h1":"Above about 50 mph on a dark road you are driving blind.","h2":"In Maine, the driver's manual says headlights let you see clearly only about 250 feet ahead, so going faster than about 50 mph on a dark road is driving blind.","p":"Correct. About 250 feet."},"es":{"q":"En Maine, según el manual del conductor, ¿hasta qué distancia te dejan ver claramente los faros?","o":["50 pies","250 pies","1,000 pies","Una milla"],"h1":"A más de unas 50 mph en un camino oscuro manejas a ciegas.","h2":"En Maine, el manual del conductor dice que los faros te dejan ver claramente solo unos 250 pies adelante, así que ir a más de unas 50 mph en un camino oscuro es manejar a ciegas.","p":"Correcto. Unos 250 pies."},"ref":{"doc":"ME","page":"8-8"}},{"id":"me-187","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, you are following a tank truck carrying flammable liquid toward a railroad crossing. What should you expect?","o":["It will speed up over the tracks","It will change lanes","It will stop at the crossing","It will turn on its high beams"],"h1":"School buses do the same thing.","h2":"In Maine, school buses and tank trucks carrying flammable liquids must stop at all railroad crossings, so slow down early and leave extra room.","p":"Right. Expect it to stop at the crossing."},"es":{"q":"En Maine, vas detrás de un camión cisterna con líquido inflamable que se acerca a un cruce de tren. ¿Qué debes esperar?","o":["Que acelere sobre las vías","Que cambie de carril","Que se detenga en el cruce","Que prenda las luces altas"],"h1":"Los autobuses escolares hacen lo mismo.","h2":"En Maine, los autobuses escolares y los camiones cisterna con líquidos inflamables deben detenerse en todos los cruces de tren, así que baja la velocidad antes y deja más espacio.","p":"Correcto. Espera que se detenga en el cruce."},"ref":{"doc":"ME","page":"8-12"}},{"id":"me-188","scope":"ME","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Maine, how big a gap in traffic does the driver's manual say you need to merge or change lanes safely?","o":["One second","Two seconds","Ten seconds","Four seconds"],"h1":"It matches Maine's following distance.","h2":"In Maine, the driver's manual says you need a gap of four seconds to merge or change lanes safely.","p":"Correct. Four seconds."},"es":{"q":"En Maine, ¿qué tan grande debe ser el espacio en el tráfico para incorporarte o cambiar de carril con seguridad, según el manual?","o":["Un segundo","Dos segundos","Diez segundos","Cuatro segundos"],"h1":"Es igual a la distancia de seguimiento de Maine.","h2":"En Maine, el manual del conductor dice que necesitas un espacio de cuatro segundos para incorporarte o cambiar de carril con seguridad.","p":"Correcto. Cuatro segundos."},"ref":{"doc":"ME","page":"8-15"}},{"id":"me-189","scope":"ME","cat":"signals","sign":null,"c":0,"en":{"q":"In Maine, during which hours must your headlights be on?","o":["From sunset to sunrise","Only after 10 p.m.","Only on highways","Only when it is raining"],"h1":"Think of the whole night.","h2":"In Maine, the law requires headlights any time from sunset to sunrise.","p":"Right. From sunset to sunrise."},"es":{"q":"En Maine, ¿en qué horas deben estar encendidos tus faros?","o":["Desde la puesta hasta la salida del sol","Solo después de las 10 p.m.","Solo en las autopistas","Solo cuando llueve"],"h1":"Piensa en toda la noche.","h2":"En Maine, la ley exige los faros encendidos en cualquier momento desde la puesta hasta la salida del sol.","p":"Correcto. Desde la puesta hasta la salida del sol."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-190","scope":"ME","cat":"signals","sign":null,"c":1,"en":{"q":"In Maine, you are using high beams and an oncoming car approaches. Within what distance must you dim them?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"When following a car, the distance is 300 feet.","h2":"In Maine, you must dim to low beams within 500 feet of an oncoming vehicle and within 300 feet when following a vehicle.","p":"Correct. Within 500 feet of oncoming traffic."},"es":{"q":"En Maine, llevas las luces altas y se acerca un auto de frente. ¿A qué distancia debes bajarlas?","o":["100 pies","500 pies","50 pies","2,000 pies"],"h1":"Cuando vas detrás de un auto, la distancia es de 300 pies.","h2":"En Maine, debes cambiar a luces bajas a 500 pies de un vehículo que viene de frente y a 300 pies cuando vas detrás de otro vehículo.","p":"Correcto. A 500 pies de un vehículo que viene de frente."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-191","scope":"ME","cat":"signals","sign":null,"c":2,"en":{"q":"In Maine, you are following another car at night with your high beams on. Within what distance must you switch to low beams?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"It is shorter than the 500 feet for oncoming cars.","h2":"In Maine, you must dim your headlights when following a vehicle within 300 feet.","p":"Right. Within 300 feet."},"es":{"q":"En Maine, vas detrás de otro auto de noche con las luces altas. ¿A qué distancia debes cambiar a luces bajas?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Es menos que los 500 pies para autos que vienen de frente.","h2":"En Maine, debes bajar las luces cuando vas detrás de un vehículo a menos de 300 pies.","p":"Correcto. A menos de 300 pies."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-192","scope":"ME","cat":"signals","sign":null,"c":3,"en":{"q":"In Maine, when must a motorcyclist have the headlight on?","o":["Only at night","Only in rain or fog","Only on highways","Always, whenever riding on Maine roads"],"h1":"There is no time of day when it may be off.","h2":"In Maine, motorcyclists must always have their headlights on when riding on Maine roads.","p":"Correct. Always."},"es":{"q":"En Maine, ¿cuándo debe un motociclista llevar el faro encendido?","o":["Solo de noche","Solo con lluvia o niebla","Solo en las autopistas","Siempre que circule por las carreteras de Maine"],"h1":"No hay hora del día en que pueda ir apagado.","h2":"En Maine, los motociclistas deben llevar el faro encendido siempre que circulen por las carreteras de Maine.","p":"Correcto. Siempre."},"ref":{"doc":"ME","page":"8-16"}},{"id":"me-193","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, may a driver read a book or magazine while driving?","o":["No, reading printed material while driving is illegal, except a map or directions","Yes, at low speeds","Yes, when stopped at a red light","Yes, on the highway only"],"h1":"There is an exception for finding your way.","h2":"In Maine, it is illegal to read printed material while driving, except a map or written directions to a place.","p":"Right. It is illegal, except maps or directions."},"es":{"q":"En Maine, ¿puede un conductor leer un libro o una revista mientras maneja?","o":["No, leer material impreso mientras manejas es ilegal, salvo un mapa o indicaciones","Sí, a baja velocidad","Sí, cuando está detenido en un semáforo en rojo","Sí, solo en la autopista"],"h1":"Hay una excepción para ubicarte.","h2":"En Maine, es ilegal leer material impreso mientras manejas, salvo un mapa o indicaciones escritas para llegar a un lugar.","p":"Correcto. Es ilegal, salvo mapas o indicaciones."},"ref":{"doc":"ME","page":"9-2"}},{"id":"me-194","scope":"ME","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Maine, you hit and hurt a dog with your car. What must you do?","o":["Drive on; animals do not count","Take reasonable steps to notify the owner, or the police or animal control","Call your insurance only","Wait 24 hours and then report it"],"h1":"The same rule covers cats and livestock.","h2":"In Maine, a driver who injures or kills a dog, cat or livestock must take reasonable steps to notify the owner, or local police or animal control if the owner cannot be found.","p":"Correct. Notify the owner, or the police or animal control."},"es":{"q":"En Maine, atropellas y lastimas a un perro con tu auto. ¿Qué debes hacer?","o":["Seguir; los animales no cuentan","Hacer lo razonable para avisar al dueño, o a la policía o al control de animales","Solo llamar a tu seguro","Esperar 24 horas y luego reportarlo"],"h1":"La misma regla cubre gatos y ganado.","h2":"En Maine, el conductor que lastima o mata a un perro, gato o animal de granja debe hacer lo razonable para avisar al dueño, o a la policía local o al control de animales si no encuentra al dueño.","p":"Correcto. Avisa al dueño, o a la policía o al control de animales."},"ref":{"doc":"ME","page":"9-3"}},{"id":"me-195","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, your car goes into water. The driver's manual says a car with windows and doors closed may float for about how long?","o":["About 10 seconds","About 1 hour","It sinks at once","About 3 to 10 minutes"],"h1":"There is a short time to escape through a window.","h2":"In Maine, the driver's manual says a car with windows and doors closed may float for 3 to 10 minutes, and the best way out is through a window.","p":"Correct. About 3 to 10 minutes."},"es":{"q":"En Maine, tu auto cae al agua. Según el manual del conductor, ¿cuánto tiempo puede flotar un auto con ventanas y puertas cerradas?","o":["Unos 10 segundos","Como 1 hora","Se hunde de inmediato","Unos 3 a 10 minutos"],"h1":"Hay poco tiempo para salir por una ventana.","h2":"En Maine, el manual del conductor dice que un auto con ventanas y puertas cerradas puede flotar de 3 a 10 minutos, y la mejor salida es por una ventana.","p":"Correcto. Unos 3 a 10 minutos."},"ref":{"doc":"ME","page":"9-7"}},{"id":"me-196","scope":"ME","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Maine, when may you drive in a bicycle lane?","o":["Only to enter or leave an alley or driveway","Whenever no bicyclist is in sight","To pass slow traffic","To park for a few minutes"],"h1":"It is a short crossing, not a trip along the lane.","h2":"In Maine, you may not stop, park or drive in a bicycle lane unless you are entering or leaving an alley or driveway.","p":"Right. Only to enter or leave an alley or driveway."},"es":{"q":"En Maine, ¿cuándo puedes manejar en un carril para bicicletas?","o":["Solo para entrar o salir de un callejón o una entrada de autos","Siempre que no veas ciclistas","Para rebasar el tráfico lento","Para estacionarte unos minutos"],"h1":"Es un cruce corto, no un recorrido por el carril.","h2":"En Maine, no puedes detenerte, estacionarte ni manejar en un carril para bicicletas salvo para entrar o salir de un callejón o una entrada de autos.","p":"Correcto. Solo para entrar o salir de un callejón o una entrada de autos."},"ref":{"doc":"ME","page":"10-2"}},{"id":"me-197","scope":"ME","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Maine, the driver's manual recommends the Dutch Reach when you open your car door. What is it?","o":["Opening the door with your left hand very fast","Opening the driver's door with your right hand so you turn to look behind","Honking before you open the door","Opening the door only halfway"],"h1":"Using the far hand makes your body twist toward the road.","h2":"In Maine, the driver's manual recommends the Dutch Reach: open the driver's door with your right hand so your body turns and you can see bicyclists coming from behind.","p":"Correct. Use your right hand so you turn and look back."},"es":{"q":"En Maine, el manual del conductor recomienda el método Dutch Reach al abrir la puerta del auto. ¿En qué consiste?","o":["Abrir la puerta con la mano izquierda muy rápido","Abrir la puerta del conductor con la mano derecha para girar y mirar hacia atrás","Tocar la bocina antes de abrir","Abrir la puerta solo hasta la mitad"],"h1":"Usar la mano más lejana hace que tu cuerpo gire hacia la calle.","h2":"En Maine, el manual del conductor recomienda el Dutch Reach: abrir la puerta del conductor con la mano derecha para que tu cuerpo gire y veas a los ciclistas que vienen por detrás.","p":"Correcto. Usa la mano derecha para girar y mirar atrás."},"ref":{"doc":"ME","page":"10-3"}},{"id":"me-198","scope":"ME","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Maine, bicycle riders under what age must wear a helmet on public ways?","o":["Under 12","Under 21","Under 16","Under 10"],"h1":"It is the age many teens start to drive.","h2":"In Maine, all bicycle riders and passengers under 16 years of age must wear helmets on public ways.","p":"Right. Under 16."},"es":{"q":"En Maine, ¿los ciclistas menores de qué edad deben usar casco en la vía pública?","o":["Menores de 12","Menores de 21","Menores de 16","Menores de 10"],"h1":"Es la edad en que muchos jóvenes empiezan a manejar.","h2":"En Maine, todos los ciclistas y pasajeros de bicicleta menores de 16 años deben usar casco en la vía pública.","p":"Correcto. Menores de 16."},"ref":{"doc":"ME","page":"10-4"}},{"id":"me-199","scope":"ME","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Maine, a bicycle ridden at night must have a white front light visible from at least how far?","o":["10 feet","50 feet","1 mile","200 feet"],"h1":"The rear reflector must be visible from the same distance.","h2":"In Maine, a bicycle at night needs a white front light visible from at least 200 feet and a red or amber rear light or reflector visible from 200 feet.","p":"Correct. At least 200 feet."},"es":{"q":"En Maine, una bicicleta de noche debe llevar una luz blanca delantera visible desde al menos qué distancia?","o":["10 pies","50 pies","1 milla","200 pies"],"h1":"El reflector de atrás debe verse desde la misma distancia.","h2":"En Maine, una bicicleta de noche necesita una luz blanca delantera visible desde al menos 200 pies y una luz o reflector trasero rojo o ámbar visible desde 200 pies.","p":"Correcto. Al menos 200 pies."},"ref":{"doc":"ME","page":"10-4"}},{"id":"me-200","scope":"ME","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Maine, the driver's manual says a loaded truck going 55 mph needs at least how far to stop?","o":["335 feet","100 feet","50 feet","3 miles"],"h1":"It is more than one and a half times what a car needs.","h2":"In Maine, the driver's manual says a loaded truck at 55 mph takes at least 335 feet to stop, so never cut in close in front of one.","p":"Right. At least 335 feet."},"es":{"q":"En Maine, según el manual del conductor, ¿cuánto necesita como mínimo un camión cargado a 55 mph para detenerse?","o":["335 pies","100 pies","50 pies","3 millas"],"h1":"Es más de una vez y media lo que necesita un auto.","h2":"En Maine, el manual del conductor dice que un camión cargado a 55 mph necesita al menos 335 pies para detenerse, así que nunca te metas muy cerca delante de él.","p":"Correcto. Al menos 335 pies."},"ref":{"doc":"ME","page":"10-7"}},{"id":"mi-001","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age to get a Level 1 Learner’s License?","o":["14 years old","14 years and 3 months","14 years and 9 months","15 years and 6 months"],"h1":"It is a few months before the 15th birthday.","h2":"You can get a Michigan Level 1 Learner’s License at 14 years and 9 months, after finishing the first part of driver education.","p":"Right. Level 1 starts at 14 years and 9 months."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para obtener la licencia de aprendiz de Nivel 1?","o":["14 años","14 años y 3 meses","14 años y 9 meses","15 años y 6 meses"],"h1":"Es unos meses antes de cumplir 15 años.","h2":"Usted puede obtener la licencia de aprendiz de Nivel 1 en Michigan a los 14 años y 9 meses, después de terminar la primera parte de la educación vial.","p":"Correcto. El Nivel 1 empieza a los 14 años y 9 meses."},"zh":{"q":"在 Michigan，最小几岁可以拿到 Level 1 学习驾照（Learner’s License）？","o":["14 岁","14 岁又 3 个月","14 岁又 9 个月","15 岁又 6 个月"],"h1":"是 15 岁生日前几个月。","h2":"你在 14 岁又 9 个月、完成驾驶教育的第一部分以后，就可以拿到 Michigan 的 Level 1 学习驾照。","p":"对。Level 1 从 14 岁又 9 个月开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lấy Giấy phép Học lái Cấp 1 (Level 1 Learner’s License) là bao nhiêu?","o":["14 tuổi","14 tuổi 3 tháng","14 tuổi 9 tháng","15 tuổi 6 tháng"],"h1":"Đó là vài tháng trước sinh nhật 15 tuổi.","h2":"Bạn có thể lấy Giấy phép Học lái Cấp 1 ở Michigan khi 14 tuổi 9 tháng, sau khi học xong phần đầu tiên của khóa học lái xe.","p":"Đúng. Cấp 1 bắt đầu khi 14 tuổi 9 tháng."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para makakuha ng Level 1 Learner’s License?","o":["14 taong gulang","14 taon at 3 buwan","14 taon at 9 na buwan","15 taon at 6 na buwan"],"h1":"Ilang buwan ito bago ang ika-15 na kaarawan.","h2":"Makakakuha ka ng Michigan Level 1 Learner’s License sa edad na 14 taon at 9 na buwan, pagkatapos tapusin ang unang bahagi ng driver education.","p":"Tama. Nagsisimula ang Level 1 sa 14 taon at 9 na buwan."},"ar":{"q":"في Michigan، ما أصغر عمر للحصول على رخصة التعلّم من المستوى 1 (Level 1 Learner’s License)؟","o":["14 سنة","14 سنة و3 أشهر","14 سنة و9 أشهر","15 سنة و6 أشهر"],"h1":"هو قبل عيد الميلاد الخامس عشر ببضعة أشهر.","h2":"يمكنك الحصول على رخصة التعلّم من المستوى 1 في Michigan في عمر 14 سنة و9 أشهر، بعد إنهاء الجزء الأول من تعليم القيادة.","p":"صحيح. يبدأ المستوى 1 في عمر 14 سنة و9 أشهر."},"ref":{"doc":"MI","page":4}},{"id":"mi-002","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what must a teen finish before getting a Level 1 Learner’s License?","o":["Segment 1 of an approved driver education course","A road skills test","50 hours of supervised driving","Six months of a part-time job"],"h1":"Michigan splits driver education into parts; this is the first one.","h2":"A teen must finish Segment 1 of an approved driver education course before getting a Level 1 license, so they learn the basics in class first.","p":"Right. Segment 1 of driver education comes first."},"es":{"q":"En Michigan, ¿qué debe terminar un joven antes de obtener la licencia de aprendiz de Nivel 1?","o":["El Segmento 1 de un curso aprobado de educación vial","Un examen práctico de manejo","50 horas de manejo supervisado","Seis meses de un trabajo de medio tiempo"],"h1":"Michigan divide la educación vial en partes; esta es la primera.","h2":"Un joven debe terminar el Segmento 1 de un curso aprobado de educación vial antes de obtener la licencia de Nivel 1, para aprender lo básico en clase primero.","p":"Correcto. Primero va el Segmento 1 de la educación vial."},"zh":{"q":"在 Michigan，青少年拿 Level 1 学习驾照前必须完成什么？","o":["批准的驾驶教育课程的 Segment 1","路考","50 小时有人监督的驾驶","六个月的兼职工作"],"h1":"Michigan 把驾驶教育分成几部分；这是第一部分。","h2":"青少年拿 Level 1 驾照前，必须完成批准的驾驶教育课程的 Segment 1，这样他们先在课堂上学会基础知识。","p":"对。先完成驾驶教育的 Segment 1。"},"vi":{"q":"Ở Michigan, thiếu niên phải học xong điều gì trước khi lấy Giấy phép Học lái Cấp 1 (Level 1 Learner’s License)?","o":["Phần 1 (Segment 1) của một khóa học lái xe được chấp thuận","Một bài thi kỹ năng lái trên đường","50 giờ lái xe có người giám sát","Sáu tháng làm việc bán thời gian"],"h1":"Michigan chia khóa học lái xe thành nhiều phần; đây là phần đầu tiên.","h2":"Thiếu niên phải học xong Phần 1 (Segment 1) của một khóa học lái xe được chấp thuận trước khi lấy giấy phép Cấp 1, để học điều cơ bản trong lớp trước.","p":"Đúng. Phần 1 của khóa học lái xe là bước đầu tiên."},"tl":{"q":"Sa Michigan, ano ang dapat tapusin ng isang teenager bago makakuha ng Level 1 Learner’s License?","o":["Segment 1 ng isang aprubadong kurso ng driver education","Isang pagsusulit sa kasanayan sa pagmamaneho sa kalsada","50 oras ng pagmamaneho na may bantay","Anim na buwan ng part-time na trabaho"],"h1":"Hinahati ng Michigan ang driver education sa mga bahagi; ito ang una.","h2":"Dapat tapusin ng teenager ang Segment 1 ng isang aprubadong kurso ng driver education bago makakuha ng Level 1 license, para matutunan muna ang mga batayan sa klase.","p":"Tama. Segment 1 ng driver education ang nauuna."},"ar":{"q":"في Michigan، ماذا يجب أن يُنهي المراهق قبل الحصول على رخصة التعلّم من المستوى 1 (Level 1 Learner’s License)؟","o":["الجزء 1 (Segment 1) من دورة تعليم قيادة معتمدة","اختبار مهارات القيادة على الطريق","50 ساعة من القيادة تحت الإشراف","ستة أشهر من عمل بدوام جزئي"],"h1":"تقسم Michigan تعليم القيادة إلى أجزاء؛ وهذا هو الجزء الأول.","h2":"يجب أن يُنهي المراهق الجزء 1 (Segment 1) من دورة تعليم قيادة معتمدة قبل الحصول على رخصة المستوى 1، حتى يتعلّم الأساسيات في الصف أولًا.","p":"صحيح. الجزء 1 من تعليم القيادة يأتي أولًا."},"ref":{"doc":"MI","page":4}},{"id":"mi-003","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, who may ride with a Level 1 driver as the supervisor?","o":["Any passenger age 16 or older","Only a certified driving instructor","Any licensed driver age 18 or older","A licensed parent or guardian, or a licensed adult 21 or older they approve"],"h1":"The supervisor must be family, or an older adult the family chose.","h2":"A Level 1 driver may drive only with a licensed parent or guardian, or with a licensed driver 21 or older whom the parent or guardian has approved.","p":"Right. A licensed parent, guardian, or approved adult 21 or older must ride along."},"es":{"q":"En Michigan, ¿quién puede ir como supervisor con un conductor de Nivel 1?","o":["Cualquier pasajero de 16 años o más","Solo un instructor de manejo certificado","Cualquier conductor con licencia de 18 años o más","Su padre, madre o tutor con licencia, o un adulto con licencia de 21 años o más aprobado por ellos"],"h1":"El supervisor debe ser de la familia, o un adulto mayor que la familia eligió.","h2":"Un conductor de Nivel 1 solo puede manejar con su padre, madre o tutor con licencia, o con un conductor con licencia de 21 años o más que ellos hayan aprobado.","p":"Correcto. Debe ir su padre, madre, tutor o un adulto aprobado de 21 años o más con licencia."},"zh":{"q":"在 Michigan，谁可以作为陪同的人坐 Level 1 司机的车？","o":["任何 16 岁或以上的乘客","只有有执照的驾驶教练","任何 18 岁或以上、有驾照的司机","有驾照的父母或监护人，或他们同意的 21 岁或以上、有驾照的成年人"],"h1":"陪同的人必须是家人，或家人选的年纪较大的成年人。","h2":"Level 1 司机只能和有驾照的父母或监护人一起开车，或者和父母或监护人同意的 21 岁或以上、有驾照的司机一起开车。","p":"对。必须有有驾照的父母、监护人，或同意的 21 岁或以上的成年人同车。"},"vi":{"q":"Ở Michigan, ai được ngồi cùng người lái Cấp 1 để giám sát?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Chỉ thầy dạy lái xe có chứng nhận","Bất kỳ người có bằng lái nào từ 18 tuổi trở lên","Cha mẹ hoặc người giám hộ có bằng lái, hoặc người lớn có bằng lái từ 21 tuổi trở lên được họ đồng ý"],"h1":"Người giám sát phải là người trong gia đình, hoặc một người lớn tuổi hơn mà gia đình đã chọn.","h2":"Người lái Cấp 1 chỉ được lái khi có cha mẹ hoặc người giám hộ có bằng lái, hoặc một người có bằng lái từ 21 tuổi trở lên được cha mẹ hoặc người giám hộ đồng ý.","p":"Đúng. Phải có cha mẹ, người giám hộ có bằng lái, hoặc người lớn từ 21 tuổi trở lên được đồng ý ngồi cùng."},"tl":{"q":"Sa Michigan, sino ang puwedeng sumakay kasama ng Level 1 driver bilang tagabantay (supervisor)?","o":["Sinumang pasahero na 16 taong gulang pataas","Isang sertipikadong instruktor sa pagmamaneho lamang","Sinumang may lisensya na 18 taong gulang pataas","Isang magulang o guardian na may lisensya, o isang adult na may lisensya na 21 pataas na pinayagan nila"],"h1":"Ang tagabantay ay dapat kapamilya, o isang mas matandang adult na pinili ng pamilya.","h2":"Ang Level 1 driver ay puwedeng magmaneho lamang kasama ang magulang o guardian na may lisensya, o isang driver na may lisensya na 21 taong gulang pataas na pinayagan ng magulang o guardian.","p":"Tama. Dapat kasama ang magulang, guardian na may lisensya, o aprubadong adult na 21 pataas."},"ar":{"q":"في Michigan، مَن يجوز له أن يركب مع سائق المستوى 1 كمشرف؟","o":["أي راكب عمره 16 سنة أو أكثر","مدرّب قيادة معتمد فقط","أي سائق مرخّص عمره 18 سنة أو أكثر","أحد الوالدين أو الوصي المرخّص، أو شخص بالغ مرخّص عمره 21 سنة أو أكثر يوافقون عليه"],"h1":"يجب أن يكون المشرف من العائلة، أو شخصًا بالغًا أكبر سنًا اختارته العائلة.","h2":"لا يجوز لسائق المستوى 1 أن يقود إلا مع أحد الوالدين أو الوصي المرخّص، أو مع سائق مرخّص عمره 21 سنة أو أكثر وافق عليه أحد الوالدين أو الوصي.","p":"صحيح. يجب أن يركب معه أحد الوالدين أو الوصي المرخّص، أو شخص بالغ موافَق عليه عمره 21 سنة أو أكثر."},"ref":{"doc":"MI","page":5}},{"id":"mi-004","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen hold a Level 1 license before moving to Level 2?","o":["Three months","Six months","One year","Two years"],"h1":"It is half of a year.","h2":"A teen must drive with a Level 1 license for at least six months before moving to Level 2, to gain supervised experience.","p":"Right. Level 1 lasts at least six months."},"es":{"q":"En Michigan, ¿cuánto tiempo debe tener un joven la licencia de Nivel 1 antes de pasar al Nivel 2?","o":["Tres meses","Seis meses","Un año","Dos años"],"h1":"Es la mitad de un año.","h2":"Un joven debe manejar con licencia de Nivel 1 por lo menos seis meses antes de pasar al Nivel 2, para ganar experiencia supervisada.","p":"Correcto. El Nivel 1 dura por lo menos seis meses."},"zh":{"q":"在 Michigan，青少年必须持有 Level 1 驾照多久，才能升到 Level 2？","o":["三个月","六个月","一年","两年"],"h1":"是半年。","h2":"青少年必须持 Level 1 驾照开车至少六个月，才能升到 Level 2，这样可以积累有人监督的经验。","p":"对。Level 1 至少要六个月。"},"vi":{"q":"Ở Michigan, thiếu niên phải giữ giấy phép Cấp 1 bao lâu trước khi lên Cấp 2?","o":["Ba tháng","Sáu tháng","Một năm","Hai năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên phải lái xe với giấy phép Cấp 1 ít nhất sáu tháng trước khi lên Cấp 2, để có kinh nghiệm khi có người giám sát.","p":"Đúng. Cấp 1 kéo dài ít nhất sáu tháng."},"tl":{"q":"Sa Michigan, gaano katagal dapat hawak ng teenager ang Level 1 license bago lumipat sa Level 2?","o":["Tatlong buwan","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Ito ay kalahati ng isang taon.","h2":"Dapat magmaneho ang teenager gamit ang Level 1 license nang hindi bababa sa anim na buwan bago lumipat sa Level 2, para magkaroon ng karanasan na may bantay.","p":"Tama. Tumatagal ang Level 1 nang hindi bababa sa anim na buwan."},"ar":{"q":"في Michigan، كم مدة يجب أن يحمل المراهق رخصة المستوى 1 قبل الانتقال إلى المستوى 2؟","o":["ثلاثة أشهر","ستة أشهر","سنة واحدة","سنتان"],"h1":"هي نصف سنة.","h2":"يجب أن يقود المراهق برخصة المستوى 1 لمدة ستة أشهر على الأقل قبل الانتقال إلى المستوى 2، ليكتسب خبرة تحت الإشراف.","p":"صحيح. يستمر المستوى 1 ستة أشهر على الأقل."},"ref":{"doc":"MI","page":5}},{"id":"mi-005","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many hours of supervised driving must a teen log before Level 2?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A teen must log at least 50 hours of supervised driving before a Level 2 license, to build steady skills with an adult beside them.","p":"Right. Michigan asks for at least 50 supervised hours."},"es":{"q":"En Michigan, ¿cuántas horas de manejo supervisado debe registrar un joven antes del Nivel 2?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven debe registrar por lo menos 50 horas de manejo supervisado antes de la licencia de Nivel 2, para ganar habilidad con un adulto a su lado.","p":"Correcto. Michigan pide por lo menos 50 horas supervisadas."},"zh":{"q":"在 Michigan，青少年升到 Level 2 前必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","60 小时","50 小时"],"h1":"是一百的一半。","h2":"青少年拿 Level 2 驾照前，必须记录至少 50 小时有人监督的驾驶，在成年人陪同下练好稳定的技能。","p":"对。Michigan 要求至少 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Michigan, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước Cấp 2?","o":["30 giờ","40 giờ","60 giờ","50 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên phải ghi lại ít nhất 50 giờ lái xe có người giám sát trước khi lấy giấy phép Cấp 2, để có kỹ năng vững vàng khi có người lớn ngồi bên cạnh.","p":"Đúng. Michigan yêu cầu ít nhất 50 giờ có người giám sát."},"tl":{"q":"Sa Michigan, ilang oras ng pagmamaneho na may bantay ang dapat itala ng teenager bago ang Level 2?","o":["30 oras","40 oras","60 oras","50 oras"],"h1":"Ito ay kalahati ng isandaan.","h2":"Dapat magtala ang teenager ng hindi bababa sa 50 oras ng pagmamaneho na may bantay bago ang Level 2 license, para maging matatag ang kasanayan habang may adult sa tabi.","p":"Tama. Humihingi ang Michigan ng hindi bababa sa 50 oras na may bantay."},"ar":{"q":"في Michigan، كم ساعة من القيادة تحت الإشراف يجب أن يسجّلها المراهق قبل المستوى 2؟","o":["30 ساعة","40 ساعة","60 ساعة","50 ساعة"],"h1":"هي نصف المئة.","h2":"يجب أن يسجّل المراهق 50 ساعة على الأقل من القيادة تحت الإشراف قبل رخصة المستوى 2، ليبني مهارات ثابتة وبجانبه شخص بالغ.","p":"صحيح. تطلب Michigan ما لا يقل عن 50 ساعة تحت الإشراف."},"ref":{"doc":"MI","page":5}},{"id":"mi-006","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many of the supervised hours before Level 2 must be at night?","o":["At least 10 hours","At least 2 hours","At least 20 hours","At least 25 hours"],"h1":"It is one fifth of the total hours.","h2":"At least 10 of the 50 supervised hours must be driven at night, because darkness makes driving harder.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Michigan, ¿cuántas de las horas supervisadas antes del Nivel 2 deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 20 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total de horas.","h2":"Por lo menos 10 de las 50 horas supervisadas deben ser de noche, porque la oscuridad hace más difícil manejar.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Michigan，升到 Level 2 前有人监督的驾驶时间中，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 20 小时","至少 25 小时"],"h1":"是总时间的五分之一。","h2":"50 小时有人监督的驾驶中，至少 10 小时必须在晚上开，因为天黑让开车更难。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Michigan, trong số giờ có người giám sát trước Cấp 2, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 20 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ít nhất 10 trong 50 giờ có người giám sát phải lái vào ban đêm, vì trời tối làm việc lái xe khó hơn.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Michigan, ilan sa mga oras na may bantay bago ang Level 2 ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 20 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuang oras.","h2":"Hindi bababa sa 10 sa 50 oras na may bantay ang dapat imaneho sa gabi, dahil mas mahirap magmaneho kapag madilim.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Michigan، كم من ساعات الإشراف قبل المستوى 2 يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل (2)","20 ساعة على الأقل","25 ساعة على الأقل"],"h1":"هي خُمس مجموع الساعات.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ50 ساعة تحت الإشراف قيادةً في الليل، لأن الظلام يجعل القيادة أصعب.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"MI","page":5}},{"id":"mi-007","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age for a Level 2 Intermediate License?","o":["15 years old","15 and a half years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You can get a Michigan Level 2 Intermediate License at 16, after finishing Segment 2 and passing a driving skills test.","p":"Right. Level 2 starts at age 16."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para la licencia intermedia de Nivel 2?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted puede obtener la licencia intermedia de Nivel 2 en Michigan a los 16 años, después de terminar el Segmento 2 y aprobar el examen práctico de manejo.","p":"Correcto. El Nivel 2 empieza a los 16 años."},"zh":{"q":"在 Michigan，最小几岁可以拿到 Level 2 中级驾照（Intermediate License）？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"很多州第一张驾照也是这个年龄。","h2":"你在 16 岁、完成 Segment 2 并通过驾驶技能考试以后，就可以拿到 Michigan 的 Level 2 中级驾照。","p":"对。Level 2 从 16 岁开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lấy Giấy phép Trung cấp Cấp 2 (Level 2 Intermediate License) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Đó là cùng tuổi mà nhiều tiểu bang dùng cho bằng lái đầu tiên.","h2":"Bạn có thể lấy Giấy phép Trung cấp Cấp 2 ở Michigan khi 16 tuổi, sau khi học xong Phần 2 (Segment 2) và đậu bài thi kỹ năng lái xe.","p":"Đúng. Cấp 2 bắt đầu khi 16 tuổi."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para sa Level 2 Intermediate License?","o":["15 taong gulang","15 at kalahating taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang parehong edad na ginagamit ng maraming estado para sa unang lisensya.","h2":"Makakakuha ka ng Michigan Level 2 Intermediate License sa edad na 16, pagkatapos tapusin ang Segment 2 at pumasa sa driving skills test.","p":"Tama. Nagsisimula ang Level 2 sa edad na 16."},"ar":{"q":"في Michigan، ما أصغر عمر للحصول على الرخصة المتوسطة من المستوى 2 (Level 2 Intermediate License)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"هو نفس العمر الذي تستخدمه ولايات كثيرة لأول رخصة.","h2":"يمكنك الحصول على الرخصة المتوسطة من المستوى 2 في Michigan في عمر 16 سنة، بعد إنهاء الجزء 2 (Segment 2) والنجاح في اختبار مهارات القيادة.","p":"صحيح. يبدأ المستوى 2 في عمر 16 سنة."},"ref":{"doc":"MI","page":5}},{"id":"mi-008","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long must a teen go with no tickets, suspensions or at-fault crashes right before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about three months.","h2":"A teen needs a clean record for the 90 days just before applying for Level 2, showing they can drive safely.","p":"Right. You need 90 days with a clean record."},"es":{"q":"En Michigan, ¿cuánto tiempo debe pasar un joven sin multas, suspensiones ni choques de los que sea culpable justo antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos tres meses.","h2":"Un joven necesita un récord limpio durante los 90 días justo antes de solicitar el Nivel 2, para mostrar que maneja con seguridad.","p":"Correcto. Necesita 90 días con récord limpio."},"zh":{"q":"在 Michigan，申请 Level 2 之前，青少年必须连续多久没有罚单、没有被暂停驾照、也没有自己有责任的车祸？","o":["30 天","90 天","180 天","一年"],"h1":"大约三个月。","h2":"青少年在申请 Level 2 之前的 90 天里必须记录干净，这表示他们能安全开车。","p":"对。你需要 90 天的干净记录。"},"vi":{"q":"Ở Michigan, ngay trước khi nộp đơn lên Cấp 2, thiếu niên phải không có vé phạt, không bị treo bằng và không gây tai nạn trong bao lâu?","o":["30 ngày","90 ngày","180 ngày","Một năm"],"h1":"Đó là khoảng ba tháng.","h2":"Thiếu niên cần có hồ sơ sạch trong 90 ngày ngay trước khi nộp đơn lên Cấp 2, để cho thấy họ có thể lái xe an toàn.","p":"Đúng. Bạn cần 90 ngày với hồ sơ sạch."},"tl":{"q":"Sa Michigan, gaano katagal dapat walang tiket, suspensyon o banggaan na kasalanan niya ang teenager bago mismo mag-apply para sa Level 2?","o":["30 araw","90 araw","180 araw","Isang taon"],"h1":"Ito ay mga tatlong buwan.","h2":"Kailangan ng teenager ng malinis na record sa 90 araw bago mismo mag-apply para sa Level 2, para ipakita na kaya niyang magmaneho nang ligtas.","p":"Tama. Kailangan mo ng 90 araw na malinis na record."},"ar":{"q":"في Michigan، كم مدة يجب أن يبقى المراهق بلا مخالفات ولا تعليق للرخصة ولا حوادث هو المخطئ فيها، مباشرةً قبل التقدّم للمستوى 2؟","o":["30 يومًا","90 يومًا","180 يومًا","سنة واحدة"],"h1":"هي نحو ثلاثة أشهر.","h2":"يحتاج المراهق إلى سجلّ نظيف خلال الـ90 يومًا التي تسبق التقدّم للمستوى 2 مباشرةً، ليُظهر أنه يستطيع القيادة بأمان.","p":"صحيح. تحتاج إلى 90 يومًا بسجلّ نظيف."},"ref":{"doc":"MI","page":5}},{"id":"mi-009","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, during which hours may a Level 2 driver not drive without an adult, unless an exception applies?","o":["10 p.m. to 5 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m."],"h1":"It starts two hours before midnight.","h2":"A Level 2 driver may not drive between 10 p.m. and 5 a.m. unless going to or from work or an approved activity, or with a parent, guardian or approved adult 21 or older.","p":"Right. Level 2 drivers stay off the road from 10 p.m. to 5 a.m."},"es":{"q":"En Michigan, ¿en qué horario no puede manejar un conductor de Nivel 2 sin un adulto, salvo una excepción?","o":["De 10 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Un conductor de Nivel 2 no puede manejar entre las 10 p.m. y las 5 a.m., salvo que vaya o vuelva del trabajo o de una actividad autorizada, o con su padre, madre, tutor o un adulto aprobado de 21 años o más.","p":"Correcto. Los conductores de Nivel 2 no manejan de 10 p.m. a 5 a.m."},"zh":{"q":"在 Michigan，除非有例外情况，Level 2 司机在哪段时间不能在没有成年人陪同时开车？","o":["晚上 10 点到早上 5 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 6 点"],"h1":"它从午夜前两个小时开始。","h2":"Level 2 司机在晚上 10 点到早上 5 点之间不能开车，除非是去上班或下班、去或离开批准的活动，或者有父母、监护人或同意的 21 岁或以上的成年人陪同。","p":"对。Level 2 司机在晚上 10 点到早上 5 点不上路。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 không được lái xe mà không có người lớn trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["10 giờ tối đến 5 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng"],"h1":"Nó bắt đầu hai giờ trước nửa đêm.","h2":"Người lái Cấp 2 không được lái từ 10 giờ tối đến 5 giờ sáng, trừ khi đi làm hoặc đi làm về, đi đến hoặc về từ một hoạt động được chấp thuận, hoặc đi cùng cha mẹ, người giám hộ hoặc người lớn từ 21 tuổi trở lên được đồng ý.","p":"Đúng. Người lái Cấp 2 không lái xe từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Michigan, sa anong mga oras hindi puwedeng magmaneho ang Level 2 driver nang walang kasamang adult, maliban kung may exception?","o":["10 p.m. hanggang 5 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito dalawang oras bago maghatinggabi.","h2":"Hindi puwedeng magmaneho ang Level 2 driver mula 10 p.m. hanggang 5 a.m., maliban kung papunta o pauwi mula sa trabaho o sa aprubadong aktibidad, o kasama ang magulang, guardian o aprubadong adult na 21 pataas.","p":"Tama. Wala sa kalsada ang Level 2 drivers mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Michigan، في أي ساعات لا يجوز لسائق المستوى 2 أن يقود بدون شخص بالغ، إلا في حالة استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعتين.","h2":"لا يجوز لسائق المستوى 2 أن يقود بين 10 مساءً و5 صباحًا، إلا إذا كان ذاهبًا إلى العمل أو عائدًا منه أو من نشاط معتمد، أو كان معه أحد الوالدين أو الوصي أو شخص بالغ موافَق عليه عمره 21 سنة أو أكثر.","p":"صحيح. سائقو المستوى 2 لا يقودون من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"MI","page":5}},{"id":"mi-010","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, which trip may a Level 2 driver make alone during the night limit hours?","o":["Driving friends home from a party","Driving to a late restaurant","Driving to or from a job","Driving around to practice"],"h1":"The exception is about earning a living.","h2":"A Level 2 driver may drive during the night limit hours when going to or from work, or while working.","p":"Right. Driving to or from work is an exception."},"es":{"q":"En Michigan, ¿qué viaje puede hacer solo un conductor de Nivel 2 en las horas de límite nocturno?","o":["Llevar a amigos a casa después de una fiesta","Ir a un restaurante tarde","Ir o volver del trabajo","Manejar por ahí para practicar"],"h1":"La excepción tiene que ver con ganarse la vida.","h2":"Un conductor de Nivel 2 puede manejar en las horas de límite nocturno cuando va o vuelve del trabajo, o mientras trabaja.","p":"Correcto. Ir o volver del trabajo es una excepción."},"zh":{"q":"在 Michigan，在夜间限制的时间里，Level 2 司机可以单独开车去做哪件事？","o":["送朋友从派对回家","开车去很晚才关门的餐厅","开车去上班或下班","开车到处转来练习"],"h1":"这个例外和赚钱养活自己有关。","h2":"Level 2 司机在夜间限制的时间里，去上班或下班、或者在工作时，可以开车。","p":"对。上班或下班是一个例外。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 được lái một mình chuyến đi nào trong giờ giới hạn ban đêm?","o":["Chở bạn bè về nhà sau bữa tiệc","Lái đến một nhà hàng mở khuya","Lái xe đi làm hoặc đi làm về","Lái vòng quanh để tập"],"h1":"Trường hợp ngoại lệ là về việc kiếm sống.","h2":"Người lái Cấp 2 được lái trong giờ giới hạn ban đêm khi đi làm, đi làm về, hoặc khi đang làm việc.","p":"Đúng. Lái xe đi làm hoặc đi làm về là trường hợp ngoại lệ."},"tl":{"q":"Sa Michigan, anong biyahe ang puwedeng gawin nang mag-isa ng Level 2 driver sa mga oras ng limitasyon sa gabi?","o":["Paghatid sa mga kaibigan pauwi mula sa party","Pagmamaneho papunta sa restawran na bukas hanggang gabi","Pagmamaneho papunta o pauwi mula sa trabaho","Pag-ikot-ikot para magpraktis"],"h1":"Ang exception ay tungkol sa paghahanapbuhay.","h2":"Puwedeng magmaneho ang Level 2 driver sa mga oras ng limitasyon sa gabi kapag papunta o pauwi mula sa trabaho, o habang nagtatrabaho.","p":"Tama. Ang pagmamaneho papunta o pauwi mula sa trabaho ay exception."},"ar":{"q":"في Michigan، أي رحلة يجوز لسائق المستوى 2 أن يقوم بها وحده خلال ساعات القيد الليلي؟","o":["توصيل الأصدقاء إلى البيت بعد حفلة","القيادة إلى مطعم يفتح حتى وقت متأخر","القيادة إلى العمل أو العودة منه","التجوّل بالسيارة للتدرّب"],"h1":"الاستثناء يتعلّق بكسب الرزق.","h2":"يجوز لسائق المستوى 2 أن يقود خلال ساعات القيد الليلي عند الذهاب إلى العمل أو العودة منه، أو أثناء العمل.","p":"صحيح. القيادة إلى العمل أو العودة منه استثناء."},"ref":{"doc":"MI","page":5}},{"id":"mi-011","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many passengers under 21 may a Level 2 driver carry, not counting family?","o":["None at all","Two","Three","One"],"h1":"More than zero, but fewer than two.","h2":"A Level 2 driver may carry no more than one passenger under 21, except for members of their own family, because young passengers raise crash risk.","p":"Right. Only one passenger under 21, besides family."},"es":{"q":"En Michigan, ¿cuántos pasajeros menores de 21 años puede llevar un conductor de Nivel 2, sin contar a la familia?","o":["Ninguno","Dos","Tres","Uno"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor de Nivel 2 no puede llevar más de un pasajero menor de 21 años, sin contar a su familia, porque los pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero menor de 21, además de la familia."},"zh":{"q":"在 Michigan，不算家人，Level 2 司机可以载多少位 21 岁以下的乘客？","o":["一个都不行","两位","三位","一位"],"h1":"多于零，但少于二。","h2":"除了自己的家人，Level 2 司机最多只能载一位 21 岁以下的乘客，因为年轻乘客会增加车祸风险。","p":"对。除了家人，只能载一位 21 岁以下的乘客。"},"vi":{"q":"Ở Michigan, người lái Cấp 2 được chở bao nhiêu hành khách dưới 21 tuổi, không tính người trong gia đình?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Nhiều hơn không, nhưng ít hơn hai.","h2":"Người lái Cấp 2 được chở không quá một hành khách dưới 21 tuổi, trừ người trong gia đình mình, vì hành khách trẻ làm tăng nguy cơ tai nạn.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi, ngoài người trong gia đình."},"tl":{"q":"Sa Michigan, ilang pasaherong wala pang 21 ang puwedeng isakay ng Level 2 driver, hindi kasama ang pamilya?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Higit sa zero, pero kulang sa dalawa.","h2":"Ang Level 2 driver ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21, maliban sa sarili niyang pamilya, dahil pinapataas ng mga batang pasahero ang panganib ng banggaan.","p":"Tama. Isang pasahero lang na wala pang 21, bukod sa pamilya."},"ar":{"q":"في Michigan، كم راكبًا عمره أقل من 21 سنة يجوز لسائق المستوى 2 أن يحمل، بدون حساب أفراد العائلة؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"أكثر من صفر، لكن أقل من اثنين.","h2":"لا يجوز لسائق المستوى 2 أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة، ما عدا أفراد عائلته، لأن الركاب الصغار يزيدون خطر الحوادث.","p":"صحيح. راكب واحد فقط أقل من 21 سنة، غير أفراد العائلة."},"ref":{"doc":"MI","page":5}},{"id":"mi-012","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, what is the youngest age to move to a Level 3 full license?","o":["16 years old","17 years old","18 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"A teen can move up to a Level 3 license at 17 at the earliest, if all requirements are met and a parent agrees.","p":"Right. Level 3 can start at age 17."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para pasar a la licencia completa de Nivel 3?","o":["16 años","17 años","18 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"Un joven puede pasar a la licencia de Nivel 3 a los 17 años como mínimo, si cumple todos los requisitos y uno de sus padres está de acuerdo.","p":"Correcto. El Nivel 3 puede empezar a los 17 años."},"zh":{"q":"在 Michigan，最小几岁可以升到 Level 3 正式驾照？","o":["16 岁","17 岁","18 岁","21 岁"],"h1":"比 Level 2 的最小年龄晚一年。","h2":"如果满足所有要求，而且父母同意，青少年最早 17 岁可以升到 Level 3 驾照。","p":"对。Level 3 最早从 17 岁开始。"},"vi":{"q":"Ở Michigan, tuổi nhỏ nhất để lên bằng lái đầy đủ Cấp 3 (Level 3) là bao nhiêu?","o":["16 tuổi","17 tuổi","18 tuổi","21 tuổi"],"h1":"Đó là một năm sau tuổi nhỏ nhất của Cấp 2.","h2":"Thiếu niên có thể lên giấy phép Cấp 3 sớm nhất khi 17 tuổi, nếu đáp ứng mọi yêu cầu và cha mẹ đồng ý.","p":"Đúng. Cấp 3 có thể bắt đầu khi 17 tuổi."},"tl":{"q":"Sa Michigan, ano ang pinakabatang edad para lumipat sa Level 3 na buong lisensya?","o":["16 taong gulang","17 taong gulang","18 taong gulang","21 taong gulang"],"h1":"Ito ay isang taon pagkatapos ng pinakabatang edad para sa Level 2.","h2":"Puwedeng lumipat ang teenager sa Level 3 license sa edad na 17 sa pinakamaaga, kung natugunan ang lahat ng kailangan at pumayag ang magulang.","p":"Tama. Puwedeng magsimula ang Level 3 sa edad na 17."},"ar":{"q":"في Michigan، ما أصغر عمر للانتقال إلى الرخصة الكاملة من المستوى 3 (Level 3)؟","o":["16 سنة","17 سنة","18 سنة","21 سنة"],"h1":"هو بعد أصغر عمر للمستوى 2 بسنة واحدة.","h2":"يمكن للمراهق الانتقال إلى رخصة المستوى 3 في عمر 17 سنة على أقرب تقدير، إذا استوفى كل الشروط ووافق أحد الوالدين.","p":"صحيح. يمكن أن يبدأ المستوى 3 في عمر 17 سنة."},"ref":{"doc":"MI","page":5}},{"id":"mi-013","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, Kelsey’s Law limits cell phone use for which drivers?","o":["All drivers over 65","Drivers of school buses only","Drivers with a Level 1 or Level 2 license","Only drivers with a past crash"],"h1":"It is about the newest drivers.","h2":"Kelsey’s Law limits phone use by drivers who hold a Level 1 or Level 2 license, because new drivers are easily distracted; calls for emergencies are allowed.","p":"Right. Kelsey’s Law covers Level 1 and Level 2 drivers."},"es":{"q":"En Michigan, ¿a qué conductores les limita el uso del celular la Ley de Kelsey?","o":["A todos los conductores mayores de 65","Solo a choferes de autobús escolar","A conductores con licencia de Nivel 1 o Nivel 2","Solo a conductores que ya tuvieron un choque"],"h1":"Se trata de los conductores más nuevos.","h2":"La Ley de Kelsey limita el uso del teléfono a quienes tienen licencia de Nivel 1 o Nivel 2, porque los conductores nuevos se distraen fácilmente; las llamadas de emergencia se permiten.","p":"Correcto. La Ley de Kelsey aplica a conductores de Nivel 1 y Nivel 2."},"zh":{"q":"在 Michigan，Kelsey’s Law 限制哪些司机使用手机？","o":["所有 65 岁以上的司机","只有校车司机","持 Level 1 或 Level 2 驾照的司机","只有以前出过车祸的司机"],"h1":"它和最新的司机有关。","h2":"Kelsey’s Law 限制持 Level 1 或 Level 2 驾照的司机使用手机，因为新司机很容易分心；紧急情况可以打电话。","p":"对。Kelsey’s Law 适用于 Level 1 和 Level 2 司机。"},"vi":{"q":"Ở Michigan, Luật Kelsey (Kelsey’s Law) giới hạn việc dùng điện thoại di động đối với những người lái nào?","o":["Tất cả người lái trên 65 tuổi","Chỉ tài xế xe buýt trường học","Người lái có giấy phép Cấp 1 hoặc Cấp 2","Chỉ người lái đã từng gây tai nạn"],"h1":"Nó nói về những người lái mới nhất.","h2":"Luật Kelsey giới hạn việc dùng điện thoại của người lái có giấy phép Cấp 1 hoặc Cấp 2, vì người lái mới dễ bị phân tâm; vẫn được gọi khi có trường hợp khẩn cấp.","p":"Đúng. Luật Kelsey áp dụng cho người lái Cấp 1 và Cấp 2."},"tl":{"q":"Sa Michigan, nililimitahan ng Kelsey’s Law ang paggamit ng cell phone ng aling mga driver?","o":["Lahat ng driver na lampas 65","Mga driver ng school bus lamang","Mga driver na may Level 1 o Level 2 license","Mga driver lamang na nagkaroon na ng banggaan"],"h1":"Tungkol ito sa pinakabagong mga driver.","h2":"Nililimitahan ng Kelsey’s Law ang paggamit ng phone ng mga driver na may Level 1 o Level 2 license, dahil madaling ma-distract ang mga bagong driver; pinapayagan ang tawag para sa emergency.","p":"Tama. Saklaw ng Kelsey’s Law ang Level 1 at Level 2 drivers."},"ar":{"q":"في Michigan، قانون كيلسي (Kelsey’s Law) يقيّد استخدام الهاتف المحمول لأي سائقين؟","o":["كل السائقين فوق 65 سنة","سائقو الحافلات المدرسية فقط","السائقون الذين يحملون رخصة المستوى 1 أو المستوى 2","السائقون الذين وقع لهم حادث سابق فقط"],"h1":"يتعلّق بأحدث السائقين.","h2":"قانون كيلسي (Kelsey’s Law) يقيّد استخدام الهاتف للسائقين الذين يحملون رخصة المستوى 1 أو المستوى 2، لأن السائقين الجدد يتشتّت انتباههم بسهولة؛ والمكالمات في حالات الطوارئ مسموحة.","p":"صحيح. قانون كيلسي يشمل سائقي المستوى 1 والمستوى 2."},"ref":{"doc":"MI","page":24}},{"id":"mi-014","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, you are stopped at a red light. May you hold your phone in your hand?","o":["No, holding a phone is not allowed even while stopped in traffic","Yes, because the car is not moving","Yes, if you only read messages","Yes, if the light is long"],"h1":"Michigan’s hands-free law does not stop at red lights.","h2":"Michigan law does not let you hold a phone while driving, and that includes waiting at a red light or in stopped traffic.","p":"Right. No holding the phone, even at a red light."},"es":{"q":"En Michigan, usted está detenido en una luz roja. ¿Puede tener el teléfono en la mano?","o":["No, no se permite tener el teléfono en la mano ni detenido en el tráfico","Sí, porque el carro no se mueve","Sí, si solo lee mensajes","Sí, si la luz es larga"],"h1":"La ley de manos libres de Michigan no se detiene en las luces rojas.","h2":"La ley de Michigan no le permite tener el teléfono en la mano mientras maneja, y eso incluye esperar en una luz roja o en tráfico detenido.","p":"Correcto. No puede tener el teléfono en la mano, ni en una luz roja."},"zh":{"q":"在 Michigan，你停在红灯前。你可以把手机拿在手里吗？","o":["不可以，即使在车流中停着，也不能拿手机","可以，因为车没有在动","可以，如果你只是看短信","可以，如果红灯很长"],"h1":"Michigan 的免提法在红灯时也适用。","h2":"Michigan 法律不让你开车时手拿手机，这也包括在红灯前或在停住的车流中等待的时候。","p":"对。即使在红灯前，也不能手拿手机。"},"vi":{"q":"Ở Michigan, bạn đang dừng ở đèn đỏ. Bạn có được cầm điện thoại trên tay không?","o":["Không, không được cầm điện thoại ngay cả khi đang dừng trong dòng xe","Có, vì xe không chạy","Có, nếu bạn chỉ đọc tin nhắn","Có, nếu đèn đỏ lâu"],"h1":"Luật rảnh tay của Michigan vẫn áp dụng ở đèn đỏ.","h2":"Luật Michigan không cho phép bạn cầm điện thoại khi lái xe, kể cả khi đang chờ đèn đỏ hoặc dừng trong dòng xe.","p":"Đúng. Không được cầm điện thoại, kể cả ở đèn đỏ."},"tl":{"q":"Sa Michigan, nakahinto ka sa pulang ilaw. Puwede mo bang hawakan ang phone mo?","o":["Hindi, bawal humawak ng phone kahit nakahinto sa trapiko","Oo, dahil hindi gumagalaw ang kotse","Oo, kung nagbabasa ka lang ng mga mensahe","Oo, kung matagal ang pulang ilaw"],"h1":"Hindi tumitigil sa pulang ilaw ang hands-free law ng Michigan.","h2":"Hindi ka pinapayagan ng batas ng Michigan na humawak ng phone habang nagmamaneho, kasama na ang paghihintay sa pulang ilaw o sa nakahintong trapiko.","p":"Tama. Bawal humawak ng phone, kahit sa pulang ilaw."},"ar":{"q":"في Michigan، أنت متوقّف عند إشارة حمراء. هل يجوز لك أن تمسك هاتفك بيدك؟","o":["لا، لا يجوز مسك الهاتف حتى وأنت متوقّف في حركة السير","نعم، لأن السيارة لا تتحرّك","نعم، إذا كنت تقرأ الرسائل فقط","نعم، إذا كانت الإشارة طويلة"],"h1":"قانون عدم استخدام اليدين (hands-free) في Michigan لا يتوقّف عند الإشارة الحمراء.","h2":"قانون Michigan لا يسمح لك بمسك الهاتف أثناء القيادة، وهذا يشمل الانتظار عند إشارة حمراء أو في حركة سير متوقّفة.","p":"صحيح. لا تمسك الهاتف، حتى عند الإشارة الحمراء."},"ref":{"doc":"MI","page":null}},{"id":"mi-015","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, you pass a stopped emergency vehicle with its lights on and cannot move over. How much must you slow down?","o":["To 5 mph below the speed limit","To at least 10 mph below the speed limit","To 15 mph below the speed limit","To exactly 20 mph"],"h1":"It is a round number, and it is the least you must slow.","h2":"If you cannot move over safely, you must slow to at least 10 mph below the posted speed limit and pass with care.","p":"Right. Slow to at least 10 mph below the limit."},"es":{"q":"En Michigan, usted pasa junto a un vehículo de emergencia detenido con las luces encendidas y no puede cambiarse de carril. ¿Cuánto debe bajar la velocidad?","o":["A 5 mph menos del límite","A por lo menos 10 mph menos del límite","A 15 mph menos del límite","Exactamente a 20 mph"],"h1":"Es un número redondo, y es lo mínimo que debe bajar.","h2":"Si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 10 mph menos del límite indicado y pasar con cuidado.","p":"Correcto. Baje a por lo menos 10 mph menos del límite."},"zh":{"q":"在 Michigan，你经过一辆停着、开着灯的急救车辆，但你没办法换道让开。你必须减速多少？","o":["减到比限速低 5 英里/小时","减到比限速至少低 10 英里/小时","减到比限速低 15 英里/小时","减到正好 20 英里/小时"],"h1":"这是一个整数，而且是你最少要减的速度。","h2":"如果你不能安全地换道让开，你必须把速度减到比标出的限速至少低 10 英里/小时，然后小心地开过去。","p":"对。减到比限速至少低 10 英里/小时。"},"vi":{"q":"Ở Michigan, bạn đi qua một xe khẩn cấp đang dừng và bật đèn, nhưng bạn không thể chuyển làn. Bạn phải giảm tốc độ bao nhiêu?","o":["Xuống 5 mph dưới tốc độ giới hạn","Xuống ít nhất 10 mph dưới tốc độ giới hạn","Xuống 15 mph dưới tốc độ giới hạn","Xuống đúng 20 mph"],"h1":"Đó là một số tròn, và là mức ít nhất bạn phải giảm.","h2":"Nếu bạn không thể chuyển làn an toàn, bạn phải giảm xuống ít nhất 10 mph dưới tốc độ giới hạn có biển báo và đi qua cẩn thận.","p":"Đúng. Giảm xuống ít nhất 10 mph dưới tốc độ giới hạn."},"tl":{"q":"Sa Michigan, dumadaan ka sa isang nakahintong emergency vehicle na nakabukas ang ilaw at hindi ka makalipat ng lane. Gaano ka dapat bumagal?","o":["Hanggang 5 mph mas mababa sa speed limit","Hanggang hindi bababa sa 10 mph mas mababa sa speed limit","Hanggang 15 mph mas mababa sa speed limit","Hanggang eksaktong 20 mph"],"h1":"Ito ay buong numero, at ito ang pinakamaliit na dapat mong ibagal.","h2":"Kung hindi ka ligtas na makalipat ng lane, dapat kang bumagal nang hindi bababa sa 10 mph mas mababa sa nakapaskil na speed limit at dumaan nang maingat.","p":"Tama. Bumagal nang hindi bababa sa 10 mph mas mababa sa limit."},"ar":{"q":"في Michigan، تمرّ بجانب سيارة طوارئ متوقّفة وأضواؤها مضاءة ولا تستطيع الانتقال إلى مسار آخر. كم يجب أن تخفّف سرعتك؟","o":["إلى 5 mph أقل من حد السرعة","إلى 10 mph على الأقل أقل من حد السرعة","إلى 15 mph أقل من حد السرعة","إلى 20 mph بالضبط"],"h1":"هو رقم مستدير، وهو أقل ما يجب أن تخفّفه.","h2":"إذا لم تستطع الانتقال إلى مسار آخر بأمان، يجب أن تخفّف سرعتك إلى 10 mph على الأقل أقل من حد السرعة المكتوب وأن تمرّ بحذر.","p":"صحيح. خفّف إلى 10 mph على الأقل أقل من الحد."},"ref":{"doc":"MI","page":28}},{"id":"mi-016","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, besides police, fire and ambulance vehicles, which stopped vehicle with flashing lights must you move over for?","o":["A parked delivery van","A car with a flat tire and no lights","A school bus with no lights on","A garbage truck or utility truck with its lights on"],"h1":"It is a work vehicle using warning lights.","h2":"Michigan’s move-over law also covers tow trucks, road crews, utility trucks and garbage trucks that are stopped with their lights flashing.","p":"Right. Move over for work trucks with flashing lights, too."},"es":{"q":"En Michigan, además de policía, bomberos y ambulancias, ¿por qué vehículo detenido con luces intermitentes debe cambiarse de carril?","o":["Una camioneta de reparto estacionada","Un carro con una llanta ponchada y sin luces","Un autobús escolar sin luces encendidas","Un camión de basura o de servicios públicos con las luces encendidas"],"h1":"Es un vehículo de trabajo que usa luces de aviso.","h2":"La ley de Michigan también cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y camiones de basura detenidos con luces intermitentes.","p":"Correcto. También cámbiese de carril por camiones de trabajo con luces intermitentes."},"zh":{"q":"在 Michigan，除了警车、消防车和救护车以外，你还必须为哪种停着、闪着灯的车让出车道？","o":["一辆停着的送货车","一辆爆胎、没有开灯的汽车","一辆没有开灯的校车","一辆开着灯的垃圾车或公用事业工程车"],"h1":"这是一辆开着警示灯的工作车辆。","h2":"Michigan 的 move over 法也包括停着、闪着灯的拖车、道路施工车、公用事业工程车和垃圾车。","p":"对。对闪着灯的工作卡车也要让出车道。"},"vi":{"q":"Ở Michigan, ngoài xe cảnh sát, xe cứu hỏa và xe cứu thương, bạn phải chuyển làn để tránh xe nào đang dừng và bật đèn nhấp nháy?","o":["Một xe giao hàng đang đậu","Một xe bị xẹp lốp và không bật đèn","Một xe buýt trường học không bật đèn","Một xe rác hoặc xe tiện ích (utility truck) đang bật đèn"],"h1":"Đó là một xe làm việc đang bật đèn cảnh báo.","h2":"Luật chuyển làn (move-over law) của Michigan cũng áp dụng cho xe kéo, đội sửa đường, xe tiện ích và xe rác đang dừng và bật đèn nhấp nháy.","p":"Đúng. Cũng phải chuyển làn để tránh xe làm việc có đèn nhấp nháy."},"tl":{"q":"Sa Michigan, bukod sa sasakyan ng pulis, bumbero at ambulansya, para sa aling nakahintong sasakyan na may kumikislap na ilaw ka dapat lumipat ng lane?","o":["Isang nakaparadang delivery van","Isang kotseng flat ang gulong at walang ilaw","Isang school bus na walang nakabukas na ilaw","Isang trak ng basura o utility truck na nakabukas ang ilaw"],"h1":"Ito ay sasakyang pantrabaho na gumagamit ng warning lights.","h2":"Saklaw din ng move-over law ng Michigan ang mga tow truck, road crew, utility truck at trak ng basura na nakahinto at kumikislap ang ilaw.","p":"Tama. Lumipat din ng lane para sa mga trak na pantrabaho na may kumikislap na ilaw."},"ar":{"q":"في Michigan، بالإضافة إلى سيارات الشرطة والإطفاء والإسعاف، لأي مركبة متوقّفة بأضواء وامضة يجب أن تنتقل إلى مسار آخر؟","o":["شاحنة توصيل متوقّفة","سيارة بإطار مثقوب وبدون أضواء","حافلة مدرسية بدون أضواء مضاءة","شاحنة نفايات أو شاحنة خدمات (utility truck) وأضواؤها مضاءة"],"h1":"هي مركبة عمل تستخدم أضواء تحذير.","h2":"قانون الانتقال إلى مسار آخر (move-over law) في Michigan يشمل أيضًا شاحنات السحب وطواقم الطرق وشاحنات الخدمات وشاحنات النفايات المتوقّفة وأضواؤها تومض.","p":"صحيح. انتقل إلى مسار آخر أيضًا لشاحنات العمل ذات الأضواء الوامضة."},"ref":{"doc":"MI","page":28}},{"id":"mi-017","scope":"MI","cat":"signals","sign":null,"c":2,"en":{"q":"In Michigan, when may you turn left on a red light?","o":["Never, under any condition","Whenever no cars are coming","After a full stop, onto a one-way street going left, unless a sign forbids it","Only when a green arrow is also shown"],"h1":"The street you turn into must carry traffic only in the direction of your turn.","h2":"You may turn left on red onto a one-way street whose traffic moves to the left, after a full stop and after yielding, unless a sign forbids it.","p":"Right. Left on red is allowed onto a one-way street, after a full stop."},"es":{"q":"En Michigan, ¿cuándo puede doblar a la izquierda con luz roja?","o":["Nunca, en ninguna situación","Siempre que no vengan carros","Después de un alto total, hacia una calle de un solo sentido que va a la izquierda, salvo que una señal lo prohíba","Solo cuando también hay una flecha verde"],"h1":"La calle a la que entra debe llevar tráfico solo en la dirección de su vuelta.","h2":"Usted puede doblar a la izquierda con luz roja hacia una calle de un solo sentido cuyo tráfico va a la izquierda, después de un alto total y de ceder el paso, salvo que una señal lo prohíba.","p":"Correcto. Se permite a la izquierda con luz roja hacia una calle de un solo sentido, después de un alto total."},"zh":{"q":"在 Michigan，什么时候可以红灯左转？","o":["任何情况下都不可以","只要没有车来就可以","完全停车后，转进往左行驶的单行道，除非有标志禁止","只有同时亮绿色箭头时"],"h1":"你转进去的街道，车只能朝你转弯的方向行驶。","h2":"完全停车并让行以后，你可以在红灯时左转进车流往左走的单行道，除非有标志禁止。","p":"对。完全停车后，可以红灯左转进单行道。"},"vi":{"q":"Ở Michigan, khi nào bạn được rẽ trái khi đèn đỏ?","o":["Không bao giờ, trong mọi trường hợp","Bất cứ khi nào không có xe tới","Sau khi dừng hẳn, vào đường một chiều chạy về bên trái, trừ khi có biển cấm","Chỉ khi cũng có mũi tên xanh"],"h1":"Con đường bạn rẽ vào chỉ được có xe chạy theo hướng bạn rẽ.","h2":"Bạn được rẽ trái khi đèn đỏ vào đường một chiều có xe chạy về bên trái, sau khi dừng hẳn và nhường đường, trừ khi có biển cấm.","p":"Đúng. Được rẽ trái khi đèn đỏ vào đường một chiều, sau khi dừng hẳn."},"tl":{"q":"Sa Michigan, kailan ka puwedeng kumaliwa sa pulang ilaw?","o":["Hindi kailanman, sa anumang sitwasyon","Kapag walang paparating na kotse","Pagkatapos ng buong paghinto, papasok sa one-way street na papuntang kaliwa, maliban kung may karatulang nagbabawal","Kapag may nakikita ring berdeng arrow lamang"],"h1":"Ang kalsadang papasukan mo ay dapat may trapiko lamang sa direksyon ng liko mo.","h2":"Puwede kang kumaliwa sa pulang ilaw papasok sa one-way street na ang trapiko ay papuntang kaliwa, pagkatapos ng buong paghinto at pagbibigay-daan, maliban kung may karatulang nagbabawal.","p":"Tama. Puwedeng kumaliwa sa pula papasok sa one-way street, pagkatapos ng buong paghinto."},"ar":{"q":"في Michigan، متى يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء؟","o":["أبدًا، في أي حال","كلما لم تكن هناك سيارات قادمة","بعد التوقّف التام، إلى شارع باتجاه واحد يسير نحو اليسار، إلا إذا منعت ذلك لافتة","فقط عندما يظهر أيضًا سهم أخضر"],"h1":"الشارع الذي تدخله يجب أن تسير فيه السيارات فقط في اتجاه انعطافك.","h2":"يجوز لك أن تنعطف يسارًا عند الإشارة الحمراء إلى شارع باتجاه واحد تسير فيه السيارات نحو اليسار، بعد التوقّف التام وإعطاء الأولوية، إلا إذا منعت ذلك لافتة.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح إلى شارع باتجاه واحد، بعد التوقّف التام."},"ref":{"doc":"MI","page":30}},{"id":"mi-018","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, a school bus stops with flashing red lights on the other side of a highway divided by a median or barrier. Who must stop?","o":["Only traffic going the same direction as the bus","Traffic going both directions","No one, because it is a highway","Only trucks and buses"],"h1":"The divider protects the far side.","h2":"On a highway divided by a median or barrier, only traffic going the same way as the bus must stop; traffic on the other side should still drive with care.","p":"Right. On a divided highway, only traffic going the bus’s way stops."},"es":{"q":"En Michigan, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por una mediana o barrera. ¿Quién debe detenerse?","o":["Solo el tráfico que va en la misma dirección que el autobús","El tráfico en ambas direcciones","Nadie, porque es una carretera","Solo camiones y autobuses"],"h1":"La división protege el lado de enfrente.","h2":"En una carretera dividida por una mediana o barrera, solo el tráfico que va en la misma dirección que el autobús debe detenerse; el tráfico del otro lado igual debe manejar con cuidado.","p":"Correcto. En una carretera dividida, solo se detiene el tráfico que va en la dirección del autobús."},"zh":{"q":"在 Michigan，一辆校车在有中央隔离带或护栏分隔的公路另一边停下，闪着红灯。谁必须停车？","o":["只有和校车同方向的车","两个方向的车","没有人，因为这是公路","只有卡车和公共汽车"],"h1":"隔离带保护着另一边。","h2":"在有中央隔离带或护栏分隔的公路上，只有和校车同方向的车必须停车；另一边的车仍然要小心开。","p":"对。在分隔公路上，只有和校车同方向的车要停。"},"vi":{"q":"Ở Michigan, một xe buýt trường học dừng và bật đèn đỏ nhấp nháy ở phía bên kia của xa lộ có dải phân cách hoặc rào chắn. Ai phải dừng lại?","o":["Chỉ xe chạy cùng hướng với xe buýt","Xe chạy cả hai hướng","Không ai cả, vì đó là xa lộ","Chỉ xe tải và xe buýt"],"h1":"Dải phân cách bảo vệ phía bên kia.","h2":"Trên xa lộ có dải phân cách hoặc rào chắn, chỉ xe chạy cùng hướng với xe buýt phải dừng; xe ở phía bên kia vẫn nên lái cẩn thận.","p":"Đúng. Trên xa lộ có dải phân cách, chỉ xe chạy cùng hướng với xe buýt phải dừng."},"tl":{"q":"Sa Michigan, huminto ang isang school bus na may kumikislap na pulang ilaw sa kabilang panig ng highway na hinahati ng median o harang. Sino ang dapat huminto?","o":["Ang trapiko lamang na papunta sa parehong direksyon ng bus","Ang trapiko sa magkabilang direksyon","Walang dapat huminto, dahil highway ito","Mga trak at bus lamang"],"h1":"Pinoprotektahan ng harang ang kabilang panig.","h2":"Sa highway na hinahati ng median o harang, ang trapiko lamang na papunta sa parehong direksyon ng bus ang dapat huminto; ang trapiko sa kabilang panig ay dapat pa ring magmaneho nang maingat.","p":"Tama. Sa hinating highway, ang trapiko lamang sa direksyon ng bus ang humihinto."},"ar":{"q":"في Michigan، توقّفت حافلة مدرسية بأضواء حمراء وامضة على الجانب الآخر من طريق سريع يفصله حاجز وسطي أو حاجز. مَن يجب أن يتوقّف؟","o":["فقط السيارات التي تسير في نفس اتجاه الحافلة","السيارات في الاتجاهين","لا أحد، لأنه طريق سريع","الشاحنات والحافلات فقط"],"h1":"الحاجز يحمي الجانب البعيد.","h2":"على طريق سريع يفصله حاجز وسطي أو حاجز، فقط السيارات التي تسير في نفس اتجاه الحافلة يجب أن تتوقّف؛ والسيارات على الجانب الآخر يجب أن تقود بحذر مع ذلك.","p":"صحيح. على طريق سريع مقسوم، تتوقّف فقط السيارات التي تسير في اتجاه الحافلة."},"ref":{"doc":"MI","page":28}},{"id":"mi-019","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how far from a stopped school bus with flashing red lights must you stop?","o":["At least 10 feet","At least 20 feet","At least 30 feet","At least 50 feet"],"h1":"It is a bit longer than one car.","h2":"You must stop at least 20 feet from a school bus with flashing red lights and wait until it moves or the lights stop.","p":"Right. Stop at least 20 feet from the bus."},"es":{"q":"En Michigan, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 10 pies","Por lo menos a 20 pies","Por lo menos a 30 pies","Por lo menos a 50 pies"],"h1":"Es un poco más largo que un carro.","h2":"Usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes y esperar a que avance o se apaguen las luces.","p":"Correcto. Deténgase por lo menos a 20 pies del autobús."},"zh":{"q":"在 Michigan，你必须在离闪着红灯、停着的校车多远的地方停车？","o":["至少 10 英尺","至少 20 英尺","至少 30 英尺","至少 50 英尺"],"h1":"比一辆汽车稍微长一点。","h2":"你必须在离闪着红灯的校车至少 20 英尺的地方停车，等到校车开走或红灯停止闪。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Michigan, bạn phải dừng cách xe buýt trường học đang dừng và bật đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 30 feet","Ít nhất 50 feet"],"h1":"Đó là dài hơn một chiếc xe hơi một chút.","h2":"Bạn phải dừng cách xe buýt trường học có đèn đỏ nhấp nháy ít nhất 20 feet và chờ đến khi xe buýt chạy hoặc đèn tắt.","p":"Đúng. Dừng cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Michigan, gaano kalayo dapat kang huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 30 feet","Hindi bababa sa 50 feet"],"h1":"Medyo mas mahaba ito kaysa isang kotse.","h2":"Dapat kang huminto nang hindi bababa sa 20 feet mula sa school bus na may kumikislap na pulang ilaw at maghintay hanggang umandar ito o tumigil ang ilaw.","p":"Tama. Huminto nang hindi bababa sa 20 feet mula sa bus."},"ar":{"q":"في Michigan، على أي مسافة من حافلة مدرسية متوقّفة بأضواء حمراء وامضة يجب أن تتوقّف؟","o":["10 أقدام (feet) على الأقل","20 قدمًا (feet) على الأقل","30 قدمًا (feet) على الأقل","50 قدمًا (feet) على الأقل"],"h1":"هي أطول قليلًا من طول سيارة واحدة.","h2":"يجب أن تتوقّف على بُعد 20 قدمًا على الأقل من حافلة مدرسية بأضواء حمراء وامضة، وأن تنتظر حتى تتحرّك أو تنطفئ الأضواء.","p":"صحيح. توقّف على بُعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"MI","page":28}},{"id":"mi-020","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, on a limited-access freeway with no posted speed limit, what is the top legal speed?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is higher than the limit for ordinary highways with no sign.","h2":"On a limited-access freeway with no posted limit, the top legal speed is 70 mph; some rural freeways are posted higher.","p":"Right. The default freeway limit is 70 mph."},"es":{"q":"En Michigan, en una autopista de acceso limitado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más alta que el límite de carreteras comunes sin señal.","h2":"En una autopista de acceso limitado sin límite indicado, la velocidad máxima legal es 70 mph; algunas autopistas rurales tienen señales con un límite más alto.","p":"Correcto. El límite normal en autopista es 70 mph."},"zh":{"q":"在 Michigan，在没有标出限速的封闭式高速公路（limited-access freeway）上，最高合法速度是多少？","o":["55 英里/小时","60 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比没有标志的普通公路的限速高。","h2":"在没有标出限速的封闭式高速公路上，最高合法速度是 70 英里/小时；有些乡村高速公路标出的限速更高。","p":"对。高速公路默认限速是 70 英里/小时。"},"vi":{"q":"Ở Michigan, trên xa lộ cao tốc hạn chế lối vào (limited-access freeway) không có biển giới hạn tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Nó cao hơn giới hạn của xa lộ thông thường không có biển báo.","h2":"Trên xa lộ cao tốc hạn chế lối vào không có biển giới hạn, tốc độ tối đa hợp pháp là 70 mph; một số xa lộ cao tốc ở vùng nông thôn có biển báo cao hơn.","p":"Đúng. Giới hạn mặc định trên xa lộ cao tốc là 70 mph."},"tl":{"q":"Sa Michigan, sa limited-access freeway na walang nakapaskil na speed limit, ano ang pinakamataas na legal na bilis?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mataas ito kaysa sa limit ng karaniwang highway na walang karatula.","h2":"Sa limited-access freeway na walang nakapaskil na limit, ang pinakamataas na legal na bilis ay 70 mph; may ilang rural freeway na mas mataas ang nakapaskil.","p":"Tama. Ang default na limit sa freeway ay 70 mph."},"ar":{"q":"في Michigan، على طريق سريع محدود المداخل (limited-access freeway) بدون حد سرعة مكتوب، ما أعلى سرعة قانونية؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"هي أعلى من حد الطرق العادية التي ليس عليها لافتة.","h2":"على طريق سريع محدود المداخل بدون حد مكتوب، أعلى سرعة قانونية هي 70 mph؛ وبعض الطرق السريعة الريفية عليها حد مكتوب أعلى.","p":"صحيح. الحد الافتراضي على الطريق السريع هو 70 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-021","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, on a state or county highway with no posted speed limit, what is the top legal speed?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than the freeway default.","h2":"On a state trunkline or county highway with no posted limit, the top legal speed is 55 mph.","p":"Right. The default on these highways is 55 mph."},"es":{"q":"En Michigan, en una carretera estatal o del condado sin límite indicado, ¿cuál es la velocidad máxima legal?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es más bajo que el límite normal de autopista.","h2":"En una carretera troncal estatal o del condado sin límite indicado, la velocidad máxima legal es 55 mph.","p":"Correcto. El límite normal en estas carreteras es 55 mph."},"zh":{"q":"在 Michigan，在没有标出限速的州公路或县公路上，最高合法速度是多少？","o":["55 英里/小时","45 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比高速公路的默认限速低。","h2":"在没有标出限速的州干线公路或县公路上，最高合法速度是 55 英里/小时。","p":"对。这些公路的默认限速是 55 英里/小时。"},"vi":{"q":"Ở Michigan, trên xa lộ của tiểu bang hoặc của quận không có biển giới hạn tốc độ, tốc độ tối đa hợp pháp là bao nhiêu?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó thấp hơn mức mặc định trên xa lộ cao tốc.","h2":"Trên đường chính của tiểu bang (state trunkline) hoặc xa lộ của quận không có biển giới hạn, tốc độ tối đa hợp pháp là 55 mph.","p":"Đúng. Mức mặc định trên những xa lộ này là 55 mph."},"tl":{"q":"Sa Michigan, sa state o county highway na walang nakapaskil na speed limit, ano ang pinakamataas na legal na bilis?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa default ng freeway.","h2":"Sa state trunkline o county highway na walang nakapaskil na limit, ang pinakamataas na legal na bilis ay 55 mph.","p":"Tama. Ang default sa mga highway na ito ay 55 mph."},"ar":{"q":"في Michigan، على طريق تابع للولاية أو للمقاطعة بدون حد سرعة مكتوب، ما أعلى سرعة قانونية؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هي أقل من الحد الافتراضي للطريق السريع.","h2":"على طريق رئيسي للولاية (state trunkline) أو طريق للمقاطعة بدون حد مكتوب، أعلى سرعة قانونية هي 55 mph.","p":"صحيح. الحد الافتراضي على هذه الطرق هو 55 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-022","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, what is the highest speed limit posted on some rural freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 5 mph above the freeway default.","h2":"Michigan posts a 75 mph limit on some rural freeways; you may go that fast only where the signs say so.","p":"Right. Some rural freeways are posted at 75 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad más alto indicado en algunas autopistas rurales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es 5 mph más que el límite normal de autopista.","h2":"Michigan indica un límite de 75 mph en algunas autopistas rurales; usted solo puede ir tan rápido donde las señales lo dicen.","p":"Correcto. Algunas autopistas rurales tienen límite de 75 mph."},"zh":{"q":"在 Michigan，有些乡村高速公路标出的最高限速是多少？","o":["65 英里/小时","70 英里/小时","75 英里/小时","80 英里/小时"],"h1":"比高速公路的默认限速高 5 英里/小时。","h2":"Michigan 在一些乡村高速公路上标出 75 英里/小时的限速；只有在标志这样写的地方，你才可以开这么快。","p":"对。有些乡村高速公路限速 75 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ cao nhất được ghi trên biển ở một số xa lộ cao tốc vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn mức mặc định trên xa lộ cao tốc 5 mph.","h2":"Michigan đặt giới hạn 75 mph trên một số xa lộ cao tốc vùng nông thôn; bạn chỉ được chạy nhanh như vậy ở nơi có biển báo cho phép.","p":"Đúng. Một số xa lộ cao tốc vùng nông thôn có biển 75 mph."},"tl":{"q":"Sa Michigan, ano ang pinakamataas na speed limit na nakapaskil sa ilang rural freeway?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Ito ay 5 mph na mas mataas sa default ng freeway.","h2":"Naglalagay ang Michigan ng 75 mph na limit sa ilang rural freeway; puwede kang tumakbo nang ganoon kabilis lamang kung saan sinasabi ng mga karatula.","p":"Tama. May ilang rural freeway na nakapaskil sa 75 mph."},"ar":{"q":"في Michigan، ما أعلى حد سرعة مكتوب على بعض الطرق السريعة الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى من الحد الافتراضي للطريق السريع بـ5 mph.","h2":"تضع Michigan حدًا قدره 75 mph على بعض الطرق السريعة الريفية؛ ولا يجوز لك أن تسير بهذه السرعة إلا حيث تقول اللافتات ذلك.","p":"صحيح. بعض الطرق السريعة الريفية عليها حد 75 mph."},"ref":{"doc":"MI","page":null}},{"id":"mi-023","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, what is the speed limit in a residential subdivision?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same number many states use near homes.","h2":"The speed limit in a residential subdivision is 25 mph, because children and people walking are often near the street.","p":"Right. Residential subdivisions are 25 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad en un fraccionamiento residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"El límite de velocidad en un fraccionamiento residencial es 25 mph, porque a menudo hay niños y peatones cerca de la calle.","p":"Correcto. En fraccionamientos residenciales el límite es 25 mph."},"zh":{"q":"在 Michigan，住宅小区里的限速是多少？","o":["20 英里/小时","25 英里/小时","30 英里/小时","35 英里/小时"],"h1":"很多州在住家附近也用这个数字。","h2":"住宅小区里的限速是 25 英里/小时，因为街边常常有孩子和走路的人。","p":"对。住宅小区限速 25 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ trong khu dân cư (residential subdivision) là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Đó là cùng con số mà nhiều tiểu bang dùng gần nhà ở.","h2":"Giới hạn tốc độ trong khu dân cư là 25 mph, vì trẻ em và người đi bộ thường ở gần đường.","p":"Đúng. Khu dân cư là 25 mph."},"tl":{"q":"Sa Michigan, ano ang speed limit sa isang residential subdivision?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Ito ang parehong numero na ginagamit ng maraming estado malapit sa mga bahay.","h2":"Ang speed limit sa residential subdivision ay 25 mph, dahil madalas may mga bata at naglalakad malapit sa kalsada.","p":"Tama. 25 mph sa residential subdivision."},"ar":{"q":"في Michigan، ما حد السرعة في حي سكني (residential subdivision)؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو نفس الرقم الذي تستخدمه ولايات كثيرة قرب البيوت.","h2":"حد السرعة في الحي السكني هو 25 mph، لأن الأطفال والمشاة يكونون غالبًا قريبين من الشارع.","p":"صحيح. الأحياء السكنية 25 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-024","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, what is the speed limit inside a mobile home park?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"It is lower than a residential subdivision, but more than 10.","h2":"The speed limit inside a mobile home park is 15 mph, because homes and people are very close to the road.","p":"Right. Mobile home parks are 15 mph."},"es":{"q":"En Michigan, ¿cuál es el límite de velocidad dentro de un parque de casas móviles?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Es más bajo que en un fraccionamiento residencial, pero más de 10.","h2":"El límite de velocidad dentro de un parque de casas móviles es 15 mph, porque las casas y las personas están muy cerca del camino.","p":"Correcto. En parques de casas móviles el límite es 15 mph."},"zh":{"q":"在 Michigan，移动房屋社区（mobile home park）里的限速是多少？","o":["5 英里/小时","10 英里/小时","20 英里/小时","15 英里/小时"],"h1":"它比住宅小区低，但比 10 高。","h2":"移动房屋社区里的限速是 15 英里/小时，因为房子和人离路很近。","p":"对。移动房屋社区限速 15 英里/小时。"},"vi":{"q":"Ở Michigan, giới hạn tốc độ bên trong khu nhà di động (mobile home park) là bao nhiêu?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Nó thấp hơn khu dân cư, nhưng cao hơn 10.","h2":"Giới hạn tốc độ bên trong khu nhà di động là 15 mph, vì nhà cửa và người đi bộ ở rất gần đường.","p":"Đúng. Khu nhà di động là 15 mph."},"tl":{"q":"Sa Michigan, ano ang speed limit sa loob ng mobile home park?","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"Mas mababa ito kaysa sa residential subdivision, pero higit sa 10.","h2":"Ang speed limit sa loob ng mobile home park ay 15 mph, dahil napakalapit ng mga bahay at tao sa kalsada.","p":"Tama. 15 mph sa mobile home park."},"ar":{"q":"في Michigan، ما حد السرعة داخل مجمّع البيوت المتنقلة (mobile home park)؟","o":["5 mph","10 mph","20 mph","15 mph"],"h1":"هو أقل من الحي السكني، لكنه أكثر من 10.","h2":"حد السرعة داخل مجمّع البيوت المتنقلة هو 15 mph، لأن البيوت والناس قريبون جدًا من الطريق.","p":"صحيح. مجمّعات البيوت المتنقلة 15 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-025","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, at what blood alcohol level does the stricter high-BAC drunk driving law apply?","o":["0.10 percent or more","0.12 percent or more","0.17 percent or more","0.20 percent or more"],"h1":"It is about twice the regular adult limit.","h2":"Michigan’s high-BAC law, sometimes called the super drunk law, applies at 0.17 percent or more and carries harsher penalties than a regular drunk driving charge.","p":"Right. The high-BAC law starts at 0.17 percent."},"es":{"q":"En Michigan, ¿a partir de qué nivel de alcohol en la sangre se aplica la ley más estricta de alto nivel de alcohol?","o":["0.10 por ciento o más","0.12 por ciento o más","0.17 por ciento o más","0.20 por ciento o más"],"h1":"Es casi el doble del límite normal para adultos.","h2":"La ley de alto nivel de alcohol de Michigan, a veces llamada ley de súper ebrio, aplica desde 0.17 por ciento y trae castigos más duros que un cargo normal por manejar ebrio.","p":"Correcto. La ley de alto nivel empieza en 0.17 por ciento."},"zh":{"q":"在 Michigan，血液酒精浓度达到多少时，适用更严格的高酒精浓度（high-BAC）醉驾法？","o":["0.10% 或更高","0.12% 或更高","0.17% 或更高","0.20% 或更高"],"h1":"大约是一般成年人限值的两倍。","h2":"Michigan 的高酒精浓度法，有时叫做 super drunk 法，在 0.17% 或更高时适用，处罚比一般醉驾罪更重。","p":"对。高酒精浓度法从 0.17% 开始。"},"vi":{"q":"Ở Michigan, luật lái xe say rượu nghiêm khắc hơn cho nồng độ cồn cao (high-BAC) áp dụng từ mức nồng độ cồn trong máu nào?","o":["0.10 phần trăm trở lên","0.12 phần trăm trở lên","0.17 phần trăm trở lên","0.20 phần trăm trở lên"],"h1":"Nó khoảng gấp đôi giới hạn thông thường của người lớn.","h2":"Luật nồng độ cồn cao (high-BAC) của Michigan, đôi khi gọi là luật say xỉn nặng (super drunk law), áp dụng từ 0.17 phần trăm trở lên và có hình phạt nặng hơn tội lái xe say rượu thông thường.","p":"Đúng. Luật high-BAC bắt đầu từ 0.17 phần trăm."},"tl":{"q":"Sa Michigan, sa anong antas ng alak sa dugo (blood alcohol) nalalapat ang mas mahigpit na high-BAC drunk driving law?","o":["0.10 porsiyento o higit pa","0.12 porsiyento o higit pa","0.17 porsiyento o higit pa","0.20 porsiyento o higit pa"],"h1":"Halos doble ito ng karaniwang limit para sa adult.","h2":"Ang high-BAC law ng Michigan, na minsang tinatawag na super drunk law, ay nalalapat sa 0.17 porsiyento o higit pa at may mas mabigat na parusa kaysa sa karaniwang kaso ng drunk driving.","p":"Tama. Nagsisimula ang high-BAC law sa 0.17 porsiyento."},"ar":{"q":"في Michigan، عند أي نسبة كحول في الدم يُطبَّق قانون القيادة تحت تأثير الكحول الأشدّ للنسبة العالية (high-BAC)؟","o":["0.10 بالمئة أو أكثر","0.12 بالمئة أو أكثر","0.17 بالمئة أو أكثر","0.20 بالمئة أو أكثر"],"h1":"هي نحو ضعف الحد العادي للبالغين.","h2":"قانون النسبة العالية (high-BAC) في Michigan، الذي يُسمّى أحيانًا قانون السُّكر الشديد (super drunk law)، يُطبَّق عند 0.17 بالمئة أو أكثر وعقوباته أشدّ من تهمة القيادة تحت تأثير الكحول العادية.","p":"صحيح. يبدأ قانون high-BAC عند 0.17 بالمئة."},"ref":{"doc":"MI","page":null}},{"id":"mi-026","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.15 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Michigan’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Michigan, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.15 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Michigan sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Michigan，21 岁或以上的司机，血液酒精浓度达到多少在法律上就算醉驾？","o":["0.08% 或更高","0.05% 或更高","0.10% 或更高","0.15% 或更高"],"h1":"它不到百分之零点一。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或更高，就违反了 Michigan 的醉驾法。","p":"对。成年人的限值是 0.08%。"},"vi":{"q":"Ở Michigan, người lái từ 21 tuổi trở lên bị xem là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên","0.15 phần trăm trở lên"],"h1":"Nó nhỏ hơn một phần mười của một phần trăm.","h2":"Người lái từ 21 tuổi trở lên vi phạm luật lái xe say rượu của Michigan khi nồng độ cồn trong máu từ 0.08 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08 phần trăm."},"tl":{"q":"Sa Michigan, ang driver na 21 taong gulang pataas ay legal na lasing sa anong antas ng alak sa dugo?","o":["0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa","0.15 porsiyento o higit pa"],"h1":"Mas mababa ito sa ikasampung bahagi ng isang porsiyento.","h2":"Ang driver na 21 taong gulang pataas ay lumalabag sa drunk driving law ng Michigan kapag ang alak sa dugo ay 0.08 porsiyento o higit pa.","p":"Tama. Ang limit para sa adult ay 0.08 porsiyento."},"ar":{"q":"في Michigan، السائق الذي عمره 21 سنة أو أكثر يُعتبر قانونيًا في حالة سُكر عند أي نسبة كحول في الدم؟","o":["0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر","0.15 بالمئة أو أكثر"],"h1":"هي أقل من عُشر واحد بالمئة.","h2":"السائق الذي عمره 21 سنة أو أكثر يخالف قانون القيادة تحت تأثير الكحول في Michigan عندما تكون نسبة الكحول في دمه 0.08 بالمئة أو أكثر.","p":"صحيح. حد البالغين هو 0.08 بالمئة."},"ref":{"doc":"MI","page":null}},{"id":"mi-027","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","No alcohol from drinking at all","Up to 0.05 percent","Up to 0.10 percent at night"],"h1":"This is called zero tolerance.","h2":"Michigan has zero tolerance for drivers under 21: a level of 0.02 percent, or any alcohol from drinking, breaks the law.","p":"Right. Drivers under 21 may not drive with alcohol from drinking."},"es":{"q":"En Michigan, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Nada de alcohol por haber tomado","Hasta 0.05 por ciento","Hasta 0.10 por ciento de noche"],"h1":"Esto se llama tolerancia cero.","h2":"Michigan tiene tolerancia cero para conductores menores de 21 años: un nivel de 0.02 por ciento, o cualquier alcohol por haber tomado, viola la ley.","p":"Correcto. Los menores de 21 no pueden manejar con alcohol por haber tomado."},"zh":{"q":"在 Michigan，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.08%","完全不能有喝酒带来的酒精","最多 0.05%","晚上最多 0.10%"],"h1":"这叫做零容忍。","h2":"Michigan 对 21 岁以下的司机实行零容忍：浓度达到 0.02%，或者体内有任何喝酒带来的酒精，就违法。","p":"对。21 岁以下的司机不能在喝酒后开车。"},"vi":{"q":"Ở Michigan, người lái dưới 21 tuổi được có bao nhiêu cồn trong cơ thể?","o":["Tối đa 0.08 phần trăm","Hoàn toàn không có cồn do uống rượu","Tối đa 0.05 phần trăm","Tối đa 0.10 phần trăm vào ban đêm"],"h1":"Điều này gọi là không khoan nhượng (zero tolerance).","h2":"Michigan không khoan nhượng (zero tolerance) với người lái dưới 21 tuổi: mức 0.02 phần trăm, hoặc bất kỳ lượng cồn nào do uống rượu, là vi phạm luật.","p":"Đúng. Người lái dưới 21 tuổi không được lái xe khi có cồn do uống rượu."},"tl":{"q":"Sa Michigan, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Walang alak mula sa pag-inom kahit kaunti","Hanggang 0.05 porsiyento","Hanggang 0.10 porsiyento sa gabi"],"h1":"Ito ay tinatawag na zero tolerance.","h2":"May zero tolerance ang Michigan para sa mga driver na wala pang 21: ang antas na 0.02 porsiyento, o anumang alak mula sa pag-inom, ay labag sa batas.","p":"Tama. Hindi puwedeng magmaneho ang driver na wala pang 21 na may alak mula sa pag-inom."},"ar":{"q":"في Michigan، كم من الكحول يجوز أن يكون في جسم سائق عمره أقل من 21 سنة؟","o":["حتى 0.08 بالمئة","لا كحول من الشرب أبدًا","حتى 0.05 بالمئة","حتى 0.10 بالمئة في الليل"],"h1":"هذا يُسمّى عدم التسامح المطلق (zero tolerance).","h2":"في Michigan عدم تسامح مطلق (zero tolerance) مع السائقين الذين أعمارهم أقل من 21 سنة: نسبة 0.02 بالمئة، أو أي كحول من الشرب، مخالفة للقانون.","p":"صحيح. السائقون تحت 21 سنة لا يجوز لهم القيادة وفي أجسامهم كحول من الشرب."},"ref":{"doc":"MI","page":14}},{"id":"mi-028","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what kind of car insurance must every vehicle owner carry?","o":["Only collision coverage","Only coverage for the other driver’s car","No insurance is required","No-fault insurance that includes personal injury protection"],"h1":"Michigan is known as a no-fault state.","h2":"Michigan is a no-fault state, so every owner must carry no-fault insurance with personal injury protection, which pays your own medical costs after a crash.","p":"Right. Michigan requires no-fault insurance with personal injury protection."},"es":{"q":"En Michigan, ¿qué tipo de seguro de carro debe tener todo dueño de vehículo?","o":["Solo cobertura de choque","Solo cobertura para el carro del otro conductor","No se requiere seguro","Seguro sin culpa que incluye protección por lesiones personales"],"h1":"Michigan es conocido como un estado sin culpa.","h2":"Michigan es un estado sin culpa, así que todo dueño debe tener seguro sin culpa con protección por lesiones personales, que paga sus propios gastos médicos después de un choque.","p":"Correcto. Michigan exige seguro sin culpa con protección por lesiones personales."},"zh":{"q":"在 Michigan，每位车主都必须买哪种汽车保险？","o":["只买碰撞险","只买赔偿对方汽车的保险","不需要任何保险","包括个人伤害保障的无过失保险"],"h1":"Michigan 被称为无过失州（no-fault state）。","h2":"Michigan 是无过失州，所以每位车主都必须买包括个人伤害保障的无过失保险，它在车祸后支付你自己的医疗费用。","p":"对。Michigan 要求包括个人伤害保障的无过失保险。"},"vi":{"q":"Ở Michigan, mọi chủ xe phải mua loại bảo hiểm xe nào?","o":["Chỉ bảo hiểm va chạm","Chỉ bảo hiểm cho xe của người lái kia","Không cần bảo hiểm","Bảo hiểm không phân lỗi (no-fault) có bảo vệ thương tích cá nhân (personal injury protection)"],"h1":"Michigan được biết là một tiểu bang không phân lỗi (no-fault).","h2":"Michigan là tiểu bang không phân lỗi (no-fault), nên mọi chủ xe phải mua bảo hiểm không phân lỗi có bảo vệ thương tích cá nhân, loại trả chi phí y tế của chính bạn sau tai nạn.","p":"Đúng. Michigan yêu cầu bảo hiểm không phân lỗi có bảo vệ thương tích cá nhân."},"tl":{"q":"Sa Michigan, anong uri ng car insurance ang dapat mayroon ang bawat may-ari ng sasakyan?","o":["Collision coverage lamang","Coverage lamang para sa kotse ng ibang driver","Hindi kailangan ng insurance","No-fault insurance na may kasamang personal injury protection"],"h1":"Kilala ang Michigan bilang isang no-fault state.","h2":"Ang Michigan ay no-fault state, kaya dapat may no-fault insurance na may personal injury protection ang bawat may-ari, na nagbabayad ng sarili mong gastos sa pagpapagamot pagkatapos ng banggaan.","p":"Tama. Hinihingi ng Michigan ang no-fault insurance na may personal injury protection."},"ar":{"q":"في Michigan، ما نوع تأمين السيارة الذي يجب أن يحمله كل مالك مركبة؟","o":["تأمين التصادم فقط","تأمين لسيارة السائق الآخر فقط","لا يُطلب أي تأمين","تأمين بدون تحديد خطأ (no-fault) يشمل حماية الإصابات الشخصية (personal injury protection)"],"h1":"تُعرف Michigan بأنها ولاية بدون تحديد خطأ (no-fault).","h2":"Michigan ولاية بدون تحديد خطأ (no-fault)، لذلك يجب أن يحمل كل مالك تأمين no-fault يشمل حماية الإصابات الشخصية، الذي يدفع تكاليف علاجك أنت بعد الحادث.","p":"صحيح. تطلب Michigan تأمين no-fault يشمل حماية الإصابات الشخصية."},"ref":{"doc":"MI","page":null}},{"id":"mi-029","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, how much space must you leave between your car and a bicycle when you pass it?","o":["1 foot","At least 3 feet","At least 10 feet","One full lane always"],"h1":"It is about the length of a yardstick.","h2":"In Michigan you must leave at least 3 feet of space between your vehicle and a bicyclist when you pass.","p":"Right. Give a bicycle at least 3 feet."},"es":{"q":"En Michigan, ¿cuánto espacio debe dejar entre su carro y una bicicleta al rebasarla?","o":["1 pie","Por lo menos 3 pies","Por lo menos 10 pies","Siempre un carril completo"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Michigan usted debe dejar por lo menos 3 pies de espacio entre su vehículo y un ciclista al rebasarlo.","p":"Correcto. Deje por lo menos 3 pies a una bicicleta."},"zh":{"q":"在 Michigan，超过自行车时，你的车和自行车之间必须留多少空间？","o":["1 英尺","至少 3 英尺","至少 10 英尺","总是留出整整一条车道"],"h1":"大约是一把码尺（yardstick）的长度。","h2":"在 Michigan，超过骑自行车的人时，你的车和骑车人之间必须至少留 3 英尺的空间。","p":"对。给自行车至少留 3 英尺。"},"vi":{"q":"Ở Michigan, khi vượt xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và xe đạp?","o":["1 foot","Ít nhất 3 feet","Ít nhất 10 feet","Luôn luôn một làn đường trọn vẹn"],"h1":"Khoảng bằng chiều dài một cây thước yard (yardstick).","h2":"Ở Michigan, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng cách giữa xe của bạn và người đi xe đạp.","p":"Đúng. Chừa cho xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Michigan, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng bisikleta kapag nilalampasan mo ito?","o":["1 foot","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet","Laging isang buong lane"],"h1":"Halos kasinghaba ito ng isang yardstick.","h2":"Sa Michigan, dapat kang mag-iwan ng hindi bababa sa 3 feet na espasyo sa pagitan ng sasakyan mo at ng nagbibisikleta kapag nilalampasan mo siya.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Michigan، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة عندما تتجاوزها؟","o":["قدم واحد (1 foot)","3 أقدام على الأقل","10 أقدام على الأقل","حارة كاملة دائمًا"],"h1":"إنها تقريبًا بطول مسطرة الياردة (yardstick).","h2":"في Michigan يجب أن تترك مسافة 3 أقدام على الأقل بين مركبتك وراكب الدراجة عندما تتجاوزه.","p":"صحيح. اترك للدراجة 3 أقدام على الأقل."},"ref":{"doc":"MI","page":57}},{"id":"mi-030","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, when does the driver's license of a person under 21 expire?","o":["On their 18th birthday","Exactly one year after it is issued","On their 21st birthday","After eight years"],"h1":"Other drivers usually get four years, but young drivers have a special date.","h2":"In Michigan, a license issued to a driver under 21 expires on the driver's 21st birthday.","p":"Right. Under 21, the license ends on the 21st birthday."},"es":{"q":"En Michigan, ¿cuándo vence la licencia de manejar de una persona menor de 21 años?","o":["En su cumpleaños número 18","Un año exacto después de emitida","En su cumpleaños número 21","Después de ocho años"],"h1":"Los demás conductores suelen tener cuatro años, pero los jóvenes tienen una fecha especial.","h2":"En Michigan, la licencia de un conductor menor de 21 años vence en su cumpleaños número 21.","p":"Correcto. Si es menor de 21, la licencia vence al cumplir 21."},"zh":{"q":"在 Michigan，未满 21 岁的人的驾照什么时候到期？","o":["在他们 18 岁生日那天","发放后正好一年","在他们 21 岁生日那天","八年以后"],"h1":"其他司机通常可以用四年，但年轻司机有一个特别的日期。","h2":"在 Michigan，发给未满 21 岁司机的驾照在司机 21 岁生日那天到期。","p":"对。未满 21 岁，驾照在 21 岁生日那天到期。"},"vi":{"q":"Ở Michigan, bằng lái của người dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật thứ 18 của họ","Đúng một năm sau khi được cấp","Vào sinh nhật thứ 21 của họ","Sau tám năm"],"h1":"Những người lái khác thường được bốn năm, nhưng người lái trẻ có một ngày đặc biệt.","h2":"Ở Michigan, bằng lái cấp cho người lái dưới 21 tuổi hết hạn vào sinh nhật thứ 21 của người lái.","p":"Đúng. Dưới 21 tuổi, bằng lái hết hạn vào sinh nhật thứ 21."},"tl":{"q":"Sa Michigan, kailan mag-e-expire ang driver's license ng taong wala pang 21 taong gulang?","o":["Sa kanilang ika-18 kaarawan","Eksaktong isang taon matapos itong ibigay","Sa kanilang ika-21 kaarawan","Pagkalipas ng walong taon"],"h1":"Karaniwang apat na taon ang ibang driver, pero may espesyal na petsa ang mga batang driver.","h2":"Sa Michigan, ang license na ibinigay sa driver na wala pang 21 taong gulang ay mag-e-expire sa ika-21 kaarawan ng driver.","p":"Tama. Kapag wala pang 21, matatapos ang license sa ika-21 kaarawan."},"ar":{"q":"في Michigan، متى تنتهي رخصة القيادة لشخص عمره أقل من 21 سنة؟","o":["في عيد ميلاده الـ 18","بعد سنة واحدة بالضبط من إصدارها","في عيد ميلاده الـ 21","بعد ثماني سنوات"],"h1":"السائقون الآخرون يحصلون عادةً على أربع سنوات، لكن للسائقين الشباب تاريخ خاص.","h2":"في Michigan، تنتهي الرخصة الصادرة لسائق عمره أقل من 21 سنة في عيد ميلاد السائق الـ 21.","p":"صحيح. إذا كان العمر أقل من 21، تنتهي الرخصة في عيد الميلاد الـ 21."},"ref":{"doc":"MI","page":10}},{"id":"mi-031","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how long do points stay on your driving record?","o":["Two years from the date of conviction","Six months","Ten years","For life"],"h1":"It is less than the seven years most convictions stay on the record.","h2":"In Michigan, points stay on your driving record for two years from the date you are convicted.","p":"Right. Points stay for two years."},"es":{"q":"En Michigan, ¿cuánto tiempo se quedan los puntos en su historial de manejo?","o":["Dos años desde la fecha de la condena","Seis meses","Diez años","Toda la vida"],"h1":"Es menos que los siete años que se quedan la mayoría de las condenas.","h2":"En Michigan, los puntos se quedan en su historial de manejo por dos años desde la fecha de la condena.","p":"Correcto. Los puntos se quedan dos años."},"zh":{"q":"在 Michigan，扣分会在你的驾驶记录上保留多久？","o":["从定罪之日起两年","六个月","十年","终身"],"h1":"它比大多数定罪在记录上保留的七年要短。","h2":"在 Michigan，扣分从你被定罪之日起在你的驾驶记录上保留两年。","p":"对。扣分保留两年。"},"vi":{"q":"Ở Michigan, điểm phạt ở lại trong hồ sơ lái xe của bạn bao lâu?","o":["Hai năm kể từ ngày bị kết tội","Sáu tháng","Mười năm","Suốt đời"],"h1":"Thời gian này ngắn hơn bảy năm mà hầu hết các bản án ở lại trong hồ sơ.","h2":"Ở Michigan, điểm phạt ở lại trong hồ sơ lái xe của bạn trong hai năm kể từ ngày bạn bị kết tội.","p":"Đúng. Điểm phạt ở lại hai năm."},"tl":{"q":"Sa Michigan, gaano katagal mananatili ang points sa iyong driving record?","o":["Dalawang taon mula sa petsa ng conviction","Anim na buwan","Sampung taon","Habambuhay"],"h1":"Mas maikli ito kaysa sa pitong taon na nananatili sa record ang karamihan ng conviction.","h2":"Sa Michigan, mananatili ang points sa iyong driving record nang dalawang taon mula sa petsa na ikaw ay na-convict.","p":"Tama. Mananatili ang points nang dalawang taon."},"ar":{"q":"في Michigan، كم من الوقت تبقى النقاط في سجل قيادتك؟","o":["سنتان من تاريخ الإدانة","ستة أشهر","عشر سنوات","مدى الحياة"],"h1":"إنها أقل من السنوات السبع التي تبقى فيها معظم الإدانات في السجل.","h2":"في Michigan، تبقى النقاط في سجل قيادتك لمدة سنتين من تاريخ إدانتك.","p":"صحيح. تبقى النقاط لمدة سنتين."},"ref":{"doc":"MI","page":13}},{"id":"mi-032","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how long is a temporary instruction permit (TIP) valid?","o":["30 days","90 days","180 days","Two years"],"h1":"It lasts about half a year.","h2":"In Michigan, a temporary instruction permit is valid for 180 days.","p":"Right. A TIP is good for 180 days."},"es":{"q":"En Michigan, ¿por cuánto tiempo es válido un permiso temporal de instrucción (TIP)?","o":["30 días","90 días","180 días","Dos años"],"h1":"Dura más o menos medio año.","h2":"En Michigan, un permiso temporal de instrucción es válido por 180 días.","p":"Correcto. Un TIP es válido por 180 días."},"zh":{"q":"在 Michigan，临时学习许可证（TIP）的有效期是多久？","o":["30 天","90 天","180 天","两年"],"h1":"大约半年。","h2":"在 Michigan，临时学习许可证的有效期是 180 天。","p":"对。TIP 有效 180 天。"},"vi":{"q":"Ở Michigan, giấy phép học lái tạm thời (TIP) có hiệu lực trong bao lâu?","o":["30 ngày","90 ngày","180 ngày","Hai năm"],"h1":"Khoảng nửa năm.","h2":"Ở Michigan, giấy phép học lái tạm thời có hiệu lực trong 180 ngày.","p":"Đúng. TIP có hiệu lực 180 ngày."},"tl":{"q":"Sa Michigan, gaano katagal valid ang temporary instruction permit (TIP)?","o":["30 araw","90 araw","180 araw","Dalawang taon"],"h1":"Mga kalahating taon ito.","h2":"Sa Michigan, valid ang temporary instruction permit nang 180 araw.","p":"Tama. Valid ang TIP nang 180 araw."},"ar":{"q":"في Michigan، ما مدة صلاحية تصريح التعليم المؤقت (TIP)؟","o":["30 يومًا","90 يومًا","180 يومًا","سنتان"],"h1":"مدته حوالي نصف سنة.","h2":"في Michigan، تصريح التعليم المؤقت صالح لمدة 180 يومًا.","p":"صحيح. تصريح TIP صالح لمدة 180 يومًا."},"ref":{"doc":"MI","page":7}},{"id":"mi-033","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, an adult has a temporary instruction permit (TIP). How long must they practice before the driving skills test?","o":["At least 30 days","At least 7 days","At least 6 months","At least one year"],"h1":"It is about one month.","h2":"In Michigan, a driver with a TIP must practice for at least 30 days before taking the driving skills test.","p":"Right. At least 30 days of practice come first."},"es":{"q":"En Michigan, un adulto tiene un permiso temporal de instrucción (TIP). ¿Cuánto tiempo debe practicar antes del examen de manejo?","o":["Por lo menos 30 días","Por lo menos 7 días","Por lo menos 6 meses","Por lo menos un año"],"h1":"Es más o menos un mes.","h2":"En Michigan, un conductor con TIP debe practicar por lo menos 30 días antes de tomar el examen de manejo.","p":"Correcto. Primero se practican por lo menos 30 días."},"zh":{"q":"在 Michigan，一个成年人有临时学习许可证（TIP）。他在参加路考之前必须练习多久？","o":["至少 30 天","至少 7 天","至少 6 个月","至少一年"],"h1":"大约一个月。","h2":"在 Michigan，有 TIP 的司机在参加路考之前必须至少练习 30 天。","p":"对。先要练习至少 30 天。"},"vi":{"q":"Ở Michigan, một người lớn có giấy phép học lái tạm thời (TIP). Họ phải tập lái bao lâu trước khi thi kỹ năng lái xe?","o":["Ít nhất 30 ngày","Ít nhất 7 ngày","Ít nhất 6 tháng","Ít nhất một năm"],"h1":"Khoảng một tháng.","h2":"Ở Michigan, người lái có TIP phải tập lái ít nhất 30 ngày trước khi thi kỹ năng lái xe.","p":"Đúng. Phải tập lái ít nhất 30 ngày trước."},"tl":{"q":"Sa Michigan, may temporary instruction permit (TIP) ang isang adult. Gaano katagal siya dapat mag-practice bago ang driving skills test?","o":["Hindi bababa sa 30 araw","Hindi bababa sa 7 araw","Hindi bababa sa 6 na buwan","Hindi bababa sa isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Michigan, ang driver na may TIP ay dapat mag-practice nang hindi bababa sa 30 araw bago kumuha ng driving skills test.","p":"Tama. Kailangan muna ng hindi bababa sa 30 araw na practice."},"ar":{"q":"في Michigan، شخص بالغ معه تصريح تعليم مؤقت (TIP). كم يجب أن يتدرّب قبل اختبار مهارات القيادة؟","o":["30 يومًا على الأقل","7 أيام على الأقل","6 أشهر على الأقل","سنة واحدة على الأقل"],"h1":"المدة حوالي شهر واحد.","h2":"في Michigan، يجب على السائق الذي معه TIP أن يتدرّب 30 يومًا على الأقل قبل أن يقدّم اختبار مهارات القيادة.","p":"صحيح. يجب التدرّب 30 يومًا على الأقل أولًا."},"ref":{"doc":"MI","page":7}},{"id":"mi-034","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many hours of supervised driving must a teen log before starting Segment 2 of driver education?","o":["10 hours","30 hours","50 hours","100 hours"],"h1":"It is less than the total needed for the driving skills test.","h2":"In Michigan, a teen must log at least 30 hours of supervised driving, including 2 at night, before starting Segment 2.","p":"Right. Segment 2 needs a log of at least 30 hours."},"es":{"q":"En Michigan, ¿cuántas horas de manejo supervisado debe anotar un adolescente antes de empezar el Segmento 2 de educación vial?","o":["10 horas","30 horas","50 horas","100 horas"],"h1":"Es menos que el total que se necesita para el examen de manejo.","h2":"En Michigan, un adolescente debe anotar por lo menos 30 horas de manejo supervisado, incluidas 2 de noche, antes de empezar el Segmento 2.","p":"Correcto. El Segmento 2 pide un registro de por lo menos 30 horas."},"zh":{"q":"在 Michigan，青少年在开始驾驶教育第二部分（Segment 2）之前，必须记录多少小时有人陪同的驾驶？","o":["10 小时","30 小时","50 小时","100 小时"],"h1":"比参加路考所需的总时数少。","h2":"在 Michigan，青少年在开始 Segment 2 之前，必须记录至少 30 小时有人陪同的驾驶，其中 2 小时在夜间。","p":"对。Segment 2 需要至少 30 小时的驾驶记录。"},"vi":{"q":"Ở Michigan, thanh thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi bắt đầu Phần 2 (Segment 2) của khóa học lái xe?","o":["10 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Ít hơn tổng số giờ cần có để thi kỹ năng lái xe.","h2":"Ở Michigan, thanh thiếu niên phải ghi lại ít nhất 30 giờ lái xe có người giám sát, trong đó có 2 giờ vào ban đêm, trước khi bắt đầu Segment 2.","p":"Đúng. Segment 2 cần ghi lại ít nhất 30 giờ."},"tl":{"q":"Sa Michigan, ilang oras ng supervised driving ang dapat itala ng isang teen bago magsimula ng Segment 2 ng driver education?","o":["10 oras","30 oras","50 oras","100 oras"],"h1":"Mas kaunti ito kaysa sa kabuuang kailangan para sa driving skills test.","h2":"Sa Michigan, dapat magtala ang isang teen ng hindi bababa sa 30 oras ng supervised driving, kasama ang 2 sa gabi, bago magsimula ng Segment 2.","p":"Tama. Kailangan ng Segment 2 ang tala na hindi bababa sa 30 oras."},"ar":{"q":"في Michigan، كم ساعة من القيادة تحت الإشراف يجب أن يسجّلها المراهق قبل أن يبدأ الجزء 2 (Segment 2) من تعليم القيادة؟","o":["10 ساعات","30 ساعة","50 ساعة","100 ساعة"],"h1":"هي أقل من المجموع المطلوب لاختبار مهارات القيادة.","h2":"في Michigan، يجب على المراهق أن يسجّل 30 ساعة على الأقل من القيادة تحت الإشراف، منها 2 في الليل، قبل أن يبدأ Segment 2.","p":"صحيح. يحتاج Segment 2 إلى سجلّ من 30 ساعة على الأقل."},"ref":{"doc":"MI","page":5}},{"id":"mi-035","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how long are new drivers placed on probation?","o":["Six months","One year","Until age 18","At least three years"],"h1":"It lasts longer than the graduated license levels.","h2":"In Michigan, new drivers, including teens, are on probation for at least three years.","p":"Right. Probation lasts at least three years."},"es":{"q":"En Michigan, ¿por cuánto tiempo quedan a prueba (probation) los conductores nuevos?","o":["Seis meses","Un año","Hasta los 18 años","Por lo menos tres años"],"h1":"Dura más que los niveles de la licencia gradual.","h2":"En Michigan, los conductores nuevos, incluidos los adolescentes, quedan a prueba por lo menos tres años.","p":"Correcto. El periodo de prueba dura por lo menos tres años."},"zh":{"q":"在 Michigan，新司机的试用期（probation）有多长？","o":["六个月","一年","到 18 岁","至少三年"],"h1":"比分级驾照的各个阶段都长。","h2":"在 Michigan，新司机（包括青少年）的试用期至少三年。","p":"对。试用期至少三年。"},"vi":{"q":"Ở Michigan, người mới lái bị đặt trong thời gian thử thách (probation) bao lâu?","o":["Sáu tháng","Một năm","Đến 18 tuổi","Ít nhất ba năm"],"h1":"Thời gian này dài hơn các cấp của bằng lái theo từng cấp.","h2":"Ở Michigan, người mới lái, kể cả thanh thiếu niên, ở trong thời gian thử thách ít nhất ba năm.","p":"Đúng. Thời gian thử thách kéo dài ít nhất ba năm."},"tl":{"q":"Sa Michigan, gaano katagal naka-probation ang mga bagong driver?","o":["Anim na buwan","Isang taon","Hanggang edad 18","Hindi bababa sa tatlong taon"],"h1":"Mas matagal ito kaysa sa mga level ng graduated license.","h2":"Sa Michigan, naka-probation ang mga bagong driver, kasama ang mga teen, nang hindi bababa sa tatlong taon.","p":"Tama. Tumatagal ang probation nang hindi bababa sa tatlong taon."},"ar":{"q":"في Michigan، كم مدة فترة الاختبار (probation) للسائقين الجدد؟","o":["ستة أشهر","سنة واحدة","حتى عمر 18 سنة","ثلاث سنوات على الأقل"],"h1":"هي أطول من مستويات الرخصة المتدرّجة.","h2":"في Michigan، يكون السائقون الجدد، ومنهم المراهقون، في فترة اختبار لمدة ثلاث سنوات على الأقل.","p":"صحيح. فترة الاختبار ثلاث سنوات على الأقل."},"ref":{"doc":"MI","page":9}},{"id":"mi-036","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how often must you renew your driver's license in person at a Secretary of State office?","o":["Every 4 years","Every 12 years","Every 20 years","Only once, at age 65"],"h1":"You can renew online or by mail in between, but not forever.","h2":"In Michigan, you must renew your license at a Secretary of State office every 12 years, for a vision check and a new photo.","p":"Right. Every 12 years you go in person."},"es":{"q":"En Michigan, ¿cada cuánto debe renovar su licencia en persona en una oficina del Secretario de Estado?","o":["Cada 4 años","Cada 12 años","Cada 20 años","Solo una vez, a los 65 años"],"h1":"Entre una visita y otra puede renovar por internet o por correo, pero no para siempre.","h2":"En Michigan, debe renovar su licencia en una oficina del Secretario de Estado cada 12 años, para un examen de la vista y una foto nueva.","p":"Correcto. Cada 12 años debe ir en persona."},"zh":{"q":"在 Michigan，你必须多久一次亲自去州务卿办公室（Secretary of State office）更新驾照？","o":["每 4 年","每 12 年","每 20 年","只有一次，在 65 岁时"],"h1":"中间可以在网上或邮寄更新，但不能一直这样。","h2":"在 Michigan，你必须每 12 年去州务卿办公室更新一次驾照，检查视力并拍新照片。","p":"对。每 12 年要亲自去一次。"},"vi":{"q":"Ở Michigan, bao lâu bạn phải đến văn phòng Secretary of State để gia hạn bằng lái trực tiếp một lần?","o":["Mỗi 4 năm","Mỗi 12 năm","Mỗi 20 năm","Chỉ một lần, khi 65 tuổi"],"h1":"Ở giữa bạn có thể gia hạn trên mạng hoặc qua thư, nhưng không phải mãi mãi.","h2":"Ở Michigan, bạn phải gia hạn bằng lái tại văn phòng Secretary of State mỗi 12 năm, để kiểm tra mắt và chụp ảnh mới.","p":"Đúng. Mỗi 12 năm bạn phải đến trực tiếp."},"tl":{"q":"Sa Michigan, gaano kadalas mo dapat i-renew nang personal ang iyong driver's license sa Secretary of State office?","o":["Tuwing 4 na taon","Tuwing 12 taon","Tuwing 20 taon","Isang beses lang, sa edad 65"],"h1":"Puwede kang mag-renew online o sa koreo sa pagitan, pero hindi habambuhay.","h2":"Sa Michigan, dapat mong i-renew ang iyong lisensya sa Secretary of State office tuwing 12 taon, para sa vision check at bagong litrato.","p":"Tama. Tuwing 12 taon, pupunta ka nang personal."},"ar":{"q":"في Michigan، كل كم سنة يجب أن تجدّد رخصة القيادة بنفسك في مكتب Secretary of State؟","o":["كل 4 سنوات","كل 12 سنة","كل 20 سنة","مرة واحدة فقط، في عمر 65 سنة"],"h1":"يمكنك التجديد عبر الإنترنت أو بالبريد بين المرّات، لكن ليس إلى الأبد.","h2":"في Michigan، يجب أن تجدّد رخصتك في مكتب Secretary of State كل 12 سنة، لفحص النظر وصورة جديدة.","p":"صحيح. كل 12 سنة تذهب بنفسك."},"ref":{"doc":"MI","page":10}},{"id":"mi-037","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many points within two years lead to a driver assessment reexamination?","o":["12 or more points","4 or more points","6 or more points","20 or more points"],"h1":"It is twice as many as six.","h2":"In Michigan, a driver with 12 or more points within two years must go to a driver assessment reexamination.","p":"Right. Twelve points in two years means a reexamination."},"es":{"q":"En Michigan, ¿cuántos puntos en dos años llevan a una reevaluación del conductor?","o":["12 puntos o más","4 puntos o más","6 puntos o más","20 puntos o más"],"h1":"Es el doble de seis.","h2":"En Michigan, un conductor con 12 puntos o más en dos años debe ir a una reevaluación del conductor.","p":"Correcto. Doce puntos en dos años llevan a una reevaluación."},"zh":{"q":"在 Michigan，两年内被扣多少分会被要求参加司机评估复查（driver assessment reexamination）？","o":["12 分或更多","4 分或更多","6 分或更多","20 分或更多"],"h1":"是六的两倍。","h2":"在 Michigan，两年内被扣 12 分或更多的司机必须参加司机评估复查。","p":"对。两年内 12 分就要复查。"},"vi":{"q":"Ở Michigan, bao nhiêu điểm phạt trong hai năm sẽ dẫn đến kỳ tái kiểm tra đánh giá người lái (driver assessment reexamination)?","o":["12 điểm trở lên","4 điểm trở lên","6 điểm trở lên","20 điểm trở lên"],"h1":"Gấp đôi số sáu.","h2":"Ở Michigan, người lái có 12 điểm phạt trở lên trong hai năm phải đi tái kiểm tra đánh giá người lái.","p":"Đúng. 12 điểm trong hai năm thì phải tái kiểm tra."},"tl":{"q":"Sa Michigan, ilang points sa loob ng dalawang taon ang hahantong sa driver assessment reexamination?","o":["12 points o higit pa","4 points o higit pa","6 points o higit pa","20 points o higit pa"],"h1":"Doble ito ng anim.","h2":"Sa Michigan, ang driver na may 12 points o higit pa sa loob ng dalawang taon ay dapat pumunta sa driver assessment reexamination.","p":"Tama. 12 points sa dalawang taon ay nangangahulugan ng reexamination."},"ar":{"q":"في Michigan، كم نقطة خلال سنتين تؤدّي إلى إعادة فحص تقييم السائق (driver assessment reexamination)؟","o":["12 نقطة أو أكثر","4 نقاط أو أكثر","6 نقاط أو أكثر","20 نقطة أو أكثر"],"h1":"هي ضعف الستة.","h2":"في Michigan، يجب على السائق الذي عنده 12 نقطة أو أكثر خلال سنتين أن يذهب إلى إعادة فحص تقييم السائق.","p":"صحيح. 12 نقطة في سنتين تعني إعادة فحص."},"ref":{"doc":"MI","page":13}},{"id":"mi-038","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many points go on your record if you refuse a chemical alcohol test?","o":["Two points","Three points","Four points","Six points"],"h1":"It is the highest point level in the Michigan list.","h2":"In Michigan, refusing a chemical alcohol test puts six points on your driving record.","p":"Right. A refusal costs six points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial si se niega a una prueba química de alcohol?","o":["Dos puntos","Tres puntos","Cuatro puntos","Seis puntos"],"h1":"Es el nivel de puntos más alto de la lista de Michigan.","h2":"En Michigan, negarse a una prueba química de alcohol pone seis puntos en su historial de manejo.","p":"Correcto. Negarse cuesta seis puntos."},"zh":{"q":"在 Michigan，如果你拒绝做化学酒精测试，你的记录上会被记多少分？","o":["两分","三分","四分","六分"],"h1":"是 Michigan 扣分表里最高的分数。","h2":"在 Michigan，拒绝做化学酒精测试会在你的驾驶记录上记六分。","p":"对。拒绝测试要记六分。"},"vi":{"q":"Ở Michigan, nếu bạn từ chối thử nghiệm hóa học về nồng độ cồn, hồ sơ của bạn bị ghi bao nhiêu điểm phạt?","o":["Hai điểm","Ba điểm","Bốn điểm","Sáu điểm"],"h1":"Đó là mức điểm cao nhất trong danh sách của Michigan.","h2":"Ở Michigan, từ chối thử nghiệm hóa học về nồng độ cồn sẽ ghi sáu điểm phạt vào hồ sơ lái xe của bạn.","p":"Đúng. Từ chối thử nghiệm bị sáu điểm."},"tl":{"q":"Sa Michigan, ilang points ang mapupunta sa iyong record kung tatanggi ka sa chemical alcohol test?","o":["Dalawang points","Tatlong points","Apat na points","Anim na points"],"h1":"Ito ang pinakamataas na antas ng points sa listahan ng Michigan.","h2":"Sa Michigan, ang pagtanggi sa chemical alcohol test ay naglalagay ng anim na points sa iyong driving record.","p":"Tama. Anim na points ang kapalit ng pagtanggi."},"ar":{"q":"في Michigan، كم نقطة تُسجَّل في سجلّك إذا رفضت اختبار الكحول الكيميائي؟","o":["نقطتان","ثلاث نقاط","أربع نقاط","ست نقاط"],"h1":"هو أعلى مستوى للنقاط في قائمة Michigan.","h2":"في Michigan، رفض اختبار الكحول الكيميائي يضع ست نقاط في سجل قيادتك.","p":"صحيح. الرفض يكلّفك ست نقاط."},"ref":{"doc":"MI","page":14}},{"id":"mi-039","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, what happens to the fine for a moving violation in a work zone?","o":["It stays the same","It is cut in half","It is doubled","It becomes a warning only"],"h1":"Work zones protect workers, so the penalty goes up.","h2":"In Michigan, fines for all moving violations are doubled in work zones.","p":"Right. Work zone fines are doubled."},"es":{"q":"En Michigan, ¿qué pasa con la multa por una infracción de tránsito en una zona de obras?","o":["Sigue igual","Se reduce a la mitad","Se duplica","Solo se da una advertencia"],"h1":"Las zonas de obras protegen a los trabajadores, así que la sanción sube.","h2":"En Michigan, las multas por todas las infracciones de tránsito se duplican en las zonas de obras.","p":"Correcto. En zonas de obras las multas se duplican."},"zh":{"q":"在 Michigan，在施工区里违反行车规则的罚款会怎样？","o":["保持不变","减半","加倍","只给警告"],"h1":"施工区是为了保护工人，所以处罚会提高。","h2":"在 Michigan，在施工区里所有行车违规的罚款都会加倍。","p":"对。施工区的罚款加倍。"},"vi":{"q":"Ở Michigan, tiền phạt cho lỗi khi đang lái xe trong khu vực công trường sẽ thế nào?","o":["Giữ nguyên","Giảm một nửa","Tăng gấp đôi","Chỉ bị cảnh cáo"],"h1":"Khu vực công trường bảo vệ công nhân, nên hình phạt tăng lên.","h2":"Ở Michigan, tiền phạt cho mọi lỗi khi đang lái xe đều tăng gấp đôi trong khu vực công trường.","p":"Đúng. Tiền phạt trong khu vực công trường tăng gấp đôi."},"tl":{"q":"Sa Michigan, ano ang nangyayari sa multa para sa moving violation sa work zone?","o":["Pareho pa rin","Nababawasan ng kalahati","Nadodoble","Babala lang"],"h1":"Pinoprotektahan ng work zone ang mga manggagawa, kaya tumataas ang parusa.","h2":"Sa Michigan, nadodoble ang multa para sa lahat ng moving violation sa work zone.","p":"Tama. Doble ang multa sa work zone."},"ar":{"q":"في Michigan، ماذا يحدث لغرامة مخالفة القيادة في منطقة أعمال الطرق؟","o":["تبقى كما هي","تنقص إلى النصف","تتضاعف","تصبح إنذارًا فقط"],"h1":"مناطق الأعمال تحمي العمّال، لذلك ترتفع العقوبة.","h2":"في Michigan، تتضاعف غرامات كل مخالفات القيادة في مناطق أعمال الطرق.","p":"صحيح. غرامات مناطق الأعمال تتضاعف."},"ref":{"doc":"MI","page":27}},{"id":"mi-040","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, what is the fine for a first offense of using a hand-held phone while driving?","o":["$100","$25","$500","$1,000"],"h1":"A second offense costs $250, so the first is less than that.","h2":"In Michigan, the fine for a first hand-held phone offense is $100, and later offenses cost $250.","p":"Right. The first offense is $100."},"es":{"q":"En Michigan, ¿cuál es la multa por una primera falta por usar un teléfono en la mano mientras maneja?","o":["$100","$25","$500","$1,000"],"h1":"Una segunda falta cuesta $250, así que la primera es menos.","h2":"En Michigan, la multa por una primera falta por usar el teléfono en la mano es de $100, y las siguientes cuestan $250.","p":"Correcto. La primera falta cuesta $100."},"zh":{"q":"在 Michigan，开车时第一次用手拿着手机，罚款是多少？","o":["$100","$25","$500","$1,000"],"h1":"第二次要罚 $250，所以第一次比这个少。","h2":"在 Michigan，第一次用手拿手机的罚款是 $100，以后再犯罚 $250。","p":"对。第一次罚 $100。"},"vi":{"q":"Ở Michigan, tiền phạt cho lần đầu cầm điện thoại trên tay khi lái xe là bao nhiêu?","o":["$100","$25","$500","$1,000"],"h1":"Lần thứ hai bị phạt $250, nên lần đầu ít hơn số đó.","h2":"Ở Michigan, tiền phạt cho lần đầu cầm điện thoại trên tay là $100, và các lần sau là $250.","p":"Đúng. Lần đầu bị phạt $100."},"tl":{"q":"Sa Michigan, magkano ang multa sa unang paglabag sa paggamit ng hawak na cellphone habang nagmamaneho?","o":["$100","$25","$500","$1,000"],"h1":"$250 ang multa sa ikalawang paglabag, kaya mas mababa roon ang una.","h2":"Sa Michigan, $100 ang multa sa unang paglabag sa paggamit ng hawak na cellphone, at $250 ang mga susunod.","p":"Tama. $100 ang unang paglabag."},"ar":{"q":"في Michigan، ما غرامة المخالفة الأولى لاستعمال الهاتف باليد أثناء القيادة؟","o":["$100","$25","$500","$1,000"],"h1":"المخالفة الثانية غرامتها $250، فالأولى أقل من ذلك.","h2":"في Michigan، غرامة المخالفة الأولى لاستعمال الهاتف باليد هي $100، والمخالفات التالية غرامتها $250.","p":"صحيح. المخالفة الأولى غرامتها $100."},"ref":{"doc":"MI","page":23}},{"id":"mi-041","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, which passengers must wear a seat belt in every seat, including the back seat?","o":["Only passengers under 8","Only passengers over 65","All passengers under 16","Only the driver's own children"],"h1":"Adults must buckle up in the front; younger riders must buckle up everywhere.","h2":"In Michigan, all passengers under age 16 must be buckled up in every seating position.","p":"Right. Everyone under 16 buckles up in any seat."},"es":{"q":"En Michigan, ¿qué pasajeros deben usar el cinturón de seguridad en cualquier asiento, incluso atrás?","o":["Solo los menores de 8 años","Solo los mayores de 65 años","Todos los menores de 16 años","Solo los hijos del conductor"],"h1":"Los adultos deben abrocharse adelante; los más jóvenes, en todos los asientos.","h2":"En Michigan, todos los pasajeros menores de 16 años deben llevar el cinturón abrochado en cualquier asiento.","p":"Correcto. Todo menor de 16 se abrocha en cualquier asiento."},"zh":{"q":"在 Michigan，哪些乘客在每个座位上（包括后座）都必须系安全带？","o":["只有未满 8 岁的乘客","只有超过 65 岁的乘客","所有未满 16 岁的乘客","只有司机自己的孩子"],"h1":"成年人在前座必须系安全带；年纪小的乘客坐哪里都必须系。","h2":"在 Michigan，所有未满 16 岁的乘客在每个座位上都必须系好安全带。","p":"对。未满 16 岁的人坐任何座位都要系安全带。"},"vi":{"q":"Ở Michigan, hành khách nào phải thắt dây an toàn ở mọi ghế, kể cả ghế sau?","o":["Chỉ hành khách dưới 8 tuổi","Chỉ hành khách trên 65 tuổi","Tất cả hành khách dưới 16 tuổi","Chỉ con của người lái"],"h1":"Người lớn phải thắt dây ở ghế trước; người nhỏ tuổi hơn phải thắt dây ở mọi chỗ.","h2":"Ở Michigan, tất cả hành khách dưới 16 tuổi phải thắt dây an toàn ở mọi chỗ ngồi.","p":"Đúng. Mọi người dưới 16 tuổi đều thắt dây ở bất kỳ ghế nào."},"tl":{"q":"Sa Michigan, aling mga pasahero ang dapat magsuot ng seat belt sa bawat upuan, kasama ang upuan sa likod?","o":["Mga pasaherong wala pang 8 taon lang","Mga pasaherong lampas 65 lang","Lahat ng pasaherong wala pang 16","Mga sariling anak lang ng driver"],"h1":"Dapat mag-seat belt ang mga adult sa harap; ang mas bata ay dapat mag-seat belt kahit saan.","h2":"Sa Michigan, lahat ng pasaherong wala pang 16 taong gulang ay dapat naka-seat belt sa bawat upuan.","p":"Tama. Lahat ng wala pang 16 ay nagse-seat belt sa kahit anong upuan."},"ar":{"q":"في Michigan، أيّ الركاب يجب أن يربطوا حزام الأمان في كل مقعد، ومنها المقعد الخلفي؟","o":["الركاب الأصغر من 8 سنوات فقط","الركاب الأكبر من 65 سنة فقط","كل الركاب الأصغر من 16 سنة","أولاد السائق فقط"],"h1":"البالغون يجب أن يربطوا الحزام في الأمام؛ والركاب الأصغر يجب أن يربطوه في كل مكان.","h2":"في Michigan، يجب على كل الركاب الأصغر من 16 سنة أن يربطوا حزام الأمان في كل مقعد.","p":"صحيح. كل من عمره أقل من 16 سنة يربط الحزام في أي مقعد."},"ref":{"doc":"MI","page":25}},{"id":"mi-042","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, until when must a child ride in a car seat or booster seat?","o":["Until age 4 or 40 pounds","Until age 8 or 4 feet 9 inches tall","Until age 12 or 5 feet tall","Until the child can sit up alone"],"h1":"There is an age limit and a height limit; whichever comes first ends it.","h2":"In Michigan, a child must ride in a car seat or booster seat until age 8 or until 4 feet 9 inches tall, whichever comes first.","p":"Right. Age 8 or 4 feet 9 inches, whichever comes first."},"es":{"q":"En Michigan, ¿hasta cuándo debe ir un niño en un asiento de seguridad o asiento elevado (booster)?","o":["Hasta los 4 años o 40 libras","Hasta los 8 años o 4 pies 9 pulgadas de estatura","Hasta los 12 años o 5 pies de estatura","Hasta que pueda sentarse solo"],"h1":"Hay un límite de edad y uno de estatura; lo que llegue primero.","h2":"En Michigan, un niño debe ir en un asiento de seguridad o elevado hasta los 8 años o hasta medir 4 pies 9 pulgadas, lo que ocurra primero.","p":"Correcto. Hasta los 8 años o 4 pies 9 pulgadas, lo que llegue primero."},"zh":{"q":"在 Michigan，孩子必须坐儿童安全座椅或增高座椅到什么时候？","o":["到 4 岁或 40 磅","到 8 岁或身高 4 英尺 9 英寸","到 12 岁或身高 5 英尺","到孩子能自己坐起来"],"h1":"有年龄限制和身高限制；先达到哪一个就结束。","h2":"在 Michigan，孩子必须坐儿童安全座椅或增高座椅，直到 8 岁或身高 4 英尺 9 英寸，以先到者为准。","p":"对。8 岁或 4 英尺 9 英寸，以先到者为准。"},"vi":{"q":"Ở Michigan, trẻ em phải ngồi ghế an toàn hoặc ghế nâng (booster seat) cho đến khi nào?","o":["Đến 4 tuổi hoặc 40 pound","Đến 8 tuổi hoặc cao 4 feet 9 inch","Đến 12 tuổi hoặc cao 5 feet","Đến khi trẻ tự ngồi được"],"h1":"Có giới hạn tuổi và giới hạn chiều cao; điều nào đến trước thì kết thúc.","h2":"Ở Michigan, trẻ em phải ngồi ghế an toàn hoặc ghế nâng cho đến 8 tuổi hoặc cao 4 feet 9 inch, tùy điều nào đến trước.","p":"Đúng. 8 tuổi hoặc 4 feet 9 inch, tùy điều nào đến trước."},"tl":{"q":"Sa Michigan, hanggang kailan dapat nakaupo ang bata sa car seat o booster seat?","o":["Hanggang edad 4 o 40 pounds","Hanggang edad 8 o 4 feet 9 inches ang taas","Hanggang edad 12 o 5 feet ang taas","Hanggang kaya nang umupo ng bata nang mag-isa"],"h1":"May limitasyon sa edad at sa taas; kung alin ang mauna, doon ito natatapos.","h2":"Sa Michigan, dapat nakaupo ang bata sa car seat o booster seat hanggang edad 8 o hanggang 4 feet 9 inches ang taas, kung alin ang mauna.","p":"Tama. Edad 8 o 4 feet 9 inches, kung alin ang mauna."},"ar":{"q":"في Michigan، حتى متى يجب أن يجلس الطفل في مقعد سيارة للأطفال أو مقعد رافع (booster seat)؟","o":["حتى عمر 4 سنوات أو 40 رطلًا","حتى عمر 8 سنوات أو طول 4 أقدام و9 بوصات","حتى عمر 12 سنة أو طول 5 أقدام","حتى يستطيع الطفل الجلوس وحده"],"h1":"هناك حد للعمر وحد للطول؛ أيّهما يأتي أولًا ينهي القاعدة.","h2":"في Michigan، يجب أن يجلس الطفل في مقعد سيارة للأطفال أو مقعد رافع حتى عمر 8 سنوات أو حتى طول 4 أقدام و9 بوصات، أيّهما يأتي أولًا.","p":"صحيح. عمر 8 سنوات أو 4 أقدام و9 بوصات، أيّهما يأتي أولًا."},"ref":{"doc":"MI","page":25}},{"id":"mi-043","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, when may a person under 18 not ride in the open bed of a pickup truck?","o":["Only on freeways","Only at night","Only when the truck is parked","When the truck goes faster than 15 mph"],"h1":"The rule is about the truck's speed.","h2":"In Michigan, a person under 18 may not ride in the open bed of a pickup truck going more than 15 mph, with a few work and parade exceptions.","p":"Right. Above 15 mph, no riders under 18 in the open bed."},"es":{"q":"En Michigan, ¿cuándo no puede una persona menor de 18 años ir en la caja abierta de una camioneta pickup?","o":["Solo en autopistas","Solo de noche","Solo cuando la camioneta está estacionada","Cuando la camioneta va a más de 15 mph"],"h1":"La regla tiene que ver con la velocidad de la camioneta.","h2":"En Michigan, una persona menor de 18 años no puede ir en la caja abierta de una pickup que va a más de 15 mph, salvo algunas excepciones de trabajo y desfiles.","p":"Correcto. A más de 15 mph, ningún menor de 18 en la caja abierta."},"zh":{"q":"在 Michigan，未满 18 岁的人在什么情况下不可以坐在皮卡车开放的后车斗里？","o":["只在高速公路上","只在晚上","只在车停着的时候","车速超过 15 英里/小时的时候"],"h1":"这条规定和车速有关。","h2":"在 Michigan，皮卡车车速超过 15 英里/小时时，未满 18 岁的人不可以坐在开放的后车斗里，工作和游行有少数例外。","p":"对。超过 15 英里/小时，未满 18 岁的人不能坐在后车斗里。"},"vi":{"q":"Ở Michigan, khi nào người dưới 18 tuổi không được ngồi ở thùng sau để trống của xe bán tải (pickup)?","o":["Chỉ trên xa lộ cao tốc","Chỉ vào ban đêm","Chỉ khi xe đang đậu","Khi xe chạy nhanh hơn 15 mph"],"h1":"Quy định này liên quan đến tốc độ của xe.","h2":"Ở Michigan, người dưới 18 tuổi không được ngồi ở thùng sau để trống của xe bán tải đang chạy nhanh hơn 15 mph, trừ một vài trường hợp khi làm việc hoặc diễu hành.","p":"Đúng. Trên 15 mph, người dưới 18 tuổi không được ngồi ở thùng sau."},"tl":{"q":"Sa Michigan, kailan hindi puwedeng sumakay ang taong wala pang 18 sa bukas na likod (open bed) ng pickup truck?","o":["Sa freeway lang","Sa gabi lang","Kapag nakaparada lang ang truck","Kapag mas mabilis sa 15 mph ang takbo ng truck"],"h1":"Tungkol sa bilis ng truck ang patakaran.","h2":"Sa Michigan, hindi puwedeng sumakay ang taong wala pang 18 sa bukas na likod ng pickup truck na tumatakbo nang mas mabilis sa 15 mph, maliban sa ilang kaso sa trabaho at parada.","p":"Tama. Lampas 15 mph, bawal ang sakay na wala pang 18 sa bukas na likod."},"ar":{"q":"في Michigan، متى لا يجوز لشخص عمره أقل من 18 سنة أن يركب في الصندوق الخلفي المكشوف لشاحنة بيك أب (pickup)؟","o":["على الطرق السريعة فقط","في الليل فقط","عندما تكون الشاحنة متوقّفة فقط","عندما تسير الشاحنة أسرع من 15 mph"],"h1":"القاعدة تتعلّق بسرعة الشاحنة.","h2":"في Michigan، لا يجوز لشخص عمره أقل من 18 سنة أن يركب في الصندوق الخلفي المكشوف لشاحنة بيك أب تسير أسرع من 15 mph، مع بعض الاستثناءات للعمل والمواكب.","p":"صحيح. فوق 15 mph، لا يركب من هم أقل من 18 سنة في الصندوق المكشوف."},"ref":{"doc":"MI","page":25}},{"id":"mi-044","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how far behind a moving emergency vehicle with lights and siren on must you stay?","o":["At least 100 feet","At least 500 feet","At least 50 feet","At least one mile"],"h1":"It is more than the length of a football field.","h2":"In Michigan, you must stay at least 500 feet behind a moving emergency vehicle that has its warning lights and siren on.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Michigan, ¿a qué distancia debe mantenerse detrás de un vehículo de emergencia en movimiento con luces y sirena encendidas?","o":["Por lo menos 100 pies","Por lo menos 500 pies","Por lo menos 50 pies","Por lo menos una milla"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Michigan, debe mantenerse por lo menos a 500 pies detrás de un vehículo de emergencia en movimiento con luces de advertencia y sirena encendidas.","p":"Correcto. Manténgase por lo menos a 500 pies."},"zh":{"q":"在 Michigan，跟在开着警灯和警笛、正在行驶的急救车辆后面，你必须保持多远？","o":["至少 100 英尺","至少 500 英尺","至少 50 英尺","至少一英里"],"h1":"比一个美式足球场还长。","h2":"在 Michigan，你必须跟在开着警灯和警笛、正在行驶的急救车辆后面至少 500 英尺。","p":"对。至少保持 500 英尺的距离。"},"vi":{"q":"Ở Michigan, bạn phải đi cách phía sau xe khẩn cấp đang chạy, có bật đèn và còi hụ, bao xa?","o":["Ít nhất 100 feet","Ít nhất 500 feet","Ít nhất 50 feet","Ít nhất một dặm"],"h1":"Xa hơn chiều dài một sân bóng bầu dục.","h2":"Ở Michigan, bạn phải đi cách phía sau xe khẩn cấp đang chạy có bật đèn cảnh báo và còi hụ ít nhất 500 feet.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet."},"tl":{"q":"Sa Michigan, gaano kalayo ka dapat manatili sa likod ng umaandar na emergency vehicle na nakabukas ang ilaw at sirena?","o":["Hindi bababa sa 100 feet","Hindi bababa sa 500 feet","Hindi bababa sa 50 feet","Hindi bababa sa isang milya"],"h1":"Mas mahaba ito kaysa sa isang football field.","h2":"Sa Michigan, dapat kang manatili nang hindi bababa sa 500 feet sa likod ng umaandar na emergency vehicle na nakabukas ang warning lights at sirena.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod."},"ar":{"q":"في Michigan، على أي مسافة يجب أن تبقى خلف سيارة طوارئ متحرّكة أضواؤها وصفّارتها تعمل؟","o":["100 قدم على الأقل","500 قدم على الأقل","50 قدمًا على الأقل","ميل واحد على الأقل"],"h1":"هي أطول من ملعب كرة قدم أمريكية.","h2":"في Michigan، يجب أن تبقى على بُعد 500 قدم على الأقل خلف سيارة طوارئ متحرّكة أضواء التحذير وصفّارتها تعمل.","p":"صحيح. ابقَ على بُعد 500 قدم على الأقل."},"ref":{"doc":"MI","page":28}},{"id":"mi-045","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, when passing on a two-lane road, you must be back in your lane before you come within what distance of an oncoming vehicle?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is a few hundred feet, not just a car length.","h2":"In Michigan, you must return to your own lane before you get within 200 feet of any oncoming vehicle.","p":"Right. Be back in your lane before 200 feet."},"es":{"q":"En Michigan, al rebasar en un camino de dos carriles, ¿antes de qué distancia de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Son unos cientos de pies, no solo el largo de un auto.","h2":"En Michigan, debe volver a su carril antes de quedar a 200 pies de cualquier vehículo que viene de frente.","p":"Correcto. Vuelva a su carril antes de los 200 pies."},"zh":{"q":"在 Michigan，在双车道路上超车时，你必须在离对面来车多远之前回到自己的车道？","o":["50 英尺","100 英尺","200 英尺","1,000 英尺"],"h1":"是几百英尺，不只是一个车身长。","h2":"在 Michigan，你必须在离任何对面来车 200 英尺之前回到自己的车道。","p":"对。在 200 英尺之前回到自己的车道。"},"vi":{"q":"Ở Michigan, khi vượt xe trên đường hai làn, bạn phải trở về làn của mình trước khi đến gần xe đi ngược chiều trong khoảng cách nào?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"Đó là vài trăm feet, không chỉ bằng chiều dài một xe.","h2":"Ở Michigan, bạn phải trở về làn của mình trước khi đến gần bất kỳ xe đi ngược chiều nào trong vòng 200 feet.","p":"Đúng. Trở về làn của bạn trước 200 feet."},"tl":{"q":"Sa Michigan, kapag nag-o-overtake sa two-lane road, dapat nakabalik ka na sa lane mo bago ka umabot sa anong layo mula sa paparating na sasakyan?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"Ilang daang feet ito, hindi lang haba ng isang kotse.","h2":"Sa Michigan, dapat kang bumalik sa sarili mong lane bago ka umabot sa loob ng 200 feet ng anumang paparating na sasakyan.","p":"Tama. Bumalik sa lane mo bago ang 200 feet."},"ar":{"q":"في Michigan، عندما تتجاوز على طريق بمسارين، يجب أن تعود إلى مسارك قبل أن تقترب من سيارة قادمة من الاتجاه المقابل إلى أي مسافة؟","o":["50 قدمًا","100 قدم","200 قدم","1,000 قدم"],"h1":"هي بضع مئات من الأقدام، وليست طول سيارة فقط.","h2":"في Michigan، يجب أن تعود إلى مسارك قبل أن تصبح على بُعد 200 قدم من أي سيارة قادمة من الاتجاه المقابل.","p":"صحيح. عُد إلى مسارك قبل 200 قدم."},"ref":{"doc":"MI","page":32}},{"id":"mi-046","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, you may not pass another vehicle when you are within what distance of an intersection or railroad crossing?","o":["100 feet","25 feet","500 feet","One mile"],"h1":"It is the same distance as for a bridge or tunnel when your view is blocked.","h2":"In Michigan, you may not pass within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Michigan, ¿a qué distancia de un cruce de calles o de un cruce de ferrocarril no puede rebasar a otro vehículo?","o":["100 pies","25 pies","500 pies","Una milla"],"h1":"Es la misma distancia que para un puente o túnel cuando no puede ver bien.","h2":"En Michigan, no puede rebasar a menos de 100 pies de un cruce de calles o de un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de un cruce o de las vías."},"zh":{"q":"在 Michigan，你在离路口或铁路道口多远以内不可以超车？","o":["100 英尺","25 英尺","500 英尺","一英里"],"h1":"和视线被挡住时在桥或隧道的距离一样。","h2":"在 Michigan，你不可以在离路口或铁路道口 100 英尺以内超车。","p":"对。离路口或铁路道口 100 英尺以内不能超车。"},"vi":{"q":"Ở Michigan, bạn không được vượt xe khác khi ở trong khoảng cách nào tính từ giao lộ hoặc chỗ băng qua đường sắt?","o":["100 feet","25 feet","500 feet","Một dặm"],"h1":"Bằng khoảng cách với cầu hoặc đường hầm khi tầm nhìn của bạn bị che.","h2":"Ở Michigan, bạn không được vượt xe trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt.","p":"Đúng. Không vượt trong vòng 100 feet tính từ giao lộ hoặc chỗ băng qua đường sắt."},"tl":{"q":"Sa Michigan, hindi ka puwedeng mag-overtake ng ibang sasakyan kapag nasa loob ka ng anong layo mula sa intersection o railroad crossing?","o":["100 feet","25 feet","500 feet","Isang milya"],"h1":"Pareho ito ng layo para sa tulay o tunnel kapag may humaharang sa tanaw mo.","h2":"Sa Michigan, hindi ka puwedeng mag-overtake sa loob ng 100 feet ng intersection o railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 feet ng intersection o railroad crossing."},"ar":{"q":"في Michigan، لا يجوز لك أن تتجاوز سيارة أخرى عندما تكون ضمن أي مسافة من تقاطع أو معبر سكة حديد؟","o":["100 قدم","25 قدمًا","500 قدم","ميل واحد"],"h1":"هي نفس المسافة عند جسر أو نفق عندما يكون نظرك محجوبًا.","h2":"في Michigan، لا يجوز لك أن تتجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديد.","p":"صحيح. لا تجاوز ضمن 100 قدم من تقاطع أو معبر سكة حديد."},"ref":{"doc":"MI","page":32}},{"id":"mi-047","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, a train is coming to a railroad crossing. Where must you stop?","o":["Right on the first rail","At least 100 feet from the tracks","Anywhere, as long as you can see the train","No more than 50 feet and no less than 15 feet from the tracks"],"h1":"Trains stick out past the rails, so you cannot stop too close.","h2":"In Michigan, when a train is coming you must stop no more than 50 feet and no less than 15 feet from the tracks.","p":"Right. Stop between 15 and 50 feet from the tracks."},"es":{"q":"En Michigan, viene un tren a un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Justo sobre el primer riel","Por lo menos a 100 pies de las vías","Donde sea, si puede ver el tren","A no más de 50 pies y no menos de 15 pies de las vías"],"h1":"Los trenes sobresalen de los rieles, así que no puede detenerse muy cerca.","h2":"En Michigan, cuando viene un tren debe detenerse a no más de 50 pies y no menos de 15 pies de las vías.","p":"Correcto. Deténgase entre 15 y 50 pies de las vías."},"zh":{"q":"在 Michigan，有火车正开向铁路道口。你必须停在哪里？","o":["就停在第一条铁轨上","离铁轨至少 100 英尺","任何地方，只要能看到火车","离铁轨不超过 50 英尺，也不少于 15 英尺"],"h1":"火车比铁轨宽，所以你不能停得太近。","h2":"在 Michigan，有火车开来时，你必须停在离铁轨不超过 50 英尺、也不少于 15 英尺的地方。","p":"对。停在离铁轨 15 到 50 英尺之间。"},"vi":{"q":"Ở Michigan, có một đoàn tàu đang đến chỗ băng qua đường sắt. Bạn phải dừng ở đâu?","o":["Ngay trên đường ray đầu tiên","Cách đường ray ít nhất 100 feet","Ở đâu cũng được, miễn là bạn thấy tàu","Cách đường ray không quá 50 feet và không dưới 15 feet"],"h1":"Tàu rộng hơn đường ray, nên bạn không thể dừng quá gần.","h2":"Ở Michigan, khi có tàu đang đến, bạn phải dừng cách đường ray không quá 50 feet và không dưới 15 feet.","p":"Đúng. Dừng cách đường ray từ 15 đến 50 feet."},"tl":{"q":"Sa Michigan, may paparating na tren sa railroad crossing. Saan ka dapat huminto?","o":["Mismo sa unang riles","Hindi bababa sa 100 feet mula sa riles","Kahit saan, basta nakikita mo ang tren","Hindi lalampas sa 50 feet at hindi bababa sa 15 feet mula sa riles"],"h1":"Lumalampas ang tren sa gilid ng riles, kaya hindi ka puwedeng huminto nang masyadong malapit.","h2":"Sa Michigan, kapag may paparating na tren, dapat kang huminto nang hindi lalampas sa 50 feet at hindi bababa sa 15 feet mula sa riles.","p":"Tama. Huminto sa pagitan ng 15 at 50 feet mula sa riles."},"ar":{"q":"في Michigan، قطار قادم إلى معبر سكة حديد. أين يجب أن تتوقّف؟","o":["على السكة الأولى مباشرة","على بُعد 100 قدم على الأقل من السكة","في أي مكان، ما دمت ترى القطار","على بُعد لا يزيد عن 50 قدمًا ولا يقل عن 15 قدمًا من السكة"],"h1":"القطار أعرض من السكة، لذلك لا يمكنك أن تتوقّف قريبًا جدًا.","h2":"في Michigan، عندما يكون قطار قادمًا، يجب أن تتوقّف على بُعد لا يزيد عن 50 قدمًا ولا يقل عن 15 قدمًا من السكة.","p":"صحيح. توقّف بين 15 و50 قدمًا من السكة."},"ref":{"doc":"MI","page":35}},{"id":"mi-048","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","Right next to it if you stay in the car"],"h1":"Think of about three car widths, so fire trucks can reach it.","h2":"In Michigan, you may not park within 15 feet of a fire hydrant.","p":"Right. Keep at least 15 feet from a hydrant."},"es":{"q":"En Michigan, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 15 pies","No a menos de 50 pies","Justo al lado si se queda en el auto"],"h1":"Piense en unos tres anchos de auto, para que los bomberos lleguen.","h2":"En Michigan, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Deje por lo menos 15 pies desde un hidrante."},"zh":{"q":"在 Michigan，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 50 英尺","如果你留在车里，可以停在旁边"],"h1":"大约三辆车宽，让消防车能接到它。","h2":"在 Michigan，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Michigan, bạn được đậu xe gần trụ cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 50 feet","Ngay bên cạnh nếu bạn ở trong xe"],"h1":"Hãy nghĩ khoảng ba chiều ngang xe, để xe cứu hỏa có thể đến được.","h2":"Ở Michigan, bạn không được đậu xe trong vòng 15 feet tính từ trụ cứu hỏa.","p":"Đúng. Đậu cách trụ cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Michigan, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Mismo sa tabi nito kung mananatili ka sa kotse"],"h1":"Isipin ang mga tatlong lapad ng kotse, para maabot ito ng fire truck.","h2":"Sa Michigan, hindi ka puwedeng pumarada sa loob ng 15 feet ng fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet sa hydrant."},"ar":{"q":"في Michigan، إلى أي مدى يجوز لك أن تركن قرب حنفية إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","بجانبها مباشرة إذا بقيت في السيارة"],"h1":"فكّر في عرض ثلاث سيارات تقريبًا، حتى تصل إليها سيارات الإطفاء.","h2":"في Michigan، لا يجوز لك أن تركن ضمن 15 قدمًا من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من الحنفية."},"ref":{"doc":"MI","page":38}},{"id":"mi-049","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, within what distance of an oncoming vehicle is it illegal to use or flash your high beams?","o":["500 feet","100 feet","50 feet","2,000 feet"],"h1":"It is the same distance used for the headlight visibility rule.","h2":"In Michigan, it is illegal to use or even flash your high beams within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Michigan, ¿a qué distancia de un vehículo que viene de frente es ilegal usar las luces altas o hacer destellos con ellas?","o":["500 pies","100 pies","50 pies","2,000 pies"],"h1":"Es la misma distancia que se usa en la regla de visibilidad de los faros.","h2":"En Michigan, es ilegal usar o incluso hacer destellos con las luces altas a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies del tráfico que viene de frente."},"zh":{"q":"在 Michigan，离对面来车多远以内使用或闪远光灯是违法的？","o":["500 英尺","100 英尺","50 英尺","2,000 英尺"],"h1":"和车灯可见距离规定用的距离一样。","h2":"在 Michigan，在离对面来车 500 英尺以内使用远光灯，甚至闪一下，都是违法的。","p":"对。离对面来车 500 英尺以内要把灯调暗。"},"vi":{"q":"Ở Michigan, trong khoảng cách nào tính từ xe đi ngược chiều thì bật hoặc nháy đèn pha là phạm luật?","o":["500 feet","100 feet","50 feet","2,000 feet"],"h1":"Bằng khoảng cách dùng trong quy định về tầm nhìn của đèn pha.","h2":"Ở Michigan, bật hoặc thậm chí nháy đèn pha trong vòng 500 feet tính từ xe đi ngược chiều là phạm luật.","p":"Đúng. Hạ đèn xuống trong vòng 500 feet tính từ xe đi ngược chiều."},"tl":{"q":"Sa Michigan, sa loob ng anong layo mula sa paparating na sasakyan labag sa batas ang paggamit o pag-flash ng high beams?","o":["500 feet","100 feet","50 feet","2,000 feet"],"h1":"Pareho ito ng layo na ginagamit sa patakaran tungkol sa kung gaano kalayo dapat nakikita ang headlight.","h2":"Sa Michigan, labag sa batas ang paggamit o kahit pag-flash ng high beams sa loob ng 500 feet ng paparating na sasakyan.","p":"Tama. Hinaan ang ilaw sa loob ng 500 feet ng paparating na trapiko."},"ar":{"q":"في Michigan، ضمن أي مسافة من سيارة قادمة من الاتجاه المقابل يكون استعمال الأضواء العالية أو ومضها مخالفًا للقانون؟","o":["500 قدم","100 قدم","50 قدمًا","2,000 قدم"],"h1":"هي نفس المسافة المستعملة في قاعدة رؤية المصابيح الأمامية.","h2":"في Michigan، استعمال الأضواء العالية أو حتى ومضها ضمن 500 قدم من سيارة قادمة من الاتجاه المقابل مخالف للقانون.","p":"صحيح. خفّض أضواءك ضمن 500 قدم من السيارات القادمة."},"ref":{"doc":"MI","page":64}},{"id":"mi-050","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, after a crash, when must you notify the police?","o":["Only if a car must be towed","Only if someone dies","Only if the other driver asks","If anyone is hurt or property damage is over $1,000"],"h1":"There is a dollar amount, and injuries always count.","h2":"In Michigan, you must notify the police after a crash if anyone is injured or property damage is more than $1,000.","p":"Right. Injuries or more than $1,000 in damage mean you call the police."},"es":{"q":"En Michigan, después de un choque, ¿cuándo debe avisar a la policía?","o":["Solo si hay que remolcar un auto","Solo si alguien muere","Solo si el otro conductor lo pide","Si alguien está herido o los daños pasan de $1,000"],"h1":"Hay una cantidad de dinero, y las lesiones siempre cuentan.","h2":"En Michigan, debe avisar a la policía después de un choque si alguien está herido o si los daños a la propiedad pasan de $1,000.","p":"Correcto. Con heridos o más de $1,000 en daños, llame a la policía."},"zh":{"q":"在 Michigan，发生车祸后，你在什么情况下必须通知警察？","o":["只有车必须被拖走时","只有有人死亡时","只有对方司机要求时","有人受伤或财产损失超过 $1,000 时"],"h1":"有一个金额标准，而且有人受伤时一定要报。","h2":"在 Michigan，车祸后如果有人受伤，或财产损失超过 $1,000，你必须通知警察。","p":"对。有人受伤或损失超过 $1,000，就要报警。"},"vi":{"q":"Ở Michigan, sau một vụ va chạm, khi nào bạn phải báo cảnh sát?","o":["Chỉ khi có xe phải kéo đi","Chỉ khi có người chết","Chỉ khi người lái xe kia yêu cầu","Nếu có người bị thương hoặc thiệt hại tài sản hơn $1,000"],"h1":"Có một số tiền nhất định, và người bị thương thì luôn phải báo.","h2":"Ở Michigan, sau một vụ va chạm bạn phải báo cảnh sát nếu có người bị thương hoặc thiệt hại tài sản hơn $1,000.","p":"Đúng. Có người bị thương hoặc thiệt hại hơn $1,000 thì bạn gọi cảnh sát."},"tl":{"q":"Sa Michigan, pagkatapos ng banggaan, kailan mo dapat abisuhan ang pulis?","o":["Kung may kotseng kailangang i-tow lang","Kung may namatay lang","Kung hihilingin lang ng ibang driver","Kung may nasaktan o lampas $1,000 ang pinsala sa ari-arian"],"h1":"May halaga ng pera, at laging kasama ang may nasaktan.","h2":"Sa Michigan, dapat mong abisuhan ang pulis pagkatapos ng banggaan kung may nasaktan o kung lampas $1,000 ang pinsala sa ari-arian.","p":"Tama. Kapag may nasaktan o lampas $1,000 ang pinsala, tumawag ka sa pulis."},"ar":{"q":"في Michigan، بعد حادث تصادم، متى يجب أن تبلّغ الشرطة؟","o":["فقط إذا كانت سيارة تحتاج إلى سحب","فقط إذا مات أحد","فقط إذا طلب السائق الآخر ذلك","إذا أُصيب أحد أو كان ضرر الممتلكات أكثر من $1,000"],"h1":"هناك مبلغ من المال، والإصابات تُحسب دائمًا.","h2":"في Michigan، يجب أن تبلّغ الشرطة بعد حادث تصادم إذا أُصيب أحد أو كان ضرر الممتلكات أكثر من $1,000.","p":"صحيح. الإصابات أو ضرر أكثر من $1,000 يعني أن تتصل بالشرطة."},"ref":{"doc":"MI","page":65}},{"id":"mi-051","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, at an intersection with a \"Michigan Left,\" how do you turn left?","o":["Turn left directly from the left lane","Turn left from the right lane after the light","Go straight or turn right, then make a U-turn at a median crossover","Back up and turn when traffic clears"],"h1":"A direct left turn is not allowed at these intersections.","h2":"In Michigan, at a Michigan Left you drive straight through or turn right, then use a median crossover to make a U-turn.","p":"Right. A Michigan Left uses a median crossover instead of a direct left turn."},"es":{"q":"En Michigan, en un cruce con \"Michigan Left\", ¿cómo se da vuelta a la izquierda?","o":["Se da vuelta a la izquierda directamente desde el carril izquierdo","Se da vuelta a la izquierda desde el carril derecho después del semáforo","Se sigue derecho o se da vuelta a la derecha, y luego se hace una vuelta en U en un cruce del camellón","Se da reversa y se da vuelta cuando no hay tráfico"],"h1":"En estos cruces no se permite dar vuelta a la izquierda directamente.","h2":"En Michigan, en un Michigan Left usted sigue derecho o da vuelta a la derecha, y luego usa un cruce del camellón para dar una vuelta en U.","p":"Correcto. Un Michigan Left usa un cruce del camellón en vez de una vuelta directa a la izquierda."},"zh":{"q":"在 Michigan，在有“Michigan Left”的路口，你怎么左转？","o":["直接从左车道左转","绿灯后从右车道左转","直行或右转，然后在中间分隔带的掉头口掉头","倒车，等车流过去再转"],"h1":"在这种路口不可以直接左转。","h2":"在 Michigan，遇到 Michigan Left，你要直行或右转，然后从中间分隔带的掉头口掉头。","p":"对。Michigan Left 用中间分隔带的掉头口，而不是直接左转。"},"vi":{"q":"Ở Michigan, tại giao lộ có “Michigan Left”, bạn rẽ trái như thế nào?","o":["Rẽ trái thẳng từ làn bên trái","Rẽ trái từ làn bên phải sau đèn","Đi thẳng hoặc rẽ phải, rồi quay đầu (U-turn) ở chỗ mở của dải phân cách","Lùi xe và rẽ khi hết xe"],"h1":"Ở những giao lộ này không được rẽ trái trực tiếp.","h2":"Ở Michigan, tại Michigan Left bạn đi thẳng qua hoặc rẽ phải, rồi dùng chỗ mở của dải phân cách để quay đầu.","p":"Đúng. Michigan Left dùng chỗ mở của dải phân cách thay vì rẽ trái trực tiếp."},"tl":{"q":"Sa Michigan, sa intersection na may “Michigan Left,” paano ka kumakaliwa?","o":["Kumaliwa nang direkta mula sa kaliwang lane","Kumaliwa mula sa kanang lane pagkatapos ng ilaw","Dumiretso o kumanan, saka mag-U-turn sa median crossover","Umatras at kumaliwa kapag wala nang trapiko"],"h1":"Hindi pinapayagan ang direktang pagkaliwa sa mga intersection na ito.","h2":"Sa Michigan, sa Michigan Left ay dumidiretso ka o kumakanan, saka gumagamit ng median crossover para mag-U-turn.","p":"Tama. Gumagamit ang Michigan Left ng median crossover sa halip na direktang pagkaliwa."},"ar":{"q":"في Michigan، عند تقاطع فيه “Michigan Left”، كيف تنعطف إلى اليسار؟","o":["انعطف إلى اليسار مباشرة من المسار الأيسر","انعطف إلى اليسار من المسار الأيمن بعد الإشارة","سِر مستقيمًا أو انعطف إلى اليمين، ثم استدر (U-turn) عند فتحة في الجزيرة الوسطى","ارجع إلى الخلف وانعطف عندما تخلو الطريق"],"h1":"الانعطاف المباشر إلى اليسار غير مسموح في هذه التقاطعات.","h2":"في Michigan، عند Michigan Left تسير مستقيمًا أو تنعطف إلى اليمين، ثم تستعمل فتحة في الجزيرة الوسطى لتستدير.","p":"صحيح. Michigan Left يستعمل فتحة في الجزيرة الوسطى بدل الانعطاف المباشر إلى اليسار."},"ref":{"doc":"MI","page":48}},{"id":"mi-052","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many valid driver's licenses may one person hold at the same time?","o":["Two","One","Three","As many as their states issue"],"h1":"Think about what happens to your old license when Michigan accepts your application.","h2":"In Michigan, a person may hold only one valid driver's license at a time.","p":"Right. Only one valid license at a time."},"es":{"q":"En Michigan, ¿cuántas licencias de conducir válidas puede tener una persona al mismo tiempo?","o":["Dos","Una","Tres","Tantas como le den sus estados"],"h1":"Piense en qué pasa con su licencia anterior cuando Michigan acepta su solicitud.","h2":"En Michigan, una persona solo puede tener una licencia de conducir válida a la vez.","p":"Correcto. Solo una licencia válida a la vez."},"ref":{"doc":"MI","page":1}},{"id":"mi-053","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you have never had a driver's license anywhere. How many moving-violation convictions in the last three years will stop you from getting one?","o":["One or more","Four or more","Six or more","Two or more"],"h1":"Michigan allows no more than one such conviction.","h2":"In Michigan, a person who was never licensed is refused a license if they have two or more moving-violation convictions within three years.","p":"Correct. Two or more convictions in three years stops the license."},"es":{"q":"En Michigan, usted nunca ha tenido licencia de conducir. ¿Cuántas condenas por infracciones en movimiento en los últimos tres años le impiden obtenerla?","o":["Una o más","Cuatro o más","Seis o más","Dos o más"],"h1":"Michigan permite como máximo una condena de ese tipo.","h2":"En Michigan, a una persona que nunca tuvo licencia se le niega si tiene dos o más condenas por infracciones en movimiento en tres años.","p":"Correcto. Dos o más condenas en tres años impiden la licencia."},"ref":{"doc":"MI","page":1}},{"id":"mi-054","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, you just moved to the state with your car. When must you title and register the car here?","o":["Right away, at a Secretary of State office","Within one year of moving","When your old plates expire","Only when you sell the car"],"h1":"Michigan does not give new residents a grace period for this.","h2":"In Michigan, new residents must title and register their vehicle at a Secretary of State office right away.","p":"Yes. New residents title and register right away."},"es":{"q":"En Michigan, usted se acaba de mudar al estado con su auto. ¿Cuándo debe titular y registrar el auto aquí?","o":["De inmediato, en una oficina de la Secretaría de Estado","Dentro de un año después de mudarse","Cuando venzan sus placas anteriores","Solo cuando venda el auto"],"h1":"Michigan no da un período de gracia a los nuevos residentes para esto.","h2":"En Michigan, los nuevos residentes deben titular y registrar su vehículo de inmediato en una oficina de la Secretaría de Estado.","p":"Sí. Los nuevos residentes titulan y registran de inmediato."},"ref":{"doc":"MI","page":1}},{"id":"mi-055","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what is the youngest age to get a chauffeur's license?","o":["18","19","16","21"],"h1":"It is the same age as a Level 2 license.","h2":"In Michigan, you must be at least 16 years old to get a chauffeur's license.","p":"Correct. A chauffeur's license starts at 16."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para obtener una licencia de chofer (chauffeur's license)?","o":["18 años","19 años","16 años","21 años"],"h1":"Es la misma edad que la licencia de Nivel 2.","h2":"En Michigan, debe tener al menos 16 años para obtener una licencia de chofer.","p":"Correcto. La licencia de chofer empieza a los 16 años."},"ref":{"doc":"MI","page":2}},{"id":"mi-056","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, you are paid mainly to drive a vehicle. At what weight rating (GVWR) do you need a chauffeur's license?","o":["5,000 pounds or more","26,001 pounds or more","10,000 pounds or more","40,000 pounds or more"],"h1":"It is a lower weight than the one that needs a commercial license.","h2":"In Michigan, you need a chauffeur's license if your main job is driving a vehicle rated at 10,000 pounds or more.","p":"Right. 10,000 pounds or more needs a chauffeur's license."},"es":{"q":"En Michigan, a usted le pagan principalmente por manejar un vehículo. ¿Desde qué peso nominal (GVWR) necesita una licencia de chofer?","o":["5,000 libras o más","26,001 libras o más","10,000 libras o más","40,000 libras o más"],"h1":"Es un peso menor que el que exige una licencia comercial.","h2":"En Michigan, necesita licencia de chofer si su trabajo principal es manejar un vehículo de 10,000 libras o más.","p":"Correcto. Desde 10,000 libras necesita licencia de chofer."},"ref":{"doc":"MI","page":2}},{"id":"mi-057","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a single vehicle needs a commercial driver's license (CDL) when its weight rating (GVWR) is at least what?","o":["26,001 pounds","10,001 pounds","16,000 pounds","50,000 pounds"],"h1":"The number is just over 26,000.","h2":"In Michigan, you need a CDL to drive a single vehicle with a weight rating of 26,001 pounds or more.","p":"Correct. 26,001 pounds or more needs a CDL."},"es":{"q":"En Michigan, ¿desde qué peso nominal (GVWR) un vehículo sencillo requiere licencia de conducir comercial (CDL)?","o":["26,001 libras","10,001 libras","16,000 libras","50,000 libras"],"h1":"El número pasa un poco de 26,000.","h2":"En Michigan, necesita una CDL para manejar un vehículo sencillo con peso nominal de 26,001 libras o más.","p":"Correcto. Desde 26,001 libras se requiere CDL."},"ref":{"doc":"MI","page":2}},{"id":"mi-058","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, a vehicle built to carry how many people, counting the driver, needs a commercial driver's license?","o":["8 or more","10 or more","24 or more","16 or more"],"h1":"Count the driver as one of the people.","h2":"In Michigan, a vehicle designed to carry 16 or more people, including the driver, needs a CDL.","p":"Yes. 16 or more people, driver included, needs a CDL."},"es":{"q":"En Michigan, ¿un vehículo hecho para llevar cuántas personas, contando al conductor, requiere licencia comercial?","o":["8 o más","10 o más","24 o más","16 o más"],"h1":"Cuente al conductor como una de las personas.","h2":"En Michigan, un vehículo diseñado para llevar 16 personas o más, incluido el conductor, requiere CDL.","p":"Sí. 16 personas o más, contando al conductor, requiere CDL."},"ref":{"doc":"MI","page":2}},{"id":"mi-059","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, before you can drive commercial vehicles, how long must your record be free of suspensions?","o":["6 months","36 months","12 months","24 months"],"h1":"It is three full years.","h2":"In Michigan, you must have no suspensions for 36 months before you apply to drive commercial vehicles.","p":"Correct. 36 months with no suspension."},"es":{"q":"En Michigan, antes de poder manejar vehículos comerciales, ¿cuánto tiempo debe estar su historial sin suspensiones?","o":["6 meses","36 meses","12 meses","24 meses"],"h1":"Son tres años completos.","h2":"En Michigan, debe estar 36 meses sin suspensiones antes de solicitar manejar vehículos comerciales.","p":"Correcto. 36 meses sin suspensión."},"ref":{"doc":"MI","page":2}},{"id":"mi-060","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, a 19-year-old has a CDL. Where may they drive a commercial vehicle?","o":["In any state","Only inside Michigan","Only in Michigan and Ohio","Nowhere until age 21"],"h1":"Crossing state lines needs an older driver.","h2":"In Michigan, CDL drivers aged 18 to 20 may drive commercial vehicles only inside Michigan; age 21 is needed to cross state lines.","p":"Right. Under 21, only inside Michigan."},"es":{"q":"En Michigan, una persona de 19 años tiene CDL. ¿Dónde puede manejar un vehículo comercial?","o":["En cualquier estado","Solo dentro de Michigan","Solo en Michigan y Ohio","En ningún lugar hasta los 21 años"],"h1":"Para cruzar a otro estado se necesita más edad.","h2":"En Michigan, los conductores con CDL de 18 a 20 años solo pueden manejar vehículos comerciales dentro de Michigan; se necesitan 21 años para cruzar a otros estados.","p":"Correcto. Antes de los 21, solo dentro de Michigan."},"ref":{"doc":"MI","page":2}},{"id":"mi-061","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what extra use does an enhanced driver's license give you?","o":["Driving a school bus","Driving in Europe without a permit","Parking in disability spaces","Coming back into the U.S. by land or sea from Canada or Mexico"],"h1":"Think about border crossings.","h2":"In Michigan, an enhanced license lets you re-enter the United States by land or sea from Canada, Mexico, Bermuda and the Caribbean.","p":"Correct. It works for land and sea border crossings."},"es":{"q":"En Michigan, ¿qué uso adicional le da una licencia de conducir mejorada (enhanced)?","o":["Manejar un autobús escolar","Manejar en Europa sin permiso","Estacionar en espacios para discapacitados","Regresar a EE. UU. por tierra o mar desde Canadá o México"],"h1":"Piense en los cruces de frontera.","h2":"En Michigan, una licencia mejorada le permite volver a entrar a Estados Unidos por tierra o mar desde Canadá, México, Bermudas y el Caribe.","p":"Correcto. Sirve para cruzar la frontera por tierra y mar."},"ref":{"doc":"MI","page":2}},{"id":"mi-062","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a 15-year-old has no driver's license. What may they apply for with a parent's approval?","o":["A moped license","A chauffeur's license","A motorcycle endorsement","A Level 2 license"],"h1":"It is for a small two-wheeled vehicle.","h2":"In Michigan, unlicensed teens aged 15 or older may apply for a moped license with a parent's approval.","p":"Yes. A moped license, with a parent's approval."},"es":{"q":"En Michigan, un joven de 15 años no tiene licencia de conducir. ¿Qué puede solicitar con la aprobación de un padre?","o":["Una licencia de ciclomotor (moped)","Una licencia de chofer","Un endoso de motocicleta","Una licencia de Nivel 2"],"h1":"Es para un vehículo pequeño de dos ruedas.","h2":"En Michigan, los jóvenes sin licencia de 15 años o más pueden solicitar una licencia de ciclomotor con la aprobación de un padre.","p":"Sí. Una licencia de ciclomotor, con aprobación de un padre."},"ref":{"doc":"MI","page":2}},{"id":"mi-063","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, a 17-year-old wants a motorcycle endorsement. What must they complete?","o":["Only the written motorcycle test","A commercial driving course","A motorcycle rider education course","Nothing extra if they have Level 2"],"h1":"Teens cannot skip the training class.","h2":"In Michigan, riders aged 16 and 17 must complete a motorcycle rider education course to get the endorsement.","p":"Correct. Teens must take the rider education course."},"es":{"q":"En Michigan, un joven de 17 años quiere un endoso de motocicleta. ¿Qué debe completar?","o":["Solo el examen escrito de motocicleta","Un curso de manejo comercial","Un curso de educación para motociclistas","Nada más si tiene Nivel 2"],"h1":"Los adolescentes no pueden saltarse la clase.","h2":"En Michigan, los motociclistas de 16 y 17 años deben completar un curso de educación para motociclistas para obtener el endoso.","p":"Correcto. Los adolescentes deben tomar el curso."},"ref":{"doc":"MI","page":2}},{"id":"mi-064","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, an adult fails the motorcycle skills test. After how many failures must they take a rider education course?","o":["One","Three","Two","Five"],"h1":"They get one more try before the course is required.","h2":"In Michigan, an adult who fails the motorcycle skills test twice must take a rider education course.","p":"Right. After two failures, the course is required."},"es":{"q":"En Michigan, un adulto reprueba el examen práctico de motocicleta. ¿Después de cuántos intentos fallidos debe tomar un curso?","o":["Uno","Tres","Dos","Cinco"],"h1":"Tiene un intento más antes de que el curso sea obligatorio.","h2":"En Michigan, un adulto que reprueba dos veces el examen práctico de motocicleta debe tomar un curso de educación para motociclistas.","p":"Correcto. Después de dos fallas, el curso es obligatorio."},"ref":{"doc":"MI","page":2}},{"id":"mi-065","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what does a motorcycle endorsement with the \"3W\" restriction allow?","o":["Riding three-wheeled motorcycles only","Riding with up to three passengers","Riding only in daylight","Riding only within 3 miles of home"],"h1":"Count the wheels.","h2":"In Michigan, the CY 3W restriction lets a rider operate only three-wheeled motorcycles.","p":"Correct. 3W means three-wheeled motorcycles only."},"es":{"q":"En Michigan, ¿qué permite un endoso de motocicleta con la restricción \"3W\"?","o":["Manejar solo motocicletas de tres ruedas","Llevar hasta tres pasajeros","Manejar solo de día","Manejar solo a 3 millas de casa"],"h1":"Cuente las ruedas.","h2":"En Michigan, la restricción CY 3W permite manejar solo motocicletas de tres ruedas.","p":"Correcto. 3W significa solo motocicletas de tres ruedas."},"ref":{"doc":"MI","page":2}},{"id":"mi-066","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, when do you need a recreational double \"R\" endorsement?","o":["You drive a motor home over 30 feet","You tow a boat on a freeway","You rent out your camper","A pickup pulls a fifth-wheel camper with a second trailer behind it"],"h1":"Count the trailers.","h2":"In Michigan, the \"R\" endorsement is needed when a pickup pulls a fifth-wheel recreational trailer with a second trailer attached behind it.","p":"Yes. Two trailers behind a pickup need the \"R\" endorsement."},"es":{"q":"En Michigan, ¿cuándo necesita el endoso recreativo doble \"R\"?","o":["Maneja una casa rodante de más de 30 pies","Remolca un bote en una autopista","Renta su casa rodante","Una camioneta jala un remolque de quinta rueda con otro remolque detrás"],"h1":"Cuente los remolques.","h2":"En Michigan, el endoso \"R\" se necesita cuando una camioneta jala un remolque recreativo de quinta rueda con un segundo remolque detrás.","p":"Sí. Dos remolques detrás de una camioneta requieren el endoso \"R\"."},"ref":{"doc":"MI","page":2}},{"id":"mi-067","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how can you tell that a driver's license is REAL ID compliant?","o":["It has a red stripe on the bottom","It has a star in the upper right corner","It says \"Federal\" on the back","It has a blue border"],"h1":"Look at the top corner of the card.","h2":"In Michigan, a REAL ID compliant card has a star, in a gold circle or in the shape of Michigan, in the upper right corner.","p":"Right. Look for the star in the upper right corner."},"es":{"q":"En Michigan, ¿cómo sabe que una licencia de conducir cumple con REAL ID?","o":["Tiene una franja roja abajo","Tiene una estrella en la esquina superior derecha","Dice \"Federal\" en la parte de atrás","Tiene un borde azul"],"h1":"Mire la esquina de arriba de la tarjeta.","h2":"En Michigan, una tarjeta que cumple con REAL ID tiene una estrella, en un círculo dorado o en la forma de Michigan, en la esquina superior derecha.","p":"Correcto. Busque la estrella en la esquina superior derecha."},"ref":{"doc":"MI","page":3}},{"id":"mi-068","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, you choose not to get a REAL ID. What is printed on your standard license?","o":["\"Temporary License\"","\"Not for Federal Identification\"","\"Driving Only\"","\"Michigan Residents Only\""],"h1":"It tells you where the card cannot be used.","h2":"In Michigan, a standard license that is not REAL ID compliant says \"Not for Federal Identification\", but it is still valid for driving.","p":"Correct. It says \"Not for Federal Identification\"."},"es":{"q":"En Michigan, usted decide no obtener REAL ID. ¿Qué viene impreso en su licencia estándar?","o":["\"Licencia temporal\"","\"Not for Federal Identification\" (no válida para identificación federal)","\"Solo para manejar\"","\"Solo residentes de Michigan\""],"h1":"Le dice dónde no se puede usar la tarjeta.","h2":"En Michigan, una licencia estándar que no cumple con REAL ID dice \"Not for Federal Identification\", pero sigue siendo válida para manejar.","p":"Correcto. Dice \"Not for Federal Identification\"."},"ref":{"doc":"MI","page":3}},{"id":"mi-069","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, which driver can switch to a Michigan license without the knowledge test, permit or skills test?","o":["A driver with a license from France","A driver with a license from Mexico","A driver with a license from Japan","A driver with a license from Germany"],"h1":"Besides other U.S. states and Canada, only two other countries are on the list.","h2":"In Michigan, licenses from other U.S. states, Canada, Germany and South Korea can be switched without the knowledge test, permit or skills test.","p":"Correct. A German license can be converted."},"es":{"q":"En Michigan, ¿qué conductor puede cambiar a una licencia de Michigan sin examen escrito, permiso ni examen práctico?","o":["Un conductor con licencia de Francia","Un conductor con licencia de México","Un conductor con licencia de Japón","Un conductor con licencia de Alemania"],"h1":"Además de otros estados y Canadá, solo hay dos países más en la lista.","h2":"En Michigan, las licencias de otros estados de EE. UU., Canadá, Alemania y Corea del Sur se pueden cambiar sin examen escrito, permiso ni examen práctico.","p":"Correcto. Una licencia alemana se puede cambiar."},"ref":{"doc":"MI","page":3}},{"id":"mi-070","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, your out-of-state license expired five years ago. What must you do to get a Michigan license?","o":["Get a temporary instruction permit and pass a driving skills test","Only pass a vision test","Pay a late fee and renew","Wait one year"],"h1":"A license expired that long is treated almost like a new driver.","h2":"In Michigan, if your out-of-state license has been expired for at least four years, you must get a temporary instruction permit and pass a driving skills test.","p":"Right. A TIP and a skills test are needed."},"es":{"q":"En Michigan, su licencia de otro estado venció hace cinco años. ¿Qué debe hacer para obtener una licencia de Michigan?","o":["Obtener un permiso temporal de instrucción y pasar un examen práctico","Solo pasar un examen de la vista","Pagar un recargo y renovar","Esperar un año"],"h1":"Una licencia vencida por tanto tiempo se trata casi como un conductor nuevo.","h2":"En Michigan, si su licencia de otro estado lleva al menos cuatro años vencida, debe obtener un permiso temporal de instrucción y pasar un examen práctico.","p":"Correcto. Se necesitan el permiso y el examen práctico."},"ref":{"doc":"MI","page":3}},{"id":"mi-071","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, after you apply, about how long does it take for your new license card to arrive in the mail?","o":["About three days","About three months","About three weeks","About one year"],"h1":"It is less than a month.","h2":"In Michigan, a new driver's license should arrive in the mail in about three weeks.","p":"Correct. About three weeks."},"es":{"q":"En Michigan, después de solicitarla, ¿cuánto tarda más o menos su nueva licencia en llegar por correo?","o":["Unos tres días","Unos tres meses","Unas tres semanas","Un año"],"h1":"Es menos de un mes.","h2":"En Michigan, una nueva licencia de conducir debe llegar por correo en unas tres semanas.","p":"Correcto. Unas tres semanas."},"ref":{"doc":"MI","page":3}},{"id":"mi-072","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, a 17-year-old moves from another state. When do they NOT have to go through Graduated Driver Licensing?","o":["When their parents agree","When they pass the vision test","When they held a valid license from that state for more than a year","When they own a car"],"h1":"It depends on how long they have already been licensed.","h2":"In Michigan, a teen who has held a valid license from another state for more than a year does not have to go through Graduated Driver Licensing.","p":"Right. More than a year with a valid license waives GDL."},"es":{"q":"En Michigan, un joven de 17 años se muda de otro estado. ¿Cuándo NO tiene que pasar por el programa de licencia gradual (GDL)?","o":["Cuando sus padres están de acuerdo","Cuando pasa el examen de la vista","Cuando tuvo una licencia válida de ese estado por más de un año","Cuando tiene su propio auto"],"h1":"Depende de cuánto tiempo ya ha tenido licencia.","h2":"En Michigan, un joven que ha tenido una licencia válida de otro estado por más de un año no tiene que pasar por el programa GDL.","p":"Correcto. Más de un año con licencia válida lo exime del GDL."},"ref":{"doc":"MI","page":3}},{"id":"mi-073","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, at what age does Graduated Driver Licensing end?","o":["18","17","19","21"],"h1":"It is the age of adulthood.","h2":"In Michigan, Graduated Driver Licensing ends when you turn 18.","p":"Correct. GDL ends at 18."},"es":{"q":"En Michigan, ¿a qué edad termina el programa de licencia gradual (GDL)?","o":["18 años","17 años","19 años","21 años"],"h1":"Es la mayoría de edad.","h2":"En Michigan, el programa de licencia gradual termina cuando usted cumple 18 años.","p":"Correcto. El GDL termina a los 18 años."},"ref":{"doc":"MI","page":4}},{"id":"mi-074","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what is the youngest age to start Segment 1 of driver education?","o":["14 years and 9 months","14 years","15 years and 6 months","14 years and 8 months"],"h1":"It is one month before you can get a Level 1 license.","h2":"In Michigan, you may start Segment 1 of driver education at 14 years and 8 months, with a parent's permission.","p":"Right. Segment 1 can start at 14 years and 8 months."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para empezar el Segmento 1 de educación vial?","o":["14 años y 9 meses","14 años","15 años y 6 meses","14 años y 8 meses"],"h1":"Es un mes antes de poder obtener la licencia de Nivel 1.","h2":"En Michigan, puede empezar el Segmento 1 de educación vial a los 14 años y 8 meses, con permiso de un padre.","p":"Correcto. El Segmento 1 empieza a los 14 años y 8 meses."},"ref":{"doc":"MI","page":4}},{"id":"mi-075","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many hours of classroom instruction does Segment 1 of driver education include, at least?","o":["6 hours","24 hours","12 hours","40 hours"],"h1":"It is the largest part of Segment 1.","h2":"In Michigan, Segment 1 of driver education includes at least 24 hours of classroom instruction.","p":"Correct. At least 24 classroom hours."},"es":{"q":"En Michigan, ¿cuántas horas de clase en el aula incluye como mínimo el Segmento 1 de educación vial?","o":["6 horas","24 horas","12 horas","40 horas"],"h1":"Es la parte más grande del Segmento 1.","h2":"En Michigan, el Segmento 1 de educación vial incluye al menos 24 horas de clase en el aula.","p":"Correcto. Al menos 24 horas en el aula."},"ref":{"doc":"MI","page":4}},{"id":"mi-076","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many hours of behind-the-wheel driving with an instructor does Segment 1 include, at least?","o":["2 hours","6 hours","10 hours","24 hours"],"h1":"It is much less than the classroom time.","h2":"In Michigan, Segment 1 of driver education includes at least 6 hours of behind-the-wheel instruction.","p":"Correct. At least 6 hours behind the wheel."},"es":{"q":"En Michigan, ¿cuántas horas de manejo con instructor incluye como mínimo el Segmento 1?","o":["2 horas","6 horas","10 horas","24 horas"],"h1":"Es mucho menos que el tiempo en el aula.","h2":"En Michigan, el Segmento 1 de educación vial incluye al menos 6 horas de manejo con instructor.","p":"Correcto. Al menos 6 horas al volante."},"ref":{"doc":"MI","page":4}},{"id":"mi-077","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what score must you get on the state exam at the end of a driver education segment?","o":["At least 60 percent","At least 80 percent","At least 90 percent","At least 70 percent"],"h1":"It is the same for Segment 1 and Segment 2.","h2":"In Michigan, you must score at least 70 percent on the Segment 1 and Segment 2 state exams.","p":"Correct. At least 70 percent."},"es":{"q":"En Michigan, ¿qué puntaje debe sacar en el examen estatal al final de un segmento de educación vial?","o":["Al menos 60 por ciento","Al menos 80 por ciento","Al menos 90 por ciento","Al menos 70 por ciento"],"h1":"Es igual para el Segmento 1 y el Segmento 2.","h2":"En Michigan, debe sacar al menos 70 por ciento en los exámenes estatales del Segmento 1 y del Segmento 2.","p":"Correcto. Al menos 70 por ciento."},"ref":{"doc":"MI","page":4}},{"id":"mi-078","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a teen goes to a Secretary of State office to apply for a Level 1 Learner's License. Who must come with them?","o":["A parent or legal guardian","A driver education instructor","Any adult over 21","No one"],"h1":"The person who gives permission for the teen.","h2":"In Michigan, a teen must visit the Secretary of State office with a parent or legal guardian to apply for a Level 1 license.","p":"Right. A parent or legal guardian must come."},"es":{"q":"En Michigan, un joven va a una oficina de la Secretaría de Estado a solicitar la licencia de aprendiz de Nivel 1. ¿Quién debe acompañarlo?","o":["Un padre o tutor legal","Un instructor de manejo","Cualquier adulto mayor de 21 años","Nadie"],"h1":"La persona que da permiso por el joven.","h2":"En Michigan, el joven debe ir a la oficina de la Secretaría de Estado con un padre o tutor legal para solicitar la licencia de Nivel 1.","p":"Correcto. Debe ir un padre o tutor legal."},"ref":{"doc":"MI","page":4}},{"id":"mi-079","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, where must the supervising adult sit when a Level 1 driver is driving?","o":["In the back seat behind the driver","Anywhere in the car","In the front seat next to the driver","In a car following behind"],"h1":"They need to be close enough to help right away.","h2":"In Michigan, the licensed adult supervising a Level 1 driver must sit in the front seat next to the driver.","p":"Correct. In the front seat next to the driver."},"es":{"q":"En Michigan, ¿dónde debe sentarse el adulto que supervisa a un conductor de Nivel 1?","o":["En el asiento de atrás, detrás del conductor","En cualquier lugar del auto","En el asiento delantero, al lado del conductor","En otro auto que va detrás"],"h1":"Debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Michigan, el adulto con licencia que supervisa a un conductor de Nivel 1 debe ir en el asiento delantero, al lado del conductor.","p":"Correcto. En el asiento delantero, al lado del conductor."},"ref":{"doc":"MI","page":5}},{"id":"mi-080","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, a family friend aged 30 will supervise a Level 1 driver. What does the friend need from the teen's parent?","o":["A copy of the parent's license","A note from the school","A signed letter of authorization","Nothing at all"],"h1":"It is written proof that the parent approves.","h2":"In Michigan, a designated adult who supervises a Level 1 driver needs a signed letter of authorization from the parent or guardian.","p":"Right. A signed letter from the parent."},"es":{"q":"En Michigan, un amigo de la familia de 30 años va a supervisar a un conductor de Nivel 1. ¿Qué necesita el amigo del padre del joven?","o":["Una copia de la licencia del padre","Una nota de la escuela","Una carta de autorización firmada","Nada"],"h1":"Es una prueba por escrito de que el padre está de acuerdo.","h2":"En Michigan, un adulto designado que supervisa a un conductor de Nivel 1 necesita una carta de autorización firmada por el padre o tutor.","p":"Correcto. Una carta firmada por el padre."},"ref":{"doc":"MI","page":5}},{"id":"mi-081","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how long must a teen hold a Level 1 license before starting Segment 2 of driver education?","o":["At least three months in a row","At least one month","At least six months","At least one year"],"h1":"It is half the time needed before Level 2.","h2":"In Michigan, you must hold your Level 1 license for at least three consecutive months before Segment 2.","p":"Correct. At least three months in a row."},"es":{"q":"En Michigan, ¿cuánto tiempo debe tener un joven la licencia de Nivel 1 antes de empezar el Segmento 2?","o":["Al menos tres meses seguidos","Al menos un mes","Al menos seis meses","Al menos un año"],"h1":"Es la mitad del tiempo necesario antes del Nivel 2.","h2":"En Michigan, debe tener la licencia de Nivel 1 por al menos tres meses seguidos antes del Segmento 2.","p":"Correcto. Al menos tres meses seguidos."},"ref":{"doc":"MI","page":5}},{"id":"mi-082","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, the driving log for Segment 2 needs 30 hours. How many of them must be at night?","o":["At least 10 hours","At least 5 hours","None","At least 2 hours"],"h1":"It is a small part of the 30 hours.","h2":"In Michigan, the 30-hour log before Segment 2 must include at least 2 hours of night driving.","p":"Right. At least 2 hours at night."},"es":{"q":"En Michigan, el registro de manejo para el Segmento 2 necesita 30 horas. ¿Cuántas deben ser de noche?","o":["Al menos 10 horas","Al menos 5 horas","Ninguna","Al menos 2 horas"],"h1":"Es una parte pequeña de las 30 horas.","h2":"En Michigan, el registro de 30 horas antes del Segmento 2 debe incluir al menos 2 horas de manejo nocturno.","p":"Correcto. Al menos 2 horas de noche."},"ref":{"doc":"MI","page":5}},{"id":"mi-083","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many hours of classroom instruction does Segment 2 of driver education include, at least?","o":["2 hours","6 hours","12 hours","24 hours"],"h1":"It is a short course compared with Segment 1.","h2":"In Michigan, Segment 2 of driver education is at least 6 hours of classroom instruction.","p":"Correct. At least 6 classroom hours."},"es":{"q":"En Michigan, ¿cuántas horas de clase en el aula incluye como mínimo el Segmento 2?","o":["2 horas","6 horas","12 horas","24 horas"],"h1":"Es un curso corto comparado con el Segmento 1.","h2":"En Michigan, el Segmento 2 de educación vial tiene al menos 6 horas de clase en el aula.","p":"Correcto. Al menos 6 horas en el aula."},"ref":{"doc":"MI","page":5}},{"id":"mi-084","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, what is the youngest age to take the driving skills test as a teen?","o":["14 years and 9 months","15","16","17"],"h1":"It comes before the minimum age for Level 2.","h2":"In Michigan, a teen must be at least 15 to take the driving skills test.","p":"Right. The skills test starts at 15."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para que un joven tome el examen práctico de manejo?","o":["14 años y 9 meses","15 años","16 años","17 años"],"h1":"Es antes de la edad mínima del Nivel 2.","h2":"En Michigan, un joven debe tener al menos 15 años para tomar el examen práctico de manejo.","p":"Correcto. El examen práctico empieza a los 15 años."},"ref":{"doc":"MI","page":5}},{"id":"mi-085","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, besides your log and certificates, what must you bring for the car you use on the driving skills test?","o":["Its purchase receipt","Its repair history","Its spare key","Its insurance and registration"],"h1":"They are the papers you show a police officer.","h2":"In Michigan, you must bring the insurance and registration for the vehicle you will drive during the skills test.","p":"Correct. Bring the car's insurance and registration."},"es":{"q":"En Michigan, además del registro y los certificados, ¿qué debe llevar del auto que usará en el examen práctico?","o":["Su recibo de compra","Su historial de reparaciones","Su llave de repuesto","Su seguro y su registro"],"h1":"Son los papeles que le muestra a un policía.","h2":"En Michigan, debe llevar el seguro y el registro del vehículo que manejará en el examen práctico.","p":"Correcto. Lleve el seguro y el registro del auto."},"ref":{"doc":"MI","page":5}},{"id":"mi-086","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a teen got a hard plastic photo card for Level 1. What happens when they meet the Level 2 requirements and pass the skills test?","o":["They move to Level 2 automatically","They must visit an office for a new card","They must retake Segment 1","They must wait until 17"],"h1":"The hard card saves a trip.","h2":"In Michigan, teens with a photo hard card who meet the requirements and pass the skills test move to Level 2 automatically, without returning to the office.","p":"Right. They advance to Level 2 automatically."},"es":{"q":"En Michigan, un joven recibió una tarjeta plástica con foto para el Nivel 1. ¿Qué pasa cuando cumple los requisitos del Nivel 2 y aprueba el examen práctico?","o":["Pasa al Nivel 2 automáticamente","Debe ir a una oficina por una tarjeta nueva","Debe repetir el Segmento 1","Debe esperar hasta los 17 años"],"h1":"La tarjeta plástica ahorra una visita.","h2":"En Michigan, los jóvenes con tarjeta plástica con foto que cumplen los requisitos y aprueban el examen práctico pasan al Nivel 2 automáticamente, sin volver a la oficina.","p":"Correcto. Pasan al Nivel 2 automáticamente."},"ref":{"doc":"MI","page":5}},{"id":"mi-087","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what can happen to a Level 1 or Level 2 driver who breaks Kelsey's Law by using a phone?","o":["A felony charge","Jail for 30 days","A civil infraction with a fine or community service","Only a warning letter"],"h1":"It is a ticket, not a crime.","h2":"In Michigan, a teen who breaks Kelsey's Law can get a civil infraction with fines, community service, or both.","p":"Correct. A civil infraction with fines or community service."},"es":{"q":"En Michigan, ¿qué le puede pasar a un conductor de Nivel 1 o 2 que viola la Ley Kelsey al usar el teléfono?","o":["Un cargo de delito grave","30 días de cárcel","Una infracción civil con multa o servicio comunitario","Solo una carta de advertencia"],"h1":"Es una multa, no un delito.","h2":"En Michigan, un joven que viola la Ley Kelsey puede recibir una infracción civil con multa, servicio comunitario o ambos.","p":"Correcto. Una infracción civil con multa o servicio comunitario."},"ref":{"doc":"MI","page":5}},{"id":"mi-088","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, to move to a Level 3 license, how long must a teen drive with no moving violation, at-fault crash or suspension?","o":["90 days","6 months","12 months in a row","24 months"],"h1":"It is a full year.","h2":"In Michigan, a teen must go 12 consecutive months without a moving violation, at-fault crash, suspension or GDL violation to get Level 3.","p":"Right. Twelve months in a row with a clean record."},"es":{"q":"En Michigan, para pasar a la licencia de Nivel 3, ¿cuánto tiempo debe manejar un joven sin infracciones en movimiento, choques con culpa ni suspensiones?","o":["90 días","6 meses","12 meses seguidos","24 meses"],"h1":"Es un año completo.","h2":"En Michigan, un joven debe pasar 12 meses seguidos sin infracciones en movimiento, choques con culpa, suspensiones ni violaciones del GDL para obtener el Nivel 3.","p":"Correcto. Doce meses seguidos con historial limpio."},"ref":{"doc":"MI","page":5}},{"id":"mi-089","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how is a Level 3 Full License usually issued once a teen meets every requirement?","o":["Automatically, at no fee, if the parent has authorized it","Only after a new road test","Only after a written test and a fee","Only at a court hearing"],"h1":"No trip or payment is needed.","h2":"In Michigan, the Level 3 license is issued automatically and at no fee when all requirements are met and a parent has authorized it.","p":"Correct. Automatically and free, with parental authorization."},"es":{"q":"En Michigan, ¿cómo se entrega normalmente la licencia completa de Nivel 3 cuando el joven cumple todos los requisitos?","o":["Automáticamente y sin costo, si el padre lo autorizó","Solo después de otro examen práctico","Solo después de un examen escrito y un pago","Solo en una audiencia judicial"],"h1":"No hace falta ir ni pagar.","h2":"En Michigan, la licencia de Nivel 3 se entrega automáticamente y sin costo cuando se cumplen los requisitos y un padre lo ha autorizado.","p":"Correcto. Automática y gratis, con autorización del padre."},"ref":{"doc":"MI","page":5}},{"id":"mi-090","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, a 16-year-old with a Level 2 license wants to drive to a movie at 11 p.m. When is this allowed?","o":["When two friends ride along","When the trip is under 5 miles","When the roads are dry","When a parent or a designated licensed adult 21 or older rides along"],"h1":"Look at who is in the car with the teen.","h2":"In Michigan, a Level 2 driver may drive between 10 p.m. and 5 a.m. for fun only if a parent, guardian or designated licensed adult aged 21 or older is with them.","p":"Correct. Only with a parent or designated adult 21 or older."},"es":{"q":"En Michigan, un joven de 16 años con licencia de Nivel 2 quiere ir al cine a las 11 p.m. ¿Cuándo se permite?","o":["Cuando van dos amigos con él","Cuando el viaje es de menos de 5 millas","Cuando las calles están secas","Cuando va con un padre o un adulto designado con licencia de 21 años o más"],"h1":"Fíjese en quién va en el auto con el joven.","h2":"En Michigan, un conductor de Nivel 2 puede manejar por diversión entre las 10 p.m. y las 5 a.m. solo si va con un padre, tutor o adulto designado con licencia de 21 años o más.","p":"Correcto. Solo con un padre o un adulto designado de 21 años o más."},"ref":{"doc":"MI","page":5}},{"id":"mi-091","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, what does it cost to take the written knowledge test at a Secretary of State office?","o":["$6.50","Nothing","$25","$50"],"h1":"There is a fee only for the at-home version.","h2":"In Michigan, the written knowledge test is given free of charge at all Secretary of State offices.","p":"Right. It is free at the office."},"es":{"q":"En Michigan, ¿cuánto cuesta tomar el examen escrito en una oficina de la Secretaría de Estado?","o":["$6.50","Nada","$25","$50"],"h1":"Solo la versión en casa tiene costo.","h2":"En Michigan, el examen escrito es gratis en todas las oficinas de la Secretaría de Estado.","p":"Correcto. En la oficina es gratis."},"ref":{"doc":"MI","page":6}},{"id":"mi-092","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, an adult takes the written knowledge test online at home. What fee do they pay?","o":["No fee","A $6.50 convenience fee","A $25 testing fee","A $100 fee"],"h1":"It is a small convenience charge.","h2":"In Michigan, taking the written knowledge test online at home costs a $6.50 convenience fee.","p":"Correct. The online test costs $6.50."},"es":{"q":"En Michigan, un adulto toma el examen escrito en línea desde su casa. ¿Qué cargo paga?","o":["Ningún cargo","Un cargo de conveniencia de $6.50","Un cargo de examen de $25","Un cargo de $100"],"h1":"Es un cargo pequeño por la comodidad.","h2":"En Michigan, tomar el examen escrito en línea desde casa cuesta un cargo de conveniencia de $6.50.","p":"Correcto. El examen en línea cuesta $6.50."},"ref":{"doc":"MI","page":6}},{"id":"mi-093","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you have no Social Security number and bring a letter of ineligibility from Social Security. How old may the letter be?","o":["No more than 1 year old","No more than 10 days old","Any age","No more than 60 days old"],"h1":"It must be fairly recent, about two months.","h2":"In Michigan, a Social Security letter of ineligibility must be no more than 60 days old.","p":"Right. No more than 60 days old."},"es":{"q":"En Michigan, usted no tiene número de Seguro Social y lleva una carta de no elegibilidad del Seguro Social. ¿Qué antigüedad puede tener la carta?","o":["No más de 1 año","No más de 10 días","Cualquier antigüedad","No más de 60 días"],"h1":"Debe ser bastante reciente, unos dos meses.","h2":"En Michigan, la carta de no elegibilidad del Seguro Social no puede tener más de 60 días.","p":"Correcto. No más de 60 días."},"ref":{"doc":"MI","page":6}},{"id":"mi-094","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, how many documents must you show to prove you live in the state?","o":["At least two","Just one","At least four","None if you have a passport"],"h1":"One is not enough.","h2":"In Michigan, you must show at least two documents to prove Michigan residency.","p":"Correct. At least two documents."},"es":{"q":"En Michigan, ¿cuántos documentos debe mostrar para probar que vive en el estado?","o":["Al menos dos","Solo uno","Al menos cuatro","Ninguno si tiene pasaporte"],"h1":"Uno no es suficiente.","h2":"En Michigan, debe mostrar al menos dos documentos para probar su residencia en Michigan.","p":"Correcto. Al menos dos documentos."},"ref":{"doc":"MI","page":6}},{"id":"mi-095","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, you use a utility bill to prove where you live. How recent must it be?","o":["Issued within the last year","Issued within the last 7 days","Issued within the last 90 days","Any date"],"h1":"It is about three months.","h2":"In Michigan, a utility bill, credit card bill or account statement used as proof of residency must be issued within the last 90 days.","p":"Right. Within the last 90 days."},"es":{"q":"En Michigan, usted usa un recibo de servicios para probar dónde vive. ¿Qué tan reciente debe ser?","o":["Emitido en el último año","Emitido en los últimos 7 días","Emitido en los últimos 90 días","De cualquier fecha"],"h1":"Son unos tres meses.","h2":"En Michigan, un recibo de servicios, de tarjeta de crédito o un estado de cuenta usado como prueba de residencia debe ser de los últimos 90 días.","p":"Correcto. De los últimos 90 días."},"ref":{"doc":"MI","page":6}},{"id":"mi-096","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, you bring a photocopy of your birth certificate to prove your identity. Will it be accepted?","o":["Yes, if it is in color","Yes, if a friend signs it","No, only original documents are accepted","Yes, if it is faxed from the hospital"],"h1":"Copies and faxes are a problem.","h2":"In Michigan, only original documents are accepted as proof of identity; photocopies and faxes are not.","p":"Correct. Only originals are accepted."},"es":{"q":"En Michigan, usted lleva una fotocopia de su acta de nacimiento para probar su identidad. ¿La aceptarán?","o":["Sí, si es a color","Sí, si la firma un amigo","No, solo se aceptan documentos originales","Sí, si la mandan por fax del hospital"],"h1":"Las copias y los faxes son un problema.","h2":"En Michigan, solo se aceptan documentos originales como prueba de identidad; no se aceptan fotocopias ni faxes.","p":"Correcto. Solo se aceptan originales."},"ref":{"doc":"MI","page":6}},{"id":"mi-097","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, on which written test may you NOT use a foreign language interpreter?","o":["A commercial driver's license (CDL) knowledge test","The operator's license knowledge test","The road sign test","The motorcycle knowledge test"],"h1":"It is the test for big trucks and buses.","h2":"In Michigan, foreign language interpreters may be used on all written tests except CDL knowledge tests.","p":"Correct. Not on CDL knowledge tests."},"es":{"q":"En Michigan, ¿en qué examen escrito NO puede usar un intérprete de otro idioma?","o":["El examen escrito de licencia comercial (CDL)","El examen escrito de licencia de conductor","El examen de señales","El examen escrito de motocicleta"],"h1":"Es el examen para camiones grandes y autobuses.","h2":"En Michigan, se pueden usar intérpretes de otros idiomas en todos los exámenes escritos menos en los de CDL.","p":"Correcto. No en los exámenes de CDL."},"ref":{"doc":"MI","page":7}},{"id":"mi-098","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you passed the driving skills test and are waiting for your card. What lets you drive until it arrives?","o":["Your skills test score sheet","A photo of your old permit","Nothing; you must wait for the card","A temporary operator's permit (TOP) printed from your online account"],"h1":"You can print it yourself from MiLogin.","h2":"In Michigan, a temporary operator's permit (TOP), printed from your MiLogin account, lets you drive until your new license arrives.","p":"Correct. The temporary operator's permit covers you."},"es":{"q":"En Michigan, usted aprobó el examen práctico y espera su tarjeta. ¿Qué le permite manejar mientras llega?","o":["Su hoja de resultados del examen","Una foto de su permiso anterior","Nada; debe esperar la tarjeta","Un permiso temporal de operador (TOP) impreso desde su cuenta en línea"],"h1":"Usted mismo lo puede imprimir desde MiLogin.","h2":"En Michigan, un permiso temporal de operador (TOP), impreso desde su cuenta MiLogin, le permite manejar hasta que llegue su nueva licencia.","p":"Correcto. El permiso temporal de operador lo cubre."},"ref":{"doc":"MI","page":7}},{"id":"mi-099","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, you fail the vision test at the Secretary of State office. What can you do next?","o":["Take the test again the next day with no changes","Have an eye-care specialist fill out a vision statement","Skip it by passing the written test","Bring a friend to read the chart"],"h1":"A professional must document your eyesight.","h2":"In Michigan, if you fail the vision test, an eye-care specialist must complete a vision statement showing you meet the standards.","p":"Right. An eye-care specialist completes a vision statement."},"es":{"q":"En Michigan, usted reprueba el examen de la vista en la oficina de la Secretaría de Estado. ¿Qué puede hacer después?","o":["Repetir el examen al día siguiente sin cambios","Pedir a un especialista de la vista que llene una declaración de visión","Saltarlo aprobando el examen escrito","Llevar a un amigo que lea la tabla"],"h1":"Un profesional debe documentar su vista.","h2":"En Michigan, si reprueba el examen de la vista, un especialista de la vista debe llenar una declaración de visión que muestre que cumple las normas.","p":"Correcto. Un especialista de la vista llena la declaración."},"ref":{"doc":"MI","page":7}},{"id":"mi-100","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, you need glasses to pass the vision test. What does this mean for your license?","o":["It will only allow driving in daylight","It will say you must wear corrective lenses while driving","It will be valid for one year only","It will not change"],"h1":"The license shows the restriction.","h2":"In Michigan, if you need glasses or contacts to pass the vision test, your license will show that you must wear them while driving.","p":"Correct. You must wear them while driving."},"es":{"q":"En Michigan, usted necesita lentes para pasar el examen de la vista. ¿Qué significa esto para su licencia?","o":["Solo le permitirá manejar de día","Dirá que debe usar lentes correctivos al manejar","Valdrá solo un año","No cambiará"],"h1":"La licencia muestra la restricción.","h2":"En Michigan, si necesita lentes o lentes de contacto para pasar el examen de la vista, su licencia indicará que debe usarlos al manejar.","p":"Correcto. Debe usarlos al manejar."},"ref":{"doc":"MI","page":7}},{"id":"mi-101","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many motorcycle temporary instruction permits can one rider get in a 10-year period?","o":["One","Three","No limit","Two"],"h1":"The permit is not meant to replace the endorsement.","h2":"In Michigan, only two motorcycle temporary instruction permits are issued to a rider in a 10-year period.","p":"Correct. Only two in 10 years."},"es":{"q":"En Michigan, ¿cuántos permisos temporales de instrucción para motocicleta puede recibir un motociclista en 10 años?","o":["Uno","Tres","Sin límite","Dos"],"h1":"El permiso no debe reemplazar el endoso.","h2":"En Michigan, solo se dan dos permisos temporales de instrucción para motocicleta a un motociclista en un período de 10 años.","p":"Correcto. Solo dos en 10 años."},"ref":{"doc":"MI","page":8}},{"id":"mi-102","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what is the youngest age to get a motorcycle temporary instruction permit?","o":["16","14","15","18"],"h1":"It is the same age as a Level 2 car license.","h2":"In Michigan, you must be at least 16 years old to get a motorcycle temporary instruction permit.","p":"Right. At least 16."},"es":{"q":"En Michigan, ¿cuál es la edad mínima para obtener un permiso temporal de instrucción para motocicleta?","o":["16 años","14 años","15 años","18 años"],"h1":"Es la misma edad que la licencia de auto de Nivel 2.","h2":"En Michigan, debe tener al menos 16 años para obtener un permiso temporal de instrucción para motocicleta.","p":"Correcto. Al menos 16 años."},"ref":{"doc":"MI","page":8}},{"id":"mi-103","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, what must you already have before you can get a motorcycle temporary instruction permit?","o":["A motorcycle registered in your name","A completed motorcycle skills test","A valid Michigan driver's license","A commercial driver's license"],"h1":"The motorcycle permit is added on top of something you already hold.","h2":"In Michigan, you must hold a valid Michigan driver's license to get a motorcycle temporary instruction permit.","p":"Correct. You need a valid Michigan driver's license."},"es":{"q":"En Michigan, ¿qué debe tener antes de poder obtener un permiso temporal de instrucción para motocicleta?","o":["Una motocicleta registrada a su nombre","El examen práctico de motocicleta aprobado","Una licencia de conducir de Michigan válida","Una licencia comercial"],"h1":"El permiso de motocicleta se suma a algo que ya tiene.","h2":"En Michigan, debe tener una licencia de conducir de Michigan válida para obtener un permiso temporal de instrucción para motocicleta.","p":"Correcto. Necesita una licencia de Michigan válida."},"ref":{"doc":"MI","page":8}},{"id":"mi-104","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, a rider has a motorcycle temporary instruction permit. Who must supervise every ride?","o":["Any licensed car driver","A parent riding as a passenger","A licensed motorcycle rider at least 18, keeping them in sight","No one in daylight"],"h1":"The supervisor must be able to see the rider the whole time.","h2":"In Michigan, a motorcycle permit holder must ride under the constant visual supervision of a licensed motorcycle operator who is at least 18.","p":"Right. A licensed motorcyclist 18 or older, always in sight."},"es":{"q":"En Michigan, un motociclista tiene permiso temporal de instrucción para motocicleta. ¿Quién debe supervisar cada viaje?","o":["Cualquier conductor de auto con licencia","Un padre que vaya de pasajero","Un motociclista con licencia de al menos 18 años que lo tenga a la vista","Nadie de día"],"h1":"El supervisor debe poder verlo todo el tiempo.","h2":"En Michigan, quien tiene permiso de motocicleta debe manejar bajo la supervisión visual constante de un motociclista con licencia de al menos 18 años.","p":"Correcto. Un motociclista con licencia de 18 años o más, siempre a la vista."},"ref":{"doc":"MI","page":8}},{"id":"mi-105","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what may a rider with a motorcycle temporary instruction permit NOT do?","o":["Ride at night or carry passengers","Ride on city streets","Ride in the rain","Ride with a helmet camera"],"h1":"The limits are about darkness and other people on the bike.","h2":"In Michigan, a rider with a motorcycle temporary instruction permit may not ride at night or carry passengers.","p":"Correct. No night riding and no passengers."},"es":{"q":"En Michigan, ¿qué NO puede hacer un motociclista con permiso temporal de instrucción?","o":["Manejar de noche o llevar pasajeros","Manejar en calles de la ciudad","Manejar bajo la lluvia","Manejar con cámara en el casco"],"h1":"Los límites tienen que ver con la oscuridad y con otras personas en la moto.","h2":"En Michigan, un motociclista con permiso temporal de instrucción no puede manejar de noche ni llevar pasajeros.","p":"Correcto. Ni de noche ni con pasajeros."},"ref":{"doc":"MI","page":8}},{"id":"mi-106","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what is the first part of the driving skills test?","o":["Highway driving at 70 mph","A written sign test","Parallel parking on a busy street","Off-street maneuvers on a closed course"],"h1":"You pass this part before you go out on the road.","h2":"In Michigan, the driving skills test starts with off-street, closed-course maneuvers, followed by an on-road test.","p":"Right. Closed-course maneuvers come first."},"es":{"q":"En Michigan, ¿cuál es la primera parte del examen práctico de manejo?","o":["Manejo en autopista a 70 mph","Un examen escrito de señales","Estacionarse en paralelo en una calle transitada","Maniobras fuera de la calle en un circuito cerrado"],"h1":"Usted pasa esta parte antes de salir a la calle.","h2":"En Michigan, el examen práctico empieza con maniobras fuera de la calle en un circuito cerrado, seguidas de un examen en la calle.","p":"Correcto. Primero las maniobras en circuito cerrado."},"ref":{"doc":"MI","page":9}},{"id":"mi-107","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, you had a seizure four months ago. What may the Secretary of State ask for when you apply for a license?","o":["A letter from your employer","A Physician's Statement of Examination","Proof of car insurance only","Nothing; it does not matter"],"h1":"A doctor must describe your condition.","h2":"In Michigan, a physician's statement is required if there is reason to believe you had a fainting spell, blackout or seizure in the last six months.","p":"Correct. A physician's statement is required."},"es":{"q":"En Michigan, usted tuvo una convulsión hace cuatro meses. ¿Qué puede pedirle la Secretaría de Estado al solicitar una licencia?","o":["Una carta de su empleador","Una declaración médica de examen (Physician's Statement)","Solo prueba de seguro del auto","Nada; no importa"],"h1":"Un médico debe describir su condición.","h2":"En Michigan, se exige una declaración médica si hay razones para creer que tuvo un desmayo, pérdida de conocimiento o convulsión en los últimos seis meses.","p":"Correcto. Se exige una declaración médica."},"ref":{"doc":"MI","page":9}},{"id":"mi-108","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, you got married and want your new name on your license. What must you do first?","o":["Get a new car registration","Change your name with the Social Security Administration","Take the knowledge test again","Wait until your license expires"],"h1":"Another agency must update its records before the Secretary of State.","h2":"In Michigan, you must first change your name with the Social Security Administration and allow at least three business days before visiting a Secretary of State office.","p":"Correct. Social Security comes first."},"es":{"q":"En Michigan, usted se casó y quiere su nuevo nombre en la licencia. ¿Qué debe hacer primero?","o":["Sacar un nuevo registro del auto","Cambiar su nombre con la Administración del Seguro Social","Repetir el examen escrito","Esperar a que venza su licencia"],"h1":"Otra agencia debe actualizar sus datos antes que la Secretaría de Estado.","h2":"En Michigan, primero debe cambiar su nombre con la Administración del Seguro Social y esperar al menos tres días hábiles antes de ir a una oficina de la Secretaría de Estado.","p":"Correcto. Primero el Seguro Social."},"ref":{"doc":"MI","page":9}},{"id":"mi-109","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, what does it cost to change the address on your driver's license?","o":["$5","$10","The full renewal fee","Nothing"],"h1":"It is a free service.","h2":"In Michigan, there is no charge to change your address online, by mail or at a Secretary of State office.","p":"Right. An address change is free."},"es":{"q":"En Michigan, ¿cuánto cuesta cambiar la dirección de su licencia de conducir?","o":["$5","$10","El precio completo de la renovación","Nada"],"h1":"Es un servicio gratis.","h2":"En Michigan, cambiar su dirección en línea, por correo o en una oficina de la Secretaría de Estado no tiene costo.","p":"Correcto. El cambio de dirección es gratis."},"ref":{"doc":"MI","page":9}},{"id":"mi-110","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, you moved months ago but never updated the address on your license. What can happen?","o":["Your license may be suspended or revoked","Nothing, as long as your plates are current","You only lose your voter registration","Your insurance doubles automatically"],"h1":"The law requires the address to match where you live.","h2":"In Michigan, your driver's license may be suspended or revoked if you fail to change your address with the Secretary of State.","p":"Correct. Your license may be suspended or revoked."},"es":{"q":"En Michigan, usted se mudó hace meses y nunca actualizó la dirección de su licencia. ¿Qué puede pasar?","o":["Le pueden suspender o revocar la licencia","Nada, si sus placas están vigentes","Solo pierde su registro de votante","Su seguro se duplica automáticamente"],"h1":"La ley exige que la dirección coincida con donde vive.","h2":"En Michigan, su licencia puede ser suspendida o revocada si no cambia su dirección con la Secretaría de Estado.","p":"Correcto. Le pueden suspender o revocar la licencia."},"ref":{"doc":"MI","page":10}},{"id":"mi-111","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, for a driver 21 or older, how long is a driver's license usually valid?","o":["Two years, ending on January 1","Eight years, ending on your birthday","Four years, ending on your birthday","Ten years, ending on the issue date"],"h1":"It ends on a date that is personal to you.","h2":"In Michigan, a driver's license is usually valid for four years and expires on your birthday in the year shown.","p":"Right. Four years, ending on your birthday."},"es":{"q":"En Michigan, para un conductor de 21 años o más, ¿por cuánto tiempo suele ser válida la licencia?","o":["Dos años, hasta el 1 de enero","Ocho años, hasta su cumpleaños","Cuatro años, hasta su cumpleaños","Diez años, hasta la fecha de emisión"],"h1":"Termina en una fecha personal para usted.","h2":"En Michigan, una licencia de conducir suele ser válida por cuatro años y vence en su cumpleaños del año indicado.","p":"Correcto. Cuatro años, hasta su cumpleaños."},"ref":{"doc":"MI","page":10}},{"id":"mi-112","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, you renew your license two weeks after it expired. What happens?","o":["You must retake the skills test","You pay nothing extra","You pay a late fee on top of the renewal fee","You must wait 30 days to renew"],"h1":"Waiting costs a little more.","h2":"In Michigan, if you renew your license after its expiration date, you pay a late fee in addition to the regular renewal fee.","p":"Correct. You pay a late fee too."},"es":{"q":"En Michigan, usted renueva su licencia dos semanas después de que venció. ¿Qué pasa?","o":["Debe repetir el examen práctico","No paga nada extra","Paga un recargo además de la renovación","Debe esperar 30 días para renovar"],"h1":"Esperar cuesta un poco más.","h2":"En Michigan, si renueva su licencia después de la fecha de vencimiento, paga un recargo además del costo normal de renovación.","p":"Correcto. También paga un recargo."},"ref":{"doc":"MI","page":10}},{"id":"mi-113","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a 70-year-old decides to stop driving and turns in their license. What can they get for free?","o":["A state ID card","A new car registration","A disability parking placard","A bus pass for life"],"h1":"It replaces the license as identification.","h2":"In Michigan, drivers 65 or older who voluntarily give up their license can get a free state ID card.","p":"Right. A free state ID card."},"es":{"q":"En Michigan, una persona de 70 años decide dejar de manejar y entrega su licencia. ¿Qué puede recibir gratis?","o":["Una tarjeta de identificación estatal","Un nuevo registro de auto","Un permiso de estacionamiento para discapacitados","Un pase de autobús de por vida"],"h1":"Reemplaza la licencia como identificación.","h2":"En Michigan, los conductores de 65 años o más que entregan su licencia voluntariamente pueden recibir una tarjeta de identificación estatal gratis.","p":"Correcto. Una identificación estatal gratis."},"ref":{"doc":"MI","page":10}},{"id":"mi-114","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, can you renew a driver's license that is currently suspended?","o":["Yes, online only","Yes, if you pay a late fee","Yes, if it expires within a month","No, a suspended license will not be renewed"],"h1":"The suspension has to be cleared first.","h2":"In Michigan, a driver's license that has been suspended, revoked or denied will not be renewed.","p":"Correct. A suspended license is not renewed."},"es":{"q":"En Michigan, ¿puede renovar una licencia de conducir que está suspendida?","o":["Sí, solo en línea","Sí, si paga un recargo","Sí, si vence en menos de un mes","No, una licencia suspendida no se renueva"],"h1":"Primero hay que resolver la suspensión.","h2":"En Michigan, una licencia de conducir suspendida, revocada o negada no se renueva.","p":"Correcto. Una licencia suspendida no se renueva."},"ref":{"doc":"MI","page":10}},{"id":"mi-115","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long do most traffic convictions stay on your driving record?","o":["Six months","At least seven years","Two years","Forever"],"h1":"It is much longer than the points.","h2":"In Michigan, most convictions stay on your driving record for at least seven years.","p":"Right. At least seven years."},"es":{"q":"En Michigan, ¿cuánto tiempo permanecen la mayoría de las condenas de tránsito en su historial de manejo?","o":["Seis meses","Al menos siete años","Dos años","Para siempre"],"h1":"Es mucho más que los puntos.","h2":"En Michigan, la mayoría de las condenas permanecen en su historial de manejo al menos siete años.","p":"Correcto. Al menos siete años."},"ref":{"doc":"MI","page":13}},{"id":"mi-116","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how long does a conviction for impaired driving stay on your driving record?","o":["Two years","Permanently","Seven years","Ten years"],"h1":"It never goes away.","h2":"In Michigan, a conviction for impaired driving or for a fatality stays on your driving record permanently.","p":"Correct. It stays permanently."},"es":{"q":"En Michigan, ¿cuánto tiempo permanece en su historial una condena por manejar bajo los efectos del alcohol o drogas?","o":["Dos años","Permanentemente","Siete años","Diez años"],"h1":"Nunca se borra.","h2":"En Michigan, una condena por manejar bajo los efectos o por una muerte permanece en su historial de manejo para siempre.","p":"Correcto. Permanece para siempre."},"ref":{"doc":"MI","page":13}},{"id":"mi-117","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you get a traffic ticket and simply ignore it. What usually happens?","o":["The ticket is dropped after a year","Nothing until you renew","Only your car is towed","Your driver's license is suspended"],"h1":"Not dealing with it makes it worse.","h2":"In Michigan, in most cases your driver's license is suspended if you do not take care of a traffic ticket.","p":"Right. Your license is usually suspended."},"es":{"q":"En Michigan, usted recibe una multa de tránsito y la ignora. ¿Qué pasa normalmente?","o":["La multa se cancela al año","Nada hasta que renueve","Solo se llevan su auto con grúa","Le suspenden la licencia de conducir"],"h1":"No atenderla empeora las cosas.","h2":"En Michigan, en la mayoría de los casos le suspenden la licencia si no atiende una multa de tránsito.","p":"Correcto. Normalmente le suspenden la licencia."},"ref":{"doc":"MI","page":13}},{"id":"mi-118","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, when are points placed on your driving record?","o":["Only after you are convicted of a moving violation","As soon as an officer writes a ticket","When you are in any crash","When you renew your license"],"h1":"A ticket alone is not enough.","h2":"In Michigan, points go on your driving record only after you are convicted of a moving violation.","p":"Correct. Only after a conviction."},"es":{"q":"En Michigan, ¿cuándo se ponen puntos en su historial de manejo?","o":["Solo después de una condena por una infracción en movimiento","En cuanto un policía escribe una multa","Cuando tiene cualquier choque","Cuando renueva su licencia"],"h1":"Una multa por sí sola no basta.","h2":"En Michigan, los puntos se ponen en su historial solo después de una condena por una infracción en movimiento.","p":"Correcto. Solo después de una condena."},"ref":{"doc":"MI","page":13}},{"id":"mi-119","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how many points go on your record for running a stop sign or a red light?","o":["Two points","Four points","Three points","Six points"],"h1":"It is in the middle of the point list.","h2":"In Michigan, disobeying a traffic signal or stop sign puts three points on your driving record.","p":"Right. Three points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por pasarse una señal de alto o una luz roja?","o":["Dos puntos","Cuatro puntos","Tres puntos","Seis puntos"],"h1":"Está en la mitad de la lista de puntos.","h2":"En Michigan, desobedecer un semáforo o una señal de alto pone tres puntos en su historial de manejo.","p":"Correcto. Tres puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-120","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, you are convicted of driving 13 mph over the speed limit. How many points go on your record?","o":["Two points","Four points","Three points","One point"],"h1":"The range is 11 to 15 mph over.","h2":"In Michigan, driving 11 to 15 mph over the legal speed limit adds three points to your driving record.","p":"Correct. Three points."},"es":{"q":"En Michigan, lo condenan por manejar 13 mph por encima del límite. ¿Cuántos puntos se ponen en su historial?","o":["Dos puntos","Cuatro puntos","Tres puntos","Un punto"],"h1":"El rango es de 11 a 15 mph por encima.","h2":"En Michigan, manejar de 11 a 15 mph por encima del límite legal suma tres puntos a su historial.","p":"Correcto. Tres puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-121","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, you are convicted of driving 20 mph over the speed limit. How many points go on your record?","o":["Four points","Two points","Three points","Six points"],"h1":"It is 16 mph or more over.","h2":"In Michigan, driving 16 mph or more over the legal speed limit adds four points to your driving record.","p":"Right. Four points."},"es":{"q":"En Michigan, lo condenan por manejar 20 mph por encima del límite. ¿Cuántos puntos se ponen en su historial?","o":["Cuatro puntos","Dos puntos","Tres puntos","Seis puntos"],"h1":"Son 16 mph o más por encima.","h2":"En Michigan, manejar 16 mph o más por encima del límite legal suma cuatro puntos a su historial.","p":"Correcto. Cuatro puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-122","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you are convicted of driving 8 mph over the speed limit. How many points go on your record?","o":["One point","Three points","Four points","Two points"],"h1":"The range is 6 to 10 mph over.","h2":"In Michigan, driving 6 to 10 mph over the legal speed limit adds two points to your driving record.","p":"Correct. Two points."},"es":{"q":"En Michigan, lo condenan por manejar 8 mph por encima del límite. ¿Cuántos puntos se ponen en su historial?","o":["Un punto","Tres puntos","Cuatro puntos","Dos puntos"],"h1":"El rango es de 6 a 10 mph por encima.","h2":"En Michigan, manejar de 6 a 10 mph por encima del límite legal suma dos puntos a su historial.","p":"Correcto. Dos puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-123","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many points go on your record for having an open alcohol container in the vehicle?","o":["Four points","Two points","Six points","No points"],"h1":"It is one of the lower point values.","h2":"In Michigan, an open alcohol container in the vehicle puts two points on your driving record.","p":"Right. Two points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por llevar un envase abierto de alcohol en el vehículo?","o":["Cuatro puntos","Dos puntos","Seis puntos","Ningún punto"],"h1":"Es uno de los valores más bajos.","h2":"En Michigan, llevar un envase abierto de alcohol en el vehículo pone dos puntos en su historial de manejo.","p":"Correcto. Dos puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-124","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how many points go on your record for a reckless driving conviction?","o":["Two points","Six points","Three points","Four points"],"h1":"It is in the most serious group.","h2":"In Michigan, reckless driving puts six points on your driving record.","p":"Correct. Six points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por una condena de manejo imprudente (reckless driving)?","o":["Dos puntos","Seis puntos","Tres puntos","Cuatro puntos"],"h1":"Está en el grupo más grave.","h2":"En Michigan, el manejo imprudente pone seis puntos en su historial de manejo.","p":"Correcto. Seis puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-125","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many points go on your record for drag racing?","o":["Two points","Three points","Six points","Four points"],"h1":"It is one step below the most serious group.","h2":"In Michigan, drag racing puts four points on your driving record.","p":"Right. Four points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por carreras de arrancones (drag racing)?","o":["Dos puntos","Tres puntos","Seis puntos","Cuatro puntos"],"h1":"Está un nivel por debajo del grupo más grave.","h2":"En Michigan, las carreras de arrancones ponen cuatro puntos en su historial de manejo.","p":"Correcto. Cuatro puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-126","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a 19-year-old refuses a preliminary breath test at the roadside. How many points go on their record?","o":["Two points","Four points","Six points","No points"],"h1":"This roadside test is different from the chemical test at the station.","h2":"In Michigan, a driver under 21 who refuses a preliminary breath test gets two points on their driving record.","p":"Correct. Two points."},"es":{"q":"En Michigan, una persona de 19 años se niega a la prueba preliminar de aliento en la carretera. ¿Cuántos puntos se ponen en su historial?","o":["Dos puntos","Cuatro puntos","Seis puntos","Ningún punto"],"h1":"Esta prueba en la carretera es distinta de la prueba química en la estación.","h2":"En Michigan, un conductor menor de 21 años que se niega a la prueba preliminar de aliento recibe dos puntos en su historial.","p":"Correcto. Dos puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-127","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how many points go on your record for leaving a crash without stopping to give your identification?","o":["Two points","Three points","Six points","Four points"],"h1":"It is treated as one of the most serious violations.","h2":"In Michigan, failing to stop and give identification at the scene of a crash puts six points on your driving record.","p":"Right. Six points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por irse de un choque sin detenerse a identificarse?","o":["Dos puntos","Tres puntos","Seis puntos","Cuatro puntos"],"h1":"Se considera una de las infracciones más graves.","h2":"En Michigan, no detenerse ni identificarse en el lugar de un choque pone seis puntos en su historial de manejo.","p":"Correcto. Seis puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-128","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how many points go on your record for failing to stop for a school bus?","o":["Two points","Four points","Three points","Six points"],"h1":"It is the same as running a stop sign.","h2":"In Michigan, failing to stop for a school bus or disobeying a school crossing guard puts three points on your driving record.","p":"Correct. Three points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por no detenerse ante un autobús escolar?","o":["Dos puntos","Cuatro puntos","Tres puntos","Seis puntos"],"h1":"Es lo mismo que pasarse una señal de alto.","h2":"En Michigan, no detenerse ante un autobús escolar o desobedecer a un guardia de cruce escolar pone tres puntos en su historial.","p":"Correcto. Tres puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-129","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a driver under 21 is convicted of driving with any alcohol in their body. How many points go on their record?","o":["Four points","Two points","Three points","Six points"],"h1":"It is the same as drag racing.","h2":"In Michigan, a driver under 21 with any bodily alcohol content gets four points on their driving record.","p":"Right. Four points."},"es":{"q":"En Michigan, un conductor menor de 21 años es condenado por manejar con cualquier cantidad de alcohol en el cuerpo. ¿Cuántos puntos recibe?","o":["Cuatro puntos","Dos puntos","Tres puntos","Seis puntos"],"h1":"Es lo mismo que las carreras de arrancones.","h2":"En Michigan, un conductor menor de 21 años con cualquier contenido de alcohol en el cuerpo recibe cuatro puntos en su historial.","p":"Correcto. Cuatro puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-130","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many points go on your record for failing to yield to an emergency vehicle?","o":["Three points","Four points","Six points","Two points"],"h1":"If no one is hurt, it is one of the lower values.","h2":"In Michigan, failing to yield or show due caution for emergency vehicles puts two points on your driving record.","p":"Correct. Two points."},"es":{"q":"En Michigan, ¿cuántos puntos se ponen en su historial por no ceder el paso a un vehículo de emergencia?","o":["Tres puntos","Cuatro puntos","Seis puntos","Dos puntos"],"h1":"Si nadie sale herido, es uno de los valores más bajos.","h2":"En Michigan, no ceder el paso ni tener precaución con los vehículos de emergencia pone dos puntos en su historial de manejo.","p":"Correcto. Dos puntos."},"ref":{"doc":"MI","page":14}},{"id":"mi-131","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, a driver has a first drug conviction and no earlier ones. How long is the license suspended?","o":["30 days","Six months","One year","Two years"],"h1":"It is half a year.","h2":"In Michigan, a first drug conviction with no prior drug violations brings a six-month license suspension.","p":"Right. Six months."},"es":{"q":"En Michigan, un conductor tiene su primera condena por drogas y ninguna anterior. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","Seis meses","Un año","Dos años"],"h1":"Es medio año.","h2":"En Michigan, una primera condena por drogas, sin violaciones anteriores, trae una suspensión de licencia de seis meses.","p":"Correcto. Seis meses."},"ref":{"doc":"MI","page":15}},{"id":"mi-132","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, after a first drug conviction, when is a restricted license NOT available?","o":["During the first 7 days","During the first 30 days of the suspension","During the last month","It is never available"],"h1":"There is a waiting period at the start.","h2":"In Michigan, after a first drug conviction, no restricted license is issued during the first 30 days of the suspension.","p":"Correct. Not during the first 30 days."},"es":{"q":"En Michigan, después de una primera condena por drogas, ¿cuándo NO se puede obtener una licencia restringida?","o":["Durante los primeros 7 días","Durante los primeros 30 días de la suspensión","Durante el último mes","Nunca se puede obtener"],"h1":"Hay un período de espera al inicio.","h2":"En Michigan, después de una primera condena por drogas, no se da licencia restringida durante los primeros 30 días de la suspensión.","p":"Correcto. No durante los primeros 30 días."},"ref":{"doc":"MI","page":15}},{"id":"mi-133","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, a driver is convicted of a drug crime and had another drug conviction five years ago. How long is the license suspended?","o":["Six months","90 days","Five years","One year"],"h1":"An earlier conviction within seven years doubles the first-time period.","h2":"In Michigan, one or more prior drug convictions within seven years means a one-year license suspension.","p":"Right. One year."},"es":{"q":"En Michigan, un conductor es condenado por drogas y tuvo otra condena por drogas hace cinco años. ¿Por cuánto tiempo le suspenden la licencia?","o":["Seis meses","90 días","Cinco años","Un año"],"h1":"Una condena anterior en siete años duplica el período de la primera vez.","h2":"En Michigan, una o más condenas anteriores por drogas en siete años significan una suspensión de licencia de un año.","p":"Correcto. Un año."},"ref":{"doc":"MI","page":15}},{"id":"mi-134","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, what is the license reinstatement fee after a drug-related suspension?","o":["$125","$25","$50","$500"],"h1":"It is more than $100.","h2":"In Michigan, the driver's license reinstatement fee after a drug suspension is $125.","p":"Correct. The fee is $125."},"es":{"q":"En Michigan, ¿cuánto cuesta reactivar la licencia después de una suspensión por drogas?","o":["$125","$25","$50","$500"],"h1":"Es más de $100.","h2":"En Michigan, el cargo por reactivar la licencia después de una suspensión por drogas es de $125.","p":"Correcto. El cargo es de $125."},"ref":{"doc":"MI","page":15}},{"id":"mi-135","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, a person is convicted of a drug crime that did not involve driving. What happens to their license?","o":["Nothing, because they were not driving","They only pay a fine","It is still suspended","They get extra points but keep driving"],"h1":"The law does not require a car to be involved.","h2":"In Michigan, the law requires a license suspension for drug convictions, even if you were not driving at the time.","p":"Right. The license is still suspended."},"es":{"q":"En Michigan, una persona es condenada por un delito de drogas que no tuvo que ver con manejar. ¿Qué pasa con su licencia?","o":["Nada, porque no manejaba","Solo paga una multa","Igual se la suspenden","Recibe puntos pero sigue manejando"],"h1":"La ley no exige que haya un auto involucrado.","h2":"En Michigan, la ley exige suspender la licencia por condenas de drogas, aunque usted no estuviera manejando.","p":"Correcto. Igual se suspende la licencia."},"ref":{"doc":"MI","page":15}},{"id":"mi-136","scope":"MI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Michigan, how much marijuana may a person 21 or older legally carry in a vehicle?","o":["1 pound or less","Any amount for personal use","2.5 ounces or less","None at all"],"h1":"It is a few ounces.","h2":"In Michigan, a person 21 or older may transport 2.5 ounces of marijuana or less, with no more than 15 grams as concentrate.","p":"Correct. 2.5 ounces or less."},"es":{"q":"En Michigan, ¿cuánta marihuana puede llevar legalmente en un vehículo una persona de 21 años o más?","o":["1 libra o menos","Cualquier cantidad para uso personal","2.5 onzas o menos","Nada"],"h1":"Son unas pocas onzas.","h2":"En Michigan, una persona de 21 años o más puede transportar 2.5 onzas de marihuana o menos, con no más de 15 gramos en concentrado.","p":"Correcto. 2.5 onzas o menos."},"ref":{"doc":"MI","page":15}},{"id":"mi-137","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a passenger wants to smoke marijuana in a car on a public road. Is that allowed?","o":["No, drivers and passengers may not smoke it in the passenger area","Yes, if the passenger is 21 or older","Yes, if the windows are open","Yes, if the driver does not smoke"],"h1":"The rule covers everyone in the car.","h2":"In Michigan, drivers and passengers are not allowed to smoke marijuana in the passenger area of a vehicle on a public road.","p":"Right. No one may smoke it in the car."},"es":{"q":"En Michigan, un pasajero quiere fumar marihuana en un auto en una vía pública. ¿Se permite?","o":["No, ni el conductor ni los pasajeros pueden fumarla dentro del auto","Sí, si el pasajero tiene 21 años o más","Sí, si las ventanas están abiertas","Sí, si el conductor no fuma"],"h1":"La regla incluye a todos en el auto.","h2":"En Michigan, el conductor y los pasajeros no pueden fumar marihuana dentro del área de pasajeros de un vehículo en una vía pública.","p":"Correcto. Nadie puede fumarla en el auto."},"ref":{"doc":"MI","page":15}},{"id":"mi-138","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, you have legal marijuana in your car and plan to drive into Canada. Is that allowed?","o":["Yes, if it is under 2.5 ounces","Yes, if it is in the trunk","Yes, if you are 21 or older","No, taking marijuana into Canada is illegal"],"h1":"Crossing the border changes everything.","h2":"In Michigan, it is illegal to transport marijuana into Canada.","p":"Correct. Taking it into Canada is illegal."},"es":{"q":"En Michigan, usted lleva marihuana legal en su auto y piensa cruzar a Canadá. ¿Se permite?","o":["Sí, si es menos de 2.5 onzas","Sí, si va en la cajuela","Sí, si tiene 21 años o más","No, llevar marihuana a Canadá es ilegal"],"h1":"Cruzar la frontera lo cambia todo.","h2":"En Michigan, es ilegal transportar marihuana a Canadá.","p":"Correcto. Llevarla a Canadá es ilegal."},"ref":{"doc":"MI","page":15}},{"id":"mi-139","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, under the implied consent law, when did you agree to take a chemical test if police ask?","o":["Only when you sign a form at the traffic stop","When you applied for or renewed your driver's license","Only after a crash","Only if a judge orders it"],"h1":"Your agreement came with getting your license.","h2":"In Michigan, all drivers are considered to have agreed to a chemical test when they apply for or renew their driver's license.","p":"Right. You agreed when you got or renewed your license."},"es":{"q":"En Michigan, según la ley de consentimiento implícito, ¿cuándo aceptó hacerse una prueba química si la policía lo pide?","o":["Solo cuando firma un formulario en la parada","Cuando solicitó o renovó su licencia de conducir","Solo después de un choque","Solo si un juez lo ordena"],"h1":"Su aceptación vino con obtener su licencia.","h2":"En Michigan, se considera que todos los conductores aceptaron una prueba química al solicitar o renovar su licencia de conducir.","p":"Correcto. Lo aceptó al obtener o renovar su licencia."},"ref":{"doc":"MI","page":15}},{"id":"mi-140","scope":"MI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Michigan, how do the penalties for driving under the influence of marijuana compare with those for alcohol?","o":["They are much lighter","They are the same","They are only a small fine","There are no penalties if it is legal"],"h1":"Michigan treats both kinds of impaired driving alike.","h2":"In Michigan, the penalties for operating under the influence of marijuana are the same as for alcohol, including up to 93 days in jail, a fine up to $500 and six points.","p":"Correct. They are the same as for alcohol."},"es":{"q":"En Michigan, ¿cómo se comparan las penas por manejar bajo los efectos de la marihuana con las del alcohol?","o":["Son mucho más leves","Son las mismas","Son solo una multa pequeña","No hay pena si es legal"],"h1":"Michigan trata igual ambos tipos de manejo bajo los efectos.","h2":"En Michigan, las penas por manejar bajo los efectos de la marihuana son las mismas que por alcohol, incluyendo hasta 93 días de cárcel, multa de hasta $500 y seis puntos.","p":"Correcto. Son las mismas que por alcohol."},"ref":{"doc":"MI","page":15}},{"id":"mi-141","scope":"MI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Michigan, how many traffic crashes in two years can lead to a driver reexamination?","o":["One","Two","Five or more","Three or more"],"h1":"It is more than two.","h2":"In Michigan, being in three or more crashes with injury or property damage in two years can lead to a driver reexamination.","p":"Right. Three or more crashes in two years."},"es":{"q":"En Michigan, ¿cuántos choques en dos años pueden llevar a una reevaluación del conductor?","o":["Uno","Dos","Cinco o más","Tres o más"],"h1":"Son más de dos.","h2":"En Michigan, tener tres o más choques con heridos o daños materiales en dos años puede llevar a una reevaluación del conductor.","p":"Correcto. Tres o más choques en dos años."},"ref":{"doc":"MI","page":16}},{"id":"mi-142","scope":"MI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Michigan, a teen with a GDL license gets tickets. After how many violations may they be called to a driver reexamination?","o":["After only one or two","Only after six","Only after 12 points","Never while under 18"],"h1":"New drivers are watched more closely.","h2":"In Michigan, probationary drivers and drivers in Graduated Driver Licensing may be called to a reexamination after only one or two violations.","p":"Correct. After only one or two violations."},"es":{"q":"En Michigan, un joven con licencia GDL recibe multas. ¿Después de cuántas infracciones lo pueden llamar a una reevaluación?","o":["Después de solo una o dos","Solo después de seis","Solo después de 12 puntos","Nunca antes de los 18 años"],"h1":"A los conductores nuevos los vigilan más de cerca.","h2":"En Michigan, los conductores en período de prueba o en el programa GDL pueden ser llamados a una reevaluación después de solo una o dos infracciones.","p":"Correcto. Después de solo una o dos infracciones."},"ref":{"doc":"MI","page":16}},{"id":"mi-143","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, what is the fine for a second or later offense of using a hand-held phone while driving?","o":["$100","$500","$250","$1,000"],"h1":"It is more than double the first fine.","h2":"In Michigan, the fine for using a hand-held phone while driving is $250 for a second or later offense.","p":"Right. $250 for later offenses."},"es":{"q":"En Michigan, ¿cuál es la multa por una segunda vez o más por usar un teléfono en la mano mientras maneja?","o":["$100","$500","$250","$1,000"],"h1":"Es más del doble de la primera multa.","h2":"En Michigan, la multa por usar un teléfono en la mano mientras maneja es de $250 a partir de la segunda vez.","p":"Correcto. $250 a partir de la segunda vez."},"ref":{"doc":"MI","page":23}},{"id":"mi-144","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, may an adult driver use the phone's GPS map while driving?","o":["Yes, and they may type an address at a red light","No, maps are never allowed","Yes, if they do not type in information by hand","Only on freeways"],"h1":"Watching is fine; typing is the problem.","h2":"In Michigan, drivers may use a GPS or navigation feature as long as they do not enter information by hand while driving.","p":"Correct. GPS is fine if you do not type by hand."},"es":{"q":"En Michigan, ¿puede un conductor adulto usar el mapa GPS del teléfono mientras maneja?","o":["Sí, y puede escribir una dirección en un semáforo en rojo","No, los mapas nunca se permiten","Sí, si no escribe información con la mano","Solo en autopistas"],"h1":"Mirar está bien; escribir es el problema.","h2":"En Michigan, los conductores pueden usar el GPS o la navegación siempre que no escriban información con la mano mientras manejan.","p":"Correcto. El GPS está bien si no escribe con la mano."},"ref":{"doc":"MI","page":24}},{"id":"mi-145","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, an adult driver uses a phone in hands-free mode. What may they do with their hand?","o":["Tap or swipe once to start or end a function","Scroll through messages","Type a short text","Hold the phone to their ear"],"h1":"One single touch is the limit.","h2":"In Michigan, a driver using hands-free mode may press, tap or swipe one time to turn a function on or off or to pick a name or number.","p":"Right. One tap or swipe only."},"es":{"q":"En Michigan, un conductor adulto usa el teléfono en modo manos libres. ¿Qué puede hacer con la mano?","o":["Tocar o deslizar una vez para iniciar o terminar una función","Desplazarse por los mensajes","Escribir un texto corto","Sostener el teléfono en la oreja"],"h1":"Un solo toque es el límite.","h2":"En Michigan, un conductor en modo manos libres puede presionar, tocar o deslizar una vez para activar o desactivar una función o elegir un nombre o número.","p":"Correcto. Solo un toque o deslizamiento."},"ref":{"doc":"MI","page":24}},{"id":"mi-146","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, a 16-year-old with a Level 2 license sees a driver who seems drunk. May the teen use a phone to report it?","o":["No, teens may never use a phone while driving","Only after parking for 10 minutes","Only with an adult in the car","Yes, to call 911 or police about an emergency"],"h1":"The emergency rule covers every driver.","h2":"In Michigan, all drivers, including teens, may use a phone while driving to call or text 911 or the police to report an emergency, such as a drunk or reckless driver.","p":"Correct. Reporting an emergency is allowed."},"es":{"q":"En Michigan, un joven de 16 años con licencia de Nivel 2 ve a un conductor que parece borracho. ¿Puede usar el teléfono para reportarlo?","o":["No, los jóvenes nunca pueden usar el teléfono al manejar","Solo después de estacionarse 10 minutos","Solo si va un adulto en el auto","Sí, para llamar al 911 o a la policía por una emergencia"],"h1":"La regla de emergencias incluye a todos los conductores.","h2":"En Michigan, todos los conductores, incluidos los jóvenes, pueden usar el teléfono al manejar para llamar o escribir al 911 o a la policía y reportar una emergencia, como un conductor borracho o imprudente.","p":"Correcto. Reportar una emergencia está permitido."},"ref":{"doc":"MI","page":24}},{"id":"mi-147","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, who in the front seat must wear a seat belt?","o":["Only the driver","Everyone in the front seat, including the driver","Only passengers under 16","Only on freeways"],"h1":"Age does not matter in the front.","h2":"In Michigan, the driver and all front-seat passengers must be buckled up.","p":"Correct. Everyone in the front seat."},"es":{"q":"En Michigan, ¿quién en el asiento delantero debe usar el cinturón de seguridad?","o":["Solo el conductor","Todos en el asiento delantero, incluido el conductor","Solo los pasajeros menores de 16 años","Solo en autopistas"],"h1":"En el frente, la edad no importa.","h2":"En Michigan, el conductor y todos los pasajeros del asiento delantero deben usar el cinturón.","p":"Correcto. Todos en el asiento delantero."},"ref":{"doc":"MI","page":25}},{"id":"mi-148","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, may a police officer stop your car only because someone is not buckled up?","o":["No, only if you also break another law","Yes, the officer may stop you for that alone","Only on freeways","Only if a child is unbuckled"],"h1":"Think of \"Click It or Ticket.\"","h2":"In Michigan, a police officer may stop a vehicle if the driver or passengers are not properly buckled up.","p":"Right. An officer may stop you for that alone."},"es":{"q":"En Michigan, ¿puede un policía detener su auto solo porque alguien no lleva el cinturón?","o":["No, solo si también viola otra ley","Sí, el policía puede detenerlo solo por eso","Solo en autopistas","Solo si un niño no lleva cinturón"],"h1":"Piense en \"Click It or Ticket\".","h2":"En Michigan, un policía puede detener un vehículo si el conductor o los pasajeros no llevan bien puesto el cinturón.","p":"Correcto. Pueden detenerlo solo por eso."},"ref":{"doc":"MI","page":25}},{"id":"mi-149","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, a driver cannot wear a seat belt because of a medical condition. What must they carry?","o":["A disability license plate","A note from their insurance company","Nothing; they just explain it","A doctor's statement"],"h1":"Proof must come from a medical professional.","h2":"In Michigan, a driver exempt from wearing a seat belt for a medical reason must carry a doctor's statement.","p":"Correct. A doctor's statement."},"es":{"q":"En Michigan, un conductor no puede usar el cinturón por una condición médica. ¿Qué debe llevar consigo?","o":["Una placa de discapacidad","Una nota de su compañía de seguros","Nada; solo lo explica","Una declaración de un médico"],"h1":"La prueba debe venir de un profesional médico.","h2":"En Michigan, un conductor exento de usar cinturón por razones médicas debe llevar una declaración de su médico.","p":"Correcto. Una declaración del médico."},"ref":{"doc":"MI","page":25}},{"id":"mi-150","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, where must a child under age 4 ride if the vehicle has a back seat?","o":["In a car seat in the back seat","In the front seat on an adult's lap","In any seat with a lap belt","In the front seat with the air bag on"],"h1":"The safest place is away from the dashboard.","h2":"In Michigan, children under 4 must ride in a car seat in a rear seat if the vehicle has one, unless all rear seats are already used by children under 4.","p":"Right. In a car seat in the back seat."},"es":{"q":"En Michigan, ¿dónde debe ir un niño menor de 4 años si el vehículo tiene asiento trasero?","o":["En una silla de auto en el asiento trasero","En el asiento delantero en las piernas de un adulto","En cualquier asiento con cinturón de cadera","En el asiento delantero con la bolsa de aire activada"],"h1":"El lugar más seguro está lejos del tablero.","h2":"En Michigan, los niños menores de 4 años deben ir en una silla de auto en el asiento trasero si el vehículo tiene uno, salvo que todos los asientos traseros ya estén ocupados por niños menores de 4.","p":"Correcto. En una silla de auto en el asiento trasero."},"ref":{"doc":"MI","page":25}},{"id":"mi-151","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, when may a baby in a rear-facing car seat ride in the front seat?","o":["Only on short trips","Only if an adult sits in the back","Only if the front passenger air bag is turned off","Whenever the parent is driving"],"h1":"An air bag can hit the back of the seat.","h2":"In Michigan, a child in a rear-facing car seat may ride in the front seat only if the front passenger air bag is deactivated.","p":"Correct. Only with the passenger air bag turned off."},"es":{"q":"En Michigan, ¿cuándo puede ir en el asiento delantero un bebé en una silla mirando hacia atrás?","o":["Solo en viajes cortos","Solo si un adulto va atrás","Solo si la bolsa de aire del pasajero está desactivada","Siempre que maneje el padre"],"h1":"Una bolsa de aire puede golpear la parte de atrás de la silla.","h2":"En Michigan, un niño en silla mirando hacia atrás puede ir en el asiento delantero solo si la bolsa de aire del pasajero está desactivada.","p":"Correcto. Solo con la bolsa de aire del pasajero desactivada."},"ref":{"doc":"MI","page":25}},{"id":"mi-152","scope":"MI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Michigan, may a parent take a baby out of a car seat to nurse while the car is moving?","o":["Yes, if the car is under 25 mph","Yes, in the back seat","No, it is against the law","Yes, on short trips"],"h1":"The child must stay secured while the vehicle moves.","h2":"In Michigan, it is illegal to take a child out of a car seat to nurse while the vehicle is moving.","p":"Right. It is not allowed."},"es":{"q":"En Michigan, ¿puede un padre sacar a un bebé de la silla de auto para amamantarlo mientras el auto está en marcha?","o":["Sí, si el auto va a menos de 25 mph","Sí, en el asiento trasero","No, va contra la ley","Sí, en viajes cortos"],"h1":"El niño debe seguir asegurado mientras el vehículo se mueve.","h2":"En Michigan, es ilegal sacar a un niño de la silla de auto para amamantarlo mientras el vehículo está en marcha.","p":"Correcto. No está permitido."},"ref":{"doc":"MI","page":25}},{"id":"mi-153","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, it is illegal to leave a child alone in a vehicle when it poses an unreasonable risk. This law covers children under what age?","o":["6","3","10","12"],"h1":"It covers young children not yet in grade school.","h2":"In Michigan, it is illegal to leave a child younger than 6 unattended in a vehicle when the time or conditions pose an unreasonable risk of harm.","p":"Correct. Children under 6."},"es":{"q":"En Michigan, es ilegal dejar a un niño solo en un vehículo cuando eso es un riesgo irrazonable. ¿A niños menores de qué edad se aplica esta ley?","o":["6 años","3 años","10 años","12 años"],"h1":"Se aplica a niños pequeños que aún no van a la primaria.","h2":"En Michigan, es ilegal dejar solo en un vehículo a un niño menor de 6 años cuando el tiempo o las condiciones son un riesgo irrazonable.","p":"Correcto. Menores de 6 años."},"ref":{"doc":"MI","page":26}},{"id":"mi-154","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, a parent runs into a store and leaves a 4-year-old in the car with a sibling. How old must the sibling be for this to be legal?","o":["10 or older","16 or older","18 or older","13 or older"],"h1":"The sibling must be a teenager.","h2":"In Michigan, leaving a young child in a vehicle under the supervision of someone 13 or older who is not legally incapacitated does not break the law.","p":"Right. The sibling must be 13 or older."},"es":{"q":"En Michigan, un padre entra rápido a una tienda y deja a un niño de 4 años en el auto con un hermano. ¿Qué edad debe tener el hermano para que sea legal?","o":["10 años o más","16 años o más","18 años o más","13 años o más"],"h1":"El hermano debe ser adolescente.","h2":"En Michigan, dejar a un niño pequeño en el vehículo bajo la supervisión de alguien de 13 años o más, que no esté legalmente incapacitado, no viola la ley.","p":"Correcto. El hermano debe tener 13 años o más."},"ref":{"doc":"MI","page":26}},{"id":"mi-155","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, how much space is recommended between the center of your breastbone and the center of the steering wheel?","o":["At least 2 inches","At least 10 inches","At least 5 inches","At least 20 inches"],"h1":"It protects you from the air bag.","h2":"In Michigan, drivers are advised to sit with at least 10 inches between the center of the breastbone and the center of the steering wheel.","p":"Correct. At least 10 inches."},"es":{"q":"En Michigan, ¿cuánto espacio se recomienda entre el centro de su esternón y el centro del volante?","o":["Al menos 2 pulgadas","Al menos 10 pulgadas","Al menos 5 pulgadas","Al menos 20 pulgadas"],"h1":"Lo protege de la bolsa de aire.","h2":"En Michigan, se recomienda sentarse con al menos 10 pulgadas entre el centro del esternón y el centro del volante.","p":"Correcto. Al menos 10 pulgadas."},"ref":{"doc":"MI","page":26}},{"id":"mi-156","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, children up to what age are best seated in the back seat to avoid air bag injuries?","o":["5 and younger","12 and younger","8 and younger","16 and younger"],"h1":"It goes up to the end of grade school.","h2":"In Michigan, parents are encouraged to seat all children 12 and younger in the rear seat to avoid injury from an air bag.","p":"Right. Children 12 and younger."},"es":{"q":"En Michigan, ¿hasta qué edad es mejor que los niños vayan atrás para evitar lesiones por la bolsa de aire?","o":["5 años o menos","12 años o menos","8 años o menos","16 años o menos"],"h1":"Llega hasta el final de la primaria.","h2":"En Michigan, se recomienda que todos los niños de 12 años o menos vayan en el asiento trasero para evitar lesiones por la bolsa de aire.","p":"Correcto. Niños de 12 años o menos."},"ref":{"doc":"MI","page":26}},{"id":"mi-157","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, on a freeway with a 70 mph limit, what is the top speed for trucks and school buses?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"It is a little lower than for cars.","h2":"In Michigan, school buses and trucks are limited to 65 mph on freeways where cars may go 70.","p":"Correct. 65 mph."},"es":{"q":"En Michigan, en una autopista con límite de 70 mph, ¿cuál es la velocidad máxima para camiones y autobuses escolares?","o":["55 mph","60 mph","70 mph","65 mph"],"h1":"Es un poco menos que para los autos.","h2":"En Michigan, los autobuses escolares y los camiones tienen un límite de 65 mph en autopistas donde los autos pueden ir a 70.","p":"Correcto. 65 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-158","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, unless signs say otherwise, what is the minimum speed on a freeway?","o":["55 mph","40 mph","45 mph","60 mph"],"h1":"It is the same number as the usual limit on other highways.","h2":"In Michigan, freeways have a 55 mph minimum speed unless posted otherwise.","p":"Right. The minimum is 55 mph."},"es":{"q":"En Michigan, salvo que las señales digan otra cosa, ¿cuál es la velocidad mínima en una autopista?","o":["55 mph","40 mph","45 mph","60 mph"],"h1":"Es el mismo número que el límite normal de otras carreteras.","h2":"En Michigan, las autopistas tienen una velocidad mínima de 55 mph, salvo que se indique otra cosa.","p":"Correcto. La mínima es 55 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-159","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, a freeway is posted at 65 mph for cars. What is the speed limit there for trucks and school buses?","o":["60 mph","65 mph","55 mph","45 mph"],"h1":"On these slower freeways, trucks drop to the usual highway limit.","h2":"In Michigan, on freeways with speed limits under 70 mph, school buses and trucks are restricted to 55 mph.","p":"Correct. 55 mph."},"es":{"q":"En Michigan, una autopista tiene un límite de 65 mph para autos. ¿Cuál es el límite allí para camiones y autobuses escolares?","o":["60 mph","65 mph","55 mph","45 mph"],"h1":"En estas autopistas más lentas, los camiones bajan al límite normal de carretera.","h2":"En Michigan, en autopistas con límite menor de 70 mph, los autobuses escolares y los camiones tienen un límite de 55 mph.","p":"Correcto. 55 mph."},"ref":{"doc":"MI","page":26}},{"id":"mi-160","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, the Basic Speed Law says you must drive at a \"careful and prudent\" speed. What does that mean in heavy snow?","o":["You must always drive the posted limit","You may go 5 mph over to keep up","You may need to drive slower than the posted limit","You must stop until the snow ends"],"h1":"The posted limit is the most you may go, not a target.","h2":"In Michigan, the Basic Speed Law means a speed that lets you stop within the clear distance ahead; it is never above the posted limit and may need to be slower in bad conditions.","p":"Right. You may need to drive slower than the limit."},"es":{"q":"En Michigan, la Ley Básica de Velocidad dice que debe manejar a una velocidad \"cuidadosa y prudente\". ¿Qué significa eso con nieve fuerte?","o":["Siempre debe ir al límite indicado","Puede ir 5 mph más rápido para seguir el tráfico","Puede que deba manejar más despacio que el límite indicado","Debe parar hasta que termine la nieve"],"h1":"El límite indicado es lo máximo, no una meta.","h2":"En Michigan, la Ley Básica de Velocidad pide una velocidad que le permita parar dentro de la distancia libre que ve; nunca es mayor que el límite y puede ser menor con mal tiempo.","p":"Correcto. Puede que deba ir más despacio que el límite."},"ref":{"doc":"MI","page":26}},{"id":"mi-161","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, you pass a work zone sign that says \"Where Workers Present 45.\" Workers are on the road. How fast may you go?","o":["45 mph or slower","The normal posted limit","55 mph","35 mph exactly"],"h1":"The sign tells you when the lower limit applies.","h2":"In Michigan, in a work zone posted \"Where Workers Present 45,\" you must slow to 45 mph or lower when workers are present; when they are gone, the normal limit applies.","p":"Correct. 45 mph or slower while workers are present."},"es":{"q":"En Michigan, usted pasa una señal de zona de obras que dice \"Where Workers Present 45\". Hay trabajadores en la vía. ¿A qué velocidad puede ir?","o":["45 mph o menos","El límite normal indicado","55 mph","Exactamente 35 mph"],"h1":"La señal le dice cuándo aplica el límite más bajo.","h2":"En Michigan, en una zona de obras con la señal \"Where Workers Present 45\", debe bajar a 45 mph o menos cuando hay trabajadores; cuando no hay, aplica el límite normal.","p":"Correcto. 45 mph o menos mientras haya trabajadores."},"ref":{"doc":"MI","page":27}},{"id":"mi-162","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, you are caught going 8 mph over the limit in a construction zone. How many points go on your record?","o":["Two points","Four points","Five points","Three points"],"h1":"Work zones add more points than the same speed elsewhere.","h2":"In Michigan, speeding 10 mph or less over the limit in a work zone adds three points to your driving record.","p":"Right. Three points in a work zone."},"es":{"q":"En Michigan, lo detienen por ir 8 mph por encima del límite en una zona de construcción. ¿Cuántos puntos se ponen en su historial?","o":["Dos puntos","Cuatro puntos","Cinco puntos","Tres puntos"],"h1":"Las zonas de obras suman más puntos que la misma velocidad en otro lugar.","h2":"En Michigan, ir 10 mph o menos por encima del límite en una zona de obras suma tres puntos a su historial.","p":"Correcto. Tres puntos en zona de obras."},"ref":{"doc":"MI","page":27}},{"id":"mi-163","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, you are caught going 20 mph over the limit in a construction zone. How many points go on your record?","o":["Three points","Five points","Four points","Six points"],"h1":"It is one point more than the same speed outside a work zone.","h2":"In Michigan, speeding more than 15 mph over the limit in a work zone adds five points to your driving record.","p":"Correct. Five points."},"es":{"q":"En Michigan, lo detienen por ir 20 mph por encima del límite en una zona de construcción. ¿Cuántos puntos se ponen en su historial?","o":["Tres puntos","Cinco puntos","Cuatro puntos","Seis puntos"],"h1":"Es un punto más que la misma velocidad fuera de una zona de obras.","h2":"En Michigan, ir más de 15 mph por encima del límite en una zona de obras suma cinco puntos a su historial.","p":"Correcto. Cinco puntos."},"ref":{"doc":"MI","page":27}},{"id":"mi-164","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, a driver injures a worker in a work zone. Up to what fine can the driver face?","o":["$500","$7,500","$1,000","$2,500"],"h1":"It is several thousand dollars, along with possible prison time.","h2":"In Michigan, causing injury or death to a person in a work zone can bring fines of up to $7,500 and up to 15 years in prison.","p":"Correct. Up to $7,500."},"es":{"q":"En Michigan, un conductor hiere a un trabajador en una zona de obras. ¿Hasta qué multa puede recibir?","o":["$500","$7,500","$1,000","$2,500"],"h1":"Son varios miles de dólares, además de posible cárcel.","h2":"En Michigan, causar heridas o la muerte a una persona en una zona de obras puede traer multas de hasta $7,500 y hasta 15 años de prisión.","p":"Correcto. Hasta $7,500."},"ref":{"doc":"MI","page":27}},{"id":"mi-165","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, a construction worker waves you through, but the traffic light in the work zone is red. What should you do?","o":["Wait for the light to turn green","Honk and wait","Turn around","Follow the worker's directions"],"h1":"Workers have authority in their zone.","h2":"In Michigan, construction workers may direct traffic in work zones, and their directions must be followed even if they conflict with a traffic signal.","p":"Right. Follow the worker."},"es":{"q":"En Michigan, un trabajador de construcción le hace señas para pasar, pero el semáforo de la zona de obras está en rojo. ¿Qué debe hacer?","o":["Esperar a que el semáforo cambie a verde","Tocar la bocina y esperar","Darse la vuelta","Seguir las indicaciones del trabajador"],"h1":"Los trabajadores tienen autoridad en su zona.","h2":"En Michigan, los trabajadores de construcción pueden dirigir el tránsito en las zonas de obras, y hay que seguir sus indicaciones aunque contradigan un semáforo.","p":"Correcto. Siga al trabajador."},"ref":{"doc":"MI","page":27}},{"id":"mi-166","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, you see a truck with flashing green lights along with amber lights. What is it?","o":["A state or local road maintenance vehicle doing road work","A police car in a chase","A funeral escort","A private tow truck"],"h1":"Michigan allows green lights for road agencies only.","h2":"In Michigan, flashing green lights are used on state and local road maintenance vehicles only while road work is taking place, so slow down and drive with caution.","p":"Correct. A road maintenance vehicle at work."},"es":{"q":"En Michigan, usted ve un camión con luces verdes intermitentes junto con luces ámbar. ¿Qué es?","o":["Un vehículo de mantenimiento vial estatal o local haciendo obras","Una patrulla en persecución","Una escolta de funeral","Una grúa privada"],"h1":"Michigan permite luces verdes solo a las agencias de caminos.","h2":"En Michigan, las luces verdes intermitentes se usan en vehículos de mantenimiento vial estatales y locales solo mientras hacen trabajos en la vía; baje la velocidad y maneje con cuidado.","p":"Correcto. Un vehículo de mantenimiento vial trabajando."},"ref":{"doc":"MI","page":27}},{"id":"mi-167","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, you pulled over and stopped for an ambulance with lights and siren. What should you do with your feet while you wait?","o":["Rest both feet on the floor","Keep a foot on the gas to be ready","Keep a foot on the brake so your brake lights show","Put the car in neutral and coast"],"h1":"Let the emergency driver see that you have stopped.","h2":"In Michigan, after pulling over for an emergency vehicle, keep your foot on the brake so your brake lights tell the driver you have stopped.","p":"Right. Keep your foot on the brake."},"es":{"q":"En Michigan, usted se orilló y se detuvo por una ambulancia con luces y sirena. ¿Qué debe hacer con los pies mientras espera?","o":["Poner los dos pies en el piso","Mantener un pie en el acelerador para estar listo","Mantener un pie en el freno para que se vean las luces de freno","Poner el auto en neutral y rodar"],"h1":"Deje que el conductor de emergencia vea que usted se detuvo.","h2":"En Michigan, después de orillarse por un vehículo de emergencia, mantenga el pie en el freno para que las luces de freno le indiquen al conductor que usted se detuvo.","p":"Correcto. Mantenga el pie en el freno."},"ref":{"doc":"MI","page":28}},{"id":"mi-168","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, a fire truck with flashing lights is moving slowly ahead of you. When may you pass it?","o":["When it goes under 25 mph","When the road has two lanes in your direction","Only if its driver or a police officer directs you to","When you have an urgent reason"],"h1":"You need permission from the right people.","h2":"In Michigan, never pass a moving emergency vehicle with flashing lights unless its driver or a law enforcement officer directs you to.","p":"Correct. Only when directed by its driver or police."},"es":{"q":"En Michigan, un camión de bomberos con luces intermitentes avanza despacio delante de usted. ¿Cuándo puede rebasarlo?","o":["Cuando va a menos de 25 mph","Cuando la vía tiene dos carriles en su dirección","Solo si su conductor o un policía se lo indica","Cuando usted tiene prisa"],"h1":"Necesita permiso de las personas indicadas.","h2":"En Michigan, nunca rebase un vehículo de emergencia en movimiento con luces intermitentes, salvo que su conductor o un policía se lo indique.","p":"Correcto. Solo si su conductor o la policía lo indica."},"ref":{"doc":"MI","page":28}},{"id":"mi-169","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, a driver fails to move over or slow down for a stopped police car and injures the officer. What is the charge?","o":["A felony","A civil infraction only","A parking ticket","A warning"],"h1":"Hurting emergency personnel makes it much more serious.","h2":"In Michigan, failing to obey the move-over law for an emergency vehicle is a civil infraction, but it becomes a felony if emergency personnel are injured or killed.","p":"Right. It is a felony."},"es":{"q":"En Michigan, un conductor no se cambia de carril ni baja la velocidad por una patrulla detenida y hiere al policía. ¿Cuál es el cargo?","o":["Un delito grave (felony)","Solo una infracción civil","Una multa de estacionamiento","Una advertencia"],"h1":"Herir al personal de emergencia lo hace mucho más grave.","h2":"En Michigan, no cumplir la ley de cambiarse de carril por un vehículo de emergencia es una infracción civil, pero se vuelve delito grave si se hiere o mata al personal de emergencia.","p":"Correcto. Es un delito grave."},"ref":{"doc":"MI","page":28}},{"id":"mi-170","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, a driver fails to slow down and move over for a stopped garbage truck with flashing lights. What type of offense is it?","o":["A felony","No offense at all","Only a warning","A misdemeanor"],"h1":"For these work vehicles, it is a criminal offense, but not the most serious kind.","h2":"In Michigan, failing to obey the move-over law for solid waste haulers, utility vehicles and road maintenance vehicles is a misdemeanor.","p":"Correct. It is a misdemeanor."},"es":{"q":"En Michigan, un conductor no baja la velocidad ni se cambia de carril por un camión de basura detenido con luces intermitentes. ¿Qué tipo de falta es?","o":["Un delito grave","Ninguna falta","Solo una advertencia","Un delito menor (misdemeanor)"],"h1":"Para estos vehículos de trabajo es un delito, pero no del tipo más grave.","h2":"En Michigan, no cumplir la ley de cambiarse de carril por camiones de basura, vehículos de servicios públicos y de mantenimiento vial es un delito menor.","p":"Correcto. Es un delito menor."},"ref":{"doc":"MI","page":28}},{"id":"mi-171","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, how does the fine for failing to stop for a school bus compare with a normal moving violation?","o":["It is the same","It is double","It is half","There is no fine, only points"],"h1":"The law treats school buses very seriously.","h2":"In Michigan, fines for failing to stop for a school bus are double what would normally be charged for a moving violation.","p":"Right. The fine is doubled."},"es":{"q":"En Michigan, ¿cómo se compara la multa por no detenerse ante un autobús escolar con la de una infracción normal en movimiento?","o":["Es la misma","Es el doble","Es la mitad","No hay multa, solo puntos"],"h1":"La ley toma muy en serio los autobuses escolares.","h2":"En Michigan, las multas por no detenerse ante un autobús escolar son el doble de lo que se cobra normalmente por una infracción en movimiento.","p":"Correcto. La multa se duplica."},"ref":{"doc":"MI","page":28}},{"id":"mi-172","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, you stopped behind a school bus with flashing red lights. When may you go again?","o":["After waiting 30 seconds","When the red lights turn off or the bus starts moving","When the children reach the sidewalk","When the driver waves at you"],"h1":"Watch the bus, not a clock.","h2":"In Michigan, remain stopped until the school bus turns off its flashing red lights or starts moving again.","p":"Correct. When the red lights go off or the bus moves on."},"es":{"q":"En Michigan, usted se detuvo detrás de un autobús escolar con luces rojas intermitentes. ¿Cuándo puede seguir?","o":["Después de esperar 30 segundos","Cuando se apagan las luces rojas o el autobús empieza a moverse","Cuando los niños llegan a la acera","Cuando el chofer le hace una seña"],"h1":"Fíjese en el autobús, no en el reloj.","h2":"En Michigan, quédese detenido hasta que el autobús escolar apague las luces rojas intermitentes o vuelva a avanzar.","p":"Correcto. Cuando se apagan las luces rojas o el autobús avanza."},"ref":{"doc":"MI","page":29}},{"id":"mi-173","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, the yellow overhead lights on a school bus are flashing. What should you do?","o":["Speed up and pass quickly","Stop at least 20 feet away right now","Nothing; they mean nothing to drivers","Get ready to stop"],"h1":"Yellow comes before red.","h2":"In Michigan, flashing yellow overhead lights on a school bus mean be prepared to stop, because the red lights are about to come on.","p":"Right. Get ready to stop."},"es":{"q":"En Michigan, las luces amarillas de arriba de un autobús escolar están intermitentes. ¿Qué debe hacer?","o":["Acelerar y rebasar rápido","Detenerse ya a por lo menos 20 pies","Nada; no significan nada para los conductores","Prepararse para detenerse"],"h1":"El amarillo viene antes que el rojo.","h2":"En Michigan, las luces amarillas intermitentes de arriba de un autobús escolar significan que debe prepararse para detenerse, porque pronto se encenderán las rojas.","p":"Correcto. Prepárese para detenerse."},"ref":{"doc":"MI","page":29}},{"id":"mi-174","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, which vehicles may cut into or go ahead of a funeral procession?","o":["Fire trucks, ambulances and police vehicles","Buses and taxis","Any vehicle with its hazard lights on","Delivery trucks"],"h1":"Only vehicles answering emergencies.","h2":"In Michigan, funeral processions have the right of way over all other vehicles except fire trucks, ambulances and police vehicles.","p":"Correct. Only fire trucks, ambulances and police."},"es":{"q":"En Michigan, ¿qué vehículos pueden pasar delante o atravesar un cortejo fúnebre?","o":["Camiones de bomberos, ambulancias y patrullas","Autobuses y taxis","Cualquier vehículo con luces de emergencia","Camiones de reparto"],"h1":"Solo los vehículos que atienden emergencias.","h2":"En Michigan, los cortejos fúnebres tienen el derecho de paso sobre todos los vehículos, menos los camiones de bomberos, las ambulancias y las patrullas.","p":"Correcto. Solo bomberos, ambulancias y policía."},"ref":{"doc":"MI","page":31}},{"id":"mi-175","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, you see a funeral procession coming toward you on the other side of the road. What does the law require?","o":["Pull over and stop until it passes","Turn on your headlights and join it","Respect it, but you do not have to pull over; never cut through it","Honk once to show respect"],"h1":"Cutting through it is the problem.","h2":"In Michigan, drivers are not required to pull over for a funeral procession, but cutting through one is a civil infraction.","p":"Right. You need not pull over, but never cut through it."},"es":{"q":"En Michigan, usted ve un cortejo fúnebre que viene en sentido contrario. ¿Qué exige la ley?","o":["Orillarse y detenerse hasta que pase","Prender las luces y unirse","Respetarlo, pero no tiene que orillarse; nunca lo atraviese","Tocar la bocina una vez en señal de respeto"],"h1":"Atravesarlo es el problema.","h2":"En Michigan, los conductores no están obligados a orillarse por un cortejo fúnebre, pero atravesarlo es una infracción civil.","p":"Correcto. No tiene que orillarse, pero nunca lo atraviese."},"ref":{"doc":"MI","page":31}},{"id":"mi-176","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, you are passing a car on a two-lane road. When may you move back into the right lane?","o":["As soon as your front bumper is past it","When you have passed its front door","When you can see the whole car you passed in your rearview mirror","After counting to two"],"h1":"Use your inside mirror as the check.","h2":"In Michigan, do not cut back into the right lane until you can see the entire vehicle you passed in your rearview mirror.","p":"Correct. When the whole car shows in your rearview mirror."},"es":{"q":"En Michigan, usted rebasa a un auto en una carretera de dos carriles. ¿Cuándo puede volver al carril derecho?","o":["En cuanto su defensa delantera lo pasa","Cuando pasó su puerta delantera","Cuando ve todo el auto que rebasó en el espejo retrovisor","Después de contar hasta dos"],"h1":"Use el espejo de adentro para comprobarlo.","h2":"En Michigan, no vuelva al carril derecho hasta que pueda ver todo el vehículo que rebasó en su espejo retrovisor.","p":"Correcto. Cuando todo el auto aparece en el retrovisor."},"ref":{"doc":"MI","page":32}},{"id":"mi-177","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, your view is blocked as you near a bridge or tunnel. Within what distance of it may you not pass?","o":["100 feet","50 feet","300 feet","500 feet"],"h1":"It is the same distance as for intersections.","h2":"In Michigan, you may not pass when your view is blocked within 100 feet of a bridge, viaduct or tunnel.","p":"Right. Within 100 feet."},"es":{"q":"En Michigan, su vista está bloqueada al acercarse a un puente o túnel. ¿Dentro de qué distancia no puede rebasar?","o":["100 pies","50 pies","300 pies","500 pies"],"h1":"Es la misma distancia que para las intersecciones.","h2":"En Michigan, no puede rebasar cuando su vista está bloqueada a menos de 100 pies de un puente, viaducto o túnel.","p":"Correcto. A menos de 100 pies."},"ref":{"doc":"MI","page":32}},{"id":"mi-178","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, a car in the next lane has stopped at a crosswalk. What should you do?","o":["Pass it carefully on the left","Pass it if you honk first","Pass it if the light is green","Do not pass it; a person may be crossing"],"h1":"The stopped car may be hiding someone.","h2":"In Michigan, you may not pass a vehicle that has stopped at a crosswalk or intersection to let a pedestrian cross.","p":"Correct. Do not pass it."},"es":{"q":"En Michigan, un auto en el carril de al lado se detuvo en un cruce peatonal. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Rebasarlo si toca la bocina antes","Rebasarlo si el semáforo está en verde","No rebasarlo; puede haber alguien cruzando"],"h1":"El auto detenido puede ocultar a alguien.","h2":"En Michigan, no puede rebasar un vehículo que se detuvo en un cruce peatonal o intersección para dejar cruzar a un peatón.","p":"Correcto. No lo rebase."},"ref":{"doc":"MI","page":32}},{"id":"mi-179","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, passing on the right is allowed in some cases. Where may you never drive to do it?","o":["In a second lane going your way","On the shoulder or off the road","On a one-way street","Around a car turning left"],"h1":"You must stay on the traveled road.","h2":"In Michigan, you may pass on the right only in certain cases, and never by driving on the shoulder or off the road.","p":"Right. Never on the shoulder or off the road."},"es":{"q":"En Michigan, rebasar por la derecha se permite en algunos casos. ¿Por dónde nunca puede manejar para hacerlo?","o":["Por un segundo carril en su dirección","Por el acotamiento o fuera de la vía","En una calle de un solo sentido","Alrededor de un auto que gira a la izquierda"],"h1":"Debe quedarse en la vía de circulación.","h2":"En Michigan, solo puede rebasar por la derecha en ciertos casos, y nunca manejando por el acotamiento o fuera de la vía.","p":"Correcto. Nunca por el acotamiento ni fuera de la vía."},"ref":{"doc":"MI","page":32}},{"id":"mi-180","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, a divided road has a paved cut-through in the median with no signs against using it. May you use it to turn left?","o":["No, it is for police only","Yes, you may","Only at night","Only if you are a truck"],"h1":"Look for signs; here there are none.","h2":"In Michigan, if a median cut-through is paved and no signs prohibit it, you may use it to make a left turn.","p":"Correct. You may use it."},"es":{"q":"En Michigan, una vía dividida tiene un cruce pavimentado en el camellón sin señales que lo prohíban. ¿Puede usarlo para girar a la izquierda?","o":["No, es solo para la policía","Sí, puede","Solo de noche","Solo si es un camión"],"h1":"Busque señales; aquí no hay ninguna.","h2":"En Michigan, si un cruce en el camellón está pavimentado y ninguna señal lo prohíbe, puede usarlo para girar a la izquierda.","p":"Correcto. Puede usarlo."},"ref":{"doc":"MI","page":33}},{"id":"mi-181","scope":"MI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Michigan, you are stopped in a line of traffic before railroad tracks. How much room must there be past the tracks before you cross?","o":["Enough for half your car","At least 1 foot","No room needed if no train is coming","Enough to clear the far rail by at least 6 feet"],"h1":"Trains are wider than the rails.","h2":"In Michigan, never cross the tracks unless there is enough space for your vehicle to clear the far side of the tracks by at least 6 feet.","p":"Right. At least 6 feet past the far side."},"es":{"q":"En Michigan, usted está en una fila de tráfico antes de unas vías del tren. ¿Cuánto espacio debe haber después de las vías antes de cruzar?","o":["Suficiente para la mitad de su auto","Al menos 1 pie","No hace falta si no viene tren","Suficiente para quedar al menos 6 pies más allá del último riel"],"h1":"Los trenes son más anchos que los rieles.","h2":"En Michigan, nunca cruce las vías si no hay espacio para que su vehículo quede al menos 6 pies más allá del otro lado de las vías.","p":"Correcto. Al menos 6 pies más allá del otro lado."},"ref":{"doc":"MI","page":36}},{"id":"mi-182","scope":"MI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Michigan, once the lights and gates at a railroad crossing turn on, about how much time do you have before the train arrives?","o":["About 20 seconds","About 2 minutes","About 5 seconds","About 1 minute"],"h1":"It is less than half a minute.","h2":"In Michigan, once railroad crossing lights and gates are activated, you have about 20 seconds before the train arrives.","p":"Correct. About 20 seconds."},"es":{"q":"En Michigan, cuando se activan las luces y barreras de un cruce de tren, ¿cuánto tiempo tiene más o menos antes de que llegue el tren?","o":["Unos 20 segundos","Unos 2 minutos","Unos 5 segundos","Un minuto"],"h1":"Es menos de medio minuto.","h2":"En Michigan, cuando se activan las luces y barreras del cruce, tiene unos 20 segundos antes de que llegue el tren.","p":"Correcto. Unos 20 segundos."},"ref":{"doc":"MI","page":36}},{"id":"mi-183","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, which vehicle must stop at every railroad crossing, even with no stop sign or signal, unless marked otherwise?","o":["A motorcycle","A pickup truck","A school bus","A car pulling a small trailer"],"h1":"Think of vehicles carrying children or dangerous cargo.","h2":"In Michigan, school buses, vehicles carrying passengers for hire, and gasoline or hazardous material trucks must stop at railroad crossings and check for trains, unless clearly marked otherwise.","p":"Right. A school bus must stop."},"es":{"q":"En Michigan, ¿qué vehículo debe detenerse en todos los cruces de tren, aunque no haya señal de alto ni semáforo, salvo que se indique otra cosa?","o":["Una motocicleta","Una camioneta pickup","Un autobús escolar","Un auto con un remolque pequeño"],"h1":"Piense en vehículos que llevan niños o carga peligrosa.","h2":"En Michigan, los autobuses escolares, los vehículos que llevan pasajeros por pago y los camiones de gasolina o materiales peligrosos deben detenerse en los cruces de tren y revisar, salvo que se indique otra cosa.","p":"Correcto. Un autobús escolar debe detenerse."},"ref":{"doc":"MI","page":36}},{"id":"mi-184","scope":"MI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Michigan, how close may you park to a fire or a crash scene?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 500 feet","No closer than 1,000 feet"],"h1":"It is the same distance used for dimming high beams.","h2":"In Michigan, you may not park within 500 feet of a fire or a crash.","p":"Correct. No closer than 500 feet."},"es":{"q":"En Michigan, ¿qué tan cerca de un incendio o de un choque puede estacionarse?","o":["A no menos de 50 pies","A no menos de 100 pies","A no menos de 500 pies","A no menos de 1,000 pies"],"h1":"Es la misma distancia que se usa para bajar las luces altas.","h2":"En Michigan, no puede estacionarse a menos de 500 pies de un incendio o de un choque.","p":"Correcto. A no menos de 500 pies."},"ref":{"doc":"MI","page":38}},{"id":"mi-185","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, you want to park on the same side of the street as a fire station driveway. How far away must you be?","o":["At least 20 feet","At least 5 feet","At least 50 feet","At least 75 feet"],"h1":"The larger distance applies across the street.","h2":"In Michigan, you may not park within 20 feet of a fire station driveway on the same side of the street, or within 75 feet on the other side when marked.","p":"Right. At least 20 feet on the same side."},"es":{"q":"En Michigan, quiere estacionarse en el mismo lado de la calle que la entrada de una estación de bomberos. ¿A qué distancia debe estar?","o":["Al menos 20 pies","Al menos 5 pies","Al menos 50 pies","Al menos 75 pies"],"h1":"La distancia mayor se aplica del otro lado de la calle.","h2":"En Michigan, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos en el mismo lado de la calle, ni a menos de 75 pies del otro lado cuando está señalado.","p":"Correcto. Al menos 20 pies en el mismo lado."},"ref":{"doc":"MI","page":38}},{"id":"mi-186","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, how close may you park to a stop sign or traffic light?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 50 feet","No closer than 30 feet"],"h1":"Parked cars must not hide the sign or light.","h2":"In Michigan, you may not park within 30 feet of a stop sign, traffic light or flashing beacon.","p":"Correct. No closer than 30 feet."},"es":{"q":"En Michigan, ¿qué tan cerca de una señal de alto o de un semáforo puede estacionarse?","o":["A no menos de 10 pies","A no menos de 15 pies","A no menos de 50 pies","A no menos de 30 pies"],"h1":"Los autos estacionados no deben tapar la señal ni el semáforo.","h2":"En Michigan, no puede estacionarse a menos de 30 pies de una señal de alto, un semáforo o una luz intermitente.","p":"Correcto. A no menos de 30 pies."},"ref":{"doc":"MI","page":38}},{"id":"mi-187","scope":"MI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Michigan, how close may you park to a marked crosswalk?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 10 feet","No closer than 50 feet"],"h1":"It is a bit more than the distance from a hydrant.","h2":"In Michigan, you may not park within 20 feet of a marked crosswalk, or within 15 feet of an intersection with no crosswalk.","p":"Right. No closer than 20 feet."},"es":{"q":"En Michigan, ¿qué tan cerca de un cruce peatonal marcado puede estacionarse?","o":["A no menos de 5 pies","A no menos de 20 pies","A no menos de 10 pies","A no menos de 50 pies"],"h1":"Es un poco más que la distancia de un hidrante.","h2":"En Michigan, no puede estacionarse a menos de 20 pies de un cruce peatonal marcado, ni a menos de 15 pies de una intersección sin cruce peatonal.","p":"Correcto. A no menos de 20 pies."},"ref":{"doc":"MI","page":39}},{"id":"mi-188","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, when must your headlights be on at night?","o":["Only after 10 p.m.","From a half hour after sunset to a half hour before sunrise","From sunset to sunrise only on highways","Only when it is fully dark"],"h1":"There is a 30-minute buffer on each end.","h2":"In Michigan, headlights must be on from one half hour after sunset until one half hour before sunrise, and whenever visibility is reduced.","p":"Correct. A half hour after sunset to a half hour before sunrise."},"es":{"q":"En Michigan, ¿cuándo deben estar encendidas sus luces delanteras de noche?","o":["Solo después de las 10 p.m.","Desde media hora después de la puesta del sol hasta media hora antes del amanecer","Del atardecer al amanecer solo en carreteras","Solo cuando está totalmente oscuro"],"h1":"Hay un margen de 30 minutos en cada extremo.","h2":"En Michigan, las luces deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer, y siempre que haya poca visibilidad.","p":"Correcto. De media hora después del atardecer a media hora antes del amanecer."},"ref":{"doc":"MI","page":64}},{"id":"mi-189","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, on dry or wet pavement in normal conditions, what following distance does the handbook call for?","o":["1 to 2 seconds","6 to 8 seconds","10 seconds","3 to 4 seconds"],"h1":"Count \"one-thousand one, one-thousand two...\" from a fixed point.","h2":"In Michigan, a following distance of 3 to 4 seconds is required in normal driving on dry or wet pavement.","p":"Correct. 3 to 4 seconds."},"es":{"q":"En Michigan, en pavimento seco o mojado y condiciones normales, ¿qué distancia de seguimiento pide el manual?","o":["De 1 a 2 segundos","De 6 a 8 segundos","10 segundos","De 3 a 4 segundos"],"h1":"Cuente \"mil uno, mil dos...\" desde un punto fijo.","h2":"En Michigan, se requiere una distancia de seguimiento de 3 a 4 segundos al manejar normalmente en pavimento seco o mojado.","p":"Correcto. De 3 a 4 segundos."},"ref":{"doc":"MI","page":64}},{"id":"mi-190","scope":"MI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Michigan, you are driving at high speed in a snowstorm. How much following distance may you need?","o":["Up to 6 seconds or more","Exactly 2 seconds","1 second less than normal","No change is needed"],"h1":"Bad conditions call for more time than the normal rule.","h2":"In Michigan, when speeds are higher or conditions are bad, increase your following distance up to 6 seconds or more if needed.","p":"Right. Up to 6 seconds or more."},"es":{"q":"En Michigan, usted maneja a alta velocidad en una tormenta de nieve. ¿Cuánta distancia de seguimiento puede necesitar?","o":["Hasta 6 segundos o más","Exactamente 2 segundos","1 segundo menos de lo normal","No hace falta cambiarla"],"h1":"Las malas condiciones piden más tiempo que la regla normal.","h2":"En Michigan, cuando la velocidad es mayor o las condiciones son malas, aumente la distancia de seguimiento hasta 6 segundos o más si hace falta.","p":"Correcto. Hasta 6 segundos o más."},"ref":{"doc":"MI","page":64}},{"id":"mi-191","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, you are behind a horse-drawn buggy. How far back should you stay?","o":["At least 5 feet","At least 100 feet","At least 20 feet","At least 500 feet"],"h1":"It is about one car length plus a little more.","h2":"In Michigan, when following a horse and rider or a horse-drawn buggy, slow to 15 to 20 mph and stay at least 20 feet back so you do not scare the horse.","p":"Correct. At least 20 feet."},"es":{"q":"En Michigan, usted va detrás de una carreta tirada por caballos. ¿A qué distancia debe quedarse?","o":["Al menos 5 pies","Al menos 100 pies","Al menos 20 pies","Al menos 500 pies"],"h1":"Es un poco más que el largo de un auto.","h2":"En Michigan, al seguir a un jinete o a una carreta de caballos, baje a 15 o 20 mph y quédese al menos a 20 pies para no asustar al caballo.","p":"Correcto. Al menos 20 pies."},"ref":{"doc":"MI","page":54}},{"id":"mi-192","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, what is the top speed a moped can reach on a level road, by law?","o":["20 mph","45 mph","30 mph","55 mph"],"h1":"It is slower than most city speed limits on main roads.","h2":"In Michigan, a moped cannot go faster than 30 mph on a level surface and has an engine of 100 cc or less.","p":"Right. 30 mph."},"es":{"q":"En Michigan, ¿cuál es la velocidad máxima que puede alcanzar un ciclomotor (moped) en terreno plano, según la ley?","o":["20 mph","45 mph","30 mph","55 mph"],"h1":"Es menos que el límite de muchas calles principales.","h2":"En Michigan, un ciclomotor no puede ir a más de 30 mph en terreno plano y tiene un motor de 100 cc o menos.","p":"Correcto. 30 mph."},"ref":{"doc":"MI","page":56}},{"id":"mi-193","scope":"MI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Michigan, what engine size must a motorcycle have to be ridden on a freeway?","o":["125 cc or more","50 cc or more","250 cc or more","Any size"],"h1":"Smaller motorcycles, up to 124 cc, are kept off freeways.","h2":"In Michigan, motorcycles with engines of 125 cc or more may be ridden on freeways; those of 124 cc or less may not.","p":"Correct. 125 cc or more."},"es":{"q":"En Michigan, ¿qué tamaño de motor debe tener una motocicleta para usarse en autopista?","o":["125 cc o más","50 cc o más","250 cc o más","Cualquier tamaño"],"h1":"Las motos pequeñas, de hasta 124 cc, no pueden ir en autopista.","h2":"En Michigan, las motocicletas con motor de 125 cc o más pueden ir en autopista; las de 124 cc o menos no.","p":"Correcto. 125 cc o más."},"ref":{"doc":"MI","page":56}},{"id":"mi-194","scope":"MI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Michigan, during its posted hours, how many people must be in a car to use a High Occupancy Vehicle (HOV) lane?","o":["Three or more","Four or more","Just the driver","Two or more"],"h1":"The driver counts.","h2":"In Michigan, a vehicle needs two or more occupants to use an HOV lane during its hours; motorcycles may use it at any time.","p":"Right. Two or more people."},"es":{"q":"En Michigan, durante su horario, ¿cuántas personas deben ir en un auto para usar un carril de alta ocupación (HOV)?","o":["Tres o más","Cuatro o más","Solo el conductor","Dos o más"],"h1":"El conductor cuenta.","h2":"En Michigan, un vehículo necesita dos o más ocupantes para usar un carril HOV en su horario; las motocicletas pueden usarlo en cualquier momento.","p":"Correcto. Dos o más personas."},"ref":{"doc":"MI","page":61}},{"id":"mi-195","scope":"MI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Michigan, on a long freeway trip, how often should you take a short break if you feel tired?","o":["Every six hours","At least every two hours","Only when you need gas","Once a day"],"h1":"A 10-minute stop is suggested.","h2":"In Michigan, if you feel tired on a long trip, stop for a 10-minute break at least every two hours.","p":"Correct. At least every two hours."},"es":{"q":"En Michigan, en un viaje largo por autopista, ¿cada cuánto debe tomar un descanso corto si se siente cansado?","o":["Cada seis horas","Al menos cada dos horas","Solo cuando necesite gasolina","Una vez al día"],"h1":"Se sugiere una parada de 10 minutos.","h2":"En Michigan, si se siente cansado en un viaje largo, haga un descanso de 10 minutos al menos cada dos horas.","p":"Correcto. Al menos cada dos horas."},"ref":{"doc":"MI","page":62}},{"id":"mi-196","scope":"MI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Michigan, an orange triangle on the back of a vehicle marks a slow-moving vehicle. How fast can such vehicles go?","o":["No faster than 10 mph","No faster than 25 mph","No faster than 40 mph","No faster than 55 mph"],"h1":"Think of tractors and Amish buggies.","h2":"In Michigan, a slow-moving vehicle with the orange triangle cannot travel faster than 25 mph.","p":"Right. No faster than 25 mph."},"es":{"q":"En Michigan, un triángulo naranja en la parte de atrás de un vehículo indica un vehículo lento. ¿A qué velocidad pueden ir esos vehículos?","o":["A no más de 10 mph","A no más de 25 mph","A no más de 40 mph","A no más de 55 mph"],"h1":"Piense en tractores y carretas amish.","h2":"En Michigan, un vehículo lento con el triángulo naranja no puede ir a más de 25 mph.","p":"Correcto. A no más de 25 mph."},"ref":{"doc":"MI","page":54}},{"id":"mi-197","scope":"MI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Michigan, it is cloudy and getting dark. At what point must your headlights be on, even before the usual time?","o":["When you cannot see 50 feet ahead","Only when it rains","Only after the streetlights come on","When you cannot clearly see people and vehicles 500 feet away"],"h1":"It is a distance check.","h2":"In Michigan, headlights must be on any time there is not enough light to see people and vehicles clearly at 500 feet.","p":"Correct. When you cannot see clearly at 500 feet."},"es":{"q":"En Michigan, está nublado y oscureciendo. ¿En qué momento deben estar encendidas sus luces, aun antes de la hora normal?","o":["Cuando no puede ver a 50 pies","Solo cuando llueve","Solo cuando se encienden las luces de la calle","Cuando no puede ver bien personas y vehículos a 500 pies"],"h1":"Es una prueba de distancia.","h2":"En Michigan, las luces deben estar encendidas siempre que no haya luz suficiente para ver con claridad personas y vehículos a 500 pies.","p":"Correcto. Cuando no puede ver bien a 500 pies."},"ref":{"doc":"MI","page":64}},{"id":"mi-198","scope":"MI","cat":"signals","sign":null,"c":0,"en":{"q":"In Michigan, you reach a Michigan Left median crossover that has no lane markings. How should you treat it?","o":["As a single lane, one vehicle turning at a time","As two lanes, side by side","As a parking area","As a place to pass slow cars"],"h1":"The extra width is for big trucks.","h2":"In Michigan, an unmarked median crossover should always be treated as a single-lane crossover, with one vehicle turning at a time.","p":"Right. Treat it as one lane."},"es":{"q":"En Michigan, usted llega a un cruce de camellón de \"Michigan Left\" sin marcas de carril. ¿Cómo debe usarlo?","o":["Como un solo carril, con un vehículo girando a la vez","Como dos carriles, lado a lado","Como zona de estacionamiento","Como lugar para rebasar autos lentos"],"h1":"El ancho extra es para camiones grandes.","h2":"En Michigan, un cruce de camellón sin marcas siempre se trata como de un solo carril, con un vehículo girando a la vez.","p":"Correcto. Trátelo como un solo carril."},"ref":{"doc":"MI","page":48}},{"id":"mi-199","scope":"MI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Michigan, a car going 55 mph can stop in about 130 feet. About how far does a large commercial truck need at the same speed?","o":["About 130 feet","About 200 feet","About 400 feet","About 1,000 feet"],"h1":"It is about three times as far.","h2":"In Michigan, a commercial vehicle traveling at 55 mph takes about 400 feet to stop, compared with about 130 feet for a car.","p":"Correct. About 400 feet."},"es":{"q":"En Michigan, un auto a 55 mph puede detenerse en unos 130 pies. ¿Cuánto necesita más o menos un camión comercial grande a la misma velocidad?","o":["Unos 130 pies","Unos 200 pies","Unos 400 pies","Unos 1,000 pies"],"h1":"Es como tres veces más.","h2":"En Michigan, un vehículo comercial a 55 mph necesita unos 400 pies para detenerse, comparado con unos 130 pies de un auto.","p":"Correcto. Unos 400 pies."},"ref":{"doc":"MI","page":53}},{"id":"mi-200","scope":"MI","cat":"signals","sign":null,"c":2,"en":{"q":"In Michigan, may you cut through a gas station or store parking lot to avoid a red light?","o":["Yes, if you do not stop","Yes, if the lot is empty","No, it is illegal","Yes, if you are turning right"],"h1":"Traffic signals cannot be dodged this way.","h2":"In Michigan, it is illegal to drive across public or private property, such as a parking lot, to avoid a traffic-control device.","p":"Right. It is illegal."},"es":{"q":"En Michigan, ¿puede atravesar el estacionamiento de una gasolinera o tienda para evitar un semáforo en rojo?","o":["Sí, si no se detiene","Sí, si el estacionamiento está vacío","No, es ilegal","Sí, si va a girar a la derecha"],"h1":"Los semáforos no se pueden evitar así.","h2":"En Michigan, es ilegal cruzar una propiedad pública o privada, como un estacionamiento, para evitar un dispositivo de control de tránsito.","p":"Correcto. Es ilegal."},"ref":{"doc":"MI","page":49}},{"id":"mn-001","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"You can get a Minnesota instruction permit at 15 after starting driver education, so you can practice before the provisional license at 16.","p":"Right. The Minnesota permit starts at 15."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener un permiso de aprendizaje?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"Usted puede obtener el permiso de aprendizaje en Minnesota a los 15 años después de empezar la educación vial, para practicar antes de la licencia provisional a los 16.","p":"Correcto. El permiso en Minnesota empieza a los 15."},"zh":{"q":"在 Minnesota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比临时驾照早一年。","h2":"你在 15 岁开始上驾驶教育课以后，就可以拿到 Minnesota 的学习驾照，这样你在 16 岁拿临时驾照前可以先练习。","p":"对。Minnesota 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Minnesota, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi lấy bằng lái tạm thời.","h2":"Bạn có thể lấy giấy phép tập lái ở Minnesota khi 15 tuổi, sau khi bắt đầu học lái xe, để tập lái trước khi lấy bằng lái tạm thời lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Minnesota bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Minnesota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang provisional license.","h2":"Puwede kang kumuha ng instruction permit sa Minnesota sa edad na 15 pagkatapos magsimula ng driver education, para makapagsanay ka bago ang provisional license sa edad na 16.","p":"Tama. Ang permit sa Minnesota ay nagsisimula sa 15."},"ar":{"q":"في Minnesota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل الرخصة المؤقتة بسنة واحدة.","h2":"يمكنك الحصول على تصريح التعلّم في Minnesota في سن 15 بعد بدء دروس تعليم القيادة، حتى تتدرّب قبل الرخصة المؤقتة في سن 16.","p":"صحيح. يبدأ تصريح التعلّم في Minnesota في سن 15."},"ref":{"doc":"MN","page":13}},{"id":"mn-002","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how old must the licensed driver be who supervises a permit holder under 18?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The helper must be an adult who can legally drink.","h2":"A Minnesota permit holder under 18 must drive with a licensed driver who is at least 21, so an experienced adult is guiding them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Minnesota, ¿qué edad debe tener el conductor con licencia que supervisa a alguien con permiso menor de 18?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene permiso en Minnesota y es menor de 18 debe manejar con un conductor con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Minnesota，陪同 18 岁以下持学习驾照的人开车的有驾照司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"陪同的人必须是在法律上可以喝酒的成年人。","h2":"在 Minnesota，18 岁以下持学习驾照的人必须和至少 21 岁、有驾照的司机一起开车，这样有一位有经验的成年人指导他们。","p":"对。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở Minnesota, người lái xe có bằng đi kèm người giữ giấy phép tập lái dưới 18 tuổi phải bao nhiêu tuổi?","o":["Ít nhất 16","Ít nhất 18","Ít nhất 21","Ít nhất 25"],"h1":"Người đi kèm phải là người lớn được phép uống rượu theo luật.","h2":"Người giữ giấy phép tập lái ở Minnesota dưới 18 tuổi phải lái cùng một người có bằng lái từ 21 tuổi trở lên, để có người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Minnesota, ilang taon dapat ang lisensyadong driver na nagbabantay sa may permit na wala pang 18?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ang katulong ay dapat adult na legal nang uminom ng alak.","h2":"Ang may permit sa Minnesota na wala pang 18 ay dapat magmaneho kasama ang lisensyadong driver na hindi bababa sa 21 taong gulang, para may bihasang adult na gumagabay sa kanya.","p":"Tama. Ang nagbabantay ay dapat 21 o mas matanda."},"ar":{"q":"في Minnesota، كم يجب أن يكون عمر السائق المرخَّص الذي يرافق حامل تصريح التعلّم الذي عمره أقل من 18 سنة؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يجب أن يكون المرافق بالغًا يسمح له القانون بشرب الكحول.","h2":"يجب على حامل تصريح التعلّم في Minnesota الذي عمره أقل من 18 سنة أن يقود مع سائق مرخَّص عمره 21 سنة على الأقل، حتى يرشده شخص بالغ ذو خبرة.","p":"صحيح. يجب أن يكون المرافق عمره 21 سنة أو أكثر."},"ref":{"doc":"MN","page":13}},{"id":"mn-003","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, where must the supervising driver sit when a permit holder is driving?","o":["In the front passenger seat","In the back seat","Anywhere in the vehicle","Behind the driver"],"h1":"They must be close enough to help at once.","h2":"The supervising driver must sit in the front passenger seat when a Minnesota permit holder drives, so they can see the road and help quickly.","p":"Right. The supervisor sits in the front passenger seat."},"es":{"q":"En Minnesota, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento del pasajero delantero","En el asiento de atrás","En cualquier lugar del vehículo","Detrás del conductor"],"h1":"Debe estar lo bastante cerca para ayudar enseguida.","h2":"El conductor supervisor debe sentarse en el asiento del pasajero delantero cuando maneja alguien con permiso en Minnesota, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor va en el asiento delantero."},"zh":{"q":"在 Minnesota，持学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排乘客座位","后排座位","车里任何地方","司机后面"],"h1":"他们必须离得够近，能马上帮忙。","h2":"Minnesota 持学习驾照的人开车时，陪同的司机必须坐在前排乘客座位，这样他们能看到道路并很快帮忙。","p":"对。陪同的人坐在前排乘客座位。"},"vi":{"q":"Ở Minnesota, người lái xe giám sát phải ngồi ở đâu khi người giữ giấy phép tập lái đang lái?","o":["Ở ghế hành khách phía trước","Ở ghế sau","Ở bất cứ chỗ nào trong xe","Phía sau người lái"],"h1":"Họ phải ngồi đủ gần để giúp ngay.","h2":"Người lái xe giám sát phải ngồi ở ghế hành khách phía trước khi người giữ giấy phép tập lái ở Minnesota lái xe, để họ thấy đường và giúp nhanh.","p":"Đúng. Người giám sát ngồi ở ghế hành khách phía trước."},"tl":{"q":"Sa Minnesota, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan ng pasahero sa harap","Sa likod na upuan","Kahit saan sa sasakyan","Sa likod ng driver"],"h1":"Dapat malapit sila para makatulong agad.","h2":"Ang nagbabantay na driver ay dapat umupo sa upuan ng pasahero sa harap kapag nagmamaneho ang may permit sa Minnesota, para makita nila ang daan at makatulong agad.","p":"Tama. Ang nagbabantay ay umuupo sa upuan ng pasahero sa harap."},"ar":{"q":"في Minnesota، أين يجب أن يجلس السائق المرافق عندما يقود حامل تصريح التعلّم؟","o":["في مقعد الراكب الأمامي","في المقعد الخلفي","في أي مكان في السيارة","خلف السائق"],"h1":"يجب أن يكون قريبًا بما يكفي ليساعد فورًا.","h2":"يجب أن يجلس السائق المرافق في مقعد الراكب الأمامي عندما يقود حامل تصريح التعلّم في Minnesota، حتى يرى الطريق ويساعد بسرعة.","p":"صحيح. يجلس المرافق في مقعد الراكب الأمامي."},"ref":{"doc":"MN","page":13}},{"id":"mn-004","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how long must a teen hold an instruction permit before applying for a provisional license?","o":["1 month","3 months","1 year","6 months"],"h1":"It is half a year.","h2":"A Minnesota teen must hold the instruction permit for the six months right before applying, with no serious traffic convictions.","p":"Right. Hold the permit for six months."},"es":{"q":"En Minnesota, ¿cuánto tiempo debe tener un adolescente el permiso de aprendizaje antes de solicitar la licencia provisional?","o":["1 mes","3 meses","1 año","6 meses"],"h1":"Es medio año.","h2":"Un adolescente en Minnesota debe tener el permiso de aprendizaje durante los seis meses justo antes de solicitar, sin condenas graves de tránsito.","p":"Correcto. Debe tener el permiso seis meses."},"zh":{"q":"在 Minnesota，青少年必须持有学习驾照多久，才能申请临时驾照？","o":["1 个月","3 个月","1 年","6 个月"],"h1":"是半年。","h2":"Minnesota 的青少年在申请前的六个月里必须一直持有学习驾照，而且没有严重的交通违法定罪。","p":"对。持有学习驾照六个月。"},"vi":{"q":"Ở Minnesota, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi xin bằng lái tạm thời (provisional license)?","o":["1 tháng","3 tháng","1 năm","6 tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Minnesota phải giữ giấy phép tập lái trong sáu tháng ngay trước khi nộp đơn, và không bị kết tội vi phạm giao thông nghiêm trọng.","p":"Đúng. Giữ giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Minnesota, gaano katagal dapat hawak ng teen ang instruction permit bago mag-apply para sa provisional license (pansamantalang lisensya)?","o":["1 buwan","3 buwan","1 taon","6 na buwan"],"h1":"Kalahating taon ito.","h2":"Ang teen sa Minnesota ay dapat may hawak ng instruction permit sa loob ng anim na buwan bago mismo mag-apply, nang walang mabigat na traffic conviction.","p":"Tama. Hawakan ang permit nang anim na buwan."},"ar":{"q":"في Minnesota، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل أن يتقدّم بطلب الرخصة المؤقتة (provisional license)؟","o":["شهر واحد","3 أشهر","سنة واحدة","6 أشهر"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Minnesota أن يحمل تصريح التعلّم لمدة ستة أشهر قبل التقديم مباشرة، دون إدانات مرورية خطيرة.","p":"صحيح. احمل التصريح لمدة ستة أشهر."},"ref":{"doc":"MN","page":14}},{"id":"mn-005","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, which of these can stop a teen from getting a provisional license after six months on a permit?","o":["Getting a parking ticket","A moving violation conviction","Having a passenger in the car","Driving at night with a parent"],"h1":"The six months must be clean of driving offenses.","h2":"A Minnesota teen must have no convictions for moving violations or alcohol and drug offenses during the six months on the permit.","p":"Right. A moving violation conviction can delay the provisional license."},"es":{"q":"En Minnesota, ¿cuál de estas cosas puede impedir que un adolescente obtenga la licencia provisional después de seis meses con permiso?","o":["Recibir una multa de estacionamiento","Una condena por una infracción en movimiento","Llevar un pasajero en el carro","Manejar de noche con un padre"],"h1":"Los seis meses deben estar limpios de infracciones al manejar.","h2":"Un adolescente en Minnesota no debe tener condenas por infracciones de tránsito en movimiento ni por alcohol o drogas durante los seis meses con el permiso.","p":"Correcto. Una infracción en movimiento puede retrasar la licencia provisional."},"zh":{"q":"在 Minnesota，持学习驾照六个月以后，下面哪一项会让青少年拿不到临时驾照？","o":["收到一张停车罚单","一次行车违规定罪","车里有乘客","和父母一起在晚上开车"],"h1":"这六个月里不能有驾驶违法记录。","h2":"Minnesota 的青少年在持学习驾照的六个月里，不能有行车违规定罪，也不能有酒精或毒品违法定罪。","p":"对。行车违规定罪会推迟拿临时驾照。"},"vi":{"q":"Ở Minnesota, điều nào sau đây có thể làm thiếu niên không lấy được bằng lái tạm thời sau sáu tháng giữ giấy phép tập lái?","o":["Bị phạt vì đậu xe sai","Bị kết tội vi phạm khi đang lái (moving violation)","Có hành khách trong xe","Lái xe ban đêm với cha mẹ"],"h1":"Sáu tháng đó phải không có lỗi khi lái xe.","h2":"Thiếu niên ở Minnesota không được bị kết tội vi phạm khi đang lái, hoặc tội liên quan đến rượu và ma túy, trong sáu tháng giữ giấy phép tập lái.","p":"Đúng. Bị kết tội vi phạm khi đang lái có thể làm chậm việc lấy bằng lái tạm thời."},"tl":{"q":"Sa Minnesota, alin dito ang puwedeng pumigil sa teen na makakuha ng provisional license pagkatapos ng anim na buwan na may permit?","o":["Pagkakaroon ng parking ticket","Conviction sa moving violation (paglabag habang nagmamaneho)","Pagkakaroon ng pasahero sa kotse","Pagmamaneho sa gabi kasama ang magulang"],"h1":"Ang anim na buwan ay dapat malinis sa paglabag sa pagmamaneho.","h2":"Ang teen sa Minnesota ay dapat walang conviction sa moving violation o sa paglabag tungkol sa alak at droga sa loob ng anim na buwan na may permit.","p":"Tama. Ang conviction sa moving violation ay puwedeng magpaantala sa provisional license."},"ar":{"q":"في Minnesota، أيّ مما يلي قد يمنع المراهق من الحصول على الرخصة المؤقتة بعد ستة أشهر مع تصريح التعلّم؟","o":["الحصول على مخالفة وقوف","إدانة بمخالفة أثناء القيادة (moving violation)","وجود راكب في السيارة","القيادة ليلًا مع أحد الوالدين"],"h1":"يجب أن تكون الأشهر الستة خالية من مخالفات القيادة.","h2":"يجب ألا يكون لدى المراهق في Minnesota أي إدانة بمخالفات أثناء القيادة أو بمخالفات الكحول والمخدرات خلال الأشهر الستة مع تصريح التعلّم.","p":"صحيح. الإدانة بمخالفة أثناء القيادة قد تؤخّر الرخصة المؤقتة."},"ref":{"doc":"MN","page":14}},{"id":"mn-006","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the instruction permit.","h2":"A Minnesota teen can get a provisional license at 16 after holding an instruction permit for six months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Minnesota, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después del permiso de aprendizaje.","h2":"Un adolescente en Minnesota puede obtener la licencia provisional a los 16 años después de tener el permiso de aprendizaje seis meses.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Minnesota，最小几岁可以拿到临时驾照（provisional license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它在学习驾照以后一年。","h2":"Minnesota 的青少年持有学习驾照六个月以后，16 岁就可以拿到临时驾照。","p":"对。临时驾照从 16 岁开始。"},"vi":{"q":"Ở Minnesota, tuổi nhỏ nhất để lấy bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là một năm sau khi lấy giấy phép tập lái.","h2":"Thiếu niên ở Minnesota có thể lấy bằng lái tạm thời khi 16 tuổi, sau khi giữ giấy phép tập lái sáu tháng.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Minnesota, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng instruction permit.","h2":"Ang teen sa Minnesota ay puwedeng makakuha ng provisional license sa edad na 16 pagkatapos hawakan ang instruction permit nang anim na buwan.","p":"Tama. Ang provisional license ay nagsisimula sa 16."},"ar":{"q":"في Minnesota، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"إنه بعد تصريح التعلّم بسنة واحدة.","h2":"يمكن للمراهق في Minnesota الحصول على الرخصة المؤقتة في سن 16 بعد حمل تصريح التعلّم لمدة ستة أشهر.","p":"صحيح. تبدأ الرخصة المؤقتة في سن 16."},"ref":{"doc":"MN","page":14}},{"id":"mn-007","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, if the parent does not take the supplemental parent class, how many supervised hours must a teen log?","o":["30 hours","40 hours","60 hours","50 hours"],"h1":"The parent class lowers this number by ten.","h2":"Without the supplemental parent class, a Minnesota teen must log at least 50 hours of supervised driving, with at least 15 at night.","p":"Right. Without the parent class, the teen logs 50 hours."},"es":{"q":"En Minnesota, si el padre no toma la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","60 horas","50 horas"],"h1":"La clase para padres baja este número en diez.","h2":"Sin la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 50 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Sin la clase para padres, el adolescente registra 50 horas."},"zh":{"q":"在 Minnesota，如果父母没有上家长补充课，青少年必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","60 小时","50 小时"],"h1":"家长课会让这个数字减少十。","h2":"父母没有上家长补充课时，Minnesota 的青少年必须记录至少 50 小时有人监督的驾驶，其中至少 15 小时在晚上。","p":"对。父母没上课，青少年要记录 50 小时。"},"vi":{"q":"Ở Minnesota, nếu cha mẹ không học lớp bổ sung cho cha mẹ (supplemental parent class), thiếu niên phải ghi lại bao nhiêu giờ lái có giám sát?","o":["30 giờ","40 giờ","60 giờ","50 giờ"],"h1":"Lớp học cho cha mẹ làm con số này giảm đi mười.","h2":"Nếu cha mẹ không học lớp bổ sung, thiếu niên ở Minnesota phải ghi lại ít nhất 50 giờ lái có giám sát, trong đó ít nhất 15 giờ vào ban đêm.","p":"Đúng. Không có lớp học cho cha mẹ, thiếu niên ghi lại 50 giờ."},"tl":{"q":"Sa Minnesota, kung hindi kukunin ng magulang ang supplemental parent class (dagdag na klase para sa magulang), ilang oras ng binantayang pagmamaneho ang dapat itala ng teen?","o":["30 oras","40 oras","60 oras","50 oras"],"h1":"Binabawasan ng klase para sa magulang ang bilang na ito ng sampu.","h2":"Kung walang supplemental parent class, ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 50 oras ng binantayang pagmamaneho, at hindi bababa sa 15 dito ay sa gabi.","p":"Tama. Kung walang klase para sa magulang, 50 oras ang itatala ng teen."},"ar":{"q":"في Minnesota، إذا لم يحضر أحد الوالدين الدرس الإضافي للوالدين (supplemental parent class)، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق؟","o":["30 ساعة","40 ساعة","60 ساعة","50 ساعة"],"h1":"الدرس الخاص بالوالدين يُنقص هذا العدد بعشر.","h2":"دون الدرس الإضافي للوالدين، يجب على المراهق في Minnesota أن يسجّل 50 ساعة على الأقل من القيادة تحت الإشراف، منها 15 ساعة على الأقل في الليل.","p":"صحيح. دون درس الوالدين، يسجّل المراهق 50 ساعة."},"ref":{"doc":"MN","page":14}},{"id":"mn-008","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, if a parent completes the supplemental parent class, how many supervised hours must the teen log?","o":["30 hours","40 hours","50 hours","60 hours"],"h1":"It is ten fewer than without the class.","h2":"When a parent completes the supplemental parent class, a Minnesota teen must log at least 40 hours of supervised driving, with at least 15 at night.","p":"Right. With the parent class, the teen logs 40 hours."},"es":{"q":"En Minnesota, si un padre completa la clase complementaria para padres, ¿cuántas horas supervisadas debe registrar el adolescente?","o":["30 horas","40 horas","50 horas","60 horas"],"h1":"Son diez menos que sin la clase.","h2":"Cuando un padre completa la clase complementaria para padres, un adolescente en Minnesota debe registrar por lo menos 40 horas de manejo supervisado, con por lo menos 15 de noche.","p":"Correcto. Con la clase para padres, el adolescente registra 40 horas."},"zh":{"q":"在 Minnesota，如果父母上完了家长补充课，青少年必须记录多少小时有人监督的驾驶？","o":["30 小时","40 小时","50 小时","60 小时"],"h1":"比没有上课时少十小时。","h2":"父母上完家长补充课时，Minnesota 的青少年必须记录至少 40 小时有人监督的驾驶，其中至少 15 小时在晚上。","p":"对。父母上了课，青少年要记录 40 小时。"},"vi":{"q":"Ở Minnesota, nếu cha mẹ học xong lớp bổ sung cho cha mẹ (supplemental parent class), thiếu niên phải ghi lại bao nhiêu giờ lái có giám sát?","o":["30 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Ít hơn mười giờ so với khi không học lớp này.","h2":"Khi cha mẹ học xong lớp bổ sung, thiếu niên ở Minnesota phải ghi lại ít nhất 40 giờ lái có giám sát, trong đó ít nhất 15 giờ vào ban đêm.","p":"Đúng. Có lớp học cho cha mẹ, thiếu niên ghi lại 40 giờ."},"tl":{"q":"Sa Minnesota, kung natapos ng magulang ang supplemental parent class (dagdag na klase para sa magulang), ilang oras ng binantayang pagmamaneho ang dapat itala ng teen?","o":["30 oras","40 oras","50 oras","60 oras"],"h1":"Sampung oras itong mas kaunti kaysa kung walang klase.","h2":"Kapag natapos ng magulang ang supplemental parent class, ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 40 oras ng binantayang pagmamaneho, at hindi bababa sa 15 dito ay sa gabi.","p":"Tama. Kung may klase para sa magulang, 40 oras ang itatala ng teen."},"ar":{"q":"في Minnesota، إذا أكمل أحد الوالدين الدرس الإضافي للوالدين (supplemental parent class)، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق؟","o":["30 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنها أقل بعشر ساعات مما يلزم دون الدرس.","h2":"عندما يكمل أحد الوالدين الدرس الإضافي، يجب على المراهق في Minnesota أن يسجّل 40 ساعة على الأقل من القيادة تحت الإشراف، منها 15 ساعة على الأقل في الليل.","p":"صحيح. مع درس الوالدين، يسجّل المراهق 40 ساعة."},"ref":{"doc":"MN","page":14}},{"id":"mn-009","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how many of the supervised practice hours must be at night?","o":["5 hours","10 hours","15 hours","20 hours"],"h1":"The number is the same with or without the parent class.","h2":"A Minnesota teen must log at least 15 hours of supervised driving at night, whether or not a parent took the supplemental class.","p":"Right. At least 15 hours must be at night."},"es":{"q":"En Minnesota, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","15 horas","20 horas"],"h1":"El número es el mismo con o sin la clase para padres.","h2":"Un adolescente en Minnesota debe registrar por lo menos 15 horas de manejo supervisado de noche, haya tomado o no un padre la clase complementaria.","p":"Correcto. Por lo menos 15 horas deben ser de noche."},"zh":{"q":"在 Minnesota，有人监督的练习时间中，有多少小时必须在晚上？","o":["5 小时","10 小时","15 小时","20 小时"],"h1":"不管父母有没有上家长课，这个数字都一样。","h2":"不管父母有没有上补充课，Minnesota 的青少年都必须记录至少 15 小时在晚上有人监督的驾驶。","p":"对。至少 15 小时必须在晚上。"},"vi":{"q":"Ở Minnesota, bao nhiêu giờ tập lái có giám sát phải là vào ban đêm?","o":["5 giờ","10 giờ","15 giờ","20 giờ"],"h1":"Con số này giống nhau dù có hay không có lớp học cho cha mẹ.","h2":"Thiếu niên ở Minnesota phải ghi lại ít nhất 15 giờ lái có giám sát vào ban đêm, dù cha mẹ có học lớp bổ sung hay không.","p":"Đúng. Ít nhất 15 giờ phải là vào ban đêm."},"tl":{"q":"Sa Minnesota, ilan sa mga oras ng binantayang pagsasanay ang dapat sa gabi?","o":["5 oras","10 oras","15 oras","20 oras"],"h1":"Pareho ang bilang, may klase man o wala para sa magulang.","h2":"Ang teen sa Minnesota ay dapat magtala ng hindi bababa sa 15 oras ng binantayang pagmamaneho sa gabi, kumuha man o hindi ng dagdag na klase ang magulang.","p":"Tama. Hindi bababa sa 15 oras ang dapat sa gabi."},"ar":{"q":"في Minnesota، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","10 ساعات","15 ساعة","20 ساعة"],"h1":"العدد نفسه مع درس الوالدين أو بدونه.","h2":"يجب على المراهق في Minnesota أن يسجّل 15 ساعة على الأقل من القيادة الليلية تحت الإشراف، سواء حضر أحد الوالدين الدرس الإضافي أم لا.","p":"صحيح. 15 ساعة على الأقل يجب أن تكون في الليل."},"ref":{"doc":"MN","page":14}},{"id":"mn-010","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, during the first six months of a provisional license, when may a teen NOT drive alone?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit begins when a new day starts.","h2":"For the first six months of a Minnesota provisional license, a teen may not drive from midnight to 5 a.m., unless a licensed driver 25 or older is along or the trip is for work or a school event.","p":"Right. No driving from midnight to 5 a.m. at first."},"es":{"q":"En Minnesota, durante los primeros seis meses de la licencia provisional, ¿en qué horario NO puede manejar solo el adolescente?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Durante los primeros seis meses de la licencia provisional en Minnesota, el adolescente no puede manejar de medianoche a las 5 a.m., salvo que lo acompañe un conductor con licencia de 25 años o más o que el viaje sea por trabajo o por un evento escolar.","p":"Correcto. Al principio no se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，青少年在什么时间不能单独开车？","o":["午夜到早上 5 点","晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","晚上 11 点到凌晨 4 点"],"h1":"限制从新的一天开始时开始。","h2":"持 Minnesota 临时驾照的前六个月，青少年在午夜到早上 5 点不能开车，除非有 25 岁或以上、有驾照的司机同车，或者是为了工作或学校活动。","p":"对。一开始，午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên KHÔNG được lái một mình vào lúc nào?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu khi một ngày mới bắt đầu.","h2":"Trong sáu tháng đầu có bằng lái tạm thời ở Minnesota, thiếu niên không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có người có bằng lái từ 25 tuổi trở lên đi cùng, hoặc chuyến đi là để đi làm hay đi sự kiện của trường.","p":"Đúng. Lúc đầu không được lái từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, kailan HINDI puwedeng magmaneho nang mag-isa ang teen?","o":["Hatinggabi hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagsimula ang bagong araw.","h2":"Sa unang anim na buwan ng provisional license sa Minnesota, hindi puwedeng magmaneho ang teen mula hatinggabi hanggang 5 a.m., maliban kung may kasamang lisensyadong driver na 25 o mas matanda, o ang biyahe ay para sa trabaho o sa event ng paaralan.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m. sa simula."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، متى لا يجوز للمراهق أن يقود وحده؟","o":["من منتصف الليل حتى 5 صباحًا","من 10 مساءً حتى 6 صباحًا","من 9 مساءً حتى 5 صباحًا","من 11 مساءً حتى 4 صباحًا"],"h1":"يبدأ المنع عندما يبدأ يوم جديد.","h2":"خلال الأشهر الستة الأولى من الرخصة المؤقتة في Minnesota، لا يجوز للمراهق أن يقود من منتصف الليل حتى 5 صباحًا، إلا إذا كان معه سائق مرخَّص عمره 25 سنة أو أكثر، أو كانت الرحلة للعمل أو لنشاط مدرسي.","p":"صحيح. لا قيادة من منتصف الليل حتى 5 صباحًا في البداية."},"ref":{"doc":"MN","page":14}},{"id":"mn-011","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, in the first six months of a provisional license, who can ride along so the teen may drive at 2 a.m.?","o":["Any friend who is 18","A brother who has a permit","A licensed driver age 25 or older","Any adult passenger"],"h1":"The person must be licensed and older than most college students.","h2":"A Minnesota provisional driver may drive between midnight and 5 a.m. in the first six months when a licensed driver who is at least 25 rides along.","p":"Right. A licensed driver 25 or older makes it legal."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿quién puede acompañar al adolescente para que maneje a las 2 a.m.?","o":["Cualquier amigo de 18 años","Un hermano que tiene permiso","Un conductor con licencia de 25 años o más","Cualquier pasajero adulto"],"h1":"La persona debe tener licencia y ser mayor que la mayoría de los universitarios.","h2":"Un conductor provisional en Minnesota puede manejar entre medianoche y 5 a.m. en los primeros seis meses si lo acompaña un conductor con licencia de por lo menos 25 años.","p":"Correcto. Un conductor con licencia de 25 años o más lo hace legal."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，谁同车时青少年可以在凌晨 2 点开车？","o":["任何 18 岁的朋友","一个持学习驾照的哥哥或弟弟","25 岁或以上、有驾照的司机","任何成年乘客"],"h1":"这个人必须有驾照，而且比大多数大学生年纪大。","h2":"持 Minnesota 临时驾照的前六个月，有至少 25 岁、有驾照的司机同车时，可以在午夜到早上 5 点之间开车。","p":"对。有 25 岁或以上、有驾照的司机同车就合法。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, ai có thể đi cùng để thiếu niên được lái xe lúc 2 giờ sáng?","o":["Bất kỳ người bạn nào 18 tuổi","Anh trai có giấy phép tập lái","Người có bằng lái từ 25 tuổi trở lên","Bất kỳ hành khách người lớn nào"],"h1":"Người đó phải có bằng lái và lớn tuổi hơn hầu hết sinh viên đại học.","h2":"Người có bằng lái tạm thời ở Minnesota được lái xe từ nửa đêm đến 5 giờ sáng trong sáu tháng đầu khi có một người có bằng lái từ 25 tuổi trở lên đi cùng.","p":"Đúng. Người có bằng lái từ 25 tuổi trở lên làm cho việc này hợp pháp."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, sino ang puwedeng sumama para makapagmaneho ang teen nang 2 a.m.?","o":["Kahit sinong kaibigan na 18","Kapatid na lalaki na may permit","Lisensyadong driver na 25 o mas matanda","Kahit sinong adult na pasahero"],"h1":"Ang tao ay dapat may lisensya at mas matanda kaysa sa karamihan ng estudyante sa kolehiyo.","h2":"Ang may provisional license sa Minnesota ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. sa unang anim na buwan kapag may kasamang lisensyadong driver na hindi bababa sa 25 taong gulang.","p":"Tama. Ang lisensyadong driver na 25 o mas matanda ang nagpapalegal dito."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، من يمكنه أن يرافق المراهق حتى يقود في الساعة 2 صباحًا؟","o":["أي صديق عمره 18 سنة","أخ لديه تصريح تعلّم","سائق مرخَّص عمره 25 سنة أو أكثر","أي راكب بالغ"],"h1":"يجب أن يكون الشخص مرخَّصًا وأكبر من معظم طلاب الجامعة.","h2":"يجوز لحامل الرخصة المؤقتة في Minnesota أن يقود بين منتصف الليل و5 صباحًا في الأشهر الستة الأولى عندما يرافقه سائق مرخَّص عمره 25 سنة على الأقل.","p":"صحيح. وجود سائق مرخَّص عمره 25 سنة أو أكثر يجعل ذلك قانونيًا."},"ref":{"doc":"MN","page":14}},{"id":"mn-012","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, in the first six months of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"For the first six months, a Minnesota provisional driver may carry only one passenger under 20 who is not immediate family, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family at first."},"es":{"q":"En Minnesota, en los primeros seis meses de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses, un conductor provisional en Minnesota puede llevar solo un pasajero menor de 20 que no sea familia directa, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Al principio solo un pasajero joven que no sea familia."},"zh":{"q":"在 Minnesota，持临时驾照的前六个月，青少年可以载多少位不是家人、20 岁以下的乘客？","o":["一个都不行","一位","两位","三位"],"h1":"这是大于零的最小数字。","h2":"在前六个月，Minnesota 持临时驾照的司机只能载一位不是直系家人、20 岁以下的乘客，因为年轻乘客会让新司机分心。","p":"对。一开始只能载一位不是家人的年轻乘客。"},"vi":{"q":"Ở Minnesota, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu, người có bằng lái tạm thời ở Minnesota chỉ được chở một hành khách dưới 20 tuổi không phải người trong gia đình gần, vì hành khách trẻ làm người mới lái bị phân tâm.","p":"Đúng. Lúc đầu chỉ được chở một hành khách trẻ không phải người nhà."},"tl":{"q":"Sa Minnesota, sa unang anim na buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay ng teen?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa unang anim na buwan, ang may provisional license sa Minnesota ay puwedeng magsakay ng isang pasahero lang na wala pang 20 na hindi malapit na kapamilya, dahil nakakaabala ang mga batang pasahero sa bagong driver.","p":"Tama. Isang batang pasahero lang na hindi kapamilya sa simula."},"ar":{"q":"في Minnesota، خلال الأشهر الستة الأولى من الرخصة المؤقتة، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يجوز للمراهق أن ينقل؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"إنه أصغر عدد أكبر من صفر.","h2":"خلال الأشهر الستة الأولى، يجوز لحامل الرخصة المؤقتة في Minnesota أن ينقل راكبًا واحدًا فقط عمره أقل من 20 سنة وليس من العائلة المباشرة، لأن الركاب الصغار يشتّتون انتباه السائقين الجدد.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة في البداية."},"ref":{"doc":"MN","page":15}},{"id":"mn-013","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, in months 7 to 12 of a provisional license, how many passengers under 20 who are not family may the teen carry?","o":["One","Two","Four","Three"],"h1":"The limit grows after the first six months.","h2":"In months 7 to 12, a Minnesota provisional driver may carry up to three passengers under 20 who are not immediate family; after 12 months the limit ends.","p":"Right. Up to three young passengers in months 7 to 12."},"es":{"q":"En Minnesota, en los meses 7 a 12 de la licencia provisional, ¿cuántos pasajeros menores de 20 que no son familia puede llevar el adolescente?","o":["Uno","Dos","Cuatro","Tres"],"h1":"El límite crece después de los primeros seis meses.","h2":"En los meses 7 a 12, un conductor provisional en Minnesota puede llevar hasta tres pasajeros menores de 20 que no sean familia directa; después de 12 meses el límite termina.","p":"Correcto. Hasta tres pasajeros jóvenes en los meses 7 a 12."},"zh":{"q":"在 Minnesota，持临时驾照的第 7 到第 12 个月，青少年可以载多少位不是家人、20 岁以下的乘客？","o":["一位","两位","四位","三位"],"h1":"前六个月以后，限制放宽了。","h2":"在第 7 到第 12 个月，Minnesota 持临时驾照的司机最多可以载三位不是直系家人、20 岁以下的乘客；12 个月以后，这个限制就结束了。","p":"对。第 7 到第 12 个月，最多三位年轻乘客。"},"vi":{"q":"Ở Minnesota, từ tháng thứ 7 đến tháng thứ 12 có bằng lái tạm thời, thiếu niên được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Một","Hai","Bốn","Ba"],"h1":"Giới hạn tăng lên sau sáu tháng đầu.","h2":"Từ tháng thứ 7 đến tháng thứ 12, người có bằng lái tạm thời ở Minnesota được chở tối đa ba hành khách dưới 20 tuổi không phải người trong gia đình gần; sau 12 tháng thì không còn giới hạn này.","p":"Đúng. Tối đa ba hành khách trẻ từ tháng thứ 7 đến tháng thứ 12."},"tl":{"q":"Sa Minnesota, sa ika-7 hanggang ika-12 buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay ng teen?","o":["Isa","Dalawa","Apat","Tatlo"],"h1":"Lumalaki ang limitasyon pagkatapos ng unang anim na buwan.","h2":"Sa ika-7 hanggang ika-12 buwan, ang may provisional license sa Minnesota ay puwedeng magsakay ng hanggang tatlong pasaherong wala pang 20 na hindi malapit na kapamilya; pagkatapos ng 12 buwan, wala na ang limitasyon.","p":"Tama. Hanggang tatlong batang pasahero sa ika-7 hanggang ika-12 buwan."},"ar":{"q":"في Minnesota، في الأشهر من 7 إلى 12 من الرخصة المؤقتة، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يجوز للمراهق أن ينقل؟","o":["واحد","اثنان","أربعة","ثلاثة"],"h1":"يزيد الحد بعد الأشهر الستة الأولى.","h2":"في الأشهر من 7 إلى 12، يجوز لحامل الرخصة المؤقتة في Minnesota أن ينقل حتى ثلاثة ركاب أعمارهم أقل من 20 سنة وليسوا من العائلة المباشرة؛ وبعد 12 شهرًا ينتهي هذا الحد.","p":"صحيح. حتى ثلاثة ركاب صغار في الأشهر من 7 إلى 12."},"ref":{"doc":"MN","page":15}},{"id":"mn-014","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, may a 16-year-old with a provisional license use a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on freeways","No, not even hands-free","Yes, for calls under one minute"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Minnesota driver under 18 with a permit or provisional license may not use a phone while the car is moving, hand-held or hands-free.","p":"Right. Under 18, no phone at all while moving."},"es":{"q":"En Minnesota, ¿puede un joven de 16 años con licencia provisional usar el teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","No, ni siquiera con manos libres","Sí, para llamadas de menos de un minuto"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Minnesota con permiso o licencia provisional no puede usar el teléfono mientras el carro se mueve, ni en la mano ni con manos libres.","p":"Correcto. Menor de 18, nada de teléfono en movimiento."},"zh":{"q":"在 Minnesota，持临时驾照的 16 岁司机开车时可以用免提手机吗？","o":["可以，免提一直都可以","可以，但只能在高速公路上","不可以，免提也不行","可以，打一分钟以内的电话"],"h1":"青少年司机的规定比成年人更严格。","h2":"在 Minnesota，持学习驾照或临时驾照、18 岁以下的司机，在车开动时不能用手机，手拿或免提都不行。","p":"对。18 岁以下，车在开时完全不能用手机。"},"vi":{"q":"Ở Minnesota, người 16 tuổi có bằng lái tạm thời có được dùng điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, kể cả rảnh tay cũng không","Có, cho cuộc gọi dưới một phút"],"h1":"Người lái xe tuổi thiếu niên có luật nghiêm hơn người lớn.","h2":"Người lái xe ở Minnesota dưới 18 tuổi có giấy phép tập lái hoặc bằng lái tạm thời không được dùng điện thoại khi xe đang chạy, dù cầm tay hay rảnh tay.","p":"Đúng. Dưới 18 tuổi, hoàn toàn không dùng điện thoại khi xe đang chạy."},"tl":{"q":"Sa Minnesota, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang 16 taong gulang na may provisional license?","o":["Oo, laging puwede ang hands-free","Oo, pero sa freeway lang","Hindi, kahit hands-free","Oo, para sa tawag na wala pang isang minuto"],"h1":"Mas mahigpit ang patakaran para sa teen na driver kaysa sa mga adult.","h2":"Ang driver sa Minnesota na wala pang 18 na may permit o provisional license ay hindi puwedeng gumamit ng telepono habang umaandar ang kotse, hawak man o hands-free.","p":"Tama. Kung wala pang 18, bawal ang telepono habang umaandar."},"ar":{"q":"في Minnesota، هل يجوز لشخص عمره 16 سنة ولديه رخصة مؤقتة أن يستخدم الهاتف بدون يدين (hands-free) أثناء القيادة؟","o":["نعم، الاستخدام بدون يدين مسموح دائمًا","نعم، ولكن على الطرق السريعة فقط","لا، ولا حتى بدون يدين","نعم، للمكالمات الأقل من دقيقة"],"h1":"للسائقين المراهقين قاعدة أشد من البالغين.","h2":"لا يجوز للسائق في Minnesota الذي عمره أقل من 18 سنة ولديه تصريح تعلّم أو رخصة مؤقتة أن يستخدم الهاتف أثناء سير السيارة، سواء باليد أو بدون يدين.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا أثناء سير السيارة."},"ref":{"doc":"MN","page":14}},{"id":"mn-015","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how may an adult driver use a cell phone to make a call while driving?","o":["By voice command or one touch, without holding it","Holding it at the ear","Holding it on the steering wheel","Holding it only at stop signs"],"h1":"Minnesota's law is called Hands-Free.","h2":"Minnesota adults may use a phone while driving only by voice command or hands-free mode, never holding it in their hand.","p":"Right. Voice or one touch, never holding the phone."},"es":{"q":"En Minnesota, ¿cómo puede un conductor adulto usar el celular para hacer una llamada mientras maneja?","o":["Con comando de voz o un solo toque, sin sostenerlo","Sosteniéndolo junto al oído","Sosteniéndolo sobre el volante","Sosteniéndolo solo en las señales de alto"],"h1":"La ley de Minnesota se llama Manos Libres.","h2":"En Minnesota, los adultos pueden usar el teléfono al manejar solo con comandos de voz o en modo manos libres, nunca sosteniéndolo en la mano.","p":"Correcto. Con voz o un toque, nunca sosteniendo el teléfono."},"zh":{"q":"在 Minnesota，成年司机开车时可以怎样用手机打电话？","o":["用语音命令或按一下，不拿着手机","拿到耳边","拿在方向盘上","只在停车标志前拿着"],"h1":"Minnesota 的这条法律叫做 Hands-Free（免提）。","h2":"Minnesota 的成年人开车时只能用语音命令或免提模式使用手机，绝不能拿在手里。","p":"对。用语音或按一下，绝不拿着手机。"},"vi":{"q":"Ở Minnesota, người lớn lái xe được dùng điện thoại di động để gọi như thế nào khi đang lái?","o":["Bằng giọng nói hoặc một lần chạm, không cầm điện thoại","Cầm điện thoại áp vào tai","Cầm điện thoại trên vô lăng","Chỉ cầm điện thoại khi dừng ở biển Stop"],"h1":"Luật của Minnesota có tên là Hands-Free (rảnh tay).","h2":"Người lớn ở Minnesota chỉ được dùng điện thoại khi lái xe bằng lệnh giọng nói hoặc chế độ rảnh tay, không bao giờ cầm điện thoại trong tay.","p":"Đúng. Dùng giọng nói hoặc một lần chạm, không bao giờ cầm điện thoại."},"tl":{"q":"Sa Minnesota, paano puwedeng gumamit ng cell phone ang adult na driver para tumawag habang nagmamaneho?","o":["Sa voice command o isang pindot, nang hindi ito hawak","Hawak ito sa tainga","Hawak ito sa manibela","Hawak ito sa stop sign lang"],"h1":"Ang batas ng Minnesota ay tinatawag na Hands-Free.","h2":"Ang mga adult sa Minnesota ay puwedeng gumamit ng telepono habang nagmamaneho sa voice command o hands-free mode lang, at hindi kailanman hawak sa kamay.","p":"Tama. Boses o isang pindot, hindi kailanman hawak ang telepono."},"ar":{"q":"في Minnesota، كيف يجوز للسائق البالغ أن يستخدم الهاتف المحمول لإجراء مكالمة أثناء القيادة؟","o":["بالأمر الصوتي أو بلمسة واحدة، دون أن يمسكه","بإمساكه عند الأذن","بإمساكه على عجلة القيادة","بإمساكه عند إشارات Stop فقط"],"h1":"قانون Minnesota اسمه Hands-Free (بدون يدين).","h2":"يجوز للبالغين في Minnesota استخدام الهاتف أثناء القيادة بالأمر الصوتي أو بوضع بدون يدين فقط، ولا يمسكونه في أيديهم أبدًا.","p":"صحيح. بالصوت أو بلمسة واحدة، ولا تمسك الهاتف أبدًا."},"ref":{"doc":"MN","page":null}},{"id":"mn-016","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what score do you need to pass the knowledge test?","o":["60 percent","70 percent","75 percent","80 percent"],"h1":"You must answer four out of every five questions right.","h2":"Minnesota requires at least 80 percent correct to pass the driver knowledge test.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Minnesota, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento","70 por ciento","75 por ciento","80 por ciento"],"h1":"Debe contestar bien cuatro de cada cinco preguntas.","h2":"Minnesota exige por lo menos 80 por ciento de respuestas correctas para aprobar el examen de conocimientos.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Minnesota，笔试要得多少分才能通过？","o":["60%","70%","75%","80%"],"h1":"每五道题你必须答对四道。","h2":"Minnesota 要求驾驶笔试至少答对 80% 才能通过。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Minnesota, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["60 phần trăm","70 phần trăm","75 phần trăm","80 phần trăm"],"h1":"Bạn phải trả lời đúng bốn trên mỗi năm câu hỏi.","h2":"Minnesota yêu cầu trả lời đúng ít nhất 80 phần trăm để đậu bài thi kiến thức lái xe.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Minnesota, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","75 porsiyento","80 porsiyento"],"h1":"Dapat tama ang sagot mo sa apat sa bawat limang tanong.","h2":"Kailangan sa Minnesota ang hindi bababa sa 80 porsiyentong tama para pumasa sa driver knowledge test.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Minnesota، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة؟","o":["60 بالمئة","70 بالمئة","75 بالمئة","80 بالمئة"],"h1":"يجب أن تجيب صحيحًا عن أربعة من كل خمسة أسئلة.","h2":"تشترط Minnesota إجابات صحيحة بنسبة 80 بالمئة على الأقل للنجاح في اختبار المعرفة للسائقين.","p":"صحيح. تحتاج 80 بالمئة للنجاح."},"ref":{"doc":"MN","page":10}},{"id":"mn-017","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, on a road with two lanes your way, you approach a stopped ambulance with flashing lights on the shoulder. What does the law require?","o":["Stay in your lane and keep your speed","Move one full lane away, if safe","Stop on the shoulder behind it","Speed up to pass it quickly"],"h1":"Leave an empty lane between you and the workers.","h2":"Minnesota's Ted Foss Move Over law requires you to move one full lane away from a stopped emergency vehicle with flashing lights; if that is not safe, slow down.","p":"Right. Move one full lane away."},"es":{"q":"En Minnesota, en una vía con dos carriles en su dirección, se acerca a una ambulancia detenida en el acotamiento con luces intermitentes. ¿Qué exige la ley?","o":["Seguir en su carril a la misma velocidad","Alejarse un carril completo, si es seguro","Parar en el acotamiento detrás de ella","Acelerar para pasarla rápido"],"h1":"Deje un carril vacío entre usted y los trabajadores.","h2":"La ley Ted Foss de Minnesota le exige alejarse un carril completo de un vehículo de emergencia detenido con luces intermitentes; si no es seguro, baje la velocidad.","p":"Correcto. Aléjese un carril completo."},"zh":{"q":"在 Minnesota，在你的方向有两条车道的路上，你接近一辆停在路肩上、闪着灯的救护车。法律要求你怎么做？","o":["留在你的车道，保持速度","如果安全，离开一整条车道","在它后面的路肩上停车","加速很快开过去"],"h1":"在你和工作人员之间留出一条空车道。","h2":"Minnesota 的 Ted Foss Move Over 法要求你离停着、闪着灯的急救车辆一整条车道；如果换道不安全，就要减速。","p":"对。离开一整条车道。"},"vi":{"q":"Ở Minnesota, trên đường có hai làn đi cùng chiều với bạn, bạn đến gần một xe cứu thương đang dừng bên lề đường với đèn nhấp nháy. Luật yêu cầu gì?","o":["Ở trong làn của bạn và giữ nguyên tốc độ","Chuyển sang cách xa một làn đầy đủ, nếu an toàn","Dừng trên lề đường phía sau xe đó","Tăng tốc để vượt qua nhanh"],"h1":"Để trống một làn giữa bạn và những người đang làm việc.","h2":"Luật Ted Foss Move Over (luật nhường làn) của Minnesota yêu cầu bạn chuyển sang cách xa một làn đầy đủ khỏi xe khẩn cấp đang dừng có đèn nhấp nháy; nếu việc đó không an toàn, hãy giảm tốc độ.","p":"Đúng. Chuyển sang cách xa một làn đầy đủ."},"tl":{"q":"Sa Minnesota, sa daan na may dalawang lane sa direksyon mo, papalapit ka sa nakahintong ambulansya na may kumikislap na ilaw sa gilid ng daan (shoulder). Ano ang hinihingi ng batas?","o":["Manatili sa lane mo at panatilihin ang bilis","Lumipat nang isang buong lane palayo, kung ligtas","Huminto sa shoulder sa likod nito","Bumilis para malampasan ito agad"],"h1":"Mag-iwan ng bakanteng lane sa pagitan mo at ng mga nagtatrabaho.","h2":"Ang Ted Foss Move Over law ng Minnesota ay nag-uutos na lumipat ka nang isang buong lane palayo sa nakahintong emergency vehicle na may kumikislap na ilaw; kung hindi ito ligtas, magdahan-dahan.","p":"Tama. Lumipat nang isang buong lane palayo."},"ar":{"q":"في Minnesota، على طريق فيه حارتان في اتجاهك، تقترب من سيارة إسعاف متوقفة على كتف الطريق وأضواؤها تومض. ماذا يشترط القانون؟","o":["ابقَ في حارتك وحافظ على سرعتك","ابتعد حارة كاملة واحدة، إذا كان ذلك آمنًا","توقف على كتف الطريق خلفها","زِد سرعتك لتتجاوزها بسرعة"],"h1":"اترك حارة فارغة بينك وبين العاملين.","h2":"قانون Ted Foss Move Over (قانون الابتعاد) في Minnesota يشترط أن تبتعد حارة كاملة واحدة عن مركبة الطوارئ المتوقفة وأضواؤها تومض؛ وإذا لم يكن ذلك آمنًا، فخفّف سرعتك.","p":"صحيح. ابتعد حارة كاملة واحدة."},"ref":{"doc":"MN","page":44}},{"id":"mn-018","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, the move over law also protects which of these?","o":["A stalled car with its hazard lights on","A parked car in a driveway","A bus at a bus stop","A car waiting at a red light"],"h1":"Think of a driver stuck on the shoulder.","h2":"Minnesota's move over law also covers stalled or disabled vehicles with their warning lights on, so stranded drivers get the same protection.","p":"Right. Stalled cars with hazards on are covered too."},"es":{"q":"En Minnesota, ¿a cuál de estos también protege la ley de cambiarse de carril (Move Over)?","o":["Un carro descompuesto con las luces de emergencia encendidas","Un carro estacionado en una entrada de casa","Un autobús en una parada","Un carro esperando en un semáforo en rojo"],"h1":"Piense en un conductor varado en el acotamiento.","h2":"La ley de cambiarse de carril de Minnesota también protege a los vehículos averiados o detenidos con las luces de advertencia encendidas, para que los conductores varados tengan la misma protección.","p":"Correcto. Los carros descompuestos con luces de emergencia también están protegidos."},"zh":{"q":"在 Minnesota，move over 法也保护下面哪一个？","o":["一辆开着危险警示灯、抛锚的车","一辆停在车道（driveway）上的车","一辆在公交站的公共汽车","一辆在红灯前等的车"],"h1":"想一想困在路肩上的司机。","h2":"Minnesota 的 move over 法也包括开着警示灯、抛锚或坏掉的车，这样被困的司机也得到同样的保护。","p":"对。开着危险警示灯的抛锚车也包括在内。"},"vi":{"q":"Ở Minnesota, luật nhường làn (move over law) cũng bảo vệ đối tượng nào sau đây?","o":["Xe bị hỏng đang bật đèn cảnh báo","Xe đậu trong lối vào nhà","Xe buýt ở trạm xe buýt","Xe đang chờ đèn đỏ"],"h1":"Hãy nghĩ đến người lái xe bị kẹt bên lề đường.","h2":"Luật nhường làn của Minnesota cũng áp dụng cho xe bị hỏng hoặc chết máy đang bật đèn cảnh báo, để người lái xe bị kẹt cũng được bảo vệ như vậy.","p":"Đúng. Xe bị hỏng đang bật đèn cảnh báo cũng được bảo vệ."},"tl":{"q":"Sa Minnesota, alin dito ang pinoprotektahan din ng move over law?","o":["Sirang kotse na nakabukas ang hazard lights","Kotseng nakaparada sa driveway","Bus sa bus stop","Kotseng naghihintay sa red light"],"h1":"Isipin ang driver na naiwan sa gilid ng daan.","h2":"Sakop din ng move over law ng Minnesota ang sira o tumirik na sasakyan na nakabukas ang warning lights, para pareho ang proteksyon ng mga naiwang driver.","p":"Tama. Sakop din ang sirang kotse na nakabukas ang hazard lights."},"ar":{"q":"في Minnesota، قانون الابتعاد (move over law) يحمي أيضًا أيًّا مما يلي؟","o":["سيارة معطّلة أضواء التحذير فيها مضاءة","سيارة واقفة في ممر بيت","حافلة عند موقف الحافلات","سيارة تنتظر عند الإشارة الحمراء"],"h1":"فكّر في سائق عالق على كتف الطريق.","h2":"قانون الابتعاد في Minnesota يشمل أيضًا المركبات المتوقفة أو المعطّلة وأضواء التحذير فيها مضاءة، حتى يحصل السائقون العالقون على الحماية نفسها.","p":"صحيح. السيارات المعطّلة وأضواء التحذير فيها مضاءة مشمولة أيضًا."},"ref":{"doc":"MN","page":44}},{"id":"mn-019","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, how far from a school bus with its stop arm out and red lights flashing must you stop?","o":["At least 5 feet","At least 10 feet","At least 20 feet","At least 50 feet"],"h1":"It is about the length of one car and a half.","h2":"In Minnesota you must stop at least 20 feet from a school bus with its stop arm out and red lights flashing, to give children room to cross.","p":"Right. Stop at least 20 feet away."},"es":{"q":"En Minnesota, ¿a qué distancia de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes debe parar?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 20 pies","Por lo menos 50 pies"],"h1":"Es como el largo de un carro y medio.","h2":"En Minnesota usted debe parar por lo menos a 20 pies de un autobús escolar con el brazo de alto extendido y luces rojas intermitentes, para dar espacio a los niños que cruzan.","p":"Correcto. Pare por lo menos a 20 pies."},"zh":{"q":"在 Minnesota，你必须在离伸出停车臂、闪着红灯的校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 20 英尺","至少 50 英尺"],"h1":"大约是一辆半汽车的长度。","h2":"在 Minnesota，你必须在离伸出停车臂、闪着红灯的校车至少 20 英尺的地方停车，给孩子留出过马路的空间。","p":"对。在至少 20 英尺外停车。"},"vi":{"q":"Ở Minnesota, bạn phải dừng cách xe buýt trường học đang giơ cần báo dừng và nhấp nháy đèn đỏ bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet"],"h1":"Khoảng chiều dài của một chiếc xe rưỡi.","h2":"Ở Minnesota, bạn phải dừng cách ít nhất 20 feet khỏi xe buýt trường học đang giơ cần báo dừng và nhấp nháy đèn đỏ, để trẻ em có chỗ băng qua đường.","p":"Đúng. Dừng cách ít nhất 20 feet."},"tl":{"q":"Sa Minnesota, gaano kalayo ka dapat huminto mula sa school bus na nakalabas ang stop arm at kumikislap ang pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet"],"h1":"Mga isa't kalahating haba ng kotse ito.","h2":"Sa Minnesota, dapat kang huminto nang hindi bababa sa 20 feet mula sa school bus na nakalabas ang stop arm at kumikislap ang pulang ilaw, para may lugar ang mga bata na tumawid.","p":"Tama. Huminto nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في Minnesota، على أي مسافة يجب أن تتوقف من حافلة مدرسية ذراع التوقف فيها ممدودة وأضواؤها الحمراء تومض؟","o":["5 feet على الأقل","10 feet على الأقل","20 feet على الأقل","50 feet على الأقل"],"h1":"إنها تقريبًا طول سيارة ونصف.","h2":"في Minnesota يجب أن تتوقف على بعد 20 feet على الأقل من الحافلة المدرسية التي ذراع التوقف فيها ممدودة وأضواؤها الحمراء تومض، لتعطي الأطفال مكانًا للعبور.","p":"صحيح. توقف على بعد 20 feet على الأقل."},"ref":{"doc":"MN","page":42}},{"id":"mn-020","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, when may oncoming traffic keep going past a school bus with its stop arm out?","o":["When the bus is on a two-lane road","When no children are visible","When the road has four lanes but no median","When a raised or depressed median separates the roads"],"h1":"The roads must be truly separated by something built.","h2":"In Minnesota, oncoming drivers need not stop only on a divided road, where a physical barrier or a raised or depressed median separates the two sides.","p":"Right. Only a real median or barrier lets oncoming traffic keep going."},"es":{"q":"En Minnesota, ¿cuándo puede seguir el tránsito que viene en sentido contrario ante un autobús escolar con el brazo de alto extendido?","o":["Cuando el autobús está en una vía de dos carriles","Cuando no se ven niños","Cuando la carretera tiene cuatro carriles pero no tiene división","Cuando un camellón elevado o hundido separa las vías"],"h1":"Las vías deben estar separadas de verdad por algo construido.","h2":"En Minnesota, los conductores que vienen en sentido contrario no tienen que detenerse solo en una carretera dividida, donde una barrera física o una división elevada o hundida separa los dos lados.","p":"Correcto. Solo un camellón o barrera real permite seguir."},"zh":{"q":"在 Minnesota，对面开来的车什么时候可以继续开过伸出停车臂的校车？","o":["校车在双车道的路上时","看不到孩子时","路有四条车道但没有中央隔离带时","有凸起或下沉的中央隔离带把两边的路分开时"],"h1":"两边的路必须真的被建好的东西分开。","h2":"在 Minnesota，只有在分隔道路上，也就是有实体护栏或凸起、下沉的中央隔离带把两边分开时，对面的司机才不用停车。","p":"对。只有真正的中央隔离带或护栏，才能让对面的车继续开。"},"vi":{"q":"Ở Minnesota, khi nào xe đi ngược chiều được tiếp tục chạy qua xe buýt trường học đang giơ cần báo dừng?","o":["Khi xe buýt ở trên đường hai làn","Khi không thấy trẻ em nào","Khi đường có bốn làn nhưng không có dải phân cách","Khi có dải phân cách nổi cao hoặc trũng thấp ngăn hai bên đường"],"h1":"Hai bên đường phải thật sự được ngăn cách bằng một thứ được xây dựng.","h2":"Ở Minnesota, xe đi ngược chiều chỉ không cần dừng trên đường có phân cách, nơi có rào chắn hoặc dải phân cách nổi cao hay trũng thấp ngăn hai bên đường.","p":"Đúng. Chỉ có dải phân cách thật hoặc rào chắn mới cho xe ngược chiều tiếp tục chạy."},"tl":{"q":"Sa Minnesota, kailan puwedeng tumuloy ang paparating na sasakyan sa kabilang direksyon na dumaan sa school bus na nakalabas ang stop arm?","o":["Kapag ang bus ay nasa daang may dalawang lane","Kapag walang nakikitang bata","Kapag may apat na lane ang daan pero walang median","Kapag may nakaangat o nakababang median na naghihiwalay sa mga daan"],"h1":"Ang mga daan ay dapat talagang hiwalay dahil sa isang bagay na itinayo.","h2":"Sa Minnesota, hindi kailangang huminto ang mga paparating na driver sa kabilang direksyon kapag nasa divided road lang, kung saan may harang o nakaangat o nakababang median na naghihiwalay sa dalawang panig.","p":"Tama. Tunay na median o harang lang ang nagpapahintulot sa kabilang direksyon na tumuloy."},"ar":{"q":"في Minnesota، متى يجوز لحركة المرور القادمة من الاتجاه المعاكس أن تستمر في المرور بجانب حافلة مدرسية ذراع التوقف فيها ممدودة؟","o":["عندما تكون الحافلة على طريق بحارتين","عندما لا يُرى أي أطفال","عندما يكون للطريق أربع حارات ولكن بلا جزيرة وسطية","عندما تفصل جزيرة وسطية مرتفعة أو منخفضة بين الطريقين"],"h1":"يجب أن يكون الطريقان مفصولين فعلًا بشيء مبني.","h2":"في Minnesota، لا يلزم السائقين القادمين من الاتجاه المعاكس أن يتوقفوا إلا على طريق مقسوم، حيث يفصل حاجز أو جزيرة وسطية مرتفعة أو منخفضة بين الجانبين.","p":"صحيح. فقط جزيرة وسطية حقيقية أو حاجز يسمح لحركة المرور المعاكسة بالاستمرار."},"ref":{"doc":"MN","page":42}},{"id":"mn-021","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, under the Not a Drop law, how much alcohol may a driver under 21 have?","o":["Up to 0.02","None at all","Up to 0.05","Up to 0.08"],"h1":"The name of the law gives the answer.","h2":"Minnesota's Not a Drop law makes it illegal for a driver under 21 to drive after drinking any alcohol at all.","p":"Right. Under 21 means not a drop."},"es":{"q":"En Minnesota, según la ley Not a Drop (Ni una gota), ¿cuánto alcohol puede tener un conductor menor de 21?","o":["Hasta 0.02","Nada","Hasta 0.05","Hasta 0.08"],"h1":"El nombre de la ley da la respuesta.","h2":"La ley Not a Drop de Minnesota prohíbe que un conductor menor de 21 maneje después de tomar cualquier cantidad de alcohol.","p":"Correcto. Menor de 21 significa ni una gota."},"zh":{"q":"在 Minnesota，根据 Not a Drop 法，21 岁以下的司机体内可以有多少酒精？","o":["最多 0.02","一点都不行","最多 0.05","最多 0.08"],"h1":"这条法律的名字就给出了答案（Not a Drop 的意思是一滴都不行）。","h2":"Minnesota 的 Not a Drop 法规定，21 岁以下的司机只要喝了任何酒，再开车就是违法的。","p":"对。21 岁以下就是一滴都不行。"},"vi":{"q":"Ở Minnesota, theo luật Not a Drop (không một giọt), người lái xe dưới 21 tuổi được có bao nhiêu rượu bia trong người?","o":["Tối đa 0.02","Hoàn toàn không có","Tối đa 0.05","Tối đa 0.08"],"h1":"Tên của luật cho bạn câu trả lời.","h2":"Luật Not a Drop của Minnesota cấm người lái xe dưới 21 tuổi lái xe sau khi uống bất kỳ chút rượu bia nào.","p":"Đúng. Dưới 21 tuổi nghĩa là không một giọt."},"tl":{"q":"Sa Minnesota, sa ilalim ng Not a Drop law (batas na kahit isang patak ay bawal), gaano karaming alak ang puwedeng mayroon ang driver na wala pang 21?","o":["Hanggang 0.02","Wala talaga","Hanggang 0.05","Hanggang 0.08"],"h1":"Ang pangalan ng batas ang nagbibigay ng sagot.","h2":"Ginagawang ilegal ng Not a Drop law ng Minnesota ang pagmamaneho ng driver na wala pang 21 pagkatapos uminom ng kahit anong alak.","p":"Tama. Kung wala pang 21, kahit isang patak ay bawal."},"ar":{"q":"في Minnesota، بموجب قانون Not a Drop (ولا قطرة)، كم من الكحول يجوز أن يكون لدى سائق عمره أقل من 21 سنة؟","o":["حتى 0.02","لا شيء على الإطلاق","حتى 0.05","حتى 0.08"],"h1":"اسم القانون يعطيك الجواب.","h2":"قانون Not a Drop في Minnesota يجعل القيادة بعد شرب أي كمية من الكحول ممنوعة على السائق الذي عمره أقل من 21 سنة.","p":"صحيح. تحت 21 سنة يعني ولا قطرة."},"ref":{"doc":"MN","page":95}},{"id":"mn-022","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, unless a sign says otherwise, what is the speed limit in an urban district?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"It is a round number below 35.","h2":"Minnesota law sets 30 mph in an urban district when no other limit is posted, because homes, businesses and people are close to the road.","p":"Right. Urban districts are 30 mph."},"es":{"q":"En Minnesota, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en zona urbana?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Minnesota fija 30 mph en zona urbana cuando no hay otro límite indicado, porque hay casas, negocios y personas cerca de la vía.","p":"Correcto. En zona urbana el límite es 30 mph."},"zh":{"q":"在 Minnesota，除非有标志另外规定，城区（urban district）的限速是多少？","o":["30 英里/小时","25 英里/小时","35 英里/小时","40 英里/小时"],"h1":"这是一个比 35 小的整数。","h2":"没有标出其他限速时，Minnesota 法律规定城区限速 30 英里/小时，因为住家、商店和人都离路很近。","p":"对。城区限速 30 英里/小时。"},"vi":{"q":"Ở Minnesota, nếu không có biển báo khác, tốc độ giới hạn trong khu đô thị là bao nhiêu?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Đó là một số tròn nhỏ hơn 35.","h2":"Luật Minnesota đặt tốc độ 30 mph trong khu đô thị khi không có giới hạn khác được ghi, vì nhà cửa, cửa hàng và người đi bộ ở gần đường.","p":"Đúng. Khu đô thị là 30 mph."},"tl":{"q":"Sa Minnesota, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa urban district (lugar sa lungsod)?","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"Ito ay buong bilang na mas mababa sa 35.","h2":"Itinatakda ng batas ng Minnesota ang 30 mph sa urban district kapag walang ibang nakapaskil na limit, dahil malapit sa daan ang mga bahay, negosyo at tao.","p":"Tama. 30 mph sa urban district."},"ar":{"q":"في Minnesota، ما لم تقل لافتة غير ذلك، ما حد السرعة في منطقة حضرية (urban district)؟","o":["30 mph","25 mph","35 mph","40 mph"],"h1":"إنه رقم مستدير أقل من 35.","h2":"يحدد قانون Minnesota سرعة 30 mph في المنطقة الحضرية عندما لا يوجد حد آخر معلن، لأن البيوت والمحلات والناس قريبون من الطريق.","p":"صحيح. المناطق الحضرية 30 mph."},"ref":{"doc":"MN","page":26}},{"id":"mn-023","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, what is the speed limit on an interstate outside a large urban area, unless posted otherwise?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Inside big cities the interstate limit is 5 mph lower.","h2":"Minnesota sets 70 mph on interstates outside urbanized areas of more than 50,000 people, and 65 mph inside them.","p":"Right. Rural interstates are 70 mph."},"es":{"q":"En Minnesota, ¿cuál es el límite de velocidad en una interestatal fuera de una zona urbana grande, si no hay otro indicado?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Dentro de las ciudades grandes el límite en la interestatal es 5 mph menos.","h2":"Minnesota fija 70 mph en las interestatales fuera de zonas urbanas de más de 50,000 personas, y 65 mph dentro de ellas.","p":"Correcto. Las interestatales rurales son de 70 mph."},"zh":{"q":"在 Minnesota，除非另有标示，大城市地区以外的州际公路限速是多少？","o":["55 英里/小时","65 英里/小时","70 英里/小时","75 英里/小时"],"h1":"在大城市里，州际公路的限速低 5 英里/小时。","h2":"Minnesota 规定，在人口超过 50,000 的城市化地区以外，州际公路限速 70 英里/小时，在这些地区以内是 65 英里/小时。","p":"对。乡村的州际公路限速 70 英里/小时。"},"vi":{"q":"Ở Minnesota, tốc độ giới hạn trên xa lộ liên bang (interstate) bên ngoài khu đô thị lớn là bao nhiêu, nếu không có biển báo khác?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Trong các thành phố lớn, giới hạn trên xa lộ liên bang thấp hơn 5 mph.","h2":"Minnesota đặt 70 mph trên xa lộ liên bang bên ngoài khu đô thị có hơn 50,000 dân, và 65 mph bên trong các khu đó.","p":"Đúng. Xa lộ liên bang ở vùng nông thôn là 70 mph."},"tl":{"q":"Sa Minnesota, ano ang speed limit sa interstate sa labas ng malaking urban area, maliban kung iba ang nakapaskil?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Sa loob ng malalaking lungsod, 5 mph na mas mababa ang limit sa interstate.","h2":"Itinatakda ng Minnesota ang 70 mph sa mga interstate sa labas ng urbanized area na may higit sa 50,000 tao, at 65 mph sa loob ng mga ito.","p":"Tama. 70 mph sa mga interstate sa probinsya."},"ar":{"q":"في Minnesota، ما حد السرعة على الطريق السريع بين الولايات (interstate) خارج منطقة حضرية كبيرة، ما لم يُعلن غير ذلك؟","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"داخل المدن الكبيرة يكون حد السرعة على الطريق السريع أقل بـ 5 mph.","h2":"تحدد Minnesota سرعة 70 mph على الطرق السريعة بين الولايات خارج المناطق الحضرية التي يزيد سكانها على 50,000 شخص، و65 mph داخلها.","p":"صحيح. الطرق السريعة بين الولايات في الريف 70 mph."},"ref":{"doc":"MN","page":null}},{"id":"mn-024","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, when must you turn on your headlights during the day?","o":["Only on the freeway","Whenever it is raining or snowing","Only in a tunnel","Only after 6 p.m."],"h1":"Think about weather that makes cars hard to see.","h2":"Minnesota law requires headlights whenever it is raining, snowing, sleeting or hailing, even in daytime, so other drivers can see you.","p":"Right. Rain or snow means headlights on."},"es":{"q":"En Minnesota, ¿cuándo debe encender los faros durante el día?","o":["Solo en la autopista","Siempre que llueva o nieve","Solo en un túnel","Solo después de las 6 p.m."],"h1":"Piense en el clima que hace difícil ver los carros.","h2":"La ley de Minnesota exige los faros encendidos siempre que llueva, nieve, caiga aguanieve o granizo, aunque sea de día, para que otros conductores lo vean.","p":"Correcto. Con lluvia o nieve, faros encendidos."},"zh":{"q":"在 Minnesota，白天什么时候必须打开车头灯？","o":["只在高速公路上","只要在下雨或下雪","只在隧道里","只在下午 6 点以后"],"h1":"想一想让车很难被看见的天气。","h2":"Minnesota 法律规定，只要在下雨、下雪、下雨夹雪或下冰雹，即使是白天，也必须打开车头灯，这样其他司机才能看见你。","p":"对。下雨或下雪就要开车头灯。"},"vi":{"q":"Ở Minnesota, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ","Bất cứ khi nào trời mưa hoặc có tuyết","Chỉ trong đường hầm","Chỉ sau 6 giờ chiều"],"h1":"Hãy nghĩ đến thời tiết làm khó thấy xe.","h2":"Luật Minnesota yêu cầu bật đèn pha bất cứ khi nào trời mưa, có tuyết, mưa tuyết hoặc mưa đá, kể cả ban ngày, để người lái xe khác thấy bạn.","p":"Đúng. Trời mưa hoặc có tuyết thì bật đèn pha."},"tl":{"q":"Sa Minnesota, kailan mo dapat buksan ang headlights sa araw?","o":["Sa freeway lang","Tuwing umuulan o umuulan ng niyebe","Sa tunnel lang","Pagkatapos lang ng 6 p.m."],"h1":"Isipin ang panahon na nagpapahirap makita ang mga kotse.","h2":"Inuutos ng batas ng Minnesota na nakabukas ang headlights tuwing umuulan, umuulan ng niyebe, sleet o yelo (hail), kahit araw, para makita ka ng ibang driver.","p":"Tama. Kapag ulan o niyebe, bukas ang headlights."},"ar":{"q":"في Minnesota، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع فقط","كلما كان هناك مطر أو ثلج","في النفق فقط","بعد الساعة 6 مساءً فقط"],"h1":"فكّر في الطقس الذي يجعل رؤية السيارات صعبة.","h2":"يشترط قانون Minnesota تشغيل المصابيح الأمامية كلما كان هناك مطر أو ثلج أو مطر متجمّد أو بَرَد، حتى في النهار، حتى يراك السائقون الآخرون.","p":"صحيح. المطر أو الثلج يعني تشغيل المصابيح الأمامية."},"ref":{"doc":"MN","page":23}},{"id":"mn-025","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what type of coverage must every car owner carry because the state has a no-fault system?","o":["Collision coverage","Rental car coverage","Roadside assistance","Personal injury protection (PIP)"],"h1":"It pays your own medical bills no matter who caused the crash.","h2":"Minnesota is a no-fault state, so every owner must carry no-fault insurance, called personal injury protection, which pays your own medical costs and lost wages whoever was at fault.","p":"Right. Minnesota requires personal injury protection."},"es":{"q":"En Minnesota, ¿qué tipo de cobertura debe tener todo dueño de carro porque el estado tiene un sistema sin culpa (no-fault)?","o":["Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino","Protección por lesiones personales (PIP)"],"h1":"Paga sus propios gastos médicos sin importar quién causó el choque.","h2":"Minnesota es un estado sin culpa, así que todo dueño debe tener el seguro sin culpa, llamado protección contra lesiones personales, que paga sus propios gastos médicos y salarios perdidos sin importar quién tuvo la culpa.","p":"Correcto. Minnesota exige protección por lesiones personales."},"zh":{"q":"在 Minnesota，因为州里实行无过失制度，每位车主都必须买哪种保险？","o":["碰撞险","租车保险","道路救援","个人伤害保障 (PIP)"],"h1":"不管车祸是谁造成的，它都支付你自己的医疗费用。","h2":"Minnesota 是无过失州，所以每位车主都必须买无过失保险，叫做个人伤害保障，不管谁有过错，它都支付你自己的医疗费用和损失的工资。","p":"对。Minnesota 要求个人伤害保障。"},"vi":{"q":"Ở Minnesota, mọi chủ xe phải mua loại bảo hiểm nào vì tiểu bang có hệ thống không xét lỗi (no-fault)?","o":["Bảo hiểm va chạm (collision)","Bảo hiểm xe thuê","Hỗ trợ bên đường","Bảo hiểm thương tích cá nhân (personal injury protection, PIP)"],"h1":"Nó trả chi phí y tế của chính bạn, bất kể ai gây ra tai nạn.","h2":"Minnesota là tiểu bang không xét lỗi, nên mọi chủ xe phải có bảo hiểm không xét lỗi, gọi là bảo hiểm thương tích cá nhân, trả chi phí y tế và tiền lương bị mất của chính bạn, bất kể ai có lỗi.","p":"Đúng. Minnesota yêu cầu bảo hiểm thương tích cá nhân."},"tl":{"q":"Sa Minnesota, anong uri ng coverage ang dapat mayroon ang bawat may-ari ng kotse dahil may no-fault system ang estado?","o":["Collision coverage","Coverage para sa inuupahang kotse","Roadside assistance","Personal injury protection (PIP)"],"h1":"Binabayaran nito ang sarili mong gastos sa pagpapagamot kahit sino ang may sanhi ng banggaan.","h2":"Ang Minnesota ay no-fault state, kaya ang bawat may-ari ay dapat may no-fault insurance, na tinatawag na personal injury protection, na nagbabayad ng sarili mong gastos sa pagpapagamot at nawalang sahod kahit sino ang may kasalanan.","p":"Tama. Inuutos ng Minnesota ang personal injury protection."},"ar":{"q":"في Minnesota، ما نوع التغطية التأمينية التي يجب أن يحملها كل مالك سيارة لأن الولاية تتبع نظام عدم تحديد الخطأ (no-fault)؟","o":["تأمين التصادم (collision)","تأمين السيارة المستأجرة","المساعدة على الطريق","تأمين الحماية من الإصابة الشخصية (personal injury protection, PIP)"],"h1":"إنه يدفع تكاليفك الطبية أنت مهما كان المتسبب في الحادث.","h2":"Minnesota ولاية بنظام عدم تحديد الخطأ، لذلك يجب على كل مالك أن يحمل تأمين عدم تحديد الخطأ، ويسمى الحماية من الإصابة الشخصية، وهو يدفع تكاليفك الطبية وأجرك الضائع أيًّا كان المخطئ.","p":"صحيح. تشترط Minnesota تأمين الحماية من الإصابة الشخصية."},"ref":{"doc":"MN","page":40}},{"id":"mn-026","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"It is the last number in 30/60/10.","h2":"Minnesota requires at least $10,000 of property damage liability for one crash, the last number in the 30/60/10 minimum.","p":"Right. The property damage minimum is $10,000."},"es":{"q":"En Minnesota, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Es el último número de 30/60/10.","h2":"Minnesota exige por lo menos $10,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/10.","p":"Correcto. El mínimo por daños a la propiedad es $10,000."},"zh":{"q":"在 Minnesota，一次车祸中对别人财产损失的最低责任保险是多少？","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"它是 30/60/10 里的最后一个数字。","h2":"Minnesota 要求一次车祸至少有 $10,000 的财产损失责任保险，也就是 30/60/10 最低标准里的最后一个数字。","p":"对。财产损失的最低额是 $10,000。"},"vi":{"q":"Ở Minnesota, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một tai nạn là bao nhiêu?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Đó là số cuối cùng trong 30/60/10.","h2":"Minnesota yêu cầu ít nhất $10,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một tai nạn, là số cuối cùng trong mức tối thiểu 30/60/10.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $10,000."},"tl":{"q":"Sa Minnesota, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"Ito ang huling bilang sa 30/60/10.","h2":"Inuutos ng Minnesota ang hindi bababa sa $10,000 na property damage liability para sa isang banggaan, ang huling bilang sa minimum na 30/60/10.","p":"Tama. Ang minimum para sa pinsala sa ari-arian ay $10,000."},"ar":{"q":"في Minnesota، ما الحد الأدنى لتأمين المسؤولية عن الضرر في ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$15,000","$25,000","$30,000"],"h1":"إنه الرقم الأخير في 30/60/10.","h2":"تشترط Minnesota تأمين مسؤولية عن الضرر في الممتلكات قدره $10,000 على الأقل لحادث واحد، وهو الرقم الأخير في الحد الأدنى 30/60/10.","p":"صحيح. الحد الأدنى للضرر في الممتلكات هو $10,000."},"ref":{"doc":"MN","page":null}},{"id":"mn-027","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"Minnesota's distance is shorter than in many other states.","h2":"In Minnesota you may not park within 10 feet of a fire hydrant, so fire crews can reach it.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En Minnesota, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies"],"h1":"La distancia de Minnesota es más corta que en muchos otros estados.","h2":"En Minnesota usted no puede estacionarse a menos de 10 pies de un hidrante, para que los bomberos puedan llegar a él.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Minnesota，你可以把车停在离消防栓多近的地方？","o":["不得近于 5 英尺","不得近于 10 英尺","不得近于 15 英尺","不得近于 25 英尺"],"h1":"Minnesota 的距离比很多其他州短。","h2":"在 Minnesota，你不可以在离消防栓 10 英尺以内停车，这样消防员才能用到它。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở Minnesota, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Khoảng cách ở Minnesota ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Minnesota, bạn không được đậu xe trong vòng 10 feet cách trụ nước cứu hỏa, để lính cứu hỏa có thể đến được trụ nước.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Minnesota, gaano kalapit sa fire hydrant ang puwede mong pagparadahan?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 25 feet"],"h1":"Mas maikli ang layo sa Minnesota kaysa sa maraming ibang estado.","h2":"Sa Minnesota, hindi ka puwedeng pumarada sa loob ng 10 feet mula sa fire hydrant, para maabot ito ng mga bumbero.","p":"Tama. Lumayo nang hindi bababa sa 10 feet mula sa hydrant."},"ar":{"q":"في Minnesota، إلى أي مسافة يمكنك أن تركن قرب صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 25 feet"],"h1":"المسافة في Minnesota أقصر منها في كثير من الولايات الأخرى.","h2":"في Minnesota لا يجوز لك أن تركن على بعد أقل من 10 feet من صنبور إطفاء الحريق، حتى يستطيع رجال الإطفاء الوصول إليه.","p":"صحيح. ابقَ على بعد 10 feet على الأقل من صنبور الإطفاء."},"ref":{"doc":"MN","page":35}},{"id":"mn-028","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what vision do you need to pass the vision screening, with glasses or contacts if you use them?","o":["At least 20/20","At least 20/30","At least 20/40","At least 20/70"],"h1":"It is the same number many states use.","h2":"In Minnesota your vision, with or without correction, must be at least 20/40 to pass the vision screening.","p":"Right. You need at least 20/40 vision."},"es":{"q":"En Minnesota, ¿qué visión necesita para pasar el examen de la vista, con lentes o lentes de contacto si los usa?","o":["Por lo menos 20/20","Por lo menos 20/30","Por lo menos 20/40","Por lo menos 20/70"],"h1":"Es el mismo número que usan muchos estados.","h2":"En Minnesota su visión, con o sin corrección, debe ser por lo menos 20/40 para pasar el examen de la vista.","p":"Correcto. Necesita una visión de por lo menos 20/40."},"zh":{"q":"在 Minnesota，要通过视力检查，你需要多好的视力？（如果你戴眼镜或隐形眼镜，就戴着测）","o":["至少 20/20","至少 20/30","至少 20/40","至少 20/70"],"h1":"这和很多州用的数字一样。","h2":"在 Minnesota，你的视力（戴不戴矫正眼镜都算）必须至少是 20/40，才能通过视力检查。","p":"对。你的视力需要至少 20/40。"},"vi":{"q":"Ở Minnesota, bạn cần thị lực như thế nào để qua bài kiểm tra mắt, khi đeo kính hoặc kính áp tròng nếu bạn có dùng?","o":["Ít nhất 20/20","Ít nhất 20/30","Ít nhất 20/40","Ít nhất 20/70"],"h1":"Đó là con số mà nhiều tiểu bang cũng dùng.","h2":"Ở Minnesota, thị lực của bạn, có hoặc không có kính, phải ít nhất là 20/40 để qua bài kiểm tra mắt.","p":"Đúng. Bạn cần thị lực ít nhất 20/40."},"tl":{"q":"Sa Minnesota, anong paningin ang kailangan mo para pumasa sa vision screening, suot ang salamin o contact lens kung gumagamit ka nito?","o":["Hindi bababa sa 20/20","Hindi bababa sa 20/30","Hindi bababa sa 20/40","Hindi bababa sa 20/70"],"h1":"Ito rin ang numerong ginagamit ng maraming estado.","h2":"Sa Minnesota, ang paningin mo, may salamin man o wala, ay dapat hindi bababa sa 20/40 para pumasa sa vision screening.","p":"Tama. Kailangan mo ng paningin na hindi bababa sa 20/40."},"ar":{"q":"في Minnesota، ما قوة النظر التي تحتاجها لتنجح في فحص النظر، مع النظارة أو العدسات اللاصقة إن كنت تستعملها؟","o":["20/20 على الأقل","20/30 على الأقل","20/40 على الأقل","20/70 على الأقل"],"h1":"إنه الرقم نفسه الذي تستعمله ولايات كثيرة.","h2":"في Minnesota يجب أن يكون نظرك، مع التصحيح أو بدونه، 20/40 على الأقل لتنجح في فحص النظر.","p":"صحيح. تحتاج إلى نظر 20/40 على الأقل."},"ref":{"doc":"MN","page":10}},{"id":"mn-029","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how much space must you leave between your car and a bicyclist you are passing?","o":["At least 3 feet","At least 1 foot","At least 18 inches","At least 2 feet"],"h1":"Think of about one long step.","h2":"In Minnesota you must leave at least 3 feet between your car and a bicyclist when you pass, and you may cross the center line to do it when it is safe.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Minnesota, ¿cuánto espacio debe dejar entre su carro y un ciclista al que va a rebasar?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 18 pulgadas","Por lo menos 2 pies"],"h1":"Piense en un paso largo.","h2":"En Minnesota usted debe dejar por lo menos 3 pies entre su carro y un ciclista al rebasarlo, y puede cruzar la línea central para hacerlo cuando sea seguro.","p":"Correcto. Deje por lo menos 3 pies a un ciclista."},"zh":{"q":"在 Minnesota，你超过骑自行车的人时，你的车和他之间必须留多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 18 英寸","至少 2 英尺"],"h1":"想一想大约一大步的距离。","h2":"在 Minnesota，你超过骑自行车的人时，必须在你的车和他之间留至少 3 英尺；在安全的时候，你可以越过中线来这样做。","p":"对。给骑自行车的人留至少 3 英尺。"},"vi":{"q":"Ở Minnesota, khi vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa xe của bạn và người đó?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 18 inches","Ít nhất 2 feet"],"h1":"Hãy nghĩ đến khoảng một bước dài.","h2":"Ở Minnesota, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và người đó, và bạn được lấn qua vạch giữa đường để làm vậy khi an toàn.","p":"Đúng. Hãy chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Minnesota, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng kotse mo at ng nagbibisikleta na inuunahan mo?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 18 inches","Hindi bababa sa 2 feet"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Minnesota, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng kotse mo at ng nagbibisikleta kapag inuunahan mo siya, at puwede kang tumawid sa gitnang linya para gawin ito kapag ligtas.","p":"Tama. Bigyan ang nagbibisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Minnesota، كم مسافة يجب أن تتركها بين سيارتك وراكب الدراجة الذي تتجاوزه؟","o":["3 feet على الأقل","1 foot على الأقل","18 inches على الأقل","2 feet على الأقل"],"h1":"فكّر في خطوة طويلة تقريبًا.","h2":"في Minnesota يجب أن تترك 3 feet على الأقل بين سيارتك وراكب الدراجة عندما تتجاوزه، ويجوز لك أن تعبر الخط الأوسط لتفعل ذلك عندما يكون آمنًا.","p":"صحيح. اترك 3 feet على الأقل لراكب الدراجة."},"ref":{"doc":"MN","page":48}},{"id":"mn-030","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, how close to an intersection or railroad crossing may you pass another vehicle?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 300 feet","No closer than 100 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Minnesota you may not pass another vehicle within 100 feet of an intersection, underpass, tunnel or railroad crossing.","p":"Right. Do not pass within 100 feet of those places."},"es":{"q":"En Minnesota, ¿qué tan cerca de una intersección o de un cruce de ferrocarril puede rebasar a otro vehículo?","o":["No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 300 pies","No más cerca de 100 pies"],"h1":"Es como el largo de seis o siete carros.","h2":"En Minnesota usted no puede rebasar a otro vehículo a menos de 100 pies de una intersección, un paso a desnivel, un túnel o un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de esos lugares."},"zh":{"q":"在 Minnesota，你可以在离路口或铁路道口多近的地方超车？","o":["不得近于 25 英尺","不得近于 50 英尺","不得近于 300 英尺","不得近于 100 英尺"],"h1":"大约是六七辆车的长度。","h2":"在 Minnesota，你不可以在离路口、地下通道、隧道或铁路道口 100 英尺以内超车。","p":"对。在这些地方 100 英尺以内不要超车。"},"vi":{"q":"Ở Minnesota, bạn được vượt xe khác khi cách giao lộ hoặc chỗ băng qua đường ray xe lửa bao xa?","o":["Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 300 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều dài của sáu hoặc bảy chiếc xe.","h2":"Ở Minnesota, bạn không được vượt xe khác trong vòng 100 feet cách giao lộ, đường chui, đường hầm hoặc chỗ băng qua đường ray xe lửa.","p":"Đúng. Không vượt xe trong vòng 100 feet cách những nơi đó."},"tl":{"q":"Sa Minnesota, gaano kalapit sa intersection o tawiran ng riles ng tren ang puwede kang umunahan ng ibang sasakyan?","o":["Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 300 feet","Hindi lalapit sa 100 feet"],"h1":"Mga haba ito ng anim o pitong kotse.","h2":"Sa Minnesota, hindi ka puwedeng umunahan ng ibang sasakyan sa loob ng 100 feet mula sa intersection, underpass, tunnel o tawiran ng riles ng tren.","p":"Tama. Huwag umunahan sa loob ng 100 feet mula sa mga lugar na iyon."},"ar":{"q":"في Minnesota، على أي مسافة من تقاطع أو معبر سكة حديد يمكنك أن تتجاوز مركبة أخرى؟","o":["ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 300 feet","ليس أقرب من 100 feet"],"h1":"إنها تقريبًا طول ست أو سبع سيارات.","h2":"في Minnesota لا يجوز لك أن تتجاوز مركبة أخرى على بعد أقل من 100 feet من تقاطع أو ممر سفلي أو نفق أو معبر سكة حديد.","p":"صحيح. لا تتجاوز على بعد أقل من 100 feet من تلك الأماكن."},"ref":{"doc":"MN","page":34}},{"id":"mn-031","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, when does a driver's license marked \"Under 21\" expire?","o":["On your 18th birthday","One year after it is issued","On your 21st birthday","On your 25th birthday"],"h1":"Look at the words printed on the license.","h2":"In Minnesota a license marked \"Under 21\" expires on your 21st birthday, and after that it expires every four years on your birthday.","p":"Right. It expires on your 21st birthday."},"es":{"q":"En Minnesota, ¿cuándo vence una licencia de manejo marcada \"Under 21\" (menor de 21)?","o":["En su cumpleaños número 18","Un año después de emitida","En su cumpleaños número 21","En su cumpleaños número 25"],"h1":"Fíjese en las palabras impresas en la licencia.","h2":"En Minnesota una licencia marcada \"Under 21\" vence en su cumpleaños número 21, y después vence cada cuatro años en su cumpleaños.","p":"Correcto. Vence en su cumpleaños número 21."},"zh":{"q":"在 Minnesota，标有 \"Under 21\"（未满 21 岁）的驾照什么时候过期？","o":["在你 18 岁生日那天","发证一年以后","在你 21 岁生日那天","在你 25 岁生日那天"],"h1":"看看驾照上印的字。","h2":"在 Minnesota，标有 \"Under 21\" 的驾照在你 21 岁生日那天过期，以后每四年在你生日那天过期。","p":"对。它在你 21 岁生日那天过期。"},"vi":{"q":"Ở Minnesota, bằng lái có ghi \"Under 21\" (dưới 21 tuổi) hết hạn khi nào?","o":["Vào sinh nhật thứ 18 của bạn","Một năm sau khi được cấp","Vào sinh nhật thứ 21 của bạn","Vào sinh nhật thứ 25 của bạn"],"h1":"Hãy nhìn chữ in trên bằng lái.","h2":"Ở Minnesota, bằng lái có ghi \"Under 21\" hết hạn vào sinh nhật thứ 21 của bạn, và sau đó hết hạn mỗi bốn năm vào ngày sinh nhật của bạn.","p":"Đúng. Bằng lái hết hạn vào sinh nhật thứ 21 của bạn."},"tl":{"q":"Sa Minnesota, kailan mag-e-expire ang driver's license na may markang \"Under 21\" (wala pang 21)?","o":["Sa ika-18 kaarawan mo","Isang taon pagkatapos itong ibigay","Sa ika-21 kaarawan mo","Sa ika-25 kaarawan mo"],"h1":"Tingnan ang mga salitang nakalimbag sa lisensya.","h2":"Sa Minnesota, ang lisensyang may markang \"Under 21\" ay mag-e-expire sa ika-21 kaarawan mo, at pagkatapos noon ay mag-e-expire ito tuwing apat na taon sa kaarawan mo.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan mo."},"ar":{"q":"في Minnesota، متى تنتهي صلاحية رخصة القيادة المكتوب عليها \"Under 21\" (أقل من 21)؟","o":["في عيد ميلادك الـ 18","بعد سنة من إصدارها","في عيد ميلادك الـ 21","في عيد ميلادك الـ 25"],"h1":"انظر إلى الكلمات المطبوعة على الرخصة.","h2":"في Minnesota تنتهي صلاحية الرخصة المكتوب عليها \"Under 21\" في عيد ميلادك الـ 21، وبعد ذلك تنتهي صلاحيتها كل أربع سنوات في عيد ميلادك.","p":"صحيح. تنتهي صلاحيتها في عيد ميلادك الـ 21."},"ref":{"doc":"MN","page":16}},{"id":"mn-032","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, you just became a resident and have a valid car license from another state. How long do you have to get a Minnesota license?","o":["30 days","60 days","90 days","1 year"],"h1":"It is more than one month but less than three.","h2":"A new Minnesota resident with a valid license from another state has 60 days to get a Minnesota license.","p":"Right. New residents have 60 days."},"es":{"q":"En Minnesota, usted acaba de hacerse residente y tiene una licencia de auto válida de otro estado. ¿Cuánto tiempo tiene para sacar una licencia de Minnesota?","o":["30 días","60 días","90 días","1 año"],"h1":"Es más de un mes, pero menos de tres.","h2":"Un nuevo residente de Minnesota con una licencia válida de otro estado tiene 60 días para sacar una licencia de Minnesota.","p":"Correcto. Los nuevos residentes tienen 60 días."},"zh":{"q":"在 Minnesota，你刚成为居民，并且有另一个州的有效汽车驾照。你有多长时间去办 Minnesota 驾照？","o":["30 天","60 天","90 天","1 年"],"h1":"比一个月长，但比三个月短。","h2":"持有其他州有效驾照的 Minnesota 新居民有 60 天时间去办 Minnesota 驾照。","p":"对。新居民有 60 天。"},"vi":{"q":"Ở Minnesota, bạn vừa trở thành cư dân và có bằng lái xe hơi còn hiệu lực của một tiểu bang khác. Bạn có bao lâu để lấy bằng lái Minnesota?","o":["30 ngày","60 ngày","90 ngày","1 năm"],"h1":"Hơn một tháng nhưng ít hơn ba tháng.","h2":"Cư dân mới của Minnesota có bằng lái còn hiệu lực của tiểu bang khác có 60 ngày để lấy bằng lái Minnesota.","p":"Đúng. Cư dân mới có 60 ngày."},"tl":{"q":"Sa Minnesota, bago ka pa lang naging residente at may valid na lisensya ng kotse mula sa ibang state. Gaano katagal ang mayroon ka para kumuha ng lisensya ng Minnesota?","o":["30 araw","60 araw","90 araw","1 taon"],"h1":"Higit ito sa isang buwan pero kulang sa tatlo.","h2":"Ang bagong residente ng Minnesota na may valid na lisensya mula sa ibang state ay may 60 araw para kumuha ng lisensya ng Minnesota.","p":"Tama. May 60 araw ang mga bagong residente."},"ar":{"q":"في Minnesota، أصبحت مقيمًا للتو ولديك رخصة سيارة سارية من ولاية أخرى. كم لديك من الوقت للحصول على رخصة Minnesota؟","o":["30 يومًا","60 يومًا","90 يومًا","سنة واحدة"],"h1":"إنها أكثر من شهر واحد وأقل من ثلاثة أشهر.","h2":"المقيم الجديد في Minnesota الذي لديه رخصة سارية من ولاية أخرى لديه 60 يومًا للحصول على رخصة Minnesota.","p":"صحيح. لدى المقيمين الجدد 60 يومًا."},"ref":{"doc":"MN","page":6}},{"id":"mn-033","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how long is an instruction permit valid?","o":["6 months","1 year","4 years","2 years"],"h1":"It gives you more than one year to practice.","h2":"A Minnesota instruction permit is valid for two years of practice driving with a supervising driver.","p":"Right. The permit lasts two years."},"es":{"q":"En Minnesota, ¿por cuánto tiempo es válido un permiso de aprendizaje (instruction permit)?","o":["6 meses","1 año","4 años","2 años"],"h1":"Le da más de un año para practicar.","h2":"Un permiso de aprendizaje de Minnesota es válido por dos años de práctica con un conductor supervisor.","p":"Correcto. El permiso dura dos años."},"zh":{"q":"在 Minnesota，学习驾照（instruction permit）的有效期是多久？","o":["6 个月","1 年","4 年","2 年"],"h1":"它给你一年以上的时间练习。","h2":"Minnesota 的学习驾照有效期是两年，让你和监督司机一起练习开车。","p":"对。学习驾照有效两年。"},"vi":{"q":"Ở Minnesota, giấy phép tập lái (instruction permit) có hiệu lực bao lâu?","o":["6 tháng","1 năm","4 năm","2 năm"],"h1":"Nó cho bạn hơn một năm để tập lái.","h2":"Giấy phép tập lái ở Minnesota có hiệu lực hai năm để tập lái cùng với một người lái xe giám sát.","p":"Đúng. Giấy phép tập lái có hiệu lực hai năm."},"tl":{"q":"Sa Minnesota, gaano katagal valid ang instruction permit (permit sa pag-aaral magmaneho)?","o":["6 buwan","1 taon","4 na taon","2 taon"],"h1":"Binibigyan ka nito ng higit sa isang taon para magsanay.","h2":"Ang instruction permit sa Minnesota ay valid nang dalawang taon para magsanay magmaneho kasama ang isang supervising driver.","p":"Tama. Dalawang taon ang permit."},"ar":{"q":"في Minnesota، كم مدة صلاحية تصريح التعلّم (instruction permit)؟","o":["6 أشهر","سنة واحدة","4 سنوات","سنتان"],"h1":"إنه يعطيك أكثر من سنة واحدة للتدرّب.","h2":"تصريح التعلّم في Minnesota صالح لمدة سنتين للتدرّب على القيادة مع سائق مشرف.","p":"صحيح. يدوم التصريح سنتين."},"ref":{"doc":"MN","page":13}},{"id":"mn-034","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, you move to a new address. How soon must you apply for a duplicate license?","o":["Within 30 days","Within 90 days","Within 1 year","At your next renewal"],"h1":"Do not wait for your renewal. The time is short.","h2":"In Minnesota, if you change your name or address, you must apply for a duplicate license within 30 days.","p":"Right. Apply within 30 days."},"es":{"q":"En Minnesota, usted se muda a una nueva dirección. ¿En cuánto tiempo debe solicitar una licencia duplicada?","o":["Dentro de 30 días","Dentro de 90 días","Dentro de 1 año","En su próxima renovación"],"h1":"No espere a la renovación. El plazo es corto.","h2":"En Minnesota, si cambia de nombre o de dirección, debe solicitar una licencia duplicada dentro de 30 días.","p":"Correcto. Solicítela dentro de 30 días."},"zh":{"q":"在 Minnesota，你搬到了新地址。你必须多快申请补发驾照？","o":["30 天内","90 天内","1 年内","下次续期时"],"h1":"不要等到续期。时间很短。","h2":"在 Minnesota，如果你改了名字或地址，你必须在 30 天内申请补发驾照。","p":"对。在 30 天内申请。"},"vi":{"q":"Ở Minnesota, bạn chuyển đến địa chỉ mới. Bạn phải xin bằng lái thay thế (duplicate license) trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 90 ngày","Trong vòng 1 năm","Vào lần gia hạn tới"],"h1":"Đừng đợi đến lúc gia hạn. Thời gian rất ngắn.","h2":"Ở Minnesota, nếu bạn đổi tên hoặc địa chỉ, bạn phải xin bằng lái thay thế trong vòng 30 ngày.","p":"Đúng. Hãy xin trong vòng 30 ngày."},"tl":{"q":"Sa Minnesota, lumipat ka sa bagong address. Gaano kabilis ka dapat mag-apply para sa duplicate license?","o":["Sa loob ng 30 araw","Sa loob ng 90 araw","Sa loob ng 1 taon","Sa susunod mong renewal"],"h1":"Huwag hintayin ang renewal mo. Maikli ang oras.","h2":"Sa Minnesota, kung magpapalit ka ng pangalan o address, dapat kang mag-apply para sa duplicate license sa loob ng 30 araw.","p":"Tama. Mag-apply sa loob ng 30 araw."},"ar":{"q":"في Minnesota، انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تطلب رخصة بديلة (duplicate license)؟","o":["خلال 30 يومًا","خلال 90 يومًا","خلال سنة واحدة","عند التجديد القادم"],"h1":"لا تنتظر موعد التجديد. الوقت قصير.","h2":"في Minnesota، إذا غيّرت اسمك أو عنوانك، يجب أن تطلب رخصة بديلة خلال 30 يومًا.","p":"صحيح. اطلبها خلال 30 يومًا."},"ref":{"doc":"MN","page":19}},{"id":"mn-035","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, after a crash, an officer asks for your insurance information, but you do not have it with you. How soon must you give it?","o":["Within 24 hours","Within 30 days","Within 72 hours","Within 10 days"],"h1":"It is a few days, not weeks.","h2":"After a crash in Minnesota, if you do not have your insurance information with you, you must provide it within 72 hours.","p":"Right. You have 72 hours."},"es":{"q":"En Minnesota, después de un choque, un oficial le pide la información de su seguro, pero usted no la tiene consigo. ¿En cuánto tiempo debe darla?","o":["Dentro de 24 horas","Dentro de 30 días","Dentro de 72 horas","Dentro de 10 días"],"h1":"Son unos pocos días, no semanas.","h2":"Después de un choque en Minnesota, si no tiene consigo la información de su seguro, debe entregarla dentro de 72 horas.","p":"Correcto. Tiene 72 horas."},"zh":{"q":"在 Minnesota，车祸后警察要你的保险资料，但你身上没有带。你必须多快提供？","o":["24 小时内","30 天内","72 小时内","10 天内"],"h1":"是几天，不是几个星期。","h2":"在 Minnesota 发生车祸后，如果你身上没有带保险资料，你必须在 72 小时内提供。","p":"对。你有 72 小时。"},"vi":{"q":"Ở Minnesota, sau một tai nạn, cảnh sát hỏi thông tin bảo hiểm của bạn, nhưng bạn không mang theo. Bạn phải đưa thông tin đó trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 30 ngày","Trong vòng 72 giờ","Trong vòng 10 ngày"],"h1":"Đó là vài ngày, không phải vài tuần.","h2":"Sau một tai nạn ở Minnesota, nếu bạn không mang theo thông tin bảo hiểm, bạn phải đưa thông tin đó trong vòng 72 giờ.","p":"Đúng. Bạn có 72 giờ."},"tl":{"q":"Sa Minnesota, pagkatapos ng banggaan, hinihingi ng pulis ang impormasyon ng insurance mo, pero wala ito sa iyo. Gaano kabilis mo ito dapat ibigay?","o":["Sa loob ng 24 oras","Sa loob ng 30 araw","Sa loob ng 72 oras","Sa loob ng 10 araw"],"h1":"Ilang araw ito, hindi ilang linggo.","h2":"Pagkatapos ng banggaan sa Minnesota, kung wala sa iyo ang impormasyon ng insurance mo, dapat mo itong ibigay sa loob ng 72 oras.","p":"Tama. May 72 oras ka."},"ar":{"q":"في Minnesota، بعد حادث، يطلب منك الشرطي معلومات التأمين، لكنها ليست معك. خلال كم من الوقت يجب أن تقدّمها؟","o":["خلال 24 ساعة","خلال 30 يومًا","خلال 72 ساعة","خلال 10 أيام"],"h1":"إنها بضعة أيام، وليست أسابيع.","h2":"بعد حادث في Minnesota، إذا لم تكن معلومات التأمين معك، يجب أن تقدّمها خلال 72 ساعة.","p":"صحيح. لديك 72 ساعة."},"ref":{"doc":"MN","page":39}},{"id":"mn-036","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what must you do after you fail the road test four times?","o":["Wait one full year before testing again","Take at least 6 hours of lessons with a licensed instructor","Ride with a police officer for one day","Pay a $500 retest fee"],"h1":"Think about what would help you drive better.","h2":"In Minnesota, after four failed road tests you must take at least six hours of behind-the-wheel lessons with a licensed instructor before you test again.","p":"Right. Six hours of lessons come first."},"es":{"q":"En Minnesota, ¿qué debe hacer después de reprobar el examen de manejo cuatro veces?","o":["Esperar un año completo antes de volver a intentarlo","Tomar por lo menos 6 horas de clases con un instructor con licencia","Viajar con un policía durante un día","Pagar $500 por volver a tomar el examen"],"h1":"Piense en lo que le ayudaría a manejar mejor.","h2":"En Minnesota, después de reprobar el examen de manejo cuatro veces, debe tomar por lo menos seis horas de clases al volante con un instructor con licencia antes de volver a intentarlo.","p":"Correcto. Primero vienen seis horas de clases."},"zh":{"q":"在 Minnesota，路考没通过四次以后，你必须做什么？","o":["等满一年才能再考","跟有执照的教练上至少 6 小时的课","跟警察坐车一天","付 $500 的重考费"],"h1":"想一想什么能帮你开得更好。","h2":"在 Minnesota，路考四次没通过以后，你必须先跟有执照的教练上至少六小时的实际驾驶课，才能再考。","p":"对。先上六小时的课。"},"vi":{"q":"Ở Minnesota, bạn phải làm gì sau khi thi lái thực hành bị rớt bốn lần?","o":["Đợi đủ một năm rồi mới thi lại","Học ít nhất 6 giờ với một giáo viên có giấy phép","Đi xe cùng cảnh sát một ngày","Trả $500 phí thi lại"],"h1":"Hãy nghĩ xem điều gì giúp bạn lái xe tốt hơn.","h2":"Ở Minnesota, sau bốn lần rớt thi lái thực hành, bạn phải học ít nhất sáu giờ lái xe thực tế với một giáo viên có giấy phép trước khi thi lại.","p":"Đúng. Phải học sáu giờ trước."},"tl":{"q":"Sa Minnesota, ano ang dapat mong gawin pagkatapos bumagsak sa road test nang apat na beses?","o":["Maghintay ng isang buong taon bago mag-test ulit","Kumuha ng hindi bababa sa 6 na oras ng lesson sa isang lisensyadong instructor","Sumakay kasama ang isang pulis nang isang araw","Magbayad ng $500 na retest fee"],"h1":"Isipin kung ano ang makakatulong para mas gumaling kang magmaneho.","h2":"Sa Minnesota, pagkatapos ng apat na bagsak na road test, dapat kang kumuha ng hindi bababa sa anim na oras ng behind-the-wheel lesson sa isang lisensyadong instructor bago ka mag-test ulit.","p":"Tama. Anim na oras ng lesson muna."},"ar":{"q":"في Minnesota، ماذا يجب أن تفعل بعد أن ترسب في اختبار القيادة على الطريق أربع مرات؟","o":["تنتظر سنة كاملة قبل أن تختبر مرة أخرى","تأخذ 6 ساعات على الأقل من الدروس مع مدرّب مرخّص","تركب مع شرطي ليوم واحد","تدفع رسوم إعادة اختبار قدرها $500"],"h1":"فكّر فيما يساعدك على القيادة بشكل أفضل.","h2":"في Minnesota، بعد الرسوب في اختبار الطريق أربع مرات يجب أن تأخذ ست ساعات على الأقل من دروس القيادة العملية مع مدرّب مرخّص قبل أن تختبر مرة أخرى.","p":"صحيح. ست ساعات من الدروس أولًا."},"ref":{"doc":"MN","page":12}},{"id":"mn-037","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, you are stranded in your car during a winter storm. What is the safest thing to do?","o":["Walk to the nearest house for help","Keep the engine running with all windows shut","Leave the car to look for the main road","Stay with your vehicle and wait for help"],"h1":"Most deaths happen when people get lost out in the cold.","h2":"If you are stranded in cold weather in Minnesota, stay with your vehicle and wait for help, because most deaths happen when people leave their cars and get lost.","p":"Right. Stay with your car."},"es":{"q":"En Minnesota, usted queda atrapado en su auto durante una tormenta de invierno. ¿Qué es lo más seguro?","o":["Caminar a la casa más cercana para pedir ayuda","Dejar el motor encendido con todas las ventanas cerradas","Salir del auto para buscar la carretera principal","Quedarse en su vehículo y esperar ayuda"],"h1":"La mayoría de las muertes ocurren cuando la gente se pierde en el frío.","h2":"Si queda atrapado en el frío en Minnesota, quédese en su vehículo y espere ayuda, porque la mayoría de las muertes ocurren cuando la gente deja el auto y se pierde.","p":"Correcto. Quédese en su auto."},"zh":{"q":"在 Minnesota，冬天暴风雪时你被困在车里。最安全的做法是什么？","o":["走到最近的房子求助","关紧所有车窗，让引擎一直开着","离开车子去找大路","留在车里等人来帮忙"],"h1":"大多数死亡发生在人们在寒冷中迷路的时候。","h2":"如果你在 Minnesota 的寒冷天气里被困，要留在车里等人来帮忙，因为大多数死亡发生在人们离开车子后迷路的时候。","p":"对。留在车里。"},"vi":{"q":"Ở Minnesota, bạn bị kẹt trong xe khi có bão tuyết mùa đông. Điều gì an toàn nhất nên làm?","o":["Đi bộ đến căn nhà gần nhất để xin giúp đỡ","Để máy xe chạy và đóng kín tất cả cửa sổ","Rời khỏi xe để tìm đường lớn","Ở lại trong xe và chờ người đến giúp"],"h1":"Phần lớn các ca tử vong xảy ra khi người ta bị lạc ngoài trời lạnh.","h2":"Nếu bạn bị kẹt khi trời lạnh ở Minnesota, hãy ở lại trong xe và chờ người đến giúp, vì phần lớn các ca tử vong xảy ra khi người ta rời xe và bị lạc.","p":"Đúng. Hãy ở lại trong xe."},"tl":{"q":"Sa Minnesota, na-stranded ka sa kotse mo habang may winter storm. Ano ang pinakaligtas na gawin?","o":["Maglakad papunta sa pinakamalapit na bahay para humingi ng tulong","Panatilihing nakaandar ang makina at nakasara lahat ng bintana","Iwan ang kotse para hanapin ang malaking daan","Manatili sa sasakyan mo at maghintay ng tulong"],"h1":"Karamihan ng namamatay ay nangyayari kapag naliligaw ang tao sa lamig.","h2":"Kung na-stranded ka sa malamig na panahon sa Minnesota, manatili sa sasakyan mo at maghintay ng tulong, dahil karamihan ng namamatay ay nangyayari kapag iniiwan ng tao ang kotse nila at naliligaw.","p":"Tama. Manatili sa kotse mo."},"ar":{"q":"في Minnesota، علقت في سيارتك أثناء عاصفة شتوية. ما أكثر شيء آمن تفعله؟","o":["تمشي إلى أقرب بيت لطلب المساعدة","تترك المحرك يعمل وكل النوافذ مغلقة","تترك السيارة لتبحث عن الطريق الرئيسي","تبقى مع مركبتك وتنتظر المساعدة"],"h1":"معظم الوفيات تحدث عندما يضيع الناس في البرد.","h2":"إذا علقت في طقس بارد في Minnesota، ابقَ مع مركبتك وانتظر المساعدة، لأن معظم الوفيات تحدث عندما يترك الناس سياراتهم ويضيعون.","p":"صحيح. ابقَ مع سيارتك."},"ref":{"doc":"MN","page":82}},{"id":"mn-038","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, you are stranded in a cold car. How long should you run the engine and heater?","o":["About 10 minutes each hour","Nonstop until help comes","About 1 minute each hour","Never, keep it off the whole time"],"h1":"Run it long enough to warm up and charge the battery, then turn it off.","h2":"When you are stranded in the cold, run the engine about 10 minutes each hour, keep the exhaust pipe clear of snow and leave a window open a little.","p":"Right. About 10 minutes each hour."},"es":{"q":"En Minnesota, usted está atrapado en un auto frío. ¿Cuánto tiempo debe encender el motor y la calefacción?","o":["Unos 10 minutos cada hora","Sin parar hasta que llegue ayuda","Como 1 minuto cada hora","Nunca, debe dejarlo apagado todo el tiempo"],"h1":"Enciéndalo lo suficiente para calentarse y cargar la batería, y luego apáguelo.","h2":"Cuando está atrapado en el frío, encienda el motor unos 10 minutos cada hora, mantenga el tubo de escape libre de nieve y deje una ventana un poco abierta.","p":"Correcto. Unos 10 minutos cada hora."},"zh":{"q":"在 Minnesota，你被困在很冷的车里。你应该开引擎和暖气多久？","o":["每小时大约 10 分钟","一直开到有人来帮忙","每小时大约 1 分钟","一直不开，全程关着"],"h1":"开到足够让车变暖、给电池充电，然后关掉。","h2":"你在寒冷中被困时，每小时开引擎大约 10 分钟，保持排气管周围没有雪，并把一扇车窗开一点缝。","p":"对。每小时大约 10 分钟。"},"vi":{"q":"Ở Minnesota, bạn bị kẹt trong một chiếc xe lạnh. Bạn nên cho máy xe và máy sưởi chạy bao lâu?","o":["Khoảng 10 phút mỗi giờ","Liên tục cho đến khi có người đến giúp","Khoảng 1 phút mỗi giờ","Không bao giờ, tắt suốt thời gian"],"h1":"Cho chạy đủ lâu để làm ấm và sạc bình điện, rồi tắt đi.","h2":"Khi bạn bị kẹt trong trời lạnh, hãy cho máy xe chạy khoảng 10 phút mỗi giờ, giữ ống xả không bị tuyết lấp và mở hé một cửa sổ.","p":"Đúng. Khoảng 10 phút mỗi giờ."},"tl":{"q":"Sa Minnesota, na-stranded ka sa malamig na kotse. Gaano katagal mo dapat paandarin ang makina at heater?","o":["Mga 10 minuto bawat oras","Tuloy-tuloy hanggang dumating ang tulong","Mga 1 minuto bawat oras","Hindi kailanman, nakapatay ito buong oras"],"h1":"Paandarin ito nang sapat para uminit at ma-charge ang baterya, tapos patayin.","h2":"Kapag na-stranded ka sa lamig, paandarin ang makina nang mga 10 minuto bawat oras, panatilihing walang snow ang tambutso at iwanang bahagyang nakabukas ang isang bintana.","p":"Tama. Mga 10 minuto bawat oras."},"ar":{"q":"في Minnesota، علقت في سيارة باردة. كم من الوقت يجب أن تشغّل المحرك والمدفأة؟","o":["حوالي 10 دقائق كل ساعة","بلا توقف حتى تصل المساعدة","حوالي دقيقة واحدة كل ساعة","أبدًا، يبقى مطفأً طوال الوقت"],"h1":"شغّله وقتًا كافيًا ليدفأ المكان وتُشحن البطارية، ثم أطفئه.","h2":"عندما تعلق في البرد، شغّل المحرك حوالي 10 دقائق كل ساعة، وأبقِ أنبوب العادم خاليًا من الثلج، واترك نافذة مفتوحة قليلًا.","p":"صحيح. حوالي 10 دقائق كل ساعة."},"ref":{"doc":"MN","page":82}},{"id":"mn-039","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, which flashing lights warn you that a snowplow is ahead?","o":["Green only","Red and green","White, yellow and blue","Purple only"],"h1":"Snowplows may use a color that police cars use too.","h2":"In Minnesota, snowplows use flashing white, yellow and blue lights, so watch for them when roads have snow or ice.","p":"Right. White, yellow and blue mean a snowplow."},"es":{"q":"En Minnesota, ¿qué luces intermitentes le avisan que hay un quitanieves adelante?","o":["Solo verdes","Rojas y verdes","Blancas, amarillas y azules","Solo moradas"],"h1":"Los quitanieves pueden usar un color que también usan los autos de policía.","h2":"En Minnesota, los quitanieves usan luces intermitentes blancas, amarillas y azules, así que búsquelas cuando hay nieve o hielo en la carretera.","p":"Correcto. Blancas, amarillas y azules indican un quitanieves."},"zh":{"q":"在 Minnesota，哪种闪灯提醒你前面有扫雪车？","o":["只有绿色","红色和绿色","白色、黄色和蓝色","只有紫色"],"h1":"扫雪车可能会用一种警车也用的颜色。","h2":"在 Minnesota，扫雪车使用闪烁的白色、黄色和蓝色灯，所以路上有雪或冰时要注意它们。","p":"对。白色、黄色和蓝色表示扫雪车。"},"vi":{"q":"Ở Minnesota, đèn nhấp nháy nào báo cho bạn biết có xe ủi tuyết phía trước?","o":["Chỉ màu xanh lá","Đỏ và xanh lá","Trắng, vàng và xanh dương","Chỉ màu tím"],"h1":"Xe ủi tuyết có thể dùng một màu mà xe cảnh sát cũng dùng.","h2":"Ở Minnesota, xe ủi tuyết dùng đèn nhấp nháy màu trắng, vàng và xanh dương, vì vậy hãy để ý chúng khi đường có tuyết hoặc băng.","p":"Đúng. Trắng, vàng và xanh dương là xe ủi tuyết."},"tl":{"q":"Sa Minnesota, aling mga kumikislap na ilaw ang nagbababala sa iyo na may snowplow sa unahan?","o":["Berde lang","Pula at berde","Puti, dilaw at asul","Lila lang"],"h1":"Puwedeng gumamit ang snowplow ng kulay na ginagamit din ng mga police car.","h2":"Sa Minnesota, gumagamit ang mga snowplow ng kumikislap na puti, dilaw at asul na ilaw, kaya bantayan sila kapag may snow o yelo sa daan.","p":"Tama. Ang puti, dilaw at asul ay snowplow."},"ar":{"q":"في Minnesota، أي أضواء وامضة تحذّرك من أن كاسحة ثلج أمامك؟","o":["الأخضر فقط","الأحمر والأخضر","الأبيض والأصفر والأزرق","البنفسجي فقط"],"h1":"قد تستخدم كاسحات الثلج لونًا تستخدمه سيارات الشرطة أيضًا.","h2":"في Minnesota تستخدم كاسحات الثلج أضواء وامضة بيضاء وصفراء وزرقاء، لذا انتبه لها عندما يكون على الطرق ثلج أو جليد.","p":"صحيح. الأبيض والأصفر والأزرق تعني كاسحة ثلج."},"ref":{"doc":"MN","page":81}},{"id":"mn-040","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, you are using high beams at night. How close can an oncoming car get before you must switch to low beams?","o":["Within 500 feet","Within 1,000 feet","Within 200 feet","Within 2,000 feet"],"h1":"It is a long distance, more than three football fields.","h2":"In Minnesota you must use low beams when you are within 1,000 feet of an oncoming vehicle.","p":"Right. Dim your lights within 1,000 feet."},"es":{"q":"En Minnesota, usted usa las luces altas de noche. ¿Qué tan cerca puede estar un auto que viene de frente antes de que deba cambiar a luces bajas?","o":["A menos de 500 pies","A menos de 1,000 pies","A menos de 200 pies","A menos de 2,000 pies"],"h1":"Es una distancia larga, más de tres campos de fútbol americano.","h2":"En Minnesota debe usar las luces bajas cuando está a menos de 1,000 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a menos de 1,000 pies."},"zh":{"q":"在 Minnesota，你晚上开着远光灯。对面来的车靠近到多近时，你必须换成近光灯？","o":["500 英尺以内","1,000 英尺以内","200 英尺以内","2,000 英尺以内"],"h1":"这是很长的距离，比三个橄榄球场还长。","h2":"在 Minnesota，当你离对面来的车 1,000 英尺以内时，你必须用近光灯。","p":"对。在 1,000 英尺以内要调暗车灯。"},"vi":{"q":"Ở Minnesota, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Xe đi ngược chiều đến gần bao nhiêu thì bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["Trong vòng 500 feet","Trong vòng 1,000 feet","Trong vòng 200 feet","Trong vòng 2,000 feet"],"h1":"Đó là một khoảng cách dài, hơn ba sân bóng bầu dục.","h2":"Ở Minnesota, bạn phải dùng đèn cốt khi bạn ở trong vòng 1,000 feet cách xe đi ngược chiều.","p":"Đúng. Hạ đèn trong vòng 1,000 feet."},"tl":{"q":"Sa Minnesota, gumagamit ka ng high beam sa gabi. Gaano kalapit ang puwedeng makarating ng kasalubong na kotse bago ka dapat lumipat sa low beam?","o":["Sa loob ng 500 feet","Sa loob ng 1,000 feet","Sa loob ng 200 feet","Sa loob ng 2,000 feet"],"h1":"Malayo ito, higit sa tatlong football field.","h2":"Sa Minnesota, dapat kang gumamit ng low beam kapag nasa loob ka ng 1,000 feet mula sa kasalubong na sasakyan.","p":"Tama. Hinaan ang ilaw sa loob ng 1,000 feet."},"ar":{"q":"في Minnesota، تستخدم الأضواء العالية في الليل. إلى أي مسافة يمكن أن تقترب سيارة قادمة من الاتجاه المعاكس قبل أن يجب عليك التحويل إلى الأضواء المنخفضة؟","o":["ضمن 500 feet","ضمن 1,000 feet","ضمن 200 feet","ضمن 2,000 feet"],"h1":"إنها مسافة طويلة، أكثر من ثلاثة ملاعب كرة قدم أمريكية.","h2":"في Minnesota يجب أن تستخدم الأضواء المنخفضة عندما تكون ضمن 1,000 feet من مركبة قادمة من الاتجاه المعاكس.","p":"صحيح. خفّض أضواءك ضمن 1,000 feet."},"ref":{"doc":"MN","page":73}},{"id":"mn-041","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, you are following another car at night. How close can you get before you must use low beams?","o":["Within 50 feet","Within 500 feet","Within 1,000 feet","Within 200 feet"],"h1":"It is a shorter distance than the rule for oncoming cars.","h2":"In Minnesota you must use low beams when you follow another vehicle at 200 feet or less.","p":"Right. Use low beams within 200 feet."},"es":{"q":"En Minnesota, usted va detrás de otro auto de noche. ¿Qué tan cerca puede estar antes de que deba usar las luces bajas?","o":["A menos de 50 pies","A menos de 500 pies","A menos de 1,000 pies","A menos de 200 pies"],"h1":"Es una distancia más corta que la regla para autos que vienen de frente.","h2":"En Minnesota debe usar las luces bajas cuando sigue a otro vehículo a 200 pies o menos.","p":"Correcto. Use luces bajas a menos de 200 pies."},"zh":{"q":"在 Minnesota，你晚上跟在另一辆车后面。你靠近到多近时，必须用近光灯？","o":["50 英尺以内","500 英尺以内","1,000 英尺以内","200 英尺以内"],"h1":"这个距离比对面来车的规定短。","h2":"在 Minnesota，当你跟在另一辆车后面 200 英尺或更近时，你必须用近光灯。","p":"对。在 200 英尺以内用近光灯。"},"vi":{"q":"Ở Minnesota, bạn đang chạy theo sau một xe khác vào ban đêm. Bạn đến gần bao nhiêu thì phải dùng đèn cốt (đèn chiếu gần)?","o":["Trong vòng 50 feet","Trong vòng 500 feet","Trong vòng 1,000 feet","Trong vòng 200 feet"],"h1":"Khoảng cách này ngắn hơn quy định cho xe đi ngược chiều.","h2":"Ở Minnesota, bạn phải dùng đèn cốt khi bạn chạy theo sau một xe khác ở khoảng cách 200 feet hoặc gần hơn.","p":"Đúng. Dùng đèn cốt trong vòng 200 feet."},"tl":{"q":"Sa Minnesota, sumusunod ka sa ibang kotse sa gabi. Gaano ka kalapit puwedeng makarating bago ka dapat gumamit ng low beam?","o":["Sa loob ng 50 feet","Sa loob ng 500 feet","Sa loob ng 1,000 feet","Sa loob ng 200 feet"],"h1":"Mas maikli ang layong ito kaysa sa patakaran para sa kasalubong na kotse.","h2":"Sa Minnesota, dapat kang gumamit ng low beam kapag sumusunod ka sa ibang sasakyan sa layong 200 feet o mas malapit.","p":"Tama. Gumamit ng low beam sa loob ng 200 feet."},"ar":{"q":"في Minnesota، تسير خلف سيارة أخرى في الليل. إلى أي مسافة يمكن أن تقترب قبل أن يجب عليك استخدام الأضواء المنخفضة؟","o":["ضمن 50 feet","ضمن 500 feet","ضمن 1,000 feet","ضمن 200 feet"],"h1":"إنها مسافة أقصر من القاعدة الخاصة بالسيارات القادمة من الاتجاه المعاكس.","h2":"في Minnesota يجب أن تستخدم الأضواء المنخفضة عندما تسير خلف مركبة أخرى على بعد 200 feet أو أقل.","p":"صحيح. استخدم الأضواء المنخفضة ضمن 200 feet."},"ref":{"doc":"MN","page":73}},{"id":"mn-042","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, on a two-lane highway with a 55 mph speed limit, how much faster may you go while lawfully passing another vehicle?","o":["Up to 10 mph over the limit","Up to 20 mph over the limit","Up to 5 mph over the limit","Not even 1 mph over the limit"],"h1":"Minnesota gives a small extra margin to finish the pass quickly.","h2":"On a Minnesota two-lane highway with a speed limit of 55 mph or more, the limit goes up by 10 mph while you are lawfully passing.","p":"Right. Up to 10 mph more while passing."},"es":{"q":"En Minnesota, en una carretera de dos carriles con límite de 55 mph, ¿cuánto más rápido puede ir mientras rebasa legalmente a otro vehículo?","o":["Hasta 10 mph sobre el límite","Hasta 20 mph sobre el límite","Hasta 5 mph sobre el límite","Ni 1 mph sobre el límite"],"h1":"Minnesota da un pequeño margen extra para terminar de rebasar rápido.","h2":"En una carretera de dos carriles de Minnesota con límite de 55 mph o más, el límite sube 10 mph mientras usted rebasa legalmente.","p":"Correcto. Hasta 10 mph más mientras rebasa."},"zh":{"q":"在 Minnesota，在限速 55 英里/小时的双车道公路上，你合法超车时可以开快多少？","o":["最多超过限速 10 英里/小时","最多超过限速 20 英里/小时","最多超过限速 5 英里/小时","连 1 英里/小时都不能超"],"h1":"Minnesota 给一点额外的余地，让你快点完成超车。","h2":"在 Minnesota 限速 55 英里/小时或更高的双车道公路上，你合法超车时，限速提高 10 英里/小时。","p":"对。超车时最多快 10 英里/小时。"},"vi":{"q":"Ở Minnesota, trên xa lộ hai làn xe có giới hạn tốc độ 55 mph, bạn được chạy nhanh hơn bao nhiêu khi đang vượt xe khác một cách hợp pháp?","o":["Tối đa 10 mph trên giới hạn","Tối đa 20 mph trên giới hạn","Tối đa 5 mph trên giới hạn","Không được vượt dù chỉ 1 mph"],"h1":"Minnesota cho thêm một chút để bạn vượt xe xong nhanh chóng.","h2":"Trên xa lộ hai làn xe ở Minnesota có giới hạn tốc độ 55 mph trở lên, giới hạn tăng thêm 10 mph trong lúc bạn vượt xe hợp pháp.","p":"Đúng. Tối đa thêm 10 mph khi vượt xe."},"tl":{"q":"Sa Minnesota, sa two-lane highway na may speed limit na 55 mph, gaano ka kabilis puwedeng magpatakbo habang legal na umuunahan ng ibang sasakyan?","o":["Hanggang 10 mph lampas sa limit","Hanggang 20 mph lampas sa limit","Hanggang 5 mph lampas sa limit","Kahit 1 mph lampas sa limit ay hindi puwede"],"h1":"Nagbibigay ang Minnesota ng kaunting dagdag para matapos mo agad ang pag-uunahan.","h2":"Sa two-lane highway sa Minnesota na may speed limit na 55 mph o higit pa, tumataas nang 10 mph ang limit habang legal kang umuunahan.","p":"Tama. Hanggang 10 mph pa habang umuunahan."},"ar":{"q":"في Minnesota، على طريق سريع ذي حارتين حد السرعة فيه 55 mph، كم يمكنك أن تزيد سرعتك أثناء التجاوز القانوني لمركبة أخرى؟","o":["حتى 10 mph فوق الحد","حتى 20 mph فوق الحد","حتى 5 mph فوق الحد","ولا حتى 1 mph فوق الحد"],"h1":"تعطي Minnesota هامشًا إضافيًا صغيرًا لتنهي التجاوز بسرعة.","h2":"على طريق سريع ذي حارتين في Minnesota حد السرعة فيه 55 mph أو أكثر، يرتفع الحد 10 mph أثناء التجاوز القانوني.","p":"صحيح. حتى 10 mph إضافية أثناء التجاوز."},"ref":{"doc":"MN","page":34}},{"id":"mn-043","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what happens if you drive faster than 100 mph?","o":["You get a warning letter only","You pay a $50 fine only","Your license is revoked for at least six months","You get two points and no fine"],"h1":"This is one of the most serious speeding offenses.","h2":"In Minnesota, if you drive over 100 mph, your driving privileges are revoked for at least six months.","p":"Right. Over 100 mph means losing your license for at least six months."},"es":{"q":"En Minnesota, ¿qué pasa si maneja a más de 100 mph?","o":["Solo recibe una carta de advertencia","Solo paga una multa de $50","Le revocan la licencia por lo menos seis meses","Recibe dos puntos y ninguna multa"],"h1":"Es una de las faltas de velocidad más graves.","h2":"En Minnesota, si maneja a más de 100 mph, le revocan el privilegio de manejar por lo menos seis meses.","p":"Correcto. Más de 100 mph significa perder la licencia por lo menos seis meses."},"zh":{"q":"在 Minnesota，如果你开车超过 100 英里/小时，会怎么样？","o":["你只会收到一封警告信","你只付 $50 罚款","你的驾照被吊销至少六个月","你被记两分，没有罚款"],"h1":"这是最严重的超速违规之一。","h2":"在 Minnesota，如果你开车超过 100 英里/小时，你的驾驶资格会被吊销至少六个月。","p":"对。超过 100 英里/小时会让你失去驾照至少六个月。"},"vi":{"q":"Ở Minnesota, điều gì xảy ra nếu bạn lái nhanh hơn 100 mph?","o":["Bạn chỉ nhận một thư cảnh cáo","Bạn chỉ trả tiền phạt $50","Bằng lái của bạn bị thu hồi ít nhất sáu tháng","Bạn bị hai điểm và không bị phạt tiền"],"h1":"Đây là một trong những lỗi chạy quá tốc độ nghiêm trọng nhất.","h2":"Ở Minnesota, nếu bạn lái nhanh hơn 100 mph, quyền lái xe của bạn bị thu hồi ít nhất sáu tháng.","p":"Đúng. Trên 100 mph nghĩa là mất bằng lái ít nhất sáu tháng."},"tl":{"q":"Sa Minnesota, ano ang mangyayari kung magmaneho ka nang mas mabilis sa 100 mph?","o":["Warning letter lang ang makukuha mo","$50 na multa lang ang babayaran mo","Babawiin ang lisensya mo nang hindi bababa sa anim na buwan","Dalawang puntos at walang multa"],"h1":"Isa ito sa pinakamabibigat na paglabag sa bilis.","h2":"Sa Minnesota, kung magmaneho ka nang lampas sa 100 mph, babawiin ang driving privileges mo nang hindi bababa sa anim na buwan.","p":"Tama. Ang lampas sa 100 mph ay pagkawala ng lisensya mo nang hindi bababa sa anim na buwan."},"ar":{"q":"في Minnesota، ماذا يحدث إذا قدت بسرعة أكثر من 100 mph؟","o":["تحصل على رسالة تحذير فقط","تدفع غرامة $50 فقط","تُلغى رخصتك لمدة ستة أشهر على الأقل","تحصل على نقطتين بلا غرامة"],"h1":"هذه من أخطر مخالفات السرعة.","h2":"في Minnesota، إذا قدت بسرعة أكثر من 100 mph، تُلغى امتيازات القيادة لديك لمدة ستة أشهر على الأقل.","p":"صحيح. أكثر من 100 mph يعني فقدان رخصتك لستة أشهر على الأقل."},"ref":{"doc":"MN","page":27}},{"id":"mn-044","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, you speed in a work zone while workers are present. What extra fine do you face?","o":["$25","$50","$100","$300"],"h1":"It is a big fine, because workers are very close to traffic.","h2":"In Minnesota, speeding in a work zone when workers are present brings a $300 fine on top of the regular speeding ticket.","p":"Right. It costs an extra $300."},"es":{"q":"En Minnesota, usted va con exceso de velocidad en una zona de obras mientras hay trabajadores. ¿Qué multa extra puede recibir?","o":["$25","$50","$100","$300"],"h1":"Es una multa grande, porque los trabajadores están muy cerca del tráfico.","h2":"En Minnesota, ir con exceso de velocidad en una zona de obras cuando hay trabajadores trae una multa de $300 además de la multa normal por velocidad.","p":"Correcto. Cuesta $300 extra."},"zh":{"q":"在 Minnesota，你在有工人在场的施工区超速。你会被额外罚多少钱？","o":["$25","$50","$100","$300"],"h1":"罚款很高，因为工人离车流非常近。","h2":"在 Minnesota，有工人在场时在施工区超速，除了一般的超速罚单以外，还要额外罚 $300。","p":"对。要额外付 $300。"},"vi":{"q":"Ở Minnesota, bạn chạy quá tốc độ trong khu công trường khi có công nhân ở đó. Bạn bị phạt thêm bao nhiêu?","o":["$25","$50","$100","$300"],"h1":"Đó là một khoản phạt lớn, vì công nhân ở rất gần xe cộ.","h2":"Ở Minnesota, chạy quá tốc độ trong khu công trường khi có công nhân ở đó bị phạt thêm $300 ngoài vé phạt quá tốc độ thông thường.","p":"Đúng. Bạn bị phạt thêm $300."},"tl":{"q":"Sa Minnesota, nag-overspeed ka sa work zone habang may mga trabahador doon. Anong dagdag na multa ang haharapin mo?","o":["$25","$50","$100","$300"],"h1":"Malaking multa ito, dahil napakalapit ng mga trabahador sa trapiko.","h2":"Sa Minnesota, ang pag-overspeed sa work zone habang may mga trabahador ay may dagdag na $300 na multa bukod sa karaniwang speeding ticket.","p":"Tama. Dagdag na $300 ito."},"ar":{"q":"في Minnesota، تجاوزت السرعة في منطقة أعمال طرق بينما العمّال موجودون. ما الغرامة الإضافية التي تواجهها؟","o":["$25","$50","$100","$300"],"h1":"إنها غرامة كبيرة، لأن العمّال قريبون جدًا من حركة المرور.","h2":"في Minnesota، تجاوز السرعة في منطقة أعمال طرق بينما العمّال موجودون يجلب غرامة $300 إضافة إلى مخالفة السرعة العادية.","p":"صحيح. تكلّفك $300 إضافية."},"ref":{"doc":"MN","page":54}},{"id":"mn-045","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, what is the smallest fine for not stopping for a school bus with its red lights flashing?","o":["$100","$500","$50","$250"],"h1":"The fine is high because children's lives are at risk.","h2":"In Minnesota, if you are convicted of not stopping for a school bus with red lights flashing, the fine is at least $500 and you lose your driving privileges.","p":"Right. The fine is at least $500."},"es":{"q":"En Minnesota, ¿cuál es la multa mínima por no parar ante un autobús escolar con las luces rojas intermitentes?","o":["$100","$500","$50","$250"],"h1":"La multa es alta porque la vida de los niños está en riesgo.","h2":"En Minnesota, si lo declaran culpable de no parar ante un autobús escolar con luces rojas intermitentes, la multa es de por lo menos $500 y pierde el privilegio de manejar.","p":"Correcto. La multa es de por lo menos $500."},"zh":{"q":"在 Minnesota，没有为闪着红灯的校车停车，最低罚款是多少？","o":["$100","$500","$50","$250"],"h1":"罚款很高，因为孩子的生命有危险。","h2":"在 Minnesota，如果你因为没有为闪着红灯的校车停车而被定罪，罚款至少 $500，而且你会失去驾驶资格。","p":"对。罚款至少 $500。"},"vi":{"q":"Ở Minnesota, tiền phạt thấp nhất cho việc không dừng lại khi xe buýt trường học đang nhấp nháy đèn đỏ là bao nhiêu?","o":["$100","$500","$50","$250"],"h1":"Tiền phạt cao vì tính mạng của trẻ em đang gặp nguy hiểm.","h2":"Ở Minnesota, nếu bạn bị kết tội không dừng lại khi xe buýt trường học đang nhấp nháy đèn đỏ, tiền phạt ít nhất là $500 và bạn mất quyền lái xe.","p":"Đúng. Tiền phạt ít nhất là $500."},"tl":{"q":"Sa Minnesota, ano ang pinakamababang multa sa hindi paghinto para sa school bus na kumikislap ang pulang ilaw?","o":["$100","$500","$50","$250"],"h1":"Mataas ang multa dahil nanganganib ang buhay ng mga bata.","h2":"Sa Minnesota, kung mahatulan ka sa hindi paghinto para sa school bus na kumikislap ang pulang ilaw, hindi bababa sa $500 ang multa at mawawala ang driving privileges mo.","p":"Tama. Hindi bababa sa $500 ang multa."},"ar":{"q":"في Minnesota، ما أقل غرامة لعدم التوقف أمام حافلة مدرسية أضواؤها الحمراء تومض؟","o":["$100","$500","$50","$250"],"h1":"الغرامة عالية لأن حياة الأطفال في خطر.","h2":"في Minnesota، إذا أُدنت بعدم التوقف أمام حافلة مدرسية أضواؤها الحمراء تومض، تكون الغرامة $500 على الأقل وتفقد امتيازات القيادة.","p":"صحيح. الغرامة $500 على الأقل."},"ref":{"doc":"MN","page":42}},{"id":"mn-046","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, when may you pass a school bus on its right side?","o":["Never while its yellow or red lights are flashing","Any time its stop arm is folded in","Whenever only its yellow lights are flashing","When no children are in sight"],"h1":"Children may be getting on or off on that side.","h2":"In Minnesota it is against the law to pass a school bus on the right while it shows flashing yellow or red lights.","p":"Right. Never pass on the right while the lights flash."},"es":{"q":"En Minnesota, ¿cuándo puede rebasar a un autobús escolar por su lado derecho?","o":["Nunca mientras tenga las luces amarillas o rojas intermitentes","Siempre que el brazo de alto esté recogido","Cuando solo tenga las luces amarillas intermitentes","Cuando no se vean niños"],"h1":"Puede haber niños subiendo o bajando por ese lado.","h2":"En Minnesota es ilegal rebasar a un autobús escolar por la derecha mientras tiene luces amarillas o rojas intermitentes.","p":"Correcto. Nunca rebase por la derecha mientras las luces parpadean."},"zh":{"q":"在 Minnesota，你什么时候可以从校车的右边超过去？","o":["校车的黄灯或红灯在闪时，永远不可以","只要停车臂收起来，任何时候都可以","只有黄灯在闪的时候","看不到孩子的时候"],"h1":"孩子可能正在那一边上车或下车。","h2":"在 Minnesota，校车闪着黄灯或红灯时，从它的右边超车是违法的。","p":"对。灯在闪时，永远不要从右边超车。"},"vi":{"q":"Ở Minnesota, khi nào bạn được vượt xe buýt trường học ở bên phải của nó?","o":["Không bao giờ khi đèn vàng hoặc đèn đỏ của xe đang nhấp nháy","Bất cứ lúc nào cần báo dừng đã thu vào","Bất cứ khi nào chỉ có đèn vàng nhấp nháy","Khi không thấy trẻ em nào"],"h1":"Trẻ em có thể đang lên hoặc xuống xe ở bên đó.","h2":"Ở Minnesota, vượt xe buýt trường học ở bên phải khi xe đang nhấp nháy đèn vàng hoặc đèn đỏ là phạm luật.","p":"Đúng. Không bao giờ vượt bên phải khi đèn đang nhấp nháy."},"tl":{"q":"Sa Minnesota, kailan ka puwedeng umunahan sa school bus sa kanang bahagi nito?","o":["Hindi kailanman habang kumikislap ang dilaw o pulang ilaw nito","Kahit kailan basta nakatiklop ang stop arm","Kapag dilaw na ilaw lang ang kumikislap","Kapag walang batang nakikita"],"h1":"Puwedeng may mga batang sumasakay o bumababa sa bahaging iyon.","h2":"Sa Minnesota, labag sa batas ang umunahan sa school bus sa kanan habang kumikislap ang dilaw o pulang ilaw nito.","p":"Tama. Huwag kailanman umunahan sa kanan habang kumikislap ang ilaw."},"ar":{"q":"في Minnesota، متى يجوز لك أن تتجاوز حافلة مدرسية من جهتها اليمنى؟","o":["أبدًا ما دامت أضواؤها الصفراء أو الحمراء تومض","في أي وقت تكون فيه ذراع التوقف مطوية","كلما كانت أضواؤها الصفراء فقط تومض","عندما لا ترى أي أطفال"],"h1":"قد يكون الأطفال يصعدون أو ينزلون من تلك الجهة.","h2":"في Minnesota، تجاوز الحافلة المدرسية من اليمين بينما أضواؤها الصفراء أو الحمراء تومض مخالف للقانون.","p":"صحيح. يجب ألّا تتجاوز من اليمين أبدًا ما دامت الأضواء تومض."},"ref":{"doc":"MN","page":41}},{"id":"mn-047","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, a fire truck is on an emergency run. How far behind it must you stay?","o":["At least 50 feet","At least 100 feet","At least 500 feet","At least 1 mile"],"h1":"It is more than the length of a city block.","h2":"In Minnesota, only vehicles on official emergency business may follow within 500 feet of a firefighting vehicle on an emergency run.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Minnesota, un camión de bomberos va a una emergencia. ¿A qué distancia detrás de él debe mantenerse?","o":["Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 500 pies","Por lo menos 1 milla"],"h1":"Es más que el largo de una cuadra de la ciudad.","h2":"En Minnesota, solo los vehículos en servicio oficial de emergencia pueden seguir a menos de 500 pies a un vehículo de bomberos que va a una emergencia.","p":"Correcto. Manténgase por lo menos a 500 pies."},"zh":{"q":"在 Minnesota，一辆消防车正在执行紧急任务。你必须在它后面保持多远？","o":["至少 50 英尺","至少 100 英尺","至少 500 英尺","至少 1 英里"],"h1":"比一个城市街区还长。","h2":"在 Minnesota，只有执行正式紧急任务的车辆，才可以在执行紧急任务的消防车后面 500 英尺以内跟车。","p":"对。保持至少 500 英尺的距离。"},"vi":{"q":"Ở Minnesota, một xe cứu hỏa đang chạy đi cấp cứu. Bạn phải giữ khoảng cách phía sau nó bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 500 feet","Ít nhất 1 dặm"],"h1":"Nó dài hơn một dãy phố trong thành phố.","h2":"Ở Minnesota, chỉ những xe đang làm nhiệm vụ khẩn cấp chính thức mới được chạy theo trong vòng 500 feet sau xe cứu hỏa đang đi cấp cứu.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet."},"tl":{"q":"Sa Minnesota, may fire truck na nasa emergency run. Gaano kalayo ka dapat manatili sa likod nito?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 500 feet","Hindi bababa sa 1 milya"],"h1":"Mas mahaba ito kaysa sa isang city block.","h2":"Sa Minnesota, mga sasakyang nasa opisyal na emergency na gawain lang ang puwedeng sumunod sa loob ng 500 feet sa likod ng sasakyang pambumbero na nasa emergency run.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod."},"ar":{"q":"في Minnesota، سيارة إطفاء في مهمة طوارئ. على أي مسافة خلفها يجب أن تبقى؟","o":["50 feet على الأقل","100 feet على الأقل","500 feet على الأقل","ميل واحد على الأقل"],"h1":"إنها أطول من مربع سكني في المدينة.","h2":"في Minnesota، المركبات التي في مهمة طوارئ رسمية فقط يجوز لها أن تسير ضمن 500 feet خلف مركبة إطفاء في مهمة طوارئ.","p":"صحيح. ابقَ على بعد 500 feet على الأقل."},"ref":{"doc":"MN","page":44}},{"id":"mn-048","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, how close to a stop sign may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Other drivers need to see the sign from far away.","h2":"In Minnesota you may not park within 30 feet of a stop sign, flashing light or traffic signal on the side of the road.","p":"Right. Park at least 30 feet away."},"es":{"q":"En Minnesota, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los otros conductores necesitan ver la señal desde lejos.","h2":"En Minnesota no puede estacionarse a menos de 30 pies de una señal de alto, una luz intermitente o un semáforo al lado de la calle.","p":"Correcto. Estaciónese por lo menos a 30 pies."},"zh":{"q":"在 Minnesota，你可以在离停车标志多近的地方停车？","o":["不得近于 5 英尺","不得近于 10 英尺","不得近于 15 英尺","不得近于 30 英尺"],"h1":"其他司机需要从很远就看到这个标志。","h2":"在 Minnesota，你不可以在路边离停车标志、闪光灯或交通信号灯 30 英尺以内停车。","p":"对。停在至少 30 英尺以外。"},"vi":{"q":"Ở Minnesota, bạn được đậu xe gần biển báo dừng (stop sign) đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Những người lái xe khác cần thấy biển báo từ xa.","h2":"Ở Minnesota, bạn không được đậu xe trong vòng 30 feet cách biển báo dừng, đèn nhấp nháy hoặc đèn giao thông ở bên đường.","p":"Đúng. Đậu xe cách ít nhất 30 feet."},"tl":{"q":"Sa Minnesota, gaano kalapit sa stop sign ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangang makita ng ibang driver ang sign mula sa malayo.","h2":"Sa Minnesota, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, kumikislap na ilaw o traffic signal sa gilid ng daan.","p":"Tama. Pumarada nang hindi bababa sa 30 feet ang layo."},"ar":{"q":"في Minnesota، إلى أي مسافة من إشارة التوقف (stop sign) يجوز لك أن تركن؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"يحتاج السائقون الآخرون إلى رؤية الإشارة من بعيد.","h2":"في Minnesota لا يجوز لك أن تركن على بعد أقل من 30 feet من إشارة توقف أو ضوء وامض أو إشارة مرور على جانب الطريق.","p":"صحيح. اركن على بعد 30 feet على الأقل."},"ref":{"doc":"MN","page":35}},{"id":"mn-049","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, the lights are flashing at a railroad crossing. How far from the nearest rail or gate must you stop?","o":["At least 10 feet","At least 2 feet","At least 100 feet","At least 300 feet"],"h1":"It is a short distance, a little less than one car length.","h2":"In Minnesota, when the lights or gates at a railroad crossing are working, you must stop at least 10 feet from the nearest rail or gate.","p":"Right. Stop at least 10 feet away."},"es":{"q":"En Minnesota, las luces de un cruce de tren están parpadeando. ¿A qué distancia del riel o de la barrera más cercana debe parar?","o":["Por lo menos 10 pies","Por lo menos 2 pies","Por lo menos 100 pies","Por lo menos 300 pies"],"h1":"Es una distancia corta, un poco menos que el largo de un auto.","h2":"En Minnesota, cuando las luces o las barreras de un cruce de tren están funcionando, debe parar por lo menos a 10 pies del riel o de la barrera más cercana.","p":"Correcto. Pare por lo menos a 10 pies."},"zh":{"q":"在 Minnesota，铁路道口的灯在闪。你必须停在离最近的铁轨或栏杆多远的地方？","o":["至少 10 英尺","至少 2 英尺","至少 100 英尺","至少 300 英尺"],"h1":"这是一段很短的距离，比一辆车的长度短一点。","h2":"在 Minnesota，当铁路道口的灯或栏杆在工作时，你必须停在离最近的铁轨或栏杆至少 10 英尺的地方。","p":"对。至少停在 10 英尺以外。"},"vi":{"q":"Ở Minnesota, đèn đang nhấp nháy ở chỗ giao nhau với đường sắt. Bạn phải dừng cách đường ray hoặc thanh chắn gần nhất bao xa?","o":["Ít nhất 10 feet","Ít nhất 2 feet","Ít nhất 100 feet","Ít nhất 300 feet"],"h1":"Đó là một khoảng ngắn, ngắn hơn một chiếc xe một chút.","h2":"Ở Minnesota, khi đèn hoặc thanh chắn ở chỗ giao nhau với đường sắt đang hoạt động, bạn phải dừng cách đường ray hoặc thanh chắn gần nhất ít nhất 10 feet.","p":"Đúng. Dừng cách xa ít nhất 10 feet."},"tl":{"q":"Sa Minnesota, kumikislap ang mga ilaw sa tawiran ng tren (railroad crossing). Gaano kalayo mula sa pinakamalapit na riles o harang ka dapat huminto?","o":["Hindi bababa sa 10 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 300 talampakan"],"h1":"Maikling layo ito, medyo mas maikli sa haba ng isang kotse.","h2":"Sa Minnesota, kapag gumagana ang mga ilaw o harang sa tawiran ng tren, dapat kang huminto nang hindi bababa sa 10 talampakan mula sa pinakamalapit na riles o harang.","p":"Tama. Huminto nang hindi bababa sa 10 talampakan ang layo."},"ar":{"q":"في Minnesota، الأضواء تومض عند معبر سكة الحديد. على أي مسافة من أقرب سكة أو حاجز يجب أن تتوقف؟","o":["10 أقدام على الأقل","2 قدم على الأقل","100 قدم على الأقل","300 قدم على الأقل"],"h1":"إنها مسافة قصيرة، أقل قليلًا من طول سيارة واحدة.","h2":"في Minnesota، عندما تعمل الأضواء أو الحواجز عند معبر سكة الحديد، يجب أن تتوقف على بُعد 10 أقدام على الأقل من أقرب سكة أو حاجز.","p":"صحيح. توقّف على بُعد 10 أقدام على الأقل."},"ref":{"doc":"MN","page":53}},{"id":"mn-050","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, a driver under 21 is convicted for the first time of driving with any alcohol in their body. How long is the license suspended?","o":["7 days","1 year","30 days","180 days"],"h1":"It is about one month. A second conviction brings a much longer suspension.","h2":"In Minnesota, a first conviction for a driver under 21 who drives with any alcohol means a 30-day suspension, and a second means 180 days.","p":"Right. The first time, it is 30 days."},"es":{"q":"En Minnesota, un conductor menor de 21 es declarado culpable por primera vez de manejar con cualquier cantidad de alcohol en el cuerpo. ¿Por cuánto tiempo le suspenden la licencia?","o":["7 días","1 año","30 días","180 días"],"h1":"Es como un mes. Una segunda condena trae una suspensión mucho más larga.","h2":"En Minnesota, la primera condena de un conductor menor de 21 que maneja con cualquier cantidad de alcohol significa 30 días de suspensión, y la segunda, 180 días.","p":"Correcto. La primera vez son 30 días."},"zh":{"q":"在 Minnesota，一名 21 岁以下的司机第一次因为体内有任何酒精还开车而被定罪。驾照会被暂停多久？","o":["7 天","1 年","30 天","180 天"],"h1":"大约一个月。第二次定罪会暂停更久。","h2":"在 Minnesota，21 岁以下的司机体内有任何酒精还开车，第一次定罪暂停驾照 30 天，第二次暂停 180 天。","p":"对。第一次是 30 天。"},"vi":{"q":"Ở Minnesota, một người lái xe dưới 21 tuổi bị kết tội lần đầu vì lái xe khi trong người có bất kỳ chút rượu bia nào. Bằng lái bị đình chỉ bao lâu?","o":["7 ngày","1 năm","30 ngày","180 ngày"],"h1":"Khoảng một tháng. Lần bị kết tội thứ hai sẽ bị đình chỉ lâu hơn nhiều.","h2":"Ở Minnesota, người lái xe dưới 21 tuổi lái xe khi có bất kỳ chút rượu bia nào trong người bị đình chỉ bằng lái 30 ngày ở lần kết tội đầu tiên, và 180 ngày ở lần thứ hai.","p":"Đúng. Lần đầu là 30 ngày."},"tl":{"q":"Sa Minnesota, isang driver na wala pang 21 ang nahatulan sa unang pagkakataon dahil nagmaneho nang may kahit anong alak sa katawan. Gaano katagal masususpinde ang lisensya?","o":["7 araw","1 taon","30 araw","180 araw"],"h1":"Mga isang buwan ito. Mas matagal na suspension ang dala ng pangalawang paghatol.","h2":"Sa Minnesota, kapag nahatulan sa unang pagkakataon ang driver na wala pang 21 na nagmaneho nang may kahit anong alak, 30 araw ang suspension, at 180 araw sa pangalawa.","p":"Tama. Sa unang pagkakataon, 30 araw ito."},"ar":{"q":"في Minnesota، أُدين سائق عمره أقل من 21 سنة لأول مرة بالقيادة مع وجود أي كمية من الكحول في جسمه. كم مدة تعليق الرخصة؟","o":["7 أيام","سنة واحدة","30 يومًا","180 يومًا"],"h1":"إنها حوالي شهر واحد. الإدانة الثانية تجلب تعليقًا أطول بكثير.","h2":"في Minnesota، الإدانة الأولى لسائق عمره أقل من 21 سنة يقود مع أي كمية من الكحول تعني تعليق الرخصة 30 يومًا، والإدانة الثانية تعني 180 يومًا.","p":"صحيح. في المرة الأولى تكون 30 يومًا."},"ref":{"doc":"MN","page":95}},{"id":"mn-051","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, an officer has good reason to believe you are driving impaired and asks for a blood, breath or urine test. What happens if you refuse?","o":["Nothing, because the test is optional","It is a crime, and your license is revoked","You only get a warning the first time","You pay a small fine and keep your license"],"h1":"Minnesota's implied consent law treats refusing very seriously.","h2":"In Minnesota, refusing a lawful blood, breath or urine test is a crime and leads to a license revocation of one to six years.","p":"Right. Refusing is a crime and costs you your license."},"es":{"q":"En Minnesota, un oficial tiene buenas razones para creer que usted maneja bajo los efectos del alcohol o drogas y le pide una prueba de sangre, aliento u orina. ¿Qué pasa si se niega?","o":["Nada, porque la prueba es opcional","Es un delito y le revocan la licencia","Solo recibe una advertencia la primera vez","Paga una multa pequeña y conserva su licencia"],"h1":"La ley de consentimiento implícito de Minnesota trata la negativa con mucha seriedad.","h2":"En Minnesota, negarse a una prueba legal de sangre, aliento u orina es un delito y lleva a una revocación de la licencia de uno a seis años.","p":"Correcto. Negarse es un delito y le cuesta la licencia."},"zh":{"q":"在 Minnesota，警察有充分理由认为你在受影响的状态下开车，要你做血液、呼气或尿液检测。如果你拒绝，会怎么样？","o":["没事，因为检测是自愿的","这是犯罪，你的驾照会被吊销","第一次只会得到警告","你付一点小罚款，并保留驾照"],"h1":"Minnesota 的默示同意法（implied consent law）对拒绝检测处理得很严厉。","h2":"在 Minnesota，拒绝合法的血液、呼气或尿液检测是犯罪，会导致驾照被吊销一到六年。","p":"对。拒绝是犯罪，会让你失去驾照。"},"vi":{"q":"Ở Minnesota, cảnh sát có lý do chính đáng để tin rằng bạn đang lái xe khi bị ảnh hưởng (say xỉn) và yêu cầu bạn xét nghiệm máu, hơi thở hoặc nước tiểu. Điều gì xảy ra nếu bạn từ chối?","o":["Không có gì, vì xét nghiệm là tùy chọn","Đó là tội phạm, và bằng lái của bạn bị thu hồi","Lần đầu bạn chỉ bị cảnh cáo","Bạn trả một khoản phạt nhỏ và giữ bằng lái"],"h1":"Luật đồng ý ngầm (implied consent law) của Minnesota xử lý việc từ chối rất nghiêm khắc.","h2":"Ở Minnesota, từ chối xét nghiệm máu, hơi thở hoặc nước tiểu hợp pháp là tội phạm và dẫn đến việc bằng lái bị thu hồi từ một đến sáu năm.","p":"Đúng. Từ chối là tội phạm và làm bạn mất bằng lái."},"tl":{"q":"Sa Minnesota, may magandang dahilan ang pulis para maniwalang nagmamaneho ka nang impaired (may impluwensya ng alak o droga) at humihingi siya ng blood, breath o urine test. Ano ang mangyayari kung tumanggi ka?","o":["Wala, dahil opsyonal ang test","Krimen ito, at babawiin ang lisensya mo","Warning lang ang makukuha mo sa unang beses","Magbabayad ka ng maliit na multa at mananatili sa iyo ang lisensya"],"h1":"Napakabigat ng tingin ng implied consent law ng Minnesota sa pagtanggi.","h2":"Sa Minnesota, krimen ang pagtanggi sa legal na blood, breath o urine test at nauuwi ito sa pagbawi ng lisensya nang isa hanggang anim na taon.","p":"Tama. Krimen ang pagtanggi at mawawala ang lisensya mo."},"ar":{"q":"في Minnesota، لدى الشرطي سبب قوي ليعتقد أنك تقود وأنت تحت التأثير، ويطلب منك فحص دم أو نفَس أو بول. ماذا يحدث إذا رفضت؟","o":["لا شيء، لأن الفحص اختياري","هذه جريمة، وتُلغى رخصتك","تحصل على تحذير فقط في المرة الأولى","تدفع غرامة صغيرة وتحتفظ برخصتك"],"h1":"قانون الموافقة الضمنية (implied consent law) في Minnesota يتعامل مع الرفض بجدية شديدة.","h2":"في Minnesota، رفض فحص الدم أو النفَس أو البول القانوني جريمة، ويؤدي إلى إلغاء الرخصة لمدة من سنة إلى ست سنوات.","p":"صحيح. الرفض جريمة ويكلّفك رخصتك."},"ref":{"doc":"MN","page":93}},{"id":"mn-052","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, your Minnesota driver's license expired three years ago. What must you pass before you get a new one?","o":["Only a road test","Nothing, you just pay the fee","A written test and a vision test","A driver education course"],"h1":"It has been more than one year but less than five.","h2":"In Minnesota, if your license has been expired for more than one year but less than five years, you must pass a written test and a vision test.","p":"Right. After that gap you take the written and vision tests."},"es":{"q":"En Minnesota, su licencia de Minnesota venció hace tres años. ¿Qué debe aprobar antes de obtener una nueva?","o":["Solo un examen de manejo","Nada, solo paga la tarifa","Un examen escrito y un examen de la vista","Un curso de educación vial"],"h1":"Han pasado más de un año pero menos de cinco.","h2":"En Minnesota, si su licencia lleva vencida más de un año pero menos de cinco, debe aprobar un examen escrito y un examen de la vista.","p":"Correcto. Después de ese tiempo hace el examen escrito y el de la vista."},"ref":{"doc":"MN","page":6}},{"id":"mn-053","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, you are 30 and move from another state with a valid, unexpired license. What do you usually need to get a Minnesota license?","o":["A vision test and an application","A written test and a road test","A road test only","A full driver education course"],"h1":"You already show you can drive with a valid license.","h2":"In Minnesota, a new resident age 21 or older with a valid, unexpired license from another state usually needs only a vision test and an application.","p":"Correct. A vision test and an application are enough."},"es":{"q":"En Minnesota, usted tiene 30 años y se muda de otro estado con una licencia válida y vigente. ¿Qué necesita normalmente para obtener una licencia de Minnesota?","o":["Un examen de la vista y una solicitud","Un examen escrito y uno de manejo","Solo un examen de manejo","Un curso completo de educación vial"],"h1":"Su licencia válida ya muestra que sabe manejar.","h2":"En Minnesota, un nuevo residente de 21 años o más con una licencia válida y vigente de otro estado normalmente solo necesita un examen de la vista y una solicitud.","p":"Correcto. Basta con el examen de la vista y la solicitud."},"ref":{"doc":"MN","page":6}},{"id":"mn-054","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you move here with a license from another state that expired more than a year ago. Which tests must you pass?","o":["Only a vision test","Only the written test","Only the road test","The written test and the road test"],"h1":"The longer the license has been expired, the more you must prove.","h2":"In Minnesota, if your former state license expired more than one year ago, you must pass both the written test and the road test.","p":"Right. Both the written and road tests are needed."},"es":{"q":"En Minnesota, usted se muda aquí con una licencia de otro estado que venció hace más de un año. ¿Qué exámenes debe aprobar?","o":["Solo un examen de la vista","Solo el examen escrito","Solo el examen de manejo","El examen escrito y el de manejo"],"h1":"Mientras más tiempo lleve vencida la licencia, más debe demostrar.","h2":"En Minnesota, si su licencia del otro estado venció hace más de un año, debe aprobar el examen escrito y el examen de manejo.","p":"Correcto. Necesita el examen escrito y el de manejo."},"ref":{"doc":"MN","page":6}},{"id":"mn-055","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, you are a new resident with a valid commercial driver's license from another state. How long do you have to get a Minnesota CDL?","o":["10 days","30 days","60 days","90 days"],"h1":"It is half the time a car driver gets.","h2":"In Minnesota, a new resident with a valid commercial driver's license has 30 days to get a Minnesota commercial license.","p":"Correct. Commercial drivers have 30 days."},"es":{"q":"En Minnesota, usted es un nuevo residente con una licencia comercial válida de otro estado. ¿Cuánto tiempo tiene para obtener una licencia comercial de Minnesota?","o":["10 días","30 días","60 días","90 días"],"h1":"Es la mitad del tiempo que tiene un conductor de auto.","h2":"En Minnesota, un nuevo residente con una licencia comercial válida tiene 30 días para obtener la licencia comercial de Minnesota.","p":"Correcto. Los conductores comerciales tienen 30 días."},"ref":{"doc":"MN","page":6}},{"id":"mn-056","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you move here from a country other than the U.S. or Canada and have a valid license from that country. What must you do?","o":["Only trade in your license","Only take a vision test","Pass a written, a vision and a road test","Drive for one year, then apply"],"h1":"A license from most other countries is not traded in directly.","h2":"In Minnesota, a new resident from a country other than the U.S. or Canada must pass a written test, a vision test and a road test, even with a valid license.","p":"Right. All three tests are required."},"es":{"q":"En Minnesota, usted se muda aquí desde un país que no es EE. UU. ni Canadá y tiene una licencia válida de ese país. ¿Qué debe hacer?","o":["Solo cambiar su licencia","Solo hacer un examen de la vista","Aprobar un examen escrito, uno de la vista y uno de manejo","Manejar un año y luego solicitar"],"h1":"La licencia de la mayoría de los otros países no se cambia directamente.","h2":"En Minnesota, un nuevo residente de un país que no es EE. UU. ni Canadá debe aprobar un examen escrito, uno de la vista y uno de manejo, aunque tenga una licencia válida.","p":"Correcto. Se requieren los tres exámenes."},"ref":{"doc":"MN","page":6}},{"id":"mn-057","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what must you do with your licenses and ID cards from other places before you get a Minnesota license?","o":["Keep them as a backup","Mail them back to the other state yourself","Cut them in half at home","Hand them all in to DVS"],"h1":"You may hold only one license.","h2":"In Minnesota, you cannot get your license until you hand in all your other driver's licenses and identification cards to DVS.","p":"Correct. You turn them all in to DVS."},"es":{"q":"En Minnesota, ¿qué debe hacer con sus licencias y tarjetas de identificación de otros lugares antes de obtener una licencia de Minnesota?","o":["Guardarlas como respaldo","Enviarlas usted mismo al otro estado","Cortarlas por la mitad en casa","Entregarlas todas a DVS"],"h1":"Solo puede tener una licencia.","h2":"En Minnesota, no puede obtener su licencia hasta que entregue a DVS todas sus otras licencias de conducir y tarjetas de identificación.","p":"Correcto. Las entrega todas a DVS."},"ref":{"doc":"MN","page":6}},{"id":"mn-058","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, a visitor who is not a resident has a valid license from their home state. What is the youngest age at which they may drive here?","o":["15","16","17","18"],"h1":"It is the same age as the Minnesota permit.","h2":"In Minnesota, a nonresident at least 15 years old with a valid license from home may drive without a Minnesota license.","p":"Right. A nonresident with a valid home license may drive here from age 15."},"es":{"q":"En Minnesota, un visitante que no es residente tiene una licencia válida de su estado. ¿Cuál es la edad mínima para manejar aquí?","o":["15","16","17","18"],"h1":"Es la misma edad del permiso de Minnesota.","h2":"En Minnesota, un no residente de al menos 15 años con una licencia válida de su lugar de origen puede manejar sin licencia de Minnesota.","p":"Correcto. Un no residente con licencia válida puede manejar aquí desde los 15 años."},"ref":{"doc":"MN","page":6}},{"id":"mn-059","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, an adult visitor comes from a country that does not license drivers, in a car registered there. How long may they drive here each calendar year?","o":["30 days","90 days","6 months","One full year"],"h1":"It is about three months.","h2":"In Minnesota, a nonresident 18 or older from a country that does not require driver's licenses may drive their home-registered car here for up to 90 days a calendar year.","p":"Correct. The limit is 90 days a year."},"es":{"q":"En Minnesota, un visitante adulto viene de un país que no exige licencia de conducir, en un auto registrado allá. ¿Cuánto tiempo puede manejar aquí cada año calendario?","o":["30 días","90 días","6 meses","Un año completo"],"h1":"Son unos tres meses.","h2":"En Minnesota, un no residente de 18 años o más de un país que no exige licencia puede manejar su auto registrado allá hasta 90 días por año calendario.","p":"Correcto. El límite es de 90 días al año."},"ref":{"doc":"MN","page":6}},{"id":"mn-060","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, which identity document will DVS refuse to accept?","o":["An original birth certificate","A valid passport","A photocopy of your birth certificate","A certified marriage certificate"],"h1":"DVS needs the real document.","h2":"In Minnesota, DVS does not accept photocopies of identification documents, and it may refuse documents that are laminated or altered.","p":"Right. Photocopies are not accepted."},"es":{"q":"En Minnesota, ¿qué documento de identidad rechazará DVS?","o":["Un acta de nacimiento original","Un pasaporte vigente","Una fotocopia del acta de nacimiento","Un acta de matrimonio certificada"],"h1":"DVS necesita el documento real.","h2":"En Minnesota, DVS no acepta fotocopias de documentos de identidad y puede rechazar documentos enmicados o alterados.","p":"Correcto. No se aceptan fotocopias."},"ref":{"doc":"MN","page":7}},{"id":"mn-061","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, since October 1, 2023, the Driver's License for All law lets you get a standard license without showing what?","o":["Proof of legal presence in the U.S.","Your date of birth","Your name","A passing vision test"],"h1":"The law is about immigration status.","h2":"In Minnesota, since October 1, 2023, you can get a standard license, permit or state ID without proof of legal presence in the U.S.","p":"Correct. Immigration status no longer matters for a standard card."},"es":{"q":"En Minnesota, desde el 1 de octubre de 2023, la ley Driver's License for All le permite obtener una licencia estándar sin mostrar qué?","o":["Prueba de presencia legal en EE. UU.","Su fecha de nacimiento","Su nombre","Un examen de la vista aprobado"],"h1":"La ley trata sobre el estatus migratorio.","h2":"En Minnesota, desde el 1 de octubre de 2023, puede obtener una licencia, permiso o identificación estándar sin prueba de presencia legal en EE. UU.","p":"Correcto. El estatus migratorio ya no importa para la tarjeta estándar."},"ref":{"doc":"MN","page":8}},{"id":"mn-062","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how many documents proving where you live in Minnesota must you bring for a REAL ID?","o":["None","One","Three","Two"],"h1":"It is more than one.","h2":"In Minnesota, a REAL ID application needs two documents that prove your current Minnesota residency.","p":"Right. Two proofs of residency are needed."},"es":{"q":"En Minnesota, ¿cuántos documentos que prueben dónde vive en Minnesota debe llevar para una REAL ID?","o":["Ninguno","Uno","Tres","Dos"],"h1":"Es más de uno.","h2":"En Minnesota, la solicitud de REAL ID necesita dos documentos que prueben su residencia actual en Minnesota.","p":"Correcto. Se necesitan dos pruebas de residencia."},"ref":{"doc":"MN","page":8}},{"id":"mn-063","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, who may get an enhanced driver's license?","o":["Any resident age 16 or older","Only U.S. citizens who live in Minnesota","Only commercial drivers","Only people born in Minnesota"],"h1":"The enhanced card can be used at some borders.","h2":"In Minnesota, only applicants who prove U.S. citizenship and Minnesota residency, along with the other documents, can get an enhanced driver's license or ID.","p":"Correct. It is only for U.S. citizens who live in Minnesota."},"es":{"q":"En Minnesota, ¿quién puede obtener una licencia de conducir mejorada (enhanced)?","o":["Cualquier residente de 16 años o más","Solo ciudadanos de EE. UU. que viven en Minnesota","Solo conductores comerciales","Solo personas nacidas en Minnesota"],"h1":"La tarjeta mejorada se puede usar en algunas fronteras.","h2":"En Minnesota, solo quienes prueban ciudadanía de EE. UU. y residencia en Minnesota, junto con los otros documentos, pueden obtener la licencia o identificación mejorada.","p":"Correcto. Es solo para ciudadanos de EE. UU. que viven en Minnesota."},"ref":{"doc":"MN","page":8}},{"id":"mn-064","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how much extra does an enhanced driver's license cost, on top of the regular license fee?","o":["$5","$10","$15","$25"],"h1":"It is between $10 and $20.","h2":"In Minnesota, an enhanced driver's license or ID costs an extra $15 on top of the regular fee.","p":"Right. The extra fee is $15."},"es":{"q":"En Minnesota, ¿cuánto cuesta de más una licencia mejorada, además de la tarifa normal?","o":["$5","$10","$15","$25"],"h1":"Está entre $10 y $20.","h2":"En Minnesota, la licencia o identificación mejorada cuesta $15 más que la tarifa normal.","p":"Correcto. El cargo adicional es de $15."},"ref":{"doc":"MN","page":8}},{"id":"mn-065","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, your birth certificate is not in English. Who may NOT translate it for DVS?","o":["A professional translator","A teacher who knows both languages","A translator from a language school","Your aunt, even if she speaks both languages"],"h1":"The translator must be neutral.","h2":"In Minnesota, the person who translates your documents must not be related to you by blood or marriage.","p":"Correct. A relative cannot be your translator."},"es":{"q":"En Minnesota, su acta de nacimiento no está en inglés. ¿Quién NO puede traducirla para DVS?","o":["Un traductor profesional","Un maestro que sabe ambos idiomas","Un traductor de una escuela de idiomas","Su tía, aunque hable ambos idiomas"],"h1":"El traductor debe ser imparcial.","h2":"En Minnesota, la persona que traduce sus documentos no puede ser pariente suyo por sangre ni por matrimonio.","p":"Correcto. Un pariente no puede ser su traductor."},"ref":{"doc":"MN","page":9}},{"id":"mn-066","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, is your Social Security number printed on your driver's license?","o":["No, it is not printed or stored on the card","Yes, on the front","Yes, on the back","Only on a REAL ID"],"h1":"The number is kept private.","h2":"In Minnesota, Social Security numbers are not printed on or embedded in driver's licenses or ID cards.","p":"Right. It is never on the card."},"es":{"q":"En Minnesota, ¿aparece su número de Seguro Social en su licencia de conducir?","o":["No, no se imprime ni se guarda en la tarjeta","Sí, en el frente","Sí, en el reverso","Solo en la REAL ID"],"h1":"El número se mantiene privado.","h2":"En Minnesota, el número de Seguro Social no se imprime ni se incluye en la licencia ni en la tarjeta de identificación.","p":"Correcto. Nunca aparece en la tarjeta."},"ref":{"doc":"MN","page":9}},{"id":"mn-067","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, you failed the written test this morning. When may you take it again?","o":["Later the same day","On another day","After 30 days","After one week of classes"],"h1":"There is a daily limit.","h2":"In Minnesota, you may take only one written test per day, so you must come back another day.","p":"Correct. One written test per day."},"es":{"q":"En Minnesota, usted reprobó el examen escrito esta mañana. ¿Cuándo puede volver a presentarlo?","o":["Más tarde el mismo día","Otro día","Después de 30 días","Después de una semana de clases"],"h1":"Hay un límite por día.","h2":"En Minnesota, solo puede presentar un examen escrito por día, así que debe volver otro día.","p":"Correcto. Un examen escrito por día."},"ref":{"doc":"MN","page":10}},{"id":"mn-068","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you failed the written test two times in a row. What happens when you take it a third time?","o":["You must wait six months","You must take driver education again","Nothing changes","You pay a $10 fee"],"h1":"It costs a little money.","h2":"In Minnesota, after two failed written tests in a row, you pay a $10 fee for the third test and each one after it.","p":"Right. The third and later tests cost $10."},"es":{"q":"En Minnesota, reprobó el examen escrito dos veces seguidas. ¿Qué pasa cuando lo presenta por tercera vez?","o":["Debe esperar seis meses","Debe tomar educación vial otra vez","No cambia nada","Paga una tarifa de $10"],"h1":"Cuesta un poco de dinero.","h2":"En Minnesota, después de reprobar el examen escrito dos veces seguidas, paga $10 por el tercer examen y por cada uno después.","p":"Correcto. El tercer examen y los siguientes cuestan $10."},"ref":{"doc":"MN","page":10}},{"id":"mn-069","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how wide must your side (peripheral) vision be for the vision screening?","o":["At least 60 degrees","At least 90 degrees","At least 105 degrees","At least 180 degrees"],"h1":"It is a little more than a right angle.","h2":"In Minnesota, your peripheral vision must be at least 105 degrees to pass the vision screening.","p":"Correct. At least 105 degrees."},"es":{"q":"En Minnesota, ¿qué tan amplia debe ser su visión lateral (periférica) en el examen de la vista?","o":["Al menos 60 grados","Al menos 90 grados","Al menos 105 grados","Al menos 180 grados"],"h1":"Es un poco más que un ángulo recto.","h2":"En Minnesota, su visión periférica debe ser de al menos 105 grados para aprobar el examen de la vista.","p":"Correcto. Al menos 105 grados."},"ref":{"doc":"MN","page":10}},{"id":"mn-070","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, which vehicle may you NOT use for your road test?","o":["A neighborhood electric vehicle (NEV)","A car with a backup camera","A rental car with you listed on the contract","Your parent's insured car"],"h1":"Some small low-speed vehicles are not allowed.","h2":"In Minnesota, neighborhood electric vehicles (NEVs) are not allowed for the road test.","p":"Right. An NEV cannot be used for the road test."},"es":{"q":"En Minnesota, ¿qué vehículo NO puede usar en su examen de manejo?","o":["Un vehículo eléctrico de vecindario (NEV)","Un auto con cámara de reversa","Un auto rentado con usted en el contrato","El auto asegurado de su padre"],"h1":"Algunos vehículos pequeños de baja velocidad no se permiten.","h2":"En Minnesota, los vehículos eléctricos de vecindario (NEV) no se permiten en el examen de manejo.","p":"Correcto. No se puede usar un NEV en el examen."},"ref":{"doc":"MN","page":10}},{"id":"mn-071","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, who may ride in the car with you during the road test, besides the examiner?","o":["Your parent","No one, not even a pet","An interpreter","A small child in a car seat"],"h1":"The examiner must be the only passenger.","h2":"In Minnesota, no passengers are allowed during the road test, including pets, children and interpreters.","p":"Correct. Only the examiner rides with you."},"es":{"q":"En Minnesota, ¿quién puede ir en el auto con usted durante el examen de manejo, además del examinador?","o":["Su padre o madre","Nadie, ni siquiera una mascota","Un intérprete","Un niño pequeño en su asiento"],"h1":"El examinador debe ser el único pasajero.","h2":"En Minnesota, no se permiten pasajeros durante el examen de manejo, incluidos mascotas, niños e intérpretes.","p":"Correcto. Solo el examinador va con usted."},"ref":{"doc":"MN","page":11}},{"id":"mn-072","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you failed the road test twice. What happens for each road test after that?","o":["You must wait one year","You must retake the written test","You pay a $20 fee","You must bring two adults"],"h1":"It costs money.","h2":"In Minnesota, after two failed road tests, you pay a $20 fee for each test after that.","p":"Right. Each later road test costs $20."},"es":{"q":"En Minnesota, reprobó el examen de manejo dos veces. ¿Qué pasa en cada examen de manejo después?","o":["Debe esperar un año","Debe repetir el examen escrito","Paga una tarifa de $20","Debe llevar a dos adultos"],"h1":"Cuesta dinero.","h2":"En Minnesota, después de reprobar dos exámenes de manejo, paga $20 por cada examen después.","p":"Correcto. Cada examen posterior cuesta $20."},"ref":{"doc":"MN","page":11}},{"id":"mn-073","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you cannot pass the vehicle safety equipment check at the start of your road test. What happens?","o":["You lose a few points but keep driving","The examiner fixes it for you","You must retake the written test","You cannot finish the road test that day"],"h1":"The car must be safe before the drive starts.","h2":"In Minnesota, if you cannot pass the safety equipment demonstration, you are not allowed to finish the road test that day.","p":"Correct. The test ends for that day."},"es":{"q":"En Minnesota, no puede aprobar la revisión del equipo de seguridad al inicio de su examen de manejo. ¿Qué pasa?","o":["Pierde unos puntos pero sigue manejando","El examinador lo arregla","Debe repetir el examen escrito","No puede terminar el examen ese día"],"h1":"El auto debe ser seguro antes de empezar.","h2":"En Minnesota, si no aprueba la demostración del equipo de seguridad, no puede terminar el examen de manejo ese día.","p":"Correcto. El examen termina por ese día."},"ref":{"doc":"MN","page":11}},{"id":"mn-074","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, the road test includes a 90-degree backing skill. What does it imitate?","o":["Backing into a 10-foot-wide driveway or parking space","Backing down a long highway shoulder","Backing out of a garage onto a freeway","Backing around a corner at a stop sign"],"h1":"Think of a narrow parking spot.","h2":"In Minnesota, the 90-degree backing maneuver imitates backing into a driveway or parking space about 10 feet wide.","p":"Right. It is like backing into a 10-foot-wide space."},"es":{"q":"En Minnesota, el examen de manejo incluye una maniobra de reversa de 90 grados. ¿Qué imita?","o":["Entrar en reversa a una entrada o espacio de 10 pies de ancho","Ir en reversa por el acotamiento de una carretera","Salir en reversa de un garaje a una autopista","Dar reversa en una esquina con alto"],"h1":"Piense en un espacio de estacionamiento angosto.","h2":"En Minnesota, la maniobra de reversa de 90 grados imita entrar en reversa a una entrada o espacio de unos 10 pies de ancho.","p":"Correcto. Es como entrar en reversa a un espacio de 10 pies."},"ref":{"doc":"MN","page":12}},{"id":"mn-075","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, during your road test another car hits you. You could have avoided it, but the other driver is at fault. What happens?","o":["You pass if everything else was good","You fail the road test","You lose a few points","The test is repeated the same day"],"h1":"The examiner looks at whether you could have prevented it.","h2":"In Minnesota, being in a crash you could have avoided makes you fail the road test right away, even if you are not legally at fault.","p":"Correct. An avoidable crash is an automatic fail."},"es":{"q":"En Minnesota, durante su examen de manejo otro auto lo choca. Usted pudo evitarlo, pero la culpa es del otro conductor. ¿Qué pasa?","o":["Aprueba si todo lo demás salió bien","Reprueba el examen de manejo","Pierde algunos puntos","Repite el examen el mismo día"],"h1":"El examinador se fija en si usted pudo evitarlo.","h2":"En Minnesota, un choque que usted pudo evitar le hace reprobar el examen de manejo de inmediato, aunque legalmente no tenga la culpa.","p":"Correcto. Un choque evitable es reprobación automática."},"ref":{"doc":"MN","page":12}},{"id":"mn-076","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you have a license and a doctor diagnoses you with epilepsy. How soon must you send DVS a doctor's statement?","o":["Within 7 days","Within 10 days","Within 30 days","At your next renewal"],"h1":"It is about one month.","h2":"In Minnesota, if you are diagnosed with epilepsy or a condition that could make you lose consciousness, you must send a doctor's statement within 30 days.","p":"Right. You have 30 days."},"es":{"q":"En Minnesota, usted tiene licencia y un médico le diagnostica epilepsia. ¿En cuánto tiempo debe enviar a DVS una declaración del médico?","o":["En 7 días","En 10 días","En 30 días","En su próxima renovación"],"h1":"Es más o menos un mes.","h2":"En Minnesota, si le diagnostican epilepsia o una condición que pueda hacerle perder el conocimiento, debe enviar una declaración médica en 30 días.","p":"Correcto. Tiene 30 días."},"ref":{"doc":"MN","page":12}},{"id":"mn-077","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, which person may sign and approve a 16-year-old's license application?","o":["A 17-year-old classmate","A neighbor who drives","The teen's driving instructor","A county-appointed foster parent"],"h1":"It is a person with legal responsibility for the teen.","h2":"In Minnesota, an under-18 application may be approved by a parent, a court-appointed guardian, a county-appointed foster parent or the director of the teen's transitional living program.","p":"Correct. A county-appointed foster parent may sign."},"es":{"q":"En Minnesota, ¿quién puede firmar y aprobar la solicitud de licencia de un joven de 16 años?","o":["Un compañero de clase de 17 años","Un vecino que maneja","El instructor de manejo del joven","Un padre de crianza asignado por el condado"],"h1":"Es una persona con responsabilidad legal sobre el joven.","h2":"En Minnesota, la solicitud de un menor de 18 puede aprobarla un padre o madre, un tutor nombrado por un tribunal, un padre de crianza asignado por el condado o el director del programa de vivienda de transición.","p":"Correcto. Un padre de crianza asignado por el condado puede firmar."},"ref":{"doc":"MN","page":13}},{"id":"mn-078","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, a 16-year-old foreign exchange student wants a permit. Who may sign the application?","o":["The student's parents, with notarized signatures","The host family, always","The high school principal","Any adult the student lives with"],"h1":"Host sponsors can sign only if they are legal guardians.","h2":"In Minnesota, host sponsors cannot sign for an exchange student unless they are legal guardians; the student needs application forms with the parents' notarized signatures.","p":"Right. The parents sign, and the signatures are notarized."},"es":{"q":"En Minnesota, un estudiante de intercambio de 16 años quiere un permiso. ¿Quién puede firmar la solicitud?","o":["Los padres del estudiante, con firmas notariadas","La familia anfitriona, siempre","El director de la escuela","Cualquier adulto con quien viva"],"h1":"La familia anfitriona solo puede firmar si es tutora legal.","h2":"En Minnesota, la familia anfitriona no puede firmar por un estudiante de intercambio a menos que sea su tutora legal; el estudiante necesita formularios con las firmas notariadas de sus padres.","p":"Correcto. Firman los padres, con firmas notariadas."},"ref":{"doc":"MN","page":13}},{"id":"mn-079","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, how many hours of driver education classroom instruction must a teen usually finish before getting a permit?","o":["15 hours","30 hours","40 hours","50 hours"],"h1":"A concurrent course needs only the first half done.","h2":"In Minnesota, a teen under 18 must finish 30 hours of classroom instruction and be enrolled in behind-the-wheel training, or finish the first 15 hours of a concurrent course.","p":"Correct. The full classroom phase is 30 hours."},"es":{"q":"En Minnesota, ¿cuántas horas de clase teórica de educación vial debe terminar normalmente un joven antes de obtener el permiso?","o":["15 horas","30 horas","40 horas","50 horas"],"h1":"Un curso simultáneo solo necesita la primera mitad.","h2":"En Minnesota, un menor de 18 debe terminar 30 horas de clase teórica y estar inscrito en la práctica al volante, o terminar las primeras 15 horas de un curso simultáneo.","p":"Correcto. La fase teórica completa es de 30 horas."},"ref":{"doc":"MN","page":13}},{"id":"mn-080","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you are 20 and applying for your first instruction permit. Do you need driver education classes?","o":["Yes, 30 classroom hours","Yes, only behind-the-wheel lessons","No, it is not required at 18 or older","Only if you fail the written test"],"h1":"Driver education is a rule for teens.","h2":"In Minnesota, classroom and behind-the-wheel instruction are not required if you are 18 or older.","p":"Right. Adults 18 and older do not need driver education."},"es":{"q":"En Minnesota, usted tiene 20 años y solicita su primer permiso de aprendizaje. ¿Necesita clases de educación vial?","o":["Sí, 30 horas de clase","Sí, solo clases al volante","No, no se exige a los 18 años o más","Solo si reprueba el examen escrito"],"h1":"La educación vial es una regla para jóvenes.","h2":"En Minnesota, la clase teórica y la práctica al volante no se exigen si usted tiene 18 años o más.","p":"Correcto. Los adultos de 18 años o más no necesitan educación vial."},"ref":{"doc":"MN","page":13}},{"id":"mn-081","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you are 25 with an instruction permit. How old must your supervising driver be?","o":["21 or older","25 or older","16 or older","18 or older"],"h1":"The rule is younger than the one for teens.","h2":"In Minnesota, a permit holder 18 or older must be supervised by a licensed driver who is at least 18.","p":"Correct. For adults, the supervisor must be 18 or older."},"es":{"q":"En Minnesota, usted tiene 25 años y un permiso de aprendizaje. ¿Qué edad debe tener su conductor supervisor?","o":["21 años o más","25 años o más","16 años o más","18 años o más"],"h1":"La regla es menor que la de los jóvenes.","h2":"En Minnesota, quien tiene permiso y 18 años o más debe ir supervisado por un conductor con licencia de al menos 18 años.","p":"Correcto. Para adultos, el supervisor debe tener 18 años o más."},"ref":{"doc":"MN","page":14}},{"id":"mn-082","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, you are 20 and have an instruction permit. How long must you hold it before your road test?","o":["6 months","3 months","1 month","12 months"],"h1":"Older new drivers wait less.","h2":"In Minnesota, a permit holder 19 or older must hold the permit for at least three months before the road test.","p":"Right. At 19 or older, it is three months."},"es":{"q":"En Minnesota, usted tiene 20 años y un permiso de aprendizaje. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["6 meses","3 meses","1 mes","12 meses"],"h1":"Los conductores nuevos mayores esperan menos.","h2":"En Minnesota, quien tiene permiso y 19 años o más debe tenerlo al menos tres meses antes del examen de manejo.","p":"Correcto. A los 19 años o más son tres meses."},"ref":{"doc":"MN","page":14}},{"id":"mn-083","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how long is a provisional license valid?","o":["Six months","One year","Two years from the application date","Until age 21"],"h1":"It is the same length as a permit.","h2":"In Minnesota, the provisional license is valid for two years from the date you apply.","p":"Right. A provisional license lasts two years."},"es":{"q":"En Minnesota, ¿cuánto tiempo es válida la licencia provisional?","o":["Seis meses","Un año","Dos años desde la fecha de solicitud","Hasta los 21 años"],"h1":"Dura lo mismo que un permiso.","h2":"En Minnesota, la licencia provisional es válida por dos años desde la fecha en que la solicita.","p":"Correcto. La licencia provisional dura dos años."},"ref":{"doc":"MN","page":14}},{"id":"mn-084","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, a 16-year-old in the first six months of a provisional license wants to drive alone at 1 a.m. Which trip is allowed?","o":["Driving home from a friend's party","Going out for a late snack","Driving a friend home from a movie","Driving home from work"],"h1":"There are a few trips linked to work and school.","h2":"In Minnesota, in the first six months a provisional driver may drive from midnight to 5 a.m. between home and work, for work, or to a school event with no school transport.","p":"Correct. Driving between home and work is allowed."},"es":{"q":"En Minnesota, un joven de 16 años en los primeros seis meses de licencia provisional quiere manejar solo a la 1 a. m. ¿Qué viaje está permitido?","o":["Regresar de una fiesta de un amigo","Salir por un bocadillo nocturno","Llevar a un amigo a casa después del cine","Regresar a casa del trabajo"],"h1":"Hay algunos viajes ligados al trabajo y la escuela.","h2":"En Minnesota, en los primeros seis meses un conductor provisional puede manejar de medianoche a 5 a. m. entre la casa y el trabajo, por trabajo o a un evento escolar sin transporte de la escuela.","p":"Correcto. Manejar entre la casa y el trabajo está permitido."},"ref":{"doc":"MN","page":14}},{"id":"mn-085","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, a teen in the first months of a provisional license is driving, and a parent is in the car. How many passengers under 20 may ride along?","o":["The passenger limit does not apply","Only one","Only three","None"],"h1":"The limit is about teens driving without a parent.","h2":"In Minnesota, the provisional license passenger limits do not apply when a parent or guardian is in the vehicle.","p":"Right. With a parent along, the limit is lifted."},"es":{"q":"En Minnesota, un joven en los primeros meses de licencia provisional maneja con su padre en el auto. ¿Cuántos pasajeros menores de 20 pueden ir?","o":["El límite de pasajeros no se aplica","Solo uno","Solo tres","Ninguno"],"h1":"El límite es para jóvenes que manejan sin un padre.","h2":"En Minnesota, los límites de pasajeros de la licencia provisional no se aplican cuando va un padre o tutor en el vehículo.","p":"Correcto. Con un padre presente, no hay límite."},"ref":{"doc":"MN","page":15}},{"id":"mn-086","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, a 15-year-old with no license is convicted of an alcohol violation while driving. Under Vanessa's Law, when can they get a permit?","o":["After six months","Not until age 18","On their 16th birthday","After paying a fine"],"h1":"The wait lasts until adulthood.","h2":"In Minnesota, under Vanessa's Law, a teen convicted of an alcohol or crash-related violation while driving unlicensed cannot get a permit or license until age 18.","p":"Correct. They must wait until 18."},"es":{"q":"En Minnesota, un joven de 15 años sin licencia es condenado por una infracción de alcohol al manejar. Según la Ley de Vanessa, ¿cuándo puede obtener un permiso?","o":["Después de seis meses","Hasta los 18 años","En su cumpleaños 16","Después de pagar una multa"],"h1":"La espera dura hasta la mayoría de edad.","h2":"En Minnesota, según la Ley de Vanessa, un joven condenado por una infracción de alcohol o relacionada con un choque al manejar sin licencia no puede obtener permiso ni licencia hasta los 18 años.","p":"Correcto. Debe esperar hasta los 18."},"ref":{"doc":"MN","page":15}},{"id":"mn-087","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, a 17-year-old's provisional license is revoked for a crash-related violation, with a 30-day withdrawal. When can they get a license back?","o":["After 30 days","After 90 days","At age 18 or the end of the withdrawal, whichever is later","Never"],"h1":"Vanessa's Law uses the longer of two times.","h2":"In Minnesota, under Vanessa's Law, a provisional driver revoked for a crash-related or alcohol violation cannot get a license until age 18 or until the withdrawal ends, whichever is longer.","p":"Right. They wait for the later of the two."},"es":{"q":"En Minnesota, a un joven de 17 años le revocan la licencia provisional por una infracción relacionada con un choque, con 30 días de retiro. ¿Cuándo puede recuperar la licencia?","o":["Después de 30 días","Después de 90 días","A los 18 años o al fin del retiro, lo que sea más tarde","Nunca"],"h1":"La Ley de Vanessa usa el más largo de dos plazos.","h2":"En Minnesota, según la Ley de Vanessa, un conductor provisional revocado por una infracción de choque o alcohol no puede recuperar la licencia hasta los 18 años o hasta que termine el retiro, lo que sea más largo.","p":"Correcto. Espera el plazo que termine más tarde."},"ref":{"doc":"MN","page":15}},{"id":"mn-088","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, under Vanessa's Law, what kind of driver education course must a revoked teen take before reinstatement?","o":["An online computer course","A 4-hour defensive driving class","No course is needed","A 30-hour classroom course, not online"],"h1":"The course must be in a classroom.","h2":"In Minnesota, under Vanessa's Law, reinstatement usually needs a 30-hour classroom driver education course; an online course is not accepted.","p":"Correct. It must be a 30-hour classroom course."},"es":{"q":"En Minnesota, según la Ley de Vanessa, ¿qué curso de educación vial debe tomar un joven revocado antes de recuperar la licencia?","o":["Un curso en línea por computadora","Una clase de manejo defensivo de 4 horas","No necesita curso","Un curso en aula de 30 horas, no en línea"],"h1":"El curso debe ser en un aula.","h2":"En Minnesota, según la Ley de Vanessa, para recuperar la licencia normalmente se necesita un curso en aula de 30 horas; no se acepta un curso en línea.","p":"Correcto. Debe ser un curso en aula de 30 horas."},"ref":{"doc":"MN","page":16}},{"id":"mn-089","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, a teen is reinstated under Vanessa's Law and gets a new permit. How long must they hold it, and what must they finish?","o":["90 days, with 6 hours of behind-the-wheel training","30 days, with a written test","1 year, with 50 hours of practice","6 months, with no training"],"h1":"It is about three months.","h2":"In Minnesota, after reinstatement under Vanessa's Law, the teen holds the permit for 90 days and completes six hours of behind-the-wheel training.","p":"Right. 90 days and six hours behind the wheel."},"es":{"q":"En Minnesota, un joven recupera su derecho según la Ley de Vanessa y obtiene un permiso nuevo. ¿Cuánto tiempo debe tenerlo y qué debe terminar?","o":["90 días, con 6 horas de práctica al volante","30 días, con un examen escrito","1 año, con 50 horas de práctica","6 meses, sin entrenamiento"],"h1":"Son unos tres meses.","h2":"En Minnesota, después de recuperar el derecho según la Ley de Vanessa, el joven tiene el permiso 90 días y completa seis horas de práctica al volante.","p":"Correcto. 90 días y seis horas al volante."},"ref":{"doc":"MN","page":16}},{"id":"mn-090","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, a 17-year-old has had a provisional license for 12 months. Which record still allows a full Class D license?","o":["One alcohol violation","One speeding ticket that was not crash-related","One crash-related moving violation","Two speeding tickets"],"h1":"Only one minor ticket is allowed.","h2":"In Minnesota, after 12 months on a provisional license you may get a full license with no alcohol, drug or crash-related violations and no more than one other moving violation.","p":"Correct. One non-crash moving violation is allowed."},"es":{"q":"En Minnesota, un joven de 17 años tiene licencia provisional desde hace 12 meses. ¿Qué historial todavía permite una licencia Clase D completa?","o":["Una infracción de alcohol","Una multa por velocidad que no fue por choque","Una infracción relacionada con un choque","Dos multas por velocidad"],"h1":"Solo se permite una multa menor.","h2":"En Minnesota, después de 12 meses con licencia provisional puede obtener la licencia completa sin infracciones de alcohol, drogas o choques y con no más de una otra infracción de tránsito.","p":"Correcto. Se permite una infracción que no fue por choque."},"ref":{"doc":"MN","page":16}},{"id":"mn-091","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, a 17-year-old upgrades from a provisional to a full license. How many extra supervised driving hours must they certify?","o":["None","5 hours","10 hours","40 hours"],"h1":"The supervising driver must be 21 or older.","h2":"In Minnesota, a driver under 18 moving to a full license must certify at least 10 hours of driving supervised by a licensed driver age 21 or older.","p":"Right. Ten supervised hours are needed."},"es":{"q":"En Minnesota, un joven de 17 años pasa de licencia provisional a licencia completa. ¿Cuántas horas extra de manejo supervisado debe certificar?","o":["Ninguna","5 horas","10 horas","40 horas"],"h1":"El supervisor debe tener 21 años o más.","h2":"En Minnesota, un conductor menor de 18 que pasa a la licencia completa debe certificar al menos 10 horas de manejo supervisado por un conductor con licencia de 21 años o más.","p":"Correcto. Se necesitan diez horas supervisadas."},"ref":{"doc":"MN","page":16}},{"id":"mn-092","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, after a license marked \"Under 21\" expires on your 21st birthday, how often must you renew?","o":["Every year","Every two years","Every eight years","Every four years"],"h1":"It is the usual adult renewal period.","h2":"In Minnesota, after the Under 21 license expires on your 21st birthday, the license expires every four years on your birthday.","p":"Correct. Every four years."},"es":{"q":"En Minnesota, después de que la licencia marcada \"Under 21\" vence en su cumpleaños 21, ¿cada cuánto debe renovarla?","o":["Cada año","Cada dos años","Cada ocho años","Cada cuatro años"],"h1":"Es el período normal para adultos.","h2":"En Minnesota, después de que la licencia Under 21 vence en su cumpleaños 21, la licencia vence cada cuatro años en su cumpleaños.","p":"Correcto. Cada cuatro años."},"ref":{"doc":"MN","page":16}},{"id":"mn-093","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, a 15-year-old has a restricted farm work license. Where and when may they drive alone for farm work?","o":["In daylight, within 40 miles of the farmhouse","At any hour, anywhere in the county","Only at night, on farm roads","In daylight, within 150 miles of the farm"],"h1":"The limit is daylight and a short distance.","h2":"In Minnesota, a restricted farm work license lets a teen drive alone for farm work during daylight within 40 miles of the farmhouse.","p":"Right. Daylight only, within 40 miles."},"es":{"q":"En Minnesota, un joven de 15 años tiene una licencia restringida para trabajo agrícola. ¿Dónde y cuándo puede manejar solo para trabajo agrícola?","o":["De día, a menos de 40 millas de la casa de la granja","A cualquier hora, en todo el condado","Solo de noche, en caminos de la granja","De día, a menos de 150 millas de la granja"],"h1":"El límite es de día y a poca distancia.","h2":"En Minnesota, la licencia restringida para trabajo agrícola permite a un joven manejar solo para trabajo agrícola de día y a menos de 40 millas de la casa de la granja.","p":"Correcto. Solo de día y a menos de 40 millas."},"ref":{"doc":"MN","page":16}},{"id":"mn-094","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, a 15-year-old has a special medical driver's license. What restriction code appears on it?","o":["FARM","MEDLIM","NIGHT","TEEN"],"h1":"It is short for medical limit.","h2":"In Minnesota, the special medical driver's license shows the restriction MEDLIM.","p":"Correct. The code is MEDLIM."},"es":{"q":"En Minnesota, un joven de 15 años tiene una licencia especial por razones médicas. ¿Qué código de restricción aparece?","o":["FARM","MEDLIM","NIGHT","TEEN"],"h1":"Es la abreviatura de límite médico en inglés.","h2":"En Minnesota, la licencia especial por razones médicas muestra la restricción MEDLIM.","p":"Correcto. El código es MEDLIM."},"ref":{"doc":"MN","page":17}},{"id":"mn-095","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what must a 15-year-old finish to get a motorized bicycle (moped) permit?","o":["Nothing, just pay a fee","Only a vision test","A moped safety course and the written, vision and road tests","50 hours of supervised driving"],"h1":"There is a course and several tests.","h2":"In Minnesota, you can get a moped permit at 15 after a motorized bicycle safety course and passing the written, vision and road tests.","p":"Right. A safety course plus three tests."},"es":{"q":"En Minnesota, ¿qué debe terminar un joven de 15 años para obtener un permiso de bicicleta motorizada (moped)?","o":["Nada, solo pagar una tarifa","Solo un examen de la vista","Un curso de seguridad de moped y los exámenes escrito, de la vista y de manejo","50 horas de manejo supervisado"],"h1":"Hay un curso y varios exámenes.","h2":"En Minnesota, puede obtener un permiso de moped a los 15 años después de un curso de seguridad de bicicleta motorizada y aprobar los exámenes escrito, de la vista y de manejo.","p":"Correcto. Un curso de seguridad y tres exámenes."},"ref":{"doc":"MN","page":17}},{"id":"mn-096","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, what do you need to ride an electric-assist bicycle?","o":["A moped permit","A Class D license","A motorcycle endorsement","No license, but you must be at least 15"],"h1":"An e-bike is not a moped.","h2":"In Minnesota, you need no test or license to ride an electric-assist bicycle, but you must be at least 15 years old.","p":"Correct. No license, but a minimum age of 15."},"es":{"q":"En Minnesota, ¿qué necesita para usar una bicicleta eléctrica de pedaleo asistido?","o":["Un permiso de moped","Una licencia Clase D","Un endoso de motocicleta","Ninguna licencia, pero debe tener al menos 15 años"],"h1":"Una bicicleta eléctrica no es un moped.","h2":"En Minnesota, no necesita examen ni licencia para usar una bicicleta eléctrica de pedaleo asistido, pero debe tener al menos 15 años.","p":"Correcto. Sin licencia, pero con edad mínima de 15."},"ref":{"doc":"MN","page":17}},{"id":"mn-097","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, which vehicle may you NOT drive with only a Class D license?","o":["A truck with a gross weight of 26,001 pounds or more","A pickup truck","A motor home for personal use","A neighborhood electric vehicle"],"h1":"Class D covers lighter single vehicles.","h2":"In Minnesota, a Class D license does not cover single vehicles with a gross weight of 26,001 pounds or more.","p":"Right. That heavy truck needs a commercial license."},"es":{"q":"En Minnesota, ¿qué vehículo NO puede manejar solo con licencia Clase D?","o":["Un camión con peso bruto de 26,001 libras o más","Una camioneta pickup","Una casa rodante de uso personal","Un vehículo eléctrico de vecindario"],"h1":"La Clase D cubre vehículos sencillos más ligeros.","h2":"En Minnesota, la licencia Clase D no cubre vehículos sencillos con peso bruto de 26,001 libras o más.","p":"Correcto. Ese camión pesado necesita licencia comercial."},"ref":{"doc":"MN","page":17}},{"id":"mn-098","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, a Class D license does not cover a vehicle designed to carry more than how many people, including the driver?","o":["8","15","20","25"],"h1":"A large van for a group is beyond this number.","h2":"In Minnesota, a Class D license does not cover vehicles designed to carry more than 15 passengers, including the driver.","p":"Correct. More than 15 needs a different license."},"es":{"q":"En Minnesota, la licencia Clase D no cubre un vehículo diseñado para llevar más de cuántas personas, incluido el conductor?","o":["8","15","20","25"],"h1":"Una camioneta grande para grupos supera este número.","h2":"En Minnesota, la licencia Clase D no cubre vehículos diseñados para llevar más de 15 pasajeros, incluido el conductor.","p":"Correcto. Más de 15 necesita otra licencia."},"ref":{"doc":"MN","page":17}},{"id":"mn-099","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how far from the farm may a farmer's family member drive a farm truck with a Class D license?","o":["Within 40 miles","Within 100 miles","Within 150 miles","Any distance"],"h1":"It is farther than 100 miles.","h2":"In Minnesota, a Class D driver who is the farmer, a family member or a farm employee may drive a farm truck within 150 miles of the farm.","p":"Right. Within 150 miles of the farm."},"es":{"q":"En Minnesota, ¿a qué distancia de la granja puede un familiar del granjero manejar un camión agrícola con licencia Clase D?","o":["A menos de 40 millas","A menos de 100 millas","A menos de 150 millas","A cualquier distancia"],"h1":"Es más de 100 millas.","h2":"En Minnesota, un conductor Clase D que es el granjero, un familiar o un empleado puede manejar un camión agrícola a menos de 150 millas de la granja.","p":"Correcto. A menos de 150 millas de la granja."},"ref":{"doc":"MN","page":17}},{"id":"mn-100","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, with a Class D license you may tow a trailer heavier than 10,000 pounds only if what is true?","o":["The trailer has its own brakes","You drive under 45 mph","You have a passenger","The combined weight is 26,000 pounds or less"],"h1":"Think of the total weight of both vehicles.","h2":"In Minnesota, a Class D driver may tow a trailer over 10,000 pounds only if the combined gross weight of the vehicle and trailer is 26,000 pounds or less.","p":"Correct. The combination must be 26,000 pounds or less."},"es":{"q":"En Minnesota, con licencia Clase D puede remolcar un remolque de más de 10,000 libras solo si se cumple qué?","o":["El remolque tiene sus propios frenos","Maneja a menos de 45 mph","Lleva un pasajero","El peso combinado es de 26,000 libras o menos"],"h1":"Piense en el peso total de ambos vehículos.","h2":"En Minnesota, un conductor Clase D puede remolcar un remolque de más de 10,000 libras solo si el peso bruto combinado del vehículo y el remolque es de 26,000 libras o menos.","p":"Correcto. La combinación debe ser de 26,000 libras o menos."},"ref":{"doc":"MN","page":18}},{"id":"mn-101","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, which license class lets you drive any vehicle or trailer combination, with the right endorsements?","o":["Class A","Class B","Class C","Class D"],"h1":"It is the first letter of the alphabet.","h2":"In Minnesota, a Class A license with the right endorsements lets you drive any vehicle or trailer combination.","p":"Right. Class A covers every combination."},"es":{"q":"En Minnesota, ¿qué clase de licencia le permite manejar cualquier combinación de vehículo y remolque, con los endosos correctos?","o":["Clase A","Clase B","Clase C","Clase D"],"h1":"Es la primera letra del alfabeto.","h2":"En Minnesota, la licencia Clase A con los endosos correctos le permite manejar cualquier combinación de vehículo y remolque.","p":"Correcto. La Clase A cubre todas las combinaciones."},"ref":{"doc":"MN","page":18}},{"id":"mn-102","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what test must you pass every time you renew your driver's license?","o":["A written test","A vision test","A road test","A hearing test"],"h1":"It checks how well you see.","h2":"In Minnesota, you must pass a vision test to renew your driver's license.","p":"Correct. A vision test is part of every renewal."},"es":{"q":"En Minnesota, ¿qué examen debe aprobar cada vez que renueva su licencia de conducir?","o":["Un examen escrito","Un examen de la vista","Un examen de manejo","Un examen del oído"],"h1":"Revisa qué tan bien ve.","h2":"En Minnesota, debe aprobar un examen de la vista para renovar su licencia de conducir.","p":"Correcto. El examen de la vista es parte de cada renovación."},"ref":{"doc":"MN","page":19}},{"id":"mn-103","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you had a valid license when you joined active military service. When must you renew it?","o":["Every four years while serving","Within 30 days of your next leave","Within one year after you leave active service","Only after age 26"],"h1":"You do not need to renew while you serve.","h2":"In Minnesota, a person in active military service with a valid license does not need to renew until discharge, and must renew within one year after leaving active service.","p":"Right. Renew within one year of discharge."},"es":{"q":"En Minnesota, usted tenía una licencia válida cuando entró al servicio militar activo. ¿Cuándo debe renovarla?","o":["Cada cuatro años mientras sirve","En 30 días de su próximo permiso","En un año después de dejar el servicio activo","Solo después de los 26 años"],"h1":"No necesita renovar mientras sirve.","h2":"En Minnesota, una persona en servicio militar activo con licencia válida no necesita renovar hasta su baja, y debe renovar dentro del año siguiente a dejar el servicio activo.","p":"Correcto. Renueva en un año después de la baja."},"ref":{"doc":"MN","page":19}},{"id":"mn-104","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, how many days of active military service must a veteran have to add a veteran mark to their license?","o":["30 days","90 days","365 days","181 days"],"h1":"It is about half a year.","h2":"In Minnesota, to add the veteran indicator you need at least 181 days of active service with an honorable or general discharge.","p":"Correct. At least 181 days."},"es":{"q":"En Minnesota, ¿cuántos días de servicio militar activo debe tener un veterano para agregar la marca de veterano a su licencia?","o":["30 días","90 días","365 días","181 días"],"h1":"Es más o menos medio año.","h2":"En Minnesota, para agregar el indicador de veterano necesita al menos 181 días de servicio activo con baja honorable o general.","p":"Correcto. Al menos 181 días."},"ref":{"doc":"MN","page":19}},{"id":"mn-105","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, you already have a driver's license and want a state ID card too. What happens?","o":["You must give up your driving privileges to get the ID card","You can hold both at once","You get the ID card free","You must take a road test"],"h1":"You can hold only one type of card.","h2":"In Minnesota, DVS will not issue an ID card to someone with a valid license or permit unless they sign a statement giving up their driving privileges.","p":"Right. You cannot have both at the same time."},"es":{"q":"En Minnesota, ya tiene licencia de conducir y quiere también una tarjeta de identificación estatal. ¿Qué pasa?","o":["Debe renunciar a su derecho a manejar para obtener la identificación","Puede tener las dos a la vez","Le dan la identificación gratis","Debe hacer un examen de manejo"],"h1":"Solo puede tener un tipo de tarjeta.","h2":"En Minnesota, DVS no emite una identificación a quien tiene licencia o permiso válido, a menos que firme una declaración renunciando a manejar.","p":"Correcto. No puede tener las dos al mismo tiempo."},"ref":{"doc":"MN","page":20}},{"id":"mn-106","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, how much extra does it cost to fast-track a license renewal?","o":["$10","$20","$35","$50"],"h1":"It is less than $25.","h2":"In Minnesota, you can fast-track a driver's license or ID for an extra $20, but not for a first-time card, an enhanced card or an upgrade.","p":"Correct. Fast track costs $20 more."},"es":{"q":"En Minnesota, ¿cuánto cuesta de más el trámite rápido (fast track) de una renovación de licencia?","o":["$10","$20","$35","$50"],"h1":"Es menos de $25.","h2":"En Minnesota, puede pedir trámite rápido para la licencia o identificación por $20 más, pero no para una primera tarjeta, una tarjeta mejorada ni un cambio de clase.","p":"Correcto. El trámite rápido cuesta $20 más."},"ref":{"doc":"MN","page":21}},{"id":"mn-107","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, how early may you fill out the online pre-application before your test appointment?","o":["Up to one year before","Up to 90 days before","No more than 30 days before","Only on the day of the test"],"h1":"It is about one month.","h2":"In Minnesota, you should complete the online pre-application no more than 30 days before your visit.","p":"Right. No more than 30 days before."},"es":{"q":"En Minnesota, ¿con cuánta anticipación puede llenar la solicitud previa en línea antes de su cita de examen?","o":["Hasta un año antes","Hasta 90 días antes","No más de 30 días antes","Solo el día del examen"],"h1":"Es más o menos un mes.","h2":"En Minnesota, debe completar la solicitud previa en línea no más de 30 días antes de su visita.","p":"Correcto. No más de 30 días antes."},"ref":{"doc":"MN","page":4}},{"id":"mn-108","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, a teen practiced part of their six months of permit driving in another state. What must they bring to the road test?","o":["A letter from a teacher","A photo of their old permit","Nothing extra","A certified driving record from that state"],"h1":"Minnesota must check the record from the other state.","h2":"In Minnesota, if part of your permit time was in another state, you must bring a certified driving record from that state.","p":"Correct. A certified driving record is needed."},"es":{"q":"En Minnesota, un joven hizo parte de sus seis meses de permiso en otro estado. ¿Qué debe llevar al examen de manejo?","o":["Una carta de un maestro","Una foto de su permiso anterior","Nada adicional","Un historial de manejo certificado de ese estado"],"h1":"Minnesota debe revisar el historial del otro estado.","h2":"En Minnesota, si parte del tiempo con permiso fue en otro estado, debe llevar un historial de manejo certificado de ese estado.","p":"Correcto. Se necesita un historial de manejo certificado."},"ref":{"doc":"MN","page":5}},{"id":"mn-109","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, your license was revoked because you had no insurance. What must you do to get it back?","o":["Pass a written test and pay a $30 reinstatement fee","Only wait 30 days","Pass a road test only","Take a 30-hour class"],"h1":"There is a test and a small fee.","h2":"In Minnesota, after a revocation for no insurance, you must pass a written test, pay a $30 reinstatement fee, apply for a new license and show an insurance certificate.","p":"Right. A written test and a $30 fee are part of it."},"es":{"q":"En Minnesota, le revocaron la licencia por no tener seguro. ¿Qué debe hacer para recuperarla?","o":["Aprobar un examen escrito y pagar $30 de reinstalación","Solo esperar 30 días","Aprobar solo un examen de manejo","Tomar una clase de 30 horas"],"h1":"Hay un examen y una tarifa pequeña.","h2":"En Minnesota, después de una revocación por no tener seguro, debe aprobar un examen escrito, pagar $30 de reinstalación, solicitar una licencia nueva y mostrar un certificado de seguro.","p":"Correcto. Un examen escrito y una tarifa de $30 son parte del proceso."},"ref":{"doc":"MN","page":40}},{"id":"mn-110","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what is the highest penalty for a conviction of driving an uninsured vehicle?","o":["A $100 fine","A $1,000 fine and 90 days in jail","A warning letter","Five years in prison"],"h1":"It can include jail time.","h2":"In Minnesota, a conviction for operating an uninsured vehicle can bring a fine of up to $1,000 and up to 90 days in jail.","p":"Correct. Up to $1,000 and 90 days."},"es":{"q":"En Minnesota, ¿cuál es la pena máxima por una condena por manejar un vehículo sin seguro?","o":["Una multa de $100","Una multa de $1,000 y 90 días de cárcel","Una carta de advertencia","Cinco años de prisión"],"h1":"Puede incluir cárcel.","h2":"En Minnesota, una condena por manejar un vehículo sin seguro puede traer una multa de hasta $1,000 y hasta 90 días de cárcel.","p":"Correcto. Hasta $1,000 y 90 días."},"ref":{"doc":"MN","page":40}},{"id":"mn-111","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, which insurance must a motorcycle owner carry?","o":["No insurance at all","Only theft insurance","Liability insurance for injuries and property damage","Only no-fault insurance"],"h1":"No-fault is optional for motorcycles.","h2":"In Minnesota, motorcycle owners must carry liability insurance that covers injuries and property damage to others; no-fault coverage is optional.","p":"Right. Liability is required."},"es":{"q":"En Minnesota, ¿qué seguro debe tener el dueño de una motocicleta?","o":["Ningún seguro","Solo seguro contra robo","Seguro de responsabilidad por lesiones y daños a la propiedad","Solo seguro sin culpa (no-fault)"],"h1":"El seguro sin culpa es opcional para motocicletas.","h2":"En Minnesota, los dueños de motocicletas deben tener seguro de responsabilidad que cubra lesiones y daños a la propiedad de otros; el seguro sin culpa es opcional.","p":"Correcto. El seguro de responsabilidad es obligatorio."},"ref":{"doc":"MN","page":40}},{"id":"mn-112","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you just moved here. How long do you have to register your car in Minnesota?","o":["10 days","30 days","90 days","60 days"],"h1":"It matches the time to get your license.","h2":"In Minnesota, a new resident has up to 60 days to register their vehicles.","p":"Correct. You have 60 days."},"es":{"q":"En Minnesota, usted acaba de mudarse aquí. ¿Cuánto tiempo tiene para registrar su auto en Minnesota?","o":["10 días","30 días","90 días","60 días"],"h1":"Coincide con el tiempo para obtener la licencia.","h2":"En Minnesota, un nuevo residente tiene hasta 60 días para registrar sus vehículos.","p":"Correcto. Tiene 60 días."},"ref":{"doc":"MN","page":40}},{"id":"mn-113","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, you are convicted a second time of texting while driving. What extra fine must you pay, on top of the court's fine?","o":["$275","$50","$100","$1,000"],"h1":"It is between $200 and $300.","h2":"In Minnesota, after two or more convictions for reading or sending messages while driving, you pay an extra $275 fine on top of the court fine.","p":"Right. The extra fine is $275."},"es":{"q":"En Minnesota, lo condenan por segunda vez por enviar mensajes mientras maneja. ¿Qué multa extra debe pagar, además de la del tribunal?","o":["$275","$50","$100","$1,000"],"h1":"Está entre $200 y $300.","h2":"En Minnesota, después de dos o más condenas por leer o enviar mensajes al manejar, paga una multa extra de $275 además de la del tribunal.","p":"Correcto. La multa extra es de $275."},"ref":{"doc":"MN","page":40}},{"id":"mn-114","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, when may an adult driver use a phone to send a text while driving?","o":["When stopped at a red light","To get emergency help or report a crash or crime","When traffic is light","On a rural road"],"h1":"There are only a few safety exceptions.","h2":"In Minnesota, a driver may not read or send texts while driving, even when stopped in traffic, except to get emergency help, to report a crash or crime, or by using voice-activated or hands-free mode.","p":"Correct. Getting emergency help or reporting a crash or crime is allowed; otherwise texting is allowed only hands-free by voice."},"es":{"q":"En Minnesota, ¿cuándo puede un conductor adulto usar el teléfono para enviar un mensaje mientras maneja?","o":["Cuando está parado en un semáforo en rojo","Para pedir ayuda de emergencia o reportar un choque o delito","Cuando hay poco tráfico","En un camino rural"],"h1":"Solo hay unas pocas excepciones de seguridad.","h2":"En Minnesota, un conductor no puede leer ni enviar mensajes al manejar, ni parado en el tráfico, salvo para pedir ayuda de emergencia, reportar un choque o un delito, o usando el modo de voz o manos libres.","p":"Correcto. Pedir ayuda de emergencia o reportar un choque o delito está permitido; fuera de eso, solo se permite enviar mensajes con manos libres por voz."},"ref":{"doc":"MN","page":40}},{"id":"mn-115","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, which of these can get your license suspended?","o":["Parking in a no-parking zone once","Driving below the speed limit","Letting someone use your license to buy alcohol for a person under 21","Forgetting to renew your plates by one day"],"h1":"It is about misusing your license.","h2":"In Minnesota, your license may be suspended if you let someone use your license, permit or ID to buy alcohol for a person under 21 or tobacco for a person under 18.","p":"Right. Lending your license for that purpose can get it suspended."},"es":{"q":"En Minnesota, ¿cuál de estos puede causar la suspensión de su licencia?","o":["Estacionarse una vez en zona prohibida","Manejar por debajo del límite de velocidad","Dejar que alguien use su licencia para comprar alcohol a un menor de 21","Olvidar renovar sus placas por un día"],"h1":"Se trata de usar mal su licencia.","h2":"En Minnesota, su licencia puede suspenderse si deja que alguien use su licencia, permiso o identificación para comprar alcohol a un menor de 21 o tabaco a un menor de 18.","p":"Correcto. Prestar su licencia para eso puede causar la suspensión."},"ref":{"doc":"MN","page":88}},{"id":"mn-116","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, you are convicted of not stopping for a school bus. Your license is suspended if you had the same conviction within how many years before?","o":["One year","Two years","Ten years","Five years"],"h1":"It is half of ten.","h2":"In Minnesota, your license may be suspended if you fail to stop for a school bus within five years of an earlier conviction for the same offense.","p":"Correct. Within five years."},"es":{"q":"En Minnesota, lo condenan por no detenerse ante un autobús escolar. Su licencia se suspende si tuvo la misma condena en cuántos años antes?","o":["Un año","Dos años","Diez años","Cinco años"],"h1":"Es la mitad de diez.","h2":"En Minnesota, su licencia puede suspenderse si no se detiene ante un autobús escolar dentro de cinco años de una condena anterior por lo mismo.","p":"Correcto. Dentro de cinco años."},"ref":{"doc":"MN","page":88}},{"id":"mn-117","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, which of these can lead to a license suspension?","o":["Being convicted of stealing gasoline","Getting a parking ticket","Driving with the radio on","Using cruise control"],"h1":"It is a theft linked to driving.","h2":"In Minnesota, a conviction for theft of gasoline can get your license suspended.","p":"Right. Gas theft can lead to a suspension."},"es":{"q":"En Minnesota, ¿cuál de estos puede llevar a la suspensión de la licencia?","o":["Ser condenado por robar gasolina","Recibir una multa de estacionamiento","Manejar con el radio encendido","Usar el control de crucero"],"h1":"Es un robo relacionado con manejar.","h2":"En Minnesota, una condena por robo de gasolina puede causar la suspensión de su licencia.","p":"Correcto. Robar gasolina puede llevar a una suspensión."},"ref":{"doc":"MN","page":89}},{"id":"mn-118","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, your license may be revoked if you plead guilty to how many jail-able traffic violations in one year?","o":["Two","Three","Five","Ten"],"h1":"It is a small number.","h2":"In Minnesota, your license may be revoked if you plead guilty or forfeit bail for three traffic violations in one year that require a jail sentence on conviction.","p":"Correct. Three such violations in one year."},"es":{"q":"En Minnesota, su licencia puede revocarse si se declara culpable de cuántas infracciones de tránsito con pena de cárcel en un año?","o":["Dos","Tres","Cinco","Diez"],"h1":"Es un número pequeño.","h2":"En Minnesota, su licencia puede revocarse si se declara culpable o pierde la fianza por tres infracciones de tránsito en un año que exigen cárcel al ser condenado.","p":"Correcto. Tres de esas infracciones en un año."},"ref":{"doc":"MN","page":89}},{"id":"mn-119","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you have a limited license after a revocation. Which trip is allowed?","o":["Driving to a friend's party","A weekend road trip","Driving to and from your job","Driving to a movie theater"],"h1":"A limited license covers needs, not fun.","h2":"In Minnesota, a limited license allows travel to and from work, treatment or counseling, a college where you are enrolled, and trips for dependents' medical, school or food needs.","p":"Right. Driving to and from work is allowed."},"es":{"q":"En Minnesota, usted tiene una licencia limitada después de una revocación. ¿Qué viaje está permitido?","o":["Ir a la fiesta de un amigo","Un viaje de fin de semana","Ir y volver de su trabajo","Ir al cine"],"h1":"La licencia limitada cubre necesidades, no diversión.","h2":"En Minnesota, una licencia limitada permite ir y volver del trabajo, del tratamiento o consejería, de la universidad donde estudia, y viajes por necesidades médicas, escolares o de alimentos de sus dependientes.","p":"Correcto. Ir y volver del trabajo está permitido."},"ref":{"doc":"MN","page":90}},{"id":"mn-120","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, your license is canceled because you gave false information on your application. How long does the cancellation last?","o":["7 days","30 days","One year","60 days or until you give the correct information, whichever is longer"],"h1":"It depends on when you fix it.","h2":"In Minnesota, false information on a license application leads to cancellation for 60 days or until you provide correct information, whichever is longer.","p":"Correct. At least 60 days, and until it is corrected."},"es":{"q":"En Minnesota, le cancelan la licencia por dar información falsa en su solicitud. ¿Cuánto dura la cancelación?","o":["7 días","30 días","Un año","60 días o hasta que dé la información correcta, lo que sea más largo"],"h1":"Depende de cuándo lo corrija.","h2":"En Minnesota, dar información falsa en la solicitud lleva a una cancelación de 60 días o hasta que dé la información correcta, lo que sea más largo.","p":"Correcto. Al menos 60 días, y hasta que se corrija."},"ref":{"doc":"MN","page":90}},{"id":"mn-121","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how many separate brake systems must every car and truck have?","o":["Two","One","Three","Four"],"h1":"Think of the foot brake and one more.","h2":"In Minnesota, all cars and trucks must have at least two separate brake systems, such as the foot brake and the parking brake.","p":"Right. At least two brake systems."},"es":{"q":"En Minnesota, ¿cuántos sistemas de frenos separados debe tener cada auto y camión?","o":["Dos","Uno","Tres","Cuatro"],"h1":"Piense en el freno de pie y uno más.","h2":"En Minnesota, todos los autos y camiones deben tener al menos dos sistemas de frenos separados, como el freno de pie y el freno de estacionamiento.","p":"Correcto. Al menos dos sistemas de frenos."},"ref":{"doc":"MN","page":22}},{"id":"mn-122","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, a pickup truck has a front bumper. What must it have at the back?","o":["Nothing is required","A rear bumper or reflectors","A tow hitch","A spare tire"],"h1":"Pickups have a choice for the rear.","h2":"In Minnesota, pickup trucks and vans must have front bumpers and either rear bumpers or reflectors.","p":"Correct. A rear bumper or reflectors."},"es":{"q":"En Minnesota, una camioneta pickup tiene defensa delantera. ¿Qué debe tener atrás?","o":["No se exige nada","Una defensa trasera o reflectores","Un enganche de remolque","Una llanta de repuesto"],"h1":"Las pickups tienen una opción para la parte trasera.","h2":"En Minnesota, las camionetas pickup y vans deben tener defensa delantera y defensa trasera o reflectores.","p":"Correcto. Defensa trasera o reflectores."},"ref":{"doc":"MN","page":22}},{"id":"mn-123","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, may you put a siren or a loud whistle on your private car as a horn?","o":["Yes, if it is not too loud","Yes, in rural areas","No, only emergency vehicles may use them","Only with a special permit from DVS"],"h1":"Those sounds are saved for one group of vehicles.","h2":"In Minnesota, bells, sirens and whistles are not horns, and only emergency vehicles may use them.","p":"Right. Only emergency vehicles may use sirens and whistles."},"es":{"q":"En Minnesota, ¿puede poner una sirena o un silbato fuerte en su auto particular como claxon?","o":["Sí, si no es muy fuerte","Sí, en zonas rurales","No, solo los vehículos de emergencia pueden usarlos","Solo con un permiso especial de DVS"],"h1":"Esos sonidos son para un solo tipo de vehículo.","h2":"En Minnesota, las campanas, sirenas y silbatos no son claxon, y solo los vehículos de emergencia pueden usarlos.","p":"Correcto. Solo los vehículos de emergencia pueden usar sirenas y silbatos."},"ref":{"doc":"MN","page":22}},{"id":"mn-124","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, how far ahead must your high beam headlights light up objects on the road?","o":["At least 100 feet","At least 200 feet","At least 1,000 feet","At least 350 feet"],"h1":"It is more than the length of a football field.","h2":"In Minnesota, high beam headlights must make objects on the road visible at least 350 feet ahead.","p":"Correct. At least 350 feet."},"es":{"q":"En Minnesota, ¿a qué distancia deben iluminar sus luces altas los objetos en el camino?","o":["Al menos 100 pies","Al menos 200 pies","Al menos 1,000 pies","Al menos 350 pies"],"h1":"Es más que el largo de una cancha de fútbol americano.","h2":"En Minnesota, las luces altas deben hacer visibles los objetos en el camino al menos a 350 pies.","p":"Correcto. Al menos 350 pies."},"ref":{"doc":"MN","page":23}},{"id":"mn-125","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, how much can dirty headlights cut the light they give?","o":["Up to 75 percent","Up to 5 percent","Up to 20 percent","They do not change the light"],"h1":"It is a large share, more than half.","h2":"In Minnesota, dirty headlights can reduce light output by up to 75 percent, so clean them as often as your windshield.","p":"Right. Up to 75 percent."},"es":{"q":"En Minnesota, ¿cuánto pueden reducir la luz unos faros sucios?","o":["Hasta 75 por ciento","Hasta 5 por ciento","Hasta 20 por ciento","No cambian la luz"],"h1":"Es una parte grande, más de la mitad.","h2":"En Minnesota, los faros sucios pueden reducir la luz hasta un 75 por ciento, así que límpielos tan seguido como el parabrisas.","p":"Correcto. Hasta 75 por ciento."},"ref":{"doc":"MN","page":23}},{"id":"mn-126","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, which vehicles may use blue lights?","o":["Any car at night","Snowplows, road maintenance equipment and emergency vehicles","Taxis and buses","Tow trucks only"],"h1":"Think of vehicles that clear winter roads, and emergencies.","h2":"In Minnesota, only snowplows, road maintenance equipment and authorized emergency vehicles may use blue lights.","p":"Correct. Snowplows, road maintenance and emergency vehicles."},"es":{"q":"En Minnesota, ¿qué vehículos pueden usar luces azules?","o":["Cualquier auto de noche","Quitanieves, equipo de mantenimiento de caminos y vehículos de emergencia","Taxis y autobuses","Solo grúas"],"h1":"Piense en los vehículos que limpian los caminos en invierno, y en las emergencias.","h2":"En Minnesota, solo los quitanieves, el equipo de mantenimiento de caminos y los vehículos de emergencia autorizados pueden usar luces azules.","p":"Correcto. Quitanieves, mantenimiento de caminos y vehículos de emergencia."},"ref":{"doc":"MN","page":23}},{"id":"mn-127","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, which of these vehicles may use strobe lamps?","o":["A pizza delivery car","A pickup truck towing a boat","A rural mail carrier's vehicle","Any car in fog"],"h1":"School buses and snow removal equipment may use them too.","h2":"In Minnesota, strobe lamps may be used only on school buses, snow removal equipment and rural mail carrier vehicles.","p":"Right. A rural mail carrier may use a strobe lamp."},"es":{"q":"En Minnesota, ¿cuál de estos vehículos puede usar luces estroboscópicas?","o":["Un auto que reparte pizza","Una pickup que remolca un bote","El vehículo de un cartero rural","Cualquier auto en la niebla"],"h1":"Los autobuses escolares y quitanieves también pueden usarlas.","h2":"En Minnesota, las luces estroboscópicas solo pueden usarse en autobuses escolares, equipo para quitar nieve y vehículos de carteros rurales.","p":"Correcto. Un cartero rural puede usar luz estroboscópica."},"ref":{"doc":"MN","page":23}},{"id":"mn-128","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, why must a pickup truck have an extra side mirror?","o":["To see the front bumper","To look at passengers","Because it has no horn","Because a load can block the rearview mirror"],"h1":"Pickups often haul things.","h2":"In Minnesota, pickup trucks must have an extra side mirror so you can see behind you when a load blocks the rearview mirror.","p":"Correct. A load may block the rearview mirror."},"es":{"q":"En Minnesota, ¿por qué una camioneta pickup debe tener un espejo lateral adicional?","o":["Para ver la defensa delantera","Para ver a los pasajeros","Porque no tiene claxon","Porque la carga puede tapar el espejo retrovisor"],"h1":"Las pickups suelen llevar carga.","h2":"En Minnesota, las pickups deben tener un espejo lateral extra para ver atrás cuando la carga tapa el espejo retrovisor.","p":"Correcto. La carga puede tapar el espejo retrovisor."},"ref":{"doc":"MN","page":23}},{"id":"mn-129","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, below what tread depth is a tire illegal?","o":["One-sixteenth of an inch","One-quarter of an inch","One-half of an inch","One inch"],"h1":"It is a very thin amount.","h2":"In Minnesota, a tire is illegal if its tread is less than one-sixteenth of an inch deep.","p":"Right. Less than 1/16 inch is illegal."},"es":{"q":"En Minnesota, ¿por debajo de qué profundidad de dibujo es ilegal una llanta?","o":["Un dieciseisavo de pulgada","Un cuarto de pulgada","Media pulgada","Una pulgada"],"h1":"Es una cantidad muy delgada.","h2":"En Minnesota, una llanta es ilegal si el dibujo tiene menos de un dieciseisavo de pulgada de profundidad.","p":"Correcto. Menos de 1/16 de pulgada es ilegal."},"ref":{"doc":"MN","page":24}},{"id":"mn-130","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, you do the penny test on your tire. When is the tread still legal?","o":["When you can see all of Lincoln's head","When part of Lincoln's head is covered by the tread","When the penny falls out","When the penny is shiny"],"h1":"Put Lincoln's head into the groove.","h2":"In Minnesota, if any part of Lincoln's head is covered by the tread in the penny test, your tires are legal.","p":"Correct. Part of the head is covered."},"es":{"q":"En Minnesota, hace la prueba del centavo en su llanta. ¿Cuándo es legal todavía el dibujo?","o":["Cuando se ve toda la cabeza de Lincoln","Cuando parte de la cabeza de Lincoln queda cubierta por el dibujo","Cuando el centavo se cae","Cuando el centavo brilla"],"h1":"Ponga la cabeza de Lincoln en la ranura.","h2":"En Minnesota, si alguna parte de la cabeza de Lincoln queda cubierta por el dibujo en la prueba del centavo, sus llantas son legales.","p":"Correcto. Parte de la cabeza queda cubierta."},"ref":{"doc":"MN","page":24}},{"id":"mn-131","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, when should you check your tire pressure?","o":["Right after a long drive","Only once a year","Before driving, or at least three hours after driving","Only when a warning light comes on"],"h1":"Tires should be cool.","h2":"In Minnesota, check tire pressure before driving or at least three hours after driving.","p":"Right. Check cold tires."},"es":{"q":"En Minnesota, ¿cuándo debe revisar la presión de las llantas?","o":["Justo después de un viaje largo","Solo una vez al año","Antes de manejar, o al menos tres horas después de manejar","Solo cuando se enciende una luz de aviso"],"h1":"Las llantas deben estar frías.","h2":"En Minnesota, revise la presión de las llantas antes de manejar o al menos tres horas después de manejar.","p":"Correcto. Revise las llantas frías."},"ref":{"doc":"MN","page":24}},{"id":"mn-132","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, about how much air pressure can a tire lose each month?","o":["None","Up to 10 PSI","Up to 5 PSI","Up to 1 PSI"],"h1":"It is a small amount, but it adds up.","h2":"In Minnesota, tires can lose up to 1 PSI of pressure each month, so check them often.","p":"Correct. Up to 1 PSI a month."},"es":{"q":"En Minnesota, ¿cuánta presión de aire puede perder una llanta cada mes?","o":["Nada","Hasta 10 PSI","Hasta 5 PSI","Hasta 1 PSI"],"h1":"Es poco, pero se acumula.","h2":"En Minnesota, las llantas pueden perder hasta 1 PSI de presión cada mes, así que revíselas seguido.","p":"Correcto. Hasta 1 PSI al mes."},"ref":{"doc":"MN","page":24}},{"id":"mn-133","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, where may you mount a GPS on the windshield?","o":["Near the bottom of the windshield","In the middle, in front of the driver","At the top, over the driver's eyes","Anywhere you like"],"h1":"It must not block your view of the road.","h2":"In Minnesota, GPS and other navigation devices may be mounted near the bottom of the windshield.","p":"Right. Near the bottom of the windshield."},"es":{"q":"En Minnesota, ¿dónde puede montar un GPS en el parabrisas?","o":["Cerca de la parte de abajo del parabrisas","En el centro, frente al conductor","Arriba, frente a los ojos del conductor","Donde usted quiera"],"h1":"No debe tapar su vista del camino.","h2":"En Minnesota, el GPS y otros aparatos de navegación pueden montarse cerca de la parte de abajo del parabrisas.","p":"Correcto. Cerca de la parte de abajo del parabrisas."},"ref":{"doc":"MN","page":24}},{"id":"mn-134","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, unless a sign says otherwise, what is the speed limit in an alley?","o":["5 mph","10 mph","15 mph","20 mph"],"h1":"It is very slow.","h2":"In Minnesota, the speed limit in alleys is 10 mph unless a sign says otherwise.","p":"Correct. Alleys are 10 mph."},"es":{"q":"En Minnesota, a menos que una señal indique otra cosa, ¿cuál es el límite de velocidad en un callejón?","o":["5 mph","10 mph","15 mph","20 mph"],"h1":"Es muy lento.","h2":"En Minnesota, el límite de velocidad en los callejones es de 10 mph, a menos que una señal indique otra cosa.","p":"Correcto. En callejones son 10 mph."},"ref":{"doc":"MN","page":26}},{"id":"mn-135","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, you drive on a rural two-lane road with no speed limit sign. What is the limit under the general rule?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is the usual rural highway limit.","h2":"In Minnesota, the speed limit is 55 mph in all other locations not listed, unless signs say otherwise.","p":"Right. Everywhere else it is 55 mph."},"es":{"q":"En Minnesota, maneja en un camino rural de dos carriles sin señal de velocidad. ¿Cuál es el límite según la regla general?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es el límite común en carreteras rurales.","h2":"En Minnesota, el límite es de 55 mph en todos los demás lugares no listados, a menos que las señales digan otra cosa.","p":"Correcto. En los demás lugares son 55 mph."},"ref":{"doc":"MN","page":26}},{"id":"mn-136","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, you drive toward an intersection faster than the speed limit. What happens to your right of way?","o":["Nothing changes","You gain the right of way","Other drivers must yield to you","You lose the right of way"],"h1":"Breaking the speed law has a cost.","h2":"In Minnesota, if you approach an intersection at an unlawful speed, you lose the right of way you would have had at a lawful speed.","p":"Correct. You lose the right of way."},"es":{"q":"En Minnesota, usted se acerca a una intersección más rápido que el límite. ¿Qué pasa con su derecho de paso?","o":["No cambia nada","Gana el derecho de paso","Los demás deben cederle el paso","Pierde el derecho de paso"],"h1":"Romper el límite tiene un costo.","h2":"En Minnesota, si se acerca a una intersección a una velocidad ilegal, pierde el derecho de paso que tendría a una velocidad legal.","p":"Correcto. Pierde el derecho de paso."},"ref":{"doc":"MN","page":26}},{"id":"mn-137","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, you get a ticket for not slowing down for a stopped emergency vehicle with flashing lights. What is added to the speeding fine?","o":["A surcharge of at least $25","Nothing extra","A $5 fee","A free warning"],"h1":"There is an added charge.","h2":"In Minnesota, a surcharge of at least $25 is added to the speeding fine if you do not slow down for a stopped emergency vehicle with flashing lights.","p":"Right. At least $25 is added."},"es":{"q":"En Minnesota, le multan por no reducir la velocidad ante un vehículo de emergencia detenido con luces. ¿Qué se agrega a la multa por velocidad?","o":["Un recargo de al menos $25","Nada adicional","Una tarifa de $5","Una advertencia gratis"],"h1":"Hay un cargo adicional.","h2":"En Minnesota, se agrega un recargo de al menos $25 a la multa por velocidad si no reduce la velocidad ante un vehículo de emergencia detenido con luces.","p":"Correcto. Se agregan al menos $25."},"ref":{"doc":"MN","page":27}},{"id":"mn-138","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, how much over the speed limit triggers additional speeding fines?","o":["5 mph or more","20 mph or more","Any amount over","50 mph or more"],"h1":"It is a big jump over the limit.","h2":"In Minnesota, additional fines apply if you drive 20 mph or more over the speed limit.","p":"Correct. 20 mph or more over brings extra fines."},"es":{"q":"En Minnesota, ¿cuánto sobre el límite de velocidad causa multas adicionales?","o":["5 mph o más","20 mph o más","Cualquier cantidad","50 mph o más"],"h1":"Es un salto grande sobre el límite.","h2":"En Minnesota, se aplican multas adicionales si maneja 20 mph o más sobre el límite de velocidad.","p":"Correcto. 20 mph o más sobre el límite trae multas extra."},"ref":{"doc":"MN","page":27}},{"id":"mn-139","scope":"MN","cat":"signals","sign":null,"c":2,"en":{"q":"In Minnesota, when may you NOT use hand and arm signals instead of your turn signals?","o":["In daylight","On a quiet street","At night","When your signals work"],"h1":"Others must be able to see your arm.","h2":"In Minnesota, you may use hand and arm signals during daylight, but not at night.","p":"Right. Do not use hand signals at night."},"es":{"q":"En Minnesota, ¿cuándo NO puede usar señales con la mano y el brazo en lugar de las direccionales?","o":["De día","En una calle tranquila","De noche","Cuando sus direccionales funcionan"],"h1":"Los demás deben poder ver su brazo.","h2":"En Minnesota, puede usar señales con la mano y el brazo de día, pero no de noche.","p":"Correcto. No use señales con la mano de noche."},"ref":{"doc":"MN","page":27}},{"id":"mn-140","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, you are stopped waiting to turn left. Why should you keep your front wheels straight?","o":["To save fuel","To turn faster","So the car behind can pass","So a rear-end hit does not push you into oncoming traffic"],"h1":"Think of what happens if someone hits you from behind.","h2":"In Minnesota, keep your wheels straight while waiting to turn left, so that if you are struck from behind you are less likely to be pushed into oncoming traffic.","p":"Correct. Straight wheels keep you out of oncoming traffic if you are hit."},"es":{"q":"En Minnesota, está detenido esperando para girar a la izquierda. ¿Por qué debe mantener las ruedas delanteras derechas?","o":["Para ahorrar gasolina","Para girar más rápido","Para que el auto de atrás pase","Para que un golpe por detrás no lo empuje hacia el tráfico de frente"],"h1":"Piense qué pasa si alguien lo choca por detrás.","h2":"En Minnesota, mantenga las ruedas derechas al esperar para girar a la izquierda, así si lo chocan por detrás es menos probable que lo empujen al tráfico de frente.","p":"Correcto. Las ruedas derechas lo protegen del tráfico de frente si lo chocan."},"ref":{"doc":"MN","page":28}},{"id":"mn-141","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, you are turning left on a green light with oncoming traffic. Where should you wait?","o":["Pulled into the intersection, with your body even with the curb line","Behind the stop line until traffic clears","In the crosswalk","In the oncoming lane"],"h1":"You move forward into the intersection a bit.","h2":"In Minnesota, when waiting to turn left on a green light with oncoming traffic, pull into the intersection so your body is even with the curb line.","p":"Right. Wait in the intersection, even with the curb line."},"es":{"q":"En Minnesota, va a girar a la izquierda con luz verde y hay tráfico de frente. ¿Dónde debe esperar?","o":["Dentro de la intersección, con su cuerpo alineado con la orilla de la banqueta","Detrás de la línea de alto hasta que pase el tráfico","En el cruce peatonal","En el carril contrario"],"h1":"Avanza un poco dentro de la intersección.","h2":"En Minnesota, al esperar para girar a la izquierda con luz verde y tráfico de frente, avance dentro de la intersección hasta que su cuerpo quede alineado con la orilla de la banqueta.","p":"Correcto. Espere dentro de la intersección, alineado con la orilla."},"ref":{"doc":"MN","page":28}},{"id":"mn-142","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, what may you do inside a roundabout?","o":["Pass the car ahead","Keep driving counterclockwise to your exit","Stop to let a friend out","Change lanes whenever you like"],"h1":"Once inside, keep moving.","h2":"In Minnesota, inside a roundabout you drive counterclockwise to your exit and do not stop, pass or change lanes.","p":"Correct. Keep going counterclockwise to your exit."},"es":{"q":"En Minnesota, ¿qué puede hacer dentro de una glorieta?","o":["Rebasar al auto de adelante","Seguir en sentido contrario a las manecillas del reloj hasta su salida","Detenerse para que baje un amigo","Cambiar de carril cuando quiera"],"h1":"Una vez dentro, siga avanzando.","h2":"En Minnesota, dentro de una glorieta maneja en sentido contrario a las manecillas del reloj hasta su salida y no se detiene, no rebasa ni cambia de carril.","p":"Correcto. Siga hasta su salida."},"ref":{"doc":"MN","page":30}},{"id":"mn-143","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, two large trucks drive through a multi-lane roundabout side by side. Who must yield?","o":["The truck on the left","The truck that is going faster","The truck on the right","Neither one"],"h1":"Think of the vehicle on the outside.","h2":"In Minnesota, when two large vehicles go through a multi-lane roundabout at the same time, the driver on the right must yield to the one on the left.","p":"Right. The truck on the right yields."},"es":{"q":"En Minnesota, dos camiones grandes pasan lado a lado por una glorieta de varios carriles. ¿Quién debe ceder el paso?","o":["El camión de la izquierda","El camión que va más rápido","El camión de la derecha","Ninguno"],"h1":"Piense en el vehículo de afuera.","h2":"En Minnesota, cuando dos vehículos grandes pasan a la vez por una glorieta de varios carriles, el conductor de la derecha debe ceder el paso al de la izquierda.","p":"Correcto. Cede el camión de la derecha."},"ref":{"doc":"MN","page":30}},{"id":"mn-144","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, a vehicle may leave its lane as needed to get through a roundabout if it is longer than how many feet?","o":["10 feet","20 feet","60 feet","40 feet"],"h1":"It is a long truck or bus.","h2":"In Minnesota, a vehicle longer than 40 feet or wider than 10 feet, or any combination vehicle, may leave its lane as needed in a roundabout.","p":"Correct. Longer than 40 feet."},"es":{"q":"En Minnesota, un vehículo puede salirse de su carril como sea necesario para pasar una glorieta si mide más de cuántos pies de largo?","o":["10 pies","20 pies","60 pies","40 pies"],"h1":"Es un camión o autobús largo.","h2":"En Minnesota, un vehículo de más de 40 pies de largo o más de 10 pies de ancho, o un vehículo combinado, puede salirse de su carril como sea necesario en una glorieta.","p":"Correcto. Más de 40 pies de largo."},"ref":{"doc":"MN","page":30}},{"id":"mn-145","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, you are on a side road at a J-turn and want to go left onto the divided highway. What do you do first?","o":["Stop, then turn right onto the highway","Turn left across both lanes","Drive straight across the median","Back up onto the shoulder"],"h1":"At a J-turn you never turn left from the side road.","h2":"In Minnesota, at a J-turn you stop, turn right onto the highway, then use the left-turn lane at the median opening to make a U-turn.","p":"Right. Stop and turn right first."},"es":{"q":"En Minnesota, está en un camino lateral en una vuelta en J (J-turn) y quiere ir a la izquierda en la carretera dividida. ¿Qué hace primero?","o":["Se detiene y luego gira a la derecha en la carretera","Gira a la izquierda cruzando ambos carriles","Cruza derecho el camellón","Da reversa al acotamiento"],"h1":"En una vuelta en J nunca gira a la izquierda desde el camino lateral.","h2":"En Minnesota, en una vuelta en J se detiene, gira a la derecha en la carretera y luego usa el carril de vuelta izquierda en la abertura del camellón para dar una vuelta en U.","p":"Correcto. Se detiene y gira primero a la derecha."},"ref":{"doc":"MN","page":32}},{"id":"mn-146","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, you are finishing the U-turn at a J-turn median opening. What must you do?","o":["Speed up to merge ahead of traffic","Yield to oncoming traffic and stop if needed","Honk and go","Use the shoulder to merge"],"h1":"You are entering fast through lanes.","h2":"In Minnesota, when completing the U-turn at a J-turn, you must yield to oncoming traffic and stop if needed before entering the through lanes.","p":"Correct. Yield, and stop if you must."},"es":{"q":"En Minnesota, está terminando la vuelta en U en la abertura del camellón de una vuelta en J. ¿Qué debe hacer?","o":["Acelerar para entrar antes que el tráfico","Ceder el paso al tráfico de frente y detenerse si es necesario","Tocar el claxon y avanzar","Usar el acotamiento para entrar"],"h1":"Va a entrar a carriles rápidos.","h2":"En Minnesota, al terminar la vuelta en U de una vuelta en J, debe ceder el paso al tráfico de frente y detenerse si es necesario antes de entrar a los carriles.","p":"Correcto. Ceda el paso y deténgase si debe."},"ref":{"doc":"MN","page":32}},{"id":"mn-147","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, you are crossing a rural divided highway with a wide median and wait in the middle. Where should you stop?","o":["Across both lanes of the median","On the left side of the median opening","To the right of the center of the median","On the shoulder of the far road"],"h1":"Keep room for cars turning from the other side.","h2":"In Minnesota, when waiting between the two roadways of a divided highway, stay to the right of the center of the median.","p":"Right. Wait to the right of center."},"es":{"q":"En Minnesota, cruza una carretera rural dividida con un camellón ancho y espera en medio. ¿Dónde debe detenerse?","o":["Atravesado en ambos carriles del camellón","Del lado izquierdo de la abertura","A la derecha del centro del camellón","En el acotamiento del otro camino"],"h1":"Deje espacio para quienes giran desde el otro lado.","h2":"En Minnesota, al esperar entre los dos caminos de una carretera dividida, quédese a la derecha del centro del camellón.","p":"Correcto. Espere a la derecha del centro."},"ref":{"doc":"MN","page":32}},{"id":"mn-148","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, near the top of a hill or on a curve, you may not make a U-turn if other drivers cannot see you from how far away?","o":["100 feet","300 feet","500 feet","1,000 feet"],"h1":"It is a long distance, more than three football fields.","h2":"In Minnesota, U-turns are illegal near hilltops and on curves where other drivers cannot see you from 1,000 feet away.","p":"Correct. 1,000 feet."},"es":{"q":"En Minnesota, cerca de la cima de una colina o en una curva, no puede dar vuelta en U si los demás no lo pueden ver desde qué distancia?","o":["100 pies","300 pies","500 pies","1,000 pies"],"h1":"Es una distancia larga, más de tres canchas de fútbol americano.","h2":"En Minnesota, las vueltas en U son ilegales cerca de la cima de colinas y en curvas donde otros conductores no lo ven desde 1,000 pies.","p":"Correcto. 1,000 pies."},"ref":{"doc":"MN","page":33}},{"id":"mn-149","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, on which road is a U-turn never allowed?","o":["An interstate freeway","A quiet two-lane road with a clear view","A city street with no sign against it","A divided road at a marked median opening"],"h1":"Think of the fastest roads.","h2":"In Minnesota, you must not make U-turns on interstate freeways.","p":"Right. No U-turns on interstate freeways."},"es":{"q":"En Minnesota, ¿en qué camino nunca se permite dar vuelta en U?","o":["Una autopista interestatal","Un camino tranquilo de dos carriles con buena vista","Una calle de ciudad sin señal que lo prohíba","Un camino dividido en una abertura marcada del camellón"],"h1":"Piense en los caminos más rápidos.","h2":"En Minnesota, no debe dar vueltas en U en autopistas interestatales.","p":"Correcto. Nada de vueltas en U en autopistas interestatales."},"ref":{"doc":"MN","page":33}},{"id":"mn-150","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, you need to make a U-turn on a road with two or more lanes your way. What may you do if needed?","o":["Back up across the lanes","Turn into the farthest lane and briefly use the shoulder","Stop in the middle lane for a minute","Drive over the curb"],"h1":"The law gives a little extra room.","h2":"In Minnesota, on a road with two or more lanes in the same direction, you may turn into the farthest lane and briefly use the shoulder to make a U-turn when needed.","p":"Correct. You may briefly use the shoulder."},"es":{"q":"En Minnesota, necesita dar una vuelta en U en un camino con dos o más carriles en su sentido. ¿Qué puede hacer si es necesario?","o":["Dar reversa cruzando los carriles","Girar al carril más lejano y usar brevemente el acotamiento","Detenerse un minuto en el carril central","Subirse a la banqueta"],"h1":"La ley da un poco de espacio extra.","h2":"En Minnesota, en un camino con dos o más carriles en el mismo sentido, puede girar al carril más lejano y usar brevemente el acotamiento para dar vuelta en U cuando sea necesario.","p":"Correcto. Puede usar brevemente el acotamiento."},"ref":{"doc":"MN","page":33}},{"id":"mn-151","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, you are on a highway with two lanes your way, cruising in the left lane, and a faster car comes up behind you. What should you do?","o":["Speed up to match it","Tap your brakes","Move out of the left lane when it is practical","Stay in the left lane"],"h1":"The left lane is not for cruising.","h2":"In Minnesota, on highways with more than one lane in your direction, drive in the right lane and move out of the left lane to let others pass when practical.","p":"Right. Move over to let the car pass."},"es":{"q":"En Minnesota, va por una carretera con dos carriles en su sentido, en el carril izquierdo, y un auto más rápido se acerca por detrás. ¿Qué debe hacer?","o":["Acelerar para igualarlo","Pisar el freno un poco","Salir del carril izquierdo cuando sea práctico","Quedarse en el carril izquierdo"],"h1":"El carril izquierdo no es para viajar.","h2":"En Minnesota, en carreteras con más de un carril en su sentido, maneje en el carril derecho y salga del izquierdo para dejar pasar cuando sea práctico.","p":"Correcto. Muévase para dejar pasar al auto."},"ref":{"doc":"MN","page":33}},{"id":"mn-152","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, after passing on a two-lane road, you must be back in the right lane before you come within how many feet of an oncoming vehicle?","o":["20 feet","50 feet","500 feet","100 feet"],"h1":"It is the same number used near intersections.","h2":"In Minnesota, you must return to the right side of the road before coming within 100 feet of an oncoming vehicle.","p":"Correct. Before 100 feet."},"es":{"q":"En Minnesota, después de rebasar en un camino de dos carriles, debe estar de vuelta en el carril derecho antes de quedar a cuántos pies de un vehículo de frente?","o":["20 pies","50 pies","500 pies","100 pies"],"h1":"Es el mismo número que se usa cerca de intersecciones.","h2":"En Minnesota, debe regresar al lado derecho del camino antes de quedar a 100 pies de un vehículo que viene de frente.","p":"Correcto. Antes de 100 pies."},"ref":{"doc":"MN","page":34}},{"id":"mn-153","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, on a hill or curve, you may not pass unless you can clearly see the road ahead for at least how far?","o":["700 feet","200 feet","350 feet","1,500 feet"],"h1":"It is a little more than the length of two football fields.","h2":"In Minnesota, do not pass on a curve or hill where you cannot clearly see the road ahead for at least 700 feet.","p":"Right. You need at least 700 feet of clear view."},"es":{"q":"En Minnesota, en una colina o curva, no puede rebasar a menos que vea claramente el camino adelante por al menos qué distancia?","o":["700 pies","200 pies","350 pies","1,500 pies"],"h1":"Es un poco más que el largo de dos campos de fútbol americano.","h2":"En Minnesota, no rebase en una curva o colina donde no pueda ver claramente el camino al menos 700 pies adelante.","p":"Correcto. Necesita al menos 700 pies de vista clara."},"ref":{"doc":"MN","page":34}},{"id":"mn-154","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, after passing a car, when may you move back into the right lane?","o":["As soon as your front bumper is past it","When you can see the whole car you passed in your rearview mirror","After you count to two","When the other driver flashes the headlights"],"h1":"Use your inside mirror.","h2":"In Minnesota, return to the right lane when you can see the entire vehicle you just passed in your rearview mirror.","p":"Correct. When the whole car shows in your rearview mirror."},"es":{"q":"En Minnesota, después de rebasar un auto, ¿cuándo puede volver al carril derecho?","o":["En cuanto su defensa delantera lo pase","Cuando vea todo el auto que rebasó en su espejo retrovisor","Después de contar hasta dos","Cuando el otro conductor le haga cambio de luces"],"h1":"Use el espejo de adentro.","h2":"En Minnesota, regrese al carril derecho cuando vea todo el vehículo que rebasó en su espejo retrovisor.","p":"Correcto. Cuando todo el auto aparezca en el espejo retrovisor."},"ref":{"doc":"MN","page":34}},{"id":"mn-155","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, the car ahead is turning left. You want to pass it on the right. Which of these is NOT allowed?","o":["Passing in a lane meant for traffic","Waiting behind it","Passing by driving on the shoulder or in a bike lane","Slowing down until it turns"],"h1":"You must stay on the main part of the road.","h2":"In Minnesota, you may pass on the right only when it is safe, and never by driving on the shoulder, in a bicycle lane or off the pavement.","p":"Right. Do not pass on the shoulder or in a bike lane."},"es":{"q":"En Minnesota, el auto de adelante va a girar a la izquierda y usted quiere rebasarlo por la derecha. ¿Qué NO está permitido?","o":["Rebasar en un carril para el tráfico","Esperar detrás de él","Rebasar por el acotamiento o por un carril de bicicletas","Reducir la velocidad hasta que gire"],"h1":"Debe quedarse en la parte principal del camino.","h2":"En Minnesota, puede rebasar por la derecha solo cuando es seguro, y nunca por el acotamiento, por un carril de bicicletas ni fuera del pavimento.","p":"Correcto. No rebase por el acotamiento ni por el carril de bicicletas."},"ref":{"doc":"MN","page":34}},{"id":"mn-156","scope":"MN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Minnesota, you must back out of a driveway onto a public road. Where should you back into?","o":["Across all lanes to the far side","Onto the sidewalk","Into the center turn lane","Into the nearest lane, then drive forward"],"h1":"Keep the backing short.","h2":"In Minnesota, when backing out of a driveway onto a public road, back into the nearest lane and drive forward from there.","p":"Correct. Back into the nearest lane."},"es":{"q":"En Minnesota, debe salir en reversa de una entrada a un camino público. ¿Hacia dónde debe dar reversa?","o":["Cruzando todos los carriles hasta el otro lado","Hacia la banqueta","Hacia el carril central de vuelta","Hacia el carril más cercano, y luego avanzar"],"h1":"Haga la reversa corta.","h2":"En Minnesota, al salir en reversa de una entrada a un camino público, dé reversa al carril más cercano y avance desde ahí.","p":"Correcto. Reversa al carril más cercano."},"ref":{"doc":"MN","page":34}},{"id":"mn-157","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, which of these is a place where you may never park?","o":["On a bridge","On a residential street with no signs","In a marked parking stall","In your own driveway"],"h1":"Think of a structure over water or a road.","h2":"In Minnesota, parking is not allowed on any bridge or in any highway tunnel.","p":"Right. You may not park on a bridge."},"es":{"q":"En Minnesota, ¿en cuál de estos lugares nunca puede estacionarse?","o":["En un puente","En una calle residencial sin señales","En un espacio marcado de estacionamiento","En la entrada de su casa"],"h1":"Piense en una estructura sobre agua o sobre un camino.","h2":"En Minnesota, no se permite estacionarse en ningún puente ni en ningún túnel de carretera.","p":"Correcto. No puede estacionarse en un puente."},"ref":{"doc":"MN","page":35}},{"id":"mn-158","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, what is \"double parking\"?","o":["Parking across two spaces","Parking on the traffic side of a car already parked at the curb","Parking for more than two hours","Parking two cars in one driveway"],"h1":"It blocks a traffic lane.","h2":"In Minnesota, double parking means parking on the traffic side of a vehicle already parked at the curb, and it is not allowed.","p":"Correct. It is parking beside a parked car, in traffic."},"es":{"q":"En Minnesota, ¿qué es \"estacionarse en doble fila\"?","o":["Ocupar dos espacios","Estacionarse del lado del tráfico junto a un auto ya estacionado en la orilla","Estacionarse más de dos horas","Poner dos autos en una entrada"],"h1":"Bloquea un carril de tráfico.","h2":"En Minnesota, estacionarse en doble fila es parar del lado del tráfico junto a un vehículo ya estacionado en la orilla, y no está permitido.","p":"Correcto. Es estacionarse junto a un auto estacionado, en el tráfico."},"ref":{"doc":"MN","page":35}},{"id":"mn-159","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, you must park on a highway at night. Your lights must be seen from at least how far?","o":["50 feet","100 feet","500 feet","2,000 feet"],"h1":"It is the same distance used for headlights in bad weather.","h2":"In Minnesota, a vehicle parked on a highway at night must show at least one white or amber light in front and one red light in back, both visible from at least 500 feet.","p":"Right. At least 500 feet."},"es":{"q":"En Minnesota, debe estacionarse en una carretera de noche. ¿Desde qué distancia mínima deben verse sus luces?","o":["50 pies","100 pies","500 pies","2,000 pies"],"h1":"Es la misma distancia que se usa para los faros con mal tiempo.","h2":"En Minnesota, un vehículo estacionado en una carretera de noche debe mostrar al menos una luz blanca o ámbar adelante y una roja atrás, visibles desde al menos 500 pies.","p":"Correcto. Al menos 500 pies."},"ref":{"doc":"MN","page":37}},{"id":"mn-160","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, may a police officer stop you only because you are not wearing a seat belt?","o":["No, only with another violation","Only at night","Only on highways","Yes, a seat belt violation alone is enough"],"h1":"Minnesota's seat belt law is a primary law.","h2":"In Minnesota, law enforcement can stop drivers solely for seat belt violations.","p":"Correct. Not wearing a seat belt is enough for a stop."},"es":{"q":"En Minnesota, ¿puede un policía detenerlo solo por no usar el cinturón de seguridad?","o":["No, solo si hay otra infracción","Solo de noche","Solo en carreteras","Sí, basta con no usar el cinturón"],"h1":"La ley del cinturón en Minnesota es una ley primaria.","h2":"En Minnesota, la policía puede detener a los conductores solo por no usar el cinturón de seguridad.","p":"Correcto. No usar el cinturón basta para que lo detengan."},"ref":{"doc":"MN","page":37}},{"id":"mn-161","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, who is NOT required by law to wear a seat belt?","o":["A driver of a car made before January 1, 1965","A back-seat passenger","A driver on a short trip","A front passenger over 65"],"h1":"It depends on how old the vehicle is.","h2":"In Minnesota, among the few exceptions, a person driving a vehicle made before January 1, 1965, is not required to wear a seat belt.","p":"Right. Vehicles made before 1965 are an exception."},"es":{"q":"En Minnesota, ¿quién NO está obligado por ley a usar cinturón de seguridad?","o":["El conductor de un auto fabricado antes del 1 de enero de 1965","Un pasajero del asiento trasero","Un conductor en un viaje corto","Un pasajero delantero mayor de 65"],"h1":"Depende de la antigüedad del vehículo.","h2":"En Minnesota, entre las pocas excepciones, quien maneja un vehículo fabricado antes del 1 de enero de 1965 no está obligado a usar cinturón.","p":"Correcto. Los vehículos fabricados antes de 1965 son una excepción."},"ref":{"doc":"MN","page":37}},{"id":"mn-162","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, a worker gets in and out of the vehicle often for the job. When is the worker excused from wearing a seat belt?","o":["Always","When not driving faster than 25 mph","Only on weekends","Only on gravel roads"],"h1":"There is a speed limit on this exception.","h2":"In Minnesota, a person whose work involves getting in and out of the vehicle often is excused from the seat belt law only while not driving faster than 25 mph.","p":"Correct. Only at 25 mph or less."},"es":{"q":"En Minnesota, un trabajador entra y sale del vehículo seguido por su trabajo. ¿Cuándo no necesita usar cinturón?","o":["Siempre","Cuando no maneja a más de 25 mph","Solo los fines de semana","Solo en caminos de grava"],"h1":"Esta excepción tiene un límite de velocidad.","h2":"En Minnesota, quien entra y sale del vehículo seguido por su trabajo no necesita cinturón solo mientras no maneje a más de 25 mph.","p":"Correcto. Solo a 25 mph o menos."},"ref":{"doc":"MN","page":37}},{"id":"mn-163","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, without a seat belt, how low can the speed be and still kill you in a crash?","o":["Only above 55 mph","Only above 30 mph","As low as 12 mph","Only above 70 mph"],"h1":"It is slower than a bicycle can go.","h2":"In Minnesota, the manual warns that without a seat belt you can be killed in a crash at speeds as low as 12 mph.","p":"Right. As low as 12 mph."},"es":{"q":"En Minnesota, sin cinturón de seguridad, ¿a qué velocidad tan baja puede morir en un choque?","o":["Solo a más de 55 mph","Solo a más de 30 mph","A tan solo 12 mph","Solo a más de 70 mph"],"h1":"Es más lento de lo que puede ir una bicicleta.","h2":"En Minnesota, el manual advierte que sin cinturón puede morir en un choque a velocidades de tan solo 12 mph.","p":"Correcto. A tan solo 12 mph."},"ref":{"doc":"MN","page":37}},{"id":"mn-164","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, children under what age must ride in the back seat if one is available?","o":["8","10","16","13"],"h1":"It is the start of the teen years.","h2":"In Minnesota, children under 13 must ride in the back seat if one is available.","p":"Correct. Under 13 rides in the back."},"es":{"q":"En Minnesota, ¿los niños menores de qué edad deben ir en el asiento trasero si hay uno?","o":["8","10","16","13"],"h1":"Es el inicio de la adolescencia.","h2":"En Minnesota, los niños menores de 13 años deben ir en el asiento trasero si hay uno disponible.","p":"Correcto. Los menores de 13 van atrás."},"ref":{"doc":"MN","page":38}},{"id":"mn-165","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, a 6-year-old has outgrown the car seat. What must the child use?","o":["A booster seat with a safety belt","Only the adult seat belt","No restraint in the back seat","An adult's lap"],"h1":"Children from 4 to 9 need extra height.","h2":"In Minnesota, a child from 4 to 9 years old who is too big for a car seat must use a booster seat with a safety belt.","p":"Right. A booster seat with a belt."},"es":{"q":"En Minnesota, un niño de 6 años ya no cabe en su silla de auto. ¿Qué debe usar?","o":["Un asiento elevado (booster) con cinturón","Solo el cinturón de adulto","Nada en el asiento trasero","Las piernas de un adulto"],"h1":"Los niños de 4 a 9 años necesitan altura extra.","h2":"En Minnesota, un niño de 4 a 9 años que ya no cabe en la silla de auto debe usar un asiento elevado con cinturón de seguridad.","p":"Correcto. Un asiento elevado con cinturón."},"ref":{"doc":"MN","page":38}},{"id":"mn-166","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, at what age may a child stop using a booster seat and use just the seat belt?","o":["6","9","12","13"],"h1":"It is the top of the booster age range.","h2":"In Minnesota, when a child is 9 years old or outgrows the booster seat, the child may sit without it and use the seat belt.","p":"Correct. At age 9, or when the booster is outgrown."},"es":{"q":"En Minnesota, ¿a qué edad puede un niño dejar el asiento elevado y usar solo el cinturón?","o":["6","9","12","13"],"h1":"Es la edad más alta del rango del asiento elevado.","h2":"En Minnesota, cuando un niño cumple 9 años o ya no cabe en el asiento elevado, puede ir sin él y usar el cinturón de seguridad.","p":"Correcto. A los 9 años, o cuando ya no cabe en el asiento elevado."},"ref":{"doc":"MN","page":38}},{"id":"mn-167","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, a 1-year-old rides in a car. How must the child ride?","o":["In a forward-facing booster","On a parent's lap","In a rear-facing car seat","With the adult seat belt"],"h1":"Babies face the back.","h2":"In Minnesota, children under 2 must ride in a rear-facing car seat until they reach the seat's height or weight limit.","p":"Right. Rear-facing."},"es":{"q":"En Minnesota, un niño de 1 año viaja en auto. ¿Cómo debe ir?","o":["En un asiento elevado mirando hacia adelante","En las piernas de un padre","En una silla de auto mirando hacia atrás","Con el cinturón de adulto"],"h1":"Los bebés miran hacia atrás.","h2":"En Minnesota, los niños menores de 2 años deben ir en una silla mirando hacia atrás hasta llegar al límite de altura o peso de la silla.","p":"Correcto. Mirando hacia atrás."},"ref":{"doc":"MN","page":38}},{"id":"mn-168","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, a child car seat has no expiration date stamped on it. How long after it was made should you stop using it?","o":["1 year","3 years","10 years","6 years"],"h1":"It is more than five years.","h2":"In Minnesota, child restraint systems expire six years from the date they were made if no other date is listed.","p":"Correct. Six years from manufacture."},"es":{"q":"En Minnesota, una silla de auto para niños no tiene fecha de vencimiento marcada. ¿Cuánto tiempo después de fabricada debe dejar de usarla?","o":["1 año","3 años","10 años","6 años"],"h1":"Son más de cinco años.","h2":"En Minnesota, las sillas de seguridad para niños vencen seis años después de su fabricación si no tienen otra fecha.","p":"Correcto. Seis años desde su fabricación."},"ref":{"doc":"MN","page":38}},{"id":"mn-169","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, to stay safe from the air bag, how far should you sit from the steering wheel?","o":["At least 10 inches","At least 2 inches","At least 5 inches","At least 3 feet"],"h1":"It is about the length of a ruler, a little less.","h2":"In Minnesota, try to keep at least 10 inches between yourself and the steering wheel because of the air bag.","p":"Right. At least 10 inches."},"es":{"q":"En Minnesota, para protegerse de la bolsa de aire, ¿a qué distancia debe sentarse del volante?","o":["Al menos 10 pulgadas","Al menos 2 pulgadas","Al menos 5 pulgadas","Al menos 3 pies"],"h1":"Es un poco menos que el largo de una regla.","h2":"En Minnesota, trate de mantener al menos 10 pulgadas entre usted y el volante por la bolsa de aire.","p":"Correcto. Al menos 10 pulgadas."},"ref":{"doc":"MN","page":39}},{"id":"mn-170","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, which hand position on the steering wheel should you avoid because of the air bag?","o":["9 and 3 o'clock","10 and 2 o'clock","8 and 4 o'clock","Both hands low on the sides"],"h1":"It is the old high position.","h2":"In Minnesota, keep your hands at 8 and 4 or 9 and 3 o'clock and avoid the 10 and 2 o'clock position.","p":"Correct. Avoid 10 and 2."},"es":{"q":"En Minnesota, ¿qué posición de manos en el volante debe evitar por la bolsa de aire?","o":["Las 9 y las 3","Las 10 y las 2","Las 8 y las 4","Ambas manos abajo a los lados"],"h1":"Es la posición alta antigua.","h2":"En Minnesota, mantenga las manos en las 8 y las 4 o en las 9 y las 3, y evite la posición de las 10 y las 2.","p":"Correcto. Evite las 10 y las 2."},"ref":{"doc":"MN","page":39}},{"id":"mn-171","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, you have a crash that only damaged the cars, and no one is hurt. Must you notify the police?","o":["Yes, always within 24 hours","Yes, within 10 days in writing","No, you do not need to notify law enforcement","Only if the other driver asks"],"h1":"Injuries change the rule.","h2":"In Minnesota, if a crash causes only property damage, you do not need to notify law enforcement.","p":"Right. Property-damage-only crashes do not have to be reported to police."},"es":{"q":"En Minnesota, tiene un choque que solo dañó los autos y nadie está herido. ¿Debe avisar a la policía?","o":["Sí, siempre en 24 horas","Sí, por escrito en 10 días","No, no necesita avisar a la policía","Solo si el otro conductor lo pide"],"h1":"Las lesiones cambian la regla.","h2":"En Minnesota, si un choque solo causa daños materiales, no necesita avisar a la policía.","p":"Correcto. Los choques solo con daños materiales no tienen que reportarse a la policía."},"ref":{"doc":"MN","page":39}},{"id":"mn-172","scope":"MN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Minnesota, right after a crash, why should you turn off the ignition?","o":["To save fuel","To keep the radio quiet","To lock the doors","To lower the risk of fire"],"h1":"Leaking fuel is a danger.","h2":"In Minnesota, after a crash you should stop, move out of the lane if possible and turn off the ignition to reduce the risk of fire.","p":"Correct. It lowers the risk of fire."},"es":{"q":"En Minnesota, justo después de un choque, ¿por qué debe apagar el motor?","o":["Para ahorrar gasolina","Para callar el radio","Para cerrar las puertas","Para bajar el riesgo de incendio"],"h1":"La gasolina derramada es un peligro.","h2":"En Minnesota, después de un choque debe detenerse, salir del carril si es posible y apagar el motor para reducir el riesgo de incendio.","p":"Correcto. Baja el riesgo de incendio."},"ref":{"doc":"MN","page":39}},{"id":"mn-173","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, on a road with a 50 mph speed limit, how far before a stop does a school bus driver turn on the flashing yellow lights?","o":["At least 300 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"Faster roads need more warning.","h2":"In Minnesota, a school bus turns on its flashing yellow lights at least 300 feet before stopping where the speed limit is over 35 mph, and at least 100 feet where it is 35 mph or less.","p":"Right. At least 300 feet on faster roads."},"es":{"q":"En Minnesota, en un camino con límite de 50 mph, ¿a qué distancia antes de parar enciende el chofer del autobús escolar las luces amarillas intermitentes?","o":["Al menos 300 pies","Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"Los caminos más rápidos necesitan más aviso.","h2":"En Minnesota, el autobús escolar enciende las luces amarillas intermitentes al menos 300 pies antes de parar donde el límite es de más de 35 mph, y al menos 100 pies donde es de 35 mph o menos.","p":"Correcto. Al menos 300 pies en caminos más rápidos."},"ref":{"doc":"MN","page":41}},{"id":"mn-174","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, you stopped behind a school bus with flashing red lights. When may you go?","o":["When the children reach the sidewalk","When the red lights stop flashing","After 30 seconds","When the bus driver waves"],"h1":"Watch the lights, not the clock.","h2":"In Minnesota, whether you face the front or the back of the bus, you must stay stopped until the red lights stop flashing.","p":"Correct. Wait until the red lights stop flashing."},"es":{"q":"En Minnesota, se detuvo detrás de un autobús escolar con luces rojas intermitentes. ¿Cuándo puede avanzar?","o":["Cuando los niños llegan a la banqueta","Cuando las luces rojas dejan de parpadear","Después de 30 segundos","Cuando el chofer le hace señas"],"h1":"Fíjese en las luces, no en el reloj.","h2":"En Minnesota, ya sea que esté frente o detrás del autobús, debe quedarse detenido hasta que las luces rojas dejen de parpadear.","p":"Correcto. Espere hasta que las luces rojas se apaguen."},"ref":{"doc":"MN","page":42}},{"id":"mn-175","scope":"MN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Minnesota, a student safety patrol is helping children cross the street ahead. What must you do?","o":["Slow down and drive around them","Honk so they hurry","Come to a complete stop","Pass if no adult is present"],"h1":"Treat them like a crossing guard.","h2":"In Minnesota, you must come to a complete stop for a student safety patrol helping students cross, and you may never drive through a line of children crossing.","p":"Right. Stop completely."},"es":{"q":"En Minnesota, una patrulla escolar de estudiantes ayuda a los niños a cruzar la calle adelante. ¿Qué debe hacer?","o":["Bajar la velocidad y rodearlos","Tocar el claxon para que se apuren","Detenerse por completo","Pasar si no hay un adulto"],"h1":"Trátelos como a un guardia de cruce.","h2":"En Minnesota, debe detenerse por completo ante una patrulla escolar que ayuda a cruzar a los estudiantes, y nunca puede pasar por una fila de niños que cruzan.","p":"Correcto. Deténgase por completo."},"ref":{"doc":"MN","page":43}},{"id":"mn-176","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, you are in the right lane and a city transit bus signals to pull out from a bus stop. What must you do?","o":["Speed up to pass it","Honk and keep going","Change lanes without signaling","Yield and let the bus merge"],"h1":"Buses get help to rejoin traffic.","h2":"In Minnesota, when you drive in the right lane you must yield to transit and metro mobility buses merging from a bus stop or the shoulder.","p":"Correct. Yield to the bus."},"es":{"q":"En Minnesota, va en el carril derecho y un autobús urbano pone la direccional para salir de una parada. ¿Qué debe hacer?","o":["Acelerar para rebasarlo","Tocar el claxon y seguir","Cambiar de carril sin señalar","Cederle el paso y dejar que entre"],"h1":"Los autobuses reciben ayuda para volver al tráfico.","h2":"En Minnesota, cuando va en el carril derecho debe ceder el paso a los autobuses de transporte público y de metro mobility que salen de una parada o del acotamiento.","p":"Correcto. Ceda el paso al autobús."},"ref":{"doc":"MN","page":43}},{"id":"mn-177","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, an ambulance with siren and lights comes toward you on the other side of a fence or wall that divides the road. Must you pull over and stop?","o":["No, not when a physical barrier separates you","Yes, always","Yes, but only at night","Only if it is a fire truck"],"h1":"Look at what separates the lanes.","h2":"In Minnesota, you do not need to stop for an emergency vehicle that is separated from your lane by a physical barrier such as a fence, wall or median strip.","p":"Right. A physical barrier means you do not have to stop."},"es":{"q":"En Minnesota, una ambulancia con sirena y luces viene hacia usted al otro lado de una cerca o muro que divide el camino. ¿Debe orillarse y detenerse?","o":["No, no cuando una barrera física los separa","Sí, siempre","Sí, pero solo de noche","Solo si es un camión de bomberos"],"h1":"Fíjese en lo que separa los carriles.","h2":"En Minnesota, no necesita detenerse por un vehículo de emergencia separado de su carril por una barrera física, como una cerca, un muro o un camellón.","p":"Correcto. Con una barrera física no tiene que detenerse."},"ref":{"doc":"MN","page":44}},{"id":"mn-178","scope":"MN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Minnesota, a fire hose lies across the street and no one is guarding it. May you drive over it?","o":["Yes, if you go slowly","Only if a police officer or fire official tells you to","Yes, if no fire truck is near","Yes, on a one-way street"],"h1":"Firefighters need the hose to work.","h2":"In Minnesota, do not drive over an unprotected fire hose unless a law enforcement officer or fire department official directs you.","p":"Correct. Only when an officer or fire official tells you."},"es":{"q":"En Minnesota, una manguera de bomberos cruza la calle y nadie la protege. ¿Puede pasar por encima?","o":["Sí, si va despacio","Solo si un policía o un oficial de bomberos se lo indica","Sí, si no hay camión de bomberos cerca","Sí, en una calle de un sentido"],"h1":"Los bomberos necesitan la manguera para trabajar.","h2":"En Minnesota, no pase por encima de una manguera de bomberos sin protección a menos que un policía o un oficial de bomberos se lo indique.","p":"Correcto. Solo cuando un policía o un bombero se lo indique."},"ref":{"doc":"MN","page":44}},{"id":"mn-179","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, what kind of crime is fleeing a police officer in a motor vehicle?","o":["A petty misdemeanor","A parking violation","A felony","No crime if no one is hurt"],"h1":"It is the most serious class of crime.","h2":"In Minnesota, fleeing a police officer in a vehicle is a felony, with up to three years and one day in prison, a fine up to $5,000, or both.","p":"Right. It is a felony."},"es":{"q":"En Minnesota, ¿qué tipo de delito es huir de un policía en un vehículo?","o":["Una falta menor","Una infracción de estacionamiento","Un delito grave (felony)","No es delito si nadie sale herido"],"h1":"Es la clase de delito más seria.","h2":"En Minnesota, huir de un policía en un vehículo es un delito grave, con hasta tres años y un día de prisión, una multa de hasta $5,000, o ambas.","p":"Correcto. Es un delito grave."},"ref":{"doc":"MN","page":46}},{"id":"mn-180","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, a car in the next lane has stopped at a crosswalk. What must you do?","o":["Pass it carefully","Honk to warn people","Change lanes and keep going","Do not pass it; look for people crossing and be ready to stop"],"h1":"Someone may be walking in front of that car.","h2":"In Minnesota, it is illegal to pass a vehicle that has stopped for a pedestrian; look for people in the crosswalk and be ready to stop.","p":"Correct. Do not pass the stopped car."},"es":{"q":"En Minnesota, un auto en el carril de al lado se detuvo en un cruce peatonal. ¿Qué debe hacer?","o":["Rebasarlo con cuidado","Tocar el claxon para avisar","Cambiar de carril y seguir","No rebasarlo; buscar peatones y estar listo para parar"],"h1":"Alguien puede estar cruzando frente a ese auto.","h2":"En Minnesota, es ilegal rebasar a un vehículo que se detuvo por un peatón; busque personas en el cruce y esté listo para parar.","p":"Correcto. No rebase al auto detenido."},"ref":{"doc":"MN","page":47}},{"id":"mn-181","scope":"MN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Minnesota, when may you drive in a bicycle lane?","o":["To prepare for a turn, after yielding to bicyclists","To pass slow traffic","Whenever no bicycles are in sight","During rush hour"],"h1":"There are only a few reasons.","h2":"In Minnesota, you may drive in a bicycle lane only to park where allowed, to enter or leave the road, or to prepare for a turn, after yielding to bicyclists.","p":"Right. To prepare for a turn, after yielding."},"es":{"q":"En Minnesota, ¿cuándo puede manejar en un carril de bicicletas?","o":["Para prepararse a girar, después de ceder el paso a los ciclistas","Para rebasar tráfico lento","Siempre que no se vean bicicletas","En las horas pico"],"h1":"Solo hay unas pocas razones.","h2":"En Minnesota, puede manejar en un carril de bicicletas solo para estacionarse donde se permite, para entrar o salir del camino, o para prepararse a girar, después de ceder el paso a los ciclistas.","p":"Correcto. Para prepararse a girar, después de ceder el paso."},"ref":{"doc":"MN","page":48}},{"id":"mn-182","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, you are behind a bicyclist in a no-passing zone. May you cross the center line to pass?","o":["No, never in a no-passing zone","Yes, when it is safe to do so","Only if the cyclist waves you on","Only on a weekend"],"h1":"The law makes a special allowance for bicycles.","h2":"In Minnesota, you may cross the center of the road to pass a bicyclist, even in a no-passing zone, when it is safe.","p":"Correct. Yes, when it is safe."},"es":{"q":"En Minnesota, va detrás de un ciclista en una zona donde no se permite rebasar. ¿Puede cruzar la línea central para rebasarlo?","o":["No, nunca en una zona de no rebasar","Sí, cuando sea seguro hacerlo","Solo si el ciclista le hace señas","Solo los fines de semana"],"h1":"La ley hace una excepción especial para las bicicletas.","h2":"En Minnesota, puede cruzar el centro del camino para rebasar a un ciclista, aun en zona de no rebasar, cuando sea seguro.","p":"Correcto. Sí, cuando sea seguro."},"ref":{"doc":"MN","page":48}},{"id":"mn-183","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, a motorcycle may split lanes between moving cars only at what speed?","o":["No more than 25 mph","No more than 45 mph","No more than 55 mph","Any speed"],"h1":"It is a low city speed.","h2":"In Minnesota, a motorcycle may lane split at no more than 25 mph and no more than 15 mph faster than the traffic around it.","p":"Right. No more than 25 mph."},"es":{"q":"En Minnesota, una motocicleta puede pasar entre carriles de autos en movimiento solo a qué velocidad?","o":["No más de 25 mph","No más de 45 mph","No más de 55 mph","A cualquier velocidad"],"h1":"Es una velocidad baja de ciudad.","h2":"En Minnesota, una motocicleta puede pasar entre carriles a no más de 25 mph y no más de 15 mph más rápido que el tráfico.","p":"Correcto. No más de 25 mph."},"ref":{"doc":"MN","page":50}},{"id":"mn-184","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, on which streets may a neighborhood electric vehicle (NEV) be driven?","o":["Any road, including freeways","Only streets with a speed limit of 35 mph or less","Only sidewalks","Only private roads"],"h1":"NEVs reach only 20 to 25 mph.","h2":"In Minnesota, anyone with a Class D license may drive an NEV, but only on streets with speed limits of 35 mph or less.","p":"Correct. Only on streets posted 35 mph or less."},"es":{"q":"En Minnesota, ¿en qué calles puede manejarse un vehículo eléctrico de vecindario (NEV)?","o":["En cualquier camino, incluso autopistas","Solo en calles con límite de 35 mph o menos","Solo en banquetas","Solo en caminos privados"],"h1":"Los NEV solo llegan a 20 o 25 mph.","h2":"En Minnesota, cualquiera con licencia Clase D puede manejar un NEV, pero solo en calles con límite de 35 mph o menos.","p":"Correcto. Solo en calles de 35 mph o menos."},"ref":{"doc":"MN","page":51}},{"id":"mn-185","scope":"MN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Minnesota, a car at 55 mph can stop in about 130 to 140 feet. How far may a fully loaded tractor-trailer need?","o":["About 100 feet","About 200 feet","More than 400 feet","About the same as a car"],"h1":"It is about three times as far.","h2":"In Minnesota, a fully loaded tractor-trailer may need more than 400 feet to stop, while a car at 55 mph stops in about 130 to 140 feet.","p":"Right. More than 400 feet."},"es":{"q":"En Minnesota, un auto a 55 mph puede detenerse en unos 130 a 140 pies. ¿Cuánto puede necesitar un tráiler totalmente cargado?","o":["Unos 100 pies","Unos 200 pies","Más de 400 pies","Lo mismo que un auto"],"h1":"Es como tres veces más.","h2":"En Minnesota, un tráiler totalmente cargado puede necesitar más de 400 pies para detenerse, mientras un auto a 55 mph se detiene en unos 130 a 140 pies.","p":"Correcto. Más de 400 pies."},"ref":{"doc":"MN","page":52}},{"id":"mn-186","scope":"MN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Minnesota, which vehicles must stop at every railroad crossing, even when no train is coming?","o":["Motorcycles","Small cars","Pickup trucks","Passenger vans, buses and some larger trucks"],"h1":"Think of vehicles that carry many people or heavy loads.","h2":"In Minnesota, some vehicles, such as passenger vans, buses and larger trucks, must stop at all railroad tracks, and you should not pass them there.","p":"Correct. Passenger vans, buses and some larger trucks."},"es":{"q":"En Minnesota, ¿qué vehículos deben detenerse en cada cruce de tren, aunque no venga un tren?","o":["Motocicletas","Autos pequeños","Camionetas pickup","Camionetas de pasajeros, autobuses y algunos camiones grandes"],"h1":"Piense en vehículos que llevan muchas personas o cargas pesadas.","h2":"En Minnesota, algunos vehículos, como camionetas de pasajeros, autobuses y camiones grandes, deben detenerse en todas las vías, y usted no debe rebasarlos ahí.","p":"Correcto. Camionetas de pasajeros, autobuses y algunos camiones grandes."},"ref":{"doc":"MN","page":53}},{"id":"mn-187","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, traffic is backing up before a lane closed ahead. What does the zipper merge ask you to do?","o":["Stay in your lane until the merge point, then take turns","Merge as early as possible","Stop and wait for a gap","Drive on the shoulder to the front"],"h1":"Use both lanes fully, like a zipper.","h2":"In Minnesota, in a zipper merge you stay in your current lane until the merge point and then take turns merging into the open lane.","p":"Right. Stay in your lane, then take turns at the merge point."},"es":{"q":"En Minnesota, el tráfico se acumula antes de un carril cerrado adelante. ¿Qué le pide hacer la incorporación en cierre (zipper merge)?","o":["Quedarse en su carril hasta el punto de unión y luego turnarse","Cambiarse lo antes posible","Detenerse y esperar un espacio","Manejar por el acotamiento hasta adelante"],"h1":"Use bien ambos carriles, como un cierre.","h2":"En Minnesota, en la incorporación en cierre usted se queda en su carril hasta el punto de unión y luego se turna para entrar al carril abierto.","p":"Correcto. Quédese en su carril y túrnese en el punto de unión."},"ref":{"doc":"MN","page":54}},{"id":"mn-188","scope":"MN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Minnesota, you have a disability parking permit, but all the disability spaces are full. What may you do?","o":["Park in a fire lane","Park at an angle across two standard spaces","Park on the sidewalk","Double park near the door"],"h1":"You may use extra room in the regular spaces.","h2":"In Minnesota, if all disability parking spaces are taken, a driver with a valid disability permit or plates may park at an angle across two standard spaces.","p":"Correct. Park at an angle across two regular spaces."},"es":{"q":"En Minnesota, usted tiene permiso de estacionamiento para discapacidad, pero todos esos espacios están ocupados. ¿Qué puede hacer?","o":["Estacionarse en un carril de bomberos","Estacionarse en ángulo ocupando dos espacios normales","Estacionarse en la banqueta","Estacionarse en doble fila cerca de la puerta"],"h1":"Puede usar más espacio en los lugares normales.","h2":"En Minnesota, si todos los espacios para discapacidad están ocupados, un conductor con permiso o placas válidos puede estacionarse en ángulo ocupando dos espacios normales.","p":"Correcto. En ángulo, ocupando dos espacios normales."},"ref":{"doc":"MN","page":59}},{"id":"mn-189","scope":"MN","cat":"signals","sign":null,"c":2,"en":{"q":"In Minnesota, the orange triangle slow-moving vehicle emblem must be shown on vehicles that travel at what speed?","o":["15 mph or less","25 mph or less","30 mph or less","45 mph or less"],"h1":"It is the same top speed as a moped.","h2":"In Minnesota, the slow-moving vehicle emblem must be displayed on vehicles that travel at 30 mph or less, such as farm equipment and animal-drawn vehicles.","p":"Right. 30 mph or less."},"es":{"q":"En Minnesota, el emblema triangular naranja de vehículo lento debe mostrarse en vehículos que van a qué velocidad?","o":["15 mph o menos","25 mph o menos","30 mph o menos","45 mph o menos"],"h1":"Es la misma velocidad máxima de un moped.","h2":"En Minnesota, el emblema de vehículo lento debe mostrarse en vehículos que van a 30 mph o menos, como maquinaria agrícola y vehículos tirados por animales.","p":"Correcto. 30 mph o menos."},"ref":{"doc":"MN","page":61}},{"id":"mn-190","scope":"MN","cat":"signals","sign":null,"c":3,"en":{"q":"In Minnesota, the traffic signal at an intersection is not working. How should you treat it?","o":["Drive through without slowing","Treat it as a green light for the main road","Wait until it is fixed","Treat it like an uncontrolled intersection"],"h1":"Follow the rules for a crossing with no signs or signals.","h2":"In Minnesota, if a traffic signal is not working, treat the intersection like an uncontrolled intersection, yielding as the right-of-way rules require.","p":"Correct. Treat it as an uncontrolled intersection."},"es":{"q":"En Minnesota, el semáforo de una intersección no funciona. ¿Cómo debe tratarla?","o":["Pasar sin bajar la velocidad","Como luz verde para el camino principal","Esperar a que lo reparen","Como una intersección sin control"],"h1":"Siga las reglas de un cruce sin señales ni semáforos.","h2":"En Minnesota, si un semáforo no funciona, trate la intersección como una intersección sin control y ceda el paso según las reglas de derecho de paso.","p":"Correcto. Trátela como intersección sin control."},"ref":{"doc":"MN","page":65}},{"id":"mn-191","scope":"MN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Minnesota, your car runs out of gas on an interstate and you stop on the shoulder. What is true?","o":["Running out of fuel is not an emergency, and you could get a ticket","It is always allowed to stop for fuel problems","Only trucks can be ticketed for this","You must leave the car right away"],"h1":"Stopping on a freeway is only for real emergencies.","h2":"In Minnesota, stopping on an interstate is allowed only in an emergency, and running out of fuel is not considered an emergency, so you could get a citation.","p":"Right. Running out of gas is not an emergency."},"es":{"q":"En Minnesota, a su auto se le acaba la gasolina en una interestatal y se detiene en el acotamiento. ¿Qué es cierto?","o":["Quedarse sin gasolina no es una emergencia y le pueden multar","Siempre se permite parar por problemas de gasolina","Solo multan a los camiones por esto","Debe dejar el auto de inmediato"],"h1":"Parar en una autopista es solo para emergencias reales.","h2":"En Minnesota, parar en una interestatal solo se permite en una emergencia, y quedarse sin gasolina no se considera emergencia, así que le pueden multar.","p":"Correcto. Quedarse sin gasolina no es una emergencia."},"ref":{"doc":"MN","page":77}},{"id":"mn-192","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, which is illegal while driving?","o":["Listening to the car radio","Wearing headphones or earbuds in both ears","Using one earbud for GPS directions","Talking with a passenger"],"h1":"You must be able to hear sirens and horns.","h2":"In Minnesota, it is illegal to wear headphones or earphones in both ears at the same time to listen to a radio or other sound device while driving.","p":"Correct. Both ears covered is illegal."},"es":{"q":"En Minnesota, ¿qué es ilegal mientras maneja?","o":["Escuchar el radio del auto","Usar audífonos en ambos oídos","Usar un audífono para las indicaciones del GPS","Hablar con un pasajero"],"h1":"Debe poder oír sirenas y bocinas.","h2":"En Minnesota, es ilegal usar audífonos en ambos oídos al mismo tiempo para escuchar un radio u otro aparato de sonido mientras maneja.","p":"Correcto. Cubrir ambos oídos es ilegal."},"ref":{"doc":"MN","page":79}},{"id":"mn-193","scope":"MN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Minnesota, your load sticks out 4 feet behind your vehicle in daylight. What must you attach to the end?","o":["A white sign","A red, yellow or orange flag at least 16 inches square","A small reflector","Nothing, under 5 feet is fine"],"h1":"It must be big and bright.","h2":"In Minnesota, a load that extends four feet or more past the rear must have a red, yellow or orange flag at least 16 inches square, and a red lamp at night.","p":"Right. A flag at least 16 inches square."},"es":{"q":"En Minnesota, su carga sobresale 4 pies detrás de su vehículo, de día. ¿Qué debe poner en la punta?","o":["Un letrero blanco","Una bandera roja, amarilla o naranja de al menos 16 pulgadas por lado","Un reflector pequeño","Nada, menos de 5 pies está bien"],"h1":"Debe ser grande y llamativa.","h2":"En Minnesota, una carga que sobresale cuatro pies o más atrás debe llevar una bandera roja, amarilla o naranja de al menos 16 pulgadas por lado, y una luz roja de noche.","p":"Correcto. Una bandera de al menos 16 pulgadas por lado."},"ref":{"doc":"MN","page":79}},{"id":"mn-194","scope":"MN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Minnesota, you are pulling a camper. How much following distance must you keep from other vehicles?","o":["At least 100 feet","At least 200 feet","At least 500 feet","At least 3 seconds only"],"h1":"It is a long distance, more than a football field.","h2":"In Minnesota, if you pull a camper or trailer, you must keep at least 500 feet of following distance from other vehicles.","p":"Correct. At least 500 feet."},"es":{"q":"En Minnesota, usted remolca un camper. ¿Qué distancia debe mantener con otros vehículos?","o":["Al menos 100 pies","Al menos 200 pies","Al menos 500 pies","Solo 3 segundos"],"h1":"Es una distancia larga, más que una cancha de fútbol americano.","h2":"En Minnesota, si remolca un camper o remolque, debe mantener al menos 500 pies de distancia con otros vehículos.","p":"Correcto. Al menos 500 pies."},"ref":{"doc":"MN","page":79}},{"id":"mn-195","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, can you be arrested for DWI with an alcohol level below 0.08?","o":["No, never","Only if you are over 21","Only on a motorcycle","Yes, as low as 0.04 if alcohol caused driving errors"],"h1":"Officers also look at how you drive.","h2":"In Minnesota, if an officer can prove alcohol caused driving errors, you can be arrested for DWI with an alcohol concentration as low as 0.04.","p":"Correct. As low as 0.04 when alcohol caused driving errors."},"es":{"q":"En Minnesota, ¿lo pueden arrestar por manejar intoxicado (DWI) con un nivel de alcohol menor de 0.08?","o":["No, nunca","Solo si tiene más de 21 años","Solo en motocicleta","Sí, desde 0.04 si el alcohol causó errores al manejar"],"h1":"Los policías también se fijan en cómo maneja.","h2":"En Minnesota, si un policía puede probar que el alcohol causó errores al manejar, lo pueden arrestar por DWI con una concentración de alcohol de tan solo 0.04.","p":"Correcto. Desde 0.04 si el alcohol causó errores al manejar."},"ref":{"doc":"MN","page":93}},{"id":"mn-196","scope":"MN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Minnesota, under the implied consent law, how long is your license revoked for refusing a blood, breath or urine test?","o":["One to six years, depending on your record","30 days","90 days","Ten years"],"h1":"It depends on how many offenses you have.","h2":"In Minnesota, refusing the test is a crime and leads to revocation of one to six years, depending on the number of offenses on your record.","p":"Right. One to six years."},"es":{"q":"En Minnesota, según la ley de consentimiento implícito, ¿por cuánto tiempo se revoca su licencia si se niega a una prueba de sangre, aliento u orina?","o":["De uno a seis años, según su historial","30 días","90 días","Diez años"],"h1":"Depende de cuántas infracciones tenga.","h2":"En Minnesota, negarse a la prueba es un delito y lleva a una revocación de uno a seis años, según el número de infracciones en su historial.","p":"Correcto. De uno a seis años."},"ref":{"doc":"MN","page":93}},{"id":"mn-197","scope":"MN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Minnesota, what is the minimum license revocation for a first DWI offense if you do not plead guilty?","o":["30 days","90 days","1 year","7 days"],"h1":"Pleading guilty can shorten it to 30 days.","h2":"In Minnesota, a first DWI offense brings a minimum 90-day revocation, or 30 days if you plead guilty.","p":"Correct. At least 90 days."},"es":{"q":"En Minnesota, ¿cuál es la revocación mínima de la licencia por un primer DWI si no se declara culpable?","o":["30 días","90 días","1 año","7 días"],"h1":"Declararse culpable puede bajarla a 30 días.","h2":"En Minnesota, un primer DWI trae una revocación mínima de 90 días, o de 30 días si se declara culpable.","p":"Correcto. Al menos 90 días."},"ref":{"doc":"MN","page":94}},{"id":"mn-198","scope":"MN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Minnesota, at what alcohol level does an ignition interlock device stop the car from starting?","o":["0.08 or more","0.04 or more","0.02 or more","Only 0.16 or more"],"h1":"It is a very low level.","h2":"In Minnesota, an ignition interlock device prevents the vehicle from starting if it detects an alcohol concentration of 0.02 or more.","p":"Right. 0.02 or more."},"es":{"q":"En Minnesota, ¿a qué nivel de alcohol impide un dispositivo de bloqueo de encendido (interlock) que el auto arranque?","o":["0.08 o más","0.04 o más","0.02 o más","Solo 0.16 o más"],"h1":"Es un nivel muy bajo.","h2":"En Minnesota, el dispositivo de bloqueo de encendido impide que el vehículo arranque si detecta una concentración de alcohol de 0.02 o más.","p":"Correcto. 0.02 o más."},"ref":{"doc":"MN","page":95}},{"id":"mn-199","scope":"MN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Minnesota, a driver under 21 is convicted a second time of driving with any alcohol. How long is the license suspended?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about six months.","h2":"In Minnesota, a second conviction for an underage driver with any detectable alcohol brings a 180-day suspension.","p":"Correct. 180 days."},"es":{"q":"En Minnesota, un conductor menor de 21 es condenado por segunda vez por manejar con algo de alcohol. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos seis meses.","h2":"En Minnesota, una segunda condena de un conductor menor de 21 con cualquier cantidad detectable de alcohol trae una suspensión de 180 días.","p":"Correcto. 180 días."},"ref":{"doc":"MN","page":95}},{"id":"mn-200","scope":"MN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Minnesota, you have an opened package of a cannabis product in your car on the road. Where must it be kept?","o":["In the trunk","In the glove compartment","On the back seat","In the driver's door pocket"],"h1":"It must be away from where people sit.","h2":"In Minnesota, an opened cannabis package must be kept in the trunk, or where there is no trunk, in an area not normally occupied by people, and not in the glove compartment.","p":"Right. In the trunk."},"es":{"q":"En Minnesota, lleva en su auto por el camino un paquete abierto de un producto de cannabis. ¿Dónde debe guardarlo?","o":["En la cajuela","En la guantera","En el asiento trasero","En la bolsa de la puerta del conductor"],"h1":"Debe estar lejos de donde van las personas.","h2":"En Minnesota, un paquete abierto de cannabis debe ir en la cajuela o, si no hay cajuela, en un área donde normalmente no van personas, y no en la guantera.","p":"Correcto. En la cajuela."},"ref":{"doc":"MN","page":96}},{"id":"mo-001","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the intermediate license.","h2":"You can get a Missouri instruction permit at 15, one year before you can apply for an intermediate license at 16.","p":"Right. The Missouri permit starts at 15."},"es":{"q":"En Missouri, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia intermedia.","h2":"Usted puede obtener el permiso de instrucción en Missouri a los 15 años, un año antes de poder solicitar la licencia intermedia a los 16.","p":"Correcto. El permiso en Missouri empieza a los 15."},"zh":{"q":"在 Missouri，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"它比中级驾照早一年。","h2":"你 15 岁就可以拿到 Missouri 的学习驾照，比 16 岁可以申请的中级驾照早一年。","p":"对。Missouri 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Missouri, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"Đó là một năm trước bằng lái trung gian.","h2":"Bạn có thể lấy giấy phép tập lái ở Missouri khi 15 tuổi, một năm trước khi bạn có thể xin bằng lái trung gian (intermediate license) lúc 16 tuổi.","p":"Đúng. Ở Missouri, giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Missouri, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahating taong gulang"],"h1":"Isang taon ito bago ang intermediate license.","h2":"Puwede kang kumuha ng instruction permit sa Missouri sa edad na 15, isang taon bago ka puwedeng mag-apply ng intermediate license sa edad na 16.","p":"Tama. Nagsisimula ang permit sa Missouri sa 15."},"ar":{"q":"في Missouri، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"هو سنة واحدة قبل الرخصة المتوسطة.","h2":"يمكنك الحصول على تصريح التعلّم في Missouri في عمر 15 سنة، أي قبل سنة من إمكانية التقديم على الرخصة المتوسطة (intermediate license) في عمر 16 سنة.","p":"صحيح. في Missouri يبدأ التصريح في عمر 15 سنة."},"ref":{"doc":"MO","page":3}},{"id":"mo-002","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how long must a teen hold an instruction permit before getting an intermediate license?","o":["30 days","90 days","At least 182 days, about six months","One full year"],"h1":"It is about half a year.","h2":"A Missouri teen must hold the instruction permit for at least 182 days, about six months, before applying for an intermediate license.","p":"Right. The permit must be held about six months."},"es":{"q":"En Missouri, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia intermedia?","o":["30 días","90 días","Por lo menos 182 días, unos seis meses","Un año completo"],"h1":"Es más o menos medio año.","h2":"Un adolescente en Missouri debe tener el permiso de instrucción por lo menos 182 días, unos seis meses, antes de solicitar la licencia intermedia.","p":"Correcto. El permiso se debe tener unos seis meses."},"zh":{"q":"在 Missouri，青少年必须持有学习驾照多久，才能拿到中级驾照？","o":["30 天","90 天","至少 182 天，大约六个月","整整一年"],"h1":"大约半年。","h2":"Missouri 的青少年必须持有学习驾照至少 182 天，大约六个月，才能申请中级驾照。","p":"对。学习驾照必须持有大约六个月。"},"vi":{"q":"Ở Missouri, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["30 ngày","90 ngày","Ít nhất 182 ngày, khoảng sáu tháng","Một năm đầy đủ"],"h1":"Đó là khoảng nửa năm.","h2":"Thiếu niên ở Missouri phải giữ giấy phép tập lái ít nhất 182 ngày, khoảng sáu tháng, trước khi xin bằng lái trung gian.","p":"Đúng. Phải giữ giấy phép tập lái khoảng sáu tháng."},"tl":{"q":"Sa Missouri, gaano katagal dapat hawak ng isang tinedyer ang instruction permit bago makakuha ng intermediate license?","o":["30 araw","90 araw","Hindi bababa sa 182 araw, mga anim na buwan","Isang buong taon"],"h1":"Mga kalahating taon ito.","h2":"Ang isang tinedyer sa Missouri ay dapat humawak ng instruction permit nang hindi bababa sa 182 araw, mga anim na buwan, bago mag-apply ng intermediate license.","p":"Tama. Dapat hawak ang permit nang mga anim na buwan."},"ar":{"q":"في Missouri، كم يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["30 يومًا","90 يومًا","182 يومًا على الأقل، أي نحو ستة أشهر","سنة كاملة"],"h1":"هي نحو نصف سنة.","h2":"يجب على المراهق في Missouri أن يحمل تصريح التعلّم 182 يومًا على الأقل، أي نحو ستة أشهر، قبل التقديم على الرخصة المتوسطة.","p":"صحيح. يجب حمل التصريح نحو ستة أشهر."},"ref":{"doc":"MO","page":16}},{"id":"mo-003","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, how many hours of driving instruction must a teen complete before an intermediate license?","o":["40 hours","20 hours","50 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Missouri teen must complete 40 hours of driving instruction with a qualified person before getting an intermediate license.","p":"Right. Missouri asks for 40 hours of driving instruction."},"es":{"q":"En Missouri, ¿cuántas horas de instrucción de manejo debe completar un adolescente antes de la licencia intermedia?","o":["40 horas","20 horas","50 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Missouri debe completar 40 horas de instrucción de manejo con una persona calificada antes de obtener la licencia intermedia.","p":"Correcto. Missouri pide 40 horas de instrucción de manejo."},"zh":{"q":"在 Missouri，青少年拿中级驾照前必须完成多少小时的驾驶指导？","o":["40 小时","20 小时","50 小时","60 小时"],"h1":"它少于五十。","h2":"Missouri 的青少年拿中级驾照前，必须和合格的人一起完成 40 小时的驾驶指导。","p":"对。Missouri 要求 40 小时的驾驶指导。"},"vi":{"q":"Ở Missouri, thiếu niên phải hoàn thành bao nhiêu giờ tập lái trước khi lấy bằng lái trung gian?","o":["40 giờ","20 giờ","50 giờ","60 giờ"],"h1":"Đó là ít hơn năm mươi.","h2":"Thiếu niên ở Missouri phải hoàn thành 40 giờ tập lái với một người đủ điều kiện trước khi lấy bằng lái trung gian.","p":"Đúng. Missouri yêu cầu 40 giờ tập lái."},"tl":{"q":"Sa Missouri, ilang oras ng pagsasanay sa pagmamaneho ang dapat tapusin ng isang tinedyer bago ang intermediate license?","o":["40 oras","20 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa limampu.","h2":"Ang isang tinedyer sa Missouri ay dapat tumapos ng 40 oras ng pagsasanay sa pagmamaneho kasama ang isang kwalipikadong tao bago makakuha ng intermediate license.","p":"Tama. Humihingi ang Missouri ng 40 oras ng pagsasanay sa pagmamaneho."},"ar":{"q":"في Missouri، كم ساعة من التدريب على القيادة يجب أن يكملها المراهق قبل الرخصة المتوسطة؟","o":["40 ساعة","20 ساعة","50 ساعة","60 ساعة"],"h1":"هي أقل من خمسين.","h2":"يجب على المراهق في Missouri أن يكمل 40 ساعة من التدريب على القيادة مع شخص مؤهَّل قبل الحصول على الرخصة المتوسطة.","p":"صحيح. تطلب Missouri 40 ساعة من التدريب على القيادة."},"ref":{"doc":"MO","page":16}},{"id":"mo-004","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how many of the 40 required practice hours must be at night?","o":["At least 2 hours","At least 5 hours","At least 20 hours","At least 10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of Missouri's 40 required hours of driving instruction must be driven at night.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Missouri, ¿cuántas de las 40 horas de práctica exigidas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas","Por lo menos 10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de instrucción exigidas en Missouri deben ser de noche.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Missouri，规定的 40 小时练习中，有多少小时必须在晚上？","o":["至少 2 小时","至少 5 小时","至少 20 小时","至少 10 小时"],"h1":"是总数的四分之一。","h2":"Missouri 规定的 40 小时驾驶指导中，至少 10 小时必须在晚上开。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Missouri, trong 40 giờ tập lái bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ","Ít nhất 10 giờ"],"h1":"Đó là một phần tư của tổng số.","h2":"Ở Missouri, ít nhất 10 trong 40 giờ tập lái bắt buộc phải lái vào ban đêm.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Missouri, ilan sa 40 kinakailangang oras ng pagsasanay ang dapat sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras","Hindi bababa sa 10 oras"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 kinakailangang oras ng pagsasanay sa Missouri ang dapat imaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Missouri، كم ساعة من ساعات التدريب الـ 40 المطلوبة يجب أن تكون في الليل؟","o":["ساعتان على الأقل (2)","5 ساعات على الأقل","20 ساعة على الأقل","10 ساعات على الأقل"],"h1":"هي ربع المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 المطلوبة في Missouri قيادةً في الليل.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"MO","page":16}},{"id":"mo-005","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, during which hours may a driver with an intermediate license not drive alone?","o":["Midnight to 6 a.m.","1 a.m. to 5 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The limit starts one hour after midnight.","h2":"A Missouri intermediate license holder may not drive alone from 1 a.m. to 5 a.m., the late night curfew for new drivers.","p":"Right. The curfew is 1 a.m. to 5 a.m."},"es":{"q":"En Missouri, ¿en qué horario no puede manejar solo un conductor con licencia intermedia?","o":["De medianoche a 6 a.m.","De 1 a.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El límite empieza una hora después de la medianoche.","h2":"Quien tiene licencia intermedia en Missouri no puede manejar solo de 1 a.m. a 5 a.m., el toque de queda nocturno para conductores nuevos.","p":"Correcto. El toque de queda es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Missouri，持中级驾照的司机在哪段时间不能单独开车？","o":["午夜到早上 6 点","凌晨 1 点到早上 5 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"限制从午夜后一个小时开始。","h2":"Missouri 持中级驾照的人在凌晨 1 点到早上 5 点不能单独开车，这是新司机的深夜宵禁。","p":"对。宵禁是凌晨 1 点到早上 5 点。"},"vi":{"q":"Ở Missouri, người có bằng lái trung gian không được lái một mình trong những giờ nào?","o":["Từ nửa đêm đến 6 giờ sáng","Từ 1 giờ sáng đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Giới hạn bắt đầu một giờ sau nửa đêm.","h2":"Ở Missouri, người có bằng lái trung gian không được lái một mình từ 1 giờ sáng đến 5 giờ sáng, đó là giờ giới nghiêm ban đêm cho tài xế mới.","p":"Đúng. Giờ giới nghiêm là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Missouri, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may intermediate license?","o":["Hatinggabi hanggang 6 a.m.","1 a.m. hanggang 5 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ang limitasyon isang oras pagkatapos ng hatinggabi.","h2":"Ang may intermediate license sa Missouri ay hindi puwedeng magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m., ang curfew sa hatinggabi para sa mga bagong driver.","p":"Tama. Ang curfew ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Missouri، في أي ساعات لا يجوز لمن يحمل الرخصة المتوسطة أن يقود وحده؟","o":["من منتصف الليل إلى 6 صباحًا","من 1 صباحًا إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"يبدأ المنع بعد منتصف الليل بساعة.","h2":"لا يجوز لمن يحمل الرخصة المتوسطة في Missouri أن يقود وحده من 1 صباحًا إلى 5 صباحًا، وهو حظر التجوّل الليلي للسائقين الجدد.","p":"صحيح. حظر التجوّل من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"MO","page":16}},{"id":"mo-006","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, during the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["None","Three","One","Two"],"h1":"The limit is as small as it can be without being zero.","h2":"In the first six months, a Missouri intermediate driver may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19 at first."},"es":{"q":"En Missouri, durante los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Ninguno","Tres","Uno","Dos"],"h1":"El límite es lo más pequeño posible sin ser cero.","h2":"En los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Al principio, solo un pasajero menor de 19 que no sea familia."},"zh":{"q":"在 Missouri，持中级驾照的前六个月，可以有多少位不是家人、19 岁以下的乘客坐车？","o":["一个都不行","三位","一位","两位"],"h1":"这个限制小到不能再小，但不是零。","h2":"在前六个月，Missouri 持中级驾照的司机最多只能载一位不是直系家人、19 岁以下的乘客。","p":"对。一开始只能载一位不是家人、19 岁以下的乘客。"},"vi":{"q":"Ở Missouri, trong sáu tháng đầu có bằng lái trung gian, bao nhiêu hành khách dưới 19 tuổi không phải người nhà được đi cùng tài xế?","o":["Không ai","Ba người","Một người","Hai người"],"h1":"Giới hạn nhỏ nhất có thể mà không phải là số không.","h2":"Trong sáu tháng đầu, tài xế có bằng lái trung gian ở Missouri chỉ được chở tối đa một hành khách dưới 19 tuổi không phải người nhà trực hệ.","p":"Đúng. Lúc đầu chỉ được một hành khách dưới 19 tuổi không phải người nhà."},"tl":{"q":"Sa Missouri, sa unang anim na buwan ng intermediate license, ilang pasaherong wala pang 19 taong gulang na hindi kapamilya ang puwedeng sumakay kasama ng driver?","o":["Wala","Tatlo","Isa","Dalawa"],"h1":"Pinakamaliit na limitasyon ito na hindi zero.","h2":"Sa unang anim na buwan, ang driver na may intermediate license sa Missouri ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 19 taong gulang na hindi malapit na kapamilya.","p":"Tama. Isang pasaherong wala pang 19 na hindi kapamilya lang sa simula."},"ar":{"q":"في Missouri، في أول ستة أشهر من الرخصة المتوسطة، كم راكبًا عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["لا أحد","ثلاثة","واحد","اثنان"],"h1":"الحدّ صغير قدر الإمكان من غير أن يكون صفرًا.","h2":"في أول ستة أشهر، لا يجوز لسائق الرخصة المتوسطة في Missouri أن يحمل أكثر من راكب واحد عمره أقل من 19 سنة وليس من العائلة المباشرة.","p":"صحيح. في البداية راكب واحد فقط أقل من 19 سنة من خارج العائلة."},"ref":{"doc":"MO","page":16}},{"id":"mo-007","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, after the first six months of an intermediate license, how many passengers under 19 who are not family may ride with the driver?","o":["One","Two","Five","Three"],"h1":"The limit grows after six months, but it does not disappear.","h2":"After the first six months, a Missouri intermediate driver may carry no more than three passengers under 19 who are not immediate family.","p":"Right. After six months the limit is three."},"es":{"q":"En Missouri, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 19 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cinco","Tres"],"h1":"El límite aumenta después de seis meses, pero no desaparece.","h2":"Después de los primeros seis meses, un conductor con licencia intermedia en Missouri puede llevar como máximo tres pasajeros menores de 19 años que no sean familiares directos.","p":"Correcto. Después de seis meses el límite es tres."},"zh":{"q":"在 Missouri，持中级驾照满六个月以后，可以有多少位不是家人、19 岁以下的乘客坐车？","o":["一位","两位","五位","三位"],"h1":"六个月以后限制放宽了，但没有取消。","h2":"前六个月以后，Missouri 持中级驾照的司机最多可以载三位不是直系家人、19 岁以下的乘客。","p":"对。六个月以后，限制是三位。"},"vi":{"q":"Ở Missouri, sau sáu tháng đầu có bằng lái trung gian, bao nhiêu hành khách dưới 19 tuổi không phải người nhà được đi cùng tài xế?","o":["Một người","Hai người","Năm người","Ba người"],"h1":"Giới hạn tăng lên sau sáu tháng, nhưng không mất đi.","h2":"Sau sáu tháng đầu, tài xế có bằng lái trung gian ở Missouri chỉ được chở tối đa ba hành khách dưới 19 tuổi không phải người nhà trực hệ.","p":"Đúng. Sau sáu tháng, giới hạn là ba người."},"tl":{"q":"Sa Missouri, pagkatapos ng unang anim na buwan ng intermediate license, ilang pasaherong wala pang 19 taong gulang na hindi kapamilya ang puwedeng sumakay kasama ng driver?","o":["Isa","Dalawa","Lima","Tatlo"],"h1":"Lumalaki ang limitasyon pagkatapos ng anim na buwan, pero hindi ito nawawala.","h2":"Pagkatapos ng unang anim na buwan, ang driver na may intermediate license sa Missouri ay puwedeng magsakay ng hindi hihigit sa tatlong pasaherong wala pang 19 taong gulang na hindi malapit na kapamilya.","p":"Tama. Pagkatapos ng anim na buwan, tatlo ang limitasyon."},"ar":{"q":"في Missouri، بعد أول ستة أشهر من الرخصة المتوسطة، كم راكبًا عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["واحد","اثنان","خمسة","ثلاثة"],"h1":"يكبر الحدّ بعد ستة أشهر، لكنه لا يختفي.","h2":"بعد أول ستة أشهر، لا يجوز لسائق الرخصة المتوسطة في Missouri أن يحمل أكثر من ثلاثة ركاب أعمارهم أقل من 19 سنة وليسوا من العائلة المباشرة.","p":"صحيح. بعد ستة أشهر يصبح الحدّ ثلاثة."},"ref":{"doc":"MO","page":16}},{"id":"mo-008","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, who must wear a seat belt when a driver has an intermediate license?","o":["The driver and every passenger","Only the driver","Only front seat riders","Only passengers under 16"],"h1":"The rule covers everyone in the car.","h2":"With a Missouri intermediate license, the driver and all passengers must wear seat belts.","p":"Right. Everyone in the car must buckle up."},"es":{"q":"En Missouri, ¿quién debe usar el cinturón de seguridad cuando el conductor tiene licencia intermedia?","o":["El conductor y todos los pasajeros","Solo el conductor","Solo los del asiento delantero","Solo los pasajeros menores de 16"],"h1":"La regla cubre a todos en el auto.","h2":"Con una licencia intermedia de Missouri, el conductor y todos los pasajeros deben usar el cinturón de seguridad.","p":"Correcto. Todos en el auto deben abrocharse el cinturón."},"zh":{"q":"在 Missouri，司机持中级驾照时，谁必须系安全带？","o":["司机和每一位乘客","只有司机","只有坐前排的人","只有 16 岁以下的乘客"],"h1":"这条规定包括车里的每个人。","h2":"持 Missouri 中级驾照时，司机和所有乘客都必须系安全带。","p":"对。车里每个人都必须系好安全带。"},"vi":{"q":"Ở Missouri, khi tài xế có bằng lái trung gian, ai phải thắt dây an toàn?","o":["Tài xế và mọi hành khách","Chỉ tài xế","Chỉ người ngồi ghế trước","Chỉ hành khách dưới 16 tuổi"],"h1":"Quy định áp dụng cho mọi người trong xe.","h2":"Với bằng lái trung gian ở Missouri, tài xế và tất cả hành khách phải thắt dây an toàn.","p":"Đúng. Mọi người trong xe phải thắt dây an toàn."},"tl":{"q":"Sa Missouri, sino ang dapat magsuot ng seat belt kapag ang driver ay may intermediate license?","o":["Ang driver at bawat pasahero","Ang driver lang","Ang mga nasa harapang upuan lang","Ang mga pasaherong wala pang 16 lang"],"h1":"Sakop ng patakaran ang lahat ng nasa sasakyan.","h2":"Kapag may intermediate license sa Missouri, ang driver at lahat ng pasahero ay dapat magsuot ng seat belt.","p":"Tama. Lahat ng nasa sasakyan ay dapat mag-seat belt."},"ar":{"q":"في Missouri، من يجب أن يربط حزام الأمان عندما يحمل السائق رخصة متوسطة؟","o":["السائق وكل راكب","السائق فقط","ركاب المقعد الأمامي فقط","الركاب الذين أعمارهم أقل من 16 سنة فقط"],"h1":"القاعدة تشمل كل من في السيارة.","h2":"مع الرخصة المتوسطة في Missouri، يجب على السائق وكل الركاب أن يربطوا أحزمة الأمان.","p":"صحيح. يجب على كل من في السيارة أن يربط الحزام."},"ref":{"doc":"MO","page":16}},{"id":"mo-009","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many questions are on the written test for a regular driver license?","o":["20 questions","30 questions","25 questions","40 questions"],"h1":"It is a quarter of one hundred.","h2":"The Missouri written test for a regular license has 25 multiple-choice questions.","p":"Right. The test has 25 questions."},"es":{"q":"En Missouri, ¿cuántas preguntas tiene el examen escrito para la licencia de conducir normal?","o":["20 preguntas","30 preguntas","25 preguntas","40 preguntas"],"h1":"Es la cuarta parte de cien.","h2":"El examen escrito de Missouri para la licencia normal tiene 25 preguntas de opción múltiple.","p":"Correcto. El examen tiene 25 preguntas."},"zh":{"q":"在 Missouri，普通驾照的笔试有多少道题？","o":["20 道题","30 道题","25 道题","40 道题"],"h1":"是一百的四分之一。","h2":"Missouri 普通驾照的笔试有 25 道选择题。","p":"对。笔试有 25 道题。"},"vi":{"q":"Ở Missouri, bài thi viết cho bằng lái thường có bao nhiêu câu hỏi?","o":["20 câu","30 câu","25 câu","40 câu"],"h1":"Đó là một phần tư của một trăm.","h2":"Bài thi viết ở Missouri cho bằng lái thường có 25 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi có 25 câu hỏi."},"tl":{"q":"Sa Missouri, ilang tanong ang nasa written test para sa regular na driver license?","o":["20 tanong","30 tanong","25 tanong","40 tanong"],"h1":"Isang-kapat ito ng isang daan.","h2":"Ang written test sa Missouri para sa regular na lisensya ay may 25 multiple-choice na tanong.","p":"Tama. May 25 tanong ang test."},"ar":{"q":"في Missouri، كم سؤالًا في الامتحان الكتابي لرخصة القيادة العادية؟","o":["20 سؤالًا","30 سؤالًا","25 سؤالًا","40 سؤالًا"],"h1":"هو ربع المئة.","h2":"الامتحان الكتابي في Missouri للرخصة العادية فيه 25 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في الامتحان 25 سؤالًا."},"ref":{"doc":"MO","page":18}},{"id":"mo-010","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how many of the 25 written test questions must you answer correctly to pass?","o":["15","20","18","22"],"h1":"You may miss five.","h2":"You must answer 20 of the 25 questions correctly on the Missouri written test, which is 80 percent.","p":"Right. You need 20 correct answers out of 25."},"es":{"q":"En Missouri, ¿cuántas de las 25 preguntas del examen escrito debe contestar bien para aprobar?","o":["15","20","18","22"],"h1":"Puede fallar cinco.","h2":"Usted debe contestar bien 20 de las 25 preguntas del examen escrito de Missouri, es decir, el 80 por ciento.","p":"Correcto. Necesita 20 respuestas correctas de 25."},"zh":{"q":"在 Missouri，25 道笔试题中必须答对几道才能通过？","o":["15","20","18","22"],"h1":"你可以答错五道。","h2":"在 Missouri 的笔试中，你必须在 25 道题里答对 20 道，也就是 80%。","p":"对。25 道题里你需要答对 20 道。"},"vi":{"q":"Ở Missouri, bạn phải trả lời đúng bao nhiêu trong 25 câu hỏi của bài thi viết để đậu?","o":["15","20","18","22"],"h1":"Bạn được sai năm câu.","h2":"Bạn phải trả lời đúng 20 trong 25 câu hỏi của bài thi viết ở Missouri, tức là 80 phần trăm.","p":"Đúng. Bạn cần trả lời đúng 20 trên 25 câu."},"tl":{"q":"Sa Missouri, ilan sa 25 tanong ng written test ang dapat mong masagot nang tama para pumasa?","o":["15","20","18","22"],"h1":"Puwede kang magkamali ng lima.","h2":"Dapat mong masagot nang tama ang 20 sa 25 tanong ng written test sa Missouri, na 80 porsiyento.","p":"Tama. Kailangan mo ng 20 tamang sagot sa 25."},"ar":{"q":"في Missouri، كم سؤالًا من أسئلة الامتحان الكتابي الـ 25 يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["15","20","18","22"],"h1":"يمكنك أن تخطئ في خمسة.","h2":"يجب أن تجيب إجابة صحيحة عن 20 سؤالًا من 25 في الامتحان الكتابي في Missouri، أي 80 في المئة.","p":"صحيح. تحتاج إلى 20 إجابة صحيحة من 25."},"ref":{"doc":"MO","page":1}},{"id":"mo-011","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, since the hands-free law, which drivers may not hold a phone while driving?","o":["Only drivers under 21","Only commercial drivers","Only drivers in school zones","All drivers"],"h1":"The newer law does not depend on age.","h2":"Missouri's hands-free law applies to all drivers: you may not hold, type on or scroll a phone while driving, and tickets began on January 1, 2025.","p":"Right. No driver may hold a phone while driving."},"es":{"q":"En Missouri, desde la ley de manos libres, ¿qué conductores no pueden sostener el teléfono mientras manejan?","o":["Solo los menores de 21","Solo los conductores comerciales","Solo en zonas escolares","Todos los conductores"],"h1":"La ley más nueva no depende de la edad.","h2":"La ley de manos libres de Missouri se aplica a todos los conductores: no puede sostener, escribir ni desplazarse en el teléfono mientras maneja, y las multas empezaron el 1 de enero de 2025.","p":"Correcto. Ningún conductor puede sostener el teléfono mientras maneja."},"zh":{"q":"在 Missouri，有了免提法以后，哪些司机开车时不能手拿手机？","o":["只有 21 岁以下的司机","只有商业司机","只有在学校区域的司机","所有司机"],"h1":"这条较新的法律和年龄无关。","h2":"Missouri 的免提法适用于所有司机：开车时你不能拿着手机、在手机上打字或滑动屏幕，从 2025 年 1 月 1 日开始开罚单。","p":"对。任何司机开车时都不能手拿手机。"},"vi":{"q":"Ở Missouri, từ khi có luật rảnh tay (hands-free law), những tài xế nào không được cầm điện thoại khi lái xe?","o":["Chỉ tài xế dưới 21 tuổi","Chỉ tài xế xe thương mại","Chỉ tài xế trong khu vực trường học","Tất cả tài xế"],"h1":"Luật mới không phụ thuộc vào tuổi.","h2":"Luật rảnh tay của Missouri áp dụng cho tất cả tài xế: bạn không được cầm, gõ chữ hay cuộn màn hình điện thoại khi lái xe, và việc phạt bắt đầu từ ngày 1 tháng 1 năm 2025.","p":"Đúng. Không tài xế nào được cầm điện thoại khi lái xe."},"tl":{"q":"Sa Missouri, mula nang magkaroon ng hands-free law, aling mga driver ang hindi puwedeng humawak ng telepono habang nagmamaneho?","o":["Mga driver na wala pang 21 lang","Mga commercial driver lang","Mga driver sa school zone lang","Lahat ng driver"],"h1":"Hindi nakadepende sa edad ang mas bagong batas.","h2":"Ang hands-free law ng Missouri ay para sa lahat ng driver: hindi ka puwedeng humawak, mag-type o mag-scroll sa telepono habang nagmamaneho, at nagsimula ang mga tiket noong Enero 1, 2025.","p":"Tama. Walang driver ang puwedeng humawak ng telepono habang nagmamaneho."},"ar":{"q":"في Missouri، منذ قانون القيادة بدون استخدام اليدين (hands-free law)، أي السائقين لا يجوز لهم حمل الهاتف أثناء القيادة؟","o":["السائقون الذين أعمارهم أقل من 21 سنة فقط","سائقو المركبات التجارية فقط","السائقون في مناطق المدارس فقط","كل السائقين"],"h1":"القانون الأحدث لا يتعلّق بالعمر.","h2":"قانون القيادة بدون استخدام اليدين في Missouri يشمل كل السائقين: لا يجوز لك أن تحمل الهاتف أو تكتب عليه أو تتصفّحه أثناء القيادة، وبدأت المخالفات في 1 يناير 2025.","p":"صحيح. لا يجوز لأي سائق أن يحمل الهاتف أثناء القيادة."},"ref":{"doc":"MO","page":93}},{"id":"mo-012","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, which way of using a phone is allowed for an adult driver?","o":["Talking with Bluetooth or speaker, hands-free","Holding the phone to your ear","Typing a text at a stop sign","Scrolling a map in your hand"],"h1":"Your hands must stay off the phone.","h2":"Missouri lets drivers use hands-free features such as Bluetooth, speaker or voice-to-text, but not holding or typing on the phone.","p":"Right. Hands-free use is allowed."},"es":{"q":"En Missouri, ¿qué forma de usar el teléfono está permitida para un conductor adulto?","o":["Hablar con Bluetooth o altavoz, sin manos","Sostener el teléfono en la oreja","Escribir un mensaje en un alto","Mover un mapa con la mano"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Missouri permite usar funciones de manos libres como Bluetooth, altavoz o dictado por voz, pero no sostener ni escribir en el teléfono.","p":"Correcto. El uso con manos libres está permitido."},"zh":{"q":"在 Missouri，成年司机可以用哪种方式使用手机？","o":["用蓝牙或扬声器通话，免提","把手机拿到耳边","在停车标志前打短信","手拿着手机滑动地图"],"h1":"你的手必须离开手机。","h2":"Missouri 允许司机使用蓝牙、扬声器或语音转文字等免提功能，但不能拿着手机或在手机上打字。","p":"对。可以免提使用。"},"vi":{"q":"Ở Missouri, cách dùng điện thoại nào được phép cho tài xế người lớn?","o":["Nói chuyện bằng Bluetooth hoặc loa ngoài, không cầm máy","Cầm điện thoại áp vào tai","Gõ tin nhắn khi dừng ở biển STOP","Cuộn bản đồ trên điện thoại cầm tay"],"h1":"Tay bạn phải rời khỏi điện thoại.","h2":"Missouri cho phép tài xế dùng các chức năng rảnh tay như Bluetooth, loa ngoài hoặc đọc thành chữ, nhưng không được cầm hay gõ trên điện thoại.","p":"Đúng. Được phép dùng điện thoại kiểu rảnh tay."},"tl":{"q":"Sa Missouri, aling paraan ng paggamit ng telepono ang pinapayagan para sa adult na driver?","o":["Pakikipag-usap gamit ang Bluetooth o speaker, nang hands-free","Paghawak ng telepono sa tainga","Pag-type ng text sa stop sign","Pag-scroll ng mapa sa kamay"],"h1":"Dapat hindi hawak ng kamay mo ang telepono.","h2":"Pinapayagan ng Missouri ang mga driver na gumamit ng hands-free na feature tulad ng Bluetooth, speaker o voice-to-text, pero hindi ang paghawak o pag-type sa telepono.","p":"Tama. Pinapayagan ang hands-free na paggamit."},"ar":{"q":"في Missouri، أي طريقة لاستخدام الهاتف مسموحة للسائق البالغ؟","o":["التحدّث عبر Bluetooth أو مكبّر الصوت، بدون استخدام اليدين","حمل الهاتف على الأذن","كتابة رسالة عند إشارة STOP","تصفّح الخريطة والهاتف في يدك"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"تسمح Missouri للسائقين باستخدام ميزات بدون اليدين مثل Bluetooth أو مكبّر الصوت أو تحويل الصوت إلى نص، لكن لا يجوز حمل الهاتف أو الكتابة عليه.","p":"صحيح. الاستخدام بدون اليدين مسموح."},"ref":{"doc":"MO","page":93}},{"id":"mo-013","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, at what blood alcohol level can a driver under 21 be charged?","o":["0.08 percent","0.02 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Missouri, a driver under 21 can be charged with a blood alcohol level of 0.02 percent, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Missouri, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.08 por ciento","0.02 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Missouri, a un conductor menor de 21 años se le puede acusar con 0.02 por ciento de alcohol en la sangre, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Missouri，21 岁以下的司机血液酒精浓度达到多少就可能被起诉？","o":["0.08%","0.02%","0.05%","0.10%"],"h1":"它比成年人的限值低很多。","h2":"在 Missouri，21 岁以下的司机血液酒精浓度达到 0.02% 就可能被起诉，远低于成年人 0.08 的限值。","p":"对。21 岁以下，限值是 0.02%。"},"vi":{"q":"Ở Missouri, tài xế dưới 21 tuổi có thể bị buộc tội ở mức nồng độ cồn trong máu nào?","o":["0.08 phần trăm","0.02 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Missouri, tài xế dưới 21 tuổi có thể bị buộc tội khi nồng độ cồn trong máu là 0.02 phần trăm, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Missouri, sa anong antas ng alak sa dugo puwedeng kasuhan ang driver na wala pang 21?","o":["0.08 porsiyento","0.02 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adult.","h2":"Sa Missouri, ang driver na wala pang 21 ay puwedeng kasuhan kapag 0.02 porsiyento ang alak sa dugo, mas mababa nang malaki sa limitasyon para sa adult na 0.08.","p":"Tama. Kapag wala pang 21, 0.02 porsiyento ang limitasyon."},"ar":{"q":"في Missouri، عند أي نسبة كحول في الدم يمكن أن يُتّهم السائق الذي عمره أقل من 21 سنة؟","o":["0.08 في المئة","0.02 في المئة","0.05 في المئة","0.10 في المئة"],"h1":"هي أقل بكثير من حدّ البالغين.","h2":"في Missouri، يمكن أن يُتّهم السائق الذي عمره أقل من 21 سنة إذا كانت نسبة الكحول في دمه 0.02 في المئة، وهي أقل بكثير من حدّ البالغين 0.08.","p":"صحيح. لمن عمره أقل من 21 سنة الحدّ هو 0.02 في المئة."},"ref":{"doc":"MO","page":67}},{"id":"mo-014","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you approach a stopped emergency vehicle with flashing lights on a highway with two lanes your way. What must you do?","o":["Stop in your lane","Speed up to pass quickly","Change lanes away from it if safe, or slow down","Honk and keep your speed"],"h1":"Give the workers more space.","h2":"Missouri's move over law says to change to a lane away from the stopped vehicle if it is safe, or slow down if you cannot.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Missouri, usted se acerca a un vehículo de emergencia detenido con luces intermitentes en una carretera con dos carriles en su dirección. ¿Qué debe hacer?","o":["Detenerse en su carril","Acelerar para pasar rápido","Cambiarse de carril, alejándose, si es seguro, o reducir la velocidad","Tocar la bocina y mantener la velocidad"],"h1":"Dé más espacio a los trabajadores.","h2":"La ley de Missouri dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, o reducir la velocidad si no puede.","p":"Correcto. Cámbiese de carril, o reduzca la velocidad si no puede."},"zh":{"q":"在 Missouri，你在你的方向有两条车道的公路上，接近一辆停着、闪着灯的急救车辆。你必须怎么做？","o":["在你的车道里停车","加速很快开过去","如果安全，换到离它远的车道，否则减速","按喇叭，保持速度"],"h1":"给工作人员更多空间。","h2":"Missouri 的 move over 法规定，如果安全，要换到离停着的车远的车道；如果不能换道，就要减速。","p":"对。让出车道，不能让就减速。"},"vi":{"q":"Ở Missouri, bạn đến gần một xe cấp cứu đang dừng và nháy đèn trên xa lộ có hai làn theo chiều của bạn. Bạn phải làm gì?","o":["Dừng lại trong làn của bạn","Tăng tốc để vượt nhanh","Chuyển sang làn xa xe đó nếu an toàn, hoặc chạy chậm lại","Bấm còi và giữ tốc độ"],"h1":"Hãy cho người làm việc thêm chỗ.","h2":"Luật nhường làn (move over law) của Missouri nói phải chuyển sang làn xa xe đang dừng nếu an toàn, hoặc chạy chậm lại nếu bạn không thể chuyển làn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Missouri, papalapit ka sa isang nakahintong emergency vehicle na may kumikislap na ilaw sa highway na may dalawang lane sa direksyon mo. Ano ang dapat mong gawin?","o":["Huminto sa lane mo","Bumilis para mabilis na makalampas","Lumipat sa lane na malayo rito kung ligtas, o bumagal","Bumusina at panatilihin ang bilis"],"h1":"Bigyan ng mas maraming espasyo ang mga nagtatrabaho.","h2":"Sinasabi ng move over law ng Missouri na lumipat sa lane na malayo sa nakahintong sasakyan kung ligtas, o bumagal kung hindi ka makalipat.","p":"Tama. Lumipat ng lane, o bumagal kung hindi puwede."},"ar":{"q":"في Missouri، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض على طريق سريع فيه مساران في اتجاهك. ماذا يجب أن تفعل؟","o":["تتوقف في مسارك","تسرع لتتجاوزها بسرعة","تنتقل إلى مسار بعيد عنها إذا كان ذلك آمنًا، أو تخفّف السرعة","تضغط على البوق وتحافظ على سرعتك"],"h1":"أعطِ العاملين مساحة أكبر.","h2":"قانون الابتعاد (move over law) في Missouri يقول أن تنتقل إلى مسار بعيد عن المركبة المتوقفة إذا كان ذلك آمنًا، أو أن تخفّف السرعة إذا لم تستطع.","p":"صحيح. ابتعد بتغيير المسار، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"MO","page":23}},{"id":"mo-015","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, which stopped vehicles are covered by the move over law besides police, fire and ambulances?","o":["Only school buses","Only mail trucks","Any car parked on the shoulder","MoDOT vehicles with amber lights"],"h1":"Think of highway work trucks with yellow lights.","h2":"Missouri's move over law also covers stopped vehicles showing amber or amber and white lights, such as MoDOT trucks, so road workers get room too.","p":"Right. MoDOT vehicles with amber lights are covered."},"es":{"q":"En Missouri, ¿qué vehículos detenidos cubre la ley de cambiarse de carril, además de policía, bomberos y ambulancias?","o":["Solo los autobuses escolares","Solo los camiones del correo","Cualquier auto en el acotamiento","Los vehículos de MoDOT con luces ámbar"],"h1":"Piense en camiones de trabajo en la carretera con luces amarillas.","h2":"La ley de Missouri también cubre los vehículos detenidos con luces ámbar o ámbar y blancas, como los camiones de MoDOT, para que los trabajadores también tengan espacio.","p":"Correcto. Los vehículos de MoDOT con luces ámbar están cubiertos."},"zh":{"q":"在 Missouri，除了警车、消防车和救护车，move over 法还包括哪些停着的车？","o":["只有校车","只有邮政卡车","任何停在路肩上的车","开着琥珀色灯的 MoDOT 车辆"],"h1":"想一想开着黄灯的公路工作卡车。","h2":"Missouri 的 move over 法也包括停着、开着琥珀色灯或琥珀色加白色灯的车，比如 MoDOT 的卡车，这样道路工人也有空间。","p":"对。开着琥珀色灯的 MoDOT 车辆也包括在内。"},"vi":{"q":"Ở Missouri, ngoài xe cảnh sát, xe cứu hỏa và xe cứu thương, luật nhường làn (move over law) còn áp dụng cho xe đang dừng nào?","o":["Chỉ xe buýt trường học","Chỉ xe tải bưu điện","Bất kỳ xe nào đậu bên lề đường","Xe của MoDOT có đèn màu hổ phách"],"h1":"Hãy nghĩ đến xe tải làm đường có đèn vàng.","h2":"Luật nhường làn của Missouri cũng áp dụng cho xe đang dừng có đèn màu hổ phách, hoặc đèn hổ phách và trắng, như xe tải của MoDOT, để công nhân làm đường cũng có chỗ.","p":"Đúng. Xe của MoDOT có đèn màu hổ phách cũng được áp dụng."},"tl":{"q":"Sa Missouri, bukod sa pulis, bumbero at ambulansya, aling mga nakahintong sasakyan ang sakop ng move over law?","o":["Mga school bus lang","Mga mail truck lang","Anumang kotseng nakaparada sa shoulder","Mga sasakyan ng MoDOT na may amber na ilaw"],"h1":"Isipin ang mga trak na pantrabaho sa highway na may dilaw na ilaw.","h2":"Sakop din ng move over law ng Missouri ang mga nakahintong sasakyan na may amber o amber at puting ilaw, tulad ng mga trak ng MoDOT, para may espasyo rin ang mga manggagawa sa kalsada.","p":"Tama. Sakop ang mga sasakyan ng MoDOT na may amber na ilaw."},"ar":{"q":"في Missouri، غير الشرطة والإطفاء والإسعاف، أي المركبات المتوقفة يشملها قانون الابتعاد (move over law)؟","o":["الحافلات المدرسية فقط","شاحنات البريد فقط","أي سيارة متوقفة على كتف الطريق","مركبات MoDOT ذات الأضواء الكهرمانية"],"h1":"فكّر في شاحنات العمل على الطرق ذات الأضواء الصفراء.","h2":"قانون الابتعاد في Missouri يشمل أيضًا المركبات المتوقفة التي تُظهر أضواء كهرمانية، أو كهرمانية وبيضاء، مثل شاحنات MoDOT، حتى يحصل عمّال الطرق أيضًا على مساحة.","p":"صحيح. مركبات MoDOT ذات الأضواء الكهرمانية مشمولة."},"ref":{"doc":"MO","page":null}},{"id":"mo-016","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, when must your headlights be on during the day?","o":["Whenever the weather requires your windshield wipers","Only after sunset","Only on interstates","Only in work zones"],"h1":"Think of rain on your windshield.","h2":"Missouri requires lighted headlights any time the weather makes you use your windshield wipers, and also in fog.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Missouri, ¿cuándo deben estar encendidas las luces delanteras durante el día?","o":["Siempre que el clima exija usar los limpiaparabrisas","Solo después de la puesta del sol","Solo en autopistas interestatales","Solo en zonas de trabajo"],"h1":"Piense en la lluvia sobre su parabrisas.","h2":"Missouri exige las luces delanteras encendidas cada vez que el clima le obliga a usar los limpiaparabrisas, y también con niebla.","p":"Correcto. Limpiaparabrisas encendidos significa luces encendidas."},"zh":{"q":"在 Missouri，白天什么时候必须打开车头灯？","o":["只要天气让你需要用雨刷","只在日落以后","只在州际公路上","只在施工区"],"h1":"想一想挡风玻璃上的雨。","h2":"Missouri 规定，只要天气让你使用挡风玻璃雨刷，就必须打开车头灯，有雾时也一样。","p":"对。开雨刷就要开车头灯。"},"vi":{"q":"Ở Missouri, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Bất cứ khi nào thời tiết cần bật cần gạt nước","Chỉ sau khi mặt trời lặn","Chỉ trên xa lộ liên bang","Chỉ trong khu vực công trường"],"h1":"Hãy nghĩ đến mưa trên kính chắn gió.","h2":"Missouri yêu cầu bật đèn pha bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước, và cả khi có sương mù.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Missouri, kailan dapat nakabukas ang headlights mo sa araw?","o":["Tuwing kailangan ng panahon ang windshield wipers mo","Pagkatapos lang lumubog ang araw","Sa interstate lang","Sa work zone lang"],"h1":"Isipin ang ulan sa windshield mo.","h2":"Hinihingi ng Missouri na nakabukas ang headlights tuwing ang panahon ay nagpapagamit sa iyo ng windshield wipers, at pati kapag may hamog (fog).","p":"Tama. Kapag bukas ang wipers, bukas ang headlights."},"ar":{"q":"في Missouri، متى يجب أن تكون المصابيح الأمامية مضاءة أثناء النهار؟","o":["كلما احتاج الطقس إلى تشغيل مسّاحات الزجاج الأمامي","بعد غروب الشمس فقط","على الطرق السريعة بين الولايات فقط","في مناطق العمل فقط"],"h1":"فكّر في المطر على الزجاج الأمامي.","h2":"تطلب Missouri إضاءة المصابيح الأمامية في أي وقت يجعلك فيه الطقس تستخدم مسّاحات الزجاج الأمامي، وكذلك في الضباب.","p":"صحيح. إذا شغّلت المسّاحات فأضئ المصابيح الأمامية."},"ref":{"doc":"MO","page":62}},{"id":"mo-017","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, there is fog but you do not need your wipers. Must your headlights be on?","o":["No, only when wipers are on","Only if you drive over 45 mph","Yes, fog also requires headlights","Only after sunset"],"h1":"The law names fog on its own.","h2":"Missouri law requires headlights during fog even when you do not need your windshield wipers.","p":"Right. Fog means headlights on."},"es":{"q":"En Missouri, hay niebla pero no necesita los limpiaparabrisas. ¿Deben estar encendidas las luces delanteras?","o":["No, solo cuando usa los limpiaparabrisas","Solo si maneja a más de 45 mph","Sí, la niebla también exige luces","Solo después de la puesta del sol"],"h1":"La ley menciona la niebla por separado.","h2":"La ley de Missouri exige las luces delanteras con niebla aunque no necesite los limpiaparabrisas.","p":"Correcto. Con niebla, luces encendidas."},"zh":{"q":"在 Missouri，有雾，但你不需要开雨刷。你必须打开车头灯吗？","o":["不用，只有开雨刷时才要","只有开超过 45 英里/小时时","要，有雾也必须开车头灯","只在日落以后"],"h1":"法律单独写明了雾。","h2":"Missouri 法律规定，有雾时必须打开车头灯，即使你不需要开挡风玻璃雨刷。","p":"对。有雾就要开车头灯。"},"vi":{"q":"Ở Missouri, trời có sương mù nhưng bạn không cần dùng cần gạt nước. Bạn có phải bật đèn pha không?","o":["Không, chỉ khi bật cần gạt nước","Chỉ khi bạn chạy trên 45 mph","Có, sương mù cũng bắt buộc bật đèn pha","Chỉ sau khi mặt trời lặn"],"h1":"Luật nói riêng về sương mù.","h2":"Luật Missouri yêu cầu bật đèn pha khi có sương mù, ngay cả khi bạn không cần dùng cần gạt nước.","p":"Đúng. Có sương mù thì bật đèn pha."},"tl":{"q":"Sa Missouri, may hamog (fog) pero hindi mo kailangan ang wipers mo. Dapat bang nakabukas ang headlights mo?","o":["Hindi, kapag bukas lang ang wipers","Kung nagmamaneho ka lang nang higit sa 45 mph","Oo, kailangan din ng headlights kapag may hamog","Pagkatapos lang lumubog ang araw"],"h1":"Binabanggit ng batas ang hamog nang hiwalay.","h2":"Hinihingi ng batas ng Missouri ang headlights kapag may hamog kahit hindi mo kailangan ang windshield wipers mo.","p":"Tama. Kapag may hamog, bukas ang headlights."},"ar":{"q":"في Missouri، يوجد ضباب لكنك لا تحتاج إلى المسّاحات. هل يجب أن تكون المصابيح الأمامية مضاءة؟","o":["لا، فقط عندما تكون المسّاحات تعمل","فقط إذا كنت تقود بسرعة أكثر من 45 mph","نعم، الضباب أيضًا يتطلّب المصابيح الأمامية","بعد غروب الشمس فقط"],"h1":"القانون يذكر الضباب وحده.","h2":"قانون Missouri يتطلّب المصابيح الأمامية في الضباب حتى عندما لا تحتاج إلى مسّاحات الزجاج الأمامي.","p":"صحيح. في الضباب أضئ المصابيح الأمامية."},"ref":{"doc":"MO","page":null}},{"id":"mo-018","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a school bus with flashing red lights is stopped on the other side of a divided highway with a median. What must you do?","o":["Stop until the lights turn off","You do not have to stop","Stop, then pass at 10 mph","Stop only if you see children"],"h1":"The median separates you from the bus.","h2":"In Missouri, drivers on the opposite side of a divided highway, or of a highway with four or more lanes, do not have to stop for a school bus, but traffic behind the bus must stop.","p":"Right. The other side of a divided highway does not have to stop."},"es":{"q":"En Missouri, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida con camellón. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","No tiene que detenerse","Detenerse y luego pasar a 10 mph","Detenerse solo si ve niños"],"h1":"El camellón lo separa del autobús.","h2":"En Missouri, los conductores del otro lado de una carretera dividida, o de una carretera de cuatro carriles o más, no tienen que detenerse por un autobús escolar, pero el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Missouri，一辆闪着红灯的校车停在有中央隔离带的分隔公路另一边。你必须怎么做？","o":["停车，直到灯熄灭","你不必停车","停车，然后用 10 英里/小时开过去","只有看到孩子时才停车"],"h1":"中央隔离带把你和校车分开。","h2":"在 Missouri，在分隔公路或四条及以上车道的公路对面行驶的司机，不必为校车停车，但校车后面的车必须停车。","p":"对。分隔公路另一边的车不必停车。"},"vi":{"q":"Ở Missouri, một xe buýt trường học nháy đèn đỏ đang dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Bạn không phải dừng lại","Dừng lại, rồi vượt qua với tốc độ 10 mph","Chỉ dừng lại nếu bạn thấy trẻ em"],"h1":"Dải phân cách ngăn cách bạn với xe buýt.","h2":"Ở Missouri, tài xế ở phía bên kia của xa lộ có dải phân cách, hoặc của xa lộ có bốn làn trở lên, không phải dừng lại cho xe buýt trường học, nhưng xe chạy phía sau xe buýt phải dừng lại.","p":"Đúng. Phía bên kia của xa lộ có dải phân cách không phải dừng lại."},"tl":{"q":"Sa Missouri, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang panig ng divided highway na may median. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Hindi mo kailangang huminto","Huminto, saka lumampas sa 10 mph","Huminto lang kung may makita kang mga bata"],"h1":"Pinaghihiwalay ka ng median sa bus.","h2":"Sa Missouri, ang mga driver sa kabilang panig ng divided highway, o ng highway na may apat o higit pang lane, ay hindi kailangang huminto para sa school bus, pero ang mga sasakyan sa likod ng bus ay dapat huminto.","p":"Tama. Hindi kailangang huminto ang kabilang panig ng divided highway."},"ar":{"q":"في Missouri، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الجانب الآخر من طريق سريع مقسوم بجزيرة وسطى. ماذا يجب أن تفعل؟","o":["تتوقف حتى تنطفئ الأضواء","ليس عليك أن تتوقف","تتوقف، ثم تتجاوز بسرعة 10 mph","تتوقف فقط إذا رأيت أطفالًا"],"h1":"الجزيرة الوسطى تفصلك عن الحافلة.","h2":"في Missouri، ليس على السائقين في الجانب الآخر من طريق سريع مقسوم، أو من طريق سريع فيه أربعة مسارات أو أكثر، أن يتوقفوا للحافلة المدرسية، لكن السيارات خلف الحافلة يجب أن تتوقف.","p":"صحيح. الجانب الآخر من الطريق المقسوم ليس عليه أن يتوقف."},"ref":{"doc":"MO","page":24}},{"id":"mo-019","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you are behind a school bus on a divided highway when it stops with red lights flashing. What must you do?","o":["Pass on the left with care","Pass if no children are near","Slow to 20 mph and pass","Stop and wait"],"h1":"You are on the same side as the bus.","h2":"When you travel in the same direction as a stopped school bus in Missouri, you must stop, even on a divided highway.","p":"Right. Traffic on the same side must stop."},"es":{"q":"En Missouri, usted va detrás de un autobús escolar en una carretera dividida cuando se detiene con luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasar por la izquierda con cuidado","Rebasar si no hay niños cerca","Bajar a 20 mph y rebasar","Detenerse y esperar"],"h1":"Usted está del mismo lado que el autobús.","h2":"Cuando usted va en la misma dirección que un autobús escolar detenido en Missouri, debe detenerse, aunque sea una carretera dividida.","p":"Correcto. El tráfico del mismo lado debe detenerse."},"zh":{"q":"在 Missouri，你在分隔公路上跟在一辆校车后面，它停下来并闪着红灯。你必须怎么做？","o":["小心地从左边超过去","如果附近没有孩子就超过去","减速到 20 英里/小时再超过去","停车等待"],"h1":"你和校车在同一边。","h2":"在 Missouri，当你和停着的校车同方向行驶时，你必须停车，即使是在分隔公路上。","p":"对。同一边的车必须停车。"},"vi":{"q":"Ở Missouri, bạn đang chạy sau một xe buýt trường học trên xa lộ có dải phân cách thì xe buýt dừng lại và nháy đèn đỏ. Bạn phải làm gì?","o":["Vượt bên trái một cách cẩn thận","Vượt nếu không có trẻ em ở gần","Chạy chậm xuống 20 mph rồi vượt","Dừng lại và chờ"],"h1":"Bạn ở cùng phía với xe buýt.","h2":"Ở Missouri, khi bạn đi cùng chiều với một xe buýt trường học đang dừng, bạn phải dừng lại, ngay cả trên xa lộ có dải phân cách.","p":"Đúng. Xe cùng phía phải dừng lại."},"tl":{"q":"Sa Missouri, nasa likod ka ng school bus sa divided highway nang huminto ito na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Lumampas sa kaliwa nang maingat","Lumampas kung walang batang malapit","Bumagal sa 20 mph at lumampas","Huminto at maghintay"],"h1":"Nasa parehong panig ka ng bus.","h2":"Kapag pareho ang direksyon mo at ng nakahintong school bus sa Missouri, dapat kang huminto, kahit sa divided highway.","p":"Tama. Dapat huminto ang mga sasakyan sa parehong panig."},"ar":{"q":"في Missouri، أنت خلف حافلة مدرسية على طريق سريع مقسوم عندما تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تتجاوز من اليسار بحذر","تتجاوز إذا لم يكن هناك أطفال قريبون","تخفّف إلى 20 mph وتتجاوز","تتوقف وتنتظر"],"h1":"أنت على نفس جانب الحافلة.","h2":"عندما تسير في نفس اتجاه حافلة مدرسية متوقفة في Missouri، يجب أن تتوقف، حتى على طريق سريع مقسوم.","p":"صحيح. السيارات على نفس الجانب يجب أن تتوقف."},"ref":{"doc":"MO","page":23}},{"id":"mo-020","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, a 2026 law allows up to 75 mph on some rural interstates. What speed must you obey where the sign still says 70 mph?","o":["70 mph, the posted limit","75 mph, the new law","80 mph when traffic is light","65 mph, the expressway limit"],"h1":"The sign on the road tells you the limit.","h2":"You must obey the posted sign: where it says 70 mph, the limit is 70 mph, even though Missouri allows up to 75 mph on some rural interstates.","p":"Right. Always obey the posted limit."},"es":{"q":"En Missouri, una ley de 2026 permite hasta 75 mph en algunas autopistas rurales. ¿Qué velocidad debe respetar donde el letrero todavía dice 70 mph?","o":["70 mph, el límite indicado","75 mph, la nueva ley","80 mph si hay poco tráfico","65 mph, el límite de vía rápida"],"h1":"El letrero en la carretera le dice el límite.","h2":"Usted debe respetar el letrero: donde dice 70 mph, el límite es 70 mph, aunque Missouri permite hasta 75 mph en algunas autopistas rurales.","p":"Correcto. Siempre respete el límite indicado."},"zh":{"q":"在 Missouri，2026 年的一条法律允许一些乡村州际公路限速最高到 75 英里/小时。在标志仍然写着 70 英里/小时的地方，你必须遵守什么速度？","o":["70 英里/小时，标出的限速","75 英里/小时，新法律","车少时 80 英里/小时","65 英里/小时，快速路的限速"],"h1":"路上的标志告诉你限速。","h2":"你必须遵守标出的标志：标志写 70 英里/小时的地方，限速就是 70 英里/小时，即使 Missouri 允许一些乡村州际公路最高到 75 英里/小时。","p":"对。一定要遵守标出的限速。"},"vi":{"q":"Ở Missouri, một luật năm 2026 cho phép chạy đến 75 mph trên một số xa lộ liên bang ở vùng nông thôn. Bạn phải theo tốc độ nào ở nơi biển báo vẫn ghi 70 mph?","o":["70 mph, giới hạn ghi trên biển","75 mph, theo luật mới","80 mph khi ít xe","65 mph, giới hạn của đường cao tốc"],"h1":"Biển báo trên đường cho bạn biết giới hạn.","h2":"Bạn phải theo biển báo: nơi biển ghi 70 mph thì giới hạn là 70 mph, dù Missouri cho phép đến 75 mph trên một số xa lộ liên bang ở vùng nông thôn.","p":"Đúng. Luôn theo giới hạn ghi trên biển báo."},"tl":{"q":"Sa Missouri, may batas noong 2026 na nagpapahintulot ng hanggang 75 mph sa ilang rural interstate. Anong bilis ang dapat mong sundin kung saan 70 mph pa rin ang nakasulat sa sign?","o":["70 mph, ang nakapaskil na limitasyon","75 mph, ang bagong batas","80 mph kapag kaunti ang trapiko","65 mph, ang limitasyon sa expressway"],"h1":"Ang sign sa kalsada ang nagsasabi sa iyo ng limitasyon.","h2":"Dapat mong sundin ang nakapaskil na sign: kung saan nakasulat ang 70 mph, 70 mph ang limitasyon, kahit pinapayagan ng Missouri ang hanggang 75 mph sa ilang rural interstate.","p":"Tama. Laging sundin ang nakapaskil na limitasyon."},"ar":{"q":"في Missouri، قانون من سنة 2026 يسمح بسرعة حتى 75 mph على بعض الطرق السريعة الريفية بين الولايات. أي سرعة يجب أن تلتزم بها حيث ما زالت اللافتة تقول 70 mph؟","o":["70 mph، الحدّ المكتوب على اللافتة","75 mph، القانون الجديد","80 mph عندما تكون حركة المرور خفيفة","65 mph، حدّ الطرق السريعة"],"h1":"اللافتة على الطريق تخبرك بالحدّ.","h2":"يجب أن تلتزم باللافتة المكتوبة: حيث تقول 70 mph فالحدّ هو 70 mph، مع أن Missouri تسمح بحتى 75 mph على بعض الطرق السريعة الريفية بين الولايات.","p":"صحيح. التزم دائمًا بالحدّ المكتوب على اللافتة."},"ref":{"doc":"MO","page":50}},{"id":"mo-021","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many points within 18 months lead to a license suspension?","o":["4 points","6 points","8 points","12 points"],"h1":"It is double the number that brings a warning letter.","h2":"In Missouri, 8 points within 18 months lead to a suspension, starting at 30 days for a first time.","p":"Right. Eight points in 18 months means suspension."},"es":{"q":"En Missouri, ¿cuántos puntos en 18 meses llevan a la suspensión de la licencia?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Es el doble del número que trae una carta de aviso.","h2":"En Missouri, 8 puntos en 18 meses llevan a una suspensión, que empieza con 30 días la primera vez.","p":"Correcto. Ocho puntos en 18 meses significan suspensión."},"zh":{"q":"在 Missouri，18 个月内被扣多少分会导致驾照被暂停？","o":["4 分","6 分","8 分","12 分"],"h1":"它是收到警告信的分数的两倍。","h2":"在 Missouri，18 个月内被扣 8 分会导致驾照被暂停，第一次是 30 天起。","p":"对。18 个月内 8 分就会被暂停驾照。"},"vi":{"q":"Ở Missouri, bị bao nhiêu điểm trong vòng 18 tháng thì bị treo bằng lái?","o":["4 điểm","6 điểm","8 điểm","12 điểm"],"h1":"Đó là gấp đôi số điểm khiến bạn nhận thư cảnh báo.","h2":"Ở Missouri, bị 8 điểm trong vòng 18 tháng thì bị treo bằng lái, bắt đầu từ 30 ngày cho lần đầu.","p":"Đúng. Tám điểm trong 18 tháng thì bị treo bằng lái."},"tl":{"q":"Sa Missouri, ilang puntos sa loob ng 18 buwan ang humahantong sa suspensyon ng lisensya?","o":["4 na puntos","6 na puntos","8 puntos","12 puntos"],"h1":"Doble ito ng bilang na nagdadala ng sulat ng babala.","h2":"Sa Missouri, ang 8 puntos sa loob ng 18 buwan ay humahantong sa suspensyon, na nagsisimula sa 30 araw sa unang beses.","p":"Tama. Walong puntos sa 18 buwan ay nangangahulugang suspensyon."},"ar":{"q":"في Missouri، كم نقطة خلال 18 شهرًا تؤدي إلى تعليق الرخصة؟","o":["4 نقاط","6 نقاط","8 نقاط","12 نقطة"],"h1":"هي ضعف العدد الذي يجلب رسالة تحذير.","h2":"في Missouri، 8 نقاط خلال 18 شهرًا تؤدي إلى تعليق الرخصة، يبدأ من 30 يومًا في المرة الأولى.","p":"صحيح. ثماني نقاط في 18 شهرًا تعني تعليق الرخصة."},"ref":{"doc":"MO","page":73}},{"id":"mo-022","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what happens when a driver gets 4 points within 12 months?","o":["The license is revoked for a year","The Department of Revenue sends a warning letter","The driver must retake the road test","Nothing happens"],"h1":"It is a first step, not a penalty.","h2":"When a Missouri driver gets 4 points in 12 months, the Department of Revenue sends an advisory letter as a warning.","p":"Right. Four points in 12 months brings a warning letter."},"es":{"q":"En Missouri, ¿qué pasa cuando un conductor acumula 4 puntos en 12 meses?","o":["Le revocan la licencia por un año","El Departamento de Ingresos le envía una carta de aviso","Debe repetir el examen de manejo","No pasa nada"],"h1":"Es un primer paso, no un castigo.","h2":"Cuando un conductor en Missouri acumula 4 puntos en 12 meses, el Departamento de Ingresos le envía una carta de aviso.","p":"Correcto. Cuatro puntos en 12 meses traen una carta de aviso."},"zh":{"q":"在 Missouri，司机在 12 个月内被扣 4 分会怎样？","o":["驾照被吊销一年","Department of Revenue 寄来一封警告信","司机必须重新路考","什么都不会发生"],"h1":"这是第一步，不是处罚。","h2":"Missouri 的司机在 12 个月内被扣 4 分时，Department of Revenue 会寄一封提醒信作为警告。","p":"对。12 个月内 4 分会收到警告信。"},"vi":{"q":"Ở Missouri, điều gì xảy ra khi tài xế bị 4 điểm trong vòng 12 tháng?","o":["Bằng lái bị thu hồi một năm","Department of Revenue (Sở Thuế vụ) gửi thư cảnh báo","Tài xế phải thi lái lại","Không có gì xảy ra"],"h1":"Đó là bước đầu tiên, không phải hình phạt.","h2":"Khi tài xế ở Missouri bị 4 điểm trong 12 tháng, Department of Revenue gửi một thư nhắc nhở để cảnh báo.","p":"Đúng. Bốn điểm trong 12 tháng sẽ nhận thư cảnh báo."},"tl":{"q":"Sa Missouri, ano ang mangyayari kapag ang isang driver ay nagkaroon ng 4 na puntos sa loob ng 12 buwan?","o":["Babawiin ang lisensya nang isang taon","Magpapadala ang Department of Revenue ng sulat ng babala","Dapat ulitin ng driver ang road test","Walang mangyayari"],"h1":"Unang hakbang ito, hindi parusa.","h2":"Kapag ang isang driver sa Missouri ay nagkaroon ng 4 na puntos sa 12 buwan, magpapadala ang Department of Revenue ng advisory letter bilang babala.","p":"Tama. Ang apat na puntos sa 12 buwan ay nagdadala ng sulat ng babala."},"ar":{"q":"في Missouri، ماذا يحدث عندما يحصل السائق على 4 نقاط خلال 12 شهرًا؟","o":["تُلغى الرخصة لمدة سنة","ترسل Department of Revenue (دائرة الإيرادات) رسالة تحذير","يجب على السائق أن يعيد امتحان القيادة على الطريق","لا يحدث شيء"],"h1":"هي خطوة أولى، وليست عقوبة.","h2":"عندما يحصل سائق في Missouri على 4 نقاط خلال 12 شهرًا، ترسل Department of Revenue رسالة تنبيه كتحذير.","p":"صحيح. أربع نقاط في 12 شهرًا تجلب رسالة تحذير."},"ref":{"doc":"MO","page":73}},{"id":"mo-023","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, what is the minimum liability insurance for property damage?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"It matches the amount required for injury to one person.","h2":"Since January 1, 2024, Missouri requires at least $25,000 of property damage coverage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $25,000."},"es":{"q":"En Missouri, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Es igual a la cantidad exigida por lesiones a una persona.","h2":"Desde el 1 de enero de 2024, Missouri exige por lo menos $25,000 de cobertura por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $25,000."},"zh":{"q":"在 Missouri，财产损失的最低责任保险是多少？","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"它和一个人受伤所要求的金额一样。","h2":"从 2024 年 1 月 1 日起，Missouri 要求至少 $25,000 的财产损失保险，每位受伤的人 $25,000，每次车祸 $50,000。","p":"对。财产损失保险必须至少 $25,000。"},"vi":{"q":"Ở Missouri, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Số tiền này bằng số tiền bắt buộc cho thương tích của một người.","h2":"Từ ngày 1 tháng 1 năm 2024, Missouri yêu cầu bảo hiểm thiệt hại tài sản ít nhất $25,000, cùng với $25,000 cho mỗi người bị thương và $50,000 cho mỗi vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất là $25,000."},"tl":{"q":"Sa Missouri, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"Kapareho ito ng halagang kailangan para sa pinsala sa isang tao.","h2":"Mula Enero 1, 2024, hinihingi ng Missouri ang hindi bababa sa $25,000 na coverage para sa pinsala sa ari-arian, kasama ang $25,000 bawat taong nasaktan at $50,000 bawat aksidente.","p":"Tama. Ang coverage para sa pinsala sa ari-arian ay dapat hindi bababa sa $25,000."},"ar":{"q":"في Missouri، ما الحدّ الأدنى لتأمين المسؤولية عن أضرار الممتلكات؟","o":["$5,000","$10,000","$50,000","$25,000"],"h1":"يساوي المبلغ المطلوب لإصابة شخص واحد.","h2":"منذ 1 يناير 2024، تطلب Missouri تغطية لأضرار الممتلكات لا تقل عن $25,000، مع $25,000 لكل شخص مصاب و$50,000 لكل حادث.","p":"صحيح. يجب ألا تقل تغطية أضرار الممتلكات عن $25,000."},"ref":{"doc":"MO","page":79}},{"id":"mo-024","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, besides liability, which insurance coverage must every car policy include?","o":["Uninsured motorist coverage","Collision coverage","Rental car coverage","Roadside assistance"],"h1":"It protects you when the other driver has no insurance.","h2":"Missouri requires uninsured motorist coverage for injuries, so you are protected if a driver without insurance hurts you.","p":"Right. Uninsured motorist coverage is required."},"es":{"q":"En Missouri, además de la responsabilidad civil, ¿qué cobertura debe incluir toda póliza de auto?","o":["Cobertura contra conductores sin seguro","Cobertura de choque","Cobertura de auto de alquiler","Asistencia en el camino"],"h1":"Le protege cuando el otro conductor no tiene seguro.","h2":"Missouri exige la cobertura contra conductores sin seguro para lesiones, para protegerle si un conductor sin seguro le lastima.","p":"Correcto. La cobertura contra conductores sin seguro es obligatoria."},"zh":{"q":"在 Missouri，除了责任保险，每份汽车保单还必须包括哪种保险？","o":["无保险驾驶人保险（uninsured motorist）","碰撞险","租车保险","道路救援"],"h1":"当对方司机没有保险时，它保护你。","h2":"Missouri 要求有针对受伤的无保险驾驶人保险，这样如果一位没有保险的司机伤到你，你也有保障。","p":"对。必须有无保险驾驶人保险。"},"vi":{"q":"Ở Missouri, ngoài bảo hiểm trách nhiệm, mọi hợp đồng bảo hiểm xe phải có loại bảo hiểm nào?","o":["Bảo hiểm tài xế không có bảo hiểm (uninsured motorist coverage)","Bảo hiểm va chạm","Bảo hiểm xe thuê","Dịch vụ cứu hộ trên đường"],"h1":"Nó bảo vệ bạn khi tài xế kia không có bảo hiểm.","h2":"Missouri yêu cầu bảo hiểm tài xế không có bảo hiểm cho thương tích, để bạn được bảo vệ nếu một tài xế không có bảo hiểm làm bạn bị thương.","p":"Đúng. Bảo hiểm tài xế không có bảo hiểm là bắt buộc."},"tl":{"q":"Sa Missouri, bukod sa liability, anong insurance coverage ang dapat kasama sa bawat car policy?","o":["Uninsured motorist coverage","Collision coverage","Coverage para sa rental car","Roadside assistance"],"h1":"Pinoprotektahan ka nito kapag walang insurance ang ibang driver.","h2":"Hinihingi ng Missouri ang uninsured motorist coverage para sa mga pinsala sa katawan, para protektado ka kung masaktan ka ng driver na walang insurance.","p":"Tama. Kailangan ang uninsured motorist coverage."},"ar":{"q":"في Missouri، غير تأمين المسؤولية، أي تغطية تأمينية يجب أن تكون في كل وثيقة تأمين سيارة؟","o":["تغطية السائق غير المؤمَّن (uninsured motorist coverage)","تغطية الاصطدام","تغطية السيارة المستأجرة","المساعدة على الطريق"],"h1":"تحميك عندما لا يكون لدى السائق الآخر تأمين.","h2":"تطلب Missouri تغطية السائق غير المؤمَّن للإصابات، حتى تكون محميًا إذا أصابك سائق ليس لديه تأمين.","p":"صحيح. تغطية السائق غير المؤمَّن مطلوبة."},"ref":{"doc":"MO","page":79}},{"id":"mo-025","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, until a permit holder turns 16, which person may ride along as the supervising driver?","o":["Any friend age 18 or older","A grandparent with a valid license","Any licensed sibling","A neighbor age 19 or older"],"h1":"Think of a close family member from an older generation.","h2":"Before age 16, a Missouri permit holder must drive with a parent, grandparent, guardian or certified instructor, or another qualified adult the rules allow.","p":"Right. A grandparent may supervise a permit holder under 16."},"es":{"q":"En Missouri, hasta que el titular del permiso cumple 16 años, ¿qué persona puede acompañarle como conductor supervisor?","o":["Cualquier amigo de 18 años o más","Un abuelo o abuela con licencia válida","Cualquier hermano con licencia","Un vecino de 19 años o más"],"h1":"Piense en un familiar cercano de una generación mayor.","h2":"Antes de los 16 años, el titular de un permiso en Missouri debe manejar con su padre, madre, abuelo, tutor o un instructor certificado, u otro adulto calificado que permitan las reglas.","p":"Correcto. Un abuelo puede supervisar a un titular de permiso menor de 16."},"zh":{"q":"在 Missouri，持学习驾照的人满 16 岁之前，谁可以作为陪同的司机同车？","o":["任何 18 岁或以上的朋友","持有效驾照的祖父母","任何有驾照的兄弟姐妹","19 岁或以上的邻居"],"h1":"想一想上一代的亲近家人。","h2":"16 岁以前，Missouri 持学习驾照的人必须和父母、祖父母、监护人或有证书的教练一起开车，或者和规定允许的其他合格成年人一起开车。","p":"对。祖父母可以陪同 16 岁以下持学习驾照的人。"},"vi":{"q":"Ở Missouri, cho đến khi người có giấy phép tập lái đủ 16 tuổi, ai có thể ngồi cùng làm người giám sát?","o":["Bất kỳ người bạn nào từ 18 tuổi trở lên","Ông hoặc bà có bằng lái hợp lệ","Bất kỳ anh chị em nào có bằng lái","Một người hàng xóm từ 19 tuổi trở lên"],"h1":"Hãy nghĩ đến một người thân trong gia đình thuộc thế hệ lớn hơn.","h2":"Trước 16 tuổi, người có giấy phép tập lái ở Missouri phải lái cùng cha mẹ, ông bà, người giám hộ hoặc giáo viên dạy lái có chứng nhận, hoặc một người lớn đủ điều kiện khác mà quy định cho phép.","p":"Đúng. Ông hoặc bà có thể giám sát người có giấy phép tập lái dưới 16 tuổi."},"tl":{"q":"Sa Missouri, hanggang sa mag-16 ang may permit, sino ang puwedeng sumama bilang supervising driver?","o":["Sinumang kaibigan na 18 taong gulang pataas","Isang lolo o lola na may valid na lisensya","Sinumang kapatid na may lisensya","Isang kapitbahay na 19 taong gulang pataas"],"h1":"Isipin ang isang malapit na kapamilya mula sa mas nakatatandang henerasyon.","h2":"Bago mag-16, ang may permit sa Missouri ay dapat magmaneho kasama ang magulang, lolo o lola, guardian o certified instructor, o ibang kwalipikadong adult na pinapayagan ng mga patakaran.","p":"Tama. Puwedeng magbantay ang lolo o lola sa may permit na wala pang 16."},"ar":{"q":"في Missouri، إلى أن يبلغ حامل التصريح 16 سنة، من يمكنه أن يرافقه كسائق مشرف؟","o":["أي صديق عمره 18 سنة أو أكثر","جدّ أو جدّة لديه رخصة سارية","أي أخ أو أخت لديه رخصة","جار عمره 19 سنة أو أكثر"],"h1":"فكّر في قريب من العائلة من جيل أكبر.","h2":"قبل عمر 16 سنة، يجب على حامل التصريح في Missouri أن يقود مع أحد الوالدين أو الجدّ أو الجدّة أو الوصي أو مدرّب معتمد، أو شخص بالغ مؤهَّل آخر تسمح به القواعد.","p":"صحيح. يمكن للجدّ أو الجدّة أن يشرف على حامل التصريح الذي عمره أقل من 16 سنة."},"ref":{"doc":"MO","page":15}},{"id":"mo-026","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, what happens if you refuse a chemical test for alcohol when a police officer asks?","o":["You get a warning letter","You pay a small fine only","Your license is taken away for one year","You must retake the written test"],"h1":"Refusing has a serious, long result.","h2":"In Missouri, if you refuse a chemical test of your blood alcohol, your driver license is taken away for one year.","p":"Right. Refusing the test costs you your license for one year."},"es":{"q":"En Missouri, ¿qué pasa si usted se niega a hacer una prueba química de alcohol cuando un policía se lo pide?","o":["Recibe una carta de advertencia","Solo paga una multa pequeña","Le quitan la licencia por un año","Debe repetir el examen escrito"],"h1":"Negarse tiene un resultado serio y largo.","h2":"En Missouri, si usted se niega a una prueba química del alcohol en la sangre, le quitan la licencia de manejar por un año.","p":"Correcto. Negarse a la prueba le cuesta la licencia por un año."},"zh":{"q":"在 Missouri，如果警察要求你做酒精化学检测而你拒绝，会怎么样？","o":["你会收到一封警告信","你只需要交一小笔罚款","你的驾照会被收回一年","你必须重新参加笔试"],"h1":"拒绝检测的后果很严重，而且时间很长。","h2":"在 Missouri，如果你拒绝做血液酒精化学检测，你的驾照会被收回一年。","p":"对。拒绝检测会让你失去驾照一年。"},"vi":{"q":"Ở Missouri, điều gì xảy ra nếu bạn từ chối làm xét nghiệm hóa học về rượu khi cảnh sát yêu cầu?","o":["Bạn nhận một lá thư cảnh cáo","Bạn chỉ phải trả một khoản phạt nhỏ","Bằng lái của bạn bị tước trong một năm","Bạn phải thi lại phần thi viết"],"h1":"Từ chối sẽ có hậu quả nghiêm trọng và kéo dài.","h2":"Ở Missouri, nếu bạn từ chối làm xét nghiệm hóa học về nồng độ cồn trong máu, bằng lái của bạn sẽ bị tước trong một năm.","p":"Đúng. Từ chối xét nghiệm làm bạn mất bằng lái trong một năm."},"tl":{"q":"Sa Missouri, ano ang mangyayari kung tumanggi ka sa chemical test para sa alak kapag hiningi ito ng pulis?","o":["Makakatanggap ka ng warning letter","Magbabayad ka lang ng maliit na multa","Kukunin ang lisensya mo nang isang taon","Kailangan mong ulitin ang written test"],"h1":"Seryoso at matagal ang resulta ng pagtanggi.","h2":"Sa Missouri, kung tumanggi ka sa chemical test ng alak sa dugo mo, kukunin ang driver license mo nang isang taon.","p":"Tama. Kapag tumanggi ka sa test, mawawala ang lisensya mo nang isang taon."},"ar":{"q":"في Missouri، ماذا يحدث إذا رفضت فحصًا كيميائيًا للكحول عندما يطلبه منك شرطي؟","o":["تحصل على رسالة تحذير","تدفع غرامة صغيرة فقط","تُسحب رخصتك لمدة سنة واحدة","يجب أن تعيد الاختبار الكتابي"],"h1":"للرفض نتيجة خطيرة وطويلة.","h2":"في Missouri، إذا رفضت فحصًا كيميائيًا لنسبة الكحول في دمك، تُسحب رخصة القيادة منك لمدة سنة واحدة.","p":"صحيح. رفض الفحص يُفقدك رخصتك لمدة سنة واحدة."},"ref":{"doc":"MO","page":70}},{"id":"mo-027","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, what is the highest fine a judge may give for littering?","o":["$1,000","$50","$100","$250"],"h1":"There can also be up to a year in jail.","h2":"In Missouri a person found guilty of littering may have to pay a fine of up to $1,000, spend up to one year in jail, or both.","p":"Right. Littering can cost up to $1,000."},"es":{"q":"En Missouri, ¿cuál es la multa más alta que un juez puede dar por tirar basura?","o":["$1,000","$50","$100","$250"],"h1":"También puede haber hasta un año de cárcel.","h2":"En Missouri una persona declarada culpable de tirar basura puede pagar una multa de hasta $1,000, pasar hasta un año en la cárcel, o las dos cosas.","p":"Correcto. Tirar basura puede costar hasta $1,000."},"zh":{"q":"在 Missouri，乱扔垃圾时法官最多可以罚多少钱？","o":["$1,000","$50","$100","$250"],"h1":"还可能被判最多一年监禁。","h2":"在 Missouri，乱扔垃圾被判有罪的人最多可能被罚 $1,000，或者最多坐一年牢，或者两样都有。","p":"对。乱扔垃圾最多可能被罚 $1,000。"},"vi":{"q":"Ở Missouri, thẩm phán có thể phạt tối đa bao nhiêu tiền vì xả rác?","o":["$1,000","$50","$100","$250"],"h1":"Cũng có thể bị tù đến một năm.","h2":"Ở Missouri, người bị kết tội xả rác có thể phải trả tiền phạt đến $1,000, bị tù đến một năm, hoặc cả hai.","p":"Đúng. Xả rác có thể bị phạt đến $1,000."},"tl":{"q":"Sa Missouri, ano ang pinakamataas na multa na puwedeng ibigay ng judge para sa pagkakalat ng basura?","o":["$1,000","$50","$100","$250"],"h1":"Puwede ring makulong nang hanggang isang taon.","h2":"Sa Missouri, ang taong napatunayang nagkalat ng basura ay puwedeng magbayad ng multa na hanggang $1,000, makulong nang hanggang isang taon, o pareho.","p":"Tama. Puwedeng umabot sa $1,000 ang multa sa pagkakalat ng basura."},"ar":{"q":"في Missouri، ما أعلى غرامة يمكن أن يفرضها القاضي على رمي النفايات في غير مكانها؟","o":["$1,000","$50","$100","$250"],"h1":"قد يكون هناك أيضًا سجن حتى سنة واحدة.","h2":"في Missouri، الشخص الذي تثبت إدانته برمي النفايات قد يدفع غرامة تصل إلى $1,000، أو يُسجن حتى سنة واحدة، أو الاثنين معًا.","p":"صحيح. رمي النفايات قد يكلّف حتى $1,000."},"ref":{"doc":"MO","page":34}},{"id":"mo-028","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, your license has expired. After how long must you take the written and driving tests again to renew it?","o":["After 30 days","After 60 days","After 2 years","After 6 months (184 days)"],"h1":"It is the same length of time as the early-renewal window.","h2":"In Missouri, if you do not renew within six months (184 days) after your license expires, you must take the written and driving tests again, plus the vision and road sign tests.","p":"Right. Wait more than 184 days and you must retest."},"es":{"q":"En Missouri, su licencia está vencida. ¿Después de cuánto tiempo debe repetir los exámenes escrito y de manejo para renovarla?","o":["Después de 30 días","Después de 60 días","Después de 2 años","Después de 6 meses (184 días)"],"h1":"Es el mismo tiempo que el plazo para renovar antes.","h2":"En Missouri, si usted no renueva dentro de seis meses (184 días) después del vencimiento, debe repetir los exámenes escrito y de manejo, además de los de vista y señales.","p":"Correcto. Si pasan más de 184 días, debe volver a examinarse."},"zh":{"q":"在 Missouri，你的驾照已经过期。过期多久以后，你必须重新参加笔试和路考才能更新？","o":["30 天以后","60 天以后","2 年以后","6 个月（184 天）以后"],"h1":"这和提前更新的期限一样长。","h2":"在 Missouri，如果驾照过期后六个月（184 天）内你没有更新，你必须重新参加笔试和路考，还要参加视力测试和路标测试。","p":"对。超过 184 天，你就必须重新考试。"},"vi":{"q":"Ở Missouri, bằng lái của bạn đã hết hạn. Sau bao lâu thì bạn phải thi lại phần thi viết và thi lái để gia hạn?","o":["Sau 30 ngày","Sau 60 ngày","Sau 2 năm","Sau 6 tháng (184 ngày)"],"h1":"Đó là cùng khoảng thời gian với thời hạn gia hạn sớm.","h2":"Ở Missouri, nếu bạn không gia hạn trong vòng sáu tháng (184 ngày) sau khi bằng lái hết hạn, bạn phải thi lại phần thi viết và thi lái, cùng với bài kiểm tra thị lực và bài kiểm tra biển báo đường.","p":"Đúng. Chờ quá 184 ngày thì bạn phải thi lại."},"tl":{"q":"Sa Missouri, expired na ang lisensya mo. Pagkalipas ng gaano katagal kailangan mong ulitin ang written at driving test para ma-renew ito?","o":["Pagkalipas ng 30 araw","Pagkalipas ng 60 araw","Pagkalipas ng 2 taon","Pagkalipas ng 6 na buwan (184 araw)"],"h1":"Kapareho ito ng haba ng panahon para sa maagang pag-renew.","h2":"Sa Missouri, kung hindi ka mag-renew sa loob ng anim na buwan (184 araw) matapos mag-expire ang lisensya mo, kailangan mong ulitin ang written at driving test, pati ang vision test at road sign test.","p":"Tama. Kapag lumampas ka sa 184 araw, kailangan mong mag-test ulit."},"ar":{"q":"في Missouri، انتهت صلاحية رخصتك. بعد كم من الوقت يجب أن تعيد الاختبار الكتابي واختبار القيادة لتجديدها؟","o":["بعد 30 يومًا","بعد 60 يومًا","بعد سنتين (2)","بعد 6 أشهر (184 يومًا)"],"h1":"إنها نفس مدة فترة التجديد المبكر.","h2":"في Missouri، إذا لم تجدّد رخصتك خلال ستة أشهر (184 يومًا) بعد انتهاء صلاحيتها، يجب أن تعيد الاختبار الكتابي واختبار القيادة، بالإضافة إلى اختبار النظر واختبار إشارات الطريق.","p":"صحيح. إذا انتظرت أكثر من 184 يومًا يجب أن تعيد الاختبار."},"ref":{"doc":"MO","page":11}},{"id":"mo-029","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, when you must file an accident report with the Department of Revenue, how long do you have?","o":["24 hours","30 days","6 months","1 year"],"h1":"It is about one month.","h2":"In Missouri a required accident report must be filed with the Driver License Bureau within 30 days.","p":"Right. File the accident report within 30 days."},"es":{"q":"En Missouri, cuando debe presentar un informe de accidente al Departamento de Ingresos, ¿cuánto tiempo tiene?","o":["24 horas","30 días","6 meses","1 año"],"h1":"Es más o menos un mes.","h2":"En Missouri un informe de accidente obligatorio se debe presentar a la Oficina de Licencias de Manejar dentro de 30 días.","p":"Correcto. Presente el informe dentro de 30 días."},"zh":{"q":"在 Missouri，如果你必须向 Department of Revenue 提交事故报告，你有多长时间？","o":["24 小时","30 天","6 个月","1 年"],"h1":"大约一个月。","h2":"在 Missouri，必须提交的事故报告要在 30 天内交给 Driver License Bureau。","p":"对。要在 30 天内提交事故报告。"},"vi":{"q":"Ở Missouri, khi bạn phải nộp báo cáo tai nạn cho Department of Revenue, bạn có bao nhiêu thời gian?","o":["24 giờ","30 ngày","6 tháng","1 năm"],"h1":"Khoảng một tháng.","h2":"Ở Missouri, báo cáo tai nạn bắt buộc phải được nộp cho Driver License Bureau trong vòng 30 ngày.","p":"Đúng. Hãy nộp báo cáo tai nạn trong vòng 30 ngày."},"tl":{"q":"Sa Missouri, kapag kailangan mong mag-file ng accident report sa Department of Revenue, gaano katagal ang mayroon ka?","o":["24 oras","30 araw","6 na buwan","1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa Missouri, ang kinakailangang accident report ay dapat i-file sa Driver License Bureau sa loob ng 30 araw.","p":"Tama. I-file ang accident report sa loob ng 30 araw."},"ar":{"q":"في Missouri، عندما يجب عليك تقديم تقرير حادث إلى Department of Revenue، كم من الوقت لديك؟","o":["24 ساعة","30 يومًا","6 أشهر","سنة واحدة (1)"],"h1":"إنها حوالي شهر واحد.","h2":"في Missouri، يجب تقديم تقرير الحادث المطلوب إلى Driver License Bureau خلال 30 يومًا.","p":"صحيح. قدّم تقرير الحادث خلال 30 يومًا."},"ref":{"doc":"MO","page":81}},{"id":"mo-030","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, you have a minor crash on the highway and no one is hurt. What should you do with your car?","o":["Leave it in the lane until police arrive","Drive away and call later","Move it onto the shoulder or off the road","Turn off the engine and wait inside"],"h1":"Think \"steer it and clear it.\"","h2":"In Missouri, after a minor crash with no injuries, you should move your car onto the shoulder or another spot off the road so traffic does not back up.","p":"Right. Steer it and clear it off the road."},"es":{"q":"En Missouri, usted tiene un choque leve en la carretera y nadie está herido. ¿Qué debe hacer con su carro?","o":["Dejarlo en el carril hasta que llegue la policía","Irse y llamar después","Moverlo al acotamiento o fuera de la carretera","Apagar el motor y esperar adentro"],"h1":"Piense en \"muévalo y despeje\".","h2":"En Missouri, después de un choque leve sin heridos, usted debe mover su carro al acotamiento u otro lugar fuera de la carretera para que el tráfico no se detenga.","p":"Correcto. Mueva el carro y despeje la carretera."},"zh":{"q":"在 Missouri，你在公路上发生了小车祸，没有人受伤。你应该怎么处理你的车？","o":["留在车道上，等警察来","开走，以后再打电话","把车移到路肩上或离开道路","关掉发动机，在车里等"],"h1":"记住“把车开走，把路让开”。","h2":"在 Missouri，发生没有人受伤的小车祸后，你应该把车移到路肩上或其他离开道路的地方，这样交通就不会堵塞。","p":"对。把车开走，把路让开。"},"vi":{"q":"Ở Missouri, bạn bị va chạm nhẹ trên xa lộ và không ai bị thương. Bạn nên làm gì với xe của mình?","o":["Để xe trong làn đường cho đến khi cảnh sát đến","Lái đi và gọi điện sau","Di chuyển xe vào lề đường hoặc ra khỏi đường","Tắt máy và ngồi chờ trong xe"],"h1":"Hãy nghĩ: \"lái xe ra và dọn đường\".","h2":"Ở Missouri, sau một va chạm nhẹ không ai bị thương, bạn nên di chuyển xe vào lề đường hoặc một chỗ khác ra khỏi đường để xe cộ không bị ùn tắc.","p":"Đúng. Lái xe ra và dọn đường."},"tl":{"q":"Sa Missouri, nagkaroon ka ng maliit na banggaan sa highway at walang nasaktan. Ano ang dapat mong gawin sa sasakyan mo?","o":["Iwan ito sa lane hanggang dumating ang pulis","Umalis at tumawag na lang mamaya","Ilipat ito sa shoulder o palabas ng kalsada","Patayin ang makina at maghintay sa loob"],"h1":"Isipin ang \"steer it and clear it\": imaneho ito at alisin sa daan.","h2":"Sa Missouri, pagkatapos ng maliit na banggaan na walang nasaktan, dapat mong ilipat ang sasakyan mo sa shoulder o sa ibang lugar na wala sa kalsada para hindi magkatrapik.","p":"Tama. Imaneho ito at alisin sa kalsada."},"ar":{"q":"في Missouri، وقع لك حادث بسيط على الطريق السريع ولم يُصب أحد. ماذا يجب أن تفعل بسيارتك؟","o":["اتركها في المسار حتى تصل الشرطة","ابتعد بالسيارة واتصل لاحقًا","انقلها إلى كتف الطريق أو خارج الطريق","أطفئ المحرك وانتظر داخل السيارة"],"h1":"فكّر في: \"حرّكها وأخلِ الطريق\".","h2":"في Missouri، بعد حادث بسيط بلا إصابات، يجب أن تنقل سيارتك إلى كتف الطريق أو إلى مكان آخر خارج الطريق حتى لا تتوقف حركة السير.","p":"صحيح. حرّك السيارة وأخلِ الطريق."},"ref":{"doc":"MO","page":81}},{"id":"mo-031","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, on a highway with two or more lanes in each direction, when should you use the left lane?","o":["To pass slower traffic","Whenever you want to drive fast","Only when towing a trailer","For the whole trip"],"h1":"Keep right most of the time.","h2":"In Missouri, on a highway with two or more lanes in each direction, you keep to the right and use the left lane to pass slower traffic; the only other reasons to leave the right lane are to make room for a driver entering the road or to get ready for a legal left turn.","p":"Right. Use the left lane to pass, then move back right."},"es":{"q":"En Missouri, en una carretera con dos o más carriles en cada dirección, ¿cuándo debe usar el carril izquierdo?","o":["Para rebasar al tráfico más lento","Siempre que quiera ir rápido","Solo cuando jala un remolque","Durante todo el viaje"],"h1":"Manténgase a la derecha casi siempre.","h2":"En Missouri, en una carretera con dos o más carriles en cada dirección, usted se mantiene a la derecha y usa el carril izquierdo para rebasar al tráfico más lento; las únicas otras razones para dejar el carril derecho son dar espacio a un conductor que entra a la carretera o prepararse para una vuelta a la izquierda permitida.","p":"Correcto. Use el carril izquierdo para rebasar y luego vuelva a la derecha."},"zh":{"q":"在 Missouri，在每个方向有两条或更多车道的公路上，你什么时候应该用左车道？","o":["超过开得比较慢的车","每次你想开快的时候","只在拖拖车的时候","整个路程都用"],"h1":"大部分时间靠右行驶。","h2":"在 Missouri，在每个方向有两条或更多车道的公路上，你要靠右行驶，用左车道超过开得比较慢的车；离开右车道的其他理由只有两个：给正在进入道路的司机让出空间，或者准备合法地左转。","p":"对。用左车道超车，然后回到右边。"},"vi":{"q":"Ở Missouri, trên xa lộ có hai làn đường trở lên mỗi chiều, khi nào bạn nên dùng làn bên trái?","o":["Để vượt xe chạy chậm hơn","Bất cứ khi nào bạn muốn chạy nhanh","Chỉ khi kéo rơ-moóc","Trong suốt chuyến đi"],"h1":"Hầu hết thời gian hãy đi bên phải.","h2":"Ở Missouri, trên xa lộ có hai làn đường trở lên mỗi chiều, bạn đi bên phải và dùng làn bên trái để vượt xe chạy chậm hơn; lý do khác duy nhất để rời làn bên phải là nhường chỗ cho tài xế đang vào đường hoặc chuẩn bị rẽ trái hợp pháp.","p":"Đúng. Dùng làn bên trái để vượt, rồi trở lại bên phải."},"tl":{"q":"Sa Missouri, sa highway na may dalawa o higit pang lane sa bawat direksyon, kailan mo dapat gamitin ang kaliwang lane?","o":["Para mag-overtake sa mas mabagal na sasakyan","Tuwing gusto mong magmaneho nang mabilis","Kapag may hila kang trailer lang","Sa buong biyahe"],"h1":"Manatili sa kanan halos sa lahat ng oras.","h2":"Sa Missouri, sa highway na may dalawa o higit pang lane sa bawat direksyon, manatili ka sa kanan at gamitin ang kaliwang lane para mag-overtake sa mas mabagal na sasakyan; ang tanging ibang dahilan para umalis sa kanang lane ay para magbigay-daan sa driver na pumapasok sa kalsada o para maghanda sa legal na pagliko pakaliwa.","p":"Tama. Gamitin ang kaliwang lane para mag-overtake, pagkatapos bumalik sa kanan."},"ar":{"q":"في Missouri، على طريق سريع فيه مساران أو أكثر في كل اتجاه، متى يجب أن تستخدم المسار الأيسر؟","o":["لتجاوز السيارات الأبطأ","كلما أردت أن تقود بسرعة","فقط عندما تجرّ مقطورة","طوال الرحلة"],"h1":"ابقَ على اليمين معظم الوقت.","h2":"في Missouri، على طريق سريع فيه مساران أو أكثر في كل اتجاه، تبقى على اليمين وتستخدم المسار الأيسر لتجاوز السيارات الأبطأ؛ والسببان الآخران الوحيدان لترك المسار الأيمن هما إفساح المجال لسائق يدخل الطريق أو الاستعداد لانعطاف قانوني إلى اليسار.","p":"صحيح. استخدم المسار الأيسر للتجاوز، ثم عُد إلى اليمين."},"ref":{"doc":"MO","page":37}},{"id":"mo-032","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a regular driver license can be valid for up to how many years?","o":["2 years","4 years","6 years","10 years"],"h1":"It is the longest period the guide gives for one license.","h2":"A Missouri driver license can be valid for up to six years.","p":"Right. A Missouri license can last up to six years."},"es":{"q":"En Missouri, ¿por cuántos años como máximo puede ser válida una licencia de conducir normal?","o":["2 años","4 años","6 años","10 años"],"h1":"Es el período más largo que da la guía para una licencia.","h2":"Una licencia de conducir de Missouri puede ser válida hasta por seis años.","p":"Correcto. Una licencia de Missouri puede durar hasta seis años."},"zh":{"q":"在 Missouri，普通驾照最长可以有效几年？","o":["2 年","4 年","6 年","10 年"],"h1":"这是指南给一张驾照的最长期限。","h2":"Missouri 的驾照最长可以有效六年。","p":"对。Missouri 的驾照最长可以用六年。"},"vi":{"q":"Ở Missouri, bằng lái xe thông thường có thể có hiệu lực tối đa bao nhiêu năm?","o":["2 năm","4 năm","6 năm","10 năm"],"h1":"Đó là thời hạn dài nhất mà sách hướng dẫn cho một bằng lái.","h2":"Bằng lái xe Missouri có thể có hiệu lực tối đa sáu năm.","p":"Đúng. Bằng lái Missouri có thể dùng tối đa sáu năm."},"tl":{"q":"Sa Missouri, hanggang ilang taon puwedeng maging valid ang isang regular na driver license?","o":["2 taon","4 na taon","6 na taon","10 taon"],"h1":"Ito ang pinakamahabang panahon na ibinibigay ng guide para sa isang lisensya.","h2":"Puwedeng maging valid ang driver license sa Missouri nang hanggang anim na taon.","p":"Tama. Puwedeng tumagal nang hanggang anim na taon ang lisensya sa Missouri."},"ar":{"q":"في Missouri، ما أقصى عدد من السنوات يمكن أن تكون فيه رخصة القيادة العادية سارية؟","o":["2 سنة","4 سنوات","6 سنوات","10 سنوات"],"h1":"هي أطول مدة يذكرها الدليل لرخصة واحدة.","h2":"يمكن أن تكون رخصة القيادة في Missouri سارية لمدة تصل إلى ست سنوات.","p":"صحيح. يمكن أن تبقى الرخصة في Missouri حتى ست سنوات."},"ref":{"doc":"MO","page":11}},{"id":"mo-033","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, what is the standard minimum vision for a driver license?","o":["20/40 with one or both eyes","20/20 in each eye","20/100 with both eyes","20/200 with glasses"],"h1":"Many drivers pass it with or without glasses.","h2":"Missouri's standard is at least 20/40 vision with either eye or both eyes.","p":"Right. The standard is 20/40 with one or both eyes."},"es":{"q":"En Missouri, ¿cuál es la visión mínima normal para obtener una licencia de conducir?","o":["20/40 con uno o ambos ojos","20/20 en cada ojo","20/100 con ambos ojos","20/200 con lentes"],"h1":"Muchos conductores la pasan con o sin lentes.","h2":"La norma de Missouri es una visión de al menos 20/40 con un ojo o con ambos.","p":"Correcto. La norma es 20/40 con uno o ambos ojos."},"zh":{"q":"在 Missouri，拿驾照的标准最低视力是多少？","o":["一只眼或两只眼 20/40","每只眼 20/20","两只眼 20/100","戴眼镜 20/200"],"h1":"很多司机戴不戴眼镜都能通过。","h2":"Missouri 的标准是一只眼或两只眼的视力至少 20/40。","p":"对。标准是一只眼或两只眼 20/40。"},"vi":{"q":"Ở Missouri, thị lực tối thiểu tiêu chuẩn để lấy bằng lái là bao nhiêu?","o":["20/40 với một hoặc cả hai mắt","20/20 ở mỗi mắt","20/100 với cả hai mắt","20/200 khi đeo kính"],"h1":"Nhiều tài xế đạt được dù có đeo kính hay không.","h2":"Tiêu chuẩn của Missouri là thị lực ít nhất 20/40 với một mắt hoặc cả hai mắt.","p":"Đúng. Tiêu chuẩn là 20/40 với một hoặc cả hai mắt."},"tl":{"q":"Sa Missouri, ano ang karaniwang pinakamababang paningin para sa driver license?","o":["20/40 sa isa o sa dalawang mata","20/20 sa bawat mata","20/100 sa dalawang mata","20/200 na may salamin"],"h1":"Maraming driver ang pumapasa rito, may salamin man o wala.","h2":"Ang pamantayan ng Missouri ay paningin na hindi bababa sa 20/40 sa isang mata o sa dalawang mata.","p":"Tama. Ang pamantayan ay 20/40 sa isa o sa dalawang mata."},"ar":{"q":"في Missouri، ما الحدّ الأدنى المعتاد للنظر للحصول على رخصة القيادة؟","o":["20/40 بعين واحدة أو بالعينين","20/20 في كل عين","20/100 بالعينين","20/200 بالنظارات"],"h1":"كثير من السائقين ينجحون فيه بالنظارات أو بدونها.","h2":"المعيار في Missouri هو نظر لا يقل عن 20/40 بعين واحدة أو بالعينين.","p":"صحيح. المعيار هو 20/40 بعين واحدة أو بالعينين."},"ref":{"doc":"MO","page":18}},{"id":"mo-034","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, during the driving test the examiner takes off points for mistakes. You fail if you lose more than how many points?","o":["10 points","20 points","50 points","30 points"],"h1":"It is a round number between 20 and 50.","h2":"You fail the Missouri driving test if you lose more than 30 points.","p":"Right. Losing more than 30 points means you fail."},"es":{"q":"En Missouri, durante el examen de manejo el examinador le resta puntos por cada error. Usted reprueba si pierde más de cierta cantidad de puntos. ¿Cuál es esa cantidad?","o":["10 puntos","20 puntos","50 puntos","30 puntos"],"h1":"Es un número redondo entre 20 y 50.","h2":"Usted reprueba el examen de manejo de Missouri si pierde más de 30 puntos.","p":"Correcto. Si pierde más de 30 puntos, reprueba."},"zh":{"q":"在 Missouri，路考时考官会因为错误扣分。扣分超过多少分就不及格？","o":["10 分","20 分","50 分","30 分"],"h1":"这是 20 和 50 之间的一个整数。","h2":"在 Missouri 的路考中，如果扣分超过 30 分，你就不及格。","p":"对。扣分超过 30 分就不及格。"},"vi":{"q":"Ở Missouri, trong bài thi lái xe, giám khảo trừ điểm khi bạn mắc lỗi. Bạn bị rớt nếu bị trừ hơn bao nhiêu điểm?","o":["10 điểm","20 điểm","50 điểm","30 điểm"],"h1":"Đó là một số tròn giữa 20 và 50.","h2":"Bạn bị rớt bài thi lái xe ở Missouri nếu bị trừ hơn 30 điểm.","p":"Đúng. Bị trừ hơn 30 điểm là bạn rớt."},"tl":{"q":"Sa Missouri, sa driving test ay nagbabawas ng puntos ang examiner sa bawat pagkakamali. Babagsak ka kung mawalan ka ng higit sa ilang puntos?","o":["10 puntos","20 puntos","50 puntos","30 puntos"],"h1":"Ito ay isang bilog na numero sa pagitan ng 20 at 50.","h2":"Babagsak ka sa driving test sa Missouri kung mawalan ka ng higit sa 30 puntos.","p":"Tama. Kapag nawalan ka ng higit sa 30 puntos, babagsak ka."},"ar":{"q":"في Missouri، أثناء امتحان القيادة يخصم الفاحص نقاطًا على الأخطاء. ترسب إذا خسرت أكثر من كم نقطة؟","o":["10 نقاط","20 نقطة","50 نقطة","30 نقطة"],"h1":"هو رقم مدوَّر بين 20 و50.","h2":"ترسب في امتحان القيادة في Missouri إذا خسرت أكثر من 30 نقطة.","p":"صحيح. إذا خسرت أكثر من 30 نقطة فأنت ترسب."},"ref":{"doc":"MO","page":21}},{"id":"mo-035","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what happens if you get 12 or more points on your record within 12 months?","o":["You get only a warning letter","Your license is revoked for one year","Your license is suspended for 30 days","Nothing happens until you reach 24 points"],"h1":"This is more serious than the result for 8 points.","h2":"Getting 12 or more points within 12 months means your Missouri license is revoked for one year.","p":"Right. 12 points in 12 months means a one-year revocation."},"es":{"q":"En Missouri, ¿qué pasa si acumula 12 puntos o más en su historial dentro de 12 meses?","o":["Solo recibe una carta de aviso","Le revocan la licencia por un año","Le suspenden la licencia por 30 días","No pasa nada hasta llegar a 24 puntos"],"h1":"Es más grave que lo que pasa con 8 puntos.","h2":"Si acumula 12 puntos o más dentro de 12 meses, le revocan la licencia de Missouri por un año.","p":"Correcto. 12 puntos en 12 meses significan una revocación de un año."},"zh":{"q":"在 Missouri，如果你在 12 个月内记录上有 12 分或更多，会怎么样？","o":["你只会收到一封警告信","你的驾照会被吊销一年","你的驾照会被暂停 30 天","到 24 分以前都不会有事"],"h1":"这比 8 分的结果更严重。","h2":"在 12 个月内得到 12 分或更多，你的 Missouri 驾照会被吊销一年。","p":"对。12 个月内 12 分，驾照会被吊销一年。"},"vi":{"q":"Ở Missouri, điều gì xảy ra nếu hồ sơ của bạn có 12 điểm trở lên trong vòng 12 tháng?","o":["Bạn chỉ nhận một thư cảnh cáo","Bằng lái của bạn bị thu hồi một năm","Bằng lái của bạn bị đình chỉ 30 ngày","Không có gì xảy ra cho đến khi bạn đủ 24 điểm"],"h1":"Điều này nặng hơn kết quả khi có 8 điểm.","h2":"Có 12 điểm trở lên trong vòng 12 tháng nghĩa là bằng lái Missouri của bạn bị thu hồi một năm.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị thu hồi bằng một năm."},"tl":{"q":"Sa Missouri, ano ang mangyayari kung magkaroon ka ng 12 puntos o higit pa sa iyong record sa loob ng 12 buwan?","o":["Warning letter lang ang matatanggap mo","Babawiin ang lisensya mo nang isang taon","Sususpindihin ang lisensya mo nang 30 araw","Walang mangyayari hangga't hindi ka umaabot sa 24 puntos"],"h1":"Mas mabigat ito kaysa sa resulta para sa 8 puntos.","h2":"Kapag nagkaroon ka ng 12 puntos o higit pa sa loob ng 12 buwan, babawiin ang lisensya mo sa Missouri nang isang taon.","p":"Tama. Ang 12 puntos sa 12 buwan ay nangangahulugang babawiin ang lisensya nang isang taon."},"ar":{"q":"في Missouri، ماذا يحدث إذا حصلت على 12 نقطة أو أكثر في سجلك خلال 12 شهرًا؟","o":["تحصل على رسالة تحذير فقط","تُلغى رخصتك لمدة سنة","تُعلَّق رخصتك لمدة 30 يومًا","لا يحدث شيء حتى تصل إلى 24 نقطة"],"h1":"هذا أشد من نتيجة 8 نقاط.","h2":"إذا حصلت على 12 نقطة أو أكثر خلال 12 شهرًا تُلغى رخصتك في Missouri لمدة سنة.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إلغاء الرخصة لمدة سنة."},"ref":{"doc":"MO","page":73}},{"id":"mo-036","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, an officer finds your blood alcohol is 0.08% or more, takes your license and gives you a notice. When does the suspension or revocation start?","o":["After 15 days","The next morning","After 6 months","Only after a jury trial"],"h1":"The notice can include a short temporary driving permit.","h2":"The suspension or revocation starts 15 days after the officer gives you the notice.","p":"Right. You lose the right to drive after 15 days."},"es":{"q":"En Missouri, un oficial encuentra que su nivel de alcohol en la sangre es de 0.08% o más, le quita la licencia y le da un aviso. ¿Cuándo empieza la suspensión o revocación?","o":["Después de 15 días","A la mañana siguiente","Después de 6 meses","Solo después de un juicio con jurado"],"h1":"El aviso puede incluir un permiso temporal corto para manejar.","h2":"La suspensión o revocación empieza 15 días después de que el oficial le da el aviso.","p":"Correcto. Pierde el derecho a manejar después de 15 días."},"zh":{"q":"在 Missouri，警察发现你的血液酒精浓度是 0.08% 或更高，拿走你的驾照并给你一份通知。暂停或吊销什么时候开始？","o":["15 天后","第二天早上","6 个月后","只有在陪审团审判后"],"h1":"这份通知可以包括一张短期的临时驾驶许可。","h2":"暂停或吊销在警察给你通知 15 天后开始。","p":"对。15 天后你就失去开车的权利。"},"vi":{"q":"Ở Missouri, cảnh sát thấy nồng độ cồn trong máu của bạn là 0.08% trở lên, lấy bằng lái của bạn và đưa bạn một thông báo. Khi nào việc đình chỉ hoặc thu hồi bắt đầu?","o":["Sau 15 ngày","Sáng hôm sau","Sau 6 tháng","Chỉ sau một phiên tòa có bồi thẩm đoàn"],"h1":"Thông báo có thể kèm một giấy phép lái xe tạm thời ngắn hạn.","h2":"Việc đình chỉ hoặc thu hồi bắt đầu 15 ngày sau khi cảnh sát đưa bạn thông báo.","p":"Đúng. Bạn mất quyền lái xe sau 15 ngày."},"tl":{"q":"Sa Missouri, nalaman ng pulis na 0.08% o higit pa ang alcohol sa dugo mo, kinuha niya ang lisensya mo at binigyan ka ng notice. Kailan magsisimula ang suspension o revocation?","o":["Pagkalipas ng 15 araw","Kinabukasan ng umaga","Pagkalipas ng 6 na buwan","Pagkatapos lang ng jury trial"],"h1":"Puwedeng may kasamang maikling temporary driving permit ang notice.","h2":"Magsisimula ang suspension o revocation 15 araw pagkatapos ibigay sa iyo ng pulis ang notice.","p":"Tama. Mawawala ang karapatan mong magmaneho pagkalipas ng 15 araw."},"ar":{"q":"في Missouri، وجد شرطي أن نسبة الكحول في دمك 0.08% أو أكثر، فأخذ رخصتك وأعطاك إشعارًا. متى يبدأ التعليق أو الإلغاء؟","o":["بعد 15 يومًا","في صباح اليوم التالي","بعد 6 أشهر","فقط بعد محاكمة أمام هيئة محلّفين"],"h1":"يمكن أن يتضمن الإشعار تصريح قيادة مؤقتًا قصيرًا.","h2":"يبدأ التعليق أو الإلغاء بعد 15 يومًا من إعطاء الشرطي الإشعار لك.","p":"صحيح. تفقد حق القيادة بعد 15 يومًا."},"ref":{"doc":"MO","page":67}},{"id":"mo-037","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, under the Abuse and Lose law, a driver under 21 is found guilty of an alcohol-related traffic offense. How long can the license be taken away?","o":["10 days","2 years","5 years","90 days"],"h1":"It is about three months.","h2":"Under Missouri's Abuse and Lose law, a driver under 21 can lose the license for 90 days.","p":"Right. Abuse and Lose means 90 days without a license."},"es":{"q":"En Missouri, según la ley Abuse and Lose, un conductor menor de 21 años es declarado culpable de una infracción de tránsito relacionada con alcohol. ¿Por cuánto tiempo le pueden quitar la licencia?","o":["10 días","2 años","5 años","90 días"],"h1":"Son unos tres meses.","h2":"Según la ley Abuse and Lose de Missouri, un conductor menor de 21 años puede perder la licencia por 90 días.","p":"Correcto. Abuse and Lose significa 90 días sin licencia."},"zh":{"q":"在 Missouri，根据 Abuse and Lose 法，一名 21 岁以下的司机被判犯有与酒精有关的交通违法。驾照可以被拿走多久？","o":["10 天","2 年","5 年","90 天"],"h1":"大约三个月。","h2":"根据 Missouri 的 Abuse and Lose 法，21 岁以下的司机可能会失去驾照 90 天。","p":"对。Abuse and Lose 意思是 90 天没有驾照。"},"vi":{"q":"Ở Missouri, theo luật Abuse and Lose, một tài xế dưới 21 tuổi bị kết tội vi phạm giao thông liên quan đến rượu bia. Bằng lái có thể bị lấy đi bao lâu?","o":["10 ngày","2 năm","5 năm","90 ngày"],"h1":"Khoảng ba tháng.","h2":"Theo luật Abuse and Lose của Missouri, tài xế dưới 21 tuổi có thể bị mất bằng lái 90 ngày.","p":"Đúng. Abuse and Lose nghĩa là 90 ngày không có bằng lái."},"tl":{"q":"Sa Missouri, sa ilalim ng Abuse and Lose law, napatunayang nagkasala ang isang driver na wala pang 21 sa isang traffic offense na may kinalaman sa alak. Gaano katagal puwedeng kunin ang lisensya?","o":["10 araw","2 taon","5 taon","90 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa ilalim ng Abuse and Lose law ng Missouri, puwedeng mawalan ng lisensya nang 90 araw ang driver na wala pang 21.","p":"Tama. Ang Abuse and Lose ay 90 araw na walang lisensya."},"ar":{"q":"في Missouri، وفق قانون Abuse and Lose، أُدين سائق عمره أقل من 21 سنة بمخالفة مرورية متعلقة بالكحول. ما المدة التي يمكن أن تُسحب فيها رخصته؟","o":["10 أيام","2 سنة","5 سنوات","90 يومًا"],"h1":"هي نحو ثلاثة أشهر.","h2":"وفق قانون Abuse and Lose في Missouri، يمكن أن يفقد السائق الذي عمره أقل من 21 سنة رخصته لمدة 90 يومًا.","p":"صحيح. Abuse and Lose تعني 90 يومًا بلا رخصة."},"ref":{"doc":"MO","page":69}},{"id":"mo-038","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you must report a crash to the Driver License Bureau when someone had no insurance and property damage is more than what amount?","o":["$250","$500","$1,000","$2,500"],"h1":"It is less than one thousand dollars.","h2":"You must report the crash when someone was uninsured and property damage is more than $500, or someone was hurt or killed.","p":"Right. The line is more than $500 in damage."},"es":{"q":"En Missouri, debe reportar un choque a la Oficina de Licencias de Conducir cuando alguien no tenía seguro y los daños a la propiedad pasan de cierta cantidad. ¿Cuál es esa cantidad?","o":["$250","$500","$1,000","$2,500"],"h1":"Es menos de mil dólares.","h2":"Debe reportar el choque cuando alguien no tenía seguro y los daños a la propiedad pasan de $500, o cuando alguien resultó herido o muerto.","p":"Correcto. El límite es más de $500 en daños."},"zh":{"q":"在 Missouri，当有人没有保险、而且财产损失超过多少钱时，你必须向驾照局（Driver License Bureau）报告车祸？","o":["$250","$500","$1,000","$2,500"],"h1":"不到一千美元。","h2":"当有人没有保险而且财产损失超过 $500，或者有人受伤或死亡时，你必须报告车祸。","p":"对。界线是损失超过 $500。"},"vi":{"q":"Ở Missouri, bạn phải báo tai nạn cho Phòng Bằng Lái Xe (Driver License Bureau) khi có người không có bảo hiểm và thiệt hại tài sản hơn bao nhiêu tiền?","o":["$250","$500","$1,000","$2,500"],"h1":"Ít hơn một nghìn đô la.","h2":"Bạn phải báo tai nạn khi có người không có bảo hiểm và thiệt hại tài sản hơn $500, hoặc khi có người bị thương hay tử vong.","p":"Đúng. Mức giới hạn là thiệt hại hơn $500."},"tl":{"q":"Sa Missouri, dapat mong i-report ang isang aksidente sa Driver License Bureau kapag may walang insurance at ang pinsala sa ari-arian ay higit sa anong halaga?","o":["$250","$500","$1,000","$2,500"],"h1":"Mas mababa ito sa isang libong dolyar.","h2":"Dapat mong i-report ang aksidente kapag may walang insurance at ang pinsala sa ari-arian ay higit sa $500, o kapag may nasaktan o namatay.","p":"Tama. Ang hangganan ay higit sa $500 na pinsala."},"ar":{"q":"في Missouri، يجب أن تبلّغ مكتب رخص القيادة (Driver License Bureau) عن الحادث عندما لا يكون لدى أحد تأمين وتزيد الأضرار في الممتلكات على أي مبلغ؟","o":["$250","$500","$1,000","$2,500"],"h1":"هو أقل من ألف دولار.","h2":"يجب أن تبلّغ عن الحادث عندما لا يكون لدى أحد تأمين وتزيد الأضرار في الممتلكات على $500، أو عندما يُصاب أحد أو يموت.","p":"صحيح. الحدّ هو أضرار تزيد على $500."},"ref":{"doc":"MO","page":82}},{"id":"mo-039","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, what is the lowest speed you may drive on an interstate highway in normal conditions?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"It is well below the maximum speed limit.","h2":"In normal conditions you may not drive slower than 40 mph on a Missouri interstate.","p":"Right. The minimum on interstates is 40 mph."},"es":{"q":"En Missouri, ¿cuál es la velocidad más baja a la que puede manejar en una autopista interestatal en condiciones normales?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"Está muy por debajo del límite máximo.","h2":"En condiciones normales no puede manejar a menos de 40 mph en una interestatal de Missouri.","p":"Correcto. La mínima en las interestatales es 40 mph."},"zh":{"q":"在 Missouri，在正常情况下，在州际公路上你可以开的最低速度是多少？","o":["30 英里/小时","45 英里/小时","40 英里/小时","55 英里/小时"],"h1":"它比最高限速低很多。","h2":"在正常情况下，你在 Missouri 的州际公路上不可以开得比 40 英里/小时慢。","p":"对。州际公路的最低速度是 40 英里/小时。"},"vi":{"q":"Ở Missouri, trong điều kiện bình thường, tốc độ thấp nhất bạn được chạy trên xa lộ liên bang là bao nhiêu?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"Nó thấp hơn nhiều so với tốc độ tối đa.","h2":"Trong điều kiện bình thường, bạn không được chạy chậm hơn 40 mph trên xa lộ liên bang ở Missouri.","p":"Đúng. Tốc độ tối thiểu trên xa lộ liên bang là 40 mph."},"tl":{"q":"Sa Missouri, ano ang pinakamababang bilis na puwede mong takbuhin sa interstate highway kapag normal ang kondisyon?","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"Mas mababa ito nang malaki sa maximum speed limit.","h2":"Kapag normal ang kondisyon, hindi ka puwedeng magmaneho nang mas mabagal sa 40 mph sa interstate sa Missouri.","p":"Tama. Ang minimum sa interstate ay 40 mph."},"ar":{"q":"في Missouri، ما أقل سرعة يُسمح لك أن تقود بها على طريق سريع بين الولايات في الظروف العادية؟","o":["30 mph","45 mph","40 mph","55 mph"],"h1":"هي أقل بكثير من الحدّ الأقصى للسرعة.","h2":"في الظروف العادية يجب ألّا تقود أبطأ من 40 mph على طريق سريع بين الولايات في Missouri.","p":"صحيح. الحدّ الأدنى على الطرق السريعة بين الولايات هو 40 mph."},"ref":{"doc":"MO","page":50}},{"id":"mo-040","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, what is the speed limit in a city, town or village when no other limit is posted?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"It is the same number many states use for neighborhoods.","h2":"The speed limit in any Missouri city, town or village is 25 mph unless a sign shows a different limit.","p":"Right. Unless posted otherwise, it is 25 mph in town."},"es":{"q":"En Missouri, ¿cuál es el límite de velocidad en una ciudad, pueblo o aldea cuando no hay otro límite señalado?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"Es el mismo número que muchos estados usan en los vecindarios.","h2":"El límite de velocidad en cualquier ciudad, pueblo o aldea de Missouri es 25 mph, a menos que un letrero indique otro.","p":"Correcto. Si no hay otro letrero, es 25 mph en la ciudad."},"zh":{"q":"在 Missouri，没有标出其他限速时，市、镇或村里的限速是多少？","o":["25 英里/小时","20 英里/小时","30 英里/小时","35 英里/小时"],"h1":"很多州在住宅区也用这个数字。","h2":"Missouri 任何市、镇或村里的限速都是 25 英里/小时，除非标志写着别的限速。","p":"对。除非另有标志，镇里的限速是 25 英里/小时。"},"vi":{"q":"Ở Missouri, tốc độ giới hạn trong thành phố, thị trấn hoặc làng là bao nhiêu khi không có biển báo giới hạn khác?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"Đó là con số mà nhiều tiểu bang dùng cho khu dân cư.","h2":"Tốc độ giới hạn trong bất kỳ thành phố, thị trấn hoặc làng nào ở Missouri là 25 mph, trừ khi biển báo ghi giới hạn khác.","p":"Đúng. Nếu không có biển báo khác, tốc độ trong thị trấn là 25 mph."},"tl":{"q":"Sa Missouri, ano ang speed limit sa isang city, town o village kapag walang ibang limit na nakapaskil?","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"Ito rin ang numerong ginagamit ng maraming state sa mga neighborhood.","h2":"Ang speed limit sa anumang city, town o village sa Missouri ay 25 mph, maliban kung iba ang limit na nakasulat sa sign.","p":"Tama. Kung walang ibang nakapaskil, 25 mph sa bayan."},"ar":{"q":"في Missouri، ما حدّ السرعة في مدينة أو بلدة أو قرية عندما لا تكون هناك لافتة بحدّ آخر؟","o":["25 mph","20 mph","30 mph","35 mph"],"h1":"هو الرقم نفسه الذي تستعمله ولايات كثيرة في الأحياء السكنية.","h2":"حدّ السرعة في أي مدينة أو بلدة أو قرية في Missouri هو 25 mph، إلا إذا أظهرت لافتة حدًّا مختلفًا.","p":"صحيح. ما لم تكن هناك لافتة أخرى، الحدّ في البلدة هو 25 mph."},"ref":{"doc":"MO","page":50}},{"id":"mo-041","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, you may not pass on the left when you are within how many feet of an intersection or railroad crossing?","o":["50 feet","300 feet","500 feet","100 feet"],"h1":"The same distance applies near bridges and tunnels when your view is blocked.","h2":"You may not pass on the left within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of an intersection or railroad crossing."},"es":{"q":"En Missouri, ¿a menos de cuántos pies de una intersección o un cruce de ferrocarril no puede rebasar por la izquierda?","o":["50 pies","300 pies","500 pies","100 pies"],"h1":"La misma distancia se aplica cerca de puentes y túneles cuando la vista está bloqueada.","h2":"No puede rebasar por la izquierda a menos de 100 pies de una intersección o un cruce de ferrocarril.","p":"Correcto. No se rebasa a menos de 100 pies de una intersección o cruce de ferrocarril."},"zh":{"q":"在 Missouri，你离路口或铁路道口多少英尺以内时，不可以从左边超车？","o":["50 英尺","300 英尺","500 英尺","100 英尺"],"h1":"在视线被挡住的桥和隧道附近，也是同样的距离。","h2":"你不可以在路口或铁路道口 100 英尺以内从左边超车。","p":"对。在路口或铁路道口 100 英尺以内不能超车。"},"vi":{"q":"Ở Missouri, bạn không được vượt bên trái khi cách giao lộ hoặc chỗ băng qua đường ray xe lửa trong vòng bao nhiêu feet?","o":["50 feet","300 feet","500 feet","100 feet"],"h1":"Khoảng cách này cũng áp dụng gần cầu và đường hầm khi tầm nhìn bị che.","h2":"Bạn không được vượt bên trái trong vòng 100 feet của giao lộ hoặc chỗ băng qua đường ray xe lửa.","p":"Đúng. Không được vượt trong vòng 100 feet của giao lộ hoặc chỗ băng qua đường ray."},"tl":{"q":"Sa Missouri, hindi ka puwedeng mag-overtake sa kaliwa kapag nasa loob ka ng ilang talampakan mula sa intersection o railroad crossing?","o":["50 talampakan","300 talampakan","500 talampakan","100 talampakan"],"h1":"Ganito rin ang layo malapit sa mga tulay at tunnel kapag natatakpan ang tanaw mo.","h2":"Hindi ka puwedeng mag-overtake sa kaliwa sa loob ng 100 talampakan mula sa intersection o railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 talampakan mula sa intersection o railroad crossing."},"ar":{"q":"في Missouri، لا يُسمح لك بالتجاوز من اليسار عندما تكون على بُعد أقل من كم قدمًا من تقاطع أو معبر سكة حديد؟","o":["50 قدمًا","300 قدم","500 قدم","100 قدم"],"h1":"المسافة نفسها تنطبق قرب الجسور والأنفاق عندما يكون نظرك محجوبًا.","h2":"يجب ألّا تتجاوز من اليسار على بُعد أقل من 100 قدم من تقاطع أو معبر سكة حديد.","p":"صحيح. لا تجاوز على بُعد أقل من 100 قدم من تقاطع أو معبر سكة حديد."},"ref":{"doc":"MO","page":22}},{"id":"mo-042","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, what is the smallest fine for a first offense of speeding or passing in a work zone on state roads?","o":["$50","$250","$100","$1,000"],"h1":"A second offense costs at least $300.","h2":"A first offense of speeding or passing in a Missouri work zone carries a fine of at least $250.","p":"Right. The first offense costs at least $250."},"es":{"q":"En Missouri, ¿cuál es la multa mínima por una primera infracción de exceso de velocidad o de rebasar en una zona de trabajo en carreteras estatales?","o":["$50","$250","$100","$1,000"],"h1":"Una segunda infracción cuesta por lo menos $300.","h2":"Una primera infracción de exceso de velocidad o de rebasar en una zona de trabajo de Missouri tiene una multa de al menos $250.","p":"Correcto. La primera infracción cuesta al menos $250."},"zh":{"q":"在 Missouri，在州公路的施工区第一次超速或超车，最低罚款是多少？","o":["$50","$250","$100","$1,000"],"h1":"第二次违法至少要罚 $300。","h2":"在 Missouri 的施工区第一次超速或超车，罚款至少是 $250。","p":"对。第一次违法至少罚 $250。"},"vi":{"q":"Ở Missouri, tiền phạt thấp nhất cho lần vi phạm đầu tiên vì chạy quá tốc độ hoặc vượt xe trong khu công trường trên đường của tiểu bang là bao nhiêu?","o":["$50","$250","$100","$1,000"],"h1":"Lần vi phạm thứ hai bị phạt ít nhất $300.","h2":"Lần vi phạm đầu tiên vì chạy quá tốc độ hoặc vượt xe trong khu công trường ở Missouri bị phạt ít nhất $250.","p":"Đúng. Lần vi phạm đầu tiên bị phạt ít nhất $250."},"tl":{"q":"Sa Missouri, ano ang pinakamaliit na multa sa unang paglabag sa pag-overspeed o pag-overtake sa work zone sa mga state road?","o":["$50","$250","$100","$1,000"],"h1":"Ang ikalawang paglabag ay hindi bababa sa $300.","h2":"Ang unang paglabag sa pag-overspeed o pag-overtake sa work zone sa Missouri ay may multang hindi bababa sa $250.","p":"Tama. Hindi bababa sa $250 ang multa sa unang paglabag."},"ar":{"q":"في Missouri، ما أقل غرامة على أول مخالفة للسرعة الزائدة أو التجاوز في منطقة أعمال على طرق الولاية؟","o":["$50","$250","$100","$1,000"],"h1":"المخالفة الثانية تكلّف $300 على الأقل.","h2":"أول مخالفة للسرعة الزائدة أو التجاوز في منطقة أعمال في Missouri غرامتها $250 على الأقل.","p":"صحيح. أول مخالفة تكلّف $250 على الأقل."},"ref":{"doc":"MO","page":22}},{"id":"mo-043","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, how many points are added to your record if you are found guilty of not stopping for a school bus that is loading or unloading students?","o":["2 points","3 points","5 points","12 points"],"h1":"It is more than the points for speeding.","h2":"Failing to stop for a school bus that is loading or unloading students adds five points to your Missouri record.","p":"Right. Passing a stopped school bus costs five points."},"es":{"q":"En Missouri, ¿cuántos puntos se agregan a su historial si lo declaran culpable de no detenerse ante un autobús escolar que sube o baja estudiantes?","o":["2 puntos","3 puntos","5 puntos","12 puntos"],"h1":"Son más que los puntos por exceso de velocidad.","h2":"No detenerse ante un autobús escolar que sube o baja estudiantes agrega cinco puntos a su historial de Missouri.","p":"Correcto. Pasar un autobús escolar detenido cuesta cinco puntos."},"zh":{"q":"在 Missouri，如果你被判没有为正在上下学生的校车停车，你的记录上会加几分？","o":["2 分","3 分","5 分","12 分"],"h1":"比超速的分数多。","h2":"没有为正在上下学生的校车停车，会在你的 Missouri 记录上加五分。","p":"对。超过停着的校车要扣五分。"},"vi":{"q":"Ở Missouri, hồ sơ của bạn bị cộng bao nhiêu điểm nếu bạn bị kết tội không dừng lại cho xe buýt trường học đang đón hoặc thả học sinh?","o":["2 điểm","3 điểm","5 điểm","12 điểm"],"h1":"Nhiều hơn số điểm cho lỗi chạy quá tốc độ.","h2":"Không dừng lại cho xe buýt trường học đang đón hoặc thả học sinh sẽ bị cộng năm điểm vào hồ sơ Missouri của bạn.","p":"Đúng. Vượt xe buýt trường học đang dừng bị năm điểm."},"tl":{"q":"Sa Missouri, ilang puntos ang madadagdag sa record mo kung mapatunayang hindi ka huminto para sa school bus na nagsasakay o nagbababa ng mga estudyante?","o":["2 puntos","3 puntos","5 puntos","12 puntos"],"h1":"Mas marami ito kaysa sa puntos para sa pag-overspeed.","h2":"Kapag hindi ka huminto para sa school bus na nagsasakay o nagbababa ng mga estudyante, madadagdagan ng limang puntos ang record mo sa Missouri.","p":"Tama. Limang puntos ang paglampas sa nakahintong school bus."},"ar":{"q":"في Missouri، كم نقطة تُضاف إلى سجلك إذا أُدنت بعدم التوقف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها؟","o":["2 نقطة","3 نقاط","5 نقاط","12 نقطة"],"h1":"هي أكثر من نقاط السرعة الزائدة.","h2":"عدم التوقف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يضيف خمس نقاط إلى سجلك في Missouri.","p":"صحيح. تجاوز حافلة مدرسية متوقفة يكلّف خمس نقاط."},"ref":{"doc":"MO","page":24}},{"id":"mo-044","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, the red lights are flashing at a railroad crossing. Where must you stop?","o":["Between 15 and 50 feet from the tracks","Right on top of the first rail","Within 5 feet of the tracks","At least 200 feet from the tracks"],"h1":"Not too close and not too far from the nearest rail.","h2":"When you must stop at a Missouri railroad crossing, stop between 15 and 50 feet from the tracks.","p":"Right. Stop 15 to 50 feet before the tracks."},"es":{"q":"En Missouri, las luces rojas parpadean en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Entre 15 y 50 pies de las vías","Justo encima del primer riel","A menos de 5 pies de las vías","Por lo menos a 200 pies de las vías"],"h1":"Ni muy cerca ni muy lejos del riel más cercano.","h2":"Cuando debe detenerse en un cruce de ferrocarril en Missouri, deténgase entre 15 y 50 pies de las vías.","p":"Correcto. Deténgase de 15 a 50 pies antes de las vías."},"zh":{"q":"在 Missouri，铁路道口的红灯在闪。你必须在哪里停车？","o":["离铁轨 15 到 50 英尺之间","就停在第一条铁轨上","离铁轨 5 英尺以内","离铁轨至少 200 英尺"],"h1":"离最近的铁轨不要太近，也不要太远。","h2":"当你必须在 Missouri 的铁路道口停车时，要停在离铁轨 15 到 50 英尺之间。","p":"对。在铁轨前 15 到 50 英尺停车。"},"vi":{"q":"Ở Missouri, đèn đỏ đang nhấp nháy tại chỗ băng qua đường ray xe lửa. Bạn phải dừng ở đâu?","o":["Cách đường ray từ 15 đến 50 feet","Ngay trên thanh ray đầu tiên","Cách đường ray trong vòng 5 feet","Cách đường ray ít nhất 200 feet"],"h1":"Không quá gần và không quá xa thanh ray gần nhất.","h2":"Khi bạn phải dừng tại chỗ băng qua đường ray xe lửa ở Missouri, hãy dừng cách đường ray từ 15 đến 50 feet.","p":"Đúng. Dừng cách đường ray từ 15 đến 50 feet."},"tl":{"q":"Sa Missouri, kumikislap ang mga pulang ilaw sa isang railroad crossing. Saan ka dapat huminto?","o":["Sa pagitan ng 15 at 50 talampakan mula sa riles","Mismo sa ibabaw ng unang riles","Sa loob ng 5 talampakan mula sa riles","Hindi bababa sa 200 talampakan mula sa riles"],"h1":"Hindi masyadong malapit at hindi masyadong malayo sa pinakamalapit na riles.","h2":"Kapag kailangan mong huminto sa railroad crossing sa Missouri, huminto sa pagitan ng 15 at 50 talampakan mula sa riles.","p":"Tama. Huminto 15 hanggang 50 talampakan bago ang riles."},"ar":{"q":"في Missouri، الأضواء الحمراء تومض عند معبر سكة حديد. أين يجب أن تتوقف؟","o":["على بُعد بين 15 و50 قدمًا من السكة","فوق القضيب الأول مباشرة","على بُعد أقل من 5 أقدام من السكة","على بُعد 200 قدم على الأقل من السكة"],"h1":"ليس قريبًا جدًا ولا بعيدًا جدًا عن أقرب قضيب.","h2":"عندما يجب أن تتوقف عند معبر سكة حديد في Missouri، توقّف على بُعد بين 15 و50 قدمًا من السكة.","p":"صحيح. توقّف على بُعد 15 إلى 50 قدمًا قبل السكة."},"ref":{"doc":"MO","page":51}},{"id":"mo-045","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, an organized funeral procession is driving through an intersection against a red light. What should you do?","o":["Drive between the cars since your light is green","Join the end of the line to get through faster","Pass the cars in the procession on the right","Wait, because the procession has the right-of-way"],"h1":"The cars in the procession have their flashing lights on.","h2":"An organized funeral procession has the right-of-way at intersections, so you must wait and not cut through it.","p":"Right. Let the funeral procession pass."},"es":{"q":"En Missouri, un cortejo fúnebre organizado cruza una intersección con la luz roja. ¿Qué debe hacer?","o":["Pasar entre los autos porque su luz está en verde","Unirse al final de la fila para pasar más rápido","Rebasar los autos del cortejo por la derecha","Esperar, porque el cortejo tiene el derecho de paso"],"h1":"Los autos del cortejo llevan las luces intermitentes encendidas.","h2":"Un cortejo fúnebre organizado tiene el derecho de paso en las intersecciones, así que usted debe esperar y no cruzarlo.","p":"Correcto. Deje pasar el cortejo fúnebre."},"zh":{"q":"在 Missouri，一个有组织的送葬车队正在闯红灯通过路口。你应该怎么做？","o":["因为你的灯是绿灯，就从车辆中间开过去","跟在车队后面，好更快通过","从右边超过送葬车队的车","等待，因为送葬车队有优先通行权"],"h1":"送葬车队的车都开着闪光灯。","h2":"有组织的送葬车队在路口有优先通行权，所以你必须等待，不可以从车队中间穿过。","p":"对。让送葬车队先过。"},"vi":{"q":"Ở Missouri, một đoàn xe tang có tổ chức đang đi qua giao lộ khi đèn đỏ. Bạn nên làm gì?","o":["Chạy xen giữa các xe vì đèn của bạn đang xanh","Nhập vào cuối đoàn để đi qua nhanh hơn","Vượt các xe trong đoàn bên phải","Chờ, vì đoàn xe tang được quyền ưu tiên"],"h1":"Các xe trong đoàn đang bật đèn nhấp nháy.","h2":"Đoàn xe tang có tổ chức được quyền ưu tiên tại giao lộ, nên bạn phải chờ và không được chạy cắt ngang qua đoàn.","p":"Đúng. Hãy để đoàn xe tang đi qua."},"tl":{"q":"Sa Missouri, may organisadong funeral procession na dumadaan sa intersection kahit pula ang ilaw. Ano ang dapat mong gawin?","o":["Dumaan sa pagitan ng mga sasakyan dahil berde ang ilaw mo","Sumama sa dulo ng hanay para mas mabilis makadaan","Lampasan sa kanan ang mga sasakyan ng procession","Maghintay, dahil ang procession ang may right-of-way"],"h1":"Nakabukas ang mga flashing light ng mga sasakyan sa procession.","h2":"Ang organisadong funeral procession ang may right-of-way sa mga intersection, kaya dapat kang maghintay at huwag sumingit dito.","p":"Tama. Hayaang dumaan ang funeral procession."},"ar":{"q":"في Missouri، موكب جنازة منظَّم يعبر تقاطعًا والإشارة حمراء. ماذا يجب أن تفعل؟","o":["تقود بين السيارات لأن إشارتك خضراء","تنضم إلى آخر الصف لتعبر أسرع","تتجاوز سيارات الموكب من اليمين","تنتظر، لأن للموكب حق المرور"],"h1":"سيارات الموكب أضواؤها الوامضة مشغّلة.","h2":"موكب الجنازة المنظَّم له حق المرور عند التقاطعات، لذلك يجب أن تنتظر ويجب ألّا تقطعه.","p":"صحيح. دع موكب الجنازة يمرّ."},"ref":{"doc":"MO","page":33}},{"id":"mo-046","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, when the driver has a full license, which people in a passenger car does the seat belt law cover?","o":["Only the driver","The driver and front-seat passengers","Only passengers in the back seat","No one, it is a personal choice"],"h1":"Think about who sits in the front row.","h2":"Missouri's seat belt law requires the driver and front-seat passengers to wear a seat belt.","p":"Right. The driver and front-seat riders must buckle up."},"es":{"q":"En Missouri, cuando el conductor tiene licencia completa, ¿a qué personas de un auto de pasajeros cubre la ley del cinturón de seguridad?","o":["Solo al conductor","Al conductor y a los pasajeros del asiento delantero","Solo a los pasajeros del asiento trasero","A nadie, es una decisión personal"],"h1":"Piense en quiénes van en la fila de adelante.","h2":"La ley de Missouri exige que el conductor y los pasajeros del asiento delantero usen el cinturón de seguridad.","p":"Correcto. El conductor y quienes van adelante deben abrocharse."},"zh":{"q":"在 Missouri，当司机有正式驾照时，安全带法包括客车里的哪些人？","o":["只有司机","司机和前座乘客","只有后座乘客","没有人，这是个人选择"],"h1":"想一想谁坐在前排。","h2":"Missouri 的安全带法要求司机和前座乘客系安全带。","p":"对。司机和前座的人必须系好安全带。"},"vi":{"q":"Ở Missouri, khi tài xế có bằng lái đầy đủ, luật dây an toàn áp dụng cho những ai trong xe chở khách?","o":["Chỉ tài xế","Tài xế và hành khách ngồi ghế trước","Chỉ hành khách ngồi ghế sau","Không ai cả, đó là lựa chọn cá nhân"],"h1":"Hãy nghĩ xem ai ngồi ở hàng ghế trước.","h2":"Luật dây an toàn của Missouri bắt buộc tài xế và hành khách ngồi ghế trước phải thắt dây an toàn.","p":"Đúng. Tài xế và người ngồi ghế trước phải thắt dây an toàn."},"tl":{"q":"Sa Missouri, kapag may full license ang driver, sino-sino sa isang passenger car ang sakop ng seat belt law?","o":["Ang driver lang","Ang driver at ang mga pasahero sa harap","Ang mga pasahero sa likod lang","Wala, personal na desisyon ito"],"h1":"Isipin kung sino ang nakaupo sa unahang hanay.","h2":"Ayon sa seat belt law ng Missouri, dapat magsuot ng seat belt ang driver at ang mga pasahero sa harap.","p":"Tama. Dapat mag-seat belt ang driver at ang mga nakaupo sa harap."},"ar":{"q":"في Missouri، عندما يكون مع السائق رخصة كاملة، مَن من الأشخاص في سيارة الركاب يشملهم قانون حزام الأمان؟","o":["السائق فقط","السائق وركّاب المقعد الأمامي","ركّاب المقعد الخلفي فقط","لا أحد، فهو اختيار شخصي"],"h1":"فكّر في من يجلس في الصف الأمامي.","h2":"قانون حزام الأمان في Missouri يُلزم السائق وركّاب المقعد الأمامي بوضع حزام الأمان.","p":"صحيح. يجب على السائق ومن يجلس في الأمام أن يربطوا الحزام."},"ref":{"doc":"MO","page":55}},{"id":"mo-047","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, how must a child younger than four years old ride in a car, no matter how much the child weighs?","o":["With only the adult seat belt","Unbuckled if riding in the back seat","In a child safety seat that fits the child","On an adult's lap, held tightly"],"h1":"Very young children need special equipment.","h2":"A child under four in Missouri must ride in a child safety seat that is right for that child, whatever the child's weight.","p":"Right. Children under four ride in a child safety seat."},"es":{"q":"En Missouri, ¿cómo debe viajar en un auto un niño menor de cuatro años, sin importar cuánto pese?","o":["Solo con el cinturón de adulto","Sin abrochar si va en el asiento trasero","En un asiento de seguridad adecuado para el niño","En las piernas de un adulto, bien sujeto"],"h1":"Los niños muy pequeños necesitan un equipo especial.","h2":"En Missouri, un niño menor de cuatro años debe viajar en un asiento de seguridad adecuado para él, pese lo que pese.","p":"Correcto. Los niños menores de cuatro años van en un asiento de seguridad."},"zh":{"q":"在 Missouri，不满四岁的孩子不管多重，坐车时必须怎么坐？","o":["只用大人的安全带","坐后座就可以不系安全带","坐在适合这个孩子的儿童安全座椅里","坐在大人的腿上，被紧紧抱住"],"h1":"很小的孩子需要特别的装备。","h2":"在 Missouri，不满四岁的孩子不管体重多少，都必须坐在适合这个孩子的儿童安全座椅里。","p":"对。不满四岁的孩子要坐儿童安全座椅。"},"vi":{"q":"Ở Missouri, một đứa trẻ dưới bốn tuổi phải ngồi xe như thế nào, dù cân nặng bao nhiêu?","o":["Chỉ dùng dây an toàn của người lớn","Không cần thắt dây nếu ngồi ghế sau","Ngồi trong ghế an toàn trẻ em vừa với đứa trẻ","Ngồi trên đùi người lớn, được giữ chặt"],"h1":"Trẻ còn rất nhỏ cần thiết bị đặc biệt.","h2":"Ở Missouri, trẻ dưới bốn tuổi phải ngồi trong ghế an toàn trẻ em phù hợp với đứa trẻ đó, dù cân nặng bao nhiêu.","p":"Đúng. Trẻ dưới bốn tuổi ngồi trong ghế an toàn trẻ em."},"tl":{"q":"Sa Missouri, paano dapat sumakay sa kotse ang batang wala pang apat na taong gulang, kahit gaano pa kabigat ang bata?","o":["Gamit lang ang seat belt ng matanda","Walang seat belt kung nasa likod","Sa child safety seat na akma sa bata","Nakakandong sa matanda, mahigpit na hawak"],"h1":"Kailangan ng espesyal na kagamitan ang napakaliliit na bata.","h2":"Sa Missouri, ang batang wala pang apat na taon ay dapat sumakay sa child safety seat na akma sa kanya, anuman ang timbang niya.","p":"Tama. Sa child safety seat sumasakay ang mga batang wala pang apat na taon."},"ar":{"q":"في Missouri، كيف يجب أن يركب الطفل الذي عمره أقل من أربع سنوات في السيارة، مهما كان وزنه؟","o":["بحزام الأمان الخاص بالكبار فقط","بلا حزام إذا كان في المقعد الخلفي","في مقعد أمان للأطفال مناسب للطفل","في حضن شخص بالغ يمسكه بقوة"],"h1":"الأطفال الصغار جدًا يحتاجون إلى معدات خاصة.","h2":"في Missouri يجب أن يركب الطفل الذي عمره أقل من أربع سنوات في مقعد أمان للأطفال مناسب له، مهما كان وزنه.","p":"صحيح. الأطفال تحت أربع سنوات يركبون في مقعد أمان للأطفال."},"ref":{"doc":"MO","page":55}},{"id":"mo-048","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, you are using high beams at night. A car comes toward you. Within how many feet must you switch to low beams?","o":["200 feet","350 feet","500 feet","1,000 feet"],"h1":"The guide says it is about one block.","h2":"You must switch to low beams when an oncoming vehicle is within 500 feet.","p":"Right. Dim your lights within 500 feet of an oncoming car."},"es":{"q":"En Missouri, usted maneja de noche con las luces altas. Viene un auto de frente. ¿A cuántos pies debe cambiar a luces bajas?","o":["200 pies","350 pies","500 pies","1,000 pies"],"h1":"La guía dice que es más o menos una cuadra.","h2":"Debe cambiar a luces bajas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Baje las luces a 500 pies de un auto que viene de frente."},"zh":{"q":"在 Missouri，你晚上开着远光灯。对面来了一辆车。在多少英尺以内你必须换成近光灯？","o":["200 英尺","350 英尺","500 英尺","1,000 英尺"],"h1":"指南说大约是一个街区。","h2":"当对面来的车在 500 英尺以内时，你必须换成近光灯。","p":"对。对面来车在 500 英尺以内时，把灯调暗。"},"vi":{"q":"Ở Missouri, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Một xe chạy ngược chiều tới. Trong vòng bao nhiêu feet bạn phải chuyển sang đèn cốt (đèn chiếu gần)?","o":["200 feet","350 feet","500 feet","1,000 feet"],"h1":"Sách hướng dẫn nói khoảng một dãy nhà.","h2":"Bạn phải chuyển sang đèn cốt khi xe chạy ngược chiều ở trong vòng 500 feet.","p":"Đúng. Giảm đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Missouri, naka-high beam ka sa gabi. May sasakyang paparating sa harap mo. Sa loob ng ilang talampakan ka dapat lumipat sa low beam?","o":["200 talampakan","350 talampakan","500 talampakan","1,000 talampakan"],"h1":"Sabi ng guide, mga isang block ito.","h2":"Dapat kang lumipat sa low beam kapag nasa loob ng 500 talampakan ang paparating na sasakyan.","p":"Tama. Hinaan ang ilaw sa loob ng 500 talampakan mula sa paparating na sasakyan."},"ar":{"q":"في Missouri، تستعمل الأضواء العالية ليلًا. سيارة تأتي نحوك. على بُعد أقل من كم قدمًا يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["200 قدم","350 قدمًا","500 قدم","1,000 قدم"],"h1":"يقول الدليل إنها نحو شارع واحد (block).","h2":"يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة نحوك على بُعد أقل من 500 قدم.","p":"صحيح. خفّض أضواءك على بُعد 500 قدم من السيارة القادمة."},"ref":{"doc":"MO","page":62}},{"id":"mo-049","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, how much space should you leave behind the car ahead when driving on snow or ice?","o":["About 1 second","About 2 seconds","About 3 seconds","About 8 to 10 seconds"],"h1":"It is much more than on a dry road.","h2":"On snow or ice, leave about eight to ten seconds between you and the vehicle ahead.","p":"Right. On snow or ice, keep about 8 to 10 seconds of space."},"es":{"q":"En Missouri, ¿cuánto espacio debe dejar detrás del auto de adelante cuando maneja sobre nieve o hielo?","o":["Más o menos 1 segundo","Más o menos 2 segundos","Más o menos 3 segundos","Más o menos de 8 a 10 segundos"],"h1":"Es mucho más que en una carretera seca.","h2":"Sobre nieve o hielo, deje entre ocho y diez segundos entre usted y el vehículo de adelante.","p":"Correcto. Sobre nieve o hielo, deje de 8 a 10 segundos de espacio."},"zh":{"q":"在 Missouri，在雪地或冰上开车时，你应该和前车保持多少距离？","o":["大约 1 秒","大约 2 秒","大约 3 秒","大约 8 到 10 秒"],"h1":"比干燥路面多很多。","h2":"在雪地或冰上，你和前车之间要保持大约八到十秒的距离。","p":"对。在雪地或冰上，保持大约 8 到 10 秒的距离。"},"vi":{"q":"Ở Missouri, khi lái xe trên tuyết hoặc băng, bạn nên chừa khoảng cách bao nhiêu với xe phía trước?","o":["Khoảng 1 giây","Khoảng 2 giây","Khoảng 3 giây","Khoảng 8 đến 10 giây"],"h1":"Nhiều hơn nhiều so với trên đường khô.","h2":"Trên tuyết hoặc băng, hãy chừa khoảng tám đến mười giây giữa bạn và xe phía trước.","p":"Đúng. Trên tuyết hoặc băng, giữ khoảng cách khoảng 8 đến 10 giây."},"tl":{"q":"Sa Missouri, gaano kalaking espasyo ang dapat mong iwan sa likod ng sasakyan sa unahan kapag nagmamaneho sa niyebe o yelo?","o":["Mga 1 segundo","Mga 2 segundo","Mga 3 segundo","Mga 8 hanggang 10 segundo"],"h1":"Mas malaki ito nang husto kaysa sa tuyong kalsada.","h2":"Sa niyebe o yelo, mag-iwan ng mga walo hanggang sampung segundo sa pagitan mo at ng sasakyan sa unahan.","p":"Tama. Sa niyebe o yelo, mag-iwan ng mga 8 hanggang 10 segundong espasyo."},"ar":{"q":"في Missouri، ما المسافة التي يجب أن تتركها خلف السيارة التي أمامك عندما تقود على الثلج أو الجليد؟","o":["نحو ثانية واحدة","نحو ثانيتين","نحو 3 ثوانٍ","نحو 8 إلى 10 ثوانٍ"],"h1":"هي أكثر بكثير مما على طريق جاف.","h2":"على الثلج أو الجليد، اترك نحو ثماني إلى عشر ثوانٍ بينك وبين المركبة التي أمامك.","p":"صحيح. على الثلج أو الجليد، اترك مسافة نحو 8 إلى 10 ثوانٍ."},"ref":{"doc":"MO","page":63}},{"id":"mo-050","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, when may your car have studded snow tires?","o":["From November 1 to April 1","At any time of the year","Only in January and February","From October 1 to June 1"],"h1":"It covers the cold months, from late fall to early spring.","h2":"Missouri allows studded snow tires only from November 1 to April 1.","p":"Right. Studded tires are allowed November 1 to April 1."},"es":{"q":"En Missouri, ¿cuándo puede su auto tener llantas de nieve con clavos?","o":["Del 1 de noviembre al 1 de abril","En cualquier época del año","Solo en enero y febrero","Del 1 de octubre al 1 de junio"],"h1":"Cubre los meses fríos, de finales del otoño a principios de la primavera.","h2":"Missouri permite llantas de nieve con clavos solo del 1 de noviembre al 1 de abril.","p":"Correcto. Las llantas con clavos se permiten del 1 de noviembre al 1 de abril."},"zh":{"q":"在 Missouri，你的车什么时候可以用带钉的雪地轮胎？","o":["从 11 月 1 日到 4 月 1 日","一年中任何时候","只在一月和二月","从 10 月 1 日到 6 月 1 日"],"h1":"它包括寒冷的月份，从晚秋到早春。","h2":"Missouri 只允许从 11 月 1 日到 4 月 1 日使用带钉的雪地轮胎。","p":"对。带钉轮胎可以从 11 月 1 日用到 4 月 1 日。"},"vi":{"q":"Ở Missouri, khi nào xe của bạn được dùng lốp đi tuyết có đinh?","o":["Từ ngày 1 tháng 11 đến ngày 1 tháng 4","Bất cứ lúc nào trong năm","Chỉ trong tháng Một và tháng Hai","Từ ngày 1 tháng 10 đến ngày 1 tháng 6"],"h1":"Nó gồm những tháng lạnh, từ cuối mùa thu đến đầu mùa xuân.","h2":"Missouri chỉ cho phép lốp đi tuyết có đinh từ ngày 1 tháng 11 đến ngày 1 tháng 4.","p":"Đúng. Lốp có đinh được phép từ ngày 1 tháng 11 đến ngày 1 tháng 4."},"tl":{"q":"Sa Missouri, kailan puwedeng may studded snow tires ang sasakyan mo?","o":["Mula Nobyembre 1 hanggang Abril 1","Kahit anong oras ng taon","Sa Enero at Pebrero lang","Mula Oktubre 1 hanggang Hunyo 1"],"h1":"Saklaw nito ang malalamig na buwan, mula huling bahagi ng taglagas hanggang simula ng tagsibol.","h2":"Pinapayagan ng Missouri ang studded snow tires mula Nobyembre 1 hanggang Abril 1 lang.","p":"Tama. Pinapayagan ang studded tires mula Nobyembre 1 hanggang Abril 1."},"ar":{"q":"في Missouri، متى يُسمح بأن تكون في سيارتك إطارات ثلج ذات مسامير؟","o":["من 1 نوفمبر إلى 1 أبريل","في أي وقت من السنة","في يناير وفبراير فقط","من 1 أكتوبر إلى 1 يونيو"],"h1":"تشمل الأشهر الباردة، من أواخر الخريف إلى أوائل الربيع.","h2":"تسمح Missouri بإطارات الثلج ذات المسامير فقط من 1 نوفمبر إلى 1 أبريل.","p":"صحيح. الإطارات ذات المسامير مسموحة من 1 نوفمبر إلى 1 أبريل."},"ref":{"doc":"MO","page":85}},{"id":"mo-051","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, which cell phone number does the Driver Guide give for reporting a highway emergency?","o":["311","*55","*88","411"],"h1":"It starts with a star.","h2":"The Missouri Driver Guide says the cell phone number to call in a highway emergency is *55.","p":"Right. Dial *55 from a cell phone for a highway emergency."},"es":{"q":"En Missouri, ¿qué número de celular da la Guía del Conductor para reportar una emergencia en la carretera?","o":["311","*55","*88","411"],"h1":"Empieza con un asterisco.","h2":"La Guía del Conductor de Missouri dice que el número de celular para una emergencia en la carretera es *55.","p":"Correcto. Marque *55 desde un celular para una emergencia en la carretera."},"zh":{"q":"在 Missouri，驾驶指南（Driver Guide）给出的报告公路紧急情况的手机号码是哪一个？","o":["311","*55","*88","411"],"h1":"它以星号开头。","h2":"Missouri 驾驶指南说，遇到公路紧急情况时用手机拨打的号码是 *55。","p":"对。遇到公路紧急情况，用手机拨 *55。"},"vi":{"q":"Ở Missouri, Sách Hướng Dẫn Lái Xe (Driver Guide) cho số điện thoại di động nào để báo trường hợp khẩn cấp trên xa lộ?","o":["311","*55","*88","411"],"h1":"Nó bắt đầu bằng dấu sao.","h2":"Sách Hướng Dẫn Lái Xe Missouri nói số điện thoại di động để gọi khi có trường hợp khẩn cấp trên xa lộ là *55.","p":"Đúng. Bấm *55 từ điện thoại di động khi có trường hợp khẩn cấp trên xa lộ."},"tl":{"q":"Sa Missouri, anong numero sa cell phone ang ibinibigay ng Driver Guide para mag-report ng emergency sa highway?","o":["311","*55","*88","411"],"h1":"Nagsisimula ito sa star.","h2":"Sinasabi ng Missouri Driver Guide na ang numerong tatawagan sa cell phone kapag may emergency sa highway ay *55.","p":"Tama. I-dial ang *55 sa cell phone kapag may emergency sa highway."},"ar":{"q":"في Missouri، ما رقم الهاتف المحمول الذي يذكره دليل السائق (Driver Guide) للإبلاغ عن حالة طوارئ على الطريق السريع؟","o":["311","*55","*88","411"],"h1":"يبدأ بنجمة.","h2":"يقول دليل السائق في Missouri إن رقم الهاتف المحمول للاتصال في حالة طوارئ على الطريق السريع هو *55.","p":"صحيح. اتصل بـ *55 من الهاتف المحمول في حالة طوارئ على الطريق السريع."},"ref":{"doc":"MO","page":41}},{"id":"mo-052","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, you want a motorcycle instruction permit at 15 and a half. What must you finish first?","o":["A 40-hour motorcycle practice log","A motorcycle safety video at the license office","An approved motorcycle rider training course","A year of driving with a car permit"],"h1":"It is a course that teaches young riders.","h2":"In Missouri, a motorcycle instruction permit at 15 and a half is issued only after you complete an approved motorcycle rider training course.","p":"Right. At 15 and a half, the rider course comes first."},"es":{"q":"En Missouri, usted quiere un permiso de instrucción para motocicleta a los 15 años y medio. ¿Qué debe terminar primero?","o":["Un registro de 40 horas de práctica en motocicleta","Un video de seguridad en la oficina de licencias","Un curso aprobado de entrenamiento para motociclistas","Un año manejando con permiso de auto"],"h1":"Es un curso que enseña a los motociclistas jóvenes.","h2":"En Missouri, el permiso de instrucción para motocicleta a los 15 años y medio solo se entrega después de completar un curso aprobado de entrenamiento para motociclistas.","p":"Correcto. A los 15 años y medio, primero va el curso."},"ref":{"doc":"MO","page":4}},{"id":"mo-053","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, a rider has a motorcycle instruction permit at 15 and a half. How far from home may the rider go?","o":["Within 50 miles","Within 10 miles","Within 25 miles","Within 100 miles"],"h1":"It is a round number between 25 and 100.","h2":"In Missouri, a motorcycle instruction permit issued at 15 and a half allows riding only within a 50-mile radius of home.","p":"Right. The limit is 50 miles from home."},"es":{"q":"En Missouri, un motociclista tiene un permiso de instrucción a los 15 años y medio. ¿Qué tan lejos de casa puede ir?","o":["Hasta 50 millas","Hasta 10 millas","Hasta 25 millas","Hasta 100 millas"],"h1":"Es un número redondo entre 25 y 100.","h2":"En Missouri, el permiso de instrucción para motocicleta de los 15 años y medio solo permite manejar dentro de un radio de 50 millas de casa.","p":"Correcto. El límite es 50 millas de casa."},"ref":{"doc":"MO","page":4}},{"id":"mo-054","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the largest motorcycle a rider may use with a motorcycle permit issued at 15 and a half?","o":["50 cc","250 cc","500 cc","750 cc"],"h1":"It is a small, light motorcycle, but bigger than a moped.","h2":"In Missouri, a rider with a motorcycle instruction permit issued at 15 and a half may ride a motorcycle no larger than 250 cc.","p":"Right. The limit is 250 cc."},"es":{"q":"En Missouri, ¿cuál es la motocicleta más grande que se puede usar con el permiso de motocicleta de los 15 años y medio?","o":["50 cc","250 cc","500 cc","750 cc"],"h1":"Es una moto pequeña y liviana, pero más grande que una motoneta.","h2":"En Missouri, quien tiene el permiso de instrucción para motocicleta de los 15 años y medio puede usar una moto de 250 cc o menos.","p":"Correcto. El límite es 250 cc."},"ref":{"doc":"MO","page":4}},{"id":"mo-055","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, a 15-and-a-half-year-old has a motorcycle instruction permit. Which rule applies?","o":["Riding allowed only on interstates","Daylight riding only, with no passengers","Night riding allowed with a helmet","One passenger allowed if under 19"],"h1":"Think of the safest, simplest conditions for a new young rider.","h2":"In Missouri, the motorcycle instruction permit issued at 15 and a half allows riding in daylight only and with no passengers.","p":"Right. Daylight only and no passengers."},"es":{"q":"En Missouri, un joven de 15 años y medio tiene permiso de instrucción para motocicleta. ¿Qué regla se aplica?","o":["Solo en autopistas interestatales","Solo de día y sin pasajeros","De noche si usa casco","Un pasajero menor de 19 años"],"h1":"Piense en las condiciones más seguras y simples para un motociclista nuevo.","h2":"En Missouri, el permiso de instrucción para motocicleta de los 15 años y medio permite manejar solo de día y sin pasajeros.","p":"Correcto. Solo de día y sin pasajeros."},"ref":{"doc":"MO","page":4}},{"id":"mo-056","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you are 17 and want a motorcycle instruction permit. Must you take the motorcycle rider training course first?","o":["Yes, every rider under 18 must take it","Yes, but only if you have no car license","No, but you must ride with a parent for 40 hours","No, it is required only at 15 and a half"],"h1":"The course rule depends on the age when you apply.","h2":"In Missouri, the rider training course is not required for a motorcycle instruction permit at 16 or older; it is required only for the permit at 15 and a half.","p":"Right. At 16 or older the course is not required for the permit."},"es":{"q":"En Missouri, usted tiene 17 años y quiere un permiso de instrucción para motocicleta. ¿Debe tomar primero el curso de entrenamiento?","o":["Sí, todo motociclista menor de 18 debe tomarlo","Sí, pero solo si no tiene licencia de auto","No, pero debe manejar 40 horas con un padre","No, solo se exige a los 15 años y medio"],"h1":"La regla del curso depende de la edad al solicitar.","h2":"En Missouri, el curso de entrenamiento no se exige para el permiso de instrucción para motocicleta a los 16 años o más; solo se exige para el permiso de los 15 años y medio.","p":"Correcto. A los 16 o más, el curso no se exige para el permiso."},"ref":{"doc":"MO","page":4}},{"id":"mo-057","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, at what age can a young driver get a full Class F driver license?","o":["16","17","18","21"],"h1":"It is the third and last step of the graduated license program.","h2":"In Missouri, the full Class F driver license is the third step of the graduated license program, and you can get it at 18.","p":"Right. The full license comes at 18."},"es":{"q":"En Missouri, ¿a qué edad puede un conductor joven obtener la licencia completa Clase F?","o":["16","17","18","21"],"h1":"Es el tercer y último paso del programa de licencia gradual.","h2":"En Missouri, la licencia completa Clase F es el tercer paso del programa de licencia gradual, y se puede obtener a los 18 años.","p":"Correcto. La licencia completa llega a los 18."},"ref":{"doc":"MO","page":4}},{"id":"mo-058","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you will be paid to drive a van with 14 or fewer passengers for a day care center. Which license do you need?","o":["A Class F license only","A Class M license","A nondriver ID with a passenger note","A Class E (for-hire) license"],"h1":"Being paid to drive people or goods calls for a special class.","h2":"In Missouri, a driver paid to carry 14 or fewer passengers, such as a day care driver, needs a Class E for-hire license.","p":"Right. Paid passenger driving needs Class E."},"es":{"q":"En Missouri, le pagarán por manejar una camioneta con 14 pasajeros o menos para una guardería. ¿Qué licencia necesita?","o":["Solo una licencia Clase F","Una licencia Clase M","Una identificación de no conductor con una nota","Una licencia Clase E (de alquiler)"],"h1":"Recibir pago por llevar personas o mercancía requiere una clase especial.","h2":"En Missouri, el conductor al que le pagan por llevar 14 pasajeros o menos, como en una guardería, necesita una licencia Clase E de alquiler.","p":"Correcto. Llevar pasajeros por pago requiere Clase E."},"ref":{"doc":"MO","page":4}},{"id":"mo-059","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, you deliver hot meals for a fast food restaurant in your own car. Do you need a Class E license?","o":["Yes, but only after 30 days of work","No, but you need a motorcycle endorsement","No, food delivery drivers are exempt","Yes, every paid delivery needs Class E"],"h1":"Missouri law lists food delivery as an exception.","h2":"In Missouri, people who deliver prepared food for a restaurant are not required to get a Class E for-hire license.","p":"Right. Prepared food delivery does not need Class E."},"es":{"q":"En Missouri, usted reparte comida caliente para un restaurante de comida rápida en su propio auto. ¿Necesita licencia Clase E?","o":["Sí, pero solo después de 30 días de trabajo","No, pero necesita un endoso de motocicleta","No, quienes reparten comida están exentos","Sí, toda entrega pagada necesita Clase E"],"h1":"La ley de Missouri pone la entrega de comida como excepción.","h2":"En Missouri, las personas que reparten comida preparada para un restaurante no tienen que sacar la licencia Clase E de alquiler.","p":"Correcto. Repartir comida preparada no requiere Clase E."},"ref":{"doc":"MO","page":5}},{"id":"mo-060","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how old must you be to get a commercial driver license with a school bus endorsement?","o":["18","19","21","25"],"h1":"A regular CDL starts younger than this endorsement.","h2":"In Missouri, you can apply for a CDL at 18, but you must be at least 21 to get one with a Hazardous Materials or School Bus endorsement.","p":"Right. The school bus endorsement on a CDL starts at 21."},"es":{"q":"En Missouri, ¿qué edad debe tener para obtener una licencia comercial con endoso de autobús escolar?","o":["18","19","21","25"],"h1":"Una licencia comercial normal empieza a una edad menor que este endoso.","h2":"En Missouri, puede solicitar una licencia comercial a los 18, pero debe tener al menos 21 para obtenerla con endoso de Materiales Peligrosos o de Autobús Escolar.","p":"Correcto. El endoso de autobús escolar empieza a los 21."},"ref":{"doc":"MO","page":5}},{"id":"mo-061","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what do you need to ride a motorized bicycle (moped) on public roads?","o":["Only a bicycle safety card","A valid driver license only","A motorcycle endorsement on your license","Nothing, because mopeds need no license"],"h1":"It is less than a motorcycle, but you still need some license.","h2":"In Missouri, a person riding a motorized bicycle must hold a valid driver license, but a motorcycle endorsement is not required.","p":"Right. A valid license is enough for a moped."},"es":{"q":"En Missouri, ¿qué necesita para manejar una bicicleta motorizada (motoneta) en vías públicas?","o":["Solo una tarjeta de seguridad en bicicleta","Solo una licencia de conducir válida","Un endoso de motocicleta en su licencia","Nada, porque las motonetas no necesitan licencia"],"h1":"Es menos que una motocicleta, pero igual necesita licencia.","h2":"En Missouri, quien maneja una bicicleta motorizada debe tener una licencia de conducir válida, pero no necesita endoso de motocicleta.","p":"Correcto. Para la motoneta basta una licencia válida."},"ref":{"doc":"MO","page":5}},{"id":"mo-062","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, a person aged 72 applies for a nondriver ID card that is not REAL ID-compliant. How long is it valid?","o":["It does not expire","2 years from issue","3 years from issue","6 years from issue"],"h1":"Missouri makes this easier for people 70 and older.","h2":"In Missouri, a non-REAL ID nondriver ID issued to a person age 70 or older does not expire; a REAL ID-compliant one may be issued for six years.","p":"Right. At 70 or older, the nondriver ID does not expire."},"es":{"q":"En Missouri, una persona de 72 años solicita una identificación de no conductor que no es compatible con REAL ID. ¿Por cuánto tiempo es válida?","o":["No vence","2 años desde que se emite","3 años desde que se emite","6 años desde que se emite"],"h1":"Missouri lo hace más fácil para personas de 70 años o más.","h2":"En Missouri, la identificación de no conductor sin REAL ID que se entrega a una persona de 70 años o más no vence; una compatible con REAL ID puede emitirse por seis años.","p":"Correcto. A los 70 o más, la identificación no vence."},"ref":{"doc":"MO","page":5}},{"id":"mo-063","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you just moved from another state and your license there is still valid. Which tests must you take to get the same kind of Missouri license?","o":["The written and driving tests","All four parts of the exam","No tests at all","The vision and road sign tests"],"h1":"Your old license already shows you can drive.","h2":"In Missouri, a new resident with a valid out-of-state license (or one expired less than 184 days) takes only the vision and road sign tests for the same type of license.","p":"Right. Only vision and road signs."},"es":{"q":"En Missouri, usted acaba de mudarse de otro estado y su licencia de allá sigue vigente. ¿Qué exámenes debe tomar para obtener el mismo tipo de licencia de Missouri?","o":["Los exámenes escrito y de manejo","Las cuatro partes del examen","Ningún examen","Los exámenes de visión y de señales"],"h1":"Su licencia anterior ya muestra que sabe manejar.","h2":"En Missouri, un nuevo residente con licencia de otro estado vigente (o vencida hace menos de 184 días) solo toma los exámenes de visión y de señales para el mismo tipo de licencia.","p":"Correcto. Solo visión y señales."},"ref":{"doc":"MO","page":18}},{"id":"mo-064","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a new resident's out-of-state license expired 200 days ago. What must the person do to get a Missouri license?","o":["Pay a late fee and transfer it","Wait one year and then transfer it","Take the full four-part driver exam","Take only the vision test"],"h1":"The limit for an expired out-of-state license is 184 days.","h2":"In Missouri, if your out-of-state license has been expired for more than 184 days, you must take the full four-part exam: written, vision, road sign and driving tests.","p":"Right. Over 184 days means the full exam."},"es":{"q":"En Missouri, la licencia de otro estado de un nuevo residente venció hace 200 días. ¿Qué debe hacer para obtener la licencia de Missouri?","o":["Pagar un recargo y transferirla","Esperar un año y luego transferirla","Tomar el examen completo de cuatro partes","Tomar solo el examen de visión"],"h1":"El límite para una licencia de otro estado vencida es de 184 días.","h2":"En Missouri, si su licencia de otro estado lleva vencida más de 184 días, debe tomar el examen completo de cuatro partes: escrito, visión, señales y manejo.","p":"Correcto. Más de 184 días significa el examen completo."},"ref":{"doc":"MO","page":6}},{"id":"mo-065","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, how many proofs of residency must you show to get a REAL ID-compliant license?","o":["Two documents","One document","Three documents","None if you show a passport"],"h1":"A non-REAL ID card needs fewer.","h2":"In Missouri, a REAL ID-compliant card needs two documents that prove your Missouri address, while a non-REAL ID card needs one.","p":"Right. REAL ID needs two proofs of residency."},"es":{"q":"En Missouri, ¿cuántas pruebas de residencia debe mostrar para obtener una licencia compatible con REAL ID?","o":["Dos documentos","Un documento","Tres documentos","Ninguno si muestra un pasaporte"],"h1":"Una tarjeta que no es REAL ID necesita menos.","h2":"En Missouri, una tarjeta compatible con REAL ID requiere dos documentos que prueben su domicilio en Missouri; una tarjeta sin REAL ID requiere uno.","p":"Correcto. REAL ID requiere dos pruebas de residencia."},"ref":{"doc":"MO","page":7}},{"id":"mo-066","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, can you use a Post Office box as your home address on your license application?","o":["Yes, but only if you are under 21","No, give the address where you live","Yes, if you have had it for a year","Yes, for any non-REAL ID card"],"h1":"Your residential address is where you physically live.","h2":"In Missouri, a Post Office box is not accepted as a residential address; you must show where you actually live, and you may add a separate mailing address.","p":"Right. A P.O. box is not a home address."},"es":{"q":"En Missouri, ¿puede usar un apartado postal como domicilio en su solicitud de licencia?","o":["Sí, pero solo si es menor de 21 años","No, dé la dirección donde vive","Sí, si lo tiene hace un año","Sí, para cualquier tarjeta sin REAL ID"],"h1":"Su domicilio es el lugar donde vive físicamente.","h2":"En Missouri, un apartado postal no se acepta como domicilio; debe mostrar dónde vive realmente, y puede agregar una dirección postal aparte.","p":"Correcto. Un apartado postal no es un domicilio."},"ref":{"doc":"MO","page":7}},{"id":"mo-067","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you are 17 and have no bill or letter in your own name to prove your address. What can you do?","o":["You must wait until you turn 21 to apply","Your school ID card proves your address","A friend can sign a note saying where you live","A parent or guardian can give one for you"],"h1":"Someone responsible for you can help.","h2":"In Missouri, if you are under 21 and cannot provide an accepted residency document, a parent or legal guardian may provide one on your behalf.","p":"Right. A parent or guardian can provide the document."},"es":{"q":"En Missouri, usted tiene 17 años y no tiene facturas ni cartas a su nombre para probar su domicilio. ¿Qué puede hacer?","o":["Debe esperar a cumplir 21 para solicitar","Su credencial escolar prueba su domicilio","Un amigo puede firmar una nota con su domicilio","Su padre o tutor puede darlo por usted"],"h1":"Alguien responsable de usted puede ayudar.","h2":"En Missouri, si usted es menor de 21 años y no puede presentar un documento de residencia aceptado, su padre, madre o tutor legal puede presentarlo por usted.","p":"Correcto. Un padre o tutor puede dar el documento."},"ref":{"doc":"MO","page":7}},{"id":"mo-068","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, you bring your Social Security card to prove your number. Which card will be accepted?","o":["The original signed card, not laminated","A laminated copy of the original card","A photo of the card on your phone","A new card, even if it is unsigned"],"h1":"Officials must be able to check the card itself.","h2":"In Missouri, a Social Security card used as proof must be the original, signed and not laminated.","p":"Right. Original, signed and not laminated."},"es":{"q":"En Missouri, lleva su tarjeta del Seguro Social para probar su número. ¿Qué tarjeta se acepta?","o":["Una tarjeta original, firmada y sin plastificar","Una copia plastificada de la tarjeta original","Una foto de la tarjeta en su teléfono","Una tarjeta nueva, aunque no esté firmada"],"h1":"Los funcionarios deben poder revisar la tarjeta misma.","h2":"En Missouri, la tarjeta del Seguro Social que se usa como prueba debe ser la original, firmada y sin plastificar.","p":"Correcto. Original, firmada y sin plastificar."},"ref":{"doc":"MO","page":7}},{"id":"mo-069","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, your first name is different on your documents. What proof of the change must you show?","o":["A letter from your employer","A signed statement from a parent","A certified court order","A marriage license"],"h1":"Last names can change through marriage, but first names change another way.","h2":"In Missouri, a first or middle name change is proven with a certified court order.","p":"Right. A first name change needs a certified court order."},"es":{"q":"En Missouri, su primer nombre es distinto en sus documentos. ¿Qué prueba del cambio debe mostrar?","o":["Una carta de su empleador","Una declaración firmada por un padre","Una orden judicial certificada","Una licencia de matrimonio"],"h1":"El apellido puede cambiar por matrimonio, pero el nombre cambia de otra forma.","h2":"En Missouri, el cambio de primer nombre o segundo nombre se prueba con una orden judicial certificada.","p":"Correcto. El cambio de nombre requiere una orden judicial certificada."},"ref":{"doc":"MO","page":8}},{"id":"mo-070","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the fee for an instruction permit?","o":["$1.00","$10.00","$14.00","$24.00"],"h1":"It costs less than the intermediate license.","h2":"In Missouri, an instruction permit costs $10.00.","p":"Right. The instruction permit is $10."},"es":{"q":"En Missouri, ¿cuánto cuesta el permiso de instrucción?","o":["$1.00","$10.00","$14.00","$24.00"],"h1":"Cuesta menos que la licencia intermedia.","h2":"En Missouri, el permiso de instrucción cuesta $10.00.","p":"Correcto. El permiso de instrucción cuesta $10."},"ref":{"doc":"MO","page":8}},{"id":"mo-071","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how long can a motorcycle instruction permit be valid?","o":["Up to 6 years","Up to 6 months","Up to 30 days","Up to 2 years"],"h1":"It is shorter than a car instruction permit, which lasts up to a year.","h2":"In Missouri, a motorcycle instruction permit is valid for up to six months, or 182 days.","p":"Right. Up to six months."},"es":{"q":"En Missouri, ¿por cuánto tiempo puede ser válido el permiso de instrucción para motocicleta?","o":["Hasta 6 años","Hasta 6 meses","Hasta 30 días","Hasta 2 años"],"h1":"Es más corto que el permiso de auto, que dura hasta un año.","h2":"En Missouri, el permiso de instrucción para motocicleta es válido por hasta seis meses, o 182 días.","p":"Correcto. Hasta seis meses."},"ref":{"doc":"MO","page":8}},{"id":"mo-072","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, for how long can an intermediate license be issued?","o":["Up to 6 months","Up to 3 years","Up to 6 years","Up to 2 years"],"h1":"It is the stage between 16 and 18.","h2":"In Missouri, an intermediate license is valid for up to two years, the time between age 16 and the full license at 18.","p":"Right. Up to two years."},"es":{"q":"En Missouri, ¿por cuánto tiempo se puede emitir una licencia intermedia?","o":["Hasta 6 meses","Hasta 3 años","Hasta 6 años","Hasta 2 años"],"h1":"Es la etapa entre los 16 y los 18 años.","h2":"En Missouri, la licencia intermedia es válida por hasta dos años, el tiempo entre los 16 años y la licencia completa a los 18.","p":"Correcto. Hasta dos años."},"ref":{"doc":"MO","page":8}},{"id":"mo-073","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, what does restriction code A on a driver license mean?","o":["You must wear corrective lenses","Daylight driving only","Automatic transmission only","25-mile radius only"],"h1":"It is the most common restriction, about your eyes.","h2":"In Missouri, restriction code A means you must wear corrective lenses, such as glasses or contacts, when you drive.","p":"Right. Code A means corrective lenses."},"es":{"q":"En Missouri, ¿qué significa la restricción con el código A en la licencia?","o":["Debe usar lentes correctivos","Solo manejar de día","Solo transmisión automática","Solo dentro de 25 millas"],"h1":"Es la restricción más común y tiene que ver con los ojos.","h2":"En Missouri, el código de restricción A significa que debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar.","p":"Correcto. El código A significa lentes correctivos."},"ref":{"doc":"MO","page":9}},{"id":"mo-074","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, your license shows restriction code C. What does it mean?","o":["You may drive only up to 45 mph","You need special hand controls","You may drive in daylight only","You must use an outside mirror"],"h1":"It is about the time of day you may drive.","h2":"In Missouri, restriction code C means daylight driving only.","p":"Right. Code C means daylight driving only."},"es":{"q":"En Missouri, su licencia tiene la restricción con código C. ¿Qué significa?","o":["Solo puede manejar hasta 45 mph","Necesita controles manuales especiales","Solo puede manejar de día","Debe usar un espejo exterior"],"h1":"Tiene que ver con la hora del día en que puede manejar.","h2":"En Missouri, el código de restricción C significa que solo puede manejar de día.","p":"Correcto. El código C significa solo de día."},"ref":{"doc":"MO","page":9}},{"id":"mo-075","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what can happen if you drive in a way your license restriction does not allow?","o":["Your car registration is cancelled","It counts as driving without a license","Nothing, restrictions are only advice","You only get a written warning"],"h1":"A restricted license is valid only under its conditions.","h2":"In Missouri, disobeying a license restriction can lead to a charge of driving without a license, and points if you are convicted.","p":"Right. It counts as driving without a license."},"es":{"q":"En Missouri, ¿qué puede pasar si maneja de una forma que la restricción de su licencia no permite?","o":["Le cancelan el registro del auto","Cuenta como manejar sin licencia","Nada, las restricciones son solo consejos","Solo recibe una advertencia escrita"],"h1":"Una licencia restringida solo es válida bajo sus condiciones.","h2":"En Missouri, desobedecer una restricción de la licencia puede llevar a un cargo de manejar sin licencia, y a puntos si lo declaran culpable.","p":"Correcto. Cuenta como manejar sin licencia."},"ref":{"doc":"MO","page":9}},{"id":"mo-076","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, you had a seizure four months ago and now apply for a license. What may you have to give the Department of Revenue?","o":["A statement from your doctor","A new birth certificate","A letter from your employer","Proof of a driving course"],"h1":"A medical professional must speak about your condition.","h2":"In Missouri, if you had seizures, convulsions or blackouts in the six months before applying, you may need to submit a physician's statement.","p":"Right. A doctor's statement is needed."},"es":{"q":"En Missouri, usted tuvo una convulsión hace cuatro meses y ahora solicita una licencia. ¿Qué puede tener que entregar al Departamento de Ingresos?","o":["Una declaración de su médico","Un acta de nacimiento nueva","Una carta de su empleador","Prueba de un curso de manejo"],"h1":"Un profesional médico debe hablar de su condición.","h2":"En Missouri, si tuvo convulsiones, ataques o desmayos en los seis meses antes de solicitar, puede tener que entregar una declaración de un médico.","p":"Correcto. Se necesita una declaración médica."},"ref":{"doc":"MO","page":9}},{"id":"mo-077","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, when is a school bus endorsement required?","o":["Driving any child to school in your own car","Driving a yellow bus only on interstates","Carrying more than 3 passengers under 19","Carrying students in a vehicle for over 10 people"],"h1":"It depends on who you carry and the size of the vehicle.","h2":"In Missouri, a school bus endorsement is required to carry students to and from school or school events in a vehicle designed for more than ten passengers.","p":"Right. Students plus a vehicle for more than ten passengers."},"es":{"q":"En Missouri, ¿cuándo se exige el endoso de autobús escolar?","o":["Al llevar a cualquier niño a la escuela en su auto","Solo al manejar un autobús amarillo en interestatales","Al llevar a más de 3 pasajeros menores de 19","Al llevar estudiantes en un vehículo para más de 10 personas"],"h1":"Depende de a quién lleva y del tamaño del vehículo.","h2":"En Missouri, el endoso de autobús escolar se exige para llevar estudiantes a la escuela, desde ella o a eventos escolares en un vehículo diseñado para más de diez pasajeros.","p":"Correcto. Estudiantes y un vehículo para más de diez pasajeros."},"ref":{"doc":"MO","page":10}},{"id":"mo-078","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, a school bus driver is 76 years old. What must the driver do to keep the school bus endorsement?","o":["Nothing more than any other bus driver","Pass a bus skills test every two years","Retake the written test every single month","Give up the endorsement on turning 75"],"h1":"Older school bus drivers are checked more often.","h2":"In Missouri, drivers aged 75 or older with a school bus endorsement must pass a school bus skills test every two years to keep it.","p":"Right. A skills test every two years."},"es":{"q":"En Missouri, un chofer de autobús escolar tiene 76 años. ¿Qué debe hacer para conservar el endoso de autobús escolar?","o":["Nada más que cualquier otro chofer","Aprobar un examen práctico cada dos años","Repetir el examen escrito todos los meses","Dejar el endoso al cumplir 75 años"],"h1":"A los choferes mayores se les revisa con más frecuencia.","h2":"En Missouri, los conductores de 75 años o más con endoso de autobús escolar deben aprobar un examen de habilidades cada dos años para conservarlo.","p":"Correcto. Un examen de habilidades cada dos años."},"ref":{"doc":"MO","page":10}},{"id":"mo-079","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how early can you renew your driver license before it expires?","o":["Up to 1 year before","Only on your birthday","Up to 6 months before","Up to 30 days before"],"h1":"It is the same span of time as the grace period after it expires.","h2":"In Missouri, you may renew your driver license up to six months before it expires.","p":"Right. Up to six months early."},"es":{"q":"En Missouri, ¿con cuánta anticipación puede renovar su licencia antes de que venza?","o":["Hasta 1 año antes","Solo el día de su cumpleaños","Hasta 6 meses antes","Hasta 30 días antes"],"h1":"Es el mismo tiempo que el plazo después del vencimiento.","h2":"En Missouri, puede renovar su licencia de conducir hasta seis meses antes de que venza.","p":"Correcto. Hasta seis meses antes."},"ref":{"doc":"MO","page":10}},{"id":"mo-080","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, which tests must you take each time you renew your driver license?","o":["The written and driving tests","Only the driving test","No tests","The vision and road sign tests"],"h1":"These tests check that you can still see and read the road.","h2":"In Missouri, every time you renew your license you take the vision and road sign tests.","p":"Right. Vision and road signs at each renewal."},"es":{"q":"En Missouri, ¿qué exámenes debe tomar cada vez que renueva su licencia?","o":["Los exámenes escrito y de manejo","Solo el examen de manejo","Ningún examen","Los exámenes de visión y de señales"],"h1":"Estos exámenes revisan que todavía puede ver y leer el camino.","h2":"En Missouri, cada vez que renueva su licencia toma los exámenes de visión y de señales de tránsito.","p":"Correcto. Visión y señales en cada renovación."},"ref":{"doc":"MO","page":10}},{"id":"mo-081","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, will the Department of Revenue mail you a renewal reminder for a temporary instruction permit?","o":["Yes, but only by e-mail","Only if you are under 16","No, not for a temporary permit","Yes, 90 days before it expires"],"h1":"Reminders go out for licenses, with a few exceptions.","h2":"In Missouri, a renewal reminder is not mailed for a temporary instruction permit, so you must keep track of the date yourself.","p":"Right. No reminder for a temporary instruction permit."},"es":{"q":"En Missouri, ¿el Departamento de Ingresos le enviará un recordatorio de renovación para un permiso de instrucción temporal?","o":["Sí, pero solo por correo electrónico","Solo si es menor de 16 años","No, no para un permiso temporal","Sí, 90 días antes de que venza"],"h1":"Los recordatorios se envían para las licencias, con algunas excepciones.","h2":"En Missouri, no se envía recordatorio de renovación para un permiso de instrucción temporal, así que usted debe recordar la fecha.","p":"Correcto. No hay recordatorio para el permiso temporal."},"ref":{"doc":"MO","page":10}},{"id":"mo-082","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you lose your license, and it expires in four months. What may you do instead of buying a duplicate?","o":["Nothing; you must buy a duplicate","Renew your license early","Drive with a copy until it expires","Ask the police for a temporary card"],"h1":"A license that expires soon can be handled in one step.","h2":"In Missouri, if your lost, stolen or destroyed license expires within six months, you may renew it early instead of getting a duplicate.","p":"Right. Renew early and save a trip."},"es":{"q":"En Missouri, usted pierde su licencia y vence en cuatro meses. ¿Qué puede hacer en vez de sacar un duplicado?","o":["Nada; debe sacar un duplicado","Renovar su licencia antes de tiempo","Manejar con una copia hasta que venza","Pedir una tarjeta temporal a la policía"],"h1":"Una licencia que vence pronto se resuelve en un solo paso.","h2":"En Missouri, si su licencia perdida, robada o destruida vence dentro de seis meses, puede renovarla antes de tiempo en lugar de sacar un duplicado.","p":"Correcto. Renovar antes y ahorrarse un viaje."},"ref":{"doc":"MO","page":11}},{"id":"mo-083","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, your driving privilege is revoked. When may you still renew your license during the revocation?","o":["Only if it was for refusing a chemical test","Only if you pay a double renewal fee","Only if you have no other points","Never, until the revocation ends"],"h1":"There is one exception, related to alcohol testing.","h2":"In Missouri, you may renew your license while revoked only if the revocation resulted from refusing a chemical test; you still cannot drive until reinstated.","p":"Right. Only for a chemical test refusal revocation."},"es":{"q":"En Missouri, su privilegio de manejar está revocado. ¿Cuándo puede renovar su licencia durante la revocación?","o":["Solo si fue por negarse a una prueba química","Solo si paga el doble por la renovación","Solo si no tiene otros puntos","Nunca, hasta que termine la revocación"],"h1":"Hay una excepción, relacionada con las pruebas de alcohol.","h2":"En Missouri, puede renovar su licencia durante una revocación solo si esta fue por negarse a una prueba química; igual no puede manejar hasta que lo restablezcan.","p":"Correcto. Solo si la revocación fue por negarse a la prueba química."},"ref":{"doc":"MO","page":11}},{"id":"mo-084","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, what symbol on your license shows you joined the organ donor registry?","o":["A red heart with a green banner","A blue star inside a circle","A green cross on a white box","A gold seal with the state map"],"h1":"It is a heart.","h2":"In Missouri, the optional organ donor symbol is a red heart with a green banner, and there is no fee to add it.","p":"Right. A red heart with a green banner."},"es":{"q":"En Missouri, ¿qué símbolo en su licencia muestra que se inscribió como donante de órganos?","o":["Un corazón rojo con una cinta verde","Una estrella azul dentro de un círculo","Una cruz verde en un cuadro blanco","Un sello dorado con el mapa del estado"],"h1":"Es un corazón.","h2":"En Missouri, el símbolo opcional de donante de órganos es un corazón rojo con una cinta verde, y agregarlo no cuesta nada.","p":"Correcto. Un corazón rojo con una cinta verde."},"ref":{"doc":"MO","page":12}},{"id":"mo-085","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, a deaf driver wants police and emergency workers to know this quickly. What can be added to the license?","o":["A Veteran designation","A \"DHH\" notation","A blue restriction code","A medical sticker on the windshield"],"h1":"The letters stand for Deaf or Hard of Hearing.","h2":"In Missouri, a driver can ask for a \"DHH\" notation on the license to show they are deaf or hard of hearing.","p":"Right. The DHH notation."},"es":{"q":"En Missouri, un conductor sordo quiere que la policía y el personal de emergencias lo sepan rápido. ¿Qué se puede agregar a la licencia?","o":["La designación de Veterano","Una anotación \"DHH\"","Un código de restricción azul","Una calcomanía médica en el parabrisas"],"h1":"Las letras significan sordo o con dificultad auditiva, en inglés.","h2":"En Missouri, un conductor puede pedir la anotación \"DHH\" en su licencia para mostrar que es sordo o tiene dificultad para oír.","p":"Correcto. La anotación DHH."},"ref":{"doc":"MO","page":12}},{"id":"mo-086","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you have a Boating Safety Education Card. What can you add to your driver license instead of carrying that card?","o":["A boat license plate number","A Class B endorsement","Nothing; you must carry both","A boater safety indicator, for a $1 fee"],"h1":"The Highway Patrol accepts a mark on your license.","h2":"In Missouri, you can add a boater safety indicator to your license for $1, and the Highway Patrol accepts it instead of the separate boating card.","p":"Right. The boater safety indicator."},"es":{"q":"En Missouri, usted tiene una tarjeta de educación en seguridad náutica. ¿Qué puede agregar a su licencia en lugar de llevar esa tarjeta?","o":["El número de placa de su bote","Un endoso Clase B","Nada; debe llevar las dos","Un indicador de seguridad náutica, por $1"],"h1":"La Patrulla de Carreteras acepta una marca en su licencia.","h2":"En Missouri, puede agregar a su licencia un indicador de seguridad náutica por $1, y la Patrulla lo acepta en lugar de la tarjeta náutica aparte.","p":"Correcto. El indicador de seguridad náutica."},"ref":{"doc":"MO","page":13}},{"id":"mo-087","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a parent of a 16-year-old asks the Director of Revenue to deny the teen a license. When does that denial end?","o":["When the teen passes the driving test again","Never; it is permanent","At 18, or when the parent clears it","After 90 days, on its own"],"h1":"The parent's power over this lasts only while the teen is a minor.","h2":"In Missouri, a parent or guardian of a driver under 18 can request a license denial, and it ends when the teen turns 18 or the parent asks to clear it.","p":"Right. It lasts until 18 unless the parent clears it."},"es":{"q":"En Missouri, el padre de un joven de 16 años pide al Director de Ingresos que le niegue la licencia. ¿Cuándo termina esa negación?","o":["Cuando el joven aprueba otra vez el examen de manejo","Nunca; es permanente","A los 18, o cuando el padre la quite","Después de 90 días, sola"],"h1":"El poder del padre sobre esto dura solo mientras el joven es menor.","h2":"En Missouri, el padre o tutor de un conductor menor de 18 puede pedir que se le niegue la licencia, y la negación termina cuando cumple 18 o cuando el padre pide quitarla.","p":"Correcto. Dura hasta los 18, salvo que el padre la quite."},"ref":{"doc":"MO","page":14}},{"id":"mo-088","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, which of these can cause you to lose your driver license?","o":["Stealing fuel from a gas station","Getting a parking ticket and paying it","Changing your address online","Selling your car"],"h1":"One of these is a crime connected to driving.","h2":"In Missouri, stealing fuel from a gas station is one of the listed reasons your license can be suspended or revoked.","p":"Right. Fuel theft can cost you your license."},"es":{"q":"En Missouri, ¿cuál de estas acciones puede hacerle perder la licencia de conducir?","o":["Robar combustible en una gasolinera","Recibir una multa de estacionamiento y pagarla","Cambiar su domicilio por internet","Vender su auto"],"h1":"Una de estas es un delito relacionado con manejar.","h2":"En Missouri, robar combustible en una gasolinera es una de las razones por las que le pueden suspender o revocar la licencia.","p":"Correcto. Robar combustible puede costarle la licencia."},"ref":{"doc":"MO","page":15}},{"id":"mo-089","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a permit holder is 15. A family friend wants to supervise the practice driving. What must the friend have?","o":["Be at least 21, licensed, and the owner of the car","Have held a driver license for at least 1 full year","Be 25+, licensed 3 years, with a parent's written permission","Be at least 18 and hold any valid driver license"],"h1":"The friend needs age, experience and a parent's written okay.","h2":"In Missouri, a permit holder under 16 may drive with a person at least 25 years old, licensed for at least three years, who has written permission from the parent or guardian.","p":"Right. Age 25, three years licensed, written permission."},"es":{"q":"En Missouri, un joven con permiso tiene 15 años. Un amigo de la familia quiere supervisar su práctica. ¿Qué debe cumplir el amigo?","o":["Tener al menos 21 años, licencia y ser el dueño del auto","Tener licencia de conducir desde hace al menos 1 año completo","Tener al menos 25 años, 3 años con licencia y permiso escrito de un padre","Tener al menos 18 años y cualquier licencia de conducir válida"],"h1":"El amigo necesita edad, experiencia y el permiso escrito de un padre.","h2":"En Missouri, un joven con permiso menor de 16 puede manejar con una persona de al menos 25 años, con licencia por al menos tres años y con permiso escrito del padre o tutor.","p":"Correcto. 25 años, tres años con licencia y permiso escrito."},"ref":{"doc":"MO","page":15}},{"id":"mo-090","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, a permit holder's parent is physically disabled. How many people may the parent name to ride along and teach?","o":["Only one person","Up to four people","Anyone with a license","Up to two people"],"h1":"It is a small number, more than one.","h2":"In Missouri, a physically disabled parent, stepparent, grandparent or guardian may designate up to two people to supervise the permit holder.","p":"Right. Up to two people."},"es":{"q":"En Missouri, el padre de un joven con permiso tiene una discapacidad física. ¿A cuántas personas puede nombrar para acompañar y enseñar?","o":["Solo una persona","Hasta cuatro personas","Cualquiera con licencia","Hasta dos personas"],"h1":"Es un número pequeño, más de uno.","h2":"En Missouri, un padre, padrastro, abuelo o tutor con discapacidad física puede nombrar hasta dos personas para supervisar al joven con permiso.","p":"Correcto. Hasta dos personas."},"ref":{"doc":"MO","page":15}},{"id":"mo-091","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you are 16 and have an instruction permit. Who may sit in the front seat and supervise you?","o":["Only a certified driving instructor","Any licensed driver age 21 or older","Any licensed driver age 18 or older","Only a parent or legal guardian"],"h1":"After 16 the list gets wider, but there is still an age limit.","h2":"In Missouri, once you are 16, you may drive on a permit with any licensed driver at least 21 years old in the front seat.","p":"Right. A licensed driver 21 or older."},"es":{"q":"En Missouri, usted tiene 16 años y un permiso de instrucción. ¿Quién puede ir en el asiento delantero y supervisarlo?","o":["Solo un instructor de manejo certificado","Cualquier conductor con licencia de 21 años o más","Cualquier conductor con licencia de 18 años o más","Solo un padre, madre o tutor legal"],"h1":"Después de los 16 la lista se amplía, pero hay un límite de edad.","h2":"En Missouri, a partir de los 16 años puede manejar con permiso si en el asiento delantero va cualquier conductor con licencia de al menos 21 años.","p":"Correcto. Un conductor con licencia de 21 años o más."},"ref":{"doc":"MO","page":15}},{"id":"mo-092","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, your instruction permit is about to expire. Must you pass the written test again to renew it?","o":["Yes, every time you renew it","Yes, after the first renewal","No, but you must take a driving test","No, you may renew it without a new written test"],"h1":"Missouri makes permit renewal simple.","h2":"In Missouri, you may renew your instruction permit as many times as needed without taking more written tests.","p":"Right. No new written test is needed."},"es":{"q":"En Missouri, su permiso de instrucción está por vencer. ¿Debe aprobar otra vez el examen escrito para renovarlo?","o":["Sí, cada vez que lo renueve","Sí, después de la primera renovación","No, pero debe tomar un examen de manejo","No, puede renovarlo sin otro examen escrito"],"h1":"Missouri hace fácil renovar el permiso.","h2":"En Missouri, puede renovar su permiso de instrucción las veces que necesite sin tomar más exámenes escritos.","p":"Correcto. No necesita otro examen escrito."},"ref":{"doc":"MO","page":15}},{"id":"mo-093","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, where can you get a free \"PERMIT DRIVER\" sign for your car window?","o":["At any license office","At the Highway Patrol test site only","At a car dealer","Only online for a fee"],"h1":"It is the same place where you get your permit.","h2":"In Missouri, free \"PERMIT DRIVER\" window signs are available at all license offices.","p":"Right. License offices have them for free."},"es":{"q":"En Missouri, ¿dónde puede conseguir gratis un letrero \"PERMIT DRIVER\" para la ventana del auto?","o":["En cualquier oficina de licencias","Solo en el sitio de exámenes de la Patrulla","En un concesionario de autos","Solo por internet y pagando"],"h1":"Es el mismo lugar donde saca su permiso.","h2":"En Missouri, los letreros gratuitos \"PERMIT DRIVER\" para la ventana están disponibles en todas las oficinas de licencias.","p":"Correcto. Las oficinas de licencias los dan gratis."},"ref":{"doc":"MO","page":16}},{"id":"mo-094","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, to move from an instruction permit to an intermediate license, you may have no traffic convictions within what period?","o":["The last 2 years","The last 5 years","The last 6 months","The last 30 days"],"h1":"It matches the minimum time you must hold the permit.","h2":"In Missouri, to get an intermediate license you must have no traffic convictions in the last six months and no alcohol-related convictions in the last 12 months.","p":"Right. No traffic convictions in the last six months."},"es":{"q":"En Missouri, para pasar del permiso de instrucción a la licencia intermedia, ¿en qué periodo no puede tener condenas de tránsito?","o":["Los últimos 2 años","Los últimos 5 años","Los últimos 6 meses","Los últimos 30 días"],"h1":"Coincide con el tiempo mínimo que debe tener el permiso.","h2":"En Missouri, para obtener la licencia intermedia no puede tener condenas de tránsito en los últimos seis meses ni condenas relacionadas con alcohol en los últimos 12 meses.","p":"Correcto. Ninguna condena de tránsito en los últimos seis meses."},"ref":{"doc":"MO","page":16}},{"id":"mo-095","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how are your 40 practice hours verified when you apply for an intermediate license?","o":["Your school sends a letter to the license office","A parent, guardian or trainer confirms them in person","You mail a written log of your hours to the state","The examiner asks you how many hours you drove"],"h1":"Someone who supervised you must appear in person.","h2":"In Missouri, a parent, grandparent, stepparent, legal guardian or certified trainer must go with you to the license office to verify your 40 hours of driving instruction.","p":"Right. An adult comes with you to verify the hours."},"es":{"q":"En Missouri, ¿cómo se verifican sus 40 horas de práctica al solicitar la licencia intermedia?","o":["Su escuela envía una carta a la oficina de licencias","Un padre, tutor o entrenador las confirma en persona","Usted envía por correo un registro de sus horas al estado","El examinador le pregunta cuántas horas manejó"],"h1":"Alguien que lo supervisó debe presentarse en persona.","h2":"En Missouri, un padre, abuelo, padrastro, tutor legal o entrenador certificado debe acompañarlo a la oficina de licencias para verificar sus 40 horas de instrucción.","p":"Correcto. Un adulto lo acompaña a verificar las horas."},"ref":{"doc":"MO","page":16}},{"id":"mo-096","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a 16-year-old with an intermediate license drives alone at 2 a.m. Which trip is allowed?","o":["Driving to get a snack","Driving around to practice","Driving home from a job","Driving to a friend's party"],"h1":"The exceptions are school activities, work and emergencies.","h2":"In Missouri, an intermediate license holder may drive alone between 1 a.m. and 5 a.m. only to or from a school activity, a job or an emergency.","p":"Right. Work trips are an exception."},"es":{"q":"En Missouri, un joven de 16 años con licencia intermedia maneja solo a las 2 a.m. ¿Qué viaje está permitido?","o":["Ir a comprar algo de comer","Dar vueltas para practicar","Volver a casa desde el trabajo","Ir a una fiesta de un amigo"],"h1":"Las excepciones son actividades escolares, trabajo y emergencias.","h2":"En Missouri, quien tiene licencia intermedia puede manejar solo entre la 1 a.m. y las 5 a.m. únicamente para ir o volver de una actividad escolar, un trabajo o una emergencia.","p":"Correcto. El trabajo es una excepción."},"ref":{"doc":"MO","page":16}},{"id":"mo-097","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, the intermediate license passenger limit does not count immediate family. Which of these passengers is immediate family?","o":["A cousin who lives in the house next door","A best friend who often stays over","A neighbor's child who rides every day","A stepbrother who lives in the driver's household"],"h1":"Family members who live in the same home count.","h2":"In Missouri, immediate family for the passenger limit includes parents, grandparents, brothers, sisters, stepbrothers, stepsisters, and adopted or foster children living in the driver's household.","p":"Right. A stepbrother in the household counts as family."},"es":{"q":"En Missouri, el límite de pasajeros de la licencia intermedia no cuenta a la familia inmediata. ¿Cuál de estos pasajeros es familia inmediata?","o":["Un primo que vive en la casa de al lado","El mejor amigo que a menudo se queda a dormir","El hijo de un vecino que viaja todos los días","Un hermanastro que vive en el hogar del conductor"],"h1":"Cuentan los familiares que viven en la misma casa.","h2":"En Missouri, la familia inmediata para el límite de pasajeros incluye padres, abuelos, hermanos, hermanas, hermanastros, hermanastras e hijos adoptivos o de crianza que viven en el hogar del conductor.","p":"Correcto. Un hermanastro que vive en la casa cuenta como familia."},"ref":{"doc":"MO","page":16}},{"id":"mo-098","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, the intermediate license passenger limits may not apply in one situation. Which one?","o":["When driving under 25 mph","When the driver is doing farm work","When the passengers are teammates","On weekends and school holidays"],"h1":"Think of work on a farm.","h2":"In Missouri, the intermediate license passenger restrictions may not apply to a driver doing agricultural work-related activities.","p":"Right. Farm work can be an exception."},"es":{"q":"En Missouri, los límites de pasajeros de la licencia intermedia pueden no aplicarse en una situación. ¿Cuál?","o":["Al manejar a menos de 25 mph","Cuando el conductor hace trabajo agrícola","Cuando los pasajeros son compañeros de equipo","Los fines de semana y feriados escolares"],"h1":"Piense en el trabajo en una granja.","h2":"En Missouri, las restricciones de pasajeros de la licencia intermedia pueden no aplicarse a un conductor que hace actividades de trabajo agrícola.","p":"Correcto. El trabajo agrícola puede ser una excepción."},"ref":{"doc":"MO","page":16}},{"id":"mo-099","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, to get a full under-21 license at 18, you may have no alcohol offenses or traffic convictions within what period?","o":["The last 12 months","The last 3 months","The last 6 months","The last 3 years"],"h1":"It is a full year.","h2":"In Missouri, to get the full under-21 driver license you must have no alcohol-related offenses or traffic convictions in the last 12 months.","p":"Right. A clean record for the last 12 months."},"es":{"q":"En Missouri, para obtener la licencia completa para menores de 21 a los 18 años, ¿en qué periodo no puede tener infracciones de alcohol ni condenas de tránsito?","o":["Los últimos 12 meses","Los últimos 3 meses","Los últimos 6 meses","Los últimos 3 años"],"h1":"Es un año completo.","h2":"En Missouri, para obtener la licencia completa para menores de 21 no puede tener infracciones relacionadas con alcohol ni condenas de tránsito en los últimos 12 meses.","p":"Correcto. Un historial limpio en los últimos 12 meses."},"ref":{"doc":"MO","page":17}},{"id":"mo-100","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, you have an intermediate license and turn 18. Which tests must you pass for the full license if you already passed the written and driving tests?","o":["The written knowledge test again","The road driving test again","All four parts of the exam again","Only the vision and road sign tests"],"h1":"You do not repeat the tests you already passed.","h2":"In Missouri, to move from an intermediate license to the full under-21 license, you pass the vision and road sign tests; the written and driving tests are not repeated.","p":"Right. Vision and road signs only."},"es":{"q":"En Missouri, usted tiene licencia intermedia y cumple 18. ¿Qué exámenes debe aprobar para la licencia completa si ya aprobó el escrito y el de manejo?","o":["Otra vez el examen escrito de conocimientos","Otra vez el examen práctico de manejo","Las cuatro partes del examen otra vez","Solo los exámenes de visión y de señales"],"h1":"No repite los exámenes que ya aprobó.","h2":"En Missouri, para pasar de la licencia intermedia a la licencia completa para menores de 21, aprueba los exámenes de visión y de señales; el escrito y el de manejo no se repiten.","p":"Correcto. Solo visión y señales."},"ref":{"doc":"MO","page":17}},{"id":"mo-101","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, your license says you are under 21. What may you do when you turn 21?","o":["You must retake the written test first","The state changes it for you automatically","Get a new one without the minor mark, or wait","You must replace it within 30 days"],"h1":"You have a choice.","h2":"In Missouri, when you turn 21 you may apply and pay for a new license without the minor mark, or simply wait until your under-21 license expires.","p":"Right. Get a new one or wait until it expires."},"es":{"q":"En Missouri, su licencia indica que es menor de 21. ¿Qué puede hacer al cumplir 21?","o":["Primero debe repetir el examen escrito","El estado la cambia automáticamente","Sacar una nueva sin la marca de menor, o esperar","Debe cambiarla dentro de 30 días"],"h1":"Usted puede elegir.","h2":"En Missouri, al cumplir 21 puede solicitar y pagar una licencia nueva sin la marca de menor, o esperar a que su licencia de menor de 21 venza.","p":"Correcto. Sacar una nueva o esperar a que venza."},"ref":{"doc":"MO","page":16}},{"id":"mo-102","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, what is the standard minimum side (peripheral) vision for a driver license?","o":["20 degrees in each eye, or 30 in one eye","45 degrees in one eye, with glasses only","55 degrees in each eye, or 85 degrees in one eye","120 degrees with both eyes together"],"h1":"There are two ways to meet it: both eyes, or one eye alone.","h2":"In Missouri, the standard minimum peripheral vision is at least 55 degrees in each eye, or 85 degrees in one eye.","p":"Right. 55 degrees each eye, or 85 in one."},"es":{"q":"En Missouri, ¿cuál es la visión lateral (periférica) mínima normal para la licencia?","o":["20 grados en cada ojo, o 30 en un ojo","45 grados en un ojo, solo con anteojos","55 grados en cada ojo, o 85 grados en un ojo","120 grados con ambos ojos juntos"],"h1":"Hay dos formas de cumplirla: con ambos ojos o con un solo ojo.","h2":"En Missouri, la visión periférica mínima normal es de al menos 55 grados en cada ojo, o 85 grados en un ojo.","p":"Correcto. 55 grados en cada ojo, o 85 en uno."},"ref":{"doc":"MO","page":19}},{"id":"mo-103","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, your vision is worse than 20/160, with and without glasses. What does this mean?","o":["You must retest every year","You cannot test for or hold a license","You may drive in daylight only","You need a restriction for 45 mph"],"h1":"This is far below the 20/40 standard.","h2":"In Missouri, if both your natural and corrected vision are worse than 20/160, you cannot take the driving test and cannot have a driver license.","p":"Right. Worse than 20/160 means no license."},"es":{"q":"En Missouri, su visión es peor que 20/160, con y sin anteojos. ¿Qué significa esto?","o":["Debe repetir el examen cada año","No puede hacer el examen ni tener licencia","Puede manejar solo de día","Necesita una restricción de 45 mph"],"h1":"Esto está muy por debajo del estándar de 20/40.","h2":"En Missouri, si su visión natural y corregida es peor que 20/160, no puede tomar el examen de manejo ni tener licencia de conducir.","p":"Correcto. Peor que 20/160 significa que no hay licencia."},"ref":{"doc":"MO","page":19}},{"id":"mo-104","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, which of these must the car you bring to the driving test have?","o":["Current plates and inspection sticker","Tinted windows on every side","A working backup camera","A GPS mounted on the dashboard"],"h1":"The examiner checks that the car is legal and safe.","h2":"In Missouri, the vehicle for the driving test must have current license plates and a valid inspection sticker, plus working seat belts, two sets of brakes, a horn and proof of insurance.","p":"Right. Current plates and a valid inspection sticker."},"es":{"q":"En Missouri, ¿cuál de estas cosas debe tener el auto que lleva al examen de manejo?","o":["Placas e inspección vigentes","Ventanas polarizadas en todos los lados","Una cámara de reversa que funcione","Un GPS montado en el tablero"],"h1":"El examinador revisa que el auto sea legal y seguro.","h2":"En Missouri, el vehículo del examen de manejo debe tener placas vigentes y una calcomanía de inspección válida, además de cinturones que funcionen, dos sistemas de frenos, bocina y prueba de seguro.","p":"Correcto. Placas vigentes y calcomanía de inspección válida."},"ref":{"doc":"MO","page":19}},{"id":"mo-105","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, who may ride in the car during your driving test?","o":["Only you and the examiner","Your parent, in the back seat","One friend for support","Anyone who owns the car"],"h1":"The examiner needs to watch only you.","h2":"In Missouri, during the driving test only you and the examiner may be in the vehicle.","p":"Right. Only you and the examiner."},"es":{"q":"En Missouri, ¿quién puede ir en el auto durante su examen de manejo?","o":["Solo usted y el examinador","Su padre o madre, en el asiento de atrás","Un amigo para darle apoyo","Cualquier dueño del auto"],"h1":"El examinador necesita observarlo solo a usted.","h2":"En Missouri, durante el examen de manejo solo pueden ir en el vehículo usted y el examinador.","p":"Correcto. Solo usted y el examinador."},"ref":{"doc":"MO","page":19}},{"id":"mo-106","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how big is the space for parallel parking on the driving test?","o":["20 feet long and 6 feet wide","25 feet long and 7 feet wide","30 feet long and 8 feet wide","35 feet long and 10 feet wide"],"h1":"It is a bit longer than most cars.","h2":"In Missouri, you parallel park in a space 25 feet long and seven feet wide during the driving test.","p":"Right. 25 feet by 7 feet."},"es":{"q":"En Missouri, ¿de qué tamaño es el espacio para estacionarse en paralelo en el examen de manejo?","o":["20 pies de largo y 6 de ancho","25 pies de largo y 7 de ancho","30 pies de largo y 8 de ancho","35 pies de largo y 10 de ancho"],"h1":"Es un poco más largo que la mayoría de los autos.","h2":"En Missouri, en el examen de manejo se estaciona en paralelo en un espacio de 25 pies de largo y siete de ancho.","p":"Correcto. 25 pies por 7 pies."},"ref":{"doc":"MO","page":20}},{"id":"mo-107","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, on the driving test, how close to the curb must you park?","o":["No more than 4 feet","No more than 18 inches","No more than 6 inches","No more than 3 feet"],"h1":"It is a foot and a half.","h2":"In Missouri, when you park parallel or on a hill during the driving test, you must be no more than 18 inches from the curb.","p":"Right. Within 18 inches of the curb."},"es":{"q":"En Missouri, en el examen de manejo, ¿qué tan cerca de la acera debe estacionarse?","o":["A no más de 4 pies","A no más de 18 pulgadas","A no más de 6 pulgadas","A no más de 3 pies"],"h1":"Es un pie y medio.","h2":"En Missouri, al estacionarse en paralelo o en una cuesta durante el examen, debe quedar a no más de 18 pulgadas de la acera.","p":"Correcto. A 18 pulgadas o menos de la acera."},"ref":{"doc":"MO","page":20}},{"id":"mo-108","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how much time do you have to finish parallel parking on the driving test?","o":["Thirty seconds","Five minutes","Ten minutes","Two minutes"],"h1":"It is enough time to do it calmly, but not forever.","h2":"In Missouri, on the driving test you are graded on parking the vehicle within two minutes.","p":"Right. Two minutes."},"es":{"q":"En Missouri, ¿cuánto tiempo tiene para terminar de estacionarse en paralelo en el examen de manejo?","o":["Treinta segundos","Cinco minutos","Diez minutos","Dos minutos"],"h1":"Es tiempo suficiente para hacerlo con calma, pero no ilimitado.","h2":"En Missouri, en el examen de manejo se evalúa que se estacione dentro de dos minutos.","p":"Correcto. Dos minutos."},"ref":{"doc":"MO","page":20}},{"id":"mo-109","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, when you back up during the driving test, where should you look?","o":["Only at the backup camera screen","Straight ahead through the windshield","Over your right shoulder, out the back","Only at the inside rearview mirror"],"h1":"Turn your body to see where you are going.","h2":"In Missouri, during the backing part of the driving test you are graded on looking over your right shoulder through the rear window.","p":"Right. Look over your right shoulder."},"es":{"q":"En Missouri, cuando retrocede durante el examen de manejo, ¿hacia dónde debe mirar?","o":["Solo a la pantalla de la cámara de reversa","Hacia adelante por el parabrisas","Sobre su hombro derecho, hacia atrás","Solo al espejo retrovisor interior"],"h1":"Gire el cuerpo para ver hacia dónde va.","h2":"En Missouri, al retroceder en el examen de manejo se evalúa que mire sobre su hombro derecho por el vidrio trasero.","p":"Correcto. Mire sobre su hombro derecho."},"ref":{"doc":"MO","page":20}},{"id":"mo-110","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, besides losing too many points, which of these makes you fail the driving test right away?","o":["Asking the examiner to repeat a direction","Adjusting your mirror before starting","Breaking a traffic law","Driving a little slowly"],"h1":"The examiner expects you to obey all Missouri traffic laws.","h2":"In Missouri, you fail the driving test if you violate a traffic law, cause a crash, hit a pedestrian, drive dangerously, or refuse to drive as asked.","p":"Right. Breaking a traffic law means you fail."},"es":{"q":"En Missouri, además de perder demasiados puntos, ¿cuál de estas acciones lo hace reprobar el examen de manejo de inmediato?","o":["Pedir al examinador que repita una indicación","Ajustar el espejo antes de empezar","Violar una ley de tránsito","Manejar un poco despacio"],"h1":"El examinador espera que obedezca todas las leyes de tránsito de Missouri.","h2":"En Missouri, reprueba el examen de manejo si viola una ley de tránsito, causa un choque, atropella a un peatón, maneja con peligro o se niega a manejar como le piden.","p":"Correcto. Violar una ley de tránsito lo hace reprobar."},"ref":{"doc":"MO","page":21}},{"id":"mo-111","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you failed the driving test this morning. When may you take it again?","o":["Only after 30 days have passed","Another day; it is one test per day","This afternoon, after lunch","Right away, after a short break"],"h1":"There is a daily limit.","h2":"In Missouri, you may take only one driving test per day, so you must come back another day.","p":"Right. One driving test per day."},"es":{"q":"En Missouri, usted reprobó el examen de manejo esta mañana. ¿Cuándo puede volver a tomarlo?","o":["Solo después de que pasen 30 días","Otro día; se permite un examen por día","Esta tarde, después del almuerzo","De inmediato, después de un descanso"],"h1":"Hay un límite diario.","h2":"En Missouri, solo puede tomar un examen de manejo por día, así que debe volver otro día.","p":"Correcto. Un examen de manejo por día."},"ref":{"doc":"MO","page":21}},{"id":"mo-112","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, what happens after you fail the driving test three times?","o":["Extra training and state approval first","You must wait five years to test again","You may keep testing once a day","You get a restricted license anyway"],"h1":"The state wants you to get more practice with a teacher.","h2":"In Missouri, after three failed driving tests you must complete extra behind-the-wheel training and get approval from the Department of Revenue before you test again.","p":"Right. More training and approval first."},"es":{"q":"En Missouri, ¿qué pasa después de reprobar el examen de manejo tres veces?","o":["Más entrenamiento y aprobación del estado","Debe esperar cinco años para volver a intentarlo","Puede seguir intentando una vez al día","Recibe de todos modos una licencia restringida"],"h1":"El estado quiere que practique más con un instructor.","h2":"En Missouri, después de reprobar tres veces el examen de manejo debe completar más entrenamiento al volante y obtener la aprobación del Departamento de Ingresos antes de volver a tomarlo.","p":"Correcto. Primero más entrenamiento y aprobación."},"ref":{"doc":"MO","page":21}},{"id":"mo-113","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, a person uses a two-way device to get help during the written test. What is this?","o":["A minor mistake that carries no penalty","A reason to retake the test the same day","Allowed if the examiner does not see it","Fraud that can cost your license"],"h1":"Cheating on a state exam is a crime.","h2":"In Missouri, cheating on a license test, including using a recording or two-way device, is fraud: a Class A misdemeanor that can cost you your driving privilege for up to one year.","p":"Right. It is fraud and can cost you your license."},"es":{"q":"En Missouri, una persona usa un aparato de comunicación para recibir ayuda en el examen escrito. ¿Qué es esto?","o":["Un error menor que no tiene castigo","Una razón para repetir el examen el mismo día","Permitido si el examinador no lo ve","Fraude que puede costarle la licencia"],"h1":"Hacer trampa en un examen del estado es un delito.","h2":"En Missouri, hacer trampa en un examen de licencia, incluso usando un aparato de grabación o de comunicación, es fraude: un delito menor Clase A que puede quitarle el privilegio de manejar hasta por un año.","p":"Correcto. Es fraude y puede costarle la licencia."},"ref":{"doc":"MO","page":21}},{"id":"mo-114","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, what is the smallest fine for a second offense of speeding or passing in a work zone on state roads?","o":["$100","$250","$300","$500"],"h1":"It is $50 more than the first-offense minimum.","h2":"In Missouri, speeding or passing in a work zone on state roads carries a minimum fine of $250 for a first offense and $300 for a second or later offense.","p":"Right. At least $300 for a second offense."},"es":{"q":"En Missouri, ¿cuál es la multa mínima por una segunda infracción de exceso de velocidad o de rebasar en una zona de trabajo en carreteras estatales?","o":["$100","$250","$300","$500"],"h1":"Son $50 más que el mínimo de la primera infracción.","h2":"En Missouri, exceder la velocidad o rebasar en una zona de trabajo en carreteras estatales tiene una multa mínima de $250 la primera vez y de $300 la segunda vez o más.","p":"Correcto. Al menos $300 la segunda vez."},"ref":{"doc":"MO","page":22}},{"id":"mo-115","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, when may you pass another vehicle on the right?","o":["When the vehicle ahead is going under the limit on a two-lane road","When there is a wide paved shoulder","Whenever the right side looks clear","When the vehicle ahead is turning left"],"h1":"The other driver must be moving out of your way.","h2":"In Missouri, you may pass on the right when the vehicle ahead is making or about to make a left turn, on a one-way street, or where there are enough marked lanes; never on the shoulder.","p":"Right. You may pass a car that is turning left."},"es":{"q":"En Missouri, ¿cuándo puede rebasar a otro vehículo por la derecha?","o":["Cuando el de adelante va bajo el límite en una vía de dos carriles","Cuando hay un acotamiento pavimentado ancho","Siempre que la derecha se vea libre","Cuando el vehículo de adelante va a girar a la izquierda"],"h1":"El otro conductor debe estar saliendo de su camino.","h2":"En Missouri, puede rebasar por la derecha cuando el vehículo de adelante gira o va a girar a la izquierda, en una calle de un solo sentido o donde hay suficientes carriles marcados; nunca por el acotamiento.","p":"Correcto. Puede rebasar a un auto que gira a la izquierda."},"ref":{"doc":"MO","page":22}},{"id":"mo-116","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, a school bus is getting ready to stop. How far before the stop do its amber lights start flashing?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is about one city block.","h2":"In Missouri, a school bus flashes its amber warning lights 500 feet before it reaches its stop.","p":"Right. Amber lights start 500 feet before the stop."},"es":{"q":"En Missouri, un autobús escolar se prepara para detenerse. ¿A qué distancia antes de la parada empiezan a parpadear sus luces ámbar?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es más o menos una cuadra de ciudad.","h2":"En Missouri, un autobús escolar enciende sus luces ámbar de advertencia 500 pies antes de llegar a su parada.","p":"Correcto. Las luces ámbar empiezan 500 pies antes."},"ref":{"doc":"MO","page":23}},{"id":"mo-117","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, you are driving the opposite way from a stopped school bus on an undivided highway with four lanes. Must you stop?","o":["No, not on a highway with four or more lanes","Yes, all traffic in both directions must stop","Yes, unless the bus is in a school zone","Only if children are on your side of the road"],"h1":"Buses may not drop students where they must cross more than two lanes.","h2":"In Missouri, you do not have to stop when you are going the opposite direction of a school bus on a highway with four or more lanes of traffic.","p":"Right. On four or more lanes, oncoming traffic need not stop."},"es":{"q":"En Missouri, usted va en sentido contrario a un autobús escolar detenido en una carretera sin división de cuatro carriles. ¿Debe detenerse?","o":["No, no en una carretera de cuatro carriles o más","Sí, todo el tráfico en ambos sentidos debe parar","Sí, salvo que el autobús esté en zona escolar","Solo si hay niños de su lado de la vía"],"h1":"Los autobuses no pueden bajar estudiantes donde deban cruzar más de dos carriles.","h2":"En Missouri, no tiene que detenerse si va en sentido contrario a un autobús escolar en una carretera de cuatro carriles de tránsito o más.","p":"Correcto. Con cuatro carriles o más, el tráfico contrario no para."},"ref":{"doc":"MO","page":24}},{"id":"mo-118","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a school bus is stopped in a loading zone at a school where students are not allowed to cross the road. Must you stop?","o":["Only if you are behind the bus","No, you do not have to stop in this case","Yes, every time a bus flashes red","Yes, for at least one minute"],"h1":"The students will not be crossing in front of you.","h2":"In Missouri, you do not have to stop for a school bus in a school loading zone where students are not permitted to cross the roadway.","p":"Right. No stop is required there."},"es":{"q":"En Missouri, un autobús escolar está detenido en una zona de carga de una escuela donde los estudiantes no pueden cruzar la calle. ¿Debe detenerse?","o":["Solo si va detrás del autobús","No, en este caso no tiene que detenerse","Sí, siempre que el autobús tenga luces rojas","Sí, por lo menos un minuto"],"h1":"Los estudiantes no van a cruzar delante de usted.","h2":"En Missouri, no tiene que detenerse ante un autobús escolar en una zona de carga escolar donde los estudiantes no pueden cruzar la calle.","p":"Correcto. Allí no tiene que parar."},"ref":{"doc":"MO","page":24}},{"id":"mo-119","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you stopped for a school bus that is unloading children. When may you go again?","o":["After you count slowly to ten","When the car behind you honks at you","When the bus moves or the driver signals","As soon as the children reach the sidewalk"],"h1":"The bus decides when it is safe.","h2":"In Missouri, after stopping for a school bus you must stay stopped until the bus moves or the bus driver signals you to proceed, and then go with caution.","p":"Right. Wait for the bus to move or for the driver's signal."},"es":{"q":"En Missouri, usted se detuvo por un autobús escolar que baja niños. ¿Cuándo puede seguir?","o":["Después de contar despacio hasta diez","Cuando el auto de atrás le toque la bocina","Cuando el autobús avance o el chofer le indique","En cuanto los niños lleguen a la acera"],"h1":"El autobús decide cuándo es seguro.","h2":"En Missouri, después de detenerse por un autobús escolar debe quedarse detenido hasta que el autobús avance o el chofer le indique seguir, y luego avanzar con cuidado.","p":"Correcto. Espere a que avance o a la señal del chofer."},"ref":{"doc":"MO","page":24}},{"id":"mo-120","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, a driver is found guilty a third time within 5 years of failing to stop for a loading school bus. How long is the suspension?","o":["30 days","90 days","180 days","1 year"],"h1":"The first and second offenses bring 90 days; the third is longer.","h2":"In Missouri, a third or later conviction within five years for failing to stop for a loading or unloading school bus brings a 180-day suspension.","p":"Right. 180 days for a third offense."},"es":{"q":"En Missouri, un conductor es declarado culpable por tercera vez en 5 años de no detenerse ante un autobús escolar que sube o baja estudiantes. ¿Cuánto dura la suspensión?","o":["30 días","90 días","180 días","1 año"],"h1":"La primera y la segunda vez son 90 días; la tercera es más.","h2":"En Missouri, una tercera condena o más en cinco años por no detenerse ante un autobús escolar que sube o baja estudiantes trae una suspensión de 180 días.","p":"Correcto. 180 días la tercera vez."},"ref":{"doc":"MO","page":24}},{"id":"mo-121","scope":"MO","cat":"signals","sign":null,"c":2,"en":{"q":"In Missouri, how far before a turn should you signal?","o":["At least 50 feet","At least 500 feet","At least 100 feet","At least 20 feet"],"h1":"It is about the length of a few houses.","h2":"In Missouri, you should signal at least 100 feet before you turn so other drivers can get ready.","p":"Right. At least 100 feet."},"es":{"q":"En Missouri, ¿a qué distancia antes de un giro debe poner la direccional?","o":["Al menos 50 pies","Al menos 500 pies","Al menos 100 pies","Al menos 20 pies"],"h1":"Es el largo de unas pocas casas.","h2":"En Missouri, debe poner la direccional al menos 100 pies antes de girar para que los demás conductores se preparen.","p":"Correcto. Al menos 100 pies."},"ref":{"doc":"MO","page":24}},{"id":"mo-122","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, where must you never make a U-turn?","o":["At an intersection with a traffic signal or officer","On a long straight road with good visibility","On a quiet street with no signs against it","Where a wide road gives you plenty of room"],"h1":"Think of places where other traffic is being directed.","h2":"In Missouri, never make a U-turn at an intersection controlled by a traffic signal or police officer, on a curve, near the top of a hill, or where a No U-Turn sign is posted.","p":"Right. Not at a signal or where an officer directs traffic."},"es":{"q":"En Missouri, ¿dónde nunca debe dar una vuelta en U?","o":["En una intersección con semáforo o con un policía","En una vía recta y larga con buena visibilidad","En una calle tranquila sin señales en contra","Donde una vía ancha le da espacio"],"h1":"Piense en lugares donde se está dirigiendo el tráfico.","h2":"En Missouri, nunca dé una vuelta en U en una intersección controlada por semáforo o por un policía, en una curva, cerca de la cima de una cuesta, ni donde haya una señal de prohibido dar vuelta en U.","p":"Correcto. No en un semáforo ni donde un policía dirige el tráfico."},"ref":{"doc":"MO","page":25}},{"id":"mo-123","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you turn left from a one-way street onto a two-way street. Which lane should you start from?","o":["The right lane of the one-way street","The middle of the street","Any lane, if you signal","The left lane of the one-way street"],"h1":"Start from the lane closest to the way you are turning.","h2":"In Missouri, when turning left from a one-way street onto a two-way street, begin the turn in the left lane and enter to the right of the yellow center line.","p":"Right. Start from the left lane."},"es":{"q":"En Missouri, gira a la izquierda desde una calle de un solo sentido hacia una de doble sentido. ¿De qué carril debe empezar?","o":["El carril derecho de la calle de un solo sentido","El centro de la calle","Cualquier carril, si pone la direccional","El carril izquierdo de la calle de un solo sentido"],"h1":"Empiece desde el carril más cercano a la dirección del giro.","h2":"En Missouri, al girar a la izquierda desde una calle de un solo sentido hacia una de doble sentido, empiece en el carril izquierdo y entre a la derecha de la línea amarilla central.","p":"Correcto. Empiece desde el carril izquierdo."},"ref":{"doc":"MO","page":25}},{"id":"mo-124","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, how far may you drive in a two-way left-turn lane in the center of the road?","o":["As far as you want if you signal","No more than 500 feet","No more than 50 feet","No more than 1,000 feet"],"h1":"It is a turning lane, not a travel lane.","h2":"In Missouri, a two-way left-turn lane is not a travel lane, and you may not drive in it for more than 500 feet.","p":"Right. No more than 500 feet."},"es":{"q":"En Missouri, ¿qué distancia puede manejar en un carril central de giro a la izquierda en ambos sentidos?","o":["Lo que quiera si pone la direccional","No más de 500 pies","No más de 50 pies","No más de 1,000 pies"],"h1":"Es un carril para girar, no para circular.","h2":"En Missouri, el carril central de giro a la izquierda en ambos sentidos no es un carril para circular, y no puede manejar en él más de 500 pies.","p":"Correcto. No más de 500 pies."},"ref":{"doc":"MO","page":26}},{"id":"mo-125","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, you are pulling out of a side street onto a road with a two-way left-turn lane in the middle. May you use that center lane to merge?","o":["Yes, for up to 500 feet as you merge","Only at night, when traffic is light","No, not when entering from a side street","Yes, it is meant for merging in"],"h1":"The center lane is only for slowing down before a left turn from the main road.","h2":"In Missouri, you should not use a two-way left-turn lane when entering the roadway from a side street; it is only for drivers on the main road getting ready to turn left.","p":"Right. Do not use it to enter from a side street."},"es":{"q":"En Missouri, usted sale de una calle lateral hacia una vía con un carril central de giro a la izquierda en ambos sentidos. ¿Puede usar ese carril central para incorporarse?","o":["Sí, hasta 500 pies mientras se incorpora","Solo de noche, cuando hay poco tráfico","No, no es para entrar desde una calle lateral","Sí, es para incorporarse al tráfico"],"h1":"El carril central es solo para frenar antes de girar a la izquierda desde la vía principal.","h2":"En Missouri, no debe usar el carril central de giro a la izquierda al entrar a la vía desde una calle lateral; es solo para quienes van por la vía principal y van a girar a la izquierda.","p":"Correcto. No lo use para entrar desde una calle lateral."},"ref":{"doc":"MO","page":26}},{"id":"mo-126","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, there are two left-turn lanes. You are in the right-hand one. Which lane should you turn into?","o":["The center turn lane","The right lane of the new road","The left lane of the new road","Either lane you like"],"h1":"Each turn lane has its own matching lane.","h2":"In Missouri, with two left-turn lanes, turn from the right-hand turn lane into the right lane, and from the left-hand turn lane into the left lane.","p":"Right. Right-hand turn lane into the right lane."},"es":{"q":"En Missouri, hay dos carriles para girar a la izquierda. Usted está en el de la derecha. ¿A qué carril debe girar?","o":["Al carril central de giro","Al carril derecho de la nueva vía","Al carril izquierdo de la nueva vía","Al que usted quiera"],"h1":"Cada carril de giro tiene su carril correspondiente.","h2":"En Missouri, con dos carriles de giro a la izquierda, del carril de giro derecho se entra al carril derecho, y del izquierdo al carril izquierdo.","p":"Correcto. Del carril de giro derecho al carril derecho."},"ref":{"doc":"MO","page":26}},{"id":"mo-127","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, what is the truck apron in the middle of a roundabout for?","o":["Large trucks' rear wheels, not cars or pickups","A place to park while you wait","A lane for passing slow cars","A spot to turn around if you miss your exit"],"h1":"Big trucks need extra room to turn.","h2":"In Missouri, the truck apron is the paved area inside a roundabout for the rear wheels of large trucks; cars, SUVs and pickup trucks should not drive on it.","p":"Right. It is for large trucks only."},"es":{"q":"En Missouri, ¿para qué es la plataforma para camiones (truck apron) en el centro de una glorieta?","o":["Para ruedas traseras de camiones, no para autos","Para estacionarse mientras espera","Para rebasar a los autos lentos","Para dar la vuelta si se pasa de su salida"],"h1":"Los camiones grandes necesitan más espacio para girar.","h2":"En Missouri, la plataforma para camiones es la zona pavimentada dentro de la glorieta para las ruedas traseras de los camiones grandes; los autos, SUV y camionetas no deben pasar por ella.","p":"Correcto. Es solo para camiones grandes."},"ref":{"doc":"MO","page":27}},{"id":"mo-128","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you are driving in a two-lane roundabout. May you change lanes inside it?","o":["Yes, whenever there is a gap","Yes, if you use your turn signal","Only to pass a large, slow truck","No, not inside a roundabout"],"h1":"Pick the right lane before you enter.","h2":"In Missouri, do not change lanes inside a roundabout; choose the correct lane before you enter, using signs and pavement markings.","p":"Right. No lane changes in a roundabout."},"es":{"q":"En Missouri, usted maneja en una glorieta de dos carriles. ¿Puede cambiar de carril dentro de ella?","o":["Sí, cuando haya espacio","Sí, si pone la direccional","Solo para rebasar a un camión grande y lento","No, no dentro de una glorieta"],"h1":"Elija el carril correcto antes de entrar.","h2":"En Missouri, no cambie de carril dentro de una glorieta; elija el carril correcto antes de entrar, según las señales y las marcas del pavimento.","p":"Correcto. No se cambia de carril en la glorieta."},"ref":{"doc":"MO","page":27}},{"id":"mo-129","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, you are about to enter a roundabout and an emergency vehicle with a siren is approaching. What should you do?","o":["Enter quickly and stop inside the circle","Enter and drive on the truck apron","Stop in the crosswalk","Do not enter the roundabout until it has passed"],"h1":"Keep the roundabout clear.","h2":"In Missouri, do not enter a roundabout if an emergency vehicle is approaching; yield and wait until it has passed.","p":"Right. Stay out of the roundabout and let it pass."},"es":{"q":"En Missouri, está por entrar a una glorieta y se acerca un vehículo de emergencia con sirena. ¿Qué debe hacer?","o":["Entrar rápido y detenerse dentro del círculo","Entrar y manejar sobre la plataforma para camiones","Detenerse en el cruce peatonal","No entrar a la glorieta hasta que haya pasado"],"h1":"Mantenga libre la glorieta.","h2":"En Missouri, no entre a una glorieta si se acerca un vehículo de emergencia; ceda el paso y espere hasta que haya pasado.","p":"Correcto. No entre y déjelo pasar."},"ref":{"doc":"MO","page":27}},{"id":"mo-130","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, at a J-turn on a four-lane highway, how do you go left from a side road?","o":["Wait in the median for a gap in traffic","Turn right, go far left, then turn left","Cross all lanes at once and turn left","Back up to the nearest median crossing"],"h1":"You never cross fast traffic directly.","h2":"In Missouri, at a J-turn intersection you turn right with traffic, merge into the far left lane, and then make a left turn to go the way you want.","p":"Right. Right, merge left, then turn."},"es":{"q":"En Missouri, en un giro en J (J-turn) de una carretera de cuatro carriles, ¿cómo va hacia la izquierda desde una vía lateral?","o":["Espera en el camellón un espacio en el tráfico","Gira a la derecha, pasa a la izquierda y luego gira","Cruza todos los carriles de una vez y gira a la izquierda","Retrocede hasta el cruce del camellón más cercano"],"h1":"Nunca cruza directamente el tráfico rápido.","h2":"En Missouri, en un giro en J usted gira a la derecha con el tráfico, se pasa al carril izquierdo y luego gira a la izquierda para ir hacia donde quiere.","p":"Correcto. Derecha, carril izquierdo y luego el giro."},"ref":{"doc":"MO","page":27}},{"id":"mo-131","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, a car at 55 mph stops in about 130 to 140 feet. About how far does a fully loaded tractor-trailer need?","o":["Almost 400 feet","About 140 feet","About 200 feet","Almost 1,000 feet"],"h1":"It is close to three times the car's distance.","h2":"In Missouri, the Driver Guide says a fully loaded tractor-trailer may need almost 400 feet to stop, while a car at 55 mph stops in about 130 to 140 feet.","p":"Right. Almost 400 feet."},"es":{"q":"En Missouri, un auto a 55 mph se detiene en unos 130 a 140 pies. ¿Más o menos cuánto necesita un tractocamión totalmente cargado?","o":["Casi 400 pies","Unos 140 pies","Unos 200 pies","Casi 1,000 pies"],"h1":"Es cerca de tres veces la distancia del auto.","h2":"En Missouri, la guía dice que un tractocamión totalmente cargado puede necesitar casi 400 pies para detenerse, mientras que un auto a 55 mph se detiene en unos 130 a 140 pies.","p":"Correcto. Casi 400 pies."},"ref":{"doc":"MO","page":29}},{"id":"mo-132","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, which vehicles must stop at every railroad crossing, so you should be ready when following them?","o":["Motorcycles with passengers","Cars pulling small trailers","Vehicles carrying hazardous materials","Pickup trucks with full beds"],"h1":"Think of tankers and trucks with warning placards.","h2":"In Missouri, vehicles carrying hazardous materials must stop at all railroad crossings, so be ready to stop behind them.","p":"Right. Hazardous materials vehicles stop at every crossing."},"es":{"q":"En Missouri, ¿qué vehículos deben detenerse en todos los cruces de tren, por lo que debe estar listo si va detrás?","o":["Las motos con pasajero","Los autos con remolques pequeños","Los que llevan materiales peligrosos","Las pickups con la caja llena"],"h1":"Piense en camiones cisterna y camiones con letreros de advertencia.","h2":"En Missouri, los vehículos que llevan materiales peligrosos deben detenerse en todos los cruces de tren, así que esté listo para parar detrás de ellos.","p":"Correcto. Los de materiales peligrosos paran en cada cruce."},"ref":{"doc":"MO","page":29}},{"id":"mo-133","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, you are driving near a truck weigh station on a multi-lane highway. Which lane should you avoid?","o":["The center lane","No lane; it does not matter","The right lane, near the station","The left lane"],"h1":"Trucks leave the weigh station slowly.","h2":"In Missouri, avoid driving in the right lane near truck weigh stations so slow-moving trucks can merge back onto the highway easily.","p":"Right. Leave the right lane for the trucks."},"es":{"q":"En Missouri, maneja cerca de una báscula para camiones en una carretera de varios carriles. ¿Qué carril debe evitar?","o":["El carril central","Ninguno; da igual","El carril derecho, junto a la báscula","El carril izquierdo"],"h1":"Los camiones salen despacio de la báscula.","h2":"En Missouri, evite el carril derecho cerca de las básculas para camiones, para que los camiones lentos puedan volver a la carretera con facilidad.","p":"Correcto. Deje el carril derecho para los camiones."},"ref":{"doc":"MO","page":29}},{"id":"mo-134","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a pedestrian crosses in the middle of a block where there is no crosswalk. Who must yield?","o":["No one, they take turns","The pedestrian must yield to all traffic","Drivers must always stop for the pedestrian","Only trucks must yield"],"h1":"Crosswalks give pedestrians priority; the middle of a block does not.","h2":"In Missouri, a pedestrian crossing in the middle of a block without a crosswalk must yield the right-of-way to all traffic, but drivers must still do their best to avoid hitting them.","p":"Right. The pedestrian must yield mid-block."},"es":{"q":"En Missouri, un peatón cruza a mitad de cuadra donde no hay cruce peatonal. ¿Quién debe ceder el paso?","o":["Nadie, se turnan","El peatón debe ceder el paso a todo el tráfico","Los conductores siempre deben parar por el peatón","Solo los camiones deben ceder"],"h1":"El cruce peatonal da prioridad al peatón; la mitad de la cuadra no.","h2":"En Missouri, un peatón que cruza a mitad de cuadra sin cruce peatonal debe ceder el paso a todo el tráfico, pero los conductores igual deben hacer todo lo posible por no atropellarlo.","p":"Correcto. A mitad de cuadra, el peatón cede el paso."},"ref":{"doc":"MO","page":30}},{"id":"mo-135","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, you are walking along a road that has no sidewalk. Which way should you walk?","o":["Facing oncoming traffic","With traffic, so cars come from behind","In the middle of the lane","It does not matter"],"h1":"You want to see the cars coming toward you.","h2":"In Missouri, when there is no sidewalk, pedestrians should walk facing traffic.","p":"Right. Walk facing traffic."},"es":{"q":"En Missouri, usted camina por una vía que no tiene acera. ¿En qué dirección debe caminar?","o":["De frente al tráfico que viene","En el mismo sentido del tráfico","Por el centro del carril","No importa"],"h1":"Usted quiere ver los autos que vienen hacia usted.","h2":"En Missouri, cuando no hay acera, los peatones deben caminar de frente al tráfico.","p":"Correcto. Camine de frente al tráfico."},"ref":{"doc":"MO","page":30}},{"id":"mo-136","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, the car in the next lane has stopped for a pedestrian. What should you do?","o":["Pass it quickly before the pedestrian reaches you","Honk to warn the pedestrian","Change lanes and keep your speed","Do not pass it; slow down and be ready to stop"],"h1":"The pedestrian may be hidden in front of that car.","h2":"In Missouri, do not pass a vehicle that has stopped or slowed down for a pedestrian.","p":"Right. Never pass a car stopped for a pedestrian."},"es":{"q":"En Missouri, el auto del carril de al lado se detuvo por un peatón. ¿Qué debe hacer?","o":["Rebáselo rápido antes de que el peatón llegue","Toque la bocina para avisar al peatón","Cambie de carril y siga a la misma velocidad","No lo rebase; baje la velocidad y esté listo para parar"],"h1":"El peatón puede estar oculto delante de ese auto.","h2":"En Missouri, no rebase a un vehículo que se detuvo o bajó la velocidad por un peatón.","p":"Correcto. Nunca rebase a un auto detenido por un peatón."},"ref":{"doc":"MO","page":30}},{"id":"mo-137","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you want to turn right and there is a bicycle lane next to you with a cyclist in it. What is the rule?","o":["The cyclist must stop and let you turn","You may drive in the bike lane for a block","Yield to the cyclist, then cross the bike lane","You may not cross a bike lane at all"],"h1":"You can enter the bike lane only after the cyclist is safe.","h2":"In Missouri, you may cross a bicycle lane when turning or entering or leaving the road, but you must yield to bicyclists in the lane.","p":"Right. Cross only after yielding to the cyclist."},"es":{"q":"En Missouri, usted quiere girar a la derecha y a su lado hay un carril de bicicletas con un ciclista. ¿Cuál es la regla?","o":["El ciclista debe parar y dejarlo girar","Puede manejar en el carril de bicicletas una cuadra","Ceda el paso al ciclista y luego cruce el carril","No puede cruzar nunca un carril de bicicletas"],"h1":"Puede entrar al carril de bicicletas solo cuando el ciclista esté seguro.","h2":"En Missouri, puede cruzar un carril de bicicletas al girar o al entrar o salir de la vía, pero debe ceder el paso a los ciclistas en ese carril.","p":"Correcto. Cruce solo después de ceder el paso al ciclista."},"ref":{"doc":"MO","page":31}},{"id":"mo-138","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, a cyclist is riding on a one-way street. Where may the cyclist ride?","o":["As far left as is safe, or near the right side","Only in the gutter at the far right","Only on the sidewalk, never the street","Only in the center of the street"],"h1":"One-way streets give cyclists another choice.","h2":"In Missouri, on a one-way street a bicyclist may choose to ride as far left as is safe, as well as near the right side.","p":"Right. On a one-way street, either side is allowed."},"es":{"q":"En Missouri, un ciclista va por una calle de un solo sentido. ¿Por dónde puede ir?","o":["A la izquierda si es seguro, o a la derecha","Solo junto a la cuneta, a la derecha","Solo por la acera, nunca por la calle","Solo por el centro de la calle"],"h1":"Las calles de un solo sentido le dan al ciclista otra opción.","h2":"En Missouri, en una calle de un solo sentido un ciclista puede ir tan a la izquierda como sea seguro, además de cerca del lado derecho.","p":"Correcto. En un solo sentido puede ir por cualquiera de los lados."},"ref":{"doc":"MO","page":32}},{"id":"mo-139","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, may you ride a moped on an interstate highway?","o":["Yes, in the right lane","Yes, on the shoulder","Only during daylight","No, never on an interstate"],"h1":"Mopeds are too slow for these roads.","h2":"In Missouri, the law does not allow you to ride a moped on any part of the federal interstate highway system.","p":"Right. No mopeds on interstates."},"es":{"q":"En Missouri, ¿puede manejar una motoneta en una autopista interestatal?","o":["Sí, en el carril derecho","Sí, por el acotamiento","Solo de día","No, nunca en una interestatal"],"h1":"Las motonetas son demasiado lentas para estas vías.","h2":"En Missouri, la ley no permite manejar una motoneta en ninguna parte del sistema federal de autopistas interestatales.","p":"Correcto. No se permiten motonetas en interestatales."},"ref":{"doc":"MO","page":32}},{"id":"mo-140","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, does state law require bicycle riders to wear a helmet?","o":["Only on state highways","No, but wearing one is wise","Yes, every rider of every age","Yes, but only at night"],"h1":"The guide strongly recommends one, even though it is not required.","h2":"In Missouri, state law does not require bicycle or moped riders to wear a helmet, but wearing a safety-certified helmet can prevent serious head injuries or death.","p":"Right. Not required by state law, but strongly advised."},"es":{"q":"En Missouri, ¿la ley estatal exige que los ciclistas usen casco?","o":["Solo en carreteras estatales","No, pero se recomienda usarlo","Sí, a todos los ciclistas de cualquier edad","Sí, pero solo de noche"],"h1":"La guía lo recomienda mucho, aunque no es obligatorio.","h2":"En Missouri, la ley estatal no exige casco a los ciclistas ni a quienes manejan motoneta, pero un casco certificado puede evitar lesiones graves en la cabeza o la muerte.","p":"Correcto. No lo exige la ley estatal, pero se recomienda mucho."},"ref":{"doc":"MO","page":32}},{"id":"mo-141","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, what is the top speed of a vehicle that counts as a motorized bicycle (moped)?","o":["15 mph","30 mph","45 mph","55 mph"],"h1":"It also has a motor of 50 cc or less.","h2":"In Missouri, a motorized bicycle has a motor of no more than 50 cc and can go no faster than 30 miles per hour on level ground.","p":"Right. No more than 30 mph."},"es":{"q":"En Missouri, ¿cuál es la velocidad máxima de un vehículo que cuenta como bicicleta motorizada (motoneta)?","o":["15 mph","30 mph","45 mph","55 mph"],"h1":"Además tiene un motor de 50 cc o menos.","h2":"En Missouri, una bicicleta motorizada tiene un motor de no más de 50 cc y no puede ir a más de 30 millas por hora en terreno plano.","p":"Correcto. No más de 30 mph."},"ref":{"doc":"MO","page":33}},{"id":"mo-142","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, must you register your moped or bicycle and have it inspected?","o":["Only the moped must be inspected","Only the bicycle must be registered","No, but it needs the required equipment","Yes, both every year"],"h1":"There is no paperwork, but there are equipment rules.","h2":"In Missouri, mopeds and bicycles do not have to be registered or inspected, but they must have the equipment state law requires.","p":"Right. No registration or inspection, but required equipment."},"es":{"q":"En Missouri, ¿debe registrar su motoneta o bicicleta y hacerla inspeccionar?","o":["Solo se inspecciona la motoneta","Solo se registra la bicicleta","No, pero necesita el equipo exigido","Sí, las dos cosas cada año"],"h1":"No hay trámites, pero sí reglas de equipo.","h2":"En Missouri, las motonetas y bicicletas no tienen que registrarse ni inspeccionarse, pero deben tener el equipo que exige la ley estatal.","p":"Correcto. Sin registro ni inspección, pero con el equipo exigido."},"ref":{"doc":"MO","page":33}},{"id":"mo-143","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, a bicycle's brakes must be able to stop it within what distance at 10 mph?","o":["10 feet","25 feet","50 feet","100 feet"],"h1":"It is the same number as the length of the parallel parking space on the driving test.","h2":"In Missouri, a bicycle's or moped's brakes must be able to stop it within 25 feet when traveling 10 mph.","p":"Right. Within 25 feet at 10 mph."},"es":{"q":"En Missouri, ¿en qué distancia deben poder detener la bicicleta sus frenos a 10 mph?","o":["10 pies","25 pies","50 pies","100 pies"],"h1":"Es el mismo número que el largo del espacio de estacionamiento del examen de manejo.","h2":"En Missouri, los frenos de una bicicleta o motoneta deben poder detenerla en 25 pies cuando va a 10 mph.","p":"Correcto. En 25 pies a 10 mph."},"ref":{"doc":"MO","page":33}},{"id":"mo-144","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, a cyclist rides at night. From how far must the front white light be visible?","o":["50 feet","100 feet","500 feet","1,000 feet"],"h1":"It is the same distance at which you dim your high beams.","h2":"In Missouri, a bicycle ridden at night needs a white front light that other drivers can see from 500 feet.","p":"Right. Visible from 500 feet."},"es":{"q":"En Missouri, un ciclista maneja de noche. ¿Desde qué distancia debe verse su luz blanca delantera?","o":["50 pies","100 pies","500 pies","1,000 pies"],"h1":"Es la misma distancia a la que usted baja las luces altas.","h2":"En Missouri, una bicicleta que se usa de noche necesita una luz blanca delantera que los demás conductores puedan ver desde 500 pies.","p":"Correcto. Visible desde 500 pies."},"ref":{"doc":"MO","page":33}},{"id":"mo-145","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, a bicycle at night may use a rear red reflector instead of a red light. From how far must it show in a car's low beams?","o":["100 feet","300 feet","600 feet","1,000 feet"],"h1":"It is a bit farther than the front light rule.","h2":"In Missouri, a bicycle at night needs a rear red reflector of at least two square inches, or a red light, that drivers can see in their low beams from 600 feet.","p":"Right. Visible from 600 feet."},"es":{"q":"En Missouri, una bicicleta puede usar de noche un reflector rojo trasero en lugar de una luz roja. ¿Desde qué distancia debe verse con las luces bajas de un auto?","o":["100 pies","300 pies","600 pies","1,000 pies"],"h1":"Es un poco más que la regla de la luz delantera.","h2":"En Missouri, una bicicleta de noche necesita un reflector rojo trasero de al menos dos pulgadas cuadradas, o una luz roja, que los conductores vean con sus luces bajas desde 600 pies.","p":"Correcto. Visible desde 600 pies."},"ref":{"doc":"MO","page":33}},{"id":"mo-146","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, what is the most power an electric bicycle's motor may have?","o":["There is no limit","Less than 750 watts","Less than 50 watts","Less than 2,000 watts"],"h1":"It is under a thousand.","h2":"In Missouri, an electric bicycle has working pedals, a seat, and an electric motor of less than 750 watts.","p":"Right. Less than 750 watts."},"es":{"q":"En Missouri, ¿cuál es la potencia máxima del motor de una bicicleta eléctrica?","o":["No hay límite","Menos de 750 vatios","Menos de 50 vatios","Menos de 2,000 vatios"],"h1":"Es menos de mil.","h2":"En Missouri, una bicicleta eléctrica tiene pedales que funcionan, asiento y un motor eléctrico de menos de 750 vatios.","p":"Correcto. Menos de 750 vatios."},"ref":{"doc":"MO","page":33}},{"id":"mo-147","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, a Class 3 electric bicycle helps the rider pedal up to what speed?","o":["15 mph","20 mph","28 mph","35 mph"],"h1":"Classes 1 and 2 stop helping at 20 mph; Class 3 goes higher.","h2":"In Missouri, a Class 3 electric bicycle gives pedal assistance up to 28 miles per hour, while Classes 1 and 2 stop at 20 mph.","p":"Right. Class 3 assists up to 28 mph."},"es":{"q":"En Missouri, ¿hasta qué velocidad ayuda al pedaleo una bicicleta eléctrica Clase 3?","o":["15 mph","20 mph","28 mph","35 mph"],"h1":"Las Clases 1 y 2 dejan de ayudar a 20 mph; la Clase 3 llega más alto.","h2":"En Missouri, una bicicleta eléctrica Clase 3 ayuda al pedaleo hasta 28 millas por hora, mientras que las Clases 1 y 2 paran a 20 mph.","p":"Correcto. La Clase 3 ayuda hasta 28 mph."},"ref":{"doc":"MO","page":33}},{"id":"mo-148","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, do you need a driver license to ride an electric bicycle?","o":["No, no license is required","Yes, a regular driver license","Yes, a motorcycle endorsement","Only for Class 2"],"h1":"Electric bicycles are treated differently from mopeds.","h2":"In Missouri, riding an electric bicycle as defined by state law does not require an operator license or motorcycle license.","p":"Right. No license is needed for an e-bike."},"es":{"q":"En Missouri, ¿necesita licencia de conducir para usar una bicicleta eléctrica?","o":["No, no se exige licencia","Sí, una licencia de conducir normal","Sí, un endoso de motocicleta","Solo para la Clase 2"],"h1":"Las bicicletas eléctricas se tratan distinto a las motonetas.","h2":"En Missouri, manejar una bicicleta eléctrica según la define la ley estatal no requiere licencia de conducir ni de motocicleta.","p":"Correcto. No se necesita licencia para una bicicleta eléctrica."},"ref":{"doc":"MO","page":33}},{"id":"mo-149","scope":"MO","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Missouri, how can you recognize the cars in an organized funeral procession?","o":["They drive in the left lane only","They fly small green flags","They always drive at least 40 mph","Each car has its emergency flashers on"],"h1":"Look for lights that blink on each car.","h2":"In Missouri, every vehicle in a funeral procession must use its flashing emergency lights.","p":"Right. Each car uses its flashing emergency lights."},"es":{"q":"En Missouri, ¿cómo puede reconocer los autos de un cortejo fúnebre organizado?","o":["Van solo por el carril izquierdo","Llevan pequeñas banderas verdes","Siempre van a 40 mph o más","Cada auto lleva las intermitentes encendidas"],"h1":"Busque luces que parpadean en cada auto.","h2":"En Missouri, todos los vehículos de un cortejo fúnebre deben usar sus luces intermitentes de emergencia.","p":"Correcto. Cada auto usa sus luces intermitentes."},"ref":{"doc":"MO","page":33}},{"id":"mo-150","scope":"MO","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Missouri, a funeral procession is passing. Which of these is against the rules for other drivers?","o":["Turning onto another street to go around it","Joining the procession to get the right-of-way","Waiting until the procession has passed","Passing it where a passing lane is provided"],"h1":"You may not use the procession to skip traffic lights.","h2":"In Missouri, drivers not in a funeral procession may not join it to get the right-of-way, drive between its vehicles, or pass it except where a passing lane is provided.","p":"Right. Never join a procession to get the right-of-way."},"es":{"q":"En Missouri, pasa un cortejo fúnebre. ¿Cuál de estas acciones va contra las reglas para los demás conductores?","o":["Girar a otra calle para rodearlo","Unirse al cortejo para tener el derecho de paso","Esperar a que pase el cortejo","Rebasarlo donde hay un carril de rebase"],"h1":"No puede usar el cortejo para saltarse los semáforos.","h2":"En Missouri, los conductores que no van en el cortejo fúnebre no pueden unirse a él para tener el derecho de paso, meterse entre sus vehículos, ni rebasarlo salvo donde haya un carril de rebase.","p":"Correcto. Nunca se una al cortejo para tener el paso."},"ref":{"doc":"MO","page":34}},{"id":"mo-151","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, besides a fine, what else can a judge order for littering?","o":["Loss of your car","A five-year license denial","Only community service","Up to one year in jail"],"h1":"Littering can be punished like other misdemeanors.","h2":"In Missouri, a person found guilty of littering may have to pay up to a $1,000 fine and/or spend up to one year in jail.","p":"Right. Up to one year in jail."},"es":{"q":"En Missouri, además de una multa, ¿qué más puede ordenar un juez por tirar basura?","o":["Quitarle el auto","Negarle la licencia cinco años","Solo servicio comunitario","Hasta un año de cárcel"],"h1":"Tirar basura se puede castigar como otros delitos menores.","h2":"En Missouri, una persona declarada culpable de tirar basura puede tener que pagar una multa de hasta $1,000 y/o pasar hasta un año en la cárcel.","p":"Correcto. Hasta un año de cárcel."},"ref":{"doc":"MO","page":34}},{"id":"mo-152","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, on which side may you normally park on a one-way street?","o":["Either the right or the left side","Only on the right side","Only on the left side","Neither side; it is not allowed"],"h1":"All traffic goes the same way, so both curbs face the right direction.","h2":"In Missouri, on a one-way street you may normally park on either the right or the left side.","p":"Right. Either side on a one-way street."},"es":{"q":"En Missouri, ¿de qué lado puede estacionarse normalmente en una calle de un solo sentido?","o":["Del lado derecho o del izquierdo","Solo del lado derecho","Solo del lado izquierdo","De ningún lado; está prohibido"],"h1":"Todo el tráfico va en el mismo sentido, así que ambas aceras quedan bien orientadas.","h2":"En Missouri, en una calle de un solo sentido normalmente puede estacionarse del lado derecho o del izquierdo.","p":"Correcto. De cualquier lado en un solo sentido."},"ref":{"doc":"MO","page":35}},{"id":"mo-153","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, where is it against the rules to park?","o":["In a marked space in a parking lot","Next to a curb with no paint","On the left side of a two-way street","On the right side of a one-way street"],"h1":"Your car would face against traffic.","h2":"In Missouri, do not park on the left side of a two-way street, facing against traffic, on a bridge, or next to a curb painted yellow.","p":"Right. Not on the left side of a two-way street."},"es":{"q":"En Missouri, ¿dónde está prohibido estacionarse?","o":["En un espacio marcado de un estacionamiento","Junto a una acera sin pintura","Del lado izquierdo de una calle de doble sentido","Del lado derecho de una calle de un solo sentido"],"h1":"Su auto quedaría en contra del tráfico.","h2":"En Missouri, no se estacione del lado izquierdo de una calle de doble sentido, en contra del tráfico, sobre un puente ni junto a una acera pintada de amarillo.","p":"Correcto. No del lado izquierdo de una calle de doble sentido."},"ref":{"doc":"MO","page":35}},{"id":"mo-154","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, your friend has a disability placard but is not in the car. May you park in a disability space while you shop?","o":["Yes, showing the placard is enough","Yes, but only for up to 15 minutes","Yes, but only after 6 p.m.","No, the disabled person must be with you"],"h1":"The space is for the person, not the card.","h2":"In Missouri, a disability parking space may be used only when the placard or plates are shown and the person with the disability is riding in the vehicle or is being dropped off or picked up.","p":"Right. The person must be with the vehicle."},"es":{"q":"En Missouri, su amigo tiene un permiso de discapacidad, pero no va en el auto. ¿Puede estacionarse en un espacio para discapacitados mientras compra?","o":["Sí, basta con mostrar el permiso","Sí, pero solo hasta 15 minutos","Sí, pero solo después de las 6 p.m.","No, la persona debe ir con usted"],"h1":"El espacio es para la persona, no para la tarjeta.","h2":"En Missouri, un espacio para discapacitados solo se puede usar si se muestra el permiso o las placas y la persona con discapacidad va en el vehículo o está subiendo o bajando de él.","p":"Correcto. La persona debe estar con el vehículo."},"ref":{"doc":"MO","page":35}},{"id":"mo-155","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, what is the fine range for illegally parking in a space for people with disabilities?","o":["$10 to $25","$50 to $300","$500 to $1,000","$1,000 to $5,000"],"h1":"The smallest fine is $50.","h2":"In Missouri, a person convicted of illegally parking in a disability space can be fined no less than $50 and no more than $300.","p":"Right. $50 to $300."},"es":{"q":"En Missouri, ¿cuál es el rango de la multa por estacionarse sin derecho en un espacio para personas con discapacidad?","o":["$10 a $25","$50 a $300","$500 a $1,000","$1,000 a $5,000"],"h1":"La multa más baja es de $50.","h2":"En Missouri, una persona condenada por estacionarse sin derecho en un espacio para discapacitados puede recibir una multa de no menos de $50 ni más de $300.","p":"Correcto. De $50 a $300."},"ref":{"doc":"MO","page":36}},{"id":"mo-156","scope":"MO","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Missouri, may you park in the striped access aisle next to a disability parking space?","o":["No, it is illegal to park there","Yes, if you have a placard","Yes, for a short stop","Only motorcycles may park there"],"h1":"People need that space for wheelchairs and ramps.","h2":"In Missouri, it is illegal to park in the access aisles next to disability parking spaces.","p":"Right. Never park in the access aisle."},"es":{"q":"En Missouri, ¿puede estacionarse en el pasillo rayado junto a un espacio para personas con discapacidad?","o":["No, es ilegal estacionarse allí","Sí, si tiene un permiso","Sí, para una parada corta","Solo las motocicletas pueden estacionarse allí"],"h1":"La gente necesita ese espacio para sillas de ruedas y rampas.","h2":"En Missouri, es ilegal estacionarse en los pasillos de acceso junto a los espacios para personas con discapacidad.","p":"Correcto. Nunca se estacione en el pasillo de acceso."},"ref":{"doc":"MO","page":36}},{"id":"mo-157","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, to start parallel parking, where do you stop your car?","o":["Half a car length behind the car ahead","Next to the curb in front of the space","Beside the car ahead, about 1.5 feet away","Directly behind the empty space, close to it"],"h1":"You line up beside the car in front, with a small gap.","h2":"In Missouri, to parallel park, stop even with the vehicle ahead of the space and about one and a half feet to the left of it, then back in.","p":"Right. Even with the car ahead, about 1 and a half feet away."},"es":{"q":"En Missouri, para empezar a estacionarse en paralelo, ¿dónde detiene su auto?","o":["Medio auto detrás del auto de adelante","Junto a la acera delante del espacio","Al lado del auto de adelante, a unos 1.5 pies","Justo detrás del espacio vacío"],"h1":"Se alinea al lado del auto de adelante, con un pequeño espacio.","h2":"En Missouri, para estacionarse en paralelo, deténgase a la par del vehículo de adelante del espacio y a unos pie y medio a su izquierda, y luego retroceda.","p":"Correcto. A la par del auto de adelante, a pie y medio."},"ref":{"doc":"MO","page":36}},{"id":"mo-158","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, your car breaks down and you stop on the shoulder of a highway. Besides the flashers, how can you signal for help?","o":["Leave the driver's door wide open","Raise the hood or tie a white cloth to the antenna","Stand in the traffic lane and wave your arms","Turn on your high beams and leave them on"],"h1":"The guide suggests a sign other drivers and police recognize.","h2":"In Missouri, if you stop on the shoulder in an emergency, turn on your flashers and raise the hood or tie a white cloth to the antenna, side mirror or door handle.","p":"Right. Raise the hood or use a white cloth."},"es":{"q":"En Missouri, su auto se descompone y se detiene en el acotamiento de una carretera. Además de las intermitentes, ¿cómo puede pedir ayuda?","o":["Dejar bien abierta la puerta del conductor","Levantar el capó o atar un trapo blanco a la antena","Pararse en el carril de tránsito y agitar los brazos","Encender las luces altas y dejarlas así"],"h1":"La guía sugiere una señal que otros conductores y la policía reconocen.","h2":"En Missouri, si se detiene en el acotamiento por una emergencia, encienda las intermitentes y levante el capó o ate un trapo blanco a la antena, el espejo o la manija de la puerta.","p":"Correcto. Levante el capó o use un trapo blanco."},"ref":{"doc":"MO","page":39}},{"id":"mo-159","scope":"MO","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Missouri, what is unusual about driving through a Diverging Diamond Interchange (DDI)?","o":["You must stop in the middle of the bridge","You enter by turning left across traffic","Trucks are not allowed","You drive on the left side for a short way"],"h1":"Traffic crosses over to the other side for a short stretch.","h2":"In Missouri, when you drive through a Diverging Diamond Interchange, you travel on the left side of the roadway for a short distance, guided by signs and signals.","p":"Right. You briefly drive on the left side."},"es":{"q":"En Missouri, ¿qué tiene de especial manejar por un intercambio de diamante divergente (DDI)?","o":["Debe detenerse en medio del puente","Entra girando a la izquierda a través del tráfico","No se permiten camiones","Maneja por el lado izquierdo un tramo corto"],"h1":"El tráfico cruza al otro lado por un tramo corto.","h2":"En Missouri, al pasar por un intercambio de diamante divergente usted va por el lado izquierdo de la vía por un tramo corto, guiado por señales y semáforos.","p":"Correcto. Por un momento va por el lado izquierdo."},"ref":{"doc":"MO","page":40}},{"id":"mo-160","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, you are on a road with three lanes going your way, and many cars are entering the right lane. Which lane should you use?","o":["The shoulder","The center lane","The right lane","The left lane"],"h1":"Normally you keep right, but leave room for entering traffic.","h2":"In Missouri, on a road with three or more lanes in your direction, stay in the right lane except to pass, but use the center lane if a lot of traffic is entering the right lane.","p":"Right. Use the center lane."},"es":{"q":"En Missouri, usted va por una vía con tres carriles en su sentido y muchos autos están entrando al carril derecho. ¿Qué carril debe usar?","o":["El acotamiento","El carril central","El carril derecho","El carril izquierdo"],"h1":"Normalmente va a la derecha, pero deje espacio al tráfico que entra.","h2":"En Missouri, en una vía con tres carriles o más en su sentido, vaya por el carril derecho salvo para rebasar, pero use el carril central si mucho tráfico está entrando al carril derecho.","p":"Correcto. Use el carril central."},"ref":{"doc":"MO","page":43}},{"id":"mo-161","scope":"MO","cat":"signals","sign":null,"c":2,"en":{"q":"In Missouri, you reach an intersection where the traffic lights are dark because of a power outage. What should you do?","o":["Yield only to cars on your left","Treat it like a flashing yellow light","Treat it as a four-way stop","Drive through if no one is coming"],"h1":"With no working signal, everyone stops first.","h2":"In Missouri, traffic signals that are dark or not working operate as a four-way stop.","p":"Right. A dark signal is a four-way stop."},"es":{"q":"En Missouri, llega a una intersección donde los semáforos están apagados por un corte de luz. ¿Qué debe hacer?","o":["Ceder el paso solo a los autos de su izquierda","Tratarla como una luz amarilla intermitente","Tratarla como un alto en cuatro sentidos","Pasar si no viene nadie"],"h1":"Sin semáforo funcionando, todos se detienen primero.","h2":"En Missouri, los semáforos apagados o que no funcionan se tratan como un alto en cuatro sentidos.","p":"Correcto. Un semáforo apagado es un alto en cuatro sentidos."},"ref":{"doc":"MO","page":45}},{"id":"mo-162","scope":"MO","cat":"signals","sign":null,"c":0,"en":{"q":"In Missouri, a reflective orange triangle is on the back of a farm vehicle ahead. What does it tell you?","o":["The vehicle travels at less than 25 mph","The vehicle carries hazardous materials","The vehicle is about to turn left","The vehicle is a school bus"],"h1":"This sign marks slow-moving vehicles.","h2":"In Missouri, a reflective orange triangle on the back of a vehicle means it travels at less than 25 mph, like farm equipment or construction machines.","p":"Right. It is slower than 25 mph."},"es":{"q":"En Missouri, hay un triángulo naranja reflectante en la parte trasera de un vehículo agrícola adelante. ¿Qué le indica?","o":["El vehículo va a menos de 25 mph","El vehículo lleva materiales peligrosos","El vehículo va a girar a la izquierda","El vehículo es un autobús escolar"],"h1":"Esta señal marca vehículos lentos.","h2":"En Missouri, un triángulo naranja reflectante en la parte trasera de un vehículo indica que va a menos de 25 mph, como la maquinaria agrícola o de construcción.","p":"Correcto. Va a menos de 25 mph."},"ref":{"doc":"MO","page":47}},{"id":"mo-163","scope":"MO","cat":"signals","sign":null,"c":3,"en":{"q":"In Missouri, a yellow turn sign (not a curve sign) warns of a sharp turn. What is the recommended maximum speed for such a turn?","o":["45 mph or less","55 mph or less","The posted speed limit","30 mph or less"],"h1":"Turn signs are used for sharper bends than curve signs.","h2":"In Missouri, a turn sign warns of a sharp turn where the recommended maximum speed is 30 mph or less.","p":"Right. 30 mph or less."},"es":{"q":"En Missouri, una señal amarilla de giro (no de curva) avisa de una vuelta cerrada. ¿Cuál es la velocidad máxima recomendada para esa vuelta?","o":["45 mph o menos","55 mph o menos","El límite de velocidad indicado","30 mph o menos"],"h1":"Las señales de giro se usan para vueltas más cerradas que las de curva.","h2":"En Missouri, una señal de giro avisa de una vuelta cerrada donde la velocidad máxima recomendada es de 30 mph o menos.","p":"Correcto. 30 mph o menos."},"ref":{"doc":"MO","page":47}},{"id":"mo-164","scope":"MO","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Missouri, what is the maximum speed on lettered roads (like Route A or Route ZZ) unless a sign says otherwise?","o":["45 mph","55 mph","60 mph","65 mph"],"h1":"These small state roads have the lowest rural limit in the table.","h2":"In Missouri, the speed guide lists 55 mph as the maximum on lettered roads, unless posted limits say otherwise.","p":"Right. 55 mph on lettered roads."},"es":{"q":"En Missouri, ¿cuál es la velocidad máxima en las carreteras con letras (como la Ruta A o la Ruta ZZ) salvo que una señal diga otra cosa?","o":["45 mph","55 mph","60 mph","65 mph"],"h1":"Estas carreteras estatales pequeñas tienen el límite rural más bajo de la tabla.","h2":"En Missouri, la guía de velocidades indica 55 mph como máximo en las carreteras con letras, salvo que los límites indicados digan otra cosa.","p":"Correcto. 55 mph en carreteras con letras."},"ref":{"doc":"MO","page":50}},{"id":"mo-165","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, what is the maximum speed on rural expressways unless a sign says otherwise?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"It is lower than rural interstates but higher than lettered roads.","h2":"In Missouri, the speed guide lists 65 mph as the maximum on rural expressways, unless posted limits say otherwise.","p":"Right. 65 mph on rural expressways."},"es":{"q":"En Missouri, ¿cuál es la velocidad máxima en las vías rápidas rurales (expressways) salvo que una señal diga otra cosa?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Es menor que en las interestatales rurales, pero mayor que en las carreteras con letras.","h2":"En Missouri, la guía de velocidades indica 65 mph como máximo en las vías rápidas rurales, salvo que los límites indicados digan otra cosa.","p":"Correcto. 65 mph en vías rápidas rurales."},"ref":{"doc":"MO","page":50}},{"id":"mo-166","scope":"MO","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Missouri, what is the maximum speed on interstates and freeways inside urbanized areas unless a sign says otherwise?","o":["45 mph","55 mph","60 mph","70 mph"],"h1":"Cities have more ramps and merging, so the limit is lower than rural interstates.","h2":"In Missouri, the speed guide lists 60 mph as the maximum on interstates, freeways and expressways within urbanized areas, unless posted limits say otherwise.","p":"Right. 60 mph in urbanized areas."},"es":{"q":"En Missouri, ¿cuál es la velocidad máxima en interestatales y autopistas dentro de zonas urbanizadas salvo que una señal diga otra cosa?","o":["45 mph","55 mph","60 mph","70 mph"],"h1":"Las ciudades tienen más rampas y entradas, así que el límite es menor que en las interestatales rurales.","h2":"En Missouri, la guía de velocidades indica 60 mph como máximo en interestatales, autopistas y vías rápidas dentro de zonas urbanizadas, salvo que los límites indicados digan otra cosa.","p":"Correcto. 60 mph en zonas urbanizadas."},"ref":{"doc":"MO","page":50}},{"id":"mo-167","scope":"MO","cat":"signals","sign":null,"c":0,"en":{"q":"In Missouri, how often are the emergency reference markers placed along interstates?","o":["Every two-tenths of a mile","Every one full mile","Every five miles","Only at exits and ramps"],"h1":"They are close enough that one is always in sight.","h2":"In Missouri, emergency reference markers are placed every two-tenths of a mile along interstates, so you can always see one and tell responders where you are.","p":"Right. Every two-tenths of a mile."},"es":{"q":"En Missouri, ¿cada cuánto se colocan los marcadores de referencia para emergencias en las interestatales?","o":["Cada dos décimas de milla","Cada milla completa","Cada cinco millas","Solo en salidas y rampas"],"h1":"Están tan cerca que siempre se ve uno.","h2":"En Missouri, los marcadores de referencia para emergencias están cada dos décimas de milla en las interestatales, para que siempre vea uno y pueda decir a los socorristas dónde está.","p":"Correcto. Cada dos décimas de milla."},"ref":{"doc":"MO","page":54}},{"id":"mo-168","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, where does the Driver Guide say children 12 and under should ride?","o":["On an adult's lap","Anywhere if wearing a lap belt","Properly restrained in a rear seat","In the front seat with an air bag"],"h1":"Air bags in the front can hurt children.","h2":"In Missouri, the Driver Guide says children 12 and under should always ride properly restrained in a rear seat.","p":"Right. Restrained in the back seat."},"es":{"q":"En Missouri, ¿dónde dice la guía que deben ir los niños de 12 años o menos?","o":["Sentados en las piernas de un adulto","En cualquier lugar con cinturón de cadera","Bien asegurados en un asiento trasero","En el asiento delantero con bolsa de aire"],"h1":"Las bolsas de aire de adelante pueden lastimar a los niños.","h2":"En Missouri, la guía dice que los niños de 12 años o menos siempre deben ir bien asegurados en un asiento trasero.","p":"Correcto. Asegurados en el asiento de atrás."},"ref":{"doc":"MO","page":55}},{"id":"mo-169","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, a child is 6 years old but weighs only 35 pounds. How must the child ride?","o":["Without a restraint on short trips","In a child restraint that fits the child","With only the regular adult seat belt","With a lap belt in the front seat"],"h1":"Weight matters as much as age for small children.","h2":"In Missouri, a child weighing less than 40 pounds, no matter the age, must ride in a child passenger restraint system appropriate for that child.","p":"Right. Under 40 pounds means a child restraint."},"es":{"q":"En Missouri, un niño tiene 6 años pero pesa solo 35 libras. ¿Cómo debe viajar?","o":["Sin sistema de retención en viajes cortos","En un asiento infantil adecuado para él","Solo con el cinturón normal de adulto","Con cinturón de cadera en el asiento delantero"],"h1":"Para niños pequeños, el peso importa tanto como la edad.","h2":"En Missouri, un niño de menos de 40 libras, sin importar su edad, debe viajar en un sistema de retención infantil adecuado para él.","p":"Correcto. Menos de 40 libras significa asiento infantil."},"ref":{"doc":"MO","page":55}},{"id":"mo-170","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, a child is 5 years old, weighs 50 pounds and is 4 feet tall. What must the child use?","o":["A shoulder belt behind the back","A child safety seat or a booster seat","Only the vehicle's seat belt","No restraint is required"],"h1":"Children ages 4 to 7 who are small still need extra help from the seat.","h2":"In Missouri, children ages 4 through 7 who weigh 40 to 79 pounds and are under 4 feet 9 inches must ride in a child restraint or booster seat.","p":"Right. A child seat or booster seat."},"es":{"q":"En Missouri, un niño tiene 5 años, pesa 50 libras y mide 4 pies. ¿Qué debe usar?","o":["Un cinturón de hombro detrás de la espalda","Un asiento infantil o un asiento elevado","Solo el cinturón del vehículo","No se exige ningún sistema"],"h1":"Los niños de 4 a 7 años pequeños todavía necesitan ayuda extra del asiento.","h2":"En Missouri, los niños de 4 a 7 años que pesan de 40 a 79 libras y miden menos de 4 pies 9 pulgadas deben ir en un asiento infantil o en un asiento elevado.","p":"Correcto. Asiento infantil o asiento elevado."},"ref":{"doc":"MO","page":56}},{"id":"mo-171","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, a child is taller than 4 feet 9 inches. How may the child be secured?","o":["Only in a rear-facing car seat","Only in a five-point harness seat","No restraint is needed at all","With a seat belt or a booster seat"],"h1":"At this height, a regular belt can fit.","h2":"In Missouri, a child who is at least 8 years old, at least 80 pounds, or taller than 4 feet 9 inches must be secured by a vehicle safety belt or a booster seat.","p":"Right. A safety belt or booster seat."},"es":{"q":"En Missouri, un niño mide más de 4 pies 9 pulgadas. ¿Cómo puede ir asegurado?","o":["Solo en un asiento mirando hacia atrás","Solo en un asiento con arnés de cinco puntos","No necesita ningún sistema","Con cinturón o asiento elevado"],"h1":"Con esta estatura, el cinturón normal puede quedar bien.","h2":"En Missouri, un niño de al menos 8 años, de al menos 80 libras o de más de 4 pies 9 pulgadas debe ir asegurado con el cinturón del vehículo o con un asiento elevado.","p":"Correcto. Cinturón de seguridad o asiento elevado."},"ref":{"doc":"MO","page":56}},{"id":"mo-172","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, the Driver Guide repeats a federal safety tip about air bags. How far from the steering wheel should your breastbone be?","o":["At least 5 inches","At least 3 feet","At least 10 inches","At least 2 inches"],"h1":"It is about the length of a pencil and a half.","h2":"In Missouri, the Driver Guide recommends sitting with at least ten inches between the center of your breastbone and the center of the steering wheel.","p":"Right. At least 10 inches."},"es":{"q":"En Missouri, la guía repite un consejo federal sobre las bolsas de aire. ¿A qué distancia del volante debe estar su esternón?","o":["Al menos 5 pulgadas","Al menos 3 pies","Al menos 10 pulgadas","Al menos 2 pulgadas"],"h1":"Es más o menos el largo de un lápiz y medio.","h2":"En Missouri, la guía recomienda sentarse con al menos diez pulgadas entre el centro del esternón y el centro del volante.","p":"Correcto. Al menos 10 pulgadas."},"ref":{"doc":"MO","page":55}},{"id":"mo-173","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, where does the Driver Guide say to place your hands on the steering wheel?","o":["Left at 7 to 9, right at 3 to 5 o'clock","Both hands together at the top, at 12 o'clock","One hand at the bottom, at 6 o'clock","Left hand at 10, right hand on the gear shift"],"h1":"Hold the wheel low on both sides.","h2":"In Missouri, the Driver Guide says to put your left hand between the seven and nine o'clock positions and your right hand between the three and five o'clock positions.","p":"Right. 7 to 9 and 3 to 5."},"es":{"q":"En Missouri, ¿dónde dice la guía que debe poner las manos en el volante?","o":["Izquierda de 7 a 9, derecha de 3 a 5","Las dos manos juntas arriba, a las 12","Una sola mano abajo, a las 6","La izquierda a las 10 y la derecha en la palanca"],"h1":"Sujete el volante abajo, de los dos lados.","h2":"En Missouri, la guía dice que ponga la mano izquierda entre las posiciones de las siete y las nueve, y la derecha entre las tres y las cinco.","p":"Correcto. De 7 a 9 y de 3 a 5."},"ref":{"doc":"MO","page":56}},{"id":"mo-174","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, why should you never turn the ignition key to \"lock\" while the car is moving?","o":["The steering wheel can lock up","The engine will speed up on its own","The air bags may open by themselves","The brakes will grab harder than normal"],"h1":"Think of what the lock position does to the steering.","h2":"In Missouri, the Driver Guide warns never to turn the key to the \"lock\" position while moving, because the steering wheel will lock when you try to turn it and you will lose control.","p":"Right. The steering wheel would lock."},"es":{"q":"En Missouri, ¿por qué nunca debe girar la llave a \"lock\" mientras el auto se mueve?","o":["El volante se puede bloquear","El motor acelera por sí solo","Las bolsas de aire pueden abrirse solas","Los frenos frenan más fuerte de lo normal"],"h1":"Piense en lo que hace la posición de bloqueo al volante.","h2":"En Missouri, la guía advierte que nunca gire la llave a \"lock\" en movimiento, porque el volante se bloquea al tratar de girarlo y usted pierde el control.","p":"Correcto. El volante se bloquearía."},"ref":{"doc":"MO","page":57}},{"id":"mo-175","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, what rule does the Driver Guide give for a safe following distance in normal conditions?","o":["The one-second rule","One car length for each 20 mph","The ten-second rule","The three-second rule"],"h1":"Count \"one-thousand one\" and on, after the car ahead passes a sign.","h2":"In Missouri, the Driver Guide uses the three-second rule: if you reach a fixed object before counting to three after the car ahead passes it, you are too close.","p":"Right. Three seconds."},"es":{"q":"En Missouri, ¿qué regla da la guía para una distancia de seguimiento segura en condiciones normales?","o":["La regla de un segundo","Un auto de distancia por cada 20 mph","La regla de los diez segundos","La regla de los tres segundos"],"h1":"Cuente \"mil uno\" y así, después de que el auto de adelante pase una señal.","h2":"En Missouri, la guía usa la regla de los tres segundos: si llega a un objeto fijo antes de contar hasta tres después de que el auto de adelante lo pasa, va demasiado cerca.","p":"Correcto. Tres segundos."},"ref":{"doc":"MO","page":57}},{"id":"mo-176","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, during which months do most deer-vehicle crashes happen?","o":["Mostly in July and early August","January, May, and October to December","June through August, in summer","February through April, in spring"],"h1":"Think of fall and early winter, plus two other months.","h2":"In Missouri, most deer-related crashes happen in January, May, and October through December, with the highest risk from sunset to midnight and around sunrise.","p":"Right. January, May, and October to December."},"es":{"q":"En Missouri, ¿en qué meses ocurren la mayoría de los choques con venados?","o":["Sobre todo en julio y a inicios de agosto","Enero, mayo y de octubre a diciembre","De junio a agosto, en verano","De febrero a abril, en primavera"],"h1":"Piense en el otoño y el inicio del invierno, más otros dos meses.","h2":"En Missouri, la mayoría de los choques con venados ocurren en enero, mayo y de octubre a diciembre, con mayor riesgo desde el atardecer hasta la medianoche y cerca del amanecer.","p":"Correcto. Enero, mayo y de octubre a diciembre."},"ref":{"doc":"MO","page":59}},{"id":"mo-177","scope":"MO","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Missouri, a police officer stops you at night. What does the Driver Guide suggest you do once you have stopped?","o":["Search for your papers right away","Turn off all your lights","Turn on your interior lights","Get out and walk to the police car"],"h1":"Help the officer see inside your car.","h2":"In Missouri, if you are stopped at night, turn on your interior lights to help the officer see inside, keep your hands on the wheel, and wait for instructions.","p":"Right. Turn on the interior lights."},"es":{"q":"En Missouri, un policía lo detiene de noche. ¿Qué sugiere la guía hacer una vez que se detuvo?","o":["Buscar sus papeles de inmediato","Apagar todas sus luces","Encender las luces interiores","Bajarse y caminar a la patrulla"],"h1":"Ayude al policía a ver dentro de su auto.","h2":"En Missouri, si lo detienen de noche, encienda las luces interiores para que el policía vea adentro, mantenga las manos en el volante y espere instrucciones.","p":"Correcto. Encienda las luces interiores."},"ref":{"doc":"MO","page":61}},{"id":"mo-178","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, during what hours should your headlights be on at night?","o":["30 minutes after sunset to 30 minutes before sunrise","From exactly sunset until exactly sunrise","From 8 p.m. to 6 a.m., all year long","Only on roads that have no streetlights"],"h1":"The rule adds a half hour on each side of darkness.","h2":"In Missouri, turn your headlights on from one half hour after sunset until one half hour before sunrise.","p":"Right. Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Missouri, ¿en qué horario deben estar encendidos sus faros de noche?","o":["De 30 minutos tras el atardecer a 30 antes del amanecer","Exactamente del atardecer al amanecer","De 8 p.m. a 6 a.m., todo el año","Solo en vías que no tienen alumbrado"],"h1":"La regla agrega media hora a cada lado de la oscuridad.","h2":"En Missouri, encienda los faros desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. De media hora después del atardecer a media hora antes del amanecer."},"ref":{"doc":"MO","page":62}},{"id":"mo-179","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, above what speed can hydroplaning happen on wet pavement?","o":["15 mph","35 mph","55 mph","70 mph"],"h1":"It can happen well below highway speeds.","h2":"In Missouri, the Driver Guide says hydroplaning can happen at any speed over 35 mph, and in a severe rainstorm the tires can lose all contact with the road at 55 mph.","p":"Right. Over 35 mph."},"es":{"q":"En Missouri, ¿a partir de qué velocidad puede ocurrir el hidroplaneo en pavimento mojado?","o":["15 mph","35 mph","55 mph","70 mph"],"h1":"Puede pasar muy por debajo de la velocidad de carretera.","h2":"En Missouri, la guía dice que el hidroplaneo puede ocurrir a cualquier velocidad mayor de 35 mph, y en una tormenta fuerte las llantas pueden perder todo contacto con el camino a 55 mph.","p":"Correcto. A más de 35 mph."},"ref":{"doc":"MO","page":63}},{"id":"mo-180","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, your accelerator pedal gets stuck. What is the first step the Driver Guide lists?","o":["Turn off the ignition right away","Pump the gas pedal","Steer onto the shoulder at full speed","Shift to neutral"],"h1":"Take the engine's power away from the wheels.","h2":"In Missouri, if your accelerator sticks, shift to neutral, apply the brakes, look for a way out, and turn off the ignition only after you have stopped.","p":"Right. Shift to neutral first."},"es":{"q":"En Missouri, el pedal del acelerador se queda pegado. ¿Cuál es el primer paso que da la guía?","o":["Apagar el motor de inmediato","Bombear el acelerador","Salir al acotamiento a toda velocidad","Poner la transmisión en neutral"],"h1":"Quite la fuerza del motor a las ruedas.","h2":"En Missouri, si el acelerador se pega, ponga neutral, frene, busque una salida y apague el motor solo después de detenerse.","p":"Correcto. Primero neutral."},"ref":{"doc":"MO","page":65}},{"id":"mo-181","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, a driver who was drinking injures someone in a crash. How much jail time can this bring?","o":["Twenty years or more","Two to seven years","Up to 10 days","Up to six months"],"h1":"It is measured in years, not days or months.","h2":"In Missouri, if you injure or kill someone while driving after drinking or using drugs, you may spend two to seven years in jail, pay a $5,000 fine, and lose your license for five years.","p":"Right. Two to seven years."},"es":{"q":"En Missouri, un conductor que había tomado alcohol lastima a alguien en un choque. ¿Cuánto tiempo de cárcel puede recibir?","o":["Veinte años o más","De dos a siete años","Hasta 10 días","Hasta seis meses"],"h1":"Se mide en años, no en días ni meses.","h2":"En Missouri, si lastima o mata a alguien manejando después de tomar alcohol o usar drogas, puede pasar de dos a siete años en la cárcel, pagar una multa de $5,000 y perder la licencia por cinco años.","p":"Correcto. De dos a siete años."},"ref":{"doc":"MO","page":67}},{"id":"mo-182","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, a driver is convicted of DWI a second time within 5 years. What happens to the license?","o":["A 90-day suspension","Only points, no loss of license","A five-year license denial","A 30-day suspension"],"h1":"A repeat conviction is much more serious than the first.","h2":"In Missouri, a second DWI or BAC conviction within five years brings a five-year license denial.","p":"Right. Five-year denial."},"es":{"q":"En Missouri, un conductor es condenado por manejar intoxicado (DWI) por segunda vez en 5 años. ¿Qué pasa con su licencia?","o":["Una suspensión de 90 días","Solo puntos, sin perder la licencia","Se le niega la licencia por cinco años","Una suspensión de 30 días"],"h1":"Una segunda condena es mucho más grave que la primera.","h2":"En Missouri, una segunda condena por DWI o por nivel de alcohol en 5 años trae una negación de la licencia por cinco años.","p":"Correcto. Negación por cinco años."},"ref":{"doc":"MO","page":68}},{"id":"mo-183","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how long is the license denial after a third DWI conviction?","o":["One year","Two years","Five years","Ten years"],"h1":"It is twice as long as after the second conviction.","h2":"In Missouri, a third or later DWI or BAC conviction brings a ten-year license denial.","p":"Right. Ten years."},"es":{"q":"En Missouri, ¿cuánto dura la negación de la licencia después de una tercera condena por DWI?","o":["Un año","Dos años","Cinco años","Diez años"],"h1":"Es el doble que después de la segunda condena.","h2":"En Missouri, una tercera condena o más por DWI o por nivel de alcohol trae una negación de la licencia por diez años.","p":"Correcto. Diez años."},"ref":{"doc":"MO","page":68}},{"id":"mo-184","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, a 19-year-old is convicted of minor in possession of alcohol for the first time. How long is the license suspended?","o":["30 days","90 days","1 year","5 years"],"h1":"The first offense is the shortest of the three steps.","h2":"In Missouri, a first minor in possession offense brings a 30-day suspension, a second 90 days, and a third a one-year revocation.","p":"Right. 30 days for a first offense."},"es":{"q":"En Missouri, un joven de 19 años es condenado por primera vez por posesión de alcohol siendo menor. ¿Cuánto dura la suspensión de su licencia?","o":["30 días","90 días","1 año","5 años"],"h1":"La primera vez es la más corta de los tres pasos.","h2":"En Missouri, una primera infracción de menor en posesión de alcohol trae una suspensión de 30 días, la segunda de 90 días y la tercera una revocación de un año.","p":"Correcto. 30 días la primera vez."},"ref":{"doc":"MO","page":69}},{"id":"mo-185","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, at what blood alcohol level on an alcohol conviction must you have an ignition interlock device to get your license back?","o":["0.02% or higher","0.04% or higher","0.15% or higher","0.30% or higher"],"h1":"It is almost twice the adult legal limit.","h2":"In Missouri, you must install an ignition interlock device before reinstatement if you had an alcohol conviction with a BAC of .15% or higher, more than one intoxication-related contact, or caused damage or injury.","p":"Right. 0.15% or higher."},"es":{"q":"En Missouri, ¿con qué nivel de alcohol en una condena debe tener un dispositivo de bloqueo de encendido (interlock) para recuperar su licencia?","o":["0.02% o más","0.04% o más","0.15% o más","0.30% o más"],"h1":"Es casi el doble del límite legal para adultos.","h2":"En Missouri, debe instalar un dispositivo de bloqueo de encendido antes del restablecimiento si tuvo una condena por alcohol con 0.15% o más, más de un incidente relacionado con intoxicación, o causó daños o lesiones.","p":"Correcto. 0.15% o más."},"ref":{"doc":"MO","page":70}},{"id":"mo-186","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, what is the blood alcohol limit for commercial vehicle drivers?","o":["0.02%","0.04%","0.08%","0.10%"],"h1":"It is half the limit for other adult drivers.","h2":"In Missouri, it is illegal to drive a commercial vehicle with a blood alcohol content of 0.04% or more.","p":"Right. 0.04% for commercial drivers."},"es":{"q":"En Missouri, ¿cuál es el límite de alcohol en la sangre para conductores de vehículos comerciales?","o":["0.02%","0.04%","0.08%","0.10%"],"h1":"Es la mitad del límite para los demás conductores adultos.","h2":"En Missouri, es ilegal manejar un vehículo comercial con un nivel de alcohol en la sangre de 0.04% o más.","p":"Correcto. 0.04% para conductores comerciales."},"ref":{"doc":"MO","page":71}},{"id":"mo-187","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, can you be charged with DWI for driving while impaired by a cold medicine you bought at a store?","o":["Only if you also drank alcohol","Yes, any drug that impairs you counts","No, only alcohol counts","No, store medicines are always safe"],"h1":"The law looks at impairment, not where the drug came from.","h2":"In Missouri, you can be charged with DWI for driving while impaired by alcohol, illegal drugs, prescription or over-the-counter medicine, and the penalties are the same.","p":"Right. Any impairing drug can lead to DWI."},"es":{"q":"En Missouri, ¿pueden acusarlo de DWI por manejar afectado por un medicamento para el resfriado comprado en una tienda?","o":["Solo si también tomó alcohol","Sí, cuenta cualquier droga que lo afecte","No, solo cuenta el alcohol","No, los medicamentos de tienda siempre son seguros"],"h1":"La ley mira si está afectado, no de dónde viene la droga.","h2":"En Missouri, lo pueden acusar de DWI por manejar afectado por alcohol, drogas ilegales o medicamentos con o sin receta, y las penas son las mismas.","p":"Correcto. Cualquier droga que lo afecte puede llevar a un DWI."},"ref":{"doc":"MO","page":71}},{"id":"mo-188","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, how many points does a state speeding conviction add to your record?","o":["1 point","3 points","6 points","12 points"],"h1":"The Driver Guide's table gives a small number, less than careless driving.","h2":"In Missouri, the Driver Guide lists 3 points for a state speeding conviction.","p":"Right. 3 points for speeding."},"es":{"q":"En Missouri, ¿cuántos puntos agrega a su historial una condena estatal por exceso de velocidad?","o":["1 punto","3 puntos","6 puntos","12 puntos"],"h1":"La tabla de la guía da un número pequeño, menor que manejar con descuido.","h2":"En Missouri, la guía indica 3 puntos por una condena estatal por exceso de velocidad.","p":"Correcto. 3 puntos por exceso de velocidad."},"ref":{"doc":"MO","page":73}},{"id":"mo-189","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, how many points are added for driving with a suspended or revoked license?","o":["3 points","4 points","8 points","12 points"],"h1":"It is the highest value in the table.","h2":"In Missouri, operating a vehicle with a suspended or revoked license adds 12 points to your record.","p":"Right. 12 points."},"es":{"q":"En Missouri, ¿cuántos puntos se agregan por manejar con la licencia suspendida o revocada?","o":["3 puntos","4 puntos","8 puntos","12 puntos"],"h1":"Es el valor más alto de la tabla.","h2":"En Missouri, manejar un vehículo con la licencia suspendida o revocada agrega 12 puntos a su historial.","p":"Correcto. 12 puntos."},"ref":{"doc":"MO","page":73}},{"id":"mo-190","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, your license is suspended for the first time for having 8 points in 18 months. How long does it last?","o":["30 days","60 days","90 days","1 year"],"h1":"Each later suspension is longer than the first.","h2":"In Missouri, a first point suspension lasts 30 days, a second 60 days, and a third or later 90 days.","p":"Right. 30 days the first time."},"es":{"q":"En Missouri, le suspenden la licencia por primera vez por tener 8 puntos en 18 meses. ¿Cuánto dura?","o":["30 días","60 días","90 días","1 año"],"h1":"Cada suspensión siguiente dura más que la primera.","h2":"En Missouri, la primera suspensión por puntos dura 30 días, la segunda 60 días y la tercera o más 90 días.","p":"Correcto. 30 días la primera vez."},"ref":{"doc":"MO","page":73}},{"id":"mo-191","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, how many points within 24 months lead to a one-year revocation?","o":["8 points","12 points","18 points","24 points"],"h1":"It is more than 12, over a longer time.","h2":"In Missouri, your license is revoked for one year if you get 12 or more points in 12 months, 18 or more in 24 months, or 24 or more in 36 months.","p":"Right. 18 points in 24 months."},"es":{"q":"En Missouri, ¿cuántos puntos en 24 meses llevan a una revocación de un año?","o":["8 puntos","12 puntos","18 puntos","24 puntos"],"h1":"Son más de 12, en un tiempo más largo.","h2":"En Missouri, la licencia se revoca por un año si acumula 12 puntos o más en 12 meses, 18 o más en 24 meses, o 24 o más en 36 meses.","p":"Correcto. 18 puntos en 24 meses."},"ref":{"doc":"MO","page":73}},{"id":"mo-192","scope":"MO","cat":"licensing","sign":null,"c":0,"en":{"q":"In Missouri, your driving privilege is reinstated after a point suspension. What happens to your point total?","o":["It is reduced to four points","It goes down to zero","It stays exactly the same","It is cut in half"],"h1":"You do not start completely clean.","h2":"In Missouri, when your driving privilege is reinstated, the Department reduces your total points to four, and they keep dropping each year you drive without new points.","p":"Right. Your points go down to four."},"es":{"q":"En Missouri, le restablecen el privilegio de manejar después de una suspensión por puntos. ¿Qué pasa con su total de puntos?","o":["Se reduce a cuatro puntos","Queda en cero","Sigue igual","Se reduce a la mitad"],"h1":"No empieza totalmente limpio.","h2":"En Missouri, cuando le restablecen el privilegio de manejar, el Departamento reduce su total a cuatro puntos, y siguen bajando cada año que maneja sin puntos nuevos.","p":"Correcto. Sus puntos bajan a cuatro."},"ref":{"doc":"MO","page":74}},{"id":"mo-193","scope":"MO","cat":"licensing","sign":null,"c":1,"en":{"q":"In Missouri, you just bought a car. How long do you have to apply for the title before you pay a penalty?","o":["10 days","30 days","60 days","90 days"],"h1":"It is about one month.","h2":"In Missouri, you must apply for a title within 30 days of buying a vehicle, or you will have to pay a penalty fee.","p":"Right. 30 days."},"es":{"q":"En Missouri, usted acaba de comprar un auto. ¿Cuánto tiempo tiene para solicitar el título antes de pagar una multa?","o":["10 días","30 días","60 días","90 días"],"h1":"Es más o menos un mes.","h2":"En Missouri, debe solicitar el título dentro de 30 días de comprar un vehículo, o tendrá que pagar un recargo.","p":"Correcto. 30 días."},"ref":{"doc":"MO","page":75}},{"id":"mo-194","scope":"MO","cat":"licensing","sign":null,"c":2,"en":{"q":"In Missouri, your license and plates are suspended a second time for no insurance, within two years of the first. What happens?","o":["A warning letter in the mail","One year and a $400 fee","90 days, $200, and 3 years of proof","Only a $20 fee and nothing more"],"h1":"The second time costs more than the first, but less than the third.","h2":"In Missouri, a second insurance suspension within two years means a 90-day suspension, a $200 fee, and filing proof of insurance for three years.","p":"Right. 90 days and $200."},"es":{"q":"En Missouri, le suspenden la licencia y las placas por segunda vez por no tener seguro, dentro de dos años de la primera. ¿Qué pasa?","o":["Una carta de advertencia por correo","Un año y un cargo de $400","90 días, cargo de $200 y 3 años de prueba","Solo un cargo de $20 y nada más"],"h1":"La segunda vez cuesta más que la primera, pero menos que la tercera.","h2":"En Missouri, una segunda suspensión por falta de seguro dentro de dos años significa 90 días de suspensión, un cargo de $200 y presentar prueba de seguro por tres años.","p":"Correcto. 90 días y $200."},"ref":{"doc":"MO","page":80}},{"id":"mo-195","scope":"MO","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Missouri, you scrape a parked car and no one is around. What should you do?","o":["Leave only if the damage is small","Wait five minutes, then leave","Stay; leaving is a crime","Drive away, since no one saw it"],"h1":"A crash with a parked car is still a crash.","h2":"In Missouri, even if you hit a parked vehicle, do not leave; leaving the scene of a traffic crash is a crime.","p":"Right. Do not leave the scene."},"es":{"q":"En Missouri, usted raya un auto estacionado y no hay nadie cerca. ¿Qué debe hacer?","o":["Irse solo si el daño es pequeño","Esperar cinco minutos y luego irse","Quedarse; irse es un delito","Irse, porque nadie lo vio"],"h1":"Un choque con un auto estacionado sigue siendo un choque.","h2":"En Missouri, aunque choque con un vehículo estacionado, no se vaya; abandonar la escena de un choque de tránsito es un delito.","p":"Correcto. No abandone la escena."},"ref":{"doc":"MO","page":81}},{"id":"mo-196","scope":"MO","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Missouri, why does MoDOT ask drivers to \"steer it and clear it\" after a minor crash?","o":["Each blocked minute causes about 4 minutes of backup","Police will not come unless you move the car","Your insurance company requires it","So you can leave without sharing information"],"h1":"A blocked lane causes long backups and more crashes.","h2":"In Missouri, after a minor crash with no injuries you should move your car off the road, because every minute a lane is blocked backs up traffic for about four minutes.","p":"Right. One blocked minute means about four minutes of backup."},"es":{"q":"En Missouri, ¿por qué MoDOT pide a los conductores \"steer it and clear it\" (muévalo y despeje) después de un choque leve?","o":["Cada minuto bloqueado causa unos 4 minutos de atasco","La policía no viene si no mueve el auto","Su compañía de seguros lo exige","Para poder irse sin intercambiar datos"],"h1":"Un carril bloqueado causa largas filas y más choques.","h2":"En Missouri, después de un choque leve sin heridos debe sacar su auto de la vía, porque cada minuto que un carril está bloqueado atasca el tráfico unos cuatro minutos.","p":"Correcto. Un minuto bloqueado son unos cuatro minutos de atasco."},"ref":{"doc":"MO","page":81}},{"id":"mo-197","scope":"MO","cat":"licensing","sign":null,"c":3,"en":{"q":"In Missouri, which vehicles do not need a safety inspection?","o":["All vehicles more than 5 years old","Every pickup truck, of any age","Vehicles with out-of-state titles only","Newer than 10 model years, under 150,000 miles"],"h1":"Newer cars with lower mileage are exempt.","h2":"In Missouri, motor vehicles are exempt from safety inspection for the first ten years after their model year, as long as they have fewer than 150,000 miles.","p":"Right. First 10 years and under 150,000 miles."},"es":{"q":"En Missouri, ¿qué vehículos no necesitan inspección de seguridad?","o":["Todos los de más de 5 años de antigüedad","Todas las camionetas pickup, de cualquier año","Solo los que tienen título de otro estado","Con menos de 10 años de modelo y 150,000 millas"],"h1":"Los autos más nuevos y con menos millas están exentos.","h2":"En Missouri, los vehículos están exentos de la inspección de seguridad durante los primeros diez años después de su año de modelo, mientras tengan menos de 150,000 millas.","p":"Correcto. Primeros 10 años y menos de 150,000 millas."},"ref":{"doc":"MO","page":83}},{"id":"mo-198","scope":"MO","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Missouri, which of these is allowed while your car is moving?","o":["Recording a video for social media","Sending a text by voice-to-text","Typing a text with your thumbs","Holding the phone to read a message"],"h1":"The law allows features that keep your hands free.","h2":"In Missouri, drivers may send or receive texts by voice-to-text and use hands-free calls and GPS, but may not hold the phone, type or read texts, or record or watch video.","p":"Right. Voice-to-text is allowed."},"es":{"q":"En Missouri, ¿cuál de estas acciones está permitida mientras su auto está en movimiento?","o":["Grabar un video para redes sociales","Enviar un mensaje con dictado por voz","Escribir un mensaje con los pulgares","Sostener el teléfono para leer un mensaje"],"h1":"La ley permite las funciones que dejan las manos libres.","h2":"En Missouri, los conductores pueden enviar o recibir mensajes con dictado por voz y usar llamadas con manos libres y GPS, pero no pueden sostener el teléfono, escribir o leer mensajes, ni grabar o ver videos.","p":"Correcto. El dictado por voz está permitido."},"ref":{"doc":"MO","page":93}},{"id":"mo-199","scope":"MO","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Missouri, you are stopped in traffic with the car still rolling slowly. May you watch a video on your phone mounted on the dashboard?","o":["Yes, if the phone is mounted","Yes, under 10 mph","Yes, if the sound is off","No, not while the car moves"],"h1":"The law bans video while the vehicle is in motion, even hands-free.","h2":"In Missouri, while the vehicle is in motion, drivers may not watch a video or movie, or record, post or broadcast video, even if the phone is mounted.","p":"Right. No watching video while moving."},"es":{"q":"En Missouri, usted está en tráfico y el auto aún avanza despacio. ¿Puede ver un video en el teléfono montado en el tablero?","o":["Sí, si el teléfono está montado","Sí, a menos de 10 mph","Sí, si no tiene sonido","No, no con el auto en movimiento"],"h1":"La ley prohíbe el video con el vehículo en movimiento, aun con manos libres.","h2":"En Missouri, con el vehículo en movimiento los conductores no pueden ver videos ni películas, ni grabar, publicar o transmitir video, aunque el teléfono esté montado.","p":"Correcto. No se ven videos en movimiento."},"ref":{"doc":"MO","page":93}},{"id":"mo-200","scope":"MO","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Missouri, what kind of offense is breaking the move over law for stopped emergency vehicles?","o":["A Class A misdemeanor","No offense, only advice","A small parking fine","A felony on the first offense"],"h1":"It is a crime, not just a ticket.","h2":"In Missouri, violating the move over law for stationary emergency vehicles and vehicles with amber lights is a Class A misdemeanor.","p":"Right. It is a Class A misdemeanor."},"es":{"q":"En Missouri, ¿qué tipo de infracción es no cumplir la ley de moverse de carril (move over) ante vehículos de emergencia detenidos?","o":["Un delito menor Clase A","Ninguna, es solo un consejo","Una multa pequeña de estacionamiento","Un delito grave desde la primera vez"],"h1":"Es un delito, no solo una multa.","h2":"En Missouri, no cumplir la ley de moverse de carril ante vehículos de emergencia detenidos y vehículos con luces ámbar es un delito menor Clase A.","p":"Correcto. Es un delito menor Clase A."},"ref":{"doc":"MO","page":98}},{"id":"ms-001","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, what is the youngest age to get a regular learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a regular driver's license.","h2":"In Mississippi, you can get a regular learner's permit at 15, one year before you can get a regular driver's license at 16.","p":"Right. The regular learner's permit starts at age 15."},"es":{"q":"En Mississippi, ¿cuál es la edad mínima para obtener un permiso de aprendiz regular?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia de conducir regular.","h2":"En Mississippi, usted puede obtener un permiso de aprendiz regular a los 15 años, un año antes de poder obtener la licencia de conducir regular a los 16.","p":"Correcto. El permiso de aprendiz regular empieza a los 15 años."},"zh":{"q":"在 Mississippi，最小几岁可以拿到普通学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比你可以拿普通驾照的时间早一年。","h2":"在 Mississippi，你 15 岁就可以拿到普通学习驾照，比 16 岁可以拿的普通驾照早一年。","p":"对。普通学习驾照从 15 岁开始。"},"vi":{"q":"Ở Mississippi, tuổi nhỏ nhất để được cấp giấy phép tập lái thông thường (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể được cấp bằng lái thông thường.","h2":"Ở Mississippi, bạn có thể được cấp giấy phép tập lái thông thường lúc 15 tuổi, một năm trước khi bạn có thể được cấp bằng lái thông thường lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái thông thường bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Mississippi, ano ang pinakabatang edad para makakuha ng regular na learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng regular na driver's license.","h2":"Sa Mississippi, puwede kang makakuha ng regular na learner's permit sa edad na 15, isang taon bago ka makakuha ng regular na driver's license sa edad na 16.","p":"Tama. Nagsisimula ang regular na learner's permit sa edad na 15."},"ar":{"q":"في Mississippi، ما أصغر سن للحصول على تصريح تعلّم القيادة العادي (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل سنة واحدة من السن الذي يمكنك فيه الحصول على رخصة القيادة العادية.","h2":"في Mississippi، يمكنك الحصول على تصريح تعلّم القيادة العادي في سن 15، أي قبل سنة واحدة من حصولك على رخصة القيادة العادية في سن 16.","p":"صحيح. يبدأ تصريح تعلّم القيادة العادي في سن 15."},"ref":{"doc":"MS","page":13}},{"id":"ms-002","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a 14-year-old may get a learner's permit in one case. Which one?","o":["If a parent signs a special form","If the teen lives on a farm","If the teen passes the test with a perfect score","If the teen is enrolled in a certified driver education program"],"h1":"Think about a class that teaches driving.","h2":"Mississippi allows a learner's permit at 14 only for a teen who is enrolled in a certified driver education program.","p":"Right. At 14, the permit requires enrollment in certified driver education."},"es":{"q":"En Mississippi, un joven de 14 años puede obtener un permiso de aprendiz en un solo caso. ¿Cuál es?","o":["Si un padre firma un formulario especial","Si el joven vive en una granja","Si el joven aprueba el examen sin errores","Si el joven está inscrito en un programa certificado de educación vial"],"h1":"Piense en una clase que enseña a manejar.","h2":"Mississippi permite el permiso de aprendiz a los 14 años solo a un joven inscrito en un programa certificado de educación vial.","p":"Correcto. A los 14 años, el permiso exige estar inscrito en educación vial certificada."},"zh":{"q":"在 Mississippi，14 岁的人在一种情况下可以拿到学习驾照。是哪一种？","o":["如果父母签一份特别表格","如果青少年住在农场","如果青少年考试得满分","如果青少年报名参加了有认证的驾驶教育课程"],"h1":"想一想教开车的课。","h2":"Mississippi 只允许报名参加了有认证的驾驶教育课程的青少年在 14 岁拿学习驾照。","p":"对。14 岁拿学习驾照，必须报名参加有认证的驾驶教育。"},"vi":{"q":"Ở Mississippi, thiếu niên 14 tuổi có thể được cấp giấy phép tập lái trong một trường hợp. Đó là trường hợp nào?","o":["Nếu cha mẹ ký một mẫu đơn đặc biệt","Nếu thiếu niên sống ở nông trại","Nếu thiếu niên đậu bài thi với điểm tuyệt đối","Nếu thiếu niên đang ghi danh vào một chương trình giáo dục lái xe được chứng nhận (driver education)"],"h1":"Hãy nghĩ đến một lớp học dạy lái xe.","h2":"Mississippi chỉ cho phép cấp giấy phép tập lái lúc 14 tuổi cho thiếu niên đang ghi danh vào một chương trình giáo dục lái xe được chứng nhận.","p":"Đúng. Lúc 14 tuổi, giấy phép đòi hỏi phải ghi danh học giáo dục lái xe được chứng nhận."},"tl":{"q":"Sa Mississippi, puwedeng makakuha ng learner's permit ang isang 14 taong gulang sa isang kaso lang. Alin ito?","o":["Kung pipirma ang magulang sa isang espesyal na form","Kung nakatira ang kabataan sa bukid","Kung pumasa ang kabataan sa test nang perpekto ang iskor","Kung naka-enroll ang kabataan sa isang sertipikadong programa ng driver education"],"h1":"Isipin ang isang klase na nagtuturo ng pagmamaneho.","h2":"Pinapayagan ng Mississippi ang learner's permit sa edad na 14 para lang sa kabataang naka-enroll sa isang sertipikadong programa ng driver education.","p":"Tama. Sa edad na 14, kailangang naka-enroll sa sertipikadong driver education para sa permit."},"ar":{"q":"في Mississippi، يمكن لشخص عمره 14 سنة أن يحصل على تصريح تعلّم القيادة في حالة واحدة. ما هي؟","o":["إذا وقّع أحد الوالدين على نموذج خاص","إذا كان المراهق يعيش في مزرعة","إذا نجح المراهق في الاختبار بالدرجة الكاملة","إذا كان المراهق مسجلًا في برنامج معتمد لتعليم القيادة (driver education)"],"h1":"فكّر في صف دراسي يعلّم القيادة.","h2":"تسمح Mississippi بتصريح تعلّم القيادة في سن 14 فقط للمراهق المسجل في برنامج معتمد لتعليم القيادة.","p":"صحيح. في سن 14، يتطلب التصريح التسجيل في برنامج معتمد لتعليم القيادة."},"ref":{"doc":"MS","page":null}},{"id":"ms-004","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, who must sit beside a driver with a learner's permit?","o":["Any passenger who is 16 or older","A licensed driver who is at least 18","A licensed driver who is at least 21","A licensed driver who is at least 25"],"h1":"The helper must be an adult old enough to buy alcohol legally.","h2":"In Mississippi, a learner's permit holder must drive with a licensed adult who is at least 21 years old sitting in the front seat.","p":"Right. A licensed driver 21 or older sits in the front seat."},"es":{"q":"En Mississippi, ¿quién debe sentarse al lado de un conductor con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años","Un conductor con licencia de por lo menos 25 años"],"h1":"El acompañante debe ser un adulto con edad suficiente para comprar alcohol legalmente.","h2":"En Mississippi, quien tiene permiso de aprendiz debe manejar con un adulto con licencia de por lo menos 21 años sentado en el asiento delantero.","p":"Correcto. Un conductor con licencia de 21 años o más va en el asiento delantero."},"zh":{"q":"在 Mississippi，谁必须坐在持学习驾照的司机旁边？","o":["任何 16 岁或以上的乘客","至少 18 岁、有驾照的司机","至少 21 岁、有驾照的司机","至少 25 岁、有驾照的司机"],"h1":"陪同的人必须是年龄够大、可以合法买酒的成年人。","h2":"在 Mississippi，持学习驾照的人开车时，必须有一位至少 21 岁、有驾照的成年人坐在前排。","p":"对。21 岁或以上、有驾照的司机坐在前排。"},"vi":{"q":"Ở Mississippi, ai phải ngồi bên cạnh người lái có giấy phép tập lái?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Một người có bằng lái ít nhất 18 tuổi","Một người có bằng lái ít nhất 21 tuổi","Một người có bằng lái ít nhất 25 tuổi"],"h1":"Người hướng dẫn phải là người lớn đủ tuổi để mua rượu hợp pháp.","h2":"Ở Mississippi, người có giấy phép tập lái phải lái xe cùng một người lớn có bằng lái, ít nhất 21 tuổi, ngồi ở ghế trước.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước."},"tl":{"q":"Sa Mississippi, sino ang dapat umupo sa tabi ng driver na may learner's permit?","o":["Kahit sinong pasahero na 16 taong gulang pataas","Isang driver na may lisensya at hindi bababa sa 18 taong gulang","Isang driver na may lisensya at hindi bababa sa 21 taong gulang","Isang driver na may lisensya at hindi bababa sa 25 taong gulang"],"h1":"Dapat ay adult ang tagatulong na nasa sapat na edad para legal na bumili ng alak.","h2":"Sa Mississippi, ang may learner's permit ay dapat magmaneho kasama ang isang adult na may lisensya, hindi bababa sa 21 taong gulang, na nakaupo sa harap.","p":"Tama. Isang driver na may lisensya at 21 taong gulang pataas ang nakaupo sa harap."},"ar":{"q":"في Mississippi، من يجب أن يجلس بجانب السائق الذي يحمل تصريح تعلّم القيادة؟","o":["أي راكب عمره 16 سنة أو أكثر","سائق يحمل رخصة وعمره 18 سنة على الأقل","سائق يحمل رخصة وعمره 21 سنة على الأقل","سائق يحمل رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا بلغ السن القانونية لشراء الكحول.","h2":"في Mississippi، يجب على حامل تصريح تعلّم القيادة أن يقود مع شخص بالغ يحمل رخصة وعمره 21 سنة على الأقل، ويجلس في المقعد الأمامي.","p":"صحيح. يجلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر."},"ref":{"doc":"MS","page":13}},{"id":"ms-005","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a teen has held a learner's permit for one year. What is the youngest age to get a regular driver's license?","o":["15 years old","16 years old","17 years old","18 years old"],"h1":"The permit starts at 15 and must be held for one year.","h2":"In Mississippi, you can get a regular driver's license at 16 if you have held a learner's permit for one year.","p":"Right. With a permit held for one year, you can get a regular license at 16."},"es":{"q":"En Mississippi, un joven ha tenido un permiso de aprendiz por un año. ¿Cuál es la edad mínima para obtener una licencia de conducir regular?","o":["15 años","16 años","17 años","18 años"],"h1":"El permiso empieza a los 15 años y se debe tener por un año.","h2":"En Mississippi, usted puede obtener una licencia de conducir regular a los 16 años si ha tenido un permiso de aprendiz por un año.","p":"Correcto. Con el permiso por un año, puede obtener la licencia regular a los 16."},"zh":{"q":"在 Mississippi，一个青少年已经持有学习驾照一年。最小几岁可以拿到普通驾照？","o":["15 岁","16 岁","17 岁","18 岁"],"h1":"学习驾照从 15 岁开始，而且必须持有一年。","h2":"在 Mississippi，如果你已经持有学习驾照一年，你 16 岁就可以拿到普通驾照。","p":"对。持有学习驾照一年后，你 16 岁就可以拿普通驾照。"},"vi":{"q":"Ở Mississippi, một thiếu niên đã có giấy phép tập lái được một năm. Tuổi nhỏ nhất để được cấp bằng lái thông thường là bao nhiêu?","o":["15 tuổi","16 tuổi","17 tuổi","18 tuổi"],"h1":"Giấy phép tập lái bắt đầu từ 15 tuổi và phải giữ trong một năm.","h2":"Ở Mississippi, bạn có thể được cấp bằng lái thông thường lúc 16 tuổi nếu bạn đã có giấy phép tập lái được một năm.","p":"Đúng. Khi đã giữ giấy phép tập lái một năm, bạn có thể được cấp bằng lái thông thường lúc 16 tuổi."},"tl":{"q":"Sa Mississippi, may learner's permit na ang isang kabataan nang isang taon. Ano ang pinakabatang edad para makakuha ng regular na driver's license?","o":["15 taong gulang","16 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Nagsisimula ang permit sa edad na 15 at dapat itong hawakan nang isang taon.","h2":"Sa Mississippi, puwede kang makakuha ng regular na driver's license sa edad na 16 kung may learner's permit ka na nang isang taon.","p":"Tama. Kapag may permit ka na nang isang taon, puwede kang makakuha ng regular na lisensya sa edad na 16."},"ar":{"q":"في Mississippi، يحمل مراهق تصريح تعلّم القيادة منذ سنة واحدة. ما أصغر سن للحصول على رخصة القيادة العادية؟","o":["15 سنة","16 سنة","17 سنة","18 سنة"],"h1":"يبدأ التصريح في سن 15 ويجب حمله لمدة سنة واحدة.","h2":"في Mississippi، يمكنك الحصول على رخصة القيادة العادية في سن 16 إذا كنت قد حملت تصريح تعلّم القيادة لمدة سنة واحدة.","p":"صحيح. بعد حمل التصريح لمدة سنة واحدة، يمكنك الحصول على رخصة عادية في سن 16."},"ref":{"doc":"MS","page":15}},{"id":"ms-006","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 15-year-old gets a learner's permit. How long must the teen hold it before getting a regular driver's license?","o":["Three months","Six months","One year","Two years"],"h1":"Think of a full trip around the calendar.","h2":"In Mississippi, you must hold a learner's permit for one year before you can get a regular driver's license, unless you turn 17 first.","p":"Right. You must hold the permit for one year."},"es":{"q":"En Mississippi, un joven de 15 años obtiene un permiso de aprendiz. ¿Cuánto tiempo debe tenerlo antes de obtener una licencia de conducir regular?","o":["Tres meses","Seis meses","Un año","Dos años"],"h1":"Piense en una vuelta completa al calendario.","h2":"En Mississippi, usted debe tener el permiso de aprendiz por un año antes de obtener una licencia de conducir regular, a menos que cumpla 17 años antes.","p":"Correcto. Debe tener el permiso por un año."},"zh":{"q":"在 Mississippi，一个 15 岁的青少年拿到了学习驾照。在拿普通驾照之前，他必须持有学习驾照多久？","o":["三个月","六个月","一年","两年"],"h1":"想一想日历走完整整一圈。","h2":"在 Mississippi，你必须持有学习驾照一年，才可以拿普通驾照，除非你先满 17 岁。","p":"对。你必须持有学习驾照一年。"},"vi":{"q":"Ở Mississippi, một thiếu niên 15 tuổi được cấp giấy phép tập lái. Thiếu niên đó phải giữ giấy phép bao lâu trước khi được cấp bằng lái thông thường?","o":["Ba tháng","Sáu tháng","Một năm","Hai năm"],"h1":"Hãy nghĩ đến một vòng trọn vẹn của lịch.","h2":"Ở Mississippi, bạn phải giữ giấy phép tập lái một năm trước khi được cấp bằng lái thông thường, trừ khi bạn đủ 17 tuổi trước.","p":"Đúng. Bạn phải giữ giấy phép tập lái một năm."},"tl":{"q":"Sa Mississippi, nakakuha ng learner's permit ang isang 15 taong gulang. Gaano katagal dapat itong hawakan ng kabataan bago makakuha ng regular na driver's license?","o":["Tatlong buwan","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Isipin ang isang buong ikot ng kalendaryo.","h2":"Sa Mississippi, dapat mong hawakan ang learner's permit nang isang taon bago ka makakuha ng regular na driver's license, maliban kung mag-17 ka muna.","p":"Tama. Dapat mong hawakan ang permit nang isang taon."},"ar":{"q":"في Mississippi، حصل مراهق عمره 15 سنة على تصريح تعلّم القيادة. كم يجب أن يحمله قبل الحصول على رخصة القيادة العادية؟","o":["ثلاثة أشهر","ستة أشهر","سنة واحدة","سنتان"],"h1":"فكّر في دورة كاملة للتقويم.","h2":"في Mississippi، يجب أن تحمل تصريح تعلّم القيادة لمدة سنة واحدة قبل أن تحصل على رخصة القيادة العادية، إلا إذا بلغت 17 سنة قبل ذلك.","p":"صحيح. يجب أن تحمل التصريح لمدة سنة واحدة."},"ref":{"doc":"MS","page":13}},{"id":"ms-007","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 16-year-old applies for a regular driver's license. How many hours of driving must a parent, teacher or guardian sign that they watched?","o":["10 hours","25 hours","50 hours","100 hours"],"h1":"It is half of one hundred.","h2":"In Mississippi, a driver under 17 needs a signed statement from a parent, teacher or guardian who watched at least 50 hours of driving.","p":"Right. An adult must sign for at least 50 hours of driving."},"es":{"q":"En Mississippi, un joven de 16 años solicita una licencia de conducir regular. ¿Cuántas horas de manejo debe firmar un padre, maestro o tutor que vio?","o":["10 horas","25 horas","50 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Mississippi, un conductor menor de 17 años necesita una declaración firmada por un padre, maestro o tutor que vio por lo menos 50 horas de manejo.","p":"Correcto. Un adulto debe firmar por lo menos 50 horas de manejo."},"zh":{"q":"在 Mississippi，一个 16 岁的人申请普通驾照。父母、老师或监护人必须签字证明看过他开车多少小时？","o":["10 小时","25 小时","50 小时","100 小时"],"h1":"这是一百的一半。","h2":"在 Mississippi，未满 17 岁的司机需要一份由父母、老师或监护人签字的声明，证明他们看过至少 50 小时的驾驶。","p":"对。一个成年人必须签字证明至少 50 小时的驾驶。"},"vi":{"q":"Ở Mississippi, một thiếu niên 16 tuổi nộp đơn xin bằng lái thông thường. Cha mẹ, giáo viên hoặc người giám hộ phải ký xác nhận đã theo dõi bao nhiêu giờ lái xe?","o":["10 giờ","25 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Mississippi, tài xế dưới 17 tuổi cần một bản xác nhận có chữ ký của cha mẹ, giáo viên hoặc người giám hộ đã theo dõi ít nhất 50 giờ lái xe.","p":"Đúng. Một người lớn phải ký xác nhận ít nhất 50 giờ lái xe."},"tl":{"q":"Sa Mississippi, nag-apply ng regular na driver's license ang isang 16 taong gulang. Ilang oras ng pagmamaneho ang dapat pirmahan ng magulang, guro o guardian na nakita nila?","o":["10 oras","25 oras","50 oras","100 oras"],"h1":"Ito ay kalahati ng isang daan.","h2":"Sa Mississippi, ang driver na wala pang 17 ay kailangan ng pinirmahang pahayag mula sa magulang, guro o guardian na nakakita ng hindi bababa sa 50 oras ng pagmamaneho.","p":"Tama. Dapat pumirma ang isang adult para sa hindi bababa sa 50 oras ng pagmamaneho."},"ar":{"q":"في Mississippi، يتقدّم شخص عمره 16 سنة للحصول على رخصة القيادة العادية. كم ساعة من القيادة يجب أن يوقّع أحد الوالدين أو المعلم أو الوصي أنه شاهدها؟","o":["10 ساعات","25 ساعة","50 ساعة","100 ساعة"],"h1":"إنها نصف المئة.","h2":"في Mississippi، يحتاج السائق الذي عمره أقل من 17 سنة إلى إقرار موقّع من أحد الوالدين أو المعلم أو الوصي الذي شاهد 50 ساعة على الأقل من القيادة.","p":"صحيح. يجب أن يوقّع شخص بالغ على 50 ساعة على الأقل من القيادة."},"ref":{"doc":"MS","page":15}},{"id":"ms-008","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, which drivers are banned from texting while driving?","o":["Only drivers with a learner's permit","Only drivers under 18","Drivers of every age","Only drivers of school buses"],"h1":"This rule does not depend on age or license type.","h2":"Mississippi bans all drivers from writing, sending or reading text messages while driving.","p":"Right. No driver of any age may text while driving in Mississippi."},"es":{"q":"En Mississippi, ¿a qué conductores se les prohíbe enviar mensajes de texto mientras manejan?","o":["Solo a quienes tienen permiso de aprendiz","Solo a los menores de 18 años","A los conductores de todas las edades","Solo a los choferes de autobús escolar"],"h1":"Esta regla no depende de la edad ni del tipo de licencia.","h2":"Mississippi prohíbe a todos los conductores escribir, enviar o leer mensajes de texto mientras manejan.","p":"Correcto. Ningún conductor, de ninguna edad, puede enviar mensajes mientras maneja en Mississippi."},"zh":{"q":"在 Mississippi，哪些司机开车时禁止发短信？","o":["只有持学习驾照的司机","只有 18 岁以下的司机","所有年龄的司机","只有校车司机"],"h1":"这条规定和年龄或驾照种类无关。","h2":"Mississippi 禁止所有司机在开车时写、发送或阅读短信。","p":"对。在 Mississippi，任何年龄的司机开车时都不能发短信。"},"vi":{"q":"Ở Mississippi, những người lái xe nào bị cấm nhắn tin khi đang lái xe?","o":["Chỉ người có giấy phép tập lái","Chỉ người lái dưới 18 tuổi","Người lái ở mọi lứa tuổi","Chỉ người lái xe buýt trường học"],"h1":"Quy định này không phụ thuộc vào tuổi hay loại bằng lái.","h2":"Mississippi cấm tất cả người lái xe viết, gửi hoặc đọc tin nhắn khi đang lái xe.","p":"Đúng. Ở Mississippi, không người lái nào, ở bất kỳ tuổi nào, được nhắn tin khi lái xe."},"tl":{"q":"Sa Mississippi, aling mga driver ang bawal mag-text habang nagmamaneho?","o":["Ang mga may learner's permit lang","Ang mga driver na wala pang 18 taong gulang lang","Mga driver sa lahat ng edad","Ang mga driver ng school bus lang"],"h1":"Hindi nakadepende ang patakarang ito sa edad o uri ng lisensya.","h2":"Ipinagbabawal ng Mississippi sa lahat ng driver ang pagsulat, pagpapadala o pagbabasa ng text message habang nagmamaneho.","p":"Tama. Walang driver sa anumang edad ang puwedeng mag-text habang nagmamaneho sa Mississippi."},"ar":{"q":"في Mississippi، أي السائقين ممنوعون من كتابة الرسائل النصية أثناء القيادة؟","o":["حاملو تصريح تعلّم القيادة فقط","السائقون الذين أعمارهم أقل من 18 سنة فقط","السائقون من جميع الأعمار","سائقو الحافلات المدرسية فقط"],"h1":"هذه القاعدة لا تعتمد على العمر أو نوع الرخصة.","h2":"تمنع Mississippi جميع السائقين من كتابة الرسائل النصية أو إرسالها أو قراءتها أثناء القيادة.","p":"صحيح. لا يجوز لأي سائق من أي عمر أن يكتب رسائل نصية أثناء القيادة في Mississippi."},"ref":{"doc":"MS","page":23}},{"id":"ms-009","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which of these does the texting law still allow while driving?","o":["Reading a social media post","Using a hands-free or voice-operated device","Sending a short email","Typing a text at a slow speed"],"h1":"Think about using your voice instead of your hands.","h2":"Mississippi's texting law does not apply to hands-free or voice-operated devices, so a driver may still use them while driving.","p":"Right. Hands-free and voice-operated devices are still allowed."},"es":{"q":"En Mississippi, ¿cuál de estas cosas todavía permite la ley de mensajes de texto mientras se maneja?","o":["Leer una publicación en redes sociales","Usar un dispositivo de manos libres o de voz","Enviar un correo corto","Escribir un mensaje despacio"],"h1":"Piense en usar la voz en lugar de las manos.","h2":"La ley de mensajes de texto de Mississippi no se aplica a los dispositivos de manos libres o de voz, así que el conductor todavía puede usarlos mientras maneja.","p":"Correcto. Los dispositivos de manos libres y de voz todavía están permitidos."},"zh":{"q":"在 Mississippi，短信法仍然允许开车时做下面哪一件事？","o":["看社交媒体上的帖子","使用免提或声控设备","发一封短的电子邮件","慢速行驶时打短信"],"h1":"想一想用声音代替用手。","h2":"Mississippi 的短信法不适用于免提或声控设备，所以司机开车时仍然可以使用它们。","p":"对。免提和声控设备仍然可以用。"},"vi":{"q":"Ở Mississippi, luật về nhắn tin vẫn cho phép điều nào sau đây khi đang lái xe?","o":["Đọc một bài đăng trên mạng xã hội","Dùng thiết bị rảnh tay hoặc điều khiển bằng giọng nói","Gửi một email ngắn","Gõ tin nhắn khi chạy chậm"],"h1":"Hãy nghĩ đến việc dùng giọng nói thay vì dùng tay.","h2":"Luật về nhắn tin của Mississippi không áp dụng cho thiết bị rảnh tay hoặc điều khiển bằng giọng nói, nên người lái vẫn có thể dùng chúng khi lái xe.","p":"Đúng. Thiết bị rảnh tay và điều khiển bằng giọng nói vẫn được phép."},"tl":{"q":"Sa Mississippi, alin dito ang pinapayagan pa rin ng batas sa pag-text habang nagmamaneho?","o":["Pagbasa ng post sa social media","Paggamit ng hands-free o voice-operated na device","Pagpapadala ng maikling email","Pag-type ng text habang mabagal ang takbo"],"h1":"Isipin ang paggamit ng boses sa halip na mga kamay.","h2":"Hindi sakop ng batas sa pag-text ng Mississippi ang mga hands-free o voice-operated na device, kaya puwede pa rin itong gamitin ng driver habang nagmamaneho.","p":"Tama. Pinapayagan pa rin ang mga hands-free at voice-operated na device."},"ar":{"q":"في Mississippi، أي من هذه الأمور لا يزال قانون الرسائل النصية يسمح بها أثناء القيادة؟","o":["قراءة منشور على وسائل التواصل الاجتماعي","استخدام جهاز بدون يدين (hands-free) أو جهاز يعمل بالصوت","إرسال بريد إلكتروني قصير","كتابة رسالة نصية أثناء السير ببطء"],"h1":"فكّر في استخدام صوتك بدلًا من يديك.","h2":"قانون الرسائل النصية في Mississippi لا ينطبق على الأجهزة التي تعمل بدون يدين أو بالصوت، لذلك يجوز للسائق أن يستخدمها أثناء القيادة.","p":"صحيح. الأجهزة التي تعمل بدون يدين أو بالصوت لا تزال مسموحة."},"ref":{"doc":"MS","page":23}},{"id":"ms-010","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, what blood alcohol level is illegal for a driver under 21?","o":["0.02 percent or higher","0.05 percent or higher","0.08 percent or higher","0.10 percent or higher"],"h1":"It is much lower than the limit for adults.","h2":"Under Mississippi's zero tolerance law, a driver under 21 with a blood alcohol level of 0.02 percent or higher breaks the law.","p":"Right. For drivers under 21, the limit is 0.02 percent."},"es":{"q":"En Mississippi, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"Según la ley de tolerancia cero de Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 por ciento o más viola la ley.","p":"Correcto. Para los menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Mississippi，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.02% 或更高","0.05% 或更高","0.08% 或更高","0.10% 或更高"],"h1":"它比成年人的限值低很多。","h2":"根据 Mississippi 的零容忍法，21 岁以下的司机血液酒精浓度达到 0.02% 或更高，就违法。","p":"对。21 岁以下的司机，限值是 0.02%。"},"vi":{"q":"Ở Mississippi, nồng độ cồn trong máu bao nhiêu là bất hợp pháp đối với người lái dưới 21 tuổi?","o":["0.02 phần trăm trở lên","0.05 phần trăm trở lên","0.08 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Theo luật không khoan nhượng (zero tolerance) của Mississippi, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên là vi phạm luật.","p":"Đúng. Với người lái dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Mississippi, anong antas ng alak sa dugo ang ilegal para sa driver na wala pang 21 taong gulang?","o":["0.02 porsiyento o higit pa","0.05 porsiyento o higit pa","0.08 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa mga adult.","h2":"Sa ilalim ng zero tolerance law ng Mississippi, lumalabag sa batas ang driver na wala pang 21 taong gulang na may antas ng alak sa dugo na 0.02 porsiyento o higit pa.","p":"Tama. Para sa mga driver na wala pang 21, ang limitasyon ay 0.02 porsiyento."},"ar":{"q":"في Mississippi، ما نسبة الكحول في الدم التي تكون غير قانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"بموجب قانون عدم التسامح (zero tolerance) في Mississippi، يخالف القانون السائق الذي عمره أقل من 21 سنة إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين الذين أعمارهم أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"MS","page":78}},{"id":"ms-011","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a driver under 21 has a blood alcohol level of 0.08 percent. How is the driver treated?","o":["Only a warning is given","As a minor under the 0.02 rule only","Under the same DUI penalties as adults","Only the parents are fined"],"h1":"At this level, age no longer gives a lighter charge.","h2":"In Mississippi, a driver under 21 with a blood alcohol level of 0.08 percent or higher faces the adult DUI penalties.","p":"Right. At 0.08 percent, a driver under 21 is treated like an adult."},"es":{"q":"En Mississippi, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.08 por ciento. ¿Cómo se le trata?","o":["Solo recibe una advertencia","Solo como menor bajo la regla de 0.02","Con las mismas penas por DUI que los adultos","Solo se multa a los padres"],"h1":"A este nivel, la edad ya no da un cargo más leve.","h2":"En Mississippi, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.08 por ciento o más recibe las penas de DUI para adultos.","p":"Correcto. Con 0.08 por ciento, el menor de 21 recibe el mismo trato que un adulto."},"zh":{"q":"在 Mississippi，一位 21 岁以下的司机血液酒精浓度是 0.08%。这位司机会被怎样处理？","o":["只给警告","只按未成年人的 0.02 规定处理","按和成年人一样的 DUI 处罚","只罚父母的款"],"h1":"到了这个浓度，年龄不会再让罪名变轻。","h2":"在 Mississippi，21 岁以下的司机血液酒精浓度达到 0.08% 或更高，会受到成年人的 DUI 处罚。","p":"对。到了 0.08%，21 岁以下的司机会被当作成年人处理。"},"vi":{"q":"Ở Mississippi, một người lái dưới 21 tuổi có nồng độ cồn trong máu là 0.08 phần trăm. Người lái này bị xử lý như thế nào?","o":["Chỉ bị cảnh cáo","Chỉ như người vị thành niên theo quy định 0.02","Chịu cùng mức phạt DUI như người lớn","Chỉ cha mẹ bị phạt tiền"],"h1":"Ở mức này, tuổi tác không còn giúp được xử nhẹ hơn.","h2":"Ở Mississippi, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.08 phần trăm trở lên sẽ chịu các mức phạt DUI dành cho người lớn.","p":"Đúng. Ở mức 0.08 phần trăm, người lái dưới 21 tuổi bị xử lý như người lớn."},"tl":{"q":"Sa Mississippi, may 0.08 porsiyentong antas ng alak sa dugo ang isang driver na wala pang 21 taong gulang. Paano siya ituturing?","o":["Babala lang ang ibibigay","Bilang menor de edad sa ilalim lang ng 0.02 na patakaran","Sa ilalim ng parehong parusa sa DUI gaya ng mga adult","Ang mga magulang lang ang pagmumultahin"],"h1":"Sa antas na ito, hindi na nagbibigay ng mas magaan na kaso ang edad.","h2":"Sa Mississippi, haharap sa mga parusa sa DUI para sa adult ang driver na wala pang 21 taong gulang na may antas ng alak sa dugo na 0.08 porsiyento o higit pa.","p":"Tama. Sa 0.08 porsiyento, itinuturing na parang adult ang driver na wala pang 21."},"ar":{"q":"في Mississippi، سائق عمره أقل من 21 سنة نسبة الكحول في دمه 0.08 بالمئة. كيف يُعامل هذا السائق؟","o":["يُعطى إنذارًا فقط","كقاصر بموجب قاعدة 0.02 فقط","بنفس عقوبات القيادة تحت تأثير الكحول (DUI) المطبقة على البالغين","يُغرَّم الوالدان فقط"],"h1":"عند هذا المستوى، لم يعد العمر يعطي تهمة أخف.","h2":"في Mississippi، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.08 بالمئة أو أكثر يواجه عقوبات DUI الخاصة بالبالغين.","p":"صحيح. عند 0.08 بالمئة، يُعامل السائق الذي عمره أقل من 21 سنة مثل البالغ."},"ref":{"doc":"MS","page":79}},{"id":"ms-012","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, what is the highest speed limit on interstate highways?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"It is 5 mph above the limit on four-lane state and U.S. highways.","h2":"The highest speed limit on Mississippi interstates is 70 mph, day and night.","p":"Right. Mississippi interstates top out at 70 mph."},"es":{"q":"En Mississippi, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"Es 5 mph más que el límite de las carreteras estatales y federales de cuatro carriles.","h2":"El límite de velocidad más alto en las interestatales de Mississippi es 70 mph, de día y de noche.","p":"Correcto. En las interestatales de Mississippi, el máximo es 70 mph."},"zh":{"q":"在 Mississippi，州际公路的最高限速是多少？","o":["60 英里/小时","65 英里/小时","75 英里/小时","70 英里/小时"],"h1":"它比四车道的州公路和联邦公路（U.S. highway）的限速高 5 英里/小时。","h2":"Mississippi 州际公路的最高限速是 70 英里/小时，白天晚上都一样。","p":"对。Mississippi 州际公路最高 70 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"Mức này cao hơn 5 mph so với giới hạn trên xa lộ tiểu bang và xa lộ U.S. có bốn làn xe.","h2":"Tốc độ tối đa cao nhất trên các xa lộ liên bang ở Mississippi là 70 mph, cả ngày lẫn đêm.","p":"Đúng. Xa lộ liên bang ở Mississippi có tốc độ tối đa là 70 mph."},"tl":{"q":"Sa Mississippi, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"5 mph itong mas mataas kaysa sa limitasyon sa mga four-lane na state at U.S. highway.","h2":"Ang pinakamataas na speed limit sa mga interstate ng Mississippi ay 70 mph, araw man o gabi.","p":"Tama. Hanggang 70 mph ang mga interstate ng Mississippi."},"ar":{"q":"في Mississippi، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["60 mph","65 mph","75 mph","70 mph"],"h1":"إنه أعلى بـ5 mph من الحد على طرق الولاية والطرق الأمريكية (U.S.) ذات الأربعة مسارات.","h2":"أعلى حد للسرعة على الطرق السريعة بين الولايات في Mississippi هو 70 mph، نهارًا وليلًا.","p":"صحيح. أعلى سرعة على الطرق السريعة بين الولايات في Mississippi هي 70 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-013","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the usual maximum speed on a four-lane state or U.S. highway, unless signs show a different limit?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"It is 10 mph more than on a two-lane highway.","h2":"In Mississippi, the usual maximum speed on a four-lane state or U.S. highway is 65 mph.","p":"Right. Four-lane state and U.S. highways usually have a 65 mph limit."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles, si las señales no indican otra?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Es 10 mph más que en una carretera de dos carriles.","h2":"En Mississippi, la velocidad máxima habitual en una carretera estatal o federal de cuatro carriles es 65 mph.","p":"Correcto. Las carreteras estatales y federales de cuatro carriles suelen tener un límite de 65 mph."},"zh":{"q":"在 Mississippi，除非标志显示不同的限速，四车道的州公路或联邦公路（U.S. highway）通常的最高速度是多少？","o":["55 英里/小时","65 英里/小时","70 英里/小时","75 英里/小时"],"h1":"它比双车道公路高 10 英里/小时。","h2":"在 Mississippi，四车道的州公路或联邦公路通常的最高速度是 65 英里/小时。","p":"对。四车道的州公路和联邦公路通常限速 65 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc xa lộ U.S. có bốn làn xe là bao nhiêu, trừ khi biển báo ghi giới hạn khác?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Mức này cao hơn 10 mph so với xa lộ có hai làn xe.","h2":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc xa lộ U.S. có bốn làn xe là 65 mph.","p":"Đúng. Xa lộ tiểu bang và xa lộ U.S. có bốn làn xe thường có giới hạn 65 mph."},"tl":{"q":"Sa Mississippi, ano ang karaniwang pinakamabilis na takbo sa four-lane na state o U.S. highway, maliban kung iba ang limitasyong ipinapakita ng mga karatula?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"10 mph itong mas mataas kaysa sa two-lane na highway.","h2":"Sa Mississippi, ang karaniwang pinakamabilis na takbo sa four-lane na state o U.S. highway ay 65 mph.","p":"Tama. Karaniwang 65 mph ang limitasyon sa mga four-lane na state at U.S. highway."},"ar":{"q":"في Mississippi، ما السرعة القصوى المعتادة على طريق ولاية أو طريق أمريكي (U.S.) ذي أربعة مسارات، إلا إذا أظهرت اللافتات حدًا مختلفًا؟","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"إنها أعلى بـ10 mph من الطريق ذي المسارين.","h2":"في Mississippi، السرعة القصوى المعتادة على طريق ولاية أو طريق أمريكي ذي أربعة مسارات هي 65 mph.","p":"صحيح. طرق الولاية والطرق الأمريكية ذات الأربعة مسارات حدها المعتاد 65 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-015","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, you cannot safely change lanes away from a stopped emergency vehicle with flashing lights. What must you do?","o":["Keep your speed and stay in your lane","Stop completely in your lane","Drive onto the shoulder on the other side","Slow down and be ready to stop"],"h1":"If you cannot add distance, reduce your speed.","h2":"Under Mississippi's move-over law, if you cannot change lanes safely, you must slow to a safe speed and be prepared to stop.","p":"Right. When you cannot move over, slow down and be ready to stop."},"es":{"q":"En Mississippi, usted no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer?","o":["Mantener la velocidad y seguir en su carril","Detenerse por completo en su carril","Pasar por el acotamiento del otro lado","Reducir la velocidad y estar listo para detenerse"],"h1":"Si no puede alejarse, reduzca la velocidad.","h2":"Según la ley de Mississippi, si usted no puede cambiarse de carril con seguridad, debe reducir a una velocidad segura y estar listo para detenerse.","p":"Correcto. Si no puede moverse de carril, reduzca la velocidad y esté listo para detenerse."},"zh":{"q":"在 Mississippi，你没办法安全地换道，离开一辆停着、闪着灯的急救车辆。你必须怎么做？","o":["保持速度，留在你的车道","在你的车道里完全停车","开到另一边的路肩上","减速，并准备好停车"],"h1":"如果你不能拉开距离，就降低速度。","h2":"根据 Mississippi 的 move-over 法，如果你不能安全换道，就必须减速到安全的速度，并准备好停车。","p":"对。不能让出车道时，就减速并准备停车。"},"vi":{"q":"Ở Mississippi, bạn không thể chuyển làn một cách an toàn để tránh xa một xe cấp cứu đang dừng có đèn nhấp nháy. Bạn phải làm gì?","o":["Giữ nguyên tốc độ và ở lại trong làn của bạn","Dừng hẳn trong làn của bạn","Lái lên lề đường ở phía bên kia","Giảm tốc độ và sẵn sàng dừng lại"],"h1":"Nếu bạn không thể tạo thêm khoảng cách, hãy giảm tốc độ.","h2":"Theo luật nhường làn của Mississippi, nếu bạn không thể chuyển làn an toàn, bạn phải giảm xuống tốc độ an toàn và sẵn sàng dừng lại.","p":"Đúng. Khi không thể nhường làn, hãy giảm tốc độ và sẵn sàng dừng lại."},"tl":{"q":"Sa Mississippi, hindi ka ligtas na makalipat ng lane palayo sa isang nakahintong emergency vehicle na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at manatili sa iyong lane","Huminto nang tuluyan sa iyong lane","Magmaneho papunta sa shoulder sa kabilang panig","Bagalan ang takbo at maging handang huminto"],"h1":"Kung hindi ka makalayo, bawasan ang bilis mo.","h2":"Sa ilalim ng move-over law ng Mississippi, kung hindi ka ligtas na makalipat ng lane, dapat kang bumagal sa ligtas na bilis at maging handang huminto.","p":"Tama. Kapag hindi ka makalipat, bumagal at maging handang huminto."},"ar":{"q":"في Mississippi، لا يمكنك تغيير المسار بأمان للابتعاد عن مركبة طوارئ متوقفة ذات أضواء وامضة. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك وابقَ في مسارك","توقف تمامًا في مسارك","اذهب إلى كتف الطريق على الجانب الآخر","خفّف سرعتك وكن مستعدًا للتوقف"],"h1":"إذا لم تستطع زيادة المسافة، فخفّف سرعتك.","h2":"بموجب قانون الابتعاد في Mississippi، إذا لم تستطع تغيير المسار بأمان، يجب أن تخفّف سرعتك إلى سرعة آمنة وتكون مستعدًا للتوقف.","p":"صحيح. عندما لا تستطيع الابتعاد، خفّف سرعتك وكن مستعدًا للتوقف."},"ref":{"doc":"MS","page":67}},{"id":"ms-017","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, how far from a stopped school bus must you stop when it is loading or unloading children?","o":["At least 5 feet","At least 10 feet","At least 30 feet","At least 50 feet"],"h1":"It is about the length of one small car.","h2":"Mississippi law requires you to stop at least 10 feet from a school bus that is stopped to pick up or drop off children.","p":"Right. You stop at least 10 feet from the bus."},"es":{"q":"En Mississippi, ¿a qué distancia de un autobús escolar detenido debe detenerse cuando suben o bajan niños?","o":["Por lo menos 5 pies","Por lo menos 10 pies","Por lo menos 30 pies","Por lo menos 50 pies"],"h1":"Es más o menos el largo de un carro pequeño.","h2":"La ley de Mississippi exige que usted se detenga por lo menos a 10 pies de un autobús escolar detenido para recoger o dejar niños.","p":"Correcto. Usted se detiene por lo menos a 10 pies del autobús."},"zh":{"q":"在 Mississippi，校车停下来让孩子上下车时，你必须在离校车多远的地方停车？","o":["至少 5 英尺","至少 10 英尺","至少 30 英尺","至少 50 英尺"],"h1":"大约是一辆小汽车的长度。","h2":"Mississippi 法律要求你在离停下来接送孩子的校车至少 10 英尺的地方停车。","p":"对。你要在离校车至少 10 英尺的地方停车。"},"vi":{"q":"Ở Mississippi, bạn phải dừng cách xe buýt trường học đang dừng bao xa khi xe đang đón hoặc trả học sinh?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 30 feet","Ít nhất 50 feet"],"h1":"Khoảng cách này bằng chiều dài của một chiếc xe hơi nhỏ.","h2":"Luật Mississippi yêu cầu bạn dừng cách ít nhất 10 feet so với xe buýt trường học đang dừng để đón hoặc trả học sinh.","p":"Đúng. Bạn dừng cách xe buýt ít nhất 10 feet."},"tl":{"q":"Sa Mississippi, gaano kalayo ka dapat huminto mula sa nakahintong school bus kapag nagsasakay o nagbababa ito ng mga bata?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 30 feet","Hindi bababa sa 50 feet"],"h1":"Halos kasinghaba ito ng isang maliit na kotse.","h2":"Ayon sa batas ng Mississippi, dapat kang huminto nang hindi bababa sa 10 feet mula sa school bus na nakahinto para magsakay o magbaba ng mga bata.","p":"Tama. Huminto ka nang hindi bababa sa 10 feet mula sa bus."},"ar":{"q":"في Mississippi، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة عندما تُركب الأطفال أو تُنزلهم؟","o":["5 feet على الأقل","10 feet على الأقل","30 feet على الأقل","50 feet على الأقل"],"h1":"إنها تقريبًا طول سيارة صغيرة واحدة.","h2":"يُلزمك قانون Mississippi بالتوقف على بعد 10 feet على الأقل من الحافلة المدرسية المتوقفة لإركاب الأطفال أو إنزالهم.","p":"صحيح. تتوقف على بعد 10 feet على الأقل من الحافلة."},"ref":{"doc":"MS","page":58}},{"id":"ms-018","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, you are on a divided highway with two lanes in each direction. A school bus on the other side stops with its red lights flashing. What must you do?","o":["You may keep going with care","Stop until the bus moves","Stop, then pass at 10 mph","Move to the left lane and stop"],"h1":"A physical divider separates you from the children's side.","h2":"In Mississippi, on a divided highway with at least two lanes in each direction, drivers on the other side do not have to stop for a stopped school bus, but should still drive with care.","p":"Right. On a divided highway, the opposite side may keep going with care."},"es":{"q":"En Mississippi, usted va por una carretera dividida con dos carriles en cada sentido. Un autobús escolar del otro lado se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Puede seguir con cuidado","Detenerse hasta que el autobús avance","Detenerse y luego pasar a 10 mph","Pasarse al carril izquierdo y detenerse"],"h1":"Una división física lo separa del lado de los niños.","h2":"En Mississippi, en una carretera dividida con por lo menos dos carriles en cada sentido, los conductores del otro lado no tienen que detenerse ante un autobús escolar detenido, pero deben manejar con cuidado.","p":"Correcto. En una carretera dividida, el lado contrario puede seguir con cuidado."},"zh":{"q":"在 Mississippi，你在每个方向有两条车道的分隔公路上。另一边的一辆校车停下来，闪着红灯。你必须怎么做？","o":["你可以小心地继续开","停车，直到校车开走","停车，然后用 10 英里/小时开过去","换到左车道并停车"],"h1":"有一个实体隔离把你和孩子那一边分开。","h2":"在 Mississippi，在每个方向至少有两条车道的分隔公路上，另一边的司机不必为停着的校车停车，但仍然要小心开。","p":"对。在分隔公路上，对面的车可以小心地继续开。"},"vi":{"q":"Ở Mississippi, bạn đang ở trên xa lộ có dải phân cách với hai làn xe mỗi chiều. Một xe buýt trường học ở chiều bên kia dừng lại và bật đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Bạn có thể tiếp tục đi nhưng phải cẩn thận","Dừng lại cho đến khi xe buýt chạy","Dừng lại, rồi vượt qua với tốc độ 10 mph","Chuyển sang làn bên trái và dừng lại"],"h1":"Một dải phân cách tách bạn khỏi phía có trẻ em.","h2":"Ở Mississippi, trên xa lộ có dải phân cách với ít nhất hai làn xe mỗi chiều, người lái ở chiều bên kia không phải dừng lại cho xe buýt trường học đang dừng, nhưng vẫn phải lái xe cẩn thận.","p":"Đúng. Trên xa lộ có dải phân cách, xe ở chiều bên kia có thể tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Mississippi, nasa divided highway ka na may dalawang lane sa bawat direksyon. Huminto ang isang school bus sa kabilang panig at kumikislap ang pulang ilaw nito. Ano ang dapat mong gawin?","o":["Puwede kang magpatuloy nang maingat","Huminto hanggang umandar ang bus","Huminto, pagkatapos ay lumampas sa 10 mph","Lumipat sa kaliwang lane at huminto"],"h1":"May harang na naghihiwalay sa iyo mula sa panig ng mga bata.","h2":"Sa Mississippi, sa divided highway na may hindi bababa sa dalawang lane sa bawat direksyon, hindi kailangang huminto ng mga driver sa kabilang panig para sa nakahintong school bus, pero dapat pa rin silang magmaneho nang maingat.","p":"Tama. Sa divided highway, puwedeng magpatuloy nang maingat ang mga sasakyan sa kabilang panig."},"ar":{"q":"في Mississippi، أنت على طريق سريع مقسوم فيه مساران في كل اتجاه. حافلة مدرسية على الجانب الآخر تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["يجوز لك أن تستمر بحذر","توقف حتى تتحرك الحافلة","توقف، ثم تجاوزها بسرعة 10 mph","انتقل إلى المسار الأيسر وتوقف"],"h1":"هناك فاصل يفصلك عن جانب الأطفال.","h2":"في Mississippi، على الطريق السريع المقسوم الذي فيه مساران على الأقل في كل اتجاه، لا يلزم السائقين على الجانب الآخر أن يتوقفوا للحافلة المدرسية المتوقفة، لكن يجب عليهم أن يقودوا بحذر.","p":"صحيح. على الطريق المقسوم، يجوز لمن في الاتجاه المعاكس أن يستمروا بحذر."},"ref":{"doc":"MS","page":58}},{"id":"ms-019","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, a school bus stops on a divided highway with a median. You are driving behind it, in the same direction. What must you do?","o":["Pass it on the left with care","Pass it on the right shoulder","Slow to 15 mph and pass","Stop until it moves again"],"h1":"The median protects only the drivers on the other side.","h2":"In Mississippi, when a school bus stops on a divided highway, drivers going the same direction as the bus must stop.","p":"Right. Traffic behind the bus must always stop."},"es":{"q":"En Mississippi, un autobús escolar se detiene en una carretera dividida con una franja central. Usted va detrás, en el mismo sentido. ¿Qué debe hacer?","o":["Pasarlo por la izquierda con cuidado","Pasarlo por el acotamiento derecho","Reducir a 15 mph y pasar","Detenerse hasta que vuelva a avanzar"],"h1":"La franja central solo protege a los conductores del otro lado.","h2":"En Mississippi, cuando un autobús escolar se detiene en una carretera dividida, los conductores que van en el mismo sentido que el autobús deben detenerse.","p":"Correcto. El tráfico que va detrás del autobús siempre debe detenerse."},"zh":{"q":"在 Mississippi，一辆校车在有中央隔离带的分隔公路上停下。你在它后面，同方向行驶。你必须怎么做？","o":["小心地从左边超过去","从右边路肩超过去","减速到 15 英里/小时再超过去","停车，直到它再开动"],"h1":"中央隔离带只保护另一边的司机。","h2":"在 Mississippi，校车在分隔公路上停下时，和校车同方向的司机必须停车。","p":"对。校车后面的车一定要停。"},"vi":{"q":"Ở Mississippi, một xe buýt trường học dừng lại trên xa lộ có dải phân cách ở giữa. Bạn đang lái phía sau xe buýt, cùng chiều. Bạn phải làm gì?","o":["Vượt qua bên trái một cách cẩn thận","Vượt qua bằng lề đường bên phải","Giảm xuống 15 mph rồi vượt qua","Dừng lại cho đến khi xe buýt chạy tiếp"],"h1":"Dải phân cách chỉ bảo vệ người lái ở chiều bên kia.","h2":"Ở Mississippi, khi xe buýt trường học dừng trên xa lộ có dải phân cách, người lái đi cùng chiều với xe buýt phải dừng lại.","p":"Đúng. Xe phía sau xe buýt luôn phải dừng lại."},"tl":{"q":"Sa Mississippi, huminto ang isang school bus sa divided highway na may median. Nagmamaneho ka sa likod nito, sa parehong direksyon. Ano ang dapat mong gawin?","o":["Lampasan ito sa kaliwa nang maingat","Lampasan ito sa kanang shoulder","Bumagal sa 15 mph at lumampas","Huminto hanggang umandar itong muli"],"h1":"Ang median ay nagpoprotekta lang sa mga driver sa kabilang panig.","h2":"Sa Mississippi, kapag huminto ang school bus sa divided highway, dapat huminto ang mga driver na papunta sa parehong direksyon ng bus.","p":"Tama. Laging dapat huminto ang mga sasakyan sa likod ng bus."},"ar":{"q":"في Mississippi، تتوقف حافلة مدرسية على طريق سريع مقسوم فيه فاصل في الوسط. أنت تقود خلفها، في نفس الاتجاه. ماذا يجب أن تفعل؟","o":["تجاوزها من اليسار بحذر","تجاوزها من كتف الطريق الأيمن","خفّف سرعتك إلى 15 mph وتجاوزها","توقف حتى تتحرك مرة أخرى"],"h1":"الفاصل يحمي السائقين على الجانب الآخر فقط.","h2":"في Mississippi، عندما تتوقف حافلة مدرسية على طريق سريع مقسوم، يجب على السائقين الذين يسيرون في نفس اتجاه الحافلة أن يتوقفوا.","p":"صحيح. يجب على السيارات خلف الحافلة أن تتوقف دائمًا."},"ref":{"doc":"MS","page":58}},{"id":"ms-022","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Mississippi requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Mississippi minimum is 25, 50 and 25 thousand dollars."},"es":{"q":"En Mississippi, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"El primer número y el último son iguales.","h2":"Mississippi exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Mississippi es de 25, 50 y 25 mil dólares."},"zh":{"q":"在 Mississippi，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"第一个和最后一个数字一样。","h2":"Mississippi 要求一个人受伤至少 $25,000，一次车祸中的伤害至少 $50,000，财产损失至少 $25,000。","p":"对。Mississippi 的最低标准是 25、50 和 25 千美元。"},"vi":{"q":"Ở Mississippi, người lái xe phải có bảo hiểm trách nhiệm (liability insurance) tối thiểu là bao nhiêu?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Mississippi yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Mississippi là 25, 50 và 25 nghìn đô la."},"tl":{"q":"Sa Mississippi, ano ang pinakamababang liability insurance na dapat mayroon ang isang driver?","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Mississippi ang hindi bababa sa $25,000 para sa pagkasugat ng isang tao, $50,000 para sa mga pagkasugat sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Mississippi ay 25, 50 at 25 libong dolyar."},"ar":{"q":"في Mississippi، ما الحد الأدنى من تأمين المسؤولية (liability insurance) الذي يجب أن يكون لدى السائق؟","o":["$25,000 / $50,000 / $25,000","$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تشترط Mississippi ما لا يقل عن $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 للأضرار بالممتلكات.","p":"صحيح. الحد الأدنى في Mississippi هو 25 و50 و25 ألف دولار."},"ref":{"doc":"MS","page":76}},{"id":"ms-023","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, how long is a regular learner's permit valid?","o":["Six months","One year","Two years","Four years"],"h1":"It lasts longer than the one year you must hold it.","h2":"In Mississippi, a regular learner's permit is valid for two years.","p":"Right. The learner's permit is good for two years."},"es":{"q":"En Mississippi, ¿por cuánto tiempo es válido un permiso de aprendiz regular?","o":["Seis meses","Un año","Dos años","Cuatro años"],"h1":"Dura más que el año que usted debe tenerlo.","h2":"En Mississippi, el permiso de aprendiz regular es válido por dos años.","p":"Correcto. El permiso de aprendiz es válido por dos años."},"zh":{"q":"在 Mississippi，普通学习驾照（learner's permit）的有效期是多久？","o":["六个月","一年","两年","四年"],"h1":"它比你必须持有学习驾照的一年更长。","h2":"在 Mississippi，普通学习驾照的有效期是两年。","p":"对。学习驾照两年内有效。"},"vi":{"q":"Ở Mississippi, giấy phép tập lái thông thường (learner's permit) có giá trị trong bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Bốn năm"],"h1":"Thời hạn này dài hơn một năm mà bạn phải giữ giấy phép.","h2":"Ở Mississippi, giấy phép tập lái thông thường có giá trị trong hai năm.","p":"Đúng. Giấy phép tập lái có giá trị trong hai năm."},"tl":{"q":"Sa Mississippi, gaano katagal valid ang regular na learner's permit?","o":["Anim na buwan","Isang taon","Dalawang taon","Apat na taon"],"h1":"Mas matagal ito kaysa sa isang taon na dapat mong hawakan ito.","h2":"Sa Mississippi, valid ang regular na learner's permit nang dalawang taon.","p":"Tama. Valid ang learner's permit nang dalawang taon."},"ar":{"q":"في Mississippi، ما مدة صلاحية تصريح تعلّم القيادة العادي (learner's permit)؟","o":["ستة أشهر","سنة واحدة","سنتان","أربع سنوات"],"h1":"مدته أطول من السنة الواحدة التي يجب أن تحمله فيها.","h2":"في Mississippi، تصريح تعلّم القيادة العادي صالح لمدة سنتين.","p":"صحيح. تصريح تعلّم القيادة صالح لمدة سنتين."},"ref":{"doc":"MS","page":13}},{"id":"ms-024","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you move here with a license from another state. How soon must you get a Mississippi driver's license?","o":["Within 60 days","Within 10 days","Within 6 months","Within 1 year"],"h1":"You have about two months.","h2":"In Mississippi, a new resident must get a Mississippi driver's license within 60 days of moving here.","p":"Right. New residents have 60 days to get a Mississippi license."},"es":{"q":"En Mississippi, usted se muda aquí con una licencia de otro estado. ¿En cuánto tiempo debe obtener una licencia de conducir de Mississippi?","o":["En un plazo de 60 días","En un plazo de 10 días","En un plazo de 6 meses","En un plazo de 1 año"],"h1":"Tiene unos dos meses.","h2":"En Mississippi, un nuevo residente debe obtener una licencia de conducir de Mississippi dentro de los 60 días después de mudarse aquí.","p":"Correcto. Los nuevos residentes tienen 60 días para obtener una licencia de Mississippi."},"zh":{"q":"在 Mississippi，你搬来这里时有别的州的驾照。你必须在多长时间内拿到 Mississippi 驾照？","o":["60 天内","10 天内","6 个月内","1 年内"],"h1":"你大约有两个月。","h2":"在 Mississippi，新居民必须在搬来后 60 天内拿到 Mississippi 驾照。","p":"对。新居民有 60 天的时间拿 Mississippi 驾照。"},"vi":{"q":"Ở Mississippi, bạn chuyển đến đây với bằng lái của một tiểu bang khác. Bạn phải lấy bằng lái Mississippi trong thời gian bao lâu?","o":["Trong vòng 60 ngày","Trong vòng 10 ngày","Trong vòng 6 tháng","Trong vòng 1 năm"],"h1":"Bạn có khoảng hai tháng.","h2":"Ở Mississippi, cư dân mới phải lấy bằng lái Mississippi trong vòng 60 ngày sau khi chuyển đến đây.","p":"Đúng. Cư dân mới có 60 ngày để lấy bằng lái Mississippi."},"tl":{"q":"Sa Mississippi, lumipat ka rito na may lisensya mula sa ibang state. Gaano kabilis ka dapat kumuha ng Mississippi driver's license?","o":["Sa loob ng 60 araw","Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa loob ng 1 taon"],"h1":"Mayroon kang mga dalawang buwan.","h2":"Sa Mississippi, dapat kumuha ng Mississippi driver's license ang bagong residente sa loob ng 60 araw mula nang lumipat dito.","p":"Tama. May 60 araw ang mga bagong residente para kumuha ng Mississippi license."},"ar":{"q":"في Mississippi، انتقلت إلى هنا ومعك رخصة من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Mississippi؟","o":["خلال 60 يومًا","خلال 10 أيام","خلال 6 أشهر","خلال سنة واحدة"],"h1":"لديك شهران تقريبًا.","h2":"في Mississippi، يجب على المقيم الجديد أن يحصل على رخصة قيادة من Mississippi خلال 60 يومًا من انتقاله إلى هنا.","p":"صحيح. لدى المقيمين الجدد 60 يومًا للحصول على رخصة من Mississippi."},"ref":{"doc":"MS","page":11}},{"id":"ms-025","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, you have a crash and no one is hurt. When must you report it to the police right away?","o":["Only if the other driver asks you to","Only if a car must be towed","Only if it happens on an interstate","If the damage looks like more than $500"],"h1":"It depends on the dollar amount of the damage.","h2":"In Mississippi, you must report a crash to the police right away if anyone is hurt or killed, or if the damage looks like more than $500.","p":"Right. Damage over $500 must be reported right away."},"es":{"q":"En Mississippi, usted tiene un choque y nadie resulta herido. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si el otro conductor se lo pide","Solo si hay que remolcar un vehículo","Solo si ocurre en una autopista interestatal","Si los daños parecen ser de más de $500"],"h1":"Depende de la cantidad en dólares de los daños.","h2":"En Mississippi, usted debe reportar un choque a la policía de inmediato si alguien resulta herido o muerto, o si los daños parecen ser de más de $500.","p":"Correcto. Los daños de más de $500 se deben reportar de inmediato."},"zh":{"q":"在 Mississippi，你出了车祸，没有人受伤。什么时候你必须马上向警察报告？","o":["只有另一位司机要求你报告时","只有车必须被拖走时","只有在州际公路上发生时","如果损失看起来超过 $500"],"h1":"这取决于损失的金额。","h2":"在 Mississippi，如果有人受伤或死亡，或者损失看起来超过 $500，你必须马上向警察报告车祸。","p":"对。损失超过 $500 必须马上报告。"},"vi":{"q":"Ở Mississippi, bạn bị tai nạn và không ai bị thương. Khi nào bạn phải báo ngay cho cảnh sát?","o":["Chỉ khi người lái kia yêu cầu bạn báo","Chỉ khi có xe phải bị kéo đi","Chỉ khi tai nạn xảy ra trên xa lộ liên bang","Nếu thiệt hại có vẻ hơn $500"],"h1":"Điều này phụ thuộc vào số tiền thiệt hại.","h2":"Ở Mississippi, bạn phải báo ngay cho cảnh sát về tai nạn nếu có người bị thương hoặc tử vong, hoặc nếu thiệt hại có vẻ hơn $500.","p":"Đúng. Thiệt hại hơn $500 phải được báo ngay."},"tl":{"q":"Sa Mississippi, naaksidente ka at walang nasaktan. Kailan mo ito dapat iulat agad sa pulis?","o":["Kung hihilingin lang ito ng ibang driver","Kung kailangan lang hilahin ang isang sasakyan","Kung nangyari lang ito sa interstate","Kung mukhang higit sa $500 ang pinsala"],"h1":"Nakadepende ito sa halaga ng pinsala sa dolyar.","h2":"Sa Mississippi, dapat mong iulat agad sa pulis ang aksidente kung may nasaktan o namatay, o kung mukhang higit sa $500 ang pinsala.","p":"Tama. Dapat iulat agad ang pinsalang higit sa $500."},"ar":{"q":"في Mississippi، وقع لك حادث ولم يُصب أحد. متى يجب أن تبلّغ الشرطة عنه فورًا؟","o":["فقط إذا طلب منك السائق الآخر ذلك","فقط إذا كان يجب سحب سيارة","فقط إذا وقع على طريق سريع بين الولايات (interstate)","إذا بدا أن الضرر أكثر من $500"],"h1":"يعتمد ذلك على قيمة الضرر بالدولار.","h2":"في Mississippi، يجب أن تبلّغ الشرطة عن الحادث فورًا إذا أُصيب أحد أو مات، أو إذا بدا أن الضرر أكثر من $500.","p":"صحيح. يجب الإبلاغ فورًا عن الضرر الذي يزيد على $500."},"ref":{"doc":"MS","page":66}},{"id":"ms-026","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which children must ride in a child car seat?","o":["Children under 2","Children under 4","Children under 8","Children under 10"],"h1":"Think of a preschool child who is not yet old enough for a booster seat.","h2":"In Mississippi, a child under 4 years old must ride in a child car seat that meets safety standards.","p":"Right. Children under 4 must be in a car seat."},"es":{"q":"En Mississippi, ¿qué niños deben viajar en un asiento de seguridad para niños?","o":["Los menores de 2 años","Los menores de 4 años","Los menores de 8 años","Los menores de 10 años"],"h1":"Piense en un niño en edad preescolar que todavía no tiene edad para un asiento elevado.","h2":"En Mississippi, un niño menor de 4 años debe viajar en un asiento de seguridad para niños que cumpla las normas de seguridad.","p":"Correcto. Los niños menores de 4 años deben ir en un asiento de seguridad."},"zh":{"q":"在 Mississippi，哪些孩子必须坐儿童汽车座椅？","o":["2 岁以下的孩子","4 岁以下的孩子","8 岁以下的孩子","10 岁以下的孩子"],"h1":"想一想一个还没到可以用加高座椅（booster seat）年龄的学龄前孩子。","h2":"在 Mississippi，4 岁以下的孩子必须坐符合安全标准的儿童汽车座椅。","p":"对。4 岁以下的孩子必须坐儿童汽车座椅。"},"vi":{"q":"Ở Mississippi, những trẻ em nào phải ngồi ghế an toàn cho trẻ em trên xe?","o":["Trẻ em dưới 2 tuổi","Trẻ em dưới 4 tuổi","Trẻ em dưới 8 tuổi","Trẻ em dưới 10 tuổi"],"h1":"Hãy nghĩ đến một trẻ mẫu giáo chưa đủ lớn để ngồi ghế nâng (booster seat).","h2":"Ở Mississippi, trẻ em dưới 4 tuổi phải ngồi ghế an toàn cho trẻ em đạt tiêu chuẩn an toàn.","p":"Đúng. Trẻ em dưới 4 tuổi phải ngồi ghế an toàn cho trẻ em."},"tl":{"q":"Sa Mississippi, aling mga bata ang dapat nakaupo sa child car seat?","o":["Mga batang wala pang 2 taong gulang","Mga batang wala pang 4 taong gulang","Mga batang wala pang 8 taong gulang","Mga batang wala pang 10 taong gulang"],"h1":"Isipin ang isang batang preschool na hindi pa sapat ang edad para sa booster seat.","h2":"Sa Mississippi, ang batang wala pang 4 taong gulang ay dapat nakaupo sa child car seat na pumapasa sa mga pamantayan sa kaligtasan.","p":"Tama. Dapat nasa car seat ang mga batang wala pang 4 taong gulang."},"ar":{"q":"في Mississippi، أي الأطفال يجب أن يجلسوا في مقعد سيارة خاص بالأطفال؟","o":["الأطفال الذين أعمارهم أقل من سنتين","الأطفال الذين أعمارهم أقل من 4 سنوات","الأطفال الذين أعمارهم أقل من 8 سنوات","الأطفال الذين أعمارهم أقل من 10 سنوات"],"h1":"فكّر في طفل في سن ما قبل المدرسة لم يكبر بعد بما يكفي لمقعد الرفع (booster seat).","h2":"في Mississippi، يجب أن يجلس الطفل الذي عمره أقل من 4 سنوات في مقعد سيارة خاص بالأطفال يستوفي معايير السلامة.","p":"صحيح. يجب أن يجلس الأطفال الذين أعمارهم أقل من 4 سنوات في مقعد سيارة خاص بالأطفال."},"ref":{"doc":"MS","page":64}},{"id":"ms-027","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a 5-year-old is 4 feet tall and weighs 45 pounds. What must the child ride in?","o":["An adult seat belt alone","A lap belt in the front seat","A belt-positioning booster seat","Nothing, if the child sits in the back"],"h1":"The child is too small for an adult belt alone.","h2":"In Mississippi, a child from 4 to 6 years old who is shorter than 4 feet 9 inches or weighs under 65 pounds must ride in a belt-positioning booster seat.","p":"Right. This child must use a booster seat."},"es":{"q":"En Mississippi, un niño de 5 años mide 4 pies y pesa 45 libras. ¿En qué debe viajar el niño?","o":["Solo con el cinturón de seguridad de adulto","Con un cinturón de regazo en el asiento delantero","En un asiento elevado (booster) que posiciona el cinturón","En nada, si el niño va en el asiento trasero"],"h1":"El niño es demasiado pequeño para usar solo el cinturón de adulto.","h2":"En Mississippi, un niño de 4 a 6 años que mide menos de 4 pies y 9 pulgadas o pesa menos de 65 libras debe viajar en un asiento elevado (booster) que posiciona el cinturón.","p":"Correcto. Este niño debe usar un asiento elevado."},"zh":{"q":"在 Mississippi，一个 5 岁的孩子身高 4 英尺，体重 45 磅。这个孩子必须坐什么？","o":["只用成年人的安全带","前排的腰部安全带","调整安全带位置的加高座椅（booster seat）","什么都不用，只要孩子坐在后排"],"h1":"这个孩子太小，不能只用成年人的安全带。","h2":"在 Mississippi，4 到 6 岁、身高不到 4 英尺 9 英寸或体重不到 65 磅的孩子，必须坐调整安全带位置的加高座椅。","p":"对。这个孩子必须用加高座椅。"},"vi":{"q":"Ở Mississippi, một em bé 5 tuổi cao 4 feet và nặng 45 pounds. Em bé phải ngồi gì?","o":["Chỉ dây an toàn của người lớn","Dây an toàn ngang hông ở ghế trước","Ghế nâng định vị dây an toàn (booster seat)","Không cần gì, nếu em bé ngồi ở ghế sau"],"h1":"Em bé quá nhỏ để chỉ dùng dây an toàn của người lớn.","h2":"Ở Mississippi, trẻ em từ 4 đến 6 tuổi cao dưới 4 feet 9 inches hoặc nặng dưới 65 pounds phải ngồi ghế nâng định vị dây an toàn.","p":"Đúng. Em bé này phải dùng ghế nâng."},"tl":{"q":"Sa Mississippi, 4 feet ang taas at 45 pounds ang bigat ng isang 5 taong gulang na bata. Saan dapat nakaupo ang bata?","o":["Seat belt lang ng adult","Lap belt sa harapang upuan","Belt-positioning booster seat","Wala, kung sa likod nakaupo ang bata"],"h1":"Masyadong maliit ang bata para sa seat belt lang ng adult.","h2":"Sa Mississippi, ang batang 4 hanggang 6 taong gulang na mas maikli sa 4 feet 9 inches o mas magaan sa 65 pounds ay dapat nakaupo sa belt-positioning booster seat.","p":"Tama. Dapat gumamit ng booster seat ang batang ito."},"ar":{"q":"في Mississippi، طفل عمره 5 سنوات طوله 4 feet ووزنه 45 pounds. في ماذا يجب أن يجلس هذا الطفل؟","o":["حزام أمان البالغين وحده","حزام حضن في المقعد الأمامي","مقعد رفع يضبط وضع الحزام (booster seat)","لا شيء، إذا جلس الطفل في الخلف"],"h1":"الطفل أصغر من أن يستخدم حزام أمان البالغين وحده.","h2":"في Mississippi، الطفل الذي عمره من 4 إلى 6 سنوات وطوله أقل من 4 feet و9 inches أو وزنه أقل من 65 pounds يجب أن يجلس في مقعد رفع يضبط وضع الحزام.","p":"صحيح. يجب أن يستخدم هذا الطفل مقعد رفع."},"ref":{"doc":"MS","page":64}},{"id":"ms-028","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, you refuse a breath test when an officer asks. For how long is your license suspended?","o":["90 days","30 days","10 days","5 years"],"h1":"It is about three months.","h2":"In Mississippi, refusing a breath or chemical test leads to a 90-day license suspension.","p":"Right. Refusing the test means a 90-day suspension."},"es":{"q":"En Mississippi, usted se niega a hacer la prueba de aliento cuando un oficial se lo pide. ¿Por cuánto tiempo se suspende su licencia?","o":["90 días","30 días","10 días","5 años"],"h1":"Son unos tres meses.","h2":"En Mississippi, negarse a una prueba de aliento o química lleva a una suspensión de la licencia por 90 días.","p":"Correcto. Negarse a la prueba significa una suspensión de 90 días."},"zh":{"q":"在 Mississippi，警察要求你做呼气测试，你拒绝了。你的驾照会被暂停多久？","o":["90 天","30 天","10 天","5 年"],"h1":"大约三个月。","h2":"在 Mississippi，拒绝呼气测试或化学测试会导致驾照被暂停 90 天。","p":"对。拒绝测试就会被暂停 90 天。"},"vi":{"q":"Ở Mississippi, bạn từ chối thổi kiểm tra hơi thở khi cảnh sát yêu cầu. Bằng lái của bạn bị đình chỉ trong bao lâu?","o":["90 ngày","30 ngày","10 ngày","5 năm"],"h1":"Khoảng ba tháng.","h2":"Ở Mississippi, từ chối kiểm tra hơi thở hoặc kiểm tra hóa học sẽ bị đình chỉ bằng lái 90 ngày.","p":"Đúng. Từ chối kiểm tra nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Mississippi, tumanggi ka sa breath test nang hilingin ito ng pulis. Gaano katagal masususpinde ang lisensya mo?","o":["90 araw","30 araw","10 araw","5 taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa Mississippi, ang pagtanggi sa breath test o chemical test ay nagdudulot ng 90 araw na suspensyon ng lisensya.","p":"Tama. Ang pagtanggi sa test ay nangangahulugang 90 araw na suspensyon."},"ar":{"q":"في Mississippi، رفضت اختبار التنفس عندما طلبه منك الشرطي. لكم من الوقت تُوقَف رخصتك؟","o":["90 يومًا","30 يومًا","10 أيام","5 سنوات"],"h1":"إنها حوالي ثلاثة أشهر.","h2":"في Mississippi، رفض اختبار التنفس أو الاختبار الكيميائي يؤدي إلى إيقاف الرخصة لمدة 90 يومًا.","p":"صحيح. رفض الاختبار يعني إيقاف الرخصة لمدة 90 يومًا."},"ref":{"doc":"MS","page":78}},{"id":"ms-029","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, a driver 21 or older is convicted of a first DUI. For how long is the license suspended?","o":["30 days","5 years","10 days","120 days"],"h1":"It is about four months.","h2":"In Mississippi, a first DUI conviction for a driver 21 or older brings a 120-day license suspension.","p":"Right. A first DUI means a 120-day suspension."},"es":{"q":"En Mississippi, un conductor de 21 años o más es declarado culpable de un primer DUI. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","5 años","10 días","120 días"],"h1":"Son unos cuatro meses.","h2":"En Mississippi, una primera condena por DUI para un conductor de 21 años o más trae una suspensión de la licencia por 120 días.","p":"Correcto. Un primer DUI significa una suspensión de 120 días."},"zh":{"q":"在 Mississippi，一位 21 岁或以上的司机第一次被判 DUI（酒后驾驶）。驾照会被暂停多久？","o":["30 天","5 年","10 天","120 天"],"h1":"大约四个月。","h2":"在 Mississippi，21 岁或以上的司机第一次被判 DUI，驾照会被暂停 120 天。","p":"对。第一次 DUI 会被暂停 120 天。"},"vi":{"q":"Ở Mississippi, một người lái từ 21 tuổi trở lên bị kết tội DUI (lái xe khi say rượu) lần đầu. Bằng lái bị đình chỉ trong bao lâu?","o":["30 ngày","5 năm","10 ngày","120 ngày"],"h1":"Khoảng bốn tháng.","h2":"Ở Mississippi, người lái từ 21 tuổi trở lên bị kết tội DUI lần đầu sẽ bị đình chỉ bằng lái 120 ngày.","p":"Đúng. DUI lần đầu nghĩa là bị đình chỉ 120 ngày."},"tl":{"q":"Sa Mississippi, nahatulan sa unang DUI ang isang driver na 21 taong gulang pataas. Gaano katagal masususpinde ang lisensya?","o":["30 araw","5 taon","10 araw","120 araw"],"h1":"Mga apat na buwan ito.","h2":"Sa Mississippi, ang unang hatol sa DUI para sa driver na 21 taong gulang pataas ay nagdudulot ng 120 araw na suspensyon ng lisensya.","p":"Tama. Ang unang DUI ay nangangahulugang 120 araw na suspensyon."},"ar":{"q":"في Mississippi، أُدين سائق عمره 21 سنة أو أكثر بأول مخالفة قيادة تحت تأثير الكحول (DUI). لكم من الوقت تُوقَف رخصته؟","o":["30 يومًا","5 سنوات","10 أيام","120 يومًا"],"h1":"إنها حوالي أربعة أشهر.","h2":"في Mississippi، أول إدانة DUI لسائق عمره 21 سنة أو أكثر تؤدي إلى إيقاف الرخصة لمدة 120 يومًا.","p":"صحيح. أول DUI يعني إيقاف الرخصة لمدة 120 يومًا."},"ref":{"doc":"MS","page":79}},{"id":"ms-030","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the highest speed allowed for any vehicle in a school zone?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"It is slower than most city streets.","h2":"In Mississippi, no vehicle may go faster than 15 mph in a school zone.","p":"Right. The school zone limit is 15 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima permitida para cualquier vehículo en una zona escolar?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Es más lenta que en la mayoría de las calles de la ciudad.","h2":"En Mississippi, ningún vehículo puede ir a más de 15 mph en una zona escolar.","p":"Correcto. El límite en una zona escolar es de 15 mph."},"zh":{"q":"在 Mississippi，任何车辆在学校区域（school zone）允许的最高速度是多少？","o":["10 英里/小时","15 英里/小时","25 英里/小时","35 英里/小时"],"h1":"它比大多数市区街道的速度慢。","h2":"在 Mississippi，任何车辆在学校区域都不能超过 15 英里/小时。","p":"对。学校区域的限速是 15 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ cao nhất cho phép đối với mọi xe trong khu vực trường học (school zone) là bao nhiêu?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mức này chậm hơn hầu hết các con đường trong thành phố.","h2":"Ở Mississippi, không xe nào được chạy nhanh hơn 15 mph trong khu vực trường học.","p":"Đúng. Giới hạn trong khu vực trường học là 15 mph."},"tl":{"q":"Sa Mississippi, ano ang pinakamabilis na takbong pinapayagan para sa anumang sasakyan sa school zone?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mas mabagal ito kaysa sa karamihan ng kalye sa lungsod.","h2":"Sa Mississippi, walang sasakyang puwedeng tumakbo nang higit sa 15 mph sa school zone.","p":"Tama. 15 mph ang limitasyon sa school zone."},"ar":{"q":"في Mississippi، ما أعلى سرعة مسموح بها لأي مركبة في منطقة المدرسة (school zone)؟","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"إنها أبطأ من معظم شوارع المدينة.","h2":"في Mississippi، لا يجوز لأي مركبة أن تسير بسرعة أكثر من 15 mph في منطقة المدرسة.","p":"صحيح. حد السرعة في منطقة المدرسة هو 15 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-031","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, what is the minimum speed on an interstate highway when conditions are good?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Driving far below the flow of traffic on an interstate is also unsafe.","h2":"In Mississippi, the minimum speed on an interstate highway is 40 mph.","p":"Right. Do not drive slower than 40 mph on an interstate."},"es":{"q":"En Mississippi, ¿cuál es la velocidad mínima en una autopista interestatal cuando las condiciones son buenas?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Manejar muy por debajo del ritmo del tráfico en una interestatal también es peligroso.","h2":"En Mississippi, la velocidad mínima en una autopista interestatal es de 40 mph.","p":"Correcto. No maneje a menos de 40 mph en una interestatal."},"zh":{"q":"在 Mississippi，路况良好时，州际公路的最低速度是多少？","o":["20 英里/小时","30 英里/小时","40 英里/小时","50 英里/小时"],"h1":"在州际公路上开得比车流慢很多，也不安全。","h2":"在 Mississippi，州际公路的最低速度是 40 英里/小时。","p":"对。在州际公路上不要开得比 40 英里/小时慢。"},"vi":{"q":"Ở Mississippi, tốc độ tối thiểu trên xa lộ liên bang (interstate) khi điều kiện tốt là bao nhiêu?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Lái chậm hơn nhiều so với dòng xe trên xa lộ liên bang cũng không an toàn.","h2":"Ở Mississippi, tốc độ tối thiểu trên xa lộ liên bang là 40 mph.","p":"Đúng. Đừng lái chậm hơn 40 mph trên xa lộ liên bang."},"tl":{"q":"Sa Mississippi, ano ang pinakamabagal na takbo sa interstate highway kapag maganda ang kondisyon?","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"Hindi rin ligtas ang magmaneho nang mas mabagal nang malaki kaysa sa daloy ng trapiko sa interstate.","h2":"Sa Mississippi, ang pinakamabagal na takbo sa interstate highway ay 40 mph.","p":"Tama. Huwag magmaneho nang mas mabagal sa 40 mph sa interstate."},"ar":{"q":"في Mississippi، ما الحد الأدنى للسرعة على الطريق السريع بين الولايات (interstate) عندما تكون الظروف جيدة؟","o":["20 mph","30 mph","40 mph","50 mph"],"h1":"القيادة أبطأ بكثير من حركة المرور على الطريق السريع بين الولايات غير آمنة أيضًا.","h2":"في Mississippi، الحد الأدنى للسرعة على الطريق السريع بين الولايات هو 40 mph.","p":"صحيح. لا تقُد بسرعة أقل من 40 mph على الطريق السريع بين الولايات."},"ref":{"doc":"MS","page":41}},{"id":"ms-032","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, how early may you renew your driver's license before it expires?","o":["Up to 30 days","Up to 2 years","Only on the day it expires","Up to 6 months"],"h1":"It is half a year.","h2":"In Mississippi, a driver who qualifies for renewal may renew up to six months before the license expires.","p":"Right. You may renew up to 6 months early."},"es":{"q":"En Mississippi, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 30 días antes","Hasta 2 años antes","Solo el día en que vence","Hasta 6 meses antes"],"h1":"Es medio año.","h2":"En Mississippi, un conductor que califica para renovar puede hacerlo hasta seis meses antes de que venza la licencia.","p":"Correcto. Puede renovar hasta 6 meses antes."},"zh":{"q":"在 Mississippi，你最早可以在驾照到期前多久续期？","o":["最多 30 天","最多 2 年","只能在到期当天","最多 6 个月"],"h1":"是半年。","h2":"在 Mississippi，符合续期条件的司机最早可以在驾照到期前六个月续期。","p":"对。你最早可以提前 6 个月续期。"},"vi":{"q":"Ở Mississippi, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi bằng hết hạn?","o":["Tối đa 30 ngày","Tối đa 2 năm","Chỉ vào ngày bằng hết hạn","Tối đa 6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Mississippi, tài xế đủ điều kiện gia hạn có thể gia hạn bằng lái sớm nhất sáu tháng trước khi bằng hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 6 tháng."},"tl":{"q":"Sa Mississippi, gaano kaaga ka puwedeng mag-renew ng driver's license bago ito mag-expire?","o":["Hanggang 30 araw","Hanggang 2 taon","Sa mismong araw lang na mag-e-expire ito","Hanggang 6 na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Mississippi, ang driver na puwedeng mag-renew ay makakapag-renew hanggang anim na buwan bago mag-expire ang license.","p":"Tama. Puwede kang mag-renew hanggang 6 na buwan nang mas maaga."},"ar":{"q":"في Mississippi، قبل كم من الوقت من انتهاء رخصة القيادة يمكنك تجديدها؟","o":["حتى 30 يومًا","حتى سنتين (2)","فقط في يوم انتهائها","حتى 6 أشهر"],"h1":"إنها نصف سنة.","h2":"في Mississippi، يمكن للسائق المؤهل للتجديد أن يجدد رخصته حتى ستة أشهر قبل انتهائها.","p":"صحيح. يمكنك التجديد مبكرًا حتى 6 أشهر."},"ref":{"doc":"MS","page":12}},{"id":"ms-033","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, how much space must you leave between your vehicle and a bicycle when you pass it?","o":["At least 3 feet","At least 1 foot","At least 10 feet","At least 20 feet"],"h1":"Think of about one long step.","h2":"In Mississippi, you must leave at least 3 feet between your vehicle and a bicycle when you pass it.","p":"Right. Leave at least 3 feet."},"es":{"q":"En Mississippi, ¿cuánto espacio debe dejar entre su vehículo y una bicicleta al pasarla?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 10 pies","Por lo menos 20 pies"],"h1":"Piense en un paso largo.","h2":"En Mississippi, usted debe dejar por lo menos 3 pies entre su vehículo y una bicicleta al pasarla.","p":"Correcto. Deje por lo menos 3 pies."},"zh":{"q":"在 Mississippi，超过自行车时，你的车和自行车之间必须留出多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 10 英尺","至少 20 英尺"],"h1":"大约是迈一大步的距离。","h2":"在 Mississippi，超过自行车时，你的车和自行车之间必须至少留出 3 英尺。","p":"对。至少留出 3 英尺。"},"vi":{"q":"Ở Mississippi, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 3 feet","Ít nhất 1 feet","Ít nhất 10 feet","Ít nhất 20 feet"],"h1":"Hãy nghĩ đến khoảng một bước chân dài.","h2":"Ở Mississippi, khi vượt xe đạp, bạn phải chừa ít nhất 3 feet giữa xe của bạn và xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet."},"tl":{"q":"Sa Mississippi, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet","Hindi bababa sa 20 feet"],"h1":"Isipin ang mga isang mahabang hakbang.","h2":"Sa Mississippi, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet."},"ar":{"q":"في Mississippi، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية عندما تتجاوزها؟","o":["3 feet على الأقل","1 foot على الأقل","10 feet على الأقل","20 feet على الأقل"],"h1":"فكّر في خطوة واحدة طويلة تقريبًا.","h2":"في Mississippi، يجب أن تترك 3 feet على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها.","p":"صحيح. اترك 3 feet على الأقل."},"ref":{"doc":"MS","page":73}},{"id":"ms-034","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, you are using high beams at night. A car is coming toward you. When must you switch to low beams?","o":["When it is 50 feet away","Only if the other driver flashes the lights","When it is within 500 feet","When it is within one mile"],"h1":"The same distance applies when you follow another car.","h2":"In Mississippi, you must use low beams when an oncoming vehicle is within 500 feet, and also when you follow within 500 feet of another vehicle.","p":"Right. Switch to low beams within 500 feet."},"es":{"q":"En Mississippi, usted usa las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe cambiar a luces bajas?","o":["Cuando esté a 50 pies","Solo si el otro conductor le hace cambio de luces","Cuando esté a menos de 500 pies","Cuando esté a menos de una milla"],"h1":"La misma distancia aplica cuando sigue a otro carro.","h2":"En Mississippi, usted debe usar luces bajas cuando un vehículo que viene de frente está a menos de 500 pies, y también cuando sigue a otro vehículo a menos de 500 pies.","p":"Correcto. Cambie a luces bajas a menos de 500 pies."},"zh":{"q":"在 Mississippi，你在夜间开着远光灯，一辆车迎面开来。你必须在什么时候换成近光灯？","o":["当它离你 50 英尺时","只有对方司机闪灯时","当它在 500 英尺以内时","当它在一英里以内时"],"h1":"你跟在别的车后面时，也用同样的距离。","h2":"在 Mississippi，迎面来车在 500 英尺以内时，你必须使用近光灯；你跟在另一辆车后面 500 英尺以内时，也必须使用近光灯。","p":"对。在 500 英尺以内要换成近光灯。"},"vi":{"q":"Ở Mississippi, bạn đang bật đèn chiếu xa vào ban đêm. Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải chuyển sang đèn chiếu gần?","o":["Khi xe đó cách 50 feet","Chỉ khi tài xế kia nháy đèn","Khi xe đó ở trong vòng 500 feet","Khi xe đó ở trong vòng một dặm"],"h1":"Khoảng cách này cũng áp dụng khi bạn chạy sau một xe khác.","h2":"Ở Mississippi, bạn phải dùng đèn chiếu gần khi xe ngược chiều ở trong vòng 500 feet, và cả khi bạn chạy sau một xe khác trong vòng 500 feet.","p":"Đúng. Hãy chuyển sang đèn chiếu gần trong vòng 500 feet."},"tl":{"q":"Sa Mississippi, gumagamit ka ng high beams sa gabi. May kotseng papalapit sa iyo. Kailan ka dapat lumipat sa low beams?","o":["Kapag 50 feet na lang ang layo nito","Kapag nag-flash lang ng ilaw ang ibang driver","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng isang milya"],"h1":"Ganito rin ang layo kapag sumusunod ka sa ibang sasakyan.","h2":"Sa Mississippi, dapat kang gumamit ng low beams kapag nasa loob ng 500 feet ang paparating na sasakyan, at kapag sumusunod ka sa ibang sasakyan sa loob ng 500 feet.","p":"Tama. Lumipat sa low beams sa loob ng 500 feet."},"ar":{"q":"في Mississippi، أنت تستخدم الأضواء العالية ليلًا. وهناك سيارة قادمة نحوك. متى يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["عندما تكون على بعد 50 feet","فقط إذا ومض السائق الآخر بأضوائه","عندما تكون ضمن 500 feet","عندما تكون ضمن ميل واحد"],"h1":"المسافة نفسها تنطبق عندما تسير خلف سيارة أخرى.","h2":"في Mississippi، يجب أن تستخدم الأضواء المنخفضة عندما تكون السيارة القادمة نحوك ضمن 500 feet، وكذلك عندما تسير خلف سيارة أخرى ضمن 500 feet.","p":"صحيح. انتقل إلى الأضواء المنخفضة ضمن 500 feet."},"ref":{"doc":"MS","page":63}},{"id":"ms-035","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 100 feet","No closer than 3 feet"],"h1":"It is more than 10 feet but less than 20.","h2":"In Mississippi, you may not park within 15 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 15 feet from the nearest rail."},"es":{"q":"En Mississippi, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 100 pies","A no menos de 3 pies"],"h1":"Es más de 10 pies pero menos de 20.","h2":"En Mississippi, no puede estacionarse a menos de 15 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Mississippi，你停车时离铁路道口最近的铁轨最近可以有多近？","o":["不能近于 5 英尺","不能近于 15 英尺","不能近于 100 英尺","不能近于 3 英尺"],"h1":"它多于 10 英尺，但少于 20 英尺。","h2":"在 Mississippi，你不可以在离铁路道口最近的铁轨 15 英尺以内停车。","p":"对。要离最近的铁轨至少 15 英尺。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần thanh ray gần nhất của chỗ giao với đường sắt đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 100 feet","Không gần hơn 3 feet"],"h1":"Nhiều hơn 10 feet nhưng ít hơn 20 feet.","h2":"Ở Mississippi, bạn không được đỗ xe trong vòng 15 feet tính từ thanh ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Hãy cách thanh ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit ka puwedeng pumarada sa pinakamalapit na riles ng railroad crossing?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 100 feet","Hindi mas malapit sa 3 feet"],"h1":"Higit ito sa 10 feet pero kulang sa 20.","h2":"Sa Mississippi, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من أقرب سكة في معبر السكة الحديدية؟","o":["ليس أقرب من 5 feet","ليس أقرب من 15 feet","ليس أقرب من 100 feet","ليس أقرب من 3 feet"],"h1":"إنها أكثر من 10 feet لكن أقل من 20.","h2":"في Mississippi، لا يجوز لك أن تركن سيارتك ضمن 15 feet من أقرب سكة في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 15 feet على الأقل من أقرب سكة."},"ref":{"doc":"MS","page":60}},{"id":"ms-036","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 50 feet","No closer than 20 feet","No closer than 2 feet"],"h1":"It is about the length of one large car plus a little more.","h2":"In Mississippi, you may not park on a crosswalk or within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Mississippi, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["A no menos de 5 pies","A no menos de 50 pies","A no menos de 20 pies","A no menos de 2 pies"],"h1":"Es como el largo de un carro grande y un poco más.","h2":"En Mississippi, no puede estacionarse sobre un cruce peatonal ni a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese por lo menos a 20 pies del cruce peatonal."},"zh":{"q":"在 Mississippi，你停车时离路口的人行横道最近可以有多近？","o":["不能近于 5 英尺","不能近于 50 英尺","不能近于 20 英尺","不能近于 2 英尺"],"h1":"大约是一辆大车的长度再多一点。","h2":"在 Mississippi，你不可以停在人行横道上，也不可以停在路口人行横道 20 英尺以内。","p":"对。要离人行横道至少 20 英尺。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần lối băng qua đường cho người đi bộ tại giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 50 feet","Không gần hơn 20 feet","Không gần hơn 2 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe hơi lớn và thêm một chút.","h2":"Ở Mississippi, bạn không được đỗ xe trên lối băng qua đường cho người đi bộ hoặc trong vòng 20 feet tính từ lối băng qua đường tại giao lộ.","p":"Đúng. Hãy cách lối băng qua đường ít nhất 20 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit ka puwedeng pumarada sa tawiran (crosswalk) sa isang intersection?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 50 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 2 feet"],"h1":"Halos kasinghaba ito ng isang malaking kotse at kaunti pa.","h2":"Sa Mississippi, hindi ka puwedeng pumarada sa tawiran o sa loob ng 20 feet mula sa tawiran sa isang intersection.","p":"Tama. Lumayo nang hindi bababa sa 20 feet mula sa tawiran."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من ممر المشاة عند التقاطع؟","o":["ليس أقرب من 5 feet","ليس أقرب من 50 feet","ليس أقرب من 20 feet","ليس أقرب من 2 feet"],"h1":"إنها تقريبًا طول سيارة كبيرة واحدة وأكثر قليلًا.","h2":"في Mississippi، لا يجوز لك أن تركن سيارتك على ممر المشاة أو ضمن 20 feet من ممر المشاة عند التقاطع.","p":"صحيح. ابقَ على بعد 20 feet على الأقل من ممر المشاة."},"ref":{"doc":"MS","page":60}},{"id":"ms-037","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, what is the usual maximum speed on a two-lane state or U.S. highway, unless signs show a different limit?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is 10 mph lower than on a four-lane highway.","h2":"In Mississippi, the usual maximum speed on a two-lane state or U.S. highway is 55 mph.","p":"Right. Two-lane highways usually have a 55 mph limit."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima habitual en una carretera estatal o federal de dos carriles, a menos que las señales indiquen otro límite?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es 10 mph menos que en una carretera de cuatro carriles.","h2":"En Mississippi, la velocidad máxima habitual en una carretera estatal o federal de dos carriles es de 55 mph.","p":"Correcto. Las carreteras de dos carriles suelen tener un límite de 55 mph."},"zh":{"q":"在 Mississippi，如果没有标志显示其他限速，双车道的州公路或美国国道（U.S. highway）通常的最高速度是多少？","o":["55 英里/小时","45 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比四车道公路低 10 英里/小时。","h2":"在 Mississippi，双车道的州公路或美国国道通常的最高速度是 55 英里/小时。","p":"对。双车道公路通常限速 55 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc xa lộ liên bang Hoa Kỳ (U.S. highway) có hai làn xe là bao nhiêu, trừ khi biển báo cho thấy giới hạn khác?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó thấp hơn 10 mph so với trên xa lộ bốn làn xe.","h2":"Ở Mississippi, tốc độ tối đa thông thường trên xa lộ tiểu bang hoặc U.S. highway có hai làn xe là 55 mph.","p":"Đúng. Xa lộ hai làn xe thường có giới hạn 55 mph."},"tl":{"q":"Sa Mississippi, ano ang karaniwang pinakamataas na bilis sa two-lane na state o U.S. highway, maliban kung may sign na nagpapakita ng ibang limit?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito nang 10 mph kaysa sa four-lane na highway.","h2":"Sa Mississippi, ang karaniwang pinakamataas na bilis sa two-lane na state o U.S. highway ay 55 mph.","p":"Tama. Karaniwang 55 mph ang limit sa two-lane na highway."},"ar":{"q":"في Mississippi، ما السرعة القصوى المعتادة على طريق سريع للولاية أو طريق سريع أمريكي (U.S. highway) ذي مسارين، ما لم تُظهر اللافتات حدًا مختلفًا؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"إنها أقل بمقدار 10 mph من السرعة على طريق سريع ذي أربعة مسارات.","h2":"في Mississippi، السرعة القصوى المعتادة على طريق سريع للولاية أو طريق سريع أمريكي ذي مسارين هي 55 mph.","p":"صحيح. الحد المعتاد على الطرق السريعة ذات المسارين هو 55 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-038","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, what is the maximum speed on the Natchez Trace Parkway, unless a lower limit is posted?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"It is slower than a regular two-lane highway.","h2":"In Mississippi, the maximum speed on the Natchez Trace Parkway is 50 mph, unless a lower limit is posted.","p":"Right. The Natchez Trace Parkway limit is 50 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima en el Natchez Trace Parkway, a menos que se indique un límite más bajo?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"Es más lenta que en una carretera normal de dos carriles.","h2":"En Mississippi, la velocidad máxima en el Natchez Trace Parkway es de 50 mph, a menos que se indique un límite más bajo.","p":"Correcto. El límite en el Natchez Trace Parkway es de 50 mph."},"zh":{"q":"在 Mississippi，如果没有标出更低的限速，Natchez Trace Parkway 上的最高速度是多少？","o":["40 英里/小时","50 英里/小时","60 英里/小时","70 英里/小时"],"h1":"它比普通双车道公路慢。","h2":"在 Mississippi，Natchez Trace Parkway 上的最高速度是 50 英里/小时，除非标出了更低的限速。","p":"对。Natchez Trace Parkway 的限速是 50 英里/小时。"},"vi":{"q":"Ở Mississippi, tốc độ tối đa trên Natchez Trace Parkway là bao nhiêu, trừ khi có biển báo giới hạn thấp hơn?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"Nó chậm hơn so với xa lộ hai làn xe thông thường.","h2":"Ở Mississippi, tốc độ tối đa trên Natchez Trace Parkway là 50 mph, trừ khi có biển báo giới hạn thấp hơn.","p":"Đúng. Giới hạn trên Natchez Trace Parkway là 50 mph."},"tl":{"q":"Sa Mississippi, ano ang pinakamataas na bilis sa Natchez Trace Parkway, maliban kung may nakapaskil na mas mababang limit?","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"Mas mabagal ito kaysa sa karaniwang two-lane na highway.","h2":"Sa Mississippi, ang pinakamataas na bilis sa Natchez Trace Parkway ay 50 mph, maliban kung may nakapaskil na mas mababang limit.","p":"Tama. 50 mph ang limit sa Natchez Trace Parkway."},"ar":{"q":"في Mississippi، ما السرعة القصوى على طريق Natchez Trace Parkway، ما لم يُعلَن عن حد أقل؟","o":["40 mph","50 mph","60 mph","70 mph"],"h1":"إنها أبطأ من طريق سريع عادي ذي مسارين.","h2":"في Mississippi، السرعة القصوى على طريق Natchez Trace Parkway هي 50 mph، ما لم يُعلَن عن حد أقل.","p":"صحيح. الحد على طريق Natchez Trace Parkway هو 50 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-039","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, how close to a fire hydrant may you park?","o":["No closer than 3 feet","No closer than 50 feet","No closer than 10 feet","No closer than 100 feet"],"h1":"It is about two car widths.","h2":"In Mississippi, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a fire hydrant."},"es":{"q":"En Mississippi, ¿qué tan cerca de un hidrante puede estacionarse?","o":["A no menos de 3 pies","A no menos de 50 pies","A no menos de 10 pies","A no menos de 100 pies"],"h1":"Es más o menos el ancho de dos carros.","h2":"En Mississippi, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Mississippi，你可以在离消防栓多近的地方停车？","o":["不能近于 3 英尺","不能近于 50 英尺","不能近于 10 英尺","不能近于 100 英尺"],"h1":"大约是两辆车的宽度。","h2":"在 Mississippi，你不可以在消防栓 10 英尺以内停车。","p":"对。要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 3 feet","Không gần hơn 50 feet","Không gần hơn 10 feet","Không gần hơn 100 feet"],"h1":"Khoảng bằng chiều ngang của hai chiếc xe.","h2":"Ở Mississippi, bạn không được đỗ xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit sa fire hydrant ka puwedeng mag-park?","o":["Hindi mas malapit sa 3 feet","Hindi mas malapit sa 50 feet","Hindi mas malapit sa 10 feet","Hindi mas malapit sa 100 feet"],"h1":"Mga kasing-lapad ito ng dalawang kotse.","h2":"Sa Mississippi, hindi ka puwedeng mag-park sa loob ng 10 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 feet mula sa fire hydrant."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن قرب صنبور إطفاء الحريق؟","o":["ليس أقرب من 3 feet","ليس أقرب من 50 feet","ليس أقرب من 10 feet","ليس أقرب من 100 feet"],"h1":"إنها تقريبًا عرض سيارتين.","h2":"في Mississippi، يجب ألّا تركن سيارتك على بعد أقل من 10 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 feet على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"MS","page":60}},{"id":"ms-040","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, there is no sign. How close to the driveway entrance of a fire station may you park?","o":["No closer than 5 feet","No closer than 100 feet","No closer than 500 feet","No closer than 20 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In Mississippi, you may not park within 20 feet of a fire station driveway, or within 75 feet if a sign says so.","p":"Right. Stay at least 20 feet from a fire station driveway, or 75 feet where posted."},"es":{"q":"En Mississippi, no hay ninguna señal. ¿Qué tan cerca de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["A no menos de 5 pies","A no menos de 100 pies","A no menos de 500 pies","A no menos de 20 pies"],"h1":"Es la misma distancia que desde un cruce peatonal en una intersección.","h2":"En Mississippi, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos, o a menos de 75 pies si una señal lo indica.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de una estación de bomberos, o a 75 pies donde haya señal."},"zh":{"q":"在 Mississippi，没有标志时，你可以在离消防站车道入口多近的地方停车？","o":["不能近于 5 英尺","不能近于 100 英尺","不能近于 500 英尺","不能近于 20 英尺"],"h1":"它和在路口离人行横道的距离一样。","h2":"在 Mississippi，你不可以在消防站车道 20 英尺以内停车；如果有标志，就是 75 英尺以内。","p":"对。要离消防站车道至少 20 英尺；有标志的地方是 75 英尺。"},"vi":{"q":"Ở Mississippi, không có biển báo. Bạn được đỗ xe gần lối xe ra vào của trạm cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 20 feet"],"h1":"Khoảng cách này bằng khoảng cách từ lối qua đường dành cho người đi bộ ở giao lộ.","h2":"Ở Mississippi, bạn không được đỗ xe trong vòng 20 feet tính từ lối xe ra vào của trạm cứu hỏa, hoặc trong vòng 75 feet nếu có biển báo.","p":"Đúng. Hãy cách lối xe ra vào của trạm cứu hỏa ít nhất 20 feet, hoặc 75 feet nếu có biển báo."},"tl":{"q":"Sa Mississippi, walang sign. Gaano kalapit sa pasukan ng driveway ng fire station ka puwedeng mag-park?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 100 feet","Hindi mas malapit sa 500 feet","Hindi mas malapit sa 20 feet"],"h1":"Kapareho ito ng layo mula sa crosswalk sa isang intersection.","h2":"Sa Mississippi, hindi ka puwedeng mag-park sa loob ng 20 feet mula sa driveway ng fire station, o sa loob ng 75 feet kung may sign na nagsasabi nito.","p":"Tama. Lumayo nang hindi bababa sa 20 feet mula sa driveway ng fire station, o 75 feet kung may nakapaskil."},"ar":{"q":"في Mississippi، لا توجد لافتة. إلى أي مدى يمكنك أن تركن قرب مدخل ممر سيارات محطة الإطفاء؟","o":["ليس أقرب من 5 feet","ليس أقرب من 100 feet","ليس أقرب من 500 feet","ليس أقرب من 20 feet"],"h1":"إنها نفس المسافة من ممر المشاة عند التقاطع.","h2":"في Mississippi، يجب ألّا تركن على بعد أقل من 20 feet من ممر سيارات محطة الإطفاء، أو أقل من 75 feet إذا كانت هناك لافتة تقول ذلك.","p":"صحيح. ابقَ على بعد 20 feet على الأقل من ممر سيارات محطة الإطفاء، أو 75 feet حيث توجد لافتة."},"ref":{"doc":"MS","page":60}},{"id":"ms-041","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, how close to a stop sign or traffic light on your side of the road may you park?","o":["No closer than 5 feet","No closer than 30 feet","No closer than 200 feet","No closer than 500 feet"],"h1":"It is more than the distance from a crosswalk, but less than 50 feet.","h2":"In Mississippi, you may not park within 30 feet of the approach to a stop sign, traffic light or other traffic control device.","p":"Right. Stay at least 30 feet back from a stop sign or traffic light."},"es":{"q":"En Mississippi, ¿qué tan cerca de una señal de alto o un semáforo de su lado de la calle puede estacionarse?","o":["A no menos de 5 pies","A no menos de 30 pies","A no menos de 200 pies","A no menos de 500 pies"],"h1":"Es más que la distancia desde un cruce peatonal, pero menos de 50 pies.","h2":"En Mississippi, no puede estacionarse a menos de 30 pies antes de una señal de alto, un semáforo u otro dispositivo de control de tráfico.","p":"Correcto. Quédese por lo menos a 30 pies antes de una señal de alto o un semáforo."},"zh":{"q":"在 Mississippi，你可以在离你这一侧道路上的停车标志或红绿灯多近的地方停车？","o":["不能近于 5 英尺","不能近于 30 英尺","不能近于 200 英尺","不能近于 500 英尺"],"h1":"它比离人行横道的距离远，但少于 50 英尺。","h2":"在 Mississippi，你不可以在停车标志、红绿灯或其他交通控制设施前方 30 英尺以内停车。","p":"对。要在停车标志或红绿灯前至少 30 英尺的地方停车。"},"vi":{"q":"Ở Mississippi, bạn được đỗ xe gần biển báo dừng hoặc đèn giao thông ở phía đường của bạn đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 30 feet","Không gần hơn 200 feet","Không gần hơn 500 feet"],"h1":"Nó xa hơn khoảng cách từ lối qua đường dành cho người đi bộ, nhưng ít hơn 50 feet.","h2":"Ở Mississippi, bạn không được đỗ xe trong vòng 30 feet trước biển báo dừng, đèn giao thông hoặc thiết bị điều khiển giao thông khác.","p":"Đúng. Hãy cách biển báo dừng hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Mississippi, gaano kalapit sa stop sign o traffic light sa iyong panig ng kalsada ka puwedeng mag-park?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 200 feet","Hindi mas malapit sa 500 feet"],"h1":"Mas malayo ito kaysa sa layo mula sa crosswalk, pero kulang sa 50 feet.","h2":"Sa Mississippi, hindi ka puwedeng mag-park sa loob ng 30 feet bago ang stop sign, traffic light o iba pang traffic control device.","p":"Tama. Lumayo nang hindi bababa sa 30 feet bago ang stop sign o traffic light."},"ar":{"q":"في Mississippi، إلى أي مدى يمكنك أن تركن قرب لافتة توقف أو إشارة مرور على جانبك من الطريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 30 feet","ليس أقرب من 200 feet","ليس أقرب من 500 feet"],"h1":"إنها أكثر من المسافة من ممر المشاة، لكنها أقل من 50 feet.","h2":"في Mississippi، يجب ألّا تركن على بعد أقل من 30 feet قبل لافتة التوقف أو إشارة المرور أو أي جهاز آخر لتنظيم المرور.","p":"صحيح. ابقَ على بعد 30 feet على الأقل قبل لافتة التوقف أو إشارة المرور."},"ref":{"doc":"MS","page":60}},{"id":"ms-042","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, when you parallel park, how close to the curb should your tires be?","o":["Within 12 inches","Within 24 inches","Within 3 feet","Within 5 feet"],"h1":"It is about the length of a ruler.","h2":"In Mississippi, when you parallel park, your tires should be within 12 inches of the curb.","p":"Right. Park with your tires within 12 inches of the curb."},"es":{"q":"En Mississippi, cuando se estaciona en paralelo, ¿qué tan cerca del borde de la acera deben estar sus llantas?","o":["A 12 pulgadas o menos","A 24 pulgadas o menos","A 3 pies o menos","A 5 pies o menos"],"h1":"Es más o menos el largo de una regla.","h2":"En Mississippi, cuando se estaciona en paralelo, sus llantas deben quedar a 12 pulgadas o menos del borde de la acera.","p":"Correcto. Estaciónese con las llantas a 12 pulgadas o menos del borde."},"zh":{"q":"在 Mississippi，你平行停车时，轮胎应该离路边多近？","o":["12 英寸以内","24 英寸以内","3 英尺以内","5 英尺以内"],"h1":"大约是一把尺子的长度。","h2":"在 Mississippi，你平行停车时，轮胎应该在离路边 12 英寸以内。","p":"对。停车时轮胎要在离路边 12 英寸以内。"},"vi":{"q":"Ở Mississippi, khi bạn đỗ xe song song, bánh xe nên cách lề đường bao xa?","o":["Trong vòng 12 inches","Trong vòng 24 inches","Trong vòng 3 feet","Trong vòng 5 feet"],"h1":"Khoảng bằng chiều dài một cây thước kẻ.","h2":"Ở Mississippi, khi bạn đỗ xe song song, bánh xe của bạn nên cách lề đường trong vòng 12 inches.","p":"Đúng. Đỗ xe sao cho bánh xe cách lề đường trong vòng 12 inches."},"tl":{"q":"Sa Mississippi, kapag nag-parallel park ka, gaano kalapit sa curb dapat ang iyong mga gulong?","o":["Sa loob ng 12 inches","Sa loob ng 24 inches","Sa loob ng 3 feet","Sa loob ng 5 feet"],"h1":"Mga kasinghaba ito ng isang ruler.","h2":"Sa Mississippi, kapag nag-parallel park ka, dapat nasa loob ng 12 inches mula sa curb ang iyong mga gulong.","p":"Tama. Mag-park nang nasa loob ng 12 inches mula sa curb ang iyong mga gulong."},"ar":{"q":"في Mississippi، عندما تركن بشكل موازٍ، كم يجب أن تكون إطاراتك قريبة من الرصيف؟","o":["ضمن 12 inches","ضمن 24 inches","ضمن 3 feet","ضمن 5 feet"],"h1":"إنها تقريبًا طول مسطرة.","h2":"في Mississippi، عندما تركن بشكل موازٍ، يجب أن تكون إطاراتك ضمن 12 inches من الرصيف.","p":"صحيح. اركن بحيث تكون إطاراتك ضمن 12 inches من الرصيف."},"ref":{"doc":"MS","page":61}},{"id":"ms-043","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, you move here and your out-of-state license expired more than 30 days ago. What must you do?","o":["Nothing more than a regular new resident","Take only a driving road test","Hold a learner's permit for one year","Take the computerized knowledge exam"],"h1":"A valid out-of-state license lets you skip one test. An expired one does not.","h2":"In Mississippi, if your out-of-state license expired more than 30 days ago, you must take the computerized exam.","p":"Right. A license expired over 30 days means you take the computerized exam."},"es":{"q":"En Mississippi, usted se muda aquí y su licencia de otro estado venció hace más de 30 días. ¿Qué debe hacer?","o":["Nada más que un nuevo residente común","Tomar solo un examen práctico de manejo","Tener un permiso de aprendiz por un año","Tomar el examen de conocimientos por computadora"],"h1":"Una licencia válida de otro estado le permite saltarse un examen. Una vencida, no.","h2":"En Mississippi, si su licencia de otro estado venció hace más de 30 días, usted debe tomar el examen por computadora.","p":"Correcto. Con una licencia vencida hace más de 30 días, usted toma el examen por computadora."},"zh":{"q":"在 Mississippi，你搬到这里，而你的外州驾照已经过期超过 30 天。你必须做什么？","o":["和一般新居民一样，不需要做别的","只考路考","持有学习驾照一年","参加电脑知识考试"],"h1":"有效的外州驾照可以让你免考一项考试。过期的驾照就不行。","h2":"在 Mississippi，如果你的外州驾照已经过期超过 30 天，你必须参加电脑考试。","p":"对。驾照过期超过 30 天，就要参加电脑考试。"},"vi":{"q":"Ở Mississippi, bạn chuyển đến đây và bằng lái của tiểu bang khác đã hết hạn hơn 30 ngày. Bạn phải làm gì?","o":["Không cần làm gì hơn một cư dân mới bình thường","Chỉ thi lái xe trên đường","Giữ giấy phép tập lái trong một năm","Thi kiến thức trên máy tính"],"h1":"Bằng lái còn hạn của tiểu bang khác giúp bạn được miễn một bài thi. Bằng đã hết hạn thì không.","h2":"Ở Mississippi, nếu bằng lái của tiểu bang khác đã hết hạn hơn 30 ngày, bạn phải thi trên máy tính.","p":"Đúng. Bằng lái hết hạn hơn 30 ngày nghĩa là bạn phải thi trên máy tính."},"tl":{"q":"Sa Mississippi, lumipat ka rito at ang iyong out-of-state na license ay nag-expire nang higit sa 30 araw na ang nakalipas. Ano ang dapat mong gawin?","o":["Wala nang iba kundi ang ginagawa ng karaniwang bagong residente","Kumuha lang ng driving road test","Hawakan ang learner's permit nang isang taon","Kumuha ng computerized knowledge exam"],"h1":"Dahil sa valid na out-of-state na license, puwede kang hindi kumuha ng isang test. Hindi ganoon kapag expired na ito.","h2":"Sa Mississippi, kung nag-expire ang iyong out-of-state na license nang higit sa 30 araw na ang nakalipas, dapat kang kumuha ng computerized exam.","p":"Tama. Kapag expired nang higit sa 30 araw ang license, kukuha ka ng computerized exam."},"ar":{"q":"في Mississippi، انتقلت إلى هنا، ورخصتك من ولاية أخرى انتهت صلاحيتها منذ أكثر من 30 يومًا. ماذا يجب أن تفعل؟","o":["لا شيء أكثر مما يفعله أي مقيم جديد عادي","تؤدي اختبار القيادة على الطريق فقط","تحمل تصريح تعلّم القيادة لمدة سنة","تؤدي اختبار المعرفة على الكمبيوتر"],"h1":"الرخصة السارية من ولاية أخرى تعفيك من اختبار واحد. أما الرخصة المنتهية فلا تعفيك.","h2":"في Mississippi، إذا انتهت صلاحية رخصتك من ولاية أخرى منذ أكثر من 30 يومًا، فيجب أن تؤدي الاختبار على الكمبيوتر.","p":"صحيح. الرخصة المنتهية منذ أكثر من 30 يومًا تعني أن تؤدي الاختبار على الكمبيوتر."},"ref":{"doc":"MS","page":11}},{"id":"ms-044","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you passed the computerized exam for your learner's permit. How long is that passing score good for?","o":["Six months","One year","Two years","Ten years"],"h1":"It is the same length of time the learner's permit is valid.","h2":"In Mississippi, a passing score on the computerized exam is valid for two years.","p":"Right. Your exam score stays good for two years."},"es":{"q":"En Mississippi, usted aprobó el examen por computadora para su permiso de aprendiz. ¿Por cuánto tiempo es válido ese resultado?","o":["Seis meses","Un año","Dos años","Diez años"],"h1":"Es el mismo tiempo que dura el permiso de aprendiz.","h2":"En Mississippi, el resultado aprobado del examen por computadora es válido por dos años.","p":"Correcto. Su resultado del examen es válido por dos años."},"zh":{"q":"在 Mississippi，你通过了学习驾照的电脑考试。这个及格成绩有效多久？","o":["六个月","一年","两年","十年"],"h1":"它和学习驾照的有效时间一样长。","h2":"在 Mississippi，电脑考试的及格成绩有效期是两年。","p":"对。你的考试成绩两年内有效。"},"vi":{"q":"Ở Mississippi, bạn đã đậu bài thi trên máy tính để lấy giấy phép tập lái. Điểm đậu đó có giá trị trong bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Mười năm"],"h1":"Đó là cùng khoảng thời gian giấy phép tập lái có hiệu lực.","h2":"Ở Mississippi, điểm đậu bài thi trên máy tính có giá trị trong hai năm.","p":"Đúng. Điểm thi của bạn có giá trị trong hai năm."},"tl":{"q":"Sa Mississippi, pumasa ka sa computerized exam para sa iyong learner's permit. Gaano katagal valid ang pumasang score na iyon?","o":["Anim na buwan","Isang taon","Dalawang taon","Sampung taon"],"h1":"Kasinghaba ito ng panahong valid ang learner's permit.","h2":"Sa Mississippi, valid nang dalawang taon ang pumasang score sa computerized exam.","p":"Tama. Valid nang dalawang taon ang iyong exam score."},"ar":{"q":"في Mississippi، نجحت في الاختبار على الكمبيوتر للحصول على تصريح تعلّم القيادة. كم تبقى نتيجة النجاح هذه صالحة؟","o":["ستة أشهر","سنة واحدة","سنتان","عشر سنوات"],"h1":"إنها نفس المدة التي يكون فيها تصريح تعلّم القيادة صالحًا.","h2":"في Mississippi، تبقى نتيجة النجاح في الاختبار على الكمبيوتر صالحة لمدة سنتين.","p":"صحيح. تبقى نتيجة اختبارك صالحة لمدة سنتين."},"ref":{"doc":"MS","page":13}},{"id":"ms-045","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a teen got a learner's permit at 16. The teen turns 17 before holding it for a full year. What is true?","o":["The teen may apply for a regular license now","The teen must still wait the full year","The teen must get a new learner's permit","The teen must wait until age 18"],"h1":"Age 17 changes the waiting rule.","h2":"In Mississippi, if you turn 17 before you have held a learner's permit for one year, you may apply for a regular license.","p":"Right. At 17, the one-year wait no longer applies."},"es":{"q":"En Mississippi, un joven obtuvo un permiso de aprendiz a los 16 años. Cumple 17 antes de tenerlo un año completo. ¿Qué es cierto?","o":["Ya puede solicitar una licencia regular","Todavía debe esperar el año completo","Debe obtener un nuevo permiso de aprendiz","Debe esperar hasta los 18 años"],"h1":"Cumplir 17 años cambia la regla de espera.","h2":"En Mississippi, si usted cumple 17 años antes de tener el permiso de aprendiz por un año, puede solicitar una licencia regular.","p":"Correcto. A los 17 años, ya no aplica la espera de un año."},"zh":{"q":"在 Mississippi，一名青少年 16 岁拿到学习驾照。他还没持有满一年就满 17 岁了。哪一项是对的？","o":["这名青少年现在可以申请普通驾照","这名青少年仍然必须等满一年","这名青少年必须重新拿一张学习驾照","这名青少年必须等到 18 岁"],"h1":"17 岁会改变等待的规定。","h2":"在 Mississippi，如果你在持有学习驾照满一年之前就满 17 岁，你可以申请普通驾照。","p":"对。满 17 岁时，就不用再等一年了。"},"vi":{"q":"Ở Mississippi, một thiếu niên được cấp giấy phép tập lái lúc 16 tuổi. Thiếu niên đó tròn 17 tuổi trước khi giữ giấy phép đủ một năm. Điều nào đúng?","o":["Thiếu niên đó có thể nộp đơn xin bằng lái thông thường ngay bây giờ","Thiếu niên đó vẫn phải chờ đủ một năm","Thiếu niên đó phải xin giấy phép tập lái mới","Thiếu niên đó phải chờ đến 18 tuổi"],"h1":"Tuổi 17 làm thay đổi quy định về thời gian chờ.","h2":"Ở Mississippi, nếu bạn tròn 17 tuổi trước khi giữ giấy phép tập lái đủ một năm, bạn có thể nộp đơn xin bằng lái thông thường.","p":"Đúng. Khi 17 tuổi, không còn phải chờ một năm nữa."},"tl":{"q":"Sa Mississippi, nakakuha ang isang teen ng learner's permit sa edad na 16. Nag-17 ang teen bago pa nito mahawakan ang permit nang buong isang taon. Ano ang totoo?","o":["Puwede nang mag-apply ang teen ng regular na license ngayon","Kailangan pa ring hintayin ng teen ang buong taon","Kailangang kumuha ang teen ng bagong learner's permit","Kailangang maghintay ang teen hanggang edad 18"],"h1":"Binabago ng edad na 17 ang patakaran sa paghihintay.","h2":"Sa Mississippi, kung mag-17 ka bago mo mahawakan ang learner's permit nang isang taon, puwede ka nang mag-apply ng regular na license.","p":"Tama. Sa edad na 17, hindi na kailangan ang isang taong paghihintay."},"ar":{"q":"في Mississippi، حصل مراهق على تصريح تعلّم القيادة في سن 16. وبلغ سن 17 قبل أن يحمله لمدة سنة كاملة. ما الصحيح؟","o":["يمكن للمراهق أن يتقدم الآن بطلب للحصول على رخصة عادية","يجب على المراهق أن ينتظر السنة الكاملة رغم ذلك","يجب على المراهق أن يحصل على تصريح تعلّم جديد","يجب على المراهق أن ينتظر حتى سن 18"],"h1":"سن 17 يغيّر قاعدة الانتظار.","h2":"في Mississippi، إذا بلغت سن 17 قبل أن تحمل تصريح تعلّم القيادة لمدة سنة واحدة، يمكنك أن تتقدم بطلب للحصول على رخصة عادية.","p":"صحيح. في سن 17، لم تعد مدة الانتظار البالغة سنة واحدة تنطبق."},"ref":{"doc":"MS","page":13}},{"id":"ms-046","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, an applicant under 18 brings a Certification of Attendance from school. How old may that form be?","o":["No more than 1 year old","No more than 30 days old","No more than 6 months old","Any age, if it is signed"],"h1":"It must be about one month old or newer.","h2":"In Mississippi, the school Certification of Attendance for an applicant under 18 must not be more than 30 days old.","p":"Right. The attendance form must be 30 days old or newer."},"es":{"q":"En Mississippi, un solicitante menor de 18 años trae un Certificado de Asistencia de la escuela. ¿Qué antigüedad puede tener ese formulario?","o":["No más de 1 año","No más de 30 días","No más de 6 meses","Cualquiera, si está firmado"],"h1":"Debe tener más o menos un mes o menos.","h2":"En Mississippi, el Certificado de Asistencia escolar de un solicitante menor de 18 años no debe tener más de 30 días.","p":"Correcto. El formulario de asistencia debe tener 30 días o menos."},"zh":{"q":"在 Mississippi，一位未满 18 岁的申请人带来学校开的出勤证明（Certification of Attendance）。这份表格最多可以是多久以前开的？","o":["不超过 1 年","不超过 30 天","不超过 6 个月","多久都可以，只要有签名"],"h1":"它必须是大约一个月内开的。","h2":"在 Mississippi，未满 18 岁申请人的学校出勤证明不能超过 30 天。","p":"对。出勤证明必须是 30 天内开的。"},"vi":{"q":"Ở Mississippi, một người nộp đơn dưới 18 tuổi mang theo Giấy chứng nhận đi học (Certification of Attendance) của trường. Giấy này được cấp tối đa bao lâu trước đó?","o":["Không quá 1 năm","Không quá 30 ngày","Không quá 6 tháng","Bao lâu cũng được, nếu có chữ ký"],"h1":"Giấy phải được cấp trong khoảng một tháng trở lại đây.","h2":"Ở Mississippi, Giấy chứng nhận đi học của trường cho người nộp đơn dưới 18 tuổi không được cấp quá 30 ngày.","p":"Đúng. Giấy chứng nhận đi học phải được cấp trong vòng 30 ngày."},"tl":{"q":"Sa Mississippi, nagdala ang isang aplikanteng wala pang 18 ng Certification of Attendance mula sa paaralan. Gaano na katagal puwede ang form na iyon?","o":["Hindi hihigit sa 1 taon","Hindi hihigit sa 30 araw","Hindi hihigit sa 6 na buwan","Kahit gaano katagal, basta may pirma"],"h1":"Dapat mga isang buwan pa lang ito o mas bago.","h2":"Sa Mississippi, ang Certification of Attendance mula sa paaralan para sa aplikanteng wala pang 18 ay hindi dapat lumampas sa 30 araw.","p":"Tama. Dapat 30 araw pa lang o mas bago ang attendance form."},"ar":{"q":"في Mississippi، أحضر متقدم عمره أقل من 18 سنة شهادة حضور من المدرسة (Certification of Attendance). كم يمكن أن يكون عمر هذا النموذج؟","o":["ليس أقدم من 1 سنة","ليس أقدم من 30 يومًا","ليس أقدم من 6 أشهر","أي عمر، إذا كان موقّعًا"],"h1":"يجب أن يكون عمره شهرًا تقريبًا أو أحدث.","h2":"في Mississippi، يجب ألّا يكون عمر شهادة الحضور المدرسية لمتقدم عمره أقل من 18 سنة أكثر من 30 يومًا.","p":"صحيح. يجب أن يكون عمر نموذج الحضور 30 يومًا أو أقل."},"ref":{"doc":"MS","page":16}},{"id":"ms-047","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a parent signs a teen's application for a permit or license. What does that signature mean?","o":["The parent must ride along on every trip","The parent pays the teen's insurance by law","The parent must take the exam too","The parent becomes liable for the teen's negligent driving"],"h1":"The person who signs takes on legal responsibility.","h2":"In Mississippi, whoever signs a teen's application becomes liable for the teen's negligence or willful misconduct, and the signature must be notarized.","p":"Right. The signer becomes responsible for the teen's negligent driving."},"es":{"q":"En Mississippi, un padre o una madre firma la solicitud de permiso o licencia de un joven. ¿Qué significa esa firma?","o":["Debe acompañar al joven en cada viaje","Debe pagar por ley el seguro del joven","También debe tomar el examen","Se vuelve responsable legal por la negligencia del joven al manejar"],"h1":"La persona que firma asume una responsabilidad legal.","h2":"En Mississippi, quien firma la solicitud de un joven se vuelve responsable por la negligencia o mala conducta intencional del joven, y la firma debe estar notarizada.","p":"Correcto. Quien firma se vuelve responsable si el joven maneja con negligencia."},"zh":{"q":"在 Mississippi，父母在青少年的学习驾照或驾照申请上签名。这个签名是什么意思？","o":["父母每次开车都必须同车","依法由父母支付青少年的保险","父母也必须参加考试","父母要为青少年的疏忽驾驶承担法律责任"],"h1":"签名的人要承担法律责任。","h2":"在 Mississippi，在青少年申请上签名的人，要为青少年的疏忽或故意不当行为承担法律责任，而且签名必须经过公证。","p":"对。签名的人要为青少年的疏忽驾驶负责。"},"vi":{"q":"Ở Mississippi, cha hoặc mẹ ký vào đơn xin giấy phép tập lái hoặc bằng lái của thiếu niên. Chữ ký đó có nghĩa là gì?","o":["Cha mẹ phải đi cùng trong mọi chuyến xe","Theo luật, cha mẹ trả tiền bảo hiểm cho thiếu niên","Cha mẹ cũng phải thi","Cha mẹ phải chịu trách nhiệm pháp lý về việc lái xe cẩu thả của thiếu niên"],"h1":"Người ký nhận trách nhiệm pháp lý.","h2":"Ở Mississippi, người ký vào đơn của thiếu niên phải chịu trách nhiệm pháp lý về sự cẩu thả hoặc hành vi sai trái cố ý của thiếu niên, và chữ ký phải được công chứng.","p":"Đúng. Người ký phải chịu trách nhiệm về việc lái xe cẩu thả của thiếu niên."},"tl":{"q":"Sa Mississippi, pumirma ang magulang sa application ng isang teen para sa permit o license. Ano ang ibig sabihin ng pirmang iyon?","o":["Kailangang sumama ang magulang sa bawat biyahe","Ayon sa batas, babayaran ng magulang ang insurance ng teen","Kailangan ding kumuha ng exam ang magulang","Mananagot ang magulang sa pabayang pagmamaneho ng teen"],"h1":"Ang taong pumirma ang tumatanggap ng legal na pananagutan.","h2":"Sa Mississippi, ang sinumang pumirma sa application ng teen ay mananagot sa kapabayaan o sadyang maling gawain ng teen, at kailangang notarized ang pirma.","p":"Tama. Mananagot ang pumirma sa pabayang pagmamaneho ng teen."},"ar":{"q":"في Mississippi، يوقّع أحد الوالدين على طلب مراهق للحصول على تصريح أو رخصة. ماذا يعني هذا التوقيع؟","o":["يجب أن يركب الوالد مع المراهق في كل رحلة","يدفع الوالد تأمين المراهق بحكم القانون","يجب أن يؤدي الوالد الاختبار أيضًا","يصبح الوالد مسؤولًا قانونيًا عن قيادة المراهق المهملة"],"h1":"الشخص الذي يوقّع يتحمل المسؤولية القانونية.","h2":"في Mississippi، كل من يوقّع على طلب المراهق يصبح مسؤولًا قانونيًا عن إهمال المراهق أو سوء سلوكه المتعمد، ويجب أن يكون التوقيع موثّقًا لدى كاتب عدل.","p":"صحيح. يصبح الموقّع مسؤولًا عن قيادة المراهق المهملة."},"ref":{"doc":"MS","page":16}},{"id":"ms-048","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you refuse a breath test and give your license to the officer. How long is the officer's receipt good as a temporary permit?","o":["10 days","90 days","45 days","1 year"],"h1":"It is about a month and a half.","h2":"In Mississippi, after you refuse a breath or chemical test, the officer's receipt works as a temporary permit for 45 days.","p":"Right. The receipt is a temporary permit for 45 days."},"es":{"q":"En Mississippi, usted se niega a la prueba de aliento y entrega su licencia al oficial. ¿Por cuánto tiempo sirve el recibo del oficial como permiso temporal?","o":["10 días","90 días","45 días","1 año"],"h1":"Es más o menos un mes y medio.","h2":"En Mississippi, después de negarse a una prueba de aliento o química, el recibo del oficial sirve como permiso temporal por 45 días.","p":"Correcto. El recibo es un permiso temporal por 45 días."},"zh":{"q":"在 Mississippi，你拒绝呼气测试，并把驾照交给警察。警察给你的收据可以当临时驾照用多久？","o":["10 天","90 天","45 天","1 年"],"h1":"大约是一个半月。","h2":"在 Mississippi，你拒绝呼气或化学测试后，警察给的收据可以当 45 天的临时驾照。","p":"对。收据是 45 天的临时驾照。"},"vi":{"q":"Ở Mississippi, bạn từ chối thử hơi thở và giao bằng lái cho cảnh sát. Biên nhận của cảnh sát có giá trị như giấy phép tạm thời trong bao lâu?","o":["10 ngày","90 ngày","45 ngày","1 năm"],"h1":"Khoảng một tháng rưỡi.","h2":"Ở Mississippi, sau khi bạn từ chối thử hơi thở hoặc thử hóa chất, biên nhận của cảnh sát có giá trị như giấy phép tạm thời trong 45 ngày.","p":"Đúng. Biên nhận là giấy phép tạm thời trong 45 ngày."},"tl":{"q":"Sa Mississippi, tumanggi ka sa breath test at ibinigay mo ang iyong license sa officer. Gaano katagal valid bilang temporary permit ang resibo ng officer?","o":["10 araw","90 araw","45 araw","1 taon"],"h1":"Mga isang buwan at kalahati ito.","h2":"Sa Mississippi, pagkatapos mong tumanggi sa breath o chemical test, magsisilbing temporary permit ang resibo ng officer nang 45 araw.","p":"Tama. Temporary permit ang resibo nang 45 araw."},"ar":{"q":"في Mississippi، رفضت اختبار التنفس وسلّمت رخصتك للشرطي. كم يبقى إيصال الشرطي صالحًا كتصريح مؤقت؟","o":["10 أيام","90 يومًا","45 يومًا","1 سنة"],"h1":"إنها تقريبًا شهر ونصف.","h2":"في Mississippi، بعد أن ترفض اختبار التنفس أو الاختبار الكيميائي، يكون إيصال الشرطي تصريحًا مؤقتًا لمدة 45 يومًا.","p":"صحيح. الإيصال تصريح مؤقت لمدة 45 يومًا."},"ref":{"doc":"MS","page":78}},{"id":"ms-049","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the fine for a first DUI offense for a driver 21 or older?","o":["$250 to $1,000","$25 to $100","$2,000 to $5,000","$5,000 to $10,000"],"h1":"The highest amount is one thousand dollars.","h2":"In Mississippi, a first DUI offense for a driver 21 or older carries a fine of $250 to $1,000.","p":"Right. A first DUI fine is $250 to $1,000."},"es":{"q":"En Mississippi, ¿cuál es la multa por un primer DUI para un conductor de 21 años o más?","o":["De $250 a $1,000","De $25 a $100","De $2,000 a $5,000","De $5,000 a $10,000"],"h1":"La cantidad más alta es de mil dólares.","h2":"En Mississippi, un primer DUI para un conductor de 21 años o más tiene una multa de $250 a $1,000.","p":"Correcto. La multa por un primer DUI es de $250 a $1,000."},"zh":{"q":"在 Mississippi，21 岁或以上的司机第一次酒驾（DUI）的罚款是多少？","o":["$250 到 $1,000","$25 到 $100","$2,000 到 $5,000","$5,000 到 $10,000"],"h1":"最高金额是一千美元。","h2":"在 Mississippi，21 岁或以上的司机第一次酒驾，罚款是 $250 到 $1,000。","p":"对。第一次酒驾的罚款是 $250 到 $1,000。"},"vi":{"q":"Ở Mississippi, mức phạt cho lần vi phạm DUI đầu tiên của người lái xe từ 21 tuổi trở lên là bao nhiêu?","o":["$250 đến $1,000","$25 đến $100","$2,000 đến $5,000","$5,000 đến $10,000"],"h1":"Số tiền cao nhất là một nghìn đô la.","h2":"Ở Mississippi, lần vi phạm DUI đầu tiên của người lái xe từ 21 tuổi trở lên bị phạt từ $250 đến $1,000.","p":"Đúng. Tiền phạt DUI lần đầu là từ $250 đến $1,000."},"tl":{"q":"Sa Mississippi, magkano ang multa para sa unang DUI offense ng driver na 21 o mas matanda?","o":["$250 hanggang $1,000","$25 hanggang $100","$2,000 hanggang $5,000","$5,000 hanggang $10,000"],"h1":"Isang libong dolyar ang pinakamataas na halaga.","h2":"Sa Mississippi, ang unang DUI offense ng driver na 21 o mas matanda ay may multang $250 hanggang $1,000.","p":"Tama. $250 hanggang $1,000 ang multa sa unang DUI."},"ar":{"q":"في Mississippi، ما غرامة المخالفة الأولى للقيادة تحت تأثير الكحول (DUI) لسائق عمره 21 سنة أو أكثر؟","o":["من $250 إلى $1,000","من $25 إلى $100","من $2,000 إلى $5,000","من $5,000 إلى $10,000"],"h1":"أعلى مبلغ هو ألف دولار.","h2":"في Mississippi، غرامة المخالفة الأولى للقيادة تحت تأثير الكحول (DUI) لسائق عمره 21 سنة أو أكثر هي من $250 إلى $1,000.","p":"صحيح. غرامة DUI الأولى هي من $250 إلى $1,000."},"ref":{"doc":"MS","page":79}},{"id":"ms-050","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a driver is convicted of a first DUI and also refused the breath test. What happens to the license suspension?","o":["The refusal is ignored","The suspension is cut in half","The license is taken for life","90 days are added to the suspension"],"h1":"Refusing the test makes the penalty longer.","h2":"In Mississippi, if you are convicted of a first DUI and you also refused the breath or chemical test, 90 days are added to the license suspension.","p":"Right. Refusing the test adds 90 days."},"es":{"q":"En Mississippi, un conductor es declarado culpable de un primer DUI y además se negó a la prueba de aliento. ¿Qué pasa con la suspensión de la licencia?","o":["No se toma en cuenta la negativa","La suspensión se reduce a la mitad","Se le quita la licencia de por vida","Se agregan 90 días a la suspensión"],"h1":"Negarse a la prueba hace la pena más larga.","h2":"En Mississippi, si usted es declarado culpable de un primer DUI y además se negó a la prueba de aliento o química, se agregan 90 días a la suspensión de la licencia.","p":"Correcto. Negarse a la prueba agrega 90 días."},"zh":{"q":"在 Mississippi，一位司机第一次酒驾（DUI）被定罪，而且他也拒绝了呼气测试。驾照的暂停期会怎样？","o":["拒绝测试不算","暂停期减半","驾照被终身收回","暂停期再加 90 天"],"h1":"拒绝测试会让处罚更长。","h2":"在 Mississippi，如果你第一次酒驾被定罪，而且你也拒绝了呼气或化学测试，驾照暂停期会再加 90 天。","p":"对。拒绝测试会多加 90 天。"},"vi":{"q":"Ở Mississippi, một người lái xe bị kết án DUI lần đầu và cũng đã từ chối thử hơi thở. Việc đình chỉ bằng lái sẽ ra sao?","o":["Việc từ chối không được tính","Thời gian đình chỉ bị giảm một nửa","Bằng lái bị lấy đi suốt đời","Thời gian đình chỉ được cộng thêm 90 ngày"],"h1":"Từ chối thử nghiệm làm hình phạt dài hơn.","h2":"Ở Mississippi, nếu bạn bị kết án DUI lần đầu và bạn cũng đã từ chối thử hơi thở hoặc thử hóa chất, thời gian đình chỉ bằng lái được cộng thêm 90 ngày.","p":"Đúng. Từ chối thử nghiệm sẽ bị cộng thêm 90 ngày."},"tl":{"q":"Sa Mississippi, nahatulan ang isang driver sa unang DUI at tumanggi rin siya sa breath test. Ano ang mangyayari sa suspension ng license?","o":["Hindi papansinin ang pagtanggi","Mababawasan nang kalahati ang suspension","Kukunin ang license habambuhay","Madadagdagan ng 90 araw ang suspension"],"h1":"Pinahahaba ng pagtanggi sa test ang parusa.","h2":"Sa Mississippi, kung nahatulan ka sa unang DUI at tumanggi ka rin sa breath o chemical test, madadagdagan ng 90 araw ang suspension ng license.","p":"Tama. Nagdadagdag ng 90 araw ang pagtanggi sa test."},"ar":{"q":"في Mississippi، أُدين سائق بأول مخالفة قيادة تحت تأثير الكحول (DUI)، وكان قد رفض أيضًا اختبار التنفس. ماذا يحدث لمدة إيقاف الرخصة؟","o":["يُتجاهَل الرفض","تُخفَّض مدة الإيقاف إلى النصف","تُسحب الرخصة مدى الحياة","تُضاف 90 يومًا إلى مدة الإيقاف"],"h1":"رفض الاختبار يجعل العقوبة أطول.","h2":"في Mississippi، إذا أُدنت بأول مخالفة DUI وكنت قد رفضت أيضًا اختبار التنفس أو الاختبار الكيميائي، تُضاف 90 يومًا إلى مدة إيقاف الرخصة.","p":"صحيح. رفض الاختبار يضيف 90 يومًا."},"ref":{"doc":"MS","page":79}},{"id":"ms-051","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a driver 21 or older is convicted of a second DUI within five years. For how long is the license suspended?","o":["30 days","1 year","120 days","10 years"],"h1":"It is much longer than for a first offense.","h2":"In Mississippi, a second DUI within five years brings a license suspension of one year.","p":"Right. A second DUI within five years means a one-year suspension."},"es":{"q":"En Mississippi, un conductor de 21 años o más es declarado culpable de un segundo DUI en un plazo de cinco años. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","1 año","120 días","10 años"],"h1":"Es mucho más largo que por una primera vez.","h2":"En Mississippi, un segundo DUI en un plazo de cinco años trae una suspensión de la licencia por un año.","p":"Correcto. Un segundo DUI en cinco años significa una suspensión de un año."},"zh":{"q":"在 Mississippi，一位 21 岁或以上的司机在五年内第二次酒驾（DUI）被定罪。驾照会被暂停多久？","o":["30 天","1 年","120 天","10 年"],"h1":"它比第一次违规长很多。","h2":"在 Mississippi，五年内第二次酒驾会让驾照被暂停一年。","p":"对。五年内第二次酒驾，驾照暂停一年。"},"vi":{"q":"Ở Mississippi, một người lái xe từ 21 tuổi trở lên bị kết án DUI lần thứ hai trong vòng năm năm. Bằng lái bị đình chỉ trong bao lâu?","o":["30 ngày","1 năm","120 ngày","10 năm"],"h1":"Thời gian này dài hơn nhiều so với lần vi phạm đầu tiên.","h2":"Ở Mississippi, vi phạm DUI lần thứ hai trong vòng năm năm sẽ bị đình chỉ bằng lái một năm.","p":"Đúng. DUI lần thứ hai trong vòng năm năm nghĩa là bị đình chỉ một năm."},"tl":{"q":"Sa Mississippi, nahatulan ang isang driver na 21 o mas matanda sa ikalawang DUI sa loob ng limang taon. Gaano katagal masususpinde ang license?","o":["30 araw","1 taon","120 araw","10 taon"],"h1":"Mas matagal ito nang husto kaysa sa unang offense.","h2":"Sa Mississippi, ang ikalawang DUI sa loob ng limang taon ay may suspension ng license nang isang taon.","p":"Tama. Ang ikalawang DUI sa loob ng limang taon ay nangangahulugan ng isang taong suspension."},"ar":{"q":"في Mississippi، أُدين سائق عمره 21 سنة أو أكثر بمخالفة DUI ثانية خلال خمس سنوات. كم مدة إيقاف الرخصة؟","o":["30 يومًا","1 سنة","120 يومًا","10 سنوات"],"h1":"إنها أطول بكثير من مدة المخالفة الأولى.","h2":"في Mississippi، المخالفة الثانية للقيادة تحت تأثير الكحول (DUI) خلال خمس سنوات تؤدي إلى إيقاف الرخصة لمدة سنة واحدة.","p":"صحيح. مخالفة DUI الثانية خلال خمس سنوات تعني إيقافًا لمدة سنة واحدة."},"ref":{"doc":"MS","page":79}},{"id":"ms-052","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a driver is convicted of reckless driving three times within 12 months. What happens?","o":["Only a written warning","A required safe-driving video","The license is revoked for one year","Nothing, if the fines are paid"],"h1":"The Commissioner must take the license away.","h2":"In Mississippi, three reckless driving convictions within 12 months mean the license is revoked for one year.","p":"Right. Three reckless driving convictions in a year mean a one-year revocation."},"es":{"q":"En Mississippi, un conductor es declarado culpable de manejo imprudente tres veces en 12 meses. ¿Qué pasa?","o":["Solo recibe una advertencia por escrito","Debe ver un video de manejo seguro","Se le revoca la licencia por un año","Nada, si paga las multas"],"h1":"El Comisionado debe quitarle la licencia.","h2":"En Mississippi, tres condenas por manejo imprudente en 12 meses significan que la licencia se revoca por un año.","p":"Correcto. Tres condenas por manejo imprudente en un año significan una revocación de un año."},"zh":{"q":"在 Mississippi，一位司机在 12 个月内三次因鲁莽驾驶被定罪。会发生什么？","o":["只给书面警告","必须看安全驾驶视频","驾照被吊销一年","只要交了罚款，就什么都不会发生"],"h1":"局长（Commissioner）必须收回驾照。","h2":"在 Mississippi，12 个月内三次鲁莽驾驶定罪，驾照会被吊销一年。","p":"对。一年内三次鲁莽驾驶定罪，驾照吊销一年。"},"vi":{"q":"Ở Mississippi, một người lái xe bị kết án lái xe liều lĩnh ba lần trong vòng 12 tháng. Chuyện gì xảy ra?","o":["Chỉ bị cảnh cáo bằng văn bản","Bắt buộc xem video lái xe an toàn","Bằng lái bị thu hồi một năm","Không có gì, nếu đã nộp tiền phạt"],"h1":"Ủy viên (Commissioner) phải lấy lại bằng lái.","h2":"Ở Mississippi, ba lần bị kết án lái xe liều lĩnh trong vòng 12 tháng nghĩa là bằng lái bị thu hồi một năm.","p":"Đúng. Ba lần bị kết án lái xe liều lĩnh trong một năm nghĩa là bị thu hồi bằng lái một năm."},"tl":{"q":"Sa Mississippi, nahatulan ang isang driver sa reckless driving nang tatlong beses sa loob ng 12 buwan. Ano ang mangyayari?","o":["Nakasulat na babala lang","Isang video tungkol sa ligtas na pagmamaneho na kailangang panoorin","Babawiin ang license nang isang taon","Wala, kung nabayaran ang mga multa"],"h1":"Kailangang bawiin ng Commissioner ang license.","h2":"Sa Mississippi, ang tatlong conviction sa reckless driving sa loob ng 12 buwan ay nangangahulugang babawiin ang license nang isang taon.","p":"Tama. Ang tatlong conviction sa reckless driving sa loob ng isang taon ay nangangahulugang babawiin ang license nang isang taon."},"ar":{"q":"في Mississippi، أُدين سائق بالقيادة المتهورة ثلاث مرات خلال 12 شهرًا. ماذا يحدث؟","o":["إنذار مكتوب فقط","فيديو إلزامي عن القيادة الآمنة","تُلغى الرخصة لمدة سنة واحدة","لا شيء، إذا دُفعت الغرامات"],"h1":"يجب على المفوض (Commissioner) أن يسحب الرخصة.","h2":"في Mississippi، ثلاث إدانات بالقيادة المتهورة خلال 12 شهرًا تعني إلغاء الرخصة لمدة سنة واحدة.","p":"صحيح. ثلاث إدانات بالقيادة المتهورة خلال سنة تعني إلغاء الرخصة لمدة سنة واحدة."},"ref":{"doc":"MS","page":80}},{"id":"ms-053","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, an at-fault driver had no liability insurance at the time of a crash. For how long must the driver keep proof of insurance on file?","o":["Three years from the crash","Six months from the crash","Until the next renewal","Ten years from the crash"],"h1":"It is longer than one year but less than five.","h2":"In Mississippi, an at-fault driver who had no liability insurance must buy it and keep proof on file for three years from the date of the crash.","p":"Right. The proof of insurance must stay in effect for three years."},"es":{"q":"En Mississippi, un conductor culpable de un choque no tenía seguro de responsabilidad civil en ese momento. ¿Por cuánto tiempo debe mantener registrada la prueba de seguro?","o":["Tres años desde el choque","Seis meses desde el choque","Hasta la próxima renovación","Diez años desde el choque"],"h1":"Es más de un año pero menos de cinco.","h2":"En Mississippi, un conductor culpable que no tenía seguro de responsabilidad civil debe comprarlo y mantener registrada la prueba por tres años desde la fecha del choque.","p":"Correcto. La prueba de seguro debe estar vigente por tres años."},"zh":{"q":"在 Mississippi，一位有过错的司机在事故发生时没有责任保险。这位司机必须把保险证明存档多久？","o":["从事故起三年","从事故起六个月","直到下次续期","从事故起十年"],"h1":"它比一年长，但少于五年。","h2":"在 Mississippi，没有责任保险的过错司机必须买保险，并从事故当天起把保险证明存档三年。","p":"对。保险证明必须保持有效三年。"},"vi":{"q":"Ở Mississippi, một người lái xe có lỗi không có bảo hiểm trách nhiệm lúc xảy ra tai nạn. Người lái xe đó phải lưu giữ bằng chứng bảo hiểm trong hồ sơ bao lâu?","o":["Ba năm kể từ tai nạn","Sáu tháng kể từ tai nạn","Cho đến lần gia hạn tới","Mười năm kể từ tai nạn"],"h1":"Thời gian này dài hơn một năm nhưng ít hơn năm năm.","h2":"Ở Mississippi, người lái xe có lỗi mà không có bảo hiểm trách nhiệm phải mua bảo hiểm và lưu giữ bằng chứng trong hồ sơ trong ba năm kể từ ngày xảy ra tai nạn.","p":"Đúng. Bằng chứng bảo hiểm phải còn hiệu lực trong ba năm."},"tl":{"q":"Sa Mississippi, walang liability insurance ang isang driver na may kasalanan noong nangyari ang banggaan. Gaano katagal dapat nakatala ang patunay ng insurance ng driver?","o":["Tatlong taon mula sa banggaan","Anim na buwan mula sa banggaan","Hanggang sa susunod na renewal","Sampung taon mula sa banggaan"],"h1":"Mas mahaba ito sa isang taon pero kulang sa lima.","h2":"Sa Mississippi, ang driver na may kasalanan na walang liability insurance ay dapat bumili nito at panatilihing nakatala ang patunay nang tatlong taon mula sa petsa ng banggaan.","p":"Tama. Dapat may bisa ang patunay ng insurance nang tatlong taon."},"ar":{"q":"في Mississippi، لم يكن لدى سائق مخطئ تأمين المسؤولية وقت وقوع الحادث. كم مدة يجب أن يُبقي السائق إثبات التأمين في الملف؟","o":["ثلاث سنوات من تاريخ الحادث","ستة أشهر من تاريخ الحادث","حتى التجديد القادم","عشر سنوات من تاريخ الحادث"],"h1":"إنها أطول من سنة واحدة لكنها أقل من خمس سنوات.","h2":"في Mississippi، يجب على السائق المخطئ الذي لم يكن لديه تأمين المسؤولية أن يشتريه وأن يُبقي إثباته في الملف لمدة ثلاث سنوات من تاريخ الحادث.","p":"صحيح. يجب أن يبقى إثبات التأمين ساريًا لمدة ثلاث سنوات."},"ref":{"doc":"MS","page":76}},{"id":"ms-054","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, you see an emergency on a highway. What can you dial on a cell phone to reach a Highway Patrol dispatcher?","o":["*311","*411","*511","*HP (*47)"],"h1":"The letters stand for Highway Patrol.","h2":"In Mississippi, you can dial *HP (*47) on a cell phone to reach a Highway Patrol dispatcher for a real emergency.","p":"Right. Dial *HP, which is *47, for the Highway Patrol."},"es":{"q":"En Mississippi, usted ve una emergencia en una carretera. ¿Qué número puede marcar en un celular para hablar con un despachador de la Patrulla de Carreteras?","o":["*311","*411","*511","*HP (*47)"],"h1":"Las letras significan Highway Patrol (Patrulla de Carreteras).","h2":"En Mississippi, puede marcar *HP (*47) en un celular para hablar con un despachador de la Patrulla de Carreteras en una emergencia real.","p":"Correcto. Marque *HP, que es *47, para la Patrulla de Carreteras."},"zh":{"q":"在 Mississippi，你在公路上看到紧急情况。你可以用手机拨什么号码联系公路巡警（Highway Patrol）调度员？","o":["*311","*411","*511","*HP (*47)"],"h1":"这些字母代表 Highway Patrol。","h2":"在 Mississippi，遇到真正的紧急情况时，你可以用手机拨 *HP (*47) 联系公路巡警调度员。","p":"对。拨 *HP，也就是 *47，联系公路巡警。"},"vi":{"q":"Ở Mississippi, bạn thấy một trường hợp khẩn cấp trên xa lộ. Bạn có thể bấm số nào trên điện thoại di động để gọi nhân viên điều phối của Highway Patrol?","o":["*311","*411","*511","*HP (*47)"],"h1":"Các chữ cái này là viết tắt của Highway Patrol.","h2":"Ở Mississippi, bạn có thể bấm *HP (*47) trên điện thoại di động để gọi nhân viên điều phối của Highway Patrol khi có trường hợp khẩn cấp thật sự.","p":"Đúng. Bấm *HP, tức là *47, để gọi Highway Patrol."},"tl":{"q":"Sa Mississippi, may nakita kang emergency sa highway. Ano ang puwede mong i-dial sa cell phone para makausap ang dispatcher ng Highway Patrol?","o":["*311","*411","*511","*HP (*47)"],"h1":"Ang mga letra ay para sa Highway Patrol.","h2":"Sa Mississippi, puwede mong i-dial ang *HP (*47) sa cell phone para makausap ang dispatcher ng Highway Patrol sa tunay na emergency.","p":"Tama. I-dial ang *HP, na *47, para sa Highway Patrol."},"ar":{"q":"في Mississippi، رأيت حالة طوارئ على طريق سريع. ما الرقم الذي يمكنك الاتصال به من الهاتف المحمول للوصول إلى موظف إرسال دوريات الطرق السريعة (Highway Patrol)؟","o":["*311","*411","*511","*HP (*47)"],"h1":"الحرفان يرمزان إلى Highway Patrol.","h2":"في Mississippi، يمكنك الاتصال بالرقم *HP (*47) من الهاتف المحمول للوصول إلى موظف إرسال دوريات الطرق السريعة في حالة طوارئ حقيقية.","p":"صحيح. اتصل بالرقم *HP، وهو *47، للوصول إلى دوريات الطرق السريعة."},"ref":{"doc":"MS","page":66}},{"id":"ms-055","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, which vehicle must always stop at every railroad crossing, even with no lights or gates?","o":["A pickup truck towing a boat","A school bus carrying even one child","A motorcycle with a passenger","Any car after dark"],"h1":"Think of vehicles that carry children, paying passengers or dangerous cargo.","h2":"In Mississippi, a school bus with even one child, a vehicle for hire with passengers, and a vehicle carrying explosives or flammable liquids must stop at every railroad crossing.","p":"Right. A school bus with any child on board must always stop."},"es":{"q":"En Mississippi, ¿qué vehículo siempre debe detenerse en todos los cruces de ferrocarril, aunque no haya luces ni barreras?","o":["Una camioneta que remolca un bote","Un autobús escolar que lleva aunque sea un niño","Una motocicleta con un pasajero","Cualquier carro de noche"],"h1":"Piense en vehículos que llevan niños, pasajeros que pagan o carga peligrosa.","h2":"En Mississippi, un autobús escolar con aunque sea un niño, un vehículo de alquiler con pasajeros y un vehículo que lleva explosivos o líquidos inflamables deben detenerse en todos los cruces de ferrocarril.","p":"Correcto. Un autobús escolar con cualquier niño a bordo siempre debe detenerse."},"zh":{"q":"在 Mississippi，哪种车辆必须在每个铁路道口都停车，即使没有灯或栏杆？","o":["拖着船的皮卡车","载着哪怕只有一个孩子的校车","载着乘客的摩托车","天黑后的任何汽车"],"h1":"想想载孩子、付费乘客或危险货物的车辆。","h2":"在 Mississippi，载着哪怕只有一个孩子的校车、载有乘客的营业车辆，以及运送爆炸物或易燃液体的车辆，都必须在每个铁路道口停车。","p":"对。只要车上有孩子，校车就必须停车。"},"vi":{"q":"Ở Mississippi, loại xe nào phải luôn dừng lại ở mọi chỗ giao với đường sắt, kể cả khi không có đèn hay thanh chắn?","o":["Xe bán tải kéo một chiếc thuyền","Xe buýt trường học chở dù chỉ một em nhỏ","Xe máy có chở người ngồi sau","Bất kỳ xe hơi nào sau khi trời tối"],"h1":"Hãy nghĩ đến những xe chở trẻ em, hành khách trả tiền hoặc hàng nguy hiểm.","h2":"Ở Mississippi, xe buýt trường học chở dù chỉ một em nhỏ, xe chở khách thuê có hành khách, và xe chở chất nổ hoặc chất lỏng dễ cháy phải dừng lại ở mọi chỗ giao với đường sắt.","p":"Đúng. Xe buýt trường học có bất kỳ em nhỏ nào trên xe phải luôn dừng lại."},"tl":{"q":"Sa Mississippi, aling sasakyan ang dapat laging huminto sa bawat railroad crossing, kahit walang ilaw o harang?","o":["Pickup truck na humihila ng bangka","School bus na may sakay kahit isang bata lang","Motorsiklo na may angkas","Anumang kotse kapag madilim na"],"h1":"Isipin ang mga sasakyang may sakay na mga bata, nagbabayad na pasahero o mapanganib na kargamento.","h2":"Sa Mississippi, ang school bus na may sakay kahit isang bata, ang sasakyang pinauupahan na may mga pasahero, at ang sasakyang may kargang pampasabog o likidong madaling magliyab ay dapat huminto sa bawat railroad crossing.","p":"Tama. Dapat laging huminto ang school bus na may sakay na kahit isang bata."},"ar":{"q":"في Mississippi، أي مركبة يجب أن تتوقف دائمًا عند كل معبر سكة حديد، حتى إذا لم تكن هناك أضواء أو حواجز؟","o":["شاحنة صغيرة (pickup) تسحب قاربًا","حافلة مدرسية تحمل ولو طفلًا واحدًا","دراجة نارية عليها راكب","أي سيارة بعد حلول الظلام"],"h1":"فكّر في المركبات التي تنقل أطفالًا أو ركابًا يدفعون الأجرة أو حمولة خطرة.","h2":"في Mississippi، يجب على الحافلة المدرسية التي تحمل ولو طفلًا واحدًا، والمركبة المؤجّرة التي تحمل ركابًا، والمركبة التي تنقل متفجرات أو سوائل قابلة للاشتعال أن تتوقف عند كل معبر سكة حديد.","p":"صحيح. يجب أن تتوقف الحافلة المدرسية دائمًا إذا كان فيها أي طفل."},"ref":{"doc":"MS","page":35}},{"id":"ms-056","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a car has aftermarket window tint. How much light must all the windows let through?","o":["At least 5 percent","At least 10 percent","At least 28 percent","At least 90 percent"],"h1":"It is a little more than one quarter of the light.","h2":"In Mississippi, all windows must let through at least 28 percent of light, and aftermarket tint needs an inspection certificate and decal.","p":"Right. Windows must let through at least 28 percent of light."},"es":{"q":"En Mississippi, un carro tiene polarizado de ventanas instalado después de la compra. ¿Cuánta luz deben dejar pasar todas las ventanas?","o":["Por lo menos 5 por ciento","Por lo menos 10 por ciento","Por lo menos 28 por ciento","Por lo menos 90 por ciento"],"h1":"Es un poco más de la cuarta parte de la luz.","h2":"En Mississippi, todas las ventanas deben dejar pasar por lo menos el 28 por ciento de la luz, y el polarizado instalado después de la compra necesita un certificado de inspección y una calcomanía.","p":"Correcto. Las ventanas deben dejar pasar por lo menos el 28 por ciento de la luz."},"zh":{"q":"在 Mississippi，一辆车贴了后装的车窗膜。所有车窗必须透过多少光？","o":["至少 5%","至少 10%","至少 28%","至少 90%"],"h1":"它比四分之一的光多一点。","h2":"在 Mississippi，所有车窗必须透过至少 28% 的光，而且后装的车窗膜需要检验证书和贴纸。","p":"对。车窗必须透过至少 28% 的光。"},"vi":{"q":"Ở Mississippi, một chiếc xe có dán phim cửa kính loại gắn thêm sau khi mua (aftermarket). Tất cả cửa kính phải cho bao nhiêu ánh sáng đi qua?","o":["Ít nhất 5 phần trăm","Ít nhất 10 phần trăm","Ít nhất 28 phần trăm","Ít nhất 90 phần trăm"],"h1":"Nhiều hơn một phần tư lượng ánh sáng một chút.","h2":"Ở Mississippi, tất cả cửa kính phải cho ít nhất 28 phần trăm ánh sáng đi qua, và phim dán gắn thêm cần có giấy chứng nhận kiểm định và nhãn dán.","p":"Đúng. Cửa kính phải cho ít nhất 28 phần trăm ánh sáng đi qua."},"tl":{"q":"Sa Mississippi, may aftermarket na window tint ang isang kotse. Gaano karaming liwanag ang dapat pinapadaan ng lahat ng bintana?","o":["Hindi bababa sa 5 porsiyento","Hindi bababa sa 10 porsiyento","Hindi bababa sa 28 porsiyento","Hindi bababa sa 90 porsiyento"],"h1":"Medyo higit ito sa ikaapat na bahagi ng liwanag.","h2":"Sa Mississippi, dapat magpadaan ang lahat ng bintana ng hindi bababa sa 28 porsiyento ng liwanag, at kailangan ng aftermarket tint ng inspection certificate at decal.","p":"Tama. Dapat magpadaan ang mga bintana ng hindi bababa sa 28 porsiyento ng liwanag."},"ar":{"q":"في Mississippi، على نوافذ سيارة تظليل مُضاف بعد الشراء (aftermarket). كم من الضوء يجب أن تسمح جميع النوافذ بمروره؟","o":["5 في المئة على الأقل","10 في المئة على الأقل","28 في المئة على الأقل","90 في المئة على الأقل"],"h1":"إنها أكثر قليلًا من ربع الضوء.","h2":"في Mississippi، يجب أن تسمح جميع النوافذ بمرور 28 في المئة من الضوء على الأقل، ويحتاج التظليل المُضاف بعد الشراء إلى شهادة فحص وملصق.","p":"صحيح. يجب أن تسمح النوافذ بمرور 28 في المئة من الضوء على الأقل."},"ref":{"doc":"MS","page":75}},{"id":"ms-057","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, how much does a learner's permit cost?","o":["$7","$11","$17","$24"],"h1":"Of these four choices, it is the lowest price.","h2":"In Mississippi, a learner's permit costs $7.","p":"Right. A learner's permit costs $7."},"es":{"q":"En Mississippi, ¿cuánto cuesta un permiso de aprendiz?","o":["$7","$11","$17","$24"],"h1":"De estas cuatro opciones, es el precio más bajo.","h2":"En Mississippi, un permiso de aprendiz cuesta $7.","p":"Correcto. El permiso de aprendiz cuesta $7."},"ref":{"doc":"MS","page":6}},{"id":"ms-058","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, how much does a 4-year regular driver's license (Class R) cost?","o":["$7","$11","$17","$24"],"h1":"It is a little more than half the price of the 8-year license.","h2":"In Mississippi, a 4-year regular driver's license (Class R) costs $24.","p":"Right. The 4-year Class R license costs $24."},"es":{"q":"En Mississippi, ¿cuánto cuesta una licencia de conducir regular (Clase R) de 4 años?","o":["$7","$11","$17","$24"],"h1":"Cuesta un poco más de la mitad de la licencia de 8 años.","h2":"En Mississippi, una licencia de conducir regular (Clase R) de 4 años cuesta $24.","p":"Correcto. La licencia Clase R de 4 años cuesta $24."},"ref":{"doc":"MS","page":6}},{"id":"ms-059","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a driver under 21 gets a regular Class R license. For how many years is it issued?","o":["2 years","4 years","6 years","8 years"],"h1":"The longer license option is not listed for drivers under 21.","h2":"In Mississippi, a driver under 21 gets the 4-year Class R license; the 8-year option is for older drivers.","p":"Right. Drivers under 21 get a 4-year license."},"es":{"q":"En Mississippi, un conductor menor de 21 años obtiene una licencia regular Clase R. ¿Por cuántos años se emite?","o":["2 años","4 años","6 años","8 años"],"h1":"La opción más larga no aparece para menores de 21 años.","h2":"En Mississippi, un conductor menor de 21 años recibe la licencia Clase R de 4 años; la opción de 8 años es para conductores mayores.","p":"Correcto. Los menores de 21 años reciben una licencia de 4 años."},"ref":{"doc":"MS","page":6}},{"id":"ms-060","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, how much does a duplicate driver's license cost?","o":["$1","$5","$11","$24"],"h1":"It costs a little more than ten dollars.","h2":"In Mississippi, a duplicate driver's license costs $11.","p":"Right. A duplicate license costs $11."},"es":{"q":"En Mississippi, ¿cuánto cuesta un duplicado de la licencia de conducir?","o":["$1","$5","$11","$24"],"h1":"Cuesta un poco más de diez dólares.","h2":"En Mississippi, un duplicado de la licencia de conducir cuesta $11.","p":"Correcto. Un duplicado cuesta $11."},"ref":{"doc":"MS","page":6}},{"id":"ms-061","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, how much does a 4-year identification card cost?","o":["$11","$17","$24","$33"],"h1":"It costs less than a 4-year driver's license.","h2":"In Mississippi, a 4-year identification card costs $17.","p":"Right. A 4-year ID card costs $17."},"es":{"q":"En Mississippi, ¿cuánto cuesta una tarjeta de identificación de 4 años?","o":["$11","$17","$24","$33"],"h1":"Cuesta menos que una licencia de conducir de 4 años.","h2":"En Mississippi, una tarjeta de identificación de 4 años cuesta $17.","p":"Correcto. La tarjeta de identificación de 4 años cuesta $17."},"ref":{"doc":"MS","page":6}},{"id":"ms-062","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, how much does a 4-year motorcycle endorsement cost?","o":["$5","$10","$17","$29"],"h1":"It is added to your license and costs only a few dollars.","h2":"In Mississippi, a 4-year motorcycle endorsement costs $5.","p":"Right. A 4-year motorcycle endorsement costs $5."},"es":{"q":"En Mississippi, ¿cuánto cuesta un endoso de motocicleta de 4 años?","o":["$5","$10","$17","$29"],"h1":"Se agrega a su licencia y cuesta solo unos pocos dólares.","h2":"En Mississippi, un endoso de motocicleta de 4 años cuesta $5.","p":"Correcto. El endoso de motocicleta de 4 años cuesta $5."},"ref":{"doc":"MS","page":6}},{"id":"ms-063","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, how can you pay a fee at a driver's license office?","o":["Only by personal check","By check or money order","Only in cash","By cash, or a Visa or MasterCard credit or debit card"],"h1":"The offices do not take checks.","h2":"In Mississippi, driver's license offices take cash and Visa or MasterCard credit or debit cards, but no checks.","p":"Right. Cash or a Visa or MasterCard card, and no checks."},"es":{"q":"En Mississippi, ¿cómo puede pagar una tarifa en una oficina de licencias de conducir?","o":["Solo con cheque personal","Con cheque o giro postal","Solo en efectivo","En efectivo, o con tarjeta de crédito o débito Visa o MasterCard"],"h1":"Las oficinas no aceptan cheques.","h2":"En Mississippi, las oficinas de licencias aceptan efectivo y tarjetas de crédito o débito Visa o MasterCard, pero no cheques.","p":"Correcto. Efectivo o tarjeta Visa o MasterCard, y no cheques."},"ref":{"doc":"MS","page":6}},{"id":"ms-064","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you have no license or permit. Your parent, a licensed driver, offers to ride with you. May you drive?","o":["Yes, on any road","Yes, but only in daylight","No, driving without a license or permit is illegal","Yes, but only on city streets"],"h1":"Having a licensed adult along does not replace your own permit or license.","h2":"In Mississippi, driving without a valid license or learner's permit is illegal, even with a parent or licensed driver in the car.","p":"Right. You need your own license or permit."},"es":{"q":"En Mississippi, usted no tiene licencia ni permiso. Su padre, que tiene licencia, se ofrece a acompañarlo. ¿Puede manejar?","o":["Sí, en cualquier camino","Sí, pero solo de día","No, manejar sin licencia ni permiso es ilegal","Sí, pero solo en calles de la ciudad"],"h1":"Ir con un adulto con licencia no reemplaza su propio permiso o licencia.","h2":"En Mississippi, manejar sin una licencia o permiso de aprendiz válido es ilegal, aunque vaya con un padre o un conductor con licencia.","p":"Correcto. Usted necesita su propia licencia o permiso."},"ref":{"doc":"MS","page":10}},{"id":"ms-065","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, who may drive without a Mississippi driver's license?","o":["A new resident during the first year","A visitor over 16 with a valid license from their home state","Anyone driving only on country roads","A 15-year-old with a parent's note"],"h1":"Think of someone who does not live in Mississippi.","h2":"In Mississippi, a non-resident over 16 who carries a valid license from their home state or country does not need a Mississippi license.","p":"Right. A visitor over 16 with a valid home license may drive."},"es":{"q":"En Mississippi, ¿quién puede manejar sin una licencia de conducir de Mississippi?","o":["Un nuevo residente durante el primer año","Un visitante mayor de 16 años con licencia válida de su estado","Cualquiera que maneje solo en caminos rurales","Un joven de 15 años con una nota de sus padres"],"h1":"Piense en alguien que no vive en Mississippi.","h2":"En Mississippi, un no residente mayor de 16 años que lleva una licencia válida de su estado o país no necesita licencia de Mississippi.","p":"Correcto. Un visitante mayor de 16 años con licencia válida de su lugar de origen puede manejar."},"ref":{"doc":"MS","page":10}},{"id":"ms-066","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a new rule starts on July 1, 2027. What will new drivers need to get a regular license?","o":["Proof that they finished a certified driver's education course","A road test with a police officer","A second written test","A year of insurance in their own name"],"h1":"It is a course, not a test.","h2":"In Mississippi, starting July 1, 2027, you must show that you finished a certified driver's education course to get a regular license.","p":"Right. A certified driver's education course will be required."},"es":{"q":"En Mississippi, una nueva regla empieza el 1 de julio de 2027. ¿Qué necesitarán los nuevos conductores para obtener una licencia regular?","o":["Prueba de haber terminado un curso certificado de educación vial","Un examen de manejo con un policía","Un segundo examen escrito","Un año de seguro a su propio nombre"],"h1":"Es un curso, no un examen.","h2":"En Mississippi, a partir del 1 de julio de 2027, usted debe mostrar que terminó un curso certificado de educación vial para obtener una licencia regular.","p":"Correcto. Se exigirá un curso certificado de educación vial."},"ref":{"doc":"MS","page":10}},{"id":"ms-067","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you just moved here with your car. How soon must you get a Mississippi license plate?","o":["Within 10 days","Within 15 days","Within 30 days","Within 90 days"],"h1":"It is sooner than the 60 days you have for your driver's license.","h2":"In Mississippi, a new resident must get a Mississippi license plate within 30 days.","p":"Right. You must get a Mississippi plate within 30 days."},"es":{"q":"En Mississippi, usted acaba de mudarse con su carro. ¿En cuánto tiempo debe obtener una placa de Mississippi?","o":["En 10 días","En 15 días","En 30 días","En 90 días"],"h1":"Es antes de los 60 días que tiene para la licencia de conducir.","h2":"En Mississippi, un nuevo residente debe obtener una placa de Mississippi en un plazo de 30 días.","p":"Correcto. Debe obtener la placa de Mississippi en 30 días."},"ref":{"doc":"MS","page":11}},{"id":"ms-068","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, you apply for a license, but you lost your out-of-state license. What must you get?","o":["A police report","A letter from your old state's governor","A copy of your car title","An Affidavit of Inability to Surrender, signed before a notary"],"h1":"It is a form from the driver's license office, and your signature must be notarized.","h2":"In Mississippi, if you lost your out-of-state license, you must get an Affidavit of Inability to Surrender form and have your signature notarized.","p":"Right. You need a notarized Affidavit of Inability to Surrender."},"es":{"q":"En Mississippi, usted solicita una licencia, pero perdió la licencia de su otro estado. ¿Qué debe obtener?","o":["Un informe de la policía","Una carta del gobernador de su antiguo estado","Una copia del título de su carro","Una Declaración Jurada de Imposibilidad de Entregar (Affidavit of Inability to Surrender), firmada ante notario"],"h1":"Es un formulario de la oficina de licencias, y su firma debe estar notariada.","h2":"En Mississippi, si perdió su licencia de otro estado, debe obtener el formulario Affidavit of Inability to Surrender y notariar su firma.","p":"Correcto. Necesita la declaración jurada notariada."},"ref":{"doc":"MS","page":11}},{"id":"ms-069","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you move here with a valid license from another state. Which test must you still pass?","o":["A vision screening","The computerized knowledge exam","A road skills test","A first aid test"],"h1":"The written exam is waived for you.","h2":"In Mississippi, a driver with a valid out-of-state license skips the computerized exam but must pass a vision screening.","p":"Right. You still need a vision screening."},"es":{"q":"En Mississippi, usted se muda aquí con una licencia válida de otro estado. ¿Qué prueba debe aprobar todavía?","o":["Un examen de la vista","El examen computarizado de conocimientos","Un examen práctico de manejo","Un examen de primeros auxilios"],"h1":"A usted se le exonera el examen escrito.","h2":"En Mississippi, un conductor con licencia válida de otro estado no toma el examen computarizado, pero debe aprobar un examen de la vista.","p":"Correcto. Todavía necesita el examen de la vista."},"ref":{"doc":"MS","page":11}},{"id":"ms-070","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, which documents does every out-of-state driver's license application need?","o":["Only your old license","A certified birth certificate, your Social Security card and two proofs of residency","A passport and a utility bill","A car title and an insurance card"],"h1":"There are three kinds of papers: one for birth, one for your Social Security number and two for where you live.","h2":"In Mississippi, an out-of-state license application needs a certified birth certificate, your original Social Security card or print-out, and two proofs of residency.","p":"Right. Birth certificate, Social Security card and two proofs of residency."},"es":{"q":"En Mississippi, ¿qué documentos necesita toda solicitud de licencia de una persona que viene de otro estado?","o":["Solo su licencia anterior","Un acta de nacimiento certificada, su tarjeta del Seguro Social y dos pruebas de residencia","Un pasaporte y una factura de servicios","El título del carro y la tarjeta de seguro"],"h1":"Son tres tipos de papeles: uno de nacimiento, uno de su número de Seguro Social y dos de dónde vive.","h2":"En Mississippi, una solicitud de licencia de otro estado necesita un acta de nacimiento certificada, su tarjeta original del Seguro Social o una impresión, y dos pruebas de residencia.","p":"Correcto. Acta de nacimiento, tarjeta del Seguro Social y dos pruebas de residencia."},"ref":{"doc":"MS","page":11}},{"id":"ms-071","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a soldier from another state is stationed here with family. May they drive with their home-state licenses?","o":["No, they need Mississippi licenses within 30 days","Only the soldier may drive","Yes, if the licenses are valid","Only on the military base"],"h1":"The handbook treats non-resident military families like visitors.","h2":"In Mississippi, non-resident military personnel and their families may drive with valid driver's licenses from another state.","p":"Right. They may drive with valid out-of-state licenses."},"es":{"q":"En Mississippi, un soldado de otro estado está destinado aquí con su familia. ¿Pueden manejar con las licencias de su estado?","o":["No, necesitan licencias de Mississippi en 30 días","Solo el soldado puede manejar","Sí, si las licencias son válidas","Solo dentro de la base militar"],"h1":"El manual trata a las familias militares no residentes como visitantes.","h2":"En Mississippi, el personal militar no residente y sus familias pueden manejar con licencias válidas de otro estado.","p":"Correcto. Pueden manejar con licencias válidas de otro estado."},"ref":{"doc":"MS","page":12}},{"id":"ms-072","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, your license expired while you were out of state on military service. How long after discharge or returning do you have to renew it?","o":["30 days","45 days","60 days","90 days"],"h1":"It is about three months.","h2":"In Mississippi, you may renew a license that expired during military service within 90 days of discharge or of returning to the state.","p":"Right. You have 90 days."},"es":{"q":"En Mississippi, su licencia venció mientras usted estaba fuera del estado en servicio militar. ¿Cuánto tiempo tiene después de la baja o de regresar para renovarla?","o":["30 días","45 días","60 días","90 días"],"h1":"Son unos tres meses.","h2":"En Mississippi, usted puede renovar una licencia que venció durante el servicio militar dentro de los 90 días después de la baja o de regresar al estado.","p":"Correcto. Tiene 90 días."},"ref":{"doc":"MS","page":12}},{"id":"ms-073","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you renew a license that expired during your military service, within the time allowed. Do you pay a late (delinquent) fee?","o":["No, a delinquent fee is not required","Yes, $1 for each month","Yes, double the normal fee","Yes, $25"],"h1":"The law does not punish service members for being away.","h2":"In Mississippi, a service member who renews within 90 days of discharge or return does not pay a delinquent fee.","p":"Right. No delinquent fee is required."},"es":{"q":"En Mississippi, usted renueva dentro del plazo una licencia que venció durante su servicio militar. ¿Paga un recargo por atraso?","o":["No, no se exige recargo por atraso","Sí, $1 por cada mes","Sí, el doble de la tarifa normal","Sí, $25"],"h1":"La ley no castiga a los militares por estar fuera.","h2":"En Mississippi, un militar que renueva dentro de los 90 días después de la baja o del regreso no paga recargo por atraso.","p":"Correcto. No se exige recargo por atraso."},"ref":{"doc":"MS","page":12}},{"id":"ms-074","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a non-citizen's legal stay ends in two years. How long is the regular license valid?","o":["Four years anyway","Until the legal stay ends, two years","One year","Eight years"],"h1":"The license cannot outlast the legal status.","h2":"In Mississippi, a non-citizen's license is valid for four years or until the legal status ends, whichever comes first.","p":"Right. It lasts only until the legal stay ends."},"es":{"q":"En Mississippi, la estadía legal de una persona no ciudadana termina en dos años. ¿Por cuánto tiempo es válida su licencia regular?","o":["Cuatro años de todos modos","Hasta que termine la estadía legal, dos años","Un año","Ocho años"],"h1":"La licencia no puede durar más que el estatus legal.","h2":"En Mississippi, la licencia de una persona no ciudadana vale por cuatro años o hasta que termine su estatus legal, lo que ocurra primero.","p":"Correcto. Dura solo hasta que termina la estadía legal."},"ref":{"doc":"MS","page":12}},{"id":"ms-075","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a non-citizen's license is valid for less than four years because of their legal status. What fee do they pay?","o":["Half the fee","A fee for each year","The standard license fee","No fee"],"h1":"The length of the license does not change the price.","h2":"In Mississippi, a non-citizen pays the standard license fee, no matter how long the license is valid.","p":"Right. The standard fee applies."},"es":{"q":"En Mississippi, la licencia de una persona no ciudadana vale menos de cuatro años por su estatus legal. ¿Qué tarifa paga?","o":["La mitad de la tarifa","Una tarifa por cada año","La tarifa normal de la licencia","Ninguna tarifa"],"h1":"La duración de la licencia no cambia el precio.","h2":"En Mississippi, una persona no ciudadana paga la tarifa normal de la licencia, sin importar cuánto tiempo sea válida.","p":"Correcto. Se aplica la tarifa normal."},"ref":{"doc":"MS","page":12}},{"id":"ms-076","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, which test must you pass to get a regular learner's permit?","o":["A shorter test just for permits","Only a vision test","A road skills test","The same computerized exam used for a regular license"],"h1":"There is not a separate, easier test for the permit.","h2":"In Mississippi, you must pass the same computerized exam required for a regular driver's license to get a learner's permit.","p":"Right. It is the same computerized exam as for a license."},"es":{"q":"En Mississippi, ¿qué examen debe aprobar para obtener un permiso de aprendiz regular?","o":["Un examen más corto solo para permisos","Solo un examen de la vista","Un examen práctico de manejo","El mismo examen computarizado que se usa para la licencia regular"],"h1":"No hay un examen aparte y más fácil para el permiso.","h2":"En Mississippi, para obtener un permiso de aprendiz debe aprobar el mismo examen computarizado que se exige para la licencia de conducir regular.","p":"Correcto. Es el mismo examen computarizado que para la licencia."},"ref":{"doc":"MS","page":13}},{"id":"ms-077","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, when do you need a Class D license?","o":["To drive any car after age 21","To drive a vehicle commercially that weighs under 26,000 pounds","To drive a motorcycle","To drive a school bus"],"h1":"Class D is for work driving in lighter vehicles.","h2":"In Mississippi, a Class D license is required to drive a vehicle commercially when its gross vehicle weight rating is under 26,000 pounds.","p":"Right. Class D is for commercial driving under 26,000 pounds."},"es":{"q":"En Mississippi, ¿cuándo necesita una licencia Clase D?","o":["Para manejar cualquier carro después de los 21 años","Para manejar comercialmente un vehículo de menos de 26,000 libras","Para manejar una motocicleta","Para manejar un autobús escolar"],"h1":"La Clase D es para manejar por trabajo en vehículos más livianos.","h2":"En Mississippi, se necesita una licencia Clase D para manejar un vehículo comercialmente cuando su peso bruto nominal es menor de 26,000 libras.","p":"Correcto. La Clase D es para manejo comercial de menos de 26,000 libras."},"ref":{"doc":"MS","page":14}},{"id":"ms-078","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you drive a pick-up truck for your business. When would you need a commercial license?","o":["Only when it carries hazardous materials that need a placard","Whenever it is used for work","When it carries more than one passenger","When you drive it at night"],"h1":"A pick-up truck alone does not require one, whatever the use.","h2":"In Mississippi, you do not need a commercial license for a pick-up truck, whatever it is used for, unless it carries enough hazardous materials to need a placard.","p":"Right. Only placarded hazardous materials make the difference."},"es":{"q":"En Mississippi, usted maneja una camioneta pick-up para su negocio. ¿Cuándo necesitaría una licencia comercial?","o":["Solo cuando lleva materiales peligrosos que requieren un letrero (placard)","Siempre que se use para trabajar","Cuando lleva más de un pasajero","Cuando la maneja de noche"],"h1":"Una pick-up por sí sola no lo requiere, sin importar su uso.","h2":"En Mississippi, no necesita licencia comercial para una camioneta pick-up, sin importar su uso, a menos que lleve suficientes materiales peligrosos como para requerir un letrero (placard).","p":"Correcto. Solo los materiales peligrosos con letrero cambian la regla."},"ref":{"doc":"MS","page":14}},{"id":"ms-079","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, what is the youngest age to get a license to drive a school bus?","o":["16","18","21","25"],"h1":"It is the same age needed to supervise a learner.","h2":"In Mississippi, you must be at least 21 to get a license to drive a school bus.","p":"Right. You must be at least 21."},"es":{"q":"En Mississippi, ¿cuál es la edad mínima para obtener una licencia para manejar un autobús escolar?","o":["16","18","21","25"],"h1":"Es la misma edad que se necesita para acompañar a un aprendiz.","h2":"En Mississippi, usted debe tener al menos 21 años para obtener una licencia para manejar un autobús escolar.","p":"Correcto. Debe tener al menos 21 años."},"ref":{"doc":"MS","page":14}},{"id":"ms-080","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, what must you pass to get a motorcycle endorsement?","o":["Only a vision test","Only a written test","A safety class with no test","A computerized motorcycle test and a skills test"],"h1":"There are two parts: one on a computer and one on the motorcycle.","h2":"In Mississippi, you must pass a computerized test on motorcycle operation and a skills test to get a motorcycle endorsement.","p":"Right. A computerized test and a skills test."},"es":{"q":"En Mississippi, ¿qué debe aprobar para obtener un endoso de motocicleta?","o":["Solo un examen de la vista","Solo un examen escrito","Una clase de seguridad sin examen","Un examen computarizado de motocicleta y un examen práctico"],"h1":"Son dos partes: una en computadora y otra en la motocicleta.","h2":"En Mississippi, debe aprobar un examen computarizado sobre el manejo de motocicletas y un examen práctico para obtener el endoso de motocicleta.","p":"Correcto. Un examen computarizado y un examen práctico."},"ref":{"doc":"MS","page":14}},{"id":"ms-081","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, who must wear a crash helmet on a motorcycle or motor scooter on public roads?","o":["Only riders under 21","Everyone operating or riding on it","Only the operator","Only on highways over 55 mph"],"h1":"The law covers the person driving and anyone riding along.","h2":"In Mississippi, everyone operating or riding a motorcycle or motor scooter on public roads must wear a crash helmet.","p":"Right. Operators and passengers must wear helmets."},"es":{"q":"En Mississippi, ¿quién debe usar casco en una motocicleta o motoneta en vías públicas?","o":["Solo los menores de 21 años","Todos los que la manejan o van en ella","Solo quien la maneja","Solo en carreteras de más de 55 mph"],"h1":"La ley cubre a quien maneja y a cualquier persona que vaya en ella.","h2":"En Mississippi, todas las personas que manejan o van en una motocicleta o motoneta en vías públicas deben usar casco.","p":"Correcto. Conductores y pasajeros deben usar casco."},"ref":{"doc":"MS","page":14}},{"id":"ms-082","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you need eyeglasses to pass the vision exam. What happens to your license?","o":["Nothing changes","You must retake the exam every year","It is restricted, so you must wear them to drive","You can only drive in daylight"],"h1":"Your license will show a condition you must follow.","h2":"In Mississippi, if you need an aid such as eyeglasses to pass the exam, your license is restricted to driving with it.","p":"Right. Your license is restricted to wearing glasses."},"es":{"q":"En Mississippi, usted necesita anteojos para aprobar el examen de la vista. ¿Qué pasa con su licencia?","o":["No cambia nada","Debe repetir el examen cada año","Queda restringida, así que debe usarlos para manejar","Solo puede manejar de día"],"h1":"Su licencia mostrará una condición que debe cumplir.","h2":"En Mississippi, si necesita una ayuda como anteojos para aprobar el examen, su licencia queda restringida a manejar con ella.","p":"Correcto. Su licencia queda restringida al uso de anteojos."},"ref":{"doc":"MS","page":14}},{"id":"ms-083","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a teen gets a learner's permit at 15 and a half. At what age can the teen get a regular license?","o":["16","17","16 and 3 months","16 and a half"],"h1":"The permit must still be held for a full year.","h2":"In Mississippi, a teen who gets a permit at 15 and a half must hold it one year, so the teen can get a regular license at 16 and a half.","p":"Right. The teen can get a regular license at 16 and a half."},"es":{"q":"En Mississippi, un adolescente obtiene el permiso de aprendiz a los 15 años y medio. ¿A qué edad puede obtener la licencia regular?","o":["16","17","16 años y 3 meses","16 años y medio"],"h1":"Igual debe tener el permiso durante un año completo.","h2":"En Mississippi, un adolescente que obtiene el permiso a los 15 años y medio debe tenerlo un año, así que puede obtener la licencia regular a los 16 años y medio.","p":"Correcto. Puede obtener la licencia regular a los 16 años y medio."},"ref":{"doc":"MS","page":15}},{"id":"ms-084","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a 16-year-old applies for the first time. What does the teen receive?","o":["A regular license right away","A learner's permit","A motorcycle endorsement","A temporary license for six months"],"h1":"At 16, a first-time applicant starts with a permit, not a license.","h2":"In Mississippi, a teen who first applies at 16 is issued a learner's permit and can get a regular license at 17.","p":"Right. The teen gets a learner's permit first."},"es":{"q":"En Mississippi, un joven de 16 años presenta su solicitud por primera vez. ¿Qué recibe?","o":["Una licencia regular de inmediato","Un permiso de aprendiz","Un endoso de motocicleta","Una licencia temporal por seis meses"],"h1":"A los 16 años, quien solicita por primera vez empieza con un permiso, no con una licencia.","h2":"En Mississippi, un joven que solicita por primera vez a los 16 años recibe un permiso de aprendiz y puede obtener la licencia regular a los 17.","p":"Correcto. Primero recibe un permiso de aprendiz."},"ref":{"doc":"MS","page":15}},{"id":"ms-085","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a person first applies for a license at age 17. What may they do?","o":["Apply directly for a regular license, taking the exam the same day","Wait one year with a learner's permit","Drive only with a parent until 18","Get a license only after a road test"],"h1":"At this age, the permit year is not required.","h2":"In Mississippi, a person who first applies at 17 or older may apply directly for a regular license and may take the computerized exam the same day.","p":"Right. At 17 you may apply directly for a regular license."},"es":{"q":"En Mississippi, una persona solicita una licencia por primera vez a los 17 años. ¿Qué puede hacer?","o":["Solicitar directamente una licencia regular, tomando el examen el mismo día","Esperar un año con permiso de aprendiz","Manejar solo con un padre hasta los 18","Obtener la licencia solo después de un examen práctico"],"h1":"A esta edad no se exige el año de permiso.","h2":"En Mississippi, una persona que solicita por primera vez a los 17 años o más puede pedir directamente una licencia regular y tomar el examen computarizado el mismo día.","p":"Correcto. A los 17 años puede solicitar directamente la licencia regular."},"ref":{"doc":"MS","page":15}},{"id":"ms-086","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, besides age, which history also makes you eligible for a regular license?","o":["Owning a car for one year","Taking a first aid class","Holding a license from another state for at least six months","Riding a bicycle on public roads"],"h1":"It involves driving experience in another state.","h2":"In Mississippi, having held an out-of-state driver's license for at least six months is one way to qualify for a regular license.","p":"Right. Six months with an out-of-state license qualifies you."},"es":{"q":"En Mississippi, además de la edad, ¿qué antecedente también lo hace elegible para una licencia regular?","o":["Tener un carro durante un año","Tomar una clase de primeros auxilios","Haber tenido licencia de otro estado por al menos seis meses","Andar en bicicleta en vías públicas"],"h1":"Tiene que ver con experiencia manejando en otro estado.","h2":"En Mississippi, haber tenido una licencia de conducir de otro estado por al menos seis meses es una forma de calificar para una licencia regular.","p":"Correcto. Seis meses con licencia de otro estado lo califican."},"ref":{"doc":"MS","page":15}},{"id":"ms-087","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, what must you always have with you when you drive?","o":["Your birth certificate","Your driver's license","Your car title","Your Social Security card"],"h1":"An officer can ask to see it at any time.","h2":"In Mississippi, you must always have your driver's license with you while you drive, and show it when asked.","p":"Right. Always carry your driver's license."},"es":{"q":"En Mississippi, ¿qué debe llevar siempre con usted cuando maneja?","o":["Su acta de nacimiento","Su licencia de conducir","El título del carro","Su tarjeta del Seguro Social"],"h1":"Un policía puede pedir verla en cualquier momento.","h2":"En Mississippi, siempre debe llevar su licencia de conducir cuando maneja y mostrarla cuando se la pidan.","p":"Correcto. Siempre lleve su licencia de conducir."},"ref":{"doc":"MS","page":15}},{"id":"ms-088","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a 16-year-old applies for a regular license. The parent signs the affidavit for 50 hours of watched driving. What does that affidavit replace?","o":["The vision exam","The computerized exam","The proof of school attendance","The road test"],"h1":"The form for drivers under 17 is called a Road Test Waiver.","h2":"In Mississippi, for an applicant under 17, the parent's affidavit of 50 hours of witnessed driving serves as a waiver of the road test.","p":"Right. It waives the road test."},"es":{"q":"En Mississippi, un joven de 16 años solicita la licencia regular. Su padre firma la declaración de 50 horas de manejo observado. ¿Qué reemplaza esa declaración?","o":["El examen de la vista","El examen computarizado","La prueba de asistencia escolar","El examen práctico de manejo"],"h1":"El formulario para menores de 17 años se llama exención del examen práctico (Road Test Waiver).","h2":"En Mississippi, para un solicitante menor de 17 años, la declaración del padre de 50 horas de manejo observado sirve como exención del examen práctico.","p":"Correcto. Reemplaza el examen práctico de manejo."},"ref":{"doc":"MS","page":15}},{"id":"ms-089","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you are 18 and apply for your first license. How many proofs of residency must you show?","o":["Two","One","Three","None"],"h1":"It is more than one.","h2":"In Mississippi, an applicant 18 or older for an original license must show two documents that prove they live in the state.","p":"Right. You need two proofs of residency."},"es":{"q":"En Mississippi, usted tiene 18 años y solicita su primera licencia. ¿Cuántas pruebas de residencia debe mostrar?","o":["Dos","Una","Tres","Ninguna"],"h1":"Es más de una.","h2":"En Mississippi, un solicitante de 18 años o más para una licencia original debe mostrar dos documentos que prueben que vive en el estado.","p":"Correcto. Necesita dos pruebas de residencia."},"ref":{"doc":"MS","page":16}},{"id":"ms-090","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, you are 19 and live with your parents. The bills are in their names. What may you use as proof of residency?","o":["Nothing; you must have bills in your own name","A post office box receipt","Documents showing your parent's residence","A letter from a friend"],"h1":"Applicants under 21 have an easier option.","h2":"In Mississippi, an applicant under 21 may use documents for a parent's residence as proof of residency.","p":"Right. You may use your parent's residence documents."},"es":{"q":"En Mississippi, usted tiene 19 años y vive con sus padres. Las facturas están a nombre de ellos. ¿Qué puede usar como prueba de residencia?","o":["Nada; debe tener facturas a su propio nombre","Un recibo de apartado postal","Documentos que muestren la residencia de su padre o madre","Una carta de un amigo"],"h1":"Los solicitantes menores de 21 años tienen una opción más fácil.","h2":"En Mississippi, un solicitante menor de 21 años puede usar documentos de la residencia de su padre o madre como prueba de residencia.","p":"Correcto. Puede usar los documentos de residencia de sus padres."},"ref":{"doc":"MS","page":16}},{"id":"ms-091","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, what is NOT accepted as the address on a proof of residency?","o":["A street address on a water bill","A street address on a lease","A street address on a bank statement","A post office box number"],"h1":"Each proof must show where you physically live.","h2":"In Mississippi, each proof of residency must show a physical address, and post office box numbers are not accepted.","p":"Right. A post office box is not accepted."},"es":{"q":"En Mississippi, ¿qué NO se acepta como dirección en una prueba de residencia?","o":["Una dirección física en una factura de agua","Una dirección física en un contrato de alquiler","Una dirección física en un estado de cuenta bancario","Un número de apartado postal"],"h1":"Cada prueba debe mostrar dónde vive físicamente.","h2":"En Mississippi, cada prueba de residencia debe mostrar una dirección física, y no se aceptan números de apartado postal.","p":"Correcto. No se acepta un apartado postal."},"ref":{"doc":"MS","page":16}},{"id":"ms-092","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, which two proofs of identification are needed before a license or permit is issued?","o":["A school ID and a library card","A Social Security card and a certified birth certificate","A utility bill and a bank card","A passport photo and a lease"],"h1":"One shows your Social Security number, the other shows your birth.","h2":"In Mississippi, you need a Social Security card and a certified birth certificate as your two proofs of identification.","p":"Right. Social Security card and certified birth certificate."},"es":{"q":"En Mississippi, ¿cuáles son las dos pruebas de identidad necesarias antes de emitir una licencia o permiso?","o":["Una credencial escolar y una tarjeta de biblioteca","Una tarjeta del Seguro Social y un acta de nacimiento certificada","Una factura de servicios y una tarjeta bancaria","Una foto de pasaporte y un contrato de alquiler"],"h1":"Una muestra su número de Seguro Social; la otra, su nacimiento.","h2":"En Mississippi, necesita una tarjeta del Seguro Social y un acta de nacimiento certificada como sus dos pruebas de identidad.","p":"Correcto. Tarjeta del Seguro Social y acta de nacimiento certificada."},"ref":{"doc":"MS","page":16}},{"id":"ms-093","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 15-year-old's parents are both living and share legal custody. Who must sign the permit application?","o":["Either parent","Any adult relative","Both parents","The school principal"],"h1":"When both parents have custody, one signature is not enough.","h2":"In Mississippi, an applicant under 17 needs the signatures of both parents if both are living and both have legal custody.","p":"Right. Both parents must sign."},"es":{"q":"En Mississippi, los dos padres de un joven de 15 años viven y comparten la custodia legal. ¿Quién debe firmar la solicitud del permiso?","o":["Cualquiera de los dos","Cualquier pariente adulto","Ambos padres","El director de la escuela"],"h1":"Cuando ambos padres tienen la custodia, una sola firma no basta.","h2":"En Mississippi, un solicitante menor de 17 años necesita la firma de ambos padres si los dos viven y tienen la custodia legal.","p":"Correcto. Ambos padres deben firmar."},"ref":{"doc":"MS","page":16}},{"id":"ms-094","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a person signs a teen's license application. What must be done with that signature?","o":["It must be notarized","It must be signed in red ink","It must be mailed to the governor","Nothing; any signature is fine"],"h1":"A notary must witness it.","h2":"In Mississippi, whoever signs a teen's application must have the signature notarized.","p":"Right. The signature must be notarized."},"es":{"q":"En Mississippi, una persona firma la solicitud de licencia de un adolescente. ¿Qué se debe hacer con esa firma?","o":["Debe estar notariada","Debe firmarse con tinta roja","Debe enviarse por correo al gobernador","Nada; cualquier firma sirve"],"h1":"Un notario debe dar fe de ella.","h2":"En Mississippi, quien firma la solicitud de un adolescente debe notariar su firma.","p":"Correcto. La firma debe estar notariada."},"ref":{"doc":"MS","page":16}},{"id":"ms-095","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a parent who signed a teen's application no longer wants to be responsible. What can the parent do?","o":["Nothing until the teen turns 21","Pay a fine to be released","Ask the teen's school to take over","File a verified written request to cancel the teen's license or permit"],"h1":"The signer can ask the state to take the license or permit back.","h2":"In Mississippi, anyone who signed a teen's application may later file a verified written request to cancel the license or permit.","p":"Right. The signer may ask in writing for it to be cancelled."},"es":{"q":"En Mississippi, un padre que firmó la solicitud de su hijo ya no quiere ser responsable. ¿Qué puede hacer?","o":["Nada hasta que el joven cumpla 21","Pagar una multa para quedar libre","Pedir a la escuela que asuma la responsabilidad","Presentar una solicitud escrita y verificada para cancelar la licencia o el permiso"],"h1":"Quien firmó puede pedir al estado que retire la licencia o el permiso.","h2":"En Mississippi, cualquier persona que firmó la solicitud de un adolescente puede presentar después una solicitud escrita y verificada para cancelar la licencia o el permiso.","p":"Correcto. Quien firmó puede pedir por escrito la cancelación."},"ref":{"doc":"MS","page":16}},{"id":"ms-096","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a 17-year-old applicant is married. What may the teen show instead of the school Certification of Attendance?","o":["A work schedule","A marriage license","A church letter","A parent's tax return"],"h1":"It is proof of the marriage.","h2":"In Mississippi, an applicant under 18 who is married may show a marriage license instead of the School Certification of Attendance.","p":"Right. A marriage license may be used."},"es":{"q":"En Mississippi, un solicitante de 17 años está casado. ¿Qué puede mostrar en lugar del Certificado de Asistencia escolar?","o":["Un horario de trabajo","Un acta de matrimonio","Una carta de la iglesia","La declaración de impuestos de un padre"],"h1":"Es la prueba del matrimonio.","h2":"En Mississippi, un solicitante menor de 18 años que está casado puede mostrar un acta de matrimonio en lugar del Certificado de Asistencia Escolar.","p":"Correcto. Puede usar el acta de matrimonio."},"ref":{"doc":"MS","page":16}},{"id":"ms-097","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a 15-year-old is home-schooled. Where does the teen get the Certification of Attendance form?","o":["From the nearest public school","From the county court","From the Department of Public Safety website","From the car dealer"],"h1":"It is a blank form you can download.","h2":"In Mississippi, a home-schooled applicant gets a blank Certification of Attendance from the Department of Public Safety website, and a parent signs it.","p":"Right. It comes from the Department of Public Safety website."},"es":{"q":"En Mississippi, un joven de 15 años estudia en casa. ¿Dónde consigue el formulario de Certificado de Asistencia?","o":["En la escuela pública más cercana","En el tribunal del condado","En el sitio web del Departamento de Seguridad Pública","En el concesionario de carros"],"h1":"Es un formulario en blanco que puede descargar.","h2":"En Mississippi, un solicitante que estudia en casa obtiene un Certificado de Asistencia en blanco del sitio web del Departamento de Seguridad Pública, y un padre lo firma.","p":"Correcto. Viene del sitio web del Departamento de Seguridad Pública."},"ref":{"doc":"MS","page":16}},{"id":"ms-098","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what can happen if you make a false statement on your license application?","o":["Your driving privileges may be suspended","Nothing, if you correct it later","You must retake the vision exam","You pay a $1 late fee"],"h1":"Lying on the form can cost you your privilege to drive.","h2":"In Mississippi, a false statement on your license application can lead to suspension of your driving privileges.","p":"Right. Your driving privileges may be suspended."},"es":{"q":"En Mississippi, ¿qué puede pasar si da información falsa en su solicitud de licencia?","o":["Le pueden suspender el privilegio de manejar","Nada, si lo corrige después","Debe repetir el examen de la vista","Paga un recargo de $1"],"h1":"Mentir en el formulario puede costarle su privilegio de manejar.","h2":"En Mississippi, dar información falsa en su solicitud de licencia puede llevar a la suspensión de su privilegio de manejar.","p":"Correcto. Le pueden suspender el privilegio de manejar."},"ref":{"doc":"MS","page":16}},{"id":"ms-099","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, which three things must you complete before you get an original driver's license?","o":["A road test, a first aid class and a fee","A vision exam, a road test and a hearing test","Proof of a job, insurance and a car title","A vision exam, the computerized exam and the 50-hour driving affidavit"],"h1":"One checks your eyes, one checks your knowledge, and one confirms your practice.","h2":"In Mississippi, before an original license you must pass the vision exam, pass the computerized exam and give an affidavit of 50 hours of witnessed driving.","p":"Right. Vision exam, computerized exam and the 50-hour affidavit."},"es":{"q":"En Mississippi, ¿cuáles son los tres requisitos que debe cumplir antes de recibir una licencia de conducir original?","o":["Un examen práctico, una clase de primeros auxilios y una tarifa","Un examen de la vista, un examen práctico y un examen de audición","Prueba de empleo, seguro y título del carro","Un examen de la vista, el examen computarizado y la declaración de 50 horas de manejo"],"h1":"Uno revisa sus ojos, otro sus conocimientos y otro confirma su práctica.","h2":"En Mississippi, antes de una licencia original debe aprobar el examen de la vista, aprobar el examen computarizado y entregar una declaración de 50 horas de manejo observado.","p":"Correcto. Examen de la vista, examen computarizado y la declaración de 50 horas."},"ref":{"doc":"MS","page":17}},{"id":"ms-100","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, you have trouble reading. How can the computerized exam help you?","o":["You may bring a friend to read for you","A headset lets the machine read the questions and answers aloud","You may skip the exam","You get double the time only"],"h1":"Listen with your ears.","h2":"In Mississippi, the computerized exam has a headset, and the machine reads the questions and answers aloud.","p":"Right. A headset reads the exam aloud."},"es":{"q":"En Mississippi, a usted le cuesta leer. ¿Cómo le puede ayudar el examen computarizado?","o":["Puede traer a un amigo que le lea","Unos audífonos permiten que la máquina lea en voz alta las preguntas y respuestas","Puede saltarse el examen","Solo le dan el doble de tiempo"],"h1":"Escuche con sus oídos.","h2":"En Mississippi, el examen computarizado tiene audífonos, y la máquina lee en voz alta las preguntas y las respuestas.","p":"Correcto. Los audífonos leen el examen en voz alta."},"ref":{"doc":"MS","page":17}},{"id":"ms-101","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, your vision test shows you may need glasses. What happens next?","o":["You fail and wait a year","You must take a road test instead","An eye specialist or optometrist fills out a vision form for you","You get a license for daytime only"],"h1":"A professional must check your eyes and fill out a form.","h2":"In Mississippi, if the vision exam shows you may need glasses, an eye specialist or optometrist must test your eyes and fill out the vision form (DE26).","p":"Right. An eye specialist fills out the vision form."},"es":{"q":"En Mississippi, su examen de la vista indica que quizá necesita anteojos. ¿Qué sigue?","o":["Reprueba y espera un año","Debe tomar un examen práctico en su lugar","Un oculista u optometrista llena un formulario de la vista para usted","Recibe una licencia solo para el día"],"h1":"Un profesional debe revisar sus ojos y llenar un formulario.","h2":"En Mississippi, si el examen de la vista indica que quizá necesita anteojos, un oculista u optometrista debe examinar sus ojos y llenar el formulario de la vista (DE26).","p":"Correcto. Un oculista llena el formulario de la vista."},"ref":{"doc":"MS","page":17}},{"id":"ms-102","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you are under a doctor's care. What may be required before your exams?","o":["A certificate about your physical or mental condition","A letter from your employer","A second vision test in another state","Nothing extra"],"h1":"Your doctor may need to fill something out.","h2":"In Mississippi, if you are under a physician's care, a certificate about your physical or mental condition may be required before you take the exams.","p":"Right. A certificate about your condition may be required."},"es":{"q":"En Mississippi, usted está bajo el cuidado de un médico. ¿Qué se le puede exigir antes de sus exámenes?","o":["Un certificado sobre su condición física o mental","Una carta de su empleador","Un segundo examen de la vista en otro estado","Nada más"],"h1":"Quizá su médico tenga que llenar algo.","h2":"En Mississippi, si está bajo el cuidado de un médico, se le puede exigir un certificado sobre su condición física o mental antes de los exámenes.","p":"Correcto. Se le puede exigir un certificado sobre su condición."},"ref":{"doc":"MS","page":17}},{"id":"ms-103","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"Under Mississippi law, is a crosswalk at an intersection part of the intersection?","o":["No, it is separate","Yes, crosswalks count as part of the intersection","Only if it is painted","Only at night"],"h1":"Think of where the intersection begins.","h2":"Under Mississippi law, crosswalks are counted as part of the intersection.","p":"Right. Crosswalks are part of the intersection."},"es":{"q":"Según la ley de Mississippi, ¿un cruce peatonal en una intersección es parte de la intersección?","o":["No, es aparte","Sí, los cruces peatonales cuentan como parte de la intersección","Solo si está pintado","Solo de noche"],"h1":"Piense en dónde empieza la intersección.","h2":"Según la ley de Mississippi, los cruces peatonales cuentan como parte de la intersección.","p":"Correcto. Los cruces peatonales son parte de la intersección."},"ref":{"doc":"MS","page":18}},{"id":"ms-104","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"Under Mississippi's definition in the manual, which of these is NOT a motor vehicle?","o":["A motorcycle","A pick-up truck","A golf cart","A car"],"h1":"The definition leaves out electric bicycles, golf carts and low-speed vehicles.","h2":"Under the Mississippi manual's definition, golf carts, electric bicycles and low-speed vehicles are not motor vehicles.","p":"Right. A golf cart is not a motor vehicle under that definition."},"es":{"q":"Según la definición del manual de Mississippi, ¿cuál de estos NO es un vehículo motorizado?","o":["Una motocicleta","Una camioneta pick-up","Un carrito de golf","Un carro"],"h1":"La definición excluye las bicicletas eléctricas, los carritos de golf y los vehículos de baja velocidad.","h2":"Según la definición del manual de Mississippi, los carritos de golf, las bicicletas eléctricas y los vehículos de baja velocidad no son vehículos motorizados.","p":"Correcto. Un carrito de golf no es un vehículo motorizado según esa definición."},"ref":{"doc":"MS","page":18}},{"id":"ms-105","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, your foot brake must be able to stop your car within what distance at 20 mph?","o":["10 feet","55 feet","100 feet","30 feet"],"h1":"It is shorter than the distance allowed for the parking brake.","h2":"In Mississippi, the foot brake must stop the vehicle within 30 feet at 20 mph.","p":"Right. The foot brake must stop you within 30 feet at 20 mph."},"es":{"q":"En Mississippi, ¿dentro de qué distancia debe poder detener su carro el freno de pie a 20 mph?","o":["10 pies","55 pies","100 pies","30 pies"],"h1":"Es menor que la distancia permitida para el freno de estacionamiento.","h2":"En Mississippi, el freno de pie debe detener el vehículo dentro de 30 pies a 20 mph.","p":"Correcto. El freno de pie debe detenerlo dentro de 30 pies a 20 mph."},"ref":{"doc":"MS","page":19}},{"id":"ms-106","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, your parking brake must be able to stop your car within what distance at 20 mph?","o":["55 feet","30 feet","20 feet","200 feet"],"h1":"It is allowed a longer distance than the foot brake.","h2":"In Mississippi, the parking brake must stop the vehicle within 55 feet at 20 mph.","p":"Right. The parking brake must stop you within 55 feet at 20 mph."},"es":{"q":"En Mississippi, ¿dentro de qué distancia debe poder detener su carro el freno de estacionamiento a 20 mph?","o":["55 pies","30 pies","20 pies","200 pies"],"h1":"Se le permite una distancia más larga que al freno de pie.","h2":"En Mississippi, el freno de estacionamiento debe detener el vehículo dentro de 55 pies a 20 mph.","p":"Correcto. El freno de estacionamiento debe detenerlo dentro de 55 pies a 20 mph."},"ref":{"doc":"MS","page":19}},{"id":"ms-107","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, from how far away must your car's horn be heard?","o":["50 feet","200 feet","500 feet","1,000 feet"],"h1":"It is the length of about 13 cars.","h2":"In Mississippi, your vehicle must have a horn that can be heard 200 feet away.","p":"Right. The horn must be heard from 200 feet."},"es":{"q":"En Mississippi, ¿desde qué distancia se debe oír la bocina de su carro?","o":["50 pies","200 pies","500 pies","1,000 pies"],"h1":"Es el largo de unos 13 carros.","h2":"En Mississippi, su vehículo debe tener una bocina que se oiga a 200 pies de distancia.","p":"Correcto. La bocina se debe oír desde 200 pies."},"ref":{"doc":"MS","page":19}},{"id":"ms-108","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, you want to put a siren on your personal car. Is that allowed?","o":["Yes, if it is quiet","Yes, but only in the country","No, sirens and exhaust whistles are against the law","Yes, after a permit from the county"],"h1":"Noise-making devices are not allowed on ordinary vehicles.","h2":"In Mississippi, it is against the law to have a siren, or an exhaust or spark whistle, on your vehicle.","p":"Right. Sirens are not allowed."},"es":{"q":"En Mississippi, usted quiere poner una sirena en su carro particular. ¿Está permitido?","o":["Sí, si es silenciosa","Sí, pero solo en el campo","No, las sirenas y los silbatos de escape son ilegales","Sí, con un permiso del condado"],"h1":"Los aparatos que hacen ruido no se permiten en vehículos comunes.","h2":"En Mississippi, es ilegal tener en su vehículo una sirena o un silbato de escape o de chispa.","p":"Correcto. Las sirenas no están permitidas."},"ref":{"doc":"MS","page":19}},{"id":"ms-109","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, from how far behind must your red taillight be visible?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is the same distance used for dimming your high beams.","h2":"In Mississippi, the taillight must be red and visible from 500 feet behind you.","p":"Right. It must be visible from 500 feet."},"es":{"q":"En Mississippi, ¿desde qué distancia detrás de usted debe verse su luz trasera roja?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es la misma distancia que se usa para bajar las luces altas.","h2":"En Mississippi, la luz trasera debe ser roja y verse desde 500 pies detrás de usted.","p":"Correcto. Debe verse desde 500 pies."},"ref":{"doc":"MS","page":19}},{"id":"ms-110","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, besides two headlights, how many extra lights may your car have?","o":["One spotlight and up to three auxiliary lights","Two spotlights and up to six auxiliary lights","No extra lights at all","As many as you like"],"h1":"The limit is one of one kind and three of the other.","h2":"In Mississippi, besides two headlights, a vehicle may have no more than one spotlight and no more than three auxiliary lights.","p":"Right. One spotlight and up to three auxiliary lights."},"es":{"q":"En Mississippi, además de los dos faros delanteros, ¿cuántas luces adicionales puede tener su carro?","o":["Un foco buscador y hasta tres luces auxiliares","Dos focos buscadores y hasta seis luces auxiliares","Ninguna luz adicional","Todas las que quiera"],"h1":"El límite es una de un tipo y tres del otro.","h2":"En Mississippi, además de los dos faros, un vehículo puede tener como máximo un foco buscador y tres luces auxiliares.","p":"Correcto. Un foco buscador y hasta tres luces auxiliares."},"ref":{"doc":"MS","page":19}},{"id":"ms-111","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, which colors are extra lights on your car, such as a spotlight or auxiliary lights, never allowed to be?","o":["White or yellow","Red or blue","Amber or white","Yellow or green"],"h1":"These colors are used by emergency vehicles.","h2":"In Mississippi, it is against the law for a spotlight or auxiliary light on your car to be red or blue.","p":"Right. Extra lights may not be red or blue."},"es":{"q":"En Mississippi, ¿de qué colores nunca pueden ser las luces adicionales de su carro, como un foco buscador o luces auxiliares?","o":["Blanco o amarillo","Rojo o azul","Ámbar o blanco","Amarillo o verde"],"h1":"Estos colores los usan los vehículos de emergencia.","h2":"En Mississippi, es ilegal que un foco buscador o una luz auxiliar de su carro sea roja o azul.","p":"Correcto. Las luces adicionales no pueden ser rojas ni azules."},"ref":{"doc":"MS","page":19}},{"id":"ms-112","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, not counting headlights, what is the most lights the manual allows burning at once?","o":["Two","Three","Four","Six"],"h1":"It is one more than the number of auxiliary lights allowed.","h2":"In Mississippi, you should never have more than four lights, not counting headlights, burning at the same time.","p":"Right. No more than four lights besides headlights."},"es":{"q":"En Mississippi, sin contar los faros, ¿cuántas luces como máximo permite el manual encendidas a la vez?","o":["Dos","Tres","Cuatro","Seis"],"h1":"Es una más que el número de luces auxiliares permitidas.","h2":"En Mississippi, nunca debe tener más de cuatro luces encendidas a la vez, sin contar los faros.","p":"Correcto. No más de cuatro luces además de los faros."},"ref":{"doc":"MS","page":19}},{"id":"ms-113","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, does state law require your car to have an inside rearview mirror?","o":["Yes, on every car","Yes, but only for drivers under 21","Yes, two of them","No, but it is recommended"],"h1":"The law requires a side mirror only when a truck body blocks your view.","h2":"In Mississippi, the law does not require a rearview mirror, but one is recommended; a truck whose body blocks the view behind must have a side mirror.","p":"Right. It is not required by law, but it is recommended."},"es":{"q":"En Mississippi, ¿exige la ley estatal que su carro tenga un espejo retrovisor interior?","o":["Sí, en todos los carros","Sí, pero solo para menores de 21 años","Sí, dos espejos","No, pero se recomienda"],"h1":"La ley exige un espejo lateral solo cuando la carrocería de un camión le tapa la vista.","h2":"En Mississippi, la ley no exige un espejo retrovisor, pero se recomienda; un camión cuya carrocería tapa la vista hacia atrás debe tener un espejo lateral.","p":"Correcto. La ley no lo exige, pero se recomienda."},"ref":{"doc":"MS","page":19}},{"id":"ms-114","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, may you install a muffler cutout or bypass on your car?","o":["No, the muffler must work all the time","Yes, on the highway only","Yes, if the car is older than 10 years","Yes, during the day"],"h1":"The muffler must always stop excess noise and smoke.","h2":"In Mississippi, your muffler must work at all times, and using a muffler cutout, bypass or similar device is not allowed.","p":"Right. Muffler cutouts and bypasses are not allowed."},"es":{"q":"En Mississippi, ¿puede instalar en su carro un desvío o anulador del silenciador (mofle)?","o":["No, el silenciador debe funcionar siempre","Sí, solo en la carretera","Sí, si el carro tiene más de 10 años","Sí, durante el día"],"h1":"El silenciador siempre debe evitar el exceso de ruido y humo.","h2":"En Mississippi, su silenciador debe funcionar en todo momento, y no se permite usar un anulador, desvío o aparato parecido.","p":"Correcto. No se permiten anuladores ni desvíos del silenciador."},"ref":{"doc":"MS","page":19}},{"id":"ms-115","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Mississippi's squatted vehicle law, a passenger vehicle may not be altered so its front fender is how much higher than its rear fender?","o":["1 inch or more","2 inches or more","4 inches or more","10 inches or more"],"h1":"It is a few inches, measured from the ground through the wheel center.","h2":"Under Mississippi law, it is illegal to drive a passenger vehicle whose front fender was raised 4 or more inches higher than the rear fender.","p":"Right. A difference of 4 inches or more is illegal."},"es":{"q":"Según la ley de vehículos 'squatted' de Mississippi, ¿cuánto más alto que el trasero no puede quedar el guardafango delantero de un vehículo de pasajeros modificado?","o":["1 pulgada o más","2 pulgadas o más","4 pulgadas o más","10 pulgadas o más"],"h1":"Son unas pocas pulgadas, medidas desde el suelo por el centro de la rueda.","h2":"Según la ley de Mississippi, es ilegal manejar un vehículo de pasajeros cuyo guardafango delantero se haya subido 4 pulgadas o más por encima del trasero.","p":"Correcto. Una diferencia de 4 pulgadas o más es ilegal."},"ref":{"doc":"MS","page":20}},{"id":"ms-116","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi's penny test, you put a penny head-first into your tire tread. What shows the tread is still safe?","o":["You can see all of Lincoln's head","Part of Lincoln's head is covered by the tread","The penny falls out","The penny is shiny"],"h1":"Deep tread hides some of the head.","h2":"In the Mississippi manual's penny test, if any part of Lincoln's head is covered by the tread, you still have a safe amount of tread.","p":"Right. If part of the head is covered, the tread is safe."},"es":{"q":"En la prueba del centavo del manual de Mississippi, usted mete un centavo con la cabeza hacia abajo en la banda de rodamiento. ¿Qué indica que la banda todavía es segura?","o":["Se ve toda la cabeza de Lincoln","Parte de la cabeza de Lincoln queda tapada por la banda","El centavo se cae","El centavo brilla"],"h1":"Una banda profunda tapa parte de la cabeza.","h2":"En la prueba del centavo del manual de Mississippi, si alguna parte de la cabeza de Lincoln queda tapada por la banda, todavía tiene una cantidad segura de banda.","p":"Correcto. Si parte de la cabeza queda tapada, la banda es segura."},"ref":{"doc":"MS","page":21}},{"id":"ms-117","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"The Mississippi manual says to plan stops on long trips. How often should you stop?","o":["Every 25 miles","Every 50 miles or 1 hour","Every 300 miles","About every 100 miles or 2 hours"],"h1":"Think of a round number of miles, or two hours.","h2":"The Mississippi manual says to plan to stop about every 100 miles or 2 hours on long trips.","p":"Right. Stop about every 100 miles or 2 hours."},"es":{"q":"El manual de Mississippi dice que planee paradas en viajes largos. ¿Cada cuánto debe parar?","o":["Cada 25 millas","Cada 50 millas o 1 hora","Cada 300 millas","Más o menos cada 100 millas o 2 horas"],"h1":"Piense en un número redondo de millas, o dos horas.","h2":"El manual de Mississippi dice que en viajes largos planee parar más o menos cada 100 millas o cada 2 horas.","p":"Correcto. Pare más o menos cada 100 millas o 2 horas."},"ref":{"doc":"MS","page":21}},{"id":"ms-118","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Mississippi manual says where to place your hands on the steering wheel. Which positions?","o":["At 3 and 9 o'clock","At 10 and 2 o'clock","At 12 o'clock with one hand","At 5 and 7 o'clock"],"h1":"The older 10-and-2 position is no longer recommended because of air bags.","h2":"The Mississippi manual recommends hands on the outside of the wheel at the 3 and 9 o'clock positions; 10 and 2 is no longer recommended with air bags.","p":"Right. Hands at 3 and 9 o'clock."},"es":{"q":"El manual de Mississippi dice dónde poner las manos en el volante. ¿En qué posiciones?","o":["A las 3 y a las 9","A las 10 y a las 2","A las 12 con una mano","A las 5 y a las 7"],"h1":"La posición antigua de las 10 y las 2 ya no se recomienda por las bolsas de aire.","h2":"El manual de Mississippi recomienda poner las manos por fuera del volante en las posiciones de las 3 y las 9; las 10 y las 2 ya no se recomiendan con bolsas de aire.","p":"Correcto. Las manos a las 3 y a las 9."},"ref":{"doc":"MS","page":22}},{"id":"ms-119","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"Under Mississippi's texting law, which message may a driver still read?","o":["A text from a friend","An email from work","A weather or traffic alert","A social media post"],"h1":"The law's definition of a text message leaves out emergency, traffic and weather alerts.","h2":"Under Mississippi's texting law, emergency, traffic and weather alerts and messages about operating or navigating the vehicle are not counted as text messages.","p":"Right. Weather and traffic alerts are not covered by the ban."},"es":{"q":"Según la ley de mensajes de texto de Mississippi, ¿qué mensaje puede leer todavía un conductor?","o":["Un mensaje de un amigo","Un correo electrónico del trabajo","Una alerta del clima o del tráfico","Una publicación en redes sociales"],"h1":"La definición de mensaje de texto en la ley excluye las alertas de emergencia, de tráfico y del clima.","h2":"Según la ley de Mississippi, las alertas de emergencia, de tráfico y del clima, y los mensajes sobre el manejo o la navegación del vehículo, no cuentan como mensajes de texto.","p":"Correcto. Las alertas del clima y del tráfico no están prohibidas."},"ref":{"doc":"MS","page":23}},{"id":"ms-120","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, while driving, may you read or post on a social networking site using a phone in your hand?","o":["Yes, at red lights","No, it is not allowed","Yes, if you are over 21","Yes, on rural roads"],"h1":"The ban covers more than texting.","h2":"In Mississippi, reading or posting to a social networking site on a hand-held phone while driving is not allowed.","p":"Right. Social media on a hand-held phone is not allowed."},"es":{"q":"En Mississippi, mientras maneja, ¿puede leer o publicar en una red social con el teléfono en la mano?","o":["Sí, en los semáforos en rojo","No, no está permitido","Sí, si tiene más de 21 años","Sí, en caminos rurales"],"h1":"La prohibición cubre más que los mensajes de texto.","h2":"En Mississippi, no está permitido leer ni publicar en una red social con un teléfono en la mano mientras maneja.","p":"Correcto. No se permiten las redes sociales con el teléfono en la mano."},"ref":{"doc":"MS","page":23}},{"id":"ms-121","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, what may NOT be put on a car's windows?","o":["A window tint inspection decal","An inspection sticker placed by law","Clear glass","Signs or material that cause a mirrored effect"],"h1":"Official decals are fine; things that block or mirror the view are not.","h2":"In Mississippi, the windshield must be free of signs and unofficial stickers, and windows may not have signs, posters, stickers or glass material that cause a mirrored effect.","p":"Right. No mirrored material or unofficial signs on the windows."},"es":{"q":"En Mississippi, ¿qué NO se puede poner en las ventanas de un carro?","o":["La calcomanía de inspección de polarizado","Una calcomanía de inspección exigida por ley","Vidrio transparente","Letreros o material que cause un efecto de espejo"],"h1":"Las calcomanías oficiales están bien; lo que tapa o refleja la vista, no.","h2":"En Mississippi, el parabrisas debe estar libre de letreros y calcomanías no oficiales, y las ventanas no pueden tener letreros, carteles, calcomanías ni material de vidrio que cause un efecto de espejo.","p":"Correcto. Nada de material de espejo ni letreros no oficiales en las ventanas."},"ref":{"doc":"MS","page":24}},{"id":"ms-122","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Mississippi manual gives a rule about stereo headphones. What is it?","o":["Never wear them while you drive","Wear them in only one ear","Use them only on the interstate","Use them only at low volume"],"h1":"You must be able to hear sirens and whistles.","h2":"The Mississippi manual says never to wear stereo headphones while you drive, because you may not hear warning signals such as sirens.","p":"Right. Never wear stereo headphones while driving."},"es":{"q":"El manual de Mississippi da una regla sobre los audífonos estéreo. ¿Cuál es?","o":["Nunca los use mientras maneja","Úselos en un solo oído","Úselos solo en la interestatal","Úselos solo a volumen bajo"],"h1":"Usted debe poder oír sirenas y silbatos.","h2":"El manual de Mississippi dice que nunca use audífonos estéreo mientras maneja, porque quizá no oiga señales de advertencia como las sirenas.","p":"Correcto. Nunca use audífonos estéreo al manejar."},"ref":{"doc":"MS","page":24}},{"id":"ms-123","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, an orange and red triangle is on the back of a farm vehicle. What does it tell you about its speed?","o":["It goes at least 45 mph","It is an emergency vehicle","It travels 25 mph or less","It is about to turn left"],"h1":"It is the slow-moving vehicle emblem.","h2":"In Mississippi, the orange and red triangle marks a slow-moving vehicle that travels 25 mph or less.","p":"Right. It travels 25 mph or less."},"es":{"q":"En Mississippi, un triángulo anaranjado y rojo está en la parte de atrás de un vehículo agrícola. ¿Qué le dice sobre su velocidad?","o":["Va al menos a 45 mph","Es un vehículo de emergencia","Viaja a 25 mph o menos","Está por girar a la izquierda"],"h1":"Es el emblema de vehículo lento.","h2":"En Mississippi, el triángulo anaranjado y rojo indica un vehículo lento que viaja a 25 mph o menos.","p":"Correcto. Viaja a 25 mph o menos."},"ref":{"doc":"MS","page":34}},{"id":"ms-124","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, you are behind a horse-drawn buggy on a rural road near fields. What should you expect?","o":["It will always pull onto the shoulder","It may turn left into a field or driveway","It must stay off highways","It has no right to use the road"],"h1":"Animal-drawn vehicles often head into farms and driveways.","h2":"In Mississippi, you should expect animal-drawn vehicles to make left turns into fields and driveways; they have the same rights to the road as other vehicles.","p":"Right. Expect it to turn left into a field or driveway."},"es":{"q":"En Mississippi, usted va detrás de un carruaje tirado por caballos en un camino rural cerca de campos. ¿Qué debe esperar?","o":["Siempre se saldrá al acotamiento","Puede girar a la izquierda hacia un campo o una entrada","No puede usar las carreteras","No tiene derecho a usar el camino"],"h1":"Los vehículos tirados por animales a menudo entran a granjas y entradas.","h2":"En Mississippi, debe esperar que los vehículos tirados por animales giren a la izquierda hacia campos y entradas; tienen los mismos derechos en el camino que otros vehículos.","p":"Correcto. Espere que gire a la izquierda hacia un campo o una entrada."},"ref":{"doc":"MS","page":34}},{"id":"ms-125","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi's rural areas, how far before the tracks is the round yellow railroad warning sign usually posted?","o":["50 to 100 feet","100 to 200 feet","1 to 2 miles","500 to 900 feet"],"h1":"It gives you a few hundred feet to slow down.","h2":"In Mississippi's rural areas, the round yellow railroad advance warning sign is normally posted 500 to 900 feet before the tracks.","p":"Right. It is usually 500 to 900 feet before the tracks."},"es":{"q":"En las zonas rurales de Mississippi, ¿a qué distancia antes de las vías se pone normalmente la señal redonda amarilla de advertencia de ferrocarril?","o":["De 50 a 100 pies","De 100 a 200 pies","De 1 a 2 millas","De 500 a 900 pies"],"h1":"Le da unos cientos de pies para bajar la velocidad.","h2":"En las zonas rurales de Mississippi, la señal redonda amarilla de advertencia de ferrocarril normalmente se pone de 500 a 900 pies antes de las vías.","p":"Correcto. Suele estar de 500 a 900 pies antes de las vías."},"ref":{"doc":"MS","page":35}},{"id":"ms-126","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, besides a school bus with children, which vehicle must always stop at every railroad crossing?","o":["A vehicle for hire carrying passengers","Any pick-up truck","Any car towing a boat","A motorcycle"],"h1":"Think of taxis and other paid passenger vehicles.","h2":"In Mississippi, a vehicle for hire carrying passengers must stop at all railroad crossings, like a school bus with children and vehicles carrying explosives or flammable liquids.","p":"Right. A vehicle for hire carrying passengers must always stop."},"es":{"q":"En Mississippi, además de un autobús escolar con niños, ¿qué vehículo siempre debe detenerse en todos los cruces de ferrocarril?","o":["Un vehículo de alquiler que lleva pasajeros","Cualquier camioneta pick-up","Cualquier carro que remolca un bote","Una motocicleta"],"h1":"Piense en los taxis y otros vehículos que cobran por llevar pasajeros.","h2":"En Mississippi, un vehículo de alquiler que lleva pasajeros debe detenerse en todos los cruces de ferrocarril, igual que un autobús escolar con niños y los vehículos que llevan explosivos o líquidos inflamables.","p":"Correcto. Un vehículo de alquiler con pasajeros siempre debe detenerse."},"ref":{"doc":"MS","page":35}},{"id":"ms-127","scope":"MS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Mississippi, the gate at a railroad crossing is lowered. Where must you stop?","o":["Right on the first rail","At least 100 feet away","Between 10 and 50 feet from the nearest rail","Anywhere you can see the train"],"h1":"Not too close to the rail, and not too far back.","h2":"In Mississippi, you must stop no more than 50 feet and no less than 10 feet from the nearest rail when a gate is lowered or signals flash.","p":"Right. Stop between 10 and 50 feet from the rail."},"es":{"q":"En Mississippi, la barrera de un cruce de ferrocarril está abajo. ¿Dónde debe detenerse?","o":["Justo sobre el primer riel","Al menos a 100 pies","Entre 10 y 50 pies del riel más cercano","En cualquier lugar donde vea el tren"],"h1":"Ni muy cerca del riel ni muy lejos.","h2":"En Mississippi, debe detenerse a no más de 50 pies y no menos de 10 pies del riel más cercano cuando la barrera está abajo o las señales parpadean.","p":"Correcto. Deténgase entre 10 y 50 pies del riel."},"ref":{"doc":"MS","page":36}},{"id":"ms-128","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, you drive a car with a manual transmission over railroad tracks. What should you avoid?","o":["Looking both ways","Shifting gears while on the tracks","Driving at a steady speed","Using your headlights"],"h1":"Stalling on the tracks could be deadly.","h2":"In Mississippi, you should not shift gears as you drive across railroad tracks.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"En Mississippi, usted cruza las vías del tren en un carro de transmisión manual. ¿Qué debe evitar?","o":["Mirar a ambos lados","Cambiar de marcha sobre las vías","Manejar a una velocidad constante","Usar los faros"],"h1":"Apagarse sobre las vías podría ser mortal.","h2":"En Mississippi, no debe cambiar de marcha mientras cruza las vías del tren.","p":"Correcto. No cambie de marcha sobre las vías."},"ref":{"doc":"MS","page":36}},{"id":"ms-129","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"The Mississippi manual says your car is stuck on the tracks and the crossing lights start to flash. How much time might you have before the train arrives?","o":["Five minutes","Two minutes","One minute","Only about 20 seconds"],"h1":"It is the least time a train takes once the lights come on.","h2":"The Mississippi manual says that once the crossing lights start to flash, you may have only about 20 seconds before the train arrives, so get out right away.","p":"Right. You may have only about 20 seconds."},"es":{"q":"El manual de Mississippi dice que su carro está atascado en las vías y las luces del cruce empiezan a parpadear. ¿Cuánto tiempo podría tener antes de que llegue el tren?","o":["Cinco minutos","Dos minutos","Un minuto","Solo unos 20 segundos"],"h1":"Es el tiempo mínimo que tarda un tren cuando se encienden las luces.","h2":"El manual de Mississippi dice que cuando las luces del cruce empiezan a parpadear, quizá tenga solo unos 20 segundos antes de que llegue el tren, así que salga de inmediato.","p":"Correcto. Quizá tenga solo unos 20 segundos."},"ref":{"doc":"MS","page":36}},{"id":"ms-130","scope":"MS","cat":"signals","sign":null,"c":0,"en":{"q":"In Mississippi, you want to turn right at a red light. There is no sign against it and the way looks clear. What must you do first?","o":["Stop completely, then yield before turning","Slow down and yield without stopping","Wait for the green light","Honk and turn"],"h1":"Yielding alone is not enough under the law.","h2":"In Mississippi, before turning right on red you must first stop completely and yield; only yielding without stopping is illegal.","p":"Right. Stop completely first, then yield and turn."},"es":{"q":"En Mississippi, usted quiere girar a la derecha con el semáforo en rojo. No hay señal que lo prohíba y el camino se ve libre. ¿Qué debe hacer primero?","o":["Detenerse por completo y luego ceder el paso antes de girar","Bajar la velocidad y ceder el paso sin detenerse","Esperar la luz verde","Tocar la bocina y girar"],"h1":"Ceder el paso solamente no basta según la ley.","h2":"En Mississippi, antes de girar a la derecha en rojo debe detenerse por completo y ceder el paso; ceder sin detenerse es ilegal.","p":"Correcto. Primero deténgase por completo, luego ceda y gire."},"ref":{"doc":"MS","page":37}},{"id":"ms-131","scope":"MS","cat":"signals","sign":null,"c":2,"en":{"q":"In Mississippi, you reach an intersection where the traffic lights are not working at all; they are dark. What must you do?","o":["Drive through at the speed limit","Slow down only","Stop completely, then go with care using right-of-way rules","Turn around and take another road"],"h1":"Treat it as if you had a stop to make.","h2":"In Mississippi, at a malfunctioning traffic light with no lights working, you must stop completely and then proceed with caution, following right-of-way rules.","p":"Right. Stop completely, then proceed carefully."},"es":{"q":"En Mississippi, usted llega a una intersección donde los semáforos no funcionan; están apagados. ¿Qué debe hacer?","o":["Pasar a la velocidad límite","Solo bajar la velocidad","Detenerse por completo y luego seguir con cuidado según las reglas del derecho de paso","Dar la vuelta y tomar otro camino"],"h1":"Trátelo como si tuviera que hacer un alto.","h2":"En Mississippi, en un semáforo dañado sin ninguna luz, debe detenerse por completo y luego seguir con cuidado, respetando las reglas del derecho de paso.","p":"Correcto. Deténgase por completo y luego siga con cuidado."},"ref":{"doc":"MS","page":39}},{"id":"ms-132","scope":"MS","cat":"signals","sign":null,"c":1,"en":{"q":"The Mississippi manual describes how an officer directing traffic usually tells you to stop. What does the officer do?","o":["Waves both arms in circles","Holds up one hand, palm toward you, and gives a long whistle blast","Points at the ground and gives short whistle blasts","Turns their back to you"],"h1":"Think of a raised palm and one long sound.","h2":"The Mississippi manual says an officer usually signals you to stop by holding up one hand, palm toward you, and giving a long blast on the whistle.","p":"Right. A raised palm and a long whistle blast mean stop."},"es":{"q":"El manual de Mississippi describe cómo un policía que dirige el tráfico suele indicarle que se detenga. ¿Qué hace el policía?","o":["Mueve los dos brazos en círculos","Levanta una mano con la palma hacia usted y da un pitazo largo","Señala el suelo y da pitazos cortos","Le da la espalda"],"h1":"Piense en una palma levantada y un sonido largo.","h2":"El manual de Mississippi dice que un policía suele indicarle que se detenga levantando una mano con la palma hacia usted y dando un pitazo largo con el silbato.","p":"Correcto. Una palma levantada y un pitazo largo significan alto."},"ref":{"doc":"MS","page":40}},{"id":"ms-133","scope":"MS","cat":"signals","sign":null,"c":3,"en":{"q":"The Mississippi manual describes how an officer directing traffic usually tells you to go. What do you hear?","o":["One long whistle blast","No sound at all","A siren","A series of short whistle blasts"],"h1":"Going is shown with a hand motion and quick sounds.","h2":"The Mississippi manual says an officer usually signals you to start or keep going by motioning with one hand and giving a series of short whistle blasts.","p":"Right. Short whistle blasts with a hand motion mean go."},"es":{"q":"El manual de Mississippi describe cómo un policía que dirige el tráfico suele indicarle que avance. ¿Qué escucha usted?","o":["Un pitazo largo","Ningún sonido","Una sirena","Una serie de pitazos cortos"],"h1":"Avanzar se indica con un movimiento de la mano y sonidos rápidos.","h2":"El manual de Mississippi dice que un policía suele indicarle que arranque o siga moviendo una mano y dando una serie de pitazos cortos.","p":"Correcto. Pitazos cortos con un movimiento de la mano significan avanzar."},"ref":{"doc":"MS","page":40}},{"id":"ms-134","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, what is the minimum speed on a four-lane state or U.S. highway?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"It is the same minimum as on interstates.","h2":"In Mississippi, the minimum speed on four-lane state and U.S. highways is 40 mph.","p":"Right. The minimum is 40 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad mínima en una carretera estatal o federal de cuatro carriles?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"Es la misma mínima que en las interestatales.","h2":"En Mississippi, la velocidad mínima en carreteras estatales y federales de cuatro carriles es de 40 mph.","p":"Correcto. La mínima es de 40 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-135","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, what is the top speed for a school bus carrying children on its regular route to and from school?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"It is 20 mph below the school bus limit on the interstate.","h2":"In Mississippi, a school bus taking children to and from school on its regular route may go no faster than 45 mph.","p":"Right. The limit is 45 mph."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima de un autobús escolar que lleva niños en su ruta regular de ida y vuelta a la escuela?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"Son 20 mph menos que el límite del autobús escolar en la interestatal.","h2":"En Mississippi, un autobús escolar que lleva niños a la escuela y de regreso en su ruta regular no puede ir a más de 45 mph.","p":"Correcto. El límite es de 45 mph."},"ref":{"doc":"MS","page":41}},{"id":"ms-136","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, what is the top speed for a school bus on the interstate?","o":["45 mph","55 mph","70 mph","65 mph"],"h1":"It is 5 mph below the interstate limit for cars.","h2":"In Mississippi, the maximum speed for a school bus on the interstate is 65 mph.","p":"Right. A school bus may go up to 65 mph on the interstate."},"es":{"q":"En Mississippi, ¿cuál es la velocidad máxima de un autobús escolar en la interestatal?","o":["45 mph","55 mph","70 mph","65 mph"],"h1":"Son 5 mph menos que el límite interestatal para carros.","h2":"En Mississippi, la velocidad máxima de un autobús escolar en la interestatal es de 65 mph.","p":"Correcto. Un autobús escolar puede ir hasta 65 mph en la interestatal."},"ref":{"doc":"MS","page":41}},{"id":"ms-137","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"The Mississippi manual compares hitting a stone wall at 40 mph to what?","o":["Falling from a chair","Driving off a four-story building","Hitting a parked bicycle","Braking hard on dry pavement"],"h1":"Picture a long fall from a tall building.","h2":"The Mississippi manual says hitting a stone wall at 40 mph has the same impact as driving off a four-story building.","p":"Right. It is like driving off a four-story building."},"es":{"q":"¿Con qué compara el manual de Mississippi chocar contra un muro de piedra a 40 mph?","o":["Caerse de una silla","Caer con el carro desde un edificio de cuatro pisos","Chocar con una bicicleta estacionada","Frenar fuerte en pavimento seco"],"h1":"Imagine una caída larga desde un edificio alto.","h2":"El manual de Mississippi dice que chocar contra un muro de piedra a 40 mph tiene el mismo impacto que caer con el carro desde un edificio de cuatro pisos.","p":"Correcto. Es como caer desde un edificio de cuatro pisos."},"ref":{"doc":"MS","page":41}},{"id":"ms-138","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, is the 70 mph interstate speed limit lower at night?","o":["Yes, it drops to 55 mph","Yes, it drops to 60 mph","No, it is 70 mph both day and night","Yes, it drops to 65 mph"],"h1":"The manual gives one limit for all hours.","h2":"In Mississippi, the interstate speed limit is 70 mph for both day and night, for ideal conditions.","p":"Right. It is 70 mph day and night."},"es":{"q":"En Mississippi, ¿el límite de 70 mph en la interestatal es más bajo de noche?","o":["Sí, baja a 55 mph","Sí, baja a 60 mph","No, es de 70 mph de día y de noche","Sí, baja a 65 mph"],"h1":"El manual da un solo límite para todas las horas.","h2":"En Mississippi, el límite de velocidad en la interestatal es de 70 mph de día y de noche, en condiciones ideales.","p":"Correcto. Es de 70 mph de día y de noche."},"ref":{"doc":"MS","page":70}},{"id":"ms-139","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, when does the 15 mph school zone speed apply as you pass a school?","o":["During recess or while children are arriving or leaving","Only on weekends","Only when a police car is present","All day, every day of the year"],"h1":"It applies when children are likely to be outside or on the street.","h2":"In Mississippi, the 15 mph school zone speed applies when passing a school during recess or while children are arriving at or leaving school.","p":"Right. During recess and arrival or dismissal times."},"es":{"q":"En Mississippi, ¿cuándo se aplica la velocidad de 15 mph de la zona escolar al pasar una escuela?","o":["Durante el recreo o mientras los niños llegan o salen","Solo los fines de semana","Solo cuando hay una patrulla","Todo el día, todos los días del año"],"h1":"Se aplica cuando es probable que los niños estén afuera o en la calle.","h2":"En Mississippi, la velocidad de 15 mph en la zona escolar se aplica al pasar una escuela durante el recreo o mientras los niños llegan o salen.","p":"Correcto. Durante el recreo y las horas de entrada o salida."},"ref":{"doc":"MS","page":31}},{"id":"ms-140","scope":"MS","cat":"signals","sign":null,"c":3,"en":{"q":"The Mississippi manual says a driver behind you wants to pass. Should you turn on your left signal to show it is safe?","o":["Yes, always","Yes, but only on the interstate","Yes, if you are driving slowly","No, the driver behind decides if it is safe to pass"],"h1":"Your signal could be mistaken for a turn.","h2":"The Mississippi manual says not to use your left signal to tell a driver behind you it is safe to pass; that driver must decide.","p":"Right. Do not signal others to pass."},"es":{"q":"El manual de Mississippi dice que un conductor detrás de usted quiere pasar. ¿Debe poner la direccional izquierda para indicarle que es seguro?","o":["Sí, siempre","Sí, pero solo en la interestatal","Sí, si usted va despacio","No, el conductor de atrás decide si es seguro pasar"],"h1":"Su señal podría confundirse con un giro.","h2":"El manual de Mississippi dice que no use la direccional izquierda para indicarle al conductor de atrás que es seguro pasar; esa persona debe decidir.","p":"Correcto. No le haga señales a otros para que pasen."},"ref":{"doc":"MS","page":42}},{"id":"ms-141","scope":"MS","cat":"signals","sign":null,"c":1,"en":{"q":"In Mississippi, your turn signals are broken. You want to move from the left lane to the right lane. Which arm signal do you use?","o":["Arm straight out","Arm bent up at the elbow","Arm pointing down, palm to the rear","Arm waving in circles"],"h1":"Use the same signal as for a right turn.","h2":"In Mississippi, the right-turn arm signal, with the arm bent up at the elbow, is also used to change from the left lane to the right lane.","p":"Right. Arm bent up at the elbow."},"es":{"q":"En Mississippi, sus direccionales no funcionan. Quiere pasar del carril izquierdo al derecho. ¿Qué señal de brazo usa?","o":["Brazo extendido hacia afuera","Brazo doblado hacia arriba en el codo","Brazo hacia abajo con la palma hacia atrás","Brazo moviéndose en círculos"],"h1":"Use la misma señal que para girar a la derecha.","h2":"En Mississippi, la señal de brazo para girar a la derecha, con el brazo doblado hacia arriba en el codo, también se usa para pasar del carril izquierdo al derecho.","p":"Correcto. Brazo doblado hacia arriba en el codo."},"ref":{"doc":"MS","page":42}},{"id":"ms-142","scope":"MS","cat":"signals","sign":null,"c":2,"en":{"q":"In Mississippi, how far before an intersection should you turn on your signal to make a turn?","o":["Just as you start the turn","At least 25 feet","At least 100 feet","At least half a mile"],"h1":"It is about the length of six or seven cars.","h2":"In Mississippi, you should turn on your signal and slow down at least 100 feet before the intersection where you will turn.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Mississippi, ¿a qué distancia antes de una intersección debe poner la direccional para girar?","o":["Justo al empezar el giro","Al menos 25 pies","Al menos 100 pies","Al menos media milla"],"h1":"Es el largo de unos seis o siete carros.","h2":"En Mississippi, debe poner la direccional y bajar la velocidad al menos 100 pies antes de la intersección donde va a girar.","p":"Correcto. Ponga la direccional al menos 100 pies antes."},"ref":{"doc":"MS","page":51}},{"id":"ms-143","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"The Mississippi manual gives a car-length rule for following distance. How much space should you leave?","o":["At least one car length for every 10 mph","One car length at any speed","Two car lengths for every 10 mph","Five car lengths at any speed"],"h1":"At 50 mph, it would be five car lengths.","h2":"The Mississippi manual says to leave at least one car length between you and the vehicle ahead for every 10 mph of speed.","p":"Right. One car length for every 10 mph."},"es":{"q":"El manual de Mississippi da una regla de largos de carro para la distancia de seguimiento. ¿Cuánto espacio debe dejar?","o":["Al menos un largo de carro por cada 10 mph","Un largo de carro a cualquier velocidad","Dos largos de carro por cada 10 mph","Cinco largos de carro a cualquier velocidad"],"h1":"A 50 mph serían cinco largos de carro.","h2":"El manual de Mississippi dice que deje al menos un largo de carro entre usted y el vehículo de adelante por cada 10 mph de velocidad.","p":"Correcto. Un largo de carro por cada 10 mph."},"ref":{"doc":"MS","page":43}},{"id":"ms-144","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, you are driving in a funeral procession. How much space should you leave between your car and the next one?","o":["As little as possible so no one can cut in","Exactly one foot","Enough room for other vehicles to pull in safely","Ten car lengths at all times"],"h1":"Other traffic may need to move into the line.","h2":"The Mississippi manual says that in a motorcade such as a funeral procession, you should leave enough space for other vehicles to pull in safely.","p":"Right. Leave room for others to pull in safely."},"es":{"q":"En Mississippi, usted va en un cortejo fúnebre. ¿Cuánto espacio debe dejar entre su carro y el siguiente?","o":["Lo menos posible para que nadie se meta","Exactamente un pie","Suficiente espacio para que otros vehículos puedan entrar con seguridad","Diez largos de carro en todo momento"],"h1":"Es posible que otros vehículos necesiten meterse en la fila.","h2":"El manual de Mississippi dice que en una caravana, como un cortejo fúnebre, deje suficiente espacio para que otros vehículos puedan entrar con seguridad.","p":"Correcto. Deje espacio para que otros entren con seguridad."},"ref":{"doc":"MS","page":43}},{"id":"ms-145","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, you are driving on a four-lane highway. Which lane should you normally use?","o":["The left lane","The right lane, except to pass or to turn left","Either lane, it does not matter","The lane with less traffic"],"h1":"The left lane is for passing and left turns.","h2":"In Mississippi, on a four-lane highway you should drive in the right lane except when passing or preparing to turn left.","p":"Right. Use the right lane except to pass or turn left."},"es":{"q":"En Mississippi, usted maneja en una carretera de cuatro carriles. ¿Qué carril debe usar normalmente?","o":["El carril izquierdo","El carril derecho, excepto para pasar o girar a la izquierda","Cualquiera, no importa","El carril con menos tráfico"],"h1":"El carril izquierdo es para pasar y girar a la izquierda.","h2":"En Mississippi, en una carretera de cuatro carriles debe usar el carril derecho, excepto para pasar o prepararse para girar a la izquierda.","p":"Correcto. Use el carril derecho excepto para pasar o girar a la izquierda."},"ref":{"doc":"MS","page":45}},{"id":"ms-146","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, you want to turn left from a multi-lane road with no turn lane. Which lane should you use?","o":["The right lane","The shoulder","Any lane","The lane next to the center"],"h1":"Get as close as you can to the center line.","h2":"In Mississippi, if there is no turn lane, use the lane next to the center to turn left.","p":"Right. Use the lane next to the center."},"es":{"q":"En Mississippi, usted quiere girar a la izquierda desde un camino de varios carriles sin carril de giro. ¿Qué carril debe usar?","o":["El carril derecho","El acotamiento","Cualquier carril","El carril junto al centro"],"h1":"Acérquese lo más posible a la línea central.","h2":"En Mississippi, si no hay carril de giro, use el carril junto al centro para girar a la izquierda.","p":"Correcto. Use el carril junto al centro."},"ref":{"doc":"MS","page":45}},{"id":"ms-147","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, may you cross the center line of a four-lane highway to pass another vehicle?","o":["No, it is never legal","Yes, if the line is broken","Yes, if no cars are coming","Yes, during daylight"],"h1":"Passing on a four-lane highway uses the lanes going your way.","h2":"In Mississippi, it is never legal to move across the center line of a four-lane highway to pass another vehicle.","p":"Right. It is never legal."},"es":{"q":"En Mississippi, ¿puede cruzar la línea central de una carretera de cuatro carriles para pasar a otro vehículo?","o":["No, nunca es legal","Sí, si la línea es discontinua","Sí, si no vienen carros","Sí, de día"],"h1":"Para pasar en una carretera de cuatro carriles se usan los carriles de su sentido.","h2":"En Mississippi, nunca es legal cruzar la línea central de una carretera de cuatro carriles para pasar a otro vehículo.","p":"Correcto. Nunca es legal."},"ref":{"doc":"MS","page":47}},{"id":"ms-148","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, on a two-lane road, when may you pass a vehicle on the right?","o":["When it is going slowly","When the shoulder is wide","When it is making or about to make a left turn","Never"],"h1":"The vehicle ahead is moving out of your way.","h2":"In Mississippi, you may pass on the right when the vehicle ahead is making or about to make a left turn, if it is safe.","p":"Right. When it is turning left."},"es":{"q":"En Mississippi, en un camino de dos carriles, ¿cuándo puede pasar a un vehículo por la derecha?","o":["Cuando va despacio","Cuando el acotamiento es ancho","Cuando está girando o por girar a la izquierda","Nunca"],"h1":"El vehículo de adelante se está quitando de su camino.","h2":"En Mississippi, puede pasar por la derecha cuando el vehículo de adelante está girando o por girar a la izquierda, si es seguro.","p":"Correcto. Cuando está girando a la izquierda."},"ref":{"doc":"MS","page":47}},{"id":"ms-149","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, a car ahead is turning left and you pass on the right. May you drive on the shoulder to do it?","o":["Yes, if you go slowly","No, you may never drive off the pavement or on the shoulder to pass","Yes, if the shoulder is paved","Yes, at night"],"h1":"Passing must stay on the road.","h2":"In Mississippi, you are never allowed to drive off the pavement or on the shoulder to pass.","p":"Right. Never use the shoulder to pass."},"es":{"q":"En Mississippi, un carro adelante gira a la izquierda y usted lo pasa por la derecha. ¿Puede usar el acotamiento para hacerlo?","o":["Sí, si va despacio","No, nunca puede salirse del pavimento ni usar el acotamiento para pasar","Sí, si el acotamiento está pavimentado","Sí, de noche"],"h1":"Para pasar debe quedarse en la calzada.","h2":"En Mississippi, nunca se permite salirse del pavimento ni manejar por el acotamiento para pasar.","p":"Correcto. Nunca use el acotamiento para pasar."},"ref":{"doc":"MS","page":47}},{"id":"ms-150","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, how close to a bridge, railroad crossing or intersection may you pass another vehicle?","o":["Within 25 feet","Within 50 feet","Right up to it","Not within 100 feet"],"h1":"The no-passing distance is a round number.","h2":"In Mississippi, you must not pass within 100 feet of bridges, viaducts, overpasses, railroad crossings, crosswalks or intersections.","p":"Right. Do not pass within 100 feet."},"es":{"q":"En Mississippi, ¿a qué distancia de un puente, un cruce de ferrocarril o una intersección puede pasar a otro vehículo?","o":["A menos de 25 pies","A menos de 50 pies","Hasta llegar a él","No a menos de 100 pies"],"h1":"La distancia sin rebasar es un número redondo.","h2":"En Mississippi, no debe pasar a otro vehículo a menos de 100 pies de puentes, viaductos, pasos elevados, cruces de ferrocarril, cruces peatonales o intersecciones.","p":"Correcto. No pase a menos de 100 pies."},"ref":{"doc":"MS","page":47}},{"id":"ms-151","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, you are being passed on a two-lane highway. What should you do?","o":["Keep to the right and do not speed up","Speed up to help the other driver","Move toward the center line","Brake hard"],"h1":"Make the pass easier, not harder.","h2":"In Mississippi, when you are being passed on a two-lane or three-lane highway, keep to the right and do not increase your speed until the other car has passed.","p":"Right. Keep right and do not speed up."},"es":{"q":"En Mississippi, otro carro lo está pasando en una carretera de dos carriles. ¿Qué debe hacer?","o":["Mantenerse a la derecha y no acelerar","Acelerar para ayudar al otro conductor","Acercarse a la línea central","Frenar fuerte"],"h1":"Facilite el rebase, no lo haga más difícil.","h2":"En Mississippi, cuando lo están pasando en una carretera de dos o tres carriles, manténgase a la derecha y no aumente la velocidad hasta que el otro carro termine de pasar.","p":"Correcto. Manténgase a la derecha y no acelere."},"ref":{"doc":"MS","page":47}},{"id":"ms-152","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, you pass a car on the left. Before you move back into the right lane, what should you see?","o":["The other car's roof","The other driver waving","The car you passed in your rearview mirror","The center line"],"h1":"Use your inside mirror.","h2":"In Mississippi, before moving back into the right lane after passing, make sure you can see the vehicle you passed in your rearview mirror.","p":"Right. See the passed car in your rearview mirror."},"es":{"q":"En Mississippi, usted pasa a un carro por la izquierda. Antes de volver al carril derecho, ¿qué debe ver?","o":["El techo del otro carro","Al otro conductor saludando","El carro que pasó en su espejo retrovisor","La línea central"],"h1":"Use el espejo interior.","h2":"En Mississippi, antes de volver al carril derecho después de pasar, asegúrese de ver en su espejo retrovisor el vehículo que pasó.","p":"Correcto. Vea el carro que pasó en su espejo retrovisor."},"ref":{"doc":"MS","page":47}},{"id":"ms-153","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, you need to turn your car around in a narrow street. How does the manual say to begin?","o":["From the left side, backing up first","From the far right side, signal, turn the wheel sharply left and inch forward","From the middle of the road, turning right","By backing into a driveway"],"h1":"Start on the right edge and head to the left.","h2":"In Mississippi, to turn around in a tight space, start from the far right side of the road, signal, and turn the wheel sharply left while inching forward.","p":"Right. Start from the far right and turn sharply left."},"es":{"q":"En Mississippi, necesita dar la vuelta con su carro en una calle angosta. ¿Cómo dice el manual que debe empezar?","o":["Desde el lado izquierdo, retrocediendo primero","Desde el extremo derecho, con la direccional, girando el volante bien a la izquierda y avanzando poco a poco","Desde el medio del camino, girando a la derecha","Retrocediendo hacia una entrada de carros"],"h1":"Empiece en la orilla derecha y vaya hacia la izquierda.","h2":"En Mississippi, para dar la vuelta en un espacio estrecho, empiece desde el extremo derecho del camino, ponga la direccional y gire el volante bien a la izquierda mientras avanza poco a poco.","p":"Correcto. Empiece desde el extremo derecho y gire bien a la izquierda."},"ref":{"doc":"MS","page":49}},{"id":"ms-154","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, you are making a left turn from a two-way street onto another two-way street. Where should you enter the new street?","o":["In the far right lane","On the shoulder","In any open lane","Just to the right of its center line"],"h1":"Do not cut the corner, and do not swing wide.","h2":"In Mississippi, when making a left turn, enter the new street just to the right of its center line.","p":"Right. Enter just to the right of center."},"es":{"q":"En Mississippi, usted gira a la izquierda de una calle de doble sentido a otra calle de doble sentido. ¿Por dónde debe entrar a la nueva calle?","o":["Por el carril del extremo derecho","Por el acotamiento","Por cualquier carril libre","Justo a la derecha de la línea central"],"h1":"No corte la esquina ni se abra demasiado.","h2":"En Mississippi, al girar a la izquierda, entre a la nueva calle justo a la derecha de su línea central.","p":"Correcto. Entre justo a la derecha del centro."},"ref":{"doc":"MS","page":51}},{"id":"ms-155","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, you and an oncoming driver both want to turn left at the same intersection. How should you turn?","o":["Each driver turns to the left of the other","Each driver turns behind the other","The driver who signaled first turns while the other waits on the shoulder","Both drivers wait for a green arrow"],"h1":"Leave from the left lane and enter the left lane, keeping the other driver on your right.","h2":"In Mississippi, when two opposing drivers both turn left, each should turn to the left of the other.","p":"Right. Each driver turns to the left of the other."},"es":{"q":"En Mississippi, usted y un conductor que viene de frente quieren girar a la izquierda en la misma intersección. ¿Cómo deben girar?","o":["Cada conductor gira a la izquierda del otro","Cada conductor gira por detrás del otro","Gira quien puso primero la direccional mientras el otro espera en el acotamiento","Ambos esperan una flecha verde"],"h1":"Salga del carril izquierdo y entre al carril izquierdo, dejando al otro conductor a su derecha.","h2":"En Mississippi, cuando dos conductores que vienen de frente giran a la izquierda, cada uno debe girar a la izquierda del otro.","p":"Correcto. Cada conductor gira a la izquierda del otro."},"ref":{"doc":"MS","page":54}},{"id":"ms-156","scope":"MS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Mississippi, you are on a one-way street and want to turn. Which lane is usually best to turn from?","o":["The middle lane","Any lane","The lane nearest the curb on the side you are turning to","The lane farthest from the curb"],"h1":"Turn from the edge closest to your turn, unless markings allow more lanes.","h2":"In Mississippi, on a one-way street you should usually turn from the lane nearest the curb, unless markings or signs allow other lanes.","p":"Right. Turn from the lane nearest the curb."},"es":{"q":"En Mississippi, usted va por una calle de un solo sentido y quiere girar. ¿Desde qué carril es mejor girar normalmente?","o":["El carril del medio","Cualquier carril","El carril más cerca de la acera del lado hacia donde gira","El carril más lejos de la acera"],"h1":"Gire desde la orilla más cercana a su giro, a menos que las marcas permitan más carriles.","h2":"En Mississippi, en una calle de un solo sentido normalmente debe girar desde el carril más cercano a la acera, a menos que las marcas o señales permitan otros carriles.","p":"Correcto. Gire desde el carril más cercano a la acera."},"ref":{"doc":"MS","page":54}},{"id":"ms-157","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, two cars arrive at a four-way stop at the same time. Which one goes first?","o":["The one on the left","The one on the right","The larger vehicle","The one going faster"],"h1":"Yield to the driver on your right.","h2":"In Mississippi, at a four-way stop the first vehicle to arrive goes first; if two arrive at the same time, the vehicle on the right has the right of way.","p":"Right. The vehicle on the right goes first."},"es":{"q":"En Mississippi, dos carros llegan al mismo tiempo a un alto de cuatro vías. ¿Cuál pasa primero?","o":["El de la izquierda","El de la derecha","El vehículo más grande","El que va más rápido"],"h1":"Ceda el paso al conductor de su derecha.","h2":"En Mississippi, en un alto de cuatro vías pasa primero quien llega primero; si dos llegan al mismo tiempo, el vehículo de la derecha tiene el derecho de paso.","p":"Correcto. Pasa primero el vehículo de la derecha."},"ref":{"doc":"MS","page":56}},{"id":"ms-158","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, at a two-way stop, two drivers arrive at their stop signs at the same time. One will go straight across and the other will turn across that lane. Who goes first?","o":["The driver who turns","The driver who honks","The driver with the newer car","The driver going straight across"],"h1":"The turning driver must wait.","h2":"In Mississippi, at a two-way stop, if two vehicles arrive at the same time, the one going straight across has the right of way and the one turning across must yield.","p":"Right. The driver going straight goes first."},"es":{"q":"En Mississippi, en un alto de dos vías, dos conductores llegan al mismo tiempo a sus señales de alto. Uno va a cruzar derecho y el otro va a girar cruzando ese carril. ¿Quién pasa primero?","o":["El que gira","El que toca la bocina","El del carro más nuevo","El que cruza derecho"],"h1":"El que gira debe esperar.","h2":"En Mississippi, en un alto de dos vías, si dos vehículos llegan al mismo tiempo, el que cruza derecho tiene el derecho de paso y el que gira debe ceder.","p":"Correcto. Pasa primero el que va derecho."},"ref":{"doc":"MS","page":56}},{"id":"ms-159","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, you are pulling onto a street from a driveway. There is no stop sign. What must you do?","o":["Stop and yield to traffic on the street","Pull out quickly before cars come","Honk and pull out","Yield only to trucks"],"h1":"A missing stop sign does not give you the right of way.","h2":"In Mississippi, when you enter a street from a driveway or other entrance, you must stop and yield to oncoming traffic, even with no stop sign.","p":"Right. Stop and yield to traffic."},"es":{"q":"En Mississippi, usted sale a una calle desde una entrada de carros. No hay señal de alto. ¿Qué debe hacer?","o":["Detenerse y ceder el paso al tráfico de la calle","Salir rápido antes de que vengan carros","Tocar la bocina y salir","Ceder solo a los camiones"],"h1":"Que no haya señal de alto no le da el derecho de paso.","h2":"En Mississippi, cuando entra a una calle desde una entrada de carros u otro acceso, debe detenerse y ceder el paso al tráfico, aunque no haya señal de alto.","p":"Correcto. Deténgase y ceda el paso."},"ref":{"doc":"MS","page":57}},{"id":"ms-160","scope":"MS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Mississippi, you reach a highway intersection with no signs or signals. What should you do?","o":["Speed up to clear it fast","Expect others to stop for you","Yield to approaching traffic, then go when it is safe","Stop and wait for a police officer"],"h1":"Nobody is told to stop, so be ready to let others go.","h2":"In Mississippi, at a highway intersection with no traffic signs or signals, yield to approaching traffic and go only when it is safe.","p":"Right. Yield to approaching traffic first."},"es":{"q":"En Mississippi, usted llega a una intersección de carretera sin señales ni semáforos. ¿Qué debe hacer?","o":["Acelerar para cruzar rápido","Esperar que los demás se detengan por usted","Ceder el paso al tráfico que se acerca y seguir cuando sea seguro","Detenerse y esperar a un policía"],"h1":"Nadie tiene orden de detenerse, así que esté listo para dejar pasar a otros.","h2":"En Mississippi, en una intersección de carretera sin señales ni semáforos, ceda el paso al tráfico que se acerca y siga solo cuando sea seguro.","p":"Correcto. Primero ceda el paso al tráfico que se acerca."},"ref":{"doc":"MS","page":57}},{"id":"ms-161","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, you are on a two-lane road. A school bus coming toward you stops with red lights flashing. What must you do?","o":["Keep going slowly","Stop, because you must stop no matter which way you are going","Stop only if children are on your side","Honk and pass"],"h1":"Only a divided highway with four or more lanes has an exception.","h2":"In Mississippi, you must stop for a school bus with flashing red lights no matter which direction you are traveling, unless you are on the opposite side of a divided highway.","p":"Right. You must stop, whichever way you are going."},"es":{"q":"En Mississippi, usted va por un camino de dos carriles. Un autobús escolar que viene de frente se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Seguir despacio","Detenerse, porque debe detenerse sin importar su dirección","Detenerse solo si hay niños de su lado","Tocar la bocina y pasar"],"h1":"Solo una carretera dividida de cuatro carriles o más tiene una excepción.","h2":"En Mississippi, debe detenerse ante un autobús escolar con luces rojas intermitentes sin importar en qué dirección viaja, a menos que esté del otro lado de una carretera dividida.","p":"Correcto. Debe detenerse, vaya en la dirección que vaya."},"ref":{"doc":"MS","page":58}},{"id":"ms-162","scope":"MS","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Mississippi, you stopped for a school bus. The children have crossed. When may you go?","o":["As soon as the children reach the sidewalk","After 30 seconds","When the driver waves","When the bus moves again, its red lights stop flashing and its stop sign is pulled in"],"h1":"Wait for all the signs that the stop is over.","h2":"In Mississippi, stay stopped until the children have crossed and the bus has started moving, its red lights stop flashing and its stop sign is retracted.","p":"Right. Wait until the bus moves and its lights and stop sign are off."},"es":{"q":"En Mississippi, usted se detuvo por un autobús escolar. Los niños ya cruzaron. ¿Cuándo puede seguir?","o":["En cuanto los niños lleguen a la acera","Después de 30 segundos","Cuando el chofer le haga señas","Cuando el autobús vuelva a moverse, sus luces rojas dejen de parpadear y retire su señal de alto"],"h1":"Espere todas las señales de que la parada terminó.","h2":"En Mississippi, quédese detenido hasta que los niños crucen y el autobús arranque, sus luces rojas dejen de parpadear y retire su señal de alto.","p":"Correcto. Espere a que el autobús arranque y apague las luces y la señal de alto."},"ref":{"doc":"MS","page":58}},{"id":"ms-163","scope":"MS","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Mississippi, a school bus stops in a loading zone beside the highway where people are not allowed to cross the road. Must you stop?","o":["No, you do not have to stop there","Yes, always","Yes, for one minute","Only if you are behind it"],"h1":"The rule is about children crossing the road.","h2":"In Mississippi, if a school bus stops in a loading zone that is part of or next to the highway and pedestrians may not cross there, you do not have to stop.","p":"Right. You do not have to stop there."},"es":{"q":"En Mississippi, un autobús escolar se detiene en una zona de carga junto a la carretera donde no se permite que las personas crucen. ¿Debe detenerse?","o":["No, no tiene que detenerse allí","Sí, siempre","Sí, por un minuto","Solo si va detrás de él"],"h1":"La regla tiene que ver con niños que cruzan el camino.","h2":"En Mississippi, si un autobús escolar se detiene en una zona de carga que es parte de la carretera o está junto a ella y allí no se permite cruzar a los peatones, no tiene que detenerse.","p":"Correcto. No tiene que detenerse allí."},"ref":{"doc":"MS","page":58}},{"id":"ms-164","scope":"MS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Mississippi, you see a person at a crosswalk with a white cane that has a red tip. What does it tell you?","o":["The person is a crossing guard","The person is selling something","The person may be blind or have low vision","The person wants a ride"],"h1":"Take every care and stop if needed.","h2":"In Mississippi, a white cane, which may have a red tip, shows a person who is blind or has a visual impairment, so take every precaution and stop if needed.","p":"Right. The person may be blind or have low vision."},"es":{"q":"En Mississippi, usted ve a una persona en un cruce peatonal con un bastón blanco de punta roja. ¿Qué le indica?","o":["Es un guardia de cruce","La persona vende algo","La persona puede ser ciega o tener baja visión","La persona quiere que la lleven"],"h1":"Tenga todo el cuidado y deténgase si hace falta.","h2":"En Mississippi, un bastón blanco, que puede tener la punta roja, indica una persona ciega o con discapacidad visual, así que tome todas las precauciones y deténgase si hace falta.","p":"Correcto. La persona puede ser ciega o tener baja visión."},"ref":{"doc":"MS","page":59}},{"id":"ms-165","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, is yielding to a funeral procession required by law?","o":["Yes, with a fine if you do not","No, but it is common courtesy","Only in cities","Only on Sundays"],"h1":"The manual calls it a courtesy.","h2":"In Mississippi, yielding to a funeral procession is not required by law, but it is common courtesy.","p":"Right. It is courtesy, not law."},"es":{"q":"En Mississippi, ¿la ley exige ceder el paso a un cortejo fúnebre?","o":["Sí, con multa si no lo hace","No, pero es una cortesía común","Solo en las ciudades","Solo los domingos"],"h1":"El manual lo llama una cortesía.","h2":"En Mississippi, la ley no exige ceder el paso a un cortejo fúnebre, pero es una cortesía común.","p":"Correcto. Es cortesía, no ley."},"ref":{"doc":"MS","page":59}},{"id":"ms-166","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, there is a sign at a fire station. How close to its driveway entrance may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 75 feet"],"h1":"With a sign, the distance is much longer than the usual 20 feet.","h2":"In Mississippi, you may not park within 20 feet of a fire station driveway, or within 75 feet when a sign says so.","p":"Right. With a sign, stay 75 feet away."},"es":{"q":"En Mississippi, hay un letrero en una estación de bomberos. ¿A qué distancia de su entrada puede estacionarse?","o":["No a menos de 10 pies","No a menos de 20 pies","No a menos de 30 pies","No a menos de 75 pies"],"h1":"Con letrero, la distancia es mucho mayor que los 20 pies normales.","h2":"En Mississippi, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos, o a menos de 75 pies si un letrero lo indica.","p":"Correcto. Con letrero, quédese a 75 pies."},"ref":{"doc":"MS","page":60}},{"id":"ms-167","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, may you stop and leave your car next to another car that is parked at the curb (double parking)?","o":["No, you may not park on the roadway side of a parked vehicle","Yes, for up to 10 minutes","Yes, with your flashers on","Yes, at night"],"h1":"That would block a traffic lane.","h2":"In Mississippi, you may not park on the roadway side of any vehicle stopped or parked at the edge of the road or curb.","p":"Right. Double parking is not allowed."},"es":{"q":"En Mississippi, ¿puede detenerse y dejar su carro junto a otro carro estacionado en la acera (doble fila)?","o":["No, no puede estacionarse del lado de la calle de un vehículo estacionado","Sí, hasta 10 minutos","Sí, con las luces intermitentes","Sí, de noche"],"h1":"Eso bloquearía un carril de tráfico.","h2":"En Mississippi, no puede estacionarse del lado de la calzada de ningún vehículo detenido o estacionado a la orilla del camino o en la acera.","p":"Correcto. No se permite estacionar en doble fila."},"ref":{"doc":"MS","page":60}},{"id":"ms-168","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, which of these is a place where you may never park?","o":["In a parking lot","Along a quiet street, 40 feet from a hydrant","On a bridge","In your own driveway"],"h1":"Think of a raised structure over water or a road.","h2":"In Mississippi, you may not park on any bridge or elevated structure, or in a highway underpass.","p":"Right. Never park on a bridge."},"es":{"q":"En Mississippi, ¿en cuál de estos lugares nunca puede estacionarse?","o":["En un estacionamiento","En una calle tranquila, a 40 pies de un hidrante","Sobre un puente","En la entrada de su propia casa"],"h1":"Piense en una estructura elevada sobre agua o un camino.","h2":"En Mississippi, no puede estacionarse sobre ningún puente o estructura elevada, ni en un paso a desnivel de carretera.","p":"Correcto. Nunca se estacione sobre un puente."},"ref":{"doc":"MS","page":60}},{"id":"ms-169","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, you must park along a highway outside a town. If possible, how much room should you leave for other vehicles to get by?","o":["5 feet","20 feet","50 feet","100 feet"],"h1":"About the width of two lanes.","h2":"In Mississippi, when you park along a highway, pull all the way off and, if possible, leave at least 20 feet for other vehicles to get by.","p":"Right. Leave at least 20 feet."},"es":{"q":"En Mississippi, debe estacionarse junto a una carretera fuera de un pueblo. Si es posible, ¿cuánto espacio debe dejar para que pasen otros vehículos?","o":["5 pies","20 pies","50 pies","100 pies"],"h1":"Más o menos el ancho de dos carriles.","h2":"En Mississippi, cuando se estaciona junto a una carretera, salga por completo de la calzada y, si es posible, deje al menos 20 pies para que pasen otros vehículos.","p":"Correcto. Deje al menos 20 pies."},"ref":{"doc":"MS","page":60}},{"id":"ms-170","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, you park along a highway. From how far away in both directions should other drivers be able to see your car?","o":["50 feet","100 feet","150 feet","200 feet"],"h1":"It is the same distance a horn must be heard.","h2":"In Mississippi, if you park along a highway, park where you can be seen from at least 200 feet in both directions.","p":"Right. Be visible from 200 feet both ways."},"es":{"q":"En Mississippi, usted se estaciona junto a una carretera. ¿Desde qué distancia en ambas direcciones deben poder ver su carro los demás?","o":["50 pies","100 pies","150 pies","200 pies"],"h1":"Es la misma distancia a la que se debe oír una bocina.","h2":"En Mississippi, si se estaciona junto a una carretera, hágalo donde lo puedan ver desde al menos 200 pies en ambas direcciones.","p":"Correcto. Debe verse desde 200 pies en ambas direcciones."},"ref":{"doc":"MS","page":60}},{"id":"ms-171","scope":"MS","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Mississippi, you park on a blind curve. What can happen?","o":["You may be arrested and your car may be towed","Nothing, if your flashers are on","You get a warning only","Nothing during the day"],"h1":"It is illegal because others cannot see your car in time.","h2":"In Mississippi, parking on a blind curve or other dangerous place is illegal; you may be arrested and your vehicle may be towed.","p":"Right. You may be arrested and towed."},"es":{"q":"En Mississippi, usted se estaciona en una curva sin visibilidad. ¿Qué puede pasar?","o":["Lo pueden arrestar y remolcar su carro","Nada, si tiene las luces intermitentes","Solo una advertencia","Nada de día"],"h1":"Es ilegal porque los demás no pueden ver su carro a tiempo.","h2":"En Mississippi, estacionarse en una curva sin visibilidad u otro lugar peligroso es ilegal; lo pueden arrestar y remolcar su vehículo.","p":"Correcto. Lo pueden arrestar y remolcar."},"ref":{"doc":"MS","page":60}},{"id":"ms-172","scope":"MS","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Mississippi, you park a car with a manual (standard) transmission. Which gear does the manual say to leave it in?","o":["Neutral","Reverse only on hills","Low gear","Third gear"],"h1":"With an automatic it would be park.","h2":"In Mississippi, when you park, put an automatic in park or a standard transmission in low, set the parking brake and turn off the ignition.","p":"Right. Leave a standard transmission in low."},"es":{"q":"En Mississippi, usted estaciona un carro de transmisión manual (estándar). ¿En qué marcha dice el manual que lo deje?","o":["Neutral","Reversa solo en cuestas","Primera (baja)","Tercera"],"h1":"Con un automático sería 'park'.","h2":"En Mississippi, al estacionar, ponga un automático en 'park' o una transmisión estándar en primera (baja), ponga el freno de estacionamiento y apague el motor.","p":"Correcto. Deje la transmisión estándar en primera."},"ref":{"doc":"MS","page":60}},{"id":"ms-173","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, you parallel park on a busy street. Which side should you use to load and unload your car?","o":["The street side","The curb side","Either side","The trunk only"],"h1":"Stay away from moving traffic.","h2":"In Mississippi, use extreme care when getting out on the street side, and unload your vehicle from the curb side.","p":"Right. Unload from the curb side."},"es":{"q":"En Mississippi, usted se estaciona en paralelo en una calle con mucho tráfico. ¿De qué lado debe cargar y descargar su carro?","o":["Del lado de la calle","Del lado de la acera","De cualquier lado","Solo por la cajuela"],"h1":"Manténgase lejos del tráfico en movimiento.","h2":"En Mississippi, tenga mucho cuidado al bajarse del lado de la calle, y descargue su vehículo del lado de la acera.","p":"Correcto. Descargue del lado de la acera."},"ref":{"doc":"MS","page":61}},{"id":"ms-174","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Mississippi, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Straight ahead","To the right","It does not matter","To the left"],"h1":"The back of the front tire should rest against the curb if the car rolls.","h2":"In Mississippi, when you park uphill with a curb, turn your wheels sharply to the left.","p":"Right. Uphill with a curb, turn the wheels left."},"es":{"q":"En Mississippi, usted se estaciona cuesta arriba junto a la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Derechas","Hacia la derecha","No importa","Hacia la izquierda"],"h1":"La parte trasera de la llanta delantera debe quedar contra la acera si el carro rueda.","h2":"En Mississippi, cuando se estaciona cuesta arriba con acera, gire las ruedas bien hacia la izquierda.","p":"Correcto. Cuesta arriba con acera, ruedas a la izquierda."},"ref":{"doc":"MS","page":62}},{"id":"ms-175","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["To the left","To the right","Straight ahead","It does not matter"],"h1":"Turn them toward the curb.","h2":"In Mississippi, when you park downhill, turn your wheels sharply to the right, whether or not there is a curb.","p":"Right. Downhill, turn the wheels to the right."},"es":{"q":"En Mississippi, usted se estaciona cuesta abajo junto a la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la izquierda","Hacia la derecha","Derechas","No importa"],"h1":"Gírelas hacia la acera.","h2":"En Mississippi, cuando se estaciona cuesta abajo, gire las ruedas bien hacia la derecha, haya acera o no.","p":"Correcto. Cuesta abajo, ruedas a la derecha."},"ref":{"doc":"MS","page":62}},{"id":"ms-176","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, besides from sunset to sunrise, when should you turn on your headlights?","o":["Only when it rains hard","Only on the interstate","Any time you cannot see clearly 500 feet ahead","Only in tunnels"],"h1":"Think of the distance you need to see ahead.","h2":"In Mississippi, use your headlights from sunset to sunrise and any other time you cannot see clearly ahead for 500 feet.","p":"Right. Whenever you cannot see 500 feet ahead."},"es":{"q":"En Mississippi, además de desde la puesta hasta la salida del sol, ¿cuándo debe encender los faros?","o":["Solo cuando llueve fuerte","Solo en la interestatal","Siempre que no pueda ver claramente 500 pies adelante","Solo en túneles"],"h1":"Piense en la distancia que necesita ver hacia adelante.","h2":"En Mississippi, use los faros desde la puesta hasta la salida del sol y en cualquier otro momento en que no pueda ver claramente 500 pies adelante.","p":"Correcto. Siempre que no pueda ver 500 pies adelante."},"ref":{"doc":"MS","page":63}},{"id":"ms-177","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, it is getting dark. May you drive with only your parking lights on?","o":["Yes, until full dark","No, if you need lights, use your headlights","Yes, in town","Yes, if you drive slowly"],"h1":"Parking lights are not made for driving.","h2":"In Mississippi, do not drive with only your parking lights on; if you need lights, use your headlights.","p":"Right. Use headlights, not just parking lights."},"es":{"q":"En Mississippi, está oscureciendo. ¿Puede manejar solo con las luces de estacionamiento?","o":["Sí, hasta que oscurezca del todo","No, si necesita luces, use los faros","Sí, en el pueblo","Sí, si maneja despacio"],"h1":"Las luces de estacionamiento no son para manejar.","h2":"En Mississippi, no maneje solo con las luces de estacionamiento; si necesita luces, use los faros.","p":"Correcto. Use los faros, no solo las luces de estacionamiento."},"ref":{"doc":"MS","page":63}},{"id":"ms-178","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Mississippi, at night you meet an oncoming vehicle with one headlight missing. What should you do?","o":["Flash your high beams","Move toward the center line","Stop on the road","Drive to the far right of your lane"],"h1":"You cannot tell how wide it is, so give it room.","h2":"In Mississippi, if you meet a vehicle at night with one headlight missing, drive to the far right of your lane.","p":"Right. Move to the far right of your lane."},"es":{"q":"En Mississippi, de noche usted se cruza con un vehículo que tiene un faro apagado. ¿Qué debe hacer?","o":["Hacerle cambio de luces altas","Acercarse a la línea central","Detenerse en el camino","Manejar lo más a la derecha de su carril"],"h1":"No puede saber qué tan ancho es, así que déle espacio.","h2":"En Mississippi, si de noche se cruza con un vehículo al que le falta un faro, maneje lo más a la derecha de su carril.","p":"Correcto. Muévase lo más a la derecha de su carril."},"ref":{"doc":"MS","page":63}},{"id":"ms-179","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"Under Mississippi law, who in a moving car must wear a seat belt?","o":["The driver and every passenger, front and back","Only the driver","Only people in the front seat","Only passengers under 18"],"h1":"The law does not stop at the front seat.","h2":"Under Mississippi law, the driver and all passengers must wear a properly fastened seat belt, whether they sit in the front or the back.","p":"Right. Everyone in the car, front and back."},"es":{"q":"Según la ley de Mississippi, ¿quién debe usar el cinturón de seguridad en un carro en movimiento?","o":["El conductor y todos los pasajeros, adelante y atrás","Solo el conductor","Solo los que van en el asiento delantero","Solo los pasajeros menores de 18 años"],"h1":"La ley no se limita al asiento delantero.","h2":"Según la ley de Mississippi, el conductor y todos los pasajeros deben usar el cinturón bien abrochado, vayan adelante o atrás.","p":"Correcto. Todos en el carro, adelante y atrás."},"ref":{"doc":"MS","page":64}},{"id":"ms-180","scope":"MS","cat":"safe-driving","sign":null,"c":3,"en":{"q":"The Mississippi manual says children under what age should always ride in the back seat?","o":["5","8","10","13"],"h1":"It is the age when a child becomes a teenager.","h2":"The Mississippi manual says children under 13 should always ride in the back seat.","p":"Right. Children under 13 belong in the back seat."},"es":{"q":"Según el manual de Mississippi, ¿hasta qué edad (menores de cuántos años) los niños siempre deben ir en el asiento trasero?","o":["5","8","10","13"],"h1":"Es la edad en que un niño se vuelve adolescente.","h2":"El manual de Mississippi dice que los niños menores de 13 años siempre deben ir en el asiento trasero.","p":"Correcto. Los menores de 13 años van atrás."},"ref":{"doc":"MS","page":64}},{"id":"ms-181","scope":"MS","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Mississippi, your car breaks down on a highway and you must walk for help. Where should you walk?","o":["On the right side, with traffic","On the left side, facing oncoming traffic","In the middle of the median","Across the interstate to the other side"],"h1":"You want to see the cars coming at you.","h2":"In Mississippi, if you must walk for help, walk on the left side of the highway facing oncoming traffic, and never cross an interstate.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Mississippi, su carro se descompone en una carretera y debe caminar para buscar ayuda. ¿Por dónde debe caminar?","o":["Por el lado derecho, en el sentido del tráfico","Por el lado izquierdo, de frente al tráfico","Por el medio de la mediana","Cruzando la interestatal al otro lado"],"h1":"Usted quiere ver los carros que vienen hacia usted.","h2":"En Mississippi, si debe caminar para buscar ayuda, camine por el lado izquierdo de la carretera de frente al tráfico, y nunca cruce una interestatal.","p":"Correcto. Camine por la izquierda, de frente al tráfico."},"ref":{"doc":"MS","page":65}},{"id":"ms-182","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, after a crash, what must you give the other people involved?","o":["Only your phone number","Your Social Security number","Your name, address, license plate number and insurance information","Nothing until the police arrive"],"h1":"They need to know who you are, which car, and who insures it.","h2":"In Mississippi, after a crash give the others involved your name, address, license plate number and insurance information, and get theirs too.","p":"Right. Name, address, plate number and insurance information."},"es":{"q":"En Mississippi, después de un choque, ¿qué debe darles a las otras personas involucradas?","o":["Solo su número de teléfono","Su número de Seguro Social","Su nombre, dirección, número de placa e información del seguro","Nada hasta que llegue la policía"],"h1":"Necesitan saber quién es usted, qué carro y quién lo asegura.","h2":"En Mississippi, después de un choque dé a los demás involucrados su nombre, dirección, número de placa e información del seguro, y pida los de ellos también.","p":"Correcto. Nombre, dirección, número de placa e información del seguro."},"ref":{"doc":"MS","page":66}},{"id":"ms-183","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, you were in a crash that was not your fault, but you have no proof of insurance. What can happen?","o":["You can still be cited for not having proof of insurance","Nothing, because it was not your fault","Only the other driver can be cited","You get a free 30-day grace period"],"h1":"Being the victim does not excuse missing proof.","h2":"In Mississippi, you must show proof of insurance to the officer at a crash, and you may be cited without it even if you are not at fault.","p":"Right. You can be cited even if it was not your fault."},"es":{"q":"En Mississippi, usted tuvo un choque que no fue su culpa, pero no tiene prueba de seguro. ¿Qué puede pasar?","o":["Igual le pueden dar una multa por no tener prueba de seguro","Nada, porque no fue su culpa","Solo pueden multar al otro conductor","Recibe 30 días de gracia gratis"],"h1":"Ser la víctima no lo excusa de no tener la prueba.","h2":"En Mississippi, debe mostrar prueba de seguro al policía en un choque, y le pueden dar una multa sin ella aunque no tenga la culpa.","p":"Correcto. Le pueden multar aunque no haya sido su culpa."},"ref":{"doc":"MS","page":66}},{"id":"ms-184","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, you are too badly hurt in a crash to report it right away. Who may report it for you?","o":["Only your lawyer","Only a family member at home","Only a doctor","Any one of your passengers"],"h1":"Someone who was in the car with you.","h2":"In Mississippi, if you are too badly injured to report a crash right away, any one of your passengers may do it.","p":"Right. Any passenger may report it."},"es":{"q":"En Mississippi, usted está demasiado herido en un choque para reportarlo de inmediato. ¿Quién puede reportarlo por usted?","o":["Solo su abogado","Solo un familiar en casa","Solo un médico","Cualquiera de sus pasajeros"],"h1":"Alguien que iba en el carro con usted.","h2":"En Mississippi, si está demasiado herido para reportar un choque de inmediato, cualquiera de sus pasajeros puede hacerlo.","p":"Correcto. Cualquier pasajero puede reportarlo."},"ref":{"doc":"MS","page":66}},{"id":"ms-185","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, you are in the middle of an intersection when an ambulance with a siren comes up behind you. What should you do?","o":["Stop right where you are","Go through the intersection, then pull over to the far right","Back up out of the intersection","Turn left to get out of the way"],"h1":"Do not block the intersection by stopping in it.","h2":"In Mississippi, if you are at an intersection when an emergency vehicle approaches, go through the intersection and then pull over to the far right.","p":"Right. Clear the intersection, then pull to the right."},"es":{"q":"En Mississippi, usted está en medio de una intersección cuando se acerca por detrás una ambulancia con sirena. ¿Qué debe hacer?","o":["Detenerse donde está","Cruzar la intersección y luego orillarse lo más a la derecha","Retroceder para salir de la intersección","Girar a la izquierda para quitarse"],"h1":"No bloquee la intersección deteniéndose en ella.","h2":"En Mississippi, si está en una intersección cuando se acerca un vehículo de emergencia, cruce la intersección y luego oríllese lo más a la derecha.","p":"Correcto. Despeje la intersección y luego oríllese a la derecha."},"ref":{"doc":"MS","page":67}},{"id":"ms-186","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, a police officer pulls you over at night. What does the manual say to do with the lights inside your car?","o":["Turn them all off","Shine a flashlight at the officer","Turn on your interior lights","Flash your headlights"],"h1":"Help the officer see inside the car.","h2":"The Mississippi manual says to turn on your interior lights if you are pulled over at night, to help with visibility.","p":"Right. Turn on your interior lights."},"es":{"q":"En Mississippi, un policía lo detiene de noche. ¿Qué dice el manual que haga con las luces de adentro de su carro?","o":["Apagarlas todas","Alumbrar al policía con una linterna","Encender las luces interiores","Hacer cambio de luces"],"h1":"Ayude al policía a ver dentro del carro.","h2":"El manual de Mississippi dice que encienda las luces interiores si lo detienen de noche, para ayudar a la visibilidad.","p":"Correcto. Encienda las luces interiores."},"ref":{"doc":"MS","page":67}},{"id":"ms-187","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Mississippi manual says you have a weapon in your car and an officer pulls you over. When should you tell the officer?","o":["At first contact, when the officer reaches you","Only if the officer asks","After you get your ticket","Never"],"h1":"Say it early, before you reach for anything.","h2":"The Mississippi manual says to let the officer know if you have a weapon in the vehicle at first contact.","p":"Right. Tell the officer at first contact."},"es":{"q":"El manual de Mississippi dice que usted tiene un arma en su carro y un policía lo detiene. ¿Cuándo debe decírselo al policía?","o":["En el primer contacto, cuando el policía llega a usted","Solo si el policía pregunta","Después de recibir la multa","Nunca"],"h1":"Dígalo pronto, antes de buscar cualquier cosa.","h2":"El manual de Mississippi dice que le avise al policía en el primer contacto si tiene un arma en el vehículo.","p":"Correcto. Avísele al policía en el primer contacto."},"ref":{"doc":"MS","page":68}},{"id":"ms-188","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, an officer gives you a traffic ticket and asks you to sign it. What does signing mean?","o":["You admit you are guilty","You give up your right to go to court","You agree to pay double","It is not an admission of guilt"],"h1":"You may still contest it in court.","h2":"In Mississippi, accepting and signing a traffic ticket is not an admission of guilt; you may contest it in court.","p":"Right. Signing is not admitting guilt."},"es":{"q":"En Mississippi, un policía le da una multa de tránsito y le pide que la firme. ¿Qué significa firmarla?","o":["Que admite que es culpable","Que renuncia a ir a la corte","Que acepta pagar el doble","No es una admisión de culpa"],"h1":"Usted todavía puede impugnarla en la corte.","h2":"En Mississippi, aceptar y firmar una multa de tránsito no es admitir la culpa; usted puede impugnarla en la corte.","p":"Correcto. Firmar no es admitir la culpa."},"ref":{"doc":"MS","page":68}},{"id":"ms-189","scope":"MS","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Mississippi, how far before your interstate exit should you be in the correct lane?","o":["At least 100 feet","At least one-quarter mile","At least 5 miles","Right at the exit"],"h1":"Give yourself time to move over without rushing.","h2":"In Mississippi, be sure you are in the correct lane at least one-quarter mile before your exit.","p":"Right. At least a quarter mile before the exit."},"es":{"q":"En Mississippi, ¿a qué distancia antes de su salida de la interestatal debe estar en el carril correcto?","o":["Al menos 100 pies","Al menos un cuarto de milla","Al menos 5 millas","Justo en la salida"],"h1":"Dese tiempo para cambiarse sin prisa.","h2":"En Mississippi, asegúrese de estar en el carril correcto al menos un cuarto de milla antes de su salida.","p":"Correcto. Al menos un cuarto de milla antes de la salida."},"ref":{"doc":"MS","page":69}},{"id":"ms-190","scope":"MS","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Mississippi, your car breaks down and you are stranded on the interstate. What does the manual say to do?","o":["Walk to the nearest exit","Stand behind your car and wave","Stay inside your car, lock the doors and wait for reliable help","Ask passing drivers for a ride"],"h1":"Being outside near interstate traffic is very dangerous.","h2":"In Mississippi, if you are stranded on the interstate, stay inside your vehicle, lock the doors and wait for reliable help; do not walk or hitchhike.","p":"Right. Stay inside, lock the doors and wait for help."},"es":{"q":"En Mississippi, su carro se descompone y usted queda varado en la interestatal. ¿Qué dice el manual que haga?","o":["Caminar hasta la salida más cercana","Pararse detrás del carro y hacer señas","Quedarse dentro del carro, cerrar las puertas con seguro y esperar ayuda confiable","Pedir que lo lleven a los conductores que pasan"],"h1":"Estar afuera cerca del tráfico de la interestatal es muy peligroso.","h2":"En Mississippi, si queda varado en la interestatal, quédese dentro del vehículo, cierre las puertas con seguro y espere ayuda confiable; no camine ni pida aventón.","p":"Correcto. Quédese adentro, cierre con seguro y espere ayuda."},"ref":{"doc":"MS","page":70}},{"id":"ms-191","scope":"MS","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"The Mississippi manual says passing a large truck on a level highway takes how much longer than passing a car?","o":["About 30 seconds longer","No longer","About 1 minute longer","About 3 to 5 seconds longer"],"h1":"It is just a few seconds, but it matters.","h2":"The Mississippi manual says that on a level highway, it takes 3 to 5 seconds longer to pass a large vehicle than to pass a car.","p":"Right. About 3 to 5 seconds longer."},"es":{"q":"Según el manual de Mississippi, en una carretera plana, ¿cuánto tiempo más toma pasar a un camión grande que a un carro?","o":["Unos 30 segundos más","Lo mismo","Como 1 minuto más","Unos 3 a 5 segundos más"],"h1":"Son solo unos segundos, pero importan.","h2":"El manual de Mississippi dice que en una carretera plana toma de 3 a 5 segundos más pasar a un vehículo grande que a un carro.","p":"Correcto. Unos 3 a 5 segundos más."},"ref":{"doc":"MS","page":72}},{"id":"ms-192","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Mississippi, you are stopped behind a large truck on an uphill road. Besides leaving extra space, where in your lane should you stay?","o":["Toward the left of your lane, so the driver can see you","Toward the right edge, out of sight","Right against the truck's bumper","Half in the next lane"],"h1":"The truck driver uses side mirrors to see you.","h2":"The Mississippi manual says that when stopped behind a large vehicle on an upgrade, leave extra space and keep to the left in your lane so the driver can see you.","p":"Right. Keep to the left in your lane."},"es":{"q":"En Mississippi, usted está detenido detrás de un camión grande en una subida. Además de dejar espacio extra, ¿en qué parte de su carril debe quedarse?","o":["Hacia la izquierda de su carril, para que el chofer lo vea","Hacia la orilla derecha, fuera de su vista","Pegado a la defensa del camión","Medio en el otro carril"],"h1":"El chofer del camión usa los espejos laterales para verlo.","h2":"El manual de Mississippi dice que cuando esté detenido detrás de un vehículo grande en una subida, deje espacio extra y manténgase a la izquierda de su carril para que el chofer lo vea.","p":"Correcto. Manténgase a la izquierda de su carril."},"ref":{"doc":"MS","page":72}},{"id":"ms-193","scope":"MS","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Mississippi, you are in a no-passing zone behind a slow bicycle going your way. May you pass it?","o":["No, never","Yes, when it is safe to do so","Only if the rider waves you on","Only at night"],"h1":"Mississippi makes a special allowance for bicycles.","h2":"In Mississippi, a driver may pass a bicycle going the same direction in a no-passing zone when it is safe to do so.","p":"Right. You may pass when it is safe."},"es":{"q":"En Mississippi, usted está en una zona de no rebasar detrás de una bicicleta lenta que va en su mismo sentido. ¿Puede pasarla?","o":["No, nunca","Sí, cuando sea seguro hacerlo","Solo si el ciclista le hace señas","Solo de noche"],"h1":"Mississippi hace una excepción especial para las bicicletas.","h2":"En Mississippi, un conductor puede pasar a una bicicleta que va en el mismo sentido en una zona de no rebasar cuando sea seguro hacerlo.","p":"Correcto. Puede pasar cuando sea seguro."},"ref":{"doc":"MS","page":73}},{"id":"ms-194","scope":"MS","cat":"right-of-way","sign":null,"c":2,"en":{"q":"The Mississippi manual says bicyclists generally ride how far from the right edge of the road?","o":["On the white line itself","6 to 8 feet","2 to 4 feet","In the middle of the lane always"],"h1":"They stay to the right, but not right on the edge.","h2":"The Mississippi manual says bicyclists should ride as far right as is safe, which generally means 2 to 4 feet from the right edge of the road.","p":"Right. Generally 2 to 4 feet from the edge."},"es":{"q":"Según el manual de Mississippi, ¿a qué distancia de la orilla derecha del camino van generalmente los ciclistas?","o":["Sobre la línea blanca","De 6 a 8 pies","De 2 a 4 pies","Siempre en medio del carril"],"h1":"Van a la derecha, pero no pegados a la orilla.","h2":"El manual de Mississippi dice que los ciclistas deben ir lo más a la derecha que sea seguro, lo que generalmente significa de 2 a 4 pies de la orilla derecha del camino.","p":"Correcto. Generalmente de 2 a 4 pies de la orilla."},"ref":{"doc":"MS","page":73}},{"id":"ms-195","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, from how far away at night must the light over your license plate make the plate readable?","o":["10 feet","20 feet","200 feet","60 feet"],"h1":"It is about four car lengths.","h2":"In Mississippi, your tag light must make the letters and numbers on your license plate visible from 60 feet at night.","p":"Right. The plate must be readable from 60 feet."},"es":{"q":"En Mississippi, ¿desde qué distancia de noche debe la luz de la placa permitir leer su placa?","o":["10 pies","20 pies","200 pies","60 pies"],"h1":"Son unos cuatro largos de carro.","h2":"En Mississippi, la luz de la placa debe hacer visibles las letras y números de su placa desde 60 pies de noche.","p":"Correcto. La placa debe leerse desde 60 pies."},"ref":{"doc":"MS","page":75}},{"id":"ms-196","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, an officer stops you and asks for proof of insurance. May you show it on your phone?","o":["Yes, an electronic image on a phone is accepted","No, only a paper card is accepted","Only if you also mail a copy","Only with a notary stamp"],"h1":"Mississippi accepts proof in electronic form.","h2":"In Mississippi, you may show proof of insurance in electronic form, on a cell phone or other electronic device.","p":"Right. Electronic proof on your phone is accepted."},"es":{"q":"En Mississippi, un policía lo detiene y le pide prueba de seguro. ¿Puede mostrarla en su teléfono?","o":["Sí, se acepta una imagen electrónica en el teléfono","No, solo se acepta la tarjeta de papel","Solo si también envía una copia por correo","Solo con sello de notario"],"h1":"Mississippi acepta la prueba en formato electrónico.","h2":"En Mississippi, usted puede mostrar la prueba de seguro en formato electrónico, en un celular u otro aparato electrónico.","p":"Correcto. Se acepta la prueba electrónica en su teléfono."},"ref":{"doc":"MS","page":76}},{"id":"ms-197","scope":"MS","cat":"safe-driving","sign":null,"c":0,"en":{"q":"The Mississippi manual says your reaction slows by only half a second at 55 mph. How much farther will your car travel before stopping?","o":["About 44 feet","About 4 feet","About 10 feet","About 200 feet"],"h1":"Half a second at highway speed covers a lot of road.","h2":"The Mississippi manual says that a half-second slower reaction at 55 mph makes your vehicle travel an extra 44 feet before stopping.","p":"Right. About 44 extra feet."},"es":{"q":"El manual de Mississippi dice que su reacción se vuelve solo medio segundo más lenta a 55 mph. ¿Cuánto más avanzará su carro antes de detenerse?","o":["Unos 44 pies","Unos 4 pies","Unos 10 pies","Unos 200 pies"],"h1":"Medio segundo a velocidad de carretera cubre mucho camino.","h2":"El manual de Mississippi dice que medio segundo más lento de reacción a 55 mph hace que su vehículo avance 44 pies más antes de detenerse.","p":"Correcto. Unos 44 pies más."},"ref":{"doc":"MS","page":77}},{"id":"ms-198","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a breath test shows a driver is over the legal alcohol limit. The officer takes the license and gives a receipt. How long is that receipt good as a temporary permit?","o":["15 days","30 days","45 days","90 days"],"h1":"It is shorter than the 45-day receipt for refusing the test.","h2":"In Mississippi, when your blood alcohol is at or over your limit, the officer's receipt for your license serves as a temporary permit for only 30 days.","p":"Right. It is good for 30 days."},"es":{"q":"En Mississippi, una prueba de aliento muestra que un conductor supera el límite legal de alcohol. El policía toma la licencia y da un recibo. ¿Por cuánto tiempo sirve ese recibo como permiso temporal?","o":["15 días","30 días","45 días","90 días"],"h1":"Es menos que el recibo de 45 días por negarse a la prueba.","h2":"En Mississippi, cuando su nivel de alcohol en la sangre llega o supera su límite, el recibo del policía por su licencia sirve como permiso temporal solo por 30 días.","p":"Correcto. Sirve por 30 días."},"ref":{"doc":"MS","page":78}},{"id":"ms-199","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, what is the fine for a second DUI within five years for a driver 21 or older?","o":["$250 to $1,000","$2,000 to $5,000","$600 to $1,500","$100 to $500"],"h1":"It is higher than a first offense but below a felony third offense.","h2":"In Mississippi, a second DUI within five years carries a fine of $600 to $1,500 for a driver 21 or older.","p":"Right. $600 to $1,500."},"es":{"q":"En Mississippi, ¿cuál es la multa por un segundo DUI en cinco años para un conductor de 21 años o más?","o":["De $250 a $1,000","De $2,000 a $5,000","De $600 a $1,500","De $100 a $500"],"h1":"Es más alta que una primera ofensa pero menor que la tercera, que es delito grave.","h2":"En Mississippi, un segundo DUI en cinco años tiene una multa de $600 a $1,500 para un conductor de 21 años o más.","p":"Correcto. De $600 a $1,500."},"ref":{"doc":"MS","page":79}},{"id":"ms-200","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, a driver 21 or older is convicted of a third DUI within five years. How is the offense classified?","o":["A traffic warning","A misdemeanor with no jail","A civil fine only","A felony"],"h1":"The first two offenses are misdemeanors; the third is more serious.","h2":"In Mississippi, a third DUI within five years is a felony, with a fine of $2,000 to $5,000 and 1 to 5 years in custody.","p":"Right. It is a felony."},"es":{"q":"En Mississippi, un conductor de 21 años o más es condenado por un tercer DUI en cinco años. ¿Cómo se clasifica el delito?","o":["Una advertencia de tránsito","Un delito menor sin cárcel","Solo una multa civil","Un delito grave (felony)"],"h1":"Las dos primeras ofensas son delitos menores; la tercera es más seria.","h2":"En Mississippi, un tercer DUI en cinco años es un delito grave (felony), con multa de $2,000 a $5,000 y de 1 a 5 años bajo custodia.","p":"Correcto. Es un delito grave."},"ref":{"doc":"MS","page":79}},{"id":"ms-201","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, a driver under 21 has a blood alcohol level of 0.04 percent. What is the fine for a first zero tolerance offense?","o":["$250","$1,000","$50","$600"],"h1":"It is the same as the lowest fine for an adult first DUI.","h2":"In Mississippi, a first zero tolerance DUI for a driver under 21 with 0.02 to under 0.08 percent carries a $250 fine and a 120-day suspension.","p":"Right. The fine is $250."},"es":{"q":"En Mississippi, un conductor menor de 21 años tiene un nivel de alcohol en la sangre de 0.04 por ciento. ¿Cuál es la multa por una primera ofensa de tolerancia cero?","o":["$250","$1,000","$50","$600"],"h1":"Es igual a la multa más baja de un primer DUI de adulto.","h2":"En Mississippi, un primer DUI de tolerancia cero para un conductor menor de 21 años con 0.02 a menos de 0.08 por ciento tiene una multa de $250 y una suspensión de 120 días.","p":"Correcto. La multa es de $250."},"ref":{"doc":"MS","page":79}},{"id":"ms-202","scope":"MS","cat":"licensing","sign":null,"c":1,"en":{"q":"In Mississippi, a driver under 21 is convicted of a third zero tolerance DUI within five years. For how long is the license suspended?","o":["90 days","Two years or until age 21, whichever is longer","Six months","Until age 18"],"h1":"It can last longer than two years for a young driver.","h2":"In Mississippi, a third zero tolerance DUI within five years brings a suspension of two years or until the driver turns 21, whichever is longer.","p":"Right. Two years or until 21, whichever is longer."},"es":{"q":"En Mississippi, un conductor menor de 21 años es condenado por un tercer DUI de tolerancia cero en cinco años. ¿Por cuánto tiempo se suspende la licencia?","o":["90 días","Dos años o hasta cumplir 21, lo que sea más largo","Seis meses","Hasta los 18 años"],"h1":"Puede durar más de dos años para un conductor joven.","h2":"En Mississippi, un tercer DUI de tolerancia cero en cinco años trae una suspensión de dos años o hasta que el conductor cumpla 21, lo que sea más largo.","p":"Correcto. Dos años o hasta los 21, lo que sea más largo."},"ref":{"doc":"MS","page":79}},{"id":"ms-203","scope":"MS","cat":"licensing","sign":null,"c":3,"en":{"q":"In Mississippi, after release from prison for a fourth DUI, what license may the person get, and for how long?","o":["A regular license right away","A learner's permit for one year","A license with no limits after 3 years","Only an interlock-restricted license for ten years"],"h1":"An interlock device checks for alcohol before the car will start.","h2":"In Mississippi, after a fourth or later DUI, the person may get only an interlock-restricted license for ten years after release.","p":"Right. Only an interlock-restricted license for ten years."},"es":{"q":"En Mississippi, al salir de prisión por un cuarto DUI, ¿qué licencia puede obtener la persona y por cuánto tiempo?","o":["Una licencia regular de inmediato","Un permiso de aprendiz por un año","Una licencia sin límites después de 3 años","Solo una licencia restringida con interlock por diez años"],"h1":"Un aparato interlock revisa si hay alcohol antes de que el carro arranque.","h2":"En Mississippi, después de un cuarto DUI o más, la persona solo puede obtener una licencia restringida con interlock por diez años después de salir.","p":"Correcto. Solo una licencia con interlock por diez años."},"ref":{"doc":"MS","page":79}},{"id":"ms-204","scope":"MS","cat":"licensing","sign":null,"c":2,"en":{"q":"In Mississippi, a driver leaves the scene of a crash without stopping to give aid as the law requires. What happens to the license after conviction?","o":["A $25 fine only","A warning letter","It is revoked for one year","Nothing if no one died"],"h1":"This is on the list of offenses with a mandatory loss of license.","h2":"In Mississippi, a conviction for failing to stop and render aid after a crash means the license is revoked for one year.","p":"Right. The license is revoked for one year."},"es":{"q":"En Mississippi, un conductor se va del lugar de un choque sin detenerse a dar ayuda como exige la ley. ¿Qué pasa con su licencia después de la condena?","o":["Solo una multa de $25","Una carta de advertencia","Se revoca por un año","Nada si nadie murió"],"h1":"Está en la lista de delitos con pérdida obligatoria de la licencia.","h2":"En Mississippi, una condena por no detenerse a dar ayuda después de un choque significa que la licencia se revoca por un año.","p":"Correcto. La licencia se revoca por un año."},"ref":{"doc":"MS","page":80}},{"id":"ms-205","scope":"MS","cat":"licensing","sign":null,"c":0,"en":{"q":"In Mississippi, what is the fee to reinstate a license after a DUI or implied consent suspension?","o":["$175","$25","$100","$11"],"h1":"It is the highest of the reinstatement fees.","h2":"In Mississippi, reinstating a license after a DUI, implied consent or controlled substances suspension costs $175.","p":"Right. The fee is $175."},"es":{"q":"En Mississippi, ¿cuál es la tarifa para restablecer una licencia después de una suspensión por DUI o por consentimiento implícito?","o":["$175","$25","$100","$11"],"h1":"Es la más alta de las tarifas de restablecimiento.","h2":"En Mississippi, restablecer una licencia después de una suspensión por DUI, consentimiento implícito o sustancias controladas cuesta $175.","p":"Correcto. La tarifa es de $175."},"ref":{"doc":"MS","page":81}},{"id":"mt-001","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the youngest age to get a learner license if you are enrolled in an approved traffic education course?","o":["14 and a half","15 and a half","16 years old","17 years old"],"h1":"Montana lets students start younger than almost any other state.","h2":"In Montana a teen who is enrolled in an approved traffic education course can get a learner license at 14 and a half.","p":"Right. With traffic education, the learner license starts at 14 and a half."},"es":{"q":"En Montana, ¿cuál es la edad mínima para obtener una licencia de aprendiz si usted está inscrito en un curso aprobado de educación vial?","o":["14 años y medio","15 años y medio","16 años","17 años"],"h1":"Montana permite empezar más joven que casi cualquier otro estado.","h2":"En Montana, un adolescente inscrito en un curso aprobado de educación vial puede obtener la licencia de aprendiz a los 14 años y medio.","p":"Correcto. Con educación vial, la licencia de aprendiz empieza a los 14 años y medio."},"zh":{"q":"在 Montana，如果你报名参加了批准的交通教育课程，最小几岁可以拿到学习驾照（learner license）？","o":["14 岁半","15 岁半","16 岁","17 岁"],"h1":"Montana 让学生比几乎任何其他州都更早开始。","h2":"在 Montana，报名参加了批准的交通教育课程的青少年，14 岁半就可以拿到学习驾照。","p":"对。上了交通教育课，学习驾照从 14 岁半开始。"},"vi":{"q":"Ở Montana, độ tuổi nhỏ nhất để được cấp giấy phép tập lái (learner license) là bao nhiêu nếu bạn đang học một khóa giáo dục giao thông được chấp thuận (traffic education)?","o":["14 tuổi rưỡi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Montana cho học sinh bắt đầu sớm hơn hầu hết các tiểu bang khác.","h2":"Ở Montana, một thiếu niên đang học khóa giáo dục giao thông được chấp thuận có thể được cấp giấy phép tập lái khi 14 tuổi rưỡi.","p":"Đúng. Khi học giáo dục giao thông, giấy phép tập lái bắt đầu từ 14 tuổi rưỡi."},"tl":{"q":"Sa Montana, ano ang pinakabatang edad para makakuha ng learner license kung naka-enroll ka sa isang aprubadong kurso ng traffic education?","o":["14 at kalahating taon","15 at kalahating taon","16 na taon","17 na taon"],"h1":"Mas maagang pinapayagang magsimula ang mga estudyante sa Montana kaysa halos lahat ng ibang estado.","h2":"Sa Montana, ang isang tinedyer na naka-enroll sa aprubadong kurso ng traffic education ay maaaring makakuha ng learner license sa edad na 14 at kalahati.","p":"Tama. Kapag may traffic education, nagsisimula ang learner license sa 14 at kalahati."},"ar":{"q":"في Montana، ما أصغر عمر للحصول على رخصة التعلّم (learner license) إذا كنت مسجَّلًا في دورة معتمدة لتعليم المرور (traffic education)؟","o":["14 سنة ونصف","15 سنة ونصف","16 سنة","17 سنة"],"h1":"تسمح Montana للطلاب بالبدء أبكر من كل الولايات الأخرى تقريبًا.","h2":"في Montana يمكن للمراهق المسجَّل في دورة معتمدة لتعليم المرور أن يحصل على رخصة التعلّم في عمر 14 سنة ونصف.","p":"صحيح. مع دورة تعليم المرور تبدأ رخصة التعلّم من عمر 14 سنة ونصف."},"ref":{"doc":"MT","page":8}},{"id":"mt-002","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long must a teen hold a learner license before getting a first-year restricted license?","o":["1 month","3 months","6 months","12 months"],"h1":"It is half a year.","h2":"A Montana teen must hold the learner license for at least six months in a row before applying for the first-year restricted license.","p":"Right. The learner license is held for six months."},"es":{"q":"En Montana, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia restringida del primer año?","o":["1 mes","3 meses","6 meses","12 meses"],"h1":"Es medio año.","h2":"En Montana, un adolescente debe tener la licencia de aprendiz por lo menos seis meses seguidos antes de solicitar la licencia restringida del primer año.","p":"Correcto. La licencia de aprendiz se tiene seis meses."},"zh":{"q":"在 Montana，青少年必须持有学习驾照多久，才能拿到第一年限制驾照？","o":["1 个月","3 个月","6 个月","12 个月"],"h1":"是半年。","h2":"Montana 的青少年必须连续持有学习驾照至少六个月，才能申请第一年限制驾照。","p":"对。学习驾照要持有六个月。"},"vi":{"q":"Ở Montana, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái hạn chế năm đầu (first-year restricted license)?","o":["1 tháng","3 tháng","6 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Montana, thiếu niên phải giữ giấy phép tập lái ít nhất sáu tháng liên tục trước khi xin bằng lái hạn chế năm đầu.","p":"Đúng. Giấy phép tập lái phải được giữ sáu tháng."},"tl":{"q":"Sa Montana, gaano katagal dapat hawak ng tinedyer ang learner license bago makakuha ng first-year restricted license (restriktadong lisensiya sa unang taon)?","o":["1 buwan","3 buwan","6 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang isang tinedyer sa Montana ay dapat may hawak na learner license nang hindi bababa sa anim na magkakasunod na buwan bago mag-apply para sa first-year restricted license.","p":"Tama. Hawak ang learner license nang anim na buwan."},"ar":{"q":"في Montana، كم مدة يجب أن يحمل المراهق رخصة التعلّم قبل الحصول على الرخصة المقيَّدة للسنة الأولى (first-year restricted license)؟","o":["شهر واحد","3 أشهر","6 أشهر","12 شهرًا"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Montana أن يحمل رخصة التعلّم ستة أشهر متتالية على الأقل قبل التقدّم للرخصة المقيَّدة للسنة الأولى.","p":"صحيح. تُحمَل رخصة التعلّم ستة أشهر."},"ref":{"doc":"MT","page":8}},{"id":"mt-003","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, how many hours of supervised driving must a teen complete with a learner license?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"A parent records these hours on a driving log.","h2":"A Montana teen must complete at least 50 hours of supervised driving while holding the learner license, and a parent certifies the log.","p":"Right. Montana asks for 50 supervised hours."},"es":{"q":"En Montana, ¿cuántas horas de manejo supervisado debe completar un adolescente con licencia de aprendiz?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Uno de los padres anota estas horas en un registro de manejo.","h2":"En Montana, un adolescente debe completar por lo menos 50 horas de manejo supervisado con la licencia de aprendiz, y uno de los padres certifica el registro.","p":"Correcto. Montana pide 50 horas supervisadas."},"zh":{"q":"在 Montana，青少年持学习驾照时必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"父母会把这些时间记在驾驶记录表上。","h2":"Montana 的青少年持学习驾照时必须完成至少 50 小时有人监督的驾驶，由父母证明记录表。","p":"对。Montana 要求 50 小时有人监督的驾驶。"},"vi":{"q":"Ở Montana, thiếu niên có giấy phép tập lái phải lái xe có người giám sát bao nhiêu giờ?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Cha mẹ ghi những giờ này vào sổ ghi chép lái xe.","h2":"Ở Montana, thiếu niên phải lái xe có người giám sát ít nhất 50 giờ trong thời gian giữ giấy phép tập lái, và cha mẹ xác nhận sổ ghi chép.","p":"Đúng. Montana yêu cầu 50 giờ có người giám sát."},"tl":{"q":"Sa Montana, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng tinedyer na may learner license?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Itinatala ng magulang ang mga oras na ito sa isang driving log.","h2":"Ang isang tinedyer sa Montana ay dapat makatapos ng hindi bababa sa 50 oras ng pagmamaneho na may gumagabay habang may hawak na learner license, at pinapatunayan ng magulang ang log.","p":"Tama. 50 oras na may gumagabay ang hinihingi ng Montana."},"ar":{"q":"في Montana، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق الذي يحمل رخصة التعلّم؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"يسجّل أحد الوالدين هذه الساعات في سجل القيادة.","h2":"يجب على المراهق في Montana أن يُكمل 50 ساعة على الأقل من القيادة تحت الإشراف وهو يحمل رخصة التعلّم، ويوقّع أحد الوالدين على السجل.","p":"صحيح. تطلب Montana 50 ساعة تحت الإشراف."},"ref":{"doc":"MT","page":7}},{"id":"mt-004","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, how many of the 50 supervised practice hours must be at night?","o":["5 hours","10 hours","20 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"Of the 50 supervised hours in Montana, at least 10 must be driven at night, so the teen learns to drive in the dark.","p":"Right. 10 of the 50 hours are at night."},"es":{"q":"En Montana, ¿cuántas de las 50 horas de práctica supervisada deben ser de noche?","o":["5 horas","10 horas","20 horas","25 horas"],"h1":"Es una quinta parte del total.","h2":"De las 50 horas supervisadas en Montana, por lo menos 10 deben ser de noche, para que el adolescente aprenda a manejar en la oscuridad.","p":"Correcto. 10 de las 50 horas son de noche."},"zh":{"q":"在 Montana，50 小时有人监督的练习中，有多少小时必须在晚上？","o":["5 小时","10 小时","20 小时","25 小时"],"h1":"是总数的五分之一。","h2":"在 Montana 的 50 小时有人监督的驾驶中，至少 10 小时必须在晚上开，这样青少年能学会在黑暗中开车。","p":"对。50 小时中有 10 小时在晚上。"},"vi":{"q":"Ở Montana, trong 50 giờ tập lái có người giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","10 giờ","20 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Trong 50 giờ có người giám sát ở Montana, ít nhất 10 giờ phải lái vào ban đêm, để thiếu niên học cách lái trong bóng tối.","p":"Đúng. 10 trong 50 giờ là vào ban đêm."},"tl":{"q":"Sa Montana, ilan sa 50 oras ng pagsasanay na may gumagabay ang dapat sa gabi?","o":["5 oras","10 oras","20 oras","25 oras"],"h1":"Ito ay ikalimang bahagi ng kabuuan.","h2":"Sa 50 oras na may gumagabay sa Montana, hindi bababa sa 10 ang dapat imaneho sa gabi, para matutong magmaneho ang tinedyer sa dilim.","p":"Tama. 10 sa 50 oras ay sa gabi."},"ar":{"q":"في Montana، كم ساعة من ساعات التدريب الـ 50 تحت الإشراف يجب أن تكون في الليل؟","o":["5 ساعات","10 ساعات","20 ساعة","25 ساعة"],"h1":"إنها خُمس المجموع.","h2":"من الساعات الـ 50 تحت الإشراف في Montana، يجب أن تكون 10 ساعات على الأقل في الليل، حتى يتعلّم المراهق القيادة في الظلام.","p":"صحيح. 10 من الـ 50 ساعة في الليل."},"ref":{"doc":"MT","page":7}},{"id":"mt-005","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a learner under 18 may drive with a parent or guardian, or with their permission, with whom?","o":["Any passenger of any age","A friend age 16 or older","Only a police officer","A licensed driver age 18 or older"],"h1":"The person must be an adult with a license.","h2":"In Montana a learner under 18 must be supervised by a parent or guardian, or, with the parent's permission, by a licensed driver who is at least 18.","p":"Right. With permission, a licensed driver 18 or older may supervise."},"es":{"q":"En Montana, un aprendiz menor de 18 años puede manejar con su padre, madre o tutor, o con su permiso, ¿con quién?","o":["Cualquier pasajero de cualquier edad","Un amigo de 16 años o más","Solamente un policía","Un conductor con licencia de 18 años o más"],"h1":"La persona debe ser un adulto con licencia.","h2":"En Montana, un aprendiz menor de 18 años debe ir supervisado por su padre, madre o tutor, o, con permiso de ellos, por un conductor con licencia de por lo menos 18 años.","p":"Correcto. Con permiso, puede supervisar un conductor con licencia de 18 años o más."},"zh":{"q":"在 Montana，18 岁以下的学习驾驶的人可以和父母或监护人一起开车，或者经他们允许，和谁一起开车？","o":["任何年龄的任何乘客","16 岁或以上的朋友","只有警察","18 岁或以上、有驾照的司机"],"h1":"这个人必须是有驾照的成年人。","h2":"在 Montana，18 岁以下的学习驾驶的人必须由父母或监护人监督，或者经父母允许，由至少 18 岁、有驾照的司机监督。","p":"对。经允许，18 岁或以上、有驾照的司机可以监督。"},"vi":{"q":"Ở Montana, người tập lái dưới 18 tuổi có thể lái xe với cha mẹ hoặc người giám hộ, hoặc, khi được họ cho phép, với ai?","o":["Bất kỳ hành khách nào ở bất kỳ tuổi nào","Một người bạn từ 16 tuổi trở lên","Chỉ một cảnh sát","Một người có bằng lái từ 18 tuổi trở lên"],"h1":"Người đó phải là người lớn có bằng lái.","h2":"Ở Montana, người tập lái dưới 18 tuổi phải được cha mẹ hoặc người giám hộ giám sát, hoặc, khi cha mẹ cho phép, được một người có bằng lái từ 18 tuổi trở lên giám sát.","p":"Đúng. Khi được cho phép, một người có bằng lái từ 18 tuổi trở lên có thể giám sát."},"tl":{"q":"Sa Montana, ang learner na wala pang 18 taong gulang ay maaaring magmaneho kasama ang magulang o guardian, o, kung may pahintulot nila, kasama sino?","o":["Kahit sinong pasahero sa kahit anong edad","Isang kaibigan na 16 taong gulang pataas","Isang pulis lamang","Isang lisensiyadong driver na 18 taong gulang pataas"],"h1":"Ang tao ay dapat nasa hustong gulang at may lisensiya.","h2":"Sa Montana, ang learner na wala pang 18 ay dapat gabayan ng magulang o guardian, o, kung may pahintulot ng magulang, ng isang lisensiyadong driver na hindi bababa sa 18 taong gulang.","p":"Tama. Kung may pahintulot, maaaring gumabay ang lisensiyadong driver na 18 pataas."},"ar":{"q":"في Montana، يمكن للمتعلّم الذي عمره أقل من 18 سنة أن يقود مع أحد الوالدين أو الوصي، أو بإذنهما، مع مَن؟","o":["أي راكب من أي عمر","صديق عمره 16 سنة أو أكثر","شرطي فقط","سائق مرخَّص عمره 18 سنة أو أكثر"],"h1":"يجب أن يكون الشخص بالغًا ومعه رخصة.","h2":"في Montana يجب أن يكون المتعلّم الذي عمره أقل من 18 سنة تحت إشراف أحد الوالدين أو الوصي، أو، بإذن الوالدين، تحت إشراف سائق مرخَّص عمره 18 سنة على الأقل.","p":"صحيح. بالإذن، يمكن لسائق مرخَّص عمره 18 سنة أو أكثر أن يُشرف."},"ref":{"doc":"MT","page":7}},{"id":"mt-006","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, during the first year with a restricted license, when may a teen not drive unless an exception applies?","o":["From 10 p.m. to 6 a.m.","From 11 p.m. to 5 a.m.","From midnight to 5 a.m.","From 9 p.m. to 5 a.m."],"h1":"It starts one hour before midnight.","h2":"A Montana teen with a first-year restricted license may not drive between 11 p.m. and 5 a.m., unless a listed exception applies, such as an emergency.","p":"Right. No driving from 11 p.m. to 5 a.m. without an exception."},"es":{"q":"En Montana, durante el primer año con licencia restringida, ¿cuándo no puede manejar un adolescente salvo que aplique una excepción?","o":["De 10 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De medianoche a 5 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Montana, un adolescente con licencia restringida del primer año no puede manejar entre las 11 p.m. y las 5 a.m., salvo que aplique una excepción de la lista, como una emergencia.","p":"Correcto. No se maneja de 11 p.m. a 5 a.m. sin una excepción."},"zh":{"q":"在 Montana，持限制驾照的第一年，除非有例外情况，青少年什么时候不能开车？","o":["晚上 10 点到早上 6 点","晚上 11 点到早上 5 点","午夜到早上 5 点","晚上 9 点到早上 5 点"],"h1":"它从午夜前一个小时开始。","h2":"Montana 持第一年限制驾照的青少年，在晚上 11 点到早上 5 点之间不能开车，除非有列出的例外情况，比如紧急情况。","p":"对。没有例外情况时，晚上 11 点到早上 5 点不能开车。"},"vi":{"q":"Ở Montana, trong năm đầu có bằng lái hạn chế, thiếu niên không được lái xe vào giờ nào, trừ khi có trường hợp ngoại lệ?","o":["Từ 10 giờ tối đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 5 giờ sáng","Từ 9 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Montana, thiếu niên có bằng lái hạn chế năm đầu không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có một ngoại lệ được liệt kê, ví dụ như trường hợp khẩn cấp.","p":"Đúng. Không lái từ 11 giờ tối đến 5 giờ sáng nếu không có ngoại lệ."},"tl":{"q":"Sa Montana, sa unang taon na may restricted license, kailan bawal magmaneho ang tinedyer maliban kung may eksepsiyon?","o":["Mula 10 p.m. hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 5 a.m.","Mula 9 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Ang tinedyer sa Montana na may first-year restricted license ay bawal magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung may nakalistang eksepsiyon, gaya ng emergency.","p":"Tama. Bawal magmaneho mula 11 p.m. hanggang 5 a.m. kung walang eksepsiyon."},"ar":{"q":"في Montana، خلال السنة الأولى مع الرخصة المقيَّدة، متى لا يجوز للمراهق أن يقود إلا إذا كان هناك استثناء؟","o":["من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من منتصف الليل إلى 5 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"لا يجوز للمراهق في Montana الذي يحمل الرخصة المقيَّدة للسنة الأولى أن يقود بين 11 مساءً و5 صباحًا، إلا إذا كان هناك استثناء مذكور، مثل حالة طارئة.","p":"صحيح. لا قيادة من 11 مساءً إلى 5 صباحًا بدون استثناء."},"ref":{"doc":"MT","page":8}},{"id":"mt-007","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, during the first six months with a restricted license, how many passengers under 18 may a teen carry without an adult supervisor?","o":["No more than one","No more than two","No more than three","As many as there are seat belts"],"h1":"The number is very small at first.","h2":"In the first six months, a Montana restricted licensee may not carry more than one passenger under 18 unless a licensed driver age 18 or older is supervising.","p":"Right. At first, no more than one passenger under 18."},"es":{"q":"En Montana, durante los primeros seis meses con licencia restringida, ¿cuántos pasajeros menores de 18 años puede llevar un adolescente sin un adulto supervisor?","o":["No más de uno","No más de dos","No más de tres","Tantos como cinturones haya"],"h1":"Al principio el número es muy pequeño.","h2":"En los primeros seis meses, quien tiene licencia restringida en Montana no puede llevar más de un pasajero menor de 18 años, salvo que lo supervise un conductor con licencia de 18 años o más.","p":"Correcto. Al principio, no más de un pasajero menor de 18."},"zh":{"q":"在 Montana，持限制驾照的前六个月，没有成年人监督时，青少年可以载多少位 18 岁以下的乘客？","o":["最多一位","最多两位","最多三位","有几条安全带就载几位"],"h1":"一开始这个数字很小。","h2":"在前六个月，Montana 持限制驾照的人不能载超过一位 18 岁以下的乘客，除非有 18 岁或以上、有驾照的司机监督。","p":"对。一开始最多只能载一位 18 岁以下的乘客。"},"vi":{"q":"Ở Montana, trong sáu tháng đầu có bằng lái hạn chế, thiếu niên được chở bao nhiêu hành khách dưới 18 tuổi khi không có người lớn giám sát?","o":["Không quá một người","Không quá hai người","Không quá ba người","Bằng số dây an toàn trong xe"],"h1":"Lúc đầu con số này rất nhỏ.","h2":"Trong sáu tháng đầu, người có bằng lái hạn chế ở Montana không được chở quá một hành khách dưới 18 tuổi, trừ khi có một người có bằng lái từ 18 tuổi trở lên giám sát.","p":"Đúng. Lúc đầu, không quá một hành khách dưới 18 tuổi."},"tl":{"q":"Sa Montana, sa unang anim na buwan na may restricted license, ilang pasaherong wala pang 18 ang maaaring isakay ng tinedyer kung walang adult na gumagabay?","o":["Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Kasing dami ng seat belt"],"h1":"Napakaliit ng bilang sa simula.","h2":"Sa unang anim na buwan, ang may restricted license sa Montana ay hindi maaaring magsakay ng higit sa isang pasaherong wala pang 18, maliban kung may gumagabay na lisensiyadong driver na 18 pataas.","p":"Tama. Sa simula, hindi hihigit sa isang pasaherong wala pang 18."},"ar":{"q":"في Montana، خلال الأشهر الستة الأولى مع الرخصة المقيَّدة، كم راكبًا عمره أقل من 18 سنة يمكن للمراهق أن ينقل بدون مشرف بالغ؟","o":["ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة","بعدد أحزمة الأمان"],"h1":"العدد صغير جدًا في البداية.","h2":"في الأشهر الستة الأولى، لا يجوز لحامل الرخصة المقيَّدة في Montana أن ينقل أكثر من راكب واحد عمره أقل من 18 سنة، إلا إذا كان سائق مرخَّص عمره 18 سنة أو أكثر يُشرف عليه.","p":"صحيح. في البداية، ليس أكثر من راكب واحد عمره أقل من 18 سنة."},"ref":{"doc":"MT","page":8}},{"id":"mt-008","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long do the restrictions on a teen's first license last?","o":["Six months, at any age","Two years, or until age 21","One year, or until age 18 if sooner","Until the teen finishes high school"],"h1":"Whichever comes first ends them.","h2":"Montana's first-license restrictions last one year from the date the license is issued, or until the driver turns 18 if that comes first.","p":"Right. One year, or until 18, whichever is first."},"es":{"q":"En Montana, ¿cuánto duran las restricciones de la primera licencia de un adolescente?","o":["Seis meses, a cualquier edad","Dos años, o hasta los 21","Un año, o hasta los 18 si es antes","Hasta que termine la secundaria"],"h1":"Las termina lo que ocurra primero.","h2":"Las restricciones de la primera licencia en Montana duran un año desde que se emite la licencia, o hasta que el conductor cumple 18 años si eso ocurre antes.","p":"Correcto. Un año, o hasta los 18, lo que ocurra primero."},"zh":{"q":"在 Montana，青少年第一张驾照的限制会持续多久？","o":["六个月，不管几岁","两年，或者到 21 岁","一年，或者到 18 岁（如果更早）","到青少年高中毕业"],"h1":"哪个先到，限制就在那时结束。","h2":"Montana 第一张驾照的限制从拿到驾照那天起持续一年，如果司机更早满 18 岁，就到满 18 岁为止。","p":"对。一年，或者到 18 岁，哪个先到就算哪个。"},"vi":{"q":"Ở Montana, các hạn chế trên bằng lái đầu tiên của thiếu niên kéo dài bao lâu?","o":["Sáu tháng, ở bất kỳ tuổi nào","Hai năm, hoặc đến 21 tuổi","Một năm, hoặc đến 18 tuổi nếu sớm hơn","Đến khi thiếu niên học xong trung học"],"h1":"Điều nào đến trước thì các hạn chế kết thúc.","h2":"Các hạn chế trên bằng lái đầu tiên ở Montana kéo dài một năm kể từ ngày cấp bằng, hoặc đến khi người lái tròn 18 tuổi nếu điều đó đến trước.","p":"Đúng. Một năm, hoặc đến 18 tuổi, tùy điều nào đến trước."},"tl":{"q":"Sa Montana, gaano katagal ang mga restriksiyon sa unang lisensiya ng tinedyer?","o":["Anim na buwan, sa kahit anong edad","Dalawang taon, o hanggang edad 21","Isang taon, o hanggang edad 18 kung mas maaga","Hanggang matapos ng tinedyer ang high school"],"h1":"Kung alin ang mauna, iyon ang tatapos sa mga ito.","h2":"Ang mga restriksiyon sa unang lisensiya sa Montana ay tumatagal ng isang taon mula sa araw na ibinigay ang lisensiya, o hanggang mag-18 ang driver kung iyon ang mauna.","p":"Tama. Isang taon, o hanggang 18, kung alin ang mauna."},"ar":{"q":"في Montana، كم تستمر القيود على أول رخصة للمراهق؟","o":["ستة أشهر، في أي عمر","سنتان، أو حتى عمر 21","سنة واحدة، أو حتى عمر 18 إذا جاء أولًا","حتى ينهي المراهق المدرسة الثانوية"],"h1":"ما يأتي أولًا هو الذي يُنهيها.","h2":"تستمر قيود أول رخصة في Montana سنة واحدة من تاريخ إصدار الرخصة، أو حتى يبلغ السائق 18 سنة إذا جاء ذلك أولًا.","p":"صحيح. سنة واحدة، أو حتى عمر 18، أيهما أولًا."},"ref":{"doc":"MT","page":8}},{"id":"mt-009","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what seat belt rule applies to a teen with a first-year restricted license?","o":["Only the driver must buckle up","Only front-seat riders must buckle up","Belts are needed only on highways","Every rider must be belted, one person per belt"],"h1":"The number of people may not be more than the number of belts.","h2":"A Montana restricted licensee may drive only if every person in the vehicle wears a seat belt or proper restraint, and there are no more riders than belts.","p":"Right. Everyone belted, and no more riders than seat belts."},"es":{"q":"En Montana, ¿qué regla de cinturón de seguridad aplica a un adolescente con licencia restringida del primer año?","o":["Solo el conductor debe abrocharse","Solo los de adelante deben abrocharse","Los cinturones solo se necesitan en carretera","Todos deben usar cinturón, una persona por cinturón"],"h1":"El número de personas no puede ser mayor que el de cinturones.","h2":"En Montana, quien tiene licencia restringida solo puede manejar si cada persona en el vehículo usa cinturón o el sistema de sujeción adecuado, y no hay más personas que cinturones.","p":"Correcto. Todos con cinturón, y no más personas que cinturones."},"zh":{"q":"在 Montana，持第一年限制驾照的青少年要遵守哪条安全带规定？","o":["只有司机要系安全带","只有坐前排的人要系安全带","只有在公路上才需要系安全带","每个乘车的人都要系安全带，一人一条"],"h1":"人数不能超过安全带的数量。","h2":"Montana 持限制驾照的人只有在车里每个人都系好安全带或合适的约束装置，而且乘车的人不比安全带多时，才可以开车。","p":"对。每个人都系安全带，乘车的人不能比安全带多。"},"vi":{"q":"Ở Montana, quy định nào về dây an toàn áp dụng cho thiếu niên có bằng lái hạn chế năm đầu?","o":["Chỉ người lái phải thắt dây an toàn","Chỉ người ngồi ghế trước phải thắt dây an toàn","Chỉ cần thắt dây an toàn trên xa lộ","Mọi người trong xe phải thắt dây an toàn, mỗi người một dây"],"h1":"Số người không được nhiều hơn số dây an toàn.","h2":"Ở Montana, người có bằng lái hạn chế chỉ được lái xe khi mọi người trong xe đều thắt dây an toàn hoặc dùng ghế an toàn phù hợp, và số người không nhiều hơn số dây an toàn.","p":"Đúng. Mọi người thắt dây an toàn, và số người không nhiều hơn số dây an toàn."},"tl":{"q":"Sa Montana, anong patakaran sa seat belt ang para sa tinedyer na may first-year restricted license?","o":["Ang driver lang ang dapat mag-seat belt","Ang mga nasa harapan lang ang dapat mag-seat belt","Kailangan lang ang seat belt sa highway","Bawat sakay ay dapat naka-seat belt, isang tao bawat belt"],"h1":"Hindi puwedeng mas marami ang tao kaysa sa bilang ng seat belt.","h2":"Ang may restricted license sa Montana ay maaari lang magmaneho kung bawat tao sa sasakyan ay naka-seat belt o tamang restraint, at hindi mas marami ang sakay kaysa sa mga belt.","p":"Tama. Lahat naka-seat belt, at hindi mas marami ang sakay kaysa sa seat belt."},"ar":{"q":"في Montana، ما قاعدة حزام الأمان التي تنطبق على المراهق الذي يحمل الرخصة المقيَّدة للسنة الأولى؟","o":["السائق فقط يجب أن يربط الحزام","ركاب المقعد الأمامي فقط يجب أن يربطوا الحزام","الأحزمة مطلوبة على الطرق السريعة فقط","كل راكب يجب أن يربط حزامًا، شخص واحد لكل حزام"],"h1":"لا يجوز أن يكون عدد الأشخاص أكثر من عدد الأحزمة.","h2":"يمكن لحامل الرخصة المقيَّدة في Montana أن يقود فقط إذا كان كل شخص في السيارة يربط حزام الأمان أو وسيلة حماية مناسبة، ولا يزيد عدد الركاب على عدد الأحزمة.","p":"صحيح. الجميع يربطون الحزام، ولا يزيد عدد الركاب على عدد الأحزمة."},"ref":{"doc":"MT","page":8}},{"id":"mt-010","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how long is a learner license valid after you pass the written test?","o":["30 days","6 months","One year","Two years"],"h1":"It lasts long enough for a full season of practice and more.","h2":"A Montana learner license is issued after you pass the written and vision tests, and it is valid for one year.","p":"Right. The learner license is valid for one year."},"es":{"q":"En Montana, ¿cuánto tiempo es válida la licencia de aprendiz después de aprobar el examen escrito?","o":["30 días","6 meses","Un año","Dos años"],"h1":"Dura lo suficiente para una temporada completa de práctica y más.","h2":"En Montana, la licencia de aprendiz se emite después de aprobar el examen escrito y el de la vista, y es válida por un año.","p":"Correcto. La licencia de aprendiz es válida por un año."},"zh":{"q":"在 Montana，通过笔试以后，学习驾照有效多久？","o":["30 天","6 个月","一年","两年"],"h1":"它的时间够你练习整整一个季节，还更长。","h2":"Montana 的学习驾照在你通过笔试和视力检查以后发给你，有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Montana, giấy phép tập lái có giá trị bao lâu sau khi bạn đậu bài thi viết?","o":["30 ngày","6 tháng","Một năm","Hai năm"],"h1":"Thời gian đủ dài cho cả một mùa tập lái và hơn nữa.","h2":"Ở Montana, giấy phép tập lái được cấp sau khi bạn đậu bài thi viết và bài kiểm tra thị lực, và có giá trị một năm.","p":"Đúng. Giấy phép tập lái có giá trị một năm."},"tl":{"q":"Sa Montana, gaano katagal valid ang learner license pagkatapos mong pumasa sa written test?","o":["30 araw","6 na buwan","Isang taon","Dalawang taon"],"h1":"Sapat ang haba nito para sa isang buong season ng pagsasanay at higit pa.","h2":"Ang learner license sa Montana ay ibinibigay pagkatapos mong pumasa sa written test at vision test, at valid ito nang isang taon.","p":"Tama. Valid ang learner license nang isang taon."},"ar":{"q":"في Montana، كم مدة صلاحية رخصة التعلّم بعد أن تنجح في الاختبار الكتابي؟","o":["30 يومًا","6 أشهر","سنة واحدة","سنتان"],"h1":"إنها طويلة بما يكفي لموسم كامل من التدريب وأكثر.","h2":"تُصدَر رخصة التعلّم في Montana بعد أن تنجح في الاختبار الكتابي واختبار النظر، وهي صالحة لمدة سنة واحدة.","p":"صحيح. رخصة التعلّم صالحة لمدة سنة واحدة."},"ref":{"doc":"MT","page":8}},{"id":"mt-011","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit on an interstate outside a city of 50,000 people or more?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"It is one of the highest limits in the country.","h2":"Montana law sets 80 mph at all times on interstates outside urbanized areas of 50,000 people or more, unless a lower limit is posted.","p":"Right. Rural Montana interstates are 80 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal fuera de una ciudad de 50,000 habitantes o más?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Es uno de los límites más altos del país.","h2":"La ley de Montana fija 80 mph a toda hora en las autopistas interestatales fuera de zonas urbanas de 50,000 habitantes o más, salvo que se indique un límite menor.","p":"Correcto. Las interestatales rurales de Montana son de 80 mph."},"zh":{"q":"在 Montana，在人口 50,000 或以上的城市以外，州际公路的限速是多少？","o":["75 英里/小时","80 英里/小时","70 英里/小时","85 英里/小时"],"h1":"它是全国最高的限速之一。","h2":"Montana 法律规定，在人口 50,000 或以上的城市化地区以外，州际公路任何时候都限速 80 英里/小时，除非标出更低的限速。","p":"对。Montana 乡村的州际公路限速 80 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trên xa lộ liên bang (interstate) bên ngoài thành phố có 50,000 dân trở lên là bao nhiêu?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Đây là một trong những giới hạn cao nhất cả nước.","h2":"Luật Montana đặt giới hạn 80 mph vào mọi lúc trên xa lộ liên bang bên ngoài khu đô thị có 50,000 dân trở lên, trừ khi có biển báo giới hạn thấp hơn.","p":"Đúng. Xa lộ liên bang ở vùng nông thôn Montana là 80 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa interstate sa labas ng lungsod na may 50,000 tao o higit pa?","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"Isa ito sa pinakamataas na limit sa bansa.","h2":"Itinatakda ng batas ng Montana ang 80 mph sa lahat ng oras sa mga interstate sa labas ng urban area na may 50,000 tao o higit pa, maliban kung may nakapaskil na mas mababang limit.","p":"Tama. 80 mph ang mga interstate sa probinsiya ng Montana."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة على الطريق السريع بين الولايات (interstate) خارج مدينة يسكنها 50,000 شخص أو أكثر؟","o":["75 mph","80 mph","70 mph","85 mph"],"h1":"إنه من أعلى الحدود في البلاد.","h2":"يحدّد قانون Montana سرعة 80 mph في كل الأوقات على الطرق السريعة بين الولايات خارج المناطق الحضرية التي يسكنها 50,000 شخص أو أكثر، إلا إذا كانت هناك لافتة بحد أقل.","p":"صحيح. الطرق السريعة بين الولايات في ريف Montana حدها 80 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-012","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, what is the speed limit on an interstate inside an urban area of 50,000 people or more, such as Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"It is 15 mph lower than on rural interstates.","h2":"Montana law sets 65 mph on interstates inside urbanized areas of 50,000 people or more, because traffic there is heavier.","p":"Right. Urban interstates in Montana are 65 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una autopista interestatal dentro de una zona urbana de 50,000 habitantes o más, como Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Es 15 mph menos que en las interestatales rurales.","h2":"La ley de Montana fija 65 mph en las autopistas interestatales dentro de zonas urbanas de 50,000 habitantes o más, porque allí hay más tráfico.","p":"Correcto. Las interestatales urbanas de Montana son de 65 mph."},"zh":{"q":"在 Montana，在人口 50,000 或以上的城市地区里，比如 Billings，州际公路的限速是多少？","o":["55 英里/小时","70 英里/小时","80 英里/小时","65 英里/小时"],"h1":"它比乡村的州际公路低 15 英里/小时。","h2":"Montana 法律规定，在人口 50,000 或以上的城市化地区里，州际公路限速 65 英里/小时，因为那里车更多。","p":"对。Montana 城市里的州际公路限速 65 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trên xa lộ liên bang bên trong khu đô thị có 50,000 dân trở lên, như Billings, là bao nhiêu?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Thấp hơn 15 mph so với xa lộ liên bang ở nông thôn.","h2":"Luật Montana đặt giới hạn 65 mph trên xa lộ liên bang bên trong khu đô thị có 50,000 dân trở lên, vì giao thông ở đó đông hơn.","p":"Đúng. Xa lộ liên bang trong đô thị ở Montana là 65 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa interstate sa loob ng urban area na may 50,000 tao o higit pa, gaya ng Billings?","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"Mas mababa ito nang 15 mph kaysa sa mga interstate sa probinsiya.","h2":"Itinatakda ng batas ng Montana ang 65 mph sa mga interstate sa loob ng urban area na may 50,000 tao o higit pa, dahil mas mabigat ang trapiko roon.","p":"Tama. 65 mph ang mga interstate sa lungsod sa Montana."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة على الطريق السريع بين الولايات داخل منطقة حضرية يسكنها 50,000 شخص أو أكثر، مثل Billings؟","o":["55 mph","70 mph","80 mph","65 mph"],"h1":"إنه أقل بـ 15 mph من الطرق السريعة في الريف.","h2":"يحدّد قانون Montana سرعة 65 mph على الطرق السريعة بين الولايات داخل المناطق الحضرية التي يسكنها 50,000 شخص أو أكثر، لأن حركة المرور هناك أكثف.","p":"صحيح. الطرق السريعة بين الولايات داخل المدن في Montana حدها 65 mph."},"ref":{"doc":"MT","page":38}},{"id":"mt-013","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, what is the daytime speed limit for a car on a two-lane highway?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"The night limit on the same road is 5 mph lower.","h2":"On a Montana two-lane highway, a car may go up to 70 mph in the daytime, unless a sign shows a different limit.","p":"Right. Two-lane highways are 70 mph in the daytime."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de día para un carro en una carretera de dos carriles?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"El límite de noche en esa misma carretera es 5 mph menor.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 70 mph de día, salvo que un letrero indique otro límite.","p":"Correcto. Las carreteras de dos carriles son de 70 mph de día."},"zh":{"q":"在 Montana，汽车在双车道公路上白天的限速是多少？","o":["70 英里/小时","60 英里/小时","65 英里/小时","80 英里/小时"],"h1":"同一条路晚上的限速低 5 英里/小时。","h2":"在 Montana 的双车道公路上，汽车白天最高可以开 70 英里/小时，除非标志显示不同的限速。","p":"对。双车道公路白天限速 70 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa ban ngày cho xe hơi trên xa lộ hai làn là bao nhiêu?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"Giới hạn ban đêm trên cùng con đường thấp hơn 5 mph.","h2":"Trên xa lộ hai làn ở Montana, xe hơi được chạy tối đa 70 mph vào ban ngày, trừ khi biển báo cho thấy giới hạn khác.","p":"Đúng. Xa lộ hai làn là 70 mph vào ban ngày."},"tl":{"q":"Sa Montana, ano ang speed limit sa araw para sa kotse sa two-lane highway (highway na may dalawang lane)?","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"Mas mababa nang 5 mph ang limit sa gabi sa parehong kalsada.","h2":"Sa two-lane highway sa Montana, ang kotse ay maaaring tumakbo hanggang 70 mph sa araw, maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 70 mph ang two-lane highway sa araw."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في النهار للسيارة على طريق سريع بحارتين (two-lane highway)؟","o":["70 mph","60 mph","65 mph","80 mph"],"h1":"الحد في الليل على نفس الطريق أقل بـ 5 mph.","h2":"على طريق سريع بحارتين في Montana، يمكن للسيارة أن تسير حتى 70 mph في النهار، إلا إذا أظهرت لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة بحارتين حدها 70 mph في النهار."},"ref":{"doc":"MT","page":38}},{"id":"mt-014","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, what is the nighttime speed limit for a car on a two-lane highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph lower than the daytime limit.","h2":"On a Montana two-lane highway, a car may go up to 65 mph at night, which is 5 mph lower than in the daytime.","p":"Right. Two-lane highways are 65 mph at night."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad de noche para un carro en una carretera de dos carriles?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de día.","h2":"En una carretera de dos carriles de Montana, un carro puede ir hasta 65 mph de noche, 5 mph menos que de día.","p":"Correcto. Las carreteras de dos carriles son de 65 mph de noche."},"zh":{"q":"在 Montana，汽车在双车道公路上晚上的限速是多少？","o":["55 英里/小时","60 英里/小时","65 英里/小时","70 英里/小时"],"h1":"它比白天的限速低 5 英里/小时。","h2":"在 Montana 的双车道公路上，汽车晚上最高可以开 65 英里/小时，比白天低 5 英里/小时。","p":"对。双车道公路晚上限速 65 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa ban đêm cho xe hơi trên xa lộ hai làn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Thấp hơn 5 mph so với giới hạn ban ngày.","h2":"Trên xa lộ hai làn ở Montana, xe hơi được chạy tối đa 65 mph vào ban đêm, thấp hơn 5 mph so với ban ngày.","p":"Đúng. Xa lộ hai làn là 65 mph vào ban đêm."},"tl":{"q":"Sa Montana, ano ang speed limit sa gabi para sa kotse sa two-lane highway?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa limit sa araw.","h2":"Sa two-lane highway sa Montana, ang kotse ay maaaring tumakbo hanggang 65 mph sa gabi, na mas mababa nang 5 mph kaysa sa araw.","p":"Tama. 65 mph ang two-lane highway sa gabi."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في الليل للسيارة على طريق سريع بحارتين؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"إنه أقل بـ 5 mph من حد النهار.","h2":"على طريق سريع بحارتين في Montana، يمكن للسيارة أن تسير حتى 65 mph في الليل، وهذا أقل بـ 5 mph من النهار.","p":"صحيح. الطرق السريعة بحارتين حدها 65 mph في الليل."},"ref":{"doc":"MT","page":38}},{"id":"mt-015","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, for speed limits, when does \"daytime\" begin and end?","o":["From sunrise to sunset","From 6 a.m. to 6 p.m.","From 7 a.m. to 9 p.m.","From half an hour before sunrise to half an hour after sunset"],"h1":"It adds a little time at each end of the day.","h2":"Montana law defines daytime as from half an hour before sunrise to half an hour after sunset, and every other hour counts as nighttime.","p":"Right. Daytime runs half an hour before sunrise to half an hour after sunset."},"es":{"q":"En Montana, para los límites de velocidad, ¿cuándo empieza y termina el \"día\"?","o":["Desde la salida hasta la puesta del sol","De 6 a.m. a 6 p.m.","De 7 a.m. a 9 p.m.","Desde media hora antes de la salida del sol hasta media hora después de la puesta"],"h1":"Agrega un poco de tiempo a cada extremo del día.","h2":"La ley de Montana define el día como desde media hora antes de la salida del sol hasta media hora después de la puesta, y toda otra hora cuenta como noche.","p":"Correcto. El día va de media hora antes del amanecer a media hora después del atardecer."},"zh":{"q":"在 Montana，对限速来说，“白天”从什么时候开始，到什么时候结束？","o":["从日出到日落","从早上 6 点到晚上 6 点","从早上 7 点到晚上 9 点","从日出前半小时到日落后半小时"],"h1":"它在一天的两头各多加一点时间。","h2":"Montana 法律规定，白天是从日出前半小时到日落后半小时，其他时间都算晚上。","p":"对。白天是从日出前半小时到日落后半小时。"},"vi":{"q":"Ở Montana, đối với giới hạn tốc độ, \"ban ngày\" bắt đầu và kết thúc khi nào?","o":["Từ lúc mặt trời mọc đến lúc mặt trời lặn","Từ 6 giờ sáng đến 6 giờ chiều","Từ 7 giờ sáng đến 9 giờ tối","Từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn"],"h1":"Có thêm một chút thời gian ở mỗi đầu ngày.","h2":"Luật Montana định nghĩa ban ngày là từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn, và mọi giờ khác được tính là ban đêm.","p":"Đúng. Ban ngày là từ nửa giờ trước khi mặt trời mọc đến nửa giờ sau khi mặt trời lặn."},"tl":{"q":"Sa Montana, para sa speed limit, kailan nagsisimula at nagtatapos ang \"araw\" (daytime)?","o":["Mula pagsikat hanggang paglubog ng araw","Mula 6 a.m. hanggang 6 p.m.","Mula 7 a.m. hanggang 9 p.m.","Mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw"],"h1":"May dagdag na kaunting oras sa bawat dulo ng araw.","h2":"Itinuturing ng batas ng Montana na daytime ang oras mula kalahating oras bago sumikat ang araw hanggang kalahating oras pagkalubog ng araw, at ang lahat ng ibang oras ay gabi.","p":"Tama. Ang daytime ay mula kalahating oras bago sumikat hanggang kalahating oras pagkalubog ng araw."},"ar":{"q":"في Montana، بالنسبة لحدود السرعة، متى يبدأ \"النهار\" (daytime) ومتى ينتهي؟","o":["من شروق الشمس إلى غروبها","من 6 صباحًا إلى 6 مساءً","من 7 صباحًا إلى 9 مساءً","من نصف ساعة قبل شروق الشمس إلى نصف ساعة بعد غروبها"],"h1":"يضيف وقتًا قليلًا في كل طرف من اليوم.","h2":"يعرّف قانون Montana النهار بأنه من نصف ساعة قبل شروق الشمس إلى نصف ساعة بعد غروبها، وكل ساعة أخرى تُحسب ليلًا.","p":"صحيح. النهار من نصف ساعة قبل الشروق إلى نصف ساعة بعد الغروب."},"ref":{"doc":"MT","page":null}},{"id":"mt-016","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, what is the speed limit in an urban district, if no sign says otherwise?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"It is the same number many states use near homes.","h2":"Montana law sets 25 mph in urban districts unless a different limit is posted, because people and cars are close together there.","p":"Right. Urban districts are 25 mph."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una zona urbana, si no hay letrero que diga otra cosa?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Es el mismo número que muchos estados usan cerca de las casas.","h2":"La ley de Montana fija 25 mph en zonas urbanas salvo que se indique otro límite, porque allí la gente y los carros están muy cerca.","p":"Correcto. Las zonas urbanas son de 25 mph."},"zh":{"q":"在 Montana，如果没有标志另外规定，城区（urban district）的限速是多少？","o":["20 英里/小时","25 英里/小时","35 英里/小时","45 英里/小时"],"h1":"很多州在住家附近也用这个数字。","h2":"Montana 法律规定，除非标出不同的限速，城区限速 25 英里/小时，因为那里人和车都很近。","p":"对。城区限速 25 英里/小时。"},"vi":{"q":"Ở Montana, tốc độ tối đa trong khu đô thị là bao nhiêu, nếu không có biển báo khác?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Đây là con số mà nhiều tiểu bang dùng gần khu nhà ở.","h2":"Luật Montana đặt giới hạn 25 mph trong khu đô thị trừ khi có biển báo giới hạn khác, vì ở đó người và xe ở gần nhau.","p":"Đúng. Khu đô thị là 25 mph."},"tl":{"q":"Sa Montana, ano ang speed limit sa urban district kung walang karatulang nagsasabi ng iba?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Ito ang parehong numero na ginagamit ng maraming estado malapit sa mga bahay.","h2":"Itinatakda ng batas ng Montana ang 25 mph sa mga urban district maliban kung may nakapaskil na ibang limit, dahil magkakalapit doon ang mga tao at sasakyan.","p":"Tama. 25 mph ang mga urban district."},"ar":{"q":"في Montana، ما الحد الأقصى للسرعة في منطقة حضرية (urban district) إذا لم تقل لافتة غير ذلك؟","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"إنه نفس الرقم الذي تستخدمه ولايات كثيرة قرب البيوت.","h2":"يحدّد قانون Montana سرعة 25 mph في المناطق الحضرية إلا إذا كانت هناك لافتة بحد مختلف، لأن الناس والسيارات قريبون من بعضهم هناك.","p":"صحيح. المناطق الحضرية حدها 25 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-017","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, on a two-lane highway, when may you go up to 10 mph over the limit?","o":["Whenever traffic is light","When you are late for work","Only while passing in a passing zone","Only at night on empty roads"],"h1":"It is a short moment, not a whole trip.","h2":"Montana lets you exceed the limit by up to 10 mph only while passing on a two-lane highway in a passing zone, and you must return safely to the right lane.","p":"Right. Only while passing, in a passing zone."},"es":{"q":"En Montana, en una carretera de dos carriles, ¿cuándo puede ir hasta 10 mph por encima del límite?","o":["Siempre que haya poco tráfico","Cuando va tarde al trabajo","Solo mientras rebasa en una zona de rebase","Solo de noche en caminos vacíos"],"h1":"Es un momento corto, no todo el viaje.","h2":"Montana le permite pasar el límite hasta por 10 mph solo mientras rebasa en una carretera de dos carriles, en una zona de rebase, y debe volver con seguridad al carril derecho.","p":"Correcto. Solo al rebasar, en una zona de rebase."},"zh":{"q":"在 Montana，在双车道公路上，什么时候可以超过限速最多 10 英里/小时？","o":["只要车少的时候","上班要迟到的时候","只有在超车区超车的时候","只有晚上路上没车的时候"],"h1":"这只是很短的一会儿，不是整段路程。","h2":"Montana 只允许你在双车道公路的超车区超车时，超过限速最多 10 英里/小时，而且你必须安全地回到右边车道。","p":"对。只有在超车区超车的时候。"},"vi":{"q":"Ở Montana, trên xa lộ hai làn, khi nào bạn được chạy vượt giới hạn tối đa 10 mph?","o":["Bất cứ khi nào xe cộ ít","Khi bạn bị trễ giờ làm","Chỉ khi đang vượt xe trong khu vực được phép vượt","Chỉ vào ban đêm trên đường vắng"],"h1":"Đó là một khoảnh khắc ngắn, không phải cả chuyến đi.","h2":"Montana cho phép bạn chạy vượt giới hạn tối đa 10 mph chỉ khi đang vượt xe trên xa lộ hai làn trong khu vực được phép vượt, và bạn phải trở lại làn bên phải một cách an toàn.","p":"Đúng. Chỉ khi đang vượt xe, trong khu vực được phép vượt."},"tl":{"q":"Sa Montana, sa two-lane highway, kailan ka maaaring lumampas nang hanggang 10 mph sa limit?","o":["Kapag kaunti ang trapiko","Kapag huli ka na sa trabaho","Habang nag-o-overtake lang sa passing zone","Sa gabi lang sa walang lamang kalsada"],"h1":"Maikling sandali lang ito, hindi ang buong biyahe.","h2":"Pinapayagan ka ng Montana na lumampas nang hanggang 10 mph sa limit habang nag-o-overtake lang sa two-lane highway sa passing zone, at dapat kang bumalik nang ligtas sa kanang lane.","p":"Tama. Habang nag-o-overtake lang, sa passing zone."},"ar":{"q":"في Montana، على طريق سريع بحارتين، متى يمكنك أن تتجاوز الحد بما يصل إلى 10 mph؟","o":["عندما تكون حركة المرور خفيفة","عندما تتأخر عن العمل","فقط أثناء التجاوز في منطقة يُسمح فيها بالتجاوز","فقط في الليل على الطرق الخالية"],"h1":"إنها لحظة قصيرة، وليست رحلة كاملة.","h2":"تسمح Montana بتجاوز الحد بما يصل إلى 10 mph فقط أثناء التجاوز على طريق سريع بحارتين في منطقة يُسمح فيها بالتجاوز، ويجب أن تعود بأمان إلى الحارة اليمنى.","p":"صحيح. فقط أثناء التجاوز، في منطقة يُسمح فيها بالتجاوز."},"ref":{"doc":"MT","page":38}},{"id":"mt-018","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, a driver under 21 breaks the law with what blood alcohol level or more?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is far below the adult limit.","h2":"In Montana it is illegal for a person under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Montana, ¿a partir de qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Está muy por debajo del límite para adultos.","h2":"En Montana es ilegal que una persona menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Montana，21 岁以下的司机血液酒精浓度达到多少或更高就违法？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"它远低于成年人的限值。","h2":"在 Montana，21 岁以下的人血液酒精浓度达到 0.02% 或更高时开车是违法的。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở Montana, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu từ mức nào trở lên?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Mức này thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Montana, người dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 phần trăm trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Montana, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay umabot sa anong antas o higit pa?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limit para sa adult.","h2":"Sa Montana, bawal sa taong wala pang 21 na magmaneho na may blood alcohol level na 0.02 porsiyento o higit pa.","p":"Tama. Kung wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Montana، يخالف السائق الذي عمره أقل من 21 سنة القانون عند أي نسبة كحول في الدم أو أكثر؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في Montana يُمنع على الشخص الذي عمره أقل من 21 سنة أن يقود ونسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. لمن هم أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"MT","page":72}},{"id":"mt-019","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what is the legal blood alcohol limit for an adult driving a regular car?","o":["0.05 percent","0.08 percent","0.04 percent","0.10 percent"],"h1":"It is the most common adult limit in the United States.","h2":"In Montana an adult driving a regular car is legally under the influence at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08."},"es":{"q":"En Montana, ¿cuál es el límite legal de alcohol en la sangre para un adulto que maneja un carro común?","o":["0.05 por ciento","0.08 por ciento","0.04 por ciento","0.10 por ciento"],"h1":"Es el límite para adultos más común en Estados Unidos.","h2":"En Montana, un adulto que maneja un carro común está legalmente bajo la influencia con un nivel de alcohol de 0.08 por ciento o más.","p":"Correcto. El límite para adultos es 0.08."},"zh":{"q":"在 Montana，成年人开普通汽车时，法定的血液酒精浓度限值是多少？","o":["0.05%","0.08%","0.04%","0.10%"],"h1":"这是美国最常见的成年人限值。","h2":"在 Montana，成年人开普通汽车时，血液酒精浓度达到 0.08% 或更高，在法律上就算受酒精影响。","p":"对。成年人的限值是 0.08。"},"vi":{"q":"Ở Montana, giới hạn nồng độ cồn trong máu theo luật cho người lớn lái xe hơi thông thường là bao nhiêu?","o":["0.05 phần trăm","0.08 phần trăm","0.04 phần trăm","0.10 phần trăm"],"h1":"Đây là giới hạn phổ biến nhất cho người lớn ở Hoa Kỳ.","h2":"Ở Montana, người lớn lái xe hơi thông thường bị coi là say xỉn theo luật khi nồng độ cồn trong máu từ 0.08 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08."},"tl":{"q":"Sa Montana, ano ang legal na blood alcohol limit para sa adult na nagmamaneho ng karaniwang kotse?","o":["0.05 porsiyento","0.08 porsiyento","0.04 porsiyento","0.10 porsiyento"],"h1":"Ito ang pinakakaraniwang limit para sa adult sa Estados Unidos.","h2":"Sa Montana, ang adult na nagmamaneho ng karaniwang kotse ay legal na lasing kapag ang blood alcohol level ay 0.08 porsiyento o higit pa.","p":"Tama. Ang limit para sa adult ay 0.08."},"ar":{"q":"في Montana، ما الحد القانوني لنسبة الكحول في الدم للبالغ الذي يقود سيارة عادية؟","o":["0.05 بالمئة","0.08 بالمئة","0.04 بالمئة","0.10 بالمئة"],"h1":"إنه الحد الأكثر شيوعًا للبالغين في الولايات المتحدة.","h2":"في Montana يُعتبر البالغ الذي يقود سيارة عادية تحت تأثير الكحول قانونيًا عندما تكون نسبة الكحول في دمه 0.08 بالمئة أو أكثر.","p":"صحيح. حد البالغين هو 0.08."},"ref":{"doc":"MT","page":72}},{"id":"mt-020","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, where can a driver be ticketed for using a hand-held phone while driving?","o":["On every road in the state","Only on interstate highways","Only in school zones statewide","Only in cities or counties with their own ban"],"h1":"Montana has no statewide ban, but some local governments do.","h2":"Montana has no statewide ban on hand-held phones or texting while driving, but many cities have their own bans, so a ticket depends on local law.","p":"Right. Only where a city or county has its own ban."},"es":{"q":"En Montana, ¿dónde se puede multar a un conductor por usar el teléfono en la mano al manejar?","o":["En todos los caminos del estado","Solo en las autopistas interestatales","Solo en zonas escolares de todo el estado","Solo en ciudades o condados con su propia prohibición"],"h1":"Montana no tiene una prohibición estatal, pero algunos gobiernos locales sí.","h2":"Montana no tiene una prohibición estatal de usar el teléfono en la mano o enviar mensajes al manejar, pero muchas ciudades tienen la suya, así que la multa depende de la ley local.","p":"Correcto. Solo donde la ciudad o el condado lo prohíbe."},"zh":{"q":"在 Montana，司机在哪里开车时手拿手机可能会被开罚单？","o":["全州每一条路上","只在州际公路上","只在全州的学校区域","只在有自己禁令的市或县"],"h1":"Montana 没有全州的禁令，但有些地方政府有。","h2":"Montana 没有全州禁止开车时手拿手机或发短信的法律，但很多城市有自己的禁令，所以会不会被开罚单要看当地法律。","p":"对。只在有自己禁令的市或县。"},"vi":{"q":"Ở Montana, người lái có thể bị phạt ở đâu vì cầm điện thoại trên tay khi lái xe?","o":["Trên mọi con đường trong tiểu bang","Chỉ trên xa lộ liên bang","Chỉ trong khu vực trường học trên toàn tiểu bang","Chỉ ở những thành phố hoặc quận có lệnh cấm riêng"],"h1":"Montana không có lệnh cấm toàn tiểu bang, nhưng một số chính quyền địa phương có.","h2":"Montana không có lệnh cấm toàn tiểu bang về việc cầm điện thoại hoặc nhắn tin khi lái xe, nhưng nhiều thành phố có lệnh cấm riêng, nên việc bị phạt tùy vào luật địa phương.","p":"Đúng. Chỉ ở nơi thành phố hoặc quận có lệnh cấm riêng."},"tl":{"q":"Sa Montana, saan maaaring tiketan ang driver dahil sa paggamit ng hawak na telepono habang nagmamaneho?","o":["Sa bawat kalsada sa estado","Sa mga interstate highway lang","Sa mga school zone lang sa buong estado","Sa mga lungsod o county lang na may sariling pagbabawal"],"h1":"Walang pagbabawal sa buong estado ang Montana, pero mayroon ang ilang lokal na pamahalaan.","h2":"Walang pagbabawal sa buong Montana sa paghawak ng telepono o pag-text habang nagmamaneho, pero maraming lungsod ang may sariling pagbabawal, kaya ang tiket ay depende sa lokal na batas.","p":"Tama. Kung saan lang may sariling pagbabawal ang lungsod o county."},"ar":{"q":"في Montana، أين يمكن أن يحصل السائق على مخالفة لاستخدامه الهاتف باليد أثناء القيادة؟","o":["على كل طريق في الولاية","على الطرق السريعة بين الولايات فقط","في مناطق المدارس فقط في كل الولاية","فقط في المدن أو المقاطعات التي لها منع خاص بها"],"h1":"ليس في Montana منع على مستوى الولاية، لكن بعض الحكومات المحلية لديها منع.","h2":"ليس في Montana منع على مستوى الولاية لاستخدام الهاتف باليد أو كتابة الرسائل أثناء القيادة، لكن مدنًا كثيرة لها منع خاص بها، لذلك تعتمد المخالفة على القانون المحلي.","p":"صحيح. فقط حيث يكون للمدينة أو المقاطعة منع خاص بها."},"ref":{"doc":"MT","page":49}},{"id":"mt-021","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, can police stop an adult driver only because they are not wearing a seat belt?","o":["No, only for another violation","Yes, at any time","Yes, but only at night","Yes, but only on interstates"],"h1":"For adults, the belt law is enforced together with another stop.","h2":"Montana's adult seat belt law is secondary, so police may ticket for it only after stopping a driver for another violation; you should still always buckle up.","p":"Right. For adults, the seat belt law is secondary."},"es":{"q":"En Montana, ¿puede la policía detener a un conductor adulto solo porque no lleva el cinturón de seguridad?","o":["No, solo por otra infracción","Sí, en cualquier momento","Sí, pero solo de noche","Sí, pero solo en interestatales"],"h1":"Para adultos, la ley del cinturón se aplica junto con otra detención.","h2":"La ley del cinturón para adultos en Montana es secundaria, así que la policía puede multar por ella solo después de detener al conductor por otra infracción; aun así, siempre debe abrocharse.","p":"Correcto. Para adultos, la ley del cinturón es secundaria."},"zh":{"q":"在 Montana，警察可以只因为成年司机没系安全带就让他停车吗？","o":["不可以，只能因为其他违规","可以，任何时候","可以，但只在晚上","可以，但只在州际公路上"],"h1":"对成年人来说，安全带法要和其他原因的拦车一起执行。","h2":"Montana 的成年人安全带法是次要执法，所以警察只有在因为其他违规让司机停车以后，才可以为这个开罚单；你还是应该一直系好安全带。","p":"对。对成年人来说，安全带法是次要执法。"},"vi":{"q":"Ở Montana, cảnh sát có thể dừng xe một người lái là người lớn chỉ vì họ không thắt dây an toàn không?","o":["Không, chỉ khi có vi phạm khác","Có, bất cứ lúc nào","Có, nhưng chỉ vào ban đêm","Có, nhưng chỉ trên xa lộ liên bang"],"h1":"Với người lớn, luật dây an toàn được áp dụng cùng với một lần dừng xe vì lý do khác.","h2":"Luật dây an toàn cho người lớn ở Montana là luật thứ cấp, nên cảnh sát chỉ được phạt lỗi này sau khi đã dừng xe vì một vi phạm khác; bạn vẫn nên luôn thắt dây an toàn.","p":"Đúng. Với người lớn, luật dây an toàn là luật thứ cấp."},"tl":{"q":"Sa Montana, maaari bang patigilin ng pulis ang adult na driver dahil lang hindi siya naka-seat belt?","o":["Hindi, kapag may ibang paglabag lang","Oo, kahit kailan","Oo, pero sa gabi lang","Oo, pero sa mga interstate lang"],"h1":"Para sa adult, ipinapatupad ang batas sa seat belt kasabay ng ibang dahilan ng pagpapatigil.","h2":"Secondary ang batas sa seat belt para sa adult sa Montana, kaya maaari lang itong tiketan ng pulis pagkatapos patigilin ang driver dahil sa ibang paglabag; dapat ka pa ring laging mag-seat belt.","p":"Tama. Para sa adult, secondary ang batas sa seat belt."},"ar":{"q":"في Montana، هل يمكن للشرطة أن توقف سائقًا بالغًا فقط لأنه لا يربط حزام الأمان؟","o":["لا، فقط مع مخالفة أخرى","نعم، في أي وقت","نعم، لكن في الليل فقط","نعم، لكن على الطرق السريعة بين الولايات فقط"],"h1":"بالنسبة للبالغين، يُطبَّق قانون الحزام مع إيقاف لسبب آخر.","h2":"قانون حزام الأمان للبالغين في Montana قانون ثانوي، لذلك يمكن للشرطة أن تعطي مخالفة عليه فقط بعد إيقاف السائق بسبب مخالفة أخرى؛ ومع ذلك يجب أن تربط الحزام دائمًا.","p":"صحيح. بالنسبة للبالغين، قانون حزام الأمان ثانوي."},"ref":{"doc":"MT","page":null}},{"id":"mt-022","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you come up on a stopped police car, emergency vehicle, or highway work vehicle with its lights flashing. What must you do?","o":["Keep your lane and your speed","Stop next to it until it leaves","Slow down and move to a lane away from it if you safely can","Honk to warn the workers"],"h1":"The law asks you to give workers both space and time.","h2":"In Montana you must slow down when you pass a stopped police, emergency or highway work vehicle with flashing lights, and move to a lane that is not next to it when you safely can.","p":"Right. Slow down and move over when you safely can."},"es":{"q":"En Montana, usted se acerca a un carro de policía, vehículo de emergencia o vehículo de obras viales detenido con las luces intermitentes. ¿Qué debe hacer?","o":["Seguir en su carril y a su velocidad","Pararse a su lado hasta que se vaya","Bajar la velocidad y pasarse a un carril alejado si puede hacerlo con seguridad","Tocar la bocina para avisar a los trabajadores"],"h1":"La ley le pide dar a los trabajadores espacio y tiempo.","h2":"En Montana, usted debe bajar la velocidad al pasar un vehículo de policía, de emergencia o de obras viales detenido con luces intermitentes, y pasarse a un carril que no esté junto a él cuando pueda hacerlo con seguridad.","p":"Correcto. Baje la velocidad y cámbiese de carril cuando sea seguro."},"zh":{"q":"在 Montana，你遇到一辆停着、闪着灯的警车、急救车辆或公路工作车辆。你必须怎么做？","o":["保持你的车道和速度","在它旁边停车，直到它开走","减速，如果能安全换道，就换到离它远的车道","按喇叭提醒工作人员"],"h1":"法律要求你给工作人员留出空间和时间。","h2":"在 Montana，你经过停着、闪着灯的警车、急救车辆或公路工作车辆时必须减速，能安全换道时，要换到不紧挨着它的车道。","p":"对。减速，能安全换道时就让出车道。"},"vi":{"q":"Ở Montana, bạn đến gần một xe cảnh sát, xe cấp cứu hoặc xe làm việc trên xa lộ đang dừng và nháy đèn. Bạn phải làm gì?","o":["Giữ nguyên làn và tốc độ","Dừng bên cạnh cho đến khi xe đó rời đi","Giảm tốc độ và chuyển sang làn cách xa xe đó nếu có thể làm an toàn","Bấm còi để cảnh báo công nhân"],"h1":"Luật yêu cầu bạn cho công nhân cả khoảng cách và thời gian.","h2":"Ở Montana, bạn phải giảm tốc độ khi đi qua xe cảnh sát, xe cấp cứu hoặc xe làm việc trên xa lộ đang dừng và nháy đèn, và chuyển sang làn không sát bên xe đó khi có thể làm an toàn.","p":"Đúng. Giảm tốc độ và chuyển làn khi có thể làm an toàn."},"tl":{"q":"Sa Montana, papalapit ka sa nakahintong sasakyan ng pulis, emergency vehicle, o sasakyang pantrabaho sa highway na kumikislap ang ilaw. Ano ang dapat mong gawin?","o":["Manatili sa iyong lane at bilis","Huminto sa tabi nito hanggang umalis ito","Bumagal at lumipat sa lane na malayo rito kung ligtas","Bumusina para balaan ang mga manggagawa"],"h1":"Hinihingi ng batas na bigyan mo ang mga manggagawa ng espasyo at oras.","h2":"Sa Montana, dapat kang bumagal kapag dumadaan sa nakahintong sasakyan ng pulis, emergency o pantrabaho sa highway na kumikislap ang ilaw, at lumipat sa lane na hindi katabi nito kapag ligtas.","p":"Tama. Bumagal at lumipat ng lane kapag ligtas."},"ar":{"q":"في Montana، تقترب من سيارة شرطة أو مركبة طوارئ أو مركبة عمل على الطريق السريع متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["تبقى في حارتك وبنفس سرعتك","تتوقف بجانبها حتى تغادر","تخفّف السرعة وتنتقل إلى حارة بعيدة عنها إذا أمكنك ذلك بأمان","تستخدم البوق لتحذير العمال"],"h1":"يطلب القانون أن تعطي العمال مساحة ووقتًا.","h2":"في Montana يجب أن تخفّف السرعة عندما تمر بجانب سيارة شرطة أو مركبة طوارئ أو مركبة عمل على الطريق السريع متوقفة وأضواؤها تومض، وأن تنتقل إلى حارة ليست بجانبها عندما يمكنك ذلك بأمان.","p":"صحيح. خفّف السرعة وانتقل إلى حارة أخرى عندما يمكنك ذلك بأمان."},"ref":{"doc":"MT","page":null}},{"id":"mt-023","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, on a divided highway with a raised median, which drivers must stop for a school bus with flashing red lights?","o":["All drivers in both directions","Drivers going the same direction as the bus","Only drivers in the lane next to the bus","Only drivers going the opposite direction"],"h1":"The raised median keeps children from crossing the far side.","h2":"On a Montana divided highway with a raised median, drivers going the same direction as a stopped school bus must stop, while traffic on the other side does not have to.","p":"Right. With a raised median, same-direction traffic stops."},"es":{"q":"En Montana, en una carretera dividida con camellón elevado, ¿qué conductores deben parar ante un autobús escolar con luces rojas intermitentes?","o":["Todos los conductores en ambas direcciones","Los que van en la misma dirección que el autobús","Solo los del carril junto al autobús","Solo los que van en dirección contraria"],"h1":"El camellón elevado impide que los niños crucen al otro lado.","h2":"En una carretera dividida con camellón elevado en Montana, los conductores que van en la misma dirección que el autobús escolar detenido deben parar, y el tráfico del otro lado no tiene que hacerlo.","p":"Correcto. Con camellón elevado, para el tráfico de la misma dirección."},"zh":{"q":"在 Montana，在有凸起中央隔离带的分隔公路上，哪些司机必须为闪着红灯的校车停车？","o":["两个方向的所有司机","和校车同方向的司机","只有校车旁边车道的司机","只有对面方向的司机"],"h1":"凸起的隔离带让孩子不会穿过远的那一边。","h2":"在 Montana 有凸起中央隔离带的分隔公路上，和停着的校车同方向的司机必须停车，另一边的车不必停。","p":"对。有凸起的隔离带时，同方向的车要停。"},"vi":{"q":"Ở Montana, trên xa lộ có dải phân cách nổi (raised median), những người lái nào phải dừng lại khi xe buýt trường học nháy đèn đỏ?","o":["Tất cả người lái ở cả hai chiều","Người lái đi cùng chiều với xe buýt","Chỉ người lái ở làn sát bên xe buýt","Chỉ người lái đi ngược chiều"],"h1":"Dải phân cách nổi giữ cho trẻ em không băng qua phía bên kia.","h2":"Trên xa lộ có dải phân cách nổi ở Montana, người lái đi cùng chiều với xe buýt trường học đang dừng phải dừng lại, còn xe ở phía bên kia thì không cần dừng.","p":"Đúng. Có dải phân cách nổi thì xe đi cùng chiều phải dừng."},"tl":{"q":"Sa Montana, sa divided highway na may raised median (nakataas na harang sa gitna), sinong mga driver ang dapat huminto para sa school bus na kumikislap ang pulang ilaw?","o":["Lahat ng driver sa dalawang direksiyon","Mga driver na papunta sa parehong direksiyon ng bus","Mga driver lang sa lane na katabi ng bus","Mga driver lang na papunta sa kabilang direksiyon"],"h1":"Pinipigilan ng raised median ang mga bata na tumawid sa kabilang panig.","h2":"Sa divided highway sa Montana na may raised median, ang mga driver na papunta sa parehong direksiyon ng nakahintong school bus ay dapat huminto, at ang trapiko sa kabilang panig ay hindi kailangang huminto.","p":"Tama. Kapag may raised median, ang trapikong kapareho ng direksiyon ang humihinto."},"ar":{"q":"في Montana، على طريق سريع مقسوم بفاصل مرتفع في الوسط (raised median)، أي السائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["كل السائقين في الاتجاهين","السائقون الذين يسيرون في نفس اتجاه الحافلة","فقط السائقون في الحارة التي بجانب الحافلة","فقط السائقون الذين يسيرون في الاتجاه المعاكس"],"h1":"الفاصل المرتفع يمنع الأطفال من العبور إلى الجانب الآخر.","h2":"على طريق سريع مقسوم في Montana بفاصل مرتفع، يجب على السائقين الذين يسيرون في نفس اتجاه الحافلة المدرسية المتوقفة أن يتوقفوا، أما حركة المرور على الجانب الآخر فلا يلزمها التوقف.","p":"صحيح. مع الفاصل المرتفع، تتوقف حركة المرور في نفس الاتجاه."},"ref":{"doc":"MT","page":40}},{"id":"mt-024","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what is the minimum liability insurance a driver must carry?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"The property damage part is $20,000.","h2":"Montana requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $20,000 for property damage.","p":"Right. Montana's minimum is 25/50/20."},"es":{"q":"En Montana, ¿cuál es el seguro de responsabilidad mínimo que debe tener un conductor?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"La parte de daños a la propiedad es de $20,000.","h2":"Montana exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un mismo choque y $20,000 por daños a la propiedad.","p":"Correcto. El mínimo en Montana es 25/50/20."},"zh":{"q":"在 Montana，司机必须买的最低责任保险是多少？","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"财产损失的部分是 $20,000。","h2":"Montana 要求一个人受伤至少 $25,000，一次车祸中的伤害至少 $50,000，财产损失至少 $20,000。","p":"对。Montana 的最低标准是 25/50/20。"},"vi":{"q":"Ở Montana, mức bảo hiểm trách nhiệm (liability insurance) tối thiểu mà người lái phải có là bao nhiêu?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"Phần thiệt hại tài sản là $20,000.","h2":"Montana yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $20,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Montana là 25/50/20."},"tl":{"q":"Sa Montana, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"$20,000 ang bahagi para sa pinsala sa ari-arian.","h2":"Hinihingi ng Montana ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang aksidente, at $20,000 para sa pinsala sa ari-arian.","p":"Tama. 25/50/20 ang pinakamababa sa Montana."},"ar":{"q":"في Montana، ما الحد الأدنى لتأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$25,000 / $50,000 / $20,000","$25,000 / $50,000 / $15,000","$50,000 / $100,000 / $25,000","$15,000 / $30,000 / $10,000"],"h1":"جزء الأضرار بالممتلكات هو $20,000.","h2":"تطلب Montana على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$20,000 للأضرار بالممتلكات.","p":"صحيح. الحد الأدنى في Montana هو 25/50/20."},"ref":{"doc":"MT","page":null}},{"id":"mt-025","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, cattle are crossing the road ahead of you in open range country. What should you do?","o":["Honk so they move faster","Drive slowly through the herd","Nudge them gently with the bumper","Stop and wait until they have crossed"],"h1":"Animals can slip on pavement when they are scared.","h2":"In Montana's open range, when livestock are crossing the road you should stop and wait, because honking or pushing can make animals panic and fall.","p":"Right. Stop and wait for the animals to cross."},"es":{"q":"En Montana, unas vacas cruzan el camino delante de usted en zona de campo abierto. ¿Qué debe hacer?","o":["Tocar la bocina para que se apuren","Pasar despacio entre el ganado","Empujarlas suavemente con el parachoques","Parar y esperar hasta que hayan cruzado"],"h1":"Los animales pueden resbalar en el pavimento cuando se asustan.","h2":"En el campo abierto de Montana, cuando el ganado cruza el camino usted debe parar y esperar, porque la bocina o los empujones pueden asustar a los animales y hacerlos caer.","p":"Correcto. Pare y espere a que crucen los animales."},"zh":{"q":"在 Montana，在开放牧场（open range）地区，前面有牛在过马路。你应该怎么做？","o":["按喇叭让它们走快点","慢慢开过牛群","用保险杠轻轻推它们","停车，等它们过完"],"h1":"动物受惊时可能在路面上滑倒。","h2":"在 Montana 的开放牧场，牲畜过马路时你应该停车等待，因为按喇叭或推它们会让动物惊慌并摔倒。","p":"对。停车，等动物过完马路。"},"vi":{"q":"Ở Montana, bò đang băng qua đường phía trước bạn ở vùng chăn thả tự do (open range). Bạn nên làm gì?","o":["Bấm còi để chúng đi nhanh hơn","Lái chậm xuyên qua đàn bò","Đẩy nhẹ chúng bằng cản xe","Dừng lại và chờ đến khi chúng đã qua đường"],"h1":"Động vật có thể trượt ngã trên mặt đường khi chúng sợ hãi.","h2":"Ở vùng chăn thả tự do của Montana, khi gia súc đang băng qua đường, bạn nên dừng lại và chờ, vì bấm còi hoặc đẩy có thể làm con vật hoảng sợ và ngã.","p":"Đúng. Dừng lại và chờ các con vật băng qua."},"tl":{"q":"Sa Montana, tumatawid ang mga baka sa kalsada sa harap mo sa open range (lupang walang bakod). Ano ang dapat mong gawin?","o":["Bumusina para bumilis sila","Dahan-dahang magmaneho sa gitna ng kawan","Itulak sila nang marahan gamit ang bumper","Huminto at maghintay hanggang makatawid sila"],"h1":"Maaaring madulas ang mga hayop sa kalsada kapag natatakot sila.","h2":"Sa open range ng Montana, kapag tumatawid ang mga alagang hayop sa kalsada, dapat kang huminto at maghintay, dahil ang pagbusina o pagtulak ay maaaring magpataranta at magpabagsak sa mga hayop.","p":"Tama. Huminto at hintaying makatawid ang mga hayop."},"ar":{"q":"في Montana، أبقار تعبر الطريق أمامك في منطقة المراعي المفتوحة (open range). ماذا يجب أن تفعل؟","o":["تستخدم البوق حتى تتحرك أسرع","تقود ببطء وسط القطيع","تدفعها بلطف بمصدّ السيارة","تتوقف وتنتظر حتى تعبر"],"h1":"يمكن أن تنزلق الحيوانات على الطريق عندما تخاف.","h2":"في المراعي المفتوحة في Montana، عندما تعبر المواشي الطريق يجب أن تتوقف وتنتظر، لأن البوق أو الدفع قد يجعل الحيوانات تذعر وتسقط.","p":"صحيح. توقّف وانتظر حتى تعبر الحيوانات."},"ref":{"doc":"MT","page":67}},{"id":"mt-026","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what does \"open range\" mean for drivers?","o":["Roads closed to trucks","Land without a proper fence, where livestock may be on the road","Highways with no speed limit","Areas where hunting is allowed from cars"],"h1":"Think about what a fence keeps off the road.","h2":"In Montana, open range is land not closed in by a fence, including public highways, so cattle and other livestock may be on or near the road.","p":"Right. On open range, expect livestock on the road."},"es":{"q":"En Montana, ¿qué significa \"campo abierto\" (open range) para los conductores?","o":["Caminos cerrados a camiones","Terreno sin una cerca adecuada, donde puede haber ganado en el camino","Carreteras sin límite de velocidad","Zonas donde se permite cazar desde el carro"],"h1":"Piense en lo que una cerca mantiene fuera del camino.","h2":"En Montana, el campo abierto es el terreno que no está cerrado por una cerca, incluidas las carreteras públicas, así que puede haber vacas y otro ganado en el camino o cerca de él.","p":"Correcto. En campo abierto, espere ganado en el camino."},"zh":{"q":"在 Montana，“open range”（开放牧场）对司机来说是什么意思？","o":["禁止卡车通行的道路","没有正规围栏的土地，牲畜可能会在路上","没有限速的公路","可以在车里打猎的地区"],"h1":"想一想围栏能把什么挡在路外。","h2":"在 Montana，开放牧场是没有用围栏围起来的土地，也包括公共公路，所以牛和其他牲畜可能在路上或路边。","p":"对。在开放牧场，要预料路上会有牲畜。"},"vi":{"q":"Ở Montana, \"open range\" (vùng chăn thả tự do) có nghĩa gì đối với người lái?","o":["Đường cấm xe tải","Đất không có hàng rào đúng cách, nơi gia súc có thể ở trên đường","Xa lộ không có giới hạn tốc độ","Khu vực được phép săn bắn từ trong xe"],"h1":"Hãy nghĩ xem hàng rào giữ cái gì khỏi đường.","h2":"Ở Montana, vùng chăn thả tự do là đất không được rào lại, kể cả xa lộ công cộng, nên bò và các gia súc khác có thể ở trên hoặc gần đường.","p":"Đúng. Ở vùng chăn thả tự do, hãy dự đoán có gia súc trên đường."},"tl":{"q":"Sa Montana, ano ang ibig sabihin ng \"open range\" para sa mga driver?","o":["Mga kalsadang sarado sa mga trak","Lupang walang tamang bakod, kung saan maaaring may alagang hayop sa kalsada","Mga highway na walang speed limit","Mga lugar kung saan pinapayagan ang pangangaso mula sa kotse"],"h1":"Isipin kung ano ang pinipigilan ng bakod na makapunta sa kalsada.","h2":"Sa Montana, ang open range ay lupang hindi nababakuran, kasama ang mga pampublikong highway, kaya maaaring may baka at ibang alagang hayop sa kalsada o malapit dito.","p":"Tama. Sa open range, asahan na may alagang hayop sa kalsada."},"ar":{"q":"في Montana، ماذا يعني \"open range\" (المراعي المفتوحة) بالنسبة للسائقين؟","o":["طرق مغلقة أمام الشاحنات","أرض بدون سياج مناسب، حيث قد تكون المواشي على الطريق","طرق سريعة بدون حد للسرعة","مناطق يُسمح فيها بالصيد من السيارات"],"h1":"فكّر في ما يمنعه السياج من الوصول إلى الطريق.","h2":"في Montana، المراعي المفتوحة هي أرض غير محاطة بسياج، ومنها الطرق السريعة العامة، لذلك قد تكون الأبقار والمواشي الأخرى على الطريق أو قريبة منه.","p":"صحيح. في المراعي المفتوحة، توقّع وجود مواشٍ على الطريق."},"ref":{"doc":"MT","page":25}},{"id":"mt-027","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, when does a driver license issued to someone under 21 expire?","o":["On the 21st birthday","On the 18th birthday","Four years after it is issued","Eight years after it is issued"],"h1":"It is tied to a birthday, not a number of years.","h2":"In Montana a driver license issued to someone under 21 expires on that person's 21st birthday.","p":"Right. It expires on the 21st birthday."},"es":{"q":"En Montana, ¿cuándo vence una licencia de manejo emitida a una persona menor de 21 años?","o":["En el cumpleaños número 21","En el cumpleaños número 18","Cuatro años después de emitida","Ocho años después de emitida"],"h1":"Depende de un cumpleaños, no de un número de años.","h2":"En Montana una licencia de manejo emitida a una persona menor de 21 años vence en su cumpleaños número 21.","p":"Correcto. Vence en el cumpleaños número 21."},"zh":{"q":"在 Montana，发给未满 21 岁的人的驾照什么时候到期？","o":["在 21 岁生日那天","在 18 岁生日那天","发证后四年","发证后八年"],"h1":"它和生日有关，而不是年数。","h2":"在 Montana，发给未满 21 岁的人的驾照在这个人 21 岁生日那天到期。","p":"对。它在 21 岁生日那天到期。"},"vi":{"q":"Ở Montana, bằng lái cấp cho người dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật 21 tuổi","Vào sinh nhật 18 tuổi","Bốn năm sau khi cấp","Tám năm sau khi cấp"],"h1":"Nó gắn với ngày sinh nhật, không phải số năm.","h2":"Ở Montana, bằng lái cấp cho người dưới 21 tuổi hết hạn vào ngày sinh nhật 21 tuổi của người đó.","p":"Đúng. Nó hết hạn vào sinh nhật 21 tuổi."},"tl":{"q":"Sa Montana, kailan mag-e-expire ang driver license na ibinigay sa taong wala pang 21 taong gulang?","o":["Sa ika-21 kaarawan","Sa ika-18 kaarawan","Apat na taon matapos itong ibigay","Walong taon matapos itong ibigay"],"h1":"Nakatali ito sa isang kaarawan, hindi sa bilang ng taon.","h2":"Sa Montana, ang driver license na ibinigay sa taong wala pang 21 taong gulang ay mag-e-expire sa ika-21 kaarawan ng taong iyon.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan."},"ar":{"q":"في Montana، متى تنتهي صلاحية رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة؟","o":["في عيد ميلاده الحادي والعشرين","في عيد ميلاده الثامن عشر","بعد أربع سنوات من صدورها","بعد ثماني سنوات من صدورها"],"h1":"ترتبط بعيد ميلاد، لا بعدد من السنوات.","h2":"في Montana تنتهي صلاحية رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة في عيد ميلاده الحادي والعشرين.","p":"صحيح. تنتهي صلاحيتها في عيد الميلاد الحادي والعشرين."},"ref":{"doc":"MT","page":8}},{"id":"mt-028","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, when must you dim your high beams for a car coming toward you?","o":["When it is within 200 feet","When it is within 500 feet","When it is within 1,000 feet","When it is within 1 mile"],"h1":"Montana's distance is longer than in many states.","h2":"In Montana you must dim your high beams when an oncoming car is within 1,000 feet, and when you are within 500 feet behind another car.","p":"Right. Dim within 1,000 feet of an oncoming car."},"es":{"q":"En Montana, ¿cuándo debe bajar las luces altas por un carro que viene hacia usted?","o":["Cuando esté a menos de 200 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,000 pies","Cuando esté a menos de 1 milla"],"h1":"La distancia de Montana es más larga que en muchos estados.","h2":"En Montana usted debe bajar las luces altas cuando un carro que viene de frente esté a menos de 1,000 pies, y cuando usted esté a menos de 500 pies detrás de otro carro.","p":"Correcto. Baje las luces a menos de 1,000 pies de un carro que viene de frente."},"zh":{"q":"在 Montana，迎面来车时，你什么时候必须把远光灯（high beams）调暗？","o":["在 200 英尺以内时","在 500 英尺以内时","在 1,000 英尺以内时","在 1 英里以内时"],"h1":"Montana 的距离比很多州都长。","h2":"在 Montana，迎面来车在 1,000 英尺以内时，以及你在另一辆车后面 500 英尺以内时，你必须把远光灯调暗。","p":"对。迎面来车在 1,000 英尺以内时要调暗。"},"vi":{"q":"Ở Montana, khi có xe chạy ngược chiều tới, lúc nào bạn phải giảm đèn chiếu xa (high beams)?","o":["Khi xe đó ở trong vòng 200 feet","Khi xe đó ở trong vòng 500 feet","Khi xe đó ở trong vòng 1,000 feet","Khi xe đó ở trong vòng 1 dặm"],"h1":"Khoảng cách của Montana dài hơn ở nhiều tiểu bang.","h2":"Ở Montana, bạn phải giảm đèn chiếu xa khi xe ngược chiều ở trong vòng 1,000 feet, và khi bạn ở trong vòng 500 feet phía sau một xe khác.","p":"Đúng. Giảm đèn khi xe ngược chiều ở trong vòng 1,000 feet."},"tl":{"q":"Sa Montana, kailan mo dapat i-dim ang high beams mo para sa sasakyang paparating sa iyo?","o":["Kapag nasa loob ito ng 200 talampakan","Kapag nasa loob ito ng 500 talampakan","Kapag nasa loob ito ng 1,000 talampakan","Kapag nasa loob ito ng 1 milya"],"h1":"Mas mahaba ang layo sa Montana kaysa sa maraming estado.","h2":"Sa Montana, dapat mong i-dim ang high beams mo kapag ang paparating na sasakyan ay nasa loob ng 1,000 talampakan, at kapag ikaw ay nasa loob ng 500 talampakan sa likod ng ibang sasakyan.","p":"Tama. I-dim sa loob ng 1,000 talampakan ng paparating na sasakyan."},"ar":{"q":"في Montana، متى يجب أن تخفض الأضواء العالية (high beams) لسيارة قادمة نحوك؟","o":["عندما تكون ضمن 200 قدم","عندما تكون ضمن 500 قدم","عندما تكون ضمن 1,000 قدم","عندما تكون ضمن 1 ميل"],"h1":"المسافة في Montana أطول منها في كثير من الولايات.","h2":"في Montana يجب أن تخفض الأضواء العالية عندما تكون السيارة القادمة ضمن 1,000 قدم، وعندما تكون أنت ضمن 500 قدم خلف سيارة أخرى.","p":"صحيح. اخفض الأضواء ضمن 1,000 قدم من السيارة القادمة."},"ref":{"doc":"MT","page":14}},{"id":"mt-029","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what is the fine for a first conviction of driving without liability insurance?","o":["$25 to $50","$100 to $150","$1,000 to $2,000","$250 to $500"],"h1":"It is a few hundred dollars.","h2":"In Montana a first conviction for driving without liability insurance brings a fine of $250 to $500.","p":"Right. The fine is $250 to $500."},"es":{"q":"En Montana, ¿cuál es la multa por una primera condena por manejar sin seguro de responsabilidad civil?","o":["De $25 a $50","De $100 a $150","De $1,000 a $2,000","De $250 a $500"],"h1":"Son unos cientos de dólares.","h2":"En Montana una primera condena por manejar sin seguro de responsabilidad civil trae una multa de $250 a $500.","p":"Correcto. La multa es de $250 a $500."},"zh":{"q":"在 Montana，第一次因为没有责任保险（liability insurance）开车被定罪，罚款是多少？","o":["$25 到 $50","$100 到 $150","$1,000 到 $2,000","$250 到 $500"],"h1":"是几百美元。","h2":"在 Montana，第一次因为没有责任保险开车被定罪，罚款是 $250 到 $500。","p":"对。罚款是 $250 到 $500。"},"vi":{"q":"Ở Montana, tiền phạt cho lần bị kết tội đầu tiên vì lái xe không có bảo hiểm trách nhiệm (liability insurance) là bao nhiêu?","o":["$25 đến $50","$100 đến $150","$1,000 đến $2,000","$250 đến $500"],"h1":"Đó là vài trăm đô la.","h2":"Ở Montana, lần bị kết tội đầu tiên vì lái xe không có bảo hiểm trách nhiệm bị phạt từ $250 đến $500.","p":"Đúng. Tiền phạt là $250 đến $500."},"tl":{"q":"Sa Montana, magkano ang multa sa unang conviction dahil sa pagmamaneho nang walang liability insurance?","o":["$25 hanggang $50","$100 hanggang $150","$1,000 hanggang $2,000","$250 hanggang $500"],"h1":"Ilang daang dolyar ito.","h2":"Sa Montana, ang unang conviction dahil sa pagmamaneho nang walang liability insurance ay may multang $250 hanggang $500.","p":"Tama. Ang multa ay $250 hanggang $500."},"ar":{"q":"في Montana، ما الغرامة على أول إدانة بالقيادة دون تأمين المسؤولية (liability insurance)؟","o":["من $25 إلى $50","من $100 إلى $150","من $1,000 إلى $2,000","من $250 إلى $500"],"h1":"إنها بضع مئات من الدولارات.","h2":"في Montana تكون الغرامة على أول إدانة بالقيادة دون تأمين المسؤولية من $250 إلى $500.","p":"صحيح. الغرامة من $250 إلى $500."},"ref":{"doc":"MT","page":47}},{"id":"mt-030","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 5 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is about the length of one car.","h2":"In Montana you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Montana, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es como el largo de un carro.","h2":"En Montana usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Montana，你可以在离消防栓多近的地方停车？","o":["不能少于 10 英尺","不能少于 5 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"大约是一辆车的长度。","h2":"在 Montana，你不可以在消防栓 15 英尺以内停车。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở Montana, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe.","h2":"Ở Montana, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước chữa cháy.","p":"Đúng. Cách trụ nước chữa cháy ít nhất 15 feet."},"tl":{"q":"Sa Montana, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 5 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 30 talampakan"],"h1":"Halos kasinghaba ito ng isang kotse.","h2":"Sa Montana, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa hydrant."},"ar":{"q":"في Montana، ما أقرب مسافة من صنبور إطفاء الحريق يمكنك أن تركن عندها؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"إنها تقريبًا طول سيارة واحدة.","h2":"في Montana لا يجوز أن تركن ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 15 قدمًا على الأقل عن صنبور الإطفاء."},"ref":{"doc":"MT","page":46}},{"id":"mt-031","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, when a written crash report is required, how soon must it be filed?","o":["Within 24 hours","Within 10 days","Within 30 days","Within 6 months"],"h1":"It is less than two weeks.","h2":"In Montana a required written crash report must be filed within 10 days of the crash.","p":"Right. File it within 10 days."},"es":{"q":"En Montana, cuando se requiere un informe escrito de un choque, ¿en qué plazo se debe presentar?","o":["Dentro de 24 horas","Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses"],"h1":"Es menos de dos semanas.","h2":"En Montana un informe escrito de choque que sea obligatorio se debe presentar dentro de los 10 días después del choque.","p":"Correcto. Preséntelo dentro de 10 días."},"zh":{"q":"在 Montana，如果需要书面车祸报告，必须在多久之内提交？","o":["24 小时之内","10 天之内","30 天之内","6 个月之内"],"h1":"不到两个星期。","h2":"在 Montana，需要的书面车祸报告必须在车祸后 10 天之内提交。","p":"对。在 10 天之内提交。"},"vi":{"q":"Ở Montana, khi cần có báo cáo tai nạn bằng văn bản, phải nộp báo cáo trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 6 tháng"],"h1":"Ít hơn hai tuần.","h2":"Ở Montana, báo cáo tai nạn bằng văn bản bắt buộc phải được nộp trong vòng 10 ngày sau tai nạn.","p":"Đúng. Nộp trong vòng 10 ngày."},"tl":{"q":"Sa Montana, kapag kailangan ang nakasulat na ulat ng banggaan, gaano kabilis ito dapat isumite?","o":["Sa loob ng 24 na oras","Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 6 na buwan"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sa Montana, ang kinakailangang nakasulat na ulat ng banggaan ay dapat isumite sa loob ng 10 araw mula sa banggaan.","p":"Tama. Isumite ito sa loob ng 10 araw."},"ar":{"q":"في Montana، عندما يكون تقرير الحادث المكتوب مطلوبًا، خلال كم من الوقت يجب تقديمه؟","o":["خلال 24 ساعة","خلال 10 أيام","خلال 30 يومًا","خلال 6 أشهر"],"h1":"إنها أقل من أسبوعين.","h2":"في Montana يجب تقديم تقرير الحادث المكتوب المطلوب خلال 10 أيام من وقوع الحادث.","p":"صحيح. قدّمه خلال 10 أيام."},"ref":{"doc":"MT","page":80}},{"id":"mt-032","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, you move to a new address. How soon must you tell the Motor Vehicle Division?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"Montana law says you must report your new address to the Motor Vehicle Division within 10 days of moving.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Montana, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar a la División de Vehículos Motorizados?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"La ley de Montana dice que usted debe informar su nueva dirección a la División de Vehículos Motorizados dentro de los 10 días después de mudarse.","p":"Correcto. Informe su nueva dirección en 10 días."},"zh":{"q":"在 Montana，你搬到了新地址。你必须在多久之内通知机动车管理处（Motor Vehicle Division）？","o":["10 天之内","30 天之内","60 天之内","下次换证的时候"],"h1":"不到两个星期。","h2":"Montana 法律规定，搬家后你必须在 10 天之内把新地址报告给机动车管理处（Motor Vehicle Division）。","p":"对。在 10 天之内报告新地址。"},"vi":{"q":"Ở Montana, bạn chuyển đến địa chỉ mới. Bạn phải báo cho Motor Vehicle Division (Sở Xe Cơ Giới) trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Vào lần gia hạn bằng lái tới"],"h1":"Ít hơn hai tuần.","h2":"Luật Montana nói rằng bạn phải báo địa chỉ mới cho Motor Vehicle Division trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Montana, lumipat ka sa bagong address. Gaano kabilis mo dapat sabihan ang Motor Vehicle Division?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa susunod mong pag-renew"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sinasabi ng batas ng Montana na dapat mong iulat ang bago mong address sa Motor Vehicle Division sa loob ng 10 araw mula sa paglipat.","p":"Tama. Iulat ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Montana، انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تُبلغ قسم المركبات (Motor Vehicle Division)؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عند تجديد رخصتك القادم"],"h1":"إنها أقل من أسبوعين.","h2":"ينص قانون Montana على أنه يجب أن تُبلغ قسم المركبات (Motor Vehicle Division) بعنوانك الجديد خلال 10 أيام من انتقالك.","p":"صحيح. أبلغ عن عنوانك الجديد خلال 10 أيام."},"ref":{"doc":"MT","page":10}},{"id":"mt-033","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how early can you renew your driver license before it expires?","o":["Up to 1 month before","Up to 3 months before","Up to 6 months before","Up to 1 year before"],"h1":"Think of half a year.","h2":"In Montana you may renew your driver license up to 6 months before the date it expires.","p":"Right. You can renew up to 6 months early."},"es":{"q":"En Montana, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 1 mes antes","Hasta 3 meses antes","Hasta 6 meses antes","Hasta 1 año antes"],"h1":"Piense en medio año.","h2":"En Montana usted puede renovar su licencia de conducir hasta 6 meses antes de la fecha en que vence.","p":"Correcto. Puede renovarla hasta 6 meses antes."},"zh":{"q":"在 Montana，驾照到期前最早可以提前多久换证？","o":["最多提前 1 个月","最多提前 3 个月","最多提前 6 个月","最多提前 1 年"],"h1":"想想半年。","h2":"在 Montana，你最多可以在驾照到期日前 6 个月换证。","p":"对。你最多可以提前 6 个月换证。"},"vi":{"q":"Ở Montana, bạn có thể gia hạn bằng lái sớm nhất là bao lâu trước khi hết hạn?","o":["Tối đa 1 tháng trước","Tối đa 3 tháng trước","Tối đa 6 tháng trước","Tối đa 1 năm trước"],"h1":"Hãy nghĩ đến nửa năm.","h2":"Ở Montana, bạn có thể gia hạn bằng lái tối đa 6 tháng trước ngày hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 6 tháng."},"tl":{"q":"Sa Montana, gaano kaaga mo maaaring i-renew ang iyong driver license bago ito mag-expire?","o":["Hanggang 1 buwan bago","Hanggang 3 buwan bago","Hanggang 6 na buwan bago","Hanggang 1 taon bago"],"h1":"Isipin ang kalahating taon.","h2":"Sa Montana, maaari mong i-renew ang iyong driver license hanggang 6 na buwan bago ang petsa ng pag-expire nito.","p":"Tama. Maaari kang mag-renew hanggang 6 na buwan nang maaga."},"ar":{"q":"في Montana، كم من الوقت قبل انتهاء رخصة القيادة يمكنك تجديدها؟","o":["حتى شهر واحد قبلها","حتى 3 أشهر قبلها","حتى 6 أشهر قبلها","حتى سنة واحدة قبلها"],"h1":"فكّر في نصف سنة.","h2":"في Montana يمكنك تجديد رخصة القيادة قبل تاريخ انتهائها بمدة تصل إلى 6 أشهر.","p":"صحيح. يمكنك التجديد مبكرًا حتى 6 أشهر."},"ref":{"doc":"MT","page":9}},{"id":"mt-034","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, a driver license is issued to a person age 75 or older. For how long is it valid at most?","o":["2 years","4 years","8 years","12 years"],"h1":"Older drivers renew more often than younger adults.","h2":"In Montana, a license issued to someone age 75 or older expires on their birthday 4 years or less after it is issued.","p":"Right. At 75 or older, a license lasts up to 4 years."},"es":{"q":"En Montana, se emite una licencia de conducir a una persona de 75 años o más. ¿Por cuánto tiempo es válida como máximo?","o":["2 años","4 años","8 años","12 años"],"h1":"Los conductores mayores renuevan más seguido que los adultos más jóvenes.","h2":"En Montana, una licencia emitida a una persona de 75 años o más vence en su cumpleaños 4 años o menos después de emitirse.","p":"Correcto. A los 75 años o más, la licencia dura hasta 4 años."},"zh":{"q":"在 Montana，给 75 岁或以上的人发的驾照，最长有效多久？","o":["2 年","4 年","8 年","12 年"],"h1":"年长的司机比年轻的成年人更常换证。","h2":"在 Montana，发给 75 岁或以上的人的驾照，在发证后 4 年或更短时间内的生日那天到期。","p":"对。75 岁或以上，驾照最长有效 4 年。"},"vi":{"q":"Ở Montana, bằng lái cấp cho người 75 tuổi trở lên có giá trị tối đa bao lâu?","o":["2 năm","4 năm","8 năm","12 năm"],"h1":"Người lái xe lớn tuổi gia hạn thường xuyên hơn người trẻ.","h2":"Ở Montana, bằng lái cấp cho người 75 tuổi trở lên hết hạn vào ngày sinh nhật của họ trong vòng 4 năm hoặc ít hơn sau khi cấp.","p":"Đúng. Từ 75 tuổi trở lên, bằng lái có giá trị tối đa 4 năm."},"tl":{"q":"Sa Montana, may driver license na ibinigay sa taong edad 75 o higit pa. Hanggang gaano katagal ito balido?","o":["2 taon","4 na taon","8 taon","12 taon"],"h1":"Mas madalas mag-renew ang matatandang drayber kaysa sa mas batang adulto.","h2":"Sa Montana, ang license na ibinigay sa taong edad 75 o higit pa ay mag-e-expire sa kanyang kaarawan 4 na taon o mas maikli mula nang ibigay ito.","p":"Tama. Sa edad 75 o higit pa, ang license ay tumatagal nang hanggang 4 na taon."},"ar":{"q":"في Montana، صدرت رخصة قيادة لشخص عمره 75 عامًا أو أكثر. ما أقصى مدة تبقى فيها صالحة؟","o":["سنتان","4 سنوات","8 سنوات","12 سنة"],"h1":"السائقون الأكبر سنًا يجددون أكثر من البالغين الأصغر سنًا.","h2":"في Montana، الرخصة التي تصدر لشخص عمره 75 عامًا أو أكثر تنتهي في يوم ميلاده بعد 4 سنوات أو أقل من صدورها.","p":"صحيح. في سن 75 أو أكثر، تبقى الرخصة صالحة حتى 4 سنوات."},"ref":{"doc":"MT","page":8}},{"id":"mt-035","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a teen breaks a rule of the first-year restricted license for the first time. What is the penalty?","o":["A warning letter only","A $500 fine","Loss of the license for one year","20 to 60 hours of community service"],"h1":"The teen has to give some time to help others.","h2":"In Montana, a first violation of the first-year license rules brings 20 to 60 hours of community service; a second one brings a 6-month suspension.","p":"Right. The first time, it is 20 to 60 hours of community service."},"es":{"q":"En Montana, un adolescente rompe por primera vez una regla de la licencia restringida del primer año. ¿Cuál es la sanción?","o":["Solo una carta de advertencia","Una multa de $500","La pérdida de la licencia por un año","De 20 a 60 horas de servicio comunitario"],"h1":"El adolescente debe dar parte de su tiempo para ayudar a otros.","h2":"En Montana, la primera infracción de las reglas de la licencia del primer año trae de 20 a 60 horas de servicio comunitario; la segunda trae una suspensión de 6 meses.","p":"Correcto. La primera vez son de 20 a 60 horas de servicio comunitario."},"zh":{"q":"在 Montana，一个青少年第一次违反第一年限制驾照的规定。处罚是什么？","o":["只有一封警告信","罚款 $500","吊销驾照一年","20 到 60 小时的社区服务"],"h1":"这个青少年要花一些时间帮助别人。","h2":"在 Montana，第一次违反第一年驾照规定要做 20 到 60 小时的社区服务；第二次会被暂停驾照 6 个月。","p":"对。第一次违规要做 20 到 60 小时的社区服务。"},"vi":{"q":"Ở Montana, một thiếu niên vi phạm quy định của bằng lái hạn chế năm đầu lần thứ nhất. Hình phạt là gì?","o":["Chỉ một thư cảnh cáo","Phạt $500","Mất bằng lái một năm","20 đến 60 giờ phục vụ cộng đồng"],"h1":"Thiếu niên phải dành thời gian giúp đỡ người khác.","h2":"Ở Montana, vi phạm lần đầu quy định của bằng lái năm đầu bị phạt 20 đến 60 giờ phục vụ cộng đồng; lần thứ hai bị treo bằng 6 tháng.","p":"Đúng. Lần đầu là 20 đến 60 giờ phục vụ cộng đồng."},"tl":{"q":"Sa Montana, unang beses lumabag ang isang teen sa patakaran ng restricted license sa unang taon. Ano ang parusa?","o":["Isang sulat ng babala lamang","Multang $500","Pagkawala ng license nang isang taon","20 hanggang 60 oras ng community service"],"h1":"Kailangang maglaan ng oras ang teen para tumulong sa iba.","h2":"Sa Montana, ang unang paglabag sa mga patakaran ng license sa unang taon ay may parusang 20 hanggang 60 oras ng community service; ang pangalawa ay 6 na buwang suspensyon.","p":"Tama. Sa unang beses, 20 hanggang 60 oras ng community service."},"ar":{"q":"في Montana، خالف مراهق قاعدة من قواعد الرخصة المقيدة للسنة الأولى لأول مرة. ما العقوبة؟","o":["رسالة تحذير فقط","غرامة $500","سحب الرخصة لمدة سنة","من 20 إلى 60 ساعة من خدمة المجتمع"],"h1":"على المراهق أن يقضي بعض الوقت في مساعدة الآخرين.","h2":"في Montana، المخالفة الأولى لقواعد رخصة السنة الأولى عقوبتها من 20 إلى 60 ساعة من خدمة المجتمع، والمخالفة الثانية عقوبتها إيقاف الرخصة 6 أشهر.","p":"صحيح. في المرة الأولى تكون العقوبة من 20 إلى 60 ساعة من خدمة المجتمع."},"ref":{"doc":"MT","page":8}},{"id":"mt-036","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, a passenger in your car is not wearing a seat belt. What is the fine for the driver?","o":["$20","$50","$100","$250"],"h1":"It is a small amount.","h2":"In Montana the driver is responsible for every rider being buckled, and the fine for breaking the seat belt law is $20.","p":"Right. The seat belt fine is $20, and the driver pays it."},"es":{"q":"En Montana, un pasajero de su auto no lleva puesto el cinturón de seguridad. ¿Cuál es la multa para el conductor?","o":["$20","$50","$100","$250"],"h1":"Es una cantidad pequeña.","h2":"En Montana el conductor es responsable de que todos lleven el cinturón abrochado, y la multa por no cumplir la ley del cinturón es de $20.","p":"Correcto. La multa del cinturón es de $20 y la paga el conductor."},"zh":{"q":"在 Montana，你车上的一名乘客没有系安全带。司机会被罚多少钱？","o":["$20","$50","$100","$250"],"h1":"金额很小。","h2":"在 Montana，司机要负责让车上每个人都系好安全带，违反安全带法的罚款是 $20。","p":"对。安全带罚款是 $20，由司机来付。"},"vi":{"q":"Ở Montana, một hành khách trong xe bạn không thắt dây an toàn. Tài xế bị phạt bao nhiêu?","o":["$20","$50","$100","$250"],"h1":"Đó là một số tiền nhỏ.","h2":"Ở Montana, tài xế chịu trách nhiệm để mọi người trong xe đều thắt dây an toàn, và tiền phạt khi vi phạm luật dây an toàn là $20.","p":"Đúng. Tiền phạt dây an toàn là $20, và tài xế phải trả."},"tl":{"q":"Sa Montana, hindi nakasuot ng seat belt ang isang pasahero sa kotse mo. Magkano ang multa ng drayber?","o":["$20","$50","$100","$250"],"h1":"Maliit na halaga ito.","h2":"Sa Montana, pananagutan ng drayber na nakasuot ng seat belt ang bawat sakay, at ang multa sa paglabag sa batas sa seat belt ay $20.","p":"Tama. Ang multa sa seat belt ay $20, at ang drayber ang nagbabayad."},"ar":{"q":"في Montana، أحد الركاب في سيارتك لا يربط حزام الأمان. ما الغرامة على السائق؟","o":["$20","$50","$100","$250"],"h1":"إنه مبلغ صغير.","h2":"في Montana السائق مسؤول عن ربط حزام الأمان لكل راكب، وغرامة مخالفة قانون حزام الأمان هي $20.","p":"صحيح. غرامة حزام الأمان هي $20، والسائق هو من يدفعها."},"ref":{"doc":"MT","page":19}},{"id":"mt-037","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, how must a child under 2 years old ride in a car?","o":["In a forward-facing booster seat","With an adult seat belt in the back seat","In a rear-facing child safety seat","On an adult's lap with a belt"],"h1":"The baby faces the back of the car.","h2":"Montana law says a child under 2 years old must ride in a rear-facing child safety seat that meets federal standards.","p":"Right. Under age 2, a child rides in a rear-facing seat."},"es":{"q":"En Montana, ¿cómo debe viajar en un auto un niño menor de 2 años?","o":["En un asiento elevado mirando hacia adelante","Con un cinturón de adulto en el asiento trasero","En un asiento de seguridad infantil mirando hacia atrás","En las piernas de un adulto con cinturón"],"h1":"El bebé mira hacia la parte de atrás del auto.","h2":"La ley de Montana dice que un niño menor de 2 años debe viajar en un asiento de seguridad infantil mirando hacia atrás que cumpla las normas federales.","p":"Correcto. Antes de los 2 años, el niño viaja en un asiento mirando hacia atrás."},"zh":{"q":"在 Montana，2 岁以下的孩子坐车时必须怎么坐？","o":["坐在面朝前的增高座椅上","在后座系成人安全带","坐在面朝后的儿童安全座椅上","坐在大人腿上并系安全带"],"h1":"宝宝面朝车的后方。","h2":"Montana 法律规定，2 岁以下的孩子必须坐在符合联邦标准的面朝后的儿童安全座椅上。","p":"对。2 岁以下的孩子坐面朝后的座椅。"},"vi":{"q":"Ở Montana, trẻ dưới 2 tuổi phải ngồi trong xe như thế nào?","o":["Trên ghế nâng quay mặt về phía trước","Thắt dây an toàn người lớn ở ghế sau","Trong ghế an toàn trẻ em quay mặt về phía sau","Ngồi trên đùi người lớn có thắt dây"],"h1":"Em bé quay mặt về phía sau xe.","h2":"Luật Montana nói rằng trẻ dưới 2 tuổi phải ngồi trong ghế an toàn trẻ em quay mặt về phía sau, đạt tiêu chuẩn liên bang.","p":"Đúng. Dưới 2 tuổi, trẻ ngồi ghế quay mặt về phía sau."},"tl":{"q":"Sa Montana, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang?","o":["Sa booster seat na nakaharap sa unahan","Na may seat belt ng adulto sa likurang upuan","Sa child safety seat na nakaharap sa likod","Sa kandungan ng adulto na may belt"],"h1":"Nakaharap ang sanggol sa likod ng kotse.","h2":"Sinasabi ng batas ng Montana na ang batang wala pang 2 taong gulang ay dapat sumakay sa child safety seat na nakaharap sa likod at pasado sa pederal na pamantayan.","p":"Tama. Kapag wala pang 2 taon, sa upuang nakaharap sa likod sumasakay ang bata."},"ar":{"q":"في Montana، كيف يجب أن يركب الطفل الذي عمره أقل من سنتين في السيارة؟","o":["في مقعد رافع يواجه الأمام","بحزام أمان الكبار في المقعد الخلفي","في مقعد أمان للأطفال يواجه الخلف","في حضن شخص كبير مع حزام"],"h1":"الطفل الرضيع يواجه مؤخرة السيارة.","h2":"ينص قانون Montana على أن الطفل الذي عمره أقل من سنتين يجب أن يركب في مقعد أمان للأطفال يواجه الخلف ويطابق المعايير الفيدرالية.","p":"صحيح. الطفل الأقل من سنتين يركب في مقعد يواجه الخلف."},"ref":{"doc":"MT","page":null}},{"id":"mt-038","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, it is daytime, but snow or blowing dust makes it hard to see. When must your headlights be on?","o":["When you cannot see 1,000 feet ahead","When you cannot clearly see people and cars 500 feet ahead","When you cannot see 200 feet ahead","Only after sunset"],"h1":"It is a bit less than two city blocks.","h2":"Montana law says to use headlights at night and any time you cannot clearly see people and vehicles 500 feet ahead.","p":"Right. If you cannot see 500 feet ahead, turn on your headlights."},"es":{"q":"En Montana, es de día, pero la nieve o el polvo hacen difícil ver. ¿Cuándo debe tener encendidos los faros?","o":["Cuando no pueda ver 1,000 pies adelante","Cuando no pueda ver bien a personas y autos a 500 pies adelante","Cuando no pueda ver 200 pies adelante","Solo después de la puesta del sol"],"h1":"La distancia es de menos de dos cuadras de ciudad.","h2":"La ley de Montana dice que use los faros de noche y en cualquier momento en que no pueda ver bien a personas y vehículos a 500 pies adelante.","p":"Correcto. Si no puede ver a 500 pies, encienda los faros."},"zh":{"q":"在 Montana，现在是白天，但雪或扬尘让人很难看清。你什么时候必须打开大灯？","o":["看不清前方 1,000 英尺的时候","看不清前方 500 英尺的人和车的时候","看不清前方 200 英尺的时候","只在日落以后"],"h1":"比两个城市街区短一点。","h2":"Montana 法律规定，夜间以及任何看不清前方 500 英尺的人和车辆的时候，都要打开大灯。","p":"对。如果看不清前方 500 英尺，就打开大灯。"},"vi":{"q":"Ở Montana, đang là ban ngày nhưng tuyết hoặc bụi bay làm khó nhìn. Khi nào bạn phải bật đèn pha?","o":["Khi bạn không nhìn thấy 1,000 feet phía trước","Khi bạn không nhìn rõ người và xe ở 500 feet phía trước","Khi bạn không nhìn thấy 200 feet phía trước","Chỉ sau khi mặt trời lặn"],"h1":"Ít hơn một chút so với hai dãy phố.","h2":"Luật Montana nói rằng phải bật đèn pha vào ban đêm và bất cứ khi nào bạn không nhìn rõ người và xe ở 500 feet phía trước.","p":"Đúng. Nếu bạn không nhìn thấy 500 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Montana, araw pa, pero mahirap makakita dahil sa niyebe o liparing alikabok. Kailan mo dapat buksan ang headlights?","o":["Kapag hindi mo makita ang 1,000 feet sa unahan","Kapag hindi mo malinaw na makita ang mga tao at sasakyan 500 feet sa unahan","Kapag hindi mo makita ang 200 feet sa unahan","Pagkalubog lamang ng araw"],"h1":"Medyo kulang ito sa dalawang city block.","h2":"Sinasabi ng batas ng Montana na gumamit ng headlights sa gabi at tuwing hindi mo malinaw na makita ang mga tao at sasakyan 500 feet sa unahan.","p":"Tama. Kapag hindi mo makita ang 500 feet sa unahan, buksan ang headlights."},"ar":{"q":"في Montana، الوقت نهار، لكن الثلج أو الغبار المتطاير يجعل الرؤية صعبة. متى يجب أن تُشعل الأضواء الأمامية؟","o":["عندما لا ترى مسافة 1,000 feet أمامك","عندما لا ترى الناس والسيارات بوضوح على بُعد 500 feet أمامك","عندما لا ترى مسافة 200 feet أمامك","بعد غروب الشمس فقط"],"h1":"إنها أقل قليلًا من طول شارعين في المدينة.","h2":"ينص قانون Montana على استخدام الأضواء الأمامية في الليل وفي أي وقت لا ترى فيه الناس والمركبات بوضوح على بُعد 500 feet أمامك.","p":"صحيح. إذا لم ترَ مسافة 500 feet أمامك، أشعل الأضواء الأمامية."},"ref":{"doc":"MT","page":14}},{"id":"mt-039","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, you plan to turn on a rural road outside town. How far before the turn must you signal?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 300 feet"],"h1":"It is three times the distance used in town.","h2":"In Montana you must signal at least 100 feet before a turn in town and at least 300 feet before a turn on rural roads.","p":"Right. On rural roads, signal at least 300 feet before you turn."},"es":{"q":"En Montana, usted va a girar en una carretera rural fuera del pueblo. ¿Con cuánta anticipación debe poner la señal?","o":["Al menos 50 pies antes","Al menos 100 pies antes","Al menos 200 pies antes","Al menos 300 pies antes"],"h1":"Es tres veces la distancia que se usa en el pueblo.","h2":"En Montana debe poner la señal al menos 100 pies antes de girar en el pueblo y al menos 300 pies antes de girar en carreteras rurales.","p":"Correcto. En carreteras rurales, ponga la señal al menos 300 pies antes de girar."},"zh":{"q":"在 Montana，你打算在城外的乡村道路上转弯。你必须在转弯前多远打信号灯？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 300 英尺"],"h1":"是城里距离的三倍。","h2":"在 Montana，你必须在城里转弯前至少 100 英尺打信号灯，在乡村道路上转弯前至少 300 英尺打信号灯。","p":"对。在乡村道路上，转弯前至少 300 英尺打信号灯。"},"vi":{"q":"Ở Montana, bạn định rẽ trên một con đường nông thôn ngoài thị trấn. Bạn phải bật đèn báo rẽ cách chỗ rẽ bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 300 feet"],"h1":"Gấp ba lần khoảng cách dùng trong thị trấn.","h2":"Ở Montana, bạn phải bật đèn báo rẽ ít nhất 100 feet trước khi rẽ trong thị trấn và ít nhất 300 feet trước khi rẽ trên đường nông thôn.","p":"Đúng. Trên đường nông thôn, bật đèn báo ít nhất 300 feet trước khi rẽ."},"tl":{"q":"Sa Montana, liliko ka sa isang daan sa probinsya sa labas ng bayan. Gaano kalayo bago lumiko ka dapat mag-signal?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 300 feet"],"h1":"Tatlong beses ito ng layong ginagamit sa bayan.","h2":"Sa Montana, dapat kang mag-signal nang hindi bababa sa 100 feet bago lumiko sa bayan at hindi bababa sa 300 feet bago lumiko sa mga daan sa probinsya.","p":"Tama. Sa mga daan sa probinsya, mag-signal nang hindi bababa sa 300 feet bago lumiko."},"ar":{"q":"في Montana، تنوي الانعطاف على طريق ريفي خارج المدينة. على أي مسافة قبل المنعطف يجب أن تشغّل الإشارة؟","o":["50 feet على الأقل","100 feet على الأقل","200 feet على الأقل","300 feet على الأقل"],"h1":"إنها ثلاثة أضعاف المسافة المستخدمة داخل المدينة.","h2":"في Montana يجب أن تشغّل الإشارة قبل 100 feet على الأقل من المنعطف داخل المدينة، وقبل 300 feet على الأقل من المنعطف على الطرق الريفية.","p":"صحيح. على الطرق الريفية، شغّل الإشارة قبل 300 feet على الأقل من المنعطف."},"ref":{"doc":"MT","page":37}},{"id":"mt-040","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the edge of the first rail","At least 5 feet from the nearest rail","At least 15 feet from the nearest rail","Only if you can see the train"],"h1":"Leave room in case the train or its load sticks out.","h2":"In Montana, when signals warn of a train, you must stop at least 15 feet from the nearest rail and wait until it is safe.","p":"Right. Stop at least 15 feet from the nearest rail."},"es":{"q":"En Montana, las luces destellan en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["Justo al borde del primer riel","Al menos a 5 pies del riel más cercano","Al menos a 15 pies del riel más cercano","Solo si puede ver el tren"],"h1":"Deje espacio por si el tren o su carga sobresale.","h2":"En Montana, cuando las señales avisan de un tren, debe detenerse al menos a 15 pies del riel más cercano y esperar hasta que sea seguro.","p":"Correcto. Deténgase al menos a 15 pies del riel más cercano."},"zh":{"q":"在 Montana，铁路道口的灯在闪烁。你必须在哪里停车？","o":["就停在第一根铁轨边上","离最近的铁轨至少 5 英尺","离最近的铁轨至少 15 英尺","只有看到火车时才停"],"h1":"留出空间，以防火车或车上的货物伸出来。","h2":"在 Montana，当信号警告有火车时，你必须在离最近的铁轨至少 15 英尺的地方停车，等到安全再走。","p":"对。在离最近的铁轨至少 15 英尺的地方停车。"},"vi":{"q":"Ở Montana, đèn đang nhấp nháy ở chỗ băng qua đường ray. Bạn phải dừng ở đâu?","o":["Ngay sát mép đường ray đầu tiên","Cách đường ray gần nhất ít nhất 5 feet","Cách đường ray gần nhất ít nhất 15 feet","Chỉ khi bạn nhìn thấy tàu"],"h1":"Chừa khoảng trống phòng khi tàu hoặc hàng trên tàu nhô ra.","h2":"Ở Montana, khi có tín hiệu báo tàu đến, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet và chờ đến khi an toàn.","p":"Đúng. Dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Montana, kumikislap ang mga ilaw sa tawiran ng riles. Saan ka dapat huminto?","o":["Mismo sa gilid ng unang riles","Hindi bababa sa 5 feet mula sa pinakamalapit na riles","Hindi bababa sa 15 feet mula sa pinakamalapit na riles","Kung nakikita mo lamang ang tren"],"h1":"Mag-iwan ng puwang kung sakaling may nakausling bahagi ang tren o ang karga nito.","h2":"Sa Montana, kapag may babala ng tren ang mga signal, dapat kang huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles at maghintay hanggang ligtas na.","p":"Tama. Huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Montana، الأضواء تومض عند معبر سكة حديد. أين يجب أن تتوقف؟","o":["على حافة السكة الأولى مباشرة","على بُعد 5 feet على الأقل من أقرب سكة","على بُعد 15 feet على الأقل من أقرب سكة","فقط إذا رأيت القطار"],"h1":"اترك مسافة في حال كان القطار أو حمولته بارزًا.","h2":"في Montana، عندما تحذّر الإشارات من قطار، يجب أن تتوقف على بُعد 15 feet على الأقل من أقرب سكة وتنتظر حتى يصبح العبور آمنًا.","p":"صحيح. توقف على بُعد 15 feet على الأقل من أقرب سكة."},"ref":{"doc":"MT","page":33}},{"id":"mt-041","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you get a traffic ticket in a work zone while highway workers are there. What happens to the fine?","o":["It is doubled","It stays the same","It is cut in half","It becomes a warning"],"h1":"Work zones protect people working near traffic.","h2":"In Montana, traffic fines in a work zone are doubled when highway workers are present.","p":"Right. Fines double in work zones when workers are present."},"es":{"q":"En Montana, a usted le ponen una multa de tránsito en una zona de obras mientras hay trabajadores de carreteras. ¿Qué pasa con la multa?","o":["Se duplica","Sigue igual","Se reduce a la mitad","Se convierte en una advertencia"],"h1":"Las zonas de obras protegen a personas que trabajan cerca del tráfico.","h2":"En Montana, las multas de tránsito en una zona de obras se duplican cuando hay trabajadores de carreteras presentes.","p":"Correcto. Las multas se duplican en zonas de obras con trabajadores."},"zh":{"q":"在 Montana，你在有公路工人在场的施工区收到交通罚单。罚款会怎样？","o":["加倍","不变","减半","变成警告"],"h1":"施工区是为了保护在车流旁边工作的人。","h2":"在 Montana，有公路工人在场时，施工区内的交通罚款加倍。","p":"对。有工人在场时，施工区罚款加倍。"},"vi":{"q":"Ở Montana, bạn bị phạt giao thông trong khu vực thi công khi có công nhân làm đường ở đó. Tiền phạt sẽ ra sao?","o":["Tăng gấp đôi","Giữ nguyên","Giảm một nửa","Chỉ còn là cảnh cáo"],"h1":"Khu vực thi công bảo vệ những người làm việc gần dòng xe.","h2":"Ở Montana, tiền phạt giao thông trong khu vực thi công tăng gấp đôi khi có công nhân làm đường ở đó.","p":"Đúng. Tiền phạt tăng gấp đôi trong khu vực thi công khi có công nhân."},"tl":{"q":"Sa Montana, nakakuha ka ng traffic ticket sa work zone habang naroon ang mga manggagawa sa highway. Ano ang mangyayari sa multa?","o":["Dinodoble ito","Hindi ito nagbabago","Hinahati ito sa dalawa","Nagiging babala lamang ito"],"h1":"Pinoprotektahan ng work zone ang mga taong nagtatrabaho malapit sa trapiko.","h2":"Sa Montana, dinodoble ang mga multa sa trapiko sa work zone kapag naroon ang mga manggagawa sa highway.","p":"Tama. Dinodoble ang multa sa work zone kapag may mga manggagawa."},"ar":{"q":"في Montana، حصلت على مخالفة مرورية في منطقة أعمال طرق بينما كان عمال الطريق موجودين. ماذا يحدث للغرامة؟","o":["تتضاعف","تبقى كما هي","تنخفض إلى النصف","تصبح تحذيرًا"],"h1":"مناطق الأعمال تحمي الناس الذين يعملون قرب حركة السير.","h2":"في Montana، تتضاعف غرامات المرور في منطقة أعمال الطرق عندما يكون عمال الطريق موجودين.","p":"صحيح. تتضاعف الغرامات في مناطق الأعمال عندما يكون العمال موجودين."},"ref":{"doc":"MT","page":28}},{"id":"mt-042","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, a funeral procession is moving past you. You are not part of it. When may you drive between its cars?","o":["Whenever there is a gap","When your light turns green","When you are late","Only if a police officer tells you to"],"h1":"Let the procession stay together.","h2":"In Montana you may not drive between the cars of a moving funeral procession unless a police officer allows it or you drive an emergency vehicle.","p":"Right. Do not cut into a funeral procession unless an officer tells you to."},"es":{"q":"En Montana, un cortejo fúnebre pasa frente a usted. Usted no forma parte de él. ¿Cuándo puede pasar entre sus autos?","o":["Siempre que haya un espacio","Cuando su semáforo cambie a verde","Cuando vaya tarde","Solo si un policía se lo indica"],"h1":"Deje que el cortejo siga unido.","h2":"En Montana no puede pasar entre los autos de un cortejo fúnebre en movimiento, a menos que un policía lo permita o usted maneje un vehículo de emergencia.","p":"Correcto. No se meta en un cortejo fúnebre a menos que un policía se lo indique."},"zh":{"q":"在 Montana，一支送葬车队正从你旁边经过。你不是车队的一员。你什么时候可以开进车队的车辆之间？","o":["只要有空隙就可以","当你的灯变绿时","当你赶时间时","只有警察让你开时"],"h1":"让车队保持在一起。","h2":"在 Montana，除非警察允许或你开的是紧急车辆，否则你不可以开进正在行进的送葬车队的车辆之间。","p":"对。除非警察让你开，否则不要插进送葬车队。"},"vi":{"q":"Ở Montana, một đoàn xe tang đang đi qua bạn. Bạn không thuộc đoàn xe đó. Khi nào bạn được lái xe chen vào giữa các xe trong đoàn?","o":["Bất cứ khi nào có khoảng trống","Khi đèn của bạn chuyển xanh","Khi bạn bị trễ","Chỉ khi cảnh sát bảo bạn đi"],"h1":"Hãy để đoàn xe đi liền nhau.","h2":"Ở Montana, bạn không được lái xe chen vào giữa các xe của đoàn xe tang đang di chuyển, trừ khi cảnh sát cho phép hoặc bạn lái xe cấp cứu.","p":"Đúng. Không chen vào đoàn xe tang trừ khi cảnh sát bảo bạn đi."},"tl":{"q":"Sa Montana, dumaraan sa harap mo ang isang prusisyon ng libing. Hindi ka kasama rito. Kailan ka maaaring magmaneho sa pagitan ng mga sasakyan nito?","o":["Tuwing may puwang","Kapag naging berde ang ilaw mo","Kapag nahuhuli ka na","Kung sasabihin lamang ng pulis"],"h1":"Hayaang magkakasama ang prusisyon.","h2":"Sa Montana, hindi ka maaaring magmaneho sa pagitan ng mga sasakyan ng umaandar na prusisyon ng libing maliban kung payagan ka ng pulis o emergency vehicle ang minamaneho mo.","p":"Tama. Huwag sumingit sa prusisyon ng libing maliban kung sabihin ng pulis."},"ar":{"q":"في Montana، موكب جنازة يمر بجانبك. أنت لست جزءًا منه. متى يجوز لك أن تقود بين سياراته؟","o":["كلما وُجدت فجوة","عندما تصبح إشارتك خضراء","عندما تكون متأخرًا","فقط إذا طلب منك شرطي ذلك"],"h1":"دع الموكب يبقى متصلًا.","h2":"في Montana يجب ألّا تقود بين سيارات موكب جنازة متحرك، إلا إذا سمح لك شرطي بذلك أو كنت تقود مركبة طوارئ.","p":"صحيح. لا تدخل في موكب الجنازة إلا إذا طلب منك شرطي ذلك."},"ref":{"doc":"MT","page":42}},{"id":"mt-043","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, how close to a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Montana you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Montana, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 15 pies","No más cerca de 50 pies","No más cerca de 25 pies","No más cerca de 100 pies"],"h1":"Es más que la distancia para un hidrante.","h2":"En Montana no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Estaciónese al menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Montana，你可以在离铁路道口多近的地方停车？","o":["不得近于 15 英尺","不得近于 50 英尺","不得近于 25 英尺","不得近于 100 英尺"],"h1":"比离消防栓的距离更远。","h2":"在 Montana，你不可以在离铁路道口最近的铁轨 50 英尺之内停车。","p":"对。停车要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Montana, bạn được đậu xe gần chỗ băng qua đường ray đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 25 feet","Không gần hơn 100 feet"],"h1":"Xa hơn khoảng cách đối với trụ nước cứu hỏa.","h2":"Ở Montana, bạn không được đậu xe trong vòng 50 feet tính từ đường ray gần nhất của chỗ băng qua đường ray.","p":"Đúng. Đậu xe cách chỗ băng qua đường ray ít nhất 50 feet."},"tl":{"q":"Sa Montana, gaano kalapit sa tawiran ng riles ka maaaring pumarada?","o":["Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 100 feet"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa Montana, hindi ka maaaring pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng tawiran ng riles.","p":"Tama. Pumarada nang hindi bababa sa 50 feet mula sa tawiran ng riles."},"ar":{"q":"في Montana، كم يمكنك أن تقترب من معبر سكة حديد عندما تركن سيارتك؟","o":["ليس أقرب من 15 feet","ليس أقرب من 50 feet","ليس أقرب من 25 feet","ليس أقرب من 100 feet"],"h1":"إنها أكثر من المسافة المطلوبة عن حنفية الإطفاء.","h2":"في Montana يجب ألّا تركن سيارتك على بُعد أقل من 50 feet من أقرب سكة في معبر السكة الحديد.","p":"صحيح. اركن على بُعد 50 feet على الأقل من معبر السكة الحديد."},"ref":{"doc":"MT","page":46}},{"id":"mt-044","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, how close to a stop sign may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Drivers need to see the sign from far away.","h2":"In Montana you may not park within 30 feet of a stop sign, yield sign, or traffic signal at the side of the road.","p":"Right. Park at least 30 feet from a stop sign."},"es":{"q":"En Montana, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los conductores necesitan ver la señal desde lejos.","h2":"En Montana no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo al lado de la vía.","p":"Correcto. Estaciónese al menos a 30 pies de una señal de alto."},"zh":{"q":"在 Montana，你可以在离停车标志多近的地方停车？","o":["不得近于 10 英尺","不得近于 20 英尺","不得近于 30 英尺","不得近于 50 英尺"],"h1":"司机需要从很远的地方看到标志。","h2":"在 Montana，你不可以在路边的停车标志、让行标志或交通信号灯 30 英尺之内停车。","p":"对。停车要离停车标志至少 30 英尺。"},"vi":{"q":"Ở Montana, bạn được đậu xe gần biển dừng (stop) đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Tài xế cần nhìn thấy biển báo từ xa.","h2":"Ở Montana, bạn không được đậu xe trong vòng 30 feet tính từ biển dừng, biển nhường đường hoặc đèn giao thông ở bên đường.","p":"Đúng. Đậu xe cách biển dừng ít nhất 30 feet."},"tl":{"q":"Sa Montana, gaano kalapit sa stop sign ka maaaring pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 30 feet","Hindi lalapit sa 50 feet"],"h1":"Kailangang makita ng mga drayber ang karatula mula sa malayo.","h2":"Sa Montana, hindi ka maaaring pumarada sa loob ng 30 feet mula sa stop sign, yield sign, o traffic signal sa gilid ng daan.","p":"Tama. Pumarada nang hindi bababa sa 30 feet mula sa stop sign."},"ar":{"q":"في Montana، كم يمكنك أن تقترب من إشارة قف عندما تركن سيارتك؟","o":["ليس أقرب من 10 feet","ليس أقرب من 20 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet"],"h1":"يحتاج السائقون إلى رؤية الإشارة من بعيد.","h2":"في Montana يجب ألّا تركن سيارتك على بُعد أقل من 30 feet من إشارة قف أو إشارة أفضلية المرور أو إشارة ضوئية على جانب الطريق.","p":"صحيح. اركن على بُعد 30 feet على الأقل من إشارة قف."},"ref":{"doc":"MT","page":46}},{"id":"mt-045","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you are convicted of driving without liability insurance. How many points go on your driving record?","o":["2 points","3 points","10 points","5 points"],"h1":"It is more than a speeding ticket, which is 3.","h2":"In Montana, a conviction for driving without liability insurance adds 5 points to your driving record, on top of the fine.","p":"Right. No insurance means 5 points on your record."},"es":{"q":"En Montana, a usted lo declaran culpable de manejar sin seguro de responsabilidad civil. ¿Cuántos puntos se agregan a su historial de manejo?","o":["2 puntos","3 puntos","10 puntos","5 puntos"],"h1":"Es más que una multa por exceso de velocidad, que son 3.","h2":"En Montana, una condena por manejar sin seguro de responsabilidad civil agrega 5 puntos a su historial de manejo, además de la multa.","p":"Correcto. Manejar sin seguro son 5 puntos en su historial."},"zh":{"q":"在 Montana，你因没有责任保险开车被定罪。你的驾驶记录上会加几分？","o":["2 分","3 分","10 分","5 分"],"h1":"比超速罚单的 3 分多。","h2":"在 Montana，没有责任保险开车被定罪，除了罚款，还会在你的驾驶记录上加 5 分。","p":"对。没有保险会在记录上加 5 分。"},"vi":{"q":"Ở Montana, bạn bị kết tội lái xe không có bảo hiểm trách nhiệm. Hồ sơ lái xe của bạn bị ghi bao nhiêu điểm?","o":["2 điểm","3 điểm","10 điểm","5 điểm"],"h1":"Nhiều hơn vé phạt chạy quá tốc độ, là 3 điểm.","h2":"Ở Montana, bị kết tội lái xe không có bảo hiểm trách nhiệm sẽ bị ghi 5 điểm vào hồ sơ lái xe, ngoài tiền phạt.","p":"Đúng. Không có bảo hiểm nghĩa là bị ghi 5 điểm vào hồ sơ."},"tl":{"q":"Sa Montana, nahatulan ka sa pagmamaneho nang walang liability insurance. Ilang puntos ang mapupunta sa iyong driving record?","o":["2 puntos","3 puntos","10 puntos","5 puntos"],"h1":"Mas marami ito kaysa sa ticket sa sobrang bilis, na 3.","h2":"Sa Montana, ang hatol sa pagmamaneho nang walang liability insurance ay nagdaragdag ng 5 puntos sa iyong driving record, bukod pa sa multa.","p":"Tama. Ang walang insurance ay 5 puntos sa iyong record."},"ar":{"q":"في Montana، أُدنت بالقيادة دون تأمين المسؤولية. كم نقطة تُضاف إلى سجل القيادة الخاص بك؟","o":["نقطتان","3 نقاط","10 نقاط","5 نقاط"],"h1":"إنها أكثر من مخالفة السرعة، وهي 3.","h2":"في Montana، الإدانة بالقيادة دون تأمين المسؤولية تضيف 5 نقاط إلى سجل القيادة الخاص بك، بالإضافة إلى الغرامة.","p":"صحيح. عدم وجود تأمين يعني 5 نقاط في سجلك."},"ref":{"doc":"MT","page":47}},{"id":"mt-046","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, during which months may you use studded tires?","o":["October 1 through May 31","All year long","November 1 through March 31","June 1 through September 30"],"h1":"Studs are for the snowy part of the year, which is long in Montana.","h2":"In Montana, studded tires may be used only from October 1 through May 31, because they damage roads.","p":"Right. Studded tires are allowed October 1 through May 31."},"es":{"q":"En Montana, ¿en qué meses puede usar llantas con clavos?","o":["Del 1 de octubre al 31 de mayo","Todo el año","Del 1 de noviembre al 31 de marzo","Del 1 de junio al 30 de septiembre"],"h1":"Los clavos son para la parte del año con nieve, que en Montana es larga.","h2":"En Montana, las llantas con clavos solo se pueden usar del 1 de octubre al 31 de mayo, porque dañan las carreteras.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 31 de mayo."},"zh":{"q":"在 Montana，哪几个月可以使用防滑钉轮胎？","o":["10 月 1 日到 5 月 31 日","全年都可以","11 月 1 日到 3 月 31 日","6 月 1 日到 9 月 30 日"],"h1":"防滑钉是给一年中下雪的时候用的，在 Montana 这段时间很长。","h2":"在 Montana，防滑钉轮胎只能在 10 月 1 日到 5 月 31 日使用，因为它们会损坏道路。","p":"对。防滑钉轮胎可以在 10 月 1 日到 5 月 31 日使用。"},"vi":{"q":"Ở Montana, bạn được dùng lốp có đinh vào những tháng nào?","o":["Từ 1 tháng 10 đến 31 tháng 5","Quanh năm","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 6 đến 30 tháng 9"],"h1":"Đinh dùng cho mùa tuyết trong năm, mà ở Montana mùa này rất dài.","h2":"Ở Montana, lốp có đinh chỉ được dùng từ 1 tháng 10 đến 31 tháng 5, vì chúng làm hỏng mặt đường.","p":"Đúng. Lốp có đinh được dùng từ 1 tháng 10 đến 31 tháng 5."},"tl":{"q":"Sa Montana, sa anong mga buwan maaaring gumamit ng studded tires?","o":["Oktubre 1 hanggang Mayo 31","Buong taon","Nobyembre 1 hanggang Marso 31","Hunyo 1 hanggang Setyembre 30"],"h1":"Ang studs ay para sa panahon ng niyebe, na mahaba sa Montana.","h2":"Sa Montana, maaaring gamitin ang studded tires mula Oktubre 1 hanggang Mayo 31 lamang, dahil sinisira nila ang mga daan.","p":"Tama. Pinapayagan ang studded tires mula Oktubre 1 hanggang Mayo 31."},"ar":{"q":"في Montana، في أي أشهر يجوز لك استخدام الإطارات ذات المسامير؟","o":["من 1 أكتوبر حتى 31 مايو","طوال السنة","من 1 نوفمبر حتى 31 مارس","من 1 يونيو حتى 30 سبتمبر"],"h1":"المسامير لفصل الثلج من السنة، وهو طويل في Montana.","h2":"في Montana، لا يجوز استخدام الإطارات ذات المسامير إلا من 1 أكتوبر حتى 31 مايو، لأنها تُتلف الطرق.","p":"صحيح. الإطارات ذات المسامير مسموحة من 1 أكتوبر حتى 31 مايو."},"ref":{"doc":"MT","page":60}},{"id":"mt-047","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, a farm tractor or other farm vehicle is coming toward you on the highway. How must you slow down?","o":["Slow down 5 mph","Slow to half the posted speed limit","Stop until it passes","Keep your speed and honk"],"h1":"Cut the posted number in two.","h2":"Montana law says that when a farm vehicle comes toward you, you must slow to half the posted speed limit.","p":"Right. Slow to half the speed limit for an oncoming farm vehicle."},"es":{"q":"En Montana, un tractor u otro vehículo agrícola viene hacia usted en la carretera. ¿Cómo debe reducir la velocidad?","o":["Bajar 5 mph","Bajar a la mitad del límite de velocidad indicado","Detenerse hasta que pase","Mantener la velocidad y tocar la bocina"],"h1":"Divida entre dos el número del letrero.","h2":"La ley de Montana dice que cuando un vehículo agrícola viene hacia usted, debe bajar a la mitad del límite de velocidad indicado.","p":"Correcto. Baje a la mitad del límite ante un vehículo agrícola que viene de frente."},"zh":{"q":"在 Montana，一辆农用拖拉机或其他农用车在公路上朝你开过来。你必须怎样减速？","o":["减速 5 mph","减到限速的一半","停车等它开过去","保持速度并按喇叭"],"h1":"把限速的数字除以二。","h2":"Montana 法律规定，农用车朝你开过来时，你必须把速度减到限速的一半。","p":"对。对面来农用车时，把速度减到限速的一半。"},"vi":{"q":"Ở Montana, một máy kéo nông trại hoặc xe nông nghiệp khác đang chạy về phía bạn trên xa lộ. Bạn phải giảm tốc như thế nào?","o":["Giảm 5 mph","Giảm xuống còn một nửa tốc độ giới hạn","Dừng lại cho đến khi nó đi qua","Giữ tốc độ và bấm còi"],"h1":"Chia đôi con số tốc độ giới hạn.","h2":"Luật Montana nói rằng khi xe nông nghiệp chạy về phía bạn, bạn phải giảm xuống còn một nửa tốc độ giới hạn.","p":"Đúng. Giảm còn một nửa tốc độ giới hạn khi có xe nông nghiệp chạy ngược chiều."},"tl":{"q":"Sa Montana, papalapit sa iyo sa highway ang isang farm tractor o ibang sasakyang pansakahan. Paano ka dapat bumagal?","o":["Bumagal nang 5 mph","Bumagal hanggang kalahati ng speed limit","Huminto hanggang makalampas ito","Panatilihin ang bilis at bumusina"],"h1":"Hatiin sa dalawa ang nakapaskil na numero.","h2":"Sinasabi ng batas ng Montana na kapag papalapit sa iyo ang sasakyang pansakahan, dapat kang bumagal hanggang kalahati ng speed limit.","p":"Tama. Bumagal hanggang kalahati ng speed limit para sa paparating na sasakyang pansakahan."},"ar":{"q":"في Montana، جرار زراعي أو مركبة زراعية أخرى قادمة نحوك على الطريق السريع. كيف يجب أن تخفف سرعتك؟","o":["خفّف 5 mph","خفّف إلى نصف الحد الأقصى للسرعة","توقف حتى تمر","حافظ على سرعتك واستخدم البوق"],"h1":"اقسم الرقم المكتوب على اللافتة على اثنين.","h2":"ينص قانون Montana على أنه عندما تأتي مركبة زراعية نحوك، يجب أن تخفف سرعتك إلى نصف الحد الأقصى للسرعة.","p":"صحيح. خفّف إلى نصف الحد الأقصى للسرعة عندما تأتي مركبة زراعية من الاتجاه المقابل."},"ref":{"doc":"MT","page":null}},{"id":"mt-048","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, a motorcycle may pass stopped or very slow cars in the same lane (\"lane filtering\"). How fast may the motorcycle go while doing this?","o":["No faster than 40 mph","Any speed that feels safe","No faster than 5 mph","No faster than 20 mph"],"h1":"It is twice the top speed of the cars being passed.","h2":"Montana law allows lane filtering only past vehicles going 10 mph or less, and the motorcycle may go no faster than 20 mph.","p":"Right. A lane-filtering motorcycle may go up to 20 mph."},"es":{"q":"En Montana, una motocicleta puede pasar entre autos detenidos o muy lentos en el mismo carril (\"lane filtering\"). ¿A qué velocidad puede ir la motocicleta al hacerlo?","o":["No más de 40 mph","A la velocidad que le parezca segura","No más de 5 mph","No más de 20 mph"],"h1":"Es el doble de la velocidad máxima de los autos que pasa.","h2":"La ley de Montana permite el lane filtering solo junto a vehículos que van a 10 mph o menos, y la motocicleta no puede ir a más de 20 mph.","p":"Correcto. Una motocicleta que hace lane filtering puede ir hasta 20 mph."},"zh":{"q":"在 Montana，摩托车可以在同一车道内从停着或开得很慢的汽车旁边穿过（\"lane filtering\"，车道穿行）。这样做时摩托车最快可以开多快？","o":["不超过 40 mph","任何感觉安全的速度","不超过 5 mph","不超过 20 mph"],"h1":"是被超过的汽车最高速度的两倍。","h2":"Montana 法律只允许在车速 10 mph 或更低的车辆旁边车道穿行，而且摩托车速度不能超过 20 mph。","p":"对。车道穿行的摩托车最快可以开 20 mph。"},"vi":{"q":"Ở Montana, xe máy được đi qua giữa các xe đang dừng hoặc chạy rất chậm trong cùng một làn (\"lane filtering\"). Khi làm vậy, xe máy được chạy nhanh đến mức nào?","o":["Không quá 40 mph","Tốc độ nào cảm thấy an toàn","Không quá 5 mph","Không quá 20 mph"],"h1":"Gấp đôi tốc độ tối đa của các xe đang bị vượt.","h2":"Luật Montana chỉ cho phép lane filtering khi đi qua các xe chạy 10 mph hoặc chậm hơn, và xe máy không được chạy quá 20 mph.","p":"Đúng. Xe máy khi lane filtering được chạy tối đa 20 mph."},"tl":{"q":"Sa Montana, maaaring lampasan ng motorsiklo ang mga nakahinto o napakabagal na kotse sa parehong lane (\"lane filtering\"). Gaano kabilis maaaring tumakbo ang motorsiklo habang ginagawa ito?","o":["Hindi lalampas sa 40 mph","Anumang bilis na pakiramdam ay ligtas","Hindi lalampas sa 5 mph","Hindi lalampas sa 20 mph"],"h1":"Doble ito ng pinakamataas na bilis ng mga kotseng nilalampasan.","h2":"Pinapayagan ng batas ng Montana ang lane filtering lamang sa paglampas sa mga sasakyang tumatakbo nang 10 mph o mas mabagal, at hindi maaaring lumampas ang motorsiklo sa 20 mph.","p":"Tama. Ang motorsiklong nagla-lane filtering ay maaaring tumakbo nang hanggang 20 mph."},"ar":{"q":"في Montana، يجوز للدراجة النارية أن تمر بين السيارات المتوقفة أو البطيئة جدًا في الحارة نفسها (\"lane filtering\"). ما أقصى سرعة للدراجة النارية أثناء ذلك؟","o":["ليس أسرع من 40 mph","أي سرعة تبدو آمنة","ليس أسرع من 5 mph","ليس أسرع من 20 mph"],"h1":"إنها ضعف أقصى سرعة للسيارات التي تمر بجانبها.","h2":"يسمح قانون Montana بالـ lane filtering فقط بجانب المركبات التي تسير بسرعة 10 mph أو أقل، ويجب ألّا تتجاوز سرعة الدراجة النارية 20 mph.","p":"صحيح. الدراجة النارية التي تمر بين السيارات يجوز أن تسير حتى 20 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-049","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, you are lawfully asked to take a test for alcohol or drugs and you refuse for the first time. What happens to your license?","o":["Nothing, if you were not drunk","It is suspended for 30 days","It is suspended for 6 months","It is revoked for life"],"h1":"It is half a year.","h2":"In Montana, a first refusal of a lawful alcohol or drug test suspends your license for 6 months, with no restricted license.","p":"Right. A first refusal means a 6-month suspension."},"es":{"q":"En Montana, le piden legalmente una prueba de alcohol o drogas y usted se niega por primera vez. ¿Qué pasa con su licencia?","o":["Nada, si no estaba ebrio","La suspenden por 30 días","La suspenden por 6 meses","Se la quitan de por vida"],"h1":"Es medio año.","h2":"En Montana, la primera negativa a una prueba legal de alcohol o drogas suspende su licencia por 6 meses, sin licencia restringida.","p":"Correcto. La primera negativa trae una suspensión de 6 meses."},"zh":{"q":"在 Montana，你被依法要求接受酒精或毒品检测，而你第一次拒绝。你的驾照会怎样？","o":["如果你没有喝醉，就什么事都没有","暂停 30 天","暂停 6 个月","终身吊销"],"h1":"是半年。","h2":"在 Montana，第一次拒绝依法进行的酒精或毒品检测，驾照会被暂停 6 个月，而且不能拿限制驾照。","p":"对。第一次拒绝会被暂停驾照 6 个月。"},"vi":{"q":"Ở Montana, bạn được yêu cầu hợp pháp làm xét nghiệm rượu bia hoặc ma túy và bạn từ chối lần đầu. Bằng lái của bạn sẽ ra sao?","o":["Không sao cả, nếu bạn không say","Bị treo 30 ngày","Bị treo 6 tháng","Bị thu hồi vĩnh viễn"],"h1":"Đó là nửa năm.","h2":"Ở Montana, từ chối lần đầu xét nghiệm rượu bia hoặc ma túy hợp pháp sẽ bị treo bằng lái 6 tháng, không có bằng lái hạn chế.","p":"Đúng. Từ chối lần đầu nghĩa là bị treo bằng 6 tháng."},"tl":{"q":"Sa Montana, legal kang hiniling na magpa-test para sa alak o droga at tumanggi ka sa unang pagkakataon. Ano ang mangyayari sa iyong license?","o":["Wala, kung hindi ka lasing","Masususpinde ito nang 30 araw","Masususpinde ito nang 6 na buwan","Babawiin ito habambuhay"],"h1":"Kalahating taon ito.","h2":"Sa Montana, ang unang pagtanggi sa legal na test para sa alak o droga ay sumususpinde sa iyong license nang 6 na buwan, nang walang restricted license.","p":"Tama. Ang unang pagtanggi ay 6 na buwang suspensyon."},"ar":{"q":"في Montana، طُلب منك بشكل قانوني إجراء فحص للكحول أو المخدرات ورفضت لأول مرة. ماذا يحدث لرخصتك؟","o":["لا شيء، إذا لم تكن مخمورًا","تُوقف لمدة 30 يومًا","تُوقف لمدة 6 أشهر","تُسحب مدى الحياة"],"h1":"إنها نصف سنة.","h2":"في Montana، الرفض الأول لفحص قانوني للكحول أو المخدرات يوقف رخصتك لمدة 6 أشهر، دون رخصة مقيدة.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة 6 أشهر."},"ref":{"doc":"MT","page":null}},{"id":"mt-050","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, a driver becomes a \"habitual traffic offender\" after collecting how many points?","o":["30 points within 3 years","12 points within 1 year","20 points within 2 years","50 points within 5 years"],"h1":"Think of ten points for each year.","h2":"In Montana, a driver who gets 30 or more conviction points within 3 years is a habitual traffic offender.","p":"Right. 30 points in 3 years makes a habitual traffic offender."},"es":{"q":"En Montana, ¿después de acumular cuántos puntos un conductor se considera \"infractor habitual de tránsito\"?","o":["30 puntos en 3 años","12 puntos en 1 año","20 puntos en 2 años","50 puntos en 5 años"],"h1":"Piense en diez puntos por cada año.","h2":"En Montana, un conductor que acumula 30 puntos o más por condenas en 3 años es un infractor habitual de tránsito.","p":"Correcto. 30 puntos en 3 años hacen a un infractor habitual."},"zh":{"q":"在 Montana，司机累积多少分后会成为\"惯犯交通违规者\"（habitual traffic offender）？","o":["3 年内 30 分","1 年内 12 分","2 年内 20 分","5 年内 50 分"],"h1":"想想每年十分。","h2":"在 Montana，3 年内被定罪累积 30 分或以上的司机就是惯犯交通违规者（habitual traffic offender）。","p":"对。3 年内 30 分就成为惯犯交通违规者。"},"vi":{"q":"Ở Montana, tài xế trở thành \"người vi phạm giao thông thường xuyên\" (habitual traffic offender) sau khi bị bao nhiêu điểm?","o":["30 điểm trong vòng 3 năm","12 điểm trong vòng 1 năm","20 điểm trong vòng 2 năm","50 điểm trong vòng 5 năm"],"h1":"Hãy nghĩ mười điểm cho mỗi năm.","h2":"Ở Montana, tài xế bị 30 điểm kết tội trở lên trong vòng 3 năm là người vi phạm giao thông thường xuyên (habitual traffic offender).","p":"Đúng. 30 điểm trong 3 năm là người vi phạm giao thông thường xuyên."},"tl":{"q":"Sa Montana, nagiging \"habitual traffic offender\" ang isang drayber pagkatapos makaipon ng ilang puntos?","o":["30 puntos sa loob ng 3 taon","12 puntos sa loob ng 1 taon","20 puntos sa loob ng 2 taon","50 puntos sa loob ng 5 taon"],"h1":"Isipin ang sampung puntos bawat taon.","h2":"Sa Montana, ang drayber na nakakuha ng 30 o higit pang puntos mula sa mga hatol sa loob ng 3 taon ay isang habitual traffic offender.","p":"Tama. Ang 30 puntos sa loob ng 3 taon ay nagiging habitual traffic offender."},"ar":{"q":"في Montana، يصبح السائق \"مخالفًا مروريًا معتادًا\" (habitual traffic offender) بعد جمع كم نقطة؟","o":["30 نقطة خلال 3 سنوات","12 نقطة خلال سنة واحدة","20 نقطة خلال سنتين","50 نقطة خلال 5 سنوات"],"h1":"فكّر في عشر نقاط لكل سنة.","h2":"في Montana، السائق الذي يحصل على 30 نقطة إدانة أو أكثر خلال 3 سنوات هو مخالف مروري معتاد (habitual traffic offender).","p":"صحيح. 30 نقطة في 3 سنوات تجعلك مخالفًا مروريًا معتادًا."},"ref":{"doc":"MT","page":null}},{"id":"mt-051","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, you have a crash where no one is hurt. You must tell the police right away if the damage looks like it is at least how much?","o":["$250","$1,000","$2,500","$5,000"],"h1":"It is a four-digit amount.","h2":"Montana law says to notify the police right away after a crash with injury, death, or damage that appears to be $1,000 or more.","p":"Right. Damage of $1,000 or more must be reported right away."},"es":{"q":"En Montana, usted tiene un choque sin heridos. ¿A partir de qué cantidad de daño aparente debe avisar a la policía de inmediato?","o":["$250","$1,000","$2,500","$5,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"La ley de Montana dice que avise a la policía de inmediato después de un choque con heridos, muertos o daños que parezcan ser de $1,000 o más.","p":"Correcto. Los daños de $1,000 o más se deben reportar de inmediato."},"zh":{"q":"在 Montana，你出了一场没有人受伤的车祸。如果损失看起来至少达到多少，你必须马上报警？","o":["$250","$1,000","$2,500","$5,000"],"h1":"是一个四位数的金额。","h2":"Montana 法律规定，车祸造成受伤、死亡，或损失看起来达到 $1,000 或以上时，要马上报警。","p":"对。损失达到 $1,000 或以上必须马上报告。"},"vi":{"q":"Ở Montana, bạn gặp tai nạn mà không ai bị thương. Bạn phải báo cảnh sát ngay nếu thiệt hại có vẻ ít nhất là bao nhiêu?","o":["$250","$1,000","$2,500","$5,000"],"h1":"Đó là số tiền có bốn chữ số.","h2":"Luật Montana nói rằng phải báo cảnh sát ngay sau một tai nạn có người bị thương, người chết, hoặc thiệt hại có vẻ từ $1,000 trở lên.","p":"Đúng. Thiệt hại từ $1,000 trở lên phải được báo ngay."},"tl":{"q":"Sa Montana, nagkaroon ka ng banggaan na walang nasaktan. Dapat mong sabihan agad ang pulis kung mukhang hindi bababa sa magkano ang pinsala?","o":["$250","$1,000","$2,500","$5,000"],"h1":"Halagang may apat na digit ito.","h2":"Sinasabi ng batas ng Montana na sabihan agad ang pulis pagkatapos ng banggaan na may nasaktan, namatay, o pinsalang mukhang $1,000 o higit pa.","p":"Tama. Ang pinsalang $1,000 o higit pa ay dapat iulat agad."},"ar":{"q":"في Montana، وقع لك حادث لم يُصب فيه أحد. يجب أن تُبلغ الشرطة فورًا إذا بدا أن الضرر يساوي على الأقل كم؟","o":["$250","$1,000","$2,500","$5,000"],"h1":"إنه مبلغ من أربعة أرقام.","h2":"ينص قانون Montana على إبلاغ الشرطة فورًا بعد حادث فيه إصابة أو وفاة أو ضرر يبدو أنه $1,000 أو أكثر.","p":"صحيح. الضرر الذي يبلغ $1,000 أو أكثر يجب الإبلاغ عنه فورًا."},"ref":{"doc":"MT","page":null}},{"id":"mt-052","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, you move to the state with a valid license from another state. For how long may you keep driving on it?","o":["10 days","30 days","60 days","1 year"],"h1":"It is about two months.","h2":"In Montana a new resident may drive on a valid out-of-state license for up to 60 days in a row, then must get a Montana license.","p":"Right. A new resident has up to 60 days."},"es":{"q":"En Montana, usted se muda al estado con una licencia válida de otro estado. ¿Por cuánto tiempo puede seguir manejando con ella?","o":["10 días","30 días","60 días","1 año"],"h1":"Son unos dos meses.","h2":"En Montana, un nuevo residente puede manejar con una licencia válida de otro estado hasta 60 días seguidos y luego debe obtener una licencia de Montana.","p":"Correcto. Un nuevo residente tiene hasta 60 días."},"ref":{"doc":"MT","page":3}},{"id":"mt-053","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, a basic Class D license lets you drive non-commercial vehicles up to what weight?","o":["Under 10,000 pounds","Under 26,000 pounds","Under 40,000 pounds","Any weight"],"h1":"Above this weight, a commercial license is needed.","h2":"In Montana a Class D license covers non-commercial vehicles under 26,000 pounds gross vehicle weight.","p":"Right. Class D covers vehicles under 26,000 pounds."},"es":{"q":"En Montana, una licencia básica Clase D ¿le permite manejar vehículos no comerciales de hasta qué peso?","o":["Menos de 10,000 libras","Menos de 26,000 libras","Menos de 40,000 libras","Cualquier peso"],"h1":"Por encima de este peso se necesita una licencia comercial.","h2":"En Montana, una licencia Clase D cubre vehículos no comerciales de menos de 26,000 libras de peso bruto.","p":"Correcto. La Clase D cubre vehículos de menos de 26,000 libras."},"ref":{"doc":"MT","page":1}},{"id":"mt-054","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a teen breaks a rule of the first-year restricted license for the second time. What is the penalty?","o":["A warning letter","20 hours of community service","A $20 fine","The license is suspended for 6 months"],"h1":"The second penalty is much stronger than community service.","h2":"In Montana a second violation of the first-year restricted license rules means the teen's license is suspended for six months.","p":"Right. A second offense brings a 6-month suspension."},"es":{"q":"En Montana, un adolescente rompe por segunda vez una regla de la licencia restringida del primer año. ¿Cuál es la sanción?","o":["Una carta de advertencia","20 horas de servicio comunitario","Una multa de $20","La licencia se suspende por 6 meses"],"h1":"La segunda sanción es mucho más fuerte que el servicio comunitario.","h2":"En Montana, una segunda infracción de las reglas de la licencia restringida del primer año significa que la licencia del adolescente se suspende por seis meses.","p":"Correcto. Una segunda infracción trae una suspensión de 6 meses."},"ref":{"doc":"MT","page":8}},{"id":"mt-055","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, during the second six months of a restricted license, how many unrelated passengers under 18 may a teen carry without an adult supervisor?","o":["Up to three","None","Only one","Any number"],"h1":"The limit goes up after the first six months.","h2":"In Montana, during the second six months of a restricted license, a teen may carry up to three unrelated passengers under 18 without a licensed adult.","p":"Right. In the second six months, up to three."},"es":{"q":"En Montana, durante los segundos seis meses de la licencia restringida, ¿cuántos pasajeros menores de 18 años, que no sean parientes, puede llevar un adolescente sin un adulto supervisor?","o":["Hasta tres","Ninguno","Solo uno","Cualquier número"],"h1":"El límite sube después de los primeros seis meses.","h2":"En Montana, durante los segundos seis meses de la licencia restringida, un adolescente puede llevar hasta tres pasajeros menores de 18 años que no sean parientes, sin un adulto con licencia.","p":"Correcto. En los segundos seis meses, hasta tres."},"ref":{"doc":"MT","page":8}},{"id":"mt-056","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, a teen is driving with a learner license. Where must the supervising adult sit?","o":["Anywhere in the car","In the back seat","In the seat beside the driver","In another car close behind"],"h1":"The adult must be close enough to help right away.","h2":"In Montana the adult who supervises a learner must sit in the seat beside the driver.","p":"Right. The supervisor sits beside the driver."},"es":{"q":"En Montana, un adolescente maneja con licencia de aprendiz. ¿Dónde debe sentarse el adulto que lo supervisa?","o":["En cualquier lugar del carro","En el asiento de atrás","En el asiento al lado del conductor","En otro carro justo detrás"],"h1":"El adulto debe estar lo bastante cerca para ayudar enseguida.","h2":"En Montana, el adulto que supervisa a un aprendiz debe sentarse en el asiento al lado del conductor.","p":"Correcto. El supervisor se sienta al lado del conductor."},"ref":{"doc":"MT","page":2}},{"id":"mt-057","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, a parent signs the consent form for a teen under 18 to get a license. What does the parent accept by signing?","o":["That the teen has finished driver education","Financial responsibility for damage the teen causes while driving","That the teen will drive only in daylight","That the parent will ride along for the first year"],"h1":"It is about who pays.","h2":"In Montana a parent who signs for a teen under 18 accepts financial responsibility for any damage the teen causes while driving.","p":"Right. The parent accepts financial responsibility."},"es":{"q":"En Montana, un padre firma el formulario de consentimiento para que un adolescente menor de 18 años obtenga la licencia. ¿Qué acepta el padre al firmar?","o":["Que el adolescente terminó la educación vial","La responsabilidad económica por los daños que cause el adolescente al manejar","Que el adolescente manejará solo de día","Que el padre lo acompañará el primer año"],"h1":"Tiene que ver con quién paga.","h2":"En Montana, el padre que firma por un adolescente menor de 18 años acepta la responsabilidad económica por cualquier daño que el adolescente cause al manejar.","p":"Correcto. El padre acepta la responsabilidad económica."},"ref":{"doc":"MT","page":2}},{"id":"mt-058","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you pay for your license and start testing. How many tries at the required tests does your receipt give you?","o":["One try","Two tries in 30 days","Unlimited tries","Three tries within one year"],"h1":"The receipt lasts one year.","h2":"In Montana a driver license receipt is good for one year and gives you three tries to pass all the required tests.","p":"Right. Three tries within one year."},"es":{"q":"En Montana, usted paga su licencia y empieza los exámenes. ¿Cuántos intentos le da su recibo para los exámenes requeridos?","o":["Un intento","Dos intentos en 30 días","Intentos ilimitados","Tres intentos dentro de un año"],"h1":"El recibo dura un año.","h2":"En Montana, el recibo de la licencia vale por un año y le da tres intentos para aprobar todos los exámenes requeridos.","p":"Correcto. Tres intentos dentro de un año."},"ref":{"doc":"MT","page":9}},{"id":"mt-059","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, a driver between 21 and 75 gets a new license. What is the longest it can be valid?","o":["Eight years","Four years","Ten years","Until age 80"],"h1":"It is twice as long as a license for drivers 75 and older.","h2":"In Montana a license for a driver between 21 and 75 is valid for eight years at most, or until the 75th birthday if that comes first.","p":"Right. Up to eight years."},"es":{"q":"En Montana, un conductor de entre 21 y 75 años obtiene una licencia nueva. ¿Cuánto tiempo puede ser válida como máximo?","o":["Ocho años","Cuatro años","Diez años","Hasta los 80 años"],"h1":"Es el doble que una licencia para conductores de 75 años o más.","h2":"En Montana, la licencia de un conductor de entre 21 y 75 años es válida por ocho años como máximo, o hasta que cumpla 75 años si eso ocurre antes.","p":"Correcto. Hasta ocho años."},"ref":{"doc":"MT","page":8}},{"id":"mt-060","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, your license has expired. Until when can you renew it without taking the tests again?","o":["Up to 10 days after it expires","Up to 1 year after it expires","Up to 3 months after it expires","You must always retest"],"h1":"After this time you start over as a new driver.","h2":"In Montana you can renew a license up to three months after it expires without retesting; after that you must apply as a new driver.","p":"Right. You have up to 3 months."},"es":{"q":"En Montana, su licencia está vencida. ¿Hasta cuándo puede renovarla sin volver a tomar los exámenes?","o":["Hasta 10 días después de vencer","Hasta 1 año después de vencer","Hasta 3 meses después de vencer","Siempre debe repetir los exámenes"],"h1":"Después de ese tiempo empieza de nuevo como conductor nuevo.","h2":"En Montana, puede renovar la licencia hasta tres meses después de que vence sin repetir los exámenes; después de eso debe solicitarla como conductor nuevo.","p":"Correcto. Tiene hasta 3 meses."},"ref":{"doc":"MT","page":9}},{"id":"mt-061","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, a police car signals you to pull over. How should you show the officer that you have seen them?","o":["Wave out the window","Turn on your right turn signal","Flash your high beams","Stop right where you are in the lane"],"h1":"Use something that also shows which way you will move.","h2":"In Montana, when an officer pulls you over, you turn on your right turn signal to show you have seen them, then move onto the right shoulder.","p":"Right. Turn on your right turn signal."},"es":{"q":"En Montana, un carro de policía le indica que se detenga. ¿Cómo debe mostrarle al agente que lo ha visto?","o":["Saludando por la ventana","Encendiendo la direccional derecha","Encendiendo las luces altas","Deteniéndose donde está, en el carril"],"h1":"Use algo que también muestre hacia dónde se va a mover.","h2":"En Montana, cuando un agente le pide que se detenga, usted enciende la direccional derecha para mostrar que lo ha visto y luego se mueve al acotamiento derecho.","p":"Correcto. Encienda la direccional derecha."},"ref":{"doc":"MT","page":81}},{"id":"mt-062","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, when can the motorcycle road test be skipped?","o":["When you already have a car license","When you are over 21","When you have ridden for one year","When you passed an approved motorcycle safety course in the past year"],"h1":"It depends on a recent safety course.","h2":"In Montana the motorcycle road test may be waived if you passed a Montana Motorcycle Safety Foundation course in the past year and show the certificate.","p":"Right. A safety course passed in the past year can replace the road test."},"es":{"q":"En Montana, ¿cuándo se puede omitir el examen práctico de motocicleta?","o":["Cuando ya tiene licencia de carro","Cuando tiene más de 21 años","Cuando ha manejado moto por un año","Cuando aprobó un curso aprobado de seguridad en motocicleta en el último año"],"h1":"Depende de un curso de seguridad reciente.","h2":"En Montana, el examen práctico de motocicleta se puede omitir si aprobó un curso de la Montana Motorcycle Safety Foundation en el último año y muestra el certificado.","p":"Correcto. Un curso de seguridad aprobado en el último año puede reemplazar el examen práctico."},"ref":{"doc":"MT","page":2}},{"id":"mt-063","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, a rider has a motorcycle learner license. Who must supervise the rider?","o":["A licensed driver who has a motorcycle endorsement","Any adult age 18 or older","Any licensed car driver","No one; the rider may ride alone"],"h1":"The supervisor must be licensed for the same kind of vehicle.","h2":"In Montana a rider with a motorcycle learner license must be supervised by a licensed driver who has a motorcycle endorsement.","p":"Right. The supervisor needs a motorcycle endorsement."},"es":{"q":"En Montana, una persona tiene licencia de aprendiz de motocicleta. ¿Quién debe supervisarla?","o":["Un conductor con licencia que tenga endoso de motocicleta","Cualquier adulto de 18 años o más","Cualquier conductor con licencia de carro","Nadie; puede manejar sola"],"h1":"El supervisor debe tener licencia para el mismo tipo de vehículo.","h2":"En Montana, una persona con licencia de aprendiz de motocicleta debe ser supervisada por un conductor con licencia que tenga endoso de motocicleta.","p":"Correcto. El supervisor necesita endoso de motocicleta."},"ref":{"doc":"MT","page":3}},{"id":"mt-064","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, from what age can a teen ask to be marked as an organ donor on the license without a parent's permission?","o":["18","21","15","16"],"h1":"It is younger than the age for a full license.","h2":"In Montana a minor who is at least 15 can ask for the organ donor mark on the license, and no parent permission is needed.","p":"Right. From age 15, without a parent's permission."},"es":{"q":"En Montana, ¿desde qué edad puede un adolescente pedir que su licencia lo marque como donante de órganos sin permiso de sus padres?","o":["18","21","15","16"],"h1":"Es menos que la edad para una licencia completa.","h2":"En Montana, un menor de al menos 15 años puede pedir la marca de donante de órganos en su licencia, y no necesita permiso de sus padres.","p":"Correcto. Desde los 15 años, sin permiso de los padres."},"ref":{"doc":"MT","page":84}},{"id":"mt-065","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, what vision must you have to pass the license vision test?","o":["20/20 in both eyes","At least 20/40 in at least one eye","20/100 in each eye","Any vision, if you wear glasses"],"h1":"Glasses or contacts may be used, and one eye can be enough.","h2":"In Montana you must have at least 20/40 vision in at least one eye, with or without glasses or contacts, to pass the vision test.","p":"Right. At least 20/40 in at least one eye."},"es":{"q":"En Montana, ¿qué visión debe tener para aprobar el examen de la vista de la licencia?","o":["20/20 en ambos ojos","Al menos 20/40 en por lo menos un ojo","20/100 en cada ojo","Cualquier visión, si usa lentes"],"h1":"Se pueden usar lentes o lentes de contacto, y un ojo puede bastar.","h2":"En Montana, debe tener una visión de al menos 20/40 en por lo menos un ojo, con o sin lentes, para aprobar el examen de la vista.","p":"Correcto. Al menos 20/40 en por lo menos un ojo."},"ref":{"doc":"MT","page":70}},{"id":"mt-066","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, your high beams must light up people and vehicles at least how far ahead?","o":["100 feet","200 feet","1,000 feet","350 feet"],"h1":"Low beams reach 100 feet; high beams reach much farther.","h2":"In Montana high beams must show people and vehicles 350 feet ahead, and low beams 100 feet ahead.","p":"Right. High beams reach 350 feet."},"es":{"q":"En Montana, ¿a qué distancia mínima adelante deben iluminar sus luces altas a personas y vehículos?","o":["100 pies","200 pies","1,000 pies","350 pies"],"h1":"Las luces bajas llegan a 100 pies; las altas llegan mucho más lejos.","h2":"En Montana, las luces altas deben mostrar personas y vehículos a 350 pies adelante, y las luces bajas a 100 pies.","p":"Correcto. Las luces altas llegan a 350 pies."},"ref":{"doc":"MT","page":14}},{"id":"mt-067","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you are driving at night behind another car going the same way. Within what distance must you dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is half the distance used for cars coming toward you.","h2":"In Montana you must dim your high beams when you are within 500 feet behind a vehicle you are following.","p":"Right. Dim them within 500 feet behind another car."},"es":{"q":"En Montana, usted maneja de noche detrás de otro carro que va en la misma dirección. ¿A qué distancia debe bajar sus luces altas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es la mitad de la distancia que se usa para los carros que vienen de frente.","h2":"En Montana, debe bajar las luces altas cuando está a 500 pies o menos detrás de un vehículo que sigue.","p":"Correcto. Bájelas a 500 pies detrás de otro carro."},"ref":{"doc":"MT","page":14}},{"id":"mt-068","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, during which hours must your headlights always be on?","o":["From sunset to sunrise","From 8 p.m. to 6 a.m.","From half an hour after sunset to half an hour before sunrise","Only when it rains"],"h1":"There is a half hour of twilight on each end.","h2":"In Montana headlights must be on from half an hour after sunset to half an hour before sunrise, and whenever you cannot see 500 feet ahead.","p":"Right. Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Montana, ¿en qué horario deben estar siempre encendidas sus luces delanteras?","o":["De la puesta del sol a la salida del sol","De 8 p.m. a 6 a.m.","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Solo cuando llueve"],"h1":"Hay media hora de crepúsculo en cada extremo.","h2":"En Montana, las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida del sol, y siempre que no pueda ver a 500 pies adelante.","p":"Correcto. De media hora después de la puesta a media hora antes de la salida del sol."},"ref":{"doc":"MT","page":14}},{"id":"mt-069","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, your brake lights must be visible from how far away in normal sunlight?","o":["50 feet","300 feet","1,000 feet","100 feet"],"h1":"It is the same distance as for turn signals.","h2":"In Montana brake lights must be visible from 300 feet away in normal sunlight.","p":"Right. Brake lights must show at 300 feet."},"es":{"q":"En Montana, ¿desde qué distancia deben verse sus luces de freno con luz normal del sol?","o":["50 pies","300 pies","1,000 pies","100 pies"],"h1":"Es la misma distancia que para las direccionales.","h2":"En Montana, las luces de freno deben verse desde 300 pies de distancia con luz normal del sol.","p":"Correcto. Las luces de freno deben verse a 300 pies."},"ref":{"doc":"MT","page":15}},{"id":"mt-070","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, a car horn must be loud enough to be heard from how far away?","o":["50 feet","500 feet","1,000 feet","200 feet"],"h1":"It is the same distance your rear mirror must let you see.","h2":"In Montana a car horn must be audible from at least 200 feet away.","p":"Right. The horn must be heard at 200 feet."},"es":{"q":"En Montana, ¿desde qué distancia debe poder oírse la bocina de un carro?","o":["50 pies","500 pies","1,000 pies","200 pies"],"h1":"Es la misma distancia que su espejo debe dejarle ver hacia atrás.","h2":"En Montana, la bocina de un carro debe poder oírse desde al menos 200 pies de distancia.","p":"Correcto. La bocina debe oírse a 200 pies."},"ref":{"doc":"MT","page":15}},{"id":"mt-071","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, during the day your load sticks out 4 feet or more past the back of your vehicle. What must you put on the end of it?","o":["A red flag at least 12 inches square","A white cloth of any size","A yellow light","Nothing in daylight"],"h1":"At night it would be a red light instead.","h2":"In Montana, when a load sticks out 4 feet or more, you must mark its end with a red flag at least 12 inches square in daylight, and a red light at night.","p":"Right. A red flag at least 12 inches square."},"es":{"q":"En Montana, de día su carga sobresale 4 pies o más por detrás de su vehículo. ¿Qué debe poner en el extremo?","o":["Una bandera roja de al menos 12 pulgadas por lado","Un trapo blanco de cualquier tamaño","Una luz amarilla","Nada durante el día"],"h1":"De noche sería una luz roja.","h2":"En Montana, cuando una carga sobresale 4 pies o más, debe marcar su extremo con una bandera roja de al menos 12 pulgadas por lado durante el día, y con una luz roja de noche.","p":"Correcto. Una bandera roja de al menos 12 pulgadas por lado."},"ref":{"doc":"MT","page":16}},{"id":"mt-072","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, which children must ride in a child safety seat?","o":["Only babies under 1 year","All children under 12","Children under 6 who weigh less than 60 pounds","Children under 4 feet tall only in the front seat"],"h1":"Think of an age and a weight together.","h2":"In Montana a child under 6 years old who weighs less than 60 pounds must be buckled into a child safety seat.","p":"Right. Under 6 and under 60 pounds."},"es":{"q":"En Montana, ¿qué niños deben ir en un asiento de seguridad infantil?","o":["Solo bebés menores de 1 año","Todos los niños menores de 12","Niños menores de 6 años que pesan menos de 60 libras","Niños de menos de 4 pies de estatura solo en el asiento delantero"],"h1":"Piense en una edad y un peso juntos.","h2":"En Montana, un niño menor de 6 años que pesa menos de 60 libras debe ir abrochado en un asiento de seguridad infantil.","p":"Correcto. Menor de 6 años y de menos de 60 libras."},"ref":{"doc":"MT","page":20}},{"id":"mt-073","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, children under what age should ride in the back seat whenever possible?","o":["Under 6","Under 13","Under 16","Under 2"],"h1":"It is the age when children become teenagers.","h2":"The Montana Driver Manual says that children under 13 should ride in the back seat whenever possible.","p":"Right. Children under 13 belong in the back seat."},"es":{"q":"En Montana, ¿los niños menores de qué edad deben ir en el asiento de atrás siempre que sea posible?","o":["Menores de 6","Menores de 13","Menores de 16","Menores de 2"],"h1":"Es la edad en que los niños se vuelven adolescentes.","h2":"El manual de Montana dice que los niños menores de 13 años deben ir en el asiento de atrás siempre que sea posible.","p":"Correcto. Los niños menores de 13 van atrás."},"ref":{"doc":"MT","page":20}},{"id":"mt-074","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, an older child has outgrown the child seat. Until about what height is a booster seat recommended?","o":["3 feet 6 inches","5 feet 6 inches","4 feet","4 feet 9 inches"],"h1":"It is when the car's lap and shoulder belt fit properly.","h2":"In Montana a booster seat is recommended until the car's lap and shoulder belt fits, usually when the child is about 4 feet 9 inches tall.","p":"Right. About 4 feet 9 inches."},"es":{"q":"En Montana, un niño mayor ya no cabe en el asiento infantil. ¿Hasta qué estatura aproximada se recomienda un asiento elevador (booster)?","o":["3 pies 6 pulgadas","5 pies 6 pulgadas","4 pies","4 pies 9 pulgadas"],"h1":"Es cuando el cinturón de regazo y hombro del carro le queda bien.","h2":"En Montana, se recomienda un asiento elevador hasta que el cinturón de regazo y hombro del carro le quede bien, por lo general cuando el niño mide unos 4 pies 9 pulgadas.","p":"Correcto. Unos 4 pies 9 pulgadas."},"ref":{"doc":"MT","page":20}},{"id":"mt-075","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, how low can a school zone speed limit be set?","o":["As low as 15 mph","No lower than 25 mph","No lower than 35 mph","As low as 5 mph"],"h1":"It is lower than the usual city limit of 25 mph.","h2":"In Montana school zone speed limits may be set as low as 15 mph.","p":"Right. As low as 15 mph."},"es":{"q":"En Montana, ¿qué tan bajo puede ser el límite de velocidad en una zona escolar?","o":["Tan bajo como 15 mph","No menos de 25 mph","No menos de 35 mph","Tan bajo como 5 mph"],"h1":"Es más bajo que el límite normal de 25 mph en la ciudad.","h2":"En Montana, los límites de velocidad en zonas escolares pueden ser tan bajos como 15 mph.","p":"Correcto. Tan bajo como 15 mph."},"ref":{"doc":"MT","page":29}},{"id":"mt-076","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, what happens to the fine for speeding in a school zone?","o":["It is the same as anywhere else","It is cut in half","It is doubled","There is no fine, only a warning"],"h1":"The same thing happens in work zones.","h2":"In Montana fines for speeding are doubled in all school zones.","p":"Right. School zone fines are doubled."},"es":{"q":"En Montana, ¿qué pasa con la multa por exceso de velocidad en una zona escolar?","o":["Es igual que en cualquier otro lugar","Se reduce a la mitad","Se duplica","No hay multa, solo una advertencia"],"h1":"Lo mismo pasa en las zonas de obras.","h2":"En Montana, las multas por exceso de velocidad se duplican en todas las zonas escolares.","p":"Correcto. Las multas en zonas escolares se duplican."},"ref":{"doc":"MT","page":29}},{"id":"mt-077","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, what is the speed limit in a highway work zone?","o":["Always 25 mph","Always 45 mph","10 mph below the normal limit","The limit set and posted for that zone"],"h1":"There is no single number for all work zones.","h2":"In Montana there is no standard work zone speed limit; the agency or contractor sets and posts a limit for each zone.","p":"Right. Each work zone has its own posted limit."},"es":{"q":"En Montana, ¿cuál es el límite de velocidad en una zona de obras en la carretera?","o":["Siempre 25 mph","Siempre 45 mph","10 mph menos que el límite normal","El límite fijado y señalado para esa zona"],"h1":"No hay un solo número para todas las zonas de obras.","h2":"En Montana no hay un límite estándar para las zonas de obras; la agencia o el contratista fija y señala un límite para cada zona.","p":"Correcto. Cada zona de obras tiene su propio límite señalado."},"ref":{"doc":"MT","page":28}},{"id":"mt-078","scope":"MT","cat":"signals","sign":null,"c":1,"en":{"q":"In Montana, you come to an intersection where the traffic lights are not working. What should you do?","o":["Drive through if no one is coming","Stop as if there were stop signs in all directions","Yield only to cars on your right","Honk and go"],"h1":"Treat it like an all-way stop.","h2":"In Montana, if a traffic signal is not working, you should stop as you would at stop signs in all directions.","p":"Right. Treat it as an all-way stop."},"es":{"q":"En Montana, llega a una intersección donde los semáforos no funcionan. ¿Qué debe hacer?","o":["Pasar si no viene nadie","Detenerse como si hubiera señales de alto en todas las direcciones","Ceder el paso solo a los carros de su derecha","Tocar la bocina y seguir"],"h1":"Trátela como un alto en todas las direcciones.","h2":"En Montana, si un semáforo no funciona, debe detenerse como lo haría ante señales de alto en todas las direcciones.","p":"Correcto. Trátela como un alto en todas las direcciones."},"ref":{"doc":"MT","page":30}},{"id":"mt-079","scope":"MT","cat":"signals","sign":null,"c":0,"en":{"q":"In Montana, when may you turn left on a red light after stopping?","o":["From a one-way street onto another one-way street, unless a sign forbids it","Never","At any intersection if no cars are coming","Only when a police officer waves you on"],"h1":"Both streets must go in only one direction.","h2":"In Montana you may turn left on red after a full stop when turning from a one-way street onto another one-way street, unless a sign says not to.","p":"Right. One-way onto one-way, after stopping."},"es":{"q":"En Montana, ¿cuándo puede girar a la izquierda con la luz roja después de detenerse?","o":["De una calle de un solo sentido a otra de un solo sentido, a menos que una señal lo prohíba","Nunca","En cualquier intersección si no vienen carros","Solo cuando un policía le hace señas"],"h1":"Las dos calles deben ser de un solo sentido.","h2":"En Montana, puede girar a la izquierda con luz roja, después de detenerse por completo, cuando pasa de una calle de un solo sentido a otra de un solo sentido, a menos que una señal lo prohíba.","p":"Correcto. De un solo sentido a un solo sentido, después de detenerse."},"ref":{"doc":"MT","page":30}},{"id":"mt-080","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, about how fast should you drive inside a roundabout?","o":["25 to 30 mph","The same speed as the road you came from","15 mph or less","35 mph"],"h1":"It is a slow, careful speed.","h2":"In Montana driving speeds in roundabouts are 15 mph or less.","p":"Right. 15 mph or less in a roundabout."},"es":{"q":"En Montana, ¿a qué velocidad aproximada debe manejar dentro de una glorieta?","o":["De 25 a 30 mph","A la misma velocidad de la calle de donde viene","A 15 mph o menos","A 35 mph"],"h1":"Es una velocidad lenta y cuidadosa.","h2":"En Montana, la velocidad dentro de las glorietas es de 15 mph o menos.","p":"Correcto. 15 mph o menos en una glorieta."},"ref":{"doc":"MT","page":32}},{"id":"mt-081","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, you must stop at a railroad crossing when an approaching train is within what distance of it?","o":["100 feet","500 feet","1 mile","1,500 feet"],"h1":"It is a little more than a quarter of a mile.","h2":"In Montana you must stop at a railroad crossing when a train is within 1,500 feet of it, even if no signal is working.","p":"Right. Stop when a train is within 1,500 feet."},"es":{"q":"En Montana, debe detenerse en un cruce de ferrocarril cuando un tren que se acerca está a cierta distancia. ¿Cuál es esa distancia?","o":["100 pies","500 pies","1 milla","1,500 pies"],"h1":"Es un poco más de un cuarto de milla.","h2":"En Montana, debe detenerse en un cruce de ferrocarril cuando un tren está a 1,500 pies o menos del cruce, aunque ninguna señal funcione.","p":"Correcto. Deténgase cuando un tren está a 1,500 pies o menos."},"ref":{"doc":"MT","page":33}},{"id":"mt-082","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, there is a solid yellow line on your side of the center. When may you cross it?","o":["To pass a slow truck","To turn left into a driveway or parking lot, when it is safe","Never, for any reason","Only at night"],"h1":"Passing is not allowed, but something else is.","h2":"In Montana you may cross a solid yellow line to turn into a driveway, parking lot or road when it is safe, but not to pass.","p":"Right. You may cross it to turn, not to pass."},"es":{"q":"En Montana, hay una línea amarilla continua de su lado del centro. ¿Cuándo puede cruzarla?","o":["Para rebasar un camión lento","Para girar a la izquierda hacia una entrada o un estacionamiento, cuando sea seguro","Nunca, por ningún motivo","Solo de noche"],"h1":"Rebasar no está permitido, pero otra cosa sí.","h2":"En Montana, puede cruzar una línea amarilla continua para girar hacia una entrada, un estacionamiento o una calle cuando sea seguro, pero no para rebasar.","p":"Correcto. Puede cruzarla para girar, no para rebasar."},"ref":{"doc":"MT","page":34}},{"id":"mt-083","scope":"MT","cat":"signals","sign":null,"c":2,"en":{"q":"In Montana, over a reversible lane you see a flashing yellow X. What does it mean?","o":["You may drive straight in this lane","The lane is closed","The lane is only for turning","The lane is for buses only"],"h1":"A steady yellow X means something different.","h2":"In Montana a flashing yellow X over a reversible lane means the lane may be used only for turning.","p":"Right. A flashing yellow X means turning only."},"es":{"q":"En Montana, sobre un carril reversible ve una X amarilla intermitente. ¿Qué significa?","o":["Puede seguir derecho en este carril","El carril está cerrado","El carril es solo para girar","El carril es solo para autobuses"],"h1":"Una X amarilla fija significa otra cosa.","h2":"En Montana, una X amarilla intermitente sobre un carril reversible significa que el carril solo se puede usar para girar.","p":"Correcto. Una X amarilla intermitente significa solo para girar."},"ref":{"doc":"MT","page":35}},{"id":"mt-084","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, on a road with three or more lanes going your way, which lane should you use when you are not passing?","o":["The right lane","The left lane","Any lane you like","The center lane always"],"h1":"The left lanes are for passing.","h2":"In Montana, on a road with three or more lanes in the same direction, you stay in the right lane except to pass; use the center lane if many cars are entering.","p":"Right. Stay in the right lane unless you are passing."},"es":{"q":"En Montana, en una carretera con tres o más carriles en su dirección, ¿qué carril debe usar cuando no está rebasando?","o":["El carril derecho","El carril izquierdo","El carril que prefiera","Siempre el carril del centro"],"h1":"Los carriles de la izquierda son para rebasar.","h2":"En Montana, en una carretera con tres o más carriles en la misma dirección, usted se mantiene en el carril derecho excepto para rebasar; use el del centro si entran muchos carros.","p":"Correcto. Manténgase en el carril derecho a menos que esté rebasando."},"ref":{"doc":"MT","page":37}},{"id":"mt-085","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, you plan to turn at a corner in town. How far before the turn must you signal?","o":["50 feet","300 feet","500 feet","100 feet"],"h1":"It is about one-third of a city block.","h2":"In Montana you must signal at least 100 feet before a turn in town, and 300 feet before a turn on rural roads.","p":"Right. Signal 100 feet before a turn in town."},"es":{"q":"En Montana, piensa girar en una esquina de la ciudad. ¿A qué distancia antes del giro debe poner la direccional?","o":["50 pies","300 pies","500 pies","100 pies"],"h1":"Es más o menos un tercio de una cuadra.","h2":"En Montana, debe poner la direccional al menos 100 pies antes de un giro en la ciudad, y 300 pies antes de un giro en caminos rurales.","p":"Correcto. Ponga la direccional 100 pies antes de girar en la ciudad."},"ref":{"doc":"MT","page":37}},{"id":"mt-086","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you reach your turn but you are in the wrong lane. What should you do?","o":["Turn anyway from the lane you are in","Go on, get into the proper lane, and turn at the next intersection","Stop and wait for a gap to change lanes","Back up to the turn"],"h1":"Do not make a last-second move.","h2":"In Montana, if you reach a turn in the wrong lane, you go on, get into the proper lane, and turn at the next intersection.","p":"Right. Go on and turn at the next intersection."},"es":{"q":"En Montana, llega a su giro pero está en el carril equivocado. ¿Qué debe hacer?","o":["Girar de todos modos desde su carril","Seguir, pasarse al carril correcto y girar en la siguiente intersección","Detenerse y esperar un espacio para cambiar de carril","Retroceder hasta el giro"],"h1":"No haga un movimiento de último segundo.","h2":"En Montana, si llega a un giro en el carril equivocado, sigue adelante, se pasa al carril correcto y gira en la siguiente intersección.","p":"Correcto. Siga y gire en la siguiente intersección."},"ref":{"doc":"MT","page":37}},{"id":"mt-087","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, to turn around on a road, how far must you be able to see clearly in both directions?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is almost two average city blocks.","h2":"In Montana you may turn around on a road only where you can see 500 feet clearly in both directions and no vehicles are coming.","p":"Right. You need 500 feet of clear view both ways."},"es":{"q":"En Montana, para dar la vuelta en una calle, ¿qué distancia debe poder ver con claridad en ambas direcciones?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Son casi dos cuadras normales.","h2":"En Montana, puede dar la vuelta en una calle solo donde pueda ver 500 pies con claridad en ambas direcciones y no vengan vehículos.","p":"Correcto. Necesita 500 pies de vista libre en ambos sentidos."},"ref":{"doc":"MT","page":39}},{"id":"mt-088","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, a person with a white cane or a guide dog is crossing the street ahead. What should you do?","o":["Give the person the right-of-way and do not honk","Honk so the person knows you are there","Drive around the person slowly","Go first if you have a green light"],"h1":"Your horn could scare or confuse the person.","h2":"In Montana a pedestrian with a white cane or guide dog has absolute right-of-way, and you should not use your horn.","p":"Right. Let the person go and do not honk."},"es":{"q":"En Montana, una persona con bastón blanco o perro guía cruza la calle adelante. ¿Qué debe hacer?","o":["Cederle el paso y no tocar la bocina","Tocar la bocina para que sepa que usted está ahí","Pasar despacio por un lado","Pasar primero si tiene luz verde"],"h1":"Su bocina podría asustar o confundir a la persona.","h2":"En Montana, un peatón con bastón blanco o perro guía tiene derecho de paso absoluto, y usted no debe usar la bocina.","p":"Correcto. Déjela pasar y no toque la bocina."},"ref":{"doc":"MT","page":39}},{"id":"mt-089","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, you are in the middle of an intersection when an ambulance with a siren comes up behind you. What should you do?","o":["Stop right where you are","Back up out of the intersection","Speed up to stay ahead of it","Drive through the intersection, then pull to the right and stop"],"h1":"Do not stop inside the intersection.","h2":"In Montana, if you are in an intersection when an emergency vehicle comes, you drive through it first, then pull to the right and stop.","p":"Right. Clear the intersection, then pull over."},"es":{"q":"En Montana, está en medio de una intersección cuando una ambulancia con sirena se acerca por detrás. ¿Qué debe hacer?","o":["Detenerse donde está","Retroceder para salir de la intersección","Acelerar para mantenerse delante","Cruzar la intersección y luego orillarse a la derecha y detenerse"],"h1":"No se detenga dentro de la intersección.","h2":"En Montana, si está en una intersección cuando llega un vehículo de emergencia, primero la cruza y luego se orilla a la derecha y se detiene.","p":"Correcto. Salga de la intersección y luego oríllese."},"ref":{"doc":"MT","page":40}},{"id":"mt-090","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, a school bus ahead is stopped with red lights flashing. How far from the bus must you stop?","o":["At least 10 feet","At least 30 feet","At least 100 feet","Right behind its bumper"],"h1":"It is the same distance as parking from a stop sign.","h2":"In Montana you must stop at least 30 feet from a school bus with flashing red lights and wait until the lights go off.","p":"Right. Stop at least 30 feet away."},"es":{"q":"En Montana, un autobús escolar adelante está detenido con luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 10 pies","Al menos a 30 pies","Al menos a 100 pies","Justo detrás de su parachoques"],"h1":"Es la misma distancia que para estacionarse lejos de una señal de alto.","h2":"En Montana, debe detenerse al menos a 30 pies de un autobús escolar con luces rojas intermitentes y esperar hasta que se apaguen.","p":"Correcto. Deténgase al menos a 30 pies."},"ref":{"doc":"MT","page":40}},{"id":"mt-091","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, a school bus ahead shows flashing yellow lights. What should you do?","o":["Stop at least 30 feet away","Pass it quickly before it stops","Slow down and go on carefully; it is about to stop","Nothing; yellow lights are only for other buses"],"h1":"Yellow lights come before the red lights.","h2":"In Montana, when a school bus shows flashing yellow lights, you slow down and go on carefully, because it is about to stop and children may be in the road.","p":"Right. Slow down and be ready to stop."},"es":{"q":"En Montana, un autobús escolar adelante muestra luces amarillas intermitentes. ¿Qué debe hacer?","o":["Detenerse al menos a 30 pies","Rebasarlo rápido antes de que pare","Reducir la velocidad y seguir con cuidado; está por detenerse","Nada; las luces amarillas son solo para otros autobuses"],"h1":"Las luces amarillas vienen antes de las rojas.","h2":"En Montana, cuando un autobús escolar muestra luces amarillas intermitentes, usted reduce la velocidad y sigue con cuidado, porque está por detenerse y puede haber niños en la calle.","p":"Correcto. Reduzca la velocidad y esté listo para parar."},"ref":{"doc":"MT","page":40}},{"id":"mt-092","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, you are driving in a funeral procession on a highway with a 70 mph limit. What is the fastest you may drive?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is a well-known older highway limit.","h2":"In Montana a vehicle in a funeral procession may not go faster than 55 mph on a highway where the limit is 55 mph or more.","p":"Right. No faster than 55 mph."},"es":{"q":"En Montana, usted va en un cortejo fúnebre por una carretera con límite de 70 mph. ¿Cuál es la velocidad máxima a la que puede ir?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es un conocido límite antiguo de carretera.","h2":"En Montana, un vehículo en un cortejo fúnebre no puede ir a más de 55 mph en una carretera cuyo límite es de 55 mph o más.","p":"Correcto. No más de 55 mph."},"ref":{"doc":"MT","page":42}},{"id":"mt-093","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, you pass a bicycle rider on a two-lane highway with no oncoming traffic. How much space does the manual recommend?","o":["1 foot","2 feet","3 feet","5 feet"],"h1":"Cross the center line to give this space.","h2":"The Montana Driver Manual recommends crossing the center line, when no one is coming, to give a bicycle rider five feet of space.","p":"Right. Give the rider five feet."},"es":{"q":"En Montana, usted rebasa a un ciclista en una carretera de dos carriles sin tráfico en sentido contrario. ¿Cuánto espacio recomienda el manual?","o":["1 pie","2 pies","3 pies","5 pies"],"h1":"Cruce la línea central para dar este espacio.","h2":"El manual de Montana recomienda cruzar la línea central, cuando no viene nadie, para darle al ciclista cinco pies de espacio.","p":"Correcto. Dele cinco pies al ciclista."},"ref":{"doc":"MT","page":43}},{"id":"mt-094","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you park next to a curb. How close to the curb must your vehicle be?","o":["Within 6 inches","Within 18 inches","Within 3 feet","Within 5 feet"],"h1":"It is one and a half feet.","h2":"In Montana a parked vehicle must be within 18 inches of the curb or shoulder.","p":"Right. Within 18 inches of the curb."},"es":{"q":"En Montana, se estaciona junto a la banqueta. ¿Qué tan cerca de la banqueta debe quedar su vehículo?","o":["A menos de 6 pulgadas","A menos de 18 pulgadas","A menos de 3 pies","A menos de 5 pies"],"h1":"Es un pie y medio.","h2":"En Montana, un vehículo estacionado debe quedar a 18 pulgadas o menos de la banqueta o del acotamiento.","p":"Correcto. A 18 pulgadas o menos de la banqueta."},"ref":{"doc":"MT","page":44}},{"id":"mt-095","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, how close may you park to a crosswalk at an intersection?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"It is more than the 15 feet for a fire hydrant.","h2":"In Montana you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Montana, ¿qué tan cerca puede estacionarse de un cruce peatonal en una intersección?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 50 pies"],"h1":"Es más que los 15 pies de un hidrante.","h2":"En Montana, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese al menos a 20 pies del cruce peatonal."},"ref":{"doc":"MT","page":46}},{"id":"mt-096","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, you want to park across the street from a fire station driveway. How far from the driveway must you stay?","o":["At least 75 feet","At least 20 feet","At least 15 feet","At least 30 feet"],"h1":"On the same side it is 20 feet; across the street it is much more.","h2":"In Montana you may not park within 75 feet of a fire station driveway on the other side of the street, or within 20 feet on the same side.","p":"Right. Stay at least 75 feet away across the street."},"es":{"q":"En Montana, quiere estacionarse en la acera de enfrente de la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe quedarse?","o":["Al menos a 75 pies","Al menos a 20 pies","Al menos a 15 pies","Al menos a 30 pies"],"h1":"Del mismo lado son 20 pies; enfrente es mucho más.","h2":"En Montana, no puede estacionarse a menos de 75 pies de la entrada de una estación de bomberos en el lado opuesto de la calle, ni a menos de 20 pies en el mismo lado.","p":"Correcto. Quédese al menos a 75 pies en el lado opuesto."},"ref":{"doc":"MT","page":46}},{"id":"mt-097","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, what does a white curb mean?","o":["No stopping at any time","Parking for up to two hours","Loading of goods only, and you must stay with the car","Stop only to pick up or drop off passengers"],"h1":"Yellow is for loading goods; red means no stopping.","h2":"In Montana a white curb means you may stop only to pick up or drop off passengers.","p":"Right. A white curb is for picking up or dropping off passengers."},"es":{"q":"En Montana, ¿qué significa una banqueta pintada de blanco?","o":["No se puede parar nunca","Estacionamiento hasta por dos horas","Solo carga de mercancía, y debe quedarse con el carro","Parar solo para subir o bajar pasajeros"],"h1":"El amarillo es para cargar mercancía; el rojo significa no parar.","h2":"En Montana, una banqueta blanca significa que solo puede parar para subir o bajar pasajeros.","p":"Correcto. La banqueta blanca es para subir o bajar pasajeros."},"ref":{"doc":"MT","page":46}},{"id":"mt-098","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, you are convicted a second time of driving without insurance. Besides a fine, what happens to the plates and registration of the car you drove?","o":["Nothing else happens","You must hand them in; after you show insurance, the car may be used only for work for 90 days","They are suspended for 10 years","The car can never be registered again"],"h1":"For a third offense the work-only period is 180 days.","h2":"In Montana a second conviction for driving without insurance means you must hand in the car's plates and registration, and after you show proof of insurance the car may be used only for work for 90 days.","p":"Right. You hand in the plates and registration, and the car is for work use only for 90 days."},"es":{"q":"En Montana, lo condenan por segunda vez por manejar sin seguro. Además de la multa, ¿qué pasa con las placas y el registro del carro que manejaba?","o":["No pasa nada más","Debe entregarlos; después de mostrar su seguro, el carro solo se puede usar para trabajar durante 90 días","Se suspenden por 10 años","El carro nunca se puede volver a registrar"],"h1":"Para una tercera vez, el período de uso solo para trabajar es de 180 días.","h2":"En Montana, una segunda condena por manejar sin seguro significa que usted debe entregar las placas y el registro del carro, y después de mostrar prueba de seguro el carro solo se puede usar para trabajar durante 90 días.","p":"Correcto. Usted entrega las placas y el registro, y el carro solo se usa para trabajar durante 90 días."},"ref":{"doc":"MT","page":null}},{"id":"mt-099","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, the road is covered with packed snow. How much should you slow down?","o":["About 5 mph","About 10 mph","Cut your speed in half","You do not need to slow down with good tires"],"h1":"On a wet road it is about 10 mph; snow needs much more.","h2":"The Montana Driver Manual says to cut your speed in half on packed snow.","p":"Right. Cut your speed in half on packed snow."},"es":{"q":"En Montana, la carretera está cubierta de nieve compacta. ¿Cuánto debe reducir la velocidad?","o":["Unas 5 mph","Unas 10 mph","A la mitad de su velocidad","No necesita reducirla si tiene buenas llantas"],"h1":"En una carretera mojada son unas 10 mph; la nieve necesita mucho más.","h2":"El manual de Montana dice que debe reducir su velocidad a la mitad sobre nieve compacta.","p":"Correcto. Reduzca su velocidad a la mitad sobre nieve compacta."},"ref":{"doc":"MT","page":60}},{"id":"mt-100","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, in normal conditions, what is the least following distance the manual tells you to keep behind the car ahead?","o":["Three seconds","One second","Two car lengths","Ten seconds"],"h1":"Count \"one-one-thousand\" after the car ahead passes a sign.","h2":"The Montana Driver Manual says to follow no closer than three seconds behind the car ahead, and more in bad conditions.","p":"Right. Keep at least three seconds."},"es":{"q":"En Montana, en condiciones normales, ¿cuál es la distancia mínima de seguimiento que el manual le indica dejar detrás del carro de adelante?","o":["Tres segundos","Un segundo","Dos largos de carro","Diez segundos"],"h1":"Cuente \"mil uno\" después de que el carro de adelante pase una señal.","h2":"El manual de Montana dice que no debe seguir a menos de tres segundos detrás del carro de adelante, y más en malas condiciones.","p":"Correcto. Deje al menos tres segundos."},"ref":{"doc":"MT","page":64}},{"id":"mt-101","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, where in a car with a trunk may an open bottle of alcohol be carried?","o":["In a cup holder","Under the driver's seat","On the back seat","In the trunk or a locked glove compartment"],"h1":"It must be out of reach of the people riding.","h2":"In Montana an open alcohol container must be kept in the trunk, a locked glove compartment or another area where people do not ride.","p":"Right. In the trunk or a locked glove compartment."},"es":{"q":"En Montana, en un carro con cajuela, ¿dónde se puede llevar una botella de alcohol abierta?","o":["En un portavasos","Debajo del asiento del conductor","En el asiento de atrás","En la cajuela o en una guantera cerrada con llave"],"h1":"Debe estar fuera del alcance de las personas que viajan.","h2":"En Montana, un envase de alcohol abierto debe ir en la cajuela, en una guantera cerrada con llave o en otra área donde no viajan personas.","p":"Correcto. En la cajuela o en una guantera cerrada con llave."},"ref":{"doc":"MT","page":72}},{"id":"mt-102","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, when must you have your driver license with you?","o":["Only on long trips","Only when driving outside your home county","Whenever you drive","Only at night"],"h1":"Police may ask to see it at any traffic stop.","h2":"In Montana you must have your valid driver license with you at all times when you drive.","p":"Right. Carry your license every time you drive."},"es":{"q":"En Montana, ¿cuándo debe llevar consigo su licencia de manejar?","o":["Solo en viajes largos","Solo cuando maneja fuera de su condado","Siempre que maneje","Solo de noche"],"h1":"La policía puede pedirla en cualquier parada de tráfico.","h2":"En Montana, usted debe llevar su licencia de manejar válida en todo momento cuando maneja.","p":"Correcto. Lleve su licencia cada vez que maneje."},"ref":{"doc":"MT","page":1}},{"id":"mt-103","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, what do you need on your license to ride a motor scooter on public roads?","o":["A motorcycle endorsement","Nothing extra; a Class D license is enough","A commercial license (CDL)","A moped sticker from the county"],"h1":"The same add-on is needed to ride a motorcycle.","h2":"In Montana you need a motorcycle endorsement on your license to ride a motorcycle or a motor scooter.","p":"Right. A motor scooter needs a motorcycle endorsement."},"es":{"q":"En Montana, ¿qué necesita en su licencia para conducir una motoneta (motor scooter) en vías públicas?","o":["Un endoso de motocicleta","Nada más; basta con una licencia Clase D","Una licencia comercial (CDL)","Una calcomanía de ciclomotor del condado"],"h1":"Lo mismo se necesita para conducir una motocicleta.","h2":"En Montana, usted necesita un endoso de motocicleta en su licencia para conducir una motocicleta o una motoneta.","p":"Correcto. Una motoneta requiere un endoso de motocicleta."},"ref":{"doc":"MT","page":1}},{"id":"mt-104","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a student has a Traffic Education Permit (TEP). When may the student drive with it?","o":["Any time with a parent","Alone, during daylight","With any licensed adult over 21","Only during the traffic education course, with a traffic education instructor"],"h1":"This permit is tied to the class the student is taking.","h2":"In Montana a Traffic Education Permit is valid only while the student is in the course, and only with a traffic education instructor supervising.","p":"Right. A TEP is only for driving in the course, with the instructor."},"es":{"q":"En Montana, un estudiante tiene un Permiso de Educación Vial (TEP). ¿Cuándo puede manejar con él?","o":["En cualquier momento con uno de sus padres","Solo, durante el día","Con cualquier adulto con licencia mayor de 21 años","Solo durante el curso de educación vial, con un instructor de educación vial"],"h1":"Este permiso está ligado a la clase que toma el estudiante.","h2":"En Montana, un Permiso de Educación Vial solo es válido mientras el estudiante está en el curso, y solo con la supervisión de un instructor de educación vial.","p":"Correcto. El TEP es solo para manejar en el curso, con el instructor."},"ref":{"doc":"MT","page":2}},{"id":"mt-105","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, a teen finished an online traffic education course. Can it be used to get a learner license early?","o":["Yes, if the teen passed the online test","No, online courses are not approved","Yes, but only after age 15","Only if a parent signs a form"],"h1":"The course must be approved by the state; local schools usually offer it.","h2":"In Montana, online and third-party traffic education courses are not approved, so they do not count toward an early learner license.","p":"Right. Online courses are not approved."},"es":{"q":"En Montana, un adolescente terminó un curso de educación vial en línea. ¿Le sirve para obtener antes la licencia de aprendiz?","o":["Sí, si aprobó el examen en línea","No, los cursos en línea no están aprobados","Sí, pero solo después de los 15 años","Solo si uno de sus padres firma un formulario"],"h1":"El curso debe estar aprobado por el estado; normalmente lo ofrecen las escuelas locales.","h2":"En Montana, los cursos de educación vial en línea o de terceros no están aprobados, así que no cuentan para una licencia de aprendiz temprana.","p":"Correcto. Los cursos en línea no están aprobados."},"ref":{"doc":"MT","page":2}},{"id":"mt-106","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you are a new resident with a valid license from another state, and you have it with you. What must you do to exchange it for a Montana license?","o":["Take the written test and the road test","Take only the road test","Take a traffic education course","Exchange it; usually no written or road test is needed"],"h1":"Montana accepts the driving skills you already proved in your old state.","h2":"In Montana a new resident with a valid out-of-state license in hand can exchange it for a Montana license without a written or road test, unless there is a concern about their ability to drive safely.","p":"Right. A valid out-of-state license can usually be exchanged without the written or road test."},"es":{"q":"En Montana, usted es nuevo residente con una licencia válida de otro estado y la tiene consigo. ¿Qué debe hacer para cambiarla por una licencia de Montana?","o":["Tomar el examen escrito y el examen de manejo","Tomar solo el examen de manejo","Tomar un curso de educación vial","Cambiarla; por lo general no necesita examen escrito ni de manejo"],"h1":"Montana acepta las habilidades que usted ya demostró en su otro estado.","h2":"En Montana, un nuevo residente con una licencia válida de otro estado en mano puede cambiarla por una de Montana sin examen escrito ni de manejo, a menos que haya dudas sobre su capacidad para manejar con seguridad.","p":"Correcto. Por lo general se cambia sin examen escrito ni de manejo."},"ref":{"doc":"MT","page":3}},{"id":"mt-107","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, your license is suspended in another state. Can you get a Montana license?","o":["No, not while it is suspended or revoked anywhere","Yes, Montana does not check other states","Yes, if you pass all the tests again","Yes, but only a learner license"],"h1":"A suspension in one state follows you to the others.","h2":"In Montana you cannot apply for, get, or keep a driver license while your license is suspended or revoked in any other state.","p":"Right. A suspension anywhere blocks a Montana license."},"es":{"q":"En Montana, su licencia está suspendida en otro estado. ¿Puede obtener una licencia de Montana?","o":["No, mientras esté suspendida o revocada en cualquier lugar","Sí, Montana no revisa otros estados","Sí, si aprueba todos los exámenes otra vez","Sí, pero solo una licencia de aprendiz"],"h1":"Una suspensión en un estado lo sigue a los demás.","h2":"En Montana, usted no puede solicitar, obtener ni mantener una licencia de manejar mientras su licencia esté suspendida o revocada en cualquier otro estado.","p":"Correcto. Una suspensión en cualquier lugar impide tener licencia de Montana."},"ref":{"doc":"MT","page":3}},{"id":"mt-108","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, a service member's license has the military exemption. How long after an honorable discharge may they keep driving on it?","o":["10 days","30 days","90 days","1 year"],"h1":"It is about three months.","h2":"In Montana a license with the military exemption stays valid for 90 days after an honorable discharge.","p":"Right. It is valid for 90 days after discharge."},"es":{"q":"En Montana, la licencia de un militar tiene la exención militar. ¿Cuánto tiempo después de una baja honorable puede seguir manejando con ella?","o":["10 días","30 días","90 días","1 año"],"h1":"Son unos tres meses.","h2":"En Montana, una licencia con exención militar sigue válida 90 días después de una baja honorable.","p":"Correcto. Es válida 90 días después de la baja."},"ref":{"doc":"MT","page":4}},{"id":"mt-109","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, how many documents must you show to prove your full legal name and date of birth?","o":["One primary document only","Two: two primary, or one primary and one secondary","Three secondary documents","Two secondary documents"],"h1":"At least one of them must be a primary document, like a birth certificate or passport.","h2":"In Montana you must show two documents for your name and birth date: either two primary documents, or one primary and one secondary.","p":"Right. Two documents, at least one of them primary."},"es":{"q":"En Montana, ¿cuántos documentos debe mostrar para probar su nombre legal completo y su fecha de nacimiento?","o":["Solo un documento principal","Dos: dos principales, o uno principal y uno secundario","Tres documentos secundarios","Dos documentos secundarios"],"h1":"Al menos uno debe ser un documento principal, como un acta de nacimiento o un pasaporte.","h2":"En Montana, debe mostrar dos documentos para su nombre y fecha de nacimiento: dos documentos principales, o uno principal y uno secundario.","p":"Correcto. Dos documentos, al menos uno principal."},"ref":{"doc":"MT","page":5}},{"id":"mt-110","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, a teen with a learner license wants a first-year restricted license. What must be true for the six months before?","o":["The teen drove at least 100 hours","The teen took a second written test","The teen drove only in daylight","No traffic violations and no alcohol or drug offenses"],"h1":"It is about the teen's driving record.","h2":"In Montana a teen must have no traffic violations and no alcohol or drug offenses in the six months before moving up to a first-year restricted license.","p":"Right. A clean record for six months."},"es":{"q":"En Montana, un adolescente con licencia de aprendiz quiere la licencia restringida del primer año. ¿Qué debe cumplirse en los seis meses anteriores?","o":["Haber manejado al menos 100 horas","Haber tomado un segundo examen escrito","Haber manejado solo de día","Ninguna infracción de tránsito ni delito de alcohol o drogas"],"h1":"Tiene que ver con el historial de manejo del adolescente.","h2":"En Montana, un adolescente no debe tener infracciones de tránsito ni delitos de alcohol o drogas en los seis meses antes de pasar a la licencia restringida del primer año.","p":"Correcto. Un historial limpio por seis meses."},"ref":{"doc":"MT","page":7}},{"id":"mt-111","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, your license expired two weeks ago. May you still drive?","o":["No, an expired license is not valid for driving","Yes, there is a 3-month grace period for driving","Yes, but only in your home county","Yes, if you carry your renewal form"],"h1":"The 3 months after it expires are only for renewing without new tests.","h2":"In Montana an expired license is not valid for driving; you can renew within 3 months without retesting, but you may not drive until you renew.","p":"Right. You may not drive on an expired license."},"es":{"q":"En Montana, su licencia venció hace dos semanas. ¿Todavía puede manejar?","o":["No, una licencia vencida no es válida para manejar","Sí, hay un período de gracia de 3 meses para manejar","Sí, pero solo en su condado","Sí, si lleva su formulario de renovación"],"h1":"Los 3 meses después del vencimiento son solo para renovar sin exámenes nuevos.","h2":"En Montana, una licencia vencida no es válida para manejar; puede renovarla dentro de 3 meses sin volver a hacer los exámenes, pero no puede manejar hasta renovarla.","p":"Correcto. No puede manejar con una licencia vencida."},"ref":{"doc":"MT","page":9}},{"id":"mt-112","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, you renew your license in person at an exam station. Which test must you pass?","o":["The written test","The road test","The vision test","No test at all"],"h1":"It checks how well you see.","h2":"In Montana you must pass the vision test and have a new photo taken when you renew your license in person.","p":"Right. You pass a vision test when you renew."},"es":{"q":"En Montana, usted renueva su licencia en persona en una estación de exámenes. ¿Qué examen debe aprobar?","o":["El examen escrito","El examen de manejo","El examen de la vista","Ningún examen"],"h1":"Revisa qué tan bien ve usted.","h2":"En Montana, debe aprobar el examen de la vista y tomarse una foto nueva cuando renueva su licencia en persona.","p":"Correcto. Al renovar, se aprueba un examen de la vista."},"ref":{"doc":"MT","page":9}},{"id":"mt-113","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, your low beam headlights must light up people and vehicles at least how far ahead?","o":["50 feet","100 feet","350 feet","500 feet"],"h1":"It is much shorter than the 350 feet of your high beams.","h2":"In Montana low beam headlights must show people and vehicles at least 100 feet ahead.","p":"Right. Low beams reach at least 100 feet."},"es":{"q":"En Montana, ¿a qué distancia mínima adelante deben iluminar sus luces bajas a personas y vehículos?","o":["50 pies","100 pies","350 pies","500 pies"],"h1":"Es mucho menos que los 350 pies de las luces altas.","h2":"En Montana, las luces bajas deben mostrar personas y vehículos al menos a 100 pies adelante.","p":"Correcto. Las luces bajas alcanzan al menos 100 pies."},"ref":{"doc":"MT","page":14}},{"id":"mt-114","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, you stop or park on the roadway at night. What lights must your car show?","o":["No lights; turn everything off","Only the hazard flashers","High beams","Parking lights that can be seen from 500 feet"],"h1":"They are white or amber in front and red in back.","h2":"In Montana a car parked or stopped on the roadway when headlights are required must show parking lights that can be seen from 500 feet.","p":"Right. Parking lights visible from 500 feet."},"es":{"q":"En Montana, usted se detiene o se estaciona en la vía de noche. ¿Qué luces debe mostrar su carro?","o":["Ninguna; apague todo","Solo las luces intermitentes de emergencia","Las luces altas","Luces de estacionamiento visibles desde 500 pies"],"h1":"Son blancas o ámbar adelante y rojas atrás.","h2":"En Montana, un carro estacionado o detenido en la vía cuando se requieren faros debe mostrar luces de estacionamiento visibles desde 500 pies.","p":"Correcto. Luces de estacionamiento visibles desde 500 pies."},"ref":{"doc":"MT","page":15}},{"id":"mt-115","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, which of these is an exception to the seat belt law?","o":["A vehicle made before January 1, 1968","A trip of less than 5 miles","Driving under 25 mph","An adult riding in the back seat"],"h1":"Older cars were not built with belts for every seat.","h2":"In Montana the seat belt law does not apply to a vehicle made before January 1, 1968.","p":"Right. Vehicles made before 1968 are an exception."},"es":{"q":"En Montana, ¿cuál de estas es una excepción a la ley del cinturón de seguridad?","o":["Un vehículo fabricado antes del 1 de enero de 1968","Un viaje de menos de 5 millas","Manejar a menos de 25 mph","Un adulto que viaja en el asiento de atrás"],"h1":"Los carros más viejos no se fabricaban con cinturones para cada asiento.","h2":"En Montana, la ley del cinturón de seguridad no se aplica a un vehículo fabricado antes del 1 de enero de 1968.","p":"Correcto. Los vehículos fabricados antes de 1968 son una excepción."},"ref":{"doc":"MT","page":20}},{"id":"mt-116","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, at night your load sticks out 4 feet or more past the back of your vehicle. What must be on the end of it?","o":["A white reflector","An orange flag","A red light that can be seen from 500 feet","Nothing, if your taillights work"],"h1":"In daytime a red flag is used; at night you need something that shines.","h2":"In Montana, when headlights are required, a load sticking out 4 feet or more must have a red light on its end that can be seen from 500 feet.","p":"Right. A red light visible from 500 feet."},"es":{"q":"En Montana, de noche su carga sobresale 4 pies o más por detrás de su vehículo. ¿Qué debe llevar en la punta?","o":["Un reflector blanco","Una bandera anaranjada","Una luz roja visible desde 500 pies","Nada, si sus luces traseras funcionan"],"h1":"De día se usa una bandera roja; de noche hace falta algo que alumbre.","h2":"En Montana, cuando se requieren faros, una carga que sobresale 4 pies o más debe llevar en la punta una luz roja visible desde 500 pies.","p":"Correcto. Una luz roja visible desde 500 pies."},"ref":{"doc":"MT","page":16}},{"id":"mt-117","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, you see an orange triangle with a red border on the back of a vehicle. What does it tell you?","o":["The vehicle carries hazardous materials","The vehicle normally goes 25 mph or less","The driver is a student","The vehicle is about to turn"],"h1":"Farm tractors and animal-drawn wagons carry this sign.","h2":"In Montana an orange triangle with a red border is the slow-moving vehicle emblem, used on vehicles that normally go 25 mph or less.","p":"Right. It marks a vehicle that normally goes 25 mph or less."},"es":{"q":"En Montana, usted ve un triángulo anaranjado con borde rojo en la parte de atrás de un vehículo. ¿Qué le indica?","o":["El vehículo lleva materiales peligrosos","El vehículo normalmente va a 25 mph o menos","El conductor es un estudiante","El vehículo está por dar vuelta"],"h1":"Los tractores agrícolas y las carretas tiradas por animales llevan esta señal.","h2":"En Montana, un triángulo anaranjado con borde rojo es el emblema de vehículo lento, que usan los vehículos que normalmente van a 25 mph o menos.","p":"Correcto. Marca un vehículo que normalmente va a 25 mph o menos."},"ref":{"doc":"MT","page":18}},{"id":"mt-118","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, you are driving a slow farm vehicle and cars are lining up behind you. When must you turn off the road to let them pass?","o":["Only if a police officer tells you","When 10 or more vehicles are behind you","Never; they must wait","When 4 or more vehicles are held up and there is a safe place to pull off"],"h1":"It is a small number of cars.","h2":"In Montana a slow-moving vehicle must turn off the road at a safe turnout when 4 or more vehicles are held up behind it.","p":"Right. Pull off when 4 or more vehicles are held up."},"es":{"q":"En Montana, usted maneja un vehículo agrícola lento y se forma una fila de carros detrás. ¿Cuándo debe salirse del camino para dejarlos pasar?","o":["Solo si un policía se lo indica","Cuando hay 10 o más vehículos detrás","Nunca; ellos deben esperar","Cuando 4 o más vehículos van detenidos y hay un lugar seguro para salirse"],"h1":"Es un número pequeño de carros.","h2":"En Montana, un vehículo lento debe salirse del camino en un lugar seguro cuando 4 o más vehículos van detenidos detrás de él.","p":"Correcto. Sálgase cuando 4 o más vehículos van detenidos."},"ref":{"doc":"MT","page":62}},{"id":"mt-119","scope":"MT","cat":"signals","sign":null,"c":0,"en":{"q":"In Montana, a work zone barricade has diagonal stripes that slope down to the right. Which way should you go?","o":["Bear to the right","Bear to the left","Stop and wait for a flagger","Go straight through"],"h1":"Follow the direction the stripes slope down toward.","h2":"In Montana barricade stripes that slope down to the right mean you should bear to the right.","p":"Right. Stripes sloping down to the right mean bear right."},"es":{"q":"En Montana, una barricada en una zona de obras tiene franjas diagonales que bajan hacia la derecha. ¿Hacia dónde debe ir?","o":["Hacia la derecha","Hacia la izquierda","Detenerse y esperar a un abanderado","Seguir derecho a través de ella"],"h1":"Siga la dirección hacia donde bajan las franjas.","h2":"En Montana, las franjas de una barricada que bajan hacia la derecha significan que debe desviarse hacia la derecha.","p":"Correcto. Franjas que bajan a la derecha: desvíese a la derecha."},"ref":{"doc":"MT","page":27}},{"id":"mt-120","scope":"MT","cat":"signals","sign":null,"c":1,"en":{"q":"In Montana, you are stopped at a steady red light and want to turn right onto a two-way street. What may you do?","o":["Wait for the green light no matter what","Turn right after a full stop, unless a sign or officer forbids it, yielding to others","Turn right without stopping if no one is coming","Turn right only on a green arrow"],"h1":"Montana allows this turn after you stop.","h2":"In Montana you may turn right on a steady red light after a full stop, unless a sign or police officer says not to, and you must yield to pedestrians, bicyclists and traffic.","p":"Right. Stop first, then turn right if it is allowed and safe."},"es":{"q":"En Montana, usted está detenido ante una luz roja fija y quiere dar vuelta a la derecha hacia una calle de doble sentido. ¿Qué puede hacer?","o":["Esperar la luz verde pase lo que pase","Dar vuelta a la derecha después de un alto total, salvo que una señal o un policía lo prohíba, cediendo el paso","Dar vuelta a la derecha sin parar si no viene nadie","Dar vuelta a la derecha solo con flecha verde"],"h1":"Montana permite esta vuelta después de detenerse.","h2":"En Montana, puede dar vuelta a la derecha con luz roja fija después de un alto total, salvo que una señal o un policía lo prohíba, y debe ceder el paso a peatones, ciclistas y tráfico.","p":"Correcto. Primero haga alto y luego dé vuelta a la derecha si está permitido y es seguro."},"ref":{"doc":"MT","page":30}},{"id":"mt-121","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, you are inside a single-lane roundabout behind a slow car. What should you do?","o":["Pass it on the left","Pass it on the right","Honk so it speeds up","Stay behind it; never pass in a single-lane roundabout"],"h1":"There is only one lane, and speeds are low.","h2":"In Montana you must never pass or overtake another vehicle after entering a single-lane roundabout.","p":"Right. Never pass in a single-lane roundabout."},"es":{"q":"En Montana, usted está dentro de una glorieta de un solo carril detrás de un carro lento. ¿Qué debe hacer?","o":["Rebasarlo por la izquierda","Rebasarlo por la derecha","Tocar el claxon para que acelere","Quedarse detrás; nunca rebase en una glorieta de un solo carril"],"h1":"Hay un solo carril y las velocidades son bajas.","h2":"En Montana, nunca debe rebasar a otro vehículo después de entrar a una glorieta de un solo carril.","p":"Correcto. Nunca rebase en una glorieta de un solo carril."},"ref":{"doc":"MT","page":32}},{"id":"mt-122","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you drive a car with a manual transmission over railroad tracks. What does the driver manual advise?","o":["Do not shift gears while crossing, in case you stall","Shift to a lower gear in the middle of the tracks","Shift to neutral and coast across","Shift up to cross faster"],"h1":"Think about what could make the engine stop on the tracks.","h2":"In Montana the driver manual advises not to shift gears while crossing railroad tracks, in case the vehicle stalls.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"En Montana, usted maneja un carro de transmisión manual y cruza unas vías del tren. ¿Qué aconseja el manual?","o":["No cambiar de velocidad mientras cruza, por si el motor se apaga","Bajar de velocidad en medio de las vías","Poner neutral y cruzar sin acelerar","Subir de velocidad para cruzar más rápido"],"h1":"Piense en qué podría hacer que el motor se apague sobre las vías.","h2":"En Montana, el manual aconseja no cambiar de velocidad al cruzar las vías del tren, por si el vehículo se apaga.","p":"Correcto. No cambie de velocidad sobre las vías."},"ref":{"doc":"MT","page":33}},{"id":"mt-123","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, you are on a road with three or more lanes going your way, and a lot of traffic is entering. Which lane should you use?","o":["The left lane","The right lane","The center lane","The shoulder"],"h1":"Normally you keep right, but this leaves room for cars coming in.","h2":"In Montana, on a road with three or more lanes in your direction, you should use the center lane when a lot of traffic is entering.","p":"Right. Use the center lane when a lot of traffic is entering."},"es":{"q":"En Montana, usted va por una vía con tres o más carriles en su dirección y está entrando mucho tráfico. ¿Qué carril debe usar?","o":["El carril izquierdo","El carril derecho","El carril del centro","El acotamiento"],"h1":"Normalmente se mantiene a la derecha, pero así deja espacio a los carros que entran.","h2":"En Montana, en una vía con tres o más carriles en su dirección, debe usar el carril del centro cuando está entrando mucho tráfico.","p":"Correcto. Use el carril del centro cuando entra mucho tráfico."},"ref":{"doc":"MT","page":37}},{"id":"mt-124","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, when is it legal to pass another vehicle on the right?","o":["Any time the shoulder is paved","When the vehicle is turning left, or the road has two or more lanes going your way","Never","When the other driver waves you on"],"h1":"You may never use the shoulder to do it.","h2":"In Montana you may pass on the right only when the other vehicle is turning left, or on a road wide enough for two or more lanes going your way, and never on the shoulder.","p":"Right. Only when it is turning left or there are two or more lanes your way."},"es":{"q":"En Montana, ¿cuándo es legal rebasar a otro vehículo por la derecha?","o":["Siempre que el acotamiento esté pavimentado","Cuando el vehículo va a dar vuelta a la izquierda, o la vía tiene dos o más carriles en su dirección","Nunca","Cuando el otro conductor le hace señas"],"h1":"Nunca puede usar el acotamiento para hacerlo.","h2":"En Montana, solo puede rebasar por la derecha cuando el otro vehículo va a dar vuelta a la izquierda, o en una vía con espacio para dos o más carriles en su dirección, y nunca por el acotamiento.","p":"Correcto. Solo si va a dar vuelta a la izquierda o hay dos o más carriles en su dirección."},"ref":{"doc":"MT","page":38}},{"id":"mt-125","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, there is no sidewalk, so a person must walk on the roadway. Which side should they walk on?","o":["The right side, with traffic","In the middle of the lane","Either side","The left side, facing oncoming traffic"],"h1":"People walking should be able to see the cars coming at them.","h2":"In Montana people walking on the roadway must walk on the left side, facing oncoming traffic.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Montana, no hay banqueta y una persona tiene que caminar por la vía. ¿Por qué lado debe caminar?","o":["Por la derecha, con el tráfico","Por el centro del carril","Por cualquier lado","Por la izquierda, de frente al tráfico"],"h1":"Quien camina debe poder ver los carros que vienen hacia él.","h2":"En Montana, las personas que caminan por la vía deben ir por el lado izquierdo, de frente al tráfico que viene.","p":"Correcto. Camine por la izquierda, de frente al tráfico."},"ref":{"doc":"MT","page":39}},{"id":"mt-126","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, you reach an intersection with no stop sign or traffic light at the same time as a car on your right. Who should yield?","o":["You should yield to the car on your right","The car on your right should yield to you","The faster car goes first","The larger vehicle goes first"],"h1":"Look at which side the other car is on.","h2":"In Montana, at an intersection with no stop sign or traffic signal, you should yield to vehicles coming from your right.","p":"Right. Yield to the car on your right."},"es":{"q":"En Montana, usted llega a un cruce sin señal de alto ni semáforo al mismo tiempo que un carro a su derecha. ¿Quién debe ceder el paso?","o":["Usted debe ceder el paso al carro de su derecha","El carro de su derecha debe cederle el paso","Pasa primero el carro más rápido","Pasa primero el vehículo más grande"],"h1":"Fíjese de qué lado está el otro carro.","h2":"En Montana, en un cruce sin señal de alto ni semáforo, usted debe ceder el paso a los vehículos que vienen por su derecha.","p":"Correcto. Ceda el paso al carro de su derecha."},"ref":{"doc":"MT","page":40}},{"id":"mt-127","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you are stopped at a crosswalk, waiting to turn right. A person is crossing. When may you make the turn?","o":["Only after the person reaches the far curb and the light changes","Never while anyone is in the crosswalk","When the person is in the opposite half of the road and not in danger","As soon as the person passes your front bumper"],"h1":"Think about which half of the road the person is in.","h2":"In Montana, when you are stopped at a crosswalk, you may make a right turn once the pedestrian is in the opposite half of the roadway and is not in danger.","p":"Right. When the person is in the far half of the road and safe."},"es":{"q":"En Montana, usted está detenido en un cruce peatonal, esperando para dar vuelta a la derecha. Una persona está cruzando. ¿Cuándo puede dar la vuelta?","o":["Solo cuando la persona llegue a la otra banqueta y cambie la luz","Nunca mientras haya alguien en el cruce peatonal","Cuando la persona esté en la mitad opuesta de la vía y no corra peligro","En cuanto la persona pase su defensa delantera"],"h1":"Piense en qué mitad de la vía está la persona.","h2":"En Montana, cuando está detenido en un cruce peatonal, puede dar vuelta a la derecha una vez que el peatón esté en la mitad opuesta de la vía y no corra peligro.","p":"Correcto. Cuando la persona esté en la mitad lejana de la vía y a salvo."},"ref":{"doc":"MT","page":40}},{"id":"mt-128","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, you are on a controlled-access highway. A school bus with flashing red lights is stopped in a loading zone beside the highway, where people are not allowed to cross the road. Must you stop?","o":["Yes, always stop 30 feet away","No, you do not need to stop","Yes, but only if you are behind the bus","Only if you can see children"],"h1":"The stop rule protects children crossing the road.","h2":"In Montana, on a controlled-access highway, you do not need to stop for a school bus that is stopped in a loading zone beside the highway where pedestrians are not allowed to cross the road.","p":"Right. You need not stop for a bus in such a loading zone."},"es":{"q":"En Montana, usted va por una carretera de acceso controlado. Un autobús escolar con luces rojas intermitentes está detenido en una zona de carga al lado de la carretera, donde las personas no pueden cruzar la vía. ¿Debe detenerse?","o":["Sí, siempre debe detenerse a 30 pies","No, no necesita detenerse","Sí, pero solo si va detrás del autobús","Solo si ve niños"],"h1":"La regla de detenerse protege a los niños que cruzan la vía.","h2":"En Montana, en una carretera de acceso controlado, usted no necesita detenerse por un autobús escolar detenido en una zona de carga al lado de la carretera donde los peatones no pueden cruzar la vía.","p":"Correcto. No necesita detenerse por un autobús en esa zona de carga."},"ref":{"doc":"MT","page":40}},{"id":"mt-129","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you are driving in a funeral procession on a city street with a 35 mph limit. What is the fastest you may drive?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"In a procession you stay a little under the posted limit.","h2":"In Montana a driver in a funeral procession on a road with a limit under 55 mph may not drive faster than 5 mph below the posted limit, which is 30 mph on a 35 mph street.","p":"Right. 5 mph below the limit: 30 mph here."},"es":{"q":"En Montana, usted va en una procesión fúnebre por una calle de la ciudad con límite de 35 mph. ¿Cuál es lo más rápido que puede ir?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"En una procesión se va un poco por debajo del límite indicado.","h2":"En Montana, un conductor en una procesión fúnebre en una vía con límite menor de 55 mph no puede ir a más de 5 mph por debajo del límite indicado, o sea 30 mph en una calle de 35 mph.","p":"Correcto. 5 mph por debajo del límite: aquí 30 mph."},"ref":{"doc":"MT","page":null}},{"id":"mt-130","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, you are driving in a funeral procession. Which lights must be on?","o":["Your headlights and taillights","Only your parking lights","No lights in daylight","Your high beams"],"h1":"Other drivers need to see which cars are in the procession.","h2":"In Montana every vehicle in a funeral procession must have its headlights and taillights on, and the first and last vehicles also flash their turn signals as warning lights.","p":"Right. Headlights and taillights on."},"es":{"q":"En Montana, usted maneja en una procesión fúnebre. ¿Qué luces deben estar encendidas?","o":["Los faros y las luces traseras","Solo las luces de estacionamiento","Ninguna, si es de día","Las luces altas"],"h1":"Los demás conductores necesitan ver qué carros van en la procesión.","h2":"En Montana, cada vehículo en una procesión fúnebre debe llevar encendidos los faros y las luces traseras, y el primero y el último también encienden sus direccionales como luces de advertencia.","p":"Correcto. Faros y luces traseras encendidos."},"ref":{"doc":"MT","page":42}},{"id":"mt-131","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, bicycle riders usually must ride single file. When may they ride two side by side?","o":["On any two-lane highway","Only at night","On a paved shoulder or in a parking lane","Never"],"h1":"It is allowed where they are out of the main travel lane.","h2":"In Montana bicycle riders may ride two side by side on a paved shoulder or in a parking lane, and in a few other cases.","p":"Right. Two side by side is allowed on a paved shoulder or in a parking lane."},"es":{"q":"En Montana, los ciclistas normalmente deben ir en fila de uno. ¿Cuándo pueden ir dos lado a lado?","o":["En cualquier carretera de dos carriles","Solo de noche","En un acotamiento pavimentado o en un carril de estacionamiento","Nunca"],"h1":"Se permite donde están fuera del carril principal.","h2":"En Montana, los ciclistas pueden ir dos lado a lado en un acotamiento pavimentado o en un carril de estacionamiento, y en otros pocos casos.","p":"Correcto. Pueden ir dos lado a lado en un acotamiento pavimentado o en un carril de estacionamiento."},"ref":{"doc":"MT","page":43}},{"id":"mt-132","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, you must cross a marked bicycle lane to turn, and a bicycle rider is in it. What must you do?","o":["Honk and turn first","Yield the right-of-way to the bicycle rider","Speed up to get ahead of the rider","Turn; cars always go first"],"h1":"That lane is set aside for the rider.","h2":"In Montana drivers must yield the right-of-way to a person riding a bicycle in a designated bicycle lane.","p":"Right. Yield to a rider in a bike lane."},"es":{"q":"En Montana, usted debe cruzar un carril para bicicletas marcado para dar vuelta, y hay un ciclista en él. ¿Qué debe hacer?","o":["Tocar el claxon y dar vuelta primero","Ceder el paso al ciclista","Acelerar para adelantarse al ciclista","Dar vuelta; los carros siempre van primero"],"h1":"Ese carril está reservado para el ciclista.","h2":"En Montana, los conductores deben ceder el paso a una persona en bicicleta que va en un carril para bicicletas.","p":"Correcto. Ceda el paso al ciclista en el carril para bicicletas."},"ref":{"doc":"MT","page":43}},{"id":"mt-133","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, a bicycle is ridden at night. Its front light must be seen from at least how far ahead?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is about one tenth of a mile.","h2":"In Montana a bicycle used at night must have a white front light that can be seen from at least 500 feet.","p":"Right. At least 500 feet."},"es":{"q":"En Montana, una bicicleta se usa de noche. ¿Desde qué distancia mínima debe verse su luz delantera?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es como una décima de milla.","h2":"En Montana, una bicicleta que se usa de noche debe tener una luz delantera blanca visible desde al menos 500 pies.","p":"Correcto. Al menos 500 pies."},"ref":{"doc":"MT","page":44}},{"id":"mt-134","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, you start to parallel park next to the car in front of the empty space. How far from that car should you be?","o":["At least 2 feet","About 6 inches","At least 6 feet","Close enough to touch its mirror"],"h1":"Leave enough room so you do not scrape it.","h2":"In Montana, to parallel park, pull up next to the car in front of the space, at least 2 feet from it, with your rear bumpers lined up.","p":"Right. Stay at least 2 feet away."},"es":{"q":"En Montana, usted empieza a estacionarse en paralelo junto al carro que está delante del espacio vacío. ¿A qué distancia de ese carro debe quedar?","o":["Al menos a 2 pies","Unas 6 pulgadas","Al menos a 6 pies","Tan cerca que toque su espejo"],"h1":"Deje espacio suficiente para no rayarlo.","h2":"En Montana, para estacionarse en paralelo, colóquese junto al carro de adelante del espacio, al menos a 2 pies de él, con las defensas traseras alineadas.","p":"Correcto. Quédese al menos a 2 pies."},"ref":{"doc":"MT","page":45}},{"id":"mt-135","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","Away from the curb","It does not matter"],"h1":"If the car rolls back, the back of the front tire should stop against the curb.","h2":"In Montana, when you park facing uphill next to a curb, turn your front wheels away from the curb.","p":"Right. Uphill with a curb: wheels away from the curb."},"es":{"q":"En Montana, usted se estaciona cuesta arriba junto a una banqueta. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la banqueta","Derechas","Lejos de la banqueta","No importa"],"h1":"Si el carro rueda hacia atrás, la parte trasera de la llanta delantera debe topar con la banqueta.","h2":"En Montana, cuando se estaciona cuesta arriba junto a una banqueta, gire las llantas delanteras lejos de la banqueta.","p":"Correcto. Cuesta arriba con banqueta: llantas lejos de la banqueta."},"ref":{"doc":"MT","page":45}},{"id":"mt-136","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you want to park on the same side of the street as a fire station driveway. How far from the driveway must you stay?","o":["At least 10 feet","At least 20 feet","At least 75 feet","At least 100 feet"],"h1":"It is much less than the 75 feet needed across the street.","h2":"In Montana you may not park within 20 feet of a fire station driveway on the same side of the street.","p":"Right. At least 20 feet on the same side."},"es":{"q":"En Montana, usted quiere estacionarse del mismo lado de la calle que la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe quedarse?","o":["Al menos a 10 pies","Al menos a 20 pies","Al menos a 75 pies","Al menos a 100 pies"],"h1":"Es mucho menos que los 75 pies del otro lado de la calle.","h2":"En Montana, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos del mismo lado de la calle.","p":"Correcto. Al menos 20 pies del mismo lado."},"ref":{"doc":"MT","page":46}},{"id":"mt-137","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, what is the fine for a second conviction of driving without liability insurance?","o":["$50","$100","$250","$350"],"h1":"It is $100 more than the smallest fine for a first offense.","h2":"In Montana a second conviction for driving without insurance brings a fine of $350, and the plates and registration of the car must be handed in.","p":"Right. The fine is $350."},"es":{"q":"En Montana, ¿cuál es la multa por una segunda condena por manejar sin seguro de responsabilidad civil?","o":["$50","$100","$250","$350"],"h1":"Son $100 más que la multa mínima de la primera vez.","h2":"En Montana, una segunda condena por manejar sin seguro trae una multa de $350, y hay que entregar las placas y el registro del carro.","p":"Correcto. La multa es de $350."},"ref":{"doc":"MT","page":null}},{"id":"mt-139","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, why does the driver manual say not to drive with headphones or earbuds?","o":["They drain the car battery","They can set off the air bag","They make it hard to hear horns and sirens","They block your side mirrors"],"h1":"Think about sounds that warn you of danger.","h2":"In Montana the driver manual says not to drive with headphones or earbuds, because they make it too hard to hear emergency horns and sirens.","p":"Right. You might not hear horns and sirens."},"es":{"q":"En Montana, ¿por qué dice el manual que no maneje con audífonos?","o":["Gastan la batería del carro","Pueden activar la bolsa de aire","No dejan oír bien las bocinas y sirenas","Tapan los espejos laterales"],"h1":"Piense en los sonidos que le avisan de un peligro.","h2":"En Montana, el manual dice que no maneje con audífonos, porque hacen muy difícil oír las bocinas y sirenas de emergencia.","p":"Correcto. Podría no oír bocinas ni sirenas."},"ref":{"doc":"MT","page":51}},{"id":"mt-140","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, you are driving on a very dusty gravel road. What does the driver manual recommend?","o":["Turn off all lights to avoid glare","Turn on your low beam headlights","Use your high beams","Turn on only your parking lights"],"h1":"The goal is for other drivers to see you.","h2":"In Montana the driver manual recommends using low beam headlights on dusty gravel roads so other drivers can see your vehicle.","p":"Right. Use your low beams."},"es":{"q":"En Montana, usted maneja por un camino de grava con mucho polvo. ¿Qué recomienda el manual?","o":["Apagar todas las luces para evitar reflejos","Encender las luces bajas","Usar las luces altas","Encender solo las luces de estacionamiento"],"h1":"La meta es que los demás conductores lo vean.","h2":"En Montana, el manual recomienda usar las luces bajas en caminos de grava con polvo para que los demás conductores vean su vehículo.","p":"Correcto. Use las luces bajas."},"ref":{"doc":"MT","page":59}},{"id":"mt-141","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, the road is wet from rain. About how much should you reduce your speed?","o":["You do not need to slow down","About 2 mph","Cut your speed in half","About 10 mph"],"h1":"Packed snow needs half your speed; a wet road needs less.","h2":"In Montana the driver manual says to reduce your speed by about 10 mph on a wet road.","p":"Right. Slow down about 10 mph."},"es":{"q":"En Montana, la vía está mojada por la lluvia. ¿Más o menos cuánto debe bajar su velocidad?","o":["No necesita bajar la velocidad","Unas 2 mph","A la mitad","Unas 10 mph"],"h1":"La nieve compacta pide la mitad de su velocidad; una vía mojada pide menos.","h2":"En Montana, el manual dice que baje su velocidad unas 10 mph en una vía mojada.","p":"Correcto. Baje unas 10 mph."},"ref":{"doc":"MT","page":60}},{"id":"mt-142","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you are stranded in your car during a snowstorm. What is the best thing to do?","o":["Stay in the car, where you are more likely to be found","Walk to the nearest house for help","Sleep with the engine running and the windows closed","Leave a note and walk along the road"],"h1":"Rescuers look for vehicles.","h2":"In Montana the driver manual says that if you are stranded in a snowstorm, the best thing is to stay in your car, because you are more likely to be found.","p":"Right. Stay in the car."},"es":{"q":"En Montana, usted queda atrapado en su carro durante una tormenta de nieve. ¿Qué es lo mejor que puede hacer?","o":["Quedarse en el carro, donde es más probable que lo encuentren","Caminar a la casa más cercana para pedir ayuda","Dormir con el motor encendido y las ventanas cerradas","Dejar una nota y caminar por la carretera"],"h1":"Los rescatistas buscan vehículos.","h2":"En Montana, el manual dice que si queda atrapado en una tormenta de nieve, lo mejor es quedarse en su carro, porque es más probable que lo encuentren.","p":"Correcto. Quédese en el carro."},"ref":{"doc":"MT","page":60}},{"id":"mt-143","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, in a heavy rain, at about what speed can your tires lose all grip on the road?","o":["20 mph","35 mph","50 mph","75 mph"],"h1":"Most tires grip well on a wet road up to about 35 mph; this speed is higher.","h2":"In Montana the driver manual says that in a heavy rain your tires can lose all traction at about 50 mph, and bald tires even sooner.","p":"Right. About 50 mph."},"es":{"q":"En Montana, con lluvia fuerte, ¿a qué velocidad aproximada pueden sus llantas perder todo el agarre?","o":["20 mph","35 mph","50 mph","75 mph"],"h1":"La mayoría de las llantas agarran bien en una vía mojada hasta unas 35 mph; esta velocidad es mayor.","h2":"En Montana, el manual dice que con lluvia fuerte sus llantas pueden perder todo el agarre a unas 50 mph, y las llantas lisas aún antes.","p":"Correcto. A unas 50 mph."},"ref":{"doc":"MT","page":60}},{"id":"mt-144","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, about how big a gap in traffic do you need to merge or change lanes safely?","o":["About 2 seconds","About 4 seconds","About 8 seconds","About 12 seconds"],"h1":"In the middle of this gap, you and the car behind you each have 2 seconds of space.","h2":"In Montana you need a gap of about four seconds whenever you merge, change lanes, or enter a roadway.","p":"Right. About four seconds."},"es":{"q":"En Montana, ¿más o menos qué tan grande debe ser el espacio en el tráfico para incorporarse o cambiar de carril con seguridad?","o":["Unos 2 segundos","Unos 4 segundos","Unos 8 segundos","Unos 12 segundos"],"h1":"En medio de este espacio, usted y el carro de atrás tienen cada uno 2 segundos de distancia.","h2":"En Montana, necesita un espacio de unos cuatro segundos cada vez que se incorpora, cambia de carril o entra a una vía.","p":"Correcto. Unos cuatro segundos."},"ref":{"doc":"MT","page":66}},{"id":"mt-145","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, the driver manual says not to start passing on a two-lane road when a hill or curve is within what distance?","o":["100 feet","300 feet","1,000 feet","One-third of a mile"],"h1":"It is about the distance you travel in 10 seconds at 55 mph, plus the same for an oncoming car.","h2":"In Montana you should not start to pass if you are within one-third of a mile of a hill or a curve.","p":"Right. Not within one-third of a mile."},"es":{"q":"En Montana, el manual dice que no empiece a rebasar en una vía de dos carriles cerca de una loma o una curva. ¿A menos de qué distancia?","o":["100 pies","300 pies","1,000 pies","Un tercio de milla"],"h1":"Es más o menos lo que usted recorre en 10 segundos a 55 mph, más lo mismo de un carro que viene de frente.","h2":"En Montana, no debe empezar a rebasar si está a menos de un tercio de milla de una loma o una curva.","p":"Correcto. No a menos de un tercio de milla."},"ref":{"doc":"MT","page":67}},{"id":"mt-146","scope":"MT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Montana, a driver is convicted of DUI for the first time. What happens to the driver license?","o":["It is suspended for six months","Nothing, for a first offense","It is suspended for 30 days","It is revoked for life"],"h1":"It is as long as a teen must hold a learner license.","h2":"In Montana a first DUI conviction brings a six-month license suspension, along with a fine and possible jail time.","p":"Right. It is suspended for six months."},"es":{"q":"En Montana, un conductor recibe su primera condena por manejar bajo la influencia (DUI). ¿Qué pasa con su licencia?","o":["La suspenden por seis meses","Nada, por ser la primera vez","La suspenden por 30 días","La revocan de por vida"],"h1":"Es lo mismo que un adolescente debe tener la licencia de aprendiz.","h2":"En Montana, una primera condena por DUI trae una suspensión de la licencia por seis meses, además de una multa y posible cárcel.","p":"Correcto. La suspenden por seis meses."},"ref":{"doc":"MT","page":72}},{"id":"mt-147","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, a police officer has pulled you over. What should you do while you wait?","o":["Get out and walk to the police car","Stay inside your vehicle unless the officer tells you to get out","Open the trunk to get your papers","Keep talking on your phone"],"h1":"Your vehicle is usually the safest place for you and your passengers.","h2":"In Montana you should stay inside your vehicle during a traffic stop unless the officer tells you to get out, and keep your hands where they can be seen.","p":"Right. Stay in your vehicle."},"es":{"q":"En Montana, un policía le indicó que se detuviera. ¿Qué debe hacer mientras espera?","o":["Bajarse y caminar a la patrulla","Quedarse dentro de su vehículo, a menos que el policía le diga que se baje","Abrir la cajuela para sacar sus papeles","Seguir hablando por teléfono"],"h1":"Su vehículo suele ser el lugar más seguro para usted y sus pasajeros.","h2":"En Montana, debe quedarse dentro de su vehículo durante una parada de tráfico, a menos que el policía le diga que se baje, y mantener las manos a la vista.","p":"Correcto. Quédese en su vehículo."},"ref":{"doc":"MT","page":81}},{"id":"mt-148","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you decide to stop driving and turn in your license more than six months before it expires. What can you get?","o":["A refund of your license fees","A free parking permit","A learner license","An ID card at no charge"],"h1":"You still need a way to prove who you are.","h2":"In Montana, if you turn in your license more than six months before it expires, you can get an identification card at no charge.","p":"Right. An ID card at no charge."},"es":{"q":"En Montana, usted decide dejar de manejar y entrega su licencia más de seis meses antes de que venza. ¿Qué puede recibir?","o":["Un reembolso de lo que pagó por la licencia","Un permiso de estacionamiento gratis","Una licencia de aprendiz","Una tarjeta de identificación sin costo"],"h1":"Usted todavía necesita una forma de probar quién es.","h2":"En Montana, si entrega su licencia más de seis meses antes de que venza, puede recibir una tarjeta de identificación sin costo.","p":"Correcto. Una tarjeta de identificación sin costo."},"ref":{"doc":"MT","page":75}},{"id":"mt-149","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, your engine dies while you are driving. What should you expect?","o":["Steering is harder, and you must press the brake pedal very hard","The brakes stop working completely","The steering wheel locks at once","The car stops right away by itself"],"h1":"The steering and brakes still work, but with less help.","h2":"In Montana the driver manual says that if your engine dies, steering may be hard but still works, and the brakes still work though you may have to press very hard; pull off the road.","p":"Right. Steering is harder and braking takes more force."},"es":{"q":"En Montana, el motor se apaga mientras usted maneja. ¿Qué debe esperar?","o":["El volante se pone más duro y debe pisar el freno con mucha fuerza","Los frenos dejan de funcionar por completo","El volante se traba de inmediato","El carro se detiene solo enseguida"],"h1":"El volante y los frenos todavía funcionan, pero con menos ayuda.","h2":"En Montana, el manual dice que si el motor se apaga, el volante puede ponerse duro pero sigue funcionando, y los frenos también funcionan aunque quizá tenga que pisar con mucha fuerza; sálgase del camino.","p":"Correcto. El volante se pone más duro y frenar requiere más fuerza."},"ref":{"doc":"MT","page":77}},{"id":"mt-150","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you come to an intersection with no signs or signals. How does the driver manual tell you to get ready to yield?","o":["Speed up to get through before other cars arrive","Honk and keep your speed","Take your foot off the gas, cover the brake, and look left, right, and left again","Flash your headlights and go first"],"h1":"Think about what your feet and your eyes should do.","h2":"In Montana, at an intersection with no signs or signals, you should take your foot off the gas, cover the brake, and look left, right, and left again, ready to yield.","p":"Right. Foot off the gas, cover the brake, and look left, right, left."},"es":{"q":"En Montana, usted llega a una intersección sin señales ni semáforos. ¿Cómo le dice el manual que se prepare para ceder el paso?","o":["Acelerar para pasar antes de que lleguen otros carros","Tocar el claxon y mantener la velocidad","Quitar el pie del acelerador, poner el pie sobre el freno y mirar a la izquierda, a la derecha y otra vez a la izquierda","Hacer cambio de luces y pasar primero"],"h1":"Piense en lo que deben hacer sus pies y sus ojos.","h2":"En Montana, en una intersección sin señales ni semáforos, debe quitar el pie del acelerador, poner el pie sobre el freno y mirar a la izquierda, a la derecha y otra vez a la izquierda, listo para ceder el paso.","p":"Correcto. Pie fuera del acelerador, pie sobre el freno, y mire izquierda, derecha, izquierda."},"ref":{"doc":"MT","page":40}},{"id":"mt-151","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, the car ahead of you has stopped at a crosswalk to let a person cross. What may you do?","o":["Stay behind it; you may not pass it","Pass it on the left if that lane is clear","Pass it slowly on the right","Honk so it moves on"],"h1":"The stopped car may be hiding the person from you.","h2":"In Montana, when a vehicle is stopped at a crosswalk to let a person cross, drivers coming up from behind may not pass it.","p":"Right. Never pass a car that is stopped for a person at a crosswalk."},"es":{"q":"En Montana, el carro de adelante se detuvo en un cruce peatonal para dejar pasar a una persona. ¿Qué puede hacer usted?","o":["Quedarse detrás; no puede rebasarlo","Rebasarlo por la izquierda si ese carril está libre","Rebasarlo despacio por la derecha","Tocar el claxon para que avance"],"h1":"El carro detenido puede taparle la vista de la persona.","h2":"En Montana, cuando un vehículo está detenido en un cruce peatonal para dejar cruzar a una persona, los conductores que vienen detrás no pueden rebasarlo.","p":"Correcto. Nunca rebase a un carro detenido por una persona en un cruce peatonal."},"ref":{"doc":"MT","page":40}},{"id":"mt-152","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, you are passing a car going the same way as you, and it starts to slow down. Who must yield?","o":["The car being passed, because it slowed down","Neither driver; it depends on the lane","The car being passed must pull onto the shoulder","You, the driver who is passing"],"h1":"The rule protects the vehicle that is already ahead.","h2":"In Montana, a driver who is passing another vehicle must yield to that vehicle, even if it is slowing down or stopping.","p":"Right. The driver who is passing must yield."},"es":{"q":"En Montana, usted está rebasando a un carro que va en su misma dirección, y ese carro empieza a frenar. ¿Quién debe ceder el paso?","o":["El carro rebasado, porque frenó","Ninguno; depende del carril","El carro rebasado debe salirse al acotamiento","Usted, el conductor que rebasa"],"h1":"La regla protege al vehículo que ya va adelante.","h2":"En Montana, el conductor que rebasa a otro vehículo debe cederle el paso, aunque ese vehículo esté frenando o deteniéndose.","p":"Correcto. El que rebasa debe ceder el paso."},"ref":{"doc":"MT","page":40}},{"id":"mt-153","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, the car ahead is turning left, and there is a wide paved shoulder on the right. May you drive on the shoulder to pass it on the right?","o":["Yes, if the shoulder is paved","No, never pass on the shoulder, paved or not","Yes, if you go under 25 mph","Yes, if you signal first"],"h1":"Other drivers never expect a car to be there.","h2":"In Montana you may never pass on the right by driving on the shoulder or off the main road, even when the shoulder is paved.","p":"Right. Never use the shoulder to pass."},"es":{"q":"En Montana, el carro de adelante va a dar vuelta a la izquierda y hay un acotamiento pavimentado ancho a la derecha. ¿Puede usar el acotamiento para rebasarlo por la derecha?","o":["Sí, si el acotamiento está pavimentado","No, nunca rebase por el acotamiento, esté pavimentado o no","Sí, si va a menos de 25 mph","Sí, si pone la direccional primero"],"h1":"Los demás conductores nunca esperan que haya un carro ahí.","h2":"En Montana nunca puede rebasar por la derecha manejando por el acotamiento o fuera de la vía principal, aunque el acotamiento esté pavimentado.","p":"Correcto. Nunca use el acotamiento para rebasar."},"ref":{"doc":"MT","page":38}},{"id":"mt-154","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, you are about to pass a bicycle rider, and a car is coming toward you. What does the driver manual say to do?","o":["Pass the bicycle quickly before the car arrives","Slow down, let the car go by first, then pass the bicycle with extra room","Squeeze between the bicycle and the car","Honk so the rider moves onto the shoulder"],"h1":"Deal with one hazard at a time.","h2":"In Montana the driver manual says to take hazards one at a time: slow down and let the oncoming vehicle pass first, so you can give the bicycle extra room.","p":"Right. Let the car pass first, then give the bicycle room."},"es":{"q":"En Montana, usted va a rebasar a un ciclista y viene un carro de frente. ¿Qué dice el manual que haga?","o":["Rebasar a la bicicleta rápido antes de que llegue el carro","Bajar la velocidad, dejar pasar primero al carro y luego rebasar a la bicicleta con más espacio","Pasar apretado entre la bicicleta y el carro","Tocar el claxon para que el ciclista se vaya al acotamiento"],"h1":"Enfrente un peligro a la vez.","h2":"En Montana, el manual dice que enfrente los peligros uno a la vez: baje la velocidad y deje pasar primero al vehículo que viene de frente, para poder darle más espacio a la bicicleta.","p":"Correcto. Deje pasar al carro primero y luego dele espacio a la bicicleta."},"ref":{"doc":"MT","page":66}},{"id":"mt-155","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, you have just passed a car on a two-lane road. When is it safe to move back into the driving lane?","o":["As soon as your back bumper is past its front bumper","When the other driver flashes the lights at you","After you count to two","When you can see both of its headlights in your rearview mirror"],"h1":"Use your inside mirror to check the space.","h2":"In Montana, after passing, it is safe to return to the driving lane when you can see both headlights of the car you passed in your rearview mirror.","p":"Right. Wait until you see both headlights in your mirror."},"es":{"q":"En Montana, usted acaba de rebasar a un carro en una carretera de dos carriles. ¿Cuándo es seguro volver al carril?","o":["En cuanto su defensa trasera pase su defensa delantera","Cuando el otro conductor le haga cambio de luces","Después de contar hasta dos","Cuando pueda ver sus dos faros delanteros en el espejo retrovisor"],"h1":"Use el espejo de adentro para revisar el espacio.","h2":"En Montana, después de rebasar, es seguro volver al carril cuando puede ver los dos faros delanteros del carro rebasado en su espejo retrovisor.","p":"Correcto. Espere a ver los dos faros en su espejo."},"ref":{"doc":"MT","page":67}},{"id":"mt-156","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, a person riding a horse along the road signals you to stop. What must you do?","o":["Stop","Slow down and pass quickly","Honk so the rider knows you are there","Keep going if you are in your own lane"],"h1":"Animals scare easily, and the rider knows the animal best.","h2":"In Montana you must stop if a person riding, leading or driving an animal signals you to stop.","p":"Right. Stop when the rider signals you to."},"es":{"q":"En Montana, una persona que va a caballo por la orilla del camino le hace señas para que se detenga. ¿Qué debe hacer?","o":["Detenerse","Bajar la velocidad y pasar rápido","Tocar el claxon para que el jinete sepa que usted está ahí","Seguir si va en su propio carril"],"h1":"Los animales se asustan fácilmente y el jinete conoce mejor a su animal.","h2":"En Montana, debe detenerse si una persona que monta, guía o conduce un animal le hace señas para que se detenga.","p":"Correcto. Deténgase cuando el jinete se lo indique."},"ref":{"doc":"MT","page":67}},{"id":"mt-157","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, state law defines a funeral procession as two or more vehicles, one carrying the deceased, traveling at what time?","o":["Only at night","Only on weekends","During daylight hours","Only on city streets after dark"],"h1":"Think of when most funerals take place.","h2":"In Montana the law defines a funeral procession as two or more vehicles, one of them carrying the deceased, traveling during daylight hours.","p":"Right. A funeral procession travels in daylight hours."},"es":{"q":"En Montana, la ley define un cortejo fúnebre como dos o más vehículos, uno con el difunto, que viajan ¿a qué hora?","o":["Solo de noche","Solo los fines de semana","Durante las horas de luz del día","Solo en calles de la ciudad después del anochecer"],"h1":"Piense en cuándo se hacen la mayoría de los funerales.","h2":"En Montana, la ley define un cortejo fúnebre como dos o más vehículos, uno de ellos con el difunto, que viajan durante las horas de luz del día.","p":"Correcto. El cortejo fúnebre viaja de día."},"ref":{"doc":"MT","page":42}},{"id":"mt-158","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, on a highway with several lanes going your way, when may you pass a funeral procession on its right side?","o":["Whenever the right lane is open","Only if you honk first","Only if you drive 10 mph faster than the procession","Only when the procession is in the far left lane"],"h1":"Passing on the right is allowed only when the procession is as far left as it can be.","h2":"In Montana you may not pass a funeral procession on its right side on a multi-lane highway unless the procession is in the farthest left lane.","p":"Right. Only when the procession is in the far left lane."},"es":{"q":"En Montana, en una carretera con varios carriles en su dirección, ¿cuándo puede rebasar a un cortejo fúnebre por su lado derecho?","o":["Siempre que el carril derecho esté libre","Solo si toca el claxon primero","Solo si va 10 mph más rápido que el cortejo","Solo cuando el cortejo va en el carril de la extrema izquierda"],"h1":"Rebasar por la derecha se permite solo cuando el cortejo va lo más a la izquierda posible.","h2":"En Montana no puede rebasar a un cortejo fúnebre por la derecha en una carretera de varios carriles, a menos que el cortejo vaya en el carril de la extrema izquierda.","p":"Correcto. Solo cuando el cortejo va en el carril de la extrema izquierda."},"ref":{"doc":"MT","page":42}},{"id":"mt-159","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, a funeral procession is going through a busy intersection. May you join the end of it so you can get through too?","o":["Yes, if you turn on your headlights","No, you may not join a procession to get its right-of-way","Yes, if you stay close to the last car","Yes, if it is during the day"],"h1":"The right-of-way belongs only to the cars that are really part of the procession.","h2":"In Montana a driver may not join a funeral procession to get the right-of-way that the procession has.","p":"Right. Do not join a procession to get through."},"es":{"q":"En Montana, un cortejo fúnebre está cruzando una intersección con mucho tráfico. ¿Puede unirse al final para pasar también?","o":["Sí, si enciende sus faros","No, no puede unirse a un cortejo para tener su derecho de paso","Sí, si se mantiene cerca del último carro","Sí, si es de día"],"h1":"El derecho de paso es solo para los carros que de verdad forman parte del cortejo.","h2":"En Montana un conductor no puede unirse a un cortejo fúnebre para obtener el derecho de paso que tiene el cortejo.","p":"Correcto. No se una a un cortejo para pasar."},"ref":{"doc":"MT","page":42}},{"id":"mt-160","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, you are driving in a funeral procession. The lead vehicle has gone ahead through an intersection, and now the light turns red for you. What does Montana law allow?","o":["You must stop and wait for the next green light","You must turn right and leave the procession","You may keep following through the intersection, with care","You may go only if you speed up past the limit"],"h1":"Once the lead vehicle has gone ahead, the procession may stay together.","h2":"In Montana, once the funeral lead vehicle has gone ahead, the other cars in the procession may follow through the intersection even against a signal, but they must use reasonable care.","p":"Right. You may keep following, with care."},"es":{"q":"En Montana, usted maneja en un cortejo fúnebre. El vehículo que lo encabeza ya cruzó la intersección y ahora el semáforo se pone en rojo para usted. ¿Qué permite la ley de Montana?","o":["Debe detenerse y esperar la próxima luz verde","Debe dar vuelta a la derecha y salirse del cortejo","Puede seguir cruzando la intersección detrás del cortejo, con cuidado","Puede seguir solo si acelera por encima del límite"],"h1":"Una vez que el vehículo que encabeza avanzó, el cortejo puede seguir unido.","h2":"En Montana, una vez que el vehículo que encabeza el cortejo fúnebre avanzó, los demás carros del cortejo pueden seguirlo por la intersección aunque el semáforo indique lo contrario, pero deben tener cuidado razonable.","p":"Correcto. Puede seguir detrás del cortejo, con cuidado."},"ref":{"doc":"MT","page":42}},{"id":"mt-161","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, a funeral procession is going through a red light at an intersection. You are not part of it. When may you enter the intersection?","o":["Only if you can do it without crossing the procession's path","As soon as your light turns green","Whenever there is a gap between two of its cars","Only if you honk first"],"h1":"The procession must not be cut.","h2":"In Montana a driver who is not in a funeral procession may not enter an intersection while the procession goes through a red light, unless the driver can do so without crossing the procession's path.","p":"Right. Only without crossing its path."},"es":{"q":"En Montana, un cortejo fúnebre está cruzando un semáforo en rojo en una intersección. Usted no forma parte de él. ¿Cuándo puede entrar a la intersección?","o":["Solo si puede hacerlo sin cruzar el camino del cortejo","En cuanto su semáforo cambie a verde","Siempre que haya un espacio entre dos de sus carros","Solo si toca el claxon primero"],"h1":"No se debe cortar el cortejo.","h2":"En Montana, un conductor que no forma parte de un cortejo fúnebre no puede entrar a una intersección mientras el cortejo cruza un semáforo en rojo, a menos que pueda hacerlo sin cruzar el camino del cortejo.","p":"Correcto. Solo sin cruzar su camino."},"ref":{"doc":"MT","page":42}},{"id":"mt-162","scope":"MT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Montana, you are driving in a funeral procession when an ambulance with its siren on comes toward the procession. What must you do?","o":["Yield the right-of-way to the ambulance","Keep going; the procession has the right-of-way","Speed up to clear the road","Turn on your hazard lights and keep going"],"h1":"A procession has special rights, but not over everyone.","h2":"In Montana a driver in a funeral procession must yield the right-of-way to an authorized emergency vehicle using its siren or lights.","p":"Right. A procession still yields to emergency vehicles."},"es":{"q":"En Montana, usted maneja en un cortejo fúnebre cuando se acerca una ambulancia con la sirena encendida. ¿Qué debe hacer?","o":["Cederle el paso a la ambulancia","Seguir; el cortejo tiene el derecho de paso","Acelerar para despejar el camino","Encender las intermitentes y seguir"],"h1":"El cortejo tiene derechos especiales, pero no frente a todos.","h2":"En Montana, un conductor en un cortejo fúnebre debe cederle el paso a un vehículo de emergencia autorizado que use su sirena o sus luces.","p":"Correcto. El cortejo también cede el paso a los vehículos de emergencia."},"ref":{"doc":"MT","page":42}},{"id":"mt-163","scope":"MT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Montana, why might a bicycle rider ride about 18 to 24 inches into the traffic lane instead of at the very edge?","o":["Because bicycles must always ride in the center of the lane","To block cars on purpose","To keep drivers from trying an unsafe pass within the same lane","Because riding near the edge is against the law"],"h1":"Think about what drivers might try if the rider hugs the edge.","h2":"In Montana many bicycle riders ride about 18 to 24 inches into the lane to discourage drivers from trying a dangerous pass within the same lane.","p":"Right. It discourages unsafe passing in the same lane."},"es":{"q":"En Montana, ¿por qué un ciclista podría ir de 18 a 24 pulgadas dentro del carril en vez de ir pegado a la orilla?","o":["Porque las bicicletas siempre deben ir en el centro del carril","Para bloquear a los carros a propósito","Para que los conductores no intenten rebasarlo de forma insegura dentro del mismo carril","Porque ir cerca de la orilla está prohibido"],"h1":"Piense en lo que podrían intentar los conductores si el ciclista va pegado a la orilla.","h2":"En Montana, muchos ciclistas van de 18 a 24 pulgadas dentro del carril para que los conductores no intenten un rebase peligroso dentro del mismo carril.","p":"Correcto. Así evitan rebases inseguros en el mismo carril."},"ref":{"doc":"MT","page":43}},{"id":"mt-164","scope":"MT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Montana, a bicycle rider going slower than traffic usually must stay as far right as practical. When may the rider move away from the right side?","o":["Only when a police officer allows it","To get ready for a left turn","Never, on any road","Only when there are no cars on the road"],"h1":"A rider must get into position before turning.","h2":"In Montana a bicycle rider may leave the right side of the road to pass, to get ready for a left turn, or to avoid an unsafe condition.","p":"Right. A rider may move left to get ready for a left turn."},"es":{"q":"En Montana, un ciclista que va más despacio que el tráfico normalmente debe ir lo más a la derecha posible. ¿Cuándo puede alejarse del lado derecho?","o":["Solo cuando un policía lo permita","Para prepararse para dar vuelta a la izquierda","Nunca, en ningún camino","Solo cuando no hay carros en el camino"],"h1":"El ciclista necesita colocarse antes de dar vuelta.","h2":"En Montana, un ciclista puede alejarse del lado derecho para rebasar, para prepararse para dar vuelta a la izquierda o para evitar una condición peligrosa.","p":"Correcto. Puede moverse a la izquierda para prepararse para dar vuelta a la izquierda."},"ref":{"doc":"MT","page":43}},{"id":"mt-165","scope":"MT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Montana, a bicycle rider is in your lane on your right side, and you want to turn right. What should you do?","o":["Speed up and turn in front of the rider","Honk so the rider moves over","Turn quickly while the rider is still beside you","Let the rider go past, or make sure the rider has stopped, before you turn"],"h1":"Your turn would cut across the rider's path.","h2":"In Montana, before you turn right with a bicycle in your lane, make sure the rider has stopped to let you turn, or let the rider pass you first.","p":"Right. Let the bicycle go by, or be sure it has stopped, before you turn."},"es":{"q":"En Montana, un ciclista va en su carril, a su lado derecho, y usted quiere dar vuelta a la derecha. ¿Qué debe hacer?","o":["Acelerar y dar vuelta delante del ciclista","Tocar el claxon para que se haga a un lado","Dar vuelta rápido mientras el ciclista sigue a su lado","Dejar que el ciclista pase, o asegurarse de que se detuvo, antes de dar vuelta"],"h1":"Su vuelta cruzaría el camino del ciclista.","h2":"En Montana, antes de dar vuelta a la derecha con una bicicleta en su carril, asegúrese de que el ciclista se detuvo para dejarlo dar vuelta, o deje que el ciclista pase primero.","p":"Correcto. Deje pasar a la bicicleta, o asegúrese de que se detuvo, antes de dar vuelta."},"ref":{"doc":"MT","page":44}},{"id":"mt-166","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, what does the law require on the back of a bicycle?","o":["Nothing; the back needs no equipment","A rear-facing reflector","A white light that can be seen from 500 feet","A license plate"],"h1":"A red rear light is allowed as an extra, but something else is required.","h2":"In Montana a bicycle must have a rear-facing reflector, and a red rear light that can be seen from 500 feet may be used in addition.","p":"Right. A rear reflector is required."},"es":{"q":"En Montana, ¿qué exige la ley en la parte de atrás de una bicicleta?","o":["Nada; la parte de atrás no necesita equipo","Un reflector que mire hacia atrás","Una luz blanca que se vea desde 500 pies","Una placa"],"h1":"Se permite una luz roja trasera como extra, pero se exige otra cosa.","h2":"En Montana, una bicicleta debe tener un reflector que mire hacia atrás, y además se puede usar una luz roja trasera visible desde 500 pies.","p":"Correcto. Se exige un reflector trasero."},"ref":{"doc":"MT","page":44}},{"id":"mt-167","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, how strong must a bicycle's brake be?","o":["Strong enough to make the wheels skid on dry, level, clean pavement","A bicycle needs no brake if it has a bell","Strong enough to stop within 100 feet from 30 mph","Only a hand brake on the front wheel is allowed"],"h1":"The test uses a dry, flat road.","h2":"In Montana a bicycle must have a brake that can make the wheels skid on dry, level, clean pavement.","p":"Right. The brake must be able to skid the wheels on dry, level pavement."},"es":{"q":"En Montana, ¿qué tan fuerte debe ser el freno de una bicicleta?","o":["Lo bastante fuerte para hacer patinar las ruedas en pavimento seco, plano y limpio","Una bicicleta no necesita freno si tiene timbre","Lo bastante fuerte para parar en 100 pies desde 30 mph","Solo se permite un freno de mano en la rueda delantera"],"h1":"La prueba usa un camino seco y plano.","h2":"En Montana, una bicicleta debe tener un freno que pueda hacer patinar las ruedas en pavimento seco, plano y limpio.","p":"Correcto. El freno debe poder hacer patinar las ruedas en pavimento seco y plano."},"ref":{"doc":"MT","page":44}},{"id":"mt-168","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, bicycle riders are encouraged to use a fluorescent orange flag. How high above the road should it be?","o":["At least 2 feet","At least 3 feet","At least 10 feet","At least 6 feet"],"h1":"It should be above the height of most cars.","h2":"In Montana every bicycle rider is encouraged to use a fluorescent orange flag, seen from behind, at least 6 feet above the road.","p":"Right. At least 6 feet above the road."},"es":{"q":"En Montana, se recomienda a los ciclistas usar una bandera anaranjada fluorescente. ¿A qué altura sobre el camino debe estar?","o":["Al menos 2 pies","Al menos 3 pies","Al menos 10 pies","Al menos 6 pies"],"h1":"Debe quedar más alta que la mayoría de los carros.","h2":"En Montana se recomienda que todo ciclista use una bandera anaranjada fluorescente, visible desde atrás, al menos a 6 pies sobre el camino.","p":"Correcto. Al menos 6 pies sobre el camino."},"ref":{"doc":"MT","page":44}},{"id":"mt-169","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, may you cover your headlights or tail lights with a tinted film or colored cover?","o":["Yes, any color is allowed","Yes, but only on the tail lights","No, unless it came with the car and meets federal rules","Yes, if you remove it at night"],"h1":"Lights must shine their proper color and strength.","h2":"In Montana headlights and tail lights may not be tinted or covered with colored material unless it is original or optional equipment that meets federal rules.","p":"Right. No tinted covers on headlights or tail lights."},"es":{"q":"En Montana, ¿puede cubrir sus faros o luces traseras con una película polarizada o una cubierta de color?","o":["Sí, se permite cualquier color","Sí, pero solo en las luces traseras","No, a menos que venga de fábrica y cumpla las reglas federales","Sí, si la quita de noche"],"h1":"Las luces deben brillar con su color y fuerza correctos.","h2":"En Montana, los faros y las luces traseras no pueden estar polarizados ni cubiertos con material de color, a menos que sea equipo original u opcional que cumpla las reglas federales.","p":"Correcto. Nada de cubiertas de color en los faros ni en las luces traseras."},"ref":{"doc":"MT","page":14}},{"id":"mt-170","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, your license plate light must light up the plate so it can be seen from how far behind the car?","o":["10 feet","200 feet","500 feet","50 feet"],"h1":"It is the shortest distance in the manual's list of light distances.","h2":"In Montana the license plate light must shine white light so the plate can be seen from 50 feet behind the car.","p":"Right. The plate must be lit for 50 feet."},"es":{"q":"En Montana, la luz de la placa debe iluminarla para que se vea ¿desde qué distancia detrás del carro?","o":["10 pies","200 pies","500 pies","50 pies"],"h1":"Es la distancia más corta de la lista de luces del manual.","h2":"En Montana, la luz de la placa debe dar luz blanca para que la placa se vea desde 50 pies detrás del carro.","p":"Correcto. La placa debe estar iluminada para 50 pies."},"ref":{"doc":"MT","page":15}},{"id":"mt-171","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, your tail lights must be visible from how far away?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is the same distance at which you must turn on your headlights if you cannot see.","h2":"In Montana tail lights must show red or amber light to the rear that can be seen from 500 feet.","p":"Right. Tail lights must be seen from 500 feet."},"es":{"q":"En Montana, ¿desde qué distancia deben verse sus luces traseras?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es la misma distancia en la que debe encender los faros si no puede ver.","h2":"En Montana, las luces traseras deben dar luz roja o ámbar hacia atrás que se vea desde 500 pies.","p":"Correcto. Las luces traseras deben verse desde 500 pies."},"ref":{"doc":"MT","page":14}},{"id":"mt-172","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, your vehicle has a spotlight. When must you turn it off?","o":["Only inside city limits","When you come near another moving vehicle from either direction","Only when it is raining","Never; spotlights may stay on"],"h1":"A spotlight can blind other drivers.","h2":"In Montana a spotlight must be turned off when you approach another moving vehicle from either direction.","p":"Right. Turn the spotlight off when another vehicle is near."},"es":{"q":"En Montana, su vehículo tiene un reflector (spotlight). ¿Cuándo debe apagarlo?","o":["Solo dentro de la ciudad","Cuando se acerque a otro vehículo en movimiento, en cualquier dirección","Solo cuando llueve","Nunca; puede quedarse encendido"],"h1":"Un reflector puede deslumbrar a otros conductores.","h2":"En Montana, un reflector (spotlight) debe apagarse cuando usted se acerca a otro vehículo en movimiento, en cualquier dirección.","p":"Correcto. Apague el reflector cuando haya otro vehículo cerca."},"ref":{"doc":"MT","page":16}},{"id":"mt-173","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, you tow a small trailer that weighs 3,000 pounds or less. What must connect its front to your vehicle?","o":["A rope at least 1 inch thick","Nothing besides the hitch","A second trailer hitch","A steel chain or cable at least 1/4 inch thick"],"h1":"It must be strong metal, not rope.","h2":"In Montana a trailer of 3,000 pounds or less must have a steel chain or cable, at least 1/4 inch thick, fastened securely to the towing vehicle.","p":"Right. A steel chain or cable at least 1/4 inch thick."},"es":{"q":"En Montana, usted remolca un tráiler pequeño de 3,000 libras o menos. ¿Qué debe unir su parte delantera a su vehículo?","o":["Una cuerda de al menos 1 pulgada de grueso","Nada aparte del enganche","Un segundo enganche","Una cadena o cable de acero de al menos 1/4 de pulgada de grueso"],"h1":"Debe ser de metal fuerte, no de cuerda.","h2":"En Montana, un tráiler de 3,000 libras o menos debe tener una cadena o cable de acero, de al menos 1/4 de pulgada de grueso, bien sujeto al vehículo que lo remolca.","p":"Correcto. Una cadena o cable de acero de al menos 1/4 de pulgada."},"ref":{"doc":"MT","page":17}},{"id":"mt-174","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, a trailer weighs more than 3,000 pounds. What kind of brakes must it have?","o":["No brakes are needed on a trailer","Only a parking brake","Break-away brakes that work if it comes loose from the towing vehicle","Brakes on its front wheels only"],"h1":"Think about what happens if the trailer comes unhooked.","h2":"In Montana a trailer with a gross weight over 3,000 pounds, or with air or vacuum brakes, must have break-away brakes that work if it separates from the towing vehicle.","p":"Right. It needs break-away brakes."},"es":{"q":"En Montana, un tráiler pesa más de 3,000 libras. ¿Qué tipo de frenos debe tener?","o":["Un tráiler no necesita frenos","Solo un freno de estacionamiento","Frenos de separación que funcionen si se suelta del vehículo que lo remolca","Frenos solo en las ruedas delanteras"],"h1":"Piense en qué pasa si el tráiler se desengancha.","h2":"En Montana, un tráiler con peso bruto de más de 3,000 libras, o con frenos de aire o de vacío, debe tener frenos de separación que funcionen si se suelta del vehículo que lo remolca.","p":"Correcto. Necesita frenos de separación."},"ref":{"doc":"MT","page":17}},{"id":"mt-175","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, you check your tire tread by putting a penny into it, Lincoln's head first. When is the tire unsafe?","o":["When the tread covers all of Lincoln's head","When the tread does not reach Lincoln's head","When the penny falls out","When you can read the date on the penny"],"h1":"Deep tread hides part of the head.","h2":"In Montana the driver manual says that if the tread does not come at least to Lincoln's head on a penny, the tire is unsafe and must be replaced.","p":"Right. If the tread does not reach Lincoln's head, replace the tire."},"es":{"q":"En Montana, usted revisa el dibujo de la llanta metiendo un centavo con la cabeza de Lincoln hacia abajo. ¿Cuándo es peligrosa la llanta?","o":["Cuando el dibujo cubre toda la cabeza de Lincoln","Cuando el dibujo no llega a la cabeza de Lincoln","Cuando el centavo se cae","Cuando puede leer la fecha del centavo"],"h1":"Un dibujo profundo tapa parte de la cabeza.","h2":"En Montana, el manual dice que si el dibujo de la llanta no llega por lo menos a la cabeza de Lincoln en un centavo, la llanta es peligrosa y hay que cambiarla.","p":"Correcto. Si el dibujo no llega a la cabeza de Lincoln, cambie la llanta."},"ref":{"doc":"MT","page":13}},{"id":"mt-176","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, it is getting dark. Why should you never drive with only your parking lights on?","o":["Oncoming drivers may think your car is stopped","Parking lights drain the battery too fast","Parking lights are too bright for other drivers","They are allowed only on the interstate"],"h1":"Parking lights are meant for parked cars.","h2":"In Montana the driver manual says never to drive with only your parking lights on, because oncoming traffic may think you are stopped; use your headlights.","p":"Right. Others may think you are stopped, so use headlights."},"es":{"q":"En Montana, está oscureciendo. ¿Por qué nunca debe manejar solo con las luces de estacionamiento?","o":["Los conductores que vienen de frente pueden creer que su carro está detenido","Gastan la batería muy rápido","Son demasiado brillantes para otros conductores","Solo se permiten en la carretera interestatal"],"h1":"Las luces de estacionamiento son para carros estacionados.","h2":"En Montana, el manual dice que nunca maneje solo con las luces de estacionamiento, porque el tráfico de frente puede creer que usted está detenido; use los faros.","p":"Correcto. Pueden creer que está detenido; use los faros."},"ref":{"doc":"MT","page":55}},{"id":"mt-177","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, which person does not have to wear a seat belt?","o":["A rider who carries a doctor's written statement that they cannot wear one for medical reasons","An adult riding in the back seat","Anyone on a trip of less than 5 miles","A driver going under 25 mph"],"h1":"The exception needs something in writing.","h2":"In Montana a person who carries a physician's written statement that they cannot wear a seat belt for medical reasons is an exception to the seat belt law.","p":"Right. A doctor's written statement is an exception."},"es":{"q":"En Montana, ¿qué persona no tiene que usar el cinturón de seguridad?","o":["Un pasajero que lleva una nota escrita de un médico que dice que no puede usarlo por razones médicas","Un adulto que va en el asiento de atrás","Cualquiera en un viaje de menos de 5 millas","Un conductor que va a menos de 25 mph"],"h1":"La excepción necesita algo por escrito.","h2":"En Montana, una persona que lleva una nota escrita de un médico que dice que no puede usar el cinturón por razones médicas es una excepción a la ley del cinturón.","p":"Correcto. La nota escrita de un médico es una excepción."},"ref":{"doc":"MT","page":20}},{"id":"mt-178","scope":"MT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Montana, with good tires and brakes on dry pavement, about how far does it take to react and stop from 50 mph?","o":["About 100 feet","About 200 feet","About 400 feet, about a city block","About 1,000 feet"],"h1":"It is about the length of a city block.","h2":"In Montana the driver manual says that at 50 mph it can take about 400 feet, about a city block, to react and stop on dry pavement.","p":"Right. About 400 feet at 50 mph."},"es":{"q":"En Montana, con buenas llantas y frenos en pavimento seco, ¿cuánta distancia se necesita para reaccionar y parar desde 50 mph?","o":["Unos 100 pies","Unos 200 pies","Unos 400 pies, como una cuadra de la ciudad","Unos 1,000 pies"],"h1":"Es más o menos el largo de una cuadra de la ciudad.","h2":"En Montana, el manual dice que a 50 mph se pueden necesitar unos 400 pies, como una cuadra, para reaccionar y parar en pavimento seco.","p":"Correcto. Unos 400 pies a 50 mph."},"ref":{"doc":"MT","page":63}},{"id":"mt-179","scope":"MT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Montana, in very heavy rain or thick fog you can see only about 200 feet ahead. What is the fastest you can safely drive?","o":["About 30 mph","About 45 mph","About 55 mph","About 65 mph"],"h1":"At this speed it takes about 200 feet to stop.","h2":"In Montana the driver manual says that when you cannot see farther than about 200 feet, you cannot safely drive faster than 30 mph.","p":"Right. No faster than about 30 mph."},"es":{"q":"En Montana, con lluvia muy fuerte o neblina espesa solo puede ver unos 200 pies hacia adelante. ¿Cuál es la velocidad más alta a la que puede manejar con seguridad?","o":["Unas 30 mph","Unas 45 mph","Unas 55 mph","Unas 65 mph"],"h1":"A esta velocidad se necesitan unos 200 pies para parar.","h2":"En Montana, el manual dice que cuando no puede ver más allá de unos 200 pies, no puede manejar con seguridad a más de 30 mph.","p":"Correcto. No más de unas 30 mph."},"ref":{"doc":"MT","page":63}},{"id":"mt-180","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you pick an object as far ahead as you can clearly see and start counting. You reach it before you finish saying \"four-one-thousand.\" What does it mean?","o":["You are following too closely","You are driving too fast for how far you can see","You are driving too slowly","Your headlights are aimed too low"],"h1":"This is the Four Second Sight Distance Rule.","h2":"In Montana, under the Four Second Sight Distance Rule, if you reach the object before you count to four seconds, you are going too fast for your sight distance and must slow down.","p":"Right. You are going too fast for your sight distance, so slow down."},"es":{"q":"En Montana, usted escoge un objeto lo más adelante que puede ver con claridad y empieza a contar. Llega a él antes de terminar de decir \"mil cuatro\". ¿Qué significa?","o":["Va demasiado cerca del carro de adelante","Va demasiado rápido para la distancia que puede ver","Va demasiado despacio","Sus faros apuntan muy bajo"],"h1":"Esta es la regla de los cuatro segundos de visibilidad.","h2":"En Montana, según la regla de los cuatro segundos de visibilidad, si llega al objeto antes de contar cuatro segundos, va demasiado rápido para la distancia que puede ver y debe bajar la velocidad.","p":"Correcto. Va demasiado rápido para lo que puede ver; baje la velocidad."},"ref":{"doc":"MT","page":64}},{"id":"mt-181","scope":"MT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Montana, you are driving below the posted speed limit on an icy road. Can you still get a ticket for your speed?","o":["No, never while you are under the limit","Only on the interstate","Only at night","Yes, if you are going too fast for the conditions"],"h1":"Speed limits are set for ideal conditions.","h2":"In Montana you can get a ticket for driving too fast for the conditions, such as ice, poor visibility or heavy traffic, even if you are under the posted limit.","p":"Right. Too fast for the conditions can get you a ticket."},"es":{"q":"En Montana, usted maneja por debajo del límite de velocidad en un camino con hielo. ¿Todavía le pueden dar una multa por su velocidad?","o":["No, nunca si va por debajo del límite","Solo en la carretera interestatal","Solo de noche","Sí, si va demasiado rápido para las condiciones"],"h1":"Los límites de velocidad son para condiciones ideales.","h2":"En Montana le pueden dar una multa por manejar demasiado rápido para las condiciones, como hielo, poca visibilidad o mucho tráfico, aunque vaya por debajo del límite.","p":"Correcto. Ir demasiado rápido para las condiciones puede costarle una multa."},"ref":{"doc":"MT","page":64}},{"id":"mt-182","scope":"MT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Montana, you are following a motorcycle. What following distance does the driver manual suggest?","o":["About one second","About four seconds","About two seconds","Half a second"],"h1":"It is more than the normal three seconds.","h2":"In Montana the driver manual says you may need a four-second following distance when following a motorcycle, because you need room if the rider falls.","p":"Right. Leave about four seconds behind a motorcycle."},"es":{"q":"En Montana, usted va detrás de una motocicleta. ¿Qué distancia de seguimiento recomienda el manual?","o":["Un segundo","Unos cuatro segundos","Unos dos segundos","Medio segundo"],"h1":"Es más que los tres segundos normales.","h2":"En Montana, el manual dice que puede necesitar una distancia de cuatro segundos detrás de una motocicleta, porque necesita espacio si el motociclista se cae.","p":"Correcto. Deje unos cuatro segundos detrás de una motocicleta."},"ref":{"doc":"MT","page":65}},{"id":"mt-183","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, you are about to slow down at a place where drivers behind you will not expect it. What should you do?","o":["Turn on your high beams","Turn on your right turn signal and keep it on","Hold the horn down","Tap the brake pedal three or four times quickly"],"h1":"Your brake lights can send the message.","h2":"In Montana the driver manual says to tap your brake pedal three or four times quickly to warn drivers behind you that you are about to slow down where they do not expect it.","p":"Right. Tap the brakes three or four times."},"es":{"q":"En Montana, usted va a bajar la velocidad en un lugar donde los conductores de atrás no lo esperan. ¿Qué debe hacer?","o":["Encender las luces altas","Poner la direccional derecha y dejarla puesta","Tocar el claxon sin soltarlo","Pisar el freno tres o cuatro veces rápido"],"h1":"Sus luces de freno pueden dar el aviso.","h2":"En Montana, el manual dice que pise el freno tres o cuatro veces rápido para avisar a los conductores de atrás que va a bajar la velocidad donde no lo esperan.","p":"Correcto. Pise el freno tres o cuatro veces."},"ref":{"doc":"MT","page":58}},{"id":"mt-184","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, the driver manual says that in most cases, which can you do more quickly to avoid a crash?","o":["Stop the vehicle","Back up","Turn the vehicle","Shift into neutral"],"h1":"Steering away often takes less distance than braking to a stop.","h2":"In Montana the driver manual says that in most cases you can turn the vehicle more quickly than you can stop it, so think about turning to avoid a collision.","p":"Right. Turning is usually quicker than stopping."},"es":{"q":"En Montana, el manual dice que en la mayoría de los casos, ¿qué puede hacer más rápido para evitar un choque?","o":["Detener el vehículo","Echarse en reversa","Dar vuelta al vehículo","Poner el cambio en neutral"],"h1":"Desviarse a menudo toma menos distancia que frenar hasta parar.","h2":"En Montana, el manual dice que en la mayoría de los casos puede dar vuelta al vehículo más rápido de lo que puede detenerlo, así que piense en desviarse para evitar un choque.","p":"Correcto. Desviarse suele ser más rápido que parar."},"ref":{"doc":"MT","page":78}},{"id":"mt-185","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, your car is about to be hit from behind. How should you protect yourself?","o":["Press back against your seat with your head against the head restraint","Lean forward toward the steering wheel","Unbuckle so you can get out fast","Turn around to look out the back window"],"h1":"Your body will be thrown backward.","h2":"In Montana, if you are about to be hit from the rear, press yourself against the back of your seat with your head against the head restraint, and be ready to brake.","p":"Right. Press back against the seat and head restraint."},"es":{"q":"En Montana, a su carro lo van a chocar por detrás. ¿Cómo debe protegerse?","o":["Pegarse al respaldo del asiento con la cabeza contra la cabecera","Inclinarse hacia el volante","Quitarse el cinturón para salir rápido","Voltearse para mirar por la ventana de atrás"],"h1":"Su cuerpo será lanzado hacia atrás.","h2":"En Montana, si lo van a chocar por detrás, péguese al respaldo del asiento con la cabeza contra la cabecera, y esté listo para frenar.","p":"Correcto. Péguese al asiento y a la cabecera."},"ref":{"doc":"MT","page":79}},{"id":"mt-186","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, you drive up to a crash. You were not involved, and police and an ambulance are already there. What should you do?","o":["Stop nearby to watch","Park and offer to direct traffic","Drive slowly to take a good look","Keep your attention on driving and keep moving"],"h1":"Stopping or slowing to look can block rescue vehicles.","h2":"In Montana you should not stop at a crash unless you are involved or emergency help has not arrived; keep your attention on your driving and keep moving.","p":"Right. Keep your eyes on the road and keep moving."},"es":{"q":"En Montana, usted llega a donde hubo un choque. Usted no estuvo involucrado y la policía y una ambulancia ya están ahí. ¿Qué debe hacer?","o":["Detenerse cerca para mirar","Estacionarse y ofrecerse a dirigir el tráfico","Pasar despacio para ver bien","Poner atención a su manejo y seguir avanzando"],"h1":"Detenerse o ir despacio para mirar puede estorbar a los vehículos de rescate.","h2":"En Montana no debe detenerse en un choque a menos que usted esté involucrado o la ayuda de emergencia no haya llegado; ponga atención a su manejo y siga avanzando.","p":"Correcto. Mire el camino y siga avanzando."},"ref":{"doc":"MT","page":79}},{"id":"mt-187","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you hit a parked car and cannot find its owner. What should you do?","o":["Leave a note where it can be seen, with how to reach you and the date and time","Drive away, since no one was hurt","Wait until the next week to report it","Write down its license plate and leave"],"h1":"The owner needs a way to contact you.","h2":"In Montana, if you hit a parked car and cannot find the owner, leave a note where it can be seen with how the owner can reach you and the date and time of the crash.","p":"Right. Leave a note with your contact information and the date and time."},"es":{"q":"En Montana, usted choca con un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Dejar una nota en un lugar visible, con cómo localizarlo y la fecha y la hora","Irse, porque nadie salió herido","Esperar hasta la semana siguiente para reportarlo","Anotar su placa e irse"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Montana, si choca con un carro estacionado y no encuentra al dueño, deje una nota en un lugar visible con cómo puede localizarlo el dueño y la fecha y la hora del choque.","p":"Correcto. Deje una nota con sus datos y la fecha y la hora."},"ref":{"doc":"MT","page":80}},{"id":"mt-188","scope":"MT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Montana, a person hurt in a crash asks you for a drink of water. What should you do?","o":["Give them small sips of water","Give them coffee to keep them awake","Do not give them anything to drink","Give them juice for energy"],"h1":"The rule includes water.","h2":"In Montana the driver manual says not to give an injured person anything to drink, not even water.","p":"Right. Give nothing to drink, not even water."},"es":{"q":"En Montana, una persona herida en un choque le pide un vaso de agua. ¿Qué debe hacer?","o":["Darle traguitos de agua","Darle café para que no se duerma","No darle nada de beber","Darle jugo para que tenga energía"],"h1":"La regla incluye el agua.","h2":"En Montana, el manual dice que no le dé nada de beber a una persona herida, ni siquiera agua.","p":"Correcto. No le dé nada de beber, ni siquiera agua."},"ref":{"doc":"MT","page":80}},{"id":"mt-189","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, a police officer signals you to pull over on the interstate. Where should you stop?","o":["In the center median","On the right shoulder","In the left lane","Right where you are, in your lane"],"h1":"Stopping near oncoming or fast traffic puts you and the officer in danger.","h2":"In Montana, when an officer pulls you over, move onto the right shoulder; do not stop in the center median or on the opposite side of the road.","p":"Right. Pull onto the right shoulder."},"es":{"q":"En Montana, un policía le indica que se detenga en la carretera interestatal. ¿Dónde debe detenerse?","o":["En el camellón central","En el acotamiento derecho","En el carril izquierdo","Ahí mismo, en su carril"],"h1":"Detenerse cerca de tráfico rápido o de frente lo pone en peligro a usted y al policía.","h2":"En Montana, cuando un policía le indica que se detenga, muévase al acotamiento derecho; no se detenga en el camellón central ni del otro lado del camino.","p":"Correcto. Deténgase en el acotamiento derecho."},"ref":{"doc":"MT","page":81}},{"id":"mt-190","scope":"MT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Montana, you have been pulled over by police, and your car windows are tinted. What does the driver manual recommend?","o":["Roll the windows down and keep everyone's hands in clear view","Keep the windows up until the officer knocks","Get out and walk to the police car","Search the car for your papers before the officer arrives"],"h1":"The officer needs to see you and your hands.","h2":"In Montana the driver manual recommends rolling down tinted windows after you stop, and keeping the hands of the driver and all passengers in clear view.","p":"Right. Windows down and hands where the officer can see them."},"es":{"q":"En Montana, la policía le indicó que se detuviera, y las ventanas de su carro están polarizadas. ¿Qué recomienda el manual?","o":["Bajar las ventanas y que todos tengan las manos a la vista","Dejar las ventanas cerradas hasta que el policía toque","Bajarse y caminar a la patrulla","Buscar sus papeles por todo el carro antes de que llegue el policía"],"h1":"El policía necesita verlo a usted y sus manos.","h2":"En Montana, el manual recomienda bajar las ventanas polarizadas después de detenerse, y que el conductor y todos los pasajeros tengan las manos a la vista.","p":"Correcto. Ventanas abajo y manos donde el policía las vea."},"ref":{"doc":"MT","page":81}},{"id":"mt-191","scope":"MT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Montana, the open container law has some exceptions. Which of these is one of them?","o":["Any passenger age 21 or older","A drink in the cup holder if the driver is sober","Any passenger in the back seat","Passengers riding in a bus, taxi or limousine with a hired driver"],"h1":"The driver in the exception is someone who is paid to drive.","h2":"In Montana the open container law does not apply to passengers carried by a hired driver in a bus, taxi or limousine, to sealed containers, or to the living quarters of a camper or motor home.","p":"Right. Passengers with a hired driver in a bus, taxi or limousine are an exception."},"es":{"q":"En Montana, la ley de envases abiertos tiene algunas excepciones. ¿Cuál de estas es una de ellas?","o":["Cualquier pasajero de 21 años o más","Una bebida en el portavasos si el conductor está sobrio","Cualquier pasajero en el asiento de atrás","Pasajeros que viajan en un autobús, taxi o limusina con un chofer pagado"],"h1":"En la excepción, el conductor es alguien a quien le pagan por manejar.","h2":"En Montana, la ley de envases abiertos no se aplica a pasajeros que lleva un chofer pagado en un autobús, taxi o limusina, a envases sellados, ni al área de vivienda de un camper o casa rodante.","p":"Correcto. Los pasajeros con chofer pagado en autobús, taxi o limusina son una excepción."},"ref":{"doc":"MT","page":72}},{"id":"mt-192","scope":"MT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Montana, you call to report a driver you think is drunk. Must you give your name?","o":["Yes, or the report will not be taken","No, you do not have to give your name","Yes, and you must also go to court","Only if you are under 21"],"h1":"The program only asks for the vehicle and where it is going.","h2":"In Montana, when you report a suspected drunk driver, you give a description of the vehicle and its direction, and you do not have to give your name.","p":"Right. You do not have to give your name."},"es":{"q":"En Montana, usted llama para reportar a un conductor que cree que está borracho. ¿Debe dar su nombre?","o":["Sí, o no aceptan el reporte","No, no tiene que dar su nombre","Sí, y además debe ir a la corte","Solo si tiene menos de 21 años"],"h1":"El programa solo pide el vehículo y hacia dónde va.","h2":"En Montana, cuando reporta a un posible conductor borracho, describe el vehículo y la dirección en que va, y no tiene que dar su nombre.","p":"Correcto. No tiene que dar su nombre."},"ref":{"doc":"MT","page":72}},{"id":"mt-193","scope":"MT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Montana, how many valid driver licenses may you have at one time?","o":["One from each state where you have a home","Two, if one of them is a learner license","Only one, from any state","As many as you want"],"h1":"Think of one person, one license.","h2":"In Montana you may have only one valid driver license, issued by any licensing jurisdiction, at any time.","p":"Right. Only one valid license at a time."},"es":{"q":"En Montana, ¿cuántas licencias de manejar válidas puede tener al mismo tiempo?","o":["Una de cada estado donde tenga casa","Dos, si una es una licencia de aprendiz","Solo una, de cualquier estado","Las que quiera"],"h1":"Piense: una persona, una licencia.","h2":"En Montana usted puede tener solo una licencia de manejar válida, emitida por cualquier jurisdicción, a la vez.","p":"Correcto. Solo una licencia válida a la vez."},"ref":{"doc":"MT","page":3}},{"id":"mt-194","scope":"MT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Montana, the spouse of an active-duty service member has a valid license from another state. When must the spouse get a Montana license?","o":["Within 60 days of arriving","When the spouse takes a paying job","Within 10 days of arriving","Never, as long as the service member stays on active duty"],"h1":"Dependents keep the out-of-state license until one thing changes.","h2":"In Montana active-duty military members and their dependents may keep driving on a valid out-of-state license unless they become gainfully employed; then they must get a Montana license.","p":"Right. Once the spouse is employed, a Montana license is needed."},"es":{"q":"En Montana, el cónyuge de un militar en servicio activo tiene una licencia válida de otro estado. ¿Cuándo debe sacar una licencia de Montana?","o":["Dentro de los 60 días de llegar","Cuando el cónyuge consiga un trabajo pagado","Dentro de los 10 días de llegar","Nunca, mientras el militar siga en servicio activo"],"h1":"Los familiares conservan la licencia de otro estado hasta que cambie una cosa.","h2":"En Montana, los militares en servicio activo y sus familiares pueden seguir manejando con una licencia válida de otro estado, a menos que consigan un empleo pagado; entonces deben sacar una licencia de Montana.","p":"Correcto. Cuando el cónyuge tiene empleo, necesita una licencia de Montana."},"ref":{"doc":"MT","page":4}},{"id":"mt-195","scope":"MT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Montana, you live in Montana and still have a valid driver license from another state. Can you get a Montana ID card?","o":["Yes, any resident can","Yes, if you pay a double fee","Yes, but it lasts only 60 days","No, not while you hold a valid license from another state"],"h1":"Montana will not give you a second credential next to a valid out-of-state license.","h2":"In Montana a resident who has a valid driver license from another jurisdiction is not eligible for a Montana identification card.","p":"Right. Not while you hold a valid license from another state."},"es":{"q":"En Montana, usted vive en Montana y todavía tiene una licencia de manejar válida de otro estado. ¿Puede sacar una tarjeta de identificación de Montana?","o":["Sí, cualquier residente puede","Sí, si paga el doble","Sí, pero solo dura 60 días","No, mientras tenga una licencia válida de otro estado"],"h1":"Montana no le da un segundo documento junto a una licencia válida de otro estado.","h2":"En Montana, un residente que tiene una licencia de manejar válida de otra jurisdicción no puede sacar una tarjeta de identificación de Montana.","p":"Correcto. No mientras tenga una licencia válida de otro estado."},"ref":{"doc":"MT","page":2}},{"id":"nc-001","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, what is the youngest age to get a limited learner permit (Level 1)?","o":["14 years old","15 years old","16 years old","18 years old"],"h1":"It is one year before the age for a Level 2 license.","h2":"In North Carolina you can get a Level 1 limited learner permit at 15, after a driver education course.","p":"Right. The Level 1 permit starts at 15."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para obtener el permiso limitado de aprendiz (Nivel 1)?","o":["14 años","15 años","16 años","18 años"],"h1":"Es un año antes de la edad para la licencia de Nivel 2.","h2":"En Carolina del Norte usted puede obtener el permiso limitado de aprendiz de Nivel 1 a los 15 años, después de un curso de educación vial.","p":"Correcto. El permiso de Nivel 1 empieza a los 15."},"zh":{"q":"在 North Carolina，最小几岁可以拿到有限制的学习驾照（limited learner permit，Level 1）？","o":["14 岁","15 岁","16 岁","18 岁"],"h1":"它比拿 Level 2 驾照的年龄早一年。","h2":"在 North Carolina，你上完驾驶教育课程以后，15 岁就可以拿到 Level 1 有限制的学习驾照。","p":"对。Level 1 学习驾照从 15 岁开始。"},"vi":{"q":"Ở North Carolina, tuổi nhỏ nhất để lấy giấy phép tập lái có giới hạn Cấp 1 (Level 1 limited learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","18 tuổi"],"h1":"Đó là một năm trước độ tuổi để lấy bằng Cấp 2.","h2":"Ở North Carolina, bạn có thể lấy giấy phép tập lái có giới hạn Cấp 1 khi 15 tuổi, sau khi học xong một khóa giáo dục lái xe.","p":"Đúng. Giấy phép Cấp 1 bắt đầu từ 15 tuổi."},"tl":{"q":"Sa North Carolina, ano ang pinakabatang edad para makakuha ng Level 1 limited learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito bago ang edad para sa Level 2 na lisensya.","h2":"Sa North Carolina, puwede kang makakuha ng Level 1 limited learner permit sa edad na 15, pagkatapos ng isang kurso sa driver education.","p":"Tama. Nagsisimula ang Level 1 permit sa edad na 15."},"ar":{"q":"في North Carolina، ما أصغر عمر للحصول على تصريح تعلّم القيادة المحدود من المستوى 1 (Level 1 limited learner permit)؟","o":["14 سنة","15 سنة","16 سنة","18 سنة"],"h1":"هو قبل سنة واحدة من عمر رخصة المستوى 2.","h2":"في North Carolina يمكنك الحصول على تصريح تعلّم القيادة المحدود من المستوى 1 في عمر 15 سنة، بعد إكمال دورة لتعليم القيادة.","p":"صحيح. يبدأ تصريح المستوى 1 في عمر 15 سنة."},"ref":{"doc":"NC","page":12}},{"id":"nc-002","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many levels does the graduated license for teens have?","o":["Three","Two","Four","Five"],"h1":"Learner permit, limited provisional, then full provisional.","h2":"North Carolina's teen license has three levels: a limited learner permit, a limited provisional license and a full provisional license.","p":"Right. There are three levels."},"es":{"q":"En Carolina del Norte, ¿cuántos niveles tiene la licencia graduada para adolescentes?","o":["Tres","Dos","Cuatro","Cinco"],"h1":"Permiso de aprendiz, provisional limitada y luego provisional completa.","h2":"La licencia para adolescentes en Carolina del Norte tiene tres niveles: permiso limitado de aprendiz, licencia provisional limitada y licencia provisional completa.","p":"Correcto. Son tres niveles."},"zh":{"q":"在 North Carolina，青少年的分级驾照一共有几级？","o":["三级","两级","四级","五级"],"h1":"学习驾照、有限制的临时驾照，然后是完整的临时驾照。","h2":"North Carolina 的青少年驾照有三级：有限制的学习驾照、有限制的临时驾照和完整的临时驾照。","p":"对。一共有三级。"},"vi":{"q":"Ở North Carolina, bằng lái theo từng giai đoạn cho thanh thiếu niên có bao nhiêu cấp?","o":["Ba","Hai","Bốn","Năm"],"h1":"Giấy phép tập lái, bằng tạm thời có giới hạn, rồi bằng tạm thời đầy đủ.","h2":"Bằng lái cho thanh thiếu niên ở North Carolina có ba cấp: giấy phép tập lái có giới hạn, bằng tạm thời có giới hạn (limited provisional license) và bằng tạm thời đầy đủ (full provisional license).","p":"Đúng. Có ba cấp."},"tl":{"q":"Sa North Carolina, ilang level mayroon ang graduated license para sa mga kabataan?","o":["Tatlo","Dalawa","Apat","Lima"],"h1":"Learner permit, limited provisional, at pagkatapos ay full provisional.","h2":"May tatlong level ang lisensya para sa kabataan sa North Carolina: limited learner permit, limited provisional license at full provisional license.","p":"Tama. May tatlong level."},"ar":{"q":"في North Carolina، كم مستوى في الرخصة المتدرّجة للمراهقين؟","o":["ثلاثة","اثنان","أربعة","خمسة"],"h1":"تصريح التعلّم، ثم الرخصة المؤقتة المحدودة، ثم الرخصة المؤقتة الكاملة.","h2":"رخصة المراهقين في North Carolina لها ثلاثة مستويات: تصريح تعلّم محدود، ورخصة مؤقتة محدودة (limited provisional license)، ورخصة مؤقتة كاملة (full provisional license).","p":"صحيح. هناك ثلاثة مستويات."},"ref":{"doc":"NC","page":12}},{"id":"nc-003","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, during the first six months of a Level 1 permit, when may the permit holder drive?","o":["Any time, day or night","Only on weekends","Only between 5 a.m. and 9 p.m., with a supervising driver","Only between noon and 6 p.m."],"h1":"The window starts early in the morning and ends in the evening.","h2":"During the first six months of a North Carolina Level 1 permit, you may drive only between 5 a.m. and 9 p.m., and always with a supervising driver.","p":"Right. 5 a.m. to 9 p.m., with a supervisor."},"es":{"q":"En Carolina del Norte, durante los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["A cualquier hora, de día o de noche","Solo los fines de semana","Solo entre las 5 a.m. y las 9 p.m., con un conductor supervisor","Solo entre el mediodía y las 6 p.m."],"h1":"El horario empieza temprano en la mañana y termina en la noche.","h2":"Durante los primeros seis meses del permiso de Nivel 1 en Carolina del Norte, usted solo puede manejar entre las 5 a.m. y las 9 p.m., y siempre con un conductor supervisor.","p":"Correcto. De 5 a.m. a 9 p.m., con un supervisor."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照的前六个月，什么时候可以开车？","o":["白天晚上任何时间","只在周末","只在早上 5 点到晚上 9 点之间，而且要有陪同的司机","只在中午到晚上 6 点之间"],"h1":"可以开车的时间从清早开始，到傍晚结束。","h2":"持 North Carolina Level 1 学习驾照的前六个月，你只能在早上 5 点到晚上 9 点之间开车，而且一直要有陪同的司机。","p":"对。早上 5 点到晚上 9 点，要有陪同的人。"},"vi":{"q":"Ở North Carolina, trong sáu tháng đầu của giấy phép Cấp 1, người có giấy phép được lái xe khi nào?","o":["Bất cứ lúc nào, ngày hay đêm","Chỉ vào cuối tuần","Chỉ từ 5 giờ sáng đến 9 giờ tối, có người lái xe giám sát đi cùng","Chỉ từ 12 giờ trưa đến 6 giờ chiều"],"h1":"Khoảng thời gian này bắt đầu từ sáng sớm và kết thúc vào buổi tối.","h2":"Trong sáu tháng đầu của giấy phép Cấp 1 ở North Carolina, bạn chỉ được lái xe từ 5 giờ sáng đến 9 giờ tối, và luôn phải có người lái xe giám sát đi cùng.","p":"Đúng. Từ 5 giờ sáng đến 9 giờ tối, có người giám sát."},"tl":{"q":"Sa North Carolina, sa unang anim na buwan ng Level 1 permit, kailan puwedeng magmaneho ang may hawak ng permit?","o":["Kahit anong oras, araw man o gabi","Tuwing weekend lang","Mula 5 a.m. hanggang 9 p.m. lang, kasama ang isang supervising driver","Mula tanghali hanggang 6 p.m. lang"],"h1":"Nagsisimula ang oras nang maaga sa umaga at natatapos sa gabi.","h2":"Sa unang anim na buwan ng Level 1 permit sa North Carolina, puwede kang magmaneho mula 5 a.m. hanggang 9 p.m. lang, at palaging may kasamang supervising driver.","p":"Tama. 5 a.m. hanggang 9 p.m., may kasamang supervisor."},"ar":{"q":"في North Carolina، خلال الأشهر الستة الأولى من تصريح المستوى 1، متى يمكن لحامل التصريح أن يقود؟","o":["في أي وقت، نهارًا أو ليلًا","في عطلة نهاية الأسبوع فقط","من 5 صباحًا إلى 9 مساءً فقط، مع سائق مشرف","من الظهر إلى 6 مساءً فقط"],"h1":"تبدأ الفترة في الصباح الباكر وتنتهي في المساء.","h2":"خلال الأشهر الستة الأولى من تصريح المستوى 1 في North Carolina، يمكنك القيادة فقط من 5 صباحًا إلى 9 مساءً، ودائمًا مع سائق مشرف.","p":"صحيح. من 5 صباحًا إلى 9 مساءً، مع مشرف."},"ref":{"doc":"NC","page":12}},{"id":"nc-004","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, after the first six months of a Level 1 permit, when may the permit holder drive?","o":["Only in daylight","Alone at any time","Never at night","At any time, but only with a supervising driver"],"h1":"The hours open up, but one thing does not change.","h2":"After the first six months, a North Carolina Level 1 permit holder may drive at any time, but still only with a supervising driver.","p":"Right. Any time, but always with a supervisor."},"es":{"q":"En Carolina del Norte, después de los primeros seis meses del permiso de Nivel 1, ¿cuándo puede manejar el titular?","o":["Solo de día","Solo, a cualquier hora","Nunca de noche","A cualquier hora, pero solo con un conductor supervisor"],"h1":"El horario se abre, pero hay algo que no cambia.","h2":"Después de los primeros seis meses, el titular de un permiso de Nivel 1 en Carolina del Norte puede manejar a cualquier hora, pero siempre con un conductor supervisor.","p":"Correcto. A cualquier hora, pero siempre con un supervisor."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照满六个月以后，什么时候可以开车？","o":["只在白天","任何时间都可以单独开","晚上永远不行","任何时间，但只能和陪同的司机一起"],"h1":"时间放开了，但有一件事不变。","h2":"前六个月以后，North Carolina 持 Level 1 学习驾照的人可以在任何时间开车，但仍然只能和陪同的司机一起。","p":"对。任何时间，但一直要有陪同的人。"},"vi":{"q":"Ở North Carolina, sau sáu tháng đầu của giấy phép Cấp 1, người có giấy phép được lái xe khi nào?","o":["Chỉ vào ban ngày","Lái một mình bất cứ lúc nào","Không bao giờ được lái vào ban đêm","Bất cứ lúc nào, nhưng chỉ khi có người lái xe giám sát"],"h1":"Giờ lái được mở rộng, nhưng có một điều không thay đổi.","h2":"Sau sáu tháng đầu, người có giấy phép Cấp 1 ở North Carolina được lái xe bất cứ lúc nào, nhưng vẫn chỉ khi có người lái xe giám sát.","p":"Đúng. Bất cứ lúc nào, nhưng luôn có người giám sát."},"tl":{"q":"Sa North Carolina, pagkatapos ng unang anim na buwan ng Level 1 permit, kailan puwedeng magmaneho ang may hawak ng permit?","o":["Kapag may liwanag ng araw lang","Mag-isa, kahit anong oras","Hindi kailanman sa gabi","Kahit anong oras, pero kasama lang ang isang supervising driver"],"h1":"Lumuluwag ang oras, pero may isang bagay na hindi nagbabago.","h2":"Pagkatapos ng unang anim na buwan, puwedeng magmaneho kahit anong oras ang may hawak ng Level 1 permit sa North Carolina, pero kasama pa rin ang isang supervising driver.","p":"Tama. Kahit anong oras, pero palaging may supervisor."},"ar":{"q":"في North Carolina، بعد الأشهر الستة الأولى من تصريح المستوى 1، متى يمكن لحامل التصريح أن يقود؟","o":["في ضوء النهار فقط","وحده في أي وقت","لا يقود في الليل أبدًا","في أي وقت، لكن مع سائق مشرف فقط"],"h1":"تصبح الساعات مفتوحة، لكن شيئًا واحدًا لا يتغيّر.","h2":"بعد الأشهر الستة الأولى، يمكن لحامل تصريح المستوى 1 في North Carolina أن يقود في أي وقت، لكن مع سائق مشرف فقط كما كان من قبل.","p":"صحيح. في أي وقت، لكن دائمًا مع مشرف."},"ref":{"doc":"NC","page":12}},{"id":"nc-005","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, how long must a supervising driver have been licensed?","o":["At least one year","At least five years","At least ten years","At least 20 years"],"h1":"It is more than a few years, but less than ten.","h2":"In North Carolina a supervising driver must be a licensed driver who has held a license for at least five years.","p":"Right. Licensed for at least five years."},"es":{"q":"En Carolina del Norte, ¿cuánto tiempo debe tener licencia un conductor supervisor?","o":["Por lo menos un año","Por lo menos cinco años","Por lo menos diez años","Por lo menos 20 años"],"h1":"Son más de unos pocos años, pero menos de diez.","h2":"En Carolina del Norte el conductor supervisor debe tener licencia de manejo desde hace por lo menos cinco años.","p":"Correcto. Con licencia desde hace por lo menos cinco años."},"zh":{"q":"在 North Carolina，陪同的司机必须持有驾照多久？","o":["至少一年","至少五年","至少十年","至少 20 年"],"h1":"比几年多，但少于十年。","h2":"在 North Carolina，陪同的司机必须是持有驾照至少五年的有驾照司机。","p":"对。持有驾照至少五年。"},"vi":{"q":"Ở North Carolina, người lái xe giám sát phải có bằng lái ít nhất bao lâu?","o":["Ít nhất một năm","Ít nhất năm năm","Ít nhất mười năm","Ít nhất 20 năm"],"h1":"Hơn vài năm, nhưng ít hơn mười năm.","h2":"Ở North Carolina, người lái xe giám sát phải là người có bằng lái và đã có bằng ít nhất năm năm.","p":"Đúng. Có bằng lái ít nhất năm năm."},"tl":{"q":"Sa North Carolina, gaano na katagal dapat may lisensya ang isang supervising driver?","o":["Hindi bababa sa isang taon","Hindi bababa sa limang taon","Hindi bababa sa sampung taon","Hindi bababa sa 20 taon"],"h1":"Higit ito sa ilang taon, pero kulang sa sampu.","h2":"Sa North Carolina, ang supervising driver ay dapat may lisensya at may hawak na lisensya nang hindi bababa sa limang taon.","p":"Tama. May lisensya nang hindi bababa sa limang taon."},"ar":{"q":"في North Carolina، منذ كم سنة على الأقل يجب أن يحمل السائق المشرف رخصة قيادة؟","o":["سنة واحدة على الأقل","خمس سنوات على الأقل","عشر سنوات على الأقل","20 سنة على الأقل"],"h1":"أكثر من بضع سنوات، لكن أقل من عشر.","h2":"في North Carolina يجب أن يكون السائق المشرف سائقًا مرخّصًا يحمل رخصة قيادة منذ خمس سنوات على الأقل.","p":"صحيح. رخصة منذ خمس سنوات على الأقل."},"ref":{"doc":"NC","page":12}},{"id":"nc-006","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, where must the supervising driver sit while a Level 1 permit holder drives?","o":["In the front seat, beside the driver","In the back seat","Anywhere in the car","In another car nearby"],"h1":"The supervisor must be close enough to help right away.","h2":"In North Carolina the supervising driver must sit in the front seat beside the permit holder whenever the car is moving.","p":"Right. The supervisor sits beside you in front."},"es":{"q":"En Carolina del Norte, ¿dónde debe sentarse el conductor supervisor mientras maneja el titular de un permiso de Nivel 1?","o":["En el asiento delantero, al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro cercano"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Carolina del Norte el conductor supervisor debe sentarse en el asiento delantero, al lado del titular del permiso, siempre que el carro esté en movimiento.","p":"Correcto. El supervisor va a su lado, adelante."},"zh":{"q":"在 North Carolina，持 Level 1 学习驾照的人开车时，陪同的司机必须坐在哪里？","o":["前排，在司机旁边","后排","车里任何地方","附近的另一辆车里"],"h1":"陪同的人必须离得够近，能马上帮忙。","h2":"在 North Carolina，只要车在开，陪同的司机就必须坐在前排，在持学习驾照的人旁边。","p":"对。陪同的人坐在前排，在你旁边。"},"vi":{"q":"Ở North Carolina, người lái xe giám sát phải ngồi ở đâu khi người có giấy phép Cấp 1 lái xe?","o":["Ở ghế trước, bên cạnh người lái","Ở ghế sau","Ở bất cứ chỗ nào trong xe","Trong một xe khác ở gần đó"],"h1":"Người giám sát phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở North Carolina, người lái xe giám sát phải ngồi ở ghế trước, bên cạnh người có giấy phép, bất cứ khi nào xe đang chạy.","p":"Đúng. Người giám sát ngồi bên cạnh bạn ở ghế trước."},"tl":{"q":"Sa North Carolina, saan dapat umupo ang supervising driver habang nagmamaneho ang may hawak ng Level 1 permit?","o":["Sa harapang upuan, katabi ng nagmamaneho","Sa likurang upuan","Kahit saan sa kotse","Sa ibang kotse na malapit"],"h1":"Dapat sapat na malapit ang supervisor para makatulong agad.","h2":"Sa North Carolina, dapat umupo ang supervising driver sa harapang upuan, katabi ng may hawak ng permit, tuwing umaandar ang kotse.","p":"Tama. Katabi mo sa harap ang supervisor."},"ar":{"q":"في North Carolina، أين يجب أن يجلس السائق المشرف بينما يقود حامل تصريح المستوى 1؟","o":["في المقعد الأمامي، بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى قريبة"],"h1":"يجب أن يكون المشرف قريبًا بما يكفي ليساعد فورًا.","h2":"في North Carolina يجب أن يجلس السائق المشرف في المقعد الأمامي بجانب حامل التصريح كلما كانت السيارة تتحرك.","p":"صحيح. المشرف يجلس بجانبك في الأمام."},"ref":{"doc":"NC","page":null}},{"id":"nc-007","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, what is the youngest age for a Level 2 limited provisional license?","o":["15 years old","15 and a half","16 years old","18 years old"],"h1":"It is one year after the youngest age for a Level 1 permit.","h2":"In North Carolina the youngest age for a Level 2 limited provisional license is 16.","p":"Right. Level 2 starts at 16."},"es":{"q":"En Carolina del Norte, ¿cuál es la edad mínima para la licencia provisional limitada de Nivel 2?","o":["15 años","15 años y medio","16 años","18 años"],"h1":"Es un año después de la edad mínima para el permiso de Nivel 1.","h2":"En Carolina del Norte la edad mínima para la licencia provisional limitada de Nivel 2 es de 16 años.","p":"Correcto. El Nivel 2 empieza a los 16."},"zh":{"q":"在 North Carolina，最小几岁可以拿到 Level 2 有限制的临时驾照？","o":["15 岁","15 岁半","16 岁","18 岁"],"h1":"它比拿 Level 1 学习驾照的最小年龄晚一年。","h2":"在 North Carolina，拿 Level 2 有限制的临时驾照的最小年龄是 16 岁。","p":"对。Level 2 从 16 岁开始。"},"vi":{"q":"Ở North Carolina, tuổi nhỏ nhất để lấy bằng tạm thời có giới hạn Cấp 2 (Level 2 limited provisional license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","18 tuổi"],"h1":"Đó là một năm sau tuổi nhỏ nhất để lấy giấy phép Cấp 1.","h2":"Ở North Carolina, tuổi nhỏ nhất để lấy bằng tạm thời có giới hạn Cấp 2 là 16 tuổi.","p":"Đúng. Cấp 2 bắt đầu từ 16 tuổi."},"tl":{"q":"Sa North Carolina, ano ang pinakabatang edad para sa Level 2 limited provisional license?","o":["15 taong gulang","15 at kalahati","16 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa Level 1 permit.","h2":"Sa North Carolina, ang pinakabatang edad para sa Level 2 limited provisional license ay 16.","p":"Tama. Nagsisimula ang Level 2 sa edad na 16."},"ar":{"q":"في North Carolina، ما أصغر عمر للحصول على الرخصة المؤقتة المحدودة من المستوى 2 (Level 2 limited provisional license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","18 سنة"],"h1":"هو بعد سنة واحدة من أصغر عمر لتصريح المستوى 1.","h2":"في North Carolina أصغر عمر للرخصة المؤقتة المحدودة من المستوى 2 هو 16 سنة.","p":"صحيح. يبدأ المستوى 2 في عمر 16 سنة."},"ref":{"doc":"NC","page":13}},{"id":"nc-008","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, during which hours may a Level 2 driver drive without a supervising driver?","o":["From 5 a.m. to 9 p.m.","From 6 a.m. to midnight","From 7 a.m. to 7 p.m.","Any hour of the day"],"h1":"These are the same hours as the first months of the Level 1 permit.","h2":"A North Carolina Level 2 driver may drive alone from 5 a.m. to 9 p.m.; from 9 p.m. to 5 a.m. a supervising driver is needed, with a few exceptions.","p":"Right. Alone from 5 a.m. to 9 p.m."},"es":{"q":"En Carolina del Norte, ¿en qué horario puede manejar un conductor de Nivel 2 sin un conductor supervisor?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a medianoche","De 7 a.m. a 7 p.m.","A cualquier hora del día"],"h1":"Es el mismo horario de los primeros meses del permiso de Nivel 1.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo de 5 a.m. a 9 p.m.; de 9 p.m. a 5 a.m. necesita un conductor supervisor, con algunas excepciones.","p":"Correcto. Solo, de 5 a.m. a 9 p.m."},"zh":{"q":"在 North Carolina，Level 2 司机在哪段时间可以没有陪同的司机开车？","o":["早上 5 点到晚上 9 点","早上 6 点到午夜","早上 7 点到晚上 7 点","一天中任何时间"],"h1":"这和 Level 1 学习驾照前几个月的时间一样。","h2":"North Carolina 的 Level 2 司机可以在早上 5 点到晚上 9 点单独开车；从晚上 9 点到早上 5 点需要有陪同的司机，只有几个例外。","p":"对。早上 5 点到晚上 9 点可以单独开车。"},"vi":{"q":"Ở North Carolina, người lái Cấp 2 được lái xe mà không cần người giám sát trong những giờ nào?","o":["Từ 5 giờ sáng đến 9 giờ tối","Từ 6 giờ sáng đến nửa đêm","Từ 7 giờ sáng đến 7 giờ tối","Bất cứ giờ nào trong ngày"],"h1":"Đây là cùng khung giờ với những tháng đầu của giấy phép Cấp 1.","h2":"Người lái Cấp 2 ở North Carolina được lái một mình từ 5 giờ sáng đến 9 giờ tối; từ 9 giờ tối đến 5 giờ sáng thì cần có người lái xe giám sát, trừ một vài trường hợp ngoại lệ.","p":"Đúng. Lái một mình từ 5 giờ sáng đến 9 giờ tối."},"tl":{"q":"Sa North Carolina, sa anong mga oras puwedeng magmaneho ang Level 2 driver nang walang supervising driver?","o":["Mula 5 a.m. hanggang 9 p.m.","Mula 6 a.m. hanggang hatinggabi","Mula 7 a.m. hanggang 7 p.m.","Kahit anong oras sa araw"],"h1":"Pareho ito sa mga oras ng mga unang buwan ng Level 1 permit.","h2":"Puwedeng magmaneho nang mag-isa ang Level 2 driver sa North Carolina mula 5 a.m. hanggang 9 p.m.; mula 9 p.m. hanggang 5 a.m., kailangan ng supervising driver, maliban sa ilang eksepsiyon.","p":"Tama. Mag-isa mula 5 a.m. hanggang 9 p.m."},"ar":{"q":"في North Carolina، في أي ساعات يمكن لسائق المستوى 2 أن يقود بدون سائق مشرف؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى منتصف الليل","من 7 صباحًا إلى 7 مساءً","في أي ساعة من اليوم"],"h1":"هي نفس ساعات الأشهر الأولى من تصريح المستوى 1.","h2":"يمكن لسائق المستوى 2 في North Carolina أن يقود وحده من 5 صباحًا إلى 9 مساءً؛ ومن 9 مساءً إلى 5 صباحًا يلزم وجود سائق مشرف، مع بعض الاستثناءات.","p":"صحيح. وحده من 5 صباحًا إلى 9 مساءً."},"ref":{"doc":"NC","page":13}},{"id":"nc-009","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, which trip may a Level 2 driver make alone after 9 p.m.?","o":["Going to a friend's party","Driving around for fun","Going to the movies","Driving directly to or from work"],"h1":"It is a trip with a serious, regular purpose.","h2":"A North Carolina Level 2 driver may drive alone after 9 p.m. when driving directly to or from work; volunteer fire, rescue or EMS trips are also allowed.","p":"Right. Driving straight to or from work is allowed."},"es":{"q":"En Carolina del Norte, ¿qué viaje puede hacer solo un conductor de Nivel 2 después de las 9 p.m.?","o":["Ir a la fiesta de un amigo","Pasear por diversión","Ir al cine","Manejar directo al trabajo o de regreso del trabajo"],"h1":"Es un viaje con un propósito serio y regular.","h2":"Un conductor de Nivel 2 en Carolina del Norte puede manejar solo después de las 9 p.m. cuando va directo al trabajo o regresa de él; también se permiten viajes como voluntario de bomberos, rescate o emergencias médicas.","p":"Correcto. Ir directo al trabajo o regresar está permitido."},"zh":{"q":"在 North Carolina，Level 2 司机晚上 9 点以后可以单独开车去做哪件事？","o":["去朋友的派对","开车出去玩","去看电影","直接去上班或下班"],"h1":"这是一个有正经、固定目的的路程。","h2":"North Carolina 的 Level 2 司机在晚上 9 点以后直接去上班或下班时可以单独开车；志愿消防、救援或急救（EMS）的路程也可以。","p":"对。直接去上班或下班是可以的。"},"vi":{"q":"Ở North Carolina, người lái Cấp 2 được lái một mình sau 9 giờ tối cho chuyến đi nào?","o":["Đi dự tiệc của bạn bè","Lái xe đi chơi cho vui","Đi xem phim","Lái xe thẳng đến nơi làm việc hoặc từ nơi làm việc về"],"h1":"Đó là một chuyến đi có mục đích nghiêm túc và thường xuyên.","h2":"Người lái Cấp 2 ở North Carolina được lái một mình sau 9 giờ tối khi lái xe thẳng đến hoặc từ nơi làm việc; các chuyến đi làm tình nguyện cứu hỏa, cứu hộ hoặc cấp cứu (EMS) cũng được phép.","p":"Đúng. Được lái thẳng đến hoặc từ nơi làm việc."},"tl":{"q":"Sa North Carolina, anong biyahe ang puwedeng gawin nang mag-isa ng Level 2 driver pagkalipas ng 9 p.m.?","o":["Pagpunta sa party ng kaibigan","Pagmamaneho-maneho para magsaya","Pagpunta sa sinehan","Diretsong pagmamaneho papunta o pauwi mula sa trabaho"],"h1":"Ito ay biyaheng may seryoso at regular na layunin.","h2":"Puwedeng magmaneho nang mag-isa ang Level 2 driver sa North Carolina pagkalipas ng 9 p.m. kapag diretsong papunta o pauwi mula sa trabaho; pinapayagan din ang mga biyahe para sa volunteer fire, rescue o EMS.","p":"Tama. Pinapayagan ang diretsong biyahe papunta o pauwi mula sa trabaho."},"ar":{"q":"في North Carolina، أي رحلة يمكن لسائق المستوى 2 أن يقوم بها وحده بعد 9 مساءً؟","o":["الذهاب إلى حفلة صديق","القيادة للتسلية","الذهاب إلى السينما","القيادة مباشرة إلى العمل أو من العمل"],"h1":"هي رحلة لها هدف جاد ومنتظم.","h2":"يمكن لسائق المستوى 2 في North Carolina أن يقود وحده بعد 9 مساءً عندما يقود مباشرة إلى العمل أو منه؛ ورحلات التطوّع في الإطفاء أو الإنقاذ أو الإسعاف (EMS) مسموحة أيضًا.","p":"صحيح. القيادة مباشرة إلى العمل أو منه مسموحة."},"ref":{"doc":"NC","page":13}},{"id":"nc-010","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, as a general rule, how many passengers under 21 who are not family may a Level 2 driver carry when no supervising driver is in the car?","o":["None","Three","One","Four"],"h1":"It is the smallest number above zero.","h2":"As a general rule, a North Carolina Level 2 driver without a supervisor may carry only one passenger under 21 who is not from the driver's household; one more student may ride on a trip straight to or from school.","p":"Right. Only one passenger under 21."},"es":{"q":"En Carolina del Norte, como regla general, ¿cuántos pasajeros menores de 21 años que no son de la familia puede llevar un conductor de Nivel 2 cuando no va un conductor supervisor en el carro?","o":["Ninguno","Tres","Uno","Cuatro"],"h1":"Es el número más pequeño mayor que cero.","h2":"Como regla general, un conductor de Nivel 2 en Carolina del Norte sin supervisor solo puede llevar un pasajero menor de 21 años que no sea de su hogar; un estudiante más puede ir en un viaje directo a la escuela o de regreso.","p":"Correcto. Solo un pasajero menor de 21."},"zh":{"q":"在 North Carolina，一般来说，车里没有陪同的司机时，Level 2 司机可以载多少位不是家人、21 岁以下的乘客？","o":["一个都不行","三位","一位","四位"],"h1":"这是大于零的最小数字。","h2":"一般来说，North Carolina 的 Level 2 司机没有陪同的人时，只能载一位不是同一家庭、21 岁以下的乘客；直接上学或放学的路上，可以再多载一位学生。","p":"对。只能载一位 21 岁以下的乘客。"},"vi":{"q":"Ở North Carolina, theo quy định chung, người lái Cấp 2 được chở bao nhiêu hành khách dưới 21 tuổi không phải người nhà khi không có người lái xe giám sát trong xe?","o":["Không ai","Ba","Một","Bốn"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Theo quy định chung, người lái Cấp 2 ở North Carolina khi không có người giám sát chỉ được chở một hành khách dưới 21 tuổi không sống cùng nhà với người lái; được chở thêm một học sinh nữa trên chuyến đi thẳng đến trường hoặc từ trường về.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi."},"tl":{"q":"Sa North Carolina, bilang pangkalahatang tuntunin, ilang pasaherong wala pang 21 taong gulang at hindi kapamilya ang puwedeng isakay ng Level 2 driver kapag walang supervising driver sa kotse?","o":["Wala","Tatlo","Isa","Apat"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Bilang pangkalahatang tuntunin, ang Level 2 driver sa North Carolina na walang supervisor ay puwedeng magsakay ng isang pasahero lang na wala pang 21 at hindi kasama sa sambahayan ng driver; puwedeng sumakay ang isa pang estudyante sa diretsong biyahe papunta o pauwi mula sa paaralan.","p":"Tama. Isang pasahero lang na wala pang 21."},"ar":{"q":"في North Carolina، كقاعدة عامة، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكن لسائق المستوى 2 أن ينقل عندما لا يكون في السيارة سائق مشرف؟","o":["لا أحد","ثلاثة","واحد","أربعة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"كقاعدة عامة، يمكن لسائق المستوى 2 في North Carolina بدون مشرف أن ينقل راكبًا واحدًا فقط عمره أقل من 21 سنة ولا يعيش في بيت السائق؛ ويمكن أن يركب طالب إضافي واحد في رحلة مباشرة إلى المدرسة أو منها.","p":"صحيح. راكب واحد فقط عمره أقل من 21 سنة."},"ref":{"doc":"NC","page":13}},{"id":"nc-011","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, when does the one-passenger-under-21 limit for Level 2 drivers not apply?","o":["When it is raining","When all the passengers live in the driver's household","When the passengers are over 16","On short trips"],"h1":"Think about who lives under the same roof.","h2":"The North Carolina Level 2 limit of one passenger under 21 does not apply when all the passengers are members of the driver's household.","p":"Right. Household members are the exception."},"es":{"q":"En Carolina del Norte, ¿cuándo no se aplica el límite de un pasajero menor de 21 años para conductores de Nivel 2?","o":["Cuando llueve","Cuando todos los pasajeros viven en el mismo hogar que el conductor","Cuando los pasajeros tienen más de 16 años","En viajes cortos"],"h1":"Piense en quién vive bajo el mismo techo.","h2":"El límite de un pasajero menor de 21 años para el Nivel 2 en Carolina del Norte no se aplica cuando todos los pasajeros son miembros del hogar del conductor.","p":"Correcto. Los miembros del hogar son la excepción."},"zh":{"q":"在 North Carolina，Level 2 司机只能载一位 21 岁以下乘客的限制，什么时候不适用？","o":["下雨的时候","所有乘客都和司机住在同一个家里时","乘客超过 16 岁时","短途的时候"],"h1":"想一想谁和你住在同一个屋檐下。","h2":"当所有乘客都是司机家里的成员时，North Carolina Level 2 只能载一位 21 岁以下乘客的限制就不适用。","p":"对。家里的成员是例外。"},"vi":{"q":"Ở North Carolina, khi nào giới hạn một hành khách dưới 21 tuổi cho người lái Cấp 2 không được áp dụng?","o":["Khi trời mưa","Khi tất cả hành khách sống cùng nhà với người lái","Khi hành khách trên 16 tuổi","Trên những chuyến đi ngắn"],"h1":"Hãy nghĩ đến những người sống dưới cùng một mái nhà.","h2":"Giới hạn một hành khách dưới 21 tuổi cho người lái Cấp 2 ở North Carolina không áp dụng khi tất cả hành khách là người sống cùng nhà với người lái.","p":"Đúng. Người sống cùng nhà là trường hợp ngoại lệ."},"tl":{"q":"Sa North Carolina, kailan hindi umiiral ang limitasyon na isang pasaherong wala pang 21 para sa mga Level 2 driver?","o":["Kapag umuulan","Kapag lahat ng pasahero ay nakatira sa sambahayan ng driver","Kapag ang mga pasahero ay higit sa 16","Sa maiikling biyahe"],"h1":"Isipin kung sino ang nakatira sa iisang bubong.","h2":"Hindi umiiral ang limitasyon ng North Carolina na isang pasaherong wala pang 21 para sa Level 2 kapag lahat ng pasahero ay kasapi ng sambahayan ng driver.","p":"Tama. Ang mga kasama sa bahay ang eksepsiyon."},"ar":{"q":"في North Carolina، متى لا يُطبَّق حدّ الراكب الواحد الذي عمره أقل من 21 سنة على سائقي المستوى 2؟","o":["عندما تمطر","عندما يعيش كل الركاب في بيت السائق","عندما يكون الركاب أكبر من 16 سنة","في الرحلات القصيرة"],"h1":"فكّر في من يعيشون تحت سقف واحد.","h2":"لا يُطبَّق حدّ الراكب الواحد الذي عمره أقل من 21 سنة على سائق المستوى 2 في North Carolina عندما يكون كل الركاب من أفراد بيت السائق.","p":"صحيح. أفراد البيت هم الاستثناء."},"ref":{"doc":"NC","page":13}},{"id":"nc-012","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, what changes when a teen moves to a Level 3 full provisional license?","o":["Nothing changes","The teen may no longer drive at night","The teen needs a new supervisor","The time, supervision and passenger limits of Levels 1 and 2 no longer apply"],"h1":"Level 3 is the last step before a regular license.","h2":"With a North Carolina Level 3 full provisional license, the time, supervision and passenger limits of Levels 1 and 2 no longer apply.","p":"Right. Level 3 lifts those limits."},"es":{"q":"En Carolina del Norte, ¿qué cambia cuando un adolescente pasa a la licencia provisional completa de Nivel 3?","o":["No cambia nada","Ya no puede manejar de noche","Necesita un nuevo supervisor","Ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2"],"h1":"El Nivel 3 es el último paso antes de una licencia regular.","h2":"Con la licencia provisional completa de Nivel 3 en Carolina del Norte, ya no se aplican los límites de horario, supervisión y pasajeros de los Niveles 1 y 2.","p":"Correcto. El Nivel 3 quita esos límites."},"zh":{"q":"在 North Carolina，青少年升到 Level 3 完整的临时驾照时，有什么改变？","o":["什么都不变","青少年不能再在晚上开车","青少年需要一位新的陪同人","Level 1 和 Level 2 的时间、陪同和乘客限制不再适用"],"h1":"Level 3 是拿普通驾照前的最后一步。","h2":"持 North Carolina Level 3 完整的临时驾照时，Level 1 和 Level 2 的时间、陪同和乘客限制都不再适用。","p":"对。Level 3 取消了这些限制。"},"vi":{"q":"Ở North Carolina, điều gì thay đổi khi một thanh thiếu niên lên bằng tạm thời đầy đủ Cấp 3 (Level 3 full provisional license)?","o":["Không có gì thay đổi","Thanh thiếu niên không còn được lái xe vào ban đêm","Thanh thiếu niên cần một người giám sát mới","Các giới hạn về giờ lái, người giám sát và hành khách của Cấp 1 và Cấp 2 không còn áp dụng"],"h1":"Cấp 3 là bước cuối cùng trước bằng lái thông thường.","h2":"Với bằng tạm thời đầy đủ Cấp 3 ở North Carolina, các giới hạn về giờ lái, người giám sát và hành khách của Cấp 1 và Cấp 2 không còn áp dụng.","p":"Đúng. Cấp 3 bỏ những giới hạn đó."},"tl":{"q":"Sa North Carolina, ano ang nagbabago kapag lumipat ang isang kabataan sa Level 3 full provisional license?","o":["Walang nagbabago","Hindi na puwedeng magmaneho sa gabi ang kabataan","Kailangan ng kabataan ng bagong supervisor","Hindi na umiiral ang mga limitasyon sa oras, supervision at pasahero ng Level 1 at 2"],"h1":"Ang Level 3 ang huling hakbang bago ang regular na lisensya.","h2":"Sa Level 3 full provisional license sa North Carolina, hindi na umiiral ang mga limitasyon sa oras, supervision at pasahero ng Level 1 at 2.","p":"Tama. Inaalis ng Level 3 ang mga limitasyong iyon."},"ar":{"q":"في North Carolina، ما الذي يتغيّر عندما ينتقل المراهق إلى الرخصة المؤقتة الكاملة من المستوى 3 (Level 3 full provisional license)؟","o":["لا شيء يتغيّر","لا يعود المراهق يستطيع القيادة في الليل","يحتاج المراهق إلى مشرف جديد","لا تعود قيود الوقت والإشراف والركاب في المستويين 1 و2 مطبّقة"],"h1":"المستوى 3 هو الخطوة الأخيرة قبل الرخصة العادية.","h2":"مع الرخصة المؤقتة الكاملة من المستوى 3 في North Carolina، لا تعود قيود الوقت والإشراف والركاب في المستويين 1 و2 مطبّقة.","p":"صحيح. المستوى 3 يرفع تلك القيود."},"ref":{"doc":"NC","page":13}},{"id":"nc-013","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, may a driver under 18 talk on a hands-free phone while driving?","o":["Yes, hands-free is always allowed","Yes, but only on highways","No, drivers under 18 may not use a phone at all, hands-free included","Yes, if a friend is in the car"],"h1":"For teens, the rule is stricter than for adults.","h2":"In North Carolina a driver under 18 may not use a mobile phone while driving, even a hands-free one, except for a few emergency and family calls.","p":"Right. Under 18, no phone, even hands-free."},"es":{"q":"En Carolina del Norte, ¿puede un conductor menor de 18 años hablar por teléfono con manos libres mientras maneja?","o":["Sí, el manos libres siempre está permitido","Sí, pero solo en carreteras","No, los menores de 18 no pueden usar el teléfono, ni siquiera con manos libres","Sí, si va un amigo en el carro"],"h1":"Para los adolescentes, la regla es más estricta que para los adultos.","h2":"En Carolina del Norte un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, salvo algunas llamadas de emergencia y de familia.","p":"Correcto. Menores de 18: nada de teléfono, ni con manos libres."},"zh":{"q":"在 North Carolina，18 岁以下的司机开车时可以用免提手机通话吗？","o":["可以，免提一直都可以","可以，但只在公路上","不可以，18 岁以下的司机完全不能用手机，免提也不行","可以，如果车里有朋友"],"h1":"对青少年来说，规定比成年人更严格。","h2":"在 North Carolina，18 岁以下的司机开车时不能用手机，免提的也不行，只有几种紧急和家人电话例外。","p":"对。18 岁以下，不能用手机，免提也不行。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 18 tuổi có được nói chuyện qua điện thoại rảnh tay (hands-free) khi lái xe không?","o":["Có, rảnh tay thì luôn được phép","Có, nhưng chỉ trên xa lộ","Không, người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại, kể cả rảnh tay","Có, nếu có bạn ngồi trong xe"],"h1":"Đối với thanh thiếu niên, quy định nghiêm hơn so với người lớn.","h2":"Ở North Carolina, người lái xe dưới 18 tuổi không được dùng điện thoại di động khi lái xe, kể cả loại rảnh tay, trừ một vài cuộc gọi khẩn cấp và gọi cho gia đình.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa North Carolina, puwede bang makipag-usap sa hands-free na telepono ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, palaging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, hindi puwedeng gumamit ng telepono ang mga driver na wala pang 18, kasama ang hands-free","Oo, kung may kaibigan sa kotse"],"h1":"Para sa mga kabataan, mas mahigpit ang tuntunin kaysa sa mga adult.","h2":"Sa North Carolina, hindi puwedeng gumamit ng mobile phone habang nagmamaneho ang driver na wala pang 18, kahit hands-free, maliban sa ilang tawag para sa emergency at pamilya.","p":"Tama. Wala pang 18, bawal ang telepono, kahit hands-free."},"ar":{"q":"في North Carolina، هل يمكن للسائق الذي عمره أقل من 18 سنة أن يتكلّم بهاتف بدون استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون يدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","لا، السائقون الذين أعمارهم أقل من 18 سنة لا يستخدمون الهاتف أبدًا، حتى بدون يدين","نعم، إذا كان صديق في السيارة"],"h1":"بالنسبة للمراهقين، القاعدة أشدّ منها للكبار.","h2":"في North Carolina لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة، حتى بدون يدين، إلا في بعض مكالمات الطوارئ والعائلة.","p":"صحيح. أقل من 18 سنة، لا هاتف، حتى بدون يدين."},"ref":{"doc":"NC","page":41}},{"id":"nc-014","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which phone call may a driver under 18 make while driving?","o":["A call to a friend","A call to a parent, legal guardian or spouse","A call to order food","Any call shorter than one minute"],"h1":"The exception is for emergencies and close family.","h2":"A North Carolina driver under 18 may call a parent, legal guardian or spouse, or emergency services, while driving; other calls are not allowed.","p":"Right. A parent, guardian or spouse is allowed."},"es":{"q":"En Carolina del Norte, ¿qué llamada puede hacer un conductor menor de 18 años mientras maneja?","o":["Una llamada a un amigo","Una llamada a su padre, madre, tutor legal o cónyuge","Una llamada para pedir comida","Cualquier llamada de menos de un minuto"],"h1":"La excepción es para emergencias y familia cercana.","h2":"Un conductor menor de 18 años en Carolina del Norte puede llamar a su padre, madre, tutor legal o cónyuge, o a servicios de emergencia, mientras maneja; otras llamadas no están permitidas.","p":"Correcto. Puede llamar a su padre, madre, tutor o cónyuge."},"zh":{"q":"在 North Carolina，18 岁以下的司机开车时可以打哪一种电话？","o":["打给朋友","打给父母、法定监护人或配偶","打电话订餐","任何一分钟以内的电话"],"h1":"例外是给紧急情况和亲近家人的。","h2":"North Carolina 18 岁以下的司机开车时可以打电话给父母、法定监护人或配偶，或者打给紧急服务；其他电话都不可以。","p":"对。可以打给父母、监护人或配偶。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 18 tuổi được gọi cuộc điện thoại nào khi đang lái xe?","o":["Gọi cho bạn bè","Gọi cho cha mẹ, người giám hộ hợp pháp hoặc vợ/chồng","Gọi để đặt đồ ăn","Bất kỳ cuộc gọi nào ngắn hơn một phút"],"h1":"Ngoại lệ dành cho trường hợp khẩn cấp và gia đình gần gũi.","h2":"Người lái xe dưới 18 tuổi ở North Carolina được gọi cho cha mẹ, người giám hộ hợp pháp hoặc vợ/chồng, hoặc gọi dịch vụ khẩn cấp, khi đang lái xe; các cuộc gọi khác không được phép.","p":"Đúng. Được gọi cho cha mẹ, người giám hộ hoặc vợ/chồng."},"tl":{"q":"Sa North Carolina, anong tawag sa telepono ang puwedeng gawin ng driver na wala pang 18 habang nagmamaneho?","o":["Tawag sa kaibigan","Tawag sa magulang, legal na tagapag-alaga o asawa","Tawag para umorder ng pagkain","Kahit anong tawag na mas maikli sa isang minuto"],"h1":"Ang eksepsiyon ay para sa emergency at malapit na pamilya.","h2":"Ang driver sa North Carolina na wala pang 18 ay puwedeng tumawag sa magulang, legal na tagapag-alaga o asawa, o sa emergency services, habang nagmamaneho; hindi pinapayagan ang ibang tawag.","p":"Tama. Pinapayagan ang magulang, tagapag-alaga o asawa."},"ar":{"q":"في North Carolina، أي مكالمة هاتفية يمكن للسائق الذي عمره أقل من 18 سنة أن يجريها أثناء القيادة؟","o":["مكالمة لصديق","مكالمة لأحد الوالدين أو الوصي القانوني أو الزوج أو الزوجة","مكالمة لطلب طعام","أي مكالمة أقصر من دقيقة واحدة"],"h1":"الاستثناء للطوارئ وللعائلة القريبة.","h2":"يمكن للسائق في North Carolina الذي عمره أقل من 18 سنة أن يتّصل بأحد الوالدين أو الوصي القانوني أو الزوج أو الزوجة، أو بخدمات الطوارئ، أثناء القيادة؛ والمكالمات الأخرى غير مسموحة.","p":"صحيح. الوالدان أو الوصي أو الزوج أو الزوجة مسموح."},"ref":{"doc":"NC","page":12}},{"id":"nc-015","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, may an adult driver read a text message while the car is moving?","o":["No, no driver may text or read texts while the car is moving","Yes, if the message is short","Yes, on empty roads","Yes, if the driver is over 21"],"h1":"This rule applies to drivers of every age.","h2":"North Carolina bans all drivers, of any age, from texting or reading a text message while the vehicle is moving.","p":"Right. No texting while moving, at any age."},"es":{"q":"En Carolina del Norte, ¿puede un conductor adulto leer un mensaje de texto mientras el carro está en movimiento?","o":["No, ningún conductor puede escribir ni leer mensajes mientras el carro está en movimiento","Sí, si el mensaje es corto","Sí, en calles vacías","Sí, si el conductor tiene más de 21 años"],"h1":"Esta regla es para conductores de todas las edades.","h2":"Carolina del Norte prohíbe a todos los conductores, de cualquier edad, escribir o leer mensajes de texto mientras el vehículo está en movimiento.","p":"Correcto. Nada de mensajes en movimiento, a ninguna edad."},"zh":{"q":"在 North Carolina，成年司机可以在车开动时看短信吗？","o":["不可以，车在开动时任何司机都不能发短信或看短信","可以，如果短信很短","可以，在没车的路上","可以，如果司机超过 21 岁"],"h1":"这条规定适用于所有年龄的司机。","h2":"North Carolina 禁止所有司机，不管几岁，在车开动时发短信或看短信。","p":"对。不管几岁，车在开时都不能发短信。"},"vi":{"q":"Ở North Carolina, người lái xe trưởng thành có được đọc tin nhắn khi xe đang chạy không?","o":["Không, không người lái xe nào được nhắn tin hoặc đọc tin nhắn khi xe đang chạy","Có, nếu tin nhắn ngắn","Có, trên đường vắng","Có, nếu người lái trên 21 tuổi"],"h1":"Quy định này áp dụng cho người lái xe ở mọi lứa tuổi.","h2":"North Carolina cấm tất cả người lái xe, ở mọi lứa tuổi, nhắn tin hoặc đọc tin nhắn khi xe đang chạy.","p":"Đúng. Không nhắn tin khi xe đang chạy, ở mọi lứa tuổi."},"tl":{"q":"Sa North Carolina, puwede bang magbasa ng text message ang adult na driver habang umaandar ang kotse?","o":["Hindi, walang driver na puwedeng mag-text o magbasa ng text habang umaandar ang kotse","Oo, kung maikli ang mensahe","Oo, sa walang laman na kalsada","Oo, kung ang driver ay higit sa 21"],"h1":"Para sa mga driver sa lahat ng edad ang tuntuning ito.","h2":"Ipinagbabawal ng North Carolina sa lahat ng driver, anuman ang edad, ang pag-text o pagbasa ng text message habang umaandar ang sasakyan.","p":"Tama. Bawal mag-text habang umaandar, sa anumang edad."},"ar":{"q":"في North Carolina، هل يمكن للسائق البالغ أن يقرأ رسالة نصية بينما السيارة تتحرك؟","o":["لا، لا يجوز لأي سائق أن يكتب أو يقرأ رسائل نصية بينما السيارة تتحرك","نعم، إذا كانت الرسالة قصيرة","نعم، على الطرق الفارغة","نعم، إذا كان عمر السائق أكثر من 21 سنة"],"h1":"هذه القاعدة تنطبق على السائقين من كل الأعمار.","h2":"تمنع North Carolina كل السائقين، من أي عمر، من كتابة أو قراءة الرسائل النصية بينما المركبة تتحرك.","p":"صحيح. لا رسائل نصية أثناء الحركة، في أي عمر."},"ref":{"doc":"NC","page":41}},{"id":"nc-016","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, a school bus stops with its stop arm out on a two-lane road with a center turn lane. Who must stop?","o":["Only traffic behind the bus","Only traffic coming toward the bus","No one, because the turn lane separates traffic","Traffic in both directions"],"h1":"On a road with only two lanes, the turn lane does not change the rule.","h2":"In North Carolina, on a two-lane road with a center turn lane, traffic in both directions must stop for a stopped school bus.","p":"Right. Both directions stop."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene con el brazo de alto extendido en una calle de dos carriles con un carril central para girar. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie, porque el carril para girar separa el tráfico","El tráfico en ambas direcciones"],"h1":"En una calle de solo dos carriles, el carril para girar no cambia la regla.","h2":"En Carolina del Norte, en una calle de dos carriles con carril central para girar, el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Ambas direcciones se detienen."},"zh":{"q":"在 North Carolina，一辆校车在有中央转弯车道的双车道路上停下，伸出停车臂。谁必须停车？","o":["只有校车后面的车","只有朝校车开过来的车","没有人，因为转弯车道把车流分开了","两个方向的车"],"h1":"在只有两条车道的路上，转弯车道不会改变规定。","h2":"在 North Carolina，在有中央转弯车道的双车道路上，两个方向的车都必须为停着的校车停车。","p":"对。两个方向都要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại và giơ cần báo dừng (stop arm) trên con đường hai làn có làn rẽ ở giữa. Ai phải dừng lại?","o":["Chỉ xe ở phía sau xe buýt","Chỉ xe đang đi về phía xe buýt","Không ai, vì làn rẽ ngăn cách hai chiều xe","Xe ở cả hai chiều"],"h1":"Trên con đường chỉ có hai làn, làn rẽ không làm thay đổi quy định.","h2":"Ở North Carolina, trên con đường hai làn có làn rẽ ở giữa, xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng.","p":"Đúng. Cả hai chiều đều dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus na nakalabas ang stop arm sa kalsadang may dalawang lane at may center turn lane sa gitna. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang mga sasakyan lang na papalapit sa bus","Wala, dahil hinahati ng turn lane ang trapiko","Ang mga sasakyan sa magkabilang direksyon"],"h1":"Sa kalsadang may dalawang lane lang, hindi binabago ng turn lane ang tuntunin.","h2":"Sa North Carolina, sa kalsadang may dalawang lane at center turn lane, dapat huminto ang mga sasakyan sa magkabilang direksyon para sa nakahintong school bus.","p":"Tama. Humihinto ang magkabilang direksyon."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية وذراع التوقّف (stop arm) مفتوح على طريق بمسارين مع مسار للانعطاف في الوسط. من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد، لأن مسار الانعطاف يفصل بين الاتجاهين","السيارات في الاتجاهين"],"h1":"على طريق بمسارين فقط، مسار الانعطاف لا يغيّر القاعدة.","h2":"في North Carolina، على طريق بمسارين مع مسار للانعطاف في الوسط، يجب أن تتوقّف السيارات في الاتجاهين عند توقّف الحافلة المدرسية.","p":"صحيح. الاتجاهان يتوقّفان."},"ref":{"doc":"NC","page":48}},{"id":"nc-017","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, a school bus stops on a four-lane road with no median, only painted lines. Who must stop?","o":["Only traffic behind the bus","Only the lane next to the bus","Traffic in both directions","No one"],"h1":"Painted lines do not separate the two sides.","h2":"In North Carolina, on a four-lane road with no median, all traffic in both directions must stop for a stopped school bus.","p":"Right. With no median, everyone stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una calle de cuatro carriles sin mediana, solo con líneas pintadas. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el carril al lado del autobús","El tráfico en ambas direcciones","Nadie"],"h1":"Las líneas pintadas no separan los dos lados.","h2":"En Carolina del Norte, en una calle de cuatro carriles sin mediana, todo el tráfico en ambas direcciones debe detenerse por un autobús escolar detenido.","p":"Correcto. Sin mediana, todos se detienen."},"zh":{"q":"在 North Carolina，一辆校车在没有中央隔离带、只有画线的四车道路上停下。谁必须停车？","o":["只有校车后面的车","只有校车旁边车道的车","两个方向的车","没有人"],"h1":"画的线不能把两边分开。","h2":"在 North Carolina，在没有中央隔离带的四车道路上，两个方向的所有车都必须为停着的校车停车。","p":"对。没有隔离带时，每个人都要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại trên con đường bốn làn không có dải phân cách, chỉ có vạch sơn. Ai phải dừng lại?","o":["Chỉ xe ở phía sau xe buýt","Chỉ làn bên cạnh xe buýt","Xe ở cả hai chiều","Không ai"],"h1":"Vạch sơn không ngăn cách hai bên đường.","h2":"Ở North Carolina, trên con đường bốn làn không có dải phân cách, tất cả xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng.","p":"Đúng. Không có dải phân cách thì mọi người đều dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus sa kalsadang may apat na lane na walang median, may pinturang guhit lang. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang lane lang na katabi ng bus","Ang mga sasakyan sa magkabilang direksyon","Wala"],"h1":"Hindi hinahati ng pinturang guhit ang dalawang panig.","h2":"Sa North Carolina, sa kalsadang may apat na lane na walang median, dapat huminto ang lahat ng sasakyan sa magkabilang direksyon para sa nakahintong school bus.","p":"Tama. Kapag walang median, humihinto ang lahat."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية على طريق بأربعة مسارات بدون فاصل في الوسط، فقط خطوط مرسومة. من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","المسار الذي بجانب الحافلة فقط","السيارات في الاتجاهين","لا أحد"],"h1":"الخطوط المرسومة لا تفصل بين جانبي الطريق.","h2":"في North Carolina، على طريق بأربعة مسارات بدون فاصل في الوسط، يجب أن تتوقّف كل السيارات في الاتجاهين عند توقّف الحافلة المدرسية.","p":"صحيح. بدون فاصل، الجميع يتوقّف."},"ref":{"doc":"NC","page":48}},{"id":"nc-018","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, a school bus stops on a divided highway with a median. Who must stop?","o":["Traffic in both directions","Only traffic following the bus","Only traffic coming toward the bus","No one"],"h1":"A median protects the other side of the road.","h2":"In North Carolina, on a divided highway with a median, only the traffic following the bus must stop.","p":"Right. Only traffic behind the bus stops."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene en una carretera dividida con mediana. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico que va detrás del autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"Una mediana protege el otro lado de la carretera.","h2":"En Carolina del Norte, en una carretera dividida con mediana, solo el tráfico que va detrás del autobús debe detenerse.","p":"Correcto. Solo se detiene el tráfico detrás del autobús."},"zh":{"q":"在 North Carolina，一辆校车在有中央隔离带的分隔公路上停下。谁必须停车？","o":["两个方向的车","只有跟在校车后面的车","只有朝校车开过来的车","没有人"],"h1":"中央隔离带保护着路的另一边。","h2":"在 North Carolina，在有中央隔离带的分隔公路上，只有跟在校车后面的车必须停车。","p":"对。只有校车后面的车要停。"},"vi":{"q":"Ở North Carolina, một xe buýt trường học dừng lại trên xa lộ có dải phân cách ở giữa. Ai phải dừng lại?","o":["Xe ở cả hai chiều","Chỉ xe đi theo sau xe buýt","Chỉ xe đang đi về phía xe buýt","Không ai"],"h1":"Dải phân cách bảo vệ phía bên kia đường.","h2":"Ở North Carolina, trên xa lộ có dải phân cách ở giữa, chỉ xe đi theo sau xe buýt phải dừng lại.","p":"Đúng. Chỉ xe phía sau xe buýt phải dừng."},"tl":{"q":"Sa North Carolina, huminto ang isang school bus sa divided highway na may median. Sino ang dapat huminto?","o":["Ang mga sasakyan sa magkabilang direksyon","Ang mga sasakyan lang na sumusunod sa bus","Ang mga sasakyan lang na papalapit sa bus","Wala"],"h1":"Pinoprotektahan ng median ang kabilang panig ng kalsada.","h2":"Sa North Carolina, sa divided highway na may median, ang mga sasakyan lang na sumusunod sa bus ang dapat huminto.","p":"Tama. Ang mga sasakyan lang sa likod ng bus ang humihinto."},"ar":{"q":"في North Carolina، توقّفت حافلة مدرسية على طريق سريع مقسوم بفاصل في الوسط. من يجب أن يتوقّف؟","o":["السيارات في الاتجاهين","السيارات التي تسير خلف الحافلة فقط","السيارات القادمة نحو الحافلة فقط","لا أحد"],"h1":"الفاصل في الوسط يحمي الجانب الآخر من الطريق.","h2":"في North Carolina، على طريق سريع مقسوم بفاصل في الوسط، يجب أن تتوقّف فقط السيارات التي تسير خلف الحافلة.","p":"صحيح. فقط السيارات خلف الحافلة تتوقّف."},"ref":{"doc":"NC","page":48}},{"id":"nc-019","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, what does the Move Over Law require when you approach an emergency vehicle stopped on the side of the road with lights flashing?","o":["Keep your speed and lane","Stop behind it","Honk and pass quickly","Move over a lane, or slow down and be ready to stop if you cannot"],"h1":"There is a first choice, and a second choice when the first is not possible.","h2":"North Carolina's Move Over Law requires you to move over a lane, or, if you cannot, slow down to a speed that lets you stop if needed.","p":"Right. Move over, or slow down."},"es":{"q":"En Carolina del Norte, ¿qué exige la Ley de Cambio de Carril (Move Over) cuando usted se acerca a un vehículo de emergencia detenido al lado de la carretera con luces intermitentes?","o":["Mantener su velocidad y su carril","Detenerse detrás de él","Tocar la bocina y pasar rápido","Cambiarse un carril o, si no puede, bajar la velocidad y estar listo para detenerse"],"h1":"Hay una primera opción, y una segunda cuando la primera no es posible.","h2":"La Ley de Cambio de Carril de Carolina del Norte exige que usted se cambie un carril o, si no puede, que baje a una velocidad que le permita detenerse si hace falta.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 North Carolina，当你接近一辆停在路边、闪着灯的急救车辆时，Move Over Law 要求你怎么做？","o":["保持速度和车道","在它后面停车","按喇叭，很快开过去","换开一条车道；如果不能，就减速并准备停车"],"h1":"有第一个选择，第一个做不到时还有第二个选择。","h2":"North Carolina 的 Move Over Law 要求你换开一条车道；如果不能，就减速到需要时可以停下来的速度。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở North Carolina, Luật Tránh Sang Làn Khác (Move Over Law) yêu cầu gì khi bạn đến gần một xe cấp cứu đang dừng bên lề đường và nháy đèn?","o":["Giữ nguyên tốc độ và làn xe","Dừng lại phía sau xe đó","Bấm còi và vượt qua thật nhanh","Chuyển sang một làn khác, hoặc nếu không thể thì chạy chậm lại và sẵn sàng dừng"],"h1":"Có một lựa chọn đầu tiên, và một lựa chọn thứ hai khi không làm được lựa chọn đầu tiên.","h2":"Luật Move Over của North Carolina yêu cầu bạn chuyển sang một làn khác, hoặc nếu không thể, phải giảm tốc độ đến mức có thể dừng lại khi cần.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại."},"tl":{"q":"Sa North Carolina, ano ang hinihingi ng Move Over Law kapag papalapit ka sa emergency vehicle na nakahinto sa gilid ng kalsada at may kumikislap na ilaw?","o":["Panatilihin ang bilis at lane mo","Huminto sa likod nito","Bumusina at lumampas nang mabilis","Lumipat ng isang lane, o kung hindi mo kaya, bumagal at maging handang huminto"],"h1":"May unang pagpipilian, at pangalawa kapag hindi posible ang una.","h2":"Hinihingi ng Move Over Law ng North Carolina na lumipat ka ng isang lane, o kung hindi mo kaya, bumagal sa bilis na makakapagpahinto sa iyo kung kailangan.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في North Carolina، ماذا يطلب قانون الابتعاد (Move Over Law) عندما تقترب من مركبة طوارئ متوقّفة على جانب الطريق وأضواؤها تومض؟","o":["حافظ على سرعتك ومسارك","توقّف خلفها","استخدم البوق وتجاوزها بسرعة","انتقل إلى مسار آخر، أو إذا لم تستطع، خفّف السرعة وكن مستعدًا للتوقّف"],"h1":"هناك خيار أول، وخيار ثانٍ عندما لا يكون الأول ممكنًا.","h2":"يطلب قانون Move Over في North Carolina أن تنتقل إلى مسار آخر، أو إذا لم تستطع، أن تخفّف سرعتك إلى سرعة تسمح لك بالتوقّف عند الحاجة.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة."},"ref":{"doc":"NC","page":49}},{"id":"nc-020","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"For drivers under 21, the rule is the strictest possible.","h2":"In North Carolina a driver under 21 may not have any alcohol in their body while driving; the 0.08 limit is only for drivers 21 and older.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Carolina del Norte, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"Para menores de 21, la regla es la más estricta posible.","h2":"En Carolina del Norte un conductor menor de 21 años no puede tener nada de alcohol en el cuerpo mientras maneja; el límite de 0.08 es solo para conductores de 21 años o más.","p":"Correcto. Menores de 21: nada de alcohol."},"zh":{"q":"在 North Carolina，21 岁以下的司机开车时体内可以有多少酒精？","o":["一点都不行","最多 0.02%","最多 0.05%","最多 0.08%"],"h1":"对 21 岁以下的司机，规定是最严格的。","h2":"在 North Carolina，21 岁以下的司机开车时体内不能有任何酒精；0.08 的限值只适用于 21 岁及以上的司机。","p":"对。21 岁以下，完全不能有酒精。"},"vi":{"q":"Ở North Carolina, người lái xe dưới 21 tuổi được có bao nhiêu rượu trong cơ thể khi lái xe?","o":["Hoàn toàn không có","Tối đa 0.02 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.08 phần trăm"],"h1":"Đối với người lái dưới 21 tuổi, quy định nghiêm ngặt nhất có thể.","h2":"Ở North Carolina, người lái xe dưới 21 tuổi không được có chút rượu nào trong cơ thể khi lái xe; mức giới hạn 0.08 chỉ dành cho người lái từ 21 tuổi trở lên.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có rượu."},"tl":{"q":"Sa North Carolina, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21 habang nagmamaneho?","o":["Wala talaga","Hanggang 0.02 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.08 porsiyento"],"h1":"Para sa mga driver na wala pang 21, ang tuntunin ang pinakamahigpit.","h2":"Sa North Carolina, hindi puwedeng may kahit anong alak sa katawan ang driver na wala pang 21 habang nagmamaneho; ang limitasyong 0.08 ay para lang sa mga driver na 21 pataas.","p":"Tama. Wala pang 21, walang alak talaga."},"ar":{"q":"في North Carolina، كم من الكحول يمكن أن يكون في جسم السائق الذي عمره أقل من 21 سنة أثناء القيادة؟","o":["لا شيء على الإطلاق","حتى 0.02 بالمئة","حتى 0.05 بالمئة","حتى 0.08 بالمئة"],"h1":"للسائقين الذين أعمارهم أقل من 21 سنة، القاعدة هي الأشدّ.","h2":"في North Carolina لا يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة أي كحول أثناء القيادة؛ وحدّ 0.08 هو فقط للسائقين الذين أعمارهم 21 سنة فأكثر.","p":"صحيح. أقل من 21 سنة، لا كحول على الإطلاق."},"ref":{"doc":"NC","page":33}},{"id":"nc-021","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, how many driver license points within three years can lead to a license suspension?","o":["4 points","7 points","12 points","10 points"],"h1":"It is more than the number that sends you to a driver improvement clinic.","h2":"In North Carolina, your license may be suspended if you collect 12 points within three years.","p":"Right. 12 points in three years can mean a suspension."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia dentro de tres años pueden llevar a una suspensión?","o":["4 puntos","7 puntos","12 puntos","10 puntos"],"h1":"Es más que el número que lo manda a una clínica para mejorar como conductor.","h2":"En Carolina del Norte, su licencia puede ser suspendida si acumula 12 puntos dentro de tres años.","p":"Correcto. 12 puntos en tres años pueden causar una suspensión."},"zh":{"q":"在 North Carolina，三年内累计多少驾照扣分可能导致驾照被暂停？","o":["4 分","7 分","12 分","10 分"],"h1":"它比让你去上驾驶改进课（driver improvement clinic）的分数多。","h2":"在 North Carolina，如果你在三年内累计 12 分，你的驾照可能会被暂停。","p":"对。三年内 12 分可能导致驾照被暂停。"},"vi":{"q":"Ở North Carolina, bao nhiêu điểm phạt trên bằng lái trong vòng ba năm có thể làm bằng lái bị đình chỉ?","o":["4 điểm","7 điểm","12 điểm","10 điểm"],"h1":"Con số này nhiều hơn số điểm khiến bạn phải đi học lớp cải thiện kỹ năng lái xe (driver improvement clinic).","h2":"Ở North Carolina, bằng lái của bạn có thể bị đình chỉ nếu bạn bị 12 điểm trong vòng ba năm.","p":"Đúng. 12 điểm trong ba năm có thể dẫn đến đình chỉ bằng lái."},"tl":{"q":"Sa North Carolina, ilang point sa driver license sa loob ng tatlong taon ang puwedeng humantong sa suspensyon ng lisensya?","o":["4 na point","7 point","12 point","10 point"],"h1":"Mas marami ito kaysa sa bilang na magpapapunta sa iyo sa driver improvement clinic.","h2":"Sa North Carolina, puwedeng masuspinde ang lisensya mo kung makaipon ka ng 12 point sa loob ng tatlong taon.","p":"Tama. Ang 12 point sa tatlong taon ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في North Carolina، كم نقطة على رخصة القيادة خلال ثلاث سنوات قد تؤدي إلى إيقاف الرخصة؟","o":["4 نقاط","7 نقاط","12 نقطة","10 نقاط"],"h1":"هو أكثر من العدد الذي يرسلك إلى دورة تحسين القيادة (driver improvement clinic).","h2":"في North Carolina، قد تُوقَف رخصتك إذا جمعت 12 نقطة خلال ثلاث سنوات.","p":"صحيح. 12 نقطة في ثلاث سنوات قد تعني إيقاف الرخصة."},"ref":{"doc":"NC","page":34}},{"id":"nc-022","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many license points do you get for passing a stopped school bus?","o":["5 points","1 point","2 points","3 points"],"h1":"It is one of the highest point values on the list for regular drivers.","h2":"In North Carolina, passing a stopped school bus puts 5 points on your license.","p":"Right. Passing a stopped school bus costs 5 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por rebasar un autobús escolar detenido?","o":["5 puntos","1 punto","2 puntos","3 puntos"],"h1":"Es uno de los valores más altos de la lista para conductores comunes.","h2":"En Carolina del Norte, rebasar un autobús escolar detenido pone 5 puntos en su licencia.","p":"Correcto. Rebasar un autobús escolar detenido cuesta 5 puntos."},"zh":{"q":"在 North Carolina，超越停着的校车会被扣多少驾照分？","o":["5 分","1 分","2 分","3 分"],"h1":"这是普通驾驶人扣分表上最高的分数之一。","h2":"在 North Carolina，超越停着的校车会在你的驾照上记 5 分。","p":"对。超越停着的校车要扣 5 分。"},"vi":{"q":"Ở North Carolina, bạn bị bao nhiêu điểm phạt trên bằng lái khi vượt qua một xe buýt trường học đang dừng?","o":["5 điểm","1 điểm","2 điểm","3 điểm"],"h1":"Đây là một trong những mức điểm cao nhất trong danh sách dành cho tài xế thông thường.","h2":"Ở North Carolina, vượt qua một xe buýt trường học đang dừng sẽ bị ghi 5 điểm vào bằng lái của bạn.","p":"Đúng. Vượt xe buýt trường học đang dừng bị 5 điểm."},"tl":{"q":"Sa North Carolina, ilang puntos sa lisensya ang makukuha mo kapag nilampasan mo ang isang nakahintong school bus?","o":["5 puntos","1 punto","2 puntos","3 puntos"],"h1":"Isa ito sa pinakamataas na puntos sa listahan para sa karaniwang mga driver.","h2":"Sa North Carolina, ang paglampas sa isang nakahintong school bus ay naglalagay ng 5 puntos sa lisensya mo.","p":"Tama. 5 puntos ang kapalit ng paglampas sa nakahintong school bus."},"ar":{"q":"في North Carolina، كم نقطة تُسجَّل على رخصتك إذا تجاوزت حافلة مدرسية متوقفة؟","o":["5 نقاط","نقطة واحدة (1)","نقطتان (2)","3 نقاط"],"h1":"هي من أعلى قيم النقاط في القائمة للسائقين العاديين.","h2":"في North Carolina، تجاوز حافلة مدرسية متوقفة يضع 5 نقاط على رخصتك.","p":"صحيح. تجاوز حافلة مدرسية متوقفة يكلّفك 5 نقاط."},"ref":{"doc":"NC","page":34}},{"id":"nc-023","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, a driver charged with impaired driving refuses a breath or blood test. What happens to the license?","o":["Nothing, if the driver was not drunk","A warning letter from the DMV","A fine, but no loss of license","At least 30 days right away, plus at least 12 months from the DMV"],"h1":"Refusing the test is treated very seriously.","h2":"In North Carolina, refusing the test means the license is taken right away for at least 30 days, and the DMV adds at least 12 more months.","p":"Right. Refusing the test costs your license for a long time."},"es":{"q":"En Carolina del Norte, a un conductor acusado de manejar bajo los efectos se le pide una prueba de aliento o de sangre y se niega. ¿Qué pasa con su licencia?","o":["Nada, si el conductor no estaba ebrio","Una carta de advertencia del DMV","Una multa, pero no pierde la licencia","Al menos 30 días de inmediato, más al menos 12 meses por parte del DMV"],"h1":"Negarse a la prueba se toma muy en serio.","h2":"En Carolina del Norte, negarse a la prueba significa que le quitan la licencia de inmediato por al menos 30 días, y el DMV agrega al menos 12 meses más.","p":"Correcto. Negarse a la prueba le cuesta la licencia por mucho tiempo."},"zh":{"q":"在 North Carolina，一名被控酒后或药后驾驶（impaired driving）的驾驶人拒绝做呼气或血液检测。驾照会怎样？","o":["如果驾驶人没喝醉，就没有任何事","DMV 寄一封警告信","罚款，但不会失去驾照","马上被收走至少 30 天，DMV 还会再加至少 12 个月"],"h1":"拒绝检测会被非常严肃地处理。","h2":"在 North Carolina，拒绝检测意味着驾照马上被收走至少 30 天，DMV 还会再加至少 12 个月。","p":"对。拒绝检测会让你很长时间失去驾照。"},"vi":{"q":"Ở North Carolina, một tài xế bị buộc tội lái xe khi say (impaired driving) từ chối thử hơi thở hoặc thử máu. Bằng lái sẽ ra sao?","o":["Không sao cả, nếu tài xế không say","Một lá thư cảnh cáo từ DMV","Bị phạt tiền, nhưng không mất bằng lái","Bị tước ngay ít nhất 30 ngày, cộng thêm ít nhất 12 tháng từ DMV"],"h1":"Từ chối thử nghiệm bị xem là rất nghiêm trọng.","h2":"Ở North Carolina, từ chối thử nghiệm nghĩa là bằng lái bị tước ngay ít nhất 30 ngày, và DMV cộng thêm ít nhất 12 tháng nữa.","p":"Đúng. Từ chối thử nghiệm khiến bạn mất bằng lái trong thời gian dài."},"tl":{"q":"Sa North Carolina, isang driver na kinasuhan ng impaired driving ang tumanggi sa breath o blood test. Ano ang mangyayari sa lisensya?","o":["Wala, kung hindi lasing ang driver","Isang sulat ng babala mula sa DMV","Multa, pero hindi mawawala ang lisensya","Hindi bababa sa 30 araw agad-agad, at hindi bababa sa 12 buwan pa mula sa DMV"],"h1":"Itinuturing na napakaseryoso ang pagtanggi sa test.","h2":"Sa North Carolina, kapag tumanggi ka sa test, kukunin agad ang lisensya nang hindi bababa sa 30 araw, at magdadagdag pa ang DMV ng hindi bababa sa 12 buwan.","p":"Tama. Ang pagtanggi sa test ay magpapawala ng lisensya mo nang matagal."},"ar":{"q":"في North Carolina، سائق متهم بالقيادة تحت التأثير (impaired driving) يرفض فحص النَّفَس أو الدم. ماذا يحدث للرخصة؟","o":["لا شيء، إذا لم يكن السائق سكرانًا","رسالة تحذير من DMV","غرامة، لكن بدون فقدان الرخصة","30 يومًا على الأقل فورًا، ثم 12 شهرًا على الأقل من DMV"],"h1":"رفض الفحص يُعامَل بجدية كبيرة.","h2":"في North Carolina، رفض الفحص يعني سحب الرخصة فورًا لمدة 30 يومًا على الأقل، ويضيف DMV مدة 12 شهرًا أخرى على الأقل.","p":"صحيح. رفض الفحص يُفقدك رخصتك لمدة طويلة."},"ref":{"doc":"NC","page":31}},{"id":"nc-024","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which child must ride in a child safety seat or booster made for their weight?","o":["Only a child under 2","A child under 8 who weighs less than 80 pounds","Any child under 16","Only a child riding in the front seat"],"h1":"Think of both an age and a weight.","h2":"In North Carolina, a child under 8 who weighs less than 80 pounds must ride in a child restraint that fits their weight.","p":"Right. Under 8 and under 80 pounds means a child restraint."},"es":{"q":"En Carolina del Norte, ¿qué niño debe viajar en un asiento de seguridad o elevador adecuado para su peso?","o":["Solo un niño menor de 2 años","Un niño menor de 8 años que pese menos de 80 libras","Cualquier niño menor de 16 años","Solo un niño que viaja en el asiento delantero"],"h1":"Piense en una edad y también en un peso.","h2":"En Carolina del Norte, un niño menor de 8 años que pese menos de 80 libras debe viajar en un sistema de retención infantil adecuado para su peso.","p":"Correcto. Menor de 8 años y de menos de 80 libras significa asiento infantil."},"zh":{"q":"在 North Carolina，哪种孩子必须坐适合其体重的儿童安全座椅或增高座椅？","o":["只有 2 岁以下的孩子","8 岁以下、体重不到 80 磅的孩子","任何 16 岁以下的孩子","只有坐在前座的孩子"],"h1":"同时想一想年龄和体重。","h2":"在 North Carolina，8 岁以下、体重不到 80 磅的孩子必须坐适合其体重的儿童约束装置。","p":"对。8 岁以下并且不到 80 磅，就要用儿童约束装置。"},"vi":{"q":"Ở North Carolina, trẻ nào phải ngồi ghế an toàn trẻ em hoặc ghế nâng (booster) phù hợp với cân nặng của trẻ?","o":["Chỉ trẻ dưới 2 tuổi","Trẻ dưới 8 tuổi và nặng dưới 80 pound","Bất kỳ trẻ nào dưới 16 tuổi","Chỉ trẻ ngồi ở ghế trước"],"h1":"Hãy nghĩ đến cả tuổi và cân nặng.","h2":"Ở North Carolina, trẻ dưới 8 tuổi và nặng dưới 80 pound phải ngồi trong thiết bị giữ an toàn trẻ em phù hợp với cân nặng của trẻ.","p":"Đúng. Dưới 8 tuổi và dưới 80 pound thì phải dùng thiết bị giữ an toàn trẻ em."},"tl":{"q":"Sa North Carolina, aling bata ang dapat nakaupo sa child safety seat o booster na ginawa para sa kanyang timbang?","o":["Bata lang na wala pang 2 taon","Batang wala pang 8 taon na mas magaan sa 80 pounds","Kahit sinong batang wala pang 16 taon","Bata lang na nakaupo sa harapang upuan"],"h1":"Isipin ang edad at ang timbang.","h2":"Sa North Carolina, ang batang wala pang 8 taon na mas magaan sa 80 pounds ay dapat nakaupo sa child restraint na angkop sa kanyang timbang.","p":"Tama. Wala pang 8 taon at wala pang 80 pounds ay nangangailangan ng child restraint."},"ar":{"q":"في North Carolina، أيّ طفل يجب أن يجلس في مقعد أمان للأطفال أو مقعد رافع (booster) مناسب لوزنه؟","o":["الطفل دون سن 2 فقط","الطفل دون سن 8 الذي يزن أقل من 80 رطلًا","أي طفل دون سن 16","الطفل الذي يجلس في المقعد الأمامي فقط"],"h1":"فكّر في العمر والوزن معًا.","h2":"في North Carolina، الطفل دون سن 8 الذي يزن أقل من 80 رطلًا يجب أن يجلس في مقعد أمان للأطفال يناسب وزنه.","p":"صحيح. دون 8 سنوات وأقل من 80 رطلًا يعني مقعد أمان للأطفال."},"ref":{"doc":"NC","page":44}},{"id":"nc-025","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, what is the speed limit in cities and towns when no sign shows a different limit?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is 20 mph lower than the limit outside cities and towns.","h2":"In North Carolina, the speed limit in cities and towns is 35 mph unless a sign says otherwise.","p":"Right. In cities and towns it is 35 mph unless posted."},"es":{"q":"En Carolina del Norte, ¿cuál es el límite de velocidad en ciudades y pueblos cuando ninguna señal indica otro límite?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es 20 mph menos que el límite fuera de las ciudades y pueblos.","h2":"En Carolina del Norte, el límite de velocidad en ciudades y pueblos es de 35 mph, a menos que una señal indique otra cosa.","p":"Correcto. En ciudades y pueblos es de 35 mph si no hay señal."},"zh":{"q":"在 North Carolina，如果没有标志显示其他限速，城市和镇里的限速是多少？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"它比城市和镇以外的限速低 20 mph。","h2":"在 North Carolina，除非有标志另外规定，城市和镇里的限速是 35 mph。","p":"对。除非有标志，城市和镇里是 35 mph。"},"vi":{"q":"Ở North Carolina, tốc độ tối đa trong thành phố và thị trấn là bao nhiêu khi không có biển báo nào ghi giới hạn khác?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Nó thấp hơn 20 mph so với giới hạn bên ngoài thành phố và thị trấn.","h2":"Ở North Carolina, tốc độ tối đa trong thành phố và thị trấn là 35 mph, trừ khi có biển báo ghi khác.","p":"Đúng. Trong thành phố và thị trấn là 35 mph nếu không có biển báo."},"tl":{"q":"Sa North Carolina, ano ang speed limit sa mga lungsod at bayan kapag walang karatula na nagpapakita ng ibang limit?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Mas mababa ito nang 20 mph kaysa sa limit sa labas ng mga lungsod at bayan.","h2":"Sa North Carolina, 35 mph ang speed limit sa mga lungsod at bayan maliban kung iba ang sinasabi ng karatula.","p":"Tama. Sa mga lungsod at bayan, 35 mph ito maliban kung may karatula."},"ar":{"q":"في North Carolina، ما حدّ السرعة في المدن والبلدات عندما لا توجد لافتة تُظهر حدًّا مختلفًا؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"هو أقل بـ 20 mph من الحدّ خارج المدن والبلدات.","h2":"في North Carolina، حدّ السرعة في المدن والبلدات هو 35 mph إلا إذا قالت لافتة غير ذلك.","p":"صحيح. في المدن والبلدات هو 35 mph ما لم توجد لافتة."},"ref":{"doc":"NC","page":53}},{"id":"nc-026","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, you turn on your windshield wipers because it is raining. What else must you turn on?","o":["Your headlights","Your hazard lights","Your fog lights only","Your interior light"],"h1":"These lights help other drivers see you in bad weather.","h2":"In North Carolina, you must turn on your headlights whenever you use your wipers because of bad weather.","p":"Right. Wipers on for weather means headlights on."},"es":{"q":"En Carolina del Norte, usted enciende los limpiaparabrisas porque está lloviendo. ¿Qué más debe encender?","o":["Las luces delanteras","Las luces de emergencia","Solo las luces antiniebla","La luz interior"],"h1":"Estas luces ayudan a que otros conductores lo vean con mal tiempo.","h2":"En Carolina del Norte, usted debe encender las luces delanteras siempre que use los limpiaparabrisas por mal tiempo.","p":"Correcto. Limpiaparabrisas por mal tiempo significa luces encendidas."},"zh":{"q":"在 North Carolina，因为下雨你打开了雨刷。你还必须打开什么？","o":["你的大灯","你的危险警示灯","只开你的雾灯","你的车内灯"],"h1":"这些灯能帮助其他驾驶人在坏天气里看到你。","h2":"在 North Carolina，只要因为坏天气使用雨刷，你就必须打开大灯。","p":"对。因为天气开雨刷，就要开大灯。"},"vi":{"q":"Ở North Carolina, bạn bật cần gạt nước vì trời mưa. Bạn còn phải bật gì nữa?","o":["Đèn pha của bạn","Đèn cảnh báo nguy hiểm của bạn","Chỉ đèn sương mù của bạn","Đèn trong xe của bạn"],"h1":"Những đèn này giúp các tài xế khác nhìn thấy bạn khi thời tiết xấu.","h2":"Ở North Carolina, bạn phải bật đèn pha bất cứ khi nào bạn dùng cần gạt nước vì thời tiết xấu.","p":"Đúng. Bật gạt nước vì thời tiết thì phải bật đèn pha."},"tl":{"q":"Sa North Carolina, binuksan mo ang windshield wipers dahil umuulan. Ano pa ang dapat mong buksan?","o":["Ang headlights mo","Ang hazard lights mo","Ang fog lights mo lang","Ang ilaw sa loob ng sasakyan"],"h1":"Tumutulong ang mga ilaw na ito para makita ka ng ibang driver kapag masama ang panahon.","h2":"Sa North Carolina, dapat mong buksan ang headlights mo tuwing gagamit ka ng wipers dahil sa masamang panahon.","p":"Tama. Kapag bukas ang wipers dahil sa panahon, bukas din ang headlights."},"ar":{"q":"في North Carolina، شغّلت مسّاحات الزجاج الأمامي لأن المطر ينزل. ماذا يجب أن تشغّل أيضًا؟","o":["المصابيح الأمامية","أضواء التحذير (الطوارئ)","مصابيح الضباب فقط","الضوء الداخلي للسيارة"],"h1":"هذه الأضواء تساعد السائقين الآخرين على رؤيتك في الطقس السيئ.","h2":"في North Carolina، يجب أن تشغّل المصابيح الأمامية كلما استخدمت المسّاحات بسبب الطقس السيئ.","p":"صحيح. المسّاحات بسبب الطقس تعني تشغيل المصابيح الأمامية."},"ref":{"doc":"NC","page":73}},{"id":"nc-027","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, no one is hurt in a crash. When must you report it to the police right away?","o":["Only if a car must be towed","When the damage looks like $1,000 or more","Only if the other driver asks you to","When the damage looks like $500 or more"],"h1":"It depends on how much the damage seems to cost.","h2":"In North Carolina, you must report a crash to the police right away if anyone is hurt or killed, or if the damage looks like $1,000 or more.","p":"Right. Damage of about $1,000 or more must be reported."},"es":{"q":"En Carolina del Norte, nadie resulta herido en un choque. ¿Cuándo debe reportarlo a la policía de inmediato?","o":["Solo si hay que remolcar un auto","Cuando el daño parece ser de $1,000 o más","Solo si el otro conductor se lo pide","Cuando el daño parece ser de $500 o más"],"h1":"Depende de cuánto parece costar el daño.","h2":"En Carolina del Norte, debe reportar un choque a la policía de inmediato si alguien resulta herido o muerto, o si el daño parece ser de $1,000 o más.","p":"Correcto. Un daño de unos $1,000 o más se debe reportar."},"zh":{"q":"在 North Carolina，一次车祸中没有人受伤。什么时候必须马上向警察报告？","o":["只有当车必须被拖走时","当损坏看起来有 $1,000 或以上时","只有当另一位司机要求你报告时","当损坏看起来有 $500 或以上时"],"h1":"这要看损坏看起来值多少钱。","h2":"在 North Carolina，如果有人受伤或死亡，或者损坏看起来有 $1,000 或以上，你必须马上向警察报告车祸。","p":"对。大约 $1,000 或以上的损坏必须报告。"},"vi":{"q":"Ở North Carolina, không ai bị thương trong một vụ tai nạn. Khi nào bạn phải báo cho cảnh sát ngay?","o":["Chỉ khi phải kéo một chiếc xe đi","Khi thiệt hại trông có vẻ từ $1,000 trở lên","Chỉ khi tài xế kia yêu cầu bạn","Khi thiệt hại trông có vẻ từ $500 trở lên"],"h1":"Điều đó tùy vào thiệt hại trông có vẻ tốn bao nhiêu tiền.","h2":"Ở North Carolina, bạn phải báo tai nạn cho cảnh sát ngay nếu có người bị thương hoặc chết, hoặc nếu thiệt hại trông có vẻ từ $1,000 trở lên.","p":"Đúng. Thiệt hại khoảng $1,000 trở lên phải được báo."},"tl":{"q":"Sa North Carolina, walang nasaktan sa isang banggaan. Kailan mo ito dapat i-report agad sa pulis?","o":["Kung kailangan lang hilahin ang isang kotse","Kapag mukhang $1,000 o higit pa ang pinsala","Kung hilingin lang ito ng kabilang driver","Kapag mukhang $500 o higit pa ang pinsala"],"h1":"Nakadepende ito sa kung magkano ang mukhang halaga ng pinsala.","h2":"Sa North Carolina, dapat mong i-report agad sa pulis ang banggaan kung may nasaktan o namatay, o kung mukhang $1,000 o higit pa ang pinsala.","p":"Tama. Dapat i-report ang pinsalang mga $1,000 o higit pa."},"ar":{"q":"في North Carolina، لم يُصب أحد في حادث. متى يجب أن تبلّغ الشرطة عنه فورًا؟","o":["فقط إذا كان يجب سحب سيارة","عندما يبدو أن الضرر $1,000 أو أكثر","فقط إذا طلب منك السائق الآخر ذلك","عندما يبدو أن الضرر $500 أو أكثر"],"h1":"يعتمد ذلك على كم تبدو تكلفة الضرر.","h2":"في North Carolina، يجب أن تبلّغ الشرطة عن الحادث فورًا إذا أُصيب أحد أو مات، أو إذا بدا أن الضرر $1,000 أو أكثر.","p":"صحيح. يجب التبليغ عن ضرر بحوالي $1,000 أو أكثر."},"ref":{"doc":"NC","page":78}},{"id":"nc-028","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, besides from sunset to sunrise, when does the law require headlights?","o":["When you can see only 400 feet or less","Only when it is snowing","Whenever you drive over 55 mph","Only on interstate highways"],"h1":"Think about how far ahead you can see.","h2":"In North Carolina, the law requires headlights from sunset to sunrise and whenever you can see only 400 feet or less.","p":"Right. Use headlights when you can see 400 feet or less."},"es":{"q":"En Carolina del Norte, además de la puesta a la salida del sol, ¿cuándo exige la ley usar los faros?","o":["Cuando solo puede ver 400 pies o menos","Solo cuando está nevando","Siempre que maneje a más de 55 mph","Solo en las autopistas interestatales"],"h1":"Piense en qué tan lejos puede ver hacia adelante.","h2":"En Carolina del Norte, la ley exige los faros desde la puesta hasta la salida del sol y siempre que solo pueda ver 400 pies o menos.","p":"Correcto. Use los faros cuando vea 400 pies o menos."},"zh":{"q":"在 North Carolina，除了日落到日出这段时间，法律还要求在什么时候开大灯？","o":["你只能看清 400 英尺或更近的时候","只在下雪的时候","每次车速超过 55 mph 的时候","只在州际公路上"],"h1":"想一想你能看清前面多远。","h2":"在 North Carolina，法律要求从日落到日出要开大灯，而且只要你只能看清 400 英尺或更近，也要开大灯。","p":"对。只能看清 400 英尺或更近时，要开大灯。"},"vi":{"q":"Ở North Carolina, ngoài thời gian từ lúc mặt trời lặn đến lúc mặt trời mọc, luật còn bắt buộc bật đèn pha khi nào?","o":["Khi bạn chỉ nhìn thấy được 400 feet hoặc ít hơn","Chỉ khi trời có tuyết","Bất cứ khi nào bạn lái nhanh hơn 55 mph","Chỉ trên xa lộ liên bang"],"h1":"Hãy nghĩ xem bạn nhìn thấy được bao xa phía trước.","h2":"Ở North Carolina, luật bắt buộc bật đèn pha từ lúc mặt trời lặn đến lúc mặt trời mọc và bất cứ khi nào bạn chỉ nhìn thấy được 400 feet hoặc ít hơn.","p":"Đúng. Hãy bật đèn pha khi bạn chỉ nhìn thấy được 400 feet hoặc ít hơn."},"tl":{"q":"Sa North Carolina, bukod sa mula paglubog hanggang pagsikat ng araw, kailan pa iniuutos ng batas ang headlights?","o":["Kapag 400 feet o mas maikli lang ang nakikita mo","Kapag umuulan lang ng niyebe","Tuwing nagmamaneho ka nang lampas 55 mph","Sa mga interstate highway lang"],"h1":"Isipin kung gaano kalayo ang nakikita mo sa unahan.","h2":"Sa North Carolina, iniuutos ng batas ang headlights mula paglubog hanggang pagsikat ng araw at tuwing 400 feet o mas maikli lang ang nakikita mo.","p":"Tama. Gamitin ang headlights kapag 400 feet o mas maikli lang ang nakikita mo."},"ar":{"q":"في North Carolina، إضافة إلى الوقت من غروب الشمس حتى شروقها، متى يفرض القانون تشغيل الأضواء الأمامية؟","o":["عندما لا ترى إلا مسافة 400 feet أو أقل","فقط عندما يتساقط الثلج","كلما قدت بسرعة أكثر من 55 mph","فقط على الطرق السريعة بين الولايات"],"h1":"فكّر في المسافة التي تستطيع أن تراها أمامك.","h2":"في North Carolina، يفرض القانون تشغيل الأضواء الأمامية من غروب الشمس حتى شروقها، وكلما كنت لا ترى إلا مسافة 400 feet أو أقل.","p":"صحيح. شغّل الأضواء الأمامية عندما لا ترى إلا 400 feet أو أقل."},"ref":{"doc":"NC","page":71}},{"id":"nc-029","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, when you pass another vehicle, how far to its left must you stay?","o":["At least 1 foot","At least 2 feet","At least 5 feet","At least 10 feet"],"h1":"It is a short distance, but more than one foot.","h2":"In North Carolina, the law requires you to pass at least 2 feet to the left of the vehicle you are passing.","p":"Right. Leave at least 2 feet when you pass."},"es":{"q":"En Carolina del Norte, cuando rebasa a otro vehículo, ¿a qué distancia a su izquierda debe pasar?","o":["Al menos 1 pie","Al menos 2 pies","Al menos 5 pies","Al menos 10 pies"],"h1":"Es una distancia corta, pero de más de un pie.","h2":"En Carolina del Norte, la ley exige pasar al menos a 2 pies a la izquierda del vehículo que rebasa.","p":"Correcto. Deje al menos 2 pies al rebasar."},"zh":{"q":"在 North Carolina，超过另一辆车时，你必须在它左边保持多远的距离？","o":["至少 1 英尺","至少 2 英尺","至少 5 英尺","至少 10 英尺"],"h1":"距离很短，但比 1 英尺多。","h2":"在 North Carolina，法律要求你超车时，要在被超车辆的左边至少 2 英尺的地方经过。","p":"对。超车时至少留出 2 英尺。"},"vi":{"q":"Ở North Carolina, khi bạn vượt một xe khác, bạn phải cách bên trái xe đó bao xa?","o":["Ít nhất 1 feet","Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 10 feet"],"h1":"Đó là một khoảng cách ngắn, nhưng hơn 1 feet.","h2":"Ở North Carolina, luật bắt buộc bạn vượt qua cách bên trái xe mà bạn đang vượt ít nhất 2 feet.","p":"Đúng. Hãy chừa ít nhất 2 feet khi bạn vượt xe."},"tl":{"q":"Sa North Carolina, kapag nag-overtake ka sa ibang sasakyan, gaano kalayo sa kaliwa nito ang dapat mong panatilihin?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 5 feet","Hindi bababa sa 10 feet"],"h1":"Maikling layo ito, pero higit sa 1 foot.","h2":"Sa North Carolina, iniuutos ng batas na dumaan ka nang hindi bababa sa 2 feet sa kaliwa ng sasakyang inoovertake mo.","p":"Tama. Mag-iwan ng hindi bababa sa 2 feet kapag nag-overtake ka."},"ar":{"q":"في North Carolina، عندما تتجاوز مركبة أخرى، كم يجب أن تبتعد إلى يسارها؟","o":["1 foot على الأقل","2 feet على الأقل","5 feet على الأقل","10 feet على الأقل"],"h1":"هي مسافة قصيرة، لكنها أكثر من 1 foot.","h2":"في North Carolina، يفرض القانون أن تمرّ على بُعد 2 feet على الأقل إلى يسار المركبة التي تتجاوزها.","p":"صحيح. اترك 2 feet على الأقل عندما تتجاوز."},"ref":{"doc":"NC","page":55}},{"id":"nc-030","scope":"NC","cat":"signals","sign":null,"c":3,"en":{"q":"In North Carolina, the speed limit is 45 mph or more. How far before a turn must you start to signal?","o":["At least 50 feet","At least 100 feet","At least 150 feet","At least 200 feet"],"h1":"On slower roads it is 100 feet. On faster roads it is more.","h2":"In North Carolina, when the speed limit is 45 mph or more, you must signal at least the last 200 feet before you turn.","p":"Right. On faster roads, signal at least 200 feet ahead."},"es":{"q":"En Carolina del Norte, el límite de velocidad es de 45 mph o más. ¿Con cuánta anticipación debe señalar antes de girar?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 150 pies","Al menos 200 pies"],"h1":"En calles más lentas son 100 pies. En vías más rápidas es más.","h2":"En Carolina del Norte, cuando el límite es de 45 mph o más, debe señalar al menos en los últimos 200 pies antes de girar.","p":"Correcto. En vías rápidas, señale al menos 200 pies antes."},"zh":{"q":"在 North Carolina，限速是 45 mph 或更高。转弯前你必须在多远的地方开始打转向灯？","o":["至少 50 英尺","至少 100 英尺","至少 150 英尺","至少 200 英尺"],"h1":"在慢一点的路上是 100 英尺。在快一点的路上要更多。","h2":"在 North Carolina，限速是 45 mph 或更高时，你必须在转弯前至少最后 200 英尺就打转向灯。","p":"对。在快一点的路上，至少提前 200 英尺打灯。"},"vi":{"q":"Ở North Carolina, tốc độ tối đa là 45 mph hoặc cao hơn. Bạn phải bắt đầu bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 150 feet","Ít nhất 200 feet"],"h1":"Trên đường chậm hơn là 100 feet. Trên đường nhanh hơn thì nhiều hơn.","h2":"Ở North Carolina, khi tốc độ tối đa là 45 mph hoặc cao hơn, bạn phải bật đèn xi nhan ít nhất trong 200 feet cuối cùng trước khi rẽ.","p":"Đúng. Trên đường nhanh hơn, hãy bật đèn xi nhan trước ít nhất 200 feet."},"tl":{"q":"Sa North Carolina, 45 mph o higit pa ang speed limit. Gaano kalayo bago lumiko ka dapat magsimulang mag-signal?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 150 feet","Hindi bababa sa 200 feet"],"h1":"Sa mas mabagal na daan, 100 feet ito. Sa mas mabilis na daan, mas malayo.","h2":"Sa North Carolina, kapag 45 mph o higit pa ang speed limit, dapat kang mag-signal nang hindi bababa sa huling 200 feet bago ka lumiko.","p":"Tama. Sa mas mabilis na daan, mag-signal nang hindi bababa sa 200 feet bago lumiko."},"ar":{"q":"في North Carolina، حدّ السرعة 45 mph أو أكثر. على أي مسافة قبل المنعطف يجب أن تبدأ بإعطاء الإشارة؟","o":["50 feet على الأقل","100 feet على الأقل","150 feet على الأقل","200 feet على الأقل"],"h1":"على الطرق الأبطأ هي 100 feet. وعلى الطرق الأسرع هي أكثر.","h2":"في North Carolina، عندما يكون حدّ السرعة 45 mph أو أكثر، يجب أن تعطي الإشارة على الأقل في آخر 200 feet قبل أن تنعطف.","p":"صحيح. على الطرق الأسرع، أعطِ الإشارة قبل 200 feet على الأقل."},"ref":{"doc":"NC","page":69}},{"id":"nc-031","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"The same distance applies to the entrance of a fire station.","h2":"In North Carolina, you may not park within 15 feet of a fire hydrant or the entrance to a fire station.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Carolina del Norte, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 30 pies"],"h1":"La misma distancia se aplica a la entrada de una estación de bomberos.","h2":"En Carolina del Norte, no puede estacionarse a menos de 15 pies de un hidrante o de la entrada de una estación de bomberos.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"zh":{"q":"在 North Carolina，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 30 英尺"],"h1":"消防站的入口也是同样的距离。","h2":"在 North Carolina，你不可以把车停在离消防栓或消防站入口 15 英尺以内的地方。","p":"对。停车时离消防栓至少 15 英尺。"},"vi":{"q":"Ở North Carolina, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này cũng áp dụng cho lối vào của trạm cứu hỏa.","h2":"Ở North Carolina, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa hoặc lối vào trạm cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa North Carolina, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Pareho rin ang layo para sa pasukan ng fire station.","h2":"Sa North Carolina, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant o sa pasukan ng fire station.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa hydrant."},"ar":{"q":"في North Carolina، كم يمكنك أن تقترب من صنبور إطفاء الحريق عندما توقف سيارتك؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"المسافة نفسها تنطبق على مدخل محطة الإطفاء.","h2":"في North Carolina، لا يجوز لك أن توقف سيارتك على بُعد أقل من 15 feet من صنبور إطفاء الحريق أو من مدخل محطة الإطفاء.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من صنبور الإطفاء."},"ref":{"doc":"NC","page":56}},{"id":"nc-032","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, how many driver license points can get you sent to a driver improvement clinic?","o":["3 points","7 points","5 points","12 points"],"h1":"It is fewer points than the number that can lead to a suspension.","h2":"In North Carolina, a driver with 7 points may be sent to a driver improvement clinic, and finishing it takes 3 points off the record.","p":"Right. At 7 points you may be sent to a driver improvement clinic."},"es":{"q":"En Carolina del Norte, ¿con cuántos puntos en la licencia lo pueden mandar a una clínica para mejorar como conductor?","o":["3 puntos","7 puntos","5 puntos","12 puntos"],"h1":"Son menos puntos que el número que puede llevar a una suspensión.","h2":"En Carolina del Norte, a un conductor con 7 puntos lo pueden mandar a una clínica para mejorar como conductor, y terminarla le quita 3 puntos del historial.","p":"Correcto. Con 7 puntos lo pueden mandar a una clínica para mejorar como conductor."},"zh":{"q":"在 North Carolina，驾照上累计多少分可能会让你被送去上驾驶改进课程（driver improvement clinic）？","o":["3 分","7 分","5 分","12 分"],"h1":"它比可能导致暂停驾照的分数少。","h2":"在 North Carolina，有 7 分的司机可能会被送去上驾驶改进课程，上完以后记录上会减掉 3 分。","p":"对。累计 7 分时，你可能会被送去上驾驶改进课程。"},"vi":{"q":"Ở North Carolina, bị bao nhiêu điểm trên bằng lái thì bạn có thể bị gửi đi học lớp cải thiện kỹ năng lái xe (driver improvement clinic)?","o":["3 điểm","7 điểm","5 điểm","12 điểm"],"h1":"Số điểm này ít hơn số điểm có thể dẫn đến bị đình chỉ bằng lái.","h2":"Ở North Carolina, tài xế có 7 điểm có thể bị gửi đi học lớp cải thiện kỹ năng lái xe, và học xong lớp này sẽ được trừ 3 điểm khỏi hồ sơ.","p":"Đúng. Khi có 7 điểm, bạn có thể bị gửi đi học lớp cải thiện kỹ năng lái xe."},"tl":{"q":"Sa North Carolina, ilang point sa lisensya ang puwedeng magpapadala sa iyo sa isang driver improvement clinic?","o":["3 point","7 point","5 point","12 point"],"h1":"Mas kaunti ito kaysa sa bilang ng point na puwedeng magdulot ng suspensyon.","h2":"Sa North Carolina, ang driver na may 7 point ay puwedeng ipadala sa isang driver improvement clinic, at kapag natapos niya ito, mababawasan ng 3 point ang record niya.","p":"Tama. Kapag 7 point na, puwede kang ipadala sa isang driver improvement clinic."},"ar":{"q":"في North Carolina، كم نقطة على رخصة القيادة قد تجعلهم يرسلونك إلى دورة لتحسين القيادة (driver improvement clinic)؟","o":["3 نقاط","7 نقاط","5 نقاط","12 نقطة"],"h1":"هي نقاط أقل من العدد الذي قد يؤدي إلى إيقاف الرخصة.","h2":"في North Carolina، قد يُرسَل السائق الذي لديه 7 نقاط إلى دورة لتحسين القيادة، وإكمالها يحذف 3 نقاط من سجله.","p":"صحيح. عند 7 نقاط قد يُرسلونك إلى دورة لتحسين القيادة."},"ref":{"doc":"NC","page":34}},{"id":"nc-033","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, your license is suspended for points for the first time. How long may it be taken?","o":["30 days","6 months","12 months","60 days"],"h1":"It is longer than one month, and later suspensions are longer still.","h2":"In North Carolina, a first suspension for points may last 60 days; a second may last 6 months and a third 12 months.","p":"Right. A first points suspension may last 60 days."},"es":{"q":"En Carolina del Norte, su licencia es suspendida por puntos por primera vez. ¿Por cuánto tiempo se la pueden quitar?","o":["30 días","6 meses","12 meses","60 días"],"h1":"Es más de un mes, y las suspensiones siguientes son aún más largas.","h2":"En Carolina del Norte, una primera suspensión por puntos puede durar 60 días; la segunda puede durar 6 meses y la tercera 12 meses.","p":"Correcto. Una primera suspensión por puntos puede durar 60 días."},"zh":{"q":"在 North Carolina，你的驾照第一次因为扣分被暂停。驾照可能会被收走多久？","o":["30 天","6 个月","12 个月","60 天"],"h1":"它比一个月长，之后的暂停时间会更长。","h2":"在 North Carolina，第一次因扣分暂停驾照可能会持续 60 天；第二次可能 6 个月，第三次可能 12 个月。","p":"对。第一次因扣分暂停驾照可能会持续 60 天。"},"vi":{"q":"Ở North Carolina, bằng lái của bạn bị đình chỉ vì điểm lần đầu tiên. Bằng lái có thể bị thu trong bao lâu?","o":["30 ngày","6 tháng","12 tháng","60 ngày"],"h1":"Thời gian này dài hơn một tháng, và những lần đình chỉ sau còn dài hơn nữa.","h2":"Ở North Carolina, lần đình chỉ đầu tiên vì điểm có thể kéo dài 60 ngày; lần thứ hai có thể 6 tháng và lần thứ ba 12 tháng.","p":"Đúng. Lần đình chỉ đầu tiên vì điểm có thể kéo dài 60 ngày."},"tl":{"q":"Sa North Carolina, nasuspinde ang lisensya mo dahil sa mga point sa unang pagkakataon. Gaano katagal ito puwedeng kunin?","o":["30 araw","6 na buwan","12 buwan","60 araw"],"h1":"Mas mahaba ito sa isang buwan, at mas mahaba pa ang mga susunod na suspensyon.","h2":"Sa North Carolina, ang unang suspensyon dahil sa mga point ay puwedeng tumagal nang 60 araw; ang ikalawa ay puwedeng 6 na buwan at ang ikatlo ay 12 buwan.","p":"Tama. Ang unang suspensyon dahil sa mga point ay puwedeng tumagal nang 60 araw."},"ar":{"q":"في North Carolina، أُوقفت رخصتك بسبب النقاط لأول مرة. كم من الوقت قد تُسحب منك؟","o":["30 يومًا","6 أشهر","12 شهرًا","60 يومًا"],"h1":"هي أطول من شهر واحد، والإيقافات التي بعدها أطول من ذلك.","h2":"في North Carolina، قد يستمر الإيقاف الأول بسبب النقاط 60 يومًا؛ وقد يستمر الثاني 6 أشهر والثالث 12 شهرًا.","p":"صحيح. قد يستمر الإيقاف الأول بسبب النقاط 60 يومًا."},"ref":{"doc":"NC","page":34}},{"id":"nc-034","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a driver under 18 is convicted of a second moving violation within 12 months. How long may the license be suspended?","o":["30 days","90 days","6 months","1 year"],"h1":"It is the shortest of the suspensions for young drivers; more violations bring longer ones.","h2":"In North Carolina, a driver under 18 may lose the license for 30 days after a second moving violation within 12 months; a third brings 90 days and a fourth six months.","p":"Right. A second moving violation within 12 months can mean a 30-day suspension."},"es":{"q":"En Carolina del Norte, un conductor menor de 18 años es declarado culpable de una segunda infracción en movimiento dentro de 12 meses. ¿Por cuánto tiempo pueden suspender su licencia?","o":["30 días","90 días","6 meses","1 año"],"h1":"Es la más corta de las suspensiones para conductores jóvenes; más infracciones traen suspensiones más largas.","h2":"En Carolina del Norte, un conductor menor de 18 años puede perder la licencia por 30 días tras una segunda infracción en movimiento dentro de 12 meses; la tercera trae 90 días y la cuarta seis meses.","p":"Correcto. Una segunda infracción en movimiento dentro de 12 meses puede causar una suspensión de 30 días."},"zh":{"q":"在 North Carolina，一名未满 18 岁的司机在 12 个月内第二次被判行车违规（moving violation）。驾照可能会被暂停多久？","o":["30 天","90 天","6 个月","1 年"],"h1":"这是年轻司机最短的暂停时间；违规越多，暂停越长。","h2":"在 North Carolina，未满 18 岁的司机在 12 个月内第二次行车违规后，可能会失去驾照 30 天；第三次是 90 天，第四次是六个月。","p":"对。12 个月内第二次行车违规可能会导致暂停驾照 30 天。"},"vi":{"q":"Ở North Carolina, một tài xế dưới 18 tuổi bị kết tội vi phạm khi đang lái xe (moving violation) lần thứ hai trong vòng 12 tháng. Bằng lái có thể bị đình chỉ trong bao lâu?","o":["30 ngày","90 ngày","6 tháng","1 năm"],"h1":"Đây là mức đình chỉ ngắn nhất cho tài xế trẻ; vi phạm nhiều hơn thì bị đình chỉ lâu hơn.","h2":"Ở North Carolina, tài xế dưới 18 tuổi có thể mất bằng lái 30 ngày sau lần vi phạm khi đang lái xe thứ hai trong vòng 12 tháng; lần thứ ba là 90 ngày và lần thứ tư là sáu tháng.","p":"Đúng. Lần vi phạm khi đang lái xe thứ hai trong vòng 12 tháng có thể bị đình chỉ 30 ngày."},"tl":{"q":"Sa North Carolina, ang isang driver na wala pang 18 ay napatunayang nagkasala ng ikalawang moving violation sa loob ng 12 buwan. Gaano katagal puwedeng masuspinde ang lisensya?","o":["30 araw","90 araw","6 na buwan","1 taon"],"h1":"Ito ang pinakamaikli sa mga suspensyon para sa mga batang driver; mas maraming paglabag, mas mahabang suspensyon.","h2":"Sa North Carolina, ang driver na wala pang 18 ay puwedeng mawalan ng lisensya nang 30 araw pagkatapos ng ikalawang moving violation sa loob ng 12 buwan; 90 araw sa ikatlo at anim na buwan sa ikaapat.","p":"Tama. Ang ikalawang moving violation sa loob ng 12 buwan ay puwedeng magdulot ng 30 araw na suspensyon."},"ar":{"q":"في North Carolina، أُدين سائق عمره أقل من 18 سنة بمخالفة قيادة ثانية (moving violation) خلال 12 شهرًا. كم من الوقت قد تُوقَف الرخصة؟","o":["30 يومًا","90 يومًا","6 أشهر","سنة واحدة (1)"],"h1":"هو أقصر إيقاف للسائقين الصغار؛ والمخالفات الأكثر تجلب إيقافًا أطول.","h2":"في North Carolina، قد يفقد السائق الذي عمره أقل من 18 سنة رخصته 30 يومًا بعد مخالفة قيادة ثانية خلال 12 شهرًا؛ والثالثة تجلب 90 يومًا والرابعة ستة أشهر.","p":"صحيح. مخالفة القيادة الثانية خلال 12 شهرًا قد تعني إيقافًا لمدة 30 يومًا."},"ref":{"doc":"NC","page":39}},{"id":"nc-035","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, what happens to the license of a driver convicted of DWI for the first time?","o":["It is revoked for 30 days","It is revoked for 6 months","It is revoked for one year","It is revoked for four years"],"h1":"The 30 days is what happens right after the arrest, not after the conviction.","h2":"In North Carolina, a first DWI conviction brings a mandatory one-year license revocation.","p":"Right. A first DWI conviction means losing the license for one year."},"es":{"q":"En Carolina del Norte, ¿qué le pasa a la licencia de un conductor declarado culpable de DWI (manejar bajo los efectos) por primera vez?","o":["Se revoca por 30 días","Se revoca por 6 meses","Se revoca por un año","Se revoca por cuatro años"],"h1":"Los 30 días son lo que pasa justo después del arresto, no después de la condena.","h2":"En Carolina del Norte, una primera condena por DWI trae la revocación obligatoria de la licencia por un año.","p":"Correcto. Una primera condena por DWI significa perder la licencia por un año."},"zh":{"q":"在 North Carolina，司机第一次被判酒后或药后驾驶（DWI），驾照会怎样？","o":["被吊销 30 天","被吊销 6 个月","被吊销一年","被吊销四年"],"h1":"30 天是被逮捕后马上发生的事，不是被定罪以后。","h2":"在 North Carolina，第一次 DWI 定罪会强制吊销驾照一年。","p":"对。第一次 DWI 定罪表示失去驾照一年。"},"vi":{"q":"Ở North Carolina, điều gì xảy ra với bằng lái của tài xế bị kết tội lái xe khi say (DWI) lần đầu tiên?","o":["Bị thu hồi 30 ngày","Bị thu hồi 6 tháng","Bị thu hồi một năm","Bị thu hồi bốn năm"],"h1":"30 ngày là chuyện xảy ra ngay sau khi bị bắt, không phải sau khi bị kết tội.","h2":"Ở North Carolina, lần đầu bị kết tội DWI thì bằng lái bắt buộc bị thu hồi một năm.","p":"Đúng. Lần đầu bị kết tội DWI nghĩa là mất bằng lái một năm."},"tl":{"q":"Sa North Carolina, ano ang mangyayari sa lisensya ng driver na napatunayang nagkasala ng DWI (pagmamaneho nang lasing o lango) sa unang pagkakataon?","o":["Babawiin ito nang 30 araw","Babawiin ito nang 6 na buwan","Babawiin ito nang isang taon","Babawiin ito nang apat na taon"],"h1":"Ang 30 araw ay nangyayari agad pagkatapos ng pag-aresto, hindi pagkatapos mapatunayang nagkasala.","h2":"Sa North Carolina, ang unang conviction sa DWI ay may sapilitang pagbawi ng lisensya nang isang taon.","p":"Tama. Ang unang conviction sa DWI ay nangangahulugang mawawalan ka ng lisensya nang isang taon."},"ar":{"q":"في North Carolina، ماذا يحدث لرخصة سائق أُدين بالقيادة تحت تأثير الكحول أو المخدرات (DWI) لأول مرة؟","o":["تُلغى لمدة 30 يومًا","تُلغى لمدة 6 أشهر","تُلغى لمدة سنة واحدة","تُلغى لمدة أربع سنوات"],"h1":"الـ 30 يومًا هي ما يحدث بعد الاعتقال مباشرة، وليس بعد الإدانة.","h2":"في North Carolina، الإدانة الأولى بـ DWI تجلب إلغاءً إجباريًا للرخصة لمدة سنة واحدة.","p":"صحيح. الإدانة الأولى بـ DWI تعني فقدان الرخصة لمدة سنة واحدة."},"ref":{"doc":"NC","page":32}},{"id":"nc-036","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, a driver is convicted of DWI with a blood alcohol level of 0.15 or more. What must be put in the vehicle?","o":["A GPS tracker","An ignition interlock device","A dashboard camera","A speed limiter"],"h1":"The device checks the driver's breath before the car will start.","h2":"In North Carolina, a DWI conviction with a blood alcohol level of 0.15 or more requires an ignition interlock device in the vehicle.","p":"Right. A 0.15 or higher DWI means an ignition interlock device."},"es":{"q":"En Carolina del Norte, un conductor es declarado culpable de DWI con un nivel de alcohol en la sangre de 0.15 o más. ¿Qué se debe instalar en el vehículo?","o":["Un rastreador GPS","Un dispositivo de bloqueo de encendido (ignition interlock)","Una cámara en el tablero","Un limitador de velocidad"],"h1":"El dispositivo revisa el aliento del conductor antes de que el carro arranque.","h2":"En Carolina del Norte, una condena por DWI con un nivel de alcohol en la sangre de 0.15 o más exige un dispositivo de bloqueo de encendido en el vehículo.","p":"Correcto. Un DWI con 0.15 o más significa un dispositivo de bloqueo de encendido."},"zh":{"q":"在 North Carolina，一名司机被判 DWI，血液酒精浓度是 0.15 或更高。车里必须装什么？","o":["GPS 追踪器","点火联锁装置（ignition interlock device）","行车记录仪","限速器"],"h1":"这个装置会在车子启动前检查司机呼出的气。","h2":"在 North Carolina，血液酒精浓度 0.15 或更高的 DWI 定罪，车里必须装点火联锁装置。","p":"对。0.15 或更高的 DWI 表示要装点火联锁装置。"},"vi":{"q":"Ở North Carolina, một tài xế bị kết tội DWI với nồng độ cồn trong máu từ 0.15 trở lên. Phải lắp gì vào xe?","o":["Một thiết bị định vị GPS","Một thiết bị khóa khởi động đo cồn (ignition interlock device)","Một camera hành trình","Một bộ giới hạn tốc độ"],"h1":"Thiết bị này kiểm tra hơi thở của tài xế trước khi xe nổ máy.","h2":"Ở North Carolina, bị kết tội DWI với nồng độ cồn trong máu từ 0.15 trở lên thì xe bắt buộc phải lắp thiết bị khóa khởi động đo cồn.","p":"Đúng. DWI từ 0.15 trở lên nghĩa là phải lắp thiết bị khóa khởi động đo cồn."},"tl":{"q":"Sa North Carolina, napatunayang nagkasala ng DWI ang isang driver na may blood alcohol level na 0.15 o higit pa. Ano ang dapat ilagay sa sasakyan?","o":["Isang GPS tracker","Isang ignition interlock device","Isang dashboard camera","Isang speed limiter"],"h1":"Sinusuri ng device ang hininga ng driver bago umandar ang kotse.","h2":"Sa North Carolina, ang conviction sa DWI na may blood alcohol level na 0.15 o higit pa ay nangangailangan ng ignition interlock device sa sasakyan.","p":"Tama. Ang DWI na 0.15 o higit pa ay nangangahulugang ignition interlock device."},"ar":{"q":"في North Carolina، أُدين سائق بـ DWI ونسبة الكحول في دمه 0.15 أو أكثر. ماذا يجب أن يُركَّب في المركبة؟","o":["جهاز تتبّع GPS","جهاز قفل التشغيل (ignition interlock device)","كاميرا على لوحة القيادة","جهاز لتحديد السرعة"],"h1":"يفحص الجهاز نَفَس السائق قبل أن تعمل السيارة.","h2":"في North Carolina، الإدانة بـ DWI مع نسبة كحول في الدم 0.15 أو أكثر تفرض تركيب جهاز قفل التشغيل في المركبة.","p":"صحيح. الـ DWI بنسبة 0.15 أو أكثر يعني جهاز قفل التشغيل."},"ref":{"doc":"NC","page":32}},{"id":"nc-037","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you just moved here and became a resident. How soon must you get a North Carolina license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is about two months.","h2":"In North Carolina, a new resident has 60 days after moving here to get a North Carolina license.","p":"Right. New residents have 60 days."},"es":{"q":"En Carolina del Norte, usted acaba de mudarse y ahora es residente. ¿En cuánto tiempo debe sacar una licencia de Carolina del Norte?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","Dentro de 90 días"],"h1":"Son unos dos meses.","h2":"En Carolina del Norte, un nuevo residente tiene 60 días después de mudarse para sacar una licencia de Carolina del Norte.","p":"Correcto. Los nuevos residentes tienen 60 días."},"zh":{"q":"在 North Carolina，你刚搬来这里，成为居民。你必须多久之内拿到 North Carolina 的驾照？","o":["10 天内","30 天内","60 天内","90 天内"],"h1":"大约是两个月。","h2":"在 North Carolina，新居民搬来以后有 60 天时间拿 North Carolina 的驾照。","p":"对。新居民有 60 天时间。"},"vi":{"q":"Ở North Carolina, bạn vừa chuyển đến đây và trở thành cư dân. Bạn phải lấy bằng lái North Carolina trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 90 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở North Carolina, cư dân mới có 60 ngày sau khi chuyển đến để lấy bằng lái North Carolina.","p":"Đúng. Cư dân mới có 60 ngày."},"tl":{"q":"Sa North Carolina, kalilipat mo lang dito at naging residente ka na. Gaano kabilis ka dapat kumuha ng lisensya ng North Carolina?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 90 araw"],"h1":"Mga dalawang buwan ito.","h2":"Sa North Carolina, may 60 araw ang bagong residente pagkatapos lumipat dito para kumuha ng lisensya ng North Carolina.","p":"Tama. May 60 araw ang mga bagong residente."},"ar":{"q":"في North Carolina، انتقلت إلى هنا حديثًا وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة من North Carolina؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","خلال 90 يومًا"],"h1":"هي شهران تقريبًا.","h2":"في North Carolina، لدى المقيم الجديد 60 يومًا بعد انتقاله إلى هنا ليحصل على رخصة من North Carolina.","p":"صحيح. لدى المقيمين الجدد 60 يومًا."},"ref":{"doc":"NC","page":25}},{"id":"nc-038","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, you are 30 years old when you get your driver license. How long is it valid?","o":["4 years","5 years","10 years","8 years"],"h1":"Drivers 66 and older get a shorter license than this.","h2":"In North Carolina, a license issued to a driver aged 18 to 65 is valid for 8 years; from age 66 it is valid for 5 years.","p":"Right. Between 18 and 65, a license lasts 8 years."},"es":{"q":"En Carolina del Norte, usted tiene 30 años cuando recibe su licencia de manejar. ¿Por cuánto tiempo es válida?","o":["4 años","5 años","10 años","8 años"],"h1":"Los conductores de 66 años o más reciben una licencia más corta que esta.","h2":"En Carolina del Norte, una licencia dada a un conductor de 18 a 65 años es válida por 8 años; desde los 66 años es válida por 5 años.","p":"Correcto. Entre los 18 y los 65 años, la licencia dura 8 años."},"zh":{"q":"在 North Carolina，你拿到驾照时 30 岁。驾照有效多久？","o":["4 年","5 年","10 年","8 年"],"h1":"66 岁和以上的司机拿到的驾照有效期比这个短。","h2":"在 North Carolina，发给 18 到 65 岁司机的驾照有效 8 年；从 66 岁开始有效 5 年。","p":"对。18 到 65 岁之间，驾照有效 8 年。"},"vi":{"q":"Ở North Carolina, bạn 30 tuổi khi nhận bằng lái. Bằng lái có giá trị trong bao lâu?","o":["4 năm","5 năm","10 năm","8 năm"],"h1":"Tài xế từ 66 tuổi trở lên nhận bằng lái có thời hạn ngắn hơn thế này.","h2":"Ở North Carolina, bằng lái cấp cho tài xế từ 18 đến 65 tuổi có giá trị 8 năm; từ 66 tuổi thì có giá trị 5 năm.","p":"Đúng. Từ 18 đến 65 tuổi, bằng lái có giá trị 8 năm."},"tl":{"q":"Sa North Carolina, 30 taong gulang ka nang makuha mo ang lisensya mo. Gaano katagal ito valid?","o":["4 na taon","5 taon","10 taon","8 taon"],"h1":"Mas maikli ang lisensyang nakukuha ng mga driver na 66 pataas.","h2":"Sa North Carolina, ang lisensyang ibinigay sa driver na edad 18 hanggang 65 ay valid nang 8 taon; mula edad 66, valid ito nang 5 taon.","p":"Tama. Mula 18 hanggang 65, tumatagal nang 8 taon ang lisensya."},"ar":{"q":"في North Carolina، عمرك 30 سنة عندما تحصل على رخصة القيادة. ما مدة صلاحيتها؟","o":["4 سنوات","5 سنوات","10 سنوات","8 سنوات"],"h1":"السائقون الذين أعمارهم 66 سنة أو أكثر يحصلون على رخصة مدتها أقصر من هذه.","h2":"في North Carolina، الرخصة التي تُعطى لسائق عمره من 18 إلى 65 سنة صالحة لمدة 8 سنوات؛ ومن عمر 66 سنة تكون صالحة لمدة 5 سنوات.","p":"صحيح. بين 18 و 65 سنة، تبقى الرخصة صالحة 8 سنوات."},"ref":{"doc":"NC","page":28}},{"id":"nc-039","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, at least how much liability insurance must a car owner carry for injuries to one person in a crash?","o":["$50,000","$10,000","$25,000","$100,000"],"h1":"It is half the amount required for all injuries in one crash.","h2":"In North Carolina, liability insurance must cover at least $50,000 for injuries to one person, $100,000 for all injuries and $50,000 for property damage in a crash (the minimums for policies issued or renewed from July 1, 2025).","p":"Right. At least $50,000 for injuries to one person."},"es":{"q":"En Carolina del Norte, ¿cuánto seguro de responsabilidad debe tener como mínimo el dueño de un carro para las lesiones de una persona en un choque?","o":["$50,000","$10,000","$25,000","$100,000"],"h1":"Es la mitad de lo que se exige para todas las lesiones de un choque.","h2":"En Carolina del Norte, el seguro de responsabilidad debe cubrir al menos $50,000 por las lesiones de una persona, $100,000 por todas las lesiones y $50,000 por daños a la propiedad en un choque (los mínimos para pólizas emitidas o renovadas desde el 1 de julio de 2025).","p":"Correcto. Al menos $50,000 por las lesiones de una persona."},"ref":{"doc":"NC","page":null}},{"id":"nc-040","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, outside cities and towns, what is the speed limit when no sign shows a different one?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"It is 20 mph more than the limit in cities and towns.","h2":"In North Carolina, the speed limit outside cities and towns is 55 mph unless a sign shows a different limit.","p":"Right. Outside cities and towns, the limit is 55 mph unless posted."},"es":{"q":"En Carolina del Norte, fuera de ciudades y pueblos, ¿cuál es el límite de velocidad cuando ningún letrero indica otro?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Son 20 mph más que el límite en ciudades y pueblos.","h2":"En Carolina del Norte, el límite de velocidad fuera de ciudades y pueblos es 55 mph, a menos que un letrero indique otro límite.","p":"Correcto. Fuera de ciudades y pueblos, el límite es 55 mph si no hay letrero."},"zh":{"q":"在 North Carolina，在城市和镇以外，如果没有标志写别的限速，限速是多少？","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"它比城市和镇里的限速多 20 mph。","h2":"在 North Carolina，除非有标志写别的限速，城市和镇以外的限速是 55 mph。","p":"对。在城市和镇以外，没有标志时限速是 55 mph。"},"vi":{"q":"Ở North Carolina, bên ngoài thành phố và thị trấn, tốc độ tối đa là bao nhiêu khi không có biển báo ghi khác?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Nhanh hơn 20 mph so với tốc độ tối đa trong thành phố và thị trấn.","h2":"Ở North Carolina, tốc độ tối đa bên ngoài thành phố và thị trấn là 55 mph, trừ khi có biển báo ghi tốc độ khác.","p":"Đúng. Bên ngoài thành phố và thị trấn, tốc độ tối đa là 55 mph nếu không có biển báo."},"tl":{"q":"Sa North Carolina, sa labas ng mga lungsod at bayan, ano ang speed limit kapag walang karatulang nagsasabi ng iba?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Mas mataas ito nang 20 mph kaysa sa speed limit sa mga lungsod at bayan.","h2":"Sa North Carolina, 55 mph ang speed limit sa labas ng mga lungsod at bayan maliban kung ibang limit ang nasa karatula.","p":"Tama. Sa labas ng mga lungsod at bayan, 55 mph ang limit kung walang karatula."},"ar":{"q":"في North Carolina، خارج المدن والبلدات، ما حدّ السرعة عندما لا توجد لافتة تقول غير ذلك؟","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"هو أكثر بـ 20 mph من حدّ السرعة في المدن والبلدات.","h2":"في North Carolina، حدّ السرعة خارج المدن والبلدات هو 55 mph إلا إذا أظهرت لافتة حدًّا آخر.","p":"صحيح. خارج المدن والبلدات، الحدّ هو 55 mph إذا لم توجد لافتة."},"ref":{"doc":"NC","page":53}},{"id":"nc-041","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, what is the highest speed a school bus may drive?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"School activity buses may go faster than this.","h2":"In North Carolina, the maximum speed limit for a school bus is 45 mph.","p":"Right. A school bus may not go over 45 mph."},"es":{"q":"En Carolina del Norte, ¿cuál es la velocidad más alta a la que puede ir un autobús escolar?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"Los autobuses para actividades escolares pueden ir más rápido que esto.","h2":"En Carolina del Norte, el límite de velocidad máximo para un autobús escolar es 45 mph.","p":"Correcto. Un autobús escolar no puede pasar de 45 mph."},"zh":{"q":"在 North Carolina，校车最快可以开多快？","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"学校活动用的巴士可以开得比这个快。","h2":"在 North Carolina，校车的最高限速是 45 mph。","p":"对。校车不可以超过 45 mph。"},"vi":{"q":"Ở North Carolina, xe buýt trường học được chạy nhanh nhất là bao nhiêu?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"Xe buýt dùng cho hoạt động của trường có thể chạy nhanh hơn mức này.","h2":"Ở North Carolina, tốc độ tối đa cho xe buýt trường học là 45 mph.","p":"Đúng. Xe buýt trường học không được chạy quá 45 mph."},"tl":{"q":"Sa North Carolina, ano ang pinakamabilis na puwedeng takbo ng isang school bus?","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"Puwedeng mas mabilis dito ang mga school activity bus.","h2":"Sa North Carolina, 45 mph ang pinakamataas na speed limit para sa isang school bus.","p":"Tama. Hindi puwedeng lumampas sa 45 mph ang school bus."},"ar":{"q":"في North Carolina، ما أعلى سرعة يجوز أن تسير بها الحافلة المدرسية؟","o":["35 mph","55 mph","45 mph","65 mph"],"h1":"حافلات الأنشطة المدرسية يجوز أن تسير أسرع من هذا.","h2":"في North Carolina، أعلى حدّ للسرعة للحافلة المدرسية هو 45 mph.","p":"صحيح. لا يجوز للحافلة المدرسية أن تتجاوز 45 mph."},"ref":{"doc":"NC","page":53}},{"id":"nc-042","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, the street has a curb. How close to the curb line of a crossing street may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 50 feet","No closer than 25 feet"],"h1":"The shorter distance is only for streets with no curb.","h2":"In North Carolina, you may not park within 25 feet of the curb line of a crossing street, or within 15 feet where there is no curb.","p":"Right. Stay at least 25 feet from the curb line of a crossing street."},"es":{"q":"En Carolina del Norte, la calle tiene bordillo. ¿Qué tan cerca de la línea del bordillo de una calle que cruza puede estacionarse?","o":["No a menos de 10 pies","No a menos de 15 pies","No a menos de 50 pies","No a menos de 25 pies"],"h1":"La distancia más corta es solo para calles sin bordillo.","h2":"En Carolina del Norte, no puede estacionarse a menos de 25 pies de la línea del bordillo de una calle que cruza, ni a menos de 15 pies donde no hay bordillo.","p":"Correcto. Quédese al menos a 25 pies de la línea del bordillo de la calle que cruza."},"zh":{"q":"在 North Carolina，这条街有路缘（curb）。你可以停在离交叉街道路缘线多近的地方？","o":["不能近于 10 英尺","不能近于 15 英尺","不能近于 50 英尺","不能近于 25 英尺"],"h1":"较短的距离只适用于没有路缘的街道。","h2":"在 North Carolina，你不可以停在离交叉街道路缘线 25 英尺以内的地方；没有路缘的地方是 15 英尺以内。","p":"对。要离交叉街道的路缘线至少 25 英尺。"},"vi":{"q":"Ở North Carolina, con đường có lề đường (curb). Bạn được đậu xe gần đường lề của con đường cắt ngang đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 25 feet"],"h1":"Khoảng cách ngắn hơn chỉ dành cho đường không có lề.","h2":"Ở North Carolina, bạn không được đậu xe trong vòng 25 feet tính từ đường lề của con đường cắt ngang, hoặc trong vòng 15 feet nếu không có lề đường.","p":"Đúng. Hãy đậu cách đường lề của con đường cắt ngang ít nhất 25 feet."},"tl":{"q":"Sa North Carolina, may curb ang kalye. Gaano kalapit sa curb line ng kalyeng tumatawid ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 25 feet"],"h1":"Para lang sa mga kalyeng walang curb ang mas maikling distansya.","h2":"Sa North Carolina, hindi ka puwedeng pumarada sa loob ng 25 feet mula sa curb line ng kalyeng tumatawid, o sa loob ng 15 feet kung walang curb.","p":"Tama. Lumayo nang hindi bababa sa 25 feet mula sa curb line ng kalyeng tumatawid."},"ar":{"q":"في North Carolina، للشارع رصيف (curb). إلى أي مدى يجوز أن توقف سيارتك قريبًا من خط رصيف الشارع المتقاطع؟","o":["ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 50 feet","ليس أقرب من 25 feet"],"h1":"المسافة الأقصر هي فقط للشوارع التي ليس لها رصيف.","h2":"في North Carolina، لا يجوز لك أن توقف سيارتك على بُعد أقل من 25 feet من خط رصيف الشارع المتقاطع، أو أقل من 15 feet حيث لا يوجد رصيف.","p":"صحيح. ابقَ على بُعد 25 feet على الأقل من خط رصيف الشارع المتقاطع."},"ref":{"doc":"NC","page":56}},{"id":"nc-043","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, an emergency vehicle has stopped at a crash to give help. How close to it may you park?","o":["No closer than 100 feet","No closer than 25 feet","No closer than 50 feet","No closer than 500 feet"],"h1":"Think of about six car lengths.","h2":"In North Carolina, you may not park within 100 feet of an emergency vehicle that has stopped at a crash or to give help.","p":"Right. Park no closer than 100 feet."},"es":{"q":"En Carolina del Norte, un vehículo de emergencia se detuvo en un choque para dar ayuda. ¿Qué tan cerca de él puede estacionarse?","o":["No a menos de 100 pies","No a menos de 25 pies","No a menos de 50 pies","No a menos de 500 pies"],"h1":"Piense en unos seis carros en fila.","h2":"En Carolina del Norte, no puede estacionarse a menos de 100 pies de un vehículo de emergencia que se detuvo en un choque o para dar ayuda.","p":"Correcto. No se estacione a menos de 100 pies."},"zh":{"q":"在 North Carolina，一辆紧急车辆停在车祸现场帮忙。你可以停在离它多近的地方？","o":["不能近于 100 英尺","不能近于 25 英尺","不能近于 50 英尺","不能近于 500 英尺"],"h1":"想一想大约六辆车排成一排的长度。","h2":"在 North Carolina，你不可以停在离停在车祸现场或停下来帮忙的紧急车辆 100 英尺以内的地方。","p":"对。停车时离它不能近于 100 英尺。"},"vi":{"q":"Ở North Carolina, một xe khẩn cấp đã dừng tại một vụ tai nạn để giúp đỡ. Bạn được đậu xe gần nó đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 500 feet"],"h1":"Hãy nghĩ đến khoảng sáu chiếc xe nối đuôi nhau.","h2":"Ở North Carolina, bạn không được đậu xe trong vòng 100 feet tính từ một xe khẩn cấp đã dừng tại vụ tai nạn hoặc để giúp đỡ.","p":"Đúng. Đậu xe không gần hơn 100 feet."},"tl":{"q":"Sa North Carolina, huminto ang isang emergency vehicle sa isang banggaan para tumulong. Gaano kalapit dito ka puwedeng pumarada?","o":["Hindi lalapit sa 100 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 500 feet"],"h1":"Isipin ang mga anim na kotseng magkakasunod.","h2":"Sa North Carolina, hindi ka puwedeng pumarada sa loob ng 100 feet mula sa isang emergency vehicle na huminto sa banggaan o para tumulong.","p":"Tama. Pumarada nang hindi lalapit sa 100 feet."},"ar":{"q":"في North Carolina، توقفت مركبة طوارئ عند حادث لتقديم المساعدة. إلى أي مدى يجوز أن توقف سيارتك قريبًا منها؟","o":["ليس أقرب من 100 feet","ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 500 feet"],"h1":"فكّر في طول ست سيارات تقريبًا واحدة خلف الأخرى.","h2":"في North Carolina، لا يجوز لك أن توقف سيارتك على بُعد أقل من 100 feet من مركبة طوارئ توقفت عند حادث أو لتقديم المساعدة.","p":"صحيح. أوقف سيارتك على بُعد 100 feet على الأقل."},"ref":{"doc":"NC","page":48}},{"id":"nc-044","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, who must wear a bicycle helmet?","o":["Only riders under 12","All riders and passengers under 16","All riders of any age","Only riders on busy highways"],"h1":"The rule is about age, and it covers passengers too.","h2":"In North Carolina, every bicycle rider and passenger under 16 must wear an approved bicycle helmet.","p":"Right. Riders and passengers under 16 must wear a helmet."},"es":{"q":"En Carolina del Norte, ¿quién debe usar casco en bicicleta?","o":["Solo los ciclistas menores de 12 años","Todos los ciclistas y pasajeros menores de 16 años","Todos los ciclistas de cualquier edad","Solo los ciclistas en carreteras con mucho tráfico"],"h1":"La regla depende de la edad y también incluye a los pasajeros.","h2":"En Carolina del Norte, todo ciclista y pasajero de bicicleta menor de 16 años debe usar un casco aprobado.","p":"Correcto. Los ciclistas y pasajeros menores de 16 años deben usar casco."},"zh":{"q":"在 North Carolina，谁必须戴自行车头盔？","o":["只有未满 12 岁的骑车人","所有未满 16 岁的骑车人和乘客","所有年龄的骑车人","只有在繁忙公路上骑车的人"],"h1":"这条规定和年龄有关，也包括乘客。","h2":"在 North Carolina，每个未满 16 岁的自行车骑车人和乘客都必须戴合格的自行车头盔。","p":"对。未满 16 岁的骑车人和乘客必须戴头盔。"},"vi":{"q":"Ở North Carolina, ai phải đội mũ bảo hiểm khi đi xe đạp?","o":["Chỉ người đi xe đạp dưới 12 tuổi","Tất cả người đi xe đạp và người ngồi sau dưới 16 tuổi","Tất cả người đi xe đạp ở mọi lứa tuổi","Chỉ người đi xe đạp trên đường cao tốc đông xe"],"h1":"Quy định này dựa vào tuổi, và cũng áp dụng cho người ngồi sau.","h2":"Ở North Carolina, mọi người đi xe đạp và người ngồi sau dưới 16 tuổi đều phải đội mũ bảo hiểm xe đạp được chấp thuận.","p":"Đúng. Người đi xe đạp và người ngồi sau dưới 16 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa North Carolina, sino ang dapat magsuot ng bicycle helmet?","o":["Ang mga siklistang wala pang 12 lang","Lahat ng siklista at pasaherong wala pang 16","Lahat ng siklista sa anumang edad","Ang mga siklista sa mga mataong highway lang"],"h1":"Tungkol sa edad ang patakaran, at kasama rin ang mga pasahero.","h2":"Sa North Carolina, dapat magsuot ng aprobadong bicycle helmet ang bawat siklista at pasahero ng bisikleta na wala pang 16.","p":"Tama. Dapat magsuot ng helmet ang mga siklista at pasaherong wala pang 16."},"ar":{"q":"في North Carolina، مَن يجب أن يلبس خوذة الدراجة الهوائية؟","o":["فقط راكبو الدراجات الذين أعمارهم أقل من 12 سنة","كل راكبي الدراجات والركاب الذين أعمارهم أقل من 16 سنة","كل راكبي الدراجات من كل الأعمار","فقط راكبو الدراجات على الطرق السريعة المزدحمة"],"h1":"القاعدة تتعلق بالعمر، وتشمل الركاب أيضًا.","h2":"في North Carolina، يجب على كل مَن عمره أقل من 16 سنة، سواء كان يقود الدراجة الهوائية أو يركب معها، أن يلبس خوذة دراجة معتمدة.","p":"صحيح. يجب على راكبي الدراجات والركاب الذين أعمارهم أقل من 16 سنة أن يلبسوا خوذة."},"ref":{"doc":"NC","page":90}},{"id":"nc-045","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, a bicycle is ridden at night. How far away must its front light be seen?","o":["At least 100 feet","At least 200 feet","At least 300 feet","At least 500 feet"],"h1":"It is farther than the rear red light or reflector must be seen.","h2":"In North Carolina, a bicycle ridden at night needs a front light seen from at least 300 feet and a red rear light or reflector seen from at least 200 feet.","p":"Right. The front light must be seen from at least 300 feet."},"es":{"q":"En Carolina del Norte, alguien anda en bicicleta de noche. ¿Desde qué distancia se debe ver su luz delantera?","o":["Al menos 100 pies","Al menos 200 pies","Al menos 300 pies","Al menos 500 pies"],"h1":"Es más lejos que la distancia desde la que se debe ver la luz o el reflector rojo de atrás.","h2":"En Carolina del Norte, una bicicleta de noche necesita una luz delantera que se vea desde al menos 300 pies y una luz o reflector rojo atrás que se vea desde al menos 200 pies.","p":"Correcto. La luz delantera se debe ver desde al menos 300 pies."},"zh":{"q":"在 North Carolina，有人在晚上骑自行车。它的前灯必须在多远的地方能被看到？","o":["至少 100 英尺","至少 200 英尺","至少 300 英尺","至少 500 英尺"],"h1":"它比后面的红灯或反光片必须被看到的距离更远。","h2":"在 North Carolina，晚上骑的自行车需要一个至少 300 英尺外能看到的前灯，以及一个至少 200 英尺外能看到的红色尾灯或反光片。","p":"对。前灯必须在至少 300 英尺外能被看到。"},"vi":{"q":"Ở North Carolina, có người đi xe đạp vào ban đêm. Đèn trước của xe đạp phải được nhìn thấy từ xa bao nhiêu?","o":["Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 300 feet","Ít nhất 500 feet"],"h1":"Khoảng cách này xa hơn khoảng cách phải nhìn thấy đèn đỏ hoặc miếng phản quang phía sau.","h2":"Ở North Carolina, xe đạp đi vào ban đêm cần một đèn trước nhìn thấy được từ ít nhất 300 feet và một đèn đỏ hoặc miếng phản quang phía sau nhìn thấy được từ ít nhất 200 feet.","p":"Đúng. Đèn trước phải được nhìn thấy từ ít nhất 300 feet."},"tl":{"q":"Sa North Carolina, may nagbibisikleta sa gabi. Gaano kalayo dapat makita ang ilaw sa harap nito?","o":["Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 300 feet","Hindi bababa sa 500 feet"],"h1":"Mas malayo ito kaysa sa layo kung saan dapat makita ang pulang ilaw o reflector sa likod.","h2":"Sa North Carolina, ang bisikletang ginagamit sa gabi ay kailangan ng ilaw sa harap na nakikita mula hindi bababa sa 300 feet at pulang ilaw o reflector sa likod na nakikita mula hindi bababa sa 200 feet.","p":"Tama. Dapat makita ang ilaw sa harap mula hindi bababa sa 300 feet."},"ar":{"q":"في North Carolina، يركب شخص دراجة هوائية في الليل. من أي مسافة يجب أن يُرى ضوؤها الأمامي؟","o":["100 feet على الأقل","200 feet على الأقل","300 feet على الأقل","500 feet على الأقل"],"h1":"هي أبعد من المسافة التي يجب أن يُرى منها الضوء الأحمر أو العاكس في الخلف.","h2":"في North Carolina، الدراجة الهوائية في الليل تحتاج إلى ضوء أمامي يُرى من 300 feet على الأقل، وضوء أحمر أو عاكس في الخلف يُرى من 200 feet على الأقل.","p":"صحيح. يجب أن يُرى الضوء الأمامي من 300 feet على الأقل."},"ref":{"doc":"NC","page":90}},{"id":"nc-046","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how old must you be to ride a moped on a public road?","o":["14 years old","15 years old","18 years old","16 years old"],"h1":"You also need a North Carolina driver license or ID card.","h2":"In North Carolina, you must be at least 16 and have a North Carolina driver license or ID card to ride a moped on a public road.","p":"Right. You must be at least 16 to ride a moped."},"es":{"q":"En Carolina del Norte, ¿qué edad debe tener para manejar un moped en una vía pública?","o":["14 años","15 años","18 años","16 años"],"h1":"También necesita una licencia de manejar o una tarjeta de identificación de Carolina del Norte.","h2":"En Carolina del Norte, debe tener al menos 16 años y una licencia de manejar o tarjeta de identificación de Carolina del Norte para manejar un moped en una vía pública.","p":"Correcto. Debe tener al menos 16 años para manejar un moped."},"zh":{"q":"在 North Carolina，你必须几岁才可以在公共道路上骑轻便摩托车（moped）？","o":["14 岁","15 岁","18 岁","16 岁"],"h1":"你还需要 North Carolina 的驾照或身份证。","h2":"在 North Carolina，你必须至少 16 岁，并且有 North Carolina 的驾照或身份证，才可以在公共道路上骑轻便摩托车。","p":"对。你必须至少 16 岁才可以骑轻便摩托车。"},"vi":{"q":"Ở North Carolina, bạn phải bao nhiêu tuổi mới được chạy xe gắn máy nhỏ (moped) trên đường công cộng?","o":["14 tuổi","15 tuổi","18 tuổi","16 tuổi"],"h1":"Bạn cũng cần bằng lái hoặc thẻ căn cước của North Carolina.","h2":"Ở North Carolina, bạn phải ít nhất 16 tuổi và có bằng lái hoặc thẻ căn cước North Carolina mới được chạy moped trên đường công cộng.","p":"Đúng. Bạn phải ít nhất 16 tuổi mới được chạy moped."},"tl":{"q":"Sa North Carolina, ilang taon ka dapat para makapagmaneho ng moped sa pampublikong kalsada?","o":["14 taong gulang","15 taong gulang","18 taong gulang","16 taong gulang"],"h1":"Kailangan mo rin ng driver license o ID card ng North Carolina.","h2":"Sa North Carolina, dapat ay hindi bababa sa 16 ang edad mo at may driver license o ID card ka ng North Carolina para makapagmaneho ng moped sa pampublikong kalsada.","p":"Tama. Dapat ay hindi bababa sa 16 ka para makapagmaneho ng moped."},"ar":{"q":"في North Carolina، كم يجب أن يكون عمرك لتقود دراجة نارية صغيرة (moped) على طريق عام؟","o":["14 سنة","15 سنة","18 سنة","16 سنة"],"h1":"تحتاج أيضًا إلى رخصة قيادة أو بطاقة هوية من North Carolina.","h2":"في North Carolina، يجب أن يكون عمرك 16 سنة على الأقل وأن تكون لديك رخصة قيادة أو بطاقة هوية من North Carolina لتقود moped على طريق عام.","p":"صحيح. يجب أن يكون عمرك 16 سنة على الأقل لتقود moped."},"ref":{"doc":"NC","page":93}},{"id":"nc-047","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, as a general rule, who may not ride in the open bed of a pickup truck?","o":["Children under 16","Children under 12","Anyone under 18","Adults over 65"],"h1":"The age is the same as the one for bicycle helmets.","h2":"In North Carolina, children under 16 may not ride in the open bed of a pickup truck, except in a few cases such as when an adult in the bed supervises them.","p":"Right. Children under 16 may not ride in an open truck bed."},"es":{"q":"En Carolina del Norte, como regla general, ¿quién no puede viajar en la caja abierta de una camioneta pickup?","o":["Los niños menores de 16 años","Los niños menores de 12 años","Cualquier persona menor de 18 años","Los adultos mayores de 65 años"],"h1":"La edad es la misma que para el casco de bicicleta.","h2":"En Carolina del Norte, los niños menores de 16 años no pueden viajar en la caja abierta de una camioneta pickup, salvo en algunos casos, como cuando un adulto en la caja los supervisa.","p":"Correcto. Los niños menores de 16 años no pueden viajar en una caja abierta."},"zh":{"q":"在 North Carolina，一般来说，谁不可以坐在皮卡车开放式的后车斗里？","o":["未满 16 岁的孩子","未满 12 岁的孩子","任何未满 18 岁的人","65 岁以上的成年人"],"h1":"这个年龄和自行车头盔规定的年龄一样。","h2":"在 North Carolina，未满 16 岁的孩子不可以坐在皮卡车开放式的后车斗里，只有少数情况例外，例如有成年人在车斗里看着他们。","p":"对。未满 16 岁的孩子不可以坐在开放式的后车斗里。"},"vi":{"q":"Ở North Carolina, theo quy định chung, ai không được ngồi trong thùng hở phía sau xe bán tải (pickup)?","o":["Trẻ em dưới 16 tuổi","Trẻ em dưới 12 tuổi","Bất kỳ ai dưới 18 tuổi","Người lớn trên 65 tuổi"],"h1":"Độ tuổi này giống với độ tuổi phải đội mũ bảo hiểm xe đạp.","h2":"Ở North Carolina, trẻ em dưới 16 tuổi không được ngồi trong thùng hở phía sau xe bán tải, trừ một vài trường hợp, ví dụ khi có một người lớn ngồi trong thùng trông chừng các em.","p":"Đúng. Trẻ em dưới 16 tuổi không được ngồi trong thùng xe hở."},"tl":{"q":"Sa North Carolina, bilang pangkalahatang patakaran, sino ang hindi puwedeng sumakay sa bukas na likod (bed) ng pickup truck?","o":["Mga batang wala pang 16","Mga batang wala pang 12","Sinumang wala pang 18","Mga adultong lampas 65"],"h1":"Pareho ang edad sa edad para sa bicycle helmet.","h2":"Sa North Carolina, hindi puwedeng sumakay ang mga batang wala pang 16 sa bukas na likod ng pickup truck, maliban sa ilang kaso gaya ng kapag may adulto sa likod na nagbabantay sa kanila.","p":"Tama. Hindi puwedeng sumakay ang mga batang wala pang 16 sa bukas na likod ng truck."},"ar":{"q":"في North Carolina، كقاعدة عامة، مَن لا يجوز له أن يركب في الصندوق الخلفي المكشوف لشاحنة pickup؟","o":["الأطفال الذين أعمارهم أقل من 16 سنة","الأطفال الذين أعمارهم أقل من 12 سنة","أي شخص عمره أقل من 18 سنة","الكبار الذين أعمارهم أكثر من 65 سنة"],"h1":"العمر هو نفسه العمر الخاص بخوذة الدراجة الهوائية.","h2":"في North Carolina، لا يجوز للأطفال الذين أعمارهم أقل من 16 سنة أن يركبوا في الصندوق الخلفي المكشوف لشاحنة pickup، إلا في حالات قليلة، مثل وجود شخص بالغ في الصندوق يراقبهم.","p":"صحيح. لا يجوز للأطفال الذين أعمارهم أقل من 16 سنة أن يركبوا في صندوق شاحنة مكشوف."},"ref":{"doc":"NC","page":45}},{"id":"nc-048","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, your car has a back seat and a front passenger air bag that is turned on. Which child must ride in the back seat?","o":["A child under 8 who weighs less than 80 pounds","A child under 5 who weighs less than 40 pounds","Any child under 16","A child under 10 who weighs less than 60 pounds"],"h1":"It is a younger, lighter child than the one who needs a booster seat.","h2":"In North Carolina, when the car has an active front passenger air bag and a back seat, a child under 5 who weighs less than 40 pounds must ride in the back seat, unless the child seat is made for use with the air bag.","p":"Right. A child under 5 and under 40 pounds must ride in the back."},"es":{"q":"En Carolina del Norte, su carro tiene asiento trasero y una bolsa de aire del pasajero delantero que está encendida. ¿Qué niño debe ir en el asiento trasero?","o":["Un niño menor de 8 años que pesa menos de 80 libras","Un niño menor de 5 años que pesa menos de 40 libras","Cualquier niño menor de 16 años","Un niño menor de 10 años que pesa menos de 60 libras"],"h1":"Es un niño más pequeño y liviano que el que necesita un asiento elevado.","h2":"En Carolina del Norte, cuando el carro tiene una bolsa de aire delantera del pasajero activa y un asiento trasero, un niño menor de 5 años que pesa menos de 40 libras debe ir atrás, salvo que su asiento esté hecho para usarse con la bolsa de aire.","p":"Correcto. Un niño menor de 5 años y de menos de 40 libras debe ir atrás."},"zh":{"q":"在 North Carolina，你的车有后座，而且前排乘客安全气囊是开着的。哪个孩子必须坐在后座？","o":["未满 8 岁、体重不到 80 磅的孩子","未满 5 岁、体重不到 40 磅的孩子","任何未满 16 岁的孩子","未满 10 岁、体重不到 60 磅的孩子"],"h1":"这个孩子比需要加高座椅的孩子更小、更轻。","h2":"在 North Carolina，当车里有开着的前排乘客安全气囊而且有后座时，未满 5 岁、体重不到 40 磅的孩子必须坐在后座，除非儿童座椅是专为和安全气囊一起使用而设计的。","p":"对。未满 5 岁、不到 40 磅的孩子必须坐在后座。"},"vi":{"q":"Ở North Carolina, xe của bạn có ghế sau và túi khí của ghế hành khách phía trước đang bật. Trẻ nào phải ngồi ở ghế sau?","o":["Trẻ dưới 8 tuổi nặng dưới 80 pound","Trẻ dưới 5 tuổi nặng dưới 40 pound","Bất kỳ trẻ nào dưới 16 tuổi","Trẻ dưới 10 tuổi nặng dưới 60 pound"],"h1":"Đó là trẻ nhỏ và nhẹ hơn trẻ cần ghế nâng (booster seat).","h2":"Ở North Carolina, khi xe có túi khí hành khách phía trước đang bật và có ghế sau, trẻ dưới 5 tuổi nặng dưới 40 pound phải ngồi ở ghế sau, trừ khi ghế trẻ em được làm để dùng với túi khí.","p":"Đúng. Trẻ dưới 5 tuổi và dưới 40 pound phải ngồi ở phía sau."},"tl":{"q":"Sa North Carolina, may back seat ang kotse mo at nakabukas ang air bag ng pasahero sa harap. Aling bata ang dapat umupo sa back seat?","o":["Batang wala pang 8 na mas magaan sa 80 pounds","Batang wala pang 5 na mas magaan sa 40 pounds","Sinumang batang wala pang 16","Batang wala pang 10 na mas magaan sa 60 pounds"],"h1":"Mas bata at mas magaan ito kaysa sa batang kailangan ng booster seat.","h2":"Sa North Carolina, kapag may nakabukas na air bag ng pasahero sa harap at may back seat ang kotse, ang batang wala pang 5 na mas magaan sa 40 pounds ay dapat umupo sa back seat, maliban kung ginawa ang child seat para gamitin kasama ng air bag.","p":"Tama. Ang batang wala pang 5 at mas magaan sa 40 pounds ay dapat umupo sa likod."},"ar":{"q":"في North Carolina، في سيارتك مقعد خلفي، والوسادة الهوائية للراكب الأمامي تعمل. أي طفل يجب أن يجلس في المقعد الخلفي؟","o":["طفل عمره أقل من 8 سنوات ووزنه أقل من 80 pounds","طفل عمره أقل من 5 سنوات ووزنه أقل من 40 pounds","أي طفل عمره أقل من 16 سنة","طفل عمره أقل من 10 سنوات ووزنه أقل من 60 pounds"],"h1":"هو طفل أصغر وأخف من الطفل الذي يحتاج إلى مقعد رافع (booster seat).","h2":"في North Carolina، عندما تكون في السيارة وسادة هوائية تعمل للراكب الأمامي ومقعد خلفي، يجب أن يجلس الطفل الذي عمره أقل من 5 سنوات ووزنه أقل من 40 pounds في المقعد الخلفي، إلا إذا كان مقعد الطفل مصنوعًا للاستعمال مع الوسادة الهوائية.","p":"صحيح. الطفل الذي عمره أقل من 5 سنوات ووزنه أقل من 40 pounds يجب أن يجلس في الخلف."},"ref":{"doc":"NC","page":44}},{"id":"nc-049","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, you are driving the same way as a funeral procession. When may you pass it?","o":["Any time, if you honk first","Whenever it goes slower than 25 mph","Only when the road has two or more lanes going your way","Never, on any road"],"h1":"It depends on how many lanes go in your direction.","h2":"In North Carolina, you may not pass a funeral procession going your way unless the road is marked for two or more lanes in that direction.","p":"Right. Pass only when there are two or more lanes going your way."},"es":{"q":"En Carolina del Norte, usted maneja en la misma dirección que un cortejo fúnebre. ¿Cuándo puede rebasarlo?","o":["En cualquier momento, si toca la bocina primero","Cuando vaya a menos de 25 mph","Solo cuando la vía tiene dos o más carriles en su dirección","Nunca, en ninguna vía"],"h1":"Depende de cuántos carriles van en su dirección.","h2":"En Carolina del Norte, no puede rebasar un cortejo fúnebre que va en su dirección, a menos que la vía tenga marcados dos o más carriles en esa dirección.","p":"Correcto. Rebase solo cuando hay dos o más carriles en su dirección."},"zh":{"q":"在 North Carolina，你和一支送葬车队往同一个方向开。你什么时候可以超过它？","o":["任何时候，只要先按喇叭","只要它的速度低于 25 mph","只有当道路在你的方向有两条或以上车道时","永远不可以，在任何道路上都不行"],"h1":"这要看你的方向有几条车道。","h2":"在 North Carolina，你不可以超过和你同方向的送葬车队，除非道路在那个方向标有两条或以上车道。","p":"对。只有在你的方向有两条或以上车道时才可以超车。"},"vi":{"q":"Ở North Carolina, bạn đang lái cùng chiều với một đoàn xe đưa tang. Khi nào bạn được vượt đoàn xe này?","o":["Bất cứ lúc nào, nếu bạn bấm còi trước","Bất cứ khi nào đoàn xe chạy chậm hơn 25 mph","Chỉ khi con đường có từ hai làn xe trở lên đi theo chiều của bạn","Không bao giờ, trên bất kỳ con đường nào"],"h1":"Điều này tùy thuộc vào số làn xe đi theo chiều của bạn.","h2":"Ở North Carolina, bạn không được vượt đoàn xe đưa tang đi cùng chiều với bạn, trừ khi con đường có kẻ vạch từ hai làn xe trở lên theo chiều đó.","p":"Đúng. Chỉ vượt khi có từ hai làn xe trở lên đi theo chiều của bạn."},"tl":{"q":"Sa North Carolina, nagmamaneho ka sa parehong direksyon ng isang funeral procession. Kailan mo ito puwedeng lampasan?","o":["Kahit kailan, kung bumusina ka muna","Tuwing mas mabagal ito sa 25 mph","Kapag may dalawa o higit pang lane lang ang kalsada sa direksyon mo","Hindi kailanman, sa anumang kalsada"],"h1":"Depende ito sa kung ilang lane ang papunta sa direksyon mo.","h2":"Sa North Carolina, hindi mo puwedeng lampasan ang funeral procession na papunta sa direksyon mo maliban kung may marka ang kalsada ng dalawa o higit pang lane sa direksyong iyon.","p":"Tama. Lumampas lang kapag may dalawa o higit pang lane sa direksyon mo."},"ar":{"q":"في North Carolina، أنت تقود في نفس اتجاه موكب جنازة. متى يجوز لك أن تتجاوزه؟","o":["في أي وقت، إذا ضغطت على البوق أولًا","كلما سار بسرعة أقل من 25 mph","فقط عندما يكون للطريق مساران أو أكثر في اتجاهك","أبدًا، على أي طريق"],"h1":"يعتمد ذلك على عدد المسارات في اتجاهك.","h2":"في North Carolina، لا يجوز لك أن تتجاوز موكب جنازة يسير في اتجاهك إلا إذا كان الطريق مُعلَّمًا بمسارين أو أكثر في ذلك الاتجاه.","p":"صحيح. تجاوز فقط عندما يكون هناك مساران أو أكثر في اتجاهك."},"ref":{"doc":"NC","page":52}},{"id":"nc-050","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, trash is thrown from your car and you are convicted of littering for the first time. What is the lowest fine?","o":["$25","$100","$500","$250"],"h1":"The highest fine for a first offense is $1,000.","h2":"In North Carolina, a first littering conviction carries a fine of at least $250 and up to $1,000, and the driver is held responsible for litter from the vehicle.","p":"Right. The fine starts at $250."},"es":{"q":"En Carolina del Norte, alguien tira basura desde su carro y usted es declarado culpable de tirar basura por primera vez. ¿Cuál es la multa más baja?","o":["$25","$100","$500","$250"],"h1":"La multa más alta para una primera vez es $1,000.","h2":"En Carolina del Norte, una primera condena por tirar basura tiene una multa de al menos $250 y hasta $1,000, y el conductor es responsable de la basura que sale del vehículo.","p":"Correcto. La multa empieza en $250."},"zh":{"q":"在 North Carolina，有人从你的车里扔出垃圾，你第一次被判乱扔垃圾。最低罚款是多少？","o":["$25","$100","$500","$250"],"h1":"第一次的最高罚款是 $1,000。","h2":"在 North Carolina，第一次被判乱扔垃圾会被罚款至少 $250，最多 $1,000，而且司机要对从车里扔出的垃圾负责。","p":"对。罚款从 $250 起。"},"vi":{"q":"Ở North Carolina, có người ném rác ra khỏi xe của bạn và bạn bị kết tội xả rác lần đầu tiên. Mức phạt thấp nhất là bao nhiêu?","o":["$25","$100","$500","$250"],"h1":"Mức phạt cao nhất cho lần đầu là $1,000.","h2":"Ở North Carolina, lần đầu bị kết tội xả rác sẽ bị phạt ít nhất $250 và tối đa $1,000, và tài xế phải chịu trách nhiệm về rác từ xe của mình.","p":"Đúng. Mức phạt bắt đầu từ $250."},"tl":{"q":"Sa North Carolina, may nagtapon ng basura mula sa kotse mo at napatunayan kang nagkasala ng pagkakalat sa unang pagkakataon. Ano ang pinakamababang multa?","o":["$25","$100","$500","$250"],"h1":"Ang pinakamataas na multa sa unang paglabag ay $1,000.","h2":"Sa North Carolina, ang unang conviction sa pagkakalat ay may multang hindi bababa sa $250 at hanggang $1,000, at ang driver ang mananagot sa basurang galing sa sasakyan.","p":"Tama. Nagsisimula sa $250 ang multa."},"ar":{"q":"في North Carolina، رمى أحدهم القمامة من سيارتك وأُدنت برمي القمامة لأول مرة. ما أقل غرامة؟","o":["$25","$100","$500","$250"],"h1":"أعلى غرامة في المرة الأولى هي $1,000.","h2":"في North Carolina، الإدانة الأولى برمي القمامة تجلب غرامة لا تقل عن $250 وتصل إلى $1,000، والسائق مسؤول عن القمامة التي تُرمى من المركبة.","p":"صحيح. تبدأ الغرامة من $250."},"ref":{"doc":"NC","page":95}},{"id":"nc-051","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, who can get a regular learner permit (not the teen Level 1 permit)?","o":["People 15 and older","People 16 and older","People 18 and older","People 21 and older"],"h1":"The teen permit has its own rules. The regular permit is for adults.","h2":"In North Carolina, the regular learner permit is for people who are 18 or older.","p":"Right. The regular learner permit is for people 18 and older."},"es":{"q":"En Carolina del Norte, ¿quién puede obtener un permiso de aprendizaje regular (no el permiso de Nivel 1 para adolescentes)?","o":["Personas de 15 años o más","Personas de 16 años o más","Personas de 18 años o más","Personas de 21 años o más"],"h1":"El permiso para adolescentes tiene sus propias reglas. El permiso regular es para adultos.","h2":"En Carolina del Norte, el permiso de aprendizaje regular es para personas de 18 años o más.","p":"Correcto. El permiso de aprendizaje regular es para personas de 18 años o más."},"ref":{"doc":"NC","page":8}},{"id":"nc-052","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you have a motorcycle learner permit. May you carry a passenger?","o":["No, the permit is for riding without passengers","Yes, one adult passenger","Yes, if the passenger also has a permit","Yes, during daylight only"],"h1":"A learner is still building skills. Think about who rides along.","h2":"In North Carolina, a motorcycle learner permit lets you ride only without passengers.","p":"Right. A motorcycle learner permit means no passengers."},"es":{"q":"En Carolina del Norte, usted tiene un permiso de aprendizaje para motocicleta. ¿Puede llevar un pasajero?","o":["No, el permiso es para manejar sin pasajeros","Sí, un pasajero adulto","Sí, si el pasajero también tiene permiso","Sí, solo de día"],"h1":"Un aprendiz todavía está ganando destreza. Piense en quién va con usted.","h2":"En Carolina del Norte, el permiso de aprendizaje para motocicleta solo le permite manejar sin pasajeros.","p":"Correcto. Con permiso de aprendizaje para motocicleta, no se llevan pasajeros."},"ref":{"doc":"NC","page":8}},{"id":"nc-053","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how long is a motorcycle learner permit valid?","o":["30 days","60 days","6 months","12 months"],"h1":"It lasts one year, and it can be renewed once for a shorter time.","h2":"In North Carolina, a motorcycle learner permit is valid for 12 months and can be renewed once for six more months.","p":"Right. It is valid for 12 months."},"es":{"q":"En Carolina del Norte, ¿por cuánto tiempo es válido el permiso de aprendizaje para motocicleta?","o":["30 días","60 días","6 meses","12 meses"],"h1":"Dura un año, y se puede renovar una vez por menos tiempo.","h2":"En Carolina del Norte, el permiso de aprendizaje para motocicleta es válido por 12 meses y se puede renovar una vez por seis meses más.","p":"Correcto. Es válido por 12 meses."},"ref":{"doc":"NC","page":9}},{"id":"nc-054","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, what driver education must a teen finish before taking the Level 1 permit test?","o":["10 hours in class and 2 hours behind the wheel","30 hours in class and 6 hours behind the wheel","20 hours in class and 20 hours behind the wheel","No course is needed"],"h1":"The classroom part is much longer than the driving part.","h2":"In North Carolina, a teen must pass an approved driver education course of at least 30 classroom hours and 6 behind-the-wheel hours before the permit test.","p":"Right. 30 hours in class and 6 hours behind the wheel."},"es":{"q":"En Carolina del Norte, ¿qué educación vial debe completar un adolescente antes del examen del permiso de Nivel 1?","o":["10 horas en clase y 2 horas al volante","30 horas en clase y 6 horas al volante","20 horas en clase y 20 horas al volante","No se necesita ningún curso"],"h1":"La parte en clase es mucho más larga que la parte al volante.","h2":"En Carolina del Norte, el adolescente debe aprobar un curso de educación vial de al menos 30 horas en clase y 6 horas al volante antes del examen del permiso.","p":"Correcto. 30 horas en clase y 6 horas al volante."},"ref":{"doc":"NC","page":12}},{"id":"nc-055","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, a teen with a Level 1 permit is driving. Who may sit in the front seat?","o":["Any passenger wearing a seat belt","Any adult","Only the driver and the supervising driver","Only the driver; the supervisor sits in back"],"h1":"The supervising driver needs to be right beside the learner.","h2":"In North Carolina, while a Level 1 permit holder drives, no one but the driver and the supervising driver may sit in the front seat.","p":"Right. Only the driver and the supervising driver sit in front."},"es":{"q":"En Carolina del Norte, un adolescente con permiso de Nivel 1 está manejando. ¿Quién puede ir en el asiento delantero?","o":["Cualquier pasajero con cinturón","Cualquier adulto","Solo el conductor y el conductor supervisor","Solo el conductor; el supervisor va atrás"],"h1":"El conductor supervisor tiene que estar justo al lado del aprendiz.","h2":"En Carolina del Norte, mientras maneja quien tiene permiso de Nivel 1, solo el conductor y el conductor supervisor pueden ir en el asiento delantero.","p":"Correcto. Adelante van solo el conductor y el conductor supervisor."},"ref":{"doc":"NC","page":12}},{"id":"nc-056","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a Level 2 driver with no supervisor already has one non-family passenger under 21. When may one more non-family passenger under 21 ride?","o":["When that passenger is a student being driven directly to or from school","On weekends","When the trip is shorter than 10 miles","Never, in any case"],"h1":"The exception is about a daily trip that students make.","h2":"In North Carolina, a Level 2 driver may carry one more non-household passenger under 21 only if that passenger is a student being driven directly to or from school.","p":"Right. One more is allowed only for a student going directly to or from school."},"es":{"q":"En Carolina del Norte, un conductor de Nivel 2 sin supervisor ya lleva un pasajero menor de 21 años que no es de su familia. ¿Cuándo puede ir otro pasajero menor de 21 que no es de la familia?","o":["Cuando ese pasajero es un estudiante que va directamente a la escuela o regresa de ella","Los fines de semana","Cuando el viaje es de menos de 10 millas","Nunca, en ningún caso"],"h1":"La excepción tiene que ver con un viaje diario que hacen los estudiantes.","h2":"En Carolina del Norte, un conductor de Nivel 2 puede llevar otro pasajero menor de 21 que no vive en su hogar solo si es un estudiante que va directamente a la escuela o regresa de ella.","p":"Correcto. Se permite uno más solo si es un estudiante que va directo a la escuela o regresa de ella."},"ref":{"doc":"NC","page":13}},{"id":"nc-057","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, your license says you must wear corrective lenses. What is the penalty for driving without them?","o":["Only a warning","The same as driving without a license","A $10 fine","None, if you can see well enough"],"h1":"Your license is only good when you follow its restriction.","h2":"In North Carolina, driving without your required corrective lenses carries the same penalty as driving without a license.","p":"Right. It counts the same as driving without a license."},"es":{"q":"En Carolina del Norte, su licencia dice que debe usar lentes correctivos. ¿Cuál es la sanción por manejar sin ellos?","o":["Solo una advertencia","La misma que por manejar sin licencia","Una multa de $10","Ninguna, si ve bastante bien"],"h1":"Su licencia solo es válida cuando cumple su restricción.","h2":"En Carolina del Norte, manejar sin los lentes correctivos que exige su licencia tiene la misma sanción que manejar sin licencia.","p":"Correcto. Cuenta igual que manejar sin licencia."},"ref":{"doc":"NC","page":9}},{"id":"nc-058","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how can you tell that a driver license is a REAL ID?","o":["It has a heart symbol","It says NOT FOR FEDERAL IDENTIFICATION","It is printed up and down (vertical)","It has a star"],"h1":"Look for a small shape on the card that the other cards do not have.","h2":"In North Carolina, every REAL ID license, permit or ID card has a star; cards that are not REAL ID say NOT FOR FEDERAL IDENTIFICATION.","p":"Right. A REAL ID has a star."},"es":{"q":"En Carolina del Norte, ¿cómo sabe que una licencia es REAL ID?","o":["Tiene un símbolo de corazón","Dice NOT FOR FEDERAL IDENTIFICATION","Está impresa en vertical","Tiene una estrella"],"h1":"Busque una pequeña figura en la tarjeta que las otras tarjetas no tienen.","h2":"En Carolina del Norte, toda licencia, permiso o identificación REAL ID tiene una estrella; las que no son REAL ID dicen NOT FOR FEDERAL IDENTIFICATION.","p":"Correcto. Una REAL ID tiene una estrella."},"ref":{"doc":"NC","page":24}},{"id":"nc-059","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, how early may you renew your driver license before it expires?","o":["Only on the day it expires","Up to 30 days before","Up to 180 days (about six months) before","Up to two years before"],"h1":"The DMV mails a reminder about half a year ahead.","h2":"In North Carolina, you may renew your driver license any time within 180 days, about six months, before it expires.","p":"Right. Up to 180 days before it expires."},"es":{"q":"En Carolina del Norte, ¿con cuánta anticipación puede renovar su licencia antes de que venza?","o":["Solo el día en que vence","Hasta 30 días antes","Hasta 180 días (unos seis meses) antes","Hasta dos años antes"],"h1":"El DMV envía un aviso por correo como medio año antes.","h2":"En Carolina del Norte, puede renovar su licencia en cualquier momento dentro de los 180 días, unos seis meses, antes de que venza.","p":"Correcto. Hasta 180 días antes de que venza."},"ref":{"doc":"NC","page":26}},{"id":"nc-060","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you are 67 years old when your driver license is issued. How long is it valid?","o":["5 years","2 years","8 years","10 years"],"h1":"Younger adults get a longer license. Drivers 66 and older get a shorter one.","h2":"In North Carolina, a license issued to a driver 66 or older is valid for 5 years.","p":"Right. From age 66, a license lasts 5 years."},"es":{"q":"En Carolina del Norte, usted tiene 67 años cuando le expiden la licencia. ¿Por cuánto tiempo es válida?","o":["5 años","2 años","8 años","10 años"],"h1":"Los adultos más jóvenes reciben una licencia más larga. Los de 66 años o más reciben una más corta.","h2":"En Carolina del Norte, la licencia expedida a un conductor de 66 años o más es válida por 5 años.","p":"Correcto. Desde los 66 años, la licencia dura 5 años."},"ref":{"doc":"NC","page":28}},{"id":"nc-061","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 10 days","Within 60 days","Within 6 months","Only when you renew"],"h1":"It is the same number of days a new resident has to get a license here.","h2":"In North Carolina, you must tell the DMV about a new address within 60 days and get a duplicate license.","p":"Right. Within 60 days."},"es":{"q":"En Carolina del Norte, usted se muda a una nueva casa. ¿En cuánto tiempo debe informar al DMV su nueva dirección?","o":["En 10 días","En 60 días","En 6 meses","Solo cuando renueve"],"h1":"Es el mismo número de días que tiene un nuevo residente para sacar la licencia aquí.","h2":"En Carolina del Norte, debe informar al DMV su nueva dirección en un plazo de 60 días y obtener un duplicado de la licencia.","p":"Correcto. En 60 días."},"ref":{"doc":"NC","page":28}},{"id":"nc-062","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, a driver's test shows a blood alcohol level of 0.08. What happens to the license right away?","o":["Nothing until the court date","It is suspended for 24 hours","It is revoked at once for at least 30 days","It is revoked for life"],"h1":"The loss starts right away, before any trial.","h2":"In North Carolina, a test result of 0.08 or more means the license is revoked immediately for at least 30 days.","p":"Right. It is revoked at once for at least 30 days."},"es":{"q":"En Carolina del Norte, la prueba de un conductor muestra un nivel de alcohol en la sangre de 0.08. ¿Qué pasa con la licencia de inmediato?","o":["Nada hasta el día del juicio","Se suspende por 24 horas","Se revoca de inmediato por al menos 30 días","Se revoca de por vida"],"h1":"La pérdida empieza enseguida, antes de cualquier juicio.","h2":"En Carolina del Norte, un resultado de 0.08 o más significa que la licencia se revoca de inmediato por al menos 30 días.","p":"Correcto. Se revoca de inmediato por al menos 30 días."},"ref":{"doc":"NC","page":31}},{"id":"nc-063","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, what blood alcohol level counts as impaired for a person driving a commercial motor vehicle?","o":["0.10 or more","0.08 or more","0.06 or more","0.04 or more"],"h1":"It is half of the limit for a regular car driver.","h2":"In North Carolina, a commercial motor vehicle driver is impaired at a blood alcohol level of 0.04 or more.","p":"Right. 0.04 or more for a commercial vehicle."},"es":{"q":"En Carolina del Norte, ¿qué nivel de alcohol en la sangre se considera estar bajo los efectos para quien maneja un vehículo comercial?","o":["0.10 o más","0.08 o más","0.06 o más","0.04 o más"],"h1":"Es la mitad del límite para quien maneja un auto normal.","h2":"En Carolina del Norte, quien maneja un vehículo comercial está bajo los efectos con un nivel de alcohol de 0.04 o más.","p":"Correcto. 0.04 o más en un vehículo comercial."},"ref":{"doc":"NC","page":31}},{"id":"nc-064","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, what must a person convicted of DWI for the second time serve?","o":["A jail sentence","Only community service","Only a fine","Nothing more than the first time"],"h1":"The second time is punished more harshly than the first.","h2":"In North Carolina, a person convicted of DWI for the second time must serve a jail sentence.","p":"Right. A second DWI means jail time."},"es":{"q":"En Carolina del Norte, ¿qué debe cumplir una persona condenada por DWI por segunda vez?","o":["Una pena de cárcel","Solo servicio comunitario","Solo una multa","Nada más que la primera vez"],"h1":"La segunda vez se castiga con más dureza que la primera.","h2":"En Carolina del Norte, una persona condenada por DWI por segunda vez debe cumplir una pena de cárcel.","p":"Correcto. Un segundo DWI significa cárcel."},"ref":{"doc":"NC","page":31}},{"id":"nc-065","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, a driver is convicted of DWI a second time, and the first offense was within the past three years. How long is the license revoked?","o":["1 year","4 years","6 months","90 days"],"h1":"It is much longer than the one year for a first conviction.","h2":"In North Carolina, a second DWI conviction with a prior offense within three years means the license is revoked for four years.","p":"Right. Four years."},"es":{"q":"En Carolina del Norte, un conductor es condenado por DWI por segunda vez, y el primer delito fue en los últimos tres años. ¿Por cuánto tiempo se revoca la licencia?","o":["1 año","4 años","6 meses","90 días"],"h1":"Es mucho más que el año de la primera condena.","h2":"En Carolina del Norte, una segunda condena por DWI con un delito anterior en los últimos tres años significa que la licencia se revoca por cuatro años.","p":"Correcto. Cuatro años."},"ref":{"doc":"NC","page":32}},{"id":"nc-066","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, a driver is convicted of DWI a third time, and one earlier conviction was within the past five years. What happens to the license?","o":["It is revoked for 1 year","It is revoked for 4 years","It is revoked permanently","It is suspended for 60 days"],"h1":"Three times is the most serious level.","h2":"In North Carolina, a third DWI conviction, with at least one earlier conviction in the past five years, means the license is revoked permanently.","p":"Right. The license is revoked permanently."},"es":{"q":"En Carolina del Norte, un conductor es condenado por DWI por tercera vez, y una condena anterior fue en los últimos cinco años. ¿Qué pasa con la licencia?","o":["Se revoca por 1 año","Se revoca por 4 años","Se revoca de forma permanente","Se suspende por 60 días"],"h1":"Tres veces es el nivel más grave.","h2":"En Carolina del Norte, una tercera condena por DWI, con al menos una condena anterior en los últimos cinco años, significa que la licencia se revoca de forma permanente.","p":"Correcto. La licencia se revoca de forma permanente."},"ref":{"doc":"NC","page":32}},{"id":"nc-067","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, your license is given back for the first time after a DWI. What alcohol limit applies to you when you drive?","o":["0.08","0.10","0.06","0.04"],"h1":"It is half the usual limit, and it drops to zero after a second restoration.","h2":"In North Carolina, after the first restoration following a DWI, your license carries an alcohol limit of 0.04.","p":"Right. The limit is 0.04 after the first restoration."},"es":{"q":"En Carolina del Norte, le devuelven la licencia por primera vez después de un DWI. ¿Qué límite de alcohol se le aplica al manejar?","o":["0.08","0.10","0.06","0.04"],"h1":"Es la mitad del límite normal, y baja a cero después de una segunda restitución.","h2":"En Carolina del Norte, después de la primera restitución tras un DWI, su licencia tiene un límite de alcohol de 0.04.","p":"Correcto. El límite es 0.04 después de la primera restitución."},"ref":{"doc":"NC","page":32}},{"id":"nc-068","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you let an underage friend use your driver license to try to buy beer. If you are convicted, what happens to your license?","o":["Nothing; only your friend is punished","It is suspended for 30 days","It is revoked for one year","You get 2 points"],"h1":"The law punishes the person who lends the ID too, not only the buyer.","h2":"In North Carolina, letting an underage person use your license to buy or try to buy alcohol leads to a one-year license revocation if you are convicted.","p":"Right. Your license is revoked for one year."},"es":{"q":"En Carolina del Norte, usted deja que un amigo menor de edad use su licencia para intentar comprar cerveza. Si lo condenan, ¿qué pasa con su licencia?","o":["Nada; solo castigan a su amigo","Se suspende por 30 días","Se revoca por un año","Recibe 2 puntos"],"h1":"La ley también castiga a quien presta la identificación, no solo al comprador.","h2":"En Carolina del Norte, dejar que un menor use su licencia para comprar o intentar comprar alcohol lleva a la revocación de la licencia por un año si lo condenan.","p":"Correcto. Su licencia se revoca por un año."},"ref":{"doc":"NC","page":33}},{"id":"nc-069","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you finish a driver improvement clinic. What happens to your driver license points?","o":["Three points are taken off your record","All points are erased","Nothing changes","One point is taken off"],"h1":"Finishing the clinic removes a few points, not all of them.","h2":"In North Carolina, when you complete a driver improvement clinic, three points are taken off your driving record.","p":"Right. Three points come off."},"es":{"q":"En Carolina del Norte, usted termina una clínica de mejoramiento para conductores. ¿Qué pasa con los puntos de su licencia?","o":["Le quitan tres puntos de su historial","Le borran todos los puntos","No cambia nada","Le quitan un punto"],"h1":"Terminar la clínica quita algunos puntos, no todos.","h2":"En Carolina del Norte, cuando completa una clínica de mejoramiento para conductores, le quitan tres puntos de su historial de manejo.","p":"Correcto. Le quitan tres puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-070","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, your license is suspended for points for the second time. How long may it be taken?","o":["60 days","6 months","2 years","For life"],"h1":"The first suspension is 60 days; each later one is longer.","h2":"In North Carolina, a second suspension under the point system may last 6 months.","p":"Right. A second point suspension may last 6 months."},"es":{"q":"En Carolina del Norte, le suspenden la licencia por puntos por segunda vez. ¿Por cuánto tiempo se la pueden quitar?","o":["60 días","6 meses","2 años","De por vida"],"h1":"La primera suspensión es de 60 días; cada una después es más larga.","h2":"En Carolina del Norte, una segunda suspensión por el sistema de puntos puede durar 6 meses.","p":"Correcto. Una segunda suspensión por puntos puede durar 6 meses."},"ref":{"doc":"NC","page":34}},{"id":"nc-071","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, how many driver license points do you get for following too closely?","o":["1 point","2 points","4 points","8 points"],"h1":"Following too closely is treated as more serious than running a stop sign.","h2":"In North Carolina, a conviction for following too closely puts 4 points on your driver license.","p":"Right. Following too closely is 4 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos recibe en su licencia por seguir demasiado cerca a otro vehículo?","o":["1 punto","2 puntos","4 puntos","8 puntos"],"h1":"Seguir demasiado cerca se considera más grave que pasarse una señal de alto.","h2":"En Carolina del Norte, una condena por seguir demasiado cerca pone 4 puntos en su licencia.","p":"Correcto. Seguir demasiado cerca son 4 puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-072","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how many driver license points do you get for running a red light?","o":["1 point","5 points","8 points","3 points"],"h1":"It is the same as running through a stop sign.","h2":"In North Carolina, a conviction for running a red light puts 3 points on your driver license.","p":"Right. Running a red light is 3 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos recibe en su licencia por pasarse una luz roja?","o":["1 punto","5 puntos","8 puntos","3 puntos"],"h1":"Es lo mismo que por pasarse una señal de alto.","h2":"En Carolina del Norte, una condena por pasarse una luz roja pone 3 puntos en su licencia.","p":"Correcto. Pasarse una luz roja son 3 puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-073","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you are convicted of illegal parking. How many driver license points do you get?","o":["None","1 point","2 points","3 points"],"h1":"Parking is not a moving violation.","h2":"In North Carolina, no driver license points are given for an illegal parking conviction.","p":"Right. Illegal parking brings no points."},"es":{"q":"En Carolina del Norte, lo condenan por estacionarse de forma ilegal. ¿Cuántos puntos recibe en su licencia?","o":["Ninguno","1 punto","2 puntos","3 puntos"],"h1":"Estacionarse no es una infracción en movimiento.","h2":"En Carolina del Norte, no se dan puntos en la licencia por una condena de estacionamiento ilegal.","p":"Correcto. Estacionarse mal no da puntos."},"ref":{"doc":"NC","page":36}},{"id":"nc-074","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, you are convicted of driving 72 mph where the limit is 55 mph. What happens to your license?","o":["Nothing; you only pay a fine","It is revoked for at least 30 days","It is revoked permanently","It is suspended for one day"],"h1":"Going more than 15 mph over the limit, at a speed above 55 mph, costs you your license for a while.","h2":"In North Carolina, driving more than 15 mph over the limit at a speed above 55 mph leads to a license revocation of at least 30 days.","p":"Right. It is revoked for at least 30 days."},"es":{"q":"En Carolina del Norte, lo condenan por manejar a 72 mph donde el límite es 55 mph. ¿Qué pasa con su licencia?","o":["Nada; solo paga una multa","Se revoca por al menos 30 días","Se revoca de forma permanente","Se suspende por un día"],"h1":"Ir a más de 15 mph sobre el límite, a una velocidad mayor de 55 mph, le cuesta la licencia por un tiempo.","h2":"En Carolina del Norte, manejar a más de 15 mph sobre el límite, a una velocidad mayor de 55 mph, lleva a revocar la licencia por al menos 30 días.","p":"Correcto. Se revoca por al menos 30 días."},"ref":{"doc":"NC","page":36}},{"id":"nc-075","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, a driver is in a crash and does not stop to give aid. How long is the license suspended?","o":["30 days","90 days","1 year","5 years"],"h1":"It is the same time as for death by vehicle.","h2":"In North Carolina, failing to stop and give aid after a crash you are involved in means a one-year license suspension.","p":"Right. One year."},"es":{"q":"En Carolina del Norte, un conductor tiene un choque y no se detiene a dar ayuda. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","90 días","1 año","5 años"],"h1":"Es el mismo tiempo que por causar una muerte con un vehículo.","h2":"En Carolina del Norte, no detenerse a dar ayuda después de un choque en el que usted participa significa una suspensión de la licencia por un año.","p":"Correcto. Un año."},"ref":{"doc":"NC","page":37}},{"id":"nc-076","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, an officer finds a driver racing another car in a planned race on the highway. What happens to the car?","o":["Nothing happens to the car","It gets a parking ticket","It must pass a new inspection","The officer seizes it, and the court may order it sold if the driver is convicted"],"h1":"The law can take away the car itself, not only the license.","h2":"In North Carolina, a car used in prearranged racing is seized by the officer, and if the driver is convicted the court may order it sold at public auction.","p":"Right. The car is seized and may be sold."},"es":{"q":"En Carolina del Norte, un agente encuentra a un conductor en una carrera planeada contra otro auto en la carretera. ¿Qué pasa con el auto?","o":["No le pasa nada al auto","Recibe una multa de estacionamiento","Debe pasar una nueva inspección","El agente lo confisca, y el tribunal puede ordenar venderlo si condenan al conductor"],"h1":"La ley puede quitarle el auto mismo, no solo la licencia.","h2":"En Carolina del Norte, el agente confisca el auto usado en una carrera planeada, y si condenan al conductor el tribunal puede ordenar venderlo en subasta pública.","p":"Correcto. El auto se confisca y puede venderse."},"ref":{"doc":"NC","page":37}},{"id":"nc-077","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a driver under 18 is convicted of a third moving violation within 12 months. How long may the license be suspended?","o":["90 days","30 days","1 year","For life"],"h1":"A second violation is 30 days, and a fourth is six months. The third is in between.","h2":"In North Carolina, a provisional licensee convicted of a third moving violation within 12 months may have the license suspended for 90 days.","p":"Right. 90 days."},"es":{"q":"En Carolina del Norte, un conductor menor de 18 años es condenado por una tercera infracción en movimiento en 12 meses. ¿Por cuánto tiempo le pueden suspender la licencia?","o":["90 días","30 días","1 año","De por vida"],"h1":"Una segunda infracción son 30 días, y una cuarta son seis meses. La tercera está en medio.","h2":"En Carolina del Norte, a un conductor provisional condenado por una tercera infracción en movimiento en 12 meses le pueden suspender la licencia por 90 días.","p":"Correcto. 90 días."},"ref":{"doc":"NC","page":39}},{"id":"nc-078","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, you are driving a long distance. How often should you get out of the car to stretch and walk?","o":["Every 30 minutes","At least every 2 hours","Every 6 hours","Only when you need gas"],"h1":"Think of a stop about every couple of hours.","h2":"In North Carolina, the handbook says to get out of the car at least every 2 hours on long trips to stretch and walk.","p":"Right. Stop at least every 2 hours."},"es":{"q":"En Carolina del Norte, usted maneja una distancia larga. ¿Cada cuánto debe bajarse del auto para estirarse y caminar?","o":["Cada 30 minutos","Al menos cada 2 horas","Cada 6 horas","Solo cuando necesite gasolina"],"h1":"Piense en una parada más o menos cada par de horas.","h2":"En Carolina del Norte, el manual dice que en viajes largos se baje del auto al menos cada 2 horas para estirarse y caminar.","p":"Correcto. Pare al menos cada 2 horas."},"ref":{"doc":"NC","page":40}},{"id":"nc-079","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, who must wear a motorcycle safety helmet?","o":["Only riders under 21","Only riders under 18","Every rider and passenger on a motorcycle or moped","Only riders on interstates"],"h1":"North Carolina does not make an exception for age.","h2":"In North Carolina, all operators and passengers on motorcycles and mopeds must wear an approved motorcycle safety helmet.","p":"Right. Everyone on a motorcycle or moped wears a helmet."},"es":{"q":"En Carolina del Norte, ¿quién debe usar casco de seguridad para motocicleta?","o":["Solo quienes tienen menos de 21 años","Solo quienes tienen menos de 18 años","Todo conductor y pasajero de motocicleta o ciclomotor","Solo quienes van por la autopista interestatal"],"h1":"Carolina del Norte no hace excepción por edad.","h2":"En Carolina del Norte, todos los conductores y pasajeros de motocicletas y ciclomotores deben usar un casco de seguridad aprobado.","p":"Correcto. Todos en motocicleta o ciclomotor usan casco."},"ref":{"doc":"NC","page":45}},{"id":"nc-080","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, children under 16 may not ride in the open bed of a pickup truck. Which is one exception?","o":["The truck goes under 25 mph","The tailgate is closed","A parent is driving","An adult rides in the bed and watches the child"],"h1":"The exception puts a grown-up right next to the child.","h2":"In North Carolina, a child under 16 may ride in an open truck bed when an adult is also in the bed supervising the child.","p":"Right. An adult in the bed supervising the child is an exception."},"es":{"q":"En Carolina del Norte, los niños menores de 16 años no pueden ir en la caja abierta de una camioneta pickup. ¿Cuál es una excepción?","o":["La camioneta va a menos de 25 mph","La compuerta trasera está cerrada","Uno de los padres maneja","Un adulto va en la caja y vigila al niño"],"h1":"La excepción pone a un adulto justo al lado del niño.","h2":"En Carolina del Norte, un niño menor de 16 años puede ir en la caja abierta cuando un adulto también va en la caja vigilándolo.","p":"Correcto. Un adulto en la caja que vigila al niño es una excepción."},"ref":{"doc":"NC","page":46}},{"id":"nc-081","scope":"NC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Carolina, you turn right on red and do not yield to a person starting to cross in front of you. What penalty can you get?","o":["A fine of $100 to $500","A fine of $10 to $25","Only a warning","A fine of $5,000"],"h1":"The law sets a minimum of $100.","h2":"In North Carolina, failing to yield to a pedestrian when turning right on red carries a penalty of at least $100 and up to $500.","p":"Right. $100 to $500."},"es":{"q":"En Carolina del Norte, usted gira a la derecha con luz roja y no cede el paso a una persona que empieza a cruzar frente a usted. ¿Qué sanción puede recibir?","o":["Una multa de $100 a $500","Una multa de $10 a $25","Solo una advertencia","Una multa de $5,000"],"h1":"La ley fija un mínimo de $100.","h2":"En Carolina del Norte, no ceder el paso a un peatón al girar a la derecha con luz roja tiene una sanción de al menos $100 y hasta $500.","p":"Correcto. De $100 a $500."},"ref":{"doc":"NC","page":80}},{"id":"nc-082","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, you stopped for a school bus that is letting children off. When may you go again?","o":["As soon as the children reach the sidewalk","When the stop arm is pulled back, the red lights stop, and the bus starts to move","After you wait 30 seconds","When the children are out of sight"],"h1":"Wait for three things the bus does.","h2":"In North Carolina, you must stay stopped until the bus pulls back its stop arm, turns off its flashing red lights and starts to move.","p":"Right. Wait until the arm is in, the lights are off and the bus moves."},"es":{"q":"En Carolina del Norte, usted se detuvo por un autobús escolar que deja bajar a niños. ¿Cuándo puede seguir?","o":["En cuanto los niños lleguen a la acera","Cuando el brazo de alto se retira, las luces rojas se apagan y el autobús empieza a moverse","Después de esperar 30 segundos","Cuando ya no vea a los niños"],"h1":"Espere tres cosas que hace el autobús.","h2":"En Carolina del Norte, debe seguir detenido hasta que el autobús retire el brazo de alto, apague las luces rojas intermitentes y empiece a moverse.","p":"Correcto. Espere a que retire el brazo, apague las luces y se mueva."},"ref":{"doc":"NC","page":47}},{"id":"nc-083","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, a fire truck is on its way to a fire alarm. How close to it may you drive or park?","o":["25 feet","50 feet","No closer than one block","As close as you like"],"h1":"Think of a distance measured in city blocks, not feet.","h2":"In North Carolina, you may not drive or park closer than one block to a fire truck answering a fire alarm.","p":"Right. Stay at least one block away."},"es":{"q":"En Carolina del Norte, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca de él puede manejar o estacionarse?","o":["25 pies","50 pies","No más cerca de una cuadra","Tan cerca como quiera"],"h1":"Piense en una distancia que se mide en cuadras, no en pies.","h2":"En Carolina del Norte, no puede manejar ni estacionarse a menos de una cuadra de un camión de bomberos que va a una alarma de incendio.","p":"Correcto. Manténgase al menos a una cuadra."},"ref":{"doc":"NC","page":48}},{"id":"nc-084","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, you drive on a four-lane, limited-access highway with a center median. An ambulance with its siren on comes toward you on the other side. What must you do?","o":["Stop in your lane","Pull over to the right and stop","Speed up to clear the way","Keep driving with care; you do not have to yield on this kind of highway"],"h1":"The median keeps the two directions apart on this road.","h2":"In North Carolina, drivers going the opposite way from an emergency vehicle on a four-lane limited-access highway with a center median do not have to yield to it.","p":"Right. On a divided limited-access highway, the other direction does not have to pull over."},"es":{"q":"En Carolina del Norte, usted maneja por una autopista de acceso limitado de cuatro carriles con mediana central. Una ambulancia con sirena viene hacia usted por el otro lado. ¿Qué debe hacer?","o":["Detenerse en su carril","Orillarse a la derecha y detenerse","Acelerar para abrir paso","Seguir con cuidado; no tiene que ceder el paso en este tipo de autopista"],"h1":"En esta vía, la mediana separa las dos direcciones.","h2":"En Carolina del Norte, quienes van en sentido contrario a un vehículo de emergencia en una autopista de acceso limitado de cuatro carriles con mediana central no tienen que cederle el paso.","p":"Correcto. En una autopista dividida de acceso limitado, el otro sentido no tiene que orillarse."},"ref":{"doc":"NC","page":48}},{"id":"nc-085","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, a police car with flashing lights is behind you, but there is no safe place to stop yet. What should you do?","o":["Turn on your hazard flashers, slow down about 10 mph, and drive on to a safe place","Stop right away in your lane","Speed up to find a place faster","Ignore it until you get home"],"h1":"Show the officer you have seen them, then keep going to a safe spot.","h2":"In North Carolina, if there is no safe place to stop, turn on your four-way flashers, slow down by about 10 mph, and keep driving lawfully to the nearest safe place.","p":"Right. Flashers on, slow down about 10 mph, and go to a safe place."},"es":{"q":"En Carolina del Norte, un auto de policía con luces intermitentes va detrás de usted, pero todavía no hay un lugar seguro para parar. ¿Qué debe hacer?","o":["Encender las luces de emergencia, bajar unas 10 mph y seguir hasta un lugar seguro","Detenerse en el acto en su carril","Acelerar para encontrar un lugar más rápido","No hacer caso hasta llegar a casa"],"h1":"Muéstrele al agente que lo vio, y luego siga hasta un lugar seguro.","h2":"En Carolina del Norte, si no hay un lugar seguro para parar, encienda las luces de emergencia, baje la velocidad unas 10 mph y siga manejando según la ley hasta el lugar seguro más cercano.","p":"Correcto. Luces de emergencia, bajar unas 10 mph e ir a un lugar seguro."},"ref":{"doc":"NC","page":49}},{"id":"nc-086","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, an unmarked car signals you to pull over, and you are not sure it is really the police. What may you do?","o":["Drive away fast","Call 911 before you pull over, to check","Get out and walk to the car","Never stop for an unmarked car"],"h1":"You can ask for help with a phone call.","h2":"In North Carolina, if you truly doubt that an unmarked car is a real officer, you may call 911 before pulling over and give your name and location to check.","p":"Right. You may call 911 to check."},"es":{"q":"En Carolina del Norte, un auto sin marcas le indica que se orille, y usted no está seguro de que sea la policía. ¿Qué puede hacer?","o":["Huir rápido","Llamar al 911 antes de orillarse, para confirmar","Bajarse y caminar hasta el auto","Nunca detenerse por un auto sin marcas"],"h1":"Puede pedir ayuda con una llamada.","h2":"En Carolina del Norte, si de verdad duda que un auto sin marcas sea de un agente, puede llamar al 911 antes de orillarse y dar su nombre y ubicación para confirmar.","p":"Correcto. Puede llamar al 911 para confirmar."},"ref":{"doc":"NC","page":49}},{"id":"nc-087","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, farm equipment may legally travel on most roads. Where is it not allowed?","o":["On two-lane roads","In towns","On interstates","On roads with a speed limit over 35 mph"],"h1":"Think of the fastest highways.","h2":"In North Carolina, farm equipment may travel on most roads, but not on interstates.","p":"Right. Farm equipment is not allowed on interstates."},"es":{"q":"En Carolina del Norte, la maquinaria agrícola puede circular por la mayoría de las vías. ¿Dónde no está permitida?","o":["En vías de dos carriles","En los pueblos","En las autopistas interestatales","En vías con límite de más de 35 mph"],"h1":"Piense en las autopistas más rápidas.","h2":"En Carolina del Norte, la maquinaria agrícola puede circular por la mayoría de las vías, pero no por las autopistas interestatales.","p":"Correcto. La maquinaria agrícola no puede ir por las interestatales."},"ref":{"doc":"NC","page":52}},{"id":"nc-088","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, which lights must every vehicle in a funeral procession have on?","o":["Only parking lights","High beams","No lights in daytime","Headlights, plus hazard flashers if the vehicle has them"],"h1":"Two kinds of lights help others see the procession.","h2":"In North Carolina, every vehicle in a funeral procession must have its headlights on, and its hazard warning lights too if it has them.","p":"Right. Headlights on, plus hazard flashers."},"es":{"q":"En Carolina del Norte, ¿qué luces debe llevar encendidas cada vehículo de un cortejo fúnebre?","o":["Solo las luces de estacionamiento","Las luces altas","Ninguna luz de día","Los faros, y también las luces de emergencia si el vehículo las tiene"],"h1":"Dos tipos de luces ayudan a que otros vean el cortejo.","h2":"En Carolina del Norte, cada vehículo de un cortejo fúnebre debe llevar los faros encendidos, y también las luces de emergencia si las tiene.","p":"Correcto. Faros encendidos, y también luces de emergencia."},"ref":{"doc":"NC","page":52}},{"id":"nc-089","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, in ideal conditions, about how far does a car going 55 mph need to stop completely?","o":["About 211 feet","About 50 feet","About 100 feet","About 1,000 feet"],"h1":"It is more than two-thirds the length of a football field.","h2":"In North Carolina, the handbook says a car going 55 mph needs about 211 feet to stop completely, even in ideal conditions.","p":"Right. About 211 feet."},"es":{"q":"En Carolina del Norte, en condiciones ideales, ¿más o menos qué distancia necesita un auto a 55 mph para detenerse por completo?","o":["Unos 211 pies","Unos 50 pies","Unos 100 pies","Unos 1,000 pies"],"h1":"Es más de dos tercios del largo de un campo de fútbol americano.","h2":"En Carolina del Norte, el manual dice que un auto a 55 mph necesita unos 211 pies para detenerse por completo, aun en condiciones ideales.","p":"Correcto. Unos 211 pies."},"ref":{"doc":"NC","page":53}},{"id":"nc-090","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, what is the highest speed limit on interstates?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 15 mph more than the limit outside towns.","h2":"In North Carolina, the maximum speed limit on interstates is 70 mph.","p":"Right. 70 mph on interstates."},"es":{"q":"En Carolina del Norte, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Son 15 mph más que el límite fuera de los pueblos.","h2":"En Carolina del Norte, el límite máximo de velocidad en las autopistas interestatales es 70 mph.","p":"Correcto. 70 mph en las interestatales."},"ref":{"doc":"NC","page":53}},{"id":"nc-091","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, a driver behind you honks to pass you. What must you do?","o":["Speed up so they do not need to pass","Brake hard","Move to the right side of the road and do not speed up","Move to the left to block them"],"h1":"The law says you must help the other driver pass.","h2":"In North Carolina, when a passing driver honks, you must move to the right side of the road and never speed up.","p":"Right. Move right and do not speed up."},"es":{"q":"En Carolina del Norte, un conductor detrás de usted toca la bocina para rebasarlo. ¿Qué debe hacer?","o":["Acelerar para que no tenga que rebasar","Frenar fuerte","Moverse al lado derecho de la vía y no acelerar","Moverse a la izquierda para bloquearlo"],"h1":"La ley dice que debe ayudar al otro conductor a rebasar.","h2":"En Carolina del Norte, cuando un conductor toca la bocina para rebasar, usted debe moverse al lado derecho de la vía y nunca acelerar.","p":"Correcto. Muévase a la derecha y no acelere."},"ref":{"doc":"NC","page":55}},{"id":"nc-092","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, you are on a highway with three lanes. Where may you pass?","o":["In any lane, any time","Only in the right lane","Only on the shoulder","Only in the center lane, where it is marked for passing in your direction"],"h1":"The middle lane is shared, so markings decide who may use it.","h2":"In North Carolina, on a three-lane highway you may pass only in the center lane, and only where it is marked for passing in your direction.","p":"Right. Pass only in the center lane where it is marked for your direction."},"es":{"q":"En Carolina del Norte, usted va por una carretera de tres carriles. ¿Dónde puede rebasar?","o":["En cualquier carril, en cualquier momento","Solo en el carril derecho","Solo por el acotamiento","Solo en el carril central, donde está marcado para rebasar en su dirección"],"h1":"El carril del medio se comparte, así que las marcas deciden quién puede usarlo.","h2":"En Carolina del Norte, en una carretera de tres carriles solo puede rebasar en el carril central, y solo donde está marcado para rebasar en su dirección.","p":"Correcto. Rebase solo en el carril central donde está marcado para su dirección."},"ref":{"doc":"NC","page":55}},{"id":"nc-093","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, what is the fastest you should go when backing up?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"A car is harder to control in reverse, so go very slowly.","h2":"In North Carolina, you should back up very slowly, never faster than 10 mph.","p":"Right. No more than 10 mph when backing."},"es":{"q":"En Carolina del Norte, ¿qué es lo más rápido que debe ir al dar marcha atrás?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Un auto es más difícil de controlar en reversa, así que vaya muy despacio.","h2":"En Carolina del Norte, debe dar marcha atrás muy despacio, nunca a más de 10 mph.","p":"Correcto. No más de 10 mph en reversa."},"ref":{"doc":"NC","page":56}},{"id":"nc-094","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, the signals at a railroad crossing show that a train is coming. Where must you stop?","o":["Right on the tracks","Within 50 feet but no closer than 15 feet from the nearest rail","At least 100 feet from the tracks","Anywhere, as long as you can see the train"],"h1":"There is a nearest and a farthest distance.","h2":"In North Carolina, when you must stop for a train, stop within 50 feet but not less than 15 feet from the nearest rail.","p":"Right. Between 15 and 50 feet from the nearest rail."},"es":{"q":"En Carolina del Norte, las señales de un cruce de tren indican que viene un tren. ¿Dónde debe detenerse?","o":["Encima de las vías","A no más de 50 pies, pero no a menos de 15 pies del riel más cercano","Al menos a 100 pies de las vías","En cualquier lugar, si puede ver el tren"],"h1":"Hay una distancia mínima y una máxima.","h2":"En Carolina del Norte, cuando debe detenerse por un tren, hágalo a no más de 50 pies pero no a menos de 15 pies del riel más cercano.","p":"Correcto. Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"NC","page":60}},{"id":"nc-095","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, you are crossing railroad tracks when the gate on the far side comes down in front of you. What should you do?","o":["Stop on the tracks and wait","Back up off the tracks","Keep moving and drive through the gate; it is flexible","Get out and lift the gate"],"h1":"The handbook says the gate cannot trap you.","h2":"In North Carolina, if the far gate comes down while you are crossing, keep moving and drive through it; the gate is flexible and will not trap you.","p":"Right. Keep moving and drive through the gate."},"es":{"q":"En Carolina del Norte, usted está cruzando las vías del tren cuando la barrera del otro lado baja frente a usted. ¿Qué debe hacer?","o":["Detenerse sobre las vías y esperar","Retroceder para salir de las vías","Seguir avanzando y pasar a través de la barrera; es flexible","Bajarse y levantar la barrera"],"h1":"El manual dice que la barrera no lo puede atrapar.","h2":"En Carolina del Norte, si la barrera del otro lado baja mientras usted cruza, siga avanzando y pase a través de ella; la barrera es flexible y no lo atrapará.","p":"Correcto. Siga avanzando y pase a través de la barrera."},"ref":{"doc":"NC","page":62}},{"id":"nc-096","scope":"NC","cat":"signals","sign":null,"c":3,"en":{"q":"In North Carolina, you come to an intersection where the traffic light is not working because of a power outage. What should you do?","o":["Drive through without slowing","Give way only to cars on your left","Honk and go first","Treat it like an all-way stop"],"h1":"Act as if every direction has a stop sign.","h2":"In North Carolina, at a traffic light that is not working, proceed as if the intersection had a stop sign on every approach, unless an officer is directing traffic.","p":"Right. Treat it like an all-way stop."},"es":{"q":"En Carolina del Norte, llega a una intersección donde el semáforo no funciona por un apagón. ¿Qué debe hacer?","o":["Pasar sin bajar la velocidad","Ceder el paso solo a los autos de su izquierda","Tocar la bocina y pasar primero","Tratarla como un alto en todas las direcciones"],"h1":"Actúe como si cada dirección tuviera una señal de alto.","h2":"En Carolina del Norte, ante un semáforo que no funciona, avance como si la intersección tuviera una señal de alto en cada entrada, salvo que un agente dirija el tránsito.","p":"Correcto. Trátela como un alto en todas las direcciones."},"ref":{"doc":"NC","page":81}},{"id":"nc-097","scope":"NC","cat":"signals","sign":null,"c":0,"en":{"q":"In North Carolina, the ramp meter signal on a freeway on-ramp is dark (no red or green light). What should you do?","o":["Go ahead without stopping and merge as usual","Stop and wait until it turns green","Back up and use another ramp","Stop and honk"],"h1":"A dark ramp meter is not controlling traffic.","h2":"In North Carolina, when a ramp meter is dark, you may go ahead without stopping and merge onto the freeway as normal traffic allows.","p":"Right. Go ahead and merge as usual."},"es":{"q":"En Carolina del Norte, el semáforo de control de una rampa de entrada a la autopista está apagado (sin luz roja ni verde). ¿Qué debe hacer?","o":["Seguir sin detenerse e incorporarse como siempre","Detenerse y esperar la luz verde","Retroceder y usar otra rampa","Detenerse y tocar la bocina"],"h1":"Un semáforo de rampa apagado no está controlando el tránsito.","h2":"En Carolina del Norte, cuando el semáforo de la rampa está apagado, puede seguir sin detenerse e incorporarse a la autopista como lo permita el tránsito.","p":"Correcto. Siga e incorpórese como siempre."},"ref":{"doc":"NC","page":82}},{"id":"nc-098","scope":"NC","cat":"signals","sign":null,"c":1,"en":{"q":"In North Carolina, what shape are the route markers for North Carolina (state) highways?","o":["A shield","A diamond","A circle","A triangle"],"h1":"U.S. routes use a shield. The state uses a different shape.","h2":"In North Carolina, state highway route markers are diamond-shaped.","p":"Right. North Carolina route markers are diamonds."},"es":{"q":"En Carolina del Norte, ¿qué forma tienen las señales de ruta de las carreteras estatales de Carolina del Norte?","o":["Un escudo","Un rombo","Un círculo","Un triángulo"],"h1":"Las rutas federales (U.S.) usan un escudo. El estado usa otra forma.","h2":"En Carolina del Norte, las señales de ruta de las carreteras estatales tienen forma de rombo.","p":"Correcto. Las señales de ruta de Carolina del Norte son rombos."},"ref":{"doc":"NC","page":85}},{"id":"nc-099","scope":"NC","cat":"signals","sign":null,"c":2,"en":{"q":"In North Carolina, you see blue reflective markers on the road. What do they often show?","o":["A bike lane","A wrong-way warning","Where fire hydrants or water supplies are nearby","A school zone"],"h1":"They help firefighters.","h2":"In North Carolina, blue reflective pavement markers can show where fire hydrants or water supplies for firefighters are nearby.","p":"Right. They mark nearby fire hydrants or water supplies."},"es":{"q":"En Carolina del Norte, usted ve marcadores reflectantes azules en la vía. ¿Qué suelen indicar?","o":["Un carril para bicicletas","Un aviso de sentido contrario","Dónde hay hidrantes o fuentes de agua cerca","Una zona escolar"],"h1":"Ayudan a los bomberos.","h2":"En Carolina del Norte, los marcadores reflectantes azules en la vía pueden indicar dónde hay hidrantes o fuentes de agua para los bomberos cerca.","p":"Correcto. Marcan hidrantes o fuentes de agua cercanas."},"ref":{"doc":"NC","page":88}},{"id":"nc-100","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, how far behind a tractor-trailer can its blind spot (No-Zone) reach?","o":["About 5 feet","About 20 feet","About 50 feet","Up to 200 feet"],"h1":"The space behind is much longer than the space in front.","h2":"In North Carolina, a tractor-trailer's No-Zone can reach up to 200 feet behind it, and up to 20 feet in front of the cab.","p":"Right. Up to 200 feet behind."},"es":{"q":"En Carolina del Norte, ¿hasta qué distancia detrás de un tractocamión puede llegar su punto ciego (No-Zone)?","o":["Unos 5 pies","Unos 20 pies","Unos 50 pies","Hasta 200 pies"],"h1":"El espacio de atrás es mucho más largo que el de adelante.","h2":"En Carolina del Norte, el punto ciego (No-Zone) de un tractocamión puede llegar hasta 200 pies detrás de él, y hasta 20 pies delante de la cabina.","p":"Correcto. Hasta 200 pies atrás."},"ref":{"doc":"NC","page":92}},{"id":"nc-101","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you do not have a valid driver license. Which of these is also against the law?","o":["Riding as a passenger in the back seat","Sitting in the driver's seat while the engine is running","Sitting in a parked car with the engine off","Holding a learner permit test appointment"],"h1":"Think about being in control of a car that is ready to move.","h2":"In North Carolina, without a valid license it is illegal even to sit in the driver's seat while the engine is running.","p":"Right. No license means no sitting behind the wheel with the engine on."},"es":{"q":"En Carolina del Norte, usted no tiene una licencia de manejar válida. ¿Cuál de estas cosas también va contra la ley?","o":["Ir como pasajero en el asiento de atrás","Sentarse en el asiento del conductor con el motor encendido","Sentarse en un carro estacionado con el motor apagado","Tener una cita para el examen del permiso"],"h1":"Piense en estar al control de un carro que está listo para moverse.","h2":"En Carolina del Norte, sin una licencia válida es ilegal incluso sentarse en el asiento del conductor con el motor encendido.","p":"Correcto. Sin licencia, no se siente al volante con el motor encendido."},"ref":{"doc":"NC","page":8}},{"id":"nc-102","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you are 17 and want a motorcycle learner permit. Which course must you finish first?","o":["A first aid course","A defensive driving course for cars","A Basic Rider Course for motorcycles","No course is needed"],"h1":"Riders under 18 need special motorcycle training.","h2":"In North Carolina, a motorcycle learner permit applicant under 18 must finish a Basic Rider Course (Motorcycle Safety Foundation or the North Carolina program).","p":"Right. Riders under 18 must finish a Basic Rider Course."},"es":{"q":"En Carolina del Norte, usted tiene 17 años y quiere un permiso de aprendizaje para motocicleta. ¿Qué curso debe terminar primero?","o":["Un curso de primeros auxilios","Un curso de manejo defensivo para carros","Un curso básico para motociclistas (Basic Rider Course)","No se necesita ningún curso"],"h1":"Los menores de 18 años necesitan entrenamiento especial de motocicleta.","h2":"En Carolina del Norte, quien pide un permiso de aprendizaje para motocicleta y tiene menos de 18 años debe terminar un curso básico para motociclistas (Basic Rider Course).","p":"Correcto. Los menores de 18 años deben terminar un Basic Rider Course."},"ref":{"doc":"NC","page":8}},{"id":"nc-103","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, you must show proof of liability insurance to get your first license here. Which proof is NOT accepted?","o":["Form DL-123 from your insurance agent","An insurance binder","An insurance card with your name and policy number","A picture of your insurance card on your phone"],"h1":"The DMV wants proof on paper.","h2":"In North Carolina, proof of insurance for a driver license must be printed; an image on a phone or other mobile device is not accepted.","p":"Right. A picture on your phone is not accepted."},"es":{"q":"En Carolina del Norte, debe mostrar prueba de seguro de responsabilidad civil para obtener su primera licencia aquí. ¿Qué prueba NO se acepta?","o":["El formulario DL-123 de su agente de seguros","Una póliza provisional de seguro (binder)","Una tarjeta de seguro con su nombre y número de póliza","Una foto de su tarjeta de seguro en su teléfono"],"h1":"El DMV quiere la prueba en papel.","h2":"En Carolina del Norte, la prueba de seguro para la licencia debe estar impresa; una imagen en el teléfono u otro aparato móvil no se acepta.","p":"Correcto. Una foto en su teléfono no se acepta."},"ref":{"doc":"NC","page":23}},{"id":"nc-104","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a driver license is printed up and down (vertical) instead of sideways. What does that show?","o":["The driver was under 21 when it was issued","The driver has a commercial license","The driver is a veteran","The license is a REAL ID"],"h1":"The DMV uses this shape as an extra check on age.","h2":"In North Carolina, the DMV gives a vertical license or ID card to people under 21.","p":"Right. A vertical card is for someone under 21."},"es":{"q":"En Carolina del Norte, una licencia está impresa en vertical en vez de horizontal. ¿Qué indica?","o":["Que el conductor tenía menos de 21 años cuando se la dieron","Que el conductor tiene licencia comercial","Que el conductor es veterano","Que la licencia es REAL ID"],"h1":"El DMV usa esta forma como un control extra de la edad.","h2":"En Carolina del Norte, el DMV da una licencia o identificación vertical a las personas menores de 21 años.","p":"Correcto. Una tarjeta vertical es para alguien menor de 21 años."},"ref":{"doc":"NC","page":26}},{"id":"nc-105","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, a driver's blood alcohol level is 0.06, under 0.08. Can the driver still be convicted of DWI?","o":["No, never below 0.08","Only if it is a second offense","Yes, if alcohol or drugs clearly impaired the driver's mind or body","Only if the driver is over 21"],"h1":"There are two ways to prove impaired driving, not just one number.","h2":"In North Carolina, DWI can be proven by a level of 0.08 or more, or by showing that the driver's physical or mental abilities were clearly impaired.","p":"Right. Clear impairment is DWI, even under 0.08."},"es":{"q":"En Carolina del Norte, el nivel de alcohol en la sangre de un conductor es 0.06, menos de 0.08. ¿Todavía pueden condenarlo por DWI (manejar bajo la influencia)?","o":["No, nunca por debajo de 0.08","Solo si es la segunda vez","Sí, si el alcohol o las drogas afectaron claramente su mente o su cuerpo","Solo si el conductor tiene más de 21 años"],"h1":"Hay dos maneras de probar que alguien maneja afectado, no solo un número.","h2":"En Carolina del Norte, el DWI se puede probar con un nivel de 0.08 o más, o mostrando que las capacidades físicas o mentales del conductor estaban claramente afectadas.","p":"Correcto. Estar claramente afectado es DWI, aun con menos de 0.08."},"ref":{"doc":"NC","page":31}},{"id":"nc-106","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, may you carry an opened bottle of wine in the passenger area of your car?","o":["Yes, if the driver does not drink from it","No, an open container of alcohol may not be carried there","Yes, if a passenger is over 21","Yes, on roads outside cities"],"h1":"Think about where an opened bottle may be.","h2":"In North Carolina, the law forbids carrying an open container of any alcoholic drink in the passenger area of the car.","p":"Right. No open alcohol in the passenger area."},"es":{"q":"En Carolina del Norte, ¿puede llevar una botella de vino abierta en el área de pasajeros de su carro?","o":["Sí, si el conductor no toma de ella","No, no se puede llevar ahí un envase abierto de alcohol","Sí, si un pasajero tiene más de 21 años","Sí, en carreteras fuera de las ciudades"],"h1":"Piense en dónde puede estar una botella abierta.","h2":"En Carolina del Norte, la ley prohíbe llevar un envase abierto de cualquier bebida alcohólica en el área de pasajeros del carro.","p":"Correcto. Nada de alcohol abierto en el área de pasajeros."},"ref":{"doc":"NC","page":31}},{"id":"nc-107","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, when is a fourth DWI conviction a felony?","o":["Always, no matter when the others happened","Only if someone was hurt","Only if the driver refused a breath test","When the three earlier DWI convictions were all within the past seven years"],"h1":"It depends on how recent the earlier convictions were.","h2":"In North Carolina, a fourth DWI conviction is a felony when the three earlier DWI convictions happened within the past seven years.","p":"Right. Three earlier DWIs within seven years make the fourth a felony."},"es":{"q":"En Carolina del Norte, ¿cuándo es un delito grave (felony) una cuarta condena por DWI?","o":["Siempre, sin importar cuándo fueron las otras","Solo si alguien resultó herido","Solo si el conductor se negó a la prueba de aliento","Cuando las tres condenas anteriores por DWI fueron en los últimos siete años"],"h1":"Depende de qué tan recientes fueron las condenas anteriores.","h2":"En Carolina del Norte, una cuarta condena por DWI es un delito grave cuando las tres condenas anteriores fueron en los últimos siete años.","p":"Correcto. Tres DWI anteriores en siete años hacen que el cuarto sea un delito grave."},"ref":{"doc":"NC","page":32}},{"id":"nc-108","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, a 19-year-old is convicted of trying to buy beer. What happens to the driver license?","o":["It is revoked for one year","Nothing, because the person was not driving","It is suspended for 30 days","The person gets 2 points"],"h1":"The penalty is the same as for other underage alcohol offenses.","h2":"In North Carolina, a person under 21 who is convicted of buying or trying to buy alcohol loses the driver license for one year.","p":"Right. Trying to buy alcohol under 21 costs one year of driving."},"es":{"q":"En Carolina del Norte, una persona de 19 años es condenada por intentar comprar cerveza. ¿Qué pasa con su licencia?","o":["Se revoca por un año","Nada, porque no estaba manejando","Se suspende por 30 días","Recibe 2 puntos"],"h1":"La sanción es la misma que en otros delitos de alcohol de menores.","h2":"En Carolina del Norte, una persona menor de 21 años condenada por comprar o intentar comprar alcohol pierde la licencia por un año.","p":"Correcto. Intentar comprar alcohol antes de los 21 cuesta un año sin manejar."},"ref":{"doc":"NC","page":33}},{"id":"nc-109","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, your license was suspended for points and then given back. How many new points within three years can lead to a second suspension?","o":["4 points","6 points","8 points","12 points"],"h1":"It is fewer than the 12 points that caused the first suspension.","h2":"In North Carolina, after your license is given back, 8 points within three years can lead to a second suspension.","p":"Right. 8 points within three years can mean a second suspension."},"es":{"q":"En Carolina del Norte, su licencia fue suspendida por puntos y luego se la devolvieron. ¿Cuántos puntos nuevos en tres años pueden causar una segunda suspensión?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Son menos que los 12 puntos que causaron la primera suspensión.","h2":"En Carolina del Norte, después de que le devuelven la licencia, 8 puntos en tres años pueden causar una segunda suspensión.","p":"Correcto. 8 puntos en tres años pueden causar una segunda suspensión."},"ref":{"doc":"NC","page":34}},{"id":"nc-110","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, your license was suspended for points, and now your driving privilege is given back. What happens to your old driver license points?","o":["They stay on your license for five more years","They are all canceled","They are cut in half","They turn into insurance points"],"h1":"You start fresh on your license record, but your insurance company keeps its own system.","h2":"In North Carolina, when your driving privilege is given back after a point suspension, all earlier driver license points are canceled; insurance points are not affected.","p":"Right. Your old license points are canceled."},"es":{"q":"En Carolina del Norte, su licencia fue suspendida por puntos y ahora le devuelven el privilegio de manejar. ¿Qué pasa con sus puntos anteriores de la licencia?","o":["Se quedan en su licencia cinco años más","Se cancelan todos","Se reducen a la mitad","Se convierten en puntos del seguro"],"h1":"Empieza de nuevo en su récord de licencia, pero la compañía de seguros tiene su propio sistema.","h2":"En Carolina del Norte, cuando le devuelven el privilegio de manejar después de una suspensión por puntos, se cancelan todos los puntos anteriores de la licencia; los puntos del seguro no cambian.","p":"Correcto. Sus puntos anteriores de la licencia se cancelan."},"ref":{"doc":"NC","page":34}},{"id":"nc-111","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how many driver license points do you get for aggressive driving?","o":["2 points","3 points","4 points","5 points"],"h1":"It is one of the highest point values, the same as passing a stopped school bus.","h2":"In North Carolina, a conviction for aggressive driving adds 5 points to your driver license.","p":"Right. Aggressive driving is 5 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por manejar de forma agresiva?","o":["2 puntos","3 puntos","4 puntos","5 puntos"],"h1":"Es uno de los valores más altos, igual que rebasar un autobús escolar detenido.","h2":"En Carolina del Norte, una condena por manejar de forma agresiva suma 5 puntos a su licencia.","p":"Correcto. Manejar de forma agresiva son 5 puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-112","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, within one year you are convicted a second time of going more than 15 mph over the limit at a speed above 55 mph. How long is your license taken?","o":["60 days","30 days","6 months","2 years"],"h1":"The first time is at least 30 days. The second time within a year is longer.","h2":"In North Carolina, a second conviction within one year for going more than 15 mph over the limit at over 55 mph means losing your license for 60 days.","p":"Right. The second time within a year is 60 days."},"es":{"q":"En Carolina del Norte, dentro de un año lo condenan por segunda vez por ir a más de 15 mph sobre el límite a una velocidad mayor de 55 mph. ¿Por cuánto tiempo le quitan la licencia?","o":["60 días","30 días","6 meses","2 años"],"h1":"La primera vez son al menos 30 días. La segunda vez en un año es más tiempo.","h2":"En Carolina del Norte, una segunda condena en un año por ir a más de 15 mph sobre el límite a más de 55 mph significa perder la licencia por 60 días.","p":"Correcto. La segunda vez en un año son 60 días."},"ref":{"doc":"NC","page":36}},{"id":"nc-113","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, a driver under 18 is convicted of a fourth moving violation within 12 months. How long may the license be suspended?","o":["30 days","90 days","6 months","2 years"],"h1":"Each new violation within the year brings a longer suspension.","h2":"In North Carolina, a provisional driver under 18 with a fourth moving violation within 12 months may lose the license for six months.","p":"Right. A fourth violation in 12 months can mean six months."},"es":{"q":"En Carolina del Norte, un conductor menor de 18 años es condenado por una cuarta infracción de tránsito en movimiento dentro de 12 meses. ¿Por cuánto tiempo pueden suspender su licencia?","o":["30 días","90 días","6 meses","2 años"],"h1":"Cada nueva infracción dentro del año trae una suspensión más larga.","h2":"En Carolina del Norte, un conductor provisional menor de 18 años con una cuarta infracción en movimiento dentro de 12 meses puede perder la licencia por seis meses.","p":"Correcto. Una cuarta infracción en 12 meses puede significar seis meses."},"ref":{"doc":"NC","page":39}},{"id":"nc-114","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, at least how much liability insurance must a car owner carry for property damage in one crash?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"The minimums went up in July 2025. It is the same as the minimum for injuries to one person.","h2":"In North Carolina, the minimum liability insurance for property damage in a crash is $50,000, raised from $25,000 for policies issued or renewed from July 1, 2025.","p":"Right. The minimum for property damage is $50,000."},"es":{"q":"En Carolina del Norte, ¿cuánto seguro de responsabilidad civil debe tener como mínimo el dueño de un carro para daños a la propiedad en un choque?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Los mínimos subieron en julio de 2025. Es lo mismo que el mínimo por lesiones a una persona.","h2":"En Carolina del Norte, el seguro mínimo de responsabilidad civil para daños a la propiedad en un choque es de $50,000; subió de $25,000 para las pólizas emitidas o renovadas desde el 1 de julio de 2025.","p":"Correcto. El mínimo para daños a la propiedad es $50,000."},"ref":{"doc":"NC","page":null}},{"id":"nc-115","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, your car insurance runs out, but your insurance company gives you a few extra days (a grace period) to pay. Does the state count those days as insured?","o":["Yes, for up to 30 days","Yes, but only on weekends","Yes, if you pay within 10 days","No, North Carolina does not honor a grace period"],"h1":"A grace period is only between you and your insurer.","h2":"In North Carolina, the state does not honor an insurance grace period; your car must have continuous liability insurance as long as it has a valid plate.","p":"Right. North Carolina does not honor a grace period."},"es":{"q":"En Carolina del Norte, su seguro de carro se vence, pero su compañía de seguros le da unos días extra (periodo de gracia) para pagar. ¿El estado cuenta esos días como asegurados?","o":["Sí, hasta 30 días","Sí, pero solo los fines de semana","Sí, si paga dentro de 10 días","No, Carolina del Norte no reconoce el periodo de gracia"],"h1":"El periodo de gracia es solo un acuerdo entre usted y su aseguradora.","h2":"En Carolina del Norte, el estado no reconoce el periodo de gracia del seguro; su carro debe tener seguro de responsabilidad civil sin interrupción mientras tenga una placa válida.","p":"Correcto. Carolina del Norte no reconoce el periodo de gracia."},"ref":{"doc":"NC","page":99}},{"id":"nc-116","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how early may you get your car's yearly inspection before the registration (license tag) expires?","o":["Up to 90 days before","Up to 1 year before","Only in the last week","Only after it expires"],"h1":"It is about three months.","h2":"In North Carolina, a vehicle inspection may be done up to 90 days before the registration expires.","p":"Right. Up to 90 days before the registration expires."},"es":{"q":"En Carolina del Norte, ¿con cuánta anticipación puede hacer la inspección anual de su carro antes de que venza el registro (placa)?","o":["Hasta 90 días antes","Hasta 1 año antes","Solo en la última semana","Solo después de que vence"],"h1":"Son unos tres meses.","h2":"En Carolina del Norte, la inspección del vehículo se puede hacer hasta 90 días antes de que venza el registro.","p":"Correcto. Hasta 90 días antes de que venza el registro."},"ref":{"doc":"NC","page":101}},{"id":"nc-117","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, you become tired while driving, so you stop. What does the handbook say can help for a short time?","o":["Opening the window and singing","Driving faster to get home sooner","A short nap of 15 to 45 minutes and some caffeine","Turning the radio up loud"],"h1":"Stop first. Then rest briefly.","h2":"In North Carolina, the handbook says that if you get tired you should stop; a short nap of 15 to 45 minutes and caffeine can help for a short time.","p":"Right. Stop, nap 15 to 45 minutes, and have some caffeine."},"es":{"q":"En Carolina del Norte, usted se cansa mientras maneja y se detiene. ¿Qué dice el manual que puede ayudar por un rato?","o":["Abrir la ventana y cantar","Manejar más rápido para llegar antes","Una siesta corta de 15 a 45 minutos y algo de cafeína","Subir mucho el volumen del radio"],"h1":"Primero deténgase. Luego descanse un poco.","h2":"En Carolina del Norte, el manual dice que si se cansa debe detenerse; una siesta corta de 15 a 45 minutos y cafeína pueden ayudar por un rato.","p":"Correcto. Deténgase, duerma de 15 a 45 minutos y tome algo de cafeína."},"ref":{"doc":"NC","page":40}},{"id":"nc-118","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, to stay safe from air bags, which children should ride buckled up in a back seat?","o":["Only babies under 1","Children 12 and under","Only children under 5","Children under 16 only on highways"],"h1":"Air bags are made for adults. Think of children up to about middle school age.","h2":"In North Carolina, the handbook says children 12 and under should ride buckled up in a back seat.","p":"Right. Children 12 and under ride in the back."},"es":{"q":"En Carolina del Norte, para protegerse de las bolsas de aire, ¿qué niños deben ir abrochados en un asiento de atrás?","o":["Solo los bebés menores de 1 año","Los niños de 12 años o menos","Solo los niños menores de 5 años","Los menores de 16 solo en autopistas"],"h1":"Las bolsas de aire están hechas para adultos. Piense en niños hasta la edad de la escuela media.","h2":"En Carolina del Norte, el manual dice que los niños de 12 años o menos deben ir abrochados en un asiento de atrás.","p":"Correcto. Los niños de 12 años o menos van atrás."},"ref":{"doc":"NC","page":45}},{"id":"nc-119","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, a police officer has stopped your car. What should you and your passengers do while the officer comes to you?","o":["Get out and walk toward the officer","Take off your seat belts so you are ready","Search the glove box for your papers right away","Stay seated and keep your seat belts on unless the officer asks otherwise"],"h1":"Stay calm and still, and let the officer give the instructions.","h2":"In North Carolina, after a traffic stop you and your passengers should stay seated in the car and keep your seat belts on unless the officer asks you to remove them.","p":"Right. Stay seated and keep your seat belts on."},"es":{"q":"En Carolina del Norte, un policía ha detenido su carro. ¿Qué deben hacer usted y sus pasajeros mientras el policía se acerca?","o":["Bajarse y caminar hacia el policía","Quitarse los cinturones para estar listos","Buscar sus papeles en la guantera de inmediato","Quedarse sentados con el cinturón puesto, a menos que el policía pida otra cosa"],"h1":"Mantenga la calma, no se mueva y deje que el policía dé las instrucciones.","h2":"En Carolina del Norte, después de que lo detiene la policía, usted y sus pasajeros deben quedarse sentados en el carro con el cinturón puesto, a menos que el policía les pida quitárselo.","p":"Correcto. Quédense sentados con el cinturón puesto."},"ref":{"doc":"NC","page":49}},{"id":"nc-120","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, when your high-beam headlights are on at night, how far away should you be able to see a person?","o":["200 feet","75 feet","50 feet","1,000 feet"],"h1":"Low beams show a person about 75 feet away. High beams reach much farther.","h2":"In North Carolina, with high beams you should be able to see a person 200 feet away; with low beams, about 75 feet.","p":"Right. High beams should show a person 200 feet away."},"es":{"q":"En Carolina del Norte, con las luces altas encendidas de noche, ¿a qué distancia debería poder ver a una persona?","o":["200 pies","75 pies","50 pies","1,000 pies"],"h1":"Con las luces bajas se ve a una persona a unos 75 pies. Las altas llegan mucho más lejos.","h2":"En Carolina del Norte, con las luces altas debería poder ver a una persona a 200 pies; con las bajas, a unos 75 pies.","p":"Correcto. Con luces altas debe ver a una persona a 200 pies."},"ref":{"doc":"NC","page":65}},{"id":"nc-121","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, when you press the brake pedal all the way down, how far from the floor should it still be?","o":["It should touch the floor","At least 1 inch","At least one-third of its normal distance from the floor","At least half of its normal distance from the floor"],"h1":"If it goes lower than a certain part of its normal distance, the brakes need to be checked.","h2":"In North Carolina, a fully pressed brake pedal should stay at least one-third of its original distance from the floor; if not, have the brakes checked.","p":"Right. At least one-third of its distance from the floor."},"es":{"q":"En Carolina del Norte, cuando pisa el pedal del freno hasta el fondo, ¿a qué distancia del piso debe quedar todavía?","o":["Debe tocar el piso","Al menos 1 pulgada","Al menos un tercio de su distancia normal del piso","Al menos la mitad de su distancia normal del piso"],"h1":"Si baja más de cierta parte de su distancia normal, hay que revisar los frenos.","h2":"En Carolina del Norte, el pedal del freno pisado a fondo debe quedar al menos a un tercio de su distancia original del piso; si no, haga revisar los frenos.","p":"Correcto. Al menos un tercio de su distancia del piso."},"ref":{"doc":"NC","page":66}},{"id":"nc-122","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, how often should you check the air pressure in your tires?","o":["Once a year at inspection","At least once a month","Only when a tire looks flat","Every time you buy gas"],"h1":"It is a regular habit, about twelve times a year.","h2":"In North Carolina, the handbook says to check your tire air pressure at least once each month.","p":"Right. Check tire pressure at least once a month."},"es":{"q":"En Carolina del Norte, ¿cada cuánto debe revisar la presión de aire de sus llantas?","o":["Una vez al año en la inspección","Al menos una vez al mes","Solo cuando una llanta se vea desinflada","Cada vez que pone gasolina"],"h1":"Es un hábito regular, unas doce veces al año.","h2":"En Carolina del Norte, el manual dice que debe revisar la presión de aire de las llantas al menos una vez al mes.","p":"Correcto. Revise la presión al menos una vez al mes."},"ref":{"doc":"NC","page":67}},{"id":"nc-123","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, how far ahead on the road do good drivers try to look?","o":["1 to 2 seconds ahead","Only to the car in front","30 to 60 seconds ahead","10 to 15 seconds ahead, about one city block"],"h1":"In a city, it is about one block.","h2":"In North Carolina, good drivers try to look 10 to 15 seconds ahead, which is about one city block.","p":"Right. Look 10 to 15 seconds ahead."},"es":{"q":"En Carolina del Norte, ¿qué tan lejos en la vía tratan de mirar los buenos conductores?","o":["De 1 a 2 segundos adelante","Solo hasta el carro de enfrente","De 30 a 60 segundos adelante","De 10 a 15 segundos adelante, como una cuadra de ciudad"],"h1":"En una ciudad, es como una cuadra.","h2":"En Carolina del Norte, los buenos conductores tratan de mirar de 10 a 15 segundos adelante, como una cuadra de ciudad.","p":"Correcto. Mire de 10 a 15 segundos adelante."},"ref":{"doc":"NC","page":68}},{"id":"nc-124","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, cars are coming toward you on your left and a child is riding a bicycle on your right. Where should you give the most room?","o":["To the child on the bicycle","To the oncoming cars","Exactly in the middle, no matter what","Nowhere; speed up and pass both quickly"],"h1":"Give the most room to the danger most likely to make a sudden move.","h2":"In North Carolina, when facing two dangers, give the most room to the one most likely to move suddenly, such as a child on a bicycle, even if that puts you closer to oncoming cars.","p":"Right. Give the child more room."},"es":{"q":"En Carolina del Norte, vienen carros hacia usted por su izquierda y un niño va en bicicleta a su derecha. ¿A quién debe darle más espacio?","o":["Al niño en bicicleta","A los carros que vienen","Exactamente en el medio, pase lo que pase","A nadie; acelere y pase a los dos rápido"],"h1":"Dele más espacio al peligro que es más probable que haga un movimiento repentino.","h2":"En Carolina del Norte, ante dos peligros, dele más espacio al que es más probable que se mueva de repente, como un niño en bicicleta, aunque eso lo acerque a los carros que vienen.","p":"Correcto. Dele más espacio al niño."},"ref":{"doc":"NC","page":69}},{"id":"nc-125","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, it is raining. How much following distance should you leave?","o":["The same as on a dry road","Half the normal distance","At least twice the normal distance","One car length"],"h1":"Stopping on wet pavement takes much longer.","h2":"In North Carolina, in the rain you should slow down and leave at least twice the normal following distance.","p":"Right. Leave at least twice the normal distance."},"es":{"q":"En Carolina del Norte, está lloviendo. ¿Cuánta distancia debe dejar con el carro de adelante?","o":["La misma que en una vía seca","La mitad de la distancia normal","Al menos el doble de la distancia normal","El largo de un carro"],"h1":"Detenerse en pavimento mojado toma mucho más.","h2":"En Carolina del Norte, cuando llueve debe ir más despacio y dejar al menos el doble de la distancia normal.","p":"Correcto. Deje al menos el doble de la distancia normal."},"ref":{"doc":"NC","page":72}},{"id":"nc-126","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, at about what speed can hydroplaning start on a wet road?","o":["Only above 70 mph","As low as 30 mph","Only above 55 mph","Only above 45 mph"],"h1":"It can happen at speeds much lower than many people think.","h2":"In North Carolina, hydroplaning can start at speeds as low as 30 mph, in water a little more than 1/8 inch deep.","p":"Right. Hydroplaning can start at 30 mph."},"es":{"q":"En Carolina del Norte, ¿desde qué velocidad puede empezar el hidroplaneo en una vía mojada?","o":["Solo a más de 70 mph","Desde apenas 30 mph","Solo a más de 55 mph","Solo a más de 45 mph"],"h1":"Puede pasar a velocidades mucho más bajas de lo que muchos creen.","h2":"En Carolina del Norte, el hidroplaneo puede empezar a solo 30 mph, en agua de poco más de 1/8 de pulgada.","p":"Correcto. El hidroplaneo puede empezar a 30 mph."},"ref":{"doc":"NC","page":72}},{"id":"nc-127","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, how deep does fast-moving water need to be to sweep a car off the road?","o":["3 feet","2 feet","18 inches","Only about 6 inches"],"h1":"Much less than most people think.","h2":"In North Carolina, the handbook warns that just 6 inches of fast-moving water can sweep a car off the road.","p":"Right. Only 6 inches of fast water can sweep a car away."},"es":{"q":"En Carolina del Norte, ¿qué tan profunda debe ser el agua que corre rápido para arrastrar un carro fuera de la vía?","o":["3 pies","2 pies","18 pulgadas","Solo unas 6 pulgadas"],"h1":"Mucho menos de lo que la mayoría cree.","h2":"En Carolina del Norte, el manual advierte que solo 6 pulgadas de agua que corre rápido pueden arrastrar un carro fuera de la vía.","p":"Correcto. Solo 6 pulgadas de agua rápida pueden arrastrar un carro."},"ref":{"doc":"NC","page":73}},{"id":"nc-128","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, you must drive on packed snow. How much should you lower your speed?","o":["By more than half","By about 5 mph","Not at all if you have snow tires","By about one-quarter"],"h1":"Packed snow is very slippery. The cut is large, and on ice you slow to a crawl.","h2":"In North Carolina, the handbook recommends cutting your speed by more than half on packed snow and slowing to a crawl on ice.","p":"Right. Cut your speed by more than half."},"es":{"q":"En Carolina del Norte, usted debe manejar sobre nieve compactada. ¿Cuánto debe bajar la velocidad?","o":["Más de la mitad","Unas 5 mph","Nada si tiene llantas para nieve","Como una cuarta parte"],"h1":"La nieve compactada es muy resbalosa. La reducción es grande, y en hielo se va casi a paso de tortuga.","h2":"En Carolina del Norte, el manual recomienda bajar la velocidad más de la mitad sobre nieve compactada e ir casi a paso de tortuga sobre hielo.","p":"Correcto. Baje la velocidad más de la mitad."},"ref":{"doc":"NC","page":73}},{"id":"nc-129","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, you hit a deer and pull off the road safely. What should you do next?","o":["Go to the deer to see if it is alive","Drag the deer off the road yourself","Stay in your car with the doors locked and hazard lights on, and do not go near the animal","Drive away without telling anyone"],"h1":"A hurt animal can be dangerous.","h2":"In North Carolina, after hitting an animal, pull off safely, stay in your car with the doors locked and hazard lights on, do not go near the animal, and report it.","p":"Right. Stay in the car and do not go near the animal."},"es":{"q":"En Carolina del Norte, usted choca con un venado y se sale de la vía de forma segura. ¿Qué debe hacer después?","o":["Ir hacia el venado para ver si está vivo","Arrastrar el venado fuera de la vía usted mismo","Quedarse en el carro con las puertas cerradas con seguro y las luces de emergencia encendidas, sin acercarse al animal","Irse sin avisar a nadie"],"h1":"Un animal herido puede ser peligroso.","h2":"En Carolina del Norte, después de chocar con un animal, sálgase de la vía con cuidado, quédese en el carro con las puertas cerradas con seguro y las luces de emergencia encendidas, no se acerque al animal y reporte el choque.","p":"Correcto. Quédese en el carro y no se acerque al animal."},"ref":{"doc":"NC","page":75}},{"id":"nc-130","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, you have a small crash in a highway travel lane. No one is hurt and both cars can still be driven safely. What should you do with the cars?","o":["Leave them exactly where they stopped until police arrive","Move them out of the travel lane onto the shoulder","Drive home and report it later","Push them into the median by hand"],"h1":"Keeping cars in the lane can cause another crash.","h2":"In North Carolina, if no one is hurt or killed and the cars can be driven safely, move them out of the travel lane onto the shoulder.","p":"Right. Move the cars onto the shoulder."},"es":{"q":"En Carolina del Norte, usted tiene un choque pequeño en un carril de la autopista. Nadie está herido y los dos carros se pueden manejar sin peligro. ¿Qué debe hacer con los carros?","o":["Dejarlos justo donde quedaron hasta que llegue la policía","Sacarlos del carril y llevarlos al acotamiento","Irse a casa y reportarlo después","Empujarlos a mano hasta la mediana"],"h1":"Dejar los carros en el carril puede causar otro choque.","h2":"En Carolina del Norte, si nadie está herido ni muerto y los carros se pueden manejar sin peligro, sáquelos del carril y llévelos al acotamiento.","p":"Correcto. Lleve los carros al acotamiento."},"ref":{"doc":"NC","page":78}},{"id":"nc-131","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, at an intersection with no traffic lights, a person with a white cane or a guide dog is crossing. What should you do?","o":["Honk so the person knows you are there","Drive around the person slowly","Go first, because there is no signal","Stop and let the person cross; the law gives them special care"],"h1":"The law gives these walkers extra protection.","h2":"In North Carolina, the law gives special consideration to a blind pedestrian with a white cane or guide dog at an intersection without signals, so stop and let the person cross.","p":"Right. Stop and let the person cross."},"es":{"q":"En Carolina del Norte, en una intersección sin semáforos, una persona con un bastón blanco o un perro guía está cruzando. ¿Qué debe hacer?","o":["Tocar la bocina para que sepa que usted está ahí","Pasar alrededor de la persona despacio","Pasar primero, porque no hay semáforo","Detenerse y dejar que cruce; la ley le da una protección especial"],"h1":"La ley les da a estos peatones una protección extra.","h2":"En Carolina del Norte, la ley da una consideración especial a un peatón ciego con bastón blanco o perro guía en una intersección sin semáforos, así que deténgase y déjelo cruzar.","p":"Correcto. Deténgase y deje que la persona cruce."},"ref":{"doc":"NC","page":46}},{"id":"nc-132","scope":"NC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Carolina, does the Move Over Law also cover a public service vehicle that is helping a driver with a disabled car, with its warning lights on?","o":["Yes, it covers these vehicles too","No, only police cars","No, only fire trucks and ambulances","Only at night"],"h1":"The law covers vehicles that help stranded or wrecked drivers, not just police, fire and ambulances.","h2":"In North Carolina, the Move Over Law also covers a public service vehicle helping drivers with wrecked or disabled cars when it is stopped within 12 feet of the road with warning lights on.","p":"Right. Move over for these vehicles too."},"es":{"q":"En Carolina del Norte, ¿la Ley de Moverse (Move Over Law) también aplica a un vehículo de servicio público que ayuda a un conductor con un carro averiado y tiene las luces de advertencia encendidas?","o":["Sí, también aplica a estos vehículos","No, solo a los carros de policía","No, solo a bomberos y ambulancias","Solo de noche"],"h1":"La ley cubre a los vehículos que ayudan a conductores varados o chocados, no solo a policía, bomberos y ambulancias.","h2":"En Carolina del Norte, la Ley de Moverse también cubre a un vehículo de servicio público que ayuda con carros chocados o averiados cuando está detenido a 12 pies o menos de la vía con las luces de advertencia encendidas.","p":"Correcto. Muévase también por estos vehículos."},"ref":{"doc":"NC","page":49}},{"id":"nc-133","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, a slow farm tractor ahead of you slows down, and its driver signals with the left hand. What should you do?","o":["Pass it right away, because the driver is waving you by","Honk and pass on the right","Stay back and do not pass; the tractor may be turning left","Pass it even in a no-passing zone"],"h1":"Many farm equipment crashes happen when a driver mistakes this signal.","h2":"In North Carolina, a farm driver's left-hand signal may mean a left turn, not an invitation to pass, so stay back; it is safest to pass only when the farm equipment pulls off the road.","p":"Right. Stay back; the tractor may be turning left."},"es":{"q":"En Carolina del Norte, un tractor lento delante de usted reduce la velocidad y su conductor hace una señal con la mano izquierda. ¿Qué debe hacer?","o":["Rebasarlo de inmediato, porque le está indicando que pase","Tocar la bocina y rebasar por la derecha","Quedarse atrás y no rebasar; el tractor puede estar por girar a la izquierda","Rebasarlo aunque esté en zona de no rebasar"],"h1":"Muchos choques con equipo agrícola pasan cuando un conductor confunde esta señal.","h2":"En Carolina del Norte, la señal con la mano izquierda de un conductor agrícola puede significar un giro a la izquierda, no una invitación a rebasar, así que quédese atrás; lo más seguro es rebasar solo cuando el equipo agrícola se sale de la vía.","p":"Correcto. Quédese atrás; el tractor puede girar a la izquierda."},"ref":{"doc":"NC","page":51}},{"id":"nc-134","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, a funeral procession is going through a red light at an intersection. Your light is green. What should you do?","o":["Go, because your light is green","Do not enter unless you can do it safely without crossing the procession's path","Honk to make the procession stop","Drive in between two cars in the procession"],"h1":"Once the lead car goes through properly, the whole procession may keep going.","h2":"In North Carolina, when a funeral procession is going through a red light, you may not enter the intersection, even on green, unless you can do it safely without crossing the procession's path.","p":"Right. Do not cut into the procession's path."},"es":{"q":"En Carolina del Norte, un cortejo fúnebre está pasando con luz roja por una intersección. Su luz está en verde. ¿Qué debe hacer?","o":["Avanzar, porque su luz está en verde","No entrar a menos que pueda hacerlo con seguridad sin cruzar el camino del cortejo","Tocar la bocina para que el cortejo se detenga","Meterse entre dos carros del cortejo"],"h1":"Cuando el carro de adelante pasa correctamente, todo el cortejo puede seguir.","h2":"En Carolina del Norte, cuando un cortejo fúnebre pasa con luz roja, usted no puede entrar a la intersección, aunque tenga luz verde, a menos que pueda hacerlo con seguridad sin cruzar el camino del cortejo.","p":"Correcto. No se meta en el camino del cortejo."},"ref":{"doc":"NC","page":52}},{"id":"nc-135","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, you and another car reach an intersection with no signs or signals at the same time. The other car is on your right. Who goes first?","o":["You, because you are on the left","The faster car","The larger vehicle","The car on your right"],"h1":"The rule points to one side.","h2":"In North Carolina, when two vehicles reach an intersection with no signs or signals at the same time, the vehicle on the right has the right of way.","p":"Right. The car on the right goes first."},"es":{"q":"En Carolina del Norte, usted y otro carro llegan al mismo tiempo a una intersección sin señales ni semáforos. El otro carro está a su derecha. ¿Quién pasa primero?","o":["Usted, porque está a la izquierda","El carro más rápido","El vehículo más grande","El carro a su derecha"],"h1":"La regla señala hacia un lado.","h2":"En Carolina del Norte, cuando dos vehículos llegan al mismo tiempo a una intersección sin señales ni semáforos, el vehículo de la derecha tiene el derecho de paso.","p":"Correcto. El carro de la derecha pasa primero."},"ref":{"doc":"NC","page":57}},{"id":"nc-136","scope":"NC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Carolina, you are pulling out of a private driveway onto a street. What must you do?","o":["Stop and yield to all vehicles and pedestrians","Honk and pull out","Yield only to cars on your left","Go first, because you were there first"],"h1":"Coming out of a driveway, you do not have the right of way.","h2":"In North Carolina, when leaving a private driveway you must stop and yield to all other vehicles and pedestrians.","p":"Right. Stop and yield to everyone."},"es":{"q":"En Carolina del Norte, usted sale de una entrada privada (driveway) a una calle. ¿Qué debe hacer?","o":["Detenerse y ceder el paso a todos los vehículos y peatones","Tocar la bocina y salir","Ceder el paso solo a los carros de su izquierda","Salir primero, porque llegó antes"],"h1":"Al salir de una entrada privada, usted no tiene el derecho de paso.","h2":"En Carolina del Norte, al salir de una entrada privada debe detenerse y ceder el paso a todos los demás vehículos y peatones.","p":"Correcto. Deténgase y ceda el paso a todos."},"ref":{"doc":"NC","page":57}},{"id":"nc-137","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, you are inside a roundabout behind a person riding a bicycle. What should you do?","o":["Pass the bicycle on the left inside the circle","Honk so the rider moves to the shoulder","Stay behind; do not pass a bicycle inside the roundabout","Pass on the inside apron"],"h1":"Roundabouts are small and slow. Wait until you are out.","h2":"In North Carolina, drivers should not pass a person riding a bicycle while inside a roundabout.","p":"Right. Do not pass a bicycle inside the roundabout."},"es":{"q":"En Carolina del Norte, usted está dentro de una glorieta detrás de una persona en bicicleta. ¿Qué debe hacer?","o":["Rebasar la bicicleta por la izquierda dentro del círculo","Tocar la bocina para que el ciclista se mueva al borde","Quedarse atrás; no rebase una bicicleta dentro de la glorieta","Rebasar por la plataforma interior"],"h1":"Las glorietas son pequeñas y lentas. Espere a salir.","h2":"En Carolina del Norte, los conductores no deben rebasar a una persona en bicicleta dentro de una glorieta.","p":"Correcto. No rebase una bicicleta dentro de la glorieta."},"ref":{"doc":"NC","page":59}},{"id":"nc-138","scope":"NC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Carolina, an ambulance with its siren on and a train both reach a railroad crossing. Who has the right of way?","o":["The ambulance","The train","Whoever gets there first","The ambulance, if its lights are flashing"],"h1":"Trains cannot stop quickly or turn.","h2":"In North Carolina, trains have the right of way over all highway traffic, even police cars, fire trucks and ambulances.","p":"Right. The train always has the right of way."},"es":{"q":"En Carolina del Norte, una ambulancia con la sirena encendida y un tren llegan a un cruce de ferrocarril. ¿Quién tiene el derecho de paso?","o":["La ambulancia","El tren","El que llegue primero","La ambulancia, si tiene las luces encendidas"],"h1":"Los trenes no pueden detenerse rápido ni girar.","h2":"En Carolina del Norte, los trenes tienen el derecho de paso sobre todo el tráfico de la carretera, incluso policía, bomberos y ambulancias.","p":"Correcto. El tren siempre tiene el derecho de paso."},"ref":{"doc":"NC","page":60}},{"id":"nc-139","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, what following distance rule does the driver handbook teach?","o":["One car length for every 20 mph","The one-second rule","The five-second rule","The two-second rule"],"h1":"Count from when the car ahead passes a point until you reach it.","h2":"In North Carolina, the handbook teaches the two-second rule: leave two seconds between when the car ahead passes a point and when you reach it.","p":"Right. Use the two-second rule."},"es":{"q":"En Carolina del Norte, ¿qué regla de distancia enseña el manual del conductor?","o":["Un largo de carro por cada 20 mph","La regla de un segundo","La regla de cinco segundos","La regla de dos segundos"],"h1":"Cuente desde que el carro de adelante pasa un punto hasta que usted llega a ese punto.","h2":"En Carolina del Norte, el manual enseña la regla de dos segundos: deje dos segundos entre el momento en que el carro de adelante pasa un punto y el momento en que usted llega a él.","p":"Correcto. Use la regla de dos segundos."},"ref":{"doc":"NC","page":54}},{"id":"nc-140","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, you are on a hill or curve. Passing is unsafe and usually illegal if you cannot see at least how far ahead?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In North Carolina, passing on a hill or curve is unsafe and usually illegal when you cannot see at least 500 feet ahead.","p":"Right. You need to see at least 500 feet ahead."},"es":{"q":"En Carolina del Norte, usted está en una colina o curva. ¿Cuánta distancia adelante debe poder ver, como mínimo, para que rebasar no sea peligroso y casi siempre ilegal?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es como el largo de un campo y medio de fútbol americano.","h2":"En Carolina del Norte, rebasar en una colina o curva es peligroso y casi siempre ilegal cuando no puede ver al menos 500 pies adelante.","p":"Correcto. Debe ver al menos 500 pies adelante."},"ref":{"doc":"NC","page":55}},{"id":"nc-141","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, passing on the right is usually against the law. When is it allowed?","o":["When the car ahead is going slowly on a two-lane road","On the paved shoulder when traffic is slow","When the car ahead is in a left-turn lane","Whenever the driver ahead waves you by"],"h1":"Think of a car that is waiting to turn the other way.","h2":"In North Carolina, passing on the right is allowed in a few cases, such as passing a vehicle that is in a left-turn lane.","p":"Right. You may pass a car that is in a left-turn lane."},"es":{"q":"En Carolina del Norte, rebasar por la derecha casi siempre va contra la ley. ¿Cuándo se permite?","o":["Cuando el carro de adelante va lento en una vía de dos carriles","Por el acotamiento pavimentado cuando el tráfico va lento","Cuando el carro de adelante está en un carril para girar a la izquierda","Siempre que el conductor de adelante le haga señas para pasar"],"h1":"Piense en un carro que espera para girar hacia el otro lado.","h2":"En Carolina del Norte, rebasar por la derecha se permite en pocos casos, por ejemplo al pasar a un vehículo que está en un carril para girar a la izquierda.","p":"Correcto. Puede pasar a un carro que está en un carril para girar a la izquierda."},"ref":{"doc":"NC","page":55}},{"id":"nc-142","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, when is it legal to park on the shoulder of a highway?","o":["Never, for any reason","Only when drivers from both directions can see your car from at least 200 feet","Any time your hazard lights are on","Only at night"],"h1":"Other drivers need to see your car in time.","h2":"In North Carolina, parking on a highway shoulder is against the law unless approaching drivers from both directions can see the car from at least 200 feet.","p":"Right. It must be visible from 200 feet both ways."},"es":{"q":"En Carolina del Norte, ¿cuándo es legal estacionarse en el acotamiento de una carretera?","o":["Nunca, por ninguna razón","Solo cuando los conductores de ambas direcciones pueden ver su carro desde al menos 200 pies","Siempre que tenga las luces de emergencia encendidas","Solo de noche"],"h1":"Los otros conductores deben ver su carro a tiempo.","h2":"En Carolina del Norte, estacionarse en el acotamiento de una carretera va contra la ley a menos que los conductores de ambas direcciones puedan ver el carro desde al menos 200 pies.","p":"Correcto. Debe verse desde 200 pies en ambas direcciones."},"ref":{"doc":"NC","page":56}},{"id":"nc-143","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, about how fast do modern roundabouts make vehicles travel?","o":["35 to 45 mph","5 mph or less","25 to 35 mph","15 to 20 mph"],"h1":"They are built for low speeds, which is why they are safer.","h2":"In North Carolina, modern roundabouts are small and make vehicles travel at low speeds of about 15 to 20 mph.","p":"Right. About 15 to 20 mph."},"es":{"q":"En Carolina del Norte, ¿a qué velocidad hacen circular a los vehículos las glorietas modernas, más o menos?","o":["De 35 a 45 mph","5 mph o menos","De 25 a 35 mph","De 15 a 20 mph"],"h1":"Están hechas para velocidades bajas, y por eso son más seguras.","h2":"En Carolina del Norte, las glorietas modernas son pequeñas y hacen que los vehículos circulen a velocidades bajas, de unas 15 a 20 mph.","p":"Correcto. Unas 15 a 20 mph."},"ref":{"doc":"NC","page":58}},{"id":"nc-144","scope":"NC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Carolina, where does a highway work zone begin and end?","o":["Only where workers are standing","Only where cones are in the road","From the first sign that shows the work zone begins to the last sign that shows it ends","One mile before and after the equipment"],"h1":"The signs mark the zone, not the workers.","h2":"In North Carolina, a highway work zone is the area between the first sign showing the work zone begins and the last sign showing it ends.","p":"Right. From the first sign to the last sign."},"es":{"q":"En Carolina del Norte, ¿dónde empieza y dónde termina una zona de trabajo en la carretera?","o":["Solo donde están los trabajadores","Solo donde hay conos en la vía","Desde la primera señal que indica que empieza la zona de trabajo hasta la última que indica que termina","Una milla antes y después de la maquinaria"],"h1":"Las señales marcan la zona, no los trabajadores.","h2":"En Carolina del Norte, una zona de trabajo en la carretera es el área entre la primera señal que indica su inicio y la última señal que indica su fin.","p":"Correcto. Desde la primera señal hasta la última."},"ref":{"doc":"NC","page":70}},{"id":"nc-145","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, how do you pass a motorcycle?","o":["Share its lane and pass close beside it","Change lanes and pass, just as you would pass a car","Pass on the right shoulder","Honk and wait for it to move over"],"h1":"A motorcycle has a right to its whole lane.","h2":"In North Carolina, a motorcycle is entitled to the full width of its lane, so to pass it you must change lanes as you would for a larger vehicle.","p":"Right. Change lanes to pass a motorcycle."},"es":{"q":"En Carolina del Norte, ¿cómo se rebasa a una motocicleta?","o":["Compartiendo su carril y pasando muy cerca a su lado","Cambiándose de carril y rebasando igual que a un carro","Pasando por el acotamiento derecho","Tocando la bocina y esperando a que se mueva"],"h1":"Una motocicleta tiene derecho a todo su carril.","h2":"En Carolina del Norte, una motocicleta tiene derecho a todo el ancho de su carril, así que para rebasarla debe cambiarse de carril como lo haría con un vehículo más grande.","p":"Correcto. Cámbiese de carril para rebasar una motocicleta."},"ref":{"doc":"NC","page":92}},{"id":"nc-146","scope":"NC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Carolina, what is the highest speed a legal moped may be able to go?","o":["45 mph","20 mph","55 mph","30 mph"],"h1":"A moped in this state also has a small motor of 50 cc or less.","h2":"In North Carolina, a moped's top speed may not be more than 30 mph; faster models are illegal to use as mopeds.","p":"Right. A legal moped tops out at 30 mph."},"es":{"q":"En Carolina del Norte, ¿cuál es la velocidad máxima que puede alcanzar un ciclomotor (moped) legal?","o":["45 mph","20 mph","55 mph","30 mph"],"h1":"En este estado un ciclomotor también tiene un motor pequeño de 50 cc o menos.","h2":"En Carolina del Norte, la velocidad máxima de un ciclomotor no puede pasar de 30 mph; los modelos más rápidos son ilegales como ciclomotores.","p":"Correcto. Un ciclomotor legal llega como máximo a 30 mph."},"ref":{"doc":"NC","page":93}},{"id":"nc-147","scope":"NC","cat":"signals","sign":null,"c":0,"en":{"q":"In North Carolina, a stop sign controls your street, but there is no stop line and no crosswalk. Where must you stop?","o":["Before entering the intersection, where you can see the cross street","In the middle of the intersection","At least 100 feet before the sign","You do not need to stop without a line"],"h1":"You still must stop, and you need to be able to see the other traffic.","h2":"In North Carolina, if there is no stop line or marked crosswalk, stop before entering the intersection at a point where you can see the cross street.","p":"Right. Stop before the intersection where you can see."},"es":{"q":"En Carolina del Norte, una señal de alto controla su calle, pero no hay línea de alto ni cruce peatonal. ¿Dónde debe detenerse?","o":["Antes de entrar a la intersección, donde pueda ver la calle que cruza","En medio de la intersección","Al menos 100 pies antes de la señal","No necesita detenerse si no hay línea"],"h1":"Igual debe detenerse, y necesita poder ver el otro tráfico.","h2":"En Carolina del Norte, si no hay línea de alto ni cruce peatonal marcado, deténgase antes de entrar a la intersección en un punto donde pueda ver la calle que cruza.","p":"Correcto. Deténgase antes de la intersección donde pueda ver."},"ref":{"doc":"NC","page":83}},{"id":"nc-148","scope":"NC","cat":"signals","sign":null,"c":2,"en":{"q":"In North Carolina, may you use the center two-way left-turn lane to pass a slow car?","o":["Yes, if no one is turning","Yes, but only during the day","No, it may not be used for passing or for merging into traffic","Yes, if you signal first"],"h1":"This lane has only one use.","h2":"In North Carolina, the center two-way left-turn lane is only for left turns; it must not be used to pass another vehicle or to merge into traffic.","p":"Right. Never use it to pass or merge."},"es":{"q":"En Carolina del Norte, ¿puede usar el carril central de giro a la izquierda en dos sentidos para rebasar a un carro lento?","o":["Sí, si nadie está girando","Sí, pero solo de día","No, no se puede usar para rebasar ni para incorporarse al tráfico","Sí, si primero pone la señal"],"h1":"Este carril tiene un solo uso.","h2":"En Carolina del Norte, el carril central de giro a la izquierda en dos sentidos es solo para girar a la izquierda; no se debe usar para rebasar ni para incorporarse al tráfico.","p":"Correcto. Nunca lo use para rebasar ni para incorporarse."},"ref":{"doc":"NC","page":88}},{"id":"nc-149","scope":"NC","cat":"signals","sign":null,"c":1,"en":{"q":"In North Carolina, a traffic officer holds up one hand with the palm toward you and gives one long blast on a whistle. What does it mean?","o":["Speed up and go through","Stop","Turn right only","Back up"],"h1":"A series of short blasts means something different from one long blast.","h2":"In North Carolina, a traffic officer usually signals drivers to stop with a raised hand, palm facing the vehicle, and one long whistle blast; short blasts with a wave mean go.","p":"Right. A raised palm and a long whistle mean stop."},"es":{"q":"En Carolina del Norte, un agente de tránsito levanta una mano con la palma hacia usted y da un silbido largo. ¿Qué significa?","o":["Acelere y pase","Deténgase","Gire solo a la derecha","Retroceda"],"h1":"Varios silbidos cortos significan algo distinto a un silbido largo.","h2":"En Carolina del Norte, un agente de tránsito normalmente indica a los conductores que se detengan con la mano levantada, la palma hacia el vehículo, y un silbido largo; silbidos cortos con un gesto de la mano significan avanzar.","p":"Correcto. La palma levantada y un silbido largo significan alto."},"ref":{"doc":"NC","page":88}},{"id":"nc-150","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you are 25 and have a regular learner permit. Who must be with you when you drive?","o":["Any adult, sitting anywhere in the car","A person licensed to drive that type of vehicle, sitting beside you","A licensed driver following you in another car","No one, once you have passed the permit tests"],"h1":"Think about where the helper must sit.","h2":"In North Carolina, a learner permit holder must drive with a person who is licensed to drive that vehicle and is seated beside the permit holder.","p":"Right. A licensed driver must sit beside you."},"es":{"q":"En Carolina del Norte, usted tiene 25 años y un permiso de aprendizaje regular. ¿Quién debe ir con usted cuando maneja?","o":["Cualquier adulto, sentado en cualquier lugar del carro","Una persona con licencia para manejar ese tipo de vehículo, sentada a su lado","Un conductor con licencia que lo sigue en otro carro","Nadie, una vez que aprobó los exámenes del permiso"],"h1":"Piense en dónde debe sentarse la persona que lo acompaña.","h2":"En Carolina del Norte, quien tiene un permiso de aprendizaje debe manejar con una persona que tenga licencia para manejar ese vehículo y que vaya sentada a su lado.","p":"Correcto. Un conductor con licencia debe ir sentado a su lado."},"ref":{"doc":"NC","page":8}},{"id":"nc-151","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, your motorcycle learner permit is about to run out. Can it be renewed?","o":["Yes, one time, for 12 more months","Yes, as many times as you like","No, it can never be renewed","Yes, one time, for six more months"],"h1":"The renewal is shorter than the first permit period.","h2":"In North Carolina, a motorcycle learner permit is good for 12 months and may be renewed one time for six more months.","p":"Right. It can be renewed once, for six months."},"es":{"q":"En Carolina del Norte, su permiso de aprendizaje para motocicleta está por vencer. ¿Se puede renovar?","o":["Sí, una vez, por 12 meses más","Sí, todas las veces que quiera","No, nunca se puede renovar","Sí, una vez, por seis meses más"],"h1":"La renovación es más corta que el primer período del permiso.","h2":"En Carolina del Norte, el permiso de aprendizaje para motocicleta vale 12 meses y se puede renovar una sola vez por seis meses más.","p":"Correcto. Se puede renovar una vez, por seis meses."},"ref":{"doc":"NC","page":9}},{"id":"nc-152","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you are 16 and want a motorcycle learner permit. Which license must you already have?","o":["A full provisional license (Level 3)","A limited learner permit (Level 1)","A limited provisional license (Level 2)","No license is needed first"],"h1":"You need the highest teen level first.","h2":"In North Carolina, a motorcycle learner permit applicant who is 16 or 17 must already hold a full provisional license, and a parent or guardian must sign.","p":"Right. You must already have a full provisional license."},"es":{"q":"En Carolina del Norte, usted tiene 16 años y quiere un permiso de aprendizaje para motocicleta. ¿Qué licencia debe tener ya?","o":["Una licencia provisional completa (Nivel 3)","Un permiso de aprendizaje limitado (Nivel 1)","Una licencia provisional limitada (Nivel 2)","No necesita ninguna licencia antes"],"h1":"Primero necesita el nivel más alto para adolescentes.","h2":"En Carolina del Norte, quien pide un permiso de aprendizaje para motocicleta y tiene 16 o 17 años debe tener ya una licencia provisional completa, y un padre o tutor debe firmar.","p":"Correcto. Debe tener ya una licencia provisional completa."},"ref":{"doc":"NC","page":8}},{"id":"nc-153","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, which test do you NOT have to take to get a learner permit?","o":["The vision test","The traffic signs test","The on-the-road driving test","The knowledge test on traffic laws"],"h1":"You are not yet allowed to drive alone, so one test waits until later.","h2":"In North Carolina, the on-the-road driving test is not required for a learner permit; it comes later, when you apply for a license.","p":"Right. The road test is not needed for a learner permit."},"es":{"q":"En Carolina del Norte, ¿qué examen NO tiene que tomar para obtener un permiso de aprendizaje?","o":["El examen de la vista","El examen de señales de tránsito","El examen práctico de manejo en la calle","El examen de conocimientos sobre las leyes de tránsito"],"h1":"Todavía no puede manejar solo, así que un examen se deja para después.","h2":"En Carolina del Norte, el examen práctico de manejo en la calle no se exige para el permiso de aprendizaje; viene después, cuando pide la licencia.","p":"Correcto. El examen práctico no se necesita para el permiso."},"ref":{"doc":"NC","page":9}},{"id":"nc-154","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, which regular license class do most people need to drive a personal car or small truck?","o":["Class A","Class B","Class C","Class D"],"h1":"It is the class for single vehicles under 26,001 pounds.","h2":"In North Carolina, most drivers need only a regular Class C license to drive personal cars and small trucks.","p":"Right. Most drivers need a Class C license."},"es":{"q":"En Carolina del Norte, ¿qué clase de licencia regular necesita la mayoría de las personas para manejar un carro personal o un camión pequeño?","o":["Clase A","Clase B","Clase C","Clase D"],"h1":"Es la clase para vehículos solos de menos de 26,001 libras.","h2":"En Carolina del Norte, la mayoría de los conductores solo necesita una licencia regular Clase C para manejar carros personales y camiones pequeños.","p":"Correcto. La mayoría necesita una licencia Clase C."},"ref":{"doc":"NC","page":10}},{"id":"nc-155","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, a driver license is not a REAL ID. What words does it show on the front?","o":["Temporary License","Limited Use Only","State Travel Only","Not for Federal Identification"],"h1":"Federal law requires these words on cards that do not meet REAL ID rules.","h2":"In North Carolina, a license or ID card that is not a REAL ID shows the words \"Not for Federal Identification\" on the front.","p":"Right. A non-REAL ID card says \"Not for Federal Identification\"."},"es":{"q":"En Carolina del Norte, una licencia de manejar no es REAL ID. ¿Qué palabras muestra al frente?","o":["Temporary License (licencia temporal)","Limited Use Only (solo uso limitado)","State Travel Only (solo viajes en el estado)","Not for Federal Identification (no válida como identificación federal)"],"h1":"La ley federal exige estas palabras en las tarjetas que no cumplen las reglas de REAL ID.","h2":"En Carolina del Norte, una licencia o tarjeta de identificación que no es REAL ID muestra al frente las palabras \"Not for Federal Identification\" (no válida como identificación federal).","p":"Correcto. Una tarjeta que no es REAL ID dice \"Not for Federal Identification\"."},"ref":{"doc":"NC","page":24}},{"id":"nc-156","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you just moved here with a commercial driver license (CDL) from another state and want to keep driving commercially. How soon must you get a North Carolina CDL?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is half the time a new resident has for a regular license.","h2":"In North Carolina, a new resident who wants to keep a commercial license must get a North Carolina CDL within 30 days of becoming a resident.","p":"Right. A CDL must be changed within 30 days."},"es":{"q":"En Carolina del Norte, usted acaba de mudarse con una licencia de manejo comercial (CDL) de otro estado y quiere seguir manejando vehículos comerciales. ¿En cuánto tiempo debe obtener una CDL de Carolina del Norte?","o":["En un plazo de 10 días","En un plazo de 30 días","En un plazo de 60 días","En un plazo de 90 días"],"h1":"Es la mitad del tiempo que tiene un nuevo residente para una licencia regular.","h2":"En Carolina del Norte, un nuevo residente que quiere conservar una licencia comercial debe obtener una CDL de Carolina del Norte en un plazo de 30 días después de hacerse residente.","p":"Correcto. La CDL se debe cambiar en 30 días."},"ref":{"doc":"NC","page":25}},{"id":"nc-157","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you pass your tests and have your photo taken at the license office. What do you use to drive until the card comes in the mail?","o":["Nothing; you may not drive until the card arrives","A temporary driving certificate, good for 60 days","A receipt that is good for 10 days","Your card is printed at the office, so you need nothing else"],"h1":"Cards are made at a central place and mailed to you.","h2":"In North Carolina, licenses are made at a central location and mailed, so you get a temporary driving certificate that is valid for 60 days.","p":"Right. A temporary certificate lets you drive for 60 days."},"es":{"q":"En Carolina del Norte, usted aprueba sus exámenes y le toman la foto en la oficina de licencias. ¿Qué usa para manejar hasta que la tarjeta le llegue por correo?","o":["Nada; no puede manejar hasta que llegue la tarjeta","Un certificado temporal de manejo, válido por 60 días","Un recibo válido por 10 días","La tarjeta se imprime en la oficina, así que no necesita nada más"],"h1":"Las tarjetas se hacen en un lugar central y se envían por correo.","h2":"En Carolina del Norte, las licencias se hacen en un lugar central y se envían por correo, así que usted recibe un certificado temporal de manejo válido por 60 días.","p":"Correcto. Un certificado temporal le permite manejar por 60 días."},"ref":{"doc":"NC","page":25}},{"id":"nc-158","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, what marks are next to the photo on a license issued to someone under 18?","o":["A blue star in the corner","A small heart symbol","The word MINOR in large letters","Two color bars, red and yellow, showing the 18th and 21st birthdays"],"h1":"The marks help a clerk see quickly when the person turns 18 and 21.","h2":"In North Carolina, a license or ID for someone under 18 has a red bar and a yellow bar next to the photo, showing the dates the person turns 18 and 21.","p":"Right. Red and yellow bars show the 18th and 21st birthdays."},"es":{"q":"En Carolina del Norte, ¿qué marcas hay junto a la foto en una licencia que se da a una persona menor de 18 años?","o":["Una estrella azul en la esquina","Un pequeño símbolo de corazón","La palabra MENOR en letras grandes","Dos barras de color, roja y amarilla, que muestran los cumpleaños 18 y 21"],"h1":"Las marcas ayudan a un empleado a ver rápido cuándo la persona cumple 18 y 21 años.","h2":"En Carolina del Norte, la licencia o identificación de una persona menor de 18 años tiene una barra roja y una barra amarilla junto a la foto, que muestran las fechas en que cumple 18 y 21 años.","p":"Correcto. Las barras roja y amarilla muestran los cumpleaños 18 y 21."},"ref":{"doc":"NC","page":26}},{"id":"nc-159","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you renew your driver license in person at a driver license office. Which test is required?","o":["A vision test","A full knowledge test","A traffic signs test","No test at all"],"h1":"It checks something you use every second you drive.","h2":"In North Carolina, a vision test is required when you renew your license at a driver license office.","p":"Right. An in-office renewal needs a vision test."},"es":{"q":"En Carolina del Norte, usted renueva su licencia en persona en una oficina de licencias. ¿Qué examen se exige?","o":["Un examen de la vista","Un examen completo de conocimientos","Un examen de señales de tránsito","Ningún examen"],"h1":"Revisa algo que usted usa cada segundo que maneja.","h2":"En Carolina del Norte, se exige un examen de la vista cuando renueva su licencia en una oficina de licencias.","p":"Correcto. La renovación en la oficina necesita un examen de la vista."},"ref":{"doc":"NC","page":26}},{"id":"nc-160","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you have been living out of state for a few months and want to renew your Class C license by mail. What is the oldest you may be on the day you ask?","o":["65","70","72","80"],"h1":"It is a little older than 70.","h2":"In North Carolina, a resident renewing a license by mail from out of state must not be older than 72 on the date of the request.","p":"Right. The age limit for renewing by mail is 72."},"es":{"q":"En Carolina del Norte, usted ha vivido fuera del estado por unos meses y quiere renovar su licencia Clase C por correo. ¿Cuál es la edad máxima que puede tener el día que lo pide?","o":["65","70","72","80"],"h1":"Es un poco más de 70.","h2":"En Carolina del Norte, un residente que renueva su licencia por correo desde fuera del estado no debe tener más de 72 años en la fecha de la solicitud.","p":"Correcto. El límite de edad para renovar por correo es 72 años."},"ref":{"doc":"NC","page":26}},{"id":"nc-161","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, what alcohol may a driver carry in the passenger area of a commercial motor vehicle on the highway?","o":["None at all, open or closed","Closed containers only","Beer only","Any alcohol, if the driver does not drink it"],"h1":"The rule for commercial vehicles is stricter than for cars.","h2":"In North Carolina, no alcoholic beverage, open or closed, may be kept in the passenger area of a commercial motor vehicle on a highway or public vehicular area.","p":"Right. No alcohol at all, not even closed containers."},"es":{"q":"En Carolina del Norte, ¿qué alcohol puede llevar un conductor en el área de pasajeros de un vehículo comercial en la carretera?","o":["Ninguno, ni abierto ni cerrado","Solo envases cerrados","Solo cerveza","Cualquier alcohol, si el conductor no lo toma"],"h1":"La regla para vehículos comerciales es más estricta que para carros.","h2":"En Carolina del Norte, no se puede llevar ninguna bebida alcohólica, abierta ni cerrada, en el área de pasajeros de un vehículo comercial en una carretera o área vehicular pública.","p":"Correcto. Ningún alcohol, ni siquiera en envases cerrados."},"ref":{"doc":"NC","page":31}},{"id":"nc-162","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, a driver whose license is revoked for an earlier DWI is convicted of DWI again. What may the court order?","o":["Only a written warning","A free driver improvement clinic","A new license with no restrictions","That the vehicle be seized and sold"],"h1":"The court can take away the car itself.","h2":"In North Carolina, if you are convicted of DWI while your license is revoked for an earlier DWI, the court may order your vehicle seized and sold.","p":"Right. The vehicle may be seized and sold."},"es":{"q":"En Carolina del Norte, un conductor con la licencia revocada por un DWI anterior es condenado otra vez por DWI. ¿Qué puede ordenar el tribunal?","o":["Solo una advertencia por escrito","Una clínica gratis de mejoramiento del conductor","Una licencia nueva sin restricciones","Que el vehículo sea confiscado y vendido"],"h1":"El tribunal puede quitarle el carro mismo.","h2":"En Carolina del Norte, si a usted lo condenan por DWI mientras su licencia está revocada por un DWI anterior, el tribunal puede ordenar que su vehículo sea confiscado y vendido.","p":"Correcto. El vehículo puede ser confiscado y vendido."},"ref":{"doc":"NC","page":32}},{"id":"nc-163","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, your license is given back for the second time after a DWI. What alcohol limit applies to you when you drive?","o":["0.04","0.00, no alcohol at all","0.08","0.02"],"h1":"The first time back, the limit is 0.04. The second time is stricter.","h2":"In North Carolina, on a second or later restoration after a DWI, the alcohol concentration restriction is 0.00.","p":"Right. After a second restoration, the limit is 0.00."},"es":{"q":"En Carolina del Norte, le devuelven la licencia por segunda vez después de un DWI. ¿Qué límite de alcohol se le aplica cuando maneja?","o":["0.04","0.00, nada de alcohol","0.08","0.02"],"h1":"La primera vez el límite es 0.04. La segunda vez es más estricto.","h2":"En Carolina del Norte, cuando la licencia se devuelve por segunda vez o más después de un DWI, la restricción de concentración de alcohol es 0.00.","p":"Correcto. Después de una segunda devolución, el límite es 0.00."},"ref":{"doc":"NC","page":32}},{"id":"nc-164","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, what must anyone convicted of DWI get before the driving privilege is given back?","o":["A new vehicle inspection","A substance abuse assessment","A letter from an employer","A motorcycle safety course"],"h1":"It checks whether the person has a problem with alcohol or drugs.","h2":"In North Carolina, anyone convicted of DWI must get a substance abuse assessment before driving privileges are reinstated.","p":"Right. A substance abuse assessment is required first."},"es":{"q":"En Carolina del Norte, ¿qué debe hacer toda persona condenada por DWI antes de que le devuelvan el privilegio de manejar?","o":["Una nueva inspección del vehículo","Una evaluación de abuso de sustancias","Una carta de su empleador","Un curso de seguridad en motocicleta"],"h1":"Sirve para ver si la persona tiene un problema con el alcohol o las drogas.","h2":"En Carolina del Norte, toda persona condenada por DWI debe hacerse una evaluación de abuso de sustancias antes de que le devuelvan el privilegio de manejar.","p":"Correcto. Primero se exige una evaluación de abuso de sustancias."},"ref":{"doc":"NC","page":32}},{"id":"nc-165","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, how many driver license points do you get for reckless driving?","o":["2 points","3 points","5 points","4 points"],"h1":"It is the same as following too closely.","h2":"In North Carolina, a reckless driving conviction puts 4 points on your driver license record.","p":"Right. Reckless driving is 4 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por manejo imprudente (reckless driving)?","o":["2 puntos","3 puntos","5 puntos","4 puntos"],"h1":"Es lo mismo que por seguir demasiado cerca a otro vehículo.","h2":"En Carolina del Norte, una condena por manejo imprudente pone 4 puntos en su historial de manejo.","p":"Correcto. El manejo imprudente vale 4 puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-166","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, how many driver license points do you get for running through a stop sign?","o":["3 points","1 point","4 points","5 points"],"h1":"It is the same as running a red light.","h2":"In North Carolina, running through a stop sign puts 3 points on your driver license record.","p":"Right. Running a stop sign is 3 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por pasarse una señal de alto (STOP)?","o":["3 puntos","1 punto","4 puntos","5 puntos"],"h1":"Es lo mismo que pasarse una luz roja.","h2":"En Carolina del Norte, pasarse una señal de alto pone 3 puntos en su historial de manejo.","p":"Correcto. Pasarse un alto vale 3 puntos."},"ref":{"doc":"NC","page":34}},{"id":"nc-167","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, how many driver license points do you get for not properly buckling a child in a car seat or seat belt?","o":["1 point","3 points","2 points","None"],"h1":"It counts the same as most other moving violations.","h2":"In North Carolina, failing to properly restrain a child in a child restraint or seat belt puts 2 points on your driver license record.","p":"Right. Not restraining a child properly is 2 points."},"es":{"q":"En Carolina del Norte, ¿cuántos puntos en la licencia recibe por no asegurar bien a un niño en un asiento de seguridad o con el cinturón?","o":["1 punto","3 puntos","2 puntos","Ninguno"],"h1":"Cuenta igual que la mayoría de las otras infracciones en movimiento.","h2":"En Carolina del Norte, no asegurar bien a un niño en un asiento de seguridad o con el cinturón pone 2 puntos en su historial de manejo.","p":"Correcto. No asegurar bien a un niño vale 2 puntos."},"ref":{"doc":"NC","page":35}},{"id":"nc-168","scope":"NC","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Carolina, you are convicted of littering from your car. How many driver license points do you get?","o":["None","2 points","1 point","3 points"],"h1":"It is the smallest point value on the list.","h2":"In North Carolina, littering that involves the use of a motor vehicle puts 1 point on your driver license record.","p":"Right. Littering from a vehicle is 1 point."},"es":{"q":"En Carolina del Norte, lo condenan por tirar basura desde su carro. ¿Cuántos puntos en la licencia recibe?","o":["Ninguno","2 puntos","1 punto","3 puntos"],"h1":"Es el valor más bajo de la lista de puntos.","h2":"En Carolina del Norte, tirar basura usando un vehículo pone 1 punto en su historial de manejo.","p":"Correcto. Tirar basura desde un vehículo vale 1 punto."},"ref":{"doc":"NC","page":35}},{"id":"nc-169","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, the DMV revoked your license and a DMV hearing did not help. How long do you have to appeal to Superior Court?","o":["30 days","10 days","60 days","1 year"],"h1":"It is about one month.","h2":"In North Carolina, you may appeal the DMV decision within 30 days to the Superior Court of the county where you live.","p":"Right. You have 30 days to appeal."},"es":{"q":"En Carolina del Norte, el DMV revocó su licencia y una audiencia del DMV no le ayudó. ¿Cuánto tiempo tiene para apelar ante el Tribunal Superior?","o":["30 días","10 días","60 días","1 año"],"h1":"Es como un mes.","h2":"En Carolina del Norte, usted puede apelar la decisión del DMV en un plazo de 30 días ante el Tribunal Superior (Superior Court) del condado donde vive.","p":"Correcto. Tiene 30 días para apelar."},"ref":{"doc":"NC","page":37}},{"id":"nc-170","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, a driver is charged with reckless driving twice within 12 months. How long is the license suspended?","o":["30 days","1 year","60 days","6 months"],"h1":"It is a full year.","h2":"In North Carolina, two charges of reckless driving within 12 months lead to a one-year license suspension.","p":"Right. Two reckless driving charges in 12 months mean one year."},"es":{"q":"En Carolina del Norte, a un conductor lo acusan dos veces de manejo imprudente en 12 meses. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","1 año","60 días","6 meses"],"h1":"Es un año completo.","h2":"En Carolina del Norte, dos acusaciones de manejo imprudente en 12 meses llevan a una suspensión de la licencia por un año.","p":"Correcto. Dos acusaciones de manejo imprudente en 12 meses significan un año."},"ref":{"doc":"NC","page":37}},{"id":"nc-171","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, you fail to yield the right of way when turning at a stop sign, and someone is seriously hurt. What is the penalty?","o":["A warning only","License suspended for 90 days and a $500 penalty","2 driver license points and no suspension","License suspended for 10 years"],"h1":"The penalty has both a time and a dollar amount.","h2":"In North Carolina, failing to yield the right of way in cases like turning at a stop or yield sign, when it causes serious bodily injury, brings a 90-day suspension and a $500 penalty.","p":"Right. It means 90 days without a license and $500."},"es":{"q":"En Carolina del Norte, usted no cede el paso al girar en una señal de alto, y una persona resulta gravemente herida. ¿Cuál es la pena?","o":["Solo una advertencia","Licencia suspendida por 90 días y una multa de $500","2 puntos en la licencia y ninguna suspensión","Licencia suspendida por 10 años"],"h1":"La pena tiene un tiempo y una cantidad de dinero.","h2":"En Carolina del Norte, no ceder el paso en casos como girar en una señal de alto o de ceda el paso, cuando causa lesiones graves, trae una suspensión de 90 días y una multa de $500.","p":"Correcto. Significa 90 días sin licencia y $500."},"ref":{"doc":"NC","page":37}},{"id":"nc-172","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, you are convicted of a traffic violation while driving in another state. Can it affect your North Carolina license?","o":["No, only North Carolina violations count","Only if you were driving a rental car","Only if the other state sends you a bill","Yes, it can lead to a suspension or revocation as if it happened in North Carolina"],"h1":"Your record follows you across state lines.","h2":"In North Carolina, convictions outside the state may lead to a suspension or revocation just as if the violation happened in North Carolina.","p":"Right. Out-of-state convictions count too."},"es":{"q":"En Carolina del Norte, lo condenan por una infracción de tránsito mientras manejaba en otro estado. ¿Puede afectar su licencia de Carolina del Norte?","o":["No, solo cuentan las infracciones en Carolina del Norte","Solo si manejaba un carro alquilado","Solo si el otro estado le manda una cuenta","Sí, puede causar una suspensión o revocación como si hubiera pasado en Carolina del Norte"],"h1":"Su historial lo sigue de un estado a otro.","h2":"En Carolina del Norte, las condenas fuera del estado pueden causar una suspensión o revocación igual que si la infracción hubiera pasado en Carolina del Norte.","p":"Correcto. Las condenas de otros estados también cuentan."},"ref":{"doc":"NC","page":38}},{"id":"nc-173","scope":"NC","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Carolina, you got a traffic ticket and cannot afford to pay the fine. What can you do to stop your license from being suspended?","o":["Ask the court, with a Motion for Relief, to lower or waive the amount or set a payment plan","Nothing; the license is always suspended","Mail your license to the DMV","Wait, because unpaid fines are canceled after one year"],"h1":"The court has a form for people who have trouble paying.","h2":"In North Carolina, if you cannot afford a fine, you can file a Motion for Relief with the court clerk, and a judge may lower the amount, set a payment plan, or waive it.","p":"Right. Ask the court for relief before the suspension starts."},"es":{"q":"En Carolina del Norte, usted recibió una multa de tránsito y no puede pagarla. ¿Qué puede hacer para que no le suspendan la licencia?","o":["Pedir al tribunal, con una moción de alivio (Motion for Relief), que baje o perdone la cantidad o le dé un plan de pagos","Nada; la licencia siempre se suspende","Enviar su licencia por correo al DMV","Esperar, porque las multas sin pagar se cancelan después de un año"],"h1":"El tribunal tiene un formulario para personas a quienes les cuesta pagar.","h2":"En Carolina del Norte, si no puede pagar una multa, puede presentar una moción de alivio (Motion for Relief) ante el secretario del tribunal, y un juez puede bajar la cantidad, darle un plan de pagos o perdonarla.","p":"Correcto. Pida alivio al tribunal antes de que empiece la suspensión."},"ref":{"doc":"NC","page":38}},{"id":"nc-174","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, to prevent drowsy driving on a long trip, about how many miles a day should you try to limit yourself to?","o":["100 to 150 miles","600 to 700 miles","300 to 400 miles","1,000 miles"],"h1":"It is a few hundred miles, not a thousand.","h2":"In North Carolina, the driver handbook suggests setting a limit of 300 to 400 miles of driving per day to avoid drowsy driving.","p":"Right. Try to keep it to 300 to 400 miles a day."},"es":{"q":"En Carolina del Norte, para evitar manejar con sueño en un viaje largo, ¿a cuántas millas por día debe tratar de limitarse?","o":["De 100 a 150 millas","De 600 a 700 millas","De 300 a 400 millas","1,000 millas"],"h1":"Son unos cientos de millas, no mil.","h2":"En Carolina del Norte, el manual del conductor sugiere un límite de 300 a 400 millas de manejo por día para evitar manejar con sueño.","p":"Correcto. Trate de no pasar de 300 a 400 millas al día."},"ref":{"doc":"NC","page":41}},{"id":"nc-175","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, may a school bus driver use a cell phone while driving the bus on a public road?","o":["Yes, with a hands-free device","Yes, but only to text","No, not at all, hands-free included","Yes, when no children are on the bus"],"h1":"The rule covers any technology tied to a mobile device.","h2":"In North Carolina, no one may drive a school bus on a public street or highway while using a cell phone or any other technology linked to a mobile device.","p":"Right. School bus drivers may not use a phone at all."},"es":{"q":"En Carolina del Norte, ¿puede un conductor de autobús escolar usar un teléfono celular mientras maneja el autobús en una vía pública?","o":["Sí, con un aparato de manos libres","Sí, pero solo para mandar textos","No, de ninguna forma, ni con manos libres","Sí, cuando no hay niños en el autobús"],"h1":"La regla cubre cualquier tecnología ligada a un aparato móvil.","h2":"En Carolina del Norte, nadie puede manejar un autobús escolar en una calle o carretera pública mientras usa un teléfono celular o cualquier otra tecnología ligada a un aparato móvil.","p":"Correcto. Los conductores de autobús escolar no pueden usar el teléfono para nada."},"ref":{"doc":"NC","page":41}},{"id":"nc-176","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, your car has an automatic shoulder belt that moves into place by itself. What else must you wear?","o":["The lap belt","Nothing else; the shoulder belt is enough","A helmet","Nothing, if the car also has air bags"],"h1":"The shoulder belt alone does not hold your hips.","h2":"In North Carolina, if a vehicle has automatic shoulder harnesses, the lap belt must also be worn.","p":"Right. You must also buckle the lap belt."},"es":{"q":"En Carolina del Norte, su carro tiene un cinturón de hombro automático que se coloca solo. ¿Qué más debe usar?","o":["El cinturón de regazo","Nada más; el cinturón de hombro basta","Un casco","Nada, si el carro también tiene bolsas de aire"],"h1":"El cinturón de hombro solo no sujeta sus caderas.","h2":"En Carolina del Norte, si un vehículo tiene cinturones de hombro automáticos, también se debe usar el cinturón de regazo.","p":"Correcto. También debe abrocharse el cinturón de regazo."},"ref":{"doc":"NC","page":43}},{"id":"nc-177","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, a 6-year-old weighs 50 pounds. No seat in the car has a lap and shoulder belt to hold the booster seat. How may the child ride?","o":["Without any belt, in the back seat","On an adult's lap","In the open bed of a pickup truck","Buckled with a properly fitted lap belt only"],"h1":"The law allows one kind of belt when no lap and shoulder belt is free.","h2":"In North Carolina, if no seat with a lap and shoulder belt is available for the weight-appropriate restraint, a child under 8 who weighs 40 to 80 pounds may ride with a properly fitted lap belt only.","p":"Right. A properly fitted lap belt is allowed in that case."},"es":{"q":"En Carolina del Norte, un niño de 6 años pesa 50 libras. Ningún asiento del carro tiene cinturón de regazo y hombro para sujetar el asiento elevado. ¿Cómo puede viajar el niño?","o":["Sin ningún cinturón, en el asiento de atrás","En las piernas de un adulto","En la caja abierta de una camioneta pickup","Abrochado solo con un cinturón de regazo bien ajustado"],"h1":"La ley permite un tipo de cinturón cuando no hay un cinturón de regazo y hombro libre.","h2":"En Carolina del Norte, si no hay un asiento con cinturón de regazo y hombro para el sistema de seguridad adecuado, un niño menor de 8 años que pesa de 40 a 80 libras puede ir solo con un cinturón de regazo bien ajustado.","p":"Correcto. En ese caso se permite un cinturón de regazo bien ajustado."},"ref":{"doc":"NC","page":44}},{"id":"nc-178","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, which is a sign of a legal motorcycle helmet?","o":["A DOT sticker that the rider bought and stuck on","A firm foam inner liner about one inch thick","Only thin, soft foam padding inside","No inner liner, so it is lighter"],"h1":"Legal helmets have thick protection you can feel inside.","h2":"In North Carolina, a legal helmet has a firm polystyrene foam inner liner about one inch thick, and its DOT sticker is put on by the maker, not added later.","p":"Right. A thick, firm inner liner is a sign of a legal helmet."},"es":{"q":"En Carolina del Norte, ¿cuál es una señal de un casco de motocicleta legal?","o":["Una calcomanía DOT que el motociclista compró y pegó","Un forro interior de espuma firme de cerca de una pulgada de grueso","Solo un relleno delgado de espuma suave por dentro","Ningún forro interior, para que pese menos"],"h1":"Los cascos legales tienen una protección gruesa que se siente por dentro.","h2":"En Carolina del Norte, un casco legal tiene un forro interior firme de espuma de poliestireno de cerca de una pulgada de grueso, y la calcomanía DOT la pone el fabricante, no se agrega después.","p":"Correcto. Un forro interior grueso y firme es señal de un casco legal."},"ref":{"doc":"NC","page":45}},{"id":"nc-179","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, a driver lets a 10-year-old ride in the open bed of a pickup with no adult watching. What is the penalty?","o":["A $500 fine and 3 license points","A $25 fine, with no license points","License revoked for one year","No penalty at all"],"h1":"It is an infraction with a small fine.","h2":"In North Carolina, breaking the pickup bed law brings a $25 fine; it is an infraction with no court costs, license points or insurance surcharge.","p":"Right. The fine is $25, with no points."},"es":{"q":"En Carolina del Norte, un conductor deja que un niño de 10 años vaya en la caja abierta de una camioneta pickup sin un adulto que lo cuide. ¿Cuál es la pena?","o":["Una multa de $500 y 3 puntos en la licencia","Una multa de $25, sin puntos en la licencia","Licencia revocada por un año","Ninguna pena"],"h1":"Es una infracción con una multa pequeña.","h2":"En Carolina del Norte, violar la ley de la caja de la pickup trae una multa de $25; es una infracción sin costos de tribunal, puntos en la licencia ni recargo del seguro.","p":"Correcto. La multa es de $25, sin puntos."},"ref":{"doc":"NC","page":46}},{"id":"nc-180","scope":"NC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Carolina, a school bus stops with its stop arm out on a road of four or more lanes with a center turning lane. Who must stop?","o":["Traffic in both directions","Only traffic coming toward the bus","No one, because there is a turn lane","Only traffic following the bus"],"h1":"This is different from a two-lane road with a center turn lane.","h2":"In North Carolina, on a road of four or more lanes with a center turning lane, only traffic following the stopped school bus must stop.","p":"Right. Only traffic behind the bus must stop."},"es":{"q":"En Carolina del Norte, un autobús escolar se detiene con el brazo de alto extendido en una vía de cuatro carriles o más con un carril central para girar. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico que viene de frente al autobús","Nadie, porque hay un carril para girar","Solo el tráfico que va detrás del autobús"],"h1":"Esto es distinto de una vía de dos carriles con carril central para girar.","h2":"En Carolina del Norte, en una vía de cuatro carriles o más con un carril central para girar, solo el tráfico que va detrás del autobús escolar detenido debe parar.","p":"Correcto. Solo el tráfico detrás del autobús debe parar."},"ref":{"doc":"NC","page":48}},{"id":"nc-181","scope":"NC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Carolina, what is the highest speed a school activity bus may drive?","o":["55 mph","35 mph","45 mph","70 mph"],"h1":"It is faster than a regular school bus, which is limited to 45 mph.","h2":"In North Carolina, the maximum speed limit for school activity buses is 55 mph.","p":"Right. School activity buses may go up to 55 mph."},"es":{"q":"En Carolina del Norte, ¿cuál es la velocidad más alta a la que puede ir un autobús de actividades escolares?","o":["55 mph","35 mph","45 mph","70 mph"],"h1":"Es más rápido que un autobús escolar normal, que tiene un límite de 45 mph.","h2":"En Carolina del Norte, el límite máximo de velocidad para los autobuses de actividades escolares es 55 mph.","p":"Correcto. Los autobuses de actividades escolares pueden ir hasta 55 mph."},"ref":{"doc":"NC","page":53}},{"id":"nc-182","scope":"NC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Carolina, the Move Over Law covers an emergency vehicle with its lights on that is parked how close to the road?","o":["Within 50 feet of the roadway","Only when it is in a travel lane","Within 12 feet of the roadway","Within 100 yards of the roadway"],"h1":"It is a short distance, about the width of a lane.","h2":"In North Carolina, the Move Over Law applies when an emergency or public service vehicle with warning lights on is parked or standing within 12 feet of the roadway.","p":"Right. It covers vehicles within 12 feet of the road."},"es":{"q":"En Carolina del Norte, la ley Move Over cubre un vehículo de emergencia con las luces encendidas que está estacionado ¿a qué distancia de la vía?","o":["A 50 pies o menos de la vía","Solo cuando está en un carril de tráfico","A 12 pies o menos de la vía","A 100 yardas o menos de la vía"],"h1":"Es una distancia corta, como el ancho de un carril.","h2":"En Carolina del Norte, la ley Move Over se aplica cuando un vehículo de emergencia o de servicio público con luces de advertencia está estacionado o detenido a 12 pies o menos de la vía.","p":"Correcto. Cubre vehículos a 12 pies o menos de la vía."},"ref":{"doc":"NC","page":49}},{"id":"nc-183","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, a police officer stops you at night. What should you do to help the officer see inside your car?","o":["Turn on your high beams","Get out and stand by the car","Turn on your interior lights","Shine a flashlight toward the officer"],"h1":"Think about lighting up the inside of the car.","h2":"In North Carolina, if you are stopped at night, turn on your interior lights as soon as you stop so the officer can see inside your vehicle.","p":"Right. Turn on the inside lights."},"es":{"q":"En Carolina del Norte, un policía lo detiene de noche. ¿Qué debe hacer para ayudar al agente a ver dentro de su carro?","o":["Encender las luces altas","Bajarse y pararse junto al carro","Encender las luces interiores","Apuntar una linterna hacia el agente"],"h1":"Piense en iluminar el interior del carro.","h2":"En Carolina del Norte, si lo detienen de noche, encienda las luces interiores en cuanto se detenga para que el agente pueda ver dentro de su vehículo.","p":"Correcto. Encienda las luces de adentro."},"ref":{"doc":"NC","page":50}},{"id":"nc-184","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, a police officer stops you. You have a concealed weapon permit and a gun is in the car. What must you do?","o":["Tell the officer about it, and do not reach for it","Hand the gun to the officer right away","Say nothing unless the officer finds it","Get out of the car and put it on the roof"],"h1":"Your hands should stay still, but you must speak up.","h2":"In North Carolina, if you have a concealed weapon permit and a weapon is in the vehicle during a traffic stop, you must tell the officer, and you should not reach for the weapon.","p":"Right. Tell the officer and keep your hands away from it."},"es":{"q":"En Carolina del Norte, un policía lo detiene. Usted tiene permiso para portar un arma oculta y hay una pistola en el carro. ¿Qué debe hacer?","o":["Decírselo al agente, y no tratar de tomar el arma","Darle la pistola al agente de inmediato","No decir nada a menos que el agente la encuentre","Bajarse del carro y ponerla sobre el techo"],"h1":"Sus manos deben quedarse quietas, pero usted debe hablar.","h2":"En Carolina del Norte, si tiene permiso para portar un arma oculta y hay un arma en el vehículo durante una parada de tránsito, debe decírselo al agente, y no debe tratar de tomar el arma.","p":"Correcto. Avísele al agente y mantenga las manos lejos del arma."},"ref":{"doc":"NC","page":50}},{"id":"nc-185","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, farm equipment must have a red light on the back that can be seen from 500 feet. What may be used instead of that red light?","o":["One white light","A small orange flag","Nothing; no rear light or reflector is needed","Two red reflectors, each at least 4 inches across"],"h1":"They are red and must be a certain size.","h2":"In North Carolina, farm equipment needs a white light in front and a red light in back visible up to 500 feet; two red reflectors at least four inches in diameter may replace the rear red light.","p":"Right. Two red reflectors, at least 4 inches across, may replace it."},"es":{"q":"En Carolina del Norte, la maquinaria agrícola debe tener una luz roja atrás que se vea a 500 pies. ¿Qué se puede usar en lugar de esa luz roja?","o":["Una luz blanca","Una banderita anaranjada","Nada; no se necesita luz ni reflector atrás","Dos reflectores rojos, cada uno de al menos 4 pulgadas de diámetro"],"h1":"Son rojos y deben tener cierto tamaño.","h2":"En Carolina del Norte, la maquinaria agrícola necesita una luz blanca adelante y una luz roja atrás visible hasta 500 pies; dos reflectores rojos de al menos cuatro pulgadas de diámetro pueden reemplazar la luz roja trasera.","p":"Correcto. Dos reflectores rojos de al menos 4 pulgadas pueden reemplazarla."},"ref":{"doc":"NC","page":51}},{"id":"nc-186","scope":"NC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Carolina, outside city limits, how close to a fire or a fire truck may you park?","o":["No closer than 15 feet","No closer than 400 feet","No closer than 100 feet","No closer than 1 mile"],"h1":"Inside a city the rule is one block; outside, it is given in feet.","h2":"In North Carolina, you may not park within 400 feet of a fire or fire truck outside city limits (within one block inside city limits).","p":"Right. Outside the city, stay at least 400 feet away."},"es":{"q":"En Carolina del Norte, fuera de los límites de la ciudad, ¿qué tan cerca de un incendio o de un camión de bomberos puede estacionarse?","o":["A no menos de 15 pies","A no menos de 400 pies","A no menos de 100 pies","A no menos de 1 milla"],"h1":"Dentro de la ciudad la regla es una cuadra; fuera, se da en pies.","h2":"En Carolina del Norte, no puede estacionarse a menos de 400 pies de un incendio o camión de bomberos fuera de los límites de la ciudad (a menos de una cuadra dentro de la ciudad).","p":"Correcto. Fuera de la ciudad, quédese al menos a 400 pies."},"ref":{"doc":"NC","page":56}},{"id":"nc-187","scope":"NC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Carolina, you stop to help injured people at a crash. Does the law protect you from being sued for helping?","o":["No, helpers can always be sued","Yes, unless you do something wrong on purpose or act in an unruly way","Only if you are a doctor or nurse","Only if you are a police officer"],"h1":"The law wants people to stop and help.","h2":"In North Carolina, the law protects people who stop and give aid at a crash from civil liability, except for intentional wrongdoing or unruly conduct.","p":"Right. Helpers are protected unless they do wrong on purpose."},"es":{"q":"En Carolina del Norte, usted se detiene a ayudar a personas heridas en un choque. ¿La ley lo protege de una demanda por ayudar?","o":["No, a quien ayuda siempre lo pueden demandar","Sí, a menos que haga algo malo a propósito o actúe de forma descontrolada","Solo si es médico o enfermera","Solo si es policía"],"h1":"La ley quiere que la gente se detenga a ayudar.","h2":"En Carolina del Norte, la ley protege de responsabilidad civil a las personas que se detienen a dar ayuda en un choque, excepto por daño intencional o conducta descontrolada.","p":"Correcto. Quien ayuda está protegido salvo que haga mal a propósito."},"ref":{"doc":"NC","page":77}},{"id":"nc-188","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, your car breaks down on the interstate and you need help. What does the handbook say to do?","o":["Stay in the travel lane with the doors locked","Walk across the lanes to wave down a driver","Fix the car where it stopped","Move far off the road, tie a white cloth to the antenna or left door handle, and raise the hood"],"h1":"Two signs on the car tell others you need help.","h2":"In North Carolina, if a breakdown forces you to stop, move far off the road, tie a white cloth on the radio antenna or left door handle, and raise the hood.","p":"Right. A white cloth and a raised hood signal that you need help."},"es":{"q":"En Carolina del Norte, su carro se descompone en la autopista interestatal y necesita ayuda. ¿Qué dice el manual que haga?","o":["Quedarse en el carril de tráfico con las puertas cerradas con seguro","Cruzar los carriles a pie para pedir ayuda a un conductor","Reparar el carro donde se paró","Salir bien lejos de la vía, atar un trapo blanco a la antena o a la manija de la puerta izquierda, y levantar el capó"],"h1":"Dos señales en el carro les dicen a los demás que usted necesita ayuda.","h2":"En Carolina del Norte, si una falla lo obliga a detenerse, salga bien lejos de la vía, ate un trapo blanco a la antena del radio o a la manija de la puerta izquierda, y levante el capó.","p":"Correcto. Un trapo blanco y el capó levantado indican que necesita ayuda."},"ref":{"doc":"NC","page":64}},{"id":"nc-189","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, with your low-beam headlights on at night, about how far away should you be able to see a person?","o":["75 feet","25 feet","200 feet","500 feet"],"h1":"It is much shorter than with high beams, which reach 200 feet.","h2":"In North Carolina, with low-beam headlights you should be able to see a person about 75 feet away.","p":"Right. Low beams should show a person at 75 feet."},"es":{"q":"En Carolina del Norte, con las luces bajas encendidas de noche, ¿a qué distancia más o menos debe poder ver a una persona?","o":["75 pies","25 pies","200 pies","500 pies"],"h1":"Es mucho menos que con las luces altas, que llegan a 200 pies.","h2":"En Carolina del Norte, con las luces bajas usted debe poder ver a una persona a unos 75 pies.","p":"Correcto. Las luces bajas deben mostrar a una persona a 75 pies."},"ref":{"doc":"NC","page":65}},{"id":"nc-190","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, what color must taillights be, and how far away must they be seen?","o":["Red, seen from at least 50 feet","Amber, seen from at least 500 feet","Red, seen from at least 500 feet","White, seen from at least 200 feet"],"h1":"The color means stop; the distance is the longest choice.","h2":"In North Carolina, taillights must be red and visible for at least 500 feet.","p":"Right. Taillights must be red and seen from 500 feet."},"es":{"q":"En Carolina del Norte, ¿de qué color deben ser las luces traseras y a qué distancia se deben ver?","o":["Rojas, visibles a por lo menos 50 pies","Ámbar, visibles a por lo menos 500 pies","Rojas, visibles a por lo menos 500 pies","Blancas, visibles a por lo menos 200 pies"],"h1":"El color significa alto; la distancia es la opción más larga.","h2":"En Carolina del Norte, las luces traseras deben ser rojas y verse a por lo menos 500 pies.","p":"Correcto. Las luces traseras deben ser rojas y verse a 500 pies."},"ref":{"doc":"NC","page":65}},{"id":"nc-191","scope":"NC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Carolina, when is a tire considered unsafe because of its tread?","o":["When the tread is less than 1/2 inch deep","When the tire is more than one year old","When the tread is less than 1/16 inch deep","Only when the tire is flat"],"h1":"It is a very small fraction of an inch.","h2":"In North Carolina, a tire is unsafe if its tread depth is less than 1/16 inch, or if it is cut or worn so the cord shows.","p":"Right. Less than 1/16 inch of tread is unsafe."},"es":{"q":"En Carolina del Norte, ¿cuándo se considera que una llanta no es segura por su banda de rodamiento (tread)?","o":["Cuando la banda tiene menos de 1/2 pulgada de profundidad","Cuando la llanta tiene más de un año","Cuando la banda tiene menos de 1/16 de pulgada de profundidad","Solo cuando la llanta está ponchada"],"h1":"Es una fracción muy pequeña de pulgada.","h2":"En Carolina del Norte, una llanta no es segura si su banda tiene menos de 1/16 de pulgada de profundidad, o si está cortada o gastada de modo que se ven las cuerdas.","p":"Correcto. Menos de 1/16 de pulgada de banda no es seguro."},"ref":{"doc":"NC","page":66}},{"id":"nc-192","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, how far away must your car horn be heard?","o":["At least 200 feet","At least 20 feet","At least 1,000 feet","At least one mile"],"h1":"It is the same distance your high beams should show a person.","h2":"In North Carolina, every motor vehicle must have a working horn that can be heard for at least 200 feet, without an unreasonably loud or harsh sound.","p":"Right. The horn must be heard from at least 200 feet."},"es":{"q":"En Carolina del Norte, ¿a qué distancia se debe oír la bocina de su carro?","o":["A por lo menos 200 pies","A por lo menos 20 pies","A por lo menos 1,000 pies","A por lo menos una milla"],"h1":"Es la misma distancia a la que las luces altas deben mostrar a una persona.","h2":"En Carolina del Norte, todo vehículo debe tener una bocina que funcione y que se oiga a por lo menos 200 pies, sin un sonido demasiado fuerte o áspero.","p":"Correcto. La bocina se debe oír a por lo menos 200 pies."},"ref":{"doc":"NC","page":67}},{"id":"nc-193","scope":"NC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Carolina, a bicycle is ridden at night. What must it have on the back?","o":["A white light seen from at least 50 feet","An orange flag","Nothing, if the front light is on","A red light or red reflector seen from at least 200 feet"],"h1":"The front needs a light; the back needs something red.","h2":"In North Carolina, a bicycle ridden at night must have a red light or reflector on the rear that can be seen from at least 200 feet.","p":"Right. A red rear light or reflector, seen from 200 feet."},"es":{"q":"En Carolina del Norte, se usa una bicicleta de noche. ¿Qué debe tener atrás?","o":["Una luz blanca visible a por lo menos 50 pies","Una bandera anaranjada","Nada, si la luz delantera está encendida","Una luz roja o un reflector rojo visible a por lo menos 200 pies"],"h1":"Adelante necesita una luz; atrás necesita algo rojo.","h2":"En Carolina del Norte, una bicicleta que se usa de noche debe tener atrás una luz roja o un reflector rojo visible a por lo menos 200 pies.","p":"Correcto. Una luz o reflector rojo atrás, visible a 200 pies."},"ref":{"doc":"NC","page":90}},{"id":"nc-194","scope":"NC","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Carolina, the DMV learns that a car owner drove without liability insurance. What can happen to the license plate?","o":["Nothing; only the driver license is affected","It can be revoked for 30 days unless the owner proves continuous coverage","It is painted a different color","It is taken for 10 years"],"h1":"The plate is tied to having insurance.","h2":"In North Carolina, if the DMV is told an owner drove without proper liability insurance, the vehicle's plate can be revoked for 30 days unless proof of continuous coverage is given.","p":"Right. The plate can be revoked for 30 days."},"es":{"q":"En Carolina del Norte, el DMV se entera de que el dueño de un carro manejó sin seguro de responsabilidad civil. ¿Qué puede pasar con la placa?","o":["Nada; solo se afecta la licencia de manejar","Se puede revocar por 30 días, a menos que el dueño pruebe que tuvo seguro sin interrupción","Se pinta de otro color","Se la quitan por 10 años"],"h1":"La placa está ligada a tener seguro.","h2":"En Carolina del Norte, si le informan al DMV que un dueño manejó sin el seguro de responsabilidad civil requerido, la placa del vehículo se puede revocar por 30 días, a menos que se pruebe que el seguro no tuvo interrupción.","p":"Correcto. La placa se puede revocar por 30 días."},"ref":{"doc":"NC","page":99}},{"id":"nc-195","scope":"NC","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Carolina, may you put a clear plastic cover over your license plate?","o":["Yes, if it is clear","Yes, but only on the front plate","Yes, if it has a dealer logo","No, plastic license plate covers are not allowed"],"h1":"The law bans them outright.","h2":"In North Carolina, plastic license plate covers are prohibited.","p":"Right. Plastic plate covers are not allowed."},"es":{"q":"En Carolina del Norte, ¿puede poner una cubierta de plástico transparente sobre su placa?","o":["Sí, si es transparente","Sí, pero solo en la placa de adelante","Sí, si tiene el logotipo del concesionario","No, las cubiertas de plástico para placas no están permitidas"],"h1":"La ley las prohíbe del todo.","h2":"En Carolina del Norte, las cubiertas de plástico para placas están prohibidas.","p":"Correcto. Las cubiertas de plástico para placas no se permiten."},"ref":{"doc":"NC","page":97}},{"id":"nc-196","scope":"NC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Carolina, how dark may after-factory window tint be?","o":["It must let at least 35% of light through","It must let at least 5% of light through","It must let at least 70% of light through","Any darkness is allowed"],"h1":"The number is a little more than one-third.","h2":"In North Carolina, tinted windows must let through no less than 35% of the light.","p":"Right. Tint must let through at least 35% of light."},"es":{"q":"En Carolina del Norte, ¿qué tan oscuro puede ser el polarizado de ventanas puesto después de fábrica?","o":["Debe dejar pasar al menos el 35% de la luz","Debe dejar pasar al menos el 5% de la luz","Debe dejar pasar al menos el 70% de la luz","Se permite cualquier oscuridad"],"h1":"El número es un poco más de un tercio.","h2":"En Carolina del Norte, las ventanas polarizadas deben dejar pasar no menos del 35% de la luz.","p":"Correcto. El polarizado debe dejar pasar al menos el 35% de la luz."},"ref":{"doc":"NC","page":102}},{"id":"nd-001","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"North Dakota lets teens start younger than most states.","h2":"In North Dakota you can get an instruction permit at 14 years old.","p":"Right. North Dakota permits start at 14."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Dakota del Norte deja empezar más joven que la mayoría de los estados.","h2":"En Dakota del Norte usted puede obtener un permiso de instrucción a los 14 años.","p":"Correcto. El permiso en Dakota del Norte empieza a los 14."},"zh":{"q":"在 North Dakota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"North Dakota 让青少年比大多数州更早开始。","h2":"在 North Dakota，你 14 岁就可以拿到学习驾照。","p":"对。North Dakota 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở North Dakota, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"North Dakota cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang.","h2":"Ở North Dakota, bạn có thể được cấp giấy phép tập lái khi đủ 14 tuổi.","p":"Đúng. Ở North Dakota, giấy phép tập lái bắt đầu từ 14 tuổi."},"tl":{"q":"Sa North Dakota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas maaga pinapayagang magsimula ng North Dakota ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa North Dakota, makakakuha ka ng instruction permit sa edad na 14.","p":"Tama. Sa North Dakota, nagsisimula ang permit sa edad na 14."},"ar":{"q":"في North Dakota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تسمح North Dakota للمراهقين بالبدء في عمر أصغر من معظم الولايات.","h2":"في North Dakota يمكنك الحصول على تصريح التعلّم في عمر 14 سنة.","p":"صحيح. يبدأ التصريح في North Dakota من عمر 14 سنة."},"ref":{"doc":"ND","page":3}},{"id":"nd-004","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how old must the licensed adult with a permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"It is the age when a person becomes a legal adult.","h2":"A North Dakota permit holder must drive with a licensed adult who is at least 18 years old.","p":"Right. The adult with you must be 18 or older."},"es":{"q":"En Dakota del Norte, ¿qué edad debe tener el adulto con licencia que acompaña a quien tiene permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Es la edad en que una persona se vuelve adulta ante la ley.","h2":"Quien tiene un permiso en Dakota del Norte debe manejar con un adulto con licencia de por lo menos 18 años.","p":"Correcto. El adulto que lo acompaña debe tener 18 años o más."},"zh":{"q":"在 North Dakota，陪同持学习驾照的人、有驾照的成年人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"这是一个人在法律上成年的年龄。","h2":"North Dakota 持学习驾照的人必须和至少 18 岁、有驾照的成年人一起开车。","p":"对。陪你的成年人必须 18 岁或以上。"},"vi":{"q":"Ở North Dakota, người lớn có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Đó là tuổi một người trở thành người lớn theo luật.","h2":"Ở North Dakota, người có giấy phép tập lái phải lái xe cùng một người lớn có bằng lái, ít nhất 18 tuổi.","p":"Đúng. Người lớn đi cùng bạn phải từ 18 tuổi trở lên."},"tl":{"q":"Sa North Dakota, ilang taon dapat ang adult na may lisensya na kasama ng may hawak ng permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ito ang edad kung kailan nagiging adult ang isang tao ayon sa batas.","h2":"Sa North Dakota, ang may hawak ng permit ay dapat magmaneho kasama ang isang adult na may lisensya na hindi bababa sa 18 taong gulang.","p":"Tama. Ang adult na kasama mo ay dapat 18 o mas matanda."},"ar":{"q":"في North Dakota، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ويرافق حامل التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"إنه العمر الذي يصبح فيه الشخص بالغاً حسب القانون.","h2":"في North Dakota يجب أن يقود حامل التصريح مع شخص بالغ يحمل رخصة وعمره 18 سنة على الأقل.","p":"صحيح. يجب أن يكون البالغ المرافق لك عمره 18 سنة أو أكثر."},"ref":{"doc":"ND","page":3}},{"id":"nd-005","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how much driving experience must the adult supervising a permit holder have?","o":["None","6 months","1 year","At least 3 years"],"h1":"It is more than a couple of years.","h2":"The adult supervising a North Dakota permit holder must have at least three years of driving experience.","p":"Right. The helper needs three years of experience."},"es":{"q":"En Dakota del Norte, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a quien tiene permiso?","o":["Ninguna","6 meses","1 año","Por lo menos 3 años"],"h1":"Es más de un par de años.","h2":"El adulto que supervisa a quien tiene permiso en Dakota del Norte debe tener por lo menos tres años de experiencia manejando.","p":"Correcto. El acompañante necesita tres años de experiencia."},"zh":{"q":"在 North Dakota，陪同持学习驾照的人的成年人必须有多少开车经验？","o":["不需要","6 个月","1 年","至少 3 年"],"h1":"比两年多一点。","h2":"陪同 North Dakota 持学习驾照的人的成年人必须有至少三年的开车经验。","p":"对。陪同的人需要三年的经验。"},"vi":{"q":"Ở North Dakota, người lớn giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Không cần","6 tháng","1 năm","Ít nhất 3 năm"],"h1":"Nhiều hơn vài năm.","h2":"Ở North Dakota, người lớn giám sát người có giấy phép tập lái phải có ít nhất ba năm kinh nghiệm lái xe.","p":"Đúng. Người đi cùng cần có ba năm kinh nghiệm."},"tl":{"q":"Sa North Dakota, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang adult na nagbabantay sa may hawak ng permit?","o":["Wala","6 na buwan","1 taon","Hindi bababa sa 3 taon"],"h1":"Higit ito sa dalawang taon.","h2":"Sa North Dakota, ang adult na nagbabantay sa may hawak ng permit ay dapat may hindi bababa sa tatlong taon na karanasan sa pagmamaneho.","p":"Tama. Kailangan ng kasama ang tatlong taon na karanasan."},"ar":{"q":"في North Dakota، ما مقدار خبرة القيادة التي يجب أن تكون لدى البالغ الذي يشرف على حامل التصريح؟","o":["لا شيء","6 أشهر","سنة واحدة","3 سنوات على الأقل"],"h1":"إنها أكثر من سنتين.","h2":"في North Dakota يجب أن تكون لدى البالغ الذي يشرف على حامل التصريح خبرة قيادة لا تقل عن ثلاث سنوات.","p":"صحيح. يحتاج المرافق إلى خبرة ثلاث سنوات."},"ref":{"doc":"ND","page":3}},{"id":"nd-006","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a teen gets an instruction permit at 14. How long must they hold it before the road test?","o":["30 days","3 months","1 year","2 years"],"h1":"It is a full trip around the calendar.","h2":"A 14-year-old in North Dakota must hold the instruction permit for 12 months, which is one year, before the road test.","p":"Right. At 14, you hold the permit for one year."},"es":{"q":"En Dakota del Norte, un adolescente obtiene el permiso de instrucción a los 14 años. ¿Cuánto tiempo debe tenerlo antes del examen de manejo?","o":["30 días","3 meses","1 año","2 años"],"h1":"Es una vuelta completa al calendario.","h2":"Un joven de 14 años en Dakota del Norte debe tener el permiso de instrucción por 12 meses, es decir un año, antes del examen de manejo.","p":"Correcto. A los 14, tiene el permiso por un año."},"zh":{"q":"在 North Dakota，一个青少年 14 岁拿到学习驾照。他必须持有多久才能路考？","o":["30 天","3 个月","1 年","2 年"],"h1":"是日历上完整的一圈。","h2":"North Dakota 14 岁的人必须持有学习驾照 12 个月，也就是一年，才能路考。","p":"对。14 岁时，学习驾照要持有一年。"},"vi":{"q":"Ở North Dakota, một thiếu niên được cấp giấy phép tập lái khi 14 tuổi. Người đó phải giữ giấy phép bao lâu trước khi thi lái xe trên đường?","o":["30 ngày","3 tháng","1 năm","2 năm"],"h1":"Đó là trọn một vòng lịch.","h2":"Ở North Dakota, người 14 tuổi phải giữ giấy phép tập lái 12 tháng, tức là một năm, trước khi thi lái xe trên đường.","p":"Đúng. Khi 14 tuổi, bạn giữ giấy phép trong một năm."},"tl":{"q":"Sa North Dakota, nakakuha ng instruction permit ang isang kabataan sa edad na 14. Gaano katagal niya ito dapat hawak bago ang road test?","o":["30 araw","3 buwan","1 taon","2 taon"],"h1":"Ito ay isang buong ikot ng kalendaryo.","h2":"Sa North Dakota, ang 14 taong gulang ay dapat humawak ng instruction permit nang 12 buwan, o isang taon, bago ang road test.","p":"Tama. Sa edad na 14, hawak mo ang permit nang isang taon."},"ar":{"q":"في North Dakota، حصل مراهق على تصريح التعلّم في عمر 14 سنة. كم مدة يجب أن يحمله قبل اختبار القيادة على الطريق؟","o":["30 يوماً","3 أشهر","سنة واحدة","سنتان"],"h1":"إنها دورة كاملة في التقويم.","h2":"في North Dakota يجب على من عمره 14 سنة أن يحمل تصريح التعلّم 12 شهراً، أي سنة واحدة، قبل اختبار القيادة على الطريق.","p":"صحيح. في عمر 14 سنة تحمل التصريح لمدة سنة واحدة."},"ref":{"doc":"ND","page":3}},{"id":"nd-007","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, how long must a 16-year-old hold an instruction permit before a license?","o":["6 months","1 month","1 year","18 months"],"h1":"It is half as long as the rule for younger teens.","h2":"A 16-year-old in North Dakota must hold the instruction permit for six months before getting a license.","p":"Right. At 16, the wait is six months."},"es":{"q":"En Dakota del Norte, ¿cuánto tiempo debe tener el permiso de instrucción una persona de 16 años antes de la licencia?","o":["6 meses","1 mes","1 año","18 meses"],"h1":"Es la mitad del tiempo que deben esperar los más jóvenes.","h2":"Una persona de 16 años en Dakota del Norte debe tener el permiso de instrucción seis meses antes de obtener la licencia.","p":"Correcto. A los 16, la espera es de seis meses."},"zh":{"q":"在 North Dakota，16 岁的人必须持有学习驾照多久才能拿驾照？","o":["6 个月","1 个月","1 年","18 个月"],"h1":"它是年龄小一点的青少年规定时间的一半。","h2":"North Dakota 16 岁的人必须持有学习驾照六个月，才能拿到驾照。","p":"对。16 岁时，要等六个月。"},"vi":{"q":"Ở North Dakota, người 16 tuổi phải giữ giấy phép tập lái bao lâu trước khi được cấp bằng lái?","o":["6 tháng","1 tháng","1 năm","18 tháng"],"h1":"Chỉ bằng một nửa thời gian quy định cho thiếu niên nhỏ tuổi hơn.","h2":"Ở North Dakota, người 16 tuổi phải giữ giấy phép tập lái sáu tháng trước khi được cấp bằng lái.","p":"Đúng. Khi 16 tuổi, thời gian chờ là sáu tháng."},"tl":{"q":"Sa North Dakota, gaano katagal dapat hawak ng 16 taong gulang ang instruction permit bago makakuha ng lisensya?","o":["6 na buwan","1 buwan","1 taon","18 buwan"],"h1":"Kalahati ito ng haba ng patakaran para sa mas batang kabataan.","h2":"Sa North Dakota, ang 16 taong gulang ay dapat humawak ng instruction permit nang anim na buwan bago makakuha ng lisensya.","p":"Tama. Sa edad na 16, anim na buwan ang paghihintay."},"ar":{"q":"في North Dakota، كم مدة يجب أن يحمل من عمره 16 سنة تصريح التعلّم قبل الحصول على رخصة القيادة؟","o":["6 أشهر","شهر واحد","سنة واحدة","18 شهراً"],"h1":"إنها نصف المدة المطلوبة من المراهقين الأصغر سناً.","h2":"في North Dakota يجب على من عمره 16 سنة أن يحمل تصريح التعلّم ستة أشهر قبل الحصول على رخصة القيادة.","p":"صحيح. في عمر 16 سنة، الانتظار ستة أشهر."},"ref":{"doc":"ND","page":3}},{"id":"nd-008","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how many hours of supervised driving must a permit holder under 16 complete?","o":["10 hours","20 hours","100 hours","50 hours"],"h1":"It is half of one hundred.","h2":"A North Dakota permit holder under 16 must complete at least 50 hours of supervised practice driving.","p":"Right. Under 16, you need 50 hours."},"es":{"q":"En Dakota del Norte, ¿cuántas horas de manejo supervisado debe completar un joven con permiso menor de 16 años?","o":["10 horas","20 horas","100 horas","50 horas"],"h1":"Es la mitad de cien.","h2":"Un joven con permiso menor de 16 años en Dakota del Norte debe completar por lo menos 50 horas de práctica de manejo supervisado.","p":"Correcto. Menor de 16, necesita 50 horas."},"zh":{"q":"在 North Dakota，16 岁以下持学习驾照的人必须完成多少小时有人监督的驾驶？","o":["10 小时","20 小时","100 小时","50 小时"],"h1":"是一百的一半。","h2":"North Dakota 16 岁以下持学习驾照的人必须完成至少 50 小时有人监督的练习驾驶。","p":"对。16 岁以下，你需要 50 小时。"},"vi":{"q":"Ở North Dakota, người có giấy phép tập lái dưới 16 tuổi phải lái xe có giám sát bao nhiêu giờ?","o":["10 giờ","20 giờ","100 giờ","50 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở North Dakota, người có giấy phép tập lái dưới 16 tuổi phải lái xe tập có giám sát ít nhất 50 giờ.","p":"Đúng. Dưới 16 tuổi, bạn cần 50 giờ."},"tl":{"q":"Sa North Dakota, ilang oras ng pagmamaneho na may bantay ang dapat tapusin ng may hawak ng permit na wala pang 16?","o":["10 oras","20 oras","100 oras","50 oras"],"h1":"Ito ay kalahati ng isang daan.","h2":"Sa North Dakota, ang may hawak ng permit na wala pang 16 ay dapat tumapos ng hindi bababa sa 50 oras ng pagsasanay sa pagmamaneho na may bantay.","p":"Tama. Kung wala ka pang 16, kailangan mo ng 50 oras."},"ar":{"q":"في North Dakota، كم ساعة من القيادة تحت الإشراف يجب أن يكملها حامل التصريح الذي عمره أقل من 16 سنة؟","o":["10 ساعات","20 ساعة","100 ساعة","50 ساعة"],"h1":"إنها نصف المئة.","h2":"في North Dakota يجب على حامل التصريح الذي عمره أقل من 16 سنة أن يكمل 50 ساعة على الأقل من التدريب على القيادة تحت الإشراف.","p":"صحيح. إذا كان عمرك أقل من 16 سنة، تحتاج إلى 50 ساعة."},"ref":{"doc":"ND","page":3}},{"id":"nd-009","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the youngest age to get a restricted license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the permit age of 14.","h2":"In North Dakota the restricted license is available from age 15.","p":"Right. The restricted license starts at 15."},"es":{"q":"En Dakota del Norte, ¿cuál es la edad mínima para obtener una licencia restringida?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso, que es 14.","h2":"En Dakota del Norte la licencia restringida se puede obtener desde los 15 años.","p":"Correcto. La licencia restringida empieza a los 15."},"zh":{"q":"在 North Dakota，最小几岁可以拿到限制驾照（restricted license）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比 14 岁的学习驾照年龄晚一年。","h2":"在 North Dakota，从 15 岁起可以拿到限制驾照。","p":"对。限制驾照从 15 岁开始。"},"vi":{"q":"Ở North Dakota, tuổi nhỏ nhất để được cấp bằng lái hạn chế (restricted license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm sau tuổi được cấp giấy phép tập lái là 14.","h2":"Ở North Dakota, bằng lái hạn chế được cấp từ 15 tuổi.","p":"Đúng. Bằng lái hạn chế bắt đầu từ 15 tuổi."},"tl":{"q":"Sa North Dakota, ano ang pinakabatang edad para makakuha ng restricted license (lisensyang may limitasyon)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad ng permit na 14.","h2":"Sa North Dakota, makukuha ang restricted license simula sa edad na 15.","p":"Tama. Nagsisimula ang restricted license sa edad na 15."},"ar":{"q":"في North Dakota، ما أصغر عمر للحصول على رخصة القيادة المقيّدة (restricted license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه بعد سنة واحدة من عمر التصريح وهو 14 سنة.","h2":"في North Dakota تتوفر رخصة القيادة المقيّدة من عمر 15 سنة.","p":"صحيح. تبدأ الرخصة المقيّدة من عمر 15 سنة."},"ref":{"doc":"ND","page":6}},{"id":"nd-010","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, when may a 15-year-old with a restricted license not drive without a parent, guardian or adult 18 or older?","o":["From 6 p.m. to 6 a.m.","From midnight to 4 a.m.","From 9 p.m., or sunset if later, until 5 a.m.","On weekends"],"h1":"The limit starts in the evening, earlier than midnight.","h2":"A 15-year-old with a North Dakota restricted license may not drive from 9 p.m., or sunset if that is later, until 5 a.m. without a parent, guardian or adult 18 or older, except straight to or from work, school activities or religious activities.","p":"Right. No driving alone from 9 p.m., or sunset if later, until 5 a.m."},"es":{"q":"En Dakota del Norte, ¿cuándo no puede manejar un joven de 15 años con licencia restringida sin su padre, madre, tutor o un adulto de 18 años o más?","o":["De 6 p.m. a 6 a.m.","De medianoche a 4 a.m.","Desde las 9 p.m., o la puesta del sol si es más tarde, hasta las 5 a.m.","Los fines de semana"],"h1":"El límite empieza en la noche, antes de la medianoche.","h2":"Un joven de 15 años con licencia restringida en Dakota del Norte no puede manejar desde las 9 p.m., o la puesta del sol si es más tarde, hasta las 5 a.m. sin su padre, madre, tutor o un adulto de 18 años o más, salvo para ir directo al trabajo, a actividades escolares o religiosas, o volver de ellos.","p":"Correcto. No maneja solo desde las 9 p.m., o la puesta del sol si es más tarde, hasta las 5 a.m."},"zh":{"q":"在 North Dakota，15 岁持限制驾照的人在什么时间不能在没有父母、监护人或 18 岁以上成年人陪同的情况下开车？","o":["晚上 6 点到早上 6 点","午夜到早上 4 点","从晚上 9 点（如果日落更晚，就从日落）到早上 5 点","周末"],"h1":"限制从晚上开始，比午夜早。","h2":"在 North Dakota，15 岁持限制驾照的人从晚上 9 点（如果日落更晚，就从日落）到早上 5 点，没有父母、监护人或 18 岁以上成年人陪同时不能开车，但直接去上班、学校活动或宗教活动或从那里回来除外。","p":"对。从晚上 9 点（如果日落更晚，就从日落）到早上 5 点不能独自开车。"},"vi":{"q":"Ở North Dakota, khi nào người 15 tuổi có bằng lái hạn chế không được lái xe nếu không có cha mẹ, người giám hộ hoặc người lớn từ 18 tuổi trở lên đi cùng?","o":["Từ 6 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng","Từ 9 giờ tối, hoặc từ lúc mặt trời lặn nếu muộn hơn, đến 5 giờ sáng","Vào cuối tuần"],"h1":"Giới hạn bắt đầu vào buổi tối, sớm hơn nửa đêm.","h2":"Ở North Dakota, người 15 tuổi có bằng lái hạn chế không được lái xe từ 9 giờ tối, hoặc từ lúc mặt trời lặn nếu muộn hơn, đến 5 giờ sáng nếu không có cha mẹ, người giám hộ hoặc người lớn từ 18 tuổi trở lên đi cùng, trừ khi đi thẳng đến hoặc về từ nơi làm việc, hoạt động của trường hoặc hoạt động tôn giáo.","p":"Đúng. Không được lái xe một mình từ 9 giờ tối, hoặc từ lúc mặt trời lặn nếu muộn hơn, đến 5 giờ sáng."},"tl":{"q":"Sa North Dakota, kailan hindi puwedeng magmaneho ang 15 taong gulang na may restricted license kung walang kasamang magulang, guardian o adult na 18 taong gulang pataas?","o":["Mula 6 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m.","Mula 9 p.m., o paglubog ng araw kung mas huli ito, hanggang 5 a.m.","Tuwing weekend"],"h1":"Nagsisimula ang limitasyon sa gabi, mas maaga sa hatinggabi.","h2":"Sa North Dakota, ang 15 taong gulang na may restricted license ay hindi puwedeng magmaneho mula 9 p.m., o paglubog ng araw kung mas huli ito, hanggang 5 a.m. kung walang kasamang magulang, guardian o adult na 18 taong gulang pataas, maliban kung diretso papunta o pauwi mula sa trabaho, mga aktibidad sa paaralan o mga aktibidad panrelihiyon.","p":"Tama. Bawal magmanehong mag-isa mula 9 p.m., o paglubog ng araw kung mas huli ito, hanggang 5 a.m."},"ar":{"q":"في North Dakota، متى لا يجوز لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود دون أحد الوالدين أو الوصي أو شخص بالغ عمره 18 سنة أو أكثر؟","o":["من 6 مساءً إلى 6 صباحًا","من منتصف الليل إلى 4 صباحًا","من 9 مساءً، أو من غروب الشمس إذا كان بعد ذلك، حتى 5 صباحًا","في عطلة نهاية الأسبوع"],"h1":"يبدأ المنع في المساء، قبل منتصف الليل.","h2":"في North Dakota لا يجوز لمن عمره 15 سنة ويحمل رخصة مقيّدة أن يقود من 9 مساءً، أو من غروب الشمس إذا كان بعد ذلك، حتى 5 صباحًا دون أحد الوالدين أو الوصي أو شخص بالغ عمره 18 سنة أو أكثر، إلا إذا كان ذاهبًا مباشرة إلى العمل أو أنشطة المدرسة أو الأنشطة الدينية أو عائدًا منها مباشرة.","p":"صحيح. لا قيادة وحدك من 9 مساءً، أو من غروب الشمس إذا كان بعد ذلك، حتى 5 صباحًا."},"ref":{"doc":"ND","page":6}},{"id":"nd-011","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, whose car may a young driver with a restricted license drive?","o":["Only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle","Any car with insurance","A friend's car","A rental car"],"h1":"The car must belong to the teen's close family.","h2":"A young North Dakota driver with a restricted license may drive only a car that belongs to a parent, guardian, grandparent, brother, sister, aunt or uncle.","p":"Right. Only a car owned by close family."},"es":{"q":"En Dakota del Norte, ¿el carro de quién puede manejar un joven con licencia restringida?","o":["Solo un carro de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío","Cualquier carro con seguro","El carro de un amigo","Un carro alquilado"],"h1":"El carro debe ser de su familia cercana.","h2":"Un joven con licencia restringida en Dakota del Norte solo puede manejar un carro que sea de su padre, madre, tutor, abuelo, abuela, hermano, hermana, tía o tío.","p":"Correcto. Solo un carro de su familia cercana."},"zh":{"q":"在 North Dakota，持限制驾照的年轻司机可以开谁的车？","o":["只能开父母、监护人、祖父母、兄弟姐妹、阿姨姑姑或叔叔舅舅的车","任何有保险的车","朋友的车","租来的车"],"h1":"这辆车必须属于青少年的亲近家人。","h2":"North Dakota 持限制驾照的年轻司机只能开属于父母、监护人、祖父母、兄弟姐妹、阿姨姑姑或叔叔舅舅的车。","p":"对。只能开亲近家人的车。"},"vi":{"q":"Ở North Dakota, người lái xe trẻ có bằng lái hạn chế được lái xe của ai?","o":["Chỉ xe của cha mẹ, người giám hộ, ông bà, anh chị em, cô dì hoặc chú bác","Bất kỳ xe nào có bảo hiểm","Xe của bạn bè","Xe thuê"],"h1":"Xe phải thuộc về gia đình thân của thiếu niên.","h2":"Ở North Dakota, người lái xe trẻ có bằng lái hạn chế chỉ được lái xe của cha mẹ, người giám hộ, ông bà, anh chị em, cô dì hoặc chú bác.","p":"Đúng. Chỉ xe của gia đình thân."},"tl":{"q":"Sa North Dakota, kaninong kotse ang maaaring imaneho ng batang driver na may restricted license?","o":["Kotse lamang ng magulang, guardian, lolo o lola, kapatid na lalaki, kapatid na babae, tita o tito","Anumang kotse na may insurance","Kotse ng kaibigan","Inuupahang kotse"],"h1":"Ang kotse ay dapat pag-aari ng malapit na pamilya ng kabataan.","h2":"Sa North Dakota, ang batang driver na may restricted license ay maaari lamang magmaneho ng kotse na pag-aari ng magulang, guardian, lolo o lola, kapatid na lalaki, kapatid na babae, tita o tito.","p":"Tama. Kotse lamang ng malapit na pamilya."},"ar":{"q":"في North Dakota، سيارة مَن يجوز للسائق الصغير الذي يحمل رخصة مقيّدة أن يقودها؟","o":["فقط سيارة يملكها أحد الوالدين أو الوصي أو الجد أو الجدة أو الأخ أو الأخت أو العمة أو الخالة أو العم أو الخال","أي سيارة عليها تأمين","سيارة صديق","سيارة مستأجرة"],"h1":"يجب أن تكون السيارة ملكاً للعائلة القريبة للمراهق.","h2":"في North Dakota لا يجوز للسائق الصغير الذي يحمل رخصة مقيّدة أن يقود إلا سيارة يملكها أحد الوالدين أو الوصي أو الجد أو الجدة أو الأخ أو الأخت أو العمة أو الخالة أو العم أو الخال.","p":"صحيح. فقط سيارة تملكها العائلة القريبة."},"ref":{"doc":"ND","page":6}},{"id":"nd-012","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, may a driver under 18 use a cell phone while driving?","o":["No, drivers under 18 may not use any electronic communication device","Yes, for calls only","Yes, at red lights","Yes, if the call is short"],"h1":"Young drivers have a stricter rule than adults.","h2":"North Dakota law says drivers under 18 may not use any electronic communication device, including a cell phone, while driving.","p":"Right. Under 18, no phone while driving."},"es":{"q":"En Dakota del Norte, ¿puede un conductor menor de 18 usar el celular mientras maneja?","o":["No, los menores de 18 no pueden usar ningún aparato de comunicación electrónica","Sí, solo para llamadas","Sí, en los semáforos en rojo","Sí, si la llamada es corta"],"h1":"Los conductores jóvenes tienen una regla más estricta que los adultos.","h2":"La ley de Dakota del Norte dice que los conductores menores de 18 no pueden usar ningún aparato de comunicación electrónica, incluido el celular, mientras manejan.","p":"Correcto. Menor de 18, nada de teléfono al manejar."},"zh":{"q":"在 North Dakota，18 岁以下的司机开车时可以用手机吗？","o":["不可以，18 岁以下的司机不能使用任何电子通讯设备","可以，只能打电话","可以，在红灯时","可以，如果电话很短"],"h1":"年轻司机的规定比成年人更严格。","h2":"North Dakota 法律规定，18 岁以下的司机开车时不能使用任何电子通讯设备，包括手机。","p":"对。18 岁以下，开车时不能用手机。"},"vi":{"q":"Ở North Dakota, người lái xe dưới 18 tuổi có được dùng điện thoại di động khi lái xe không?","o":["Không, người lái xe dưới 18 tuổi không được dùng bất kỳ thiết bị liên lạc điện tử nào","Có, chỉ để gọi điện","Có, khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Người lái xe trẻ có quy định nghiêm hơn người lớn.","h2":"Luật North Dakota nói người lái xe dưới 18 tuổi không được dùng bất kỳ thiết bị liên lạc điện tử nào, kể cả điện thoại di động, khi lái xe.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại khi lái xe."},"tl":{"q":"Sa North Dakota, maaari bang gumamit ng cell phone habang nagmamaneho ang driver na wala pang 18?","o":["Hindi, ang mga driver na wala pang 18 ay hindi maaaring gumamit ng anumang electronic communication device","Oo, para sa tawag lamang","Oo, sa red light","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa mga adult.","h2":"Ayon sa batas ng North Dakota, ang mga driver na wala pang 18 ay hindi maaaring gumamit ng anumang electronic communication device, kasama ang cell phone, habang nagmamaneho.","p":"Tama. Kung wala ka pang 18, bawal ang phone habang nagmamaneho."},"ar":{"q":"في North Dakota، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة؟","o":["لا، لا يجوز للسائقين الذين عمرهم أقل من 18 سنة استخدام أي جهاز اتصال إلكتروني","نعم، للمكالمات فقط","نعم، عند الإشارة الحمراء","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين الصغار قاعدة أشد من البالغين.","h2":"يقول قانون North Dakota إن السائقين الذين عمرهم أقل من 18 سنة لا يجوز لهم استخدام أي جهاز اتصال إلكتروني، ومنه الهاتف المحمول، أثناء القيادة.","p":"صحيح. تحت 18 سنة، لا هاتف أثناء القيادة."},"ref":{"doc":"ND","page":6}},{"id":"nd-013","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, who is banned from texting while driving?","o":["Only drivers under 18","Only bus drivers","Only drivers with a permit","All drivers"],"h1":"The texting rule does not depend on age.","h2":"In North Dakota, text messaging while driving is banned for all drivers.","p":"Right. No one may text while driving."},"es":{"q":"En Dakota del Norte, ¿a quién se le prohíbe enviar mensajes de texto mientras maneja?","o":["Solo a los menores de 18","Solo a los choferes de autobús","Solo a quienes tienen permiso","A todos los conductores"],"h1":"La regla de los mensajes no depende de la edad.","h2":"En Dakota del Norte, enviar mensajes de texto mientras maneja está prohibido para todos los conductores.","p":"Correcto. Nadie puede enviar mensajes al manejar."},"zh":{"q":"在 North Dakota，谁开车时禁止发短信？","o":["只有 18 岁以下的司机","只有公共汽车司机","只有持学习驾照的司机","所有司机"],"h1":"发短信的规定和年龄无关。","h2":"在 North Dakota，所有司机开车时都禁止发短信。","p":"对。任何人开车时都不能发短信。"},"vi":{"q":"Ở North Dakota, ai bị cấm nhắn tin khi lái xe?","o":["Chỉ người lái xe dưới 18 tuổi","Chỉ tài xế xe buýt","Chỉ người có giấy phép tập lái","Tất cả người lái xe"],"h1":"Quy định về nhắn tin không phụ thuộc vào tuổi.","h2":"Ở North Dakota, tất cả người lái xe đều bị cấm nhắn tin khi lái xe.","p":"Đúng. Không ai được nhắn tin khi lái xe."},"tl":{"q":"Sa North Dakota, sino ang bawal mag-text habang nagmamaneho?","o":["Mga driver lamang na wala pang 18","Mga driver lamang ng bus","Mga driver lamang na may permit","Lahat ng driver"],"h1":"Hindi nakadepende sa edad ang patakaran sa pag-text.","h2":"Sa North Dakota, bawal sa lahat ng driver ang pag-text habang nagmamaneho.","p":"Tama. Walang sinuman ang maaaring mag-text habang nagmamaneho."},"ar":{"q":"في North Dakota، مَن الممنوع من كتابة الرسائل النصية أثناء القيادة؟","o":["فقط السائقون الذين عمرهم أقل من 18 سنة","فقط سائقو الحافلات","فقط السائقون الذين يحملون تصريحاً","جميع السائقين"],"h1":"قاعدة الرسائل النصية لا تعتمد على العمر.","h2":"في North Dakota كتابة الرسائل النصية أثناء القيادة ممنوعة على جميع السائقين.","p":"صحيح. لا يجوز لأحد كتابة الرسائل أثناء القيادة."},"ref":{"doc":"ND","page":30}},{"id":"nd-014","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, what is the fine for texting while driving?","o":["$20","$100","$500","$1,000"],"h1":"It is a round number in the hundreds.","h2":"The fine for texting while driving in North Dakota is $100.","p":"Right. The fine is $100."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por enviar mensajes de texto mientras maneja?","o":["$20","$100","$500","$1,000"],"h1":"Es un número redondo de cientos.","h2":"La multa por enviar mensajes de texto mientras maneja en Dakota del Norte es de $100.","p":"Correcto. La multa es de $100."},"zh":{"q":"在 North Dakota，开车时发短信的罚款是多少？","o":["$20","$100","$500","$1,000"],"h1":"这是几百里的一个整数。","h2":"在 North Dakota，开车时发短信的罚款是 $100。","p":"对。罚款是 $100。"},"vi":{"q":"Ở North Dakota, tiền phạt cho việc nhắn tin khi lái xe là bao nhiêu?","o":["$20","$100","$500","$1,000"],"h1":"Đó là một số tròn hàng trăm.","h2":"Ở North Dakota, tiền phạt cho việc nhắn tin khi lái xe là $100.","p":"Đúng. Tiền phạt là $100."},"tl":{"q":"Sa North Dakota, magkano ang multa sa pag-text habang nagmamaneho?","o":["$20","$100","$500","$1,000"],"h1":"Ito ay isang buong numero na nasa daan-daan.","h2":"Sa North Dakota, ang multa sa pag-text habang nagmamaneho ay $100.","p":"Tama. Ang multa ay $100."},"ar":{"q":"في North Dakota، كم غرامة كتابة الرسائل النصية أثناء القيادة؟","o":["$20","$100","$500","$1,000"],"h1":"إنه رقم مستدير بالمئات.","h2":"غرامة كتابة الرسائل النصية أثناء القيادة في North Dakota هي $100.","p":"صحيح. الغرامة $100."},"ref":{"doc":"ND","page":30}},{"id":"nd-015","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver under 21?","o":["0.08 percent","0.05 percent","0.02 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In North Dakota the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.08 por ciento","0.05 por ciento","0.02 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Dakota del Norte el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"zh":{"q":"在 North Dakota，21 岁以下司机的法定酒精限值是多少？","o":["0.08%","0.05%","0.02%","0.10%"],"h1":"它比成年人的限值低很多。","h2":"在 North Dakota，21 岁以下司机的酒精限值是 0.02%。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở North Dakota, giới hạn nồng độ cồn hợp pháp cho người lái xe dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.05 phần trăm","0.02 phần trăm","0.10 phần trăm"],"h1":"Thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở North Dakota, giới hạn nồng độ cồn cho người lái xe dưới 21 tuổi là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa North Dakota, ano ang legal na limitasyon ng alak para sa driver na wala pang 21?","o":["0.08 porsiyento","0.05 porsiyento","0.02 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adult.","h2":"Sa North Dakota, ang limitasyon ng alak para sa driver na wala pang 21 ay 0.02 porsiyento.","p":"Tama. Kung wala ka pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في North Dakota، ما الحد القانوني للكحول للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة","0.05 بالمئة","0.02 بالمئة","0.10 بالمئة"],"h1":"إنه أقل بكثير من حد البالغين.","h2":"في North Dakota حد الكحول للسائق الذي عمره أقل من 21 سنة هو 0.02 بالمئة.","p":"صحيح. تحت 21 سنة، الحد 0.02."},"ref":{"doc":"ND","page":36}},{"id":"nd-016","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the legal alcohol limit for a driver 21 or older?","o":["0.08 percent","0.02 percent","0.10 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In North Dakota the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.08 por ciento","0.02 por ciento","0.10 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Dakota del Norte el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 North Dakota，21 岁或以上司机的法定酒精限值是多少？","o":["0.08%","0.02%","0.10%","0.12%"],"h1":"它和大多数州用的限值一样。","h2":"在 North Dakota，21 岁或以上司机的酒精限值是 0.08%。","p":"对。成年人的限值是 0.08。"},"vi":{"q":"Ở North Dakota, giới hạn nồng độ cồn hợp pháp cho người lái xe từ 21 tuổi trở lên là bao nhiêu?","o":["0.08 phần trăm","0.02 phần trăm","0.10 phần trăm","0.12 phần trăm"],"h1":"Đó là cùng giới hạn được dùng ở hầu hết các tiểu bang.","h2":"Ở North Dakota, giới hạn nồng độ cồn cho người lái xe từ 21 tuổi trở lên là 0.08 phần trăm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa North Dakota, ano ang legal na limitasyon ng alak para sa driver na 21 o mas matanda?","o":["0.08 porsiyento","0.02 porsiyento","0.10 porsiyento","0.12 porsiyento"],"h1":"Ito ang parehong limitasyon na ginagamit sa karamihan ng estado.","h2":"Sa North Dakota, ang limitasyon ng alak para sa driver na 21 o mas matanda ay 0.08 porsiyento.","p":"Tama. Para sa mga adult, ang limitasyon ay 0.08."},"ar":{"q":"في North Dakota، ما الحد القانوني للكحول للسائق الذي عمره 21 سنة أو أكثر؟","o":["0.08 بالمئة","0.02 بالمئة","0.10 بالمئة","0.12 بالمئة"],"h1":"إنه نفس الحد المستخدم في معظم الولايات.","h2":"في North Dakota حد الكحول للسائق الذي عمره 21 سنة أو أكثر هو 0.08 بالمئة.","p":"صحيح. للبالغين، الحد 0.08."},"ref":{"doc":"ND","page":36}},{"id":"nd-017","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, on a multi-lane highway, what must you do when you pass a stopped vehicle with flashing lights?","o":["Honk to warn them","Stop behind it","Keep the same lane and speed","Change lanes if it is safe, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"North Dakota's move over law says to change to a lane away from the stopped vehicle if it is safe, and to slow down if you cannot change lanes.","p":"Right. Move over, or slow down."},"es":{"q":"En Dakota del Norte, en una carretera de varios carriles, ¿qué debe hacer al pasar un vehículo detenido con luces intermitentes?","o":["Tocar la bocina para avisar","Detenerse detrás de él","Seguir en el mismo carril y a la misma velocidad","Cambiarse de carril si es seguro, o bajar la velocidad si no puede"],"h1":"Dé más espacio a las personas en el acotamiento.","h2":"La ley de Dakota del Norte para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido si es seguro, y bajar la velocidad si no puede cambiarse.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 North Dakota，在多车道公路上，经过一辆停着、闪着灯的车时，你必须怎么做？","o":["按喇叭提醒他们","在它后面停车","保持同一条车道和速度","如果安全就换道，不能换道就减速"],"h1":"给路肩上的人更多空间。","h2":"North Dakota 的 move over 法规定，如果安全，要换到离停着的车远的车道；如果不能换道，就要减速。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở North Dakota, trên xa lộ nhiều làn, bạn phải làm gì khi chạy qua một xe đang dừng có đèn nhấp nháy?","o":["Bóp còi để cảnh báo họ","Dừng lại phía sau xe đó","Giữ nguyên làn và tốc độ","Đổi làn nếu an toàn, hoặc chạy chậm lại nếu không đổi làn được"],"h1":"Hãy chừa thêm chỗ cho những người ở lề đường.","h2":"Luật nhường làn (move over law) của North Dakota nói phải đổi sang làn xa xe đang dừng nếu an toàn, và chạy chậm lại nếu bạn không đổi làn được.","p":"Đúng. Nhường làn, hoặc chạy chậm lại."},"tl":{"q":"Sa North Dakota, sa highway na maraming lane, ano ang dapat mong gawin kapag dumaan ka sa nakahintong sasakyan na may kumikislap na ilaw?","o":["Bumusina para balaan sila","Huminto sa likod nito","Manatili sa parehong lane at bilis","Lumipat ng lane kung ligtas, o bumagal kung hindi ka makalipat"],"h1":"Bigyan ng mas maraming espasyo ang mga tao sa gilid ng daan.","h2":"Ayon sa move over law ng North Dakota, lumipat sa lane na malayo sa nakahintong sasakyan kung ligtas, at bumagal kung hindi ka makalipat ng lane.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في North Dakota، على طريق سريع متعدد المسارات، ماذا يجب أن تفعل عندما تمر بمركبة متوقفة أضواؤها تومض؟","o":["استخدم البوق لتحذيرهم","توقف خلفها","ابقَ في نفس المسار وبنفس السرعة","غيّر المسار إذا كان ذلك آمناً، أو خفّف السرعة إذا لم تستطع"],"h1":"أعطِ الأشخاص على جانب الطريق مساحة أكبر.","h2":"يقول قانون الابتعاد (move over law) في North Dakota أن تنتقل إلى مسار بعيد عن المركبة المتوقفة إذا كان ذلك آمناً، وأن تخفّف السرعة إذا لم تستطع تغيير المسار.","p":"صحيح. ابتعد، أو خفّف السرعة."},"ref":{"doc":"ND","page":32}},{"id":"nd-018","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on an interstate or multi-lane highway outside a city, which stopped vehicles does the move over rule cover?","o":["Only police cars","Any vehicle showing flashing hazard lights","Only ambulances and fire trucks","Only school buses"],"h1":"It is not only for emergency vehicles.","h2":"In North Dakota, the move over rule also covers any vehicle stopped on an interstate or multi-lane highway outside a city with its flashing hazard lights on.","p":"Right. Any vehicle with hazard lights is covered."},"es":{"q":"En Dakota del Norte, en una interestatal o carretera de varios carriles fuera de una ciudad, ¿qué vehículos detenidos cubre la regla para moverse de carril?","o":["Solo carros de policía","Cualquier vehículo con luces de emergencia intermitentes","Solo ambulancias y bomberos","Solo autobuses escolares"],"h1":"No es solo para vehículos de emergencia.","h2":"En Dakota del Norte, la regla para moverse de carril también cubre cualquier vehículo detenido en una interestatal o carretera de varios carriles fuera de una ciudad con sus luces de emergencia intermitentes encendidas.","p":"Correcto. Cualquier vehículo con luces de emergencia está cubierto."},"zh":{"q":"在 North Dakota，在城市以外的州际公路或多车道公路上，move over 规定包括哪些停着的车？","o":["只有警车","任何开着危险警示灯的车","只有救护车和消防车","只有校车"],"h1":"它不只是给急救车辆的。","h2":"在 North Dakota，move over 规定也包括任何停在城市以外的州际公路或多车道公路上、开着危险警示灯的车。","p":"对。任何开着危险警示灯的车都包括在内。"},"vi":{"q":"Ở North Dakota, trên xa lộ liên tiểu bang (interstate) hoặc xa lộ nhiều làn bên ngoài thành phố, quy định nhường làn áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Bất kỳ xe nào đang bật đèn cảnh báo nhấp nháy","Chỉ xe cứu thương và xe cứu hỏa","Chỉ xe buýt trường học"],"h1":"Không chỉ dành cho xe khẩn cấp.","h2":"Ở North Dakota, quy định nhường làn cũng áp dụng cho bất kỳ xe nào đang dừng trên xa lộ liên tiểu bang hoặc xa lộ nhiều làn bên ngoài thành phố và đang bật đèn cảnh báo nhấp nháy.","p":"Đúng. Bất kỳ xe nào bật đèn cảnh báo đều được áp dụng."},"tl":{"q":"Sa North Dakota, sa interstate o highway na maraming lane sa labas ng lungsod, aling mga nakahintong sasakyan ang sakop ng move over rule?","o":["Mga kotse lamang ng pulis","Anumang sasakyan na nakabukas ang kumikislap na hazard lights","Mga ambulansya at trak ng bumbero lamang","Mga school bus lamang"],"h1":"Hindi lamang ito para sa mga emergency vehicle.","h2":"Sa North Dakota, sakop din ng move over rule ang anumang sasakyan na nakahinto sa interstate o highway na maraming lane sa labas ng lungsod na nakabukas ang kumikislap na hazard lights.","p":"Tama. Sakop ang anumang sasakyan na may hazard lights."},"ar":{"q":"في North Dakota، على طريق سريع بين الولايات (interstate) أو طريق سريع متعدد المسارات خارج المدينة، أي المركبات المتوقفة تشملها قاعدة الابتعاد؟","o":["سيارات الشرطة فقط","أي مركبة تشغّل أضواء التحذير الوامضة","سيارات الإسعاف والإطفاء فقط","الحافلات المدرسية فقط"],"h1":"إنها ليست لمركبات الطوارئ فقط.","h2":"في North Dakota تشمل قاعدة الابتعاد أيضاً أي مركبة متوقفة على طريق سريع بين الولايات أو طريق سريع متعدد المسارات خارج المدينة وأضواء التحذير الوامضة فيها مشغّلة.","p":"صحيح. أي مركبة بأضواء التحذير مشمولة."},"ref":{"doc":"ND","page":32}},{"id":"nd-019","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, on a two-way road with no median, who must stop for a school bus with its stop arm out?","o":["Traffic in both directions","Only traffic behind the bus","Only trucks","No one, if the road is clear"],"h1":"On an undivided road, the children may cross toward either side.","h2":"In North Dakota, when a school bus stops with red lights flashing and the stop arm out on an undivided road, traffic in both directions must stop.","p":"Right. Both directions stop."},"es":{"q":"En Dakota del Norte, en una vía de doble sentido sin división, ¿quién debe detenerse ante un autobús escolar con el brazo de alto extendido?","o":["El tráfico en ambos sentidos","Solo el tráfico detrás del autobús","Solo los camiones","Nadie, si la vía está libre"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Dakota del Norte, cuando un autobús escolar se detiene con luces rojas intermitentes y el brazo de alto extendido en una vía sin división, el tráfico en ambos sentidos debe detenerse.","p":"Correcto. Ambos sentidos se detienen."},"zh":{"q":"在 North Dakota，在没有中央隔离带的双向道路上，谁必须为伸出停车臂的校车停车？","o":["两个方向的车","只有校车后面的车","只有卡车","没有人，如果路上没人"],"h1":"在没有分隔的路上，孩子可能往任何一边过马路。","h2":"在 North Dakota，校车在没有分隔的路上停下、闪着红灯并伸出停车臂时，两个方向的车都必须停车。","p":"对。两个方向都要停。"},"vi":{"q":"Ở North Dakota, trên đường hai chiều không có dải phân cách, ai phải dừng lại khi xe buýt trường học giương biển STOP?","o":["Xe cộ ở cả hai chiều","Chỉ xe phía sau xe buýt","Chỉ xe tải","Không ai, nếu đường trống"],"h1":"Trên đường không có dải phân cách, trẻ em có thể băng qua về bất kỳ bên nào.","h2":"Ở North Dakota, khi xe buýt trường học dừng lại, đèn đỏ nhấp nháy và giương biển STOP trên đường không có dải phân cách, xe cộ ở cả hai chiều phải dừng lại.","p":"Đúng. Cả hai chiều đều dừng lại."},"tl":{"q":"Sa North Dakota, sa daang two-way na walang median, sino ang dapat huminto para sa school bus na nakalabas ang stop arm?","o":["Mga sasakyan sa magkabilang direksyon","Mga sasakyan lamang sa likod ng bus","Mga trak lamang","Wala, kung maluwag ang daan"],"h1":"Sa daang walang harang sa gitna, maaaring tumawid ang mga bata papunta sa alinmang gilid.","h2":"Sa North Dakota, kapag huminto ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm sa daang walang harang sa gitna, dapat huminto ang mga sasakyan sa magkabilang direksyon.","p":"Tama. Huminto ang magkabilang direksyon."},"ar":{"q":"في North Dakota، على طريق باتجاهين بلا جزيرة وسطية، مَن يجب أن يتوقف لحافلة مدرسية ذراع التوقف (STOP) فيها مفتوح؟","o":["حركة المرور في الاتجاهين","حركة المرور خلف الحافلة فقط","الشاحنات فقط","لا أحد، إذا كان الطريق خالياً"],"h1":"على طريق غير مقسوم، قد يعبر الأطفال نحو أي جانب.","h2":"في North Dakota، عندما تتوقف حافلة مدرسية وأضواؤها الحمراء تومض وذراع التوقف مفتوح على طريق غير مقسوم، يجب أن تتوقف حركة المرور في الاتجاهين.","p":"صحيح. يتوقف الاتجاهان."},"ref":{"doc":"ND","page":20}},{"id":"nd-020","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, when may oncoming drivers keep going past a stopped school bus with its stop arm out?","o":["When they are in a hurry","When the bus is yellow","When a physical median or barrier divides the highway","When they honk first"],"h1":"Something solid must separate your side from the bus's side.","h2":"In North Dakota, oncoming drivers do not have to stop for a school bus only when the highway has separate roadways, divided by a median or barrier, and the bus is on the other roadway.","p":"Right. A physical median makes the difference."},"es":{"q":"En Dakota del Norte, ¿cuándo pueden seguir los conductores que vienen de frente ante un autobús escolar detenido con el brazo de alto extendido?","o":["Cuando tienen prisa","Cuando el autobús es amarillo","Cuando una división física o barrera separa la carretera","Cuando tocan la bocina primero"],"h1":"Algo sólido debe separar su lado del lado del autobús.","h2":"En Dakota del Norte, los conductores que vienen de frente no tienen que detenerse ante un autobús escolar solo cuando la carretera tiene calzadas separadas por una división o barrera y el autobús está en la otra calzada.","p":"Correcto. La división física hace la diferencia."},"zh":{"q":"在 North Dakota，对面开来的司机什么时候可以继续开过伸出停车臂、停着的校车？","o":["他们赶时间的时候","校车是黄色的时候","有实体中央隔离带或护栏把公路分开的时候","他们先按了喇叭的时候"],"h1":"必须有坚固的东西把你这边和校车那边分开。","h2":"在 North Dakota，只有当公路被中央隔离带或护栏分成两条独立的路面，而且校车在另一条路面上时，对面的司机才不用为校车停车。","p":"对。实体的中央隔离带是关键。"},"vi":{"q":"Ở North Dakota, khi nào xe chạy ngược chiều được tiếp tục chạy qua xe buýt trường học đang dừng và giương biển STOP?","o":["Khi họ đang vội","Khi xe buýt màu vàng","Khi có dải phân cách hoặc rào chắn chia đôi xa lộ","Khi họ bóp còi trước"],"h1":"Phải có một vật cứng ngăn cách phía bạn với phía xe buýt.","h2":"Ở North Dakota, xe chạy ngược chiều chỉ không phải dừng lại cho xe buýt trường học khi xa lộ có hai lòng đường riêng, được chia bởi dải phân cách hoặc rào chắn, và xe buýt ở lòng đường bên kia.","p":"Đúng. Dải phân cách thật sự là điều tạo nên sự khác biệt."},"tl":{"q":"Sa North Dakota, kailan maaaring tumuloy ang mga sasakyang paparating sa kabilang direksyon at lumampas sa nakahintong school bus na nakalabas ang stop arm?","o":["Kapag nagmamadali sila","Kapag dilaw ang bus","Kapag may median o harang na naghahati sa highway","Kapag bumusina muna sila"],"h1":"May matibay na bagay na dapat naghihiwalay sa iyong panig at sa panig ng bus.","h2":"Sa North Dakota, hindi kailangang huminto ng mga paparating na sasakyan para sa school bus lamang kapag ang highway ay may hiwalay na daan, na hinahati ng median o harang, at nasa kabilang daan ang bus.","p":"Tama. Ang median o harang ang nagpapaiba."},"ar":{"q":"في North Dakota، متى يجوز للسائقين القادمين من الاتجاه المعاكس أن يستمروا في المرور بجانب حافلة مدرسية متوقفة ذراع التوقف فيها مفتوح؟","o":["عندما يكونون مستعجلين","عندما تكون الحافلة صفراء","عندما تقسم جزيرة وسطية أو حاجز الطريق السريع","عندما يستخدمون البوق أولاً"],"h1":"يجب أن يفصل شيء صلب جانبك عن جانب الحافلة.","h2":"في North Dakota، ليس على السائقين القادمين من الاتجاه المعاكس أن يتوقفوا للحافلة المدرسية في حالة واحدة فقط: عندما يكون للطريق السريع طريقان منفصلان تقسمهما جزيرة وسطية أو حاجز، وتكون الحافلة على الطريق الآخر.","p":"صحيح. الجزيرة الوسطية أو الحاجز هو ما يصنع الفرق."},"ref":{"doc":"ND","page":null}},{"id":"nd-021","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, what is the top speed limit on rural interstate highways, unless a sign says otherwise?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"It is higher than the limit on divided highways that are not interstates.","h2":"In North Dakota the speed limit on rural interstate highways is 80 mph unless a sign shows a different limit.","p":"Right. Rural interstates in North Dakota allow up to 80 mph."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad máximo en las autopistas interestatales rurales, si no hay una señal que diga otra cosa?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Es más alto que el límite en las carreteras divididas que no son interestatales.","h2":"En Dakota del Norte el límite de velocidad en las autopistas interestatales rurales es de 80 mph, a menos que una señal indique otro límite.","p":"Correcto. En las interestatales rurales de Dakota del Norte se permite hasta 80 mph."},"zh":{"q":"在 North Dakota，如果没有标志另行规定，乡村州际公路的最高限速是多少？","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"它比不是州际公路的分隔公路的限速更高。","h2":"在 North Dakota，乡村州际公路的限速是 80 mph，除非标志显示不同的限速。","p":"对。North Dakota 的乡村州际公路最高可以开到 80 mph。"},"vi":{"q":"Ở North Dakota, tốc độ tối đa trên xa lộ liên tiểu bang ở vùng nông thôn là bao nhiêu, trừ khi có biển báo khác?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Nó cao hơn giới hạn trên các xa lộ có dải phân cách không phải là xa lộ liên tiểu bang.","h2":"Ở North Dakota, giới hạn tốc độ trên xa lộ liên tiểu bang ở vùng nông thôn là 80 mph, trừ khi biển báo ghi giới hạn khác.","p":"Đúng. Xa lộ liên tiểu bang ở vùng nông thôn của North Dakota cho phép chạy tới 80 mph."},"tl":{"q":"Sa North Dakota, ano ang pinakamataas na speed limit sa mga rural interstate highway, maliban kung iba ang sinasabi ng karatula?","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"Mas mataas ito kaysa sa limit sa mga divided highway na hindi interstate.","h2":"Sa North Dakota, ang speed limit sa mga rural interstate highway ay 80 mph maliban kung ibang limit ang nakasaad sa karatula.","p":"Tama. Hanggang 80 mph ang pinapayagan sa mga rural interstate sa North Dakota."},"ar":{"q":"في North Dakota، ما هو الحد الأقصى للسرعة على الطرق السريعة بين الولايات في المناطق الريفية، ما لم تقل لافتة غير ذلك؟","o":["65 mph","70 mph","80 mph","75 mph"],"h1":"إنه أعلى من الحد على الطرق المقسمة التي ليست طرقًا بين الولايات.","h2":"في North Dakota، حد السرعة على الطرق السريعة بين الولايات في المناطق الريفية هو 80 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. الطرق السريعة الريفية بين الولايات في North Dakota تسمح بسرعة تصل إلى 80 mph."},"ref":{"doc":"ND","page":20}},{"id":"nd-022","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, what is the speed limit on a gravel or dirt road when no limit is posted?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"It is the same as on a paved county road with no posted limit.","h2":"In North Dakota the speed limit on gravel, dirt or other loose-surface roads is 55 mph when no other limit is posted.","p":"Right. Gravel and dirt roads have a 55 mph limit unless posted."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en un camino de grava o de tierra cuando no hay un límite señalado?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Es igual que en una carretera pavimentada del condado sin límite señalado.","h2":"En Dakota del Norte el límite de velocidad en caminos de grava, de tierra u otra superficie suelta es de 55 mph cuando no hay otro límite señalado.","p":"Correcto. Los caminos de grava y de tierra tienen un límite de 55 mph si no hay señal."},"zh":{"q":"在 North Dakota，没有标出限速时，碎石路或土路的限速是多少？","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"它和没有标出限速的铺装县道一样。","h2":"在 North Dakota，没有标出其他限速时，碎石路、土路或其他松散路面道路的限速是 55 mph。","p":"对。除非另有标示，碎石路和土路的限速是 55 mph。"},"vi":{"q":"Ở North Dakota, giới hạn tốc độ trên đường sỏi hoặc đường đất là bao nhiêu khi không có biển báo giới hạn?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Nó giống như trên đường quận trải nhựa không có biển báo giới hạn.","h2":"Ở North Dakota, giới hạn tốc độ trên đường sỏi, đường đất hoặc đường có mặt đường rời khác là 55 mph khi không có giới hạn nào khác được ghi.","p":"Đúng. Đường sỏi và đường đất có giới hạn 55 mph trừ khi có biển báo khác."},"tl":{"q":"Sa North Dakota, ano ang speed limit sa daang graba o lupa kapag walang nakapaskil na limit?","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"Pareho ito sa sementadong county road na walang nakapaskil na limit.","h2":"Sa North Dakota, ang speed limit sa mga daang graba, lupa o iba pang maluwag ang ibabaw ay 55 mph kapag walang ibang limit na nakapaskil.","p":"Tama. May 55 mph na limit ang mga daang graba at lupa maliban kung may nakapaskil."},"ar":{"q":"في North Dakota، ما هو حد السرعة على طريق من الحصى أو التراب عندما لا يكون هناك حد مكتوب؟","o":["45 mph","55 mph","65 mph","35 mph"],"h1":"إنه نفس الحد على طريق مقاطعة معبد بلا حد مكتوب.","h2":"في North Dakota، حد السرعة على طرق الحصى أو التراب أو الطرق ذات السطح غير الثابت هو 55 mph عندما لا يكون هناك حد آخر مكتوب.","p":"صحيح. طرق الحصى والتراب حدها 55 mph ما لم يُكتب غير ذلك."},"ref":{"doc":"ND","page":20}},{"id":"nd-023","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, what is the fine for a first offense of driving without liability insurance?","o":["$50","$100","$500","$150"],"h1":"A second offense within three years costs twice as much.","h2":"In North Dakota the fine for a first offense of driving without liability insurance is $150, and your license may also be suspended.","p":"Right. A first no-insurance offense is a $150 fine."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por una primera infracción de manejar sin seguro de responsabilidad civil?","o":["$50","$100","$500","$150"],"h1":"Una segunda infracción en tres años cuesta el doble.","h2":"En Dakota del Norte la multa por una primera infracción de manejar sin seguro de responsabilidad civil es de $150, y además le pueden suspender la licencia.","p":"Correcto. La primera infracción por no tener seguro es una multa de $150."},"zh":{"q":"在 North Dakota，第一次没有责任保险开车会被罚款多少？","o":["$50","$100","$500","$150"],"h1":"三年内第二次违规要付两倍的钱。","h2":"在 North Dakota，第一次没有责任保险开车的罚款是 $150，你的驾照也可能被暂停。","p":"对。第一次没有保险的罚款是 $150。"},"vi":{"q":"Ở North Dakota, tiền phạt cho lần vi phạm đầu tiên vì lái xe không có bảo hiểm trách nhiệm là bao nhiêu?","o":["$50","$100","$500","$150"],"h1":"Lần vi phạm thứ hai trong vòng ba năm bị phạt gấp đôi.","h2":"Ở North Dakota, tiền phạt cho lần đầu lái xe không có bảo hiểm trách nhiệm là $150, và bằng lái của bạn cũng có thể bị đình chỉ.","p":"Đúng. Lần đầu không có bảo hiểm bị phạt $150."},"tl":{"q":"Sa North Dakota, magkano ang multa sa unang paglabag sa pagmamaneho nang walang liability insurance?","o":["$50","$100","$500","$150"],"h1":"Doble ang babayaran sa ikalawang paglabag sa loob ng tatlong taon.","h2":"Sa North Dakota, ang multa sa unang paglabag sa pagmamaneho nang walang liability insurance ay $150, at maaari ring masuspinde ang iyong lisensya.","p":"Tama. $150 ang multa sa unang paglabag na walang insurance."},"ar":{"q":"في North Dakota، ما هي الغرامة على المخالفة الأولى للقيادة بدون تأمين المسؤولية؟","o":["$50","$100","$500","$150"],"h1":"المخالفة الثانية خلال ثلاث سنوات تكلف ضعف المبلغ.","h2":"في North Dakota، الغرامة على المخالفة الأولى للقيادة بدون تأمين المسؤولية هي $150، وقد تُعلَّق رخصتك أيضًا.","p":"صحيح. المخالفة الأولى بدون تأمين غرامتها $150."},"ref":{"doc":"ND","page":27}},{"id":"nd-024","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, a crash with no injuries must be reported to police right away when the total damage reaches what amount?","o":["$4,000 or more","$1,000 or more","$500 or more","$10,000 or more"],"h1":"The amount is a few thousand dollars, added up for all vehicles and property.","h2":"In North Dakota you must report a crash to police right away when the combined damage is $4,000 or more, or when anyone is hurt or killed.","p":"Right. Combined damage of $4,000 or more must be reported."},"es":{"q":"En Dakota del Norte, un choque sin heridos se debe reportar a la policía de inmediato cuando el daño total llega a ¿qué cantidad?","o":["$4,000 o más","$1,000 o más","$500 o más","$10,000 o más"],"h1":"La cantidad es de unos miles de dólares, sumando todos los vehículos y la propiedad.","h2":"En Dakota del Norte usted debe reportar un choque a la policía de inmediato cuando el daño combinado es de $4,000 o más, o cuando alguien resulta herido o muere.","p":"Correcto. Un daño combinado de $4,000 o más se debe reportar."},"zh":{"q":"在 North Dakota，没有人受伤的车祸，总损失达到多少时必须马上报警？","o":["$4,000 或以上","$1,000 或以上","$500 或以上","$10,000 或以上"],"h1":"这个金额是几千美元，把所有车辆和财产的损失加在一起计算。","h2":"在 North Dakota，当总损失达到 $4,000 或以上，或者有人受伤或死亡时，你必须马上向警察报告车祸。","p":"对。总损失 $4,000 或以上必须报告。"},"vi":{"q":"Ở North Dakota, một vụ tai nạn không có người bị thương phải được báo ngay cho cảnh sát khi tổng thiệt hại đạt mức nào?","o":["$4,000 trở lên","$1,000 trở lên","$500 trở lên","$10,000 trở lên"],"h1":"Số tiền này là vài nghìn đô la, cộng lại cho tất cả xe và tài sản.","h2":"Ở North Dakota, bạn phải báo tai nạn cho cảnh sát ngay khi tổng thiệt hại là $4,000 trở lên, hoặc khi có người bị thương hay tử vong.","p":"Đúng. Tổng thiệt hại từ $4,000 trở lên phải được báo."},"tl":{"q":"Sa North Dakota, ang banggaang walang nasaktan ay dapat i-report agad sa pulis kapag umabot ang kabuuang pinsala sa anong halaga?","o":["$4,000 o higit pa","$1,000 o higit pa","$500 o higit pa","$10,000 o higit pa"],"h1":"Ilang libong dolyar ang halaga, pinagsama para sa lahat ng sasakyan at ari-arian.","h2":"Sa North Dakota, dapat mong i-report agad sa pulis ang banggaan kapag ang pinagsamang pinsala ay $4,000 o higit pa, o kapag may nasaktan o namatay.","p":"Tama. Dapat i-report ang pinagsamang pinsala na $4,000 o higit pa."},"ar":{"q":"في North Dakota، يجب إبلاغ الشرطة فورًا عن حادث بلا إصابات عندما يصل مجموع الأضرار إلى أي مبلغ؟","o":["$4,000 أو أكثر","$1,000 أو أكثر","$500 أو أكثر","$10,000 أو أكثر"],"h1":"المبلغ بضعة آلاف من الدولارات، مجموعًا لكل المركبات والممتلكات.","h2":"في North Dakota، يجب أن تبلغ الشرطة عن الحادث فورًا عندما يكون مجموع الأضرار $4,000 أو أكثر، أو عندما يُصاب أحد أو يُقتل.","p":"صحيح. يجب الإبلاغ عن أضرار مجموعها $4,000 أو أكثر."},"ref":{"doc":"ND","page":27}},{"id":"nd-025","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, children under what age must ride in a car seat or booster seat (unless they are at least 57 inches tall)?","o":["Under 5","Under 8","Under 10","Under 12"],"h1":"Older children, up to age 17, may use a seat belt instead.","h2":"In North Dakota children under 8 must ride in a car seat or booster seat, unless they are at least 57 inches tall and can use a seat belt.","p":"Right. Children under 8 need a car seat or booster seat."},"es":{"q":"En Dakota del Norte, ¿los niños menores de qué edad deben viajar en un asiento de seguridad o elevador (a menos que midan al menos 57 pulgadas)?","o":["Menores de 5","Menores de 8","Menores de 10","Menores de 12"],"h1":"Los niños mayores, hasta los 17 años, pueden usar el cinturón de seguridad.","h2":"En Dakota del Norte los niños menores de 8 años deben viajar en un asiento de seguridad o elevador, a menos que midan al menos 57 pulgadas y puedan usar el cinturón.","p":"Correcto. Los niños menores de 8 años necesitan un asiento de seguridad o elevador."},"zh":{"q":"在 North Dakota，几岁以下的儿童必须坐儿童安全座椅或增高座椅（除非身高至少 57 英寸）？","o":["5 岁以下","8 岁以下","10 岁以下","12 岁以下"],"h1":"更大的孩子，到 17 岁为止，可以改用安全带。","h2":"在 North Dakota，8 岁以下的儿童必须坐儿童安全座椅或增高座椅，除非他们身高至少 57 英寸并且可以使用安全带。","p":"对。8 岁以下的儿童需要儿童安全座椅或增高座椅。"},"vi":{"q":"Ở North Dakota, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn hoặc ghế nâng (trừ khi cao ít nhất 57 inch)?","o":["Dưới 5 tuổi","Dưới 8 tuổi","Dưới 10 tuổi","Dưới 12 tuổi"],"h1":"Trẻ lớn hơn, đến 17 tuổi, có thể dùng dây an toàn thay thế.","h2":"Ở North Dakota, trẻ em dưới 8 tuổi phải ngồi ghế an toàn hoặc ghế nâng, trừ khi các em cao ít nhất 57 inch và có thể dùng dây an toàn.","p":"Đúng. Trẻ em dưới 8 tuổi cần ghế an toàn hoặc ghế nâng."},"tl":{"q":"Sa North Dakota, ang mga batang wala pang anong edad ang dapat nakaupo sa car seat o booster seat (maliban kung hindi bababa sa 57 pulgada ang taas nila)?","o":["Wala pang 5","Wala pang 8","Wala pang 10","Wala pang 12"],"h1":"Ang mas malalaking bata, hanggang edad 17, ay maaaring gumamit ng seat belt sa halip.","h2":"Sa North Dakota, ang mga batang wala pang 8 taong gulang ay dapat nakaupo sa car seat o booster seat, maliban kung hindi bababa sa 57 pulgada ang taas nila at kaya nilang gumamit ng seat belt.","p":"Tama. Kailangan ng car seat o booster seat ang mga batang wala pang 8."},"ar":{"q":"في North Dakota، الأطفال دون أي عمر يجب أن يجلسوا في مقعد أطفال أو مقعد رافع (إلا إذا كان طولهم 57 بوصة على الأقل)؟","o":["دون 5","دون 8","دون 10","دون 12"],"h1":"الأطفال الأكبر سنًا، حتى عمر 17، يمكنهم استخدام حزام الأمان بدلاً من ذلك.","h2":"في North Dakota، يجب أن يجلس الأطفال دون 8 سنوات في مقعد أطفال أو مقعد رافع، إلا إذا كان طولهم 57 بوصة على الأقل ويمكنهم استخدام حزام الأمان.","p":"صحيح. الأطفال دون 8 سنوات يحتاجون إلى مقعد أطفال أو مقعد رافع."},"ref":{"doc":"ND","page":34}},{"id":"nd-026","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, what happens if you refuse a chemical test for alcohol or drugs when an officer asks?","o":["You get a warning only","You pay a $100 fine","You must take a driving class","Your license is revoked for 180 days to 3 years"],"h1":"By getting a license, you already agreed to be tested.","h2":"In North Dakota, if you refuse a chemical test, your license is revoked for 180 days to three years.","p":"Right. Refusing the test brings a revocation of 180 days to 3 years."},"es":{"q":"En Dakota del Norte, ¿qué pasa si usted se niega a hacerse una prueba química de alcohol o drogas cuando un oficial se lo pide?","o":["Solo recibe una advertencia","Paga una multa de $100","Debe tomar una clase de manejo","Le revocan la licencia de 180 días a 3 años"],"h1":"Al obtener la licencia, usted ya aceptó hacerse la prueba.","h2":"En Dakota del Norte, si usted se niega a una prueba química, le revocan la licencia por un período de 180 días a tres años.","p":"Correcto. Negarse a la prueba trae una revocación de 180 días a 3 años."},"zh":{"q":"在 North Dakota，如果警察要求你做酒精或毒品化学检测而你拒绝，会怎样？","o":["你只会收到警告","你要付 $100 罚款","你必须上驾驶课","你的驾照会被吊销 180 天到 3 年"],"h1":"拿到驾照时，你就已经同意接受检测。","h2":"在 North Dakota，如果你拒绝化学检测，你的驾照会被吊销 180 天到三年。","p":"对。拒绝检测会导致驾照被吊销 180 天到 3 年。"},"vi":{"q":"Ở North Dakota, điều gì xảy ra nếu bạn từ chối xét nghiệm hóa học về rượu hoặc ma túy khi cảnh sát yêu cầu?","o":["Bạn chỉ bị cảnh cáo","Bạn bị phạt $100","Bạn phải học một lớp lái xe","Bằng lái của bạn bị thu hồi từ 180 ngày đến 3 năm"],"h1":"Khi nhận bằng lái, bạn đã đồng ý được xét nghiệm.","h2":"Ở North Dakota, nếu bạn từ chối xét nghiệm hóa học, bằng lái của bạn bị thu hồi từ 180 ngày đến ba năm.","p":"Đúng. Từ chối xét nghiệm dẫn đến bị thu hồi bằng từ 180 ngày đến 3 năm."},"tl":{"q":"Sa North Dakota, ano ang mangyayari kapag tumanggi ka sa chemical test para sa alak o droga kapag hiniling ito ng pulis?","o":["Babala lang ang matatanggap mo","Magbabayad ka ng $100 na multa","Kailangan mong kumuha ng klase sa pagmamaneho","Babawiin ang iyong lisensya nang 180 araw hanggang 3 taon"],"h1":"Nang kumuha ka ng lisensya, pumayag ka nang ma-test.","h2":"Sa North Dakota, kapag tumanggi ka sa chemical test, babawiin ang iyong lisensya nang 180 araw hanggang tatlong taon.","p":"Tama. Ang pagtanggi sa test ay nagdudulot ng pagbawi ng lisensya nang 180 araw hanggang 3 taon."},"ar":{"q":"في North Dakota، ماذا يحدث إذا رفضت فحصًا كيميائيًا للكحول أو المخدرات عندما يطلبه الشرطي؟","o":["تحصل على تحذير فقط","تدفع غرامة $100","يجب أن تحضر دورة قيادة","تُلغى رخصتك لمدة من 180 يومًا إلى 3 سنوات"],"h1":"عندما حصلت على الرخصة، وافقت مسبقًا على أن تُفحص.","h2":"في North Dakota، إذا رفضت الفحص الكيميائي، تُلغى رخصتك لمدة من 180 يومًا إلى ثلاث سنوات.","p":"صحيح. رفض الفحص يؤدي إلى إلغاء الرخصة لمدة من 180 يومًا إلى 3 سنوات."},"ref":{"doc":"ND","page":36}},{"id":"nd-027","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, how many points on your driving record lead to a license suspension?","o":["12 or more","6 or more","8 or more","20 or more"],"h1":"It is a dozen.","h2":"In North Dakota your license is suspended when your driving record reaches 12 or more points.","p":"Right. Twelve or more points means a suspension."},"es":{"q":"En Dakota del Norte, ¿cuántos puntos en su historial de manejo llevan a la suspensión de la licencia?","o":["12 o más","6 o más","8 o más","20 o más"],"h1":"Es una docena.","h2":"En Dakota del Norte le suspenden la licencia cuando su historial de manejo llega a 12 puntos o más.","p":"Correcto. Doce puntos o más significan una suspensión."},"zh":{"q":"在 North Dakota，驾驶记录上有多少分会导致驾照被暂停？","o":["12 分或以上","6 分或以上","8 分或以上","20 分或以上"],"h1":"是一打。","h2":"在 North Dakota，当你的驾驶记录达到 12 分或以上时，你的驾照会被暂停。","p":"对。12 分或以上就会被暂停驾照。"},"vi":{"q":"Ở North Dakota, bao nhiêu điểm trong hồ sơ lái xe sẽ dẫn đến việc đình chỉ bằng lái?","o":["12 điểm trở lên","6 điểm trở lên","8 điểm trở lên","20 điểm trở lên"],"h1":"Đó là một tá.","h2":"Ở North Dakota, bằng lái của bạn bị đình chỉ khi hồ sơ lái xe có 12 điểm trở lên.","p":"Đúng. Từ 12 điểm trở lên nghĩa là bị đình chỉ."},"tl":{"q":"Sa North Dakota, ilang puntos sa iyong driving record ang magdudulot ng pagsuspinde ng lisensya?","o":["12 o higit pa","6 o higit pa","8 o higit pa","20 o higit pa"],"h1":"Isang dosena ito.","h2":"Sa North Dakota, masususpinde ang iyong lisensya kapag umabot sa 12 o higit pang puntos ang iyong driving record.","p":"Tama. Ang 12 o higit pang puntos ay nangangahulugang suspensyon."},"ar":{"q":"في North Dakota، كم نقطة في سجل قيادتك تؤدي إلى تعليق الرخصة؟","o":["12 أو أكثر","6 أو أكثر","8 أو أكثر","20 أو أكثر"],"h1":"إنها دزينة.","h2":"في North Dakota، تُعلَّق رخصتك عندما يصل سجل قيادتك إلى 12 نقطة أو أكثر.","p":"صحيح. 12 نقطة أو أكثر تعني التعليق."},"ref":{"doc":"ND","page":40}},{"id":"nd-028","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how can you have one point taken off your driving record without taking a class?","o":["Pay a fee to the state","Ask a judge after one month","Go three months with no new points","Wait until your next birthday"],"h1":"It happens on its own if you keep a clean record.","h2":"In North Dakota one point comes off your record for every three months in which you get no new points.","p":"Right. Each three months with no new points removes one point."},"es":{"q":"En Dakota del Norte, ¿cómo se le puede quitar un punto de su historial de manejo sin tomar una clase?","o":["Pagar una tarifa al estado","Pedírselo a un juez después de un mes","Pasar tres meses sin puntos nuevos","Esperar hasta su próximo cumpleaños"],"h1":"Pasa solo si usted mantiene un historial limpio.","h2":"En Dakota del Norte se le quita un punto de su historial por cada tres meses en los que no recibe puntos nuevos.","p":"Correcto. Cada tres meses sin puntos nuevos le quita un punto."},"zh":{"q":"在 North Dakota，不上课的话，怎样可以从驾驶记录上减掉一分？","o":["向州政府付一笔费用","一个月后请求法官","连续三个月没有新扣分","等到你下一个生日"],"h1":"只要保持记录干净，它会自动发生。","h2":"在 North Dakota，每连续三个月没有新扣分，你的记录就会减掉一分。","p":"对。每三个月没有新扣分就减掉一分。"},"vi":{"q":"Ở North Dakota, làm sao để được xóa một điểm khỏi hồ sơ lái xe mà không cần học một lớp?","o":["Trả một khoản phí cho tiểu bang","Xin thẩm phán sau một tháng","Ba tháng liền không bị thêm điểm mới","Chờ đến sinh nhật tiếp theo"],"h1":"Điều này tự xảy ra nếu bạn giữ hồ sơ sạch.","h2":"Ở North Dakota, cứ mỗi ba tháng bạn không bị thêm điểm mới thì hồ sơ của bạn được xóa một điểm.","p":"Đúng. Mỗi ba tháng không có điểm mới sẽ xóa một điểm."},"tl":{"q":"Sa North Dakota, paano mo maaalis ang isang puntos sa iyong driving record nang hindi kumukuha ng klase?","o":["Magbayad ng bayad sa estado","Humiling sa hukom pagkalipas ng isang buwan","Tatlong buwan nang walang bagong puntos","Maghintay hanggang sa susunod mong kaarawan"],"h1":"Kusa itong nangyayari kung malinis ang iyong record.","h2":"Sa North Dakota, may isang puntos na naaalis sa iyong record sa bawat tatlong buwan na wala kang bagong puntos.","p":"Tama. Bawat tatlong buwan na walang bagong puntos ay nag-aalis ng isang puntos."},"ar":{"q":"في North Dakota، كيف يمكنك حذف نقطة واحدة من سجل قيادتك دون حضور دورة؟","o":["أن تدفع رسومًا للولاية","أن تطلب من قاضٍ بعد شهر","أن تمضي ثلاثة أشهر دون نقاط جديدة","أن تنتظر حتى عيد ميلادك القادم"],"h1":"يحدث ذلك من تلقاء نفسه إذا حافظت على سجل نظيف.","h2":"في North Dakota، تُحذف نقطة واحدة من سجلك عن كل ثلاثة أشهر لا تحصل فيها على نقاط جديدة.","p":"صحيح. كل ثلاثة أشهر بلا نقاط جديدة تحذف نقطة واحدة."},"ref":{"doc":"ND","page":40}},{"id":"nd-029","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the penalty on your driving record for breaking the rules of your instruction permit?","o":["One point","Two points","Four points","Six points"],"h1":"It is a small number of points, more than one.","h2":"In North Dakota, driving against the conditions of your instruction permit puts two points on your driving record.","p":"Right. Breaking permit rules adds two points."},"es":{"q":"En Dakota del Norte, ¿cuál es la sanción en su historial de manejo por no cumplir las reglas de su permiso de instrucción?","o":["Un punto","Dos puntos","Cuatro puntos","Seis puntos"],"h1":"Es un número pequeño de puntos, más de uno.","h2":"En Dakota del Norte, manejar sin cumplir las condiciones de su permiso de instrucción agrega dos puntos a su historial de manejo.","p":"Correcto. No cumplir las reglas del permiso agrega dos puntos."},"zh":{"q":"在 North Dakota，违反学习驾照（instruction permit）的规定，在驾驶记录上会受到什么处罚？","o":["一分","两分","四分","六分"],"h1":"分数不多，但多于一分。","h2":"在 North Dakota，违反学习驾照的条件开车，会在你的驾驶记录上记两分。","p":"对。违反学习驾照规定会加两分。"},"vi":{"q":"Ở North Dakota, hình phạt trong hồ sơ lái xe khi vi phạm quy định của giấy phép học lái (instruction permit) là gì?","o":["Một điểm","Hai điểm","Bốn điểm","Sáu điểm"],"h1":"Đó là một số điểm nhỏ, nhiều hơn một.","h2":"Ở North Dakota, lái xe trái với điều kiện của giấy phép học lái sẽ bị ghi hai điểm vào hồ sơ lái xe.","p":"Đúng. Vi phạm quy định của giấy phép học lái bị thêm hai điểm."},"tl":{"q":"Sa North Dakota, ano ang parusa sa iyong driving record kapag nilabag mo ang mga patakaran ng iyong instruction permit?","o":["Isang puntos","Dalawang puntos","Apat na puntos","Anim na puntos"],"h1":"Maliit na bilang ng puntos ito, higit sa isa.","h2":"Sa North Dakota, ang pagmamaneho nang labag sa mga kondisyon ng iyong instruction permit ay naglalagay ng dalawang puntos sa iyong driving record.","p":"Tama. Ang paglabag sa mga patakaran ng permit ay nagdadagdag ng dalawang puntos."},"ar":{"q":"في North Dakota، ما هي العقوبة في سجل قيادتك عند مخالفة قواعد تصريح التعلم (instruction permit)؟","o":["نقطة واحدة","نقطتان","أربع نقاط","ست نقاط"],"h1":"إنه عدد صغير من النقاط، أكثر من واحدة.","h2":"في North Dakota، القيادة بما يخالف شروط تصريح التعلم تضيف نقطتين إلى سجل قيادتك.","p":"صحيح. مخالفة قواعد التصريح تضيف نقطتين."},"ref":{"doc":"ND","page":4}},{"id":"nd-030","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, how close to a fire hydrant may you park?","o":["5 feet","10 feet","25 feet","50 feet"],"h1":"It is closer than in many other states.","h2":"In North Dakota you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a fire hydrant."},"es":{"q":"En Dakota del Norte, ¿qué tan cerca de un hidrante puede estacionarse?","o":["5 pies","10 pies","25 pies","50 pies"],"h1":"Es más cerca que en muchos otros estados.","h2":"En Dakota del Norte usted no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 North Dakota，停车时离消防栓（fire hydrant）要多远？","o":["5 英尺","10 英尺","25 英尺","50 英尺"],"h1":"这个距离比很多其他州更近。","h2":"在 North Dakota，你不可以把车停在离消防栓 10 英尺以内的地方。","p":"对。离消防栓至少 10 英尺。"},"vi":{"q":"Ở North Dakota, bạn được đỗ xe cách trụ nước cứu hỏa (fire hydrant) bao xa?","o":["5 feet","10 feet","25 feet","50 feet"],"h1":"Khoảng cách này gần hơn so với nhiều tiểu bang khác.","h2":"Ở North Dakota, bạn không được đỗ xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa North Dakota, gaano kalapit sa fire hydrant (gripo ng bumbero) ka puwedeng pumarada?","o":["5 talampakan","10 talampakan","25 talampakan","50 talampakan"],"h1":"Mas malapit ito kaysa sa maraming ibang estado.","h2":"Sa North Dakota, bawal kang pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan mula sa fire hydrant."},"ar":{"q":"في North Dakota، على أي مسافة من صنبور إطفاء الحريق (fire hydrant) يمكنك أن تركن سيارتك؟","o":["5 أقدام","10 أقدام","25 قدمًا","50 قدمًا"],"h1":"هذه المسافة أقرب مما هي في كثير من الولايات الأخرى.","h2":"في North Dakota لا يجوز لك أن تركن سيارتك على بعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"ND","page":26}},{"id":"nd-031","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, how much space must you leave when passing a bicycle?","o":["6 inches","1 foot","2 feet","At least 3 feet"],"h1":"Give the rider room to wobble.","h2":"In North Dakota a driver must leave at least three feet of space when passing a bicycle.","p":"Right. Leave at least 3 feet when you pass a bicycle."},"es":{"q":"En Dakota del Norte, ¿cuánto espacio debe dejar al rebasar una bicicleta?","o":["6 pulgadas","1 pie","2 pies","Por lo menos 3 pies"],"h1":"Dele espacio al ciclista por si se tambalea.","h2":"En Dakota del Norte el conductor debe dejar por lo menos tres pies de espacio al rebasar una bicicleta.","p":"Correcto. Deje por lo menos 3 pies al rebasar una bicicleta."},"zh":{"q":"在 North Dakota，超过自行车时必须留出多大的空间？","o":["6 英寸","1 英尺","2 英尺","至少 3 英尺"],"h1":"给骑车的人留出摇晃的空间。","h2":"在 North Dakota，司机超过自行车时必须留出至少 3 英尺的空间。","p":"对。超过自行车时要留出至少 3 英尺。"},"vi":{"q":"Ở North Dakota, khi vượt xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["6 inch","1 foot","2 feet","Ít nhất 3 feet"],"h1":"Hãy chừa chỗ để người đi xe đạp có thể lắc lư.","h2":"Ở North Dakota, tài xế phải chừa khoảng cách ít nhất 3 feet khi vượt xe đạp.","p":"Đúng. Hãy chừa ít nhất 3 feet khi vượt xe đạp."},"tl":{"q":"Sa North Dakota, gaano kalaking espasyo ang dapat mong iwan kapag nag-overtake ka sa bisikleta?","o":["6 pulgada","1 talampakan","2 talampakan","Hindi bababa sa 3 talampakan"],"h1":"Bigyan ng puwang ang siklista kung sakaling gumewang siya.","h2":"Sa North Dakota, dapat mag-iwan ang drayber ng hindi bababa sa 3 talampakang espasyo kapag nag-overtake sa bisikleta.","p":"Tama. Mag-iwan ng hindi bababa sa 3 talampakan kapag nag-overtake ka sa bisikleta."},"ar":{"q":"في North Dakota، ما المسافة التي يجب أن تتركها عندما تتجاوز دراجة هوائية؟","o":["6 بوصات","قدم واحد","قدمان","3 أقدام على الأقل"],"h1":"اترك لراكب الدراجة مساحة إذا تمايل.","h2":"في North Dakota يجب على السائق أن يترك مسافة 3 أقدام على الأقل عندما يتجاوز دراجة هوائية.","p":"صحيح. اترك 3 أقدام على الأقل عندما تتجاوز دراجة هوائية."},"ref":{"doc":"ND","page":33}},{"id":"nd-032","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, where must an open container of alcohol be kept in a car?","o":["In the trunk","Under the driver's seat","In the glove box","In a passenger's hand"],"h1":"It must be out of reach of everyone in the car.","h2":"In North Dakota you may not have an open container of alcohol in the car, so any open container must be put in the trunk.","p":"Right. Open containers go in the trunk."},"es":{"q":"En Dakota del Norte, ¿dónde se debe guardar un envase abierto de alcohol en el carro?","o":["En la cajuela","Debajo del asiento del conductor","En la guantera","En la mano de un pasajero"],"h1":"Debe estar fuera del alcance de todos en el carro.","h2":"En Dakota del Norte no puede llevar un envase abierto de alcohol en el carro, así que cualquier envase abierto debe ir en la cajuela.","p":"Correcto. Los envases abiertos van en la cajuela."},"zh":{"q":"在 North Dakota，车里打开过的酒（open container）必须放在哪里？","o":["后备箱里","司机座位下面","手套箱里","乘客手里"],"h1":"它必须放在车里所有人都够不到的地方。","h2":"在 North Dakota，车里不可以有打开过的酒，所以打开过的酒必须放在后备箱里。","p":"对。打开过的酒要放在后备箱里。"},"vi":{"q":"Ở North Dakota, đồ uống có cồn đã mở (open container) phải được để ở đâu trong xe?","o":["Trong cốp xe","Dưới ghế tài xế","Trong hộc đựng đồ (glove box)","Trong tay hành khách"],"h1":"Nó phải ở ngoài tầm với của mọi người trong xe.","h2":"Ở North Dakota, bạn không được để đồ uống có cồn đã mở trong khoang xe, vì vậy đồ uống có cồn đã mở phải được để trong cốp xe.","p":"Đúng. Đồ uống có cồn đã mở phải để trong cốp xe."},"tl":{"q":"Sa North Dakota, saan dapat ilagay sa kotse ang bukas na lalagyan ng alak (open container)?","o":["Sa trunk (likurang kompartimento)","Sa ilalim ng upuan ng drayber","Sa glove box","Sa kamay ng pasahero"],"h1":"Dapat hindi ito maabot ng sinuman sa loob ng kotse.","h2":"Sa North Dakota, bawal magkaroon ng bukas na lalagyan ng alak sa loob ng kotse, kaya dapat ilagay sa trunk ang anumang bukas na lalagyan.","p":"Tama. Sa trunk inilalagay ang bukas na lalagyan ng alak."},"ar":{"q":"في North Dakota، أين يجب أن يوضع وعاء الكحول المفتوح (open container) في السيارة؟","o":["في صندوق السيارة الخلفي","تحت مقعد السائق","في درج القفازات","في يد أحد الركاب"],"h1":"يجب أن يكون بعيدًا عن متناول كل من في السيارة.","h2":"في North Dakota لا يجوز أن يكون معك وعاء كحول مفتوح داخل السيارة، لذلك يجب وضع أي وعاء مفتوح في صندوق السيارة الخلفي.","p":"صحيح. الأوعية المفتوحة توضع في صندوق السيارة الخلفي."},"ref":{"doc":"ND","page":37}},{"id":"nd-033","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how early can you renew your license without losing time left on the old one?","o":["1 month before it expires","3 months before it expires","10 months before it expires","2 years before it expires"],"h1":"It is almost a full year.","h2":"In North Dakota you may renew your license up to 10 months before it expires without losing the time left on your old license.","p":"Right. You can renew up to 10 months early."},"es":{"q":"En Dakota del Norte, ¿con cuánta anticipación puede renovar su licencia sin perder el tiempo que le queda a la anterior?","o":["1 mes antes del vencimiento","3 meses antes del vencimiento","10 meses antes del vencimiento","2 años antes del vencimiento"],"h1":"Es casi un año completo.","h2":"En Dakota del Norte usted puede renovar su licencia hasta 10 meses antes del vencimiento sin perder el tiempo que le queda a la licencia anterior.","p":"Correcto. Puede renovar hasta 10 meses antes."},"zh":{"q":"在 North Dakota，最早可以提前多久更新驾照，而不会失去旧驾照剩下的时间？","o":["到期前 1 个月","到期前 3 个月","到期前 10 个月","到期前 2 年"],"h1":"差不多是一整年。","h2":"在 North Dakota，你可以在驾照到期前最多 10 个月更新，而不会失去旧驾照剩下的时间。","p":"对。你最多可以提前 10 个月更新。"},"vi":{"q":"Ở North Dakota, bạn có thể gia hạn bằng lái sớm nhất là bao lâu mà không mất thời gian còn lại của bằng cũ?","o":["1 tháng trước khi hết hạn","3 tháng trước khi hết hạn","10 tháng trước khi hết hạn","2 năm trước khi hết hạn"],"h1":"Gần như trọn một năm.","h2":"Ở North Dakota, bạn có thể gia hạn bằng lái tối đa 10 tháng trước khi hết hạn mà không mất thời gian còn lại của bằng cũ.","p":"Đúng. Bạn có thể gia hạn sớm tối đa 10 tháng."},"tl":{"q":"Sa North Dakota, gaano kaaga ka puwedeng mag-renew ng lisensya nang hindi nawawala ang natitirang panahon ng luma?","o":["1 buwan bago ito mag-expire","3 buwan bago ito mag-expire","10 buwan bago ito mag-expire","2 taon bago ito mag-expire"],"h1":"Halos isang buong taon ito.","h2":"Sa North Dakota, puwede kang mag-renew ng lisensya hanggang 10 buwan bago ito mag-expire nang hindi nawawala ang natitirang panahon ng lumang lisensya.","p":"Tama. Puwede kang mag-renew hanggang 10 buwan nang mas maaga."},"ar":{"q":"في North Dakota، كم مبكرًا يمكنك تجديد رخصتك دون أن تخسر المدة المتبقية في الرخصة القديمة؟","o":["قبل انتهائها بشهر واحد","قبل انتهائها بـ 3 أشهر","قبل انتهائها بـ 10 أشهر","قبل انتهائها بسنتين"],"h1":"إنها تقريبًا سنة كاملة.","h2":"في North Dakota يمكنك تجديد رخصتك قبل انتهائها بمدة تصل إلى 10 أشهر دون أن تخسر المدة المتبقية في رخصتك القديمة.","p":"صحيح. يمكنك التجديد مبكرًا بمدة تصل إلى 10 أشهر."},"ref":{"doc":"ND","page":7}},{"id":"nd-034","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, you just moved here and have a valid license from another state. How long may you drive a car with it?","o":["30 days","60 days","90 days","1 year"],"h1":"It is about two months.","h2":"In North Dakota a new resident may drive with a valid license from another state for 60 days, then must get a North Dakota license.","p":"Right. You have 60 days to get a North Dakota license."},"es":{"q":"En Dakota del Norte, usted acaba de mudarse y tiene una licencia válida de otro estado. ¿Por cuánto tiempo puede manejar un carro con ella?","o":["30 días","60 días","90 días","1 año"],"h1":"Son unos dos meses.","h2":"En Dakota del Norte un nuevo residente puede manejar con una licencia válida de otro estado por 60 días, y después debe sacar una licencia de Dakota del Norte.","p":"Correcto. Usted tiene 60 días para sacar una licencia de Dakota del Norte."},"zh":{"q":"在 North Dakota，你刚搬来，持有另一个州的有效驾照。你可以用它开车多久？","o":["30 天","60 天","90 天","1 年"],"h1":"大约两个月。","h2":"在 North Dakota，新居民可以用另一个州的有效驾照开车 60 天，之后必须换成 North Dakota 驾照。","p":"对。你有 60 天时间去拿 North Dakota 驾照。"},"vi":{"q":"Ở North Dakota, bạn vừa chuyển đến và có bằng lái hợp lệ của một tiểu bang khác. Bạn được lái xe bằng bằng lái đó trong bao lâu?","o":["30 ngày","60 ngày","90 ngày","1 năm"],"h1":"Khoảng hai tháng.","h2":"Ở North Dakota, cư dân mới được lái xe bằng bằng lái hợp lệ của tiểu bang khác trong 60 ngày, sau đó phải lấy bằng lái North Dakota.","p":"Đúng. Bạn có 60 ngày để lấy bằng lái North Dakota."},"tl":{"q":"Sa North Dakota, bago ka pa lang lumipat dito at may valid na lisensya ka mula sa ibang estado. Gaano katagal ka puwedeng magmaneho gamit ito?","o":["30 araw","60 araw","90 araw","1 taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa North Dakota, ang bagong residente ay puwedeng magmaneho gamit ang valid na lisensya mula sa ibang estado sa loob ng 60 araw, at pagkatapos ay kailangan niyang kumuha ng lisensya ng North Dakota.","p":"Tama. May 60 araw ka para kumuha ng lisensya ng North Dakota."},"ar":{"q":"في North Dakota، انتقلت إليها للتو ولديك رخصة سارية من ولاية أخرى. كم من الوقت يمكنك أن تقود بها؟","o":["30 يومًا","60 يومًا","90 يومًا","1 سنة"],"h1":"المدة حوالي شهرين.","h2":"في North Dakota يمكن للمقيم الجديد أن يقود برخصة سارية من ولاية أخرى لمدة 60 يومًا، ثم يجب عليه أن يحصل على رخصة North Dakota.","p":"صحيح. لديك 60 يومًا للحصول على رخصة North Dakota."},"ref":{"doc":"ND","page":2}},{"id":"nd-035","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, you change your name or address. How soon must you tell the Driver License Division?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is less than two weeks.","h2":"In North Dakota you must tell the Driver License Division about a new name or address within 10 days.","p":"Right. Report a new name or address within 10 days."},"es":{"q":"En Dakota del Norte, usted cambia de nombre o de dirección. ¿En cuánto tiempo debe avisar a la División de Licencias de Conducir?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En Dakota del Norte usted debe avisar a la División de Licencias de Conducir de un nuevo nombre o dirección dentro de 10 días.","p":"Correcto. Avise de un nuevo nombre o dirección dentro de 10 días."},"zh":{"q":"在 North Dakota，你改了姓名或地址。必须在多久之内通知驾照部门（Driver License Division）？","o":["10 天内","30 天内","60 天内","下次更新驾照时"],"h1":"不到两个星期。","h2":"在 North Dakota，你必须在 10 天内把新的姓名或地址告诉驾照部门。","p":"对。新的姓名或地址要在 10 天内报告。"},"vi":{"q":"Ở North Dakota, bạn đổi tên hoặc địa chỉ. Bạn phải báo cho Phòng Bằng Lái (Driver License Division) trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Vào lần gia hạn tới"],"h1":"Chưa đến hai tuần.","h2":"Ở North Dakota, bạn phải báo cho Phòng Bằng Lái biết tên hoặc địa chỉ mới trong vòng 10 ngày.","p":"Đúng. Hãy báo tên hoặc địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa North Dakota, nagpalit ka ng pangalan o address. Gaano kabilis mo dapat sabihin sa Driver License Division?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa susunod mong pag-renew"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sa North Dakota, kailangan mong sabihin sa Driver License Division ang bagong pangalan o address sa loob ng 10 araw.","p":"Tama. Iulat ang bagong pangalan o address sa loob ng 10 araw."},"ar":{"q":"في North Dakota، غيّرت اسمك أو عنوانك. خلال كم من الوقت يجب أن تُبلغ قسم رخص القيادة (Driver License Division)؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عند تجديد رخصتك القادم"],"h1":"المدة أقل من أسبوعين.","h2":"في North Dakota يجب أن تُبلغ قسم رخص القيادة باسمك أو عنوانك الجديد خلال 10 أيام.","p":"صحيح. أبلغ عن الاسم أو العنوان الجديد خلال 10 أيام."},"ref":{"doc":"ND","page":8}},{"id":"nd-036","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, you are driving with an instruction permit. Who may sit in the front seat with you?","o":["Any passenger who wears a seat belt","Any passenger 16 or older","Only the supervising driver, unless the vehicle has only a front seat","Anyone, if the back seat is full"],"h1":"The front seat is kept for the person who is teaching you.","h2":"In North Dakota only the supervising driver may sit in the front seat with a permit holder, unless the vehicle has only a front seat.","p":"Right. Only the supervising driver sits up front with you."},"es":{"q":"En Dakota del Norte, usted maneja con un permiso de aprendizaje. ¿Quién puede ir en el asiento delantero con usted?","o":["Cualquier pasajero que use el cinturón","Cualquier pasajero de 16 años o más","Solo el conductor que lo supervisa, a menos que el vehículo tenga solo asiento delantero","Cualquier persona, si el asiento de atrás está lleno"],"h1":"El asiento delantero es para la persona que le enseña.","h2":"En Dakota del Norte solo el conductor que supervisa puede ir en el asiento delantero con quien tiene un permiso, a menos que el vehículo tenga solo asiento delantero.","p":"Correcto. Solo el conductor que lo supervisa va adelante con usted."},"zh":{"q":"在 North Dakota，你持学习驾照开车。谁可以和你一起坐在前排？","o":["任何系好安全带的乘客","任何 16 岁或以上的乘客","只有监督司机，除非车里只有前排座位","任何人，如果后座坐满了"],"h1":"前排座位是留给教你开车的人的。","h2":"在 North Dakota，只有监督司机可以和持学习驾照的人一起坐在前排，除非车里只有前排座位。","p":"对。只有监督司机和你一起坐在前排。"},"vi":{"q":"Ở North Dakota, bạn đang lái xe với giấy phép tập lái. Ai được ngồi ghế trước cùng bạn?","o":["Bất kỳ hành khách nào thắt dây an toàn","Bất kỳ hành khách nào từ 16 tuổi trở lên","Chỉ người lái xe giám sát, trừ khi xe chỉ có ghế trước","Bất kỳ ai, nếu ghế sau đã đầy"],"h1":"Ghế trước dành cho người đang dạy bạn lái xe.","h2":"Ở North Dakota, chỉ người lái xe giám sát được ngồi ghế trước cùng người có giấy phép tập lái, trừ khi xe chỉ có ghế trước.","p":"Đúng. Chỉ người lái xe giám sát ngồi phía trước cùng bạn."},"tl":{"q":"Sa North Dakota, nagmamaneho ka nang may instruction permit. Sino ang puwedeng umupo sa harap kasama mo?","o":["Kahit sinong pasaherong naka-seat belt","Kahit sinong pasaherong 16 o mas matanda","Ang supervising driver lamang, maliban kung upuan sa harap lang ang mayroon ang sasakyan","Kahit sino, kung puno na ang upuan sa likod"],"h1":"Ang upuan sa harap ay para sa taong nagtuturo sa iyo.","h2":"Sa North Dakota, ang supervising driver lamang ang puwedeng umupo sa harap kasama ng may permit, maliban kung upuan sa harap lang ang mayroon ang sasakyan.","p":"Tama. Ang supervising driver lang ang nakaupo sa harap kasama mo."},"ar":{"q":"في North Dakota، تقود بتصريح تعلّم. من يجوز له أن يجلس معك في المقعد الأمامي؟","o":["أي راكب يربط حزام الأمان","أي راكب عمره 16 سنة أو أكثر","السائق المشرف فقط، إلا إذا لم يكن في المركبة إلا مقعد أمامي","أي شخص، إذا كان المقعد الخلفي ممتلئًا"],"h1":"المقعد الأمامي مخصص للشخص الذي يعلّمك.","h2":"في North Dakota يجلس السائق المشرف وحده في المقعد الأمامي مع حامل تصريح التعلّم، ما لم يكن في المركبة مقعد أمامي فقط.","p":"صحيح. السائق المشرف وحده يجلس معك في الأمام."},"ref":{"doc":"ND","page":3}},{"id":"nd-037","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, how can you have the Class D road test waived?","o":["Pass the knowledge test with a perfect score","Hold your permit for two years","Log 100 hours of driving with a parent","Show a certificate from an approved course with 30 hours of classroom and 6 hours behind the wheel"],"h1":"Think of a driver training course with both class time and driving time.","h2":"In North Dakota the road test can be waived with a certificate from an approved course of at least 30 hours of classroom and 6 hours of behind-the-wheel training.","p":"Right. An approved 30-hour classroom and 6-hour driving course can waive the road test."},"es":{"q":"En Dakota del Norte, ¿cómo puede usted quedar exento del examen de manejo de la Clase D?","o":["Aprobar el examen escrito con una nota perfecta","Tener el permiso por dos años","Anotar 100 horas de manejo con un padre","Mostrar un certificado de un curso aprobado con 30 horas de clase y 6 horas al volante"],"h1":"Piense en un curso de manejo con horas de clase y horas manejando.","h2":"En Dakota del Norte se puede omitir el examen de manejo con un certificado de un curso aprobado de al menos 30 horas de clase y 6 horas de práctica al volante.","p":"Correcto. Un curso aprobado de 30 horas de clase y 6 horas al volante puede reemplazar el examen de manejo."},"zh":{"q":"在 North Dakota，怎样可以免考 D 类（Class D）路考？","o":["笔试拿满分","持学习驾照两年","和父母一起记录 100 小时驾驶","出示批准课程的证书，课程包括 30 小时课堂和 6 小时实际驾驶"],"h1":"想一想既有上课时间又有驾驶时间的驾驶培训课程。","h2":"在 North Dakota，如果你有批准课程的证书，课程至少包括 30 小时课堂和 6 小时实际驾驶培训，就可以免考路考。","p":"对。批准的 30 小时课堂加 6 小时驾驶课程可以免考路考。"},"vi":{"q":"Ở North Dakota, làm sao để được miễn bài thi lái xe thực hành hạng D (Class D)?","o":["Đậu bài thi lý thuyết với điểm tuyệt đối","Giữ giấy phép tập lái trong hai năm","Ghi lại 100 giờ lái xe với cha mẹ","Xuất trình chứng chỉ của một khóa học được chấp thuận có 30 giờ học trên lớp và 6 giờ lái xe thực tế"],"h1":"Hãy nghĩ đến một khóa đào tạo lái xe có cả giờ học trên lớp và giờ lái xe.","h2":"Ở North Dakota, bài thi lái xe thực hành có thể được miễn nếu bạn có chứng chỉ của một khóa học được chấp thuận gồm ít nhất 30 giờ học trên lớp và 6 giờ lái xe thực tế.","p":"Đúng. Khóa học được chấp thuận với 30 giờ trên lớp và 6 giờ lái xe có thể giúp miễn bài thi thực hành."},"tl":{"q":"Sa North Dakota, paano ka hindi na kukuha ng Class D road test?","o":["Pumasa sa knowledge test nang perpekto ang score","Hawakan ang permit mo nang dalawang taon","Magtala ng 100 oras ng pagmamaneho kasama ang magulang","Magpakita ng certificate mula sa aprubadong kurso na may 30 oras sa klase at 6 na oras sa likod ng manibela"],"h1":"Isipin ang isang kurso sa pagmamaneho na may oras sa klase at oras ng pagmamaneho.","h2":"Sa North Dakota, puwedeng hindi na kunin ang road test kung may certificate ka mula sa aprubadong kurso na may hindi bababa sa 30 oras sa klase at 6 na oras ng pagmamaneho.","p":"Tama. Ang aprubadong kurso na may 30 oras sa klase at 6 na oras ng pagmamaneho ay puwedeng pumalit sa road test."},"ar":{"q":"في North Dakota، كيف يمكن إعفاؤك من اختبار القيادة العملي للفئة D (Class D)؟","o":["أن تنجح في الاختبار النظري بالعلامة الكاملة","أن تحمل تصريحك لمدة سنتين","أن تسجّل 100 ساعة قيادة مع أحد الوالدين","أن تُظهر شهادة من دورة معتمدة فيها 30 ساعة دراسة في الصف و6 ساعات خلف المقود"],"h1":"فكّر في دورة تدريب على القيادة فيها وقت للدراسة ووقت للقيادة.","h2":"في North Dakota يمكن إعفاؤك من اختبار القيادة العملي بشهادة من دورة معتمدة فيها 30 ساعة دراسة في الصف على الأقل و6 ساعات تدريب خلف المقود.","p":"صحيح. دورة معتمدة فيها 30 ساعة في الصف و6 ساعات قيادة تُعفيك من الاختبار العملي."},"ref":{"doc":"ND","page":4}},{"id":"nd-038","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how many points can an approved driver improvement course, such as a defensive driving course, take off your record?","o":["1 point","3 points","6 points","All of your points"],"h1":"It is more than the one point you get back after three months with no new points.","h2":"In North Dakota finishing an approved driver improvement course takes 3 points off your driving record.","p":"Right. The course takes off 3 points."},"es":{"q":"En Dakota del Norte, ¿cuántos puntos puede quitar de su récord un curso aprobado de mejoramiento del conductor, como un curso de manejo defensivo?","o":["1 punto","3 puntos","6 puntos","Todos sus puntos"],"h1":"Es más que el punto que se quita después de tres meses sin puntos nuevos.","h2":"En Dakota del Norte terminar un curso aprobado de mejoramiento del conductor quita 3 puntos de su récord de manejo.","p":"Correcto. El curso quita 3 puntos."},"zh":{"q":"在 North Dakota，批准的驾驶改进课程（例如防御性驾驶课程）可以从你的记录上减掉多少分？","o":["1 分","3 分","6 分","你所有的分"],"h1":"比三个月没有新扣分后减回的 1 分要多。","h2":"在 North Dakota，完成批准的驾驶改进课程可以从你的驾驶记录上减掉 3 分。","p":"对。这个课程可以减掉 3 分。"},"vi":{"q":"Ở North Dakota, một khóa học cải thiện kỹ năng lái xe được chấp thuận, như khóa lái xe phòng vệ, có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["1 điểm","3 điểm","6 điểm","Tất cả số điểm của bạn"],"h1":"Nhiều hơn 1 điểm bạn được xóa sau ba tháng không có điểm mới.","h2":"Ở North Dakota, hoàn thành một khóa học cải thiện kỹ năng lái xe được chấp thuận sẽ xóa 3 điểm khỏi hồ sơ lái xe của bạn.","p":"Đúng. Khóa học xóa 3 điểm."},"tl":{"q":"Sa North Dakota, ilang puntos ang puwedeng mabawas sa iyong record ng isang aprubadong driver improvement course, gaya ng defensive driving course?","o":["1 punto","3 puntos","6 na puntos","Lahat ng iyong puntos"],"h1":"Mas marami ito kaysa sa isang puntong naibabalik pagkatapos ng tatlong buwan na walang bagong puntos.","h2":"Sa North Dakota, ang pagtapos ng aprubadong driver improvement course ay nagbabawas ng 3 puntos sa iyong driving record.","p":"Tama. Nagbabawas ang kurso ng 3 puntos."},"ar":{"q":"في North Dakota، كم نقطة يمكن أن تحذف من سجلك دورةٌ معتمدة لتحسين القيادة، مثل دورة القيادة الوقائية؟","o":["1 نقطة","3 نقاط","6 نقاط","كل نقاطك"],"h1":"العدد أكثر من النقطة الواحدة التي تُحذف بعد ثلاثة أشهر بلا نقاط جديدة.","h2":"في North Dakota إتمام دورة معتمدة لتحسين القيادة يحذف 3 نقاط من سجل قيادتك.","p":"صحيح. الدورة تحذف 3 نقاط."},"ref":{"doc":"ND","page":40}},{"id":"nd-039","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what is the fine for throwing litter on a public highway?","o":["$50","$100","$500","$1,000"],"h1":"It is several hundred dollars.","h2":"In North Dakota throwing litter on a public highway can bring a $500 fine.","p":"Right. Littering on a highway can cost $500."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por tirar basura en una carretera pública?","o":["$50","$100","$500","$1,000"],"h1":"Son varios cientos de dólares.","h2":"En Dakota del Norte tirar basura en una carretera pública puede costar una multa de $500.","p":"Correcto. Tirar basura en la carretera puede costar $500."},"zh":{"q":"在 North Dakota，在公共公路上乱扔垃圾的罚款是多少？","o":["$50","$100","$500","$1,000"],"h1":"是几百美元。","h2":"在 North Dakota，在公共公路上乱扔垃圾可能被罚款 $500。","p":"对。在公路上乱扔垃圾可能要付 $500。"},"vi":{"q":"Ở North Dakota, tiền phạt cho việc xả rác trên xa lộ công cộng là bao nhiêu?","o":["$50","$100","$500","$1,000"],"h1":"Vài trăm đô la.","h2":"Ở North Dakota, xả rác trên xa lộ công cộng có thể bị phạt $500.","p":"Đúng. Xả rác trên xa lộ có thể bị phạt $500."},"tl":{"q":"Sa North Dakota, magkano ang multa sa pagtatapon ng basura sa pampublikong highway?","o":["$50","$100","$500","$1,000"],"h1":"Ilang daang dolyar ito.","h2":"Sa North Dakota, ang pagtatapon ng basura sa pampublikong highway ay puwedeng magresulta sa multang $500.","p":"Tama. Puwedeng umabot sa $500 ang pagkakalat sa highway."},"ar":{"q":"في North Dakota، ما غرامة رمي النفايات على طريق سريع عام؟","o":["$50","$100","$500","$1,000"],"h1":"إنها بضع مئات من الدولارات.","h2":"في North Dakota قد يؤدي رمي النفايات على طريق سريع عام إلى غرامة قدرها $500.","p":"صحيح. رمي النفايات على الطريق السريع قد يكلّفك $500."},"ref":{"doc":"ND","page":27}},{"id":"nd-040","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the fine for driving onto a road that is officially closed because of dangerous conditions?","o":["$250","$50","$100","$1,000"],"h1":"It is more than $200.","h2":"In North Dakota driving onto a road that is officially closed for dangerous conditions brings a $250 fine.","p":"Right. Entering a closed road costs $250."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por entrar a una carretera cerrada oficialmente por condiciones peligrosas?","o":["$250","$50","$100","$1,000"],"h1":"Es más de $200.","h2":"En Dakota del Norte entrar a una carretera cerrada oficialmente por condiciones peligrosas trae una multa de $250.","p":"Correcto. Entrar a una carretera cerrada cuesta $250."},"zh":{"q":"在 North Dakota，开上因危险情况而被正式封闭的道路，罚款是多少？","o":["$250","$50","$100","$1,000"],"h1":"超过 $200。","h2":"在 North Dakota，开上因危险情况而被正式封闭的道路，会被罚款 $250。","p":"对。开进封闭的道路要罚 $250。"},"vi":{"q":"Ở North Dakota, tiền phạt cho việc lái xe vào một con đường đã chính thức bị đóng vì điều kiện nguy hiểm là bao nhiêu?","o":["$250","$50","$100","$1,000"],"h1":"Nhiều hơn $200.","h2":"Ở North Dakota, lái xe vào con đường đã chính thức bị đóng vì điều kiện nguy hiểm sẽ bị phạt $250.","p":"Đúng. Đi vào đường bị đóng bị phạt $250."},"tl":{"q":"Sa North Dakota, magkano ang multa sa pagmamaneho papasok sa daang opisyal na isinara dahil sa mapanganib na kalagayan?","o":["$250","$50","$100","$1,000"],"h1":"Higit ito sa $200.","h2":"Sa North Dakota, ang pagmamaneho papasok sa daang opisyal na isinara dahil sa mapanganib na kalagayan ay may multang $250.","p":"Tama. $250 ang multa sa pagpasok sa saradong daan."},"ar":{"q":"في North Dakota، ما غرامة القيادة على طريق مغلق رسميًا بسبب ظروف خطرة؟","o":["$250","$50","$100","$1,000"],"h1":"إنها أكثر من $200.","h2":"في North Dakota القيادة على طريق مغلق رسميًا بسبب ظروف خطرة تؤدي إلى غرامة قدرها $250.","p":"صحيح. دخول طريق مغلق يكلّف $250."},"ref":{"doc":"ND","page":27}},{"id":"nd-041","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, when may you use studded snow tires?","o":["All year","From November 1 to March 1","Only when snow is on the road","From October 15 to April 15"],"h1":"The season starts in the middle of October.","h2":"In North Dakota studded snow tires may be used from October 15 to April 15.","p":"Right. Studded tires are allowed from October 15 to April 15."},"es":{"q":"En Dakota del Norte, ¿cuándo puede usar llantas de nieve con clavos?","o":["Todo el año","Del 1 de noviembre al 1 de marzo","Solo cuando hay nieve en la carretera","Del 15 de octubre al 15 de abril"],"h1":"La temporada empieza a mediados de octubre.","h2":"En Dakota del Norte las llantas de nieve con clavos se pueden usar del 15 de octubre al 15 de abril.","p":"Correcto. Las llantas con clavos se permiten del 15 de octubre al 15 de abril."},"zh":{"q":"在 North Dakota，什么时候可以使用带钉的雪地轮胎？","o":["全年","11 月 1 日到 3 月 1 日","只有路上有雪的时候","10 月 15 日到 4 月 15 日"],"h1":"这个季节从十月中旬开始。","h2":"在 North Dakota，带钉的雪地轮胎可以在 10 月 15 日到 4 月 15 日使用。","p":"对。带钉轮胎可以在 10 月 15 日到 4 月 15 日使用。"},"vi":{"q":"Ở North Dakota, khi nào bạn được dùng lốp xe tuyết có đinh?","o":["Cả năm","Từ ngày 1 tháng 11 đến ngày 1 tháng 3","Chỉ khi có tuyết trên đường","Từ ngày 15 tháng 10 đến ngày 15 tháng 4"],"h1":"Mùa này bắt đầu vào giữa tháng Mười.","h2":"Ở North Dakota, lốp xe tuyết có đinh được dùng từ ngày 15 tháng 10 đến ngày 15 tháng 4.","p":"Đúng. Lốp có đinh được phép dùng từ ngày 15 tháng 10 đến ngày 15 tháng 4."},"tl":{"q":"Sa North Dakota, kailan ka puwedeng gumamit ng studded snow tires (gulong na may pako para sa niyebe)?","o":["Buong taon","Mula Nobyembre 1 hanggang Marso 1","Kapag may niyebe lang sa daan","Mula Oktubre 15 hanggang Abril 15"],"h1":"Nagsisimula ang panahon sa kalagitnaan ng Oktubre.","h2":"Sa North Dakota, puwedeng gamitin ang studded snow tires mula Oktubre 15 hanggang Abril 15.","p":"Tama. Pinapayagan ang studded tires mula Oktubre 15 hanggang Abril 15."},"ar":{"q":"في North Dakota، متى يجوز لك استخدام إطارات الثلج ذات المسامير؟","o":["طوال السنة","من 1 نوفمبر إلى 1 مارس","فقط عندما يكون الثلج على الطريق","من 15 أكتوبر إلى 15 أبريل"],"h1":"يبدأ الموسم في منتصف أكتوبر.","h2":"في North Dakota يجوز استخدام إطارات الثلج ذات المسامير من 15 أكتوبر إلى 15 أبريل.","p":"صحيح. الإطارات ذات المسامير مسموحة من 15 أكتوبر إلى 15 أبريل."},"ref":{"doc":"ND","page":28}},{"id":"nd-042","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, your car gets stuck in a snowstorm. What should you do?","o":["Walk to the nearest house for help","Stay with the car and run the engine and heater only for short times, with a window open a little","Run the engine the whole time with all windows closed","Leave the car and follow the road on foot"],"h1":"Most deaths happen when people leave their cars and get lost.","h2":"In North Dakota, if you are stuck in a snowstorm, you should stay with your car and run the engine and heater only for short times, with a window slightly open.","p":"Right. Stay with the car and run the heater only now and then, with a window open a little."},"es":{"q":"En Dakota del Norte, su carro se queda atascado en una tormenta de nieve. ¿Qué debe hacer?","o":["Caminar a la casa más cercana para pedir ayuda","Quedarse con el carro y prender el motor y la calefacción solo por ratos cortos, con una ventana un poco abierta","Dejar el motor prendido todo el tiempo con las ventanas cerradas","Dejar el carro y seguir la carretera a pie"],"h1":"La mayoría de las muertes ocurren cuando la gente deja el carro y se pierde.","h2":"En Dakota del Norte, si usted queda atascado en una tormenta de nieve, debe quedarse con el carro y prender el motor y la calefacción solo por ratos cortos, con una ventana un poco abierta.","p":"Correcto. Quédese con el carro y use la calefacción solo por ratos, con una ventana un poco abierta."},"zh":{"q":"在 North Dakota，你的车在暴风雪中被困住了。你应该怎么做？","o":["走到最近的房子求助","留在车里，只短时间开发动机和暖气，并把一扇窗户开一点","一直开着发动机，所有窗户都关上","离开车，沿着路步行"],"h1":"大多数死亡发生在人们离开车子并迷路的时候。","h2":"在 North Dakota，如果你在暴风雪中被困，你应该留在车里，只短时间开发动机和暖气，并把一扇窗户稍微打开。","p":"对。留在车里，只偶尔开暖气，并把窗户开一点。"},"vi":{"q":"Ở North Dakota, xe của bạn bị kẹt trong bão tuyết. Bạn nên làm gì?","o":["Đi bộ đến nhà gần nhất để nhờ giúp đỡ","Ở lại trong xe và chỉ nổ máy, bật máy sưởi từng lúc ngắn, với một cửa sổ hé mở một chút","Nổ máy suốt thời gian với tất cả cửa sổ đóng kín","Rời xe và đi bộ theo con đường"],"h1":"Phần lớn các ca tử vong xảy ra khi người ta rời xe và bị lạc.","h2":"Ở North Dakota, nếu bị kẹt trong bão tuyết, bạn nên ở lại trong xe và chỉ nổ máy, bật máy sưởi từng lúc ngắn, với một cửa sổ hé mở một chút.","p":"Đúng. Ở lại trong xe và chỉ thỉnh thoảng bật máy sưởi, với cửa sổ hé mở một chút."},"tl":{"q":"Sa North Dakota, naipit ang kotse mo sa snowstorm (bagyo ng niyebe). Ano ang dapat mong gawin?","o":["Maglakad papunta sa pinakamalapit na bahay para humingi ng tulong","Manatili sa kotse at paandarin ang makina at heater nang sandali lamang, na bahagyang nakabukas ang isang bintana","Paandarin ang makina nang tuloy-tuloy na sarado ang lahat ng bintana","Iwan ang kotse at sundan ang daan nang naglalakad"],"h1":"Karamihan ng namamatay ay umalis sa kanilang kotse at naligaw.","h2":"Sa North Dakota, kung naipit ka sa snowstorm, dapat kang manatili sa kotse at paandarin ang makina at heater nang sandali lamang, na bahagyang nakabukas ang isang bintana.","p":"Tama. Manatili sa kotse at paandarin ang heater paminsan-minsan lang, na bahagyang nakabukas ang bintana."},"ar":{"q":"في North Dakota، علقت سيارتك في عاصفة ثلجية. ماذا يجب أن تفعل؟","o":["أن تمشي إلى أقرب بيت لطلب المساعدة","أن تبقى مع السيارة وتشغّل المحرك والتدفئة لفترات قصيرة فقط، مع فتح نافذة قليلًا","أن تشغّل المحرك طوال الوقت وكل النوافذ مغلقة","أن تترك السيارة وتتبع الطريق مشيًا"],"h1":"تحدث معظم الوفيات عندما يترك الناس سياراتهم ويضلّون الطريق.","h2":"في North Dakota، إذا علقت في عاصفة ثلجية، يجب أن تبقى مع سيارتك وتشغّل المحرك والتدفئة لفترات قصيرة فقط، مع فتح نافذة قليلًا.","p":"صحيح. ابقَ مع السيارة وشغّل التدفئة من وقت لآخر فقط، مع فتح نافذة قليلًا."},"ref":{"doc":"ND","page":28}},{"id":"nd-043","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, a driver has a first offense in seven years with an alcohol level of 0.08 percent (below 0.18). How long is the license suspended?","o":["30 days","1 year","91 days","2 years"],"h1":"It is about three months.","h2":"In North Dakota a first offense in seven years at 0.08 percent or more, but below 0.18, brings a 91-day license suspension.","p":"Right. A first offense brings a 91-day suspension."},"es":{"q":"En Dakota del Norte, un conductor tiene una primera infracción en siete años con un nivel de alcohol de 0.08 por ciento (menos de 0.18). ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","1 año","91 días","2 años"],"h1":"Son unos tres meses.","h2":"En Dakota del Norte una primera infracción en siete años con 0.08 por ciento o más, pero menos de 0.18, trae una suspensión de la licencia de 91 días.","p":"Correcto. Una primera infracción trae una suspensión de 91 días."},"zh":{"q":"在 North Dakota，一名司机七年内第一次违规，酒精浓度为 0.08%（低于 0.18%）。驾照会被暂停多久？","o":["30 天","1 年","91 天","2 年"],"h1":"大约三个月。","h2":"在 North Dakota，七年内第一次违规，酒精浓度在 0.08% 或以上但低于 0.18%，驾照会被暂停 91 天。","p":"对。第一次违规会被暂停驾照 91 天。"},"vi":{"q":"Ở North Dakota, một người lái xe vi phạm lần đầu trong bảy năm với nồng độ cồn 0.08% (dưới 0.18%). Bằng lái bị đình chỉ bao lâu?","o":["30 ngày","1 năm","91 ngày","2 năm"],"h1":"Khoảng ba tháng.","h2":"Ở North Dakota, vi phạm lần đầu trong bảy năm với nồng độ cồn từ 0.08% trở lên nhưng dưới 0.18% sẽ bị đình chỉ bằng lái 91 ngày.","p":"Đúng. Vi phạm lần đầu bị đình chỉ 91 ngày."},"tl":{"q":"Sa North Dakota, unang paglabag ng isang driver sa loob ng pitong taon, na may alcohol level na 0.08% (mas mababa sa 0.18%). Gaano katagal masususpinde ang lisensya?","o":["30 araw","1 taon","91 araw","2 taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa North Dakota, ang unang paglabag sa loob ng pitong taon na may 0.08% o higit pa, pero mas mababa sa 0.18%, ay may 91 araw na suspensyon ng lisensya.","p":"Tama. 91 araw na suspensyon sa unang paglabag."},"ar":{"q":"في North Dakota، سائق ارتكب أول مخالفة له خلال سبع سنوات بنسبة كحول 0.08% (أقل من 0.18%). كم مدة تعليق الرخصة؟","o":["30 يومًا","1 سنة","91 يومًا","2 سنة"],"h1":"المدة حوالي ثلاثة أشهر.","h2":"في North Dakota أول مخالفة خلال سبع سنوات بنسبة كحول 0.08% أو أكثر، لكن أقل من 0.18%، تؤدي إلى تعليق الرخصة لمدة 91 يومًا.","p":"صحيح. أول مخالفة تؤدي إلى تعليق الرخصة لمدة 91 يومًا."},"ref":{"doc":"ND","page":36}},{"id":"nd-044","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, what is the penalty for the driver when a child is not buckled in as the child passenger law requires?","o":["A $25 fine and one point on the license","A warning only","A $500 fine and a license suspension","Two points and no fine"],"h1":"The fine is small, but it also goes on your record.","h2":"In North Dakota breaking the child passenger safety law costs the driver a $25 fine and one point on the license.","p":"Right. It is a $25 fine and one point."},"es":{"q":"En Dakota del Norte, ¿cuál es la sanción para el conductor cuando un niño no va asegurado como exige la ley de pasajeros infantiles?","o":["Una multa de $25 y un punto en la licencia","Solo una advertencia","Una multa de $500 y la suspensión de la licencia","Dos puntos y ninguna multa"],"h1":"La multa es pequeña, pero también va a su récord.","h2":"En Dakota del Norte violar la ley de seguridad de pasajeros infantiles le cuesta al conductor una multa de $25 y un punto en la licencia.","p":"Correcto. Es una multa de $25 y un punto."},"zh":{"q":"在 North Dakota，如果孩子没有按照儿童乘客法的要求系好安全带，司机会受到什么处罚？","o":["罚款 $25，驾照记一分","只有警告","罚款 $500 并暂停驾照","记两分，不罚款"],"h1":"罚款不多，但也会记在你的记录上。","h2":"在 North Dakota，违反儿童乘客安全法，司机会被罚款 $25，驾照记一分。","p":"对。罚款 $25，记一分。"},"vi":{"q":"Ở North Dakota, hình phạt cho người lái xe là gì khi trẻ em không được thắt dây an toàn theo luật về hành khách trẻ em?","o":["Phạt $25 và một điểm trên bằng lái","Chỉ cảnh cáo","Phạt $500 và đình chỉ bằng lái","Hai điểm và không bị phạt tiền"],"h1":"Tiền phạt nhỏ, nhưng cũng được ghi vào hồ sơ của bạn.","h2":"Ở North Dakota, vi phạm luật an toàn hành khách trẻ em khiến người lái xe bị phạt $25 và một điểm trên bằng lái.","p":"Đúng. Phạt $25 và một điểm."},"tl":{"q":"Sa North Dakota, ano ang parusa sa driver kapag hindi naka-buckle ang bata ayon sa child passenger law?","o":["Multang $25 at isang punto sa lisensya","Babala lamang","Multang $500 at suspensyon ng lisensya","Dalawang puntos at walang multa"],"h1":"Maliit ang multa, pero napupunta rin ito sa iyong record.","h2":"Sa North Dakota, ang paglabag sa child passenger safety law ay may multang $25 at isang punto sa lisensya ng driver.","p":"Tama. Multang $25 at isang punto."},"ar":{"q":"في North Dakota، ما عقوبة السائق عندما لا يكون الطفل مربوطًا بالحزام كما يشترط قانون سلامة الأطفال الركاب؟","o":["غرامة $25 ونقطة واحدة على الرخصة","إنذار فقط","غرامة $500 وتعليق الرخصة","نقطتان ولا غرامة"],"h1":"الغرامة صغيرة، لكنها تُسجَّل أيضًا في سجلك.","h2":"في North Dakota مخالفة قانون سلامة الأطفال الركاب تكلّف السائق غرامة $25 ونقطة واحدة على الرخصة.","p":"صحيح. غرامة $25 ونقطة واحدة."},"ref":{"doc":"ND","page":34}},{"id":"nd-045","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, in rain, snow or fog, you should turn on your headlights when you cannot see clearly for how far?","o":["200 feet","500 feet","2,000 feet","1,000 feet"],"h1":"It is a little less than a fifth of a mile.","h2":"In North Dakota you should use your headlights in bad weather when you cannot see clearly for 1,000 feet.","p":"Right. Lights on when you cannot see 1,000 feet ahead."},"es":{"q":"En Dakota del Norte, con lluvia, nieve o niebla, ¿debe prender las luces delanteras cuando no puede ver con claridad a qué distancia?","o":["200 pies","500 pies","2,000 pies","1,000 pies"],"h1":"Es un poco menos de un quinto de milla.","h2":"En Dakota del Norte usted debe usar las luces delanteras con mal tiempo cuando no puede ver con claridad a 1,000 pies.","p":"Correcto. Prenda las luces cuando no pueda ver a 1,000 pies."},"zh":{"q":"在 North Dakota，下雨、下雪或有雾时，如果你在多远的距离内看不清楚，就应该打开大灯？","o":["200 英尺","500 英尺","2,000 英尺","1,000 英尺"],"h1":"比五分之一英里少一点。","h2":"在 North Dakota，天气不好时，如果你看不清 1,000 英尺远的地方，就应该打开大灯。","p":"对。看不清前方 1,000 英尺时就开灯。"},"vi":{"q":"Ở North Dakota, khi trời mưa, có tuyết hoặc sương mù, bạn nên bật đèn pha khi không thể nhìn rõ trong khoảng cách bao xa?","o":["200 feet","500 feet","2,000 feet","1,000 feet"],"h1":"Ít hơn một phần năm dặm một chút.","h2":"Ở North Dakota, bạn nên bật đèn pha khi thời tiết xấu và bạn không thể nhìn rõ trong khoảng 1,000 feet.","p":"Đúng. Bật đèn khi bạn không thể nhìn thấy 1,000 feet phía trước."},"tl":{"q":"Sa North Dakota, kapag umuulan, may niyebe o may hamog, dapat mong buksan ang headlights kapag hindi ka makakita nang malinaw sa layong gaano kalayo?","o":["200 talampakan","500 talampakan","2,000 talampakan","1,000 talampakan"],"h1":"Medyo kulang ito sa ikalimang bahagi ng isang milya.","h2":"Sa North Dakota, dapat mong gamitin ang headlights sa masamang panahon kapag hindi ka makakita nang malinaw sa layong 1,000 talampakan.","p":"Tama. Buksan ang ilaw kapag hindi mo makita ang 1,000 talampakan sa unahan."},"ar":{"q":"في North Dakota، في المطر أو الثلج أو الضباب، يجب أن تشغّل المصابيح الأمامية عندما لا ترى بوضوح لأي مسافة؟","o":["200 قدم","500 قدم","2,000 قدم","1,000 قدم"],"h1":"المسافة أقل قليلًا من خُمس ميل.","h2":"في North Dakota يجب أن تستخدم المصابيح الأمامية في الطقس السيئ عندما لا ترى بوضوح لمسافة 1,000 قدم.","p":"صحيح. شغّل المصابيح عندما لا ترى 1,000 قدم أمامك."},"ref":{"doc":"ND","page":24}},{"id":"nd-046","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, what is the speed limit in a business or residential district when no sign says otherwise?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is a quarter of 100.","h2":"In North Dakota the speed limit in a business or residential district is 25 mph unless a sign says otherwise.","p":"Right. It is 25 mph in town unless posted."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando no hay un letrero que diga otra cosa?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es la cuarta parte de 100.","h2":"En Dakota del Norte el límite de velocidad en una zona comercial o residencial es de 25 mph, a menos que un letrero diga otra cosa.","p":"Correcto. Son 25 mph en la ciudad si no hay otro letrero."},"zh":{"q":"在 North Dakota，没有标志另外规定时，商业区或住宅区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"是 100 的四分之一。","h2":"在 North Dakota，除非有标志另外规定，商业区或住宅区的限速是 25 mph。","p":"对。除非有标志，市区限速是 25 mph。"},"vi":{"q":"Ở North Dakota, tốc độ giới hạn trong khu thương mại hoặc khu dân cư là bao nhiêu khi không có biển báo khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Đó là một phần tư của 100.","h2":"Ở North Dakota, tốc độ giới hạn trong khu thương mại hoặc khu dân cư là 25 mph, trừ khi có biển báo khác.","p":"Đúng. Trong thị trấn là 25 mph, trừ khi có biển báo."},"tl":{"q":"Sa North Dakota, ano ang speed limit sa business o residential district kapag walang karatulang nagsasabi ng iba?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Ito ay isang-kapat ng 100.","h2":"Sa North Dakota, ang speed limit sa business o residential district ay 25 mph maliban kung iba ang sinasabi ng karatula.","p":"Tama. 25 mph sa bayan maliban kung may karatula."},"ar":{"q":"في North Dakota، ما حد السرعة في منطقة تجارية أو سكنية عندما لا تُظهر لافتة حدًا مختلفًا؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"إنه ربع 100.","h2":"في North Dakota حد السرعة في المنطقة التجارية أو السكنية هو 25 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. الحد داخل البلدة 25 mph ما لم تُظهر لافتة غير ذلك."},"ref":{"doc":"ND","page":20}},{"id":"nd-047","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, you are coming up to a railroad crossing and your view of the track is blocked. What is the speed limit, unless a sign says otherwise?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"It is the same as the limit near a school at recess.","h2":"In North Dakota the speed limit is 20 mph when you approach a railroad crossing and cannot see the track clearly, unless a sign says otherwise.","p":"Right. Slow to 20 mph when you cannot see the track."},"es":{"q":"En Dakota del Norte, usted se acerca a un cruce de ferrocarril y no puede ver bien la vía. ¿Cuál es el límite de velocidad, a menos que un letrero diga otra cosa?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"Es igual al límite cerca de una escuela durante el recreo.","h2":"En Dakota del Norte el límite de velocidad es de 20 mph al acercarse a un cruce de ferrocarril cuando no puede ver bien la vía, a menos que un letrero diga otra cosa.","p":"Correcto. Baje a 20 mph cuando no pueda ver la vía."},"zh":{"q":"在 North Dakota，你快到铁路道口，而你看铁轨的视线被挡住了。除非有标志另外规定，限速是多少？","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"和学校课间休息时附近的限速一样。","h2":"在 North Dakota，当你接近铁路道口而看不清铁轨时，除非有标志另外规定，限速是 20 mph。","p":"对。看不清铁轨时，减速到 20 mph。"},"vi":{"q":"Ở North Dakota, bạn đang đến gần chỗ băng qua đường ray xe lửa và tầm nhìn đường ray bị che khuất. Tốc độ giới hạn là bao nhiêu, trừ khi có biển báo khác?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"Giống với giới hạn gần trường học vào giờ ra chơi.","h2":"Ở North Dakota, tốc độ giới hạn là 20 mph khi bạn đến gần chỗ băng qua đường ray xe lửa mà không thể nhìn rõ đường ray, trừ khi có biển báo khác.","p":"Đúng. Giảm xuống 20 mph khi bạn không thể nhìn thấy đường ray."},"tl":{"q":"Sa North Dakota, papalapit ka sa railroad crossing (tawiran ng tren) at may humaharang sa tanaw mo sa riles. Ano ang speed limit, maliban kung iba ang sinasabi ng karatula?","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"Pareho ito ng limit malapit sa paaralan tuwing recess.","h2":"Sa North Dakota, 20 mph ang speed limit kapag papalapit ka sa railroad crossing at hindi mo makita nang malinaw ang riles, maliban kung iba ang sinasabi ng karatula.","p":"Tama. Bumagal sa 20 mph kapag hindi mo makita ang riles."},"ar":{"q":"في North Dakota، تقترب من معبر سكة حديد ورؤيتك للسكة محجوبة. ما حد السرعة ما لم تُظهر لافتة حدًا مختلفًا؟","o":["10 mph","30 mph","20 mph","35 mph"],"h1":"إنه نفس الحد قرب المدرسة في وقت الاستراحة.","h2":"في North Dakota حد السرعة 20 mph عندما تقترب من معبر سكة حديد ولا ترى السكة بوضوح، ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. خفّف السرعة إلى 20 mph عندما لا ترى السكة."},"ref":{"doc":"ND","page":20}},{"id":"nd-048","scope":"ND","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Dakota, what is the speed limit on a paved, divided highway with more than one lane each way (not an interstate), unless a sign says otherwise?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"It is 10 mph less than on rural interstates.","h2":"In North Dakota the speed limit on a paved, divided multi-lane highway is 70 mph unless a sign says otherwise.","p":"Right. It is 70 mph on divided multi-lane highways."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en una carretera pavimentada y dividida con más de un carril en cada sentido (que no es interestatal), a menos que un letrero diga otra cosa?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"Es 10 mph menos que en las interestatales rurales.","h2":"En Dakota del Norte el límite de velocidad en una carretera pavimentada y dividida de varios carriles es de 70 mph, a menos que un letrero diga otra cosa.","p":"Correcto. Son 70 mph en carreteras divididas de varios carriles."},"zh":{"q":"在 North Dakota，在每个方向有一条以上车道的铺面分隔公路（不是州际公路）上，除非有标志另外规定，限速是多少？","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"比乡村州际公路的限速少 10 mph。","h2":"在 North Dakota，除非有标志另外规定，铺面的分隔多车道公路限速是 70 mph。","p":"对。分隔的多车道公路限速是 70 mph。"},"vi":{"q":"Ở North Dakota, tốc độ giới hạn trên xa lộ trải nhựa có dải phân cách và có nhiều hơn một làn mỗi chiều (không phải xa lộ liên bang) là bao nhiêu, trừ khi có biển báo khác?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"Ít hơn 10 mph so với xa lộ liên bang ở vùng nông thôn.","h2":"Ở North Dakota, tốc độ giới hạn trên xa lộ trải nhựa nhiều làn có dải phân cách là 70 mph, trừ khi có biển báo khác.","p":"Đúng. Trên xa lộ nhiều làn có dải phân cách là 70 mph."},"tl":{"q":"Sa North Dakota, ano ang speed limit sa sementadong divided highway na may higit sa isang lane bawat direksyon (hindi interstate), maliban kung iba ang sinasabi ng karatula?","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"Mas mababa ito nang 10 mph kaysa sa mga rural interstate.","h2":"Sa North Dakota, ang speed limit sa sementadong divided highway na maraming lane ay 70 mph maliban kung iba ang sinasabi ng karatula.","p":"Tama. 70 mph sa mga divided highway na maraming lane."},"ar":{"q":"في North Dakota، ما حد السرعة على طريق سريع معبّد ومقسوم فيه أكثر من مسار واحد في كل اتجاه (ليس طريقًا سريعًا بين الولايات)، ما لم تُظهر لافتة حدًا مختلفًا؟","o":["55 mph","65 mph","80 mph","70 mph"],"h1":"إنه أقل بـ 10 mph من حد الطرق السريعة بين الولايات في المناطق الريفية.","h2":"في North Dakota حد السرعة على الطريق السريع المعبّد والمقسوم ذي المسارات المتعددة هو 70 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. الحد 70 mph على الطرق السريعة المقسومة ذات المسارات المتعددة."},"ref":{"doc":"ND","page":20}},{"id":"nd-049","scope":"ND","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Dakota, how close to a stop sign or a traffic signal at the side of the road may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In North Dakota you may not park within 15 feet of a stop sign, a flashing beacon or a traffic signal at the side of the road.","p":"Right. Stay at least 15 feet from a stop sign or signal."},"es":{"q":"En Dakota del Norte, ¿qué tan cerca de un letrero de alto o de un semáforo al lado de la calle puede estacionarse?","o":["A no menos de 15 pies","A no menos de 5 pies","A no menos de 30 pies","A no menos de 50 pies"],"h1":"Es más que la distancia para un hidrante.","h2":"En Dakota del Norte usted no puede estacionarse a menos de 15 pies de un letrero de alto, una luz intermitente o un semáforo al lado de la calle.","p":"Correcto. Quédese por lo menos a 15 pies de un letrero de alto o un semáforo."},"zh":{"q":"在 North Dakota，停车时离停车标志或路边的交通信号灯最近可以多近？","o":["不能近于 15 英尺","不能近于 5 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"比离消防栓的距离更远。","h2":"在 North Dakota，你不可以把车停在离停车标志、闪光信号灯或路边交通信号灯 15 英尺以内的地方。","p":"对。离停车标志或信号灯至少 15 英尺。"},"vi":{"q":"Ở North Dakota, bạn được đỗ xe gần biển báo dừng (stop sign) hoặc đèn giao thông bên lề đường đến mức nào?","o":["Không gần hơn 15 feet","Không gần hơn 5 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Xa hơn khoảng cách đối với trụ nước cứu hỏa.","h2":"Ở North Dakota, bạn không được đỗ xe trong vòng 15 feet tính từ biển báo dừng, đèn báo nhấp nháy hoặc đèn giao thông bên lề đường.","p":"Đúng. Hãy cách biển báo dừng hoặc đèn giao thông ít nhất 15 feet."},"tl":{"q":"Sa North Dakota, gaano kalapit sa stop sign o traffic signal sa gilid ng daan ka puwedeng pumarada?","o":["Hindi lalapit sa 15 talampakan","Hindi lalapit sa 5 talampakan","Hindi lalapit sa 30 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas malayo ito kaysa sa layo para sa fire hydrant.","h2":"Sa North Dakota, bawal kang pumarada sa loob ng 15 talampakan mula sa stop sign, kumikislap na ilaw (flashing beacon) o traffic signal sa gilid ng daan.","p":"Tama. Lumayo nang hindi bababa sa 15 talampakan mula sa stop sign o signal."},"ar":{"q":"في North Dakota، كم يمكن أن تقترب عند الركن من لافتة قف أو إشارة مرور على جانب الطريق؟","o":["ليس أقرب من 15 قدمًا","ليس أقرب من 5 أقدام","ليس أقرب من 30 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"المسافة أكبر من المسافة المطلوبة عن صنبور إطفاء الحريق.","h2":"في North Dakota لا يجوز لك أن تركن سيارتك على بعد أقل من 15 قدمًا من لافتة قف أو ضوء وامض أو إشارة مرور على جانب الطريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من لافتة قف أو إشارة المرور."},"ref":{"doc":"ND","page":26}},{"id":"nd-050","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, you are passing on a two-lane road. How far ahead of an oncoming vehicle should you be back in your own lane?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 1,000 feet"],"h1":"It is about the length of ten cars.","h2":"In North Dakota you should finish passing and be back in your lane at least 200 feet before you meet an oncoming vehicle.","p":"Right. Be back in your lane at least 200 feet before oncoming traffic."},"es":{"q":"En Dakota del Norte, usted está rebasando en una carretera de dos carriles. ¿A qué distancia de un vehículo que viene de frente debe estar ya de vuelta en su carril?","o":["Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 200 pies","Por lo menos 1,000 pies"],"h1":"Es más o menos el largo de diez carros.","h2":"En Dakota del Norte usted debe terminar de rebasar y estar de vuelta en su carril por lo menos 200 pies antes de encontrarse con un vehículo que viene de frente.","p":"Correcto. Vuelva a su carril por lo menos 200 pies antes del tráfico que viene de frente."},"zh":{"q":"在 North Dakota，你在双车道道路上超车。你应该在离对面来车多远之前回到自己的车道？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 1,000 英尺"],"h1":"大约十辆车的长度。","h2":"在 North Dakota，你应该在遇到对面来车之前至少 200 英尺完成超车并回到自己的车道。","p":"对。在对面来车前至少 200 英尺回到自己的车道。"},"vi":{"q":"Ở North Dakota, bạn đang vượt xe trên đường hai làn. Bạn nên trở về làn của mình khi còn cách xe chạy ngược chiều bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 1,000 feet"],"h1":"Khoảng chiều dài của mười chiếc xe.","h2":"Ở North Dakota, bạn nên vượt xong và trở về làn của mình khi còn cách xe chạy ngược chiều ít nhất 200 feet.","p":"Đúng. Trở về làn của bạn khi còn cách xe ngược chiều ít nhất 200 feet."},"tl":{"q":"Sa North Dakota, nag-o-overtake ka sa daang may dalawang lane. Gaano kalayo dapat sa paparating na sasakyan ay nakabalik ka na sa iyong lane?","o":["Hindi bababa sa 50 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 200 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Mga haba ito ng sampung kotse.","h2":"Sa North Dakota, dapat tapos ka nang mag-overtake at nakabalik na sa iyong lane nang hindi bababa sa 200 talampakan bago mo makasalubong ang paparating na sasakyan.","p":"Tama. Bumalik sa iyong lane nang hindi bababa sa 200 talampakan bago ang paparating na sasakyan."},"ar":{"q":"في North Dakota، تتجاوز سيارة على طريق من مسارين. على أي مسافة من المركبة القادمة من الاتجاه المعاكس يجب أن تكون قد عدت إلى مسارك؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","1,000 قدم على الأقل"],"h1":"المسافة تقارب طول عشر سيارات.","h2":"في North Dakota يجب أن تُنهي التجاوز وتعود إلى مسارك قبل 200 قدم على الأقل من المركبة القادمة من الاتجاه المعاكس.","p":"صحيح. عُد إلى مسارك قبل 200 قدم على الأقل من المركبة القادمة."},"ref":{"doc":"ND","page":21}},{"id":"nd-051","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on a two-lane road, a police car is parked at a crash with its emergency lights flashing. No officer is directing traffic. What must you do?","o":["Keep going at the same speed","Drive to the right side of the road and stop, then pass with care when the road is clear","Honk and pass quickly","Stop in your lane until the police car leaves"],"h1":"First you stop at the edge of the road; then you may go on carefully.","h2":"In North Dakota you must drive to the right side of the road and stop for an emergency vehicle parked at a crash with its lights flashing, then you may pass with care when the road is clear.","p":"Right. Pull right and stop, then pass with care when it is clear."},"es":{"q":"En Dakota del Norte, en una carretera de dos carriles, un carro de policía está estacionado en un choque con sus luces de emergencia encendidas. Ningún oficial dirige el tráfico. ¿Qué debe hacer?","o":["Seguir a la misma velocidad","Ir al lado derecho de la carretera y detenerse, y luego pasar con cuidado cuando el camino esté libre","Tocar la bocina y pasar rápido","Detenerse en su carril hasta que el carro de policía se vaya"],"h1":"Primero se detiene a la orilla del camino; después puede seguir con cuidado.","h2":"En Dakota del Norte usted debe ir al lado derecho de la carretera y detenerse ante un vehículo de emergencia estacionado en un choque con las luces encendidas, y luego puede pasar con cuidado cuando el camino esté libre.","p":"Correcto. Oríllese a la derecha y deténgase, y luego pase con cuidado cuando esté libre."},"zh":{"q":"在 North Dakota，在双车道道路上，一辆警车停在车祸现场，紧急灯在闪。没有警察指挥交通。你必须怎么做？","o":["保持同样的速度继续开","开到道路右侧停车，然后在路上没有车时小心通过","按喇叭并快速通过","在你的车道停下，直到警车离开"],"h1":"先在路边停车，然后才可以小心继续开。","h2":"在 North Dakota，遇到停在车祸现场、紧急灯在闪的紧急车辆时，你必须开到道路右侧停车，然后在路上没有车时可以小心通过。","p":"对。靠右停车，然后在路上没有车时小心通过。"},"vi":{"q":"Ở North Dakota, trên đường hai làn, một xe cảnh sát đang đỗ tại hiện trường tai nạn với đèn khẩn cấp nhấp nháy. Không có cảnh sát điều khiển giao thông. Bạn phải làm gì?","o":["Tiếp tục chạy với cùng tốc độ","Lái sang bên phải đường và dừng lại, rồi cẩn thận vượt qua khi đường thông thoáng","Bóp còi và vượt qua thật nhanh","Dừng lại trong làn của bạn cho đến khi xe cảnh sát rời đi"],"h1":"Trước tiên bạn dừng ở mép đường; sau đó bạn có thể cẩn thận đi tiếp.","h2":"Ở North Dakota, bạn phải lái sang bên phải đường và dừng lại khi gặp xe khẩn cấp đang đỗ tại hiện trường tai nạn với đèn nhấp nháy, sau đó bạn có thể cẩn thận vượt qua khi đường thông thoáng.","p":"Đúng. Tấp vào bên phải và dừng lại, rồi cẩn thận vượt qua khi đường thông thoáng."},"tl":{"q":"Sa North Dakota, sa daang may dalawang lane, may police car na nakaparada sa isang aksidente at kumikislap ang emergency lights nito. Walang pulis na nagmamando ng trapiko. Ano ang dapat mong gawin?","o":["Tumuloy sa parehong bilis","Pumunta sa kanang gilid ng daan at huminto, saka dumaan nang maingat kapag maluwag na ang daan","Bumusina at dumaan nang mabilis","Huminto sa iyong lane hanggang umalis ang police car"],"h1":"Una, huminto ka sa gilid ng daan; saka ka puwedeng tumuloy nang maingat.","h2":"Sa North Dakota, dapat kang pumunta sa kanang gilid ng daan at huminto para sa emergency vehicle na nakaparada sa aksidente na kumikislap ang ilaw, saka ka puwedeng dumaan nang maingat kapag maluwag na ang daan.","p":"Tama. Tumabi sa kanan at huminto, saka dumaan nang maingat kapag maluwag na."},"ar":{"q":"في North Dakota، على طريق من مسارين، سيارة شرطة متوقفة عند حادث وأضواء الطوارئ فيها تومض. لا يوجد شرطي ينظّم المرور. ماذا يجب أن تفعل؟","o":["أن تستمر بنفس السرعة","أن تقود إلى الجانب الأيمن من الطريق وتتوقف، ثم تمر بحذر عندما يكون الطريق خاليًا","أن تستخدم البوق وتمر بسرعة","أن تتوقف في مسارك حتى تغادر سيارة الشرطة"],"h1":"أولًا تتوقف عند طرف الطريق، ثم يمكنك أن تتابع بحذر.","h2":"في North Dakota يجب أن تقود إلى الجانب الأيمن من الطريق وتتوقف لمركبة طوارئ متوقفة عند حادث وأضواؤها تومض، ثم يمكنك أن تمر بحذر عندما يكون الطريق خاليًا.","p":"صحيح. اتجه إلى اليمين وتوقف، ثم مُرّ بحذر عندما يكون الطريق خاليًا."},"ref":{"doc":"ND","page":20}},{"id":"nd-052","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, which vehicles must always stop at a railroad crossing, so you should not pass them there?","o":["Only vehicles pulling a trailer","Only motorcycles","All pickup trucks","School buses, buses with passengers, and trucks carrying fuel or explosives"],"h1":"Think of vehicles that carry children, many people, or dangerous loads.","h2":"In North Dakota school buses, buses carrying passengers, and vehicles carrying explosives or flammable liquids must stop between 15 and 50 feet from the tracks, so you should not pass them there.","p":"Right. School buses, passenger buses, and fuel or explosive trucks always stop at the tracks."},"es":{"q":"En Dakota del Norte, ¿qué vehículos deben detenerse siempre en un cruce de ferrocarril, por lo que usted no debe rebasarlos allí?","o":["Solo los vehículos que jalan un remolque","Solo las motocicletas","Todas las camionetas pickup","Los autobuses escolares, los autobuses con pasajeros y los camiones con combustible o explosivos"],"h1":"Piense en vehículos que llevan niños, mucha gente o cargas peligrosas.","h2":"En Dakota del Norte los autobuses escolares, los autobuses con pasajeros y los vehículos con explosivos o líquidos inflamables deben detenerse a entre 15 y 50 pies de la vía, por lo que usted no debe rebasarlos allí.","p":"Correcto. Los autobuses escolares, los de pasajeros y los camiones con combustible o explosivos siempre se detienen en la vía."},"zh":{"q":"在 North Dakota，哪些车辆在铁路道口一定要停车，所以你不应该在那里超过它们？","o":["只有拖着拖车的车辆","只有摩托车","所有皮卡车","校车、载客的公共汽车，以及运送燃料或爆炸物的卡车"],"h1":"想一想载着孩子、很多人或危险货物的车辆。","h2":"在 North Dakota，校车、载客的公共汽车，以及运送爆炸物或易燃液体的车辆，必须在离铁轨 15 到 50 英尺的地方停车，所以你不应该在那里超过它们。","p":"对。校车、载客公共汽车和运送燃料或爆炸物的卡车在铁轨前一定会停车。"},"vi":{"q":"Ở North Dakota, những xe nào luôn phải dừng lại ở chỗ băng qua đường ray xe lửa, vì vậy bạn không nên vượt chúng ở đó?","o":["Chỉ những xe kéo rơ-moóc","Chỉ xe máy","Tất cả xe bán tải","Xe buýt trường học, xe buýt chở khách, và xe tải chở nhiên liệu hoặc chất nổ"],"h1":"Hãy nghĩ đến những xe chở trẻ em, nhiều người hoặc hàng nguy hiểm.","h2":"Ở North Dakota, xe buýt trường học, xe buýt chở khách, và xe chở chất nổ hoặc chất lỏng dễ cháy phải dừng lại cách đường ray từ 15 đến 50 feet, vì vậy bạn không nên vượt chúng ở đó.","p":"Đúng. Xe buýt trường học, xe buýt chở khách, và xe tải chở nhiên liệu hoặc chất nổ luôn dừng lại ở đường ray."},"tl":{"q":"Sa North Dakota, aling mga sasakyan ang laging dapat huminto sa railroad crossing, kaya hindi mo sila dapat i-overtake doon?","o":["Mga sasakyang humihila ng trailer lamang","Mga motorsiklo lamang","Lahat ng pickup truck","Mga school bus, mga bus na may pasahero, at mga truck na may dalang gasolina o pampasabog"],"h1":"Isipin ang mga sasakyang may dalang mga bata, maraming tao, o mapanganib na karga.","h2":"Sa North Dakota, ang mga school bus, mga bus na may pasahero, at mga sasakyang may dalang pampasabog o likidong madaling magliyab ay dapat huminto nang 15 hanggang 50 talampakan mula sa riles, kaya hindi mo sila dapat i-overtake doon.","p":"Tama. Laging humihinto sa riles ang mga school bus, bus na may pasahero, at truck na may gasolina o pampasabog."},"ar":{"q":"في North Dakota، ما المركبات التي يجب أن تتوقف دائمًا عند معبر سكة الحديد، ولذلك يجب ألّا تتجاوزها هناك؟","o":["المركبات التي تجرّ مقطورة فقط","الدراجات النارية فقط","كل الشاحنات الصغيرة (pickup)","الحافلات المدرسية، والحافلات التي تنقل ركابًا، والشاحنات التي تنقل الوقود أو المتفجرات"],"h1":"فكّر في المركبات التي تنقل أطفالًا أو أشخاصًا كثيرين أو حمولات خطرة.","h2":"في North Dakota يجب أن تتوقف الحافلات المدرسية، والحافلات التي تنقل ركابًا، والمركبات التي تنقل متفجرات أو سوائل قابلة للاشتعال على بعد 15 إلى 50 قدمًا من السكة، ولذلك يجب ألّا تتجاوزها هناك.","p":"صحيح. الحافلات المدرسية وحافلات الركاب وشاحنات الوقود أو المتفجرات تتوقف دائمًا عند السكة."},"ref":{"doc":"ND","page":18}},{"id":"nd-053","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, after how many days in a row of living in the state are you counted as a resident for driver licensing?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about three months.","h2":"In North Dakota a person who has lived in the state for 90 days in a row is counted as a resident for driver licensing.","p":"Right. After 90 days in a row you are a resident."},"es":{"q":"En Dakota del Norte, ¿después de cuántos días seguidos viviendo en el estado se le considera residente para la licencia de manejo?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos tres meses.","h2":"En Dakota del Norte una persona que ha vivido en el estado 90 días seguidos se considera residente para la licencia de manejo.","p":"Correcto. Después de 90 días seguidos usted es residente."},"ref":{"doc":"ND","page":2}},{"id":"nd-054","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, children under what age should ride in the back seat, even if the car has no air bag?","o":["Under 13","Under 8","Under 10","Under 16"],"h1":"It is the age when a child becomes a teenager.","h2":"In North Dakota children under age 13 should ride in the back seat, even if the vehicle has no air bag.","p":"Right. Children under 13 belong in the back seat."},"es":{"q":"En Dakota del Norte, ¿los niños menores de qué edad deben ir en el asiento trasero, aunque el carro no tenga bolsa de aire?","o":["Menores de 13 años","Menores de 8 años","Menores de 10 años","Menores de 16 años"],"h1":"Es la edad en que un niño se vuelve adolescente.","h2":"En Dakota del Norte los niños menores de 13 años deben ir en el asiento trasero, aunque el vehículo no tenga bolsa de aire.","p":"Correcto. Los niños menores de 13 años van en el asiento trasero."},"ref":{"doc":"ND","page":34}},{"id":"nd-055","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, who must wear a seat belt?","o":["Only the driver","Only people in the front seat","Only children under 18","Everyone in the vehicle, in every seat"],"h1":"The law does not depend on where you sit.","h2":"In North Dakota the seat belt law requires everyone in the vehicle, in every seat, to wear a seat belt.","p":"Right. Everyone in every seat must buckle up."},"es":{"q":"En Dakota del Norte, ¿quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo las personas en el asiento delantero","Solo los menores de 18 años","Todos en el vehículo, en cada asiento"],"h1":"La ley no depende de dónde se siente.","h2":"En Dakota del Norte la ley del cinturón exige que todos en el vehículo, en cada asiento, usen el cinturón de seguridad.","p":"Correcto. Todos, en cada asiento, deben abrocharse."},"ref":{"doc":"ND","page":34}},{"id":"nd-056","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a visitor has a valid license from their home state. How old must they be to drive in North Dakota?","o":["At least 14","At least 16","At least 18","At least 21"],"h1":"It is the same age at which a North Dakota teen can get an unrestricted license.","h2":"In North Dakota a non-resident with a valid home-state license must be at least 16 years old to drive.","p":"Right. A visiting driver must be at least 16."},"es":{"q":"En Dakota del Norte, un visitante tiene una licencia válida de su estado. ¿Qué edad debe tener para manejar en Dakota del Norte?","o":["Por lo menos 14 años","Por lo menos 16 años","Por lo menos 18 años","Por lo menos 21 años"],"h1":"Es la misma edad en que un joven de Dakota del Norte puede tener una licencia sin restricciones.","h2":"En Dakota del Norte un no residente con una licencia válida de su estado debe tener por lo menos 16 años para manejar.","p":"Correcto. Un conductor visitante debe tener por lo menos 16 años."},"ref":{"doc":"ND","page":3}},{"id":"nd-057","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a resident on active military duty outside the state left with a valid license. How long does it stay valid?","o":["Until it is 1 year past its date","Until 90 days after they come home on leave","Until their next birthday","Until 30 days after they leave the service"],"h1":"The time starts when military service ends.","h2":"In North Dakota the license of a resident on active duty outside the state stays valid until 30 days after discharge or separation from the service.","p":"Right. It stays valid until 30 days after leaving the service."},"es":{"q":"En Dakota del Norte, un residente en servicio militar activo fuera del estado se fue con una licencia válida. ¿Hasta cuándo sigue siendo válida?","o":["Hasta 1 año después de su fecha","Hasta 90 días después de volver de permiso","Hasta su próximo cumpleaños","Hasta 30 días después de dejar el servicio"],"h1":"El tiempo empieza cuando termina el servicio militar.","h2":"En Dakota del Norte la licencia de un residente en servicio activo fuera del estado sigue válida hasta 30 días después de su baja o separación del servicio.","p":"Correcto. Sigue válida hasta 30 días después de dejar el servicio."},"ref":{"doc":"ND","page":3}},{"id":"nd-058","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, you fail your knowledge test or road test. When can you take it again?","o":["Not on the same day","Right away, the same day","Only after 30 days","Only after 6 months"],"h1":"You must come back another day.","h2":"In North Dakota, if you fail a test, you are not allowed to take it again on the same day.","p":"Right. You cannot retake it the same day."},"es":{"q":"En Dakota del Norte, usted no pasa el examen escrito o el examen de manejo. ¿Cuándo puede tomarlo otra vez?","o":["No el mismo día","Enseguida, el mismo día","Solo después de 30 días","Solo después de 6 meses"],"h1":"Debe volver otro día.","h2":"En Dakota del Norte, si usted no pasa un examen, no se le permite tomarlo otra vez el mismo día.","p":"Correcto. No puede repetirlo el mismo día."},"ref":{"doc":"ND","page":5}},{"id":"nd-059","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how many documents must you bring to prove your North Dakota home address?","o":["One","Three","Two","None, a post office box is enough"],"h1":"It is more than one, but not many.","h2":"In North Dakota you must bring two documents that show your name and home address to prove where you live; a post office box is not accepted.","p":"Right. You need two documents with your home address."},"es":{"q":"En Dakota del Norte, ¿cuántos documentos debe llevar para probar su domicilio en Dakota del Norte?","o":["Uno","Tres","Dos","Ninguno, basta con un apartado postal"],"h1":"Es más de uno, pero no muchos.","h2":"En Dakota del Norte usted debe llevar dos documentos con su nombre y su domicilio para probar dónde vive; un apartado postal no se acepta.","p":"Correcto. Necesita dos documentos con su domicilio."},"ref":{"doc":"ND","page":5}},{"id":"nd-060","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, at what age does a restricted Class D license become an unrestricted license?","o":["15","16","17","18"],"h1":"It is one year after the youngest age for a restricted license.","h2":"In North Dakota a restricted Class D license becomes an unrestricted license at age 16.","p":"Right. At 16 the restrictions end."},"es":{"q":"En Dakota del Norte, ¿a qué edad una licencia Clase D restringida pasa a ser una licencia sin restricciones?","o":["15","16","17","18"],"h1":"Es un año después de la edad mínima para la licencia restringida.","h2":"En Dakota del Norte una licencia Clase D restringida pasa a ser una licencia sin restricciones a los 16 años.","p":"Correcto. A los 16 años terminan las restricciones."},"ref":{"doc":"ND","page":6}},{"id":"nd-061","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a 15-year-old with a restricted license wants to drive alone at 10 p.m. Which trip is allowed?","o":["Driving friends home from a movie","Going to a store for snacks","Driving around town for practice","Driving straight home from work"],"h1":"Only a few kinds of trips are allowed at night: work, school activities and religious activities.","h2":"In North Dakota a 15-year-old with a restricted license may drive alone at night only directly to or from work, an official school activity or a religious activity.","p":"Right. Driving straight home from work is allowed."},"es":{"q":"En Dakota del Norte, un joven de 15 años con licencia restringida quiere manejar solo a las 10 p.m. ¿Qué viaje está permitido?","o":["Llevar a sus amigos a casa después del cine","Ir a una tienda a comprar algo de comer","Dar vueltas por la ciudad para practicar","Manejar directo a casa desde el trabajo"],"h1":"De noche solo se permiten pocos viajes: trabajo, actividades de la escuela y actividades religiosas.","h2":"En Dakota del Norte un joven de 15 años con licencia restringida puede manejar solo de noche únicamente directo hacia o desde el trabajo, una actividad oficial de la escuela o una actividad religiosa.","p":"Correcto. Manejar directo a casa desde el trabajo está permitido."},"ref":{"doc":"ND","page":6}},{"id":"nd-062","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, a 17-year-old driver may not use a phone while driving. When is it allowed?","o":["To call for help in an emergency","To read a text at a red light","To use GPS on a short trip","To call a parent to say they are late"],"h1":"Think of a danger to someone's life or safety.","h2":"In North Dakota a driver under 18 may use a phone while driving only to get emergency help, to stop a crime, or when someone's life or safety is in danger.","p":"Right. Only to get help in an emergency."},"es":{"q":"En Dakota del Norte, un conductor de 17 años no puede usar el teléfono mientras maneja. ¿Cuándo sí se permite?","o":["Para pedir ayuda en una emergencia","Para leer un mensaje en una luz roja","Para usar el GPS en un viaje corto","Para llamar a sus padres y decir que va tarde"],"h1":"Piense en un peligro para la vida o la seguridad de alguien.","h2":"En Dakota del Norte un conductor menor de 18 años puede usar el teléfono mientras maneja solo para pedir ayuda en una emergencia, para evitar un delito, o cuando la vida o la seguridad de alguien está en peligro.","p":"Correcto. Solo para pedir ayuda en una emergencia."},"ref":{"doc":"ND","page":6}},{"id":"nd-063","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, when does a driver license expire?","o":["On December 31 of its last year","On the first day of your birth month","At midnight on your birthday","On the date you first got it"],"h1":"The date is personal to you.","h2":"In North Dakota a driver license expires at midnight on your birthday.","p":"Right. It expires at midnight on your birthday."},"es":{"q":"En Dakota del Norte, ¿cuándo vence una licencia de manejo?","o":["El 31 de diciembre de su último año","El primer día del mes de su cumpleaños","A la medianoche de su cumpleaños","En la fecha en que la recibió por primera vez"],"h1":"La fecha es personal para usted.","h2":"En Dakota del Norte la licencia de manejo vence a la medianoche de su cumpleaños.","p":"Correcto. Vence a la medianoche de su cumpleaños."},"ref":{"doc":"ND","page":7}},{"id":"nd-064","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, instead of a vision test at renewal, you bring a vision certificate from your eye doctor. How old may it be?","o":["Up to 30 days","No more than 6 months","Up to 2 years","Any age, if it is signed"],"h1":"It is half a year.","h2":"In North Dakota a vision certificate from a physician or optometrist used for renewal must be no more than six months old.","p":"Right. It must be no more than 6 months old."},"es":{"q":"En Dakota del Norte, en vez del examen de la vista al renovar, usted lleva un certificado de visión de su médico de los ojos. ¿Qué antigüedad puede tener?","o":["Hasta 30 días","No más de 6 meses","Hasta 2 años","Cualquiera, si está firmado"],"h1":"Es medio año.","h2":"En Dakota del Norte el certificado de visión de un médico u optometrista para renovar no puede tener más de seis meses.","p":"Correcto. No puede tener más de 6 meses."},"ref":{"doc":"ND","page":7}},{"id":"nd-065","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, during which time of year may you never ride a snowmobile on any road right of way?","o":["From October 15 to April 15","From December 1 to March 1","Only on weekends in winter","From April 1 to November 1"],"h1":"It is the warm part of the year, from spring to late fall.","h2":"In North Dakota you may never ride a snowmobile on any road right of way from April 1 to November 1.","p":"Right. No snowmobiles on any right of way from April 1 to November 1."},"es":{"q":"En Dakota del Norte, ¿en qué época del año nunca puede andar en moto de nieve en el derecho de vía de ningún camino?","o":["Del 15 de octubre al 15 de abril","Del 1 de diciembre al 1 de marzo","Solo los fines de semana en invierno","Del 1 de abril al 1 de noviembre"],"h1":"Es la parte cálida del año, de la primavera a finales del otoño.","h2":"En Dakota del Norte nunca puede andar en moto de nieve en el derecho de vía de ningún camino del 1 de abril al 1 de noviembre.","p":"Correcto. Nada de motos de nieve en el derecho de vía del 1 de abril al 1 de noviembre."},"ref":{"doc":"ND","page":39}},{"id":"nd-066","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, you move here or start a job here and own a car. When must you register it in North Dakota?","o":["Right away","Within 60 days","Within 1 year","When your old plates expire"],"h1":"The law does not give you a waiting period.","h2":"In North Dakota you must register your vehicle right away when you become a resident or start working in the state.","p":"Right. You must register it right away."},"es":{"q":"En Dakota del Norte, usted se muda aquí o empieza un trabajo aquí y tiene un carro. ¿Cuándo debe registrarlo en Dakota del Norte?","o":["De inmediato","Dentro de 60 días","Dentro de 1 año","Cuando venzan sus placas anteriores"],"h1":"La ley no le da un tiempo de espera.","h2":"En Dakota del Norte usted debe registrar su vehículo de inmediato cuando se hace residente o empieza a trabajar en el estado.","p":"Correcto. Debe registrarlo de inmediato."},"ref":{"doc":"ND","page":8}},{"id":"nd-067","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a driver has a first offense in seven years with an alcohol level of 0.18 percent or more. How long is the license suspended?","o":["91 days","365 days","180 days","3 years"],"h1":"It is about half a year.","h2":"In North Dakota a first offense in seven years with an alcohol level of 0.18 percent or more brings a 180-day license suspension.","p":"Right. The suspension is 180 days."},"es":{"q":"En Dakota del Norte, un conductor tiene una primera infracción en siete años con un nivel de alcohol de 0.18 por ciento o más. ¿Por cuánto tiempo se suspende la licencia?","o":["91 días","365 días","180 días","3 años"],"h1":"Es como medio año.","h2":"En Dakota del Norte una primera infracción en siete años con un nivel de alcohol de 0.18 por ciento o más trae una suspensión de la licencia de 180 días.","p":"Correcto. La suspensión es de 180 días."},"ref":{"doc":"ND","page":36}},{"id":"nd-068","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, with a Class D license, what is the heaviest trailer you may tow?","o":["2,000 pounds","5,000 pounds","26,000 pounds","10,000 pounds"],"h1":"It is ten thousand pounds or less.","h2":"In North Dakota a Class D license lets you tow a trailer of up to 10,000 pounds gross vehicle weight rating.","p":"Right. Up to 10,000 pounds."},"es":{"q":"En Dakota del Norte, con una licencia Clase D, ¿cuál es el remolque más pesado que puede jalar?","o":["2,000 libras","5,000 libras","26,000 libras","10,000 libras"],"h1":"Es de diez mil libras o menos.","h2":"En Dakota del Norte una licencia Clase D le permite jalar un remolque de hasta 10,000 libras de peso bruto nominal.","p":"Correcto. Hasta 10,000 libras."},"ref":{"doc":"ND","page":8}},{"id":"nd-069","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a driver reaches exactly 12 points and the license is suspended. How long is the suspension?","o":["1 day","7 days","30 days","1 year"],"h1":"It is one week.","h2":"In North Dakota a driver with 12 points has the license suspended for 7 days, and 7 more days for each point over 11.","p":"Right. Twelve points means a 7-day suspension."},"es":{"q":"En Dakota del Norte, un conductor llega a exactamente 12 puntos y le suspenden la licencia. ¿Cuánto dura la suspensión?","o":["1 día","7 días","30 días","1 año"],"h1":"Es una semana.","h2":"En Dakota del Norte a un conductor con 12 puntos le suspenden la licencia por 7 días, y 7 días más por cada punto por encima de 11.","p":"Correcto. Doce puntos significan una suspensión de 7 días."},"ref":{"doc":"ND","page":40}},{"id":"nd-070","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, a 14- or 15-year-old wants a motorcycle license. What must they do besides passing the motorcycle knowledge test?","o":["Finish an approved motorcycle safety course","Drive a car for one year first","Have a parent ride on the back","Nothing else"],"h1":"They need a certificate from a training course.","h2":"In North Dakota a 14- or 15-year-old can get a motorcycle license by finishing an approved motorcycle safety course and passing the motorcycle knowledge test.","p":"Right. They must finish an approved motorcycle safety course."},"es":{"q":"En Dakota del Norte, un joven de 14 o 15 años quiere una licencia de motocicleta. ¿Qué debe hacer además de pasar el examen escrito de motocicleta?","o":["Terminar un curso aprobado de seguridad en motocicleta","Manejar un carro por un año primero","Llevar a un padre sentado atrás","Nada más"],"h1":"Necesita un certificado de un curso de entrenamiento.","h2":"En Dakota del Norte un joven de 14 o 15 años puede sacar una licencia de motocicleta si termina un curso aprobado de seguridad en motocicleta y pasa el examen escrito de motocicleta.","p":"Correcto. Debe terminar un curso aprobado de seguridad en motocicleta."},"ref":{"doc":"ND","page":4}},{"id":"nd-071","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, what is the smallest fee for breaking the work zone speed limit while work is going on and workers are there?","o":["$20","$40","$80","$250"],"h1":"It is more than $50 but less than $100.","h2":"In North Dakota breaking the work zone speed limit while workers are present carries a fee of at least $80.","p":"Right. The minimum fee is $80."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa mínima por no respetar el límite de velocidad en una zona de obras cuando hay trabajo y trabajadores presentes?","o":["$20","$40","$80","$250"],"h1":"Es más de $50 pero menos de $100.","h2":"En Dakota del Norte no respetar el límite de velocidad en una zona de obras con trabajadores presentes tiene una multa de por lo menos $80.","p":"Correcto. La multa mínima es de $80."},"ref":{"doc":"ND","page":13}},{"id":"nd-072","scope":"ND","cat":"signals","sign":null,"c":1,"en":{"q":"In North Dakota, an orange triangle sign with a red border is on the back of a vehicle. How fast does that vehicle usually go?","o":["55 mph or less","25 mph or less","40 mph or less","The same as other traffic"],"h1":"It is a slow-moving vehicle sign.","h2":"In North Dakota the orange triangle slow-moving vehicle sign is used on vehicles or equipment that travel at 25 mph or less, so slow down and use care.","p":"Right. It marks a vehicle going 25 mph or less."},"es":{"q":"En Dakota del Norte, un letrero triangular anaranjado con borde rojo está en la parte trasera de un vehículo. ¿A qué velocidad suele ir ese vehículo?","o":["55 mph o menos","25 mph o menos","40 mph o menos","Igual que el resto del tráfico"],"h1":"Es el letrero de vehículo lento.","h2":"En Dakota del Norte el letrero triangular anaranjado de vehículo lento se usa en vehículos o equipos que van a 25 mph o menos, así que baje la velocidad y tenga cuidado.","p":"Correcto. Marca un vehículo que va a 25 mph o menos."},"ref":{"doc":"ND","page":12}},{"id":"nd-073","scope":"ND","cat":"signals","sign":null,"c":3,"en":{"q":"In North Dakota, when may you turn left on a red light after stopping?","o":["Never","At any intersection, if no cars are coming","Only when a police officer waves you on","From a one-way street onto another one-way street, unless a sign says no"],"h1":"Both streets must carry traffic in only one direction.","h2":"In North Dakota you may turn left on red, after stopping, only from a one-way street onto another one-way street, unless a sign forbids it.","p":"Right. Left on red is allowed only from one one-way street onto another."},"es":{"q":"En Dakota del Norte, ¿cuándo puede girar a la izquierda con la luz roja después de detenerse?","o":["Nunca","En cualquier intersección, si no vienen carros","Solo cuando un policía le indica que pase","De una calle de un solo sentido a otra calle de un solo sentido, a menos que un letrero lo prohíba"],"h1":"Las dos calles deben tener tráfico en una sola dirección.","h2":"En Dakota del Norte usted puede girar a la izquierda con luz roja, después de detenerse, solo de una calle de un solo sentido a otra calle de un solo sentido, a menos que un letrero lo prohíba.","p":"Correcto. La izquierda con rojo solo se permite de una calle de un solo sentido a otra."},"ref":{"doc":"ND","page":15}},{"id":"nd-074","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, the power is out and the traffic lights at an intersection are dark. What must you do?","o":["Stop and yield to any vehicle already in the intersection","Drive through without stopping if the road looks clear","Honk and go first","Turn around and find another road"],"h1":"Treat the intersection with great care: stop first.","h2":"In North Dakota, when traffic signals are dark, you must stop and yield the right of way to any vehicle already in the intersection.","p":"Right. Stop, and yield to vehicles already in the intersection."},"es":{"q":"En Dakota del Norte, no hay electricidad y los semáforos de una intersección están apagados. ¿Qué debe hacer?","o":["Detenerse y ceder el paso a cualquier vehículo que ya esté en la intersección","Pasar sin detenerse si el camino parece libre","Tocar la bocina y pasar primero","Dar la vuelta y buscar otro camino"],"h1":"Trate la intersección con mucho cuidado: primero deténgase.","h2":"En Dakota del Norte, cuando los semáforos están apagados, usted debe detenerse y ceder el paso a cualquier vehículo que ya esté en la intersección.","p":"Correcto. Deténgase y ceda el paso a los vehículos que ya están en la intersección."},"ref":{"doc":"ND","page":15}},{"id":"nd-075","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, a train is going through a railroad crossing ahead of you. How far from the crossing must you stop?","o":["At least 5 feet","At least 50 feet","At least 15 feet","Right at the tracks"],"h1":"It is a little more than the length of a car.","h2":"In North Dakota, when a train is crossing, you must stop at least 15 feet before the crossing.","p":"Right. Stop at least 15 feet before the crossing."},"es":{"q":"En Dakota del Norte, un tren está pasando por un cruce de ferrocarril delante de usted. ¿A qué distancia del cruce debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 50 pies","Por lo menos a 15 pies","Justo al lado de las vías"],"h1":"Es un poco más que el largo de un carro.","h2":"En Dakota del Norte, cuando un tren está cruzando, usted debe detenerse por lo menos a 15 pies antes del cruce.","p":"Correcto. Deténgase por lo menos a 15 pies antes del cruce."},"ref":{"doc":"ND","page":18}},{"id":"nd-076","scope":"ND","cat":"signals","sign":null,"c":1,"en":{"q":"In North Dakota, for how far before a turn must you keep your turn signal on?","o":["The last 50 feet","The last 100 feet","The last 500 feet","Only as you start to turn"],"h1":"It is about the length of seven cars.","h2":"In North Dakota you must signal without stopping during the last 100 feet before a turn.","p":"Right. Signal for the last 100 feet."},"es":{"q":"En Dakota del Norte, ¿durante qué distancia antes de un giro debe mantener encendida la direccional?","o":["Los últimos 50 pies","Los últimos 100 pies","Los últimos 500 pies","Solo al empezar a girar"],"h1":"Es como el largo de siete carros.","h2":"En Dakota del Norte usted debe señalar sin parar durante los últimos 100 pies antes de un giro.","p":"Correcto. Señale durante los últimos 100 pies."},"ref":{"doc":"ND","page":19}},{"id":"nd-077","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, you and another car reach an intersection with no signs or signals at about the same time. The other car is on your right. Who goes first?","o":["You, because you are on the left","Whoever is driving faster","The bigger vehicle","The car on your right"],"h1":"The driver on the left gives way.","h2":"In North Dakota, when two vehicles reach an unsigned intersection at about the same time, the vehicle on the left must yield to the vehicle on the right.","p":"Right. The car on the right goes first."},"es":{"q":"En Dakota del Norte, usted y otro carro llegan casi al mismo tiempo a una intersección sin letreros ni semáforos. El otro carro está a su derecha. ¿Quién pasa primero?","o":["Usted, porque está a la izquierda","El que va más rápido","El vehículo más grande","El carro a su derecha"],"h1":"El conductor de la izquierda cede el paso.","h2":"En Dakota del Norte, cuando dos vehículos llegan casi al mismo tiempo a una intersección sin letreros, el vehículo de la izquierda debe ceder el paso al de la derecha.","p":"Correcto. El carro de la derecha pasa primero."},"ref":{"doc":"ND","page":19}},{"id":"nd-078","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, you are on a street that ends at a T-intersection with no signs. Who must yield?","o":["You, the driver on the street that ends","Drivers on the street that goes on","Whoever arrives last","No one; both may go"],"h1":"Think about which road keeps going.","h2":"In North Dakota, at a T-intersection with no signs or signals, the driver on the street that ends must yield to vehicles on the street that continues.","p":"Right. The driver on the ending street yields."},"es":{"q":"En Dakota del Norte, usted va por una calle que termina en una intersección en T sin letreros. ¿Quién debe ceder el paso?","o":["Usted, el conductor de la calle que termina","Los conductores de la calle que sigue","El que llega último","Nadie; los dos pueden pasar"],"h1":"Piense en cuál calle sigue adelante.","h2":"En Dakota del Norte, en una intersección en T sin letreros ni semáforos, el conductor de la calle que termina debe ceder el paso a los vehículos de la calle que continúa.","p":"Correcto. Cede el paso el conductor de la calle que termina."},"ref":{"doc":"ND","page":19}},{"id":"nd-079","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, at a four-way stop, who goes first?","o":["The car going straight","The largest vehicle","The vehicle that stopped first","The car on the left"],"h1":"Think \"first come, first served.\"","h2":"In North Dakota, at a four-way stop, the vehicle that stops first goes first.","p":"Right. The first one to stop goes first."},"es":{"q":"En Dakota del Norte, en un alto de cuatro vías, ¿quién pasa primero?","o":["El carro que sigue derecho","El vehículo más grande","El vehículo que se detuvo primero","El carro de la izquierda"],"h1":"Piense en \"el primero que llega, pasa primero\".","h2":"En Dakota del Norte, en un alto de cuatro vías, pasa primero el vehículo que se detuvo primero.","p":"Correcto. Pasa primero el que se detuvo primero."},"ref":{"doc":"ND","page":19}},{"id":"nd-080","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, a person with a white cane is waiting to cross at an intersection where you are stopping. Where should you stop?","o":["In the middle of the crosswalk","Behind the crosswalk, so the path is clear","Past the crosswalk","Anywhere, then honk to let them know it is safe"],"h1":"Leave the walking path completely open.","h2":"In North Dakota, when you stop at an intersection near a person with a white cane or guide dog, you should stop behind the crosswalk so the person has a clear path.","p":"Right. Stop behind the crosswalk and leave the path clear."},"es":{"q":"En Dakota del Norte, una persona con un bastón blanco espera para cruzar en una intersección donde usted se está deteniendo. ¿Dónde debe detenerse?","o":["En medio del cruce peatonal","Antes del cruce peatonal, para dejar el paso libre","Después del cruce peatonal","En cualquier lugar, y luego tocar la bocina para avisar que es seguro"],"h1":"Deje el camino de la persona completamente libre.","h2":"En Dakota del Norte, cuando usted se detiene en una intersección cerca de una persona con bastón blanco o perro guía, debe detenerse antes del cruce peatonal para que la persona tenga el paso libre.","p":"Correcto. Deténgase antes del cruce peatonal y deje el paso libre."},"ref":{"doc":"ND","page":19}},{"id":"nd-081","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, near the top of a hill or on a curve, at least how far ahead must you be able to see before you may make a U-turn?","o":["100 feet","200 feet","1,000 feet","500 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In North Dakota you may not make a U-turn near the top of a hill or on a curve where you cannot see 500 feet or more.","p":"Right. You need to see at least 500 feet."},"es":{"q":"En Dakota del Norte, cerca de la cima de una colina o en una curva, ¿por lo menos qué distancia debe poder ver hacia adelante para dar una vuelta en U?","o":["100 pies","200 pies","1,000 pies","500 pies"],"h1":"Es como el largo de una cancha y media de fútbol americano.","h2":"En Dakota del Norte usted no puede dar una vuelta en U cerca de la cima de una colina o en una curva donde no puede ver 500 pies o más.","p":"Correcto. Necesita ver por lo menos 500 pies."},"ref":{"doc":"ND","page":20}},{"id":"nd-082","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, a police car with flashing lights and a siren comes up behind you. What must you do?","o":["Speed up to get out of its way","Pull to the right edge of the road, stop, and stay stopped until it passes","Stop right where you are, even in an intersection","Keep driving and let it go around you"],"h1":"Move right, stop, and wait, but not in the middle of an intersection.","h2":"In North Dakota, when an emergency or police vehicle uses flashing lights or a siren, you must pull to the right edge of the road, stop, and stay stopped until it has passed, but never stop in an intersection.","p":"Right. Pull right, stop, and wait until it passes."},"es":{"q":"En Dakota del Norte, un carro de policía con luces intermitentes y sirena se acerca por detrás. ¿Qué debe hacer?","o":["Acelerar para quitarse del camino","Orillarse a la derecha del camino, detenerse y quedarse detenido hasta que pase","Detenerse donde está, aunque sea en una intersección","Seguir manejando y dejar que le pase por un lado"],"h1":"Muévase a la derecha, deténgase y espere, pero no en medio de una intersección.","h2":"En Dakota del Norte, cuando un vehículo de emergencia o de policía usa luces intermitentes o sirena, usted debe orillarse a la derecha del camino, detenerse y quedarse detenido hasta que pase, pero nunca detenerse en una intersección.","p":"Correcto. Oríllese a la derecha, deténgase y espere a que pase."},"ref":{"doc":"ND","page":20}},{"id":"nd-083","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, you are stopped for a school bus with flashing red lights. When may you go?","o":["When you see no children near the road","After waiting 30 seconds","When the bus moves, the driver signals you to pass, or the red lights stop flashing","As soon as the stop arm starts to close"],"h1":"The bus itself or its driver tells you when.","h2":"In North Dakota you may go on past a stopped school bus only when the bus starts moving, the bus driver signals you to pass, or the red lights stop flashing.","p":"Right. Wait for the bus to move, the driver to signal, or the red lights to stop."},"es":{"q":"En Dakota del Norte, usted está detenido por un autobús escolar con luces rojas intermitentes. ¿Cuándo puede seguir?","o":["Cuando no vea niños cerca del camino","Después de esperar 30 segundos","Cuando el autobús avance, el conductor le indique que pase o las luces rojas dejen de parpadear","En cuanto el brazo de alto empiece a cerrarse"],"h1":"El autobús o su conductor le indican cuándo.","h2":"En Dakota del Norte usted puede pasar un autobús escolar detenido solo cuando el autobús empieza a moverse, el conductor le indica que pase o las luces rojas dejan de parpadear.","p":"Correcto. Espere a que el autobús avance, el conductor le indique o las luces rojas se apaguen."},"ref":{"doc":"ND","page":20}},{"id":"nd-084","scope":"ND","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Dakota, what is the speed limit when you pass a school during recess, unless a sign says otherwise?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"It is lower than the usual town speed limit of 25 mph.","h2":"In North Dakota the speed limit is 20 mph when you pass a school during recess or while children are going to or leaving school, unless a sign says otherwise.","p":"Right. Near a school at those times the limit is 20 mph."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad al pasar por una escuela durante el recreo, a menos que un letrero diga otra cosa?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Es menor que el límite normal en la ciudad, que es de 25 mph.","h2":"En Dakota del Norte el límite es de 20 mph al pasar por una escuela durante el recreo o cuando los niños llegan o salen de la escuela, a menos que un letrero diga otra cosa.","p":"Correcto. Cerca de una escuela en esos momentos el límite es de 20 mph."},"ref":{"doc":"ND","page":20}},{"id":"nd-085","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, what is the top speed on a rural, paved two-lane highway when it is posted for that speed?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"It is 10 mph more than the limit on gravel roads.","h2":"In North Dakota the speed limit on rural, paved two-lane highways is 65 mph where it is posted for that speed.","p":"Right. It is 65 mph where posted."},"es":{"q":"En Dakota del Norte, ¿cuál es la velocidad máxima en una carretera rural pavimentada de dos carriles cuando está señalada para esa velocidad?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Es 10 mph más que el límite en caminos de grava.","h2":"En Dakota del Norte el límite en carreteras rurales pavimentadas de dos carriles es de 65 mph donde está señalado para esa velocidad.","p":"Correcto. Es de 65 mph donde está señalado."},"ref":{"doc":"ND","page":20}},{"id":"nd-086","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, you should never pass another vehicle within how many feet of an intersection, railroad crossing or tunnel?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"It is the same distance you signal before a turn.","h2":"In North Dakota you should never pass another vehicle within 100 feet of an intersection, a railroad crossing or a tunnel.","p":"Right. Never pass within 100 feet of them."},"es":{"q":"En Dakota del Norte, ¿a menos de cuántos pies de una intersección, un cruce de ferrocarril o un túnel nunca debe rebasar a otro vehículo?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Es la misma distancia en que usted señala antes de un giro.","h2":"En Dakota del Norte usted nunca debe rebasar a otro vehículo a menos de 100 pies de una intersección, un cruce de ferrocarril o un túnel.","p":"Correcto. Nunca rebase a menos de 100 pies de ellos."},"ref":{"doc":"ND","page":21}},{"id":"nd-087","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, about how far does it take a car going 55 mph to stop on dry pavement?","o":["About 50 feet","About 100 feet","About half a mile","About 300 feet, or one city block"],"h1":"It is about the length of a football field or one city block.","h2":"In North Dakota the handbook says a car going 55 mph needs about 300 feet, or one city block, to stop on dry pavement.","p":"Right. About 300 feet, or one city block."},"es":{"q":"En Dakota del Norte, ¿más o menos qué distancia necesita un carro que va a 55 mph para detenerse en pavimento seco?","o":["Unos 50 pies","Unos 100 pies","Como media milla","Unos 300 pies, o una cuadra de la ciudad"],"h1":"Es como el largo de una cancha de fútbol americano o una cuadra.","h2":"En Dakota del Norte el manual dice que un carro que va a 55 mph necesita unos 300 pies, o una cuadra de la ciudad, para detenerse en pavimento seco.","p":"Correcto. Unos 300 pies, o una cuadra."},"ref":{"doc":"ND","page":21}},{"id":"nd-088","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, the handbook gives a rule for a safe following distance. How many seconds behind the car ahead should you be, at least?","o":["3 seconds","1 second","2 seconds","10 seconds"],"h1":"Count \"one-thousand-and-one, one-thousand-and-two, ...\"","h2":"In North Dakota the handbook uses the three-second rule: you should be at least 3 seconds behind the vehicle ahead, and more in bad conditions.","p":"Right. Stay at least 3 seconds behind."},"es":{"q":"En Dakota del Norte, el manual da una regla para una distancia segura. ¿Por lo menos cuántos segundos detrás del carro de adelante debe ir?","o":["3 segundos","1 segundo","2 segundos","10 segundos"],"h1":"Cuente \"mil uno, mil dos, ...\"","h2":"En Dakota del Norte el manual usa la regla de los tres segundos: usted debe ir por lo menos 3 segundos detrás del vehículo de adelante, y más con malas condiciones.","p":"Correcto. Vaya por lo menos 3 segundos detrás."},"ref":{"doc":"ND","page":22}},{"id":"nd-089","scope":"ND","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Dakota, you turn left from a two-way road onto a four-lane highway. Which lane should you turn into?","o":["The right lane, right away","The shoulder, until traffic clears","Any lane that is open","The passing (left) lane, then move right when traffic allows"],"h1":"Turn into the nearest lane first, then change lanes later.","h2":"In North Dakota, when you turn left onto a four-lane highway, you should turn into the passing lane and then move to the right lane when traffic allows.","p":"Right. Enter the passing lane, then move right when it is safe."},"es":{"q":"En Dakota del Norte, usted gira a la izquierda desde un camino de doble sentido hacia una carretera de cuatro carriles. ¿A qué carril debe entrar?","o":["Al carril derecho, enseguida","Al acotamiento, hasta que pase el tráfico","A cualquier carril que esté libre","Al carril de rebase (izquierdo), y luego pasarse a la derecha cuando el tráfico lo permita"],"h1":"Primero entre al carril más cercano y después cambie de carril.","h2":"En Dakota del Norte, cuando usted gira a la izquierda hacia una carretera de cuatro carriles, debe entrar al carril de rebase y luego pasarse al carril derecho cuando el tráfico lo permita.","p":"Correcto. Entre al carril de rebase y luego pásese a la derecha cuando sea seguro."},"ref":{"doc":"ND","page":23}},{"id":"nd-090","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, your car has a problem on the Interstate and you must stop. What should you do?","o":["Stop in the right lane and turn on your wipers","Stop on the shoulder and raise your hood","Back up to the last exit","Cross the median to turn around"],"h1":"Get off the road and show other drivers you need help.","h2":"In North Dakota, in an emergency on the Interstate, you should stop on the shoulder, never on the traveled road, and raise your hood to show you have trouble.","p":"Right. Stop on the shoulder and raise the hood."},"es":{"q":"En Dakota del Norte, su carro tiene un problema en la Interestatal y debe detenerse. ¿Qué debe hacer?","o":["Detenerse en el carril derecho y prender los limpiaparabrisas","Detenerse en el acotamiento y levantar el cofre","Ir en reversa hasta la última salida","Cruzar la mediana para dar la vuelta"],"h1":"Salga del camino y muestre a otros conductores que necesita ayuda.","h2":"En Dakota del Norte, en una emergencia en la Interestatal, usted debe detenerse en el acotamiento, nunca en el camino, y levantar el cofre para mostrar que tiene un problema.","p":"Correcto. Deténgase en el acotamiento y levante el cofre."},"ref":{"doc":"ND","page":24}},{"id":"nd-091","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, who may use the crossovers in the Interstate median?","o":["Any driver who missed an exit","Cars only, not trucks","Only authorized vehicles, such as emergency and maintenance vehicles","Any driver at night"],"h1":"These crossovers are not for the public.","h2":"In North Dakota the median crossovers on the Interstate are only for authorized vehicles, such as emergency and maintenance vehicles.","p":"Right. Only authorized vehicles may use them."},"es":{"q":"En Dakota del Norte, ¿quién puede usar los cruces de la mediana en la Interestatal?","o":["Cualquier conductor que se pasó de una salida","Solo carros, no camiones","Solo vehículos autorizados, como los de emergencia y mantenimiento","Cualquier conductor de noche"],"h1":"Estos cruces no son para el público.","h2":"En Dakota del Norte los cruces de la mediana en la Interestatal son solo para vehículos autorizados, como los de emergencia y mantenimiento.","p":"Correcto. Solo los vehículos autorizados pueden usarlos."},"ref":{"doc":"ND","page":24}},{"id":"nd-092","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, at night, a car is coming toward you. At least how far away should you dim your high beams?","o":["500 feet","100 feet","200 feet","1,000 feet"],"h1":"It is a little less than two football fields long.","h2":"In North Dakota you should dim your high beams at least 500 feet before you meet an oncoming vehicle.","p":"Right. Dim them at least 500 feet away."},"es":{"q":"En Dakota del Norte, de noche, un carro viene hacia usted. ¿Por lo menos a qué distancia debe bajar sus luces altas?","o":["500 pies","100 pies","200 pies","1,000 pies"],"h1":"Es un poco menos que el largo de dos canchas de fútbol americano.","h2":"En Dakota del Norte usted debe bajar sus luces altas por lo menos 500 pies antes de encontrarse con un vehículo que viene de frente.","p":"Correcto. Bájelas por lo menos a 500 pies."},"ref":{"doc":"ND","page":25}},{"id":"nd-093","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, at night, you are following another vehicle. Within how many feet of it should your high beams be dimmed?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"It is about the same as the distance to stop from 55 mph.","h2":"In North Dakota you should dim your high beams when you are within 300 feet of a vehicle you are following.","p":"Right. Dim them within 300 feet."},"es":{"q":"En Dakota del Norte, de noche, usted va detrás de otro vehículo. ¿A menos de cuántos pies de él debe tener bajas sus luces altas?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Es más o menos la distancia para detenerse a 55 mph.","h2":"En Dakota del Norte usted debe bajar sus luces altas cuando está a menos de 300 pies de un vehículo que va delante.","p":"Correcto. Bájelas a menos de 300 pies."},"ref":{"doc":"ND","page":25}},{"id":"nd-094","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, when you parallel park, how close to the curb should your wheels be?","o":["Within 3 feet","Within 1 foot","Within 2 feet","Touching the curb"],"h1":"It is about the length of a ruler.","h2":"In North Dakota, when you parallel park, your wheels should be straight and within one foot of the curb.","p":"Right. Within one foot of the curb."},"es":{"q":"En Dakota del Norte, cuando se estaciona en paralelo, ¿qué tan cerca de la banqueta deben quedar sus llantas?","o":["A menos de 3 pies","A menos de 1 pie","A menos de 2 pies","Tocando la banqueta"],"h1":"Es como el largo de una regla.","h2":"En Dakota del Norte, cuando se estaciona en paralelo, sus llantas deben quedar derechas y a menos de un pie de la banqueta.","p":"Correcto. A menos de un pie de la banqueta."},"ref":{"doc":"ND","page":25}},{"id":"nd-095","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","It does not matter","Away from the curb"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In North Dakota, when you park uphill next to a curb, you should turn your front wheels away from the curb.","p":"Right. Uphill with a curb, turn the wheels away from it."},"es":{"q":"En Dakota del Norte, usted se estaciona cuesta arriba junto a una banqueta. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la banqueta","Derechas","No importa","Lejos de la banqueta"],"h1":"Si el carro rueda hacia atrás, la parte trasera de la llanta delantera debe quedar contra la banqueta.","h2":"En Dakota del Norte, cuando se estaciona cuesta arriba junto a una banqueta, debe girar las llantas delanteras lejos de la banqueta.","p":"Correcto. Cuesta arriba con banqueta, gire las llantas lejos de ella."},"ref":{"doc":"ND","page":25}},{"id":"nd-096","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 5 feet","Right up to the crosswalk","On the crosswalk, if no one is crossing"],"h1":"Leave about two car widths of space.","h2":"In North Dakota you may not park on a crosswalk at an intersection or within 10 feet of it.","p":"Right. Stay at least 10 feet away."},"es":{"q":"En Dakota del Norte, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 5 pies","Justo hasta el cruce peatonal","Sobre el cruce, si nadie está cruzando"],"h1":"Deje como el ancho de dos carros.","h2":"En Dakota del Norte usted no puede estacionarse sobre un cruce peatonal en una intersección ni a menos de 10 pies de él.","p":"Correcto. Quédese por lo menos a 10 pies."},"ref":{"doc":"ND","page":26}},{"id":"nd-097","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, you tow a trailer faster than 25 mph. What must it have in case the hitch breaks?","o":["A flag on the back","A second driver in the trailer","Safety chains, or brakes that can hold the trailer","Nothing extra"],"h1":"Something must keep the trailer from running loose.","h2":"In North Dakota, when you tow a trailer faster than 25 mph, you need safety chains or brakes that can hold the trailer if the hitch breaks.","p":"Right. You need safety chains or trailer brakes."},"es":{"q":"En Dakota del Norte, usted jala un remolque a más de 25 mph. ¿Qué debe tener por si se rompe el enganche?","o":["Una bandera atrás","Un segundo conductor en el remolque","Cadenas de seguridad, o frenos que puedan detener el remolque","Nada extra"],"h1":"Algo debe evitar que el remolque se suelte.","h2":"En Dakota del Norte, cuando jala un remolque a más de 25 mph, necesita cadenas de seguridad o frenos que puedan detener el remolque si se rompe el enganche.","p":"Correcto. Necesita cadenas de seguridad o frenos en el remolque."},"ref":{"doc":"ND","page":26}},{"id":"nd-098","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, you are driving down a long hill. May you shift into neutral and coast?","o":["Yes, it saves gas","No, coasting downhill in neutral is not allowed","Yes, but only below 25 mph","Yes, if no one is behind you"],"h1":"The law wants you to keep the car in gear.","h2":"In North Dakota a driver going downhill may not coast with the gears or transmission in neutral.","p":"Right. Coasting downhill in neutral is not allowed."},"es":{"q":"En Dakota del Norte, usted va bajando una cuesta larga. ¿Puede poner neutral y dejar que el carro baje solo?","o":["Sí, ahorra gasolina","No, bajar en neutral no está permitido","Sí, pero solo a menos de 25 mph","Sí, si nadie viene atrás"],"h1":"La ley quiere que mantenga el carro en una marcha.","h2":"En Dakota del Norte un conductor que va cuesta abajo no puede bajar con la transmisión en neutral.","p":"Correcto. Bajar en neutral no está permitido."},"ref":{"doc":"ND","page":26}},{"id":"nd-099","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, what is the fine for a second time driving without liability insurance within three years?","o":["$150","$100","$500","$300"],"h1":"It is twice the fine for a first time.","h2":"In North Dakota the fine for a second or later violation for driving without liability insurance within three years is $300.","p":"Right. A second violation costs $300."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa por manejar sin seguro de responsabilidad civil por segunda vez en tres años?","o":["$150","$100","$500","$300"],"h1":"Es el doble de la multa por la primera vez.","h2":"En Dakota del Norte la multa por una segunda infracción o más por manejar sin seguro de responsabilidad civil en tres años es de $300.","p":"Correcto. Una segunda infracción cuesta $300."},"ref":{"doc":"ND","page":27}},{"id":"nd-100","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, you hit a parked car and no one is in it. You cannot find the owner. What must you do?","o":["Leave a note in plain sight with your name, address and insurance company","Drive away, since no one was hurt","Wait one hour and then leave","Only call your own insurance company later"],"h1":"The owner must be able to find you.","h2":"In North Dakota, if you hit an unattended vehicle and cannot find the owner, you must leave a note in plain sight on it with your name, address and insurance company.","p":"Right. Leave a note with your name, address and insurance company."},"es":{"q":"En Dakota del Norte, usted choca contra un carro estacionado y no hay nadie en él. No puede encontrar al dueño. ¿Qué debe hacer?","o":["Dejar una nota a la vista con su nombre, dirección y compañía de seguros","Irse, porque nadie salió herido","Esperar una hora y luego irse","Solo llamar después a su propia compañía de seguros"],"h1":"El dueño debe poder encontrarlo.","h2":"En Dakota del Norte, si usted choca contra un vehículo sin nadie y no puede encontrar al dueño, debe dejar una nota a la vista con su nombre, dirección y compañía de seguros.","p":"Correcto. Deje una nota con su nombre, dirección y compañía de seguros."},"ref":{"doc":"ND","page":27}},{"id":"nd-101","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, you have a crash outside city limits with someone hurt. Who must you report it to right away?","o":["Your insurance company only","The Driver License Division by mail","The Highway Patrol or the County Sheriff's Office","The nearest city police, even if far away"],"h1":"Outside a city, the state or county police handle it.","h2":"In North Dakota a crash outside city limits with injury, death or $4,000 or more in damage must be reported right away to the Highway Patrol or the County Sheriff's Office.","p":"Right. Report it to the Highway Patrol or the County Sheriff."},"es":{"q":"En Dakota del Norte, usted tiene un choque fuera de los límites de la ciudad y alguien está herido. ¿A quién debe reportarlo de inmediato?","o":["Solo a su compañía de seguros","A la División de Licencias por correo","A la Patrulla de Caminos o a la oficina del Sheriff del condado","A la policía de la ciudad más cercana, aunque esté lejos"],"h1":"Fuera de la ciudad, se encarga la policía del estado o del condado.","h2":"En Dakota del Norte un choque fuera de los límites de la ciudad con heridos, muertos o $4,000 o más en daños debe reportarse de inmediato a la Patrulla de Caminos o a la oficina del Sheriff del condado.","p":"Correcto. Repórtelo a la Patrulla de Caminos o al Sheriff del condado."},"ref":{"doc":"ND","page":27}},{"id":"nd-102","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what is the court fine for a first DUI conviction (alcohol level under 0.16 percent)?","o":["$250","$500","$1,000","$2,000"],"h1":"It is less than the $750 fine for a first conviction at 0.16 percent or higher.","h2":"In North Dakota a first DUI conviction brings a $500 fine, and more if the alcohol level is 0.16 percent or higher.","p":"Right. A first conviction brings a $500 fine."},"es":{"q":"En Dakota del Norte, ¿cuál es la multa del tribunal por una primera condena por manejar bajo la influencia (nivel de alcohol menor de 0.16 por ciento)?","o":["$250","$500","$1,000","$2,000"],"h1":"Es menos que la multa de $750 por una primera condena con 0.16 por ciento o más.","h2":"En Dakota del Norte una primera condena por manejar bajo la influencia trae una multa de $500, y más si el nivel de alcohol es de 0.16 por ciento o más.","p":"Correcto. Una primera condena trae una multa de $500."},"ref":{"doc":"ND","page":36}},{"id":"nd-103","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, the car you bring to the road test must have a horn. How far away must the horn be heard?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"It is the same distance a mirror must let you see behind you.","h2":"In North Dakota the horn on a road test vehicle must be clearly heard from 200 feet away.","p":"Right. The horn must be heard from 200 feet."},"es":{"q":"En Dakota del Norte, el carro que usted lleva al examen de manejo debe tener bocina. ¿Desde qué distancia se debe oír la bocina?","o":["200 pies","50 pies","500 pies","1,000 pies"],"h1":"Es la misma distancia que un espejo debe dejarle ver detrás de usted.","h2":"En Dakota del Norte la bocina de un vehículo para el examen de manejo se debe oír claramente desde 200 pies.","p":"Correcto. La bocina se debe oír desde 200 pies."},"ref":{"doc":"ND","page":2}},{"id":"nd-104","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, your car can park itself. May you use it for the road test?","o":["Yes, any car with current registration may be used","Yes, if you tell the examiner first","Only if you use another car or turn the self-parking feature off","Only if you are 18 or older"],"h1":"The examiner must see you park the car yourself.","h2":"In North Dakota self-parking cars are not allowed on the road test, so you must use a different car or turn the self-parking feature off.","p":"Right. Use another car or turn self-parking off."},"es":{"q":"En Dakota del Norte, su carro se puede estacionar solo. ¿Puede usarlo para el examen de manejo?","o":["Sí, se puede usar cualquier carro con registro vigente","Sí, si se lo dice antes al examinador","Solo si usa otro carro o apaga la función de estacionamiento automático","Solo si tiene 18 años o más"],"h1":"El examinador debe verlo a usted estacionar el carro.","h2":"En Dakota del Norte no se permiten carros que se estacionan solos en el examen de manejo, así que usted debe usar otro carro o apagar la función de estacionamiento automático.","p":"Correcto. Use otro carro o apague el estacionamiento automático."},"ref":{"doc":"ND","page":2}},{"id":"nd-105","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, what must you do for your license or permit to be valid?","o":["Keep it at home in a safe place","Show it at a driver license office every year","Have a parent sign it if you are over 18","Sign it, and carry it every time you drive"],"h1":"Your own name and your pocket.","h2":"In North Dakota your license or permit is valid only if you have signed it, and you must have it with you every time you drive.","p":"Right. Sign it and carry it whenever you drive."},"es":{"q":"En Dakota del Norte, ¿qué debe hacer para que su licencia o permiso sea válido?","o":["Guardarlo en casa en un lugar seguro","Mostrarlo en una oficina de licencias cada año","Pedir a un padre que lo firme si usted tiene más de 18 años","Firmarlo y llevarlo cada vez que maneja"],"h1":"Su propia firma y su bolsillo.","h2":"En Dakota del Norte su licencia o permiso es válido solo si usted lo ha firmado, y debe llevarlo cada vez que maneja.","p":"Correcto. Fírmelo y llévelo siempre que maneje."},"ref":{"doc":"ND","page":3}},{"id":"nd-106","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a person has a history of seizures. When may they still get a license?","o":["After 1 month with no seizures","After at least 6 months in a row with no seizures, and a medical exam","Only after 5 years with no seizures","Never"],"h1":"It is half a year, plus a doctor check.","h2":"In North Dakota a person with a history of seizures may get a license after at least six months in a row with no seizures, if they agree to the required medical exam.","p":"Right. Six seizure-free months in a row and a medical exam."},"es":{"q":"En Dakota del Norte, una persona tiene antecedentes de convulsiones. ¿Cuándo puede sacar una licencia de todos modos?","o":["Después de 1 mes sin convulsiones","Después de al menos 6 meses seguidos sin convulsiones y un examen médico","Solo después de 5 años sin convulsiones","Nunca"],"h1":"Es medio año, más una revisión médica.","h2":"En Dakota del Norte una persona con antecedentes de convulsiones puede sacar una licencia después de al menos seis meses seguidos sin convulsiones, si acepta el examen médico requerido.","p":"Correcto. Seis meses seguidos sin convulsiones y un examen médico."},"ref":{"doc":"ND","page":3}},{"id":"nd-107","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, a high school driver education student has no permit yet. When may the student drive the driver education car?","o":["With a certified driving instructor, if the student is at least 14","Alone in the school parking lot","With any parent, on any road","Never, a permit is always needed first"],"h1":"Think of the teacher in the car and the youngest age for driving lessons.","h2":"In North Dakota a high school driver education student who is at least 14 may drive the driver education car without a license or permit while a certified instructor supervises.","p":"Right. At 14 or older, with a certified instructor."},"es":{"q":"En Dakota del Norte, un estudiante de educación vial de la escuela secundaria aún no tiene permiso. ¿Cuándo puede manejar el carro de educación vial?","o":["Con un instructor de manejo certificado, si el estudiante tiene al menos 14 años","Solo en el estacionamiento de la escuela","Con cualquier padre, en cualquier camino","Nunca, siempre se necesita un permiso primero"],"h1":"Piense en el maestro en el carro y en la edad mínima para las clases de manejo.","h2":"En Dakota del Norte un estudiante de educación vial de la escuela secundaria que tenga al menos 14 años puede manejar el carro de educación vial sin licencia ni permiso mientras lo supervisa un instructor certificado.","p":"Correcto. Con 14 años o más y un instructor certificado."},"ref":{"doc":"ND","page":4}},{"id":"nd-108","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, what do you need to ride a motorized bicycle (moped) on the road?","o":["Nothing, if you wear a helmet","A motorcycle license only","You must be at least 14 and carry a valid license or permit","You must be at least 16 and own the moped"],"h1":"It is the same youngest age as for an instruction permit.","h2":"In North Dakota you must be at least 14 and carry a valid license or permit, such as a motorized bicycle permit, to ride a motorized bicycle.","p":"Right. Be 14 or older and carry a license or permit."},"es":{"q":"En Dakota del Norte, ¿qué necesita para andar en una bicicleta motorizada (moped) en el camino?","o":["Nada, si usa casco","Solo una licencia de motocicleta","Tener al menos 14 años y llevar una licencia o permiso válido","Tener al menos 16 años y ser dueño del moped"],"h1":"Es la misma edad mínima que para un permiso de aprendizaje.","h2":"En Dakota del Norte usted debe tener al menos 14 años y llevar una licencia o permiso válido, como un permiso de bicicleta motorizada, para andar en una bicicleta motorizada.","p":"Correcto. Tenga 14 años o más y lleve una licencia o permiso."},"ref":{"doc":"ND","page":38}},{"id":"nd-109","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, you bring your birth certificate to prove who you are. What kind of copy is accepted?","o":["A clear photocopy","A photo on your phone","A hospital birth certificate","The original or a certified copy"],"h1":"Copies you make yourself do not count.","h2":"In North Dakota identity documents must be originals or certified copies; photocopies and hospital certificates are not accepted.","p":"Right. Only originals or certified copies are accepted."},"es":{"q":"En Dakota del Norte, usted lleva su acta de nacimiento para probar quién es. ¿Qué tipo de copia se acepta?","o":["Una fotocopia clara","Una foto en su teléfono","Un certificado de nacimiento del hospital","El original o una copia certificada"],"h1":"Las copias que usted mismo hace no cuentan.","h2":"En Dakota del Norte los documentos de identidad deben ser originales o copias certificadas; no se aceptan fotocopias ni certificados del hospital.","p":"Correcto. Solo se aceptan originales o copias certificadas."},"ref":{"doc":"ND","page":4}},{"id":"nd-110","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, which address may NOT be used as your residence address on your documents?","o":["A house address in a town","A post office box","A farm address","An apartment address"],"h1":"It is a place where you get mail, not where you live.","h2":"In North Dakota a post office box is not accepted as your residence address; your documents must show where you actually live.","p":"Right. A post office box is not a residence address."},"es":{"q":"En Dakota del Norte, ¿qué dirección NO se puede usar como dirección de residencia en sus documentos?","o":["La dirección de una casa en un pueblo","Un apartado postal","La dirección de una granja","La dirección de un apartamento"],"h1":"Es un lugar donde recibe correo, no donde vive.","h2":"En Dakota del Norte no se acepta un apartado postal como dirección de residencia; sus documentos deben mostrar dónde vive usted en realidad.","p":"Correcto. Un apartado postal no es una dirección de residencia."},"ref":{"doc":"ND","page":5}},{"id":"nd-111","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, you bring your cell phone into the knowledge testing area. What happens?","o":["Nothing, if it is turned off","You must start the test over","You get a failed test score","You pay a $25 fee"],"h1":"Phones, bags and notes must stay out of the testing area.","h2":"In North Dakota you get a failed test score if you bring a cell phone or other banned item into the knowledge testing area.","p":"Right. Bringing a phone into the testing area means a failed score."},"es":{"q":"En Dakota del Norte, usted entra con su teléfono celular al área del examen escrito. ¿Qué pasa?","o":["Nada, si está apagado","Debe empezar el examen otra vez","Recibe una nota de examen reprobado","Paga una tarifa de $25"],"h1":"Los teléfonos, bolsos y notas deben quedar fuera del área del examen.","h2":"En Dakota del Norte usted recibe una nota de examen reprobado si entra con un teléfono celular u otro objeto prohibido al área del examen escrito.","p":"Correcto. Entrar con un teléfono al área del examen significa reprobar."},"ref":{"doc":"ND","page":1}},{"id":"nd-112","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, what papers must you show for the car you use on the road test?","o":["Current registration and proof of insurance","Only the title","A repair shop inspection report","No papers are needed"],"h1":"Think of what proves the car is legal to drive and is covered.","h2":"In North Dakota you must show current registration and current proof of insurance for the car you use on the road test.","p":"Right. Bring current registration and proof of insurance."},"es":{"q":"En Dakota del Norte, ¿qué papeles debe mostrar del carro que usa en el examen de manejo?","o":["El registro vigente y la prueba de seguro","Solo el título","Un informe de inspección de un taller","No se necesitan papeles"],"h1":"Piense en lo que prueba que el carro es legal y está asegurado.","h2":"En Dakota del Norte usted debe mostrar el registro vigente y la prueba de seguro vigente del carro que usa en el examen de manejo.","p":"Correcto. Lleve el registro vigente y la prueba de seguro."},"ref":{"doc":"ND","page":2}},{"id":"nd-113","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a driver under 18 has a license canceled by an official order for an alcohol offense while driving. How do they get licensed again?","o":["They wait 30 days and get the license back","They start over as if they never had a permit or license","They only pay a fee","They must wait until age 21"],"h1":"They go back to the very first step.","h2":"In North Dakota a minor whose license is canceled for an alcohol or drug offense is treated as never having had a permit or license, so they must start over with a permit.","p":"Right. They start over from the beginning."},"es":{"q":"En Dakota del Norte, a un conductor menor de 18 años le cancelan la licencia por orden oficial por un delito de alcohol al manejar. ¿Cómo vuelve a tener licencia?","o":["Espera 30 días y le devuelven la licencia","Empieza de nuevo como si nunca hubiera tenido permiso ni licencia","Solo paga una tarifa","Debe esperar hasta los 21 años"],"h1":"Vuelve al primer paso.","h2":"En Dakota del Norte un menor al que le cancelan la licencia por un delito de alcohol o drogas se trata como si nunca hubiera tenido permiso ni licencia, así que debe empezar de nuevo con un permiso.","p":"Correcto. Empieza de nuevo desde el principio."},"ref":{"doc":"ND","page":7}},{"id":"nd-114","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, you permanently lose the use of a hand, arm, foot, leg or eye. What must you do?","o":["Nothing until your next renewal","Tell your insurance company only","Stop driving for one year","Report it to the Driver License Division"],"h1":"The office that issues licenses must know.","h2":"In North Dakota you must report the permanent loss of use of a hand, arm, foot, leg or eye to the Driver License Division.","p":"Right. Report it to the Driver License Division."},"es":{"q":"En Dakota del Norte, usted pierde para siempre el uso de una mano, un brazo, un pie, una pierna o un ojo. ¿Qué debe hacer?","o":["Nada hasta su próxima renovación","Avisar solo a su compañía de seguros","Dejar de manejar por un año","Informarlo a la División de Licencias de Conducir"],"h1":"La oficina que da las licencias debe saberlo.","h2":"En Dakota del Norte usted debe informar a la División de Licencias de Conducir si pierde para siempre el uso de una mano, un brazo, un pie, una pierna o un ojo.","p":"Correcto. Infórmelo a la División de Licencias de Conducir."},"ref":{"doc":"ND","page":7}},{"id":"nd-115","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, when must you apply for a duplicate license?","o":["Every time you buy a new car","Only when you move to a new city","When it is lost, has wrong information, or is too damaged to read","Every two years"],"h1":"Think of a card you cannot use as it is.","h2":"In North Dakota you must apply for a duplicate license if yours is lost, has wrong information, or is too damaged to read.","p":"Right. Lost, wrong or unreadable means a duplicate."},"es":{"q":"En Dakota del Norte, ¿cuándo debe pedir un duplicado de su licencia?","o":["Cada vez que compra un carro nuevo","Solo cuando se muda a otra ciudad","Cuando se pierde, tiene datos incorrectos o está tan dañada que no se puede leer","Cada dos años"],"h1":"Piense en una tarjeta que no puede usar como está.","h2":"En Dakota del Norte usted debe pedir un duplicado si su licencia se pierde, tiene datos incorrectos o está tan dañada que no se puede leer.","p":"Correcto. Perdida, con errores o ilegible significa duplicado."},"ref":{"doc":"ND","page":7}},{"id":"nd-116","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, your license shows restriction 1. What does it mean?","o":["You must wear corrective lenses, such as glasses or contacts, when you drive","You may drive only in daylight","You may drive only cars with automatic transmission","You need outside mirrors"],"h1":"It is the most common restriction, about your eyes.","h2":"In North Dakota restriction 1 on a license means you must wear corrective lenses, such as glasses or contact lenses, when you drive.","p":"Right. Restriction 1 means corrective lenses."},"es":{"q":"En Dakota del Norte, su licencia muestra la restricción 1. ¿Qué significa?","o":["Debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar","Solo puede manejar de día","Solo puede manejar carros de transmisión automática","Necesita espejos exteriores"],"h1":"Es la restricción más común, sobre sus ojos.","h2":"En Dakota del Norte la restricción 1 en una licencia significa que usted debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar.","p":"Correcto. La restricción 1 significa lentes correctivos."},"ref":{"doc":"ND","page":7}},{"id":"nd-117","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, you will be in the state only a short time and your car still has a current registration from another state. For how long can you buy a temporary registration permit?","o":["30 or 60 days","1 or 2 years","3 months only","6 or 12 months"],"h1":"It is half a year or a full year.","h2":"In North Dakota a temporary registration permit is sold for six months or 12 months, with a $10 service fee each time.","p":"Right. Temporary permits are for 6 or 12 months."},"es":{"q":"En Dakota del Norte, usted estará en el estado poco tiempo y su carro todavía tiene un registro vigente de otro estado. ¿Por cuánto tiempo puede comprar un permiso temporal de registro?","o":["30 o 60 días","1 o 2 años","Solo 3 meses","6 o 12 meses"],"h1":"Es medio año o un año completo.","h2":"En Dakota del Norte un permiso temporal de registro se vende por seis meses o 12 meses, con una tarifa de servicio de $10 cada vez.","p":"Correcto. Los permisos temporales son por 6 o 12 meses."},"ref":{"doc":"ND","page":8}},{"id":"nd-118","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, where must the vehicle registration card be kept?","o":["At home with the title","In the vehicle at all times","At the county office","With your insurance agent"],"h1":"An officer may ask to see it during a stop.","h2":"In North Dakota the vehicle registration card must be carried in the vehicle at all times.","p":"Right. Keep the registration card in the vehicle."},"es":{"q":"En Dakota del Norte, ¿dónde se debe guardar la tarjeta de registro del vehículo?","o":["En casa con el título","En el vehículo en todo momento","En la oficina del condado","Con su agente de seguros"],"h1":"Un oficial puede pedir verla en una parada.","h2":"En Dakota del Norte la tarjeta de registro del vehículo se debe llevar en el vehículo en todo momento.","p":"Correcto. Guarde la tarjeta de registro en el vehículo."},"ref":{"doc":"ND","page":8}},{"id":"nd-119","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, how many classes of operator's license are there?","o":["Two","Three","Five","Seven"],"h1":"They are A, B, C, D and M.","h2":"In North Dakota there are five classes of operator's license: A, B, C, D and M.","p":"Right. There are five classes: A, B, C, D and M."},"es":{"q":"En Dakota del Norte, ¿cuántas clases de licencia de conducir hay?","o":["Dos","Tres","Cinco","Siete"],"h1":"Son A, B, C, D y M.","h2":"En Dakota del Norte hay cinco clases de licencia de conducir: A, B, C, D y M.","p":"Correcto. Hay cinco clases: A, B, C, D y M."},"ref":{"doc":"ND","page":8}},{"id":"nd-120","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, may you drive a motor home (RV) for personal use with a Class D license?","o":["Yes, an RV or camper may be driven with a Class D license","No, you need a Class B license","No, you need a Class A license","Only with a motorcycle endorsement"],"h1":"The handbook lists RVs and campers among vehicles allowed on a Class D.","h2":"In North Dakota an RV, a camper, or a vehicle towing a travel trailer for personal use may be driven with a Class D license.","p":"Right. A Class D license covers an RV for personal use."},"es":{"q":"En Dakota del Norte, ¿puede manejar una casa rodante (RV) para uso personal con una licencia Clase D?","o":["Sí, se puede manejar un RV o camper con una licencia Clase D","No, necesita una licencia Clase B","No, necesita una licencia Clase A","Solo con un endoso de motocicleta"],"h1":"El manual pone los RV y campers entre los vehículos permitidos con la Clase D.","h2":"En Dakota del Norte se puede manejar un RV, un camper o un vehículo que remolca un tráiler de viaje para uso personal con una licencia Clase D.","p":"Correcto. La licencia Clase D cubre un RV para uso personal."},"ref":{"doc":"ND","page":8}},{"id":"nd-121","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, under the farm exemption, how far from the family farm may a 15-year-old with a Class D license drive a farm vehicle hauling farm products?","o":["Only on the farm itself","Within 10 miles","Within 50 miles","Within 150 miles"],"h1":"It is more than a hundred miles.","h2":"In North Dakota a 15-year-old may drive a farm vehicle within 150 miles of the farm when hauling farm products or supplies, if it weighs no more than 50,000 pounds.","p":"Right. Within 150 miles of the farm."},"es":{"q":"En Dakota del Norte, bajo la exención agrícola, ¿a qué distancia de la granja familiar puede un joven de 15 años con licencia Clase D manejar un vehículo agrícola que lleva productos de la granja?","o":["Solo dentro de la granja","Dentro de 10 millas","Dentro de 50 millas","Dentro de 150 millas"],"h1":"Es más de cien millas.","h2":"En Dakota del Norte un joven de 15 años puede manejar un vehículo agrícola dentro de 150 millas de la granja cuando lleva productos o suministros agrícolas, si no pesa más de 50,000 libras.","p":"Correcto. Dentro de 150 millas de la granja."},"ref":{"doc":"ND","page":8}},{"id":"nd-122","scope":"ND","cat":"signals","sign":null,"c":1,"en":{"q":"In North Dakota, what does the number on a green milepost sign tell you?","o":["How far it is to the next city","How many miles you are from the south or west border of the state, or the start of the route","The speed limit for the next mile","How many miles to the next rest area"],"h1":"The count starts at one edge of the state.","h2":"In North Dakota the number on a milepost sign tells you how many miles you are from the south or west border of the state, or from where the route begins in the state.","p":"Right. Mileposts count from the south or west border, or the route start."},"es":{"q":"En Dakota del Norte, ¿qué le dice el número en un letrero verde de poste de milla?","o":["Qué tan lejos está la próxima ciudad","A cuántas millas está usted de la frontera sur u oeste del estado, o del inicio de la ruta","El límite de velocidad de la próxima milla","Cuántas millas faltan para la próxima área de descanso"],"h1":"La cuenta empieza en un borde del estado.","h2":"En Dakota del Norte el número en un letrero de poste de milla le dice a cuántas millas está usted de la frontera sur u oeste del estado, o de donde empieza la ruta en el estado.","p":"Correcto. Los postes de milla cuentan desde la frontera sur u oeste, o el inicio de la ruta."},"ref":{"doc":"ND","page":14}},{"id":"nd-123","scope":"ND","cat":"signals","sign":null,"c":2,"en":{"q":"In North Dakota, in a work zone, the stripes on a barricade slope down to the right. What do they tell you?","o":["Stop ahead","Keep to the left","Keep to the right","The road is closed"],"h1":"Follow the direction the stripes slope down toward.","h2":"In North Dakota barricade stripes that slope down to the right mean you should keep to the right.","p":"Right. Stripes sloping down to the right mean keep right."},"es":{"q":"En Dakota del Norte, en una zona de obras, las rayas de una barricada bajan hacia la derecha. ¿Qué le indican?","o":["Pare más adelante","Manténgase a la izquierda","Manténgase a la derecha","El camino está cerrado"],"h1":"Siga la dirección hacia donde bajan las rayas.","h2":"En Dakota del Norte las rayas de una barricada que bajan hacia la derecha significan que usted debe mantenerse a la derecha.","p":"Correcto. Rayas que bajan a la derecha significan mantenerse a la derecha."},"ref":{"doc":"ND","page":13}},{"id":"nd-124","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, a school bus or gasoline truck must stop at a railroad crossing. At most, how far from the tracks must it stop?","o":["50 feet","25 feet","100 feet","200 feet"],"h1":"It must stop no closer than 15 feet, and not much farther away.","h2":"In North Dakota school buses, passenger buses and vehicles carrying fuel or explosives must stop within 50 feet of the tracks, but not closer than 15 feet.","p":"Right. They stop within 50 feet of the tracks."},"es":{"q":"En Dakota del Norte, un autobús escolar o un camión de gasolina debe parar en un cruce de tren. ¿A qué distancia máxima de las vías debe parar?","o":["50 pies","25 pies","100 pies","200 pies"],"h1":"Debe parar a no menos de 15 pies, y no mucho más lejos.","h2":"En Dakota del Norte los autobuses escolares, los autobuses con pasajeros y los vehículos que llevan combustible o explosivos deben parar a no más de 50 pies de las vías, pero no a menos de 15 pies.","p":"Correcto. Paran a no más de 50 pies de las vías."},"ref":{"doc":"ND","page":18}},{"id":"nd-125","scope":"ND","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Dakota, you are coming up to an intersection and your view of it is blocked. What is the speed limit, unless a sign says otherwise?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"It is the same limit as near a school at recess.","h2":"In North Dakota the speed limit is 20 mph when you approach an intersection and your view of it is blocked, unless a sign says otherwise.","p":"Right. It is 20 mph when your view of the intersection is blocked."},"es":{"q":"En Dakota del Norte, usted se acerca a una intersección y no puede verla bien. ¿Cuál es el límite de velocidad, a menos que un letrero diga otra cosa?","o":["15 mph","25 mph","30 mph","20 mph"],"h1":"Es el mismo límite que cerca de una escuela en el recreo.","h2":"En Dakota del Norte el límite de velocidad es de 20 mph cuando usted se acerca a una intersección y no puede verla bien, a menos que un letrero diga otra cosa.","p":"Correcto. Son 20 mph cuando no puede ver bien la intersección."},"ref":{"doc":"ND","page":20}},{"id":"nd-126","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, what is the speed limit on a paved two-lane county or township road when no limit is posted?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"It is the same as on a gravel road with no sign.","h2":"In North Dakota the speed limit on a paved two-lane county or township road with no posted limit is 55 mph.","p":"Right. It is 55 mph on an unposted paved county or township road."},"es":{"q":"En Dakota del Norte, ¿cuál es el límite de velocidad en un camino pavimentado de dos carriles del condado o del municipio cuando no hay límite señalado?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Es igual que en un camino de grava sin letrero.","h2":"En Dakota del Norte el límite de velocidad en un camino pavimentado de dos carriles del condado o del municipio sin límite señalado es de 55 mph.","p":"Correcto. Son 55 mph en un camino pavimentado del condado o municipio sin letrero."},"ref":{"doc":"ND","page":20}},{"id":"nd-127","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, you are pulling out of a private drive onto a road. Who has the right of way?","o":["You do, if you signal","Whoever is going faster","All traffic on the road","Only traffic coming from your left"],"h1":"The road is theirs until you can enter safely.","h2":"In North Dakota a driver entering or crossing a road from a private drive must yield to all traffic on the road.","p":"Right. Yield to all traffic on the road."},"es":{"q":"En Dakota del Norte, usted sale de una entrada privada a un camino. ¿Quién tiene el derecho de paso?","o":["Usted, si pone la direccional","El que va más rápido","Todo el tráfico del camino","Solo el tráfico que viene de su izquierda"],"h1":"El camino es de ellos hasta que usted pueda entrar con seguridad.","h2":"En Dakota del Norte un conductor que entra o cruza un camino desde una entrada privada debe ceder el paso a todo el tráfico del camino.","p":"Correcto. Ceda el paso a todo el tráfico del camino."},"ref":{"doc":"ND","page":20}},{"id":"nd-128","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, you drive out of an alley in a business district. There is a sidewalk ahead. Where must you stop?","o":["Just before you cross the sidewalk","Only at the edge of the street","You do not need to stop if no one is there","In the middle of the sidewalk, to see better"],"h1":"People on foot may be walking past.","h2":"In North Dakota, in a business or residential district, a driver coming out of an alley, driveway or building must stop completely before crossing the sidewalk.","p":"Right. Stop before you cross the sidewalk."},"es":{"q":"En Dakota del Norte, usted sale de un callejón en una zona comercial. Hay una acera adelante. ¿Dónde debe parar?","o":["Justo antes de cruzar la acera","Solo en el borde de la calle","No necesita parar si no hay nadie","En medio de la acera, para ver mejor"],"h1":"Puede haber personas caminando.","h2":"En Dakota del Norte, en una zona comercial o residencial, el conductor que sale de un callejón, una entrada o un edificio debe parar por completo antes de cruzar la acera.","p":"Correcto. Pare antes de cruzar la acera."},"ref":{"doc":"ND","page":20}},{"id":"nd-129","scope":"ND","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In North Dakota, a school bus ahead turns on flashing yellow lights. What does it mean?","o":["You may pass the bus quickly","The bus is broken down","Children have finished getting off","The bus is about to stop, and the red lights will soon flash"],"h1":"Yellow comes before red.","h2":"In North Dakota flashing yellow lights on a school bus warn that the bus is about to stop and its red lights will soon come on.","p":"Right. Yellow lights mean the bus is about to stop."},"es":{"q":"En Dakota del Norte, un autobús escolar adelante enciende luces amarillas intermitentes. ¿Qué significa?","o":["Puede pasar al autobús rápidamente","El autobús está descompuesto","Los niños ya terminaron de bajar","El autobús va a parar y pronto se encenderán las luces rojas"],"h1":"El amarillo viene antes que el rojo.","h2":"En Dakota del Norte las luces amarillas intermitentes de un autobús escolar avisan que el autobús va a parar y que pronto se encenderán sus luces rojas.","p":"Correcto. Las luces amarillas significan que el autobús va a parar."},"ref":{"doc":"ND","page":20}},{"id":"nd-130","scope":"ND","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In North Dakota, fog, snow or rain is cutting down how far you can see. May you pass another vehicle?","o":["Yes, if you use your headlights","No, never pass when your view is reduced by fog, snow or rain","Yes, on a four-lane road only","Yes, if you honk first"],"h1":"You must be able to see the road ahead clearly to pass.","h2":"In North Dakota you must never pass when fog, snow or rain reduces or blocks your view of the road.","p":"Right. Do not pass when your view is reduced."},"es":{"q":"En Dakota del Norte, la neblina, la nieve o la lluvia reducen lo que usted puede ver. ¿Puede rebasar a otro vehículo?","o":["Sí, si usa los faros","No, nunca rebase cuando la neblina, la nieve o la lluvia reducen su visión","Sí, solo en un camino de cuatro carriles","Sí, si toca la bocina primero"],"h1":"Para rebasar debe ver bien el camino adelante.","h2":"En Dakota del Norte usted nunca debe rebasar cuando la neblina, la nieve o la lluvia reducen o bloquean su visión del camino.","p":"Correcto. No rebase cuando su visión está reducida."},"ref":{"doc":"ND","page":21}},{"id":"nd-131","scope":"ND","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In North Dakota, you are passing a slow car. May you drive onto the shoulder to get around it?","o":["Yes, if the shoulder is paved","Yes, on the right side only","No, when passing you must never leave the main road","Yes, if the car ahead signals you"],"h1":"Passing happens on the traveled part of the road only.","h2":"In North Dakota, when you pass, you must never leave the main traveled part of the road, so you may not use the shoulder.","p":"Right. Never leave the main road when passing."},"es":{"q":"En Dakota del Norte, usted rebasa a un carro lento. ¿Puede manejar sobre el acotamiento para pasarlo?","o":["Sí, si el acotamiento está pavimentado","Sí, solo por el lado derecho","No, al rebasar nunca debe salirse del camino principal","Sí, si el carro de adelante le hace señas"],"h1":"Se rebasa solo en la parte transitada del camino.","h2":"En Dakota del Norte, al rebasar, usted nunca debe salirse de la parte principal transitada del camino, así que no puede usar el acotamiento.","p":"Correcto. Nunca se salga del camino principal al rebasar."},"ref":{"doc":"ND","page":21}},{"id":"nd-132","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, you are pulling a trailer. How much following distance should you keep?","o":["1 second","2 seconds","Exactly 3 seconds","4 seconds or more"],"h1":"You need more than the usual three seconds.","h2":"In North Dakota you should keep four or more seconds of following distance when you have a heavy load or pull a trailer.","p":"Right. Keep four seconds or more with a trailer."},"es":{"q":"En Dakota del Norte, usted remolca un tráiler. ¿Cuánta distancia debe dejar con el vehículo de adelante?","o":["1 segundo","2 segundos","Exactamente 3 segundos","4 segundos o más"],"h1":"Necesita más que los tres segundos de siempre.","h2":"En Dakota del Norte usted debe dejar cuatro segundos o más de distancia cuando lleva una carga pesada o remolca un tráiler.","p":"Correcto. Deje cuatro segundos o más con un tráiler."},"ref":{"doc":"ND","page":22}},{"id":"nd-133","scope":"ND","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In North Dakota, you want to turn left from a one-way street onto another one-way street. Where should you start and finish the turn?","o":["Start in the left lane and turn close to the left curb","Start in the right lane and swing wide","Start in the middle lane and end in the right lane","Start in any lane"],"h1":"On one-way streets the left side is your turning side.","h2":"In North Dakota, to turn left from a one-way street onto a one-way street, begin in the left lane and make the turn close to the left curb.","p":"Right. Start in the left lane and stay close to the left curb."},"es":{"q":"En Dakota del Norte, usted quiere girar a la izquierda de una calle de un solo sentido a otra calle de un solo sentido. ¿Dónde debe empezar y terminar el giro?","o":["Empiece en el carril izquierdo y gire cerca de la orilla izquierda","Empiece en el carril derecho y abra el giro","Empiece en el carril del medio y termine en el carril derecho","Empiece en cualquier carril"],"h1":"En calles de un solo sentido el lado izquierdo es su lado para girar.","h2":"En Dakota del Norte, para girar a la izquierda de una calle de un solo sentido a otra de un solo sentido, empiece en el carril izquierdo y haga el giro cerca de la orilla izquierda.","p":"Correcto. Empiece en el carril izquierdo y quédese cerca de la orilla izquierda."},"ref":{"doc":"ND","page":22}},{"id":"nd-134","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, you are about to enter a roundabout and an emergency vehicle is coming toward it. What should you do?","o":["Enter quickly, before it arrives","Stop inside the roundabout","Do not enter the roundabout","Follow the emergency vehicle in"],"h1":"Keep the circle clear for it.","h2":"In North Dakota you should not enter a roundabout when an emergency vehicle is approaching, so the roundabout stays clear for it to pass.","p":"Right. Wait and do not enter the roundabout."},"es":{"q":"En Dakota del Norte, usted está por entrar a una rotonda y un vehículo de emergencia se acerca a ella. ¿Qué debe hacer?","o":["Entrar rápido antes de que llegue","Parar dentro de la rotonda","No entrar a la rotonda","Entrar detrás del vehículo de emergencia"],"h1":"Deje la rotonda libre para él.","h2":"En Dakota del Norte usted no debe entrar a una rotonda cuando se acerca un vehículo de emergencia, para que la rotonda quede libre y pueda pasar.","p":"Correcto. Espere y no entre a la rotonda."},"ref":{"doc":"ND","page":23}},{"id":"nd-135","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, many roundabouts have a raised apron around the center island. What is it for?","o":["Parking for cars","The rear wheels of large trucks","Bicycle riders","People walking across"],"h1":"Long vehicles need extra room to turn.","h2":"In North Dakota the apron around a roundabout's center island is there for the rear wheels of large trucks and trailers.","p":"Right. The apron is for the rear wheels of large trucks."},"es":{"q":"En Dakota del Norte, muchas rotondas tienen una plataforma elevada alrededor de la isla central. ¿Para qué es?","o":["Para estacionar carros","Para las ruedas traseras de camiones grandes","Para los ciclistas","Para las personas que cruzan a pie"],"h1":"Los vehículos largos necesitan más espacio para girar.","h2":"En Dakota del Norte la plataforma alrededor de la isla central de una rotonda es para las ruedas traseras de camiones grandes y tráileres.","p":"Correcto. La plataforma es para las ruedas traseras de camiones grandes."},"ref":{"doc":"ND","page":23}},{"id":"nd-136","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, you are on an entrance ramp merging onto a freeway. Who has the right of way, unless signs say otherwise?","o":["Vehicles already on the freeway","You, because you are entering","Whichever vehicle is larger","The faster vehicle"],"h1":"The traffic already on the main road keeps moving.","h2":"In North Dakota, unless signs say otherwise, a driver entering a freeway from a ramp must yield to vehicles on the main roadway.","p":"Right. Yield to vehicles already on the freeway."},"es":{"q":"En Dakota del Norte, usted está en una rampa de entrada para unirse a una autopista. ¿Quién tiene el derecho de paso, a menos que los letreros digan otra cosa?","o":["Los vehículos que ya están en la autopista","Usted, porque está entrando","El vehículo más grande","El vehículo más rápido"],"h1":"El tráfico que ya está en el camino principal sigue avanzando.","h2":"En Dakota del Norte, a menos que los letreros digan otra cosa, el conductor que entra a una autopista desde una rampa debe ceder el paso a los vehículos del camino principal.","p":"Correcto. Ceda el paso a los vehículos que ya están en la autopista."},"ref":{"doc":"ND","page":24}},{"id":"nd-137","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, during what hours should you use your headlights, besides other times you need them?","o":["Only after midnight","From 9 p.m. to 5 a.m.","From sunset to sunrise","Only on the Interstate"],"h1":"Think of when the sun is down.","h2":"In North Dakota you should use your headlights from sunset to sunrise, and at any other time they are needed to drive safely.","p":"Right. Use headlights from sunset to sunrise."},"es":{"q":"En Dakota del Norte, ¿en qué horas debe usar los faros, además de otras veces que los necesite?","o":["Solo después de medianoche","De 9 p.m. a 5 a.m.","Desde la puesta del sol hasta la salida del sol","Solo en la autopista interestatal"],"h1":"Piense en cuando no hay sol.","h2":"En Dakota del Norte usted debe usar los faros desde la puesta del sol hasta la salida del sol, y en cualquier otro momento en que los necesite para manejar con seguridad.","p":"Correcto. Use los faros desde la puesta hasta la salida del sol."},"ref":{"doc":"ND","page":24}},{"id":"nd-138","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, your car is parked on a public highway at night. What lights must it show?","o":["No lights, if it is on the shoulder","At least one white or amber light in front and a red light in back, seen from 1,000 feet","Only the hazard lights","High beams"],"h1":"Other drivers must see it from both directions, far away.","h2":"In North Dakota a vehicle parked on a public highway at night must show at least one white or amber light in front and a red light in back, each seen from 1,000 feet.","p":"Right. White or amber in front, red in back, seen from 1,000 feet."},"es":{"q":"En Dakota del Norte, su carro está estacionado en una carretera pública de noche. ¿Qué luces debe mostrar?","o":["Ninguna luz, si está en el acotamiento","Al menos una luz blanca o ámbar adelante y una luz roja atrás, visibles desde 1,000 pies","Solo las luces de emergencia","Las luces altas"],"h1":"Los otros conductores deben verlo desde ambos lados y desde lejos.","h2":"En Dakota del Norte un vehículo estacionado en una carretera pública de noche debe mostrar al menos una luz blanca o ámbar adelante y una luz roja atrás, cada una visible desde 1,000 pies.","p":"Correcto. Blanca o ámbar adelante, roja atrás, visibles desde 1,000 pies."},"ref":{"doc":"ND","page":26}},{"id":"nd-139","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, you start to parallel park. You stop even with the car ahead of the space. About how far from that car should you be?","o":["Touching it","6 inches","6 feet","About 2 feet"],"h1":"Close, but with room to back in.","h2":"In North Dakota, to parallel park, you stop even with the car ahead of the space and about two feet away from it.","p":"Right. Stop about two feet away from it."},"es":{"q":"En Dakota del Norte, usted empieza a estacionarse en paralelo. Para al lado del carro de adelante del espacio. ¿A qué distancia aproximada de ese carro debe estar?","o":["Tocándolo","6 pulgadas","6 pies","Unos 2 pies"],"h1":"Cerca, pero con espacio para retroceder.","h2":"En Dakota del Norte, para estacionarse en paralelo, usted para al lado del carro de adelante del espacio y a unos dos pies de él.","p":"Correcto. Pare a unos dos pies de él."},"ref":{"doc":"ND","page":25}},{"id":"nd-140","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Away from the curb","Straight ahead","It does not matter"],"h1":"If the car rolls, the curb should stop it.","h2":"In North Dakota, when you park facing downhill next to a curb, you turn your front wheels toward the curb.","p":"Right. Downhill, turn the wheels toward the curb."},"es":{"q":"En Dakota del Norte, usted se estaciona cuesta abajo junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la orilla de la acera","Lejos de la orilla de la acera","Rectas","No importa"],"h1":"Si el carro rueda, la orilla debe detenerlo.","h2":"En Dakota del Norte, cuando usted se estaciona cuesta abajo junto a la orilla de la acera, gira las ruedas delanteras hacia la orilla.","p":"Correcto. Cuesta abajo, gire las ruedas hacia la orilla."},"ref":{"doc":"ND","page":25}},{"id":"nd-141","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, you see a parking space for people with disabilities with painted diagonal lines next to it. May you park on the lines?","o":["Yes, if you stay less than 15 minutes","Yes, if you have a placard","No, do not park on the diagonal lines","Yes, at night"],"h1":"Those lines leave room for wheelchairs and lifts.","h2":"In North Dakota you must not park on the diagonal lines next to an accessible parking space.","p":"Right. Never park on the diagonal lines."},"es":{"q":"En Dakota del Norte, usted ve un espacio de estacionamiento para personas con discapacidad con líneas diagonales pintadas al lado. ¿Puede estacionarse sobre las líneas?","o":["Sí, si se queda menos de 15 minutos","Sí, si tiene un permiso colgante","No, no se estacione sobre las líneas diagonales","Sí, de noche"],"h1":"Esas líneas dejan espacio para sillas de ruedas y rampas.","h2":"En Dakota del Norte usted no debe estacionarse sobre las líneas diagonales junto a un espacio de estacionamiento accesible.","p":"Correcto. Nunca se estacione sobre las líneas diagonales."},"ref":{"doc":"ND","page":26}},{"id":"nd-142","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, your trailer needs two amber clearance lamps in front and two red ones in back once it is at least how wide?","o":["60 inches","80 inches","96 inches","102 inches"],"h1":"It is a little under 7 feet.","h2":"In North Dakota a trailer that is 80 inches wide or more needs two amber clearance lamps in front and two red clearance lights in back.","p":"Right. Trailers 80 inches or wider need clearance lamps."},"es":{"q":"En Dakota del Norte, su tráiler necesita dos luces de gálibo ámbar adelante y dos rojas atrás cuando mide por lo menos ¿qué ancho?","o":["60 pulgadas","80 pulgadas","96 pulgadas","102 pulgadas"],"h1":"Es un poco menos de 7 pies.","h2":"En Dakota del Norte un tráiler de 80 pulgadas de ancho o más necesita dos luces de gálibo ámbar adelante y dos luces de gálibo rojas atrás.","p":"Correcto. Los tráileres de 80 pulgadas o más necesitan luces de gálibo."},"ref":{"doc":"ND","page":26}},{"id":"nd-143","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, every vehicle must have a mirror that lets you see at least how far behind you?","o":["50 feet","100 feet","500 feet","200 feet"],"h1":"It is the same distance the horn must be heard on the road test.","h2":"In North Dakota every vehicle must have a mirror that lets the driver see at least 200 feet to the rear.","p":"Right. The mirror must show at least 200 feet behind."},"es":{"q":"En Dakota del Norte, todo vehículo debe tener un espejo que le deje ver por lo menos ¿qué distancia detrás de usted?","o":["50 pies","100 pies","500 pies","200 pies"],"h1":"Es la misma distancia desde la que se debe oír la bocina en el examen de manejo.","h2":"En Dakota del Norte todo vehículo debe tener un espejo que le deje al conductor ver por lo menos 200 pies hacia atrás.","p":"Correcto. El espejo debe mostrar al menos 200 pies hacia atrás."},"ref":{"doc":"ND","page":26}},{"id":"nd-144","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, after a crash with injury or damage, what information must the drivers exchange?","o":["Name, address, insurance company and policy number","Only phone numbers","Driver license photos","Nothing, the police handle it"],"h1":"Who you are, where you live, and who insures you.","h2":"In North Dakota, in every crash with injury or damage, drivers must exchange their name, address, insurance company and policy number.","p":"Right. Exchange name, address, insurance company and policy number."},"es":{"q":"En Dakota del Norte, después de un choque con heridos o daños, ¿qué información deben intercambiar los conductores?","o":["Nombre, dirección, compañía de seguros y número de póliza","Solo los números de teléfono","Fotos de la licencia de conducir","Nada, la policía se encarga"],"h1":"Quién es usted, dónde vive y quién lo asegura.","h2":"En Dakota del Norte, en todo choque con heridos o daños, los conductores deben intercambiar su nombre, dirección, compañía de seguros y número de póliza.","p":"Correcto. Intercambie nombre, dirección, compañía de seguros y número de póliza."},"ref":{"doc":"ND","page":27}},{"id":"nd-145","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, a driver is too hurt to report a crash and does not own the car. Within how many days must the owner report it?","o":["24 hours","30 days","5 days","10 days"],"h1":"It is less than a week.","h2":"In North Dakota, if the driver cannot report a crash and is not the owner, the owner must give notice and insurance information within five days of learning of the crash.","p":"Right. The owner must report it within five days."},"es":{"q":"En Dakota del Norte, un conductor está demasiado herido para informar un choque y no es dueño del carro. ¿En cuántos días debe informarlo el dueño?","o":["24 horas","30 días","5 días","10 días"],"h1":"Es menos de una semana.","h2":"En Dakota del Norte, si el conductor no puede informar un choque y no es el dueño, el dueño debe avisar y dar la información del seguro dentro de cinco días después de saber del choque.","p":"Correcto. El dueño debe informarlo dentro de cinco días."},"ref":{"doc":"ND","page":27}},{"id":"nd-146","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a driver is convicted of having no liability insurance. For how long must they show proof of insurance to the Driver License Division?","o":["30 days","3 months","3 years","1 year"],"h1":"It is twelve months.","h2":"In North Dakota a driver convicted of no liability insurance must provide proof of insurance to the Driver License Division for one year.","p":"Right. Proof of insurance is required for one year."},"es":{"q":"En Dakota del Norte, un conductor es condenado por no tener seguro de responsabilidad civil. ¿Por cuánto tiempo debe mostrar prueba de seguro a la División de Licencias de Conducir?","o":["30 días","3 meses","3 años","1 año"],"h1":"Son doce meses.","h2":"En Dakota del Norte un conductor condenado por no tener seguro de responsabilidad civil debe dar prueba de seguro a la División de Licencias de Conducir por un año.","p":"Correcto. Se exige prueba de seguro por un año."},"ref":{"doc":"ND","page":27}},{"id":"nd-147","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, you are driving fast in very cold weather and spray washer fluid. What can happen?","o":["Nothing, washer fluid never freezes","The fluid can freeze on the windshield and block your view","The engine will stall","Your headlights will turn off"],"h1":"Even with anti-freeze, very cold wind can freeze it.","h2":"In North Dakota, at high speeds in very cold weather, washer fluid can freeze on the windshield and block your view, even with anti-freeze in it.","p":"Right. The fluid can freeze on the glass and block your view."},"es":{"q":"En Dakota del Norte, usted maneja rápido con mucho frío y rocía líquido limpiaparabrisas. ¿Qué puede pasar?","o":["Nada, el líquido nunca se congela","El líquido se puede congelar en el parabrisas y taparle la vista","El motor se apagará","Los faros se apagarán"],"h1":"Aun con anticongelante, el viento muy frío lo puede congelar.","h2":"En Dakota del Norte, a alta velocidad con mucho frío, el líquido limpiaparabrisas se puede congelar en el parabrisas y taparle la vista, aun con anticongelante.","p":"Correcto. El líquido se puede congelar en el vidrio y taparle la vista."},"ref":{"doc":"ND","page":28}},{"id":"nd-148","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, you are driving on snow with snow tires. What should you do with your following distance?","o":["Double it","Keep it the same, snow tires are enough","Cut it in half","Add one car length"],"h1":"Snow tires help, but they do not fix slick roads.","h2":"In North Dakota you should double your following distance on winter roads, even with snow tires or chains.","p":"Right. Double your following distance."},"es":{"q":"En Dakota del Norte, usted maneja sobre nieve con llantas para nieve. ¿Qué debe hacer con la distancia que deja con el vehículo de adelante?","o":["Duplicarla","Dejarla igual, las llantas para nieve bastan","Reducirla a la mitad","Agregar el largo de un carro"],"h1":"Las llantas para nieve ayudan, pero no arreglan un camino resbaloso.","h2":"En Dakota del Norte usted debe duplicar la distancia con el vehículo de adelante en caminos de invierno, aun con llantas para nieve o cadenas.","p":"Correcto. Duplique la distancia."},"ref":{"doc":"ND","page":28}},{"id":"nd-149","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, you are behind a snowplow at work. Why should you stay well back?","o":["Plows always drive above the speed limit","Plows have no brake lights","Plows may stop and back up, cannot see right behind them, and throw sand","Plows only drive on the shoulder"],"h1":"Think of what the plow driver cannot see and what comes off the truck.","h2":"In North Dakota you should stay well back from a snowplow because it may stop and back up, the driver cannot see directly behind, and it throws sand.","p":"Right. Plows may back up, cannot see behind, and throw sand."},"es":{"q":"En Dakota del Norte, usted va detrás de un quitanieves que está trabajando. ¿Por qué debe mantenerse bien atrás?","o":["Los quitanieves siempre van más rápido que el límite","Los quitanieves no tienen luces de freno","Los quitanieves pueden parar y retroceder, no ven justo detrás de ellos y tiran arena","Los quitanieves solo andan por el acotamiento"],"h1":"Piense en lo que el conductor no ve y en lo que cae del camión.","h2":"En Dakota del Norte usted debe mantenerse bien atrás de un quitanieves porque puede parar y retroceder, el conductor no ve justo detrás y tira arena.","p":"Correcto. Pueden retroceder, no ven atrás y tiran arena."},"ref":{"doc":"ND","page":28}},{"id":"nd-150","scope":"ND","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In North Dakota, how deep does water have to be to reach the bottom of most passenger cars, which can cause loss of control or stalling?","o":["1 inch","6 inches","3 feet","4 feet"],"h1":"It is half a foot.","h2":"In North Dakota the handbook warns that six inches of water reaches the bottom of most passenger cars and can cause loss of control or stalling.","p":"Right. Six inches of water reaches the bottom of most cars."},"es":{"q":"En Dakota del Norte, ¿qué tan profunda debe ser el agua para llegar a la parte de abajo de la mayoría de los carros de pasajeros, lo que puede causar pérdida de control o que el motor se apague?","o":["1 pulgada","6 pulgadas","3 pies","4 pies"],"h1":"Es medio pie.","h2":"En Dakota del Norte el manual advierte que seis pulgadas de agua llegan a la parte de abajo de la mayoría de los carros de pasajeros y pueden causar pérdida de control o que el motor se apague.","p":"Correcto. Seis pulgadas de agua llegan a la parte de abajo de la mayoría de los carros."},"ref":{"doc":"ND","page":29}},{"id":"nd-151","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, a rear tire goes flat while you drive. What will the car most likely do?","o":["Pull hard to the left only","Speed up","Stop by itself","Sway back and forth"],"h1":"A front tire pulls to one side; a rear tire acts differently.","h2":"In North Dakota the handbook says a flat rear tire makes the car sway back and forth, while a front blowout pulls toward the blown tire.","p":"Right. A flat rear tire makes the car sway."},"es":{"q":"En Dakota del Norte, se desinfla una llanta trasera mientras usted maneja. ¿Qué hará el carro con más probabilidad?","o":["Jalar fuerte solo a la izquierda","Acelerar","Pararse solo","Moverse de un lado a otro"],"h1":"Una llanta delantera jala hacia un lado; una trasera actúa distinto.","h2":"En Dakota del Norte el manual dice que una llanta trasera desinflada hace que el carro se mueva de un lado a otro, mientras que una delantera reventada jala hacia el lado de esa llanta.","p":"Correcto. Una llanta trasera desinflada hace que el carro se mueva de un lado a otro."},"ref":{"doc":"ND","page":30}},{"id":"nd-153","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a driver's license is suspended for DUI. When can a temporary restricted license be issued, if the driver is not in the 24/7 Sobriety Program?","o":["Right away, on the day of the arrest","After 7 days of the suspension","After at least 30 days of the suspension","Only after the whole suspension ends"],"h1":"It is about one month into the suspension.","h2":"In North Dakota, a temporary restricted license can be issued after at least 30 days of a DUI suspension have been served, or after 14 days for a driver in the 24/7 Sobriety Program.","p":"Right. At least 30 days must be served first."},"es":{"q":"En Dakota del Norte, a un conductor le suspenden la licencia por manejar bajo la influencia (DUI). Si no está en el programa de sobriedad 24/7, ¿cuándo se le puede dar una licencia restringida temporal?","o":["De inmediato, el mismo día del arresto","Después de 7 días de la suspensión","Después de cumplir al menos 30 días de la suspensión","Solo cuando termine toda la suspensión"],"h1":"Es más o menos un mes después de empezar la suspensión.","h2":"En Dakota del Norte, se puede dar una licencia restringida temporal después de cumplir al menos 30 días de una suspensión por DUI, o 14 días si el conductor está en el programa de sobriedad 24/7.","p":"Correcto. Primero debe cumplir al menos 30 días."},"ref":{"doc":"ND","page":36}},{"id":"nd-154","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, a driver suspended for DUI joins the 24/7 Sobriety Program. After how many days of the suspension can a temporary restricted license be issued?","o":["At least 14 days","At least 3 days","At least 60 days","At least 91 days"],"h1":"The program shortens the usual 30-day wait to two weeks.","h2":"In North Dakota, a driver in the 24/7 Sobriety Program can get a temporary restricted license after serving at least 14 days of the suspension.","p":"Right. With the 24/7 program, it is at least 14 days."},"es":{"q":"En Dakota del Norte, un conductor suspendido por DUI entra al programa de sobriedad 24/7. ¿Después de cuántos días de la suspensión se le puede dar una licencia restringida temporal?","o":["Al menos 14 días","Al menos 3 días","Al menos 60 días","Al menos 91 días"],"h1":"El programa acorta la espera normal de 30 días a dos semanas.","h2":"En Dakota del Norte, un conductor en el programa de sobriedad 24/7 puede recibir una licencia restringida temporal después de cumplir al menos 14 días de la suspensión.","p":"Correcto. Con el programa 24/7, son al menos 14 días."},"ref":{"doc":"ND","page":36}},{"id":"nd-155","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a driver has a second alcohol offense within seven years, with an alcohol level under 0.18 percent. How long is the license suspended?","o":["91 days","30 days","10 years","365 days"],"h1":"It is a full year.","h2":"In North Dakota, a second alcohol offense within seven years, with an alcohol level under 0.18 percent, brings a license suspension of 365 days.","p":"Right. A second offense in seven years means 365 days."},"es":{"q":"En Dakota del Norte, un conductor comete una segunda infracción por alcohol en siete años, con un nivel de alcohol menor de 0.18 por ciento. ¿Por cuánto tiempo le suspenden la licencia?","o":["91 días","30 días","10 años","365 días"],"h1":"Es un año completo.","h2":"En Dakota del Norte, una segunda infracción por alcohol en siete años, con un nivel de alcohol menor de 0.18 por ciento, trae una suspensión de la licencia de 365 días.","p":"Correcto. Una segunda infracción en siete años son 365 días."},"ref":{"doc":"ND","page":36}},{"id":"nd-156","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a driver has a second alcohol offense within seven years, and this time the alcohol level is 0.18 percent or more. How long is the license suspended?","o":["91 days","Two years","180 days","30 days"],"h1":"A high alcohol level on a second offense means more than one year.","h2":"In North Dakota, a second alcohol offense within seven years with an alcohol level of 0.18 percent or more brings a two-year license suspension.","p":"Right. It is two years."},"es":{"q":"En Dakota del Norte, un conductor comete una segunda infracción por alcohol en siete años, y esta vez el nivel de alcohol es de 0.18 por ciento o más. ¿Por cuánto tiempo le suspenden la licencia?","o":["91 días","Dos años","180 días","30 días"],"h1":"Un nivel alto de alcohol en una segunda infracción significa más de un año.","h2":"En Dakota del Norte, una segunda infracción por alcohol en siete años con un nivel de alcohol de 0.18 por ciento o más trae una suspensión de la licencia de dos años.","p":"Correcto. Son dos años."},"ref":{"doc":"ND","page":36}},{"id":"nd-157","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, a driver has a third alcohol offense within seven years, with an alcohol level of 0.18 percent or more. How long is the license suspended?","o":["One year","Three years","91 days","Two years"],"h1":"This is the longest suspension on the handbook's list.","h2":"In North Dakota, a third or later alcohol offense within seven years with an alcohol level of 0.18 percent or more brings a three-year license suspension.","p":"Right. It is three years."},"es":{"q":"En Dakota del Norte, un conductor comete una tercera infracción por alcohol en siete años, con un nivel de alcohol de 0.18 por ciento o más. ¿Por cuánto tiempo le suspenden la licencia?","o":["Un año","Tres años","91 días","Dos años"],"h1":"Es la suspensión más larga de la lista del manual.","h2":"En Dakota del Norte, una tercera infracción por alcohol (o más) en siete años con un nivel de alcohol de 0.18 por ciento o más trae una suspensión de la licencia de tres años.","p":"Correcto. Son tres años."},"ref":{"doc":"ND","page":36}},{"id":"nd-158","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a person drives while the license is suspended for an alcohol violation. What is the smallest jail sentence?","o":["No jail, only a warning","1 hour","1 day, which can be skipped","4 days"],"h1":"The law sets a mandatory minimum of a few days.","h2":"In North Dakota, driving while your license is suspended or revoked after an alcohol violation brings a mandatory minimum of four days in jail, plus a fine.","p":"Right. At least 4 days in jail."},"es":{"q":"En Dakota del Norte, una persona maneja con la licencia suspendida por una infracción de alcohol. ¿Cuál es la pena de cárcel más corta?","o":["Sin cárcel, solo una advertencia","1 hora","1 día, que se puede saltar","4 días"],"h1":"La ley fija un mínimo obligatorio de unos días.","h2":"En Dakota del Norte, manejar con la licencia suspendida o revocada después de una infracción de alcohol trae un mínimo obligatorio de cuatro días de cárcel, más una multa.","p":"Correcto. Al menos 4 días de cárcel."},"ref":{"doc":"ND","page":36}},{"id":"nd-159","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, a license is suspended or revoked after an alcohol violation. What can also happen to the vehicle's license plates and registration card?","o":["They may be taken (impounded) for as long as the suspension lasts","Nothing; they stay with the car","They must be painted a different color","They are given to the driver's insurance company"],"h1":"Without them, the car cannot be driven legally.","h2":"In North Dakota, the license plates and registration card of your vehicle may be impounded for the length of an alcohol-related suspension or revocation.","p":"Right. Plates and registration may be impounded."},"es":{"q":"En Dakota del Norte, una licencia es suspendida o revocada después de una infracción de alcohol. ¿Qué más puede pasar con las placas y la tarjeta de registro del vehículo?","o":["Se las pueden quitar (confiscar) mientras dure la suspensión","Nada; se quedan con el carro","Deben pintarse de otro color","Se entregan a la compañía de seguros del conductor"],"h1":"Sin ellas, el carro no se puede manejar legalmente.","h2":"En Dakota del Norte, las placas y la tarjeta de registro de su vehículo se pueden confiscar durante todo el tiempo de una suspensión o revocación por alcohol.","p":"Correcto. Pueden confiscar las placas y el registro."},"ref":{"doc":"ND","page":36}},{"id":"nd-160","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a driver's first DUI conviction is for an alcohol level of 0.16 percent or more. What is the court penalty?","o":["A $100 fine only","A warning letter","A fine of at least $750 and at least two days in jail","A $25 fine and one point"],"h1":"A very high alcohol level makes even a first offense come with jail time.","h2":"In North Dakota, a first DUI conviction with an alcohol level of 0.16 percent or more brings a fine of at least $750 and at least two days in jail, which may be changed to community service.","p":"Right. At least $750 and two days in jail."},"es":{"q":"En Dakota del Norte, la primera condena por DUI de un conductor es con un nivel de alcohol de 0.16 por ciento o más. ¿Cuál es la pena del tribunal?","o":["Solo una multa de $100","Una carta de advertencia","Una multa de al menos $750 y al menos dos días de cárcel","Una multa de $25 y un punto"],"h1":"Un nivel de alcohol muy alto hace que incluso una primera infracción tenga cárcel.","h2":"En Dakota del Norte, una primera condena por DUI con un nivel de alcohol de 0.16 por ciento o más trae una multa de al menos $750 y al menos dos días de cárcel, que se pueden cambiar por servicio comunitario.","p":"Correcto. Al menos $750 y dos días de cárcel."},"ref":{"doc":"ND","page":36}},{"id":"nd-161","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a driver is convicted of DUI for the second time within seven years. How many days in jail does the sentence include?","o":["1 day","120 days","No jail","10 days"],"h1":"It is more than a week but less than a month.","h2":"In North Dakota, a second DUI conviction within seven years brings at least 10 days in jail, a $1,500 fine, and at least 360 days in the 24/7 Sobriety Program.","p":"Right. A second DUI in seven years means at least 10 days in jail."},"es":{"q":"En Dakota del Norte, un conductor es condenado por DUI por segunda vez en siete años. ¿Cuántos días de cárcel incluye la sentencia?","o":["1 día","120 días","Sin cárcel","10 días"],"h1":"Es más de una semana pero menos de un mes.","h2":"En Dakota del Norte, una segunda condena por DUI en siete años trae al menos 10 días de cárcel, una multa de $1,500 y al menos 360 días en el programa de sobriedad 24/7.","p":"Correcto. Un segundo DUI en siete años significa al menos 10 días de cárcel."},"ref":{"doc":"ND","page":36}},{"id":"nd-162","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a driver is convicted of DUI for the third time within seven years. What is the sentence?","o":["A $500 fine and no jail","A $250 fine and 2 days in jail","A $2,000 fine and 120 days in jail","A $100 fine and 10 days in jail"],"h1":"Jail time is about four months.","h2":"In North Dakota, a third DUI conviction within seven years brings a $2,000 fine, 120 days in jail and the 24/7 Sobriety Program as a condition of probation.","p":"Right. A $2,000 fine and 120 days in jail."},"es":{"q":"En Dakota del Norte, un conductor es condenado por DUI por tercera vez en siete años. ¿Cuál es la sentencia?","o":["Una multa de $500 y sin cárcel","Una multa de $250 y 2 días de cárcel","Una multa de $2,000 y 120 días de cárcel","Una multa de $100 y 10 días de cárcel"],"h1":"La cárcel es de unos cuatro meses.","h2":"En Dakota del Norte, una tercera condena por DUI en siete años trae una multa de $2,000, 120 días de cárcel y el programa de sobriedad 24/7 como condición de la libertad condicional.","p":"Correcto. Una multa de $2,000 y 120 días de cárcel."},"ref":{"doc":"ND","page":37}},{"id":"nd-163","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how much jail time comes with a fourth DUI offense?","o":["10 days","One year and one day","30 days","Two days"],"h1":"It is just over one year.","h2":"In North Dakota, a fourth or later DUI offense brings one year and one day in jail, a $2,000 fine and the 24/7 Sobriety Program.","p":"Right. One year and one day."},"es":{"q":"En Dakota del Norte, ¿cuánto tiempo de cárcel trae una cuarta infracción por DUI?","o":["10 días","Un año y un día","30 días","Dos días"],"h1":"Es un poco más de un año.","h2":"En Dakota del Norte, una cuarta infracción por DUI (o más) trae un año y un día de cárcel, una multa de $2,000 y el programa de sobriedad 24/7.","p":"Correcto. Un año y un día."},"ref":{"doc":"ND","page":37}},{"id":"nd-164","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, besides fines and jail, what must every person convicted of DUI do?","o":["Get an alcohol addiction evaluation and complete any treatment it recommends","Retake only the vision test","Pay for a new license plate design","Nothing else"],"h1":"It is a check of the person's use of alcohol.","h2":"In North Dakota, everyone convicted of DUI must have an alcohol addiction evaluation and complete any treatment that is recommended.","p":"Right. An addiction evaluation and any recommended treatment."},"es":{"q":"En Dakota del Norte, además de multas y cárcel, ¿qué debe hacer toda persona condenada por DUI?","o":["Hacerse una evaluación de adicción al alcohol y completar el tratamiento que se recomiende","Repetir solo el examen de la vista","Pagar por un nuevo diseño de placa","Nada más"],"h1":"Es una revisión del uso de alcohol de la persona.","h2":"En Dakota del Norte, toda persona condenada por DUI debe hacerse una evaluación de adicción al alcohol y completar cualquier tratamiento que se recomiende.","p":"Correcto. Una evaluación de adicción y el tratamiento recomendado."},"ref":{"doc":"ND","page":37}},{"id":"nd-165","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a driver refuses an alcohol test or is convicted of DUI. What must the driver then show about insurance?","o":["Nothing; insurance does not change","A letter from a friend","Proof of financial responsibility, called SR-22 insurance","Proof the car is paid off"],"h1":"It is a special filing that proves you are insured.","h2":"In North Dakota, after refusing an alcohol test or a DUI conviction, the law requires you to show proof of financial responsibility (SR-22 insurance), and your insurance rates may double or triple.","p":"Right. You must show SR-22 proof of insurance."},"es":{"q":"En Dakota del Norte, un conductor se niega a una prueba de alcohol o es condenado por DUI. ¿Qué debe mostrar después sobre su seguro?","o":["Nada; el seguro no cambia","Una carta de un amigo","Prueba de responsabilidad financiera, llamada seguro SR-22","Prueba de que el carro está pagado"],"h1":"Es un documento especial que prueba que usted tiene seguro.","h2":"En Dakota del Norte, después de negarse a una prueba de alcohol o de una condena por DUI, la ley exige mostrar prueba de responsabilidad financiera (seguro SR-22), y el costo de su seguro puede duplicarse o triplicarse.","p":"Correcto. Debe mostrar la prueba de seguro SR-22."},"ref":{"doc":"ND","page":37}},{"id":"nd-166","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, an adult passenger wants to drink a beer while you drive. Is it legal?","o":["No, no one in a vehicle, driver or passenger, may drink alcohol","Yes, only the driver may not drink","Yes, if the windows are closed","Yes, on rural roads"],"h1":"The law covers everyone in or on the vehicle.","h2":"In North Dakota, it is illegal for anyone, driver or passenger, to drink alcohol in or on a motor vehicle.","p":"Right. No one in the vehicle may drink."},"es":{"q":"En Dakota del Norte, un pasajero adulto quiere tomar una cerveza mientras usted maneja. ¿Es legal?","o":["No, nadie en un vehículo, ni el conductor ni los pasajeros, puede tomar alcohol","Sí, solo el conductor no puede tomar","Sí, si las ventanas están cerradas","Sí, en caminos rurales"],"h1":"La ley cubre a todos los que van dentro o encima del vehículo.","h2":"En Dakota del Norte, es ilegal que cualquier persona, conductor o pasajero, tome bebidas alcohólicas dentro o encima de un vehículo motorizado.","p":"Correcto. Nadie en el vehículo puede tomar."},"ref":{"doc":"ND","page":37}},{"id":"nd-167","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a driver's record shows 15 points and the license is suspended. How long is the suspension?","o":["7 days","15 days","1 year","28 days"],"h1":"It is 7 days for each point over 11.","h2":"In North Dakota, a driver with 13 or more points is suspended 7 days for each point over 11, so 15 points means 4 times 7, or 28 days.","p":"Right. 15 points means 28 days."},"es":{"q":"En Dakota del Norte, el récord de un conductor muestra 15 puntos y le suspenden la licencia. ¿Cuánto dura la suspensión?","o":["7 días","15 días","1 año","28 días"],"h1":"Son 7 días por cada punto por encima de 11.","h2":"En Dakota del Norte, a un conductor con 13 puntos o más le suspenden 7 días por cada punto por encima de 11, así que 15 puntos son 4 por 7, o 28 días.","p":"Correcto. 15 puntos son 28 días."},"ref":{"doc":"ND","page":40}},{"id":"nd-168","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, you may take a driver improvement course instead of getting points for a ticket. For which tickets is this allowed?","o":["Any violation, even DUI","Violations worth 5 points or less","Only violations worth 10 points or more","Only parking tickets"],"h1":"It is for smaller violations only.","h2":"In North Dakota, you may take an approved driver improvement course instead of getting points for a violation worth five points or less.","p":"Right. Only for violations of 5 points or less."},"es":{"q":"En Dakota del Norte, usted puede tomar un curso de mejoramiento para conductores en lugar de recibir puntos por una multa. ¿Para qué multas se permite?","o":["Cualquier infracción, incluso DUI","Infracciones de 5 puntos o menos","Solo infracciones de 10 puntos o más","Solo multas de estacionamiento"],"h1":"Es solo para infracciones menores.","h2":"En Dakota del Norte, usted puede tomar un curso aprobado de mejoramiento para conductores en lugar de recibir puntos por una infracción de cinco puntos o menos.","p":"Correcto. Solo para infracciones de 5 puntos o menos."},"ref":{"doc":"ND","page":40}},{"id":"nd-169","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, how often may you choose a driver improvement course instead of points on your record?","o":["Once every week","Once every 12 months","As often as you like","Only once in your life"],"h1":"Think of one year.","h2":"In North Dakota, the choice to take a driver improvement course instead of points can be used once every 12 months.","p":"Right. Once every 12 months."},"es":{"q":"En Dakota del Norte, ¿cada cuánto puede elegir un curso de mejoramiento para conductores en lugar de puntos en su récord?","o":["Una vez cada semana","Una vez cada 12 meses","Las veces que quiera","Solo una vez en la vida"],"h1":"Piense en un año.","h2":"En Dakota del Norte, la opción de tomar un curso de mejoramiento para conductores en lugar de recibir puntos se puede usar una vez cada 12 meses.","p":"Correcto. Una vez cada 12 meses."},"ref":{"doc":"ND","page":40}},{"id":"nd-170","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, a parent signed for a 16-year-old's license and now takes back that consent. What happens?","o":["Nothing; consent cannot be taken back","The teen gets two points","The teen must retake driver education","The license is canceled"],"h1":"The parent's signature is what keeps the minor's license valid.","h2":"In North Dakota, the parent or guardian who consented can withdraw consent at any time, and the minor's permit or license is then canceled until consent is given again or the teen turns 18.","p":"Right. The license is canceled."},"es":{"q":"En Dakota del Norte, un padre firmó para la licencia de su hijo de 16 años y ahora retira ese permiso. ¿Qué pasa?","o":["Nada; el permiso no se puede retirar","El joven recibe dos puntos","El joven debe repetir la educación vial","La licencia se cancela"],"h1":"La firma del padre es lo que mantiene válida la licencia del menor.","h2":"En Dakota del Norte, el padre o tutor que dio su consentimiento puede retirarlo en cualquier momento, y el permiso o la licencia del menor se cancela hasta que se dé el consentimiento otra vez o el joven cumpla 18 años.","p":"Correcto. La licencia se cancela."},"ref":{"doc":"ND","page":40}},{"id":"nd-171","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, what does the child passenger law require for children ages 8 through 17?","o":["They must be secured in a seat belt or a child restraint","Nothing; the law ends at age 8","They must ride in a booster seat","They must sit in the front seat"],"h1":"The law does not stop at age 8.","h2":"In North Dakota, children ages 8 through 17 must be properly secured in a seat belt or a child restraint.","p":"Right. A seat belt or child restraint for ages 8 through 17."},"es":{"q":"En Dakota del Norte, ¿qué exige la ley de pasajeros infantiles para niños de 8 a 17 años?","o":["Que vayan asegurados con cinturón de seguridad o un asiento de seguridad","Nada; la ley termina a los 8 años","Que vayan en un asiento elevado","Que se sienten adelante"],"h1":"La ley no termina a los 8 años.","h2":"En Dakota del Norte, los niños de 8 a 17 años deben ir bien asegurados con un cinturón de seguridad o un asiento de seguridad.","p":"Correcto. Cinturón o asiento de seguridad de 8 a 17 años."},"ref":{"doc":"ND","page":34}},{"id":"nd-172","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, the handbook says a child should be at least how big and how old before moving from a car seat to a booster seat?","o":["At least 20 pounds and 1 year old","At least 80 pounds and 10 years old","At least 40 pounds and at least 4 years old","At least 57 inches and 8 years old"],"h1":"Think of a preschool child.","h2":"In North Dakota, the handbook says children should be at least 40 pounds and at least 4 years old to move from a car seat to a booster seat.","p":"Right. At least 40 pounds and 4 years old."},"es":{"q":"En Dakota del Norte, según el manual, ¿qué tamaño y edad debe tener un niño, como mínimo, para pasar de una silla de auto a un asiento elevado (booster)?","o":["Al menos 20 libras y 1 año","Al menos 80 libras y 10 años","Al menos 40 libras y al menos 4 años","Al menos 57 pulgadas y 8 años"],"h1":"Piense en un niño de edad preescolar.","h2":"En Dakota del Norte, el manual dice que los niños deben pesar al menos 40 libras y tener al menos 4 años para pasar de una silla de auto a un asiento elevado.","p":"Correcto. Al menos 40 libras y 4 años."},"ref":{"doc":"ND","page":34}},{"id":"nd-173","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, you are driving a pickup truck and have more children than seats. May some ride in the cargo area (the truck bed)?","o":["Yes, on short trips","Yes, if they sit down","Yes, if an adult rides with them","No, never let children ride in the cargo area of a pickup"],"h1":"The handbook says this is never safe.","h2":"In North Dakota, the handbook says never to allow children to ride in the cargo area of a pickup truck.","p":"Right. Never in the cargo area."},"es":{"q":"En Dakota del Norte, usted maneja una camioneta pickup y tiene más niños que asientos. ¿Pueden algunos ir en la parte de carga (la caja)?","o":["Sí, en viajes cortos","Sí, si van sentados","Sí, si un adulto va con ellos","No, nunca deje que los niños vayan en la parte de carga de una pickup"],"h1":"El manual dice que esto nunca es seguro.","h2":"En Dakota del Norte, el manual dice que nunca se debe permitir que los niños vayan en la parte de carga de una camioneta pickup.","p":"Correcto. Nunca en la parte de carga."},"ref":{"doc":"ND","page":34}},{"id":"nd-174","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, what are the two parts of using a child car seat correctly?","o":["Put the seat in front of the air bag and leave the straps loose","Set the seat on the seat without tying it in","Install the seat tightly with the seat belt or LATCH system, and buckle the child in snugly","Use a pillow under the child instead of straps"],"h1":"Both the seat and the child must be held firmly.","h2":"In North Dakota, using a child restraint correctly means installing the car seat tightly with the seat belt or LATCH system and snugly securing the child in the seat.","p":"Right. A tight seat and a snug child."},"es":{"q":"En Dakota del Norte, ¿cuáles son las dos partes de usar bien una silla de auto para niños?","o":["Poner la silla frente a la bolsa de aire y dejar las correas flojas","Poner la silla sobre el asiento sin sujetarla","Instalar la silla bien firme con el cinturón o el sistema LATCH, y abrochar al niño bien ajustado","Usar una almohada bajo el niño en vez de correas"],"h1":"Tanto la silla como el niño deben quedar bien sujetos.","h2":"En Dakota del Norte, usar bien una silla de auto significa instalarla firmemente con el cinturón de seguridad o el sistema LATCH y asegurar al niño bien ajustado en la silla.","p":"Correcto. Silla firme y niño bien ajustado."},"ref":{"doc":"ND","page":34}},{"id":"nd-175","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, about how far does a fully loaded tractor-trailer need to stop on dry pavement?","o":["More than 400 feet, longer than a football field","About 50 feet","About 100 feet","The same distance as a car"],"h1":"It is more than the length of a football field.","h2":"In North Dakota, the handbook says a fully loaded tractor-trailer may need more than 400 feet on dry pavement to stop, more than the length of a football field.","p":"Right. More than 400 feet."},"es":{"q":"En Dakota del Norte, ¿aproximadamente qué distancia necesita un tráiler (camión de 18 ruedas) completamente cargado para detenerse en pavimento seco?","o":["Más de 400 pies, más que un campo de fútbol americano","Unos 50 pies","Unos 100 pies","La misma distancia que un carro"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Dakota del Norte, el manual dice que un tráiler completamente cargado puede necesitar más de 400 pies en pavimento seco para detenerse, más que el largo de un campo de fútbol americano.","p":"Correcto. Más de 400 pies."},"ref":{"doc":"ND","page":31}},{"id":"nd-176","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, a tractor-trailer's blind spot behind it can reach how far back?","o":["Up to 5 feet","Up to 20 feet","Up to 200 feet","There is no blind spot behind a truck"],"h1":"It is much longer than the truck itself.","h2":"In North Dakota, the handbook says a tractor-trailer's blind spot can reach up to 200 feet behind it, and up to 20 feet in front of the cab.","p":"Right. Up to 200 feet behind."},"es":{"q":"En Dakota del Norte, ¿hasta qué distancia detrás de un tráiler puede llegar su punto ciego?","o":["Hasta 5 pies","Hasta 20 pies","Hasta 200 pies","Un camión no tiene punto ciego atrás"],"h1":"Es mucho más largo que el mismo camión.","h2":"En Dakota del Norte, el manual dice que el punto ciego de un tráiler puede llegar hasta 200 pies detrás de él, y hasta 20 pies delante de la cabina.","p":"Correcto. Hasta 200 pies atrás."},"ref":{"doc":"ND","page":31}},{"id":"nd-177","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, when any vehicle turns, how do its rear wheels move compared with the front wheels?","o":["They follow a shorter path, cutting closer to the inside of the turn","They follow the exact same path","They follow a wider path","They do not move during a turn"],"h1":"That is why long trucks swing wide.","h2":"In North Dakota, the handbook explains that the rear wheels of a turning vehicle follow a shorter path than the front wheels, and the longer the vehicle, the bigger the difference.","p":"Right. The rear wheels take a shorter path."},"es":{"q":"En Dakota del Norte, cuando un vehículo da vuelta, ¿cómo se mueven sus llantas traseras comparadas con las delanteras?","o":["Siguen un camino más corto, más cerca del lado interior de la vuelta","Siguen exactamente el mismo camino","Siguen un camino más amplio","No se mueven durante la vuelta"],"h1":"Por eso los camiones largos abren mucho la vuelta.","h2":"En Dakota del Norte, el manual explica que las llantas traseras de un vehículo que da vuelta siguen un camino más corto que las delanteras, y mientras más largo el vehículo, mayor es la diferencia.","p":"Correcto. Las llantas traseras siguen un camino más corto."},"ref":{"doc":"ND","page":31}},{"id":"nd-178","scope":"ND","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In North Dakota, on a multi-lane highway, which lane do tractor-trailers usually stay in?","o":["The far left lane","The shoulder","The far right lane only","The center lane"],"h1":"It helps local traffic get on and off the highway.","h2":"In North Dakota, the handbook says tractor-trailers stay in the center lane on multi-lane highways to help local traffic get on and off, and to have room to change lanes in an emergency.","p":"Right. Trucks usually stay in the center lane."},"es":{"q":"En Dakota del Norte, en una carretera de varios carriles, ¿en qué carril suelen ir los tráileres?","o":["El carril de la extrema izquierda","El acotamiento","Solo el carril de la extrema derecha","El carril del centro"],"h1":"Ayuda al tráfico local a entrar y salir de la carretera.","h2":"En Dakota del Norte, el manual dice que los tráileres van en el carril del centro en carreteras de varios carriles para ayudar al tráfico local a entrar y salir, y para tener espacio para cambiar de carril en una emergencia.","p":"Correcto. Los camiones suelen ir en el carril del centro."},"ref":{"doc":"ND","page":32}},{"id":"nd-179","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, on which side should you pass a tractor-trailer?","o":["On the right, if that lane is open","Always on the left, and pass it completely","On the shoulder","Either side, then stay beside it"],"h1":"Pass where the truck driver can see you best, and do not stay alongside.","h2":"In North Dakota, the handbook says always pass a tractor-trailer on the left side and pass it completely, without lingering beside it.","p":"Right. Pass on the left, completely."},"es":{"q":"En Dakota del Norte, ¿por qué lado debe rebasar a un tráiler?","o":["Por la derecha, si ese carril está libre","Siempre por la izquierda, y rebasarlo por completo","Por el acotamiento","Por cualquier lado, y luego quedarse a su lado"],"h1":"Rebase por donde el camionero lo ve mejor, y no se quede a su lado.","h2":"En Dakota del Norte, el manual dice que siempre se debe rebasar a un tráiler por el lado izquierdo y por completo, sin quedarse a su lado.","p":"Correcto. Por la izquierda y por completo."},"ref":{"doc":"ND","page":32}},{"id":"nd-180","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, a motorcycle is in your lane and there seems to be room for your car beside it. What should you do?","o":["Drive beside it in the same lane","Give the motorcycle the full lane width; do not share the lane","Honk so it moves over","Pass it inside the same lane"],"h1":"The rider needs the whole lane to move safely.","h2":"In North Dakota, you must allow a motorcycle a full lane width and never share the lane with it, because the rider needs room to move safely.","p":"Right. A motorcycle gets the whole lane."},"es":{"q":"En Dakota del Norte, hay una motocicleta en su carril y parece que hay espacio para su carro a su lado. ¿Qué debe hacer?","o":["Manejar a su lado en el mismo carril","Darle a la motocicleta todo el ancho del carril; no compartir el carril","Tocar la bocina para que se mueva","Rebasarla dentro del mismo carril"],"h1":"El motociclista necesita todo el carril para moverse con seguridad.","h2":"En Dakota del Norte, debe darle a una motocicleta todo el ancho del carril y nunca compartir el carril con ella, porque el motociclista necesita espacio para moverse con seguridad.","p":"Correcto. La motocicleta tiene derecho a todo el carril."},"ref":{"doc":"ND","page":32}},{"id":"nd-181","scope":"ND","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In North Dakota, how much following distance should you leave behind a motorcycle?","o":["One second","Half a second","No extra space is needed","Three or four seconds"],"h1":"Give the rider time to react or stop in an emergency.","h2":"In North Dakota, the handbook says to leave three or four seconds of following distance behind a motorcycle.","p":"Right. Three or four seconds."},"es":{"q":"En Dakota del Norte, ¿cuánta distancia debe dejar detrás de una motocicleta?","o":["Un segundo","Medio segundo","No hace falta espacio extra","Tres o cuatro segundos"],"h1":"Dele al motociclista tiempo para reaccionar o parar en una emergencia.","h2":"En Dakota del Norte, el manual dice que debe dejar tres o cuatro segundos de distancia detrás de una motocicleta.","p":"Correcto. Tres o cuatro segundos."},"ref":{"doc":"ND","page":33}},{"id":"nd-182","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, when may you drive in a marked bicycle lane?","o":["Only to make a right turn, after you signal and look","To pass slow traffic","To park for a moment","Whenever no bicycle is in sight"],"h1":"It has to do with turning at the corner.","h2":"In North Dakota, avoid driving in a bicycle lane except to make a right turn, and signal and look before you move into it.","p":"Right. Only to make a right turn."},"es":{"q":"En Dakota del Norte, ¿cuándo puede manejar en un carril marcado para bicicletas?","o":["Solo para dar vuelta a la derecha, después de señalar y mirar","Para rebasar al tráfico lento","Para estacionarse un momento","Siempre que no se vea ninguna bicicleta"],"h1":"Tiene que ver con dar vuelta en la esquina.","h2":"En Dakota del Norte, evite manejar en un carril para bicicletas excepto para dar vuelta a la derecha, y señale y mire antes de entrar en él.","p":"Correcto. Solo para dar vuelta a la derecha."},"ref":{"doc":"ND","page":33}},{"id":"nd-183","scope":"ND","cat":"licensing","sign":null,"c":2,"en":{"q":"In North Dakota, a motorized bicycle (moped) must have a small engine. How fast may it be able to go on level ground?","o":["No more than 55 mph","No more than 45 mph","No more than 30 mph","Any speed"],"h1":"It is the same as many city speed limits plus a little.","h2":"In North Dakota, a motorized bicycle has an engine of no more than 49.98 cc and cannot go faster than 30 mph on a level surface.","p":"Right. No more than 30 mph."},"es":{"q":"En Dakota del Norte, una bicicleta motorizada (moped) debe tener un motor pequeño. ¿A qué velocidad puede ir, como máximo, en terreno plano?","o":["No más de 55 mph","No más de 45 mph","No más de 30 mph","A cualquier velocidad"],"h1":"Es un poco más que muchos límites de la ciudad.","h2":"En Dakota del Norte, una bicicleta motorizada tiene un motor de no más de 49.98 cc y no puede ir a más de 30 mph en terreno plano.","p":"Correcto. No más de 30 mph."},"ref":{"doc":"ND","page":38}},{"id":"nd-184","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, who must wear an approved safety helmet to ride a motorized bicycle (moped)?","o":["Only riders under 14","No one","Only riders over 65","Riders under 18"],"h1":"The law covers young riders.","h2":"In North Dakota, anyone under 18 must wear an approved safety helmet to ride a motorized bicycle, and the handbook advises a helmet at any age.","p":"Right. Riders under 18 must wear a helmet."},"es":{"q":"En Dakota del Norte, ¿quién debe usar un casco de seguridad aprobado para andar en bicicleta motorizada (moped)?","o":["Solo los menores de 14 años","Nadie","Solo los mayores de 65 años","Los menores de 18 años"],"h1":"La ley cubre a los conductores jóvenes.","h2":"En Dakota del Norte, toda persona menor de 18 años debe usar un casco de seguridad aprobado para andar en bicicleta motorizada, y el manual aconseja usar casco a cualquier edad.","p":"Correcto. Los menores de 18 deben usar casco."},"ref":{"doc":"ND","page":38}},{"id":"nd-185","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, how many bicycle or moped riders may ride side by side?","o":["Any number","Three","No more than two; single file is safest","They must never ride on the road"],"h1":"Single file is safest, but there is a limit.","h2":"In North Dakota, bicycle and motorized bicycle riders may ride no more than two side by side, and single file is safest.","p":"Right. No more than two side by side."},"es":{"q":"En Dakota del Norte, ¿cuántos ciclistas o conductores de moped pueden ir lado a lado?","o":["Cualquier número","Tres","No más de dos; en fila de uno es lo más seguro","Nunca pueden ir por la calle"],"h1":"En fila de uno es lo más seguro, pero hay un límite.","h2":"En Dakota del Norte, los ciclistas y conductores de bicicleta motorizada pueden ir no más de dos lado a lado, y en fila de uno es lo más seguro.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"ND","page":38}},{"id":"nd-186","scope":"ND","cat":"licensing","sign":null,"c":1,"en":{"q":"In North Dakota, what lights and reflectors must a bicycle have at night?","o":["Only a bell","A headlight seen from 500 feet and a red reflector on the rear","Only reflectors on the pedals","A flashing blue light"],"h1":"Others must see it from the front and from behind.","h2":"In North Dakota, a bicycle at night must have a headlight visible from 500 feet and a red reflector on the rear; a taillight, if it has one, must be seen from 500 feet.","p":"Right. A 500-foot headlight and a red rear reflector."},"es":{"q":"En Dakota del Norte, ¿qué luces y reflectores debe tener una bicicleta de noche?","o":["Solo una campana","Un faro que se vea a 500 pies y un reflector rojo atrás","Solo reflectores en los pedales","Una luz azul intermitente"],"h1":"Los demás deben verla de frente y desde atrás.","h2":"En Dakota del Norte, una bicicleta de noche debe tener un faro visible a 500 pies y un reflector rojo atrás; si tiene luz trasera, debe verse a 500 pies.","p":"Correcto. Un faro de 500 pies y un reflector rojo atrás."},"ref":{"doc":"ND","page":38}},{"id":"nd-187","scope":"ND","cat":"licensing","sign":null,"c":0,"en":{"q":"In North Dakota, in general, on which paved highways may a licensed driver operate a registered off-highway vehicle (OHV)?","o":["Paved highways designated and posted at 55 mph or less","Any interstate highway","Any paved highway at any speed","No paved roads at all"],"h1":"The posted speed limit must be low enough.","h2":"In North Dakota, a licensed driver may operate a registered off-highway vehicle on gravel or dirt roads and on paved highways designated and posted at 55 mph or less; a driver over 16 may take a registered class III OHV on paved highways posted up to 65 mph.","p":"Right. Paved highways posted at 55 mph or less."},"es":{"q":"En Dakota del Norte, en general, ¿por qué carreteras pavimentadas puede un conductor con licencia manejar un vehículo todoterreno (OHV) registrado?","o":["Carreteras pavimentadas designadas y con límite de 55 mph o menos","Cualquier carretera interestatal","Cualquier carretera pavimentada a cualquier velocidad","Por ninguna carretera pavimentada"],"h1":"El límite de velocidad marcado debe ser bastante bajo.","h2":"En Dakota del Norte, un conductor con licencia puede manejar un vehículo todoterreno registrado en caminos de grava o tierra y en carreteras pavimentadas designadas y con límite de 55 mph o menos; un conductor mayor de 16 años puede llevar un OHV clase III registrado en carreteras pavimentadas con límite de hasta 65 mph.","p":"Correcto. Carreteras pavimentadas con límite de 55 mph o menos."},"ref":{"doc":"ND","page":39}},{"id":"nd-188","scope":"ND","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In North Dakota, you are on a snowmobile and must cross a road. What must you do?","o":["Speed up and cross at an angle","Ride along the shoulder until you find a gap","Stop before the shoulder, yield to all traffic, and cross at a right angle when it is clear","Cross anywhere on a divided highway"],"h1":"Stop first, then go straight across.","h2":"In North Dakota, a snowmobile must come to a complete stop before reaching the shoulder, yield to all traffic, and cross at right angles to the road when it is clear; on a divided highway, cross only at intersections.","p":"Right. Stop, yield, and cross straight across."},"es":{"q":"En Dakota del Norte, usted va en una motonieve y debe cruzar una carretera. ¿Qué debe hacer?","o":["Acelerar y cruzar en diagonal","Ir por el acotamiento hasta encontrar un espacio","Parar antes del acotamiento, ceder el paso a todo el tráfico y cruzar en ángulo recto cuando esté libre","Cruzar por cualquier parte en una carretera dividida"],"h1":"Pare primero y luego cruce derecho.","h2":"En Dakota del Norte, una motonieve debe parar por completo antes de llegar al acotamiento, ceder el paso a todo el tráfico y cruzar en ángulo recto cuando el camino esté libre; en una carretera dividida, solo puede cruzar en las intersecciones.","p":"Correcto. Pare, ceda el paso y cruce derecho."},"ref":{"doc":"ND","page":39}},{"id":"nd-189","scope":"ND","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In North Dakota, you ride a snowmobile in the ditch beside a road. Which way must you go?","o":["The same direction as the traffic on that side of the road","Against traffic, so you can see cars coming","Any direction","Only on the side nearest the center line"],"h1":"Move with the cars, not against them.","h2":"In North Dakota, a snowmobile in a ditch alongside the road must travel in the same direction as the roadway traffic.","p":"Right. Go the same way as traffic."},"es":{"q":"En Dakota del Norte, usted va en motonieve por la zanja junto a una carretera. ¿En qué dirección debe ir?","o":["En la misma dirección que el tráfico de ese lado de la carretera","Contra el tráfico, para ver los carros que vienen","En cualquier dirección","Solo por el lado más cerca de la línea central"],"h1":"Vaya con los carros, no en contra.","h2":"En Dakota del Norte, una motonieve en la zanja junto a la carretera debe ir en la misma dirección que el tráfico de la carretera.","p":"Correcto. Vaya en la misma dirección que el tráfico."},"ref":{"doc":"ND","page":39}},{"id":"nd-190","scope":"ND","cat":"licensing","sign":null,"c":3,"en":{"q":"In North Dakota, may you ride a snowmobile in the median or ditch of an Interstate highway?","o":["Yes, in the ditch only","Yes, in the median only","Yes, from November to April","No, never; the Interstate right of way includes the median, shoulders and ditches"],"h1":"The whole Interstate right of way is closed to snowmobiles.","h2":"In North Dakota, you may never ride a snowmobile on the right of way of an Interstate highway, which includes the road, the median, the shoulders and the ditches.","p":"Right. Never on the Interstate right of way."},"es":{"q":"En Dakota del Norte, ¿puede andar en motonieve por el camellón central o la zanja de una carretera interestatal?","o":["Sí, solo en la zanja","Sí, solo en el camellón","Sí, de noviembre a abril","No, nunca; el derecho de vía de la interestatal incluye el camellón, los acotamientos y las zanjas"],"h1":"Todo el derecho de vía de la interestatal está cerrado para las motonieves.","h2":"En Dakota del Norte, nunca puede andar en motonieve en el derecho de vía de una carretera interestatal, que incluye el camino, el camellón central, los acotamientos y las zanjas.","p":"Correcto. Nunca en el derecho de vía de la interestatal."},"ref":{"doc":"ND","page":39}},{"id":"nd-191","scope":"ND","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In North Dakota, a person on foot crosses a road where there is no crosswalk. Who has the right of way?","o":["The person on foot","The vehicles on the road","Whoever is faster","The person on foot, only at night"],"h1":"Walkers have the right of way only in crosswalks.","h2":"In North Dakota, a pedestrian crossing where there is no crosswalk must yield the right of way to all vehicles on the road.","p":"Right. Outside a crosswalk, the walker must yield to vehicles."},"es":{"q":"En Dakota del Norte, una persona a pie cruza una calle donde no hay cruce peatonal. ¿Quién tiene el derecho de paso?","o":["La persona a pie","Los vehículos que van por la calle","El que sea más rápido","La persona a pie, solo de noche"],"h1":"Los peatones tienen el derecho de paso solo en los cruces peatonales.","h2":"En Dakota del Norte, un peatón que cruza donde no hay cruce peatonal debe ceder el paso a todos los vehículos de la calle.","p":"Correcto. Fuera del cruce peatonal, el peatón cede el paso a los vehículos."},"ref":{"doc":"ND","page":37}},{"id":"nd-192","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, your windshield wipers stop working in heavy rain. What does the handbook say to do?","o":["Slow down and look out your side window as you leave the road","Keep driving at the same speed","Stop right away in your lane","Turn on your high beams and keep going"],"h1":"You still need to see while you get off the road.","h2":"In North Dakota, if your wipers fail in rain or snow, slow down and put your head out the side window so you can see as you leave the road.","p":"Right. Slow down, look out the side window, and leave the road."},"es":{"q":"En Dakota del Norte, sus limpiaparabrisas dejan de funcionar con mucha lluvia. ¿Qué dice el manual que debe hacer?","o":["Bajar la velocidad y mirar por la ventana lateral mientras sale del camino","Seguir a la misma velocidad","Parar de inmediato en su carril","Prender las luces altas y seguir"],"h1":"Necesita ver mientras sale del camino.","h2":"En Dakota del Norte, si los limpiaparabrisas fallan con lluvia o nieve, baje la velocidad y saque la cabeza por la ventana lateral para poder ver mientras sale del camino.","p":"Correcto. Baje la velocidad, mire por la ventana lateral y salga del camino."},"ref":{"doc":"ND","page":30}},{"id":"nd-193","scope":"ND","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In North Dakota, why should you never turn the ignition to the LOCK position while the car is moving?","o":["The radio will stop","The doors will open","The steering will lock if you try to turn the wheel","The headlights will get brighter"],"h1":"Think about what happens to the steering wheel.","h2":"In North Dakota, never turn the ignition to LOCK while the vehicle is moving, because the steering will lock when you try to turn the wheel.","p":"Right. The steering would lock."},"es":{"q":"En Dakota del Norte, ¿por qué nunca debe poner el encendido en la posición LOCK (bloqueo) mientras el carro está en movimiento?","o":["Se apagará el radio","Se abrirán las puertas","El volante se bloqueará si intenta girarlo","Los faros alumbrarán más"],"h1":"Piense en lo que pasa con el volante.","h2":"En Dakota del Norte, nunca ponga el encendido en LOCK mientras el vehículo está en movimiento, porque el volante se bloqueará cuando intente girarlo.","p":"Correcto. El volante se bloquearía."},"ref":{"doc":"ND","page":30}},{"id":"nd-196","scope":"ND","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In North Dakota, you are towing a trailer, so your vehicle weighs twice as much. What happens to your braking distance?","o":["It doubles","It stays the same","It gets shorter","It becomes ten times as long"],"h1":"More weight means a longer stop, in the same proportion.","h2":"In North Dakota, the handbook says doubling your vehicle's weight will double your braking distance, so a large vehicle or one towing a trailer takes longer to stop.","p":"Right. Twice the weight, twice the braking distance."},"es":{"q":"En Dakota del Norte, usted remolca un tráiler, así que su vehículo pesa el doble. ¿Qué pasa con su distancia de frenado?","o":["Se duplica","Queda igual","Se hace más corta","Se vuelve diez veces más larga"],"h1":"Más peso significa una parada más larga, en la misma proporción.","h2":"En Dakota del Norte, el manual dice que duplicar el peso del vehículo duplica la distancia de frenado, así que un vehículo grande o uno que remolca un tráiler tarda más en parar.","p":"Correcto. El doble de peso, el doble de distancia de frenado."},"ref":{"doc":"ND","page":42}},{"id":"ne-001","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the youngest age to get a learner's permit (LPD)?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It is one year before the provisional permit.","h2":"In Nebraska you can get a learner's permit (LPD) at 15 years old.","p":"Right. The LPD starts at 15."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para obtener el permiso de aprendiz (LPD)?","o":["13 años","14 años","15 años","16 años"],"h1":"Es un año antes del permiso provisional.","h2":"En Nebraska puede obtener un permiso de aprendiz (LPD) a los 15 años.","p":"Correcto. El LPD empieza a los 15."},"zh":{"q":"在 Nebraska，最小几岁可以拿到学习驾照（LPD）？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比临时驾照早一年。","h2":"在 Nebraska，你 15 岁就可以拿到学习驾照（LPD）。","p":"对。LPD 从 15 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit, LPD) là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Đó là một năm trước giấy phép tạm thời (provisional permit).","h2":"Ở Nebraska, bạn có thể có giấy phép tập lái (LPD) khi 15 tuổi.","p":"Đúng. LPD bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para makakuha ng learner's permit (LPD)?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang provisional permit.","h2":"Sa Nebraska, makakakuha ka ng learner's permit (LPD) sa edad na 15.","p":"Tama. Nagsisimula ang LPD sa 15."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit, LPD)؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل التصريح المؤقت (provisional permit) بسنة واحدة.","h2":"في Nebraska يمكنك الحصول على تصريح التعلّم (LPD) في عمر 15 سنة.","p":"صحيح. يبدأ تصريح LPD من عمر 15 سنة."},"ref":{"doc":"NE","page":3}},{"id":"ne-002","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what is the youngest age for a school learner's permit (LPE), used to practice for driving to school?","o":["13 years old","14 years old","15 years old","16 years old"],"h1":"It comes one year before the regular learner's permit.","h2":"In Nebraska a teen can get a school learner's permit (LPE) at 14, so they can practice for driving to school.","p":"Right. The school learner's permit starts at 14."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso escolar de aprendiz (LPE), que sirve para practicar para manejar a la escuela?","o":["13 años","14 años","15 años","16 años"],"h1":"Llega un año antes del permiso de aprendiz normal.","h2":"En Nebraska un adolescente puede obtener el permiso escolar de aprendiz (LPE) a los 14 años, para practicar para manejar a la escuela.","p":"Correcto. El permiso escolar de aprendiz empieza a los 14."},"zh":{"q":"在 Nebraska，用来练习开车上学的学校学习驾照（LPE），最小几岁可以拿？","o":["13 岁","14 岁","15 岁","16 岁"],"h1":"它比普通学习驾照早一年。","h2":"在 Nebraska，青少年 14 岁就可以拿到学校学习驾照（LPE），这样他们可以练习开车上学。","p":"对。学校学习驾照从 14 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép tập lái đi học (school learner's permit, LPE), dùng để tập lái xe đến trường, là bao nhiêu?","o":["13 tuổi","14 tuổi","15 tuổi","16 tuổi"],"h1":"Nó đến một năm trước giấy phép tập lái thông thường.","h2":"Ở Nebraska, thiếu niên có thể có giấy phép tập lái đi học (LPE) khi 14 tuổi, để tập lái xe đến trường.","p":"Đúng. Giấy phép tập lái đi học bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para sa school learner's permit (LPE), na ginagamit para magsanay sa pagmamaneho papunta sa paaralan?","o":["13 taong gulang","14 taong gulang","15 taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang karaniwang learner's permit.","h2":"Sa Nebraska, makakakuha ang isang tinedyer ng school learner's permit (LPE) sa edad na 14, para makapagsanay sa pagmamaneho papunta sa paaralan.","p":"Tama. Nagsisimula ang school learner's permit sa 14."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح التعلّم المدرسي (school learner's permit, LPE)، الذي يُستخدم للتدرّب على القيادة إلى المدرسة؟","o":["13 سنة","14 سنة","15 سنة","16 سنة"],"h1":"إنه قبل تصريح التعلّم العادي بسنة واحدة.","h2":"في Nebraska يمكن للمراهق الحصول على تصريح التعلّم المدرسي (LPE) في عمر 14 سنة، ليتدرّب على القيادة إلى المدرسة.","p":"صحيح. يبدأ تصريح التعلّم المدرسي من عمر 14 سنة."},"ref":{"doc":"NE","page":2}},{"id":"ne-003","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sit in the front passenger seat when a teen drives with a learner's permit (LPD)?","o":["Any passenger with a permit","A licensed driver 18 or older","Any adult, licensed or not","A licensed driver 21 or older"],"h1":"The helper must be an adult who can legally drink.","h2":"A Nebraska LPD holder must always drive with a licensed adult who is at least 21 in the front passenger seat.","p":"Right. A licensed adult 21 or older beside you."},"es":{"q":"En Nebraska, ¿quién debe ir en el asiento delantero del pasajero cuando un adolescente maneja con permiso de aprendiz (LPD)?","o":["Cualquier pasajero con permiso","Un conductor con licencia de 18 años o más","Cualquier adulto, con o sin licencia","Un conductor con licencia de 21 años o más"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Quien tiene un LPD en Nebraska siempre debe manejar con un adulto con licencia de por lo menos 21 años en el asiento delantero del pasajero.","p":"Correcto. Un adulto con licencia de 21 años o más a su lado."},"zh":{"q":"在 Nebraska，青少年持学习驾照（LPD）开车时，谁必须坐在前排乘客座位？","o":["任何有学习驾照的乘客","18 岁或以上、有驾照的司机","任何成年人，有没有驾照都可以","21 岁或以上、有驾照的司机"],"h1":"陪同的人必须是在法律上可以喝酒的成年人。","h2":"Nebraska 持 LPD 的人开车时，前排乘客座位上必须一直有一位至少 21 岁、有驾照的成年人。","p":"对。一位 21 岁或以上、有驾照的成年人坐在你旁边。"},"vi":{"q":"Ở Nebraska, ai phải ngồi ở ghế hành khách phía trước khi thiếu niên lái xe với giấy phép tập lái (LPD)?","o":["Bất kỳ hành khách nào có giấy phép tập lái","Một tài xế có bằng lái, từ 18 tuổi trở lên","Bất kỳ người lớn nào, có bằng lái hay không","Một tài xế có bằng lái, từ 21 tuổi trở lên"],"h1":"Người hướng dẫn phải là người lớn đủ tuổi uống rượu hợp pháp.","h2":"Người có LPD ở Nebraska luôn phải lái xe với một người lớn có bằng lái, ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước.","p":"Đúng. Một người lớn có bằng lái, từ 21 tuổi trở lên, ngồi bên cạnh bạn."},"tl":{"q":"Sa Nebraska, sino ang dapat umupo sa harap na upuan ng pasahero kapag nagmamaneho ang isang tinedyer na may learner's permit (LPD)?","o":["Kahit sinong pasahero na may permit","Isang lisensyadong drayber na 18 taong gulang o higit pa","Kahit sinong adulto, may lisensya man o wala","Isang lisensyadong drayber na 21 taong gulang o higit pa"],"h1":"Ang tumutulong ay dapat adultong legal nang uminom ng alak.","h2":"Ang may hawak ng LPD sa Nebraska ay dapat laging magmaneho kasama ang isang lisensyadong adulto na hindi bababa sa 21 taong gulang sa harap na upuan ng pasahero.","p":"Tama. Isang lisensyadong adulto na 21 o higit pa sa tabi mo."},"ar":{"q":"في Nebraska، من يجب أن يجلس في مقعد الراكب الأمامي عندما يقود مراهق بتصريح التعلّم (LPD)؟","o":["أي راكب معه تصريح","سائق مرخّص عمره 18 سنة أو أكثر","أي شخص بالغ، مرخّص أو غير مرخّص","سائق مرخّص عمره 21 سنة أو أكثر"],"h1":"يجب أن يكون المرافق شخصاً بالغاً يحق له قانونياً شرب الكحول.","h2":"يجب على حامل تصريح LPD في Nebraska أن يقود دائماً مع شخص بالغ مرخّص عمره 21 سنة على الأقل في مقعد الراكب الأمامي.","p":"صحيح. شخص بالغ مرخّص عمره 21 سنة أو أكثر بجانبك."},"ref":{"doc":"NE","page":4}},{"id":"ne-004","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, what is the youngest age for a provisional operator's permit (POP), which lets a teen drive alone?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is the most common age for a first license.","h2":"In Nebraska you must be at least 16 to get a provisional operator's permit (POP).","p":"Right. The POP starts at 16."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para el permiso provisional de operador (POP), que permite manejar solo?","o":["16 años","15 años","17 años","18 años"],"h1":"Es la edad más común para la primera licencia.","h2":"En Nebraska usted debe tener por lo menos 16 años para obtener el permiso provisional de operador (POP).","p":"Correcto. El POP empieza a los 16."},"zh":{"q":"在 Nebraska，可以让青少年单独开车的临时驾照（POP），最小几岁可以拿？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"这是拿第一张驾照最常见的年龄。","h2":"在 Nebraska，你必须至少 16 岁才能拿到临时驾照（POP）。","p":"对。POP 从 16 岁开始。"},"vi":{"q":"Ở Nebraska, tuổi nhỏ nhất để có giấy phép lái xe tạm thời (provisional operator's permit, POP), cho phép thiếu niên lái xe một mình, là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là tuổi phổ biến nhất để có bằng lái đầu tiên.","h2":"Ở Nebraska, bạn phải ít nhất 16 tuổi để có giấy phép lái xe tạm thời (POP).","p":"Đúng. POP bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Nebraska, ano ang pinakabatang edad para sa provisional operator's permit (POP), na nagpapahintulot sa tinedyer na magmaneho nang mag-isa?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ito ang pinakakaraniwang edad para sa unang lisensya.","h2":"Sa Nebraska, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng provisional operator's permit (POP).","p":"Tama. Nagsisimula ang POP sa 16."},"ar":{"q":"في Nebraska، ما أصغر عمر للحصول على تصريح القيادة المؤقت (provisional operator's permit, POP)، الذي يسمح للمراهق بالقيادة وحده؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"إنه العمر الأكثر شيوعاً لأول رخصة.","h2":"في Nebraska يجب أن يكون عمرك 16 سنة على الأقل للحصول على تصريح القيادة المؤقت (POP).","p":"صحيح. يبدأ تصريح POP من عمر 16 سنة."},"ref":{"doc":"NE","page":4}},{"id":"ne-005","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how long must a teen hold a learner's permit before getting a provisional operator's permit (POP)?","o":["3 months","6 months","9 months","12 months"],"h1":"It is half a year.","h2":"A Nebraska teen must hold a learner's permit for at least 6 months before getting a provisional operator's permit.","p":"Right. Six months with the permit."},"es":{"q":"En Nebraska, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes del permiso provisional de operador (POP)?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es medio año.","h2":"Un adolescente en Nebraska debe tener el permiso de aprendiz por lo menos 6 meses antes de obtener el permiso provisional de operador.","p":"Correcto. Seis meses con el permiso."},"zh":{"q":"在 Nebraska，青少年必须持有学习驾照多久，才能拿到临时驾照（POP）？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"是半年。","h2":"Nebraska 的青少年必须持有学习驾照至少 6 个月，才能拿到临时驾照。","p":"对。持有学习驾照六个月。"},"vi":{"q":"Ở Nebraska, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi có giấy phép lái xe tạm thời (POP)?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Nebraska phải giữ giấy phép tập lái ít nhất 6 tháng trước khi có giấy phép lái xe tạm thời.","p":"Đúng. Sáu tháng với giấy phép tập lái."},"tl":{"q":"Sa Nebraska, gaano katagal dapat hawak ng tinedyer ang learner's permit bago makakuha ng provisional operator's permit (POP)?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Kalahating taon ito.","h2":"Ang tinedyer sa Nebraska ay dapat humawak ng learner's permit nang hindi bababa sa 6 na buwan bago makakuha ng provisional operator's permit.","p":"Tama. Anim na buwan na may permit."},"ar":{"q":"في Nebraska، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على تصريح القيادة المؤقت (POP)؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهراً"],"h1":"إنها نصف سنة.","h2":"يجب على المراهق في Nebraska أن يحمل تصريح التعلّم 6 أشهر على الأقل قبل الحصول على تصريح القيادة المؤقت.","p":"صحيح. ستة أشهر مع التصريح."},"ref":{"doc":"NE","page":4}},{"id":"ne-006","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, if a teen does not take an approved driver safety course, how many hours of supervised driving must be logged for a POP?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is the same as a full work week plus ten.","h2":"A Nebraska teen who skips the approved driver safety course must log 50 hours of supervised driving to get a provisional operator's permit.","p":"Right. 50 logged hours."},"es":{"q":"En Nebraska, si un adolescente no toma un curso aprobado de seguridad vial, ¿cuántas horas de manejo supervisado debe registrar para el POP?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es lo mismo que una semana completa de trabajo más diez.","h2":"Un adolescente en Nebraska que no toma el curso aprobado de seguridad vial debe registrar 50 horas de manejo supervisado para obtener el permiso provisional de operador.","p":"Correcto. 50 horas registradas."},"zh":{"q":"在 Nebraska，如果青少年没有上批准的驾驶安全课程，要拿 POP 必须记录多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"它等于一个完整工作周的时间再加十。","h2":"Nebraska 的青少年如果不上批准的驾驶安全课程，必须记录 50 小时有人监督的驾驶，才能拿到临时驾照。","p":"对。记录 50 小时。"},"vi":{"q":"Ở Nebraska, nếu thiếu niên không học khóa an toàn lái xe được chấp thuận, phải ghi lại bao nhiêu giờ lái xe có giám sát để có POP?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Nó bằng một tuần làm việc đầy đủ cộng thêm mười.","h2":"Thiếu niên ở Nebraska không học khóa an toàn lái xe được chấp thuận phải ghi lại 50 giờ lái xe có giám sát để có giấy phép lái xe tạm thời.","p":"Đúng. 50 giờ được ghi lại."},"tl":{"q":"Sa Nebraska, kung hindi kumuha ang tinedyer ng aprubadong kurso sa ligtas na pagmamaneho, ilang oras ng pagmamanehong may gabay ang dapat itala para sa POP?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Kapareho ito ng isang buong linggo ng trabaho at dagdag na sampu.","h2":"Ang tinedyer sa Nebraska na hindi kumuha ng aprubadong kurso sa ligtas na pagmamaneho ay dapat magtala ng 50 oras ng pagmamanehong may gabay para makakuha ng provisional operator's permit.","p":"Tama. 50 oras na naitala."},"ar":{"q":"في Nebraska، إذا لم يأخذ المراهق دورة سلامة قيادة معتمدة، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل للحصول على تصريح POP؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"إنها مثل أسبوع عمل كامل وزيادة عشرة.","h2":"المراهق في Nebraska الذي لا يأخذ دورة سلامة القيادة المعتمدة يجب أن يسجّل 50 ساعة من القيادة تحت الإشراف للحصول على تصريح القيادة المؤقت.","p":"صحيح. 50 ساعة مسجّلة."},"ref":{"doc":"NE","page":4}},{"id":"ne-007","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, who must sign the 50-hour driving log for a provisional operator's permit?","o":["The teen driver","A teacher at school","A DMV examiner","A licensed driver at least 21 years old"],"h1":"It is the same kind of person who supervises practice.","h2":"The Nebraska 50-hour driving form must be signed by a parent, a guardian, or a licensed driver who is at least 21 years old.","p":"Right. A licensed driver 21 or older signs it."},"es":{"q":"En Nebraska, ¿quién debe firmar el registro de 50 horas de manejo para el permiso provisional de operador?","o":["El conductor adolescente","Un maestro de la escuela","Un examinador del DMV","Un conductor con licencia de por lo menos 21 años"],"h1":"Es el mismo tipo de persona que supervisa la práctica.","h2":"El formulario de 50 horas de manejo en Nebraska debe firmarlo uno de los padres, un tutor o un conductor con licencia de por lo menos 21 años.","p":"Correcto. Lo firma un conductor con licencia de 21 años o más."},"zh":{"q":"在 Nebraska，临时驾照的 50 小时驾驶记录必须由谁签名？","o":["青少年司机自己","学校的老师","DMV 考官","至少 21 岁、有驾照的司机"],"h1":"和陪同练习的是同一种人。","h2":"Nebraska 的 50 小时驾驶表必须由父母、监护人，或至少 21 岁、有驾照的司机签名。","p":"对。由 21 岁或以上、有驾照的司机签名。"},"vi":{"q":"Ở Nebraska, ai phải ký sổ ghi 50 giờ lái xe để có giấy phép lái xe tạm thời?","o":["Thiếu niên lái xe","Một giáo viên ở trường","Một giám khảo DMV","Một tài xế có bằng lái, ít nhất 21 tuổi"],"h1":"Đó là cùng loại người giám sát khi tập lái.","h2":"Mẫu ghi 50 giờ lái xe ở Nebraska phải được ký bởi cha mẹ, người giám hộ, hoặc một tài xế có bằng lái ít nhất 21 tuổi.","p":"Đúng. Một tài xế có bằng lái, từ 21 tuổi trở lên, ký tên."},"tl":{"q":"Sa Nebraska, sino ang dapat pumirma sa talaan ng 50 oras ng pagmamaneho para sa provisional operator's permit?","o":["Ang tinedyer na drayber","Isang guro sa paaralan","Isang tagasuri ng DMV","Isang lisensyadong drayber na hindi bababa sa 21 taong gulang"],"h1":"Kaparehong uri ito ng tao na gumagabay sa pagsasanay.","h2":"Ang form ng 50 oras ng pagmamaneho sa Nebraska ay dapat pirmahan ng magulang, tagapag-alaga, o lisensyadong drayber na hindi bababa sa 21 taong gulang.","p":"Tama. Isang lisensyadong drayber na 21 o higit pa ang pipirma."},"ar":{"q":"في Nebraska، من يجب أن يوقّع سجل القيادة لمدة 50 ساعة للحصول على تصريح القيادة المؤقت؟","o":["السائق المراهق","معلّم في المدرسة","فاحص من DMV","سائق مرخّص عمره 21 سنة على الأقل"],"h1":"إنه نفس نوع الشخص الذي يشرف على التدريب.","h2":"يجب أن يوقّع استمارة الـ 50 ساعة من القيادة في Nebraska أحد الوالدين، أو الوصي، أو سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يوقّعها سائق مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"NE","page":4}},{"id":"ne-008","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, during which hours may a POP holder not drive alone, except for work or school activities?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","1 a.m. to 5 a.m."],"h1":"The limit starts exactly at midnight.","h2":"A Nebraska POP holder may not drive alone between midnight and 6 a.m., except to or from work or a school activity.","p":"Right. No solo driving from midnight to 6 a.m."},"es":{"q":"En Nebraska, ¿en qué horario no puede manejar solo quien tiene POP, salvo para el trabajo o actividades escolares?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 1 a.m. a 5 a.m."],"h1":"El límite empieza justo a la medianoche.","h2":"Quien tiene POP en Nebraska no puede manejar solo entre la medianoche y las 6 a.m., salvo para ir o volver del trabajo o de una actividad escolar.","p":"Correcto. No puede manejar solo de medianoche a 6 a.m."},"zh":{"q":"在 Nebraska，除了工作或学校活动，持 POP 的人在哪段时间不能单独开车？","o":["午夜到早上 6 点","晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","凌晨 1 点到早上 5 点"],"h1":"限制正好从午夜开始。","h2":"Nebraska 持 POP 的人在午夜到早上 6 点之间不能单独开车，除非是去或离开工作或学校活动。","p":"对。午夜到早上 6 点不能单独开车。"},"vi":{"q":"Ở Nebraska, trong những giờ nào người có POP không được lái xe một mình, trừ khi đi làm hoặc đi hoạt động ở trường?","o":["Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","1 giờ sáng đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu đúng lúc nửa đêm.","h2":"Người có POP ở Nebraska không được lái xe một mình từ nửa đêm đến 6 giờ sáng, trừ khi đi đến hoặc về từ nơi làm việc hay hoạt động ở trường.","p":"Đúng. Không lái một mình từ nửa đêm đến 6 giờ sáng."},"tl":{"q":"Sa Nebraska, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may hawak ng POP, maliban kung para sa trabaho o gawain sa paaralan?","o":["Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","1 a.m. hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon eksakto sa hatinggabi.","h2":"Ang may hawak ng POP sa Nebraska ay hindi puwedeng magmaneho nang mag-isa mula hatinggabi hanggang 6 a.m., maliban kung papunta o pauwi mula sa trabaho o gawain sa paaralan.","p":"Tama. Bawal magmanehong mag-isa mula hatinggabi hanggang 6 a.m."},"ar":{"q":"في Nebraska، في أي ساعات لا يجوز لحامل تصريح POP أن يقود وحده، إلا للعمل أو لأنشطة المدرسة؟","o":["من منتصف الليل إلى 6 صباحاً","من 10 مساءً إلى 5 صباحاً","من 11 مساءً إلى 6 صباحاً","من 1 صباحاً إلى 5 صباحاً"],"h1":"يبدأ المنع عند منتصف الليل تماماً.","h2":"لا يجوز لحامل تصريح POP في Nebraska أن يقود وحده بين منتصف الليل و6 صباحاً، إلا في الذهاب إلى العمل أو نشاط مدرسي أو العودة منهما.","p":"صحيح. لا قيادة وحدك من منتصف الليل إلى 6 صباحاً."},"ref":{"doc":"NE","page":4}},{"id":"ne-009","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a POP holder wants to drive at 1 a.m. to visit a friend. When is this allowed?","o":["Never","Only on weekends","When a licensed driver 21 or older is in the car","When the friend is under 19"],"h1":"An experienced adult in the car changes the rule.","h2":"A Nebraska POP holder may drive between midnight and 6 a.m. when a licensed driver who is 21 or older rides along.","p":"Right. With a licensed adult 21 or older."},"es":{"q":"En Nebraska, quien tiene POP quiere manejar a la 1 a.m. para visitar a un amigo. ¿Cuándo está permitido?","o":["Nunca","Solo los fines de semana","Cuando va en el carro un conductor con licencia de 21 años o más","Cuando el amigo es menor de 19 años"],"h1":"Un adulto con experiencia en el carro cambia la regla.","h2":"Quien tiene POP en Nebraska puede manejar entre la medianoche y las 6 a.m. cuando lo acompaña un conductor con licencia de 21 años o más.","p":"Correcto. Con un adulto con licencia de 21 años o más."},"zh":{"q":"在 Nebraska，持 POP 的人想在凌晨 1 点开车去看朋友。什么情况下可以？","o":["永远不可以","只在周末","车里有 21 岁或以上、有驾照的司机时","朋友未满 19 岁时"],"h1":"车里有一位有经验的成年人，规定就不同了。","h2":"Nebraska 持 POP 的人在有 21 岁或以上、有驾照的司机同车时，可以在午夜到早上 6 点之间开车。","p":"对。有 21 岁或以上、有驾照的成年人同车就可以。"},"vi":{"q":"Ở Nebraska, một người có POP muốn lái xe lúc 1 giờ sáng để thăm bạn. Khi nào điều này được phép?","o":["Không bao giờ","Chỉ vào cuối tuần","Khi có một tài xế có bằng lái, từ 21 tuổi trở lên, trong xe","Khi người bạn dưới 19 tuổi"],"h1":"Một người lớn có kinh nghiệm trong xe làm thay đổi quy định.","h2":"Người có POP ở Nebraska được lái xe từ nửa đêm đến 6 giờ sáng khi có một tài xế có bằng lái, từ 21 tuổi trở lên, đi cùng.","p":"Đúng. Với một người lớn có bằng lái, từ 21 tuổi trở lên."},"tl":{"q":"Sa Nebraska, gustong magmaneho ng may hawak ng POP nang 1 a.m. para bisitahin ang isang kaibigan. Kailan ito pinapayagan?","o":["Hindi kailanman","Tuwing weekend lang","Kapag may lisensyadong drayber na 21 o higit pa sa sasakyan","Kapag ang kaibigan ay wala pang 19"],"h1":"Nagbabago ang patakaran kapag may bihasang adulto sa sasakyan.","h2":"Ang may hawak ng POP sa Nebraska ay puwedeng magmaneho mula hatinggabi hanggang 6 a.m. kapag may kasamang lisensyadong drayber na 21 taong gulang o higit pa.","p":"Tama. Kasama ang lisensyadong adulto na 21 o higit pa."},"ar":{"q":"في Nebraska، يريد حامل تصريح POP أن يقود في الساعة 1 صباحاً لزيارة صديق. متى يُسمح بذلك؟","o":["أبداً","في عطلة نهاية الأسبوع فقط","عندما يكون في السيارة سائق مرخّص عمره 21 سنة أو أكثر","عندما يكون عمر الصديق أقل من 19 سنة"],"h1":"وجود شخص بالغ ذي خبرة في السيارة يغيّر القاعدة.","h2":"يجوز لحامل تصريح POP في Nebraska أن يقود بين منتصف الليل و6 صباحاً عندما يرافقه سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. مع شخص بالغ مرخّص عمره 21 سنة أو أكثر."},"ref":{"doc":"NE","page":4}},{"id":"ne-010","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, during the first 6 months with a POP, how many passengers under 19 who are not family may ride along?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit is very small.","h2":"During the first 6 months with a POP, a Nebraska teen may carry no more than one passenger under 19 who is not immediate family.","p":"Right. Only one non-family passenger under 19."},"es":{"q":"En Nebraska, durante los primeros 6 meses con POP, ¿cuántos pasajeros menores de 19 años que no son familiares pueden ir con usted?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite es muy pequeño.","h2":"Durante los primeros 6 meses con POP, un adolescente en Nebraska puede llevar no más de un pasajero menor de 19 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 19 que no es familiar."},"zh":{"q":"在 Nebraska，持 POP 的前 6 个月，可以有多少位不是家人、19 岁以下的乘客同车？","o":["一个都不行","最多一位","最多两位","最多三位"],"h1":"这个限制很小。","h2":"持 POP 的前 6 个月，Nebraska 的青少年最多只能载一位不是直系家人、19 岁以下的乘客。","p":"对。只能载一位不是家人、19 岁以下的乘客。"},"vi":{"q":"Ở Nebraska, trong 6 tháng đầu với POP, được chở bao nhiêu hành khách dưới 19 tuổi không phải người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Giới hạn rất nhỏ.","h2":"Trong 6 tháng đầu với POP, thiếu niên ở Nebraska được chở không quá một hành khách dưới 19 tuổi không phải người trong gia đình trực hệ.","p":"Đúng. Chỉ một hành khách dưới 19 tuổi không phải người nhà."},"tl":{"q":"Sa Nebraska, sa unang 6 na buwan na may POP, ilang pasaherong wala pang 19 na hindi kapamilya ang puwedeng isakay?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Napakaliit ng limitasyon.","h2":"Sa unang 6 na buwan na may POP, ang tinedyer sa Nebraska ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 19 na hindi malapit na kapamilya.","p":"Tama. Isa lang na hindi kapamilyang pasahero na wala pang 19."},"ar":{"q":"في Nebraska، خلال أول 6 أشهر مع تصريح POP، كم راكباً عمره أقل من 19 سنة وليس من العائلة يمكن أن يركب معك؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة"],"h1":"الحد صغير جداً.","h2":"خلال أول 6 أشهر مع تصريح POP، يجوز للمراهق في Nebraska أن يحمل راكباً واحداً فقط على الأكثر عمره أقل من 19 سنة وليس من أفراد العائلة المباشرين.","p":"صحيح. راكب واحد فقط من خارج العائلة عمره أقل من 19 سنة."},"ref":{"doc":"NE","page":4}},{"id":"ne-011","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, may a POP holder talk or text on a wireless phone while driving?","o":["Yes, if hands-free","Yes, for calls only","Yes, at stop signs","No, interactive wireless devices are not allowed"],"h1":"The POP has a stricter rule than for adults.","h2":"A Nebraska POP holder may not use an interactive wireless device, such as a phone, while driving.","p":"Right. No phones for POP drivers."},"es":{"q":"En Nebraska, ¿puede quien tiene POP hablar o escribir mensajes en un teléfono inalámbrico mientras maneja?","o":["Sí, con manos libres","Sí, solo para llamadas","Sí, en las señales de alto","No, no se permiten aparatos inalámbricos interactivos"],"h1":"El POP tiene una regla más estricta que la de los adultos.","h2":"Quien tiene POP en Nebraska no puede usar un aparato inalámbrico interactivo, como un teléfono, mientras maneja.","p":"Correcto. Nada de teléfonos para conductores con POP."},"zh":{"q":"在 Nebraska，持 POP 的人开车时可以用无线电话通话或发短信吗？","o":["可以，如果是免提","可以，只能打电话","可以，在停车标志前","不可以，不能使用互动式无线设备"],"h1":"POP 的规定比成年人更严格。","h2":"Nebraska 持 POP 的人开车时不能使用互动式无线设备，比如手机。","p":"对。持 POP 的司机不能用手机。"},"vi":{"q":"Ở Nebraska, người có POP có được nói chuyện hoặc nhắn tin bằng điện thoại không dây khi lái xe không?","o":["Có, nếu dùng rảnh tay","Có, chỉ để gọi điện","Có, khi dừng ở biển dừng","Không, không được dùng thiết bị không dây tương tác"],"h1":"POP có quy định nghiêm hơn so với người lớn.","h2":"Người có POP ở Nebraska không được dùng thiết bị không dây tương tác, như điện thoại, khi lái xe.","p":"Đúng. Tài xế có POP không được dùng điện thoại."},"tl":{"q":"Sa Nebraska, puwede bang tumawag o mag-text sa wireless na telepono ang may hawak ng POP habang nagmamaneho?","o":["Oo, kung hands-free","Oo, para sa tawag lang","Oo, sa mga stop sign","Hindi, bawal ang interactive na wireless device"],"h1":"Mas mahigpit ang patakaran sa POP kaysa sa mga adulto.","h2":"Ang may hawak ng POP sa Nebraska ay hindi puwedeng gumamit ng interactive na wireless device, tulad ng telepono, habang nagmamaneho.","p":"Tama. Bawal ang telepono sa mga drayber na may POP."},"ar":{"q":"في Nebraska، هل يجوز لحامل تصريح POP أن يتكلم أو يرسل رسائل نصية على هاتف لاسلكي أثناء القيادة؟","o":["نعم، إذا كان بدون استخدام اليدين","نعم، للمكالمات فقط","نعم، عند علامات التوقف","لا، الأجهزة اللاسلكية التفاعلية غير مسموح بها"],"h1":"لتصريح POP قاعدة أشد من قاعدة البالغين.","h2":"لا يجوز لحامل تصريح POP في Nebraska أن يستخدم جهازاً لاسلكياً تفاعلياً، مثل الهاتف، أثناء القيادة.","p":"صحيح. لا هواتف لسائقي POP."},"ref":{"doc":"NE","page":1}},{"id":"ne-012","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, when can a POP holder move up to a full operator's license?","o":["At 16, after 3 months","At 16 and a half, after 6 months","At 17, after holding the POP for 12 months","At 18 only"],"h1":"It takes a full year on the POP.","h2":"A Nebraska POP holder can get a full operator's license at 17, after holding the POP for 12 months with a good record.","p":"Right. Age 17 and 12 months on the POP."},"es":{"q":"En Nebraska, ¿cuándo puede quien tiene POP pasar a la licencia de operador completa?","o":["A los 16, después de 3 meses","A los 16 y medio, después de 6 meses","A los 17, después de tener el POP 12 meses","Solo a los 18"],"h1":"Se necesita un año completo con el POP.","h2":"Quien tiene POP en Nebraska puede obtener la licencia de operador completa a los 17 años, después de tener el POP 12 meses con buen historial.","p":"Correcto. A los 17 y 12 meses con el POP."},"zh":{"q":"在 Nebraska，持 POP 的人什么时候可以升到正式驾照（full operator's license）？","o":["16 岁，持有 3 个月以后","16 岁半，持有 6 个月以后","17 岁，持有 POP 12 个月以后","只能在 18 岁"],"h1":"需要持有 POP 整整一年。","h2":"Nebraska 持 POP 的人在 17 岁、持有 POP 12 个月并且记录良好以后，可以拿到正式驾照。","p":"对。17 岁，并持有 POP 12 个月。"},"vi":{"q":"Ở Nebraska, khi nào người có POP được lên bằng lái đầy đủ (operator's license)?","o":["Khi 16 tuổi, sau 3 tháng","Khi 16 tuổi rưỡi, sau 6 tháng","Khi 17 tuổi, sau khi giữ POP 12 tháng","Chỉ khi 18 tuổi"],"h1":"Cần giữ POP trọn một năm.","h2":"Người có POP ở Nebraska có thể có bằng lái đầy đủ khi 17 tuổi, sau khi giữ POP 12 tháng với hồ sơ lái xe tốt.","p":"Đúng. 17 tuổi và 12 tháng với POP."},"tl":{"q":"Sa Nebraska, kailan puwedeng umakyat sa buong operator's license ang may hawak ng POP?","o":["Sa 16, pagkalipas ng 3 buwan","Sa 16 at kalahati, pagkalipas ng 6 na buwan","Sa 17, pagkatapos hawakan ang POP nang 12 buwan","Sa 18 lang"],"h1":"Kailangan ng isang buong taon sa POP.","h2":"Ang may hawak ng POP sa Nebraska ay makakakuha ng buong operator's license sa edad na 17, pagkatapos hawakan ang POP nang 12 buwan na may magandang rekord.","p":"Tama. Edad 17 at 12 buwan sa POP."},"ar":{"q":"في Nebraska، متى يمكن لحامل تصريح POP أن ينتقل إلى رخصة القيادة الكاملة (operator's license)؟","o":["في عمر 16، بعد 3 أشهر","في عمر 16 ونصف، بعد 6 أشهر","في عمر 17، بعد حمل تصريح POP لمدة 12 شهراً","في عمر 18 فقط"],"h1":"يحتاج سنة كاملة مع تصريح POP.","h2":"يمكن لحامل تصريح POP في Nebraska الحصول على رخصة القيادة الكاملة في عمر 17، بعد حمل تصريح POP لمدة 12 شهراً مع سجل جيد.","p":"صحيح. عمر 17 و12 شهراً مع تصريح POP."},"ref":{"doc":"NE","page":5}},{"id":"ne-013","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, what blood alcohol level is illegal for a driver under 21?","o":["0.02 or more","0.08 or more","0.05 or more","0.10 or more"],"h1":"It is much lower than the adult limit.","h2":"In Nebraska it is against the law for a driver under 21 to drive with a blood alcohol level of 0.02 or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Nebraska, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.02 o más","0.08 o más","0.05 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nebraska es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Nebraska，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.02 或更高","0.08 或更高","0.05 或更高","0.10 或更高"],"h1":"它比成年人的限值低很多。","h2":"在 Nebraska，21 岁以下的司机血液酒精浓度达到 0.02 或更高时开车是违法的。","p":"对。21 岁以下，限值是 0.02。"},"vi":{"q":"Ở Nebraska, nồng độ cồn trong máu bao nhiêu là phạm luật đối với tài xế dưới 21 tuổi?","o":["0.02 trở lên","0.08 trở lên","0.05 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Nebraska, tài xế dưới 21 tuổi lái xe với nồng độ cồn trong máu từ 0.02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Nebraska, anong antas ng alak sa dugo ang ilegal para sa drayber na wala pang 21?","o":["0.02 o higit pa","0.08 o higit pa","0.05 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa Nebraska, labag sa batas para sa drayber na wala pang 21 ang magmaneho na may antas ng alak sa dugo na 0.02 o higit pa.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Nebraska، ما نسبة الكحول في الدم غير القانونية للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 أو أكثر","0.08 أو أكثر","0.05 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في Nebraska من المخالف للقانون أن يقود سائق عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. تحت 21 سنة، الحد هو 0.02."},"ref":{"doc":"NE","page":24}},{"id":"ne-014","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, may a driver read or send a text on a handheld phone while the car is moving?","o":["Yes, on rural roads","No, it is against the law","Yes, below 30 mph","Yes, at night"],"h1":"Texting takes your eyes off the road.","h2":"No. In Nebraska it is against the law to read, type, or send a text on a handheld phone while driving.","p":"Right. No texting while you drive."},"es":{"q":"En Nebraska, ¿puede un conductor leer o enviar un mensaje de texto en un teléfono en la mano mientras el carro está en movimiento?","o":["Sí, en caminos rurales","No, es ilegal","Sí, a menos de 30 mph","Sí, de noche"],"h1":"Escribir mensajes le quita la vista del camino.","h2":"No. En Nebraska es ilegal leer, escribir o enviar un mensaje de texto en un teléfono en la mano mientras maneja.","p":"Correcto. Nada de mensajes mientras maneja."},"zh":{"q":"在 Nebraska，车在开动时，司机可以用手拿的手机看短信或发短信吗？","o":["可以，在乡村道路上","不可以，这是违法的","可以，在 30 英里/小时以下时","可以，在晚上"],"h1":"发短信会让你的眼睛离开道路。","h2":"不可以。在 Nebraska，开车时用手拿的手机看短信、打短信或发短信是违法的。","p":"对。开车时不能发短信。"},"vi":{"q":"Ở Nebraska, tài xế có được đọc hoặc gửi tin nhắn trên điện thoại cầm tay khi xe đang chạy không?","o":["Có, trên đường nông thôn","Không, điều đó là phạm luật","Có, dưới 30 mph","Có, vào ban đêm"],"h1":"Nhắn tin làm mắt bạn rời khỏi đường.","h2":"Không. Ở Nebraska, đọc, gõ hoặc gửi tin nhắn trên điện thoại cầm tay khi lái xe là phạm luật.","p":"Đúng. Không nhắn tin khi lái xe."},"tl":{"q":"Sa Nebraska, puwede bang magbasa o magpadala ng text sa hawak na telepono ang drayber habang umaandar ang sasakyan?","o":["Oo, sa mga daan sa probinsya","Hindi, labag ito sa batas","Oo, kapag mas mabagal sa 30 mph","Oo, sa gabi"],"h1":"Inaalis ng pag-text ang mata mo sa daan.","h2":"Hindi. Sa Nebraska, labag sa batas ang magbasa, mag-type, o magpadala ng text sa hawak na telepono habang nagmamaneho.","p":"Tama. Bawal mag-text habang nagmamaneho."},"ar":{"q":"في Nebraska، هل يجوز للسائق أن يقرأ أو يرسل رسالة نصية على هاتف محمول باليد أثناء سير السيارة؟","o":["نعم، على الطرق الريفية","لا، هذا مخالف للقانون","نعم، تحت 30 mph","نعم، في الليل"],"h1":"كتابة الرسائل تُبعد عينيك عن الطريق.","h2":"لا. في Nebraska من المخالف للقانون أن تقرأ أو تكتب أو ترسل رسالة نصية على هاتف محمول باليد أثناء القيادة.","p":"صحيح. لا رسائل نصية أثناء القيادة."},"ref":{"doc":"NE","page":65}},{"id":"ne-015","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, on an interstate, you come up to a stopped car on the shoulder with people near it. What must you do?","o":["Nothing; the law covers only police cars","Stop next to it","Honk to warn the people","Move one lane over, or slow down if you cannot"],"h1":"Give the people on the shoulder more room.","h2":"On a Nebraska interstate, you must move one lane away from a stopped vehicle with people in or near it, or slow down if you cannot move over.","p":"Right. Move over, or slow down."},"es":{"q":"En Nebraska, en una interestatal, usted se acerca a un carro detenido en el acotamiento con personas cerca. ¿Qué debe hacer?","o":["Nada; la ley solo aplica a patrullas","Detenerse junto a él","Tocar la bocina para avisar","Pasarse un carril, o bajar la velocidad si no puede"],"h1":"Deles más espacio a las personas en el acotamiento.","h2":"En una interestatal de Nebraska, usted debe pasarse a un carril más lejos de un vehículo detenido con personas dentro o cerca, o bajar la velocidad si no puede cambiarse.","p":"Correcto. Cambiar de carril, o bajar la velocidad."},"zh":{"q":"在 Nebraska，在州际公路上，你遇到一辆停在路肩上的车，旁边有人。你必须怎么做？","o":["什么都不用做；法律只包括警车","在它旁边停车","按喇叭提醒那些人","换开一条车道，不能换就减速"],"h1":"给路肩上的人更多空间。","h2":"在 Nebraska 的州际公路上，你必须离开一辆车里或旁边有人、停着的车一条车道；如果不能换道，就要减速。","p":"对。让出车道，或者减速。"},"vi":{"q":"Ở Nebraska, trên xa lộ liên bang (interstate), bạn đến gần một xe đang dừng ở lề đường có người ở gần. Bạn phải làm gì?","o":["Không làm gì; luật chỉ áp dụng cho xe cảnh sát","Dừng lại bên cạnh xe đó","Bấm còi để cảnh báo mọi người","Chuyển sang một làn khác, hoặc giảm tốc độ nếu không chuyển được"],"h1":"Hãy chừa thêm chỗ cho những người ở lề đường.","h2":"Trên xa lộ liên bang ở Nebraska, bạn phải chuyển sang một làn cách xa xe đang dừng có người ở trong hoặc ở gần, hoặc giảm tốc độ nếu không thể chuyển làn.","p":"Đúng. Chuyển làn, hoặc giảm tốc độ."},"tl":{"q":"Sa Nebraska, sa isang interstate, papalapit ka sa nakahintong sasakyan sa gilid ng daan (shoulder) na may mga tao sa malapit. Ano ang dapat mong gawin?","o":["Wala; para lang sa sasakyan ng pulis ang batas","Huminto sa tabi nito","Bumusina para balaan ang mga tao","Lumipat ng isang lane, o bumagal kung hindi ka makalipat"],"h1":"Bigyan ng mas maraming espasyo ang mga tao sa gilid ng daan.","h2":"Sa isang interstate sa Nebraska, dapat kang lumipat ng isang lane palayo sa nakahintong sasakyan na may mga tao sa loob o malapit dito, o bumagal kung hindi ka makalipat.","p":"Tama. Lumipat ng lane, o bumagal."},"ar":{"q":"في Nebraska، على طريق سريع بين الولايات (interstate)، تقترب من سيارة متوقفة على كتف الطريق وبقربها أشخاص. ماذا يجب أن تفعل؟","o":["لا شيء؛ القانون يشمل سيارات الشرطة فقط","توقّف بجانبها","استخدم البوق لتحذير الناس","انتقل حارة واحدة بعيداً، أو خفّف السرعة إذا لم تستطع"],"h1":"أعطِ الناس على كتف الطريق مساحة أكبر.","h2":"على طريق interstate في Nebraska، يجب أن تنتقل حارة واحدة بعيداً عن مركبة متوقفة فيها أو بقربها أشخاص، أو أن تخفّف السرعة إذا لم تستطع الانتقال.","p":"صحيح. انتقل إلى حارة أخرى، أو خفّف السرعة."},"ref":{"doc":"NE","page":null}},{"id":"ne-016","scope":"NE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nebraska, on a road divided by a median, a school bus stops with its red lights flashing and stop arm out. Who must stop?","o":["Every vehicle, from both directions","Only traffic coming toward the bus","Only traffic going the same direction as the bus","No one, if no child is crossing"],"h1":"The median separates the two sides of the road.","h2":"On a Nebraska road divided by a median, only traffic going the same direction as the school bus must stop.","p":"Right. Only the same direction stops."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, un autobús escolar se detiene con las luces rojas encendidas y el brazo de alto extendido. ¿Quién debe detenerse?","o":["Todos los vehículos, de los dos sentidos","Solo el tráfico que viene hacia el autobús","Solo el tráfico que va en el mismo sentido que el autobús","Nadie, si ningún niño está cruzando"],"h1":"El camellón separa los dos lados del camino.","h2":"En un camino de Nebraska dividido por un camellón, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. Solo se detiene el mismo sentido."},"zh":{"q":"在 Nebraska，在有中央隔离带分隔的路上，一辆校车停下来，闪着红灯并伸出停车臂。谁必须停车？","o":["两个方向的每一辆车","只有朝校车开过来的车","只有和校车同方向的车","没有人，如果没有孩子在过马路"],"h1":"中央隔离带把路的两边分开。","h2":"在 Nebraska 有中央隔离带分隔的路上，只有和校车同方向的车必须停车。","p":"对。只有同方向的车要停。"},"vi":{"q":"Ở Nebraska, trên đường có dải phân cách ở giữa, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy và cần báo dừng (stop arm) mở ra. Ai phải dừng?","o":["Mọi xe, từ cả hai chiều","Chỉ xe đi ngược chiều về phía xe buýt","Chỉ xe đi cùng chiều với xe buýt","Không ai, nếu không có trẻ em băng qua đường"],"h1":"Dải phân cách chia hai bên đường ra.","h2":"Trên đường có dải phân cách ở Nebraska, chỉ xe đi cùng chiều với xe buýt trường học phải dừng.","p":"Đúng. Chỉ xe cùng chiều phải dừng."},"tl":{"q":"Sa Nebraska, sa daang hinahati ng median, huminto ang school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm. Sino ang dapat huminto?","o":["Lahat ng sasakyan, mula sa dalawang direksyon","Ang mga sasakyang paparating lang sa bus","Ang mga sasakyang kapareho lang ng direksyon ng bus","Wala, kung walang batang tumatawid"],"h1":"Pinaghihiwalay ng median ang dalawang panig ng daan.","h2":"Sa daang hinahati ng median sa Nebraska, ang mga sasakyang kapareho lang ng direksyon ng school bus ang dapat huminto.","p":"Tama. Ang kaparehong direksyon lang ang hihinto."},"ar":{"q":"في Nebraska، على طريق مقسوم بجزيرة وسطية (median)، تتوقف حافلة مدرسية وأضواؤها الحمراء تومض وذراع التوقف (stop arm) ممدودة. من يجب أن يتوقف؟","o":["كل المركبات، من الاتجاهين","المركبات القادمة نحو الحافلة فقط","المركبات التي تسير في نفس اتجاه الحافلة فقط","لا أحد، إذا لم يكن هناك طفل يعبر"],"h1":"الجزيرة الوسطية تفصل بين جانبي الطريق.","h2":"على طريق في Nebraska مقسوم بجزيرة وسطية، يجب أن تتوقف فقط المركبات التي تسير في نفس اتجاه الحافلة المدرسية.","p":"صحيح. يتوقف نفس الاتجاه فقط."},"ref":{"doc":"NE","page":70}},{"id":"ne-017","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the usual posted speed limit on most rural interstates?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"It is higher than in many eastern states.","h2":"The speed limit on most rural interstates in Nebraska is 75 mph; city stretches are lower.","p":"Right. 75 mph on most rural interstates."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad usual en la mayoría de las interestatales rurales?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Es más alto que en muchos estados del este.","h2":"El límite de velocidad en la mayoría de las interestatales rurales de Nebraska es de 75 millas por hora; los tramos en la ciudad son más bajos.","p":"Correcto. 75 mph en la mayoría de las interestatales rurales."},"zh":{"q":"在 Nebraska，大多数乡村州际公路通常标出的限速是多少？","o":["75 英里/小时","65 英里/小时","70 英里/小时","80 英里/小时"],"h1":"它比很多东部的州高。","h2":"Nebraska 大多数乡村州际公路的限速是 75 英里/小时；城市路段更低。","p":"对。大多数乡村州际公路限速 75 英里/小时。"},"vi":{"q":"Ở Nebraska, tốc độ tối đa thường được ghi trên hầu hết xa lộ liên bang ở vùng nông thôn là bao nhiêu?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Nó cao hơn ở nhiều bang miền đông.","h2":"Tốc độ tối đa trên hầu hết xa lộ liên bang ở vùng nông thôn của Nebraska là 75 mph; các đoạn trong thành phố thấp hơn.","p":"Đúng. 75 mph trên hầu hết xa lộ liên bang ở vùng nông thôn."},"tl":{"q":"Sa Nebraska, ano ang karaniwang nakapaskil na speed limit sa karamihan ng interstate sa probinsya?","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"Mas mataas ito kaysa sa maraming estado sa silangan.","h2":"Ang speed limit sa karamihan ng interstate sa probinsya sa Nebraska ay 75 mph; mas mababa sa mga bahaging nasa lungsod.","p":"Tama. 75 mph sa karamihan ng interstate sa probinsya."},"ar":{"q":"في Nebraska، ما حد السرعة المعتاد المكتوب على معظم الطرق السريعة بين الولايات في المناطق الريفية؟","o":["75 mph","65 mph","70 mph","80 mph"],"h1":"إنه أعلى منه في كثير من الولايات الشرقية.","h2":"حد السرعة على معظم الطرق السريعة بين الولايات في المناطق الريفية في Nebraska هو 75 mph؛ وهو أقل في أجزائها داخل المدن.","p":"صحيح. 75 mph على معظم الطرق السريعة الريفية بين الولايات."},"ref":{"doc":"NE","page":52}},{"id":"ne-018","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, can police stop an adult driver only for not wearing a seat belt?","o":["Yes, it is a primary offense","Yes, but only at night","Yes, but only on interstates","No, it is a secondary law"],"h1":"The ticket comes only with another violation.","h2":"Nebraska's adult seat belt law is secondary, so a driver gets a seat belt ticket only when stopped for another violation. You should still always buckle up.","p":"Right. For adults it is a secondary law, but buckle up anyway."},"es":{"q":"En Nebraska, ¿puede la policía detener a un conductor adulto solo por no usar el cinturón de seguridad?","o":["Sí, es una infracción primaria","Sí, pero solo de noche","Sí, pero solo en interestatales","No, es una ley secundaria"],"h1":"La multa llega solo junto con otra infracción.","h2":"La ley de cinturón de seguridad para adultos en Nebraska es secundaria, así que el conductor recibe esa multa solo cuando lo detienen por otra infracción. Aun así, abróchese siempre.","p":"Correcto. Para adultos es una ley secundaria, pero abróchese de todos modos."},"zh":{"q":"在 Nebraska，警察可以只因为成年司机没系安全带就让他停车吗？","o":["可以，这是主要违规","可以，但只在晚上","可以，但只在州际公路上","不可以，这是次要执法的法律"],"h1":"只有在有其他违规时，才会开这张罚单。","h2":"Nebraska 的成年人安全带法是次要执法，所以司机只有在因为其他违规被拦下时，才会收到安全带罚单。你还是应该一直系好安全带。","p":"对。对成年人来说这是次要执法的法律，但还是要系好安全带。"},"vi":{"q":"Ở Nebraska, cảnh sát có thể chặn một tài xế người lớn chỉ vì không thắt dây an toàn không?","o":["Có, đó là vi phạm chính (primary offense)","Có, nhưng chỉ vào ban đêm","Có, nhưng chỉ trên xa lộ liên bang","Không, đó là luật phụ (secondary law)"],"h1":"Vé phạt chỉ đi kèm với một vi phạm khác.","h2":"Luật dây an toàn cho người lớn ở Nebraska là luật phụ, nên tài xế chỉ bị phạt về dây an toàn khi bị chặn vì một vi phạm khác. Bạn vẫn nên luôn thắt dây an toàn.","p":"Đúng. Với người lớn đó là luật phụ, nhưng hãy luôn thắt dây an toàn."},"tl":{"q":"Sa Nebraska, puwede bang patigilin ng pulis ang adultong drayber dahil lang hindi siya naka-seat belt?","o":["Oo, ito ay primary offense","Oo, pero sa gabi lang","Oo, pero sa interstate lang","Hindi, ito ay secondary law"],"h1":"Darating lang ang tiket kasama ng ibang paglabag.","h2":"Secondary ang batas sa seat belt para sa adulto sa Nebraska, kaya natitiketan lang ang drayber sa seat belt kapag pinatigil siya dahil sa ibang paglabag. Dapat ka pa ring laging mag-seat belt.","p":"Tama. Para sa adulto, secondary law ito, pero mag-seat belt pa rin."},"ar":{"q":"في Nebraska، هل يمكن للشرطة إيقاف سائق بالغ فقط لأنه لا يضع حزام الأمان؟","o":["نعم، إنها مخالفة أساسية (primary offense)","نعم، ولكن في الليل فقط","نعم، ولكن على الطرق السريعة بين الولايات فقط","لا، إنه قانون ثانوي (secondary law)"],"h1":"المخالفة تأتي فقط مع مخالفة أخرى.","h2":"قانون حزام الأمان للبالغين في Nebraska قانون ثانوي، لذلك يحصل السائق على مخالفة حزام الأمان فقط عندما يُوقَف بسبب مخالفة أخرى. ومع ذلك يجب أن تضع حزام الأمان دائماً.","p":"صحيح. للبالغين هو قانون ثانوي، لكن ضع الحزام على أي حال."},"ref":{"doc":"NE","page":26}},{"id":"ne-019","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, on a road divided by a median, you meet a stopped school bus on the other side. What must you do?","o":["You do not have to stop, but watch for children","Stop until the bus moves","Stop only if children are near the bus","Pull onto the shoulder"],"h1":"The median separates you from the bus.","h2":"On a Nebraska road divided by a median, traffic coming from the opposite direction does not have to stop for a stopped school bus, but should watch for children.","p":"Right. Oncoming traffic on a divided highway may pass with care."},"es":{"q":"En Nebraska, en un camino dividido por un camellón, usted se encuentra con un autobús escolar detenido del otro lado. ¿Qué debe hacer?","o":["No tiene que detenerse, pero esté atento a los niños","Detenerse hasta que el autobús avance","Detenerse solo si hay niños cerca del autobús","Orillarse al acotamiento"],"h1":"El camellón lo separa del autobús.","h2":"En un camino de Nebraska dividido por un camellón, el tráfico que viene en sentido contrario no tiene que detenerse por un autobús escolar detenido, pero debe estar atento a los niños.","p":"Correcto. En una carretera dividida, el tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 Nebraska，在有中央隔离带分隔的路上，你遇到另一边停着的校车。你必须怎么做？","o":["你不必停车，但要注意孩子","停车，直到校车开走","只有孩子在校车附近时才停车","开到路肩上"],"h1":"中央隔离带把你和校车分开。","h2":"在 Nebraska 有中央隔离带分隔的路上，从对面方向开来的车不必为停着的校车停车，但应该注意孩子。","p":"对。在分隔公路上，对面的车可以小心地开过去。"},"vi":{"q":"Ở Nebraska, trên đường có dải phân cách ở giữa, bạn gặp một xe buýt trường học đang dừng ở phía bên kia. Bạn phải làm gì?","o":["Bạn không phải dừng, nhưng hãy chú ý trẻ em","Dừng lại cho đến khi xe buýt chạy","Chỉ dừng nếu có trẻ em gần xe buýt","Tấp vào lề đường"],"h1":"Dải phân cách ngăn cách bạn với xe buýt.","h2":"Trên đường có dải phân cách ở Nebraska, xe đi ngược chiều không phải dừng khi xe buýt trường học dừng, nhưng phải chú ý trẻ em.","p":"Đúng. Xe đi ngược chiều trên đường có dải phân cách có thể đi qua một cách cẩn thận."},"tl":{"q":"Sa Nebraska, sa daang hinahati ng median, nakasalubong mo ang nakahintong school bus sa kabilang panig. Ano ang dapat mong gawin?","o":["Hindi mo kailangang huminto, pero bantayan ang mga bata","Huminto hanggang umandar ang bus","Huminto lang kung may mga bata malapit sa bus","Pumunta sa gilid ng daan (shoulder)"],"h1":"Pinaghihiwalay ka ng median sa bus.","h2":"Sa daang hinahati ng median sa Nebraska, ang mga sasakyang galing sa kabilang direksyon ay hindi kailangang huminto para sa nakahintong school bus, pero dapat magbantay sa mga bata.","p":"Tama. Puwedeng dumaan nang maingat ang paparating na sasakyan sa daang may median."},"ar":{"q":"في Nebraska، على طريق مقسوم بجزيرة وسطية (median)، تصادف حافلة مدرسية متوقفة على الجانب الآخر. ماذا يجب أن تفعل؟","o":["ليس عليك أن تتوقف، لكن انتبه للأطفال","توقّف حتى تتحرك الحافلة","توقّف فقط إذا كان هناك أطفال قرب الحافلة","انتقل إلى كتف الطريق"],"h1":"الجزيرة الوسطية تفصلك عن الحافلة.","h2":"على طريق في Nebraska مقسوم بجزيرة وسطية، ليس على المركبات القادمة من الاتجاه المعاكس أن تتوقف لحافلة مدرسية متوقفة، لكن يجب أن تنتبه للأطفال.","p":"صحيح. المركبات القادمة من الاتجاه المعاكس على طريق مقسوم يمكنها المرور بحذر."},"ref":{"doc":"NE","page":70}},{"id":"ne-020","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, who must wear a seat belt by law?","o":["Only the driver","The driver, every front-seat passenger, and all children under 18","Only passengers under 16","Only people on interstates"],"h1":"The law covers the front seat and all children.","h2":"Nebraska law requires the driver and each front-seat passenger to buckle up, and every child under 18 must ride in a seat belt or a child safety seat.","p":"Right. The front seat, plus every child under 18."},"es":{"q":"En Nebraska, ¿quién debe usar el cinturón de seguridad por ley?","o":["Solo el conductor","El conductor, cada pasajero del asiento delantero y todos los niños menores de 18 años","Solo los pasajeros menores de 16 años","Solo quienes van en interestatales"],"h1":"La ley cubre el asiento delantero y a todos los niños.","h2":"La ley de Nebraska exige que el conductor y cada pasajero del asiento delantero usen el cinturón, y todo niño menor de 18 años debe ir con cinturón o en un asiento de seguridad para niños.","p":"Correcto. El asiento delantero, y todos los niños menores de 18."},"zh":{"q":"在 Nebraska，法律规定谁必须系安全带？","o":["只有司机","司机、每位前排乘客，以及所有 18 岁以下的孩子","只有 16 岁以下的乘客","只有在州际公路上的人"],"h1":"这条法律包括前排和所有孩子。","h2":"Nebraska 法律要求司机和每位前排乘客系好安全带，每个 18 岁以下的孩子都必须系安全带或坐儿童安全座椅。","p":"对。前排的人，加上每个 18 岁以下的孩子。"},"vi":{"q":"Ở Nebraska, theo luật ai phải thắt dây an toàn?","o":["Chỉ tài xế","Tài xế, mọi hành khách ở ghế trước, và tất cả trẻ em dưới 18 tuổi","Chỉ hành khách dưới 16 tuổi","Chỉ người đi trên xa lộ liên bang"],"h1":"Luật áp dụng cho ghế trước và tất cả trẻ em.","h2":"Luật Nebraska bắt buộc tài xế và mỗi hành khách ở ghế trước phải thắt dây an toàn, và mọi trẻ em dưới 18 tuổi phải ngồi với dây an toàn hoặc ghế an toàn cho trẻ em.","p":"Đúng. Ghế trước, cộng với mọi trẻ em dưới 18 tuổi."},"tl":{"q":"Sa Nebraska, sino ang dapat mag-seat belt ayon sa batas?","o":["Ang drayber lang","Ang drayber, bawat pasahero sa harap na upuan, at lahat ng batang wala pang 18","Ang mga pasaherong wala pang 16 lang","Ang mga tao lang sa interstate"],"h1":"Sakop ng batas ang harap na upuan at lahat ng bata.","h2":"Ayon sa batas ng Nebraska, dapat mag-seat belt ang drayber at bawat pasahero sa harap na upuan, at bawat batang wala pang 18 ay dapat naka-seat belt o nasa child safety seat.","p":"Tama. Ang harap na upuan, at bawat batang wala pang 18."},"ar":{"q":"في Nebraska، من يجب أن يضع حزام الأمان حسب القانون؟","o":["السائق فقط","السائق، وكل راكب في المقعد الأمامي، وكل الأطفال تحت 18 سنة","الركاب تحت 16 سنة فقط","الناس على الطرق السريعة بين الولايات فقط"],"h1":"القانون يشمل المقعد الأمامي وكل الأطفال.","h2":"قانون Nebraska يُلزم السائق وكل راكب في المقعد الأمامي بوضع حزام الأمان، ويجب أن يركب كل طفل تحت 18 سنة بحزام أمان أو في مقعد أمان للأطفال.","p":"صحيح. المقعد الأمامي، وكل طفل تحت 18 سنة."},"ref":{"doc":"NE","page":26}},{"id":"ne-021","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what happens if a driver collects 12 points within two years?","o":["A warning letter only","The license is revoked for six months","A one-day safety class","Higher fines, but the license is kept"],"h1":"Under the point system, this is automatic.","h2":"In Nebraska, collecting 12 points within two years means the license is automatically revoked for six months.","p":"Right. 12 points in two years means a six-month revocation."},"es":{"q":"En Nebraska, ¿qué pasa si un conductor acumula 12 puntos dentro de dos años?","o":["Solo recibe una carta de advertencia","La licencia se revoca por seis meses","Una clase de seguridad de un día","Multas más altas, pero conserva la licencia"],"h1":"Con el sistema de puntos, esto es automático.","h2":"En Nebraska, acumular 12 puntos dentro de dos años significa que la licencia se revoca automáticamente por seis meses.","p":"Correcto. 12 puntos en dos años significan una revocación de seis meses."},"zh":{"q":"在 Nebraska，如果司机在两年内累计 12 分，会怎么样？","o":["只收到一封警告信","驾照被吊销六个月","上一天的安全课","罚款更高，但可以保留驾照"],"h1":"按照扣分制度，这是自动发生的。","h2":"在 Nebraska，两年内累计 12 分，驾照会被自动吊销六个月。","p":"对。两年内 12 分，驾照被吊销六个月。"},"vi":{"q":"Ở Nebraska, chuyện gì xảy ra nếu tài xế bị 12 điểm trong vòng hai năm?","o":["Chỉ nhận một thư cảnh cáo","Bằng lái bị thu hồi sáu tháng","Học một lớp an toàn một ngày","Bị phạt nặng hơn, nhưng vẫn giữ bằng lái"],"h1":"Theo hệ thống tính điểm, việc này xảy ra tự động.","h2":"Ở Nebraska, bị 12 điểm trong vòng hai năm có nghĩa là bằng lái tự động bị thu hồi sáu tháng.","p":"Đúng. 12 điểm trong hai năm thì bị thu hồi bằng lái sáu tháng."},"tl":{"q":"Sa Nebraska, ano ang mangyayari kapag nakaipon ang drayber ng 12 puntos sa loob ng dalawang taon?","o":["Isang sulat ng babala lang","Babawiin ang lisensya nang anim na buwan","Isang araw na klase sa kaligtasan","Mas mataas na multa, pero mananatili ang lisensya"],"h1":"Sa point system, awtomatiko ito.","h2":"Sa Nebraska, kapag nakaipon ka ng 12 puntos sa loob ng dalawang taon, awtomatikong babawiin ang lisensya mo nang anim na buwan.","p":"Tama. Ang 12 puntos sa dalawang taon ay anim na buwang pagbawi ng lisensya."},"ar":{"q":"في Nebraska، ماذا يحدث إذا جمع السائق 12 نقطة خلال سنتين؟","o":["رسالة تحذير فقط","تُسحب الرخصة لمدة ستة أشهر","دورة سلامة ليوم واحد","غرامات أعلى، لكن يحتفظ بالرخصة"],"h1":"حسب نظام النقاط، يحدث هذا تلقائياً.","h2":"في Nebraska، إذا جمع السائق 12 نقطة خلال سنتين تُسحب رخصته تلقائياً لمدة ستة أشهر.","p":"صحيح. 12 نقطة خلال سنتين تعني سحب الرخصة لمدة ستة أشهر."},"ref":{"doc":"NE","page":18}},{"id":"ne-022","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a driver under 21 gets 6 or more points within one year. What must the driver do?","o":["Retake the driving skills test","Pay a $1,000 fine","Wait until age 21 to drive again","Take a driver improvement course within three months"],"h1":"It is a course meant to help the driver do better.","h2":"In Nebraska, a driver under 21 with 6 or more points in one year must take a driver improvement course within three months.","p":"Right. A driver improvement course within three months is required."},"es":{"q":"En Nebraska, un conductor menor de 21 años acumula 6 puntos o más dentro de un año. ¿Qué debe hacer?","o":["Repetir el examen práctico de manejo","Pagar una multa de $1,000","Esperar hasta los 21 años para volver a manejar","Tomar un curso para mejorar como conductor dentro de tres meses"],"h1":"Es un curso que busca ayudar al conductor a mejorar.","h2":"En Nebraska, un conductor menor de 21 años con 6 puntos o más en un año debe tomar un curso para mejorar como conductor dentro de tres meses.","p":"Correcto. Se exige un curso para mejorar como conductor dentro de tres meses."},"zh":{"q":"在 Nebraska，一位 21 岁以下的司机在一年内被扣 6 分或更多。这位司机必须做什么？","o":["重新参加驾驶技能考试","交 $1,000 罚款","等到 21 岁才能再开车","在三个月内上驾驶改进课程"],"h1":"这是一门帮助司机开得更好的课程。","h2":"在 Nebraska，21 岁以下的司机如果一年内被扣 6 分或更多，必须在三个月内上驾驶改进课程。","p":"对。必须在三个月内上驾驶改进课程。"},"vi":{"q":"Ở Nebraska, một tài xế dưới 21 tuổi bị 6 điểm trở lên trong vòng một năm. Tài xế đó phải làm gì?","o":["Thi lại phần thi kỹ năng lái xe","Nộp phạt $1,000","Chờ đến 21 tuổi mới được lái lại","Học một khóa cải thiện kỹ năng lái xe (driver improvement course) trong vòng ba tháng"],"h1":"Đó là một khóa học giúp tài xế lái tốt hơn.","h2":"Ở Nebraska, tài xế dưới 21 tuổi bị 6 điểm trở lên trong một năm phải học một khóa cải thiện kỹ năng lái xe trong vòng ba tháng.","p":"Đúng. Phải học khóa cải thiện kỹ năng lái xe trong vòng ba tháng."},"tl":{"q":"Sa Nebraska, nakakuha ang isang drayber na wala pang 21 ng 6 o higit pang puntos sa loob ng isang taon. Ano ang dapat gawin ng drayber?","o":["Kumuha ulit ng driving skills test","Magbayad ng $1,000 na multa","Maghintay hanggang edad 21 bago magmaneho ulit","Kumuha ng driver improvement course sa loob ng tatlong buwan"],"h1":"Isa itong kurso para tulungan ang drayber na gumaling.","h2":"Sa Nebraska, ang drayber na wala pang 21 na may 6 o higit pang puntos sa isang taon ay dapat kumuha ng driver improvement course sa loob ng tatlong buwan.","p":"Tama. Kailangan ang driver improvement course sa loob ng tatlong buwan."},"ar":{"q":"في Nebraska، حصل سائق عمره أقل من 21 سنة على 6 نقاط أو أكثر خلال سنة واحدة. ماذا يجب على السائق أن يفعل؟","o":["أن يعيد اختبار مهارات القيادة","أن يدفع غرامة $1,000","أن ينتظر حتى عمر 21 سنة ليقود مرة أخرى","أن يأخذ دورة تحسين القيادة (driver improvement course) خلال ثلاثة أشهر"],"h1":"إنها دورة تساعد السائق على أن يقود بشكل أفضل.","h2":"في Nebraska، السائق الذي عمره أقل من 21 سنة ويحصل على 6 نقاط أو أكثر خلال سنة يجب أن يأخذ دورة تحسين القيادة خلال ثلاثة أشهر.","p":"صحيح. دورة تحسين القيادة خلال ثلاثة أشهر مطلوبة."},"ref":{"doc":"NE","page":1}},{"id":"ne-023","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, a driver refuses a chemical test for alcohol or drugs when a police officer asks. What is the administrative penalty?","o":["One year of license revocation","A 30-day warning period","A $50 fine only","No penalty if the driver passes a later test"],"h1":"Every driver in Nebraska has already agreed to be tested.","h2":"In Nebraska, refusing a chemical test leads to a one-year license revocation, and the refusal is also a separate crime.","p":"Right. Refusing the test means one year without a license."},"es":{"q":"En Nebraska, un conductor se niega a hacer una prueba química de alcohol o drogas cuando un policía se la pide. ¿Cuál es la sanción administrativa?","o":["Un año de revocación de la licencia","Un período de advertencia de 30 días","Solo una multa de $50","Ninguna sanción si pasa una prueba después"],"h1":"Todo conductor en Nebraska ya aceptó hacerse la prueba.","h2":"En Nebraska, negarse a una prueba química lleva a una revocación de la licencia por un año, y negarse también es un delito aparte.","p":"Correcto. Negarse a la prueba significa un año sin licencia."},"zh":{"q":"在 Nebraska，警察要求司机做酒精或毒品化学检测，司机拒绝了。行政处罚是什么？","o":["吊销驾照一年","30 天的警告期","只罚款 $50","如果司机之后检测通过，就没有处罚"],"h1":"Nebraska 的每位司机都已经同意接受检测。","h2":"在 Nebraska，拒绝化学检测会导致驾照被吊销一年，而且拒绝检测本身也是另一项犯罪。","p":"对。拒绝检测就是一年没有驾照。"},"vi":{"q":"Ở Nebraska, tài xế từ chối xét nghiệm hóa học (chemical test) về rượu hoặc ma túy khi cảnh sát yêu cầu. Hình phạt hành chính là gì?","o":["Bị thu hồi bằng lái một năm","Thời gian cảnh cáo 30 ngày","Chỉ bị phạt $50","Không bị phạt nếu tài xế qua được xét nghiệm sau đó"],"h1":"Mọi tài xế ở Nebraska đều đã đồng ý cho xét nghiệm.","h2":"Ở Nebraska, từ chối xét nghiệm hóa học sẽ bị thu hồi bằng lái một năm, và việc từ chối cũng là một tội riêng.","p":"Đúng. Từ chối xét nghiệm nghĩa là một năm không có bằng lái."},"tl":{"q":"Sa Nebraska, tumanggi ang drayber sa chemical test para sa alak o droga nang hilingin ito ng pulis. Ano ang administratibong parusa?","o":["Isang taong pagbawi ng lisensya","30 araw na panahon ng babala","$50 na multa lang","Walang parusa kung pumasa ang drayber sa susunod na test"],"h1":"Pumayag na ang bawat drayber sa Nebraska na magpa-test.","h2":"Sa Nebraska, ang pagtanggi sa chemical test ay nagdudulot ng isang taong pagbawi ng lisensya, at hiwalay na krimen din ang pagtanggi.","p":"Tama. Ang pagtanggi sa test ay isang taon nang walang lisensya."},"ar":{"q":"في Nebraska، رفض سائق إجراء فحص كيميائي (chemical test) للكحول أو المخدرات عندما طلب منه الشرطي ذلك. ما هي العقوبة الإدارية؟","o":["سحب الرخصة لمدة سنة واحدة","فترة تحذير لمدة 30 يوماً","غرامة $50 فقط","لا عقوبة إذا نجح السائق في فحص لاحق"],"h1":"كل سائق في Nebraska قد وافق مسبقاً على إجراء الفحص.","h2":"في Nebraska، رفض الفحص الكيميائي يؤدي إلى سحب الرخصة لمدة سنة واحدة، والرفض أيضاً جريمة منفصلة.","p":"صحيح. رفض الفحص يعني سنة واحدة بدون رخصة."},"ref":{"doc":"NE","page":24}},{"id":"ne-024","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the minimum liability insurance for injury to one person in one crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In Nebraska, a vehicle must carry at least $25,000 of coverage for injury to one person in a crash.","p":"Right. The minimum is $25,000 for one injured person."},"es":{"q":"En Nebraska, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Nebraska, un vehículo debe tener al menos $25,000 de cobertura por lesiones a una persona en un choque.","p":"Correcto. El mínimo es de $25,000 por una persona lesionada."},"zh":{"q":"在 Nebraska，一次车祸中一人受伤的最低责任保险金额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"它和财产损失的最低金额一样。","h2":"在 Nebraska，车辆必须至少有 $25,000 的保险，用于车祸中一人受伤。","p":"对。一人受伤的最低金额是 $25,000。"},"vi":{"q":"Ở Nebraska, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Số tiền này bằng mức tối thiểu cho thiệt hại tài sản.","h2":"Ở Nebraska, xe phải có bảo hiểm ít nhất $25,000 cho thương tích của một người trong một vụ tai nạn.","p":"Đúng. Mức tối thiểu là $25,000 cho một người bị thương."},"tl":{"q":"Sa Nebraska, ano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang aksidente?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Kapareho ito ng pinakamababang halaga para sa pinsala sa ari-arian.","h2":"Sa Nebraska, dapat may hindi bababa sa $25,000 na coverage ang sasakyan para sa pinsala sa isang tao sa aksidente.","p":"Tama. $25,000 ang pinakamababa para sa isang taong nasaktan."},"ar":{"q":"في Nebraska، ما الحد الأدنى لتأمين المسؤولية (liability insurance) عن إصابة شخص واحد في حادث واحد؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"إنه نفس مبلغ الحد الأدنى لأضرار الممتلكات.","h2":"في Nebraska، يجب أن يكون للمركبة تأمين لا يقل عن $25,000 لإصابة شخص واحد في حادث.","p":"صحيح. الحد الأدنى هو $25,000 لشخص واحد مصاب."},"ref":{"doc":"NE","page":28}},{"id":"ne-025","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, what happens to a speeding fine in a school zone, or in a work zone when workers are present?","o":["It stays the same","It is doubled","It is cut in half","It is replaced by a warning"],"h1":"These zones protect children and workers, so the penalty is higher.","h2":"In Nebraska, speeding fines are doubled in school zones and in work zones when workers are present.","p":"Right. Fines are doubled in those zones."},"es":{"q":"En Nebraska, ¿qué pasa con la multa por exceso de velocidad en una zona escolar, o en una zona de obras cuando hay trabajadores?","o":["Se queda igual","Se duplica","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Estas zonas protegen a niños y trabajadores, así que la sanción es mayor.","h2":"En Nebraska, las multas por exceso de velocidad se duplican en zonas escolares y en zonas de obras cuando hay trabajadores.","p":"Correcto. Las multas se duplican en esas zonas."},"zh":{"q":"在 Nebraska，在学校区，或在有工人在场的施工区超速，罚款会怎么样？","o":["保持不变","加倍","减半","改成警告"],"h1":"这些区域保护孩子和工人，所以处罚更重。","h2":"在 Nebraska，在学校区和有工人在场的施工区超速，罚款会加倍。","p":"对。在这些区域罚款加倍。"},"vi":{"q":"Ở Nebraska, tiền phạt chạy quá tốc độ trong khu vực trường học, hoặc trong khu vực công trường khi có công nhân, sẽ thế nào?","o":["Vẫn như cũ","Tăng gấp đôi","Giảm một nửa","Được thay bằng cảnh cáo"],"h1":"Những khu vực này bảo vệ trẻ em và công nhân, nên hình phạt nặng hơn.","h2":"Ở Nebraska, tiền phạt chạy quá tốc độ tăng gấp đôi trong khu vực trường học và trong khu vực công trường khi có công nhân.","p":"Đúng. Tiền phạt tăng gấp đôi trong những khu vực đó."},"tl":{"q":"Sa Nebraska, ano ang nangyayari sa multa sa sobrang bilis sa school zone, o sa work zone kapag may mga manggagawa?","o":["Hindi ito nagbabago","Nadodoble ito","Nahahati ito sa kalahati","Napapalitan ito ng babala"],"h1":"Pinoprotektahan ng mga zone na ito ang mga bata at manggagawa, kaya mas mabigat ang parusa.","h2":"Sa Nebraska, nadodoble ang multa sa sobrang bilis sa school zone at sa work zone kapag may mga manggagawa.","p":"Tama. Doble ang multa sa mga zone na iyon."},"ar":{"q":"في Nebraska، ماذا يحدث لغرامة تجاوز السرعة في منطقة مدرسية، أو في منطقة أعمال عندما يكون العمّال موجودين؟","o":["تبقى كما هي","تتضاعف","تُخفَّض إلى النصف","تُستبدل بتحذير"],"h1":"هذه المناطق تحمي الأطفال والعمّال، لذلك العقوبة أعلى.","h2":"في Nebraska، تتضاعف غرامات تجاوز السرعة في المناطق المدرسية وفي مناطق الأعمال عندما يكون العمّال موجودين.","p":"صحيح. الغرامات تتضاعف في تلك المناطق."},"ref":{"doc":"NE","page":53}},{"id":"ne-026","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a new resident has a valid license from another state. How soon must they get a Nebraska license?","o":["Within 10 days","Within 6 months","Within 30 days","Within one year"],"h1":"It is about one month.","h2":"In Nebraska, a new resident with a valid out-of-state license must get a Nebraska license within 30 days.","p":"Right. New residents have 30 days."},"es":{"q":"En Nebraska, un nuevo residente tiene una licencia válida de otro estado. ¿En cuánto tiempo debe obtener una licencia de Nebraska?","o":["Dentro de 10 días","Dentro de 6 meses","Dentro de 30 días","Dentro de un año"],"h1":"Es más o menos un mes.","h2":"En Nebraska, un nuevo residente con una licencia válida de otro estado debe obtener una licencia de Nebraska dentro de 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 Nebraska，一位新居民有另一个州的有效驾照。他们必须在多久内拿到 Nebraska 驾照？","o":["10 天内","6 个月内","30 天内","一年内"],"h1":"大约是一个月。","h2":"在 Nebraska，有外州有效驾照的新居民必须在 30 天内拿到 Nebraska 驾照。","p":"对。新居民有 30 天。"},"vi":{"q":"Ở Nebraska, một cư dân mới có bằng lái còn hiệu lực của tiểu bang khác. Họ phải có bằng lái Nebraska trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 6 tháng","Trong vòng 30 ngày","Trong vòng một năm"],"h1":"Khoảng một tháng.","h2":"Ở Nebraska, cư dân mới có bằng lái còn hiệu lực của tiểu bang khác phải có bằng lái Nebraska trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa Nebraska, may valid na lisensya mula sa ibang estado ang isang bagong residente. Gaano kabilis siya dapat kumuha ng lisensya ng Nebraska?","o":["Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa loob ng 30 araw","Sa loob ng isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Nebraska, ang bagong residente na may valid na lisensya mula sa ibang estado ay dapat kumuha ng lisensya ng Nebraska sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في Nebraska، مقيم جديد لديه رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن يحصل على رخصة Nebraska؟","o":["خلال 10 أيام","خلال 6 أشهر","خلال 30 يوماً","خلال سنة واحدة"],"h1":"إنها حوالي شهر واحد.","h2":"في Nebraska، يجب على المقيم الجديد الذي لديه رخصة سارية من ولاية أخرى أن يحصل على رخصة Nebraska خلال 30 يوماً.","p":"صحيح. المقيمون الجدد لديهم 30 يوماً."},"ref":{"doc":"NE","page":1}},{"id":"ne-027","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you are in a crash that no police officer looked into, and someone was hurt. When must you send a crash report to the Department of Transportation?","o":["Within 24 hours","Within 30 days","Only if your insurance company asks","Within 10 days"],"h1":"You have a little more than one week.","h2":"In Nebraska, if no officer investigated and someone was hurt or the damage was $1,500 or more, you must send a crash report within 10 days.","p":"Right. The report is due within 10 days."},"es":{"q":"En Nebraska, usted tiene un choque que ningún policía investigó, y alguien resultó herido. ¿Cuándo debe enviar un reporte del choque al Departamento de Transporte?","o":["Dentro de 24 horas","Dentro de 30 días","Solo si su compañía de seguros lo pide","Dentro de 10 días"],"h1":"Tiene un poco más de una semana.","h2":"En Nebraska, si ningún policía investigó y alguien resultó herido o el daño fue de $1,500 o más, debe enviar un reporte del choque dentro de 10 días.","p":"Correcto. El reporte se debe enviar dentro de 10 días."},"zh":{"q":"在 Nebraska，你发生了一起没有警察调查的车祸，而且有人受伤。你必须在什么时候向交通部（Department of Transportation）提交车祸报告？","o":["24 小时内","30 天内","只有保险公司要求时","10 天内"],"h1":"你有一个多星期的时间。","h2":"在 Nebraska，如果没有警察调查，而且有人受伤或损失达到 $1,500 或更多，你必须在 10 天内提交车祸报告。","p":"对。报告要在 10 天内提交。"},"vi":{"q":"Ở Nebraska, bạn bị tai nạn mà không có cảnh sát điều tra, và có người bị thương. Khi nào bạn phải gửi báo cáo tai nạn cho Sở Giao thông (Department of Transportation)?","o":["Trong vòng 24 giờ","Trong vòng 30 ngày","Chỉ khi công ty bảo hiểm yêu cầu","Trong vòng 10 ngày"],"h1":"Bạn có hơn một tuần một chút.","h2":"Ở Nebraska, nếu không có cảnh sát điều tra và có người bị thương hoặc thiệt hại từ $1,500 trở lên, bạn phải gửi báo cáo tai nạn trong vòng 10 ngày.","p":"Đúng. Báo cáo phải nộp trong vòng 10 ngày."},"tl":{"q":"Sa Nebraska, naaksidente ka at walang pulis na nag-imbestiga, at may nasaktan. Kailan mo dapat ipadala ang crash report sa Department of Transportation?","o":["Sa loob ng 24 na oras","Sa loob ng 30 araw","Kapag hiningi lang ng insurance company mo","Sa loob ng 10 araw"],"h1":"May kaunti kang higit sa isang linggo.","h2":"Sa Nebraska, kung walang pulis na nag-imbestiga at may nasaktan o umabot sa $1,500 o higit pa ang pinsala, dapat kang magpadala ng crash report sa loob ng 10 araw.","p":"Tama. Dapat maipadala ang report sa loob ng 10 araw."},"ar":{"q":"في Nebraska، تعرّضت لحادث لم يحقق فيه أي شرطي، وأُصيب شخص. متى يجب أن ترسل تقرير الحادث إلى وزارة النقل (Department of Transportation)؟","o":["خلال 24 ساعة","خلال 30 يوماً","فقط إذا طلبت شركة التأمين","خلال 10 أيام"],"h1":"لديك أكثر من أسبوع بقليل.","h2":"في Nebraska، إذا لم يحقق أي شرطي في الحادث وأُصيب شخص أو كانت الأضرار $1,500 أو أكثر، يجب أن ترسل تقرير الحادث خلال 10 أيام.","p":"صحيح. التقرير مطلوب خلال 10 أيام."},"ref":{"doc":"NE","page":73}},{"id":"ne-028","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what happens if you fail the drive test three times in a row?","o":["You must wait one full year to try again","You need a driver training course or 90 days with an LPD","You must pay a double fee and test the next day","You lose your learner's permit for six months"],"h1":"You need more training or more practice time before you can try again.","h2":"In Nebraska, after three failed drive tests in a row, you must finish an approved driver training course or hold an LPD for at least 90 days before you apply again.","p":"Right. Take a course or practice with an LPD for 90 days."},"es":{"q":"En Nebraska, ¿qué pasa si reprueba el examen de manejo tres veces seguidas?","o":["Debe esperar un año completo para intentarlo otra vez","Necesita un curso de manejo o 90 días con un LPD","Debe pagar el doble y examinarse al día siguiente","Pierde su permiso de aprendiz por seis meses"],"h1":"Necesita más entrenamiento o más tiempo de práctica antes de intentarlo otra vez.","h2":"En Nebraska, después de reprobar tres veces seguidas el examen de manejo, debe terminar un curso de manejo aprobado o tener un LPD por al menos 90 días antes de volver a solicitar.","p":"Correcto. Tome un curso o practique con un LPD por 90 días."},"zh":{"q":"在 Nebraska，如果你连续三次路考不及格，会怎么样？","o":["你必须等整整一年才能再考","你需要上驾驶培训课，或持有 LPD 满 90 天","你必须付双倍费用，第二天再考","你的学习驾照会被收回六个月"],"h1":"你需要更多培训或更多练习时间，才能再考。","h2":"在 Nebraska，连续三次路考不及格后，你必须完成一门认可的驾驶培训课，或持有 LPD 至少 90 天，然后才能再次申请。","p":"对。去上课，或持 LPD 练习 90 天。"},"vi":{"q":"Ở Nebraska, chuyện gì xảy ra nếu bạn thi lái xe trượt ba lần liên tiếp?","o":["Bạn phải chờ đủ một năm mới được thi lại","Bạn cần học một khóa đào tạo lái xe hoặc có LPD 90 ngày","Bạn phải trả gấp đôi lệ phí và thi vào ngày hôm sau","Bạn bị mất giấy phép tập lái trong sáu tháng"],"h1":"Bạn cần học thêm hoặc tập thêm trước khi thi lại.","h2":"Ở Nebraska, sau khi thi lái xe trượt ba lần liên tiếp, bạn phải học xong một khóa đào tạo lái xe được chấp thuận hoặc có LPD ít nhất 90 ngày trước khi nộp đơn lại.","p":"Đúng. Học một khóa hoặc tập lái với LPD trong 90 ngày."},"tl":{"q":"Sa Nebraska, ano ang mangyayari kung bumagsak ka sa drive test nang tatlong beses na sunud-sunod?","o":["Dapat kang maghintay ng isang buong taon bago sumubok ulit","Kailangan mo ng driver training course o 90 araw na may LPD","Dapat kang magbayad ng dobleng bayad at mag-test kinabukasan","Mawawala ang learner's permit mo nang anim na buwan"],"h1":"Kailangan mo ng dagdag na training o dagdag na oras ng pagsasanay bago sumubok ulit.","h2":"Sa Nebraska, pagkatapos bumagsak sa drive test nang tatlong beses na sunud-sunod, dapat mong tapusin ang isang aprubadong driver training course o magkaroon ng LPD nang hindi bababa sa 90 araw bago mag-apply ulit.","p":"Tama. Mag-course o magsanay gamit ang LPD nang 90 araw."},"ar":{"q":"في Nebraska، ماذا يحدث إذا رسبت في اختبار القيادة ثلاث مرات متتالية؟","o":["يجب أن تنتظر سنة كاملة لتحاول مرة أخرى","تحتاج إلى دورة تدريب على القيادة أو 90 يوماً مع تصريح LPD","يجب أن تدفع رسوماً مضاعفة وتختبر في اليوم التالي","تفقد تصريح التعلّم لمدة ستة أشهر"],"h1":"تحتاج إلى تدريب أكثر أو وقت تمرين أطول قبل أن تحاول مرة أخرى.","h2":"في Nebraska، بعد الرسوب في اختبار القيادة ثلاث مرات متتالية، يجب أن تُكمل دورة تدريب على القيادة معتمدة أو أن تحمل تصريح LPD لمدة 90 يوماً على الأقل قبل أن تتقدّم مرة أخرى.","p":"صحيح. خذ دورة أو تمرّن مع تصريح LPD لمدة 90 يوماً."},"ref":{"doc":"NE","page":12}},{"id":"ne-029","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, when does a license issued to a driver under 21 expire?","o":["On the driver's 21st birthday","On the driver's 18th birthday","One year after it is issued","Five years after it is issued"],"h1":"It is tied to the age when adult alcohol rules begin.","h2":"In Nebraska, a license issued to someone under 21 expires on the driver's 21st birthday.","p":"Right. It expires on the 21st birthday."},"es":{"q":"En Nebraska, ¿cuándo vence una licencia emitida a un conductor menor de 21 años?","o":["El día que cumple 21 años","El día que cumple 18 años","Un año después de emitida","Cinco años después de emitida"],"h1":"Está ligada a la edad en que empiezan las reglas de alcohol para adultos.","h2":"En Nebraska, la licencia emitida a una persona menor de 21 años vence el día que el conductor cumple 21 años.","p":"Correcto. Vence al cumplir 21 años."},"zh":{"q":"在 Nebraska，发给 21 岁以下驾驶人的驾照什么时候到期？","o":["在驾驶人 21 岁生日那天","在驾驶人 18 岁生日那天","发证后一年","发证后五年"],"h1":"这和成年人饮酒规定开始的年龄有关。","h2":"在 Nebraska，发给 21 岁以下的人的驾照，在驾驶人 21 岁生日那天到期。","p":"对。驾照在 21 岁生日那天到期。"},"vi":{"q":"Ở Nebraska, bằng lái cấp cho người lái dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật lần thứ 21 của người lái","Vào sinh nhật lần thứ 18 của người lái","Một năm sau khi được cấp","Năm năm sau khi được cấp"],"h1":"Nó gắn với tuổi bắt đầu áp dụng luật rượu bia cho người lớn.","h2":"Ở Nebraska, bằng lái cấp cho người dưới 21 tuổi hết hạn vào sinh nhật lần thứ 21 của người lái.","p":"Đúng. Bằng lái hết hạn vào sinh nhật lần thứ 21."},"tl":{"q":"Sa Nebraska, kailan mag-e-expire ang lisensyang ibinigay sa driver na wala pang 21?","o":["Sa ika-21 kaarawan ng driver","Sa ika-18 kaarawan ng driver","Isang taon pagkatapos itong ibigay","Limang taon pagkatapos itong ibigay"],"h1":"Nakatali ito sa edad kung kailan nagsisimula ang mga patakaran sa alak para sa adult.","h2":"Sa Nebraska, ang lisensyang ibinigay sa taong wala pang 21 ay mag-e-expire sa ika-21 kaarawan ng driver.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan."},"ar":{"q":"في Nebraska، متى تنتهي صلاحية الرخصة الصادرة لسائق عمره أقل من 21 سنة؟","o":["في عيد ميلاد السائق الحادي والعشرين (21)","في عيد ميلاد السائق الثامن عشر (18)","بعد سنة واحدة من صدورها","بعد خمس سنوات من صدورها"],"h1":"الأمر مرتبط بالعمر الذي تبدأ فيه قواعد الكحول الخاصة بالبالغين.","h2":"في Nebraska، تنتهي صلاحية الرخصة الصادرة لشخص عمره أقل من 21 سنة في عيد ميلاد السائق الحادي والعشرين (21).","p":"صحيح. تنتهي صلاحيتها في عيد الميلاد الحادي والعشرين (21)."},"ref":{"doc":"NE","page":15}},{"id":"ne-030","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, it is illegal to pass another vehicle within what distance of an intersection or railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is about the length of a few houses.","h2":"In Nebraska, it is illegal to pass another vehicle within 100 feet of an intersection or a railroad crossing.","p":"Right. No passing within 100 feet of either one."},"es":{"q":"En Nebraska, ¿a qué distancia de una intersección o de un cruce de ferrocarril es ilegal rebasar a otro vehículo?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Nebraska, es ilegal rebasar a otro vehículo a menos de 100 pies de una intersección o de un cruce de ferrocarril.","p":"Correcto. No rebase a menos de 100 pies de ninguno de los dos."},"zh":{"q":"在 Nebraska，在距离路口或铁路道口多远以内超车是违法的？","o":["25 英尺","50 英尺","100 英尺","500 英尺"],"h1":"大约是几栋房子的长度。","h2":"在 Nebraska，在距离路口或铁路道口 100 英尺以内超车是违法的。","p":"对。在这两种地方 100 英尺以内都不能超车。"},"vi":{"q":"Ở Nebraska, vượt xe khác trong khoảng cách bao nhiêu gần giao lộ hoặc chỗ băng qua đường ray xe lửa là phạm luật?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Khoảng bằng chiều dài của vài căn nhà.","h2":"Ở Nebraska, vượt xe khác trong vòng 100 feet gần giao lộ hoặc chỗ băng qua đường ray xe lửa là phạm luật.","p":"Đúng. Không được vượt trong vòng 100 feet gần cả hai nơi này."},"tl":{"q":"Sa Nebraska, bawal mag-overtake sa ibang sasakyan sa loob ng anong layo mula sa intersection o railroad crossing?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"Mga kasinghaba ito ng ilang bahay.","h2":"Sa Nebraska, bawal mag-overtake sa ibang sasakyan sa loob ng 100 feet mula sa intersection o railroad crossing.","p":"Tama. Bawal mag-overtake sa loob ng 100 feet mula sa alinman sa dalawa."},"ar":{"q":"في Nebraska، يُمنع تجاوز مركبة أخرى ضمن أي مسافة من التقاطع أو من معبر السكة الحديدية؟","o":["25 قدماً","50 قدماً","100 قدم","500 قدم"],"h1":"إنها تقريباً بطول بضعة بيوت.","h2":"في Nebraska، يُمنع تجاوز مركبة أخرى ضمن 100 قدم من التقاطع أو من معبر السكة الحديدية.","p":"صحيح. لا تجاوز ضمن 100 قدم من أيّ منهما."},"ref":{"doc":"NE","page":53}},{"id":"ne-031","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a snowplow is working on the road ahead. Unless you are passing, how far back should you stay?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Sand and chunks of ice can fly off the plow.","h2":"In Nebraska, you should stay 100 feet behind a snowplow or other road maintenance vehicle that is working, unless you are passing.","p":"Right. Keep 100 feet behind a working snowplow."},"es":{"q":"En Nebraska, un quitanieves está trabajando en la carretera delante de usted. Si no va a rebasar, ¿a qué distancia debe mantenerse?","o":["20 pies","50 pies","75 pies","100 pies"],"h1":"Del quitanieves pueden salir volando arena y trozos de hielo.","h2":"En Nebraska, debe mantenerse a 100 pies detrás de un quitanieves u otro vehículo de mantenimiento que esté trabajando, a menos que vaya a rebasar.","p":"Correcto. Manténgase a 100 pies de un quitanieves que trabaja."},"zh":{"q":"在 Nebraska，前方道路上有一辆扫雪车正在工作。除非你要超车，你应该在后面保持多远？","o":["20 英尺","50 英尺","75 英尺","100 英尺"],"h1":"沙子和冰块可能会从扫雪车上飞出来。","h2":"在 Nebraska，除非你要超车，你应该在正在工作的扫雪车或其他道路养护车后面保持 100 英尺。","p":"对。在正在工作的扫雪车后面保持 100 英尺。"},"vi":{"q":"Ở Nebraska, có một xe ủi tuyết đang làm việc trên đường phía trước. Trừ khi bạn đang vượt, bạn nên giữ khoảng cách phía sau bao xa?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Cát và những cục băng có thể văng ra từ xe ủi tuyết.","h2":"Ở Nebraska, bạn nên ở cách 100 feet phía sau xe ủi tuyết hoặc xe bảo trì đường khác đang làm việc, trừ khi bạn đang vượt.","p":"Đúng. Giữ cách 100 feet phía sau xe ủi tuyết đang làm việc."},"tl":{"q":"Sa Nebraska, may snowplow na nagtatrabaho sa daan sa unahan mo. Maliban kung nag-o-overtake ka, gaano kalayo ka dapat manatili sa likod?","o":["20 feet","50 feet","75 feet","100 feet"],"h1":"Puwedeng tumilapon ang buhangin at piraso ng yelo mula sa snowplow.","h2":"Sa Nebraska, dapat kang manatili nang 100 feet sa likod ng snowplow o ibang sasakyang pang-maintenance ng daan na nagtatrabaho, maliban kung nag-o-overtake ka.","p":"Tama. Manatili nang 100 feet sa likod ng nagtatrabahong snowplow."},"ar":{"q":"في Nebraska، هناك كاسحة ثلج تعمل على الطريق أمامك. ما لم تكن تتجاوزها، على أي مسافة يجب أن تبقى خلفها؟","o":["20 قدماً","50 قدماً","75 قدماً","100 قدم"],"h1":"قد يتطاير الرمل وقطع الجليد من كاسحة الثلج.","h2":"في Nebraska، يجب أن تبقى على بُعد 100 قدم خلف كاسحة الثلج أو أي مركبة صيانة طرق أخرى تعمل، ما لم تكن تتجاوزها.","p":"صحيح. ابقَ على بُعد 100 قدم خلف كاسحة الثلج التي تعمل."},"ref":{"doc":"NE","page":70}},{"id":"ne-032","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how long is a learner's permit (LPD) valid?","o":["Six months after it is issued","One year after it is issued","Until the 16th birthday","Two years after it is issued"],"h1":"It lasts longer than the six-month school learner's permit.","h2":"In Nebraska, a learner's permit (LPD) expires one year after the date it is issued.","p":"Right. The LPD is good for one year."},"es":{"q":"En Nebraska, ¿por cuánto tiempo es válido el permiso de aprendiz (LPD)?","o":["Seis meses después de emitido","Un año después de emitido","Hasta cumplir 16 años","Dos años después de emitido"],"h1":"Dura más que el permiso escolar de aprendiz de seis meses.","h2":"En Nebraska, el permiso de aprendiz (LPD) vence un año después de la fecha en que se emite.","p":"Correcto. El LPD es válido por un año."},"zh":{"q":"在 Nebraska，学习驾照（LPD）的有效期是多久？","o":["发放后六个月","发放后一年","到 16 岁生日为止","发放后两年"],"h1":"它比只有六个月的学校学习驾照用得更久。","h2":"在 Nebraska，学习驾照（LPD）在发放日期一年后到期。","p":"对。LPD 有效期是一年。"},"vi":{"q":"Ở Nebraska, giấy phép tập lái (LPD) có hiệu lực trong bao lâu?","o":["Sáu tháng sau khi được cấp","Một năm sau khi được cấp","Đến sinh nhật 16 tuổi","Hai năm sau khi được cấp"],"h1":"Nó có hiệu lực lâu hơn giấy phép tập lái đi học, loại chỉ có sáu tháng.","h2":"Ở Nebraska, giấy phép tập lái (LPD) hết hạn một năm sau ngày được cấp.","p":"Đúng. LPD có hiệu lực một năm."},"tl":{"q":"Sa Nebraska, gaano katagal may bisa ang learner's permit (LPD)?","o":["Anim na buwan matapos itong ibigay","Isang taon matapos itong ibigay","Hanggang sa ika-16 na kaarawan","Dalawang taon matapos itong ibigay"],"h1":"Mas matagal ito kaysa sa school learner's permit na anim na buwan lang.","h2":"Sa Nebraska, mapapaso ang learner's permit (LPD) isang taon matapos ang petsa ng pagbibigay nito.","p":"Tama. May bisa ang LPD nang isang taon."},"ar":{"q":"في Nebraska، ما مدة صلاحية تصريح التعلّم (LPD)؟","o":["ستة أشهر بعد إصداره","سنة واحدة بعد إصداره","حتى عيد الميلاد الـ 16","سنتان بعد إصداره"],"h1":"مدته أطول من تصريح التعلّم المدرسي الذي يدوم ستة أشهر.","h2":"في Nebraska ينتهي تصريح التعلّم (LPD) بعد سنة واحدة من تاريخ إصداره.","p":"صحيح. تصريح LPD صالح لمدة سنة واحدة."},"ref":{"doc":"NE","page":4}},{"id":"ne-033","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, when does a provisional operator's permit (POP) expire?","o":["On the 16th birthday","One year after it is issued","On the 21st birthday","On the 18th birthday"],"h1":"It ends when the driver becomes an adult.","h2":"In Nebraska, a provisional operator's permit (POP) expires on the holder's 18th birthday.","p":"Right. The POP ends at 18."},"es":{"q":"En Nebraska, ¿cuándo vence el permiso provisional de operador (POP)?","o":["Al cumplir 16 años","Un año después de emitido","Al cumplir 21 años","Al cumplir 18 años"],"h1":"Termina cuando el conductor llega a la mayoría de edad.","h2":"En Nebraska, el permiso provisional de operador (POP) vence cuando el titular cumple 18 años.","p":"Correcto. El POP termina a los 18."},"zh":{"q":"在 Nebraska，临时驾照（POP）什么时候到期？","o":["16 岁生日那天","发放后一年","21 岁生日那天","18 岁生日那天"],"h1":"司机成年时，它就结束了。","h2":"在 Nebraska，临时驾照（POP）在持有人 18 岁生日那天到期。","p":"对。POP 到 18 岁结束。"},"vi":{"q":"Ở Nebraska, giấy phép lái xe tạm thời (POP) hết hạn khi nào?","o":["Vào sinh nhật 16 tuổi","Một năm sau khi được cấp","Vào sinh nhật 21 tuổi","Vào sinh nhật 18 tuổi"],"h1":"Nó kết thúc khi tài xế trở thành người lớn.","h2":"Ở Nebraska, giấy phép lái xe tạm thời (POP) hết hạn vào sinh nhật 18 tuổi của người giữ giấy phép.","p":"Đúng. POP kết thúc lúc 18 tuổi."},"tl":{"q":"Sa Nebraska, kailan mapapaso ang provisional operator's permit (POP)?","o":["Sa ika-16 na kaarawan","Isang taon matapos itong ibigay","Sa ika-21 kaarawan","Sa ika-18 kaarawan"],"h1":"Natatapos ito kapag naging adulto na ang drayber.","h2":"Sa Nebraska, mapapaso ang provisional operator's permit (POP) sa ika-18 kaarawan ng may hawak nito.","p":"Tama. Natatapos ang POP sa edad na 18."},"ar":{"q":"في Nebraska، متى ينتهي تصريح القيادة المؤقت (POP)؟","o":["في عيد الميلاد الـ 16","بعد سنة واحدة من إصداره","في عيد الميلاد الـ 21","في عيد الميلاد الـ 18"],"h1":"ينتهي عندما يصبح السائق بالغاً.","h2":"في Nebraska ينتهي تصريح القيادة المؤقت (POP) في عيد الميلاد الـ 18 لحامله.","p":"صحيح. ينتهي تصريح POP في عمر 18 سنة."},"ref":{"doc":"NE","page":5}},{"id":"ne-034","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a School Permit (SCP) lets a young teen drive to school. Where must the teen live or go to school to get one?","o":["Outside a city of 5,000 or more people","Inside a city of 50,000 or more people","Within one mile of the school","In a county with no school buses"],"h1":"This permit is meant for teens in small towns and the country.","h2":"In Nebraska, a School Permit can be issued to a teen who lives, or goes to school, outside a city of 5,000 or more people.","p":"Right. The SCP is for teens outside cities of 5,000 or more."},"es":{"q":"En Nebraska, el permiso escolar (SCP) permite a un adolescente joven manejar a la escuela. ¿Dónde debe vivir o estudiar el adolescente para obtenerlo?","o":["Fuera de una ciudad de 5,000 habitantes o más","Dentro de una ciudad de 50,000 habitantes o más","A menos de una milla de la escuela","En un condado sin autobuses escolares"],"h1":"Este permiso es para adolescentes de pueblos pequeños y del campo.","h2":"En Nebraska, el permiso escolar se puede dar a un adolescente que vive, o estudia, fuera de una ciudad de 5,000 habitantes o más.","p":"Correcto. El SCP es para adolescentes fuera de ciudades de 5,000 o más."},"zh":{"q":"在 Nebraska，学校驾照（SCP）让年纪小的青少年可以开车上学。青少年必须住在哪里或在哪里上学，才能拿到它？","o":["人口 5,000 或以上的城市以外","人口 50,000 或以上的城市以内","离学校一英里以内","没有校车的县"],"h1":"这种驾照是给小镇和乡下的青少年的。","h2":"在 Nebraska，住在人口 5,000 或以上的城市以外，或在那里以外上学的青少年，可以拿到学校驾照。","p":"对。SCP 是给人口 5,000 或以上城市以外的青少年的。"},"vi":{"q":"Ở Nebraska, giấy phép đi học (School Permit, SCP) cho phép thiếu niên nhỏ tuổi lái xe đến trường. Thiếu niên phải sống hoặc đi học ở đâu để có giấy phép này?","o":["Bên ngoài thành phố có 5,000 dân trở lên","Bên trong thành phố có 50,000 dân trở lên","Trong vòng một dặm từ trường","Ở quận không có xe buýt trường học"],"h1":"Giấy phép này dành cho thiếu niên ở thị trấn nhỏ và vùng nông thôn.","h2":"Ở Nebraska, giấy phép đi học có thể được cấp cho thiếu niên sống, hoặc đi học, bên ngoài thành phố có 5,000 dân trở lên.","p":"Đúng. SCP dành cho thiếu niên bên ngoài thành phố có 5,000 dân trở lên."},"tl":{"q":"Sa Nebraska, pinapayagan ng School Permit (SCP) ang batang tinedyer na magmaneho papunta sa paaralan. Saan dapat nakatira o nag-aaral ang tinedyer para makakuha nito?","o":["Sa labas ng lungsod na may 5,000 o higit pang tao","Sa loob ng lungsod na may 50,000 o higit pang tao","Sa loob ng isang milya mula sa paaralan","Sa county na walang school bus"],"h1":"Para ang permit na ito sa mga tinedyer sa maliliit na bayan at sa probinsya.","h2":"Sa Nebraska, puwedeng bigyan ng School Permit ang tinedyer na nakatira, o nag-aaral, sa labas ng lungsod na may 5,000 o higit pang tao.","p":"Tama. Para ang SCP sa mga tinedyer sa labas ng mga lungsod na may 5,000 o higit pang tao."},"ar":{"q":"في Nebraska، يسمح التصريح المدرسي (School Permit, SCP) للمراهق الصغير بقيادة السيارة إلى المدرسة. أين يجب أن يسكن المراهق أو يدرس ليحصل عليه؟","o":["خارج مدينة يسكنها 5,000 شخص أو أكثر","داخل مدينة يسكنها 50,000 شخص أو أكثر","على بعد ميل واحد من المدرسة أو أقل","في مقاطعة ليس فيها حافلات مدرسية"],"h1":"هذا التصريح مخصّص للمراهقين في البلدات الصغيرة والأرياف.","h2":"في Nebraska يمكن إصدار التصريح المدرسي لمراهق يسكن، أو يدرس، خارج مدينة يسكنها 5,000 شخص أو أكثر.","p":"صحيح. تصريح SCP للمراهقين خارج المدن التي يسكنها 5,000 شخص أو أكثر."},"ref":{"doc":"NE","page":2}},{"id":"ne-035","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you change your name or move to a new address. How soon must you update your license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is about two months.","h2":"In Nebraska, state law says you must report a name or address change within 60 days.","p":"Right. You have 60 days to update it."},"es":{"q":"En Nebraska, usted cambia de nombre o se muda a otra dirección. ¿En cuánto tiempo debe actualizar su licencia?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 60 días","Dentro de 90 días"],"h1":"Son unos dos meses.","h2":"En Nebraska, la ley estatal dice que debe informar un cambio de nombre o de dirección dentro de 60 días.","p":"Correcto. Tiene 60 días para actualizarla."},"zh":{"q":"在 Nebraska，你改了名字或搬到新地址。你必须在多久内更新驾照？","o":["10 天内","30 天内","60 天内","90 天内"],"h1":"大约两个月。","h2":"在 Nebraska，州法律规定你必须在 60 天内报告名字或地址的变更。","p":"对。你有 60 天时间更新。"},"vi":{"q":"Ở Nebraska, bạn đổi tên hoặc chuyển đến địa chỉ mới. Bạn phải cập nhật bằng lái trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 90 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở Nebraska, luật tiểu bang nói bạn phải báo việc đổi tên hoặc đổi địa chỉ trong vòng 60 ngày.","p":"Đúng. Bạn có 60 ngày để cập nhật."},"tl":{"q":"Sa Nebraska, nagpalit ka ng pangalan o lumipat ka sa bagong address. Gaano kabilis mo dapat i-update ang lisensya mo?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 90 araw"],"h1":"Mga dalawang buwan ito.","h2":"Sa Nebraska, sinasabi ng batas ng estado na dapat mong iulat ang pagpapalit ng pangalan o address sa loob ng 60 araw.","p":"Tama. May 60 araw ka para i-update ito."},"ar":{"q":"في Nebraska، غيّرت اسمك أو انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تحدّث رخصتك؟","o":["خلال 10 أيام","خلال 30 يوماً","خلال 60 يوماً","خلال 90 يوماً"],"h1":"حوالي شهرين.","h2":"في Nebraska ينصّ قانون الولاية على أنه يجب أن تبلّغ عن تغيير الاسم أو العنوان خلال 60 يوماً.","p":"صحيح. لديك 60 يوماً لتحديثها."},"ref":{"doc":"NE","page":16}},{"id":"ne-036","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a driver finishes a DMV-approved driver improvement course before reaching 12 points. What may the driver get?","o":["All points are erased","A credit of 2 points","A credit of 6 points","A free license renewal"],"h1":"The credit is small, and it can be used only once every five years.","h2":"In Nebraska, a driver who finishes a DMV-approved driver improvement course before reaching 12 points may get a 2-point credit, once every five years.","p":"Right. The course can earn a 2-point credit."},"es":{"q":"En Nebraska, un conductor termina un curso de mejora para conductores aprobado por el DMV antes de llegar a 12 puntos. ¿Qué puede recibir?","o":["Se borran todos los puntos","Un crédito de 2 puntos","Un crédito de 6 puntos","Una renovación de licencia gratis"],"h1":"El crédito es pequeño y solo se puede usar una vez cada cinco años.","h2":"En Nebraska, un conductor que termina un curso de mejora aprobado por el DMV antes de llegar a 12 puntos puede recibir un crédito de 2 puntos, una vez cada cinco años.","p":"Correcto. El curso puede dar un crédito de 2 puntos."},"zh":{"q":"在 Nebraska，一位司机在累计到 12 分之前，完成了 DMV 批准的驾驶改进课程。这位司机可以得到什么？","o":["所有扣分都被清除","抵消 2 分","抵消 6 分","免费更新驾照"],"h1":"抵消的分数很少，而且每五年只能用一次。","h2":"在 Nebraska，司机在累计到 12 分之前完成 DMV 批准的驾驶改进课程，可以抵消 2 分，每五年一次。","p":"对。这门课程可以抵消 2 分。"},"vi":{"q":"Ở Nebraska, một tài xế học xong khóa cải thiện kỹ năng lái xe được DMV chấp thuận trước khi bị 12 điểm. Tài xế đó có thể được gì?","o":["Xóa hết tất cả điểm","Được trừ 2 điểm","Được trừ 6 điểm","Gia hạn bằng lái miễn phí"],"h1":"Số điểm được trừ nhỏ, và chỉ được dùng một lần mỗi năm năm.","h2":"Ở Nebraska, tài xế học xong khóa cải thiện kỹ năng lái xe được DMV chấp thuận trước khi bị 12 điểm có thể được trừ 2 điểm, một lần mỗi năm năm.","p":"Đúng. Khóa học có thể giúp được trừ 2 điểm."},"tl":{"q":"Sa Nebraska, natapos ng isang drayber ang driver improvement course na aprubado ng DMV bago umabot sa 12 puntos. Ano ang puwedeng makuha ng drayber?","o":["Mabubura ang lahat ng puntos","Bawas na 2 puntos","Bawas na 6 na puntos","Libreng renewal ng lisensya"],"h1":"Maliit ang bawas, at magagamit lang ito minsan bawat limang taon.","h2":"Sa Nebraska, ang drayber na nakatapos ng driver improvement course na aprubado ng DMV bago umabot sa 12 puntos ay puwedeng makakuha ng bawas na 2 puntos, minsan bawat limang taon.","p":"Tama. Puwedeng magbigay ang kurso ng bawas na 2 puntos."},"ar":{"q":"في Nebraska، أنهى سائق دورة تحسين القيادة المعتمدة من DMV قبل أن يصل إلى 12 نقطة. ماذا يمكن أن يحصل عليه السائق؟","o":["تُمحى كل النقاط","خصم 2 نقطة","خصم 6 نقاط","تجديد مجاني للرخصة"],"h1":"الخصم صغير، ولا يمكن استخدامه إلا مرة واحدة كل خمس سنوات.","h2":"في Nebraska، السائق الذي ينهي دورة تحسين القيادة المعتمدة من DMV قبل أن يصل إلى 12 نقطة يمكن أن يحصل على خصم 2 نقطة، مرة واحدة كل خمس سنوات.","p":"صحيح. يمكن أن تمنحك الدورة خصم 2 نقطة."},"ref":{"doc":"NE","page":19}},{"id":"ne-037","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, how many points go on a regular (Class O) license holder's record for reading, typing or sending a text on a handheld phone while driving?","o":["2 points","No points","6 points","3 points"],"h1":"It is more than for most small violations, but less than for drunk driving.","h2":"In Nebraska, using a handheld phone to read, type or send written messages while driving adds 3 points to your record.","p":"Right. Texting while driving costs 3 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan al historial de un conductor con licencia regular (Clase O) por leer, escribir o enviar un mensaje de texto en un teléfono de mano mientras maneja?","o":["2 puntos","Ningún punto","6 puntos","3 puntos"],"h1":"Es más que por la mayoría de las faltas pequeñas, pero menos que por manejar ebrio.","h2":"En Nebraska, usar un teléfono de mano para leer, escribir o enviar mensajes mientras maneja agrega 3 puntos a su historial.","p":"Correcto. Enviar textos al manejar cuesta 3 puntos."},"zh":{"q":"在 Nebraska，持普通驾照（Class O）的人开车时用手拿的手机看短信、打短信或发短信，记录上会被记几分？","o":["2 分","不记分","6 分","3 分"],"h1":"比大多数小违规记得多，但比酒后驾驶记得少。","h2":"在 Nebraska，开车时用手拿的手机看、打或发文字信息，你的记录上会被记 3 分。","p":"对。开车时发短信记 3 分。"},"vi":{"q":"Ở Nebraska, người có bằng lái thường (Class O) bị ghi bao nhiêu điểm vào hồ sơ vì đọc, gõ hoặc gửi tin nhắn trên điện thoại cầm tay khi lái xe?","o":["2 điểm","Không bị điểm nào","6 điểm","3 điểm"],"h1":"Nhiều hơn hầu hết các vi phạm nhỏ, nhưng ít hơn lái xe khi say rượu.","h2":"Ở Nebraska, dùng điện thoại cầm tay để đọc, gõ hoặc gửi tin nhắn chữ khi lái xe sẽ bị ghi 3 điểm vào hồ sơ của bạn.","p":"Đúng. Nhắn tin khi lái xe bị 3 điểm."},"tl":{"q":"Sa Nebraska, ilang puntos ang inilalagay sa rekord ng may hawak ng regular na lisensya (Class O) dahil sa pagbasa, pag-type o pagpapadala ng text sa hawak na telepono habang nagmamaneho?","o":["2 puntos","Walang puntos","6 na puntos","3 puntos"],"h1":"Mas marami ito kaysa sa karamihan ng maliliit na paglabag, pero mas kaunti kaysa sa pagmamaneho nang lasing.","h2":"Sa Nebraska, ang paggamit ng hawak na telepono para magbasa, mag-type o magpadala ng nakasulat na mensahe habang nagmamaneho ay nagdadagdag ng 3 puntos sa rekord mo.","p":"Tama. 3 puntos ang pag-text habang nagmamaneho."},"ar":{"q":"في Nebraska، كم نقطة تُضاف إلى سجل حامل الرخصة العادية (Class O) بسبب قراءة أو كتابة أو إرسال رسالة نصية على هاتف محمول باليد أثناء القيادة؟","o":["2 نقطة","لا نقاط","6 نقاط","3 نقاط"],"h1":"أكثر من معظم المخالفات الصغيرة، لكن أقل من القيادة تحت تأثير الكحول.","h2":"في Nebraska، استخدام هاتف محمول باليد لقراءة رسائل مكتوبة أو كتابتها أو إرسالها أثناء القيادة يضيف 3 نقاط إلى سجلك.","p":"صحيح. الرسائل النصية أثناء القيادة تكلّف 3 نقاط."},"ref":{"doc":"NE","page":19}},{"id":"ne-038","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a driver's license is revoked under the point system for the second time in five years. How long is this revocation?","o":["Three years","Six months","One year","Ten years"],"h1":"It is much longer than the first six-month revocation.","h2":"In Nebraska, a driver whose license is revoked under the point system twice in five years loses it for three years.","p":"Right. A second point revocation lasts three years."},"es":{"q":"En Nebraska, a un conductor le revocan la licencia por el sistema de puntos por segunda vez en cinco años. ¿Cuánto dura esta revocación?","o":["Tres años","Seis meses","Un año","Diez años"],"h1":"Es mucho más larga que la primera revocación de seis meses.","h2":"En Nebraska, un conductor a quien le revocan la licencia por el sistema de puntos dos veces en cinco años la pierde por tres años.","p":"Correcto. Una segunda revocación por puntos dura tres años."},"zh":{"q":"在 Nebraska，一位司机的驾照在五年内第二次因为记分制度被吊销。这次吊销多久？","o":["三年","六个月","一年","十年"],"h1":"比第一次六个月的吊销长得多。","h2":"在 Nebraska，五年内两次因为记分制度被吊销驾照的司机，会失去驾照三年。","p":"对。第二次因记分吊销持续三年。"},"vi":{"q":"Ở Nebraska, bằng lái của một tài xế bị thu hồi theo hệ thống điểm lần thứ hai trong năm năm. Lần thu hồi này kéo dài bao lâu?","o":["Ba năm","Sáu tháng","Một năm","Mười năm"],"h1":"Lâu hơn nhiều so với lần thu hồi đầu tiên sáu tháng.","h2":"Ở Nebraska, tài xế bị thu hồi bằng lái theo hệ thống điểm hai lần trong năm năm sẽ mất bằng lái ba năm.","p":"Đúng. Lần thu hồi thứ hai vì điểm kéo dài ba năm."},"tl":{"q":"Sa Nebraska, binawi ang lisensya ng isang drayber sa ilalim ng point system sa ikalawang pagkakataon sa loob ng limang taon. Gaano katagal ang pagbawing ito?","o":["Tatlong taon","Anim na buwan","Isang taon","Sampung taon"],"h1":"Mas matagal ito kaysa sa unang pagbawi na anim na buwan.","h2":"Sa Nebraska, ang drayber na binawian ng lisensya sa ilalim ng point system nang dalawang beses sa loob ng limang taon ay mawawalan nito nang tatlong taon.","p":"Tama. Tatlong taon ang ikalawang pagbawi dahil sa puntos."},"ar":{"q":"في Nebraska، سُحبت رخصة سائق بموجب نظام النقاط للمرة الثانية خلال خمس سنوات. ما مدة هذا السحب؟","o":["ثلاث سنوات","ستة أشهر","سنة واحدة","عشر سنوات"],"h1":"إنه أطول بكثير من السحب الأول لمدة ستة أشهر.","h2":"في Nebraska، السائق الذي تُسحب رخصته بموجب نظام النقاط مرتين خلال خمس سنوات يفقدها لمدة ثلاث سنوات.","p":"صحيح. السحب الثاني بسبب النقاط يدوم ثلاث سنوات."},"ref":{"doc":"NE","page":18}},{"id":"ne-039","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a first-time offender fails an alcohol test after a DUI arrest. How long is the administrative license revocation?","o":["30 days","90 days","180 days","Two years"],"h1":"It is about half a year.","h2":"In Nebraska, a first-time offender who fails an alcohol test has the license administratively revoked for 180 days.","p":"Right. A first failed test means 180 days."},"es":{"q":"En Nebraska, un conductor sin infracciones anteriores no pasa la prueba de alcohol después de un arresto por manejar ebrio (DUI). ¿Cuánto dura la revocación administrativa de la licencia?","o":["30 días","90 días","180 días","Dos años"],"h1":"Es más o menos medio año.","h2":"En Nebraska, a quien no pasa una prueba de alcohol por primera vez se le revoca la licencia de forma administrativa por 180 días.","p":"Correcto. La primera prueba fallida significa 180 días."},"zh":{"q":"在 Nebraska，一位初次违规的人因 DUI（酒后驾驶）被捕后，酒精检测没有通过。行政吊销驾照多久？","o":["30 天","90 天","180 天","两年"],"h1":"大约半年。","h2":"在 Nebraska，初次违规的人酒精检测没有通过，驾照会被行政吊销 180 天。","p":"对。第一次检测不通过是 180 天。"},"vi":{"q":"Ở Nebraska, một người vi phạm lần đầu không qua được xét nghiệm nồng độ cồn sau khi bị bắt vì DUI (lái xe khi say rượu). Bằng lái bị thu hồi hành chính trong bao lâu?","o":["30 ngày","90 ngày","180 ngày","Hai năm"],"h1":"Khoảng nửa năm.","h2":"Ở Nebraska, người vi phạm lần đầu không qua được xét nghiệm nồng độ cồn sẽ bị thu hồi hành chính bằng lái trong 180 ngày.","p":"Đúng. Không qua xét nghiệm lần đầu là 180 ngày."},"tl":{"q":"Sa Nebraska, bumagsak sa alcohol test ang isang first-time offender matapos maaresto dahil sa DUI (pagmamaneho nang lasing). Gaano katagal ang administratibong pagbawi ng lisensya?","o":["30 araw","90 araw","180 araw","Dalawang taon"],"h1":"Mga kalahating taon ito.","h2":"Sa Nebraska, ang first-time offender na bumagsak sa alcohol test ay administratibong babawian ng lisensya nang 180 araw.","p":"Tama. 180 araw para sa unang bagsak na test."},"ar":{"q":"في Nebraska، شخص يخالف لأول مرة رسب في فحص الكحول بعد اعتقاله بسبب DUI (القيادة تحت تأثير الكحول). ما مدة السحب الإداري للرخصة؟","o":["30 يوماً","90 يوماً","180 يوماً","سنتان"],"h1":"حوالي نصف سنة.","h2":"في Nebraska، الشخص الذي يخالف لأول مرة ويرسب في فحص الكحول تُسحب رخصته إدارياً لمدة 180 يوماً.","p":"صحيح. الرسوب الأول في الفحص يعني 180 يوماً."},"ref":{"doc":"NE","page":20}},{"id":"ne-040","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a police officer takes your license because you failed or refused an alcohol test. How long is the temporary license you get valid?","o":["24 hours","15 days","30 days","60 days"],"h1":"It is about two weeks.","h2":"In Nebraska, after an officer takes your license for a failed or refused alcohol test, the temporary license expires 15 days after it is issued.","p":"Right. The temporary license lasts 15 days."},"es":{"q":"En Nebraska, un policía le quita la licencia porque usted no pasó o se negó a una prueba de alcohol. ¿Por cuánto tiempo es válida la licencia temporal que recibe?","o":["24 horas","15 días","30 días","60 días"],"h1":"Son unas dos semanas.","h2":"En Nebraska, después de que un policía le quita la licencia por no pasar o negarse a una prueba de alcohol, la licencia temporal vence 15 días después de emitida.","p":"Correcto. La licencia temporal dura 15 días."},"zh":{"q":"在 Nebraska，警察因为你酒精检测没通过或拒绝检测，拿走了你的驾照。你拿到的临时驾照有效期多久？","o":["24 小时","15 天","30 天","60 天"],"h1":"大约两个星期。","h2":"在 Nebraska，警察因为酒精检测没通过或拒绝检测拿走你的驾照后，临时驾照在发放 15 天后到期。","p":"对。临时驾照有效 15 天。"},"vi":{"q":"Ở Nebraska, cảnh sát lấy bằng lái của bạn vì bạn không qua hoặc từ chối xét nghiệm nồng độ cồn. Bằng lái tạm thời bạn nhận được có hiệu lực bao lâu?","o":["24 giờ","15 ngày","30 ngày","60 ngày"],"h1":"Khoảng hai tuần.","h2":"Ở Nebraska, sau khi cảnh sát lấy bằng lái của bạn vì không qua hoặc từ chối xét nghiệm nồng độ cồn, bằng lái tạm thời hết hạn 15 ngày sau khi được cấp.","p":"Đúng. Bằng lái tạm thời có hiệu lực 15 ngày."},"tl":{"q":"Sa Nebraska, kinuha ng pulis ang lisensya mo dahil bumagsak ka o tumanggi ka sa alcohol test. Gaano katagal may bisa ang pansamantalang lisensya na matatanggap mo?","o":["24 oras","15 araw","30 araw","60 araw"],"h1":"Mga dalawang linggo ito.","h2":"Sa Nebraska, matapos kunin ng pulis ang lisensya mo dahil bumagsak ka o tumanggi sa alcohol test, mapapaso ang pansamantalang lisensya 15 araw matapos itong ibigay.","p":"Tama. 15 araw ang bisa ng pansamantalang lisensya."},"ar":{"q":"في Nebraska، أخذ شرطي رخصتك لأنك رسبت في فحص الكحول أو رفضته. ما مدة صلاحية الرخصة المؤقتة التي تحصل عليها؟","o":["24 ساعة","15 يوماً","30 يوماً","60 يوماً"],"h1":"حوالي أسبوعين.","h2":"في Nebraska، بعد أن يأخذ الشرطي رخصتك بسبب الرسوب في فحص الكحول أو رفضه، تنتهي الرخصة المؤقتة بعد 15 يوماً من إصدارها.","p":"صحيح. الرخصة المؤقتة صالحة لمدة 15 يوماً."},"ref":{"doc":"NE","page":20}},{"id":"ne-041","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a driver under 21 is convicted of driving with a blood alcohol level of .02 or more. What does the court do with the license?","o":["Nothing, it is only a warning","Revokes it for one year","Suspends it for six months","Impounds it for 30 days"],"h1":"The court holds the license for about a month.","h2":"In Nebraska, for a driver under 21 convicted at .02, the court impounds the license for 30 days.","p":"Right. The court holds the license for 30 days."},"es":{"q":"En Nebraska, un conductor menor de 21 años es condenado por manejar con un nivel de alcohol en la sangre de .02 o más. ¿Qué hace el tribunal con la licencia?","o":["Nada, es solo una advertencia","La revoca por un año","La suspende por seis meses","La retiene por 30 días"],"h1":"El tribunal guarda la licencia por más o menos un mes.","h2":"En Nebraska, si un conductor menor de 21 años es condenado con .02, el tribunal retiene su licencia por 30 días.","p":"Correcto. El tribunal retiene la licencia por 30 días."},"zh":{"q":"在 Nebraska，一位 21 岁以下的司机因为血液酒精浓度 .02 或更高时开车被定罪。法院会怎样处理驾照？","o":["不处理，只是警告","吊销一年","暂停六个月","扣押 30 天"],"h1":"法院会把驾照扣留大约一个月。","h2":"在 Nebraska，21 岁以下的司机在 .02 被定罪后，法院会扣押驾照 30 天。","p":"对。法院扣押驾照 30 天。"},"vi":{"q":"Ở Nebraska, một tài xế dưới 21 tuổi bị kết tội lái xe với nồng độ cồn trong máu từ .02 trở lên. Tòa án làm gì với bằng lái?","o":["Không làm gì, chỉ là cảnh cáo","Thu hồi một năm","Đình chỉ sáu tháng","Tạm giữ 30 ngày"],"h1":"Tòa án giữ bằng lái khoảng một tháng.","h2":"Ở Nebraska, với tài xế dưới 21 tuổi bị kết tội ở mức .02, tòa án tạm giữ bằng lái 30 ngày.","p":"Đúng. Tòa án giữ bằng lái 30 ngày."},"tl":{"q":"Sa Nebraska, nahatulan ang isang drayber na wala pang 21 dahil nagmaneho na may antas ng alak sa dugo na .02 o higit pa. Ano ang gagawin ng korte sa lisensya?","o":["Wala, babala lang ito","Babawiin ito nang isang taon","Sususpindihin ito nang anim na buwan","Kukumpiskahin ito nang 30 araw"],"h1":"Hahawakan ng korte ang lisensya nang mga isang buwan.","h2":"Sa Nebraska, para sa drayber na wala pang 21 na nahatulan sa .02, kukumpiskahin ng korte ang lisensya nang 30 araw.","p":"Tama. Hahawakan ng korte ang lisensya nang 30 araw."},"ar":{"q":"في Nebraska، أُدين سائق عمره أقل من 21 سنة بالقيادة ونسبة الكحول في دمه .02 أو أكثر. ماذا تفعل المحكمة بالرخصة؟","o":["لا شيء، إنه مجرد تحذير","تسحبها لمدة سنة واحدة","توقفها لمدة ستة أشهر","تحجزها لمدة 30 يوماً"],"h1":"تحتفظ المحكمة بالرخصة لمدة شهر تقريباً.","h2":"في Nebraska، إذا أُدين سائق عمره أقل من 21 سنة بنسبة .02، تحجز المحكمة رخصته لمدة 30 يوماً.","p":"صحيح. تحتفظ المحكمة بالرخصة لمدة 30 يوماً."},"ref":{"doc":"NE","page":20}},{"id":"ne-042","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, until when must a young child ride in a rear-facing car seat?","o":["Until age 2, or until the seat's height or weight limit","Until age 6 months","Until age 4","Until age 8"],"h1":"Think of a toddler, not a baby or a school child.","h2":"In Nebraska, children ride rear-facing until age 2, or until they reach the height or weight limit set by the car seat maker.","p":"Right. Rear-facing until age 2 or the seat's limit."},"es":{"q":"En Nebraska, ¿hasta cuándo debe un niño pequeño ir en un asiento de seguridad mirando hacia atrás?","o":["Hasta los 2 años, o hasta el límite de altura o peso del asiento","Hasta los 6 meses","Hasta los 4 años","Hasta los 8 años"],"h1":"Piense en un niño que empieza a caminar, no en un bebé ni en un escolar.","h2":"En Nebraska, los niños van mirando hacia atrás hasta los 2 años, o hasta llegar al límite de altura o peso que fija el fabricante del asiento.","p":"Correcto. Mirando hacia atrás hasta los 2 años o el límite del asiento."},"zh":{"q":"在 Nebraska，小孩必须坐后向式汽车座椅到什么时候？","o":["到 2 岁，或到座椅的身高或体重上限","到 6 个月大","到 4 岁","到 8 岁"],"h1":"想想刚学走路的幼儿，不是婴儿，也不是上学的孩子。","h2":"在 Nebraska，孩子要坐后向式座椅到 2 岁，或到他们达到汽车座椅制造商规定的身高或体重上限。","p":"对。后向坐到 2 岁或座椅的上限。"},"vi":{"q":"Ở Nebraska, trẻ nhỏ phải ngồi ghế ô tô quay mặt về phía sau cho đến khi nào?","o":["Đến 2 tuổi, hoặc đến giới hạn chiều cao hay cân nặng của ghế","Đến 6 tháng tuổi","Đến 4 tuổi","Đến 8 tuổi"],"h1":"Hãy nghĩ đến trẻ mới biết đi, không phải em bé hay trẻ đi học.","h2":"Ở Nebraska, trẻ em ngồi quay mặt về phía sau đến 2 tuổi, hoặc đến khi đạt giới hạn chiều cao hay cân nặng do nhà sản xuất ghế ô tô quy định.","p":"Đúng. Quay mặt về phía sau đến 2 tuổi hoặc đến giới hạn của ghế."},"tl":{"q":"Sa Nebraska, hanggang kailan dapat nakasakay ang maliit na bata sa rear-facing na car seat (nakaharap sa likod)?","o":["Hanggang edad 2, o hanggang sa limitasyon ng taas o timbang ng upuan","Hanggang edad 6 na buwan","Hanggang edad 4","Hanggang edad 8"],"h1":"Isipin ang batang nagsisimulang maglakad, hindi sanggol o batang nag-aaral.","h2":"Sa Nebraska, nakaharap sa likod ang mga bata hanggang edad 2, o hanggang maabot nila ang limitasyon ng taas o timbang na itinakda ng gumawa ng car seat.","p":"Tama. Nakaharap sa likod hanggang edad 2 o hanggang sa limitasyon ng upuan."},"ar":{"q":"في Nebraska، حتى متى يجب أن يركب الطفل الصغير في مقعد سيارة موجّه إلى الخلف؟","o":["حتى عمر 2 سنة، أو حتى حد الطول أو الوزن للمقعد","حتى عمر 6 أشهر","حتى عمر 4 سنوات","حتى عمر 8 سنوات"],"h1":"فكّر في طفل يتعلّم المشي، وليس رضيعاً أو طفلاً في المدرسة.","h2":"في Nebraska يركب الأطفال في مقعد موجّه إلى الخلف حتى عمر 2 سنة، أو حتى يصلوا إلى حد الطول أو الوزن الذي حدّدته الشركة المصنّعة لمقعد السيارة.","p":"صحيح. موجّه إلى الخلف حتى عمر 2 سنة أو حتى حد المقعد."},"ref":{"doc":"NE","page":26}},{"id":"ne-043","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, your steering wheel has an air bag. How much space should you leave between yourself and the wheel?","o":["About 2 inches","About 5 inches","At least 10 inches","Exactly 24 inches"],"h1":"An air bag opens with great force, so give it room.","h2":"In Nebraska, a driver should leave at least 10 inches between themselves and a steering wheel with an air bag.","p":"Right. Keep at least 10 inches from the wheel."},"es":{"q":"En Nebraska, su volante tiene bolsa de aire. ¿Cuánto espacio debe dejar entre usted y el volante?","o":["Unas 2 pulgadas","Unas 5 pulgadas","Por lo menos 10 pulgadas","Exactamente 24 pulgadas"],"h1":"La bolsa de aire se abre con mucha fuerza, así que déjele espacio.","h2":"En Nebraska, el conductor debe dejar por lo menos 10 pulgadas entre su cuerpo y un volante con bolsa de aire.","p":"Correcto. Manténgase por lo menos a 10 pulgadas del volante."},"zh":{"q":"在 Nebraska，你的方向盘里有安全气囊。你和方向盘之间应该留多少距离？","o":["大约 2 英寸","大约 5 英寸","至少 10 英寸","正好 24 英寸"],"h1":"安全气囊打开时力量很大，所以要给它留空间。","h2":"在 Nebraska，司机和有安全气囊的方向盘之间应该至少留 10 英寸。","p":"对。离方向盘至少 10 英寸。"},"vi":{"q":"Ở Nebraska, vô lăng của bạn có túi khí. Bạn nên để khoảng cách bao nhiêu giữa bạn và vô lăng?","o":["Khoảng 2 inch","Khoảng 5 inch","Ít nhất 10 inch","Đúng 24 inch"],"h1":"Túi khí bung ra rất mạnh, nên hãy chừa chỗ cho nó.","h2":"Ở Nebraska, tài xế nên để ít nhất 10 inch giữa mình và vô lăng có túi khí.","p":"Đúng. Ngồi cách vô lăng ít nhất 10 inch."},"tl":{"q":"Sa Nebraska, may air bag ang manibela mo. Gaano kalaking espasyo ang dapat mong iwan sa pagitan mo at ng manibela?","o":["Mga 2 inches","Mga 5 inches","Hindi bababa sa 10 inches","Eksaktong 24 inches"],"h1":"Bumubukas ang air bag nang napakalakas, kaya bigyan ito ng espasyo.","h2":"Sa Nebraska, dapat mag-iwan ang drayber ng hindi bababa sa 10 inches sa pagitan niya at ng manibelang may air bag.","p":"Tama. Lumayo nang hindi bababa sa 10 inches sa manibela."},"ar":{"q":"في Nebraska، في مقود سيارتك وسادة هوائية. ما المسافة التي يجب أن تتركها بينك وبين المقود؟","o":["حوالي 2 بوصة","حوالي 5 بوصات","10 بوصات على الأقل","24 بوصة بالضبط"],"h1":"الوسادة الهوائية تنفتح بقوة كبيرة، فاترك لها مساحة.","h2":"في Nebraska يجب أن يترك السائق 10 بوصات على الأقل بينه وبين مقود فيه وسادة هوائية.","p":"صحيح. ابقَ على بعد 10 بوصات على الأقل من المقود."},"ref":{"doc":"NE","page":26}},{"id":"ne-044","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a deer jumps onto the road and you are about to hit it. What is the safest thing to do?","o":["Swerve hard into the other lane","Brake firmly, keep control, and do not swerve","Speed up to get past it","Steer off the road into the ditch"],"h1":"Nebraska says: Don't veer for deer.","h2":"In Nebraska, if you are about to hit a deer, the safest action is to brake firmly, steer to keep control and stop, instead of swerving.","p":"Right. Brake, keep control, and don't veer."},"es":{"q":"En Nebraska, un venado salta a la carretera y está a punto de chocarlo. ¿Qué es lo más seguro?","o":["Desviarse con fuerza al otro carril","Frenar con firmeza, mantener el control y no desviarse","Acelerar para pasarlo","Salirse de la carretera hacia la cuneta"],"h1":"Nebraska dice: no se desvíe por un venado.","h2":"En Nebraska, si está a punto de chocar con un venado, lo más seguro es frenar con firmeza, mantener el control y detenerse, en vez de desviarse.","p":"Correcto. Frene, mantenga el control y no se desvíe."},"zh":{"q":"在 Nebraska，一只鹿跳到路上，你快要撞到它了。最安全的做法是什么？","o":["猛打方向盘冲到另一条车道","用力刹车，保持控制，不要急转","加速开过去","把车开出路面，开进路边沟里"],"h1":"Nebraska 说：“Don't veer for deer”（不要为了鹿急转弯）。","h2":"在 Nebraska，如果你快要撞到鹿，最安全的做法是用力刹车，控制好方向并停下来，而不是急转弯。","p":"对。刹车，保持控制，不要急转。"},"vi":{"q":"Ở Nebraska, một con nai nhảy ra đường và bạn sắp đâm vào nó. Điều an toàn nhất nên làm là gì?","o":["Đánh lái gấp sang làn khác","Phanh mạnh, giữ vững tay lái, và không đánh lái gấp","Tăng tốc để vượt qua nó","Lái ra khỏi đường xuống mương"],"h1":"Nebraska nói: “Don't veer for deer” (Đừng đánh lái tránh nai).","h2":"Ở Nebraska, nếu bạn sắp đâm vào một con nai, cách an toàn nhất là phanh mạnh, giữ vững tay lái và dừng lại, thay vì đánh lái gấp.","p":"Đúng. Phanh, giữ vững tay lái, và đừng đánh lái tránh."},"tl":{"q":"Sa Nebraska, may usang tumalon sa daan at mababangga mo na ito. Ano ang pinakaligtas na gawin?","o":["Biglang lumiko nang malakas papunta sa kabilang lane","Magpreno nang mariin, panatilihin ang kontrol, at huwag biglang lumiko","Bumilis para malampasan ito","Lumabas sa daan papunta sa kanal"],"h1":"Sabi ng Nebraska: “Don't veer for deer” (Huwag biglang lumiko dahil sa usa).","h2":"Sa Nebraska, kung mababangga mo na ang usa, ang pinakaligtas na gawin ay magpreno nang mariin, panatilihin ang kontrol at huminto, sa halip na biglang lumiko.","p":"Tama. Magpreno, panatilihin ang kontrol, at huwag biglang lumiko."},"ar":{"q":"في Nebraska، قفز أيّل (deer) إلى الطريق وأنت على وشك أن تصدمه. ما أكثر شيء آمن تفعله؟","o":["انحرف بقوة إلى الحارة الأخرى","اضغط على الفرامل بقوة، وحافظ على السيطرة، ولا تنحرف","زِد السرعة لتتجاوزه","اخرج من الطريق إلى الخندق"],"h1":"تقول Nebraska: “Don't veer for deer” (لا تنحرف من أجل الأيّل).","h2":"في Nebraska، إذا كنت على وشك أن تصدم أيّلاً، فأكثر شيء آمن هو أن تضغط على الفرامل بقوة، وتوجّه السيارة لتحافظ على السيطرة وتتوقف، بدلاً من أن تنحرف.","p":"صحيح. اضغط على الفرامل، وحافظ على السيطرة، ولا تنحرف."},"ref":{"doc":"NE","page":26}},{"id":"ne-045","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, when is it legal to use studded tires?","o":["Any time of year","Only in January and February","From October 1 to May 1","From November 1 to April 1"],"h1":"It covers the snowy months, from late fall to early spring.","h2":"In Nebraska, studded tires are legal only from November 1 to April 1.","p":"Right. Studded tires: November 1 to April 1."},"es":{"q":"En Nebraska, ¿cuándo es legal usar llantas con clavos?","o":["En cualquier época del año","Solo en enero y febrero","Del 1 de octubre al 1 de mayo","Del 1 de noviembre al 1 de abril"],"h1":"Cubre los meses de nieve, de fines de otoño a principios de primavera.","h2":"En Nebraska, las llantas con clavos son legales solo del 1 de noviembre al 1 de abril.","p":"Correcto. Llantas con clavos: del 1 de noviembre al 1 de abril."},"zh":{"q":"在 Nebraska，什么时候可以合法使用带钉轮胎？","o":["一年中任何时候","只在一月和二月","从 10 月 1 日到 5 月 1 日","从 11 月 1 日到 4 月 1 日"],"h1":"它包括下雪的月份，从深秋到初春。","h2":"在 Nebraska，带钉轮胎只在 11 月 1 日到 4 月 1 日之间合法。","p":"对。带钉轮胎：11 月 1 日到 4 月 1 日。"},"vi":{"q":"Ở Nebraska, khi nào được phép dùng lốp xe có đinh?","o":["Bất cứ lúc nào trong năm","Chỉ trong tháng Một và tháng Hai","Từ 1 tháng 10 đến 1 tháng 5","Từ 1 tháng 11 đến 1 tháng 4"],"h1":"Đó là những tháng có tuyết, từ cuối mùa thu đến đầu mùa xuân.","h2":"Ở Nebraska, lốp xe có đinh chỉ hợp pháp từ 1 tháng 11 đến 1 tháng 4.","p":"Đúng. Lốp có đinh: từ 1 tháng 11 đến 1 tháng 4."},"tl":{"q":"Sa Nebraska, kailan legal ang paggamit ng studded tires (gulong na may pako)?","o":["Kahit kailan sa buong taon","Sa Enero at Pebrero lang","Mula Oktubre 1 hanggang Mayo 1","Mula Nobyembre 1 hanggang Abril 1"],"h1":"Saklaw nito ang mga buwang may niyebe, mula huling bahagi ng taglagas hanggang simula ng tagsibol.","h2":"Sa Nebraska, legal lang ang studded tires mula Nobyembre 1 hanggang Abril 1.","p":"Tama. Studded tires: Nobyembre 1 hanggang Abril 1."},"ar":{"q":"في Nebraska، متى يكون استخدام الإطارات المسمارية (studded tires) قانونياً؟","o":["في أي وقت من السنة","في يناير وفبراير فقط","من 1 أكتوبر إلى 1 مايو","من 1 نوفمبر إلى 1 أبريل"],"h1":"يشمل الأشهر الثلجية، من أواخر الخريف إلى أوائل الربيع.","h2":"في Nebraska تكون الإطارات المسمارية قانونية فقط من 1 نوفمبر إلى 1 أبريل.","p":"صحيح. الإطارات المسمارية: من 1 نوفمبر إلى 1 أبريل."},"ref":{"doc":"NE","page":63}},{"id":"ne-046","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the minimum speed on the interstate?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"It is well below the usual interstate limit, but not very slow.","h2":"In Nebraska, the minimum speed on the interstate is 40 mph.","p":"Right. Do not drive under 40 mph on the interstate."},"es":{"q":"En Nebraska, ¿cuál es la velocidad mínima en la autopista interestatal?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"Está muy por debajo del límite normal de la interestatal, pero no es muy lenta.","h2":"En Nebraska, la velocidad mínima en la autopista interestatal es de 40 mph.","p":"Correcto. No maneje a menos de 40 mph en la interestatal."},"zh":{"q":"在 Nebraska，州际公路上的最低速度是多少？","o":["40 英里/小时","30 英里/小时","45 英里/小时","55 英里/小时"],"h1":"它比州际公路平常的限速低很多，但也不算很慢。","h2":"在 Nebraska，州际公路上的最低速度是 40 英里/小时。","p":"对。在州际公路上不要开得低于 40 英里/小时。"},"vi":{"q":"Ở Nebraska, tốc độ tối thiểu trên xa lộ liên bang là bao nhiêu?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"Thấp hơn nhiều so với tốc độ tối đa thông thường trên xa lộ liên bang, nhưng không quá chậm.","h2":"Ở Nebraska, tốc độ tối thiểu trên xa lộ liên bang là 40 mph.","p":"Đúng. Đừng lái dưới 40 mph trên xa lộ liên bang."},"tl":{"q":"Sa Nebraska, ano ang minimum na bilis sa interstate?","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"Mas mababa ito nang malaki sa karaniwang speed limit sa interstate, pero hindi masyadong mabagal.","h2":"Sa Nebraska, ang minimum na bilis sa interstate ay 40 mph.","p":"Tama. Huwag magmaneho nang mas mabagal sa 40 mph sa interstate."},"ar":{"q":"في Nebraska، ما الحد الأدنى للسرعة على الطريق السريع بين الولايات (interstate)؟","o":["40 mph","30 mph","45 mph","55 mph"],"h1":"إنه أقل بكثير من حد السرعة المعتاد على الطريق السريع بين الولايات، لكنه ليس بطيئاً جداً.","h2":"في Nebraska الحد الأدنى للسرعة على الطريق السريع بين الولايات هو 40 mph.","p":"صحيح. يجب ألّا تقود بأقل من 40 mph على الطريق السريع بين الولايات."},"ref":{"doc":"NE","page":60}},{"id":"ne-047","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, what is the speed limit on a gravel road when no sign says otherwise?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"It is 5 mph lower than on a paved road off the state highway system.","h2":"In Nebraska, the speed limit on a gravel road is 50 mph unless a sign shows a different limit.","p":"Right. Gravel roads: 50 mph unless posted."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad en un camino de grava cuando ninguna señal indica otro?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"Es 5 mph menos que en un camino pavimentado fuera del sistema de carreteras estatales.","h2":"En Nebraska, el límite de velocidad en un camino de grava es de 50 mph, a menos que una señal indique otro límite.","p":"Correcto. Caminos de grava: 50 mph si no hay señal."},"zh":{"q":"在 Nebraska，没有标志另外规定时，碎石路上的限速是多少？","o":["35 英里/小时","45 英里/小时","50 英里/小时","55 英里/小时"],"h1":"它比州公路系统以外的铺面道路低 5 英里/小时。","h2":"在 Nebraska，碎石路的限速是 50 英里/小时，除非有标志显示不同的限速。","p":"对。碎石路：50 英里/小时，除非有标志另外规定。"},"vi":{"q":"Ở Nebraska, tốc độ tối đa trên đường sỏi là bao nhiêu khi không có biển báo khác?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"Thấp hơn 5 mph so với đường trải nhựa không thuộc hệ thống xa lộ của tiểu bang.","h2":"Ở Nebraska, tốc độ tối đa trên đường sỏi là 50 mph, trừ khi có biển báo ghi tốc độ khác.","p":"Đúng. Đường sỏi: 50 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Nebraska, ano ang speed limit sa daang graba kapag walang karatulang nagsasabi ng iba?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa sementadong daan na wala sa state highway system.","h2":"Sa Nebraska, ang speed limit sa daang graba ay 50 mph maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. Daang graba: 50 mph maliban kung may karatula."},"ar":{"q":"في Nebraska، ما حد السرعة على طريق حصوي عندما لا توجد لافتة تقول غير ذلك؟","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"إنه أقل بـ 5 mph من الطريق المعبّد الذي ليس ضمن شبكة طرق الولاية السريعة.","h2":"في Nebraska حد السرعة على الطريق الحصوي هو 50 mph إلا إذا أظهرت لافتة حداً مختلفاً.","p":"صحيح. الطرق الحصوية: 50 mph ما لم تكن هناك لافتة."},"ref":{"doc":"NE","page":52}},{"id":"ne-048","scope":"NE","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nebraska, a school bus ahead turns on its flashing amber (yellow) lights. What should you do?","o":["Pass it quickly before it stops","Slow to 25 mph and get ready to stop","Keep your speed; the lights are only for the bus driver","Honk so the children know you are coming"],"h1":"Amber lights mean the bus is about to stop for children.","h2":"In Nebraska, when a school bus shows its amber warning lights, you must slow to 25 mph and get ready to stop.","p":"Right. Slow to 25 mph and be ready to stop."},"es":{"q":"En Nebraska, un autobús escolar delante de usted enciende sus luces ámbar (amarillas) intermitentes. ¿Qué debe hacer?","o":["Rebasarlo rápido antes de que se detenga","Bajar a 25 mph y prepararse para detenerse","Mantener su velocidad; las luces son solo para el conductor del autobús","Tocar la bocina para que los niños sepan que viene"],"h1":"Las luces ámbar indican que el autobús está por detenerse para los niños.","h2":"En Nebraska, cuando un autobús escolar enciende sus luces ámbar de advertencia, debe bajar a 25 mph y prepararse para detenerse.","p":"Correcto. Baje a 25 mph y prepárese para detenerse."},"zh":{"q":"在 Nebraska，前面的校车打开了闪烁的琥珀色（黄色）灯。你应该怎么做？","o":["在它停下前快速超过它","减速到 25 英里/小时，准备停车","保持车速；这些灯只是给校车司机看的","按喇叭让孩子们知道你来了"],"h1":"琥珀色灯表示校车马上要停下来接送孩子。","h2":"在 Nebraska，校车亮起琥珀色警示灯时，你必须减速到 25 英里/小时，并准备停车。","p":"对。减速到 25 英里/小时，准备停车。"},"vi":{"q":"Ở Nebraska, xe buýt trường học phía trước bật đèn nhấp nháy màu hổ phách (vàng). Bạn nên làm gì?","o":["Vượt qua nhanh trước khi nó dừng","Giảm xuống 25 mph và sẵn sàng dừng lại","Giữ nguyên tốc độ; đèn chỉ dành cho tài xế xe buýt","Bấm còi để trẻ em biết bạn đang đến"],"h1":"Đèn màu hổ phách có nghĩa là xe buýt sắp dừng để đón hoặc trả trẻ em.","h2":"Ở Nebraska, khi xe buýt trường học bật đèn cảnh báo màu hổ phách, bạn phải giảm xuống 25 mph và sẵn sàng dừng lại.","p":"Đúng. Giảm xuống 25 mph và sẵn sàng dừng lại."},"tl":{"q":"Sa Nebraska, binuksan ng school bus sa unahan ang kumikislap na amber (dilaw) na ilaw nito. Ano ang dapat mong gawin?","o":["Lampasan ito agad bago ito huminto","Bumagal sa 25 mph at maghandang huminto","Panatilihin ang bilis mo; para lang sa drayber ng bus ang mga ilaw","Bumusina para malaman ng mga bata na parating ka"],"h1":"Ang amber na ilaw ay nangangahulugang malapit nang huminto ang bus para sa mga bata.","h2":"Sa Nebraska, kapag binuksan ng school bus ang amber na babalang ilaw nito, dapat kang bumagal sa 25 mph at maghandang huminto.","p":"Tama. Bumagal sa 25 mph at maghandang huminto."},"ar":{"q":"في Nebraska، شغّلت حافلة مدرسية أمامك أضواءها الكهرمانية (الصفراء) الوامضة. ماذا يجب أن تفعل؟","o":["تجاوزها بسرعة قبل أن تتوقف","خفّف السرعة إلى 25 mph واستعدّ للتوقف","حافظ على سرعتك؛ الأضواء لسائق الحافلة فقط","اضغط على البوق ليعرف الأطفال أنك قادم"],"h1":"الأضواء الكهرمانية تعني أن الحافلة على وشك أن تتوقف من أجل الأطفال.","h2":"في Nebraska، عندما تُظهر الحافلة المدرسية أضواء التحذير الكهرمانية، يجب أن تخفّف السرعة إلى 25 mph وتستعدّ للتوقف.","p":"صحيح. خفّف السرعة إلى 25 mph واستعدّ للتوقف."},"ref":{"doc":"NE","page":70}},{"id":"ne-049","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, a fire truck is going to an emergency. How close behind it may you follow?","o":["100 feet","200 feet","300 feet","No closer than 500 feet"],"h1":"It is more than the length of a football field.","h2":"In Nebraska, you may not follow a fire truck on an emergency call closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck."},"es":{"q":"En Nebraska, un camión de bomberos va a una emergencia. ¿A qué distancia detrás de él puede seguirlo?","o":["100 pies","200 pies","300 pies","No más cerca de 500 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Nebraska, no puede seguir a un camión de bomberos que va a una emergencia a menos de 500 pies.","p":"Correcto. Manténgase por lo menos a 500 pies de un camión de bomberos."},"zh":{"q":"在 Nebraska，一辆消防车正赶往紧急情况。你最近可以跟在它后面多近？","o":["100 英尺","200 英尺","300 英尺","不能近于 500 英尺"],"h1":"比一个橄榄球场的长度还长。","h2":"在 Nebraska，跟随执行紧急任务的消防车时，距离不能少于 500 英尺。","p":"对。在消防车后面至少保持 500 英尺。"},"vi":{"q":"Ở Nebraska, một xe cứu hỏa đang đi đến chỗ khẩn cấp. Bạn được chạy theo sau nó gần nhất là bao nhiêu?","o":["100 feet","200 feet","300 feet","Không gần hơn 500 feet"],"h1":"Dài hơn chiều dài một sân bóng bầu dục.","h2":"Ở Nebraska, bạn không được chạy theo xe cứu hỏa đang đi làm nhiệm vụ khẩn cấp ở khoảng cách gần hơn 500 feet.","p":"Đúng. Giữ khoảng cách ít nhất 500 feet phía sau xe cứu hỏa."},"tl":{"q":"Sa Nebraska, papunta sa emergency ang isang trak ng bumbero. Gaano kalapit ka puwedeng sumunod sa likod nito?","o":["100 feet","200 feet","300 feet","Hindi mas malapit sa 500 feet"],"h1":"Mas mahaba ito kaysa sa haba ng isang football field.","h2":"Sa Nebraska, hindi ka puwedeng sumunod sa trak ng bumbero na papunta sa emergency nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng trak ng bumbero."},"ar":{"q":"في Nebraska، شاحنة إطفاء ذاهبة إلى حالة طارئة. ما أقرب مسافة يجوز أن تسير بها خلفها؟","o":["100 قدم","200 قدم","300 قدم","ليس أقرب من 500 قدم"],"h1":"إنها أطول من طول ملعب كرة القدم الأمريكية.","h2":"في Nebraska، لا يجوز أن تسير خلف شاحنة إطفاء في مهمة طارئة على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل خلف شاحنة الإطفاء."},"ref":{"doc":"NE","page":52}},{"id":"ne-050","scope":"NE","cat":"signals","sign":null,"c":0,"en":{"q":"In Nebraska, which vehicles must show the slow-moving vehicle emblem on a public road?","o":["Vehicles that travel 25 mph or less","Vehicles that travel 35 mph or less","Vehicles that travel 45 mph or less","Any vehicle pulling a trailer"],"h1":"Think of farm equipment, which moves very slowly.","h2":"In Nebraska, vehicles that travel 25 mph or less, such as farm equipment, must show the slow-moving vehicle emblem on a public road.","p":"Right. The emblem is for vehicles at 25 mph or less."},"es":{"q":"En Nebraska, ¿qué vehículos deben mostrar el emblema de vehículo lento en una vía pública?","o":["Los vehículos que andan a 25 mph o menos","Los vehículos que andan a 35 mph o menos","Los vehículos que andan a 45 mph o menos","Cualquier vehículo que jala un remolque"],"h1":"Piense en la maquinaria agrícola, que avanza muy despacio.","h2":"En Nebraska, los vehículos que andan a 25 mph o menos, como la maquinaria agrícola, deben mostrar el emblema de vehículo lento en una vía pública.","p":"Correcto. El emblema es para vehículos a 25 mph o menos."},"zh":{"q":"在 Nebraska，哪些车辆在公共道路上必须挂慢速车辆标志？","o":["速度在 25 英里/小时或以下的车辆","速度在 35 英里/小时或以下的车辆","速度在 45 英里/小时或以下的车辆","任何拖着拖车的车辆"],"h1":"想想农用机械，它们开得很慢。","h2":"在 Nebraska，速度在 25 英里/小时或以下的车辆，比如农用机械，在公共道路上必须挂慢速车辆标志。","p":"对。这个标志是给速度在 25 英里/小时或以下的车辆的。"},"vi":{"q":"Ở Nebraska, những xe nào phải gắn biểu tượng xe chạy chậm khi đi trên đường công cộng?","o":["Xe chạy 25 mph trở xuống","Xe chạy 35 mph trở xuống","Xe chạy 45 mph trở xuống","Bất kỳ xe nào kéo rơ-moóc"],"h1":"Hãy nghĩ đến máy móc nông trại, loại chạy rất chậm.","h2":"Ở Nebraska, xe chạy 25 mph trở xuống, như máy móc nông trại, phải gắn biểu tượng xe chạy chậm khi đi trên đường công cộng.","p":"Đúng. Biểu tượng này dành cho xe chạy 25 mph trở xuống."},"tl":{"q":"Sa Nebraska, aling mga sasakyan ang dapat magpakita ng slow-moving vehicle emblem (tanda ng mabagal na sasakyan) sa pampublikong daan?","o":["Mga sasakyang tumatakbo nang 25 mph o mas mabagal","Mga sasakyang tumatakbo nang 35 mph o mas mabagal","Mga sasakyang tumatakbo nang 45 mph o mas mabagal","Anumang sasakyang may hilang trailer"],"h1":"Isipin ang mga makinarya sa bukid, na napakabagal tumakbo.","h2":"Sa Nebraska, ang mga sasakyang tumatakbo nang 25 mph o mas mabagal, tulad ng makinarya sa bukid, ay dapat magpakita ng slow-moving vehicle emblem sa pampublikong daan.","p":"Tama. Para sa mga sasakyang 25 mph o mas mabagal ang emblem."},"ar":{"q":"في Nebraska، ما المركبات التي يجب أن تعرض شارة المركبة البطيئة على الطريق العام؟","o":["المركبات التي تسير بسرعة 25 mph أو أقل","المركبات التي تسير بسرعة 35 mph أو أقل","المركبات التي تسير بسرعة 45 mph أو أقل","أي مركبة تسحب مقطورة"],"h1":"فكّر في الآلات الزراعية، التي تسير ببطء شديد.","h2":"في Nebraska، المركبات التي تسير بسرعة 25 mph أو أقل، مثل الآلات الزراعية، يجب أن تعرض شارة المركبة البطيئة على الطريق العام.","p":"صحيح. الشارة للمركبات التي تسير بسرعة 25 mph أو أقل."},"ref":{"doc":"NE","page":42}},{"id":"ne-051","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how long is a school learner's permit (LPE) valid?","o":["30 days","Three months","Six months","Two years"],"h1":"It is shorter than the one-year LPD.","h2":"In Nebraska, a school learner's permit (LPE) expires six months after it is issued.","p":"Right. An LPE is good for six months."},"es":{"q":"En Nebraska, ¿por cuánto tiempo es válido el permiso escolar de aprendiz (LPE)?","o":["30 días","Tres meses","Seis meses","Dos años"],"h1":"Es más corto que el LPD, que dura un año.","h2":"En Nebraska, el permiso escolar de aprendiz (LPE) vence seis meses después de emitido.","p":"Correcto. El LPE es válido por seis meses."},"ref":{"doc":"NE","page":2}},{"id":"ne-052","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, what is the youngest age to get a School Permit (SCP)?","o":["14 years and two months","13 years","15 years and six months","16 years"],"h1":"It is a little older than the youngest age for the LPE.","h2":"In Nebraska, you must be at least 14 years and two months old to get a School Permit (SCP).","p":"Right. The SCP starts at 14 years and two months."},"es":{"q":"En Nebraska, ¿cuál es la edad mínima para obtener el permiso escolar (SCP)?","o":["14 años y dos meses","13 años","15 años y seis meses","16 años"],"h1":"Es un poco más que la edad mínima para el LPE.","h2":"En Nebraska, usted debe tener por lo menos 14 años y dos meses para obtener el permiso escolar (SCP).","p":"Correcto. El SCP empieza a los 14 años y dos meses."},"ref":{"doc":"NE","page":2}},{"id":"ne-053","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, when does a School Permit (SCP) expire?","o":["On the 15th birthday","One year after it is issued","On the 18th birthday","At age 16 years and three months"],"h1":"It ends a few months after the 16th birthday.","h2":"In Nebraska, a School Permit (SCP) expires when the holder is 16 years and three months old.","p":"Right. The SCP ends at 16 years and three months."},"es":{"q":"En Nebraska, ¿cuándo vence el permiso escolar (SCP)?","o":["Al cumplir 15 años","Un año después de emitido","Al cumplir 18 años","A los 16 años y tres meses"],"h1":"Termina unos meses después de cumplir 16 años.","h2":"En Nebraska, el permiso escolar (SCP) vence cuando el titular tiene 16 años y tres meses.","p":"Correcto. El SCP vence a los 16 años y tres meses."},"ref":{"doc":"NE","page":3}},{"id":"ne-054","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a teen with a School Permit (SCP) drives alone to school. Who may ride along?","o":["Any friends from school","Only family members who live with the teen","No one at all","One passenger of any age"],"h1":"Think of the people in the teen's own home.","h2":"In Nebraska, a School Permit holder driving to school may only carry family members who live with them.","p":"Right. Only family members who live with the teen may ride."},"es":{"q":"En Nebraska, un adolescente con permiso escolar (SCP) maneja solo a la escuela. ¿Quién puede ir con él?","o":["Cualquier amigo de la escuela","Solo familiares que viven con el adolescente","Nadie","Un pasajero de cualquier edad"],"h1":"Piense en las personas de la propia casa del adolescente.","h2":"En Nebraska, quien tiene permiso escolar y maneja a la escuela solo puede llevar a familiares que viven con él.","p":"Correcto. Solo pueden ir familiares que viven con el adolescente."},"ref":{"doc":"NE","page":1}},{"id":"ne-055","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, of the 50 hours of supervised driving on the certification form, how many must be between sunset and sunrise?","o":["None","At least 5 hours","At least 10 hours","At least 25 hours"],"h1":"It is one fifth of the total.","h2":"In Nebraska, the 50-hour certification form must show at least 10 hours of driving between sunset and sunrise.","p":"Right. At least 10 of the 50 hours must be at night."},"es":{"q":"En Nebraska, de las 50 horas de manejo supervisado del formulario, ¿cuántas deben ser entre la puesta y la salida del sol?","o":["Ninguna","Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total.","h2":"En Nebraska, el formulario de 50 horas debe mostrar por lo menos 10 horas de manejo entre la puesta y la salida del sol.","p":"Correcto. Por lo menos 10 de las 50 horas deben ser de noche."},"ref":{"doc":"NE","page":4}},{"id":"ne-056","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, how early may you apply for a learner's permit (LPD)?","o":["60 days before your 15th birthday","One year before your 15th birthday","Only after your 16th birthday","Any time after age 13"],"h1":"You may apply a short time early, but it is issued only on or after the birthday.","h2":"In Nebraska, you may apply for an LPD 60 days before your 15th birthday, but it is issued on or after that birthday.","p":"Right. You may apply 60 days before turning 15."},"es":{"q":"En Nebraska, ¿con cuánta anticipación puede solicitar el permiso de aprendiz (LPD)?","o":["60 días antes de cumplir 15 años","Un año antes de cumplir 15 años","Solo después de cumplir 16 años","En cualquier momento después de los 13 años"],"h1":"Puede solicitarlo un poco antes, pero se emite solo en o después del cumpleaños.","h2":"En Nebraska, puede solicitar el LPD 60 días antes de cumplir 15 años, pero se emite en esa fecha o después.","p":"Correcto. Puede solicitarlo 60 días antes de cumplir 15."},"ref":{"doc":"NE","page":3}},{"id":"ne-057","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a teen wants a provisional operator's permit (POP). What must be true about points in the six months before applying?","o":["No limit on points","Fewer than 12 points","Fewer than 6 points","Fewer than 3 points"],"h1":"Even a few points can stop the POP.","h2":"In Nebraska, a teen must have fewer than 3 points in the six months before applying for a POP.","p":"Right. Three or more points in those six months blocks the POP."},"es":{"q":"En Nebraska, un adolescente quiere el permiso provisional de operador (POP). ¿Qué debe cumplir sobre los puntos en los seis meses antes de solicitarlo?","o":["No hay límite de puntos","Menos de 12 puntos","Menos de 6 puntos","Menos de 3 puntos"],"h1":"Incluso unos pocos puntos pueden impedir el POP.","h2":"En Nebraska, un adolescente debe tener menos de 3 puntos en los seis meses antes de solicitar el POP.","p":"Correcto. Tres puntos o más en esos seis meses impiden el POP."},"ref":{"doc":"NE","page":4}},{"id":"ne-058","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a POP holder drives alone at 2 a.m. just for fun and is caught. What goes on the driving record?","o":["Nothing, only a warning","One point","Six points","The license is revoked at once"],"h1":"It is the smallest point penalty.","h2":"In Nebraska, breaking the POP night driving rule adds one point to the driving record.","p":"Right. A night driving violation is one point."},"es":{"q":"En Nebraska, quien tiene POP maneja solo a las 2 a.m. solo por diversión y lo detienen. ¿Qué se anota en su historial?","o":["Nada, solo una advertencia","Un punto","Seis puntos","Le revocan la licencia de inmediato"],"h1":"Es la sanción de puntos más pequeña.","h2":"En Nebraska, violar la regla de manejo nocturno del POP agrega un punto al historial de manejo.","p":"Correcto. Una violación del horario nocturno es un punto."},"ref":{"doc":"NE","page":1}},{"id":"ne-059","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a teen with a permit or POP uses a phone while the car is moving. What is the fine for a first offense?","o":["$25","$75","$200","$1,000"],"h1":"It is more than a seat belt ticket.","h2":"In Nebraska, a permit or POP holder who uses a wireless device while driving faces a $200 fine for a first offense, plus points.","p":"Right. The first offense is a $200 fine."},"es":{"q":"En Nebraska, un adolescente con permiso o POP usa el teléfono mientras el carro está en movimiento. ¿Cuál es la multa la primera vez?","o":["$25","$75","$200","$1,000"],"h1":"Es más que una multa por no usar el cinturón.","h2":"En Nebraska, quien tiene permiso o POP y usa un aparato inalámbrico mientras maneja recibe una multa de $200 la primera vez, más puntos.","p":"Correcto. La primera vez la multa es de $200."},"ref":{"doc":"NE","page":1}},{"id":"ne-060","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, may a 15-year-old ride in the open cargo bed of a pickup truck on the road?","o":["No, riders under 18 may not ride in cargo areas","Yes, if the truck goes under 25 mph","Yes, if an adult rides along in the back","Yes, outside city limits"],"h1":"The age limit for this rule is 18.","h2":"In Nebraska, children under 18 may not ride in the cargo area of a vehicle.","p":"Right. No one under 18 may ride in a cargo area."},"es":{"q":"En Nebraska, ¿puede un joven de 15 años ir en la caja abierta de una camioneta pickup en la carretera?","o":["No, los menores de 18 no pueden ir en áreas de carga","Sí, si la camioneta va a menos de 25 mph","Sí, si un adulto va atrás con él","Sí, fuera de la ciudad"],"h1":"El límite de edad de esta regla es 18 años.","h2":"En Nebraska, los menores de 18 años no pueden ir en el área de carga de un vehículo.","p":"Correcto. Nadie menor de 18 puede ir en un área de carga."},"ref":{"doc":"NE","page":26}},{"id":"ne-061","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, you are driving a 6-year-old in a car seat. The back seat has a free seat with a belt. Where must the child ride?","o":["In the front seat, next to the driver","Wherever the child wants","In the front if the air bag is on","In the back seat, not the front"],"h1":"The law keeps young children out of one seat when another is free.","h2":"In Nebraska, a child under 8 must ride in a seat other than the front seat when a back seat with a belt is free.","p":"Right. A child under 8 rides in the back when a seat is free there."},"es":{"q":"En Nebraska, usted lleva a un niño de 6 años en un asiento de seguridad. Hay un asiento libre con cinturón atrás. ¿Dónde debe ir el niño?","o":["En el asiento delantero, junto al conductor","Donde el niño quiera","Adelante si la bolsa de aire está activada","En el asiento de atrás, no adelante"],"h1":"La ley mantiene a los niños pequeños fuera de un asiento cuando hay otro libre.","h2":"En Nebraska, un niño menor de 8 años debe ir en un asiento que no sea el delantero cuando hay un asiento libre con cinturón atrás.","p":"Correcto. Un niño menor de 8 va atrás cuando hay lugar."},"ref":{"doc":"NE","page":26}},{"id":"ne-062","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, what is the fine for a driver or front-seat passenger who does not wear a seat belt?","o":["$10","$25 plus court costs","$150 plus court costs","$500"],"h1":"It is a small fine, but court costs are added.","h2":"In Nebraska, not wearing a seat belt in the front seat brings a $25 fine plus court costs.","p":"Right. The fine is $25 plus court costs."},"es":{"q":"En Nebraska, ¿cuál es la multa para el conductor o el pasajero delantero que no usa el cinturón de seguridad?","o":["$10","$25 más costos judiciales","$150 más costos judiciales","$500"],"h1":"Es una multa pequeña, pero se suman costos judiciales.","h2":"En Nebraska, no usar el cinturón en el asiento delantero tiene una multa de $25 más costos judiciales.","p":"Correcto. La multa es de $25 más costos judiciales."},"ref":{"doc":"NE","page":26}},{"id":"ne-063","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a vehicle with a weight rating over how many pounds needs a commercial driver's license (CDL)?","o":["10,000 pounds","16,000 pounds","26,000 pounds","40,000 pounds"],"h1":"The number is in the mid-twenty thousands.","h2":"In Nebraska, you need a CDL to drive a vehicle with a weight rating of more than 26,000 pounds.","p":"Right. Over 26,000 pounds needs a CDL."},"es":{"q":"En Nebraska, ¿a partir de qué peso nominal un vehículo requiere licencia de conducir comercial (CDL)?","o":["Más de 10,000 libras","Más de 16,000 libras","Más de 26,000 libras","Más de 40,000 libras"],"h1":"El número está entre las veinte mil y treinta mil.","h2":"En Nebraska, necesita una CDL para manejar un vehículo con un peso nominal de más de 26,000 libras.","p":"Correcto. Más de 26,000 libras requiere CDL."},"ref":{"doc":"NE","page":8}},{"id":"ne-064","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, which of these may you NOT drive with only a Class O operator's license?","o":["A motorcycle","A moped","An autocycle","An all-terrain vehicle (ATV)"],"h1":"It needs its own Class M license.","h2":"In Nebraska, a Class O license covers mopeds, autocycles, ATVs and UTVs, but not motorcycles.","p":"Right. A motorcycle needs a Class M license or endorsement."},"es":{"q":"En Nebraska, ¿cuál de estos NO puede manejar solo con una licencia de operador Clase O?","o":["Una motocicleta","Un ciclomotor (moped)","Un autociclo","Un vehículo todo terreno (ATV)"],"h1":"Necesita su propia licencia Clase M.","h2":"En Nebraska, la licencia Clase O cubre ciclomotores, autociclos, ATV y UTV, pero no motocicletas.","p":"Correcto. Una motocicleta necesita licencia o endoso Clase M."},"ref":{"doc":"NE","page":5}},{"id":"ne-065","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a moped's motor may be no bigger than 50 cc. What is its highest design speed?","o":["15 mph","45 mph","55 mph","30 mph"],"h1":"It is slower than most city traffic.","h2":"In Nebraska, a moped has a motor of 50 cc or less and a top design speed of no more than 30 mph.","p":"Right. A moped is built to go no faster than 30 mph."},"es":{"q":"En Nebraska, el motor de un ciclomotor (moped) no puede pasar de 50 cc. ¿Cuál es su velocidad máxima de diseño?","o":["15 mph","45 mph","55 mph","30 mph"],"h1":"Es más lento que la mayoría del tráfico de la ciudad.","h2":"En Nebraska, un ciclomotor tiene un motor de 50 cc o menos y una velocidad máxima de diseño de no más de 30 mph.","p":"Correcto. Un ciclomotor está hecho para no pasar de 30 mph."},"ref":{"doc":"NE","page":6}},{"id":"ne-066","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, an ATV is allowed on a public road. When may it be driven there?","o":["Any time, day or night","Only between sunrise and sunset, under 30 mph","Only at night, with flashers on","Only on weekends"],"h1":"Daylight and a low speed are both required.","h2":"In Nebraska, an ATV or UTV allowed on a public road may be driven only between sunrise and sunset, at less than 30 mph.","p":"Right. Daylight only, and under 30 mph."},"es":{"q":"En Nebraska, un ATV tiene permiso para usar una vía pública. ¿Cuándo puede manejarse ahí?","o":["A cualquier hora, de día o de noche","Solo entre la salida y la puesta del sol, a menos de 30 mph","Solo de noche, con luces intermitentes","Solo los fines de semana"],"h1":"Se exige luz del día y poca velocidad.","h2":"En Nebraska, un ATV o UTV con permiso para usar una vía pública solo puede manejarse entre la salida y la puesta del sol, a menos de 30 mph.","p":"Correcto. Solo de día y a menos de 30 mph."},"ref":{"doc":"NE","page":7}},{"id":"ne-067","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how many documents showing your Nebraska home address must you bring for a permit or license?","o":["None","One","Two, from different sources","Five"],"h1":"One is not enough, and they cannot come from the same place.","h2":"In Nebraska, you must show two documents with your principal address, from two different issuing sources.","p":"Right. Two address documents from different sources."},"es":{"q":"En Nebraska, ¿cuántos documentos con su dirección en Nebraska debe llevar para un permiso o licencia?","o":["Ninguno","Uno","Dos, de fuentes distintas","Cinco"],"h1":"Uno no basta, y no pueden venir del mismo lugar.","h2":"En Nebraska, debe mostrar dos documentos con su dirección principal, de dos fuentes distintas.","p":"Correcto. Dos documentos de dirección de fuentes distintas."},"ref":{"doc":"NE","page":10}},{"id":"ne-068","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, you back into a parked car and the owner is not there. What must you do?","o":["Contact the authorities and leave your information where the owner can find it","Drive away if the damage looks small","Wait one hour, then leave","Only take a photo of the damage"],"h1":"The owner needs a way to reach you.","h2":"In Nebraska, if you hit an unattended vehicle, you must contact the proper authorities and leave your written information where the owner can find it.","p":"Right. Report it and leave your information for the owner."},"es":{"q":"En Nebraska, usted choca un carro estacionado al dar marcha atrás y el dueño no está. ¿Qué debe hacer?","o":["Avisar a las autoridades y dejar sus datos donde el dueño los encuentre","Irse si el daño parece pequeño","Esperar una hora y luego irse","Solo tomar una foto del daño"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Nebraska, si choca un vehículo sin nadie, debe avisar a las autoridades y dejar sus datos por escrito donde el dueño los encuentre.","p":"Correcto. Avise y deje sus datos para el dueño."},"ref":{"doc":"NE","page":73}},{"id":"ne-069","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a license is issued to a driver who is 30. When does it expire?","o":["After two years","On the 40th birthday","After ten years","On the birthday in the fifth year after issue"],"h1":"Count years, not decades.","h2":"In Nebraska, a license issued to someone 21 or older expires on their birthday in the fifth year after it is issued.","p":"Right. It runs to the birthday in the fifth year."},"es":{"q":"En Nebraska, se emite una licencia a un conductor de 30 años. ¿Cuándo vence?","o":["Después de dos años","Al cumplir 40 años","Después de diez años","En el cumpleaños del quinto año después de emitida"],"h1":"Cuente años, no décadas.","h2":"En Nebraska, la licencia de una persona de 21 años o más vence en su cumpleaños del quinto año después de emitida.","p":"Correcto. Dura hasta el cumpleaños del quinto año."},"ref":{"doc":"NE","page":15}},{"id":"ne-070","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a driver over 21 wants to renew early. How soon before the birthday may they renew?","o":["7 days","90 days","One year","Two years"],"h1":"It is about three months.","h2":"In Nebraska, drivers 21 and over may renew their license up to 90 days before their birthday.","p":"Right. Renewal can start 90 days before the birthday."},"es":{"q":"En Nebraska, un conductor mayor de 21 años quiere renovar antes. ¿Con cuánta anticipación a su cumpleaños puede renovar?","o":["7 días","90 días","Un año","Dos años"],"h1":"Son unos tres meses.","h2":"En Nebraska, los conductores de 21 años o más pueden renovar la licencia hasta 90 días antes de su cumpleaños.","p":"Correcto. Puede renovar desde 90 días antes del cumpleaños."},"ref":{"doc":"NE","page":15}},{"id":"ne-071","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what does restriction code B on a driver's license mean?","o":["Daylight driving only","No interstate driving","Must wear corrective lenses","Automatic transmission only"],"h1":"It is about how the driver sees.","h2":"In Nebraska, restriction B means the driver must wear corrective lenses, such as glasses or contacts, while driving.","p":"Right. B means corrective lenses."},"es":{"q":"En Nebraska, ¿qué significa el código de restricción B en una licencia?","o":["Manejar solo de día","No manejar en interestatales","Debe usar lentes correctivos","Solo transmisión automática"],"h1":"Tiene que ver con cómo ve el conductor.","h2":"En Nebraska, la restricción B significa que el conductor debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar.","p":"Correcto. B significa lentes correctivos."},"ref":{"doc":"NE","page":16}},{"id":"ne-072","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a license was revoked under the point system. What course must be finished before it is reinstated?","o":["A driver's education course of at least four hours","A one-hour online video","A full new driver training of 50 hours","No course is needed"],"h1":"It is approved by the DMV and paid for by the driver.","h2":"In Nebraska, after a point system revocation, the driver must finish a DMV-approved course of at least four hours before the license is reinstated.","p":"Right. A course of at least four hours is required."},"es":{"q":"En Nebraska, a un conductor le revocaron la licencia por el sistema de puntos. ¿Qué curso debe terminar antes de recuperarla?","o":["Un curso de educación vial de por lo menos cuatro horas","Un video en línea de una hora","Un entrenamiento nuevo completo de 50 horas","No necesita ningún curso"],"h1":"Lo aprueba el DMV y lo paga el conductor.","h2":"En Nebraska, después de una revocación por puntos, el conductor debe terminar un curso aprobado por el DMV de por lo menos cuatro horas antes de recuperar la licencia.","p":"Correcto. Se exige un curso de por lo menos cuatro horas."},"ref":{"doc":"NE","page":18}},{"id":"ne-073","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, after a point system revocation, how long must the driver keep proof of insurance (Form SR-22)?","o":["30 days","Six months","Ten years","Three years"],"h1":"It is counted from the end of the revocation.","h2":"In Nebraska, proof of financial responsibility, usually an SR-22, must be kept for three years after the revocation ends.","p":"Right. The SR-22 is needed for three years."},"es":{"q":"En Nebraska, después de una revocación por puntos, ¿por cuánto tiempo debe el conductor mantener prueba de seguro (formulario SR-22)?","o":["30 días","Seis meses","Diez años","Tres años"],"h1":"Se cuenta desde el final de la revocación.","h2":"En Nebraska, la prueba de responsabilidad financiera, por lo general un SR-22, debe mantenerse por tres años después de que termina la revocación.","p":"Correcto. El SR-22 se necesita por tres años."},"ref":{"doc":"NE","page":18}},{"id":"ne-074","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, how many points are added for a conviction of driving under the influence of alcohol or drugs?","o":["2 points","6 points","1 point","12 points"],"h1":"It is half of the 12 points that cause revocation.","h2":"In Nebraska, a conviction for driving under the influence adds 6 points to the driving record.","p":"Right. A DUI conviction is 6 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por una condena por manejar bajo la influencia de alcohol o drogas?","o":["2 puntos","6 puntos","1 punto","12 puntos"],"h1":"Es la mitad de los 12 puntos que causan la revocación.","h2":"En Nebraska, una condena por manejar bajo la influencia agrega 6 puntos al historial de manejo.","p":"Correcto. Una condena por DUI son 6 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-075","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how many points does careless (inattentive) driving add?","o":["1 point","2 points","4 points","8 points"],"h1":"It is less than reckless driving but more than negligent driving.","h2":"In Nebraska, careless driving adds 4 points to the driving record.","p":"Right. Careless driving is 4 points."},"es":{"q":"En Nebraska, ¿cuántos puntos agrega manejar sin cuidado (desatento)?","o":["1 punto","2 puntos","4 puntos","8 puntos"],"h1":"Es menos que manejar de forma imprudente, pero más que manejar con negligencia.","h2":"En Nebraska, manejar sin cuidado agrega 4 puntos al historial de manejo.","p":"Correcto. Manejar sin cuidado son 4 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-076","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, how many points are added for passing a school bus that has its red lights flashing and stop arm out?","o":["1 point","6 points","12 points","3 points"],"h1":"It is the same number as texting while driving.","h2":"In Nebraska, illegally passing a stopped school bus with flashing red lights and the stop arm out adds 3 points.","p":"Right. A school bus violation is 3 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por rebasar un autobús escolar con las luces rojas intermitentes y el brazo de alto extendido?","o":["1 punto","6 puntos","12 puntos","3 puntos"],"h1":"Es el mismo número que por escribir mensajes al manejar.","h2":"En Nebraska, rebasar ilegalmente un autobús escolar detenido con luces rojas intermitentes y el brazo de alto extendido agrega 3 puntos.","p":"Correcto. Una violación del autobús escolar son 3 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-077","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, a driver fails to yield to a pedestrian, but the pedestrian is not hurt. How many points are added?","o":["2 points","4 points","6 points","None"],"h1":"If the person had been hurt, it would be 4 points.","h2":"In Nebraska, failing to yield to a pedestrian with no injury adds 2 points; with an injury it adds 4.","p":"Right. With no injury, it is 2 points."},"es":{"q":"En Nebraska, un conductor no cede el paso a un peatón, pero el peatón no sale herido. ¿Cuántos puntos se agregan?","o":["2 puntos","4 puntos","6 puntos","Ninguno"],"h1":"Si la persona hubiera salido herida, serían 4 puntos.","h2":"En Nebraska, no ceder el paso a un peatón sin lesiones agrega 2 puntos; con lesiones agrega 4.","p":"Correcto. Sin lesiones son 2 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-078","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, you get a ticket today for driving 4 mph over the speed limit. How many points go on your record?","o":["1 point","2 points","No points","3 points"],"h1":"The rule changed for tickets from November 14, 2020.","h2":"In Nebraska, speeding 1 to 5 mph over the limit adds no points for tickets dated on or after November 14, 2020, though you can still be fined.","p":"Right. 1 to 5 mph over now adds no points."},"es":{"q":"En Nebraska, hoy le dan una multa por manejar 4 mph sobre el límite. ¿Cuántos puntos se anotan en su historial?","o":["1 punto","2 puntos","Ningún punto","3 puntos"],"h1":"La regla cambió para multas desde el 14 de noviembre de 2020.","h2":"En Nebraska, exceder el límite por 1 a 5 mph no agrega puntos en multas del 14 de noviembre de 2020 en adelante, aunque igual puede recibir una multa.","p":"Correcto. De 1 a 5 mph sobre el límite ya no agrega puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-079","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a conviction stays on the record for five years. After how long do its points stop counting?","o":["Six months","Two years after the violation","Five years","Ten years"],"h1":"It is the same period used for the 12-point revocation rule.","h2":"In Nebraska, points stop counting two years after the date of the violation, even though the conviction stays on the record for five years.","p":"Right. Points stop counting after two years."},"es":{"q":"En Nebraska, una condena queda en el historial por cinco años. ¿Después de cuánto tiempo dejan de contar sus puntos?","o":["Seis meses","Dos años después de la infracción","Cinco años","Diez años"],"h1":"Es el mismo período de la regla de revocación por 12 puntos.","h2":"En Nebraska, los puntos dejan de contar dos años después de la fecha de la infracción, aunque la condena queda en el historial cinco años.","p":"Correcto. Los puntos dejan de contar después de dos años."},"ref":{"doc":"NE","page":19}},{"id":"ne-080","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you are convicted of a traffic violation in another state. What happens to your Nebraska record?","o":["Nothing, it only counts in that state","Points are cut in half","Only a fine is recorded","Points are added as if it happened in Nebraska"],"h1":"Leaving the state does not protect your record.","h2":"In Nebraska, points for a traffic conviction in another state are added to your record as if the violation happened in Nebraska.","p":"Right. Out-of-state violations count like Nebraska ones."},"es":{"q":"En Nebraska, a usted lo condenan por una infracción de tránsito en otro estado. ¿Qué pasa con su historial de Nebraska?","o":["Nada, solo cuenta en ese estado","Los puntos se reducen a la mitad","Solo se anota una multa","Se agregan puntos como si hubiera pasado en Nebraska"],"h1":"Salir del estado no protege su historial.","h2":"En Nebraska, los puntos de una condena de tránsito en otro estado se agregan a su historial como si la infracción hubiera ocurrido en Nebraska.","p":"Correcto. Las infracciones de otro estado cuentan como las de Nebraska."},"ref":{"doc":"NE","page":19}},{"id":"ne-081","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a court impounds a driver's license, and the driver is convicted of driving during the impoundment. What happens?","o":["The license is revoked for one year","Only a warning is given","The impoundment ends early","A $10 fine only"],"h1":"The penalty is much longer than most impoundments.","h2":"In Nebraska, a driver convicted of driving while the license is impounded by a court has the license revoked for one year.","p":"Right. Driving during impoundment means a one-year revocation."},"es":{"q":"En Nebraska, un tribunal retiene la licencia de un conductor, y lo condenan por manejar durante ese período. ¿Qué pasa?","o":["La licencia se revoca por un año","Solo recibe una advertencia","La retención termina antes","Solo una multa de $10"],"h1":"La sanción es mucho más larga que la mayoría de las retenciones.","h2":"En Nebraska, a un conductor condenado por manejar mientras un tribunal retiene su licencia se le revoca la licencia por un año.","p":"Correcto. Manejar durante la retención significa un año de revocación."},"ref":{"doc":"NE","page":20}},{"id":"ne-082","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a driver under 21 is convicted of refusing an alcohol test. How long does the court impound the license?","o":["10 days","30 days","90 days","Five years"],"h1":"It is longer than the 30 days for a .02 conviction.","h2":"In Nebraska, an underage driver convicted of refusing a test has the license impounded by the court for 90 days.","p":"Right. An underage refusal means a 90-day impoundment."},"es":{"q":"En Nebraska, a un conductor menor de 21 años lo condenan por negarse a una prueba de alcohol. ¿Por cuánto tiempo retiene el tribunal la licencia?","o":["10 días","30 días","90 días","Cinco años"],"h1":"Es más que los 30 días por una condena de .02.","h2":"En Nebraska, a un conductor menor de edad condenado por negarse a la prueba el tribunal le retiene la licencia por 90 días.","p":"Correcto. Negarse siendo menor significa 90 días de retención."},"ref":{"doc":"NE","page":20}},{"id":"ne-083","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a driver who already has a prior offense fails an alcohol test after a DUI arrest. How long is the administrative license revocation?","o":["15 days","90 days","180 days","One year"],"h1":"It is longer than the 180 days for a first offense.","h2":"In Nebraska, a repeat offender who fails an alcohol test serves a one-year administrative license revocation.","p":"Right. A repeat offender loses the license for one year."},"es":{"q":"En Nebraska, un conductor con una infracción anterior no pasa la prueba de alcohol después de un arresto por DUI. ¿Cuánto dura la revocación administrativa?","o":["15 días","90 días","180 días","Un año"],"h1":"Es más que los 180 días de la primera vez.","h2":"En Nebraska, quien ya tiene una infracción anterior y no pasa la prueba de alcohol recibe una revocación administrativa de un año.","p":"Correcto. Quien reincide pierde la licencia por un año."},"ref":{"doc":"NE","page":20}},{"id":"ne-084","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a first-time offender with an administrative revocation gets an ignition interlock permit. How long is it valid?","o":["15 days","Six months","Five years","For life"],"h1":"It covers the same time as a first-offense revocation.","h2":"In Nebraska, a first-time offender's ignition interlock permit is valid for six months and allows driving only a vehicle with an interlock device.","p":"Right. The permit is valid for six months."},"es":{"q":"En Nebraska, un infractor por primera vez con revocación administrativa obtiene un permiso de bloqueo de encendido (interlock). ¿Por cuánto tiempo es válido?","o":["15 días","Seis meses","Cinco años","De por vida"],"h1":"Cubre el mismo tiempo que la revocación de la primera vez.","h2":"En Nebraska, el permiso de bloqueo de encendido de un infractor por primera vez es válido por seis meses y solo permite manejar un vehículo con ese aparato.","p":"Correcto. El permiso es válido por seis meses."},"ref":{"doc":"NE","page":21}},{"id":"ne-085","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a person is convicted of leaving the scene of a crash. How long may the license be revoked?","o":["One week","30 days","Up to one year","Fifteen years"],"h1":"The longest time is twelve months.","h2":"In Nebraska, a driver convicted of leaving the scene of a crash may have the license revoked for up to one year.","p":"Right. The revocation can last up to one year."},"es":{"q":"En Nebraska, condenan a una persona por irse del lugar de un choque. ¿Por cuánto tiempo pueden revocarle la licencia?","o":["Una semana","30 días","Hasta un año","Quince años"],"h1":"El tiempo más largo es de doce meses.","h2":"En Nebraska, a un conductor condenado por irse del lugar de un choque le pueden revocar la licencia hasta por un año.","p":"Correcto. La revocación puede durar hasta un año."},"ref":{"doc":"NE","page":22}},{"id":"ne-086","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, a 19-year-old is convicted of minor in possession of alcohol for the second time. How long is the license impounded?","o":["90 days","7 days","30 days","Three years"],"h1":"The first offense is 30 days; the second is longer.","h2":"In Nebraska, a second minor in possession conviction means the court impounds the permit or license for 90 days.","p":"Right. A second offense means 90 days."},"es":{"q":"En Nebraska, a un joven de 19 años lo condenan por segunda vez por posesión de alcohol siendo menor. ¿Por cuánto tiempo se retiene la licencia?","o":["90 días","7 días","30 días","Tres años"],"h1":"La primera vez son 30 días; la segunda es más.","h2":"En Nebraska, una segunda condena por posesión de alcohol siendo menor significa que el tribunal retiene el permiso o la licencia por 90 días.","p":"Correcto. La segunda vez son 90 días."},"ref":{"doc":"NE","page":22}},{"id":"ne-087","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, what blood alcohol level is illegal for a person driving a commercial motor vehicle?","o":["0.02 or higher","0.04 or higher","0.10 or higher","0.15 or higher"],"h1":"It is half the limit for other adult drivers.","h2":"In Nebraska, it is illegal to drive a commercial motor vehicle with a blood alcohol level of 0.04 or higher.","p":"Right. The commercial limit is 0.04."},"es":{"q":"En Nebraska, ¿qué nivel de alcohol en la sangre es ilegal para quien maneja un vehículo comercial?","o":["0.02 o más","0.04 o más","0.10 o más","0.15 o más"],"h1":"Es la mitad del límite para los demás conductores adultos.","h2":"En Nebraska, es ilegal manejar un vehículo comercial con un nivel de alcohol en la sangre de 0.04 o más.","p":"Correcto. El límite comercial es 0.04."},"ref":{"doc":"NE","page":24}},{"id":"ne-088","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, a passenger wants to hold an open can of beer while you drive. Is this legal?","o":["Yes, only the driver may not drink","Yes, if the car is parked on the street","Yes, if the passenger is over 21","No, open containers are illegal for drivers and passengers"],"h1":"The rule covers everyone inside the vehicle.","h2":"In Nebraska, it is illegal for a driver or a passenger to have an open container of alcohol in a vehicle on a public road or public parking area.","p":"Right. Open containers are illegal for everyone in the vehicle."},"es":{"q":"En Nebraska, un pasajero quiere llevar una lata de cerveza abierta mientras usted maneja. ¿Es legal?","o":["Sí, solo el conductor no puede beber","Sí, si el carro está estacionado en la calle","Sí, si el pasajero es mayor de 21","No, los envases abiertos son ilegales para el conductor y los pasajeros"],"h1":"La regla incluye a todos dentro del vehículo.","h2":"En Nebraska, es ilegal que el conductor o un pasajero tenga un envase abierto de alcohol en un vehículo en una vía pública o un estacionamiento público.","p":"Correcto. Los envases abiertos son ilegales para todos en el vehículo."},"ref":{"doc":"NE","page":24}},{"id":"ne-089","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, what is the minimum insurance for injury to two or more people in one crash?","o":["$10,000","$25,000","$50,000","$1,000,000"],"h1":"It is twice the amount for one person.","h2":"In Nebraska, insurance must cover at least $50,000 for injury or death of two or more people in one crash.","p":"Right. The minimum is $50,000 for two or more people."},"es":{"q":"En Nebraska, ¿cuál es el seguro mínimo por lesiones a dos o más personas en un choque?","o":["$10,000","$25,000","$50,000","$1,000,000"],"h1":"Es el doble de la cantidad por una persona.","h2":"En Nebraska, el seguro debe cubrir por lo menos $50,000 por lesiones o muerte de dos o más personas en un choque.","p":"Correcto. El mínimo es de $50,000 para dos o más personas."},"ref":{"doc":"NE","page":28}},{"id":"ne-090","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, what is the least tread depth your tires must have?","o":["2/32 of an inch","1/64 of an inch","1/2 inch","No set amount"],"h1":"It is a small fraction measured in 32nds of an inch.","h2":"In Nebraska, a vehicle's tires must have at least 2/32 of an inch of tread.","p":"Right. Tires need at least 2/32 inch of tread."},"es":{"q":"En Nebraska, ¿cuál es la profundidad mínima del dibujo de las llantas?","o":["2/32 de pulgada","1/64 de pulgada","1/2 pulgada","No hay una cantidad fija"],"h1":"Es una fracción pequeña medida en treintaidosavos de pulgada.","h2":"En Nebraska, las llantas de un vehículo deben tener por lo menos 2/32 de pulgada de dibujo.","p":"Correcto. Las llantas necesitan por lo menos 2/32 de pulgada de dibujo."},"ref":{"doc":"NE","page":29}},{"id":"ne-091","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, front side window tint must let in at least how much light?","o":["5 percent","10 percent","20 percent","35 percent"],"h1":"The back windows may be darker than the front side windows.","h2":"In Nebraska, tint on the front side windows must let at least 35 percent of light through.","p":"Right. Front side windows need at least 35 percent light."},"es":{"q":"En Nebraska, ¿cuánta luz debe dejar pasar, como mínimo, el polarizado de las ventanas laterales delanteras?","o":["5 por ciento","10 por ciento","20 por ciento","35 por ciento"],"h1":"Las ventanas de atrás pueden ser más oscuras que las laterales delanteras.","h2":"En Nebraska, el polarizado de las ventanas laterales delanteras debe dejar pasar por lo menos el 35 por ciento de la luz.","p":"Correcto. Las laterales delanteras necesitan por lo menos 35 por ciento de luz."},"ref":{"doc":"NE","page":29}},{"id":"ne-092","scope":"NE","cat":"signals","sign":null,"c":1,"en":{"q":"In Nebraska, the power is out and a traffic light is completely dark. No officer is there. What must you do?","o":["Drive through if no one is coming","Treat it as an all-way stop","Treat it as a yield sign","Honk and go"],"h1":"Every driver at the intersection must do the same thing.","h2":"In Nebraska, an intersection with a dark traffic signal and no officer or flagger is treated as an all-way stop.","p":"Right. A dark signal is an all-way stop."},"es":{"q":"En Nebraska, no hay electricidad y un semáforo está totalmente apagado. No hay ningún policía. ¿Qué debe hacer?","o":["Pasar si no viene nadie","Tratarlo como un alto en todas las direcciones","Tratarlo como una señal de ceda el paso","Tocar la bocina y seguir"],"h1":"Todos los conductores en la intersección deben hacer lo mismo.","h2":"En Nebraska, una intersección con el semáforo apagado y sin policía ni banderero se trata como un alto en todas las direcciones.","p":"Correcto. Un semáforo apagado es un alto en todas las direcciones."},"ref":{"doc":"NE","page":31}},{"id":"ne-093","scope":"NE","cat":"signals","sign":null,"c":2,"en":{"q":"In Nebraska, when may you turn left on a steady red light after stopping?","o":["Never","At any intersection after stopping","Only from a one-way street onto another one-way street","Only from a two-way street onto a one-way street"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Nebraska, you may turn left on red after a full stop only from a one-way street onto another one-way street, unless a sign says no.","p":"Right. Left on red is only one-way onto one-way."},"es":{"q":"En Nebraska, ¿cuándo puede girar a la izquierda con la luz roja fija después de detenerse?","o":["Nunca","En cualquier intersección después de detenerse","Solo de una calle de un sentido a otra calle de un sentido","Solo de una calle de doble sentido a una de un sentido"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Nebraska, puede girar a la izquierda en rojo después de detenerse por completo solo de una calle de un sentido a otra de un sentido, salvo que una señal lo prohíba.","p":"Correcto. Girar a la izquierda en rojo es solo de un sentido a un sentido."},"ref":{"doc":"NE","page":32}},{"id":"ne-094","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, you must stop at a railroad crossing that has no stop line. How far from the nearest rail should you stop?","o":["Between 15 and 50 feet","Between 2 and 5 feet","Exactly 100 feet","Right on the first rail"],"h1":"Not too close, and not too far to see the tracks.","h2":"In Nebraska, when there is no stop line, you must stop not less than 15 feet and not more than 50 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Nebraska, debe detenerse en un cruce de ferrocarril sin línea de alto. ¿A qué distancia del riel más cercano debe detenerse?","o":["Entre 15 y 50 pies","Entre 2 y 5 pies","Exactamente a 100 pies","Justo sobre el primer riel"],"h1":"Ni muy cerca, ni tan lejos que no vea las vías.","h2":"En Nebraska, cuando no hay línea de alto, debe detenerse a no menos de 15 pies ni más de 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"NE","page":58}},{"id":"ne-095","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, you are passing a bicycle going the same way. How much space must you leave?","o":["6 inches","1 foot","10 feet","At least 3 feet"],"h1":"It is a little more than an arm's length.","h2":"In Nebraska, you must leave at least three feet of clearance when passing a bicycle, and keep it until you are safely past.","p":"Right. Leave at least three feet."},"es":{"q":"En Nebraska, usted rebasa una bicicleta que va en su mismo sentido. ¿Cuánto espacio debe dejar?","o":["6 pulgadas","1 pie","10 pies","Por lo menos 3 pies"],"h1":"Es un poco más que el largo de un brazo.","h2":"En Nebraska, debe dejar por lo menos tres pies de espacio al rebasar una bicicleta, y mantenerlo hasta pasarla con seguridad.","p":"Correcto. Deje por lo menos tres pies."},"ref":{"doc":"NE","page":69}},{"id":"ne-096","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, you are using high beams on an open highway and come up behind another car. Within what distance must you dim your lights?","o":["50 feet","200 feet","1,000 feet","One mile"],"h1":"It is about two-thirds the length of a football field.","h2":"In Nebraska, you must dim your high beams when you are following within 200 feet of another vehicle.","p":"Right. Dim your lights within 200 feet of a car ahead."},"es":{"q":"En Nebraska, usted usa las luces altas en una carretera abierta y se acerca por detrás a otro carro. ¿A qué distancia debe bajar las luces?","o":["50 pies","200 pies","1,000 pies","Una milla"],"h1":"Es como dos tercios del largo de un campo de fútbol americano.","h2":"En Nebraska, debe bajar las luces altas cuando sigue a otro vehículo a menos de 200 pies.","p":"Correcto. Baje las luces a menos de 200 pies del carro de adelante."},"ref":{"doc":"NE","page":61}},{"id":"ne-097","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, what is the speed limit in a business district when no sign says otherwise?","o":["15 mph","35 mph","20 mph","30 mph"],"h1":"It is lower than the limit in residential districts.","h2":"In Nebraska, the speed limit in a business district is 20 mph unless a sign says otherwise.","p":"Right. Business districts are 20 mph."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad en una zona comercial cuando ninguna señal indica otro?","o":["15 mph","35 mph","20 mph","30 mph"],"h1":"Es más bajo que el límite en zonas residenciales.","h2":"En Nebraska, el límite de velocidad en una zona comercial es de 20 mph, a menos que una señal indique otro.","p":"Correcto. Las zonas comerciales son de 20 mph."},"ref":{"doc":"NE","page":52}},{"id":"ne-098","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, you drive 8 mph over the limit in a school zone. What is the fine, before court costs?","o":["$50","$25","$10","$600"],"h1":"The normal fine for 6 to 10 mph over is $25, and school zones double it.","h2":"In Nebraska, going 6 to 10 mph over the limit in a school zone costs $50, twice the normal $25, plus court costs.","p":"Right. The fine is $50 plus court costs."},"es":{"q":"En Nebraska, usted maneja 8 mph sobre el límite en una zona escolar. ¿Cuál es la multa, sin contar los costos judiciales?","o":["$50","$25","$10","$600"],"h1":"La multa normal por 6 a 10 mph de más es $25, y en zonas escolares se duplica.","h2":"En Nebraska, ir de 6 a 10 mph sobre el límite en una zona escolar cuesta $50, el doble de los $25 normales, más costos judiciales.","p":"Correcto. La multa es de $50 más costos judiciales."},"ref":{"doc":"NE","page":53}},{"id":"ne-099","scope":"NE","cat":"signals","sign":null,"c":3,"en":{"q":"In Nebraska, how far before a turn should you turn on your turn signal?","o":["Right as you begin to turn","At least 10 feet","At least 1 mile","At least 100 feet"],"h1":"It is about one third of a football field.","h2":"In Nebraska, you should signal at least 100 feet before turning or moving right or left.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Nebraska, ¿con cuánta anticipación a un giro debe encender la direccional?","o":["Justo al empezar a girar","Por lo menos 10 pies","Por lo menos 1 milla","Por lo menos 100 pies"],"h1":"Es más o menos un tercio de un campo de fútbol americano.","h2":"En Nebraska, debe poner la señal por lo menos 100 pies antes de girar o moverse a la derecha o a la izquierda.","p":"Correcto. Ponga la señal por lo menos 100 pies antes."},"ref":{"doc":"NE","page":54}},{"id":"ne-100","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, how close to a stop sign at the side of the road may you park?","o":["5 feet","No closer than 30 feet","No closer than 10 feet","You may park right next to it"],"h1":"Parked cars must not hide the sign from other drivers.","h2":"In Nebraska, you may not park within 30 feet of a stop sign, yield sign, flashing signal or other traffic control device at the side of the road.","p":"Right. Stay at least 30 feet from a stop sign."},"es":{"q":"En Nebraska, ¿qué tan cerca de una señal de alto al lado del camino puede estacionarse?","o":["5 pies","No más cerca de 30 pies","No más cerca de 10 pies","Puede estacionarse justo al lado"],"h1":"Los carros estacionados no deben tapar la señal a otros conductores.","h2":"En Nebraska, no puede estacionarse a menos de 30 pies de una señal de alto, de ceda el paso, de una luz intermitente u otro control de tránsito al lado del camino.","p":"Correcto. Quédese por lo menos a 30 pies de una señal de alto."},"ref":{"doc":"NE","page":57}},{"id":"ne-101","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a teen lives on a farm. What is the youngest age to get a Farm Husbandry Permit (FHP)?","o":["12 years old","13 years old","15 years old","16 years old"],"h1":"It is younger than the age for a school learner's permit.","h2":"In Nebraska, a teen who lives on a farm may get a Farm Husbandry Permit at age 13.","p":"Right. A farm teen may get it at 13."},"es":{"q":"En Nebraska, un adolescente vive en una granja. ¿Cuál es la edad mínima para obtener un permiso agrícola (Farm Husbandry Permit, FHP)?","o":["12 años","13 años","15 años","16 años"],"h1":"Es menor que la edad del permiso escolar de aprendiz.","h2":"En Nebraska, un adolescente que vive en una granja puede obtener el permiso agrícola a los 13 años.","p":"Correcto. Un adolescente de granja puede obtenerlo a los 13."},"ref":{"doc":"NE","page":2}},{"id":"ne-102","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, when does a Farm Husbandry Permit (FHP) expire?","o":["One year after it is issued","On the 18th birthday","On the 21st birthday","On the 16th birthday"],"h1":"It ends at the age when a teen can get a provisional permit.","h2":"In Nebraska, a Farm Husbandry Permit expires on the holder's 16th birthday.","p":"Right. It expires on the 16th birthday."},"es":{"q":"En Nebraska, ¿cuándo vence un permiso agrícola (FHP)?","o":["Un año después de emitirse","En el cumpleaños número 18","En el cumpleaños número 21","En el cumpleaños número 16"],"h1":"Termina a la edad en que un adolescente puede obtener el permiso provisional.","h2":"En Nebraska, el permiso agrícola vence en el cumpleaños número 16 de su titular.","p":"Correcto. Vence en el cumpleaños número 16."},"ref":{"doc":"NE","page":2}},{"id":"ne-103","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, how long must a teen hold a school learner's permit (LPE) or learner's permit (LPD) before applying for a School Permit (SCP)?","o":["At least two months","At least two weeks","At least six months","At least one year"],"h1":"It is shorter than the wait for a provisional permit (POP).","h2":"In Nebraska, a teen must hold an LPE or LPD for at least two months before applying for a School Permit.","p":"Right. At least two months."},"es":{"q":"En Nebraska, ¿cuánto tiempo debe tener un adolescente el permiso escolar de aprendiz (LPE) o el permiso de aprendiz (LPD) antes de pedir el permiso escolar (SCP)?","o":["Por lo menos dos meses","Por lo menos dos semanas","Por lo menos seis meses","Por lo menos un año"],"h1":"Es menos tiempo que la espera para el permiso provisional (POP).","h2":"En Nebraska, un adolescente debe tener el LPE o el LPD por lo menos dos meses antes de pedir el permiso escolar.","p":"Correcto. Por lo menos dos meses."},"ref":{"doc":"NE","page":2}},{"id":"ne-104","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a teen with a provisional operator's permit (POP) is driving. A 30-year-old friend rides in the back seat. Must the friend wear a seat belt?","o":["No, only front-seat riders must","No, only riders under 18 must","Yes, every rider must be buckled","Only on the interstate"],"h1":"The rule is stricter when the driver is a teen with a permit.","h2":"In Nebraska, everyone riding with a POP holder must be buckled up, in every seat and at every age.","p":"Right. With a POP driver, every rider buckles up."},"es":{"q":"En Nebraska, un adolescente con permiso provisional (POP) va manejando. Un amigo de 30 años va en el asiento de atrás. ¿Debe el amigo usar el cinturón?","o":["No, solo los del asiento delantero","No, solo los menores de 18","Sí, todos los pasajeros deben ir abrochados","Solo en la autopista interestatal"],"h1":"La regla es más estricta cuando quien maneja es un adolescente con permiso.","h2":"En Nebraska, todos los que viajan con un titular de POP deben ir abrochados, en cualquier asiento y a cualquier edad.","p":"Correcto. Con un conductor con POP, todos se abrochan."},"ref":{"doc":"NE","page":5}},{"id":"ne-105","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, an ATV is being driven on a public road where it is allowed. What must it have?","o":["Headlight and taillight on, and a bicycle safety flag","Only its hazard lights on","Only a slow-moving vehicle emblem","Nothing extra in daylight"],"h1":"Other drivers must be able to see it from far away, even by day.","h2":"In Nebraska, an ATV or UTV on a public road must have its headlight and taillight on and carry a bicycle safety flag.","p":"Right. Lights on and a safety flag."},"es":{"q":"En Nebraska, un ATV circula por un camino público donde está permitido. ¿Qué debe tener?","o":["El faro y la luz trasera encendidos, y una bandera de seguridad de bicicleta","Solo las luces de emergencia encendidas","Solo el emblema de vehículo lento","Nada adicional de día"],"h1":"Los demás conductores deben verlo desde lejos, incluso de día.","h2":"En Nebraska, un ATV o UTV en un camino público debe llevar el faro y la luz trasera encendidos y una bandera de seguridad de bicicleta.","p":"Correcto. Luces encendidas y bandera de seguridad."},"ref":{"doc":"NE","page":7}},{"id":"ne-106","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a vehicle carries a certain number of people. At what number, counting the driver, is a commercial driver's license (CDL) needed?","o":["8 or more","10 or more","12 or more","16 or more"],"h1":"Think of a large van or a small bus.","h2":"In Nebraska, a CDL is needed to drive a vehicle that carries 16 or more people, including the driver.","p":"Right. 16 or more people, counting the driver."},"es":{"q":"En Nebraska, un vehículo lleva cierto número de personas. ¿A partir de cuántas, contando al conductor, se necesita una licencia comercial (CDL)?","o":["8 o más","10 o más","12 o más","16 o más"],"h1":"Piense en una camioneta grande o un autobús pequeño.","h2":"En Nebraska, se necesita una CDL para manejar un vehículo que lleva 16 o más personas, incluido el conductor.","p":"Correcto. 16 o más personas, contando al conductor."},"ref":{"doc":"NE","page":8}},{"id":"ne-107","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, you apply for a license. Can a document showing only a P.O. Box prove your home address?","o":["Yes, if it is from a bank","No, a P.O. Box is not accepted","Yes, if it is less than 90 days old","Yes, but only for renewals"],"h1":"The DMV wants the place where you actually live.","h2":"In Nebraska, a P.O. Box is not accepted as proof of your principal address.","p":"Right. A P.O. Box does not count."},"es":{"q":"En Nebraska, usted solicita una licencia. ¿Puede un documento que muestra solo un apartado postal (P.O. Box) probar su domicilio?","o":["Sí, si es de un banco","No, no se acepta un apartado postal","Sí, si tiene menos de 90 días","Sí, pero solo para renovaciones"],"h1":"El DMV quiere el lugar donde usted vive de verdad.","h2":"En Nebraska, un apartado postal (P.O. Box) no se acepta como prueba de su domicilio principal.","p":"Correcto. Un apartado postal no cuenta."},"ref":{"doc":"NE","page":10}},{"id":"ne-108","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a 16-year-old has no mail or bills in their own name. What can prove their home address?","o":["A letter from a friend","A school ID card only","Their parents' or guardians' address documents","Nothing; they must wait until 18"],"h1":"There is a special rule for people under 21.","h2":"In Nebraska, an applicant under 21 who cannot prove their address may use their parents' or guardians' address documents.","p":"Right. A parent's or guardian's documents can be used."},"es":{"q":"En Nebraska, un joven de 16 años no tiene correo ni facturas a su nombre. ¿Qué puede probar su domicilio?","o":["Una carta de un amigo","Solo la credencial de la escuela","Los documentos de domicilio de sus padres o tutores","Nada; debe esperar hasta los 18"],"h1":"Hay una regla especial para menores de 21 años.","h2":"En Nebraska, un solicitante menor de 21 años que no puede probar su domicilio puede usar los documentos de domicilio de sus padres o tutores.","p":"Correcto. Se pueden usar los documentos de un padre o tutor."},"ref":{"doc":"NE","page":10}},{"id":"ne-109","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you bring a photocopy of your birth certificate to the driver licensing office. Will it be accepted?","o":["Yes, any clear copy works","Yes, if a parent signs it","Yes, if it was faxed by the hospital","No, faxed or photocopied documents are not accepted"],"h1":"The office needs a certified document with a raised seal or stamp.","h2":"In Nebraska, faxed or photocopied documents are not accepted; you must bring certified documents.","p":"Right. No photocopies or faxes."},"es":{"q":"En Nebraska, usted lleva una fotocopia de su acta de nacimiento a la oficina de licencias. ¿Se la aceptarán?","o":["Sí, cualquier copia clara sirve","Sí, si la firma un padre","Sí, si la envió por fax el hospital","No, no se aceptan documentos enviados por fax ni fotocopiados"],"h1":"La oficina necesita un documento certificado con sello en relieve o estampado.","h2":"En Nebraska, no se aceptan documentos enviados por fax ni fotocopiados; debe llevar documentos certificados.","p":"Correcto. Ni fotocopias ni faxes."},"ref":{"doc":"NE","page":9}},{"id":"ne-110","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, you fail a test at the driver licensing office. When may you take it again?","o":["Not on the same day","The same day, after one hour","Only after 30 days","Only after 90 days"],"h1":"You will need to come back another time.","h2":"In Nebraska, a failed test may not be taken again on the same day.","p":"Right. Not on the same day."},"es":{"q":"En Nebraska, usted reprueba un examen en la oficina de licencias. ¿Cuándo puede volver a tomarlo?","o":["No el mismo día","El mismo día, después de una hora","Solo después de 30 días","Solo después de 90 días"],"h1":"Tendrá que regresar en otra ocasión.","h2":"En Nebraska, un examen reprobado no se puede volver a tomar el mismo día.","p":"Correcto. No el mismo día."},"ref":{"doc":"NE","page":12}},{"id":"ne-111","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a driver's license expires on their 21st birthday. How early may they apply to renew it?","o":["120 days before the birthday","60 days before the birthday","10 days before the birthday","Only after the birthday"],"h1":"It is less time than the 90 days allowed for drivers over 21.","h2":"In Nebraska, a driver turning 21 may apply to renew 60 days before the 21st birthday.","p":"Right. They may apply 60 days before."},"es":{"q":"En Nebraska, la licencia de un conductor vence en su cumpleaños número 21. ¿Con cuánta anticipación puede solicitar la renovación?","o":["120 días antes del cumpleaños","60 días antes del cumpleaños","10 días antes del cumpleaños","Solo después del cumpleaños"],"h1":"Es menos que los 90 días permitidos a los mayores de 21.","h2":"En Nebraska, un conductor que cumple 21 puede solicitar la renovación 60 días antes de ese cumpleaños.","p":"Correcto. Puede solicitarla 60 días antes."},"ref":{"doc":"NE","page":15}},{"id":"ne-112","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, may you hold a driver's license and a State ID Card at the same time?","o":["Yes, many people carry both","Yes, if you pay a second fee","Only if you are over 65","No, you may not hold both at once"],"h1":"You must choose one or the other.","h2":"In Nebraska, no one may hold a permit or license and a State ID Card at the same time.","p":"Right. You cannot have both at once."},"es":{"q":"En Nebraska, ¿puede tener una licencia de manejo y una tarjeta de identificación estatal al mismo tiempo?","o":["Sí, mucha gente tiene las dos","Sí, si paga una segunda cuota","Solo si tiene más de 65 años","No, no puede tener las dos a la vez"],"h1":"Debe escoger una o la otra.","h2":"En Nebraska, nadie puede tener un permiso o licencia y una tarjeta de identificación estatal al mismo tiempo.","p":"Correcto. No puede tener las dos a la vez."},"ref":{"doc":"NE","page":17}},{"id":"ne-113","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, what does restriction code G on a driver's license mean?","o":["Daylight driving only","Must wear glasses","No interstate driving","Automatic transmission only"],"h1":"It limits the time of day you may drive.","h2":"In Nebraska, restriction G means the driver is limited to driving in daylight only.","p":"Right. G means daylight only."},"es":{"q":"En Nebraska, ¿qué significa el código de restricción G en una licencia?","o":["Solo manejar de día","Debe usar anteojos","No manejar en autopistas interestatales","Solo transmisión automática"],"h1":"Limita la hora del día en que puede manejar.","h2":"En Nebraska, la restricción G significa que el conductor solo puede manejar de día.","p":"Correcto. G significa solo de día."},"ref":{"doc":"NE","page":16}},{"id":"ne-114","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a driver's license has restriction code Q. What may this driver not do?","o":["Drive at night","Drive on one-way streets","Drive on the interstate","Drive with passengers"],"h1":"It concerns one kind of highway.","h2":"In Nebraska, restriction Q means the driver may not drive on the interstate.","p":"Right. Q means no interstate driving."},"es":{"q":"En Nebraska, una licencia tiene el código de restricción Q. ¿Qué no puede hacer este conductor?","o":["Manejar de noche","Manejar en calles de un solo sentido","Manejar en la autopista interestatal","Manejar con pasajeros"],"h1":"Tiene que ver con un tipo de carretera.","h2":"En Nebraska, la restricción Q significa que el conductor no puede manejar en la autopista interestatal.","p":"Correcto. Q significa no manejar en la interestatal."},"ref":{"doc":"NE","page":16}},{"id":"ne-115","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what is the minimum insurance for damage to other people's property in one crash?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"It is the same amount as the minimum for injury to one person.","h2":"In Nebraska, the minimum insurance for damage to others' property in one crash is $25,000.","p":"Right. $25,000 for property damage."},"es":{"q":"En Nebraska, ¿cuál es el seguro mínimo para daños a la propiedad de otras personas en un choque?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Es la misma cantidad que el mínimo por lesiones a una persona.","h2":"En Nebraska, el seguro mínimo por daños a la propiedad de otros en un choque es de $25,000.","p":"Correcto. $25,000 por daños a la propiedad."},"ref":{"doc":"NE","page":28}},{"id":"ne-116","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a 15-year-old breaks the rules of their learner's permit (LPD), and it is taken away. When can they get any permit again?","o":["After 30 days","After 90 days","At age 15 and a half","Not until age 16"],"h1":"It is the age for a provisional operator's permit.","h2":"In Nebraska, a teen who violates the terms of an LPE, SCP or LPD cannot get any permit until age 16.","p":"Right. No permit until age 16."},"es":{"q":"En Nebraska, un joven de 15 años no cumple las reglas de su permiso de aprendiz (LPD) y se lo quitan. ¿Cuándo puede volver a obtener un permiso?","o":["Después de 30 días","Después de 90 días","A los 15 años y medio","No antes de los 16 años"],"h1":"Es la edad del permiso provisional.","h2":"En Nebraska, un adolescente que no cumple las reglas de un LPE, SCP o LPD no puede obtener ningún permiso hasta los 16 años.","p":"Correcto. Ningún permiso antes de los 16."},"ref":{"doc":"NE","page":18}},{"id":"ne-117","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how many points are added for reckless driving that is rash and dangerous, but not deliberate (willful)?","o":["3 points","4 points","5 points","6 points"],"h1":"It is one more than careless driving and one less than willful reckless driving.","h2":"In Nebraska, reckless driving adds 5 points; willful reckless driving adds 6.","p":"Right. Reckless driving is 5 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por manejo imprudente (reckless) que es temerario y peligroso, pero no intencional?","o":["3 puntos","4 puntos","5 puntos","6 puntos"],"h1":"Es uno más que el manejo descuidado y uno menos que el manejo imprudente intencional.","h2":"En Nebraska, el manejo imprudente agrega 5 puntos; el manejo imprudente intencional agrega 6.","p":"Correcto. El manejo imprudente son 5 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-118","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, how many points are added for leaving the scene of a crash?","o":["6 points","2 points","4 points","12 points"],"h1":"It is the same as a conviction for driving under the influence.","h2":"In Nebraska, leaving the scene of a crash adds 6 points to your record.","p":"Right. Leaving the scene is 6 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por abandonar el lugar de un choque?","o":["6 puntos","2 puntos","4 puntos","12 puntos"],"h1":"Es lo mismo que una condena por manejar bajo la influencia.","h2":"En Nebraska, abandonar el lugar de un choque agrega 6 puntos a su historial.","p":"Correcto. Abandonar el lugar son 6 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-119","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, how many points does a third offense for drunk driving add?","o":["4 points","6 points","8 points","12 points"],"h1":"It is enough points, all at once, to lose the license.","h2":"In Nebraska, a third drunk driving offense adds 12 points, enough on its own for a point revocation.","p":"Right. A third offense is 12 points."},"es":{"q":"En Nebraska, ¿cuántos puntos agrega una tercera infracción por manejar ebrio?","o":["4 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Son suficientes puntos, de una sola vez, para perder la licencia.","h2":"En Nebraska, una tercera infracción por manejar ebrio agrega 12 puntos, suficientes por sí solos para revocar la licencia.","p":"Correcto. Una tercera infracción son 12 puntos."},"ref":{"doc":"NE","page":18}},{"id":"ne-120","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, a loaded truck with good brakes is going 55 mph on a dry road. About how far does it need to stop?","o":["About 100 feet","At least 340 feet","About 50 feet","About 150 feet"],"h1":"Trucks need far more room than cars to stop.","h2":"In Nebraska, a loaded truck at 55 mph on a clear, dry road needs at least 340 feet to stop, so never cut in and brake in front of it.","p":"Right. At least 340 feet."},"es":{"q":"En Nebraska, un camión cargado con buenos frenos va a 55 mph en un camino seco. ¿Más o menos qué distancia necesita para detenerse?","o":["Unos 100 pies","Por lo menos 340 pies","Unos 50 pies","Unos 150 pies"],"h1":"Los camiones necesitan mucho más espacio que los carros para detenerse.","h2":"En Nebraska, un camión cargado a 55 mph en un camino seco y despejado necesita por lo menos 340 pies para detenerse, así que nunca se meta y frene delante de él.","p":"Correcto. Por lo menos 340 pies."},"ref":{"doc":"NE","page":71}},{"id":"ne-121","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you are ticketed for driving 8 mph over the limit inside city limits. How many points are added?","o":["None","1 point","2 points","3 points"],"h1":"Inside a city, this range counts more than it would outside.","h2":"In Nebraska, going over 5 and up to 10 mph over the limit inside city limits adds 2 points.","p":"Right. Inside city limits, it is 2 points."},"es":{"q":"En Nebraska, le dan una multa por ir 8 mph sobre el límite dentro de la ciudad. ¿Cuántos puntos se agregan?","o":["Ninguno","1 punto","2 puntos","3 puntos"],"h1":"Dentro de una ciudad, este rango cuenta más que afuera.","h2":"En Nebraska, ir más de 5 y hasta 10 mph sobre el límite dentro de la ciudad agrega 2 puntos.","p":"Correcto. Dentro de la ciudad son 2 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-122","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a driver is convicted of going 40 mph over the speed limit. How many points are added?","o":["3 points","4 points","6 points","12 points"],"h1":"This is the highest speeding level on the point chart.","h2":"In Nebraska, driving more than 35 mph over the limit adds 4 points, inside or outside city limits.","p":"Right. More than 35 mph over is 4 points."},"es":{"q":"En Nebraska, un conductor es condenado por ir 40 mph sobre el límite. ¿Cuántos puntos se agregan?","o":["3 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Es el nivel más alto de exceso de velocidad en la tabla de puntos.","h2":"En Nebraska, ir más de 35 mph sobre el límite agrega 4 puntos, dentro o fuera de la ciudad.","p":"Correcto. Más de 35 mph sobre el límite son 4 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-123","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, an adult driver gets a ticket for not wearing a seat belt. How many points go on the record?","o":["No points","1 point","2 points","3 points"],"h1":"The penalty for this is a fine, not points.","h2":"In Nebraska, no points are given for an adult seat belt violation; the penalty is a $25 fine plus court costs.","p":"Right. No points, just a fine."},"es":{"q":"En Nebraska, un conductor adulto recibe una multa por no usar el cinturón de seguridad. ¿Cuántos puntos van a su historial?","o":["Ningún punto","1 punto","2 puntos","3 puntos"],"h1":"El castigo es una multa, no puntos.","h2":"En Nebraska, no se dan puntos por no usar el cinturón un adulto; el castigo es una multa de $25 más costos de corte.","p":"Correcto. Ningún punto, solo una multa."},"ref":{"doc":"NE","page":19}},{"id":"ne-124","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a driver is ticketed because a 5-year-old is not in a child safety seat. How many points are added?","o":["None","3 points","2 points","1 point"],"h1":"Unlike an adult seat belt ticket, this one does add points.","h2":"In Nebraska, a child restraint violation brings a $25 fine plus court costs and 1 point on the driver's record.","p":"Right. It adds 1 point."},"es":{"q":"En Nebraska, multan a un conductor porque un niño de 5 años no va en un asiento de seguridad infantil. ¿Cuántos puntos se agregan?","o":["Ninguno","3 puntos","2 puntos","1 punto"],"h1":"A diferencia de la multa por cinturón de un adulto, esta sí agrega puntos.","h2":"En Nebraska, no usar el asiento de seguridad infantil trae una multa de $25 más costos de corte y 1 punto en el historial del conductor.","p":"Correcto. Agrega 1 punto."},"ref":{"doc":"NE","page":26}},{"id":"ne-125","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how often may a driver use the 2-point credit for finishing a driver improvement course?","o":["Once a year","Once every two years","Once every five years","As often as they like"],"h1":"It is the same length of time that convictions stay on your record.","h2":"In Nebraska, the 2-point credit for a driver improvement course may be used only once every five years.","p":"Right. Once every five years."},"es":{"q":"En Nebraska, ¿cada cuánto puede un conductor usar el crédito de 2 puntos por terminar un curso de mejoramiento de manejo?","o":["Una vez al año","Una vez cada dos años","Una vez cada cinco años","Las veces que quiera"],"h1":"Es el mismo tiempo que las condenas quedan en su historial.","h2":"En Nebraska, el crédito de 2 puntos por un curso de mejoramiento solo se puede usar una vez cada cinco años.","p":"Correcto. Una vez cada cinco años."},"ref":{"doc":"NE","page":19}},{"id":"ne-126","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a 19-year-old is convicted of driving with a blood alcohol level of .02. How long does this conviction stay on the driving record?","o":["30 days","90 days","Two years","Five years"],"h1":"It is longer than the 30-day impoundment.","h2":"In Nebraska, an under-21 .02 conviction stays on the driving record for 90 days and is then deleted.","p":"Right. It stays for 90 days."},"es":{"q":"En Nebraska, un joven de 19 años es condenado por manejar con un nivel de alcohol de .02. ¿Cuánto tiempo queda esta condena en su historial?","o":["30 días","90 días","Dos años","Cinco años"],"h1":"Es más que los 30 días de retención de la licencia.","h2":"En Nebraska, una condena de .02 para menores de 21 queda en el historial 90 días y luego se borra.","p":"Correcto. Queda 90 días."},"ref":{"doc":"NE","page":20}},{"id":"ne-127","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a driver under 21 had the license impounded for a .02 conviction, and then is convicted of driving during the impoundment. What happens?","o":["The court revokes the license for six months","Only a warning is given","The impoundment is extended by 10 days","The license is revoked for five years"],"h1":"It is half as long as the revocation an adult would get.","h2":"In Nebraska, an underage driver convicted of driving during the impoundment has the license revoked by the court for six months.","p":"Right. The license is revoked for six months."},"es":{"q":"En Nebraska, a un conductor menor de 21 le retuvieron la licencia por una condena de .02, y luego lo condenan por manejar durante la retención. ¿Qué pasa?","o":["La corte revoca la licencia por seis meses","Solo recibe una advertencia","La retención se alarga 10 días","La licencia se revoca por cinco años"],"h1":"Es la mitad de la revocación que recibiría un adulto.","h2":"En Nebraska, a un menor condenado por manejar durante la retención la corte le revoca la licencia por seis meses.","p":"Correcto. La licencia se revoca por seis meses."},"ref":{"doc":"NE","page":20}},{"id":"ne-128","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a license is revoked under the point system, and the driver gets an Employment Driving Permit. Where may they drive with it?","o":["Anywhere during the day","Anywhere inside their county","To school, church and stores","Only between home and work, by the most direct route"],"h1":"The name of the permit tells you what it is for.","h2":"In Nebraska, an Employment Driving Permit allows driving only between home and work, by the most direct route, for the job.","p":"Right. Only between home and work."},"es":{"q":"En Nebraska, a un conductor le revocan la licencia por el sistema de puntos y obtiene un permiso para manejar al trabajo (Employment Driving Permit). ¿Por dónde puede manejar con él?","o":["Por cualquier lugar durante el día","Por cualquier lugar dentro de su condado","A la escuela, la iglesia y las tiendas","Solo entre la casa y el trabajo, por la ruta más directa"],"h1":"El nombre del permiso le dice para qué sirve.","h2":"En Nebraska, el permiso para manejar al trabajo solo permite ir entre la casa y el trabajo, por la ruta más directa, por motivos del empleo.","p":"Correcto. Solo entre la casa y el trabajo."},"ref":{"doc":"NE","page":21}},{"id":"ne-129","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a 20-year-old is convicted of minor in possession of alcohol for the third time. How long is the license impounded?","o":["30 days","90 days","12 months","Five years"],"h1":"Each offense is longer: 30 days, then 90 days, then this.","h2":"In Nebraska, a third or later minor in possession conviction means the court impounds the license for 12 months.","p":"Right. A third offense means 12 months."},"es":{"q":"En Nebraska, un joven de 20 años es condenado por tercera vez por posesión de alcohol siendo menor. ¿Por cuánto tiempo se retiene la licencia?","o":["30 días","90 días","12 meses","Cinco años"],"h1":"Cada infracción es más larga: 30 días, luego 90 días, y luego esto.","h2":"En Nebraska, una tercera condena o más por posesión de alcohol siendo menor hace que la corte retenga la licencia 12 meses.","p":"Correcto. La tercera vez son 12 meses."},"ref":{"doc":"NE","page":22}},{"id":"ne-130","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, a police officer pulls you over at night. What should you turn on to help?","o":["Your interior (dome) lights","Your high beams","Your radio","Your wipers"],"h1":"It helps the officer see inside your car.","h2":"In Nebraska, if you are pulled over at night, turn on your interior lights so the officer can see inside, and keep your hands visible.","p":"Right. Turn on the interior lights."},"es":{"q":"En Nebraska, un policía lo detiene de noche. ¿Qué debe encender para ayudar?","o":["Las luces interiores del carro","Las luces altas","El radio","Los limpiaparabrisas"],"h1":"Ayuda al policía a ver dentro de su carro.","h2":"En Nebraska, si lo detienen de noche, encienda las luces interiores para que el policía vea adentro, y mantenga las manos a la vista.","p":"Correcto. Encienda las luces interiores."},"ref":{"doc":"NE","page":28}},{"id":"ne-131","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, an officer asks you to sign a traffic ticket. What does signing it mean?","o":["You admit you are guilty","You give up your right to go to court","It is not an admission of guilt","You agree to pay double"],"h1":"Refusing to sign can get you arrested, and you can still fight it in court.","h2":"In Nebraska, signing a traffic ticket is not an admission of guilt, but refusing to sign may lead to arrest.","p":"Right. Signing does not mean you admit guilt."},"es":{"q":"En Nebraska, un policía le pide firmar una multa de tránsito. ¿Qué significa firmarla?","o":["Que usted admite que es culpable","Que renuncia a su derecho de ir a la corte","No es una admisión de culpa","Que acepta pagar el doble"],"h1":"Negarse a firmar puede llevarlo a un arresto, y aún puede disputarla en la corte.","h2":"En Nebraska, firmar una multa de tránsito no es admitir la culpa, pero negarse a firmar puede llevar a un arresto.","p":"Correcto. Firmar no significa admitir la culpa."},"ref":{"doc":"NE","page":28}},{"id":"ne-132","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, what brakes must a car have by law?","o":["Only a foot brake","Two systems: a service brake and a parking brake","Anti-lock brakes on all four wheels","A brake on each front wheel only"],"h1":"One is used while driving and one is used when parked.","h2":"In Nebraska, vehicles must have two systems of brakes: a service brake and a parking brake.","p":"Right. A service brake and a parking brake."},"es":{"q":"En Nebraska, ¿qué frenos debe tener un carro por ley?","o":["Solo un freno de pie","Dos sistemas: un freno de servicio y un freno de estacionamiento","Frenos antibloqueo en las cuatro ruedas","Un freno solo en cada rueda delantera"],"h1":"Uno se usa al manejar y otro cuando el carro está estacionado.","h2":"En Nebraska, los vehículos deben tener dos sistemas de frenos: un freno de servicio y un freno de estacionamiento.","p":"Correcto. Freno de servicio y freno de estacionamiento."},"ref":{"doc":"NE","page":29}},{"id":"ne-133","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, rear and back window tint must let in at least how much light?","o":["10 percent","50 percent","35 percent","20 percent"],"h1":"It is less than the limit for the front side windows.","h2":"In Nebraska, rear and back windows must let in at least 20 percent of light; front side windows need at least 35 percent.","p":"Right. At least 20 percent for rear windows."},"es":{"q":"En Nebraska, ¿cuánta luz, como mínimo, debe dejar pasar el polarizado de las ventanas traseras?","o":["10 por ciento","50 por ciento","35 por ciento","20 por ciento"],"h1":"Es menos que el límite para las ventanas laterales delanteras.","h2":"En Nebraska, las ventanas traseras deben dejar pasar por lo menos el 20 por ciento de la luz; las laterales delanteras, por lo menos el 35 por ciento.","p":"Correcto. Por lo menos 20 por ciento atrás."},"ref":{"doc":"NE","page":29}},{"id":"ne-134","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, a fire truck has stopped on a street to answer an emergency. May you drive onto that block or park on it?","o":["No, you may not drive onto or park within that block","Yes, if you stay 100 feet away","Yes, if you turn on your hazard lights","Yes, once the siren stops"],"h1":"The crew needs the whole area clear.","h2":"In Nebraska, you may not drive onto or park within the block where a fire truck has stopped to answer an emergency.","p":"Right. Keep out of that block."},"es":{"q":"En Nebraska, un camión de bomberos se ha detenido en una calle para atender una emergencia. ¿Puede entrar a esa cuadra o estacionarse en ella?","o":["No, no puede entrar ni estacionarse en esa cuadra","Sí, si se queda a 100 pies","Sí, si enciende las luces de emergencia","Sí, cuando se apague la sirena"],"h1":"Los bomberos necesitan toda el área libre.","h2":"En Nebraska, no puede entrar ni estacionarse en la cuadra donde un camión de bomberos se detuvo para atender una emergencia.","p":"Correcto. No entre a esa cuadra."},"ref":{"doc":"NE","page":52}},{"id":"ne-135","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, a funeral procession escort vehicle is showing its lights and sounding a signal. What must you do?","o":["Pass it quickly on the left","Nothing; it is not an emergency","Honk to let it know you are there","Yield to it, as you would to an emergency vehicle"],"h1":"Nebraska puts these escort vehicles in a special group.","h2":"In Nebraska, funeral procession escort vehicles count as emergency vehicles, and you must yield to them when they show proper signals.","p":"Right. Yield to a funeral escort."},"es":{"q":"En Nebraska, un vehículo que escolta un cortejo fúnebre lleva las luces encendidas y suena una señal. ¿Qué debe hacer?","o":["Rebasarlo rápido por la izquierda","Nada; no es una emergencia","Tocar el claxon para avisar que está ahí","Cederle el paso, como a un vehículo de emergencia"],"h1":"Nebraska pone estos vehículos de escolta en un grupo especial.","h2":"En Nebraska, los vehículos que escoltan cortejos fúnebres cuentan como vehículos de emergencia, y debe cederles el paso cuando usan las señales correctas.","p":"Correcto. Ceda el paso a la escolta fúnebre."},"ref":{"doc":"NE","page":52}},{"id":"ne-136","scope":"NE","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nebraska, a person is walking along the side of the road. How much space should you leave as you drive past?","o":["At least 6 inches","At least 1 foot","At least 3 feet","No space is needed if you slow down"],"h1":"It is the same space you give a bicycle.","h2":"In Nebraska, drivers should leave at least three feet of clearance to avoid hitting a pedestrian on the road.","p":"Right. At least three feet."},"es":{"q":"En Nebraska, una persona camina por la orilla del camino. ¿Cuánto espacio debe dejar al pasar?","o":["Por lo menos 6 pulgadas","Por lo menos 1 pie","Por lo menos 3 pies","No hace falta espacio si va despacio"],"h1":"Es el mismo espacio que le da a una bicicleta.","h2":"En Nebraska, los conductores deben dejar por lo menos tres pies de espacio para no golpear a un peatón en el camino.","p":"Correcto. Por lo menos tres pies."},"ref":{"doc":"NE","page":52}},{"id":"ne-137","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, what is the speed limit in a residential district when no sign says otherwise?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is 5 mph more than in a business district.","h2":"In Nebraska, the speed limit in a residential district is 25 mph unless a sign says otherwise.","p":"Right. 25 mph in residential areas."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad en una zona residencial cuando ninguna señal indica otra cosa?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es 5 mph más que en una zona comercial.","h2":"En Nebraska, el límite de velocidad en una zona residencial es de 25 mph, salvo que una señal indique otra cosa.","p":"Correcto. 25 mph en zonas residenciales."},"ref":{"doc":"NE","page":52}},{"id":"ne-138","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, you have a minor crash on the interstate. No one is hurt, and both cars can still be driven. What should you do?","o":["Leave the cars where they are until police arrive","Stop in the lane and turn on hazard lights","Drive away without stopping","Drive the cars to the nearest shoulder, out of the travel lanes"],"h1":"Blocking the lanes can cause another crash.","h2":"In Nebraska, after a minor interstate crash with no injuries, drivers should move drivable cars to the nearest shoulder, out of the travel lanes.","p":"Right. Move to the shoulder."},"es":{"q":"En Nebraska, usted tiene un choque leve en la autopista interestatal. Nadie está herido y los dos carros todavía funcionan. ¿Qué debe hacer?","o":["Dejar los carros donde están hasta que llegue la policía","Detenerse en el carril y encender las luces de emergencia","Irse sin detenerse","Llevar los carros al acotamiento más cercano, fuera de los carriles"],"h1":"Bloquear los carriles puede causar otro choque.","h2":"En Nebraska, después de un choque leve en la interestatal sin heridos, los conductores deben llevar los carros que funcionan al acotamiento más cercano, fuera de los carriles.","p":"Correcto. Muévase al acotamiento."},"ref":{"doc":"NE","page":51}},{"id":"ne-139","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, you are caught driving 12 mph over the limit on a normal road (not a school or work zone). What is the fine, before court costs?","o":["$25","$75","$150","$200"],"h1":"In a school zone it would be double this amount.","h2":"In Nebraska, the fine for 11 to 15 mph over the limit on a normal road is $75, plus court costs.","p":"Right. The fine is $75."},"es":{"q":"En Nebraska, lo detienen por ir 12 mph sobre el límite en un camino normal (no en zona escolar ni de obras). ¿Cuál es la multa, sin contar los costos de corte?","o":["$25","$75","$150","$200"],"h1":"En una zona escolar sería el doble.","h2":"En Nebraska, la multa por ir de 11 a 15 mph sobre el límite en un camino normal es de $75, más costos de corte.","p":"Correcto. La multa es de $75."},"ref":{"doc":"NE","page":53}},{"id":"ne-140","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","Right next to it"],"h1":"It is less than the distance from a stop sign.","h2":"In Nebraska, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay 20 feet from the crosswalk."},"es":{"q":"En Nebraska, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","Justo al lado"],"h1":"Es menos que la distancia a una señal de alto.","h2":"En Nebraska, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese a 20 pies del cruce peatonal."},"ref":{"doc":"NE","page":57}},{"id":"ne-141","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, how close to railroad tracks may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"It is the same as the farthest point where you stop for a train.","h2":"In Nebraska, you may not park within 50 feet of railroad tracks.","p":"Right. Stay 50 feet from the tracks."},"es":{"q":"En Nebraska, ¿qué tan cerca de las vías del tren puede estacionarse?","o":["No más cerca de 50 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Es igual a la distancia más lejana a la que se detiene por un tren.","h2":"En Nebraska, no puede estacionarse a menos de 50 pies de las vías del tren.","p":"Correcto. Quédese a 50 pies de las vías."},"ref":{"doc":"NE","page":57}},{"id":"ne-142","scope":"NE","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nebraska, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 30 feet","No closer than 15 feet"],"h1":"Firefighters need room to hook up their hoses.","h2":"In Nebraska, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a hydrant."},"es":{"q":"En Nebraska, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 30 pies","No más cerca de 15 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Nebraska, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies de un hidrante."},"ref":{"doc":"NE","page":57}},{"id":"ne-143","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, what is the highest fine for a first offense of parking illegally in a handicapped parking space?","o":["$50","$150","$300","$500"],"h1":"The fine goes up for a second and third offense.","h2":"In Nebraska, a first handicapped parking offense can bring a fine of up to $150; up to $300 for a second and $500 for a third.","p":"Right. Up to $150 the first time."},"es":{"q":"En Nebraska, ¿cuál es la multa más alta por una primera infracción de estacionarse sin permiso en un espacio para discapacitados?","o":["$50","$150","$300","$500"],"h1":"La multa sube en la segunda y la tercera infracción.","h2":"En Nebraska, una primera infracción en un espacio para discapacitados puede tener una multa de hasta $150; hasta $300 la segunda y $500 la tercera.","p":"Correcto. Hasta $150 la primera vez."},"ref":{"doc":"NE","page":57}},{"id":"ne-144","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, it is getting dark. May you drive with only your parking lights on?","o":["Yes, until full darkness","Yes, inside city limits","No, driving with only parking lights is unlawful","Yes, if you drive under 25 mph"],"h1":"Headlights are required from sunset to sunrise.","h2":"In Nebraska, driving with only parking lights on is unlawful; use your headlights from sunset to sunrise.","p":"Right. Parking lights alone are not allowed."},"es":{"q":"En Nebraska, está oscureciendo. ¿Puede manejar solo con las luces de estacionamiento encendidas?","o":["Sí, hasta que esté totalmente oscuro","Sí, dentro de la ciudad","No, manejar solo con luces de estacionamiento es ilegal","Sí, si va a menos de 25 mph"],"h1":"Los faros son obligatorios desde la puesta hasta la salida del sol.","h2":"En Nebraska, manejar solo con las luces de estacionamiento es ilegal; use los faros desde la puesta hasta la salida del sol.","p":"Correcto. Las luces de estacionamiento solas no se permiten."},"ref":{"doc":"NE","page":61}},{"id":"ne-145","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, fog cuts your view to less than a quarter mile. What does the manual say about roads posted at 40 mph or more?","o":["Travel on them is not recommended","Drive them with high beams on","Drive them at the posted speed with hazard lights","Use only the left lane"],"h1":"Think about whether you should be on such a road at all.","h2":"In Nebraska, travel on roads posted at 40 mph or more is not recommended when fog cuts visibility to less than a quarter mile.","p":"Right. Travel there is not recommended."},"es":{"q":"En Nebraska, la neblina reduce su visibilidad a menos de un cuarto de milla. ¿Qué dice el manual sobre los caminos con límite de 40 mph o más?","o":["No se recomienda viajar por ellos","Manejarlos con las luces altas","Manejarlos al límite indicado con luces de emergencia","Usar solo el carril izquierdo"],"h1":"Piense si debe estar en un camino así.","h2":"En Nebraska, no se recomienda viajar por caminos con límite de 40 mph o más cuando la neblina reduce la visibilidad a menos de un cuarto de milla.","p":"Correcto. No se recomienda viajar por ahí."},"ref":{"doc":"NE","page":62}},{"id":"ne-146","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, may a car have a television screen that the driver can see while driving?","o":["Yes, if the sound is off","Yes, on the interstate only","Yes, if a passenger controls it","No, it is illegal"],"h1":"The driver's eyes belong on the road.","h2":"In Nebraska, it is illegal to drive on a public road with a television screen that the driver can see.","p":"Right. A TV the driver can see is illegal."},"es":{"q":"En Nebraska, ¿puede un carro tener una pantalla de televisión que el conductor vea mientras maneja?","o":["Sí, si está sin sonido","Sí, solo en la interestatal","Sí, si la controla un pasajero","No, es ilegal"],"h1":"Los ojos del conductor deben estar en el camino.","h2":"En Nebraska, es ilegal manejar en un camino público con una pantalla de televisión que el conductor pueda ver.","p":"Correcto. Una televisión a la vista del conductor es ilegal."},"ref":{"doc":"NE","page":65}},{"id":"ne-147","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, the three-second following rule is a minimum. It starts to rain. How should you change it?","o":["Keep it at three seconds","Add one second, for at least four seconds","Cut it to two seconds","Double it to ten seconds"],"h1":"Add a little time for each extra problem, like rain or heavy traffic.","h2":"In Nebraska, add one second to the three-second rule for each bad condition, such as rain or heavy traffic.","p":"Right. Add one second for the rain."},"es":{"q":"En Nebraska, la regla de seguir a tres segundos es un mínimo. Empieza a llover. ¿Cómo debe cambiarla?","o":["Dejarla en tres segundos","Agregar un segundo, para tener por lo menos cuatro","Bajarla a dos segundos","Duplicarla a diez segundos"],"h1":"Agregue un poco de tiempo por cada problema extra, como lluvia o tráfico pesado.","h2":"En Nebraska, agregue un segundo a la regla de tres segundos por cada condición mala, como lluvia o tráfico pesado.","p":"Correcto. Agregue un segundo por la lluvia."},"ref":{"doc":"NE","page":67}},{"id":"ne-148","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, on a one-way street in a city, where is a bicyclist allowed to ride?","o":["Only on the sidewalk","Only in a marked bike lane","Only in the far right lane","In the far left lane, if they choose"],"h1":"On these streets, cyclists are not stuck on the right side.","h2":"In Nebraska, on one-way streets in urban areas, bicyclists may ride in the far left lane.","p":"Right. They may use the far left lane."},"es":{"q":"En Nebraska, en una calle de un solo sentido en la ciudad, ¿por dónde puede ir un ciclista?","o":["Solo por la banqueta","Solo en un carril marcado para bicicletas","Solo en el carril de la extrema derecha","En el carril de la extrema izquierda, si quiere"],"h1":"En estas calles, los ciclistas no tienen que ir del lado derecho.","h2":"En Nebraska, en calles de un solo sentido en zonas urbanas, los ciclistas pueden ir en el carril de la extrema izquierda.","p":"Correcto. Pueden usar el carril de la extrema izquierda."},"ref":{"doc":"NE","page":69}},{"id":"ne-149","scope":"NE","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nebraska, you drive on a paved county road that is not part of the state highway system. No sign shows the speed limit. What is it?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is 5 mph faster than the limit on a gravel road.","h2":"In Nebraska, the speed limit is 55 mph on a paved road that is not part of the state highway system, unless a sign says otherwise.","p":"Right. It is 55 mph."},"es":{"q":"En Nebraska, usted maneja por un camino pavimentado del condado que no es parte del sistema estatal de carreteras. No hay letrero de límite de velocidad. ¿Cuál es el límite?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es 5 mph más rápido que el límite en un camino de grava.","h2":"En Nebraska, el límite es de 55 mph en un camino pavimentado que no es parte del sistema estatal de carreteras, a menos que un letrero diga otra cosa.","p":"Correcto. Es de 55 mph."},"ref":{"doc":"NE","page":52}},{"id":"ne-150","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, what is the speed limit on an expressway or freeway of the state highway system (not a rural interstate), unless posted otherwise?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"It is 5 mph less than on rural interstates.","h2":"In Nebraska, the speed limit on expressways, super-two highways and freeways of the state highway system is 70 mph, unless posted otherwise.","p":"Right. It is 70 mph."},"es":{"q":"En Nebraska, ¿cuál es el límite de velocidad en una autovía o autopista del sistema estatal de carreteras (no una interestatal rural), si no hay otro letrero?","o":["70 mph","60 mph","65 mph","75 mph"],"h1":"Es 5 mph menos que en las interestatales rurales.","h2":"En Nebraska, el límite en las autovías, carreteras \"super-two\" y autopistas del sistema estatal de carreteras es de 70 mph, si no hay otro letrero.","p":"Correcto. Es de 70 mph."},"ref":{"doc":"NE","page":52}},{"id":"ne-151","scope":"NE","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nebraska, you drive on a state highway that is not an expressway, super-two highway or freeway. No sign shows the limit. What is it?","o":["50 mph","55 mph","60 mph","65 mph"],"h1":"It is 10 mph more than on a paved county road.","h2":"In Nebraska, the speed limit on the state highway system, other than expressways, super-two highways and freeways, is 65 mph unless posted otherwise.","p":"Right. It is 65 mph."},"es":{"q":"En Nebraska, usted maneja por una carretera estatal que no es autovía, carretera \"super-two\" ni autopista. No hay letrero de límite. ¿Cuál es?","o":["50 mph","55 mph","60 mph","65 mph"],"h1":"Es 10 mph más que en un camino pavimentado del condado.","h2":"En Nebraska, el límite en el sistema estatal de carreteras, fuera de autovías, carreteras \"super-two\" y autopistas, es de 65 mph si no hay otro letrero.","p":"Correcto. Es de 65 mph."},"ref":{"doc":"NE","page":52}},{"id":"ne-152","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, you must make an emergency stop at the side of the road. How close to the curb or road edge should you park?","o":["Within 6 inches","Within 12 inches","Within 24 inches","Within 3 feet"],"h1":"It is about one foot.","h2":"In Nebraska, for an emergency roadside stop, park parallel to and within 12 inches of the curb or road edge.","p":"Right. Park within 12 inches."},"es":{"q":"En Nebraska, usted debe hacer una parada de emergencia al lado del camino. ¿A qué distancia de la acera o del borde del camino debe estacionarse?","o":["A no más de 6 pulgadas","A no más de 12 pulgadas","A no más de 24 pulgadas","A no más de 3 pies"],"h1":"Es como un pie.","h2":"En Nebraska, en una parada de emergencia, estaciónese en paralelo y a no más de 12 pulgadas de la acera o del borde del camino.","p":"Correcto. A no más de 12 pulgadas."},"ref":{"doc":"NE","page":56}},{"id":"ne-153","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, no police officer looked into your crash and no one was hurt. You must send a crash report if damage to one person's property reaches at least what amount?","o":["$500","$1,500","$2,500","$5,000"],"h1":"It is more than $1,000 but less than $2,000.","h2":"In Nebraska, if police did not investigate, you must send a crash report within 10 days when damage to any one person's property is $1,500 or more.","p":"Right. The amount is $1,500."},"es":{"q":"En Nebraska, ningún policía investigó su choque y nadie se lastimó. Usted debe enviar un reporte del choque si el daño a la propiedad de una persona llega por lo menos a ¿qué cantidad?","o":["$500","$1,500","$2,500","$5,000"],"h1":"Es más de $1,000 pero menos de $2,000.","h2":"En Nebraska, si la policía no investigó, usted debe enviar un reporte del choque dentro de 10 días cuando el daño a la propiedad de una persona es de $1,500 o más.","p":"Correcto. La cantidad es $1,500."},"ref":{"doc":"NE","page":73}},{"id":"ne-154","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, how many points are added for failing to report a crash to law enforcement?","o":["1 point","2 points","4 points","6 points"],"h1":"It is the same as for leaving the scene of a crash.","h2":"In Nebraska, failing to report a crash to law enforcement adds 6 points to the driving record.","p":"Right. It adds 6 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por no reportar un choque a la policía?","o":["1 punto","2 puntos","4 puntos","6 puntos"],"h1":"Es lo mismo que por irse del lugar de un choque.","h2":"En Nebraska, no reportar un choque a la policía agrega 6 puntos al historial de manejo.","p":"Correcto. Agrega 6 puntos."},"ref":{"doc":"NE","page":18}},{"id":"ne-155","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, how many points are added for a conviction of motor vehicle homicide?","o":["12 points","4 points","6 points","8 points"],"h1":"It is enough points, all at once, to lose the license.","h2":"In Nebraska, a conviction of motor vehicle homicide adds 12 points to the driving record.","p":"Right. It adds 12 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por una condena de homicidio con vehículo motorizado?","o":["12 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Son suficientes puntos, de una sola vez, para perder la licencia.","h2":"En Nebraska, una condena de homicidio con vehículo motorizado agrega 12 puntos al historial de manejo.","p":"Correcto. Agrega 12 puntos."},"ref":{"doc":"NE","page":18}},{"id":"ne-156","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, how many points are added for willful reckless driving, which is deliberate and on purpose?","o":["3 points","4 points","6 points","12 points"],"h1":"It is one point more than for reckless driving that is not on purpose.","h2":"In Nebraska, willful reckless driving adds 6 points to the driving record.","p":"Right. It adds 6 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por manejo imprudente intencional (willful reckless), es decir, hecho a propósito?","o":["3 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Es un punto más que por el manejo imprudente que no es a propósito.","h2":"En Nebraska, el manejo imprudente intencional agrega 6 puntos al historial de manejo.","p":"Correcto. Agrega 6 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-157","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, how many points are added for negligent driving (indifferent or neglectful)?","o":["2 points","3 points","5 points","6 points"],"h1":"It is one point less than careless driving.","h2":"In Nebraska, negligent driving adds 3 points to the driving record.","p":"Right. It adds 3 points."},"es":{"q":"En Nebraska, ¿cuántos puntos se agregan por manejo negligente (indiferente o descuidado)?","o":["2 puntos","3 puntos","5 puntos","6 puntos"],"h1":"Es un punto menos que el manejo sin cuidado (careless).","h2":"En Nebraska, el manejo negligente agrega 3 puntos al historial de manejo.","p":"Correcto. Agrega 3 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-158","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, a driver fails to yield to a pedestrian, and the pedestrian is hurt. How many points are added?","o":["1 point","2 points","3 points","4 points"],"h1":"It is twice the points for the same mistake when nobody is hurt.","h2":"In Nebraska, failing to yield to a pedestrian who is injured adds 4 points to the driving record.","p":"Right. It adds 4 points."},"es":{"q":"En Nebraska, un conductor no le cede el paso a un peatón, y el peatón resulta herido. ¿Cuántos puntos se agregan?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Es el doble de puntos que por el mismo error cuando nadie sale herido.","h2":"En Nebraska, no ceder el paso a un peatón que resulta herido agrega 4 puntos al historial de manejo.","p":"Correcto. Agrega 4 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-159","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, you are caught driving with a license that has expired. How many points go on your record?","o":["1 point","No points","3 points","6 points"],"h1":"It is the smallest number of points that can be added.","h2":"In Nebraska, driving with an expired license, or with no license ever issued, is a 1-point violation.","p":"Right. It is 1 point."},"es":{"q":"En Nebraska, lo detienen manejando con una licencia vencida. ¿Cuántos puntos se agregan a su historial?","o":["1 punto","Ningún punto","3 puntos","6 puntos"],"h1":"Es la menor cantidad de puntos que se puede agregar.","h2":"En Nebraska, manejar con una licencia vencida, o sin haber tenido nunca una licencia, es una infracción de 1 punto.","p":"Correcto. Es 1 punto."},"ref":{"doc":"NE","page":19}},{"id":"ne-160","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you get a parking ticket. How many points go on your driving record?","o":["1 point","2 points","No points","3 points"],"h1":"Parking is one of the violations the point system leaves out.","h2":"In Nebraska, no points are added for parking violations.","p":"Right. Parking tickets add no points."},"es":{"q":"En Nebraska, usted recibe una multa de estacionamiento. ¿Cuántos puntos se agregan a su historial de manejo?","o":["1 punto","2 puntos","Ningún punto","3 puntos"],"h1":"El estacionamiento es una de las infracciones que el sistema de puntos no cuenta.","h2":"En Nebraska, no se agregan puntos por infracciones de estacionamiento.","p":"Correcto. Las multas de estacionamiento no agregan puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-161","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, you are ticketed for driving 7 mph over the limit on a highway outside city limits. How many points are added?","o":["No points","1 point","2 points","3 points"],"h1":"Outside city limits, this is one point less than the same speed inside a city.","h2":"In Nebraska, speeding more than 5 and up to 10 mph over the limit outside city limits adds 1 point.","p":"Right. It adds 1 point."},"es":{"q":"En Nebraska, le dan una multa por manejar 7 mph sobre el límite en una carretera fuera de los límites de la ciudad. ¿Cuántos puntos se agregan?","o":["Ningún punto","1 punto","2 puntos","3 puntos"],"h1":"Fuera de la ciudad, es un punto menos que la misma velocidad dentro de la ciudad.","h2":"En Nebraska, exceder el límite por más de 5 y hasta 10 mph fuera de los límites de la ciudad agrega 1 punto.","p":"Correcto. Agrega 1 punto."},"ref":{"doc":"NE","page":19}},{"id":"ne-162","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a driver is convicted of going 25 mph over the speed limit. How many points are added?","o":["1 point","2 points","3 points","4 points"],"h1":"Four points are only for going more than 35 mph over.","h2":"In Nebraska, speeding 25 mph over the limit adds 3 points, inside or outside city limits.","p":"Right. It adds 3 points."},"es":{"q":"En Nebraska, condenan a un conductor por ir 25 mph sobre el límite de velocidad. ¿Cuántos puntos se agregan?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Los 4 puntos son solo para más de 35 mph sobre el límite.","h2":"En Nebraska, ir 25 mph sobre el límite agrega 3 puntos, dentro o fuera de los límites de la ciudad.","p":"Correcto. Agrega 3 puntos."},"ref":{"doc":"NE","page":19}},{"id":"ne-163","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a driver with a commercial driver's license (CDL) finishes a driver improvement course. Can they get the 2-point credit?","o":["Yes, once every five years","Yes, once every two years","Yes, but only 1 point","No, CDL holders cannot get it"],"h1":"The manual names one group of license holders who are left out.","h2":"In Nebraska, CDL and CLP holders are not eligible for the 2-point credit for a driver improvement course.","p":"Right. CDL holders cannot get the credit."},"es":{"q":"En Nebraska, un conductor con licencia comercial (CDL) termina un curso de mejoramiento para conductores. ¿Puede recibir el crédito de 2 puntos?","o":["Sí, una vez cada cinco años","Sí, una vez cada dos años","Sí, pero solo de 1 punto","No, quienes tienen CDL no pueden recibirlo"],"h1":"El manual nombra un grupo de titulares de licencia que queda fuera.","h2":"En Nebraska, quienes tienen CDL o CLP no pueden recibir el crédito de 2 puntos por un curso de mejoramiento.","p":"Correcto. Quienes tienen CDL no pueden recibir el crédito."},"ref":{"doc":"NE","page":19}},{"id":"ne-164","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, a driver under 21 is convicted of refusing an alcohol test. How long does this conviction stay on the driving record?","o":["120 days","30 days","90 days","Five years"],"h1":"It stays a little longer than the 90-day impoundment.","h2":"In Nebraska, an underage refusal conviction stays on the driving record for 120 days and is then deleted.","p":"Right. It stays for 120 days."},"es":{"q":"En Nebraska, un conductor menor de 21 años es condenado por negarse a una prueba de alcohol. ¿Cuánto tiempo queda esta condena en su historial de manejo?","o":["120 días","30 días","90 días","Cinco años"],"h1":"Queda un poco más que la retención de 90 días.","h2":"En Nebraska, una condena por negarse a la prueba siendo menor de 21 queda en el historial 120 días y después se borra.","p":"Correcto. Queda 120 días."},"ref":{"doc":"NE","page":20}},{"id":"ne-165","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, after a DUI arrest, a driver asks for a hearing to fight the administrative license revocation. Can they get an ignition interlock permit to drive meanwhile?","o":["Yes, right away","No, not until a court orders it in the DUI sentence","Yes, after 15 days","Yes, if they pay a fee"],"h1":"Asking for a hearing has a cost when it comes to permits.","h2":"In Nebraska, a driver who asks for an ALR hearing may not get an ignition interlock permit until a court orders it as part of the DUI sentence.","p":"Right. Not until the court orders it."},"es":{"q":"En Nebraska, después de un arresto por DUI, un conductor pide una audiencia para pelear la revocación administrativa de su licencia. ¿Puede obtener mientras tanto un permiso con dispositivo de bloqueo de encendido (interlock)?","o":["Sí, de inmediato","No, hasta que un juez lo ordene en la sentencia por DUI","Sí, después de 15 días","Sí, si paga una cuota"],"h1":"Pedir una audiencia tiene un costo en cuanto a permisos.","h2":"En Nebraska, un conductor que pide una audiencia de revocación administrativa no puede obtener un permiso interlock hasta que un juez lo ordene como parte de la sentencia por DUI.","p":"Correcto. Hasta que el juez lo ordene."},"ref":{"doc":"NE","page":20}},{"id":"ne-166","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a driver with a prior offense fails an alcohol test. After the temporary license expires, how long must they wait to apply for an ignition interlock permit?","o":["No wait","15 days","45 days","90 days"],"h1":"It is half the wait for someone who refused the test.","h2":"In Nebraska, a repeat offender must wait 45 days after the temporary license expires to apply for an ignition interlock permit.","p":"Right. They wait 45 days."},"es":{"q":"En Nebraska, un conductor con una infracción anterior falla una prueba de alcohol. Después de que vence la licencia temporal, ¿cuánto debe esperar para pedir un permiso interlock?","o":["No tiene que esperar","15 días","45 días","90 días"],"h1":"Es la mitad de la espera de alguien que se negó a la prueba.","h2":"En Nebraska, un infractor reincidente debe esperar 45 días después de que vence la licencia temporal para pedir un permiso interlock.","p":"Correcto. Espera 45 días."},"ref":{"doc":"NE","page":21}},{"id":"ne-167","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, a driver refused a chemical test. After the temporary license expires, how long must they wait to apply for an ignition interlock permit?","o":["15 days","30 days","45 days","90 days"],"h1":"Refusing brings the longest wait.","h2":"In Nebraska, a driver who refused a test must wait 90 days after the temporary license expires to apply for an ignition interlock permit.","p":"Right. They wait 90 days."},"es":{"q":"En Nebraska, un conductor se negó a una prueba química. Después de que vence la licencia temporal, ¿cuánto debe esperar para pedir un permiso interlock?","o":["15 días","30 días","45 días","90 días"],"h1":"Negarse trae la espera más larga.","h2":"En Nebraska, un conductor que se negó a la prueba debe esperar 90 días después de que vence la licencia temporal para pedir un permiso interlock.","p":"Correcto. Espera 90 días."},"ref":{"doc":"NE","page":22}},{"id":"ne-168","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, an 18-year-old is convicted of minor in possession of alcohol for the first time. How long does the court impound the license?","o":["30 days","90 days","6 months","12 months"],"h1":"A second offense brings 90 days, so the first is shorter.","h2":"In Nebraska, a first conviction for minor in possession means the court impounds the permit or license for 30 days.","p":"Right. It is 30 days."},"es":{"q":"En Nebraska, una persona de 18 años es condenada por primera vez por posesión de alcohol siendo menor. ¿Por cuánto tiempo retiene el juez la licencia?","o":["30 días","90 días","6 meses","12 meses"],"h1":"Una segunda vez son 90 días, así que la primera es menos.","h2":"En Nebraska, una primera condena por posesión de alcohol siendo menor hace que el juez retenga el permiso o la licencia por 30 días.","p":"Correcto. Son 30 días."},"ref":{"doc":"NE","page":22}},{"id":"ne-169","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a license is revoked under the point system, and the driver gets a Medical Hardship Driving Permit. Where may they drive?","o":["Anywhere during daylight","From home or work to a doctor, clinic or hospital for treatment, and back","Only to and from school","Anywhere within their county"],"h1":"The name of the permit tells you its purpose.","h2":"In Nebraska, a Medical Hardship Driving Permit allows driving only from home or work to a named medical place for treatment, and back.","p":"Right. Only to get medical treatment and back."},"es":{"q":"En Nebraska, a un conductor le revocan la licencia por el sistema de puntos y recibe un permiso por necesidad médica (Medical Hardship Driving Permit). ¿A dónde puede manejar?","o":["A cualquier lugar de día","De su casa o trabajo a un médico, clínica u hospital para tratamiento, y de regreso","Solo a la escuela y de regreso","A cualquier lugar de su condado"],"h1":"El nombre del permiso dice para qué es.","h2":"En Nebraska, el permiso por necesidad médica solo permite manejar de la casa o el trabajo a un lugar médico señalado para recibir tratamiento, y de regreso.","p":"Correcto. Solo para recibir tratamiento médico y regresar."},"ref":{"doc":"NE","page":22}},{"id":"ne-170","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a driver is criminally convicted of refusing a chemical test. The criminal penalties are the same as for which conviction?","o":["A seat belt ticket","A DUI with a BAC of .02","A DUI with a BAC of .15 or over","Careless driving"],"h1":"Refusing is treated like one of the most serious kinds of DUI.","h2":"In Nebraska, criminal penalties for refusing a chemical test are the same as for a DUI conviction with a BAC of .15 or over.","p":"Right. They match a DUI at .15 or over."},"es":{"q":"En Nebraska, un conductor es condenado penalmente por negarse a una prueba química. ¿Las penas penales son iguales a las de cuál condena?","o":["Una multa por no usar cinturón","Un DUI con nivel de alcohol de .02","Un DUI con nivel de alcohol de .15 o más","Manejo sin cuidado"],"h1":"Negarse se trata como uno de los tipos de DUI más graves.","h2":"En Nebraska, las penas penales por negarse a una prueba química son las mismas que por un DUI con un nivel de alcohol de .15 o más.","p":"Correcto. Son iguales a un DUI de .15 o más."},"ref":{"doc":"NE","page":24}},{"id":"ne-171","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you had a seizure or blacked out within the three months before renewing your license. What will you be asked for?","o":["Nothing extra","A new birth certificate","Proof of insurance only","A doctor's statement that you can drive safely"],"h1":"A medical professional must speak to your ability to drive.","h2":"In Nebraska, a person who had a seizure or loss of consciousness within three months before getting or renewing a license must have a physician certify that they can drive safely.","p":"Right. A doctor must certify you can drive safely."},"es":{"q":"En Nebraska, usted tuvo una convulsión o perdió el conocimiento en los tres meses antes de renovar su licencia. ¿Qué le van a pedir?","o":["Nada más","Un acta de nacimiento nueva","Solo comprobante de seguro","Una declaración de un médico de que puede manejar con seguridad"],"h1":"Un profesional de la salud tiene que hablar de su capacidad para manejar.","h2":"En Nebraska, quien tuvo una convulsión o pérdida del conocimiento en los tres meses antes de obtener o renovar una licencia debe tener un médico que certifique que puede manejar con seguridad.","p":"Correcto. Un médico debe certificar que puede manejar con seguridad."},"ref":{"doc":"NE","page":27}},{"id":"ne-172","scope":"NE","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nebraska, is it legal to use nitrous oxide in a motor vehicle on a public road?","o":["No, it is against the law","Yes, if the driver does not use it","Yes, at night only","Yes, if the car is a race car"],"h1":"The manual lists it as a prohibited use.","h2":"In Nebraska, it is unlawful to use nitrous oxide in any motor vehicle on a public road.","p":"Right. It is against the law."},"es":{"q":"En Nebraska, ¿es legal usar óxido nitroso en un vehículo en un camino público?","o":["No, es contra la ley","Sí, si el conductor no lo usa","Sí, solo de noche","Sí, si el carro es de carreras"],"h1":"El manual dice que su uso está prohibido.","h2":"En Nebraska, es ilegal usar óxido nitroso en cualquier vehículo en un camino público.","p":"Correcto. Es contra la ley."},"ref":{"doc":"NE","page":27}},{"id":"ne-173","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, a police officer pulls you over and you have a weapon in the car. When should you tell the officer?","o":["Only if the officer asks","After you get your ticket","At first contact, when the officer comes to your window","Never, it is private"],"h1":"Tell the officer early, before you reach for anything.","h2":"In Nebraska, if you have a weapon in the vehicle, let the officer know at first contact.","p":"Right. Tell the officer at first contact."},"es":{"q":"En Nebraska, un policía lo detiene y usted tiene un arma en el carro. ¿Cuándo debe decírselo al policía?","o":["Solo si el policía pregunta","Después de recibir su multa","En el primer contacto, cuando el policía llega a su ventana","Nunca, es privado"],"h1":"Dígaselo pronto, antes de alcanzar cualquier cosa.","h2":"En Nebraska, si tiene un arma en el vehículo, avísele al policía en el primer contacto.","p":"Correcto. Avísele en el primer contacto."},"ref":{"doc":"NE","page":28}},{"id":"ne-174","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you want to use a birth certificate to prove your identity. Which one will NOT be accepted?","o":["A certified one from a state office","A certified one with a raised seal","A certified one with a stamp","One issued by the hospital"],"h1":"It must come from a government office.","h2":"In Nebraska, hospital-issued birth certificates are not accepted; bring a certified birth certificate from a state government office.","p":"Right. A hospital birth certificate is not accepted."},"es":{"q":"En Nebraska, usted quiere usar un acta de nacimiento para comprobar su identidad. ¿Cuál NO se acepta?","o":["Una certificada de una oficina estatal","Una certificada con sello en relieve","Una certificada con sello","Una emitida por el hospital"],"h1":"Debe venir de una oficina del gobierno.","h2":"En Nebraska, no se aceptan actas de nacimiento emitidas por el hospital; traiga un acta certificada de una oficina del gobierno estatal.","p":"Correcto. El acta del hospital no se acepta."},"ref":{"doc":"NE","page":9}},{"id":"ne-175","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, you bring a bank statement to prove your home address. How recent must it be?","o":["Issued within the last 90 days","Issued within the last year","Issued within the last 30 days","Any date is fine"],"h1":"It is about three months.","h2":"In Nebraska, a bank statement used to prove your address must be issued within the last 90 days.","p":"Right. Within the last 90 days."},"es":{"q":"En Nebraska, usted trae un estado de cuenta del banco para comprobar su domicilio. ¿Qué tan reciente debe ser?","o":["Emitido en los últimos 90 días","Emitido en el último año","Emitido en los últimos 30 días","Cualquier fecha sirve"],"h1":"Son como tres meses.","h2":"En Nebraska, un estado de cuenta del banco usado para comprobar su domicilio debe ser de los últimos 90 días.","p":"Correcto. De los últimos 90 días."},"ref":{"doc":"NE","page":10}},{"id":"ne-176","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you pass your tests and get an Issuance Certificate. How long do you have to take it to the county treasurer?","o":["10 days","30 days","90 days","One year"],"h1":"It is about three months.","h2":"In Nebraska, you must present the Issuance Certificate to a county treasurer, or the state office in Douglas, Lancaster or Sarpy County, within 90 days.","p":"Right. You have 90 days."},"es":{"q":"En Nebraska, usted aprueba sus exámenes y recibe un certificado de emisión (Issuance Certificate). ¿Cuánto tiempo tiene para llevarlo al tesorero del condado?","o":["10 días","30 días","90 días","Un año"],"h1":"Son como tres meses.","h2":"En Nebraska, debe presentar el certificado de emisión a un tesorero del condado, o a la oficina estatal en los condados de Douglas, Lancaster o Sarpy, dentro de 90 días.","p":"Correcto. Tiene 90 días."},"ref":{"doc":"NE","page":12}},{"id":"ne-177","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, a person on active military duty outside the state holds a Nebraska license. How long does it stay valid after discharge or return to Nebraska?","o":["It ends on discharge day","60 days after discharge or return, whichever is later","30 days after discharge","One year after discharge"],"h1":"It is about two months.","h2":"In Nebraska, an eligible service member's license stays valid during active duty and for 60 days after discharge or return to Nebraska, whichever is later.","p":"Right. It stays valid for 60 days after."},"es":{"q":"En Nebraska, una persona en servicio militar activo fuera del estado tiene licencia de Nebraska. ¿Cuánto tiempo sigue válida después de la baja o del regreso a Nebraska?","o":["Termina el día de la baja","60 días después de la baja o del regreso, lo que sea más tarde","30 días después de la baja","Un año después de la baja"],"h1":"Son como dos meses.","h2":"En Nebraska, la licencia de un militar elegible sigue válida durante el servicio activo y 60 días después de la baja o del regreso a Nebraska, lo que sea más tarde.","p":"Correcto. Sigue válida 60 días después."},"ref":{"doc":"NE","page":13}},{"id":"ne-178","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you want to renew your Class O license online. Your license must expire before which birthday?","o":["50th","60th","65th","72nd"],"h1":"It is past the usual retirement age.","h2":"In Nebraska, you may renew a Class O or Class M license online only if it expires before your 72nd birthday.","p":"Right. It must expire before age 72."},"es":{"q":"En Nebraska, usted quiere renovar su licencia Clase O por internet. ¿Antes de qué cumpleaños debe vencer su licencia?","o":["50 años","60 años","65 años","72 años"],"h1":"Es después de la edad común de jubilación.","h2":"En Nebraska, puede renovar una licencia Clase O o Clase M por internet solo si vence antes de que cumpla 72 años.","p":"Correcto. Debe vencer antes de los 72 años."},"ref":{"doc":"NE","page":14}},{"id":"ne-179","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, how many times in a row may you renew a Class O license online?","o":["Two times","One time","Three times","As many times as you want"],"h1":"State ID cards allow one more online renewal than licenses.","h2":"In Nebraska, Class O and Class M license holders may renew online two times in a row.","p":"Right. Two times in a row."},"es":{"q":"En Nebraska, ¿cuántas veces seguidas puede renovar una licencia Clase O por internet?","o":["Dos veces","Una vez","Tres veces","Todas las que quiera"],"h1":"Las tarjetas de identificación estatal permiten una renovación más por internet que las licencias.","h2":"En Nebraska, los titulares de licencia Clase O y Clase M pueden renovar por internet dos veces seguidas.","p":"Correcto. Dos veces seguidas."},"ref":{"doc":"NE","page":14}},{"id":"ne-180","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, you renew 60 days before your 21st birthday. When does the new license become valid?","o":["The same day","30 days before your 21st birthday","On your 21st birthday","60 days after your birthday"],"h1":"You may apply early, but the new card waits a bit.","h2":"In Nebraska, you may renew 60 days before your 21st birthday, but the new license is not valid until 30 days before that birthday.","p":"Right. It is valid 30 days before you turn 21."},"es":{"q":"En Nebraska, usted renueva 60 días antes de cumplir 21 años. ¿Cuándo empieza a ser válida la licencia nueva?","o":["El mismo día","30 días antes de cumplir 21 años","El día que cumple 21 años","60 días después de su cumpleaños"],"h1":"Puede pedirla antes, pero la tarjeta nueva espera un poco.","h2":"En Nebraska, puede renovar 60 días antes de cumplir 21 años, pero la licencia nueva no es válida hasta 30 días antes de ese cumpleaños.","p":"Correcto. Es válida 30 días antes de cumplir 21."},"ref":{"doc":"NE","page":15}},{"id":"ne-181","scope":"NE","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nebraska, you are out of state during your renewal period. Until when may you renew by mail?","o":["Only before the license expires","Up to 30 days after it expires","Up to 90 days after it expires","Up to one year after it expires"],"h1":"The time after expiration is longer than a few months.","h2":"In Nebraska, a person out of state during the renewal period may renew by mail before the license expires or within one year after it expires.","p":"Right. Up to one year after it expires."},"es":{"q":"En Nebraska, usted está fuera del estado durante su período de renovación. ¿Hasta cuándo puede renovar por correo?","o":["Solo antes de que venza la licencia","Hasta 30 días después de que vence","Hasta 90 días después de que vence","Hasta un año después de que vence"],"h1":"El tiempo después del vencimiento es más que unos meses.","h2":"En Nebraska, una persona fuera del estado durante su período de renovación puede renovar por correo antes de que venza la licencia o hasta un año después de que vence.","p":"Correcto. Hasta un año después de que vence."},"ref":{"doc":"NE","page":15}},{"id":"ne-182","scope":"NE","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nebraska, the DMV recalls a driver to retake the written and driving tests. The driver does not show up. What happens?","o":["The license is cancelled","Nothing happens","The driver pays a small fine","The driver gets 1 point"],"h1":"Skipping the exam is treated the same as failing it.","h2":"In Nebraska, a recalled driver who does not report for the exam, send the medical or vision statement, or pass the tests will have the license cancelled.","p":"Right. The license is cancelled."},"es":{"q":"En Nebraska, el DMV llama a un conductor para que repita los exámenes escrito y de manejo. El conductor no se presenta. ¿Qué pasa?","o":["Se cancela la licencia","No pasa nada","El conductor paga una multa pequeña","El conductor recibe 1 punto"],"h1":"No presentarse se trata igual que reprobar.","h2":"En Nebraska, a un conductor llamado a examen que no se presenta, no entrega la declaración médica o de la vista, o no aprueba los exámenes, se le cancela la licencia.","p":"Correcto. Se cancela la licencia."},"ref":{"doc":"NE","page":15}},{"id":"ne-183","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, you get a replacement license and later find your old one. Can you still use the old card as ID?","o":["Yes, until its expiration date","Yes, but only for driving","No, it is no longer valid","Yes, for 30 days"],"h1":"Only one card can be the real one.","h2":"In Nebraska, once a replacement license is issued, the old one is invalid and cannot be used as identification.","p":"Right. The old card is no longer valid."},"es":{"q":"En Nebraska, usted recibe una licencia de reemplazo y después encuentra la anterior. ¿Puede seguir usando la tarjeta anterior como identificación?","o":["Sí, hasta su fecha de vencimiento","Sí, pero solo para manejar","No, ya no es válida","Sí, por 30 días"],"h1":"Solo una tarjeta puede ser la válida.","h2":"En Nebraska, una vez que se emite una licencia de reemplazo, la anterior ya no es válida y no puede usarse como identificación.","p":"Correcto. La tarjeta anterior ya no es válida."},"ref":{"doc":"NE","page":16}},{"id":"ne-184","scope":"NE","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nebraska, what does restriction code E on a driver's license mean?","o":["Outside mirrors needed","Automatic transmission only","No interstate driving","Daylight driving only"],"h1":"It is about the type of gear shifting in the car.","h2":"In Nebraska, restriction code E means the driver is limited to vehicles with an automatic transmission.","p":"Right. E means automatic transmission."},"es":{"q":"En Nebraska, ¿qué significa el código de restricción E en una licencia de manejo?","o":["Necesita espejos exteriores","Solo transmisión automática","No puede manejar en la interestatal","Solo puede manejar de día"],"h1":"Tiene que ver con el tipo de cambio de velocidades del carro.","h2":"En Nebraska, el código de restricción E significa que el conductor está limitado a vehículos con transmisión automática.","p":"Correcto. E significa transmisión automática."},"ref":{"doc":"NE","page":16}},{"id":"ne-185","scope":"NE","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nebraska, an ATV needs to cross a two-lane highway. How must it cross?","o":["At any angle, without stopping","Along the shoulder until a gap appears","Only at night with lights off","After a complete stop, at about a 90-degree angle"],"h1":"Think straight across, not on a slant.","h2":"In Nebraska, an ATV or UTV must come to a complete stop and cross a highway at about a 90-degree angle, yielding to all oncoming traffic, with the headlight and taillight on.","p":"Right. Stop, then cross straight across."},"es":{"q":"En Nebraska, un vehículo todoterreno (ATV) necesita cruzar una carretera de dos carriles. ¿Cómo debe cruzar?","o":["En cualquier ángulo, sin detenerse","Por el acotamiento hasta que haya espacio","Solo de noche con las luces apagadas","Después de un alto total, en un ángulo de unos 90 grados"],"h1":"Piense en cruzar derecho, no en diagonal.","h2":"En Nebraska, un ATV o UTV debe hacer un alto total y cruzar la carretera en un ángulo de unos 90 grados, cediendo el paso a todo el tráfico, con el faro y la luz trasera encendidos.","p":"Correcto. Alto total y cruzar derecho."},"ref":{"doc":"NE","page":7}},{"id":"ne-186","scope":"NE","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nebraska, an ATV operator needs to cross a divided highway. Where may they cross?","o":["Only at an intersection","Anywhere the median is flat","At any farm field entrance","Wherever no car is in sight"],"h1":"Look for a place where roads meet.","h2":"In Nebraska, an ATV or UTV may cross a divided highway only at an intersection.","p":"Right. Only at an intersection."},"es":{"q":"En Nebraska, el conductor de un ATV necesita cruzar una carretera dividida. ¿Dónde puede cruzar?","o":["Solo en una intersección","Donde el camellón sea plano","En cualquier entrada a un campo","Donde no se vea ningún carro"],"h1":"Busque un lugar donde se juntan los caminos.","h2":"En Nebraska, un ATV o UTV solo puede cruzar una carretera dividida en una intersección.","p":"Correcto. Solo en una intersección."},"ref":{"doc":"NE","page":7}},{"id":"ne-187","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a teen does not live on a farm but is paid to work on one. What is the youngest age for a Farm Husbandry Permit?","o":["12","13","14","15"],"h1":"It is one year older than for a teen who lives on a farm.","h2":"In Nebraska, a teen employed on a farm for pay may get a Farm Husbandry Permit at age 14.","p":"Right. The youngest age is 14."},"es":{"q":"En Nebraska, un adolescente no vive en una granja, pero le pagan por trabajar en una. ¿Cuál es la edad mínima para un permiso agrícola (Farm Husbandry Permit)?","o":["12","13","14","15"],"h1":"Es un año más que para un adolescente que vive en una granja.","h2":"En Nebraska, un adolescente que trabaja con pago en una granja puede obtener el permiso agrícola a los 14 años.","p":"Correcto. La edad mínima es 14."},"ref":{"doc":"NE","page":2}},{"id":"ne-188","scope":"NE","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nebraska, you are caught going 18 mph over the limit on a normal road (not a school or work zone). What is the fine, before court costs?","o":["$75","$125","$200","$250"],"h1":"It is more than $100 but less than $150.","h2":"In Nebraska, the fine for going 16 to 20 mph over the limit outside school and work zones is $125, plus court costs.","p":"Right. The fine is $125."},"es":{"q":"En Nebraska, lo detienen yendo 18 mph sobre el límite en un camino normal (no en zona escolar ni de obras). ¿Cuál es la multa, sin contar los costos de corte?","o":["$75","$125","$200","$250"],"h1":"Es más de $100 pero menos de $150.","h2":"En Nebraska, la multa por ir de 16 a 20 mph sobre el límite fuera de zonas escolares y de obras es de $125, más costos de corte.","p":"Correcto. La multa es de $125."},"ref":{"doc":"NE","page":53}},{"id":"ne-189","scope":"NE","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nebraska, you drive 25 mph over the limit in a work zone while workers are present. What is the fine, before court costs?","o":["$125","$200","$300","$400"],"h1":"Fines double in work zones with workers; the normal fine is $200.","h2":"In Nebraska, going 21 to 35 mph over the limit in a work zone with workers present brings a $400 fine, plus court costs.","p":"Right. The fine is $400."},"es":{"q":"En Nebraska, usted maneja 25 mph sobre el límite en una zona de obras con trabajadores presentes. ¿Cuál es la multa, sin contar los costos de corte?","o":["$125","$200","$300","$400"],"h1":"Las multas se duplican en zonas de obras con trabajadores; la multa normal es de $200.","h2":"En Nebraska, ir de 21 a 35 mph sobre el límite en una zona de obras con trabajadores presentes trae una multa de $400, más costos de corte.","p":"Correcto. La multa es de $400."},"ref":{"doc":"NE","page":53}},{"id":"ne-190","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, what is the highest fine for a third offense of parking illegally in a handicapped space?","o":["$150","$300","$500","$1,000"],"h1":"The fine goes up with each offense: $150, then $300, then this.","h2":"In Nebraska, a third offense of illegal handicapped parking brings a fine of up to $500.","p":"Right. Up to $500."},"es":{"q":"En Nebraska, ¿cuál es la multa más alta por la tercera vez que se estaciona ilegalmente en un espacio para personas con discapacidad?","o":["$150","$300","$500","$1,000"],"h1":"La multa sube con cada vez: $150, después $300, y después esta.","h2":"En Nebraska, la tercera infracción por estacionarse ilegalmente en un espacio para personas con discapacidad tiene una multa de hasta $500.","p":"Correcto. Hasta $500."},"ref":{"doc":"NE","page":57}},{"id":"ne-191","scope":"NE","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nebraska, what does the manual say is the fine range for texting while driving?","o":["$25 to $50","$200 to $500","$100 to $150","$1,000 or more"],"h1":"The low end is the same as the first-offense fine for a teen using a phone.","h2":"In Nebraska, the manual says the fine for texting and driving is $200 to $500.","p":"Right. It is $200 to $500."},"es":{"q":"En Nebraska, según el manual, ¿cuál es el rango de la multa por enviar mensajes de texto mientras maneja?","o":["$25 a $50","$200 a $500","$100 a $150","$1,000 o más"],"h1":"La cantidad más baja es igual a la multa de primera vez para un adolescente que usa el teléfono.","h2":"En Nebraska, el manual dice que la multa por enviar mensajes de texto y manejar es de $200 a $500.","p":"Correcto. Es de $200 a $500."},"ref":{"doc":"NE","page":64}},{"id":"ne-192","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, the manual says to turn on your headlights at certain times during the day. Which is one of them?","o":["Only on the interstate","Only when you pass a truck","Only in a school zone","Whenever you use your windshield wipers"],"h1":"Think of weather when you need to clear the glass.","h2":"In Nebraska, the manual says to use your headlights whenever you use your windshield wipers, and any time it is hard to see other vehicles.","p":"Right. Use headlights whenever the wipers are on."},"es":{"q":"En Nebraska, el manual dice que encienda los faros en ciertos momentos durante el día. ¿Cuál es uno de ellos?","o":["Solo en la interestatal","Solo al rebasar un camión","Solo en una zona escolar","Siempre que use los limpiaparabrisas"],"h1":"Piense en el clima, cuando necesita limpiar el vidrio.","h2":"En Nebraska, el manual dice que use los faros siempre que use los limpiaparabrisas, y cuando le cueste ver a otros vehículos.","p":"Correcto. Use los faros siempre que tenga los limpiaparabrisas encendidos."},"ref":{"doc":"NE","page":66}},{"id":"ne-193","scope":"NE","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nebraska, you are following a motorcycle. How much following distance does the manual suggest?","o":["One second","Two seconds","Three or four seconds","Ten seconds"],"h1":"It is at least the usual three-second rule, or a bit more.","h2":"In Nebraska, the manual says to allow three or four seconds of following distance behind a motorcycle.","p":"Right. Three or four seconds."},"es":{"q":"En Nebraska, usted va detrás de una motocicleta. ¿Cuánta distancia de seguimiento sugiere el manual?","o":["Un segundo","Dos segundos","Tres o cuatro segundos","Diez segundos"],"h1":"Es por lo menos la regla normal de tres segundos, o un poco más.","h2":"En Nebraska, el manual dice que deje tres o cuatro segundos de distancia detrás de una motocicleta.","p":"Correcto. Tres o cuatro segundos."},"ref":{"doc":"NE","page":68}},{"id":"ne-194","scope":"NE","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nebraska, you are on the highway near a truck weigh station. Which lane does the manual say to avoid?","o":["The right lane","The left lane","The middle lane","The shoulder only"],"h1":"Slow trucks will be coming back onto the road there.","h2":"In Nebraska, the manual says to avoid the right lane near truck weigh stations, where slow trucks re-enter faster traffic.","p":"Right. Avoid the right lane."},"es":{"q":"En Nebraska, usted va por la carretera cerca de una estación de pesaje de camiones. ¿Qué carril dice el manual que evite?","o":["El carril derecho","El carril izquierdo","El carril del centro","Solo el acotamiento"],"h1":"Por ahí regresan al camino camiones lentos.","h2":"En Nebraska, el manual dice que evite el carril derecho cerca de las estaciones de pesaje, donde los camiones lentos vuelven al tráfico más rápido.","p":"Correcto. Evite el carril derecho."},"ref":{"doc":"NE","page":71}},{"id":"ne-195","scope":"NE","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nebraska, you are stranded in your car during a blizzard. What does the manual say to do?","o":["Walk to the nearest house for help","Keep the engine running with all windows shut","Turn off all lights to save the battery","Stay with the car and run the engine and heater only now and then, with a window slightly open"],"h1":"Leaving the car or sealing it up are both dangerous.","h2":"In Nebraska, if stranded in a blizzard, stay with the vehicle, run the engine and heater sparingly with a window slightly open, and keep snow away from the tailpipe.","p":"Right. Stay with the car and use the heater carefully."},"es":{"q":"En Nebraska, usted queda atrapado en su carro durante una ventisca de nieve. ¿Qué dice el manual que haga?","o":["Caminar a la casa más cercana a pedir ayuda","Dejar el motor encendido con todas las ventanas cerradas","Apagar todas las luces para ahorrar batería","Quedarse en el carro y prender el motor y la calefacción solo de vez en cuando, con una ventana un poco abierta"],"h1":"Salir del carro o cerrarlo por completo son peligrosos.","h2":"En Nebraska, si queda atrapado en una ventisca, quédese en el vehículo, use el motor y la calefacción poco y con una ventana un poco abierta, y no deje que la nieve tape el escape.","p":"Correcto. Quédese en el carro y use la calefacción con cuidado."},"ref":{"doc":"NE","page":63}},{"id":"ne-196","scope":"NE","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nebraska, a new resident age 30 cannot turn in their old out-of-state license. Besides the vision test, what test is required?","o":["None","A motorcycle test","The written test","A medical exam"],"h1":"Handing in a valid old license is what lets you skip this test.","h2":"In Nebraska, a new resident 18 or older who cannot surrender the out-of-state license, or whose license has expired, must take the written test.","p":"Right. The written test is required."},"es":{"q":"En Nebraska, un nuevo residente de 30 años no puede entregar su licencia anterior de otro estado. Además del examen de la vista, ¿qué examen se requiere?","o":["Ninguno","Un examen de motocicleta","El examen escrito","Un examen médico"],"h1":"Entregar una licencia anterior válida es lo que le permite saltarse este examen.","h2":"En Nebraska, un nuevo residente de 18 años o más que no puede entregar su licencia de otro estado, o cuya licencia está vencida, debe hacer el examen escrito.","p":"Correcto. Se requiere el examen escrito."},"ref":{"doc":"NE","page":5}},{"id":"nh-001","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, what score do you need to pass a knowledge test?","o":["60 percent","70 percent","80 percent","90 percent"],"h1":"It is the same as getting 4 out of 5 right.","h2":"Every New Hampshire knowledge test requires a passing grade of 80 percent.","p":"Right. You need 80 percent."},"es":{"q":"En New Hampshire, ¿qué puntaje necesita para aprobar un examen de conocimientos?","o":["60 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Es lo mismo que acertar 4 de cada 5.","h2":"Todos los exámenes de conocimientos en New Hampshire exigen una nota mínima del 80 por ciento.","p":"Correcto. Necesita el 80 por ciento."},"zh":{"q":"在 New Hampshire，笔试要得多少分才能通过？","o":["60%","70%","80%","90%"],"h1":"它等于 5 道题答对 4 道。","h2":"New Hampshire 的每一种笔试都要求得到 80% 才能通过。","p":"对。你需要 80%。"},"vi":{"q":"Ở New Hampshire, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["60 phần trăm","70 phần trăm","80 phần trăm","90 phần trăm"],"h1":"Điều này giống như trả lời đúng 4 trên 5 câu.","h2":"Mọi bài thi kiến thức ở New Hampshire đều cần điểm đậu là 80 phần trăm.","p":"Đúng. Bạn cần 80 phần trăm."},"tl":{"q":"Sa New Hampshire, anong iskor ang kailangan mo para pumasa sa knowledge test?","o":["60 porsiyento","70 porsiyento","80 porsiyento","90 porsiyento"],"h1":"Pareho ito ng pagkuha ng 4 na tama sa 5.","h2":"Bawat knowledge test sa New Hampshire ay nangangailangan ng pasadong marka na 80 porsiyento.","p":"Tama. Kailangan mo ng 80 porsiyento."},"ar":{"q":"في New Hampshire، ما الدرجة التي تحتاجها لتنجح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة","70 بالمئة","80 بالمئة","90 بالمئة"],"h1":"هذا مثل أن تجيب إجابة صحيحة عن 4 من 5.","h2":"كل اختبار معرفة في New Hampshire يحتاج إلى درجة نجاح 80 بالمئة.","p":"صحيح. تحتاج إلى 80 بالمئة."},"ref":{"doc":"NH","page":2}},{"id":"nh-002","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the youngest age to practice driving on public roads with a licensed adult?","o":["15","15 and a half","16","14 and a half"],"h1":"It is six months before the age of 16.","h2":"In New Hampshire a teen may start practice driving at 15 and a half, with a licensed adult in the front seat.","p":"Correct. Practice starts at 15 and a half."},"es":{"q":"En New Hampshire, ¿cuál es la edad mínima para practicar manejo en las calles con un adulto con licencia?","o":["15 años","15 años y medio","16 años","14 años y medio"],"h1":"Es seis meses antes de cumplir 16 años.","h2":"En New Hampshire un joven puede empezar a practicar a los 15 años y medio, con un adulto con licencia en el asiento delantero.","p":"Correcto. La práctica empieza a los 15 años y medio."},"zh":{"q":"在 New Hampshire，最小几岁可以和有驾照的成年人一起在公共道路上练习开车？","o":["15 岁","15 岁半","16 岁","14 岁半"],"h1":"是 16 岁前六个月。","h2":"在 New Hampshire，青少年 15 岁半就可以开始练习开车，前排要有一位有驾照的成年人。","p":"对。15 岁半开始练习。"},"vi":{"q":"Ở New Hampshire, tuổi nhỏ nhất để tập lái trên đường công cộng cùng một người lớn có bằng lái là bao nhiêu?","o":["15","15 tuổi rưỡi","16","14 tuổi rưỡi"],"h1":"Đó là sáu tháng trước tuổi 16.","h2":"Ở New Hampshire, thiếu niên có thể bắt đầu tập lái khi 15 tuổi rưỡi, với một người lớn có bằng lái ngồi ở ghế trước.","p":"Đúng. Tập lái bắt đầu lúc 15 tuổi rưỡi."},"tl":{"q":"Sa New Hampshire, ano ang pinakabatang edad para mag-praktis magmaneho sa pampublikong kalsada kasama ang isang adult na may lisensya?","o":["15","15 at kalahati","16","14 at kalahati"],"h1":"Anim na buwan ito bago ang edad na 16.","h2":"Sa New Hampshire, puwedeng magsimulang mag-praktis magmaneho ang isang teen sa edad na 15 at kalahati, kasama ang isang adult na may lisensya sa upuan sa harap.","p":"Tama. Nagsisimula ang praktis sa 15 at kalahati."},"ar":{"q":"في New Hampshire، ما أصغر عمر للتدرّب على القيادة في الطرق العامة مع شخص بالغ يحمل رخصة؟","o":["15","15 سنة ونصف","16","14 سنة ونصف"],"h1":"هذا العمر قبل 16 سنة بستة أشهر.","h2":"في New Hampshire يمكن للمراهق أن يبدأ التدرّب على القيادة في عمر 15 سنة ونصف، مع شخص بالغ يحمل رخصة في المقعد الأمامي.","p":"صحيح. التدرّب يبدأ في عمر 15 سنة ونصف."},"ref":{"doc":"NH","page":2}},{"id":"nh-004","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, how old must the licensed adult be who supervises a teen's practice driving?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"It is older than the drinking age.","h2":"In New Hampshire the adult who supervises practice driving must be licensed and at least 25 years old.","p":"Correct. The adult must be 25 or older."},"es":{"q":"En New Hampshire, ¿qué edad debe tener el adulto con licencia que supervisa la práctica de un joven?","o":["Por lo menos 18","Por lo menos 19","Por lo menos 21","Por lo menos 25"],"h1":"Es mayor que la edad legal para tomar alcohol.","h2":"En New Hampshire el adulto que supervisa la práctica debe tener licencia y por lo menos 25 años.","p":"Correcto. El adulto debe tener 25 años o más."},"zh":{"q":"在 New Hampshire，陪同青少年练习开车的有驾照成年人必须几岁？","o":["至少 18 岁","至少 19 岁","至少 21 岁","至少 25 岁"],"h1":"它比可以喝酒的年龄还大。","h2":"在 New Hampshire，陪同练习开车的成年人必须有驾照，而且至少 25 岁。","p":"对。这位成年人必须 25 岁或以上。"},"vi":{"q":"Ở New Hampshire, người lớn có bằng lái giám sát thiếu niên tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 19 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Tuổi này lớn hơn tuổi được phép uống rượu.","h2":"Ở New Hampshire, người lớn giám sát việc tập lái phải có bằng lái và ít nhất 25 tuổi.","p":"Đúng. Người lớn phải từ 25 tuổi trở lên."},"tl":{"q":"Sa New Hampshire, ilang taon dapat ang adult na may lisensya na nagbabantay sa praktis sa pagmamaneho ng isang teen?","o":["Hindi bababa sa 18","Hindi bababa sa 19","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Mas matanda ito sa edad na puwedeng uminom ng alak.","h2":"Sa New Hampshire, ang adult na nagbabantay sa praktis sa pagmamaneho ay dapat may lisensya at hindi bababa sa 25 taong gulang.","p":"Tama. Dapat 25 o higit pa ang adult."},"ar":{"q":"في New Hampshire، كم يجب أن يكون عمر الشخص البالغ الذي يحمل رخصة ويشرف على تدرّب المراهق على القيادة؟","o":["18 سنة على الأقل","19 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"هذا العمر أكبر من العمر المسموح فيه بشرب الكحول.","h2":"في New Hampshire يجب أن يحمل الشخص البالغ الذي يشرف على التدرّب على القيادة رخصة، وأن يكون عمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ 25 سنة أو أكثر."},"ref":{"doc":"NH","page":1}},{"id":"nh-005","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, who must take driver education to get a license?","o":["Everyone, at any age","Only drivers over 65","Applicants under 18","Only drivers from another country"],"h1":"It depends on the applicant's age.","h2":"In New Hampshire driver education is required for anyone under 18 who applies for a driver license.","p":"Right. Under 18 needs driver education."},"es":{"q":"En New Hampshire, ¿quién debe tomar un curso de educación vial para obtener la licencia?","o":["Todos, a cualquier edad","Solo los mayores de 65","Los solicitantes menores de 18 años","Solo los conductores de otro país"],"h1":"Depende de la edad de la persona.","h2":"En New Hampshire el curso de educación vial es obligatorio para toda persona menor de 18 años que solicita una licencia.","p":"Correcto. Menor de 18 necesita educación vial."},"zh":{"q":"在 New Hampshire，谁必须上驾驶教育课才能拿驾照？","o":["每个人，不管几岁","只有 65 岁以上的司机","18 岁以下的申请人","只有来自其他国家的司机"],"h1":"这要看申请人的年龄。","h2":"在 New Hampshire，任何 18 岁以下申请驾照的人都必须上驾驶教育课。","p":"对。18 岁以下需要驾驶教育。"},"vi":{"q":"Ở New Hampshire, ai phải học giáo dục lái xe (driver education) để có bằng lái?","o":["Mọi người, ở bất kỳ tuổi nào","Chỉ người lái xe trên 65 tuổi","Người nộp đơn dưới 18 tuổi","Chỉ người lái xe từ nước khác"],"h1":"Điều này tùy theo tuổi của người nộp đơn.","h2":"Ở New Hampshire, bất kỳ ai dưới 18 tuổi nộp đơn xin bằng lái đều phải học giáo dục lái xe.","p":"Đúng. Dưới 18 tuổi cần học giáo dục lái xe."},"tl":{"q":"Sa New Hampshire, sino ang dapat kumuha ng driver education para magkaroon ng lisensya?","o":["Lahat, kahit anong edad","Mga driver lang na higit sa 65","Mga aplikanteng wala pang 18","Mga driver lang na galing sa ibang bansa"],"h1":"Depende ito sa edad ng aplikante.","h2":"Sa New Hampshire, kailangan ang driver education para sa sinumang wala pang 18 na nag-a-apply ng driver license.","p":"Tama. Kailangan ng driver education kung wala pang 18."},"ar":{"q":"في New Hampshire، من يجب أن يأخذ دورة تعليم القيادة (driver education) ليحصل على رخصة؟","o":["الجميع، في أي عمر","السائقون الذين تزيد أعمارهم عن 65 سنة فقط","المتقدّمون الذين أعمارهم أقل من 18 سنة","السائقون القادمون من بلد آخر فقط"],"h1":"هذا يعتمد على عمر المتقدّم.","h2":"في New Hampshire تعليم القيادة مطلوب من كل شخص عمره أقل من 18 سنة يتقدّم للحصول على رخصة قيادة.","p":"صحيح. من عمره أقل من 18 سنة يحتاج إلى تعليم القيادة."},"ref":{"doc":"NH","page":1}},{"id":"nh-006","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, how many hours of supervised driving must a student log, on top of driver education?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than 50.","h2":"A New Hampshire student must log 40 hours of supervised driving with a parent, guardian or other responsible adult before applying for a license.","p":"Correct. Forty supervised hours."},"es":{"q":"En New Hampshire, ¿cuántas horas de manejo supervisado debe registrar un estudiante, además del curso de educación vial?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos de 50.","h2":"Un estudiante en New Hampshire debe registrar 40 horas de manejo supervisado con su padre, madre, tutor u otro adulto responsable antes de solicitar la licencia.","p":"Correcto. Cuarenta horas supervisadas."},"zh":{"q":"在 New Hampshire，除了驾驶教育，学生还必须记录多少小时有人监督的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它少于 50。","h2":"New Hampshire 的学生申请驾照前，必须和父母、监护人或其他负责任的成年人一起记录 40 小时有人监督的驾驶。","p":"对。四十小时有人监督的驾驶。"},"vi":{"q":"Ở New Hampshire, ngoài giáo dục lái xe, học viên phải ghi lại bao nhiêu giờ lái xe có người giám sát?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Số giờ ít hơn 50.","h2":"Học viên ở New Hampshire phải ghi lại 40 giờ lái xe có giám sát với cha mẹ, người giám hộ hoặc một người lớn có trách nhiệm khác trước khi xin bằng lái.","p":"Đúng. Bốn mươi giờ có giám sát."},"tl":{"q":"Sa New Hampshire, ilang oras ng supervised na pagmamaneho ang dapat itala ng estudyante, bukod pa sa driver education?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa 50.","h2":"Ang estudyante sa New Hampshire ay dapat magtala ng 40 oras ng supervised na pagmamaneho kasama ang magulang, guardian o ibang responsableng adult bago mag-apply ng lisensya.","p":"Tama. Apatnapung supervised na oras."},"ar":{"q":"في New Hampshire، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل الطالب، بالإضافة إلى تعليم القيادة؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"العدد أقل من 50.","h2":"يجب على الطالب في New Hampshire أن يسجّل 40 ساعة من القيادة تحت الإشراف مع أحد الوالدين أو الوصي أو شخص بالغ مسؤول آخر قبل أن يتقدّم للحصول على رخصة.","p":"صحيح. أربعون ساعة تحت الإشراف."},"ref":{"doc":"NH","page":1}},{"id":"nh-007","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, how many of the 40 supervised hours must be at night?","o":["At least 10","At least 2","At least 20","None"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 supervised hours in New Hampshire must be driven at night.","p":"Right. Ten hours at night."},"es":{"q":"En New Hampshire, ¿cuántas de las 40 horas supervisadas deben ser de noche?","o":["Por lo menos 10","Por lo menos 2","Por lo menos 20","Ninguna"],"h1":"Es la cuarta parte del total.","h2":"En New Hampshire, por lo menos 10 de las 40 horas supervisadas deben ser de noche.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 New Hampshire，40 小时有人监督的驾驶中，有多少小时必须在晚上？","o":["至少 10 小时","至少 2 小时","至少 20 小时","不需要"],"h1":"是总数的四分之一。","h2":"在 New Hampshire，40 小时有人监督的驾驶中，至少 10 小时必须在晚上开。","p":"对。十小时在晚上。"},"vi":{"q":"Ở New Hampshire, trong 40 giờ có giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 20 giờ","Không giờ nào"],"h1":"Đó là một phần tư của tổng số giờ.","h2":"Ở New Hampshire, ít nhất 10 trong 40 giờ có giám sát phải được lái vào ban đêm.","p":"Đúng. Mười giờ vào ban đêm."},"tl":{"q":"Sa New Hampshire, ilan sa 40 supervised na oras ang dapat sa gabi?","o":["Hindi bababa sa 10","Hindi bababa sa 2","Hindi bababa sa 20","Wala"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 supervised na oras sa New Hampshire ang dapat imaneho sa gabi.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في New Hampshire، كم ساعة من الساعات الـ 40 تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","ساعتان على الأقل","20 ساعة على الأقل","لا شيء"],"h1":"هذا ربع المجموع.","h2":"في New Hampshire يجب أن تكون 10 ساعات على الأقل من الساعات الـ 40 تحت الإشراف قيادةً في الليل.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"NH","page":1}},{"id":"nh-009","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, when does a Youth Operator License expire?","o":["On the 18th birthday","After one year","On the 21st birthday","After six months"],"h1":"It ends when the driver becomes a full adult in the eyes of most laws.","h2":"A New Hampshire Youth Operator License expires on the holder's 21st birthday.","p":"Right. It expires at 21."},"es":{"q":"En New Hampshire, ¿cuándo vence la licencia de conductor joven (Youth Operator License)?","o":["Al cumplir 18 años","Después de un año","Al cumplir 21 años","Después de seis meses"],"h1":"Termina cuando el conductor llega a la edad adulta para la mayoría de las leyes.","h2":"La licencia de conductor joven de New Hampshire vence el día que su titular cumple 21 años.","p":"Correcto. Vence a los 21."},"zh":{"q":"在 New Hampshire，青少年驾照（Youth Operator License）什么时候到期？","o":["18 岁生日那天","一年以后","21 岁生日那天","六个月以后"],"h1":"在大多数法律看来，司机成为完全的成年人时，它就结束了。","h2":"New Hampshire 的青少年驾照在持有人 21 岁生日那天到期。","p":"对。它在 21 岁时到期。"},"vi":{"q":"Ở New Hampshire, bằng lái dành cho người trẻ (Youth Operator License) hết hạn khi nào?","o":["Vào sinh nhật 18 tuổi","Sau một năm","Vào sinh nhật 21 tuổi","Sau sáu tháng"],"h1":"Nó hết hạn khi người lái trở thành người lớn hoàn toàn theo hầu hết các luật.","h2":"Bằng lái dành cho người trẻ (Youth Operator License) ở New Hampshire hết hạn vào sinh nhật 21 tuổi của người có bằng.","p":"Đúng. Nó hết hạn lúc 21 tuổi."},"tl":{"q":"Sa New Hampshire, kailan mag-e-expire ang Youth Operator License?","o":["Sa ika-18 kaarawan","Pagkalipas ng isang taon","Sa ika-21 kaarawan","Pagkalipas ng anim na buwan"],"h1":"Natatapos ito kapag ganap nang adult ang driver ayon sa karamihan ng batas.","h2":"Ang Youth Operator License sa New Hampshire ay mag-e-expire sa ika-21 kaarawan ng may-hawak nito.","p":"Tama. Mag-e-expire ito sa edad na 21."},"ar":{"q":"في New Hampshire، متى تنتهي رخصة السائق الشاب (Youth Operator License)؟","o":["في عيد الميلاد الـ 18","بعد سنة واحدة","في عيد الميلاد الـ 21","بعد ستة أشهر"],"h1":"تنتهي عندما يصبح السائق بالغًا تمامًا في نظر أغلب القوانين.","h2":"تنتهي رخصة السائق الشاب (Youth Operator License) في New Hampshire في عيد الميلاد الـ 21 لصاحبها.","p":"صحيح. تنتهي في عمر 21 سنة."},"ref":{"doc":"NH","page":4}},{"id":"nh-010","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, during which hours may a Youth Operator License holder not drive?","o":["Midnight to 5 a.m.","1 a.m. to 4 a.m.","11 p.m. to 5 a.m.","10 p.m. to 6 a.m."],"h1":"The window is only three hours long.","h2":"A New Hampshire Youth Operator License holder may not drive between 1 a.m. and 4 a.m.","p":"Correct. No driving from 1 to 4 a.m."},"es":{"q":"En New Hampshire, ¿en qué horario no puede manejar el titular de una licencia de conductor joven?","o":["De medianoche a 5 a.m.","De 1 a.m. a 4 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 6 a.m."],"h1":"El período dura solo tres horas.","h2":"El titular de una licencia de conductor joven en New Hampshire no puede manejar entre la 1 a.m. y las 4 a.m.","p":"Correcto. No se maneja de 1 a 4 a.m."},"zh":{"q":"在 New Hampshire，持青少年驾照的人在哪段时间不能开车？","o":["午夜到早上 5 点","凌晨 1 点到凌晨 4 点","晚上 11 点到早上 5 点","晚上 10 点到早上 6 点"],"h1":"这段时间只有三个小时。","h2":"New Hampshire 持青少年驾照的人在凌晨 1 点到凌晨 4 点之间不能开车。","p":"对。凌晨 1 点到 4 点不能开车。"},"vi":{"q":"Ở New Hampshire, người có bằng lái dành cho người trẻ (Youth Operator License) không được lái xe trong khoảng giờ nào?","o":["Từ nửa đêm đến 5 giờ sáng","Từ 1 giờ sáng đến 4 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Khoảng thời gian này chỉ dài ba tiếng.","h2":"Ở New Hampshire, người có bằng lái dành cho người trẻ không được lái xe từ 1 giờ sáng đến 4 giờ sáng.","p":"Đúng. Không lái xe từ 1 đến 4 giờ sáng."},"tl":{"q":"Sa New Hampshire, sa anong mga oras bawal magmaneho ang may hawak ng Youth Operator License?","o":["Hatinggabi hanggang alas-5 ng umaga","Ala-1 hanggang alas-4 ng madaling-araw","Alas-11 ng gabi hanggang alas-5 ng umaga","Alas-10 ng gabi hanggang alas-6 ng umaga"],"h1":"Tatlong oras lang ang haba nito.","h2":"Ang may hawak ng Youth Operator License sa New Hampshire ay bawal magmaneho mula ala-1 hanggang alas-4 ng madaling-araw.","p":"Tama. Bawal magmaneho mula ala-1 hanggang alas-4 ng madaling-araw."},"ar":{"q":"في New Hampshire، في أي ساعات لا يجوز لصاحب رخصة السائق الشاب (Youth Operator License) أن يقود؟","o":["من منتصف الليل إلى 5 صباحًا","من 1 صباحًا إلى 4 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"هذه الفترة طولها ثلاث ساعات فقط.","h2":"في New Hampshire لا يجوز لصاحب رخصة السائق الشاب أن يقود بين الساعة 1 صباحًا والساعة 4 صباحًا.","p":"صحيح. ممنوع القيادة من 1 إلى 4 صباحًا."},"ref":{"doc":"NH","page":4}},{"id":"nh-011","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, during the first six months of a Youth Operator License, how many non-family passengers under 25 may the driver carry?","o":["One","None","Two","Three"],"h1":"The limit is more than zero but very small.","h2":"During the first six months, a New Hampshire youth operator may carry no more than one passenger under 25 who is not a family member.","p":"Right. Only one."},"es":{"q":"En New Hampshire, durante los primeros seis meses de la licencia de conductor joven, ¿cuántos pasajeros menores de 25 años que no son familiares puede llevar el conductor?","o":["Uno","Ninguno","Dos","Tres"],"h1":"El límite es mayor que cero, pero muy pequeño.","h2":"Durante los primeros seis meses, un conductor joven en New Hampshire no puede llevar más de un pasajero menor de 25 años que no sea de su familia.","p":"Correcto. Solo uno."},"zh":{"q":"在 New Hampshire，持青少年驾照的前六个月，司机可以载多少位不是家人、25 岁以下的乘客？","o":["一位","一个都不行","两位","三位"],"h1":"这个限制大于零，但很小。","h2":"在前六个月，New Hampshire 持青少年驾照的司机最多只能载一位不是家人、25 岁以下的乘客。","p":"对。只能一位。"},"vi":{"q":"Ở New Hampshire, trong sáu tháng đầu có bằng lái dành cho người trẻ (Youth Operator License), người lái được chở bao nhiêu hành khách dưới 25 tuổi không phải người trong gia đình?","o":["Một người","Không người nào","Hai người","Ba người"],"h1":"Giới hạn này nhiều hơn số không nhưng rất nhỏ.","h2":"Trong sáu tháng đầu, người lái trẻ ở New Hampshire chỉ được chở tối đa một hành khách dưới 25 tuổi không phải người trong gia đình.","p":"Đúng. Chỉ một người."},"tl":{"q":"Sa New Hampshire, sa unang anim na buwan ng Youth Operator License, ilang pasaherong wala pang 25 na hindi kapamilya ang puwedeng isakay ng driver?","o":["Isa","Wala","Dalawa","Tatlo"],"h1":"Higit ito sa zero pero napakaliit.","h2":"Sa unang anim na buwan, ang batang driver sa New Hampshire ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 25 na hindi kapamilya.","p":"Tama. Isa lang."},"ar":{"q":"في New Hampshire، في الأشهر الستة الأولى من رخصة السائق الشاب (Youth Operator License)، كم راكبًا عمره أقل من 25 سنة ومن خارج العائلة يمكن للسائق أن ينقل؟","o":["واحد","لا أحد","اثنان","ثلاثة"],"h1":"الحد أكثر من صفر لكنه صغير جدًا.","h2":"في الأشهر الستة الأولى، لا يجوز للسائق الشاب في New Hampshire أن ينقل أكثر من راكب واحد عمره أقل من 25 سنة وليس من أفراد العائلة.","p":"صحيح. واحد فقط."},"ref":{"doc":"NH","page":4}},{"id":"nh-012","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, when may a new youth operator carry more than one non-family passenger under 25 in the first six months?","o":["On weekends","On roads with a low speed limit","During daylight","When a licensed adult at least 25 years old is in the car"],"h1":"An experienced adult has to be with them.","h2":"In New Hampshire the one-passenger limit does not apply when a licensed responsible adult at least 25 years old rides along.","p":"Correct. A licensed adult 25 or older lifts the limit."},"es":{"q":"En New Hampshire, ¿cuándo puede un conductor joven nuevo llevar más de un pasajero menor de 25 años que no sea familiar en los primeros seis meses?","o":["Los fines de semana","En calles con límite de velocidad bajo","Durante el día","Cuando lo acompaña un adulto con licencia de por lo menos 25 años"],"h1":"Debe ir con un adulto con experiencia.","h2":"En New Hampshire el límite de un pasajero no se aplica cuando lo acompaña un adulto responsable con licencia de por lo menos 25 años.","p":"Correcto. Un adulto con licencia de 25 años o más quita el límite."},"zh":{"q":"在 New Hampshire，持青少年驾照的新司机在前六个月什么时候可以载超过一位不是家人、25 岁以下的乘客？","o":["周末","在限速低的路上","白天","车里有一位至少 25 岁、有驾照的成年人时"],"h1":"必须有一位有经验的成年人和他们一起。","h2":"在 New Hampshire，有一位至少 25 岁、有驾照、负责任的成年人同车时，只能载一位乘客的限制就不适用。","p":"对。有一位 25 岁或以上、有驾照的成年人同车，就取消这个限制。"},"vi":{"q":"Ở New Hampshire, trong sáu tháng đầu, khi nào người lái trẻ mới được chở hơn một hành khách dưới 25 tuổi không phải người trong gia đình?","o":["Vào cuối tuần","Trên đường có tốc độ giới hạn thấp","Vào ban ngày","Khi có một người lớn có bằng lái, ít nhất 25 tuổi, ở trong xe"],"h1":"Phải có một người lớn có kinh nghiệm đi cùng.","h2":"Ở New Hampshire, giới hạn một hành khách không áp dụng khi có một người lớn có trách nhiệm, có bằng lái, ít nhất 25 tuổi, đi cùng trong xe.","p":"Đúng. Một người lớn có bằng lái từ 25 tuổi trở lên sẽ bỏ giới hạn này."},"tl":{"q":"Sa New Hampshire, kailan puwedeng magsakay ang bagong batang driver ng higit sa isang pasaherong wala pang 25 na hindi kapamilya sa unang anim na buwan?","o":["Tuwing weekend","Sa mga kalsadang mababa ang speed limit","Sa araw","Kapag may adult na may lisensya na hindi bababa sa 25 taong gulang sa sasakyan"],"h1":"Kailangang may kasamang adult na may karanasan.","h2":"Sa New Hampshire, hindi umiiral ang limitasyong isang pasahero kapag may kasamang responsableng adult na may lisensya na hindi bababa sa 25 taong gulang.","p":"Tama. Inaalis ng adult na may lisensya na 25 o higit pa ang limitasyon."},"ar":{"q":"في New Hampshire، متى يمكن للسائق الشاب الجديد أن ينقل أكثر من راكب واحد عمره أقل من 25 سنة ومن خارج العائلة في الأشهر الستة الأولى؟","o":["في عطلة نهاية الأسبوع","في الطرق ذات حد السرعة المنخفض","في النهار","عندما يكون في السيارة شخص بالغ يحمل رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون معه شخص بالغ له خبرة.","h2":"في New Hampshire لا ينطبق حد الراكب الواحد عندما يرافق السائقَ شخصٌ بالغ مسؤول يحمل رخصة وعمره 25 سنة على الأقل.","p":"صحيح. وجود بالغ يحمل رخصة وعمره 25 سنة أو أكثر يرفع الحد."},"ref":{"doc":"NH","page":4}},{"id":"nh-013","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, how many people may ride with a youth operator?","o":["Any number","No more than four","No more than there are seat belts","Only one"],"h1":"Every person needs a place to buckle up.","h2":"A New Hampshire youth operator may not carry more people than the vehicle has seat belts.","p":"Right. One seat belt for each person."},"es":{"q":"En New Hampshire, ¿cuántas personas pueden ir con un conductor joven?","o":["Cualquier número","No más de cuatro","No más que el número de cinturones de seguridad","Solo una"],"h1":"Cada persona necesita un lugar donde abrocharse.","h2":"Un conductor joven en New Hampshire no puede llevar más personas que el número de cinturones de seguridad del vehículo.","p":"Correcto. Un cinturón para cada persona."},"zh":{"q":"在 New Hampshire，持青少年驾照的司机可以载多少人？","o":["多少人都可以","最多四个人","不能超过安全带的数量","只能一个人"],"h1":"每个人都需要一个系安全带的位置。","h2":"New Hampshire 持青少年驾照的司机载的人不能比车里的安全带多。","p":"对。每个人一条安全带。"},"vi":{"q":"Ở New Hampshire, bao nhiêu người được đi cùng xe với người lái trẻ?","o":["Bao nhiêu cũng được","Không quá bốn người","Không nhiều hơn số dây an toàn trong xe","Chỉ một người"],"h1":"Mỗi người cần một chỗ để thắt dây an toàn.","h2":"Người lái trẻ ở New Hampshire không được chở nhiều người hơn số dây an toàn có trong xe.","p":"Đúng. Mỗi người một dây an toàn."},"tl":{"q":"Sa New Hampshire, ilang tao ang puwedeng sumakay kasama ng batang driver?","o":["Kahit ilan","Hindi hihigit sa apat","Hindi hihigit sa bilang ng seat belt","Isa lang"],"h1":"Bawat tao ay kailangan ng lugar para mag-seat belt.","h2":"Ang batang driver sa New Hampshire ay hindi puwedeng magsakay ng mas maraming tao kaysa sa bilang ng seat belt ng sasakyan.","p":"Tama. Isang seat belt sa bawat tao."},"ar":{"q":"في New Hampshire، كم شخصًا يمكن أن يركب مع السائق الشاب؟","o":["أي عدد","لا يزيد عن أربعة","لا يزيد عن عدد أحزمة الأمان","واحد فقط"],"h1":"كل شخص يحتاج إلى مكان يربط فيه حزام الأمان.","h2":"لا يجوز للسائق الشاب في New Hampshire أن ينقل أشخاصًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. حزام أمان واحد لكل شخص."},"ref":{"doc":"NH","page":4}},{"id":"nh-014","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, may a driver under 18 talk on a phone using a hands-free device?","o":["Yes, any time","No, only to report an emergency","Yes, but only at a red light","Yes, if the call is short"],"h1":"Younger drivers have a stricter rule than adults.","h2":"In New Hampshire a driver under 18 may not use a phone or other mobile device at all while driving, even hands-free, except to report an emergency.","p":"Correct. Under 18, no phone except emergencies."},"es":{"q":"En New Hampshire, ¿puede un conductor menor de 18 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, en cualquier momento","No, solo para reportar una emergencia","Sí, pero solo en un semáforo en rojo","Sí, si la llamada es corta"],"h1":"Los conductores más jóvenes tienen una regla más estricta que los adultos.","h2":"En New Hampshire un conductor menor de 18 años no puede usar un teléfono ni otro dispositivo móvil mientras maneja, ni siquiera con manos libres, excepto para reportar una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo emergencias."},"zh":{"q":"在 New Hampshire，18 岁以下的司机可以用免提设备打电话吗？","o":["可以，任何时候","不可以，只能报告紧急情况","可以，但只在红灯时","可以，如果电话很短"],"h1":"年轻司机的规定比成年人更严格。","h2":"在 New Hampshire，18 岁以下的司机开车时完全不能用手机或其他移动设备，免提也不行，只有报告紧急情况例外。","p":"对。18 岁以下，除了紧急情况，不能用手机。"},"vi":{"q":"Ở New Hampshire, người lái xe dưới 18 tuổi có được nói điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Có, bất cứ lúc nào","Không, chỉ được gọi để báo trường hợp khẩn cấp","Có, nhưng chỉ khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Người lái trẻ có luật nghiêm hơn người lớn.","h2":"Ở New Hampshire, người lái xe dưới 18 tuổi hoàn toàn không được dùng điện thoại hay thiết bị di động khác khi lái xe, kể cả rảnh tay, trừ khi để báo trường hợp khẩn cấp.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại trừ khi khẩn cấp."},"tl":{"q":"Sa New Hampshire, puwede bang makipag-usap sa telepono gamit ang hands-free device ang driver na wala pang 18?","o":["Oo, kahit kailan","Hindi, puwede lang para mag-report ng emergency","Oo, pero sa red light lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa mas batang driver kaysa sa mga adult.","h2":"Sa New Hampshire, ang driver na wala pang 18 ay bawal gumamit ng telepono o ibang mobile device habang nagmamaneho, kahit hands-free, maliban para mag-report ng emergency.","p":"Tama. Kung wala pang 18, walang telepono maliban sa emergency."},"ar":{"q":"في New Hampshire، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلّم في الهاتف باستخدام جهاز من غير استعمال اليدين (hands-free)؟","o":["نعم، في أي وقت","لا، إلا للإبلاغ عن حالة طوارئ","نعم، لكن عند الإشارة الحمراء فقط","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين الأصغر سنًا قاعدة أشد من قاعدة البالغين.","h2":"في New Hampshire لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أو أي جهاز محمول آخر أبدًا أثناء القيادة، حتى من غير استعمال اليدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. أقل من 18 سنة: لا هاتف إلا في الطوارئ."},"ref":{"doc":"NH","page":4}},{"id":"nh-015","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, how may an adult driver make a phone call while driving?","o":["With a Bluetooth or other hands-free device","Holding the phone to the ear","Holding the phone while stopped in traffic","Typing the number on the screen in the hand"],"h1":"The law bans hand-held use, even when stopped in traffic.","h2":"New Hampshire bans hand-held phone use while driving, even when stopped in traffic, but an adult may use a Bluetooth or other hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En New Hampshire, ¿cómo puede un conductor adulto hacer una llamada mientras maneja?","o":["Con un dispositivo Bluetooth u otro de manos libres","Sosteniendo el teléfono junto al oído","Sosteniendo el teléfono cuando está detenido en el tráfico","Marcando el número en la pantalla con el teléfono en la mano"],"h1":"La ley prohíbe usar el teléfono en la mano, aun detenido en el tráfico.","h2":"New Hampshire prohíbe usar el teléfono en la mano mientras se maneja, aun detenido en el tráfico, pero un adulto puede usar un dispositivo Bluetooth u otro de manos libres.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 New Hampshire，成年司机开车时可以怎样打电话？","o":["用蓝牙或其他免提设备","把手机拿到耳边","在车流中停着时拿着手机","手拿着手机在屏幕上按号码"],"h1":"法律禁止手拿使用，即使在车流中停着也不行。","h2":"New Hampshire 禁止开车时手拿手机使用，即使在车流中停着也不行，但成年人可以用蓝牙或其他免提设备。","p":"对。只能免提。"},"vi":{"q":"Ở New Hampshire, người lái xe là người lớn có thể gọi điện thoại khi lái xe bằng cách nào?","o":["Bằng Bluetooth hoặc thiết bị rảnh tay (hands-free) khác","Cầm điện thoại áp vào tai","Cầm điện thoại khi đang dừng vì kẹt xe","Bấm số trên màn hình điện thoại cầm trong tay"],"h1":"Luật cấm cầm điện thoại trên tay, kể cả khi đang dừng vì kẹt xe.","h2":"New Hampshire cấm cầm điện thoại trên tay khi lái xe, kể cả khi đang dừng vì kẹt xe, nhưng người lớn có thể dùng Bluetooth hoặc thiết bị rảnh tay khác.","p":"Đúng. Chỉ dùng rảnh tay."},"tl":{"q":"Sa New Hampshire, paano puwedeng tumawag ang adult na driver habang nagmamaneho?","o":["Gamit ang Bluetooth o ibang hands-free device","Hawak ang telepono sa tainga","Hawak ang telepono habang nakahinto sa trapiko","Pinipindot ang numero sa screen ng teleponong hawak"],"h1":"Bawal ng batas ang paghawak ng telepono, kahit nakahinto sa trapiko.","h2":"Bawal sa New Hampshire ang paghawak ng telepono habang nagmamaneho, kahit nakahinto sa trapiko, pero puwedeng gumamit ang adult ng Bluetooth o ibang hands-free device.","p":"Tama. Hands-free lang."},"ar":{"q":"في New Hampshire، كيف يمكن للسائق البالغ أن يجري مكالمة هاتفية أثناء القيادة؟","o":["باستخدام Bluetooth أو جهاز آخر من غير استعمال اليدين (hands-free)","بإمساك الهاتف على الأذن","بإمساك الهاتف أثناء التوقّف في زحمة السير","بكتابة الرقم على شاشة الهاتف وهو في اليد"],"h1":"القانون يمنع إمساك الهاتف باليد، حتى أثناء التوقّف في زحمة السير.","h2":"تمنع New Hampshire إمساك الهاتف باليد أثناء القيادة، حتى أثناء التوقّف في زحمة السير، لكن يمكن للبالغ أن يستخدم Bluetooth أو جهازًا آخر من غير استعمال اليدين.","p":"صحيح. من غير استعمال اليدين فقط."},"ref":{"doc":"NH","page":7}},{"id":"nh-017","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, which drivers must wear a seat belt by law?","o":["Only drivers on the highway","Only drivers over 65","Drivers under 18","Only taxi drivers"],"h1":"The rule is about young drivers.","h2":"New Hampshire law says a person under 18 may not drive unless wearing a properly fastened seat belt.","p":"Right. Drivers under 18 must buckle up."},"es":{"q":"En New Hampshire, ¿qué conductores deben usar cinturón de seguridad por ley?","o":["Solo los que manejan en la autopista","Solo los mayores de 65","Los conductores menores de 18 años","Solo los taxistas"],"h1":"La regla se refiere a los conductores jóvenes.","h2":"La ley de New Hampshire dice que una persona menor de 18 años no puede manejar sin el cinturón de seguridad bien abrochado.","p":"Correcto. Los menores de 18 deben abrocharse."},"zh":{"q":"在 New Hampshire，法律规定哪些司机必须系安全带？","o":["只有在公路上的司机","只有 65 岁以上的司机","18 岁以下的司机","只有出租车司机"],"h1":"这条规定和年轻司机有关。","h2":"New Hampshire 法律规定，18 岁以下的人必须正确系好安全带才能开车。","p":"对。18 岁以下的司机必须系好安全带。"},"vi":{"q":"Ở New Hampshire, theo luật, những người lái xe nào phải thắt dây an toàn?","o":["Chỉ người lái xe trên xa lộ","Chỉ người lái xe trên 65 tuổi","Người lái xe dưới 18 tuổi","Chỉ tài xế taxi"],"h1":"Luật này nói về người lái xe trẻ.","h2":"Luật New Hampshire nói rằng người dưới 18 tuổi không được lái xe nếu không thắt dây an toàn đúng cách.","p":"Đúng. Người lái xe dưới 18 tuổi phải thắt dây an toàn."},"tl":{"q":"Sa New Hampshire, aling mga driver ang dapat mag-seat belt ayon sa batas?","o":["Mga driver lang sa highway","Mga driver lang na higit sa 65","Mga driver na wala pang 18","Mga taxi driver lang"],"h1":"Tungkol sa mga batang driver ang patakaran.","h2":"Sinasabi ng batas ng New Hampshire na ang taong wala pang 18 ay bawal magmaneho kung hindi siya nakasuot ng seat belt nang tama.","p":"Tama. Dapat mag-seat belt ang mga driver na wala pang 18."},"ar":{"q":"في New Hampshire، أي السائقين يجب عليهم بحكم القانون أن يربطوا حزام الأمان؟","o":["السائقون على الطريق السريع فقط","السائقون الذين تزيد أعمارهم عن 65 سنة فقط","السائقون الذين أعمارهم أقل من 18 سنة","سائقو سيارات الأجرة فقط"],"h1":"القاعدة تخص السائقين الصغار.","h2":"قانون New Hampshire يقول إن الشخص الذي عمره أقل من 18 سنة لا يجوز له أن يقود إلا وهو رابط حزام الأمان بشكل صحيح.","p":"صحيح. السائقون الذين أعمارهم أقل من 18 سنة يجب أن يربطوا الحزام."},"ref":{"doc":"NH","page":11}},{"id":"nh-018","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, which passengers must the driver make sure are wearing a seat belt?","o":["Only the front-seat passenger","Every passenger under 18","Only passengers over 65","No one but the driver"],"h1":"The driver is responsible for young passengers.","h2":"In New Hampshire a driver may not carry a passenger under 18 who is not wearing a properly fastened seat belt.","p":"Correct. Every passenger under 18."},"es":{"q":"En New Hampshire, ¿qué pasajeros debe asegurarse el conductor de que usen cinturón de seguridad?","o":["Solo el pasajero del asiento delantero","Todo pasajero menor de 18 años","Solo los pasajeros mayores de 65","Nadie más que el conductor"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En New Hampshire un conductor no puede llevar a un pasajero menor de 18 años que no tenga el cinturón de seguridad bien abrochado.","p":"Correcto. Todo pasajero menor de 18."},"zh":{"q":"在 New Hampshire，司机必须确认哪些乘客系好了安全带？","o":["只有前排乘客","每位 18 岁以下的乘客","只有 65 岁以上的乘客","除了司机，谁都不用"],"h1":"司机要为年轻乘客负责。","h2":"在 New Hampshire，司机不能载没有正确系好安全带的 18 岁以下乘客。","p":"对。每位 18 岁以下的乘客。"},"vi":{"q":"Ở New Hampshire, người lái xe phải bảo đảm những hành khách nào thắt dây an toàn?","o":["Chỉ hành khách ngồi ghế trước","Mọi hành khách dưới 18 tuổi","Chỉ hành khách trên 65 tuổi","Không ai ngoài người lái xe"],"h1":"Người lái xe chịu trách nhiệm cho hành khách trẻ.","h2":"Ở New Hampshire, người lái xe không được chở hành khách dưới 18 tuổi nếu người đó không thắt dây an toàn đúng cách.","p":"Đúng. Mọi hành khách dưới 18 tuổi."},"tl":{"q":"Sa New Hampshire, aling mga pasahero ang dapat tiyakin ng driver na naka-seat belt?","o":["Ang pasahero lang sa upuan sa harap","Bawat pasaherong wala pang 18","Mga pasahero lang na higit sa 65","Wala, ang driver lang"],"h1":"Responsable ang driver sa mga batang pasahero.","h2":"Sa New Hampshire, bawal magsakay ang driver ng pasaherong wala pang 18 na hindi nakasuot ng seat belt nang tama.","p":"Tama. Bawat pasaherong wala pang 18."},"ar":{"q":"في New Hampshire، أي الركاب يجب على السائق أن يتأكد أنهم يربطون حزام الأمان؟","o":["راكب المقعد الأمامي فقط","كل راكب عمره أقل من 18 سنة","الركاب الذين تزيد أعمارهم عن 65 سنة فقط","لا أحد غير السائق"],"h1":"السائق مسؤول عن الركاب الصغار.","h2":"في New Hampshire لا يجوز للسائق أن ينقل راكبًا عمره أقل من 18 سنة إذا لم يكن رابطًا حزام الأمان بشكل صحيح.","p":"صحيح. كل راكب عمره أقل من 18 سنة."},"ref":{"doc":"NH","page":11}},{"id":"nh-019","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, at what blood alcohol level is a driver under 21 legally intoxicated?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In New Hampshire a driver under 21 is legally intoxicated at a blood alcohol level of 0.02 or more.","p":"Right. The limit under 21 is 0.02."},"es":{"q":"En New Hampshire, ¿con qué nivel de alcohol en la sangre se considera legalmente intoxicado a un conductor menor de 21 años?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En New Hampshire un conductor menor de 21 años está legalmente intoxicado con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 New Hampshire，21 岁以下的司机血液酒精浓度达到多少，在法律上就算醉酒？","o":["0.02 或更高","0.05 或更高","0.08 或更高","0.10 或更高"],"h1":"它比成年人 0.08 的限值低很多。","h2":"在 New Hampshire，21 岁以下的司机血液酒精浓度达到 0.02 或更高，在法律上就算醉酒。","p":"对。21 岁以下的限值是 0.02。"},"vi":{"q":"Ở New Hampshire, người lái xe dưới 21 tuổi bị coi là say rượu theo luật khi nồng độ cồn trong máu là bao nhiêu?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.10 trở lên"],"h1":"Mức này thấp hơn nhiều so với giới hạn 0.08 cho người lớn.","h2":"Ở New Hampshire, người lái xe dưới 21 tuổi bị coi là say rượu theo luật khi nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa New Hampshire, sa anong blood alcohol level itinuturing na legal na lasing ang driver na wala pang 21?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki sa limitasyon ng adult na 0.08.","h2":"Sa New Hampshire, ang driver na wala pang 21 ay legal na lasing kapag ang blood alcohol level niya ay 0.02 o higit pa.","p":"Tama. 0.02 ang limitasyon kung wala pang 21."},"ar":{"q":"في New Hampshire، عند أي نسبة كحول في الدم يُعتبر السائق الذي عمره أقل من 21 سنة سكرانًا قانونيًا؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.10 أو أكثر"],"h1":"هذه النسبة أقل بكثير من حد البالغين وهو 0.08.","h2":"في New Hampshire يُعتبر السائق الذي عمره أقل من 21 سنة سكرانًا قانونيًا عندما تكون نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد لمن عمره أقل من 21 سنة هو 0.02."},"ref":{"doc":"NH","page":6}},{"id":"nh-020","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, when does the Move Over law ask you to slow down and give extra space?","o":["Only for police cars with sirens","Only on interstate highways","Only at night","At an emergency scene, a police traffic stop, or any stopped vehicle showing warning lights, hazard lights, flares or cones"],"h1":"Since 2025 the law covers more than emergency vehicles.","h2":"Since September 2025, New Hampshire's Move Over law asks drivers to slow down and, if practical, give a wide berth at an emergency scene, a police traffic stop, or any stopped vehicle showing warning signals such as emergency lights, hazard lights, flares or cones.","p":"Correct. Emergencies, police stops, and any stopped vehicle with warning signals."},"es":{"q":"En New Hampshire, ¿cuándo le pide la ley Move Over que reduzca la velocidad y deje más espacio?","o":["Solo con carros de policía con sirena","Solo en las autopistas interestatales","Solo de noche","En una emergencia, una parada de tráfico de la policía, o cualquier vehículo detenido con luces de advertencia, luces intermitentes de emergencia, bengalas o conos"],"h1":"Desde 2025 la ley cubre más que los vehículos de emergencia.","h2":"Desde septiembre de 2025, la ley Move Over de New Hampshire pide a los conductores reducir la velocidad y, si es práctico, dejar mucho espacio en una emergencia, una parada de tráfico de la policía, o ante cualquier vehículo detenido con señales de advertencia como luces de emergencia, luces intermitentes, bengalas o conos.","p":"Correcto. Emergencias, paradas de la policía y cualquier vehículo detenido con señales de advertencia."},"zh":{"q":"在 New Hampshire，“让道法”（Move Over law）在什么时候要求你减速并留出更多空间？","o":["只在遇到响着警笛的警车时","只在州际公路上","只在夜间","在紧急现场、警察拦车检查处，或任何亮着警示灯、危险警告灯、放着照明弹或锥桶的停靠车辆旁"],"h1":"从 2025 年起，这条法律不只适用于紧急车辆。","h2":"从 2025 年 9 月起，New Hampshire 的让道法要求司机在紧急现场、警察拦车检查处，或任何显示紧急灯、危险警告灯、照明弹或锥桶等警示信号的停靠车辆旁减速，并在可行时留出很大的空间。","p":"对。紧急情况、警察拦车，以及任何显示警示信号的停靠车辆。"},"vi":{"q":"Ở New Hampshire, khi nào luật Move Over yêu cầu bạn giảm tốc độ và chừa thêm khoảng trống?","o":["Chỉ với xe cảnh sát đang hú còi","Chỉ trên đường cao tốc liên bang","Chỉ vào ban đêm","Tại hiện trường khẩn cấp, nơi cảnh sát dừng xe kiểm tra, hoặc bất kỳ xe nào đang dừng có bật đèn cảnh báo, đèn khẩn cấp, pháo sáng hoặc đặt cọc tiêu"],"h1":"Từ năm 2025, luật này áp dụng cho nhiều hơn xe khẩn cấp.","h2":"Từ tháng 9 năm 2025, luật Move Over của New Hampshire yêu cầu tài xế giảm tốc độ và, nếu có thể, chừa khoảng trống rộng tại hiện trường khẩn cấp, nơi cảnh sát dừng xe kiểm tra, hoặc bên cạnh bất kỳ xe nào đang dừng có tín hiệu cảnh báo như đèn khẩn cấp, đèn nháy cảnh báo, pháo sáng hoặc cọc tiêu.","p":"Đúng. Trường hợp khẩn cấp, cảnh sát dừng xe, và bất kỳ xe nào đang dừng có tín hiệu cảnh báo."},"tl":{"q":"Sa New Hampshire, kailan hinihiling ng Move Over law na bumagal ka at magbigay ng dagdag na espasyo?","o":["Para lang sa mga sasakyan ng pulis na may sirena","Sa mga interstate highway lang","Sa gabi lang","Sa isang emergency scene, sa traffic stop ng pulis, o sa anumang nakahintong sasakyan na may warning lights, hazard lights, flares o cones"],"h1":"Mula 2025, sakop ng batas ang higit pa sa mga emergency vehicle.","h2":"Mula Setyembre 2025, hinihiling ng Move Over law ng New Hampshire na bumagal ang mga driver at, kung kaya, magbigay ng malawak na espasyo sa isang emergency scene, sa traffic stop ng pulis, o sa anumang nakahintong sasakyan na may warning signals tulad ng emergency lights, hazard lights, flares o cones.","p":"Tama. Mga emergency, traffic stop ng pulis, at anumang nakahintong sasakyan na may warning signals."},"ar":{"q":"في New Hampshire، متى يطلب منك قانون إفساح الطريق (Move Over law) أن تبطئ وتترك مسافة إضافية؟","o":["فقط عند سيارات الشرطة التي تُطلق صفارة الإنذار","فقط على الطرق السريعة بين الولايات","فقط في الليل","عند موقع طوارئ، أو عند توقيف مروري من الشرطة، أو عند أي مركبة متوقفة تُظهر أضواء تحذير، أو أضواء الخطر، أو مشاعل، أو أقماعًا"],"h1":"منذ 2025 يشمل القانون أكثر من مركبات الطوارئ.","h2":"منذ سبتمبر 2025، يطلب قانون إفساح الطريق في New Hampshire من السائقين أن يبطئوا، وأن يتركوا مسافة واسعة إن أمكن، عند موقع طوارئ، أو عند توقيف مروري من الشرطة، أو عند أي مركبة متوقفة تُظهر إشارات تحذير مثل أضواء الطوارئ، أو أضواء الخطر، أو المشاعل، أو الأقماع.","p":"صحيح. حالات الطوارئ، وتوقيفات الشرطة، وأي مركبة متوقفة تُظهر إشارات تحذير."},"ref":{"doc":"NH","page":null}},{"id":"nh-021","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how fast may you drive in a posted school zone while the school limit is in effect?","o":["5 mph below the usual posted limit","15 mph, whatever the usual limit is","10 mph below the usual posted limit","20 mph below the usual posted limit"],"h1":"The school limit is found by taking a set number off the usual limit.","h2":"In a posted New Hampshire school zone, the limit is 10 mph below the usual posted limit while the school limit is in effect.","p":"Right. Drive 10 mph under the usual limit."},"es":{"q":"En New Hampshire, ¿a qué velocidad puede manejar en una zona escolar señalizada mientras rige el límite escolar?","o":["5 mph menos que el límite habitual","15 mph, sea cual sea el límite habitual","10 mph menos que el límite habitual","20 mph menos que el límite habitual"],"h1":"El límite escolar se obtiene restando un número fijo al límite habitual.","h2":"En una zona escolar señalizada de New Hampshire, el límite es 10 mph menos que el límite habitual mientras rige el límite escolar.","p":"Correcto. Maneje 10 mph por debajo del límite habitual."},"zh":{"q":"在 New Hampshire，在有标志的学校区域，学校限速生效时，你可以开多快？","o":["比平常标示的限速低 5 mph","15 mph，不管平常限速是多少","比平常标示的限速低 10 mph","比平常标示的限速低 20 mph"],"h1":"学校限速是从平常限速中减去一个固定的数。","h2":"在 New Hampshire 有标志的学校区域，学校限速生效时，限速比平常标示的限速低 10 mph。","p":"对。比平常限速低 10 mph。"},"vi":{"q":"Ở New Hampshire, bạn được lái nhanh bao nhiêu trong khu vực trường học có biển báo khi giới hạn tốc độ của trường đang có hiệu lực?","o":["Thấp hơn giới hạn thường lệ 5 mph","15 mph, bất kể giới hạn thường lệ là bao nhiêu","Thấp hơn giới hạn thường lệ 10 mph","Thấp hơn giới hạn thường lệ 20 mph"],"h1":"Giới hạn của trường được tính bằng cách lấy giới hạn thường lệ trừ đi một con số cố định.","h2":"Trong khu vực trường học có biển báo ở New Hampshire, giới hạn tốc độ thấp hơn giới hạn thường lệ 10 mph khi giới hạn của trường đang có hiệu lực.","p":"Đúng. Lái chậm hơn giới hạn thường lệ 10 mph."},"tl":{"q":"Sa New Hampshire, gaano kabilis ka puwedeng magmaneho sa isang school zone na may karatula habang may bisa ang limitasyon para sa paaralan?","o":["5 mph na mas mababa sa karaniwang limitasyon","15 mph, anuman ang karaniwang limitasyon","10 mph na mas mababa sa karaniwang limitasyon","20 mph na mas mababa sa karaniwang limitasyon"],"h1":"Makukuha ang limitasyon sa paaralan sa pagbawas ng isang tiyak na bilang mula sa karaniwang limitasyon.","h2":"Sa isang school zone na may karatula sa New Hampshire, ang limitasyon ay 10 mph na mas mababa sa karaniwang limitasyon habang may bisa ang limitasyon para sa paaralan.","p":"Tama. Magmaneho nang 10 mph na mas mababa sa karaniwang limitasyon."},"ar":{"q":"في New Hampshire، ما السرعة المسموح بها في منطقة مدرسية عليها لافتة أثناء سريان حدّ سرعة المدرسة؟","o":["أقل من الحد المعتاد بـ 5 mph","15 mph، مهما كان الحد المعتاد","أقل من الحد المعتاد بـ 10 mph","أقل من الحد المعتاد بـ 20 mph"],"h1":"حدّ المدرسة هو الحد المعتاد مطروحًا منه رقم ثابت.","h2":"في منطقة مدرسية عليها لافتة في New Hampshire، يكون حد السرعة أقل من الحد المعتاد بـ 10 mph أثناء سريان حد المدرسة.","p":"صحيح. قُد بسرعة أقل من الحد المعتاد بـ 10 mph."},"ref":{"doc":"NH","page":null}},{"id":"nh-022","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, when does the lower speed limit in a posted school zone apply?","o":["From 45 minutes before school opens until it opens, and from closing until 45 minutes after","All day, every day of the year","Only when children are on the sidewalk","From 7 a.m. to 5 p.m. on weekdays"],"h1":"It is tied to the times the school opens and closes.","h2":"In New Hampshire, the school zone limit applies from 45 minutes before school opens until it opens, and from the time school closes until 45 minutes later.","p":"Right. 45 minutes before opening and 45 minutes after closing."},"es":{"q":"En New Hampshire, ¿cuándo rige el límite de velocidad más bajo en una zona escolar señalizada?","o":["Desde 45 minutos antes de que abra la escuela hasta que abre, y desde el cierre hasta 45 minutos después","Todo el día, todos los días del año","Solo cuando hay niños en la acera","De 7 a.m. a 5 p.m. los días entre semana"],"h1":"Depende de la hora en que la escuela abre y cierra.","h2":"En New Hampshire, el límite de la zona escolar rige desde 45 minutos antes de que abra la escuela hasta que abre, y desde que cierra hasta 45 minutos después.","p":"Correcto. 45 minutos antes de abrir y 45 minutos después de cerrar."},"zh":{"q":"在 New Hampshire，有标志的学校区域里较低的限速什么时候适用？","o":["从开学前 45 分钟到开学，以及从放学到放学后 45 分钟","全年每天全天","只在有孩子在人行道上时","工作日早上 7 点到下午 5 点"],"h1":"它和学校开门、放学的时间有关。","h2":"在 New Hampshire，学校区域限速适用于学校开门前 45 分钟到开门，以及从放学到放学后 45 分钟。","p":"对。开门前 45 分钟和放学后 45 分钟。"},"vi":{"q":"Ở New Hampshire, giới hạn tốc độ thấp hơn trong khu vực trường học có biển báo được áp dụng khi nào?","o":["Từ 45 phút trước khi trường mở cửa cho đến lúc mở cửa, và từ lúc tan học đến 45 phút sau đó","Cả ngày, mọi ngày trong năm","Chỉ khi có trẻ em trên vỉa hè","Từ 7 giờ sáng đến 5 giờ chiều vào các ngày trong tuần"],"h1":"Nó gắn với giờ trường mở cửa và tan học.","h2":"Ở New Hampshire, giới hạn tốc độ khu vực trường học áp dụng từ 45 phút trước khi trường mở cửa cho đến lúc mở cửa, và từ lúc tan học đến 45 phút sau đó.","p":"Đúng. 45 phút trước khi mở cửa và 45 phút sau khi tan học."},"tl":{"q":"Sa New Hampshire, kailan may bisa ang mas mababang speed limit sa isang school zone na may karatula?","o":["Mula 45 minuto bago magbukas ang paaralan hanggang sa magbukas ito, at mula sa pagsasara hanggang 45 minuto pagkatapos","Buong araw, araw-araw sa buong taon","Kapag may mga bata lang sa bangketa","Mula 7 a.m. hanggang 5 p.m. tuwing weekday"],"h1":"Nakaugnay ito sa oras ng pagbubukas at pagsasara ng paaralan.","h2":"Sa New Hampshire, may bisa ang limitasyon sa school zone mula 45 minuto bago magbukas ang paaralan hanggang sa magbukas ito, at mula sa pagsasara ng paaralan hanggang 45 minuto pagkatapos.","p":"Tama. 45 minuto bago magbukas at 45 minuto pagkatapos magsara."},"ar":{"q":"في New Hampshire، متى يسري حد السرعة الأدنى في منطقة مدرسية عليها لافتة؟","o":["من 45 دقيقة قبل فتح المدرسة حتى فتحها، ومن وقت الإغلاق حتى 45 دقيقة بعده","طوال اليوم، كل يوم في السنة","فقط عندما يكون هناك أطفال على الرصيف","من 7 صباحًا إلى 5 مساءً في أيام الأسبوع"],"h1":"يرتبط بأوقات فتح المدرسة وإغلاقها.","h2":"في New Hampshire، يسري حد سرعة المنطقة المدرسية من 45 دقيقة قبل فتح المدرسة حتى فتحها، ومن وقت إغلاق المدرسة حتى 45 دقيقة بعده.","p":"صحيح. 45 دقيقة قبل الفتح و45 دقيقة بعد الإغلاق."},"ref":{"doc":"NH","page":null}},{"id":"nh-023","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the speed limit in a business district or a city residential area when no sign says otherwise?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is the limit for town business streets, a little lower than in rural residential areas.","h2":"In New Hampshire, the speed limit in a business or urban residence district is 30 mph unless a sign says otherwise.","p":"Right. 30 mph in business and city residential areas."},"es":{"q":"En New Hampshire, ¿cuál es el límite de velocidad en una zona comercial o un barrio residencial de ciudad cuando ninguna señal indica otra cosa?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es el límite para calles comerciales de pueblo, un poco más bajo que en zonas residenciales rurales.","h2":"En New Hampshire, el límite de velocidad en una zona comercial o un barrio residencial urbano es de 30 mph, salvo que una señal indique otra cosa.","p":"Correcto. 30 mph en zonas comerciales y barrios de ciudad."},"zh":{"q":"在 New Hampshire，没有标志另行规定时，商业区或城市住宅区的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"这是城镇商业街道的限速，比乡村住宅区稍低一点。","h2":"在 New Hampshire，除非标志另有规定，商业区或城市住宅区的限速是 30 mph。","p":"对。商业区和城市住宅区限速 30 mph。"},"vi":{"q":"Ở New Hampshire, giới hạn tốc độ trong khu thương mại hoặc khu dân cư thành phố là bao nhiêu khi không có biển báo khác?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Đó là giới hạn cho đường phố thương mại trong thị trấn, thấp hơn một chút so với khu dân cư nông thôn.","h2":"Ở New Hampshire, giới hạn tốc độ trong khu thương mại hoặc khu dân cư thành phố là 30 mph, trừ khi có biển báo khác.","p":"Đúng. 30 mph trong khu thương mại và khu dân cư thành phố."},"tl":{"q":"Sa New Hampshire, ano ang speed limit sa business district o residential area sa lungsod kapag walang karatulang nagsasabi ng iba?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Ito ang limitasyon sa mga kalye ng negosyo sa bayan, medyo mas mababa kaysa sa residential area sa probinsya.","h2":"Sa New Hampshire, ang speed limit sa business district o residential area sa lungsod ay 30 mph maliban kung may karatulang nagsasabi ng iba.","p":"Tama. 30 mph sa business at residential area sa lungsod."},"ar":{"q":"في New Hampshire، ما حد السرعة في منطقة تجارية أو منطقة سكنية في المدينة عندما لا توجد لافتة تقول غير ذلك؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"هو حد شوارع الأعمال في البلدة، وهو أقل قليلًا من حد المناطق السكنية الريفية.","h2":"في New Hampshire، حد السرعة في المنطقة التجارية أو المنطقة السكنية في المدينة هو 30 mph ما لم تقل لافتة غير ذلك.","p":"صحيح. 30 mph في المناطق التجارية والسكنية في المدينة."},"ref":{"doc":"NH","page":null}},{"id":"nh-024","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, what is the speed limit in a rural residential area when no sign says otherwise?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"It is a little higher than the limit in a town business area.","h2":"In New Hampshire, the speed limit in a rural residence district is 35 mph unless a sign says otherwise.","p":"Right. 35 mph in rural residential areas."},"es":{"q":"En New Hampshire, ¿cuál es el límite de velocidad en una zona residencial rural cuando ninguna señal indica otra cosa?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"Es un poco más alto que el límite en una zona comercial de un pueblo.","h2":"En New Hampshire, el límite de velocidad en una zona residencial rural es de 35 mph, salvo que una señal indique otra cosa.","p":"Correcto. 35 mph en zonas residenciales rurales."},"zh":{"q":"在 New Hampshire，没有标志另行规定时，乡村住宅区的限速是多少？","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"它比城镇商业区的限速稍高一点。","h2":"在 New Hampshire，除非标志另有规定，乡村住宅区的限速是 35 mph。","p":"对。乡村住宅区限速 35 mph。"},"vi":{"q":"Ở New Hampshire, giới hạn tốc độ trong khu dân cư nông thôn là bao nhiêu khi không có biển báo khác?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"Nó cao hơn một chút so với giới hạn trong khu thương mại của thị trấn.","h2":"Ở New Hampshire, giới hạn tốc độ trong khu dân cư nông thôn là 35 mph, trừ khi có biển báo khác.","p":"Đúng. 35 mph trong khu dân cư nông thôn."},"tl":{"q":"Sa New Hampshire, ano ang speed limit sa residential area sa probinsya kapag walang karatulang nagsasabi ng iba?","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"Medyo mas mataas ito kaysa sa limitasyon sa business area ng bayan.","h2":"Sa New Hampshire, ang speed limit sa residential area sa probinsya ay 35 mph maliban kung may karatulang nagsasabi ng iba.","p":"Tama. 35 mph sa residential area sa probinsya."},"ar":{"q":"في New Hampshire، ما حد السرعة في منطقة سكنية ريفية عندما لا توجد لافتة تقول غير ذلك؟","o":["25 mph","30 mph","45 mph","35 mph"],"h1":"هو أعلى قليلًا من الحد في منطقة الأعمال في البلدة.","h2":"في New Hampshire، حد السرعة في المنطقة السكنية الريفية هو 35 mph ما لم تقل لافتة غير ذلك.","p":"صحيح. 35 mph في المناطق السكنية الريفية."},"ref":{"doc":"NH","page":null}},{"id":"nh-025","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, you are on a paved two-lane state highway in the countryside, outside business and residential areas. No sign shows the limit. What is the speed limit?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is 10 mph less than the usual limit on a four-lane interstate.","h2":"In New Hampshire, the speed limit on a paved two-lane highway in the countryside, outside business and residential areas, is 55 mph when no sign says otherwise.","p":"Right. The limit there is 55 mph."},"es":{"q":"En New Hampshire, usted va por una carretera estatal pavimentada de dos carriles en el campo, fuera de zonas comerciales y residenciales. Ninguna señal indica el límite. ¿Cuál es el límite de velocidad?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Es 10 mph menos que el límite habitual en una interestatal de cuatro carriles.","h2":"En New Hampshire, el límite de velocidad en una carretera pavimentada de dos carriles en el campo, fuera de zonas comerciales y residenciales, es de 55 mph cuando ninguna señal indica otra cosa.","p":"Correcto. Allí el límite es de 55 mph."},"zh":{"q":"在 New Hampshire，你在乡间一条铺好的双车道州公路上，不在商业区或住宅区。没有标志显示限速。限速是多少？","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"它比四车道州际公路的通常限速少 10 mph。","h2":"在 New Hampshire，没有标志另行规定时，乡间商业区和住宅区以外的铺好的双车道公路限速是 55 mph。","p":"对。那里限速 55 mph。"},"vi":{"q":"Ở New Hampshire, bạn đang ở trên một xa lộ tiểu bang hai làn đã trải nhựa ở vùng nông thôn, ngoài khu thương mại và khu dân cư. Không có biển báo tốc độ. Giới hạn tốc độ là bao nhiêu?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Nó thấp hơn 10 mph so với giới hạn thường lệ trên xa lộ liên bang bốn làn.","h2":"Ở New Hampshire, giới hạn tốc độ trên xa lộ hai làn đã trải nhựa ở vùng nông thôn, ngoài khu thương mại và khu dân cư, là 55 mph khi không có biển báo khác.","p":"Đúng. Giới hạn ở đó là 55 mph."},"tl":{"q":"Sa New Hampshire, nasa isang sementadong two-lane na state highway ka sa probinsya, labas sa business at residential area. Walang karatula ng limitasyon. Ano ang speed limit?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Ito ay 10 mph na mas mababa sa karaniwang limitasyon sa four-lane na interstate.","h2":"Sa New Hampshire, ang speed limit sa sementadong two-lane na highway sa probinsya, labas sa business at residential area, ay 55 mph kapag walang karatulang nagsasabi ng iba.","p":"Tama. 55 mph ang limitasyon doon."},"ar":{"q":"في New Hampshire، أنت على طريق سريع للولاية معبّد بحارتين في الريف، خارج المناطق التجارية والسكنية. لا توجد لافتة تبيّن الحد. ما حد السرعة؟","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"هو أقل بـ 10 mph من الحد المعتاد على طريق سريع بين الولايات بأربع حارات.","h2":"في New Hampshire، حد السرعة على طريق معبّد بحارتين في الريف، خارج المناطق التجارية والسكنية، هو 55 mph عندما لا توجد لافتة تقول غير ذلك.","p":"صحيح. الحد هناك 55 mph."},"ref":{"doc":"NH","page":null}},{"id":"nh-026","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, where is the speed limit set at 70 mph by state law?","o":["On every interstate highway","On part of I-93, from mile marker 45 to the Vermont border","On I-95 along the seacoast","Nowhere; the top limit is 65 mph"],"h1":"It is one stretch of a single interstate, heading north and west.","h2":"In New Hampshire, the speed limit is 70 mph on part of I-93, from mile marker 45 to the Vermont border.","p":"Right. 70 mph on I-93 from mile marker 45 to Vermont."},"es":{"q":"En New Hampshire, ¿dónde fija la ley estatal un límite de velocidad de 70 mph?","o":["En todas las carreteras interestatales","En parte de la I-93, desde la milla 45 hasta la frontera con Vermont","En la I-95 a lo largo de la costa","En ningún lugar; el límite máximo es de 65 mph"],"h1":"Es un tramo de una sola interestatal, hacia el norte y el oeste.","h2":"En New Hampshire, el límite de velocidad es de 70 mph en parte de la I-93, desde la milla 45 hasta la frontera con Vermont.","p":"Correcto. 70 mph en la I-93 desde la milla 45 hasta Vermont."},"zh":{"q":"在 New Hampshire，州法律在哪里把限速定为 70 mph？","o":["在所有州际公路上","在 I-93 的一段，从 45 号里程标到 Vermont 边界","在沿海的 I-95 上","没有地方；最高限速是 65 mph"],"h1":"它是某一条州际公路上的一段，向北和向西走。","h2":"在 New Hampshire，I-93 从 45 号里程标到 Vermont 边界的一段限速是 70 mph。","p":"对。I-93 从 45 号里程标到 Vermont 限速 70 mph。"},"vi":{"q":"Ở New Hampshire, luật tiểu bang đặt giới hạn tốc độ 70 mph ở đâu?","o":["Trên mọi xa lộ liên bang","Trên một đoạn của I-93, từ cột mốc dặm 45 đến biên giới Vermont","Trên I-95 dọc theo bờ biển","Không ở đâu cả; giới hạn cao nhất là 65 mph"],"h1":"Đó là một đoạn của một xa lộ liên bang duy nhất, đi về hướng bắc và tây.","h2":"Ở New Hampshire, giới hạn tốc độ là 70 mph trên một đoạn của I-93, từ cột mốc dặm 45 đến biên giới Vermont.","p":"Đúng. 70 mph trên I-93 từ cột mốc dặm 45 đến Vermont."},"tl":{"q":"Sa New Hampshire, saan itinakda ng batas ng estado ang speed limit na 70 mph?","o":["Sa bawat interstate highway","Sa bahagi ng I-93, mula mile marker 45 hanggang sa hangganan ng Vermont","Sa I-95 sa tabing-dagat","Wala; 65 mph ang pinakamataas na limitasyon"],"h1":"Isa itong bahagi ng iisang interstate, papuntang hilaga at kanluran.","h2":"Sa New Hampshire, ang speed limit ay 70 mph sa bahagi ng I-93, mula mile marker 45 hanggang sa hangganan ng Vermont.","p":"Tama. 70 mph sa I-93 mula mile marker 45 hanggang Vermont."},"ar":{"q":"في New Hampshire، أين يحدد قانون الولاية حد السرعة بـ 70 mph؟","o":["على كل الطرق السريعة بين الولايات","على جزء من I-93، من علامة الميل 45 إلى حدود Vermont","على I-95 على طول الساحل","لا يوجد مكان كهذا؛ أعلى حد هو 65 mph"],"h1":"هو جزء واحد من طريق سريع واحد بين الولايات، يتجه شمالًا وغربًا.","h2":"في New Hampshire، حد السرعة 70 mph على جزء من I-93، من علامة الميل 45 إلى حدود Vermont.","p":"صحيح. 70 mph على I-93 من علامة الميل 45 إلى Vermont."},"ref":{"doc":"NH","page":null}},{"id":"nh-027","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, road workers are working on or right next to the road. How fast may you drive past them?","o":["The usual posted limit","5 mph below the usual limit","25 mph, on any road","At least 10 mph below the usual limit"],"h1":"You must take off a set number, and you may slow down even more.","h2":"In New Hampshire, when workers are on or close to the road, you must drive at least 10 mph below the usual posted limit.","p":"Right. At least 10 mph under the usual limit."},"es":{"q":"En New Hampshire, hay trabajadores en la vía o justo al lado. ¿A qué velocidad puede pasar junto a ellos?","o":["Al límite habitual señalizado","5 mph menos que el límite habitual","25 mph, en cualquier vía","Al menos 10 mph menos que el límite habitual"],"h1":"Debe restar un número fijo, y puede ir aún más despacio.","h2":"En New Hampshire, cuando hay trabajadores en la vía o muy cerca, debe manejar al menos 10 mph por debajo del límite habitual señalizado.","p":"Correcto. Al menos 10 mph menos que el límite habitual."},"zh":{"q":"在 New Hampshire，道路工人正在路上或紧挨着道路工作。你开过他们旁边时可以开多快？","o":["平常标示的限速","比平常限速低 5 mph","25 mph，任何道路都一样","至少比平常限速低 10 mph"],"h1":"你必须减去一个固定的数，也可以再开慢一些。","h2":"在 New Hampshire，有工人在路上或靠近道路时，你必须开得至少比平常标示的限速低 10 mph。","p":"对。至少比平常限速低 10 mph。"},"vi":{"q":"Ở New Hampshire, công nhân làm đường đang làm việc trên đường hoặc ngay sát đường. Bạn được lái nhanh bao nhiêu khi đi qua họ?","o":["Giới hạn thường lệ có biển báo","Thấp hơn giới hạn thường lệ 5 mph","25 mph, trên mọi con đường","Thấp hơn giới hạn thường lệ ít nhất 10 mph"],"h1":"Bạn phải trừ đi một con số cố định, và bạn có thể chạy chậm hơn nữa.","h2":"Ở New Hampshire, khi công nhân ở trên đường hoặc gần đường, bạn phải lái thấp hơn giới hạn thường lệ có biển báo ít nhất 10 mph.","p":"Đúng. Thấp hơn giới hạn thường lệ ít nhất 10 mph."},"tl":{"q":"Sa New Hampshire, may mga road worker na nagtatrabaho sa kalsada o katabi mismo nito. Gaano kabilis ka puwedeng dumaan sa kanila?","o":["Ang karaniwang limitasyon sa karatula","5 mph na mas mababa sa karaniwang limitasyon","25 mph, sa anumang kalsada","Hindi bababa sa 10 mph na mas mababa sa karaniwang limitasyon"],"h1":"Kailangan mong magbawas ng tiyak na bilang, at puwede ka pang bumagal.","h2":"Sa New Hampshire, kapag may mga worker sa kalsada o malapit dito, kailangan mong magmaneho nang hindi bababa sa 10 mph na mas mababa sa karaniwang limitasyon sa karatula.","p":"Tama. Hindi bababa sa 10 mph na mas mababa sa karaniwang limitasyon."},"ar":{"q":"في New Hampshire، يعمل عمال الطرق على الطريق أو بجانبه مباشرة. ما السرعة المسموح بها عند المرور بهم؟","o":["الحد المعتاد المكتوب على اللافتة","أقل من الحد المعتاد بـ 5 mph","25 mph، على أي طريق","أقل من الحد المعتاد بـ 10 mph على الأقل"],"h1":"يجب أن تطرح رقمًا ثابتًا، ويمكنك أن تبطئ أكثر.","h2":"في New Hampshire، عندما يكون العمال على الطريق أو قريبين منه، يجب أن تقود بسرعة أقل من الحد المعتاد المكتوب بـ 10 mph على الأقل.","p":"صحيح. أقل من الحد المعتاد بـ 10 mph على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-028","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, your car has a toll transponder, such as E-ZPass. How fast may you go through a toll booth with a transponder reader that is not an open road tolling lane?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"It is a little slower than the limit in a town business area.","h2":"In New Hampshire, a car with a transponder may go no faster than 25 mph through a toll booth with a transponder reader, unless it is an open road tolling lane.","p":"Right. 25 mph through the toll booth."},"es":{"q":"En New Hampshire, su carro tiene un transpondedor de peaje, como E-ZPass. ¿A qué velocidad puede pasar por una caseta de peaje con lector de transpondedor que no es un carril de peaje abierto (open road tolling)?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Es un poco más lento que el límite en una zona comercial de un pueblo.","h2":"En New Hampshire, un carro con transpondedor no puede pasar a más de 25 mph por una caseta de peaje con lector de transpondedor, salvo en un carril de peaje abierto.","p":"Correcto. 25 mph por la caseta de peaje."},"zh":{"q":"在 New Hampshire，你的车装有收费电子标签（transponder），例如 E-ZPass。经过装有标签读取器、但不是 open road tolling 车道的收费亭时，你可以开多快？","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"它比城镇商业区的限速稍慢一点。","h2":"在 New Hampshire，装有电子标签的车经过有标签读取器的收费亭时，车速不得超过 25 mph，除非那是 open road tolling 车道。","p":"对。经过收费亭时 25 mph。"},"vi":{"q":"Ở New Hampshire, xe của bạn có thiết bị thu phí điện tử (transponder), như E-ZPass. Bạn được chạy nhanh bao nhiêu qua trạm thu phí có máy đọc thiết bị nhưng không phải làn open road tolling?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Nó chậm hơn một chút so với giới hạn trong khu thương mại của thị trấn.","h2":"Ở New Hampshire, xe có thiết bị thu phí điện tử không được chạy quá 25 mph qua trạm thu phí có máy đọc thiết bị, trừ khi đó là làn open road tolling.","p":"Đúng. 25 mph qua trạm thu phí."},"tl":{"q":"Sa New Hampshire, may toll transponder ang kotse mo, gaya ng E-ZPass. Gaano kabilis ka puwedeng dumaan sa toll booth na may transponder reader na hindi open road tolling lane?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Medyo mas mabagal ito kaysa sa limitasyon sa business area ng bayan.","h2":"Sa New Hampshire, ang kotseng may transponder ay hindi puwedeng lumampas sa 25 mph sa pagdaan sa toll booth na may transponder reader, maliban kung ito ay open road tolling lane.","p":"Tama. 25 mph sa pagdaan sa toll booth."},"ar":{"q":"في New Hampshire، في سيارتك جهاز دفع رسوم إلكتروني (transponder) مثل E-ZPass. ما السرعة المسموح بها عند المرور بكشك رسوم فيه قارئ للجهاز وليس حارة open road tolling؟","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"هي أبطأ قليلًا من الحد في منطقة الأعمال في البلدة.","h2":"في New Hampshire، يجب ألّا تزيد سرعة السيارة التي فيها جهاز رسوم إلكتروني عن 25 mph عند المرور بكشك رسوم فيه قارئ للجهاز، إلا إذا كانت حارة open road tolling.","p":"صحيح. 25 mph عند المرور بكشك الرسوم."},"ref":{"doc":"NH","page":null}},{"id":"nh-029","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"It is about the length of one car.","h2":"In New Hampshire, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a hydrant."},"es":{"q":"En New Hampshire, ¿a qué distancia de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 25 pies"],"h1":"Es más o menos el largo de un carro.","h2":"En New Hampshire, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies del hidrante."},"zh":{"q":"在 New Hampshire，你可以在离消防栓多近的地方停车？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 15 英尺","不能少于 25 英尺"],"h1":"大约是一辆车的长度。","h2":"在 New Hampshire，你不能在消防栓 15 英尺以内停车。","p":"对。离消防栓 15 英尺。"},"vi":{"q":"Ở New Hampshire, bạn được đỗ xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe.","h2":"Ở New Hampshire, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước chữa cháy.","p":"Đúng. Cách trụ nước 15 feet."},"tl":{"q":"Sa New Hampshire, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 10 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 25 feet"],"h1":"Mga kasinghaba ito ng isang kotse.","h2":"Sa New Hampshire, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang 15 feet sa hydrant."},"ar":{"q":"في New Hampshire، كم يمكنك أن تقترب من صنبور إطفاء الحريق (fire hydrant) عند الوقوف؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 25 feet"],"h1":"هي تقريبًا طول سيارة واحدة.","h2":"في New Hampshire، يجب ألّا تقف بسيارتك على بُعد أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابتعد 15 feet عن الصنبور."},"ref":{"doc":"NH","page":null}},{"id":"nh-030","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is more than the space you leave at a fire hydrant.","h2":"In New Hampshire, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay 20 feet from the crosswalk."},"es":{"q":"En New Hampshire, ¿a qué distancia de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 10 pies","No a menos de 20 pies","No a menos de 30 pies","No a menos de 50 pies"],"h1":"Es más que el espacio que deja junto a un hidrante.","h2":"En New Hampshire, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese a 20 pies del cruce peatonal."},"zh":{"q":"在 New Hampshire，你可以在离路口人行横道多近的地方停车？","o":["不能少于 10 英尺","不能少于 20 英尺","不能少于 30 英尺","不能少于 50 英尺"],"h1":"它比你在消防栓旁要留的距离更长。","h2":"在 New Hampshire，你不能在路口人行横道 20 英尺以内停车。","p":"对。离人行横道 20 英尺。"},"vi":{"q":"Ở New Hampshire, bạn được đỗ xe gần lối qua đường ở giao lộ đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Nó xa hơn khoảng cách bạn chừa ra ở trụ nước chữa cháy.","h2":"Ở New Hampshire, bạn không được đỗ xe trong vòng 20 feet tính từ lối qua đường ở giao lộ.","p":"Đúng. Cách lối qua đường 20 feet."},"tl":{"q":"Sa New Hampshire, gaano kalapit sa crosswalk sa isang interseksyon ka puwedeng pumarada?","o":["Hindi mas malapit sa 10 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 30 feet","Hindi mas malapit sa 50 feet"],"h1":"Mas malaki ito kaysa sa espasyong iniiwan mo sa fire hydrant.","h2":"Sa New Hampshire, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa crosswalk sa isang interseksyon.","p":"Tama. Lumayo nang 20 feet sa crosswalk."},"ar":{"q":"في New Hampshire، كم يمكنك أن تقترب من ممر المشاة عند تقاطع عند الوقوف؟","o":["ليس أقرب من 10 feet","ليس أقرب من 20 feet","ليس أقرب من 30 feet","ليس أقرب من 50 feet"],"h1":"هي أكثر من المسافة التي تتركها عند صنبور إطفاء الحريق.","h2":"في New Hampshire، يجب ألّا تقف بسيارتك على بُعد أقل من 20 feet من ممر المشاة عند تقاطع.","p":"صحيح. ابتعد 20 feet عن ممر المشاة."},"ref":{"doc":"NH","page":null}},{"id":"nh-031","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, you are coming up to a stop sign, a flashing signal or a traffic light at the side of the road. How close to it may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 20 feet","No closer than 30 feet"],"h1":"Drivers need room to see the sign or light, so the gap is longer than at a crosswalk.","h2":"In New Hampshire, you may not park within 30 feet before a stop sign, flashing signal or traffic light at the side of the road.","p":"Right. Stay 30 feet back."},"es":{"q":"En New Hampshire, usted se acerca a una señal de alto, una luz intermitente o un semáforo al lado de la vía. ¿A qué distancia puede estacionarse?","o":["No a menos de 10 pies","No a menos de 15 pies","No a menos de 20 pies","No a menos de 30 pies"],"h1":"Los conductores necesitan espacio para ver la señal o la luz, así que la distancia es mayor que en un cruce peatonal.","h2":"En New Hampshire, no puede estacionarse a menos de 30 pies antes de una señal de alto, una luz intermitente o un semáforo al lado de la vía.","p":"Correcto. Quédese a 30 pies."},"zh":{"q":"在 New Hampshire，你快到路边的停车标志、闪光信号灯或交通灯。你可以在离它多近的地方停车？","o":["不能少于 10 英尺","不能少于 15 英尺","不能少于 20 英尺","不能少于 30 英尺"],"h1":"司机需要空间看到标志或灯，所以距离比人行横道更长。","h2":"在 New Hampshire，你不能在路边的停车标志、闪光信号灯或交通灯前 30 英尺以内停车。","p":"对。离开 30 英尺。"},"vi":{"q":"Ở New Hampshire, bạn sắp đến một biển báo dừng, đèn nhấp nháy hoặc đèn giao thông ở bên đường. Bạn được đỗ xe gần nó đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 20 feet","Không gần hơn 30 feet"],"h1":"Người lái xe cần khoảng trống để thấy biển báo hoặc đèn, nên khoảng cách dài hơn so với ở lối qua đường.","h2":"Ở New Hampshire, bạn không được đỗ xe trong vòng 30 feet trước biển báo dừng, đèn nhấp nháy hoặc đèn giao thông ở bên đường.","p":"Đúng. Lùi lại 30 feet."},"tl":{"q":"Sa New Hampshire, papalapit ka sa stop sign, flashing signal o traffic light sa gilid ng kalsada. Gaano kalapit dito ka puwedeng pumarada?","o":["Hindi mas malapit sa 10 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 30 feet"],"h1":"Kailangan ng mga driver ng espasyo para makita ang karatula o ilaw, kaya mas mahaba ang agwat kaysa sa crosswalk.","h2":"Sa New Hampshire, hindi ka puwedeng pumarada sa loob ng 30 feet bago ang stop sign, flashing signal o traffic light sa gilid ng kalsada.","p":"Tama. Lumayo nang 30 feet."},"ar":{"q":"في New Hampshire، تقترب من لافتة توقف أو إشارة وامضة أو إشارة مرور على جانب الطريق. كم يمكنك أن تقترب منها عند الوقوف؟","o":["ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 20 feet","ليس أقرب من 30 feet"],"h1":"يحتاج السائقون إلى مساحة لرؤية اللافتة أو الإشارة، لذلك المسافة أطول منها عند ممر المشاة.","h2":"في New Hampshire، يجب ألّا تقف بسيارتك على بُعد أقل من 30 feet قبل لافتة توقف أو إشارة وامضة أو إشارة مرور على جانب الطريق.","p":"صحيح. ابقَ على بُعد 30 feet."},"ref":{"doc":"NH","page":null}},{"id":"nh-032","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is the longest of the usual parking distances.","h2":"In New Hampshire, you may not park within 50 feet of the nearest rail of a railroad crossing, except for a short stop to load or unload.","p":"Right. Stay 50 feet from the nearest rail."},"es":{"q":"En New Hampshire, ¿a qué distancia del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["No a menos de 50 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 100 pies"],"h1":"Es la mayor de las distancias comunes para estacionar.","h2":"En New Hampshire, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril, salvo una parada corta para cargar o descargar.","p":"Correcto. Quédese a 50 pies del riel más cercano."},"zh":{"q":"在 New Hampshire，你可以在离铁路道口最近的铁轨多近的地方停车？","o":["不能少于 50 英尺","不能少于 15 英尺","不能少于 25 英尺","不能少于 100 英尺"],"h1":"这是常见停车距离中最长的一个。","h2":"在 New Hampshire，你不能在铁路道口最近铁轨的 50 英尺以内停车，短暂停车上下人或装卸东西除外。","p":"对。离最近的铁轨 50 英尺。"},"vi":{"q":"Ở New Hampshire, bạn được đỗ xe gần thanh ray gần nhất của chỗ chắn tàu đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 100 feet"],"h1":"Đó là khoảng cách dài nhất trong các khoảng cách đỗ xe thường gặp.","h2":"Ở New Hampshire, bạn không được đỗ xe trong vòng 50 feet tính từ thanh ray gần nhất của chỗ chắn tàu, trừ khi dừng một lúc ngắn để đưa đón người hoặc chất dỡ hàng.","p":"Đúng. Cách thanh ray gần nhất 50 feet."},"tl":{"q":"Sa New Hampshire, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng pumarada?","o":["Hindi mas malapit sa 50 feet","Hindi mas malapit sa 15 feet","Hindi mas malapit sa 25 feet","Hindi mas malapit sa 100 feet"],"h1":"Ito ang pinakamahaba sa mga karaniwang layo sa pagparada.","h2":"Sa New Hampshire, hindi ka puwedeng pumarada sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing, maliban sa sandaling paghinto para magsakay o magbaba.","p":"Tama. Lumayo nang 50 feet sa pinakamalapit na riles."},"ar":{"q":"في New Hampshire، كم يمكنك أن تقترب من أقرب قضيب في معبر سكة حديد عند الوقوف؟","o":["ليس أقرب من 50 feet","ليس أقرب من 15 feet","ليس أقرب من 25 feet","ليس أقرب من 100 feet"],"h1":"هي أطول مسافات الوقوف المعتادة.","h2":"في New Hampshire، يجب ألّا تقف بسيارتك على بُعد أقل من 50 feet من أقرب قضيب في معبر سكة حديد، إلا لتوقف قصير للتحميل أو التنزيل.","p":"صحيح. ابتعد 50 feet عن أقرب قضيب."},"ref":{"doc":"NH","page":null}},{"id":"nh-033","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, how close to the driveway of a fire station may you park, on the same side of the street?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 100 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In New Hampshire, you may not park within 20 feet of the driveway entrance of a fire station.","p":"Right. Stay 20 feet from a fire station driveway."},"es":{"q":"En New Hampshire, ¿a qué distancia de la entrada de vehículos de una estación de bomberos puede estacionarse, del mismo lado de la calle?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 100 pies"],"h1":"Es la misma distancia que desde un cruce peatonal en una intersección.","h2":"En New Hampshire, no puede estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos.","p":"Correcto. Quédese a 20 pies de la entrada de los bomberos."},"zh":{"q":"在 New Hampshire，在同一侧街道上，你可以在离消防站车道多近的地方停车？","o":["不能少于 5 英尺","不能少于 10 英尺","不能少于 20 英尺","不能少于 100 英尺"],"h1":"它和离路口人行横道的距离一样。","h2":"在 New Hampshire，你不能在消防站车道入口 20 英尺以内停车。","p":"对。离消防站车道 20 英尺。"},"vi":{"q":"Ở New Hampshire, bạn được đỗ xe gần lối xe ra vào của trạm cứu hỏa đến mức nào, ở cùng bên đường?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 100 feet"],"h1":"Đó là cùng khoảng cách như với lối qua đường ở giao lộ.","h2":"Ở New Hampshire, bạn không được đỗ xe trong vòng 20 feet tính từ lối vào của trạm cứu hỏa.","p":"Đúng. Cách lối vào trạm cứu hỏa 20 feet."},"tl":{"q":"Sa New Hampshire, gaano kalapit sa driveway ng fire station ka puwedeng pumarada, sa parehong gilid ng kalye?","o":["Hindi mas malapit sa 5 feet","Hindi mas malapit sa 10 feet","Hindi mas malapit sa 20 feet","Hindi mas malapit sa 100 feet"],"h1":"Pareho ito ng layo mula sa crosswalk sa isang interseksyon.","h2":"Sa New Hampshire, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa pasukan ng driveway ng fire station.","p":"Tama. Lumayo nang 20 feet sa driveway ng fire station."},"ar":{"q":"في New Hampshire، كم يمكنك أن تقترب من مدخل سيارات محطة الإطفاء عند الوقوف، في الجانب نفسه من الشارع؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 20 feet","ليس أقرب من 100 feet"],"h1":"هي المسافة نفسها كما من ممر المشاة عند تقاطع.","h2":"في New Hampshire، يجب ألّا تقف بسيارتك على بُعد أقل من 20 feet من مدخل سيارات محطة الإطفاء.","p":"صحيح. ابتعد 20 feet عن مدخل محطة الإطفاء."},"ref":{"doc":"NH","page":null}},{"id":"nh-034","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a school bus is stopped with its red lights flashing. How far from the bus must you stop?","o":["At least 10 feet away","At least 25 feet away","At least 50 feet away","At least 100 feet away"],"h1":"It is a little less than two car lengths.","h2":"In New Hampshire, you must stop at least 25 feet from a school bus with flashing red lights and wait until it moves or the lights stop.","p":"Right. Stop at least 25 feet away."},"es":{"q":"En New Hampshire, un autobús escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 10 pies","Al menos a 25 pies","Al menos a 50 pies","Al menos a 100 pies"],"h1":"Es un poco menos que el largo de dos carros.","h2":"En New Hampshire, debe detenerse al menos a 25 pies de un autobús escolar con luces rojas intermitentes y esperar hasta que se mueva o se apaguen las luces.","p":"Correcto. Deténgase al menos a 25 pies."},"zh":{"q":"在 New Hampshire，一辆校车停着，红灯在闪。你必须在离校车多远的地方停车？","o":["至少 10 英尺","至少 25 英尺","至少 50 英尺","至少 100 英尺"],"h1":"比两个车身长度稍短一点。","h2":"在 New Hampshire，你必须在离红灯闪烁的校车至少 25 英尺的地方停下，等到校车开走或灯停止闪烁。","p":"对。至少在 25 英尺外停下。"},"vi":{"q":"Ở New Hampshire, một xe buýt trường học đang dừng với đèn đỏ nhấp nháy. Bạn phải dừng cách xe buýt bao xa?","o":["Ít nhất 10 feet","Ít nhất 25 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Ngắn hơn một chút so với chiều dài hai chiếc xe.","h2":"Ở New Hampshire, bạn phải dừng cách xe buýt trường học có đèn đỏ nhấp nháy ít nhất 25 feet và chờ đến khi xe chạy hoặc đèn tắt.","p":"Đúng. Dừng cách ít nhất 25 feet."},"tl":{"q":"Sa New Hampshire, nakahinto ang isang school bus na kumikislap ang pulang ilaw. Gaano kalayo sa bus ka dapat huminto?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet"],"h1":"Medyo kulang ito sa haba ng dalawang kotse.","h2":"Sa New Hampshire, kailangan mong huminto nang hindi bababa sa 25 feet mula sa school bus na kumikislap ang pulang ilaw at maghintay hanggang umandar ito o tumigil ang ilaw.","p":"Tama. Huminto nang hindi bababa sa 25 feet ang layo."},"ar":{"q":"في New Hampshire، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض. على أي بُعد من الحافلة يجب أن تتوقف؟","o":["على بُعد 10 feet على الأقل","على بُعد 25 feet على الأقل","على بُعد 50 feet على الأقل","على بُعد 100 feet على الأقل"],"h1":"هي أقل قليلًا من طول سيارتين.","h2":"في New Hampshire، يجب أن تتوقف على بُعد 25 feet على الأقل من حافلة مدرسية أضواؤها الحمراء تومض، وأن تنتظر حتى تتحرك أو تتوقف الأضواء.","p":"صحيح. توقف على بُعد 25 feet على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-035","scope":"NH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Hampshire, you are on a divided highway with separate roadways. A school bus going the other way is stopped on the other roadway with red lights flashing. What must you do?","o":["Stop at least 25 feet away until the bus moves","Pull onto the shoulder and stop","Slow to 10 mph as you pass","You do not need to stop"],"h1":"The bus is on a separate roadway, going the opposite way.","h2":"In New Hampshire, on a divided highway with separate roadways, you do not need to stop for a school bus going the opposite way.","p":"Right. On a divided highway, oncoming traffic does not stop."},"es":{"q":"En New Hampshire, usted va por una carretera dividida con calzadas separadas. Un autobús escolar que va en sentido contrario está detenido en la otra calzada con luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse al menos a 25 pies hasta que el autobús se mueva","Salir al acotamiento y detenerse","Bajar a 10 mph al pasar","No necesita detenerse"],"h1":"El autobús está en una calzada separada y va en sentido contrario.","h2":"En New Hampshire, en una carretera dividida con calzadas separadas, no necesita detenerse por un autobús escolar que va en sentido contrario.","p":"Correcto. En una carretera dividida, el tránsito en sentido contrario no se detiene."},"zh":{"q":"在 New Hampshire，你在一条有分开路面的分隔公路上。一辆反方向行驶的校车停在另一边路面上，红灯在闪。你必须怎么做？","o":["在至少 25 英尺外停下，直到校车开走","开到路肩上停下","经过时减速到 10 mph","你不需要停车"],"h1":"校车在另一条分开的路面上，方向相反。","h2":"在 New Hampshire，在有分开路面的分隔公路上，你不需要为反方向行驶的校车停车。","p":"对。在分隔公路上，对向车辆不用停。"},"vi":{"q":"Ở New Hampshire, bạn đang ở trên xa lộ có dải phân cách với hai mặt đường riêng. Một xe buýt trường học chạy chiều ngược lại đang dừng ở mặt đường bên kia với đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Dừng cách ít nhất 25 feet cho đến khi xe buýt chạy","Tấp vào lề đường và dừng","Giảm xuống 10 mph khi đi ngang qua","Bạn không cần dừng"],"h1":"Xe buýt ở trên một mặt đường riêng, đi theo chiều ngược lại.","h2":"Ở New Hampshire, trên xa lộ có dải phân cách với hai mặt đường riêng, bạn không cần dừng cho xe buýt trường học chạy chiều ngược lại.","p":"Đúng. Trên xa lộ có dải phân cách, xe chiều ngược lại không phải dừng."},"tl":{"q":"Sa New Hampshire, nasa divided highway ka na may magkahiwalay na daan. Nakahinto sa kabilang daan ang isang school bus na papunta sa kabilang direksyon, kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Huminto nang hindi bababa sa 25 feet ang layo hanggang umandar ang bus","Tumabi sa shoulder at huminto","Bumagal sa 10 mph habang dumadaan","Hindi mo kailangang huminto"],"h1":"Nasa hiwalay na daan ang bus, papunta sa kabilang direksyon.","h2":"Sa New Hampshire, sa divided highway na may magkahiwalay na daan, hindi mo kailangang huminto para sa school bus na papunta sa kabilang direksyon.","p":"Tama. Sa divided highway, hindi humihinto ang mga sasakyang galing sa kabila."},"ar":{"q":"في New Hampshire، أنت على طريق سريع مقسوم له طريقان منفصلان. حافلة مدرسية تسير في الاتجاه الآخر متوقفة على الطريق الآخر وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["أن تتوقف على بُعد 25 feet على الأقل حتى تتحرك الحافلة","أن تنتقل إلى كتف الطريق وتتوقف","أن تبطئ إلى 10 mph وأنت تمر","ليس عليك أن تتوقف"],"h1":"الحافلة على طريق منفصل، وتسير في الاتجاه المعاكس.","h2":"في New Hampshire، على طريق سريع مقسوم له طريقان منفصلان، ليس عليك أن تتوقف لحافلة مدرسية تسير في الاتجاه المعاكس.","p":"صحيح. على الطريق المقسوم، لا تتوقف السيارات القادمة من الاتجاه الآخر."},"ref":{"doc":"NH","page":null}},{"id":"nh-036","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, you pass a bicycle while driving at 50 mph. What is the smallest gap the law treats as safe?","o":["3 feet","4 feet","5 feet","6 feet"],"h1":"The 3-foot rule is for 30 mph or less. Above that, you need more room.","h2":"In New Hampshire, the gap starts at 3 feet at 30 mph or less and grows by one foot for every 10 mph above 30, so at 50 mph it is 5 feet.","p":"Right. At 50 mph, give at least 5 feet."},"es":{"q":"En New Hampshire, usted rebasa a una bicicleta manejando a 50 mph. ¿Cuál es el espacio mínimo que la ley considera seguro?","o":["3 pies","4 pies","5 pies","6 pies"],"h1":"La regla de 3 pies es para 30 mph o menos. Más rápido, necesita más espacio.","h2":"En New Hampshire, el espacio empieza en 3 pies a 30 mph o menos y aumenta un pie por cada 10 mph por encima de 30, así que a 50 mph es de 5 pies.","p":"Correcto. A 50 mph, deje al menos 5 pies."},"zh":{"q":"在 New Hampshire，你以 50 mph 的速度超过一辆自行车。法律认为安全的最小间距是多少？","o":["3 英尺","4 英尺","5 英尺","6 英尺"],"h1":"3 英尺的规定适用于 30 mph 或更慢。速度更快时，你需要更多空间。","h2":"在 New Hampshire，间距在 30 mph 或更慢时从 3 英尺开始，超过 30 mph 后每多 10 mph 就多 1 英尺，所以在 50 mph 时是 5 英尺。","p":"对。在 50 mph 时，至少留 5 英尺。"},"vi":{"q":"Ở New Hampshire, bạn vượt một chiếc xe đạp khi đang chạy 50 mph. Khoảng cách nhỏ nhất mà luật coi là an toàn là bao nhiêu?","o":["3 feet","4 feet","5 feet","6 feet"],"h1":"Quy tắc 3 feet là cho tốc độ 30 mph trở xuống. Nhanh hơn thì bạn cần nhiều chỗ hơn.","h2":"Ở New Hampshire, khoảng cách bắt đầu từ 3 feet ở 30 mph trở xuống và tăng thêm một foot cho mỗi 10 mph trên 30, nên ở 50 mph là 5 feet.","p":"Đúng. Ở 50 mph, chừa ít nhất 5 feet."},"tl":{"q":"Sa New Hampshire, nag-overtake ka sa isang bisikleta habang nagmamaneho nang 50 mph. Ano ang pinakamaliit na agwat na itinuturing ng batas na ligtas?","o":["3 feet","4 feet","5 feet","6 feet"],"h1":"Ang 3-foot na tuntunin ay para sa 30 mph o mas mabagal. Kapag mas mabilis, kailangan mo ng mas maraming espasyo.","h2":"Sa New Hampshire, nagsisimula ang agwat sa 3 feet sa 30 mph o mas mabagal at nadadagdagan ng isang foot sa bawat 10 mph na lampas sa 30, kaya sa 50 mph ay 5 feet ito.","p":"Tama. Sa 50 mph, magbigay ng hindi bababa sa 5 feet."},"ar":{"q":"في New Hampshire، تتجاوز دراجة هوائية وأنت تقود بسرعة 50 mph. ما أصغر مسافة يعتبرها القانون آمنة؟","o":["3 feet","4 feet","5 feet","6 feet"],"h1":"قاعدة 3 feet هي لسرعة 30 mph أو أقل. فوق ذلك تحتاج إلى مساحة أكبر.","h2":"في New Hampshire، تبدأ المسافة من 3 feet عند 30 mph أو أقل، وتزيد قدمًا واحدة لكل 10 mph فوق 30، لذلك تكون عند 50 mph هي 5 feet.","p":"صحيح. عند 50 mph، اترك 5 feet على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-037","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, which child passenger must ride in an approved child restraint, such as a car seat or booster seat?","o":["A child under 7 who is shorter than 57 inches","Any child under 12","Only a child under 4","Any child shorter than 4 feet, at any age"],"h1":"The rule uses both an age and a height.","h2":"In New Hampshire, a child under 7 must ride in an approved child restraint unless the child is 57 inches tall or more.","p":"Right. Under 7 and under 57 inches means a child restraint."},"es":{"q":"En New Hampshire, ¿qué niño pasajero debe ir en un sistema de retención infantil aprobado, como una silla de auto o un asiento elevador?","o":["Un niño menor de 7 años que mide menos de 57 pulgadas","Cualquier niño menor de 12 años","Solo un niño menor de 4 años","Cualquier niño que mide menos de 4 pies, a cualquier edad"],"h1":"La regla usa una edad y una estatura.","h2":"En New Hampshire, un niño menor de 7 años debe ir en un sistema de retención infantil aprobado, salvo que mida 57 pulgadas o más.","p":"Correcto. Menor de 7 años y de menos de 57 pulgadas va en asiento infantil."},"zh":{"q":"在 New Hampshire，哪个儿童乘客必须坐在核准的儿童约束装置里，例如儿童安全座椅或增高座椅？","o":["7 岁以下、身高不到 57 英寸的儿童","任何 12 岁以下的儿童","只有 4 岁以下的儿童","任何身高不到 4 英尺的儿童，不论年龄"],"h1":"这条规定同时看年龄和身高。","h2":"在 New Hampshire，7 岁以下的儿童必须坐在核准的儿童约束装置里，除非孩子身高达到 57 英寸或以上。","p":"对。7 岁以下且不到 57 英寸，就要用儿童约束装置。"},"vi":{"q":"Ở New Hampshire, hành khách trẻ em nào phải ngồi trong thiết bị giữ trẻ được chấp thuận, như ghế ô tô cho trẻ hoặc ghế nâng?","o":["Trẻ dưới 7 tuổi và thấp hơn 57 inches","Mọi trẻ dưới 12 tuổi","Chỉ trẻ dưới 4 tuổi","Mọi trẻ thấp hơn 4 feet, ở bất kỳ tuổi nào"],"h1":"Quy tắc này dùng cả tuổi và chiều cao.","h2":"Ở New Hampshire, trẻ dưới 7 tuổi phải ngồi trong thiết bị giữ trẻ được chấp thuận, trừ khi trẻ cao 57 inches trở lên.","p":"Đúng. Dưới 7 tuổi và thấp hơn 57 inches thì phải dùng thiết bị giữ trẻ."},"tl":{"q":"Sa New Hampshire, aling batang pasahero ang dapat nakasakay sa aprubadong child restraint, gaya ng car seat o booster seat?","o":["Batang wala pang 7 taong gulang na mas maikli sa 57 inches","Sinumang batang wala pang 12","Batang wala pang 4 lang","Sinumang batang mas maikli sa 4 feet, anuman ang edad"],"h1":"Gumagamit ang tuntunin ng edad at taas.","h2":"Sa New Hampshire, ang batang wala pang 7 taong gulang ay dapat nakasakay sa aprubadong child restraint maliban kung 57 inches o higit pa ang taas niya.","p":"Tama. Wala pang 7 at wala pang 57 inches ay nangangahulugang child restraint."},"ar":{"q":"في New Hampshire، أي طفل راكب يجب أن يجلس في وسيلة تقييد معتمدة للأطفال، مثل مقعد السيارة للأطفال أو المقعد الرافع؟","o":["طفل عمره أقل من 7 سنوات وطوله أقل من 57 inches","أي طفل عمره أقل من 12 سنة","فقط طفل عمره أقل من 4 سنوات","أي طفل طوله أقل من 4 feet، في أي عمر"],"h1":"تستخدم القاعدة العمر والطول معًا.","h2":"في New Hampshire، يجب أن يجلس الطفل الذي عمره أقل من 7 سنوات في وسيلة تقييد معتمدة للأطفال، إلا إذا كان طوله 57 inches أو أكثر.","p":"صحيح. أقل من 7 سنوات وأقل من 57 inches يعني وسيلة تقييد للأطفال."},"ref":{"doc":"NH","page":null}},{"id":"nh-038","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, a child under what age must ride in a rear-facing car seat?","o":["Under 6 months","Under 1 year","Under 4 years","Under 2 years"],"h1":"It covers babies and young toddlers.","h2":"In New Hampshire, a child under 2 years old must ride in a rear-facing child restraint.","p":"Right. Under 2 rides rear-facing."},"es":{"q":"En New Hampshire, ¿un niño menor de qué edad debe ir en una silla de auto mirando hacia atrás?","o":["Menor de 6 meses","Menor de 1 año","Menor de 4 años","Menor de 2 años"],"h1":"Incluye a bebés y a niños que recién empiezan a caminar.","h2":"En New Hampshire, un niño menor de 2 años debe ir en un sistema de retención infantil mirando hacia atrás.","p":"Correcto. Menores de 2 años van mirando hacia atrás."},"zh":{"q":"在 New Hampshire，多大以下的儿童必须坐后向式儿童安全座椅？","o":["6 个月以下","1 岁以下","4 岁以下","2 岁以下"],"h1":"它包括婴儿和刚学走路的幼儿。","h2":"在 New Hampshire，2 岁以下的儿童必须坐在后向式儿童约束装置里。","p":"对。2 岁以下坐后向式座椅。"},"vi":{"q":"Ở New Hampshire, trẻ dưới bao nhiêu tuổi phải ngồi ghế ô tô quay mặt về phía sau?","o":["Dưới 6 tháng","Dưới 1 tuổi","Dưới 4 tuổi","Dưới 2 tuổi"],"h1":"Nó bao gồm em bé và trẻ mới biết đi.","h2":"Ở New Hampshire, trẻ dưới 2 tuổi phải ngồi trong thiết bị giữ trẻ quay mặt về phía sau.","p":"Đúng. Dưới 2 tuổi ngồi quay mặt về phía sau."},"tl":{"q":"Sa New Hampshire, ang batang wala pa sa anong edad ang dapat nakasakay sa rear-facing na car seat?","o":["Wala pang 6 na buwan","Wala pang 1 taon","Wala pang 4 na taon","Wala pang 2 taon"],"h1":"Saklaw nito ang mga sanggol at maliliit na batang nagsisimulang maglakad.","h2":"Sa New Hampshire, ang batang wala pang 2 taong gulang ay dapat nakasakay sa rear-facing na child restraint.","p":"Tama. Ang wala pang 2 ay nakasakay nang rear-facing."},"ar":{"q":"في New Hampshire، الطفل الذي عمره أقل من كم يجب أن يجلس في مقعد سيارة مواجه للخلف؟","o":["أقل من 6 أشهر","أقل من 1 سنة","أقل من 4 سنوات","أقل من 2 سنة"],"h1":"يشمل الرضّع والأطفال الصغار الذين بدأوا المشي.","h2":"في New Hampshire، يجب أن يجلس الطفل الذي عمره أقل من 2 سنة في وسيلة تقييد للأطفال مواجهة للخلف.","p":"صحيح. من عمره أقل من 2 سنة يجلس مواجهًا للخلف."},"ref":{"doc":"NH","page":null}},{"id":"nh-039","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, which rule applies to a rider with a motorcycle learner's permit?","o":["May ride at any hour with one passenger","May ride only in daylight and may not carry passengers","May ride only on interstate highways","May ride at night only with a passenger 25 or older"],"h1":"A new rider rides alone, when it is easiest to see.","h2":"In New Hampshire, a motorcycle learner's permit allows riding only between sunrise and sunset, with no passengers.","p":"Right. Daylight only, and no passengers."},"es":{"q":"En New Hampshire, ¿qué regla se aplica a un motociclista con permiso de aprendiz de motocicleta?","o":["Puede manejar a cualquier hora con un pasajero","Puede manejar solo de día y no puede llevar pasajeros","Puede manejar solo en carreteras interestatales","Puede manejar de noche solo con un pasajero de 25 años o más"],"h1":"Un motociclista nuevo va solo, cuando es más fácil ver.","h2":"En New Hampshire, el permiso de aprendiz de motocicleta permite manejar solo entre la salida y la puesta del sol, sin pasajeros.","p":"Correcto. Solo de día y sin pasajeros."},"zh":{"q":"在 New Hampshire，持有摩托车学习许可的骑手要遵守哪条规定？","o":["任何时间都可以骑，可以带一名乘客","只能在白天骑，不能带乘客","只能在州际公路上骑","晚上只能和 25 岁或以上的乘客一起骑"],"h1":"新骑手要一个人骑，在最容易看清的时候骑。","h2":"在 New Hampshire，摩托车学习许可只允许在日出到日落之间骑车，而且不能带乘客。","p":"对。只在白天，不带乘客。"},"vi":{"q":"Ở New Hampshire, quy tắc nào áp dụng cho người lái có giấy phép tập lái xe máy?","o":["Được chạy vào bất kỳ giờ nào với một người ngồi sau","Chỉ được chạy ban ngày và không được chở người","Chỉ được chạy trên xa lộ liên bang","Chỉ được chạy ban đêm với người ngồi sau từ 25 tuổi trở lên"],"h1":"Người mới tập lái đi một mình, vào lúc dễ nhìn thấy nhất.","h2":"Ở New Hampshire, giấy phép tập lái xe máy chỉ cho phép chạy từ lúc mặt trời mọc đến lúc mặt trời lặn, và không được chở người.","p":"Đúng. Chỉ ban ngày, và không chở người."},"tl":{"q":"Sa New Hampshire, anong tuntunin ang para sa rider na may motorcycle learner's permit?","o":["Puwedeng magmaneho anumang oras na may isang pasahero","Puwedeng magmaneho sa araw lang at hindi puwedeng magsakay ng pasahero","Puwedeng magmaneho sa interstate highway lang","Puwedeng magmaneho sa gabi kung may pasaherong 25 o mas matanda lang"],"h1":"Mag-isa ang bagong rider, sa oras na pinakamadaling makakita.","h2":"Sa New Hampshire, ang motorcycle learner's permit ay pumapayag lang magmaneho mula pagsikat hanggang paglubog ng araw, nang walang pasahero.","p":"Tama. Sa araw lang, at walang pasahero."},"ar":{"q":"في New Hampshire، أي قاعدة تنطبق على راكب يحمل تصريح تعلّم قيادة الدراجة النارية (learner's permit)؟","o":["يمكنه القيادة في أي ساعة مع راكب واحد","يمكنه القيادة في النهار فقط ويجب ألّا يحمل ركابًا","يمكنه القيادة على الطرق السريعة بين الولايات فقط","يمكنه القيادة ليلًا فقط مع راكب عمره 25 سنة أو أكثر"],"h1":"السائق الجديد يقود وحده، في الوقت الذي تكون فيه الرؤية أسهل.","h2":"في New Hampshire، تصريح تعلّم قيادة الدراجة النارية يسمح بالقيادة فقط بين شروق الشمس وغروبها، بدون ركاب.","p":"صحيح. في النهار فقط، وبدون ركاب."},"ref":{"doc":"NH","page":null}},{"id":"nh-040","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, during what period does the law require your vehicle's lamps to be lit?","o":["Only from 9 p.m. to 5 a.m.","From half an hour after sunset to half an hour before sunrise","From 1 hour after sunset to 1 hour before sunrise","Only when the street lights are off"],"h1":"It starts a short time after the sun goes down.","h2":"In New Hampshire, your lamps must be lit from half an hour after sunset to half an hour before sunrise.","p":"Right. Lights on from half an hour after sunset to half an hour before sunrise."},"es":{"q":"En New Hampshire, ¿durante qué período exige la ley que las luces de su vehículo estén encendidas?","o":["Solo de 9 p.m. a 5 a.m.","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Desde 1 hora después de la puesta del sol hasta 1 hora antes de la salida del sol","Solo cuando las luces de la calle están apagadas"],"h1":"Empieza poco después de que se pone el sol.","h2":"En New Hampshire, las luces deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Luces encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida."},"zh":{"q":"在 New Hampshire，法律要求你的车灯在什么时间段要打开？","o":["只在晚上 9 点到早上 5 点","从日落后半小时到日出前半小时","从日落后 1 小时到日出前 1 小时","只在路灯关着的时候"],"h1":"它在太阳下山后不久开始。","h2":"在 New Hampshire，从日落后半小时到日出前半小时，你的车灯必须打开。","p":"对。从日落后半小时到日出前半小时开灯。"},"vi":{"q":"Ở New Hampshire, luật yêu cầu đèn xe của bạn phải bật trong khoảng thời gian nào?","o":["Chỉ từ 9 giờ tối đến 5 giờ sáng","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc","Từ 1 giờ sau khi mặt trời lặn đến 1 giờ trước khi mặt trời mọc","Chỉ khi đèn đường tắt"],"h1":"Nó bắt đầu một lúc ngắn sau khi mặt trời lặn.","h2":"Ở New Hampshire, đèn xe của bạn phải bật từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Bật đèn từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa New Hampshire, kailan hinihingi ng batas na nakabukas ang mga ilaw ng sasakyan mo?","o":["Mula 9 p.m. hanggang 5 a.m. lang","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw","Mula 1 oras pagkalubog ng araw hanggang 1 oras bago sumikat ang araw","Kapag patay lang ang mga ilaw sa kalye"],"h1":"Nagsisimula ito ilang sandali pagkalubog ng araw.","h2":"Sa New Hampshire, dapat nakabukas ang mga ilaw mo mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Nakabukas ang ilaw mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ito."},"ar":{"q":"في New Hampshire، في أي فترة يطلب القانون أن تكون أضواء سيارتك مُشعلة؟","o":["فقط من 9 مساءً إلى 5 صباحًا","من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق","من 1 ساعة بعد الغروب إلى 1 ساعة قبل الشروق","فقط عندما تكون أضواء الشارع مطفأة"],"h1":"تبدأ بعد وقت قصير من غروب الشمس.","h2":"في New Hampshire، يجب أن تكون أضواء سيارتك مُشعلة من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق.","p":"صحيح. الأضواء مُشعلة من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق."},"ref":{"doc":"NH","page":null}},{"id":"nh-041","scope":"NH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Hampshire, a fire truck is going to a fire alarm. How close behind it may you follow?","o":["No closer than 500 feet","No closer than 100 feet","No closer than 200 feet","No closer than 1,000 feet"],"h1":"It is about the length of one and a half football fields.","h2":"In New Hampshire, you may not follow a fire truck answering an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En New Hampshire, un camión de bomberos va a atender una alarma de incendio. ¿A qué distancia detrás de él puede seguirlo?","o":["No a menos de 500 pies","No a menos de 100 pies","No a menos de 200 pies","No a menos de 1,000 pies"],"h1":"Es más o menos el largo de una cancha y media de fútbol americano.","h2":"En New Hampshire, no puede seguir a un camión de bomberos que atiende una alarma a menos de 500 pies.","p":"Correcto. Quédese al menos a 500 pies detrás."},"zh":{"q":"在 New Hampshire，一辆消防车正赶去处理火警。你可以跟在它后面多近？","o":["不能少于 500 英尺","不能少于 100 英尺","不能少于 200 英尺","不能少于 1,000 英尺"],"h1":"大约是一个半橄榄球场的长度。","h2":"在 New Hampshire，你跟在赶去处理火警的消防车后面时，距离不能少于 500 英尺。","p":"对。至少在后面 500 英尺。"},"vi":{"q":"Ở New Hampshire, một xe cứu hỏa đang đi đến nơi báo cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 500 feet","Không gần hơn 100 feet","Không gần hơn 200 feet","Không gần hơn 1,000 feet"],"h1":"Khoảng bằng chiều dài một sân bóng bầu dục rưỡi.","h2":"Ở New Hampshire, bạn không được chạy theo sau xe cứu hỏa đang đi báo cháy gần hơn 500 feet.","p":"Đúng. Ở phía sau ít nhất 500 feet."},"tl":{"q":"Sa New Hampshire, papunta ang isang fire truck sa isang fire alarm. Gaano kalapit sa likod nito ka puwedeng sumunod?","o":["Hindi mas malapit sa 500 feet","Hindi mas malapit sa 100 feet","Hindi mas malapit sa 200 feet","Hindi mas malapit sa 1,000 feet"],"h1":"Mga kasinghaba ito ng isa't kalahating football field.","h2":"Sa New Hampshire, hindi ka puwedeng sumunod sa fire truck na rumeresponde sa alarm nang mas malapit sa 500 feet.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod."},"ar":{"q":"في New Hampshire، سيارة إطفاء متجهة إلى إنذار حريق. كم يمكنك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 500 feet","ليس أقرب من 100 feet","ليس أقرب من 200 feet","ليس أقرب من 1,000 feet"],"h1":"هي تقريبًا طول ملعب كرة قدم أمريكية ونصف.","h2":"في New Hampshire، يجب ألّا تسير خلف سيارة إطفاء متجهة إلى إنذار على بُعد أقل من 500 feet.","p":"صحيح. ابقَ خلفها على بُعد 500 feet على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-042","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you are in a crash and no police officer investigates it. When must you send a written report to the Division of Motor Vehicles?","o":["Within 24 hours, for any crash","Within 30 days, if damage is over $500","Within 15 days, if anyone is hurt or killed or damage is over $1,000","Only if your insurance company asks for one"],"h1":"The report is needed for injuries or larger damage, and you have about two weeks.","h2":"In New Hampshire, if no officer investigates, you must report in writing to the Division of Motor Vehicles within 15 days when anyone is hurt or killed or damage is over $1,000.","p":"Right. Within 15 days, for injury, death or damage over $1,000."},"es":{"q":"En New Hampshire, usted tiene un choque y ningún policía lo investiga. ¿Cuándo debe enviar un informe por escrito a la División de Vehículos Motorizados?","o":["En 24 horas, para cualquier choque","En 30 días, si los daños pasan de $500","En 15 días, si alguien resulta herido o muerto o los daños pasan de $1,000","Solo si su compañía de seguros lo pide"],"h1":"El informe se exige por heridos o daños mayores, y usted tiene unas dos semanas.","h2":"En New Hampshire, si ningún policía investiga, debe informar por escrito a la División de Vehículos Motorizados en 15 días cuando alguien resulta herido o muerto o los daños pasan de $1,000.","p":"Correcto. En 15 días, por heridos, muertos o daños de más de $1,000."},"zh":{"q":"在 New Hampshire，你发生了车祸，没有警察来调查。你必须在什么时候向机动车管理处（Division of Motor Vehicles）寄书面报告？","o":["任何车祸都要在 24 小时内","损失超过 $500 时在 30 天内","有人受伤或死亡，或损失超过 $1,000 时在 15 天内","只有保险公司要求时"],"h1":"有人受伤或损失较大时需要报告，你大约有两周时间。","h2":"在 New Hampshire，如果没有警察调查，当有人受伤或死亡、或损失超过 $1,000 时，你必须在 15 天内向机动车管理处寄书面报告。","p":"对。有伤亡或损失超过 $1,000 时，在 15 天内报告。"},"vi":{"q":"Ở New Hampshire, bạn bị tai nạn và không có cảnh sát nào điều tra. Khi nào bạn phải gửi báo cáo bằng văn bản cho Division of Motor Vehicles?","o":["Trong vòng 24 giờ, cho mọi tai nạn","Trong vòng 30 ngày, nếu thiệt hại trên $500","Trong vòng 15 ngày, nếu có người bị thương hoặc chết hoặc thiệt hại trên $1,000","Chỉ khi công ty bảo hiểm của bạn yêu cầu"],"h1":"Báo cáo cần khi có người bị thương hoặc thiệt hại lớn hơn, và bạn có khoảng hai tuần.","h2":"Ở New Hampshire, nếu không có cảnh sát điều tra, bạn phải báo cáo bằng văn bản cho Division of Motor Vehicles trong vòng 15 ngày khi có người bị thương hoặc chết hoặc thiệt hại trên $1,000.","p":"Đúng. Trong vòng 15 ngày, khi có người bị thương, chết hoặc thiệt hại trên $1,000."},"tl":{"q":"Sa New Hampshire, nabangga ka at walang pulis na nag-imbestiga. Kailan mo dapat ipadala ang nakasulat na ulat sa Division of Motor Vehicles?","o":["Sa loob ng 24 na oras, para sa anumang banggaan","Sa loob ng 30 araw, kung lampas sa $500 ang pinsala","Sa loob ng 15 araw, kung may nasaktan o namatay o lampas sa $1,000 ang pinsala","Kapag hiningi lang ng insurance company mo"],"h1":"Kailangan ang ulat kapag may nasaktan o mas malaki ang pinsala, at mga dalawang linggo ang mayroon ka.","h2":"Sa New Hampshire, kung walang pulis na nag-imbestiga, kailangan mong mag-ulat nang nakasulat sa Division of Motor Vehicles sa loob ng 15 araw kapag may nasaktan o namatay o lampas sa $1,000 ang pinsala.","p":"Tama. Sa loob ng 15 araw, kapag may nasaktan, namatay o lampas sa $1,000 ang pinsala."},"ar":{"q":"في New Hampshire، تعرضت لحادث ولم يحقق فيه أي شرطي. متى يجب أن ترسل تقريرًا مكتوبًا إلى قسم المركبات (Division of Motor Vehicles)؟","o":["خلال 24 ساعة، لأي حادث","خلال 30 يومًا، إذا كان الضرر أكثر من $500","خلال 15 يومًا، إذا أُصيب أحد أو مات أو كان الضرر أكثر من $1,000","فقط إذا طلبت شركة التأمين ذلك"],"h1":"التقرير مطلوب عند الإصابات أو الضرر الأكبر، ولديك نحو أسبوعين.","h2":"في New Hampshire، إذا لم يحقق أي شرطي، يجب أن ترسل تقريرًا مكتوبًا إلى قسم المركبات خلال 15 يومًا عندما يُصاب أحد أو يموت أو يكون الضرر أكثر من $1,000.","p":"صحيح. خلال 15 يومًا، عند الإصابة أو الوفاة أو ضرر أكثر من $1,000."},"ref":{"doc":"NH","page":null}},{"id":"nh-043","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you hit a dog or a cat with your car. What must you do?","o":["Nothing, if the animal ran away","Report it only if the animal dies","Call your insurance company within 30 days","Report it as soon as possible to the owner or a police officer"],"h1":"Someone needs to know about the animal quickly.","h2":"In New Hampshire, if you hit a dog or a cat, you must report it as soon as possible to the owner or to a police officer.","p":"Right. Tell the owner or the police as soon as you can."},"es":{"q":"En New Hampshire, usted atropella a un perro o un gato con su carro. ¿Qué debe hacer?","o":["Nada, si el animal se fue corriendo","Informarlo solo si el animal muere","Llamar a su compañía de seguros en 30 días","Informarlo lo antes posible al dueño o a un policía"],"h1":"Alguien debe saber pronto lo que le pasó al animal.","h2":"En New Hampshire, si atropella a un perro o un gato, debe informarlo lo antes posible al dueño o a un policía.","p":"Correcto. Avise al dueño o a la policía lo antes posible."},"zh":{"q":"在 New Hampshire，你开车撞到了一只狗或猫。你必须怎么做？","o":["如果动物跑掉了，就什么都不用做","只有动物死了才报告","在 30 天内打电话给保险公司","尽快向主人或警察报告"],"h1":"需要有人尽快知道这只动物的情况。","h2":"在 New Hampshire，如果你撞到狗或猫，必须尽快向主人或警察报告。","p":"对。尽快告诉主人或警察。"},"vi":{"q":"Ở New Hampshire, bạn lái xe đụng phải một con chó hoặc mèo. Bạn phải làm gì?","o":["Không cần làm gì, nếu con vật đã chạy đi","Chỉ báo nếu con vật chết","Gọi công ty bảo hiểm trong vòng 30 ngày","Báo càng sớm càng tốt cho chủ hoặc cảnh sát"],"h1":"Cần có người biết về con vật thật nhanh.","h2":"Ở New Hampshire, nếu bạn đụng phải chó hoặc mèo, bạn phải báo càng sớm càng tốt cho chủ hoặc cho cảnh sát.","p":"Đúng. Báo cho chủ hoặc cảnh sát càng sớm càng tốt."},"tl":{"q":"Sa New Hampshire, nabangga ng kotse mo ang isang aso o pusa. Ano ang dapat mong gawin?","o":["Wala, kung tumakbo palayo ang hayop","Mag-ulat lang kung mamatay ang hayop","Tawagan ang insurance company mo sa loob ng 30 araw","Iulat ito sa lalong madaling panahon sa may-ari o sa pulis"],"h1":"Kailangang malaman agad ng isang tao ang tungkol sa hayop.","h2":"Sa New Hampshire, kung nakabangga ka ng aso o pusa, kailangan mong iulat ito sa lalong madaling panahon sa may-ari o sa pulis.","p":"Tama. Sabihan ang may-ari o ang pulis sa lalong madaling panahon."},"ar":{"q":"في New Hampshire، صدمت كلبًا أو قطة بسيارتك. ماذا يجب أن تفعل؟","o":["لا شيء، إذا هرب الحيوان","أن تبلّغ فقط إذا مات الحيوان","أن تتصل بشركة التأمين خلال 30 يومًا","أن تبلّغ المالك أو الشرطة في أسرع وقت ممكن"],"h1":"يجب أن يعرف أحد بأمر الحيوان بسرعة.","h2":"في New Hampshire، إذا صدمت كلبًا أو قطة، يجب أن تبلّغ المالك أو الشرطة في أسرع وقت ممكن.","p":"صحيح. أخبر المالك أو الشرطة في أسرع وقت ممكن."},"ref":{"doc":"NH","page":null}},{"id":"nh-044","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, you move or change your name. How soon must you tell the DMV in writing?","o":["Within 10 days","Within 30 days","Within 60 days","At your next license renewal"],"h1":"You have about one month.","h2":"In New Hampshire, you must tell the DMV in writing within 30 days after you change your name or address.","p":"Right. Within 30 days."},"es":{"q":"En New Hampshire, usted se muda o cambia de nombre. ¿En cuánto tiempo debe avisarle al DMV por escrito?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación de licencia"],"h1":"Tiene más o menos un mes.","h2":"En New Hampshire, debe avisarle al DMV por escrito en un plazo de 30 días después de cambiar de nombre o de dirección.","p":"Correcto. En 30 días."},"zh":{"q":"在 New Hampshire，你搬家或改名了。你必须在多久内书面通知 DMV？","o":["10 天内","30 天内","60 天内","下次更新驾照时"],"h1":"你大约有一个月时间。","h2":"在 New Hampshire，你改名或改地址后，必须在 30 天内书面通知 DMV。","p":"对。30 天内。"},"vi":{"q":"Ở New Hampshire, bạn chuyển nhà hoặc đổi tên. Bạn phải báo cho DMV bằng văn bản trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Vào lần gia hạn bằng lái tiếp theo"],"h1":"Bạn có khoảng một tháng.","h2":"Ở New Hampshire, bạn phải báo cho DMV bằng văn bản trong vòng 30 ngày sau khi đổi tên hoặc địa chỉ.","p":"Đúng. Trong vòng 30 ngày."},"tl":{"q":"Sa New Hampshire, lumipat ka ng tirahan o nagpalit ng pangalan. Gaano kabilis mo dapat sabihan nang nakasulat ang DMV?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa susunod mong pag-renew ng lisensya"],"h1":"Mga isang buwan ang mayroon ka.","h2":"Sa New Hampshire, kailangan mong sabihan nang nakasulat ang DMV sa loob ng 30 araw matapos mong palitan ang pangalan o address mo.","p":"Tama. Sa loob ng 30 araw."},"ar":{"q":"في New Hampshire، انتقلت إلى عنوان جديد أو غيّرت اسمك. خلال كم من الوقت يجب أن تُبلغ DMV كتابيًا؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عند تجديد الرخصة القادم"],"h1":"لديك نحو شهر واحد.","h2":"في New Hampshire، يجب أن تُبلغ DMV كتابيًا خلال 30 يومًا بعد تغيير اسمك أو عنوانك.","p":"صحيح. خلال 30 يومًا."},"ref":{"doc":"NH","page":null}},{"id":"nh-045","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, when does a regular adult driver's license expire?","o":["On your fifth birthday after the license was issued","Exactly 4 years after the issue date","On your eighth birthday after the license was issued","Every 2 years on January 1"],"h1":"It ends on a birthday, a few years after you got it.","h2":"In New Hampshire, a regular driver's license expires on your fifth birthday after it was issued.","p":"Right. It expires on your fifth birthday after issue."},"es":{"q":"En New Hampshire, ¿cuándo vence una licencia de conducir común para adultos?","o":["En su quinto cumpleaños después de que se emitió la licencia","Exactamente 4 años después de la fecha de emisión","En su octavo cumpleaños después de que se emitió la licencia","Cada 2 años el 1 de enero"],"h1":"Vence en un cumpleaños, unos años después de recibirla.","h2":"En New Hampshire, una licencia de conducir común vence en su quinto cumpleaños después de que se emitió.","p":"Correcto. Vence en su quinto cumpleaños después de emitida."},"zh":{"q":"在 New Hampshire，普通成人驾照什么时候过期？","o":["在发证后的第五个生日","正好在发证日期后 4 年","在发证后的第八个生日","每 2 年的 1 月 1 日"],"h1":"它在一个生日结束，是你拿到驾照几年以后。","h2":"在 New Hampshire，普通驾照在发证后的第五个生日过期。","p":"对。在发证后的第五个生日过期。"},"vi":{"q":"Ở New Hampshire, bằng lái thường của người lớn hết hạn khi nào?","o":["Vào sinh nhật thứ năm sau khi bằng được cấp","Đúng 4 năm sau ngày cấp","Vào sinh nhật thứ tám sau khi bằng được cấp","Cứ 2 năm một lần vào ngày 1 tháng 1"],"h1":"Nó hết hạn vào một ngày sinh nhật, vài năm sau khi bạn nhận bằng.","h2":"Ở New Hampshire, bằng lái thường hết hạn vào sinh nhật thứ năm sau khi được cấp.","p":"Đúng. Nó hết hạn vào sinh nhật thứ năm sau khi cấp."},"tl":{"q":"Sa New Hampshire, kailan mag-e-expire ang karaniwang driver's license ng adult?","o":["Sa ikalimang kaarawan mo matapos ibigay ang lisensya","Eksaktong 4 na taon matapos ang petsa ng pagbibigay","Sa ikawalong kaarawan mo matapos ibigay ang lisensya","Tuwing 2 taon sa Enero 1"],"h1":"Nagtatapos ito sa isang kaarawan, ilang taon matapos mo itong makuha.","h2":"Sa New Hampshire, nag-e-expire ang karaniwang driver's license sa ikalimang kaarawan mo matapos itong ibigay.","p":"Tama. Nag-e-expire ito sa ikalimang kaarawan mo matapos ibigay."},"ar":{"q":"في New Hampshire، متى تنتهي رخصة القيادة العادية للبالغين؟","o":["في عيد ميلادك الخامس بعد إصدار الرخصة","بعد 4 سنوات بالضبط من تاريخ الإصدار","في عيد ميلادك الثامن بعد إصدار الرخصة","كل 2 سنة في 1 يناير"],"h1":"تنتهي في يوم عيد ميلاد، بعد بضع سنوات من حصولك عليها.","h2":"في New Hampshire، تنتهي رخصة القيادة العادية في عيد ميلادك الخامس بعد إصدارها.","p":"صحيح. تنتهي في عيد ميلادك الخامس بعد الإصدار."},"ref":{"doc":"NH","page":null}},{"id":"nh-046","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you move here from another state and become a resident. How soon must you get a New Hampshire driver's license?","o":["Within 10 days","Within 30 days","Within 60 days","Within 1 year"],"h1":"You have about two months.","h2":"In New Hampshire, a new resident must get a New Hampshire driver's license within 60 days of becoming a resident.","p":"Right. Within 60 days."},"es":{"q":"En New Hampshire, usted se muda aquí desde otro estado y pasa a ser residente. ¿En cuánto tiempo debe obtener una licencia de conducir de New Hampshire?","o":["En 10 días","En 30 días","En 60 días","En 1 año"],"h1":"Tiene más o menos dos meses.","h2":"En New Hampshire, un nuevo residente debe obtener una licencia de conducir de New Hampshire en un plazo de 60 días desde que pasa a ser residente.","p":"Correcto. En 60 días."},"zh":{"q":"在 New Hampshire，你从别的州搬来，成为这里的居民。你必须在多久内拿到 New Hampshire 驾照？","o":["10 天内","30 天内","60 天内","1 年内"],"h1":"你大约有两个月时间。","h2":"在 New Hampshire，新居民必须在成为居民后 60 天内拿到 New Hampshire 驾照。","p":"对。60 天内。"},"vi":{"q":"Ở New Hampshire, bạn chuyển đến từ một tiểu bang khác và trở thành cư dân. Bạn phải lấy bằng lái New Hampshire trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Trong vòng 1 năm"],"h1":"Bạn có khoảng hai tháng.","h2":"Ở New Hampshire, cư dân mới phải lấy bằng lái New Hampshire trong vòng 60 ngày sau khi trở thành cư dân.","p":"Đúng. Trong vòng 60 ngày."},"tl":{"q":"Sa New Hampshire, lumipat ka rito mula sa ibang estado at naging residente. Gaano kabilis ka dapat kumuha ng New Hampshire driver's license?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Sa loob ng 1 taon"],"h1":"Mga dalawang buwan ang mayroon ka.","h2":"Sa New Hampshire, ang bagong residente ay dapat kumuha ng New Hampshire driver's license sa loob ng 60 araw mula nang maging residente.","p":"Tama. Sa loob ng 60 araw."},"ar":{"q":"في New Hampshire، انتقلت إليها من ولاية أخرى وأصبحت مقيمًا. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من New Hampshire؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","خلال 1 سنة"],"h1":"لديك نحو شهرين.","h2":"في New Hampshire، يجب على المقيم الجديد أن يحصل على رخصة قيادة من New Hampshire خلال 60 يومًا من أن يصبح مقيمًا.","p":"صحيح. خلال 60 يومًا."},"ref":{"doc":"NH","page":null}},{"id":"nh-047","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you leave your car parked on a hill with no one in it. What must you do?","o":["Stop the engine and leave the key in, with the wheels pointed straight","Leave the engine running, set the brake and lock the doors","Stop the engine, take the key, and leave the car in neutral","Stop the engine, take the key, set the brake and turn the front wheels to the curb or side of the road"],"h1":"The car must not be able to start or roll away.","h2":"In New Hampshire, before leaving a car on a hill, you must stop the engine, take the key, set the brake and turn the front wheels to the curb or side of the road.","p":"Right. Engine off, key out, brake set, wheels to the curb."},"es":{"q":"En New Hampshire, usted deja su carro estacionado en una pendiente sin nadie adentro. ¿Qué debe hacer?","o":["Apagar el motor y dejar la llave puesta, con las ruedas derechas","Dejar el motor encendido, poner el freno y cerrar las puertas con llave","Apagar el motor, sacar la llave y dejar el carro en neutro","Apagar el motor, sacar la llave, poner el freno y girar las ruedas delanteras hacia la acera o el lado de la vía"],"h1":"El carro no debe poder arrancar ni rodar.","h2":"En New Hampshire, antes de dejar un carro en una pendiente, debe apagar el motor, sacar la llave, poner el freno y girar las ruedas delanteras hacia la acera o el lado de la vía.","p":"Correcto. Motor apagado, llave afuera, freno puesto y ruedas hacia la acera."},"zh":{"q":"在 New Hampshire，你把车停在坡上，车里没有人。你必须怎么做？","o":["关掉引擎，把钥匙留在车里，车轮朝正前方","让引擎开着，拉好刹车，锁上车门","关掉引擎，拿走钥匙，挂空挡","关掉引擎，拿走钥匙，拉好刹车，把前轮转向路缘或路边"],"h1":"车必须不能被发动，也不能滑走。","h2":"在 New Hampshire，把车留在坡上之前，你必须关掉引擎、拿走钥匙、拉好刹车，并把前轮转向路缘或路边。","p":"对。关引擎，拿钥匙，拉刹车，车轮转向路缘。"},"vi":{"q":"Ở New Hampshire, bạn để xe đỗ trên dốc và không có ai trong xe. Bạn phải làm gì?","o":["Tắt máy và để chìa khóa trong xe, bánh xe để thẳng","Để máy chạy, kéo phanh và khóa cửa","Tắt máy, lấy chìa khóa, và để xe ở số mo","Tắt máy, lấy chìa khóa, kéo phanh và quay bánh trước về phía lề đường hoặc mép đường"],"h1":"Xe phải không thể khởi động hoặc trôi đi.","h2":"Ở New Hampshire, trước khi để xe trên dốc, bạn phải tắt máy, lấy chìa khóa, kéo phanh và quay bánh trước về phía lề đường hoặc mép đường.","p":"Đúng. Tắt máy, lấy chìa khóa, kéo phanh, quay bánh về phía lề."},"tl":{"q":"Sa New Hampshire, iiwan mong nakaparada ang kotse mo sa isang burol nang walang tao sa loob. Ano ang dapat mong gawin?","o":["Patayin ang makina at iwan ang susi, nakatuwid ang mga gulong","Iwanang umaandar ang makina, i-set ang preno at i-lock ang mga pinto","Patayin ang makina, kunin ang susi, at iwan ang kotse sa neutral","Patayin ang makina, kunin ang susi, i-set ang preno at ibaling ang mga gulong sa harap papunta sa curb o gilid ng kalsada"],"h1":"Hindi dapat mapaandar o gumulong palayo ang kotse.","h2":"Sa New Hampshire, bago iwan ang kotse sa burol, kailangan mong patayin ang makina, kunin ang susi, i-set ang preno at ibaling ang mga gulong sa harap papunta sa curb o gilid ng kalsada.","p":"Tama. Patay ang makina, kuha ang susi, naka-set ang preno, nakabaling ang gulong sa curb."},"ar":{"q":"في New Hampshire، تترك سيارتك متوقفة على منحدر وليس فيها أحد. ماذا يجب أن تفعل؟","o":["أن تطفئ المحرك وتترك المفتاح فيها، والعجلات مستقيمة","أن تترك المحرك يعمل، وتشد الفرامل، وتقفل الأبواب","أن تطفئ المحرك، وتأخذ المفتاح، وتترك السيارة على وضع neutral","أن تطفئ المحرك، وتأخذ المفتاح، وتشد الفرامل، وتدير العجلات الأمامية نحو الرصيف أو جانب الطريق"],"h1":"يجب ألّا يكون ممكنًا تشغيل السيارة أو أن تتدحرج.","h2":"في New Hampshire، قبل أن تترك سيارة على منحدر، يجب أن تطفئ المحرك، وتأخذ المفتاح، وتشد الفرامل، وتدير العجلات الأمامية نحو الرصيف أو جانب الطريق.","p":"صحيح. المحرك مطفأ، والمفتاح معك، والفرامل مشدودة، والعجلات نحو الرصيف."},"ref":{"doc":"NH","page":null}},{"id":"nh-048","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, you are driving with a capped bottle of wine that is partly empty. Where must it be?","o":["Under the driver's seat","In the trunk","In the glove box","On the back seat, as long as it is capped"],"h1":"It must be out of the area where people sit.","h2":"In New Hampshire, a capped, partly full container of alcohol must ride in the trunk, or in the place hardest for the driver to reach if there is no trunk.","p":"Right. It goes in the trunk."},"es":{"q":"En New Hampshire, usted maneja con una botella de vino tapada que está medio vacía. ¿Dónde debe ir?","o":["Debajo del asiento del conductor","En el maletero (cajuela)","En la guantera","En el asiento de atrás, si está tapada"],"h1":"Debe estar fuera del área donde van las personas.","h2":"En New Hampshire, un envase de alcohol tapado y parcialmente lleno debe ir en el maletero, o en el lugar más difícil de alcanzar para el conductor si no hay maletero.","p":"Correcto. Va en el maletero."},"zh":{"q":"在 New Hampshire，你开车时带着一瓶盖好盖子、但已经喝了一部分的葡萄酒。它必须放在哪里？","o":["在司机座位下面","在后备箱里","在手套箱里","在后座上，只要盖着盖子"],"h1":"它必须放在人坐的地方以外。","h2":"在 New Hampshire，盖好盖子、没有装满的酒精容器必须放在后备箱里；如果没有后备箱，就放在司机最难拿到的地方。","p":"对。放在后备箱里。"},"vi":{"q":"Ở New Hampshire, bạn đang lái xe với một chai rượu vang đã đậy nắp nhưng đã uống bớt một phần. Nó phải ở đâu?","o":["Dưới ghế người lái","Trong cốp xe","Trong hộc đựng đồ","Trên ghế sau, miễn là có đậy nắp"],"h1":"Nó phải ở ngoài khu vực mọi người ngồi.","h2":"Ở New Hampshire, một chai rượu đã đậy nắp và không còn đầy phải để trong cốp xe, hoặc ở chỗ người lái khó với tới nhất nếu xe không có cốp.","p":"Đúng. Nó để trong cốp xe."},"tl":{"q":"Sa New Hampshire, nagmamaneho ka na may dalang nakatakip na bote ng wine na may bawas na. Saan ito dapat nakalagay?","o":["Sa ilalim ng upuan ng driver","Sa trunk","Sa glove box","Sa upuan sa likod, basta nakatakip"],"h1":"Dapat nasa labas ito ng lugar kung saan nakaupo ang mga tao.","h2":"Sa New Hampshire, ang nakatakip na lalagyan ng alak na may bawas na ay dapat nasa trunk, o sa lugar na pinakamahirap abutin ng driver kung walang trunk.","p":"Tama. Sa trunk ito nakalagay."},"ar":{"q":"في New Hampshire، تقود ومعك زجاجة نبيذ مغلقة بغطائها لكنها ليست ممتلئة. أين يجب أن تكون؟","o":["تحت مقعد السائق","في صندوق السيارة الخلفي","في درج القفازات","على المقعد الخلفي، ما دامت مغلقة"],"h1":"يجب أن تكون خارج المكان الذي يجلس فيه الناس.","h2":"في New Hampshire، يجب أن تكون زجاجة الكحول المغلقة وغير الممتلئة في صندوق السيارة الخلفي، أو في المكان الأصعب على السائق أن يصل إليه إذا لم يكن هناك صندوق.","p":"صحيح. توضع في صندوق السيارة الخلفي."},"ref":{"doc":"NH","page":null}},{"id":"nh-049","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, what is the smallest fine for a first conviction for impaired driving (DWI)?","o":["$100","$250","$500","$5,000"],"h1":"It is several hundred dollars.","h2":"In New Hampshire, a first DWI conviction brings a fine of at least $500.","p":"Right. The fine is at least $500."},"es":{"q":"En New Hampshire, ¿cuál es la multa mínima por una primera condena por manejar bajo los efectos del alcohol o drogas (DWI)?","o":["$100","$250","$500","$5,000"],"h1":"Son varios cientos de dólares.","h2":"En New Hampshire, una primera condena por DWI trae una multa de al menos $500.","p":"Correcto. La multa es de al menos $500."},"zh":{"q":"在 New Hampshire，第一次因酒驾或药驾（DWI）被定罪，最低罚款是多少？","o":["$100","$250","$500","$5,000"],"h1":"是几百美元。","h2":"在 New Hampshire，第一次 DWI 定罪的罚款至少是 $500。","p":"对。罚款至少 $500。"},"vi":{"q":"Ở New Hampshire, tiền phạt thấp nhất cho lần bị kết tội đầu tiên về lái xe khi say (DWI) là bao nhiêu?","o":["$100","$250","$500","$5,000"],"h1":"Đó là vài trăm đô la.","h2":"Ở New Hampshire, lần bị kết tội DWI đầu tiên có tiền phạt ít nhất là $500.","p":"Đúng. Tiền phạt ít nhất là $500."},"tl":{"q":"Sa New Hampshire, ano ang pinakamaliit na multa sa unang conviction para sa impaired driving (DWI)?","o":["$100","$250","$500","$5,000"],"h1":"Ilang daang dolyar ito.","h2":"Sa New Hampshire, ang unang DWI conviction ay may multang hindi bababa sa $500.","p":"Tama. Hindi bababa sa $500 ang multa."},"ar":{"q":"في New Hampshire، ما أقل غرامة لأول إدانة بالقيادة تحت التأثير (DWI)؟","o":["$100","$250","$500","$5,000"],"h1":"هي بضع مئات من الدولارات.","h2":"في New Hampshire، أول إدانة بـ DWI تأتي بغرامة لا تقل عن $500.","p":"صحيح. الغرامة $500 على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-050","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, at what blood alcohol level is driving aggravated DWI, even with no other factor?","o":["0.16 or more","0.10 or more","0.12 or more","0.20 or more"],"h1":"It is twice the usual adult limit of 0.08.","h2":"In New Hampshire, driving with a blood alcohol level of 0.16 or more is aggravated DWI on its own.","p":"Right. 0.16 or more is aggravated DWI."},"es":{"q":"En New Hampshire, ¿con qué nivel de alcohol en la sangre manejar es DWI agravado, aunque no haya otro factor?","o":["0.16 o más","0.10 o más","0.12 o más","0.20 o más"],"h1":"Es el doble del límite habitual para adultos, que es 0.08.","h2":"En New Hampshire, manejar con un nivel de alcohol en la sangre de 0.16 o más es DWI agravado por sí solo.","p":"Correcto. 0.16 o más es DWI agravado."},"zh":{"q":"在 New Hampshire，血液酒精浓度达到多少时，即使没有其他因素，开车也算加重 DWI（aggravated DWI）？","o":["0.16 或以上","0.10 或以上","0.12 或以上","0.20 或以上"],"h1":"它是成人通常上限 0.08 的两倍。","h2":"在 New Hampshire，血液酒精浓度在 0.16 或以上时开车，本身就是加重 DWI。","p":"对。0.16 或以上是加重 DWI。"},"vi":{"q":"Ở New Hampshire, nồng độ cồn trong máu ở mức nào thì lái xe là DWI nghiêm trọng (aggravated DWI), dù không có yếu tố nào khác?","o":["0.16 trở lên","0.10 trở lên","0.12 trở lên","0.20 trở lên"],"h1":"Nó gấp đôi giới hạn thường lệ cho người lớn là 0.08.","h2":"Ở New Hampshire, lái xe với nồng độ cồn trong máu từ 0.16 trở lên tự nó đã là DWI nghiêm trọng.","p":"Đúng. 0.16 trở lên là DWI nghiêm trọng."},"tl":{"q":"Sa New Hampshire, sa anong blood alcohol level ang pagmamaneho ay aggravated DWI, kahit walang ibang dahilan?","o":["0.16 o higit pa","0.10 o higit pa","0.12 o higit pa","0.20 o higit pa"],"h1":"Doble ito ng karaniwang limitasyon para sa adult na 0.08.","h2":"Sa New Hampshire, ang pagmamaneho na may blood alcohol level na 0.16 o higit pa ay aggravated DWI na mismo.","p":"Tama. Ang 0.16 o higit pa ay aggravated DWI."},"ar":{"q":"في New Hampshire، عند أي نسبة كحول في الدم تُعد القيادة DWI مشددة (aggravated DWI)، حتى بدون أي عامل آخر؟","o":["0.16 أو أكثر","0.10 أو أكثر","0.12 أو أكثر","0.20 أو أكثر"],"h1":"هي ضعف الحد المعتاد للبالغين وهو 0.08.","h2":"في New Hampshire، القيادة بنسبة كحول في الدم 0.16 أو أكثر هي DWI مشددة بحد ذاتها.","p":"صحيح. 0.16 أو أكثر هي DWI مشددة."},"ref":{"doc":"NH","page":null}},{"id":"nh-051","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, who must wear a helmet on a motorcycle by law?","o":["Every rider and passenger","Only the driver","Only riders over 65","Riders and passengers under 18"],"h1":"The law is about age, not about who steers.","h2":"In New Hampshire, the law requires a helmet for motorcycle riders and passengers under 18.","p":"Right. The helmet law covers anyone under 18."},"es":{"q":"En New Hampshire, ¿quién debe usar casco en una motocicleta por ley?","o":["Todos los motociclistas y pasajeros","Solo quien maneja","Solo los motociclistas mayores de 65 años","Los motociclistas y pasajeros menores de 18 años"],"h1":"La ley se basa en la edad, no en quién maneja.","h2":"En New Hampshire, la ley exige casco a los motociclistas y pasajeros menores de 18 años.","p":"Correcto. La ley del casco aplica a menores de 18 años."},"zh":{"q":"在 New Hampshire，法律要求谁骑摩托车时必须戴头盔？","o":["每一位骑手和乘客","只有驾驶的人","只有 65 岁以上的骑手","18 岁以下的骑手和乘客"],"h1":"这条法律看的是年龄，不是谁在驾驶。","h2":"在 New Hampshire，法律要求 18 岁以下的摩托车骑手和乘客戴头盔。","p":"对。头盔法适用于所有 18 岁以下的人。"},"vi":{"q":"Ở New Hampshire, theo luật ai phải đội mũ bảo hiểm khi đi xe máy?","o":["Mọi người lái và người ngồi sau","Chỉ người lái","Chỉ người lái trên 65 tuổi","Người lái và người ngồi sau dưới 18 tuổi"],"h1":"Luật này dựa vào tuổi, không phải ai cầm lái.","h2":"Ở New Hampshire, luật yêu cầu người lái và người ngồi sau xe máy dưới 18 tuổi phải đội mũ bảo hiểm.","p":"Đúng. Luật mũ bảo hiểm áp dụng cho mọi người dưới 18 tuổi."},"tl":{"q":"Sa New Hampshire, sino ang kailangang magsuot ng helmet sa motorsiklo ayon sa batas?","o":["Bawat rider at pasahero","Ang driver lang","Mga rider na lampas 65 lang","Mga rider at pasaherong wala pang 18"],"h1":"Tungkol sa edad ang batas, hindi kung sino ang nagmamaneho.","h2":"Sa New Hampshire, hinihingi ng batas ang helmet para sa mga rider at pasahero ng motorsiklo na wala pang 18.","p":"Tama. Saklaw ng helmet law ang sinumang wala pang 18."},"ar":{"q":"في New Hampshire، من يجب أن يلبس خوذة على الدراجة النارية حسب القانون؟","o":["كل سائق وراكب","السائق فقط","السائقون فوق 65 سنة فقط","السائقون والركاب تحت 18 سنة"],"h1":"القانون يتعلق بالعمر، لا بمن يقود.","h2":"في New Hampshire، يطلب القانون خوذة لسائقي الدراجات النارية وركابها تحت 18 سنة.","p":"صحيح. قانون الخوذة يشمل كل من عمره تحت 18 سنة."},"ref":{"doc":"NH","page":null}},{"id":"nh-052","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the smallest tire tread depth allowed by law on a car?","o":["1/32 of an inch","2/32 of an inch","4/32 of an inch","6/32 of an inch"],"h1":"It is very thin, but not the thinnest choice here.","h2":"In New Hampshire, a car's tires must have a tread depth of at least 2/32 of an inch.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En New Hampshire, ¿cuál es la profundidad mínima de la banda de rodadura de las llantas que permite la ley en un carro?","o":["1/32 de pulgada","2/32 de pulgada","4/32 de pulgada","6/32 de pulgada"],"h1":"Es muy poca, pero no la menor de estas opciones.","h2":"En New Hampshire, las llantas de un carro deben tener una banda de rodadura de al menos 2/32 de pulgada.","p":"Correcto. Al menos 2/32 de pulgada."},"zh":{"q":"在 New Hampshire，法律允许的汽车轮胎最小花纹深度是多少？","o":["1/32 英寸","2/32 英寸","4/32 英寸","6/32 英寸"],"h1":"它很薄，但不是这里最薄的选项。","h2":"在 New Hampshire，汽车轮胎的花纹深度必须至少是 2/32 英寸。","p":"对。至少 2/32 英寸。"},"vi":{"q":"Ở New Hampshire, độ sâu gai lốp nhỏ nhất mà luật cho phép trên xe hơi là bao nhiêu?","o":["1/32 inch","2/32 inch","4/32 inch","6/32 inch"],"h1":"Nó rất mỏng, nhưng không phải lựa chọn mỏng nhất ở đây.","h2":"Ở New Hampshire, lốp xe hơi phải có độ sâu gai ít nhất là 2/32 inch.","p":"Đúng. Ít nhất 2/32 inch."},"tl":{"q":"Sa New Hampshire, ano ang pinakamababaw na lalim ng tread ng gulong na pinapayagan ng batas sa kotse?","o":["1/32 ng isang inch","2/32 ng isang inch","4/32 ng isang inch","6/32 ng isang inch"],"h1":"Napakanipis nito, pero hindi ito ang pinakamanipis na pagpipilian dito.","h2":"Sa New Hampshire, ang mga gulong ng kotse ay dapat may tread depth na hindi bababa sa 2/32 ng isang inch.","p":"Tama. Hindi bababa sa 2/32 ng isang inch."},"ar":{"q":"في New Hampshire، ما أقل عمق لنقشة الإطار يسمح به القانون في السيارة؟","o":["1/32 من inch","2/32 من inch","4/32 من inch","6/32 من inch"],"h1":"هو رقيق جدًا، لكنه ليس أرقّ اختيار هنا.","h2":"في New Hampshire، يجب أن يكون عمق نقشة إطارات السيارة 2/32 من inch على الأقل.","p":"صحيح. 2/32 من inch على الأقل."},"ref":{"doc":"NH","page":null}},{"id":"nh-053","scope":"NH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Hampshire, the car ahead of you in your lane has stopped at a crosswalk to let a person cross. What must you do?","o":["Pass it carefully on the left","Honk and pass it on the right","Do not pass it; stay behind it","Pass it once the person reaches the middle of the road"],"h1":"The other driver may be stopped for someone you cannot see.","h2":"In New Hampshire, you may not pass a car that has stopped at a crosswalk to let a person cross.","p":"Right. Never pass a car stopped for a person crossing."},"es":{"q":"En New Hampshire, el carro que va delante en su carril se detuvo en un cruce peatonal para dejar pasar a una persona. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Tocar la bocina y rebasarlo por la derecha","No rebasarlo; quedarse detrás","Rebasarlo cuando la persona llegue a la mitad de la calle"],"h1":"El otro conductor puede estar detenido por alguien que usted no ve.","h2":"En New Hampshire, no puede rebasar a un carro que se detuvo en un cruce peatonal para dejar pasar a una persona.","p":"Correcto. Nunca rebase a un carro detenido por un peatón."},"zh":{"q":"在 New Hampshire，你车道上前面的车在人行横道前停下，让一个人过马路。你必须怎么做？","o":["小心地从左边超过它","按喇叭，从右边超过它","不要超过它；待在它后面","等那个人走到路中间后再超过它"],"h1":"另一位司机可能是为你看不见的人停车。","h2":"在 New Hampshire，你不能超过在人行横道前停下让人过马路的车。","p":"对。绝不能超过为过马路的人停下的车。"},"vi":{"q":"Ở New Hampshire, xe phía trước bạn trong cùng làn đã dừng ở lối qua đường để một người đi qua. Bạn phải làm gì?","o":["Cẩn thận vượt nó bên trái","Bấm còi và vượt nó bên phải","Không vượt nó; ở phía sau nó","Vượt nó khi người đó đi đến giữa đường"],"h1":"Người lái kia có thể đang dừng cho một người mà bạn không nhìn thấy.","h2":"Ở New Hampshire, bạn không được vượt một chiếc xe đã dừng ở lối qua đường để một người đi qua.","p":"Đúng. Không bao giờ vượt xe đang dừng cho người qua đường."},"tl":{"q":"Sa New Hampshire, huminto sa crosswalk ang kotse sa unahan mo sa iyong lane para patawirin ang isang tao. Ano ang dapat mong gawin?","o":["Lampasan ito nang maingat sa kaliwa","Bumusina at lampasan ito sa kanan","Huwag itong lampasan; manatili sa likod nito","Lampasan ito kapag nasa gitna na ng kalsada ang tao"],"h1":"Maaaring nakahinto ang ibang driver para sa taong hindi mo nakikita.","h2":"Sa New Hampshire, hindi ka puwedeng lumampas sa kotseng huminto sa crosswalk para patawirin ang isang tao.","p":"Tama. Huwag kailanman lampasan ang kotseng nakahinto para sa taong tumatawid."},"ar":{"q":"في New Hampshire، السيارة التي أمامك في حارتك توقفت عند ممر المشاة لتترك شخصًا يعبر. ماذا يجب أن تفعل؟","o":["أن تتجاوزها بحذر من اليسار","أن تستخدم البوق وتتجاوزها من اليمين","ألّا تتجاوزها؛ ابقَ خلفها","أن تتجاوزها عندما يصل الشخص إلى منتصف الطريق"],"h1":"قد يكون السائق الآخر متوقفًا لشخص لا تراه.","h2":"في New Hampshire، يجب ألّا تتجاوز سيارة توقفت عند ممر المشاة لتترك شخصًا يعبر.","p":"صحيح. لا تتجاوز أبدًا سيارة متوقفة لشخص يعبر."},"ref":{"doc":"NH","page":null}},{"id":"nh-054","scope":"NH","cat":"signals","sign":null,"c":2,"en":{"q":"In New Hampshire, you plan to turn right at the next corner. For how long must your turn signal be on before the turn?","o":["Only for the last 25 feet","At least the last 50 feet","At least the last 100 feet","Only once you start turning"],"h1":"It is about six car lengths.","h2":"In New Hampshire, you must signal without a break for at least the last 100 feet before you turn.","p":"Right. Signal for at least the last 100 feet."},"es":{"q":"En New Hampshire, usted piensa girar a la derecha en la próxima esquina. ¿Durante cuánto tiempo debe estar encendida su direccional antes del giro?","o":["Solo durante los últimos 25 pies","Al menos los últimos 50 pies","Al menos los últimos 100 pies","Solo cuando ya empieza a girar"],"h1":"Son unos seis largos de carro.","h2":"En New Hampshire, debe señalizar sin interrupción durante al menos los últimos 100 pies antes de girar.","p":"Correcto. Señalice durante al menos los últimos 100 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-055","scope":"NH","cat":"signals","sign":null,"c":3,"en":{"q":"In New Hampshire, a driver behind you wants to pass. May you flash your left turn signal to tell the driver it is safe to pass?","o":["Yes, it is a polite way to help","Yes, but only on a highway","Yes, if you also wave your hand","No, turn signals may not be used as a \"pass me\" signal"],"h1":"Turn signals are only for turning, changing lanes, or pulling out from a parked spot.","h2":"In New Hampshire, you may not use your turn signals as a courtesy or \"go ahead and pass\" signal to drivers behind you.","p":"Right. Turn signals are not a \"pass me\" signal."},"es":{"q":"En New Hampshire, un conductor detrás de usted quiere rebasar. ¿Puede usted encender la direccional izquierda para decirle que es seguro rebasar?","o":["Sí, es una manera amable de ayudar","Sí, pero solo en una autopista","Sí, si además hace una seña con la mano","No, las direccionales no se pueden usar como señal de \"rebáseme\""],"h1":"Las direccionales son solo para girar, cambiar de carril o salir de un estacionamiento.","h2":"En New Hampshire, no puede usar las direccionales como cortesía ni como señal de \"adelante, rebase\" para los conductores que vienen detrás.","p":"Correcto. Las direccionales no son una señal de \"rebáseme\"."},"ref":{"doc":"NH","page":null}},{"id":"nh-056","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a railroad crossing has a STOP sign. Where must you stop?","o":["Right on the first rail","Within 50 feet of the nearest rail, but not closer than 15 feet","At least 100 feet before the tracks","Anywhere, as long as you can see the tracks"],"h1":"Not too close to the rail, and not too far away either.","h2":"In New Hampshire, at a railroad crossing with a STOP sign, you must stop within 50 feet of the nearest rail but not closer than 15 feet.","p":"Right. Between 15 and 50 feet from the nearest rail."},"es":{"q":"En New Hampshire, un cruce de ferrocarril tiene una señal de ALTO. ¿Dónde debe detenerse?","o":["Justo encima del primer riel","A menos de 50 pies del riel más cercano, pero no a menos de 15 pies","Al menos 100 pies antes de las vías","En cualquier lugar, siempre que pueda ver las vías"],"h1":"Ni demasiado cerca del riel ni demasiado lejos.","h2":"En New Hampshire, en un cruce de ferrocarril con señal de ALTO, debe detenerse a menos de 50 pies del riel más cercano, pero no a menos de 15 pies.","p":"Correcto. Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"NH","page":null}},{"id":"nh-057","scope":"NH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Hampshire, which vehicle must stop at every railroad crossing, even with no STOP sign, unless a police officer or traffic signal tells it to go?","o":["Any pickup truck","Any car pulling a small trailer","A school bus carrying school children","A motorcycle with a passenger"],"h1":"Think of a vehicle full of young passengers.","h2":"In New Hampshire, a school bus carrying school children must stop at every railroad crossing, as must vehicles carrying passengers for hire or explosives.","p":"Right. A school bus with children must always stop."},"es":{"q":"En New Hampshire, ¿qué vehículo debe detenerse en todo cruce de ferrocarril, aunque no haya señal de ALTO, a menos que un policía o un semáforo le indique seguir?","o":["Cualquier camioneta pickup","Cualquier carro que jala un remolque pequeño","Un autobús escolar que lleva niños","Una motocicleta con pasajero"],"h1":"Piense en un vehículo lleno de pasajeros jóvenes.","h2":"En New Hampshire, un autobús escolar que lleva niños debe detenerse en todo cruce de ferrocarril, igual que los vehículos que llevan pasajeros por pago o explosivos.","p":"Correcto. Un autobús escolar con niños siempre debe detenerse."},"ref":{"doc":"NH","page":null}},{"id":"nh-058","scope":"NH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Hampshire, firefighters have laid a hose across the street to fight a fire. When may you drive over the hose?","o":["When you drive slowly","When the hose looks empty","When no firefighter is near it","Only when the fire official in charge says you may"],"h1":"The hose belongs to the fire department.","h2":"In New Hampshire, you may not drive over a fire hose laid across the street unless the fire department official in charge allows it.","p":"Right. Only with the fire official's permission."},"es":{"q":"En New Hampshire, los bomberos pusieron una manguera a través de la calle para apagar un incendio. ¿Cuándo puede pasar con el carro por encima de la manguera?","o":["Cuando maneja despacio","Cuando la manguera parece vacía","Cuando no hay bomberos cerca","Solo cuando el jefe de bomberos a cargo se lo permite"],"h1":"La manguera es del departamento de bomberos.","h2":"En New Hampshire, no puede pasar por encima de una manguera de bomberos tendida en la calle a menos que el jefe de bomberos a cargo lo permita.","p":"Correcto. Solo con permiso del jefe de bomberos."},"ref":{"doc":"NH","page":null}},{"id":"nh-059","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, you missed your exit on a controlled-access highway, such as an interstate. May you back up on the shoulder to reach it?","o":["No, backing on the shoulder or road of such a highway is not allowed","Yes, if your hazard lights are on","Yes, if no cars are coming","Yes, but only for a short distance"],"h1":"Go on to the next exit instead.","h2":"In New Hampshire, you may not back up on the shoulder or roadway of a controlled-access highway; go on to the next exit.","p":"Right. Never back up on that highway; take the next exit."},"es":{"q":"En New Hampshire, usted se pasó de su salida en una autopista de acceso controlado, como una interestatal. ¿Puede retroceder por el acotamiento para llegar a ella?","o":["No, no se permite retroceder en el acotamiento ni en la vía de esa autopista","Sí, si tiene las luces intermitentes encendidas","Sí, si no vienen carros","Sí, pero solo una distancia corta"],"h1":"Mejor siga hasta la próxima salida.","h2":"En New Hampshire, no puede retroceder en el acotamiento ni en la vía de una autopista de acceso controlado; siga hasta la próxima salida.","p":"Correcto. Nunca retroceda en esa autopista; tome la próxima salida."},"ref":{"doc":"NH","page":null}},{"id":"nh-060","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, you are parked on a street and want to open your door on the traffic side. What does the law say?","o":["You may open it any time; drivers must go around you","Open it only when it is safe and does not get in the way of traffic, and close it as soon as you can","Open it only if your hazard lights are on","You may never open a door on the traffic side"],"h1":"The door must not swing into moving traffic, and must not stay open long.","h2":"In New Hampshire, you may open a door on the traffic side only when it is safe and does not get in the way of traffic, and you may not leave it open longer than needed.","p":"Right. Open it only when safe, and close it quickly."},"es":{"q":"En New Hampshire, usted está estacionado en una calle y quiere abrir la puerta del lado del tráfico. ¿Qué dice la ley?","o":["Puede abrirla cuando quiera; los conductores deben rodearlo","Ábrala solo cuando sea seguro y no estorbe al tráfico, y ciérrela lo antes posible","Ábrala solo si tiene las luces intermitentes encendidas","Nunca puede abrir una puerta del lado del tráfico"],"h1":"La puerta no debe abrirse hacia el tráfico en movimiento ni quedarse abierta mucho tiempo.","h2":"En New Hampshire, puede abrir una puerta del lado del tráfico solo cuando sea seguro y no estorbe al tráfico, y no puede dejarla abierta más de lo necesario.","p":"Correcto. Ábrala solo cuando sea seguro y ciérrela pronto."},"ref":{"doc":"NH","page":null}},{"id":"nh-061","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, what is the fine for following another vehicle too closely?","o":["$25","$50","$100","$1,000"],"h1":"It is a three-digit number.","h2":"In New Hampshire, the fine for following another vehicle too closely is $100.","p":"Right. The fine is $100."},"es":{"q":"En New Hampshire, ¿cuál es la multa por seguir demasiado cerca a otro vehículo?","o":["$25","$50","$100","$1,000"],"h1":"Es un número de tres cifras.","h2":"En New Hampshire, la multa por seguir demasiado cerca a otro vehículo es de $100.","p":"Correcto. La multa es de $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-062","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, what is the fine for a first offense of negligent driving, driving in a way that puts people or property in danger?","o":["$25 to $50","$50 to $100","$1,000 to $2,000","$250 to $500"],"h1":"The smallest fine is a few hundred dollars.","h2":"In New Hampshire, a first offense of negligent driving brings a fine of $250 to $500.","p":"Right. $250 to $500."},"es":{"q":"En New Hampshire, ¿cuál es la multa por una primera infracción de manejo negligente, es decir, manejar de una forma que pone en peligro a personas o bienes?","o":["De $25 a $50","De $50 a $100","De $1,000 a $2,000","De $250 a $500"],"h1":"La multa más baja es de unos cientos de dólares.","h2":"En New Hampshire, una primera infracción de manejo negligente tiene una multa de $250 a $500.","p":"Correcto. De $250 a $500."},"ref":{"doc":"NH","page":null}},{"id":"nh-063","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, a driver is convicted of reckless driving for the first time. For how long is the license revoked?","o":["60 days","7 days","1 year","It is not revoked"],"h1":"It is about two months.","h2":"In New Hampshire, a first conviction for reckless driving means the license is revoked for 60 days.","p":"Right. 60 days."},"es":{"q":"En New Hampshire, un conductor es condenado por primera vez por manejo temerario. ¿Por cuánto tiempo le revocan la licencia?","o":["60 días","7 días","1 año","No se la revocan"],"h1":"Son unos dos meses.","h2":"En New Hampshire, una primera condena por manejo temerario significa que la licencia se revoca por 60 días.","p":"Correcto. 60 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-064","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, a driver is caught going 100 mph or faster for the first time. For how long is the license revoked?","o":["30 days","90 days","5 years","It is not revoked; there is only a fine"],"h1":"It is about three months.","h2":"In New Hampshire, a first conviction for driving 100 mph or faster means the license is revoked for 90 days.","p":"Right. 90 days."},"es":{"q":"En New Hampshire, a un conductor lo detienen por primera vez a 100 mph o más. ¿Por cuánto tiempo le revocan la licencia?","o":["30 días","90 días","5 años","No se la revocan; solo hay multa"],"h1":"Son unos tres meses.","h2":"En New Hampshire, una primera condena por manejar a 100 mph o más significa que la licencia se revoca por 90 días.","p":"Correcto. 90 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-065","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, at night you leave your car parked partly on a road with no street lights. Which lights must be on?","o":["No lights","High beams","Parking lights","Only the inside dome light"],"h1":"These are small lights that show where a parked car is.","h2":"In New Hampshire, a car parked on a road at night must show its parking lights, unless street lights or other lights make it plainly visible.","p":"Right. Parking lights."},"es":{"q":"En New Hampshire, de noche usted deja su carro estacionado en parte sobre una calle sin alumbrado público. ¿Qué luces deben estar encendidas?","o":["Ninguna luz","Las luces altas","Las luces de estacionamiento","Solo la luz interior del techo"],"h1":"Son luces pequeñas que muestran dónde está un carro estacionado.","h2":"En New Hampshire, un carro estacionado en una calle de noche debe tener encendidas las luces de estacionamiento, a menos que el alumbrado u otras luces lo hagan claramente visible.","p":"Correcto. Las luces de estacionamiento."},"ref":{"doc":"NH","page":null}},{"id":"nh-066","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you are driving on a mountain road. A curve ahead blocks your view within 200 feet. What must you do?","o":["Flash your high beams","Drive in the middle of the road","Speed up to get through the curve","Keep right and sound your horn"],"h1":"Warn drivers you cannot see yet.","h2":"In New Hampshire, on a mountain road you must keep as far right as you reasonably can and sound your horn before a curve where your view is blocked within 200 feet.","p":"Right. Keep right and sound your horn."},"es":{"q":"En New Hampshire, usted maneja por un camino de montaña. Una curva adelante le tapa la vista a menos de 200 pies. ¿Qué debe hacer?","o":["Hacer cambio de luces altas","Manejar por el centro del camino","Acelerar para pasar rápido la curva","Mantenerse a la derecha y tocar la bocina"],"h1":"Avise a los conductores que todavía no puede ver.","h2":"En New Hampshire, en un camino de montaña debe mantenerse lo más a la derecha posible y tocar la bocina antes de una curva donde la vista está tapada a menos de 200 pies.","p":"Correcto. Manténgase a la derecha y toque la bocina."},"ref":{"doc":"NH","page":null}},{"id":"nh-067","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, you are passing in the lane for oncoming traffic. A car is coming toward you. You must be back in your lane before you come within what distance of it?","o":["200 feet","20 feet","50 feet","10 feet"],"h1":"It is about a dozen car lengths.","h2":"In New Hampshire, when you pass in the oncoming lane, you must return to your own lane before you come within 200 feet of an oncoming vehicle.","p":"Right. Before you are within 200 feet."},"es":{"q":"En New Hampshire, usted está rebasando por el carril del tráfico contrario. Viene un carro de frente. ¿Antes de qué distancia de ese carro debe volver a su carril?","o":["200 pies","20 pies","50 pies","10 pies"],"h1":"Son unos doce largos de carro.","h2":"En New Hampshire, cuando rebasa por el carril contrario, debe volver a su carril antes de llegar a 200 pies de un vehículo que viene de frente.","p":"Correcto. Antes de llegar a 200 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-068","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, on a two-way road, how close to an intersection or a railroad crossing may you drive on the left side of the road to pass, unless markings allow it?","o":["Up to 10 feet","Not within 100 feet","Not within 1,000 feet","Any distance, if no train or car is in sight"],"h1":"Stay out of the left side for the last stretch of about six car lengths.","h2":"In New Hampshire, you may not drive on the left side of the road within 100 feet of an intersection or a railroad crossing, unless signs or markings allow it.","p":"Right. Not within 100 feet."},"es":{"q":"En New Hampshire, en un camino de doble sentido, ¿a qué distancia de una intersección o de un cruce de ferrocarril puede manejar por el lado izquierdo para rebasar, a menos que las marcas lo permitan?","o":["Hasta 10 pies","No a menos de 100 pies","No a menos de 1,000 pies","A cualquier distancia, si no se ve un tren ni un carro"],"h1":"No use el lado izquierdo en el último tramo de unos seis largos de carro.","h2":"En New Hampshire, no puede manejar por el lado izquierdo del camino a menos de 100 pies de una intersección o de un cruce de ferrocarril, a menos que las señales o marcas lo permitan.","p":"Correcto. No a menos de 100 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-069","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, a driver behind you sounds the horn and starts to pass you on the left. What must you do?","o":["Speed up so the driver passes faster","Move to the left to block the pass","Give way to the right and do not speed up until you are passed","Stop in your lane right away"],"h1":"Make the pass easier, not harder.","h2":"In New Hampshire, when another vehicle passes you, you must give way to the right and not speed up until it has completely passed.","p":"Right. Give way to the right and do not speed up."},"es":{"q":"En New Hampshire, un conductor detrás de usted toca la bocina y empieza a rebasarlo por la izquierda. ¿Qué debe hacer?","o":["Acelerar para que lo rebase más rápido","Moverse a la izquierda para impedirlo","Hacerse a la derecha y no acelerar hasta que lo hayan rebasado","Detenerse en su carril de inmediato"],"h1":"Facilite el rebase, no lo complique.","h2":"En New Hampshire, cuando otro vehículo lo rebasa, usted debe hacerse a la derecha y no acelerar hasta que lo haya rebasado por completo.","p":"Correcto. Hágase a la derecha y no acelere."},"ref":{"doc":"NH","page":null}},{"id":"nh-070","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, the car ahead is waiting to turn left. You want to pass it on the right. Which is NOT allowed?","o":["Passing on the right when the car is turning left","Passing on the right when it is safe","Passing on the right on a road with room for two lines of cars","Passing on the right by driving onto the shoulder or off the road"],"h1":"Passing on the right must stay on the pavement.","h2":"In New Hampshire, you may pass on the right only when it is safe, and never by driving off the roadway, such as onto the shoulder.","p":"Right. Never pass on the right by driving off the road."},"es":{"q":"En New Hampshire, el carro de adelante espera para girar a la izquierda. Usted quiere rebasarlo por la derecha. ¿Qué NO está permitido?","o":["Rebasar por la derecha cuando el carro gira a la izquierda","Rebasar por la derecha cuando es seguro","Rebasar por la derecha en una vía con espacio para dos filas de carros","Rebasar por la derecha saliéndose al acotamiento o fuera del camino"],"h1":"El rebase por la derecha debe hacerse sobre el pavimento.","h2":"En New Hampshire, puede rebasar por la derecha solo cuando es seguro, y nunca saliéndose de la vía, por ejemplo al acotamiento.","p":"Correcto. Nunca rebase por la derecha saliéndose del camino."},"ref":{"doc":"NH","page":null}},{"id":"nh-071","scope":"NH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Hampshire, may you make a U-turn on a curve or near the top of a hill?","o":["Not if drivers coming from either direction cannot see you within 500 feet","Yes, any time you signal first","Yes, if you go fast","Only at night"],"h1":"Other drivers must be able to see you from far away.","h2":"In New Hampshire, you may not turn around on a curve or near the top of a hill where drivers coming from either direction cannot see you within 500 feet.","p":"Right. Not where you cannot be seen within 500 feet."},"es":{"q":"En New Hampshire, ¿puede dar una vuelta en U en una curva o cerca de la cima de una loma?","o":["No, si los conductores que vienen de cualquier dirección no pueden verlo a 500 pies","Sí, siempre que señalice antes","Sí, si lo hace rápido","Solo de noche"],"h1":"Los otros conductores deben poder verlo desde lejos.","h2":"En New Hampshire, no puede dar la vuelta en una curva ni cerca de la cima de una loma donde los conductores que vienen de cualquier dirección no puedan verlo a 500 pies.","p":"Correcto. No donde no lo vean a 500 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-072","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, you have a small crash in a travel lane. Your car can still be moved safely and no one is hurt. What should you do?","o":["Leave the car where it is until the police arrive","Move the car off the travel lanes to a safe spot","Drive home and report it later","Leave the car and walk to the nearest phone"],"h1":"Clear the road if you can do it without more harm.","h2":"In New Hampshire, if your car is in a crash on the travel lanes and it can be moved without more damage or injury, you must move it off the travel lanes.","p":"Right. Move it off the travel lanes."},"es":{"q":"En New Hampshire, usted tiene un choque leve en un carril de circulación. Su carro todavía se puede mover sin peligro y nadie está herido. ¿Qué debe hacer?","o":["Dejar el carro donde está hasta que llegue la policía","Sacar el carro de los carriles de circulación a un lugar seguro","Irse a casa y reportarlo más tarde","Dejar el carro y caminar al teléfono más cercano"],"h1":"Despeje la vía si puede hacerlo sin causar más daño.","h2":"En New Hampshire, si su carro choca en los carriles de circulación y se puede mover sin más daño ni lesiones, debe sacarlo de esos carriles.","p":"Correcto. Sáquelo de los carriles de circulación."},"ref":{"doc":"NH","page":null}},{"id":"nh-073","scope":"NH","cat":"signals","sign":null,"c":2,"en":{"q":"In New Hampshire, the light ahead is red. May you cut through a gas station lot on the corner to avoid it?","o":["Yes, if you drive slowly","Yes, if the lot is empty","No, that is against the law","Yes, if you are turning right"],"h1":"The law protects traffic signals from shortcuts.","h2":"In New Hampshire, it is against the law to cut across property that is not a road, such as a parking lot, to avoid a traffic signal or sign.","p":"Right. Cutting through to avoid a signal is not allowed."},"es":{"q":"En New Hampshire, el semáforo de adelante está en rojo. ¿Puede atravesar el terreno de una gasolinera en la esquina para evitarlo?","o":["Sí, si maneja despacio","Sí, si el terreno está vacío","No, eso va contra la ley","Sí, si va a girar a la derecha"],"h1":"La ley protege los semáforos de los atajos.","h2":"En New Hampshire, es ilegal atravesar un terreno que no es calle, como un estacionamiento, para evitar un semáforo o una señal.","p":"Correcto. No se permite atravesar para evitar un semáforo."},"ref":{"doc":"NH","page":null}},{"id":"nh-074","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, may a motorcycle ride between two lanes of slow or stopped cars?","o":["Yes, at any speed","Yes, if traffic is stopped","Yes, if the rider signals","No, riding between lanes or rows of cars is not allowed"],"h1":"Motorcycles get a full lane, like cars.","h2":"In New Hampshire, a motorcycle may not ride between lanes of traffic or between rows of cars.","p":"Right. No riding between lanes."},"es":{"q":"En New Hampshire, ¿puede una motocicleta circular entre dos carriles de carros lentos o detenidos?","o":["Sí, a cualquier velocidad","Sí, si el tráfico está detenido","Sí, si el motociclista señaliza","No, no se permite circular entre carriles ni entre filas de carros"],"h1":"Las motocicletas tienen derecho a un carril completo, como los carros.","h2":"En New Hampshire, una motocicleta no puede circular entre carriles de tráfico ni entre filas de carros.","p":"Correcto. No se circula entre carriles."},"ref":{"doc":"NH","page":null}},{"id":"nh-075","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, what is the largest number of motorcycles that may ride side by side in one lane?","o":["2","3","4","Only 1"],"h1":"Think of a pair.","h2":"In New Hampshire, no more than 2 motorcycles may ride side by side in a single lane.","p":"Right. No more than 2."},"es":{"q":"En New Hampshire, ¿cuál es el mayor número de motocicletas que pueden ir lado a lado en un carril?","o":["2","3","4","Solo 1"],"h1":"Piense en una pareja.","h2":"En New Hampshire, no pueden ir más de 2 motocicletas lado a lado en un mismo carril.","p":"Correcto. No más de 2."},"ref":{"doc":"NH","page":null}},{"id":"nh-076","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, a motorcycle has no windshield to protect the rider's eyes and face. What must the rider wear while riding?","o":["Nothing extra","Eyeglasses, goggles or a face shield","Only a reflective vest","Only gloves"],"h1":"It protects the eyes from wind and bugs.","h2":"In New Hampshire, if a motorcycle has no windshield or screen protecting the rider's eyes and face, the rider must wear eyeglasses, goggles or a face shield.","p":"Right. Eyeglasses, goggles or a face shield."},"es":{"q":"En New Hampshire, una motocicleta no tiene parabrisas que proteja los ojos y la cara del motociclista. ¿Qué debe llevar puesto el motociclista mientras maneja?","o":["Nada más","Anteojos, gafas protectoras o una careta","Solo un chaleco reflectante","Solo guantes"],"h1":"Protege los ojos del viento y de los insectos.","h2":"En New Hampshire, si una motocicleta no tiene parabrisas o pantalla que proteja los ojos y la cara, el motociclista debe usar anteojos, gafas protectoras o una careta.","p":"Correcto. Anteojos, gafas protectoras o una careta."},"ref":{"doc":"NH","page":null}},{"id":"nh-077","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, may a motorcycle rider carry a package that keeps one hand off the handlebars?","o":["Yes, if it is small","Yes, on short trips","No, the rider must be able to keep both hands on the handlebars","Yes, if the package is tied to the rider's arm"],"h1":"Think about full control of the motorcycle.","h2":"In New Hampshire, a motorcycle rider may not carry any package or item that keeps the rider from keeping both hands on the handlebars.","p":"Right. Both hands must stay on the handlebars."},"es":{"q":"En New Hampshire, ¿puede un motociclista llevar un paquete que le impida tener una mano en el manubrio?","o":["Sí, si es pequeño","Sí, en viajes cortos","No, el motociclista debe poder tener las dos manos en el manubrio","Sí, si el paquete está amarrado al brazo"],"h1":"Piense en el control total de la motocicleta.","h2":"En New Hampshire, un motociclista no puede llevar ningún paquete u objeto que le impida tener las dos manos en el manubrio.","p":"Correcto. Las dos manos deben estar en el manubrio."},"ref":{"doc":"NH","page":null}},{"id":"nh-078","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, who must wear a helmet when riding a bicycle on a public road?","o":["Every rider","Riders under 21","Only riders at night","Riders under 16"],"h1":"It applies to children and young teens.","h2":"In New Hampshire, a bicycle rider under 16 must wear an approved helmet on a public road.","p":"Right. Riders under 16."},"es":{"q":"En New Hampshire, ¿quién debe usar casco al andar en bicicleta por una vía pública?","o":["Todos los ciclistas","Los ciclistas menores de 21 años","Solo los ciclistas de noche","Los ciclistas menores de 16 años"],"h1":"Se aplica a niños y adolescentes jóvenes.","h2":"En New Hampshire, un ciclista menor de 16 años debe usar un casco aprobado en una vía pública.","p":"Correcto. Los menores de 16 años."},"ref":{"doc":"NH","page":null}},{"id":"nh-079","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, what must a bicycle rider wear between half an hour after sunset and half an hour before sunrise?","o":["At least one piece of reflective clothing","A helmet light","Only dark clothing","Nothing special"],"h1":"It helps drivers see the rider in headlights.","h2":"In New Hampshire, at night a bicycle rider must wear at least one item of reflective outer clothing.","p":"Right. At least one reflective item."},"es":{"q":"En New Hampshire, ¿qué debe llevar puesto un ciclista entre media hora después de la puesta del sol y media hora antes de la salida del sol?","o":["Al menos una prenda reflectante","Una luz en el casco","Solo ropa oscura","Nada especial"],"h1":"Ayuda a que los conductores vean al ciclista con los faros.","h2":"En New Hampshire, de noche un ciclista debe llevar al menos una prenda exterior reflectante.","p":"Correcto. Al menos una prenda reflectante."},"ref":{"doc":"NH","page":null}},{"id":"nh-080","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, a bicycle is ridden in the dark. From how far in front must its white lamp be visible?","o":["50 feet","300 feet","30 feet","1 mile"],"h1":"It is about the length of a football field.","h2":"In New Hampshire, a bicycle ridden in the dark needs a white front lamp visible from 300 feet, and a red rear reflector.","p":"Right. 300 feet."},"es":{"q":"En New Hampshire, una bicicleta circula en la oscuridad. ¿Desde qué distancia al frente debe verse su luz blanca?","o":["50 pies","300 pies","30 pies","1 milla"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En New Hampshire, una bicicleta que circula en la oscuridad necesita una luz blanca delantera visible a 300 pies y un reflector rojo atrás.","p":"Correcto. 300 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-081","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, a 19-year-old driver is carrying alcohol in the car, with no parent or other allowed adult along. What can happen to the license?","o":["Nothing, if the bottles are closed","A warning only","It can be suspended for 60 days","It is taken away for 10 years"],"h1":"It is about two months.","h2":"In New Hampshire, a driver under 21 who carries alcohol in a vehicle, without an allowed family member along, can have the license suspended for 60 days.","p":"Right. 60 days."},"es":{"q":"En New Hampshire, un conductor de 19 años lleva alcohol en el carro, sin un padre ni otro adulto permitido. ¿Qué le puede pasar a la licencia?","o":["Nada, si las botellas están cerradas","Solo una advertencia","Se la pueden suspender por 60 días","Se la quitan por 10 años"],"h1":"Son unos dos meses.","h2":"En New Hampshire, un conductor menor de 21 años que lleva alcohol en un vehículo, sin un familiar permitido, puede perder la licencia por 60 días.","p":"Correcto. 60 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-082","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, by driving on a public road, which tests have you agreed to take if you are arrested for impaired driving?","o":["Only a breath test","No test unless a judge orders it","Only a blood test at a hospital","Breath, blood or urine tests"],"h1":"The law lists three kinds of samples.","h2":"In New Hampshire, by driving you agree to breath, blood or urine tests if you are arrested for driving while impaired.","p":"Right. Breath, blood or urine tests."},"es":{"q":"En New Hampshire, al manejar en una vía pública, ¿qué pruebas ha aceptado hacerse si lo arrestan por manejar bajo los efectos del alcohol o drogas?","o":["Solo una prueba de aliento","Ninguna prueba, a menos que la ordene un juez","Solo una prueba de sangre en un hospital","Pruebas de aliento, sangre u orina"],"h1":"La ley menciona tres tipos de muestras.","h2":"En New Hampshire, al manejar usted acepta pruebas de aliento, sangre u orina si lo arrestan por manejar bajo los efectos del alcohol o drogas.","p":"Correcto. Pruebas de aliento, sangre u orina."},"ref":{"doc":"NH","page":null}},{"id":"nh-083","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, an adult driver is arrested and a test shows 0.08 or more. It is the first time. How long is the administrative license suspension by the state, separate from the court case?","o":["6 months","10 days","5 years","There is no suspension outside court"],"h1":"It is half a year.","h2":"In New Hampshire, a first-time driver whose test shows 0.08 or more gets an administrative license suspension of 6 months.","p":"Right. 6 months."},"es":{"q":"En New Hampshire, arrestan a un conductor adulto y una prueba muestra 0.08 o más. Es la primera vez. ¿Por cuánto tiempo dura la suspensión administrativa de la licencia por parte del estado, aparte del juicio?","o":["6 meses","10 días","5 años","No hay suspensión fuera del juicio"],"h1":"Es medio año.","h2":"En New Hampshire, a un conductor que por primera vez da 0.08 o más en la prueba le suspenden la licencia por vía administrativa durante 6 meses.","p":"Correcto. 6 meses."},"ref":{"doc":"NH","page":null}},{"id":"nh-084","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, an adult is convicted of a first DWI. What is the shortest time the license is revoked?","o":["30 days","9 months","5 years","It is not revoked"],"h1":"It is less than a year.","h2":"In New Hampshire, a first DWI conviction means the license is revoked for at least 9 months, and the court can make it up to 2 years.","p":"Right. At least 9 months."},"es":{"q":"En New Hampshire, un adulto es condenado por un primer DWI (manejar en estado de ebriedad). ¿Cuál es el tiempo mínimo de revocación de la licencia?","o":["30 días","9 meses","5 años","No se revoca"],"h1":"Es menos de un año.","h2":"En New Hampshire, una primera condena por DWI significa que la licencia se revoca por al menos 9 meses, y el tribunal puede extenderlo hasta 2 años.","p":"Correcto. Al menos 9 meses."},"ref":{"doc":"NH","page":null}},{"id":"nh-085","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, a driver who was under 21 at the time is convicted of DWI. What is the shortest time the license is revoked?","o":["30 days","3 months","One year","Until age 25"],"h1":"It is longer than the minimum for adults.","h2":"In New Hampshire, if a driver was under 21 when the DWI happened, the license is revoked for at least one year.","p":"Right. At least one year."},"es":{"q":"En New Hampshire, un conductor que era menor de 21 años en ese momento es condenado por DWI. ¿Cuál es el tiempo mínimo de revocación de la licencia?","o":["30 días","3 meses","Un año","Hasta los 25 años"],"h1":"Es más largo que el mínimo para adultos.","h2":"En New Hampshire, si el conductor era menor de 21 años cuando ocurrió el DWI, la licencia se revoca por al menos un año.","p":"Correcto. Al menos un año."},"ref":{"doc":"NH","page":null}},{"id":"nh-086","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, where must your driver's license be while you drive?","o":["At home in a safe place","Anywhere, as long as you can bring it to the police within a month","Only a photo of it on your phone","On you, or somewhere easy to reach in the vehicle"],"h1":"An officer may ask you to hand it over.","h2":"In New Hampshire, you must carry your driver's license on you or keep it in an easy-to-reach place in the vehicle, and hand it to an officer who asks for it.","p":"Right. On you or easy to reach in the car."},"es":{"q":"En New Hampshire, ¿dónde debe estar su licencia de conducir mientras maneja?","o":["En casa, en un lugar seguro","En cualquier parte, si puede llevarla a la policía en un mes","Solo una foto en su teléfono","Con usted, o en un lugar fácil de alcanzar dentro del vehículo"],"h1":"Un policía puede pedirle que se la entregue.","h2":"En New Hampshire, debe llevar su licencia de conducir con usted o en un lugar fácil de alcanzar dentro del vehículo, y entregarla al policía que se la pida.","p":"Correcto. Con usted o fácil de alcanzar en el carro."},"ref":{"doc":"NH","page":null}},{"id":"nh-087","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, a driver with a Youth Operator License is 19. What about the 1 a.m. to 4 a.m. and passenger limits?","o":["They no longer apply","They stay until age 21","They become stricter","They stay until age 25"],"h1":"The license itself lasts until 21, but these limits do not.","h2":"In New Hampshire, the night-hour and passenger limits on a Youth Operator License do not apply to drivers over 18.","p":"Right. They no longer apply after 18."},"es":{"q":"En New Hampshire, un conductor con licencia juvenil (Youth Operator License) tiene 19 años. ¿Qué pasa con los límites de 1 a.m. a 4 a.m. y de pasajeros?","o":["Ya no se aplican","Siguen hasta los 21 años","Se vuelven más estrictos","Siguen hasta los 25 años"],"h1":"La licencia dura hasta los 21, pero estos límites no.","h2":"En New Hampshire, los límites de horario nocturno y de pasajeros de la licencia juvenil no se aplican a los conductores mayores de 18 años.","p":"Correcto. Ya no se aplican después de los 18."},"ref":{"doc":"NH","page":null}},{"id":"nh-088","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, a 16-year-old youth operator drives at 2 a.m. for the first time and is caught. What is the most that can happen?","o":["Only a warning","A fine of up to $100 and a license suspension of up to 30 days","A $1,000 fine and loss of license for one year","Jail time"],"h1":"The penalty is a small fine and a short suspension.","h2":"In New Hampshire, a first violation of the youth night-hour or passenger limits brings a fine of up to $100 and a license suspension of up to 30 days.","p":"Right. Up to $100 and up to 30 days."},"es":{"q":"En New Hampshire, un conductor juvenil de 16 años maneja a las 2 a.m. por primera vez y lo detienen. ¿Qué es lo máximo que le puede pasar?","o":["Solo una advertencia","Una multa de hasta $100 y una suspensión de la licencia de hasta 30 días","Una multa de $1,000 y pérdida de la licencia por un año","Cárcel"],"h1":"La sanción es una multa pequeña y una suspensión corta.","h2":"En New Hampshire, una primera infracción de los límites de horario nocturno o de pasajeros para jóvenes tiene una multa de hasta $100 y una suspensión de la licencia de hasta 30 días.","p":"Correcto. Hasta $100 y hasta 30 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-089","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, a driver under 20 with a first license is convicted of a first traffic offense, such as speeding. For how long can the DMV suspend the license?","o":["1 to 5 days","1 to 2 years","20 to 40 days","There is no suspension for a first offense"],"h1":"It is more than two weeks but less than two months.","h2":"In New Hampshire, a driver under 20 with an original license can have it suspended for 20 to 40 days after a first conviction.","p":"Right. 20 to 40 days."},"es":{"q":"En New Hampshire, un conductor menor de 20 años con su primera licencia es condenado por una primera infracción de tránsito, como exceso de velocidad. ¿Por cuánto tiempo puede el DMV suspenderle la licencia?","o":["De 1 a 5 días","De 1 a 2 años","De 20 a 40 días","No hay suspensión por una primera infracción"],"h1":"Es más de dos semanas pero menos de dos meses.","h2":"En New Hampshire, a un conductor menor de 20 años con licencia original se le puede suspender la licencia de 20 a 40 días después de una primera condena.","p":"Correcto. De 20 a 40 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-090","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, a youth operator is convicted of driving more than 30 mph over the speed limit. What must happen before the license is given back?","o":["Nothing; the license is kept","Only a new photo","Only paying the fine online","At least 90 days must pass, and the driver must finish a driver attitude program in person"],"h1":"There is a waiting time and a class.","h2":"In New Hampshire, a youth operator convicted of going more than 30 mph over the limit cannot get the license back for at least 90 days and must finish an in-person driver attitude program.","p":"Right. At least 90 days and a driver attitude program."},"es":{"q":"En New Hampshire, un conductor juvenil es condenado por manejar a más de 30 mph por encima del límite. ¿Qué debe pasar antes de que le devuelvan la licencia?","o":["Nada; conserva la licencia","Solo una foto nueva","Solo pagar la multa por internet","Deben pasar al menos 90 días y debe completar en persona un programa de actitud al volante"],"h1":"Hay un tiempo de espera y una clase.","h2":"En New Hampshire, un conductor juvenil condenado por ir a más de 30 mph por encima del límite no puede recuperar la licencia antes de 90 días y debe completar en persona un programa de actitud al volante.","p":"Correcto. Al menos 90 días y un programa de actitud al volante."},"ref":{"doc":"NH","page":null}},{"id":"nh-091","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, how many hours of classroom instruction must a driver education course have for a license applicant under 18?","o":["At least 30 hours","At least 5 hours","At least 100 hours","No classroom hours"],"h1":"It is the biggest part of driver education.","h2":"In New Hampshire, driver education for applicants under 18 includes at least 30 hours of classroom instruction.","p":"Right. At least 30 hours."},"es":{"q":"En New Hampshire, ¿cuántas horas de clase teórica debe tener el curso de educación vial para un solicitante menor de 18 años?","o":["Al menos 30 horas","Al menos 5 horas","Al menos 100 horas","Ninguna hora de clase"],"h1":"Es la parte más grande de la educación vial.","h2":"En New Hampshire, la educación vial para solicitantes menores de 18 años incluye al menos 30 horas de clase teórica.","p":"Correcto. Al menos 30 horas."},"ref":{"doc":"NH","page":null}},{"id":"nh-092","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, how many hours of behind-the-wheel training must a driver education course give a student under 18?","o":["At least 2 hours","At least 10 hours","At least 40 hours","At least 60 hours"],"h1":"It is fewer than the 40 hours of practice with a parent.","h2":"In New Hampshire, driver education for applicants under 18 includes at least 10 hours of behind-the-wheel training.","p":"Right. At least 10 hours."},"es":{"q":"En New Hampshire, ¿cuántas horas de práctica al volante debe dar el curso de educación vial a un estudiante menor de 18 años?","o":["Al menos 2 horas","Al menos 10 horas","Al menos 40 horas","Al menos 60 horas"],"h1":"Son menos que las 40 horas de práctica con un padre.","h2":"En New Hampshire, la educación vial para solicitantes menores de 18 años incluye al menos 10 horas de práctica al volante.","p":"Correcto. Al menos 10 horas."},"ref":{"doc":"NH","page":null}},{"id":"nh-093","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, a 16-year-old applies for a driver's license. Besides the tests, what is needed?","o":["Nothing else","A letter from a teacher","Written permission from a parent or guardian, and proof of insurance","A job"],"h1":"An adult must agree, and the car must be covered.","h2":"In New Hampshire, a driver's license is not issued to someone under 18 without written permission from a parent or guardian and proof of insurance, unless the person is married.","p":"Right. A parent's written permission and proof of insurance."},"es":{"q":"En New Hampshire, un joven de 16 años solicita una licencia de conducir. Además de los exámenes, ¿qué necesita?","o":["Nada más","Una carta de un maestro","Permiso por escrito de un padre o tutor, y prueba de seguro","Un trabajo"],"h1":"Un adulto debe estar de acuerdo, y debe haber seguro.","h2":"En New Hampshire, no se da licencia de conducir a un menor de 18 años sin el permiso por escrito de un padre o tutor y prueba de seguro, salvo que esté casado.","p":"Correcto. Permiso por escrito de un padre y prueba de seguro."},"ref":{"doc":"NH","page":null}},{"id":"nh-094","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, how much light must the front side windows next to the driver let through?","o":["At least 5 percent","At least 20 percent","At least 35 percent","At least 70 percent"],"h1":"Most of the light must get through.","h2":"In New Hampshire, the front side windows to the left and right of the driver must let through at least 70 percent of light.","p":"Right. At least 70 percent."},"es":{"q":"En New Hampshire, ¿cuánta luz deben dejar pasar las ventanas laterales delanteras junto al conductor?","o":["Al menos el 5 por ciento","Al menos el 20 por ciento","Al menos el 35 por ciento","Al menos el 70 por ciento"],"h1":"Debe pasar la mayor parte de la luz.","h2":"En New Hampshire, las ventanas laterales delanteras a la izquierda y a la derecha del conductor deben dejar pasar al menos el 70 por ciento de la luz.","p":"Correcto. Al menos el 70 por ciento."},"ref":{"doc":"NH","page":null}},{"id":"nh-095","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, may you add tint to your car's windshield?","o":["Only a strip at the very top, no wider than 6 inches","Yes, any amount","Yes, if it lets through half the light","Only on the passenger half"],"h1":"Only a narrow band is allowed.","h2":"In New Hampshire, after-market tint on the windshield is allowed only in a strip at the very top, no wider than 6 inches.","p":"Right. Only a top strip up to 6 inches wide."},"es":{"q":"En New Hampshire, ¿puede poner polarizado en el parabrisas de su carro?","o":["Solo una franja en la parte de arriba, de no más de 6 pulgadas","Sí, todo lo que quiera","Sí, si deja pasar la mitad de la luz","Solo en la mitad del pasajero"],"h1":"Solo se permite una banda angosta.","h2":"En New Hampshire, el polarizado agregado al parabrisas solo se permite en una franja en la parte de arriba, de no más de 6 pulgadas.","p":"Correcto. Solo una franja arriba de hasta 6 pulgadas."},"ref":{"doc":"NH","page":null}},{"id":"nh-096","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, during the day, your load sticks out 4 feet or more past the back of your truck bed. What must you put on its end?","o":["Nothing","A red flag or cloth at least 12 inches square","A white light","A sign saying WIDE LOAD"],"h1":"At night a red light is needed; in the day, something red to see.","h2":"In New Hampshire, a load that sticks out 4 feet or more behind the vehicle must have a red flag or cloth at least 12 inches square at its end in daylight, and a red light at night.","p":"Right. A red flag at least 12 inches square."},"es":{"q":"En New Hampshire, de día, su carga sobresale 4 pies o más de la parte de atrás de la caja de su camioneta. ¿Qué debe poner en su extremo?","o":["Nada","Una bandera o tela roja de al menos 12 pulgadas por lado","Una luz blanca","Un letrero que diga WIDE LOAD"],"h1":"De noche hace falta una luz roja; de día, algo rojo que se vea.","h2":"En New Hampshire, una carga que sobresale 4 pies o más detrás del vehículo debe llevar en su extremo una bandera o tela roja de al menos 12 pulgadas por lado de día, y una luz roja de noche.","p":"Correcto. Una bandera roja de al menos 12 pulgadas por lado."},"ref":{"doc":"NH","page":null}},{"id":"nh-097","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you are in a crash with another car. Besides stopping, what must you give the other driver?","o":["Only your phone number","Nothing; the police handle it","Your name and address, license number and vehicle registration number","Only your insurance company's name"],"h1":"The other driver needs to know who you are and which car was involved.","h2":"In New Hampshire, after a crash you must stop and give your name and address, driver's license number and vehicle registration number to the other driver, or to the police if the driver cannot receive them.","p":"Right. Name, address, license and registration numbers."},"es":{"q":"En New Hampshire, usted tiene un choque con otro carro. Además de detenerse, ¿qué debe darle al otro conductor?","o":["Solo su número de teléfono","Nada; la policía se encarga","Su nombre y dirección, número de licencia y número de registro del vehículo","Solo el nombre de su compañía de seguros"],"h1":"El otro conductor necesita saber quién es usted y qué carro estuvo involucrado.","h2":"En New Hampshire, después de un choque debe detenerse y dar su nombre y dirección, número de licencia y número de registro del vehículo al otro conductor, o a la policía si el conductor no puede recibirlos.","p":"Correcto. Nombre, dirección, números de licencia y de registro."},"ref":{"doc":"NH","page":null}},{"id":"nh-098","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, a driver must show proof of financial responsibility, such as insurance. How much bodily injury coverage is needed for one person in one crash?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"It is half of the amount for two or more people.","h2":"In New Hampshire, proof of financial responsibility means $25,000 for injury to one person, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. $25,000 for one person."},"es":{"q":"En New Hampshire, un conductor debe presentar prueba de responsabilidad financiera, como un seguro. ¿Cuánta cobertura por lesiones se necesita para una persona en un choque?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Es la mitad del monto para dos o más personas.","h2":"En New Hampshire, la prueba de responsabilidad financiera es de $25,000 por lesiones a una persona, $50,000 para dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. $25,000 por persona."},"ref":{"doc":"NH","page":null}},{"id":"nh-099","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, how many people may sit in the front seat if it blocks the driver's view or control?","o":["No more than 3","No more than 5","No more than 4","There is no limit"],"h1":"Think of the driver and two others.","h2":"In New Hampshire, you may not drive with more than 3 people in the front seat if that blocks your view or gets in the way of your control of the car.","p":"Right. No more than 3."},"es":{"q":"En New Hampshire, ¿cuántas personas pueden ir en el asiento delantero si eso tapa la vista o el control del conductor?","o":["No más de 3","No más de 5","No más de 4","No hay límite"],"h1":"Piense en el conductor y dos personas más.","h2":"En New Hampshire, no puede manejar con más de 3 personas en el asiento delantero si eso le tapa la vista o le quita control del carro.","p":"Correcto. No más de 3."},"ref":{"doc":"NH","page":null}},{"id":"nh-100","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a person with a white cane held up, or led by a guide dog, is crossing the street. What must you do?","o":["Honk so the person knows you are there","Come to a full stop and take care not to hurt the person","Drive around the person slowly","Keep going if you have a green light"],"h1":"Never assume the person can see you.","h2":"In New Hampshire, you must come to a full stop for a blind person crossing with a raised white cane or a guide dog, and take care not to hurt the person before going on.","p":"Right. Stop fully and take care."},"es":{"q":"En New Hampshire, una persona con un bastón blanco levantado, o guiada por un perro guía, está cruzando la calle. ¿Qué debe hacer?","o":["Tocar la bocina para que sepa que usted está ahí","Detenerse por completo y tener cuidado de no lastimarla","Rodearla despacio","Seguir si tiene luz verde"],"h1":"Nunca suponga que la persona puede verlo.","h2":"En New Hampshire, debe detenerse por completo ante una persona ciega que cruza con un bastón blanco levantado o un perro guía, y tener cuidado de no lastimarla antes de seguir.","p":"Correcto. Deténgase por completo y tenga cuidado."},"ref":{"doc":"NH","page":null}},{"id":"nh-101","scope":"NH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Hampshire, a school crossing guard signals you to stop. How far from the guard must you stop?","o":["At least 5 feet","At least 10 feet","At least 25 feet","At least 100 feet"],"h1":"It is the same distance as for a stopped school bus.","h2":"In New Hampshire, when a school crossing guard signals you to stop, you must stop at least 25 feet before the guard.","p":"Right. At least 25 feet."},"es":{"q":"En New Hampshire, un guardia de cruce escolar le indica que se detenga. ¿A qué distancia del guardia debe detenerse?","o":["Al menos a 5 pies","Al menos a 10 pies","Al menos a 25 pies","Al menos a 100 pies"],"h1":"Es la misma distancia que para un autobús escolar detenido.","h2":"En New Hampshire, cuando un guardia de cruce escolar le indica que se detenga, debe detenerse al menos 25 pies antes del guardia.","p":"Correcto. Al menos 25 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-102","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, what is the minimum speed limit on interstate highways?","o":["25 mph","35 mph","55 mph","45 mph"],"h1":"It is 10 mph below 55 mph.","h2":"In New Hampshire, the minimum speed limit on the interstate highways is 45 mph.","p":"Right. 45 mph."},"es":{"q":"En New Hampshire, ¿cuál es el límite de velocidad mínima en las autopistas interestatales?","o":["25 mph","35 mph","55 mph","45 mph"],"h1":"Es 10 mph menos que 55 mph.","h2":"En New Hampshire, el límite de velocidad mínima en las autopistas interestatales es de 45 mph.","p":"Correcto. 45 mph."},"ref":{"doc":"NH","page":null}},{"id":"nh-103","scope":"NH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the fine for a first offense of breaking the Move Over law?","o":["$25 plus a penalty assessment","$75 plus a penalty assessment","$500 plus a penalty assessment","$1,000 plus a penalty assessment"],"h1":"It is less than $100 for a first offense.","h2":"In New Hampshire, a first offense of breaking the Move Over law costs a $75 fine plus a penalty assessment.","p":"Right. $75 plus a penalty assessment."},"es":{"q":"En New Hampshire, ¿cuál es la multa por una primera infracción de la ley Move Over (apartarse)?","o":["$25 más un recargo","$75 más un recargo","$500 más un recargo","$1,000 más un recargo"],"h1":"Es menos de $100 para la primera infracción.","h2":"En New Hampshire, una primera infracción de la ley Move Over cuesta una multa de $75 más un recargo.","p":"Correcto. $75 más un recargo."},"ref":{"doc":"NH","page":null}},{"id":"nh-104","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, you come to a crash scene where a stopped fire truck blocks part of your lane. Besides slowing down, what must you do?","o":["Stay in your lane and drive past slowly","Stop and wait until the crash is cleared","Speed up to get past quickly","Leave the blocked lane as soon as you can"],"h1":"Do not stay in a lane that is blocked, even partly.","h2":"In New Hampshire, at an emergency scene you must slow down and move out of any lane that is fully or partly blocked as soon as you can.","p":"Right. Leave the blocked lane as soon as you can."},"es":{"q":"En New Hampshire, llega a un choque donde un camión de bomberos detenido bloquea parte de su carril. Además de reducir la velocidad, ¿qué debe hacer?","o":["Quedarse en su carril y pasar despacio","Detenerse y esperar hasta que despejen el choque","Acelerar para pasar rápido","Salir del carril bloqueado lo antes posible"],"h1":"No se quede en un carril bloqueado, aunque sea en parte.","h2":"En New Hampshire, en una emergencia en la vía debe reducir la velocidad y salir lo antes posible de cualquier carril bloqueado total o parcialmente.","p":"Correcto. Salga del carril bloqueado lo antes posible."},"ref":{"doc":"NH","page":null}},{"id":"nh-105","scope":"NH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Hampshire, the lead car of a funeral procession goes through an intersection on a green light. The light turns red. What may the rest of the procession do?","o":["Keep going without stopping, with care","Stop and wait for the next green light","Go only if a police officer is there","Turn on high beams and go one at a time"],"h1":"The procession stays together once the lead car has crossed legally.","h2":"In New Hampshire, once the lead car of a funeral procession has crossed an intersection legally, the rest of the procession may keep going without stopping, whatever the sign or signal, but with care.","p":"Right. The procession may keep going, with care."},"es":{"q":"En New Hampshire, el auto que encabeza un cortejo fúnebre cruza una intersección con luz verde. La luz cambia a roja. ¿Qué puede hacer el resto del cortejo?","o":["Seguir sin detenerse, con cuidado","Detenerse y esperar la próxima luz verde","Seguir solo si hay un policía","Encender las luces altas y pasar uno por uno"],"h1":"El cortejo se mantiene unido cuando el auto de adelante cruzó legalmente.","h2":"En New Hampshire, cuando el auto que encabeza un cortejo fúnebre cruzó legalmente una intersección, el resto del cortejo puede seguir sin detenerse, sin importar la señal o el semáforo, pero con cuidado.","p":"Correcto. El cortejo puede seguir, con cuidado."},"ref":{"doc":"NH","page":null}},{"id":"nh-106","scope":"NH","cat":"signals","sign":null,"c":2,"en":{"q":"In New Hampshire, you drive in a funeral procession. Which lights must be on?","o":["Only the parking lights","Only the hazard flashers","Headlights, taillights, and hazard flashers if the car has them","No lights in daytime"],"h1":"Other drivers must be able to see every car in the line.","h2":"In New Hampshire, each car in a funeral procession must have its headlights and taillights on, and its hazard flashers too if it has them.","p":"Right. Headlights, taillights and hazard flashers."},"es":{"q":"En New Hampshire, usted maneja en un cortejo fúnebre. ¿Qué luces deben estar encendidas?","o":["Solo las luces de estacionamiento","Solo las intermitentes de emergencia","Los faros, las luces traseras y las intermitentes de emergencia si el auto las tiene","Ninguna luz durante el día"],"h1":"Los demás conductores deben ver cada auto de la fila.","h2":"En New Hampshire, cada auto de un cortejo fúnebre debe llevar encendidos los faros y las luces traseras, y también las intermitentes de emergencia si las tiene.","p":"Correcto. Faros, luces traseras e intermitentes de emergencia."},"ref":{"doc":"NH","page":null}},{"id":"nh-107","scope":"NH","cat":"signals","sign":null,"c":2,"en":{"q":"In New Hampshire, what color is the flashing light on a funeral escort or lead vehicle?","o":["Blue","Red","Purple","Green"],"h1":"It is a color that police, fire and road crews do not use.","h2":"In New Hampshire, a funeral escort or lead vehicle uses a purple flashing light.","p":"Right. Purple."},"es":{"q":"En New Hampshire, ¿de qué color es la luz intermitente del vehículo que escolta o encabeza un cortejo fúnebre?","o":["Azul","Roja","Morada","Verde"],"h1":"Es un color que no usan la policía, los bomberos ni los equipos de carretera.","h2":"En New Hampshire, el vehículo que escolta o encabeza un cortejo fúnebre usa una luz intermitente morada.","p":"Correcto. Morada."},"ref":{"doc":"NH","page":null}},{"id":"nh-108","scope":"NH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Hampshire, you are behind a funeral procession on a two-lane road. May you pass it?","o":["No, passing a funeral procession on a two-lane road is not allowed","Yes, if the center line is broken","Yes, if you pass the whole line at once","Yes, during daylight"],"h1":"Be patient and stay behind the line of cars.","h2":"In New Hampshire, a driver who is not in a funeral procession may not try to pass its cars on a two-lane road.","p":"Right. Do not pass it on a two-lane road."},"es":{"q":"En New Hampshire, usted va detrás de un cortejo fúnebre en una carretera de dos carriles. ¿Puede rebasarlo?","o":["No, no se permite rebasar un cortejo fúnebre en una carretera de dos carriles","Sí, si la línea central es discontinua","Sí, si rebasa toda la fila de una vez","Sí, de día"],"h1":"Tenga paciencia y quédese detrás de la fila de autos.","h2":"En New Hampshire, un conductor que no forma parte de un cortejo fúnebre no puede intentar rebasar sus autos en una carretera de dos carriles.","p":"Correcto. No lo rebase en una carretera de dos carriles."},"ref":{"doc":"NH","page":null}},{"id":"nh-109","scope":"NH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Hampshire, a funeral procession is moving through town. May you drive into a gap between its cars?","o":["Yes, if the gap is big enough","Yes, if you turn on your headlights","Yes, to reach a driveway","No, unless a police officer tells you to"],"h1":"Treat the procession as one long vehicle.","h2":"In New Hampshire, you may not drive between the cars of a moving funeral procession unless a police officer allows it.","p":"Right. Not unless a police officer tells you to."},"es":{"q":"En New Hampshire, un cortejo fúnebre avanza por el pueblo. ¿Puede meterse en un espacio entre sus autos?","o":["Sí, si el espacio es grande","Sí, si enciende los faros","Sí, para llegar a una entrada de auto","No, a menos que un policía se lo indique"],"h1":"Piense en el cortejo como un solo vehículo largo.","h2":"En New Hampshire, no puede meterse entre los autos de un cortejo fúnebre en movimiento, a menos que un policía lo permita.","p":"Correcto. No, a menos que un policía se lo indique."},"ref":{"doc":"NH","page":null}},{"id":"nh-110","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a person must walk along a two-way road that has no sidewalk and no shoulder. Where should the person walk?","o":["Near the right edge, with traffic","Near the left edge, facing traffic","In the middle of the lane","On the center line"],"h1":"Walkers should see the cars coming toward them.","h2":"In New Hampshire, where a two-way road has no sidewalk or shoulder, a person on foot should walk near the outside edge on the left side, facing traffic.","p":"Right. On the left side, facing traffic."},"es":{"q":"En New Hampshire, una persona debe caminar por una carretera de doble sentido sin acera ni acotamiento. ¿Por dónde debe caminar?","o":["Cerca del borde derecho, en el sentido del tráfico","Cerca del borde izquierdo, de frente al tráfico","Por el centro del carril","Sobre la línea central"],"h1":"Quien camina debe ver los autos que vienen hacia él.","h2":"En New Hampshire, donde una carretera de doble sentido no tiene acera ni acotamiento, el peatón debe caminar cerca del borde por el lado izquierdo, de frente al tráfico.","p":"Correcto. Por el lado izquierdo, de frente al tráfico."},"ref":{"doc":"NH","page":null}},{"id":"nh-111","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, outside towns you must stop your car partly on the road. From how far away must other drivers be able to see it in each direction?","o":["50 feet","100 feet","1,000 feet","200 feet"],"h1":"Do not stop just past a hill or a curve.","h2":"In New Hampshire, outside business and residence districts, a car stopped on the road must be in clear view from 200 feet in each direction, with room left for other cars to pass.","p":"Right. 200 feet in each direction."},"es":{"q":"En New Hampshire, fuera de los pueblos debe detener su auto en parte sobre la carretera. ¿Desde qué distancia deben poder verlo los demás conductores en cada dirección?","o":["50 pies","100 pies","1,000 pies","200 pies"],"h1":"No se detenga justo después de una colina o una curva.","h2":"En New Hampshire, fuera de zonas comerciales y residenciales, un auto detenido en la carretera debe verse claramente desde 200 pies en cada dirección, dejando espacio para que pasen los demás.","p":"Correcto. 200 pies en cada dirección."},"ref":{"doc":"NH","page":null}},{"id":"nh-112","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what do you need to ride an electric bicycle (e-bike) on the road?","o":["A driver's license","No driver's license and no registration","A motorcycle license","A registration and license plate"],"h1":"The law treats an e-bike much like a regular bicycle.","h2":"In New Hampshire, an electric bicycle needs no driver's license, registration or plate; it has the same rights and duties as a regular bicycle.","p":"Right. No license and no registration."},"es":{"q":"En New Hampshire, ¿qué necesita para andar en una bicicleta eléctrica (e-bike) por la carretera?","o":["Una licencia de conducir","Ni licencia de conducir ni registro","Una licencia de motocicleta","Un registro y una placa"],"h1":"La ley trata la bicicleta eléctrica casi como una bicicleta común.","h2":"En New Hampshire, una bicicleta eléctrica no necesita licencia de conducir, registro ni placa; tiene los mismos derechos y deberes que una bicicleta común.","p":"Correcto. Ni licencia ni registro."},"ref":{"doc":"NH","page":null}},{"id":"nh-113","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, how old must you be to ride a class 3 electric bicycle (the fastest class)?","o":["At least 12","At least 18","At least 16","At least 21"],"h1":"It is the same age as many first driver's licenses.","h2":"In New Hampshire, no one under 16 may ride a class 3 electric bicycle, except as a passenger on one made for passengers.","p":"Right. At least 16."},"es":{"q":"En New Hampshire, ¿qué edad debe tener para manejar una bicicleta eléctrica de clase 3 (la clase más rápida)?","o":["Al menos 12 años","Al menos 18 años","Al menos 16 años","Al menos 21 años"],"h1":"Es la misma edad de muchas primeras licencias de conducir.","h2":"En New Hampshire, nadie menor de 16 años puede manejar una bicicleta eléctrica de clase 3, salvo como pasajero en una hecha para pasajeros.","p":"Correcto. Al menos 16 años."},"ref":{"doc":"NH","page":null}},{"id":"nh-114","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, who must wear a helmet on a class 3 electric bicycle?","o":["Every rider and passenger under 18","Only riders under 12","Only the rider, at any age","No one"],"h1":"The age is higher than for a regular bicycle.","h2":"In New Hampshire, anyone under 18 riding on a class 3 electric bicycle, as rider or passenger, must wear a fitted, fastened, approved helmet.","p":"Right. Everyone under 18."},"es":{"q":"En New Hampshire, ¿quién debe usar casco en una bicicleta eléctrica de clase 3?","o":["Todo conductor y pasajero menor de 18 años","Solo los menores de 12 años","Solo el conductor, de cualquier edad","Nadie"],"h1":"La edad es mayor que para una bicicleta común.","h2":"En New Hampshire, todo menor de 18 años que vaya en una bicicleta eléctrica de clase 3, como conductor o pasajero, debe usar un casco aprobado, bien ajustado y abrochado.","p":"Correcto. Todos los menores de 18 años."},"ref":{"doc":"NH","page":null}},{"id":"nh-115","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, a driver is caught driving for the first time while the license is suspended. What is the smallest fine?","o":["$250","$50","$100","$2,000"],"h1":"It is more than the usual $100 traffic fine.","h2":"In New Hampshire, the fine for a first offense of driving while your license is suspended or revoked is at least $250.","p":"Right. At least $250."},"es":{"q":"En New Hampshire, detienen a un conductor por primera vez manejando con la licencia suspendida. ¿Cuál es la multa mínima?","o":["$250","$50","$100","$2,000"],"h1":"Es más que la multa común de $100.","h2":"En New Hampshire, la multa por una primera infracción de manejar con la licencia suspendida o revocada es de al menos $250.","p":"Correcto. Al menos $250."},"ref":{"doc":"NH","page":null}},{"id":"nh-116","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, a person whose license was taken away for impaired driving (DWI) drives anyway and is convicted. What is the shortest jail time?","o":["No jail time","24 hours","7 days in a row","1 year"],"h1":"It is one full week, and the court cannot suspend it.","h2":"In New Hampshire, driving while your license is suspended for DWI or a similar offense means at least 7 consecutive 24-hour periods in jail.","p":"Right. At least 7 days in a row."},"es":{"q":"En New Hampshire, una persona a quien le quitaron la licencia por manejar bajo los efectos (DWI) maneja de todos modos y la declaran culpable. ¿Cuál es el tiempo mínimo de cárcel?","o":["Nada de cárcel","24 horas","7 días seguidos","1 año"],"h1":"Es una semana completa, y el juez no puede suspenderla.","h2":"En New Hampshire, manejar con la licencia suspendida por DWI o una falta similar significa al menos 7 periodos seguidos de 24 horas en la cárcel.","p":"Correcto. Al menos 7 días seguidos."},"ref":{"doc":"NH","page":null}},{"id":"nh-117","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, a driver is convicted of driving while the license was suspended for DWI. What happens to the license?","o":["It is given back right away","It is revoked for one more year","Nothing more happens to it","It is revoked for one more week"],"h1":"The time without a license gets longer.","h2":"In New Hampshire, a driver convicted of driving while suspended for DWI or a similar offense loses the license for one more year.","p":"Right. One more year without a license."},"es":{"q":"En New Hampshire, declaran culpable a un conductor de manejar con la licencia suspendida por DWI. ¿Qué pasa con la licencia?","o":["Se la devuelven de inmediato","Se revoca por un año más","No le pasa nada más","Se revoca por una semana más"],"h1":"El tiempo sin licencia se alarga.","h2":"En New Hampshire, a un conductor culpable de manejar con la licencia suspendida por DWI o una falta similar le revocan la licencia por un año más.","p":"Correcto. Un año más sin licencia."},"ref":{"doc":"NH","page":null}},{"id":"nh-118","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, your family tows a camper trailer on the highway. May anyone ride inside the trailer?","o":["Yes, if they wear seat belts","Yes, adults only","Yes, on short trips","No, no one may ride in it while it is moving"],"h1":"A towed trailer is not a passenger seat.","h2":"In New Hampshire, no one may ride inside a house trailer or utility trailer while it is being moved on the road.","p":"Right. No one may ride in it."},"es":{"q":"En New Hampshire, su familia remolca una casa rodante (tráiler) por la carretera. ¿Puede alguien ir dentro del tráiler?","o":["Sí, si usa cinturón","Sí, solo adultos","Sí, en viajes cortos","No, nadie puede ir dentro mientras se mueve"],"h1":"Un tráiler remolcado no es un asiento de pasajero.","h2":"En New Hampshire, nadie puede ir dentro de una casa rodante o un tráiler de carga mientras lo mueven por la carretera.","p":"Correcto. Nadie puede ir dentro."},"ref":{"doc":"NH","page":null}},{"id":"nh-119","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the fine for riding a motorcycle without a motorcycle license, endorsement or learner's permit?","o":["$25","$100","$500","$1,200"],"h1":"It is the same as the fine for running a stop sign.","h2":"In New Hampshire, the fine for riding a motorcycle without a motorcycle license, endorsement or learner's permit is $100.","p":"Right. $100."},"es":{"q":"En New Hampshire, ¿cuál es la multa por manejar una motocicleta sin licencia de motocicleta, endoso o permiso de aprendiz?","o":["$25","$100","$500","$1,200"],"h1":"Es igual que la multa por no parar en una señal de alto.","h2":"En New Hampshire, la multa por manejar una motocicleta sin licencia de motocicleta, endoso o permiso de aprendiz es de $100.","p":"Correcto. $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-120","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, a rider has a restricted endorsement for 3-wheeled motorcycles only. May the rider drive a 2-wheeled motorcycle?","o":["Yes, any motorcycle","Yes, in daylight only","Yes, with a passenger 25 or older","No, only 3-wheeled motorcycles"],"h1":"The endorsement matches the type of motorcycle tested.","h2":"In New Hampshire, a rider with a restricted 3-wheeled motorcycle endorsement may drive 3-wheeled motorcycles but not 2-wheeled ones.","p":"Right. Only 3-wheeled motorcycles."},"es":{"q":"En New Hampshire, un motociclista tiene un endoso restringido solo para motocicletas de 3 ruedas. ¿Puede manejar una motocicleta de 2 ruedas?","o":["Sí, cualquier motocicleta","Sí, solo de día","Sí, con un pasajero de 25 años o más","No, solo motocicletas de 3 ruedas"],"h1":"El endoso corresponde al tipo de motocicleta del examen.","h2":"En New Hampshire, quien tiene un endoso restringido para motocicletas de 3 ruedas puede manejar motocicletas de 3 ruedas, pero no de 2 ruedas.","p":"Correcto. Solo motocicletas de 3 ruedas."},"ref":{"doc":"NH","page":null}},{"id":"nh-121","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, a 17-year-old wants a motorcycle learner's permit. What must the teen already have?","o":["A New Hampshire driver's license and a finished driver education course","Nothing; any 17-year-old may get one","A parent riding on the back","A moped registration"],"h1":"Adults 18 and older do not need these, but younger riders do.","h2":"In New Hampshire, a motorcycle learner's permit is for people 18 or older, or 16 and 17-year-olds who have finished an approved driver education course and hold a valid New Hampshire driver's license.","p":"Right. A New Hampshire license and driver education."},"es":{"q":"En New Hampshire, un joven de 17 años quiere un permiso de aprendiz de motocicleta. ¿Qué debe tener ya?","o":["Una licencia de conducir de New Hampshire y un curso de educación vial terminado","Nada; cualquiera de 17 años puede obtenerlo","Un padre que vaya atrás en la moto","El registro de un ciclomotor"],"h1":"Los adultos de 18 años o más no lo necesitan, pero los más jóvenes sí.","h2":"En New Hampshire, el permiso de aprendiz de motocicleta es para personas de 18 años o más, o de 16 y 17 años que terminaron un curso aprobado de educación vial y tienen una licencia de conducir válida de New Hampshire.","p":"Correcto. Una licencia de New Hampshire y educación vial."},"ref":{"doc":"NH","page":null}},{"id":"nh-122","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, how long is a motorcycle learner's permit valid?","o":["10 days","6 months","45 days","2 years"],"h1":"It is about a month and a half.","h2":"In New Hampshire, a motorcycle learner's permit is valid for 45 days, or until you get your motorcycle license if that comes first.","p":"Right. 45 days."},"es":{"q":"En New Hampshire, ¿por cuánto tiempo es válido un permiso de aprendiz de motocicleta?","o":["10 días","6 meses","45 días","2 años"],"h1":"Es como un mes y medio.","h2":"En New Hampshire, un permiso de aprendiz de motocicleta es válido por 45 días, o hasta que obtenga la licencia de motocicleta si eso ocurre antes.","p":"Correcto. 45 días."},"ref":{"doc":"NH","page":null}},{"id":"nh-123","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, your motorcycle learner's permit is running out. How many times may it be renewed?","o":["Never","As many times as you like","One time, for 45 more days","Once a year"],"h1":"You get one more chance, not endless ones.","h2":"In New Hampshire, a motorcycle learner's permit may be renewed one time, for another 45 days.","p":"Right. One renewal, for 45 more days."},"es":{"q":"En New Hampshire, su permiso de aprendiz de motocicleta está por vencer. ¿Cuántas veces se puede renovar?","o":["Nunca","Todas las veces que quiera","Una vez, por 45 días más","Una vez al año"],"h1":"Tiene una oportunidad más, no infinitas.","h2":"En New Hampshire, el permiso de aprendiz de motocicleta se puede renovar una sola vez, por otros 45 días.","p":"Correcto. Una renovación, por 45 días más."},"ref":{"doc":"NH","page":null}},{"id":"nh-124","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, you have failed the motorcycle driving test twice. What must you do next?","o":["Finish the motorcycle rider education program","Wait one year and test again","Take the car driving test again","Pay a fee and test as often as you like"],"h1":"After two tries, you need training.","h2":"In New Hampshire, you may take the motorcycle driving test only twice; after failing it twice, you must finish the motorcycle rider education program.","p":"Right. Finish the rider education program."},"es":{"q":"En New Hampshire, usted reprobó dos veces el examen práctico de motocicleta. ¿Qué debe hacer ahora?","o":["Terminar el programa de educación para motociclistas","Esperar un año y volver a presentarlo","Presentar otra vez el examen práctico de auto","Pagar y presentarlo todas las veces que quiera"],"h1":"Después de dos intentos, necesita capacitación.","h2":"En New Hampshire, el examen práctico de motocicleta solo se puede presentar dos veces; si lo reprueba dos veces, debe terminar el programa de educación para motociclistas.","p":"Correcto. Terminar el programa de educación para motociclistas."},"ref":{"doc":"NH","page":null}},{"id":"nh-125","scope":"NH","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Hampshire, what do you need to ride a moped on a public road?","o":["No license at all","Only a bicycle helmet","A commercial driver's license","A valid driver's license"],"h1":"A moped is not treated like a bicycle here.","h2":"In New Hampshire, you may ride a moped on a public road only if you hold a valid driver's license, such as a regular or motorcycle license.","p":"Right. A valid driver's license."},"es":{"q":"En New Hampshire, ¿qué necesita para manejar un ciclomotor (moped) en una vía pública?","o":["Ninguna licencia","Solo un casco de bicicleta","Una licencia de conducir comercial","Una licencia de conducir válida"],"h1":"Aquí un ciclomotor no se trata como una bicicleta.","h2":"En New Hampshire, solo puede manejar un ciclomotor en una vía pública si tiene una licencia de conducir válida, como una licencia común o de motocicleta.","p":"Correcto. Una licencia de conducir válida."},"ref":{"doc":"NH","page":null}},{"id":"nh-126","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, how must a person sit on a motorcycle?","o":["Sideways, with both legs on one side","Astride the seat, facing forward, one leg on each side","Facing backward, if a passenger","Any way, if holding on"],"h1":"Think of how you sit on a horse.","h2":"In New Hampshire, a person on a motorcycle must sit astride the seat, facing forward, with one leg on each side.","p":"Right. Astride, facing forward."},"es":{"q":"En New Hampshire, ¿cómo debe sentarse una persona en una motocicleta?","o":["De lado, con las dos piernas del mismo lado","A horcajadas en el asiento, mirando hacia adelante, con una pierna a cada lado","Mirando hacia atrás, si es pasajero","De cualquier forma, si se agarra bien"],"h1":"Piense en cómo se sienta en un caballo.","h2":"En New Hampshire, quien va en una motocicleta debe sentarse a horcajadas en el asiento, mirando hacia adelante, con una pierna a cada lado.","p":"Correcto. A horcajadas, mirando hacia adelante."},"ref":{"doc":"NH","page":null}},{"id":"nh-127","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, which equipment must every motorcycle on the road have?","o":["A windshield and a radio","Saddlebags and a backrest","A sidecar","Footrests for each rider and a rearview mirror"],"h1":"One is for your feet, one is for seeing behind.","h2":"In New Hampshire, every motorcycle on the road must have footrests for each person riding it and a rearview mirror.","p":"Right. Footrests and a rearview mirror."},"es":{"q":"En New Hampshire, ¿qué equipo debe tener toda motocicleta en la carretera?","o":["Un parabrisas y un radio","Alforjas y un respaldo","Un sidecar","Reposapiés para cada persona y un espejo retrovisor"],"h1":"Uno es para los pies y otro para ver atrás.","h2":"En New Hampshire, toda motocicleta en la carretera debe tener reposapiés para cada persona que va en ella y un espejo retrovisor.","p":"Correcto. Reposapiés y espejo retrovisor."},"ref":{"doc":"NH","page":null}},{"id":"nh-128","scope":"NH","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Hampshire, what is the fine for driving a vehicle that is not registered?","o":["$20","$100","$500","$1,000"],"h1":"It is a common New Hampshire fine amount.","h2":"In New Hampshire, the fine for driving a vehicle that must be registered but is not is $100.","p":"Right. $100."},"es":{"q":"En New Hampshire, ¿cuál es la multa por manejar un vehículo que no está registrado?","o":["$20","$100","$500","$1,000"],"h1":"Es una multa común en New Hampshire.","h2":"En New Hampshire, la multa por manejar un vehículo que debe estar registrado y no lo está es de $100.","p":"Correcto. $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-129","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, you bought a car and are driving it on a 20-day registration. What must you have with you?","o":["The title from the last three owners","A letter from your insurance agent","A valid bill of sale for the car","Nothing extra"],"h1":"It shows the car was sold to you.","h2":"In New Hampshire, a 20-day registration is valid for 20 days, and you must carry a valid bill of sale for the car while you drive on it.","p":"Right. A valid bill of sale."},"es":{"q":"En New Hampshire, usted compró un auto y lo maneja con un registro de 20 días. ¿Qué debe llevar consigo?","o":["El título de los últimos tres dueños","Una carta de su agente de seguros","Un comprobante de venta válido del auto","Nada más"],"h1":"Demuestra que el auto se lo vendieron a usted.","h2":"En New Hampshire, un registro de 20 días vale por 20 días, y mientras maneje con él debe llevar un comprobante de venta válido del auto.","p":"Correcto. Un comprobante de venta válido."},"ref":{"doc":"NH","page":null}},{"id":"nh-130","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, it is daytime, but rain, snow or fog hides people and cars from you. When must your headlights be on?","o":["When you cannot clearly see 1,000 feet ahead","Only when you cannot see 50 feet ahead","Only after sunset","Only on highways"],"h1":"The distance is about one fifth of a mile.","h2":"In New Hampshire, you must show at least 2 lighted front lamps whenever rain, snow or fog keeps you from clearly seeing people and vehicles 1,000 feet ahead.","p":"Right. When you cannot see clearly 1,000 feet ahead."},"es":{"q":"En New Hampshire, es de día, pero la lluvia, la nieve o la niebla le impiden ver a personas y autos. ¿Cuándo debe llevar los faros encendidos?","o":["Cuando no puede ver claramente 1,000 pies adelante","Solo cuando no puede ver 50 pies adelante","Solo después de la puesta del sol","Solo en autopistas"],"h1":"La distancia es como un quinto de milla.","h2":"En New Hampshire, debe llevar al menos 2 luces delanteras encendidas siempre que la lluvia, la nieve o la niebla le impidan ver claramente personas y vehículos a 1,000 pies.","p":"Correcto. Cuando no puede ver claramente 1,000 pies adelante."},"ref":{"doc":"NH","page":null}},{"id":"nh-131","scope":"NH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Hampshire, how far ahead must a car's headlights make people and objects on the road clearly visible?","o":["200 feet","20 feet","50 feet","2,000 feet"],"h1":"It is about two-thirds of a football field.","h2":"In New Hampshire, a car's headlights must light the road well enough to show vehicles, people and large objects clearly at 200 feet.","p":"Right. 200 feet."},"es":{"q":"En New Hampshire, ¿a qué distancia deben los faros de un auto mostrar claramente a personas y objetos en la carretera?","o":["200 pies","20 pies","50 pies","2,000 pies"],"h1":"Es como dos tercios de una cancha de fútbol americano.","h2":"En New Hampshire, los faros de un auto deben iluminar la carretera para mostrar claramente vehículos, personas y objetos grandes a 200 pies.","p":"Correcto. 200 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-132","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, at night, from how far behind must your red tail lamp be visible?","o":["At least 50 feet","At least 100 feet","At least 1,000 feet","At least 2 miles"],"h1":"It is the same distance used for headlights in fog.","h2":"In New Hampshire, at night a vehicle's red tail lamp must be visible from at least 1,000 feet behind it.","p":"Right. At least 1,000 feet."},"es":{"q":"En New Hampshire, de noche, ¿desde qué distancia detrás debe verse su luz trasera roja?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies","Al menos 2 millas"],"h1":"Es la misma distancia que se usa para los faros con niebla.","h2":"En New Hampshire, de noche la luz trasera roja de un vehículo debe verse desde al menos 1,000 pies detrás.","p":"Correcto. Al menos 1,000 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-133","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, at night, a white light must shine on your rear license plate. From how far must the plate be readable?","o":["At least 5 feet","At least 50 feet","At least 500 feet","At least 1,000 feet"],"h1":"It is a short distance, about three car lengths.","h2":"In New Hampshire, a white light must light the rear plate at night so its characters can be read from at least 50 feet.","p":"Right. At least 50 feet."},"es":{"q":"En New Hampshire, de noche, una luz blanca debe iluminar la placa trasera. ¿Desde qué distancia debe poder leerse la placa?","o":["Al menos 5 pies","Al menos 50 pies","Al menos 500 pies","Al menos 1,000 pies"],"h1":"Es una distancia corta, como tres autos de largo.","h2":"En New Hampshire, de noche una luz blanca debe iluminar la placa trasera para que sus caracteres se lean desde al menos 50 pies.","p":"Correcto. Al menos 50 pies."},"ref":{"doc":"NH","page":null}},{"id":"nh-134","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, besides windshield wipers, what must every car made after 1947 have in good working order?","o":["Snow tires","A roof rack","Fog lights","A defroster for the windshield"],"h1":"It melts snow and ice on the glass.","h2":"In New Hampshire, every car must have windshield wipers, and cars made after January 1, 1947 must also have a working windshield defroster.","p":"Right. A working defroster."},"es":{"q":"En New Hampshire, además de limpiaparabrisas, ¿qué debe tener funcionando todo auto fabricado después de 1947?","o":["Llantas de nieve","Una parrilla de techo","Faros antiniebla","Un desempañador (descongelador) del parabrisas"],"h1":"Derrite la nieve y el hielo del vidrio.","h2":"En New Hampshire, todo auto debe tener limpiaparabrisas, y los fabricados después del 1 de enero de 1947 también deben tener un descongelador del parabrisas que funcione.","p":"Correcto. Un descongelador que funcione."},"ref":{"doc":"NH","page":null}},{"id":"nh-135","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, a driver uses a straight pipe exhaust with no muffler baffles. What is the smallest fine for a first offense?","o":["$10","$100","$1,000","$5,000"],"h1":"It goes up to $250 and then $500 for repeat offenses in a year.","h2":"In New Hampshire, driving with a straight pipe exhaust is fined at least $100 for a first offense, $250 for a second and $500 for a third in a calendar year.","p":"Right. At least $100."},"es":{"q":"En New Hampshire, un conductor usa un escape de tubo recto, sin deflectores de silenciador. ¿Cuál es la multa mínima por una primera infracción?","o":["$10","$100","$1,000","$5,000"],"h1":"Sube a $250 y luego a $500 si se repite en el mismo año.","h2":"En New Hampshire, manejar con un escape de tubo recto tiene una multa de al menos $100 la primera vez, $250 la segunda y $500 la tercera en un año calendario.","p":"Correcto. Al menos $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-136","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, which screen may the driver look at while the car is moving?","o":["A TV show","A movie on a DVD player","A video on a phone mounted on the dash","A navigation map with traffic and weather"],"h1":"It must help with the driving task.","h2":"In New Hampshire, a driver may not watch TV or video while the car is moving, but screens for navigation, traffic, weather and vehicle information are allowed.","p":"Right. A navigation map is allowed."},"es":{"q":"En New Hampshire, ¿qué pantalla puede mirar el conductor mientras el auto se mueve?","o":["Un programa de televisión","Una película en un reproductor de DVD","Un video en un teléfono montado en el tablero","Un mapa de navegación con tráfico y clima"],"h1":"Debe ayudar a la tarea de manejar.","h2":"En New Hampshire, el conductor no puede ver televisión ni videos mientras el auto se mueve, pero se permiten pantallas de navegación, tráfico, clima e información del vehículo.","p":"Correcto. Se permite un mapa de navegación."},"ref":{"doc":"NH","page":null}},{"id":"nh-137","scope":"NH","cat":"signals","sign":null,"c":0,"en":{"q":"In New Hampshire, who may drive a vehicle with forward-facing blue lights?","o":["A sworn law enforcement officer","A tow truck","A funeral escort","A snowplow"],"h1":"Only certain officers may drive with blue lights.","h2":"In New Hampshire, blue lights are reserved for law enforcement and corrections officers; fire and rescue vehicles may have only a single rear-facing blue light.","p":"Right. A sworn law enforcement officer."},"es":{"q":"En New Hampshire, ¿quién puede manejar un vehículo con luces azules hacia adelante?","o":["Un agente del orden juramentado (policía)","Una grúa","Una escolta funeraria","Un quitanieves"],"h1":"Solo ciertos agentes pueden manejar con luces azules.","h2":"En New Hampshire, las luces azules están reservadas para agentes del orden y de correccionales; los vehículos de bomberos y rescate solo pueden tener una luz azul hacia atrás.","p":"Correcto. Un agente del orden."},"ref":{"doc":"NH","page":null}},{"id":"nh-138","scope":"NH","cat":"signals","sign":null,"c":2,"en":{"q":"In New Hampshire, which vehicles must always show a slow moving vehicle emblem on the back when on the road?","o":["All pickup trucks","School buses","Tractors and animal-drawn vehicles","Motorcycles"],"h1":"Think of farm traffic.","h2":"In New Hampshire, every tractor and every animal-drawn vehicle on the road must show an approved slow moving vehicle emblem on its back.","p":"Right. Tractors and animal-drawn vehicles."},"es":{"q":"En New Hampshire, ¿qué vehículos deben llevar siempre atrás el emblema de vehículo lento cuando van por la carretera?","o":["Todas las camionetas pickup","Los autobuses escolares","Los tractores y los vehículos tirados por animales","Las motocicletas"],"h1":"Piense en el tráfico de las granjas.","h2":"En New Hampshire, todo tractor y todo vehículo tirado por animales en la carretera debe llevar atrás un emblema aprobado de vehículo lento.","p":"Correcto. Los tractores y los vehículos tirados por animales."},"ref":{"doc":"NH","page":null}},{"id":"nh-139","scope":"NH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Hampshire, you drive an open pickup full of sand on a highway at 50 mph. What does the law require?","o":["Nothing, if the bed is not overfull","Drive with hazard lights on","Cover the load fully with a tarp or similar cover","Put a red flag on the load"],"h1":"Nothing may blow out onto the road.","h2":"In New Hampshire, an open vehicle carrying sand, gravel, stone, earth or similar loads must have the load fully covered and secured by a tarp or similar cover, unless it is driven under 30 mph.","p":"Right. Cover the load fully."},"es":{"q":"En New Hampshire, maneja una camioneta abierta llena de arena por una carretera a 50 mph. ¿Qué exige la ley?","o":["Nada, si la caja no va muy llena","Manejar con las intermitentes de emergencia","Cubrir toda la carga con una lona u otra cubierta similar","Poner una bandera roja en la carga"],"h1":"Nada puede volar a la carretera.","h2":"En New Hampshire, un vehículo abierto que lleva arena, grava, piedra, tierra o cargas similares debe llevarla totalmente cubierta y sujeta con una lona o algo similar, salvo que vaya a menos de 30 mph.","p":"Correcto. Cubra toda la carga."},"ref":{"doc":"NH","page":null}},{"id":"nh-140","scope":"NH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Hampshire, an ambulance with siren and flashing lights comes up behind you near an intersection. What must you do?","o":["Pull to the right edge, clear of the intersection, and stop until it passes","Stop right in the middle of the intersection","Speed up to stay ahead of it","Keep driving at the same speed"],"h1":"Move right, but do not block the crossing.","h2":"In New Hampshire, when an emergency vehicle with siren or lights approaches, you must pull as close as you can to the right edge, clear of any intersection, and stop until it has passed, unless a police officer directs otherwise.","p":"Right. Pull right, clear of the intersection, and stop."},"es":{"q":"En New Hampshire, una ambulancia con sirena y luces se acerca por detrás cerca de una intersección. ¿Qué debe hacer?","o":["Orillarse a la derecha, fuera de la intersección, y detenerse hasta que pase","Detenerse en medio de la intersección","Acelerar para mantenerse adelante","Seguir a la misma velocidad"],"h1":"Muévase a la derecha, pero no bloquee el cruce.","h2":"En New Hampshire, cuando se acerca un vehículo de emergencia con sirena o luces, debe orillarse lo más posible a la derecha, fuera de cualquier intersección, y detenerse hasta que pase, salvo que un policía le indique otra cosa.","p":"Correcto. Orillarse a la derecha, fuera de la intersección, y detenerse."},"ref":{"doc":"NH","page":null}},{"id":"nh-141","scope":"NH","cat":"signals","sign":null,"c":3,"en":{"q":"In New Hampshire, what is the fine for not stopping at a stop sign?","o":["$25","$300","$1,000","$100"],"h1":"It is the same as the fine for following too closely.","h2":"In New Hampshire, the fine for breaking the stop sign or yield sign law is $100.","p":"Right. $100."},"es":{"q":"En New Hampshire, ¿cuál es la multa por no detenerse en una señal de alto (STOP)?","o":["$25","$300","$1,000","$100"],"h1":"Es igual que la multa por seguir demasiado cerca.","h2":"En New Hampshire, la multa por no cumplir la ley de la señal de alto o de ceda el paso es de $100.","p":"Correcto. $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-142","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a driver goes through a railroad crossing while the warning lights are flashing. What is the fine for a first offense?","o":["$10 plus a penalty assessment","$100 plus a penalty assessment","$2,000 plus a penalty assessment","There is no fine, only a warning"],"h1":"A second offense within 12 months costs $250.","h2":"In New Hampshire, breaking a railroad crossing law costs $100 plus a penalty assessment for a first offense, and $250 plus a penalty assessment for another offense within 12 months.","p":"Right. $100 plus a penalty assessment."},"es":{"q":"En New Hampshire, un conductor cruza las vías del tren mientras las luces de advertencia parpadean. ¿Cuál es la multa por una primera infracción?","o":["$10 más un recargo","$100 más un recargo","$2,000 más un recargo","No hay multa, solo una advertencia"],"h1":"Una segunda infracción dentro de 12 meses cuesta $250.","h2":"En New Hampshire, no cumplir una ley de cruce de ferrocarril cuesta $100 más un recargo la primera vez, y $250 más un recargo por otra infracción dentro de 12 meses.","p":"Correcto. $100 más un recargo."},"ref":{"doc":"NH","page":null}},{"id":"nh-143","scope":"NH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Hampshire, a flagger in a work zone signals you to stop. Where must you stop?","o":["Right next to the flagger","At least 500 feet before the flagger","Anywhere, as long as you slow down","At least 25 feet before the flagger"],"h1":"It is the same distance as for a crossing guard.","h2":"In New Hampshire, when a flagger signals you to stop, you must stop at least 25 feet before the flagger and wait until you are told to go and it is safe.","p":"Right. At least 25 feet before the flagger."},"es":{"q":"En New Hampshire, un abanderado en una zona de obras le indica que se detenga. ¿Dónde debe detenerse?","o":["Justo al lado del abanderado","Al menos 500 pies antes del abanderado","En cualquier lugar, si reduce la velocidad","Al menos 25 pies antes del abanderado"],"h1":"Es la misma distancia que para un guardia de cruce.","h2":"En New Hampshire, cuando un abanderado le indica que se detenga, debe detenerse al menos 25 pies antes del abanderado y esperar hasta que le indique seguir y sea seguro.","p":"Correcto. Al menos 25 pies antes del abanderado."},"ref":{"doc":"NH","page":null}},{"id":"nh-144","scope":"NH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Hampshire, you park in a space for people with a walking disability without a plate or placard. What is the smallest fine?","o":["$25 plus a penalty assessment","$50 plus a penalty assessment","$500 plus a penalty assessment","$100 plus a penalty assessment"],"h1":"It is much higher than most parking tickets.","h2":"In New Hampshire, parking in a space or access aisle for people with a walking disability without the right plate or placard costs at least $500 plus a penalty assessment.","p":"Right. At least $500 plus a penalty assessment."},"es":{"q":"En New Hampshire, usted se estaciona en un espacio para personas con discapacidad para caminar sin placa ni permiso. ¿Cuál es la multa mínima?","o":["$25 más un recargo","$50 más un recargo","$500 más un recargo","$100 más un recargo"],"h1":"Es mucho más que la mayoría de las multas de estacionamiento.","h2":"En New Hampshire, estacionarse en un espacio o pasillo de acceso para personas con discapacidad para caminar sin la placa o el permiso correcto cuesta al menos $500 más un recargo.","p":"Correcto. Al menos $500 más un recargo."},"ref":{"doc":"NH","page":null}},{"id":"nh-145","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, a parent sits beside a teen who is learning to drive without a license. The teen runs a red light. Who is liable for the violation?","o":["The adult riding with the teen","No one, because the teen has no license","Only the driver education school","Only the owner of the car, if not the parent"],"h1":"The supervisor is responsible for what the learner does.","h2":"In New Hampshire, the licensed adult riding with an unlicensed learner is liable for any traffic violation the learner commits.","p":"Right. The adult riding with the teen."},"es":{"q":"En New Hampshire, un padre va sentado al lado de un adolescente que aprende a manejar sin licencia. El adolescente se pasa una luz roja. ¿Quién es responsable de la infracción?","o":["El adulto que acompaña al adolescente","Nadie, porque el adolescente no tiene licencia","Solo la escuela de manejo","Solo el dueño del auto, si no es el padre"],"h1":"El supervisor responde por lo que hace el aprendiz.","h2":"En New Hampshire, el adulto con licencia que acompaña a un aprendiz sin licencia es responsable de cualquier infracción de tránsito que cometa el aprendiz.","p":"Correcto. El adulto que acompaña al adolescente."},"ref":{"doc":"NH","page":null}},{"id":"nh-146","scope":"NH","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Hampshire, you let a friend drive your car, knowing the friend's license is suspended. What is the smallest fine for you?","o":["$100","$10","$25","You cannot be fined"],"h1":"The owner is also responsible.","h2":"In New Hampshire, an owner who knowingly lets a person with a suspended or revoked license drive the car is fined at least $100.","p":"Right. At least $100."},"es":{"q":"En New Hampshire, usted deja que un amigo maneje su auto sabiendo que tiene la licencia suspendida. ¿Cuál es la multa mínima para usted?","o":["$100","$10","$25","No le pueden multar"],"h1":"El dueño también es responsable.","h2":"En New Hampshire, el dueño que a sabiendas deja manejar su auto a una persona con la licencia suspendida o revocada recibe una multa de al menos $100.","p":"Correcto. Al menos $100."},"ref":{"doc":"NH","page":null}},{"id":"nh-147","scope":"NH","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Hampshire, your cousin asks to borrow your driver's license. What does the law say?","o":["It is fine if your cousin looks like you","It is allowed for one day","Lending your license to anyone is a misdemeanor","It is allowed if your cousin is over 21"],"h1":"A license is only for the person it was issued to.","h2":"In New Hampshire, lending your driver's license to another person, or letting someone use it, is a misdemeanor.","p":"Right. It is a misdemeanor."},"es":{"q":"En New Hampshire, su primo le pide prestada su licencia de conducir. ¿Qué dice la ley?","o":["Está bien si su primo se parece a usted","Se permite por un día","Prestar su licencia a cualquier persona es un delito menor","Se permite si su primo tiene más de 21 años"],"h1":"La licencia es solo para la persona a quien se emitió.","h2":"En New Hampshire, prestar su licencia de conducir a otra persona, o dejar que alguien la use, es un delito menor (misdemeanor).","p":"Correcto. Es un delito menor."},"ref":{"doc":"NH","page":null}},{"id":"nh-148","scope":"NH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Hampshire, a driver is convicted of a second DWI within 10 years. What is the shortest time the license is revoked?","o":["30 days","3 years","6 months","1 year"],"h1":"It is much longer than for a first offense.","h2":"In New Hampshire, a second DWI conviction within 10 years brings a license revocation of at least 3 years and a fine of at least $750.","p":"Right. At least 3 years."},"es":{"q":"En New Hampshire, declaran culpable a un conductor de un segundo DWI en 10 años. ¿Cuál es el tiempo mínimo de revocación de la licencia?","o":["30 días","3 años","6 meses","1 año"],"h1":"Es mucho más largo que por una primera infracción.","h2":"En New Hampshire, una segunda condena por DWI en 10 años trae una revocación de la licencia de al menos 3 años y una multa de al menos $750.","p":"Correcto. Al menos 3 años."},"ref":{"doc":"NH","page":null}},{"id":"nh-149","scope":"NH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Hampshire, you meet an oncoming car on a narrow road with room for only one lane each way. What must you do?","o":["Stop and let the other car back up","Drive in the middle until the car is close","Flash your high beams and keep going","Keep right and give the other driver at least half of the road"],"h1":"Share the road fairly.","h2":"In New Hampshire, drivers meeting each other must pass to the right, and on a narrow road each must give the other at least half of the main traveled part of the road.","p":"Right. Keep right and give at least half."},"es":{"q":"En New Hampshire, se cruza con un auto que viene de frente en una carretera estrecha con espacio para un solo carril en cada sentido. ¿Qué debe hacer?","o":["Detenerse y hacer que el otro auto retroceda","Ir por el centro hasta que el auto esté cerca","Hacer cambio de luces y seguir","Mantenerse a la derecha y dejar al otro conductor al menos la mitad de la vía"],"h1":"Comparta la vía de forma justa.","h2":"En New Hampshire, los conductores que se cruzan deben pasar por la derecha, y en una vía estrecha cada uno debe dejar al otro al menos la mitad de la parte principal de la vía.","p":"Correcto. Manténgase a la derecha y deje al menos la mitad."},"ref":{"doc":"NH","page":null}},{"id":"nh-150","scope":"NH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Hampshire, a person wants to hitchhike. Where may the person stand?","o":["In the travel lane, facing traffic","Off the paved part of the road","On the center line","Anywhere, if waving a sign"],"h1":"Asking for a ride is legal, but not from the pavement.","h2":"In New Hampshire, a person may hitchhike only when not standing on the paved part of the road.","p":"Right. Off the paved part of the road."},"es":{"q":"En New Hampshire, una persona quiere pedir aventón (autostop). ¿Dónde puede pararse?","o":["En el carril de circulación, de frente al tráfico","Fuera de la parte pavimentada de la vía","Sobre la línea central","En cualquier lugar, si muestra un letrero"],"h1":"Pedir aventón es legal, pero no desde el pavimento.","h2":"En New Hampshire, una persona solo puede pedir aventón si no está parada en la parte pavimentada de la vía.","p":"Correcto. Fuera de la parte pavimentada de la vía."},"ref":{"doc":"NH","page":null}},{"id":"nh-151","scope":"NH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Hampshire, you are stopped in traffic. May a bicycle rider pass your car on the right?","o":["No, never","Only if the rider gets off and walks","Only on a one-way street","Yes, a bicycle may pass a stopped car on the right"],"h1":"Check your right mirror before you open a door or turn right.","h2":"In New Hampshire, a bicycle rider may pass a stopped or standing motor vehicle on the right, so watch for bikes before you turn right or open a door.","p":"Right. A bicycle may pass a stopped car on the right."},"es":{"q":"En New Hampshire, usted está detenido en el tráfico. ¿Puede un ciclista rebasar su auto por la derecha?","o":["No, nunca","Solo si el ciclista se baja y camina","Solo en una calle de un solo sentido","Sí, una bicicleta puede rebasar por la derecha a un auto detenido"],"h1":"Mire su espejo derecho antes de abrir una puerta o girar a la derecha.","h2":"En New Hampshire, un ciclista puede rebasar por la derecha a un vehículo detenido o parado, así que fíjese en las bicicletas antes de girar a la derecha o abrir una puerta.","p":"Correcto. Una bicicleta puede rebasar por la derecha a un auto detenido."},"ref":{"doc":"NH","page":null}},{"id":"nj-001","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The New Jersey knowledge test has 50 multiple-choice questions.","p":"Right. The New Jersey test has 50 questions."},"es":{"q":"En New Jersey, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de New Jersey tiene 50 preguntas de opción múltiple.","p":"Correcto. El examen de New Jersey tiene 50 preguntas."},"zh":{"q":"在 New Jersey，知识考试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"它是一百的一半。","h2":"New Jersey 的知识考试有 50 道选择题。","p":"对。New Jersey 的考试有 50 道题。"},"vi":{"q":"Ở New Jersey, bài thi kiến thức (knowledge test) có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Đó là một nửa của một trăm.","h2":"Bài thi kiến thức của New Jersey có 50 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi của New Jersey có 50 câu hỏi."},"tl":{"q":"Sa New Jersey, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Ito ay kalahati ng isang daan.","h2":"Ang knowledge test ng New Jersey ay may 50 multiple-choice na tanong.","p":"Tama. May 50 tanong ang test ng New Jersey."},"ar":{"q":"في New Jersey، كم سؤالًا في اختبار المعرفة (knowledge test)؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"إنه نصف المئة.","h2":"في اختبار المعرفة في New Jersey يوجد 50 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في اختبار New Jersey يوجد 50 سؤالًا."},"ref":{"doc":"NJ","page":30}},{"id":"nj-002","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many knowledge test questions must you answer correctly to pass?","o":["30","40","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 New Jersey test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En New Jersey, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["30","40","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de New Jersey, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"zh":{"q":"在 New Jersey，知识考试必须答对多少道题才能通过？","o":["30","40","35","45"],"h1":"你需要答对 50 道题的百分之 80。","h2":"你必须答对 New Jersey 考试 50 道题里的至少 40 道，也就是百分之 80。","p":"对。你需要答对 40 道。"},"vi":{"q":"Ở New Jersey, bạn phải trả lời đúng bao nhiêu câu hỏi của bài thi kiến thức để đậu?","o":["30","40","35","45"],"h1":"Bạn cần đúng 80 phần trăm của 50 câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trong 50 câu hỏi của bài thi New Jersey, tức là 80 phần trăm.","p":"Đúng. Bạn cần 40 câu trả lời đúng."},"tl":{"q":"Sa New Jersey, ilang tanong sa knowledge test ang dapat mong masagot nang tama para pumasa?","o":["30","40","35","45"],"h1":"Kailangan mo ang 80 porsiyento ng 50 tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong ng test sa New Jersey, na 80 porsiyento.","p":"Tama. Kailangan mo ng 40 tamang sagot."},"ar":{"q":"في New Jersey، كم سؤالًا من أسئلة اختبار المعرفة يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["30","40","35","45"],"h1":"تحتاج إلى 80 بالمئة من الأسئلة الخمسين.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50 سؤالًا في اختبار New Jersey، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة."},"ref":{"doc":"NJ","page":31}},{"id":"nj-003","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, if you fail the knowledge test, how long must you wait to take it again?","o":["The same day","One day","7 days","30 days"],"h1":"It is one week.","h2":"In New Jersey you must wait 7 days before you can retake a failed knowledge test.","p":"Right. You wait seven days to try again."},"es":{"q":"En New Jersey, si no aprueba el examen de conocimientos, ¿cuánto debe esperar para presentarlo otra vez?","o":["El mismo día","Un día","7 días","30 días"],"h1":"Es una semana.","h2":"En New Jersey usted debe esperar 7 días antes de volver a presentar un examen de conocimientos que no aprobó.","p":"Correcto. Se esperan siete días para intentarlo de nuevo."},"zh":{"q":"在 New Jersey，如果知识考试没通过，要等多久才能再考？","o":["当天","一天","7 天","30 天"],"h1":"它是一个星期。","h2":"在 New Jersey，知识考试没通过的话，你必须等 7 天才能再考。","p":"对。你要等七天才能再考。"},"vi":{"q":"Ở New Jersey, nếu bạn thi rớt bài thi kiến thức, bạn phải chờ bao lâu để thi lại?","o":["Cùng ngày","Một ngày","7 ngày","30 ngày"],"h1":"Đó là một tuần.","h2":"Ở New Jersey, bạn phải chờ 7 ngày rồi mới được thi lại bài thi kiến thức đã rớt.","p":"Đúng. Bạn chờ bảy ngày để thi lại."},"tl":{"q":"Sa New Jersey, kung bumagsak ka sa knowledge test, gaano katagal ka dapat maghintay bago kumuha ulit?","o":["Sa parehong araw","Isang araw","7 araw","30 araw"],"h1":"Ito ay isang linggo.","h2":"Sa New Jersey, dapat kang maghintay ng 7 araw bago mo ulitin ang knowledge test na binagsak mo.","p":"Tama. Maghihintay ka ng pitong araw bago sumubok ulit."},"ar":{"q":"في New Jersey، إذا رسبت في اختبار المعرفة، كم يجب أن تنتظر لتعيده؟","o":["في اليوم نفسه","يومًا واحدًا","7 أيام","30 يومًا"],"h1":"إنه أسبوع واحد.","h2":"في New Jersey يجب أن تنتظر 7 أيام قبل أن تعيد اختبار المعرفة الذي رسبت فيه.","p":"صحيح. تنتظر سبعة أيام لتحاول مرة أخرى."},"ref":{"doc":"NJ","page":null}},{"id":"nj-004","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, what lets a 16-year-old get a special learner's permit?","o":["Being enrolled in a behind-the-wheel driver training course","Having a parent with a license","Passing a road test first","Owning a car"],"h1":"It is connected to driving lessons.","h2":"A New Jersey 16-year-old can get a special learner's permit by enrolling in a behind-the-wheel driver training course at a high school or a licensed driving school.","p":"Right. Driver training opens the permit at 16."},"es":{"q":"En New Jersey, ¿qué le permite a un joven de 16 años obtener un permiso especial de aprendiz?","o":["Estar inscrito en un curso de manejo práctico al volante","Tener un padre con licencia","Aprobar primero un examen de manejo","Ser dueño de un carro"],"h1":"Tiene que ver con clases de manejo.","h2":"Un joven de 16 años en New Jersey puede obtener un permiso especial de aprendiz si se inscribe en un curso de manejo práctico al volante en una escuela secundaria o en una escuela de manejo con licencia.","p":"Correcto. El curso de manejo abre el permiso a los 16."},"zh":{"q":"在 New Jersey，16 岁的青少年怎样才能拿到特别学习驾照（special learner's permit）？","o":["报名参加实际上路的驾驶训练课程","父母有驾照","先通过路考","自己有一辆车"],"h1":"它和驾驶课有关。","h2":"New Jersey 16 岁的青少年报名参加高中或有执照的驾校的实际上路驾驶训练课程，就可以拿到特别学习驾照。","p":"对。参加驾驶训练，16 岁就能拿学习驾照。"},"vi":{"q":"Ở New Jersey, điều gì cho phép một người 16 tuổi lấy giấy phép tập lái đặc biệt (special learner's permit)?","o":["Đã ghi danh vào một khóa học lái xe thực hành (behind-the-wheel)","Có cha hoặc mẹ có bằng lái","Thi đậu bài thi lái xe trên đường trước","Có xe hơi riêng"],"h1":"Điều này liên quan đến các buổi học lái xe.","h2":"Ở New Jersey, một người 16 tuổi có thể lấy giấy phép tập lái đặc biệt khi ghi danh vào một khóa học lái xe thực hành tại trường trung học hoặc tại một trường dạy lái xe có giấy phép.","p":"Đúng. Khóa học lái xe giúp bạn lấy giấy phép ở tuổi 16."},"tl":{"q":"Sa New Jersey, ano ang nagpapahintulot sa isang 16 taong gulang na makakuha ng special learner's permit?","o":["Naka-enroll sa isang behind-the-wheel na kurso sa pagmamaneho","May magulang na may lisensya","Pumasa muna sa road test","May sariling kotse"],"h1":"May kinalaman ito sa mga leksyon sa pagmamaneho.","h2":"Sa New Jersey, ang isang 16 taong gulang ay makakakuha ng special learner's permit kapag naka-enroll sa isang behind-the-wheel na kurso sa pagmamaneho sa high school o sa isang lisensyadong driving school.","p":"Tama. Ang kurso sa pagmamaneho ang nagbubukas ng permit sa edad na 16."},"ar":{"q":"في New Jersey، ما الذي يسمح لشخص عمره 16 سنة بالحصول على تصريح تعلّم خاص (special learner's permit)؟","o":["التسجيل في دورة تدريب عملي على القيادة (behind-the-wheel)","أن يكون لأحد والديه رخصة قيادة","النجاح في اختبار الطريق أولًا","امتلاك سيارة"],"h1":"الأمر له علاقة بدروس القيادة.","h2":"في New Jersey يستطيع من عمره 16 سنة الحصول على تصريح تعلّم خاص إذا سجّل في دورة تدريب عملي على القيادة في مدرسة ثانوية أو في مدرسة قيادة مرخّصة.","p":"صحيح. دورة تدريب القيادة تتيح التصريح في عمر 16."},"ref":{"doc":"NJ","page":19}},{"id":"nj-005","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, at what age can you get an examination permit without a driver training course?","o":["16","17","18","21"],"h1":"It is one year after the age for the special learner's permit.","h2":"In New Jersey you can get an examination permit at 17 without taking a driver training course.","p":"Right. At 17 no driver training course is needed."},"es":{"q":"En New Jersey, ¿a qué edad puede obtener un permiso de examen sin un curso de manejo?","o":["16","17","18","21"],"h1":"Es un año después de la edad del permiso especial de aprendiz.","h2":"En New Jersey usted puede obtener un permiso de examen a los 17 años sin tomar un curso de manejo.","p":"Correcto. A los 17 no se necesita curso de manejo."},"zh":{"q":"在 New Jersey，不上驾驶训练课程，几岁可以拿到考试学习驾照（examination permit）？","o":["16","17","18","21"],"h1":"它比特别学习驾照的年龄大一岁。","h2":"在 New Jersey，你 17 岁时不用上驾驶训练课程，就可以拿到考试学习驾照。","p":"对。17 岁不需要上驾驶训练课程。"},"vi":{"q":"Ở New Jersey, bạn có thể lấy giấy phép thi (examination permit) mà không cần khóa học lái xe từ bao nhiêu tuổi?","o":["16","17","18","21"],"h1":"Đó là một năm sau độ tuổi lấy giấy phép tập lái đặc biệt.","h2":"Ở New Jersey, bạn có thể lấy giấy phép thi (examination permit) từ 17 tuổi mà không cần học khóa lái xe.","p":"Đúng. Từ 17 tuổi thì không cần khóa học lái xe."},"tl":{"q":"Sa New Jersey, sa anong edad ka makakakuha ng examination permit nang walang kurso sa pagmamaneho?","o":["16","17","18","21"],"h1":"Ito ay isang taon pagkatapos ng edad para sa special learner's permit.","h2":"Sa New Jersey, makakakuha ka ng examination permit sa edad na 17 nang hindi kumukuha ng kurso sa pagmamaneho.","p":"Tama. Sa edad na 17, hindi na kailangan ng kurso sa pagmamaneho."},"ar":{"q":"في New Jersey، في أي عمر يمكنك الحصول على تصريح الاختبار (examination permit) دون دورة تدريب على القيادة؟","o":["16","17","18","21"],"h1":"إنه بعد سنة واحدة من عمر تصريح التعلّم الخاص.","h2":"في New Jersey يمكنك الحصول على تصريح الاختبار (examination permit) في عمر 17 سنة دون أن تأخذ دورة تدريب على القيادة.","p":"صحيح. في عمر 17 لا تحتاج إلى دورة تدريب على القيادة."},"ref":{"doc":"NJ","page":20}},{"id":"nj-006","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how much driving experience must the adult supervising a permit holder have?","o":["At least 1 year","At least 6 months","At least 10 years","At least 3 years"],"h1":"It is more than two years but less than five.","h2":"The supervising driver in New Jersey must be at least 21, hold a valid New Jersey license, and have at least three years of driving experience.","p":"Right. The supervisor needs three years of experience."},"es":{"q":"En New Jersey, ¿cuánta experiencia de manejo debe tener el adulto que supervisa a un conductor con permiso?","o":["Por lo menos 1 año","Por lo menos 6 meses","Por lo menos 10 años","Por lo menos 3 años"],"h1":"Es más de dos años pero menos de cinco.","h2":"El conductor supervisor en New Jersey debe tener por lo menos 21 años, una licencia válida de New Jersey y por lo menos tres años de experiencia manejando.","p":"Correcto. El supervisor necesita tres años de experiencia."},"zh":{"q":"在 New Jersey，监督学习驾照持有人的成年人必须有多少驾驶经验？","o":["至少 1 年","至少 6 个月","至少 10 年","至少 3 年"],"h1":"它比两年多，但比五年少。","h2":"在 New Jersey，监督司机必须至少 21 岁，有有效的 New Jersey 驾照，并且至少有三年驾驶经验。","p":"对。监督的人需要三年经验。"},"vi":{"q":"Ở New Jersey, người lớn đi kèm giám sát người có giấy phép tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Ít nhất 1 năm","Ít nhất 6 tháng","Ít nhất 10 năm","Ít nhất 3 năm"],"h1":"Nhiều hơn hai năm nhưng ít hơn năm năm.","h2":"Ở New Jersey, người lái xe giám sát phải ít nhất 21 tuổi, có bằng lái New Jersey còn hiệu lực, và có ít nhất ba năm kinh nghiệm lái xe.","p":"Đúng. Người giám sát cần ba năm kinh nghiệm."},"tl":{"q":"Sa New Jersey, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang adult na nagbabantay sa may permit?","o":["Hindi bababa sa 1 taon","Hindi bababa sa 6 na buwan","Hindi bababa sa 10 taon","Hindi bababa sa 3 taon"],"h1":"Higit ito sa dalawang taon pero kulang sa lima.","h2":"Sa New Jersey, ang nagbabantay na driver ay dapat hindi bababa sa 21 taong gulang, may valid na lisensya ng New Jersey, at may hindi bababa sa tatlong taon na karanasan sa pagmamaneho.","p":"Tama. Kailangan ng nagbabantay ang tatlong taon na karanasan."},"ar":{"q":"في New Jersey، كم سنة من الخبرة في القيادة يجب أن تكون لدى الشخص البالغ الذي يرافق حامل التصريح ويشرف عليه؟","o":["سنة واحدة على الأقل","6 أشهر على الأقل","10 سنوات على الأقل","3 سنوات على الأقل"],"h1":"أكثر من سنتين وأقل من خمس سنوات.","h2":"في New Jersey يجب أن يكون السائق المشرف عمره 21 سنة على الأقل، ويحمل رخصة قيادة سارية من New Jersey، ولديه ثلاث سنوات على الأقل من الخبرة في القيادة.","p":"صحيح. يحتاج المشرف إلى ثلاث سنوات من الخبرة."},"ref":{"doc":"NJ","page":18}},{"id":"nj-007","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, where must the supervising driver sit when a permit holder drives?","o":["In the back seat","Anywhere in the car","In the front seat","In a separate car following behind"],"h1":"The supervisor must be close enough to help right away.","h2":"In New Jersey the adult supervising driver must sit in the front seat next to the permit holder.","p":"Right. The supervisor sits in the front seat."},"es":{"q":"En New Jersey, ¿dónde debe sentarse el conductor supervisor cuando maneja alguien con permiso?","o":["En el asiento de atrás","En cualquier lugar del carro","En el asiento de adelante","En otro carro que va detrás"],"h1":"El supervisor debe estar lo bastante cerca para ayudar de inmediato.","h2":"En New Jersey el adulto supervisor debe sentarse en el asiento de adelante, al lado del conductor con permiso.","p":"Correcto. El supervisor va en el asiento de adelante."},"zh":{"q":"在 New Jersey，学习驾照持有人开车时，监督司机必须坐在哪里？","o":["后排座位","车里任何地方","前排座位","跟在后面的另一辆车里"],"h1":"监督的人必须离得够近，能马上帮忙。","h2":"在 New Jersey，监督的成年司机必须坐在前排，在学习驾照持有人旁边。","p":"对。监督的人坐在前排。"},"vi":{"q":"Ở New Jersey, khi người có giấy phép tập lái đang lái xe, người lái xe giám sát phải ngồi ở đâu?","o":["Ở ghế sau","Ở bất cứ chỗ nào trong xe","Ở ghế trước","Trong một xe khác chạy theo phía sau"],"h1":"Người giám sát phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở New Jersey, người lớn giám sát phải ngồi ở ghế trước, bên cạnh người có giấy phép tập lái.","p":"Đúng. Người giám sát ngồi ở ghế trước."},"tl":{"q":"Sa New Jersey, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa likurang upuan","Kahit saan sa kotse","Sa harapang upuan","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang nagbabantay para tumulong agad.","h2":"Sa New Jersey, ang adult na nagbabantay na driver ay dapat umupo sa harapang upuan, katabi ng may permit.","p":"Tama. Sa harapang upuan umuupo ang nagbabantay."},"ar":{"q":"في New Jersey، أين يجب أن يجلس السائق المشرف عندما يقود حامل التصريح؟","o":["في المقعد الخلفي","في أي مكان في السيارة","في المقعد الأمامي","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون المشرف قريبًا بما يكفي ليساعد فورًا.","h2":"في New Jersey يجب أن يجلس السائق البالغ المشرف في المقعد الأمامي بجانب حامل التصريح.","p":"صحيح. يجلس المشرف في المقعد الأمامي."},"ref":{"doc":"NJ","page":18}},{"id":"nj-008","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how long must a permit holder under 21 drive only with a supervising adult before the road test?","o":["At least 6 months","At least 1 month","At least 2 years","No set time"],"h1":"It is half a year.","h2":"In New Jersey a permit holder under 21 must drive with a supervising adult for at least six months before passing the road test.","p":"Right. Six months of supervised driving come first."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe manejar solo con un adulto supervisor un conductor con permiso menor de 21 años antes del examen de manejo?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay tiempo fijo"],"h1":"Es medio año.","h2":"En New Jersey un conductor con permiso menor de 21 años debe manejar con un adulto supervisor por lo menos seis meses antes de aprobar el examen de manejo.","p":"Correcto. Primero vienen seis meses de manejo supervisado."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照持有人在路考前，必须只和监督的成年人一起开车多久？","o":["至少 6 个月","至少 1 个月","至少 2 年","没有规定时间"],"h1":"它是半年。","h2":"在 New Jersey，未满 21 岁的学习驾照持有人在通过路考前，必须和监督的成年人一起开车至少六个月。","p":"对。先要有六个月有人监督的驾驶。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái dưới 21 tuổi phải lái xe chỉ khi có người lớn giám sát trong bao lâu trước khi thi lái xe trên đường?","o":["Ít nhất 6 tháng","Ít nhất 1 tháng","Ít nhất 2 năm","Không có thời gian quy định"],"h1":"Đó là nửa năm.","h2":"Ở New Jersey, người có giấy phép tập lái dưới 21 tuổi phải lái xe với người lớn giám sát ít nhất sáu tháng trước khi thi đậu bài thi lái xe trên đường.","p":"Đúng. Phải lái xe có giám sát sáu tháng trước."},"tl":{"q":"Sa New Jersey, gaano katagal dapat magmaneho ang may permit na wala pang 21 taong gulang kasama lamang ang nagbabantay na adult bago ang road test?","o":["Hindi bababa sa 6 na buwan","Hindi bababa sa 1 buwan","Hindi bababa sa 2 taon","Walang takdang panahon"],"h1":"Ito ay kalahating taon.","h2":"Sa New Jersey, ang may permit na wala pang 21 taong gulang ay dapat magmaneho kasama ang nagbabantay na adult nang hindi bababa sa anim na buwan bago pumasa sa road test.","p":"Tama. Anim na buwan ng binabantayang pagmamaneho muna."},"ar":{"q":"في New Jersey، كم من الوقت يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يقود مع شخص بالغ مشرف فقط قبل اختبار الطريق؟","o":["6 أشهر على الأقل","شهر واحد على الأقل","سنتان على الأقل","لا توجد مدة محددة"],"h1":"إنها نصف سنة.","h2":"في New Jersey يجب على حامل التصريح الذي عمره أقل من 21 سنة أن يقود مع شخص بالغ مشرف ستة أشهر على الأقل قبل أن ينجح في اختبار الطريق.","p":"صحيح. ستة أشهر من القيادة تحت الإشراف أولًا."},"ref":{"doc":"NJ","page":15}},{"id":"nj-009","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, between which hours may a probationary driver under 21 not drive?","o":["10:00 p.m. to 6:00 a.m.","11:01 p.m. to 5:00 a.m.","Midnight to 4:00 a.m.","9:00 p.m. to 5:00 a.m."],"h1":"It starts just after eleven at night.","h2":"In New Jersey a probationary driver under 21 may not drive from 11:01 p.m. to 5:00 a.m., unless they carry a letter showing they must drive then for work or religion.","p":"Right. No driving from 11:01 p.m. to 5:00 a.m."},"es":{"q":"En New Jersey, ¿entre qué horas no puede manejar un conductor con licencia probatoria menor de 21 años?","o":["10:00 p.m. a 6:00 a.m.","11:01 p.m. a 5:00 a.m.","Medianoche a 4:00 a.m.","9:00 p.m. a 5:00 a.m."],"h1":"Empieza justo después de las once de la noche.","h2":"En New Jersey un conductor con licencia probatoria menor de 21 años no puede manejar de 11:01 p.m. a 5:00 a.m., a menos que lleve una carta que muestre que debe manejar a esa hora por trabajo o por religión.","p":"Correcto. No se maneja de 11:01 p.m. a 5:00 a.m."},"zh":{"q":"在 New Jersey，未满 21 岁的试用驾照（probationary license）司机在哪个时间段不能开车？","o":["晚上 10:00 到早上 6:00","晚上 11:01 到早上 5:00","午夜到凌晨 4:00","晚上 9:00 到早上 5:00"],"h1":"它从晚上十一点刚过开始。","h2":"在 New Jersey，未满 21 岁的试用驾照司机从晚上 11:01 到早上 5:00 不能开车，除非带着一封信，证明因为工作或宗教必须在这个时间开车。","p":"对。晚上 11:01 到早上 5:00 不能开车。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) dưới 21 tuổi không được lái xe trong khoảng giờ nào?","o":["10:00 p.m. đến 6:00 a.m.","11:01 p.m. đến 5:00 a.m.","Nửa đêm đến 4:00 a.m.","9:00 p.m. đến 5:00 a.m."],"h1":"Bắt đầu ngay sau mười một giờ đêm.","h2":"Ở New Jersey, người lái xe tạm thời dưới 21 tuổi không được lái xe từ 11:01 p.m. đến 5:00 a.m., trừ khi họ mang theo một lá thư cho thấy họ phải lái xe vào giờ đó vì công việc hoặc tôn giáo.","p":"Đúng. Không lái xe từ 11:01 p.m. đến 5:00 a.m."},"tl":{"q":"Sa New Jersey, sa pagitan ng anong mga oras bawal magmaneho ang probationary driver na wala pang 21 taong gulang?","o":["10:00 p.m. hanggang 6:00 a.m.","11:01 p.m. hanggang 5:00 a.m.","Hatinggabi hanggang 4:00 a.m.","9:00 p.m. hanggang 5:00 a.m."],"h1":"Nagsisimula ito pagkalipas lang ng alas-onse ng gabi.","h2":"Sa New Jersey, ang probationary driver na wala pang 21 taong gulang ay hindi puwedeng magmaneho mula 11:01 p.m. hanggang 5:00 a.m., maliban kung may dala siyang sulat na nagpapakitang kailangan niyang magmaneho sa oras na iyon dahil sa trabaho o relihiyon.","p":"Tama. Bawal magmaneho mula 11:01 p.m. hanggang 5:00 a.m."},"ar":{"q":"في New Jersey، في أي ساعات لا يجوز للسائق تحت الاختبار (probationary driver) الذي عمره أقل من 21 سنة أن يقود؟","o":["من 10:00 p.m. إلى 6:00 a.m.","من 11:01 p.m. إلى 5:00 a.m.","من منتصف الليل إلى 4:00 a.m.","من 9:00 p.m. إلى 5:00 a.m."],"h1":"تبدأ بعد الساعة الحادية عشرة ليلًا مباشرة.","h2":"في New Jersey لا يجوز للسائق تحت الاختبار الذي عمره أقل من 21 سنة أن يقود من 11:01 p.m. إلى 5:00 a.m.، إلا إذا كان يحمل رسالة تُظهر أنه يجب أن يقود في هذا الوقت بسبب العمل أو الدين.","p":"صحيح. لا قيادة من 11:01 p.m. إلى 5:00 a.m."},"ref":{"doc":"NJ","page":18}},{"id":"nj-010","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many passengers may a probationary driver under 21 carry when no parent or guardian is in the car?","o":["None","Two","Three","One, plus the driver's own dependents"],"h1":"The driver's own dependents do not count.","h2":"A New Jersey probationary driver under 21 may carry only one passenger, plus the driver's own dependents, unless a parent or guardian is in the car.","p":"Right. One passenger, plus the driver's dependents."},"es":{"q":"En New Jersey, ¿cuántos pasajeros puede llevar un conductor con licencia probatoria menor de 21 años si no va un padre o tutor en el carro?","o":["Ninguno","Dos","Tres","Uno, más los dependientes del conductor"],"h1":"Los dependientes del propio conductor no cuentan.","h2":"Un conductor con licencia probatoria menor de 21 años en New Jersey solo puede llevar un pasajero, más sus propios dependientes, a menos que vaya un padre o tutor en el carro.","p":"Correcto. Un pasajero, más los dependientes del conductor."},"zh":{"q":"在 New Jersey，车里没有父母或监护人时，未满 21 岁的试用驾照司机可以载几位乘客？","o":["一位也不行","两位","三位","一位，再加上司机自己的家属（受抚养人）"],"h1":"司机自己的受抚养人不算在内。","h2":"New Jersey 未满 21 岁的试用驾照司机只能载一位乘客，再加上自己的受抚养人，除非车里有父母或监护人。","p":"对。一位乘客，再加上司机的受抚养人。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) dưới 21 tuổi được chở bao nhiêu hành khách khi không có cha mẹ hoặc người giám hộ trong xe?","o":["Không ai","Hai người","Ba người","Một người, cộng thêm những người phụ thuộc của chính người lái"],"h1":"Những người phụ thuộc của chính người lái không bị tính.","h2":"Ở New Jersey, người lái xe tạm thời dưới 21 tuổi chỉ được chở một hành khách, cộng thêm những người phụ thuộc của chính người lái, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Một hành khách, cộng thêm những người phụ thuộc của người lái."},"tl":{"q":"Sa New Jersey, ilang pasahero ang puwedeng isakay ng probationary driver na wala pang 21 taong gulang kapag walang magulang o guardian sa kotse?","o":["Wala","Dalawa","Tatlo","Isa, dagdag ang sariling mga dependent ng driver"],"h1":"Hindi binibilang ang sariling mga dependent ng driver.","h2":"Ang probationary driver sa New Jersey na wala pang 21 taong gulang ay puwedeng magsakay ng isang pasahero lamang, dagdag ang sariling mga dependent ng driver, maliban kung may magulang o guardian sa kotse.","p":"Tama. Isang pasahero, dagdag ang mga dependent ng driver."},"ar":{"q":"في New Jersey، كم راكبًا يجوز للسائق تحت الاختبار (probationary driver) الذي عمره أقل من 21 سنة أن يحمل عندما لا يكون أحد الوالدين أو الوصي في السيارة؟","o":["لا أحد","اثنان","ثلاثة","واحد، بالإضافة إلى المُعالين التابعين للسائق نفسه"],"h1":"المُعالون التابعون للسائق نفسه لا يُحسبون.","h2":"في New Jersey يجوز للسائق تحت الاختبار الذي عمره أقل من 21 سنة أن يحمل راكبًا واحدًا فقط، بالإضافة إلى المُعالين التابعين له، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد، بالإضافة إلى المُعالين التابعين للسائق."},"ref":{"doc":"NJ","page":18}},{"id":"nj-011","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, may a probationary driver use a hands-free phone while driving?","o":["No, hand-held and hands-free are both banned","Yes, hands-free is allowed","Yes, but only at red lights","Yes, if the call is short"],"h1":"The rule for new drivers covers every kind of phone use.","h2":"A New Jersey probationary driver may not use any wireless device while driving, hand-held or hands-free.","p":"Right. No phone at all for probationary drivers."},"es":{"q":"En New Jersey, ¿puede un conductor con licencia probatoria usar un teléfono manos libres mientras maneja?","o":["No, están prohibidos el teléfono en la mano y el manos libres","Sí, el manos libres está permitido","Sí, pero solo en semáforos en rojo","Sí, si la llamada es corta"],"h1":"La regla para conductores nuevos cubre todo uso del teléfono.","h2":"Un conductor con licencia probatoria en New Jersey no puede usar ningún aparato inalámbrico mientras maneja, ni en la mano ni con manos libres.","p":"Correcto. Nada de teléfono para conductores con licencia probatoria."},"zh":{"q":"在 New Jersey，试用驾照司机开车时可以用免提电话吗？","o":["不可以，手持和免提都禁止","可以，免提是允许的","可以，但只能在红灯时","可以，如果通话很短"],"h1":"新司机的规定包括所有用手机的方式。","h2":"New Jersey 的试用驾照司机开车时不能用任何无线设备，手持和免提都不行。","p":"对。试用驾照司机完全不能用手机。"},"vi":{"q":"Ở New Jersey, người lái xe tạm thời (probationary driver) có được dùng điện thoại rảnh tay khi lái xe không?","o":["Không, cả cầm tay và rảnh tay đều bị cấm","Có, được dùng rảnh tay","Có, nhưng chỉ khi dừng đèn đỏ","Có, nếu cuộc gọi ngắn"],"h1":"Luật cho người mới lái xe áp dụng cho mọi cách dùng điện thoại.","h2":"Ở New Jersey, người lái xe tạm thời không được dùng bất kỳ thiết bị không dây nào khi lái xe, dù cầm tay hay rảnh tay.","p":"Đúng. Người lái xe tạm thời không được dùng điện thoại chút nào."},"tl":{"q":"Sa New Jersey, puwede bang gumamit ng hands-free na telepono ang probationary driver habang nagmamaneho?","o":["Hindi, bawal ang hand-held at hands-free","Oo, puwede ang hands-free","Oo, pero sa red light lamang","Oo, kung maikli ang tawag"],"h1":"Sakop ng patakaran para sa mga bagong driver ang lahat ng uri ng paggamit ng telepono.","h2":"Ang probationary driver sa New Jersey ay hindi puwedeng gumamit ng kahit anong wireless device habang nagmamaneho, hand-held man o hands-free.","p":"Tama. Walang telepono para sa mga probationary driver."},"ar":{"q":"في New Jersey، هل يجوز للسائق تحت الاختبار (probationary driver) أن يستخدم هاتفًا بدون يدين (hands-free) أثناء القيادة؟","o":["لا، الهاتف المحمول باليد والهاتف بدون يدين ممنوعان كلاهما","نعم، الهاتف بدون يدين مسموح","نعم، ولكن فقط عند الإشارة الحمراء","نعم، إذا كانت المكالمة قصيرة"],"h1":"القاعدة للسائقين الجدد تشمل كل أنواع استخدام الهاتف.","h2":"في New Jersey لا يجوز للسائق تحت الاختبار أن يستخدم أي جهاز لاسلكي أثناء القيادة، سواء كان محمولًا باليد أو بدون يدين.","p":"صحيح. لا هاتف أبدًا للسائقين تحت الاختبار."},"ref":{"doc":"NJ","page":86}},{"id":"nj-012","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many reflective decals must a permit or probationary driver under 21 display on the vehicle?","o":["None","One","Two","Four"],"h1":"It is more than one but fewer than three.","h2":"A New Jersey permit or probationary driver under 21 must display two red reflective decals, one on the front license plate and one on the rear plate.","p":"Right. Two decals are displayed."},"es":{"q":"En New Jersey, ¿cuántas calcomanías reflectantes debe mostrar en el vehículo un conductor con permiso o licencia probatoria menor de 21 años?","o":["Ninguna","Una","Dos","Cuatro"],"h1":"Es más de una pero menos de tres.","h2":"En New Jersey, un conductor con permiso o licencia probatoria menor de 21 años debe mostrar dos calcomanías rojas reflectantes, una en la placa delantera y otra en la placa trasera.","p":"Correcto. Se muestran dos calcomanías."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照或试用驾照司机必须在车上贴几张反光贴纸（decal）？","o":["不用贴","一张","两张","四张"],"h1":"它比一多，但比三少。","h2":"New Jersey 未满 21 岁的学习驾照或试用驾照司机必须贴两张红色反光贴纸，一张在前车牌上，一张在后车牌上。","p":"对。要贴两张贴纸。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi phải dán bao nhiêu miếng dán phản quang (decal) trên xe?","o":["Không có","Một","Hai","Bốn"],"h1":"Nhiều hơn một nhưng ít hơn ba.","h2":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi phải dán hai miếng dán phản quang màu đỏ, một miếng trên biển số trước và một miếng trên biển số sau.","p":"Đúng. Phải dán hai miếng dán."},"tl":{"q":"Sa New Jersey, ilang reflective decal ang dapat ilagay sa sasakyan ng may permit o probationary driver na wala pang 21 taong gulang?","o":["Wala","Isa","Dalawa","Apat"],"h1":"Higit ito sa isa pero kulang sa tatlo.","h2":"Ang may permit o probationary driver sa New Jersey na wala pang 21 taong gulang ay dapat maglagay ng dalawang pulang reflective decal, isa sa plaka sa harap at isa sa plaka sa likod.","p":"Tama. Dalawang decal ang inilalagay."},"ar":{"q":"في New Jersey، كم ملصقًا عاكسًا (decal) يجب أن يضع حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة على السيارة؟","o":["لا شيء","واحد","اثنان","أربعة"],"h1":"أكثر من واحد وأقل من ثلاثة.","h2":"في New Jersey يجب على حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة أن يضع ملصقين عاكسين باللون الأحمر، واحدًا على لوحة الأرقام الأمامية وواحدًا على لوحة الأرقام الخلفية.","p":"صحيح. يوضع ملصقان."},"ref":{"doc":"NJ","page":19}},{"id":"nj-013","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for a permit or probationary driver under 21 who drives without the required decals?","o":["$25","$100","$500","There is no fine"],"h1":"It is a round number with three digits.","h2":"In New Jersey, breaking a graduated license rule, such as driving without the required decals, can bring a $100 fine.","p":"Right. Missing decals can cost $100."},"es":{"q":"En New Jersey, ¿cuál es la multa para un conductor con permiso o licencia probatoria menor de 21 años que maneja sin las calcomanías obligatorias?","o":["$25","$100","$500","No hay multa"],"h1":"Es un número redondo de tres cifras.","h2":"En New Jersey, no cumplir una regla de la licencia gradual, como manejar sin las calcomanías obligatorias, puede costar una multa de $100.","p":"Correcto. No llevar las calcomanías puede costar $100."},"zh":{"q":"在 New Jersey，未满 21 岁的学习驾照或试用驾照司机没贴规定的贴纸开车，罚款多少？","o":["$25","$100","$500","不罚款"],"h1":"它是一个整数，有三位数。","h2":"在 New Jersey，违反分级驾照的规定，比如没贴规定的贴纸开车，可能被罚 $100。","p":"对。没贴贴纸可能被罚 $100。"},"vi":{"q":"Ở New Jersey, người có giấy phép tập lái hoặc người lái xe tạm thời dưới 21 tuổi lái xe mà không có miếng dán bắt buộc sẽ bị phạt bao nhiêu?","o":["$25","$100","$500","Không bị phạt"],"h1":"Đó là một số tròn có ba chữ số.","h2":"Ở New Jersey, vi phạm luật bằng lái theo từng giai đoạn, chẳng hạn như lái xe không có miếng dán bắt buộc, có thể bị phạt $100.","p":"Đúng. Thiếu miếng dán có thể bị phạt $100."},"tl":{"q":"Sa New Jersey, magkano ang multa para sa may permit o probationary driver na wala pang 21 taong gulang na nagmamaneho nang walang kailangang decal?","o":["$25","$100","$500","Walang multa"],"h1":"Ito ay buong numero na may tatlong digit.","h2":"Sa New Jersey, ang paglabag sa patakaran ng graduated license, gaya ng pagmamaneho nang walang kailangang decal, ay puwedeng magresulta sa multang $100.","p":"Tama. Ang kulang na decal ay puwedeng magkahalaga ng $100."},"ar":{"q":"في New Jersey، ما الغرامة على حامل التصريح أو السائق تحت الاختبار الذي عمره أقل من 21 سنة إذا قاد دون الملصقات المطلوبة؟","o":["$25","$100","$500","لا توجد غرامة"],"h1":"إنه رقم مستدير من ثلاث خانات.","h2":"في New Jersey، مخالفة قواعد الرخصة المتدرجة، مثل القيادة دون الملصقات المطلوبة، قد تؤدي إلى غرامة قدرها $100.","p":"صحيح. غياب الملصقات قد يكلّف $100."},"ref":{"doc":"NJ","page":14}},{"id":"nj-014","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, what is the fine range for a first offense of using a hand-held phone while driving?","o":["$25 to $50","$50 to $100","$1,000 to $2,000","$200 to $400"],"h1":"It starts at two hundred dollars.","h2":"A first offense for using a hand-held phone while driving in New Jersey carries a fine of $200 to $400.","p":"Right. A first offense costs $200 to $400."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por una primera vez de usar el teléfono en la mano mientras maneja?","o":["$25 a $50","$50 a $100","$1,000 a $2,000","$200 a $400"],"h1":"Empieza en doscientos dólares.","h2":"Una primera infracción por usar el teléfono en la mano mientras maneja en New Jersey tiene una multa de $200 a $400.","p":"Correcto. Una primera infracción cuesta de $200 a $400."},"zh":{"q":"在 New Jersey，第一次因为开车时用手持手机被抓，罚款范围是多少？","o":["$25 到 $50","$50 到 $100","$1,000 到 $2,000","$200 到 $400"],"h1":"它从两百美元开始。","h2":"在 New Jersey，第一次因为开车时用手持手机被抓，罚款 $200 到 $400。","p":"对。第一次罚 $200 到 $400。"},"vi":{"q":"Ở New Jersey, mức phạt cho lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe là bao nhiêu?","o":["$25 đến $50","$50 đến $100","$1,000 đến $2,000","$200 đến $400"],"h1":"Bắt đầu từ hai trăm đô la.","h2":"Ở New Jersey, lần vi phạm đầu tiên vì dùng điện thoại cầm tay khi lái xe bị phạt từ $200 đến $400.","p":"Đúng. Lần vi phạm đầu tiên bị phạt $200 đến $400."},"tl":{"q":"Sa New Jersey, magkano ang multa sa unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho?","o":["$25 hanggang $50","$50 hanggang $100","$1,000 hanggang $2,000","$200 hanggang $400"],"h1":"Nagsisimula ito sa dalawang daang dolyar.","h2":"Ang unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho sa New Jersey ay may multang $200 hanggang $400.","p":"Tama. Ang unang paglabag ay $200 hanggang $400."},"ar":{"q":"في New Jersey، ما مقدار الغرامة على المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة؟","o":["من $25 إلى $50","من $50 إلى $100","من $1,000 إلى $2,000","من $200 إلى $400"],"h1":"تبدأ من مئتي دولار.","h2":"في New Jersey، المخالفة الأولى لاستخدام هاتف محمول باليد أثناء القيادة عليها غرامة من $200 إلى $400.","p":"صحيح. المخالفة الأولى تكلّف من $200 إلى $400."},"ref":{"doc":"NJ","page":86}},{"id":"nj-015","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you are on the opposite side of a highway divided by a raised median from a stopped school bus. What must you do?","o":["Stop until the bus moves","Keep your normal speed","Slow to no more than 10 mph while passing","Honk and pass"],"h1":"You do not have to stop, but you must go very slowly.","h2":"In New Jersey, if a safety island or raised median separates you from a stopped school bus on the other side, you must slow to no more than 10 miles per hour while passing.","p":"Right. Slow to 10 mph or less."},"es":{"q":"En New Jersey, usted va por el lado opuesto de una carretera dividida por un camellón elevado y hay un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Mantener su velocidad normal","Bajar a no más de 10 mph al pasar","Tocar el claxon y pasar"],"h1":"No tiene que detenerse, pero debe ir muy despacio.","h2":"En New Jersey, si una isla de seguridad o un camellón elevado lo separa de un autobús escolar detenido del otro lado, usted debe bajar a no más de 10 millas por hora al pasar.","p":"Correcto. Baje a 10 mph o menos."},"zh":{"q":"在 New Jersey，你在一条有凸起中间隔离带的公路上，校车停在对面。你必须怎么做？","o":["停车，等到校车开走","保持正常速度","经过时减速到不超过 10 mph","按喇叭然后超过去"],"h1":"你不用停车，但必须开得很慢。","h2":"在 New Jersey，如果安全岛或凸起的中间隔离带把你和对面停着的校车分开，你经过时必须减速到每小时不超过 10 英里。","p":"对。减速到 10 mph 或更低。"},"vi":{"q":"Ở New Jersey, bạn đang ở phía bên kia của một xa lộ có dải phân cách nhô cao, đối diện một xe buýt trường học đang dừng. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Giữ tốc độ bình thường","Chạy chậm lại không quá 10 mph khi đi qua","Bấm còi rồi chạy qua"],"h1":"Bạn không phải dừng, nhưng phải chạy thật chậm.","h2":"Ở New Jersey, nếu có đảo an toàn hoặc dải phân cách nhô cao ngăn cách bạn với xe buýt trường học đang dừng ở phía bên kia, bạn phải chạy chậm lại không quá 10 dặm một giờ khi đi qua.","p":"Đúng. Chạy chậm lại 10 mph hoặc thấp hơn."},"tl":{"q":"Sa New Jersey, nasa kabilang panig ka ng highway na hinahati ng nakataas na median mula sa isang nakahintong school bus. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Panatilihin ang karaniwang bilis","Bumagal sa hindi hihigit sa 10 mph habang dumadaan","Bumusina at lumampas"],"h1":"Hindi mo kailangang huminto, pero dapat napakabagal mo.","h2":"Sa New Jersey, kung may safety island o nakataas na median na naghihiwalay sa iyo at sa nakahintong school bus sa kabilang panig, dapat kang bumagal sa hindi hihigit sa 10 milya kada oras habang dumadaan.","p":"Tama. Bumagal sa 10 mph o mas mababa."},"ar":{"q":"في New Jersey، أنت على الجانب المقابل لطريق سريع مقسوم بفاصل مرتفع، وفي الجانب الآخر حافلة مدرسية متوقفة. ماذا يجب أن تفعل؟","o":["تتوقف حتى تتحرك الحافلة","تحافظ على سرعتك العادية","تُبطئ إلى 10 mph أو أقل أثناء المرور","تستخدم البوق وتمرّ"],"h1":"ليس عليك أن تتوقف، لكن يجب أن تسير ببطء شديد.","h2":"في New Jersey، إذا كانت جزيرة أمان أو فاصل مرتفع يفصلك عن حافلة مدرسية متوقفة في الجانب الآخر، يجب أن تُبطئ إلى 10 أميال في الساعة أو أقل أثناء المرور.","p":"صحيح. أبطئ إلى 10 mph أو أقل."},"ref":{"doc":"NJ","page":77}},{"id":"nj-016","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, when may you drive in the left lane of a multi-lane highway?","o":["When passing or turning left","Whenever you like","Only at night","Only when going the speed limit"],"h1":"New Jersey has a keep right law.","h2":"New Jersey law says to keep to the right lane and use the left lane only to pass another vehicle or to turn left.","p":"Right. Keep right, and pass on the left."},"es":{"q":"En New Jersey, ¿cuándo puede manejar en el carril izquierdo de una carretera de varios carriles?","o":["Cuando rebasa o va a dar vuelta a la izquierda","Siempre que quiera","Solo de noche","Solo si va al límite de velocidad"],"h1":"New Jersey tiene una ley de mantenerse a la derecha.","h2":"La ley de New Jersey dice que debe mantenerse en el carril derecho y usar el carril izquierdo solo para rebasar a otro vehículo o para dar vuelta a la izquierda.","p":"Correcto. Manténgase a la derecha y rebase por la izquierda."},"zh":{"q":"在 New Jersey，在多车道的公路上，什么时候可以走左车道？","o":["超车或左转时","想走就走","只在晚上","只在开到限速时"],"h1":"New Jersey 有靠右行驶的法律。","h2":"New Jersey 法律规定要走右车道，只有超车或左转时才走左车道。","p":"对。靠右行驶，从左边超车。"},"vi":{"q":"Ở New Jersey, khi nào bạn được lái xe ở làn bên trái của xa lộ có nhiều làn?","o":["Khi vượt xe hoặc khi rẽ trái","Bất cứ khi nào bạn muốn","Chỉ vào ban đêm","Chỉ khi chạy đúng tốc độ giới hạn"],"h1":"New Jersey có luật đi bên phải (keep right law).","h2":"Luật New Jersey nói phải đi ở làn bên phải và chỉ dùng làn bên trái để vượt xe khác hoặc để rẽ trái.","p":"Đúng. Đi bên phải, và vượt bên trái."},"tl":{"q":"Sa New Jersey, kailan ka puwedeng magmaneho sa kaliwang lane ng highway na maraming lane?","o":["Kapag lumalampas o kumakaliwa","Kahit kailan mo gusto","Sa gabi lamang","Kapag nasa speed limit lamang"],"h1":"May keep right law ang New Jersey.","h2":"Sinasabi ng batas ng New Jersey na manatili sa kanang lane at gamitin ang kaliwang lane para lamang lumampas sa ibang sasakyan o para kumaliwa.","p":"Tama. Manatili sa kanan, at lumampas sa kaliwa."},"ar":{"q":"في New Jersey، متى يجوز لك أن تقود في المسار الأيسر لطريق سريع متعدد المسارات؟","o":["عند التجاوز أو الانعطاف يسارًا","في أي وقت تريده","في الليل فقط","فقط عند السير بالسرعة القصوى المسموحة"],"h1":"في New Jersey قانون البقاء في اليمين (keep right law).","h2":"قانون New Jersey يقول أن تبقى في المسار الأيمن وأن تستخدم المسار الأيسر فقط لتجاوز مركبة أخرى أو للانعطاف يسارًا.","p":"صحيح. ابقَ في اليمين، وتجاوز من اليسار."},"ref":{"doc":"NJ","page":65}},{"id":"nj-017","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine range for breaking the Move Over law?","o":["$25 to $50","$100 to $500","$1,000 to $5,000","There is only a warning"],"h1":"It starts at one hundred dollars.","h2":"Breaking the New Jersey Move Over law carries a fine of $100 to $500.","p":"Right. The fine is $100 to $500."},"es":{"q":"En New Jersey, ¿cuál es el rango de la multa por no cumplir la ley de \"Move Over\" (cambie de carril)?","o":["$25 a $50","$100 a $500","$1,000 a $5,000","Solo hay una advertencia"],"h1":"Empieza en cien dólares.","h2":"No cumplir la ley de \"Move Over\" en New Jersey tiene una multa de $100 a $500.","p":"Correcto. La multa es de $100 a $500."},"zh":{"q":"在 New Jersey，违反让道变道法（Move Over law）罚款范围是多少？","o":["$25 到 $50","$100 到 $500","$1,000 到 $5,000","只会警告"],"h1":"它从一百美元开始。","h2":"违反 New Jersey 的让道变道法（Move Over law），罚款 $100 到 $500。","p":"对。罚款是 $100 到 $500。"},"vi":{"q":"Ở New Jersey, mức phạt khi vi phạm luật Nhường Làn (Move Over law) là bao nhiêu?","o":["$25 đến $50","$100 đến $500","$1,000 đến $5,000","Chỉ bị cảnh cáo"],"h1":"Bắt đầu từ một trăm đô la.","h2":"Vi phạm luật Nhường Làn (Move Over law) của New Jersey bị phạt từ $100 đến $500.","p":"Đúng. Mức phạt là $100 đến $500."},"tl":{"q":"Sa New Jersey, magkano ang multa sa paglabag sa Move Over law?","o":["$25 hanggang $50","$100 hanggang $500","$1,000 hanggang $5,000","Babala lamang"],"h1":"Nagsisimula ito sa isang daang dolyar.","h2":"Ang paglabag sa Move Over law ng New Jersey ay may multang $100 hanggang $500.","p":"Tama. Ang multa ay $100 hanggang $500."},"ar":{"q":"في New Jersey، ما مقدار الغرامة على مخالفة قانون الابتعاد عن المركبات المتوقفة (Move Over law)؟","o":["من $25 إلى $50","من $100 إلى $500","من $1,000 إلى $5,000","يوجد تحذير فقط"],"h1":"تبدأ من مئة دولار.","h2":"مخالفة قانون الابتعاد عن المركبات المتوقفة (Move Over law) في New Jersey عليها غرامة من $100 إلى $500.","p":"صحيح. الغرامة من $100 إلى $500."},"ref":{"doc":"NJ","page":78}},{"id":"nj-018","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, besides emergency, tow and road crew vehicles, what else does the Move Over law cover?","o":["Only parked school buses","Only police on foot","Nothing else","Disabled vehicles with their hazard lights on"],"h1":"A car with flashing hazard lights on the shoulder counts too.","h2":"The New Jersey Move Over law now also covers disabled vehicles that have their hazard lights on.","p":"Right. Disabled cars with hazard lights are covered."},"es":{"q":"En New Jersey, además de vehículos de emergencia, grúas y cuadrillas de carretera, ¿qué más cubre la ley de \"Move Over\"?","o":["Solo autobuses escolares estacionados","Solo policías a pie","Nada más","Vehículos descompuestos con las luces intermitentes encendidas"],"h1":"Un carro en el acotamiento con luces intermitentes también cuenta.","h2":"La ley de \"Move Over\" de New Jersey ahora también cubre vehículos descompuestos que tienen las luces intermitentes encendidas.","p":"Correcto. Los carros descompuestos con luces intermitentes están cubiertos."},"zh":{"q":"在 New Jersey，除了紧急车辆、拖车和道路工程车，让道变道法（Move Over law）还包括什么？","o":["只有停着的校车","只有步行的警察","没有别的","开着危险警示灯的故障车"],"h1":"路肩上闪着危险警示灯的车也算。","h2":"New Jersey 的让道变道法（Move Over law）现在也包括开着危险警示灯的故障车。","p":"对。开着危险警示灯的故障车也包括在内。"},"vi":{"q":"Ở New Jersey, ngoài xe khẩn cấp, xe kéo và xe của đội làm đường, luật Nhường Làn (Move Over law) còn áp dụng cho gì nữa?","o":["Chỉ xe buýt trường học đang đậu","Chỉ cảnh sát đi bộ","Không gì khác","Xe bị hư đang bật đèn cảnh báo nguy hiểm (hazard lights)"],"h1":"Một xe hơi nháy đèn cảnh báo nguy hiểm bên lề đường cũng được tính.","h2":"Luật Nhường Làn (Move Over law) của New Jersey nay cũng áp dụng cho xe bị hư đang bật đèn cảnh báo nguy hiểm.","p":"Đúng. Xe bị hư có bật đèn cảnh báo cũng được bảo vệ."},"tl":{"q":"Sa New Jersey, bukod sa mga emergency vehicle, tow truck at sasakyan ng road crew, ano pa ang sakop ng Move Over law?","o":["Mga nakaparadang school bus lamang","Mga pulis na naglalakad lamang","Wala nang iba","Mga sirang sasakyan na nakabukas ang hazard lights"],"h1":"Kasama rin ang kotse sa gilid ng daan na kumikislap ang hazard lights.","h2":"Sakop na rin ng Move Over law ng New Jersey ang mga sirang sasakyan na nakabukas ang hazard lights.","p":"Tama. Sakop ang mga sirang kotse na may hazard lights."},"ar":{"q":"في New Jersey، إلى جانب مركبات الطوارئ وشاحنات السحب ومركبات عمّال الطرق، ماذا يشمل أيضًا قانون الابتعاد عن المركبات المتوقفة (Move Over law)؟","o":["الحافلات المدرسية المتوقفة فقط","الشرطة الذين يسيرون على الأقدام فقط","لا شيء آخر","المركبات المعطّلة التي أضواء التحذير (hazard lights) فيها مشتعلة"],"h1":"السيارة على جانب الطريق التي تومض أضواء التحذير فيها تُحسب أيضًا.","h2":"قانون الابتعاد عن المركبات المتوقفة (Move Over law) في New Jersey يشمل الآن أيضًا المركبات المعطّلة التي أضواء التحذير فيها مشتعلة.","p":"صحيح. السيارات المعطّلة ذات أضواء التحذير مشمولة."},"ref":{"doc":"NJ","page":78}},{"id":"nj-019","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you pass a person walking or biking on the road and cannot change lanes or leave 4 feet. What must you do?","o":["Honk and pass quickly","Pass at the posted speed","Slow to 25 mph and be ready to stop","Stop and wait for them to leave the road"],"h1":"There is a set speed for this case.","h2":"In New Jersey, if you cannot change lanes or leave 4 feet when passing a pedestrian or bicyclist, you must slow to 25 miles per hour and be ready to stop.","p":"Right. Slow to 25 mph and be ready to stop."},"es":{"q":"En New Jersey, usted va a rebasar a una persona que camina o va en bicicleta por la calle y no puede cambiar de carril ni dejar 4 pies. ¿Qué debe hacer?","o":["Tocar el claxon y pasar rápido","Pasar al límite de velocidad","Bajar a 25 mph y estar listo para detenerse","Detenerse y esperar a que salga de la calle"],"h1":"Hay una velocidad fija para este caso.","h2":"En New Jersey, si no puede cambiar de carril ni dejar 4 pies al rebasar a un peatón o ciclista, debe bajar a 25 millas por hora y estar listo para detenerse.","p":"Correcto. Baje a 25 mph y esté listo para detenerse."},"zh":{"q":"在 New Jersey，你要经过路上走路或骑自行车的人，但不能换车道，也不能留出 4 英尺。你必须怎么做？","o":["按喇叭然后快速超过去","按标示的限速超过去","减速到 25 mph，并准备好停车","停车，等他们离开道路"],"h1":"这种情况有规定的速度。","h2":"在 New Jersey，经过行人或骑自行车的人时，如果不能换车道或留出 4 英尺，你必须减速到每小时 25 英里，并准备好停车。","p":"对。减速到 25 mph，并准备好停车。"},"vi":{"q":"Ở New Jersey, bạn đang vượt qua một người đi bộ hoặc đi xe đạp trên đường và không thể chuyển làn hoặc chừa khoảng cách 4 feet. Bạn phải làm gì?","o":["Bấm còi và vượt qua thật nhanh","Vượt qua với tốc độ giới hạn được ghi","Chạy chậm lại 25 mph và sẵn sàng dừng lại","Dừng lại và chờ họ rời khỏi đường"],"h1":"Có một tốc độ quy định cho trường hợp này.","h2":"Ở New Jersey, nếu bạn không thể chuyển làn hoặc chừa 4 feet khi vượt qua người đi bộ hoặc người đi xe đạp, bạn phải chạy chậm lại 25 dặm một giờ và sẵn sàng dừng lại.","p":"Đúng. Chạy chậm lại 25 mph và sẵn sàng dừng lại."},"tl":{"q":"Sa New Jersey, nilalampasan mo ang taong naglalakad o nagbibisikleta sa daan at hindi ka makalipat ng lane o makapag-iwan ng 4 feet. Ano ang dapat mong gawin?","o":["Bumusina at lumampas nang mabilis","Lumampas sa nakapaskil na bilis","Bumagal sa 25 mph at maging handang huminto","Huminto at hintayin silang umalis sa daan"],"h1":"May takdang bilis para sa ganitong kaso.","h2":"Sa New Jersey, kung hindi ka makalipat ng lane o makapag-iwan ng 4 feet kapag nilalampasan mo ang naglalakad o nagbibisikleta, dapat kang bumagal sa 25 milya kada oras at maging handang huminto.","p":"Tama. Bumagal sa 25 mph at maging handang huminto."},"ar":{"q":"في New Jersey، أنت تتجاوز شخصًا يمشي أو يركب دراجة على الطريق، ولا تستطيع تغيير المسار أو ترك مسافة 4 feet. ماذا يجب أن تفعل؟","o":["تستخدم البوق وتتجاوز بسرعة","تتجاوز بالسرعة المكتوبة على اللافتة","تُبطئ إلى 25 mph وتكون مستعدًا للتوقف","تتوقف وتنتظر حتى يتركوا الطريق"],"h1":"توجد سرعة محددة لهذه الحالة.","h2":"في New Jersey، إذا لم تستطع تغيير المسار أو ترك مسافة 4 feet عند تجاوز شخص يمشي أو يركب دراجة، يجب أن تُبطئ إلى 25 ميلًا في الساعة وتكون مستعدًا للتوقف.","p":"صحيح. أبطئ إلى 25 mph وكن مستعدًا للتوقف."},"ref":{"doc":"NJ","page":150}},{"id":"nj-020","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, at what blood alcohol level can a driver under 21 be charged?","o":["0.01","0.05","0.08","0.10"],"h1":"Even a very small amount counts.","h2":"New Jersey has zero tolerance for drivers under 21, so a blood alcohol level of just 0.01 can lead to a charge.","p":"Right. Under 21, 0.01 is already too much."},"es":{"q":"En New Jersey, ¿con qué nivel de alcohol en la sangre se puede acusar a un conductor menor de 21 años?","o":["0.01","0.05","0.08","0.10"],"h1":"Incluso una cantidad muy pequeña cuenta.","h2":"New Jersey tiene tolerancia cero para conductores menores de 21 años, así que un nivel de alcohol en la sangre de apenas 0.01 puede llevar a una acusación.","p":"Correcto. Menor de 21, 0.01 ya es demasiado."},"zh":{"q":"在 New Jersey，未满 21 岁的司机血液酒精浓度到多少就可能被起诉？","o":["0.01","0.05","0.08","0.10"],"h1":"就算很少的量也算。","h2":"New Jersey 对未满 21 岁的司机零容忍，所以血液酒精浓度只有 0.01 也可能被起诉。","p":"对。未满 21 岁，0.01 就已经太多了。"},"vi":{"q":"Ở New Jersey, người lái xe dưới 21 tuổi có thể bị buộc tội khi nồng độ cồn trong máu ở mức nào?","o":["0.01","0.05","0.08","0.10"],"h1":"Ngay cả một lượng rất nhỏ cũng bị tính.","h2":"New Jersey không khoan nhượng với người lái xe dưới 21 tuổi, nên nồng độ cồn trong máu chỉ 0.01 cũng có thể bị buộc tội.","p":"Đúng. Dưới 21 tuổi, 0.01 đã là quá nhiều."},"tl":{"q":"Sa New Jersey, sa anong blood alcohol level puwedeng kasuhan ang driver na wala pang 21 taong gulang?","o":["0.01","0.05","0.08","0.10"],"h1":"Kahit napakaliit na dami ay binibilang.","h2":"May zero tolerance ang New Jersey para sa mga driver na wala pang 21 taong gulang, kaya ang blood alcohol level na 0.01 lamang ay puwedeng humantong sa kaso.","p":"Tama. Kung wala pang 21, sobra na ang 0.01."},"ar":{"q":"في New Jersey، عند أي نسبة كحول في الدم يمكن توجيه تهمة إلى سائق عمره أقل من 21 سنة؟","o":["0.01","0.05","0.08","0.10"],"h1":"حتى كمية صغيرة جدًا تُحسب.","h2":"في New Jersey لا تسامح أبدًا مع السائقين الذين أعمارهم أقل من 21 سنة، لذلك فإن نسبة كحول في الدم قدرها 0.01 فقط قد تؤدي إلى توجيه تهمة.","p":"صحيح. تحت 21 سنة، نسبة 0.01 كثيرة جدًا بالفعل."},"ref":{"doc":"NJ","page":115}},{"id":"nj-021","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, what is the speed limit on a rural road with no posted limit?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"It is lower than the limit on most interstates.","h2":"In New Jersey, the speed limit on a rural road with no speed limit sign is 50 mph.","p":"Right. Unposted rural roads have a 50 mph limit."},"es":{"q":"En New Jersey, ¿cuál es el límite de velocidad en una carretera rural sin límite señalizado?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Es más bajo que el límite de la mayoría de las autopistas interestatales.","h2":"En New Jersey, el límite de velocidad en una carretera rural sin señal de límite es de 50 mph.","p":"Correcto. Las carreteras rurales sin señal tienen un límite de 50 mph."},"zh":{"q":"在 New Jersey，没有限速标志的乡村道路限速是多少？","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"它比大多数州际公路的限速低。","h2":"在 New Jersey，没有限速标志的乡村道路限速是 50 mph。","p":"对。没有限速标志的乡村道路限速是 50 mph。"},"vi":{"q":"Ở New Jersey, tốc độ tối đa trên đường nông thôn không có biển báo tốc độ là bao nhiêu?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Nó thấp hơn tốc độ tối đa trên hầu hết các xa lộ liên bang.","h2":"Ở New Jersey, tốc độ tối đa trên đường nông thôn không có biển báo tốc độ là 50 mph.","p":"Đúng. Đường nông thôn không có biển báo có tốc độ tối đa 50 mph."},"tl":{"q":"Sa New Jersey, ano ang speed limit sa daan sa probinsya na walang nakapaskil na limit?","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"Mas mababa ito kaysa sa limit sa karamihan ng interstate.","h2":"Sa New Jersey, ang speed limit sa daan sa probinsya na walang speed limit sign ay 50 mph.","p":"Tama. 50 mph ang limit sa daan sa probinsya na walang nakapaskil na limit."},"ar":{"q":"في New Jersey، ما حد السرعة على طريق ريفي لا توجد عليه لافتة لحد السرعة؟","o":["35 mph","45 mph","50 mph","65 mph"],"h1":"إنه أقل من حد السرعة على معظم الطرق السريعة بين الولايات.","h2":"في New Jersey، حد السرعة على طريق ريفي لا توجد عليه لافتة لحد السرعة هو 50 mph.","p":"صحيح. حد السرعة على الطرق الريفية التي لا توجد عليها لافتة هو 50 mph."},"ref":{"doc":"NJ","page":62}},{"id":"nj-022","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you must turn on your headlights when you can see only how far ahead?","o":["500 feet or less","1,000 feet or less","200 feet or less","1 mile or less"],"h1":"It is about the length of one and a half football fields.","h2":"In New Jersey, you must use your headlights when you can see 500 feet or less ahead.","p":"Right. Headlights go on when you can see 500 feet or less."},"es":{"q":"En New Jersey, ¿debe encender las luces delanteras cuando solo puede ver hasta qué distancia?","o":["500 pies o menos","1,000 pies o menos","200 pies o menos","1 milla o menos"],"h1":"Es como un campo de fútbol americano y medio.","h2":"En New Jersey, usted debe usar las luces delanteras cuando puede ver 500 pies o menos hacia adelante.","p":"Correcto. Las luces se encienden cuando se ve a 500 pies o menos."},"zh":{"q":"在 New Jersey，当你只能看到前方多远时，必须打开车头灯？","o":["500 英尺或更短","1,000 英尺或更短","200 英尺或更短","1 英里或更短"],"h1":"大约是一个半足球场的长度。","h2":"在 New Jersey，当你只能看到前方 500 英尺或更短时，必须打开车头灯。","p":"对。能看到的距离只有 500 英尺或更短时，要打开车头灯。"},"vi":{"q":"Ở New Jersey, bạn phải bật đèn pha khi bạn chỉ nhìn thấy phía trước bao xa?","o":["500 feet hoặc ít hơn","1,000 feet hoặc ít hơn","200 feet hoặc ít hơn","1 dặm hoặc ít hơn"],"h1":"Nó dài khoảng một sân bóng bầu dục rưỡi.","h2":"Ở New Jersey, bạn phải bật đèn pha khi bạn chỉ nhìn thấy phía trước 500 feet hoặc ít hơn.","p":"Đúng. Bật đèn pha khi bạn chỉ nhìn thấy 500 feet hoặc ít hơn."},"tl":{"q":"Sa New Jersey, kailangan mong buksan ang headlights kapag gaano kalayo lang ang nakikita mo sa unahan?","o":["500 feet o mas maikli","1,000 feet o mas maikli","200 feet o mas maikli","1 milya o mas maikli"],"h1":"Mga isa't kalahating haba ng football field ito.","h2":"Sa New Jersey, kailangan mong gamitin ang headlights kapag 500 feet o mas maikli lang ang nakikita mo sa unahan.","p":"Tama. Buksan ang headlights kapag 500 feet o mas maikli lang ang nakikita mo."},"ar":{"q":"في New Jersey، يجب أن تشغّل المصابيح الأمامية عندما لا ترى أمامك إلا إلى أي مسافة؟","o":["500 قدم أو أقل","1,000 قدم أو أقل","200 قدم أو أقل","1 ميل أو أقل"],"h1":"إنها تقريبًا طول ملعب كرة قدم ونصف.","h2":"في New Jersey، يجب أن تستخدم المصابيح الأمامية عندما لا ترى أمامك إلا 500 قدم أو أقل.","p":"صحيح. شغّل المصابيح الأمامية عندما لا ترى إلا 500 قدم أو أقل."},"ref":{"doc":"NJ","page":83}},{"id":"nj-023","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a child is 6 years old and 50 inches tall. Where and how must the child ride?","o":["In the front seat with a seat belt","In any seat with only a lap belt","On an adult's lap in the back seat","In a rear seat, in a booster seat or harness car seat"],"h1":"Think of children under 8 who are shorter than 57 inches.","h2":"In New Jersey, a child under 8 who is shorter than 57 inches must ride in a rear seat in a booster seat or a car seat with a harness.","p":"Right. Under 8 and under 57 inches means a booster or harness seat in the back."},"es":{"q":"En New Jersey, un niño tiene 6 años y mide 50 pulgadas. ¿Dónde y cómo debe viajar?","o":["En el asiento delantero con cinturón","En cualquier asiento con solo el cinturón de cadera","En las piernas de un adulto en el asiento trasero","En un asiento trasero, en un asiento elevado o una silla con arnés"],"h1":"Piense en los niños menores de 8 años que miden menos de 57 pulgadas.","h2":"En New Jersey, un niño menor de 8 años que mide menos de 57 pulgadas debe viajar en un asiento trasero, en un asiento elevado o en una silla con arnés.","p":"Correcto. Menor de 8 años y de menos de 57 pulgadas: asiento elevado o silla con arnés atrás."},"zh":{"q":"在 New Jersey，一个孩子 6 岁，身高 50 英寸。这个孩子必须坐在哪里、怎样坐？","o":["坐前排，系安全带","坐任何座位，只系腰部安全带","在后排坐在大人腿上","坐后排，用增高座椅或带安全背带的儿童座椅"],"h1":"想一想不到 8 岁、身高不到 57 英寸的孩子。","h2":"在 New Jersey，不到 8 岁、身高不到 57 英寸的孩子必须坐在后排，使用增高座椅或带安全背带的儿童座椅。","p":"对。不到 8 岁、身高不到 57 英寸，就要在后排用增高座椅或带背带的座椅。"},"vi":{"q":"Ở New Jersey, một em bé 6 tuổi và cao 50 inch. Em phải ngồi ở đâu và ngồi như thế nào?","o":["Ngồi ghế trước, thắt dây an toàn","Ngồi ghế nào cũng được, chỉ với dây an toàn ngang hông","Ngồi trên đùi người lớn ở ghế sau","Ngồi ghế sau, trong ghế nâng (booster seat) hoặc ghế xe có dây đai"],"h1":"Hãy nghĩ đến trẻ dưới 8 tuổi và thấp hơn 57 inch.","h2":"Ở New Jersey, trẻ dưới 8 tuổi và thấp hơn 57 inch phải ngồi ở ghế sau, trong ghế nâng hoặc ghế xe có dây đai.","p":"Đúng. Dưới 8 tuổi và thấp hơn 57 inch thì phải ngồi ghế nâng hoặc ghế có dây đai ở phía sau."},"tl":{"q":"Sa New Jersey, ang isang bata ay 6 na taong gulang at 50 inches ang taas. Saan at paano dapat sumakay ang bata?","o":["Sa upuan sa harap, may seat belt","Sa kahit anong upuan, lap belt lang","Nakakandong sa matanda sa upuan sa likod","Sa upuan sa likod, sa booster seat o car seat na may harness"],"h1":"Isipin ang mga batang wala pang 8 taon na mas maikli sa 57 inches.","h2":"Sa New Jersey, ang batang wala pang 8 taon na mas maikli sa 57 inches ay dapat sumakay sa upuan sa likod, sa booster seat o car seat na may harness.","p":"Tama. Kapag wala pang 8 taon at mas maikli sa 57 inches, booster o harness seat sa likod."},"ar":{"q":"في New Jersey، طفل عمره 6 سنوات وطوله 50 بوصة. أين وكيف يجب أن يجلس؟","o":["في المقعد الأمامي مع حزام الأمان","في أي مقعد مع حزام الحِجر فقط","في حضن شخص بالغ في المقعد الخلفي","في مقعد خلفي، في مقعد رافع (booster seat) أو مقعد سيارة بأحزمة"],"h1":"فكّر في الأطفال الذين عمرهم أقل من 8 سنوات وطولهم أقل من 57 بوصة.","h2":"في New Jersey، الطفل الذي عمره أقل من 8 سنوات وطوله أقل من 57 بوصة يجب أن يجلس في مقعد خلفي، في مقعد رافع أو مقعد سيارة بأحزمة.","p":"صحيح. أقل من 8 سنوات وأقل من 57 بوصة يعني مقعدًا رافعًا أو مقعدًا بأحزمة في الخلف."},"ref":{"doc":"NJ","page":42}},{"id":"nj-024","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for breaking the child passenger safety law?","o":["$10 to $25","$50 to $75","$200 to $400","$500 to $1,000"],"h1":"It is less than one hundred dollars, plus court costs.","h2":"In New Jersey, breaking the child car seat law can bring a fine of $50 to $75, plus fees and court costs.","p":"Right. The fine is $50 to $75, plus costs."},"es":{"q":"En New Jersey, ¿cuál es la multa por no cumplir la ley de seguridad de pasajeros infantiles?","o":["De $10 a $25","De $50 a $75","De $200 a $400","De $500 a $1,000"],"h1":"Es menos de cien dólares, más los costos del tribunal.","h2":"En New Jersey, no cumplir la ley de asientos de seguridad para niños puede costar una multa de $50 a $75, más cargos y costos del tribunal.","p":"Correcto. La multa es de $50 a $75, más los costos."},"zh":{"q":"在 New Jersey，违反儿童乘车安全法的罚款是多少？","o":["$10 到 $25","$50 到 $75","$200 到 $400","$500 到 $1,000"],"h1":"不到一百美元，另加法院费用。","h2":"在 New Jersey，违反儿童安全座椅法可被罚款 $50 到 $75，另加手续费和法院费用。","p":"对。罚款是 $50 到 $75，另加费用。"},"vi":{"q":"Ở New Jersey, tiền phạt khi vi phạm luật an toàn cho trẻ em đi xe là bao nhiêu?","o":["$10 đến $25","$50 đến $75","$200 đến $400","$500 đến $1,000"],"h1":"Nó dưới một trăm đô la, cộng thêm án phí.","h2":"Ở New Jersey, vi phạm luật ghế xe cho trẻ em có thể bị phạt $50 đến $75, cộng thêm lệ phí và án phí.","p":"Đúng. Tiền phạt là $50 đến $75, cộng thêm các khoản phí."},"tl":{"q":"Sa New Jersey, magkano ang multa sa paglabag sa batas sa kaligtasan ng batang pasahero?","o":["$10 hanggang $25","$50 hanggang $75","$200 hanggang $400","$500 hanggang $1,000"],"h1":"Mas mababa ito sa isang daang dolyar, dagdag ang gastos sa korte.","h2":"Sa New Jersey, ang paglabag sa batas sa car seat ng bata ay may multang $50 hanggang $75, dagdag ang mga bayarin at gastos sa korte.","p":"Tama. $50 hanggang $75 ang multa, dagdag ang mga gastos."},"ar":{"q":"في New Jersey، ما الغرامة على مخالفة قانون سلامة الأطفال الركاب؟","o":["من $10 إلى $25","من $50 إلى $75","من $200 إلى $400","من $500 إلى $1,000"],"h1":"إنها أقل من مئة دولار، بالإضافة إلى رسوم المحكمة.","h2":"في New Jersey، مخالفة قانون مقعد الطفل في السيارة قد تؤدي إلى غرامة من $50 إلى $75، بالإضافة إلى الرسوم وتكاليف المحكمة.","p":"صحيح. الغرامة من $50 إلى $75، بالإضافة إلى التكاليف."},"ref":{"doc":"NJ","page":43}},{"id":"nj-025","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, who is responsible when a passenger under 18 does not wear a seat belt?","o":["The driver","The passenger","The car's owner","The passenger's parent, even if not in the car"],"h1":"Think of the person behind the wheel.","h2":"In New Jersey, the driver is responsible for making sure every passenger under 18 wears a seat belt.","p":"Right. The driver answers for passengers under 18."},"es":{"q":"En New Jersey, ¿quién es responsable cuando un pasajero menor de 18 años no usa el cinturón de seguridad?","o":["El conductor","El pasajero","El dueño del auto","El padre o la madre del pasajero, aunque no esté en el auto"],"h1":"Piense en la persona que va al volante.","h2":"En New Jersey, el conductor es responsable de que cada pasajero menor de 18 años use el cinturón de seguridad.","p":"Correcto. El conductor responde por los pasajeros menores de 18 años."},"zh":{"q":"在 New Jersey，未满 18 岁的乘客没有系安全带时，由谁负责？","o":["司机","乘客","车主","乘客的父母，即使他们不在车上"],"h1":"想一想握方向盘的人。","h2":"在 New Jersey，司机有责任确保每位未满 18 岁的乘客都系好安全带。","p":"对。司机要为未满 18 岁的乘客负责。"},"vi":{"q":"Ở New Jersey, ai chịu trách nhiệm khi một hành khách dưới 18 tuổi không thắt dây an toàn?","o":["Người lái xe","Hành khách","Chủ xe","Cha mẹ của hành khách, dù không ở trong xe"],"h1":"Hãy nghĩ đến người cầm vô lăng.","h2":"Ở New Jersey, người lái xe có trách nhiệm bảo đảm mọi hành khách dưới 18 tuổi đều thắt dây an toàn.","p":"Đúng. Người lái xe chịu trách nhiệm cho hành khách dưới 18 tuổi."},"tl":{"q":"Sa New Jersey, sino ang mananagot kapag hindi nakasuot ng seat belt ang pasaherong wala pang 18?","o":["Ang driver","Ang pasahero","Ang may-ari ng kotse","Ang magulang ng pasahero, kahit wala sa kotse"],"h1":"Isipin ang taong nasa likod ng manibela.","h2":"Sa New Jersey, ang driver ang may pananagutan na siguraduhing nakasuot ng seat belt ang bawat pasaherong wala pang 18.","p":"Tama. Ang driver ang mananagot sa mga pasaherong wala pang 18."},"ar":{"q":"في New Jersey، مَن المسؤول عندما لا يربط راكب عمره أقل من 18 عامًا حزام الأمان؟","o":["السائق","الراكب","مالك السيارة","أحد والدَي الراكب، حتى لو لم يكن في السيارة"],"h1":"فكّر في الشخص الذي يمسك المِقوَد.","h2":"في New Jersey، السائق هو المسؤول عن التأكد من أن كل راكب عمره أقل من 18 عامًا يربط حزام الأمان.","p":"صحيح. السائق مسؤول عن الركاب الذين أعمارهم أقل من 18 عامًا."},"ref":{"doc":"NJ","page":40}},{"id":"nj-026","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a crash causes more than $500 in damage and the police file no report. What must you do?","o":["Nothing, if no one was hurt","Call the MVC within 24 hours","Send a written report to the MVC within 10 days","Report it at your next license renewal"],"h1":"You put it in writing, and you have less than two weeks.","h2":"In New Jersey, if damage is over $500 or someone is hurt and the police file no report, you must send a written report to the MVC within 10 days.","p":"Right. Without a police report, you send a written report to the MVC within 10 days."},"es":{"q":"En New Jersey, un choque causa más de $500 en daños y la policía no hace un informe. ¿Qué debe hacer usted?","o":["Nada, si nadie resultó herido","Llamar a la MVC dentro de 24 horas","Enviar un informe escrito a la MVC dentro de 10 días","Informarlo cuando renueve su licencia"],"h1":"Se hace por escrito, y tiene menos de dos semanas.","h2":"En New Jersey, si los daños pasan de $500 o hay alguien herido y la policía no hace un informe, usted debe enviar un informe escrito a la MVC dentro de 10 días.","p":"Correcto. Sin informe policial, usted envía un informe escrito a la MVC dentro de 10 días."},"zh":{"q":"在 New Jersey，一场车祸造成超过 $500 的损失，警察没有写报告。你必须怎么做？","o":["如果没人受伤，什么都不用做","在 24 小时内打电话给 MVC","在 10 天内向 MVC 寄送书面报告","在下次更新驾照时报告"],"h1":"你要写成书面的，而且时间不到两个星期。","h2":"在 New Jersey，如果损失超过 $500 或有人受伤，而警察没有写报告，你必须在 10 天内向 MVC 寄送书面报告。","p":"对。没有警察报告时，你要在 10 天内向 MVC 寄送书面报告。"},"vi":{"q":"Ở New Jersey, một vụ tai nạn gây thiệt hại hơn $500 và cảnh sát không làm biên bản. Bạn phải làm gì?","o":["Không cần làm gì, nếu không ai bị thương","Gọi cho MVC trong vòng 24 giờ","Gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày","Báo cáo khi gia hạn bằng lái lần tới"],"h1":"Bạn phải viết ra giấy, và bạn có chưa đến hai tuần.","h2":"Ở New Jersey, nếu thiệt hại hơn $500 hoặc có người bị thương và cảnh sát không làm biên bản, bạn phải gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày.","p":"Đúng. Khi không có biên bản của cảnh sát, bạn gửi báo cáo bằng văn bản cho MVC trong vòng 10 ngày."},"tl":{"q":"Sa New Jersey, ang isang banggaan ay nagdulot ng higit sa $500 na pinsala at walang report na ginawa ang pulis. Ano ang dapat mong gawin?","o":["Wala, kung walang nasaktan","Tumawag sa MVC sa loob ng 24 oras","Magpadala ng nakasulat na report sa MVC sa loob ng 10 araw","I-report ito sa susunod mong pag-renew ng lisensya"],"h1":"Isusulat mo ito, at mayroon kang wala pang dalawang linggo.","h2":"Sa New Jersey, kung higit sa $500 ang pinsala o may nasaktan at walang report na ginawa ang pulis, dapat kang magpadala ng nakasulat na report sa MVC sa loob ng 10 araw.","p":"Tama. Kapag walang police report, magpadala ng nakasulat na report sa MVC sa loob ng 10 araw."},"ar":{"q":"في New Jersey، تسبّب حادث في أضرار تزيد على $500 ولم تكتب الشرطة أي تقرير. ماذا يجب أن تفعل؟","o":["لا شيء، إذا لم يُصب أحد","الاتصال بـ MVC خلال 24 ساعة","إرسال تقرير مكتوب إلى MVC خلال 10 أيام","الإبلاغ عنه عند تجديد رخصتك القادم"],"h1":"تكتبه على الورق، ولديك أقل من أسبوعين.","h2":"في New Jersey، إذا زادت الأضرار على $500 أو أُصيب أحد ولم تكتب الشرطة تقريرًا، يجب أن ترسل تقريرًا مكتوبًا إلى MVC خلال 10 أيام.","p":"صحيح. عندما لا يوجد تقرير من الشرطة، ترسل تقريرًا مكتوبًا إلى MVC خلال 10 أيام."},"ref":{"doc":"NJ","page":111}},{"id":"nj-027","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many points can come off your record for each year you drive with no violation or suspension?","o":["One point","Up to three points","Up to six points","All of your points"],"h1":"It is a small number, and your total never goes below zero.","h2":"In New Jersey, up to three points are taken off your record for each year with no violation or suspension.","p":"Right. A clean year can remove up to three points."},"es":{"q":"En New Jersey, ¿cuántos puntos se pueden quitar de su historial por cada año que maneja sin infracciones ni suspensiones?","o":["Un punto","Hasta tres puntos","Hasta seis puntos","Todos sus puntos"],"h1":"Es un número pequeño, y su total nunca baja de cero.","h2":"En New Jersey, se quitan hasta tres puntos de su historial por cada año sin infracciones ni suspensiones.","p":"Correcto. Un año limpio puede quitar hasta tres puntos."},"zh":{"q":"在 New Jersey，你每开车一年没有违规或被吊销驾照，记录上可以减去多少分？","o":["一分","最多三分","最多六分","全部分数"],"h1":"这是一个小数字，而且你的总分永远不会低于零。","h2":"在 New Jersey，每一年没有违规或被吊销驾照，你的记录上最多可以减去三分。","p":"对。一年没有违规最多可以减去三分。"},"vi":{"q":"Ở New Jersey, mỗi năm bạn lái xe không vi phạm và không bị treo bằng lái, hồ sơ của bạn được trừ bao nhiêu điểm?","o":["Một điểm","Tối đa ba điểm","Tối đa sáu điểm","Tất cả số điểm của bạn"],"h1":"Đó là một con số nhỏ, và tổng điểm của bạn không bao giờ dưới không.","h2":"Ở New Jersey, mỗi năm không vi phạm và không bị treo bằng lái, hồ sơ của bạn được trừ tối đa ba điểm.","p":"Đúng. Một năm không vi phạm có thể trừ tối đa ba điểm."},"tl":{"q":"Sa New Jersey, ilang puntos ang puwedeng matanggal sa record mo sa bawat taon na nagmaneho ka nang walang paglabag o suspensyon?","o":["Isang puntos","Hanggang tatlong puntos","Hanggang anim na puntos","Lahat ng puntos mo"],"h1":"Maliit na numero ito, at hindi bababa sa zero ang kabuuan mo.","h2":"Sa New Jersey, hanggang tatlong puntos ang tinatanggal sa record mo sa bawat taon na walang paglabag o suspensyon.","p":"Tama. Ang isang malinis na taon ay puwedeng mag-alis ng hanggang tatlong puntos."},"ar":{"q":"في New Jersey، كم نقطة يمكن أن تُحذف من سجلّك عن كل سنة تقود فيها بلا مخالفة أو إيقاف للرخصة؟","o":["نقطة واحدة","حتى ثلاث نقاط","حتى ست نقاط","كل نقاطك"],"h1":"إنه عدد صغير، ومجموع نقاطك لا ينزل أبدًا تحت الصفر.","h2":"في New Jersey، تُحذف حتى ثلاث نقاط من سجلّك عن كل سنة بلا مخالفة أو إيقاف للرخصة.","p":"صحيح. السنة النظيفة يمكن أن تحذف حتى ثلاث نقاط."},"ref":{"doc":"NJ","page":137}},{"id":"nj-028","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, what eyesight must a basic license applicant have, with or without glasses?","o":["20/20","20/40","20/50","20/100"],"h1":"The rule for commercial drivers is stricter than this one.","h2":"In New Jersey, a basic license applicant needs 20/50 vision, with or without glasses or contact lenses.","p":"Right. A basic license needs 20/50 vision."},"es":{"q":"En Nueva Jersey, ¿qué visión debe tener quien solicita una licencia básica, con o sin anteojos?","o":["20/20","20/40","20/50","20/100"],"h1":"La regla para conductores comerciales es más estricta que esta.","h2":"En Nueva Jersey, quien solicita una licencia básica necesita una visión de 20/50, con o sin anteojos o lentes de contacto.","p":"Correcto. La licencia básica pide una visión de 20/50."},"zh":{"q":"在 New Jersey，申请普通驾照的人戴或不戴眼镜，视力必须达到多少？","o":["20/20","20/40","20/50","20/100"],"h1":"商业驾驶员的规定比这个更严格。","h2":"在 New Jersey，申请普通驾照的人戴或不戴眼镜或隐形眼镜，视力都需要达到 20/50。","p":"对。普通驾照需要 20/50 的视力。"},"vi":{"q":"Ở New Jersey, người xin bằng lái thông thường phải có thị lực bao nhiêu, dù có đeo kính hay không?","o":["20/20","20/40","20/50","20/100"],"h1":"Quy định cho tài xế thương mại nghiêm ngặt hơn quy định này.","h2":"Ở New Jersey, người xin bằng lái thông thường cần có thị lực 20/50, dù có đeo kính hoặc kính áp tròng hay không.","p":"Đúng. Bằng lái thông thường cần thị lực 20/50."},"tl":{"q":"Sa New Jersey, anong linaw ng paningin ang kailangan ng nag-a-apply ng basic na lisensya, may salamin man o wala?","o":["20/20","20/40","20/50","20/100"],"h1":"Mas mahigpit ang patakaran para sa mga commercial driver kaysa rito.","h2":"Sa New Jersey, kailangan ng nag-a-apply ng basic na lisensya ang 20/50 na paningin, may salamin o contact lens man o wala.","p":"Tama. Kailangan ng 20/50 na paningin para sa basic na lisensya."},"ar":{"q":"في New Jersey، ما قوة النظر المطلوبة لمن يتقدّم لرخصة قيادة عادية، بالنظارة أو بدونها؟","o":["20/20","20/40","20/50","20/100"],"h1":"القاعدة لسائقي المركبات التجارية أشدّ من هذه.","h2":"في New Jersey، يحتاج المتقدّم لرخصة عادية إلى نظر 20/50، بالنظارة أو العدسات اللاصقة أو بدونها.","p":"صحيح. الرخصة العادية تحتاج إلى نظر 20/50."},"ref":{"doc":"NJ","page":31}},{"id":"nj-029","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points of ID must your documents add up to when you apply for a license?","o":["At least three points","At least four points","At least five points","At least six points"],"h1":"The MVC's ID system is named after this number.","h2":"In New Jersey, your ID documents must add up to at least six points, with at least one primary and one secondary document, plus proof of address.","p":"Right. You need at least six points of ID."},"es":{"q":"En Nueva Jersey, ¿cuántos puntos deben sumar sus documentos de identidad al solicitar una licencia?","o":["Al menos tres puntos","Al menos cuatro puntos","Al menos cinco puntos","Al menos seis puntos"],"h1":"El sistema de identificación de la MVC lleva el nombre de este número.","h2":"En Nueva Jersey, sus documentos de identidad deben sumar al menos seis puntos, con al menos un documento primario y uno secundario, más prueba de domicilio.","p":"Correcto. Necesita al menos seis puntos de identificación."},"zh":{"q":"在 New Jersey，申请驾照时，你的身份证明文件加起来必须有多少分？","o":["至少三分","至少四分","至少五分","至少六分"],"h1":"MVC 的身份证明制度就是用这个数字命名的。","h2":"在 New Jersey，你的身份证明文件加起来必须至少有六分，其中至少要有一份主要文件和一份次要文件，另外还要有地址证明。","p":"对。你需要至少六分的身份证明。"},"vi":{"q":"Ở New Jersey, khi xin bằng lái, giấy tờ tùy thân của bạn phải cộng lại được bao nhiêu điểm?","o":["Ít nhất ba điểm","Ít nhất bốn điểm","Ít nhất năm điểm","Ít nhất sáu điểm"],"h1":"Hệ thống giấy tờ tùy thân của MVC được đặt tên theo con số này.","h2":"Ở New Jersey, giấy tờ tùy thân của bạn phải cộng lại được ít nhất sáu điểm, với ít nhất một giấy tờ chính và một giấy tờ phụ, cùng với giấy tờ chứng minh địa chỉ.","p":"Đúng. Bạn cần ít nhất sáu điểm giấy tờ tùy thân."},"tl":{"q":"Sa New Jersey, ilang puntos ng ID ang dapat kabuuan ng mga dokumento mo kapag nag-apply ka ng lisensya?","o":["Hindi bababa sa tatlong puntos","Hindi bababa sa apat na puntos","Hindi bababa sa limang puntos","Hindi bababa sa anim na puntos"],"h1":"Ipinangalan sa numerong ito ang ID system ng MVC.","h2":"Sa New Jersey, dapat umabot sa hindi bababa sa anim na puntos ang mga ID document mo, kasama ang hindi bababa sa isang primary at isang secondary na dokumento, at patunay ng address.","p":"Tama. Kailangan mo ng hindi bababa sa anim na puntos ng ID."},"ar":{"q":"في New Jersey، كم نقطة يجب أن يكون مجموع وثائق هويتك عندما تتقدّم لرخصة القيادة؟","o":["ثلاث نقاط على الأقل","أربع نقاط على الأقل","خمس نقاط على الأقل","ست نقاط على الأقل"],"h1":"نظام الهوية في MVC يحمل اسم هذا الرقم.","h2":"في New Jersey، يجب أن يكون مجموع وثائق هويتك ست نقاط على الأقل، منها وثيقة أساسية واحدة ووثيقة ثانوية واحدة على الأقل، مع إثبات العنوان.","p":"صحيح. تحتاج إلى ست نقاط على الأقل من وثائق الهوية."},"ref":{"doc":"NJ","page":9}},{"id":"nj-030","scope":"NJ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Jersey, after an emergency vehicle with its siren or lights on passes you, how far behind it must you stay?","o":["At least 300 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"It is about the length of a football field.","h2":"In New Jersey, after an emergency vehicle passes, you must stay at least 300 feet behind it while its signals are on.","p":"Right. Stay at least 300 feet behind."},"es":{"q":"En Nueva Jersey, después de que lo pasa un vehículo de emergencia con la sirena o las luces encendidas, ¿a qué distancia detrás debe mantenerse?","o":["Al menos 300 pies","Al menos 50 pies","Al menos 100 pies","Al menos 1,000 pies"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En Nueva Jersey, después de que pasa un vehículo de emergencia, debe mantenerse al menos a 300 pies detrás mientras tenga sus señales encendidas.","p":"Correcto. Manténgase al menos a 300 pies detrás."},"zh":{"q":"在 New Jersey，一辆开着警笛或警灯的紧急车辆从你旁边经过后，你必须在它后面保持多远？","o":["至少 300 英尺","至少 50 英尺","至少 100 英尺","至少 1,000 英尺"],"h1":"大约是一个橄榄球场的长度。","h2":"在 New Jersey，紧急车辆经过后，只要它的信号还开着，你必须在它后面保持至少 300 英尺。","p":"对。要在后面保持至少 300 英尺。"},"vi":{"q":"Ở New Jersey, sau khi một xe cấp cứu đang bật còi hoặc đèn chạy qua bạn, bạn phải đi cách phía sau nó bao xa?","o":["Ít nhất 300 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 1,000 feet"],"h1":"Khoảng bằng chiều dài một sân bóng bầu dục.","h2":"Ở New Jersey, sau khi xe cấp cứu chạy qua, bạn phải đi cách phía sau nó ít nhất 300 feet khi nó còn bật tín hiệu.","p":"Đúng. Hãy đi cách phía sau ít nhất 300 feet."},"tl":{"q":"Sa New Jersey, pagkalampas sa iyo ng emergency vehicle na may sirena o ilaw na nakabukas, gaano kalayo ka dapat manatili sa likod nito?","o":["Hindi bababa sa 300 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Halos kasinghaba ito ng isang football field.","h2":"Sa New Jersey, pagkalampas ng emergency vehicle, dapat kang manatili nang hindi bababa sa 300 talampakan sa likod nito habang nakabukas ang mga signal nito.","p":"Tama. Manatili nang hindi bababa sa 300 talampakan sa likod."},"ar":{"q":"في New Jersey، بعد أن تتجاوزك مركبة طوارئ صفّارتها أو أضواؤها تعمل، كم يجب أن تبقى بعيدًا خلفها؟","o":["300 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","1,000 قدم على الأقل"],"h1":"إنها تقريبًا طول ملعب كرة قدم أمريكية.","h2":"في New Jersey، بعد أن تمرّ مركبة الطوارئ، يجب أن تبقى خلفها 300 قدم على الأقل ما دامت إشاراتها تعمل.","p":"صحيح. ابقَ خلفها 300 قدم على الأقل."},"ref":{"doc":"NJ","page":78}},{"id":"nj-031","scope":"NJ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Jersey, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"In New Jersey it is less than the 15 feet used in many other states.","h2":"In New Jersey, you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En Nueva Jersey, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 25 pies"],"h1":"En Nueva Jersey es menos que los 15 pies que se usan en muchos otros estados.","h2":"En Nueva Jersey, no puede estacionarse a menos de 10 pies de un hidrante.","p":"Correcto. Quédese al menos a 10 pies de un hidrante."},"zh":{"q":"在 New Jersey，你可以在离消防栓多近的地方停车？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 25 英尺"],"h1":"在 New Jersey，这个距离比很多其他州使用的 15 英尺要短。","h2":"在 New Jersey，你不可以在离消防栓 10 英尺以内的地方停车。","p":"对。停车要离消防栓至少 10 英尺。"},"vi":{"q":"Ở New Jersey, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Ở New Jersey, khoảng cách này ngắn hơn mức 15 feet mà nhiều tiểu bang khác dùng.","h2":"Ở New Jersey, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa New Jersey, gaano kalapit ka puwedeng pumarada sa fire hydrant?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan"],"h1":"Sa New Jersey, mas maikli ito kaysa sa 15 talampakan na ginagamit sa maraming ibang estado.","h2":"Sa New Jersey, hindi ka puwedeng pumarada sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 talampakan sa hydrant."},"ar":{"q":"في New Jersey، ما أقرب مسافة يمكنك أن تركن فيها من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا"],"h1":"في New Jersey هي أقل من الـ 15 قدمًا المستخدمة في ولايات كثيرة أخرى.","h2":"في New Jersey، لا يجوز لك أن تركن على مسافة أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور الإطفاء."},"ref":{"doc":"NJ","page":85}},{"id":"nj-032","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, you move to a new home. How soon must you report your new address to the MVC?","o":["Within one week","Within 30 days","Within 60 days","Only when you renew your license"],"h1":"It is a short time, counted in days, not months.","h2":"In New Jersey, you must report a new address to the MVC within one week after you move.","p":"Right. Report a new address within one week."},"es":{"q":"En New Jersey, usted se muda a una casa nueva. ¿En cuánto tiempo debe informar su nueva dirección a la MVC?","o":["Dentro de una semana","Dentro de 30 días","Dentro de 60 días","Solo cuando renueve su licencia"],"h1":"Es poco tiempo, contado en días, no en meses.","h2":"En New Jersey, usted debe informar su nueva dirección a la MVC dentro de una semana después de mudarse.","p":"Correcto. Informe la nueva dirección dentro de una semana."},"zh":{"q":"在 New Jersey，你搬了新家。你必须在多久之内把新地址报告给 MVC？","o":["一周之内","30 天之内","60 天之内","只在更新驾照时"],"h1":"时间很短，按天算，不是按月算。","h2":"在 New Jersey，你搬家后必须在一周之内把新地址报告给 MVC。","p":"对。要在一周之内报告新地址。"},"vi":{"q":"Ở New Jersey, bạn chuyển đến nhà mới. Bạn phải báo địa chỉ mới cho MVC trong thời gian bao lâu?","o":["Trong vòng một tuần","Trong vòng 30 ngày","Trong vòng 60 ngày","Chỉ khi gia hạn bằng lái"],"h1":"Đó là một thời gian ngắn, tính bằng ngày, không phải bằng tháng.","h2":"Ở New Jersey, bạn phải báo địa chỉ mới cho MVC trong vòng một tuần sau khi chuyển nhà.","p":"Đúng. Báo địa chỉ mới trong vòng một tuần."},"tl":{"q":"Sa New Jersey, lumipat ka sa bagong bahay. Gaano kabilis mo dapat i-report ang bago mong address sa MVC?","o":["Sa loob ng isang linggo","Sa loob ng 30 araw","Sa loob ng 60 araw","Kapag nag-renew ka lang ng lisensya"],"h1":"Maikling panahon ito, binibilang sa araw, hindi sa buwan.","h2":"Sa New Jersey, dapat mong i-report ang bagong address sa MVC sa loob ng isang linggo pagkatapos mong lumipat.","p":"Tama. I-report ang bagong address sa loob ng isang linggo."},"ar":{"q":"في New Jersey، انتقلت إلى منزل جديد. خلال كم من الوقت يجب أن تبلّغ MVC بعنوانك الجديد؟","o":["خلال أسبوع واحد","خلال 30 يومًا","خلال 60 يومًا","فقط عندما تجدّد رخصتك"],"h1":"إنها مدة قصيرة، تُحسب بالأيام وليس بالأشهر.","h2":"في New Jersey يجب أن تبلّغ MVC بعنوانك الجديد خلال أسبوع واحد بعد انتقالك.","p":"صحيح. بلّغ عن العنوان الجديد خلال أسبوع واحد."},"ref":{"doc":"NJ","page":4}},{"id":"nj-033","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, for how long is a new driver license valid?","o":["Two years","Four years","Eight years","Until you turn 65"],"h1":"It is more than two years but less than eight.","h2":"In New Jersey, driver licenses are valid for four years.","p":"Right. A New Jersey license lasts four years."},"es":{"q":"En New Jersey, ¿por cuánto tiempo es válida una licencia de conducir nueva?","o":["Dos años","Cuatro años","Ocho años","Hasta que cumpla 65 años"],"h1":"Es más de dos años pero menos de ocho.","h2":"En New Jersey, las licencias de conducir son válidas por cuatro años.","p":"Correcto. Una licencia de New Jersey dura cuatro años."},"zh":{"q":"在 New Jersey，新驾照的有效期是多久？","o":["两年","四年","八年","到你满 65 岁为止"],"h1":"它比两年长，但比八年短。","h2":"在 New Jersey，驾照的有效期是四年。","p":"对。New Jersey 的驾照有效期是四年。"},"vi":{"q":"Ở New Jersey, bằng lái xe mới có giá trị trong bao lâu?","o":["Hai năm","Bốn năm","Tám năm","Cho đến khi bạn 65 tuổi"],"h1":"Nó dài hơn hai năm nhưng ngắn hơn tám năm.","h2":"Ở New Jersey, bằng lái xe có giá trị trong bốn năm.","p":"Đúng. Bằng lái của New Jersey có giá trị bốn năm."},"tl":{"q":"Sa New Jersey, gaano katagal valid ang bagong driver license?","o":["Dalawang taon","Apat na taon","Walong taon","Hanggang mag-65 ka"],"h1":"Mas mahaba ito sa dalawang taon pero mas maikli sa walo.","h2":"Sa New Jersey, valid ang driver license nang apat na taon.","p":"Tama. Apat na taon ang bisa ng lisensya sa New Jersey."},"ar":{"q":"في New Jersey، ما مدة صلاحية رخصة القيادة الجديدة؟","o":["سنتان","أربع سنوات","ثماني سنوات","حتى تبلغ 65 سنة"],"h1":"إنها أكثر من سنتين وأقل من ثماني سنوات.","h2":"في New Jersey تكون رخصة القيادة صالحة لمدة أربع سنوات.","p":"صحيح. رخصة New Jersey صالحة أربع سنوات."},"ref":{"doc":"NJ","page":6}},{"id":"nj-034","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many hours of behind-the-wheel lessons does an approved course for a special learner permit include?","o":["Two hours","Fifty hours","Six hours","Ten hours"],"h1":"It is about one full school day of lessons with an instructor.","h2":"In New Jersey, an approved course for a special learner permit is six full hours of behind-the-wheel lessons in a car with dual controls.","p":"Right. The course is six hours behind the wheel."},"es":{"q":"En New Jersey, ¿cuántas horas de clases al volante incluye un curso aprobado para el permiso especial de aprendiz?","o":["Dos horas","Cincuenta horas","Seis horas","Diez horas"],"h1":"Es más o menos un día escolar completo de clases con un instructor.","h2":"En New Jersey, un curso aprobado para el permiso especial de aprendiz son seis horas completas de clases al volante en un carro con doble control.","p":"Correcto. El curso es de seis horas al volante."},"zh":{"q":"在 New Jersey，特别学习驾照（special learner permit）的认可课程包括多少小时的实际驾驶课？","o":["两小时","五十小时","六小时","十小时"],"h1":"大约是一整个上学日的教练课。","h2":"在 New Jersey，特别学习驾照的认可课程是在有双控制的车里上满六小时的实际驾驶课。","p":"对。这个课程是六小时的实际驾驶。"},"vi":{"q":"Ở New Jersey, khóa học được chấp thuận cho giấy phép tập lái đặc biệt (special learner permit) gồm bao nhiêu giờ học lái thực tế?","o":["Hai giờ","Năm mươi giờ","Sáu giờ","Mười giờ"],"h1":"Nó khoảng bằng một ngày học trọn vẹn với giáo viên dạy lái.","h2":"Ở New Jersey, khóa học được chấp thuận cho giấy phép tập lái đặc biệt gồm đủ sáu giờ học lái thực tế trong xe có hai bộ điều khiển.","p":"Đúng. Khóa học là sáu giờ lái thực tế."},"tl":{"q":"Sa New Jersey, ilang oras ng behind-the-wheel na aralin ang kasama sa aprubadong kurso para sa special learner permit?","o":["Dalawang oras","Limampung oras","Anim na oras","Sampung oras"],"h1":"Halos isang buong araw ng klase ito kasama ang instructor.","h2":"Sa New Jersey, ang aprubadong kurso para sa special learner permit ay anim na buong oras ng behind-the-wheel na aralin sa kotseng may dual controls.","p":"Tama. Anim na oras ng behind-the-wheel ang kurso."},"ar":{"q":"في New Jersey، كم ساعة من دروس القيادة العملية تتضمن الدورة المعتمدة لتصريح التعلّم الخاص (special learner permit)؟","o":["ساعتان","خمسون ساعة","ست ساعات","عشر ساعات"],"h1":"إنها تقريبًا يوم دراسي كامل من الدروس مع مدرّب.","h2":"في New Jersey تتضمن الدورة المعتمدة لتصريح التعلّم الخاص ست ساعات كاملة من دروس القيادة العملية في سيارة بأدوات تحكّم مزدوجة.","p":"صحيح. الدورة ست ساعات من القيادة العملية."},"ref":{"doc":"NJ","page":19}},{"id":"nj-035","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how long must you drive with a probationary license before you can get a basic driver license?","o":["Three months","Six months","Two years","At least one year"],"h1":"It is longer than the six months of supervised practice.","h2":"In New Jersey, you must drive for at least one year with a probationary license before you can get a basic driver license.","p":"Right. At least one year on a probationary license."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe manejar con licencia probatoria antes de obtener la licencia de conducir básica?","o":["Tres meses","Seis meses","Dos años","Al menos un año"],"h1":"Es más que los seis meses de práctica supervisada.","h2":"En New Jersey, usted debe manejar al menos un año con licencia probatoria antes de obtener la licencia de conducir básica.","p":"Correcto. Al menos un año con licencia probatoria."},"zh":{"q":"在 New Jersey，你必须持试用驾照（probationary license）开车多久，才能拿到基本驾照？","o":["三个月","六个月","两年","至少一年"],"h1":"它比六个月的监督练习时间长。","h2":"在 New Jersey，你必须持试用驾照开车至少一年，才能拿到基本驾照。","p":"对。持试用驾照至少一年。"},"vi":{"q":"Ở New Jersey, bạn phải lái xe với bằng lái tạm thời (probationary license) trong bao lâu trước khi lấy được bằng lái cơ bản?","o":["Ba tháng","Sáu tháng","Hai năm","Ít nhất một năm"],"h1":"Nó dài hơn sáu tháng tập lái có giám sát.","h2":"Ở New Jersey, bạn phải lái xe với bằng lái tạm thời ít nhất một năm trước khi lấy được bằng lái cơ bản.","p":"Đúng. Ít nhất một năm với bằng lái tạm thời."},"tl":{"q":"Sa New Jersey, gaano katagal ka dapat magmaneho nang may probationary license bago ka makakuha ng basic driver license?","o":["Tatlong buwan","Anim na buwan","Dalawang taon","Hindi bababa sa isang taon"],"h1":"Mas mahaba ito kaysa sa anim na buwan ng praktis na may nagbabantay.","h2":"Sa New Jersey, dapat kang magmaneho nang hindi bababa sa isang taon nang may probationary license bago ka makakuha ng basic driver license.","p":"Tama. Hindi bababa sa isang taon sa probationary license."},"ar":{"q":"في New Jersey، كم من الوقت يجب أن تقود برخصة تحت الاختبار (probationary license) قبل أن تحصل على رخصة قيادة أساسية؟","o":["ثلاثة أشهر","ستة أشهر","سنتان","سنة واحدة على الأقل"],"h1":"إنها أطول من الأشهر الستة للتدريب تحت الإشراف.","h2":"في New Jersey يجب أن تقود سنة واحدة على الأقل برخصة تحت الاختبار قبل أن تحصل على رخصة قيادة أساسية.","p":"صحيح. سنة واحدة على الأقل برخصة تحت الاختبار."},"ref":{"doc":"NJ","page":15}},{"id":"nj-036","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, when may you use studded snow tires?","o":["From November 15 to April 1","From October 1 to May 1","From December 1 to March 1","Any time of the year"],"h1":"The season starts in the middle of November.","h2":"In New Jersey, you may use studded snow tires from November 15 to April 1.","p":"Right. Studded tires are allowed from November 15 to April 1."},"es":{"q":"En New Jersey, ¿cuándo puede usar llantas de nieve con clavos?","o":["Del 15 de noviembre al 1 de abril","Del 1 de octubre al 1 de mayo","Del 1 de diciembre al 1 de marzo","En cualquier época del año"],"h1":"La temporada empieza a mediados de noviembre.","h2":"En New Jersey, puede usar llantas de nieve con clavos del 15 de noviembre al 1 de abril.","p":"Correcto. Las llantas con clavos se permiten del 15 de noviembre al 1 de abril."},"zh":{"q":"在 New Jersey，什么时候可以用带钉雪地轮胎？","o":["从 November 15 到 April 1","从 October 1 到 May 1","从 December 1 到 March 1","一年中任何时候"],"h1":"这个季节从 11 月中旬开始。","h2":"在 New Jersey，你可以在 November 15 到 April 1 之间使用带钉雪地轮胎。","p":"对。带钉轮胎允许从 November 15 用到 April 1。"},"vi":{"q":"Ở New Jersey, khi nào bạn được dùng lốp xe có đinh đi tuyết (studded snow tires)?","o":["Từ November 15 đến April 1","Từ October 1 đến May 1","Từ December 1 đến March 1","Bất cứ lúc nào trong năm"],"h1":"Mùa này bắt đầu vào giữa tháng 11.","h2":"Ở New Jersey, bạn được dùng lốp xe có đinh đi tuyết từ November 15 đến April 1.","p":"Đúng. Lốp có đinh được phép dùng từ November 15 đến April 1."},"tl":{"q":"Sa New Jersey, kailan puwedeng gumamit ng studded snow tires?","o":["Mula November 15 hanggang April 1","Mula October 1 hanggang May 1","Mula December 1 hanggang March 1","Kahit anong oras ng taon"],"h1":"Nagsisimula ang season sa kalagitnaan ng Nobyembre.","h2":"Sa New Jersey, puwede kang gumamit ng studded snow tires mula November 15 hanggang April 1.","p":"Tama. Puwede ang studded tires mula November 15 hanggang April 1."},"ar":{"q":"في New Jersey، متى يجوز لك استخدام إطارات الثلج المزوّدة بمسامير (studded snow tires)؟","o":["من November 15 إلى April 1","من October 1 إلى May 1","من December 1 إلى March 1","في أي وقت من السنة"],"h1":"يبدأ الموسم في منتصف شهر نوفمبر.","h2":"في New Jersey يجوز لك استخدام إطارات الثلج المزوّدة بمسامير من November 15 إلى April 1.","p":"صحيح. الإطارات المزوّدة بمسامير مسموحة من November 15 إلى April 1."},"ref":{"doc":"NJ","page":99}},{"id":"nj-037","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, you drive without clearing the snow and ice off your car. What fine can you get, even if nothing flies off?","o":["No fine, unless snow flies off","$25 to $75","$200 to $1,000","$1,500"],"h1":"You can be fined even if no snow falls off, but the amount is small.","h2":"In New Jersey, driving without clearing snow and ice off your car can bring a fine of $25 to $75, even if nothing flies off.","p":"Right. Not clearing your car can cost $25 to $75."},"es":{"q":"En New Jersey, usted maneja sin quitar la nieve y el hielo de su carro. ¿Qué multa le pueden poner, aunque no se caiga nada?","o":["Ninguna multa, a menos que se caiga la nieve","$25 a $75","$200 a $1,000","$1,500"],"h1":"Le pueden multar aunque no se caiga nada de nieve, pero la cantidad es pequeña.","h2":"En New Jersey, manejar sin quitar la nieve y el hielo de su carro puede costarle una multa de $25 a $75, aunque no se caiga nada.","p":"Correcto. No limpiar su carro puede costar de $25 a $75."},"zh":{"q":"在 New Jersey，你没有清除车上的雪和冰就开车。即使没有东西飞出去，你会被罚多少钱？","o":["不罚款，除非雪飞出去","$25 到 $75","$200 到 $1,000","$1,500"],"h1":"即使没有雪掉下来也会被罚款，但金额不大。","h2":"在 New Jersey，没有清除车上的雪和冰就开车，即使没有东西飞出去，也可能被罚 $25 到 $75。","p":"对。不清理车子可能被罚 $25 到 $75。"},"vi":{"q":"Ở New Jersey, bạn lái xe mà không dọn sạch tuyết và băng trên xe. Bạn có thể bị phạt bao nhiêu, kể cả khi không có gì bay ra?","o":["Không bị phạt, trừ khi tuyết bay ra","$25 đến $75","$200 đến $1,000","$1,500"],"h1":"Bạn có thể bị phạt kể cả khi không có tuyết rơi ra, nhưng số tiền nhỏ.","h2":"Ở New Jersey, lái xe mà không dọn sạch tuyết và băng trên xe có thể bị phạt $25 đến $75, kể cả khi không có gì bay ra.","p":"Đúng. Không dọn sạch xe có thể bị phạt $25 đến $75."},"tl":{"q":"Sa New Jersey, nagmaneho ka nang hindi inaalis ang snow at yelo sa kotse mo. Anong multa ang puwede mong makuha, kahit walang lumipad?","o":["Walang multa, maliban kung may lumipad na snow","$25 hanggang $75","$200 hanggang $1,000","$1,500"],"h1":"Puwede kang multahan kahit walang nahulog na snow, pero maliit ang halaga.","h2":"Sa New Jersey, ang pagmamaneho nang hindi inaalis ang snow at yelo sa kotse ay puwedeng magresulta sa multang $25 hanggang $75, kahit walang lumipad.","p":"Tama. Ang hindi paglilinis ng kotse ay puwedeng magkahalaga ng $25 hanggang $75."},"ar":{"q":"في New Jersey، قدت سيارتك دون أن تزيل الثلج والجليد عنها. ما الغرامة التي قد تدفعها، حتى لو لم يتطاير شيء؟","o":["لا غرامة، إلا إذا تطاير الثلج","من $25 إلى $75","من $200 إلى $1,000","$1,500"],"h1":"يمكن أن تُغرَّم حتى لو لم يسقط أي ثلج، لكن المبلغ صغير.","h2":"في New Jersey، القيادة دون إزالة الثلج والجليد عن السيارة قد تؤدي إلى غرامة من $25 إلى $75، حتى لو لم يتطاير شيء.","p":"صحيح. عدم تنظيف سيارتك قد يكلّفك من $25 إلى $75."},"ref":{"doc":"NJ","page":47}},{"id":"nj-038","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, apart from a few exceptions such as being stuck in traffic, how long may a vehicle sit with its engine idling?","o":["One minute","Ten minutes","Three minutes","Fifteen minutes"],"h1":"It is only a few minutes.","h2":"In New Jersey, the law limits vehicle idling to three minutes or less, with a few exceptions such as being stuck in traffic.","p":"Right. Idling is limited to three minutes."},"es":{"q":"En New Jersey, salvo algunas excepciones como estar atascado en el tráfico, ¿cuánto tiempo puede estar un vehículo con el motor encendido sin moverse?","o":["Un minuto","Diez minutos","Tres minutos","Quince minutos"],"h1":"Son solo unos pocos minutos.","h2":"En New Jersey, la ley limita a tres minutos o menos el tiempo que un vehículo puede estar con el motor encendido sin moverse, con algunas excepciones como estar atascado en el tráfico.","p":"Correcto. El motor encendido sin moverse se limita a tres minutos."},"zh":{"q":"在 New Jersey，除了少数例外（比如堵车），车辆可以停着让发动机空转多久？","o":["一分钟","十分钟","三分钟","十五分钟"],"h1":"只有几分钟。","h2":"在 New Jersey，法律规定车辆空转不能超过三分钟，只有少数例外，比如堵车。","p":"对。空转限制在三分钟以内。"},"vi":{"q":"Ở New Jersey, ngoài một vài trường hợp ngoại lệ như bị kẹt xe, một chiếc xe được đứng yên nổ máy (idling) trong bao lâu?","o":["Một phút","Mười phút","Ba phút","Mười lăm phút"],"h1":"Chỉ vài phút thôi.","h2":"Ở New Jersey, luật giới hạn việc để xe nổ máy khi đứng yên trong ba phút hoặc ít hơn, trừ một vài trường hợp ngoại lệ như bị kẹt xe.","p":"Đúng. Nổ máy khi đứng yên bị giới hạn trong ba phút."},"tl":{"q":"Sa New Jersey, maliban sa ilang eksepsyon tulad ng pagkaipit sa trapiko, gaano katagal puwedeng nakatigil ang sasakyan habang naka-idle ang makina?","o":["Isang minuto","Sampung minuto","Tatlong minuto","Labinlimang minuto"],"h1":"Ilang minuto lang ito.","h2":"Sa New Jersey, nililimitahan ng batas ang pag-idle ng sasakyan sa tatlong minuto o mas maikli, maliban sa ilang eksepsyon tulad ng pagkaipit sa trapiko.","p":"Tama. Hanggang tatlong minuto lang ang pag-idle."},"ar":{"q":"في New Jersey، باستثناء حالات قليلة مثل الوقوف في زحمة السير، كم من الوقت يجوز أن تبقى السيارة متوقفة ومحرّكها يعمل؟","o":["دقيقة واحدة","عشر دقائق","ثلاث دقائق","خمس عشرة دقيقة"],"h1":"إنها بضع دقائق فقط.","h2":"في New Jersey يحدّد القانون تشغيل محرّك السيارة وهي متوقفة بثلاث دقائق أو أقل، مع استثناءات قليلة مثل الوقوف في زحمة السير.","p":"صحيح. تشغيل المحرّك والسيارة متوقفة محدود بثلاث دقائق."},"ref":{"doc":"NJ","page":50}},{"id":"nj-039","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, an ice cream truck ahead has its red lights flashing and its stop arm out. What must you do?","o":["Slow to 25 mph and pass","Pass at normal speed if no one is crossing","Stop and wait until the truck drives away","Stop, then pass at no more than 15 mph"],"h1":"Children may run to or from the truck, so you stop first.","h2":"In New Jersey, you must stop for an ice cream truck with flashing red lights and a stop arm, yield to people crossing, then pass at no more than 15 mph.","p":"Right. Stop first, then pass at 15 mph or less."},"es":{"q":"En New Jersey, un camión de helados adelante tiene las luces rojas intermitentes y el brazo de pare extendido. ¿Qué debe hacer?","o":["Bajar a 25 mph y pasar","Pasar a velocidad normal si nadie está cruzando","Parar y esperar hasta que el camión se vaya","Parar, y luego pasar a no más de 15 mph"],"h1":"Puede haber niños que corren hacia el camión o desde él, así que primero se para.","h2":"En New Jersey, usted debe parar ante un camión de helados con luces rojas intermitentes y brazo de pare, ceder el paso a quienes cruzan, y luego pasar a no más de 15 mph.","p":"Correcto. Primero pare, y luego pase a 15 mph o menos."},"zh":{"q":"在 New Jersey，前面的冰淇淋车红灯在闪，停车臂也伸出来了。你必须怎么做？","o":["减速到 25 mph 然后超过去","如果没人过马路，就用正常速度超过去","停车，等冰淇淋车开走","停车，然后以不超过 15 mph 的速度超过去"],"h1":"孩子可能会跑向冰淇淋车或从车那边跑过来，所以你要先停车。","h2":"在 New Jersey，遇到红灯闪烁并伸出停车臂的冰淇淋车，你必须停车，让过马路的人先走，然后以不超过 15 mph 的速度超过去。","p":"对。先停车，然后以 15 mph 或更低的速度超过去。"},"vi":{"q":"Ở New Jersey, một xe bán kem phía trước đang nhấp nháy đèn đỏ và đưa cần báo dừng ra. Bạn phải làm gì?","o":["Giảm xuống 25 mph rồi vượt qua","Vượt qua với tốc độ bình thường nếu không ai đang băng qua đường","Dừng lại và đợi đến khi xe bán kem chạy đi","Dừng lại, rồi vượt qua với tốc độ không quá 15 mph"],"h1":"Trẻ em có thể chạy đến hoặc chạy ra từ xe bán kem, nên bạn phải dừng trước.","h2":"Ở New Jersey, bạn phải dừng lại khi gặp xe bán kem nhấp nháy đèn đỏ và đưa cần báo dừng ra, nhường đường cho người đang băng qua, rồi vượt qua với tốc độ không quá 15 mph.","p":"Đúng. Dừng trước, rồi vượt qua với tốc độ 15 mph hoặc thấp hơn."},"tl":{"q":"Sa New Jersey, ang ice cream truck sa unahan ay may kumikislap na pulang ilaw at nakalabas ang stop arm. Ano ang dapat mong gawin?","o":["Bumagal sa 25 mph at lumampas","Lumampas sa normal na bilis kung walang tumatawid","Huminto at maghintay hanggang umalis ang truck","Huminto, saka lumampas nang hindi hihigit sa 15 mph"],"h1":"Puwedeng tumakbo ang mga bata papunta o mula sa truck, kaya huminto ka muna.","h2":"Sa New Jersey, dapat kang huminto para sa ice cream truck na may kumikislap na pulang ilaw at stop arm, magbigay-daan sa mga tumatawid, saka lumampas nang hindi hihigit sa 15 mph.","p":"Tama. Huminto muna, saka lumampas sa 15 mph o mas mabagal."},"ar":{"q":"في New Jersey، أمامك شاحنة بوظة (ice cream truck) أضواؤها الحمراء تومض وذراع التوقف فيها ممدودة. ماذا يجب أن تفعل؟","o":["خفّف السرعة إلى 25 mph وتجاوزها","تجاوزها بسرعتك العادية إذا لم يكن أحد يعبر","توقّف وانتظر حتى تبتعد الشاحنة","توقّف، ثم تجاوزها بسرعة لا تزيد على 15 mph"],"h1":"قد يركض الأطفال نحو الشاحنة أو منها، لذلك تتوقف أولًا.","h2":"في New Jersey يجب أن تتوقف لشاحنة البوظة التي تومض أضواؤها الحمراء وذراع التوقف فيها ممدودة، وأن تعطي حق المرور للعابرين، ثم تتجاوزها بسرعة لا تزيد على 15 mph.","p":"صحيح. توقّف أولًا، ثم تجاوز بسرعة 15 mph أو أقل."},"ref":{"doc":"NJ","page":78}},{"id":"nj-040","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, how close may you park to a fire department vehicle that is in service?","o":["No closer than 200 feet","No closer than 50 feet","No closer than 20 feet","No closer than 10 feet"],"h1":"It is a long distance, more than half a football field.","h2":"In New Jersey, you may not park within 200 feet of a fire department vehicle that is in service.","p":"Right. Stay at least 200 feet away from a working fire vehicle."},"es":{"q":"En New Jersey, ¿qué tan cerca puede estacionarse de un vehículo de bomberos que está en servicio?","o":["No a menos de 200 pies","No a menos de 50 pies","No a menos de 20 pies","No a menos de 10 pies"],"h1":"Es una distancia larga, más de medio campo de fútbol americano.","h2":"En New Jersey, no puede estacionarse a menos de 200 pies de un vehículo de bomberos que está en servicio.","p":"Correcto. Quédese al menos a 200 pies de un vehículo de bomberos en servicio."},"zh":{"q":"在 New Jersey，你最近可以把车停在离正在执勤的消防车多远的地方？","o":["不能近于 200 英尺","不能近于 50 英尺","不能近于 20 英尺","不能近于 10 英尺"],"h1":"这是很长的距离，超过半个橄榄球场。","h2":"在 New Jersey，你不能把车停在正在执勤的消防车 200 英尺以内。","p":"对。离正在工作的消防车至少 200 英尺。"},"vi":{"q":"Ở New Jersey, bạn được đậu xe gần xe cứu hỏa đang làm nhiệm vụ đến mức nào?","o":["Không gần hơn 200 feet","Không gần hơn 50 feet","Không gần hơn 20 feet","Không gần hơn 10 feet"],"h1":"Đó là một khoảng cách dài, hơn nửa sân bóng bầu dục.","h2":"Ở New Jersey, bạn không được đậu xe trong vòng 200 feet từ một xe cứu hỏa đang làm nhiệm vụ.","p":"Đúng. Cách xe cứu hỏa đang làm việc ít nhất 200 feet."},"tl":{"q":"Sa New Jersey, gaano kalapit ka puwedeng pumarada sa sasakyan ng bumbero na naka-duty?","o":["Hindi lalapit sa 200 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 10 feet"],"h1":"Malayo ito, higit sa kalahati ng football field.","h2":"Sa New Jersey, bawal kang pumarada sa loob ng 200 feet mula sa sasakyan ng bumbero na naka-duty.","p":"Tama. Lumayo nang hindi bababa sa 200 feet sa sasakyan ng bumbero na nagtatrabaho."},"ar":{"q":"في New Jersey، ما أقرب مسافة يجوز أن تركن فيها سيارتك من مركبة إطفاء في الخدمة؟","o":["ليس أقرب من 200 قدم","ليس أقرب من 50 قدمًا","ليس أقرب من 20 قدمًا","ليس أقرب من 10 أقدام"],"h1":"إنها مسافة طويلة، أكثر من نصف ملعب كرة قدم أمريكية.","h2":"في New Jersey لا يجوز لك أن تركن سيارتك على بُعد أقل من 200 قدم من مركبة إطفاء في الخدمة.","p":"صحيح. ابقَ على بُعد 200 قدم على الأقل من مركبة إطفاء تعمل."},"ref":{"doc":"NJ","page":78}},{"id":"nj-041","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, how many points go on your record if you fail to stop for a person in a crosswalk?","o":["None, only a fine","Two points","Five points","Eight points"],"h1":"It is the same number of points as many common moving violations.","h2":"In New Jersey, failing to stop for a person in a crosswalk adds two points to your record, along with a fine of up to $500.","p":"Right. It adds two points to your record."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial si no para ante una persona en un cruce peatonal?","o":["Ninguno, solo una multa","Dos puntos","Cinco puntos","Ocho puntos"],"h1":"Es la misma cantidad de puntos que muchas infracciones de tránsito comunes.","h2":"En New Jersey, no parar ante una persona en un cruce peatonal agrega dos puntos a su historial, además de una multa de hasta $500.","p":"Correcto. Agrega dos puntos a su historial."},"zh":{"q":"在 New Jersey，如果你没有为人行横道上的人停车，你的记录上会被加多少分？","o":["不加分，只罚款","两分","五分","八分"],"h1":"和很多常见的行车违规的分数一样。","h2":"在 New Jersey，没有为人行横道上的人停车，你的记录上会被加两分，还可能被罚款最多 $500。","p":"对。你的记录上会被加两分。"},"vi":{"q":"Ở New Jersey, nếu bạn không dừng lại cho người đang ở trên lối qua đường dành cho người đi bộ, hồ sơ của bạn bị ghi bao nhiêu điểm?","o":["Không bị điểm, chỉ bị phạt tiền","Hai điểm","Năm điểm","Tám điểm"],"h1":"Đó là số điểm giống như nhiều lỗi lái xe thông thường.","h2":"Ở New Jersey, không dừng lại cho người đang ở trên lối qua đường dành cho người đi bộ sẽ bị ghi hai điểm vào hồ sơ, cùng với tiền phạt đến $500.","p":"Đúng. Hồ sơ của bạn bị ghi hai điểm."},"tl":{"q":"Sa New Jersey, ilang puntos ang madadagdag sa record mo kung hindi ka huminto para sa tao sa crosswalk?","o":["Wala, multa lang","Dalawang puntos","Limang puntos","Walong puntos"],"h1":"Kapareho ito ng puntos ng maraming karaniwang paglabag sa pagmamaneho.","h2":"Sa New Jersey, ang hindi paghinto para sa tao sa crosswalk ay nagdadagdag ng dalawang puntos sa record mo, kasama ang multang hanggang $500.","p":"Tama. Dalawang puntos ang madadagdag sa record mo."},"ar":{"q":"في New Jersey، كم نقطة تُضاف إلى سجلّك إذا لم تتوقف لشخص في ممرّ المشاة؟","o":["لا نقاط، غرامة فقط","نقطتان","خمس نقاط","ثماني نقاط"],"h1":"إنه عدد النقاط نفسه لكثير من مخالفات القيادة الشائعة.","h2":"في New Jersey، عدم التوقف لشخص في ممرّ المشاة يضيف نقطتين إلى سجلّك، مع غرامة قد تصل إلى $500.","p":"صحيح. تُضاف نقطتان إلى سجلّك."},"ref":{"doc":"NJ","page":66}},{"id":"nj-042","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, on a road with a 65 mph limit, how fast over the limit must you go for the speeding fine to double?","o":["Any amount over the limit","5 mph or more over","10 mph or more over","20 mph or more over"],"h1":"It is a round number between 5 and 20.","h2":"In New Jersey, speeding fines are doubled for going 10 mph or more over the limit in a 65 mph zone.","p":"Right. Fines double at 10 mph or more over in a 65 mph zone."},"es":{"q":"En New Jersey, en una carretera con límite de 65 mph, ¿cuánto debe pasar el límite para que la multa por exceso de velocidad sea el doble?","o":["Cualquier cantidad sobre el límite","5 mph o más sobre el límite","10 mph o más sobre el límite","20 mph o más sobre el límite"],"h1":"Es un número redondo entre 5 y 20.","h2":"En New Jersey, las multas por exceso de velocidad son el doble si va a 10 mph o más sobre el límite en una zona de 65 mph.","p":"Correcto. La multa es el doble a 10 mph o más sobre el límite en una zona de 65 mph."},"zh":{"q":"在 New Jersey，在限速 65 mph 的道路上，超速多少时超速罚款会加倍？","o":["超过限速多少都会","超过 5 mph 或以上","超过 10 mph 或以上","超过 20 mph 或以上"],"h1":"它是 5 和 20 之间的一个整数。","h2":"在 New Jersey，在限速 65 mph 的路段超速 10 mph 或以上，超速罚款会加倍。","p":"对。在 65 mph 路段超速 10 mph 或以上，罚款加倍。"},"vi":{"q":"Ở New Jersey, trên đường có tốc độ tối đa 65 mph, bạn phải chạy quá tốc độ bao nhiêu thì tiền phạt bị tăng gấp đôi?","o":["Quá tốc độ bất kỳ mức nào","Quá 5 mph trở lên","Quá 10 mph trở lên","Quá 20 mph trở lên"],"h1":"Đó là một số tròn giữa 5 và 20.","h2":"Ở New Jersey, tiền phạt chạy quá tốc độ bị tăng gấp đôi khi bạn chạy quá 10 mph trở lên trong khu vực có tốc độ tối đa 65 mph.","p":"Đúng. Tiền phạt tăng gấp đôi khi quá 10 mph trở lên trong khu vực 65 mph."},"tl":{"q":"Sa New Jersey, sa daan na may 65 mph na limit, gaano kabilis lampas sa limit bago dumoble ang multa sa speeding?","o":["Kahit gaano kaliit ang lampas","5 mph o higit pa ang lampas","10 mph o higit pa ang lampas","20 mph o higit pa ang lampas"],"h1":"Isa itong bilog na numero sa pagitan ng 5 at 20.","h2":"Sa New Jersey, dumodoble ang multa sa speeding kapag 10 mph o higit pa ang lampas mo sa limit sa 65 mph na zone.","p":"Tama. Dumodoble ang multa kapag 10 mph o higit pa ang lampas sa 65 mph na zone."},"ar":{"q":"في New Jersey، على طريق حد السرعة فيه 65 mph، بكم يجب أن تتجاوز الحد حتى تتضاعف غرامة السرعة؟","o":["بأي مقدار فوق الحد","بـ 5 mph أو أكثر","بـ 10 mph أو أكثر","بـ 20 mph أو أكثر"],"h1":"إنه رقم مدوّر بين 5 و20.","h2":"في New Jersey تتضاعف غرامات السرعة إذا تجاوزت الحد بـ 10 mph أو أكثر في منطقة حد السرعة فيها 65 mph.","p":"صحيح. تتضاعف الغرامة عند تجاوز الحد بـ 10 mph أو أكثر في منطقة 65 mph."},"ref":{"doc":"NJ","page":62}},{"id":"nj-043","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points do you get for driving 15 to 29 mph over the speed limit?","o":["Two points","Three points","Five points","Four points"],"h1":"It is more than the points for going 1 to 14 mph over, and less than for 30 or more.","h2":"In New Jersey, driving 15 to 29 mph over the speed limit adds four points to your record.","p":"Right. Going 15 to 29 mph over costs four points."},"es":{"q":"En New Jersey, ¿cuántos puntos recibe por manejar de 15 a 29 mph sobre el límite de velocidad?","o":["Dos puntos","Tres puntos","Cinco puntos","Cuatro puntos"],"h1":"Es más que los puntos por ir de 1 a 14 mph sobre el límite, y menos que por ir 30 o más.","h2":"En New Jersey, manejar de 15 a 29 mph sobre el límite de velocidad agrega cuatro puntos a su historial.","p":"Correcto. Ir de 15 a 29 mph sobre el límite cuesta cuatro puntos."},"zh":{"q":"在 New Jersey，超速 15 到 29 mph 会被加多少分？","o":["两分","三分","五分","四分"],"h1":"它比超速 1 到 14 mph 的分数多，比超速 30 mph 或以上的分数少。","h2":"在 New Jersey，超速 15 到 29 mph 会在你的记录上加四分。","p":"对。超速 15 到 29 mph 会被加四分。"},"vi":{"q":"Ở New Jersey, bạn bị ghi bao nhiêu điểm khi chạy quá tốc độ tối đa từ 15 đến 29 mph?","o":["Hai điểm","Ba điểm","Năm điểm","Bốn điểm"],"h1":"Nó nhiều hơn số điểm khi quá 1 đến 14 mph, và ít hơn khi quá 30 mph trở lên.","h2":"Ở New Jersey, chạy quá tốc độ tối đa từ 15 đến 29 mph sẽ bị ghi bốn điểm vào hồ sơ của bạn.","p":"Đúng. Chạy quá 15 đến 29 mph bị ghi bốn điểm."},"tl":{"q":"Sa New Jersey, ilang puntos ang makukuha mo kapag nagmaneho ka nang 15 hanggang 29 mph lampas sa speed limit?","o":["Dalawang puntos","Tatlong puntos","Limang puntos","Apat na puntos"],"h1":"Mas marami ito kaysa sa puntos para sa 1 hanggang 14 mph na lampas, at mas kaunti kaysa sa 30 o higit pa.","h2":"Sa New Jersey, ang pagmamaneho nang 15 hanggang 29 mph lampas sa speed limit ay nagdadagdag ng apat na puntos sa record mo.","p":"Tama. Apat na puntos kapag 15 hanggang 29 mph ang lampas."},"ar":{"q":"في New Jersey، كم نقطة تحصل عليها إذا قدت بسرعة تزيد من 15 إلى 29 mph على حد السرعة؟","o":["نقطتان","ثلاث نقاط","خمس نقاط","أربع نقاط"],"h1":"إنها أكثر من نقاط تجاوز الحد بـ 1 إلى 14 mph، وأقل من نقاط تجاوزه بـ 30 أو أكثر.","h2":"في New Jersey، القيادة بسرعة تزيد من 15 إلى 29 mph على حد السرعة تضيف أربع نقاط إلى سجلّك.","p":"صحيح. تجاوز الحد بـ 15 إلى 29 mph يكلّفك أربع نقاط."},"ref":{"doc":"NJ","page":139}},{"id":"nj-044","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how many points come off your record when you finish an approved defensive driving course?","o":["Two points","Four points","Six points","All of your points"],"h1":"It is a small number, and the MVC counts the course only once every five years.","h2":"In New Jersey, finishing an approved defensive driving course takes two points off your record.","p":"Right. The course removes two points."},"es":{"q":"En New Jersey, ¿cuántos puntos se quitan de su historial cuando termina un curso aprobado de manejo defensivo?","o":["Dos puntos","Cuatro puntos","Seis puntos","Todos sus puntos"],"h1":"Es un número pequeño, y la MVC cuenta el curso solo una vez cada cinco años.","h2":"En New Jersey, terminar un curso aprobado de manejo defensivo quita dos puntos de su historial.","p":"Correcto. El curso quita dos puntos."},"zh":{"q":"在 New Jersey，你完成认可的防御性驾驶课程后，记录上会减去多少分？","o":["两分","四分","六分","全部的分"],"h1":"这是个小数字，而且 MVC 每五年只算一次这个课程。","h2":"在 New Jersey，完成认可的防御性驾驶课程会从你的记录上减去两分。","p":"对。这个课程会减去两分。"},"vi":{"q":"Ở New Jersey, hồ sơ của bạn được trừ bao nhiêu điểm khi bạn hoàn thành một khóa học lái xe phòng vệ (defensive driving course) được chấp thuận?","o":["Hai điểm","Bốn điểm","Sáu điểm","Tất cả số điểm của bạn"],"h1":"Đó là một số nhỏ, và MVC chỉ tính khóa học này một lần mỗi năm năm.","h2":"Ở New Jersey, hoàn thành một khóa học lái xe phòng vệ được chấp thuận sẽ trừ hai điểm khỏi hồ sơ của bạn.","p":"Đúng. Khóa học trừ hai điểm."},"tl":{"q":"Sa New Jersey, ilang puntos ang matatanggal sa record mo kapag natapos mo ang aprubadong defensive driving course?","o":["Dalawang puntos","Apat na puntos","Anim na puntos","Lahat ng puntos mo"],"h1":"Maliit na numero ito, at isang beses lang bawat limang taon binibilang ng MVC ang kurso.","h2":"Sa New Jersey, ang pagtatapos ng aprubadong defensive driving course ay nag-aalis ng dalawang puntos sa record mo.","p":"Tama. Nag-aalis ng dalawang puntos ang kurso."},"ar":{"q":"في New Jersey، كم نقطة تُحذف من سجلّك عندما تُنهي دورة قيادة دفاعية (defensive driving course) معتمدة؟","o":["نقطتان","أربع نقاط","ست نقاط","كل نقاطك"],"h1":"إنه عدد صغير، وMVC تحسب الدورة مرة واحدة فقط كل خمس سنوات.","h2":"في New Jersey، إنهاء دورة قيادة دفاعية معتمدة يحذف نقطتين من سجلّك.","p":"صحيح. الدورة تحذف نقطتين."},"ref":{"doc":"NJ","page":135}},{"id":"nj-045","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a new driver is convicted of two moving violations worth 4 or more points in the first two years after getting a permit. What must the driver do?","o":["Retake the knowledge test","Complete the Probationary Driver Program","Pay a $1,000 surcharge","Get a new permit and start over"],"h1":"It is a program for new drivers, run by approved driving schools and safety groups.","h2":"In New Jersey, a new driver with two or more moving violations worth 4 or more points in the two-year probationary period must complete the Probationary Driver Program.","p":"Right. The driver must complete the Probationary Driver Program."},"es":{"q":"En New Jersey, un conductor nuevo es condenado por dos infracciones de tránsito que suman 4 puntos o más en los primeros dos años después de obtener el permiso. ¿Qué debe hacer?","o":["Volver a tomar el examen de conocimientos","Completar el Probationary Driver Program (programa para conductores nuevos)","Pagar un recargo de $1,000","Obtener un permiso nuevo y empezar de cero"],"h1":"Es un programa para conductores nuevos que dan escuelas de manejo y organizaciones de seguridad aprobadas.","h2":"En New Jersey, un conductor nuevo con dos o más infracciones que suman 4 puntos o más en el período probatorio de dos años debe completar el Probationary Driver Program.","p":"Correcto. El conductor debe completar el Probationary Driver Program."},"zh":{"q":"在 New Jersey，一位新司机在拿到学习驾照后的头两年内，因两次 4 分或以上的行车违规被定罪。这位司机必须怎么做？","o":["重考知识考试","完成试用期司机课程（Probationary Driver Program）","缴纳 $1,000 附加费","重新拿学习驾照，从头开始"],"h1":"这是为新司机开设的课程，由认可的驾校和安全组织开办。","h2":"在 New Jersey，新司机在两年试用期内有两次或以上 4 分或以上的行车违规，必须完成试用期司机课程（Probationary Driver Program）。","p":"对。这位司机必须完成试用期司机课程。"},"vi":{"q":"Ở New Jersey, một người mới lái xe bị kết tội hai lỗi lái xe, mỗi lỗi từ 4 điểm trở lên, trong hai năm đầu sau khi có giấy phép tập lái. Người lái xe đó phải làm gì?","o":["Thi lại bài thi kiến thức","Hoàn thành Chương trình dành cho người lái xe tạm thời (Probationary Driver Program)","Trả khoản phụ phí $1,000","Lấy giấy phép tập lái mới và bắt đầu lại từ đầu"],"h1":"Đó là một chương trình cho người mới lái xe, do các trường dạy lái và tổ chức an toàn được chấp thuận tổ chức.","h2":"Ở New Jersey, người mới lái xe có hai lỗi lái xe trở lên, mỗi lỗi từ 4 điểm trở lên, trong thời gian tạm thời hai năm phải hoàn thành Chương trình dành cho người lái xe tạm thời (Probationary Driver Program).","p":"Đúng. Người lái xe phải hoàn thành Probationary Driver Program."},"tl":{"q":"Sa New Jersey, ang isang bagong driver ay nahatulan sa dalawang moving violation na may 4 o higit pang puntos sa unang dalawang taon pagkatapos makakuha ng permit. Ano ang dapat gawin ng driver?","o":["Ulitin ang knowledge test","Tapusin ang Probationary Driver Program","Magbayad ng $1,000 na surcharge","Kumuha ng bagong permit at magsimula ulit"],"h1":"Programa ito para sa mga bagong driver, pinapatakbo ng mga aprubadong driving school at safety group.","h2":"Sa New Jersey, ang bagong driver na may dalawa o higit pang moving violation na may 4 o higit pang puntos sa dalawang taong probationary period ay dapat tapusin ang Probationary Driver Program.","p":"Tama. Dapat tapusin ng driver ang Probationary Driver Program."},"ar":{"q":"في New Jersey، أُدين سائق جديد بمخالفتَي قيادة، لكل منهما 4 نقاط أو أكثر، في أول سنتين بعد حصوله على التصريح. ماذا يجب أن يفعل السائق؟","o":["أن يعيد اختبار المعرفة","أن يُكمل برنامج السائق تحت الاختبار (Probationary Driver Program)","أن يدفع رسومًا إضافية قدرها $1,000","أن يحصل على تصريح جديد ويبدأ من جديد"],"h1":"إنه برنامج للسائقين الجدد، تديره مدارس قيادة ومجموعات سلامة معتمدة.","h2":"في New Jersey يجب على السائق الجديد الذي لديه مخالفتا قيادة أو أكثر، لكل منها 4 نقاط أو أكثر، خلال فترة الاختبار التي مدتها سنتان أن يُكمل برنامج السائق تحت الاختبار (Probationary Driver Program).","p":"صحيح. يجب على السائق أن يُكمل برنامج السائق تحت الاختبار."},"ref":{"doc":"NJ","page":134}},{"id":"nj-046","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, a driver refuses to take a breath test. What surcharge does the driver face?","o":["$250, paid once","$500 a year for two years","$1,000 a year for three years","No surcharge, only a warning"],"h1":"It is paid every year for more than one year.","h2":"In New Jersey, a driver who refuses a breath test faces a surcharge of $1,000 a year for three years.","p":"Right. Refusing costs $1,000 a year for three years."},"es":{"q":"En New Jersey, un conductor se niega a hacerse la prueba de aliento. ¿Qué recargo le corresponde?","o":["$250, que se paga una vez","$500 al año por dos años","$1,000 al año por tres años","Ningún recargo, solo una advertencia"],"h1":"Se paga cada año, por más de un año.","h2":"En New Jersey, un conductor que se niega a la prueba de aliento debe pagar un recargo de $1,000 al año por tres años.","p":"Correcto. Negarse cuesta $1,000 al año por tres años."},"zh":{"q":"在 New Jersey，一位司机拒绝做呼气检测。这位司机要交什么附加费？","o":["$250，交一次","每年 $500，交两年","每年 $1,000，交三年","没有附加费，只有警告"],"h1":"它每年都要交，而且不止交一年。","h2":"在 New Jersey，拒绝做呼气检测的司机要交附加费，每年 $1,000，交三年。","p":"对。拒绝检测要每年交 $1,000，交三年。"},"vi":{"q":"Ở New Jersey, một người lái xe từ chối kiểm tra hơi thở (breath test). Người lái xe đó phải trả khoản phụ phí nào?","o":["$250, trả một lần","$500 mỗi năm trong hai năm","$1,000 mỗi năm trong ba năm","Không có phụ phí, chỉ bị cảnh cáo"],"h1":"Khoản này phải trả mỗi năm, trong hơn một năm.","h2":"Ở New Jersey, người lái xe từ chối kiểm tra hơi thở phải trả khoản phụ phí $1,000 mỗi năm trong ba năm.","p":"Đúng. Từ chối kiểm tra bị phụ phí $1,000 mỗi năm trong ba năm."},"tl":{"q":"Sa New Jersey, tumanggi ang isang driver na kumuha ng breath test. Anong surcharge ang haharapin ng driver?","o":["$250, isang beses babayaran","$500 bawat taon sa loob ng dalawang taon","$1,000 bawat taon sa loob ng tatlong taon","Walang surcharge, babala lang"],"h1":"Binabayaran ito bawat taon nang higit sa isang taon.","h2":"Sa New Jersey, ang driver na tumanggi sa breath test ay haharap sa surcharge na $1,000 bawat taon sa loob ng tatlong taon.","p":"Tama. Ang pagtanggi ay nagkakahalaga ng $1,000 bawat taon sa loob ng tatlong taon."},"ar":{"q":"في New Jersey، رفض سائق أن يخضع لاختبار التنفّس (breath test). ما الرسوم الإضافية التي يواجهها السائق؟","o":["$250، تُدفع مرة واحدة","$500 كل سنة لمدة سنتين","$1,000 كل سنة لمدة ثلاث سنوات","لا رسوم إضافية، تحذير فقط"],"h1":"تُدفع كل سنة لأكثر من سنة واحدة.","h2":"في New Jersey يواجه السائق الذي يرفض اختبار التنفّس رسومًا إضافية قدرها $1,000 كل سنة لمدة ثلاث سنوات.","p":"صحيح. الرفض يكلّف $1,000 كل سنة لمدة ثلاث سنوات."},"ref":{"doc":"NJ","page":127}},{"id":"nj-047","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a driver leaves the scene of a crash where someone was hurt. For a first offense, how long does the driver lose their license?","o":["30 days","Six months","For life","One year"],"h1":"Losing it for life is the penalty for doing it again.","h2":"In New Jersey, a first offense of leaving the scene of a crash where someone was hurt means losing your license for one year.","p":"Right. A first hit-and-run with injury costs your license for one year."},"es":{"q":"En New Jersey, un conductor se va del lugar de un choque donde alguien resultó herido. Por una primera infracción, ¿por cuánto tiempo pierde la licencia?","o":["30 días","Seis meses","De por vida","Un año"],"h1":"Perderla de por vida es el castigo por hacerlo otra vez.","h2":"En New Jersey, una primera infracción por irse del lugar de un choque donde alguien resultó herido significa perder la licencia por un año.","p":"Correcto. Una primera fuga con heridos le quita la licencia por un año."},"zh":{"q":"在 New Jersey，一位司机离开了有人受伤的车祸现场。第一次违法，这位司机会被吊销驾照多久？","o":["30 天","六个月","终身","一年"],"h1":"终身吊销是再犯的处罚。","h2":"在 New Jersey，第一次离开有人受伤的车祸现场，会被吊销驾照一年。","p":"对。第一次有人受伤的肇事逃逸，会被吊销驾照一年。"},"vi":{"q":"Ở New Jersey, một người lái xe bỏ đi khỏi hiện trường tai nạn có người bị thương. Với lần vi phạm đầu tiên, người lái xe đó bị mất bằng lái trong bao lâu?","o":["30 ngày","Sáu tháng","Suốt đời","Một năm"],"h1":"Mất bằng suốt đời là hình phạt khi tái phạm.","h2":"Ở New Jersey, lần vi phạm đầu tiên vì bỏ đi khỏi hiện trường tai nạn có người bị thương sẽ bị mất bằng lái một năm.","p":"Đúng. Lần đầu gây tai nạn có người bị thương rồi bỏ chạy sẽ bị mất bằng lái một năm."},"tl":{"q":"Sa New Jersey, umalis ang isang driver sa lugar ng banggaan kung saan may nasaktan. Sa unang paglabag, gaano katagal mawawala ang lisensya ng driver?","o":["30 araw","Anim na buwan","Habambuhay","Isang taon"],"h1":"Ang pagkawala nito habambuhay ay parusa kapag inulit ito.","h2":"Sa New Jersey, ang unang paglabag ng pag-alis sa lugar ng banggaan kung saan may nasaktan ay nangangahulugang mawawala ang lisensya mo nang isang taon.","p":"Tama. Ang unang hit-and-run na may nasaktan ay nagtatanggal ng lisensya mo nang isang taon."},"ar":{"q":"في New Jersey، غادر سائق مكان حادث أُصيب فيه شخص. في المخالفة الأولى، لكم من الوقت يفقد السائق رخصته؟","o":["30 يومًا","ستة أشهر","مدى الحياة","سنة واحدة"],"h1":"فقدان الرخصة مدى الحياة هو عقوبة تكرار المخالفة.","h2":"في New Jersey، المخالفة الأولى لمغادرة مكان حادث أُصيب فيه شخص تعني أن تفقد رخصتك لمدة سنة واحدة.","p":"صحيح. أول هروب من حادث فيه إصابة يكلّفك رخصتك لمدة سنة واحدة."},"ref":{"doc":"NJ","page":130}},{"id":"nj-048","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, what is the fine for a first offense of carrying an open container of alcohol in the passenger area of a car?","o":["$200","$50","$100","$1,000"],"h1":"It is a few hundred dollars, not thousands.","h2":"In New Jersey, a first offense of carrying an open container of alcohol in the passenger area of a car brings a $200 fine.","p":"Right. A first offense costs $200."},"es":{"q":"En New Jersey, ¿cuál es la multa por una primera vez de llevar un envase de alcohol abierto en el área de pasajeros de un carro?","o":["$200","$50","$100","$1,000"],"h1":"Son unos cientos de dólares, no miles.","h2":"En New Jersey, una primera infracción por llevar un envase de alcohol abierto en el área de pasajeros de un carro tiene una multa de $200.","p":"Correcto. Una primera infracción cuesta $200."},"zh":{"q":"在 New Jersey，第一次在车的乘客区放着开了封的酒，罚款是多少？","o":["$200","$50","$100","$1,000"],"h1":"是几百美元，不是几千美元。","h2":"在 New Jersey，第一次在车的乘客区放着开了封的酒，会被罚款 $200。","p":"对。第一次违法罚 $200。"},"vi":{"q":"Ở New Jersey, tiền phạt cho lần vi phạm đầu tiên vì để đồ uống có cồn đã mở nắp trong khu vực hành khách của xe là bao nhiêu?","o":["$200","$50","$100","$1,000"],"h1":"Đó là vài trăm đô la, không phải vài nghìn.","h2":"Ở New Jersey, lần vi phạm đầu tiên vì để đồ uống có cồn đã mở nắp trong khu vực hành khách của xe bị phạt $200.","p":"Đúng. Lần vi phạm đầu tiên bị phạt $200."},"tl":{"q":"Sa New Jersey, magkano ang multa sa unang paglabag ng pagdadala ng bukas na lalagyan ng alak sa bahagi ng pasahero ng kotse?","o":["$200","$50","$100","$1,000"],"h1":"Ilang daang dolyar ito, hindi libo.","h2":"Sa New Jersey, ang unang paglabag ng pagdadala ng bukas na lalagyan ng alak sa bahagi ng pasahero ng kotse ay may multang $200.","p":"Tama. $200 ang multa sa unang paglabag."},"ar":{"q":"في New Jersey، ما غرامة المخالفة الأولى لحمل وعاء كحول مفتوح في منطقة الركاب في السيارة؟","o":["$200","$50","$100","$1,000"],"h1":"إنها بضع مئات من الدولارات، وليست آلافًا.","h2":"في New Jersey، المخالفة الأولى لحمل وعاء كحول مفتوح في منطقة الركاب في السيارة تؤدي إلى غرامة قدرها $200.","p":"صحيح. المخالفة الأولى تكلّف $200."},"ref":{"doc":"NJ","page":129}},{"id":"nj-049","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, a bus has picked up passengers and signals to pull back into traffic. What must you do?","o":["Speed up and pass it before it moves","Yield and let the bus back into the lane","Yield only if it is a school bus","Honk and keep going, because the bus must wait"],"h1":"State law protects buses at this moment.","h2":"In New Jersey, you must yield to a bus that is pulling back into traffic after picking up or dropping off passengers.","p":"Right. Let the bus back into traffic."},"es":{"q":"En New Jersey, un autobús recogió pasajeros y señala que va a volver al tráfico. ¿Qué debe hacer?","o":["Acelerar y pasarlo antes de que se mueva","Ceder el paso y dejar que el autobús vuelva al carril","Ceder el paso solo si es un autobús escolar","Tocar la bocina y seguir, porque el autobús debe esperar"],"h1":"La ley del estado protege a los autobuses en este momento.","h2":"En New Jersey, usted debe ceder el paso a un autobús que vuelve al tráfico después de recoger o dejar pasajeros.","p":"Correcto. Deje que el autobús vuelva al tráfico."},"zh":{"q":"在 New Jersey，一辆公交车载完乘客后打信号要开回车流。你必须怎么做？","o":["加速，在它开动前超过去","让行，让公交车开回车道","只有校车才让行","按喇叭继续开，因为公交车必须等"],"h1":"州法律在这个时候保护公交车。","h2":"在 New Jersey，公交车上下乘客后要开回车流时，你必须让行。","p":"对。让公交车开回车流。"},"vi":{"q":"Ở New Jersey, một xe buýt vừa đón khách xong và bật tín hiệu để chạy trở lại vào dòng xe. Bạn phải làm gì?","o":["Tăng tốc và vượt qua trước khi xe buýt chạy","Nhường đường và để xe buýt trở lại làn đường","Chỉ nhường đường nếu đó là xe buýt trường học","Bấm còi và tiếp tục chạy, vì xe buýt phải đợi"],"h1":"Luật của tiểu bang bảo vệ xe buýt vào lúc này.","h2":"Ở New Jersey, bạn phải nhường đường cho xe buýt đang chạy trở lại vào dòng xe sau khi đón hoặc trả khách.","p":"Đúng. Hãy để xe buýt trở lại dòng xe."},"tl":{"q":"Sa New Jersey, nakapagsakay na ng pasahero ang isang bus at nag-signal para bumalik sa trapiko. Ano ang dapat mong gawin?","o":["Bumilis at lampasan ito bago ito umandar","Magbigay-daan at hayaang bumalik ang bus sa lane","Magbigay-daan lang kung school bus ito","Bumusina at magtuloy, dahil ang bus ang dapat maghintay"],"h1":"Pinoprotektahan ng batas ng estado ang mga bus sa sandaling ito.","h2":"Sa New Jersey, dapat kang magbigay-daan sa bus na bumabalik sa trapiko pagkatapos magsakay o magbaba ng pasahero.","p":"Tama. Hayaang bumalik ang bus sa trapiko."},"ar":{"q":"في New Jersey، حافلة أركبت ركابًا وتعطي إشارة للعودة إلى حركة السير. ماذا يجب أن تفعل؟","o":["أسرِع وتجاوزها قبل أن تتحرك","أعطِ حق المرور ودع الحافلة تعود إلى المسرب","أعطِ حق المرور فقط إذا كانت حافلة مدرسية","اضغط على البوق واستمر، لأن الحافلة يجب أن تنتظر"],"h1":"قانون الولاية يحمي الحافلات في هذه اللحظة.","h2":"في New Jersey يجب أن تعطي حق المرور لحافلة تعود إلى حركة السير بعد أن تُركب ركابًا أو تُنزلهم.","p":"صحيح. دع الحافلة تعود إلى حركة السير."},"ref":{"doc":"NJ","page":150}},{"id":"nj-050","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, how fast may you go when you come up to or pass a horse-drawn vehicle?","o":["No more than 10 mph","No more than 35 mph","No more than 25 mph","The posted speed limit"],"h1":"It is the same speed as in many school zones.","h2":"In New Jersey, you must slow to 25 mph or less when you come up to or pass a horse-drawn vehicle.","p":"Right. Slow to 25 mph or less near a horse-drawn vehicle."},"es":{"q":"En New Jersey, ¿a qué velocidad puede ir cuando se acerca a un vehículo tirado por caballos o lo pasa?","o":["A no más de 10 mph","A no más de 35 mph","A no más de 25 mph","Al límite de velocidad indicado"],"h1":"Es la misma velocidad que en muchas zonas escolares.","h2":"En New Jersey, usted debe bajar a 25 mph o menos cuando se acerca a un vehículo tirado por caballos o lo pasa.","p":"Correcto. Baje a 25 mph o menos cerca de un vehículo tirado por caballos."},"zh":{"q":"在 New Jersey，当你靠近或超过马拉的车时，最快可以开多快？","o":["不超过 10 mph","不超过 35 mph","不超过 25 mph","标示的限速"],"h1":"和很多学校区的速度一样。","h2":"在 New Jersey，当你靠近或超过马拉的车时，必须减速到 25 mph 或更低。","p":"对。在马拉的车附近要减速到 25 mph 或更低。"},"vi":{"q":"Ở New Jersey, bạn được chạy nhanh bao nhiêu khi đến gần hoặc vượt qua một xe do ngựa kéo?","o":["Không quá 10 mph","Không quá 35 mph","Không quá 25 mph","Tốc độ tối đa ghi trên biển báo"],"h1":"Đó là tốc độ giống như ở nhiều khu vực trường học.","h2":"Ở New Jersey, bạn phải giảm tốc độ xuống 25 mph hoặc thấp hơn khi đến gần hoặc vượt qua một xe do ngựa kéo.","p":"Đúng. Giảm xuống 25 mph hoặc thấp hơn gần xe do ngựa kéo."},"tl":{"q":"Sa New Jersey, gaano kabilis ka puwedeng magmaneho kapag papalapit ka o lalampas sa sasakyang hila ng kabayo?","o":["Hindi hihigit sa 10 mph","Hindi hihigit sa 35 mph","Hindi hihigit sa 25 mph","Ang nakapaskil na speed limit"],"h1":"Kapareho ito ng bilis sa maraming school zone.","h2":"Sa New Jersey, dapat kang bumagal sa 25 mph o mas mabagal kapag papalapit ka o lalampas sa sasakyang hila ng kabayo.","p":"Tama. Bumagal sa 25 mph o mas mabagal malapit sa sasakyang hila ng kabayo."},"ar":{"q":"في New Jersey، ما السرعة المسموحة لك عندما تقترب من عربة يجرّها حصان أو تتجاوزها؟","o":["لا تزيد على 10 mph","لا تزيد على 35 mph","لا تزيد على 25 mph","حد السرعة المكتوب على اللافتة"],"h1":"إنها السرعة نفسها في كثير من مناطق المدارس.","h2":"في New Jersey يجب أن تخفّف سرعتك إلى 25 mph أو أقل عندما تقترب من عربة يجرّها حصان أو تتجاوزها.","p":"صحيح. خفّف سرعتك إلى 25 mph أو أقل قرب عربة يجرّها حصان."},"ref":{"doc":"NJ","page":155}},{"id":"nj-051","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you legally change your name. How soon must you tell the MVC?","o":["Within 48 hours","Within 30 days","Within two weeks","At your next license renewal"],"h1":"It is a little longer than the time allowed for an address change.","h2":"In New Jersey, you must report a legal name change to the MVC within two weeks.","p":"Right. A name change must be reported within two weeks."},"es":{"q":"En New Jersey, usted cambia su nombre legalmente. ¿En cuánto tiempo debe informar a la MVC?","o":["En 48 horas","En 30 días","En dos semanas","En su próxima renovación de licencia"],"h1":"Es un poco más del tiempo que se permite para un cambio de dirección.","h2":"En New Jersey, usted debe informar un cambio legal de nombre a la MVC en dos semanas.","p":"Correcto. El cambio de nombre se informa en dos semanas."},"ref":{"doc":"NJ","page":4}},{"id":"nj-052","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, you move to the state with a valid license from another state. If it does not expire first, how long do you have to apply for a New Jersey license?","o":["10 days","30 days","6 months","60 days"],"h1":"It is about two months.","h2":"In New Jersey, a new resident with a valid out-of-state license must apply for a New Jersey license within 60 days, or sooner if the old license expires first.","p":"Right. New residents have 60 days."},"es":{"q":"En New Jersey, usted se muda al estado con una licencia válida de otro estado. Si no vence antes, ¿cuánto tiempo tiene para solicitar una licencia de New Jersey?","o":["10 días","30 días","6 meses","60 días"],"h1":"Son unos dos meses.","h2":"En New Jersey, un nuevo residente con una licencia válida de otro estado debe solicitar una licencia de New Jersey en 60 días, o antes si la licencia anterior vence primero.","p":"Correcto. Los nuevos residentes tienen 60 días."},"ref":{"doc":"NJ","page":4}},{"id":"nj-053","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, a person has a valid driver license from another country. How long may they drive with it?","o":["Up to one year","Up to 30 days","Up to 90 days","Not at all"],"h1":"It is longer than a few months.","h2":"In New Jersey, a person with a valid license from another country may drive with it for up to one year.","p":"Right. A valid foreign license can be used for up to a year."},"es":{"q":"En New Jersey, una persona tiene una licencia de manejo válida de otro país. ¿Por cuánto tiempo puede manejar con ella?","o":["Hasta un año","Hasta 30 días","Hasta 90 días","No puede manejar con ella"],"h1":"Es más de unos pocos meses.","h2":"En New Jersey, una persona con una licencia válida de otro país puede manejar con ella hasta un año.","p":"Correcto. Una licencia extranjera válida se puede usar hasta un año."},"ref":{"doc":"NJ","page":4}},{"id":"nj-054","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how long is a special learner permit valid?","o":["Six months","Two years","One year","Four years"],"h1":"It is more than one year.","h2":"In New Jersey, a special learner permit, which the driving instructor buys, is valid for two years.","p":"Right. The special learner permit is good for two years."},"es":{"q":"En New Jersey, ¿por cuánto tiempo es válido un permiso especial de aprendiz?","o":["Seis meses","Dos años","Un año","Cuatro años"],"h1":"Es más de un año.","h2":"En New Jersey, un permiso especial de aprendiz, que compra el instructor de manejo, es válido por dos años.","p":"Correcto. El permiso especial de aprendiz vale por dos años."},"ref":{"doc":"NJ","page":19}},{"id":"nj-055","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how old must the adult supervising a permit holder be?","o":["At least 18","At least 19","At least 21","At least 25"],"h1":"It is the age when you may legally buy alcohol.","h2":"In New Jersey, the supervising driver must be at least 21 years old and hold a valid New Jersey license.","p":"Right. The supervising driver must be at least 21."},"es":{"q":"En New Jersey, ¿qué edad debe tener el adulto que supervisa a quien tiene un permiso?","o":["Al menos 18","Al menos 19","Al menos 21","Al menos 25"],"h1":"Es la edad en que se puede comprar alcohol legalmente.","h2":"En New Jersey, el conductor supervisor debe tener al menos 21 años y una licencia válida de New Jersey.","p":"Correcto. El conductor supervisor debe tener al menos 21 años."},"ref":{"doc":"NJ","page":18}},{"id":"nj-056","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, a driver with a GDL permit has friends riding in the back seat. Who must wear a seat belt?","o":["Only the driver","Only the people in the front seat","Only passengers under 18","The driver and every passenger"],"h1":"The GDL rule covers every seat in the car.","h2":"In New Jersey, a permit or probationary driver and all passengers, in every seat, must wear seat belts.","p":"Right. Everyone in the car must buckle up."},"es":{"q":"En New Jersey, un conductor con permiso GDL lleva amigos en el asiento de atrás. ¿Quién debe usar el cinturón de seguridad?","o":["Solo el conductor","Solo las personas del asiento delantero","Solo los pasajeros menores de 18 años","El conductor y todos los pasajeros"],"h1":"La regla GDL cubre todos los asientos del carro.","h2":"En New Jersey, un conductor con permiso o licencia probatoria y todos sus pasajeros, en cualquier asiento, deben usar el cinturón de seguridad.","p":"Correcto. Todos en el carro deben abrocharse el cinturón."},"ref":{"doc":"NJ","page":18}},{"id":"nj-057","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, a 24-year-old has an examination permit. Which GDL rule still applies to this driver?","o":["No phone use at all, not even hands-free","No driving after 11:01 p.m.","Only one passenger","Red decals on the license plates"],"h1":"At 21 or older, the hour, passenger and decal limits are lifted.","h2":"In New Jersey, permit and probationary drivers 21 or older are free of the hour, passenger and decal limits, but they still may not use any phone, even hands-free.","p":"Right. The phone ban applies at any age."},"es":{"q":"En New Jersey, una persona de 24 años tiene un permiso de examen. ¿Qué regla GDL todavía se aplica a este conductor?","o":["No usar ningún teléfono, ni siquiera manos libres","No manejar después de las 11:01 p.m.","Llevar solo un pasajero","Calcomanías rojas en las placas"],"h1":"A los 21 años o más, se quitan los límites de horario, pasajeros y calcomanías.","h2":"En New Jersey, los conductores con permiso o licencia probatoria de 21 años o más no tienen los límites de horario, pasajeros y calcomanías, pero todavía no pueden usar ningún teléfono, ni siquiera manos libres.","p":"Correcto. La prohibición del teléfono se aplica a cualquier edad."},"ref":{"doc":"NJ","page":18}},{"id":"nj-058","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, where do the two red GDL decals go?","o":["On the back window and the windshield","On the top left corner of the front and rear license plates","On both front doors","Side by side on the rear bumper"],"h1":"They go on the license plates.","h2":"In New Jersey, one GDL decal goes on the top left corner of the front license plate and the other on the top left corner of the rear plate.","p":"Right. One decal goes on each plate, at the top left."},"es":{"q":"En New Jersey, ¿dónde se ponen las dos calcomanías rojas GDL?","o":["En la ventana trasera y el parabrisas","En la esquina superior izquierda de las placas delantera y trasera","En las dos puertas delanteras","Una al lado de la otra en el parachoques trasero"],"h1":"Van en las placas.","h2":"En New Jersey, una calcomanía GDL va en la esquina superior izquierda de la placa delantera y la otra en la esquina superior izquierda de la placa trasera.","p":"Correcto. Va una calcomanía en cada placa, arriba a la izquierda."},"ref":{"doc":"NJ","page":19}},{"id":"nj-059","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a 17-year-old probationary driver must drive to work after 11:01 p.m. What allows this?","o":["A note from a parent","Nothing; there are no exceptions","A signed letter from the employer on company letterhead, carried in the car","A text message from the boss"],"h1":"The exception is for work or religion, and it needs proof on paper.","h2":"In New Jersey, a GDL driver under 21 may drive during the banned hours for work or religion only with a signed letter from the employer or religious official on official letterhead.","p":"Right. A signed letter on letterhead must be carried."},"es":{"q":"En New Jersey, un conductor probatorio de 17 años debe manejar al trabajo después de las 11:01 p.m. ¿Qué le permite hacerlo?","o":["Una nota de su padre o madre","Nada; no hay excepciones","Una carta firmada por el empleador en papel con membrete de la empresa, que lleva en el carro","Un mensaje de texto de su jefe"],"h1":"La excepción es por trabajo o religión, y necesita una prueba en papel.","h2":"En New Jersey, un conductor GDL menor de 21 años puede manejar en las horas prohibidas por trabajo o religión solo con una carta firmada por el empleador o el líder religioso en papel con membrete oficial.","p":"Correcto. Debe llevar una carta firmada con membrete."},"ref":{"doc":"NJ","page":19}},{"id":"nj-060","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, your 12 months as a probationary driver are over, but you do not go to the MVC to upgrade. What happens?","o":["Your license is canceled","You must take the road test again","A basic license comes to you by mail","You must still follow the probationary restrictions"],"h1":"The upgrade does not happen by itself.","h2":"In New Jersey, a probationary driver who does not upgrade to a basic license at the MVC after 12 months stays under the probationary restrictions and can be ticketed for breaking them.","p":"Right. Until you upgrade, the probationary rules still apply."},"es":{"q":"En New Jersey, terminaron sus 12 meses como conductor probatorio, pero usted no va a la MVC para cambiar su licencia. ¿Qué pasa?","o":["Le cancelan la licencia","Debe tomar el examen de manejo otra vez","Le llega una licencia básica por correo","Todavía debe seguir las restricciones probatorias"],"h1":"El cambio no ocurre solo.","h2":"En New Jersey, un conductor probatorio que no cambia a una licencia básica en la MVC después de 12 meses sigue bajo las restricciones probatorias y puede recibir una multa si no las cumple.","p":"Correcto. Hasta que cambie la licencia, las reglas probatorias siguen vigentes."},"ref":{"doc":"NJ","page":19}},{"id":"nj-061","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how long must a permit holder who is 21 or older practice with a supervising driver before the road test?","o":["At least 3 months","At least 6 months","At least 1 month","At least 1 year"],"h1":"It is half the time required for younger drivers.","h2":"In New Jersey, a permit holder 21 or older must practice with a supervising driver for at least three months before the road test.","p":"Right. Adults practice at least three months."},"es":{"q":"En New Jersey, ¿cuánto tiempo debe practicar con un conductor supervisor quien tiene un permiso y tiene 21 años o más, antes del examen de manejo?","o":["Al menos 3 meses","Al menos 6 meses","Al menos 1 mes","Al menos 1 año"],"h1":"Es la mitad del tiempo que se exige a los conductores más jóvenes.","h2":"En New Jersey, quien tiene un permiso y tiene 21 años o más debe practicar con un conductor supervisor al menos tres meses antes del examen de manejo.","p":"Correcto. Los adultos practican al menos tres meses."},"ref":{"doc":"NJ","page":17}},{"id":"nj-062","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a 17-year-old with a valid license moves from another state. What license do they get?","o":["A basic license for four years","A probationary license for one year, with the GDL rules","Only a permit, until age 18","No license until they take a driving course"],"h1":"New Jersey's graduated license rules still apply to them.","h2":"In New Jersey, a new resident between 17 and 18 with a valid out-of-state license gets a probationary license for one year and must follow the GDL rules.","p":"Right. They get a one-year probationary license."},"es":{"q":"En New Jersey, una persona de 17 años con una licencia válida se muda desde otro estado. ¿Qué licencia recibe?","o":["Una licencia básica por cuatro años","Una licencia probatoria por un año, con las reglas GDL","Solo un permiso, hasta los 18 años","Ninguna licencia hasta que tome un curso de manejo"],"h1":"Las reglas de licencia graduada de New Jersey también se aplican a esa persona.","h2":"En New Jersey, un nuevo residente de entre 17 y 18 años con una licencia válida de otro estado recibe una licencia probatoria por un año y debe seguir las reglas GDL.","p":"Correcto. Recibe una licencia probatoria por un año."},"ref":{"doc":"NJ","page":32}},{"id":"nj-063","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, how many seconds of following distance should you keep in bad weather?","o":["Two seconds","Three seconds","Four seconds or more","One second"],"h1":"Add at least one second to the normal rule.","h2":"In New Jersey, the normal three-second following rule should grow to four seconds or more in bad weather.","p":"Right. Use four seconds or more in bad weather."},"es":{"q":"En New Jersey, ¿cuántos segundos de distancia debe dejar detrás de otro vehículo cuando hay mal tiempo?","o":["Dos segundos","Tres segundos","Cuatro segundos o más","Un segundo"],"h1":"Agregue al menos un segundo a la regla normal.","h2":"En New Jersey, la regla normal de tres segundos debe aumentar a cuatro segundos o más cuando hay mal tiempo.","p":"Correcto. Use cuatro segundos o más con mal tiempo."},"ref":{"doc":"NJ","page":95}},{"id":"nj-064","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, using the \"car length\" rule of thumb, how far back should you stay at 50 mph?","o":["One car length","Two car lengths","Three car lengths","Five car lengths"],"h1":"The rule links the number of car lengths to your speed.","h2":"In New Jersey, a common rule is to stay one car length (about 20 feet) back for each 10 mph, so five car lengths at 50 mph.","p":"Right. At 50 mph, that is five car lengths."},"es":{"q":"En New Jersey, según la regla práctica del \"largo de un carro\", ¿a qué distancia debe ir detrás de otro vehículo a 50 mph?","o":["Un largo de carro","Dos largos de carro","Tres largos de carro","Cinco largos de carro"],"h1":"La regla relaciona el número de largos de carro con su velocidad.","h2":"En New Jersey, una regla común es dejar un largo de carro (unos 20 pies) por cada 10 mph, así que cinco largos de carro a 50 mph.","p":"Correcto. A 50 mph, son cinco largos de carro."},"ref":{"doc":"NJ","page":94}},{"id":"nj-065","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, an adult passenger in the back seat is not wearing a seat belt. When can the police ticket this passenger?","o":["Only when the car is stopped for another reason","Any time the police see it","Never; back seat belts are optional for adults","Only on a highway"],"h1":"For adults in the back seat, it is a secondary offense.","h2":"In New Jersey, an unbuckled back-seat passenger 18 or older can be ticketed only when the car is stopped for another reason.","p":"Right. For adults in back, it is a secondary offense."},"es":{"q":"En New Jersey, un pasajero adulto en el asiento de atrás no usa el cinturón de seguridad. ¿Cuándo puede la policía multar a este pasajero?","o":["Solo cuando detienen el carro por otra razón","En cualquier momento en que la policía lo vea","Nunca; el cinturón atrás es opcional para adultos","Solo en una autopista"],"h1":"Para adultos en el asiento de atrás, es una infracción secundaria.","h2":"En New Jersey, a un pasajero de 18 años o más sin cinturón en el asiento de atrás solo lo pueden multar cuando detienen el carro por otra razón.","p":"Correcto. Para adultos atrás, es una infracción secundaria."},"ref":{"doc":"NJ","page":40}},{"id":"nj-066","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a child is under 2 years old and weighs less than 30 pounds. How must the child ride?","o":["In a booster seat","In a rear-facing car seat with a five-point harness","In a forward-facing seat with only a lap belt","On an adult's lap, under a seat belt"],"h1":"Babies this small face the back of the car.","h2":"In New Jersey, a child under 2 and under 30 pounds must ride in a rear-facing car seat with a five-point harness.","p":"Right. Rear-facing, with a five-point harness."},"es":{"q":"En New Jersey, un niño tiene menos de 2 años y pesa menos de 30 libras. ¿Cómo debe viajar?","o":["En un asiento elevado (booster)","En un asiento de seguridad mirando hacia atrás, con arnés de cinco puntos","En un asiento mirando hacia adelante, solo con cinturón de regazo","En las piernas de un adulto, bajo el cinturón"],"h1":"Los bebés tan pequeños van mirando hacia la parte de atrás del carro.","h2":"En New Jersey, un niño menor de 2 años y de menos de 30 libras debe viajar en un asiento de seguridad mirando hacia atrás, con arnés de cinco puntos.","p":"Correcto. Mirando hacia atrás, con arnés de cinco puntos."},"ref":{"doc":"NJ","page":42}},{"id":"nj-067","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, when is it against the law to have your backup lights on?","o":["When the car is parked","At night","While the car is moving forward","While you are backing up"],"h1":"Backup lights are for going backward.","h2":"In New Jersey, it is against the law to have backup lights on while the vehicle is moving forward.","p":"Right. Backup lights may not be on while you move forward."},"es":{"q":"En New Jersey, ¿cuándo es ilegal tener encendidas las luces de reversa?","o":["Cuando el carro está estacionado","De noche","Mientras el carro avanza hacia adelante","Mientras usted va en reversa"],"h1":"Las luces de reversa son para ir hacia atrás.","h2":"En New Jersey, es ilegal tener encendidas las luces de reversa mientras el vehículo avanza hacia adelante.","p":"Correcto. Las luces de reversa no pueden estar encendidas al avanzar."},"ref":{"doc":"NJ","page":45}},{"id":"nj-068","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, at about what speed can tires start to hydroplane on a wet road?","o":["15 mph","25 mph","55 mph","35 mph"],"h1":"It is well below highway speed.","h2":"In New Jersey, the driver manual says tires can start to hydroplane at about 35 mph on a wet road, and the risk grows as speed goes up.","p":"Right. Hydroplaning can start at about 35 mph."},"es":{"q":"En New Jersey, ¿a partir de qué velocidad, más o menos, pueden las llantas empezar a hidroplanear en un camino mojado?","o":["15 mph","25 mph","55 mph","35 mph"],"h1":"Es mucho menos que la velocidad de autopista.","h2":"En New Jersey, el manual dice que las llantas pueden empezar a hidroplanear a unas 35 mph en un camino mojado, y el riesgo aumenta con la velocidad.","p":"Correcto. El hidroplaneo puede empezar a unas 35 mph."},"ref":{"doc":"NJ","page":97}},{"id":"nj-069","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you should not drive on tires with less than how much tread?","o":["1/16 inch","1/4 inch","1/2 inch","1/32 inch"],"h1":"It is about the depth to the edge of a penny.","h2":"In New Jersey, the driver manual says not to drive on tires with less than 1/16 inch of tread.","p":"Right. 1/16 inch is the least tread you should drive on."},"es":{"q":"En New Jersey, ¿con menos de cuánta banda de rodamiento no debe manejar en sus llantas?","o":["1/16 de pulgada","1/4 de pulgada","1/2 pulgada","1/32 de pulgada"],"h1":"Es más o menos la profundidad hasta el borde de una moneda de un centavo.","h2":"En New Jersey, el manual dice que no debe manejar con llantas que tengan menos de 1/16 de pulgada de banda de rodamiento.","p":"Correcto. 1/16 de pulgada es lo mínimo para manejar."},"ref":{"doc":"NJ","page":46}},{"id":"nj-070","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, under normal conditions, from how far away must your car horn be heard?","o":["50 feet","At least 200 feet","1,000 feet","20 feet"],"h1":"It is about two-thirds of a football field.","h2":"In New Jersey, a car horn must be able to be heard from at least 200 feet under normal conditions.","p":"Right. At least 200 feet."},"es":{"q":"En New Jersey, en condiciones normales, ¿desde qué distancia se debe oír la bocina de su carro?","o":["50 pies","Al menos 200 pies","1,000 pies","20 pies"],"h1":"Son unas dos terceras partes de un campo de fútbol americano.","h2":"En New Jersey, la bocina de un carro se debe poder oír desde al menos 200 pies en condiciones normales.","p":"Correcto. Al menos 200 pies."},"ref":{"doc":"NJ","page":54}},{"id":"nj-071","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, where does the law ban add-on window tint?","o":["On the rear window only","On every window except the windshield","On the windshield and the front side windows","Nowhere; any tint is allowed"],"h1":"It covers the glass the driver looks through to the front and sides.","h2":"In New Jersey, add-on tinting is not allowed on the windshield or the front side windows.","p":"Right. No add-on tint on the windshield or front side windows."},"es":{"q":"En New Jersey, ¿dónde prohíbe la ley el polarizado añadido en las ventanas?","o":["Solo en la ventana trasera","En todas las ventanas menos el parabrisas","En el parabrisas y las ventanas laterales delanteras","En ninguna; se permite cualquier polarizado"],"h1":"Cubre el vidrio por el que el conductor mira hacia adelante y a los lados.","h2":"En New Jersey, no se permite el polarizado añadido en el parabrisas ni en las ventanas laterales delanteras.","p":"Correcto. Nada de polarizado añadido en el parabrisas ni en las ventanas laterales delanteras."},"ref":{"doc":"NJ","page":47}},{"id":"nj-072","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, ice flies off a private car and hurts someone. What fine can the driver face?","o":["$25 to $75","$50 to $100","$500 to $1,500","$200 to $1,000"],"h1":"It is much more than the fine for only not clearing the car, and less than what commercial drivers pay.","h2":"In New Jersey, when ice or snow flies from a private vehicle and causes injury, death or damage, the driver faces a fine of $200 to $1,000 each time.","p":"Right. $200 to $1,000 for a private vehicle."},"es":{"q":"En New Jersey, hielo sale volando de un carro particular y lastima a alguien. ¿Qué multa puede recibir el conductor?","o":["De $25 a $75","De $50 a $100","De $500 a $1,500","De $200 a $1,000"],"h1":"Es mucho más que la multa por solo no limpiar el carro, y menos de lo que pagan los conductores comerciales.","h2":"En New Jersey, cuando hielo o nieve sale volando de un vehículo particular y causa lesiones, muerte o daños, el conductor puede recibir una multa de $200 a $1,000 cada vez.","p":"Correcto. De $200 a $1,000 para un vehículo particular."},"ref":{"doc":"NJ","page":129}},{"id":"nj-073","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, what fine can owners face for each violation of the state's idling limit?","o":["$250 to $1,000","$25 to $50","$50 to $100","$5,000"],"h1":"It can reach four figures.","h2":"In New Jersey, vehicle and property owners can be fined $250 to $1,000 for each violation of the idling law.","p":"Right. $250 to $1,000 for each violation."},"es":{"q":"En New Jersey, ¿qué multa pueden recibir los dueños por cada violación del límite estatal de motor encendido sin moverse?","o":["De $250 a $1,000","De $25 a $50","De $50 a $100","$5,000"],"h1":"Puede llegar a cuatro cifras.","h2":"En New Jersey, los dueños de vehículos y propiedades pueden recibir una multa de $250 a $1,000 por cada violación de la ley de motor encendido sin moverse.","p":"Correcto. De $250 a $1,000 por cada violación."},"ref":{"doc":"NJ","page":50}},{"id":"nj-074","scope":"NJ","cat":"signals","sign":null,"c":1,"en":{"q":"In New Jersey, at least how far before a turn must you signal?","o":["50 feet","100 feet","300 feet","500 feet"],"h1":"It is one-third of a football field.","h2":"In New Jersey, you must move into the proper lane and signal at least 100 feet before any turn.","p":"Right. Signal at least 100 feet before you turn."},"es":{"q":"En New Jersey, ¿al menos a qué distancia antes de un giro debe poner la señal?","o":["50 pies","100 pies","300 pies","500 pies"],"h1":"Es un tercio de un campo de fútbol americano.","h2":"En New Jersey, usted debe pasar al carril correcto y poner la señal al menos 100 pies antes de cualquier giro.","p":"Correcto. Ponga la señal al menos 100 pies antes de girar."},"ref":{"doc":"NJ","page":55}},{"id":"nj-075","scope":"NJ","cat":"signals","sign":null,"c":2,"en":{"q":"In New Jersey, a bicycle rider ahead holds the right arm straight out. What does this mean?","o":["The rider will stop","The rider wants you to pass","The rider will turn right","The rider will turn left"],"h1":"Bicycle riders may point with the arm on the side they will turn toward.","h2":"In New Jersey, a bicycle rider may signal a right turn by holding the right arm straight out, instead of the left arm bent upward.","p":"Right. Right arm straight out means a right turn."},"es":{"q":"En New Jersey, un ciclista adelante extiende el brazo derecho recto hacia afuera. ¿Qué significa?","o":["El ciclista va a parar","El ciclista quiere que usted lo pase","El ciclista va a girar a la derecha","El ciclista va a girar a la izquierda"],"h1":"Los ciclistas pueden señalar con el brazo del lado hacia donde van a girar.","h2":"En New Jersey, un ciclista puede indicar un giro a la derecha extendiendo el brazo derecho recto, en vez del brazo izquierdo doblado hacia arriba.","p":"Correcto. El brazo derecho extendido indica un giro a la derecha."},"ref":{"doc":"NJ","page":54}},{"id":"nj-076","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, how fast should you drive in reverse?","o":["10 to 15 mph","5 to 10 mph","The same speed as going forward","Walking speed, about 2 to 4 mph"],"h1":"Think of how fast a person walks.","h2":"In New Jersey, you should back up slowly, at about walking speed, which is 2 to 4 mph.","p":"Right. Back up at walking speed."},"es":{"q":"En New Jersey, ¿a qué velocidad debe manejar en reversa?","o":["De 10 a 15 mph","De 5 a 10 mph","A la misma velocidad que hacia adelante","A paso de caminar, unas 2 a 4 mph"],"h1":"Piense en qué tan rápido camina una persona.","h2":"En New Jersey, debe ir en reversa despacio, más o menos a paso de caminar, que es de 2 a 4 mph.","p":"Correcto. En reversa, vaya a paso de caminar."},"ref":{"doc":"NJ","page":55}},{"id":"nj-077","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, when you park at a curb, how far from the curb may your car be?","o":["No more than 6 inches","No more than 12 inches","No more than 18 inches","No more than 2 feet"],"h1":"The car must be very close to the curb.","h2":"In New Jersey, it is against the law to park more than six inches from the curb.","p":"Right. No more than six inches from the curb."},"es":{"q":"En New Jersey, cuando se estaciona junto a la acera, ¿a qué distancia de la acera puede quedar su carro?","o":["A no más de 6 pulgadas","A no más de 12 pulgadas","A no más de 18 pulgadas","A no más de 2 pies"],"h1":"El carro debe quedar muy cerca de la acera.","h2":"En New Jersey, es ilegal estacionarse a más de seis pulgadas de la acera.","p":"Correcto. A no más de seis pulgadas de la acera."},"ref":{"doc":"NJ","page":84}},{"id":"nj-078","scope":"NJ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Jersey, you park facing uphill next to a curb. Which way do you turn your front wheels?","o":["Toward the curb","Away from the curb","Straight ahead","It does not matter if the brake is set"],"h1":"If the car rolls back, the back of a front tire should catch the curb.","h2":"In New Jersey, when you park facing uphill next to a curb, turn your front wheels away from the curb and set the parking brake.","p":"Right. Uphill with a curb: wheels away from the curb."},"es":{"q":"En New Jersey, usted se estaciona cuesta arriba junto a una acera. ¿Hacia dónde gira las llantas delanteras?","o":["Hacia la acera","Lejos de la acera","Rectas","No importa si pone el freno"],"h1":"Si el carro rueda hacia atrás, la parte de atrás de una llanta delantera debe chocar con la acera.","h2":"En New Jersey, cuando se estaciona cuesta arriba junto a una acera, gire las llantas delanteras lejos de la acera y ponga el freno de estacionamiento.","p":"Correcto. Cuesta arriba con acera: llantas lejos de la acera."},"ref":{"doc":"NJ","page":57}},{"id":"nj-079","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, unless a sign says otherwise, what is the speed limit in a school zone, business district or residential district?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is the lowest of New Jersey's general speed limits.","h2":"In New Jersey, the speed limit is 25 mph in school zones, business districts and residential districts unless a sign says otherwise.","p":"Right. 25 mph unless posted."},"es":{"q":"En New Jersey, a menos que una señal diga otra cosa, ¿cuál es el límite de velocidad en una zona escolar, zona comercial o zona residencial?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es el más bajo de los límites generales de New Jersey.","h2":"En New Jersey, el límite es de 25 mph en zonas escolares, comerciales y residenciales, a menos que una señal diga otra cosa.","p":"Correcto. 25 mph si no hay otra señal."},"ref":{"doc":"NJ","page":62}},{"id":"nj-080","scope":"NJ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Jersey, unless a sign says otherwise, what is the speed limit in suburban business and residential districts?","o":["25 mph","45 mph","50 mph","35 mph"],"h1":"It is 10 mph more than in a school zone.","h2":"In New Jersey, the speed limit in suburban business and residential districts is 35 mph unless a sign says otherwise.","p":"Right. 35 mph in suburban districts."},"es":{"q":"En New Jersey, a menos que una señal diga otra cosa, ¿cuál es el límite de velocidad en zonas comerciales y residenciales suburbanas?","o":["25 mph","45 mph","50 mph","35 mph"],"h1":"Son 10 mph más que en una zona escolar.","h2":"En New Jersey, el límite en zonas comerciales y residenciales suburbanas es de 35 mph, a menos que una señal diga otra cosa.","p":"Correcto. 35 mph en zonas suburbanas."},"ref":{"doc":"NJ","page":62}},{"id":"nj-081","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, when may you pass another car by driving on the right shoulder?","o":["Never; it is against the law","When the car ahead is turning left","When traffic is moving very slowly","When the shoulder is paved"],"h1":"The shoulder is not a travel lane.","h2":"In New Jersey, passing on the right shoulder of the road is never allowed; it is against the law.","p":"Right. Never pass on the shoulder."},"es":{"q":"En New Jersey, ¿cuándo puede rebasar a otro carro manejando por el acotamiento derecho?","o":["Nunca; es contra la ley","Cuando el carro de adelante va a girar a la izquierda","Cuando el tráfico va muy lento","Cuando el acotamiento está pavimentado"],"h1":"El acotamiento no es un carril para circular.","h2":"En New Jersey, rebasar por el acotamiento derecho nunca está permitido; es contra la ley.","p":"Correcto. Nunca rebase por el acotamiento."},"ref":{"doc":"NJ","page":65}},{"id":"nj-082","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, you stop for a person in a crosswalk on a road with two lanes going your way. How long must you stay stopped?","o":["Until the person reaches the center line","Until the person has cleared your lane and the next lane going your way","Until the person is out of your lane only","For three seconds"],"h1":"Think about the lane next to you, too.","h2":"In New Jersey, you must stay stopped until the pedestrian has safely cleared your lane and the next lane going in the same direction.","p":"Right. Wait until the person has cleared both lanes going your way."},"es":{"q":"En New Jersey, usted se detiene por una persona en un cruce peatonal, en un camino con dos carriles en su dirección. ¿Hasta cuándo debe seguir detenido?","o":["Hasta que la persona llegue a la línea central","Hasta que la persona haya salido de su carril y del carril de al lado en su dirección","Solo hasta que la persona salga de su carril","Por tres segundos"],"h1":"Piense también en el carril de al lado.","h2":"En New Jersey, usted debe seguir detenido hasta que el peatón haya salido con seguridad de su carril y del carril de al lado que va en la misma dirección.","p":"Correcto. Espere hasta que la persona haya salido de los dos carriles en su dirección."},"ref":{"doc":"NJ","page":66}},{"id":"nj-083","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, what is the highest fine for failing to stop for a pedestrian in a crosswalk?","o":["$100","$250","$500","$1,000"],"h1":"There can also be up to 25 days in jail.","h2":"In New Jersey, failing to stop for a pedestrian in a crosswalk can bring a fine of up to $500, along with up to 25 days in jail, community service, a suspension and two points.","p":"Right. The fine can be up to $500."},"es":{"q":"En New Jersey, ¿cuál es la multa más alta por no detenerse ante un peatón en un cruce peatonal?","o":["$100","$250","$500","$1,000"],"h1":"También puede haber hasta 25 días de cárcel.","h2":"En New Jersey, no detenerse ante un peatón en un cruce peatonal puede costar una multa de hasta $500, además de hasta 25 días de cárcel, servicio comunitario, una suspensión y dos puntos.","p":"Correcto. La multa puede ser de hasta $500."},"ref":{"doc":"NJ","page":66}},{"id":"nj-084","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, at a stop sign, you must stop within how many feet of the crosswalk or stop line?","o":["15 feet","10 feet","25 feet","5 feet"],"h1":"It is very close to the line.","h2":"In New Jersey, at a stop sign you must come to a complete stop within five feet of the nearest crosswalk or stop line.","p":"Right. Stop within five feet of the line."},"es":{"q":"En New Jersey, en una señal de alto, ¿a cuántos pies del cruce peatonal o de la línea de alto debe detenerse?","o":["A 15 pies","A 10 pies","A 25 pies","A 5 pies"],"h1":"Es muy cerca de la línea.","h2":"En New Jersey, en una señal de alto debe detenerse por completo a no más de cinco pies del cruce peatonal o de la línea de alto más cercana.","p":"Correcto. Deténgase a no más de cinco pies de la línea."},"ref":{"doc":"NJ","page":67}},{"id":"nj-085","scope":"NJ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Jersey, to avoid a red light, a driver cuts through a gas station lot at the corner. What is true?","o":["It is a traffic violation that carries 2 points","It is legal because the lot is private property","It is legal if no one else is in the lot","It is only a parking ticket"],"h1":"Using any property to get around a light or sign is against the law.","h2":"In New Jersey, driving over public or private property to avoid a traffic signal or sign is a violation that carries 2 points.","p":"Right. It is a violation, with 2 points."},"es":{"q":"En New Jersey, para evitar un semáforo en rojo, un conductor cruza por el lote de una gasolinera en la esquina. ¿Qué es cierto?","o":["Es una infracción de tránsito que lleva 2 puntos","Es legal porque el lote es propiedad privada","Es legal si no hay nadie más en el lote","Es solo una multa de estacionamiento"],"h1":"Usar cualquier propiedad para evitar un semáforo o una señal es contra la ley.","h2":"En New Jersey, manejar por una propiedad pública o privada para evitar un semáforo o una señal es una infracción que lleva 2 puntos.","p":"Correcto. Es una infracción, con 2 puntos."},"ref":{"doc":"NJ","page":138}},{"id":"nj-086","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, a traffic light is dark because of a power failure. How should you treat the intersection?","o":["As a green light for the bigger road","As a 4-way stop","As a yield sign","As a flashing yellow light"],"h1":"Every driver must stop.","h2":"In New Jersey, when a traffic signal is out because of a power failure or other problem, you must treat the intersection as a 4-way stop.","p":"Right. A dark signal means a 4-way stop."},"es":{"q":"En New Jersey, un semáforo está apagado por una falla de electricidad. ¿Cómo debe tratar la intersección?","o":["Como una luz verde para la calle más grande","Como un alto en los 4 sentidos","Como una señal de ceder el paso","Como una luz amarilla intermitente"],"h1":"Todos los conductores deben detenerse.","h2":"En New Jersey, cuando un semáforo está apagado por una falla de electricidad u otro problema, debe tratar la intersección como un alto en los 4 sentidos.","p":"Correcto. Un semáforo apagado es un alto en los 4 sentidos."},"ref":{"doc":"NJ","page":68}},{"id":"nj-087","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you are not sure who has the right-of-way in a traffic circle. What basic rule should you follow?","o":["The bigger vehicle goes first","A car already in the circle always goes first","The vehicle on the left yields to the vehicle on the right","The vehicle on the right yields to the vehicle on the left"],"h1":"Use the rule for an intersection with no signs or signals.","h2":"In New Jersey, when in doubt in a traffic circle, the vehicle on the left yields to the vehicle coming from the right.","p":"Right. Left yields to right."},"es":{"q":"En New Jersey, usted no está seguro de quién tiene el derecho de paso en un círculo de tránsito. ¿Qué regla básica debe seguir?","o":["El vehículo más grande pasa primero","Un carro que ya está en el círculo siempre pasa primero","El vehículo de la izquierda cede el paso al de la derecha","El vehículo de la derecha cede el paso al de la izquierda"],"h1":"Use la regla de una intersección sin señales ni semáforos.","h2":"En New Jersey, si tiene dudas en un círculo de tránsito, el vehículo de la izquierda cede el paso al vehículo que viene por la derecha.","p":"Correcto. El de la izquierda cede al de la derecha."},"ref":{"doc":"NJ","page":68}},{"id":"nj-088","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, in a weave lane, a car coming onto the expressway and a car leaving it meet. Who must yield?","o":["The car leaving the expressway","Whichever car is slower","Neither; both keep their speed","The car coming onto the expressway"],"h1":"Think about which driver is joining the road.","h2":"In New Jersey, in a weave lane, the driver entering from the ramp must yield to the driver leaving the expressway.","p":"Right. Entering traffic yields to exiting traffic."},"es":{"q":"En New Jersey, en un carril de entrecruce, se encuentran un carro que entra a la autopista y uno que sale. ¿Quién debe ceder el paso?","o":["El carro que sale de la autopista","El carro más lento","Ninguno; los dos mantienen su velocidad","El carro que entra a la autopista"],"h1":"Piense en cuál conductor se está uniendo a la vía.","h2":"En New Jersey, en un carril de entrecruce, el conductor que entra desde la rampa debe ceder el paso al conductor que sale de la autopista.","p":"Correcto. El que entra cede el paso al que sale."},"ref":{"doc":"NJ","page":70}},{"id":"nj-089","scope":"NJ","cat":"signals","sign":null,"c":0,"en":{"q":"In New Jersey, a railroad crossing's red lights are flashing. At least how far from the crossing must you stop?","o":["15 feet","5 feet","50 feet","100 feet"],"h1":"It is about the length of one car.","h2":"In New Jersey, when railroad lights flash, bells ring or gates are down, you must stop at least 15 feet from the crossing.","p":"Right. Stop at least 15 feet away."},"es":{"q":"En New Jersey, las luces rojas de un cruce de tren están intermitentes. ¿Al menos a qué distancia del cruce debe detenerse?","o":["15 pies","5 pies","50 pies","100 pies"],"h1":"Es más o menos el largo de un carro.","h2":"En New Jersey, cuando las luces del tren parpadean, suenan las campanas o las barreras están bajas, debe detenerse al menos a 15 pies del cruce.","p":"Correcto. Deténgase al menos a 15 pies."},"ref":{"doc":"NJ","page":76}},{"id":"nj-090","scope":"NJ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Jersey, within how many feet of a railroad crossing may you NOT pass another vehicle?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is twice the no-parking distance for a railroad crossing.","h2":"In New Jersey, you may not pass other vehicles within 100 feet of a railroad crossing.","p":"Right. No passing within 100 feet of a crossing."},"es":{"q":"En New Jersey, ¿a cuántos pies de un cruce de tren NO puede rebasar a otro vehículo?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es el doble de la distancia en que no se puede estacionar cerca de un cruce de tren.","h2":"En New Jersey, no puede rebasar a otros vehículos a menos de 100 pies de un cruce de tren.","p":"Correcto. No rebase a menos de 100 pies de un cruce."},"ref":{"doc":"NJ","page":153}},{"id":"nj-091","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, a private car with flashing blue lights comes up behind you. Who is most likely driving it?","o":["A police detective","A tow truck driver","A volunteer firefighter or rescue squad member going to an emergency","A school bus driver"],"h1":"These are volunteers using their own cars.","h2":"In New Jersey, volunteer fire and rescue squad members answering an emergency call in their own cars use blue lights; it is a courtesy, not a legal duty, to make way for them when you safely can.","p":"Right. Blue lights on a private car mean a volunteer fire or rescue member."},"es":{"q":"En New Jersey, un carro particular con luces azules intermitentes se acerca por detrás. ¿Quién es más probable que lo maneje?","o":["Un detective de la policía","Un conductor de grúa","Un bombero o rescatista voluntario que va a una emergencia","Un conductor de autobús escolar"],"h1":"Son voluntarios que usan sus propios carros.","h2":"En Nueva Jersey, los voluntarios de bomberos y de rescate que responden a una emergencia en sus propios carros usan luces azules; abrirles paso cuando pueda hacerlo con seguridad es una cortesía, no una obligación legal.","p":"Correcto. Luces azules en un carro particular indican un bombero o rescatista voluntario."},"ref":{"doc":"NJ","page":78}},{"id":"nj-092","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, it is daytime and raining lightly. You turn on your windshield wipers. What else must you turn on?","o":["Your hazard lights","Your high beams","Only your parking lights","Your headlights"],"h1":"Other drivers need to see you in the rain.","h2":"In New Jersey, headlights must be on whenever you use your windshield wipers in rain, snow or ice.","p":"Right. Wipers on means headlights on."},"es":{"q":"En New Jersey, es de día y llueve un poco. Usted enciende los limpiaparabrisas. ¿Qué más debe encender?","o":["Las luces de emergencia","Las luces altas","Solo las luces de estacionamiento","Los faros delanteros"],"h1":"Los otros conductores necesitan verlo bajo la lluvia.","h2":"En New Jersey, los faros deben estar encendidos siempre que use los limpiaparabrisas por lluvia, nieve o hielo.","p":"Correcto. Con limpiaparabrisas, faros encendidos."},"ref":{"doc":"NJ","page":83}},{"id":"nj-093","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, during what hours must your headlights be on?","o":["From half an hour after sunset until half an hour before sunrise","From exactly sunset until exactly sunrise","From one hour after sunset until one hour before sunrise","From 8 p.m. to 6 a.m."],"h1":"The time is counted from sunset and sunrise.","h2":"In New Jersey, headlights must be on from half an hour after sunset until half an hour before sunrise.","p":"Right. Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En New Jersey, ¿en qué horas deben estar encendidos sus faros?","o":["Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Desde la puesta del sol exacta hasta la salida del sol exacta","Desde una hora después de la puesta del sol hasta una hora antes de la salida del sol","De 8 p.m. a 6 a.m."],"h1":"El tiempo se cuenta desde la puesta y la salida del sol.","h2":"En New Jersey, los faros deben estar encendidos desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Desde media hora después de la puesta del sol hasta media hora antes de la salida."},"ref":{"doc":"NJ","page":83}},{"id":"nj-094","scope":"NJ","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Jersey, how close to a stop sign may you park?","o":["No closer than 25 feet","No closer than 50 feet","No closer than 10 feet","No closer than 100 feet"],"h1":"It is the same distance as for a railroad crossing.","h2":"In New Jersey, you may not park within 50 feet of a stop sign.","p":"Right. Stay at least 50 feet from a stop sign."},"es":{"q":"En New Jersey, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["No a menos de 25 pies","No a menos de 50 pies","No a menos de 10 pies","No a menos de 100 pies"],"h1":"Es la misma distancia que para un cruce de tren.","h2":"En New Jersey, no puede estacionarse a menos de 50 pies de una señal de alto.","p":"Correcto. Quédese al menos a 50 pies de una señal de alto."},"ref":{"doc":"NJ","page":85}},{"id":"nj-095","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is half the distance for a stop sign.","h2":"In New Jersey, you may not park within 25 feet of a crosswalk at an intersection.","p":"Right. Stay at least 25 feet from the crosswalk."},"es":{"q":"En New Jersey, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 10 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 50 pies"],"h1":"Es la mitad de la distancia para una señal de alto.","h2":"En New Jersey, no puede estacionarse a menos de 25 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese al menos a 25 pies del cruce peatonal."},"ref":{"doc":"NJ","page":85}},{"id":"nj-096","scope":"NJ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Jersey, how close may you park to the driveway of a fire station, on the same side of the street?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 75 feet","No closer than 20 feet"],"h1":"On the other side of the street, the distance is much bigger: 75 feet.","h2":"In New Jersey, you may not park within 20 feet of a fire station driveway, or within 75 feet of it on the opposite side of the street.","p":"Right. 20 feet on the same side."},"es":{"q":"En New Jersey, ¿qué tan cerca de la entrada de una estación de bomberos puede estacionarse, en el mismo lado de la calle?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 75 pies","No a menos de 20 pies"],"h1":"En el otro lado de la calle, la distancia es mucho mayor: 75 pies.","h2":"En New Jersey, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos, ni a menos de 75 pies de ella en el lado opuesto de la calle.","p":"Correcto. 20 pies en el mismo lado."},"ref":{"doc":"NJ","page":85}},{"id":"nj-097","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you have a basic license. You see a crash and use your hand-held phone to call for help while driving. What must you do?","o":["Keep one hand on the steering wheel","Use only the speakerphone","Hold the phone with both hands","Nothing; this call is never allowed"],"h1":"Emergency calls are allowed, with one condition.","h2":"In New Jersey, a hand-held phone may be used in emergencies such as a fire, crash or medical emergency, but the driver must keep one hand on the steering wheel.","p":"Right. Keep one hand on the wheel."},"es":{"q":"En New Jersey, usted tiene una licencia básica. Ve un choque y usa su teléfono en la mano para pedir ayuda mientras maneja. ¿Qué debe hacer?","o":["Mantener una mano en el volante","Usar solo el altavoz","Sostener el teléfono con las dos manos","Nada; esta llamada nunca está permitida"],"h1":"Las llamadas de emergencia están permitidas, con una condición.","h2":"En New Jersey, se puede usar un teléfono en la mano en emergencias como un incendio, un choque o una emergencia médica, pero el conductor debe mantener una mano en el volante.","p":"Correcto. Mantenga una mano en el volante."},"ref":{"doc":"NJ","page":86}},{"id":"nj-098","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, how many points go on your record for a third conviction for using a hand-held phone while driving?","o":["None","3 points","2 points","6 points"],"h1":"Points are added only from the third offense.","h2":"In New Jersey, a third or later conviction for using a hand-held phone while driving adds 3 points, and there may also be a 90-day suspension.","p":"Right. 3 points for a third offense."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su récord por una tercera condena por usar un teléfono en la mano mientras maneja?","o":["Ninguno","3 puntos","2 puntos","6 puntos"],"h1":"Los puntos se agregan solo a partir de la tercera infracción.","h2":"En New Jersey, una tercera condena o más por usar un teléfono en la mano mientras maneja agrega 3 puntos, y también puede haber una suspensión de 90 días.","p":"Correcto. 3 puntos por la tercera infracción."},"ref":{"doc":"NJ","page":139}},{"id":"nj-099","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, what number can you dial on a cell phone to report an aggressive driver?","o":["411","311","#77","*55"],"h1":"It starts with the pound sign.","h2":"In New Jersey, you can report an aggressive driver by dialing #77 on a cell phone, or by calling (888) SAF-ROAD.","p":"Right. Dial #77."},"es":{"q":"En New Jersey, ¿qué número puede marcar en un celular para reportar a un conductor agresivo?","o":["411","311","#77","*55"],"h1":"Empieza con el signo de número (#).","h2":"En New Jersey, puede reportar a un conductor agresivo marcando #77 en un celular, o llamando al (888) SAF-ROAD.","p":"Correcto. Marque #77."},"ref":{"doc":"NJ","page":91}},{"id":"nj-100","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, what does Maggie's Law make illegal?","o":["Driving with a pet on your lap","Texting while stopped at a red light","Driving without headlights in the rain","Knowingly driving while impaired by lack of sleep"],"h1":"It is about being too tired.","h2":"In New Jersey, Maggie's Law makes it illegal to knowingly drive while impaired by lack of sleep, and treats it as recklessness in a vehicular homicide case.","p":"Right. Knowingly driving while too tired is illegal."},"es":{"q":"En New Jersey, ¿qué prohíbe la Ley de Maggie?","o":["Manejar con una mascota en las piernas","Enviar mensajes de texto detenido en un semáforo en rojo","Manejar sin faros bajo la lluvia","Manejar a sabiendas con falta de sueño que lo afecta"],"h1":"Trata de estar demasiado cansado.","h2":"En New Jersey, la Ley de Maggie prohíbe manejar a sabiendas cuando la falta de sueño lo afecta, y lo trata como imprudencia en un caso de homicidio con vehículo.","p":"Correcto. Es ilegal manejar a sabiendas cuando está demasiado cansado."},"ref":{"doc":"NJ","page":92}},{"id":"nj-101","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, who is called a \"habitual offender\"?","o":["A driver whose license was suspended three times in three years","A driver with two speeding tickets in one year","A driver who failed the road test three times","A driver who paid a surcharge late twice"],"h1":"Think of license suspensions, not tickets.","h2":"In New Jersey, a habitual offender is a driver whose license has been suspended three times in three years.","p":"Right. Three suspensions in three years makes a habitual offender."},"es":{"q":"En New Jersey, ¿a quién se le llama \"infractor habitual\" (habitual offender)?","o":["A un conductor cuya licencia fue suspendida tres veces en tres años","A un conductor con dos multas por exceso de velocidad en un año","A un conductor que reprobó el examen de manejo tres veces","A un conductor que pagó tarde un recargo dos veces"],"h1":"Piense en suspensiones de licencia, no en multas.","h2":"En New Jersey, un infractor habitual es un conductor cuya licencia ha sido suspendida tres veces en tres años.","p":"Correcto. Tres suspensiones en tres años lo hacen infractor habitual."},"ref":{"doc":"NJ","page":122}},{"id":"nj-102","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for a first DUI with a blood alcohol level of at least 0.08% but under 0.10%?","o":["$50 to $100","$250 to $400","$1,000 to $2,500","$5,000"],"h1":"It is a few hundred dollars, before the many added fees and surcharges.","h2":"In New Jersey, a first DUI with a blood alcohol level from 0.08% up to 0.10% carries a fine of $250 to $400, plus many fees and surcharges.","p":"Right. The fine is $250 to $400, plus fees and surcharges."},"es":{"q":"En New Jersey, ¿cuál es la multa por un primer DUI con un nivel de alcohol en la sangre de 0.08% o más, pero menos de 0.10%?","o":["De $50 a $100","De $250 a $400","De $1,000 a $2,500","$5,000"],"h1":"Son unos cientos de dólares, antes de las muchas tarifas y recargos que se suman.","h2":"En New Jersey, un primer DUI con un nivel de alcohol en la sangre de 0.08% a menos de 0.10% tiene una multa de $250 a $400, más muchas tarifas y recargos.","p":"Correcto. La multa es de $250 a $400, más tarifas y recargos."},"ref":{"doc":"NJ","page":123}},{"id":"nj-103","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, after a first DUI, how long must the driver spend at an Intoxicated Driver Resource Center (IDRC)?","o":["One hour","7 days","12 to 48 hours","6 months"],"h1":"It is counted in hours, not days.","h2":"In New Jersey, a first DUI requires 12 to 48 hours at an Intoxicated Driver Resource Center (IDRC).","p":"Right. A first DUI means 12 to 48 hours at an IDRC."},"es":{"q":"En New Jersey, después de un primer DUI, ¿cuánto tiempo debe pasar el conductor en un Intoxicated Driver Resource Center (IDRC, centro para conductores intoxicados)?","o":["Una hora","7 días","De 12 a 48 horas","6 meses"],"h1":"Se cuenta en horas, no en días.","h2":"En New Jersey, un primer DUI exige pasar de 12 a 48 horas en un Intoxicated Driver Resource Center (IDRC).","p":"Correcto. Un primer DUI significa de 12 a 48 horas en un IDRC."},"ref":{"doc":"NJ","page":123}},{"id":"nj-104","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a driver under 21 is caught with a blood alcohol level of 0.03%. For a first offense, how long is the license suspended?","o":["No suspension, only a warning","1 to 2 years","10 years","30 to 90 days"],"h1":"It is between one and three months.","h2":"In New Jersey, a first offense by a driver under 21 with a blood alcohol level from 0.01% up to 0.08% brings a license suspension of 30 to 90 days.","p":"Right. The suspension is 30 to 90 days."},"es":{"q":"En New Jersey, a un conductor menor de 21 años lo detienen con un nivel de alcohol en la sangre de 0.03%. Por una primera infracción, ¿por cuánto tiempo suspenden la licencia?","o":["No la suspenden, solo hay una advertencia","De 1 a 2 años","10 años","De 30 a 90 días"],"h1":"Es entre uno y tres meses.","h2":"En New Jersey, una primera infracción de un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.01% a menos de 0.08% trae una suspensión de licencia de 30 a 90 días.","p":"Correcto. La suspensión es de 30 a 90 días."},"ref":{"doc":"NJ","page":124}},{"id":"nj-105","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, how much community service does a first underage drinking-and-driving offense (blood alcohol 0.01% to under 0.08%) bring?","o":["15 to 30 days","None","One day","6 months"],"h1":"It is between two weeks and one month.","h2":"In New Jersey, a first offense by a driver under 21 with a blood alcohol level from 0.01% up to 0.08% brings 15 to 30 days of community service.","p":"Right. It brings 15 to 30 days of community service."},"es":{"q":"En New Jersey, ¿cuánto servicio comunitario trae una primera infracción de un menor de 21 años por manejar con alcohol (de 0.01% a menos de 0.08%)?","o":["De 15 a 30 días","Ninguno","Un día","6 meses"],"h1":"Es entre dos semanas y un mes.","h2":"En New Jersey, una primera infracción de un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.01% a menos de 0.08% trae de 15 a 30 días de servicio comunitario.","p":"Correcto. Trae de 15 a 30 días de servicio comunitario."},"ref":{"doc":"NJ","page":124}},{"id":"nj-106","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a driver is convicted of a first alcohol DUI with a blood alcohol level below 0.15%. How long does the driver lose their license?","o":["For exactly one week","Until an ignition interlock device is put in the car","For 10 years","The driver never loses the license"],"h1":"It depends on a device that tests the driver's breath.","h2":"In New Jersey, a first alcohol DUI with a blood alcohol level below 0.15% means losing the license until an ignition interlock device is installed.","p":"Right. The license is lost until an ignition interlock is installed."},"es":{"q":"En New Jersey, condenan a un conductor por un primer DUI por alcohol con un nivel en la sangre de menos de 0.15%. ¿Por cuánto tiempo pierde la licencia?","o":["Exactamente una semana","Hasta que se instala en el auto un dispositivo de bloqueo de encendido (ignition interlock)","10 años","El conductor nunca pierde la licencia"],"h1":"Depende de un aparato que revisa el aliento del conductor.","h2":"En New Jersey, un primer DUI por alcohol con un nivel en la sangre de menos de 0.15% significa perder la licencia hasta que se instala un dispositivo de bloqueo de encendido.","p":"Correcto. Pierde la licencia hasta que se instala el dispositivo de bloqueo."},"ref":{"doc":"NJ","page":125}},{"id":"nj-107","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, how long is the license suspended for a first alcohol DUI with a blood alcohol level of 0.15% or higher?","o":["One day","30 days","3 months","8 years"],"h1":"It is a season of the year: a quarter of a year.","h2":"In New Jersey, a first alcohol DUI with a blood alcohol level of 0.15% or higher brings a 3-month license suspension, plus an ignition interlock during the suspension and after.","p":"Right. The suspension is 3 months, with an ignition interlock too."},"es":{"q":"En New Jersey, ¿por cuánto tiempo suspenden la licencia por un primer DUI por alcohol con un nivel en la sangre de 0.15% o más?","o":["Un día","30 días","3 meses","8 años"],"h1":"Es una estación del año: la cuarta parte de un año.","h2":"En New Jersey, un primer DUI por alcohol con un nivel en la sangre de 0.15% o más trae una suspensión de licencia de 3 meses, más un dispositivo de bloqueo de encendido durante la suspensión y después.","p":"Correcto. La suspensión es de 3 meses, con dispositivo de bloqueo también."},"ref":{"doc":"NJ","page":125}},{"id":"nj-108","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, how long does a driver lose their license for a second DUI within 10 years of the first?","o":["30 days","3 months","For life","1 to 2 years"],"h1":"It is counted in years, but not many.","h2":"In New Jersey, a second DUI within 10 years of the first means losing the license for 1 to 2 years.","p":"Right. A second DUI means 1 to 2 years without a license."},"es":{"q":"En New Jersey, ¿por cuánto tiempo pierde la licencia un conductor por un segundo DUI dentro de 10 años del primero?","o":["30 días","3 meses","De por vida","De 1 a 2 años"],"h1":"Se cuenta en años, pero no son muchos.","h2":"En New Jersey, un segundo DUI dentro de 10 años del primero significa perder la licencia de 1 a 2 años.","p":"Correcto. Un segundo DUI significa de 1 a 2 años sin licencia."},"ref":{"doc":"NJ","page":125}},{"id":"nj-109","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, how long does a driver lose their license for a third DUI within 10 years of the second?","o":["8 years","6 months","2 years","20 years"],"h1":"It is close to a decade, but less.","h2":"In New Jersey, a third DUI within 10 years of the second means losing the license for 8 years.","p":"Right. A third DUI means losing the license for 8 years."},"es":{"q":"En New Jersey, ¿por cuánto tiempo pierde la licencia un conductor por un tercer DUI dentro de 10 años del segundo?","o":["8 años","6 meses","2 años","20 años"],"h1":"Es casi una década, pero menos.","h2":"En New Jersey, un tercer DUI dentro de 10 años del segundo significa perder la licencia por 8 años.","p":"Correcto. Un tercer DUI significa perder la licencia por 8 años."},"ref":{"doc":"NJ","page":126}},{"id":"nj-110","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, what is the fine for a first offense of driving with no insurance?","o":["$25 to $50","$300 to $1,000","$100","$10,000 to $20,000"],"h1":"It starts at a few hundred dollars and can reach a thousand.","h2":"In New Jersey, a first offense of driving with no insurance carries a fine of $300 to $1,000, plus a yearly surcharge and loss of the license.","p":"Right. The fine is $300 to $1,000."},"es":{"q":"En New Jersey, ¿cuál es la multa por una primera infracción de manejar sin seguro?","o":["De $25 a $50","De $300 a $1,000","$100","De $10,000 a $20,000"],"h1":"Empieza en unos cientos de dólares y puede llegar a mil.","h2":"En New Jersey, una primera infracción de manejar sin seguro tiene una multa de $300 a $1,000, más un recargo anual y la pérdida de la licencia.","p":"Correcto. La multa es de $300 a $1,000."},"ref":{"doc":"NJ","page":126}},{"id":"nj-111","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, a driver is convicted of driving while having illegal drugs in the car. How long can the driver lose their license?","o":["One week","30 days","2 years","No license loss, only a fine"],"h1":"It is more than one year.","h2":"In New Jersey, a driver convicted of driving while possessing drugs can lose their license for 2 years, along with a fine of at least $50.","p":"Right. The license can be lost for 2 years."},"es":{"q":"En New Jersey, condenan a un conductor por manejar con drogas ilegales en el auto. ¿Por cuánto tiempo puede perder la licencia?","o":["Una semana","30 días","2 años","No pierde la licencia, solo paga una multa"],"h1":"Es más de un año.","h2":"En New Jersey, un conductor condenado por manejar con drogas en su poder puede perder la licencia por 2 años, además de una multa de al menos $50.","p":"Correcto. Puede perder la licencia por 2 años."},"ref":{"doc":"NJ","page":126}},{"id":"nj-112","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, an ignition interlock device will not let the car start if the driver's blood alcohol is above what level?","o":["0.01%","0.08%","0.15%","0.05%"],"h1":"It is lower than the legal limit for adults.","h2":"In New Jersey, an ignition interlock device stops the car from starting if the driver's blood alcohol is above 0.05%.","p":"Right. The device blocks starting above 0.05%."},"es":{"q":"En New Jersey, ¿por encima de qué nivel de alcohol en la sangre del conductor un dispositivo de bloqueo de encendido (ignition interlock) no deja arrancar el auto?","o":["0.01%","0.08%","0.15%","0.05%"],"h1":"Es más bajo que el límite legal para adultos.","h2":"En New Jersey, un dispositivo de bloqueo de encendido no deja arrancar el auto si el alcohol en la sangre del conductor es mayor de 0.05%.","p":"Correcto. El dispositivo no deja arrancar con más de 0.05%."},"ref":{"doc":"NJ","page":127}},{"id":"nj-113","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, after a second DUI, how long must the driver keep an ignition interlock after getting the license back?","o":["2 to 4 years","One week","3 months","It is never required"],"h1":"It is counted in years.","h2":"In New Jersey, after a second DUI, the driver must have an ignition interlock during the suspension and for 2 to 4 years after the license is restored.","p":"Right. It stays for 2 to 4 years after the license comes back."},"es":{"q":"En New Jersey, después de un segundo DUI, ¿por cuánto tiempo debe tener el conductor un dispositivo de bloqueo de encendido después de recuperar la licencia?","o":["De 2 a 4 años","Una semana","3 meses","Nunca se exige"],"h1":"Se cuenta en años.","h2":"En New Jersey, después de un segundo DUI, el conductor debe tener un dispositivo de bloqueo de encendido durante la suspensión y de 2 a 4 años después de recuperar la licencia.","p":"Correcto. Se queda de 2 a 4 años después de recuperar la licencia."},"ref":{"doc":"NJ","page":127}},{"id":"nj-114","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, besides the fine, what court surcharge is added for each conviction for unsafe driving?","o":["$5","$250","$25","$2,500"],"h1":"It is a few hundred dollars, every time.","h2":"In New Jersey, each unsafe driving conviction adds a $250 court surcharge on top of the fine.","p":"Right. Each unsafe driving offense adds a $250 surcharge."},"es":{"q":"En New Jersey, además de la multa, ¿qué recargo de la corte se suma por cada condena por manejar de forma insegura (unsafe driving)?","o":["$5","$250","$25","$2,500"],"h1":"Son unos cientos de dólares, cada vez.","h2":"En New Jersey, cada condena por manejar de forma insegura suma un recargo de la corte de $250 además de la multa.","p":"Correcto. Cada infracción por manejo inseguro suma un recargo de $250."},"ref":{"doc":"NJ","page":128}},{"id":"nj-115","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, for a first offense of reckless driving, what jail time is possible?","o":["None; it is only a warning","Exactly one night","Up to 60 days","At least 5 years"],"h1":"It is up to about two months.","h2":"In New Jersey, a first offense of reckless driving can bring up to 60 days in jail, a fine of $50 to $200, or both, plus points.","p":"Right. Reckless driving can mean up to 60 days in jail."},"es":{"q":"En New Jersey, por una primera infracción de manejo temerario (reckless driving), ¿qué tiempo de cárcel es posible?","o":["Ninguno; es solo una advertencia","Exactamente una noche","Hasta 60 días","Al menos 5 años"],"h1":"Es hasta unos dos meses.","h2":"En New Jersey, una primera infracción de manejo temerario puede traer hasta 60 días de cárcel, una multa de $50 a $200, o ambas, además de puntos.","p":"Correcto. El manejo temerario puede significar hasta 60 días de cárcel."},"ref":{"doc":"NJ","page":129}},{"id":"nj-116","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, a vehicle is left on a limited-access highway without permission. After how long is it considered abandoned?","o":["15 minutes","7 days","30 days","4 hours or more"],"h1":"It is counted in hours, not days.","h2":"In New Jersey, leaving a vehicle on a limited-access highway for 4 hours or more without permission counts as abandoning it, with a fine and possible license loss.","p":"Right. Four hours or more counts as abandoning it."},"es":{"q":"En New Jersey, un vehículo se deja en una autopista de acceso limitado sin permiso. ¿Después de cuánto tiempo se considera abandonado?","o":["15 minutos","7 días","30 días","4 horas o más"],"h1":"Se cuenta en horas, no en días.","h2":"En New Jersey, dejar un vehículo en una autopista de acceso limitado por 4 horas o más sin permiso cuenta como abandonarlo, con multa y posible pérdida de la licencia.","p":"Correcto. Cuatro horas o más cuenta como abandono."},"ref":{"doc":"NJ","page":129}},{"id":"nj-117","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, you get a ticket for speeding in a highway construction zone. What happens to the fine?","o":["It is doubled","It is cut in half","It stays the same","It is replaced by a warning"],"h1":"Work zones carry heavier penalties.","h2":"In New Jersey, fines for speeding and other moving violations are doubled in highway construction zones.","p":"Right. Fines are doubled in construction zones."},"es":{"q":"En New Jersey, le ponen una multa por exceso de velocidad en una zona de construcción de la carretera. ¿Qué pasa con la multa?","o":["Es el doble","Se reduce a la mitad","Es igual","Se cambia por una advertencia"],"h1":"Las zonas de trabajo tienen castigos más fuertes.","h2":"En New Jersey, las multas por exceso de velocidad y otras infracciones de manejo son el doble en las zonas de construcción de carreteras.","p":"Correcto. Las multas son el doble en zonas de construcción."},"ref":{"doc":"NJ","page":129}},{"id":"nj-118","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, what fine can a driver face for a hit-and-run in which someone is hurt or killed?","o":["$50 to $100","$2,500 to $5,000","$200 to $400","$100,000"],"h1":"It is several thousand dollars.","h2":"In New Jersey, a hit-and-run with injury or death can bring a fine of $2,500 to $5,000, up to 180 days in jail, or both.","p":"Right. The fine is $2,500 to $5,000."},"es":{"q":"En New Jersey, ¿qué multa puede recibir un conductor que huye de un choque (hit-and-run) en el que alguien resulta herido o muerto?","o":["De $50 a $100","De $2,500 a $5,000","De $200 a $400","$100,000"],"h1":"Son varios miles de dólares.","h2":"En New Jersey, huir de un choque con heridos o muertos puede traer una multa de $2,500 a $5,000, hasta 180 días de cárcel, o ambas.","p":"Correcto. La multa es de $2,500 a $5,000."},"ref":{"doc":"NJ","page":130}},{"id":"nj-119","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, what is the fine for a first offense of driving while your license is suspended?","o":["$25","$75","$500","$10,000"],"h1":"It is a round number of several hundred dollars.","h2":"In New Jersey, a first offense of driving while suspended brings a $500 fine and up to six more months of suspension.","p":"Right. The fine is $500, and the suspension can grow."},"es":{"q":"En New Jersey, ¿cuál es la multa por una primera infracción de manejar con la licencia suspendida?","o":["$25","$75","$500","$10,000"],"h1":"Es un número redondo de varios cientos de dólares.","h2":"En New Jersey, una primera infracción de manejar con la licencia suspendida trae una multa de $500 y hasta seis meses más de suspensión.","p":"Correcto. La multa es de $500, y la suspensión puede aumentar."},"ref":{"doc":"NJ","page":130}},{"id":"nj-120","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a court orders a driver to put an ignition interlock in the car. The driver drives without installing it. What extra penalty follows?","o":["A warning letter only","A $10 fine","Two points off the record","One more year of license suspension"],"h1":"It adds time without a license.","h2":"In New Jersey, driving after failing to install a court-ordered ignition interlock brings a one-year suspension on top of any other suspension.","p":"Right. It adds a one-year suspension."},"es":{"q":"En New Jersey, una corte ordena a un conductor instalar un dispositivo de bloqueo de encendido. El conductor maneja sin instalarlo. ¿Qué castigo extra recibe?","o":["Solo una carta de advertencia","Una multa de $10","Le quitan dos puntos del historial","Un año más de suspensión de licencia"],"h1":"Suma tiempo sin licencia.","h2":"En New Jersey, manejar sin instalar un dispositivo de bloqueo de encendido ordenado por la corte trae una suspensión de un año además de cualquier otra suspensión.","p":"Correcto. Suma un año de suspensión."},"ref":{"doc":"NJ","page":131}},{"id":"nj-121","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you let a friend drive your car, knowing their license is suspended for DUI. For a first offense, what fine can you get?","o":["$1,000","$10","$50","No fine; only the driver is punished"],"h1":"The owner is punished too, with a fine in the thousands.","h2":"In New Jersey, an owner who knowingly lets a person with a DUI suspension drive the car faces a $1,000 fine, up to 15 days in jail, or both, plus up to six months of license and registration suspension.","p":"Right. The owner can be fined $1,000."},"es":{"q":"En New Jersey, usted deja que un amigo maneje su auto, sabiendo que tiene la licencia suspendida por DUI. Por una primera infracción, ¿qué multa puede recibir usted?","o":["$1,000","$10","$50","Ninguna; solo castigan al conductor"],"h1":"También castigan al dueño, con una multa de miles de dólares.","h2":"En New Jersey, un dueño que a sabiendas deja manejar su auto a una persona suspendida por DUI puede recibir una multa de $1,000, hasta 15 días de cárcel, o ambas, más hasta seis meses de suspensión de licencia y registro.","p":"Correcto. Al dueño le pueden poner una multa de $1,000."},"ref":{"doc":"NJ","page":132}},{"id":"nj-122","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a parent is convicted of DUI while their child under 18 was riding in the car. What extra penalty can the parent get?","o":["Nothing extra","Up to 6 months of license suspension and up to 5 days of community service","Only a $5 fee","A free safety class instead of the DUI penalty"],"h1":"Having a minor in the car makes the DUI worse, not better.","h2":"In New Jersey, a parent or guardian convicted of DUI with a minor in the car is guilty of a disorderly persons offense and faces up to 6 months of license suspension and up to 5 days of community service.","p":"Right. The parent faces up to 6 months of suspension and up to 5 days of community service."},"es":{"q":"En New Jersey, condenan a un padre por DUI mientras su hijo menor de 18 años iba en el auto. ¿Qué castigo extra puede recibir?","o":["Nada extra","Hasta 6 meses de suspensión de licencia y hasta 5 días de servicio comunitario","Solo una tarifa de $5","Una clase de seguridad gratis en lugar del castigo por DUI"],"h1":"Llevar a un menor en el auto hace el DUI más grave, no menos.","h2":"En New Jersey, un padre o tutor condenado por DUI con un menor en el auto comete un delito menor (disorderly persons offense) y puede recibir hasta 6 meses de suspensión de licencia y hasta 5 días de servicio comunitario.","p":"Correcto. Puede recibir hasta 6 meses de suspensión y hasta 5 días de servicio comunitario."},"ref":{"doc":"NJ","page":133}},{"id":"nj-123","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a driver builds up 12 points on their record. What does the MVC send?","o":["A thank-you letter","A new license with a gold star","A Notice of Scheduled Suspension","Nothing until the driver reaches 30 points"],"h1":"At this many points, the license is in danger.","h2":"In New Jersey, a driver who builds up 12 or more points receives a Notice of Scheduled Suspension from the MVC by mail.","p":"Right. The MVC mails a Notice of Scheduled Suspension."},"es":{"q":"En New Jersey, un conductor acumula 12 puntos en su historial. ¿Qué le envía la MVC?","o":["Una carta de agradecimiento","Una licencia nueva con una estrella dorada","Un aviso de suspensión programada (Notice of Scheduled Suspension)","Nada hasta que llegue a 30 puntos"],"h1":"Con tantos puntos, la licencia está en peligro.","h2":"En New Jersey, un conductor que acumula 12 puntos o más recibe por correo un aviso de suspensión programada de la MVC.","p":"Correcto. La MVC envía por correo un aviso de suspensión programada."},"ref":{"doc":"NJ","page":133}},{"id":"nj-124","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points come off your record when you finish a Driver Improvement Program?","o":["One point","Six points","All your points","Three points"],"h1":"It is one more than a defensive driving course removes.","h2":"In New Jersey, finishing a Driver Improvement Program removes three points from your record.","p":"Right. A Driver Improvement Program removes three points."},"es":{"q":"En New Jersey, ¿cuántos puntos se quitan de su historial cuando termina un Driver Improvement Program (programa para mejorar el manejo)?","o":["Un punto","Seis puntos","Todos sus puntos","Tres puntos"],"h1":"Es uno más de los que quita un curso de manejo defensivo.","h2":"En New Jersey, terminar un Driver Improvement Program quita tres puntos de su historial.","p":"Correcto. El Driver Improvement Program quita tres puntos."},"ref":{"doc":"NJ","page":134}},{"id":"nj-125","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, you finish a Driver Improvement Program. What happens if you get a moving violation in the next year?","o":["A suspension of your license is scheduled","Nothing; the program protects you for five years","You only get a warning","Your points are doubled but nothing else happens"],"h1":"After the program, you are on probation for a while.","h2":"In New Jersey, after a Driver Improvement Program you are on probation for one year, and any moving violation in that year leads to a scheduled suspension.","p":"Right. A moving violation in that year leads to a scheduled suspension."},"es":{"q":"En New Jersey, usted termina un Driver Improvement Program. ¿Qué pasa si recibe una infracción de manejo en el año siguiente?","o":["Se programa una suspensión de su licencia","Nada; el programa lo protege por cinco años","Solo recibe una advertencia","Se duplican sus puntos, pero no pasa nada más"],"h1":"Después del programa, usted queda a prueba por un tiempo.","h2":"En New Jersey, después de un Driver Improvement Program usted queda a prueba por un año, y cualquier infracción de manejo en ese año lleva a una suspensión programada.","p":"Correcto. Una infracción en ese año lleva a una suspensión programada."},"ref":{"doc":"NJ","page":134}},{"id":"nj-126","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a driver has 6 points posted within three years. What yearly surcharge must they pay?","o":["$6","$150","$1,000","None; points never bring a surcharge"],"h1":"It is more than $100 but much less than $1,000. Each extra point adds $25.","h2":"In New Jersey, 6 points within three years bring a $150 surcharge, plus $25 for each point over six.","p":"Right. Six points bring a $150 surcharge."},"es":{"q":"En New Jersey, un conductor tiene 6 puntos registrados en tres años. ¿Qué recargo anual debe pagar?","o":["$6","$150","$1,000","Ninguno; los puntos nunca traen recargo"],"h1":"Es más de $100 pero mucho menos de $1,000. Cada punto extra suma $25.","h2":"En New Jersey, 6 puntos en tres años traen un recargo de $150, más $25 por cada punto por encima de seis.","p":"Correcto. Seis puntos traen un recargo de $150."},"ref":{"doc":"NJ","page":136}},{"id":"nj-127","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you get a moving violation while driving in another state. How many points go on your New Jersey record?","o":["None","Five points","Two points","Eight points"],"h1":"It is the same small number for any out-of-state moving violation.","h2":"In New Jersey, two points are added to your record for a moving violation in another state.","p":"Right. An out-of-state violation adds two points."},"es":{"q":"En New Jersey, usted recibe una infracción de manejo en otro estado. ¿Cuántos puntos se agregan a su historial de New Jersey?","o":["Ninguno","Cinco puntos","Dos puntos","Ocho puntos"],"h1":"Es el mismo número pequeño para cualquier infracción fuera del estado.","h2":"En New Jersey, se agregan dos puntos a su historial por una infracción de manejo en otro estado.","p":"Correcto. Una infracción fuera del estado agrega dos puntos."},"ref":{"doc":"NJ","page":137}},{"id":"nj-128","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points go on your record for racing on a highway?","o":["One point","Two points","Three points","Five points"],"h1":"Racing is one of the most serious violations on the chart.","h2":"In New Jersey, racing on a highway adds five points to your record.","p":"Right. Racing costs five points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por hacer carreras en una carretera?","o":["Un punto","Dos puntos","Tres puntos","Cinco puntos"],"h1":"Las carreras son de las infracciones más graves de la tabla.","h2":"En New Jersey, hacer carreras en una carretera agrega cinco puntos a su historial.","p":"Correcto. Las carreras cuestan cinco puntos."},"ref":{"doc":"NJ","page":138}},{"id":"nj-129","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how many points go on your record for tailgating (following too closely)?","o":["Five points","No points","One point","Two points"],"h1":"It counts as much as reckless driving.","h2":"In New Jersey, tailgating adds five points to your record.","p":"Right. Tailgating costs five points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por seguir demasiado cerca a otro vehículo (tailgating)?","o":["Cinco puntos","Ningún punto","Un punto","Dos puntos"],"h1":"Cuenta tanto como el manejo temerario.","h2":"En New Jersey, seguir demasiado cerca a otro vehículo agrega cinco puntos a su historial.","p":"Correcto. Seguir demasiado cerca cuesta cinco puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-130","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many points go on your record for passing a school bus illegally?","o":["One point","Five points","Two points","Twelve points"],"h1":"It is one of the highest point values for a single violation, but not the highest.","h2":"In New Jersey, improperly passing a school bus adds five points to your record.","p":"Right. Passing a school bus illegally costs five points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por pasar un autobús escolar de forma ilegal?","o":["Un punto","Cinco puntos","Dos puntos","Doce puntos"],"h1":"Es uno de los valores más altos para una sola infracción, pero no el más alto.","h2":"En New Jersey, pasar un autobús escolar de forma indebida agrega cinco puntos a su historial.","p":"Correcto. Pasar un autobús escolar ilegalmente cuesta cinco puntos."},"ref":{"doc":"NJ","page":140}},{"id":"nj-131","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how many points go on your record for leaving the scene of a crash in which someone was hurt?","o":["Two points","Three points","Eight points","Four points"],"h1":"It is the highest point value on the chart.","h2":"In New Jersey, leaving the scene of a crash with personal injury adds eight points to your record.","p":"Right. It costs eight points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por irse del lugar de un choque en el que alguien resultó herido?","o":["Dos puntos","Tres puntos","Ocho puntos","Cuatro puntos"],"h1":"Es el valor más alto de la tabla.","h2":"En New Jersey, irse del lugar de un choque con heridos agrega ocho puntos a su historial.","p":"Correcto. Cuesta ocho puntos."},"ref":{"doc":"NJ","page":140}},{"id":"nj-132","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how many points go on your record for an improper U-turn?","o":["No points","Five points","Eight points","Three points"],"h1":"It is the same as an improper right or left turn.","h2":"In New Jersey, an improper U-turn adds three points to your record.","p":"Right. An improper U-turn costs three points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por una vuelta en U indebida?","o":["Ningún punto","Cinco puntos","Ocho puntos","Tres puntos"],"h1":"Es lo mismo que una vuelta indebida a la derecha o a la izquierda.","h2":"En New Jersey, una vuelta en U indebida agrega tres puntos a su historial.","p":"Correcto. Una vuelta en U indebida cuesta tres puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-133","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, how many points go on your record for driving 1 to 14 mph over the speed limit?","o":["Two points","No points","Four points","Five points"],"h1":"It is the lowest point value for speeding.","h2":"In New Jersey, driving 1 to 14 mph over the speed limit adds two points to your record.","p":"Right. Going 1 to 14 mph over costs two points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por manejar de 1 a 14 mph sobre el límite de velocidad?","o":["Dos puntos","Ningún punto","Cuatro puntos","Cinco puntos"],"h1":"Es el valor más bajo de puntos por exceso de velocidad.","h2":"En New Jersey, manejar de 1 a 14 mph sobre el límite de velocidad agrega dos puntos a su historial.","p":"Correcto. Ir de 1 a 14 mph sobre el límite cuesta dos puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-134","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a car hits a person walking. If the car is going 40 mph instead of 20 mph, how does the chance the person dies change?","o":["It stays about the same","From about 5 percent to about 85 percent","From about 50 percent to about 55 percent","It goes down, because the crash is shorter"],"h1":"Speed makes a huge difference for people on foot.","h2":"In New Jersey, about 5 percent of pedestrians hit at 20 mph die, but about 85 percent die when hit at 40 mph.","p":"Right. The death rate jumps from about 5 percent to about 85 percent."},"es":{"q":"En New Jersey, un auto atropella a una persona que camina. Si el auto va a 40 mph en vez de 20 mph, ¿cómo cambia la probabilidad de que la persona muera?","o":["Queda más o menos igual","De un 5 por ciento a un 85 por ciento, más o menos","De un 50 por ciento a un 55 por ciento, más o menos","Baja, porque el choque es más corto"],"h1":"La velocidad hace una diferencia enorme para la gente a pie.","h2":"En New Jersey, alrededor del 5 por ciento de los peatones atropellados a 20 mph mueren, pero alrededor del 85 por ciento mueren a 40 mph.","p":"Correcto. La tasa de muerte sube de un 5 a un 85 por ciento, más o menos."},"ref":{"doc":"NJ","page":144}},{"id":"nj-135","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, a person started crossing on a WALK signal. The signal changes to DON'T WALK while they are still in the crosswalk. What must you do?","o":["Honk so they hurry","Drive around them","Stay stopped until the person is out of your way","Go, because the signal now favors you"],"h1":"The person started legally and still has the right to finish.","h2":"In New Jersey, if a person began crossing on WALK and the signal changes to DON'T WALK, you must stay stopped and let them finish crossing.","p":"Right. You stay stopped and let the person finish."},"es":{"q":"En New Jersey, una persona empezó a cruzar con la señal WALK (camine). La señal cambia a DON'T WALK (no camine) mientras todavía está en el cruce. ¿Qué debe hacer usted?","o":["Tocar la bocina para que se apure","Rodearla con el auto","Seguir detenido hasta que la persona ya no esté en su camino","Avanzar, porque ahora la señal lo favorece a usted"],"h1":"La persona empezó a cruzar legalmente y todavía tiene derecho a terminar.","h2":"En New Jersey, si una persona empezó a cruzar con WALK y la señal cambia a DON'T WALK, usted debe seguir detenido y dejarla terminar de cruzar.","p":"Correcto. Usted sigue detenido y deja que la persona termine."},"ref":{"doc":"NJ","page":144}},{"id":"nj-136","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, in bad weather, how much longer can a truck, tractor-trailer or bus take to stop?","o":["It stops in the same distance","It stops in a shorter distance than in good weather","Exactly twice as long, always","As much as 25 percent longer"],"h1":"It is about one quarter longer.","h2":"In New Jersey, in bad weather a truck, tractor-trailer or bus can take as much as 25 percent longer to stop.","p":"Right. It can take as much as 25 percent longer."},"es":{"q":"En New Jersey, con mal tiempo, ¿cuánto más le puede costar detenerse a un camión, un tractor-remolque o un autobús?","o":["Se detiene en la misma distancia","Se detiene en menos distancia que con buen tiempo","Exactamente el doble, siempre","Hasta un 25 por ciento más"],"h1":"Es alrededor de una cuarta parte más.","h2":"En New Jersey, con mal tiempo un camión, un tractor-remolque o un autobús puede tardar hasta un 25 por ciento más en detenerse.","p":"Correcto. Puede tardar hasta un 25 por ciento más."},"ref":{"doc":"NJ","page":147}},{"id":"nj-137","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, a large truck is coming toward you from the other direction on a two-way road. What should you do?","o":["Keep to the right side of your lane","Move toward the center line","Speed up to pass it quickly","Flash your high beams at it"],"h1":"Space between you and the truck cuts the wind blast.","h2":"In New Jersey, when a large vehicle comes toward you from the other direction, you should keep to the right to reduce wind turbulence and avoid a sideswipe.","p":"Right. Keeping right reduces the wind and helps avoid a sideswipe."},"es":{"q":"En New Jersey, un camión grande viene hacia usted en dirección contraria en una calle de doble sentido. ¿Qué debe hacer?","o":["Mantenerse en el lado derecho de su carril","Acercarse a la línea central","Acelerar para cruzarse rápido","Hacerle cambio de luces altas"],"h1":"El espacio entre usted y el camión reduce el golpe de viento.","h2":"En New Jersey, cuando un vehículo grande viene hacia usted en dirección contraria, debe mantenerse a la derecha para reducir la turbulencia del viento y evitar un roce lateral.","p":"Correcto. Mantenerse a la derecha reduce el viento y ayuda a evitar un roce."},"ref":{"doc":"NJ","page":150}},{"id":"nj-138","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, what fine can a driver face for not yielding to a bus that is pulling back into traffic from a stop?","o":["$5","$50 to $200","$1,000 to $2,500","No fine; it is only a courtesy"],"h1":"It is a fine of up to a couple hundred dollars, and jail of up to 15 days is possible.","h2":"In New Jersey, not yielding to a bus re-entering traffic after a stop can bring a fine of $50 to $200, up to 15 days in jail, or both.","p":"Right. The fine is $50 to $200."},"es":{"q":"En New Jersey, ¿qué multa puede recibir un conductor que no le cede el paso a un autobús que vuelve al tráfico después de una parada?","o":["$5","De $50 a $200","De $1,000 a $2,500","Ninguna; es solo una cortesía"],"h1":"Es una multa de hasta un par de cientos de dólares, y es posible la cárcel de hasta 15 días.","h2":"En New Jersey, no ceder el paso a un autobús que vuelve al tráfico después de una parada puede traer una multa de $50 a $200, hasta 15 días de cárcel, o ambas.","p":"Correcto. La multa es de $50 a $200."},"ref":{"doc":"NJ","page":150}},{"id":"nj-139","scope":"NJ","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Jersey, what is the top speed a moped (motorized bicycle) rider may go?","o":["10 mph","45 mph","25 mph","The same as the posted limit for cars"],"h1":"It is the same as the usual limit in a school zone.","h2":"In New Jersey, a moped rider may not go faster than 25 mph and must ride on the right with the flow of traffic.","p":"Right. Mopeds may not go over 25 mph."},"es":{"q":"En New Jersey, ¿cuál es la velocidad máxima a la que puede ir una persona en un moped (bicicleta motorizada)?","o":["10 mph","45 mph","25 mph","La misma que el límite indicado para autos"],"h1":"Es lo mismo que el límite habitual en una zona escolar.","h2":"En New Jersey, una persona en moped no puede ir a más de 25 mph y debe circular por la derecha, en la dirección del tráfico.","p":"Correcto. Los mopeds no pueden ir a más de 25 mph."},"ref":{"doc":"NJ","page":150}},{"id":"nj-140","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, what must a bicycle ridden after dark have?","o":["Only a bell","Only a flag on a pole","Nothing; bicycles need no lights","A front light, a rear light and a rear reflector"],"h1":"It needs lights at both ends, plus something that reflects at the back.","h2":"In New Jersey, a bicycle ridden after dark must have front and rear lights and a rear reflector.","p":"Right. It needs front and rear lights and a rear reflector."},"es":{"q":"En New Jersey, ¿qué debe tener una bicicleta que se usa de noche?","o":["Solo una campana","Solo una bandera en un palo","Nada; las bicicletas no necesitan luces","Una luz delantera, una luz trasera y un reflector trasero"],"h1":"Necesita luces en los dos extremos, y algo que refleje atrás.","h2":"En New Jersey, una bicicleta que se usa de noche debe tener luces delantera y trasera y un reflector trasero.","p":"Correcto. Necesita luces delantera y trasera y un reflector trasero."},"ref":{"doc":"NJ","page":151}},{"id":"nj-141","scope":"NJ","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Jersey, a person riding a horse toward you raises a hand to signal you. What must you do?","o":["Stop and stay stopped until the horse has passed","Honk to warn the rider","Speed up and pass quickly","Flash your headlights and keep going"],"h1":"The law protects the horse from being frightened.","h2":"In New Jersey, if a person riding or driving a horse from the other direction signals you, you must stop and stay stopped as long as it takes the horse to pass.","p":"Right. You stop and wait until the horse has passed."},"es":{"q":"En New Jersey, una persona que viene a caballo hacia usted levanta la mano para hacerle una señal. ¿Qué debe hacer?","o":["Detenerse y quedarse detenido hasta que el caballo haya pasado","Tocar la bocina para avisarle al jinete","Acelerar y pasar rápido","Hacer cambio de luces y seguir"],"h1":"La ley protege al caballo para que no se asuste.","h2":"En New Jersey, si una persona a caballo o en un vehículo tirado por caballos que viene en dirección contraria le hace una señal, usted debe detenerse y quedarse detenido el tiempo que tarde el caballo en pasar.","p":"Correcto. Usted se detiene y espera hasta que pase el caballo."},"ref":{"doc":"NJ","page":155}},{"id":"nj-142","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, you move to the state with a car registered somewhere else. How long do you have to title and register it in New Jersey?","o":["7 days","60 days, or sooner if the old registration expires","6 months","One year"],"h1":"It is about two months.","h2":"In New Jersey, a new resident must title and register their vehicle within 60 days, or sooner if the out-of-state registration expires first.","p":"Right. You have 60 days, or less if the old registration runs out."},"es":{"q":"En New Jersey, usted se muda al estado con un auto registrado en otro lugar. ¿Cuánto tiempo tiene para titularlo y registrarlo en New Jersey?","o":["7 días","60 días, o antes si vence el registro anterior","6 meses","Un año"],"h1":"Son unos dos meses.","h2":"En New Jersey, un nuevo residente debe titular y registrar su vehículo en 60 días, o antes si el registro de otro estado vence primero.","p":"Correcto. Tiene 60 días, o menos si vence el registro anterior."},"ref":{"doc":"NJ","page":158}},{"id":"nj-143","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, how high above the ground must a car's license plates be mounted?","o":["Touching the ground","At least 60 inches","At least 12 inches but less than 48 inches","Any height, as long as they are on the car"],"h1":"It is between about one foot and four feet.","h2":"In New Jersey, license plates must be mounted at least 12 inches but less than 48 inches above the ground.","p":"Right. Plates go between 12 and 48 inches above the ground."},"es":{"q":"En New Jersey, ¿a qué altura del suelo deben ir las placas de un auto?","o":["Tocando el suelo","Al menos a 60 pulgadas","Al menos a 12 pulgadas, pero a menos de 48 pulgadas","A cualquier altura, siempre que estén en el auto"],"h1":"Es entre un pie y cuatro pies, más o menos.","h2":"En New Jersey, las placas deben ir al menos a 12 pulgadas, pero a menos de 48 pulgadas del suelo.","p":"Correcto. Las placas van entre 12 y 48 pulgadas del suelo."},"ref":{"doc":"NJ","page":159}},{"id":"nj-144","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, at night, from how far away must the lighted rear license plate be visible?","o":["5 feet","500 feet","One mile","50 feet"],"h1":"It is a short distance, less than 100 feet.","h2":"In New Jersey, the rear license plate must be lit so it can be seen from 50 feet at night, even if it is reflective.","p":"Right. It must be visible from 50 feet at night."},"es":{"q":"En New Jersey, de noche, ¿desde qué distancia debe verse la placa trasera iluminada?","o":["5 pies","500 pies","Una milla","50 pies"],"h1":"Es una distancia corta, menos de 100 pies.","h2":"En New Jersey, la placa trasera debe estar iluminada para que se vea desde 50 pies de noche, aunque sea reflectante.","p":"Correcto. Debe verse desde 50 pies de noche."},"ref":{"doc":"NJ","page":159}},{"id":"nj-145","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, one of your license plates is damaged. How soon should you replace it at an MVC Vehicle Center?","o":["Within 24 hours","Within 30 days","At your next registration renewal","Never; one plate is enough"],"h1":"It is very soon: about one day.","h2":"In New Jersey, lost or damaged license plates should be replaced at an MVC Vehicle Center within 24 hours.","p":"Right. Replace it within 24 hours."},"es":{"q":"En New Jersey, una de sus placas está dañada. ¿En cuánto tiempo debe reemplazarla en un MVC Vehicle Center?","o":["En 24 horas","En 30 días","En su próxima renovación de registro","Nunca; una placa es suficiente"],"h1":"Es muy pronto: más o menos un día.","h2":"En New Jersey, las placas perdidas o dañadas se deben reemplazar en un MVC Vehicle Center en 24 horas.","p":"Correcto. Reemplácela en 24 horas."},"ref":{"doc":"NJ","page":159}},{"id":"nj-146","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how often must a gasoline passenger car that is more than five model years old pass state inspection?","o":["Every month","Every two years","Every six months","Only once, when it is sold"],"h1":"It is less often than once a year.","h2":"In New Jersey, gasoline passenger cars more than five model years old must pass state inspection every two years.","p":"Right. Inspection is every two years."},"es":{"q":"En New Jersey, ¿cada cuánto tiempo debe pasar la inspección estatal un auto de pasajeros de gasolina con más de cinco años de modelo?","o":["Cada mes","Cada dos años","Cada seis meses","Solo una vez, cuando se vende"],"h1":"Es menos de una vez al año.","h2":"En New Jersey, los autos de pasajeros de gasolina con más de cinco años de modelo deben pasar la inspección estatal cada dos años.","p":"Correcto. La inspección es cada dos años."},"ref":{"doc":"NJ","page":160}},{"id":"nj-147","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you move to the state with a passenger car that is five model years old or older. How soon after registering it must you get it inspected?","o":["Within 24 hours","Within one year","Within 14 days","It does not need inspection"],"h1":"It is two weeks.","h2":"In New Jersey, a new resident must have a passenger car that is five model years old or older inspected within 14 days after registering it.","p":"Right. It must be inspected within 14 days."},"es":{"q":"En New Jersey, usted se muda al estado con un auto de pasajeros de cinco años de modelo o más. ¿En cuánto tiempo después de registrarlo debe inspeccionarlo?","o":["En 24 horas","En un año","En 14 días","No necesita inspección"],"h1":"Son dos semanas.","h2":"En New Jersey, un nuevo residente debe inspeccionar un auto de pasajeros de cinco años de modelo o más en 14 días después de registrarlo.","p":"Correcto. Debe inspeccionarlo en 14 días."},"ref":{"doc":"NJ","page":160}},{"id":"nj-148","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, you cancel the insurance on your car and do not replace it. What must you do with the license plates?","o":["Keep them on the car","Give them to the next owner","Throw them away","Return them to the MVC"],"h1":"A car without insurance may not stay registered for the road.","h2":"In New Jersey, if you no longer have insurance on a vehicle, you must surrender its license plates to the MVC.","p":"Right. You must return the plates to the MVC."},"es":{"q":"En New Jersey, usted cancela el seguro de su auto y no lo reemplaza. ¿Qué debe hacer con las placas?","o":["Dejarlas en el auto","Dárselas al próximo dueño","Tirarlas a la basura","Devolverlas a la MVC"],"h1":"Un auto sin seguro no puede seguir registrado para usar la calle.","h2":"En New Jersey, si ya no tiene seguro en un vehículo, debe entregar sus placas a la MVC.","p":"Correcto. Debe devolver las placas a la MVC."},"ref":{"doc":"NJ","page":161}},{"id":"nj-149","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, you make an emergency stop on a highway shoulder. You put one warning device just behind the car. How far back should the second one go?","o":["At least 300 feet, about 120 paces","About 10 feet","About 50 feet","One mile"],"h1":"It is about the length of a football field.","h2":"In New Jersey, after an emergency stop you should place one warning device just behind the vehicle and another at least 300 feet back, about 120 paces.","p":"Right. The second device goes at least 300 feet back."},"es":{"q":"En New Jersey, usted hace una parada de emergencia en el acotamiento de una carretera. Pone un aviso de advertencia justo detrás del auto. ¿A qué distancia debe ir el segundo?","o":["Al menos a 300 pies, unos 120 pasos","A unos 10 pies","A unos 50 pies","A una milla"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En New Jersey, después de una parada de emergencia debe poner un aviso de advertencia justo detrás del vehículo y otro al menos a 300 pies atrás, unos 120 pasos.","p":"Correcto. El segundo aviso va al menos a 300 pies atrás."},"ref":{"doc":"NJ","page":105}},{"id":"nj-150","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, your right wheels drift off the pavement onto the shoulder. How slow should you be going before you steer back onto the road?","o":["Any speed; steer back right away","25 mph or less","At least 45 mph","You must stop fully and call for help"],"h1":"It is a low speed, well under 30 mph.","h2":"In New Jersey, if your wheels drift onto the shoulder, ease off the gas and wait until you have slowed to 25 mph or less, then turn the wheel about a quarter turn back onto the road.","p":"Right. Slow to 25 mph or less before steering back."},"es":{"q":"En New Jersey, sus ruedas derechas se salen del pavimento hacia el acotamiento. ¿A qué velocidad debe bajar antes de volver a la calle?","o":["A cualquier velocidad; vuelva de inmediato","A 25 mph o menos","Al menos a 45 mph","Debe detenerse por completo y pedir ayuda"],"h1":"Es una velocidad baja, bastante menos de 30 mph.","h2":"En New Jersey, si sus ruedas se salen al acotamiento, suelte el acelerador y espere a bajar a 25 mph o menos; luego gire el volante un cuarto de vuelta para volver a la calle.","p":"Correcto. Baje a 25 mph o menos antes de volver."},"ref":{"doc":"NJ","page":105}},{"id":"nj-151","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, what is the fine for a first DUI with a blood alcohol level of 0.10% or higher?","o":["$300 to $500","$25 to $50","$100 to $150","$5,000 to $10,000"],"h1":"It is a little higher than the fine for a level just under 0.10%.","h2":"In New Jersey, a first DUI with a blood alcohol level of 0.10% or higher carries a fine of $300 to $500, plus fees and surcharges.","p":"Right. The fine is $300 to $500."},"es":{"q":"En New Jersey, ¿cuál es la multa por un primer DUI con un nivel de alcohol en la sangre de 0.10% o más?","o":["De $300 a $500","De $25 a $50","De $100 a $150","De $5,000 a $10,000"],"h1":"Es un poco más alta que la multa por un nivel justo debajo de 0.10%.","h2":"En New Jersey, un primer DUI con un nivel de alcohol en la sangre de 0.10% o más tiene una multa de $300 a $500, más tarifas y recargos.","p":"Correcto. La multa es de $300 a $500."},"ref":{"doc":"NJ","page":123}},{"id":"nj-152","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a 19-year-old buys a drink at a bar. Besides possibly losing their license, what fine can they get?","o":["$10","$500","$50","No fine, only a warning"],"h1":"It is a round number of a few hundred dollars.","h2":"In New Jersey, a person under 21 who buys or drinks alcohol in a place licensed to sell it can be fined $500 and lose their driver license for a time.","p":"Right. The fine is $500, and the license can be suspended."},"es":{"q":"En New Jersey, una persona de 19 años compra una bebida alcohólica en un bar. Además de poder perder su licencia, ¿qué multa puede recibir?","o":["$10","$500","$50","Ninguna multa, solo una advertencia"],"h1":"Es una cifra redonda de unos cientos de dólares.","h2":"En New Jersey, una persona menor de 21 años que compra o toma alcohol en un lugar con licencia para venderlo puede recibir una multa de $500 y perder su licencia de manejo por un tiempo.","p":"Correcto. La multa es de $500 y pueden suspender la licencia."},"ref":{"doc":"NJ","page":123}},{"id":"nj-153","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, how long does a driver lose their license for a first DUI caused by drugs, not alcohol?","o":["One week","30 days","7 to 12 months","10 years"],"h1":"It is more than half a year but no more than one year.","h2":"In New Jersey, a first drug-related DUI brings a license suspension of 7 to 12 months.","p":"Right. A first drug DUI means losing the license for 7 to 12 months."},"es":{"q":"En New Jersey, ¿por cuánto tiempo pierde la licencia un conductor por un primer DUI causado por drogas, no por alcohol?","o":["Una semana","30 días","De 7 a 12 meses","10 años"],"h1":"Es más de medio año, pero no más de un año.","h2":"En New Jersey, un primer DUI relacionado con drogas trae una suspensión de la licencia de 7 a 12 meses.","p":"Correcto. Un primer DUI por drogas significa perder la licencia de 7 a 12 meses."},"ref":{"doc":"NJ","page":125}},{"id":"nj-154","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, after a first DUI with a blood alcohol level of 0.08% up to 0.10%, how long must an ignition interlock stay in the car after the license is restored?","o":["One week","5 years","For life","3 months"],"h1":"It is a short time, counted in months.","h2":"In New Jersey, a first DUI with a blood alcohol level from 0.08% up to 0.10% requires an ignition interlock for 3 months after the license is restored.","p":"Right. The interlock stays for 3 months."},"es":{"q":"En New Jersey, después de un primer DUI con un nivel de alcohol en la sangre de 0.08% a menos de 0.10%, ¿por cuánto tiempo debe quedar un ignition interlock (bloqueo de encendido) en el carro después de recuperar la licencia?","o":["Una semana","5 años","De por vida","3 meses"],"h1":"Es poco tiempo, contado en meses.","h2":"En New Jersey, un primer DUI con un nivel de alcohol en la sangre de 0.08% a menos de 0.10% exige un ignition interlock por 3 meses después de recuperar la licencia.","p":"Correcto. El interlock se queda por 3 meses."},"ref":{"doc":"NJ","page":127}},{"id":"nj-155","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, what is the fine for a first conviction for unsafe driving that puts people or property in danger?","o":["$50 to $150","$1 to $10","$1,000 to $2,000","$5,000"],"h1":"It is under two hundred dollars, plus a court surcharge.","h2":"In New Jersey, a first unsafe driving conviction carries a fine of $50 to $150, plus a $250 court surcharge.","p":"Right. The fine is $50 to $150 for a first offense."},"es":{"q":"En New Jersey, ¿cuál es la multa por una primera condena por manejo inseguro (unsafe driving) que pone en peligro a personas o propiedades?","o":["De $50 a $150","De $1 a $10","De $1,000 a $2,000","$5,000"],"h1":"Es menos de doscientos dólares, más un recargo del tribunal.","h2":"En New Jersey, una primera condena por manejo inseguro tiene una multa de $50 a $150, más un recargo del tribunal de $250.","p":"Correcto. La multa es de $50 a $150 por una primera infracción."},"ref":{"doc":"NJ","page":128}},{"id":"nj-156","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a car is left on a public street (not a limited-access highway) without permission. After how long is it considered abandoned?","o":["One hour","48 hours or more","30 days","It is never considered abandoned"],"h1":"It is about two days.","h2":"In New Jersey, a vehicle left on a highway, on public property, or on private property without consent for 48 hours or more is considered abandoned, and the owner can be fined.","p":"Right. After 48 hours it counts as abandoned."},"es":{"q":"En New Jersey, un carro se deja en una calle pública (no en una autopista de acceso limitado) sin permiso. ¿Después de cuánto tiempo se considera abandonado?","o":["Una hora","48 horas o más","30 días","Nunca se considera abandonado"],"h1":"Son unos dos días.","h2":"En New Jersey, un vehículo dejado en una carretera, en propiedad pública o en propiedad privada sin permiso por 48 horas o más se considera abandonado, y el dueño puede recibir una multa.","p":"Correcto. Después de 48 horas se considera abandonado."},"ref":{"doc":"NJ","page":129}},{"id":"nj-157","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a person is convicted of an automobile insurance crime, such as lying on a claim. What happens to their driver license?","o":["Nothing; it is not a driving offense","They lose it for one week","They lose it for one year","They get two points"],"h1":"Insurance fraud can cost you your license, not only money.","h2":"In New Jersey, a person convicted of an automobile insurance crime loses their driver license for one year.","p":"Right. The license is lost for one year."},"es":{"q":"En New Jersey, una persona es condenada por un delito de seguro de auto, como mentir en un reclamo. ¿Qué pasa con su licencia de manejo?","o":["Nada; no es una infracción de manejo","La pierde por una semana","La pierde por un año","Recibe dos puntos"],"h1":"El fraude de seguros le puede costar la licencia, no solo dinero.","h2":"En New Jersey, una persona condenada por un delito de seguro de auto pierde su licencia de manejo por un año.","p":"Correcto. Pierde la licencia por un año."},"ref":{"doc":"NJ","page":130}},{"id":"nj-158","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, a driver is convicted a second time of leaving the scene of a crash where someone was hurt. What happens to their license?","o":["They lose it for 30 days","They get a written warning","They must only pay a $50 fine","They lose it permanently"],"h1":"A first offense costs one year. A second is much worse.","h2":"In New Jersey, a second hit-and-run conviction involving injury or death means the driver loses their license permanently.","p":"Right. A second offense means losing the license for good."},"es":{"q":"En New Jersey, un conductor es condenado por segunda vez por huir del lugar de un choque donde alguien resultó herido. ¿Qué pasa con su licencia?","o":["La pierde por 30 días","Recibe una advertencia por escrito","Solo debe pagar una multa de $50","La pierde para siempre"],"h1":"Una primera infracción cuesta un año. Una segunda es mucho peor.","h2":"En New Jersey, una segunda condena por huir de un choque con heridos o muertos significa que el conductor pierde su licencia para siempre.","p":"Correcto. Una segunda infracción significa perder la licencia para siempre."},"ref":{"doc":"NJ","page":130}},{"id":"nj-159","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, what penalty can a driver get for a second offense of driving while their license is suspended?","o":["A $750 fine and up to 5 days in jail","A $50 fine only","A written warning","Two points and no fine"],"h1":"The fine is higher than the $500 for a first offense, and jail is possible.","h2":"In New Jersey, a second offense of driving while suspended brings a $750 fine, up to 5 days in jail, and up to six more months of suspension.","p":"Right. It is a $750 fine and up to 5 days in jail."},"es":{"q":"En New Jersey, ¿qué castigo puede recibir un conductor por una segunda infracción de manejar con la licencia suspendida?","o":["Una multa de $750 y hasta 5 días de cárcel","Solo una multa de $50","Una advertencia por escrito","Dos puntos y ninguna multa"],"h1":"La multa es mayor que los $500 de la primera vez, y puede haber cárcel.","h2":"En New Jersey, una segunda infracción de manejar con la licencia suspendida trae una multa de $750, hasta 5 días de cárcel y hasta seis meses más de suspensión.","p":"Correcto. Es una multa de $750 y hasta 5 días de cárcel."},"ref":{"doc":"NJ","page":130}},{"id":"nj-160","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a person takes the driver license test in place of a friend. Besides a fine, what jail time can they face?","o":["None; it is only a fine","30 to 90 days","One day","10 years"],"h1":"It is counted in days, between one and three months.","h2":"In New Jersey, taking a license test for someone else, or having someone take it for you, can bring a $200 to $500 fine and 30 to 90 days in jail.","p":"Right. The jail term can be 30 to 90 days."},"es":{"q":"En New Jersey, una persona toma el examen de licencia en lugar de un amigo. Además de una multa, ¿qué tiempo de cárcel puede recibir?","o":["Ninguno; solo hay multa","De 30 a 90 días","Un día","10 años"],"h1":"Se cuenta en días, entre uno y tres meses.","h2":"En New Jersey, tomar el examen de licencia por otra persona, o hacer que otro lo tome por usted, puede traer una multa de $200 a $500 y de 30 a 90 días de cárcel.","p":"Correcto. La cárcel puede ser de 30 a 90 días."},"ref":{"doc":"NJ","page":132}},{"id":"nj-161","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a person is convicted of operating a boat under the influence. What happens to their driver license?","o":["Nothing; boating has no effect on driving","They get one point","It is suspended too","It is renewed early"],"h1":"The state links boating and driving privileges.","h2":"In New Jersey, a person convicted of boating under the influence loses both their boating and their driving privileges.","p":"Right. Boating DUI also suspends the driver license."},"es":{"q":"En New Jersey, una persona es condenada por manejar un bote bajo la influencia del alcohol o drogas. ¿Qué pasa con su licencia de manejo?","o":["Nada; el bote no afecta el manejo","Recibe un punto","También la suspenden","La renuevan antes de tiempo"],"h1":"El estado une el permiso de navegar con el de manejar.","h2":"En New Jersey, una persona condenada por navegar bajo la influencia pierde tanto el permiso de navegar como el de manejar.","p":"Correcto. El DUI en bote también suspende la licencia de manejo."},"ref":{"doc":"NJ","page":132}},{"id":"nj-162","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, defensive driving courses for \"mature drivers\" are offered to drivers of what age?","o":["16 and 17","21 to 25","90 and older","55 and older"],"h1":"It starts in the mid-fifties.","h2":"In New Jersey, defensive driving courses for mature drivers are offered to drivers 55 and older, and finishing one can lower insurance costs.","p":"Right. Mature driver courses are for drivers 55 and older."},"es":{"q":"En New Jersey, los cursos de manejo defensivo para \"conductores mayores\" (mature drivers), ¿a conductores de qué edad se ofrecen?","o":["16 y 17 años","De 21 a 25 años","90 años o más","55 años o más"],"h1":"Empieza a mediados de los cincuenta.","h2":"En New Jersey, los cursos de manejo defensivo para conductores mayores se ofrecen a conductores de 55 años o más, y terminarlos puede bajar el costo del seguro.","p":"Correcto. Los cursos para conductores mayores son para personas de 55 años o más."},"ref":{"doc":"NJ","page":135}},{"id":"nj-163","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, a driver has 8 points posted within three years. What yearly surcharge must they pay?","o":["$200","$8","$150","$1,000"],"h1":"Six points cost $150, and each extra point adds $25.","h2":"In New Jersey, six points within three years bring a $150 surcharge, plus $25 for each extra point, so 8 points mean $200 a year.","p":"Right. $150 plus $25 for each of the two extra points makes $200."},"es":{"q":"En New Jersey, un conductor tiene 8 puntos registrados en tres años. ¿Qué recargo anual debe pagar?","o":["$200","$8","$150","$1,000"],"h1":"Seis puntos cuestan $150, y cada punto extra suma $25.","h2":"En New Jersey, seis puntos en tres años traen un recargo de $150, más $25 por cada punto extra, así que 8 puntos significan $200 al año.","p":"Correcto. $150 más $25 por cada uno de los dos puntos extra suman $200."},"ref":{"doc":"NJ","page":136}},{"id":"nj-164","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a person is convicted of driving without a license. What yearly surcharge must they pay?","o":["No surcharge, only a warning","$100 a year for three years","$5 one time","$1,500 a year for ten years"],"h1":"It is the smallest amount on the surcharge list, paid for three years.","h2":"In New Jersey, an unlicensed driver must pay a surcharge of $100 a year for three years, on top of court fines.","p":"Right. It is $100 a year for three years."},"es":{"q":"En New Jersey, una persona es condenada por manejar sin licencia. ¿Qué recargo anual debe pagar?","o":["Ningún recargo, solo una advertencia","$100 al año por tres años","$5 una sola vez","$1,500 al año por diez años"],"h1":"Es la cantidad más baja de la lista de recargos, pagada por tres años.","h2":"En New Jersey, un conductor sin licencia debe pagar un recargo de $100 al año por tres años, además de las multas del tribunal.","p":"Correcto. Son $100 al año por tres años."},"ref":{"doc":"NJ","page":136}},{"id":"nj-165","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, how many points go on your record for reckless driving?","o":["No points","One point","Five points","Twelve points"],"h1":"It is the same as racing or tailgating.","h2":"In New Jersey, a reckless driving conviction puts 5 points on your record.","p":"Right. Reckless driving carries 5 points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por manejar de forma temeraria (reckless driving)?","o":["Ningún punto","Un punto","Cinco puntos","Doce puntos"],"h1":"Es lo mismo que por correr carreras o seguir muy de cerca.","h2":"En New Jersey, una condena por manejo temerario agrega 5 puntos a su historial.","p":"Correcto. El manejo temerario tiene 5 puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-166","scope":"NJ","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Jersey, how many points go on your record for passing in a no-passing zone?","o":["No points","One point","Eight points","Four points"],"h1":"It is more than most violations, but less than tailgating.","h2":"In New Jersey, passing in a no-passing zone puts 4 points on your record.","p":"Right. Passing in a no-passing zone carries 4 points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por rebasar en una zona donde está prohibido rebasar?","o":["Ningún punto","Un punto","Ocho puntos","Cuatro puntos"],"h1":"Es más que la mayoría de las infracciones, pero menos que seguir muy de cerca.","h2":"En New Jersey, rebasar en una zona prohibida agrega 4 puntos a su historial.","p":"Correcto. Rebasar en zona prohibida tiene 4 puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-167","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, how many points go on your record for driving 30 mph or more over the speed limit?","o":["Five points","Two points","Three points","One point"],"h1":"It is the highest point value for speeding.","h2":"In New Jersey, driving 30 mph or more over the speed limit puts 5 points on your record.","p":"Right. Going 30 mph or more over the limit carries 5 points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por manejar 30 mph o más por encima del límite de velocidad?","o":["Cinco puntos","Dos puntos","Tres puntos","Un punto"],"h1":"Es el valor más alto en puntos por exceso de velocidad.","h2":"En New Jersey, manejar 30 mph o más por encima del límite agrega 5 puntos a su historial.","p":"Correcto. Ir 30 mph o más por encima del límite tiene 5 puntos."},"ref":{"doc":"NJ","page":139}},{"id":"nj-168","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, how many points go on your record for breaking the Move Over law?","o":["No points","Two points","Six points","Eight points"],"h1":"It is the same as many common violations, like running a stop sign.","h2":"In New Jersey, breaking the Move Over law puts 2 points on your record, along with the fine.","p":"Right. A Move Over violation carries 2 points."},"es":{"q":"En New Jersey, ¿cuántos puntos se agregan a su historial por no cumplir la ley Move Over (cambiarse de carril)?","o":["Ningún punto","Dos puntos","Seis puntos","Ocho puntos"],"h1":"Es lo mismo que muchas infracciones comunes, como pasarse una señal de alto.","h2":"En New Jersey, no cumplir la ley Move Over agrega 2 puntos a su historial, además de la multa.","p":"Correcto. Una infracción de Move Over tiene 2 puntos."},"ref":{"doc":"NJ","page":140}},{"id":"nj-169","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, a driver leaves the scene of a crash in which nobody was hurt. How many points go on the record?","o":["No points","Eight points","Two points","Twelve points"],"h1":"It is far fewer than when someone is hurt.","h2":"In New Jersey, leaving the scene of a crash with no injuries puts 2 points on your record; it is 8 points if someone is hurt.","p":"Right. With no injuries, it is 2 points."},"es":{"q":"En New Jersey, un conductor se va del lugar de un choque en el que nadie resultó herido. ¿Cuántos puntos se agregan al historial?","o":["Ningún punto","Ocho puntos","Dos puntos","Doce puntos"],"h1":"Son muchos menos que cuando alguien resulta herido.","h2":"En New Jersey, irse del lugar de un choque sin heridos agrega 2 puntos a su historial; son 8 puntos si alguien resulta herido.","p":"Correcto. Sin heridos, son 2 puntos."},"ref":{"doc":"NJ","page":140}},{"id":"nj-170","scope":"NJ","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Jersey, you stop for a person at a crosswalk on a road with several lanes going your way. Where should you stop?","o":["Right on top of the crosswalk lines","As close to the person as you can","Past the crosswalk, so the person can walk behind you","Far enough back that drivers in the next lanes can still see the person"],"h1":"Think about the drivers beside you, who also need to see the person.","h2":"In New Jersey, on a road with several lanes, you should stop far enough before the crosswalk that you do not block the view of drivers in the lanes next to you.","p":"Right. Stop well back so other drivers can see the person too."},"es":{"q":"En New Jersey, usted se detiene por una persona en un cruce peatonal en una calle con varios carriles en su dirección. ¿Dónde debe detenerse?","o":["Justo encima de las líneas del cruce","Lo más cerca posible de la persona","Pasando el cruce, para que la persona camine detrás de usted","Lo bastante atrás para que los conductores de los otros carriles todavía vean a la persona"],"h1":"Piense en los conductores a su lado, que también necesitan ver a la persona.","h2":"En New Jersey, en una calle con varios carriles, debe detenerse lo bastante antes del cruce peatonal para no tapar la vista de los conductores de los carriles de al lado.","p":"Correcto. Deténgase bien atrás para que los demás también vean a la persona."},"ref":{"doc":"NJ","page":145}},{"id":"nj-171","scope":"NJ","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Jersey, a motorcycle is passing you. What should you do?","o":["Keep your speed and your position in the lane","Speed up so it cannot pass","Move toward the motorcycle to keep it close","Brake hard to let it go by"],"h1":"Do not make sudden changes; just let it finish the pass.","h2":"In New Jersey, when a motorcycle passes you, keep your speed and your place in the lane, and leave it room to finish the pass.","p":"Right. Keep your speed and lane position."},"es":{"q":"En New Jersey, una motocicleta lo está rebasando. ¿Qué debe hacer usted?","o":["Mantener su velocidad y su posición en el carril","Acelerar para que no pueda rebasarlo","Acercarse a la motocicleta para mantenerla cerca","Frenar fuerte para dejarla pasar"],"h1":"No haga cambios bruscos; solo déjela terminar de rebasar.","h2":"En New Jersey, cuando una motocicleta lo rebasa, mantenga su velocidad y su lugar en el carril, y déjele espacio para terminar de rebasar.","p":"Correcto. Mantenga su velocidad y su posición en el carril."},"ref":{"doc":"NJ","page":147}},{"id":"nj-172","scope":"NJ","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Jersey, a bus has already pulled back into traffic and now signals to change lanes. Must you yield to it by law?","o":["Yes, you must always yield to any bus","No; the yield law covers only buses pulling back in from a stop","Yes, but only on highways","Yes, if it is a school bus with no children"],"h1":"The law protects buses re-entering traffic after a stop, not every move a bus makes.","h2":"In New Jersey, you must yield to a bus pulling back into traffic after a stop, but once it is moving with traffic you are not required to yield when it changes lanes.","p":"Right. The yield law covers buses re-entering traffic, not later lane changes."},"es":{"q":"En New Jersey, un autobús ya volvió al tráfico y ahora señala que va a cambiar de carril. ¿Debe usted cederle el paso por ley?","o":["Sí, siempre debe ceder el paso a cualquier autobús","No; la ley de ceder el paso solo cubre a los autobuses que vuelven al tráfico desde una parada","Sí, pero solo en autopistas","Sí, si es un autobús escolar sin niños"],"h1":"La ley protege a los autobuses que vuelven al tráfico después de una parada, no cada movimiento del autobús.","h2":"En New Jersey, debe ceder el paso a un autobús que vuelve al tráfico después de una parada, pero cuando ya va con el tráfico no está obligado a cederle el paso si cambia de carril.","p":"Correcto. La ley cubre a los autobuses que vuelven al tráfico, no los cambios de carril después."},"ref":{"doc":"NJ","page":150}},{"id":"nj-173","scope":"NJ","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Jersey, you signal a right turn. A bicycle rider next to you is going straight through the intersection. What must you do?","o":["Turn quickly in front of the rider","Honk so the rider stops","Yield and let the rider go through first","Turn at the same time as the rider"],"h1":"The rider going straight has the right-of-way over your turn.","h2":"In New Jersey, a driver signaling a right turn must yield to a bicycle rider, skateboarder or skater going straight through the intersection.","p":"Right. Yield and let the rider go first."},"es":{"q":"En New Jersey, usted señala una vuelta a la derecha. Un ciclista a su lado sigue derecho por la intersección. ¿Qué debe hacer?","o":["Dar la vuelta rápido delante del ciclista","Tocar la bocina para que el ciclista se detenga","Ceder el paso y dejar que el ciclista pase primero","Dar la vuelta al mismo tiempo que el ciclista"],"h1":"El ciclista que sigue derecho tiene el derecho de paso sobre su vuelta.","h2":"En New Jersey, un conductor que señala una vuelta a la derecha debe ceder el paso a un ciclista, patinador o persona en patineta que sigue derecho por la intersección.","p":"Correcto. Ceda el paso y deje pasar primero al ciclista."},"ref":{"doc":"NJ","page":151}},{"id":"nj-174","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, where may a motorized scooter such as a pocket bike or mini motorcycle be ridden?","o":["On any public road","On sidewalks only","In bike lanes on any highway","Only on municipal or county property set aside for it, not on public roads or sidewalks"],"h1":"These small machines are not allowed in normal traffic.","h2":"In New Jersey, motorized scooters such as pocket bikes are illegal on public roads and sidewalks and may be ridden only on municipal or county property set aside for them.","p":"Right. They are allowed only on property set aside for them."},"es":{"q":"En New Jersey, ¿dónde se puede usar un scooter motorizado, como una pocket bike o una minimoto?","o":["En cualquier calle pública","Solo en las aceras","En los carriles de bicicleta de cualquier carretera","Solo en propiedad municipal o del condado designada para eso, no en calles públicas ni aceras"],"h1":"Estas máquinas pequeñas no se permiten en el tráfico normal.","h2":"En New Jersey, los scooters motorizados como las pocket bikes están prohibidos en calles públicas y aceras, y solo se pueden usar en propiedad municipal o del condado designada para eso.","p":"Correcto. Solo se permiten en propiedad designada para eso."},"ref":{"doc":"NJ","page":151}},{"id":"nj-175","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, unless a town or county sets a different age, how old must you be to operate a motorized scooter?","o":["At least 12","At least 5","At least 21","There is no age limit"],"h1":"It is a child's age, not an adult's.","h2":"In New Jersey, no one under 12 may operate a motorized scooter, unless the town or county where it is used sets a different age.","p":"Right. The minimum age is 12."},"es":{"q":"En New Jersey, a menos que el pueblo o el condado fije otra edad, ¿qué edad debe tener para manejar un scooter motorizado?","o":["Al menos 12 años","Al menos 5 años","Al menos 21 años","No hay límite de edad"],"h1":"Es una edad de niño, no de adulto.","h2":"En New Jersey, nadie menor de 12 años puede manejar un scooter motorizado, a menos que el pueblo o el condado donde se use fije otra edad.","p":"Correcto. La edad mínima es 12 años."},"ref":{"doc":"NJ","page":152}},{"id":"nj-176","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, what is a low-speed vehicle (LSV)?","o":["Any car driven under the speed limit","A four-wheeled vehicle with a top speed over 20 mph but no more than 25 mph","A two-wheeled bike with pedals and a motor","A truck with a top speed of 45 mph"],"h1":"It has four wheels and cannot go faster than 25 mph.","h2":"In New Jersey, a low-speed vehicle has four wheels, a top speed over 20 mph but no more than 25 mph, and cannot run on gas or diesel.","p":"Right. An LSV has four wheels and tops out between 20 and 25 mph."},"es":{"q":"En New Jersey, ¿qué es un vehículo de baja velocidad (low-speed vehicle o LSV)?","o":["Cualquier carro que va por debajo del límite de velocidad","Un vehículo de cuatro ruedas con velocidad máxima de más de 20 mph pero no más de 25 mph","Una bicicleta de dos ruedas con pedales y motor","Un camión con velocidad máxima de 45 mph"],"h1":"Tiene cuatro ruedas y no puede ir a más de 25 mph.","h2":"En New Jersey, un vehículo de baja velocidad tiene cuatro ruedas, una velocidad máxima de más de 20 mph pero no más de 25 mph, y no puede usar gasolina ni diésel.","p":"Correcto. Un LSV tiene cuatro ruedas y su máximo está entre 20 y 25 mph."},"ref":{"doc":"NJ","page":153}},{"id":"nj-177","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, how far can a train stick out past the rails on each side?","o":["Not at all; it is exactly as wide as the rails","About one inch","Three feet or more","Only on curves"],"h1":"A train is wider than the track it runs on.","h2":"In New Jersey, a train can be three or more feet wider than the tracks on each side, so stop well back from the rails.","p":"Right. A train can stick out three feet or more on each side."},"es":{"q":"En New Jersey, ¿cuánto puede sobresalir un tren de los rieles a cada lado?","o":["Nada; es exactamente tan ancho como los rieles","Más o menos una pulgada","Tres pies o más","Solo en las curvas"],"h1":"Un tren es más ancho que la vía sobre la que corre.","h2":"En New Jersey, un tren puede ser tres pies o más más ancho que la vía a cada lado, así que deténgase bien lejos de los rieles.","p":"Correcto. Un tren puede sobresalir tres pies o más a cada lado."},"ref":{"doc":"NJ","page":153}},{"id":"nj-178","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, you drive a car with a manual (stick shift) transmission. What should you avoid while crossing railroad tracks?","o":["Looking both ways","Keeping both hands on the wheel","Listening for a train","Shifting gears"],"h1":"A missed shift could stall the car on the tracks.","h2":"In New Jersey, if you drive a stick shift, do not shift gears while crossing railroad tracks.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"En New Jersey, usted maneja un carro de transmisión manual (de cambios). ¿Qué debe evitar al cruzar la vía del tren?","o":["Mirar a ambos lados","Tener las dos manos en el volante","Escuchar si viene un tren","Cambiar de velocidad"],"h1":"Un cambio fallido podría apagar el carro sobre la vía.","h2":"En New Jersey, si maneja un carro de cambios, no cambie de velocidad mientras cruza la vía del tren.","p":"Correcto. No cambie de velocidad sobre la vía."},"ref":{"doc":"NJ","page":153}},{"id":"nj-179","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, may a registered ATV, dirt bike or snowmobile ride along public roads with other traffic?","o":["No, but it may cross certain roads when it is safe","Yes, on any road","Yes, but only at night","Yes, if it stays on the shoulder"],"h1":"They are not allowed to travel with traffic, only to get across.","h2":"In New Jersey, ATVs, dirt bikes and snowmobiles may not ride on public roads with other vehicles, but they may cross certain roads when it is safe.","p":"Right. They may cross some roads, but not ride along them."},"es":{"q":"En New Jersey, ¿puede un ATV (cuatrimoto), una moto de tierra o una moto de nieve registrada andar por calles públicas con el resto del tráfico?","o":["No, pero puede cruzar ciertas calles cuando sea seguro","Sí, en cualquier calle","Sí, pero solo de noche","Sí, si se queda en el acotamiento"],"h1":"No se les permite andar con el tráfico, solo cruzar.","h2":"En New Jersey, los ATV, las motos de tierra y las motos de nieve no pueden andar por calles públicas con otros vehículos, pero sí pueden cruzar ciertas calles cuando sea seguro.","p":"Correcto. Pueden cruzar algunas calles, pero no andar por ellas."},"ref":{"doc":"NJ","page":154}},{"id":"nj-180","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how long is the first registration of a brand-new vehicle valid?","o":["One month","Four years","Ten years","For as long as you own it"],"h1":"Most other registrations last one year; a brand-new car gets longer.","h2":"In New Jersey, the first registration of a brand-new vehicle is valid for four years; most other registrations last one year.","p":"Right. A brand-new vehicle's first registration lasts four years."},"es":{"q":"En New Jersey, ¿por cuánto tiempo es válido el primer registro de un vehículo nuevo?","o":["Un mes","Cuatro años","Diez años","Mientras usted sea el dueño"],"h1":"La mayoría de los otros registros duran un año; un carro nuevo recibe más tiempo.","h2":"En New Jersey, el primer registro de un vehículo nuevo es válido por cuatro años; la mayoría de los otros registros duran un año.","p":"Correcto. El primer registro de un vehículo nuevo dura cuatro años."},"ref":{"doc":"NJ","page":158}},{"id":"nj-181","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you put a cover on your license plate that hides some of the letters. What fine can you get?","o":["No fine; covers are allowed","Up to $5","Up to $100","Up to $10,000"],"h1":"It is a fine of up to a hundred dollars.","h2":"In New Jersey, a license plate cover or holder that hides any lettering on the plate is a violation with a fine of up to $100.","p":"Right. The fine is up to $100."},"es":{"q":"En New Jersey, usted pone una cubierta en su placa que tapa algunas letras. ¿Qué multa puede recibir?","o":["Ninguna multa; las cubiertas están permitidas","Hasta $5","Hasta $100","Hasta $10,000"],"h1":"Es una multa de hasta cien dólares.","h2":"En New Jersey, una cubierta o marco de placa que tapa cualquier letra de la placa es una infracción con una multa de hasta $100.","p":"Correcto. La multa es de hasta $100."},"ref":{"doc":"NJ","page":159}},{"id":"nj-182","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, how often must a gasoline vehicle with commercial registration be inspected?","o":["Every two years","Every ten years","Never","Every year"],"h1":"It is more often than for a passenger car.","h2":"In New Jersey, gasoline vehicles with commercial registration must be inspected every year.","p":"Right. Commercial vehicles are inspected every year."},"es":{"q":"En New Jersey, ¿cada cuánto debe inspeccionarse un vehículo de gasolina con registro comercial?","o":["Cada dos años","Cada diez años","Nunca","Cada año"],"h1":"Es más seguido que para un carro de pasajeros.","h2":"En New Jersey, los vehículos de gasolina con registro comercial deben inspeccionarse cada año.","p":"Correcto. Los vehículos comerciales se inspeccionan cada año."},"ref":{"doc":"NJ","page":160}},{"id":"nj-183","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, a police officer stops you and asks for your insurance ID card. May you show it on your phone?","o":["Yes, an electronic insurance ID card is accepted","No, only a paper card is accepted","No, you must bring it to court later","Only if you also show a utility bill"],"h1":"The state accepts a digital version.","h2":"In New Jersey, your insurance ID card must be in the vehicle and shown when asked, and an electronic version is accepted.","p":"Right. An electronic insurance ID card is accepted."},"es":{"q":"En New Jersey, un policía lo detiene y le pide su tarjeta de identificación del seguro. ¿Puede mostrarla en su teléfono?","o":["Sí, se acepta una tarjeta de seguro electrónica","No, solo se acepta una tarjeta de papel","No, debe llevarla al tribunal después","Solo si también muestra una factura de servicios"],"h1":"El estado acepta una versión digital.","h2":"En New Jersey, su tarjeta de identificación del seguro debe estar en el vehículo y mostrarse cuando la pidan, y se acepta una versión electrónica.","p":"Correcto. Se acepta una tarjeta de seguro electrónica."},"ref":{"doc":"NJ","page":161}},{"id":"nj-184","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, how many license plates does a motorcycle get, and where does it go?","o":["Two plates, front and rear","One plate, on the rear","One plate, on the front","None; motorcycles do not need plates"],"h1":"Cars get two plates, but a motorcycle is different.","h2":"In New Jersey, a motorcycle gets one license plate, which must always be shown on the rear.","p":"Right. A motorcycle has one plate, on the back."},"es":{"q":"En New Jersey, ¿cuántas placas recibe una motocicleta y dónde va?","o":["Dos placas, adelante y atrás","Una placa, atrás","Una placa, adelante","Ninguna; las motocicletas no necesitan placa"],"h1":"Los carros reciben dos placas, pero la motocicleta es diferente.","h2":"En New Jersey, una motocicleta recibe una placa, que siempre debe mostrarse en la parte de atrás.","p":"Correcto. Una motocicleta tiene una placa, atrás."},"ref":{"doc":"NJ","page":170}},{"id":"nj-185","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, what following distance is a good rule on snow-covered roads?","o":["One second","Two seconds","Six seconds or more","Half a second"],"h1":"It is more than the four seconds for wet roads.","h2":"In New Jersey, a good rule on snow-covered roads is to stay at least six seconds behind the vehicle ahead.","p":"Right. Keep six seconds or more on snow."},"es":{"q":"En New Jersey, ¿qué distancia de seguimiento es una buena regla en calles cubiertas de nieve?","o":["Un segundo","Dos segundos","Seis segundos o más","Medio segundo"],"h1":"Es más que los cuatro segundos para calles mojadas.","h2":"En New Jersey, una buena regla en calles cubiertas de nieve es mantenerse al menos seis segundos detrás del vehículo de adelante.","p":"Correcto. Mantenga seis segundos o más en la nieve."},"ref":{"doc":"NJ","page":99}},{"id":"nj-186","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, above what speed can your tires completely leave the road surface on a wet road?","o":["5 mph","15 mph","100 mph","55 mph"],"h1":"Hydroplaning starts around 35 mph; total loss of contact comes at a higher speed.","h2":"In New Jersey, hydroplaning can start at about 35 mph, and above 55 mph the tires may totally leave the road, so braking and steering no longer work.","p":"Right. Above 55 mph, tires may totally leave the road."},"es":{"q":"En New Jersey, ¿a partir de qué velocidad las llantas pueden separarse por completo de una calle mojada?","o":["5 mph","15 mph","100 mph","55 mph"],"h1":"El hidroplaneo empieza cerca de 35 mph; la pérdida total de contacto llega a una velocidad más alta.","h2":"En New Jersey, el hidroplaneo puede empezar a unas 35 mph, y a más de 55 mph las llantas pueden separarse por completo de la calle, así que frenar y girar ya no funcionan.","p":"Correcto. A más de 55 mph, las llantas pueden separarse por completo."},"ref":{"doc":"NJ","page":97}},{"id":"nj-187","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a work zone may be marked by a warning sign or flashing lights up to how far before the work area?","o":["10 feet","Half a mile","50 feet","20 miles"],"h1":"It is a fraction of a mile.","h2":"In New Jersey, a work zone is marked by an advance warning sign or flashing lights on a vehicle up to half a mile before the work area, and fines are doubled inside it.","p":"Right. The warning can come up to half a mile ahead."},"es":{"q":"En New Jersey, ¿hasta qué distancia antes del área de trabajo puede estar marcada una zona de trabajo con una señal de advertencia o luces intermitentes?","o":["10 pies","Media milla","50 pies","20 millas"],"h1":"Es una fracción de milla.","h2":"En New Jersey, una zona de trabajo se marca con una señal de advertencia o luces intermitentes en un vehículo hasta media milla antes del área de trabajo, y las multas se duplican dentro de ella.","p":"Correcto. La advertencia puede estar hasta media milla antes."},"ref":{"doc":"NJ","page":103}},{"id":"nj-188","scope":"NJ","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Jersey, why must you never turn the ignition key to the lock position while the car is moving?","o":["The radio will stop working","The car will stop at once safely","The steering wheel can lock and you lose control","The seat belts will unlock"],"h1":"Think of what the lock position does to the steering.","h2":"In New Jersey, never turn the ignition to lock while the car is moving, because the steering will lock and you will lose control.","p":"Right. The steering can lock and you lose control."},"es":{"q":"En New Jersey, ¿por qué nunca debe girar la llave del encendido a la posición de bloqueo (lock) mientras el carro está en movimiento?","o":["El radio dejará de funcionar","El carro se detendrá de inmediato de forma segura","El volante se puede trabar y usted pierde el control","Los cinturones de seguridad se soltarán"],"h1":"Piense en lo que la posición de bloqueo le hace al volante.","h2":"En New Jersey, nunca gire el encendido a la posición de bloqueo mientras el carro se mueve, porque el volante se trabará y usted perderá el control.","p":"Correcto. El volante se puede trabar y usted pierde el control."},"ref":{"doc":"NJ","page":104}},{"id":"nj-189","scope":"NJ","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Jersey, a front tire blows out while you are driving. What should you do?","o":["Brake as hard as you can","Turn sharply to the shoulder at once","Speed up to keep the car straight","Hold the wheel firmly, take your foot off the gas, and slow down without braking"],"h1":"Keep the car straight and let it coast.","h2":"In New Jersey, after a blowout you should hold the wheel firmly, keep the car straight, take your foot off the gas and not use the brakes, letting the car coast to a safe stop off the road.","p":"Right. Hold the wheel, ease off the gas, and do not brake."},"es":{"q":"En New Jersey, una llanta delantera revienta mientras usted maneja. ¿Qué debe hacer?","o":["Frenar lo más fuerte que pueda","Girar bruscamente hacia el acotamiento de inmediato","Acelerar para mantener el carro derecho","Sujetar firme el volante, quitar el pie del acelerador y bajar la velocidad sin frenar"],"h1":"Mantenga el carro derecho y déjelo rodar.","h2":"En New Jersey, después de que revienta una llanta debe sujetar firme el volante, mantener el carro derecho, quitar el pie del acelerador y no usar los frenos, dejando que el carro se detenga solo en un lugar seguro fuera de la calle.","p":"Correcto. Sujete el volante, suelte el acelerador y no frene."},"ref":{"doc":"NJ","page":107}},{"id":"nj-190","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, a low-speed motorcycle (under 50cc, top speed 35 mph) may NOT be ridden on which roads?","o":["Any road in a town","Roads with a posted speed limit over 35 mph, toll roads and limited-access highways","Roads with a speed limit of 25 mph","Any road during the day"],"h1":"Its top speed tells you which roads are too fast for it.","h2":"In New Jersey, a low-speed motorcycle may not be ridden on any state toll road, limited-access highway or road with a posted limit over 35 mph; a basic license is enough to ride one.","p":"Right. It may not use roads posted over 35 mph, toll roads or limited-access highways."},"es":{"q":"En New Jersey, una motocicleta de baja velocidad (menos de 50cc, velocidad máxima de 35 mph), ¿en qué calles NO puede usarse?","o":["Cualquier calle de un pueblo","Calles con límite de velocidad de más de 35 mph, autopistas de peaje y autopistas de acceso limitado","Calles con límite de 25 mph","Cualquier calle durante el día"],"h1":"Su velocidad máxima le dice qué calles son demasiado rápidas para ella.","h2":"En New Jersey, una motocicleta de baja velocidad no puede usarse en autopistas estatales de peaje, autopistas de acceso limitado ni calles con límite de más de 35 mph; basta una licencia básica para manejarla.","p":"Correcto. No puede usar calles de más de 35 mph, autopistas de peaje ni de acceso limitado."},"ref":{"doc":"NJ","page":165}},{"id":"nj-191","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you pass the MVC motorcycle road test on a 200cc motorcycle and did not take a safety course. What restriction goes on your license?","o":["You may ride only in daylight for life","You may ride only motorcycles of 200cc or less","You may ride only motorcycles of 500cc or less","There is no restriction"],"h1":"A test on a small bike (231cc or less) limits you to mid-size bikes.","h2":"In New Jersey, if you take the MVC road test on a motorcycle of 231cc or less, your license is restricted to motorcycles of 500cc or less, unless you finished an approved safety course.","p":"Right. You are limited to 500cc or less."},"es":{"q":"En New Jersey, usted aprueba el examen práctico de motocicleta de la MVC en una motocicleta de 200cc y no tomó un curso de seguridad. ¿Qué restricción tendrá su licencia?","o":["Solo puede manejar de día por toda la vida","Solo puede manejar motocicletas de 200cc o menos","Solo puede manejar motocicletas de 500cc o menos","No hay ninguna restricción"],"h1":"Un examen en una moto pequeña (231cc o menos) lo limita a motos medianas.","h2":"En New Jersey, si toma el examen práctico de la MVC en una motocicleta de 231cc o menos, su licencia queda limitada a motocicletas de 500cc o menos, a menos que haya terminado un curso de seguridad aprobado.","p":"Correcto. Queda limitado a 500cc o menos."},"ref":{"doc":"NJ","page":165}},{"id":"nj-192","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, a 17-year-old wants a motorcycle endorsement. What must they complete first?","o":["Nothing; age 17 is enough","A truck driving course","Five years of car driving","The Motorcycle Safety Education Program Basic Rider Course"],"h1":"Riders under 18 must take a training course.","h2":"In New Jersey, anyone under 18 must take the Motorcycle Safety Education Program Basic Rider Course before getting a motorcycle endorsement.","p":"Right. Riders under 18 must take the Basic Rider Course."},"es":{"q":"En New Jersey, una persona de 17 años quiere un endoso de motocicleta. ¿Qué debe completar primero?","o":["Nada; tener 17 años es suficiente","Un curso para manejar camiones","Cinco años de manejar carro","El Basic Rider Course (curso básico) del Motorcycle Safety Education Program"],"h1":"Los menores de 18 años deben tomar un curso de entrenamiento.","h2":"En New Jersey, toda persona menor de 18 años debe tomar el Basic Rider Course del Motorcycle Safety Education Program antes de recibir un endoso de motocicleta.","p":"Correcto. Los menores de 18 años deben tomar el Basic Rider Course."},"ref":{"doc":"NJ","page":164}},{"id":"nj-193","scope":"NJ","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Jersey, what is the youngest age to get a motorcycle permit?","o":["17, with a parent or guardian's consent if under 18","14","15, with a parent's consent","21"],"h1":"It is a year after the age for a car learner permit.","h2":"In New Jersey, you must be at least 17 to get a motorcycle permit, and a parent or guardian must consent if you are under 18.","p":"Right. You must be at least 17."},"es":{"q":"En New Jersey, ¿cuál es la edad mínima para obtener un permiso de motocicleta?","o":["17 años, con el permiso de un padre o tutor si es menor de 18","14 años","15 años, con el permiso de un padre","21 años"],"h1":"Es un año después de la edad del permiso especial para carro.","h2":"En New Jersey, debe tener al menos 17 años para obtener un permiso de motocicleta, y un padre o tutor debe dar su permiso si es menor de 18.","p":"Correcto. Debe tener al menos 17 años."},"ref":{"doc":"NJ","page":169}},{"id":"nj-194","scope":"NJ","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Jersey, if you do not take a Basic Rider Course, how old must you be to take the MVC motorcycle road test?","o":["At least 15","At least 18","At least 16","At least 25"],"h1":"You can get the permit at 17, but the MVC test comes later.","h2":"In New Jersey, without a Basic Rider Course you must be at least 18 to take the MVC motorcycle road test.","p":"Right. You must be at least 18."},"es":{"q":"En New Jersey, si no toma un Basic Rider Course, ¿qué edad debe tener para tomar el examen práctico de motocicleta de la MVC?","o":["Al menos 15 años","Al menos 18 años","Al menos 16 años","Al menos 25 años"],"h1":"Puede obtener el permiso a los 17, pero el examen de la MVC viene después.","h2":"En New Jersey, sin un Basic Rider Course debe tener al menos 18 años para tomar el examen práctico de motocicleta de la MVC.","p":"Correcto. Debe tener al menos 18 años."},"ref":{"doc":"NJ","page":166}},{"id":"nj-195","scope":"NJ","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Jersey, you have a basic driver license and want a motorcycle endorsement without a rider course. At least how long must you practice with your motorcycle permit before the road test?","o":["1 day","90 days","20 days","2 years"],"h1":"It is a few weeks.","h2":"In New Jersey, a licensed driver adding a motorcycle endorsement without a rider course must practice with a motorcycle permit for at least 20 days before the road test.","p":"Right. You must practice for at least 20 days."},"es":{"q":"En New Jersey, usted tiene una licencia básica de manejo y quiere un endoso de motocicleta sin tomar un curso. ¿Por cuánto tiempo, como mínimo, debe practicar con su permiso de motocicleta antes del examen práctico?","o":["1 día","90 días","20 días","2 años"],"h1":"Son unas pocas semanas.","h2":"En New Jersey, un conductor con licencia que quiere agregar un endoso de motocicleta sin tomar un curso debe practicar con un permiso de motocicleta por al menos 20 días antes del examen práctico.","p":"Correcto. Debe practicar al menos 20 días."},"ref":{"doc":"NJ","page":166}},{"id":"nj-196","scope":"NJ","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Jersey, may a rider with a motorcycle permit carry a passenger?","o":["Yes, any passenger","Yes, if the passenger is under 18","Yes, but only on toll roads","No, permit holders may not carry passengers"],"h1":"The permit has limits on night riding, highways and who rides along.","h2":"In New Jersey, a motorcycle permit holder may not carry passengers, ride from half an hour after sunset to half an hour before sunrise, or use toll roads and limited-access highways.","p":"Right. Permit holders may not carry passengers."},"es":{"q":"En New Jersey, ¿puede un motociclista con permiso de motocicleta llevar un pasajero?","o":["Sí, a cualquier pasajero","Sí, si el pasajero es menor de 18 años","Sí, pero solo en autopistas de peaje","No, quien tiene permiso no puede llevar pasajeros"],"h1":"El permiso tiene límites sobre manejar de noche, las autopistas y quién viaja con usted.","h2":"En New Jersey, quien tiene permiso de motocicleta no puede llevar pasajeros, manejar desde media hora después de la puesta del sol hasta media hora antes de la salida del sol, ni usar autopistas de peaje o de acceso limitado.","p":"Correcto. Quien tiene permiso no puede llevar pasajeros."},"ref":{"doc":"NJ","page":169}},{"id":"nj-197","scope":"NJ","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Jersey, who on a motorcycle must wear a helmet?","o":["Both the operator and any passenger","Only the operator","Only riders under 18","No one; helmets are optional"],"h1":"The law covers everyone on the bike, and the operator can be fined for a bare-headed passenger.","h2":"In New Jersey, helmets are required by law for motorcycle operators and passengers, and an operator can be fined for carrying a passenger without one.","p":"Right. Both operator and passenger must wear helmets."},"es":{"q":"En New Jersey, ¿quién debe usar casco en una motocicleta?","o":["Tanto el conductor como cualquier pasajero","Solo el conductor","Solo los menores de 18 años","Nadie; el casco es opcional"],"h1":"La ley cubre a todos en la moto, y al conductor lo pueden multar si el pasajero va sin casco.","h2":"En New Jersey, la ley exige casco al conductor de la motocicleta y a los pasajeros, y al conductor lo pueden multar si lleva a un pasajero sin casco.","p":"Correcto. Tanto el conductor como el pasajero deben usar casco."},"ref":{"doc":"NJ","page":173}},{"id":"nj-198","scope":"NJ","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Jersey, a motorcycle has no windscreen. What must the operator wear to protect the eyes?","o":["Nothing; eye protection is optional","Approved goggles or a face shield","Regular sunglasses are enough","Only eyeglasses at night"],"h1":"Glasses and sunglasses do not count.","h2":"In New Jersey, a motorcycle operator must wear approved goggles or a face shield unless the motorcycle has a windscreen.","p":"Right. Wear approved goggles or a face shield."},"es":{"q":"En New Jersey, una motocicleta no tiene parabrisas. ¿Qué debe usar el conductor para proteger los ojos?","o":["Nada; la protección de los ojos es opcional","Gafas protectoras (goggles) o un protector facial aprobados","Basta con lentes de sol comunes","Solo anteojos de noche"],"h1":"Los anteojos y los lentes de sol no cuentan.","h2":"En New Jersey, el conductor de una motocicleta debe usar gafas protectoras o un protector facial aprobados, a menos que la motocicleta tenga parabrisas.","p":"Correcto. Use gafas protectoras o un protector facial aprobados."},"ref":{"doc":"NJ","page":174}},{"id":"nm-001","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, what is the youngest age to apply for an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year younger than 16.","h2":"In New Mexico you can apply for an instruction permit at 15 if you are in or have finished an approved driver education course.","p":"Right. The New Mexico permit starts at 15."},"es":{"q":"En Nuevo México, ¿cuál es la edad mínima para solicitar un permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año menos que 16.","h2":"En Nuevo México usted puede solicitar un permiso de instrucción a los 15 años si está tomando o ya terminó un curso aprobado de educación vial.","p":"Correcto. El permiso en Nuevo México empieza a los 15."},"zh":{"q":"在 New Mexico，最小几岁可以申请学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比 16 岁小一岁。","h2":"在 New Mexico，如果你正在上或已经上完认可的驾驶教育课程，15 岁就可以申请学习驾照。","p":"对。New Mexico 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở New Mexico, tuổi nhỏ nhất để xin giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Nó nhỏ hơn 16 một tuổi.","h2":"Ở New Mexico, bạn có thể xin giấy phép tập lái lúc 15 tuổi nếu bạn đang học hoặc đã học xong một khóa giáo dục lái xe được chấp thuận.","p":"Đúng. Giấy phép tập lái ở New Mexico bắt đầu từ 15 tuổi."},"tl":{"q":"Sa New Mexico, ano ang pinakabatang edad para mag-apply ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ay isang taon na mas bata sa 16.","h2":"Sa New Mexico, puwede kang mag-apply ng instruction permit sa edad na 15 kung nag-aaral ka o tapos ka na sa isang aprubadong kurso sa driver education.","p":"Tama. Ang permit sa New Mexico ay nagsisimula sa edad na 15."},"ar":{"q":"في New Mexico، ما أصغر عمر للتقدّم بطلب تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه أصغر من 16 بسنة واحدة.","h2":"في New Mexico يمكنك التقدّم بطلب تصريح التعلّم في سن 15 إذا كنت تدرس في دورة معتمدة لتعليم القيادة أو أنهيتها.","p":"صحيح. يبدأ تصريح التعلّم في New Mexico من سن 15."},"ref":{"doc":"NM","page":1}},{"id":"nm-002","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what must the driver education course include for a teen to get an instruction permit?","o":["A car repair class","A first aid certificate","A DWI prevention and education part","A night driving test"],"h1":"It is about drinking and driving.","h2":"In New Mexico the approved driver education course must include a DWI prevention and education part.","p":"Correct. The course includes DWI education."},"es":{"q":"En Nuevo México, ¿qué debe incluir el curso de educación vial para que un joven obtenga el permiso de instrucción?","o":["Una clase de mecánica","Un certificado de primeros auxilios","Una parte de prevención y educación sobre manejar bajo la influencia (DWI)","Un examen de manejo nocturno"],"h1":"Tiene que ver con tomar alcohol y manejar.","h2":"En Nuevo México, el curso aprobado de educación vial debe incluir una parte de prevención y educación sobre manejar bajo la influencia (DWI).","p":"Correcto. El curso incluye educación sobre DWI."},"zh":{"q":"在 New Mexico，青少年要拿学习驾照，驾驶教育课程必须包括什么？","o":["修车课","急救证书","DWI（酒后驾车）预防和教育的部分","夜间驾驶考试"],"h1":"它和喝酒开车有关。","h2":"在 New Mexico，认可的驾驶教育课程必须包括 DWI（酒后驾车）预防和教育的部分。","p":"对。课程包括 DWI 教育。"},"vi":{"q":"Ở New Mexico, khóa giáo dục lái xe phải có phần nào để thanh thiếu niên được cấp giấy phép tập lái?","o":["Một lớp sửa xe","Một chứng chỉ sơ cứu","Một phần phòng chống và giáo dục về lái xe khi say rượu (DWI)","Một bài thi lái xe ban đêm"],"h1":"Nó nói về uống rượu và lái xe.","h2":"Ở New Mexico, khóa giáo dục lái xe được chấp thuận phải có một phần phòng chống và giáo dục về lái xe khi say rượu (DWI).","p":"Đúng. Khóa học có phần giáo dục về DWI."},"tl":{"q":"Sa New Mexico, ano ang dapat kasama sa kurso sa driver education para makakuha ang isang teen ng instruction permit?","o":["Isang klase sa pag-aayos ng kotse","Isang sertipiko sa first aid","Isang bahagi tungkol sa pag-iwas at edukasyon sa DWI (pagmamaneho nang lasing)","Isang pagsusulit sa pagmamaneho sa gabi"],"h1":"Ito ay tungkol sa pag-inom ng alak at pagmamaneho.","h2":"Sa New Mexico, ang aprubadong kurso sa driver education ay dapat may bahagi tungkol sa pag-iwas at edukasyon sa DWI (pagmamaneho nang lasing).","p":"Tama. May edukasyon sa DWI ang kurso."},"ar":{"q":"في New Mexico، ماذا يجب أن تتضمّن دورة تعليم القيادة حتى يحصل المراهق على تصريح التعلّم؟","o":["درسًا في إصلاح السيارات","شهادة إسعافات أولية","جزءًا عن الوقاية والتوعية من القيادة تحت تأثير الكحول (DWI)","اختبار قيادة ليلية"],"h1":"إنه عن شرب الكحول والقيادة.","h2":"في New Mexico يجب أن تتضمّن دورة تعليم القيادة المعتمدة جزءًا عن الوقاية والتوعية من القيادة تحت تأثير الكحول (DWI).","p":"صحيح. تتضمّن الدورة توعية عن DWI."},"ref":{"doc":"NM","page":1}},{"id":"nm-003","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, how old must the licensed driver beside an instruction permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The helper must be old enough to drink legally.","h2":"In New Mexico an instruction permit holder must drive with a licensed driver who is 21 or older in the seat beside them.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nuevo México, ¿qué edad debe tener el conductor con licencia que va al lado de quien tiene permiso de instrucción?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente.","h2":"En Nuevo México, quien tiene permiso de instrucción debe manejar con un conductor con licencia de 21 años o más sentado a su lado.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 New Mexico，坐在学习驾照持有人旁边的有驾照司机必须几岁？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 New Mexico，学习驾照持有人开车时，旁边的座位必须坐一位 21 岁或以上、有驾照的司机。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở New Mexico, người lái xe có bằng ngồi bên cạnh người có giấy phép tập lái phải bao nhiêu tuổi?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Người giúp đỡ phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở New Mexico, người có giấy phép tập lái phải lái xe cùng một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế bên cạnh.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa New Mexico, ilang taon dapat ang lisensiyadong driver na katabi ng may instruction permit?","o":["16 pataas","18 pataas","25 pataas","21 pataas"],"h1":"Ang tagatulong ay dapat nasa edad na legal nang uminom ng alak.","h2":"Sa New Mexico, ang may instruction permit ay dapat magmaneho kasama ang isang lisensiyadong driver na 21 taong gulang pataas na nakaupo sa tabi niya.","p":"Tama. Ang superbisor ay dapat 21 taong gulang pataas."},"ar":{"q":"في New Mexico، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب حامل تصريح التعلّم؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"يجب أن يكون المساعد في العمر الذي يُسمح فيه قانونيًا بشرب الكحول.","h2":"في New Mexico يجب أن يقود حامل تصريح التعلّم مع سائق مرخَّص عمره 21 سنة أو أكثر يجلس في المقعد بجانبه.","p":"صحيح. يجب أن يكون المشرف عمره 21 سنة أو أكثر."},"ref":{"doc":"NM","page":1}},{"id":"nm-004","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how long must the supervising driver have been licensed?","o":["At least three years","At least six months","At least one year","At least ten years"],"h1":"It is more than one year but less than five.","h2":"In New Mexico the supervising driver must have been licensed for at least three years, in New Mexico or another state.","p":"Correct. Three years of licensed driving are required."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener licencia el conductor que supervisa?","o":["Por lo menos tres años","Por lo menos seis meses","Por lo menos un año","Por lo menos diez años"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Nuevo México, el conductor que supervisa debe tener licencia desde hace por lo menos tres años, en Nuevo México o en otro estado.","p":"Correcto. Se piden tres años con licencia."},"zh":{"q":"在 New Mexico，监督司机必须有驾照多久？","o":["至少三年","至少六个月","至少一年","至少十年"],"h1":"它比一年多，但比五年少。","h2":"在 New Mexico，监督司机必须有驾照至少三年，在 New Mexico 或其他州都可以。","p":"对。需要有三年驾照。"},"vi":{"q":"Ở New Mexico, người lái xe giám sát phải có bằng lái được bao lâu?","o":["Ít nhất ba năm","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất mười năm"],"h1":"Nó nhiều hơn một năm nhưng ít hơn năm năm.","h2":"Ở New Mexico, người lái xe giám sát phải có bằng lái ít nhất ba năm, ở New Mexico hoặc ở một tiểu bang khác.","p":"Đúng. Cần ba năm có bằng lái."},"tl":{"q":"Sa New Mexico, gaano na katagal dapat may lisensiya ang nagbabantay na driver?","o":["Hindi bababa sa tatlong taon","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa sampung taon"],"h1":"Ito ay higit sa isang taon pero kulang sa limang taon.","h2":"Sa New Mexico, ang nagbabantay na driver ay dapat may lisensiya nang hindi bababa sa tatlong taon, sa New Mexico o sa ibang estado.","p":"Tama. Kailangan ang tatlong taon na may lisensiya."},"ar":{"q":"في New Mexico، منذ كم من الوقت يجب أن يكون السائق المشرف حاصلًا على رخصة؟","o":["ثلاث سنوات على الأقل","ستة أشهر على الأقل","سنة واحدة على الأقل","عشر سنوات على الأقل"],"h1":"إنها أكثر من سنة وأقل من خمس سنوات.","h2":"في New Mexico يجب أن يكون السائق المشرف حاصلًا على رخصة منذ ثلاث سنوات على الأقل، في New Mexico أو في ولاية أخرى.","p":"صحيح. يجب أن يكون لديه رخصة منذ ثلاث سنوات."},"ref":{"doc":"NM","page":1}},{"id":"nm-005","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, where must the supervising driver sit?","o":["In any back seat","In the seat beside the driver","Anywhere in the vehicle","In a car following behind"],"h1":"They need to see the road and help right away.","h2":"In New Mexico the supervising driver must sit in the seat beside the permit holder.","p":"Right. The supervisor sits beside you."},"es":{"q":"En Nuevo México, ¿dónde debe sentarse el conductor que supervisa?","o":["En cualquier asiento de atrás","En el asiento al lado del conductor","En cualquier lugar del vehículo","En otro auto que va detrás"],"h1":"Necesita ver el camino y ayudar de inmediato.","h2":"En Nuevo México, el conductor que supervisa debe ir sentado al lado de quien tiene el permiso.","p":"Correcto. El supervisor va a su lado."},"zh":{"q":"在 New Mexico，监督司机必须坐在哪里？","o":["任何后排座位","司机旁边的座位","车里任何地方","跟在后面的车里"],"h1":"他们需要看到道路，并能马上帮忙。","h2":"在 New Mexico，监督司机必须坐在学习驾照持有人旁边的座位。","p":"对。监督的人坐在你旁边。"},"vi":{"q":"Ở New Mexico, người lái xe giám sát phải ngồi ở đâu?","o":["Ở bất kỳ ghế sau nào","Ở ghế bên cạnh người lái","Ở bất cứ chỗ nào trong xe","Trong một xe chạy theo phía sau"],"h1":"Họ cần nhìn thấy đường và giúp ngay lập tức.","h2":"Ở New Mexico, người lái xe giám sát phải ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Đúng. Người giám sát ngồi bên cạnh bạn."},"tl":{"q":"Sa New Mexico, saan dapat umupo ang nagbabantay na driver?","o":["Sa kahit anong upuan sa likod","Sa upuan sa tabi ng driver","Kahit saan sa sasakyan","Sa kotseng sumusunod sa likod"],"h1":"Kailangan nilang makita ang daan at tumulong agad.","h2":"Sa New Mexico, ang nagbabantay na driver ay dapat umupo sa upuan sa tabi ng may permit.","p":"Tama. Ang superbisor ay nakaupo sa tabi mo."},"ar":{"q":"في New Mexico، أين يجب أن يجلس السائق المشرف؟","o":["في أي مقعد خلفي","في المقعد بجانب السائق","في أي مكان في السيارة","في سيارة تسير خلفك"],"h1":"يحتاج أن يرى الطريق وأن يساعد فورًا.","h2":"في New Mexico يجب أن يجلس السائق المشرف في المقعد بجانب حامل تصريح التعلّم.","p":"صحيح. يجلس المشرف بجانبك."},"ref":{"doc":"NM","page":1}},{"id":"nm-006","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold an instruction permit before a provisional license?","o":["At least one month","At least three months","At least six months","At least two years"],"h1":"It is half a year.","h2":"In New Mexico you must hold an instruction permit for at least six months before getting a provisional license.","p":"Correct. Six months is the minimum."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener el permiso de instrucción antes de la licencia provisional?","o":["Por lo menos un mes","Por lo menos tres meses","Por lo menos seis meses","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Nuevo México usted debe tener el permiso de instrucción por lo menos seis meses antes de obtener la licencia provisional.","p":"Correcto. Seis meses es el mínimo."},"zh":{"q":"在 New Mexico，拿过渡驾照（provisional license）前，必须持有学习驾照多久？","o":["至少一个月","至少三个月","至少六个月","至少两年"],"h1":"它是半年。","h2":"在 New Mexico，你必须持有学习驾照至少六个月，才能拿过渡驾照。","p":"对。最少六个月。"},"vi":{"q":"Ở New Mexico, bạn phải giữ giấy phép tập lái bao lâu trước khi được bằng lái tạm thời (provisional license)?","o":["Ít nhất một tháng","Ít nhất ba tháng","Ít nhất sáu tháng","Ít nhất hai năm"],"h1":"Nó là nửa năm.","h2":"Ở New Mexico, bạn phải giữ giấy phép tập lái ít nhất sáu tháng trước khi được bằng lái tạm thời.","p":"Đúng. Ít nhất là sáu tháng."},"tl":{"q":"Sa New Mexico, gaano katagal mo dapat hawak ang instruction permit bago makakuha ng provisional license?","o":["Hindi bababa sa isang buwan","Hindi bababa sa tatlong buwan","Hindi bababa sa anim na buwan","Hindi bababa sa dalawang taon"],"h1":"Ito ay kalahating taon.","h2":"Sa New Mexico, dapat mong hawak ang instruction permit nang hindi bababa sa anim na buwan bago makakuha ng provisional license.","p":"Tama. Anim na buwan ang pinakamaikli."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تحمل تصريح التعلّم قبل الحصول على الرخصة المؤقتة (provisional license)؟","o":["شهر واحد على الأقل","ثلاثة أشهر على الأقل","ستة أشهر على الأقل","سنتان على الأقل"],"h1":"إنها نصف سنة.","h2":"في New Mexico يجب أن تحمل تصريح التعلّم ستة أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. ستة أشهر هي أقل مدة."},"ref":{"doc":"NM","page":1}},{"id":"nm-007","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what happens to the permit waiting period if you get a traffic violation while driving on a permit?","o":["Nothing changes","It starts over from zero","It grows by one year","It grows by 30 days for each violation"],"h1":"Each ticket adds about one month.","h2":"In New Mexico the six-month permit period is extended by 30 days for each traffic violation committed while driving on the permit.","p":"Right. Each violation adds 30 days."},"es":{"q":"En Nuevo México, ¿qué pasa con el período de espera del permiso si comete una infracción de tránsito mientras maneja con permiso?","o":["No cambia nada","Empieza otra vez desde cero","Aumenta un año","Aumenta 30 días por cada infracción"],"h1":"Cada multa agrega más o menos un mes.","h2":"En Nuevo México, el período de seis meses con permiso se alarga 30 días por cada infracción de tránsito cometida mientras maneja con el permiso.","p":"Correcto. Cada infracción agrega 30 días."},"zh":{"q":"在 New Mexico，如果你用学习驾照开车时有交通违规，学习驾照的等待期会怎样？","o":["没有改变","从零重新开始","多一年","每次违规多 30 天"],"h1":"每张罚单大约多一个月。","h2":"在 New Mexico，用学习驾照开车时每有一次交通违规，六个月的学习驾照期就延长 30 天。","p":"对。每次违规多 30 天。"},"vi":{"q":"Ở New Mexico, thời gian chờ của giấy phép tập lái thay đổi thế nào nếu bạn vi phạm luật giao thông khi đang lái bằng giấy phép tập lái?","o":["Không có gì thay đổi","Nó bắt đầu lại từ số không","Nó dài thêm một năm","Nó dài thêm 30 ngày cho mỗi lần vi phạm"],"h1":"Mỗi vé phạt thêm khoảng một tháng.","h2":"Ở New Mexico, thời gian sáu tháng của giấy phép tập lái được kéo dài thêm 30 ngày cho mỗi lần vi phạm luật giao thông khi đang lái bằng giấy phép tập lái.","p":"Đúng. Mỗi lần vi phạm thêm 30 ngày."},"tl":{"q":"Sa New Mexico, ano ang mangyayari sa panahon ng paghihintay ng permit kung magkaroon ka ng traffic violation habang nagmamaneho gamit ang permit?","o":["Walang nagbabago","Magsisimula ulit ito sa zero","Hahaba ito nang isang taon","Hahaba ito nang 30 araw sa bawat violation"],"h1":"Ang bawat tiket ay nagdadagdag ng mga isang buwan.","h2":"Sa New Mexico, ang anim na buwan ng permit ay hahaba nang 30 araw sa bawat traffic violation na nagawa habang nagmamaneho gamit ang permit.","p":"Tama. Ang bawat violation ay nagdadagdag ng 30 araw."},"ar":{"q":"في New Mexico، ماذا يحدث لمدة انتظار التصريح إذا ارتكبت مخالفة مرورية وأنت تقود بتصريح التعلّم؟","o":["لا يتغيّر شيء","تبدأ من الصفر من جديد","تزيد سنة واحدة","تزيد 30 يومًا عن كل مخالفة"],"h1":"كل مخالفة تضيف شهرًا تقريبًا.","h2":"في New Mexico تزيد مدة التصريح البالغة ستة أشهر 30 يومًا عن كل مخالفة مرورية تُرتكب أثناء القيادة بتصريح التعلّم.","p":"صحيح. كل مخالفة تضيف 30 يومًا."},"ref":{"doc":"NM","page":null}},{"id":"nm-008","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, how many hours of supervised driving practice do you need before a provisional license?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In New Mexico you need a total of 50 hours of supervised driving practice before a provisional license.","p":"Correct. New Mexico asks for 50 hours."},"es":{"q":"En Nuevo México, ¿cuántas horas de práctica supervisada necesita antes de la licencia provisional?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Nuevo México usted necesita un total de 50 horas de práctica supervisada antes de la licencia provisional.","p":"Correcto. Nuevo México pide 50 horas."},"zh":{"q":"在 New Mexico，拿过渡驾照前需要多少小时有人监督的驾驶练习？","o":["50 小时","20 小时","30 小时","100 小时"],"h1":"它是 30 到 100 之间的一个整数。","h2":"在 New Mexico，拿过渡驾照前一共需要 50 小时有人监督的驾驶练习。","p":"对。New Mexico 要求 50 小时。"},"vi":{"q":"Ở New Mexico, bạn cần bao nhiêu giờ tập lái có người giám sát trước khi được bằng lái tạm thời?","o":["50 giờ","20 giờ","30 giờ","100 giờ"],"h1":"Nó là một số tròn ở giữa 30 và 100.","h2":"Ở New Mexico, bạn cần tổng cộng 50 giờ tập lái có người giám sát trước khi được bằng lái tạm thời.","p":"Đúng. New Mexico yêu cầu 50 giờ."},"tl":{"q":"Sa New Mexico, ilang oras ng pagsasanay sa pagmamaneho na may nagbabantay ang kailangan mo bago makakuha ng provisional license?","o":["50 oras","20 oras","30 oras","100 oras"],"h1":"Ito ay isang buong numero sa pagitan ng 30 at 100.","h2":"Sa New Mexico, kailangan mo ng kabuuang 50 oras ng pagsasanay sa pagmamaneho na may nagbabantay bago makakuha ng provisional license.","p":"Tama. Humihingi ang New Mexico ng 50 oras."},"ar":{"q":"في New Mexico، كم ساعة من التدرّب على القيادة مع مشرف تحتاج قبل الحصول على الرخصة المؤقتة؟","o":["50 ساعة","20 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد مُقرَّب بين 30 و100.","h2":"في New Mexico تحتاج إلى 50 ساعة في المجموع من التدرّب على القيادة مع مشرف قبل الحصول على الرخصة المؤقتة.","p":"صحيح. تطلب New Mexico 50 ساعة."},"ref":{"doc":"NM","page":1}},{"id":"nm-009","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many of the supervised practice hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 20 hours"],"h1":"It is one fifth of the total.","h2":"In New Mexico at least 10 of the 50 supervised practice hours must be at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Nuevo México, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es la quinta parte del total.","h2":"En Nuevo México, por lo menos 10 de las 50 horas de práctica supervisada deben ser de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 New Mexico，有人监督的练习时间里，有多少小时必须在晚上？","o":["至少 2 小时","至少 10 小时","至少 5 小时","至少 20 小时"],"h1":"它是全部时间的五分之一。","h2":"在 New Mexico，50 小时有人监督的练习里，至少 10 小时必须在晚上。","p":"对。十小时必须在晚上。"},"vi":{"q":"Ở New Mexico, bao nhiêu giờ tập lái có người giám sát phải là vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ"],"h1":"Nó là một phần năm của tổng số.","h2":"Ở New Mexico, ít nhất 10 trong 50 giờ tập lái có người giám sát phải là vào ban đêm.","p":"Đúng. Mười giờ phải là vào ban đêm."},"tl":{"q":"Sa New Mexico, ilan sa mga oras ng pagsasanay na may nagbabantay ang dapat sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay one fifth (isang ikalima) ng kabuuan.","h2":"Sa New Mexico, hindi bababa sa 10 sa 50 oras ng pagsasanay na may nagbabantay ang dapat sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في New Mexico، كم ساعة من ساعات التدرّب مع مشرف يجب أن تكون في الليل؟","o":["ساعتان على الأقل (2)","10 ساعات على الأقل","5 ساعات على الأقل","20 ساعة على الأقل"],"h1":"إنها خُمس المجموع.","h2":"في New Mexico يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من التدرّب مع مشرف في الليل.","p":"صحيح. يجب أن تكون عشر ساعات في الليل."},"ref":{"doc":"NM","page":1}},{"id":"nm-010","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, who must certify in writing that the supervised practice hours are done?","o":["A school teacher","Any friend over 18","A parent or guardian","The permit holder alone"],"h1":"It is the adult legally responsible for the teen.","h2":"In New Mexico a parent or guardian must certify in writing that the 50 supervised practice hours are complete.","p":"Correct. A parent or guardian signs for the hours."},"es":{"q":"En Nuevo México, ¿quién debe certificar por escrito que se completaron las horas de práctica supervisada?","o":["Un maestro de la escuela","Cualquier amigo mayor de 18","Un padre o tutor","Solo quien tiene el permiso"],"h1":"Es el adulto legalmente responsable del joven.","h2":"En Nuevo México, un padre o tutor debe certificar por escrito que se completaron las 50 horas de práctica supervisada.","p":"Correcto. Un padre o tutor firma por las horas."},"zh":{"q":"在 New Mexico，谁必须书面证明有人监督的练习时间已经完成？","o":["学校老师","任何 18 岁以上的朋友","父母或监护人","学习驾照持有人自己"],"h1":"是在法律上对青少年负责的成年人。","h2":"在 New Mexico，父母或监护人必须书面证明 50 小时有人监督的练习已经完成。","p":"对。父母或监护人为练习时间签字。"},"vi":{"q":"Ở New Mexico, ai phải xác nhận bằng văn bản rằng các giờ tập lái có người giám sát đã xong?","o":["Một giáo viên ở trường","Bất kỳ người bạn nào trên 18 tuổi","Cha mẹ hoặc người giám hộ","Chỉ người có giấy phép tập lái"],"h1":"Đó là người lớn chịu trách nhiệm pháp lý cho thanh thiếu niên.","h2":"Ở New Mexico, cha mẹ hoặc người giám hộ phải xác nhận bằng văn bản rằng 50 giờ tập lái có người giám sát đã xong.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa New Mexico, sino ang dapat magpatunay nang nakasulat na tapos na ang mga oras ng pagsasanay na may nagbabantay?","o":["Isang guro sa paaralan","Kahit sinong kaibigan na higit 18","Isang magulang o guardian","Ang may permit lamang"],"h1":"Siya ang adult na legal na responsable sa teen.","h2":"Sa New Mexico, ang isang magulang o guardian ay dapat magpatunay nang nakasulat na tapos na ang 50 oras ng pagsasanay na may nagbabantay.","p":"Tama. Ang magulang o guardian ang pumipirma para sa mga oras."},"ar":{"q":"في New Mexico، من يجب أن يؤكّد كتابيًا أن ساعات التدرّب مع مشرف قد اكتملت؟","o":["معلّم في المدرسة","أي صديق عمره أكثر من 18","أحد الوالدين أو الوصي","حامل التصريح وحده"],"h1":"إنه الشخص البالغ المسؤول قانونيًا عن المراهق.","h2":"في New Mexico يجب أن يؤكّد أحد الوالدين أو الوصي كتابيًا أن الـ 50 ساعة من التدرّب مع مشرف قد اكتملت.","p":"صحيح. يوقّع أحد الوالدين أو الوصي على الساعات."},"ref":{"doc":"NM","page":1}},{"id":"nm-011","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, during which hours is a provisional license holder not allowed to drive, unless an exception applies?","o":["9 p.m. to 5 a.m.","10 p.m. to 6 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"The limit starts when the date changes.","h2":"In New Mexico a provisional license holder may not drive from midnight to 5 a.m. unless an exception applies, such as a licensed driver 21 or older in the vehicle.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Nuevo México, ¿en qué horario no puede manejar quien tiene licencia provisional, salvo una excepción?","o":["De 9 p.m. a 5 a.m.","De 10 p.m. a 6 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza cuando cambia la fecha.","h2":"En Nuevo México, quien tiene licencia provisional no puede manejar de medianoche a 5 a.m., salvo una excepción, como ir con un conductor con licencia de 21 años o más.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"zh":{"q":"在 New Mexico，除非有例外情况，过渡驾照持有人在哪个时间段不能开车？","o":["晚上 9 点到早上 5 点","晚上 10 点到早上 6 点","晚上 11 点到凌晨 4 点","午夜到早上 5 点"],"h1":"限制从日期改变的时候开始。","h2":"在 New Mexico，过渡驾照持有人从午夜到早上 5 点不能开车，除非有例外情况，比如车里有一位 21 岁或以上、有驾照的司机。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở New Mexico, người có bằng lái tạm thời không được lái xe trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["9 giờ tối đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng","11 giờ tối đến 4 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu khi sang ngày mới.","h2":"Ở New Mexico, người có bằng lái tạm thời không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có ngoại lệ, ví dụ có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa New Mexico, sa anong mga oras bawal magmaneho ang may provisional license, maliban kung may exception?","o":["9 p.m. hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","11 p.m. hanggang 4 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagpalit ang petsa.","h2":"Sa New Mexico, ang may provisional license ay bawal magmaneho mula hatinggabi hanggang 5 a.m. maliban kung may exception, gaya ng lisensiyadong driver na 21 taong gulang pataas na nasa sasakyan.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في New Mexico، في أي ساعات لا يُسمح لحامل الرخصة المؤقتة بالقيادة، إلا إذا كان هناك استثناء؟","o":["من 9 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 11 مساءً إلى 4 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"يبدأ المنع عندما يتغيّر التاريخ.","h2":"في New Mexico لا يجوز لحامل الرخصة المؤقتة أن يقود من منتصف الليل إلى 5 صباحًا إلا إذا كان هناك استثناء، مثل وجود سائق مرخَّص عمره 21 سنة أو أكثر في السيارة.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"NM","page":1}},{"id":"nm-012","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, a provisional license holder wants to drive at 1 a.m. Which situation allows it?","o":["A licensed driver 21 or older is in the vehicle","A friend 18 years old is in the vehicle","The driver feels wide awake","The roads are empty"],"h1":"Think of the same kind of adult who supervises a permit holder.","h2":"In New Mexico a provisional license holder may drive between midnight and 5 a.m. when a licensed driver 21 or older is in the vehicle.","p":"Correct. An adult driver 21 or older makes it allowed."},"es":{"q":"En Nuevo México, alguien con licencia provisional quiere manejar a la 1 a.m. ¿Qué situación lo permite?","o":["Va en el vehículo un conductor con licencia de 21 años o más","Va en el vehículo un amigo de 18 años","El conductor se siente bien despierto","Las calles están vacías"],"h1":"Piense en el mismo tipo de adulto que supervisa a quien tiene permiso.","h2":"En Nuevo México, quien tiene licencia provisional puede manejar entre medianoche y 5 a.m. si va en el vehículo un conductor con licencia de 21 años o más.","p":"Correcto. Un conductor adulto de 21 años o más lo permite."},"zh":{"q":"在 New Mexico，过渡驾照持有人想在凌晨 1 点开车。哪种情况可以？","o":["车里有一位 21 岁或以上、有驾照的司机","车里有一位 18 岁的朋友","司机觉得很清醒","路上没有车"],"h1":"想想监督学习驾照持有人的是哪种成年人。","h2":"在 New Mexico，如果车里有一位 21 岁或以上、有驾照的司机，过渡驾照持有人可以在午夜到早上 5 点之间开车。","p":"对。有一位 21 岁或以上的成年司机就可以。"},"vi":{"q":"Ở New Mexico, một người có bằng lái tạm thời muốn lái xe lúc 1 giờ sáng. Trường hợp nào cho phép điều đó?","o":["Có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe","Có một người bạn 18 tuổi ở trong xe","Người lái cảm thấy rất tỉnh táo","Đường vắng"],"h1":"Hãy nghĩ đến loại người lớn giống như người giám sát người có giấy phép tập lái.","h2":"Ở New Mexico, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Một người lớn có bằng lái từ 21 tuổi trở lên làm cho việc này được phép."},"tl":{"q":"Sa New Mexico, gustong magmaneho ng isang may provisional license nang 1 a.m. Anong sitwasyon ang pumapayag dito?","o":["May lisensiyadong driver na 21 taong gulang pataas sa sasakyan","May kaibigang 18 taong gulang sa sasakyan","Gising na gising ang pakiramdam ng driver","Walang tao sa mga kalsada"],"h1":"Isipin ang parehong uri ng adult na nagbabantay sa may permit.","h2":"Sa New Mexico, ang may provisional license ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. kapag may lisensiyadong driver na 21 taong gulang pataas sa sasakyan.","p":"Tama. Puwede ito kung may adult na driver na 21 taong gulang pataas."},"ar":{"q":"في New Mexico، يريد حامل رخصة مؤقتة أن يقود في الساعة 1 صباحًا. أي حالة تسمح بذلك؟","o":["وجود سائق مرخَّص عمره 21 سنة أو أكثر في السيارة","وجود صديق عمره 18 سنة في السيارة","شعور السائق بأنه مستيقظ تمامًا","خلوّ الطرق من السيارات"],"h1":"فكّر في نفس نوع الشخص البالغ الذي يشرف على حامل تصريح التعلّم.","h2":"في New Mexico يجوز لحامل الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا عندما يكون في السيارة سائق مرخَّص عمره 21 سنة أو أكثر.","p":"صحيح. وجود سائق بالغ عمره 21 سنة أو أكثر يجعل ذلك مسموحًا."},"ref":{"doc":"NM","page":2}},{"id":"nm-013","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how many passengers under 21 who are not immediate family may a provisional driver carry?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"It is the smallest number that is not zero.","h2":"In New Mexico a provisional driver may carry no more than one passenger under 21 who is not immediate family, unless a licensed driver 21 or older is in the vehicle.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Nuevo México, ¿cuántos pasajeros menores de 21 años que no son familia directa puede llevar un conductor provisional?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nuevo México, un conductor provisional no puede llevar más de un pasajero menor de 21 años que no sea familia directa, salvo que vaya un conductor con licencia de 21 años o más.","p":"Correcto. Solo un pasajero joven que no sea familia."},"zh":{"q":"在 New Mexico，过渡驾照司机可以载几位不是直系亲属、未满 21 岁的乘客？","o":["一位也不行","不超过一位","不超过两位","不超过三位"],"h1":"它是不等于零的最小数字。","h2":"在 New Mexico，过渡驾照司机最多只能载一位不是直系亲属、未满 21 岁的乘客，除非车里有一位 21 岁或以上、有驾照的司机。","p":"对。只能载一位不是家人的年轻乘客。"},"vi":{"q":"Ở New Mexico, người có bằng lái tạm thời được chở bao nhiêu hành khách dưới 21 tuổi không phải là người thân trong gia đình?","o":["Không ai cả","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Nó là số nhỏ nhất mà không phải là số không.","h2":"Ở New Mexico, người có bằng lái tạm thời được chở không quá một hành khách dưới 21 tuổi không phải là người thân trong gia đình, trừ khi có một người lái xe có bằng từ 21 tuổi trở lên ở trong xe.","p":"Đúng. Chỉ một hành khách trẻ không phải người thân."},"tl":{"q":"Sa New Mexico, ilang pasahero na wala pang 21 at hindi malapit na kapamilya ang puwedeng isakay ng provisional driver?","o":["Wala talaga","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Ito ang pinakamaliit na numero na hindi zero.","h2":"Sa New Mexico, ang provisional driver ay puwedeng magsakay ng hindi hihigit sa isang pasahero na wala pang 21 at hindi malapit na kapamilya, maliban kung may lisensiyadong driver na 21 taong gulang pataas sa sasakyan.","p":"Tama. Isa lang na batang pasahero na hindi kapamilya."},"ar":{"q":"في New Mexico، كم راكبًا عمره أقل من 21 وليس من العائلة القريبة يجوز للسائق بالرخصة المؤقتة أن ينقل؟","o":["لا أحد أبدًا","راكب واحد فقط على الأكثر","راكبان على الأكثر","ثلاثة ركاب على الأكثر"],"h1":"إنه أصغر عدد غير الصفر.","h2":"في New Mexico يجوز للسائق بالرخصة المؤقتة أن ينقل راكبًا واحدًا على الأكثر عمره أقل من 21 وليس من العائلة القريبة، إلا إذا كان في السيارة سائق مرخَّص عمره 21 سنة أو أكثر.","p":"صحيح. راكب شاب واحد فقط من خارج العائلة."},"ref":{"doc":"NM","page":1}},{"id":"nm-014","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you hold a provisional license before applying for a full license?","o":["At least 3 months","At least 6 months","At least 12 months","At least 3 years"],"h1":"It is one full year.","h2":"In New Mexico you must hold a provisional license for at least 12 months before applying for a full license.","p":"Correct. It takes at least one year."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe tener la licencia provisional antes de solicitar la licencia completa?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 12 meses","Por lo menos 3 años"],"h1":"Es un año completo.","h2":"En Nuevo México usted debe tener la licencia provisional por lo menos 12 meses antes de solicitar la licencia completa.","p":"Correcto. Se necesita por lo menos un año."},"zh":{"q":"在 New Mexico，申请正式驾照前，必须持有过渡驾照多久？","o":["至少 3 个月","至少 6 个月","至少 12 个月","至少 3 年"],"h1":"它是整整一年。","h2":"在 New Mexico，你必须持有过渡驾照至少 12 个月，才能申请正式驾照。","p":"对。至少要一年。"},"vi":{"q":"Ở New Mexico, bạn phải giữ bằng lái tạm thời bao lâu trước khi xin bằng lái đầy đủ?","o":["Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 12 tháng","Ít nhất 3 năm"],"h1":"Nó là một năm trọn.","h2":"Ở New Mexico, bạn phải giữ bằng lái tạm thời ít nhất 12 tháng trước khi xin bằng lái đầy đủ.","p":"Đúng. Cần ít nhất một năm."},"tl":{"q":"Sa New Mexico, gaano katagal mo dapat hawak ang provisional license bago mag-apply ng full license?","o":["Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 12 buwan","Hindi bababa sa 3 taon"],"h1":"Ito ay isang buong taon.","h2":"Sa New Mexico, dapat mong hawak ang provisional license nang hindi bababa sa 12 buwan bago mag-apply ng full license.","p":"Tama. Kailangan ng hindi bababa sa isang taon."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تحمل الرخصة المؤقتة قبل التقدّم بطلب الرخصة الكاملة؟","o":["3 أشهر على الأقل","6 أشهر على الأقل","12 شهرًا على الأقل","3 سنوات على الأقل"],"h1":"إنها سنة كاملة.","h2":"في New Mexico يجب أن تحمل الرخصة المؤقتة 12 شهرًا على الأقل قبل التقدّم بطلب الرخصة الكاملة.","p":"صحيح. يحتاج ذلك سنة واحدة على الأقل."},"ref":{"doc":"NM","page":2}},{"id":"nm-015","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what score do you need to pass the written test for a car license?","o":["50 percent or better","60 percent or better","90 percent or better","70 percent or better"],"h1":"It is the same as a passing grade of C in many schools.","h2":"In New Mexico you need a score of 70 percent or better to pass the written test.","p":"Right. You need 70 percent."},"es":{"q":"En Nuevo México, ¿qué calificación necesita para aprobar el examen escrito para licencia de auto?","o":["50 por ciento o más","60 por ciento o más","90 por ciento o más","70 por ciento o más"],"h1":"Es como una nota de aprobado en muchas escuelas.","h2":"En Nuevo México usted necesita 70 por ciento o más para aprobar el examen escrito.","p":"Correcto. Se necesita 70 por ciento."},"zh":{"q":"在 New Mexico，小汽车驾照的笔试要得多少分才能通过？","o":["百分之 50 或以上","百分之 60 或以上","百分之 90 或以上","百分之 70 或以上"],"h1":"它和很多学校里及格的 C 等级一样。","h2":"在 New Mexico，笔试要得百分之 70 或以上才能通过。","p":"对。你需要百分之 70。"},"vi":{"q":"Ở New Mexico, bạn cần bao nhiêu điểm để đậu bài thi viết lấy bằng lái xe hơi?","o":["50 phần trăm trở lên","60 phần trăm trở lên","90 phần trăm trở lên","70 phần trăm trở lên"],"h1":"Nó giống như điểm C đủ để đậu ở nhiều trường học.","h2":"Ở New Mexico, bạn cần được 70 phần trăm trở lên để đậu bài thi viết.","p":"Đúng. Bạn cần 70 phần trăm."},"tl":{"q":"Sa New Mexico, anong score ang kailangan mo para pumasa sa written test para sa lisensiya sa kotse?","o":["50 porsiyento o higit pa","60 porsiyento o higit pa","90 porsiyento o higit pa","70 porsiyento o higit pa"],"h1":"Ito ay katulad ng pasadong grade na C sa maraming paaralan.","h2":"Sa New Mexico, kailangan mo ng score na 70 porsiyento o higit pa para pumasa sa written test.","p":"Tama. Kailangan mo ng 70 porsiyento."},"ar":{"q":"في New Mexico، ما الدرجة التي تحتاجها لتنجح في الاختبار الكتابي لرخصة السيارة؟","o":["50 بالمئة أو أكثر","60 بالمئة أو أكثر","90 بالمئة أو أكثر","70 بالمئة أو أكثر"],"h1":"إنها مثل درجة النجاح C في مدارس كثيرة.","h2":"في New Mexico تحتاج إلى درجة 70 بالمئة أو أكثر لتنجح في الاختبار الكتابي.","p":"صحيح. تحتاج إلى 70 بالمئة."},"ref":{"doc":"NM","page":null}},{"id":"nm-016","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, in which languages can you take the written knowledge test?","o":["English, Spanish and several other languages","English only","English and Spanish only on weekends","Spanish only at the border"],"h1":"New Mexico offers more than two choices.","h2":"In New Mexico the written test is offered in English, Spanish and several other languages.","p":"Correct. Spanish and other languages are offered."},"es":{"q":"En Nuevo México, ¿en qué idiomas puede tomar el examen escrito de conocimientos?","o":["Inglés, español y varios idiomas más","Solo en inglés","Inglés y español solo los fines de semana","Español solo en la frontera"],"h1":"Nuevo México ofrece más de dos opciones.","h2":"En Nuevo México el examen escrito se ofrece en inglés, español y varios idiomas más.","p":"Correcto. Se ofrece en español y en otros idiomas."},"zh":{"q":"在 New Mexico，笔试（知识考试）可以用哪些语言考？","o":["英语、西班牙语和其他几种语言","只有英语","只在周末有英语和西班牙语","只在边境有西班牙语"],"h1":"New Mexico 提供两种以上的选择。","h2":"在 New Mexico，笔试有英语、西班牙语和其他几种语言。","p":"对。可以用西班牙语和其他语言考。"},"vi":{"q":"Ở New Mexico, bạn có thể làm bài thi kiến thức viết bằng những ngôn ngữ nào?","o":["Tiếng Anh, tiếng Tây Ban Nha và một số ngôn ngữ khác","Chỉ tiếng Anh","Tiếng Anh và tiếng Tây Ban Nha chỉ vào cuối tuần","Chỉ tiếng Tây Ban Nha ở vùng biên giới"],"h1":"New Mexico có nhiều hơn hai lựa chọn.","h2":"Ở New Mexico, bài thi viết có bằng tiếng Anh, tiếng Tây Ban Nha và một số ngôn ngữ khác.","p":"Đúng. Có tiếng Tây Ban Nha và các ngôn ngữ khác."},"tl":{"q":"Sa New Mexico, sa anong mga wika puwede mong kunin ang written knowledge test?","o":["English, Spanish at ilang iba pang wika","English lamang","English at Spanish tuwing weekend lamang","Spanish lamang sa border"],"h1":"Ang New Mexico ay may higit sa dalawang pagpipilian.","h2":"Sa New Mexico, ang written test ay mayroon sa English, Spanish at ilang iba pang wika.","p":"Tama. May Spanish at iba pang wika."},"ar":{"q":"في New Mexico، بأي لغات يمكنك أداء اختبار المعرفة الكتابي؟","o":["الإنجليزية والإسبانية وعدة لغات أخرى","الإنجليزية فقط","الإنجليزية والإسبانية في عطلة نهاية الأسبوع فقط","الإسبانية فقط عند الحدود"],"h1":"تقدّم New Mexico أكثر من خيارين.","h2":"في New Mexico يُقدَّم الاختبار الكتابي بالإنجليزية والإسبانية وعدة لغات أخرى.","p":"صحيح. الإسبانية ولغات أخرى متاحة."},"ref":{"doc":"NM","page":null}},{"id":"nm-017","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, who does not need to take the written test when getting a first New Mexico license?","o":["Anyone over 18","Someone with a current license from another state","Anyone who owns a car","Anyone with a permit from another country"],"h1":"They already hold a valid license from a US state.","h2":"In New Mexico the written test is not required if you hold a current driver license from another state.","p":"Right. A current out-of-state license skips the written test."},"es":{"q":"En Nuevo México, ¿quién no necesita tomar el examen escrito al sacar su primera licencia de Nuevo México?","o":["Cualquier persona mayor de 18","Alguien con una licencia vigente de otro estado","Cualquiera que tenga carro propio","Cualquiera con permiso de otro país"],"h1":"Esa persona ya tiene una licencia válida de un estado del país.","h2":"En Nuevo México no se exige el examen escrito si usted tiene una licencia de manejo vigente de otro estado.","p":"Correcto. Con licencia vigente de otro estado no hace falta el examen escrito."},"zh":{"q":"在 New Mexico，第一次拿 New Mexico 驾照时，谁不需要参加笔试？","o":["任何 18 岁以上的人","有其他州有效驾照的人","任何有车的人","任何有外国学习驾照的人"],"h1":"他们已经有美国某个州的有效驾照。","h2":"在 New Mexico，如果你有其他州的有效驾照，就不需要参加笔试。","p":"对。有其他州的有效驾照就不用笔试。"},"vi":{"q":"Ở New Mexico, ai không cần làm bài thi viết khi lấy bằng lái New Mexico lần đầu?","o":["Bất kỳ ai trên 18 tuổi","Người có bằng lái còn hạn của một tiểu bang khác","Bất kỳ ai có xe hơi","Bất kỳ ai có giấy phép từ một nước khác"],"h1":"Họ đã có bằng lái hợp lệ của một tiểu bang ở Mỹ.","h2":"Ở New Mexico, bạn không cần làm bài thi viết nếu bạn có bằng lái còn hạn của một tiểu bang khác.","p":"Đúng. Bằng lái còn hạn của tiểu bang khác thì không cần thi viết."},"tl":{"q":"Sa New Mexico, sino ang hindi kailangang kumuha ng written test kapag kumukuha ng unang lisensiya sa New Mexico?","o":["Kahit sinong higit 18","Isang taong may kasalukuyang lisensiya mula sa ibang estado","Kahit sinong may sariling kotse","Kahit sinong may permit mula sa ibang bansa"],"h1":"May hawak na silang balidong lisensiya mula sa isang estado sa US.","h2":"Sa New Mexico, hindi kailangan ang written test kung may hawak kang kasalukuyang driver license mula sa ibang estado.","p":"Tama. Kung may kasalukuyang lisensiya mula sa ibang estado, hindi na kailangan ang written test."},"ar":{"q":"في New Mexico، من لا يحتاج إلى أداء الاختبار الكتابي عند الحصول على أول رخصة من New Mexico؟","o":["أي شخص عمره أكثر من 18","شخص لديه رخصة سارية من ولاية أخرى","أي شخص يملك سيارة","أي شخص لديه تصريح من بلد آخر"],"h1":"لديه بالفعل رخصة سارية من ولاية أمريكية.","h2":"في New Mexico لا يُطلب الاختبار الكتابي إذا كانت لديك رخصة قيادة سارية من ولاية أخرى.","p":"صحيح. الرخصة السارية من ولاية أخرى تُعفيك من الاختبار الكتابي."},"ref":{"doc":"NM","page":null}},{"id":"nm-018","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, what blood or breath alcohol level is illegal for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In New Mexico it is illegal for a driver under 21 to drive with an alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Nuevo México, ¿qué nivel de alcohol en la sangre o el aliento es ilegal para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Nuevo México es ilegal que un conductor menor de 21 años maneje con un nivel de alcohol de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 New Mexico，未满 21 岁的司机血液或呼气酒精浓度到多少是违法的？","o":["0.08 或以上","0.05 或以上","0.02 或以上","0.10 或以上"],"h1":"它比成年人的上限低很多。","h2":"在 New Mexico，未满 21 岁的司机酒精浓度在 0.02 或以上开车是违法的。","p":"对。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở New Mexico, nồng độ cồn trong máu hoặc hơi thở bao nhiêu là phạm luật đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở New Mexico, người lái xe dưới 21 tuổi lái xe với nồng độ cồn 0.02 trở lên là phạm luật.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa New Mexico, anong antas ng alak sa dugo o hininga ang bawal para sa driver na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Ito ay mas mababa nang malaki kaysa sa limit para sa adult.","h2":"Sa New Mexico, bawal sa driver na wala pang 21 na magmaneho nang may antas ng alak na 0.02 o higit pa.","p":"Tama. Kung wala pang 21, ang limit ay 0.02."},"ar":{"q":"في New Mexico، ما نسبة الكحول في الدم أو النَّفَس التي تكون غير قانونية للسائق الذي عمره أقل من 21؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من الحد المسموح للبالغين.","h2":"في New Mexico من غير القانوني أن يقود سائق عمره أقل من 21 ونسبة الكحول لديه 0.02 أو أكثر.","p":"صحيح. لمن عمره أقل من 21، الحد هو 0.02."},"ref":{"doc":"NM","page":29}},{"id":"nm-019","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, a school bus is stopped with red lights flashing on the opposite side of a road with no median. What must you do?","o":["Keep going, because the bus is on the other side","Slow to 20 mph and pass","Honk and pass carefully","Stop, because you must stop on either side of an undivided road"],"h1":"Only a median or barrier would change the rule.","h2":"In New Mexico you must stop for a school bus with flashing red lights even on the opposite side, unless a median or physical barrier separates you from it.","p":"Right. Without a median, everyone stops."},"es":{"q":"En Nuevo México, un autobús escolar está detenido con luces rojas intermitentes al otro lado de una calle sin mediana. ¿Qué debe hacer?","o":["Seguir, porque el autobús está del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado","Detenerse, porque en una calle sin división se detiene de los dos lados"],"h1":"Solo una mediana o barrera cambiaría la regla.","h2":"En Nuevo México debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté del otro lado, salvo que lo separe una mediana o barrera física.","p":"Correcto. Sin mediana, todos se detienen."},"zh":{"q":"在 New Mexico，一条没有中间隔离带的路上，对面停着一辆闪着红灯的校车。你必须怎么做？","o":["继续开，因为校车在对面","减速到 20 mph 然后经过","按喇叭然后小心经过","停车，因为在没有分隔的路上，两边都必须停车"],"h1":"只有中间隔离带或障碍物才会改变规定。","h2":"在 New Mexico，就算校车在对面，只要它闪着红灯，你也必须停车，除非有中间隔离带或实体障碍物把你和它分开。","p":"对。没有中间隔离带，所有人都要停车。"},"vi":{"q":"Ở New Mexico, một xe buýt trường học đang dừng và nháy đèn đỏ ở phía bên kia của một con đường không có dải phân cách. Bạn phải làm gì?","o":["Cứ đi tiếp, vì xe buýt ở phía bên kia","Giảm còn 20 mph và vượt qua","Bấm còi và vượt qua cẩn thận","Dừng lại, vì bạn phải dừng ở cả hai phía của đường không có dải phân cách"],"h1":"Chỉ có dải phân cách hoặc rào chắn mới làm thay đổi luật.","h2":"Ở New Mexico, bạn phải dừng lại khi xe buýt trường học nháy đèn đỏ, ngay cả khi nó ở phía bên kia đường, trừ khi có dải phân cách hoặc rào chắn ngăn cách bạn với xe buýt.","p":"Đúng. Không có dải phân cách thì mọi người đều dừng."},"tl":{"q":"Sa New Mexico, may school bus na nakahinto at kumikislap ang pulang ilaw sa kabilang panig ng daan na walang median (harang sa gitna). Ano ang dapat mong gawin?","o":["Tuloy lang, dahil nasa kabilang panig ang bus","Bumagal sa 20 mph at lumampas","Bumusina at lumampas nang maingat","Huminto, dahil dapat kang huminto sa alinmang panig ng daan na walang harang sa gitna"],"h1":"Median o harang lamang ang makapagbabago ng patakaran.","h2":"Sa New Mexico, dapat kang huminto para sa school bus na may kumikislap na pulang ilaw kahit nasa kabilang panig ito, maliban kung may median o pisikal na harang sa pagitan ninyo.","p":"Tama. Kung walang median, lahat ay humihinto."},"ar":{"q":"في New Mexico، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب المقابل من طريق ليس فيه فاصل في الوسط (median). ماذا يجب أن تفعل؟","o":["أكمل السير، لأن الحافلة على الجانب الآخر","خفّف السرعة إلى 20 mph وتجاوزها","اضغط على البوق وتجاوز بحذر","توقّف، لأنه يجب التوقف على الجانبين في الطريق غير المقسوم"],"h1":"فقط الفاصل في الوسط أو الحاجز يغيّر القاعدة.","h2":"في New Mexico يجب أن تتوقف للحافلة المدرسية التي تومض أضواؤها الحمراء حتى لو كانت على الجانب المقابل، إلا إذا كان بينك وبينها فاصل في الوسط أو حاجز مادي.","p":"صحيح. بدون فاصل في الوسط، يتوقف الجميع."},"ref":{"doc":"NM","page":12}},{"id":"nm-020","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, when do you not have to stop for a school bus with flashing red lights?","o":["When it is coming toward you and a median or barrier separates the roads","When you are behind it","When it is at an intersection ahead","When you are late for work"],"h1":"It depends on the bus's direction and what lies between you.","h2":"In New Mexico you do not have to stop when the school bus is traveling toward you on a road separated by a median or other physical barrier.","p":"Correct. A median and opposite direction mean no stop."},"es":{"q":"En Nuevo México, ¿cuándo no tiene que detenerse por un autobús escolar con luces rojas intermitentes?","o":["Cuando viene hacia usted y una mediana o barrera separa los carriles","Cuando usted va detrás de él","Cuando está en una intersección adelante","Cuando usted va tarde al trabajo"],"h1":"Depende de la dirección del autobús y de lo que hay entre ustedes.","h2":"En Nuevo México no tiene que detenerse cuando el autobús escolar viene hacia usted por una vía separada por una mediana u otra barrera física.","p":"Correcto. Con mediana y en dirección contraria, no se detiene."},"zh":{"q":"在 New Mexico，什么时候不用为闪着红灯的校车停车？","o":["校车朝你开过来，而且中间隔离带或障碍物把道路分开时","你在校车后面时","校车在前面路口时","你上班要迟到时"],"h1":"这要看校车的方向，和你们中间有什么。","h2":"在 New Mexico，如果校车在有中间隔离带或其他实体障碍物分开的路上朝你开过来，你不用停车。","p":"对。有中间隔离带，而且方向相反，就不用停车。"},"vi":{"q":"Ở New Mexico, khi nào bạn không phải dừng lại cho xe buýt trường học đang nháy đèn đỏ?","o":["Khi nó đang chạy về phía bạn và có dải phân cách hoặc rào chắn ngăn cách hai bên đường","Khi bạn ở phía sau nó","Khi nó ở ngã tư phía trước","Khi bạn bị trễ giờ làm"],"h1":"Nó phụ thuộc vào hướng đi của xe buýt và những gì ở giữa bạn và xe buýt.","h2":"Ở New Mexico, bạn không phải dừng lại khi xe buýt trường học đang chạy về phía bạn trên con đường có dải phân cách hoặc rào chắn khác ngăn cách.","p":"Đúng. Có dải phân cách và đi ngược chiều thì không cần dừng."},"tl":{"q":"Sa New Mexico, kailan hindi mo kailangang huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Kapag papunta ito sa direksiyon mo at may median o harang sa pagitan ng mga daan","Kapag nasa likod ka nito","Kapag nasa intersection ito sa unahan","Kapag late ka na sa trabaho"],"h1":"Depende ito sa direksiyon ng bus at kung ano ang nasa pagitan ninyo.","h2":"Sa New Mexico, hindi mo kailangang huminto kapag ang school bus ay papunta sa direksiyon mo sa daan na may median o ibang pisikal na harang sa pagitan.","p":"Tama. Kung may median at kabilang direksiyon, hindi kailangang huminto."},"ar":{"q":"في New Mexico، متى لا يكون عليك أن تتوقف لحافلة مدرسية تومض أضواؤها الحمراء؟","o":["عندما تكون قادمة نحوك ويفصل بين الطريقين فاصل في الوسط أو حاجز","عندما تكون خلفها","عندما تكون عند تقاطع أمامك","عندما تكون متأخرًا عن العمل"],"h1":"يعتمد ذلك على اتجاه الحافلة وعلى ما يوجد بينك وبينها.","h2":"في New Mexico ليس عليك أن تتوقف عندما تكون الحافلة المدرسية قادمة نحوك على طريق يفصله فاصل في الوسط أو حاجز مادي آخر.","p":"صحيح. الفاصل في الوسط مع الاتجاه المعاكس يعني عدم التوقف."},"ref":{"doc":"NM","page":12}},{"id":"nm-021","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, what does state law say about texting while driving?","o":["It is allowed at speeds under 30 mph","It is against the law to read or type text messages while driving","It is allowed on rural roads","It is only a warning, never a fine"],"h1":"It carries a fine.","h2":"In New Mexico it is against the law to read, view or type text messages on a phone while driving, and it carries a fine.","p":"Right. Texting while driving is illegal."},"es":{"q":"En Nuevo México, ¿qué dice la ley estatal sobre los mensajes de texto al manejar?","o":["Se permite a menos de 30 mph","Es ilegal leer o escribir mensajes de texto mientras maneja","Se permite en caminos rurales","Es solo una advertencia, nunca una multa"],"h1":"Tiene una multa.","h2":"En Nuevo México es ilegal leer, ver o escribir mensajes de texto en un teléfono mientras maneja, y tiene una multa.","p":"Correcto. Escribir mensajes al manejar es ilegal."},"zh":{"q":"在 New Mexico，州法律对开车时发短信是怎么规定的？","o":["车速低于 30 mph 时可以","开车时看或打短信是违法的","在乡村道路上可以","只会警告，不会罚款"],"h1":"它会被罚款。","h2":"在 New Mexico，开车时在手机上看、读或打短信是违法的，会被罚款。","p":"对。开车时发短信是违法的。"},"vi":{"q":"Ở New Mexico, luật tiểu bang nói gì về việc nhắn tin khi lái xe?","o":["Được phép khi chạy dưới 30 mph","Đọc hoặc gõ tin nhắn khi lái xe là phạm luật","Được phép trên đường nông thôn","Chỉ bị cảnh cáo, không bao giờ bị phạt tiền"],"h1":"Nó bị phạt tiền.","h2":"Ở New Mexico, đọc, xem hoặc gõ tin nhắn trên điện thoại khi lái xe là phạm luật và bị phạt tiền.","p":"Đúng. Nhắn tin khi lái xe là phạm luật."},"tl":{"q":"Sa New Mexico, ano ang sinasabi ng batas ng estado tungkol sa pag-text habang nagmamaneho?","o":["Puwede ito kapag ang bilis ay mas mababa sa 30 mph","Labag sa batas ang magbasa o mag-type ng text message habang nagmamaneho","Puwede ito sa mga daan sa probinsiya","Babala lang ito, hindi kailanman multa"],"h1":"May multa ito.","h2":"Sa New Mexico, labag sa batas ang magbasa, tumingin o mag-type ng text message sa telepono habang nagmamaneho, at may multa ito.","p":"Tama. Bawal ang pag-text habang nagmamaneho."},"ar":{"q":"في New Mexico، ماذا يقول قانون الولاية عن كتابة الرسائل النصية أثناء القيادة؟","o":["إنها مسموحة بسرعة أقل من 30 mph","من المخالف للقانون قراءة أو كتابة الرسائل النصية أثناء القيادة","إنها مسموحة على الطرق الريفية","إنها تحذير فقط، ولا غرامة أبدًا"],"h1":"عليها غرامة.","h2":"في New Mexico من المخالف للقانون قراءة الرسائل النصية أو مشاهدتها أو كتابتها على الهاتف أثناء القيادة، وعليها غرامة.","p":"صحيح. كتابة الرسائل النصية أثناء القيادة مخالفة للقانون."},"ref":{"doc":"NM","page":null}},{"id":"nm-022","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what happens if a driver gets 12 or more points within 12 months?","o":["A warning letter only","A 30-day suspension","A one-year suspension","A fine but no suspension"],"h1":"The suspension lasts as long as the period the points are counted in.","h2":"In New Mexico, a driver with 12 or more points within 12 months has the license suspended for one year.","p":"Right. 12 points in a year means a one-year suspension."},"es":{"q":"En Nuevo México, ¿qué pasa si un conductor acumula 12 puntos o más en 12 meses?","o":["Solo una carta de advertencia","Una suspensión de 30 días","Una suspensión de un año","Una multa pero sin suspensión"],"h1":"La suspensión dura lo mismo que el período en que se cuentan los puntos.","h2":"En Nuevo México, a un conductor con 12 puntos o más en 12 meses le suspenden la licencia por un año.","p":"Correcto. 12 puntos en un año significan una suspensión de un año."},"zh":{"q":"在 New Mexico，如果司机在 12 个月内被记 12 分或更多，会怎样？","o":["只收到一封警告信","暂停驾照 30 天","暂停驾照一年","罚款，但不暂停驾照"],"h1":"暂停的时间和计算分数的时间一样长。","h2":"在 New Mexico，司机在 12 个月内被记 12 分或更多，驾照会被暂停一年。","p":"对。一年内 12 分，就会暂停驾照一年。"},"vi":{"q":"Ở New Mexico, điều gì xảy ra nếu một tài xế bị 12 điểm trở lên trong vòng 12 tháng?","o":["Chỉ nhận một thư cảnh cáo","Bị đình chỉ bằng lái 30 ngày","Bị đình chỉ bằng lái một năm","Bị phạt tiền nhưng không bị đình chỉ"],"h1":"Thời gian đình chỉ dài bằng khoảng thời gian tính điểm.","h2":"Ở New Mexico, tài xế bị 12 điểm trở lên trong vòng 12 tháng sẽ bị đình chỉ bằng lái một năm.","p":"Đúng. 12 điểm trong một năm nghĩa là bị đình chỉ một năm."},"tl":{"q":"Sa New Mexico, ano ang mangyayari kung ang isang driver ay magkaroon ng 12 puntos o higit pa sa loob ng 12 buwan?","o":["Isang sulat ng babala lang","Suspensyon ng 30 araw","Suspensyon ng isang taon","Multa pero walang suspensyon"],"h1":"Ang haba ng suspensyon ay kapareho ng panahon kung kailan binibilang ang mga puntos.","h2":"Sa New Mexico, ang driver na may 12 puntos o higit pa sa loob ng 12 buwan ay masususpinde ang lisensya nang isang taon.","p":"Tama. Ang 12 puntos sa isang taon ay nangangahulugang suspensyon ng isang taon."},"ar":{"q":"في New Mexico، ماذا يحدث إذا حصل السائق على 12 نقطة أو أكثر خلال 12 شهرًا؟","o":["رسالة تحذير فقط","إيقاف الرخصة لمدة 30 يومًا","إيقاف الرخصة لمدة سنة واحدة","غرامة بدون إيقاف"],"h1":"مدة الإيقاف تساوي المدة التي تُحسب فيها النقاط.","h2":"في New Mexico، السائق الذي يحصل على 12 نقطة أو أكثر خلال 12 شهرًا تُوقف رخصته لمدة سنة واحدة.","p":"صحيح. 12 نقطة في سنة تعني إيقاف الرخصة لمدة سنة."},"ref":{"doc":"NM","page":14}},{"id":"nm-023","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, what can happen if you refuse an alcohol test when a police officer asks?","o":["You can lose your license for one year","Nothing, the test is your choice","You get a warning the first time","You only pay a small fine"],"h1":"Saying no to the test has its own penalty.","h2":"In New Mexico, if you refuse a blood alcohol test when an officer asks, you can lose your driver license for one year.","p":"Right. Refusing the test can cost your license for a year."},"es":{"q":"En Nuevo México, ¿qué puede pasar si usted se niega a una prueba de alcohol cuando un policía se la pide?","o":["Puede perder su licencia por un año","Nada, la prueba es opcional","Recibe una advertencia la primera vez","Solo paga una multa pequeña"],"h1":"Negarse a la prueba tiene su propio castigo.","h2":"En Nuevo México, si usted se niega a una prueba de alcohol en la sangre cuando un policía se la pide, puede perder su licencia de manejar por un año.","p":"Correcto. Negarse a la prueba puede costarle la licencia por un año."},"zh":{"q":"在 New Mexico，如果警察要求你做酒精测试而你拒绝，会发生什么？","o":["你可能失去驾照一年","什么都不会发生，测试由你决定","第一次只会收到警告","你只需要付一小笔罚款"],"h1":"拒绝测试本身就有惩罚。","h2":"在 New Mexico，如果警察要求你做血液酒精测试而你拒绝，你可能失去驾照一年。","p":"对。拒绝测试可能让你失去驾照一年。"},"vi":{"q":"Ở New Mexico, điều gì có thể xảy ra nếu bạn từ chối kiểm tra nồng độ cồn khi cảnh sát yêu cầu?","o":["Bạn có thể bị mất bằng lái một năm","Không có gì, kiểm tra là do bạn chọn","Bạn bị cảnh cáo trong lần đầu","Bạn chỉ phải trả một khoản phạt nhỏ"],"h1":"Từ chối kiểm tra cũng có hình phạt riêng.","h2":"Ở New Mexico, nếu bạn từ chối kiểm tra nồng độ cồn trong máu khi cảnh sát yêu cầu, bạn có thể bị mất bằng lái một năm.","p":"Đúng. Từ chối kiểm tra có thể khiến bạn mất bằng lái một năm."},"tl":{"q":"Sa New Mexico, ano ang puwedeng mangyari kung tumanggi ka sa alcohol test kapag hiniling ng pulis?","o":["Puwede kang mawalan ng lisensya nang isang taon","Wala, ikaw ang pipili kung magpapa-test ka","Babala ang makukuha mo sa unang beses","Maliit na multa lang ang babayaran mo"],"h1":"May sariling parusa ang pagtanggi sa test.","h2":"Sa New Mexico, kung tumanggi ka sa blood alcohol test kapag hiniling ng pulis, puwede kang mawalan ng driver license nang isang taon.","p":"Tama. Ang pagtanggi sa test ay puwedeng magpawala ng lisensya mo nang isang taon."},"ar":{"q":"في New Mexico، ماذا يمكن أن يحدث إذا رفضت اختبار الكحول عندما يطلبه منك شرطي؟","o":["يمكن أن تفقد رخصتك لمدة سنة واحدة","لا شيء، الاختبار باختيارك","تحصل على تحذير في المرة الأولى","تدفع غرامة صغيرة فقط"],"h1":"رفض الاختبار له عقوبة خاصة به.","h2":"في New Mexico، إذا رفضت اختبار الكحول في الدم عندما يطلبه منك شرطي، يمكن أن تفقد رخصة القيادة لمدة سنة واحدة.","p":"صحيح. رفض الاختبار يمكن أن يفقدك رخصتك لمدة سنة."},"ref":{"doc":"NM","page":29}},{"id":"nm-024","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, what is the top speed on rural interstate highways unless a sign says otherwise?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Open country interstates have the highest limit in the state.","h2":"In New Mexico, the speed limit on rural interstate highways is 75 mph unless a different limit is posted.","p":"Right. Rural interstates allow 75 mph."},"es":{"q":"En Nuevo México, ¿cuál es la velocidad máxima en las autopistas interestatales rurales si no hay un letrero que diga otra cosa?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Las interestatales en el campo tienen el límite más alto del estado.","h2":"En Nuevo México, el límite de velocidad en las autopistas interestatales rurales es de 75 mph, a menos que un letrero indique otro límite.","p":"Correcto. En las interestatales rurales se permiten 75 mph."},"zh":{"q":"在 New Mexico，如果没有标志另行规定，乡村州际公路的最高速度是多少？","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"乡村的州际公路有全州最高的限速。","h2":"在 New Mexico，除非标志写着不同的限速，乡村州际公路的限速是 75 mph。","p":"对。乡村州际公路可以开到 75 mph。"},"vi":{"q":"Ở New Mexico, tốc độ tối đa trên xa lộ liên bang ở vùng nông thôn là bao nhiêu nếu không có biển báo khác?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Xa lộ liên bang ở vùng quê có giới hạn cao nhất trong tiểu bang.","h2":"Ở New Mexico, giới hạn tốc độ trên xa lộ liên bang ở vùng nông thôn là 75 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Xa lộ liên bang ở nông thôn cho phép 75 mph."},"tl":{"q":"Sa New Mexico, ano ang pinakamataas na bilis sa mga rural interstate highway kung walang karatulang nagsasabi ng iba?","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"Ang mga interstate sa probinsya ang may pinakamataas na limit sa estado.","h2":"Sa New Mexico, ang speed limit sa mga rural interstate highway ay 75 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. Pinapayagan ang 75 mph sa mga rural interstate."},"ar":{"q":"في New Mexico، ما السرعة القصوى على الطرق السريعة بين الولايات في المناطق الريفية إذا لم تقل لافتة غير ذلك؟","o":["55 mph","60 mph","65 mph","75 mph"],"h1":"الطرق السريعة بين الولايات في الريف لها أعلى حد سرعة في الولاية.","h2":"في New Mexico، حد السرعة على الطرق السريعة بين الولايات في المناطق الريفية هو 75 mph إلا إذا كانت هناك لافتة بحد مختلف.","p":"صحيح. يُسمح بسرعة 75 mph على الطرق السريعة الريفية بين الولايات."},"ref":{"doc":"NM","page":12}},{"id":"nm-025","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, what is the speed limit in a posted school zone?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"It is lower than the limit on a normal city street.","h2":"In New Mexico, the speed limit in a posted school zone is 15 mph.","p":"Right. School zones are 15 mph."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una zona escolar señalizada?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Es más bajo que el límite en una calle normal de la ciudad.","h2":"En Nuevo México, el límite de velocidad en una zona escolar señalizada es de 15 mph.","p":"Correcto. En las zonas escolares el límite es 15 mph."},"zh":{"q":"在 New Mexico，有标志的学校区限速是多少？","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"它比普通城市街道的限速低。","h2":"在 New Mexico，有标志的学校区限速是 15 mph。","p":"对。学校区限速是 15 mph。"},"vi":{"q":"Ở New Mexico, giới hạn tốc độ trong khu vực trường học có biển báo là bao nhiêu?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Nó thấp hơn giới hạn trên một con đường bình thường trong thành phố.","h2":"Ở New Mexico, giới hạn tốc độ trong khu vực trường học có biển báo là 15 mph.","p":"Đúng. Khu vực trường học giới hạn 15 mph."},"tl":{"q":"Sa New Mexico, ano ang speed limit sa school zone na may karatula?","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"Mas mababa ito kaysa sa limit sa karaniwang kalye sa lungsod.","h2":"Sa New Mexico, ang speed limit sa school zone na may karatula ay 15 mph.","p":"Tama. 15 mph ang limit sa mga school zone."},"ar":{"q":"في New Mexico، ما حد السرعة في منطقة مدرسية عليها لافتة؟","o":["10 mph","15 mph","25 mph","30 mph"],"h1":"إنه أقل من حد السرعة في شارع عادي في المدينة.","h2":"في New Mexico، حد السرعة في منطقة مدرسية عليها لافتة هو 15 mph.","p":"صحيح. حد السرعة في المناطق المدرسية هو 15 mph."},"ref":{"doc":"NM","page":12}},{"id":"nm-026","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what is the minimum insurance for damage to other people's property in one crash?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"It is the smallest of the three required amounts.","h2":"In New Mexico, liability insurance must cover at least $10,000 for property damage, $25,000 for injury to one person, and $50,000 for two or more people in one crash.","p":"Right. Property damage coverage starts at $10,000."},"es":{"q":"En Nuevo México, ¿cuál es el seguro mínimo por daños a la propiedad de otras personas en un choque?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Es la más pequeña de las tres cantidades requeridas.","h2":"En Nuevo México, el seguro de responsabilidad debe cubrir al menos $10,000 por daños a la propiedad, $25,000 por lesiones a una persona y $50,000 por dos o más personas en un choque.","p":"Correcto. La cobertura por daños a la propiedad empieza en $10,000."},"zh":{"q":"在 New Mexico，一次车祸中对他人财产损失的最低保险金额是多少？","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"它是三个规定金额中最小的。","h2":"在 New Mexico，责任保险至少要赔付财产损失 $10,000、一人受伤 $25,000、一次车祸中两人或更多人受伤 $50,000。","p":"对。财产损失的保险从 $10,000 起。"},"vi":{"q":"Ở New Mexico, bảo hiểm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Đó là số nhỏ nhất trong ba số tiền bắt buộc.","h2":"Ở New Mexico, bảo hiểm trách nhiệm phải chi trả ít nhất $10,000 cho thiệt hại tài sản, $25,000 cho thương tích của một người, và $50,000 cho hai người trở lên trong một vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản bắt đầu từ $10,000."},"tl":{"q":"Sa New Mexico, ano ang pinakamababang insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"Ito ang pinakamaliit sa tatlong kinakailangang halaga.","h2":"Sa New Mexico, ang liability insurance ay dapat sumagot ng hindi bababa sa $10,000 para sa pinsala sa ari-arian, $25,000 para sa pinsala sa isang tao, at $50,000 para sa dalawa o higit pang tao sa isang banggaan.","p":"Tama. Nagsisimula sa $10,000 ang coverage para sa pinsala sa ari-arian."},"ar":{"q":"في New Mexico، ما الحد الأدنى للتأمين على الأضرار بممتلكات الآخرين في حادث واحد؟","o":["$10,000","$5,000","$25,000","$50,000"],"h1":"إنه أصغر المبالغ الثلاثة المطلوبة.","h2":"في New Mexico، يجب أن يغطي تأمين المسؤولية على الأقل $10,000 لأضرار الممتلكات، و$25,000 لإصابة شخص واحد، و$50,000 لشخصين أو أكثر في حادث واحد.","p":"صحيح. تبدأ تغطية أضرار الممتلكات من $10,000."},"ref":{"doc":"NM","page":35}},{"id":"nm-027","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long must you go without a traffic conviction before you apply for a provisional license?","o":["7 days","30 days","90 days","One year"],"h1":"It is about three months.","h2":"In New Mexico, you must have no traffic conviction in the 90 days before you apply for a provisional license.","p":"Right. You need 90 days with no traffic conviction."},"es":{"q":"En Nuevo México, ¿cuánto tiempo debe pasar sin una condena de tránsito antes de solicitar una licencia provisional?","o":["7 días","30 días","90 días","Un año"],"h1":"Son unos tres meses.","h2":"En Nuevo México, usted no debe tener ninguna condena de tránsito en los 90 días antes de solicitar una licencia provisional.","p":"Correcto. Necesita 90 días sin condenas de tránsito."},"zh":{"q":"在 New Mexico，申请临时驾照（provisional license）前，你必须多长时间没有交通定罪？","o":["7 天","30 天","90 天","一年"],"h1":"大约是三个月。","h2":"在 New Mexico，申请临时驾照前的 90 天内，你必须没有任何交通定罪。","p":"对。你需要 90 天没有交通定罪。"},"vi":{"q":"Ở New Mexico, bạn phải không bị kết tội vi phạm giao thông trong bao lâu trước khi xin bằng lái tạm thời (provisional license)?","o":["7 ngày","30 ngày","90 ngày","Một năm"],"h1":"Khoảng ba tháng.","h2":"Ở New Mexico, bạn không được có bất kỳ lần bị kết tội vi phạm giao thông nào trong 90 ngày trước khi xin bằng lái tạm thời.","p":"Đúng. Bạn cần 90 ngày không bị kết tội vi phạm giao thông."},"tl":{"q":"Sa New Mexico, gaano katagal ka dapat walang traffic conviction bago ka mag-apply ng provisional license?","o":["7 araw","30 araw","90 araw","Isang taon"],"h1":"Mga tatlong buwan ito.","h2":"Sa New Mexico, dapat wala kang traffic conviction sa loob ng 90 araw bago ka mag-apply ng provisional license.","p":"Tama. Kailangan mo ng 90 araw na walang traffic conviction."},"ar":{"q":"في New Mexico، كم من الوقت يجب أن تمضي بدون إدانة مرورية قبل أن تتقدّم بطلب رخصة مؤقتة (provisional license)؟","o":["7 أيام","30 يومًا","90 يومًا","سنة واحدة"],"h1":"إنها حوالي ثلاثة أشهر.","h2":"في New Mexico، يجب ألا تكون لديك أي إدانة مرورية خلال الـ 90 يومًا التي تسبق تقديم طلب الرخصة المؤقتة.","p":"صحيح. تحتاج إلى 90 يومًا بدون إدانة مرورية."},"ref":{"doc":"NM","page":2}},{"id":"nm-028","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, when may you renew your driver license?","o":["Only on the day it expires","Only in the month after it expires","From 90 days before until 30 days after it expires","Any time up to one year after it expires"],"h1":"You can renew a few months early, and a short time late.","h2":"In New Mexico you may renew your driver license from 90 days before it expires until 30 days after it expires.","p":"Right. Renew from 90 days before to 30 days after the expiration date."},"es":{"q":"En Nuevo México, ¿cuándo puede renovar su licencia de conducir?","o":["Solo el día en que vence","Solo en el mes después de que vence","Desde 90 días antes hasta 30 días después de que vence","En cualquier momento hasta un año después de que vence"],"h1":"Puede renovar unos meses antes y un poco tarde.","h2":"En Nuevo México usted puede renovar su licencia de conducir desde 90 días antes de que venza hasta 30 días después de que venza.","p":"Correcto. Se renueva desde 90 días antes hasta 30 días después del vencimiento."},"zh":{"q":"在 New Mexico，你什么时候可以更新（续期）驾照？","o":["只能在驾照到期的那一天","只能在驾照到期后的那个月","从到期前 90 天到到期后 30 天","到期后一年内的任何时间"],"h1":"你可以提前几个月更新，也可以晚一点点更新。","h2":"在 New Mexico，你可以从驾照到期前 90 天到到期后 30 天之间更新驾照。","p":"对。从到期日前 90 天到到期日后 30 天都可以更新。"},"vi":{"q":"Ở New Mexico, khi nào bạn có thể gia hạn bằng lái xe?","o":["Chỉ vào ngày bằng lái hết hạn","Chỉ trong tháng sau khi bằng lái hết hạn","Từ 90 ngày trước cho đến 30 ngày sau khi bằng lái hết hạn","Bất cứ lúc nào cho đến một năm sau khi bằng lái hết hạn"],"h1":"Bạn có thể gia hạn sớm vài tháng, và trễ một chút.","h2":"Ở New Mexico, bạn có thể gia hạn bằng lái xe từ 90 ngày trước khi hết hạn cho đến 30 ngày sau khi hết hạn.","p":"Đúng. Gia hạn từ 90 ngày trước đến 30 ngày sau ngày hết hạn."},"tl":{"q":"Sa New Mexico, kailan mo puwedeng i-renew ang iyong driver license?","o":["Sa mismong araw lang na mag-e-expire ito","Sa buwan lang pagkatapos itong mag-expire","Mula 90 araw bago hanggang 30 araw pagkatapos itong mag-expire","Kahit kailan hanggang isang taon pagkatapos itong mag-expire"],"h1":"Puwede kang mag-renew nang ilang buwan na mas maaga, at nang medyo huli.","h2":"Sa New Mexico, puwede mong i-renew ang iyong driver license mula 90 araw bago ito mag-expire hanggang 30 araw pagkatapos itong mag-expire.","p":"Tama. Mag-renew mula 90 araw bago hanggang 30 araw pagkatapos ng expiration date."},"ar":{"q":"في New Mexico، متى يمكنك تجديد رخصة القيادة؟","o":["فقط في يوم انتهائها","فقط في الشهر الذي يلي انتهاءها","من 90 يومًا قبل انتهائها حتى 30 يومًا بعد انتهائها","في أي وقت حتى سنة واحدة بعد انتهائها"],"h1":"يمكنك التجديد قبل الموعد ببضعة أشهر، وبعده بوقت قصير.","h2":"في New Mexico يمكنك تجديد رخصة القيادة من 90 يومًا قبل انتهائها حتى 30 يومًا بعد انتهائها.","p":"صحيح. جدّد الرخصة من 90 يومًا قبل تاريخ الانتهاء حتى 30 يومًا بعده."},"ref":{"doc":"NM","page":2}},{"id":"nm-029","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what vision do you need to pass the vision test for a driver license?","o":["At least 20/40 in at least one eye, with or without glasses","At least 20/20 in both eyes, without glasses","At least 20/100 in both eyes","At least 20/40 in both eyes, without glasses"],"h1":"You may wear glasses or contacts, and one eye can be enough.","h2":"In New Mexico you need at least 20/40 vision in at least one eye, with or without glasses or contact lenses, to get a driver license.","p":"Right. You need 20/40 in at least one eye, and glasses are allowed."},"es":{"q":"En Nuevo México, ¿qué visión necesita para pasar el examen de la vista para una licencia de conducir?","o":["Por lo menos 20/40 en al menos un ojo, con o sin anteojos","Por lo menos 20/20 en ambos ojos, sin anteojos","Por lo menos 20/100 en ambos ojos","Por lo menos 20/40 en ambos ojos, sin anteojos"],"h1":"Puede usar anteojos o lentes de contacto, y un ojo puede ser suficiente.","h2":"En Nuevo México usted necesita una visión de por lo menos 20/40 en al menos un ojo, con o sin anteojos o lentes de contacto, para obtener una licencia de conducir.","p":"Correcto. Necesita 20/40 en al menos un ojo, y se permiten anteojos."},"zh":{"q":"在 New Mexico，要通过驾照的视力测试，你需要什么样的视力？","o":["至少一只眼睛达到 20/40，戴不戴眼镜都可以","两只眼睛都达到 20/20，不戴眼镜","两只眼睛都至少达到 20/100","两只眼睛都达到 20/40，不戴眼镜"],"h1":"你可以戴眼镜或隐形眼镜，一只眼睛可能就够了。","h2":"在 New Mexico，你至少一只眼睛的视力要达到 20/40，戴不戴眼镜或隐形眼镜都可以，才能拿到驾照。","p":"对。至少一只眼睛要达到 20/40，可以戴眼镜。"},"vi":{"q":"Ở New Mexico, bạn cần thị lực như thế nào để qua bài kiểm tra mắt khi lấy bằng lái xe?","o":["Ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính","Ít nhất 20/20 ở cả hai mắt, không đeo kính","Ít nhất 20/100 ở cả hai mắt","Ít nhất 20/40 ở cả hai mắt, không đeo kính"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng, và một mắt có thể là đủ.","h2":"Ở New Mexico, bạn cần thị lực ít nhất 20/40 ở ít nhất một mắt, có hoặc không đeo kính hay kính áp tròng, để lấy bằng lái xe.","p":"Đúng. Bạn cần 20/40 ở ít nhất một mắt, và được phép đeo kính."},"tl":{"q":"Sa New Mexico, anong paningin ang kailangan mo para pumasa sa vision test para sa driver license?","o":["Hindi bababa sa 20/40 sa kahit isang mata, may salamin man o wala","Hindi bababa sa 20/20 sa dalawang mata, nang walang salamin","Hindi bababa sa 20/100 sa dalawang mata","Hindi bababa sa 20/40 sa dalawang mata, nang walang salamin"],"h1":"Puwede kang magsuot ng salamin o contact lens, at puwedeng sapat na ang isang mata.","h2":"Sa New Mexico, kailangan mo ng paningin na hindi bababa sa 20/40 sa kahit isang mata, may salamin o contact lens man o wala, para makakuha ng driver license.","p":"Tama. Kailangan mo ng 20/40 sa kahit isang mata, at puwede ang salamin."},"ar":{"q":"في New Mexico، ما قوة النظر التي تحتاجها لتنجح في فحص النظر لرخصة القيادة؟","o":["20/40 على الأقل في عين واحدة على الأقل، بنظارة أو بدونها","20/20 على الأقل في العينين، بدون نظارة","20/100 على الأقل في العينين","20/40 على الأقل في العينين، بدون نظارة"],"h1":"يمكنك لبس النظارة أو العدسات اللاصقة، وقد تكفي عين واحدة.","h2":"في New Mexico تحتاج إلى نظر 20/40 على الأقل في عين واحدة على الأقل، بنظارة أو عدسات لاصقة أو بدونها، لتحصل على رخصة القيادة.","p":"صحيح. تحتاج إلى 20/40 في عين واحدة على الأقل، والنظارة مسموحة."},"ref":{"doc":"NM","page":28}},{"id":"nm-030","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, how close to a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is the largest of these distances.","h2":"In New Mexico you may not park within 50 feet of a railroad crossing.","p":"Right. Stay at least 50 feet away from a railroad crossing when you park."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Nuevo México usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies de un cruce de ferrocarril al estacionarse."},"zh":{"q":"在 New Mexico，你最近可以在离铁路道口多远的地方停车？","o":["不能近于 10 英尺","不能近于 20 英尺","不能近于 30 英尺","不能近于 50 英尺"],"h1":"是这几个距离中最大的那个。","h2":"在 New Mexico，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时，要离铁路道口至少 50 英尺。"},"vi":{"q":"Ở New Mexico, bạn được đậu xe gần đường ray xe lửa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 30 feet","Không gần hơn 50 feet"],"h1":"Đó là khoảng cách lớn nhất trong các khoảng cách này.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 50 feet từ chỗ băng qua đường ray xe lửa.","p":"Đúng. Khi đậu xe, hãy cách chỗ băng qua đường ray xe lửa ít nhất 50 feet."},"tl":{"q":"Sa New Mexico, gaano kalapit sa railroad crossing ka puwedeng mag-park?","o":["Hindi mas malapit sa 10 talampakan","Hindi mas malapit sa 20 talampakan","Hindi mas malapit sa 30 talampakan","Hindi mas malapit sa 50 talampakan"],"h1":"Ito ang pinakamalayo sa mga distansyang ito.","h2":"Sa New Mexico, hindi ka puwedeng mag-park sa loob ng 50 talampakan mula sa railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 talampakan mula sa railroad crossing kapag nagpa-park ka."},"ar":{"q":"في New Mexico، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من معبر سكة الحديد؟","o":["ليس أقرب من 10 أقدام (feet)","ليس أقرب من 20 قدمًا (feet)","ليس أقرب من 30 قدمًا (feet)","ليس أقرب من 50 قدمًا (feet)"],"h1":"إنها أكبر مسافة بين هذه المسافات.","h2":"في New Mexico لا يجوز لك أن تركن سيارتك على بعد أقل من 50 قدمًا (feet) من معبر سكة الحديد.","p":"صحيح. ابقَ على بعد 50 قدمًا (feet) على الأقل من معبر سكة الحديد عندما تركن سيارتك."},"ref":{"doc":"NM","page":13}},{"id":"nm-031","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you are driving behind another car at night. Within what distance should you use your low beams?","o":["100 feet","200 feet","1,000 feet","1 mile"],"h1":"It is about the length of 13 cars.","h2":"In New Mexico you should use your low beams when you are within 200 feet of a vehicle you are following.","p":"Right. Switch to low beams within 200 feet of the car ahead."},"es":{"q":"En Nuevo México, usted maneja de noche detrás de otro carro. ¿A qué distancia debe usar las luces bajas?","o":["100 pies","200 pies","1,000 pies","1 milla"],"h1":"Es más o menos el largo de 13 carros.","h2":"En Nuevo México usted debe usar las luces bajas cuando está a menos de 200 pies del vehículo que va delante.","p":"Correcto. Cambie a luces bajas a menos de 200 pies del carro de adelante."},"zh":{"q":"在 New Mexico，你晚上开在另一辆车后面。在多远的距离内你应该用近光灯？","o":["100 英尺","200 英尺","1,000 英尺","1 英里"],"h1":"大约是 13 辆车的长度。","h2":"在 New Mexico，当你离前面跟着的车在 200 英尺以内时，你应该用近光灯。","p":"对。离前车 200 英尺以内时，换成近光灯。"},"vi":{"q":"Ở New Mexico, bạn đang lái xe phía sau một xe khác vào ban đêm. Trong khoảng cách bao xa thì bạn nên dùng đèn cốt (đèn chiếu gần)?","o":["100 feet","200 feet","1,000 feet","1 dặm"],"h1":"Đó là khoảng chiều dài của 13 chiếc xe.","h2":"Ở New Mexico, bạn nên dùng đèn cốt (đèn chiếu gần) khi bạn ở trong vòng 200 feet sau chiếc xe bạn đang đi theo.","p":"Đúng. Chuyển sang đèn cốt khi bạn ở trong vòng 200 feet sau xe phía trước."},"tl":{"q":"Sa New Mexico, nagmamaneho ka sa likod ng ibang kotse sa gabi. Sa loob ng anong distansya ka dapat gumamit ng low beams?","o":["100 talampakan","200 talampakan","1,000 talampakan","1 milya"],"h1":"Ito ay mga kasinghaba ng 13 kotse.","h2":"Sa New Mexico, dapat kang gumamit ng low beams kapag nasa loob ka ng 200 talampakan mula sa sasakyang sinusundan mo.","p":"Tama. Lumipat sa low beams kapag nasa loob ka ng 200 talampakan mula sa kotse sa unahan."},"ar":{"q":"في New Mexico، أنت تقود خلف سيارة أخرى في الليل. ضمن أي مسافة يجب أن تستعمل الأضواء المنخفضة؟","o":["100 قدم (feet)","200 قدم (feet)","1,000 قدم (feet)","1 ميل"],"h1":"إنها تقريبًا طول 13 سيارة.","h2":"في New Mexico يجب أن تستعمل الأضواء المنخفضة عندما تكون على بعد أقل من 200 قدم (feet) من السيارة التي تسير خلفها.","p":"صحيح. انتقل إلى الأضواء المنخفضة عندما تكون على بعد أقل من 200 قدم (feet) من السيارة التي أمامك."},"ref":{"doc":"NM","page":18}},{"id":"nm-032","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, how long is a driver license valid?","o":["1 or 2 years","2 or 3 years","4 or 8 years","10 or 12 years"],"h1":"There are two choices, and one is twice as long as the other.","h2":"In New Mexico a driver license is valid for either 4 years or 8 years.","p":"Right. A New Mexico license lasts 4 or 8 years."},"es":{"q":"En Nuevo México, ¿por cuánto tiempo es válida una licencia de conducir?","o":["1 o 2 años","2 o 3 años","4 u 8 años","10 o 12 años"],"h1":"Hay dos opciones, y una dura el doble que la otra.","h2":"En Nuevo México una licencia de conducir es válida por 4 años o por 8 años.","p":"Correcto. Una licencia de Nuevo México dura 4 u 8 años."},"zh":{"q":"在 New Mexico，驾照的有效期是多久？","o":["1 年或 2 年","2 年或 3 年","4 年或 8 年","10 年或 12 年"],"h1":"有两种选择，一种是另一种的两倍长。","h2":"在 New Mexico，驾照的有效期是 4 年或 8 年。","p":"对。New Mexico 的驾照有效 4 年或 8 年。"},"vi":{"q":"Ở New Mexico, bằng lái xe có hiệu lực trong bao lâu?","o":["1 hoặc 2 năm","2 hoặc 3 năm","4 hoặc 8 năm","10 hoặc 12 năm"],"h1":"Có hai lựa chọn, và một lựa chọn dài gấp đôi lựa chọn kia.","h2":"Ở New Mexico, bằng lái xe có hiệu lực 4 năm hoặc 8 năm.","p":"Đúng. Bằng lái ở New Mexico có hiệu lực 4 hoặc 8 năm."},"tl":{"q":"Sa New Mexico, gaano katagal valid ang driver license?","o":["1 o 2 taon","2 o 3 taon","4 o 8 taon","10 o 12 taon"],"h1":"May dalawang pagpipilian, at ang isa ay doble ang haba kaysa sa isa.","h2":"Sa New Mexico, ang driver license ay valid nang 4 na taon o 8 taon.","p":"Tama. Ang license sa New Mexico ay tumatagal nang 4 o 8 taon."},"ar":{"q":"في New Mexico، ما مدة صلاحية رخصة القيادة؟","o":["1 أو 2 سنة","2 أو 3 سنوات","4 أو 8 سنوات","10 أو 12 سنة"],"h1":"هناك خياران، وأحدهما ضعف الآخر في الطول.","h2":"في New Mexico تكون رخصة القيادة صالحة لمدة 4 سنوات أو 8 سنوات.","p":"صحيح. رخصة New Mexico صالحة 4 أو 8 سنوات."},"ref":{"doc":"NM","page":2}},{"id":"nm-033","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, which of these can stop a provisional driver from getting a full (unrestricted) license?","o":["An alcohol or drug offense during the provisional period","Driving with a parent in the car","Carrying a brother or sister as a passenger","Taking a driver education course"],"h1":"Think about what the law treats as a serious offense for young drivers.","h2":"In New Mexico you cannot get an unrestricted license if you were found guilty of, or have a pending case for, an alcohol or drug offense during the provisional period.","p":"Right. An alcohol or drug offense while on a provisional license blocks the full license."},"es":{"q":"En Nuevo México, ¿cuál de estas cosas puede impedir que un conductor con licencia provisional obtenga una licencia completa (sin restricciones)?","o":["Un delito de alcohol o drogas durante el período provisional","Manejar con un padre en el auto","Llevar a un hermano o hermana como pasajero","Tomar un curso de educación vial"],"h1":"Piense en lo que la ley considera una falta grave para los conductores jóvenes.","h2":"En Nuevo México usted no puede obtener una licencia sin restricciones si fue declarado culpable, o tiene un caso pendiente, de un delito de alcohol o drogas durante el período provisional.","p":"Correcto. Un delito de alcohol o drogas con licencia provisional impide la licencia completa."},"zh":{"q":"在 New Mexico，下面哪一项会让持临时驾照（provisional license）的司机拿不到正式（无限制）驾照？","o":["在临时驾照期间有酒精或毒品违法记录","车里有父母陪着开车","载兄弟姐妹当乘客","上驾驶教育课程"],"h1":"想一想，法律认为哪种行为对年轻司机来说是严重违法。","h2":"在 New Mexico，如果你在临时驾照期间因酒精或毒品违法被判有罪，或有这类案件还没有结案，你就不能拿到无限制驾照。","p":"对。持临时驾照期间的酒精或毒品违法会让你拿不到正式驾照。"},"vi":{"q":"Ở New Mexico, điều nào sau đây có thể làm người lái có bằng tạm thời (provisional license) không được cấp bằng đầy đủ (không hạn chế)?","o":["Vi phạm liên quan đến rượu hoặc ma túy trong thời gian có bằng tạm thời","Lái xe có cha mẹ ngồi trong xe","Chở anh chị em làm hành khách","Học một khóa giáo dục lái xe"],"h1":"Hãy nghĩ xem luật coi điều gì là vi phạm nghiêm trọng đối với người lái trẻ.","h2":"Ở New Mexico, bạn không thể được cấp bằng không hạn chế nếu bạn bị kết tội, hoặc đang có vụ việc chưa xử xong, về vi phạm liên quan đến rượu hoặc ma túy trong thời gian có bằng tạm thời.","p":"Đúng. Vi phạm về rượu hoặc ma túy khi có bằng tạm thời sẽ ngăn bạn được cấp bằng đầy đủ."},"tl":{"q":"Sa New Mexico, alin sa mga ito ang puwedeng pumigil sa isang provisional driver na makakuha ng buong (unrestricted) license?","o":["Isang paglabag na may kinalaman sa alak o droga habang nasa provisional period","Pagmamaneho na may kasamang magulang sa kotse","Pagsasakay ng kapatid bilang pasahero","Pagkuha ng kurso sa driver education"],"h1":"Isipin kung ano ang itinuturing ng batas na mabigat na paglabag para sa mga batang driver.","h2":"Sa New Mexico, hindi ka makakakuha ng unrestricted license kung napatunayang nagkasala ka, o may nakabinbing kaso ka, sa isang paglabag na may kinalaman sa alak o droga habang nasa provisional period.","p":"Tama. Ang paglabag sa alak o droga habang may provisional license ay pumipigil sa buong license."},"ar":{"q":"في New Mexico، أيّ مما يلي يمكن أن يمنع سائقًا يحمل رخصة مؤقتة (provisional license) من الحصول على رخصة كاملة (بلا قيود)؟","o":["مخالفة تتعلق بالكحول أو المخدرات خلال فترة الرخصة المؤقتة","القيادة مع أحد الوالدين في السيارة","نقل أخ أو أخت كراكب","حضور دورة لتعليم القيادة"],"h1":"فكّر فيما يعدّه القانون مخالفة خطيرة للسائقين الشباب.","h2":"في New Mexico لا يمكنك الحصول على رخصة بلا قيود إذا أُدنت، أو كانت لديك قضية لم يُحكم فيها بعد، بمخالفة تتعلق بالكحول أو المخدرات خلال فترة الرخصة المؤقتة.","p":"صحيح. مخالفة الكحول أو المخدرات خلال الرخصة المؤقتة تمنع الحصول على الرخصة الكاملة."},"ref":{"doc":"NM","page":2}},{"id":"nm-034","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, how close to a stop sign, yield sign or traffic signal may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"It is about the length of two cars.","h2":"In New Mexico you may not park within 30 feet of a stop sign, yield sign or traffic signal.","p":"Right. Stay at least 30 feet away from a stop sign, yield sign or traffic signal."},"es":{"q":"En Nuevo México, ¿qué tan cerca de una señal de alto, una señal de ceda el paso o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Es más o menos el largo de dos autos.","h2":"En Nuevo México usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso o un semáforo.","p":"Correcto. Manténgase al menos a 30 pies de una señal de alto, de ceda el paso o de un semáforo."},"zh":{"q":"在 New Mexico，你可以把车停在离停车标志、让行标志或交通信号灯多近的地方？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 30 英尺"],"h1":"大约是两辆车的长度。","h2":"在 New Mexico，你不可以停在离停车标志、让行标志或交通信号灯 30 英尺以内的地方。","p":"对。离停车标志、让行标志或交通信号灯至少 30 英尺。"},"vi":{"q":"Ở New Mexico, bạn được đậu xe gần biển báo dừng, biển báo nhường đường hoặc đèn giao thông đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Khoảng bằng chiều dài của hai chiếc xe.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 30 feet tính từ biển báo dừng, biển báo nhường đường hoặc đèn giao thông.","p":"Đúng. Hãy đậu cách biển báo dừng, biển báo nhường đường hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa New Mexico, gaano kalapit sa stop sign, yield sign o traffic signal ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Ito ay mga kasinghaba ng dalawang kotse.","h2":"Sa New Mexico, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, yield sign o traffic signal.","p":"Tama. Lumayo nang hindi bababa sa 30 feet mula sa stop sign, yield sign o traffic signal."},"ar":{"q":"في New Mexico، إلى أي مدى يمكنك أن تركن قريبًا من لافتة توقف أو لافتة إفساح الطريق أو إشارة مرور؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"إنها تقريبًا طول سيارتين.","h2":"في New Mexico يجب ألّا تركن على بُعد أقل من 30 feet من لافتة توقف أو لافتة إفساح الطريق أو إشارة مرور.","p":"صحيح. ابقَ على بُعد 30 feet على الأقل من لافتة التوقف أو لافتة إفساح الطريق أو إشارة المرور."},"ref":{"doc":"NM","page":13}},{"id":"nm-035","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 25 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is a quarter of 100 feet.","h2":"In New Mexico you may not park within 25 feet of a crosswalk at an intersection.","p":"Right. Park at least 25 feet from a crosswalk at an intersection."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Es la cuarta parte de 100 pies.","h2":"En Nuevo México usted no puede estacionarse a menos de 25 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese al menos a 25 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 New Mexico，你可以把车停在离路口人行横道多近的地方？","o":["不能近于 10 英尺","不能近于 25 英尺","不能近于 50 英尺","不能近于 100 英尺"],"h1":"它是 100 英尺的四分之一。","h2":"在 New Mexico，你不可以停在离路口人行横道 25 英尺以内的地方。","p":"对。停车时离路口人行横道至少 25 英尺。"},"vi":{"q":"Ở New Mexico, bạn được đậu xe gần vạch qua đường ở ngã tư đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet","Không gần hơn 100 feet"],"h1":"Nó bằng một phần tư của 100 feet.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 25 feet tính từ vạch qua đường ở ngã tư.","p":"Đúng. Hãy đậu cách vạch qua đường ở ngã tư ít nhất 25 feet."},"tl":{"q":"Sa New Mexico, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 25 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 100 feet"],"h1":"Ito ay isang-kapat ng 100 feet.","h2":"Sa New Mexico, hindi ka puwedeng pumarada sa loob ng 25 feet mula sa crosswalk sa intersection.","p":"Tama. Pumarada nang hindi bababa sa 25 feet mula sa crosswalk sa intersection."},"ar":{"q":"في New Mexico، إلى أي مدى يمكنك أن تركن قريبًا من ممر المشاة عند تقاطع؟","o":["ليس أقرب من 10 feet","ليس أقرب من 25 feet","ليس أقرب من 50 feet","ليس أقرب من 100 feet"],"h1":"إنها ربع 100 feet.","h2":"في New Mexico يجب ألّا تركن على بُعد أقل من 25 feet من ممر المشاة عند تقاطع.","p":"صحيح. اركن على بُعد 25 feet على الأقل من ممر المشاة عند التقاطع."},"ref":{"doc":"NM","page":13}},{"id":"nm-036","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 8 feet","No closer than 15 feet","No closer than 40 feet"],"h1":"Firefighters need room to reach the hydrant. The answer is between 10 and 20 feet.","h2":"In New Mexico you may not park within 15 feet of a fire hydrant.","p":"Right. Keep at least 15 feet from a fire hydrant."},"es":{"q":"En Nuevo México, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 8 pies","No más cerca de 15 pies","No más cerca de 40 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante. La respuesta está entre 10 y 20 pies.","h2":"En Nuevo México usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Manténgase al menos a 15 pies de un hidrante."},"zh":{"q":"在 New Mexico，你可以把车停在离消防栓多近的地方？","o":["不能近于 5 英尺","不能近于 8 英尺","不能近于 15 英尺","不能近于 40 英尺"],"h1":"消防员需要空间才能用到消防栓。答案在 10 到 20 英尺之间。","h2":"在 New Mexico，你不可以停在离消防栓 15 英尺以内的地方。","p":"对。离消防栓至少 15 英尺。"},"vi":{"q":"Ở New Mexico, bạn được đậu xe gần trụ cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 8 feet","Không gần hơn 15 feet","Không gần hơn 40 feet"],"h1":"Lính cứu hỏa cần chỗ để tới được trụ cứu hỏa. Câu trả lời nằm giữa 10 và 20 feet.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 15 feet tính từ trụ cứu hỏa.","p":"Đúng. Hãy cách trụ cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa New Mexico, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 8 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 40 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant. Ang sagot ay nasa pagitan ng 10 at 20 feet.","h2":"Sa New Mexico, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في New Mexico، إلى أي مدى يمكنك أن تركن قريبًا من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 feet","ليس أقرب من 8 feet","ليس أقرب من 15 feet","ليس أقرب من 40 feet"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الصنبور. الجواب بين 10 و20 feet.","h2":"في New Mexico يجب ألّا تركن على بُعد أقل من 15 feet من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"NM","page":13}},{"id":"nm-037","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, you park next to a curb. How far from the curb may your car be?","o":["No more than 18 inches","No more than 3 feet","No more than 4 feet","Any distance, if your lights are on"],"h1":"It is less than two feet.","h2":"In New Mexico you may not park more than 18 inches from the curb.","p":"Right. Park no more than 18 inches from the curb."},"es":{"q":"En Nuevo México, usted se estaciona junto a la acera. ¿A qué distancia de la acera puede quedar su auto?","o":["A no más de 18 pulgadas","A no más de 3 pies","A no más de 4 pies","A cualquier distancia, si tiene las luces encendidas"],"h1":"Es menos de dos pies.","h2":"En Nuevo México usted no puede estacionarse a más de 18 pulgadas de la acera.","p":"Correcto. Estaciónese a no más de 18 pulgadas de la acera."},"zh":{"q":"在 New Mexico，你把车停在路缘旁边。车离路缘最多可以多远？","o":["不超过 18 英寸","不超过 3 英尺","不超过 4 英尺","多远都可以，只要开着车灯"],"h1":"不到两英尺。","h2":"在 New Mexico，停车时车离路缘不可以超过 18 英寸。","p":"对。停车时离路缘不超过 18 英寸。"},"vi":{"q":"Ở New Mexico, bạn đậu xe cạnh lề đường. Xe của bạn được cách lề đường bao xa?","o":["Không quá 18 inches","Không quá 3 feet","Không quá 4 feet","Bao xa cũng được, nếu bạn bật đèn"],"h1":"Nó ít hơn hai feet.","h2":"Ở New Mexico, bạn không được đậu xe cách lề đường quá 18 inches.","p":"Đúng. Hãy đậu cách lề đường không quá 18 inches."},"tl":{"q":"Sa New Mexico, pumarada ka sa tabi ng curb. Gaano kalayo sa curb puwede ang kotse mo?","o":["Hindi hihigit sa 18 inches","Hindi hihigit sa 3 feet","Hindi hihigit sa 4 feet","Kahit gaano kalayo, kung nakabukas ang ilaw mo"],"h1":"Ito ay mas maikli sa dalawang feet.","h2":"Sa New Mexico, hindi ka puwedeng pumarada nang higit sa 18 inches mula sa curb.","p":"Tama. Pumarada nang hindi hihigit sa 18 inches mula sa curb."},"ar":{"q":"في New Mexico، تركن بجانب حافة الرصيف. كم يمكن أن تبعد سيارتك عن حافة الرصيف؟","o":["ليس أكثر من 18 inches","ليس أكثر من 3 feet","ليس أكثر من 4 feet","أي مسافة، إذا كانت أضواؤك مُشعلة"],"h1":"إنها أقل من قدمين.","h2":"في New Mexico يجب ألّا تركن على بُعد أكثر من 18 inches من حافة الرصيف.","p":"صحيح. اركن على بُعد لا يزيد على 18 inches من حافة الرصيف."},"ref":{"doc":"NM","page":13}},{"id":"nm-038","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you want to park on the same side of the street as a fire station driveway. How close to that driveway may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 75 feet","No closer than 20 feet"],"h1":"On the same side of the street the distance is shorter than on the other side.","h2":"In New Mexico you may not park within 20 feet of a fire station driveway on the same side of the street.","p":"Right. On the same side, stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nuevo México, usted quiere estacionarse en el mismo lado de la calle que la entrada de una estación de bomberos. ¿Qué tan cerca de esa entrada puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 75 pies","No más cerca de 20 pies"],"h1":"En el mismo lado de la calle la distancia es más corta que en el otro lado.","h2":"En Nuevo México usted no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos en el mismo lado de la calle.","p":"Correcto. En el mismo lado, manténgase al menos a 20 pies de la entrada de una estación de bomberos."},"zh":{"q":"在 New Mexico，你想在消防站车道同一侧的街边停车。你可以停在离那个车道多近的地方？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 75 英尺","不能近于 20 英尺"],"h1":"在街道同一侧，距离比在对面一侧短。","h2":"在 New Mexico，在街道同一侧，你不可以停在离消防站车道 20 英尺以内的地方。","p":"对。在同一侧，离消防站车道至少 20 英尺。"},"vi":{"q":"Ở New Mexico, bạn muốn đậu xe cùng bên đường với lối ra vào của trạm cứu hỏa. Bạn được đậu gần lối ra vào đó đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 75 feet","Không gần hơn 20 feet"],"h1":"Ở cùng bên đường, khoảng cách ngắn hơn so với bên kia đường.","h2":"Ở New Mexico, bạn không được đậu xe trong vòng 20 feet tính từ lối ra vào của trạm cứu hỏa khi ở cùng bên đường.","p":"Đúng. Ở cùng bên đường, hãy cách lối ra vào của trạm cứu hỏa ít nhất 20 feet."},"tl":{"q":"Sa New Mexico, gusto mong pumarada sa parehong panig ng kalye kung nasaan ang driveway ng fire station. Gaano kalapit sa driveway na iyon ka puwedeng pumarada?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 75 feet","Hindi lalapit sa 20 feet"],"h1":"Sa parehong panig ng kalye, mas maikli ang layo kaysa sa kabilang panig.","h2":"Sa New Mexico, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa driveway ng fire station sa parehong panig ng kalye.","p":"Tama. Sa parehong panig, lumayo nang hindi bababa sa 20 feet mula sa driveway ng fire station."},"ar":{"q":"في New Mexico، تريد أن تركن على نفس جانب الشارع الذي فيه مدخل محطة الإطفاء. إلى أي مدى يمكنك أن تركن قريبًا من ذلك المدخل؟","o":["ليس أقرب من 5 feet","ليس أقرب من 10 feet","ليس أقرب من 75 feet","ليس أقرب من 20 feet"],"h1":"على نفس جانب الشارع تكون المسافة أقصر منها على الجانب الآخر.","h2":"في New Mexico يجب ألّا تركن على بُعد أقل من 20 feet من مدخل محطة الإطفاء على نفس جانب الشارع.","p":"صحيح. على نفس الجانب، ابقَ على بُعد 20 feet على الأقل من مدخل محطة الإطفاء."},"ref":{"doc":"NM","page":13}},{"id":"nm-039","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, what does a curb painted red mean?","o":["Short stops only","A fire zone: no parking or standing","Parking for people with disabilities only","A loading zone"],"h1":"Red is the color for fire and danger.","h2":"In New Mexico a red curb marks a fire zone where you may not park or stand.","p":"Right. A red curb means a fire zone with no parking or standing."},"es":{"q":"En Nuevo México, ¿qué significa una acera pintada de rojo?","o":["Solo paradas cortas","Una zona de incendios: no se puede estacionar ni detenerse","Estacionamiento solo para personas con discapacidad","Una zona de carga"],"h1":"El rojo es el color del fuego y del peligro.","h2":"En Nuevo México una acera roja marca una zona de incendios donde no se puede estacionar ni detenerse.","p":"Correcto. Una acera roja indica una zona de incendios donde no se puede estacionar ni detenerse."},"zh":{"q":"在 New Mexico，漆成红色的路缘是什么意思？","o":["只能短暂停车","消防区：不能停车，也不能临时停留","只供残障人士停车","装卸货区"],"h1":"红色是代表火和危险的颜色。","h2":"在 New Mexico，红色路缘表示消防区，你不可以在那里停车或临时停留。","p":"对。红色路缘表示消防区，不能停车或临时停留。"},"vi":{"q":"Ở New Mexico, lề đường sơn màu đỏ có nghĩa là gì?","o":["Chỉ được dừng ngắn","Khu vực phòng cháy: không được đậu xe hoặc dừng xe","Chỉ dành cho người khuyết tật đậu xe","Khu vực bốc dỡ hàng"],"h1":"Màu đỏ là màu của lửa và nguy hiểm.","h2":"Ở New Mexico, lề đường màu đỏ đánh dấu khu vực phòng cháy, nơi bạn không được đậu xe hoặc dừng xe.","p":"Đúng. Lề đường màu đỏ là khu vực phòng cháy, không được đậu hoặc dừng xe."},"tl":{"q":"Sa New Mexico, ano ang ibig sabihin ng curb na pinintahan ng pula?","o":["Maikling paghinto lang","Fire zone: bawal pumarada o tumigil","Paradahan para lang sa mga taong may kapansanan","Loading zone"],"h1":"Ang pula ay kulay ng apoy at panganib.","h2":"Sa New Mexico, ang pulang curb ay nagmamarka ng fire zone kung saan hindi ka puwedeng pumarada o tumigil.","p":"Tama. Ang pulang curb ay fire zone na bawal pumarada o tumigil."},"ar":{"q":"في New Mexico، ماذا يعني رصيف مطليّ باللون الأحمر؟","o":["توقفات قصيرة فقط","منطقة إطفاء: ممنوع الركن أو الوقوف","ركن للأشخاص ذوي الإعاقة فقط","منطقة تحميل وتنزيل"],"h1":"الأحمر هو لون النار والخطر.","h2":"في New Mexico يدلّ الرصيف الأحمر على منطقة إطفاء يجب ألّا تركن أو تقف فيها.","p":"صحيح. الرصيف الأحمر يعني منطقة إطفاء ممنوع فيها الركن أو الوقوف."},"ref":{"doc":"NM","page":14}},{"id":"nm-040","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, what is the speed limit in a business or residential area when no sign says otherwise?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"It is twice the school zone limit.","h2":"In New Mexico the speed limit in business and residential areas is 30 mph unless a sign shows a different limit.","p":"Right. Business and residential areas are 30 mph unless posted otherwise."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una zona comercial o residencial cuando ninguna señal indica otro?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"Es el doble del límite en una zona escolar.","h2":"En Nuevo México el límite de velocidad en zonas comerciales y residenciales es de 30 mph, a menos que una señal indique otro límite.","p":"Correcto. Las zonas comerciales y residenciales son de 30 mph si no hay otra señal."},"zh":{"q":"在 New Mexico，如果没有标志另作规定，商业区或住宅区的限速是多少？","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"它是学校区限速的两倍。","h2":"在 New Mexico，商业区和住宅区的限速是 30 mph，除非标志显示别的限速。","p":"对。商业区和住宅区限速 30 mph，除非另有标志。"},"vi":{"q":"Ở New Mexico, giới hạn tốc độ trong khu thương mại hoặc khu dân cư là bao nhiêu khi không có biển báo nói khác?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"Nó gấp đôi giới hạn tốc độ ở khu vực trường học.","h2":"Ở New Mexico, giới hạn tốc độ trong khu thương mại và khu dân cư là 30 mph, trừ khi biển báo cho thấy giới hạn khác.","p":"Đúng. Khu thương mại và khu dân cư là 30 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa New Mexico, ano ang speed limit sa business o residential area kapag walang karatulang nagsasabi ng iba?","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"Ito ay doble ng limit sa school zone.","h2":"Sa New Mexico, ang speed limit sa mga business at residential area ay 30 mph maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 30 mph sa mga business at residential area maliban kung may ibang nakapaskil."},"ar":{"q":"في New Mexico، ما حد السرعة في منطقة تجارية أو سكنية عندما لا توجد لافتة تقول غير ذلك؟","o":["15 mph","25 mph","30 mph","40 mph"],"h1":"إنه ضعف حد السرعة في المنطقة المدرسية.","h2":"في New Mexico حد السرعة في المناطق التجارية والسكنية هو 30 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. حد السرعة في المناطق التجارية والسكنية 30 mph ما لم تقل لافتة غير ذلك."},"ref":{"doc":"NM","page":12}},{"id":"nm-041","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, what is the speed limit on a public highway that is not a rural interstate, when no sign says otherwise?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"It is 20 mph less than the rural interstate limit.","h2":"In New Mexico the speed limit on public highways is 55 mph unless a sign shows a different limit.","p":"Right. Public highways are 55 mph unless posted otherwise."},"es":{"q":"En Nuevo México, ¿cuál es el límite de velocidad en una carretera pública que no es una interestatal rural, cuando ninguna señal indica otro?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"Es 20 mph menos que el límite en las interestatales rurales.","h2":"En Nuevo México el límite de velocidad en las carreteras públicas es de 55 mph, a menos que una señal indique otro límite.","p":"Correcto. Las carreteras públicas son de 55 mph si no hay otra señal."},"zh":{"q":"在 New Mexico，如果没有标志另作规定，不是乡村州际公路的公共公路限速是多少？","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"它比乡村州际公路的限速低 20 mph。","h2":"在 New Mexico，公共公路的限速是 55 mph，除非标志显示别的限速。","p":"对。公共公路限速 55 mph，除非另有标志。"},"vi":{"q":"Ở New Mexico, giới hạn tốc độ trên đường quốc lộ công cộng không phải đường liên bang ở nông thôn là bao nhiêu khi không có biển báo nói khác?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"Nó thấp hơn giới hạn trên đường liên bang ở nông thôn 20 mph.","h2":"Ở New Mexico, giới hạn tốc độ trên đường quốc lộ công cộng là 55 mph, trừ khi biển báo cho thấy giới hạn khác.","p":"Đúng. Đường quốc lộ công cộng là 55 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa New Mexico, ano ang speed limit sa pampublikong highway na hindi rural interstate, kapag walang karatulang nagsasabi ng iba?","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"Ito ay 20 mph na mas mababa kaysa sa limit sa rural interstate.","h2":"Sa New Mexico, ang speed limit sa mga pampublikong highway ay 55 mph maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 55 mph sa mga pampublikong highway maliban kung may ibang nakapaskil."},"ar":{"q":"في New Mexico، ما حد السرعة على طريق سريع عام ليس طريقًا سريعًا بين الولايات في منطقة ريفية، عندما لا توجد لافتة تقول غير ذلك؟","o":["55 mph","45 mph","65 mph","75 mph"],"h1":"إنه أقل بـ 20 mph من حد السرعة على الطرق السريعة بين الولايات في المناطق الريفية.","h2":"في New Mexico حد السرعة على الطرق السريعة العامة هو 55 mph ما لم تُظهر لافتة حدًا مختلفًا.","p":"صحيح. حد السرعة على الطرق السريعة العامة 55 mph ما لم تقل لافتة غير ذلك."},"ref":{"doc":"NM","page":12}},{"id":"nm-042","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, how far before a turn should you turn on your turn signal?","o":["At least 10 feet","Only when you start to turn","At least 1 mile","At least 100 feet"],"h1":"It is about the length of a few cars in a row, more than 50 feet.","h2":"In New Mexico you should signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet before the turn."},"es":{"q":"En Nuevo México, ¿con cuánta anticipación antes de girar debe encender la direccional?","o":["Al menos 10 pies antes","Solo cuando empieza a girar","Al menos 1 milla antes","Al menos 100 pies antes"],"h1":"Es como el largo de varios autos en fila, más de 50 pies.","h2":"En Nuevo México usted debe señalar al menos 100 pies antes de girar.","p":"Correcto. Señale al menos 100 pies antes del giro."},"zh":{"q":"在 New Mexico，转弯前多远就应该打开转向灯？","o":["至少 10 英尺","开始转弯时才打","至少 1 英里","至少 100 英尺"],"h1":"大约是几辆车排成一排的长度，超过 50 英尺。","h2":"在 New Mexico，你应该在转弯前至少 100 英尺打转向灯。","p":"对。在转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở New Mexico, bạn nên bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 10 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 1 mile","Ít nhất 100 feet"],"h1":"Nó khoảng bằng chiều dài vài chiếc xe xếp thành hàng, hơn 50 feet.","h2":"Ở New Mexico, bạn nên bật đèn xi nhan ít nhất 100 feet trước khi rẽ.","p":"Đúng. Hãy bật xi nhan ít nhất 100 feet trước chỗ rẽ."},"tl":{"q":"Sa New Mexico, gaano kalayo bago lumiko dapat mong buksan ang turn signal?","o":["Hindi bababa sa 10 feet","Kapag nagsisimula ka lang lumiko","Hindi bababa sa 1 mile","Hindi bababa sa 100 feet"],"h1":"Ito ay mga kasinghaba ng ilang kotseng nakahanay, higit sa 50 feet.","h2":"Sa New Mexico, dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago lumiko."},"ar":{"q":"في New Mexico، على أي مسافة قبل المنعطف يجب أن تُشغّل إشارة الانعطاف؟","o":["10 feet على الأقل","فقط عندما تبدأ بالانعطاف","1 mile على الأقل","100 feet على الأقل"],"h1":"إنها تقريبًا طول بضع سيارات في صف واحد، أكثر من 50 feet.","h2":"في New Mexico يجب أن تُشغّل الإشارة قبل 100 feet على الأقل من المنعطف.","p":"صحيح. شغّل الإشارة قبل 100 feet على الأقل من المنعطف."},"ref":{"doc":"NM","page":19}},{"id":"nm-043","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you are using high beams at night. When should you dim them for a car coming toward you?","o":["When it is about half a mile away","When it is within about one block","Only when it is right next to you","Never; high beams are always allowed"],"h1":"Think of the length of one city block.","h2":"In New Mexico you should dim your high beams when an oncoming vehicle is within about one block.","p":"Right. Dim your high beams within about one block of an oncoming car."},"es":{"q":"En Nuevo México, usted usa las luces altas de noche. ¿Cuándo debe bajarlas por un auto que viene de frente?","o":["Cuando está a media milla","Cuando está a una cuadra o menos","Solo cuando está justo a su lado","Nunca; las luces altas siempre están permitidas"],"h1":"Piense en el largo de una cuadra de la ciudad.","h2":"En Nuevo México usted debe bajar las luces altas cuando un vehículo que viene de frente está a una cuadra o menos.","p":"Correcto. Baje las luces altas cuando un auto de frente esté a una cuadra o menos."},"zh":{"q":"在 New Mexico，你晚上开着远光灯。对面有车开过来时，你应该什么时候把灯调暗？","o":["在它离你大约半英里时","在它离你大约一个街区以内时","只有在它就在你旁边时","永远不用；远光灯什么时候都可以开"],"h1":"想一想一个城市街区的长度。","h2":"在 New Mexico，当对面来车离你大约一个街区以内时，你应该把远光灯调暗。","p":"对。对面来车在大约一个街区以内时，把远光灯调暗。"},"vi":{"q":"Ở New Mexico, bạn đang bật đèn pha chiếu xa vào ban đêm. Khi nào bạn nên hạ đèn xuống vì có xe đang chạy về phía bạn?","o":["Khi xe đó cách khoảng nửa mile","Khi xe đó ở trong khoảng một dãy nhà","Chỉ khi xe đó ở ngay cạnh bạn","Không bao giờ; đèn pha chiếu xa luôn được phép"],"h1":"Hãy nghĩ đến chiều dài của một dãy nhà trong thành phố.","h2":"Ở New Mexico, bạn nên hạ đèn pha chiếu xa khi xe đi ngược chiều ở trong khoảng một dãy nhà.","p":"Đúng. Hãy hạ đèn pha chiếu xa khi xe ngược chiều ở trong khoảng một dãy nhà."},"tl":{"q":"Sa New Mexico, gumagamit ka ng high beams sa gabi. Kailan mo dapat i-dim ang mga ito para sa kotseng papunta sa direksiyon mo?","o":["Kapag mga kalahating mile pa ang layo nito","Kapag nasa loob na ito ng mga isang block","Kapag nasa tabi mo na lang ito","Hindi kailanman; laging puwede ang high beams"],"h1":"Isipin ang haba ng isang block sa lungsod.","h2":"Sa New Mexico, dapat mong i-dim ang high beams kapag ang paparating na sasakyan ay nasa loob ng mga isang block.","p":"Tama. I-dim ang high beams kapag ang paparating na kotse ay nasa loob ng mga isang block."},"ar":{"q":"في New Mexico، تستخدم الأضواء العالية في الليل. متى يجب أن تخفّضها لسيارة قادمة نحوك؟","o":["عندما تكون على بُعد نحو نصف mile","عندما تكون على بُعد نحو مربع سكني واحد","فقط عندما تكون بجانبك مباشرة","أبدًا؛ الأضواء العالية مسموحة دائمًا"],"h1":"فكّر في طول مربع سكني واحد في المدينة.","h2":"في New Mexico يجب أن تخفّض أضواءك العالية عندما تكون المركبة القادمة على بُعد نحو مربع سكني واحد.","p":"صحيح. خفّض أضواءك العالية عندما تكون السيارة القادمة على بُعد نحو مربع سكني واحد."},"ref":{"doc":"NM","page":18}},{"id":"nm-044","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, the road is covered with packed snow. How much should you slow down?","o":["About 5 mph","About 10 mph","Cut your speed about in half","Not at all, if you have good tires"],"h1":"Packed snow is much more slippery than a wet road.","h2":"In New Mexico the driver manual says to cut your speed about in half on packed snow.","p":"Right. On packed snow, cut your speed about in half."},"es":{"q":"En Nuevo México, la carretera está cubierta de nieve compacta. ¿Cuánto debe reducir la velocidad?","o":["Unas 5 mph","Unas 10 mph","Reducir la velocidad más o menos a la mitad","Nada, si tiene buenas llantas"],"h1":"La nieve compacta es mucho más resbalosa que una carretera mojada.","h2":"En Nuevo México el manual del conductor dice que debe reducir la velocidad más o menos a la mitad sobre nieve compacta.","p":"Correcto. Sobre nieve compacta, reduzca la velocidad más o menos a la mitad."},"zh":{"q":"在 New Mexico，路上盖着压实的积雪。你应该减速多少？","o":["大约 5 mph","大约 10 mph","把车速减到大约一半","不用减速，只要轮胎好"],"h1":"压实的积雪比湿路面滑得多。","h2":"在 New Mexico，驾驶手册说在压实的积雪上要把车速减到大约一半。","p":"对。在压实的积雪上，把车速减到大约一半。"},"vi":{"q":"Ở New Mexico, mặt đường bị phủ tuyết nén chặt. Bạn nên giảm tốc độ bao nhiêu?","o":["Khoảng 5 mph","Khoảng 10 mph","Giảm tốc độ còn khoảng một nửa","Không cần giảm, nếu lốp xe của bạn tốt"],"h1":"Tuyết nén chặt trơn hơn nhiều so với đường ướt.","h2":"Ở New Mexico, sách hướng dẫn lái xe nói hãy giảm tốc độ còn khoảng một nửa trên tuyết nén chặt.","p":"Đúng. Trên tuyết nén chặt, hãy giảm tốc độ còn khoảng một nửa."},"tl":{"q":"Sa New Mexico, ang daan ay natatakpan ng siksik na niyebe. Gaano mo dapat bagalan?","o":["Mga 5 mph","Mga 10 mph","Bawasan ang bilis mo nang mga kalahati","Hindi na, kung maganda ang gulong mo"],"h1":"Mas madulas ang siksik na niyebe kaysa sa basang daan.","h2":"Sa New Mexico, sinasabi ng driver manual na bawasan ang bilis mo nang mga kalahati sa siksik na niyebe.","p":"Tama. Sa siksik na niyebe, bawasan ang bilis mo nang mga kalahati."},"ar":{"q":"في New Mexico، الطريق مغطّى بثلج مضغوط. بكم يجب أن تخفّف سرعتك؟","o":["نحو 5 mph","نحو 10 mph","خفّض سرعتك إلى النصف تقريبًا","لا داعي لذلك، إذا كانت إطاراتك جيدة"],"h1":"الثلج المضغوط أكثر انزلاقًا بكثير من الطريق المبلل.","h2":"في New Mexico يقول دليل السائق إن عليك أن تخفّض سرعتك إلى النصف تقريبًا على الثلج المضغوط.","p":"صحيح. على الثلج المضغوط، خفّض سرعتك إلى النصف تقريبًا."},"ref":{"doc":"NM","page":20}},{"id":"nm-045","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, who must wear a helmet on a motorcycle?","o":["All riders and passengers under 18","Only the rider, not the passenger","Only riders on interstate highways","No one; helmets are never required"],"h1":"The law covers young people. Helmets are recommended for everyone.","h2":"In New Mexico the law requires motorcycle riders and passengers under 18 to wear a helmet.","p":"Right. Riders and passengers under 18 must wear a helmet."},"es":{"q":"En Nuevo México, ¿quién debe usar casco en una motocicleta?","o":["Todos los conductores y pasajeros menores de 18 años","Solo el conductor, no el pasajero","Solo los conductores en carreteras interestatales","Nadie; el casco nunca es obligatorio"],"h1":"La ley protege a los jóvenes. Se recomienda el casco para todos.","h2":"En Nuevo México la ley exige que los conductores y pasajeros de motocicleta menores de 18 años usen casco.","p":"Correcto. Los conductores y pasajeros menores de 18 años deben usar casco."},"zh":{"q":"在 New Mexico，骑摩托车时谁必须戴头盔？","o":["所有 18 岁以下的骑车人和乘客","只有骑车人，乘客不用","只有在州际公路上骑车的人","没有人；从来不要求戴头盔"],"h1":"法律保护的是年轻人。建议每个人都戴头盔。","h2":"在 New Mexico，法律要求 18 岁以下的摩托车骑车人和乘客戴头盔。","p":"对。18 岁以下的骑车人和乘客必须戴头盔。"},"vi":{"q":"Ở New Mexico, ai phải đội mũ bảo hiểm khi đi xe máy?","o":["Tất cả người lái và người ngồi sau dưới 18 tuổi","Chỉ người lái, không phải người ngồi sau","Chỉ người lái trên đường liên bang","Không ai cả; không bao giờ bắt buộc đội mũ bảo hiểm"],"h1":"Luật áp dụng cho người trẻ. Mọi người đều được khuyên nên đội mũ bảo hiểm.","h2":"Ở New Mexico, luật bắt buộc người lái xe máy và người ngồi sau dưới 18 tuổi phải đội mũ bảo hiểm.","p":"Đúng. Người lái và người ngồi sau dưới 18 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa New Mexico, sino ang dapat magsuot ng helmet sa motorsiklo?","o":["Lahat ng rider at pasahero na wala pang 18","Ang rider lang, hindi ang pasahero","Ang mga rider lang sa interstate highway","Wala; hindi kailanman kailangan ang helmet"],"h1":"Para sa mga kabataan ang batas. Inirerekomenda ang helmet para sa lahat.","h2":"Sa New Mexico, iniuutos ng batas na magsuot ng helmet ang mga rider at pasahero ng motorsiklo na wala pang 18.","p":"Tama. Dapat magsuot ng helmet ang mga rider at pasahero na wala pang 18."},"ar":{"q":"في New Mexico، من يجب أن يلبس خوذة على الدراجة النارية؟","o":["كل السائقين والركاب الذين أعمارهم أقل من 18","السائق فقط، وليس الراكب","السائقون على الطرق السريعة بين الولايات فقط","لا أحد؛ الخوذة غير مطلوبة أبدًا"],"h1":"القانون يشمل صغار السن. ويُنصح الجميع بلبس الخوذة.","h2":"في New Mexico يفرض القانون على سائقي الدراجات النارية وركابها الذين أعمارهم أقل من 18 أن يلبسوا خوذة.","p":"صحيح. يجب على السائقين والركاب الذين أعمارهم أقل من 18 أن يلبسوا خوذة."},"ref":{"doc":"NM","page":37}},{"id":"nm-046","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, you are passing a person on a bicycle. How much space should you try to give?","o":["At least 1 foot","At least 2 feet","No space is needed","At least 5 feet"],"h1":"It is more than one yard, but less than two yards.","h2":"In New Mexico you should try to leave at least five feet when you pass a bicyclist.","p":"Right. Try to give a bicyclist at least five feet."},"es":{"q":"En Nuevo México, usted va a rebasar a una persona en bicicleta. ¿Cuánto espacio debe tratar de dejarle?","o":["Al menos 1 pie","Al menos 2 pies","No hace falta espacio","Al menos 5 pies"],"h1":"Es más de una yarda, pero menos de dos yardas.","h2":"En Nuevo México usted debe tratar de dejar al menos cinco pies al rebasar a un ciclista.","p":"Correcto. Trate de dejarle al menos cinco pies al ciclista."},"zh":{"q":"在 New Mexico，你正在超过一个骑自行车的人。你应该尽量留出多少空间？","o":["至少 1 英尺","至少 2 英尺","不需要留空间","至少 5 英尺"],"h1":"它比一码多，但比两码少。","h2":"在 New Mexico，超过骑自行车的人时，你应该尽量留出至少 5 英尺的空间。","p":"对。尽量给骑自行车的人留出至少 5 英尺。"},"vi":{"q":"Ở New Mexico, bạn đang vượt một người đi xe đạp. Bạn nên cố gắng chừa khoảng cách bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Không cần chừa khoảng cách","Ít nhất 5 feet"],"h1":"Nó hơn một yard, nhưng ít hơn hai yard.","h2":"Ở New Mexico, bạn nên cố gắng chừa ít nhất 5 feet khi vượt người đi xe đạp.","p":"Đúng. Hãy cố gắng chừa cho người đi xe đạp ít nhất 5 feet."},"tl":{"q":"Sa New Mexico, nilalampasan mo ang isang taong nagbibisikleta. Gaano kalaking espasyo ang dapat mong subukang ibigay?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi kailangan ng espasyo","Hindi bababa sa 5 feet"],"h1":"Ito ay higit sa isang yard, pero kulang sa dalawang yard.","h2":"Sa New Mexico, dapat mong subukang mag-iwan ng hindi bababa sa 5 feet kapag nilalampasan mo ang nagbibisikleta.","p":"Tama. Subukang bigyan ang nagbibisikleta ng hindi bababa sa 5 feet."},"ar":{"q":"في New Mexico، أنت تتجاوز شخصًا يركب دراجة هوائية. كم مسافة يجب أن تحاول أن تتركها؟","o":["1 foot على الأقل","2 feet على الأقل","لا حاجة لأي مسافة","5 feet على الأقل"],"h1":"إنها أكثر من yard واحدة، لكن أقل من yard اثنتين.","h2":"في New Mexico يجب أن تحاول أن تترك 5 feet على الأقل عندما تتجاوز راكب دراجة هوائية.","p":"صحيح. حاول أن تترك لراكب الدراجة الهوائية 5 feet على الأقل."},"ref":{"doc":"NM","page":25}},{"id":"nm-047","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, a school bus or a truck carrying gasoline comes to a railroad crossing. What must it do?","o":["Cross quickly without stopping","Stop at least 15 feet from the crossing before going on","Stop only if a train can be seen","Stop right on the tracks to look both ways"],"h1":"These vehicles must always stop, and not too close to the tracks.","h2":"In New Mexico school buses, vehicles for hire that carry passengers, and trucks carrying dangerous loads such as gasoline must stop at least 15 feet from a railroad crossing before going on.","p":"Right. They must stop at least 15 feet from the crossing."},"es":{"q":"En Nuevo México, un autobús escolar o un camión que lleva gasolina llega a un cruce de ferrocarril. ¿Qué debe hacer?","o":["Cruzar rápido sin detenerse","Detenerse al menos a 15 pies del cruce antes de seguir","Detenerse solo si se ve un tren","Detenerse sobre las vías para mirar a ambos lados"],"h1":"Estos vehículos siempre deben detenerse, y no demasiado cerca de las vías.","h2":"En Nuevo México los autobuses escolares, los vehículos de alquiler que llevan pasajeros y los camiones con cargas peligrosas como gasolina deben detenerse al menos a 15 pies de un cruce de ferrocarril antes de seguir.","p":"Correcto. Deben detenerse al menos a 15 pies del cruce."},"zh":{"q":"在 New Mexico，校车或运汽油的卡车来到铁路道口。它必须怎么做？","o":["不停车，快速通过","在离道口至少 15 英尺的地方停车，然后再走","只有看到火车时才停车","停在铁轨上，向两边看"],"h1":"这些车辆必须每次都停车，而且不能离铁轨太近。","h2":"在 New Mexico，校车、载客的营运车辆，以及运汽油等危险货物的卡车，必须在离铁路道口至少 15 英尺的地方停车，然后才能继续走。","p":"对。它们必须在离道口至少 15 英尺的地方停车。"},"vi":{"q":"Ở New Mexico, một xe buýt trường học hoặc một xe tải chở xăng đến chỗ giao nhau với đường sắt. Xe đó phải làm gì?","o":["Chạy qua nhanh mà không dừng","Dừng cách chỗ giao nhau ít nhất 15 feet rồi mới đi tiếp","Chỉ dừng nếu thấy tàu hỏa","Dừng ngay trên đường ray để nhìn hai bên"],"h1":"Những xe này luôn phải dừng, và không được quá gần đường ray.","h2":"Ở New Mexico, xe buýt trường học, xe chở khách thuê, và xe tải chở hàng nguy hiểm như xăng phải dừng cách chỗ giao nhau với đường sắt ít nhất 15 feet rồi mới đi tiếp.","p":"Đúng. Các xe đó phải dừng cách chỗ giao nhau ít nhất 15 feet."},"tl":{"q":"Sa New Mexico, isang school bus o isang truck na may kargang gasolina ang dumating sa railroad crossing. Ano ang dapat nitong gawin?","o":["Tumawid nang mabilis nang hindi humihinto","Huminto nang hindi bababa sa 15 feet mula sa crossing bago magpatuloy","Huminto lang kung may nakikitang tren","Huminto mismo sa riles para tumingin sa magkabilang panig"],"h1":"Laging dapat huminto ang mga sasakyang ito, at hindi masyadong malapit sa riles.","h2":"Sa New Mexico, ang mga school bus, mga pinaupahang sasakyan na nagsasakay ng pasahero, at mga truck na may mapanganib na karga gaya ng gasolina ay dapat huminto nang hindi bababa sa 15 feet mula sa railroad crossing bago magpatuloy.","p":"Tama. Dapat silang huminto nang hindi bababa sa 15 feet mula sa crossing."},"ar":{"q":"في New Mexico، تصل حافلة مدرسية أو شاحنة تحمل البنزين إلى معبر سكة حديد. ماذا يجب أن تفعل؟","o":["أن تعبر بسرعة دون توقف","أن تتوقف على بُعد 15 feet على الأقل من المعبر قبل أن تتابع","أن تتوقف فقط إذا رأت قطارًا","أن تتوقف فوق القضبان مباشرة لتنظر في الاتجاهين"],"h1":"هذه المركبات يجب أن تتوقف دائمًا، وليس قريبًا جدًا من القضبان.","h2":"في New Mexico يجب على الحافلات المدرسية، ومركبات الأجرة التي تنقل الركاب، والشاحنات التي تحمل حمولات خطرة مثل البنزين أن تتوقف على بُعد 15 feet على الأقل من معبر السكة الحديد قبل أن تتابع.","p":"صحيح. يجب أن تتوقف على بُعد 15 feet على الأقل من المعبر."},"ref":{"doc":"NM","page":6}},{"id":"nm-048","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, what is the minimum insurance for injury to or death of one person in one crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is more than the minimum for property damage, but less than $50,000.","h2":"In New Mexico the minimum liability insurance for injury to or death of one person in one crash is $25,000.","p":"Right. The minimum for one person is $25,000."},"es":{"q":"En Nuevo México, ¿cuál es el seguro mínimo por lesiones o muerte de una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es más que el mínimo por daños a la propiedad, pero menos de $50,000.","h2":"En Nuevo México el seguro de responsabilidad mínimo por lesiones o muerte de una persona en un choque es de $25,000.","p":"Correcto. El mínimo por una persona es de $25,000."},"zh":{"q":"在 New Mexico，一次车祸中一个人受伤或死亡的最低保险额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"它比财产损失的最低额多，但少于 $50,000。","h2":"在 New Mexico，一次车祸中一个人受伤或死亡的最低责任保险额是 $25,000。","p":"对。一个人的最低保险额是 $25,000。"},"vi":{"q":"Ở New Mexico, mức bảo hiểm tối thiểu cho thương tích hoặc tử vong của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Nó nhiều hơn mức tối thiểu cho thiệt hại tài sản, nhưng ít hơn $50,000.","h2":"Ở New Mexico, mức bảo hiểm trách nhiệm tối thiểu cho thương tích hoặc tử vong của một người trong một vụ tai nạn là $25,000.","p":"Đúng. Mức tối thiểu cho một người là $25,000."},"tl":{"q":"Sa New Mexico, ano ang pinakamababang insurance para sa pinsala o pagkamatay ng isang tao sa isang aksidente?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Mas mataas ito kaysa sa minimum para sa pinsala sa ari-arian, pero mas mababa sa $50,000.","h2":"Sa New Mexico, ang pinakamababang liability insurance para sa pinsala o pagkamatay ng isang tao sa isang aksidente ay $25,000.","p":"Tama. Ang minimum para sa isang tao ay $25,000."},"ar":{"q":"في New Mexico، ما الحد الأدنى للتأمين عن إصابة شخص واحد أو وفاته في حادث واحد؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"إنه أكثر من الحد الأدنى لأضرار الممتلكات، لكنه أقل من $50,000.","h2":"في New Mexico الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد أو وفاته في حادث واحد هو $25,000.","p":"صحيح. الحد الأدنى لشخص واحد هو $25,000."},"ref":{"doc":"NM","page":35}},{"id":"nm-049","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what can happen if you do not have car insurance?","o":["Your vehicle registration can be suspended and you may have to turn in your plates","Nothing, if you drive carefully","You only get a warning the first time","You must take the road test again"],"h1":"The state can take away your right to keep the car on the road.","h2":"In New Mexico driving without insurance can lead to a suspended registration, turning in your license plates, and possible criminal penalties.","p":"Right. No insurance can cost you your registration and your plates."},"es":{"q":"En Nuevo México, ¿qué puede pasar si no tiene seguro de auto?","o":["Le pueden suspender el registro del vehículo y puede tener que entregar las placas","Nada, si maneja con cuidado","Solo recibe una advertencia la primera vez","Debe tomar otra vez el examen de manejo"],"h1":"El estado puede quitarle el derecho de tener el auto en la carretera.","h2":"En Nuevo México manejar sin seguro puede llevar a la suspensión del registro, a entregar las placas y a posibles sanciones penales.","p":"Correcto. No tener seguro le puede costar el registro y las placas."},"zh":{"q":"在 New Mexico，如果你没有汽车保险，会发生什么？","o":["你的车辆登记可能被暂停，你可能必须交回车牌","什么都不会发生，只要你小心开车","第一次只会被警告","你必须重新参加路考"],"h1":"州政府可以拿走你让这辆车上路的权利。","h2":"在 New Mexico，没有保险开车可能导致车辆登记被暂停、必须交回车牌，还可能受到刑事处罚。","p":"对。没有保险可能让你失去车辆登记和车牌。"},"vi":{"q":"Ở New Mexico, điều gì có thể xảy ra nếu bạn không có bảo hiểm xe?","o":["Đăng ký xe của bạn có thể bị đình chỉ và bạn có thể phải nộp lại biển số","Không có gì, nếu bạn lái cẩn thận","Lần đầu bạn chỉ bị cảnh cáo","Bạn phải thi lái xe trên đường lại"],"h1":"Tiểu bang có thể lấy đi quyền cho xe của bạn chạy trên đường.","h2":"Ở New Mexico, lái xe không có bảo hiểm có thể khiến đăng ký xe bị đình chỉ, phải nộp lại biển số, và có thể bị phạt hình sự.","p":"Đúng. Không có bảo hiểm có thể khiến bạn mất đăng ký xe và biển số."},"tl":{"q":"Sa New Mexico, ano ang puwedeng mangyari kung wala kang car insurance?","o":["Puwedeng ma-suspend ang registration ng sasakyan mo at baka kailangan mong isauli ang plaka","Wala, kung maingat kang magmaneho","Babala lang ang makukuha mo sa unang beses","Kailangan mong kumuha ulit ng road test"],"h1":"Puwedeng alisin ng estado ang karapatan mong gamitin ang kotse sa daan.","h2":"Sa New Mexico, ang pagmamaneho nang walang insurance ay puwedeng humantong sa suspendidong registration, pagsasauli ng plaka, at posibleng kriminal na parusa.","p":"Tama. Kapag walang insurance, puwede kang mawalan ng registration at plaka."},"ar":{"q":"في New Mexico، ماذا يمكن أن يحدث إذا لم يكن لديك تأمين على السيارة؟","o":["يمكن أن يُعلَّق تسجيل مركبتك وقد يكون عليك أن تُسلّم لوحاتها","لا شيء، إذا قدت بحذر","تحصل على تحذير فقط في المرة الأولى","يجب أن تُعيد اختبار القيادة على الطريق"],"h1":"يمكن للولاية أن تسحب حقك في إبقاء السيارة على الطريق.","h2":"في New Mexico يمكن أن تؤدي القيادة دون تأمين إلى تعليق تسجيل المركبة، وتسليم لوحاتها، وعقوبات جنائية محتملة.","p":"صحيح. عدم وجود تأمين قد يُفقدك تسجيل المركبة ولوحاتها."},"ref":{"doc":"NM","page":35}},{"id":"nm-050","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, you see an orange triangle on the back of a vehicle. What does it tell you?","o":["The vehicle carries a dangerous load","The driver is a student","The vehicle is an emergency vehicle","The vehicle goes less than 25 mph"],"h1":"You often see it on farm tractors and horse-drawn wagons.","h2":"In New Mexico an orange triangle on the back of a vehicle means it is a slow-moving vehicle that travels under 25 mph.","p":"Right. The orange triangle marks a slow vehicle going under 25 mph."},"es":{"q":"En Nuevo México, usted ve un triángulo anaranjado en la parte de atrás de un vehículo. ¿Qué le indica?","o":["El vehículo lleva una carga peligrosa","El conductor es un estudiante","Es un vehículo de emergencia","El vehículo va a menos de 25 mph"],"h1":"Se ve a menudo en tractores agrícolas y carretas tiradas por caballos.","h2":"En Nuevo México un triángulo anaranjado en la parte de atrás de un vehículo indica que es un vehículo lento que va a menos de 25 mph.","p":"Correcto. El triángulo anaranjado marca un vehículo lento que va a menos de 25 mph."},"zh":{"q":"在 New Mexico，你看到一辆车后面有一个橙色三角形。它告诉你什么？","o":["这辆车装着危险货物","司机是学员","这辆车是紧急车辆","这辆车的速度低于 25 mph"],"h1":"你常常在农用拖拉机和马拉的车上看到它。","h2":"在 New Mexico，车后面的橙色三角形表示这是一辆慢速车辆，速度低于 25 mph。","p":"对。橙色三角形表示速度低于 25 mph 的慢速车辆。"},"vi":{"q":"Ở New Mexico, bạn thấy một hình tam giác màu cam ở phía sau một chiếc xe. Nó cho bạn biết điều gì?","o":["Xe đó chở hàng nguy hiểm","Người lái là học viên","Xe đó là xe khẩn cấp","Xe đó chạy dưới 25 mph"],"h1":"Bạn thường thấy nó trên máy kéo nông trại và xe ngựa kéo.","h2":"Ở New Mexico, hình tam giác màu cam ở phía sau một chiếc xe có nghĩa đó là xe chạy chậm, đi dưới 25 mph.","p":"Đúng. Hình tam giác màu cam đánh dấu xe chạy chậm dưới 25 mph."},"tl":{"q":"Sa New Mexico, may nakikita kang orange na tatsulok sa likod ng isang sasakyan. Ano ang sinasabi nito sa iyo?","o":["May mapanganib na karga ang sasakyan","Estudyante ang driver","Emergency vehicle ang sasakyan","Mas mabagal sa 25 mph ang takbo ng sasakyan"],"h1":"Madalas mo itong makita sa mga tractor sa bukid at mga karitong hila ng kabayo.","h2":"Sa New Mexico, ang orange na tatsulok sa likod ng sasakyan ay nangangahulugang mabagal na sasakyan ito na tumatakbo nang mas mababa sa 25 mph.","p":"Tama. Ang orange na tatsulok ay tanda ng mabagal na sasakyan na mas mababa sa 25 mph."},"ar":{"q":"في New Mexico، ترى مثلثًا برتقاليًا على مؤخرة مركبة. ماذا يخبرك؟","o":["المركبة تحمل حمولة خطرة","السائق متعلّم","المركبة مركبة طوارئ","المركبة تسير بأقل من 25 mph"],"h1":"تراه كثيرًا على الجرارات الزراعية والعربات التي تجرّها الخيول.","h2":"في New Mexico يعني المثلث البرتقالي على مؤخرة المركبة أنها مركبة بطيئة تسير بأقل من 25 mph.","p":"صحيح. المثلث البرتقالي يدلّ على مركبة بطيئة تسير بأقل من 25 mph."},"ref":{"doc":"NM","page":7}},{"id":"nm-051","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, you are learning to ride a motorcycle on an instruction permit. Where must your licensed supervising driver be?","o":["Following behind you","Riding on the back seat of your motorcycle","Riding in front of you to lead the way","Waiting at home with a phone"],"h1":"On a car the supervisor sits beside you; on a motorcycle it is different.","h2":"In New Mexico, when a permit holder rides a motorcycle, the licensed supervising driver must follow behind the learner.","p":"Right. On a motorcycle, the licensed driver follows the learner."},"es":{"q":"En Nuevo México, usted aprende a manejar motocicleta con un permiso de instrucción. ¿Dónde debe estar el conductor con licencia que lo supervisa?","o":["Siguiéndolo por detrás","En el asiento trasero de su motocicleta","Delante de usted para guiarlo","Esperando en casa con un teléfono"],"h1":"En un carro el supervisor se sienta a su lado; en una motocicleta es distinto.","h2":"En Nuevo México, cuando alguien con permiso maneja una motocicleta, el conductor con licencia que lo supervisa debe ir detrás de él.","p":"Correcto. En motocicleta, el conductor con licencia sigue al aprendiz."},"ref":{"doc":"NM","page":1}},{"id":"nm-052","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, you are 16 and applying for an instruction permit. Besides the tests, what else do you need?","o":["A letter from your school principal","A consent form signed by your parent or guardian","Proof that you own a car","A signed note from a police officer"],"h1":"Think of the adult who is responsible for you.","h2":"In New Mexico, a permit applicant under 18 needs a consent form signed by a parent or guardian.","p":"Right. Under 18, you need a parent or guardian to sign a consent form."},"es":{"q":"En Nuevo México, usted tiene 16 años y solicita un permiso de instrucción. Además de los exámenes, ¿qué más necesita?","o":["Una carta del director de su escuela","Un formulario de consentimiento firmado por su padre, madre o tutor","Prueba de que usted es dueño de un carro","Una nota firmada por un policía"],"h1":"Piense en el adulto que es responsable de usted.","h2":"En Nuevo México, quien solicita un permiso y tiene menos de 18 años necesita un formulario de consentimiento firmado por su padre, madre o tutor.","p":"Correcto. Si tiene menos de 18 años, su padre, madre o tutor debe firmar un consentimiento."},"ref":{"doc":"NM","page":1}},{"id":"nm-053","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, which tests must you pass to get a provisional license?","o":["Only a vision screening","Only a road test","A written test, a road test and a vision screening","A written test only"],"h1":"You must show what you know, how you drive and how you see.","h2":"In New Mexico, to get a provisional license you must pass a written test and a road test, plus a vision screening.","p":"Right. You need the written test, the road test and a vision screening."},"es":{"q":"En Nuevo México, ¿qué exámenes debe aprobar para obtener una licencia provisional?","o":["Solo una prueba de la vista","Solo un examen de manejo","Un examen escrito, un examen de manejo y una prueba de la vista","Solo un examen escrito"],"h1":"Debe mostrar lo que sabe, cómo maneja y cómo ve.","h2":"En Nuevo México, para obtener una licencia provisional usted debe aprobar un examen escrito y un examen de manejo, además de una prueba de la vista.","p":"Correcto. Necesita el examen escrito, el de manejo y la prueba de la vista."},"ref":{"doc":"NM","page":1}},{"id":"nm-054","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, a provisional driver needs to drive home from a job after midnight. What is needed for this to be allowed?","o":["A text message from a friend","Nothing; work trips never need proof","A note from the driver's teacher","A signed statement from the employer"],"h1":"The proof comes from the person who gives the job.","h2":"In New Mexico, a provisional driver may drive to and from work at night if the employer gives a signed statement.","p":"Right. For work trips at night, the employer signs a statement."},"es":{"q":"En Nuevo México, un conductor con licencia provisional necesita manejar a casa desde su trabajo después de la medianoche. ¿Qué se necesita para que esté permitido?","o":["Un mensaje de texto de un amigo","Nada; los viajes de trabajo nunca necesitan prueba","Una nota del maestro del conductor","Una declaración firmada por el empleador"],"h1":"La prueba viene de la persona que da el trabajo.","h2":"En Nuevo México, un conductor con licencia provisional puede manejar de noche hacia y desde el trabajo si el empleador da una declaración firmada.","p":"Correcto. Para ir al trabajo de noche, el empleador firma una declaración."},"ref":{"doc":"NM","page":2}},{"id":"nm-055","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, a provisional driver has a speeding ticket that the court has not decided yet. Can the driver get a full (unrestricted) license now?","o":["Yes, a pending ticket does not count","Yes, if the driver pays a small extra fee","No, no traffic violation may be pending when you apply","Yes, if a parent signs a form"],"h1":"The case must be closed before you apply.","h2":"In New Mexico, you cannot get an unrestricted license while any traffic violation is still pending.","p":"Right. You may not have a traffic violation pending when you apply."},"es":{"q":"En Nuevo México, un conductor con licencia provisional tiene una multa por exceso de velocidad que la corte todavía no ha decidido. ¿Puede obtener ahora una licencia completa (sin restricciones)?","o":["Sí, una multa pendiente no cuenta","Sí, si paga una pequeña tarifa adicional","No, no puede tener ninguna infracción de tránsito pendiente al solicitarla","Sí, si su padre o madre firma un formulario"],"h1":"El caso debe estar cerrado antes de solicitarla.","h2":"En Nuevo México, usted no puede obtener una licencia sin restricciones mientras tenga una infracción de tránsito pendiente.","p":"Correcto. No puede tener infracciones de tránsito pendientes al solicitarla."},"ref":{"doc":"NM","page":2}},{"id":"nm-056","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what should you bring when you renew your driver license?","o":["Your current license and one other proof of identity","Only your car's title","A letter from your doctor","Your car insurance card only"],"h1":"You show the old card plus something else that proves who you are.","h2":"In New Mexico, to renew your license you bring your current license and one other proof of identity.","p":"Right. Bring your current license and one more proof of identity."},"es":{"q":"En Nuevo México, ¿qué debe llevar cuando renueva su licencia de manejar?","o":["Su licencia actual y otra prueba de identidad","Solo el título de su carro","Una carta de su médico","Solo la tarjeta del seguro de su carro"],"h1":"Usted muestra la tarjeta vieja y algo más que pruebe quién es.","h2":"En Nuevo México, para renovar su licencia usted lleva su licencia actual y otra prueba de identidad.","p":"Correcto. Lleve su licencia actual y otra prueba de identidad."},"ref":{"doc":"NM","page":2}},{"id":"nm-057","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, you are in a crash and drive away without giving your name. What can happen to your license?","o":["Nothing, if no one was hurt","You only get a warning letter","Your license is renewed early","You can lose your driving privileges"],"h1":"Leaving a crash scene without identifying yourself is a serious offense.","h2":"In New Mexico, leaving the scene of a crash you are in without identifying yourself can cost you your driving privileges.","p":"Right. Leaving a crash without identifying yourself can cost you your license."},"es":{"q":"En Nuevo México, usted tiene un choque y se va sin dar su nombre. ¿Qué le puede pasar a su licencia?","o":["Nada, si nadie resultó herido","Solo recibe una carta de advertencia","Su licencia se renueva antes","Puede perder su privilegio de manejar"],"h1":"Irse del lugar de un choque sin identificarse es una falta grave.","h2":"En Nuevo México, irse del lugar de un choque en el que usted participó sin identificarse puede costarle su privilegio de manejar.","p":"Correcto. Irse de un choque sin identificarse le puede costar la licencia."},"ref":{"doc":"NM","page":2}},{"id":"nm-058","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, the MVD asks you to come in for a re-examination, but you do not go. What can happen?","o":["Nothing; re-exams are optional","You can lose your driving privileges","The MVD will mail you a new license","You get extra points on your next test"],"h1":"When the MVD asks, you must show up.","h2":"In New Mexico, failing to appear for a re-examination that the MVD requests can cost you your driving privileges.","p":"Right. Skipping an MVD re-examination can cost you your license."},"es":{"q":"En Nuevo México, la MVD le pide que se presente a un nuevo examen, pero usted no va. ¿Qué puede pasar?","o":["Nada; los nuevos exámenes son opcionales","Puede perder su privilegio de manejar","La MVD le envía una licencia nueva por correo","Recibe puntos extra en su próximo examen"],"h1":"Cuando la MVD se lo pide, usted debe presentarse.","h2":"En Nuevo México, no presentarse a un nuevo examen que pide la MVD le puede costar su privilegio de manejar.","p":"Correcto. No ir al nuevo examen de la MVD le puede costar la licencia."},"ref":{"doc":"NM","page":2}},{"id":"nm-059","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, a court orders you to pay for damage from a car crash, and you do not pay. What can happen to your license?","o":["Nothing; that is only between you and the other driver","You can lose your driving privileges","Your license gets a gold star","You must only take a vision test"],"h1":"Unpaid crash judgments affect your right to drive.","h2":"In New Mexico, failing to settle a money judgment against you for damage from a motor vehicle crash can cost you your driving privileges.","p":"Right. An unpaid crash judgment can cost you your license."},"es":{"q":"En Nuevo México, una corte le ordena pagar por los daños de un choque de carro, y usted no paga. ¿Qué le puede pasar a su licencia?","o":["Nada; eso es solo entre usted y el otro conductor","Puede perder su privilegio de manejar","Su licencia recibe una estrella dorada","Solo tiene que hacer una prueba de la vista"],"h1":"Las sentencias de choques sin pagar afectan su derecho a manejar.","h2":"En Nuevo México, no pagar una sentencia en su contra por daños de un choque de vehículo le puede costar su privilegio de manejar.","p":"Correcto. Una sentencia de choque sin pagar le puede costar la licencia."},"ref":{"doc":"NM","page":2}},{"id":"nm-060","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, is it legal to drive without wearing your safety belt?","o":["Yes, on roads under 30 mph","Yes, if your car has air bags","Yes, for drivers over 18","No, it is against the law"],"h1":"The law applies on every trip.","h2":"In New Mexico, it is against the law to drive without wearing your safety belt.","p":"Right. Driving without a safety belt is illegal in New Mexico."},"es":{"q":"En Nuevo México, ¿es legal manejar sin el cinturón de seguridad puesto?","o":["Sí, en calles de menos de 30 mph","Sí, si su carro tiene bolsas de aire","Sí, para conductores mayores de 18 años","No, va en contra de la ley"],"h1":"La ley se aplica en cada viaje.","h2":"En Nuevo México, manejar sin el cinturón de seguridad puesto va en contra de la ley.","p":"Correcto. Manejar sin cinturón de seguridad es ilegal en Nuevo México."},"ref":{"doc":"NM","page":3}},{"id":"nm-061","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, what is the minimum insurance for injury to or death of two or more people in one crash?","o":["$25,000","$10,000","$100,000","$50,000"],"h1":"It is double the amount for one person.","h2":"In New Mexico, your insurance must cover at least $50,000 for injury to or death of two or more people in one crash.","p":"Right. The minimum is $50,000 for two or more people."},"es":{"q":"En Nuevo México, ¿cuál es el seguro mínimo por lesiones o muerte de dos o más personas en un mismo choque?","o":["$25,000","$10,000","$100,000","$50,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"En Nuevo México, su seguro debe cubrir al menos $50,000 por lesiones o muerte de dos o más personas en un mismo choque.","p":"Correcto. El mínimo es $50,000 para dos o más personas."},"ref":{"doc":"NM","page":35}},{"id":"nm-062","scope":"NM","cat":"signals","sign":null,"c":2,"en":{"q":"In New Mexico, you see a small, very bright blinking light in the middle of a steady red traffic light. What does it mean?","o":["You may drive through without stopping","The signal is broken, so treat it as green","It alerts you to the red light; you must stop","Only trucks must stop"],"h1":"It is there to make the red light easier to notice.","h2":"In New Mexico, a small bright blinking light inside a red signal is there to alert you to the red light, and you must stop.","p":"Right. The blinking light calls your attention to the red light, so stop."},"es":{"q":"En Nuevo México, usted ve una luz pequeña y muy brillante que parpadea en el centro de una luz roja fija del semáforo. ¿Qué significa?","o":["Puede pasar sin detenerse","El semáforo está dañado, así que trátelo como verde","Le avisa de la luz roja; usted debe detenerse","Solo los camiones deben detenerse"],"h1":"Está ahí para que la luz roja se note más.","h2":"En Nuevo México, una luz pequeña y brillante que parpadea dentro de la luz roja está ahí para avisarle de la luz roja, y usted debe detenerse.","p":"Correcto. La luz que parpadea le llama la atención sobre la luz roja; deténgase."},"ref":{"doc":"NM","page":4}},{"id":"nm-063","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, you are stopped at a red light and it turns green. What must you do before you go?","o":["Go at once, because green means go","Let crossing traffic clear the intersection","Honk to warn crossing cars","Wait for a second green light"],"h1":"Some cars may still be crossing in front of you.","h2":"In New Mexico, when the light turns green while you are stopped, you must let crossing traffic clear the intersection before you go.","p":"Right. Let crossing traffic clear the intersection first."},"es":{"q":"En Nuevo México, usted está detenido en una luz roja y cambia a verde. ¿Qué debe hacer antes de avanzar?","o":["Avanzar de inmediato, porque verde significa avanzar","Dejar que el tráfico que cruza despeje la intersección","Tocar la bocina para avisar a los carros que cruzan","Esperar una segunda luz verde"],"h1":"Puede que algunos carros todavía estén cruzando delante de usted.","h2":"En Nuevo México, cuando la luz cambia a verde mientras usted está detenido, debe dejar que el tráfico que cruza despeje la intersección antes de avanzar.","p":"Correcto. Primero deje que el tráfico que cruza despeje la intersección."},"ref":{"doc":"NM","page":4}},{"id":"nm-064","scope":"NM","cat":"signals","sign":null,"c":0,"en":{"q":"In New Mexico, you are in a turn lane facing a steady red arrow. When may you make the turn?","o":["When the red arrow goes off and a green arrow or green light comes on","After a full stop, if no cars are coming","Right away, if you signal","When the car behind you honks"],"h1":"A steady red arrow does not allow the turn at all.","h2":"In New Mexico, you may not turn on a steady red arrow; you may go when the red arrow goes off and a green arrow or light comes on.","p":"Right. Wait until the red arrow goes off and a green arrow or light shows."},"es":{"q":"En Nuevo México, usted está en un carril para dar vuelta frente a una flecha roja fija. ¿Cuándo puede dar la vuelta?","o":["Cuando la flecha roja se apaga y se enciende una flecha verde o una luz verde","Después de un alto total, si no vienen carros","De inmediato, si pone la direccional","Cuando el carro de atrás toca la bocina"],"h1":"Una flecha roja fija no permite la vuelta en ningún caso.","h2":"En Nuevo México, usted no puede dar vuelta con una flecha roja fija; puede avanzar cuando la flecha roja se apaga y se enciende una flecha o luz verde.","p":"Correcto. Espere a que se apague la flecha roja y aparezca una flecha o luz verde."},"ref":{"doc":"NM","page":4}},{"id":"nm-065","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, you want to turn right at a steady red light. There is no sign about turning. What may you do?","o":["Turn after a full stop, if it is safe","Turn without stopping, if no one is coming","You may never turn on red","Turn only if a police officer waves you on"],"h1":"Stop first, then check for people and cars.","h2":"In New Mexico, you may turn right on a red light after a full stop, if it is safe and no sign forbids it.","p":"Right. Stop fully, then turn right on red if it is safe and allowed."},"es":{"q":"En Nuevo México, usted quiere dar vuelta a la derecha con la luz roja fija. No hay ningún letrero sobre la vuelta. ¿Qué puede hacer?","o":["Dar la vuelta después de un alto total, si es seguro","Dar la vuelta sin detenerse, si no viene nadie","Nunca puede dar vuelta con luz roja","Dar la vuelta solo si un policía le hace señas"],"h1":"Primero deténgase y después fíjese en personas y carros.","h2":"En Nuevo México, usted puede dar vuelta a la derecha con luz roja después de un alto total, si es seguro y ningún letrero lo prohíbe.","p":"Correcto. Haga un alto total y luego dé vuelta a la derecha con luz roja si es seguro y está permitido."},"ref":{"doc":"NM","page":4}},{"id":"nm-066","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, you are on a one-way street at a red light and want to turn left onto another one-way street. What does the manual say?","o":["Left turns on red are never allowed","You may turn after a full stop, unless a sign forbids it","You may turn without stopping","You must wait for a police officer"],"h1":"It works like a right turn on red.","h2":"In New Mexico, you may turn left on red from a one-way street onto another one-way street after a full stop, unless a sign forbids it.","p":"Right. From one one-way street onto another, a left on red is allowed after a stop unless a sign says no."},"es":{"q":"En Nuevo México, usted está en una calle de un solo sentido con luz roja y quiere dar vuelta a la izquierda hacia otra calle de un solo sentido. ¿Qué dice el manual?","o":["Nunca se permite dar vuelta a la izquierda con luz roja","Puede dar la vuelta después de un alto total, salvo que un letrero lo prohíba","Puede dar la vuelta sin detenerse","Debe esperar a un policía"],"h1":"Funciona como una vuelta a la derecha con luz roja.","h2":"En Nuevo México, usted puede dar vuelta a la izquierda con luz roja desde una calle de un solo sentido hacia otra de un solo sentido después de un alto total, salvo que un letrero lo prohíba.","p":"Correcto. De una calle de un solo sentido a otra, se permite la vuelta a la izquierda con luz roja después de detenerse, salvo que un letrero lo prohíba."},"ref":{"doc":"NM","page":16}},{"id":"nm-067","scope":"NM","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Mexico, a school bus driver has stopped before a railroad crossing. What else must the driver do before crossing?","o":["Turn off the engine","Sound the horn three times","Open the bus doors","Turn on the high beams"],"h1":"It helps the driver hear and see a train.","h2":"In New Mexico, a school bus driver must stop before a railroad crossing and open the bus doors before crossing.","p":"Right. The school bus driver opens the doors before crossing the tracks."},"es":{"q":"En Nuevo México, el conductor de un autobús escolar se detuvo antes de un cruce de ferrocarril. ¿Qué más debe hacer antes de cruzar?","o":["Apagar el motor","Tocar la bocina tres veces","Abrir las puertas del autobús","Encender las luces altas"],"h1":"Le ayuda al conductor a oír y ver un tren.","h2":"En Nuevo México, el conductor de un autobús escolar debe detenerse antes de un cruce de ferrocarril y abrir las puertas del autobús antes de cruzar.","p":"Correcto. El conductor del autobús escolar abre las puertas antes de cruzar las vías."},"ref":{"doc":"NM","page":6}},{"id":"nm-068","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, a bell is ringing at a railroad crossing. When may you cross?","o":["As soon as you cannot see a train","While the bell rings, if you drive quickly","After counting to ten","Only after the bell has stopped"],"h1":"The sound means a train is near.","h2":"In New Mexico, you must not cross a railroad crossing until its bell or horn has stopped sounding.","p":"Right. Wait until the bell or horn stops before you cross."},"es":{"q":"En Nuevo México, suena una campana en un cruce de ferrocarril. ¿Cuándo puede cruzar?","o":["En cuanto no vea un tren","Mientras suena la campana, si maneja rápido","Después de contar hasta diez","Solo después de que la campana deja de sonar"],"h1":"El sonido significa que hay un tren cerca.","h2":"En Nuevo México, usted no debe cruzar un cruce de ferrocarril hasta que su campana o bocina deje de sonar.","p":"Correcto. Espere a que la campana o la bocina deje de sonar antes de cruzar."},"ref":{"doc":"NM","page":6}},{"id":"nm-069","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, a highway has a posted minimum speed that feels too fast for you. What should you do?","o":["Use another road","Drive below the minimum on the shoulder","Drive below the minimum with your flashers on","Drive in the left lane"],"h1":"Driving below the minimum makes you a hazard there.","h2":"In New Mexico, if a posted minimum speed is too fast for you, you should use another road.","p":"Right. If the minimum is too fast for you, take another road."},"es":{"q":"En Nuevo México, una carretera tiene una velocidad mínima señalada que a usted le parece demasiado rápida. ¿Qué debe hacer?","o":["Usar otra carretera","Manejar por debajo del mínimo en el acotamiento","Manejar por debajo del mínimo con las luces intermitentes","Manejar en el carril izquierdo"],"h1":"Manejar por debajo del mínimo lo convierte en un peligro allí.","h2":"En Nuevo México, si la velocidad mínima señalada es demasiado rápida para usted, debe usar otra carretera.","p":"Correcto. Si el mínimo es demasiado rápido para usted, tome otra carretera."},"ref":{"doc":"NM","page":7}},{"id":"nm-070","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, there is a solid yellow line on your side of the center line. You want to turn left into a driveway. What may you do?","o":["You may never cross a solid yellow line","Drive to the next intersection and make a U-turn","Cross only if a police officer is there","Cross the line to turn into the driveway, if it is safe"],"h1":"The solid line is about passing, not about turning.","h2":"In New Mexico, you may cross a solid yellow line to turn into a driveway if it is safe.","p":"Right. You may cross a solid yellow line to turn into a driveway when it is safe."},"es":{"q":"En Nuevo México, hay una línea amarilla continua de su lado de la línea central. Usted quiere dar vuelta a la izquierda para entrar a una entrada de casa. ¿Qué puede hacer?","o":["Nunca puede cruzar una línea amarilla continua","Ir a la siguiente intersección y dar una vuelta en U","Cruzar solo si hay un policía","Cruzar la línea para entrar, si es seguro"],"h1":"La línea continua tiene que ver con rebasar, no con dar vuelta.","h2":"En Nuevo México, usted puede cruzar una línea amarilla continua para entrar a una entrada de casa si es seguro.","p":"Correcto. Puede cruzar una línea amarilla continua para entrar a una entrada de casa cuando es seguro."},"ref":{"doc":"NM","page":8}},{"id":"nm-071","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, a flashing yellow X is shown over a reversible lane. What does it mean?","o":["You may drive in the lane for any trip","The lane is only for turning","The lane is closed to all traffic","The lane is for buses only"],"h1":"A flashing yellow X is different from a steady one.","h2":"In New Mexico, a flashing yellow X over a reversible lane means the lane may be used only for turning.","p":"Right. A flashing yellow X means the lane is for turning only."},"es":{"q":"En Nuevo México, sobre un carril reversible se ve una X amarilla intermitente. ¿Qué significa?","o":["Puede manejar en el carril para cualquier viaje","El carril es solo para dar vuelta","El carril está cerrado a todo el tráfico","El carril es solo para autobuses"],"h1":"Una X amarilla intermitente es distinta de una fija.","h2":"En Nuevo México, una X amarilla intermitente sobre un carril reversible significa que el carril solo se puede usar para dar vuelta.","p":"Correcto. Una X amarilla intermitente significa que el carril es solo para dar vuelta."},"ref":{"doc":"NM","page":9}},{"id":"nm-072","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, a lane sign says \"HOV 3\". Who may use that lane?","o":["Vehicles with three axles or more","Vehicles with at least three people in them","Only the driver, alone","Vehicles going under 3 miles"],"h1":"HOV means High Occupancy Vehicle.","h2":"In New Mexico, an \"HOV 3\" sign means there must be at least three people in the vehicle to use that lane.","p":"Right. HOV 3 means at least three people in the vehicle."},"es":{"q":"En Nuevo México, un letrero de carril dice \"HOV 3\". ¿Quién puede usar ese carril?","o":["Vehículos con tres ejes o más","Vehículos con al menos tres personas adentro","Solo el conductor, sin nadie más","Vehículos que van a menos de 3 millas"],"h1":"HOV significa vehículo de alta ocupación.","h2":"En Nuevo México, un letrero \"HOV 3\" significa que debe haber al menos tres personas en el vehículo para usar ese carril.","p":"Correcto. HOV 3 significa al menos tres personas en el vehículo."},"ref":{"doc":"NM","page":9}},{"id":"nm-073","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, when may you back up in a travel lane?","o":["Whenever you miss your exit","When traffic is light","When you signal first","Only to parallel park"],"h1":"It is allowed for one parking move only.","h2":"In New Mexico, you must never back up in a travel lane except to parallel park.","p":"Right. Backing in a travel lane is only for parallel parking."},"es":{"q":"En Nuevo México, ¿cuándo puede manejar en reversa en un carril de circulación?","o":["Siempre que se le pase la salida","Cuando hay poco tráfico","Cuando pone la direccional antes","Solo para estacionarse en paralelo"],"h1":"Se permite solo para una maniobra de estacionamiento.","h2":"En Nuevo México, nunca debe manejar en reversa en un carril de circulación, excepto para estacionarse en paralelo.","p":"Correcto. Ir en reversa en un carril de circulación es solo para estacionarse en paralelo."},"ref":{"doc":"NM","page":10}},{"id":"nm-074","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, you are on a road with three lanes going your way, and many cars are entering and exiting. Which lane should you use?","o":["The center lane","The right lane","The left lane","The shoulder"],"h1":"Stay away from the lane where cars come and go.","h2":"In New Mexico, on a road with three or more lanes going your way and a lot of entering and exiting traffic, you should use the center lane.","p":"Right. With lots of entering and exiting traffic, use the center lane."},"es":{"q":"En Nuevo México, usted va por una calle con tres carriles en su dirección, y muchos carros entran y salen. ¿Qué carril debe usar?","o":["El carril del centro","El carril derecho","El carril izquierdo","El acotamiento"],"h1":"Aléjese del carril donde los carros entran y salen.","h2":"En Nuevo México, en una calle con tres o más carriles en su dirección y mucho tráfico que entra y sale, usted debe usar el carril del centro.","p":"Correcto. Con mucho tráfico que entra y sale, use el carril del centro."},"ref":{"doc":"NM","page":10}},{"id":"nm-075","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, the car ahead stops to turn left. There is a paved shoulder on your right. May you pass on the shoulder?","o":["Yes, if the shoulder is paved","Yes, if you use your turn signal","No, never pass on the shoulder, paved or not","Yes, if you go slowly"],"h1":"Other drivers do not expect anyone there.","h2":"In New Mexico, you must never pass on the shoulder, whether it is paved or not.","p":"Right. Never pass on the shoulder, even a paved one."},"es":{"q":"En Nuevo México, el carro de adelante se detiene para dar vuelta a la izquierda. Hay un acotamiento pavimentado a su derecha. ¿Puede rebasar por el acotamiento?","o":["Sí, si el acotamiento está pavimentado","Sí, si usa la direccional","No, nunca rebase por el acotamiento, esté pavimentado o no","Sí, si va despacio"],"h1":"Los demás conductores no esperan que haya nadie ahí.","h2":"En Nuevo México, usted nunca debe rebasar por el acotamiento, esté pavimentado o no.","p":"Correcto. Nunca rebase por el acotamiento, aunque esté pavimentado."},"ref":{"doc":"NM","page":10}},{"id":"nm-076","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, the White Cane Law protects people who are blind or visually impaired. How might you recognize such a person?","o":["They wear a yellow vest","They wave a red flag","They always walk in the bike lane","They carry a white or metallic cane, or use a guide dog"],"h1":"Think of the law's name and a helpful animal.","h2":"In New Mexico, the White Cane Law covers a blind or visually impaired person who carries a white or metallic cane, with or without a red tip, or who uses a guide dog, and drivers must take every care not to hurt them.","p":"Right. A white or metallic cane, or a guide dog, tells you to take extra care."},"es":{"q":"En Nuevo México, la Ley del Bastón Blanco protege a las personas ciegas o con problemas de la vista. ¿Cómo puede reconocer a esa persona?","o":["Lleva un chaleco amarillo","Agita una bandera roja","Siempre camina por el carril de bicicletas","Lleva un bastón blanco o metálico, o usa un perro guía"],"h1":"Piense en el nombre de la ley y en un animal que ayuda.","h2":"En Nuevo México, la Ley del Bastón Blanco protege a la persona ciega o con problemas de la vista que lleva un bastón blanco o metálico, con o sin punta roja, o que usa un perro guía, y los conductores deben tener todo el cuidado para no lastimarla.","p":"Correcto. Un bastón blanco o metálico, o un perro guía, le indica que tenga mucho cuidado."},"ref":{"doc":"NM","page":11}},{"id":"nm-077","scope":"NM","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Mexico, a person starts crossing the street against a DON'T WALK signal. What must you do?","o":["Keep going, because you have the right-of-way","Honk and drive around them","Yield to the person","Speed up to pass before they reach your lane"],"h1":"The rule about pedestrians has no exception for their mistakes.","h2":"In New Mexico, you must always yield to a pedestrian, even one who is not obeying traffic signals.","p":"Right. Always yield to a pedestrian, even one who breaks the rules."},"es":{"q":"En Nuevo México, una persona empieza a cruzar la calle cuando la señal dice NO CAMINE. ¿Qué debe hacer usted?","o":["Seguir, porque usted tiene el derecho de paso","Tocar la bocina y rodearla","Cederle el paso a la persona","Acelerar para pasar antes de que llegue a su carril"],"h1":"La regla sobre los peatones no tiene excepción por sus errores.","h2":"En Nuevo México, usted siempre debe cederle el paso a un peatón, aunque no esté obedeciendo las señales de tránsito.","p":"Correcto. Siempre ceda el paso a un peatón, aunque no cumpla las reglas."},"ref":{"doc":"NM","page":11}},{"id":"nm-078","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, you and another car stop at a 4-way stop at the same time. The other car is on your right. Who goes first?","o":["You do, because you are on the left","The car on your right","The bigger vehicle","Whoever honks first"],"h1":"Look to your right side.","h2":"In New Mexico, when two vehicles arrive at a 4-way stop at the same time, the vehicle on the right goes first.","p":"Right. At the same time, the car on the right goes first."},"es":{"q":"En Nuevo México, usted y otro carro se detienen en un alto de 4 direcciones al mismo tiempo. El otro carro está a su derecha. ¿Quién avanza primero?","o":["Usted, porque está a la izquierda","El carro a su derecha","El vehículo más grande","El que toque la bocina primero"],"h1":"Mire hacia su lado derecho.","h2":"En Nuevo México, cuando dos vehículos llegan al mismo tiempo a un alto de 4 direcciones, avanza primero el vehículo de la derecha.","p":"Correcto. Si llegan al mismo tiempo, avanza primero el carro de la derecha."},"ref":{"doc":"NM","page":11}},{"id":"nm-079","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, you come to an intersection with no stop sign, yield sign or traffic light. A car is coming from your right. Who should yield?","o":["You should yield to the car on your right","The car on your right should yield to you","Whoever is going faster","Neither; both may go"],"h1":"With no signs or lights, one side always waits.","h2":"In New Mexico, at an intersection with no stop sign, yield sign or signal, you must yield to vehicles coming from your right.","p":"Right. With no signs or lights, yield to the vehicle on your right."},"es":{"q":"En Nuevo México, usted llega a una intersección sin señal de alto, sin señal de ceda el paso y sin semáforo. Viene un carro por su derecha. ¿Quién debe ceder el paso?","o":["Usted debe cederle el paso al carro de su derecha","El carro de su derecha debe cederle el paso a usted","El que vaya más rápido","Ninguno; ambos pueden pasar"],"h1":"Sin señales ni semáforo, un lado siempre espera.","h2":"En Nuevo México, en una intersección sin señal de alto, sin ceda el paso y sin semáforo, usted debe cederle el paso a los vehículos que vienen por su derecha.","p":"Correcto. Sin señales ni semáforo, ceda el paso al vehículo de su derecha."},"ref":{"doc":"NM","page":11}},{"id":"nm-080","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, you are passing a car going the same way, and it starts to slow down. Who must yield?","o":["You, the driver who is passing","The car being passed","Whoever is in the left lane","No one needs to yield"],"h1":"The duty stays with the one who is overtaking.","h2":"In New Mexico, a driver who is passing a vehicle going the same way must yield to it, even if it slows down or stops.","p":"Right. The passing driver must yield, even if the other car slows."},"es":{"q":"En Nuevo México, usted está rebasando a un carro que va en la misma dirección, y ese carro empieza a bajar la velocidad. ¿Quién debe ceder el paso?","o":["Usted, el conductor que está rebasando","El carro al que rebasan","El que esté en el carril izquierdo","Nadie tiene que ceder el paso"],"h1":"La obligación es de quien está rebasando.","h2":"En Nuevo México, el conductor que rebasa a un vehículo que va en la misma dirección debe cederle el paso, aunque ese vehículo baje la velocidad o se detenga.","p":"Correcto. El que rebasa debe ceder el paso, aunque el otro carro baje la velocidad."},"ref":{"doc":"NM","page":12}},{"id":"nm-081","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, you are in the middle of an intersection when you hear an ambulance siren behind you. What should you do?","o":["Stop right where you are in the intersection","Drive through the intersection, then pull over to the right","Back up out of the intersection","Turn left to get out of the way"],"h1":"Do not block the intersection.","h2":"In New Mexico, if you are in an intersection when an emergency vehicle comes, drive through the intersection first and then pull over to the right.","p":"Right. Clear the intersection first, then pull to the right."},"es":{"q":"En Nuevo México, usted está en medio de una intersección cuando oye la sirena de una ambulancia detrás. ¿Qué debe hacer?","o":["Detenerse donde está, en la intersección","Cruzar la intersección y luego orillarse a la derecha","Retroceder para salir de la intersección","Dar vuelta a la izquierda para apartarse"],"h1":"No bloquee la intersección.","h2":"En Nuevo México, si usted está en una intersección cuando llega un vehículo de emergencia, primero cruce la intersección y luego oríllese a la derecha.","p":"Correcto. Primero salga de la intersección y luego oríllese a la derecha."},"ref":{"doc":"NM","page":12}},{"id":"nm-082","scope":"NM","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Mexico, a stopped school bus turns off its flashing red lights. What should you do next?","o":["Drive on at once at normal speed","Honk to tell the children to hurry","Wait until the children have completely left the roadway","Pass the bus on the right"],"h1":"The lights going off does not mean the children are gone.","h2":"In New Mexico, after a school bus turns off its red lights, watch for children and do not go on until they have completely left the roadway.","p":"Right. Wait until the children are completely off the road."},"es":{"q":"En Nuevo México, un autobús escolar detenido apaga sus luces rojas intermitentes. ¿Qué debe hacer usted después?","o":["Avanzar de inmediato a velocidad normal","Tocar la bocina para que los niños se apuren","Esperar a que los niños hayan salido por completo de la calle","Rebasar al autobús por la derecha"],"h1":"Que se apaguen las luces no significa que los niños ya se fueron.","h2":"En Nuevo México, después de que un autobús escolar apaga sus luces rojas, fíjese en los niños y no avance hasta que hayan salido por completo de la calle.","p":"Correcto. Espere a que los niños estén completamente fuera de la calle."},"ref":{"doc":"NM","page":12}},{"id":"nm-083","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you want to park across the street from a fire station driveway. How close to that driveway may you park?","o":["No closer than 20 feet","No closer than 10 feet","No closer than 150 feet","No closer than 75 feet"],"h1":"It is much farther than on the same side of the street.","h2":"In New Mexico, on the side of the street opposite a fire station driveway, you may not park within 75 feet of it.","p":"Right. Across the street from a fire station driveway, stay 75 feet away."},"es":{"q":"En Nuevo México, usted quiere estacionarse al otro lado de la calle de la entrada de una estación de bomberos. ¿Qué tan cerca de esa entrada puede estacionarse?","o":["No más cerca de 20 pies","No más cerca de 10 pies","No más cerca de 150 pies","No más cerca de 75 pies"],"h1":"Es mucho más lejos que en el mismo lado de la calle.","h2":"En Nuevo México, en el lado de la calle opuesto a la entrada de una estación de bomberos, usted no puede estacionarse a menos de 75 pies de ella.","p":"Correcto. Al otro lado de la calle de la entrada de bomberos, quédese a 75 pies."},"ref":{"doc":"NM","page":13}},{"id":"nm-084","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, what does a curb painted white mean?","o":["Parking for people with disabilities only","A fire zone with no stopping","Only short stops are allowed","Free all-day parking"],"h1":"You may stop there, but not for long.","h2":"In New Mexico, a white curb means only short stops are allowed.","p":"Right. A white curb is for short stops only."},"es":{"q":"En Nuevo México, ¿qué significa una banqueta (bordillo) pintada de blanco?","o":["Estacionamiento solo para personas con discapacidad","Una zona de bomberos donde no se puede parar","Solo se permiten paradas cortas","Estacionamiento gratis todo el día"],"h1":"Puede detenerse ahí, pero no por mucho tiempo.","h2":"En Nuevo México, una banqueta (bordillo) blanca significa que solo se permiten paradas cortas.","p":"Correcto. Una banqueta blanca es solo para paradas cortas."},"ref":{"doc":"NM","page":14}},{"id":"nm-085","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, what does a curb painted yellow mean?","o":["A loading zone or some other restriction","Parking for people with disabilities only","Free parking for any length of time","A school bus stop only"],"h1":"Trucks often stop there to deliver goods.","h2":"In New Mexico, a yellow curb marks a loading zone or some other parking restriction.","p":"Right. A yellow curb means a loading zone or another restriction."},"es":{"q":"En Nuevo México, ¿qué significa una banqueta (bordillo) pintada de amarillo?","o":["Una zona de carga o alguna otra restricción","Estacionamiento solo para personas con discapacidad","Estacionamiento gratis por cualquier tiempo","Solo una parada de autobús escolar"],"h1":"Los camiones a menudo se detienen ahí para entregar mercancía.","h2":"En Nuevo México, una banqueta (bordillo) amarilla marca una zona de carga u otra restricción de estacionamiento.","p":"Correcto. Una banqueta amarilla indica una zona de carga u otra restricción."},"ref":{"doc":"NM","page":14}},{"id":"nm-086","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, you are stopped for driving without insurance. How is this violation handled?","o":["It adds 12 points at once","You only get a warning","It is handled by your insurance company only","It carries no points, but you must appear in court"],"h1":"Some violations skip the point system and go to a judge.","h2":"In New Mexico, driving without insurance or registration does not carry points, but you must appear in court, which can lead to more fines or a suspended license.","p":"Right. No points, but you must go to court."},"es":{"q":"En Nuevo México, la policía lo detiene por manejar sin seguro. ¿Cómo se maneja esta infracción?","o":["Suma 12 puntos de una vez","Solo recibe una advertencia","Solo la maneja su compañía de seguros","No lleva puntos, pero usted debe presentarse en la corte"],"h1":"Algunas infracciones no usan el sistema de puntos y van ante un juez.","h2":"En Nuevo México, manejar sin seguro o sin registro no lleva puntos, pero usted debe presentarse en la corte, y eso puede traer más multas o la suspensión de su licencia.","p":"Correcto. No lleva puntos, pero debe ir a la corte."},"ref":{"doc":"NM","page":14}},{"id":"nm-087","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, where must proof of your car insurance be?","o":["At home with your important papers","In the vehicle at all times","Only at the MVD office","Only with your insurance agent"],"h1":"An officer may ask to see it during a traffic stop.","h2":"In New Mexico, proof of liability insurance must be carried in the vehicle at all times.","p":"Right. Keep proof of insurance in the vehicle at all times."},"es":{"q":"En Nuevo México, ¿dónde debe estar la prueba del seguro de su carro?","o":["En casa con sus papeles importantes","En el vehículo en todo momento","Solo en la oficina de la MVD","Solo con su agente de seguros"],"h1":"Un policía puede pedir verla cuando lo detiene.","h2":"En Nuevo México, la prueba del seguro de responsabilidad debe ir en el vehículo en todo momento.","p":"Correcto. Lleve la prueba del seguro en el vehículo en todo momento."},"ref":{"doc":"NM","page":34}},{"id":"nm-088","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, how far ahead do safer drivers look, and about how far is that in the city?","o":["At least 2 seconds, about one car length","At least 10 seconds, about one block","At least 1 minute, about one mile","Only to the bumper of the car ahead"],"h1":"In the city, it is about the distance to the next corner.","h2":"In New Mexico, safer drivers look at least 10 seconds ahead, which is about one block in the city.","p":"Right. Look at least 10 seconds ahead, about one city block."},"es":{"q":"En Nuevo México, ¿qué tan adelante miran los conductores más seguros, y más o menos cuánto es eso en la ciudad?","o":["Al menos 2 segundos, más o menos el largo de un carro","Al menos 10 segundos, más o menos una cuadra","Al menos 1 minuto, más o menos una milla","Solo hasta la defensa del carro de adelante"],"h1":"En la ciudad, es más o menos la distancia hasta la próxima esquina.","h2":"En Nuevo México, los conductores más seguros miran al menos 10 segundos adelante, que en la ciudad es más o menos una cuadra.","p":"Correcto. Mire al menos 10 segundos adelante, más o menos una cuadra."},"ref":{"doc":"NM","page":15}},{"id":"nm-089","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, compared with low beams, how far do high beams let you see?","o":["About the same distance","About half as far","About ten times as far","About twice as far"],"h1":"Think double.","h2":"In New Mexico, high beams let you see about twice as far as low beams.","p":"Right. High beams let you see about twice as far."},"es":{"q":"En Nuevo México, comparadas con las luces bajas, ¿qué tan lejos le permiten ver las luces altas?","o":["Más o menos la misma distancia","Más o menos la mitad","Más o menos diez veces más lejos","Más o menos el doble de lejos"],"h1":"Piense en el doble.","h2":"En Nuevo México, las luces altas le permiten ver más o menos el doble de lejos que las luces bajas.","p":"Correcto. Las luces altas le permiten ver más o menos el doble de lejos."},"ref":{"doc":"NM","page":18}},{"id":"nm-090","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, a driver is found guilty of DWI for the first time. Besides fines, what will the driver be ordered to do?","o":["Get treatment and install an ignition interlock device","Only take a short online quiz","Only buy a new car","Nothing else on a first offense"],"h1":"One part is a device that checks your breath before the car starts.","h2":"In New Mexico, a first DWI conviction brings fines and court costs, and the driver is ordered to get treatment and install an ignition interlock device.","p":"Right. A first DWI means treatment and an ignition interlock device."},"es":{"q":"En Nuevo México, un conductor es declarado culpable de DWI por primera vez. Además de las multas, ¿qué se le ordenará hacer?","o":["Recibir tratamiento e instalar un dispositivo de bloqueo del encendido","Solo hacer un breve cuestionario en línea","Solo comprar un carro nuevo","Nada más en una primera falta"],"h1":"Una parte es un aparato que revisa su aliento antes de que arranque el carro.","h2":"En Nuevo México, una primera condena por DWI trae multas y costos de corte, y al conductor se le ordena recibir tratamiento e instalar un dispositivo de bloqueo del encendido.","p":"Correcto. Un primer DWI significa tratamiento y un dispositivo de bloqueo del encendido."},"ref":{"doc":"NM","page":29}},{"id":"nm-091","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you are driving away from a rising or setting sun. What should you do with your headlights?","o":["Turn them off to save power","Flash your high beams at every car","Turn them on so oncoming drivers can see you","Use only your parking lights"],"h1":"Drivers facing the sun have trouble seeing you.","h2":"In New Mexico, when you drive away from a rising or setting sun, turn on your headlights so drivers coming toward you can see you.","p":"Right. Turn on your headlights so drivers facing the sun can see you."},"es":{"q":"En Nuevo México, usted maneja de espaldas al sol que sale o que se pone. ¿Qué debe hacer con sus faros?","o":["Apagarlos para ahorrar energía","Hacer cambio de luces altas a cada carro","Encenderlos para que los conductores que vienen de frente lo vean","Usar solo las luces de estacionamiento"],"h1":"Los conductores que miran hacia el sol tienen dificultad para verlo.","h2":"En Nuevo México, cuando maneja de espaldas al sol que sale o que se pone, encienda sus faros para que los conductores que vienen de frente lo vean.","p":"Correcto. Encienda los faros para que los conductores que miran hacia el sol lo vean."},"ref":{"doc":"NM","page":18}},{"id":"nm-092","scope":"NM","cat":"signals","sign":null,"c":3,"en":{"q":"In New Mexico, you plan to turn right just past a driveway, and a car is about to pull out of that driveway. When should you signal?","o":["Before you reach the driveway","Never; skip the signal","Only after you finish the turn","After you pass the driveway"],"h1":"An early signal might make that driver think you are turning into the driveway.","h2":"In New Mexico, if a car is about to enter the street between you and your turn, wait until you have passed it before you signal.","p":"Right. Pass the waiting car first, then signal your turn."},"es":{"q":"En Nuevo México, usted piensa dar vuelta a la derecha justo después de una entrada de casa, y un carro está por salir de esa entrada. ¿Cuándo debe poner la direccional?","o":["Antes de llegar a esa entrada","Nunca; no use la direccional","Solo después de terminar la vuelta","Después de pasar esa entrada"],"h1":"Una direccional temprana puede hacer creer a ese conductor que usted va a entrar ahí.","h2":"En Nuevo México, si un carro está por entrar a la calle entre usted y el lugar donde va a dar vuelta, espere a pasarlo antes de poner la direccional.","p":"Correcto. Primero pase el carro que espera y luego ponga la direccional."},"ref":{"doc":"NM","page":19}},{"id":"nm-093","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, the road is wet from rain. About how much should you reduce your speed?","o":["About 1 mph","By half","About 10 mph","You do not need to slow down"],"h1":"Packed snow needs half; a wet road needs less.","h2":"In New Mexico, on a wet road you should reduce your speed by about 10 mph.","p":"Right. On a wet road, slow down about 10 mph."},"es":{"q":"En Nuevo México, la calle está mojada por la lluvia. ¿Más o menos cuánto debe bajar su velocidad?","o":["Unas 1 mph","A la mitad","Unas 10 mph","No necesita bajar la velocidad"],"h1":"La nieve compacta pide la mitad; una calle mojada pide menos.","h2":"En Nuevo México, en una calle mojada usted debe bajar su velocidad unas 10 mph.","p":"Correcto. En una calle mojada, baje unas 10 mph."},"ref":{"doc":"NM","page":20}},{"id":"nm-094","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, on a wet road, up to about what speed do most tires keep good traction?","o":["About 15 mph","About 35 mph","About 55 mph","About 75 mph"],"h1":"Above this speed, tires can start to ride up on the water.","h2":"In New Mexico, most tires have good traction on a wet road up to about 35 mph; faster than that, they can start to hydroplane.","p":"Right. Most tires grip well on a wet road up to about 35 mph."},"es":{"q":"En Nuevo México, en una calle mojada, ¿hasta más o menos qué velocidad mantienen buena tracción la mayoría de las llantas?","o":["Unas 15 mph","Unas 35 mph","Unas 55 mph","Unas 75 mph"],"h1":"A más velocidad, las llantas pueden empezar a subirse sobre el agua.","h2":"En Nuevo México, la mayoría de las llantas tienen buena tracción en una calle mojada hasta unas 35 mph; más rápido, pueden empezar a hidroplanear.","p":"Correcto. La mayoría de las llantas agarran bien en calle mojada hasta unas 35 mph."},"ref":{"doc":"NM","page":20}},{"id":"nm-095","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, at which times are many wild animals most active near roads?","o":["Dawn, dusk and the first few hours after dark","Noon on sunny days","Only in the middle of winter","Only during rush hour"],"h1":"Think of when the light is low.","h2":"In New Mexico, be especially watchful for wildlife at dawn, at dusk and in the first few hours after dark, when many animals are most active.","p":"Right. Watch for wildlife at dawn, dusk and early in the night."},"es":{"q":"En Nuevo México, ¿a qué horas están más activos muchos animales salvajes cerca de las carreteras?","o":["Al amanecer, al atardecer y en las primeras horas después de oscurecer","Al mediodía en días soleados","Solo a mitad del invierno","Solo en las horas pico"],"h1":"Piense en cuando hay poca luz.","h2":"En Nuevo México, esté muy atento a los animales salvajes al amanecer, al atardecer y en las primeras horas después de oscurecer, cuando muchos animales están más activos.","p":"Correcto. Esté atento a los animales al amanecer, al atardecer y al principio de la noche."},"ref":{"doc":"NM","page":21}},{"id":"nm-096","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, on dry pavement with good tires and brakes, about how far can it take to react and stop from 50 mph?","o":["About 50 feet, about three car lengths","About 400 feet, about one city block","About 100 feet","About one mile"],"h1":"It is about the length of a city block.","h2":"In New Mexico, at 50 mph it can take about 400 feet to react and stop, about the length of a city block.","p":"Right. From 50 mph, it can take about 400 feet to stop."},"es":{"q":"En Nuevo México, en pavimento seco con buenas llantas y frenos, ¿más o menos cuánta distancia se puede necesitar para reaccionar y detenerse desde 50 mph?","o":["Unos 50 pies, más o menos tres largos de carro","Unos 400 pies, más o menos una cuadra de ciudad","Unos 100 pies","Más o menos una milla"],"h1":"Es más o menos el largo de una cuadra de ciudad.","h2":"En Nuevo México, a 50 mph se pueden necesitar unos 400 pies para reaccionar y detenerse, más o menos el largo de una cuadra de ciudad.","p":"Correcto. Desde 50 mph se pueden necesitar unos 400 pies para detenerse."},"ref":{"doc":"NM","page":22}},{"id":"nm-097","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, what is the youngest age to get a provisional license, if you have held your instruction permit for 6 months?","o":["15 years and 6 months","15 years","16 years and 6 months","17 years"],"h1":"Add the 6-month permit time to the youngest permit age.","h2":"In New Mexico, the youngest age for a provisional license is 15 years and 6 months, after holding a permit for 6 months.","p":"Right. You can get a provisional license at 15 and a half."},"es":{"q":"En Nuevo México, ¿cuál es la edad mínima para obtener una licencia provisional, si ha tenido su permiso de aprendizaje por 6 meses?","o":["15 años y 6 meses","15 años","16 años y 6 meses","17 años"],"h1":"Sume los 6 meses del permiso a la edad mínima del permiso.","h2":"En Nuevo México, la edad mínima para una licencia provisional es 15 años y 6 meses, después de tener el permiso por 6 meses.","p":"Correcto. Puede obtener la licencia provisional a los 15 años y medio."},"ref":{"doc":"NM","page":1}},{"id":"nm-098","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, you have an instruction permit. Besides a licensed driver 21 or older, who may sit beside you while you drive?","o":["Any friend who is 18","An approved driving instructor","A brother or sister with a permit","No one; you may drive alone"],"h1":"Think of the person who teaches driver education.","h2":"In New Mexico, a permit holder may drive with an approved driving instructor in the seat beside them, or with a licensed driver 21 or older.","p":"Right. An approved instructor may sit beside you."},"es":{"q":"En Nuevo México, usted tiene un permiso de aprendizaje. Además de un conductor con licencia de 21 años o más, ¿quién puede ir sentado a su lado mientras maneja?","o":["Cualquier amigo de 18 años","Un instructor de manejo aprobado","Un hermano o hermana con permiso","Nadie; puede manejar solo"],"h1":"Piense en la persona que enseña la clase de manejo.","h2":"En Nuevo México, quien tiene permiso puede manejar con un instructor de manejo aprobado en el asiento de al lado, o con un conductor con licencia de 21 años o más.","p":"Correcto. Un instructor aprobado puede ir a su lado."},"ref":{"doc":"NM","page":1}},{"id":"nm-099","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, a provisional driver must drive home from a religious activity after midnight. Who may sign the statement that allows this?","o":["Only a police officer","Only an MVD employee","A religious official, or a parent or guardian","No one; this is never allowed"],"h1":"The same kind of statement works for school activities.","h2":"In New Mexico, a provisional driver may drive to and from a religious activity after midnight with a signed statement from a religious official or a parent or guardian.","p":"Right. A religious official or a parent or guardian may sign it."},"es":{"q":"En Nuevo México, un conductor con licencia provisional debe volver a casa de una actividad religiosa después de la medianoche. ¿Quién puede firmar la declaración que lo permite?","o":["Solo un policía","Solo un empleado de la MVD","Un líder religioso, o un padre, madre o tutor","Nadie; nunca se permite"],"h1":"El mismo tipo de declaración sirve para actividades de la escuela.","h2":"En Nuevo México, un conductor con licencia provisional puede manejar a una actividad religiosa y de regreso después de la medianoche con una declaración firmada por un líder religioso o por un padre, madre o tutor.","p":"Correcto. Lo puede firmar un líder religioso o un padre, madre o tutor."},"ref":{"doc":"NM","page":2}},{"id":"nm-100","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, a provisional driver must drive after midnight because of a family need. What is needed for this to be allowed?","o":["A note from a friend","A call to the police first","Nothing; family needs are never allowed","A signed statement from a parent or guardian"],"h1":"Think of who is responsible for a teen driver.","h2":"In New Mexico, a provisional driver may drive after midnight for a family need with a signed statement from a parent or guardian.","p":"Right. A parent or guardian must sign a statement."},"es":{"q":"En Nuevo México, un conductor con licencia provisional debe manejar después de la medianoche por una necesidad de la familia. ¿Qué se necesita para que se permita?","o":["Una nota de un amigo","Llamar primero a la policía","Nada; nunca se permite por la familia","Una declaración firmada por un padre, madre o tutor"],"h1":"Piense en quién es responsable de un conductor joven.","h2":"En Nuevo México, un conductor con licencia provisional puede manejar después de la medianoche por una necesidad de la familia con una declaración firmada por un padre, madre o tutor.","p":"Correcto. Un padre, madre o tutor debe firmar una declaración."},"ref":{"doc":"NM","page":2}},{"id":"nm-101","scope":"NM","cat":"licensing","sign":null,"c":0,"en":{"q":"In New Mexico, which of these can cost you your driving privileges?","o":["Giving false information when you apply for a license","Renewing your license 60 days early","Driving 70 mph on a rural interstate posted at 75 mph","Taking the written test in Spanish"],"h1":"Look for the dishonest choice.","h2":"In New Mexico, you can lose your driving privileges for giving false information when you apply for a driver license.","p":"Right. False information on your application can cost you your license."},"es":{"q":"En Nuevo México, ¿cuál de estas cosas le puede quitar el privilegio de manejar?","o":["Dar información falsa al solicitar la licencia","Renovar su licencia 60 días antes","Manejar a 70 mph en una interestatal rural con límite de 75 mph","Tomar el examen escrito en español"],"h1":"Busque la opción deshonesta.","h2":"En Nuevo México, puede perder el privilegio de manejar por dar información falsa al solicitar la licencia de conducir.","p":"Correcto. Dar información falsa en la solicitud le puede costar la licencia."},"ref":{"doc":"NM","page":2}},{"id":"nm-102","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, you are 19 and use a friend's driver license to try to buy beer. What can happen to your own license?","o":["Nothing, because you were not driving","You can lose your driving privileges","You only get a warning letter","Your license is renewed early"],"h1":"Misusing a license is treated seriously, even away from the road.","h2":"In New Mexico, using someone else's license, or changing yours, to buy alcohol can cost you your driving privileges.","p":"Right. You can lose your license for this."},"es":{"q":"En Nuevo México, usted tiene 19 años y usa la licencia de un amigo para intentar comprar cerveza. ¿Qué le puede pasar a su propia licencia?","o":["Nada, porque no estaba manejando","Puede perder el privilegio de manejar","Solo recibe una carta de advertencia","Le renuevan la licencia antes"],"h1":"Usar mal una licencia es algo serio, aunque no esté en la calle.","h2":"En Nuevo México, usar la licencia de otra persona, o cambiar la suya, para comprar alcohol le puede quitar el privilegio de manejar.","p":"Correcto. Puede perder su licencia por esto."},"ref":{"doc":"NM","page":2}},{"id":"nm-103","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, your car has a separate lap belt and shoulder belt. What should you wear?","o":["Only the lap belt","Only the shoulder belt","Both the lap belt and the shoulder belt","Either one; they protect the same"],"h1":"Wearing only one part reduces your protection.","h2":"In New Mexico, with a two-part safety belt you should wear both the lap belt and the shoulder belt, because either part alone protects you less.","p":"Right. Wear both parts of the belt."},"es":{"q":"En Nuevo México, su carro tiene un cinturón de cadera y un cinturón de hombro separados. ¿Cuál debe usar?","o":["Solo el de cadera","Solo el de hombro","Los dos: el de cadera y el de hombro","Cualquiera de los dos; protegen igual"],"h1":"Usar solo una parte le protege menos.","h2":"En Nuevo México, con un cinturón de dos partes usted debe usar el de cadera y el de hombro, porque una sola parte le protege menos.","p":"Correcto. Use las dos partes del cinturón."},"ref":{"doc":"NM","page":3}},{"id":"nm-104","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, you drive a car with a manual shift. What does the manual advise as you cross railroad tracks?","o":["Shift into neutral and coast","Shift to a higher gear in the middle","Stop on the tracks to change gears","Do not shift gears while crossing"],"h1":"Think about what could happen if the engine stalls.","h2":"In New Mexico, it is wise not to shift gears while crossing railroad tracks, in case the engine stalls.","p":"Right. Do not change gears on the tracks."},"es":{"q":"En Nuevo México, usted maneja un carro de cambios manuales. ¿Qué aconseja el manual al cruzar las vías del tren?","o":["Poner neutral y dejarse llevar","Subir a una velocidad más alta en medio de las vías","Parar sobre las vías para cambiar de velocidad","No cambiar de velocidad mientras cruza"],"h1":"Piense en lo que pasa si el motor se apaga.","h2":"En Nuevo México, es prudente no cambiar de velocidad al cruzar las vías del tren, por si el motor se apaga.","p":"Correcto. No cambie de velocidad sobre las vías."},"ref":{"doc":"NM","page":5}},{"id":"nm-105","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, you need to let a passenger out of your car on a busy street. What should you do?","o":["Stop in the travel lane for a few seconds","Keep going until you can safely pull off the road","Stop in the lane with your hazard lights on","Back up to a better spot"],"h1":"Other drivers do not expect a car to stop in a travel lane.","h2":"In New Mexico, you should not stop in a travel lane for any reason, such as letting out a passenger; keep moving until you can safely pull off the road.","p":"Right. Do not stop in a travel lane; pull off safely first."},"es":{"q":"En Nuevo México, necesita dejar bajar a un pasajero en una calle con mucho tráfico. ¿Qué debe hacer?","o":["Pararse en el carril unos segundos","Seguir hasta que pueda salirse de la calle con seguridad","Pararse en el carril con las luces intermitentes","Retroceder hasta un mejor lugar"],"h1":"Los otros conductores no esperan que un carro se pare en un carril de circulación.","h2":"En Nuevo México, no debe pararse en un carril de circulación por ninguna razón, como dejar bajar a un pasajero; siga hasta que pueda salirse de la calle con seguridad.","p":"Correcto. No se pare en el carril; primero sálgase con seguridad."},"ref":{"doc":"NM","page":10}},{"id":"nm-106","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, you turn right from a road with two lanes onto a street with two lanes going your way. There are no signs or markings. Which lane should you turn into?","o":["The left lane","Either lane, then change later","The lane closest to the one you came from: the right lane","The lane with the least traffic"],"h1":"Turning this way means you cross the fewest lanes.","h2":"In New Mexico, with no signs or markings, you turn into the lane closest to the one you came from; for a right turn, that is the right lane.","p":"Right. Turn into the closest lane, then change lanes later if needed."},"es":{"q":"En Nuevo México, usted gira a la derecha desde una calle de dos carriles hacia otra con dos carriles en su dirección. No hay señales ni marcas. ¿A qué carril debe entrar?","o":["Al carril izquierdo","A cualquiera, y cambia después","Al carril más cercano al que venía: el carril derecho","Al carril con menos tráfico"],"h1":"Así cruza la menor cantidad de carriles.","h2":"En Nuevo México, sin señales ni marcas, usted entra al carril más cercano al que venía; en un giro a la derecha, es el carril derecho.","p":"Correcto. Entre al carril más cercano y, si hace falta, cambie después."},"ref":{"doc":"NM","page":10}},{"id":"nm-107","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, when may you drive on a sidewalk?","o":["When traffic in the street is stopped","When no one is walking on it","To pass a car that is turning","Only to cross it, such as entering or leaving a driveway"],"h1":"A sidewalk is for people on foot.","h2":"In New Mexico, it is illegal to drive on a sidewalk except to cross it, and you must yield to people walking there.","p":"Right. You may only cross a sidewalk, never drive along it."},"es":{"q":"En Nuevo México, ¿cuándo puede manejar sobre una acera?","o":["Cuando el tráfico de la calle está parado","Cuando nadie camina por ella","Para pasar a un carro que está girando","Solo para cruzarla, como al entrar o salir de una entrada de carros"],"h1":"La acera es para la gente a pie.","h2":"En Nuevo México, es ilegal manejar sobre una acera excepto para cruzarla, y debe ceder el paso a la gente que camina por ella.","p":"Correcto. Solo puede cruzar la acera, nunca manejar a lo largo de ella."},"ref":{"doc":"NM","page":11}},{"id":"nm-108","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, a police car with flashing lights pulls up behind you, and the officer gives instructions over the loudspeaker. What should you do?","o":["Follow the instructions","Ignore them and keep driving","Stop in the middle of your lane and wait","Speed up to get out of the way"],"h1":"The driver of the emergency vehicle can see what you cannot.","h2":"In New Mexico, you must pull over to the right for an emergency vehicle and follow any instructions given over its loudspeaker.","p":"Right. Follow the loudspeaker instructions."},"es":{"q":"En Nuevo México, un carro de policía con luces intermitentes se acerca por detrás y el oficial da instrucciones por el altavoz. ¿Qué debe hacer?","o":["Seguir las instrucciones","Ignorarlas y seguir manejando","Pararse en medio de su carril y esperar","Acelerar para quitarse del camino"],"h1":"El conductor del vehículo de emergencia puede ver lo que usted no ve.","h2":"En Nuevo México, debe orillarse a la derecha para un vehículo de emergencia y seguir las instrucciones que se den por su altavoz.","p":"Correcto. Siga las instrucciones del altavoz."},"ref":{"doc":"NM","page":12}},{"id":"nm-109","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, you park a car with a manual transmission. Besides setting the parking brake, what should you do?","o":["Leave it in neutral","Leave it in gear","Leave the engine running","Leave the keys inside"],"h1":"An automatic goes in \"park\"; a manual needs something similar.","h2":"In New Mexico, when you park a car with a manual transmission, set the parking brake and leave it in gear.","p":"Right. Leave a manual car in gear when you park."},"es":{"q":"En Nuevo México, usted estaciona un carro de cambios manuales. Además de poner el freno de mano, ¿qué debe hacer?","o":["Dejarlo en neutral","Dejarlo en una velocidad (en cambio)","Dejar el motor encendido","Dejar las llaves adentro"],"h1":"Un automático va en \"park\"; un manual necesita algo parecido.","h2":"En Nuevo México, al estacionar un carro de cambios manuales, ponga el freno de mano y déjelo en una velocidad.","p":"Correcto. Deje un carro manual en una velocidad al estacionarlo."},"ref":{"doc":"NM","page":13}},{"id":"nm-110","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, in which of these places is parking not allowed?","o":["In a marked space in a parking lot","Next to a curb 12 inches away","On a bridge, an overpass or in a tunnel","40 feet from a stop sign"],"h1":"Think of places where a stopped car blocks a narrow road with no way around.","h2":"In New Mexico, you may not park on a bridge or overpass, or in a tunnel or underpass.","p":"Right. Never park on a bridge, overpass or in a tunnel."},"es":{"q":"En Nuevo México, ¿en cuál de estos lugares no se permite estacionarse?","o":["En un espacio marcado de un estacionamiento","Junto a la acera, a 12 pulgadas","En un puente, un paso elevado o un túnel","A 40 pies de una señal de alto"],"h1":"Piense en lugares donde un carro parado bloquea una vía angosta sin salida.","h2":"En Nuevo México, no puede estacionarse en un puente o paso elevado, ni en un túnel o paso a desnivel.","p":"Correcto. Nunca se estacione en un puente, paso elevado o túnel."},"ref":{"doc":"NM","page":13}},{"id":"nm-111","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, what does a curb painted blue mean?","o":["A loading zone","A fire zone","Short stops only","Parking for people with disabilities only"],"h1":"Think of the color of the wheelchair parking sign.","h2":"In New Mexico, a blue curb means the space is for handicap (disability) parking only.","p":"Right. A blue curb is for disability parking only."},"es":{"q":"En Nuevo México, ¿qué significa una acera pintada de azul?","o":["Una zona de carga","Una zona de bomberos","Solo paradas cortas","Estacionamiento solo para personas con discapacidad"],"h1":"Piense en el color del letrero de estacionamiento con silla de ruedas.","h2":"En Nuevo México, una acera azul significa que el espacio es solo para estacionamiento de personas con discapacidad.","p":"Correcto. La acera azul es solo para personas con discapacidad."},"ref":{"doc":"NM","page":14}},{"id":"nm-112","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, how should you turn the steering wheel for a sharp corner?","o":["Use the hand-over-hand method","Turn it with one finger","Let it slide through your hands","Hold it at the bottom with one hand"],"h1":"Your hands cross over each other as you turn.","h2":"In New Mexico, you should use the hand-over-hand method for sharp corners, and then straighten the wheel by hand instead of letting it slip through your fingers.","p":"Right. Use hand-over-hand for sharp turns."},"es":{"q":"En Nuevo México, ¿cómo debe girar el volante en una esquina cerrada?","o":["Con el método de mano sobre mano","Con un solo dedo","Dejándolo resbalar entre las manos","Sujetándolo abajo con una mano"],"h1":"Sus manos se cruzan una sobre la otra al girar.","h2":"En Nuevo México, debe usar el método de mano sobre mano en las esquinas cerradas y después enderezar el volante con las manos, sin dejarlo resbalar entre los dedos.","p":"Correcto. Use mano sobre mano en giros cerrados."},"ref":{"doc":"NM","page":15}},{"id":"nm-113","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, when are drivers on the cross street most likely to hurry through an intersection against the light?","o":["When your light has been green for a long time","Just after your light has turned green","Only late at night","Only when there is a stop sign"],"h1":"They are trying to beat the change to red.","h2":"In New Mexico, look left and right just after your light turns green, because that is when drivers on the cross street are most likely to rush through before their light turns red.","p":"Right. Look both ways right after your light turns green."},"es":{"q":"En Nuevo México, ¿cuándo es más probable que los conductores de la calle que cruza pasen rápido la intersección contra la luz?","o":["Cuando su luz lleva mucho tiempo en verde","Justo después de que su luz cambia a verde","Solo tarde en la noche","Solo cuando hay una señal de alto"],"h1":"Tratan de pasar antes de que su luz cambie a rojo.","h2":"En Nuevo México, mire a la izquierda y a la derecha justo después de que su luz cambia a verde, porque es cuando los conductores de la calle que cruza tienen más probabilidad de pasar rápido antes de que su luz cambie a rojo.","p":"Correcto. Mire a los dos lados justo después de que su luz cambia a verde."},"ref":{"doc":"NM","page":16}},{"id":"nm-114","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, when may you drive with only your parking lights on?","o":["At dusk","In light rain","Never; parking lights are for parking only","In a city with street lights"],"h1":"The name of these lights tells you what they are for.","h2":"In New Mexico, you should never drive with only your parking lights on; they are for parked vehicles only.","p":"Right. Never drive with only parking lights."},"es":{"q":"En Nuevo México, ¿cuándo puede manejar solo con las luces de estacionamiento encendidas?","o":["Al atardecer","Con lluvia ligera","Nunca; son solo para estacionar","En una ciudad con alumbrado público"],"h1":"El nombre de estas luces dice para qué son.","h2":"En Nuevo México, nunca debe manejar solo con las luces de estacionamiento encendidas; son solo para vehículos estacionados.","p":"Correcto. Nunca maneje solo con luces de estacionamiento."},"ref":{"doc":"NM","page":18}},{"id":"nm-115","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, it starts to rain and you turn on your windshield wipers. What else does the manual say to turn on?","o":["Your hazard lights","Your high beams","Your parking lights only","Your headlights"],"h1":"Other drivers need to see your car in the rain.","h2":"In New Mexico, the manual says that if you turn on your wipers, you should turn on your headlights too.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Nuevo México, empieza a llover y usted enciende los limpiaparabrisas. ¿Qué más dice el manual que encienda?","o":["Las luces intermitentes de emergencia","Las luces altas","Solo las luces de estacionamiento","Las luces delanteras (faros)"],"h1":"Los otros conductores necesitan ver su carro con la lluvia.","h2":"En Nuevo México, el manual dice que si enciende los limpiaparabrisas, también debe encender las luces delanteras.","p":"Correcto. Limpiaparabrisas encendidos, luces encendidas."},"ref":{"doc":"NM","page":18}},{"id":"nm-116","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, a child is about to run into the street in front of you. How should you use your horn?","o":["Give a sharp blast","Give a light tap","Do not use the horn at all","Honk only after the child is in the street"],"h1":"This is real danger, not just a reminder.","h2":"In New Mexico, when there is danger, such as a child about to run into the street, you should give a sharp blast on your horn.","p":"Right. In danger, use a sharp blast."},"es":{"q":"En Nuevo México, un niño está a punto de correr a la calle frente a usted. ¿Cómo debe usar la bocina?","o":["Dar un bocinazo fuerte","Dar un toque suave","No usar la bocina","Tocarla solo cuando el niño ya esté en la calle"],"h1":"Esto es un peligro real, no solo un aviso.","h2":"En Nuevo México, cuando hay peligro, como un niño a punto de correr a la calle, debe dar un bocinazo fuerte.","p":"Correcto. En peligro, dé un bocinazo fuerte."},"ref":{"doc":"NM","page":19}},{"id":"nm-117","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, your car has trouble and you cannot get it off the road. Where should you try to stop?","o":["Just over the top of a hill","Where other drivers have a clear view of your car","Just around a curve","In the middle of an intersection"],"h1":"Other drivers must see your car in time to stop or change lanes.","h2":"In New Mexico, if you cannot get off the road, stop where other drivers can clearly see your car, not just over a hill or just around a curve.","p":"Right. Stop where others can see you clearly."},"es":{"q":"En Nuevo México, su carro tiene un problema y no puede sacarlo de la calle. ¿Dónde debe tratar de pararse?","o":["Justo pasando la cima de una loma","Donde los otros conductores vean bien su carro","Justo después de una curva","En medio de una intersección"],"h1":"Los otros conductores deben ver su carro a tiempo para parar o cambiar de carril.","h2":"En Nuevo México, si no puede salirse de la calle, pare donde los otros conductores vean bien su carro, no justo pasando una loma ni justo después de una curva.","p":"Correcto. Pare donde los demás le vean bien."},"ref":{"doc":"NM","page":19}},{"id":"nm-118","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, in a heavy rain, at about what speed can your tires lose all traction with the road?","o":["About 20 mph","About 35 mph","About 50 mph","About 80 mph"],"h1":"It is faster than the speed at which tires start to ride up on water.","h2":"In New Mexico, in a heavy rain your tires can lose all traction with the road at about 50 mph.","p":"Right. In heavy rain, tires can lose all grip at about 50 mph."},"es":{"q":"En Nuevo México, con lluvia fuerte, ¿más o menos a qué velocidad pueden perder sus llantas todo el agarre con la calle?","o":["Unas 20 mph","Unas 35 mph","Unas 50 mph","Unas 80 mph"],"h1":"Es más rápido que la velocidad a la que las llantas empiezan a subirse sobre el agua.","h2":"En Nuevo México, con lluvia fuerte sus llantas pueden perder todo el agarre con la calle a unas 50 mph.","p":"Correcto. Con lluvia fuerte, las llantas pueden perder todo el agarre a unas 50 mph."},"ref":{"doc":"NM","page":20}},{"id":"nm-119","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, in thick fog you cannot see more than about 200 feet ahead. What is the fastest you can safely drive?","o":["30 mph","45 mph","55 mph","65 mph"],"h1":"You must be able to stop within the distance you can see.","h2":"In New Mexico, when you cannot see farther than about 200 feet in rain, fog or snow, you cannot safely drive faster than 30 mph.","p":"Right. With only 200 feet of view, drive no faster than 30 mph."},"es":{"q":"En Nuevo México, con neblina espesa usted no puede ver más de unos 200 pies adelante. ¿Cuál es la velocidad máxima segura?","o":["30 mph","45 mph","55 mph","65 mph"],"h1":"Debe poder detenerse dentro de la distancia que puede ver.","h2":"En Nuevo México, cuando no puede ver más allá de unos 200 pies con lluvia, neblina o nieve, no puede manejar con seguridad a más de 30 mph.","p":"Correcto. Con solo 200 pies de vista, no pase de 30 mph."},"ref":{"doc":"NM","page":23}},{"id":"nm-120","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, you pick an object as far ahead as you can see clearly and start counting. You reach it before you finish counting \"four-one-thousand\". What does it mean?","o":["You are driving at a safe speed","You are going too fast for your sight distance","You should speed up","You are following too far behind"],"h1":"This is the Four Second Sight Distance Rule.","h2":"In New Mexico, under the Four Second Sight Distance Rule, if you reach the object before you count to four seconds, you are going too fast for how far you can see and must slow down.","p":"Right. You need to slow down."},"es":{"q":"En Nuevo México, usted escoge un objeto lo más adelante que puede ver con claridad y empieza a contar. Llega a él antes de terminar de contar \"cuatro-mil\". ¿Qué significa?","o":["Va a una velocidad segura","Va demasiado rápido para la distancia que puede ver","Debe acelerar","Va demasiado lejos del carro de adelante"],"h1":"Es la regla de cuatro segundos de distancia visual.","h2":"En Nuevo México, según la regla de cuatro segundos de distancia visual, si llega al objeto antes de contar cuatro segundos, va demasiado rápido para lo que puede ver y debe bajar la velocidad.","p":"Correcto. Necesita bajar la velocidad."},"ref":{"doc":"NM","page":23}},{"id":"nm-121","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, what is the following-distance rule in the manual for normal conditions?","o":["At least one second","One car length for each 20 mph","At least three seconds behind the vehicle ahead","At least ten seconds"],"h1":"Count \"one-thousand-one\" from a fixed point.","h2":"In New Mexico, the manual uses the three-second rule: stay at least three seconds behind the vehicle ahead, at any speed.","p":"Right. Follow at least three seconds behind."},"es":{"q":"En Nuevo México, ¿cuál es la regla de distancia de seguimiento del manual en condiciones normales?","o":["Por lo menos un segundo","Un largo de carro por cada 20 mph","Por lo menos tres segundos detrás del vehículo de adelante","Por lo menos diez segundos"],"h1":"Cuente \"mil uno\" desde un punto fijo.","h2":"En Nuevo México, el manual usa la regla de tres segundos: quédese por lo menos tres segundos detrás del vehículo de adelante, a cualquier velocidad.","p":"Correcto. Vaya por lo menos tres segundos detrás."},"ref":{"doc":"NM","page":23}},{"id":"nm-122","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you are following a motorcycle. What following distance does the manual suggest?","o":["Two seconds","One second","Half a second","Four seconds"],"h1":"Following a motorcycle is one of the times you need more space than usual.","h2":"In New Mexico, you may need a four-second following distance when following a motorcycle, as well as on slippery roads, when pulling a trailer, or near railroad crossings.","p":"Right. Leave four seconds behind a motorcycle."},"es":{"q":"En Nuevo México, usted va detrás de una motocicleta. ¿Qué distancia de seguimiento sugiere el manual?","o":["Dos segundos","Un segundo","Medio segundo","Cuatro segundos"],"h1":"Seguir a una motocicleta es una de las veces en que necesita más espacio de lo normal.","h2":"En Nuevo México, puede necesitar cuatro segundos de distancia al seguir a una motocicleta, y también en calles resbalosas, al jalar un remolque o cerca de cruces de tren.","p":"Correcto. Deje cuatro segundos detrás de una motocicleta."},"ref":{"doc":"NM","page":24}},{"id":"nm-123","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, about how big a gap in traffic do you need to merge or change lanes?","o":["About four seconds","About one second","About two car lengths","About ten seconds"],"h1":"In the middle of the gap, you and the car behind each get two seconds.","h2":"In New Mexico, you need a gap of about four seconds to merge, change lanes or enter a roadway.","p":"Right. Look for a gap of about four seconds."},"es":{"q":"En Nuevo México, ¿más o menos de qué tamaño debe ser el espacio en el tráfico para incorporarse o cambiar de carril?","o":["Unos cuatro segundos","Un segundo","Dos largos de carro","Unos diez segundos"],"h1":"En medio del espacio, usted y el carro de atrás quedan con dos segundos cada uno.","h2":"En Nuevo México, necesita un espacio de unos cuatro segundos para incorporarse, cambiar de carril o entrar a una carretera.","p":"Correcto. Busque un espacio de unos cuatro segundos."},"ref":{"doc":"NM","page":24}},{"id":"nm-124","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, at 55 mph, about how much time do you need to pass another vehicle?","o":["About 3 seconds","About 10 seconds","About 5 seconds","About 30 seconds"],"h1":"You need the same gap in oncoming traffic.","h2":"In New Mexico, at 55 mph you need about 10 seconds to pass, so you need a 10-second gap in oncoming traffic.","p":"Right. Passing at 55 mph takes about 10 seconds."},"es":{"q":"En Nuevo México, a 55 mph, ¿más o menos cuánto tiempo necesita para rebasar a otro vehículo?","o":["Unos 3 segundos","Unos 10 segundos","Unos 5 segundos","Unos 30 segundos"],"h1":"Necesita el mismo espacio libre en el tráfico que viene de frente.","h2":"En Nuevo México, a 55 mph necesita unos 10 segundos para rebasar, así que necesita un espacio de 10 segundos en el tráfico que viene de frente.","p":"Correcto. Rebasar a 55 mph toma unos 10 segundos."},"ref":{"doc":"NM","page":25}},{"id":"nm-125","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, there is a hill or curve ahead that blocks your view. Within what distance of it should you not start to pass?","o":["100 feet","500 feet","One-third of a mile","Two miles"],"h1":"It is about the distance you travel in 10 seconds on the highway.","h2":"In New Mexico, you should not start to pass within one-third of a mile of a hill or curve, because an oncoming car may be just out of sight.","p":"Right. Do not start to pass within one-third of a mile of a hill or curve."},"es":{"q":"En Nuevo México, adelante hay una loma o una curva que tapa la vista. ¿A qué distancia de ella no debe empezar a rebasar?","o":["A 100 pies","A 500 pies","A un tercio de milla","A dos millas"],"h1":"Es más o menos lo que recorre en 10 segundos en la carretera.","h2":"En Nuevo México, no debe empezar a rebasar a menos de un tercio de milla de una loma o curva, porque puede venir un carro de frente que no se ve.","p":"Correcto. No empiece a rebasar a menos de un tercio de milla de una loma o curva."},"ref":{"doc":"NM","page":25}},{"id":"nm-126","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, you just passed a bicyclist and want to turn right at the next corner. What should you do?","o":["Turn right quickly in front of the bicyclist","Honk and turn","Speed up so you turn before the bicyclist arrives","Slow down and merge behind the bicyclist before turning"],"h1":"Cutting across the bicycle's path is dangerous.","h2":"In New Mexico, do not make a sudden right turn after passing a bicyclist; slow down and merge behind the bicyclist before you turn.","p":"Right. Slow down and turn behind the bicyclist."},"es":{"q":"En Nuevo México, acaba de rebasar a un ciclista y quiere girar a la derecha en la siguiente esquina. ¿Qué debe hacer?","o":["Girar rápido a la derecha frente al ciclista","Tocar la bocina y girar","Acelerar para girar antes de que llegue el ciclista","Bajar la velocidad y ponerse detrás del ciclista antes de girar"],"h1":"Cruzarse en el camino de la bicicleta es peligroso.","h2":"En Nuevo México, no haga un giro repentino a la derecha después de rebasar a un ciclista; baje la velocidad y póngase detrás del ciclista antes de girar.","p":"Correcto. Baje la velocidad y gire detrás del ciclista."},"ref":{"doc":"NM","page":26}},{"id":"nm-127","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, who must wear a helmet when riding a bicycle?","o":["Minors (riders under 18)","No one","Only riders over 65","Only riders on highways"],"h1":"The manual says adults should, and this group must.","h2":"In New Mexico, minors must wear a well-fitting helmet when riding a bicycle, and adults should wear one too.","p":"Right. Minors must wear a bicycle helmet."},"es":{"q":"En Nuevo México, ¿quién debe usar casco al andar en bicicleta?","o":["Los menores de edad (menores de 18)","Nadie","Solo los mayores de 65","Solo quienes andan en carreteras"],"h1":"El manual dice que los adultos deberían usarlo y este grupo debe usarlo.","h2":"En Nuevo México, los menores de edad deben usar un casco bien ajustado al andar en bicicleta, y los adultos también deberían usarlo.","p":"Correcto. Los menores deben usar casco en bicicleta."},"ref":{"doc":"NM","page":26}},{"id":"nm-128","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, a car going 55 mph can stop in about 400 feet. About how far could a large truck need?","o":["About 200 feet","Almost 800 feet","About 400 feet, the same as a car","About 100 feet"],"h1":"A big rig needs about twice as far as a car.","h2":"In New Mexico, a large truck going 55 mph could take almost 800 feet to stop, about twice as far as a car, so never cut in front of one and slow down.","p":"Right. A large truck could need almost 800 feet."},"es":{"q":"En Nuevo México, un carro a 55 mph puede detenerse en unos 400 pies. ¿Más o menos cuánto podría necesitar un camión grande?","o":["Unos 200 pies","Casi 800 pies","Unos 400 pies, igual que un carro","Unos 100 pies"],"h1":"Un camión grande necesita más o menos el doble que un carro.","h2":"En Nuevo México, un camión grande a 55 mph podría necesitar casi 800 pies para detenerse, más o menos el doble que un carro; nunca se meta delante de uno para frenar.","p":"Correcto. Un camión grande podría necesitar casi 800 pies."},"ref":{"doc":"NM","page":27}},{"id":"nm-129","scope":"NM","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Mexico, on which side should you pass a large truck or RV?","o":["Always on the right side","On the shoulder","Always on the left side","Either side is the same"],"h1":"The driver can see better on that side, and trucks often swing wide to the right.","h2":"In New Mexico, always pass a large truck or RV on the left side, then move ahead of it instead of staying in its blind spot.","p":"Right. Pass large trucks and RVs on the left."},"es":{"q":"En Nuevo México, ¿por qué lado debe rebasar a un camión grande o a una casa rodante (RV)?","o":["Siempre por el lado derecho","Por el acotamiento","Siempre por el lado izquierdo","Da igual el lado"],"h1":"El conductor ve mejor de ese lado, y los camiones a menudo se abren a la derecha.","h2":"En Nuevo México, siempre rebase a un camión grande o casa rodante por el lado izquierdo y luego adelántese, sin quedarse en su punto ciego.","p":"Correcto. Rebase a camiones y casas rodantes por la izquierda."},"ref":{"doc":"NM","page":27}},{"id":"nm-130","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, glare from headlights bothers you at night. What does the manual say about sunglasses or tinted contact lenses?","o":["Use them to cut the glare","Use them only on the highway","Use them only in the city","Do not use them at night"],"h1":"At night you need all the light you can get.","h2":"In New Mexico, avoid dark glasses or tinted contact lenses at night, even for glare, because they cut down the light you need to see.","p":"Right. Do not wear dark or tinted lenses at night."},"es":{"q":"En Nuevo México, de noche le molesta el reflejo de las luces. ¿Qué dice el manual sobre los lentes oscuros o los lentes de contacto con color?","o":["Úselos para reducir el reflejo","Úselos solo en la carretera","Úselos solo en la ciudad","No los use de noche"],"h1":"De noche necesita toda la luz posible.","h2":"En Nuevo México, evite los lentes oscuros o de contacto con color de noche, aunque sea por el reflejo, porque reducen la luz que necesita para ver.","p":"Correcto. No use lentes oscuros ni con color de noche."},"ref":{"doc":"NM","page":28}},{"id":"nm-131","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, about how long does it take alcohol to reach your brain after you drink it?","o":["20 to 40 minutes","1 to 2 minutes","3 to 4 hours","One full day"],"h1":"It is less than an hour.","h2":"In New Mexico, the manual says alcohol reaches your brain in about 20 to 40 minutes.","p":"Right. Alcohol reaches the brain in 20 to 40 minutes."},"es":{"q":"En Nuevo México, ¿más o menos cuánto tarda el alcohol en llegar al cerebro después de tomarlo?","o":["De 20 a 40 minutos","De 1 a 2 minutos","De 3 a 4 horas","Un día entero"],"h1":"Es menos de una hora.","h2":"En Nuevo México, el manual dice que el alcohol llega al cerebro en unos 20 a 40 minutos.","p":"Correcto. El alcohol llega al cerebro en 20 a 40 minutos."},"ref":{"doc":"NM","page":29}},{"id":"nm-132","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, about how fast does your body get rid of alcohol?","o":["About three drinks per hour","About one drink per hour","About one drink per day","Faster if you drink coffee"],"h1":"Only time works, and it is slow.","h2":"In New Mexico, the manual says your body gets rid of about one alcoholic drink per hour, and coffee or cold showers do not speed it up.","p":"Right. About one drink per hour."},"es":{"q":"En Nuevo México, ¿más o menos qué tan rápido elimina su cuerpo el alcohol?","o":["Más o menos tres bebidas por hora","Más o menos una bebida por hora","Más o menos una bebida por día","Más rápido si toma café"],"h1":"Solo el tiempo funciona, y es lento.","h2":"En Nuevo México, el manual dice que su cuerpo elimina más o menos una bebida alcohólica por hora, y el café o una ducha fría no lo aceleran.","p":"Correcto. Más o menos una bebida por hora."},"ref":{"doc":"NM","page":29}},{"id":"nm-133","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, at what blood alcohol level can a driver 21 or older be arrested for drinking and driving?","o":["0.02 or more","0.10 or more","0.08 or more","0.15 or more"],"h1":"Drivers under 21 have a much lower limit of 0.02.","h2":"In New Mexico, a driver 21 or older can be arrested with a blood alcohol content of 0.08 or more.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Nuevo México, ¿con qué nivel de alcohol en la sangre puede ser arrestado un conductor de 21 años o más por manejar después de tomar?","o":["0.02 o más","0.10 o más","0.08 o más","0.15 o más"],"h1":"Los menores de 21 tienen un límite mucho más bajo, de 0.02.","h2":"En Nuevo México, un conductor de 21 años o más puede ser arrestado con un nivel de alcohol en la sangre de 0.08 o más.","p":"Correcto. Para adultos, el límite es 0.08."},"ref":{"doc":"NM","page":29}},{"id":"nm-134","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, according to the manual, how long should a person with epilepsy be free of seizures before getting a driver license?","o":["1 week","1 month","5 years","6 months"],"h1":"It is half a year.","h2":"In New Mexico, the manual says a person with epilepsy should be stable and seizure-free for 6 months before being issued a driver license.","p":"Right. Six months without a seizure."},"es":{"q":"En Nuevo México, según el manual, ¿cuánto tiempo debe pasar sin convulsiones una persona con epilepsia antes de obtener la licencia?","o":["1 semana","1 mes","5 años","6 meses"],"h1":"Es medio año.","h2":"En Nuevo México, el manual dice que una persona con epilepsia debe estar estable y sin convulsiones por 6 meses antes de recibir la licencia de conducir.","p":"Correcto. Seis meses sin convulsiones."},"ref":{"doc":"NM","page":30}},{"id":"nm-135","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, the engine dies while you are driving. What should you know about the steering and brakes?","o":["Steering is harder but still works, and the brakes need a hard push","Steering and brakes stop working completely","Steering is easier and the brakes are stronger","Only the parking brake will work"],"h1":"They still work, just not as easily.","h2":"In New Mexico, if the engine dies, grip the wheel firmly: the steering is harder to turn but still works, and the brakes work but may need a very hard push. Pull off the road.","p":"Right. You can still steer and brake, but it takes more force."},"es":{"q":"En Nuevo México, el motor se apaga mientras maneja. ¿Qué debe saber sobre el volante y los frenos?","o":["El volante cuesta más pero funciona, y los frenos necesitan que pise fuerte","El volante y los frenos dejan de funcionar por completo","El volante es más fácil y los frenos son más fuertes","Solo funcionará el freno de mano"],"h1":"Siguen funcionando, pero no tan fácil.","h2":"En Nuevo México, si el motor se apaga, sujete bien el volante: cuesta más girarlo pero funciona, y los frenos funcionan pero quizás tenga que pisar muy fuerte. Sálgase de la calle.","p":"Correcto. Todavía puede girar y frenar, pero con más fuerza."},"ref":{"doc":"NM","page":31}},{"id":"nm-136","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, a crash from the front cannot be avoided. What should you try to do?","o":["Let go of the steering wheel","Turn so that you get a glancing blow instead of a head-on hit","Take off your seat belt to get out faster","Speed up straight ahead"],"h1":"Even a small turn can change how you are hit.","h2":"In New Mexico, if you are about to be hit from the front, try to turn so you get a glancing blow rather than a head-on crash.","p":"Right. Turn to make it a glancing blow."},"es":{"q":"En Nuevo México, no puede evitar un choque de frente. ¿Qué debe tratar de hacer?","o":["Soltar el volante","Girar para que el golpe sea de lado (rozando) y no de frente","Quitarse el cinturón para salir más rápido","Acelerar en línea recta"],"h1":"Hasta un giro pequeño puede cambiar cómo le golpean.","h2":"En Nuevo México, si le van a chocar de frente, trate de girar para que el golpe sea rozando de lado y no de frente.","p":"Correcto. Gire para que el golpe sea rozando."},"ref":{"doc":"NM","page":33}},{"id":"nm-137","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you hit a parked car and cannot find the owner. What should you leave on the car?","o":["Nothing; just drive away","Only your license plate number written on the window","A note with how to reach you and the date and time of the crash","Some money under the wiper"],"h1":"The owner needs to contact you and know when it happened.","h2":"In New Mexico, if you hit a parked car and cannot find the owner, leave a note where it can be seen, with how to reach you and the date and time of the crash.","p":"Right. Leave a note with your contact information, the date and the time."},"es":{"q":"En Nuevo México, usted choca un carro estacionado y no encuentra al dueño. ¿Qué debe dejar en el carro?","o":["Nada; solo se va","Solo su número de placa escrito en la ventana","Una nota con cómo contactarle y la fecha y hora del choque","Algo de dinero bajo el limpiaparabrisas"],"h1":"El dueño necesita contactarle y saber cuándo pasó.","h2":"En Nuevo México, si choca un carro estacionado y no encuentra al dueño, deje una nota donde se vea, con cómo contactarle y la fecha y hora del choque.","p":"Correcto. Deje una nota con sus datos de contacto, la fecha y la hora."},"ref":{"doc":"NM","page":34}},{"id":"nm-138","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, an injured person at a crash asks for a drink of water. What does the manual say?","o":["Give them as much water as they want","Give them coffee to keep them awake","Give them a soda for sugar","Do not give injured people anything to drink, not even water"],"h1":"The answer is the same for every kind of drink.","h2":"In New Mexico, the manual says do not give injured people anything to drink, not even water.","p":"Right. Give nothing to drink, not even water."},"es":{"q":"En Nuevo México, una persona herida en un choque pide un vaso de agua. ¿Qué dice el manual?","o":["Déle toda el agua que quiera","Déle café para que no se duerma","Déle un refresco por el azúcar","No dé nada de beber a los heridos, ni siquiera agua"],"h1":"La respuesta es igual para cualquier bebida.","h2":"En Nuevo México, el manual dice que no dé nada de beber a las personas heridas, ni siquiera agua.","p":"Correcto. No dé nada de beber, ni siquiera agua."},"ref":{"doc":"NM","page":34}},{"id":"nm-139","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, you stop to help at a crash with several hurt people. Whom should you help first?","o":["Anyone who is not walking and talking","The person who is shouting the loudest","The drivers, before the passengers","The person with a small cut on the hand"],"h1":"People who can walk and talk are breathing and awake.","h2":"In New Mexico, first help anyone who is not already walking and talking: check for breathing, then check for bleeding.","p":"Right. Help those who are not walking and talking first."},"es":{"q":"En Nuevo México, usted se para a ayudar en un choque con varios heridos. ¿A quién debe ayudar primero?","o":["A quien no esté caminando ni hablando","A la persona que grita más fuerte","A los conductores antes que a los pasajeros","A la persona con una cortadita en la mano"],"h1":"Quien puede caminar y hablar está respirando y despierto.","h2":"En Nuevo México, primero ayude a quien no esté caminando ni hablando: revise si respira y luego si sangra.","p":"Correcto. Ayude primero a quien no camina ni habla."},"ref":{"doc":"NM","page":34}},{"id":"nm-140","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, on a motorcycle, how much of your total stopping power can the front brake give?","o":["About one-tenth","Up to about three-quarters","About one-quarter","None; only the rear brake stops you"],"h1":"The front brake is the more powerful one.","h2":"In New Mexico, the motorcycle front brake can give as much as three-quarters of your total stopping power, so use both brakes every time.","p":"Right. The front brake gives up to three-quarters of your stopping power."},"es":{"q":"En Nuevo México, en una motocicleta, ¿qué parte de la fuerza total de frenado puede dar el freno delantero?","o":["Más o menos una décima parte","Hasta unas tres cuartas partes","Más o menos una cuarta parte","Nada; solo frena el trasero"],"h1":"El freno delantero es el más fuerte.","h2":"En Nuevo México, el freno delantero de la motocicleta puede dar hasta tres cuartas partes de la fuerza total de frenado; use los dos frenos siempre.","p":"Correcto. El freno delantero da hasta tres cuartas partes del frenado."},"ref":{"doc":"NM","page":35}},{"id":"nm-141","scope":"NM","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New Mexico, what does the manual say about riding a motorcycle between rows of cars in the same lane (lane sharing)?","o":["It is always allowed in heavy traffic","It is allowed below 30 mph","It is usually prohibited","It is required at red lights"],"h1":"Cars and motorcycles each need a full lane.","h2":"In New Mexico, lane sharing is usually prohibited, because cars and motorcycles each need a full lane to operate safely.","p":"Right. Lane sharing is usually prohibited."},"es":{"q":"En Nuevo México, ¿qué dice el manual sobre andar en motocicleta entre filas de carros en el mismo carril (compartir carril)?","o":["Siempre se permite con mucho tráfico","Se permite a menos de 30 mph","Normalmente está prohibido","Es obligatorio en los semáforos en rojo"],"h1":"Los carros y las motocicletas necesitan cada uno un carril completo.","h2":"En Nuevo México, compartir carril normalmente está prohibido, porque los carros y las motocicletas necesitan cada uno un carril completo para ir con seguridad.","p":"Correcto. Compartir carril normalmente está prohibido."},"ref":{"doc":"NM","page":36}},{"id":"nm-142","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, most motorcycles have rounded (convex) mirrors. How do cars look in them?","o":["Closer than they really are","Exactly as far as they really are","Upside down","Farther away than they really are"],"h1":"Convex mirrors show a wider view, but make things look small.","h2":"In New Mexico, the manual says convex motorcycle mirrors give a wider view but make cars seem farther away than they really are, so allow extra distance before changing lanes.","p":"Right. Cars look farther away than they are."},"es":{"q":"En Nuevo México, la mayoría de las motocicletas tienen espejos redondeados (convexos). ¿Cómo se ven los carros en ellos?","o":["Más cerca de lo que en realidad están","A la distancia exacta","Al revés","Más lejos de lo que en realidad están"],"h1":"Los espejos convexos dan una vista más amplia, pero hacen que todo se vea pequeño.","h2":"En Nuevo México, el manual dice que los espejos convexos de motocicleta dan una vista más amplia, pero hacen que los carros parezcan más lejos de lo que están; deje más distancia antes de cambiar de carril.","p":"Correcto. Los carros se ven más lejos de lo que están."},"ref":{"doc":"NM","page":37}},{"id":"nm-143","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, a dog chases you while you ride a motorcycle. What does the manual say to do?","o":["Shift down, approach it slowly, then speed up and leave it behind","Kick at the dog","Stop and wait for the dog to leave","Swerve sharply toward the dog"],"h1":"Keep control of the motorcycle and look where you want to go.","h2":"In New Mexico, if a dog chases you, shift down and approach it slowly, then speed up and leave it behind; never kick at it.","p":"Right. Slow down near it, then speed up past it."},"es":{"q":"En Nuevo México, un perro le persigue mientras usted va en motocicleta. ¿Qué dice el manual que haga?","o":["Bajar de cambio, acercarse despacio y luego acelerar para dejarlo atrás","Darle una patada al perro","Pararse y esperar a que se vaya","Desviarse bruscamente hacia el perro"],"h1":"Mantenga el control de la motocicleta y mire a donde quiere ir.","h2":"En Nuevo México, si un perro le persigue, baje de cambio y acérquese despacio, luego acelere y déjelo atrás; nunca le dé una patada.","p":"Correcto. Vaya despacio al acercarse y luego acelere para pasarlo."},"ref":{"doc":"NM","page":38}},{"id":"nm-144","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, the front wheel and handlebars of your motorcycle suddenly start to shake (a wobble). What should you do?","o":["Speed up to get out of the wobble","Grip the handlebars firmly and close the throttle gradually, without braking","Brake hard right away","Let go of the handlebars"],"h1":"Speeding up or braking can make it worse.","h2":"In New Mexico, in a wobble you should grip the handlebars firmly, close the throttle gradually to slow down, not use the brakes, and pull off the road as soon as you can.","p":"Right. Hold firmly and ease off the throttle; do not brake."},"es":{"q":"En Nuevo México, la rueda delantera y el manubrio de su motocicleta empiezan a sacudirse de repente (bamboleo). ¿Qué debe hacer?","o":["Acelerar para salir del bamboleo","Sujetar firme el manubrio y cerrar el acelerador poco a poco, sin frenar","Frenar fuerte de inmediato","Soltar el manubrio"],"h1":"Acelerar o frenar puede empeorarlo.","h2":"En Nuevo México, en un bamboleo debe sujetar firme el manubrio, cerrar el acelerador poco a poco para bajar la velocidad, no usar los frenos y salirse de la calle en cuanto pueda.","p":"Correcto. Sujete firme y suelte el acelerador; no frene."},"ref":{"doc":"NM","page":39}},{"id":"nm-145","scope":"NM","cat":"licensing","sign":null,"c":2,"en":{"q":"In New Mexico, you let a friend use your driver license. What can happen to you?","o":["Nothing, if your friend drives safely","Only your friend can be punished","You can lose your driving privileges","You only get a warning letter"],"h1":"Your license is for you alone.","h2":"In New Mexico, letting someone else use your driver license is one of the things that can cost you your driving privileges.","p":"Right. Lending your license can cost you your license."},"es":{"q":"En Nuevo México, usted deja que un amigo use su licencia de manejar. ¿Qué le puede pasar a usted?","o":["Nada, si su amigo maneja con cuidado","Solo pueden castigar a su amigo","Puede perder sus privilegios de manejar","Solo recibe una carta de advertencia"],"h1":"Su licencia es solo para usted.","h2":"En Nuevo México, dejar que otra persona use su licencia de manejar es una de las cosas por las que puede perder sus privilegios de manejar.","p":"Correcto. Prestar su licencia le puede costar la licencia."},"ref":{"doc":"NM","page":3}},{"id":"nm-146","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, when should you drive at the maximum posted speed limit?","o":["Only in ideal driving conditions","Any time, day or night","Whenever you are running late","Whenever the road is empty, even in fog"],"h1":"Think about rain, snow, ice and fog.","h2":"In New Mexico, the maximum speed limit should be driven only in ideal conditions; you must slow down when the road or the weather calls for it.","p":"Right. The top limit is only for ideal conditions."},"es":{"q":"En Nuevo México, ¿cuándo debe manejar al límite máximo de velocidad indicado?","o":["Solo en condiciones ideales para manejar","En cualquier momento, de día o de noche","Siempre que vaya tarde","Siempre que la calle esté vacía, aunque haya neblina"],"h1":"Piense en la lluvia, la nieve, el hielo y la neblina.","h2":"En Nuevo México, el límite máximo de velocidad solo se debe usar en condiciones ideales; debe ir más despacio cuando la calle o el clima lo pidan.","p":"Correcto. El límite máximo es solo para condiciones ideales."},"ref":{"doc":"NM","page":6}},{"id":"nm-147","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, why should you not swing wide to the left before you turn right?","o":["It makes your tires wear out faster","It puts your car too close to the curb","It is only a problem for large trucks","A driver behind may think you are turning left and pass you on the right"],"h1":"Think about what the driver behind you sees.","h2":"In New Mexico, if you swing wide to the left before a right turn, the driver behind you may think you are changing lanes or turning left and may try to pass you on the right.","p":"Right. Swinging wide can trick the driver behind you."},"es":{"q":"En Nuevo México, ¿por qué no debe abrirse hacia la izquierda antes de girar a la derecha?","o":["Gasta más rápido las llantas","Deja su carro demasiado cerca de la banqueta","Solo es un problema para camiones grandes","El conductor de atrás puede creer que usted va a girar a la izquierda y rebasarle por la derecha"],"h1":"Piense en lo que ve el conductor que va detrás de usted.","h2":"En Nuevo México, si se abre hacia la izquierda antes de girar a la derecha, el conductor de atrás puede creer que usted cambia de carril o gira a la izquierda, y puede tratar de rebasarle por la derecha.","p":"Correcto. Abrirse puede confundir al conductor de atrás."},"ref":{"doc":"NM","page":10}},{"id":"nm-148","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, what should you avoid when you make a left turn?","o":["Leaving room for oncoming cars to turn left in front of you","Cutting the corner so sharply that you hit someone coming from the left","Watching for people crossing","Using your turn signal"],"h1":"Think about the cars coming from your left on the street you turn into.","h2":"In New Mexico, when you turn left, do not cut the corner so sharply that you run into someone coming from the left, but still leave room for oncoming cars to turn left in front of you.","p":"Right. Do not cut the corner on a left turn."},"es":{"q":"En Nuevo México, ¿qué debe evitar al girar a la izquierda?","o":["Dejar espacio para que los carros de enfrente giren a la izquierda delante de usted","Cortar la esquina tan cerrado que choque con alguien que viene de la izquierda","Fijarse en las personas que cruzan","Usar su direccional"],"h1":"Piense en los carros que vienen por su izquierda en la calle a la que entra.","h2":"En Nuevo México, al girar a la izquierda no corte la esquina tan cerrado que choque con alguien que viene de la izquierda, pero deje espacio para que los carros de enfrente giren a la izquierda delante de usted.","p":"Correcto. No corte la esquina al girar a la izquierda."},"ref":{"doc":"NM","page":11}},{"id":"nm-149","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, signs show that two lanes may turn left together. You are in one of them. What should you do during the turn?","o":["Move into the other turn lane if it is faster","Stay in your own lane through the turn","Turn into the far right lane","Drive across both lanes to make the turn wider"],"h1":"The car in the other turn lane is turning at the same time.","h2":"In New Mexico, when signs or markings allow two or more turning lanes, you must stay in your own lane during the turn.","p":"Right. Stay in your lane while you turn."},"es":{"q":"En Nuevo México, unos letreros indican que dos carriles pueden girar a la izquierda juntos. Usted está en uno de ellos. ¿Qué debe hacer durante el giro?","o":["Pasarse al otro carril de giro si va más rápido","Quedarse en su propio carril durante todo el giro","Girar hacia el carril de la extrema derecha","Cruzar los dos carriles para abrir más la vuelta"],"h1":"El carro del otro carril de giro está girando al mismo tiempo.","h2":"En Nuevo México, cuando los letreros o las marcas permiten dos o más carriles de giro, debe quedarse en su propio carril durante el giro.","p":"Correcto. Quédese en su carril mientras gira."},"ref":{"doc":"NM","page":11}},{"id":"nm-150","scope":"NM","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New Mexico, you are pulling out of an alley onto a main road. Who must yield?","o":["Cars on the main road must slow down and let you in first","Whoever is going faster","The larger vehicle","You must yield to vehicles already on the main road"],"h1":"The cars on the main road were there first.","h2":"In New Mexico, a driver entering a road from a driveway, alley or roadside must yield to vehicles already on the main road.","p":"Right. Yield to traffic already on the main road."},"es":{"q":"En Nuevo México, usted sale de un callejón hacia una calle principal. ¿Quién debe ceder el paso?","o":["Los carros de la calle principal deben frenar y dejarle entrar primero","El que va más rápido","El vehículo más grande","Usted debe ceder el paso a los vehículos que ya están en la calle principal"],"h1":"Los carros de la calle principal estaban ahí primero.","h2":"En Nuevo México, el conductor que entra a una calle desde una entrada de casa, un callejón o la orilla del camino debe ceder el paso a los vehículos que ya están en la calle principal.","p":"Correcto. Ceda el paso al tráfico que ya está en la calle principal."},"ref":{"doc":"NM","page":11}},{"id":"nm-151","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, your light is green, but traffic is backed up just past the intersection. What should you do?","o":["Wait until you can get all the way through without stopping","Drive in and wait in the middle of the intersection until traffic moves","Honk so the cars ahead move","Go around the stopped cars on the shoulder"],"h1":"Do not leave your car where it blocks the cross street.","h2":"In New Mexico, you may not enter an intersection unless you can get through it without stopping, so wait until traffic ahead clears and you will not block it.","p":"Right. Do not enter unless you can get all the way through."},"es":{"q":"En Nuevo México, su luz está en verde, pero el tráfico está detenido justo después de la intersección. ¿Qué debe hacer?","o":["Esperar hasta poder pasar completa la intersección sin detenerse","Entrar y esperar en medio de la intersección hasta que avance el tráfico","Tocar la bocina para que avancen los carros de adelante","Rodear los carros detenidos por el acotamiento"],"h1":"No deje su carro donde bloquee la calle que cruza.","h2":"En Nuevo México, no puede entrar a una intersección si no puede pasarla sin detenerse; espere a que avance el tráfico de adelante para no bloquearla.","p":"Correcto. No entre si no puede pasar completo."},"ref":{"doc":"NM","page":11}},{"id":"nm-152","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you have parked next to a curb. Which side of the car should you get out on, if you can?","o":["The street side","The side closest to the center line","The curb side","Either side; it makes no difference"],"h1":"Which side keeps you away from moving cars?","h2":"In New Mexico, you should get out of a parked car on the curb side if you can; if you must use the street side, check traffic before you get out.","p":"Right. Get out on the curb side when you can."},"es":{"q":"En Nuevo México, usted se estacionó junto a la banqueta. ¿Por qué lado del carro debe bajarse, si puede?","o":["Por el lado de la calle","Por el lado más cerca de la línea del centro","Por el lado de la banqueta","Por cualquier lado; da igual"],"h1":"¿Qué lado le mantiene lejos de los carros en movimiento?","h2":"En Nuevo México, si puede, bájese de un carro estacionado por el lado de la banqueta; si tiene que usar el lado de la calle, fíjese en el tráfico antes de bajarse.","p":"Correcto. Bájese por el lado de la banqueta cuando pueda."},"ref":{"doc":"NM","page":13}},{"id":"nm-153","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, you want to stop and park on the street next to a car that is already parked at the curb. What does the manual say?","o":["You may park there for up to 10 minutes","You may park there if your flashers are on","Do not park there; that is double parking","You may park there at night only"],"h1":"There is a name for parking on the road side of a parked car.","h2":"In New Mexico, you may not park on the road side of a parked vehicle; this is called double parking.","p":"Right. Double parking is not allowed."},"es":{"q":"En Nuevo México, usted quiere estacionarse en la calle al lado de un carro que ya está estacionado junto a la banqueta. ¿Qué dice el manual?","o":["Puede estacionarse ahí hasta 10 minutos","Puede estacionarse ahí si prende las luces intermitentes","No se estacione ahí; eso es estacionarse en doble fila","Solo puede estacionarse ahí de noche"],"h1":"Hay un nombre para estacionarse del lado de la calle de un carro estacionado.","h2":"En Nuevo México, no puede estacionarse del lado de la calle de un vehículo estacionado; a esto se le llama estacionarse en doble fila.","p":"Correcto. No se permite estacionarse en doble fila."},"ref":{"doc":"NM","page":13}},{"id":"nm-154","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, before you start the engine, what should you make sure of?","o":["The parking brake is on","The car is in drive","Your foot is on the gas pedal","The high beams are on"],"h1":"It keeps the car from rolling.","h2":"In New Mexico, make sure the parking brake is on before you start the vehicle; an automatic should be in park, and a manual must not be in gear.","p":"Right. Set the parking brake before you start."},"es":{"q":"En Nuevo México, antes de encender el motor, ¿de qué debe asegurarse?","o":["De que el freno de mano esté puesto","De que el carro esté en drive","De tener el pie en el acelerador","De tener las luces altas prendidas"],"h1":"Evita que el carro se mueva.","h2":"En Nuevo México, asegúrese de que el freno de mano esté puesto antes de encender el vehículo; un automático debe estar en park, y uno de cambios no debe estar en una velocidad.","p":"Correcto. Ponga el freno de mano antes de encender."},"ref":{"doc":"NM","page":14}},{"id":"nm-155","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, which hand positions on the steering wheel does the manual describe as balanced?","o":["One hand at 12 o'clock","Both hands at 6 o'clock","11 and 1 o'clock, close together","10 and 2 o'clock, or 9 and 3 o'clock"],"h1":"Picture the wheel as a clock, with a hand on each side.","h2":"In New Mexico, the manual says to hold the wheel firmly on each side, at 10 and 2 o'clock or at 9 and 3 o'clock, with your knuckles outside the rim.","p":"Right. 10 and 2, or 9 and 3."},"es":{"q":"En Nuevo México, ¿qué posiciones de las manos en el volante describe el manual como equilibradas?","o":["Una mano a las 12","Las dos manos a las 6","A las 11 y la 1, muy juntas","A las 10 y las 2, o a las 9 y las 3"],"h1":"Imagine el volante como un reloj, con una mano a cada lado.","h2":"En Nuevo México, el manual dice que tome el volante con firmeza a cada lado, a las 10 y las 2 o a las 9 y las 3, con los nudillos por fuera del aro.","p":"Correcto. A las 10 y las 2, o a las 9 y las 3."},"ref":{"doc":"NM","page":14}},{"id":"nm-156","scope":"NM","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New Mexico, you stopped at an intersection, but buildings block your view of the cross street. What should you do?","o":["Go quickly so you are in the way for less time","Edge forward slowly until you can see","Honk and drive straight across","Back up and take another road"],"h1":"Moving slowly lets crossing drivers see the front of your car.","h2":"In New Mexico, if your view of a cross street is blocked, edge forward slowly until you can see; crossing drivers will see the front of your car and can slow down.","p":"Right. Edge forward slowly until you can see."},"es":{"q":"En Nuevo México, usted se detuvo en una intersección, pero unos edificios le tapan la vista de la calle que cruza. ¿Qué debe hacer?","o":["Pasar rápido para estorbar menos tiempo","Avanzar poco a poco hasta que pueda ver","Tocar la bocina y cruzar derecho","Echarse en reversa y tomar otra calle"],"h1":"Avanzar despacio deja que los otros conductores vean el frente de su carro.","h2":"En Nuevo México, si algo le tapa la vista de la calle que cruza, avance poco a poco hasta que pueda ver; los conductores que cruzan verán el frente de su carro y podrán frenar.","p":"Correcto. Avance poco a poco hasta que pueda ver."},"ref":{"doc":"NM","page":16}},{"id":"nm-157","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you want to move into the middle lane of a road with three lanes going your way. Besides your mirrors and blind spot, what should you check?","o":["Your fuel gauge","Traffic across the center line","The lane lines behind you","The far lane, because a car there may move into the middle lane too"],"h1":"Someone on the other side may want the same lane.","h2":"In New Mexico, before you change lanes, check the far lane if there is one, because a driver in that lane may be planning to move into the same lane you want.","p":"Right. Check the far lane too."},"es":{"q":"En Nuevo México, usted quiere pasarse al carril del medio de una calle con tres carriles en su sentido. Además de los espejos y el punto ciego, ¿qué debe revisar?","o":["El indicador de gasolina","El tráfico al otro lado de la línea del centro","Las líneas de los carriles detrás de usted","El carril del otro lado, porque un carro ahí también puede pasarse al carril del medio"],"h1":"Alguien del otro lado puede querer el mismo carril.","h2":"En Nuevo México, antes de cambiar de carril, revise el carril del otro lado si lo hay, porque un conductor ahí puede querer pasarse al mismo carril que usted.","p":"Correcto. Revise también el carril del otro lado."},"ref":{"doc":"NM","page":17}},{"id":"nm-158","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, you are going to back out of your driveway. What should you do before you get into the car?","o":["Check behind the car","Turn on the radio","Honk the horn","Adjust your side mirrors from outside"],"h1":"Small children cannot be seen from the driver's seat.","h2":"In New Mexico, check behind your vehicle before you get in, because children or small objects cannot be seen from the driver's seat.","p":"Right. Look behind the car before you get in."},"es":{"q":"En Nuevo México, usted va a salir en reversa de la entrada de su casa. ¿Qué debe hacer antes de subirse al carro?","o":["Revisar detrás del carro","Prender el radio","Tocar la bocina","Ajustar los espejos laterales desde afuera"],"h1":"Desde el asiento del conductor no se ven los niños pequeños.","h2":"En Nuevo México, revise detrás de su vehículo antes de subirse, porque desde el asiento del conductor no se ven los niños ni los objetos pequeños.","p":"Correcto. Revise detrás del carro antes de subirse."},"ref":{"doc":"NM","page":17}},{"id":"nm-159","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you are driving down a long, steep hill. What should you watch for in your mirrors?","o":["Cars behind you that are slowing down to turn into driveways","Police cars that must pass you","Large trucks and buses that may be going too fast","Nothing; mirrors matter only on flat roads"],"h1":"Heavy vehicles build up speed going downhill.","h2":"In New Mexico, check your mirrors when going down hills or mountains, because vehicles build up speed on a steep grade; watch for large trucks and buses that may be going too fast.","p":"Right. Watch for trucks and buses going too fast."},"es":{"q":"En Nuevo México, usted baja una pendiente larga y empinada. ¿A qué debe estar atento en sus espejos?","o":["A carros detrás de usted que van frenando para entrar a una casa","A patrullas que tienen que rebasarle","A camiones grandes y autobuses que pueden ir demasiado rápido","A nada; los espejos solo importan en terreno plano"],"h1":"Los vehículos pesados agarran velocidad de bajada.","h2":"En Nuevo México, revise sus espejos al bajar lomas o montañas, porque los vehículos agarran velocidad en una pendiente; fíjese en camiones grandes y autobuses que puedan ir demasiado rápido.","p":"Correcto. Fíjese en camiones y autobuses que van muy rápido."},"ref":{"doc":"NM","page":17}},{"id":"nm-160","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, there are no cars coming toward you at night. Where does the manual say it is important to use your high beams?","o":["In thick fog","In heavy snow","On unfamiliar roads and in construction areas","When you follow close behind another car at night"],"h1":"High beams help most where you do not know what is ahead.","h2":"In New Mexico, when no vehicles are coming, it is important to use high beams on unfamiliar roads, in construction areas and where people may be along the side of the road.","p":"Right. Use high beams on unfamiliar roads and in work areas."},"es":{"q":"En Nuevo México, de noche no vienen carros de frente. ¿Dónde dice el manual que es importante usar las luces altas?","o":["En neblina espesa","En una nevada fuerte","En caminos que no conoce y en zonas de construcción","Cuando va muy cerca detrás de otro carro de noche"],"h1":"Las luces altas ayudan más donde no sabe qué hay adelante.","h2":"En Nuevo México, cuando no vienen vehículos de frente, es importante usar las luces altas en caminos que no conoce, en zonas de construcción y donde puede haber gente a la orilla del camino.","p":"Correcto. Use luces altas en caminos desconocidos y zonas de obra."},"ref":{"doc":"NM","page":18}},{"id":"nm-161","scope":"NM","cat":"signals","sign":null,"c":0,"en":{"q":"In New Mexico, you are driving out of a narrow alley and cannot see what is coming. There is no immediate danger. How should you use your horn?","o":["Give it a light tap","Give a long, sharp blast","Do not use it at all","Honk again and again"],"h1":"With no immediate danger, a little is enough.","h2":"In New Mexico, when you come to a place where you cannot see ahead, like a sharp curve or the exit of a narrow alley, give your horn a light tap.","p":"Right. A light tap is enough here."},"es":{"q":"En Nuevo México, usted sale de un callejón angosto y no puede ver qué viene. No hay peligro inmediato. ¿Cómo debe usar la bocina?","o":["Darle un toque ligero","Dar un pitazo largo y fuerte","No usarla para nada","Tocarla una y otra vez"],"h1":"Sin peligro inmediato, basta con poco.","h2":"En Nuevo México, cuando llega a un lugar donde no puede ver lo que hay adelante, como una curva cerrada o la salida de un callejón angosto, dé un toque ligero a la bocina.","p":"Correcto. Aquí basta un toque ligero."},"ref":{"doc":"NM","page":18}},{"id":"nm-162","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, your car breaks down on the highway. Where should you put emergency flares?","o":["Only in front of your vehicle","On the roof of your vehicle","On the other side of the highway","Behind your vehicle"],"h1":"They warn drivers coming up from behind.","h2":"In New Mexico, if your car breaks down, place emergency flares behind it so other drivers can see it and change lanes if needed.","p":"Right. Put the flares behind your car."},"es":{"q":"En Nuevo México, su carro se descompone en la carretera. ¿Dónde debe poner las bengalas de emergencia?","o":["Solo delante de su vehículo","Sobre el techo de su vehículo","Del otro lado de la carretera","Detrás de su vehículo"],"h1":"Avisan a los conductores que vienen por detrás.","h2":"En Nuevo México, si su carro se descompone, ponga bengalas de emergencia detrás de él para que los demás lo vean y puedan cambiar de carril si hace falta.","p":"Correcto. Ponga las bengalas detrás de su carro."},"ref":{"doc":"NM","page":19}},{"id":"nm-163","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you have a flat tire, and changing it would mean standing in a traffic lane. What should you do?","o":["Change it quickly with your flashers on","Do not change it there; never stand in the roadway","Change it only if it is daytime","Change it while a passenger watches traffic"],"h1":"Your safety comes before the tire.","h2":"In New Mexico, never stand in the roadway, and do not try to change a tire if it means you have to be in a traffic lane.","p":"Right. Do not change a tire from a traffic lane."},"es":{"q":"En Nuevo México, se le poncha una llanta, y para cambiarla tendría que pararse en un carril de tráfico. ¿Qué debe hacer?","o":["Cambiarla rápido con las luces intermitentes prendidas","No cambiarla ahí; nunca se pare en la calle","Cambiarla solo si es de día","Cambiarla mientras un pasajero vigila el tráfico"],"h1":"Su seguridad es más importante que la llanta.","h2":"En Nuevo México, nunca se pare en la calle, y no trate de cambiar una llanta si para eso tiene que estar en un carril de tráfico.","p":"Correcto. No cambie una llanta desde un carril de tráfico."},"ref":{"doc":"NM","page":19}},{"id":"nm-164","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you turn onto a gravel or dirt road. What should you expect?","o":["More traction than on asphalt","Less traction, so slow down; stopping takes much longer","The same stopping distance as on concrete","You can turn more sharply than on pavement"],"h1":"Loose stones and dirt do not grip like pavement.","h2":"In New Mexico, gravel and dirt roads give less traction than concrete or asphalt, so you must slow down; it takes much longer to stop and it is easier to skid when turning.","p":"Right. Slow down on gravel or dirt."},"es":{"q":"En Nuevo México, usted entra a un camino de grava o de tierra. ¿Qué debe esperar?","o":["Más agarre que en el asfalto","Menos agarre, así que baje la velocidad; detenerse toma mucho más","La misma distancia para detenerse que en concreto","Que puede girar más cerrado que en pavimento"],"h1":"Las piedras sueltas y la tierra no agarran como el pavimento.","h2":"En Nuevo México, los caminos de grava y de tierra dan menos agarre que el concreto o el asfalto, así que debe ir más despacio; detenerse toma mucho más y es más fácil derrapar al girar.","p":"Correcto. Vaya más despacio en grava o tierra."},"ref":{"doc":"NM","page":20}},{"id":"nm-165","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, the road is covered with ice. How much should you slow down?","o":["About 10 mph below the limit","To about half the speed limit","Not at all, if you have good tires","Slow to a crawl"],"h1":"Ice is the most dangerous surface in the manual.","h2":"In New Mexico, on ice you must slow to a crawl; if at all possible, do not drive when the roads are icy.","p":"Right. On ice, slow to a crawl."},"es":{"q":"En Nuevo México, la calle está cubierta de hielo. ¿Cuánto debe bajar la velocidad?","o":["Unas 10 mph menos que el límite","Más o menos a la mitad del límite","Nada, si tiene buenas llantas","Ir a vuelta de rueda, muy despacio"],"h1":"El hielo es la superficie más peligrosa del manual.","h2":"En Nuevo México, sobre hielo debe ir a vuelta de rueda, muy despacio; si es posible, no maneje cuando las calles tengan hielo.","p":"Correcto. Sobre hielo, vaya a vuelta de rueda."},"ref":{"doc":"NM","page":20}},{"id":"nm-166","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, when is ice on the road the most slippery?","o":["When the temperature is near freezing and the ice is wet","When it is far below freezing","When the ice is dry and very cold","Only late at night"],"h1":"A thin layer of water on top makes it worse.","h2":"In New Mexico, when the temperature is around the freezing point, ice can become wet, and that makes it more slippery than at temperatures well below freezing.","p":"Right. Wet ice near freezing is the most slippery."},"es":{"q":"En Nuevo México, ¿cuándo es más resbaloso el hielo en la calle?","o":["Cuando la temperatura está cerca del punto de congelación y el hielo está mojado","Cuando hace muchísimo frío, muy por debajo de cero","Cuando el hielo está seco y muy frío","Solo muy tarde en la noche"],"h1":"Una capa delgada de agua encima lo empeora.","h2":"En Nuevo México, cuando la temperatura está cerca del punto de congelación, el hielo se puede mojar, y eso lo hace más resbaloso que cuando hace mucho más frío.","p":"Correcto. El hielo mojado cerca de la congelación es el más resbaloso."},"ref":{"doc":"NM","page":20}},{"id":"nm-167","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you see animals beside the road that have been hit by cars. What should you do?","o":["Speed up to get through the area","Stop in your lane to look","Slow down; you may be in an animal crossing area","Keep the same speed and turn on your high beams to see better"],"h1":"Where animals were hit before, more may cross.","h2":"In New Mexico, if you see animals that have been hit, slow down, because you may be in an area where animals cross the road.","p":"Right. Slow down; animals may be crossing here."},"es":{"q":"En Nuevo México, usted ve animales atropellados a la orilla del camino. ¿Qué debe hacer?","o":["Acelerar para salir pronto de la zona","Detenerse en su carril para mirar","Bajar la velocidad; puede estar en una zona donde cruzan animales","Seguir a la misma velocidad y prender las luces altas para ver mejor"],"h1":"Donde atropellaron animales antes, pueden cruzar más.","h2":"En Nuevo México, si ve animales atropellados, baje la velocidad, porque puede estar en una zona donde los animales cruzan el camino.","p":"Correcto. Baje la velocidad; aquí pueden cruzar animales."},"ref":{"doc":"NM","page":21}},{"id":"nm-168","scope":"NM","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New Mexico, you will leave the freeway at the next exit, which has an exit ramp. When should you slow down?","o":["On the main road, well before the ramp","As soon as you see the exit sign","After you move onto the exit ramp","Only at the end of the ramp"],"h1":"Keep up with traffic while you are still on the main road.","h2":"In New Mexico, keep up with the speed of traffic while you are on the main road, and do not slow down until you have moved onto the exit ramp.","p":"Right. Slow down once you are on the exit ramp."},"es":{"q":"En Nuevo México, usted va a salir de la autopista en la próxima salida, que tiene rampa. ¿Cuándo debe bajar la velocidad?","o":["En la vía principal, mucho antes de la rampa","En cuanto vea el letrero de la salida","Después de entrar a la rampa de salida","Solo al final de la rampa"],"h1":"Siga el ritmo del tráfico mientras siga en la vía principal.","h2":"En Nuevo México, mantenga la velocidad del tráfico mientras esté en la vía principal, y no baje la velocidad hasta que haya entrado a la rampa de salida.","p":"Correcto. Baje la velocidad ya en la rampa de salida."},"ref":{"doc":"NM","page":22}},{"id":"nm-169","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, the rain is so heavy that you cannot see well enough to drive. What should you do?","o":["Pull off the road in a safe place and wait until it clears","Keep going with your high beams on","Stop right in your lane and turn on your emergency flashers until it clears","Follow close behind the taillights ahead"],"h1":"Get out of the traffic lanes first.","h2":"In New Mexico, if a very heavy downpour keeps you from seeing well enough to drive, pull off the road in a safe place and wait until it clears.","p":"Right. Pull off safely and wait it out."},"es":{"q":"En Nuevo México, llueve tan fuerte que no puede ver lo suficiente para manejar. ¿Qué debe hacer?","o":["Salirse del camino en un lugar seguro y esperar a que aclare","Seguir con las luces altas prendidas","Detenerse en su carril y prender las intermitentes hasta que aclare","Seguir muy de cerca las luces traseras del carro de adelante"],"h1":"Primero salga de los carriles de tráfico.","h2":"En Nuevo México, si un aguacero muy fuerte no le deja ver lo suficiente para manejar, sálgase del camino en un lugar seguro y espere a que aclare.","p":"Correcto. Sálgase con seguridad y espere."},"ref":{"doc":"NM","page":23}},{"id":"nm-170","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you are pulling a trailer. What following distance does the manual suggest?","o":["Three seconds","Two seconds","One second","Four seconds"],"h1":"It is one second more than the normal rule.","h2":"In New Mexico, you may need a four-second following distance when you have a heavy load or are pulling a trailer.","p":"Right. Keep four seconds with a trailer."},"es":{"q":"En Nuevo México, usted va jalando un remolque. ¿Qué distancia de seguimiento sugiere el manual?","o":["Tres segundos","Dos segundos","Un segundo","Cuatro segundos"],"h1":"Es un segundo más que la regla normal.","h2":"En Nuevo México, puede necesitar una distancia de cuatro segundos cuando lleva una carga pesada o va jalando un remolque.","p":"Correcto. Deje cuatro segundos con remolque."},"ref":{"doc":"NM","page":24}},{"id":"nm-171","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, you merge into the middle of a four-second gap. How much following distance do you and the car behind you then have?","o":["About four seconds each","About two seconds each","About one second each","About eight seconds each"],"h1":"The gap is split in half.","h2":"In New Mexico, if you move into the middle of a four-second gap, both you and the vehicle now behind you have about a two-second following distance.","p":"Right. Each of you has about two seconds."},"es":{"q":"En Nuevo México, usted se incorpora en medio de un espacio de cuatro segundos. ¿Cuánta distancia de seguimiento tienen usted y el carro que queda detrás?","o":["Unos cuatro segundos cada uno","Unos dos segundos cada uno","Más o menos un segundo cada uno","Unos ocho segundos cada uno"],"h1":"El espacio se divide a la mitad.","h2":"En Nuevo México, si se mete en medio de un espacio de cuatro segundos, usted y el vehículo que queda detrás tienen unos dos segundos de distancia cada uno.","p":"Correcto. Cada uno tiene unos dos segundos."},"ref":{"doc":"NM","page":24}},{"id":"nm-172","scope":"NM","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New Mexico, you have just passed a car. When is it safe to move back into the driving lane?","o":["As soon as your front bumper is past it","When you can see both of its headlights in your rearview mirror","When you are beside its front door","When its driver flashes the lights"],"h1":"Look in your mirror for the car you passed.","h2":"In New Mexico, after passing, it is safe to return to the driving lane when you can see both headlights of the vehicle you passed in your rearview mirror.","p":"Right. Wait until you see both headlights in your mirror."},"es":{"q":"En Nuevo México, usted acaba de rebasar a un carro. ¿Cuándo es seguro regresar al carril?","o":["En cuanto su defensa delantera lo haya pasado","Cuando vea los dos faros de ese carro en su espejo retrovisor","Cuando vaya junto a su puerta delantera","Cuando su conductor le haga cambio de luces"],"h1":"Busque en su espejo al carro que rebasó.","h2":"En Nuevo México, después de rebasar, es seguro regresar al carril cuando vea los dos faros del vehículo que rebasó en su espejo retrovisor.","p":"Correcto. Espere hasta ver los dos faros en su espejo."},"ref":{"doc":"NM","page":25}},{"id":"nm-173","scope":"NM","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New Mexico, you want to pass a slow car, but there is a railroad crossing just ahead. What should you do?","o":["Pass quickly before the crossing","Pass if no train is in sight","Pass on the right side","Do not pass"],"h1":"The car you pass can block your view of a train.","h2":"In New Mexico, do not pass if there is a railroad grade crossing ahead.","p":"Right. Do not pass near a railroad crossing."},"es":{"q":"En Nuevo México, usted quiere rebasar a un carro lento, pero hay un cruce de tren justo adelante. ¿Qué debe hacer?","o":["Rebasar rápido antes del cruce","Rebasar si no se ve ningún tren","Rebasar por la derecha","No rebasar"],"h1":"El carro que rebasa puede taparle la vista de un tren.","h2":"En Nuevo México, no rebase si hay un cruce de tren adelante.","p":"Correcto. No rebase cerca de un cruce de tren."},"ref":{"doc":"NM","page":25}},{"id":"nm-174","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, a bicyclist is riding in the center of the traffic lane. What does the manual say about this?","o":["It is legal when needed, such as to get ready for a left turn","It is never legal; bicycles must stay at the right edge","It is legal only on interstate highways","It is legal only when no cars are on the road"],"h1":"Think about a bicyclist who needs to turn left.","h2":"In New Mexico, bicyclists usually stay on the right, but they may legally take the whole lane when needed, for example to prepare for a left turn, to avoid being squeezed on a narrow street, or to avoid hazards.","p":"Right. A bicyclist may take the whole lane when needed."},"es":{"q":"En Nuevo México, un ciclista va por el centro del carril. ¿Qué dice el manual sobre esto?","o":["Es legal cuando hace falta, por ejemplo para prepararse para girar a la izquierda","Nunca es legal; las bicicletas deben ir pegadas a la orilla derecha","Solo es legal en las autopistas interestatales","Solo es legal cuando no hay carros en la calle"],"h1":"Piense en un ciclista que necesita girar a la izquierda.","h2":"En Nuevo México, los ciclistas suelen ir a la derecha, pero pueden usar legalmente todo el carril cuando hace falta, por ejemplo para prepararse para girar a la izquierda, para que no los aprieten en una calle angosta o para evitar peligros.","p":"Correcto. Un ciclista puede usar todo el carril cuando hace falta."},"ref":{"doc":"NM","page":25}},{"id":"nm-175","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, what lighting must a bicyclist use at night?","o":["Only a bell","A license plate light","A bright headlight and a good rear reflector","No lights; bright reflective clothes are enough at night"],"h1":"Others must see the bicycle from the front and from behind.","h2":"In New Mexico, bicyclists must obey the same rules as drivers, including using a bright headlight and a good rear reflector at night.","p":"Right. A bright headlight and a good rear reflector."},"es":{"q":"En Nuevo México, ¿qué luces debe usar un ciclista de noche?","o":["Solo un timbre","Una luz para placa","Una luz delantera brillante y un buen reflector trasero","Ninguna luz; de noche basta con ropa reflejante de colores vivos"],"h1":"Los demás deben ver la bicicleta de frente y por detrás.","h2":"En Nuevo México, los ciclistas deben cumplir las mismas reglas que los conductores, incluso usar de noche una luz delantera brillante y un buen reflector trasero.","p":"Correcto. Luz delantera brillante y buen reflector trasero."},"ref":{"doc":"NM","page":26}},{"id":"nm-176","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, on a long trip, about how often should you stop for a break?","o":["Every hour or so","Every four hours","Only when you need gas","Once a day"],"h1":"Short, frequent breaks help you stay alert.","h2":"In New Mexico, to keep from getting tired on a long trip, stop every hour or so, or whenever you need to.","p":"Right. Take a break every hour or so."},"es":{"q":"En Nuevo México, en un viaje largo, ¿más o menos cada cuánto debe parar a descansar?","o":["Más o menos cada hora","Cada cuatro horas","Solo cuando necesite gasolina","Una vez al día"],"h1":"Las paradas cortas y frecuentes le ayudan a estar alerta.","h2":"En Nuevo México, para no cansarse en un viaje largo, pare más o menos cada hora, o cuando lo necesite.","p":"Correcto. Descanse más o menos cada hora."},"ref":{"doc":"NM","page":28}},{"id":"nm-177","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, according to the manual, with how many drinks in your bloodstream are you impaired and could be arrested?","o":["Four or more","Five or more","Only more than six","Two or more"],"h1":"The manual says even one drink can affect your driving.","h2":"In New Mexico, the manual says even one drink can affect your driving, and with two or more drinks in your bloodstream you are impaired and could be arrested.","p":"Right. Two or more drinks can get you arrested."},"es":{"q":"En Nuevo México, según el manual, ¿con cuántas bebidas en la sangre está usted afectado y lo pueden arrestar?","o":["Con cuatro o más","Con cinco o más","Solo con más de seis","Con dos o más"],"h1":"El manual dice que hasta una sola bebida puede afectar su manejo.","h2":"En Nuevo México, el manual dice que hasta una bebida puede afectar su manejo, y con dos o más bebidas en la sangre usted está afectado y lo pueden arrestar.","p":"Correcto. Con dos o más bebidas lo pueden arrestar."},"ref":{"doc":"NM","page":29}},{"id":"nm-178","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you are 20 years old. What does the law say about alcohol?","o":["You may drink it at home but not buy it","You may not buy it, drink it or have it","You may have it if an adult bought it","You may drink beer or wine, but not hard liquor"],"h1":"The age for all three is the same.","h2":"In New Mexico, you are not allowed to buy, drink or have alcohol unless you are 21 years of age.","p":"Right. Under 21, no buying, drinking or having alcohol."},"es":{"q":"En Nuevo México, usted tiene 20 años. ¿Qué dice la ley sobre el alcohol?","o":["Puede tomarlo en casa, pero no comprarlo","No puede comprarlo, tomarlo ni tenerlo","Puede tenerlo si un adulto lo compró","Puede tomar cerveza o vino, pero no licor fuerte"],"h1":"La edad es la misma para las tres cosas.","h2":"En Nuevo México, no puede comprar, tomar ni tener alcohol si no tiene 21 años.","p":"Correcto. Con menos de 21, no puede comprar, tomar ni tener alcohol."},"ref":{"doc":"NM","page":29}},{"id":"nm-179","scope":"NM","cat":"licensing","sign":null,"c":1,"en":{"q":"In New Mexico, how is your blood alcohol content (BAC) usually measured?","o":["By how many drinks you tell the officer you had","With a breath, blood or urine test","With a vision test","By how fast you were driving"],"h1":"It is a test of your body.","h2":"In New Mexico, BAC is the percentage of alcohol in your blood, and it is usually found with a breath, blood or urine test.","p":"Right. A breath, blood or urine test."},"es":{"q":"En Nuevo México, ¿cómo se mide normalmente el contenido de alcohol en la sangre (BAC)?","o":["Por cuántas bebidas le dice usted al policía que tomó","Con una prueba de aliento, de sangre o de orina","Con un examen de la vista","Por lo rápido que iba manejando"],"h1":"Es una prueba de su cuerpo.","h2":"En Nuevo México, el BAC es el porcentaje de alcohol en la sangre, y normalmente se mide con una prueba de aliento, de sangre o de orina.","p":"Correcto. Una prueba de aliento, de sangre o de orina."},"ref":{"doc":"NM","page":29}},{"id":"nm-180","scope":"NM","cat":"licensing","sign":null,"c":3,"en":{"q":"In New Mexico, a driver has epilepsy, diabetes or a serious heart condition. What must the driver send to the MVD from time to time?","o":["A new license photo","Proof that you took a new driving safety course","A letter from an employer","A medical statement signed by a doctor"],"h1":"It comes from the person who treats the condition.","h2":"In New Mexico, drivers with epilepsy, diabetes, heart conditions and other medical problems must send the MVD periodic medical statements signed by their doctors.","p":"Right. A medical statement signed by a doctor."},"es":{"q":"En Nuevo México, un conductor tiene epilepsia, diabetes o un problema serio del corazón. ¿Qué debe mandar a la MVD de vez en cuando?","o":["Una foto nueva para la licencia","Prueba de que tomó un nuevo curso de seguridad al manejar","Una carta de su empleador","Una declaración médica firmada por un doctor"],"h1":"Viene de la persona que trata la enfermedad.","h2":"En Nuevo México, los conductores con epilepsia, diabetes, problemas del corazón y otros problemas médicos deben mandar a la MVD, cada cierto tiempo, declaraciones médicas firmadas por su doctor.","p":"Correcto. Una declaración médica firmada por un doctor."},"ref":{"doc":"NM","page":30}},{"id":"nm-181","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, you need to make a phone call while you are driving. What does the manual say to do when possible?","o":["Pull over to the side of the road first","Make calls only while stopped at red lights","Talk only on straight roads","Hold the phone low, below the window"],"h1":"Even talking can take your mind off the road.","h2":"In New Mexico, the manual says to pull over to the side of the road to place or take a call whenever possible, and notes that some towns allow phones while driving only with a hands-free device.","p":"Right. Pull over to make or take a call."},"es":{"q":"En Nuevo México, usted necesita hacer una llamada mientras maneja. ¿Qué dice el manual que haga cuando sea posible?","o":["Orillarse a un lado del camino primero","Hacer llamadas solo cuando esté parado en un semáforo en rojo","Hablar solo en caminos rectos","Sostener el teléfono abajo, debajo de la ventana"],"h1":"Hasta hablar puede quitarle la atención del camino.","h2":"En Nuevo México, el manual dice que se orille para hacer o contestar una llamada siempre que pueda, y que en algunos pueblos solo se permite el teléfono al manejar con un aparato de manos libres.","p":"Correcto. Oríllese para hacer o contestar una llamada."},"ref":{"doc":"NM","page":30}},{"id":"nm-182","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, a collision looks likely. What three options does the manual say drivers have?","o":["Honk, flash your lights or stop","Stop, back up or wait","Stop, turn or speed up","Brake, close your eyes or let go"],"h1":"One of them is to get out of the way faster.","h2":"In New Mexico, to avoid a collision, drivers have three options: stop, turn or speed up.","p":"Right. Stop, turn or speed up."},"es":{"q":"En Nuevo México, parece que va a haber un choque. ¿Qué tres opciones dice el manual que tienen los conductores?","o":["Tocar la bocina, hacer cambio de luces o detenerse","Detenerse, echarse en reversa o esperar","Detenerse, girar o acelerar","Frenar, cerrar los ojos o soltar el volante"],"h1":"Una de ellas es quitarse del camino más rápido.","h2":"En Nuevo México, para evitar un choque, los conductores tienen tres opciones: detenerse, girar o acelerar.","p":"Correcto. Detenerse, girar o acelerar."},"ref":{"doc":"NM","page":32}},{"id":"nm-183","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, your car has no anti-lock brakes (ABS). You brake hard in an emergency and the wheels lock. What should you do?","o":["Keep pressing the brake as hard as you can","Shift into neutral","Quickly let up on the brake, then press it again","Pull the parking brake hard"],"h1":"Locked wheels make the car skid.","h2":"In New Mexico, without ABS, if the brakes lock and the car starts to skid, quickly let up on the brake pedal, then push it down again as soon as the skid stops, and repeat until you stop.","p":"Right. Let up, then press again."},"es":{"q":"En Nuevo México, su carro no tiene frenos antibloqueo (ABS). Usted frena fuerte en una emergencia y las llantas se bloquean. ¿Qué debe hacer?","o":["Seguir pisando el freno con toda su fuerza","Poner el carro en neutral","Soltar rápido el freno y luego volver a pisarlo","Jalar fuerte el freno de mano"],"h1":"Las llantas bloqueadas hacen que el carro derrape.","h2":"En Nuevo México, sin ABS, si los frenos se bloquean y el carro empieza a derrapar, suelte rápido el pedal del freno, vuelva a pisarlo en cuanto deje de derrapar, y repita hasta detenerse.","p":"Correcto. Suelte y vuelva a pisar."},"ref":{"doc":"NM","page":32}},{"id":"nm-184","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, to avoid a collision, which can you usually do more quickly: stop your car or turn it?","o":["Turn it","Stop it","Both always take the same time","It depends only on the weather"],"h1":"Think about steering around a problem.","h2":"In New Mexico, the manual says that in most cases you can turn the vehicle more quickly than you can stop it, so think about turning to avoid a collision.","p":"Right. You can usually turn faster than you can stop."},"es":{"q":"En Nuevo México, para evitar un choque, ¿qué puede hacer normalmente más rápido: detener su carro o girarlo?","o":["Girarlo","Detenerlo","Las dos cosas siempre toman el mismo tiempo","Depende solo del clima"],"h1":"Piense en esquivar un problema con el volante.","h2":"En Nuevo México, el manual dice que casi siempre puede girar el vehículo más rápido de lo que puede detenerlo, así que piense en girar para evitar un choque.","p":"Correcto. Normalmente puede girar más rápido de lo que puede detenerse."},"ref":{"doc":"NM","page":32}},{"id":"nm-185","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, your car is about to be hit from behind. What should you do?","o":["Lean forward toward the steering wheel","Press back against your seat, with your head against the head restraint","Turn around to look at the other car","Take your hands off the wheel"],"h1":"Your body will be thrown backward.","h2":"In New Mexico, if you are about to be hit from the rear, press yourself against the back of your seat, put your head against the head restraint, and be ready to brake.","p":"Right. Press back against the seat and head restraint."},"es":{"q":"En Nuevo México, están a punto de chocarle por detrás. ¿Qué debe hacer?","o":["Inclinarse hacia el volante","Apoyarse contra el respaldo, con la cabeza contra la cabecera","Voltearse para ver el otro carro","Soltar el volante"],"h1":"Su cuerpo será lanzado hacia atrás.","h2":"En Nuevo México, si le van a chocar por detrás, apóyese contra el respaldo del asiento, ponga la cabeza contra la cabecera y esté listo para frenar.","p":"Correcto. Apóyese contra el respaldo y la cabecera."},"ref":{"doc":"NM","page":33}},{"id":"nm-186","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, you hear about a crash with a fire a few streets away. Should you drive there to look?","o":["Yes, to see whether you can help","No, you may block police, fire trucks and ambulances","Yes, if you park on the shoulder","Only if it is on your way home"],"h1":"Think about the rescue vehicles that need to get there.","h2":"In New Mexico, never drive to the scene of a crash, fire or other disaster just to look, because you may block police, firefighters, ambulances and other rescue vehicles.","p":"Right. Do not go just to look."},"es":{"q":"En Nuevo México, usted se entera de un choque con incendio a unas calles. ¿Debe ir manejando para ver?","o":["Sí, para ver si puede ayudar","No, puede estorbar a la policía, los bomberos y las ambulancias","Sí, si se estaciona en el acotamiento","Solo si le queda de camino a casa"],"h1":"Piense en los vehículos de rescate que tienen que llegar.","h2":"En Nuevo México, nunca maneje hacia un choque, incendio u otro desastre solo para mirar, porque puede bloquearles el paso a la policía, los bomberos, las ambulancias y otros vehículos de rescate.","p":"Correcto. No vaya solo para mirar."},"ref":{"doc":"NM","page":33}},{"id":"nm-187","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, you are at a crash scene. What should be done about the wrecked vehicles?","o":["Start their engines to move them","Push them away with your own car","Open their fuel caps","Turn off their ignitions and do not smoke near them"],"h1":"Fuel may have spilled.","h2":"In New Mexico, at a crash scene, turn off the ignition of wrecked vehicles and do not smoke around them, because fuel could have spilled and fire is a real danger.","p":"Right. Turn off the ignitions and do not smoke."},"es":{"q":"En Nuevo México, usted está en el lugar de un choque. ¿Qué se debe hacer con los vehículos chocados?","o":["Encender sus motores para moverlos","Empujarlos con su propio carro","Abrirles el tapón de la gasolina","Apagarles el motor y no fumar cerca de ellos"],"h1":"Puede haberse derramado gasolina.","h2":"En Nuevo México, en un choque, apague el encendido de los vehículos chocados y no fume cerca de ellos, porque puede haberse derramado gasolina y el fuego es un peligro real.","p":"Correcto. Apague los motores y no fume."},"ref":{"doc":"NM","page":34}},{"id":"nm-188","scope":"NM","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New Mexico, at a crash, power lines are down with wires lying in the road. What should you do?","o":["Stay away from them","Move them off the road with a stick","Drive over them slowly","Move them by hand if you wear gloves"],"h1":"Downed wires can kill.","h2":"In New Mexico, if power lines are down at a crash scene with wires in the road, do not go near them.","p":"Right. Stay away from downed wires."},"es":{"q":"En Nuevo México, en un choque hay cables de luz caídos sobre la calle. ¿Qué debe hacer?","o":["Mantenerse lejos de ellos","Quitarlos de la calle con un palo","Pasarles por encima despacio","Moverlos con la mano si trae guantes"],"h1":"Los cables caídos pueden matar.","h2":"En Nuevo México, si en un choque hay cables de luz caídos sobre la calle, no se acerque a ellos.","p":"Correcto. Manténgase lejos de los cables caídos."},"ref":{"doc":"NM","page":34}},{"id":"nm-189","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, a person hurt in a crash is bleeding. What should you do?","o":["Give the person some water","Help the person walk around","Press directly on the wound with your hand or a cloth","Wait for the bleeding to stop by itself"],"h1":"Even heavy bleeding can usually be slowed this way.","h2":"In New Mexico, if an injured person is bleeding, apply pressure directly on the wound with your hand or a cloth; this almost always stops or slows even severe bleeding.","p":"Right. Press directly on the wound."},"es":{"q":"En Nuevo México, una persona herida en un choque está sangrando. ¿Qué debe hacer?","o":["Darle un poco de agua","Ayudarle a caminar","Presionar directo sobre la herida con la mano o con un trapo","Esperar a que la sangre pare sola"],"h1":"Así casi siempre se puede frenar hasta una hemorragia fuerte.","h2":"En Nuevo México, si una persona herida está sangrando, presione directo sobre la herida con la mano o con un trapo; casi siempre así se detiene o se reduce hasta una hemorragia fuerte.","p":"Correcto. Presione directo sobre la herida."},"ref":{"doc":"NM","page":34}},{"id":"nm-190","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, on a motorcycle, which brakes should you use when you slow or stop normally?","o":["Only the rear brake, so the front wheel never locks","Only the front brake","Both the front and rear brakes, every time","Neither; just close the throttle"],"h1":"Using one brake for normal stops builds a bad habit.","h2":"In New Mexico, motorcycle riders should use both brakes every time they slow or stop, so they build the habit and skill of using the front brake in an emergency.","p":"Right. Use both brakes every time."},"es":{"q":"En Nuevo México, en motocicleta, ¿qué frenos debe usar para bajar la velocidad o parar normalmente?","o":["Solo el freno trasero, para que la rueda delantera nunca se bloquee","Solo el freno delantero","Los dos, el delantero y el trasero, cada vez","Ninguno; solo cerrar el acelerador"],"h1":"Usar un solo freno en paradas normales crea un mal hábito.","h2":"En Nuevo México, los motociclistas deben usar los dos frenos cada vez que bajan la velocidad o se detienen, para tener el hábito y la habilidad de usar el freno delantero en una emergencia.","p":"Correcto. Use los dos frenos cada vez."},"ref":{"doc":"NM","page":35}},{"id":"nm-191","scope":"NM","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New Mexico, you ride a motorcycle and are getting ready to pass a car. Where in your lane should you ride before you pass?","o":["In the left part of the lane, at a safe following distance","In the right part, close behind the car","In the center, right behind the car","On the shoulder"],"h1":"This lets you see farther ahead and be seen.","h2":"In New Mexico, before passing on a motorcycle, ride in the left portion of the lane at a safe following distance to see farther ahead and be more visible.","p":"Right. Ride in the left part of the lane before passing."},"es":{"q":"En Nuevo México, usted va en motocicleta y se prepara para rebasar a un carro. ¿En qué parte de su carril debe ir antes de rebasar?","o":["En la parte izquierda del carril, a una distancia segura","En la parte derecha, muy cerca detrás del carro","En el centro, justo detrás del carro","En el acotamiento"],"h1":"Así ve más lejos hacia adelante y le ven mejor.","h2":"En Nuevo México, antes de rebasar en motocicleta, vaya en la parte izquierda del carril a una distancia segura para ver más adelante y que le vean mejor.","p":"Correcto. Vaya en la parte izquierda del carril antes de rebasar."},"ref":{"doc":"NM","page":35}},{"id":"nm-192","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, you ride a motorcycle past a row of parked cars. Where in your lane should you ride?","o":["Toward the right side, close to the cars","On the right shoulder","Weaving between the parked cars","Toward the left side of the lane"],"h1":"Car doors can open and people can step out.","h2":"In New Mexico, when passing parked cars on a motorcycle, stay toward the left of your lane to avoid opening doors, drivers getting out and people stepping from between cars.","p":"Right. Stay toward the left of your lane."},"es":{"q":"En Nuevo México, usted va en motocicleta junto a una fila de carros estacionados. ¿En qué parte de su carril debe ir?","o":["Hacia el lado derecho, cerca de los carros","Por el acotamiento derecho","Zigzagueando entre los carros estacionados","Hacia el lado izquierdo del carril"],"h1":"Se pueden abrir puertas y puede bajarse gente.","h2":"En Nuevo México, al pasar junto a carros estacionados en motocicleta, vaya hacia la izquierda de su carril para evitar puertas que se abren, conductores que se bajan y personas que salen de entre los carros.","p":"Correcto. Vaya hacia la izquierda de su carril."},"ref":{"doc":"NM","page":36}},{"id":"nm-193","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, what standards should a motorcycle helmet meet?","o":["Bicycle helmet standards","U.S. Department of Transportation (DOT) standards","No standard, if it looks strong","The same standards as hard hats worn on building sites"],"h1":"Look for a label from a federal agency.","h2":"In New Mexico, for the most protection a motorcycle helmet should meet U.S. Department of Transportation (DOT) standards, fit snugly and have no obvious defects.","p":"Right. It should meet DOT standards."},"es":{"q":"En Nuevo México, ¿qué normas debe cumplir un casco de motocicleta?","o":["Las normas de cascos de bicicleta","Las normas del Departamento de Transporte de EE. UU. (DOT)","Ninguna, si se ve resistente","Las mismas normas que los cascos de las obras de construcción"],"h1":"Busque la etiqueta de una agencia federal.","h2":"En Nuevo México, para la mayor protección, un casco de motocicleta debe cumplir las normas del Departamento de Transporte de EE. UU. (DOT), quedar ajustado y no tener defectos visibles.","p":"Correcto. Debe cumplir las normas DOT."},"ref":{"doc":"NM","page":37}},{"id":"nm-194","scope":"NM","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New Mexico, a group of motorcycles rides in a staggered formation. Where does the second rider ride?","o":["Right beside the leader","One second behind the leader, on the right side of the lane","Two seconds behind, on the left side of the lane","Directly behind the leader, in the same track"],"h1":"The leader rides on the left side of the lane.","h2":"In New Mexico, in a staggered formation the leader rides on the left side of the lane, and the second rider stays one second behind on the right side.","p":"Right. One second behind, on the right side."},"es":{"q":"En Nuevo México, un grupo de motocicletas va en formación escalonada. ¿Dónde va el segundo motociclista?","o":["Justo al lado del líder","Un segundo detrás del líder, en el lado derecho del carril","Dos segundos detrás, en el lado izquierdo del carril","Justo detrás del líder, en la misma línea"],"h1":"El líder va en el lado izquierdo del carril.","h2":"En Nuevo México, en la formación escalonada el líder va en el lado izquierdo del carril, y el segundo motociclista va un segundo detrás, en el lado derecho.","p":"Correcto. Un segundo detrás, en el lado derecho."},"ref":{"doc":"NM","page":38}},{"id":"nm-195","scope":"NM","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New Mexico, when should a group of motorcycles change to single file?","o":["On long, straight highways","Whenever it is dark","While stopped at a red light","On curves, when turning, and when entering or leaving a highway"],"h1":"Think of the moments when riders need the most room.","h2":"In New Mexico, it is best for a motorcycle group to ride single file on curves, when turning, and when entering or leaving a highway.","p":"Right. Single file on curves, turns, and highway entries and exits."},"es":{"q":"En Nuevo México, ¿cuándo debe un grupo de motocicletas ponerse en fila india?","o":["En carreteras largas y rectas","Siempre que esté oscuro","Mientras esperan en un semáforo en rojo","En curvas, al girar y al entrar o salir de una carretera"],"h1":"Piense en los momentos en que los motociclistas necesitan más espacio.","h2":"En Nuevo México, lo mejor es que un grupo de motocicletas vaya en fila india en las curvas, al girar y al entrar o salir de una carretera.","p":"Correcto. En fila india en curvas, giros y entradas y salidas de carretera."},"ref":{"doc":"NM","page":38}},{"id":"nm-196","scope":"NM","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New Mexico, what are the two biggest dangers for a motorcyclist at intersections?","o":["Oncoming cars turning left, and cars pulling out of side streets","People walking and people on bicycles","Trucks and buses passing from behind","Painted lines and potholes"],"h1":"Both are cars that move into the rider's path.","h2":"In New Mexico, oncoming cars that turn left in front of a motorcyclist, and cars on side streets that pull into the rider's lane, are the two biggest dangers at intersections.","p":"Right. Left-turning cars and cars from side streets."},"es":{"q":"En Nuevo México, ¿cuáles son los dos mayores peligros para un motociclista en las intersecciones?","o":["Los carros de enfrente que giran a la izquierda y los carros que salen de calles laterales","Las personas que caminan y las que van en bicicleta","Los camiones y autobuses que rebasan por detrás","Las líneas pintadas y los baches"],"h1":"Los dos son carros que se meten en el camino del motociclista.","h2":"En Nuevo México, los carros de enfrente que giran a la izquierda delante del motociclista y los carros de calles laterales que se meten a su carril son los dos mayores peligros en las intersecciones.","p":"Correcto. Los carros que giran a la izquierda y los que salen de calles laterales."},"ref":{"doc":"NM","page":39}},{"id":"nm-197","scope":"NM","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New Mexico, you are riding a motorcycle and a car is passing you. Which part of your lane should you ride in?","o":["The part closest to the passing car","The part farthest from the passing car","The center part","The shoulder"],"h1":"Moving away can invite the driver to cut back in too early.","h2":"In New Mexico, when you are being passed on a motorcycle, stay in the center portion of your lane; moving to the far side may invite the other driver to cut back in too early.","p":"Right. Stay in the center of your lane."},"es":{"q":"En Nuevo México, usted va en motocicleta y un carro le está rebasando. ¿En qué parte de su carril debe ir?","o":["En la parte más cerca del carro que rebasa","En la parte más lejos del carro que rebasa","En la parte del centro","En el acotamiento"],"h1":"Alejarse puede invitar al otro conductor a meterse antes de tiempo.","h2":"En Nuevo México, cuando le rebasan en motocicleta, quédese en la parte del centro de su carril; irse al lado más lejano puede invitar al otro conductor a regresar a su carril antes de tiempo.","p":"Correcto. Quédese en el centro de su carril."},"ref":{"doc":"NM","page":39}},{"id":"nv-001","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is a half year past a birthday.","h2":"In Nevada you can get an instruction permit at 15 and a half years old.","p":"Right. Nevada permits start at 15 and a half."},"es":{"q":"En Nevada, ¿cuál es la edad mínima para obtener un permiso de instrucción?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año después de un cumpleaños.","h2":"En Nevada usted puede obtener el permiso de instrucción a los 15 años y medio.","p":"Correcto. El permiso en Nevada empieza a los 15 años y medio."},"zh":{"q":"在 Nevada，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它是过了某个生日半年。","h2":"在 Nevada，你 15 岁半就可以拿到学习驾照。","p":"对。Nevada 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Nevada, tuổi nhỏ nhất để được cấp giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm sau một ngày sinh nhật.","h2":"Ở Nevada, bạn có thể được cấp giấy phép tập lái khi 15 tuổi rưỡi.","p":"Đúng. Ở Nevada, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Nevada, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito pagkatapos ng isang kaarawan.","h2":"Sa Nevada, makakakuha ka ng instruction permit sa edad na 15 at kalahati.","p":"Tama. Sa Nevada, nagsisimula ang permit sa edad na 15 at kalahati."},"ar":{"q":"في Nevada، ما أصغر عمر للحصول على تصريح تعلّم القيادة (instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة بعد يوم ميلاد.","h2":"في Nevada يمكنك الحصول على تصريح تعلّم القيادة في عمر 15 سنة ونصف.","p":"صحيح. في Nevada يبدأ تصريح التعلّم من عمر 15 سنة ونصف."},"ref":{"doc":"NV","page":15}},{"id":"nv-002","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is an instruction permit valid?","o":["Six months","One year","Two years","Until age 18"],"h1":"It lasts one trip around the calendar.","h2":"A Nevada instruction permit is valid for one year.","p":"Right. The permit lasts one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Seis meses","Un año","Dos años","Hasta los 18 años"],"h1":"Dura una vuelta completa al calendario.","h2":"En Nevada, el permiso de instrucción es válido por un año.","p":"Correcto. El permiso dura un año."},"zh":{"q":"在 Nevada，学习驾照有效期多久？","o":["六个月","一年","两年","到 18 岁"],"h1":"它是日历走一整圈的时间。","h2":"Nevada 的学习驾照有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Nevada, giấy phép tập lái có giá trị trong bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Cho đến 18 tuổi"],"h1":"Nó kéo dài trọn một vòng lịch.","h2":"Giấy phép tập lái ở Nevada có giá trị trong một năm.","p":"Đúng. Giấy phép có giá trị một năm."},"tl":{"q":"Sa Nevada, gaano katagal valid ang instruction permit?","o":["Anim na buwan","Isang taon","Dalawang taon","Hanggang edad 18"],"h1":"Tumatagal ito ng isang buong ikot ng kalendaryo.","h2":"Ang Nevada instruction permit ay valid nang isang taon.","p":"Tama. Tumatagal nang isang taon ang permit."},"ar":{"q":"في Nevada، كم مدة صلاحية تصريح تعلّم القيادة؟","o":["ستة أشهر","سنة واحدة","سنتان","حتى عمر 18 سنة"],"h1":"يدوم دورة كاملة في التقويم.","h2":"تصريح تعلّم القيادة في Nevada صالح لمدة سنة واحدة.","p":"صحيح. التصريح صالح لمدة سنة واحدة."},"ref":{"doc":"NV","page":15}},{"id":"nv-003","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how many supervised driving hours must a teen complete, and how many at night?","o":["50 hours, 10 at night","30 hours, 5 at night","40 hours, 15 at night","100 hours, 20 at night"],"h1":"The night hours are one fifth of the total.","h2":"A Nevada teen must complete at least 50 hours of supervised driving, and 10 of those hours must be at night.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Nevada, ¿cuántas horas de manejo supervisado debe completar un adolescente, y cuántas de noche?","o":["50 horas, 10 de noche","30 horas, 5 de noche","40 horas, 15 de noche","100 horas, 20 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Nevada, un adolescente debe completar por lo menos 50 horas de manejo supervisado, y 10 de ellas deben ser de noche.","p":"Correcto. Cincuenta horas, diez de noche."},"zh":{"q":"在 Nevada，青少年必须完成多少小时有人监督的驾驶，其中多少小时在晚上？","o":["50 小时，10 小时在晚上","30 小时，5 小时在晚上","40 小时，15 小时在晚上","100 小时，20 小时在晚上"],"h1":"晚上的时间是全部时间的五分之一。","h2":"Nevada 的青少年必须完成至少 50 小时有人监督的驾驶，其中 10 小时必须在晚上。","p":"对。五十小时，十小时在晚上。"},"vi":{"q":"Ở Nevada, thiếu niên phải hoàn thành bao nhiêu giờ lái xe có người giám sát, và bao nhiêu giờ vào ban đêm?","o":["50 giờ, 10 giờ ban đêm","30 giờ, 5 giờ ban đêm","40 giờ, 15 giờ ban đêm","100 giờ, 20 giờ ban đêm"],"h1":"Số giờ ban đêm bằng một phần năm tổng số giờ.","h2":"Ở Nevada, thiếu niên phải lái xe có người giám sát ít nhất 50 giờ, và 10 giờ trong số đó phải vào ban đêm.","p":"Đúng. Năm mươi giờ, mười giờ vào ban đêm."},"tl":{"q":"Sa Nevada, ilang oras ng supervised na pagmamaneho ang dapat tapusin ng isang tinedyer, at ilan dito ang sa gabi?","o":["50 oras, 10 sa gabi","30 oras, 5 sa gabi","40 oras, 15 sa gabi","100 oras, 20 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Nevada, ang tinedyer ay dapat magmaneho nang hindi bababa sa 50 oras na may gumagabay, at 10 sa mga oras na iyon ay dapat sa gabi.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Nevada، كم ساعة من القيادة تحت الإشراف يجب أن يُكمل المراهق، وكم منها في الليل؟","o":["50 ساعة، منها 10 في الليل","30 ساعة، منها 5 في الليل","40 ساعة، منها 15 في الليل","100 ساعة، منها 20 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Nevada يجب أن يُكمل المراهق 50 ساعة على الأقل من القيادة تحت الإشراف، و10 ساعات منها يجب أن تكون في الليل.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"NV","page":14}},{"id":"nv-004","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, who may supervise a teen's practice driving?","o":["Any person with a permit","Any adult over 18","A licensed driver over 25 only","A licensed driver at least 21 who has been licensed at least one year"],"h1":"There is a rule about age and a rule about experience.","h2":"In Nevada, a teen may practice with any licensed driver who is at least 21 and has held a license for at least one year.","p":"Right. At least 21, and licensed for at least a year."},"es":{"q":"En Nevada, ¿quién puede supervisar la práctica de manejo de un adolescente?","o":["Cualquier persona con permiso","Cualquier adulto mayor de 18","Solo un conductor con licencia mayor de 25","Un conductor con licencia de por lo menos 21 años y con licencia desde hace por lo menos un año"],"h1":"Hay una regla de edad y otra de experiencia.","h2":"En Nevada, un adolescente puede practicar con cualquier conductor con licencia que tenga por lo menos 21 años y haya tenido licencia por lo menos un año.","p":"Correcto. Por lo menos 21 años y un año con licencia."},"zh":{"q":"在 Nevada，谁可以监督青少年练习开车？","o":["任何有学习驾照的人","任何 18 岁以上的成年人","只有 25 岁以上、有驾照的司机","至少 21 岁、有驾照至少一年的司机"],"h1":"有一条关于年龄的规定，还有一条关于经验的规定。","h2":"在 Nevada，青少年可以和任何至少 21 岁、有驾照至少一年的司机一起练习。","p":"对。至少 21 岁，有驾照至少一年。"},"vi":{"q":"Ở Nevada, ai được giám sát thiếu niên khi tập lái?","o":["Bất kỳ ai có giấy phép tập lái","Bất kỳ người lớn nào trên 18 tuổi","Chỉ người có bằng lái trên 25 tuổi","Người có bằng lái từ 21 tuổi trở lên và đã có bằng ít nhất một năm"],"h1":"Có một quy định về tuổi và một quy định về kinh nghiệm.","h2":"Ở Nevada, thiếu niên có thể tập lái với bất kỳ người có bằng lái nào từ 21 tuổi trở lên và đã có bằng ít nhất một năm.","p":"Đúng. Ít nhất 21 tuổi, và đã có bằng lái ít nhất một năm."},"tl":{"q":"Sa Nevada, sino ang puwedeng gumabay sa pagsasanay magmaneho ng isang tinedyer?","o":["Kahit sinong may permit","Kahit sinong adulto na lampas 18","Lisensiyadong drayber na lampas 25 lamang","Lisensiyadong drayber na hindi bababa sa 21 taong gulang at may lisensya nang hindi bababa sa isang taon"],"h1":"May patakaran tungkol sa edad at may patakaran tungkol sa karanasan.","h2":"Sa Nevada, puwedeng magsanay ang tinedyer kasama ang kahit sinong lisensiyadong drayber na hindi bababa sa 21 taong gulang at may lisensya nang hindi bababa sa isang taon.","p":"Tama. Hindi bababa sa 21, at may lisensya nang hindi bababa sa isang taon."},"ar":{"q":"في Nevada، من يمكنه الإشراف على تدريب المراهق على القيادة؟","o":["أي شخص لديه تصريح تعلّم","أي شخص بالغ عمره أكثر من 18 سنة","سائق مرخّص عمره أكثر من 25 سنة فقط","سائق مرخّص عمره 21 سنة على الأقل ولديه رخصة منذ سنة على الأقل"],"h1":"هناك قاعدة عن العمر وقاعدة عن الخبرة.","h2":"في Nevada يمكن للمراهق أن يتدرّب مع أي سائق مرخّص عمره 21 سنة على الأقل ولديه رخصة منذ سنة على الأقل.","p":"صحيح. 21 سنة على الأقل، ورخصة منذ سنة على الأقل."},"ref":{"doc":"NV","page":15}},{"id":"nv-005","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, where must the experienced driver sit while a beginner practices?","o":["In the back seat","In the seat next to the beginner","Anywhere in the car","In a car following behind"],"h1":"They need to be close enough to help right away.","h2":"In Nevada, the experienced driver must sit in the seat next to the beginning driver.","p":"Right. The helper sits right beside you."},"es":{"q":"En Nevada, ¿dónde debe sentarse el conductor con experiencia mientras practica un principiante?","o":["En el asiento de atrás","En el asiento junto al principiante","En cualquier lugar del carro","En otro carro detrás"],"h1":"Debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Nevada, el conductor con experiencia debe ir sentado en el asiento junto al conductor principiante.","p":"Correcto. El acompañante va a su lado."},"zh":{"q":"在 Nevada，新手练习开车时，有经验的司机必须坐在哪里？","o":["后排座位","新手旁边的座位","车里任何地方","跟在后面的车里"],"h1":"他们需要离得够近，能马上帮忙。","h2":"在 Nevada，有经验的司机必须坐在新手司机旁边的座位。","p":"对。陪同的人就坐在你旁边。"},"vi":{"q":"Ở Nevada, người lái có kinh nghiệm phải ngồi ở đâu khi người mới tập lái?","o":["Ở ghế sau","Ở ghế ngay bên cạnh người mới tập","Ở bất kỳ chỗ nào trong xe","Trong một xe chạy phía sau"],"h1":"Họ cần ngồi đủ gần để giúp ngay lập tức.","h2":"Ở Nevada, người lái có kinh nghiệm phải ngồi ở ghế ngay bên cạnh người mới tập lái.","p":"Đúng. Người giúp ngồi ngay bên cạnh bạn."},"tl":{"q":"Sa Nevada, saan dapat umupo ang may-karanasang drayber habang nagsasanay ang baguhan?","o":["Sa likurang upuan","Sa upuan katabi ng baguhan","Kahit saan sa sasakyan","Sa sasakyang sumusunod sa likod"],"h1":"Kailangan silang malapit para makatulong agad.","h2":"Sa Nevada, ang may-karanasang drayber ay dapat umupo sa upuan katabi ng baguhang drayber.","p":"Tama. Nakaupo mismo sa tabi mo ang tumutulong."},"ar":{"q":"في Nevada، أين يجب أن يجلس السائق صاحب الخبرة أثناء تدريب السائق المبتدئ؟","o":["في المقعد الخلفي","في المقعد المجاور للمبتدئ","في أي مكان في السيارة","في سيارة تسير خلفه"],"h1":"يجب أن يكون قريبًا بما يكفي ليساعد فورًا.","h2":"في Nevada يجب أن يجلس السائق صاحب الخبرة في المقعد المجاور للسائق المبتدئ.","p":"صحيح. المساعد يجلس بجانبك مباشرة."},"ref":{"doc":"NV","page":15}},{"id":"nv-006","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how do a teen and parent prove the supervised driving hours?","o":["They take a photo of the car","No proof is needed","They keep a log of the dates and times of practice","They send text messages to the DMV"],"h1":"It is a written record.","h2":"In Nevada, the teen and a parent or guardian must keep a log of the dates and times of the supervised driving.","p":"Right. Keep a written log of your practice."},"es":{"q":"En Nevada, ¿cómo comprueban un adolescente y su padre las horas de manejo supervisado?","o":["Toman una foto del carro","No se necesita prueba","Llevan un registro de las fechas y horas de práctica","Mandan mensajes de texto al DMV"],"h1":"Es un registro escrito.","h2":"En Nevada, el adolescente y su padre, madre o tutor deben llevar un registro de las fechas y horas del manejo supervisado.","p":"Correcto. Lleve un registro escrito de su práctica."},"zh":{"q":"在 Nevada，青少年和父母怎样证明有人监督的驾驶时间？","o":["给车拍照","不需要证明","记录练习的日期和时间","给 DMV 发短信"],"h1":"它是书面记录。","h2":"在 Nevada，青少年和父母或监护人必须记录有人监督驾驶的日期和时间。","p":"对。把你的练习写下来做记录。"},"vi":{"q":"Ở Nevada, thiếu niên và cha mẹ chứng minh số giờ lái xe có giám sát bằng cách nào?","o":["Họ chụp ảnh chiếc xe","Không cần chứng minh","Họ ghi sổ ngày và giờ tập lái","Họ gửi tin nhắn cho DMV"],"h1":"Đó là một bản ghi chép bằng văn bản.","h2":"Ở Nevada, thiếu niên và cha mẹ hoặc người giám hộ phải ghi sổ (log) ngày và giờ của các buổi lái xe có giám sát.","p":"Đúng. Hãy ghi sổ các buổi tập lái của bạn."},"tl":{"q":"Sa Nevada, paano pinatutunayan ng tinedyer at magulang ang mga oras ng supervised na pagmamaneho?","o":["Kinukunan nila ng litrato ang sasakyan","Hindi kailangan ng patunay","Nagtatala sila ng log ng mga petsa at oras ng pagsasanay","Nagpapadala sila ng text message sa DMV"],"h1":"Isa itong nakasulat na talaan.","h2":"Sa Nevada, ang tinedyer at isang magulang o guardian ay dapat magtala ng log ng mga petsa at oras ng supervised na pagmamaneho.","p":"Tama. Magtala ng nakasulat na log ng iyong pagsasanay."},"ar":{"q":"في Nevada، كيف يُثبت المراهق والوالد ساعات القيادة تحت الإشراف؟","o":["يلتقطان صورة للسيارة","لا حاجة إلى إثبات","يحتفظان بسجلّ (log) لتواريخ وأوقات التدريب","يرسلان رسائل نصية إلى DMV"],"h1":"هو سجلّ مكتوب.","h2":"في Nevada يجب أن يحتفظ المراهق وأحد الوالدين أو الوصي بسجلّ لتواريخ وأوقات القيادة تحت الإشراف.","p":"صحيح. احتفظ بسجلّ مكتوب لتدريبك."},"ref":{"doc":"NV","page":13}},{"id":"nv-007","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, is driver education required to get an instruction permit?","o":["No, it is not required for the permit","Yes, always","Only for adults","Only in Las Vegas"],"h1":"It is required later, but not at the very first step.","h2":"In Nevada, driver education is not required to get an instruction permit.","p":"Right. The permit does not require driver education."},"es":{"q":"En Nevada, ¿se exige educación vial para obtener el permiso de instrucción?","o":["No, no se exige para el permiso","Sí, siempre","Solo para adultos","Solo en Las Vegas"],"h1":"Se exige más adelante, pero no en el primer paso.","h2":"En Nevada, no se exige educación vial para obtener el permiso de instrucción.","p":"Correcto. El permiso no exige educación vial."},"zh":{"q":"在 Nevada，拿学习驾照需要先上驾驶教育课程吗？","o":["不需要，拿学习驾照不需要","需要，一直都需要","只有成年人需要","只在 Las Vegas 需要"],"h1":"以后会需要，但第一步不需要。","h2":"在 Nevada，拿学习驾照不需要上驾驶教育课程。","p":"对。拿学习驾照不需要驾驶教育。"},"vi":{"q":"Ở Nevada, có bắt buộc học lớp lái xe (driver education) để được cấp giấy phép tập lái không?","o":["Không, không bắt buộc để có giấy phép tập lái","Có, luôn luôn bắt buộc","Chỉ đối với người lớn","Chỉ ở Las Vegas"],"h1":"Nó bắt buộc sau này, nhưng không phải ở bước đầu tiên.","h2":"Ở Nevada, không bắt buộc học lớp lái xe để được cấp giấy phép tập lái.","p":"Đúng. Giấy phép tập lái không đòi hỏi lớp lái xe."},"tl":{"q":"Sa Nevada, kailangan ba ang driver education para makakuha ng instruction permit?","o":["Hindi, hindi ito kailangan para sa permit","Oo, palagi","Para lamang sa mga adulto","Sa Las Vegas lamang"],"h1":"Kailangan ito sa bandang huli, pero hindi sa pinakaunang hakbang.","h2":"Sa Nevada, hindi kailangan ang driver education para makakuha ng instruction permit.","p":"Tama. Hindi kailangan ng permit ang driver education."},"ar":{"q":"في Nevada، هل دورة تعليم القيادة (driver education) مطلوبة للحصول على تصريح تعلّم القيادة؟","o":["لا، ليست مطلوبة للتصريح","نعم، دائمًا","للبالغين فقط","في Las Vegas فقط"],"h1":"هي مطلوبة لاحقًا، لكن ليس في الخطوة الأولى.","h2":"في Nevada لا تُطلب دورة تعليم القيادة للحصول على تصريح تعلّم القيادة.","p":"صحيح. التصريح لا يحتاج إلى دورة تعليم القيادة."},"ref":{"doc":"NV","page":15}},{"id":"nv-008","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, what must a parent or guardian sign when a teen applies for a permit?","o":["A school report card","A car title","A medical form","A financial responsibility statement"],"h1":"It is about who pays if something goes wrong.","h2":"In Nevada, a parent or guardian must be present to sign a financial responsibility statement for the teen's permit.","p":"Right. The parent signs for financial responsibility."},"es":{"q":"En Nevada, ¿qué debe firmar el padre, madre o tutor cuando un adolescente solicita el permiso?","o":["Una boleta de calificaciones","El título del carro","Un formulario médico","Una declaración de responsabilidad financiera"],"h1":"Tiene que ver con quién paga si algo sale mal.","h2":"En Nevada, el padre, madre o tutor debe estar presente para firmar una declaración de responsabilidad financiera para el permiso del adolescente.","p":"Correcto. El padre firma la responsabilidad financiera."},"zh":{"q":"在 Nevada，青少年申请学习驾照时，父母或监护人必须签什么？","o":["学校成绩单","汽车所有权证（title）","医疗表格","经济责任声明"],"h1":"它是关于出了事由谁付钱。","h2":"在 Nevada，父母或监护人必须到场，为青少年的学习驾照签一份经济责任声明。","p":"对。父母签经济责任声明。"},"vi":{"q":"Ở Nevada, khi thiếu niên xin giấy phép tập lái, cha mẹ hoặc người giám hộ phải ký giấy gì?","o":["Phiếu điểm ở trường","Giấy chủ quyền xe (car title)","Giấy khám sức khỏe","Bản cam kết trách nhiệm tài chính (financial responsibility statement)"],"h1":"Nó nói về ai sẽ trả tiền nếu có chuyện xảy ra.","h2":"Ở Nevada, cha mẹ hoặc người giám hộ phải có mặt để ký bản cam kết trách nhiệm tài chính cho giấy phép tập lái của thiếu niên.","p":"Đúng. Cha mẹ ký nhận trách nhiệm tài chính."},"tl":{"q":"Sa Nevada, ano ang dapat pirmahan ng magulang o guardian kapag nag-aaplay ng permit ang isang tinedyer?","o":["Report card sa paaralan","Titulo ng sasakyan (car title)","Medical na form","Financial responsibility statement (pahayag ng pananagutang pinansiyal)"],"h1":"Tungkol ito sa kung sino ang magbabayad kapag may nangyaring masama.","h2":"Sa Nevada, dapat naroroon ang magulang o guardian para pirmahan ang financial responsibility statement para sa permit ng tinedyer.","p":"Tama. Pumipirma ang magulang para sa pananagutang pinansiyal."},"ar":{"q":"في Nevada، ماذا يجب أن يوقّع الوالد أو الوصي عندما يتقدّم المراهق بطلب تصريح تعلّم القيادة؟","o":["شهادة الدرجات المدرسية","وثيقة ملكية السيارة (car title)","نموذج طبي","إقرار المسؤولية المالية (financial responsibility statement)"],"h1":"يتعلّق بمن يدفع إذا حدث شيء سيّئ.","h2":"في Nevada يجب أن يحضر الوالد أو الوصي ليوقّع إقرار المسؤولية المالية لتصريح المراهق.","p":"صحيح. الوالد يوقّع على المسؤولية المالية."},"ref":{"doc":"NV","page":null}},{"id":"nv-009","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, during which hours may a licensed driver under 18 not drive, unless going to or from a scheduled event?","o":["Midnight to 6 a.m.","10 p.m. to 5 a.m.","9 p.m. to 6 a.m.","11 p.m. to 4 a.m."],"h1":"It starts at ten at night.","h2":"In Nevada, a licensed driver under 18 may not drive between 10 p.m. and 5 a.m. unless going to or from a scheduled event such as work or school.","p":"Right. No driving from 10 p.m. to 5 a.m."},"es":{"q":"En Nevada, ¿en qué horario no puede manejar un conductor con licencia menor de 18 años, salvo para ir o volver de un evento programado?","o":["De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De 11 p.m. a 4 a.m."],"h1":"Empieza a las diez de la noche.","h2":"En Nevada, un conductor con licencia menor de 18 años no puede manejar entre las 10 p.m. y las 5 a.m., salvo para ir o volver de un evento programado como el trabajo o la escuela.","p":"Correcto. No se maneja de 10 p.m. a 5 a.m."},"zh":{"q":"在 Nevada，除非是去或离开预定的活动，未满 18 岁的有驾照司机在哪个时间段不能开车？","o":["午夜到早上 6 点","晚上 10 点到早上 5 点","晚上 9 点到早上 6 点","晚上 11 点到凌晨 4 点"],"h1":"它从晚上十点开始。","h2":"在 Nevada，未满 18 岁的有驾照司机在晚上 10 点到早上 5 点之间不能开车，除非是去或离开预定的活动，比如上班或上学。","p":"对。晚上 10 点到早上 5 点不能开车。"},"vi":{"q":"Ở Nevada, người có bằng lái dưới 18 tuổi không được lái xe trong khoảng giờ nào, trừ khi đi đến hoặc về từ một sự kiện đã lên lịch?","o":["Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","9 giờ tối đến 6 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Nó bắt đầu lúc mười giờ tối.","h2":"Ở Nevada, người có bằng lái dưới 18 tuổi không được lái xe từ 10 giờ tối đến 5 giờ sáng, trừ khi đi đến hoặc về từ một sự kiện đã lên lịch như đi làm hoặc đi học.","p":"Đúng. Không lái xe từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Nevada, sa anong mga oras hindi puwedeng magmaneho ang lisensiyadong drayber na wala pang 18, maliban kung papunta o pauwi mula sa nakatakdang event?","o":["Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","9 p.m. hanggang 6 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ito nang alas-diyes ng gabi.","h2":"Sa Nevada, ang lisensiyadong drayber na wala pang 18 ay hindi puwedeng magmaneho mula 10 p.m. hanggang 5 a.m., maliban kung papunta o pauwi mula sa nakatakdang event tulad ng trabaho o paaralan.","p":"Tama. Bawal magmaneho mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Nevada، في أي ساعات لا يجوز للسائق المرخّص الذي عمره أقل من 18 سنة أن يقود، إلا إذا كان ذاهبًا إلى حدث مُجدول أو عائدًا منه؟","o":["من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"تبدأ في الساعة العاشرة ليلًا.","h2":"في Nevada لا يجوز للسائق المرخّص الذي عمره أقل من 18 سنة أن يقود بين 10 مساءً و5 صباحًا، إلا إذا كان ذاهبًا إلى حدث مُجدول مثل العمل أو المدرسة أو عائدًا منه.","p":"صحيح. لا قيادة من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"NV","page":15}},{"id":"nv-010","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, for how long after getting a license may a teen not carry passengers under 18 who are not family?","o":["One month","Three months","Six months","Two years"],"h1":"It is half a year.","h2":"In Nevada, a new teen driver may not carry passengers under 18, except immediate family, for the first six months after getting a license.","p":"Right. The first six months."},"es":{"q":"En Nevada, ¿por cuánto tiempo después de obtener la licencia no puede un adolescente llevar pasajeros menores de 18 años que no sean familia?","o":["Un mes","Tres meses","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Nevada, un conductor adolescente nuevo no puede llevar pasajeros menores de 18 años, salvo familiares directos, durante los primeros seis meses con licencia.","p":"Correcto. Los primeros seis meses."},"zh":{"q":"在 Nevada，青少年拿到驾照后多久内，不能载不是家人、未满 18 岁的乘客？","o":["一个月","三个月","六个月","两年"],"h1":"它是半年。","h2":"在 Nevada，青少年新司机拿到驾照后的前六个月，不能载未满 18 岁的乘客，直系亲属除外。","p":"对。前六个月。"},"vi":{"q":"Ở Nevada, sau khi có bằng lái, thiếu niên không được chở hành khách dưới 18 tuổi không phải người nhà trong bao lâu?","o":["Một tháng","Ba tháng","Sáu tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Nevada, người lái trẻ mới có bằng không được chở hành khách dưới 18 tuổi, trừ người nhà trực tiếp, trong sáu tháng đầu sau khi có bằng lái.","p":"Đúng. Sáu tháng đầu tiên."},"tl":{"q":"Sa Nevada, gaano katagal pagkatapos makakuha ng lisensya na hindi puwedeng magsakay ang tinedyer ng mga pasaherong wala pang 18 na hindi kapamilya?","o":["Isang buwan","Tatlong buwan","Anim na buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Nevada, ang bagong tinedyer na drayber ay hindi puwedeng magsakay ng mga pasaherong wala pang 18, maliban sa malapit na kapamilya, sa unang anim na buwan pagkatapos makakuha ng lisensya.","p":"Tama. Ang unang anim na buwan."},"ar":{"q":"في Nevada، كم مدة بعد الحصول على الرخصة لا يجوز للمراهق أن ينقل ركّابًا أعمارهم أقل من 18 سنة وليسوا من العائلة؟","o":["شهر واحد","ثلاثة أشهر","ستة أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في Nevada لا يجوز للسائق المراهق الجديد أن ينقل ركّابًا أعمارهم أقل من 18 سنة، ما عدا أفراد العائلة المباشرين، في الأشهر الستة الأولى بعد الحصول على الرخصة.","p":"صحيح. الأشهر الستة الأولى."},"ref":{"doc":"NV","page":15}},{"id":"nv-011","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how many questions are on the car knowledge test, and how many must you answer correctly?","o":["20 questions, 15 correct","25 questions, 20 correct","40 questions, 30 correct","50 questions, 40 correct"],"h1":"You need 80 percent.","h2":"The Nevada knowledge test has 25 multiple-choice questions, and you must answer 20 correctly, which is 80 percent.","p":"Right. 20 out of 25."},"es":{"q":"En Nevada, ¿cuántas preguntas tiene el examen de conocimientos para carro, y cuántas debe contestar bien?","o":["20 preguntas, 15 correctas","25 preguntas, 20 correctas","40 preguntas, 30 correctas","50 preguntas, 40 correctas"],"h1":"Necesita el 80 por ciento.","h2":"El examen de conocimientos de Nevada tiene 25 preguntas de opción múltiple, y usted debe contestar 20 bien, que es el 80 por ciento.","p":"Correcto. 20 de 25."},"zh":{"q":"在 Nevada，小汽车知识考试有多少道题，必须答对多少道？","o":["20 道题，答对 15 道","25 道题，答对 20 道","40 道题，答对 30 道","50 道题，答对 40 道"],"h1":"你需要答对百分之 80。","h2":"Nevada 的知识考试有 25 道选择题，你必须答对 20 道，也就是百分之 80。","p":"对。25 道题答对 20 道。"},"vi":{"q":"Ở Nevada, bài thi kiến thức cho xe hơi có bao nhiêu câu hỏi, và bạn phải trả lời đúng bao nhiêu câu?","o":["20 câu, đúng 15 câu","25 câu, đúng 20 câu","40 câu, đúng 30 câu","50 câu, đúng 40 câu"],"h1":"Bạn cần đúng 80 phần trăm.","h2":"Bài thi kiến thức ở Nevada có 25 câu hỏi trắc nghiệm, và bạn phải trả lời đúng 20 câu, tức là 80 phần trăm.","p":"Đúng. 20 trên 25 câu."},"tl":{"q":"Sa Nevada, ilang tanong ang nasa knowledge test para sa kotse, at ilan ang dapat mong masagot nang tama?","o":["20 tanong, 15 tama","25 tanong, 20 tama","40 tanong, 30 tama","50 tanong, 40 tama"],"h1":"Kailangan mo ng 80 porsiyento.","h2":"Ang Nevada knowledge test ay may 25 multiple-choice na tanong, at dapat mong masagot nang tama ang 20, na 80 porsiyento.","p":"Tama. 20 sa 25."},"ar":{"q":"في Nevada، كم سؤالًا في اختبار المعرفة للسيارات، وكم سؤالًا يجب أن تجيب عنه إجابة صحيحة؟","o":["20 سؤالًا، 15 صحيحة","25 سؤالًا، 20 صحيحة","40 سؤالًا، 30 صحيحة","50 سؤالًا، 40 صحيحة"],"h1":"تحتاج إلى 80 بالمئة.","h2":"اختبار المعرفة في Nevada فيه 25 سؤالًا من نوع الاختيار من متعدّد، ويجب أن تجيب عن 20 منها إجابة صحيحة، أي 80 بالمئة.","p":"صحيح. 20 من 25."},"ref":{"doc":"NV","page":null}},{"id":"nv-013","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how long is a passed knowledge test result valid?","o":["30 days","90 days","Six months","One year"],"h1":"It matches how long the permit lasts.","h2":"In Nevada, a passed knowledge test result is valid for one year from the date you pass.","p":"Right. The result is good for one year."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válido el resultado de un examen de conocimientos aprobado?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Coincide con lo que dura el permiso.","h2":"En Nevada, el resultado de un examen de conocimientos aprobado es válido por un año desde la fecha en que lo aprueba.","p":"Correcto. El resultado vale un año."},"zh":{"q":"在 Nevada，通过的知识考试成绩有效期多久？","o":["30 天","90 天","六个月","一年"],"h1":"它和学习驾照的有效期一样长。","h2":"在 Nevada，通过的知识考试成绩从你通过那天起有效一年。","p":"对。成绩有效一年。"},"vi":{"q":"Ở Nevada, kết quả thi kiến thức đã đậu có giá trị trong bao lâu?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Nó bằng thời hạn của giấy phép tập lái.","h2":"Ở Nevada, kết quả thi kiến thức đã đậu có giá trị một năm kể từ ngày bạn đậu.","p":"Đúng. Kết quả có giá trị một năm."},"tl":{"q":"Sa Nevada, gaano katagal valid ang resulta ng knowledge test na naipasa mo?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Kapareho ito ng tagal ng permit.","h2":"Sa Nevada, ang resulta ng naipasang knowledge test ay valid nang isang taon mula sa petsa ng pagpasa mo.","p":"Tama. Valid ang resulta nang isang taon."},"ar":{"q":"في Nevada، كم مدة صلاحية نتيجة اختبار المعرفة بعد النجاح فيه؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"هي نفس مدة صلاحية تصريح التعلّم.","h2":"في Nevada تبقى نتيجة اختبار المعرفة الناجحة صالحة لمدة سنة واحدة من تاريخ نجاحك.","p":"صحيح. النتيجة صالحة لمدة سنة واحدة."},"ref":{"doc":"NV","page":null}},{"id":"nv-014","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, in which languages can you take the car knowledge test?","o":["English only","Spanish only","English or Spanish","Any language you choose"],"h1":"This app uses the same two languages.","h2":"In Nevada you can take the car knowledge test in English or in Spanish.","p":"Right. English or Spanish."},"es":{"q":"En Nevada, ¿en qué idiomas puede tomar el examen de conocimientos para carro?","o":["Solo inglés","Solo español","Inglés o español","Cualquier idioma que elija"],"h1":"Esta aplicación usa los mismos dos idiomas.","h2":"En Nevada usted puede tomar el examen de conocimientos para carro en inglés o en español.","p":"Correcto. Inglés o español."},"zh":{"q":"在 Nevada，小汽车知识考试可以用哪些语言考？","o":["只有英语","只有西班牙语","英语或西班牙语","你选择的任何语言"],"h1":"这个应用最先用的也是这两种语言。","h2":"在 Nevada，小汽车知识考试可以用英语或西班牙语考。","p":"对。英语或西班牙语。"},"vi":{"q":"Ở Nevada, bạn có thể thi kiến thức cho xe hơi bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Chỉ tiếng Tây Ban Nha","Tiếng Anh hoặc tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Đó là hai ngôn ngữ chính của ứng dụng này.","h2":"Ở Nevada, bạn có thể thi kiến thức cho xe hơi bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa Nevada, sa anong mga wika puwedeng kunin ang knowledge test para sa kotse?","o":["Ingles lamang","Espanyol lamang","Ingles o Espanyol","Kahit anong wikang pipiliin mo"],"h1":"Ito ang dalawang pangunahing wika ng app na ito.","h2":"Sa Nevada, puwede mong kunin ang knowledge test para sa kotse sa Ingles o sa Espanyol.","p":"Tama. Ingles o Espanyol."},"ar":{"q":"في Nevada، بأي لغات يمكنك أن تؤدّي اختبار المعرفة للسيارات؟","o":["الإنجليزية فقط","الإسبانية فقط","الإنجليزية أو الإسبانية","أي لغة تختارها"],"h1":"هما اللغتان الرئيسيتان في هذا التطبيق.","h2":"في Nevada يمكنك أن تؤدّي اختبار المعرفة للسيارات بالإنجليزية أو بالإسبانية.","p":"صحيح. الإنجليزية أو الإسبانية."},"ref":{"doc":"NV","page":12}},{"id":"nv-015","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, what is the blood alcohol limit for drivers under 21?","o":[".02 percent",".05 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Nevada the blood alcohol limit for drivers under 21 is .02 percent, much lower than the adult limit of .08.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Nevada, ¿cuál es el límite de alcohol en la sangre para conductores menores de 21 años?","o":[".02 por ciento",".05 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Nevada el límite de alcohol en la sangre para conductores menores de 21 años es .02 por ciento, mucho menor que el límite de .08 para adultos.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Nevada，未满 21 岁的司机血液酒精浓度上限是多少？","o":[".02%",".05%",".08%",".10%"],"h1":"它只是成年人上限的很小一部分。","h2":"在 Nevada，未满 21 岁的司机血液酒精浓度上限是 .02%，比成年人的上限 .08 低很多。","p":"对。未满 21 岁，上限是 .02。"},"vi":{"q":"Ở Nevada, giới hạn nồng độ cồn trong máu đối với người lái dưới 21 tuổi là bao nhiêu?","o":[".02 phần trăm",".05 phần trăm",".08 phần trăm",".10 phần trăm"],"h1":"Nó chỉ bằng một phần rất nhỏ của giới hạn cho người lớn.","h2":"Ở Nevada, giới hạn nồng độ cồn trong máu đối với người lái dưới 21 tuổi là .02 phần trăm, thấp hơn nhiều so với giới hạn .08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Nevada, ano ang limitasyon ng alcohol sa dugo para sa mga drayber na wala pang 21?","o":[".02 porsiyento",".05 porsiyento",".08 porsiyento",".10 porsiyento"],"h1":"Napakaliit na bahagi ito ng limitasyon para sa adulto.","h2":"Sa Nevada, ang limitasyon ng alcohol sa dugo para sa mga drayber na wala pang 21 ay .02 porsiyento, mas mababa kaysa sa .08 na limitasyon para sa adulto.","p":"Tama. Kapag wala pang 21, .02 ang limitasyon."},"ar":{"q":"في Nevada، ما الحدّ الأقصى لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة؟","o":[".02 بالمئة",".05 بالمئة",".08 بالمئة",".10 بالمئة"],"h1":"هو جزء صغير جدًا من حدّ البالغين.","h2":"في Nevada الحدّ الأقصى لنسبة الكحول في الدم للسائقين الذين أعمارهم أقل من 21 سنة هو .02 بالمئة، وهو أقل بكثير من حدّ البالغين وهو .08.","p":"صحيح. تحت 21 سنة، الحدّ هو .02."},"ref":{"doc":"NV","page":79}},{"id":"nv-016","scope":"NV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nevada, the move-over law covers more than emergency vehicles. Which of these does it also cover?","o":["Parked cars at a mall","A stalled vehicle or debris on the road","Bicycles in a bike lane","Buses at a bus stop"],"h1":"The law also covers hazards on the road itself.","h2":"In Nevada the move-over law also covers traffic incidents, such as a crash, a stalled vehicle or debris on the road.","p":"Right. Stalled cars and debris count too."},"es":{"q":"En Nevada, la ley de cambiarse de carril cubre más que los vehículos de emergencia. ¿Qué otra cosa también cubre?","o":["Carros estacionados en un centro comercial","Un vehículo averiado o escombros en la vía","Bicicletas en una ciclovía","Autobuses en una parada"],"h1":"La ley también cubre peligros en la misma vía.","h2":"En Nevada la ley de cambiarse de carril también cubre incidentes de tráfico, como un choque, un vehículo averiado o escombros en la vía.","p":"Correcto. Los vehículos averiados y los escombros también cuentan."},"zh":{"q":"在 Nevada，让道变道法（move-over law）不只包括紧急车辆。它还包括下面哪一种？","o":["购物中心停着的车","路上抛锚的车或杂物","自行车道上的自行车","公交车站的公交车"],"h1":"这条法律也包括路面上的危险。","h2":"在 Nevada，让道变道法（move-over law）也包括交通事故现场，比如撞车、抛锚的车或路上的杂物。","p":"对。抛锚的车和杂物也算。"},"vi":{"q":"Ở Nevada, luật nhường làn (move-over law) không chỉ áp dụng cho xe khẩn cấp. Luật này còn áp dụng cho trường hợp nào dưới đây?","o":["Xe đậu ở trung tâm mua sắm","Một xe bị chết máy hoặc vật cản trên đường","Xe đạp trong làn xe đạp","Xe buýt ở trạm xe buýt"],"h1":"Luật này cũng áp dụng cho các mối nguy ngay trên mặt đường.","h2":"Ở Nevada, luật nhường làn cũng áp dụng cho sự cố giao thông, như tai nạn, xe bị chết máy hoặc vật cản trên đường.","p":"Đúng. Xe chết máy và vật cản cũng được tính."},"tl":{"q":"Sa Nevada, saklaw ng move-over law ang higit pa sa mga emergency vehicle. Alin sa mga ito ang saklaw rin nito?","o":["Mga nakaparadang sasakyan sa mall","Sasakyang tumirik o mga kalat sa kalsada","Mga bisikleta sa bike lane","Mga bus sa hintuan ng bus"],"h1":"Saklaw rin ng batas ang mga panganib sa mismong kalsada.","h2":"Sa Nevada, saklaw rin ng move-over law ang mga insidente sa trapiko, tulad ng banggaan, sasakyang tumirik o mga kalat sa kalsada.","p":"Tama. Kasama rin ang mga tumirik na sasakyan at kalat."},"ar":{"q":"في Nevada، قانون إفساح المسار (move-over law) لا يشمل مركبات الطوارئ فقط. أيّ مما يلي يشمله أيضًا؟","o":["سيارات متوقّفة في مركز تسوّق","مركبة معطّلة أو حطام على الطريق","دراجات هوائية في مسار الدراجات","حافلات في موقف الحافلات"],"h1":"القانون يشمل أيضًا المخاطر الموجودة على الطريق نفسه.","h2":"في Nevada يشمل قانون إفساح المسار أيضًا حوادث المرور، مثل التصادم أو مركبة معطّلة أو حطام على الطريق.","p":"صحيح. المركبات المعطّلة والحطام تُحسب أيضًا."},"ref":{"doc":"NV","page":null}},{"id":"nv-017","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, what must you do when passing an emergency vehicle stopped on the shoulder with its lights flashing?","o":["Speed up to pass quickly","Stop in your lane","Honk to warn them","Slow down and, if you can, use a lane that is not next to it"],"h1":"Give them more space and less speed.","h2":"In Nevada you must slow down below the posted limit, drive with care, be ready to stop and, if you can, use a lane that is not next to the stopped emergency vehicle.","p":"Right. Slow down and move over."},"es":{"q":"En Nevada, ¿qué debe hacer al pasar un vehículo de emergencia detenido en el acotamiento con las luces encendidas?","o":["Acelerar para pasar rápido","Detenerse en su carril","Tocar la bocina para avisar","Bajar la velocidad y, si puede, usar un carril que no esté al lado"],"h1":"Deles más espacio y vaya más despacio.","h2":"En Nevada usted debe bajar la velocidad por debajo del límite indicado, manejar con cuidado, estar listo para detenerse y, si puede, usar un carril que no esté al lado del vehículo de emergencia detenido.","p":"Correcto. Baje la velocidad y cámbiese de carril."},"zh":{"q":"在 Nevada，经过停在路肩、闪着灯的紧急车辆时，你必须怎么做？","o":["加速快点开过去","在你的车道停下","按喇叭提醒他们","减速，如果可以，换到不靠近它的车道"],"h1":"给他们更多空间，开得更慢。","h2":"在 Nevada，你必须减速到标示的限速以下，小心开车，准备好停车，如果可以，换到不靠近停着的紧急车辆的车道。","p":"对。减速并让道变道。"},"vi":{"q":"Ở Nevada, bạn phải làm gì khi chạy ngang qua một xe khẩn cấp đang dừng bên lề đường với đèn đang nhấp nháy?","o":["Tăng tốc để qua nhanh","Dừng lại trong làn của bạn","Bấm còi để báo cho họ","Giảm tốc độ và, nếu có thể, đi vào làn không nằm sát xe đó"],"h1":"Hãy cho họ thêm khoảng trống và giảm tốc độ.","h2":"Ở Nevada, bạn phải giảm tốc độ xuống dưới mức giới hạn đã ghi, lái xe cẩn thận, sẵn sàng dừng lại và, nếu có thể, đi vào làn không nằm sát xe khẩn cấp đang dừng.","p":"Đúng. Giảm tốc độ và chuyển làn tránh xa."},"tl":{"q":"Sa Nevada, ano ang dapat mong gawin kapag dadaan ka sa isang emergency vehicle na nakahinto sa gilid ng kalsada na kumikislap ang ilaw?","o":["Bumilis para makalampas agad","Huminto sa iyong lane","Bumusina para balaan sila","Bumagal at, kung kaya, gumamit ng lane na hindi katabi nito"],"h1":"Bigyan sila ng mas maluwag na espasyo at bawasan ang bilis.","h2":"Sa Nevada, dapat kang bumagal nang mas mababa sa nakapaskil na speed limit, magmaneho nang maingat, maging handang huminto at, kung kaya, gumamit ng lane na hindi katabi ng nakahintong emergency vehicle.","p":"Tama. Bumagal at lumipat ng lane."},"ar":{"q":"في Nevada، ماذا يجب أن تفعل عندما تمرّ بمركبة طوارئ متوقّفة على كتف الطريق وأضواؤها تومض؟","o":["أسرع لتمرّ بسرعة","توقّف في مسارك","استخدم البوق لتحذيرهم","خفّف السرعة، وإذا استطعت، استخدم مسارًا غير مجاور لها"],"h1":"أعطهم مسافة أكبر وسرعة أقل.","h2":"في Nevada يجب أن تخفّف سرعتك إلى أقل من الحدّ المكتوب، وتقود بحذر، وتكون مستعدًا للتوقّف، وإذا استطعت، تستخدم مسارًا غير مجاور لمركبة الطوارئ المتوقّفة.","p":"صحيح. خفّف السرعة وابتعد عن المسار المجاور."},"ref":{"doc":"NV","page":61}},{"id":"nv-018","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, when do you not have to stop for a stopped school bus with flashing red lights?","o":["When you are in a hurry","When no children are visible","When the bus is on the other roadway of a divided highway","When you are on a two-lane road"],"h1":"A barrier or dividing section separates you from the bus.","h2":"In Nevada, on a divided highway, you need not stop for a school bus that is on the other roadway; traffic going the same way as the bus must stop.","p":"Right. Only the divided highway exception applies."},"es":{"q":"En Nevada, ¿cuándo no tiene que detenerse ante un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando tiene prisa","Cuando no se ven niños","Cuando el autobús está en el otro lado de una carretera dividida","Cuando va por una carretera de dos carriles"],"h1":"Una barrera o franja divisoria lo separa del autobús.","h2":"En Nevada, en una carretera dividida, usted no tiene que detenerse por un autobús escolar que está en la otra calzada; el tráfico que va en la misma dirección que el autobús sí debe detenerse.","p":"Correcto. Solo aplica la excepción de la carretera dividida."},"zh":{"q":"在 Nevada，什么时候不用为停着、闪着红灯的校车停车？","o":["你很赶时间时","看不到孩子时","校车在分隔公路的另一边道路上时","你在双车道的路上时"],"h1":"有障碍物或分隔带把你和校车分开。","h2":"在 Nevada，在分隔公路上，如果校车在另一边的道路上，你不用停车；和校车同方向的车必须停车。","p":"对。只有分隔公路是例外。"},"vi":{"q":"Ở Nevada, khi nào bạn không phải dừng lại cho xe buýt trường học đang dừng với đèn đỏ nhấp nháy?","o":["Khi bạn đang vội","Khi không thấy trẻ em nào","Khi xe buýt ở phía đường bên kia của xa lộ có dải phân cách","Khi bạn đang đi trên đường hai làn"],"h1":"Có một rào chắn hoặc dải phân cách ngăn giữa bạn và xe buýt.","h2":"Ở Nevada, trên xa lộ có dải phân cách, bạn không cần dừng lại cho xe buýt trường học ở phía đường bên kia; xe chạy cùng chiều với xe buýt thì phải dừng lại.","p":"Đúng. Chỉ có ngoại lệ xa lộ có dải phân cách."},"tl":{"q":"Sa Nevada, kailan hindi mo kailangang huminto para sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Kapag nagmamadali ka","Kapag walang nakikitang bata","Kapag nasa kabilang daan ng divided highway ang bus","Kapag nasa kalsadang may dalawang lane ka"],"h1":"May harang o pagitan na naghihiwalay sa iyo at sa bus.","h2":"Sa Nevada, sa divided highway, hindi mo kailangang huminto para sa school bus na nasa kabilang daan; ang trapikong papunta sa parehong direksiyon ng bus ay dapat huminto.","p":"Tama. Ang divided highway lamang ang eksepsiyon."},"ar":{"q":"في Nevada، متى لا يكون عليك أن تتوقّف لحافلة مدرسية متوقّفة وأضواؤها الحمراء تومض؟","o":["عندما تكون مستعجلًا","عندما لا ترى أي أطفال","عندما تكون الحافلة على الجهة الأخرى من طريق سريع مقسوم (divided highway)","عندما تكون على طريق من مسارين"],"h1":"هناك حاجز أو فاصل يفصلك عن الحافلة.","h2":"في Nevada، على الطريق السريع المقسوم، ليس عليك أن تتوقّف لحافلة مدرسية على الجهة الأخرى من الطريق؛ أما السيارات التي تسير في نفس اتجاه الحافلة فيجب أن تتوقّف.","p":"صحيح. الاستثناء الوحيد هو الطريق السريع المقسوم."},"ref":{"doc":"NV","page":64}},{"id":"nv-019","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, how may an adult driver talk on a cell phone while driving?","o":["Only with a hands-free device","Holding the phone in one hand","Only at speeds under 25 mph","Any way they like"],"h1":"Your hands must stay free for the wheel.","h2":"In Nevada it is illegal to hold a phone to talk while driving, so an adult may only talk using a hands-free device.","p":"Right. Hands-free only."},"es":{"q":"En Nevada, ¿cómo puede un conductor adulto hablar por celular mientras maneja?","o":["Solo con un dispositivo manos libres","Sosteniendo el teléfono en una mano","Solo a menos de 25 mph","Como quiera"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Nevada es ilegal sostener el teléfono para hablar mientras maneja, así que un adulto solo puede hablar con un dispositivo manos libres.","p":"Correcto. Solo manos libres."},"zh":{"q":"在 Nevada，成年司机开车时可以怎样打手机？","o":["只能用免提设备","一只手拿着手机","只在车速低于 25 mph 时","想怎样都可以"],"h1":"你的手必须空出来握方向盘。","h2":"在 Nevada，开车时拿着手机通话是违法的，所以成年人只能用免提设备通话。","p":"对。只能用免提。"},"vi":{"q":"Ở Nevada, người lái xe là người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Chỉ dùng thiết bị rảnh tay (hands-free)","Cầm điện thoại bằng một tay","Chỉ khi chạy dưới 25 mph","Bằng bất kỳ cách nào họ muốn"],"h1":"Tay bạn phải luôn rảnh để cầm vô lăng.","h2":"Ở Nevada, cầm điện thoại để nói chuyện khi lái xe là phạm luật, vì vậy người lớn chỉ được nói chuyện bằng thiết bị rảnh tay.","p":"Đúng. Chỉ dùng thiết bị rảnh tay."},"tl":{"q":"Sa Nevada, paano puwedeng makipag-usap sa cell phone ang adultong drayber habang nagmamaneho?","o":["Gamit lamang ang hands-free na device","Hawak ang telepono sa isang kamay","Kapag ang bilis ay mas mababa sa 25 mph lamang","Kahit anong paraan na gusto nila"],"h1":"Dapat manatiling malaya ang iyong mga kamay para sa manibela.","h2":"Sa Nevada, bawal ang paghawak ng telepono para makipag-usap habang nagmamaneho, kaya ang adulto ay puwede lamang makipag-usap gamit ang hands-free na device.","p":"Tama. Hands-free lamang."},"ar":{"q":"في Nevada، كيف يمكن للسائق البالغ أن يتكلّم بالهاتف المحمول أثناء القيادة؟","o":["باستخدام جهاز من دون استخدام اليدين (hands-free) فقط","وهو يمسك الهاتف بيد واحدة","فقط بسرعة أقل من 25 mph","بأي طريقة يريدها"],"h1":"يجب أن تبقى يداك حرّتين لعجلة القيادة.","h2":"في Nevada يُمنع إمساك الهاتف للتكلّم أثناء القيادة، لذلك لا يمكن للبالغ أن يتكلّم إلا باستخدام جهاز من دون استخدام اليدين.","p":"صحيح. من دون استخدام اليدين فقط."},"ref":{"doc":"NV","page":43}},{"id":"nv-020","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, what is the fine for a first handheld phone or texting offense in seven years?","o":["$25","$50","$250","$500"],"h1":"It is the lowest step of three: then $100, then $250.","h2":"In Nevada, the fine for a first handheld phone or texting offense in seven years is $50, and it can double in a work zone.","p":"Right. The first fine is $50."},"es":{"q":"En Nevada, ¿cuál es la multa por la primera infracción de usar el teléfono en la mano o enviar mensajes en siete años?","o":["$25","$50","$250","$500"],"h1":"Es el escalón más bajo de tres: luego $100, luego $250.","h2":"En Nevada, la multa por la primera infracción de teléfono en la mano o mensajes en siete años es de $50, y puede duplicarse en una zona de obras.","p":"Correcto. La primera multa es de $50."},"zh":{"q":"在 Nevada，七年内第一次因为手持手机或发短信被抓，罚款多少？","o":["$25","$50","$250","$500"],"h1":"它是三级里最低的一级：接下来是 $100，再接下来是 $250。","h2":"在 Nevada，七年内第一次因为手持手机或发短信被抓，罚款 $50，在施工区可能加倍。","p":"对。第一次罚 $50。"},"vi":{"q":"Ở Nevada, tiền phạt cho lần vi phạm đầu tiên trong bảy năm về cầm điện thoại hoặc nhắn tin khi lái xe là bao nhiêu?","o":["$25","$50","$250","$500"],"h1":"Đó là mức thấp nhất trong ba mức: sau đó là $100, rồi $250.","h2":"Ở Nevada, tiền phạt cho lần vi phạm đầu tiên trong bảy năm về cầm điện thoại hoặc nhắn tin là $50, và có thể tăng gấp đôi trong khu vực công trường.","p":"Đúng. Lần phạt đầu tiên là $50."},"tl":{"q":"Sa Nevada, magkano ang multa sa unang paglabag sa loob ng pitong taon sa paghawak ng telepono o pag-text habang nagmamaneho?","o":["$25","$50","$250","$500"],"h1":"Ito ang pinakamababa sa tatlong antas: susunod ang $100, tapos $250.","h2":"Sa Nevada, ang multa sa unang paglabag sa loob ng pitong taon sa paghawak ng telepono o pag-text ay $50, at puwede itong dumoble sa work zone.","p":"Tama. $50 ang unang multa."},"ar":{"q":"في Nevada، ما غرامة المخالفة الأولى خلال سبع سنوات لإمساك الهاتف أو كتابة الرسائل أثناء القيادة؟","o":["$25","$50","$250","$500"],"h1":"هي أقل درجة من ثلاث درجات: بعدها $100، ثم $250.","h2":"في Nevada غرامة المخالفة الأولى خلال سبع سنوات لإمساك الهاتف أو كتابة الرسائل هي $50، ويمكن أن تتضاعف في منطقة أعمال الطرق.","p":"صحيح. الغرامة الأولى هي $50."},"ref":{"doc":"NV","page":null}},{"id":"nv-021","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, what is the highest speed limit the state may post on its highways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It matches the name of a big interstate across northern Nevada.","h2":"Nevada may post a speed limit of up to 80 mph on state highways, and only where a sign shows it.","p":"Right. The top posted limit is 80 mph."},"es":{"q":"En Nevada, ¿cuál es el límite de velocidad más alto que el estado puede indicar en sus carreteras?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Coincide con el nombre de una autopista grande en el norte de Nevada.","h2":"Nevada puede indicar un límite de hasta 80 mph en carreteras estatales, y solo donde un letrero lo muestre.","p":"Correcto. El límite más alto es 80 mph."},"zh":{"q":"在 Nevada，州政府在公路上最高可以标示多少限速？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它和横穿 Nevada 北部的一条大州际公路的号码一样。","h2":"Nevada 在州公路上最高可以标示 80 mph 的限速，而且只在有标志显示的地方。","p":"对。标示的最高限速是 80 mph。"},"vi":{"q":"Ở Nevada, giới hạn tốc độ cao nhất mà tiểu bang có thể ghi trên các xa lộ là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó trùng với số của một xa lộ liên bang lớn chạy qua miền bắc Nevada.","h2":"Nevada có thể ghi giới hạn tốc độ đến 80 mph trên các xa lộ của tiểu bang, và chỉ ở nơi có biển báo ghi như vậy.","p":"Đúng. Giới hạn cao nhất được ghi là 80 mph."},"tl":{"q":"Sa Nevada, ano ang pinakamataas na speed limit na puwedeng ipaskil ng estado sa mga highway nito?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Kapareho ito ng numero ng isang malaking interstate na dumadaan sa hilagang Nevada.","h2":"Puwedeng magpaskil ang Nevada ng speed limit na hanggang 80 mph sa mga highway ng estado, at kung saan lamang may karatulang nagpapakita nito.","p":"Tama. 80 mph ang pinakamataas na nakapaskil na limitasyon."},"ar":{"q":"في Nevada، ما أعلى حدّ للسرعة يمكن للولاية أن تضعه على طرقها السريعة؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو نفس رقم طريق سريع كبير بين الولايات (interstate) يعبر شمال Nevada.","h2":"يمكن لولاية Nevada أن تضع حدًّا للسرعة يصل إلى 80 mph على طرق الولاية السريعة، وفقط حيث توجد لافتة تُظهر ذلك.","p":"صحيح. أعلى حدّ مكتوب هو 80 mph."},"ref":{"doc":"NV","page":null}},{"id":"nv-022","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how many demerit points in 12 months will get your license suspended?","o":["4 or more","8 or more","12 or more","10 or more"],"h1":"It is the number of months in a year.","h2":"In Nevada, your license is suspended if you get 12 or more demerit points in any 12-month period.","p":"Right. 12 points in 12 months means a suspension."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito en 12 meses causan la suspensión de su licencia?","o":["4 o más","8 o más","12 o más","10 o más"],"h1":"Es el número de meses que tiene un año.","h2":"En Nevada, su licencia se suspende si acumula 12 o más puntos de demérito en cualquier período de 12 meses.","p":"Correcto. 12 puntos en 12 meses significan una suspensión."},"zh":{"q":"在 Nevada，12 个月内累计多少扣分会让你的驾照被暂停？","o":["4 分或以上","8 分或以上","12 分或以上","10 分或以上"],"h1":"它是一年里月份的数目。","h2":"在 Nevada，如果你在任何 12 个月内累计 12 分或以上的扣分，你的驾照会被暂停。","p":"对。12 个月内 12 分就会被暂停驾照。"},"vi":{"q":"Ở Nevada, bao nhiêu điểm phạt trong 12 tháng sẽ làm bằng lái của bạn bị đình chỉ?","o":["Từ 4 trở lên","Từ 8 trở lên","Từ 12 trở lên","Từ 10 trở lên"],"h1":"Đó là số tháng trong một năm.","h2":"Ở Nevada, bằng lái của bạn bị đình chỉ nếu bạn bị từ 12 điểm phạt trở lên trong bất kỳ khoảng 12 tháng nào.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Nevada, ilang demerit point sa loob ng 12 buwan ang magpapasuspinde sa lisensya mo?","o":["4 o higit pa","8 o higit pa","12 o higit pa","10 o higit pa"],"h1":"Ito ang bilang ng buwan sa isang taon.","h2":"Sa Nevada, sinususpinde ang lisensya mo kung makakuha ka ng 12 o higit pang demerit point sa alinmang 12 buwan.","p":"Tama. Ang 12 point sa 12 buwan ay nangangahulugang suspensyon."},"ar":{"q":"في Nevada، كم نقطة مخالفة خلال 12 شهرًا تؤدي إلى إيقاف رخصتك؟","o":["4 أو أكثر","8 أو أكثر","12 أو أكثر","10 أو أكثر"],"h1":"هو عدد الأشهر في السنة.","h2":"في Nevada، تُوقَف رخصتك إذا حصلت على 12 نقطة مخالفة أو أكثر خلال أي فترة 12 شهرًا.","p":"صحيح. 12 نقطة في 12 شهرًا تعني إيقاف الرخصة."},"ref":{"doc":"NV","page":77}},{"id":"nv-023","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how many demerit points can a DMV-approved traffic safety course remove?","o":["Up to 3 points","Up to 6 points","Up to 12 points","None at all"],"h1":"It is a small number, and you can do it once in 12 months.","h2":"In Nevada, a DMV-approved traffic safety course can remove up to 3 demerit points, once in a 12-month period.","p":"Right. Traffic school removes up to 3 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito puede quitar un curso de seguridad vial aprobado por el DMV?","o":["Hasta 3 puntos","Hasta 6 puntos","Hasta 12 puntos","Ninguno"],"h1":"Es un número pequeño, y solo se puede hacer una vez cada 12 meses.","h2":"En Nevada, un curso de seguridad vial aprobado por el DMV puede quitar hasta 3 puntos de demérito, una vez en un período de 12 meses.","p":"Correcto. La escuela de tránsito quita hasta 3 puntos."},"zh":{"q":"在 Nevada，参加 DMV 认可的交通安全课程可以消除多少扣分？","o":["最多 3 分","最多 6 分","最多 12 分","一分也不能"],"h1":"它是一个小数字，而且 12 个月内只能上一次。","h2":"在 Nevada，DMV 认可的交通安全课程最多可以消除 3 分，12 个月内只能用一次。","p":"对。交通学校最多消除 3 分。"},"vi":{"q":"Ở Nevada, một khóa học an toàn giao thông được DMV chấp thuận có thể xóa bao nhiêu điểm phạt?","o":["Tối đa 3 điểm","Tối đa 6 điểm","Tối đa 12 điểm","Không xóa điểm nào"],"h1":"Đó là một con số nhỏ, và bạn chỉ được làm một lần trong 12 tháng.","h2":"Ở Nevada, một khóa học an toàn giao thông được DMV chấp thuận có thể xóa tối đa 3 điểm phạt, một lần trong khoảng 12 tháng.","p":"Đúng. Trường dạy luật giao thông xóa tối đa 3 điểm."},"tl":{"q":"Sa Nevada, ilang demerit point ang puwedeng alisin ng isang traffic safety course na aprubado ng DMV?","o":["Hanggang 3 point","Hanggang 6 na point","Hanggang 12 point","Wala kahit isa"],"h1":"Maliit na numero ito, at isang beses mo lang ito magagawa sa loob ng 12 buwan.","h2":"Sa Nevada, ang traffic safety course na aprubado ng DMV ay puwedeng mag-alis ng hanggang 3 demerit point, isang beses sa loob ng 12 buwan.","p":"Tama. Ang traffic school ay nag-aalis ng hanggang 3 point."},"ar":{"q":"في Nevada، كم نقطة مخالفة يمكن أن تمحوها دورة سلامة مرورية معتمدة من DMV؟","o":["حتى 3 نقاط","حتى 6 نقاط","حتى 12 نقطة","لا شيء أبدًا"],"h1":"هو رقم صغير، ويمكنك فعل ذلك مرة واحدة خلال 12 شهرًا.","h2":"في Nevada، يمكن لدورة سلامة مرورية معتمدة من DMV أن تمحو حتى 3 نقاط مخالفة، مرة واحدة خلال فترة 12 شهرًا.","p":"صحيح. مدرسة المرور تمحو حتى 3 نقاط."},"ref":{"doc":"NV","page":77}},{"id":"nv-024","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, police do not investigate a crash that causes $750 or more in damage. What must you do?","o":["Nothing, if no one was hurt","Tell your insurance company only","Call the DMV within 30 days","Send a crash report form (SR-1) to the DMV within 10 days"],"h1":"There is a form, and you have less than two weeks.","h2":"In Nevada, if police do not investigate a crash with $750 or more in damage or an injury, you must send an SR-1 crash report to the DMV within 10 days.","p":"Right. You send the SR-1 form to the DMV within 10 days."},"es":{"q":"En Nevada, la policía no investiga un choque que causa $750 o más en daños. ¿Qué debe hacer usted?","o":["Nada, si nadie resultó herido","Avisar solo a su compañía de seguros","Llamar al DMV dentro de 30 días","Enviar un formulario de informe de choque (SR-1) al DMV dentro de 10 días"],"h1":"Hay un formulario, y tiene menos de dos semanas.","h2":"En Nevada, si la policía no investiga un choque con $750 o más en daños o con heridos, usted debe enviar un informe de choque SR-1 al DMV dentro de 10 días.","p":"Correcto. Usted envía el formulario SR-1 al DMV dentro de 10 días."},"zh":{"q":"在 Nevada，如果警察没有调查一起造成 $750 或以上损失的车祸，你必须做什么？","o":["如果没人受伤，什么都不用做","只告诉你的保险公司","在 30 天内打电话给 DMV","在 10 天内把车祸报告表（SR-1）交给 DMV"],"h1":"有一张表格，而且你的时间不到两个星期。","h2":"在 Nevada，如果警察没有调查一起造成 $750 或以上损失或有人受伤的车祸，你必须在 10 天内把 SR-1 车祸报告交给 DMV。","p":"对。你要在 10 天内把 SR-1 表格交给 DMV。"},"vi":{"q":"Ở Nevada, cảnh sát không điều tra một vụ tai nạn gây thiệt hại từ $750 trở lên. Bạn phải làm gì?","o":["Không cần làm gì, nếu không ai bị thương","Chỉ báo cho công ty bảo hiểm","Gọi cho DMV trong vòng 30 ngày","Gửi mẫu báo cáo tai nạn (SR-1) cho DMV trong vòng 10 ngày"],"h1":"Có một mẫu đơn, và bạn có chưa tới hai tuần.","h2":"Ở Nevada, nếu cảnh sát không điều tra một vụ tai nạn gây thiệt hại từ $750 trở lên hoặc có người bị thương, bạn phải gửi báo cáo tai nạn SR-1 cho DMV trong vòng 10 ngày.","p":"Đúng. Bạn gửi mẫu SR-1 cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa Nevada, hindi inimbestigahan ng pulis ang isang banggaan na may pinsalang $750 o higit pa. Ano ang dapat mong gawin?","o":["Wala, kung walang nasaktan","Sabihan lamang ang iyong insurance company","Tawagan ang DMV sa loob ng 30 araw","Magpadala ng crash report form (SR-1) sa DMV sa loob ng 10 araw"],"h1":"May isang form, at wala pang dalawang linggo ang iyong oras.","h2":"Sa Nevada, kung hindi inimbestigahan ng pulis ang isang banggaan na may pinsalang $750 o higit pa o may nasaktan, dapat kang magpadala ng SR-1 crash report sa DMV sa loob ng 10 araw.","p":"Tama. Ipapadala mo ang SR-1 form sa DMV sa loob ng 10 araw."},"ar":{"q":"في Nevada، لم تحقّق الشرطة في حادث سبّب أضرارًا بقيمة $750 أو أكثر. ماذا يجب أن تفعل؟","o":["لا شيء، إذا لم يُصَب أحد","أخبر شركة التأمين فقط","اتصل بـ DMV خلال 30 يومًا","أرسل نموذج تقرير الحادث (SR-1) إلى DMV خلال 10 أيام"],"h1":"هناك نموذج، ولديك أقل من أسبوعين.","h2":"في Nevada، إذا لم تحقّق الشرطة في حادث فيه أضرار بقيمة $750 أو أكثر أو فيه إصابة، يجب أن ترسل تقرير الحادث SR-1 إلى DMV خلال 10 أيام.","p":"صحيح. ترسل نموذج SR-1 إلى DMV خلال 10 أيام."},"ref":{"doc":"NV","page":75}},{"id":"nv-025","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, what is the minimum liability insurance for injury to one person in a crash?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"It is half of the amount required for two or more people.","h2":"In Nevada, the minimum liability insurance is $25,000 for injury or death of one person in a crash.","p":"Right. The minimum for one person is $25,000."},"es":{"q":"En Nevada, ¿cuál es el seguro de responsabilidad civil mínimo por lesiones a una persona en un choque?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Es la mitad de lo que se exige para dos o más personas.","h2":"En Nevada, el seguro de responsabilidad civil mínimo es de $25,000 por lesiones o muerte de una persona en un choque.","p":"Correcto. El mínimo para una persona es de $25,000."},"zh":{"q":"在 Nevada，车祸中一个人受伤的最低责任保险金额是多少？","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"它是两人或以上所需金额的一半。","h2":"在 Nevada，车祸中一个人受伤或死亡的最低责任保险金额是 $25,000。","p":"对。一个人的最低金额是 $25,000。"},"vi":{"q":"Ở Nevada, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Đó là một nửa số tiền bắt buộc cho hai người trở lên.","h2":"Ở Nevada, bảo hiểm trách nhiệm tối thiểu là $25,000 cho thương tích hoặc tử vong của một người trong một vụ tai nạn.","p":"Đúng. Mức tối thiểu cho một người là $25,000."},"tl":{"q":"Sa Nevada, magkano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang banggaan?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Kalahati ito ng halagang kailangan para sa dalawa o higit pang tao.","h2":"Sa Nevada, ang pinakamababang liability insurance ay $25,000 para sa pinsala o pagkamatay ng isang tao sa isang banggaan.","p":"Tama. $25,000 ang pinakamababa para sa isang tao."},"ar":{"q":"في Nevada، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"هو نصف المبلغ المطلوب لشخصين أو أكثر.","h2":"في Nevada، الحدّ الأدنى لتأمين المسؤولية هو $25,000 عن إصابة شخص واحد أو وفاته في حادث.","p":"صحيح. الحدّ الأدنى لشخص واحد هو $25,000."},"ref":{"doc":"NV","page":75}},{"id":"nv-026","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, which children must ride in an approved child restraint system?","o":["Only babies under 1 year","Children under 12, at any height","Children under 6 who are shorter than 57 inches","Only children riding in the front seat"],"h1":"Think of age six and a height of 4 feet 9 inches.","h2":"In Nevada, children under 6 who are shorter than 57 inches must ride in an approved child restraint system.","p":"Right. Under 6 and under 57 inches means a child restraint."},"es":{"q":"En Nevada, ¿qué niños deben viajar en un sistema de retención infantil aprobado?","o":["Solo los bebés menores de 1 año","Los menores de 12 años, de cualquier estatura","Los menores de 6 años que miden menos de 57 pulgadas","Solo los niños que viajan en el asiento delantero"],"h1":"Piense en la edad de seis años y una estatura de 4 pies 9 pulgadas.","h2":"En Nevada, los niños menores de 6 años que miden menos de 57 pulgadas deben viajar en un sistema de retención infantil aprobado.","p":"Correcto. Menor de 6 años y de menos de 57 pulgadas: va en un asiento de seguridad."},"zh":{"q":"在 Nevada，哪些孩子必须坐在认可的儿童安全座椅里？","o":["只有不到 1 岁的婴儿","不到 12 岁的孩子，不管多高","不到 6 岁而且身高不到 57 英寸的孩子","只有坐在前座的孩子"],"h1":"想一想 6 岁和 4 英尺 9 英寸的身高。","h2":"在 Nevada，不到 6 岁而且身高不到 57 英寸的孩子必须坐在认可的儿童安全座椅里。","p":"对。不到 6 岁并且不到 57 英寸，就要用儿童安全座椅。"},"vi":{"q":"Ở Nevada, những trẻ em nào phải ngồi trong hệ thống ghế an toàn trẻ em được chấp thuận?","o":["Chỉ em bé dưới 1 tuổi","Trẻ em dưới 12 tuổi, bất kể chiều cao","Trẻ em dưới 6 tuổi và thấp hơn 57 inch","Chỉ trẻ em ngồi ở ghế trước"],"h1":"Hãy nghĩ đến 6 tuổi và chiều cao 4 feet 9 inch.","h2":"Ở Nevada, trẻ em dưới 6 tuổi và thấp hơn 57 inch phải ngồi trong hệ thống ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Dưới 6 tuổi và dưới 57 inch thì phải dùng ghế an toàn trẻ em."},"tl":{"q":"Sa Nevada, aling mga bata ang dapat sumakay sa aprubadong child restraint system?","o":["Mga sanggol lamang na wala pang 1 taon","Mga batang wala pang 12 taon, kahit gaano kataas","Mga batang wala pang 6 na taon at mas maliit sa 57 pulgada","Mga batang nakaupo lamang sa harapang upuan"],"h1":"Isipin ang edad na anim at taas na 4 na talampakan at 9 na pulgada.","h2":"Sa Nevada, ang mga batang wala pang 6 na taon at mas maliit sa 57 pulgada ay dapat sumakay sa aprubadong child restraint system.","p":"Tama. Wala pang 6 na taon at mas maliit sa 57 pulgada ay nangangahulugan ng child restraint."},"ar":{"q":"في Nevada، أيّ الأطفال يجب أن يركبوا في مقعد أمان معتمد للأطفال؟","o":["الرضّع تحت عمر سنة واحدة فقط","الأطفال تحت 12 سنة، مهما كان طولهم","الأطفال تحت 6 سنوات الذين طولهم أقل من 57 إنشًا","الأطفال الذين يجلسون في المقعد الأمامي فقط"],"h1":"فكّر في عمر ست سنوات وطول 4 أقدام و9 إنشات.","h2":"في Nevada، يجب أن يركب الأطفال تحت 6 سنوات الذين طولهم أقل من 57 إنشًا في مقعد أمان معتمد للأطفال.","p":"صحيح. تحت 6 سنوات وأقل من 57 إنشًا يعني مقعد أمان للأطفال."},"ref":{"doc":"NV","page":25}},{"id":"nv-027","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, you must use headlights when you cannot clearly see people or vehicles at what distance?","o":["1,000 feet","300 feet","100 feet","2 miles"],"h1":"It is a little more than three football fields.","h2":"In Nevada, headlights are required whenever you cannot clearly see people or vehicles 1,000 feet away.","p":"Right. Headlights go on when you cannot see clearly at 1,000 feet."},"es":{"q":"En Nevada, ¿debe usar las luces delanteras cuando no puede ver con claridad a personas o vehículos a qué distancia?","o":["1,000 pies","300 pies","100 pies","2 millas"],"h1":"Es un poco más que tres campos de fútbol americano.","h2":"En Nevada, las luces delanteras son obligatorias siempre que no pueda ver con claridad a personas o vehículos a 1,000 pies.","p":"Correcto. Las luces se encienden cuando no se ve bien a 1,000 pies."},"zh":{"q":"在 Nevada，当你在多远的距离看不清楚行人或车辆时，必须开大灯？","o":["1,000 英尺","300 英尺","100 英尺","2 英里"],"h1":"它比三个足球场长一点。","h2":"在 Nevada，只要你看不清楚 1,000 英尺外的行人或车辆，就必须开大灯。","p":"对。在 1,000 英尺看不清楚时就要开大灯。"},"vi":{"q":"Ở Nevada, bạn phải bật đèn pha khi không thể nhìn rõ người hoặc xe ở khoảng cách bao xa?","o":["1,000 feet","300 feet","100 feet","2 dặm"],"h1":"Nó dài hơn ba sân bóng bầu dục một chút.","h2":"Ở Nevada, bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ người hoặc xe ở cách xa 1,000 feet.","p":"Đúng. Bật đèn pha khi bạn không nhìn rõ ở 1,000 feet."},"tl":{"q":"Sa Nevada, dapat kang gumamit ng headlight kapag hindi mo malinaw na makita ang mga tao o sasakyan sa anong layo?","o":["1,000 talampakan","300 talampakan","100 talampakan","2 milya"],"h1":"Medyo higit ito sa haba ng tatlong football field.","h2":"Sa Nevada, kailangan ang headlight tuwing hindi mo malinaw na makita ang mga tao o sasakyan na 1,000 talampakan ang layo.","p":"Tama. Binubuksan ang headlight kapag hindi ka makakita nang malinaw sa 1,000 talampakan."},"ar":{"q":"في Nevada، يجب أن تشغّل المصابيح الأمامية عندما لا ترى الناس أو المركبات بوضوح على أيّ مسافة؟","o":["1,000 قدم","300 قدم","100 قدم","2 ميل"],"h1":"هي أكثر قليلًا من طول ثلاثة ملاعب كرة قدم أمريكية.","h2":"في Nevada، يجب تشغيل المصابيح الأمامية كلما لم تستطع أن ترى الناس أو المركبات بوضوح على بُعد 1,000 قدم.","p":"صحيح. تُشغَّل المصابيح الأمامية عندما لا ترى بوضوح على بُعد 1,000 قدم."},"ref":{"doc":"NV","page":56}},{"id":"nv-028","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, when is a school zone speed limit in effect, unless signs say otherwise?","o":["Every day of the year, at all hours","School days, from 7 a.m. to 3 p.m. only","Only when a crossing guard is in the street","School days, from 30 minutes before to 30 minutes after classes"],"h1":"It covers the school day plus a short time on each side.","h2":"In Nevada, unless signs say otherwise, the school zone limit applies on school days from half an hour before school starts until half an hour after it ends.","p":"Right. It runs from half an hour before to half an hour after school."},"es":{"q":"En Nevada, ¿cuándo rige el límite de velocidad de una zona escolar, si las señales no dicen otra cosa?","o":["Todos los días del año, a toda hora","En días de clase, solo de 7 a.m. a 3 p.m.","Solo cuando hay un guardia de cruce en la calle","En días de clase, de 30 minutos antes a 30 minutos después de las clases"],"h1":"Cubre el horario escolar más un rato antes y después.","h2":"En Nevada, si las señales no dicen otra cosa, el límite de la zona escolar rige en días de clase desde media hora antes de que empiecen las clases hasta media hora después de que terminen.","p":"Correcto. Rige desde media hora antes hasta media hora después de las clases."},"zh":{"q":"在 Nevada，如果没有标志另外说明，学校区的限速什么时候有效？","o":["一年中每一天，全天","上学日，只在早上 7 点到下午 3 点","只在有交通协管员站在街上时","上学日，从上课前 30 分钟到放学后 30 分钟"],"h1":"它包括上学时间，再加上前后一小段时间。","h2":"在 Nevada，除非标志另外说明，学校区限速在上学日从上学前半小时一直到放学后半小时有效。","p":"对。从上学前半小时到放学后半小时。"},"vi":{"q":"Ở Nevada, giới hạn tốc độ khu vực trường học có hiệu lực khi nào, trừ khi biển báo ghi khác?","o":["Mọi ngày trong năm, mọi giờ","Ngày đi học, chỉ từ 7 giờ sáng đến 3 giờ chiều","Chỉ khi có người hướng dẫn qua đường đứng trên đường","Ngày đi học, từ 30 phút trước đến 30 phút sau giờ học"],"h1":"Nó bao gồm giờ học cộng thêm một khoảng thời gian ngắn ở trước và sau.","h2":"Ở Nevada, trừ khi biển báo ghi khác, giới hạn tốc độ khu vực trường học áp dụng vào ngày đi học, từ nửa giờ trước khi vào học đến nửa giờ sau khi tan học.","p":"Đúng. Nó áp dụng từ nửa giờ trước đến nửa giờ sau giờ học."},"tl":{"q":"Sa Nevada, kailan may bisa ang speed limit sa school zone, maliban kung iba ang sinasabi ng mga karatula?","o":["Araw-araw sa buong taon, sa lahat ng oras","Sa mga araw ng pasok, mula 7 a.m. hanggang 3 p.m. lamang","Kapag may crossing guard lamang sa kalye","Sa mga araw ng pasok, mula 30 minuto bago hanggang 30 minuto pagkatapos ng klase"],"h1":"Saklaw nito ang oras ng pasok, at maikling oras bago at pagkatapos.","h2":"Sa Nevada, maliban kung iba ang sinasabi ng mga karatula, may bisa ang limitasyon sa school zone sa mga araw ng pasok mula kalahating oras bago magsimula ang klase hanggang kalahating oras pagkatapos nito matapos.","p":"Tama. Mula kalahating oras bago hanggang kalahating oras pagkatapos ng klase."},"ar":{"q":"في Nevada، متى يكون حدّ السرعة في منطقة المدرسة ساريًا، إلا إذا قالت اللافتات غير ذلك؟","o":["كل يوم في السنة، في كل الساعات","في أيام الدراسة، من 7 صباحًا إلى 3 بعد الظهر فقط","فقط عندما يكون حارس عبور في الشارع","في أيام الدراسة، من 30 دقيقة قبل الحصص إلى 30 دقيقة بعدها"],"h1":"يشمل اليوم الدراسي ووقتًا قصيرًا قبله وبعده.","h2":"في Nevada، إلا إذا قالت اللافتات غير ذلك، يسري حدّ السرعة في منطقة المدرسة في أيام الدراسة من نصف ساعة قبل بدء الدراسة حتى نصف ساعة بعد انتهائها.","p":"صحيح. يسري من نصف ساعة قبل الدراسة إلى نصف ساعة بعدها."},"ref":{"doc":"NV","page":33}},{"id":"nv-029","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, you pass a bicycle on a road with only one lane in your direction. How much space must you leave?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Nevada, when there is no other lane to move into, you must pass a bicycle on its left with at least three feet of space.","p":"Right. Give a bicycle at least three feet when you pass."},"es":{"q":"En Nevada, usted pasa a una bicicleta en una calle con un solo carril en su dirección. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 3 pies","Por lo menos 10 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Nevada, cuando no hay otro carril al cual moverse, usted debe pasar a una bicicleta por su izquierda dejando por lo menos tres pies de espacio.","p":"Correcto. Deje por lo menos tres pies a una bicicleta al pasarla."},"zh":{"q":"在 Nevada，你在本方向只有一条车道的道路上超过一辆自行车。你必须留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 3 英尺","至少 10 英尺"],"h1":"大约是一根码尺（yardstick）的长度。","h2":"在 Nevada，当没有别的车道可以换过去时，你必须从自行车的左边超过它，并留出至少三英尺的空间。","p":"对。超过自行车时，至少要留出三英尺。"},"vi":{"q":"Ở Nevada, bạn vượt một xe đạp trên con đường chỉ có một làn theo hướng của bạn. Bạn phải chừa khoảng trống bao nhiêu?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Nó dài khoảng bằng một cây thước yard.","h2":"Ở Nevada, khi không có làn nào khác để chuyển sang, bạn phải vượt xe đạp ở bên trái của nó và chừa ít nhất ba feet khoảng trống.","p":"Đúng. Hãy chừa cho xe đạp ít nhất ba feet khi bạn vượt."},"tl":{"q":"Sa Nevada, nag-o-overtake ka sa isang bisikleta sa kalsadang may iisang lane lang sa direksyon mo. Gaano kalaking espasyo ang dapat mong iwan?","o":["Hindi bababa sa 1 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 10 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick (panukat na isang yarda).","h2":"Sa Nevada, kapag walang ibang lane na malilipatan, dapat mong lampasan ang bisikleta sa kaliwa nito at mag-iwan ng hindi bababa sa tatlong talampakan na espasyo.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa tatlong talampakan kapag lumalampas ka."},"ar":{"q":"في Nevada، تتجاوز درّاجة على طريق فيه مسار واحد فقط في اتجاهك. كم مسافة يجب أن تترك؟","o":["1 قدم على الأقل","2 قدم على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Nevada، عندما لا يوجد مسار آخر تنتقل إليه، يجب أن تتجاوز الدرّاجة من يسارها وتترك مسافة ثلاثة أقدام على الأقل.","p":"صحيح. اترك للدرّاجة ثلاثة أقدام على الأقل عندما تتجاوزها."},"ref":{"doc":"NV","page":48}},{"id":"nv-030","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, you are on a highway outside a city with two lanes in your direction. When is it illegal to stay in the far left lane?","o":["When you go slower than the speed limit and a faster car comes up behind you","Any time it is dark outside","When you are about to pass a slower car","Any time you drive faster than 45 mph"],"h1":"Think about a faster driver who wants to get by.","h2":"In Nevada, on a highway with two lanes in your direction, it is illegal to stay in the far left lane below the speed limit when a faster vehicle is coming up behind you in that lane.","p":"Right. If you are slower than the limit and someone faster is behind you, leave the left lane."},"es":{"q":"En Nevada, usted va por una carretera fuera de la ciudad con dos carriles en su dirección. ¿Cuándo es ilegal quedarse en el carril de la extrema izquierda?","o":["Cuando va más despacio que el límite de velocidad y un carro más rápido se acerca por detrás","Siempre que está oscuro afuera","Cuando está por pasar a un carro más lento","Siempre que maneja a más de 45 mph"],"h1":"Piense en un conductor más rápido que quiere pasar.","h2":"En Nevada, en una carretera con dos carriles en su dirección, es ilegal quedarse en el carril de la extrema izquierda por debajo del límite de velocidad cuando un vehículo más rápido se acerca por detrás en ese carril.","p":"Correcto. Si va más lento que el límite y alguien más rápido viene detrás, deje el carril izquierdo."},"zh":{"q":"在 Nevada，你在城外的公路上，本方向有两条车道。什么时候留在最左边的车道是违法的？","o":["当你开得比限速慢，而有一辆更快的车从后面开过来时","天黑的任何时候","当你正要超过一辆较慢的车时","你开得比 45 mph 快的任何时候"],"h1":"想一想一位想开过去的更快的司机。","h2":"在 Nevada，在本方向有两条车道的公路上，如果你开得比限速慢，而有一辆更快的车在这条车道上从你后面开过来，留在最左边的车道就是违法的。","p":"对。如果你比限速慢，而后面有更快的车，就要离开左车道。"},"vi":{"q":"Ở Nevada, bạn đang ở trên xa lộ ngoài thành phố có hai làn theo hướng của bạn. Khi nào ở lại làn ngoài cùng bên trái là phạm luật?","o":["Khi bạn chạy chậm hơn tốc độ giới hạn và có một xe nhanh hơn chạy đến phía sau bạn","Bất cứ lúc nào trời tối","Khi bạn sắp vượt một xe chạy chậm hơn","Bất cứ lúc nào bạn chạy nhanh hơn 45 mph"],"h1":"Hãy nghĩ đến một người lái xe nhanh hơn muốn đi qua.","h2":"Ở Nevada, trên xa lộ có hai làn theo hướng của bạn, việc ở lại làn ngoài cùng bên trái khi chạy chậm hơn tốc độ giới hạn là phạm luật nếu có một xe nhanh hơn đang chạy đến phía sau bạn trong làn đó.","p":"Đúng. Nếu bạn chạy chậm hơn giới hạn và có người nhanh hơn ở phía sau, hãy rời làn bên trái."},"tl":{"q":"Sa Nevada, nasa highway ka sa labas ng lungsod na may dalawang lane sa direksyon mo. Kailan bawal manatili sa pinakakaliwang lane?","o":["Kapag mas mabagal ka kaysa sa speed limit at may mas mabilis na sasakyang dumarating sa likod mo","Anumang oras na madilim sa labas","Kapag malapit ka nang lumampas sa mas mabagal na sasakyan","Anumang oras na mas mabilis ka sa 45 mph"],"h1":"Isipin ang mas mabilis na drayber na gustong makadaan.","h2":"Sa Nevada, sa highway na may dalawang lane sa direksyon mo, bawal manatili sa pinakakaliwang lane nang mas mabagal sa speed limit kapag may mas mabilis na sasakyang dumarating sa likod mo sa lane na iyon.","p":"Tama. Kung mas mabagal ka sa limit at may mas mabilis sa likod mo, umalis ka sa kaliwang lane."},"ar":{"q":"في Nevada، أنت على طريق سريع خارج المدينة فيه مساران في اتجاهك. متى يكون البقاء في المسار الأيسر الأقصى مخالفًا للقانون؟","o":["عندما تسير أبطأ من حد السرعة وتقترب سيارة أسرع من خلفك","في أي وقت يكون فيه الجو مظلمًا","عندما تكون على وشك تجاوز سيارة أبطأ","في أي وقت تسير فيه أسرع من 45 mph"],"h1":"فكّر في سائق أسرع يريد أن يمرّ.","h2":"في Nevada، على طريق سريع فيه مساران في اتجاهك، يُمنع البقاء في المسار الأيسر الأقصى بسرعة أقل من حد السرعة عندما تقترب مركبة أسرع من خلفك في هذا المسار.","p":"صحيح. إذا كنت أبطأ من الحد وكان خلفك من هو أسرع، فاترك المسار الأيسر."},"ref":{"doc":"NV","page":47}},{"id":"nv-031","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, how close to the nearest rail of a railroad may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is the largest of these distances.","h2":"In Nevada you may not park within 50 feet of the nearest rail of a railroad.","p":"Right. Park at least 50 feet from the nearest rail."},"es":{"q":"En Nevada, ¿qué tan cerca del riel más cercano de un ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Nevada usted no puede estacionarse a menos de 50 pies del riel más cercano de un ferrocarril.","p":"Correcto. Estaciónese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Nevada，你可以在离铁路最近的铁轨多近的地方停车？","o":["不能近于 10 英尺","不能近于 15 英尺","不能近于 25 英尺","不能近于 50 英尺"],"h1":"它是这些距离中最大的一个。","h2":"在 Nevada，你不可以在离铁路最近的铁轨 50 英尺以内停车。","p":"对。停车时要离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Nevada, bạn được đậu xe gần đường ray gần nhất của đường xe lửa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"Đó là khoảng cách lớn nhất trong các khoảng cách này.","h2":"Ở Nevada, bạn không được đậu xe trong vòng 50 feet tính từ đường ray gần nhất của đường xe lửa.","p":"Đúng. Hãy đậu xe cách đường ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Nevada, gaano kalapit sa pinakamalapit na riles ng tren ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Ito ang pinakamalaki sa mga layong ito.","h2":"Sa Nevada, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa pinakamalapit na riles ng tren.","p":"Tama. Pumarada nang hindi bababa sa 50 talampakan mula sa pinakamalapit na riles."},"ar":{"q":"في Nevada، إلى أيّ قرب من أقرب قضيب لسكة الحديد يمكنك أن تركن سيارتك؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أكبر هذه المسافات.","h2":"في Nevada لا يجوز لك أن تركن سيارتك على بُعد أقل من 50 قدمًا من أقرب قضيب لسكة الحديد.","p":"صحيح. اركن على بُعد 50 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"NV","page":50}},{"id":"nv-032","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is a first driver license valid for a person under 65?","o":["Four years","Eight years","Ten years","Twelve years"],"h1":"Drivers 65 and older get half this time.","h2":"In Nevada a first driver license for a person under 65 is valid for eight years and expires on the driver's birthday.","p":"Right. A first Nevada license lasts eight years if you are under 65."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válida una primera licencia de conducir para una persona menor de 65 años?","o":["Cuatro años","Ocho años","Diez años","Doce años"],"h1":"Los conductores de 65 años o más reciben la mitad de este tiempo.","h2":"En Nevada una primera licencia de conducir para una persona menor de 65 años es válida por ocho años y vence el día del cumpleaños del conductor.","p":"Correcto. Una primera licencia de Nevada dura ocho años si usted tiene menos de 65."},"zh":{"q":"在 Nevada，65 岁以下的人第一次拿到的驾照有效期是多久？","o":["四年","八年","十年","十二年"],"h1":"65 岁及以上的司机只有这个时间的一半。","h2":"在 Nevada，65 岁以下的人第一次拿到的驾照有效期是八年，在司机生日那天到期。","p":"对。如果你不到 65 岁，第一张 Nevada 驾照有效八年。"},"vi":{"q":"Ở Nevada, bằng lái xe đầu tiên của người dưới 65 tuổi có giá trị trong bao lâu?","o":["Bốn năm","Tám năm","Mười năm","Mười hai năm"],"h1":"Người lái xe từ 65 tuổi trở lên được một nửa thời gian này.","h2":"Ở Nevada, bằng lái xe đầu tiên của người dưới 65 tuổi có giá trị tám năm và hết hạn vào ngày sinh nhật của người lái xe.","p":"Đúng. Bằng lái đầu tiên ở Nevada có giá trị tám năm nếu bạn dưới 65 tuổi."},"tl":{"q":"Sa Nevada, gaano katagal may bisa ang unang driver license ng taong wala pang 65 taong gulang?","o":["Apat na taon","Walong taon","Sampung taon","Labindalawang taon"],"h1":"Kalahati lang ng panahong ito ang nakukuha ng mga drayber na 65 pataas.","h2":"Sa Nevada, ang unang driver license ng taong wala pang 65 ay may bisa nang walong taon at mag-e-expire sa kaarawan ng drayber.","p":"Tama. Walong taon ang bisa ng unang Nevada license kung wala ka pang 65."},"ar":{"q":"في Nevada، ما مدة صلاحية أول رخصة قيادة لشخص عمره أقل من 65 سنة؟","o":["أربع سنوات","ثماني سنوات","عشر سنوات","اثنتا عشرة سنة"],"h1":"السائقون في عمر 65 فما فوق يحصلون على نصف هذه المدة.","h2":"في Nevada تكون أول رخصة قيادة لشخص عمره أقل من 65 سنة صالحة لمدة ثماني سنوات، وتنتهي في يوم ميلاد السائق.","p":"صحيح. أول رخصة في Nevada تدوم ثماني سنوات إذا كان عمرك أقل من 65 سنة."},"ref":{"doc":"NV","page":6}},{"id":"nv-033","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you refuse an officer's blood, breath, or urine test for the first time. How long can you not get a license?","o":["185 days","One year","90 days","Three years"],"h1":"It is longer than six months. Three years is for a repeat refusal.","h2":"In Nevada, if you refuse the blood, breath, or urine test the first time, your license is revoked and you cannot get one for one year.","p":"Right. A first refusal costs you your license for one year."},"es":{"q":"En Nevada, usted se niega por primera vez a la prueba de sangre, aliento u orina que pide un oficial. ¿Por cuánto tiempo no puede obtener una licencia?","o":["185 días","Un año","90 días","Tres años"],"h1":"Es más de seis meses. Tres años es para quien se niega otra vez.","h2":"En Nevada, si usted se niega por primera vez a la prueba de sangre, aliento u orina, le revocan la licencia y no puede obtener una por un año.","p":"Correcto. La primera negativa le quita la licencia por un año."},"zh":{"q":"在 Nevada，你第一次拒绝警察要求的血液、呼气或尿液检测。你有多长时间不能拿驾照？","o":["185 天","一年","90 天","三年"],"h1":"比六个月长。三年是给再次拒绝的人的。","h2":"在 Nevada，如果你第一次拒绝血液、呼气或尿液检测，你的驾照会被吊销，一年内不能再拿驾照。","p":"对。第一次拒绝检测，你会失去驾照一年。"},"vi":{"q":"Ở Nevada, bạn từ chối xét nghiệm máu, hơi thở hoặc nước tiểu của cảnh sát lần đầu tiên. Bạn không được có bằng lái trong bao lâu?","o":["185 ngày","Một năm","90 ngày","Ba năm"],"h1":"Lâu hơn sáu tháng. Ba năm là dành cho người từ chối lần nữa.","h2":"Ở Nevada, nếu bạn từ chối xét nghiệm máu, hơi thở hoặc nước tiểu lần đầu tiên, bằng lái của bạn bị thu hồi và bạn không được có bằng lái trong một năm.","p":"Đúng. Từ chối lần đầu khiến bạn mất bằng lái một năm."},"tl":{"q":"Sa Nevada, tumanggi ka sa unang pagkakataon sa blood, breath, o urine test ng pulis. Gaano katagal kang hindi puwedeng magkaroon ng license?","o":["185 araw","Isang taon","90 araw","Tatlong taon"],"h1":"Mas mahaba ito sa anim na buwan. Ang tatlong taon ay para sa paulit-ulit na pagtanggi.","h2":"Sa Nevada, kung tumanggi ka sa blood, breath, o urine test sa unang pagkakataon, babawiin ang license mo at hindi ka puwedeng magkaroon nito nang isang taon.","p":"Tama. Sa unang pagtanggi, mawawala ang license mo nang isang taon."},"ar":{"q":"في Nevada، رفضت لأول مرة فحص الدم أو النفَس أو البول الذي طلبه الشرطي. ما المدة التي لا يمكنك فيها الحصول على رخصة؟","o":["185 يومًا","سنة واحدة","90 يومًا","ثلاث سنوات"],"h1":"المدة أطول من ستة أشهر. الثلاث سنوات هي للرفض المتكرر.","h2":"في Nevada، إذا رفضت فحص الدم أو النفَس أو البول لأول مرة، تُلغى رخصتك ولا يمكنك الحصول على رخصة لمدة سنة واحدة.","p":"صحيح. الرفض الأول يُفقدك رخصتك لمدة سنة واحدة."},"ref":{"doc":"NV","page":79}},{"id":"nv-034","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how many demerit points does a conviction for reckless driving add to your record?","o":["4 points","6 points","2 points","8 points"],"h1":"It is the most points on the list of common violations.","h2":"In Nevada, reckless driving adds 8 demerit points to your driving record.","p":"Right. Reckless driving is 8 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito agrega a su historial una condena por manejo imprudente (reckless driving)?","o":["4 puntos","6 puntos","2 puntos","8 puntos"],"h1":"Es la mayor cantidad de puntos en la lista de infracciones comunes.","h2":"En Nevada, el manejo imprudente agrega 8 puntos de demérito a su historial de manejo.","p":"Correcto. El manejo imprudente son 8 puntos."},"zh":{"q":"在 Nevada，因为鲁莽驾驶被定罪，会在你的记录上加几分？","o":["4 分","6 分","2 分","8 分"],"h1":"这是常见违规清单上分数最多的一项。","h2":"在 Nevada，鲁莽驾驶会在你的驾驶记录上加 8 分。","p":"对。鲁莽驾驶是 8 分。"},"vi":{"q":"Ở Nevada, bị kết tội lái xe liều lĩnh thì hồ sơ của bạn bị thêm bao nhiêu điểm phạt?","o":["4 điểm","6 điểm","2 điểm","8 điểm"],"h1":"Đây là mức điểm cao nhất trong danh sách các vi phạm thường gặp.","h2":"Ở Nevada, lái xe liều lĩnh làm hồ sơ lái xe của bạn bị thêm 8 điểm phạt.","p":"Đúng. Lái xe liều lĩnh là 8 điểm."},"tl":{"q":"Sa Nevada, ilang demerit point ang nadadagdag sa record mo kapag nahatulan ka sa reckless driving?","o":["4 point","6 point","2 point","8 point"],"h1":"Ito ang pinakamaraming point sa listahan ng mga karaniwang paglabag.","h2":"Sa Nevada, ang reckless driving ay nagdadagdag ng 8 demerit point sa driving record mo.","p":"Tama. 8 point ang reckless driving."},"ar":{"q":"في Nevada، كم نقطة مخالفة تُضاف إلى سجلّك عند إدانتك بالقيادة المتهوّرة؟","o":["4 نقاط","6 نقاط","نقطتان (2)","8 نقاط"],"h1":"هي أكثر عدد من النقاط في قائمة المخالفات الشائعة.","h2":"في Nevada، القيادة المتهوّرة تضيف 8 نقاط مخالفة إلى سجلّ قيادتك.","p":"صحيح. القيادة المتهوّرة 8 نقاط."},"ref":{"doc":"NV","page":78}},{"id":"nv-035","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"It is less than the amount for injury to one person.","h2":"In Nevada, your liability insurance must cover at least $20,000 for damage to other people's property in one crash.","p":"Right. Property damage coverage must be at least $20,000."},"es":{"q":"En Nevada, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"Es menos que la cantidad por lesiones a una persona.","h2":"En Nevada, su seguro de responsabilidad civil debe cubrir por lo menos $20,000 por daños a la propiedad de otras personas en un choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $20,000."},"zh":{"q":"在 Nevada，一次车祸中对别人财产损失的最低责任保险是多少？","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"比一个人受伤的金额少。","h2":"在 Nevada，你的责任保险必须对一次车祸中别人的财产损失至少赔付 $20,000。","p":"对。财产损失的保险至少要 $20,000。"},"vi":{"q":"Ở Nevada, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một vụ tai nạn là bao nhiêu?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"Ít hơn số tiền cho thương tích của một người.","h2":"Ở Nevada, bảo hiểm trách nhiệm của bạn phải trả ít nhất $20,000 cho thiệt hại tài sản của người khác trong một vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất $20,000."},"tl":{"q":"Sa Nevada, magkano ang pinakamababang liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"Mas mababa ito sa halaga para sa pinsala ng isang tao.","h2":"Sa Nevada, ang liability insurance mo ay dapat sumagot ng hindi bababa sa $20,000 para sa pinsala sa ari-arian ng ibang tao sa isang banggaan.","p":"Tama. Hindi bababa sa $20,000 ang coverage para sa pinsala sa ari-arian."},"ar":{"q":"في Nevada، ما الحدّ الأدنى لتأمين المسؤولية عن الأضرار في ممتلكات الآخرين في حادث واحد؟","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"المبلغ أقل من مبلغ إصابة شخص واحد.","h2":"في Nevada، يجب أن يغطي تأمين المسؤولية لديك $20,000 على الأقل عن الأضرار في ممتلكات الآخرين في حادث واحد.","p":"صحيح. تغطية الأضرار في الممتلكات يجب أن تكون $20,000 على الأقل."},"ref":{"doc":"NV","page":75}},{"id":"nv-036","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you move to a new address. How soon must you tell the DMV?","o":["Within 10 days","Within 60 days","Within 30 days","Within 1 year"],"h1":"It is about one month.","h2":"In Nevada, you must tell the DMV about a new address or a new name within 30 days.","p":"Right. Tell the DMV within 30 days."},"es":{"q":"En Nevada, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar al DMV?","o":["Dentro de 10 días","Dentro de 60 días","Dentro de 30 días","Dentro de 1 año"],"h1":"Es más o menos un mes.","h2":"En Nevada, usted debe avisar al DMV de una nueva dirección o un nuevo nombre dentro de 30 días.","p":"Correcto. Avise al DMV dentro de 30 días."},"zh":{"q":"在 Nevada，你搬到了新地址。你必须在多长时间内通知 DMV？","o":["10 天内","60 天内","30 天内","1 年内"],"h1":"大约一个月。","h2":"在 Nevada，你必须在 30 天内把新地址或新名字告诉 DMV。","p":"对。在 30 天内通知 DMV。"},"vi":{"q":"Ở Nevada, bạn chuyển đến địa chỉ mới. Bạn phải báo cho DMV trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 60 ngày","Trong vòng 30 ngày","Trong vòng 1 năm"],"h1":"Khoảng một tháng.","h2":"Ở Nevada, bạn phải báo cho DMV về địa chỉ mới hoặc tên mới trong vòng 30 ngày.","p":"Đúng. Báo cho DMV trong vòng 30 ngày."},"tl":{"q":"Sa Nevada, lumipat ka sa bagong address. Gaano kabilis mo dapat sabihan ang DMV?","o":["Sa loob ng 10 araw","Sa loob ng 60 araw","Sa loob ng 30 araw","Sa loob ng 1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa Nevada, dapat mong sabihan ang DMV tungkol sa bagong address o bagong pangalan sa loob ng 30 araw.","p":"Tama. Sabihan ang DMV sa loob ng 30 araw."},"ar":{"q":"في Nevada، انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تُبلغ DMV؟","o":["خلال 10 أيام","خلال 60 يومًا","خلال 30 يومًا","خلال سنة واحدة (1)"],"h1":"المدة نحو شهر واحد.","h2":"في Nevada، يجب أن تُبلغ DMV بعنوانك الجديد أو اسمك الجديد خلال 30 يومًا.","p":"صحيح. أبلغ DMV خلال 30 يومًا."},"ref":{"doc":"NV","page":19}},{"id":"nv-037","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you are under 18. How long must you hold an instruction permit before you apply for a driver license?","o":["At least 3 months","At least 6 months","At least 9 months","At least 12 months"],"h1":"It is half a year.","h2":"In Nevada, a driver under 18 must hold an instruction permit for at least 6 months before applying for a driver license.","p":"Right. Hold the permit at least 6 months first."},"es":{"q":"En Nevada, usted es menor de 18 años. ¿Por cuánto tiempo debe tener el permiso de instrucción antes de solicitar la licencia de manejar?","o":["Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 9 meses","Por lo menos 12 meses"],"h1":"Es medio año.","h2":"En Nevada, un conductor menor de 18 años debe tener el permiso de instrucción por lo menos 6 meses antes de solicitar la licencia de manejar.","p":"Correcto. Primero tenga el permiso por lo menos 6 meses."},"zh":{"q":"在 Nevada，你不到 18 岁。申请驾照之前，你必须持有学习驾照多长时间？","o":["至少 3 个月","至少 6 个月","至少 9 个月","至少 12 个月"],"h1":"是半年。","h2":"在 Nevada，不到 18 岁的司机必须持有学习驾照至少 6 个月，才能申请驾照。","p":"对。先持有学习驾照至少 6 个月。"},"vi":{"q":"Ở Nevada, bạn dưới 18 tuổi. Bạn phải giữ giấy phép tập lái bao lâu trước khi xin bằng lái?","o":["Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 9 tháng","Ít nhất 12 tháng"],"h1":"Nửa năm.","h2":"Ở Nevada, người lái xe dưới 18 tuổi phải giữ giấy phép tập lái ít nhất 6 tháng trước khi xin bằng lái.","p":"Đúng. Giữ giấy phép tập lái ít nhất 6 tháng trước."},"tl":{"q":"Sa Nevada, wala ka pang 18 taong gulang. Gaano katagal mo dapat hawak ang instruction permit bago ka mag-apply ng driver license?","o":["Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 9 na buwan","Hindi bababa sa 12 buwan"],"h1":"Kalahating taon ito.","h2":"Sa Nevada, ang drayber na wala pang 18 ay dapat may hawak na instruction permit nang hindi bababa sa 6 na buwan bago mag-apply ng driver license.","p":"Tama. Hawakan muna ang permit nang hindi bababa sa 6 na buwan."},"ar":{"q":"في Nevada، عمرك أقل من 18 سنة. ما المدة التي يجب أن تحمل فيها تصريح التعلّم قبل أن تتقدّم بطلب رخصة قيادة؟","o":["3 أشهر على الأقل","6 أشهر على الأقل","9 أشهر على الأقل","12 شهرًا على الأقل"],"h1":"المدة نصف سنة.","h2":"في Nevada، يجب على السائق الذي عمره أقل من 18 سنة أن يحمل تصريح التعلّم لمدة 6 أشهر على الأقل قبل أن يتقدّم بطلب رخصة قيادة.","p":"صحيح. احمل التصريح 6 أشهر على الأقل أولًا."},"ref":{"doc":"NV","page":15}},{"id":"nv-038","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, how must a child under age 2 ride in a car?","o":["In a booster seat in the front seat","Facing forward in the front seat","Facing forward in the back seat","In a rear-facing seat in the back seat"],"h1":"The baby faces the back of the car, away from the front.","h2":"In Nevada, a child under age 2 must ride in a rear-facing child seat in the back seat.","p":"Right. Under 2: rear-facing, in the back seat."},"es":{"q":"En Nevada, ¿cómo debe viajar en el carro un niño menor de 2 años?","o":["En un asiento elevado (booster) en el asiento delantero","Mirando hacia adelante en el asiento delantero","Mirando hacia adelante en el asiento trasero","En un asiento orientado hacia atrás en el asiento trasero"],"h1":"El bebé mira hacia la parte de atrás del carro, no hacia el frente.","h2":"En Nevada, un niño menor de 2 años debe viajar en un asiento de seguridad orientado hacia atrás en el asiento trasero.","p":"Correcto. Menores de 2 años: mirando hacia atrás, en el asiento trasero."},"zh":{"q":"在 Nevada，不到 2 岁的孩子必须怎样坐车？","o":["坐在前排的增高座椅里","在前排面朝前坐","在后排面朝前坐","在后排坐面朝后的座椅"],"h1":"宝宝面朝车的后面，背对前面。","h2":"在 Nevada，不到 2 岁的孩子必须坐在后排面朝后的儿童座椅里。","p":"对。不到 2 岁：面朝后，坐后排。"},"vi":{"q":"Ở Nevada, trẻ em dưới 2 tuổi phải ngồi trong xe như thế nào?","o":["Ngồi ghế nâng ở hàng ghế trước","Quay mặt về phía trước ở hàng ghế trước","Quay mặt về phía trước ở hàng ghế sau","Ngồi ghế quay mặt về phía sau ở hàng ghế sau"],"h1":"Em bé quay mặt về phía sau xe, không nhìn về phía trước.","h2":"Ở Nevada, trẻ em dưới 2 tuổi phải ngồi trong ghế trẻ em quay mặt về phía sau ở hàng ghế sau.","p":"Đúng. Dưới 2 tuổi: quay mặt về phía sau, ở hàng ghế sau."},"tl":{"q":"Sa Nevada, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang?","o":["Sa booster seat sa harapang upuan","Nakaharap sa unahan sa harapang upuan","Nakaharap sa unahan sa likurang upuan","Sa rear-facing seat sa likurang upuan"],"h1":"Nakaharap ang sanggol sa likod ng kotse, palayo sa unahan.","h2":"Sa Nevada, ang batang wala pang 2 taon ay dapat sumakay sa rear-facing na child seat sa likurang upuan.","p":"Tama. Wala pang 2: nakaharap sa likod, sa likurang upuan."},"ar":{"q":"في Nevada، كيف يجب أن يركب الطفل الذي عمره أقل من سنتين (2) في السيارة؟","o":["في مقعد رافع في المقعد الأمامي","متّجهًا إلى الأمام في المقعد الأمامي","متّجهًا إلى الأمام في المقعد الخلفي","في مقعد متّجه إلى الخلف في المقعد الخلفي"],"h1":"يكون وجه الطفل نحو مؤخرة السيارة، بعيدًا عن الأمام.","h2":"في Nevada، يجب أن يركب الطفل الذي عمره أقل من سنتين (2) في مقعد أطفال متّجه إلى الخلف في المقعد الخلفي.","p":"صحيح. أقل من سنتين (2): مقعد متّجه إلى الخلف، في المقعد الخلفي."},"ref":{"doc":"NV","page":25}},{"id":"nv-039","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, you may not leave a child aged 7 or younger alone in a car when it puts the child at risk, unless someone watches the child. How old must that person be?","o":["At least 12","At least 10","At least 16","At least 18"],"h1":"The person can be younger than a teen driver.","h2":"In Nevada, a child aged 7 or younger may not be left in a car when it is risky unless a person at least 12 years old is watching and can see the child.","p":"Right. The person watching must be at least 12."},"es":{"q":"En Nevada, usted no puede dejar solo en un carro a un niño de 7 años o menos cuando eso lo pone en riesgo, a menos que alguien lo cuide. ¿Qué edad debe tener esa persona?","o":["Por lo menos 12 años","Por lo menos 10 años","Por lo menos 16 años","Por lo menos 18 años"],"h1":"La persona puede ser menor que un conductor adolescente.","h2":"En Nevada, no se puede dejar en un carro a un niño de 7 años o menos cuando es peligroso, a menos que lo cuide y lo pueda ver una persona de por lo menos 12 años.","p":"Correcto. La persona que lo cuida debe tener por lo menos 12 años."},"zh":{"q":"在 Nevada，如果会让孩子有危险，你不可以把 7 岁或以下的孩子单独留在车里，除非有人看着孩子。这个人至少要几岁？","o":["至少 12 岁","至少 10 岁","至少 16 岁","至少 18 岁"],"h1":"这个人可以比青少年司机还小。","h2":"在 Nevada，有危险时不可以把 7 岁或以下的孩子留在车里，除非有一个至少 12 岁的人在看着并且能看到孩子。","p":"对。看孩子的人必须至少 12 岁。"},"vi":{"q":"Ở Nevada, bạn không được để trẻ từ 7 tuổi trở xuống một mình trong xe khi điều đó gây nguy hiểm cho trẻ, trừ khi có người trông trẻ. Người đó phải bao nhiêu tuổi?","o":["Ít nhất 12 tuổi","Ít nhất 10 tuổi","Ít nhất 16 tuổi","Ít nhất 18 tuổi"],"h1":"Người này có thể nhỏ tuổi hơn một thiếu niên lái xe.","h2":"Ở Nevada, không được để trẻ từ 7 tuổi trở xuống trong xe khi có nguy hiểm, trừ khi có một người ít nhất 12 tuổi đang trông và có thể nhìn thấy trẻ.","p":"Đúng. Người trông trẻ phải ít nhất 12 tuổi."},"tl":{"q":"Sa Nevada, hindi mo puwedeng iwanang mag-isa sa kotse ang batang 7 taong gulang pababa kapag mapapahamak ang bata, maliban kung may nagbabantay sa kanya. Ilang taon dapat ang taong iyon?","o":["Hindi bababa sa 12","Hindi bababa sa 10","Hindi bababa sa 16","Hindi bababa sa 18"],"h1":"Puwedeng mas bata ang taong ito kaysa sa isang tinedyer na drayber.","h2":"Sa Nevada, hindi puwedeng iwan sa kotse ang batang 7 taon pababa kapag delikado, maliban kung may taong hindi bababa sa 12 taong gulang na nagbabantay at nakikita ang bata.","p":"Tama. Ang nagbabantay ay dapat hindi bababa sa 12 taong gulang."},"ar":{"q":"في Nevada، لا يجوز لك أن تترك طفلًا عمره 7 سنوات أو أقل وحده في السيارة إذا كان ذلك يعرّضه للخطر، إلا إذا كان هناك شخص يراقبه. كم يجب أن يكون عمر هذا الشخص؟","o":["12 سنة على الأقل","10 سنوات على الأقل","16 سنة على الأقل","18 سنة على الأقل"],"h1":"يمكن أن يكون هذا الشخص أصغر من سائق مراهق.","h2":"في Nevada، لا يجوز ترك طفل عمره 7 سنوات أو أقل في السيارة عندما يكون ذلك خطرًا، إلا إذا كان شخص عمره 12 سنة على الأقل يراقبه ويستطيع أن يراه.","p":"صحيح. يجب أن يكون عمر الشخص الذي يراقب 12 سنة على الأقل."},"ref":{"doc":"NV","page":25}},{"id":"nv-040","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, you use a center turn lane to make a left turn. What is the farthest you may drive in it before you turn?","o":["100 feet","300 feet","200 feet","500 feet"],"h1":"It is about 20 car lengths.","h2":"In Nevada, you may not drive more than 200 feet in a center turn lane before you make your left turn.","p":"Right. No more than 200 feet in the center turn lane before turning."},"es":{"q":"En Nevada, usted usa un carril central de vuelta para dar vuelta a la izquierda. ¿Cuál es la distancia máxima que puede manejar en él antes de dar la vuelta?","o":["100 pies","300 pies","200 pies","500 pies"],"h1":"Son más o menos 20 largos de carro.","h2":"En Nevada, usted no puede manejar más de 200 pies en un carril central de vuelta antes de dar vuelta a la izquierda.","p":"Correcto. No más de 200 pies en el carril central antes de dar la vuelta."},"zh":{"q":"在 Nevada，你用中间转弯车道来左转。转弯之前，你最多可以在里面开多远？","o":["100 英尺","300 英尺","200 英尺","500 英尺"],"h1":"大约 20 个车身长。","h2":"在 Nevada，左转之前，你在中间转弯车道里开的距离不可以超过 200 英尺。","p":"对。转弯前在中间转弯车道里不超过 200 英尺。"},"vi":{"q":"Ở Nevada, bạn dùng làn rẽ ở giữa đường để rẽ trái. Bạn được chạy trong làn đó xa nhất bao nhiêu trước khi rẽ?","o":["100 feet","300 feet","200 feet","500 feet"],"h1":"Khoảng 20 chiều dài xe.","h2":"Ở Nevada, bạn không được chạy quá 200 feet trong làn rẽ ở giữa đường trước khi rẽ trái.","p":"Đúng. Không quá 200 feet trong làn rẽ ở giữa trước khi rẽ."},"tl":{"q":"Sa Nevada, gumagamit ka ng center turn lane para kumaliwa. Hanggang gaano kalayo ka puwedeng magmaneho rito bago ka lumiko?","o":["100 talampakan","300 talampakan","200 talampakan","500 talampakan"],"h1":"Mga 20 haba ng kotse ito.","h2":"Sa Nevada, hindi ka puwedeng magmaneho nang higit sa 200 talampakan sa center turn lane bago ka kumaliwa.","p":"Tama. Hindi hihigit sa 200 talampakan sa center turn lane bago lumiko."},"ar":{"q":"في Nevada، تستخدم مسار الانعطاف الأوسط لتنعطف يسارًا. ما أقصى مسافة يجوز لك أن تقودها فيه قبل أن تنعطف؟","o":["100 قدم","300 قدم","200 قدم","500 قدم"],"h1":"المسافة نحو طول 20 سيارة.","h2":"في Nevada، لا يجوز لك أن تقود أكثر من 200 قدم في مسار الانعطاف الأوسط قبل أن تنعطف يسارًا.","p":"صحيح. لا تزد على 200 قدم في مسار الانعطاف الأوسط قبل الانعطاف."},"ref":{"doc":"NV","page":32}},{"id":"nv-041","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, what is the speed limit in a school zone?","o":["10 or 20 mph","15 or 25 mph","20 or 30 mph","25 or 35 mph"],"h1":"The higher number is the usual limit in business and residential areas.","h2":"In Nevada, the speed limit in a school zone is either 15 mph or 25 mph.","p":"Right. School zones in Nevada are 15 or 25 mph."},"es":{"q":"En Nevada, ¿cuál es el límite de velocidad en una zona escolar?","o":["10 o 20 mph","15 o 25 mph","20 o 30 mph","25 o 35 mph"],"h1":"El número más alto es el límite usual en zonas comerciales y residenciales.","h2":"En Nevada, el límite de velocidad en una zona escolar es de 15 mph o de 25 mph.","p":"Correcto. Las zonas escolares en Nevada son de 15 o 25 mph."},"zh":{"q":"在 Nevada，学校区的限速是多少？","o":["10 或 20 mph","15 或 25 mph","20 或 30 mph","25 或 35 mph"],"h1":"较大的那个数字是商业区和住宅区通常的限速。","h2":"在 Nevada，学校区的限速是 15 mph 或 25 mph。","p":"对。Nevada 的学校区限速是 15 或 25 mph。"},"vi":{"q":"Ở Nevada, giới hạn tốc độ trong khu vực trường học là bao nhiêu?","o":["10 hoặc 20 mph","15 hoặc 25 mph","20 hoặc 30 mph","25 hoặc 35 mph"],"h1":"Số lớn hơn là giới hạn thường gặp ở khu thương mại và khu dân cư.","h2":"Ở Nevada, giới hạn tốc độ trong khu vực trường học là 15 mph hoặc 25 mph.","p":"Đúng. Khu vực trường học ở Nevada là 15 hoặc 25 mph."},"tl":{"q":"Sa Nevada, ano ang speed limit sa school zone?","o":["10 o 20 mph","15 o 25 mph","20 o 30 mph","25 o 35 mph"],"h1":"Ang mas mataas na numero ang karaniwang limit sa mga business at residential na lugar.","h2":"Sa Nevada, ang speed limit sa school zone ay 15 mph o 25 mph.","p":"Tama. 15 o 25 mph ang mga school zone sa Nevada."},"ar":{"q":"في Nevada، ما حدّ السرعة في منطقة المدرسة؟","o":["10 أو 20 mph","15 أو 25 mph","20 أو 30 mph","25 أو 35 mph"],"h1":"الرقم الأكبر هو الحدّ المعتاد في المناطق التجارية والسكنية.","h2":"في Nevada، حدّ السرعة في منطقة المدرسة هو 15 mph أو 25 mph.","p":"صحيح. مناطق المدارس في Nevada حدّها 15 أو 25 mph."},"ref":{"doc":"NV","page":33}},{"id":"nv-042","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a school crossing guard is in the crosswalk in front of you. When may you go?","o":["As soon as the children reach the curb","When the guard turns to face the sidewalk","Right away, if you drive slowly around the guard","When the guard is all the way out of the crosswalk"],"h1":"Think about where the guard is standing, not the children.","h2":"In Nevada, you must wait until the school crossing guard is completely out of the crosswalk before you go.","p":"Right. Wait until the guard has left the crosswalk."},"es":{"q":"En Nevada, un guardia de cruce escolar está en el cruce de peatones frente a usted. ¿Cuándo puede seguir?","o":["En cuanto los niños lleguen a la banqueta","Cuando el guardia se voltee hacia la acera","Enseguida, si maneja despacio alrededor del guardia","Cuando el guardia haya salido por completo del cruce de peatones"],"h1":"Piense en dónde está el guardia, no los niños.","h2":"En Nevada, usted debe esperar a que el guardia de cruce escolar salga por completo del cruce de peatones antes de seguir.","p":"Correcto. Espere a que el guardia salga del cruce de peatones."},"zh":{"q":"在 Nevada，一位学校过路协管员在你前面的人行横道上。你什么时候可以走？","o":["孩子们一走到路边就可以","协管员转身面向人行道时","马上，只要你慢慢绕过协管员","协管员完全离开人行横道时"],"h1":"想一想协管员站在哪里，而不是孩子们。","h2":"在 Nevada，你必须等学校过路协管员完全离开人行横道以后才可以走。","p":"对。等协管员离开人行横道再走。"},"vi":{"q":"Ở Nevada, một người hướng dẫn qua đường cho học sinh đang ở trên lối qua đường trước mặt bạn. Khi nào bạn được đi?","o":["Ngay khi các em đến lề đường","Khi người hướng dẫn quay mặt về phía vỉa hè","Ngay lập tức, nếu bạn chạy chậm vòng qua người hướng dẫn","Khi người hướng dẫn đã ra khỏi hẳn lối qua đường"],"h1":"Hãy nghĩ đến chỗ người hướng dẫn đang đứng, không phải các em học sinh.","h2":"Ở Nevada, bạn phải chờ đến khi người hướng dẫn qua đường cho học sinh ra khỏi hẳn lối qua đường rồi mới được đi.","p":"Đúng. Chờ đến khi người hướng dẫn đã rời khỏi lối qua đường."},"tl":{"q":"Sa Nevada, may school crossing guard sa tawiran sa harap mo. Kailan ka puwedeng umandar?","o":["Pagdating ng mga bata sa gilid ng kalsada","Kapag humarap ang guard sa bangketa","Agad-agad, kung dahan-dahan kang dadaan sa paligid ng guard","Kapag ganap nang nakaalis ang guard sa tawiran"],"h1":"Isipin kung saan nakatayo ang guard, hindi ang mga bata.","h2":"Sa Nevada, dapat kang maghintay hanggang ganap nang nakaalis sa tawiran ang school crossing guard bago ka umandar.","p":"Tama. Maghintay hanggang makaalis ang guard sa tawiran."},"ar":{"q":"في Nevada، يقف مراقب عبور المدرسة في ممرّ المشاة أمامك. متى يجوز لك أن تتحرّك؟","o":["بمجرد أن يصل الأطفال إلى الرصيف","عندما يستدير المراقب ليواجه الرصيف","فورًا، إذا قدت ببطء حول المراقب","عندما يخرج المراقب من ممرّ المشاة بالكامل"],"h1":"فكّر في مكان وقوف المراقب، وليس الأطفال.","h2":"في Nevada، يجب أن تنتظر حتى يخرج مراقب عبور المدرسة من ممرّ المشاة بالكامل قبل أن تتحرّك.","p":"صحيح. انتظر حتى يغادر المراقب ممرّ المشاة."},"ref":{"doc":"NV","page":33}},{"id":"nv-043","scope":"NV","cat":"signals","sign":null,"c":0,"en":{"q":"In Nevada, you are on an open highway. How far ahead should you start signaling before a turn?","o":["At least 300 feet (about 30 car lengths)","At least 100 feet (about 10 car lengths)","At least 50 feet (about 5 car lengths)","At least 1,000 feet (about 100 car lengths)"],"h1":"On a city street it is 100 feet. On an open highway it is three times as far.","h2":"In Nevada, on an open highway you should signal at least 300 feet, about 30 car lengths, before you turn.","p":"Right. Signal at least 300 feet ahead on an open highway."},"es":{"q":"En Nevada, usted va por una carretera abierta. ¿Con cuánta anticipación debe poner la señal antes de dar vuelta?","o":["Por lo menos 300 pies (unos 30 largos de carro)","Por lo menos 100 pies (unos 10 largos de carro)","Por lo menos 50 pies (unos 5 largos de carro)","Por lo menos 1,000 pies (unos 100 largos de carro)"],"h1":"En una calle de la ciudad son 100 pies. En una carretera abierta es tres veces más.","h2":"En Nevada, en una carretera abierta usted debe poner la señal por lo menos 300 pies, unos 30 largos de carro, antes de dar vuelta.","p":"Correcto. Ponga la señal por lo menos 300 pies antes en una carretera abierta."},"zh":{"q":"在 Nevada，你在开阔的公路上。转弯之前，你应该提前多远开始打转向灯？","o":["至少 300 英尺（大约 30 个车身长）","至少 100 英尺（大约 10 个车身长）","至少 50 英尺（大约 5 个车身长）","至少 1,000 英尺（大约 100 个车身长）"],"h1":"在城市街道上是 100 英尺。在开阔的公路上是它的三倍。","h2":"在 Nevada，在开阔的公路上，你应该在转弯前至少 300 英尺（大约 30 个车身长）打转向灯。","p":"对。在开阔的公路上至少提前 300 英尺打灯。"},"vi":{"q":"Ở Nevada, bạn đang ở trên xa lộ ngoài đường trống. Bạn nên bắt đầu bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 300 feet (khoảng 30 chiều dài xe)","Ít nhất 100 feet (khoảng 10 chiều dài xe)","Ít nhất 50 feet (khoảng 5 chiều dài xe)","Ít nhất 1,000 feet (khoảng 100 chiều dài xe)"],"h1":"Trên đường phố trong thành phố là 100 feet. Trên xa lộ ngoài đường trống thì xa gấp ba lần.","h2":"Ở Nevada, trên xa lộ ngoài đường trống bạn nên bật đèn xi nhan ít nhất 300 feet, khoảng 30 chiều dài xe, trước khi rẽ.","p":"Đúng. Bật xi nhan trước ít nhất 300 feet trên xa lộ ngoài đường trống."},"tl":{"q":"Sa Nevada, nasa bukas na highway ka. Gaano kalayo bago lumiko ka dapat magsimulang mag-signal?","o":["Hindi bababa sa 300 talampakan (mga 30 haba ng kotse)","Hindi bababa sa 100 talampakan (mga 10 haba ng kotse)","Hindi bababa sa 50 talampakan (mga 5 haba ng kotse)","Hindi bababa sa 1,000 talampakan (mga 100 haba ng kotse)"],"h1":"Sa kalye sa lungsod, 100 talampakan ito. Sa bukas na highway, tatlong beses ang layo.","h2":"Sa Nevada, sa bukas na highway dapat kang mag-signal nang hindi bababa sa 300 talampakan, mga 30 haba ng kotse, bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 300 talampakan bago lumiko sa bukas na highway."},"ar":{"q":"في Nevada، أنت على طريق سريع مفتوح. من أي مسافة قبل الانعطاف يجب أن تبدأ بإعطاء الإشارة؟","o":["300 قدم على الأقل (نحو طول 30 سيارة)","100 قدم على الأقل (نحو طول 10 سيارات)","50 قدمًا على الأقل (نحو طول 5 سيارات)","1,000 قدم على الأقل (نحو طول 100 سيارة)"],"h1":"في شارع داخل المدينة تكون 100 قدم. على الطريق السريع المفتوح تكون ثلاثة أضعاف ذلك.","h2":"في Nevada، على الطريق السريع المفتوح يجب أن تعطي الإشارة قبل الانعطاف بمسافة 300 قدم على الأقل، أي نحو طول 30 سيارة.","p":"صحيح. أعطِ الإشارة قبل 300 قدم على الأقل على الطريق السريع المفتوح."},"ref":{"doc":"NV","page":45}},{"id":"nv-044","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, you may not make a U-turn if a curve, hill, rain, or fog blocks your clear view for a certain distance in each direction. What is that distance?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is about 20 car lengths.","h2":"In Nevada, you may not make a U-turn where you cannot see clearly for 200 feet in each direction.","p":"Right. You need a clear view of 200 feet each way for a U-turn."},"es":{"q":"En Nevada, no puede dar una vuelta en U si una curva, una colina, la lluvia o la neblina no le deja ver con claridad cierta distancia en cada dirección. ¿Qué distancia es?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Son más o menos 20 largos de carro.","h2":"En Nevada, usted no puede dar una vuelta en U donde no puede ver con claridad 200 pies en cada dirección.","p":"Correcto. Para una vuelta en U necesita ver bien 200 pies en cada dirección."},"zh":{"q":"在 Nevada，如果弯道、坡、雨或雾挡住了你在每个方向一定距离内的清楚视线，你就不可以掉头。这个距离是多少？","o":["50 英尺","100 英尺","200 英尺","1,000 英尺"],"h1":"大约 20 个车身长。","h2":"在 Nevada，如果你不能在每个方向清楚地看到 200 英尺，就不可以掉头。","p":"对。掉头时每个方向都要能清楚地看到 200 英尺。"},"vi":{"q":"Ở Nevada, bạn không được quay đầu xe nếu khúc cua, dốc, mưa hoặc sương mù che tầm nhìn rõ của bạn trong một khoảng cách nhất định ở mỗi hướng. Khoảng cách đó là bao nhiêu?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"Khoảng 20 chiều dài xe.","h2":"Ở Nevada, bạn không được quay đầu xe ở nơi bạn không nhìn rõ được 200 feet ở mỗi hướng.","p":"Đúng. Bạn cần nhìn rõ 200 feet ở mỗi hướng để quay đầu xe."},"tl":{"q":"Sa Nevada, hindi ka puwedeng mag-U-turn kung may kurba, burol, ulan, o hamog na humaharang sa malinaw mong tanaw sa isang tiyak na layo sa bawat direksyon. Ano ang layong iyon?","o":["50 talampakan","100 talampakan","200 talampakan","1,000 talampakan"],"h1":"Mga 20 haba ng kotse ito.","h2":"Sa Nevada, hindi ka puwedeng mag-U-turn kung saan hindi mo malinaw na nakikita ang 200 talampakan sa bawat direksyon.","p":"Tama. Kailangan mo ng malinaw na tanaw na 200 talampakan sa bawat direksyon para mag-U-turn."},"ar":{"q":"في Nevada، لا يجوز لك أن تستدير استدارة كاملة (U-turn) إذا كان منعطف أو تلّة أو مطر أو ضباب يحجب رؤيتك الواضحة لمسافة معيّنة في كل اتجاه. ما هذه المسافة؟","o":["50 قدمًا","100 قدم","200 قدم","1,000 قدم"],"h1":"المسافة نحو طول 20 سيارة.","h2":"في Nevada، لا يجوز لك أن تستدير استدارة كاملة (U-turn) في مكان لا ترى فيه بوضوح مسافة 200 قدم في كل اتجاه.","p":"صحيح. تحتاج إلى رؤية واضحة لمسافة 200 قدم في كل اتجاه لتستدير استدارة كاملة."},"ref":{"doc":"NV","page":46}},{"id":"nv-045","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, on the same side of the street, how close to the driveway entrance of a fire station may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is the same as the distance from a crosswalk.","h2":"In Nevada, you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nevada, en el mismo lado de la calle, ¿qué tan cerca de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies","No más cerca de 100 pies"],"h1":"Es la misma distancia que de un cruce de peatones.","h2":"En Nevada, usted no puede estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de una estación de bomberos."},"zh":{"q":"在 Nevada，在街道同一边，你可以在离消防站车道入口多近的地方停车？","o":["不能近于 10 英尺","不能近于 20 英尺","不能近于 50 英尺","不能近于 100 英尺"],"h1":"和离人行横道的距离一样。","h2":"在 Nevada，你不可以在消防站车道入口 20 英尺以内停车。","p":"对。离消防站车道至少 20 英尺。"},"vi":{"q":"Ở Nevada, trên cùng một bên đường, bạn được đậu xe gần lối vào trạm cứu hỏa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 50 feet","Không gần hơn 100 feet"],"h1":"Bằng với khoảng cách từ lối qua đường.","h2":"Ở Nevada, bạn không được đậu xe trong vòng 20 feet tính từ lối vào của trạm cứu hỏa.","p":"Đúng. Cách lối vào trạm cứu hỏa ít nhất 20 feet."},"tl":{"q":"Sa Nevada, sa parehong gilid ng kalye, gaano kalapit sa pasukan ng driveway ng fire station ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 20 talampakan","Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan"],"h1":"Pareho ito ng layo mula sa tawiran.","h2":"Sa Nevada, hindi ka puwedeng pumarada sa loob ng 20 talampakan mula sa pasukan ng driveway ng fire station.","p":"Tama. Lumayo nang hindi bababa sa 20 talampakan sa driveway ng fire station."},"ar":{"q":"في Nevada، على الجهة نفسها من الشارع، إلى أي مدى يجوز لك أن تركن سيارتك قريبًا من مدخل ممرّ محطة الإطفاء؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم"],"h1":"هي نفس المسافة عن ممرّ المشاة.","h2":"في Nevada، لا يجوز لك أن تركن سيارتك على بُعد أقل من 20 قدمًا من مدخل ممرّ محطة الإطفاء.","p":"صحيح. ابقَ على بُعد 20 قدمًا على الأقل من ممرّ محطة الإطفاء."},"ref":{"doc":"NV","page":50}},{"id":"nv-046","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, what is the lowest fine for parking in a disabled parking space without the right placard or license plate?","o":["$50","$100","$150","$250"],"h1":"It is the highest amount here.","h2":"In Nevada, the minimum fine for parking in a space for people with disabilities without the right placard or plate is $250.","p":"Right. The fine starts at $250."},"es":{"q":"En Nevada, ¿cuál es la multa mínima por estacionarse en un espacio para personas con discapacidad sin el permiso (placard) o la placa correspondiente?","o":["$50","$100","$150","$250"],"h1":"Es la cantidad más alta de estas.","h2":"En Nevada, la multa mínima por estacionarse en un espacio para personas con discapacidad sin el permiso o la placa correspondiente es de $250.","p":"Correcto. La multa empieza en $250."},"zh":{"q":"在 Nevada，没有正确的停车证或车牌就停在残疾人车位，最低罚款是多少？","o":["$50","$100","$150","$250"],"h1":"是这里最高的金额。","h2":"在 Nevada，没有正确的停车证或车牌就停在残疾人车位，最低罚款是 $250。","p":"对。罚款从 $250 起。"},"vi":{"q":"Ở Nevada, mức phạt thấp nhất cho việc đậu xe ở chỗ dành cho người khuyết tật mà không có thẻ hoặc biển số đúng là bao nhiêu?","o":["$50","$100","$150","$250"],"h1":"Đây là số tiền cao nhất ở đây.","h2":"Ở Nevada, mức phạt tối thiểu cho việc đậu xe ở chỗ dành cho người khuyết tật mà không có thẻ hoặc biển số đúng là $250.","p":"Đúng. Tiền phạt bắt đầu từ $250."},"tl":{"q":"Sa Nevada, magkano ang pinakamababang multa sa pagparada sa disabled parking space nang walang tamang placard o license plate?","o":["$50","$100","$150","$250"],"h1":"Ito ang pinakamataas na halaga rito.","h2":"Sa Nevada, ang pinakamababang multa sa pagparada sa puwesto para sa mga taong may kapansanan nang walang tamang placard o plate ay $250.","p":"Tama. Nagsisimula sa $250 ang multa."},"ar":{"q":"في Nevada، ما أقل غرامة لركن السيارة في موقف ذوي الإعاقة من دون البطاقة أو لوحة الترخيص الصحيحة؟","o":["$50","$100","$150","$250"],"h1":"هي أعلى مبلغ هنا.","h2":"في Nevada، الحدّ الأدنى لغرامة ركن السيارة في موقف مخصّص لذوي الإعاقة من دون البطاقة أو اللوحة الصحيحة هو $250.","p":"صحيح. الغرامة تبدأ من $250."},"ref":{"doc":"NV","page":50}},{"id":"nv-047","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, when may you use studded snow tires?","o":["From October 1 through April 30","From November 1 through March 31","From December 1 through the end of February","Any time of year"],"h1":"The season starts in the fall and ends in the spring.","h2":"In Nevada, studded snow tires may be used only from October 1 through April 30.","p":"Right. Studded tires are allowed October 1 through April 30."},"es":{"q":"En Nevada, ¿cuándo puede usar llantas de nieve con clavos?","o":["Del 1 de octubre al 30 de abril","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre hasta el final de febrero","En cualquier época del año"],"h1":"La temporada empieza en el otoño y termina en la primavera.","h2":"En Nevada, las llantas de nieve con clavos solo se pueden usar del 1 de octubre al 30 de abril.","p":"Correcto. Las llantas con clavos se permiten del 1 de octubre al 30 de abril."},"zh":{"q":"在 Nevada，什么时候可以用带钉的雪地轮胎？","o":["从 10 月 1 日到 4 月 30 日","从 11 月 1 日到 3 月 31 日","从 12 月 1 日到 2 月底","一年中任何时候"],"h1":"这个季节从秋天开始，到春天结束。","h2":"在 Nevada，带钉的雪地轮胎只能在 10 月 1 日到 4 月 30 日之间使用。","p":"对。10 月 1 日到 4 月 30 日可以用带钉轮胎。"},"vi":{"q":"Ở Nevada, khi nào bạn được dùng lốp xe tuyết có đinh?","o":["Từ ngày 1 tháng 10 đến ngày 30 tháng 4","Từ ngày 1 tháng 11 đến ngày 31 tháng 3","Từ ngày 1 tháng 12 đến cuối tháng 2","Bất cứ lúc nào trong năm"],"h1":"Mùa này bắt đầu vào mùa thu và kết thúc vào mùa xuân.","h2":"Ở Nevada, lốp xe tuyết có đinh chỉ được dùng từ ngày 1 tháng 10 đến ngày 30 tháng 4.","p":"Đúng. Lốp có đinh được dùng từ ngày 1 tháng 10 đến ngày 30 tháng 4."},"tl":{"q":"Sa Nevada, kailan ka puwedeng gumamit ng studded snow tire?","o":["Mula Oktubre 1 hanggang Abril 30","Mula Nobyembre 1 hanggang Marso 31","Mula Disyembre 1 hanggang katapusan ng Pebrero","Kahit anong oras ng taon"],"h1":"Nagsisimula ang panahong ito sa taglagas at natatapos sa tagsibol.","h2":"Sa Nevada, puwede lamang gamitin ang studded snow tire mula Oktubre 1 hanggang Abril 30.","p":"Tama. Pinapayagan ang studded tire mula Oktubre 1 hanggang Abril 30."},"ar":{"q":"في Nevada، متى يجوز لك استخدام إطارات الثلج ذات المسامير؟","o":["من 1 أكتوبر حتى 30 أبريل","من 1 نوفمبر حتى 31 مارس","من 1 ديسمبر حتى نهاية فبراير","في أي وقت من السنة"],"h1":"يبدأ هذا الموسم في الخريف وينتهي في الربيع.","h2":"في Nevada، يجوز استخدام إطارات الثلج ذات المسامير فقط من 1 أكتوبر حتى 30 أبريل.","p":"صحيح. الإطارات ذات المسامير مسموحة من 1 أكتوبر حتى 30 أبريل."},"ref":{"doc":"NV","page":57}},{"id":"nv-048","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, how many people must be in a car to use an HOV (carpool) lane?","o":["Only the driver","At least 3","At least 2","At least 4"],"h1":"The driver and one passenger are enough.","h2":"In Nevada, a car needs at least 2 people in it to use an HOV (carpool) lane.","p":"Right. Two or more people may use the carpool lane."},"es":{"q":"En Nevada, ¿cuántas personas deben ir en un carro para usar un carril HOV (de vehículos compartidos)?","o":["Solo el conductor","Por lo menos 3","Por lo menos 2","Por lo menos 4"],"h1":"Basta con el conductor y un pasajero.","h2":"En Nevada, un carro necesita por lo menos 2 personas para usar un carril HOV (de vehículos compartidos).","p":"Correcto. Dos o más personas pueden usar el carril de vehículos compartidos."},"zh":{"q":"在 Nevada，车里至少要有几个人才能用 HOV（拼车）车道？","o":["只有司机","至少 3 人","至少 2 人","至少 4 人"],"h1":"司机加一名乘客就够了。","h2":"在 Nevada，车里至少要有 2 个人才能用 HOV（拼车）车道。","p":"对。两个人或以上可以用拼车车道。"},"vi":{"q":"Ở Nevada, trong xe phải có bao nhiêu người mới được dùng làn HOV (làn đi chung xe)?","o":["Chỉ người lái xe","Ít nhất 3 người","Ít nhất 2 người","Ít nhất 4 người"],"h1":"Người lái xe và một hành khách là đủ.","h2":"Ở Nevada, trong xe cần có ít nhất 2 người mới được dùng làn HOV (làn đi chung xe).","p":"Đúng. Hai người trở lên được dùng làn đi chung xe."},"tl":{"q":"Sa Nevada, ilang tao ang dapat nasa kotse para magamit ang HOV (carpool) lane?","o":["Ang drayber lamang","Hindi bababa sa 3","Hindi bababa sa 2","Hindi bababa sa 4"],"h1":"Sapat na ang drayber at isang pasahero.","h2":"Sa Nevada, kailangang may hindi bababa sa 2 tao sa kotse para magamit ang HOV (carpool) lane.","p":"Tama. Puwedeng gumamit ng carpool lane ang dalawa o higit pang tao."},"ar":{"q":"في Nevada، كم شخصًا يجب أن يكون في السيارة لاستخدام مسار HOV (مسار المشاركة في الركوب)؟","o":["السائق فقط","3 أشخاص على الأقل","شخصان (2) على الأقل","4 أشخاص على الأقل"],"h1":"السائق وراكب واحد يكفيان.","h2":"في Nevada، يجب أن يكون في السيارة شخصان (2) على الأقل لاستخدام مسار HOV (مسار المشاركة في الركوب).","p":"صحيح. يمكن لشخصين أو أكثر استخدام مسار المشاركة في الركوب."},"ref":{"doc":"NV","page":39}},{"id":"nv-049","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, who may not ride in the open bed of a pickup truck on a paved highway, except in a parade or for farm or ranch work?","o":["Only children under 6","Anyone under 18","Only children under 12","Anyone over 65"],"h1":"It is anyone who is not yet an adult.","h2":"In Nevada, no one under 18 may ride in the bed of a pickup truck on a paved highway, except in an approved parade or for farm or ranch work.","p":"Right. No one under 18 may ride in a pickup bed on a paved highway."},"es":{"q":"En Nevada, ¿quién no puede viajar en la caja abierta de una camioneta pickup en una carretera pavimentada, salvo en un desfile o en trabajo de granja o rancho?","o":["Solo los niños menores de 6 años","Cualquier persona menor de 18 años","Solo los niños menores de 12 años","Cualquier persona mayor de 65 años"],"h1":"Es cualquier persona que todavía no es adulta.","h2":"En Nevada, ninguna persona menor de 18 años puede viajar en la caja de una camioneta pickup en una carretera pavimentada, salvo en un desfile autorizado o en trabajo de granja o rancho.","p":"Correcto. Nadie menor de 18 años puede viajar en la caja de una pickup en una carretera pavimentada."},"zh":{"q":"在 Nevada，除了游行或农场、牧场工作以外，谁不可以在铺好的公路上坐在皮卡的露天车斗里？","o":["只有不到 6 岁的孩子","任何不到 18 岁的人","只有不到 12 岁的孩子","任何超过 65 岁的人"],"h1":"是任何还不是成年人的人。","h2":"在 Nevada，不到 18 岁的人都不可以在铺好的公路上坐在皮卡车斗里，除非是在批准的游行中或做农场、牧场工作。","p":"对。不到 18 岁的人不可以在铺好的公路上坐皮卡车斗。"},"vi":{"q":"Ở Nevada, ai không được ngồi ở thùng sau để trống của xe bán tải trên đường cao tốc trải nhựa, trừ khi đi diễu hành hoặc làm việc ở nông trại hay trại chăn nuôi?","o":["Chỉ trẻ em dưới 6 tuổi","Bất cứ ai dưới 18 tuổi","Chỉ trẻ em dưới 12 tuổi","Bất cứ ai trên 65 tuổi"],"h1":"Đó là bất cứ ai chưa phải là người lớn.","h2":"Ở Nevada, không ai dưới 18 tuổi được ngồi ở thùng sau xe bán tải trên đường cao tốc trải nhựa, trừ khi đi trong một cuộc diễu hành được chấp thuận hoặc làm việc ở nông trại hay trại chăn nuôi.","p":"Đúng. Không ai dưới 18 tuổi được ngồi thùng sau xe bán tải trên đường trải nhựa."},"tl":{"q":"Sa Nevada, sino ang hindi puwedeng sumakay sa bukas na likuran (bed) ng pickup truck sa sementadong highway, maliban sa parada o sa trabaho sa bukid o rantso?","o":["Mga batang wala pang 6 lamang","Sinumang wala pang 18","Mga batang wala pang 12 lamang","Sinumang lampas 65"],"h1":"Ito ay sinumang hindi pa adulto.","h2":"Sa Nevada, walang sinumang wala pang 18 ang puwedeng sumakay sa bed ng pickup truck sa sementadong highway, maliban sa aprubadong parada o sa trabaho sa bukid o rantso.","p":"Tama. Walang wala pang 18 ang puwedeng sumakay sa bed ng pickup sa sementadong highway."},"ar":{"q":"في Nevada، من الذي لا يجوز له أن يركب في الصندوق الخلفي المكشوف لشاحنة بيك أب على طريق سريع معبّد، إلا في استعراض أو لعمل في مزرعة أو مزرعة مواشٍ؟","o":["الأطفال تحت 6 سنوات فقط","أي شخص تحت 18 سنة","الأطفال تحت 12 سنة فقط","أي شخص فوق 65 سنة"],"h1":"هو أي شخص لم يصبح بالغًا بعد.","h2":"في Nevada، لا يجوز لأي شخص تحت 18 سنة أن يركب في الصندوق الخلفي لشاحنة بيك أب على طريق سريع معبّد، إلا في استعراض معتمد أو لعمل في مزرعة أو مزرعة مواشٍ.","p":"صحيح. لا يجوز لأي شخص تحت 18 سنة أن يركب في صندوق البيك أب على طريق سريع معبّد."},"ref":{"doc":"NV","page":66}},{"id":"nv-050","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, what can you dial on a cell phone to report a driver you think is drunk?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"The letters stand for the Nevada Highway Patrol.","h2":"In Nevada, you can report a suspected drunk driver or a highway emergency by dialing *NHP, which is *647.","p":"Right. Dial *NHP (*647) to report a drunk driver."},"es":{"q":"En Nevada, ¿qué número puede marcar en un teléfono celular para reportar a un conductor que usted cree que está borracho?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"Las letras son de la Patrulla de Carreteras de Nevada (Nevada Highway Patrol).","h2":"En Nevada, usted puede reportar a un conductor que parece borracho o una emergencia en la carretera marcando *NHP, que es *647.","p":"Correcto. Marque *NHP (*647) para reportar a un conductor borracho."},"zh":{"q":"在 Nevada，你可以用手机拨什么号码来举报你认为喝醉的司机？","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"这些字母代表 Nevada 公路巡警（Nevada Highway Patrol）。","h2":"在 Nevada，你可以拨 *NHP，也就是 *647，来举报可能喝醉的司机或公路上的紧急情况。","p":"对。拨 *NHP（*647）举报醉酒司机。"},"vi":{"q":"Ở Nevada, bạn có thể bấm số nào trên điện thoại di động để báo một người lái xe mà bạn nghĩ là say rượu?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"Các chữ cái này là viết tắt của Cảnh sát Xa lộ Nevada (Nevada Highway Patrol).","h2":"Ở Nevada, bạn có thể báo một người lái xe nghi say rượu hoặc một trường hợp khẩn cấp trên xa lộ bằng cách bấm *NHP, tức là *647.","p":"Đúng. Bấm *NHP (*647) để báo người lái xe say rượu."},"tl":{"q":"Sa Nevada, ano ang puwede mong i-dial sa cell phone para i-report ang drayber na sa tingin mo ay lasing?","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"Ang mga titik ay para sa Nevada Highway Patrol.","h2":"Sa Nevada, puwede mong i-report ang pinaghihinalaang lasing na drayber o emergency sa highway sa pag-dial ng *NHP, na *647.","p":"Tama. I-dial ang *NHP (*647) para i-report ang lasing na drayber."},"ar":{"q":"في Nevada، ما الرقم الذي يمكنك أن تتصل به من الهاتف المحمول للإبلاغ عن سائق تظن أنه سكران؟","o":["*311","*411","*368 (*DMV)","*647 (*NHP)"],"h1":"الحروف تعني دورية الطرق السريعة في Nevada (Nevada Highway Patrol).","h2":"في Nevada، يمكنك الإبلاغ عن سائق يُشتبه بأنه سكران أو عن حالة طارئة على الطريق السريع بالاتصال بالرقم *NHP، أي *647.","p":"صحيح. اتصل بالرقم *NHP (*647) للإبلاغ عن سائق سكران."},"ref":{"doc":"NV","page":81}},{"id":"nv-051","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, which rule applies to a rider with a motorcycle instruction permit?","o":["Ride only in daylight hours","Ride at night only with a supervisor","Carry one passenger who is at least 21","Ride on freeways only with a supervisor"],"h1":"Permit riders may not carry passengers or use freeways.","h2":"In Nevada, a rider with a motorcycle instruction permit may ride only in daylight, with no passengers and not on freeways.","p":"Right. Motorcycle permit riders ride in daylight only."},"es":{"q":"En Nevada, ¿qué regla se aplica a quien tiene un permiso de instrucción de motocicleta?","o":["Manejar solo durante las horas de luz del día","Manejar de noche solo con un supervisor","Llevar un pasajero de por lo menos 21 años","Manejar en autopistas solo con un supervisor"],"h1":"Con el permiso no se pueden llevar pasajeros ni usar autopistas.","h2":"En Nevada, quien tiene un permiso de instrucción de motocicleta solo puede manejar de día, sin pasajeros y no en autopistas.","p":"Correcto. Con el permiso de motocicleta se maneja solo de día."},"zh":{"q":"在 Nevada，持有摩托车学习许可证的骑手要遵守哪条规定？","o":["只能在白天骑","有监督人陪同才能在晚上骑","可以带一名至少 21 岁的乘客","有监督人陪同才能上高速公路"],"h1":"持学习许可证的骑手不可以带乘客，也不可以上高速公路。","h2":"在 Nevada，持有摩托车学习许可证的骑手只能在白天骑，不能带乘客，也不能上高速公路。","p":"对。持摩托车学习许可证只能在白天骑。"},"vi":{"q":"Ở Nevada, quy định nào áp dụng cho người có giấy phép tập lái xe máy?","o":["Chỉ chạy vào ban ngày","Chạy ban đêm chỉ khi có người giám sát","Chở một hành khách ít nhất 21 tuổi","Chạy trên xa lộ cao tốc chỉ khi có người giám sát"],"h1":"Người có giấy phép tập lái không được chở hành khách và không được chạy trên xa lộ cao tốc.","h2":"Ở Nevada, người có giấy phép tập lái xe máy chỉ được chạy vào ban ngày, không được chở hành khách và không được chạy trên xa lộ cao tốc.","p":"Đúng. Người có giấy phép tập lái xe máy chỉ chạy vào ban ngày."},"tl":{"q":"Sa Nevada, aling patakaran ang para sa rider na may motorcycle instruction permit?","o":["Magmaneho lamang sa oras na may liwanag ng araw","Magmaneho sa gabi lamang kung may supervisor","Magsakay ng isang pasaherong hindi bababa sa 21","Magmaneho sa freeway lamang kung may supervisor"],"h1":"Hindi puwedeng magsakay ng pasahero o gumamit ng freeway ang mga rider na may permit.","h2":"Sa Nevada, ang rider na may motorcycle instruction permit ay puwede lamang magmaneho kapag may liwanag ng araw, walang pasahero, at hindi sa freeway.","p":"Tama. Sa araw lamang nagmamaneho ang mga rider na may motorcycle permit."},"ar":{"q":"في Nevada، أي قاعدة تنطبق على راكب الدرّاجة النارية الذي يحمل تصريح تعلّم للدرّاجة النارية؟","o":["القيادة في ساعات النهار فقط","القيادة ليلًا فقط مع مشرف","حمل راكب واحد عمره 21 سنة على الأقل","القيادة على الطرق السريعة فقط مع مشرف"],"h1":"يجب ألّا يحمل أصحاب التصريح ركّابًا أو يستخدموا الطرق السريعة.","h2":"في Nevada، يجوز لصاحب تصريح تعلّم الدرّاجة النارية أن يقود في النهار فقط، من دون ركّاب، وليس على الطرق السريعة.","p":"صحيح. أصحاب تصريح الدرّاجة النارية يقودون في النهار فقط."},"ref":{"doc":"NV","page":18}},{"id":"nv-052","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, you move here from another state. How soon must you apply for a Nevada driver license?","o":["Within 30 days after becoming a resident","Within 90 days after becoming a resident","Within 6 months after becoming a resident","Only when your old license expires"],"h1":"It is about one month.","h2":"In Nevada, a driver who moves here from another state must apply for a Nevada license within 30 days after becoming a resident.","p":"Right. New residents apply within 30 days."},"es":{"q":"En Nevada, usted se muda aquí desde otro estado. ¿En cuánto tiempo debe solicitar una licencia de manejo de Nevada?","o":["Dentro de 30 días después de hacerse residente","Dentro de 90 días después de hacerse residente","Dentro de 6 meses después de hacerse residente","Solo cuando venza su licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Nevada, un conductor que se muda aquí desde otro estado debe solicitar una licencia de Nevada dentro de 30 días después de hacerse residente.","p":"Correcto. Los nuevos residentes la solicitan dentro de 30 días."},"ref":{"doc":"NV","page":6}},{"id":"nv-053","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how long is a driver license valid for a person aged 65 or older?","o":["Two years","Four years","Eight years","Ten years"],"h1":"It is half as long as for younger drivers.","h2":"In Nevada, a driver license for a person aged 65 or older is valid for four years.","p":"Right. At 65 and older, a license lasts four years."},"es":{"q":"En Nevada, ¿por cuánto tiempo es válida la licencia de manejo de una persona de 65 años o más?","o":["Dos años","Cuatro años","Ocho años","Diez años"],"h1":"Es la mitad del tiempo que para los conductores más jóvenes.","h2":"En Nevada, la licencia de manejo de una persona de 65 años o más es válida por cuatro años.","p":"Correcto. A partir de los 65 años, la licencia dura cuatro años."},"ref":{"doc":"NV","page":6}},{"id":"nv-054","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you move here with a valid license from another state. Which test will the DMV always give you?","o":["The drive test","The knowledge test","The vision test","No test at all"],"h1":"The other tests may be waived, but not this one.","h2":"In Nevada, your vision is always tested when you apply for a Nevada license; the other tests may be waived if you meet certain conditions.","p":"Right. The vision test is always given."},"es":{"q":"En Nevada, usted se muda aquí con una licencia válida de otro estado. ¿Qué examen le hará siempre el DMV?","o":["El examen de manejo","El examen de conocimientos","El examen de la vista","Ningún examen"],"h1":"Los otros exámenes se pueden omitir, pero este no.","h2":"En Nevada, siempre le examinan la vista cuando solicita una licencia de Nevada; los otros exámenes se pueden omitir si usted cumple ciertas condiciones.","p":"Correcto. El examen de la vista siempre se hace."},"ref":{"doc":"NV","page":7}},{"id":"nv-055","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, you have a valid license from another state. To have the knowledge and drive tests waived, how old must you be, among other rules?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"It is the same as the legal age to drink alcohol.","h2":"In Nevada, the knowledge and drive tests can be waived for a driver with a valid out-of-state license only if the driver is 21 or older and meets the other rules.","p":"Right. You must be 21 or older."},"es":{"q":"En Nevada, usted tiene una licencia válida de otro estado. Para que no le hagan los exámenes de conocimientos y de manejo, ¿cuántos años debe tener, entre otras reglas?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"Es la misma edad legal para beber alcohol.","h2":"En Nevada, a un conductor con licencia válida de otro estado le pueden omitir los exámenes de conocimientos y de manejo solo si tiene 21 años o más y cumple las otras reglas.","p":"Correcto. Debe tener 21 años o más."},"ref":{"doc":"NV","page":7}},{"id":"nv-056","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, how can you tell that a driver license is a Real ID?","o":["It has a gold Nevada outline with a star cut out","It has a red stripe across the top","It says NOT FOR REAL ID PURPOSES","It has a blue photo background"],"h1":"Look for the shape of the state and a star.","h2":"In Nevada, a Real ID license has a gold outline of Nevada with a star cut out; a standard card says NOT FOR REAL ID PURPOSES.","p":"Right. The gold Nevada outline with a star means Real ID."},"es":{"q":"En Nevada, ¿cómo puede saber que una licencia de manejo es Real ID?","o":["Tiene la silueta dorada de Nevada con una estrella recortada","Tiene una franja roja en la parte de arriba","Dice NOT FOR REAL ID PURPOSES","Tiene un fondo azul en la foto"],"h1":"Busque la forma del estado y una estrella.","h2":"En Nevada, una licencia Real ID tiene la silueta dorada de Nevada con una estrella recortada; una tarjeta estándar dice NOT FOR REAL ID PURPOSES.","p":"Correcto. La silueta dorada de Nevada con una estrella indica Real ID."},"ref":{"doc":"NV","page":9}},{"id":"nv-057","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, what happens if you use a cell phone during your drive test?","o":["You lose 5 points","You fail the test automatically","The examiner gives you a warning","Nothing, if the car is stopped"],"h1":"The result is the worst one possible.","h2":"In Nevada, using a cell phone during the drive test means you fail the test automatically.","p":"Right. A phone during the drive test is an automatic fail."},"es":{"q":"En Nevada, ¿qué pasa si usted usa un teléfono celular durante el examen de manejo?","o":["Pierde 5 puntos","Reprueba el examen automáticamente","El examinador le da una advertencia","Nada, si el auto está detenido"],"h1":"Es el peor resultado posible.","h2":"En Nevada, usar un teléfono celular durante el examen de manejo significa que usted reprueba el examen automáticamente.","p":"Correcto. Usar el teléfono en el examen de manejo es reprobar automáticamente."},"ref":{"doc":"NV","page":12}},{"id":"nv-058","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, your license shows Restriction B. What does it mean?","o":["You may drive only in daylight","You need extra rearview mirrors","You must wear glasses or contact lenses to drive","You need a yearly driving test"],"h1":"It is linked to the vision test.","h2":"In Nevada, Restriction B on a license means the driver must wear glasses or contact lenses to drive.","p":"Right. Restriction B means glasses or contacts."},"es":{"q":"En Nevada, su licencia tiene la Restricción B. ¿Qué significa?","o":["Solo puede manejar de día","Necesita espejos retrovisores adicionales","Debe usar anteojos o lentes de contacto para manejar","Necesita un examen de manejo cada año"],"h1":"Está relacionada con el examen de la vista.","h2":"En Nevada, la Restricción B en la licencia significa que el conductor debe usar anteojos o lentes de contacto para manejar.","p":"Correcto. La Restricción B significa anteojos o lentes de contacto."},"ref":{"doc":"NV","page":16}},{"id":"nv-059","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, you are 18 or older and get a motorcycle instruction permit. How long is it valid?","o":["One month","Two years","One year","Six months"],"h1":"It is shorter than the permit for riders under 18.","h2":"In Nevada, a motorcycle instruction permit issued to a person 18 or older is valid for six months.","p":"Right. For adults, it is valid for six months."},"es":{"q":"En Nevada, usted tiene 18 años o más y obtiene un permiso de instrucción de motocicleta. ¿Por cuánto tiempo es válido?","o":["Un mes","Dos años","Un año","Seis meses"],"h1":"Es más corto que el permiso para quienes tienen menos de 18 años.","h2":"En Nevada, un permiso de instrucción de motocicleta para una persona de 18 años o más es válido por seis meses.","p":"Correcto. Para adultos, es válido por seis meses."},"ref":{"doc":"NV","page":18}},{"id":"nv-060","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what happens if you fail the DMV motorcycle skills test two or more times?","o":["You can never get another motorcycle instruction permit","You must wait 30 days to try again","Your car license is suspended","Nothing; you may keep trying"],"h1":"The result is permanent.","h2":"In Nevada, failing the DMV motorcycle skills test two or more times means you are permanently denied future motorcycle instruction permits.","p":"Right. It means a permanent denial of motorcycle permits."},"es":{"q":"En Nevada, ¿qué pasa si usted reprueba dos o más veces el examen de habilidades de motocicleta del DMV?","o":["Nunca puede obtener otro permiso de instrucción de motocicleta","Debe esperar 30 días para intentarlo de nuevo","Le suspenden su licencia de auto","Nada; puede seguir intentando"],"h1":"El resultado es permanente.","h2":"En Nevada, reprobar dos o más veces el examen de habilidades de motocicleta del DMV significa que le niegan para siempre futuros permisos de instrucción de motocicleta.","p":"Correcto. Significa que le niegan los permisos de motocicleta para siempre."},"ref":{"doc":"NV","page":18}},{"id":"nv-061","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, which license lets you ride a moped?","o":["Only a Class M license","Any class of Nevada driver license","Only a commercial driver license","No license is needed for a moped"],"h1":"A regular car license is enough.","h2":"In Nevada, you may ride a moped with any class of Nevada driver license, or with a Class M license limited to mopeds.","p":"Right. Any class of Nevada license lets you ride a moped."},"es":{"q":"En Nevada, ¿qué licencia le permite manejar un ciclomotor (moped)?","o":["Solo una licencia Clase M","Cualquier clase de licencia de manejo de Nevada","Solo una licencia de manejo comercial","No se necesita licencia para un ciclomotor"],"h1":"Una licencia normal de auto es suficiente.","h2":"En Nevada, usted puede manejar un ciclomotor con cualquier clase de licencia de manejo de Nevada, o con una licencia Clase M limitada a ciclomotores.","p":"Correcto. Cualquier clase de licencia de Nevada le permite manejar un ciclomotor."},"ref":{"doc":"NV","page":16}},{"id":"nv-062","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, who may get a restricted license at age 14 or 15?","o":["Any teen who passes the knowledge test","A teen who finishes driver education early","A teen with a family hardship or a need to drive to and from school","No one under 15 and a half"],"h1":"It is only for special cases.","h2":"In Nevada, a restricted license may be issued to drivers aged 14 or 15 who show a family hardship or need to drive to and from school.","p":"Right. It is for family hardship or getting to school."},"es":{"q":"En Nevada, ¿quién puede obtener una licencia restringida a los 14 o 15 años?","o":["Cualquier adolescente que apruebe el examen de conocimientos","Un adolescente que termine pronto la educación vial","Un adolescente con una necesidad familiar grave o que necesite manejar para ir y volver de la escuela","Nadie menor de 15 años y medio"],"h1":"Es solo para casos especiales.","h2":"En Nevada, se puede dar una licencia restringida a conductores de 14 o 15 años que demuestren una necesidad familiar grave o que necesiten manejar para ir y volver de la escuela.","p":"Correcto. Es para necesidad familiar o para ir a la escuela."},"ref":{"doc":"NV","page":19}},{"id":"nv-063","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, you are under 18 and apply for an instruction permit. What school form must you give the DMV?","o":["A copy of your report card","A letter from a teacher","Your class schedule","A DMV-301 Certification of Attendance signed by the school"],"h1":"It shows you meet the school attendance rules.","h2":"In Nevada, a permit applicant under 18 must give the DMV a DMV-301 Certification of Attendance signed by the principal or a school official.","p":"Right. You need the DMV-301 attendance form."},"es":{"q":"En Nevada, usted tiene menos de 18 años y solicita un permiso de instrucción. ¿Qué formulario de la escuela debe entregar al DMV?","o":["Una copia de su boleta de calificaciones","Una carta de un maestro","Su horario de clases","Un formulario DMV-301 de Certificación de Asistencia firmado por la escuela"],"h1":"Muestra que usted cumple las reglas de asistencia escolar.","h2":"En Nevada, quien solicita un permiso y tiene menos de 18 años debe entregar al DMV un formulario DMV-301 de Certificación de Asistencia firmado por el director o un funcionario de la escuela.","p":"Correcto. Necesita el formulario de asistencia DMV-301."},"ref":{"doc":"NV","page":13}},{"id":"nv-064","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what is the youngest age to get a state identification (ID) card?","o":["10 years old","5 years old","14 years old","16 years old"],"h1":"A child in grade school can get one.","h2":"In Nevada, you must be at least 10 years old to get an identification card.","p":"Right. You can get a Nevada ID card at 10."},"es":{"q":"En Nevada, ¿cuál es la edad mínima para obtener una tarjeta de identificación (ID) del estado?","o":["10 años","5 años","14 años","16 años"],"h1":"Un niño de primaria puede obtenerla.","h2":"En Nevada, usted debe tener por lo menos 10 años para obtener una tarjeta de identificación.","p":"Correcto. Puede obtener una tarjeta de identificación de Nevada a los 10 años."},"ref":{"doc":"NV","page":20}},{"id":"nv-065","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, who must wear a seat belt when the car has one?","o":["Only the driver","The driver and every passenger aged six and older","Only people in the front seat","Only passengers under 18"],"h1":"Young children ride in a child seat instead.","h2":"In Nevada, the driver and every passenger aged six and older must wear a seat belt if the car has one.","p":"Right. The driver and all passengers six and older buckle up."},"es":{"q":"En Nevada, ¿quién debe usar el cinturón de seguridad si el vehículo lo tiene?","o":["Solo el conductor","El conductor y todos los pasajeros de seis años o más","Solo las personas del asiento delantero","Solo los pasajeros menores de 18 años"],"h1":"Los niños pequeños usan un asiento infantil.","h2":"En Nevada, el conductor y todos los pasajeros de seis años o más deben usar el cinturón de seguridad si el vehículo lo tiene.","p":"Correcto. El conductor y todos los pasajeros de seis años o más se abrochan."},"ref":{"doc":"NV","page":25}},{"id":"nv-066","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, a dog is left alone in a parked car on a very hot day. Which is true?","o":["It is legal if a window is open","It is legal for up to 30 minutes","It is illegal, and officers or firefighters may use reasonable force to rescue it","It is illegal only for cats, not dogs"],"h1":"The law protects both dogs and cats.","h2":"In Nevada, it is illegal to leave a dog or cat alone in a car in extreme heat or cold, and officers, firefighters and other officials may use reasonable force to rescue it.","p":"Right. It is illegal, and officials may use force to rescue the pet."},"es":{"q":"En Nevada, dejan a un perro solo en un auto estacionado en un día muy caluroso. ¿Qué es cierto?","o":["Es legal si una ventana está abierta","Es legal hasta por 30 minutos","Es ilegal, y los oficiales o bomberos pueden usar fuerza razonable para rescatarlo","Es ilegal solo para gatos, no para perros"],"h1":"La ley protege tanto a perros como a gatos.","h2":"En Nevada, es ilegal dejar a un perro o un gato solo en un auto con calor o frío extremo, y los oficiales, bomberos y otros funcionarios pueden usar fuerza razonable para rescatarlo.","p":"Correcto. Es ilegal, y los funcionarios pueden usar la fuerza para rescatar a la mascota."},"ref":{"doc":"NV","page":25}},{"id":"nv-067","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, what is the most common type of crash on streets and highways?","o":["Head-on crashes","Side-impact crashes at intersections","Single-car rollovers","Rear-end crashes"],"h1":"It happens when a driver follows too closely or stops too late.","h2":"In Nevada, the rear-end collision is the number one type of crash on streets and highways.","p":"Right. Rear-end crashes are number one."},"es":{"q":"En Nevada, ¿cuál es el tipo de choque más común en calles y carreteras?","o":["Choques de frente","Choques laterales en intersecciones","Volcaduras de un solo vehículo","Choques por alcance (por detrás)"],"h1":"Ocurre cuando un conductor sigue muy de cerca o frena demasiado tarde.","h2":"En Nevada, el choque por alcance (por detrás) es el tipo de choque número uno en calles y carreteras.","p":"Correcto. Los choques por alcance son el número uno."},"ref":{"doc":"NV","page":41}},{"id":"nv-068","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, in heavy rain, at what speeds do most cars start to lose traction and hydroplane?","o":["Between 35 and 55 mph","Only above 75 mph","Below 20 mph","Only above 65 mph"],"h1":"It can happen at normal city and highway speeds.","h2":"In Nevada, most cars begin to lose traction and hydroplane between 35 and 55 mph in heavy rain.","p":"Right. Hydroplaning can start between 35 and 55 mph."},"es":{"q":"En Nevada, con lluvia fuerte, ¿a qué velocidades la mayoría de los autos empiezan a perder tracción e hidroplanear?","o":["Entre 35 y 55 mph","Solo a más de 75 mph","A menos de 20 mph","Solo a más de 65 mph"],"h1":"Puede pasar a velocidades normales de ciudad y carretera.","h2":"En Nevada, la mayoría de los autos empiezan a perder tracción e hidroplanear entre 35 y 55 mph con lluvia fuerte.","p":"Correcto. El hidroplaneo puede empezar entre 35 y 55 mph."},"ref":{"doc":"NV","page":41}},{"id":"nv-069","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, from when to when must you use headlights at night?","o":["From sunset to sunrise","From a half hour after sunset to a half hour before sunrise","From 8 p.m. to 6 a.m.","From one hour after sunset to one hour before sunrise"],"h1":"Count half an hour on each side.","h2":"In Nevada, headlights are required from a half hour after sunset until a half hour before sunrise.","p":"Right. Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Nevada, ¿desde cuándo hasta cuándo debe usar los faros por la noche?","o":["Desde la puesta del sol hasta la salida del sol","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Desde las 8 p.m. hasta las 6 a.m.","Desde una hora después de la puesta del sol hasta una hora antes de la salida del sol"],"h1":"Cuente media hora de cada lado.","h2":"En Nevada, los faros son obligatorios desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Desde media hora después de la puesta del sol hasta media hora antes de la salida."},"ref":{"doc":"NV","page":56}},{"id":"nv-070","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, you are using high beams at night. A car is coming toward you. At what distance should you switch to low beams?","o":["At least 100 feet before it","At least 200 feet before it","At least 500 feet before it","At least 1,000 feet before it"],"h1":"It is more than 300 feet and less than 1,000 feet.","h2":"In Nevada, you should switch to low beams when you are at least 500 feet from an oncoming vehicle.","p":"Right. Dim your lights at least 500 feet before an oncoming car."},"es":{"q":"En Nevada, usted usa las luces altas de noche. Viene un auto de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["Por lo menos 100 pies antes","Por lo menos 200 pies antes","Por lo menos 500 pies antes","Por lo menos 1,000 pies antes"],"h1":"Es más de 300 pies y menos de 1,000 pies.","h2":"En Nevada, usted debe cambiar a luces bajas cuando está por lo menos a 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces por lo menos 500 pies antes de un auto que viene de frente."},"ref":{"doc":"NV","page":56}},{"id":"nv-071","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, you have just driven through deep water. How should you dry your brakes?","o":["Brake hard once at full speed","Drive fast so the wind dries them","Park and wait one hour","Drive slowly in low gear and press the brakes lightly, testing them about every 200 feet"],"h1":"Go slowly and use light pressure.","h2":"In Nevada, to dry wet brakes you drive slowly in low gear, press the brakes lightly, and test them about every 200 feet until they work normally.","p":"Right. Drive slowly in low gear and brake lightly until they work again."},"es":{"q":"En Nevada, usted acaba de pasar por agua profunda. ¿Cómo debe secar los frenos?","o":["Frenar fuerte una vez a toda velocidad","Manejar rápido para que el viento los seque","Estacionarse y esperar una hora","Manejar despacio en una marcha baja y frenar suavemente, probándolos cada 200 pies más o menos"],"h1":"Vaya despacio y presione suavemente.","h2":"En Nevada, para secar los frenos mojados usted maneja despacio en una marcha baja, frena suavemente y los prueba cada 200 pies más o menos hasta que funcionen normalmente.","p":"Correcto. Maneje despacio en una marcha baja y frene suavemente hasta que vuelvan a funcionar."},"ref":{"doc":"NV","page":58}},{"id":"nv-072","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, what happens to the fine for speeding in a work zone?","o":["It is doubled","It stays the same","It is cut in half","It is replaced by a warning"],"h1":"Breaking the law there costs more than usual.","h2":"In Nevada, fines for speeding double in work zones.","p":"Right. Speeding fines double in work zones."},"es":{"q":"En Nevada, ¿qué pasa con la multa por exceso de velocidad en una zona de trabajo?","o":["Se duplica","Sigue igual","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Romper la ley ahí cuesta más de lo normal.","h2":"En Nevada, las multas por exceso de velocidad se duplican en las zonas de trabajo.","p":"Correcto. Las multas por exceso de velocidad se duplican en zonas de trabajo."},"ref":{"doc":"NV","page":60}},{"id":"nv-073","scope":"NV","cat":"signals","sign":null,"c":1,"en":{"q":"In Nevada, in a work zone, what does an orange speed limit sign mean?","o":["It is the legal limit, the same as a black and white sign","It is an advisory speed: a slower, safer speed","It applies only to trucks","It applies only at night"],"h1":"Black and white speed signs are the regulatory ones.","h2":"In Nevada, an orange speed limit sign in a work zone is advisory and shows a slower, safer speed; black and white speed limit signs are regulatory.","p":"Right. Orange speed signs advise a slower, safer speed."},"es":{"q":"En Nevada, en una zona de trabajo, ¿qué significa un letrero naranja de límite de velocidad?","o":["Es el límite legal, igual que un letrero blanco y negro","Es una velocidad recomendada: más lenta y más segura","Se aplica solo a camiones","Se aplica solo de noche"],"h1":"Los letreros de velocidad blancos y negros son los obligatorios.","h2":"En Nevada, un letrero naranja de límite de velocidad en una zona de trabajo es una recomendación y muestra una velocidad más lenta y segura; los letreros blancos y negros de límite de velocidad son obligatorios.","p":"Correcto. Los letreros naranjas recomiendan una velocidad más lenta y segura."},"ref":{"doc":"NV","page":60}},{"id":"nv-074","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, a police officer stops you at night. What should you do?","o":["Get out and walk to the police car","Turn off all lights and wait","Stay in the car, turn on the inside light, and keep your hands in view","Search for your papers before the officer arrives"],"h1":"Good lighting helps, and the officer must see your hands.","h2":"In Nevada, if you are stopped at night, stay in your car, turn on the inside light, and keep your hands in plain view, such as on the steering wheel.","p":"Right. Stay in the car, turn on the light, and keep your hands in view."},"es":{"q":"En Nevada, un oficial de policía lo detiene de noche. ¿Qué debe hacer?","o":["Bajarse y caminar hasta la patrulla","Apagar todas las luces y esperar","Quedarse en el auto, encender la luz interior y mantener las manos a la vista","Buscar sus documentos antes de que llegue el oficial"],"h1":"La buena iluminación ayuda, y el oficial debe ver sus manos.","h2":"En Nevada, si lo detienen de noche, quédese en el auto, encienda la luz interior y mantenga las manos a la vista, por ejemplo en el volante.","p":"Correcto. Quédese en el auto, encienda la luz y mantenga las manos a la vista."},"ref":{"doc":"NV","page":43}},{"id":"nv-075","scope":"NV","cat":"signals","sign":null,"c":3,"en":{"q":"In Nevada, you come to an intersection where the traffic lights are not working. What must you do?","o":["Go through if no one is coming","Slow down and yield only to cars on the right","Honk and drive through","Come to a full stop, then go when it is safe"],"h1":"Treat it as if there were a stop sign.","h2":"In Nevada, when traffic lights are not working, you must come to a full stop, yield to people and vehicles already stopped or in the intersection, and then go with caution.","p":"Right. A dark signal means a full stop first."},"es":{"q":"En Nevada, usted llega a una intersección donde los semáforos no funcionan. ¿Qué debe hacer?","o":["Pasar si no viene nadie","Bajar la velocidad y ceder el paso solo a los autos de la derecha","Tocar la bocina y pasar","Hacer un alto total y luego seguir cuando sea seguro"],"h1":"Trátelo como si hubiera una señal de alto.","h2":"En Nevada, cuando los semáforos no funcionan, usted debe hacer un alto total, ceder el paso a las personas y vehículos que ya se detuvieron o están en la intersección, y luego seguir con precaución.","p":"Correcto. Un semáforo apagado significa primero un alto total."},"ref":{"doc":"NV","page":30}},{"id":"nv-076","scope":"NV","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nevada, when may you turn left on a red light after a full stop?","o":["From a one-way street onto another one-way street whose traffic moves left","From any street when no cars are coming","Never, a left turn on red is always illegal","Only at a T intersection"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Nevada, you may turn left on red, after a full stop and yielding, only from a one-way street onto another one-way street whose traffic moves to the left, unless a sign forbids it.","p":"Right. Left on red is only from one-way to one-way."},"es":{"q":"En Nevada, ¿cuándo puede dar vuelta a la izquierda con la luz roja después de un alto total?","o":["De una calle de un solo sentido a otra calle de un solo sentido cuyo tráfico va hacia la izquierda","Desde cualquier calle cuando no vienen autos","Nunca, la vuelta a la izquierda con luz roja siempre es ilegal","Solo en una intersección en forma de T"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Nevada, usted puede dar vuelta a la izquierda con luz roja, después de un alto total y de ceder el paso, solo de una calle de un solo sentido a otra calle de un solo sentido cuyo tráfico va hacia la izquierda, a menos que un letrero lo prohíba.","p":"Correcto. La vuelta a la izquierda con luz roja es solo de un solo sentido a un solo sentido."},"ref":{"doc":"NV","page":30}},{"id":"nv-077","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, a railroad crossing has a stop sign and a train is coming. How far from the tracks must you stop?","o":["At least 5 feet","At least 15 feet","At least 50 feet","At least 100 feet"],"h1":"It is less than 20 feet, but more than 10.","h2":"In Nevada, if a train is coming at a crossing, you must stop at least 15 feet from the tracks.","p":"Right. Stop at least 15 feet from the tracks."},"es":{"q":"En Nevada, un cruce de ferrocarril tiene una señal de alto y viene un tren. ¿A qué distancia de las vías debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 15 pies","Por lo menos a 50 pies","Por lo menos a 100 pies"],"h1":"Es menos de 20 pies, pero más de 10.","h2":"En Nevada, si viene un tren en un cruce, usted debe detenerse por lo menos a 15 pies de las vías.","p":"Correcto. Deténgase por lo menos a 15 pies de las vías."},"ref":{"doc":"NV","page":33}},{"id":"nv-078","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, what is the leading cause of crashes?","o":["Driving too slowly","Bad weather","Failing to yield the right-of-way","Flat tires"],"h1":"It is about who must let the other go first.","h2":"In Nevada, failing to yield the right-of-way is the leading cause of crashes.","p":"Right. Failure to yield is the leading cause of crashes."},"es":{"q":"En Nevada, ¿cuál es la causa principal de los choques?","o":["Manejar demasiado despacio","El mal tiempo","No ceder el derecho de paso","Las llantas ponchadas"],"h1":"Tiene que ver con quién debe dejar pasar primero al otro.","h2":"En Nevada, no ceder el derecho de paso es la causa principal de los choques.","p":"Correcto. No ceder el paso es la causa principal de los choques."},"ref":{"doc":"NV","page":34}},{"id":"nv-079","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a person with a white cane or a guide dog is crossing the street. What must you do?","o":["Honk so the person knows where you are","Call out directions to help","Drive around the person slowly","Yield, stop if needed, and take care before you go on"],"h1":"This person has the right-of-way at all times.","h2":"In Nevada, a blind or visually impaired person with a white cane or guide dog has the right-of-way, so you must yield, stop if needed, and take care before going on.","p":"Right. Yield and stop if needed for a person with a white cane or guide dog."},"es":{"q":"En Nevada, una persona con bastón blanco o con perro guía está cruzando la calle. ¿Qué debe hacer usted?","o":["Tocar la bocina para que la persona sepa dónde está usted","Darle instrucciones en voz alta para ayudarla","Rodear a la persona despacio","Ceder el paso, detenerse si es necesario y tener cuidado antes de seguir"],"h1":"Esta persona tiene el derecho de paso en todo momento.","h2":"En Nevada, una persona ciega o con baja visión que usa bastón blanco o perro guía tiene el derecho de paso, así que usted debe ceder el paso, detenerse si es necesario y tener cuidado antes de seguir.","p":"Correcto. Ceda el paso y deténgase si es necesario ante una persona con bastón blanco o perro guía."},"ref":{"doc":"NV","page":34}},{"id":"nv-080","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, how far ahead should you look when you drive on a freeway?","o":["At least 20 to 30 seconds ahead","About 2 seconds ahead","About 5 seconds ahead","Only at the car in front of you"],"h1":"It is farther than the 12 seconds used on city streets.","h2":"In Nevada, on a freeway you should look ahead at least 20 to 30 seconds.","p":"Right. On the freeway, look 20 to 30 seconds ahead."},"es":{"q":"En Nevada, ¿qué tan lejos debe mirar hacia adelante cuando maneja en una autopista?","o":["Por lo menos de 20 a 30 segundos hacia adelante","Unos 2 segundos hacia adelante","Unos 5 segundos hacia adelante","Solo al auto que va delante de usted"],"h1":"Es más lejos que los 12 segundos que se usan en la ciudad.","h2":"En Nevada, en la autopista usted debe mirar por lo menos de 20 a 30 segundos hacia adelante.","p":"Correcto. En la autopista, mire de 20 a 30 segundos hacia adelante."},"ref":{"doc":"NV","page":36}},{"id":"nv-081","scope":"NV","cat":"signals","sign":null,"c":1,"en":{"q":"In Nevada, a freeway lane signal above your lane shows a yellow X with the word CAUTION. What does it mean?","o":["The lane is closed; leave it now","You may use the lane, but watch for slow traffic or debris","The lane is only for buses","Speed up to clear the lane"],"h1":"A red X is the one that closes a lane.","h2":"In Nevada, a yellow X with CAUTION over a freeway lane means you may drive in that lane, but carefully, because of slow traffic or debris.","p":"Right. You may use the lane, with caution."},"es":{"q":"En Nevada, una señal sobre su carril en la autopista muestra una X amarilla con la palabra CAUTION. ¿Qué significa?","o":["El carril está cerrado; sálgase ahora","Puede usar el carril, pero tenga cuidado con tráfico lento u objetos en el camino","El carril es solo para autobuses","Acelere para salir del carril"],"h1":"La X roja es la que cierra un carril.","h2":"En Nevada, una X amarilla con la palabra CAUTION sobre un carril de autopista significa que usted puede manejar en ese carril, pero con cuidado por el tráfico lento u objetos en el camino.","p":"Correcto. Puede usar el carril, con precaución."},"ref":{"doc":"NV","page":37}},{"id":"nv-082","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, how close to a crosswalk may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"It is more than 15 feet and less than 30 feet.","h2":"In Nevada, you may not park on a crosswalk or within 20 feet of one.","p":"Right. Stay at least 20 feet from a crosswalk."},"es":{"q":"En Nevada, ¿qué tan cerca de un cruce peatonal puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 20 pies","No a menos de 50 pies"],"h1":"Es más de 15 pies y menos de 30 pies.","h2":"En Nevada, usted no puede estacionarse sobre un cruce peatonal ni a menos de 20 pies de uno.","p":"Correcto. Quédese por lo menos a 20 pies de un cruce peatonal."},"ref":{"doc":"NV","page":50}},{"id":"nv-083","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a roundabout has a raised truck apron around the center island. Who should drive on it?","o":["Any car that needs more room","Cars turning left","Motorcycles only","Large trucks and trailers, not cars"],"h1":"It helps very long vehicles make the tight turn.","h2":"In Nevada, the truck apron in a roundabout is for large trucks and trailers that need room to turn; cars should not use it.","p":"Right. The truck apron is for large trucks, not cars."},"es":{"q":"En Nevada, una glorieta tiene una plataforma elevada para camiones alrededor de la isla central. ¿Quién debe pasar por ella?","o":["Cualquier auto que necesite más espacio","Los autos que dan vuelta a la izquierda","Solo las motocicletas","Los camiones grandes y los remolques, no los autos"],"h1":"Ayuda a los vehículos muy largos a dar la vuelta cerrada.","h2":"En Nevada, la plataforma para camiones de una glorieta es para camiones grandes y remolques que necesitan espacio para girar; los autos no deben usarla.","p":"Correcto. La plataforma es para camiones grandes, no para autos."},"ref":{"doc":"NV","page":44}},{"id":"nv-084","scope":"NV","cat":"signals","sign":null,"c":0,"en":{"q":"In Nevada, your turn signals are broken. How do you give a hand signal for a right turn?","o":["Left arm out, elbow bent, hand pointing up","Left arm straight out the window","Left arm pointing down, palm to the rear","Right arm out the right window"],"h1":"The arm bends at about a right angle.","h2":"In Nevada, the hand signal for a right turn is the left arm out with the elbow bent upward at about 90 degrees.","p":"Right. Left arm bent up means a right turn."},"es":{"q":"En Nevada, sus direccionales no funcionan. ¿Cómo hace la señal con la mano para dar vuelta a la derecha?","o":["Brazo izquierdo afuera, codo doblado, mano hacia arriba","Brazo izquierdo recto afuera de la ventana","Brazo izquierdo hacia abajo, palma hacia atrás","Brazo derecho afuera de la ventana derecha"],"h1":"El brazo se dobla en un ángulo de unos 90 grados.","h2":"En Nevada, la señal con la mano para dar vuelta a la derecha es el brazo izquierdo afuera con el codo doblado hacia arriba en unos 90 grados.","p":"Correcto. Brazo izquierdo doblado hacia arriba significa vuelta a la derecha."},"ref":{"doc":"NV","page":45}},{"id":"nv-085","scope":"NV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Nevada, you are waiting to turn left. Which way should your front wheels point until you start the turn?","o":["To the left, ready to turn","Straight ahead","To the right","It does not matter"],"h1":"Do not turn the steering wheel early.","h2":"In Nevada, when turning left, keep your wheels pointed straight ahead until you actually begin the turn.","p":"Right. Keep the wheels straight until you turn."},"es":{"q":"En Nevada, usted espera para dar vuelta a la izquierda. ¿Hacia dónde deben apuntar sus ruedas delanteras hasta que empiece la vuelta?","o":["Hacia la izquierda, listas para girar","Derecho hacia adelante","Hacia la derecha","No importa"],"h1":"No gire el volante antes de tiempo.","h2":"En Nevada, al dar vuelta a la izquierda, mantenga las ruedas apuntando derecho hacia adelante hasta que de verdad empiece la vuelta.","p":"Correcto. Mantenga las ruedas derechas hasta girar."},"ref":{"doc":"NV","page":45}},{"id":"nv-086","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, U-turns are not allowed in business districts, except where turns are allowed at intersections or openings. Which area also counts as a business district?","o":["A quiet farm road","An empty desert highway","An area with churches, apartments or public buildings","A street with only single-family homes"],"h1":"Think of places where many people gather or live close together.","h2":"In Nevada, areas with churches, apartments, multifamily housing and public buildings count as business districts, where you may not make a U-turn except at an intersection or opening where it is allowed.","p":"Right. Churches, apartments and public buildings count as a business district."},"es":{"q":"En Nevada, no se permiten las vueltas en U en zonas comerciales, excepto donde se permite girar en intersecciones o aberturas. ¿Qué zona también cuenta como zona comercial?","o":["Un camino rural tranquilo","Una carretera vacía en el desierto","Una zona con iglesias, apartamentos o edificios públicos","Una calle con solo casas para una familia"],"h1":"Piense en lugares donde se reúne mucha gente o vive muy junta.","h2":"En Nevada, las zonas con iglesias, apartamentos, viviendas multifamiliares y edificios públicos cuentan como zonas comerciales, donde no puede dar vuelta en U excepto en una intersección o abertura donde esté permitido.","p":"Correcto. Iglesias, apartamentos y edificios públicos cuentan como zona comercial."},"ref":{"doc":"NV","page":46}},{"id":"nv-087","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, on a two-lane road, you may not pass within what distance of a street crossing or a railroad crossing?","o":["25 feet","50 feet","500 feet","100 feet"],"h1":"It is about 10 car lengths.","h2":"In Nevada, on a two-lane road you may not pass at or within 100 feet of a street crossing or a railroad crossing.","p":"Right. No passing within 100 feet of a crossing."},"es":{"q":"En Nevada, en un camino de dos carriles, ¿a qué distancia de un cruce de calles o de un cruce de ferrocarril no puede rebasar?","o":["25 pies","50 pies","500 pies","100 pies"],"h1":"Son unos 10 largos de auto.","h2":"En Nevada, en un camino de dos carriles no puede rebasar en un cruce de calles o de ferrocarril ni a menos de 100 pies de él.","p":"Correcto. No rebase a menos de 100 pies de un cruce."},"ref":{"doc":"NV","page":47}},{"id":"nv-088","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, you turn left from a side street into a center turn lane. What is the farthest you may drive in it before you merge into traffic?","o":["50 feet","200 feet","500 feet","A quarter mile"],"h1":"It is much shorter than the distance allowed before a left turn.","h2":"In Nevada, after you turn left into a center turn lane, you may drive no more than 50 feet in it before you merge with traffic.","p":"Right. Merge within 50 feet."},"es":{"q":"En Nevada, usted da vuelta a la izquierda desde una calle lateral hacia un carril central de vuelta. ¿Cuál es la mayor distancia que puede recorrer en él antes de incorporarse al tráfico?","o":["50 pies","200 pies","500 pies","Un cuarto de milla"],"h1":"Es mucho menos que la distancia permitida antes de una vuelta a la izquierda.","h2":"En Nevada, después de dar vuelta a la izquierda hacia un carril central de vuelta, no puede recorrer más de 50 pies en él antes de incorporarse al tráfico.","p":"Correcto. Incorpórese antes de 50 pies."},"ref":{"doc":"NV","page":32}},{"id":"nv-089","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, when you park next to a curb, what is the farthest your wheels may be from the curb?","o":["6 inches","18 inches","3 feet","5 feet"],"h1":"It is a foot and a half.","h2":"In Nevada, the legal parking position is with the front and rear wheels within 18 inches of the curb.","p":"Right. Park within 18 inches of the curb."},"es":{"q":"En Nevada, cuando se estaciona junto a la banqueta (acera), ¿cuál es la mayor distancia a la que pueden estar sus ruedas de la banqueta?","o":["6 pulgadas","18 pulgadas","3 pies","5 pies"],"h1":"Es un pie y medio.","h2":"En Nevada, la posición legal para estacionarse es con las ruedas delanteras y traseras a menos de 18 pulgadas de la banqueta.","p":"Correcto. Estaciónese a menos de 18 pulgadas de la banqueta."},"ref":{"doc":"NV","page":48}},{"id":"nv-090","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, what does a green curb usually mean?","o":["No stopping at any time","A loading zone","You may park for a limited time","Parking for people with disabilities"],"h1":"A sign nearby usually shows how long.","h2":"In Nevada, a green curb means you may park for a limited time, usually shown on a sign.","p":"Right. Green means limited-time parking."},"es":{"q":"En Nevada, ¿qué significa normalmente una banqueta pintada de verde?","o":["No se puede parar nunca","Una zona de carga","Puede estacionarse por un tiempo limitado","Estacionamiento para personas con discapacidad"],"h1":"Normalmente un letrero cercano indica cuánto tiempo.","h2":"En Nevada, una banqueta verde significa que puede estacionarse por un tiempo limitado, que normalmente se indica en un letrero.","p":"Correcto. Verde significa estacionamiento por tiempo limitado."},"ref":{"doc":"NV","page":48}},{"id":"nv-091","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","It does not matter if you set the brake","Away from the curb"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In Nevada, when you park uphill next to a curb, turn your front wheels away from the curb and set the parking brake.","p":"Right. Uphill with a curb: wheels away from the curb."},"es":{"q":"En Nevada, usted se estaciona cuesta arriba junto a la banqueta. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la banqueta","Derecho hacia adelante","No importa si pone el freno","Lejos de la banqueta"],"h1":"Si el auto rueda hacia atrás, la parte de atrás de la llanta delantera debe quedar contra la banqueta.","h2":"En Nevada, cuando se estaciona cuesta arriba junto a la banqueta, gire las ruedas delanteras lejos de la banqueta y ponga el freno de estacionamiento.","p":"Correcto. Cuesta arriba con banqueta: ruedas lejos de la banqueta."},"ref":{"doc":"NV","page":49}},{"id":"nv-092","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, on a street with parallel parking, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 30 feet"],"h1":"Angle parking needs more room: 20 feet.","h2":"In Nevada, where parallel parking is allowed, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet from a hydrant."},"es":{"q":"En Nevada, en una calle con estacionamiento en paralelo, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 10 pies","No a menos de 30 pies"],"h1":"El estacionamiento en ángulo necesita más espacio: 20 pies.","h2":"En Nevada, donde se permite estacionarse en paralelo, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies de un hidrante."},"ref":{"doc":"NV","page":50}},{"id":"nv-093","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, how many motorcycles may ride side by side in one traffic lane, if the riders agree?","o":["One only","No more than two","No more than three","As many as fit"],"h1":"Without the riders' consent, they ride in a staggered line.","h2":"In Nevada, motorcycles and mopeds may ride no more than two abreast in a single lane, and only if the riders agree.","p":"Right. No more than two side by side."},"es":{"q":"En Nevada, ¿cuántas motocicletas pueden ir lado a lado en un mismo carril, si los conductores están de acuerdo?","o":["Solo una","No más de dos","No más de tres","Todas las que quepan"],"h1":"Sin el acuerdo de los conductores, van en una fila escalonada.","h2":"En Nevada, las motocicletas y los ciclomotores pueden ir no más de dos lado a lado en un mismo carril, y solo si los conductores están de acuerdo.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"NV","page":63}},{"id":"nv-094","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, the car in the lane next to you slows down and stops. What does the law say about passing it?","o":["Pass quickly before people start to cross","Honk, then pass","Do not pass until you slow down enough to see why it stopped","Pass on the shoulder"],"h1":"Someone may be crossing in front of that car.","h2":"In Nevada, it is illegal to pass a vehicle that is slowing down or stopped until you slow down enough to find out why it slowed or stopped.","p":"Right. Slow down and find out why before you pass."},"es":{"q":"En Nevada, el auto del carril de al lado baja la velocidad y se detiene. ¿Qué dice la ley sobre rebasarlo?","o":["Rebasar rápido antes de que la gente empiece a cruzar","Tocar la bocina y luego rebasar","No rebasar hasta bajar la velocidad lo suficiente para ver por qué se detuvo","Rebasar por el acotamiento"],"h1":"Puede haber alguien cruzando delante de ese auto.","h2":"En Nevada, es ilegal rebasar a un vehículo que baja la velocidad o está detenido hasta que usted baje la velocidad lo suficiente para saber por qué lo hizo.","p":"Correcto. Baje la velocidad y vea por qué antes de rebasar."},"ref":{"doc":"NV","page":66}},{"id":"nv-095","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, signs show that a highway shoulder may be used by emergency vehicles. May you stop your car there?","o":["Yes, any time you want a break","Yes, to make a phone call","Yes, if traffic is slow","No, drivers of other vehicles may not stop on that shoulder"],"h1":"The shoulder is kept clear for vehicles such as ambulances and tow cars.","h2":"In Nevada, drivers of non-emergency vehicles may not stop on a shoulder that signs mark for emergency vehicle use.","p":"Right. Keep that shoulder clear."},"es":{"q":"En Nevada, unos letreros indican que el acotamiento de una carretera puede ser usado por vehículos de emergencia. ¿Puede usted detener su auto ahí?","o":["Sí, cuando quiera descansar","Sí, para hacer una llamada","Sí, si el tráfico va lento","No, los conductores de otros vehículos no pueden detenerse en ese acotamiento"],"h1":"El acotamiento se mantiene libre para vehículos como ambulancias y grúas.","h2":"En Nevada, los conductores de vehículos que no son de emergencia no pueden detenerse en un acotamiento que los letreros marcan para uso de vehículos de emergencia.","p":"Correcto. Deje libre ese acotamiento."},"ref":{"doc":"NV","page":61}},{"id":"nv-096","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what is the minimum liability insurance for injury or death of two or more people in one crash?","o":["$50,000","$25,000","$40,000","$100,000"],"h1":"It is twice the amount for one person.","h2":"In Nevada, the minimum liability insurance is $50,000 for injury or death of two or more people in one crash.","p":"Right. The minimum is $50,000 for two or more people."},"es":{"q":"En Nevada, ¿cuál es el seguro de responsabilidad mínimo por lesiones o muerte de dos o más personas en un choque?","o":["$50,000","$25,000","$40,000","$100,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"En Nevada, el seguro de responsabilidad mínimo es de $50,000 por lesiones o muerte de dos o más personas en un choque.","p":"Correcto. El mínimo es $50,000 para dos o más personas."},"ref":{"doc":"NV","page":75}},{"id":"nv-097","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how many demerit points does a conviction for following too closely add?","o":["1 point","4 points","6 points","8 points"],"h1":"It is the same as running a stop sign.","h2":"In Nevada, following too closely adds 4 demerit points to your driving record.","p":"Right. Following too closely is 4 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito agrega una condena por seguir a otro vehículo demasiado de cerca?","o":["1 punto","4 puntos","6 puntos","8 puntos"],"h1":"Es lo mismo que no respetar una señal de alto.","h2":"En Nevada, seguir demasiado de cerca agrega 4 puntos de demérito a su historial de manejo.","p":"Correcto. Seguir demasiado de cerca son 4 puntos."},"ref":{"doc":"NV","page":78}},{"id":"nv-098","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you are convicted of driving 15 mph over the speed limit. How many demerit points are added?","o":["1 point","5 points","2 points","4 points"],"h1":"It is more than for going 10 mph or less over the limit.","h2":"In Nevada, speeding 11 to 20 mph over the posted limit adds 2 demerit points.","p":"Right. 11 to 20 mph over is 2 points."},"es":{"q":"En Nevada, lo condenan por manejar 15 mph por encima del límite de velocidad. ¿Cuántos puntos de demérito le agregan?","o":["1 punto","5 puntos","2 puntos","4 puntos"],"h1":"Es más que por pasarse del límite por 10 mph o menos.","h2":"En Nevada, pasarse del límite de velocidad por 11 a 20 mph agrega 2 puntos de demérito.","p":"Correcto. De 11 a 20 mph por encima son 2 puntos."},"ref":{"doc":"NV","page":78}},{"id":"nv-099","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, what is the fine for a first DUI offense?","o":["$100 to $250","$2,000 to $5,000","$750 to $1,000","$400 to $1,000"],"h1":"The fine for a third offense is $2,000 to $5,000.","h2":"In Nevada, a first DUI offense carries a fine of $400 to $1,000, plus other penalties such as license revocation and DUI school.","p":"Right. A first DUI fine is $400 to $1,000."},"es":{"q":"En Nevada, ¿cuál es la multa por un primer delito de DUI (manejar bajo la influencia)?","o":["$100 a $250","$2,000 a $5,000","$750 a $1,000","$400 a $1,000"],"h1":"La multa por un tercer delito es de $2,000 a $5,000.","h2":"En Nevada, un primer delito de DUI tiene una multa de $400 a $1,000, además de otras penas como la revocación de la licencia y la escuela de DUI.","p":"Correcto. La multa por un primer DUI es de $400 a $1,000."},"ref":{"doc":"NV","page":80}},{"id":"nv-100","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, where does the open container law allow an opened alcoholic drink while the vehicle is moving?","o":["In the passenger area of a taxi or limousine","In the front passenger's hand","In the back seat of a family car","Anywhere, if the driver is sober"],"h1":"It is a vehicle where passengers pay to ride.","h2":"In Nevada, the open container law bans opened alcoholic drinks in the driver and passenger areas, but it does not apply to the passenger areas of buses, limousines or taxis, or the living quarters of motor homes.","p":"Right. The law does not apply to taxi or limousine passenger areas."},"es":{"q":"En Nevada, ¿dónde permite la ley de envases abiertos una bebida alcohólica abierta mientras el vehículo está en marcha?","o":["En el área de pasajeros de un taxi o una limusina","En la mano del pasajero de adelante","En el asiento de atrás de un auto familiar","En cualquier lugar, si el conductor está sobrio"],"h1":"Es un vehículo donde los pasajeros pagan por viajar.","h2":"En Nevada, la ley de envases abiertos prohíbe bebidas alcohólicas abiertas en las áreas del conductor y de los pasajeros, pero no se aplica a las áreas de pasajeros de autobuses, limusinas o taxis, ni a la zona de vivienda de las casas rodantes.","p":"Correcto. La ley no se aplica al área de pasajeros de un taxi o una limusina."},"ref":{"doc":"NV","page":81}},{"id":"nv-101","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you cancel your car insurance and do not get new insurance. What must you do?","o":["Nothing until the registration expires","Cancel the registration and turn in the license plates the same day","Tell the DMV within 30 days","Drive only in your home county"],"h1":"A registered vehicle must be insured at all times.","h2":"In Nevada, if you cancel your insurance and do not get new insurance, you must cancel your vehicle registration and turn in your license plates on the same day.","p":"Right. Cancel the registration and return the plates that day."},"es":{"q":"En Nevada, usted cancela el seguro de su auto y no consigue otro. ¿Qué debe hacer?","o":["Nada hasta que venza el registro","Cancelar el registro y entregar las placas el mismo día","Avisar al DMV dentro de 30 días","Manejar solo en su condado"],"h1":"Un vehículo registrado debe tener seguro todo el tiempo.","h2":"En Nevada, si usted cancela su seguro y no consigue otro, debe cancelar el registro del vehículo y entregar las placas el mismo día.","p":"Correcto. Cancele el registro y entregue las placas ese mismo día."},"ref":{"doc":"NV","page":83}},{"id":"nv-102","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, apart from special restricted licenses, what is the youngest age to get a driver license?","o":["16 years old","15 and a half years old","17 years old","18 years old"],"h1":"It is older than the age for an instruction permit.","h2":"In Nevada, you must be at least 16 years old to get a driver license.","p":"Right. You must be at least 16 for a driver license."},"es":{"q":"En Nevada, aparte de las licencias restringidas especiales, ¿cuál es la edad mínima para obtener una licencia de manejo?","o":["16 años","15 años y medio","17 años","18 años"],"h1":"Es más que la edad para el permiso de aprendizaje.","h2":"En Nevada, usted debe tener por lo menos 16 años para obtener una licencia de manejo.","p":"Correcto. Debe tener por lo menos 16 años para la licencia."},"ref":{"doc":"NV","page":6}},{"id":"nv-103","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, a parent co-signs the license application of a driver under 18. What does that mean for the parent?","o":["The parent must ride along every time the teen drives","The parent shares liability for damage the teen causes while driving","The parent must pay for driver education","Nothing after the license is issued"],"h1":"Think about who pays if the teen causes a crash.","h2":"In Nevada, the person who co-signs a minor's license application shares liability for damage the minor causes by careless or willful driving.","p":"Right. The co-signer shares liability for the teen's driving."},"es":{"q":"En Nevada, un padre firma como cofirmante la solicitud de licencia de un conductor menor de 18 años. ¿Qué significa eso para el padre?","o":["El padre debe acompañarlo cada vez que maneje","El padre comparte la responsabilidad por los daños que cause el joven al manejar","El padre debe pagar la educación vial","Nada, una vez que se emite la licencia"],"h1":"Piense en quién paga si el joven causa un choque.","h2":"En Nevada, la persona que firma como cofirmante la solicitud de licencia de un menor comparte la responsabilidad por los daños que el menor cause al manejar con descuido o a propósito.","p":"Correcto. El cofirmante comparte la responsabilidad por el manejo del joven."},"ref":{"doc":"NV","page":6}},{"id":"nv-104","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you get a Nevada license and you still have a license from another state. What happens to the old license?","o":["You may keep using both","You must mail it back to the other state yourself","You must surrender it, and it is voided","It stays valid for one more year"],"h1":"A Nevada resident may hold only one license or ID card.","h2":"In Nevada, a resident may hold only one license or ID card, so you must surrender your out-of-state license and it is voided.","p":"Right. You surrender the old license and it is voided."},"es":{"q":"En Nevada, usted obtiene una licencia de Nevada y todavía tiene una licencia de otro estado. ¿Qué pasa con la licencia anterior?","o":["Puede seguir usando las dos","Debe enviarla usted mismo por correo al otro estado","Debe entregarla y queda anulada","Sigue siendo válida por un año más"],"h1":"Un residente de Nevada solo puede tener una licencia o tarjeta de identificación.","h2":"En Nevada, un residente solo puede tener una licencia o tarjeta de identificación, así que usted debe entregar su licencia de otro estado y esta queda anulada.","p":"Correcto. Usted entrega la licencia anterior y queda anulada."},"ref":{"doc":"NV","page":7}},{"id":"nv-105","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, a new resident with a valid license from another state may have the knowledge and drive tests waived. What is one of the rules about their driving record?","o":["No more than 5 moving violations in the past 2 years","No parking tickets in the past year","At least 10 years of driving with no crashes","Fewer than 3 moving violations in the past 4 years"],"h1":"The rule counts moving violations over a few years.","h2":"In Nevada, to have the other tests waived, a new resident must have had fewer than 3 moving violations in the past 4 years, along with the other rules.","p":"Right. You need fewer than 3 moving violations in 4 years."},"es":{"q":"En Nevada, a un nuevo residente con una licencia válida de otro estado le pueden dispensar el examen de conocimientos y el de manejo. ¿Cuál es una de las reglas sobre su historial de manejo?","o":["No más de 5 infracciones en movimiento en los últimos 2 años","Ninguna multa de estacionamiento en el último año","Por lo menos 10 años manejando sin choques","Menos de 3 infracciones de tránsito en movimiento en los últimos 4 años"],"h1":"La regla cuenta las infracciones en movimiento durante algunos años.","h2":"En Nevada, para que le dispensen los otros exámenes, un nuevo residente debe tener menos de 3 infracciones en movimiento en los últimos 4 años, además de cumplir las otras reglas.","p":"Correcto. Necesita menos de 3 infracciones en movimiento en 4 años."},"ref":{"doc":"NV","page":7}},{"id":"nv-106","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, which of these is NOT accepted as proof of your name and date of birth?","o":["A birth certificate issued by a hospital","A certified birth certificate issued by a state","A valid U.S. passport","A Certificate of Naturalization"],"h1":"The DMV wants a birth certificate from a government office.","h2":"In Nevada, a hospital-issued birth certificate is not accepted as proof of name and date of birth; a state-issued certificate is.","p":"Right. A hospital birth certificate is not accepted."},"es":{"q":"En Nevada, ¿cuál de estos NO se acepta como prueba de su nombre y fecha de nacimiento?","o":["Un certificado de nacimiento emitido por un hospital","Un certificado de nacimiento certificado emitido por un estado","Un pasaporte de EE. UU. válido","Un Certificado de Naturalización"],"h1":"El DMV quiere un certificado de nacimiento de una oficina del gobierno.","h2":"En Nevada, un certificado de nacimiento emitido por un hospital no se acepta como prueba de nombre y fecha de nacimiento; uno emitido por el estado sí.","p":"Correcto. El certificado de nacimiento del hospital no se acepta."},"ref":{"doc":"NV","page":8}},{"id":"nv-107","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, how many documents showing your Nevada home address must you bring to get a first license or ID card?","o":["One","Two","Three","None, if you have a Social Security card"],"h1":"It is more than one.","h2":"In Nevada, you must bring two documents that show your Nevada home address, such as a utility bill or a lease.","p":"Right. You need two proofs of Nevada residency."},"es":{"q":"En Nevada, ¿cuántos documentos que muestren su domicilio en Nevada debe llevar para obtener su primera licencia o tarjeta de identificación?","o":["Uno","Dos","Tres","Ninguno, si tiene tarjeta del Seguro Social"],"h1":"Es más de uno.","h2":"En Nevada, usted debe llevar dos documentos que muestren su domicilio en Nevada, como una factura de servicios o un contrato de alquiler.","p":"Correcto. Necesita dos pruebas de residencia en Nevada."},"ref":{"doc":"NV","page":11}},{"id":"nv-108","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, a teen gives the DMV a DMV-301 school attendance form. How recent must the school's signature be?","o":["Signed within the past year","Signed within the past 6 months","Any date is fine","Signed within the past 60 days"],"h1":"It is about two months.","h2":"In Nevada, the DMV-301 attendance form must be signed and dated within the previous 60 days.","p":"Right. The DMV-301 must be signed within 60 days."},"es":{"q":"En Nevada, un joven entrega al DMV el formulario de asistencia escolar DMV-301. ¿Qué tan reciente debe ser la firma de la escuela?","o":["Firmado dentro del último año","Firmado dentro de los últimos 6 meses","Cualquier fecha sirve","Firmado dentro de los últimos 60 días"],"h1":"Es más o menos dos meses.","h2":"En Nevada, el formulario de asistencia DMV-301 debe estar firmado y fechado dentro de los 60 días anteriores.","p":"Correcto. El DMV-301 debe estar firmado dentro de 60 días."},"ref":{"doc":"NV","page":13}},{"id":"nv-109","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, a teen lives more than 30 miles from a driver education school and cannot take a class online. How much supervised driving must they do instead?","o":["100 hours, with 10 at night","50 hours, with 10 at night","75 hours, with 15 at night","30 hours, with 5 at night"],"h1":"It is twice the usual number of hours.","h2":"In Nevada, a teen with no driver education school within 30 miles and no internet access must complete 100 hours of supervised driving, 10 of them at night.","p":"Right. Without driver education, it is 100 hours, 10 at night."},"es":{"q":"En Nevada, un joven vive a más de 30 millas de una escuela de manejo y no puede tomar la clase por internet. ¿Cuánta práctica supervisada debe hacer en su lugar?","o":["100 horas, 10 de noche","50 horas, 10 de noche","75 horas, 15 de noche","30 horas, 5 de noche"],"h1":"Es el doble de las horas normales.","h2":"En Nevada, un joven sin escuela de manejo a menos de 30 millas y sin acceso a internet debe completar 100 horas de manejo supervisado, 10 de ellas de noche.","p":"Correcto. Sin educación vial, son 100 horas, 10 de noche."},"ref":{"doc":"NV","page":14}},{"id":"nv-110","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, before a minor gets a driver license, for how long must they have no at-fault crashes, no moving violation convictions and no alcohol or drug convictions?","o":["One month","Six months","Three months","One year"],"h1":"It is half a year.","h2":"In Nevada, a minor must stay free of at-fault crashes, moving violation convictions and alcohol or drug convictions for six months before getting a driver license.","p":"Right. Six months with a clean record."},"es":{"q":"En Nevada, antes de que un menor obtenga su licencia, ¿por cuánto tiempo debe estar sin choques con culpa, sin condenas por infracciones en movimiento y sin condenas por alcohol o drogas?","o":["Un mes","Seis meses","Tres meses","Un año"],"h1":"Es medio año.","h2":"En Nevada, un menor debe estar libre de choques con culpa, condenas por infracciones en movimiento y condenas por alcohol o drogas durante seis meses antes de obtener la licencia.","p":"Correcto. Seis meses con un historial limpio."},"ref":{"doc":"NV","page":14}},{"id":"nv-111","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you practice with a motorcycle instruction permit. Where must your supervising rider be?","o":["In a car driving behind you","On the back seat of your motorcycle","On a motorcycle, watching you","Anywhere, as long as you can call them"],"h1":"The supervisor may not be in a car or truck.","h2":"In Nevada, the licensed rider who supervises a motorcycle permit holder must be on a motorcycle, in direct sight of the learner, not in a car or truck.","p":"Right. The supervisor rides a motorcycle too."},"es":{"q":"En Nevada, usted practica con un permiso de aprendizaje de motocicleta. ¿Dónde debe estar la persona que lo supervisa?","o":["En un auto detrás de usted","En el asiento de atrás de su motocicleta","En una motocicleta, observándolo","En cualquier lugar, si usted puede llamarla"],"h1":"El supervisor no puede ir en un auto ni en una camioneta.","h2":"En Nevada, el motociclista con licencia que supervisa a quien tiene permiso de motocicleta debe ir en una motocicleta, a la vista del aprendiz, y no en un auto ni en una camioneta.","p":"Correcto. El supervisor también va en motocicleta."},"ref":{"doc":"NV","page":15}},{"id":"nv-112","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, with a Class C license, how long may a combination of vehicles (such as a truck and trailer) be?","o":["No more than 40 feet","No more than 55 feet","No more than 100 feet","No more than 70 feet"],"h1":"It is between 60 and 80 feet.","h2":"In Nevada, a combination of vehicles driven with a Class C license may not be longer than 70 feet.","p":"Right. A Class C combination may be up to 70 feet long."},"es":{"q":"En Nevada, con una licencia Clase C, ¿qué largo puede tener una combinación de vehículos (como una camioneta con remolque)?","o":["No más de 40 pies","No más de 55 pies","No más de 100 pies","No más de 70 pies"],"h1":"Está entre 60 y 80 pies.","h2":"En Nevada, una combinación de vehículos que se maneja con licencia Clase C no puede medir más de 70 pies.","p":"Correcto. Una combinación Clase C puede medir hasta 70 pies."},"ref":{"doc":"NV","page":16}},{"id":"nv-113","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, your license shows Restriction G. What does it mean?","o":["You may drive only in daylight","You must have extra rearview mirrors","You need a yearly vision exam","You must wear glasses"],"h1":"Think about the time of day.","h2":"In Nevada, Restriction G on a license means daylight driving only.","p":"Right. Restriction G means daylight driving only."},"es":{"q":"En Nevada, su licencia tiene la Restricción G. ¿Qué significa?","o":["Solo puede manejar de día","Debe tener espejos retrovisores adicionales","Necesita un examen de la vista cada año","Debe usar lentes"],"h1":"Piense en la hora del día.","h2":"En Nevada, la Restricción G en una licencia significa que solo puede manejar con luz de día.","p":"Correcto. La Restricción G significa manejar solo de día."},"ref":{"doc":"NV","page":16}},{"id":"nv-114","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you have a Class C license and want to tow a trailer weighing more than 10,000 pounds (the whole combination under 26,000 pounds and 70 feet). What do you need?","o":["A motorcycle endorsement","A J endorsement","Nothing extra","A Class M license"],"h1":"An endorsement is a special added permission on your license.","h2":"In Nevada, a Class C driver needs a J endorsement to tow a vehicle over 10,000 pounds, as long as the combination stays within 26,000 pounds and 70 feet.","p":"Right. Towing over 10,000 pounds with Class C needs a J endorsement."},"es":{"q":"En Nevada, usted tiene licencia Clase C y quiere remolcar un remolque de más de 10,000 libras (la combinación completa pesa menos de 26,000 libras y mide menos de 70 pies). ¿Qué necesita?","o":["Un endoso de motocicleta","Un endoso J","Nada más","Una licencia Clase M"],"h1":"Un endoso es un permiso especial que se agrega a su licencia.","h2":"En Nevada, un conductor Clase C necesita un endoso J para remolcar un vehículo de más de 10,000 libras, siempre que la combinación no pase de 26,000 libras ni de 70 pies.","p":"Correcto. Para remolcar más de 10,000 libras con Clase C se necesita un endoso J."},"ref":{"doc":"NV","page":17}},{"id":"nv-115","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, you get a motorcycle instruction permit after your 17th birthday. When does it expire?","o":["One year after it is issued","Six months after it is issued","On your 18th birthday","On your 21st birthday"],"h1":"It ends when you become an adult.","h2":"In Nevada, a motorcycle instruction permit issued after you turn 17 expires on your 18th birthday.","p":"Right. It expires on your 18th birthday."},"es":{"q":"En Nevada, usted obtiene un permiso de aprendizaje de motocicleta después de cumplir 17 años. ¿Cuándo vence?","o":["Un año después de emitido","Seis meses después de emitido","El día que cumple 18 años","El día que cumple 21 años"],"h1":"Termina cuando usted llega a la mayoría de edad.","h2":"En Nevada, un permiso de aprendizaje de motocicleta emitido después de cumplir 17 años vence el día que usted cumple 18.","p":"Correcto. Vence el día que cumple 18 años."},"ref":{"doc":"NV","page":18}},{"id":"nv-116","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, your license is suspended. When might you qualify for a restricted license?","o":["Right after the suspension starts","Only after the whole suspension ends","Never","After you serve half of the suspension"],"h1":"It is partway through the suspension.","h2":"In Nevada, a restricted license may be issued, in special cases, to a person who has served half of the required suspension or revocation period.","p":"Right. Half of the suspension must be served first."},"es":{"q":"En Nevada, su licencia está suspendida. ¿Cuándo podría usted calificar para una licencia restringida?","o":["Justo cuando empieza la suspensión","Solo cuando termine toda la suspensión","Nunca","Después de cumplir la mitad de la suspensión"],"h1":"Es a mitad de camino de la suspensión.","h2":"En Nevada, en casos especiales se puede dar una licencia restringida a una persona que ya cumplió la mitad del período de suspensión o revocación.","p":"Correcto. Primero debe cumplir la mitad de la suspensión."},"ref":{"doc":"NV","page":19}},{"id":"nv-117","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, you hold a driver license and then get a Nevada identification (ID) card. What happens?","o":["Your driving privilege is surrendered","You keep both and may still drive","Your license is extended by four years","Nothing changes"],"h1":"A Nevada resident may hold only one of the two cards.","h2":"In Nevada, getting an identification card automatically surrenders your driving privilege.","p":"Right. Getting an ID card surrenders your driving privilege."},"es":{"q":"En Nevada, usted tiene licencia de manejo y luego obtiene una tarjeta de identificación (ID) de Nevada. ¿Qué pasa?","o":["Usted entrega su privilegio de manejar","Conserva las dos y puede seguir manejando","Su licencia se extiende cuatro años","No cambia nada"],"h1":"Un residente de Nevada solo puede tener una de las dos tarjetas.","h2":"En Nevada, obtener una tarjeta de identificación entrega automáticamente su privilegio de manejar.","p":"Correcto. Obtener una tarjeta ID entrega su privilegio de manejar."},"ref":{"doc":"NV","page":20}},{"id":"nv-118","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, you check your tire tread with a penny, putting Lincoln's head into a groove. What shows the tire still has a safe amount of tread?","o":["You can see all of Lincoln's head","Part of Lincoln's head is covered by the tread","The penny falls out of the groove","The penny touches the rim"],"h1":"Deep tread hides part of the coin.","h2":"In Nevada, if the tread covers part of Lincoln's head in the penny test, the tire has a safe amount of tread.","p":"Right. If the tread covers part of Lincoln's head, the tread is safe."},"es":{"q":"En Nevada, usted revisa el dibujo de la llanta con un centavo, metiendo la cabeza de Lincoln en una ranura. ¿Qué muestra que la llanta todavía tiene suficiente dibujo?","o":["Se ve toda la cabeza de Lincoln","El dibujo cubre parte de la cabeza de Lincoln","El centavo se cae de la ranura","El centavo toca el rin"],"h1":"Un dibujo profundo esconde parte de la moneda.","h2":"En Nevada, si en la prueba del centavo el dibujo cubre parte de la cabeza de Lincoln, la llanta tiene suficiente dibujo.","p":"Correcto. Si el dibujo cubre parte de la cabeza de Lincoln, está bien."},"ref":{"doc":"NV","page":27}},{"id":"nv-119","scope":"NV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Nevada, what does the law say about the right-of-way?","o":["It always gives the right-of-way to the bigger vehicle","It gives the right-of-way to whoever honks first","It does not give anyone the right-of-way; it only says who must yield","It gives drivers the right-of-way over people walking"],"h1":"Even when you may go first, you must still try to avoid a crash.","h2":"In Nevada, the law does not give anyone the right-of-way; it only says who must yield, and you must do everything you can to avoid a crash.","p":"Right. The law only says who must yield."},"es":{"q":"En Nevada, ¿qué dice la ley sobre el derecho de paso?","o":["Siempre se lo da al vehículo más grande","Se lo da a quien toque la bocina primero","No le da a nadie el derecho de paso; solo dice quién debe ceder","Les da a los conductores el derecho de paso sobre los peatones"],"h1":"Aunque usted pueda pasar primero, debe tratar de evitar un choque.","h2":"En Nevada, la ley no le da a nadie el derecho de paso; solo dice quién debe ceder, y usted debe hacer todo lo posible para evitar un choque.","p":"Correcto. La ley solo dice quién debe ceder el paso."},"ref":{"doc":"NV","page":34}},{"id":"nv-120","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a funeral procession with headlights on is going through an intersection. What should you do?","o":["Drive between the cars when there is a gap","Honk so they know you are waiting","Follow the last car through the light","Yield and let the vehicles pass as a group"],"h1":"The cars in the procession stay together.","h2":"In Nevada, you should yield to a funeral procession and let the vehicles with headlights on pass as a group.","p":"Right. Let the funeral procession pass as a group."},"es":{"q":"En Nevada, un cortejo fúnebre con las luces encendidas pasa por una intersección. ¿Qué debe hacer usted?","o":["Pasar entre los autos cuando haya un espacio","Tocar la bocina para que sepan que espera","Seguir al último auto a través del semáforo","Ceder el paso y dejar pasar los vehículos en grupo"],"h1":"Los autos del cortejo van juntos.","h2":"En Nevada, usted debe ceder el paso a un cortejo fúnebre y dejar pasar en grupo a los vehículos con las luces encendidas.","p":"Correcto. Deje pasar el cortejo fúnebre en grupo."},"ref":{"doc":"NV","page":34}},{"id":"nv-121","scope":"NV","cat":"signals","sign":null,"c":0,"en":{"q":"In Nevada, which vehicles must stop at a railroad crossing even when there is no stop signal and no train is coming?","o":["Passenger buses and trucks carrying flammable or dangerous materials","All pickup trucks","Motorcycles","Cars pulling any trailer"],"h1":"Think of vehicles that carry many people or risky loads.","h2":"In Nevada, passenger buses and trucks carrying flammable or dangerous materials must stop at railroad crossings even when no train is coming.","p":"Right. Buses and hazardous-load trucks always stop."},"es":{"q":"En Nevada, ¿qué vehículos deben detenerse en un cruce de ferrocarril aunque no haya señal de alto y no venga ningún tren?","o":["Los autobuses de pasajeros y los camiones con materiales inflamables o peligrosos","Todas las camionetas pickup","Las motocicletas","Los autos que jalan cualquier remolque"],"h1":"Piense en vehículos que llevan a muchas personas o cargas peligrosas.","h2":"En Nevada, los autobuses de pasajeros y los camiones con materiales inflamables o peligrosos deben detenerse en los cruces de ferrocarril aunque no venga ningún tren.","p":"Correcto. Los autobuses y los camiones con carga peligrosa siempre se detienen."},"ref":{"doc":"NV","page":33}},{"id":"nv-122","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, what should you avoid doing while you drive across railroad tracks?","o":["Looking both ways","Shifting gears","Keeping both hands on the wheel","Driving at a steady speed"],"h1":"Your car could stall on the tracks.","h2":"In Nevada, you should not shift gears while crossing railroad tracks.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"En Nevada, ¿qué debe evitar hacer mientras cruza las vías del tren?","o":["Mirar a ambos lados","Cambiar de velocidad (marcha)","Mantener las dos manos en el volante","Manejar a una velocidad constante"],"h1":"Su auto se podría apagar sobre las vías.","h2":"En Nevada, usted no debe cambiar de velocidad (marcha) mientras cruza las vías del tren.","p":"Correcto. No cambie de marcha sobre las vías."},"ref":{"doc":"NV","page":33}},{"id":"nv-123","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, a school zone uses flashing yellow lights, and the lights are off while students are in class. What speed limit applies then?","o":["15 mph","25 mph","The limit posted for non-school hours","No limit at all"],"h1":"The lower school limit is in effect only when the lights say so.","h2":"In Nevada, when school zone flashing lights are turned off during class hours, the speed limit goes back to the one posted for non-school hours.","p":"Right. With the lights off, the regular posted limit applies."},"es":{"q":"En Nevada, una zona escolar usa luces amarillas intermitentes, y las luces están apagadas mientras los alumnos están en clase. ¿Qué límite de velocidad se aplica entonces?","o":["15 mph","25 mph","El límite indicado para las horas sin clases","Ningún límite"],"h1":"El límite escolar más bajo solo rige cuando las luces lo indican.","h2":"En Nevada, cuando las luces intermitentes de la zona escolar se apagan durante las clases, el límite de velocidad vuelve al indicado para las horas sin clases.","p":"Correcto. Con las luces apagadas, rige el límite normal indicado."},"ref":{"doc":"NV","page":33}},{"id":"nv-124","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, a freeway on-ramp has a ramp meter and a carpool (HOV) bypass lane marked with a diamond. You have two people in your car. What may you do?","o":["Use the bypass lane but stop at its red light","Use only the metered lane","Drive on the shoulder past the meter","Use the bypass lane without stopping"],"h1":"The HOV bypass lane is not metered.","h2":"In Nevada, a carpool of two or more people may use the HOV ramp meter bypass lane without stopping.","p":"Right. Carpools may use the bypass lane without stopping."},"es":{"q":"En Nevada, una rampa de entrada a la autopista tiene un semáforo de rampa y un carril de paso para vehículos compartidos (HOV) marcado con un rombo. Usted lleva dos personas en su auto. ¿Qué puede hacer?","o":["Usar el carril de paso pero detenerse en su luz roja","Usar solo el carril con semáforo","Pasar el semáforo por el acotamiento","Usar el carril de paso sin detenerse"],"h1":"El carril de paso HOV no tiene semáforo.","h2":"En Nevada, un vehículo compartido con dos o más personas puede usar el carril de paso HOV del semáforo de rampa sin detenerse.","p":"Correcto. Los vehículos compartidos usan el carril de paso sin detenerse."},"ref":{"doc":"NV","page":37}},{"id":"nv-125","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, a carpool (HOV) lane is separated from the other lanes by a double solid white line. Where may you enter or leave the carpool lane?","o":["Only where the line is broken (dashed) white","Anywhere, if you signal","Across the double white line when traffic is light","Only at freeway exits"],"h1":"A double solid white line means do not cross.","h2":"In Nevada, you may not cross a double solid white line to enter or leave a carpool lane; you enter or exit where the line is broken white.","p":"Right. Enter or exit the carpool lane only at the broken white line."},"es":{"q":"En Nevada, un carril para vehículos compartidos (HOV) está separado de los otros carriles por una doble línea blanca continua. ¿Dónde puede entrar o salir del carril?","o":["Solo donde la línea blanca es discontinua","En cualquier lugar, si pone la direccional","Cruzando la doble línea blanca cuando hay poco tráfico","Solo en las salidas de la autopista"],"h1":"Una doble línea blanca continua significa no cruzar.","h2":"En Nevada, usted no puede cruzar una doble línea blanca continua para entrar o salir de un carril HOV; entra o sale donde la línea blanca es discontinua.","p":"Correcto. Entre o salga del carril HOV solo en la línea blanca discontinua."},"ref":{"doc":"NV","page":39}},{"id":"nv-126","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, the ABS light on your dashboard stays on long after you start the car. What does it mean?","o":["All your brakes have failed","The anti-lock brakes are not working, but your regular brakes still work","The parking brake is on","The car needs gas"],"h1":"There are two brake systems to think about.","h2":"In Nevada, if the ABS light stays on long after the car starts, the anti-lock system is not working, but the regular brakes still work.","p":"Right. ABS is off, but normal brakes still work."},"es":{"q":"En Nevada, la luz ABS del tablero sigue encendida mucho tiempo después de arrancar el auto. ¿Qué significa?","o":["Todos los frenos fallaron","Los frenos antibloqueo no funcionan, pero los frenos normales sí","El freno de mano está puesto","El auto necesita gasolina"],"h1":"Hay dos sistemas de frenos en qué pensar.","h2":"En Nevada, si la luz ABS sigue encendida mucho después de arrancar, el sistema antibloqueo no funciona, pero los frenos normales sí funcionan.","p":"Correcto. El ABS no funciona, pero los frenos normales sí."},"ref":{"doc":"NV","page":40}},{"id":"nv-127","scope":"NV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Nevada, you are driving 40 mph or slower. What is the minimum following distance behind the vehicle ahead?","o":["One second","Half a second","Ten seconds","Two seconds"],"h1":"Count one thousand one, one thousand ...","h2":"In Nevada, at 40 mph or less, you should stay at least two seconds behind the vehicle ahead; this is the minimum.","p":"Right. At least two seconds is the minimum."},"es":{"q":"En Nevada, usted maneja a 40 mph o menos. ¿Cuál es la distancia mínima que debe dejar detrás del vehículo de adelante?","o":["Un segundo","Medio segundo","Diez segundos","Dos segundos"],"h1":"Cuente mil uno, mil ...","h2":"En Nevada, a 40 mph o menos, usted debe ir por lo menos dos segundos detrás del vehículo de adelante; ese es el mínimo.","p":"Correcto. Dos segundos es el mínimo."},"ref":{"doc":"NV","page":42}},{"id":"nv-128","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, when may you use a handheld phone while driving?","o":["To report an emergency when stopping would be unsafe","To read a text at a red light","To check a map while moving slowly","To make a short call under one minute"],"h1":"There is one exception, for safety.","h2":"In Nevada, you may use a handheld phone while driving to report an emergency if stopping the vehicle would be unwise, impractical or dangerous.","p":"Right. Only to report an emergency when stopping is unsafe."},"es":{"q":"En Nevada, ¿cuándo puede usar un teléfono en la mano mientras maneja?","o":["Para reportar una emergencia cuando detenerse no sería seguro","Para leer un mensaje en un semáforo en rojo","Para ver un mapa mientras avanza despacio","Para hacer una llamada corta de menos de un minuto"],"h1":"Hay una excepción, por seguridad.","h2":"En Nevada, usted puede usar un teléfono en la mano mientras maneja para reportar una emergencia si detener el vehículo sería imprudente, poco práctico o peligroso.","p":"Correcto. Solo para reportar una emergencia cuando detenerse no es seguro."},"ref":{"doc":"NV","page":43}},{"id":"nv-129","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, in a roundabout with two lanes, what may you do from the right lane?","o":["Turn left or make a U-turn","Turn right or go straight","Only make a U-turn","Only go straight"],"h1":"The left lane is for left turns and U-turns.","h2":"In Nevada, in a two-lane roundabout, you use the right lane to turn right or to go straight.","p":"Right. From the right lane, turn right or go straight."},"es":{"q":"En Nevada, en una glorieta de dos carriles, ¿qué puede hacer desde el carril derecho?","o":["Girar a la izquierda o dar vuelta en U","Girar a la derecha o seguir derecho","Solo dar vuelta en U","Solo seguir derecho"],"h1":"El carril izquierdo es para girar a la izquierda y dar vuelta en U.","h2":"En Nevada, en una glorieta de dos carriles, usted usa el carril derecho para girar a la derecha o seguir derecho.","p":"Correcto. Desde el carril derecho, gire a la derecha o siga derecho."},"ref":{"doc":"NV","page":44}},{"id":"nv-130","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, you may not make a U-turn near a grade (a hill) where you can see less than what distance in both directions?","o":["100 feet","50 feet","500 feet","1,000 feet"],"h1":"It is more than the 200 feet used for curves and fog.","h2":"In Nevada, you may not make a U-turn near a grade where there is less than 500 feet of visibility in both directions.","p":"Right. Near a grade, you need 500 feet of view each way."},"es":{"q":"En Nevada, no puede dar vuelta en U cerca de una pendiente (una colina) si puede ver menos de cierta distancia en ambas direcciones. ¿Cuál es esa distancia?","o":["100 pies","50 pies","500 pies","1,000 pies"],"h1":"Es más que los 200 pies que se usan para curvas y neblina.","h2":"En Nevada, usted no puede dar vuelta en U cerca de una pendiente donde hay menos de 500 pies de visibilidad en ambas direcciones.","p":"Correcto. Cerca de una pendiente necesita 500 pies de visibilidad en cada dirección."},"ref":{"doc":"NV","page":46}},{"id":"nv-131","scope":"NV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Nevada, what does a white curb usually mean?","o":["Parking for a limited time shown on a sign","A loading zone for trucks","Parking for people with disabilities","A very short stop only, to pick up or drop off passengers or mail"],"h1":"You may not stay there long at all.","h2":"In Nevada, a white curb usually means a very short stop only, to take on or let off passengers or to drop mail in a mailbox.","p":"Right. White means a very short stop for passengers or mail."},"es":{"q":"En Nevada, ¿qué significa normalmente una banqueta (cordón) pintada de blanco?","o":["Estacionamiento por un tiempo limitado que indica un letrero","Una zona de carga para camiones","Estacionamiento para personas con discapacidad","Solo una parada muy corta, para subir o bajar pasajeros o dejar correo"],"h1":"No se puede quedar mucho tiempo.","h2":"En Nevada, una banqueta blanca normalmente significa solo una parada muy corta, para subir o bajar pasajeros o dejar correo en un buzón.","p":"Correcto. El blanco es una parada muy corta para pasajeros o correo."},"ref":{"doc":"NV","page":48}},{"id":"nv-132","scope":"NV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Nevada, you park on the side of a road. From how far away in each direction should other drivers be able to see your vehicle?","o":["200 feet (about 20 car lengths)","50 feet (about 5 car lengths)","100 feet (about 10 car lengths)","1,000 feet"],"h1":"It is about 20 car lengths.","h2":"In Nevada, a parked vehicle should be visible for 200 feet, about 20 car lengths, in each direction.","p":"Right. Park where you can be seen from 200 feet each way."},"es":{"q":"En Nevada, usted se estaciona al lado de un camino. ¿Desde qué distancia en cada dirección deben poder ver su vehículo los otros conductores?","o":["200 pies (unos 20 largos de auto)","50 pies (unos 5 largos de auto)","100 pies (unos 10 largos de auto)","1,000 pies"],"h1":"Son unos 20 largos de auto.","h2":"En Nevada, un vehículo estacionado debe verse desde 200 pies, unos 20 largos de auto, en cada dirección.","p":"Correcto. Estaciónese donde lo vean desde 200 pies en cada dirección."},"ref":{"doc":"NV","page":48}},{"id":"nv-133","scope":"NV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Nevada, how close to a traffic signal at the side of a highway may you park?","o":["No closer than 10 feet","No closer than 30 feet","No closer than 15 feet","No closer than 75 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Nevada, you may not park within 30 feet of a traffic control signal at the side of a highway.","p":"Right. Stay at least 30 feet from a traffic signal."},"es":{"q":"En Nevada, ¿qué tan cerca de un semáforo al lado de una carretera puede estacionarse?","o":["A no menos de 10 pies","A no menos de 30 pies","A no menos de 15 pies","A no menos de 75 pies"],"h1":"Es más que la distancia para un hidrante.","h2":"En Nevada, usted no puede estacionarse a menos de 30 pies de un semáforo al lado de una carretera.","p":"Correcto. Quédese por lo menos a 30 pies de un semáforo."},"ref":{"doc":"NV","page":50}},{"id":"nv-134","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, you want to park on the side of the street across from a fire station driveway. How far from the entrance must you stay?","o":["At least 20 feet","At least 30 feet","At least 75 feet","At least 15 feet"],"h1":"It is much farther than on the same side of the street.","h2":"In Nevada, on the side of a highway opposite a fire station entrance, you may not park within 75 feet of that entrance.","p":"Right. Across from a fire station entrance, stay 75 feet away."},"es":{"q":"En Nevada, usted quiere estacionarse en el lado de la calle frente a la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe quedarse?","o":["Por lo menos a 20 pies","Por lo menos a 30 pies","Por lo menos a 75 pies","Por lo menos a 15 pies"],"h1":"Es mucho más lejos que en el mismo lado de la calle.","h2":"En Nevada, en el lado de la carretera frente a la entrada de una estación de bomberos, usted no puede estacionarse a menos de 75 pies de esa entrada.","p":"Correcto. Frente a la entrada de bomberos, quédese a 75 pies."},"ref":{"doc":"NV","page":50}},{"id":"nv-135","scope":"NV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Nevada, you are using high beams at night and come up behind another vehicle going the same way. At what distance should you switch to low beams?","o":["At least 300 feet behind it","At least 50 feet behind it","At least 100 feet behind it","Only when it is 1,000 feet ahead"],"h1":"It is less than the distance for oncoming cars.","h2":"In Nevada, you should change to low beams when you are at least 300 feet behind a vehicle you are following.","p":"Right. Dim your lights 300 feet behind the car ahead."},"es":{"q":"En Nevada, usted usa las luces altas de noche y se acerca por detrás a otro vehículo que va en su misma dirección. ¿A qué distancia debe cambiar a luces bajas?","o":["Por lo menos a 300 pies detrás de él","Por lo menos a 50 pies detrás de él","Por lo menos a 100 pies detrás de él","Solo cuando esté a 1,000 pies adelante"],"h1":"Es menos que la distancia para autos que vienen de frente.","h2":"En Nevada, usted debe cambiar a luces bajas cuando esté por lo menos a 300 pies detrás de un vehículo al que sigue.","p":"Correcto. Baje las luces a 300 pies detrás del auto de adelante."},"ref":{"doc":"NV","page":56}},{"id":"nv-136","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, a gasoline fire starts under your hood and you have no fire extinguisher. What should you never use on it?","o":["Sand","Water","Dirt","A chemical fire extinguisher"],"h1":"Burning gasoline floats.","h2":"In Nevada, you should never use water on a car fire, because burning gasoline floats on water and spreads the fire; sand or dirt can smother it.","p":"Right. Never use water on a gasoline fire."},"es":{"q":"En Nevada, se inicia un incendio de gasolina bajo el cofre y usted no tiene extintor. ¿Qué nunca debe usar para apagarlo?","o":["Arena","Agua","Tierra","Un extintor químico"],"h1":"La gasolina encendida flota.","h2":"En Nevada, nunca debe usar agua en un incendio del auto, porque la gasolina encendida flota sobre el agua y extiende el fuego; la arena o la tierra pueden sofocarlo.","p":"Correcto. Nunca use agua en un incendio de gasolina."},"ref":{"doc":"NV","page":58}},{"id":"nv-137","scope":"NV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Nevada, how much water on the road can push a car going at high speed off the road?","o":["At least 3 feet","At least 2 feet","Only 6 inches","At least 1 foot"],"h1":"It is much less than you might think: about half a foot.","h2":"In Nevada, a car traveling at high speed can be pushed off the road by only 6 inches of water.","p":"Right. Just 6 inches of water can push a fast car off the road."},"es":{"q":"En Nevada, ¿cuánta agua en el camino puede sacar del camino a un auto que va a alta velocidad?","o":["Por lo menos 3 pies","Por lo menos 2 pies","Solo 6 pulgadas","Por lo menos 1 pie"],"h1":"Es mucho menos de lo que usted cree: como medio pie.","h2":"En Nevada, un auto que va a alta velocidad puede salir del camino con solo 6 pulgadas de agua.","p":"Correcto. Solo 6 pulgadas de agua pueden sacar del camino a un auto rápido."},"ref":{"doc":"NV","page":59}},{"id":"nv-138","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, why should you be careful about a motorcycle's turn signal before you turn or change lanes?","o":["Motorcycles do not have turn signals","Motorcycle signals are red","Riders must use only hand signals","On most motorcycles, turn signals do not turn off by themselves"],"h1":"The rider may have forgotten to turn the signal off.","h2":"In Nevada, turn signals are not self-canceling on most motorcycles, so make sure you know what the rider is really doing.","p":"Right. A motorcycle signal may still be on by mistake."},"es":{"q":"En Nevada, ¿por qué debe tener cuidado con la direccional de una motocicleta antes de girar o cambiar de carril?","o":["Las motocicletas no tienen direccionales","Las direccionales de motocicleta son rojas","Los motociclistas solo deben usar señales con la mano","En la mayoría de las motocicletas, las direccionales no se apagan solas"],"h1":"El motociclista pudo haber olvidado apagar la direccional.","h2":"En Nevada, en la mayoría de las motocicletas las direccionales no se apagan solas, así que asegúrese de saber lo que realmente hace el motociclista.","p":"Correcto. La direccional de una moto puede seguir encendida por error."},"ref":{"doc":"NV","page":63}},{"id":"nv-139","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, what is the top speed of a moped on flat ground?","o":["30 mph","15 mph","45 mph","55 mph"],"h1":"It is a little more than 25 mph.","h2":"In Nevada, a moped has a maximum speed of 30 mph on flat or nearly flat ground and no more than two brake horsepower.","p":"Right. A moped goes no faster than 30 mph on flat ground."},"es":{"q":"En Nevada, ¿cuál es la velocidad máxima de un ciclomotor (moped) en terreno plano?","o":["30 mph","15 mph","45 mph","55 mph"],"h1":"Es un poco más de 25 mph.","h2":"En Nevada, un ciclomotor tiene una velocidad máxima de 30 mph en terreno plano o casi plano y no más de dos caballos de fuerza al freno.","p":"Correcto. Un ciclomotor no pasa de 30 mph en terreno plano."},"ref":{"doc":"NV","page":64}},{"id":"nv-140","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, what does a moped owner have to do?","o":["Insure the moped, but registration is not required","Register the moped, but insurance is not required","Both register and insure it every year","Neither register nor insure it"],"h1":"Registration is a one-time fee to help prevent theft.","h2":"In Nevada, moped owners must register their mopeds with the DMV, but they are not required to insure them.","p":"Right. Register it; insurance is not required."},"es":{"q":"En Nevada, ¿qué debe hacer el dueño de un ciclomotor (moped)?","o":["Asegurarlo, pero no se requiere registro","Registrarlo, pero no se requiere seguro","Registrarlo y asegurarlo cada año","Ni registrarlo ni asegurarlo"],"h1":"El registro es un pago único que ayuda a prevenir robos.","h2":"En Nevada, los dueños de ciclomotores deben registrarlos en el DMV, pero no están obligados a asegurarlos.","p":"Correcto. Se registra; el seguro no es obligatorio."},"ref":{"doc":"NV","page":64}},{"id":"nv-141","scope":"NV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Nevada, a moped rider must stay in the far right lane. When may the rider leave it to turn left?","o":["Whenever the rider wants to pass","Only on freeways","When getting ready to turn left within a quarter mile","Never; mopeds may not turn left"],"h1":"The turn must be close by.","h2":"In Nevada, a moped rider may leave the far right lane to prepare for a left turn, and the turn must be made within one-quarter mile.","p":"Right. Moving left is allowed for a left turn within a quarter mile."},"es":{"q":"En Nevada, quien maneja un ciclomotor (moped) debe ir en el carril de la extrema derecha. ¿Cuándo puede salir de él para girar a la izquierda?","o":["Siempre que quiera rebasar","Solo en autopistas","Cuando se prepara para girar a la izquierda dentro de un cuarto de milla","Nunca; los ciclomotores no pueden girar a la izquierda"],"h1":"El giro debe estar cerca.","h2":"En Nevada, quien maneja un ciclomotor puede salir del carril derecho para prepararse para un giro a la izquierda, y el giro debe hacerse dentro de un cuarto de milla.","p":"Correcto. Puede moverse a la izquierda para girar dentro de un cuarto de milla."},"ref":{"doc":"NV","page":64}},{"id":"nv-142","scope":"NV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Nevada, a school bus driver sees you pass the bus while its red lights are flashing and reports it. What can happen?","o":["Nothing, only police can report it","The bus driver may take your license","Your car is towed right away","The vehicle's registered owner gets a warning letter"],"h1":"The report goes to the school district and the DMV.","h2":"In Nevada, school bus drivers may report violations to the school district and the DMV, and the vehicle's registered owner is sent a warning letter.","p":"Right. The registered owner gets a warning letter."},"es":{"q":"En Nevada, el conductor de un autobús escolar ve que usted rebasa el autobús mientras tiene las luces rojas intermitentes y lo reporta. ¿Qué puede pasar?","o":["Nada, solo la policía puede reportarlo","El conductor del autobús puede quitarle la licencia","Su auto es remolcado de inmediato","El dueño registrado del vehículo recibe una carta de advertencia"],"h1":"El reporte va al distrito escolar y al DMV.","h2":"En Nevada, los conductores de autobuses escolares pueden reportar infracciones al distrito escolar y al DMV, y al dueño registrado del vehículo se le envía una carta de advertencia.","p":"Correcto. El dueño registrado recibe una carta de advertencia."},"ref":{"doc":"NV","page":64}},{"id":"nv-143","scope":"NV","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Nevada, you stop for a person who is blind waiting at a crosswalk. How close to the crosswalk should you stop?","o":["No more than five feet from it","At least 20 feet back from it","In the middle of it","It does not matter"],"h1":"The person uses the sound of your engine as a guide.","h2":"In Nevada, you should not stop more than five feet from the crosswalk, because a person who is blind uses the sound of your engine as a guide.","p":"Right. Stop within five feet of the crosswalk."},"es":{"q":"En Nevada, usted se detiene por una persona ciega que espera en un cruce peatonal. ¿Qué tan cerca del cruce debe detenerse?","o":["A no más de cinco pies de él","Por lo menos a 20 pies antes de él","En medio del cruce","No importa"],"h1":"La persona usa el sonido de su motor como guía.","h2":"En Nevada, usted no debe detenerse a más de cinco pies del cruce peatonal, porque una persona ciega usa el sonido de su motor como guía.","p":"Correcto. Deténgase a no más de cinco pies del cruce."},"ref":{"doc":"NV","page":67}},{"id":"nv-144","scope":"NV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Nevada, you start a long trip pulling a trailer. When should you first stop to inspect the trailer and its load again?","o":["After 500 miles","Within the first 50 miles","Only when you arrive","After 8 hours"],"h1":"Check early, before a small problem grows.","h2":"In Nevada, you should inspect the trailer and the load-securing devices again within 50 miles after starting an extended trip.","p":"Right. Check again within the first 50 miles."},"es":{"q":"En Nevada, usted empieza un viaje largo jalando un remolque. ¿Cuándo debe detenerse por primera vez para revisar otra vez el remolque y la carga?","o":["Después de 500 millas","Dentro de las primeras 50 millas","Solo al llegar","Después de 8 horas"],"h1":"Revise pronto, antes de que un problema pequeño crezca.","h2":"En Nevada, usted debe revisar otra vez el remolque y los amarres de la carga dentro de las primeras 50 millas de un viaje largo.","p":"Correcto. Revise de nuevo dentro de las primeras 50 millas."},"ref":{"doc":"NV","page":70}},{"id":"nv-145","scope":"NV","cat":"licensing","sign":null,"c":2,"en":{"q":"In Nevada, how long do DUI convictions stay on your driving record?","o":["One year","Three years","Seven years","Ten years"],"h1":"Most other violations are reported to insurers for three years; DUI lasts longer.","h2":"In Nevada, convictions related to DUI stay on your driving record for seven years.","p":"Right. DUI convictions stay on your record seven years."},"es":{"q":"En Nevada, ¿por cuánto tiempo quedan en su historial de manejo las condenas por DUI?","o":["Un año","Tres años","Siete años","Diez años"],"h1":"La mayoría de las otras infracciones se reportan a las aseguradoras por tres años; el DUI dura más.","h2":"En Nevada, las condenas relacionadas con DUI quedan en su historial de manejo por siete años.","p":"Correcto. Las condenas por DUI quedan siete años en su historial."},"ref":{"doc":"NV","page":77}},{"id":"nv-146","scope":"NV","cat":"licensing","sign":null,"c":3,"en":{"q":"In Nevada, how many demerit points does a conviction for careless driving add?","o":["2 points","4 points","8 points","6 points"],"h1":"It is fewer than reckless driving, which is 8.","h2":"In Nevada, careless driving adds 6 demerit points to your driving record.","p":"Right. Careless driving is 6 points."},"es":{"q":"En Nevada, ¿cuántos puntos de demérito agrega una condena por manejo descuidado (careless driving)?","o":["2 puntos","4 puntos","8 puntos","6 puntos"],"h1":"Es menos que el manejo imprudente, que son 8.","h2":"En Nevada, el manejo descuidado agrega 6 puntos de demérito a su historial de manejo.","p":"Correcto. El manejo descuidado son 6 puntos."},"ref":{"doc":"NV","page":78}},{"id":"nv-147","scope":"NV","cat":"licensing","sign":null,"c":0,"en":{"q":"In Nevada, you are convicted of a second DUI within 7 years. How long is your license revoked?","o":["One year","90 days","185 days","Five years"],"h1":"It is longer than for a first offense, but shorter than for a third.","h2":"In Nevada, a second DUI offense within 7 years brings a one-year license revocation, along with other penalties.","p":"Right. A second DUI in 7 years means a one-year revocation."},"es":{"q":"En Nevada, a usted lo condenan por un segundo DUI dentro de 7 años. ¿Por cuánto tiempo le revocan la licencia?","o":["Un año","90 días","185 días","Cinco años"],"h1":"Es más que para un primer delito, pero menos que para un tercero.","h2":"En Nevada, un segundo delito de DUI dentro de 7 años trae la revocación de la licencia por un año, además de otras penas.","p":"Correcto. Un segundo DUI en 7 años significa un año de revocación."},"ref":{"doc":"NV","page":80}},{"id":"nv-148","scope":"NV","cat":"licensing","sign":null,"c":1,"en":{"q":"In Nevada, you move here with a car registered in another state. When must you register it in Nevada?","o":["Within 6 months","Within 30 days of becoming a resident, or when you get a Nevada license if that is sooner","Only when the old registration expires","Within one year"],"h1":"Whichever of two events comes first.","h2":"In Nevada, you must register your vehicle within 30 days of becoming a resident or when you get a Nevada driver license, whichever comes first.","p":"Right. Register within 30 days, or sooner if you get your license first."},"es":{"q":"En Nevada, usted se muda aquí con un auto registrado en otro estado. ¿Cuándo debe registrarlo en Nevada?","o":["Dentro de 6 meses","Dentro de 30 días de hacerse residente, o al obtener su licencia de Nevada si eso pasa antes","Solo cuando venza el registro anterior","Dentro de un año"],"h1":"Lo que pase primero de dos cosas.","h2":"En Nevada, usted debe registrar su vehículo dentro de 30 días de hacerse residente o al obtener su licencia de manejo de Nevada, lo que ocurra primero.","p":"Correcto. Regístrelo dentro de 30 días, o antes si obtiene primero la licencia."},"ref":{"doc":"NV","page":83}},{"id":"ny-001","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the youngest age to apply for a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is the same age many states use for a first license.","h2":"You must be at least 16 to apply for a New York learner permit.","p":"Right. In New York the permit starts at 16."},"es":{"q":"En Nueva York, ¿cuál es la edad mínima para solicitar un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es la misma edad que muchos estados usan para la primera licencia.","h2":"Usted debe tener por lo menos 16 años para solicitar un permiso de aprendiz en Nueva York.","p":"Correcto. En Nueva York el permiso empieza a los 16."},"zh":{"q":"在 New York，最小几岁可以申请学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"很多州第一次拿驾照也是这个年龄。","h2":"你必须至少 16 岁才能申请 New York 的学习驾照。","p":"对。在 New York，学习驾照从 16 岁开始。"},"vi":{"q":"Ở New York, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đây là cùng độ tuổi mà nhiều tiểu bang dùng cho bằng lái đầu tiên.","h2":"Bạn phải ít nhất 16 tuổi để nộp đơn xin giấy phép tập lái ở New York.","p":"Đúng. Ở New York, giấy phép tập lái bắt đầu từ 16 tuổi."},"tl":{"q":"Sa New York, ano ang pinakabatang edad para mag-apply ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Ito ang parehong edad na ginagamit ng maraming estado para sa unang lisensya.","h2":"Dapat ay hindi bababa sa 16 taong gulang ka para mag-apply ng learner permit sa New York.","p":"Tama. Sa New York, nagsisimula ang permit sa edad na 16."},"ar":{"q":"في New York، ما أصغر عمر للتقدّم بطلب تصريح تعلّم القيادة (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو نفس العمر الذي تستخدمه ولايات كثيرة لأول رخصة قيادة.","h2":"يجب أن يكون عمرك 16 سنة على الأقل لتتقدّم بطلب تصريح تعلّم القيادة في New York.","p":"صحيح. في New York يبدأ التصريح في عمر 16 سنة."},"ref":{"doc":"NY","page":11}},{"id":"ny-002","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, how many of the 20 questions on the written permit test must you answer correctly?","o":["At least 14","At least 10","At least 16","At least 18"],"h1":"You may miss up to six questions.","h2":"To pass the New York written permit test you must answer at least 14 of the 20 questions correctly.","p":"Right. You need at least 14 out of 20."},"es":{"q":"En Nueva York, ¿cuántas de las 20 preguntas del examen escrito del permiso debe contestar bien?","o":["Por lo menos 14","Por lo menos 10","Por lo menos 16","Por lo menos 18"],"h1":"Puede equivocarse hasta en seis preguntas.","h2":"Para aprobar el examen escrito del permiso en Nueva York debe contestar bien por lo menos 14 de las 20 preguntas.","p":"Correcto. Necesita por lo menos 14 de 20."},"zh":{"q":"在 New York，学习驾照笔试的 20 道题里，你必须答对多少道？","o":["至少 14 道","至少 10 道","至少 16 道","至少 18 道"],"h1":"你最多可以答错六道。","h2":"要通过 New York 的学习驾照笔试，你必须答对 20 道题里的至少 14 道。","p":"对。20 道里你至少要答对 14 道。"},"vi":{"q":"Ở New York, trong 20 câu hỏi của bài thi viết để lấy giấy phép tập lái, bạn phải trả lời đúng bao nhiêu câu?","o":["Ít nhất 14 câu","Ít nhất 10 câu","Ít nhất 16 câu","Ít nhất 18 câu"],"h1":"Bạn có thể sai tối đa sáu câu.","h2":"Để đậu bài thi viết lấy giấy phép tập lái ở New York, bạn phải trả lời đúng ít nhất 14 trong 20 câu hỏi.","p":"Đúng. Bạn cần ít nhất 14 trên 20 câu."},"tl":{"q":"Sa New York, ilan sa 20 tanong sa written permit test ang dapat mong masagot nang tama?","o":["Hindi bababa sa 14","Hindi bababa sa 10","Hindi bababa sa 16","Hindi bababa sa 18"],"h1":"Puwede kang magkamali sa hanggang anim na tanong.","h2":"Para pumasa sa written permit test ng New York, dapat mong masagot nang tama ang hindi bababa sa 14 sa 20 tanong.","p":"Tama. Kailangan mo ng hindi bababa sa 14 sa 20."},"ar":{"q":"في New York، كم سؤالًا من أسئلة الاختبار الكتابي العشرين للتصريح يجب أن تجيب عنه إجابة صحيحة؟","o":["14 على الأقل","10 على الأقل","16 على الأقل","18 على الأقل"],"h1":"يمكنك أن تخطئ في ستة أسئلة كحدّ أقصى.","h2":"لتنجح في الاختبار الكتابي للتصريح في New York يجب أن تجيب إجابة صحيحة عن 14 سؤالًا على الأقل من 20.","p":"صحيح. تحتاج إلى 14 من 20 على الأقل."},"ref":{"doc":"NY","page":10}},{"id":"ny-003","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, what else must you get right on the written permit test, besides 14 of 20 questions?","o":["All four road sign questions","The first five questions","Every question about alcohol","At least two of the four road sign questions"],"h1":"It is half of the sign questions.","h2":"On the New York written permit test you must also answer at least two of the four road sign questions correctly, or you fail.","p":"Right. You need two of the four sign questions."},"es":{"q":"En Nueva York, además de 14 de 20 preguntas, ¿qué más debe contestar bien en el examen escrito del permiso?","o":["Las cuatro preguntas sobre señales de tránsito","Las primeras cinco preguntas","Todas las preguntas sobre alcohol","Por lo menos dos de las cuatro preguntas sobre señales de tránsito"],"h1":"Es la mitad de las preguntas sobre señales.","h2":"En el examen escrito del permiso de Nueva York también debe contestar bien por lo menos dos de las cuatro preguntas sobre señales de tránsito, o no aprueba.","p":"Correcto. Necesita dos de las cuatro preguntas sobre señales."},"zh":{"q":"在 New York，学习驾照笔试除了要答对 20 道里的 14 道，还必须答对什么？","o":["全部四道交通标志题","前五道题","每一道关于酒精的题","四道交通标志题里至少两道"],"h1":"它是交通标志题的一半。","h2":"在 New York 的学习驾照笔试中，你还必须答对四道交通标志题里的至少两道，不然就不通过。","p":"对。四道标志题你要答对两道。"},"vi":{"q":"Ở New York, ngoài việc đúng 14 trên 20 câu, bạn còn phải trả lời đúng điều gì khác trong bài thi viết?","o":["Cả bốn câu hỏi về biển báo giao thông","Năm câu hỏi đầu tiên","Mọi câu hỏi về rượu bia","Ít nhất hai trong bốn câu hỏi về biển báo giao thông"],"h1":"Đó là một nửa số câu hỏi về biển báo.","h2":"Trong bài thi viết lấy giấy phép tập lái ở New York, bạn cũng phải trả lời đúng ít nhất hai trong bốn câu hỏi về biển báo giao thông, nếu không bạn sẽ rớt.","p":"Đúng. Bạn cần đúng hai trong bốn câu hỏi về biển báo."},"tl":{"q":"Sa New York, bukod sa 14 sa 20 tanong, ano pa ang dapat mong masagot nang tama sa written permit test?","o":["Lahat ng apat na tanong tungkol sa road sign","Ang unang limang tanong","Bawat tanong tungkol sa alak","Hindi bababa sa dalawa sa apat na tanong tungkol sa road sign"],"h1":"Kalahati ito ng mga tanong tungkol sa sign.","h2":"Sa written permit test ng New York, dapat mo ring masagot nang tama ang hindi bababa sa dalawa sa apat na tanong tungkol sa road sign, kung hindi ay babagsak ka.","p":"Tama. Kailangan mo ng dalawa sa apat na tanong tungkol sa sign."},"ar":{"q":"في New York، ما الذي يجب أن تجيب عنه إجابة صحيحة أيضًا في الاختبار الكتابي للتصريح، إلى جانب 14 من 20 سؤالًا؟","o":["كل أسئلة إشارات الطريق الأربعة","الأسئلة الخمسة الأولى","كل سؤال عن الكحول","سؤالان على الأقل من أسئلة إشارات الطريق الأربعة"],"h1":"هي نصف أسئلة الإشارات.","h2":"في الاختبار الكتابي للتصريح في New York يجب أيضًا أن تجيب إجابة صحيحة عن سؤالين على الأقل من أسئلة إشارات الطريق الأربعة، وإلا ترسب.","p":"صحيح. تحتاج إلى سؤالين من أسئلة الإشارات الأربعة."},"ref":{"doc":"NY","page":10}},{"id":"ny-004","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, can you take the Class D written permit test in Spanish?","o":["No, only in English","Yes, it is offered in Spanish and many other languages","Only in New York City","Only with a paid interpreter"],"h1":"The DMV offers the test in about 20 languages.","h2":"Yes, the New York DMV offers the Class D written permit test in Spanish and many other languages.","p":"Right. You can take it in Spanish."},"es":{"q":"En Nueva York, ¿puede tomar en español el examen escrito del permiso clase D?","o":["No, solo en inglés","Sí, se ofrece en español y en muchos otros idiomas","Solo en la ciudad de Nueva York","Solo con un intérprete pagado"],"h1":"El DMV ofrece el examen en unos 20 idiomas.","h2":"Sí, el DMV de Nueva York ofrece el examen escrito del permiso clase D en español y en muchos otros idiomas.","p":"Correcto. Puede tomarlo en español."},"zh":{"q":"在 New York，Class D 学习驾照笔试可以用西班牙语考吗？","o":["不可以，只能用英语","可以，有西班牙语和很多其他语言","只在 New York City 可以","只有付钱请翻译才可以"],"h1":"DMV 提供大约 20 种语言的考试。","h2":"可以，New York DMV 提供西班牙语和很多其他语言的 Class D 学习驾照笔试。","p":"对。你可以用西班牙语考。"},"vi":{"q":"Ở New York, bạn có thể làm bài thi viết lấy giấy phép Class D bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, bài thi có bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác","Chỉ ở New York City","Chỉ khi có thông dịch viên trả tiền"],"h1":"DMV có bài thi bằng khoảng 20 ngôn ngữ.","h2":"Có, DMV New York có bài thi viết lấy giấy phép Class D bằng tiếng Tây Ban Nha và nhiều ngôn ngữ khác.","p":"Đúng. Bạn có thể thi bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa New York, puwede mo bang kunin ang Class D written permit test sa Spanish?","o":["Hindi, sa English lang","Oo, inaalok ito sa Spanish at sa marami pang ibang wika","Sa New York City lang","Kung may bayad na interpreter lang"],"h1":"Inaalok ng DMV ang test sa mga 20 wika.","h2":"Oo, inaalok ng New York DMV ang Class D written permit test sa Spanish at sa marami pang ibang wika.","p":"Tama. Puwede mo itong kunin sa Spanish."},"ar":{"q":"في New York، هل يمكنك أداء الاختبار الكتابي لتصريح Class D باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، هو متاح بالإسبانية وبلغات أخرى كثيرة","في New York City فقط","مع مترجم مدفوع الأجر فقط"],"h1":"تقدّم إدارة DMV الاختبار بحوالي 20 لغة.","h2":"نعم، تقدّم إدارة DMV في New York الاختبار الكتابي لتصريح Class D بالإسبانية وبلغات أخرى كثيرة.","p":"صحيح. يمكنك أداؤه بالإسبانية."},"ref":{"doc":"NY","page":10}},{"id":"ny-005","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how many hours of supervised driving must a teen complete before the road test?","o":["30 hours","50 hours","40 hours","60 hours"],"h1":"It is half of one hundred.","h2":"A New York teen must complete at least 50 hours of supervised practice driving before the road test.","p":"Right. New York asks for 50 supervised hours."},"es":{"q":"En Nueva York, ¿cuántas horas de manejo supervisado debe completar un joven antes del examen de manejo?","o":["30 horas","50 horas","40 horas","60 horas"],"h1":"Es la mitad de cien.","h2":"En Nueva York, un joven debe completar por lo menos 50 horas de práctica de manejo supervisada antes del examen de manejo.","p":"Correcto. Nueva York pide 50 horas supervisadas."},"zh":{"q":"在 New York，青少年路考前必须完成多少小时有人监督的驾驶？","o":["30 小时","50 小时","40 小时","60 小时"],"h1":"它是一百的一半。","h2":"New York 的青少年路考前必须完成至少 50 小时有人监督的驾驶练习。","p":"对。New York 要求 50 小时有人监督的练习。"},"vi":{"q":"Ở New York, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi thi lái trên đường (road test)?","o":["30 giờ","50 giờ","40 giờ","60 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên ở New York phải tập lái có người giám sát ít nhất 50 giờ trước khi thi lái trên đường.","p":"Đúng. New York yêu cầu 50 giờ có người giám sát."},"tl":{"q":"Sa New York, ilang oras ng supervised driving (pagmamaneho na may kasamang nagbabantay) ang dapat tapusin ng isang teen bago ang road test?","o":["30 oras","50 oras","40 oras","60 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Ang isang teen sa New York ay dapat makatapos ng hindi bababa sa 50 oras ng supervised practice driving bago ang road test.","p":"Tama. Humihingi ang New York ng 50 supervised na oras."},"ar":{"q":"في New York، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل اختبار القيادة على الطريق (road test)؟","o":["30 ساعة","50 ساعة","40 ساعة","60 ساعة"],"h1":"هي نصف المئة.","h2":"يجب أن يكمل المراهق في New York ما لا يقل عن 50 ساعة من التدريب على القيادة تحت الإشراف قبل اختبار القيادة على الطريق.","p":"صحيح. تطلب New York خمسين ساعة تحت الإشراف."},"ref":{"doc":"NY","page":13}},{"id":"ny-006","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many of the 50 supervised hours must be driven after sunset?","o":["5 hours","10 hours","20 hours","15 hours"],"h1":"It is more than 10 and less than 20.","h2":"At least 15 of the 50 supervised hours in New York must be driven after sunset.","p":"Right. Fifteen of the hours are after sunset."},"es":{"q":"En Nueva York, ¿cuántas de las 50 horas supervisadas deben ser después de la puesta del sol?","o":["5 horas","10 horas","20 horas","15 horas"],"h1":"Son más de 10 y menos de 20.","h2":"En Nueva York, por lo menos 15 de las 50 horas supervisadas deben ser después de la puesta del sol.","p":"Correcto. Quince de las horas son después de la puesta del sol."},"zh":{"q":"在 New York，50 小时有人监督的驾驶里，有多少小时必须在日落以后开？","o":["5 小时","10 小时","20 小时","15 小时"],"h1":"它比 10 多，比 20 少。","h2":"在 New York，50 小时有人监督的驾驶里，至少 15 小时必须在日落以后开。","p":"对。其中十五小时在日落以后。"},"vi":{"q":"Ở New York, trong 50 giờ lái có người giám sát, phải có bao nhiêu giờ lái sau khi mặt trời lặn?","o":["5 giờ","10 giờ","20 giờ","15 giờ"],"h1":"Nhiều hơn 10 và ít hơn 20.","h2":"Ở New York, ít nhất 15 trong 50 giờ lái có người giám sát phải là sau khi mặt trời lặn.","p":"Đúng. Mười lăm giờ là sau khi mặt trời lặn."},"tl":{"q":"Sa New York, ilan sa 50 supervised na oras ang dapat imaneho pagkatapos lumubog ang araw?","o":["5 oras","10 oras","20 oras","15 oras"],"h1":"Higit ito sa 10 at kulang sa 20.","h2":"Sa New York, hindi bababa sa 15 sa 50 supervised na oras ang dapat imaneho pagkatapos lumubog ang araw.","p":"Tama. Labinlima sa mga oras ay pagkatapos lumubog ang araw."},"ar":{"q":"في New York، كم ساعة من الخمسين ساعة تحت الإشراف يجب أن تكون بعد غروب الشمس؟","o":["5 ساعات","10 ساعات","20 ساعة","15 ساعة"],"h1":"هي أكثر من 10 وأقل من 20.","h2":"في New York يجب أن تكون 15 ساعة على الأقل من الخمسين ساعة تحت الإشراف بعد غروب الشمس.","p":"صحيح. خمس عشرة ساعة منها بعد غروب الشمس."},"ref":{"doc":"NY","page":13}},{"id":"ny-007","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, what must a teen bring to every road test to show the supervised hours?","o":["A Certification of Supervised Driving signed by a parent or guardian","A letter from a teacher","A copy of the learner permit test","Nothing, the DMV checks online"],"h1":"It is a DMV form that a parent signs.","h2":"A New York teen must bring a Certification of Supervised Driving, signed by a parent or guardian, each time they take the road test.","p":"Right. Bring the signed certification every time."},"es":{"q":"En Nueva York, ¿qué debe llevar un joven a cada examen de manejo para demostrar las horas supervisadas?","o":["Una Certificación de Manejo Supervisado firmada por un padre, madre o tutor","Una carta de un maestro","Una copia del examen del permiso","Nada, el DMV lo revisa en línea"],"h1":"Es un formulario del DMV que firma un padre.","h2":"En Nueva York, un joven debe llevar una Certificación de Manejo Supervisado, firmada por un padre, madre o tutor, cada vez que toma el examen de manejo.","p":"Correcto. Lleve la certificación firmada cada vez."},"zh":{"q":"在 New York，青少年每次路考必须带什么来证明有人监督的驾驶时间？","o":["一份由父母或监护人签字的有人监督驾驶证明（Certification of Supervised Driving）","一封老师的信","一份学习驾照考试的复印件","什么都不用带，DMV 会在网上查"],"h1":"它是一份父母签字的 DMV 表格。","h2":"New York 的青少年每次路考都必须带一份由父母或监护人签字的有人监督驾驶证明（Certification of Supervised Driving）。","p":"对。每次都要带签好字的证明。"},"vi":{"q":"Ở New York, thiếu niên phải mang gì đến mỗi lần thi lái trên đường để chứng minh số giờ lái có người giám sát?","o":["Giấy Chứng nhận Lái xe có Giám sát (Certification of Supervised Driving) có chữ ký của cha mẹ hoặc người giám hộ","Một lá thư của giáo viên","Một bản sao bài thi giấy phép tập lái","Không cần gì, DMV kiểm tra trên mạng"],"h1":"Đó là một mẫu đơn của DMV mà cha mẹ ký tên.","h2":"Thiếu niên ở New York phải mang Giấy Chứng nhận Lái xe có Giám sát (Certification of Supervised Driving), có chữ ký của cha mẹ hoặc người giám hộ, mỗi lần đi thi lái trên đường.","p":"Đúng. Mỗi lần thi đều mang giấy chứng nhận đã ký."},"tl":{"q":"Sa New York, ano ang dapat dalhin ng isang teen sa bawat road test para ipakita ang supervised na oras?","o":["Isang Certification of Supervised Driving na pinirmahan ng magulang o guardian","Isang sulat mula sa guro","Kopya ng learner permit test","Wala, tinitingnan ng DMV online"],"h1":"Isa itong form ng DMV na pinipirmahan ng magulang.","h2":"Ang isang teen sa New York ay dapat magdala ng Certification of Supervised Driving, na pinirmahan ng magulang o guardian, sa bawat pagkuha ng road test.","p":"Tama. Dalhin ang pinirmahang certification sa bawat pagkakataon."},"ar":{"q":"في New York، ماذا يجب أن يُحضر المراهق إلى كل اختبار قيادة على الطريق ليُثبت ساعات القيادة تحت الإشراف؟","o":["شهادة القيادة تحت الإشراف (Certification of Supervised Driving) موقّعة من أحد الوالدين أو الوصي","رسالة من معلّم","نسخة من اختبار تصريح التعلّم","لا شيء، فإدارة DMV تتحقق عبر الإنترنت"],"h1":"هي استمارة من DMV يوقّعها أحد الوالدين.","h2":"يجب أن يُحضر المراهق في New York شهادة القيادة تحت الإشراف (Certification of Supervised Driving)، موقّعة من أحد الوالدين أو الوصي، في كل مرة يؤدي فيها اختبار القيادة على الطريق.","p":"صحيح. أحضِر الشهادة الموقّعة في كل مرة."},"ref":{"doc":"NY","page":14}},{"id":"ny-008","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, how old must the supervising driver of a learner permit holder be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"The supervisor must be old enough to drink alcohol legally.","h2":"In New York the supervising driver must be at least 21 and hold a valid license for the type of vehicle being driven.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Nueva York, ¿qué edad debe tener el conductor que supervisa a quien tiene permiso de aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Nueva York, el conductor supervisor debe tener por lo menos 21 años y una licencia válida para el tipo de vehículo que se maneja.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 New York，监督学习驾照持有人的司机必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"监督的人必须到了可以合法喝酒的年龄。","h2":"在 New York，监督司机必须至少 21 岁，并且有所开车辆类型的有效驾照。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở New York, người lái xe giám sát người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người giám sát phải đủ tuổi để được uống rượu hợp pháp.","h2":"Ở New York, người lái xe giám sát phải ít nhất 21 tuổi và có bằng lái hợp lệ cho loại xe đang lái.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa New York, ilang taon dapat ang supervising driver (nagbabantay na driver) ng may learner permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Dapat ay nasa edad na ang supervisor para legal na uminom ng alak.","h2":"Sa New York, ang supervising driver ay dapat hindi bababa sa 21 taong gulang at may valid na lisensya para sa uri ng sasakyang minamaneho.","p":"Tama. Dapat ay 21 o mas matanda ang supervisor."},"ar":{"q":"في New York، كم يجب أن يكون عمر السائق المشرف على حامل تصريح التعلّم؟","o":["16 على الأقل","18 على الأقل","21 على الأقل","25 على الأقل"],"h1":"يجب أن يكون المشرف في عمر يسمح له بشرب الكحول قانونيًا.","h2":"في New York يجب أن يكون السائق المشرف بعمر 21 سنة على الأقل وأن يحمل رخصة سارية لنوع المركبة التي تُقاد.","p":"صحيح. يجب أن يكون المشرف بعمر 21 أو أكثر."},"ref":{"doc":"NY","page":11}},{"id":"ny-009","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how long must a teen hold the learner permit before taking the road test?","o":["At least one month","At least six months","At least three months","At least one year"],"h1":"It is half a year.","h2":"A New York teen must hold the learner permit for at least six months before taking the road test.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Nueva York, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes del examen de manejo?","o":["Por lo menos un mes","Por lo menos seis meses","Por lo menos tres meses","Por lo menos un año"],"h1":"Es medio año.","h2":"En Nueva York, un joven debe tener el permiso de aprendiz por lo menos seis meses antes del examen de manejo.","p":"Correcto. Tenga el permiso por lo menos seis meses."},"zh":{"q":"在 New York，青少年必须持有学习驾照多久才能参加路考？","o":["至少一个月","至少六个月","至少三个月","至少一年"],"h1":"它是半年。","h2":"New York 的青少年必须持有学习驾照至少六个月，才能参加路考。","p":"对。持有学习驾照至少六个月。"},"vi":{"q":"Ở New York, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái trên đường?","o":["Ít nhất một tháng","Ít nhất sáu tháng","Ít nhất ba tháng","Ít nhất một năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở New York phải giữ giấy phép tập lái ít nhất sáu tháng trước khi thi lái trên đường.","p":"Đúng. Giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa New York, gaano katagal dapat hawak ng isang teen ang learner permit bago kumuha ng road test?","o":["Hindi bababa sa isang buwan","Hindi bababa sa anim na buwan","Hindi bababa sa tatlong buwan","Hindi bababa sa isang taon"],"h1":"Kalahating taon ito.","h2":"Ang isang teen sa New York ay dapat may hawak ng learner permit nang hindi bababa sa anim na buwan bago kumuha ng road test.","p":"Tama. Hawakan ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في New York، كم يجب أن يحمل المراهق تصريح التعلّم قبل أداء اختبار القيادة على الطريق؟","o":["شهر واحد على الأقل","ستة أشهر على الأقل","ثلاثة أشهر على الأقل","سنة واحدة على الأقل"],"h1":"هي نصف سنة.","h2":"يجب أن يحمل المراهق في New York تصريح التعلّم ستة أشهر على الأقل قبل أداء اختبار القيادة على الطريق.","p":"صحيح. احمل التصريح ستة أشهر على الأقل."},"ref":{"doc":"NY","page":14}},{"id":"ny-010","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, who may sit in the front seat when a junior permit holder is driving?","o":["Any passenger over 16","Any family member","Anyone wearing a seat belt","Only the supervising driver"],"h1":"The seat beside the learner is saved for one person.","h2":"When a New York junior permit holder drives, no one may sit in the front seat except the supervising driver.","p":"Right. Only the supervisor sits in front."},"es":{"q":"En Nueva York, ¿quién puede ir en el asiento delantero cuando maneja alguien con permiso de aprendiz juvenil?","o":["Cualquier pasajero mayor de 16","Cualquier familiar","Cualquiera que use el cinturón","Solo el conductor supervisor"],"h1":"El asiento al lado del aprendiz es para una sola persona.","h2":"Cuando maneja en Nueva York alguien con permiso de aprendiz juvenil, nadie puede ir en el asiento delantero excepto el conductor supervisor.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 New York，青少年学习驾照（junior permit）持有人开车时，谁可以坐在前排？","o":["任何 16 岁以上的乘客","任何家人","任何系了安全带的人","只有监督司机"],"h1":"学员旁边的座位是留给一个人的。","h2":"New York 的青少年学习驾照持有人开车时，除了监督司机，任何人都不能坐在前排。","p":"对。只有监督的人坐在前面。"},"vi":{"q":"Ở New York, ai được ngồi ghế trước khi người có giấy phép tập lái thiếu niên (junior permit) đang lái xe?","o":["Bất kỳ hành khách nào trên 16 tuổi","Bất kỳ người nào trong gia đình","Bất kỳ ai thắt dây an toàn","Chỉ người lái xe giám sát"],"h1":"Ghế bên cạnh người tập lái được dành cho một người.","h2":"Khi người có junior permit ở New York lái xe, không ai được ngồi ghế trước ngoại trừ người lái xe giám sát.","p":"Đúng. Chỉ người giám sát ngồi phía trước."},"tl":{"q":"Sa New York, sino ang puwedeng umupo sa harapang upuan kapag nagmamaneho ang may junior permit?","o":["Kahit sinong pasahero na higit 16 taong gulang","Kahit sinong miyembro ng pamilya","Kahit sinong nakasuot ng seat belt","Ang supervising driver lang"],"h1":"Ang upuan sa tabi ng nag-aaral ay para sa iisang tao.","h2":"Kapag nagmamaneho ang may junior permit sa New York, walang ibang puwedeng umupo sa harapang upuan maliban sa supervising driver.","p":"Tama. Ang supervisor lang ang nasa harap."},"ar":{"q":"في New York، من يمكنه الجلوس في المقعد الأمامي عندما يقود حامل تصريح التعلّم للصغار (junior permit)؟","o":["أي راكب عمره أكثر من 16","أي فرد من العائلة","أي شخص يضع حزام الأمان","السائق المشرف فقط"],"h1":"المقعد بجانب المتعلّم محجوز لشخص واحد.","h2":"عندما يقود حامل junior permit في New York، لا يجوز لأحد الجلوس في المقعد الأمامي إلا السائق المشرف.","p":"صحيح. المشرف وحده يجلس في الأمام."},"ref":{"doc":"NY","page":13}},{"id":"ny-011","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York City, when may a junior permit holder (under 18) never drive?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 10 p.m. and 4 a.m.","Between 11 p.m. and 5 a.m."],"h1":"It starts at 9 in the evening.","h2":"A junior permit holder may never drive in the five boroughs of New York City between 9 p.m. and 5 a.m.","p":"Right. No junior permit driving in the city from 9 p.m. to 5 a.m."},"es":{"q":"En la ciudad de Nueva York, ¿en qué horario no puede manejar nunca quien tiene un permiso juvenil (menor de 18 años)?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 10 p.m. y las 4 a.m.","Entre las 11 p.m. y las 5 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"Quien tiene un permiso juvenil nunca puede manejar en los cinco condados de la ciudad de Nueva York entre las 9 p.m. y las 5 a.m.","p":"Correcto. Con permiso juvenil no se maneja en la ciudad de 9 p.m. a 5 a.m."},"zh":{"q":"在 New York City，青少年学习驾照（junior permit）持有人（未满 18 岁）什么时候绝对不能开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 10 点到凌晨 4 点之间","晚上 11 点到早上 5 点之间"],"h1":"它从晚上 9 点开始。","h2":"青少年学习驾照持有人在晚上 9 点到早上 5 点之间，绝对不能在 New York City 的五个区开车。","p":"对。晚上 9 点到早上 5 点，青少年学习驾照不能在市内开车。"},"vi":{"q":"Ở New York City, người có junior permit (dưới 18 tuổi) không bao giờ được lái xe vào giờ nào?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 10 giờ tối đến 4 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu lúc 9 giờ tối.","h2":"Người có junior permit không bao giờ được lái xe trong năm quận của New York City từ 9 giờ tối đến 5 giờ sáng.","p":"Đúng. Người có junior permit không được lái trong thành phố từ 9 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa New York City, kailan hindi kailanman puwedeng magmaneho ang may junior permit (wala pang 18)?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 10 p.m. hanggang 4 a.m.","Mula 11 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito nang 9 ng gabi.","h2":"Ang may junior permit ay hindi kailanman puwedeng magmaneho sa limang borough ng New York City mula 9 p.m. hanggang 5 a.m.","p":"Tama. Bawal magmaneho ang may junior permit sa lungsod mula 9 p.m. hanggang 5 a.m."},"ar":{"q":"في New York City، متى لا يجوز أبدًا لحامل junior permit (أقل من 18 سنة) أن يقود؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 4 صباحًا","من 11 مساءً إلى 5 صباحًا"],"h1":"يبدأ في الساعة 9 مساءً.","h2":"لا يجوز أبدًا لحامل junior permit أن يقود في الأحياء الخمسة (boroughs) في New York City من 9 مساءً إلى 5 صباحًا.","p":"صحيح. لا قيادة بتصريح junior في المدينة من 9 مساءً إلى 5 صباحًا."},"ref":{"doc":"NY","page":12}},{"id":"ny-012","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York City, what kind of car must a junior permit holder (under 18) use during the day?","o":["Any car with four doors","A car with automatic transmission","A car with dual controls","A car with a backup camera"],"h1":"The supervisor must be able to brake too.","h2":"In New York City a junior permit holder may drive during the day only in a car with dual controls, so the supervisor can brake too.","p":"Right. In the city, the car must have dual controls."},"es":{"q":"En la ciudad de Nueva York, ¿qué tipo de auto debe usar de día quien tiene un permiso juvenil (menor de 18 años)?","o":["Cualquier auto de cuatro puertas","Un auto con transmisión automática","Un auto con doble control","Un auto con cámara de reversa"],"h1":"El supervisor también debe poder frenar.","h2":"En la ciudad de Nueva York, quien tiene un permiso juvenil solo puede manejar de día en un auto con doble control, para que el supervisor también pueda frenar.","p":"Correcto. En la ciudad, el auto debe tener doble control."},"zh":{"q":"在 New York City，青少年学习驾照（junior permit）持有人（未满 18 岁）白天必须用什么样的车？","o":["任何四门车","自动挡的车","有双控制装置（dual controls）的车","有倒车摄像头的车"],"h1":"监督的人也必须能刹车。","h2":"在 New York City，青少年学习驾照持有人白天只能开有双控制装置（dual controls）的车，这样监督的人也能刹车。","p":"对。在市内，车必须有双控制装置。"},"vi":{"q":"Ở New York City, người có junior permit (dưới 18 tuổi) phải dùng loại xe nào vào ban ngày?","o":["Bất kỳ xe nào có bốn cửa","Xe số tự động","Xe có bộ điều khiển kép (dual controls)","Xe có camera lùi"],"h1":"Người giám sát cũng phải có thể đạp thắng.","h2":"Ở New York City, người có junior permit chỉ được lái ban ngày trong xe có bộ điều khiển kép (dual controls), để người giám sát cũng có thể đạp thắng.","p":"Đúng. Trong thành phố, xe phải có bộ điều khiển kép."},"tl":{"q":"Sa New York City, anong uri ng kotse ang dapat gamitin ng may junior permit (wala pang 18) sa araw?","o":["Kahit anong kotse na may apat na pinto","Kotseng automatic ang transmission","Kotseng may dual controls","Kotseng may backup camera"],"h1":"Dapat ay kaya ring magpreno ng supervisor.","h2":"Sa New York City, ang may junior permit ay puwedeng magmaneho sa araw sa kotseng may dual controls lang, para kaya ring magpreno ng supervisor.","p":"Tama. Sa lungsod, dapat may dual controls ang kotse."},"ar":{"q":"في New York City، أي نوع من السيارات يجب أن يستخدمه حامل junior permit (أقل من 18 سنة) أثناء النهار؟","o":["أي سيارة بأربعة أبواب","سيارة بناقل حركة أوتوماتيكي","سيارة بأدوات تحكم مزدوجة (dual controls)","سيارة بكاميرا خلفية"],"h1":"يجب أن يتمكن المشرف أيضًا من الضغط على الفرامل.","h2":"في New York City لا يجوز لحامل junior permit أن يقود في النهار إلا في سيارة بأدوات تحكم مزدوجة (dual controls)، حتى يتمكن المشرف أيضًا من الضغط على الفرامل.","p":"صحيح. في المدينة يجب أن تكون للسيارة أدوات تحكم مزدوجة."},"ref":{"doc":"NY","page":12}},{"id":"ny-013","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, where may a junior license holder never drive?","o":["On Long Island","In New York City","On rural roads","In parking lots"],"h1":"It is the largest city in the state.","h2":"A New York junior license holder may not drive in New York City under any circumstances.","p":"Right. A junior license does not allow driving in New York City."},"es":{"q":"En Nueva York, ¿dónde nunca puede manejar quien tiene licencia juvenil?","o":["En Long Island","En la ciudad de Nueva York","En caminos rurales","En estacionamientos"],"h1":"Es la ciudad más grande del estado.","h2":"En Nueva York, quien tiene licencia juvenil no puede manejar en la ciudad de Nueva York bajo ninguna circunstancia.","p":"Correcto. La licencia juvenil no permite manejar en la ciudad de Nueva York."},"zh":{"q":"在 New York，青少年驾照（junior license）持有人绝对不能在哪里开车？","o":["在 Long Island","在 New York City","在乡村道路上","在停车场"],"h1":"它是这个州最大的城市。","h2":"New York 的青少年驾照持有人在任何情况下都不能在 New York City 开车。","p":"对。青少年驾照不能在 New York City 开车。"},"vi":{"q":"Ở New York, người có bằng lái thiếu niên (junior license) không bao giờ được lái xe ở đâu?","o":["Ở Long Island","Ở New York City","Trên đường nông thôn","Trong bãi đậu xe"],"h1":"Đó là thành phố lớn nhất của tiểu bang.","h2":"Người có junior license ở New York không được lái xe ở New York City trong bất kỳ trường hợp nào.","p":"Đúng. Junior license không cho phép lái xe ở New York City."},"tl":{"q":"Sa New York, saan hindi kailanman puwedeng magmaneho ang may junior license?","o":["Sa Long Island","Sa New York City","Sa mga daan sa probinsya","Sa mga parking lot"],"h1":"Ito ang pinakamalaking lungsod sa estado.","h2":"Ang may junior license sa New York ay hindi puwedeng magmaneho sa New York City sa anumang sitwasyon.","p":"Tama. Hindi pinapayagan ng junior license ang pagmamaneho sa New York City."},"ar":{"q":"في New York، أين لا يجوز أبدًا لحامل رخصة القيادة للصغار (junior license) أن يقود؟","o":["في Long Island","في New York City","على الطرق الريفية","في مواقف السيارات"],"h1":"هي أكبر مدينة في الولاية.","h2":"لا يجوز لحامل junior license في New York أن يقود في New York City في أي حال من الأحوال.","p":"صحيح. رخصة junior لا تسمح بالقيادة في New York City."},"ref":{"doc":"NY","page":16}},{"id":"ny-014","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many passengers under 21 who are not close family may a junior license holder carry without a supervisor?","o":["None at all","No more than two","No more than three","No more than one"],"h1":"It is the smallest number that is not zero.","h2":"A New York junior license holder driving without a supervisor may carry no more than one passenger under 21 who is not an immediate family member.","p":"Right. Only one passenger under 21 who is not family."},"es":{"q":"En Nueva York, ¿cuántos pasajeros menores de 21 años que no son familiares cercanos puede llevar sin supervisor quien tiene licencia juvenil?","o":["Ninguno","No más de dos","No más de tres","No más de uno"],"h1":"Es el número más pequeño que no es cero.","h2":"En Nueva York, quien tiene licencia juvenil y maneja sin supervisor puede llevar no más de un pasajero menor de 21 años que no sea familiar cercano.","p":"Correcto. Solo un pasajero menor de 21 que no sea familiar."},"zh":{"q":"在 New York，没有监督的人时，青少年驾照（junior license）持有人可以载几位不是近亲、未满 21 岁的乘客？","o":["一位也不行","不超过两位","不超过三位","不超过一位"],"h1":"它是不等于零的最小数字。","h2":"New York 的青少年驾照持有人在没有监督的人时，最多只能载一位不是直系亲属、未满 21 岁的乘客。","p":"对。只能载一位不是家人、未满 21 岁的乘客。"},"vi":{"q":"Ở New York, khi không có người giám sát, người có junior license được chở bao nhiêu hành khách dưới 21 tuổi không phải người thân gần?","o":["Không ai cả","Không quá hai người","Không quá ba người","Không quá một người"],"h1":"Đó là số nhỏ nhất mà không phải là số không.","h2":"Người có junior license ở New York, khi lái không có người giám sát, được chở không quá một hành khách dưới 21 tuổi không phải người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa New York, ilang pasahero na wala pang 21 at hindi malapit na kapamilya ang puwedeng isakay ng may junior license kapag walang supervisor?","o":["Wala talaga","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo","Hindi hihigit sa isa"],"h1":"Ito ang pinakamaliit na numero na hindi zero.","h2":"Ang may junior license sa New York na nagmamaneho nang walang supervisor ay puwedeng magsakay ng hindi hihigit sa isang pasahero na wala pang 21 at hindi malapit na kapamilya.","p":"Tama. Isang pasahero lang na wala pang 21 na hindi kapamilya."},"ar":{"q":"في New York، كم راكبًا عمره أقل من 21 وليس من العائلة القريبة يمكن أن يحمل حامل junior license دون مشرف؟","o":["لا أحد على الإطلاق","اثنان على الأكثر","ثلاثة على الأكثر","واحد على الأكثر"],"h1":"هو أصغر عدد ليس صفرًا.","h2":"حامل junior license في New York الذي يقود دون مشرف يمكنه أن يحمل راكبًا واحدًا على الأكثر عمره أقل من 21 وليس من أفراد العائلة المباشرين.","p":"صحيح. راكب واحد فقط عمره أقل من 21 وليس من العائلة."},"ref":{"doc":"NY","page":15}},{"id":"ny-015","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In upstate New York (outside New York City and Long Island), between what hours may a junior license holder not drive alone, except straight between home and work or school?","o":["Between 9 p.m. and 5 a.m.","Between midnight and 6 a.m.","Between 11 p.m. and 5 a.m.","Between 10 p.m. and 6 a.m."],"h1":"It starts at 9 in the evening.","h2":"In upstate New York a junior license holder may not drive alone between 9 p.m. and 5 a.m., except straight between home and work or a school course.","p":"Right. Upstate, no driving alone from 9 p.m. to 5 a.m., except to work or school."},"es":{"q":"En el norte del estado de Nueva York (fuera de la ciudad de Nueva York y de Long Island), ¿en qué horario no puede manejar solo quien tiene licencia juvenil, salvo directo entre la casa y el trabajo o la escuela?","o":["Entre las 9 p.m. y las 5 a.m.","Entre la medianoche y las 6 a.m.","Entre las 11 p.m. y las 5 a.m.","Entre las 10 p.m. y las 6 a.m."],"h1":"Empieza a las 9 de la noche.","h2":"En el norte del estado de Nueva York, quien tiene licencia juvenil no puede manejar solo entre las 9 p.m. y las 5 a.m., salvo directo entre la casa y el trabajo o un curso escolar.","p":"Correcto. En el norte del estado no se maneja solo de 9 p.m. a 5 a.m., salvo al trabajo o la escuela."},"zh":{"q":"在 New York 州北部（New York City 和 Long Island 以外），除了直接往返家和工作或学校，青少年驾照（junior license）持有人在哪个时间段不能自己开车？","o":["晚上 9 点到早上 5 点之间","午夜到早上 6 点之间","晚上 11 点到早上 5 点之间","晚上 10 点到早上 6 点之间"],"h1":"它从晚上 9 点开始。","h2":"在 New York 州北部，青少年驾照持有人在晚上 9 点到早上 5 点之间不能自己开车，除非是直接往返家和工作或学校课程。","p":"对。在州北部，晚上 9 点到早上 5 点不能自己开车，去上班或上学除外。"},"vi":{"q":"Ở vùng upstate New York (ngoài New York City và Long Island), người có junior license không được lái một mình vào giờ nào, trừ khi đi thẳng giữa nhà và nơi làm việc hoặc trường học?","o":["Từ 9 giờ tối đến 5 giờ sáng","Từ nửa đêm đến 6 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 10 giờ tối đến 6 giờ sáng"],"h1":"Bắt đầu lúc 9 giờ tối.","h2":"Ở upstate New York, người có junior license không được lái một mình từ 9 giờ tối đến 5 giờ sáng, trừ khi đi thẳng giữa nhà và nơi làm việc hoặc một khóa học ở trường.","p":"Đúng. Ở upstate, không lái một mình từ 9 giờ tối đến 5 giờ sáng, trừ khi đi làm hoặc đi học."},"tl":{"q":"Sa upstate New York (labas ng New York City at Long Island), sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may junior license, maliban kung diretso sa pagitan ng bahay at trabaho o paaralan?","o":["Mula 9 p.m. hanggang 5 a.m.","Mula hatinggabi hanggang 6 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 10 p.m. hanggang 6 a.m."],"h1":"Nagsisimula ito nang 9 ng gabi.","h2":"Sa upstate New York, ang may junior license ay hindi puwedeng magmaneho nang mag-isa mula 9 p.m. hanggang 5 a.m., maliban kung diretso sa pagitan ng bahay at trabaho o ng isang kurso sa paaralan.","p":"Tama. Sa upstate, bawal magmaneho nang mag-isa mula 9 p.m. hanggang 5 a.m., maliban papunta sa trabaho o paaralan."},"ar":{"q":"في شمال ولاية New York (upstate، خارج New York City وLong Island)، في أي ساعات لا يجوز لحامل junior license أن يقود وحده، إلا مباشرة بين البيت والعمل أو المدرسة؟","o":["من 9 مساءً إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا"],"h1":"يبدأ في الساعة 9 مساءً.","h2":"في upstate New York لا يجوز لحامل junior license أن يقود وحده من 9 مساءً إلى 5 صباحًا، إلا مباشرة بين البيت والعمل أو دورة دراسية.","p":"صحيح. في upstate لا قيادة وحدك من 9 مساءً إلى 5 صباحًا، إلا إلى العمل أو المدرسة."},"ref":{"doc":"NY","page":16}},{"id":"ny-016","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what course must most new drivers complete before the road test?","o":["A 1-hour online video","A 20-hour defensive driving course","A 5-hour pre-licensing course","A first aid course"],"h1":"It is a short classroom course of a few hours.","h2":"Most new drivers in New York must complete a 5-hour pre-licensing course before the road test, unless they finished a high school or college driver education program.","p":"Right. Most new drivers take the 5-hour course."},"es":{"q":"En Nueva York, ¿qué curso deben completar la mayoría de los conductores nuevos antes del examen de manejo?","o":["Un video en línea de 1 hora","Un curso de manejo defensivo de 20 horas","Un curso previo a la licencia de 5 horas","Un curso de primeros auxilios"],"h1":"Es un curso corto de pocas horas en un salón.","h2":"La mayoría de los conductores nuevos en Nueva York deben completar un curso previo a la licencia de 5 horas antes del examen de manejo, salvo que hayan terminado un programa de educación vial en la escuela secundaria o la universidad.","p":"Correcto. La mayoría toma el curso de 5 horas."},"zh":{"q":"在 New York，大多数新司机路考前必须完成什么课程？","o":["1 小时的网上视频","20 小时的防御性驾驶课程","5 小时的驾照前课程（pre-licensing course）","急救课程"],"h1":"它是一个只有几小时的短课堂课程。","h2":"New York 的大多数新司机路考前必须完成 5 小时的驾照前课程（pre-licensing course），除非已经上完高中或大学的驾驶教育课程。","p":"对。大多数新司机要上 5 小时的课程。"},"vi":{"q":"Ở New York, phần lớn người mới lái xe phải hoàn thành khóa học nào trước khi thi lái trên đường?","o":["Một video trên mạng dài 1 giờ","Một khóa lái xe phòng thủ 20 giờ","Một khóa học trước khi cấp bằng (pre-licensing course) 5 giờ","Một khóa sơ cứu"],"h1":"Đó là một khóa học ngắn trong lớp, vài giờ.","h2":"Phần lớn người mới lái xe ở New York phải hoàn thành khóa học trước khi cấp bằng (pre-licensing course) 5 giờ trước khi thi lái trên đường, trừ khi họ đã học xong chương trình giáo dục lái xe ở trường trung học hoặc đại học.","p":"Đúng. Phần lớn người mới lái học khóa 5 giờ."},"tl":{"q":"Sa New York, anong kurso ang dapat tapusin ng karamihan ng bagong driver bago ang road test?","o":["Isang 1 oras na video online","Isang 20 oras na defensive driving course","Isang 5 oras na pre-licensing course","Isang kurso sa first aid"],"h1":"Isa itong maikling kurso sa classroom na ilang oras lang.","h2":"Karamihan ng bagong driver sa New York ay dapat makatapos ng 5 oras na pre-licensing course bago ang road test, maliban kung natapos nila ang driver education program sa high school o kolehiyo.","p":"Tama. Kinukuha ng karamihan ng bagong driver ang 5 oras na kurso."},"ar":{"q":"في New York، ما الدورة التي يجب أن يكملها معظم السائقين الجدد قبل اختبار القيادة على الطريق؟","o":["فيديو على الإنترنت مدته ساعة واحدة","دورة قيادة دفاعية مدتها 20 ساعة","دورة ما قبل الترخيص (pre-licensing course) مدتها 5 ساعات","دورة إسعافات أولية"],"h1":"هي دورة قصيرة في الصف مدتها بضع ساعات.","h2":"يجب أن يكمل معظم السائقين الجدد في New York دورة ما قبل الترخيص (pre-licensing course) مدتها 5 ساعات قبل اختبار القيادة على الطريق، إلا إذا أنهوا برنامج تعليم القيادة في المدرسة الثانوية أو الكلية.","p":"صحيح. معظم السائقين الجدد يأخذون الدورة ذات الخمس ساعات."},"ref":{"doc":"NY","page":8}},{"id":"ny-017","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, a school bus with flashing red lights is stopped on the other side of a divided highway. What must you do?","o":["Keep driving, because the highway is divided","Stop, even though you are on the other side","Slow down to 20 mph and pass","Honk and pass with care"],"h1":"In New York this rule has no exception for divided highways.","h2":"In New York you must stop for a school bus with flashing red lights even when it is on the other side of a divided highway.","p":"Right. In New York, traffic on both sides stops."},"es":{"q":"En Nueva York, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una carretera dividida. ¿Qué debe hacer?","o":["Seguir manejando, porque la carretera está dividida","Detenerse, aunque usted esté del otro lado","Bajar a 20 mph y pasar","Tocar la bocina y pasar con cuidado"],"h1":"En Nueva York esta regla no tiene excepción para carreteras divididas.","h2":"En Nueva York usted debe detenerse ante un autobús escolar con luces rojas intermitentes aunque esté al otro lado de una carretera dividida.","p":"Correcto. En Nueva York se detiene el tráfico de los dos lados."},"zh":{"q":"在 New York，一辆闪着红灯的校车停在分隔公路的另一边。你必须怎么做？","o":["继续开，因为公路有分隔","停车，就算你在另一边","减速到 20 mph 然后经过","按喇叭然后小心经过"],"h1":"在 New York，这条规定对分隔公路没有例外。","h2":"在 New York，就算闪着红灯的校车在分隔公路的另一边，你也必须停车。","p":"对。在 New York，两边的车都要停。"},"vi":{"q":"Ở New York, một xe buýt trường học đang bật đèn đỏ nhấp nháy dừng ở phía bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Tiếp tục lái, vì xa lộ có dải phân cách","Dừng lại, dù bạn ở phía bên kia","Giảm tốc xuống 20 mph rồi chạy qua","Bấm còi và chạy qua cẩn thận"],"h1":"Ở New York, luật này không có ngoại lệ cho xa lộ có dải phân cách.","h2":"Ở New York, bạn phải dừng lại khi có xe buýt trường học bật đèn đỏ nhấp nháy, ngay cả khi nó ở phía bên kia của xa lộ có dải phân cách.","p":"Đúng. Ở New York, xe cả hai chiều đều phải dừng."},"tl":{"q":"Sa New York, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang panig ng divided highway. Ano ang dapat mong gawin?","o":["Tuloy lang sa pagmamaneho, dahil divided ang highway","Huminto, kahit nasa kabilang panig ka","Bagalan hanggang 20 mph at lumampas","Bumusina at lumampas nang maingat"],"h1":"Sa New York, walang exception ang patakarang ito para sa divided highway.","h2":"Sa New York, dapat kang huminto para sa school bus na may kumikislap na pulang ilaw kahit nasa kabilang panig ito ng divided highway.","p":"Tama. Sa New York, humihinto ang trapiko sa magkabilang panig."},"ar":{"q":"في New York، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع مقسوم بفاصل. ماذا يجب أن تفعل؟","o":["تستمر في القيادة لأن الطريق مقسوم","تتوقف، حتى لو كنت على الجانب الآخر","تخفّف السرعة إلى 20 mph وتتجاوز","تضغط على البوق وتتجاوز بحذر"],"h1":"في New York لا يوجد استثناء في هذه القاعدة للطرق المقسومة.","h2":"في New York يجب أن تتوقف للحافلة المدرسية ذات الأضواء الحمراء الوامضة حتى لو كانت على الجانب الآخر من طريق سريع مقسوم.","p":"صحيح. في New York تتوقف السيارات في الاتجاهين."},"ref":{"doc":"NY","page":40}},{"id":"ny-018","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, how far from a stopped school bus with flashing red lights should you stop?","o":["At least 5 feet","At least 10 feet","Right next to the bus","At least 20 feet"],"h1":"It is a bit more than the length of a car.","h2":"In New York you should stop at least 20 feet away from a school bus with flashing red lights.","p":"Right. Stay at least 20 feet back."},"es":{"q":"En Nueva York, ¿a qué distancia de un autobús escolar detenido con luces rojas intermitentes debe detenerse?","o":["Por lo menos a 5 pies","Por lo menos a 10 pies","Justo al lado del autobús","Por lo menos a 20 pies"],"h1":"Es un poco más que el largo de un auto.","h2":"En Nueva York usted debe detenerse por lo menos a 20 pies de un autobús escolar con luces rojas intermitentes.","p":"Correcto. Quédese por lo menos a 20 pies."},"zh":{"q":"在 New York，你应该停在离闪着红灯的校车多远的地方？","o":["至少 5 英尺","至少 10 英尺","就在校车旁边","至少 20 英尺"],"h1":"它比一辆车的长度多一点。","h2":"在 New York，你应该停在离闪着红灯的校车至少 20 英尺的地方。","p":"对。离开至少 20 英尺。"},"vi":{"q":"Ở New York, bạn nên dừng cách xe buýt trường học đang dừng và bật đèn đỏ nhấp nháy bao xa?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ngay sát bên xe buýt","Ít nhất 20 feet"],"h1":"Dài hơn chiều dài một chiếc xe hơi một chút.","h2":"Ở New York, bạn nên dừng cách xe buýt trường học đang bật đèn đỏ nhấp nháy ít nhất 20 feet.","p":"Đúng. Dừng cách xa ít nhất 20 feet."},"tl":{"q":"Sa New York, gaano kalayo ka dapat huminto mula sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Mismong katabi ng bus","Hindi bababa sa 20 feet"],"h1":"Medyo mas mahaba ito sa haba ng isang kotse.","h2":"Sa New York, dapat kang huminto nang hindi bababa sa 20 feet ang layo mula sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Manatili nang hindi bababa sa 20 feet ang layo."},"ar":{"q":"في New York، على أي مسافة يجب أن تتوقف من حافلة مدرسية متوقفة وأضواؤها الحمراء تومض؟","o":["5 أقدام (feet) على الأقل","10 أقدام (feet) على الأقل","بجانب الحافلة مباشرة","20 قدمًا (feet) على الأقل"],"h1":"هي أطول قليلًا من طول سيارة.","h2":"في New York يجب أن تتوقف على بعد 20 قدمًا (feet) على الأقل من الحافلة المدرسية ذات الأضواء الحمراء الوامضة.","p":"صحيح. ابقَ على بعد 20 قدمًا على الأقل."},"ref":{"doc":"NY","page":40}},{"id":"ny-019","scope":"NY","cat":"signals","sign":null,"c":2,"en":{"q":"In New York City, may you turn right on a red light after a full stop?","o":["Yes, always after a full stop","Yes, but only at night","No, unless a sign says it is allowed","Yes, if no police officer is present"],"h1":"The city has the opposite rule from the rest of the state.","h2":"In New York City you may not turn right on a red light unless a sign says it is allowed.","p":"Right. No turn on red in the city without a sign."},"es":{"q":"En la ciudad de Nueva York, ¿puede dar vuelta a la derecha con la luz roja después de detenerse por completo?","o":["Sí, siempre después de detenerse","Sí, pero solo de noche","No, salvo que una señal lo permita","Sí, si no hay un policía"],"h1":"La ciudad tiene la regla contraria al resto del estado.","h2":"En la ciudad de Nueva York no puede dar vuelta a la derecha con la luz roja, salvo que una señal lo permita.","p":"Correcto. En la ciudad no se da vuelta con la luz roja sin una señal."},"zh":{"q":"在 New York City，红灯时完全停车以后可以右转吗？","o":["可以，完全停车以后都可以","可以，但只在晚上","不可以，除非有标志说允许","可以，如果没有警察"],"h1":"这个城市的规定和州里其他地方相反。","h2":"在 New York City，红灯时不能右转，除非有标志说允许。","p":"对。在市内，没有标志就不能红灯右转。"},"vi":{"q":"Ở New York City, bạn có được quẹo phải khi đèn đỏ sau khi đã dừng hẳn không?","o":["Có, luôn được sau khi dừng hẳn","Có, nhưng chỉ vào ban đêm","Không, trừ khi có biển báo cho phép","Có, nếu không có cảnh sát"],"h1":"Thành phố có luật ngược lại với phần còn lại của tiểu bang.","h2":"Ở New York City, bạn không được quẹo phải khi đèn đỏ, trừ khi có biển báo cho phép.","p":"Đúng. Trong thành phố không được quẹo khi đèn đỏ nếu không có biển báo."},"tl":{"q":"Sa New York City, puwede ka bang kumanan sa pulang ilaw pagkatapos ng buong paghinto?","o":["Oo, palagi pagkatapos ng buong paghinto","Oo, pero sa gabi lang","Hindi, maliban kung may sign na nagsasabing pinapayagan ito","Oo, kung walang pulis"],"h1":"Kabaligtaran ang patakaran ng lungsod sa ibang bahagi ng estado.","h2":"Sa New York City, hindi ka puwedeng kumanan sa pulang ilaw maliban kung may sign na nagsasabing pinapayagan ito.","p":"Tama. Bawal kumanan sa pula sa lungsod kung walang sign."},"ar":{"q":"في New York City، هل يجوز لك الانعطاف يمينًا عند الإشارة الحمراء بعد التوقف التام؟","o":["نعم، دائمًا بعد التوقف التام","نعم، لكن في الليل فقط","لا، إلا إذا كانت هناك لافتة تسمح بذلك","نعم، إذا لم يكن هناك شرطي"],"h1":"المدينة لها قاعدة عكس باقي الولاية.","h2":"في New York City لا يجوز لك الانعطاف يمينًا عند الإشارة الحمراء إلا إذا كانت هناك لافتة تسمح بذلك.","p":"صحيح. لا انعطاف عند الأحمر في المدينة بدون لافتة."},"ref":{"doc":"NY","page":31}},{"id":"ny-020","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, when must you turn on your headlights during the day?","o":["Whenever the weather makes you use your windshield wipers","Only inside tunnels","Only on highways","Never during the day"],"h1":"Think about rain, snow, sleet or fog.","h2":"New York law says you must turn on your headlights whenever the weather makes you use your windshield wipers, and daytime running lights do not count.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Nueva York, ¿cuándo debe encender los faros durante el día?","o":["Siempre que el clima le obligue a usar los limpiaparabrisas","Solo dentro de los túneles","Solo en las autopistas","Nunca durante el día"],"h1":"Piense en lluvia, nieve, aguanieve o niebla.","h2":"La ley de Nueva York dice que debe encender los faros siempre que el clima le obligue a usar los limpiaparabrisas, y las luces de circulación diurna no cuentan.","p":"Correcto. Si usa los limpiaparabrisas, encienda los faros."},"zh":{"q":"在 New York，白天什么时候必须开大灯？","o":["天气让你需要用雨刷的时候","只在隧道里","只在高速公路上","白天从来不用"],"h1":"想想下雨、下雪、冻雨或有雾。","h2":"New York 法律规定，天气让你需要用雨刷时，你必须开大灯，日间行车灯不算。","p":"对。开雨刷，就开大灯。"},"vi":{"q":"Ở New York, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước kính chắn gió","Chỉ trong đường hầm","Chỉ trên xa lộ","Không bao giờ vào ban ngày"],"h1":"Hãy nghĩ đến mưa, tuyết, mưa tuyết hoặc sương mù.","h2":"Luật New York nói bạn phải bật đèn pha bất cứ khi nào thời tiết khiến bạn phải dùng cần gạt nước, và đèn chạy ban ngày (daytime running lights) không được tính.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa New York, kailan mo dapat buksan ang headlights sa araw?","o":["Tuwing pinapagamit ka ng panahon ng windshield wipers","Sa loob lang ng tunnel","Sa highway lang","Hindi kailanman sa araw"],"h1":"Isipin ang ulan, niyebe, sleet o fog.","h2":"Sinasabi ng batas ng New York na dapat mong buksan ang headlights tuwing pinapagamit ka ng panahon ng windshield wipers, at hindi binibilang ang daytime running lights.","p":"Tama. Bukas ang wipers, bukas ang headlights."},"ar":{"q":"في New York، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["كلما جعلك الطقس تستخدم مسّاحات الزجاج الأمامي","داخل الأنفاق فقط","على الطرق السريعة فقط","أبدًا أثناء النهار"],"h1":"فكّر في المطر أو الثلج أو المطر المتجمد أو الضباب.","h2":"يقول قانون New York إنه يجب أن تشغّل المصابيح الأمامية كلما جعلك الطقس تستخدم مسّاحات الزجاج الأمامي، وأضواء النهار (daytime running lights) لا تُحسب.","p":"صحيح. المسّاحات تعمل، المصابيح تعمل."},"ref":{"doc":"NY","page":63}},{"id":"ny-021","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York State, outside New York City, what is the speed limit when no limit is posted?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"It is the same number used on many expressways in the state.","h2":"In New York State, when no speed limit is posted, you may not drive faster than 55 mph.","p":"Right. With no sign, the limit is 55 mph."},"es":{"q":"En el estado de Nueva York, fuera de la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay uno indicado?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Es el mismo número de muchas autopistas del estado.","h2":"En el estado de Nueva York, cuando no hay un límite indicado, no puede manejar a más de 55 mph.","p":"Correcto. Sin señal, el límite es 55 mph."},"zh":{"q":"在 New York 州，New York City 以外，没有标示限速时，限速是多少？","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"这个州很多快速路也用这个数字。","h2":"在 New York 州，没有标示限速时，你开车不能超过 55 mph。","p":"对。没有标志时，限速是 55 mph。"},"vi":{"q":"Ở tiểu bang New York, ngoài New York City, giới hạn tốc độ là bao nhiêu khi không có biển báo tốc độ?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Đó là cùng con số dùng trên nhiều đường cao tốc trong tiểu bang.","h2":"Ở tiểu bang New York, khi không có biển báo giới hạn tốc độ, bạn không được lái nhanh hơn 55 mph.","p":"Đúng. Không có biển báo thì giới hạn là 55 mph."},"tl":{"q":"Sa New York State, labas ng New York City, ano ang speed limit kapag walang nakapaskil na limit?","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"Ito ang parehong numero na ginagamit sa maraming expressway sa estado.","h2":"Sa New York State, kapag walang nakapaskil na speed limit, hindi ka puwedeng magmaneho nang mas mabilis sa 55 mph.","p":"Tama. Kung walang sign, 55 mph ang limit."},"ar":{"q":"في ولاية New York، خارج New York City، ما حدّ السرعة عندما لا توجد لافتة حدّ سرعة؟","o":["45 mph","60 mph","65 mph","55 mph"],"h1":"هو نفس الرقم المستخدم على كثير من الطرق السريعة في الولاية.","h2":"في ولاية New York، عندما لا توجد لافتة حدّ سرعة، لا يجوز أن تقود أسرع من 55 mph.","p":"صحيح. بدون لافتة، الحدّ هو 55 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-022","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York City, what is the speed limit when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is lower than the 30 mph used in many towns.","h2":"In New York City the speed limit is 25 mph unless a sign shows a different limit.","p":"Right. The city default is 25 mph."},"es":{"q":"En la ciudad de Nueva York, ¿cuál es el límite de velocidad cuando no hay otro indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es más bajo que las 30 mph de muchos pueblos.","h2":"En la ciudad de Nueva York el límite de velocidad es 25 mph, salvo que una señal indique otro límite.","p":"Correcto. En la ciudad, el límite general es 25 mph."},"zh":{"q":"在 New York City，没有标示其他限速时，限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比很多城镇用的 30 mph 低。","h2":"在 New York City，除非标志显示不同的限速，限速是 25 mph。","p":"对。市内默认限速是 25 mph。"},"vi":{"q":"Ở New York City, giới hạn tốc độ là bao nhiêu khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó thấp hơn mức 30 mph dùng ở nhiều thị trấn.","h2":"Ở New York City, giới hạn tốc độ là 25 mph trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. Giới hạn mặc định trong thành phố là 25 mph."},"tl":{"q":"Sa New York City, ano ang speed limit kapag walang ibang nakapaskil na limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Mas mababa ito sa 30 mph na ginagamit sa maraming bayan.","h2":"Sa New York City, 25 mph ang speed limit maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. 25 mph ang default sa lungsod."},"ar":{"q":"في New York City، ما حدّ السرعة عندما لا توجد لافتة بحدّ آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أقل من 30 mph المستخدم في بلدات كثيرة.","h2":"في New York City حدّ السرعة هو 25 mph إلا إذا أظهرت لافتة حدًّا مختلفًا.","p":"صحيح. الحدّ العادي في المدينة 25 mph."},"ref":{"doc":"NY","page":47}},{"id":"ny-023","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, on a parkway or expressway, the Move Over law also covers which stopped vehicles?","o":["Only police cars","Only ambulances and fire trucks","Any vehicle stopped on the shoulder or in the road","Only tow trucks"],"h1":"It is not only emergency vehicles.","h2":"On a New York parkway or expressway, the Move Over law covers any vehicle stopped on the shoulder or in the road, so you slow down and move over when it is safe.","p":"Right. On those roads it covers every stopped vehicle."},"es":{"q":"En Nueva York, en una autopista o parkway, ¿qué vehículos detenidos también cubre la ley de cambiar de carril (Move Over)?","o":["Solo las patrullas de policía","Solo las ambulancias y los camiones de bomberos","Cualquier vehículo detenido en el acotamiento o en el camino","Solo las grúas"],"h1":"No son solo los vehículos de emergencia.","h2":"En una autopista o parkway de Nueva York, la ley de cambiar de carril cubre cualquier vehículo detenido en el acotamiento o en el camino, así que usted baja la velocidad y se cambia de carril cuando sea seguro.","p":"Correcto. En esas vías cubre a todo vehículo detenido."},"zh":{"q":"在 New York，在景观大道（parkway）或快速路（expressway）上，让道变道法（Move Over law）还包括哪些停着的车？","o":["只有警车","只有救护车和消防车","任何停在路肩或路上的车","只有拖车"],"h1":"不只是紧急车辆。","h2":"在 New York 的景观大道或快速路上，让道变道法（Move Over law）包括任何停在路肩或路上的车，所以在安全时你要减速并换车道让开。","p":"对。在这些路上，所有停着的车都包括在内。"},"vi":{"q":"Ở New York, trên parkway hoặc expressway, luật Tránh Sang Làn Khác (Move Over law) còn áp dụng cho những xe nào đang dừng?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Bất kỳ xe nào dừng trên lề đường hoặc trên đường","Chỉ xe kéo"],"h1":"Không chỉ là xe khẩn cấp.","h2":"Trên parkway hoặc expressway ở New York, luật Move Over áp dụng cho bất kỳ xe nào dừng trên lề đường hoặc trên đường, nên bạn giảm tốc và chuyển làn khi an toàn.","p":"Đúng. Trên những con đường đó, luật áp dụng cho mọi xe đang dừng."},"tl":{"q":"Sa New York, sa parkway o expressway, aling mga nakahintong sasakyan ang sakop din ng Move Over law?","o":["Mga sasakyan ng pulis lang","Mga ambulansya at fire truck lang","Kahit anong sasakyang nakahinto sa shoulder o sa daan","Mga tow truck lang"],"h1":"Hindi lang ito mga emergency vehicle.","h2":"Sa parkway o expressway sa New York, sakop ng Move Over law ang kahit anong sasakyang nakahinto sa shoulder o sa daan, kaya magbagal ka at lumipat ng lane kapag ligtas.","p":"Tama. Sa mga daang iyon, sakop nito ang bawat nakahintong sasakyan."},"ar":{"q":"في New York، على طريق parkway أو expressway، أي مركبات متوقفة يشملها أيضًا قانون الابتعاد (Move Over law)؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","أي مركبة متوقفة على كتف الطريق أو في الطريق","سيارات السحب فقط"],"h1":"ليست مركبات الطوارئ فقط.","h2":"على طريق parkway أو expressway في New York، يشمل قانون Move Over أي مركبة متوقفة على كتف الطريق أو في الطريق، لذلك تخفّف السرعة وتنتقل إلى مسار آخر عندما يكون ذلك آمنًا.","p":"صحيح. على تلك الطرق يشمل كل مركبة متوقفة."},"ref":{"doc":"NY","page":35}},{"id":"ny-024","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, what blood alcohol level breaks the Zero Tolerance law for a driver under 21?","o":["0.02 to 0.07 percent","0.08 percent or more","Only 0.10 percent or more","Any level is legal under 21 with a permit"],"h1":"It starts at the smallest amount a test can reliably measure.","h2":"In New York a driver under 21 breaks the Zero Tolerance law with a blood alcohol level from 0.02 to 0.07 percent, and a higher level is a criminal charge.","p":"Right. Zero Tolerance covers 0.02 to 0.07 percent."},"es":{"q":"En Nueva York, ¿qué nivel de alcohol en la sangre viola la ley de Tolerancia Cero para un conductor menor de 21 años?","o":["De 0.02 a 0.07 por ciento","0.08 por ciento o más","Solo 0.10 por ciento o más","Con permiso, cualquier nivel es legal para menores de 21"],"h1":"Empieza en la cantidad más pequeña que una prueba puede medir con seguridad.","h2":"En Nueva York, un conductor menor de 21 años viola la ley de Tolerancia Cero con un nivel de alcohol en la sangre de 0.02 a 0.07 por ciento, y un nivel más alto es un delito.","p":"Correcto. Tolerancia Cero cubre de 0.02 a 0.07 por ciento."},"zh":{"q":"在 New York，未满 21 岁的司机血液酒精浓度到多少就违反零容忍法（Zero Tolerance law）？","o":["0.02% 到 0.07%","0.08% 或以上","只有 0.10% 或以上","未满 21 岁、有学习驾照，任何浓度都合法"],"h1":"它从测试能可靠测出的最小量开始。","h2":"在 New York，未满 21 岁的司机血液酒精浓度在 0.02% 到 0.07% 就违反零容忍法（Zero Tolerance law），更高的浓度是刑事指控。","p":"对。零容忍法包括 0.02% 到 0.07%。"},"vi":{"q":"Ở New York, nồng độ cồn trong máu bao nhiêu thì vi phạm luật Không Dung Thứ (Zero Tolerance law) đối với người lái dưới 21 tuổi?","o":["0.02 đến 0.07 phần trăm","0.08 phần trăm trở lên","Chỉ từ 0.10 phần trăm trở lên","Dưới 21 tuổi có giấy phép thì mức nào cũng hợp pháp"],"h1":"Bắt đầu từ lượng nhỏ nhất mà máy đo có thể đo chính xác.","h2":"Ở New York, người lái dưới 21 tuổi vi phạm luật Zero Tolerance khi nồng độ cồn trong máu từ 0.02 đến 0.07 phần trăm, và mức cao hơn là tội hình sự.","p":"Đúng. Zero Tolerance áp dụng từ 0.02 đến 0.07 phần trăm."},"tl":{"q":"Sa New York, anong blood alcohol level ang lumalabag sa Zero Tolerance law para sa driver na wala pang 21?","o":["0.02 hanggang 0.07 porsyento","0.08 porsyento o higit pa","0.10 porsyento o higit pa lang","Legal ang kahit anong level kung wala pang 21 at may permit"],"h1":"Nagsisimula ito sa pinakamaliit na dami na maaasahang masukat ng test.","h2":"Sa New York, lumalabag sa Zero Tolerance law ang driver na wala pang 21 kapag ang blood alcohol level ay mula 0.02 hanggang 0.07 porsyento, at ang mas mataas na level ay isang kasong kriminal.","p":"Tama. Sakop ng Zero Tolerance ang 0.02 hanggang 0.07 porsyento."},"ar":{"q":"في New York، أي نسبة كحول في الدم تخالف قانون عدم التسامح (Zero Tolerance law) لسائق عمره أقل من 21؟","o":["من 0.02 إلى 0.07 بالمئة","0.08 بالمئة أو أكثر","0.10 بالمئة أو أكثر فقط","أي نسبة قانونية تحت 21 مع تصريح"],"h1":"تبدأ من أصغر كمية يمكن للاختبار قياسها بدقة.","h2":"في New York يخالف السائق الذي عمره أقل من 21 قانون Zero Tolerance إذا كانت نسبة الكحول في دمه من 0.02 إلى 0.07 بالمئة، والنسبة الأعلى تُعدّ تهمة جنائية.","p":"صحيح. Zero Tolerance يشمل من 0.02 إلى 0.07 بالمئة."},"ref":{"doc":"NY","page":57}},{"id":"ny-025","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, what happens after a first Zero Tolerance violation by a driver under 21?","o":["Only a written warning","A 30-day suspension","A fine with no suspension","The license is suspended for six months"],"h1":"It is half a year without a license.","h2":"After a first Zero Tolerance violation in New York, the driver under 21 has the license suspended for six months.","p":"Right. A first violation means a six-month suspension."},"es":{"q":"En Nueva York, ¿qué pasa después de una primera violación de Tolerancia Cero de un conductor menor de 21 años?","o":["Solo una advertencia por escrito","Una suspensión de 30 días","Una multa sin suspensión","Le suspenden la licencia por seis meses"],"h1":"Es medio año sin licencia.","h2":"Después de una primera violación de Tolerancia Cero en Nueva York, al conductor menor de 21 años le suspenden la licencia por seis meses.","p":"Correcto. La primera violación trae una suspensión de seis meses."},"zh":{"q":"在 New York，未满 21 岁的司机第一次违反零容忍法（Zero Tolerance）以后会怎么样？","o":["只有书面警告","暂停 30 天","只罚款，不暂停","驾照被暂停六个月"],"h1":"它是半年没有驾照。","h2":"在 New York，未满 21 岁的司机第一次违反零容忍法以后，驾照会被暂停六个月。","p":"对。第一次违反，暂停六个月。"},"vi":{"q":"Ở New York, điều gì xảy ra sau lần vi phạm Zero Tolerance đầu tiên của người lái dưới 21 tuổi?","o":["Chỉ một lời cảnh cáo bằng văn bản","Bị treo bằng 30 ngày","Bị phạt tiền mà không bị treo bằng","Bằng lái bị treo sáu tháng"],"h1":"Đó là nửa năm không có bằng lái.","h2":"Sau lần vi phạm Zero Tolerance đầu tiên ở New York, người lái dưới 21 tuổi bị treo bằng lái sáu tháng.","p":"Đúng. Lần vi phạm đầu tiên bị treo bằng sáu tháng."},"tl":{"q":"Sa New York, ano ang mangyayari pagkatapos ng unang Zero Tolerance violation ng driver na wala pang 21?","o":["Nakasulat na babala lang","30 araw na suspension","Multa na walang suspension","Masususpinde ang lisensya nang anim na buwan"],"h1":"Kalahating taon ito na walang lisensya.","h2":"Pagkatapos ng unang Zero Tolerance violation sa New York, masususpinde nang anim na buwan ang lisensya ng driver na wala pang 21.","p":"Tama. Ang unang violation ay anim na buwang suspension."},"ar":{"q":"في New York، ماذا يحدث بعد أول مخالفة لقانون Zero Tolerance لسائق عمره أقل من 21؟","o":["إنذار مكتوب فقط","إيقاف لمدة 30 يومًا","غرامة بدون إيقاف","إيقاف الرخصة لمدة ستة أشهر"],"h1":"هي نصف سنة بدون رخصة.","h2":"بعد أول مخالفة لقانون Zero Tolerance في New York، تُوقف رخصة السائق الذي عمره أقل من 21 لمدة ستة أشهر.","p":"صحيح. أول مخالفة تعني إيقافًا لمدة ستة أشهر."},"ref":{"doc":"NY","page":57}},{"id":"ny-026","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, Driving While Ability Impaired by alcohol (DWAI) starts at what blood alcohol level?","o":["More than 0.01 percent","More than 0.05 percent","More than 0.08 percent","More than 0.10 percent"],"h1":"It is below the 0.08 level for Driving While Intoxicated.","h2":"In New York, Driving While Ability Impaired by alcohol starts at a blood alcohol level of more than 0.05 percent, below the 0.08 percent level for Driving While Intoxicated.","p":"Right. DWAI starts above 0.05 percent."},"es":{"q":"En Nueva York, ¿a partir de qué nivel de alcohol en la sangre se considera manejar con la capacidad disminuida por alcohol (DWAI)?","o":["Más de 0.01 por ciento","Más de 0.05 por ciento","Más de 0.08 por ciento","Más de 0.10 por ciento"],"h1":"Está por debajo del nivel de 0.08 de manejar en estado de ebriedad.","h2":"En Nueva York, manejar con la capacidad disminuida por alcohol empieza con un nivel de alcohol en la sangre de más de 0.05 por ciento, por debajo del 0.08 por ciento de manejar en estado de ebriedad.","p":"Correcto. DWAI empieza con más de 0.05 por ciento."},"zh":{"q":"在 New York，酒精导致驾驶能力受损（DWAI）从血液酒精浓度多少开始？","o":["超过 0.01%","超过 0.05%","超过 0.08%","超过 0.10%"],"h1":"它低于醉酒驾驶（Driving While Intoxicated）的 0.08。","h2":"在 New York，酒精导致驾驶能力受损（DWAI）从血液酒精浓度超过 0.05% 开始，低于醉酒驾驶的 0.08%。","p":"对。DWAI 从超过 0.05% 开始。"},"vi":{"q":"Ở New York, tội Lái Xe Khi Bị Rượu Làm Giảm Khả Năng (Driving While Ability Impaired, DWAI) bắt đầu từ nồng độ cồn trong máu bao nhiêu?","o":["Hơn 0.01 phần trăm","Hơn 0.05 phần trăm","Hơn 0.08 phần trăm","Hơn 0.10 phần trăm"],"h1":"Nó thấp hơn mức 0.08 của tội Lái Xe Khi Say Rượu (Driving While Intoxicated).","h2":"Ở New York, tội Lái Xe Khi Bị Rượu Làm Giảm Khả Năng (DWAI) bắt đầu khi nồng độ cồn trong máu hơn 0.05 phần trăm, thấp hơn mức 0.08 phần trăm của tội Lái Xe Khi Say Rượu (Driving While Intoxicated).","p":"Đúng. DWAI bắt đầu từ trên 0.05 phần trăm."},"tl":{"q":"Sa New York, sa anong blood alcohol level nagsisimula ang Driving While Ability Impaired by alcohol (DWAI)?","o":["Higit sa 0.01 porsyento","Higit sa 0.05 porsyento","Higit sa 0.08 porsyento","Higit sa 0.10 porsyento"],"h1":"Mas mababa ito sa 0.08 level para sa Driving While Intoxicated.","h2":"Sa New York, nagsisimula ang Driving While Ability Impaired by alcohol (DWAI) sa blood alcohol level na higit sa 0.05 porsyento, mas mababa sa 0.08 porsyento na level para sa Driving While Intoxicated.","p":"Tama. Nagsisimula ang DWAI sa higit sa 0.05 porsyento."},"ar":{"q":"في New York، من أي نسبة كحول في الدم تبدأ مخالفة القيادة مع ضعف القدرة بسبب الكحول (Driving While Ability Impaired, DWAI)؟","o":["أكثر من 0.01 بالمئة","أكثر من 0.05 بالمئة","أكثر من 0.08 بالمئة","أكثر من 0.10 بالمئة"],"h1":"هي أقل من نسبة 0.08 الخاصة بالقيادة في حالة سُكر (Driving While Intoxicated).","h2":"في New York تبدأ مخالفة القيادة مع ضعف القدرة بسبب الكحول (DWAI) عند نسبة كحول في الدم أكثر من 0.05 بالمئة، وهي أقل من نسبة 0.08 بالمئة الخاصة بالقيادة في حالة سُكر (Driving While Intoxicated).","p":"صحيح. DWAI يبدأ فوق 0.05 بالمئة."},"ref":{"doc":"NY","page":58}},{"id":"ny-027","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, what happens to a junior permit or license holder after a first conviction for using a phone or texting while driving?","o":["A warning letter only","A 30-day suspension","The permit or license is suspended for 120 days","Points only, with no suspension"],"h1":"It is about four months.","h2":"In New York, a first phone or texting conviction suspends a junior permit or license for 120 days.","p":"Right. A first conviction means a 120-day suspension."},"es":{"q":"En Nueva York, ¿qué le pasa a quien tiene permiso o licencia juvenil después de una primera condena por usar el teléfono o enviar mensajes mientras maneja?","o":["Solo una carta de advertencia","Una suspensión de 30 días","Le suspenden el permiso o la licencia por 120 días","Solo puntos, sin suspensión"],"h1":"Son unos cuatro meses.","h2":"En Nueva York, una primera condena por usar el teléfono o enviar mensajes suspende el permiso o la licencia juvenil por 120 días.","p":"Correcto. La primera condena trae una suspensión de 120 días."},"zh":{"q":"在 New York，青少年学习驾照或青少年驾照持有人第一次因为开车时用手机或发短信被定罪，会怎么样？","o":["只有警告信","暂停 30 天","学习驾照或驾照被暂停 120 天","只扣分，不暂停"],"h1":"它大约是四个月。","h2":"在 New York，第一次因为用手机或发短信被定罪，青少年学习驾照或驾照会被暂停 120 天。","p":"对。第一次定罪，暂停 120 天。"},"vi":{"q":"Ở New York, điều gì xảy ra với người có junior permit hoặc junior license sau lần đầu bị kết tội dùng điện thoại hoặc nhắn tin khi lái xe?","o":["Chỉ một lá thư cảnh cáo","Bị treo 30 ngày","Giấy phép hoặc bằng lái bị treo 120 ngày","Chỉ bị trừ điểm, không bị treo"],"h1":"Khoảng bốn tháng.","h2":"Ở New York, lần đầu bị kết tội dùng điện thoại hoặc nhắn tin khi lái xe sẽ làm junior permit hoặc junior license bị treo 120 ngày.","p":"Đúng. Lần đầu bị kết tội là bị treo 120 ngày."},"tl":{"q":"Sa New York, ano ang mangyayari sa may junior permit o junior license pagkatapos ng unang conviction sa paggamit ng phone o pag-text habang nagmamaneho?","o":["Sulat ng babala lang","30 araw na suspension","Masususpinde ang permit o lisensya nang 120 araw","Points lang, walang suspension"],"h1":"Mga apat na buwan ito.","h2":"Sa New York, ang unang conviction sa paggamit ng phone o pag-text ay magsususpinde sa junior permit o lisensya nang 120 araw.","p":"Tama. Ang unang conviction ay 120 araw na suspension."},"ar":{"q":"في New York، ماذا يحدث لحامل junior permit أو junior license بعد أول إدانة باستخدام الهاتف أو إرسال الرسائل أثناء القيادة؟","o":["رسالة إنذار فقط","إيقاف لمدة 30 يومًا","إيقاف التصريح أو الرخصة لمدة 120 يومًا","نقاط فقط، بدون إيقاف"],"h1":"هي حوالي أربعة أشهر.","h2":"في New York، أول إدانة باستخدام الهاتف أو إرسال الرسائل أثناء القيادة توقف junior permit أو الرخصة لمدة 120 يومًا.","p":"صحيح. أول إدانة تعني إيقافًا لمدة 120 يومًا."},"ref":{"doc":"NY","page":19}},{"id":"ny-028","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, what vision do you need to pass the DMV vision test, with or without glasses?","o":["20/20 in both eyes","20/40 in at least one eye","20/60 in both eyes","20/100 in at least one eye"],"h1":"Only one eye has to meet the standard.","h2":"In New York you need 20/40 vision in at least one eye, with or without glasses or contacts, to pass the vision test.","p":"Right. You need 20/40 in at least one eye."},"es":{"q":"En Nueva York, ¿qué visión necesita para pasar el examen de la vista del DMV, con o sin lentes?","o":["20/20 en ambos ojos","20/40 en por lo menos un ojo","20/60 en ambos ojos","20/100 en por lo menos un ojo"],"h1":"Solo un ojo tiene que cumplir el requisito.","h2":"En Nueva York usted necesita una visión de 20/40 en por lo menos un ojo, con o sin lentes o lentes de contacto, para pasar el examen de la vista.","p":"Correcto. Necesita 20/40 en por lo menos un ojo."},"zh":{"q":"在 New York，要通过 DMV 视力检查，你需要什么视力（戴不戴眼镜都可以）？","o":["两只眼睛都是 20/20","至少一只眼睛是 20/40","两只眼睛都是 20/60","至少一只眼睛是 20/100"],"h1":"只需要一只眼睛达到标准。","h2":"在 New York，至少一只眼睛的视力要达到 20/40（戴不戴眼镜或隐形眼镜都可以），才能通过视力检查。","p":"对。至少一只眼睛要达到 20/40。"},"vi":{"q":"Ở New York, bạn cần thị lực như thế nào để qua bài kiểm tra thị lực của DMV, có hoặc không có kính?","o":["20/20 ở cả hai mắt","20/40 ở ít nhất một mắt","20/60 ở cả hai mắt","20/100 ở ít nhất một mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn.","h2":"Ở New York, bạn cần thị lực 20/40 ở ít nhất một mắt, có hoặc không có kính hay kính áp tròng, để qua bài kiểm tra thị lực.","p":"Đúng. Bạn cần 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa New York, anong paningin ang kailangan mo para pumasa sa vision test ng DMV, may salamin man o wala?","o":["20/20 sa dalawang mata","20/40 sa kahit isang mata","20/60 sa dalawang mata","20/100 sa kahit isang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan.","h2":"Sa New York, kailangan mo ng 20/40 na paningin sa kahit isang mata, may salamin o contact lens man o wala, para pumasa sa vision test.","p":"Tama. Kailangan mo ng 20/40 sa kahit isang mata."},"ar":{"q":"في New York، ما النظر الذي تحتاجه لتنجح في فحص النظر في DMV، بالنظارة أو بدونها؟","o":["20/20 في العينين","20/40 في عين واحدة على الأقل","20/60 في العينين","20/100 في عين واحدة على الأقل"],"h1":"يكفي أن تحقق عين واحدة المعيار.","h2":"في New York تحتاج إلى نظر 20/40 في عين واحدة على الأقل، بالنظارة أو العدسات اللاصقة أو بدونها، لتنجح في فحص النظر.","p":"صحيح. تحتاج إلى 20/40 في عين واحدة على الأقل."},"ref":{"doc":"NY","page":10}},{"id":"ny-029","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, when you apply for your first license, your proofs of name and identity must add up to how many points?","o":["At least 2 points","At least 4 points","At least 10 points","At least 6 points"],"h1":"A U.S. passport counts for 4 points, and that is not enough on its own.","h2":"In New York your proofs of name must add up to at least 6 points, and at least one of them must have your signature.","p":"Right. You need at least 6 points."},"es":{"q":"En Nueva York, cuando solicita su primera licencia, ¿cuántos puntos deben sumar sus pruebas de nombre e identidad?","o":["Por lo menos 2 puntos","Por lo menos 4 puntos","Por lo menos 10 puntos","Por lo menos 6 puntos"],"h1":"Un pasaporte de EE. UU. vale 4 puntos, y eso solo no es suficiente.","h2":"En Nueva York sus pruebas de nombre deben sumar por lo menos 6 puntos, y por lo menos una de ellas debe tener su firma.","p":"Correcto. Necesita por lo menos 6 puntos."},"zh":{"q":"在 New York，第一次申请驾照时，你的姓名和身份证明文件加起来必须有多少分？","o":["至少 2 分","至少 4 分","至少 10 分","至少 6 分"],"h1":"美国护照算 4 分，只有它还不够。","h2":"在 New York，你的姓名证明文件加起来必须至少有 6 分，而且至少有一份要有你的签名。","p":"对。你需要至少 6 分。"},"vi":{"q":"Ở New York, khi bạn xin bằng lái lần đầu, giấy tờ chứng minh tên và danh tính của bạn phải cộng lại được bao nhiêu điểm?","o":["Ít nhất 2 điểm","Ít nhất 4 điểm","Ít nhất 10 điểm","Ít nhất 6 điểm"],"h1":"Hộ chiếu Mỹ được tính 4 điểm, và chỉ một mình nó thì chưa đủ.","h2":"Ở New York, giấy tờ chứng minh tên của bạn phải cộng lại được ít nhất 6 điểm, và ít nhất một giấy tờ phải có chữ ký của bạn.","p":"Đúng. Bạn cần ít nhất 6 điểm."},"tl":{"q":"Sa New York, kapag nag-apply ka ng una mong lisensya, ilang points dapat ang kabuuan ng mga patunay ng pangalan at pagkakakilanlan mo?","o":["Hindi bababa sa 2 points","Hindi bababa sa 4 points","Hindi bababa sa 10 points","Hindi bababa sa 6 points"],"h1":"Ang U.S. passport ay 4 points, at hindi ito sapat nang mag-isa.","h2":"Sa New York, ang mga patunay ng pangalan mo ay dapat umabot ng hindi bababa sa 6 points, at kahit isa sa mga ito ay dapat may pirma mo.","p":"Tama. Kailangan mo ng hindi bababa sa 6 points."},"ar":{"q":"في New York، عندما تقدّم طلبًا لأول رخصة لك، كم نقطة يجب أن يكون مجموع إثباتات الاسم والهوية؟","o":["نقطتان على الأقل","4 نقاط على الأقل","10 نقاط على الأقل","6 نقاط على الأقل"],"h1":"جواز السفر الأمريكي يُحسب 4 نقاط، ولا يكفي وحده.","h2":"في New York يجب أن يكون مجموع إثباتات اسمك 6 نقاط على الأقل، ويجب أن يحمل واحد منها على الأقل توقيعك.","p":"صحيح. تحتاج إلى 6 نقاط على الأقل."},"ref":{"doc":"NY","page":8}},{"id":"ny-030","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, how must a child aged 4 to 7 ride in a car?","o":["In an approved child seat, usually a booster, with the lap and shoulder belt","With only the car's seat belt","On an adult's lap in the back seat","In a rear-facing infant seat"],"h1":"The car's belt alone does not fit a small child.","h2":"In New York a child aged 4 to 7 must ride in an approved child restraint, usually a booster seat, used with the lap and shoulder belt.","p":"Right. A booster or other approved child seat is required."},"es":{"q":"En Nueva York, ¿cómo debe viajar en un carro un niño de 4 a 7 años?","o":["En un asiento infantil aprobado, por lo general un asiento elevado, con el cinturón de regazo y hombro","Solo con el cinturón de seguridad del carro","En las piernas de un adulto en el asiento trasero","En un asiento para bebé mirando hacia atrás"],"h1":"El cinturón del carro solo no le queda bien a un niño pequeño.","h2":"En Nueva York un niño de 4 a 7 años debe viajar en un sistema de retención infantil aprobado, por lo general un asiento elevado, usado con el cinturón de regazo y hombro.","p":"Correcto. Se requiere un asiento elevado u otro asiento infantil aprobado."},"zh":{"q":"在 New York，4 到 7 岁的孩子坐车时必须怎么坐？","o":["坐在合格的儿童座椅上，通常是增高座椅，并系上腰带和肩带","只系汽车的安全带","坐在后座大人的腿上","坐在后向婴儿座椅上"],"h1":"只用汽车的安全带不适合小孩子。","h2":"在 New York，4 到 7 岁的孩子必须坐在合格的儿童安全座椅上，通常是增高座椅，并配合腰带和肩带使用。","p":"对。必须用增高座椅或其他合格的儿童座椅。"},"vi":{"q":"Ở New York, trẻ từ 4 đến 7 tuổi phải ngồi trong xe như thế nào?","o":["Trong ghế trẻ em được chấp thuận, thường là ghế nâng, với dây đai ngang hông và dây đai vai","Chỉ với dây an toàn của xe","Ngồi trên đùi người lớn ở ghế sau","Trong ghế em bé quay mặt về phía sau"],"h1":"Chỉ dây an toàn của xe thì không vừa với trẻ nhỏ.","h2":"Ở New York, trẻ từ 4 đến 7 tuổi phải ngồi trong ghế an toàn trẻ em được chấp thuận, thường là ghế nâng, dùng cùng dây đai ngang hông và dây đai vai.","p":"Đúng. Phải có ghế nâng hoặc ghế trẻ em khác được chấp thuận."},"tl":{"q":"Sa New York, paano dapat sumakay sa kotse ang batang 4 hanggang 7 taong gulang?","o":["Sa aprubadong child seat, karaniwang booster, kasama ang lap at shoulder belt","Gamit lang ang seat belt ng kotse","Nakakandong sa adult sa likod na upuan","Sa rear-facing na upuan ng sanggol"],"h1":"Hindi kasya sa maliit na bata ang seat belt lang ng kotse.","h2":"Sa New York, ang batang 4 hanggang 7 taong gulang ay dapat nakaupo sa aprubadong child restraint, karaniwang booster seat, na ginagamit kasama ang lap at shoulder belt.","p":"Tama. Kailangan ang booster o iba pang aprubadong child seat."},"ar":{"q":"في New York، كيف يجب أن يجلس طفل عمره من 4 إلى 7 سنوات في السيارة؟","o":["في مقعد أطفال معتمد، وعادةً مقعد رافع، مع حزام الحِجر وحزام الكتف","بحزام أمان السيارة فقط","في حضن شخص بالغ في المقعد الخلفي","في مقعد رضيع موجّه إلى الخلف"],"h1":"حزام السيارة وحده لا يناسب الطفل الصغير.","h2":"في New York يجب أن يجلس الطفل الذي عمره من 4 إلى 7 سنوات في مقعد أطفال معتمد، وعادةً مقعد رافع، يُستخدم مع حزام الحِجر وحزام الكتف.","p":"صحيح. يجب استخدام مقعد رافع أو مقعد أطفال معتمد آخر."},"ref":{"doc":"NY","page":48}},{"id":"ny-031","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, after a crash with $1,000 or more in damage to one person's property, how soon must you report it to the DMV?","o":["Within 24 hours","Within 30 days","Within 10 days","Within 90 days"],"h1":"Reporting to your insurance company does not count.","h2":"In New York you must file a crash report with the DMV within 10 days when someone is hurt or killed, or when one person's property has $1,000 or more in damage.","p":"Right. Report it to the DMV within 10 days."},"es":{"q":"En Nueva York, después de un choque con $1,000 o más en daños a la propiedad de una persona, ¿en qué plazo debe reportarlo al DMV?","o":["Dentro de 24 horas","Dentro de 30 días","Dentro de 10 días","Dentro de 90 días"],"h1":"Avisar a su compañía de seguros no cuenta.","h2":"En Nueva York usted debe presentar un informe de choque al DMV dentro de 10 días cuando alguien resulta herido o muere, o cuando la propiedad de una persona tiene $1,000 o más en daños.","p":"Correcto. Repórtelo al DMV dentro de 10 días."},"zh":{"q":"在 New York，发生车祸后，如果一个人的财产损失达到 $1,000 或以上，你必须在多久之内向 DMV 报告？","o":["24 小时之内","30 天之内","10 天之内","90 天之内"],"h1":"向你的保险公司报告不算数。","h2":"在 New York，如果有人受伤或死亡，或者一个人的财产损失达到 $1,000 或以上，你必须在 10 天之内向 DMV 提交车祸报告。","p":"对。10 天之内向 DMV 报告。"},"vi":{"q":"Ở New York, sau một vụ tai nạn làm hư hại tài sản của một người từ $1,000 trở lên, bạn phải báo cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày"],"h1":"Báo cho công ty bảo hiểm của bạn thì không tính.","h2":"Ở New York, bạn phải nộp báo cáo tai nạn cho DMV trong vòng 10 ngày khi có người bị thương hoặc tử vong, hoặc khi tài sản của một người bị hư hại từ $1,000 trở lên.","p":"Đúng. Báo cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa New York, pagkatapos ng banggaan na may $1,000 o higit pang pinsala sa ari-arian ng isang tao, gaano kabilis mo ito dapat i-report sa DMV?","o":["Sa loob ng 24 oras","Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 90 araw"],"h1":"Hindi binibilang ang pag-report sa insurance company mo.","h2":"Sa New York, dapat kang mag-file ng crash report sa DMV sa loob ng 10 araw kapag may nasaktan o namatay, o kapag ang ari-arian ng isang tao ay may $1,000 o higit pang pinsala.","p":"Tama. I-report ito sa DMV sa loob ng 10 araw."},"ar":{"q":"في New York، بعد حادث تسبّب في ضرر بقيمة $1,000 أو أكثر لممتلكات شخص واحد، خلال كم من الوقت يجب أن تبلّغ DMV؟","o":["خلال 24 ساعة","خلال 30 يومًا","خلال 10 أيام","خلال 90 يومًا"],"h1":"إبلاغ شركة التأمين لا يُحسب.","h2":"في New York يجب أن تقدّم تقرير حادث إلى DMV خلال 10 أيام إذا أُصيب أحد أو توفي، أو إذا كان الضرر في ممتلكات شخص واحد $1,000 أو أكثر.","p":"صحيح. بلّغ DMV خلال 10 أيام."},"ref":{"doc":"NY","page":77}},{"id":"ny-032","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, how many points within 24 months lead to a notice that your license will be suspended?","o":["6 or more points","11 or more points","15 or more points","20 or more points"],"h1":"It is more than 10.","h2":"In New York, if you get 11 or more points within 24 months, the DMV will tell you by mail that your license will be suspended.","p":"Right. 11 points in 24 months means a suspension."},"es":{"q":"En Nueva York, ¿cuántos puntos en 24 meses traen un aviso de que su licencia será suspendida?","o":["6 puntos o más","11 puntos o más","15 puntos o más","20 puntos o más"],"h1":"Son más de 10.","h2":"En Nueva York, si usted acumula 11 puntos o más en 24 meses, el DMV le avisará por correo que su licencia será suspendida.","p":"Correcto. 11 puntos en 24 meses traen una suspensión."},"zh":{"q":"在 New York，24 个月内被记多少分，就会收到驾照将被暂停的通知？","o":["6 分或以上","11 分或以上","15 分或以上","20 分或以上"],"h1":"比 10 分多。","h2":"在 New York，如果你在 24 个月内被记 11 分或以上，DMV 会寄信告诉你，你的驾照将被暂停。","p":"对。24 个月内 11 分就会被暂停驾照。"},"vi":{"q":"Ở New York, bị bao nhiêu điểm trong vòng 24 tháng thì bạn sẽ nhận thông báo bằng lái sẽ bị treo?","o":["6 điểm trở lên","11 điểm trở lên","15 điểm trở lên","20 điểm trở lên"],"h1":"Nhiều hơn 10.","h2":"Ở New York, nếu bạn bị 11 điểm trở lên trong vòng 24 tháng, DMV sẽ gửi thư báo rằng bằng lái của bạn sẽ bị treo.","p":"Đúng. 11 điểm trong 24 tháng nghĩa là bị treo bằng lái."},"tl":{"q":"Sa New York, ilang puntos sa loob ng 24 na buwan ang magdudulot ng abiso na masususpinde ang lisensya mo?","o":["6 na puntos o higit pa","11 puntos o higit pa","15 puntos o higit pa","20 puntos o higit pa"],"h1":"Higit ito sa 10.","h2":"Sa New York, kung makakuha ka ng 11 puntos o higit pa sa loob ng 24 na buwan, sasabihan ka ng DMV sa sulat na masususpinde ang lisensya mo.","p":"Tama. Ang 11 puntos sa loob ng 24 na buwan ay nangangahulugang suspensyon."},"ar":{"q":"في New York، كم نقطة خلال 24 شهرًا تؤدي إلى إشعار بأن رخصتك ستُوقف؟","o":["6 نقاط أو أكثر","11 نقطة أو أكثر","15 نقطة أو أكثر","20 نقطة أو أكثر"],"h1":"العدد أكثر من 10.","h2":"في New York، إذا حصلت على 11 نقطة أو أكثر خلال 24 شهرًا، ترسل لك إدارة DMV رسالة بالبريد تخبرك أن رخصتك ستُوقف.","p":"صحيح. 11 نقطة خلال 24 شهرًا تعني إيقاف الرخصة."},"ref":{"doc":"NY","page":22}},{"id":"ny-033","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, by how many points can a DMV-approved crash prevention course (PIRP) lower your point total?","o":["1 point","2 points","Up to 4 points","All of your points"],"h1":"It helps, but it does not erase everything.","h2":"In New York, a DMV-approved crash prevention course (PIRP) can lower your point total by up to 4 points.","p":"Right. The course can take off up to 4 points."},"es":{"q":"En Nueva York, ¿cuántos puntos puede reducir de su total un curso de prevención de choques aprobado por el DMV (PIRP)?","o":["1 punto","2 puntos","Hasta 4 puntos","Todos sus puntos"],"h1":"Ayuda, pero no lo borra todo.","h2":"En Nueva York, un curso de prevención de choques aprobado por el DMV (PIRP) puede reducir su total hasta en 4 puntos.","p":"Correcto. El curso puede quitar hasta 4 puntos."},"zh":{"q":"在 New York，经 DMV 批准的事故预防课程（PIRP）最多可以减掉你多少分？","o":["1 分","2 分","最多 4 分","全部的分"],"h1":"它有帮助，但不会把所有分都清掉。","h2":"在 New York，经 DMV 批准的事故预防课程（PIRP）最多可以从你的总分里减掉 4 分。","p":"对。这个课程最多可以减掉 4 分。"},"vi":{"q":"Ở New York, khóa học phòng ngừa tai nạn được DMV chấp thuận (PIRP) có thể giảm tổng số điểm của bạn bao nhiêu điểm?","o":["1 điểm","2 điểm","Tối đa 4 điểm","Tất cả số điểm của bạn"],"h1":"Nó có giúp, nhưng không xóa hết mọi thứ.","h2":"Ở New York, khóa học phòng ngừa tai nạn được DMV chấp thuận (PIRP) có thể giảm tổng số điểm của bạn tối đa 4 điểm.","p":"Đúng. Khóa học có thể trừ tối đa 4 điểm."},"tl":{"q":"Sa New York, ilang puntos ang maaaring ibawas sa kabuuang puntos mo ng crash prevention course (PIRP) na aprubado ng DMV?","o":["1 puntos","2 puntos","Hanggang 4 na puntos","Lahat ng puntos mo"],"h1":"Nakakatulong ito, pero hindi nito binubura ang lahat.","h2":"Sa New York, ang crash prevention course (PIRP) na aprubado ng DMV ay maaaring magbawas ng hanggang 4 na puntos sa kabuuang puntos mo.","p":"Tama. Kayang magbawas ng kurso ng hanggang 4 na puntos."},"ar":{"q":"في New York، بكم نقطة يمكن أن تُخفّض دورة الوقاية من الحوادث المعتمدة من DMV (PIRP) مجموع نقاطك؟","o":["نقطة واحدة (1)","نقطتان (2)","حتى 4 نقاط","كل نقاطك"],"h1":"الدورة تساعد، لكنها لا تمحو كل شيء.","h2":"في New York، يمكن لدورة الوقاية من الحوادث المعتمدة من DMV (PIRP) أن تُخفّض مجموع نقاطك بما يصل إلى 4 نقاط.","p":"صحيح. الدورة يمكن أن تحذف حتى 4 نقاط."},"ref":{"doc":"NY","page":15}},{"id":"ny-034","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, you are 18 or older and pass your road test. How long is your new license on probation?","o":["Six months","One month","Two years","There is no probation"],"h1":"It is half a year.","h2":"In New York, a driver who is 18 or older when passing the road test is on probation for six months.","p":"Right. New adult drivers are on probation for six months."},"es":{"q":"En Nueva York, usted tiene 18 años o más y aprueba el examen de manejo. ¿Cuánto dura el período de prueba de su nueva licencia?","o":["Seis meses","Un mes","Dos años","No hay período de prueba"],"h1":"Es medio año.","h2":"En Nueva York, quien tiene 18 años o más al aprobar el examen de manejo queda en período de prueba por seis meses.","p":"Correcto. Los nuevos conductores adultos están a prueba seis meses."},"zh":{"q":"在 New York，你 18 岁或以上并通过了路考。你的新驾照试用期（probation）有多长？","o":["六个月","一个月","两年","没有试用期"],"h1":"是半年。","h2":"在 New York，通过路考时已满 18 岁的司机有六个月的试用期。","p":"对。新的成年司机有六个月的试用期。"},"vi":{"q":"Ở New York, bạn từ 18 tuổi trở lên và đậu bài thi lái đường. Bằng lái mới của bạn ở trong thời gian thử thách (probation) bao lâu?","o":["Sáu tháng","Một tháng","Hai năm","Không có thời gian thử thách"],"h1":"Là nửa năm.","h2":"Ở New York, người lái từ 18 tuổi trở lên khi đậu bài thi lái đường sẽ ở trong thời gian thử thách sáu tháng.","p":"Đúng. Người lái mới là người lớn có thời gian thử thách sáu tháng."},"tl":{"q":"Sa New York, 18 taong gulang ka o higit pa at pumasa ka sa road test. Gaano katagal naka-probation ang bago mong lisensya?","o":["Anim na buwan","Isang buwan","Dalawang taon","Walang probation"],"h1":"Kalahating taon ito.","h2":"Sa New York, ang driver na 18 taong gulang o higit pa nang pumasa sa road test ay naka-probation nang anim na buwan.","p":"Tama. Ang mga bagong adult driver ay naka-probation nang anim na buwan."},"ar":{"q":"في New York، عمرك 18 سنة أو أكثر ونجحت في اختبار القيادة على الطريق. كم مدة فترة الاختبار (probation) لرخصتك الجديدة؟","o":["ستة أشهر","شهر واحد","سنتان","لا توجد فترة اختبار"],"h1":"المدة نصف سنة.","h2":"في New York، السائق الذي عمره 18 سنة أو أكثر عند نجاحه في اختبار الطريق يكون في فترة اختبار لمدة ستة أشهر.","p":"صحيح. السائقون البالغون الجدد في فترة اختبار لمدة ستة أشهر."},"ref":{"doc":"NY","page":19}},{"id":"ny-035","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, you move to a new home. How soon must you tell the DMV your new address?","o":["Within 24 hours","Within 60 days","When you renew your license","Within 10 days"],"h1":"It is less than two weeks.","h2":"In New York, you must tell the DMV your new address within 10 days, by mail or online.","p":"Right. Tell the DMV within 10 days."},"es":{"q":"En Nueva York, usted se muda a una casa nueva. ¿En qué plazo debe avisar al DMV su nueva dirección?","o":["Dentro de 24 horas","Dentro de 60 días","Cuando renueve su licencia","Dentro de 10 días"],"h1":"Es menos de dos semanas.","h2":"En Nueva York, usted debe avisar al DMV su nueva dirección dentro de 10 días, por correo o en línea.","p":"Correcto. Avise al DMV dentro de 10 días."},"zh":{"q":"在 New York，你搬了新家。你必须多快把新地址告诉 DMV？","o":["24 小时内","60 天内","在你更新驾照时","10 天内"],"h1":"不到两个星期。","h2":"在 New York，你必须在 10 天内通过邮寄或网上把新地址告诉 DMV。","p":"对。要在 10 天内告诉 DMV。"},"vi":{"q":"Ở New York, bạn chuyển đến nhà mới. Bạn phải báo địa chỉ mới cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 60 ngày","Khi bạn gia hạn bằng lái","Trong vòng 10 ngày"],"h1":"Ít hơn hai tuần.","h2":"Ở New York, bạn phải báo địa chỉ mới cho DMV trong vòng 10 ngày, qua thư hoặc trên mạng.","p":"Đúng. Hãy báo cho DMV trong vòng 10 ngày."},"tl":{"q":"Sa New York, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihin sa DMV ang bago mong address?","o":["Sa loob ng 24 na oras","Sa loob ng 60 araw","Kapag nag-renew ka ng lisensya","Sa loob ng 10 araw"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa New York, dapat mong sabihin sa DMV ang bago mong address sa loob ng 10 araw, sa koreo o online.","p":"Tama. Sabihan ang DMV sa loob ng 10 araw."},"ar":{"q":"في New York، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ DMV بعنوانك الجديد؟","o":["خلال 24 ساعة","خلال 60 يومًا","عندما تجدّد رخصتك","خلال 10 أيام"],"h1":"المدة أقل من أسبوعين.","h2":"في New York، يجب أن تُبلغ DMV بعنوانك الجديد خلال 10 أيام، بالبريد أو عبر الإنترنت.","p":"صحيح. أبلغ DMV خلال 10 أيام."},"ref":{"doc":"NY","page":17}},{"id":"ny-036","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, you move here from another state and become a resident. How soon must you apply for a New York license?","o":["Within 10 days","Within 30 days","Within 6 months","Only when your old license expires"],"h1":"It is about one month.","h2":"In New York, a new resident must apply for a New York driver license within 30 days of becoming a resident.","p":"Right. New residents have 30 days."},"es":{"q":"En Nueva York, usted se muda desde otro estado y se hace residente. ¿En qué plazo debe solicitar una licencia de Nueva York?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses","Solo cuando venza su licencia anterior"],"h1":"Es más o menos un mes.","h2":"En Nueva York, un nuevo residente debe solicitar una licencia de conducir de Nueva York dentro de 30 días de hacerse residente.","p":"Correcto. Los nuevos residentes tienen 30 días."},"zh":{"q":"在 New York，你从别的州搬来，成为本州居民。你必须多快申请 New York 驾照？","o":["10 天内","30 天内","6 个月内","只在旧驾照过期时"],"h1":"大约一个月。","h2":"在 New York，新居民必须在成为居民后 30 天内申请 New York 驾照。","p":"对。新居民有 30 天。"},"vi":{"q":"Ở New York, bạn chuyển đến từ một tiểu bang khác và trở thành cư dân. Bạn phải nộp đơn xin bằng lái New York trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 6 tháng","Chỉ khi bằng lái cũ hết hạn"],"h1":"Khoảng một tháng.","h2":"Ở New York, cư dân mới phải nộp đơn xin bằng lái New York trong vòng 30 ngày kể từ khi trở thành cư dân.","p":"Đúng. Cư dân mới có 30 ngày."},"tl":{"q":"Sa New York, lumipat ka rito mula sa ibang estado at naging residente. Gaano kabilis ka dapat mag-apply ng lisensya ng New York?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 6 na buwan","Kapag nag-expire na lang ang luma mong lisensya"],"h1":"Mga isang buwan ito.","h2":"Sa New York, ang bagong residente ay dapat mag-apply ng driver license ng New York sa loob ng 30 araw mula nang maging residente.","p":"Tama. May 30 araw ang mga bagong residente."},"ar":{"q":"في New York، انتقلت إليها من ولاية أخرى وأصبحت مقيمًا. خلال كم من الوقت يجب أن تتقدّم بطلب رخصة New York؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 6 أشهر","فقط عندما تنتهي رخصتك القديمة"],"h1":"المدة شهر تقريبًا.","h2":"في New York، يجب على المقيم الجديد أن يتقدّم بطلب رخصة قيادة New York خلال 30 يومًا من أن يصبح مقيمًا.","p":"صحيح. لدى المقيمين الجدد 30 يومًا."},"ref":{"doc":"NY","page":18}},{"id":"ny-037","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the minimum liability insurance for injury to one person in a crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"It is more than $10,000 but much less than $100,000.","h2":"In New York, your liability insurance must cover at least $25,000 for injury to one person.","p":"Right. The minimum is $25,000 for injury to one person."},"es":{"q":"En Nueva York, ¿cuál es el seguro de responsabilidad mínimo por lesiones a una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Es más de $10,000 pero mucho menos de $100,000.","h2":"En Nueva York, su seguro de responsabilidad debe cubrir por lo menos $25,000 por lesiones a una persona.","p":"Correcto. El mínimo es $25,000 por lesiones a una persona."},"zh":{"q":"在 New York，车祸中一个人受伤的最低责任保险金额是多少？","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"比 $10,000 多，但比 $100,000 少很多。","h2":"在 New York，你的责任保险对一个人受伤必须至少赔付 $25,000。","p":"对。一个人受伤的最低金额是 $25,000。"},"vi":{"q":"Ở New York, mức bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong một vụ tai nạn là bao nhiêu?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Nhiều hơn $10,000 nhưng ít hơn $100,000 rất nhiều.","h2":"Ở New York, bảo hiểm trách nhiệm của bạn phải chi trả ít nhất $25,000 cho thương tích của một người.","p":"Đúng. Mức tối thiểu là $25,000 cho thương tích của một người."},"tl":{"q":"Sa New York, ano ang pinakamababang liability insurance para sa pinsala sa isang tao sa isang banggaan?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Higit ito sa $10,000 pero mas mababa nang malaki sa $100,000.","h2":"Sa New York, dapat sakupin ng liability insurance mo ang hindi bababa sa $25,000 para sa pinsala sa isang tao.","p":"Tama. Ang pinakamababa ay $25,000 para sa pinsala sa isang tao."},"ar":{"q":"في New York، ما الحد الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"المبلغ أكثر من $10,000 لكنه أقل بكثير من $100,000.","h2":"في New York، يجب أن يغطي تأمين المسؤولية لديك $25,000 على الأقل عن إصابة شخص واحد.","p":"صحيح. الحد الأدنى هو $25,000 عن إصابة شخص واحد."},"ref":{"doc":"NY","page":27}},{"id":"ny-038","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a driver age 21 or older refuses a chemical test for the first time. What happens to the license?","o":["Nothing, if the driver is found not guilty","A warning only","A 30-day suspension","It is revoked for at least one year"],"h1":"Refusing is treated more strictly than many people think.","h2":"In New York, a first chemical test refusal by a driver age 21 or older means the license is revoked for at least one year.","p":"Right. A first refusal means at least a one-year revocation."},"es":{"q":"En Nueva York, un conductor de 21 años o más se niega por primera vez a una prueba química. ¿Qué pasa con la licencia?","o":["Nada, si lo declaran no culpable","Solo una advertencia","Una suspensión de 30 días","Se revoca por al menos un año"],"h1":"Negarse se castiga con más fuerza de lo que muchos piensan.","h2":"En Nueva York, la primera vez que un conductor de 21 años o más se niega a una prueba química, su licencia se revoca por al menos un año.","p":"Correcto. Negarse la primera vez trae una revocación de al menos un año."},"zh":{"q":"在 New York，一位 21 岁或以上的司机第一次拒绝化学测试。驾照会怎样？","o":["如果司机被判无罪，就没事","只是警告","暂停 30 天","吊销至少一年"],"h1":"拒绝测试的处罚比很多人想的更严格。","h2":"在 New York，21 岁或以上的司机第一次拒绝化学测试，驾照会被吊销至少一年。","p":"对。第一次拒绝就会被吊销至少一年。"},"vi":{"q":"Ở New York, một người lái từ 21 tuổi trở lên từ chối xét nghiệm hóa học lần đầu. Bằng lái sẽ bị gì?","o":["Không sao, nếu người lái được xử là vô tội","Chỉ bị cảnh cáo","Bị treo 30 ngày","Bị thu hồi ít nhất một năm"],"h1":"Việc từ chối bị xử nghiêm hơn nhiều người nghĩ.","h2":"Ở New York, người lái từ 21 tuổi trở lên từ chối xét nghiệm hóa học lần đầu sẽ bị thu hồi bằng lái ít nhất một năm.","p":"Đúng. Từ chối lần đầu nghĩa là bị thu hồi ít nhất một năm."},"tl":{"q":"Sa New York, tumanggi sa chemical test sa unang pagkakataon ang driver na 21 taong gulang o higit pa. Ano ang mangyayari sa lisensya?","o":["Wala, kung mapatunayang hindi nagkasala ang driver","Babala lang","Suspensyon nang 30 araw","Babawiin ito nang hindi bababa sa isang taon"],"h1":"Mas mahigpit ang trato sa pagtanggi kaysa sa inaakala ng marami.","h2":"Sa New York, kapag unang tumanggi sa chemical test ang driver na 21 taong gulang o higit pa, babawiin ang lisensya nang hindi bababa sa isang taon.","p":"Tama. Ang unang pagtanggi ay nangangahulugang pagbawi nang hindi bababa sa isang taon."},"ar":{"q":"في New York، سائق عمره 21 سنة أو أكثر يرفض فحصًا كيميائيًا لأول مرة. ماذا يحدث للرخصة؟","o":["لا شيء، إذا ثبتت براءة السائق","إنذار فقط","إيقاف لمدة 30 يومًا","تُسحب لمدة سنة واحدة على الأقل"],"h1":"الرفض يُعامل بصرامة أكبر مما يظن كثير من الناس.","h2":"في New York، إذا رفض سائق عمره 21 سنة أو أكثر الفحص الكيميائي لأول مرة، تُسحب رخصته لمدة سنة واحدة على الأقل.","p":"صحيح. الرفض الأول يعني سحب الرخصة لمدة سنة على الأقل."},"ref":{"doc":"NY","page":21}},{"id":"ny-039","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, Aggravated Driving While Intoxicated (Agg-DWI) starts at what blood alcohol level?","o":["0.18 percent","0.05 percent","0.08 percent","0.12 percent"],"h1":"It is more than twice the usual legal limit.","h2":"In New York, a blood alcohol level of 0.18 percent or more is evidence of Aggravated Driving While Intoxicated.","p":"Right. Agg-DWI starts at 0.18 percent."},"es":{"q":"En Nueva York, ¿a partir de qué nivel de alcohol en la sangre se considera Manejar en Estado de Intoxicación Agravado (Agg-DWI)?","o":["0.18 por ciento","0.05 por ciento","0.08 por ciento","0.12 por ciento"],"h1":"Es más del doble del límite legal normal.","h2":"En Nueva York, un nivel de alcohol en la sangre de 0.18 por ciento o más es prueba de Manejar en Estado de Intoxicación Agravado.","p":"Correcto. El Agg-DWI empieza en 0.18 por ciento."},"zh":{"q":"在 New York，加重醉酒驾驶（Agg-DWI）从多少血液酒精浓度开始？","o":["0.18%","0.05%","0.08%","0.12%"],"h1":"是一般法定上限的两倍多。","h2":"在 New York，血液酒精浓度达到 0.18% 或以上，就是加重醉酒驾驶（Aggravated Driving While Intoxicated）的证据。","p":"对。Agg-DWI 从 0.18% 开始。"},"vi":{"q":"Ở New York, tội lái xe khi say rượu nghiêm trọng (Agg-DWI) bắt đầu từ nồng độ cồn trong máu là bao nhiêu?","o":["0.18 phần trăm","0.05 phần trăm","0.08 phần trăm","0.12 phần trăm"],"h1":"Cao hơn gấp đôi mức giới hạn pháp lý thông thường.","h2":"Ở New York, nồng độ cồn trong máu từ 0.18 phần trăm trở lên là bằng chứng của tội lái xe khi say rượu nghiêm trọng (Aggravated Driving While Intoxicated).","p":"Đúng. Agg-DWI bắt đầu từ 0.18 phần trăm."},"tl":{"q":"Sa New York, sa anong blood alcohol level nagsisimula ang Aggravated Driving While Intoxicated (Agg-DWI)?","o":["0.18 porsiyento","0.05 porsiyento","0.08 porsiyento","0.12 porsiyento"],"h1":"Higit ito sa doble ng karaniwang legal na limitasyon.","h2":"Sa New York, ang blood alcohol level na 0.18 porsiyento o higit pa ay ebidensya ng Aggravated Driving While Intoxicated.","p":"Tama. Nagsisimula ang Agg-DWI sa 0.18 porsiyento."},"ar":{"q":"في New York، من أي نسبة كحول في الدم تبدأ القيادة تحت تأثير الكحول المشدّدة (Agg-DWI)؟","o":["0.18 بالمئة","0.05 بالمئة","0.08 بالمئة","0.12 بالمئة"],"h1":"النسبة أكثر من ضعف الحد القانوني المعتاد.","h2":"في New York، نسبة كحول في الدم تبلغ 0.18 بالمئة أو أكثر هي دليل على القيادة تحت تأثير الكحول المشدّدة (Aggravated Driving While Intoxicated).","p":"صحيح. تبدأ Agg-DWI من 0.18 بالمئة."},"ref":{"doc":"NY","page":55}},{"id":"ny-040","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, under Leandra's Law, what can a drunk driver face if a child under 16 is in the vehicle?","o":["Only a larger fine","A felony charge","Points only","A warning letter"],"h1":"It is a much more serious crime than a traffic ticket.","h2":"Under New York's Leandra's Law, a person who drives drunk with a child under 16 in the vehicle can be charged with a felony.","p":"Right. With a child under 16 in the car, it can be a felony."},"es":{"q":"En Nueva York, según la Ley de Leandra, ¿a qué se expone un conductor ebrio si lleva en el vehículo a un niño menor de 16 años?","o":["Solo a una multa más alta","A un cargo de delito grave (felony)","Solo a puntos","A una carta de advertencia"],"h1":"Es un delito mucho más serio que una multa de tráfico.","h2":"Según la Ley de Leandra de Nueva York, quien maneja ebrio con un niño menor de 16 años en el vehículo puede ser acusado de un delito grave (felony).","p":"Correcto. Con un niño menor de 16 años en el auto, puede ser un delito grave."},"zh":{"q":"在 New York，根据 Leandra's Law，如果车里有未满 16 岁的孩子，醉酒司机会面临什么？","o":["只是更高的罚款","重罪指控","只记分","一封警告信"],"h1":"这比交通罚单严重得多。","h2":"根据 New York 的 Leandra's Law，车里有未满 16 岁的孩子时醉酒驾驶的人，可以被控重罪。","p":"对。车里有未满 16 岁的孩子，就可能是重罪。"},"vi":{"q":"Ở New York, theo Luật Leandra (Leandra's Law), người lái xe say rượu có thể bị gì nếu có trẻ dưới 16 tuổi trong xe?","o":["Chỉ bị phạt tiền nặng hơn","Bị buộc tội trọng tội (felony)","Chỉ bị trừ điểm","Một lá thư cảnh cáo"],"h1":"Đây là tội nặng hơn nhiều so với một vé phạt giao thông.","h2":"Theo Luật Leandra (Leandra's Law) của New York, người lái xe say rượu khi có trẻ dưới 16 tuổi trong xe có thể bị buộc tội trọng tội (felony).","p":"Đúng. Có trẻ dưới 16 tuổi trong xe thì có thể là trọng tội."},"tl":{"q":"Sa New York, sa ilalim ng Leandra's Law, ano ang maaaring harapin ng lasing na driver kung may batang wala pang 16 sa sasakyan?","o":["Mas malaking multa lang","Kasong felony","Puntos lang","Sulat ng babala"],"h1":"Mas mabigat na krimen ito kaysa sa traffic ticket.","h2":"Sa ilalim ng Leandra's Law ng New York, ang taong nagmamaneho nang lasing na may batang wala pang 16 sa sasakyan ay maaaring kasuhan ng felony.","p":"Tama. Kapag may batang wala pang 16 sa kotse, maaari itong maging felony."},"ar":{"q":"في New York، بموجب قانون Leandra's Law، ماذا قد يواجه السائق المخمور إذا كان في السيارة طفل عمره أقل من 16 سنة؟","o":["غرامة أكبر فقط","تهمة جناية (felony)","نقاط فقط","رسالة إنذار"],"h1":"هذه جريمة أخطر بكثير من مخالفة مرورية.","h2":"بموجب قانون Leandra's Law في New York، يمكن أن يُتّهم بجناية (felony) من يقود وهو مخمور ومعه في السيارة طفل عمره أقل من 16 سنة.","p":"صحيح. مع طفل عمره أقل من 16 سنة في السيارة، قد تكون جناية."},"ref":{"doc":"NY","page":59}},{"id":"ny-041","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, how many points can an adult driver get for a first offense of talking on a hand-held phone while driving?","o":["No points","2 points","5 points","11 points"],"h1":"It is more than for most small violations.","h2":"In New York, a first offense for using a hand-held phone while driving can bring a fine of up to $200 and 5 points.","p":"Right. A hand-held phone can cost you 5 points."},"es":{"q":"En Nueva York, ¿cuántos puntos puede recibir un conductor adulto por una primera infracción de hablar con el teléfono en la mano mientras maneja?","o":["Ningún punto","2 puntos","5 puntos","11 puntos"],"h1":"Es más que por la mayoría de las infracciones menores.","h2":"En Nueva York, una primera infracción por usar el teléfono en la mano mientras maneja puede traer una multa de hasta $200 y 5 puntos.","p":"Correcto. El teléfono en la mano le puede costar 5 puntos."},"zh":{"q":"在 New York，成年司机第一次开车时用手持电话通话，会被记多少分？","o":["不记分","2 分","5 分","11 分"],"h1":"比大多数小违规的分数多。","h2":"在 New York，第一次开车时使用手持电话，可能被罚款最高 $200 并记 5 分。","p":"对。用手持电话可能让你被记 5 分。"},"vi":{"q":"Ở New York, người lái là người lớn có thể bị bao nhiêu điểm khi vi phạm lần đầu vì nói chuyện bằng điện thoại cầm tay trong khi lái xe?","o":["Không bị điểm","2 điểm","5 điểm","11 điểm"],"h1":"Nhiều hơn so với phần lớn các vi phạm nhỏ.","h2":"Ở New York, vi phạm lần đầu vì dùng điện thoại cầm tay trong khi lái xe có thể bị phạt tối đa $200 và 5 điểm.","p":"Đúng. Dùng điện thoại cầm tay có thể làm bạn bị 5 điểm."},"tl":{"q":"Sa New York, ilang puntos ang maaaring makuha ng adult driver sa unang paglabag ng pakikipag-usap sa hand-held na telepono habang nagmamaneho?","o":["Walang puntos","2 puntos","5 puntos","11 puntos"],"h1":"Mas marami ito kaysa sa karamihan ng maliliit na paglabag.","h2":"Sa New York, ang unang paglabag sa paggamit ng hand-held na telepono habang nagmamaneho ay maaaring magdulot ng multang hanggang $200 at 5 puntos.","p":"Tama. Ang hand-held na telepono ay maaaring magdulot sa iyo ng 5 puntos."},"ar":{"q":"في New York، كم نقطة قد يحصل عليها سائق بالغ في أول مخالفة للتحدث بهاتف محمول باليد أثناء القيادة؟","o":["لا نقاط","2 نقطة","5 نقاط","11 نقطة"],"h1":"العدد أكثر من معظم المخالفات الصغيرة.","h2":"في New York، أول مخالفة لاستخدام هاتف محمول باليد أثناء القيادة قد تؤدي إلى غرامة تصل إلى $200 و5 نقاط.","p":"صحيح. الهاتف المحمول باليد قد يكلّفك 5 نقاط."},"ref":{"doc":"NY","page":52}},{"id":"ny-042","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a passenger under 16 is not buckled in. What can happen to the driver?","o":["Nothing, the passenger gets the ticket","Only a warning","A $500 fine and a suspension","A fine of $25 to $100 and 3 points"],"h1":"The driver is responsible for young passengers.","h2":"In New York, the driver can be fined $25 to $100 and get 3 points for each passenger under 16 who is not properly buckled in.","p":"Right. The driver can get a fine and 3 points."},"es":{"q":"En Nueva York, un pasajero menor de 16 años no lleva puesto el cinturón. ¿Qué le puede pasar al conductor?","o":["Nada, la multa es para el pasajero","Solo una advertencia","Una multa de $500 y una suspensión","Una multa de $25 a $100 y 3 puntos"],"h1":"El conductor es responsable de los pasajeros jóvenes.","h2":"En Nueva York, el conductor puede recibir una multa de $25 a $100 y 3 puntos por cada pasajero menor de 16 años que no esté bien abrochado.","p":"Correcto. El conductor puede recibir una multa y 3 puntos."},"zh":{"q":"在 New York，一位未满 16 岁的乘客没有系好安全带。司机会怎样？","o":["没事，乘客会收到罚单","只是警告","罚款 $500 并暂停驾照","罚款 $25 到 $100 并记 3 分"],"h1":"司机要为年幼的乘客负责。","h2":"在 New York，每有一位未满 16 岁的乘客没有正确系好安全带，司机就可能被罚款 $25 到 $100 并记 3 分。","p":"对。司机可能被罚款并记 3 分。"},"vi":{"q":"Ở New York, một hành khách dưới 16 tuổi không thắt dây an toàn. Người lái có thể bị gì?","o":["Không sao, hành khách sẽ bị phạt","Chỉ bị cảnh cáo","Bị phạt $500 và treo bằng lái","Bị phạt từ $25 đến $100 và 3 điểm"],"h1":"Người lái chịu trách nhiệm về hành khách nhỏ tuổi.","h2":"Ở New York, người lái có thể bị phạt từ $25 đến $100 và bị 3 điểm cho mỗi hành khách dưới 16 tuổi không thắt dây an toàn đúng cách.","p":"Đúng. Người lái có thể bị phạt tiền và 3 điểm."},"tl":{"q":"Sa New York, hindi naka-seatbelt ang pasaherong wala pang 16. Ano ang maaaring mangyari sa driver?","o":["Wala, ang pasahero ang makakakuha ng ticket","Babala lang","Multang $500 at suspensyon","Multang $25 hanggang $100 at 3 puntos"],"h1":"Ang driver ang may pananagutan sa mga batang pasahero.","h2":"Sa New York, maaaring multahan ang driver ng $25 hanggang $100 at bigyan ng 3 puntos para sa bawat pasaherong wala pang 16 na hindi maayos na naka-seatbelt.","p":"Tama. Maaaring makakuha ang driver ng multa at 3 puntos."},"ar":{"q":"في New York، راكب عمره أقل من 16 سنة لا يربط حزام الأمان. ماذا قد يحدث للسائق؟","o":["لا شيء، الراكب هو من يأخذ المخالفة","إنذار فقط","غرامة $500 وإيقاف الرخصة","غرامة من $25 إلى $100 و3 نقاط"],"h1":"السائق مسؤول عن الركّاب الصغار.","h2":"في New York، قد يُغرَّم السائق من $25 إلى $100 ويحصل على 3 نقاط عن كل راكب عمره أقل من 16 سنة لا يربط حزام الأمان بشكل صحيح.","p":"صحيح. قد يحصل السائق على غرامة و3 نقاط."},"ref":{"doc":"NY","page":48}},{"id":"ny-043","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, how long must a young child ride in a rear-facing car seat?","o":["Until age 2, or until the child reaches the seat's weight or height limit","Until age 6 months","Until age 1, no matter what","Until the child can walk"],"h1":"Think of a toddler's second birthday.","h2":"In New York, a child must ride rear-facing until age 2, or until the child reaches the highest weight or height the car seat allows.","p":"Right. Rear-facing until age 2 or the seat's limit."},"es":{"q":"En Nueva York, ¿hasta cuándo debe viajar un niño pequeño en un asiento de seguridad mirando hacia atrás?","o":["Hasta los 2 años, o hasta que alcance el límite de peso o altura del asiento","Hasta los 6 meses","Hasta 1 año, sin importar nada más","Hasta que el niño pueda caminar"],"h1":"Piense en el segundo cumpleaños de un niño pequeño.","h2":"En Nueva York, un niño debe viajar mirando hacia atrás hasta los 2 años, o hasta que alcance el peso o la altura máxima que permite el asiento.","p":"Correcto. Mirando hacia atrás hasta los 2 años o hasta el límite del asiento."},"zh":{"q":"在 New York，幼儿要坐后向式儿童座椅坐到什么时候？","o":["到 2 岁，或到孩子达到座椅的体重或身高上限","到 6 个月大","到 1 岁，不管其他情况","到孩子会走路"],"h1":"想想幼儿的第二个生日。","h2":"在 New York，孩子必须坐后向式座椅到 2 岁，或到孩子达到座椅允许的最高体重或身高。","p":"对。后向坐到 2 岁或到座椅的上限。"},"vi":{"q":"Ở New York, trẻ nhỏ phải ngồi ghế an toàn quay mặt về phía sau cho đến khi nào?","o":["Đến 2 tuổi, hoặc đến khi trẻ đạt giới hạn cân nặng hoặc chiều cao của ghế","Đến 6 tháng tuổi","Đến 1 tuổi, dù thế nào đi nữa","Đến khi trẻ biết đi"],"h1":"Hãy nghĩ đến sinh nhật thứ hai của em bé.","h2":"Ở New York, trẻ phải ngồi quay mặt về phía sau cho đến 2 tuổi, hoặc đến khi trẻ đạt mức cân nặng hoặc chiều cao cao nhất mà ghế cho phép.","p":"Đúng. Quay mặt về phía sau đến 2 tuổi hoặc đến giới hạn của ghế."},"tl":{"q":"Sa New York, hanggang kailan dapat nakasakay ang maliit na bata sa rear-facing na car seat?","o":["Hanggang 2 taong gulang, o hanggang maabot ng bata ang limitasyon ng timbang o taas ng upuan","Hanggang 6 na buwang gulang","Hanggang 1 taong gulang, anuman ang mangyari","Hanggang makalakad ang bata"],"h1":"Isipin ang ikalawang kaarawan ng isang toddler.","h2":"Sa New York, dapat nakasakay nang rear-facing ang bata hanggang 2 taong gulang, o hanggang maabot ng bata ang pinakamataas na timbang o taas na pinapayagan ng car seat.","p":"Tama. Rear-facing hanggang 2 taong gulang o hanggang sa limitasyon ng upuan."},"ar":{"q":"في New York، إلى متى يجب أن يجلس الطفل الصغير في مقعد سيارة مواجه للخلف؟","o":["حتى عمر سنتين (2)، أو حتى يصل الطفل إلى حد الوزن أو الطول للمقعد","حتى عمر 6 أشهر","حتى عمر سنة واحدة (1)، مهما كان","حتى يستطيع الطفل المشي"],"h1":"فكّر في عيد الميلاد الثاني للطفل الصغير.","h2":"في New York، يجب أن يجلس الطفل في مقعد مواجه للخلف حتى عمر سنتين (2)، أو حتى يصل إلى أعلى وزن أو طول يسمح به المقعد.","p":"صحيح. مواجهًا للخلف حتى عمر سنتين أو حتى حد المقعد."},"ref":{"doc":"NY","page":48}},{"id":"ny-044","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, when may you use tires with metal studs?","o":["All year","Only from October 16 through April 30","Only in December, January and February","Never"],"h1":"Think of the cold part of the year, from fall to spring.","h2":"In New York, tires with metal studs may be used only from October 16 through April 30.","p":"Right. Studded tires are allowed from October 16 to April 30."},"es":{"q":"En Nueva York, ¿cuándo puede usar llantas con clavos de metal?","o":["Todo el año","Solo del 16 de octubre al 30 de abril","Solo en diciembre, enero y febrero","Nunca"],"h1":"Piense en la parte fría del año, del otoño a la primavera.","h2":"En Nueva York, las llantas con clavos de metal solo se pueden usar del 16 de octubre al 30 de abril.","p":"Correcto. Las llantas con clavos se permiten del 16 de octubre al 30 de abril."},"zh":{"q":"在 New York，什么时候可以使用带金属钉的轮胎？","o":["全年","只在 10 月 16 日到 4 月 30 日","只在十二月、一月和二月","永远不可以"],"h1":"想想一年中寒冷的时候，从秋天到春天。","h2":"在 New York，带金属钉的轮胎只能在 10 月 16 日到 4 月 30 日使用。","p":"对。钉胎从 10 月 16 日到 4 月 30 日可以用。"},"vi":{"q":"Ở New York, khi nào bạn được dùng lốp xe có đinh kim loại?","o":["Cả năm","Chỉ từ ngày 16 tháng 10 đến ngày 30 tháng 4","Chỉ trong tháng 12, tháng 1 và tháng 2","Không bao giờ"],"h1":"Hãy nghĩ đến phần lạnh trong năm, từ mùa thu đến mùa xuân.","h2":"Ở New York, lốp xe có đinh kim loại chỉ được dùng từ ngày 16 tháng 10 đến ngày 30 tháng 4.","p":"Đúng. Lốp có đinh được phép dùng từ ngày 16 tháng 10 đến ngày 30 tháng 4."},"tl":{"q":"Sa New York, kailan mo maaaring gamitin ang mga gulong na may metal studs?","o":["Buong taon","Mula Oktubre 16 hanggang Abril 30 lang","Sa Disyembre, Enero at Pebrero lang","Hindi kailanman"],"h1":"Isipin ang malamig na bahagi ng taon, mula taglagas hanggang tagsibol.","h2":"Sa New York, ang mga gulong na may metal studs ay maaaring gamitin mula Oktubre 16 hanggang Abril 30 lang.","p":"Tama. Pinapayagan ang studded tires mula Oktubre 16 hanggang Abril 30."},"ar":{"q":"في New York، متى يُسمح لك باستخدام إطارات فيها مسامير معدنية؟","o":["طوال السنة","فقط من 16 أكتوبر إلى 30 أبريل","فقط في ديسمبر ويناير وفبراير","أبدًا"],"h1":"فكّر في الجزء البارد من السنة، من الخريف إلى الربيع.","h2":"في New York، يُسمح باستخدام الإطارات ذات المسامير المعدنية فقط من 16 أكتوبر إلى 30 أبريل.","p":"صحيح. الإطارات ذات المسامير مسموحة من 16 أكتوبر إلى 30 أبريل."},"ref":{"doc":"NY","page":64}},{"id":"ny-045","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, which bicycle riders must wear an approved helmet by state law?","o":["Only riders under age 5","All riders of every age","Riders and passengers ages 1 to 13","Only riders on highways"],"h1":"State law covers children, not adults.","h2":"In New York, bicycle riders and passengers ages 1 to 13 must wear an approved helmet.","p":"Right. Ages 1 to 13 must wear a helmet."},"es":{"q":"En Nueva York, ¿qué ciclistas deben usar un casco aprobado según la ley estatal?","o":["Solo los menores de 5 años","Todos, de cualquier edad","Ciclistas y pasajeros de 1 a 13 años","Solo los que van por autopistas"],"h1":"La ley estatal cubre a los niños, no a los adultos.","h2":"En Nueva York, los ciclistas y sus pasajeros de 1 a 13 años deben usar un casco aprobado.","p":"Correcto. De 1 a 13 años deben usar casco."},"zh":{"q":"在 New York，按州法律，哪些骑自行车的人必须戴合格的头盔？","o":["只有未满 5 岁的骑车人","所有年龄的骑车人","1 到 13 岁的骑车人和乘坐者","只有在高速公路上骑车的人"],"h1":"州法律管的是孩子，不是成年人。","h2":"在 New York，1 到 13 岁的自行车骑车人和乘坐者必须戴合格的头盔。","p":"对。1 到 13 岁必须戴头盔。"},"vi":{"q":"Ở New York, theo luật tiểu bang, những người đi xe đạp nào phải đội mũ bảo hiểm được chấp thuận?","o":["Chỉ người đi xe dưới 5 tuổi","Mọi người đi xe ở mọi lứa tuổi","Người đi xe và người ngồi sau từ 1 đến 13 tuổi","Chỉ người đi xe trên xa lộ"],"h1":"Luật tiểu bang áp dụng cho trẻ em, không phải người lớn.","h2":"Ở New York, người đi xe đạp và người ngồi sau từ 1 đến 13 tuổi phải đội mũ bảo hiểm được chấp thuận.","p":"Đúng. Từ 1 đến 13 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa New York, aling mga nagbibisikleta ang dapat magsuot ng aprubadong helmet ayon sa batas ng estado?","o":["Mga nagbibisikletang wala pang 5 lang","Lahat ng nagbibisikleta sa anumang edad","Mga nagbibisikleta at pasaherong edad 1 hanggang 13","Mga nagbibisikleta sa highway lang"],"h1":"Mga bata ang sakop ng batas ng estado, hindi ang mga adult.","h2":"Sa New York, ang mga nagbibisikleta at pasaherong edad 1 hanggang 13 ay dapat magsuot ng aprubadong helmet.","p":"Tama. Ang edad 1 hanggang 13 ay dapat magsuot ng helmet."},"ar":{"q":"في New York، أيّ راكبي الدراجات الهوائية يجب أن يلبسوا خوذة معتمدة بحسب قانون الولاية؟","o":["فقط الراكبون الذين عمرهم أقل من 5 سنوات","كل الراكبين من كل الأعمار","الراكبون والركّاب من عمر 1 إلى 13 سنة","فقط الراكبون على الطرق السريعة"],"h1":"قانون الولاية يشمل الأطفال، لا البالغين.","h2":"في New York، يجب على راكبي الدراجات الهوائية والركّاب معهم من عمر 1 إلى 13 سنة أن يلبسوا خوذة معتمدة.","p":"صحيح. من عمر 1 إلى 13 سنة يجب لبس الخوذة."},"ref":{"doc":"NY","page":69}},{"id":"ny-046","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, on a two-way road, an ambulance with its siren on is coming toward you in the opposite lane. What must you do?","o":["Keep driving, it is not in your lane","Speed up to clear the way","Stop right where you are, in your lane","Pull over to the right edge and stop"],"h1":"The rule is the same no matter which direction it comes from.","h2":"In New York, you must pull over to the right edge and stop for an emergency vehicle, even when it is coming toward you in the opposite lane of a two-way road.","p":"Right. Pull over and stop, even for the opposite lane."},"es":{"q":"En Nueva York, en una calle de doble sentido, una ambulancia con la sirena encendida viene hacia usted por el carril contrario. ¿Qué debe hacer?","o":["Seguir manejando, no está en su carril","Acelerar para abrir paso","Detenerse donde está, en su carril","Orillarse a la derecha y detenerse"],"h1":"La regla es la misma venga de donde venga.","h2":"En Nueva York, usted debe orillarse a la derecha y detenerse ante un vehículo de emergencia, aunque venga hacia usted por el carril contrario de una calle de doble sentido.","p":"Correcto. Oríllese y deténgase, aunque venga por el carril contrario."},"zh":{"q":"在 New York，在双向道路上，一辆开着警笛的救护车在对面车道朝你开来。你必须怎么做？","o":["继续开，它不在你的车道上","加速让开路","就在你的车道里原地停下","靠到右边路边停下"],"h1":"不管它从哪个方向来，规则都一样。","h2":"在 New York，你必须靠到右边路边停下，给紧急车辆让路，即使它是在双向道路的对面车道朝你开来。","p":"对。即使是对面车道，也要靠边停下。"},"vi":{"q":"Ở New York, trên đường hai chiều, một xe cứu thương đang hú còi chạy về phía bạn ở làn đường ngược chiều. Bạn phải làm gì?","o":["Cứ lái tiếp, nó không ở làn của bạn","Tăng tốc để nhường đường","Dừng ngay tại chỗ, trong làn của bạn","Tấp vào sát lề bên phải và dừng lại"],"h1":"Quy định giống nhau dù xe đến từ hướng nào.","h2":"Ở New York, bạn phải tấp vào sát lề bên phải và dừng lại cho xe khẩn cấp, ngay cả khi xe đang chạy về phía bạn ở làn ngược chiều của đường hai chiều.","p":"Đúng. Tấp vào lề và dừng lại, ngay cả với làn ngược chiều."},"tl":{"q":"Sa New York, sa two-way na kalsada, may ambulansyang naka-siren na papalapit sa iyo sa kabilang lane. Ano ang dapat mong gawin?","o":["Magpatuloy sa pagmamaneho, wala ito sa lane mo","Bumilis para magbigay-daan","Huminto kung nasaan ka, sa lane mo","Tumabi sa kanang gilid at huminto"],"h1":"Pareho ang patakaran saanmang direksyon ito manggaling.","h2":"Sa New York, dapat kang tumabi sa kanang gilid at huminto para sa emergency vehicle, kahit papalapit ito sa iyo sa kabilang lane ng two-way na kalsada.","p":"Tama. Tumabi at huminto, kahit para sa kabilang lane."},"ar":{"q":"في New York، على طريق باتجاهين، سيارة إسعاف تشغّل صفّارتها قادمة نحوك في المسار المقابل. ماذا يجب أن تفعل؟","o":["استمر في القيادة، فهي ليست في مسارك","زِد سرعتك لتفسح الطريق","توقّف في مكانك تمامًا، في مسارك","اقترب من الحافة اليمنى وتوقّف"],"h1":"القاعدة نفسها مهما كان الاتجاه الذي تأتي منه.","h2":"في New York، يجب أن تقترب من الحافة اليمنى وتتوقّف لمركبة الطوارئ، حتى عندما تكون قادمة نحوك في المسار المقابل على طريق باتجاهين.","p":"صحيح. اقترب من الحافة وتوقّف، حتى للمسار المقابل."},"ref":{"doc":"NY","page":35}},{"id":"ny-047","scope":"NY","cat":"signals","sign":null,"c":0,"en":{"q":"In New York, a personal car shows a flashing blue light. Who is usually driving it?","o":["A volunteer firefighter answering an alarm","A police officer making a traffic stop","A snowplow driver","A school bus driver"],"h1":"Green lights are used by volunteer ambulance members.","h2":"In New York, a flashing blue light on a personal car usually means a volunteer firefighter answering an alarm; it is not an emergency vehicle, but you should let it pass if you safely can.","p":"Right. Blue light means a volunteer firefighter."},"es":{"q":"En Nueva York, un auto particular lleva una luz azul intermitente. ¿Quién lo maneja normalmente?","o":["Un bombero voluntario que acude a una alarma","Un policía que detiene a un conductor","El conductor de un quitanieves","El conductor de un autobús escolar"],"h1":"Las luces verdes las usan los voluntarios de ambulancia.","h2":"En Nueva York, una luz azul intermitente en un auto particular suele indicar un bombero voluntario que acude a una alarma; no es un vehículo de emergencia, pero debe dejarlo pasar si puede hacerlo con seguridad.","p":"Correcto. La luz azul indica un bombero voluntario."},"zh":{"q":"在 New York，一辆私家车闪着蓝灯。开车的通常是谁？","o":["赶去处理警报的志愿消防员","正在拦车的警察","扫雪车司机","校车司机"],"h1":"绿灯是志愿救护队员用的。","h2":"在 New York，私家车上闪蓝灯通常表示是赶去处理警报的志愿消防员；它不是紧急车辆，但如果安全，你应该让它先过。","p":"对。蓝灯表示志愿消防员。"},"vi":{"q":"Ở New York, một xe cá nhân có đèn xanh dương nhấp nháy. Người lái thường là ai?","o":["Một lính cứu hỏa tình nguyện đang đi ứng cứu báo động","Một cảnh sát đang chặn xe","Một tài xế xe ủi tuyết","Một tài xế xe buýt trường học"],"h1":"Đèn xanh lá được các thành viên cứu thương tình nguyện dùng.","h2":"Ở New York, đèn xanh dương nhấp nháy trên xe cá nhân thường có nghĩa là một lính cứu hỏa tình nguyện đang đi ứng cứu báo động; đó không phải là xe khẩn cấp, nhưng bạn nên để xe đó đi qua nếu có thể làm an toàn.","p":"Đúng. Đèn xanh dương nghĩa là lính cứu hỏa tình nguyện."},"tl":{"q":"Sa New York, may personal na kotseng may kumikislap na asul na ilaw. Sino ang karaniwang nagmamaneho nito?","o":["Isang volunteer firefighter na tumutugon sa alarma","Isang pulis na nagpapahinto ng sasakyan","Isang driver ng snowplow","Isang driver ng school bus"],"h1":"Ang berdeng ilaw ay ginagamit ng mga volunteer na miyembro ng ambulansya.","h2":"Sa New York, ang kumikislap na asul na ilaw sa personal na kotse ay karaniwang nangangahulugang isang volunteer firefighter na tumutugon sa alarma; hindi ito emergency vehicle, pero dapat mo itong padaanin kung ligtas mong magagawa.","p":"Tama. Ang asul na ilaw ay nangangahulugang volunteer firefighter."},"ar":{"q":"في New York، سيارة شخصية عليها ضوء أزرق وامض. من يقودها عادةً؟","o":["رجل إطفاء متطوّع ذاهب للاستجابة لإنذار","شرطي يوقف سيارة","سائق كاسحة ثلج","سائق حافلة مدرسية"],"h1":"الأضواء الخضراء يستخدمها أعضاء الإسعاف المتطوّعون.","h2":"في New York، الضوء الأزرق الوامض على سيارة شخصية يعني عادةً رجل إطفاء متطوّعًا ذاهبًا للاستجابة لإنذار؛ إنها ليست مركبة طوارئ، لكن ينبغي أن تتركها تمرّ إذا استطعت ذلك بأمان.","p":"صحيح. الضوء الأزرق يعني رجل إطفاء متطوّعًا."},"ref":{"doc":"NY","page":35}},{"id":"ny-048","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York, you may not make a U-turn where other drivers cannot see your car from how far away?","o":["100 feet","500 feet","50 feet","1 mile"],"h1":"It is a long distance, more than the length of a football field.","h2":"In New York, you may not make a U-turn near a hilltop, a curve or any place where other drivers cannot see your car from 500 feet away in either direction.","p":"Right. Drivers must be able to see you from 500 feet."},"es":{"q":"En Nueva York, no puede dar una vuelta en U donde otros conductores no puedan ver su auto desde ¿qué distancia?","o":["100 pies","500 pies","50 pies","1 milla"],"h1":"Es una distancia larga, más que el largo de un campo de fútbol americano.","h2":"En Nueva York, no puede dar una vuelta en U cerca de la cima de una colina, en una curva ni en ningún lugar donde otros conductores no puedan ver su auto desde 500 pies en cualquier dirección.","p":"Correcto. Los demás deben poder verlo desde 500 pies."},"zh":{"q":"在 New York，在其他司机从多远都看不到你的车的地方，你不可以掉头（U-turn）？","o":["100 英尺","500 英尺","50 英尺","1 英里"],"h1":"这是很长的距离，比一个橄榄球场还长。","h2":"在 New York，在山顶、弯道附近，或任何其他司机从两个方向 500 英尺外都看不到你的车的地方，你不可以掉头。","p":"对。其他司机必须能从 500 英尺外看到你。"},"vi":{"q":"Ở New York, bạn không được quay đầu xe (U-turn) ở nơi mà các người lái khác không thể thấy xe bạn từ khoảng cách bao xa?","o":["100 feet","500 feet","50 feet","1 dặm"],"h1":"Đó là một khoảng cách dài, hơn chiều dài một sân bóng bầu dục.","h2":"Ở New York, bạn không được quay đầu xe gần đỉnh đồi, khúc cua hoặc bất cứ nơi nào mà các người lái khác không thể thấy xe bạn từ 500 feet ở cả hai hướng.","p":"Đúng. Các người lái khác phải thấy được bạn từ 500 feet."},"tl":{"q":"Sa New York, hindi ka maaaring mag-U-turn kung saan hindi makikita ng ibang driver ang kotse mo mula sa gaano kalayo?","o":["100 feet","500 feet","50 feet","1 milya"],"h1":"Malayong distansya ito, mas mahaba pa sa isang football field.","h2":"Sa New York, hindi ka maaaring mag-U-turn malapit sa tuktok ng burol, sa kurba o sa anumang lugar kung saan hindi makikita ng ibang driver ang kotse mo mula 500 feet ang layo sa alinmang direksyon.","p":"Tama. Dapat kang makita ng ibang driver mula 500 feet."},"ar":{"q":"في New York، لا يجوز لك أن تستدير للخلف (U-turn) في مكان لا يستطيع السائقون الآخرون أن يروا سيارتك فيه من أي مسافة؟","o":["100 قدم (feet)","500 قدم (feet)","50 قدمًا (feet)","1 ميل"],"h1":"إنها مسافة طويلة، أطول من ملعب كرة قدم أمريكية.","h2":"في New York، لا يجوز لك أن تستدير للخلف قرب قمة تلّ أو منعطف أو أي مكان لا يستطيع السائقون الآخرون أن يروا سيارتك فيه من مسافة 500 قدم (feet) في أي من الاتجاهين.","p":"صحيح. يجب أن يستطيع السائقون رؤيتك من مسافة 500 قدم."},"ref":{"doc":"NY","page":37}},{"id":"ny-049","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, you are about to pass a person riding a horse along the road. What must you not do?","o":["Slow down","Leave extra space","Sound your horn","Pass when it is safe"],"h1":"A loud noise can scare the horse.","h2":"In New York, it is against the law to sound your horn when you come near or pass a horse.","p":"Right. Never honk near a horse."},"es":{"q":"En Nueva York, está por pasar a una persona que va a caballo por la calle. ¿Qué no debe hacer?","o":["Reducir la velocidad","Dejar más espacio","Tocar la bocina","Pasar cuando sea seguro"],"h1":"Un ruido fuerte puede asustar al caballo.","h2":"En Nueva York, es ilegal tocar la bocina cuando se acerca a un caballo o lo pasa.","p":"Correcto. Nunca toque la bocina cerca de un caballo."},"zh":{"q":"在 New York，你要超过一个在路边骑马的人。你一定不可以做什么？","o":["减速","多留空间","按喇叭","安全时再超过"],"h1":"很大的声音会吓到马。","h2":"在 New York，靠近或超过马的时候按喇叭是违法的。","p":"对。在马附近千万不要按喇叭。"},"vi":{"q":"Ở New York, bạn sắp vượt qua một người đang cưỡi ngựa dọc đường. Bạn không được làm gì?","o":["Giảm tốc độ","Chừa thêm khoảng cách","Bấm còi","Vượt khi an toàn"],"h1":"Tiếng động lớn có thể làm con ngựa sợ.","h2":"Ở New York, bấm còi khi bạn đến gần hoặc vượt qua một con ngựa là phạm luật.","p":"Đúng. Không bao giờ bấm còi gần ngựa."},"tl":{"q":"Sa New York, malapit mo nang lampasan ang taong nakasakay sa kabayo sa tabi ng kalsada. Ano ang hindi mo dapat gawin?","o":["Magdahan-dahan","Mag-iwan ng dagdag na espasyo","Bumusina","Lumampas kapag ligtas na"],"h1":"Maaaring matakot ang kabayo sa malakas na ingay.","h2":"Sa New York, labag sa batas ang bumusina kapag lumalapit ka o lumalampas sa kabayo.","p":"Tama. Huwag kailanman bumusina malapit sa kabayo."},"ar":{"q":"في New York، أنت على وشك أن تتجاوز شخصًا يركب حصانًا على جانب الطريق. ما الذي يجب ألّا تفعله؟","o":["أن تخفّف السرعة","أن تترك مسافة إضافية","أن تستخدم البوق (الزمّور)","أن تتجاوز عندما يكون ذلك آمنًا"],"h1":"الصوت العالي قد يُخيف الحصان.","h2":"في New York، استخدام البوق عندما تقترب من حصان أو تتجاوزه مخالف للقانون.","p":"صحيح. لا تستخدم البوق أبدًا قرب حصان."},"ref":{"doc":"NY","page":76}},{"id":"ny-050","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, how close to a fire station driveway may you park on the same side of the street?","o":["5 feet","10 feet","15 feet","No closer than 20 feet"],"h1":"Across the street, the distance is 75 feet.","h2":"In New York, you may not park or stand within 20 feet of a fire station driveway on the same side of the street, or within 75 feet on the other side.","p":"Right. Stay at least 20 feet from a fire station driveway."},"es":{"q":"En Nueva York, ¿a qué distancia de la entrada de una estación de bomberos puede estacionarse del mismo lado de la calle?","o":["5 pies","10 pies","15 pies","No más cerca de 20 pies"],"h1":"Del otro lado de la calle, la distancia es de 75 pies.","h2":"En Nueva York, no puede estacionarse ni detenerse a menos de 20 pies de la entrada de una estación de bomberos del mismo lado de la calle, ni a menos de 75 pies del otro lado.","p":"Correcto. Manténgase por lo menos a 20 pies de la entrada de los bomberos."},"zh":{"q":"在 New York，在同一边街道上，你可以把车停在离消防站车道多近的地方？","o":["5 英尺","10 英尺","15 英尺","不能近于 20 英尺"],"h1":"在街道对面，距离是 75 英尺。","h2":"在 New York，在同一边街道上，你不可以在离消防站车道 20 英尺以内停车或停留；在对面一边是 75 英尺以内。","p":"对。要离消防站车道至少 20 英尺。"},"vi":{"q":"Ở New York, bạn được đậu xe gần lối ra vào trạm cứu hỏa đến mức nào nếu ở cùng bên đường?","o":["5 feet","10 feet","15 feet","Không gần hơn 20 feet"],"h1":"Ở bên kia đường, khoảng cách là 75 feet.","h2":"Ở New York, bạn không được đậu hoặc dừng xe trong vòng 20 feet tính từ lối ra vào trạm cứu hỏa nếu ở cùng bên đường, hoặc trong vòng 75 feet nếu ở bên kia đường.","p":"Đúng. Hãy cách lối ra vào trạm cứu hỏa ít nhất 20 feet."},"tl":{"q":"Sa New York, gaano kalapit sa driveway ng fire station ka maaaring pumarada sa parehong panig ng kalye?","o":["5 feet","10 feet","15 feet","Hindi mas malapit sa 20 feet"],"h1":"Sa kabilang panig ng kalye, 75 feet ang distansya.","h2":"Sa New York, hindi ka maaaring pumarada o tumigil sa loob ng 20 feet mula sa driveway ng fire station sa parehong panig ng kalye, o sa loob ng 75 feet sa kabilang panig.","p":"Tama. Lumayo nang hindi bababa sa 20 feet sa driveway ng fire station."},"ar":{"q":"في New York، ما أقرب مسافة يمكنك أن تركن فيها من مدخل محطة إطفاء على نفس جانب الشارع؟","o":["5 أقدام (feet)","10 أقدام (feet)","15 قدمًا (feet)","ليس أقرب من 20 قدمًا (feet)"],"h1":"على الجانب المقابل من الشارع، المسافة 75 قدمًا.","h2":"في New York، لا يجوز لك أن تركن أو تتوقّف على بعد أقل من 20 قدمًا (feet) من مدخل محطة إطفاء على نفس جانب الشارع، أو أقل من 75 قدمًا على الجانب الآخر.","p":"صحيح. ابقَ على بعد 20 قدمًا على الأقل من مدخل محطة الإطفاء."},"ref":{"doc":"NY","page":43}},{"id":"ny-051","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, from what age can a student take the written permit test online at a participating high school?","o":["15 years and 11 months","15 years","15 years and 6 months","16 years and 6 months"],"h1":"It is just one month before the permit age of 16.","h2":"In New York, students who are at least 15 years and 11 months old can take the written test online (OKTA) at a participating high school.","p":"Right. The online school test starts at 15 years and 11 months."},"es":{"q":"En Nueva York, ¿desde qué edad puede un estudiante tomar el examen escrito del permiso en línea en una escuela secundaria participante?","o":["15 años y 11 meses","15 años","15 años y 6 meses","16 años y 6 meses"],"h1":"Es solo un mes antes de la edad del permiso, 16 años.","h2":"En Nueva York, los estudiantes de por lo menos 15 años y 11 meses pueden tomar el examen escrito en línea (OKTA) en una escuela secundaria participante.","p":"Correcto. El examen en línea en la escuela empieza a los 15 años y 11 meses."},"ref":{"doc":"NY","page":10}},{"id":"ny-052","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, where may a learner permit holder NOT practice driving?","o":["On a quiet street in Buffalo","On the Taconic State Parkway in Westchester County","On a state highway in Ulster County","On a country road in Erie County"],"h1":"The rule names some parkways in one county just north of New York City.","h2":"In New York, a learner permit holder may not practice on the Cross County, Hutchinson River, Saw Mill River or Taconic State parkways in Westchester County.","p":"Right. Those Westchester parkways are off limits to permit holders."},"es":{"q":"En Nueva York, ¿dónde NO puede practicar quien tiene un permiso de aprendiz?","o":["En una calle tranquila de Buffalo","En el Taconic State Parkway en el condado de Westchester","En una carretera estatal del condado de Ulster","En un camino rural del condado de Erie"],"h1":"La regla nombra algunas vías (parkways) de un condado justo al norte de la ciudad de Nueva York.","h2":"En Nueva York, quien tiene un permiso de aprendiz no puede practicar en los parkways Cross County, Hutchinson River, Saw Mill River ni Taconic State del condado de Westchester.","p":"Correcto. Esos parkways de Westchester están prohibidos para quienes tienen permiso."},"ref":{"doc":"NY","page":13}},{"id":"ny-053","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, after you finish the 5-hour pre-licensing course in person, how long is your completion certificate valid?","o":["30 days","Six months","One year","Five years"],"h1":"Plan to take your road test within 12 months.","h2":"In New York, the certificate from an in-person pre-licensing course is valid for one year.","p":"Right. The certificate is good for one year."},"es":{"q":"En Nueva York, después de terminar en persona el curso previo a la licencia de 5 horas, ¿por cuánto tiempo es válido su certificado?","o":["30 días","Seis meses","Un año","Cinco años"],"h1":"Planee tomar el examen de manejo dentro de 12 meses.","h2":"En Nueva York, el certificado de un curso previo a la licencia tomado en persona es válido por un año.","p":"Correcto. El certificado vale por un año."},"ref":{"doc":"NY","page":14}},{"id":"ny-054","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, can a Point and Insurance Reduction Program (defensive driving) course replace the 5-hour pre-licensing course before your road test?","o":["Yes, it always counts","Yes, if you take it online","Yes, if you are over 18","No, it does not meet that requirement"],"h1":"The two courses have different purposes.","h2":"In New York, a Point and Insurance Reduction Program course does not meet the safe driving course requirement for the road test; you still need the pre-licensing course or driver education.","p":"Right. A defensive driving course does not replace the pre-licensing course."},"es":{"q":"En Nueva York, ¿puede un curso del Programa de Reducción de Puntos y Seguro (manejo defensivo) reemplazar el curso previo a la licencia de 5 horas antes del examen de manejo?","o":["Sí, siempre cuenta","Sí, si lo toma en línea","Sí, si tiene más de 18 años","No, no cumple ese requisito"],"h1":"Los dos cursos tienen fines distintos.","h2":"En Nueva York, un curso del Programa de Reducción de Puntos y Seguro no cumple el requisito del curso de manejo seguro para el examen de manejo; usted igual necesita el curso previo a la licencia o la educación vial.","p":"Correcto. El curso de manejo defensivo no reemplaza el curso previo a la licencia."},"ref":{"doc":"NY","page":14}},{"id":"ny-055","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, how often can you take a crash prevention course (PIRP) to lower the points on your record?","o":["Once every 18 months","Once every 6 months","Once every 5 years","As often as you like"],"h1":"It is a year and a half.","h2":"In New York, you can take a crash prevention course for point reduction once every 18 months.","p":"Right. Once every 18 months for point reduction."},"es":{"q":"En Nueva York, ¿cada cuánto puede tomar un curso de prevención de choques (PIRP) para bajar los puntos de su historial?","o":["Una vez cada 18 meses","Una vez cada 6 meses","Una vez cada 5 años","Todas las veces que quiera"],"h1":"Es un año y medio.","h2":"En Nueva York, puede tomar un curso de prevención de choques para reducir puntos una vez cada 18 meses.","p":"Correcto. Una vez cada 18 meses para reducir puntos."},"ref":{"doc":"NY","page":15}},{"id":"ny-056","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, after you finish a crash prevention course (PIRP), how long does your insurance discount last?","o":["One year","Three years","Five years","For life"],"h1":"It is more than one year but less than five.","h2":"In New York, a crash prevention course can lower the base rate of your liability and collision insurance by at least 10 percent for three years.","p":"Right. The insurance discount lasts three years."},"es":{"q":"En Nueva York, después de terminar un curso de prevención de choques (PIRP), ¿cuánto dura su descuento en el seguro?","o":["Un año","Tres años","Cinco años","Toda la vida"],"h1":"Es más de un año pero menos de cinco.","h2":"En Nueva York, un curso de prevención de choques puede bajar la tarifa base de su seguro de responsabilidad civil y de choque por lo menos un 10 por ciento durante tres años.","p":"Correcto. El descuento del seguro dura tres años."},"ref":{"doc":"NY","page":15}},{"id":"ny-057","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, you have a junior license and finished driver education, but you never trade it for a senior license. Until what age do the junior rules still apply to you?","o":["Age 17","Age 21","Age 18","Age 20"],"h1":"It is the age when you become an adult.","h2":"In New York, if you do not change your junior license to a senior license, the junior rules apply until you turn 18, even with a driver education certificate.","p":"Right. Without the senior license, junior rules last until 18."},"es":{"q":"En Nueva York, usted tiene licencia juvenil y terminó la educación vial, pero nunca la cambia por una licencia regular (senior). ¿Hasta qué edad se le siguen aplicando las reglas juveniles?","o":["Hasta los 17 años","Hasta los 21 años","Hasta los 18 años","Hasta los 20 años"],"h1":"Es la edad en que usted se vuelve adulto.","h2":"En Nueva York, si no cambia su licencia juvenil por una licencia regular (senior), las reglas juveniles se aplican hasta que cumpla 18 años, aunque tenga el certificado de educación vial.","p":"Correcto. Sin la licencia regular, las reglas juveniles duran hasta los 18."},"ref":{"doc":"NY","page":14}},{"id":"ny-058","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, on Long Island (Nassau and Suffolk), a junior license holder wants to drive alone at 2 p.m. to visit a friend. Is this allowed?","o":["Yes, any time between 5 a.m. and 9 p.m.","Yes, if no passengers ride along","Yes, if the trip is under 10 miles","No, alone only straight between home and work, school or a similar place"],"h1":"On Long Island, driving alone is limited to certain trips, even in the daytime.","h2":"In New York, a junior license holder on Long Island may drive alone only directly between home and work, a school course or a similar approved place, so a trip to a friend's house needs a parent, guardian or instructor in the car.","p":"Right. On Long Island, alone only for trips to work, school or similar."},"es":{"q":"En Nueva York, en Long Island (Nassau y Suffolk), quien tiene licencia juvenil quiere manejar solo a las 2 p.m. para visitar a un amigo. ¿Está permitido?","o":["Sí, a cualquier hora entre las 5 a.m. y las 9 p.m.","Sí, si no lleva pasajeros","Sí, si el viaje es de menos de 10 millas","No, solo puede manejar solo directo entre la casa y el trabajo, la escuela o un lugar similar"],"h1":"En Long Island, manejar solo está limitado a ciertos viajes, aun de día.","h2":"En Nueva York, quien tiene licencia juvenil en Long Island solo puede manejar solo directo entre la casa y el trabajo, un curso escolar o un lugar similar aprobado, así que para ir a casa de un amigo necesita a un padre, tutor o instructor en el auto.","p":"Correcto. En Long Island, solo para ir al trabajo, la escuela o algo similar."},"ref":{"doc":"NY","page":16}},{"id":"ny-059","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In upstate New York (outside New York City and Long Island), may a junior license holder drive alone at noon?","o":["Yes, driving alone is allowed between 5 a.m. and 9 p.m.","No, a parent must always ride along","Only on the way to school","Only with a letter from an employer"],"h1":"During the day, the upstate rules are the least strict in the state.","h2":"In upstate New York, a junior license holder may drive without a supervisor between 5 a.m. and 9 p.m.","p":"Right. Upstate, daytime driving alone is allowed."},"es":{"q":"En el norte del estado de Nueva York (fuera de la ciudad de Nueva York y de Long Island), ¿puede manejar solo al mediodía quien tiene licencia juvenil?","o":["Sí, puede manejar solo entre las 5 a.m. y las 9 p.m.","No, siempre debe ir un padre","Solo para ir a la escuela","Solo con una carta del empleador"],"h1":"De día, las reglas del norte del estado son las menos estrictas del estado.","h2":"En el norte del estado de Nueva York, quien tiene licencia juvenil puede manejar sin supervisor entre las 5 a.m. y las 9 p.m.","p":"Correcto. En el norte del estado se puede manejar solo de día."},"ref":{"doc":"NY","page":16}},{"id":"ny-060","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In upstate New York, a junior permit holder wants to practice at 10 p.m. Who may supervise?","o":["Any licensed driver age 21 or older","A parent, guardian, or driver education or driving school instructor, age 21 or older","Any licensed driver age 18 or older","No one, because permit holders may not drive at night upstate"],"h1":"At night the list of supervisors is shorter than during the day.","h2":"In upstate New York, from 9 p.m. to 5 a.m. a junior permit holder may drive only with a parent, guardian, or driver education or driving school instructor who is 21 or older and properly licensed.","p":"Right. At night upstate, only a parent, guardian or instructor may supervise."},"es":{"q":"En el norte del estado de Nueva York, quien tiene un permiso juvenil quiere practicar a las 10 p.m. ¿Quién puede supervisar?","o":["Cualquier conductor con licencia de 21 años o más","Un padre, tutor, o instructor de educación vial o de escuela de manejo, de 21 años o más","Cualquier conductor con licencia de 18 años o más","Nadie, porque con permiso no se puede manejar de noche en el norte del estado"],"h1":"De noche la lista de supervisores es más corta que de día.","h2":"En el norte del estado de Nueva York, de 9 p.m. a 5 a.m., quien tiene un permiso juvenil solo puede manejar con un padre, tutor, o instructor de educación vial o de escuela de manejo que tenga 21 años o más y la licencia adecuada.","p":"Correcto. De noche en el norte del estado, solo un padre, tutor o instructor puede supervisar."},"ref":{"doc":"NY","page":12}},{"id":"ny-061","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, a teen with a motorcycle learner permit is practicing. How close must the supervising driver stay?","o":["Within 50 feet","Within 5 miles","Within one-quarter mile","Anywhere in the same town"],"h1":"It is a short distance, a part of a mile.","h2":"In New York, the supervising driver of a motorcycle or moped learner must stay within one-quarter mile, and it is strongly recommended that the supervisor can see the learner at all times.","p":"Right. The supervisor stays within a quarter mile."},"es":{"q":"En Nueva York, un joven con permiso de aprendiz de motocicleta está practicando. ¿Qué tan cerca debe mantenerse el supervisor?","o":["A menos de 50 pies","A menos de 5 millas","A menos de un cuarto de milla","En cualquier parte del mismo pueblo"],"h1":"Es una distancia corta, una parte de una milla.","h2":"En Nueva York, el supervisor de un aprendiz de motocicleta o ciclomotor debe mantenerse a menos de un cuarto de milla, y se recomienda mucho que pueda verlo en todo momento.","p":"Correcto. El supervisor se queda a menos de un cuarto de milla."},"ref":{"doc":"NY","page":17}},{"id":"ny-062","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, you become a resident with an out-of-state license you got only four months ago. What must you do to get a New York license?","o":["Only turn in your old license","Only pass the vision test","Pay a fee and wait 30 days","Pass the vision, written and road tests and take the safe driving course"],"h1":"Your old license is very new, so it does not show much experience.","h2":"In New York, if your out-of-state license has been valid for less than six months, you must pass the vision, written and road tests and complete the safe driving course.","p":"Right. A license under six months old means you take all the tests."},"es":{"q":"En Nueva York, usted se vuelve residente con una licencia de otro estado que obtuvo hace solo cuatro meses. ¿Qué debe hacer para obtener una licencia de Nueva York?","o":["Solo entregar su licencia anterior","Solo pasar el examen de la vista","Pagar una tarifa y esperar 30 días","Pasar los exámenes de la vista, escrito y de manejo, y tomar el curso de manejo seguro"],"h1":"Su licencia anterior es muy nueva, así que no muestra mucha experiencia.","h2":"En Nueva York, si su licencia de otro estado ha sido válida por menos de seis meses, debe pasar los exámenes de la vista, escrito y de manejo, y completar el curso de manejo seguro.","p":"Correcto. Con una licencia de menos de seis meses, toma todos los exámenes."},"ref":{"doc":"NY","page":18}},{"id":"ny-063","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, a junior license holder is convicted of one serious traffic violation worth 3 or more points. What happens?","o":["The license is suspended for 60 days","Nothing, if it is the first violation","Only a warning letter","The license is revoked for 5 years"],"h1":"It is about two months.","h2":"In New York, a junior permit or license is suspended for 60 days after a conviction for one serious violation of 3 or more points, or for two other violations.","p":"Right. One serious violation means a 60-day suspension."},"es":{"q":"En Nueva York, quien tiene licencia juvenil es declarado culpable de una infracción grave de 3 puntos o más. ¿Qué pasa?","o":["La licencia se suspende por 60 días","Nada, si es la primera infracción","Solo una carta de advertencia","La licencia se revoca por 5 años"],"h1":"Son unos dos meses.","h2":"En Nueva York, un permiso o licencia juvenil se suspende por 60 días tras una condena por una infracción grave de 3 puntos o más, o por otras dos infracciones.","p":"Correcto. Una infracción grave significa 60 días de suspensión."},"ref":{"doc":"NY","page":19}},{"id":"ny-064","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, a driver licensed at age 18 or older is still on probation and is convicted of speeding. The license is suspended for 60 days. What happens after that?","o":["The driver gets a full license right away","A new six-month probation period begins","The driver must wait one year to drive","The driver must take the permit test again"],"h1":"The probation clock starts over.","h2":"In New York, when the 60-day suspension for a speeding conviction during probation ends, a new six-month probation period begins.","p":"Right. A new six-month probation starts."},"es":{"q":"En Nueva York, un conductor que obtuvo la licencia a los 18 años o más sigue en período de prueba y es declarado culpable de exceso de velocidad. La licencia se suspende por 60 días. ¿Qué pasa después?","o":["Recibe una licencia completa enseguida","Empieza un nuevo período de prueba de seis meses","Debe esperar un año para manejar","Debe tomar otra vez el examen del permiso"],"h1":"El período de prueba vuelve a empezar.","h2":"En Nueva York, cuando termina la suspensión de 60 días por exceso de velocidad durante el período de prueba, empieza un nuevo período de prueba de seis meses.","p":"Correcto. Empieza un nuevo período de prueba de seis meses."},"ref":{"doc":"NY","page":19}},{"id":"ny-065","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what happens if you are found guilty of three speeding or misdemeanor traffic violations within 18 months?","o":["You get a warning letter","You must take a new vision test","Your license is revoked for at least six months","Your fines double, but you keep your license"],"h1":"The license is cancelled for half a year or more.","h2":"In New York, three speeding or misdemeanor traffic violations within 18 months lead to a license revocation of at least six months.","p":"Right. Three in 18 months means at least six months of revocation."},"es":{"q":"En Nueva York, ¿qué pasa si lo declaran culpable de tres infracciones de exceso de velocidad o de tránsito de tipo delito menor en 18 meses?","o":["Recibe una carta de advertencia","Debe tomar otro examen de la vista","Su licencia se revoca por lo menos seis meses","Sus multas se duplican, pero conserva la licencia"],"h1":"La licencia se cancela por medio año o más.","h2":"En Nueva York, tres infracciones de exceso de velocidad o de tránsito de tipo delito menor en 18 meses llevan a la revocación de la licencia por lo menos seis meses.","p":"Correcto. Tres en 18 meses significa por lo menos seis meses de revocación."},"ref":{"doc":"NY","page":21}},{"id":"ny-066","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many points do you get for driving 1 to 10 mph over the speed limit?","o":["No points","1 point","6 points","3 points"],"h1":"It is the same as for running a red light.","h2":"In New York, speeding 1 to 10 mph over the posted limit adds 3 points to your driving record.","p":"Right. Up to 10 mph over is 3 points."},"es":{"q":"En Nueva York, ¿cuántos puntos recibe por manejar de 1 a 10 mph por encima del límite de velocidad?","o":["Ningún punto","1 punto","6 puntos","3 puntos"],"h1":"Es lo mismo que por pasarse una luz roja.","h2":"En Nueva York, manejar de 1 a 10 mph por encima del límite indicado suma 3 puntos a su historial de manejo.","p":"Correcto. Hasta 10 mph de más son 3 puntos."},"ref":{"doc":"NY","page":22}},{"id":"ny-067","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, how many points are added to your record for failing to stop for a school bus?","o":["8 points","2 points","3 points","5 points"],"h1":"It is one of the highest point values for one violation, below only 11.","h2":"In New York, failing to stop for a school bus adds 8 points to your driving record.","p":"Right. Not stopping for a school bus costs 8 points."},"es":{"q":"En Nueva York, ¿cuántos puntos se suman a su historial por no detenerse ante un autobús escolar?","o":["8 puntos","2 puntos","3 puntos","5 puntos"],"h1":"Es uno de los valores más altos por una sola infracción, solo por debajo de 11.","h2":"En Nueva York, no detenerse ante un autobús escolar suma 8 puntos a su historial de manejo.","p":"Correcto. No detenerse ante un autobús escolar cuesta 8 puntos."},"ref":{"doc":"NY","page":22}},{"id":"ny-068","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, you get six points for traffic violations within 18 months. What extra charge must you pay the DMV?","o":["A one-time $25 fee","$100 a year for three years","$500 a year for five years","Nothing extra, only the fines"],"h1":"This Driver Responsibility Assessment is paid every year for a few years.","h2":"In New York, six points within 18 months bring a Driver Responsibility Assessment of $100 a year for three years, plus $25 a year for each extra point.","p":"Right. Six points means $100 a year for three years."},"es":{"q":"En Nueva York, usted acumula seis puntos por infracciones de tránsito en 18 meses. ¿Qué cargo adicional debe pagar al DMV?","o":["Una tarifa única de $25","$100 al año durante tres años","$500 al año durante cinco años","Nada adicional, solo las multas"],"h1":"Este cargo (Driver Responsibility Assessment) se paga cada año durante algunos años.","h2":"En Nueva York, seis puntos en 18 meses traen un cargo de responsabilidad del conductor de $100 al año durante tres años, más $25 al año por cada punto adicional.","p":"Correcto. Seis puntos significan $100 al año durante tres años."},"ref":{"doc":"NY","page":23}},{"id":"ny-069","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"It is less than the $25,000 needed for injury to one person.","h2":"New York requires at least $10,000 of liability insurance for property damage in one crash.","p":"Right. The minimum for property damage is $10,000."},"es":{"q":"En Nueva York, ¿cuál es el seguro mínimo de responsabilidad civil por daños a la propiedad de otras personas en un choque?","o":["$1,000","$5,000","$10,000","$100,000"],"h1":"Es menos que los $25,000 que se exigen por lesiones a una persona.","h2":"Nueva York exige por lo menos $10,000 de seguro de responsabilidad civil por daños a la propiedad en un choque.","p":"Correcto. El mínimo por daños a la propiedad es $10,000."},"ref":{"doc":"NY","page":27}},{"id":"ny-070","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, what is the minimum liability insurance for the death of one person in a crash?","o":["$10,000","$25,000","$100,000","$50,000"],"h1":"It is twice the amount required for injury to one person.","h2":"New York requires at least $50,000 of liability insurance for the death of one person, and $100,000 for the death of two or more people.","p":"Right. The minimum for the death of one person is $50,000."},"es":{"q":"En Nueva York, ¿cuál es el seguro mínimo de responsabilidad civil por la muerte de una persona en un choque?","o":["$10,000","$25,000","$100,000","$50,000"],"h1":"Es el doble de lo que se exige por lesiones a una persona.","h2":"Nueva York exige por lo menos $50,000 de seguro de responsabilidad civil por la muerte de una persona, y $100,000 por la muerte de dos o más personas.","p":"Correcto. El mínimo por la muerte de una persona es $50,000."},"ref":{"doc":"NY","page":27}},{"id":"ny-071","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, you are going to stop insuring your car. What must you do before the insurance ends?","o":["Turn in the license plates at a motor vehicle office","Just park the car and stop driving it","Take off the registration sticker","Tell only your insurance company"],"h1":"A registered car must always be insured, so the registration must end first.","h2":"In New York, before your liability insurance ends, you must turn in your license plates at a state or county motor vehicle office, or you may face civil penalties and a suspension.","p":"Right. Turn in the plates before the insurance ends."},"es":{"q":"En Nueva York, usted va a dejar de asegurar su auto. ¿Qué debe hacer antes de que termine el seguro?","o":["Entregar las placas en una oficina de vehículos motorizados","Solo estacionar el auto y no manejarlo","Quitar la calcomanía de registro","Avisarle solo a su compañía de seguros"],"h1":"Un auto registrado siempre debe tener seguro, así que primero debe terminar el registro.","h2":"En Nueva York, antes de que termine su seguro de responsabilidad civil, debe entregar las placas en una oficina estatal o del condado de vehículos motorizados; si no, puede recibir multas civiles y una suspensión.","p":"Correcto. Entregue las placas antes de que termine el seguro."},"ref":{"doc":"NY","page":27}},{"id":"ny-072","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, you buy a used car from a private seller, not a dealer. How soon after you register it must you get it inspected?","o":["Within 30 days","Within 10 days","Within 6 months","Before the next winter"],"h1":"It is less than two weeks.","h2":"In New York, if you buy a vehicle from someone who is not a New York dealer, you must have it inspected within 10 days after you register it.","p":"Right. Get it inspected within 10 days."},"es":{"q":"En Nueva York, usted compra un auto usado a un vendedor particular, no a un concesionario. ¿En cuánto tiempo después de registrarlo debe hacerlo inspeccionar?","o":["Dentro de 30 días","Dentro de 10 días","Dentro de 6 meses","Antes del próximo invierno"],"h1":"Es menos de dos semanas.","h2":"En Nueva York, si compra un vehículo a alguien que no es un concesionario de Nueva York, debe hacerlo inspeccionar dentro de los 10 días después de registrarlo.","p":"Correcto. Hágalo inspeccionar dentro de 10 días."},"ref":{"doc":"NY","page":27}},{"id":"ny-073","scope":"NY","cat":"signals","sign":null,"c":2,"en":{"q":"In New York, you come to an intersection and the traffic lights are not working. What must you do?","o":["Drive through slowly without stopping","Treat it like a YIELD sign","Stop as you would for a STOP sign, then follow the right-of-way rules","Flash your headlights and go first"],"h1":"Think of the sign with eight sides.","h2":"In New York, if the traffic lights are out or not working, you must stop as you would at a STOP sign and then follow the right-of-way rules, unless a traffic officer directs you.","p":"Right. A dark signal is treated like a STOP sign."},"es":{"q":"En Nueva York, llega a una intersección y los semáforos no funcionan. ¿Qué debe hacer?","o":["Pasar despacio sin detenerse","Tratarlo como una señal de CEDA EL PASO","Detenerse como ante una señal de ALTO y luego seguir las reglas de derecho de paso","Hacer cambio de luces y pasar primero"],"h1":"Piense en la señal de ocho lados.","h2":"En Nueva York, si los semáforos están apagados o no funcionan bien, debe detenerse como ante una señal de ALTO y luego seguir las reglas de derecho de paso, salvo que un agente de tránsito le indique otra cosa.","p":"Correcto. Un semáforo apagado se trata como una señal de ALTO."},"ref":{"doc":"NY","page":30}},{"id":"ny-074","scope":"NY","cat":"signals","sign":null,"c":3,"en":{"q":"In New York (outside New York City), when may you turn left on a steady red light?","o":["Never","Whenever no cars are coming","Only at night","From a one-way road onto another one-way road, after a full stop"],"h1":"Both roads must carry traffic in only one direction.","h2":"In New York, you may turn left on a steady red light only from a one-way road onto another one-way road, after you stop fully and yield to traffic and pedestrians.","p":"Right. Left on red is only from one-way to one-way."},"es":{"q":"En Nueva York (fuera de la ciudad de Nueva York), ¿cuándo puede dar vuelta a la izquierda con la luz roja fija?","o":["Nunca","Siempre que no vengan autos","Solo de noche","De una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Nueva York, puede dar vuelta a la izquierda con la luz roja fija solo de una calle de un solo sentido a otra de un solo sentido, después de detenerse por completo y ceder el paso al tráfico y a los peatones.","p":"Correcto. A la izquierda con luz roja solo de un solo sentido a un solo sentido."},"ref":{"doc":"NY","page":31}},{"id":"ny-075","scope":"NY","cat":"signals","sign":null,"c":0,"en":{"q":"In New York, a flashing yellow X is lit above your lane. What does it mean?","o":["You may use this lane only to turn left","Move out of this lane now","Do not drive in this lane","The lane is open to all traffic"],"h1":"The flashing X is about one kind of turn.","h2":"In New York, a flashing yellow X above a lane means the lane may be used only for left turns.","p":"Right. A flashing yellow X means left turns only."},"es":{"q":"En Nueva York, una X amarilla intermitente está encendida sobre su carril. ¿Qué significa?","o":["Puede usar este carril solo para dar vuelta a la izquierda","Salga de este carril ahora","No maneje en este carril","El carril está abierto para todo el tráfico"],"h1":"La X intermitente tiene que ver con un tipo de vuelta.","h2":"En Nueva York, una X amarilla intermitente sobre un carril significa que el carril solo se puede usar para dar vuelta a la izquierda.","p":"Correcto. La X amarilla intermitente significa solo vuelta a la izquierda."},"ref":{"doc":"NY","page":31}},{"id":"ny-076","scope":"NY","cat":"signals","sign":null,"c":1,"en":{"q":"In New York, may the driver of a school bus carrying students turn right on a red light?","o":["Yes, after a full stop","No, never","Yes, if no children are crossing","Only outside cities"],"h1":"There is a special rule just for school buses with students on board.","h2":"In New York, the driver of a school bus carrying students may not turn right on any red light.","p":"Right. A school bus with students never turns right on red."},"es":{"q":"En Nueva York, ¿puede el conductor de un autobús escolar con estudiantes dar vuelta a la derecha con la luz roja?","o":["Sí, después de detenerse por completo","No, nunca","Sí, si no cruzan niños","Solo fuera de las ciudades"],"h1":"Hay una regla especial solo para autobuses escolares con estudiantes.","h2":"En Nueva York, el conductor de un autobús escolar con estudiantes no puede dar vuelta a la derecha con ninguna luz roja.","p":"Correcto. Un autobús escolar con estudiantes nunca da vuelta a la derecha con luz roja."},"ref":{"doc":"NY","page":31}},{"id":"ny-077","scope":"NY","cat":"signals","sign":null,"c":2,"en":{"q":"In New York, how far before a turn or lane change must you start to signal?","o":["At least 20 feet","At least 50 feet","At least 100 feet","At least 1,000 feet"],"h1":"It is about one-third the length of a football field.","h2":"New York law requires you to signal a turn or lane change at least 100 feet before you make it.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Nueva York, ¿a qué distancia antes de una vuelta o un cambio de carril debe empezar a señalar?","o":["Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 1,000 pies"],"h1":"Es más o menos un tercio del largo de un campo de fútbol americano.","h2":"La ley de Nueva York exige señalar una vuelta o un cambio de carril por lo menos 100 pies antes de hacerlo.","p":"Correcto. Señale por lo menos 100 pies antes."},"ref":{"doc":"NY","page":36}},{"id":"ny-078","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, on a city street, the line beside a diamond lane is broken (dashed) in some places. When may a regular car, not a carpool or bus, enter the lane there?","o":["Any time traffic is heavy","To pass a slow car","To park for a few minutes","To make a right turn at the next intersection"],"h1":"Think about where a car that will turn right must be.","h2":"In New York, where the line beside a diamond lane on a city street is broken, cars that do not meet the lane's rules may enter it only to make a right turn at the next intersection.","p":"Right. You may enter only to turn right at the next corner."},"es":{"q":"En Nueva York, en una calle de la ciudad, la línea al lado de un carril con diamante es discontinua en algunos tramos. ¿Cuándo puede entrar allí un auto común, que no es de viaje compartido ni autobús?","o":["Siempre que haya mucho tráfico","Para pasar a un auto lento","Para estacionarse unos minutos","Para dar vuelta a la derecha en la próxima intersección"],"h1":"Piense dónde debe estar un auto que va a dar vuelta a la derecha.","h2":"En Nueva York, donde la línea al lado de un carril con diamante en una calle de la ciudad es discontinua, los autos que no cumplen las reglas del carril solo pueden entrar para dar vuelta a la derecha en la próxima intersección.","p":"Correcto. Solo puede entrar para dar vuelta a la derecha en la próxima esquina."},"ref":{"doc":"NY","page":33}},{"id":"ny-079","scope":"NY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New York, where is it against the law to make a U-turn?","o":["In a school zone","At a green left-turn arrow, when no sign forbids it","On a narrow two-way street where drivers can see you from 500 feet","From the left part of the lane nearest the center line"],"h1":"Think of places where many children walk.","h2":"In New York, it is against the law to make a U-turn in a school zone.","p":"Right. No U-turns in a school zone."},"es":{"q":"En Nueva York, ¿dónde es ilegal dar una vuelta en U?","o":["En una zona escolar","Con una flecha verde de vuelta a la izquierda, si ninguna señal lo prohíbe","En una calle angosta de doble sentido donde los conductores lo ven desde 500 pies","Desde la parte izquierda del carril más cercano a la línea central"],"h1":"Piense en lugares donde caminan muchos niños.","h2":"En Nueva York, es ilegal dar una vuelta en U en una zona escolar.","p":"Correcto. No se dan vueltas en U en una zona escolar."},"ref":{"doc":"NY","page":37}},{"id":"ny-080","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York, on a two-way road, you may not pass on the left when you are within how many feet of a railroad crossing?","o":["50 feet","100 feet","500 feet","1,000 feet"],"h1":"The same distance applies near a bridge or tunnel when your view is blocked.","h2":"In New York, you may not pass on the left within 100 feet of a railroad crossing on a two-way road.","p":"Right. No passing within 100 feet of a railroad crossing."},"es":{"q":"En Nueva York, en una calle de doble sentido, no puede pasar por la izquierda cuando está a menos de ¿cuántos pies de un cruce de tren?","o":["50 pies","100 pies","500 pies","1,000 pies"],"h1":"La misma distancia se aplica cerca de un puente o túnel cuando no puede ver bien.","h2":"En Nueva York, no puede pasar por la izquierda a menos de 100 pies de un cruce de tren en una calle de doble sentido.","p":"Correcto. No se pasa a menos de 100 pies de un cruce de tren."},"ref":{"doc":"NY","page":39}},{"id":"ny-081","scope":"NY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New York, how close may you park to a traffic light, STOP sign or YIELD sign?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"It is more than the 20 feet you must leave from a crosswalk at an intersection.","h2":"In New York, you may not park or stand within 30 feet of a traffic light, STOP sign or YIELD sign.","p":"Right. Stay 30 feet away from a light or sign."},"es":{"q":"En Nueva York, ¿qué tan cerca de un semáforo o de una señal de ALTO o CEDA EL PASO puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Es más que los 20 pies que debe dejar desde un cruce peatonal en una intersección.","h2":"En Nueva York, no puede estacionarse ni detenerse a menos de 30 pies de un semáforo o de una señal de ALTO o CEDA EL PASO.","p":"Correcto. Quédese a 30 pies de un semáforo o una señal."},"ref":{"doc":"NY","page":43}},{"id":"ny-082","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, how close to a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is about the length of three cars.","h2":"In New York, you may not park within 50 feet of a railroad crossing.","p":"Right. Park at least 50 feet from a railroad crossing."},"es":{"q":"En Nueva York, ¿qué tan cerca de un cruce de tren puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es más o menos el largo de tres autos.","h2":"En Nueva York, no puede estacionarse a menos de 50 pies de un cruce de tren.","p":"Correcto. Estaciónese por lo menos a 50 pies de un cruce de tren."},"ref":{"doc":"NY","page":43}},{"id":"ny-083","scope":"NY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In New York, you stop your car 10 feet from a fire hydrant. When is this allowed?","o":["Only if a licensed driver stays in the car to move it in an emergency","Any time, for up to 10 minutes","Only at night","Only if your hazard lights are on"],"h1":"Someone must be ready to move the car fast.","h2":"In New York, you may not park, stop or stand within 15 feet of a fire hydrant unless a licensed driver stays in the vehicle to move it in an emergency.","p":"Right. Only with a licensed driver ready to move the car."},"es":{"q":"En Nueva York, usted detiene su auto a 10 pies de un hidrante. ¿Cuándo está permitido?","o":["Solo si un conductor con licencia se queda en el auto para moverlo en una emergencia","Siempre, por hasta 10 minutos","Solo de noche","Solo si tiene encendidas las luces de emergencia"],"h1":"Alguien debe estar listo para mover el auto rápido.","h2":"En Nueva York, no puede estacionarse, detenerse ni quedarse parado a menos de 15 pies de un hidrante, salvo que un conductor con licencia se quede en el vehículo para moverlo en una emergencia.","p":"Correcto. Solo con un conductor con licencia listo para mover el auto."},"ref":{"doc":"NY","page":43}},{"id":"ny-084","scope":"NY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In New York, after you parallel park, how far from the curb may your wheels be?","o":["No more than 6 inches","No more than one foot","No more than two feet","No more than three feet"],"h1":"It is about the length of a ruler.","h2":"In New York, after you parallel park, your wheels must be no more than one foot from the curb.","p":"Right. Within one foot of the curb."},"es":{"q":"En Nueva York, después de estacionarse en paralelo, ¿a qué distancia de la acera pueden quedar sus llantas?","o":["A no más de 6 pulgadas","A no más de un pie","A no más de dos pies","A no más de tres pies"],"h1":"Es más o menos el largo de una regla.","h2":"En Nueva York, después de estacionarse en paralelo, sus llantas deben quedar a no más de un pie (30 cm) de la acera.","p":"Correcto. A no más de un pie de la acera."},"ref":{"doc":"NY","page":42}},{"id":"ny-085","scope":"NY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New York, roundabouts are designed so that vehicles inside them go no faster than about what speed?","o":["15 mph","45 mph","30 mph","55 mph"],"h1":"It is a low city speed.","h2":"In New York, roundabouts are designed so that all vehicles inside go 30 mph or less.","p":"Right. Roundabouts keep speeds at 30 mph or less."},"es":{"q":"En Nueva York, las rotondas están diseñadas para que los vehículos dentro de ellas no vayan a más de ¿qué velocidad, aproximadamente?","o":["15 mph","45 mph","30 mph","55 mph"],"h1":"Es una velocidad baja de ciudad.","h2":"En Nueva York, las rotondas están diseñadas para que todos los vehículos dentro de ellas vayan a 30 mph o menos.","p":"Correcto. En las rotondas la velocidad es de 30 mph o menos."},"ref":{"doc":"NY","page":50}},{"id":"ny-086","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, where must a Class B or Class C moped ride?","o":["In any lane, like a car","Only on the sidewalk","In the left lane","In the right lane, as far right as possible, or on the shoulder"],"h1":"These slower mopeds keep to one side of the road.","h2":"In New York, Class B and C mopeds may ride only in the right lane, as far right as possible, or on the shoulder, except when turning left.","p":"Right. Slower mopeds keep to the far right."},"es":{"q":"En Nueva York, ¿por dónde debe circular un ciclomotor (moped) Clase B o Clase C?","o":["Por cualquier carril, como un auto","Solo por la acera","Por el carril izquierdo","Por el carril derecho, lo más a la derecha posible, o por el acotamiento"],"h1":"Estos ciclomotores más lentos van por un lado de la calle.","h2":"En Nueva York, los ciclomotores Clase B y C solo pueden circular por el carril derecho, lo más a la derecha posible, o por el acotamiento, salvo al dar vuelta a la izquierda.","p":"Correcto. Los ciclomotores más lentos van bien a la derecha."},"ref":{"doc":"NY","page":74}},{"id":"ny-087","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, what happens to the fine for speeding in a work zone?","o":["It doubles, even when no workers are there","It stays the same as anywhere else","It doubles only when workers are present","There is no fine, only points"],"h1":"The rule applies whether or not you see workers.","h2":"In New York, fines for speeding in a work zone are doubled, even when workers and work vehicles are not there.","p":"Right. Work zone speeding fines double."},"es":{"q":"En Nueva York, ¿qué pasa con la multa por exceso de velocidad en una zona de obras?","o":["Se duplica, aunque no haya trabajadores","Es igual que en cualquier otro lugar","Se duplica solo si hay trabajadores","No hay multa, solo puntos"],"h1":"La regla se aplica vea o no vea trabajadores.","h2":"En Nueva York, las multas por exceso de velocidad en una zona de obras se duplican, aunque no estén los trabajadores ni los vehículos de trabajo.","p":"Correcto. En zona de obras la multa por velocidad se duplica."},"ref":{"doc":"NY","page":49}},{"id":"ny-088","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, a driver is caught texting while driving for the second time within 18 months. What is the highest fine?","o":["$100","$250","$450","$1,000"],"h1":"It is a bit more than the $200 limit for a first offense.","h2":"In New York, a second texting offense within 18 months can bring a fine of up to $250; a third can bring up to $450.","p":"Right. Up to $250 for a second offense."},"es":{"q":"En Nueva York, a un conductor lo sorprenden enviando mensajes de texto mientras maneja por segunda vez en 18 meses. ¿Cuál es la multa más alta?","o":["$100","$250","$450","$1,000"],"h1":"Es un poco más que el límite de $200 de la primera infracción.","h2":"En Nueva York, una segunda infracción por mensajes de texto en 18 meses puede traer una multa de hasta $250; una tercera, de hasta $450.","p":"Correcto. Hasta $250 por una segunda infracción."},"ref":{"doc":"NY","page":52}},{"id":"ny-089","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, to prevent drowsy driving on a long trip, how often should you plan a stop?","o":["Every 500 miles","Every 6 hours","Every 100 miles or two hours","Only when you feel sleepy"],"h1":"Think of a short distance or a couple of hours.","h2":"The New York Driver's Manual says to schedule regular stops every 100 miles or two hours on a long trip.","p":"Right. Stop every 100 miles or two hours."},"es":{"q":"En Nueva York, para evitar manejar con sueño en un viaje largo, ¿cada cuánto debe planear una parada?","o":["Cada 500 millas","Cada 6 horas","Cada 100 millas o dos horas","Solo cuando sienta sueño"],"h1":"Piense en una distancia corta o en un par de horas.","h2":"El manual del conductor de Nueva York dice que en un viaje largo debe planear paradas regulares cada 100 millas o dos horas.","p":"Correcto. Pare cada 100 millas o dos horas."},"ref":{"doc":"NY","page":52}},{"id":"ny-090","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, what is the least tread depth the law allows on your tires?","o":["1/32 of an inch","4/32 of an inch","1/4 of an inch","2/32 of an inch"],"h1":"Try the penny test: if you can see all of Lincoln's head, the tread is too worn.","h2":"New York law requires at least 2/32 of an inch of tread on your tires.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En Nueva York, ¿cuál es la profundidad mínima del dibujo de las llantas que permite la ley?","o":["1/32 de pulgada","4/32 de pulgada","1/4 de pulgada","2/32 de pulgada"],"h1":"Pruebe con una moneda de un centavo: si ve toda la cabeza de Lincoln, el dibujo está demasiado gastado.","h2":"La ley de Nueva York exige por lo menos 2/32 de pulgada de dibujo en sus llantas.","p":"Correcto. Por lo menos 2/32 de pulgada."},"ref":{"doc":"NY","page":53}},{"id":"ny-091","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, a driver or passenger has an open container of alcohol in a car on a public road. What is the highest fine for a first conviction?","o":["$150","$50","$500","$1,000"],"h1":"It is less than $200.","h2":"In New York, a first conviction for drinking or having an open alcohol container in a vehicle on a public road can bring a fine of up to $150, plus a surcharge.","p":"Right. Up to $150 for a first conviction."},"es":{"q":"En Nueva York, un conductor o pasajero tiene un envase abierto de alcohol en un auto en una vía pública. ¿Cuál es la multa más alta por una primera condena?","o":["$150","$50","$500","$1,000"],"h1":"Es menos de $200.","h2":"En Nueva York, una primera condena por tomar alcohol o tener un envase abierto de alcohol en un vehículo en una vía pública puede traer una multa de hasta $150, más un recargo.","p":"Correcto. Hasta $150 por una primera condena."},"ref":{"doc":"NY","page":57}},{"id":"ny-092","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, what fine can a court give for a first DWI conviction (blood alcohol 0.08 or more)?","o":["$100 to $250","$500 to $1,000","$1,000 to $2,500","$5,000 to $10,000"],"h1":"The fine for aggravated DWI starts where this one ends.","h2":"In New York, a first DWI conviction brings a fine of $500 to $1,000, up to one year in jail, and at least a six-month license revocation.","p":"Right. A first DWI fine is $500 to $1,000."},"es":{"q":"En Nueva York, ¿qué multa puede imponer un tribunal por una primera condena por DWI (alcohol en la sangre de 0.08 o más)?","o":["De $100 a $250","De $500 a $1,000","De $1,000 a $2,500","De $5,000 a $10,000"],"h1":"La multa por DWI agravado empieza donde termina esta.","h2":"En Nueva York, una primera condena por DWI trae una multa de $500 a $1,000, hasta un año de cárcel y la revocación de la licencia por lo menos seis meses.","p":"Correcto. La multa por un primer DWI es de $500 a $1,000."},"ref":{"doc":"NY","page":58}},{"id":"ny-093","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, after a DWI conviction, for at least how long must the court order an ignition interlock on any car the driver owns or drives?","o":["30 days","3 months","12 months","10 years"],"h1":"It is more than six months.","h2":"In New York, a court must order a person convicted of DWI to install and keep an ignition interlock on any vehicle they own or drive for at least 12 months.","p":"Right. The interlock is ordered for at least 12 months."},"es":{"q":"En Nueva York, después de una condena por DWI, ¿por cuánto tiempo como mínimo debe ordenar el tribunal un bloqueo de encendido (interlock) en cualquier auto que el conductor tenga o maneje?","o":["30 días","3 meses","12 meses","10 años"],"h1":"Es más de seis meses.","h2":"En Nueva York, el tribunal debe ordenar que una persona condenada por DWI instale y mantenga un bloqueo de encendido en cualquier vehículo que tenga o maneje por lo menos 12 meses.","p":"Correcto. El bloqueo se ordena por lo menos por 12 meses."},"ref":{"doc":"NY","page":59}},{"id":"ny-094","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a driver's license was revoked for a first chemical test refusal. What civil penalty must the driver pay before applying for a new license?","o":["$50","$100","$250","$500"],"h1":"It is half of $1,000.","h2":"In New York, after a revocation for refusing a chemical test, the driver must pay a $500 civil penalty before an application for a new license is accepted.","p":"Right. A test refusal costs a $500 civil penalty."},"es":{"q":"En Nueva York, a un conductor le revocaron la licencia por negarse por primera vez a una prueba química. ¿Qué multa civil debe pagar antes de solicitar una licencia nueva?","o":["$50","$100","$250","$500"],"h1":"Es la mitad de $1,000.","h2":"En Nueva York, después de una revocación por negarse a una prueba química, el conductor debe pagar una multa civil de $500 antes de que se acepte su solicitud de licencia nueva.","p":"Correcto. Negarse a la prueba cuesta una multa civil de $500."},"ref":{"doc":"NY","page":23}},{"id":"ny-095","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, you are using your high beams and come up behind another car. Within how many feet of it must you switch to low beams?","o":["200 feet","50 feet","500 feet","1,000 feet"],"h1":"It is about two-thirds the length of a football field.","h2":"In New York, you must use low beams within 200 feet of a vehicle ahead of you, even if it is in a different lane.","p":"Right. Dim your lights within 200 feet of a car ahead."},"es":{"q":"En Nueva York, usted lleva las luces altas y se acerca por detrás a otro auto. ¿A menos de cuántos pies de ese auto debe cambiar a luces bajas?","o":["200 pies","50 pies","500 pies","1,000 pies"],"h1":"Es más o menos dos tercios del largo de un campo de fútbol americano.","h2":"En Nueva York, debe usar luces bajas a menos de 200 pies de un vehículo que va delante de usted, aunque esté en otro carril.","p":"Correcto. Baje las luces a menos de 200 pies de un auto que va delante."},"ref":{"doc":"NY","page":63}},{"id":"ny-096","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, a bicycle ridden at night must have a headlight that can be seen from at least how far ahead?","o":["50 feet","500 feet","100 feet","2,000 feet"],"h1":"The red taillight must be seen from 300 feet, and the headlight from even farther.","h2":"In New York, a bicycle used at night must have a headlight visible from at least 500 feet ahead and a red taillight visible from at least 300 feet behind.","p":"Right. A bike headlight must be seen from 500 feet."},"es":{"q":"En Nueva York, una bicicleta que se usa de noche debe tener una luz delantera que se vea desde por lo menos ¿qué distancia?","o":["50 pies","500 pies","100 pies","2,000 pies"],"h1":"La luz trasera roja debe verse desde 300 pies, y la delantera desde más lejos todavía.","h2":"En Nueva York, una bicicleta que se usa de noche debe tener una luz delantera visible desde por lo menos 500 pies adelante y una luz trasera roja visible desde por lo menos 300 pies atrás.","p":"Correcto. La luz delantera de la bicicleta debe verse desde 500 pies."},"ref":{"doc":"NY","page":69}},{"id":"ny-097","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, the lights are flashing and the gates are down at a railroad crossing. How far from the tracks must you stop?","o":["At least 2 feet","At least 5 feet","At least 15 feet","At least 100 feet"],"h1":"It is about the length of one car.","h2":"In New York, when railroad crossing lights flash, the bell rings or the gates are down, you must stop at least 15 feet from the tracks.","p":"Right. Stop at least 15 feet from the tracks."},"es":{"q":"En Nueva York, en un cruce de tren las luces están intermitentes y las barreras están bajas. ¿A qué distancia de las vías debe detenerse?","o":["Por lo menos a 2 pies","Por lo menos a 5 pies","Por lo menos a 15 pies","Por lo menos a 100 pies"],"h1":"Es más o menos el largo de un auto.","h2":"En Nueva York, cuando en un cruce de tren las luces están intermitentes, suena la campana o las barreras están bajas, debe detenerse por lo menos a 15 pies de las vías.","p":"Correcto. Deténgase por lo menos a 15 pies de las vías."},"ref":{"doc":"NY","page":61}},{"id":"ny-098","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, may two motorcycles ride side by side in the same lane?","o":["No, never","Yes, and a car may share the lane too","Yes, up to four at a time","Yes, two motorcycles may share one lane"],"h1":"A pair is allowed, but not together with a car.","h2":"In New York, two motorcyclists may ride side by side in one lane, but a motorcycle may not share a lane with a car or any other vehicle that is not a motorcycle.","p":"Right. Two motorcycles may share a lane."},"es":{"q":"En Nueva York, ¿pueden dos motocicletas circular una al lado de la otra en el mismo carril?","o":["No, nunca","Sí, y un auto también puede compartir el carril","Sí, hasta cuatro a la vez","Sí, dos motocicletas pueden compartir un carril"],"h1":"Se permite una pareja, pero no junto con un auto.","h2":"En Nueva York, dos motociclistas pueden circular uno al lado del otro en un carril, pero una motocicleta no puede compartir el carril con un auto ni con otro vehículo que no sea motocicleta.","p":"Correcto. Dos motocicletas pueden compartir un carril."},"ref":{"doc":"NY","page":71}},{"id":"ny-099","scope":"NY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New York, a person with a white cane or a guide dog is trying to cross at a crosswalk, but your light is green. What must you do?","o":["Yield and let the person cross","Go, because your light is green","Honk so the person knows you are there","Drive around the person slowly"],"h1":"A special law protects people who are blind.","h2":"In New York, you must always yield to a blind pedestrian with a guide dog or a white or metal cane who is crossing at a crosswalk, even if the signals are not in their favor.","p":"Right. Always yield to a blind pedestrian."},"es":{"q":"En Nueva York, una persona con bastón blanco o perro guía intenta cruzar en un cruce peatonal, pero usted tiene la luz verde. ¿Qué debe hacer?","o":["Ceder el paso y dejar cruzar a la persona","Seguir, porque tiene la luz verde","Tocar la bocina para que sepa que usted está ahí","Rodear a la persona despacio"],"h1":"Una ley especial protege a las personas ciegas.","h2":"En Nueva York, siempre debe ceder el paso a un peatón ciego con perro guía o con bastón blanco o de metal que cruza en un cruce peatonal, aunque las señales no lo favorezcan.","p":"Correcto. Siempre ceda el paso a un peatón ciego."},"ref":{"doc":"NY","page":67}},{"id":"ny-100","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, you scrape a parked car and nobody is around. What must you do?","o":["Drive away, since no one was hurt","Try to find the owner or notify the police","Leave without a note if the damage is small","Wait one hour, then leave"],"h1":"The owner must be able to find out who hit the car.","h2":"In New York, if you damage a parked vehicle or other property, you must try to find the owner or notify the police.","p":"Right. Find the owner or call the police."},"es":{"q":"En Nueva York, usted raya un auto estacionado y no hay nadie cerca. ¿Qué debe hacer?","o":["Irse, porque nadie salió herido","Tratar de encontrar al dueño o avisar a la policía","Irse sin dejar nota si el daño es pequeño","Esperar una hora y luego irse"],"h1":"El dueño debe poder saber quién chocó su auto.","h2":"En Nueva York, si daña un vehículo estacionado u otra propiedad, debe tratar de encontrar al dueño o avisar a la policía.","p":"Correcto. Busque al dueño o llame a la policía."},"ref":{"doc":"NY","page":77}},{"id":"ny-101","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, what is the youngest age for a full Class D driver license if you did NOT finish a driver education course?","o":["18","16","17","21"],"h1":"Finishing driver education lets you get it one year sooner.","h2":"In New York, the minimum age for a Class D license is 18, or 17 if you have a driver education Certificate of Completion.","p":"Right. Without driver education, you must be 18."},"es":{"q":"En Nueva York, ¿cuál es la edad mínima para una licencia Clase D completa si usted NO terminó un curso de educación vial?","o":["18","16","17","21"],"h1":"Terminar la educación vial le permite obtenerla un año antes.","h2":"En Nueva York, la edad mínima para una licencia Clase D es 18 años, o 17 si usted tiene un Certificado de Finalización de educación vial.","p":"Correcto. Sin educación vial, debe tener 18 años."},"ref":{"doc":"NY","page":6}},{"id":"ny-102","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, what extra use does an Enhanced Driver License have?","o":["It lets you drive a bus or large truck without a CDL","It can be used instead of a passport at land and sea crossings to Canada or Mexico","It lets a 16-year-old drive alone in New York City","It never needs to be renewed"],"h1":"Think about crossing a border.","h2":"In New York, an Enhanced Driver License can be used instead of a passport at land and sea crossings to and from Canada, Mexico, Bermuda and the Caribbean.","p":"Right. It works like a passport at land and sea borders."},"es":{"q":"En Nueva York, ¿qué uso adicional tiene una Licencia de Conducir Mejorada (Enhanced Driver License)?","o":["Le permite manejar un autobús o un camión grande sin una CDL","Se puede usar en lugar de un pasaporte en cruces por tierra y mar hacia Canadá o México","Le permite a un joven de 16 años manejar solo en la ciudad de Nueva York","Nunca hay que renovarla"],"h1":"Piense en cruzar una frontera.","h2":"En Nueva York, una Licencia de Conducir Mejorada se puede usar en lugar de un pasaporte en cruces por tierra y mar hacia y desde Canadá, México, Bermudas y el Caribe.","p":"Correcto. Funciona como un pasaporte en fronteras por tierra y mar."},"ref":{"doc":"NY","page":7}},{"id":"ny-103","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, how early can you renew your driver license before its printed expiration date?","o":["Only in the last 10 days","Up to five years before","Up to one year before","Only after it has expired"],"h1":"It is many months, but not years.","h2":"In New York, you can renew your driver license up to one year before its printed expiration date.","p":"Right. You can renew up to one year early."},"es":{"q":"En Nueva York, ¿con cuánta anticipación puede renovar su licencia antes de la fecha de vencimiento impresa?","o":["Solo en los últimos 10 días","Hasta cinco años antes","Hasta un año antes","Solo después de que haya vencido"],"h1":"Son muchos meses, pero no años.","h2":"En Nueva York, usted puede renovar su licencia de conducir hasta un año antes de la fecha de vencimiento impresa.","p":"Correcto. Puede renovarla hasta un año antes."},"ref":{"doc":"NY","page":17}},{"id":"ny-104","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, you renew your driver license by mail. What must you send with your renewal application?","o":["A new road test certificate","A letter from your employer","Your car's inspection sticker","An Eye Test Report showing you passed a vision test"],"h1":"The DMV needs to know you can still see well.","h2":"In New York, to renew your license by mail you send the renewal application with a completed Eye Test Report (MV-619) showing you passed the vision test.","p":"Right. Send an Eye Test Report with it."},"es":{"q":"En Nueva York, usted renueva su licencia por correo. ¿Qué debe enviar con la solicitud de renovación?","o":["Un nuevo certificado de examen práctico","Una carta de su empleador","La calcomanía de inspección de su carro","Un Informe de Examen de la Vista que muestre que aprobó la prueba de visión"],"h1":"El DMV necesita saber que usted todavía ve bien.","h2":"En Nueva York, para renovar la licencia por correo usted envía la solicitud con un Informe de Examen de la Vista (MV-619) completo que muestre que aprobó la prueba de visión.","p":"Correcto. Envíe un Informe de Examen de la Vista."},"ref":{"doc":"NY","page":17}},{"id":"ny-105","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, you get a speeding ticket while visiting Pennsylvania and you never answer it. What can happen to your New York license?","o":["It is suspended until you answer the ticket","Nothing, because the ticket was out of state","It is revoked for five years","You get 11 points right away"],"h1":"An unanswered ticket follows you home.","h2":"In New York, your license will be suspended if you do not answer a moving traffic ticket from most other states, and it stays suspended until you answer it.","p":"Right. It stays suspended until you answer the ticket."},"es":{"q":"En Nueva York, usted recibe una multa por exceso de velocidad mientras visita Pensilvania y nunca la responde. ¿Qué puede pasar con su licencia de Nueva York?","o":["Se suspende hasta que usted responda la multa","Nada, porque la multa fue en otro estado","Se revoca por cinco años","Recibe 11 puntos de inmediato"],"h1":"Una multa sin responder lo sigue hasta su casa.","h2":"En Nueva York, su licencia será suspendida si usted no responde una multa de tránsito en movimiento de la mayoría de los otros estados, y sigue suspendida hasta que la responda.","p":"Correcto. Sigue suspendida hasta que responda la multa."},"ref":{"doc":"NY","page":20}},{"id":"ny-106","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, what license penalty comes with a first conviction for Driving While Ability Impaired by alcohol (DWAI)?","o":["No license penalty, only a fine","A 90-day suspension","Revocation for at least one year","Revocation for life"],"h1":"It is about three months.","h2":"In New York, a first DWAI (alcohol) conviction brings a 90-day license suspension.","p":"Right. A first DWAI means a 90-day suspension."},"es":{"q":"En Nueva York, ¿qué castigo a la licencia trae una primera condena por Manejar con la Capacidad Disminuida por alcohol (DWAI)?","o":["Ningún castigo a la licencia, solo una multa","Una suspensión de 90 días","Revocación por al menos un año","Revocación de por vida"],"h1":"Son unos tres meses.","h2":"En Nueva York, una primera condena por DWAI (alcohol) trae una suspensión de la licencia por 90 días.","p":"Correcto. Un primer DWAI significa una suspensión de 90 días."},"ref":{"doc":"NY","page":20}},{"id":"ny-107","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, what is the least license penalty for a first conviction of Aggravated DWI (blood alcohol 0.18 or more)?","o":["A 90-day suspension","A 30-day suspension","Revocation for at least one year","A warning letter only"],"h1":"It is longer than the penalty for a regular first DWI.","h2":"In New York, a first Aggravated DWI conviction brings a license revocation of at least one year.","p":"Right. At least a one-year revocation."},"es":{"q":"En Nueva York, ¿cuál es el castigo mínimo a la licencia por una primera condena de DWI Agravado (alcohol en la sangre de 0.18 o más)?","o":["Una suspensión de 90 días","Una suspensión de 30 días","Revocación por al menos un año","Solo una carta de advertencia"],"h1":"Es más largo que el castigo por un primer DWI normal.","h2":"En Nueva York, una primera condena por DWI Agravado trae una revocación de la licencia por al menos un año.","p":"Correcto. Al menos un año de revocación."},"ref":{"doc":"NY","page":20}},{"id":"ny-108","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, a 30-year-old driver refuses a chemical test. Three years ago the same driver's license was revoked for an earlier refusal. What is the least revocation now?","o":["90 days","6 months","10 years","18 months"],"h1":"It is longer than the one year for a first refusal.","h2":"In New York, a driver over 21 who refuses a chemical test within five years of an earlier refusal revocation or alcohol or drug violation loses the license for at least 18 months.","p":"Right. At least 18 months."},"es":{"q":"En Nueva York, un conductor de 30 años se niega a una prueba química. Hace tres años, su licencia fue revocada por otra negativa. ¿Cuál es la revocación mínima ahora?","o":["90 días","6 meses","10 años","18 meses"],"h1":"Es más largo que el año de una primera negativa.","h2":"En Nueva York, un conductor mayor de 21 años que se niega a una prueba química dentro de cinco años de una revocación anterior por negativa o por una infracción de alcohol o drogas pierde la licencia por al menos 18 meses.","p":"Correcto. Al menos 18 meses."},"ref":{"doc":"NY","page":21}},{"id":"ny-109","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, a 19-year-old driver breaks the Zero Tolerance law for the second time. What happens to the license?","o":["It is revoked for at least one year or until age 21, whichever is longer","It is suspended for 30 days","The same six-month suspension as the first time","It is revoked for life"],"h1":"It is stricter than the first time, and age 21 matters.","h2":"In New York, a second Zero Tolerance violation means the license is revoked for at least one year or until the driver turns 21, whichever is longer.","p":"Right. One year or until 21, whichever is longer."},"es":{"q":"En Nueva York, un conductor de 19 años viola la ley de Tolerancia Cero por segunda vez. ¿Qué pasa con la licencia?","o":["Se revoca por al menos un año o hasta los 21 años, lo que sea más largo","Se suspende por 30 días","La misma suspensión de seis meses que la primera vez","Se revoca de por vida"],"h1":"Es más estricto que la primera vez, y la edad de 21 años importa.","h2":"En Nueva York, una segunda violación de Tolerancia Cero significa que la licencia se revoca por al menos un año o hasta que el conductor cumpla 21 años, lo que sea más largo.","p":"Correcto. Un año o hasta los 21, lo que sea más largo."},"ref":{"doc":"NY","page":21}},{"id":"ny-110","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, you let a friend drive your car, and the car has no insurance. What happens to your own license?","o":["Nothing, because you were not driving","It is revoked for at least one year","You get a warning letter","It is suspended for 10 days"],"h1":"The owner is responsible for the insurance.","h2":"In New York, your license is revoked for at least one year if you drive, or let another person drive, your uninsured vehicle.","p":"Right. At least a one-year revocation."},"es":{"q":"En Nueva York, usted deja que un amigo maneje su carro, y el carro no tiene seguro. ¿Qué pasa con su propia licencia?","o":["Nada, porque usted no manejaba","Se revoca por al menos un año","Recibe una carta de advertencia","Se suspende por 10 días"],"h1":"El dueño es responsable del seguro.","h2":"En Nueva York, su licencia se revoca por al menos un año si usted maneja, o deja que otra persona maneje, su vehículo sin seguro.","p":"Correcto. Al menos un año de revocación."},"ref":{"doc":"NY","page":21}},{"id":"ny-111","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, how many points do you get for driving 11 to 20 mph over the speed limit?","o":["2 points","6 points","4 points","11 points"],"h1":"It is one more than for going 1 to 10 mph over.","h2":"In New York, driving 11 to 20 mph over the speed limit adds 4 points to your record.","p":"Right. 11 to 20 mph over is 4 points."},"es":{"q":"En Nueva York, ¿cuántos puntos recibe por manejar de 11 a 20 mph por encima del límite de velocidad?","o":["2 puntos","6 puntos","4 puntos","11 puntos"],"h1":"Es uno más que por ir de 1 a 10 mph por encima.","h2":"En Nueva York, manejar de 11 a 20 mph por encima del límite de velocidad suma 4 puntos a su historial.","p":"Correcto. De 11 a 20 mph por encima son 4 puntos."},"ref":{"doc":"NY","page":22}},{"id":"ny-112","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, how many points does a reckless driving conviction add to your record?","o":["2 points","3 points","8 points","5 points"],"h1":"It is the same as for texting while driving.","h2":"In New York, a reckless driving conviction adds 5 points to your driving record.","p":"Right. Reckless driving is 5 points."},"es":{"q":"En Nueva York, ¿cuántos puntos suma a su historial una condena por manejo imprudente (reckless driving)?","o":["2 puntos","3 puntos","8 puntos","5 puntos"],"h1":"Es lo mismo que por enviar mensajes de texto mientras maneja.","h2":"En Nueva York, una condena por manejo imprudente suma 5 puntos a su historial de manejo.","p":"Correcto. El manejo imprudente son 5 puntos."},"ref":{"doc":"NY","page":22}},{"id":"ny-113","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, a driver under 21 had the license suspended under the Zero Tolerance law. What must the driver pay to get it back?","o":["A $125 civil penalty and a $100 suspension termination fee","Nothing at all","A $50 fee only","A $750 civil penalty"],"h1":"There are two charges, and together they are a little over $200.","h2":"In New York, after a Zero Tolerance suspension, the driver must pay a $125 civil penalty and a $100 suspension termination fee to be licensed again.","p":"Right. $125 plus $100."},"es":{"q":"En Nueva York, a un conductor menor de 21 años le suspendieron la licencia por la ley de Tolerancia Cero. ¿Qué debe pagar para recuperarla?","o":["Una multa civil de $125 y un cargo de $100 por terminar la suspensión","Nada","Solo un cargo de $50","Una multa civil de $750"],"h1":"Son dos cargos, y juntos suman un poco más de $200.","h2":"En Nueva York, después de una suspensión por Tolerancia Cero, el conductor debe pagar una multa civil de $125 y un cargo de $100 por terminar la suspensión para volver a tener licencia.","p":"Correcto. $125 más $100."},"ref":{"doc":"NY","page":22}},{"id":"ny-114","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, a driver is convicted of DWI. What Driver Responsibility Assessment must the driver pay the DMV?","o":["$25 one time","$250 a year for three years","$100 a year for one year","$1,000 a year for ten years"],"h1":"It is paid every year for a few years.","h2":"In New York, a conviction for DWI, DWAI or a chemical test refusal brings a Driver Responsibility Assessment of $250 each year for three years.","p":"Right. $250 a year for three years."},"es":{"q":"En Nueva York, un conductor es condenado por DWI. ¿Qué Cargo de Responsabilidad del Conductor (Driver Responsibility Assessment) debe pagar al DMV?","o":["$25 una sola vez","$250 al año durante tres años","$100 al año durante un año","$1,000 al año durante diez años"],"h1":"Se paga cada año durante algunos años.","h2":"En Nueva York, una condena por DWI, DWAI o por negarse a una prueba química trae un Cargo de Responsabilidad del Conductor de $250 cada año durante tres años.","p":"Correcto. $250 al año durante tres años."},"ref":{"doc":"NY","page":23}},{"id":"ny-115","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, is it a crime to drive while your license is suspended or revoked?","o":["No, it is like a parking ticket","Only if you cause a crash","Yes, it is a criminal offense with mandatory fines of $200 to $5,000","No, if you drive less than 10 miles"],"h1":"The penalties can include jail or probation.","h2":"In New York, driving while your license is suspended or revoked is a criminal offense, with mandatory fines from $200 to $5,000 and possible jail or probation.","p":"Right. It is a crime."},"es":{"q":"En Nueva York, ¿es un delito manejar mientras su licencia está suspendida o revocada?","o":["No, es como una multa de estacionamiento","Solo si usted causa un choque","Sí, es un delito penal con multas obligatorias de $200 a $5,000","No, si maneja menos de 10 millas"],"h1":"Los castigos pueden incluir cárcel o libertad condicional.","h2":"En Nueva York, manejar con la licencia suspendida o revocada es un delito penal, con multas obligatorias de $200 a $5,000 y posible cárcel o libertad condicional.","p":"Correcto. Es un delito."},"ref":{"doc":"NY","page":23}},{"id":"ny-116","scope":"NY","cat":"licensing","sign":null,"c":3,"en":{"q":"In New York, you are about to sell your old car. What should you take off it first?","o":["The spare tire","Only the inspection sticker","Nothing; the buyer keeps your plates","The license plates and the windshield registration sticker"],"h1":"Think about parking tickets that could come to you later.","h2":"In New York, before you sell or trade in a car, remove the license plates and the windshield registration sticker so you are not charged with parking tickets that are not yours.","p":"Right. Take the plates and the registration sticker."},"es":{"q":"En Nueva York, usted va a vender su carro viejo. ¿Qué debe quitarle primero?","o":["La llanta de repuesto","Solo la calcomanía de inspección","Nada; el comprador se queda con sus placas","Las placas y la calcomanía de registro del parabrisas"],"h1":"Piense en multas de estacionamiento que le podrían llegar después.","h2":"En Nueva York, antes de vender o entregar un carro, quite las placas y la calcomanía de registro del parabrisas para que no le cobren multas de estacionamiento que no son suyas.","p":"Correcto. Quite las placas y la calcomanía de registro."},"ref":{"doc":"NY","page":26}},{"id":"ny-117","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, your registered car has had no insurance for 90 days, and you never turned in the plates. What happens to your driver license?","o":["It is suspended","Nothing happens to it","It gets 2 points","It is renewed early"],"h1":"The problem is not only with the registration.","h2":"In New York, if your vehicle is not insured for 90 days and you have not turned in the plates, your driver license is also suspended.","p":"Right. Your license is suspended too."},"es":{"q":"En Nueva York, su carro registrado lleva 90 días sin seguro, y usted nunca entregó las placas. ¿Qué pasa con su licencia de conducir?","o":["Se suspende","No le pasa nada","Recibe 2 puntos","Se renueva antes de tiempo"],"h1":"El problema no es solo con el registro.","h2":"En Nueva York, si su vehículo no tiene seguro durante 90 días y usted no ha entregado las placas, su licencia de conducir también se suspende.","p":"Correcto. Su licencia también se suspende."},"ref":{"doc":"NY","page":27}},{"id":"ny-118","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, you and another driver reach an intersection with no signs or signals at the same time. The other driver is on your right. Who must yield?","o":["The driver on your right must yield to you","You must yield to the driver on your right","The faster driver goes first","The larger vehicle goes first"],"h1":"The driver on the left waits.","h2":"In New York, at an intersection with no signs or signals, the driver on the left must yield to the driver on the right when they arrive at the same time.","p":"Right. Yield to the driver on your right."},"es":{"q":"En Nueva York, usted y otro conductor llegan al mismo tiempo a una intersección sin señales ni semáforos. El otro conductor está a su derecha. ¿Quién debe ceder el paso?","o":["El conductor de su derecha debe cederle el paso a usted","Usted debe ceder el paso al conductor de su derecha","El conductor más rápido pasa primero","El vehículo más grande pasa primero"],"h1":"El conductor de la izquierda espera.","h2":"En Nueva York, en una intersección sin señales ni semáforos, el conductor de la izquierda debe ceder el paso al conductor de la derecha cuando llegan al mismo tiempo.","p":"Correcto. Ceda el paso al conductor de su derecha."},"ref":{"doc":"NY","page":34}},{"id":"ny-119","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, you are in the middle of an intersection when an ambulance with its siren on comes up behind you. What should you do?","o":["Stop right where you are, in the intersection","Back up out of the intersection","Drive out of the intersection, then pull over to the right and stop","Speed up and stay ahead of it"],"h1":"Do not block the intersection while you wait.","h2":"In New York, if you are in an intersection when an emergency vehicle comes, drive out of the intersection first, then pull over to the right edge and stop.","p":"Right. Clear the intersection, then pull over."},"es":{"q":"En Nueva York, usted está en medio de una intersección cuando una ambulancia con la sirena encendida se acerca por detrás. ¿Qué debe hacer?","o":["Detenerse ahí mismo, dentro de la intersección","Retroceder para salir de la intersección","Salir de la intersección y luego orillarse a la derecha y detenerse","Acelerar y mantenerse delante de ella"],"h1":"No bloquee la intersección mientras espera.","h2":"En Nueva York, si usted está en una intersección cuando llega un vehículo de emergencia, primero salga de la intersección y luego oríllese a la derecha y deténgase.","p":"Correcto. Salga de la intersección y luego oríllese."},"ref":{"doc":"NY","page":35}},{"id":"ny-120","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York City, where is a U-turn against the law, even with no sign?","o":["On any street with a bus stop","At any intersection with a traffic light","On any street with parked cars","In a business district"],"h1":"Think of busy areas with many stores and offices.","h2":"In New York City, U-turns are illegal in business districts, as well as anywhere a NO U-TURN sign is posted.","p":"Right. No U-turns in New York City business districts."},"es":{"q":"En la ciudad de Nueva York, ¿dónde es ilegal dar una vuelta en U, aunque no haya letrero?","o":["En cualquier calle con parada de autobús","En cualquier intersección con semáforo","En cualquier calle con carros estacionados","En una zona comercial"],"h1":"Piense en zonas con mucho movimiento, tiendas y oficinas.","h2":"En la ciudad de Nueva York, las vueltas en U son ilegales en las zonas comerciales, y también donde haya un letrero de NO U-TURN.","p":"Correcto. No se permiten vueltas en U en zonas comerciales de la ciudad de Nueva York."},"ref":{"doc":"NY","page":37}},{"id":"ny-121","scope":"NY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New York, how many bicycle riders may ride side by side in one lane?","o":["No more than two","Only one","Up to three","Any number"],"h1":"Think of a pair.","h2":"In New York, bicyclists may never ride more than two side by side in a single lane.","p":"Right. No more than two side by side."},"es":{"q":"En Nueva York, ¿cuántos ciclistas pueden ir uno al lado del otro en un mismo carril?","o":["No más de dos","Solo uno","Hasta tres","Cualquier número"],"h1":"Piense en una pareja.","h2":"En Nueva York, los ciclistas nunca pueden ir más de dos uno al lado del otro en un mismo carril.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"NY","page":69}},{"id":"ny-122","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, you stopped for a school bus with flashing red lights. When may you drive on?","o":["As soon as the children are off the bus","When the bus starts moving, or the bus driver or a traffic officer signals you to go","After waiting 30 seconds","When the bus starts to flash yellow lights"],"h1":"Watch the bus, its driver, or an officer.","h2":"In New York, after you stop for a school bus, you may not drive on until the bus starts moving or the bus driver or a traffic officer signals that you can go.","p":"Right. Wait for the bus to move or for a signal to go."},"es":{"q":"En Nueva York, usted se detuvo por un autobús escolar con luces rojas intermitentes. ¿Cuándo puede seguir?","o":["En cuanto los niños se bajen del autobús","Cuando el autobús empiece a moverse, o el chofer o un agente de tránsito le indique que siga","Después de esperar 30 segundos","Cuando el autobús empiece a encender luces amarillas"],"h1":"Fíjese en el autobús, su chofer o un agente.","h2":"En Nueva York, después de detenerse por un autobús escolar, usted no puede seguir hasta que el autobús empiece a moverse o el chofer o un agente de tránsito le indique que puede seguir.","p":"Correcto. Espere a que el autobús se mueva o a una señal para seguir."},"ref":{"doc":"NY","page":40}},{"id":"ny-123","scope":"NY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In New York, a sign says NO STANDING. What may you do there?","o":["Park for up to 15 minutes","Stop to load and unload goods","Stop briefly to pick up or drop off passengers, without leaving the car","Stop for any reason if the driver stays in the car"],"h1":"It is only about people getting in or out.","h2":"In New York, at a NO STANDING sign you may only stop for a moment to pick up or drop off passengers, and the driver may not leave the vehicle.","p":"Right. Only a quick stop for passengers."},"es":{"q":"En Nueva York, un letrero dice NO STANDING. ¿Qué puede hacer ahí?","o":["Estacionarse hasta 15 minutos","Detenerse para cargar y descargar mercancía","Detenerse un momento para recoger o dejar pasajeros, sin bajarse del carro","Detenerse por cualquier motivo si el conductor se queda en el carro"],"h1":"Se trata solo de personas que suben o bajan.","h2":"En Nueva York, ante un letrero de NO STANDING usted solo puede detenerse un momento para recoger o dejar pasajeros, y el conductor no puede bajarse del vehículo.","p":"Correcto. Solo una parada breve para pasajeros."},"ref":{"doc":"NY","page":43}},{"id":"ny-124","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, your car has a disability parking permit issued to your father. When may you park in a reserved disability space?","o":["Any time, because the car has the permit","Only at night","Only for 15 minutes","Only when your father is in the car"],"h1":"The permit belongs to a person, not to the car.","h2":"In New York, you may park in a space reserved for people with disabilities only when the person who received the permit or plates is in the vehicle.","p":"Right. Only when the permit holder is with you."},"es":{"q":"En Nueva York, su carro tiene un permiso de estacionamiento para personas con discapacidad a nombre de su padre. ¿Cuándo puede estacionarse en un espacio reservado?","o":["En cualquier momento, porque el carro tiene el permiso","Solo de noche","Solo por 15 minutos","Solo cuando su padre está en el carro"],"h1":"El permiso es de una persona, no del carro.","h2":"En Nueva York, usted puede estacionarse en un espacio reservado para personas con discapacidad solo cuando la persona que recibió el permiso o las placas está en el vehículo.","p":"Correcto. Solo cuando el titular del permiso va con usted."},"ref":{"doc":"NY","page":44}},{"id":"ny-125","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, an 18-year-old passenger does not wear a seat belt. Who can be fined up to $50?","o":["The passenger","Only the car's owner","No one, because adults may choose","The passenger in the next seat"],"h1":"From age 16, passengers answer for their own belt.","h2":"In New York, a passenger age 16 or older who does not buckle up can be fined up to $50.","p":"Right. The passenger can be fined."},"es":{"q":"En Nueva York, un pasajero de 18 años no usa el cinturón de seguridad. ¿A quién le pueden poner una multa de hasta $50?","o":["Al pasajero","Solo al dueño del carro","A nadie, porque los adultos pueden decidir","Al pasajero del asiento de al lado"],"h1":"Desde los 16 años, los pasajeros responden por su propio cinturón.","h2":"En Nueva York, un pasajero de 16 años o más que no se abrocha el cinturón puede recibir una multa de hasta $50.","p":"Correcto. Al pasajero le pueden poner la multa."},"ref":{"doc":"NY","page":48}},{"id":"ny-126","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, how much space should there be between the center of your chest and the air bag cover in the steering wheel?","o":["About 2 inches","At least 10 inches","At least 3 feet","It does not matter"],"h1":"It is a little less than the length of a sheet of paper.","h2":"The New York Driver's Manual says to sit with at least 10 inches between the center of your chest and the air bag cover.","p":"Right. At least 10 inches."},"es":{"q":"En Nueva York, ¿cuánto espacio debe haber entre el centro de su pecho y la tapa de la bolsa de aire del volante?","o":["Unas 2 pulgadas","Al menos 10 pulgadas","Al menos 3 pies","No importa"],"h1":"Es un poco menos que el largo de una hoja de papel.","h2":"El Manual del Conductor de Nueva York dice que se siente con al menos 10 pulgadas entre el centro de su pecho y la tapa de la bolsa de aire.","p":"Correcto. Al menos 10 pulgadas."},"ref":{"doc":"NY","page":49}},{"id":"ny-127","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, a bicycle is riding in the lane ahead of you inside a roundabout. What should you do?","o":["Pass it quickly on the left","Honk so it moves to the edge","Pass it on the right","Stay behind it; do not pass a bicycle in the roundabout"],"h1":"In a roundabout, the bicycle uses the lane like a car.","h2":"In New York, bicyclists may ride in the lane inside a roundabout like other vehicles, and you should not pass a bicycle in the roundabout.","p":"Right. Stay behind the bicycle."},"es":{"q":"En Nueva York, una bicicleta va en el carril delante de usted dentro de una glorieta. ¿Qué debe hacer?","o":["Rebasarla rápido por la izquierda","Tocar la bocina para que se haga a la orilla","Rebasarla por la derecha","Quedarse detrás; no rebase una bicicleta dentro de la glorieta"],"h1":"En una glorieta, la bicicleta usa el carril como un carro.","h2":"En Nueva York, los ciclistas pueden ir en el carril dentro de una glorieta como los demás vehículos, y usted no debe rebasar una bicicleta dentro de la glorieta.","p":"Correcto. Quédese detrás de la bicicleta."},"ref":{"doc":"NY","page":50}},{"id":"ny-128","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, the Driver's Manual says that after you wake up from sleep you should wait how long before you drive?","o":["At least 15 minutes","No time at all","At least 2 hours","About 30 seconds"],"h1":"It is about a quarter of an hour.","h2":"The New York Driver's Manual says not to drive for at least 15 minutes after you wake up from sleep.","p":"Right. Wait at least 15 minutes."},"es":{"q":"En Nueva York, según el Manual del Conductor, ¿cuánto tiempo debe esperar después de despertarse antes de manejar?","o":["Al menos 15 minutos","Nada de tiempo","Al menos 2 horas","Unos 30 segundos"],"h1":"Es como un cuarto de hora.","h2":"El Manual del Conductor de Nueva York dice que no maneje durante al menos 15 minutos después de despertarse.","p":"Correcto. Espere al menos 15 minutos."},"ref":{"doc":"NY","page":52}},{"id":"ny-129","scope":"NY","cat":"licensing","sign":null,"c":1,"en":{"q":"In New York, a junior license holder had a 120-day suspension for a phone violation. Within six months of getting the license back, the teen is convicted again. What happens?","o":["Only another warning","The license is revoked for at least one year","A 30-day suspension","Only a fine, with no license action"],"h1":"It is much longer than the first 120 days.","h2":"In New York, a junior or probationary driver convicted again of phone use or texting within six months after the license is restored faces a revocation of at least one year.","p":"Right. At least a one-year revocation."},"es":{"q":"En Nueva York, un joven con licencia junior tuvo una suspensión de 120 días por usar el teléfono. Dentro de los seis meses después de recuperar la licencia, lo condenan otra vez. ¿Qué pasa?","o":["Solo otra advertencia","La licencia se revoca por al menos un año","Una suspensión de 30 días","Solo una multa, sin castigo a la licencia"],"h1":"Es mucho más largo que los primeros 120 días.","h2":"En Nueva York, un conductor junior o en periodo de prueba condenado otra vez por usar el teléfono o enviar mensajes dentro de los seis meses después de recuperar la licencia enfrenta una revocación de al menos un año.","p":"Correcto. Al menos un año de revocación."},"ref":{"doc":"NY","page":52}},{"id":"ny-130","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, what does the Implied Consent law mean?","o":["You agree to let police search your phone","You agree to pay any ticket without going to court","You agree to take a road test every year","By driving in New York, you are considered to have agreed to a chemical test for alcohol or drugs"],"h1":"It is about breath, blood, urine or saliva tests.","h2":"Under New York's Implied Consent law, when you drive in the state you are considered to have agreed to take a chemical test for alcohol or drugs.","p":"Right. Driving here means you agreed to a chemical test."},"es":{"q":"En Nueva York, ¿qué significa la ley de Consentimiento Implícito (Implied Consent)?","o":["Usted acepta que la policía revise su teléfono","Usted acepta pagar cualquier multa sin ir a la corte","Usted acepta hacer un examen práctico cada año","Al manejar en Nueva York, se considera que usted aceptó una prueba química de alcohol o drogas"],"h1":"Se trata de pruebas de aliento, sangre, orina o saliva.","h2":"Según la ley de Consentimiento Implícito de Nueva York, cuando usted maneja en el estado se considera que aceptó hacerse una prueba química de alcohol o drogas.","p":"Correcto. Manejar aquí significa que aceptó una prueba química."},"ref":{"doc":"NY","page":56}},{"id":"ny-131","scope":"NY","cat":"licensing","sign":null,"c":0,"en":{"q":"In New York, a person under 21 uses a driver license as proof of age to buy alcohol illegally. What does state law require?","o":["The driver license is suspended","Only a warning","Only the store is punished","Two points on the license, nothing more"],"h1":"The license was misused, so the license is affected.","h2":"In New York, using a driver license or non-driver ID to buy alcohol illegally leads to a required suspension of the license or of the right to apply for one.","p":"Right. The license is suspended."},"es":{"q":"En Nueva York, una persona menor de 21 años usa una licencia de conducir como prueba de edad para comprar alcohol ilegalmente. ¿Qué exige la ley del estado?","o":["Se suspende la licencia de conducir","Solo una advertencia","Solo se castiga a la tienda","Dos puntos en la licencia, nada más"],"h1":"Se usó mal la licencia, así que la licencia se ve afectada.","h2":"En Nueva York, usar una licencia de conducir o una identificación para comprar alcohol ilegalmente lleva a la suspensión obligatoria de la licencia o del derecho a solicitarla.","p":"Correcto. Se suspende la licencia."},"ref":{"doc":"NY","page":57}},{"id":"ny-132","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, a passenger in a car on a public road smokes marijuana (cannabis). Is this allowed?","o":["Yes, because cannabis is legal for adults","No, it is a traffic infraction","Yes, if the windows are open","Yes, as long as the driver does not smoke"],"h1":"The same rule covers drinking alcohol in a car.","h2":"In New York, it is a traffic infraction for a driver or passenger to consume marijuana (cannabis) in a motor vehicle on a public road.","p":"Right. It is a traffic infraction."},"es":{"q":"En Nueva York, un pasajero en un carro en una vía pública fuma marihuana (cannabis). ¿Está permitido?","o":["Sí, porque el cannabis es legal para adultos","No, es una infracción de tránsito","Sí, si las ventanas están abiertas","Sí, mientras el conductor no fume"],"h1":"La misma regla aplica a tomar alcohol en un carro.","h2":"En Nueva York, es una infracción de tránsito que un conductor o pasajero consuma marihuana (cannabis) en un vehículo en una vía pública.","p":"Correcto. Es una infracción de tránsito."},"ref":{"doc":"NY","page":57}},{"id":"ny-133","scope":"NY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In New York, you are following a bus with passengers toward a railroad crossing. No train is in sight. What should you expect the bus to do?","o":["Speed up to cross quickly","Move onto the shoulder","Stop at the crossing","Cross without slowing down"],"h1":"Some vehicles must stop at every crossing.","h2":"In New York, school buses, other buses with passengers, and vehicles carrying explosives or flammable cargo must stop at all railroad crossings, so be ready to stop behind them.","p":"Right. The bus must stop at the crossing."},"es":{"q":"En Nueva York, usted va detrás de un autobús con pasajeros hacia un cruce de tren. No se ve ningún tren. ¿Qué debe esperar que haga el autobús?","o":["Acelerar para cruzar rápido","Pasarse al acotamiento","Detenerse en el cruce","Cruzar sin bajar la velocidad"],"h1":"Algunos vehículos deben detenerse en todos los cruces.","h2":"En Nueva York, los autobuses escolares, otros autobuses con pasajeros y los vehículos con explosivos o carga inflamable deben detenerse en todos los cruces de tren, así que esté listo para detenerse detrás de ellos.","p":"Correcto. El autobús debe detenerse en el cruce."},"ref":{"doc":"NY","page":61}},{"id":"ny-134","scope":"NY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In New York, the entrance lane to an expressway is too short to reach expressway speed. What is the safest way to enter?","o":["Drive on the shoulder until a gap appears","Enter slowly and let traffic go around you","Back up and use a different ramp","Stop, wait for a large gap in traffic, then enter and speed up quickly"],"h1":"You need a big space because you start slowly.","h2":"In New York, if an expressway entrance lane is too short to speed up, the safest way is to stop and wait for a large gap, then enter and speed up quickly.","p":"Right. Wait for a large gap, then go."},"es":{"q":"En Nueva York, el carril de entrada a una autopista es demasiado corto para alcanzar la velocidad de la autopista. ¿Cuál es la forma más segura de entrar?","o":["Manejar por el acotamiento hasta que haya un espacio","Entrar despacio y dejar que el tráfico lo rodee","Retroceder y usar otra rampa","Detenerse, esperar un espacio grande en el tráfico y luego entrar y acelerar rápido"],"h1":"Necesita un espacio grande porque empieza despacio.","h2":"En Nueva York, si el carril de entrada a una autopista es demasiado corto para acelerar, lo más seguro es detenerse y esperar un espacio grande, y luego entrar y acelerar rápido.","p":"Correcto. Espere un espacio grande y luego entre."},"ref":{"doc":"NY","page":62}},{"id":"ny-135","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, about how far ahead do your headlights light the road at night?","o":["About 350 feet","About 50 feet","About 1,000 feet","About one mile"],"h1":"It is a bit longer than a football field.","h2":"The New York Driver's Manual says your headlights cover about 350 feet ahead, so drive at a speed that lets you stop within that distance.","p":"Right. About 350 feet."},"es":{"q":"En Nueva York, ¿hasta qué distancia, más o menos, iluminan el camino sus faros de noche?","o":["Unos 350 pies","Unos 50 pies","Unos 1,000 pies","Una milla"],"h1":"Es un poco más que un campo de fútbol americano.","h2":"El Manual del Conductor de Nueva York dice que sus faros alumbran unos 350 pies hacia adelante, así que maneje a una velocidad que le permita detenerse dentro de esa distancia.","p":"Correcto. Unos 350 pies."},"ref":{"doc":"NY","page":62}},{"id":"ny-136","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, during what hours does the law require your headlights to be on?","o":["Only from midnight to 5 a.m.","From one-half hour after sunset to one-half hour before sunrise","Only from 9 p.m. to 5 a.m.","Only when the street lights are off"],"h1":"It starts a little after the sun goes down.","h2":"New York law requires headlights from one-half hour after sunset to one-half hour before sunrise.","p":"Right. Half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Nueva York, ¿en qué horas exige la ley que tenga los faros encendidos?","o":["Solo de medianoche a las 5 a.m.","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Solo de 9 p.m. a 5 a.m.","Solo cuando las luces de la calle están apagadas"],"h1":"Empieza un poco después de que se pone el sol.","h2":"La ley de Nueva York exige los faros desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. De media hora después de la puesta del sol a media hora antes de la salida."},"ref":{"doc":"NY","page":63}},{"id":"ny-137","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, it is daytime, but heavy smoke means you cannot see clearly beyond about 800 feet. Must your headlights be on?","o":["No, headlights are only required at night","Only if you are on an expressway","Yes, they are required when you cannot see 1,000 feet ahead","No, parking lights are enough"],"h1":"The law gives a distance in feet.","h2":"New York law requires headlights whenever visibility is less than 1,000 feet, even in daytime.","p":"Right. Under 1,000 feet of visibility, headlights go on."},"es":{"q":"En Nueva York, es de día, pero el humo espeso no le deja ver bien más allá de unos 800 pies. ¿Debe tener los faros encendidos?","o":["No, los faros solo son obligatorios de noche","Solo si está en una autopista","Sí, son obligatorios cuando no puede ver 1,000 pies adelante","No, las luces de estacionamiento son suficientes"],"h1":"La ley da una distancia en pies.","h2":"La ley de Nueva York exige los faros cada vez que la visibilidad es menor de 1,000 pies, incluso de día.","p":"Correcto. Con menos de 1,000 pies de visibilidad, se encienden los faros."},"ref":{"doc":"NY","page":63}},{"id":"ny-138","scope":"NY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In New York, you are using high beams and a car comes toward you. Within how many feet of it must you switch to low beams?","o":["100 feet","200 feet","1,000 feet","500 feet"],"h1":"It is farther than the distance for a car ahead of you.","h2":"In New York, you must switch to low beams within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of oncoming traffic."},"es":{"q":"En Nueva York, usted lleva las luces altas y un carro viene de frente. ¿A cuántos pies de él debe cambiar a luces bajas?","o":["100 pies","200 pies","1,000 pies","500 pies"],"h1":"Es más lejos que la distancia para un carro que va delante de usted.","h2":"En Nueva York, usted debe cambiar a luces bajas a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. Baje las luces a menos de 500 pies del tráfico de frente."},"ref":{"doc":"NY","page":63}},{"id":"ny-139","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, where there is no sidewalk, how should people walk along the road?","o":["With their backs to traffic","Facing traffic, as far from it as possible","In the middle of the lane","On either side; it does not matter"],"h1":"Walkers should be able to see the cars coming.","h2":"In New York, pedestrians must use the sidewalk when there is one; otherwise they must walk facing traffic, as far from the nearest lane as possible.","p":"Right. Walk facing traffic."},"es":{"q":"En Nueva York, donde no hay acera, ¿cómo deben caminar las personas a lo largo de la calle?","o":["De espaldas al tráfico","De frente al tráfico, lo más lejos posible de él","En medio del carril","De cualquier lado; no importa"],"h1":"Los peatones deben poder ver los carros que vienen.","h2":"En Nueva York, los peatones deben usar la acera cuando la hay; si no, deben caminar de frente al tráfico, lo más lejos posible del carril más cercano.","p":"Correcto. Caminar de frente al tráfico."},"ref":{"doc":"NY","page":67}},{"id":"ny-140","scope":"NY","cat":"licensing","sign":null,"c":2,"en":{"q":"In New York, what license do you need to ride a Class A moped (top speed 31 to 40 mph)?","o":["Any class of driver license","No license at all","A motorcycle (Class M) license or permit","A commercial bus license"],"h1":"The fastest mopeds are treated more like motorcycles.","h2":"In New York, a Class A moped needs a motorcycle (Class M) license or learner permit, while Class B and C mopeds can be ridden with any class of license.","p":"Right. A Class A moped needs a motorcycle license."},"es":{"q":"En Nueva York, ¿qué licencia necesita para manejar un ciclomotor Clase A (velocidad máxima de 31 a 40 mph)?","o":["Cualquier clase de licencia de conducir","Ninguna licencia","Una licencia o permiso de motocicleta (Clase M)","Una licencia comercial de autobús"],"h1":"Los ciclomotores más rápidos se tratan más como motocicletas.","h2":"En Nueva York, un ciclomotor Clase A necesita una licencia o permiso de aprendiz de motocicleta (Clase M), mientras que los de Clase B y C se pueden manejar con cualquier clase de licencia.","p":"Correcto. Un ciclomotor Clase A necesita licencia de motocicleta."},"ref":{"doc":"NY","page":73}},{"id":"ny-141","scope":"NY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In New York, a vehicle ahead has a reflective orange triangle on its back. What does it tell you?","o":["It is a slow-moving vehicle, such as a farm vehicle","It is a school bus","It is carrying explosives","It is a police car"],"h1":"Farm tractors and horse-drawn wagons show it.","h2":"In New York, the reflective orange triangle is the slow-moving vehicle symbol, shown on animal-drawn vehicles, most farm vehicles, construction equipment and rural mail vehicles.","p":"Right. It marks a slow-moving vehicle."},"es":{"q":"En Nueva York, un vehículo delante de usted tiene un triángulo naranja reflectante en la parte de atrás. ¿Qué le indica?","o":["Es un vehículo lento, como un vehículo agrícola","Es un autobús escolar","Lleva explosivos","Es un carro de policía"],"h1":"Los tractores agrícolas y las carretas tiradas por caballos lo llevan.","h2":"En Nueva York, el triángulo naranja reflectante es el símbolo de vehículo lento, que llevan los vehículos tirados por animales, la mayoría de los vehículos agrícolas, la maquinaria de construcción y los vehículos de correo rural.","p":"Correcto. Marca un vehículo lento."},"ref":{"doc":"NY","page":76}},{"id":"ny-142","scope":"NY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In New York, a tractor-trailer with a long hood can have a blind spot of about how far in front of it?","o":["2 feet","20 feet","200 feet","There is no blind spot in front"],"h1":"It is about the length of one car or more.","h2":"The New York Driver's Manual says tractors with long hoods can have a blind spot of about 20 feet in front, so do not cut in close ahead of them.","p":"Right. About 20 feet in front."},"es":{"q":"En Nueva York, ¿de qué tamaño, más o menos, puede ser el punto ciego delante de un tractocamión con el cofre largo?","o":["2 pies","20 pies","200 pies","No tiene punto ciego adelante"],"h1":"Es más o menos el largo de un carro o más.","h2":"El Manual del Conductor de Nueva York dice que los tractocamiones con cofre largo pueden tener un punto ciego de unos 20 pies adelante, así que no se meta muy cerca delante de ellos.","p":"Correcto. Unos 20 pies adelante."},"ref":{"doc":"NY","page":74}},{"id":"ny-143","scope":"NY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In New York, may a police officer stop you just because a passenger is not wearing a seat belt?","o":["No, only if you break another law too","Only on expressways","Yes, New York is a primary enforcement state","Only if the passenger is under 8"],"h1":"The seat belt alone is enough reason.","h2":"New York is a primary enforcement state, so a police officer can pull you over just because you or a passenger is not wearing a seat belt.","p":"Right. A seat belt violation alone is enough."},"es":{"q":"En Nueva York, ¿puede un policía detenerlo solo porque un pasajero no lleva el cinturón de seguridad?","o":["No, solo si usted también viola otra ley","Solo en autopistas","Sí, Nueva York es un estado de aplicación primaria","Solo si el pasajero tiene menos de 8 años"],"h1":"El cinturón por sí solo es razón suficiente.","h2":"Nueva York es un estado de aplicación primaria, así que un policía puede detenerlo solo porque usted o un pasajero no lleva el cinturón de seguridad.","p":"Correcto. No llevar el cinturón basta."},"ref":{"doc":"NY","page":48}},{"id":"ny-144","scope":"NY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In New York, children are playing near your home, and you need to back out of the driveway. What does the Driver's Manual say to do first?","o":["Honk twice and back out slowly","Use only your mirrors","Back out fast so you are in the way for less time","Get out of the car and check behind it"],"h1":"Small children can be hidden right behind the car.","h2":"The New York Driver's Manual says that before you back into or out of a driveway, you should get out of the vehicle and check behind it, especially when children are near.","p":"Right. Get out and look behind the car."},"es":{"q":"En Nueva York, hay niños jugando cerca de su casa y usted necesita salir en reversa de la entrada. ¿Qué dice el Manual del Conductor que haga primero?","o":["Tocar la bocina dos veces y salir despacio","Usar solo los espejos","Salir rápido para estorbar menos tiempo","Bajarse del carro y revisar detrás de él"],"h1":"Los niños pequeños pueden estar escondidos justo detrás del carro.","h2":"El Manual del Conductor de Nueva York dice que antes de entrar o salir en reversa de una entrada de garaje, usted debe bajarse del vehículo y revisar detrás de él, sobre todo cuando hay niños cerca.","p":"Correcto. Bájese y mire detrás del carro."},"ref":{"doc":"NY","page":67}},{"id":"ny-145","scope":"NY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In New York, a driver leaves the scene of a crash in which someone was hurt. What kind of offense is this?","o":["A crime (criminal violation)","Only a parking violation","No offense if the damage was small","Only a warning"],"h1":"Leaving after property damage is a traffic violation; an injury makes it more serious.","h2":"In New York, leaving the scene of a crash that causes injury or death is a criminal violation, while leaving a property-damage crash is a traffic violation.","p":"Right. It is a crime."},"es":{"q":"En Nueva York, un conductor se va del lugar de un choque en el que alguien resultó herido. ¿Qué tipo de falta es?","o":["Un delito (violación penal)","Solo una infracción de estacionamiento","No es falta si el daño fue pequeño","Solo una advertencia"],"h1":"Irse después de daños a la propiedad es una infracción de tránsito; si hay heridos es más grave.","h2":"En Nueva York, irse del lugar de un choque con heridos o muertos es una violación penal, mientras que irse de un choque con solo daños a la propiedad es una infracción de tránsito.","p":"Correcto. Es un delito."},"ref":{"doc":"NY","page":77}},{"id":"ny-146","scope":"NY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In New York, your car suddenly will not respond when you turn the steering wheel. What should you do?","o":["Brake hard right away","Slowly ease off the gas, turn on your emergency lights, and keep off the brake while it is safe","Turn off the engine at once","Speed up to regain control"],"h1":"A sudden change in speed could send the car out of control.","h2":"In New York, if your steering fails, slowly take your foot off the gas, turn on your emergency lights and keep off the brake while it is safe; once you have slowed, brake very gently to stop.","p":"Right. Ease off the gas, flashers on, brake gently later."},"es":{"q":"En Nueva York, su carro de repente no responde cuando gira el volante. ¿Qué debe hacer?","o":["Frenar fuerte de inmediato","Soltar el acelerador poco a poco, encender las luces de emergencia y no frenar mientras sea seguro","Apagar el motor enseguida","Acelerar para recuperar el control"],"h1":"Un cambio brusco de velocidad podría hacerle perder el control.","h2":"En Nueva York, si falla la dirección, suelte el acelerador poco a poco, encienda las luces de emergencia y no frene mientras sea seguro; cuando haya bajado la velocidad, frene con mucho cuidado para detenerse.","p":"Correcto. Suelte el acelerador, luces de emergencia y frene con suavidad después."},"ref":{"doc":"NY","page":65}},{"id":"oh-001","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what is the youngest age to get a temporary instruction permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is half a year before the probationary license age.","h2":"In Ohio you can get a temporary instruction permit at 15 and a half years old.","p":"Right. The Ohio permit starts at 15 and a half."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener un permiso temporal de aprendizaje?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es medio año antes de la edad para la licencia probatoria.","h2":"En Ohio usted puede obtener un permiso temporal de aprendizaje a los 15 años y medio.","p":"Correcto. El permiso en Ohio empieza a los 15 años y medio."},"zh":{"q":"在 Ohio，最小几岁可以拿到临时学习驾照（temporary instruction permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它比拿试用驾照的年龄早半年。","h2":"在 Ohio，你 15 岁半就可以拿到临时学习驾照。","p":"对。Ohio 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Ohio, tuổi nhỏ nhất để lấy giấy phép tập lái tạm thời (temporary instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là nửa năm trước tuổi lấy bằng lái thử thách.","h2":"Ở Ohio, bạn có thể lấy giấy phép tập lái tạm thời khi 15 tuổi rưỡi.","p":"Đúng. Ở Ohio, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Ohio, ano ang pinakabatang edad para makakuha ng temporary instruction permit?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Kalahating taon ito bago ang edad para sa probationary license.","h2":"Sa Ohio, puwede kang kumuha ng temporary instruction permit sa edad na 15 at kalahati.","p":"Tama. Nagsisimula ang permit sa Ohio sa 15 at kalahati."},"ar":{"q":"في Ohio، ما أصغر عمر للحصول على تصريح التعلّم المؤقت (temporary instruction permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو نصف سنة قبل عمر الرخصة التجريبية.","h2":"في Ohio يمكنك الحصول على تصريح التعلّم المؤقت في عمر 15 سنة ونصف.","p":"صحيح. في Ohio يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-002","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how long is a temporary instruction permit valid?","o":["One year","Six months","Two years","Four years"],"h1":"It lasts long enough to cover the holding period twice.","h2":"In Ohio a temporary instruction permit is valid for one year.","p":"Right. The permit is valid for one year."},"es":{"q":"En Ohio, ¿por cuánto tiempo es válido un permiso temporal de aprendizaje?","o":["Un año","Seis meses","Dos años","Cuatro años"],"h1":"Dura lo suficiente para cubrir dos veces el período de espera.","h2":"En Ohio un permiso temporal de aprendizaje es válido por un año.","p":"Correcto. El permiso es válido por un año."},"zh":{"q":"在 Ohio，临时学习驾照有效期多久？","o":["一年","六个月","两年","四年"],"h1":"它够长，可以覆盖两次必须持有的时间。","h2":"在 Ohio，临时学习驾照有效期是一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Ohio, giấy phép tập lái tạm thời (temporary instruction permit) có giá trị trong bao lâu?","o":["Một năm","Sáu tháng","Hai năm","Bốn năm"],"h1":"Nó đủ dài bằng hai lần thời gian phải giữ giấy phép.","h2":"Ở Ohio, giấy phép tập lái tạm thời có giá trị trong một năm.","p":"Đúng. Giấy phép có giá trị một năm."},"tl":{"q":"Sa Ohio, gaano katagal valid ang temporary instruction permit?","o":["Isang taon","Anim na buwan","Dalawang taon","Apat na taon"],"h1":"Sapat ang haba nito para dalawang beses ang panahon ng paghawak ng permit.","h2":"Sa Ohio, valid ang temporary instruction permit nang isang taon.","p":"Tama. Valid ang permit nang isang taon."},"ar":{"q":"في Ohio، ما مدة صلاحية تصريح التعلّم المؤقت (temporary instruction permit)؟","o":["سنة واحدة","ستة أشهر","سنتان","أربع سنوات"],"h1":"مدته طويلة بما يكفي لتغطية فترة الاحتفاظ بالتصريح مرتين.","h2":"في Ohio يكون تصريح التعلّم المؤقت صالحًا لمدة سنة واحدة.","p":"صحيح. التصريح صالح لمدة سنة واحدة."},"ref":{"doc":"OH","page":null}},{"id":"oh-003","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how long must a teen hold a temporary instruction permit before getting a probationary license?","o":["One month","At least six months","At least one year","At least two years"],"h1":"It is half a year.","h2":"In Ohio a teen must hold a temporary instruction permit for at least six months before getting a probationary license.","p":"Right. Hold the permit at least six months."},"es":{"q":"En Ohio, ¿cuánto tiempo debe tener un joven el permiso temporal antes de obtener la licencia probatoria?","o":["Un mes","Por lo menos seis meses","Por lo menos un año","Por lo menos dos años"],"h1":"Es medio año.","h2":"En Ohio un joven debe tener el permiso temporal de aprendizaje por lo menos seis meses antes de obtener la licencia probatoria.","p":"Correcto. Debe tener el permiso por lo menos seis meses."},"zh":{"q":"在 Ohio，青少年拿试用驾照（probationary license）前，必须持有临时学习驾照多久？","o":["一个月","至少六个月","至少一年","至少两年"],"h1":"它是半年。","h2":"在 Ohio，青少年必须持有临时学习驾照至少六个月，才能拿试用驾照。","p":"对。持有学习驾照至少六个月。"},"vi":{"q":"Ở Ohio, thiếu niên phải giữ giấy phép tập lái tạm thời (temporary instruction permit) bao lâu trước khi lấy bằng lái thử thách (probationary license)?","o":["Một tháng","Ít nhất sáu tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Ohio, thiếu niên phải giữ giấy phép tập lái tạm thời ít nhất sáu tháng trước khi lấy bằng lái thử thách.","p":"Đúng. Giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa Ohio, gaano katagal dapat hawak ng isang teen ang temporary instruction permit bago makakuha ng probationary license?","o":["Isang buwan","Hindi bababa sa anim na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Ohio, dapat hawak ng teen ang temporary instruction permit nang hindi bababa sa anim na buwan bago makakuha ng probationary license.","p":"Tama. Hawakan ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Ohio، كم مدة يجب أن يحتفظ المراهق بـتصريح التعلّم المؤقت (temporary instruction permit) قبل الحصول على الرخصة التجريبية (probationary license)؟","o":["شهر واحد","ستة أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"هي نصف سنة.","h2":"في Ohio يجب أن يحتفظ المراهق بتصريح التعلّم المؤقت ستة أشهر على الأقل قبل الحصول على الرخصة التجريبية.","p":"صحيح. احتفظ بالتصريح ستة أشهر على الأقل."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-004","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what is the youngest age to get a probationary driver's license?","o":["15","17","18","16"],"h1":"It is six months after the earliest permit age.","h2":"In Ohio you can get a probationary driver's license at 16, after holding a permit for at least six months.","p":"Right. The probationary license starts at 16."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para obtener una licencia de conducir probatoria?","o":["15","17","18","16"],"h1":"Es seis meses después de la edad mínima para el permiso.","h2":"En Ohio usted puede obtener la licencia probatoria a los 16 años, después de tener el permiso por lo menos seis meses.","p":"Correcto. La licencia probatoria empieza a los 16."},"zh":{"q":"在 Ohio，最小几岁可以拿到试用驾照（probationary driver's license）？","o":["15","17","18","16"],"h1":"它比最早拿学习驾照的年龄晚六个月。","h2":"在 Ohio，持有学习驾照至少六个月以后，你 16 岁就可以拿到试用驾照。","p":"对。试用驾照从 16 岁开始。"},"vi":{"q":"Ở Ohio, tuổi nhỏ nhất để lấy bằng lái thử thách (probationary license) là bao nhiêu?","o":["15","17","18","16"],"h1":"Đó là sáu tháng sau tuổi sớm nhất để lấy giấy phép tập lái.","h2":"Ở Ohio, bạn có thể lấy bằng lái thử thách khi 16 tuổi, sau khi giữ giấy phép tập lái ít nhất sáu tháng.","p":"Đúng. Bằng lái thử thách bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Ohio, ano ang pinakabatang edad para makakuha ng probationary driver's license?","o":["15","17","18","16"],"h1":"Anim na buwan ito pagkatapos ng pinakamaagang edad para sa permit.","h2":"Sa Ohio, puwede kang kumuha ng probationary driver's license sa edad na 16, pagkatapos hawakan ang permit nang hindi bababa sa anim na buwan.","p":"Tama. Nagsisimula ang probationary license sa 16."},"ar":{"q":"في Ohio، ما أصغر عمر للحصول على الرخصة التجريبية (probationary license)؟","o":["15","17","18","16"],"h1":"هو بعد ستة أشهر من أصغر عمر للتصريح.","h2":"في Ohio يمكنك الحصول على الرخصة التجريبية في عمر 16 سنة، بعد الاحتفاظ بالتصريح ستة أشهر على الأقل.","p":"صحيح. تبدأ الرخصة التجريبية في عمر 16 سنة."},"ref":{"doc":"OH","page":null}},{"id":"oh-005","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of supervised driving must a teen complete before a probationary license?","o":["20 hours","30 hours","50 hours","100 hours"],"h1":"It is half of one hundred.","h2":"In Ohio a teen must complete 50 hours of supervised driving before getting a probationary license.","p":"Right. 50 supervised hours."},"es":{"q":"En Ohio, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia probatoria?","o":["20 horas","30 horas","50 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Ohio un joven debe completar 50 horas de manejo supervisado antes de obtener la licencia probatoria.","p":"Correcto. 50 horas supervisadas."},"zh":{"q":"在 Ohio，青少年拿试用驾照前，必须完成多少小时有人监督的驾驶？","o":["20 小时","30 小时","50 小时","100 小时"],"h1":"它是一百的一半。","h2":"在 Ohio，青少年拿试用驾照前必须完成 50 小时有人监督的驾驶。","p":"对。50 小时有人监督的驾驶。"},"vi":{"q":"Ở Ohio, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi lấy bằng lái thử thách (probationary license)?","o":["20 giờ","30 giờ","50 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Ohio, thiếu niên phải lái xe có người giám sát 50 giờ trước khi lấy bằng lái thử thách.","p":"Đúng. 50 giờ có người giám sát."},"tl":{"q":"Sa Ohio, ilang oras ng supervised driving ang dapat tapusin ng teen bago ang probationary license?","o":["20 oras","30 oras","50 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Sa Ohio, dapat tapusin ng teen ang 50 oras ng supervised driving bago makakuha ng probationary license.","p":"Tama. 50 oras na may bantay."},"ar":{"q":"في Ohio، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الرخصة التجريبية (probationary license)؟","o":["20 ساعة","30 ساعة","50 ساعة","100 ساعة"],"h1":"هو نصف المئة.","h2":"في Ohio يجب أن يكمل المراهق 50 ساعة من القيادة تحت الإشراف قبل الحصول على الرخصة التجريبية.","p":"صحيح. 50 ساعة تحت الإشراف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-006","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many of the supervised driving hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"In Ohio 10 of the 50 supervised driving hours must be at night.","p":"Right. 10 hours at night."},"es":{"q":"En Ohio, ¿cuántas de las horas de manejo supervisado deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"En Ohio 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. 10 horas de noche."},"zh":{"q":"在 Ohio，有人监督的驾驶时间里，有多少小时必须在晚上？","o":["10 小时","5 小时","15 小时","25 小时"],"h1":"它是全部时间的五分之一。","h2":"在 Ohio，50 小时有人监督的驾驶里，10 小时必须在晚上。","p":"对。晚上 10 小时。"},"vi":{"q":"Ở Ohio, bao nhiêu giờ trong số giờ lái xe có người giám sát phải là vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số giờ.","h2":"Ở Ohio, 10 trong số 50 giờ lái xe có người giám sát phải là vào ban đêm.","p":"Đúng. 10 giờ vào ban đêm."},"tl":{"q":"Sa Ohio, ilan sa mga oras ng supervised driving ang dapat gawin sa gabi?","o":["10 oras","5 oras","15 oras","25 oras"],"h1":"Isang-ikalima ito ng kabuuan.","h2":"Sa Ohio, 10 sa 50 oras ng supervised driving ang dapat gawin sa gabi.","p":"Tama. 10 oras sa gabi."},"ar":{"q":"في Ohio، كم ساعة من ساعات القيادة تحت الإشراف يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"في Ohio يجب أن تكون 10 من أصل 50 ساعة من القيادة تحت الإشراف في الليل.","p":"صحيح. 10 ساعات في الليل."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-007","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, who certifies a teen's supervised driving hours?","o":["The driving test examiner","A parent or guardian, by signing an affidavit","A police officer","The teen alone"],"h1":"It is the adult responsible for the teen.","h2":"In Ohio a parent or guardian signs an affidavit that the teen completed the supervised hours, and lying on it can bring a fine or jail.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Ohio, ¿quién certifica las horas de manejo supervisado de un joven?","o":["El examinador de la prueba de manejo","Su padre, madre o tutor, firmando una declaración jurada","Un policía","El joven solo"],"h1":"Es el adulto responsable del joven.","h2":"En Ohio el padre, la madre o el tutor firma una declaración jurada de que el joven completó las horas supervisadas, y mentir en ella puede causar una multa o cárcel.","p":"Correcto. El padre, la madre o el tutor firma por las horas."},"zh":{"q":"在 Ohio，谁证明青少年有人监督的驾驶时间？","o":["路考考官","父母或监护人，签一份宣誓书（affidavit）","警察","青少年自己"],"h1":"是对青少年负责的成年人。","h2":"在 Ohio，父母或监护人签一份宣誓书（affidavit），证明青少年完成了有人监督的驾驶时间，在上面说谎可能被罚款或坐牢。","p":"对。父母或监护人为练习时间签字。"},"vi":{"q":"Ở Ohio, ai xác nhận số giờ lái xe có người giám sát của thiếu niên?","o":["Giám khảo thi lái xe","Cha mẹ hoặc người giám hộ, bằng cách ký một bản cam kết (affidavit)","Một cảnh sát","Chỉ một mình thiếu niên"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên.","h2":"Ở Ohio, cha mẹ hoặc người giám hộ ký một bản cam kết (affidavit) rằng thiếu niên đã lái đủ số giờ có người giám sát, và khai gian có thể bị phạt tiền hoặc ngồi tù.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa Ohio, sino ang nagpapatunay sa mga oras ng supervised driving ng teen?","o":["Ang examiner ng driving test","Isang magulang o guardian, sa pagpirma ng affidavit","Isang pulis","Ang teen lang"],"h1":"Ito ang adultong responsable sa teen.","h2":"Sa Ohio, pumipirma ang magulang o guardian ng affidavit na natapos ng teen ang mga oras na may bantay, at ang pagsisinungaling dito ay puwedeng magdulot ng multa o kulong.","p":"Tama. Magulang o guardian ang pumipirma para sa mga oras."},"ar":{"q":"في Ohio، من يؤكد ساعات القيادة تحت الإشراف التي أكملها المراهق؟","o":["فاحص اختبار القيادة","أحد الوالدين أو الوصي، بتوقيع إقرار رسمي (affidavit)","شرطي","المراهق وحده"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Ohio يوقّع أحد الوالدين أو الوصي إقرارًا رسميًا (affidavit) بأن المراهق أكمل الساعات تحت الإشراف، والكذب فيه قد يؤدي إلى غرامة أو سجن.","p":"صحيح. أحد الوالدين أو الوصي يوقّع على الساعات."},"ref":{"doc":"OH","page":null}},{"id":"oh-008","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, during the first 12 months with a probationary license, when may a teen not drive unless a parent or guardian is along?","o":["9 p.m. to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","Midnight to 6 a.m."],"h1":"It starts at midnight.","h2":"In Ohio, during the first 12 months, a probationary driver may not drive from midnight to 6 a.m. unless a parent or guardian is in the car, with a few exceptions such as work or school.","p":"Right. Midnight to 6 a.m. in the first year."},"es":{"q":"En Ohio, durante los primeros 12 meses con licencia probatoria, ¿en qué horario no puede manejar un joven sin uno de sus padres o tutor?","o":["De 9 p.m. a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","De medianoche a 6 a.m."],"h1":"Empieza a la medianoche.","h2":"En Ohio, durante los primeros 12 meses, un conductor con licencia probatoria no puede manejar de medianoche a 6 a.m. sin su padre, madre o tutor en el carro, con algunas excepciones como el trabajo o la escuela.","p":"Correcto. De medianoche a 6 a.m. el primer año."},"zh":{"q":"在 Ohio，持试用驾照的前 12 个月，除非父母或监护人在车上，青少年什么时候不能开车？","o":["晚上 9 点到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","午夜到早上 6 点"],"h1":"它从午夜开始。","h2":"在 Ohio，前 12 个月里，持试用驾照的司机从午夜到早上 6 点不能开车，除非父母或监护人在车上，也有一些例外，比如上班或上学。","p":"对。第一年是午夜到早上 6 点。"},"vi":{"q":"Ở Ohio, trong 12 tháng đầu có bằng lái thử thách (probationary license), thiếu niên không được lái xe vào giờ nào nếu không có cha mẹ hoặc người giám hộ đi cùng?","o":["9 giờ tối đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng"],"h1":"Nó bắt đầu lúc nửa đêm.","h2":"Ở Ohio, trong 12 tháng đầu, người có bằng lái thử thách không được lái xe từ nửa đêm đến 6 giờ sáng nếu không có cha mẹ hoặc người giám hộ trong xe, trừ một vài trường hợp như đi làm hoặc đi học.","p":"Đúng. Từ nửa đêm đến 6 giờ sáng trong năm đầu tiên."},"tl":{"q":"Sa Ohio, sa unang 12 buwan na may probationary license, kailan hindi puwedeng magmaneho ang teen kung walang kasamang magulang o guardian?","o":["9 p.m. hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Sa Ohio, sa unang 12 buwan, hindi puwedeng magmaneho ang probationary driver mula hatinggabi hanggang 6 a.m. kung walang magulang o guardian sa kotse, maliban sa ilang kaso tulad ng trabaho o paaralan.","p":"Tama. Hatinggabi hanggang 6 a.m. sa unang taon."},"ar":{"q":"في Ohio، خلال أول 12 شهرًا مع الرخصة التجريبية (probationary license)، متى لا يجوز للمراهق القيادة إلا إذا كان معه أحد الوالدين أو الوصي؟","o":["من 9 مساءً إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا"],"h1":"تبدأ عند منتصف الليل.","h2":"في Ohio، خلال أول 12 شهرًا، لا يجوز لصاحب الرخصة التجريبية القيادة من منتصف الليل إلى 6 صباحًا إلا إذا كان أحد الوالدين أو الوصي في السيارة، مع بعض الاستثناءات مثل العمل أو المدرسة.","p":"صحيح. من منتصف الليل إلى 6 صباحًا في السنة الأولى."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-009","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, after holding a probationary license for 12 months, which hours are still restricted unless a parent or guardian is along?","o":["Midnight to 6 a.m.","11 p.m. to 5 a.m.","1 a.m. to 5 a.m.","No hours are restricted"],"h1":"The window becomes shorter at both ends.","h2":"In Ohio, after 12 months with a probationary license, a teen may not drive from 1 a.m. to 5 a.m. unless a parent or guardian is along.","p":"Right. After a year the limit is 1 a.m. to 5 a.m."},"es":{"q":"En Ohio, después de 12 meses con licencia probatoria, ¿qué horario sigue restringido sin uno de sus padres o tutor?","o":["De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 1 a.m. a 5 a.m.","Ningún horario"],"h1":"El horario se acorta por los dos lados.","h2":"En Ohio, después de 12 meses con licencia probatoria, un joven no puede manejar de 1 a.m. a 5 a.m. sin su padre, madre o tutor.","p":"Correcto. Después de un año el límite es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Ohio，持试用驾照 12 个月以后，除非父母或监护人在车上，哪些时间仍然有限制？","o":["午夜到早上 6 点","晚上 11 点到早上 5 点","凌晨 1 点到早上 5 点","没有时间限制"],"h1":"限制的时间段两头都变短了。","h2":"在 Ohio，持试用驾照 12 个月以后，青少年从凌晨 1 点到早上 5 点不能开车，除非父母或监护人在车上。","p":"对。一年以后，限制是凌晨 1 点到早上 5 点。"},"vi":{"q":"Ở Ohio, sau khi giữ bằng lái thử thách (probationary license) 12 tháng, những giờ nào vẫn bị hạn chế nếu không có cha mẹ hoặc người giám hộ đi cùng?","o":["Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","1 giờ sáng đến 5 giờ sáng","Không có giờ nào bị hạn chế"],"h1":"Khoảng thời gian ngắn lại ở cả hai đầu.","h2":"Ở Ohio, sau 12 tháng có bằng lái thử thách, thiếu niên không được lái xe từ 1 giờ sáng đến 5 giờ sáng nếu không có cha mẹ hoặc người giám hộ đi cùng.","p":"Đúng. Sau một năm, giới hạn là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Ohio, pagkatapos hawakan ang probationary license nang 12 buwan, aling mga oras ang bawal pa rin kung walang kasamang magulang o guardian?","o":["Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","1 a.m. hanggang 5 a.m.","Walang bawal na oras"],"h1":"Umiikli ang oras sa magkabilang dulo.","h2":"Sa Ohio, pagkatapos ng 12 buwan na may probationary license, hindi puwedeng magmaneho ang teen mula 1 a.m. hanggang 5 a.m. kung walang kasamang magulang o guardian.","p":"Tama. Pagkatapos ng isang taon, ang limit ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Ohio، بعد الاحتفاظ بـالرخصة التجريبية (probationary license) لمدة 12 شهرًا، ما الساعات التي تبقى ممنوعة إلا إذا كان معه أحد الوالدين أو الوصي؟","o":["من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 1 صباحًا إلى 5 صباحًا","لا توجد ساعات ممنوعة"],"h1":"تصبح الفترة أقصر من البداية والنهاية.","h2":"في Ohio، بعد 12 شهرًا مع الرخصة التجريبية، لا يجوز للمراهق القيادة من 1 صباحًا إلى 5 صباحًا إلا إذا كان معه أحد الوالدين أو الوصي.","p":"صحيح. بعد سنة يصبح المنع من 1 صباحًا إلى 5 صباحًا."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-010","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what must a probationary driver carry to drive to or from work during restricted night hours?","o":["Written documentation from the employer","A pay stub from last year","A note from a friend","Nothing; work is always allowed"],"h1":"It is a paper from the job.","h2":"In Ohio a probationary driver going to or from work during restricted hours must have written documentation from the employer with them.","p":"Right. Carry the paper from your employer."},"es":{"q":"En Ohio, ¿qué debe llevar un conductor con licencia probatoria para ir o volver del trabajo en el horario nocturno restringido?","o":["Un documento escrito del empleador","Un recibo de pago del año pasado","Una nota de un amigo","Nada; ir al trabajo siempre está permitido"],"h1":"Es un papel del trabajo.","h2":"En Ohio un conductor con licencia probatoria que va o vuelve del trabajo en el horario restringido debe llevar consigo un documento escrito del empleador.","p":"Correcto. Lleve el documento de su empleador."},"zh":{"q":"在 Ohio，持试用驾照的司机在限制的夜间时间开车上下班，必须带什么？","o":["雇主写的书面证明","去年的工资单","朋友写的字条","什么都不用带，上班一直都可以"],"h1":"它是工作单位给的一张纸。","h2":"在 Ohio，持试用驾照的司机在限制的时间开车上下班，必须随身带着雇主写的书面证明。","p":"对。带上雇主给的证明。"},"vi":{"q":"Ở Ohio, người có bằng lái thử thách phải mang theo gì để lái xe đi làm hoặc đi làm về trong giờ ban đêm bị hạn chế?","o":["Giấy tờ viết tay hoặc in từ chủ lao động","Phiếu lương của năm ngoái","Một tờ giấy từ bạn bè","Không cần gì; đi làm luôn được phép"],"h1":"Đó là một tờ giấy từ nơi làm việc.","h2":"Ở Ohio, người có bằng lái thử thách lái xe đi làm hoặc đi làm về trong giờ bị hạn chế phải mang theo giấy tờ xác nhận bằng văn bản từ chủ lao động.","p":"Đúng. Mang theo giấy tờ từ chủ lao động của bạn."},"tl":{"q":"Sa Ohio, ano ang dapat dalhin ng probationary driver para magmaneho papunta o pauwi mula sa trabaho sa mga bawal na oras sa gabi?","o":["Nakasulat na dokumento mula sa employer","Pay stub mula noong nakaraang taon","Sulat mula sa isang kaibigan","Wala; laging pinapayagan ang trabaho"],"h1":"Isa itong papel mula sa trabaho.","h2":"Sa Ohio, ang probationary driver na papunta o pauwi mula sa trabaho sa mga bawal na oras ay dapat may dalang nakasulat na dokumento mula sa employer.","p":"Tama. Dalhin ang papel mula sa iyong employer."},"ar":{"q":"في Ohio، ماذا يجب أن يحمل صاحب الرخصة التجريبية ليقود إلى العمل أو منه في ساعات الليل الممنوعة؟","o":["ورقة مكتوبة من صاحب العمل","قسيمة راتب من السنة الماضية","ورقة من صديق","لا شيء؛ العمل مسموح دائمًا"],"h1":"هي ورقة من مكان العمل.","h2":"في Ohio يجب أن يحمل صاحب الرخصة التجريبية الذي يقود إلى العمل أو منه في الساعات الممنوعة ورقة مكتوبة من صاحب العمل.","p":"صحيح. احمل الورقة من صاحب عملك."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-011","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, during the first year with a probationary license, how many passengers who are not family may a teen carry without a parent or guardian?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"In Ohio, during the first year, a probationary driver may carry no more than one passenger who is not a family member, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger in the first year."},"es":{"q":"En Ohio, durante el primer año con licencia probatoria, ¿cuántos pasajeros que no son de la familia puede llevar un joven sin uno de sus padres o tutor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño después del cero.","h2":"En Ohio, durante el primer año, un conductor con licencia probatoria no puede llevar más de un pasajero que no sea de su familia, salvo que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero que no es de la familia el primer año."},"zh":{"q":"在 Ohio，持试用驾照的第一年，没有父母或监护人时，青少年可以载几位不是家人的乘客？","o":["一位也不行","一位","两位","三位"],"h1":"它是大于零的最小数字。","h2":"在 Ohio，第一年里，持试用驾照的司机最多只能载一位不是家人的乘客，除非父母或监护人在车上。","p":"对。第一年只能载一位不是家人的乘客。"},"vi":{"q":"Ở Ohio, trong năm đầu có bằng lái thử thách, thiếu niên được chở bao nhiêu hành khách không phải người trong gia đình khi không có cha mẹ hoặc người giám hộ?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Ohio, trong năm đầu tiên, người có bằng lái thử thách được chở không quá một hành khách không phải người trong gia đình, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Chỉ một hành khách không phải người nhà trong năm đầu."},"tl":{"q":"Sa Ohio, sa unang taon na may probationary license, ilang pasaherong hindi kapamilya ang puwedeng isakay ng teen kung walang magulang o guardian?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Ohio, sa unang taon, hindi puwedeng magsakay ang probationary driver ng higit sa isang pasaherong hindi kapamilya, maliban kung may magulang o guardian sa kotse.","p":"Tama. Isang pasaherong hindi kapamilya lang sa unang taon."},"ar":{"q":"في Ohio، خلال السنة الأولى مع الرخصة التجريبية، كم راكبًا من غير العائلة يمكن للمراهق أن يحمل بدون أحد الوالدين أو الوصي؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من صفر.","h2":"في Ohio، خلال السنة الأولى، لا يجوز لصاحب الرخصة التجريبية أن يحمل أكثر من راكب واحد من غير العائلة، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد فقط من غير العائلة في السنة الأولى."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-012","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, once a permit holder turns 16, who may supervise them while they drive?","o":["Any passenger over 16","Only a driving instructor","A licensed driver who is at least 18","A licensed driver who is at least 21, in the front passenger seat"],"h1":"The helper must be old enough to drink legally, and sit beside you.","h2":"In Ohio a permit holder who is 16 or older may drive with any licensed driver who is at least 21 and sits in the front passenger seat.","p":"Right. A licensed driver 21 or older beside you."},"es":{"q":"En Ohio, cuando quien tiene permiso cumple 16 años, ¿quién puede supervisarle al manejar?","o":["Cualquier pasajero mayor de 16","Solo un instructor de manejo","Un conductor con licencia de por lo menos 18 años","Un conductor con licencia de por lo menos 21 años, en el asiento del pasajero delantero"],"h1":"El acompañante debe tener edad para tomar alcohol legalmente, y sentarse a su lado.","h2":"En Ohio quien tiene permiso y tiene 16 años o más puede manejar con cualquier conductor con licencia de por lo menos 21 años que vaya en el asiento del pasajero delantero.","p":"Correcto. Un conductor con licencia de 21 años o más a su lado."},"zh":{"q":"在 Ohio，学习驾照持有人满 16 岁以后，谁可以在他们开车时监督？","o":["任何 16 岁以上的乘客","只有驾驶教练","至少 18 岁、有驾照的司机","至少 21 岁、有驾照、坐在前排乘客座位的司机"],"h1":"陪同的人必须到了可以合法喝酒的年龄，而且坐在你旁边。","h2":"在 Ohio，16 岁或以上的学习驾照持有人可以和任何至少 21 岁、有驾照、坐在前排乘客座位的司机一起开车。","p":"对。一位 21 岁或以上、有驾照的司机坐在你旁边。"},"vi":{"q":"Ở Ohio, khi người có giấy phép tập lái đủ 16 tuổi, ai có thể giám sát họ khi lái xe?","o":["Bất kỳ hành khách nào trên 16 tuổi","Chỉ giáo viên dạy lái xe","Một người có bằng lái ít nhất 18 tuổi","Một người có bằng lái ít nhất 21 tuổi, ngồi ở ghế hành khách phía trước"],"h1":"Người giúp phải đủ tuổi uống rượu hợp pháp, và ngồi bên cạnh bạn.","h2":"Ở Ohio, người có giấy phép tập lái từ 16 tuổi trở lên có thể lái xe với bất kỳ người có bằng lái nào ít nhất 21 tuổi ngồi ở ghế hành khách phía trước.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên ngồi bên cạnh bạn."},"tl":{"q":"Sa Ohio, kapag nag-16 na ang may hawak ng permit, sino ang puwedeng magbantay sa kanila habang nagmamaneho?","o":["Kahit sinong pasahero na higit 16","Driving instructor lang","Isang lisensyadong driver na hindi bababa sa 18","Isang lisensyadong driver na hindi bababa sa 21, sa front passenger seat"],"h1":"Dapat sapat ang edad ng kasama para legal na uminom ng alak, at umupo sa tabi mo.","h2":"Sa Ohio, ang may hawak ng permit na 16 pataas ay puwedeng magmaneho kasama ang kahit sinong lisensyadong driver na hindi bababa sa 21 at nakaupo sa front passenger seat.","p":"Tama. Isang lisensyadong driver na 21 pataas sa tabi mo."},"ar":{"q":"في Ohio، عندما يبلغ صاحب التصريح 16 سنة، من يمكنه الإشراف عليه أثناء القيادة؟","o":["أي راكب عمره فوق 16 سنة","مدرّب القيادة فقط","سائق مرخّص عمره 18 سنة على الأقل","سائق مرخّص عمره 21 سنة على الأقل، في المقعد الأمامي بجانب السائق"],"h1":"يجب أن يكون المرافق في العمر القانوني لشرب الكحول، وأن يجلس بجانبك.","h2":"في Ohio يمكن لصاحب التصريح الذي عمره 16 سنة أو أكثر أن يقود مع أي سائق مرخّص عمره 21 سنة على الأقل ويجلس في المقعد الأمامي بجانب السائق.","p":"صحيح. سائق مرخّص عمره 21 سنة أو أكثر بجانبك."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-013","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many classroom hours of driver education must a teen complete?","o":["24 hours","8 hours","38 hours","50 hours"],"h1":"It is one full day of hours.","h2":"In Ohio a teen must complete 24 hours of driver education in the classroom, plus 8 hours of driving with an instructor.","p":"Right. 24 classroom hours."},"es":{"q":"En Ohio, ¿cuántas horas de clase de manejo debe completar un joven?","o":["24 horas","8 horas","38 horas","50 horas"],"h1":"Son las horas de un día completo.","h2":"En Ohio un joven debe completar 24 horas de clase de manejo, más 8 horas de manejo con un instructor.","p":"Correcto. 24 horas de clase."},"zh":{"q":"在 Ohio，青少年必须完成多少小时的驾驶教育课堂课？","o":["24 小时","8 小时","38 小时","50 小时"],"h1":"它是一整天的小时数。","h2":"在 Ohio，青少年必须完成 24 小时的驾驶教育课堂课，再加上和教练一起开车 8 小时。","p":"对。课堂课 24 小时。"},"vi":{"q":"Ở Ohio, thiếu niên phải học bao nhiêu giờ lý thuyết lái xe (driver education) trong lớp?","o":["24 giờ","8 giờ","38 giờ","50 giờ"],"h1":"Đó là số giờ của một ngày trọn vẹn.","h2":"Ở Ohio, thiếu niên phải học 24 giờ lý thuyết lái xe trong lớp, cộng thêm 8 giờ lái xe với giáo viên.","p":"Đúng. 24 giờ học trong lớp."},"tl":{"q":"Sa Ohio, ilang oras ng driver education sa classroom ang dapat tapusin ng teen?","o":["24 oras","8 oras","38 oras","50 oras"],"h1":"Ito ang bilang ng oras sa isang buong araw.","h2":"Sa Ohio, dapat tapusin ng teen ang 24 oras ng driver education sa classroom, dagdag ang 8 oras ng pagmamaneho kasama ang instructor.","p":"Tama. 24 oras sa classroom."},"ar":{"q":"في Ohio، كم ساعة من دروس تعليم القيادة (driver education) في الصف يجب أن يكملها المراهق؟","o":["24 ساعة","8 ساعات","38 ساعة","50 ساعة"],"h1":"هي عدد ساعات يوم كامل.","h2":"في Ohio يجب أن يكمل المراهق 24 ساعة من تعليم القيادة في الصف، بالإضافة إلى 8 ساعات من القيادة مع مدرّب.","p":"صحيح. 24 ساعة في الصف."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-014","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many hours of behind-the-wheel training with a driving instructor must a teen complete?","o":["2 hours","24 hours","8 hours","50 hours"],"h1":"It is one third of the classroom hours.","h2":"In Ohio a teen must complete 8 hours of behind-the-wheel training with a driving instructor.","p":"Right. 8 hours with an instructor."},"es":{"q":"En Ohio, ¿cuántas horas de práctica al volante con un instructor de manejo debe completar un joven?","o":["2 horas","24 horas","8 horas","50 horas"],"h1":"Es la tercera parte de las horas de clase.","h2":"En Ohio un joven debe completar 8 horas de práctica al volante con un instructor de manejo.","p":"Correcto. 8 horas con un instructor."},"zh":{"q":"在 Ohio，青少年必须和驾驶教练完成多少小时的实际上路训练？","o":["2 小时","24 小时","8 小时","50 小时"],"h1":"它是课堂课时间的三分之一。","h2":"在 Ohio，青少年必须和驾驶教练完成 8 小时的实际上路训练。","p":"对。和教练开 8 小时。"},"vi":{"q":"Ở Ohio, thiếu niên phải học bao nhiêu giờ lái xe thực hành (behind-the-wheel) với giáo viên dạy lái?","o":["2 giờ","24 giờ","8 giờ","50 giờ"],"h1":"Đó là một phần ba số giờ học trong lớp.","h2":"Ở Ohio, thiếu niên phải học 8 giờ lái xe thực hành với giáo viên dạy lái.","p":"Đúng. 8 giờ với giáo viên."},"tl":{"q":"Sa Ohio, ilang oras ng behind-the-wheel training kasama ang driving instructor ang dapat tapusin ng teen?","o":["2 oras","24 oras","8 oras","50 oras"],"h1":"Isang-katlo ito ng mga oras sa classroom.","h2":"Sa Ohio, dapat tapusin ng teen ang 8 oras ng behind-the-wheel training kasama ang driving instructor.","p":"Tama. 8 oras kasama ang instructor."},"ar":{"q":"في Ohio، كم ساعة من التدريب العملي خلف المقود (behind-the-wheel) مع مدرّب القيادة يجب أن يكملها المراهق؟","o":["2 ساعة","24 ساعة","8 ساعات","50 ساعة"],"h1":"هي ثلث ساعات الصف.","h2":"في Ohio يجب أن يكمل المراهق 8 ساعات من التدريب العملي خلف المقود مع مدرّب القيادة.","p":"صحيح. 8 ساعات مع المدرّب."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-015","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, can police stop a driver only for holding a phone while driving?","o":["No, only if there is another violation","Yes, it is a primary offense","Only on interstates","Only at night"],"h1":"The law changed in April 2023 to make this stronger.","h2":"In Ohio, since April 4, 2023, using a hand-held phone while driving is a primary offense, so police can stop you for that alone.","p":"Right. Holding the phone is enough to be stopped."},"es":{"q":"En Ohio, ¿puede la policía detener a un conductor solo por tener el teléfono en la mano mientras maneja?","o":["No, solo si hay otra infracción","Sí, es una infracción principal","Solo en las autopistas interestatales","Solo de noche"],"h1":"La ley cambió en abril de 2023 para ser más fuerte.","h2":"En Ohio, desde el 4 de abril de 2023, usar el teléfono en la mano al manejar es una infracción principal, y la policía puede detenerle solo por eso.","p":"Correcto. Tener el teléfono en la mano basta para que le detengan."},"zh":{"q":"在 Ohio，警察可以只因为司机开车时拿着手机就让他停车吗？","o":["不可以，只有在有其他违规时才可以","可以，它是主要违规（primary offense）","只在州际公路上可以","只在晚上可以"],"h1":"法律在 2023 年 4 月改得更严了。","h2":"在 Ohio，从 2023 年 4 月 4 日起，开车时用手持手机是主要违规（primary offense），所以警察只因为这一点就可以让你停车。","p":"对。拿着手机就足够被拦下。"},"vi":{"q":"Ở Ohio, cảnh sát có thể chặn xe chỉ vì tài xế cầm điện thoại khi lái không?","o":["Không, chỉ khi có vi phạm khác","Có, đó là vi phạm chính (primary offense)","Chỉ trên đường cao tốc liên tiểu bang","Chỉ vào ban đêm"],"h1":"Luật đã thay đổi vào tháng 4 năm 2023 để nghiêm hơn.","h2":"Ở Ohio, từ ngày 4 tháng 4 năm 2023, cầm điện thoại khi lái xe là vi phạm chính (primary offense), nên cảnh sát có thể chặn xe bạn chỉ vì lý do đó.","p":"Đúng. Chỉ cần cầm điện thoại là có thể bị chặn xe."},"tl":{"q":"Sa Ohio, puwede bang patigilin ng pulis ang driver dahil lang sa paghawak ng phone habang nagmamaneho?","o":["Hindi, kung may iba pang paglabag lang","Oo, ito ay primary offense","Sa mga interstate lang","Sa gabi lang"],"h1":"Nagbago ang batas noong April 2023 para gawin itong mas mahigpit.","h2":"Sa Ohio, mula April 4, 2023, ang paggamit ng hawak na phone habang nagmamaneho ay primary offense, kaya puwede kang patigilin ng pulis dahil lang doon.","p":"Tama. Sapat na ang paghawak ng phone para patigilin ka."},"ar":{"q":"في Ohio، هل يمكن للشرطة إيقاف السائق فقط لأنه يمسك الهاتف أثناء القيادة؟","o":["لا، فقط إذا كانت هناك مخالفة أخرى","نعم، إنها مخالفة أساسية (primary offense)","على الطرق السريعة بين الولايات فقط","في الليل فقط"],"h1":"تغيّر القانون في أبريل 2023 ليصبح أشد.","h2":"في Ohio، منذ 4 أبريل 2023، استخدام الهاتف باليد أثناء القيادة مخالفة أساسية (primary offense)، لذلك يمكن للشرطة إيقافك لهذا السبب وحده.","p":"صحيح. إمساك الهاتف يكفي لإيقافك."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-016","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, how much may an adult driver touch a phone while driving, in most cases?","o":["As much as needed at a red light","Only to send short texts","Not at all, even to answer a call","A single touch or swipe"],"h1":"It is the smallest possible action.","h2":"In Ohio, in most cases, a driver may use only a single touch or swipe on a phone; anything more is against the law.","p":"Right. One touch or swipe at most."},"es":{"q":"En Ohio, en la mayoría de los casos, ¿cuánto puede tocar el teléfono un conductor adulto mientras maneja?","o":["Lo que necesite en un semáforo en rojo","Solo para enviar mensajes cortos","Nada, ni siquiera para contestar una llamada","Un solo toque o deslizamiento"],"h1":"Es la acción más pequeña posible.","h2":"En Ohio, en la mayoría de los casos, un conductor solo puede dar un toque o un deslizamiento en el teléfono; más que eso va contra la ley.","p":"Correcto. Un toque o deslizamiento como máximo."},"zh":{"q":"在 Ohio，大多数情况下，成年司机开车时可以碰手机多少？","o":["红灯时想用多少就用多少","只能发短的短信","完全不能碰，接电话也不行","点一下或划一下"],"h1":"它是最小的动作。","h2":"在 Ohio，大多数情况下，司机只能在手机上点一下或划一下；再多就是违法的。","p":"对。最多点一下或划一下。"},"vi":{"q":"Ở Ohio, trong hầu hết trường hợp, tài xế người lớn được chạm vào điện thoại bao nhiêu khi lái xe?","o":["Bao nhiêu cũng được khi dừng đèn đỏ","Chỉ để gửi tin nhắn ngắn","Hoàn toàn không, kể cả để nghe cuộc gọi","Một lần chạm hoặc vuốt"],"h1":"Đó là hành động nhỏ nhất có thể.","h2":"Ở Ohio, trong hầu hết trường hợp, tài xế chỉ được chạm hoặc vuốt điện thoại một lần; làm nhiều hơn là phạm luật.","p":"Đúng. Nhiều nhất là một lần chạm hoặc vuốt."},"tl":{"q":"Sa Ohio, gaano kadalas puwedeng hawakan ng adultong driver ang phone habang nagmamaneho, sa karamihan ng kaso?","o":["Kahit gaano karami kapag naka-red light","Para lang magpadala ng maikling text","Hindi talaga, kahit para sumagot ng tawag","Isang touch o swipe"],"h1":"Ito ang pinakamaliit na posibleng galaw.","h2":"Sa Ohio, sa karamihan ng kaso, isang touch o swipe lang sa phone ang puwede sa driver; labag sa batas ang higit doon.","p":"Tama. Isang touch o swipe lang ang pinakamarami."},"ar":{"q":"في Ohio، إلى أي حد يجوز للسائق البالغ أن يلمس الهاتف أثناء القيادة، في معظم الحالات؟","o":["بقدر ما يحتاج عند الإشارة الحمراء","فقط لإرسال رسائل قصيرة","لا يجوز أبدًا، حتى للرد على مكالمة","لمسة واحدة أو سحبة واحدة"],"h1":"هو أصغر فعل ممكن.","h2":"في Ohio، في معظم الحالات، يجوز للسائق لمسة واحدة أو سحبة واحدة فقط على الهاتف؛ وأي شيء أكثر من ذلك مخالف للقانون.","p":"صحيح. لمسة أو سحبة واحدة على الأكثر."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-017","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the penalty for a first hand-held phone offense?","o":["Up to a $150 fine and 2 points, or a distracted driving course instead","A $25 fine","Loss of the license for one year","Only a warning, always"],"h1":"There is a choice between paying and learning.","h2":"In Ohio a first hand-held phone offense brings 2 points and a fine of up to $150, but a distracted driving course can let you avoid the fine and points.","p":"Right. Up to $150 and 2 points, or a distracted driving course."},"es":{"q":"En Ohio, ¿cuál es la sanción por la primera vez que se usa el teléfono en la mano al manejar?","o":["Una multa de hasta $150 y 2 puntos, o un curso sobre manejo distraído en su lugar","Una multa de $25","Perder la licencia por un año","Siempre solo una advertencia"],"h1":"Hay que elegir entre pagar o aprender.","h2":"En Ohio la primera infracción por usar el teléfono en la mano trae 2 puntos y una multa de hasta $150, pero un curso sobre manejo distraído le permite evitar la multa y los puntos.","p":"Correcto. Hasta $150 y 2 puntos, o un curso sobre manejo distraído."},"zh":{"q":"在 Ohio，第一次因为手持手机被抓，处罚是什么？","o":["最高罚款 $150 并扣 2 分，或者改上分心驾驶课程","罚款 $25","吊销驾照一年","只会警告，一直都是"],"h1":"可以在付钱和学习之间选择。","h2":"在 Ohio，第一次因为手持手机被抓，扣 2 分并罚款最高 $150，但上分心驾驶课程可以让你不用罚款和扣分。","p":"对。最高 $150 并扣 2 分，或者上分心驾驶课程。"},"vi":{"q":"Ở Ohio, hình phạt cho lần đầu vi phạm cầm điện thoại khi lái xe là gì?","o":["Phạt tối đa $150 và 2 điểm, hoặc học khóa lái xe mất tập trung (distracted driving course) thay thế","Phạt $25","Mất bằng lái một năm","Luôn luôn chỉ bị cảnh cáo"],"h1":"Bạn được chọn giữa trả tiền và đi học.","h2":"Ở Ohio, lần đầu vi phạm cầm điện thoại bị 2 điểm và phạt tối đa $150, nhưng học một khóa về lái xe mất tập trung có thể giúp bạn tránh tiền phạt và điểm.","p":"Đúng. Tối đa $150 và 2 điểm, hoặc học khóa lái xe mất tập trung."},"tl":{"q":"Sa Ohio, ano ang parusa sa unang paglabag sa paghawak ng phone?","o":["Multang hanggang $150 at 2 points, o isang distracted driving course bilang kapalit","Multang $25","Pagkawala ng lisensya nang isang taon","Babala lang, palagi"],"h1":"May pagpipilian sa pagitan ng pagbabayad at pag-aaral.","h2":"Sa Ohio, ang unang paglabag sa paghawak ng phone ay may 2 points at multang hanggang $150, pero ang isang distracted driving course ay puwedeng magligtas sa iyo sa multa at points.","p":"Tama. Hanggang $150 at 2 points, o isang distracted driving course."},"ar":{"q":"في Ohio، ما عقوبة المخالفة الأولى لاستخدام الهاتف باليد؟","o":["غرامة حتى $150 و2 نقاط، أو دورة عن القيادة المشتّتة (distracted driving course) بدلًا منها","غرامة $25","سحب الرخصة لمدة سنة","تحذير فقط، دائمًا"],"h1":"هناك اختيار بين الدفع والتعلّم.","h2":"في Ohio تؤدي المخالفة الأولى لاستخدام الهاتف باليد إلى 2 نقاط وغرامة حتى $150، لكن دورة عن القيادة المشتّتة قد تعفيك من الغرامة والنقاط.","p":"صحيح. حتى $150 و2 نقاط، أو دورة عن القيادة المشتّتة."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-018","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, which stopped vehicles with warning lights on must you move over for?","o":["Only police cars","Only ambulances and fire trucks","Police, emergency, tow, road crew and garbage trucks","Only tow trucks"],"h1":"The law covers more than police and fire. Think of road workers too.","h2":"In Ohio you must move one lane away from stopped police and emergency vehicles, tow trucks, road maintenance trucks and garbage trucks with warning lights on, or slow down if you cannot move over safely.","p":"Right. Emergency, tow, road crew and garbage trucks all count."},"es":{"q":"En Ohio, ¿ante qué vehículos detenidos con luces de advertencia encendidas debe cambiarse de carril?","o":["Solo patrullas de policía","Solo ambulancias y camiones de bomberos","Policía, emergencias, grúas, equipos de carreteras y camiones de basura","Solo grúas"],"h1":"La ley cubre más que la policía y los bomberos. Piense también en los trabajadores de carreteras.","h2":"En Ohio usted debe alejarse un carril de los vehículos de policía y emergencias, grúas, camiones de mantenimiento de carreteras y camiones de basura que estén detenidos con luces de advertencia, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Emergencias, grúas, equipos de carreteras y camiones de basura cuentan."},"zh":{"q":"在 Ohio，你必须为哪些停着、开着警示灯的车让道变道（move over）？","o":["只有警车","只有救护车和消防车","警车、紧急车辆、拖车、道路工程车和垃圾车","只有拖车"],"h1":"这条法律不只包括警察和消防。也想想道路工人。","h2":"在 Ohio，遇到停着、开着警示灯的警车、紧急车辆、拖车、道路维修车和垃圾车，你必须换到离它们远一条的车道，如果不能安全换道，就要减速。","p":"对。紧急车辆、拖车、道路工程车和垃圾车都算。"},"vi":{"q":"Ở Ohio, bạn phải chuyển làn tránh xa những xe đang dừng có bật đèn cảnh báo nào?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương và xe cứu hỏa","Xe cảnh sát, xe cấp cứu, xe kéo, xe sửa đường và xe rác","Chỉ xe kéo"],"h1":"Luật áp dụng cho nhiều xe hơn cảnh sát và cứu hỏa. Hãy nghĩ cả đến công nhân làm đường.","h2":"Ở Ohio, bạn phải chuyển sang cách một làn với xe cảnh sát và xe cấp cứu, xe kéo, xe bảo trì đường và xe rác đang dừng có bật đèn cảnh báo, hoặc chạy chậm lại nếu không thể chuyển làn an toàn.","p":"Đúng. Xe cấp cứu, xe kéo, xe sửa đường và xe rác đều tính."},"tl":{"q":"Sa Ohio, aling mga nakahintong sasakyan na may nakabukas na warning lights ang dapat mong lipatan ng lane?","o":["Mga police car lang","Mga ambulansya at fire truck lang","Police, emergency, tow, road crew at garbage truck","Mga tow truck lang"],"h1":"Mas marami ang saklaw ng batas kaysa pulis at bumbero. Isipin din ang mga trabahador sa kalsada.","h2":"Sa Ohio, dapat kang lumipat ng isang lane palayo sa mga nakahintong police at emergency vehicle, tow truck, road maintenance truck at garbage truck na may nakabukas na warning lights, o bumagal kung hindi ka ligtas na makakalipat.","p":"Tama. Kasama ang emergency, tow, road crew at garbage truck."},"ar":{"q":"في Ohio، ما المركبات المتوقفة التي أضواء التحذير فيها مضاءة ويجب أن تبتعد عنها بتغيير المسار؟","o":["سيارات الشرطة فقط","سيارات الإسعاف والإطفاء فقط","الشرطة والطوارئ وشاحنات السحب وعمال الطرق وشاحنات القمامة","شاحنات السحب فقط"],"h1":"القانون يشمل أكثر من الشرطة والإطفاء. فكّر في عمال الطرق أيضًا.","h2":"في Ohio يجب أن تنتقل مسارًا واحدًا بعيدًا عن سيارات الشرطة والطوارئ وشاحنات السحب وشاحنات صيانة الطرق وشاحنات القمامة المتوقفة وأضواء التحذير فيها مضاءة، أو أن تخفف السرعة إذا لم تستطع تغيير المسار بأمان.","p":"صحيح. الطوارئ وشاحنات السحب وعمال الطرق وشاحنات القمامة كلها مشمولة."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-019","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, on a road with four or more lanes, who must stop for a school bus loading or unloading students?","o":["All traffic in both directions","Only traffic moving in the same direction as the bus","Only traffic coming toward the bus","No one"],"h1":"On a wide road, the bus lets students out only on the side where they live.","h2":"In Ohio, on a road with four or more lanes, only traffic moving in the same direction as the school bus must stop.","p":"Right. Only the same direction stops on four or more lanes."},"es":{"q":"En Ohio, en una carretera de cuatro carriles o más, ¿quién debe detenerse ante un autobús escolar que sube o baja estudiantes?","o":["Todo el tráfico en los dos sentidos","Solo el tráfico que va en el mismo sentido que el autobús","Solo el tráfico que viene hacia el autobús","Nadie"],"h1":"En una carretera ancha, el autobús deja a los estudiantes solo del lado donde viven.","h2":"En Ohio, en una carretera de cuatro carriles o más, solo el tráfico que va en el mismo sentido que el autobús escolar debe detenerse.","p":"Correcto. En cuatro carriles o más, solo se detiene el mismo sentido."},"zh":{"q":"在 Ohio，在四条或更多车道的路上，校车上下学生时，谁必须停车？","o":["两个方向的所有车","只有和校车同方向的车","只有朝校车开过来的车","谁都不用"],"h1":"在宽的路上，校车只在学生住的那一边让他们下车。","h2":"在 Ohio，在四条或更多车道的路上，只有和校车同方向的车必须停车。","p":"对。四条或更多车道时，只有同方向的车停。"},"vi":{"q":"Ở Ohio, trên đường có bốn làn trở lên, ai phải dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống?","o":["Tất cả xe cộ ở cả hai chiều","Chỉ xe chạy cùng chiều với xe buýt","Chỉ xe chạy ngược chiều về phía xe buýt","Không ai cả"],"h1":"Trên đường rộng, xe buýt chỉ cho học sinh xuống ở phía nhà của các em.","h2":"Ở Ohio, trên đường có bốn làn trở lên, chỉ xe chạy cùng chiều với xe buýt trường học phải dừng lại.","p":"Đúng. Trên đường bốn làn trở lên, chỉ xe cùng chiều phải dừng."},"tl":{"q":"Sa Ohio, sa kalsadang may apat o higit pang lane, sino ang dapat huminto para sa school bus na nagsasakay o nagbababa ng mga estudyante?","o":["Lahat ng sasakyan sa dalawang direksyon","Ang mga sasakyan lang na papunta sa parehong direksyon ng bus","Ang mga sasakyan lang na papalapit sa bus","Wala"],"h1":"Sa malawak na kalsada, nagbababa lang ang bus ng estudyante sa gilid kung saan sila nakatira.","h2":"Sa Ohio, sa kalsadang may apat o higit pang lane, ang mga sasakyan lang na papunta sa parehong direksyon ng school bus ang dapat huminto.","p":"Tama. Ang parehong direksyon lang ang humihinto sa apat o higit pang lane."},"ar":{"q":"في Ohio، على طريق فيه أربعة مسارات أو أكثر، من يجب أن يتوقف لحافلة مدرسية تُركب الطلاب أو تُنزلهم؟","o":["كل السيارات في الاتجاهين","فقط السيارات التي تسير في نفس اتجاه الحافلة","فقط السيارات القادمة نحو الحافلة","لا أحد"],"h1":"على الطريق العريض، تُنزل الحافلة الطلاب فقط في الجهة التي يسكنون فيها.","h2":"في Ohio، على طريق فيه أربعة مسارات أو أكثر، فقط السيارات التي تسير في نفس اتجاه الحافلة المدرسية يجب أن تتوقف.","p":"صحيح. على أربعة مسارات أو أكثر، يتوقف فقط من يسير في نفس الاتجاه."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-020","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what is the legal blood alcohol limit for a driver under 21?","o":["0.08 percent","0.10 percent","0.04 percent","0.02 percent"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Ohio a driver under 21 breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. For drivers under 21 the limit is 0.02."},"es":{"q":"En Ohio, ¿cuál es el límite legal de alcohol en la sangre para un conductor menor de 21?","o":["0.08 por ciento","0.10 por ciento","0.04 por ciento","0.02 por ciento"],"h1":"Es mucho más bajo que el límite de 0.08 para adultos.","h2":"En Ohio un conductor menor de 21 viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más.","p":"Correcto. Para menores de 21 el límite es 0.02."},"zh":{"q":"在 Ohio，未满 21 岁的司机法定血液酒精浓度上限是多少？","o":["0.08%","0.10%","0.04%","0.02%"],"h1":"它比成年人的上限 0.08 低很多。","h2":"在 Ohio，未满 21 岁的司机血液酒精浓度在 0.02% 或以上就违法。","p":"对。未满 21 岁的司机上限是 0.02。"},"vi":{"q":"Ở Ohio, giới hạn nồng độ cồn trong máu hợp pháp cho tài xế dưới 21 tuổi là bao nhiêu?","o":["0.08 phần trăm","0.10 phần trăm","0.04 phần trăm","0.02 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn là 0.08.","h2":"Ở Ohio, tài xế dưới 21 tuổi phạm luật khi có nồng độ cồn trong máu từ 0.02 phần trăm trở lên.","p":"Đúng. Với tài xế dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Ohio, ano ang legal na limit ng alcohol sa dugo para sa driver na wala pang 21?","o":["0.08 percent","0.10 percent","0.04 percent","0.02 percent"],"h1":"Mas mababa ito nang malaki kaysa sa limit ng adulto na 0.08.","h2":"Sa Ohio, lumalabag sa batas ang driver na wala pang 21 kapag 0.02 percent o higit pa ang alcohol sa kanyang dugo.","p":"Tama. Para sa mga driver na wala pang 21, ang limit ay 0.02."},"ar":{"q":"في Ohio، ما الحد القانوني لنسبة الكحول في الدم للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة","0.10 بالمئة","0.04 بالمئة","0.02 بالمئة"],"h1":"هو أقل بكثير من حد البالغين وهو 0.08.","h2":"في Ohio يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. للسائقين تحت 21 سنة الحد هو 0.02."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-021","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how many points within two years lead to a license suspension?","o":["6 points","12 or more points","8 points","10 points"],"h1":"At 6 points you only get a warning letter.","h2":"In Ohio, a driver who gets 12 or more points within two years has the license suspended by the BMV.","p":"Right. 12 points in two years means a suspension."},"es":{"q":"En Ohio, ¿cuántos puntos en dos años llevan a la suspensión de la licencia?","o":["6 puntos","12 puntos o más","8 puntos","10 puntos"],"h1":"Con 6 puntos solo recibe una carta de advertencia.","h2":"En Ohio, al conductor que acumula 12 puntos o más en dos años, el BMV le suspende la licencia.","p":"Correcto. 12 puntos en dos años significan una suspensión."},"zh":{"q":"在 Ohio，两年内累计多少分会导致驾照被暂停？","o":["6 分","12 分或以上","8 分","10 分"],"h1":"到 6 分时你只会收到一封警告信。","h2":"在 Ohio，两年内累计 12 分或以上的司机，驾照会被 BMV 暂停。","p":"对。两年内 12 分就会被暂停驾照。"},"vi":{"q":"Ở Ohio, bao nhiêu điểm trong vòng hai năm sẽ dẫn đến đình chỉ bằng lái?","o":["6 điểm","Từ 12 điểm trở lên","8 điểm","10 điểm"],"h1":"Khi bị 6 điểm, bạn chỉ nhận một lá thư cảnh cáo.","h2":"Ở Ohio, tài xế bị từ 12 điểm trở lên trong vòng hai năm sẽ bị BMV đình chỉ bằng lái.","p":"Đúng. 12 điểm trong hai năm nghĩa là bị đình chỉ bằng lái."},"tl":{"q":"Sa Ohio, ilang point sa loob ng dalawang taon ang humahantong sa suspensyon ng lisensya?","o":["6 na point","12 o higit pang point","8 point","10 point"],"h1":"Sa 6 na point, warning letter lang ang matatanggap mo.","h2":"Sa Ohio, ang driver na makakuha ng 12 o higit pang point sa loob ng dalawang taon ay sinususpindehan ng lisensya ng BMV.","p":"Tama. Ang 12 point sa dalawang taon ay nangangahulugang suspensyon."},"ar":{"q":"في Ohio، كم نقطة خلال سنتين تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط","12 نقطة أو أكثر","8 نقاط","10 نقاط"],"h1":"عند 6 نقاط تحصل فقط على رسالة تحذير.","h2":"في Ohio، السائق الذي يحصل على 12 نقطة أو أكثر خلال سنتين يوقف الـ BMV رخصته.","p":"صحيح. 12 نقطة في سنتين تعني إيقاف الرخصة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-022","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what is the minimum liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"The first and last numbers are the same, and the middle one is twice as big.","h2":"In Ohio, the minimum liability insurance is $25,000 for one person hurt, $50,000 for two or more people hurt, and $25,000 for property damage.","p":"Right. $25,000, $50,000 and $25,000."},"es":{"q":"En Ohio, ¿cuál es el seguro mínimo de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"El primer número y el último son iguales, y el del medio es el doble.","h2":"En Ohio, el seguro mínimo de responsabilidad civil es de $25,000 por una persona herida, $50,000 por dos o más personas heridas y $25,000 por daños a la propiedad.","p":"Correcto. $25,000, $50,000 y $25,000."},"zh":{"q":"在 Ohio，司机最低必须买多少责任保险？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"第一个和最后一个数字一样，中间的数字是它们的两倍。","h2":"在 Ohio，最低责任保险是：一人受伤 $25,000，两人或更多人受伤 $50,000，财产损失 $25,000。","p":"对。$25,000、$50,000 和 $25,000。"},"vi":{"q":"Ở Ohio, người lái xe phải có bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"Số đầu và số cuối giống nhau, số ở giữa lớn gấp đôi.","h2":"Ở Ohio, bảo hiểm trách nhiệm tối thiểu là $25,000 khi một người bị thương, $50,000 khi hai người trở lên bị thương, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000, $50,000 và $25,000."},"tl":{"q":"Sa Ohio, ano ang pinakamababang liability insurance na dapat mayroon ang drayber?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"Pareho ang una at huling numero, at doble ang nasa gitna.","h2":"Sa Ohio, ang pinakamababang liability insurance ay $25,000 para sa isang taong nasaktan, $50,000 para sa dalawa o higit pang taong nasaktan, at $25,000 para sa sira sa ari-arian.","p":"Tama. $25,000, $50,000 at $25,000."},"ar":{"q":"في Ohio، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يملكه السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $50,000","$25,000 / $50,000 / $25,000"],"h1":"الرقم الأول والأخير متساويان، والرقم الأوسط ضعفهما.","h2":"في Ohio، الحد الأدنى من تأمين المسؤولية هو $25,000 لإصابة شخص واحد، و$50,000 لإصابة شخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 و$50,000 و$25,000."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-023","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what happens the first time a driver refuses a chemical test for alcohol after an arrest?","o":["A one-year license suspension","Only a warning","A 30-day license suspension","A fine, but no suspension"],"h1":"Refusing is treated more harshly than failing the test the first time.","h2":"In Ohio, refusing a chemical test for the first time brings a one-year license suspension that starts right away, even if the driver is later found not guilty.","p":"Right. A first refusal means a one-year suspension."},"es":{"q":"En Ohio, ¿qué pasa la primera vez que un conductor arrestado se niega a una prueba química de alcohol?","o":["Una suspensión de la licencia por un año","Solo una advertencia","Una suspensión de la licencia por 30 días","Una multa, pero sin suspensión"],"h1":"Negarse se castiga más que no pasar la prueba la primera vez.","h2":"En Ohio, negarse por primera vez a una prueba química trae una suspensión de la licencia por un año que empieza de inmediato, aunque después declaren inocente al conductor.","p":"Correcto. La primera negativa significa un año de suspensión."},"zh":{"q":"在 Ohio，司机被逮捕后第一次拒绝做酒精化学检测，会怎么样？","o":["暂停驾照一年","只有警告","暂停驾照 30 天","罚款，但不暂停驾照"],"h1":"第一次拒绝检测，处罚比检测没通过更重。","h2":"在 Ohio，第一次拒绝化学检测会被马上暂停驾照一年，即使司机后来被判无罪也一样。","p":"对。第一次拒绝就会被暂停驾照一年。"},"vi":{"q":"Ở Ohio, điều gì xảy ra khi người lái xe lần đầu từ chối xét nghiệm hóa học về rượu sau khi bị bắt?","o":["Bị đình chỉ bằng lái một năm","Chỉ bị cảnh cáo","Bị đình chỉ bằng lái 30 ngày","Bị phạt tiền, nhưng không bị đình chỉ"],"h1":"Lần đầu từ chối bị xử nặng hơn là xét nghiệm không đạt.","h2":"Ở Ohio, lần đầu từ chối xét nghiệm hóa học sẽ bị đình chỉ bằng lái một năm ngay lập tức, kể cả khi sau đó người lái xe được tuyên vô tội.","p":"Đúng. Lần đầu từ chối nghĩa là bị đình chỉ bằng lái một năm."},"tl":{"q":"Sa Ohio, ano ang mangyayari sa unang beses na tumanggi ang drayber sa chemical test para sa alak matapos maaresto?","o":["Isang taong suspensyon ng lisensya","Babala lang","30 araw na suspensyon ng lisensya","Multa, pero walang suspensyon"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa pagbagsak sa test sa unang beses.","h2":"Sa Ohio, ang unang pagtanggi sa chemical test ay may isang taong suspensyon ng lisensya na nagsisimula agad, kahit mapatunayang hindi nagkasala ang drayber sa huli.","p":"Tama. Ang unang pagtanggi ay nangangahulugan ng isang taong suspensyon."},"ar":{"q":"في Ohio، ماذا يحدث أول مرة يرفض فيها السائق الفحص الكيميائي للكحول بعد القبض عليه؟","o":["إيقاف الرخصة لمدة سنة","تحذير فقط","إيقاف الرخصة لمدة 30 يومًا","غرامة، لكن بدون إيقاف"],"h1":"الرفض في المرة الأولى عقوبته أشد من الرسوب في الفحص.","h2":"في Ohio، رفض الفحص الكيميائي أول مرة يؤدي إلى إيقاف الرخصة لمدة سنة يبدأ فورًا، حتى لو ثبتت براءة السائق لاحقًا.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة لمدة سنة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-024","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what happens to a driver under 18 who is convicted of two moving violations?","o":["A warning letter only","A one-year license suspension","A three-month license suspension","Nothing, until 12 points"],"h1":"For teens, the BMV acts quickly. Two violations bring a short suspension.","h2":"In Ohio, a driver under 18 who is convicted of two moving violations gets an automatic three-month license suspension.","p":"Right. Two moving violations mean three months without a license."},"es":{"q":"En Ohio, ¿qué le pasa a un conductor menor de 18 años condenado por dos infracciones de tránsito en movimiento?","o":["Solo una carta de advertencia","Una suspensión de la licencia por un año","Una suspensión de la licencia por tres meses","Nada, hasta llegar a 12 puntos"],"h1":"Con los adolescentes, el BMV actúa rápido. Dos infracciones traen una suspensión corta.","h2":"En Ohio, un conductor menor de 18 años condenado por dos infracciones en movimiento recibe una suspensión automática de la licencia por tres meses.","p":"Correcto. Dos infracciones significan tres meses sin licencia."},"zh":{"q":"在 Ohio，未满 18 岁的司机如果有两次行车违规定罪，会怎么样？","o":["只收到警告信","暂停驾照一年","暂停驾照三个月","到 12 分之前都没事"],"h1":"对青少年，BMV 处理得很快。两次违规就会被短期暂停驾照。","h2":"在 Ohio，未满 18 岁的司机如果有两次行车违规定罪，会被自动暂停驾照三个月。","p":"对。两次行车违规就是三个月没有驾照。"},"vi":{"q":"Ở Ohio, điều gì xảy ra với người lái xe dưới 18 tuổi bị kết tội hai lần vi phạm khi lái xe?","o":["Chỉ nhận thư cảnh cáo","Bị đình chỉ bằng lái một năm","Bị đình chỉ bằng lái ba tháng","Không sao, cho đến khi bị 12 điểm"],"h1":"Với thanh thiếu niên, BMV xử lý rất nhanh. Hai lần vi phạm sẽ bị đình chỉ một thời gian ngắn.","h2":"Ở Ohio, người lái xe dưới 18 tuổi bị kết tội hai lần vi phạm khi lái xe sẽ tự động bị đình chỉ bằng lái ba tháng.","p":"Đúng. Hai lần vi phạm khi lái xe nghĩa là ba tháng không có bằng lái."},"tl":{"q":"Sa Ohio, ano ang mangyayari sa drayber na wala pang 18 na nahatulan sa dalawang moving violation?","o":["Sulat ng babala lang","Isang taong suspensyon ng lisensya","Tatlong buwang suspensyon ng lisensya","Wala, hanggang umabot sa 12 puntos"],"h1":"Sa mga kabataan, mabilis kumilos ang BMV. Ang dalawang paglabag ay may maikling suspensyon.","h2":"Sa Ohio, ang drayber na wala pang 18 na nahatulan sa dalawang moving violation ay awtomatikong masususpinde ang lisensya nang tatlong buwan.","p":"Tama. Ang dalawang moving violation ay nangangahulugan ng tatlong buwang walang lisensya."},"ar":{"q":"في Ohio، ماذا يحدث للسائق تحت 18 سنة إذا أُدين بمخالفتين أثناء القيادة؟","o":["رسالة تحذير فقط","إيقاف الرخصة لمدة سنة","إيقاف الرخصة لمدة ثلاثة أشهر","لا شيء، حتى يصل إلى 12 نقطة"],"h1":"مع المراهقين تتصرف إدارة BMV بسرعة. مخالفتان تعنيان إيقافًا قصيرًا.","h2":"في Ohio، السائق تحت 18 سنة الذي يُدان بمخالفتين أثناء القيادة تُوقف رخصته تلقائيًا لمدة ثلاثة أشهر.","p":"صحيح. مخالفتان أثناء القيادة تعنيان ثلاثة أشهر بدون رخصة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-025","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a child is 6 years old and 4 feet tall. How must the child ride in a car?","o":["With only a seat belt","In a booster seat","In a rear-facing infant seat","On an adult's lap"],"h1":"Children from 4 up to 8 years old need extra height unless they are already 4 feet 9 inches tall.","h2":"In Ohio, a child at least 4 but under 8 years old must ride in a booster seat unless the child is 4 feet 9 inches tall or taller.","p":"Right. This child needs a booster seat."},"es":{"q":"En Ohio, un niño tiene 6 años y mide 4 pies. ¿Cómo debe viajar en el carro?","o":["Solo con el cinturón de seguridad","En un asiento elevado (booster)","En un asiento para bebé mirando hacia atrás","En las piernas de un adulto"],"h1":"Los niños de 4 a 8 años necesitan más altura, a menos que ya midan 4 pies 9 pulgadas.","h2":"En Ohio, un niño de al menos 4 años pero menor de 8 debe viajar en un asiento elevado (booster), a menos que mida 4 pies 9 pulgadas o más.","p":"Correcto. Este niño necesita un asiento elevado."},"zh":{"q":"在 Ohio，一个孩子 6 岁，身高 4 英尺。这个孩子坐车时必须怎么坐？","o":["只系安全带","坐增高座椅（booster seat）","坐后向婴儿座椅","坐在大人腿上"],"h1":"4 岁到 8 岁的孩子需要垫高，除非已经有 4 英尺 9 英寸高。","h2":"在 Ohio，至少 4 岁但未满 8 岁的孩子必须坐增高座椅，除非孩子身高达到 4 英尺 9 英寸或更高。","p":"对。这个孩子需要坐增高座椅。"},"vi":{"q":"Ở Ohio, một em bé 6 tuổi và cao 4 feet. Em bé phải ngồi trong xe như thế nào?","o":["Chỉ cần thắt dây an toàn","Ngồi ghế nâng (booster seat)","Ngồi ghế trẻ sơ sinh quay về phía sau","Ngồi trong lòng người lớn"],"h1":"Trẻ từ 4 đến 8 tuổi cần được ngồi cao hơn, trừ khi đã cao 4 feet 9 inch.","h2":"Ở Ohio, trẻ từ 4 tuổi nhưng chưa đủ 8 tuổi phải ngồi ghế nâng, trừ khi trẻ cao từ 4 feet 9 inch trở lên.","p":"Đúng. Em bé này cần ngồi ghế nâng."},"tl":{"q":"Sa Ohio, may batang 6 na taong gulang at 4 na talampakan ang taas. Paano dapat sumakay ang bata sa kotse?","o":["Seat belt lang","Sa booster seat","Sa rear-facing na upuan ng sanggol","Sa kandungan ng matanda"],"h1":"Ang mga batang 4 hanggang 8 taong gulang ay kailangang iupo nang mas mataas, maliban kung 4 na talampakan at 9 na pulgada na ang taas nila.","h2":"Sa Ohio, ang batang hindi bababa sa 4 pero wala pang 8 taong gulang ay dapat nasa booster seat, maliban kung 4 na talampakan at 9 na pulgada o higit pa ang taas ng bata.","p":"Tama. Kailangan ng batang ito ng booster seat."},"ar":{"q":"في Ohio، طفل عمره 6 سنوات وطوله 4 أقدام. كيف يجب أن يجلس الطفل في السيارة؟","o":["بحزام الأمان فقط","في مقعد رافع (booster seat)","في مقعد رضيع موجّه للخلف","في حضن شخص بالغ"],"h1":"الأطفال من 4 إلى 8 سنوات يحتاجون إلى رفع إضافي، إلا إذا كان طولهم 4 أقدام و9 بوصات.","h2":"في Ohio، الطفل الذي عمره 4 سنوات على الأقل وأقل من 8 سنوات يجب أن يجلس في مقعد رافع، إلا إذا كان طوله 4 أقدام و9 بوصات أو أكثر.","p":"صحيح. هذا الطفل يحتاج إلى مقعد رافع."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-026","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, when must your headlights be on during the day?","o":["Only on the highway","Only inside tunnels","Never during the day","When your wipers are on because of rain or snow"],"h1":"Think about what you turn on when it starts to rain.","h2":"In Ohio, your headlights must be on whenever your windshield wipers are in use because of rain, snow or other weather, and also when it is hard to see.","p":"Right. Wipers on for rain or snow means headlights on."},"es":{"q":"En Ohio, ¿cuándo deben estar encendidas sus luces delanteras durante el día?","o":["Solo en la autopista","Solo dentro de los túneles","Nunca durante el día","Cuando usa los limpiaparabrisas por lluvia o nieve"],"h1":"Piense en lo que enciende cuando empieza a llover.","h2":"En Ohio, las luces delanteras deben estar encendidas siempre que use los limpiaparabrisas por lluvia, nieve u otro mal tiempo, y también cuando se ve poco.","p":"Correcto. Limpiaparabrisas por lluvia o nieve significa luces encendidas."},"zh":{"q":"在 Ohio，白天什么时候必须开大灯？","o":["只在高速公路上","只在隧道里","白天从来不用","因为下雨或下雪而开雨刷时"],"h1":"想一想，开始下雨时你会打开什么。","h2":"在 Ohio，只要因为下雨、下雪或其他天气而使用雨刷，就必须开大灯；看不清楚的时候也必须开。","p":"对。下雨或下雪开雨刷，就要开大灯。"},"vi":{"q":"Ở Ohio, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ trên xa lộ","Chỉ trong đường hầm","Không bao giờ vào ban ngày","Khi bạn bật cần gạt nước vì mưa hoặc tuyết"],"h1":"Hãy nghĩ xem bạn bật cái gì khi trời bắt đầu mưa.","h2":"Ở Ohio, bạn phải bật đèn pha mỗi khi dùng cần gạt nước vì mưa, tuyết hoặc thời tiết khác, và cả khi khó nhìn thấy.","p":"Đúng. Bật cần gạt nước vì mưa hoặc tuyết thì phải bật đèn pha."},"tl":{"q":"Sa Ohio, kailan dapat nakabukas ang headlights mo sa araw?","o":["Sa highway lang","Sa loob ng tunnel lang","Hindi kailanman sa araw","Kapag nakabukas ang wipers mo dahil sa ulan o niyebe"],"h1":"Isipin kung ano ang binubuksan mo kapag nagsimulang umulan.","h2":"Sa Ohio, dapat nakabukas ang headlights mo tuwing ginagamit ang windshield wipers dahil sa ulan, niyebe o ibang panahon, at pati kapag mahirap makakita.","p":"Tama. Kapag bukas ang wipers dahil sa ulan o niyebe, bukas din ang headlights."},"ar":{"q":"في Ohio، متى يجب تشغيل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع فقط","داخل الأنفاق فقط","أبدًا أثناء النهار","عندما تشغّل المسّاحات بسبب المطر أو الثلج"],"h1":"فكّر فيما تشغّله عندما يبدأ المطر.","h2":"في Ohio، يجب تشغيل المصابيح الأمامية كلما استخدمت مسّاحات الزجاج بسبب المطر أو الثلج أو أي طقس آخر، وأيضًا عندما تكون الرؤية صعبة.","p":"صحيح. المسّاحات تعمل بسبب المطر أو الثلج تعني أن المصابيح الأمامية تعمل."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-027","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, when are studded tires legal?","o":["From November 1 through April 15","All year","Only in January and February","Never"],"h1":"They are allowed only during the cold months, from late fall to mid-spring.","h2":"In Ohio, you may use studded tires only from November 1 to April 15.","p":"Right. November 1 through April 15."},"es":{"q":"En Ohio, ¿cuándo son legales las llantas con clavos?","o":["Del 1 de noviembre al 15 de abril","Todo el año","Solo en enero y febrero","Nunca"],"h1":"Se permiten solo en los meses fríos, desde fines del otoño hasta mediados de la primavera.","h2":"En Ohio, usted puede usar llantas con clavos solo del 1 de noviembre al 15 de abril.","p":"Correcto. Del 1 de noviembre al 15 de abril."},"zh":{"q":"在 Ohio，什么时候可以合法使用钉胎（studded tires）？","o":["从 11 月 1 日到 4 月 15 日","全年","只在 1 月和 2 月","永远不可以"],"h1":"只在寒冷的月份可以用，从深秋到春天中期。","h2":"在 Ohio，你只能在 11 月 1 日到 4 月 15 日之间使用钉胎。","p":"对。从 11 月 1 日到 4 月 15 日。"},"vi":{"q":"Ở Ohio, khi nào lốp xe có đinh (studded tires) là hợp pháp?","o":["Từ ngày 1 tháng 11 đến ngày 15 tháng 4","Cả năm","Chỉ trong tháng 1 và tháng 2","Không bao giờ"],"h1":"Chỉ được phép trong những tháng lạnh, từ cuối mùa thu đến giữa mùa xuân.","h2":"Ở Ohio, bạn chỉ được dùng lốp xe có đinh từ ngày 1 tháng 11 đến ngày 15 tháng 4.","p":"Đúng. Từ ngày 1 tháng 11 đến ngày 15 tháng 4."},"tl":{"q":"Sa Ohio, kailan legal ang studded tires?","o":["Mula Nobyembre 1 hanggang Abril 15","Buong taon","Sa Enero at Pebrero lang","Hindi kailanman"],"h1":"Pinapayagan lang ang mga ito sa malalamig na buwan, mula huling bahagi ng taglagas hanggang kalagitnaan ng tagsibol.","h2":"Sa Ohio, puwede kang gumamit ng studded tires mula Nobyembre 1 hanggang Abril 15 lang.","p":"Tama. Mula Nobyembre 1 hanggang Abril 15."},"ar":{"q":"في Ohio، متى تكون إطارات المسامير (studded tires) قانونية؟","o":["من 1 نوفمبر حتى 15 أبريل","طوال السنة","في يناير وفبراير فقط","أبدًا"],"h1":"مسموح بها فقط في الأشهر الباردة، من أواخر الخريف إلى منتصف الربيع.","h2":"في Ohio، يمكنك استعمال إطارات المسامير فقط من 1 نوفمبر إلى 15 أبريل.","p":"صحيح. من 1 نوفمبر حتى 15 أبريل."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-028","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is less than the 15 feet many other states use.","h2":"In Ohio you may not stop, park or stand a vehicle within 10 feet of a fire hydrant.","p":"Right. In Ohio, stay at least 10 feet from a fire hydrant."},"es":{"q":"En Ohio, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es menos que los 15 pies que usan muchos otros estados.","h2":"En Ohio usted no puede detenerse, estacionarse ni quedarse parado con un vehículo a menos de 10 pies de un hidrante de incendios.","p":"Correcto. En Ohio, quédese por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Ohio，你可以把车停在离消防栓多近的地方？","o":["不少于 5 英尺","不少于 10 英尺","不少于 25 英尺","不少于 50 英尺"],"h1":"它比很多其他州规定的 15 英尺要少。","h2":"在 Ohio，你不可以在离消防栓 10 英尺以内停车、泊车或停留。","p":"对。在 Ohio，要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Ohio, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"Khoảng cách này ít hơn 15 feet mà nhiều tiểu bang khác dùng.","h2":"Ở Ohio, bạn không được dừng, đậu hoặc để xe đứng trong vòng 10 feet cách trụ nước cứu hỏa.","p":"Đúng. Ở Ohio, hãy cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Ohio, gaano kalapit sa fire hydrant ang puwede mong pagparadahan?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mas maikli ito sa 15 talampakan na ginagamit ng maraming ibang estado.","h2":"Sa Ohio, hindi ka puwedeng huminto, pumarada o magpatigil ng sasakyan sa loob ng 10 talampakan mula sa fire hydrant.","p":"Tama. Sa Ohio, lumayo nang hindi bababa sa 10 talampakan mula sa fire hydrant."},"ar":{"q":"في Ohio، ما أقرب مسافة يمكنك أن توقف فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي أقل من 15 قدمًا التي تستخدمها ولايات كثيرة أخرى.","h2":"في Ohio لا يجوز لك أن تتوقف أو تركن أو تترك سيارتك واقفة على بُعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. في Ohio ابقَ على بُعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-029","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what is the minimum following distance the driver manual tells you to keep behind the car ahead?","o":["Half a second","One second","Two seconds","Four seconds"],"h1":"Count \"one-thousand-one\" and keep going past three.","h2":"The Ohio driver manual says to stay at least four seconds behind the vehicle ahead, or one car length for every 10 mph.","p":"Right. Keep at least four seconds between you and the car ahead."},"es":{"q":"En Ohio, ¿cuál es la distancia mínima que el manual del conductor le pide mantener detrás del carro de adelante?","o":["Medio segundo","Un segundo","Dos segundos","Cuatro segundos"],"h1":"Cuente \"mil uno\" y siga más allá de tres.","h2":"El manual del conductor de Ohio dice que se mantenga por lo menos cuatro segundos detrás del vehículo de adelante, o el largo de un carro por cada 10 mph.","p":"Correcto. Mantenga por lo menos cuatro segundos entre usted y el carro de adelante."},"zh":{"q":"在 Ohio，驾驶手册要求你和前车至少保持多长的跟车距离？","o":["半秒","1 秒","2 秒","4 秒"],"h1":"数 “one-thousand-one”，数过 3 之后继续数。","h2":"Ohio 驾驶手册说，要和前车保持至少 4 秒的距离，或者每 10 mph 保持一个车身的长度。","p":"对。和前车之间至少保持 4 秒。"},"vi":{"q":"Ở Ohio, sổ tay lái xe bảo bạn giữ khoảng cách tối thiểu bao nhiêu với xe phía trước?","o":["Nửa giây","Một giây","Hai giây","Bốn giây"],"h1":"Đếm \"one-thousand-one\" và tiếp tục đếm qua số ba.","h2":"Sổ tay lái xe của Ohio nói phải ở cách xe phía trước ít nhất bốn giây, hoặc một thân xe cho mỗi 10 mph.","p":"Đúng. Hãy giữ ít nhất bốn giây giữa bạn và xe phía trước."},"tl":{"q":"Sa Ohio, ano ang pinakamaikling pagitan na sinasabi ng driver manual na panatilihin mo sa likod ng sasakyan sa unahan?","o":["Kalahating segundo","Isang segundo","Dalawang segundo","Apat na segundo"],"h1":"Magbilang ng \"one-thousand-one\" at ituloy lampas sa tatlo.","h2":"Sinasabi ng Ohio driver manual na manatili nang hindi bababa sa apat na segundo sa likod ng sasakyan sa unahan, o isang haba ng kotse sa bawat 10 mph.","p":"Tama. Panatilihin ang hindi bababa sa apat na segundo sa pagitan mo at ng kotse sa unahan."},"ar":{"q":"في Ohio، ما أقل مسافة يطلب منك دليل السائق أن تتركها خلف السيارة التي أمامك؟","o":["نصف ثانية","ثانية واحدة","ثانيتان","أربع ثوانٍ"],"h1":"عُدّ \"one-thousand-one\" واستمر في العدّ بعد الثلاثة.","h2":"يقول دليل السائق في Ohio أن تبقى خلف السيارة التي أمامك بأربع ثوانٍ على الأقل، أو بطول سيارة واحدة لكل 10 mph.","p":"صحيح. اترك أربع ثوانٍ على الأقل بينك وبين السيارة التي أمامك."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-030","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, how much space should you keep between your car and a bicycle?","o":["At least 6 inches","At least 1 foot","At least 3 feet","At least 20 feet"],"h1":"It is about the length of a yardstick.","h2":"In Ohio you should keep a safety zone of at least three feet between your car and a bicycle.","p":"Right. Give a bicycle at least three feet of space."},"es":{"q":"En Ohio, ¿cuánto espacio debe dejar entre su carro y una bicicleta?","o":["Por lo menos 6 pulgadas","Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 20 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Ohio usted debe mantener una zona de seguridad de por lo menos tres pies entre su carro y una bicicleta.","p":"Correcto. Deje por lo menos tres pies de espacio a una bicicleta."},"zh":{"q":"在 Ohio，你的车和自行车之间应该保持多大的空间？","o":["至少 6 英寸","至少 1 英尺","至少 3 英尺","至少 20 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Ohio，你的车和自行车之间应该保持至少 3 英尺的安全距离。","p":"对。给自行车至少 3 英尺的空间。"},"vi":{"q":"Ở Ohio, bạn nên giữ khoảng cách bao nhiêu giữa xe của bạn và xe đạp?","o":["Ít nhất 6 inch","Ít nhất 1 foot","Ít nhất 3 feet","Ít nhất 20 feet"],"h1":"Khoảng bằng chiều dài một cây thước yard.","h2":"Ở Ohio, bạn nên giữ một vùng an toàn ít nhất ba feet giữa xe của bạn và xe đạp.","p":"Đúng. Hãy chừa cho xe đạp ít nhất ba feet."},"tl":{"q":"Sa Ohio, gaano kalaking espasyo ang dapat mong panatilihin sa pagitan ng kotse mo at ng bisikleta?","o":["Hindi bababa sa 6 na pulgada","Hindi bababa sa 1 talampakan","Hindi bababa sa 3 talampakan","Hindi bababa sa 20 talampakan"],"h1":"Halos kasinghaba ito ng isang yardstick.","h2":"Sa Ohio, dapat kang magpanatili ng safety zone na hindi bababa sa tatlong talampakan sa pagitan ng kotse mo at ng bisikleta.","p":"Tama. Bigyan ang bisikleta ng hindi bababa sa tatlong talampakan na espasyo."},"ar":{"q":"في Ohio، ما المسافة التي يجب أن تتركها بين سيارتك والدراجة الهوائية؟","o":["6 بوصات على الأقل","قدم واحدة على الأقل","3 أقدام على الأقل","20 قدمًا على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Ohio يجب أن تترك منطقة أمان لا تقل عن ثلاثة أقدام بين سيارتك والدراجة الهوائية.","p":"صحيح. اترك للدراجة الهوائية مسافة ثلاثة أقدام على الأقل."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-031","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, after you pass the vision screening and knowledge test, how long do you have to buy your temporary instruction permit?","o":["60 days","7 days","1 year","2 years"],"h1":"It is about two months.","h2":"In Ohio you must buy your temporary instruction permit within 60 days of passing the tests, or you have to take the vision screening and knowledge test again.","p":"Right. Buy the permit within 60 days, or you start over."},"es":{"q":"En Ohio, después de pasar el examen de la vista y el examen de conocimientos, ¿cuánto tiempo tiene para comprar su permiso temporal de instrucción?","o":["60 días","7 días","1 año","2 años"],"h1":"Son más o menos dos meses.","h2":"En Ohio usted debe comprar su permiso temporal de instrucción dentro de los 60 días después de pasar los exámenes, o tendrá que tomar de nuevo el examen de la vista y el de conocimientos.","p":"Correcto. Compre el permiso dentro de 60 días o tendrá que empezar de nuevo."},"zh":{"q":"在 Ohio，通过视力检查和知识考试后，你有多长时间去购买临时学习驾照？","o":["60 天","7 天","1 年","2 年"],"h1":"大约是两个月。","h2":"在 Ohio，你必须在通过考试后 60 天内购买临时学习驾照，否则要重新参加视力检查和知识考试。","p":"对。在 60 天内购买学习驾照，否则要从头再来。"},"vi":{"q":"Ở Ohio, sau khi bạn đậu bài kiểm tra thị lực và bài thi kiến thức, bạn có bao lâu để mua giấy phép tập lái tạm thời?","o":["60 ngày","7 ngày","1 năm","2 năm"],"h1":"Khoảng hai tháng.","h2":"Ở Ohio, bạn phải mua giấy phép tập lái tạm thời trong vòng 60 ngày sau khi đậu các bài thi, nếu không bạn phải thi lại bài kiểm tra thị lực và bài thi kiến thức.","p":"Đúng. Hãy mua giấy phép trong vòng 60 ngày, nếu không bạn phải bắt đầu lại."},"tl":{"q":"Sa Ohio, pagkatapos mong pumasa sa vision screening at knowledge test, gaano katagal ang mayroon ka para bilhin ang temporary instruction permit mo?","o":["60 araw","7 araw","1 taon","2 taon"],"h1":"Mga dalawang buwan ito.","h2":"Sa Ohio, dapat mong bilhin ang temporary instruction permit mo sa loob ng 60 araw mula nang pumasa ka sa mga test, o kailangan mong kumuha ulit ng vision screening at knowledge test.","p":"Tama. Bilhin ang permit sa loob ng 60 araw, o magsisimula ka ulit."},"ar":{"q":"في Ohio، بعد أن تنجح في فحص النظر واختبار المعرفة، كم لديك من الوقت لشراء تصريح التعلّم المؤقت؟","o":["60 يومًا","7 أيام","سنة واحدة","سنتان"],"h1":"هي تقريبًا شهران.","h2":"في Ohio يجب أن تشتري تصريح التعلّم المؤقت خلال 60 يومًا من نجاحك في الاختبارات، وإلا يجب أن تعيد فحص النظر واختبار المعرفة.","p":"صحيح. اشترِ التصريح خلال 60 يومًا، وإلا تبدأ من جديد."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-032","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a driver who is 21 or older fails the driving test. What must they usually do before the second try?","o":["Wait one year","Take a short adult driver training course","Retake the knowledge test","Nothing; they may test again the next day"],"h1":"Ohio wants adults who fail to get some extra training first.","h2":"In Ohio, a driver 21 or older who fails the driving test must take an Abbreviated Adult Driver Training Course before testing again, unless they finished an approved driver education course within the past year.","p":"Right. Adults who fail take a short training course first."},"es":{"q":"En Ohio, un conductor de 21 años o más no pasa el examen de manejo. ¿Qué debe hacer normalmente antes del segundo intento?","o":["Esperar un año","Tomar un curso corto de manejo para adultos","Repetir el examen de conocimientos","Nada; puede volver a intentarlo al día siguiente"],"h1":"Ohio quiere que los adultos que no pasan reciban un poco más de entrenamiento primero.","h2":"En Ohio, un conductor de 21 años o más que no pasa el examen de manejo debe tomar un curso abreviado de manejo para adultos antes de volver a intentarlo, a menos que haya terminado un curso aprobado de educación vial en el último año.","p":"Correcto. Los adultos que no pasan toman primero un curso corto."},"zh":{"q":"在 Ohio，21 岁或以上的司机路考没通过。第二次考试之前，他们通常必须做什么？","o":["等一年","上一个简短的成人驾驶训练课程","重新考知识考试","什么都不用做；第二天就可以再考"],"h1":"Ohio 希望没考过的成年人先多接受一些训练。","h2":"在 Ohio，21 岁或以上路考没通过的司机，必须先上简短的成人驾驶训练课程（Abbreviated Adult Driver Training Course）才能再考，除非他们在过去一年内上完了认可的驾驶教育课程。","p":"对。没考过的成年人要先上一个简短的训练课程。"},"vi":{"q":"Ở Ohio, một tài xế từ 21 tuổi trở lên thi lái xe không đậu. Thường thì họ phải làm gì trước lần thi thứ hai?","o":["Chờ một năm","Học một khóa huấn luyện lái xe ngắn cho người lớn","Thi lại bài thi kiến thức","Không cần làm gì; họ có thể thi lại ngày hôm sau"],"h1":"Ohio muốn người lớn thi rớt được huấn luyện thêm trước.","h2":"Ở Ohio, tài xế từ 21 tuổi trở lên thi lái xe không đậu phải học khóa huấn luyện lái xe rút gọn cho người lớn (Abbreviated Adult Driver Training Course) trước khi thi lại, trừ khi họ đã học xong một khóa giáo dục lái xe được chấp thuận trong vòng một năm qua.","p":"Đúng. Người lớn thi rớt phải học một khóa huấn luyện ngắn trước."},"tl":{"q":"Sa Ohio, bumagsak sa driving test ang isang driver na 21 pataas. Ano ang karaniwang dapat niyang gawin bago ang pangalawang subok?","o":["Maghintay ng isang taon","Kumuha ng maikling adult driver training course","Kumuha ulit ng knowledge test","Wala; puwede siyang mag-test ulit kinabukasan"],"h1":"Gusto ng Ohio na kumuha muna ng dagdag na training ang mga adult na bumagsak.","h2":"Sa Ohio, ang driver na 21 pataas na bumagsak sa driving test ay dapat kumuha ng Abbreviated Adult Driver Training Course bago mag-test ulit, maliban kung natapos niya ang isang aprubadong driver education course sa nakaraang isang taon.","p":"Tama. Kumukuha muna ng maikling training course ang mga adult na bumagsak."},"ar":{"q":"في Ohio، سائق عمره 21 سنة أو أكثر رسب في اختبار القيادة. ماذا يجب عليه عادةً أن يفعل قبل المحاولة الثانية؟","o":["أن ينتظر سنة واحدة","أن يأخذ دورة قصيرة لتدريب البالغين على القيادة","أن يعيد اختبار المعرفة","لا شيء؛ يمكنه أن يختبر مرة أخرى في اليوم التالي"],"h1":"تريد Ohio أن يحصل البالغون الذين رسبوا على تدريب إضافي أولًا.","h2":"في Ohio، السائق الذي عمره 21 سنة أو أكثر ورسب في اختبار القيادة يجب أن يأخذ دورة مختصرة لتدريب البالغين على القيادة (Abbreviated Adult Driver Training Course) قبل أن يختبر مرة أخرى، إلا إذا أنهى دورة معتمدة لتعليم القيادة خلال السنة الماضية.","p":"صحيح. البالغون الذين يرسبون يأخذون دورة تدريب قصيرة أولًا."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-033","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a driver takes a chemical test after an arrest and the result is 0.08 or higher, for the first time. How long is the license suspended right away?","o":["One week","30 days","90 days","Five years"],"h1":"It is shorter than the suspension for refusing the test.","h2":"In Ohio, a first chemical test over the legal limit brings an administrative license suspension of three months, or 90 days.","p":"Right. A first test over the limit means a 90-day suspension."},"es":{"q":"En Ohio, un conductor arrestado se hace una prueba química y el resultado es 0.08 o más, por primera vez. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["Una semana","30 días","90 días","Cinco años"],"h1":"Es menos que la suspensión por negarse a la prueba.","h2":"En Ohio, la primera prueba química por encima del límite legal trae una suspensión administrativa de la licencia por tres meses, es decir, 90 días.","p":"Correcto. La primera prueba por encima del límite significa 90 días de suspensión."},"zh":{"q":"在 Ohio，司机被逮捕后做了化学检测，结果是 0.08 或更高，而且是第一次。驾照会马上被暂停多久？","o":["一周","30 天","90 天","五年"],"h1":"它比拒绝检测的暂停时间短。","h2":"在 Ohio，第一次化学检测超过法定上限，会被行政暂停驾照三个月，也就是 90 天。","p":"对。第一次检测超标，驾照暂停 90 天。"},"vi":{"q":"Ở Ohio, một tài xế làm xét nghiệm hóa học sau khi bị bắt và kết quả là 0.08 trở lên, lần đầu tiên. Bằng lái bị đình chỉ ngay trong bao lâu?","o":["Một tuần","30 ngày","90 ngày","Năm năm"],"h1":"Thời gian này ngắn hơn mức đình chỉ khi từ chối xét nghiệm.","h2":"Ở Ohio, lần đầu xét nghiệm hóa học vượt mức giới hạn luật định sẽ bị đình chỉ bằng lái hành chính ba tháng, tức là 90 ngày.","p":"Đúng. Lần đầu xét nghiệm vượt mức nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Ohio, kumuha ng chemical test ang isang driver matapos maaresto at 0.08 o higit pa ang resulta, sa unang pagkakataon. Gaano katagal agad masususpinde ang lisensya?","o":["Isang linggo","30 araw","90 araw","Limang taon"],"h1":"Mas maikli ito kaysa sa suspensyon dahil sa pagtanggi sa test.","h2":"Sa Ohio, ang unang chemical test na lampas sa legal na limitasyon ay may administrative license suspension na tatlong buwan, o 90 araw.","p":"Tama. Ang unang test na lampas sa limit ay may 90 araw na suspensyon."},"ar":{"q":"في Ohio، سائق أجرى فحصًا كيميائيًا بعد القبض عليه وكانت النتيجة 0.08 أو أكثر، لأول مرة. كم مدة إيقاف الرخصة فورًا؟","o":["أسبوع واحد","30 يومًا","90 يومًا","خمس سنوات"],"h1":"هي أقصر من مدة الإيقاف بسبب رفض الفحص.","h2":"في Ohio، أول فحص كيميائي فوق الحد القانوني يؤدي إلى إيقاف إداري للرخصة لمدة ثلاثة أشهر، أي 90 يومًا.","p":"صحيح. أول فحص فوق الحد يعني إيقافًا لمدة 90 يومًا."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-034","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what happens to a driver under 18 who is convicted of three moving violations?","o":["A warning letter","A 30-day license suspension","A three-month license suspension","A one-year license suspension"],"h1":"Two violations bring three months. A third one brings much more.","h2":"In Ohio, a driver under 18 who is convicted of three moving violations gets an automatic one-year license suspension.","p":"Right. Three moving violations mean a year without a license."},"es":{"q":"En Ohio, ¿qué le pasa a un conductor menor de 18 años condenado por tres infracciones de tránsito en movimiento?","o":["Una carta de advertencia","Una suspensión de la licencia por 30 días","Una suspensión de la licencia por tres meses","Una suspensión de la licencia por un año"],"h1":"Dos infracciones traen tres meses. Una tercera trae mucho más.","h2":"En Ohio, un conductor menor de 18 años condenado por tres infracciones en movimiento recibe una suspensión automática de la licencia por un año.","p":"Correcto. Tres infracciones significan un año sin licencia."},"zh":{"q":"在 Ohio，未满 18 岁的司机有三次行车违规定罪，会怎么样？","o":["一封警告信","驾照暂停 30 天","驾照暂停三个月","驾照暂停一年"],"h1":"两次违规是三个月。第三次的处罚重得多。","h2":"在 Ohio，未满 18 岁的司机如果有三次行车违规定罪，会被自动暂停驾照一年。","p":"对。三次行车违规就是一年没有驾照。"},"vi":{"q":"Ở Ohio, điều gì xảy ra với người lái xe dưới 18 tuổi bị kết tội ba lần vi phạm khi lái xe?","o":["Một lá thư cảnh cáo","Đình chỉ bằng lái 30 ngày","Đình chỉ bằng lái ba tháng","Đình chỉ bằng lái một năm"],"h1":"Hai lần vi phạm là ba tháng. Lần thứ ba nặng hơn nhiều.","h2":"Ở Ohio, người lái xe dưới 18 tuổi bị kết tội ba lần vi phạm khi lái xe sẽ tự động bị đình chỉ bằng lái một năm.","p":"Đúng. Ba lần vi phạm khi lái xe nghĩa là một năm không có bằng lái."},"tl":{"q":"Sa Ohio, ano ang mangyayari sa driver na wala pang 18 na nahatulan sa tatlong moving violation?","o":["Isang warning letter","30 araw na suspensyon ng lisensya","Tatlong buwang suspensyon ng lisensya","Isang taong suspensyon ng lisensya"],"h1":"Ang dalawang paglabag ay tatlong buwan. Mas mabigat pa ang pangatlo.","h2":"Sa Ohio, ang driver na wala pang 18 na nahatulan sa tatlong moving violation ay awtomatikong masususpinde ang lisensya nang isang taon.","p":"Tama. Tatlong moving violation ay isang taon na walang lisensya."},"ar":{"q":"في Ohio، ماذا يحدث للسائق تحت 18 سنة الذي يُدان بثلاث مخالفات أثناء القيادة؟","o":["رسالة تحذير","إيقاف الرخصة لمدة 30 يومًا","إيقاف الرخصة لمدة ثلاثة أشهر","إيقاف الرخصة لمدة سنة واحدة"],"h1":"مخالفتان تعنيان ثلاثة أشهر. والمخالفة الثالثة عقوبتها أكبر بكثير.","h2":"في Ohio، السائق تحت 18 سنة الذي يُدان بثلاث مخالفات أثناء القيادة تُوقف رخصته تلقائيًا لمدة سنة واحدة.","p":"صحيح. ثلاث مخالفات أثناء القيادة تعني سنة بلا رخصة."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-035","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what fine can a driver get for driving while the license is suspended?","o":["Up to $1,000","Up to $50","Up to $150","No fine, only a warning"],"h1":"It is a serious crime, a first-degree misdemeanor.","h2":"In Ohio, driving with a suspended license is a first-degree misdemeanor with a fine of up to $1,000, and the license can be suspended for one more year.","p":"Right. Up to $1,000, and maybe another year of suspension."},"es":{"q":"En Ohio, ¿qué multa puede recibir un conductor por manejar con la licencia suspendida?","o":["Hasta $1,000","Hasta $50","Hasta $150","Ninguna multa, solo una advertencia"],"h1":"Es un delito serio, un delito menor de primer grado.","h2":"En Ohio, manejar con la licencia suspendida es un delito menor de primer grado con una multa de hasta $1,000, y la licencia puede quedar suspendida un año más.","p":"Correcto. Hasta $1,000, y tal vez un año más de suspensión."},"zh":{"q":"在 Ohio，驾照被暂停时开车，司机可能被罚多少钱？","o":["最高 $1,000","最高 $50","最高 $150","不罚款，只给警告"],"h1":"这是严重的犯罪，属于一级轻罪。","h2":"在 Ohio，驾照被暂停时开车是一级轻罪，最高罚款 $1,000，而且驾照可能再被暂停一年。","p":"对。最高 $1,000，还可能再暂停一年。"},"vi":{"q":"Ở Ohio, tài xế lái xe khi bằng lái đang bị đình chỉ có thể bị phạt bao nhiêu?","o":["Tối đa $1,000","Tối đa $50","Tối đa $150","Không phạt tiền, chỉ cảnh cáo"],"h1":"Đây là tội nghiêm trọng, một tội nhẹ cấp một.","h2":"Ở Ohio, lái xe khi bằng lái đang bị đình chỉ là tội nhẹ cấp một với tiền phạt tối đa $1,000, và bằng lái có thể bị đình chỉ thêm một năm.","p":"Đúng. Tối đa $1,000, và có thể bị đình chỉ thêm một năm."},"tl":{"q":"Sa Ohio, magkano ang puwedeng multa sa driver na nagmamaneho habang suspendido ang lisensya?","o":["Hanggang $1,000","Hanggang $50","Hanggang $150","Walang multa, warning lang"],"h1":"Seryosong krimen ito, isang first-degree misdemeanor.","h2":"Sa Ohio, ang pagmamaneho nang suspendido ang lisensya ay first-degree misdemeanor na may multang hanggang $1,000, at puwedeng masuspinde ang lisensya nang isa pang taon.","p":"Tama. Hanggang $1,000, at baka isa pang taon ng suspensyon."},"ar":{"q":"في Ohio، ما الغرامة التي قد يحصل عليها السائق إذا قاد ورخصته موقوفة؟","o":["حتى $1,000","حتى $50","حتى $150","لا غرامة، تحذير فقط"],"h1":"هي جريمة خطيرة، جنحة من الدرجة الأولى.","h2":"في Ohio، القيادة برخصة موقوفة جنحة من الدرجة الأولى غرامتها حتى $1,000، ويمكن إيقاف الرخصة سنة أخرى.","p":"صحيح. حتى $1,000، وربما سنة أخرى من الإيقاف."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-036","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, up to what age should children ride in the back seat?","o":["Age 4 and younger","Age 8 and younger","Age 12 and younger","Age 16 and younger"],"h1":"Front air bags can hurt children until they are about to become teenagers.","h2":"In Ohio, children age 12 and younger should ride in the back seat so a front air bag cannot hurt them in a crash.","p":"Right. Age 12 and younger ride in the back."},"es":{"q":"En Ohio, ¿hasta qué edad deben viajar los niños en el asiento trasero?","o":["Hasta los 4 años","Hasta los 8 años","Hasta los 12 años","Hasta los 16 años"],"h1":"Las bolsas de aire delanteras pueden lastimar a los niños hasta casi la adolescencia.","h2":"En Ohio, los niños de 12 años o menos deben viajar en el asiento trasero para que una bolsa de aire delantera no los lastime en un choque.","p":"Correcto. Los niños de 12 años o menos van atrás."},"zh":{"q":"在 Ohio，几岁以下的孩子应该坐在后座？","o":["4 岁及以下","8 岁及以下","12 岁及以下","16 岁及以下"],"h1":"前排安全气囊会伤到孩子，直到他们快成为青少年。","h2":"在 Ohio，12 岁及以下的孩子应该坐在后座，这样车祸时前排安全气囊不会伤到他们。","p":"对。12 岁及以下坐后座。"},"vi":{"q":"Ở Ohio, trẻ em đến bao nhiêu tuổi nên ngồi ở ghế sau?","o":["Từ 4 tuổi trở xuống","Từ 8 tuổi trở xuống","Từ 12 tuổi trở xuống","Từ 16 tuổi trở xuống"],"h1":"Túi khí phía trước có thể làm trẻ bị thương cho đến khi trẻ gần thành thiếu niên.","h2":"Ở Ohio, trẻ em từ 12 tuổi trở xuống nên ngồi ở ghế sau để túi khí phía trước không làm trẻ bị thương khi có tai nạn.","p":"Đúng. Trẻ từ 12 tuổi trở xuống ngồi ở ghế sau."},"tl":{"q":"Sa Ohio, hanggang anong edad dapat nakaupo ang mga bata sa likod na upuan?","o":["Edad 4 pababa","Edad 8 pababa","Edad 12 pababa","Edad 16 pababa"],"h1":"Puwedeng masaktan ng front air bag ang mga bata hanggang malapit na silang maging teenager.","h2":"Sa Ohio, ang mga batang edad 12 pababa ay dapat nakaupo sa likod na upuan para hindi sila masaktan ng front air bag sa isang banggaan.","p":"Tama. Sa likod nakaupo ang edad 12 pababa."},"ar":{"q":"في Ohio، حتى أي عمر يجب أن يجلس الأطفال في المقعد الخلفي؟","o":["4 سنوات وأقل","8 سنوات وأقل","12 سنة وأقل","16 سنة وأقل"],"h1":"الوسائد الهوائية الأمامية قد تؤذي الأطفال حتى يقتربوا من سن المراهقة.","h2":"في Ohio، يجب أن يجلس الأطفال الذين عمرهم 12 سنة وأقل في المقعد الخلفي حتى لا تؤذيهم الوسادة الهوائية الأمامية في حادث.","p":"صحيح. من عمرهم 12 سنة وأقل يجلسون في الخلف."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-037","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a driver under 18 is caught using a phone while driving for the first time. What is the penalty?","o":["Only a warning","A 60-day license suspension and a $150 fine","A $25 fine","Two points, with no suspension"],"h1":"Teens lose the license for about two months.","h2":"In Ohio, a first phone violation by a driver under 18 brings a 60-day license suspension and a $150 fine.","p":"Right. 60 days without a license and a $150 fine."},"es":{"q":"En Ohio, a un conductor menor de 18 años lo detienen por primera vez por usar el teléfono al manejar. ¿Cuál es la sanción?","o":["Solo una advertencia","Una suspensión de la licencia por 60 días y una multa de $150","Una multa de $25","Dos puntos, sin suspensión"],"h1":"Los adolescentes pierden la licencia por unos dos meses.","h2":"En Ohio, la primera infracción por usar el teléfono de un conductor menor de 18 años trae una suspensión de la licencia por 60 días y una multa de $150.","p":"Correcto. 60 días sin licencia y una multa de $150."},"zh":{"q":"在 Ohio，未满 18 岁的司机第一次被抓到开车时用手机。处罚是什么？","o":["只给警告","驾照暂停 60 天，罚款 $150","罚款 $25","扣两分，不暂停驾照"],"h1":"青少年会失去驾照大约两个月。","h2":"在 Ohio，未满 18 岁的司机第一次用手机违规，会被暂停驾照 60 天并罚款 $150。","p":"对。60 天没有驾照，罚款 $150。"},"vi":{"q":"Ở Ohio, một tài xế dưới 18 tuổi bị bắt lần đầu vì dùng điện thoại khi lái xe. Hình phạt là gì?","o":["Chỉ cảnh cáo","Đình chỉ bằng lái 60 ngày và phạt $150","Phạt $25","Hai điểm, không bị đình chỉ"],"h1":"Thiếu niên bị mất bằng lái khoảng hai tháng.","h2":"Ở Ohio, lần đầu vi phạm dùng điện thoại của tài xế dưới 18 tuổi sẽ bị đình chỉ bằng lái 60 ngày và phạt $150.","p":"Đúng. 60 ngày không có bằng lái và phạt $150."},"tl":{"q":"Sa Ohio, nahuli sa unang pagkakataon ang driver na wala pang 18 na gumagamit ng phone habang nagmamaneho. Ano ang parusa?","o":["Warning lang","60 araw na suspensyon ng lisensya at multang $150","Multang $25","Dalawang point, walang suspensyon"],"h1":"Mawawalan ng lisensya ang mga teen nang mga dalawang buwan.","h2":"Sa Ohio, ang unang paglabag sa phone ng driver na wala pang 18 ay may 60 araw na suspensyon ng lisensya at multang $150.","p":"Tama. 60 araw na walang lisensya at multang $150."},"ar":{"q":"في Ohio، ضُبط سائق تحت 18 سنة يستخدم الهاتف أثناء القيادة لأول مرة. ما العقوبة؟","o":["تحذير فقط","إيقاف الرخصة لمدة 60 يومًا وغرامة $150","غرامة $25","نقطتان، بلا إيقاف"],"h1":"يفقد المراهقون الرخصة لمدة شهرين تقريبًا.","h2":"في Ohio، المخالفة الأولى لاستخدام الهاتف من سائق تحت 18 سنة تؤدي إلى إيقاف الرخصة لمدة 60 يومًا وغرامة $150.","p":"صحيح. 60 يومًا بلا رخصة وغرامة $150."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-038","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, what happens to the fine for a hand-held phone offense in a work zone?","o":["It is cut in half","It stays the same","It becomes only a warning","It is doubled"],"h1":"Work zones protect road workers, so the penalty goes up.","h2":"In Ohio, the fine for using a hand-held phone while driving is doubled if it happens in a work zone.","p":"Right. In a work zone, the phone fine is doubled."},"es":{"q":"En Ohio, ¿qué pasa con la multa por usar el teléfono en la mano en una zona de obras?","o":["Se reduce a la mitad","Queda igual","Se convierte solo en una advertencia","Se duplica"],"h1":"Las zonas de obras protegen a los trabajadores, así que la sanción sube.","h2":"En Ohio, la multa por usar el teléfono en la mano al manejar se duplica si ocurre en una zona de obras.","p":"Correcto. En una zona de obras, la multa por el teléfono se duplica."},"zh":{"q":"在 Ohio，在施工区用手持手机违规，罚款会怎么样？","o":["减半","保持不变","变成只有警告","加倍"],"h1":"施工区保护道路工人，所以处罚会提高。","h2":"在 Ohio，开车时用手持手机如果发生在施工区，罚款会加倍。","p":"对。在施工区，手机罚款加倍。"},"vi":{"q":"Ở Ohio, tiền phạt cho lỗi cầm điện thoại trong khu vực công trường thay đổi thế nào?","o":["Giảm một nửa","Giữ nguyên","Chỉ còn là cảnh cáo","Tăng gấp đôi"],"h1":"Khu vực công trường bảo vệ công nhân làm đường, nên hình phạt tăng lên.","h2":"Ở Ohio, tiền phạt cho việc cầm điện thoại khi lái xe sẽ tăng gấp đôi nếu xảy ra trong khu vực công trường.","p":"Đúng. Trong khu vực công trường, tiền phạt điện thoại tăng gấp đôi."},"tl":{"q":"Sa Ohio, ano ang nangyayari sa multa para sa paghawak ng phone sa isang work zone?","o":["Nababawasan ng kalahati","Pareho lang","Nagiging warning lang","Nadodoble"],"h1":"Pinoprotektahan ng work zone ang mga manggagawa sa kalsada, kaya tumataas ang parusa.","h2":"Sa Ohio, nadodoble ang multa sa paggamit ng hawak na phone habang nagmamaneho kapag nangyari ito sa isang work zone.","p":"Tama. Sa work zone, doble ang multa sa phone."},"ar":{"q":"في Ohio، ماذا يحدث لغرامة استخدام الهاتف باليد في منطقة أعمال الطرق؟","o":["تُخفَّض إلى النصف","تبقى كما هي","تصبح تحذيرًا فقط","تُضاعَف"],"h1":"مناطق أعمال الطرق تحمي العمال، لذلك تزيد العقوبة.","h2":"في Ohio، تُضاعَف غرامة استخدام الهاتف باليد أثناء القيادة إذا حدث ذلك في منطقة أعمال الطرق.","p":"صحيح. في منطقة أعمال الطرق تُضاعَف غرامة الهاتف."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-039","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the smallest tread depth a safe tire should have?","o":["One-sixteenth of an inch","One-half of an inch","One inch","Two inches"],"h1":"It is very thin. You can check it with a penny.","h2":"In Ohio, a safe tire must have at least one-sixteenth of an inch of tread depth and no major bumps or bulges.","p":"Right. At least one-sixteenth of an inch of tread."},"es":{"q":"En Ohio, ¿cuál es la profundidad mínima de la banda de rodadura que debe tener una llanta segura?","o":["Un dieciseisavo de pulgada","Media pulgada","Una pulgada","Dos pulgadas"],"h1":"Es muy poca. La puede revisar con una moneda de un centavo.","h2":"En Ohio, una llanta segura debe tener al menos un dieciseisavo de pulgada de profundidad en la banda de rodadura y no tener bultos grandes.","p":"Correcto. Al menos un dieciseisavo de pulgada de banda."},"zh":{"q":"在 Ohio，安全的轮胎最少要有多深的胎纹？","o":["十六分之一英寸","二分之一英寸","一英寸","两英寸"],"h1":"它非常薄。你可以用一分硬币来检查。","h2":"在 Ohio，安全的轮胎必须至少有十六分之一英寸的胎纹深度，而且没有明显的鼓包或凸起。","p":"对。胎纹至少要有十六分之一英寸。"},"vi":{"q":"Ở Ohio, độ sâu gai lốp nhỏ nhất của một lốp xe an toàn là bao nhiêu?","o":["Một phần mười sáu inch","Một nửa inch","Một inch","Hai inch"],"h1":"Nó rất mỏng. Bạn có thể kiểm tra bằng một đồng xu một cent.","h2":"Ở Ohio, một lốp xe an toàn phải có độ sâu gai lốp ít nhất một phần mười sáu inch và không có chỗ phồng hay u lớn.","p":"Đúng. Gai lốp ít nhất một phần mười sáu inch."},"tl":{"q":"Sa Ohio, ano ang pinakamababang lalim ng tread na dapat mayroon ang isang ligtas na gulong?","o":["Isang-labing-anim na bahagi ng pulgada","Kalahating pulgada","Isang pulgada","Dalawang pulgada"],"h1":"Napakanipis nito. Puwede mo itong suriin gamit ang isang penny.","h2":"Sa Ohio, ang ligtas na gulong ay dapat may lalim ng tread na hindi bababa sa isang-labing-anim na bahagi ng pulgada at walang malalaking umbok o bukol.","p":"Tama. Hindi bababa sa isang-labing-anim na bahagi ng pulgada ang tread."},"ar":{"q":"في Ohio، ما أقل عمق لنقشة الإطار (tread) يجب أن يكون في الإطار الآمن؟","o":["جزء من ستة عشر من البوصة","نصف بوصة","بوصة واحدة","بوصتان"],"h1":"هو رقيق جدًا. يمكنك فحصه بقطعة نقود من فئة سنت واحد.","h2":"في Ohio، يجب أن يكون في الإطار الآمن عمق نقشة لا يقل عن جزء من ستة عشر من البوصة، وألّا يكون فيه انتفاخات أو نتوءات كبيرة.","p":"صحيح. عمق النقشة جزء من ستة عشر من البوصة على الأقل."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-040","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a qualified driver who is 30 years old renews the license. What is the longest license they can choose?","o":["2 years","4 years","8 years","12 years"],"h1":"Drivers from 21 up to 65 may choose twice the usual length.","h2":"In Ohio, a qualified driver who is at least 21 but not yet 65 may buy an 8-year license; otherwise the license lasts 4 years.","p":"Right. Drivers 21 to 64 can choose an 8-year license."},"es":{"q":"En Ohio, un conductor que cumple los requisitos y tiene 30 años renueva su licencia. ¿Cuál es la licencia más larga que puede elegir?","o":["2 años","4 años","8 años","12 años"],"h1":"Los conductores de 21 a 65 años pueden elegir el doble del plazo normal.","h2":"En Ohio, un conductor que cumple los requisitos y tiene al menos 21 años pero menos de 65 puede comprar una licencia de 8 años; si no, la licencia dura 4 años.","p":"Correcto. De 21 a 64 años se puede elegir una licencia de 8 años."},"zh":{"q":"在 Ohio，一位符合条件的 30 岁司机更新驾照。他们最长可以选择多久的驾照？","o":["2 年","4 年","8 年","12 年"],"h1":"21 岁到 65 岁的司机可以选择通常期限的两倍。","h2":"在 Ohio，符合条件、至少 21 岁但还不到 65 岁的司机可以买 8 年的驾照；否则驾照的有效期是 4 年。","p":"对。21 到 64 岁的司机可以选择 8 年的驾照。"},"vi":{"q":"Ở Ohio, một tài xế đủ điều kiện 30 tuổi gia hạn bằng lái. Họ có thể chọn bằng lái có thời hạn dài nhất là bao lâu?","o":["2 năm","4 năm","8 năm","12 năm"],"h1":"Tài xế từ 21 đến 65 tuổi có thể chọn thời hạn gấp đôi bình thường.","h2":"Ở Ohio, tài xế đủ điều kiện từ 21 tuổi trở lên nhưng chưa đến 65 tuổi có thể mua bằng lái 8 năm; nếu không thì bằng lái có thời hạn 4 năm.","p":"Đúng. Tài xế từ 21 đến 64 tuổi có thể chọn bằng lái 8 năm."},"tl":{"q":"Sa Ohio, nagre-renew ng lisensya ang isang qualified na driver na 30 taong gulang. Ano ang pinakamahabang lisensya na puwede niyang piliin?","o":["2 taon","4 na taon","8 taon","12 taon"],"h1":"Ang mga driver mula 21 hanggang 65 ay puwedeng pumili ng dobleng karaniwang haba.","h2":"Sa Ohio, ang qualified na driver na hindi bababa sa 21 pero wala pang 65 ay puwedeng bumili ng 8 taong lisensya; kung hindi, 4 na taon ang lisensya.","p":"Tama. Puwedeng pumili ng 8 taong lisensya ang mga driver na 21 hanggang 64."},"ar":{"q":"في Ohio، سائق مؤهَّل عمره 30 سنة يجدّد رخصته. ما أطول مدة رخصة يمكنه أن يختارها؟","o":["2 سنة","4 سنوات","8 سنوات","12 سنة"],"h1":"السائقون من 21 حتى 65 سنة يمكنهم اختيار ضعف المدة المعتادة.","h2":"في Ohio، السائق المؤهَّل الذي عمره 21 سنة على الأقل ولم يبلغ 65 سنة بعد يمكنه شراء رخصة لمدة 8 سنوات؛ وإلا فمدة الرخصة 4 سنوات.","p":"صحيح. السائقون من 21 إلى 64 سنة يمكنهم اختيار رخصة لمدة 8 سنوات."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-041","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a parent co-signs a teen's license application. Until when is the parent also responsible for damage the teen causes while driving?","o":["Only while the teen has a permit","Until the teen turns 18","Until the teen turns 21","For the rest of the teen's life"],"h1":"It ends when the teen becomes an adult.","h2":"In Ohio, a parent or guardian who co-signs a minor's license application shares liability for damage the minor causes while driving until the minor's 18th birthday.","p":"Right. The co-signer is responsible until the teen turns 18."},"es":{"q":"En Ohio, un padre firma como codeudor la solicitud de licencia de su hijo adolescente. ¿Hasta cuándo es el padre también responsable por los daños que cause el joven al manejar?","o":["Solo mientras el joven tiene el permiso","Hasta que el joven cumpla 18 años","Hasta que el joven cumpla 21 años","Por el resto de la vida del joven"],"h1":"Termina cuando el joven llega a la mayoría de edad.","h2":"En Ohio, el padre o tutor que firma la solicitud de licencia de un menor comparte la responsabilidad por los daños que el menor cause al manejar hasta que el menor cumpla 18 años.","p":"Correcto. El codeudor es responsable hasta que el joven cumpla 18 años."},"zh":{"q":"在 Ohio，父母在青少年的驾照申请上共同签名。父母要对青少年开车造成的损害负责到什么时候？","o":["只在青少年持学习驾照期间","直到青少年满 18 岁","直到青少年满 21 岁","青少年的一辈子"],"h1":"青少年成年时就结束了。","h2":"在 Ohio，在未成年人驾照申请上共同签名的父母或监护人，要和未成年人一起对他开车造成的损害负责，直到他满 18 岁。","p":"对。共同签名的人要负责到青少年满 18 岁。"},"vi":{"q":"Ở Ohio, cha mẹ cùng ký đơn xin bằng lái của con tuổi thiếu niên. Cha mẹ cũng phải chịu trách nhiệm về thiệt hại do con gây ra khi lái xe cho đến khi nào?","o":["Chỉ khi con còn giấy phép tập lái","Cho đến khi con đủ 18 tuổi","Cho đến khi con đủ 21 tuổi","Suốt đời của con"],"h1":"Trách nhiệm kết thúc khi con trở thành người lớn.","h2":"Ở Ohio, cha mẹ hoặc người giám hộ cùng ký đơn xin bằng lái của trẻ vị thành niên phải cùng chịu trách nhiệm về thiệt hại trẻ gây ra khi lái xe cho đến sinh nhật 18 tuổi của trẻ.","p":"Đúng. Người cùng ký chịu trách nhiệm cho đến khi con đủ 18 tuổi."},"tl":{"q":"Sa Ohio, pumirma bilang co-signer ang isang magulang sa license application ng teen. Hanggang kailan siya responsable rin sa pinsalang gawa ng teen habang nagmamaneho?","o":["Habang may permit lang ang teen","Hanggang mag-18 ang teen","Hanggang mag-21 ang teen","Habambuhay ng teen"],"h1":"Natatapos ito kapag naging adult na ang teen.","h2":"Sa Ohio, ang magulang o guardian na co-signer sa license application ng isang menor ay kasamang responsable sa pinsalang gawa ng menor habang nagmamaneho hanggang sa ika-18 kaarawan ng menor.","p":"Tama. Responsable ang co-signer hanggang mag-18 ang teen."},"ar":{"q":"في Ohio، أحد الوالدين يوقّع مع المراهق على طلب رخصته. حتى متى يكون الوالد مسؤولًا أيضًا عن الأضرار التي يسبّبها المراهق أثناء القيادة؟","o":["فقط ما دام المراهق يحمل تصريح تعلّم","حتى يبلغ المراهق 18 سنة","حتى يبلغ المراهق 21 سنة","طوال حياة المراهق"],"h1":"تنتهي المسؤولية عندما يصبح المراهق بالغًا.","h2":"في Ohio، الوالد أو الوصي الذي يوقّع على طلب رخصة القاصر يشاركه المسؤولية عن الأضرار التي يسبّبها أثناء القيادة حتى عيد ميلاده الثامن عشر.","p":"صحيح. الموقّع مسؤول حتى يبلغ المراهق 18 سنة."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-042","scope":"OH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Ohio, a school bus is stopped with red lights flashing on a road with fewer than four lanes. How far from the bus must you stop?","o":["At least 10 feet","At least 2 feet","At least 50 feet","At least 100 feet"],"h1":"It is less than the length of one car.","h2":"In Ohio, on a road with fewer than four lanes, traffic from both directions must stop at least 10 feet from the front or back of a stopped school bus.","p":"Right. Stop at least 10 feet from the bus."},"es":{"q":"En Ohio, un autobús escolar está detenido con las luces rojas intermitentes en una carretera de menos de cuatro carriles. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 10 pies","Al menos a 2 pies","Al menos a 50 pies","Al menos a 100 pies"],"h1":"Es menos que el largo de un carro.","h2":"En Ohio, en una carretera de menos de cuatro carriles, el tráfico de los dos sentidos debe detenerse al menos a 10 pies del frente o de la parte de atrás de un autobús escolar detenido.","p":"Correcto. Deténgase al menos a 10 pies del autobús."},"zh":{"q":"在 Ohio，在少于四条车道的路上，一辆校车停着并闪着红灯。你必须在离校车多远的地方停车？","o":["至少 10 英尺","至少 2 英尺","至少 50 英尺","至少 100 英尺"],"h1":"它比一辆车的长度还短。","h2":"在 Ohio，在少于四条车道的路上，两个方向的车都必须在离停着的校车前面或后面至少 10 英尺的地方停车。","p":"对。在离校车至少 10 英尺的地方停车。"},"vi":{"q":"Ở Ohio, một xe buýt trường học đang dừng với đèn đỏ nhấp nháy trên đường có ít hơn bốn làn. Bạn phải dừng cách xe buýt bao xa?","o":["Ít nhất 10 feet","Ít nhất 2 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng cách này ngắn hơn chiều dài một chiếc xe hơi.","h2":"Ở Ohio, trên đường có ít hơn bốn làn, xe từ cả hai chiều phải dừng cách phía trước hoặc phía sau xe buýt trường học đang dừng ít nhất 10 feet.","p":"Đúng. Dừng cách xe buýt ít nhất 10 feet."},"tl":{"q":"Sa Ohio, nakahinto ang isang school bus na kumikislap ang pulang ilaw sa kalsadang may mas kaunti sa apat na lane. Gaano kalayo sa bus ka dapat huminto?","o":["Hindi bababa sa 10 talampakan","Hindi bababa sa 2 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 100 talampakan"],"h1":"Mas maikli ito kaysa sa haba ng isang kotse.","h2":"Sa Ohio, sa kalsadang may mas kaunti sa apat na lane, ang mga sasakyan mula sa dalawang direksyon ay dapat huminto nang hindi bababa sa 10 talampakan mula sa harap o likod ng nakahintong school bus.","p":"Tama. Huminto nang hindi bababa sa 10 talampakan mula sa bus."},"ar":{"q":"في Ohio، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض على طريق فيه أقل من أربعة مسارات. على أي بُعد من الحافلة يجب أن تتوقف؟","o":["10 أقدام على الأقل","2 قدم على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"هي أقل من طول سيارة واحدة.","h2":"في Ohio، على طريق فيه أقل من أربعة مسارات، يجب أن تتوقف السيارات من الاتجاهين على بُعد 10 أقدام على الأقل من مقدمة الحافلة المدرسية المتوقفة أو من مؤخرتها.","p":"صحيح. توقّف على بُعد 10 أقدام على الأقل من الحافلة."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-043","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a driver under 21 fails the driving test. How long must they wait before testing again?","o":["One hour","One week","One month","Two days"],"h1":"It is a very short wait, just a little longer than for the knowledge test.","h2":"In Ohio, a driver under 21 who fails the driving test must wait two days before taking it again.","p":"Right. Wait two days, then try again."},"es":{"q":"En Ohio, un conductor menor de 21 años no pasa el examen de manejo. ¿Cuánto tiempo debe esperar para volver a intentarlo?","o":["Una hora","Una semana","Un mes","Dos días"],"h1":"Es una espera muy corta, solo un poco más que para el examen de conocimientos.","h2":"En Ohio, un conductor menor de 21 años que no pasa el examen de manejo debe esperar dos días para volver a tomarlo.","p":"Correcto. Espere dos días y vuelva a intentarlo."},"zh":{"q":"在 Ohio，未满 21 岁的司机路考没通过。他们必须等多久才能再考？","o":["一小时","一周","一个月","两天"],"h1":"只需要等很短的时间，比知识考试稍微长一点。","h2":"在 Ohio，未满 21 岁、路考没通过的司机必须等两天才能再考。","p":"对。等两天，然后再考。"},"vi":{"q":"Ở Ohio, một tài xế dưới 21 tuổi thi lái xe không đậu. Họ phải chờ bao lâu trước khi thi lại?","o":["Một giờ","Một tuần","Một tháng","Hai ngày"],"h1":"Chỉ chờ rất ngắn, lâu hơn một chút so với bài thi kiến thức.","h2":"Ở Ohio, tài xế dưới 21 tuổi thi lái xe không đậu phải chờ hai ngày trước khi thi lại.","p":"Đúng. Chờ hai ngày, rồi thi lại."},"tl":{"q":"Sa Ohio, bumagsak sa driving test ang isang driver na wala pang 21. Gaano katagal siya dapat maghintay bago mag-test ulit?","o":["Isang oras","Isang linggo","Isang buwan","Dalawang araw"],"h1":"Napakaikling paghihintay lang ito, medyo mas mahaba lang kaysa sa knowledge test.","h2":"Sa Ohio, ang driver na wala pang 21 na bumagsak sa driving test ay dapat maghintay ng dalawang araw bago kumuha ulit nito.","p":"Tama. Maghintay ng dalawang araw, saka subukan ulit."},"ar":{"q":"في Ohio، سائق عمره أقل من 21 سنة رسب في اختبار القيادة. كم يجب أن ينتظر قبل أن يختبر مرة أخرى؟","o":["ساعة واحدة","أسبوع واحد","شهر واحد","يومان"],"h1":"الانتظار قصير جدًا، أطول قليلًا فقط من انتظار اختبار المعرفة.","h2":"في Ohio، السائق الذي عمره أقل من 21 سنة ورسب في اختبار القيادة يجب أن ينتظر يومين قبل أن يعيد الاختبار.","p":"صحيح. انتظر يومين، ثم حاول مرة أخرى."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-044","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, besides at night and in bad weather, when must your headlights be on?","o":["When you cannot see clearly 500 feet ahead","When you cannot see clearly 1,000 feet ahead","When you cannot see clearly 200 feet ahead","When you cannot see clearly 100 feet ahead"],"h1":"The distance is a round number, about the length of three football fields.","h2":"In Ohio, your headlights must be on any time the light is too poor to see things clearly 1,000 feet ahead.","p":"Right. If you cannot see 1,000 feet ahead, turn your headlights on."},"es":{"q":"En Ohio, además de la noche y el mal tiempo, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Cuando no puede ver bien a 500 pies adelante","Cuando no puede ver bien a 1,000 pies adelante","Cuando no puede ver bien a 200 pies adelante","Cuando no puede ver bien a 100 pies adelante"],"h1":"La distancia es un número redondo, como el largo de tres campos de fútbol americano.","h2":"En Ohio, las luces delanteras deben estar encendidas siempre que la luz no permita ver bien las cosas a 1,000 pies adelante.","p":"Correcto. Si no puede ver a 1,000 pies adelante, encienda las luces."},"zh":{"q":"在 Ohio，除了晚上和天气不好的时候，什么时候还必须开大灯？","o":["看不清前方 500 英尺的时候","看不清前方 1,000 英尺的时候","看不清前方 200 英尺的时候","看不清前方 100 英尺的时候"],"h1":"这个距离是一个整数，大约是三个橄榄球场的长度。","h2":"在 Ohio，只要光线太暗、看不清前方 1,000 英尺的东西，就必须开大灯。","p":"对。看不清前方 1,000 英尺，就要开大灯。"},"vi":{"q":"Ở Ohio, ngoài ban đêm và thời tiết xấu, khi nào bạn phải bật đèn pha?","o":["Khi bạn không thể nhìn rõ 500 feet phía trước","Khi bạn không thể nhìn rõ 1,000 feet phía trước","Khi bạn không thể nhìn rõ 200 feet phía trước","Khi bạn không thể nhìn rõ 100 feet phía trước"],"h1":"Khoảng cách là một số tròn, dài khoảng ba sân bóng bầu dục.","h2":"Ở Ohio, bạn phải bật đèn pha bất cứ khi nào ánh sáng quá yếu để nhìn rõ mọi thứ ở 1,000 feet phía trước.","p":"Đúng. Nếu không thể nhìn 1,000 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Ohio, bukod sa gabi at masamang panahon, kailan dapat nakabukas ang headlights mo?","o":["Kapag hindi mo makita nang malinaw ang 500 talampakan sa unahan","Kapag hindi mo makita nang malinaw ang 1,000 talampakan sa unahan","Kapag hindi mo makita nang malinaw ang 200 talampakan sa unahan","Kapag hindi mo makita nang malinaw ang 100 talampakan sa unahan"],"h1":"Bilog na numero ang distansya, mga haba ng tatlong football field.","h2":"Sa Ohio, dapat nakabukas ang headlights mo tuwing masyadong mahina ang liwanag para makita nang malinaw ang mga bagay 1,000 talampakan sa unahan.","p":"Tama. Kung hindi mo makita ang 1,000 talampakan sa unahan, buksan ang headlights."},"ar":{"q":"في Ohio، إلى جانب الليل والطقس السيئ، متى يجب أن تكون مصابيحك الأمامية مضاءة؟","o":["عندما لا ترى بوضوح 500 قدم أمامك","عندما لا ترى بوضوح 1,000 قدم أمامك","عندما لا ترى بوضوح 200 قدم أمامك","عندما لا ترى بوضوح 100 قدم أمامك"],"h1":"المسافة رقم مستدير، بطول ثلاثة ملاعب كرة قدم أمريكية تقريبًا.","h2":"في Ohio، يجب أن تكون مصابيحك الأمامية مضاءة في أي وقت يكون فيه الضوء ضعيفًا جدًا لترى الأشياء بوضوح على بُعد 1,000 قدم أمامك.","p":"صحيح. إذا لم تستطع أن ترى 1,000 قدم أمامك، فشغّل المصابيح الأمامية."},"ref":{"doc":"OH","page":"§7"}},{"id":"oh-045","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, an orange and red triangle is on the back of a farm tractor. What does it tell you?","o":["The vehicle is going less than 45 mph","The vehicle is going less than 35 mph","The vehicle is going less than 25 mph","The vehicle is about to turn left"],"h1":"It is the slow-moving vehicle sign. Think of a speed slower than most town streets.","h2":"In Ohio, the orange and red slow-moving vehicle triangle means the vehicle travels at less than 25 mph.","p":"Right. The triangle means less than 25 mph."},"es":{"q":"En Ohio, un tractor agrícola lleva atrás un triángulo anaranjado y rojo. ¿Qué le indica?","o":["El vehículo va a menos de 45 mph","El vehículo va a menos de 35 mph","El vehículo va a menos de 25 mph","El vehículo está por doblar a la izquierda"],"h1":"Es la señal de vehículo lento. Piense en una velocidad menor que la de la mayoría de las calles del pueblo.","h2":"En Ohio, el triángulo anaranjado y rojo de vehículo lento significa que el vehículo va a menos de 25 mph.","p":"Correcto. El triángulo significa menos de 25 mph."},"zh":{"q":"在 Ohio，农用拖拉机后面有一个橙色和红色的三角形。它告诉你什么？","o":["这辆车的速度低于 45 mph","这辆车的速度低于 35 mph","这辆车的速度低于 25 mph","这辆车马上要左转"],"h1":"这是慢速车辆标志。想一个比大多数城镇街道还慢的速度。","h2":"在 Ohio，橙色和红色的慢速车辆三角形表示这辆车的速度低于 25 mph。","p":"对。这个三角形表示低于 25 mph。"},"vi":{"q":"Ở Ohio, có một hình tam giác màu cam và đỏ ở phía sau một máy kéo nông nghiệp. Nó cho bạn biết điều gì?","o":["Xe đang chạy dưới 45 mph","Xe đang chạy dưới 35 mph","Xe đang chạy dưới 25 mph","Xe sắp rẽ trái"],"h1":"Đó là biển báo xe chạy chậm. Hãy nghĩ đến tốc độ chậm hơn hầu hết các đường phố trong thị trấn.","h2":"Ở Ohio, hình tam giác màu cam và đỏ báo xe chạy chậm có nghĩa là xe đó chạy dưới 25 mph.","p":"Đúng. Hình tam giác có nghĩa là dưới 25 mph."},"tl":{"q":"Sa Ohio, may orange at pulang tatsulok sa likod ng isang farm tractor. Ano ang sinasabi nito sa iyo?","o":["Mas mabagal sa 45 mph ang takbo ng sasakyan","Mas mabagal sa 35 mph ang takbo ng sasakyan","Mas mabagal sa 25 mph ang takbo ng sasakyan","Malapit nang kumaliwa ang sasakyan"],"h1":"Ito ang slow-moving vehicle sign. Isipin ang bilis na mas mabagal pa kaysa sa karamihan ng kalye sa bayan.","h2":"Sa Ohio, ang orange at pulang slow-moving vehicle na tatsulok ay nangangahulugang mas mabagal sa 25 mph ang takbo ng sasakyan.","p":"Tama. Ang tatsulok ay nangangahulugang mas mabagal sa 25 mph."},"ar":{"q":"في Ohio، يوجد مثلث برتقالي وأحمر على مؤخرة جرّار زراعي. ماذا يخبرك؟","o":["المركبة تسير بأقل من 45 mph","المركبة تسير بأقل من 35 mph","المركبة تسير بأقل من 25 mph","المركبة على وشك أن تنعطف يسارًا"],"h1":"هي علامة المركبة البطيئة. فكّر في سرعة أبطأ من معظم شوارع البلدات.","h2":"في Ohio، مثلث المركبة البطيئة البرتقالي والأحمر يعني أن المركبة تسير بأقل من 25 mph.","p":"صحيح. المثلث يعني أقل من 25 mph."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-046","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, when may you cross a solid yellow line to pass a slow-moving vehicle?","o":["When it goes less than half the speed limit, there is clear room, and you stay within the limit","Any time it goes slower than you","Never, for any reason","Only at night"],"h1":"The vehicle must be very slow, and you must still pass safely and legally.","h2":"In Ohio, you may cross a solid yellow line to pass a slow-moving vehicle only if it is going less than half the posted speed limit, the oncoming lane is clear enough, and you do not go over the speed limit.","p":"Right. Less than half the limit, clear room, and no speeding."},"es":{"q":"En Ohio, ¿cuándo puede cruzar una línea amarilla continua para rebasar a un vehículo lento?","o":["Cuando va a menos de la mitad del límite de velocidad, hay espacio libre y usted no pasa el límite","Siempre que vaya más despacio que usted","Nunca, por ninguna razón","Solo de noche"],"h1":"El vehículo debe ir muy despacio, y usted debe rebasar de forma segura y legal.","h2":"En Ohio, usted puede cruzar una línea amarilla continua para rebasar a un vehículo lento solo si este va a menos de la mitad del límite de velocidad, el carril contrario tiene suficiente espacio libre y usted no pasa el límite de velocidad.","p":"Correcto. Menos de la mitad del límite, espacio libre y sin exceso de velocidad."},"zh":{"q":"在 Ohio，什么时候可以越过黄色实线超过慢速车辆？","o":["当它的速度低于限速的一半、前面有足够空间、而且你不超速的时候","只要它比你慢，任何时候都可以","任何情况下都不可以","只在晚上"],"h1":"那辆车必须非常慢，而且你超车时仍然必须安全、合法。","h2":"在 Ohio，只有当慢速车辆的速度低于标示限速的一半、对面车道有足够空间、而且你不超过限速时，你才可以越过黄色实线超过它。","p":"对。低于限速一半、有足够空间、而且不超速。"},"vi":{"q":"Ở Ohio, khi nào bạn được vượt qua vạch vàng liền để vượt một xe chạy chậm?","o":["Khi xe đó chạy dưới một nửa tốc độ giới hạn, có đủ chỗ trống, và bạn không vượt quá giới hạn","Bất cứ khi nào xe đó chạy chậm hơn bạn","Không bao giờ, vì bất cứ lý do gì","Chỉ vào ban đêm"],"h1":"Xe đó phải rất chậm, và bạn vẫn phải vượt một cách an toàn và đúng luật.","h2":"Ở Ohio, bạn chỉ được vượt qua vạch vàng liền để vượt một xe chạy chậm nếu xe đó chạy dưới một nửa tốc độ giới hạn được ghi, làn ngược chiều đủ trống, và bạn không chạy quá tốc độ giới hạn.","p":"Đúng. Dưới một nửa giới hạn, đủ chỗ trống, và không chạy quá tốc độ."},"tl":{"q":"Sa Ohio, kailan ka puwedeng tumawid sa solid na dilaw na linya para lampasan ang isang mabagal na sasakyan?","o":["Kapag mas mabagal ito sa kalahati ng speed limit, may maluwag na espasyo, at hindi ka lalampas sa limit","Anumang oras na mas mabagal ito sa iyo","Hindi kailanman, sa anumang dahilan","Sa gabi lang"],"h1":"Dapat napakabagal ng sasakyan, at dapat ligtas at legal pa rin ang paglampas mo.","h2":"Sa Ohio, puwede kang tumawid sa solid na dilaw na linya para lampasan ang isang mabagal na sasakyan kung mas mabagal lang ito sa kalahati ng nakapaskil na speed limit, sapat na maluwag ang kabilang lane, at hindi ka lalampas sa speed limit.","p":"Tama. Mas mabagal sa kalahati ng limit, maluwag na espasyo, at walang overspeeding."},"ar":{"q":"في Ohio، متى يجوز لك أن تعبر الخط الأصفر المتصل لتتجاوز مركبة بطيئة؟","o":["عندما تسير بأقل من نصف حد السرعة، ويكون الطريق فارغًا بما يكفي، وتبقى أنت ضمن حد السرعة","في أي وقت تسير فيه أبطأ منك","أبدًا، لأي سبب","في الليل فقط"],"h1":"يجب أن تكون المركبة بطيئة جدًا، ويجب أن يكون تجاوزك آمنًا وقانونيًا.","h2":"في Ohio، يجوز لك أن تعبر الخط الأصفر المتصل لتتجاوز مركبة بطيئة فقط إذا كانت تسير بأقل من نصف حد السرعة المكتوب، وكان المسار المقابل فارغًا بما يكفي، ولم تتجاوز أنت حد السرعة.","p":"صحيح. أقل من نصف الحد، وطريق فارغ، وبلا سرعة زائدة."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-047","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a loaded truck is going 55 mph in ideal conditions. About how much distance does it need to stop?","o":["About 50 feet","About 100 feet","About 150 feet","At least 335 feet"],"h1":"It needs more than one and a half times what a car needs.","h2":"The Ohio driver manual says a loaded truck at 55 mph needs at least 335 feet to stop, so never cut in front of one.","p":"Right. At least 335 feet, so do not cut in front of a truck."},"es":{"q":"En Ohio, un camión cargado va a 55 mph en condiciones ideales. ¿Más o menos qué distancia necesita para detenerse?","o":["Unos 50 pies","Unos 100 pies","Unos 150 pies","Al menos 335 pies"],"h1":"Necesita más de una vez y media lo que necesita un carro.","h2":"El manual de manejo de Ohio dice que un camión cargado a 55 mph necesita al menos 335 pies para detenerse, así que nunca se le meta adelante.","p":"Correcto. Al menos 335 pies, así que no se meta delante de un camión."},"zh":{"q":"在 Ohio，一辆载满货物的卡车在理想条件下以 55 mph 行驶。它大约需要多长的距离才能停下来？","o":["大约 50 英尺","大约 100 英尺","大约 150 英尺","至少 335 英尺"],"h1":"它需要的距离是汽车的一倍半以上。","h2":"Ohio 驾驶手册说，满载的卡车以 55 mph 行驶时至少需要 335 英尺才能停下来，所以绝对不要突然切到卡车前面。","p":"对。至少 335 英尺，所以不要切到卡车前面。"},"vi":{"q":"Ở Ohio, một xe tải chở đầy hàng đang chạy 55 mph trong điều kiện lý tưởng. Nó cần khoảng bao xa để dừng lại?","o":["Khoảng 50 feet","Khoảng 100 feet","Khoảng 150 feet","Ít nhất 335 feet"],"h1":"Nó cần hơn một lần rưỡi khoảng cách mà một chiếc xe hơi cần.","h2":"Sổ tay lái xe của Ohio nói một xe tải chở đầy hàng chạy 55 mph cần ít nhất 335 feet để dừng lại, vì vậy đừng bao giờ cắt ngang trước đầu xe tải.","p":"Đúng. Ít nhất 335 feet, vì vậy đừng cắt ngang trước đầu xe tải."},"tl":{"q":"Sa Ohio, tumatakbo nang 55 mph ang isang kargadong truck sa ideal na kondisyon. Mga gaano kalayo ang kailangan nito para huminto?","o":["Mga 50 talampakan","Mga 100 talampakan","Mga 150 talampakan","Hindi bababa sa 335 talampakan"],"h1":"Kailangan nito ng higit sa isa't kalahating beses ng kailangan ng isang kotse.","h2":"Sinasabi ng Ohio driver manual na ang kargadong truck na 55 mph ay nangangailangan ng hindi bababa sa 335 talampakan para huminto, kaya huwag kailanmang sumingit sa harap nito.","p":"Tama. Hindi bababa sa 335 talampakan, kaya huwag sumingit sa harap ng truck."},"ar":{"q":"في Ohio، شاحنة محمّلة تسير بسرعة 55 mph في ظروف مثالية. كم تحتاج من المسافة تقريبًا لتتوقف؟","o":["نحو 50 قدمًا","نحو 100 قدم","نحو 150 قدمًا","335 قدمًا على الأقل"],"h1":"تحتاج أكثر من مرة ونصف مما تحتاجه السيارة.","h2":"يقول دليل السائق في Ohio إن الشاحنة المحمّلة بسرعة 55 mph تحتاج 335 قدمًا على الأقل لتتوقف، لذلك يجب ألّا تدخل أمامها فجأة أبدًا.","p":"صحيح. 335 قدمًا على الأقل، لذلك لا تدخل أمام الشاحنة فجأة."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-048","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, your car breaks down on the road. If you have flares, where should you put them?","o":["Right next to your car","About 20 to 30 feet behind your car","About 200 to 300 feet behind your car","In front of your car only"],"h1":"Put them far enough back that drivers have time to change lanes.","h2":"In Ohio, if your car breaks down, place flares about 200 to 300 feet behind it so other drivers have time to move over.","p":"Right. About 200 to 300 feet behind the car."},"es":{"q":"En Ohio, su carro se descompone en la carretera. Si tiene bengalas, ¿dónde debe ponerlas?","o":["Justo al lado de su carro","Unos 20 a 30 pies detrás de su carro","Unos 200 a 300 pies detrás de su carro","Solo delante de su carro"],"h1":"Póngalas lo bastante lejos para que los conductores tengan tiempo de cambiarse de carril.","h2":"En Ohio, si su carro se descompone, ponga bengalas unos 200 a 300 pies detrás de él para que los demás conductores tengan tiempo de cambiarse de carril.","p":"Correcto. Unos 200 a 300 pies detrás del carro."},"zh":{"q":"在 Ohio，你的车在路上抛锚了。如果你有警示火焰（flares），应该放在哪里？","o":["就在你的车旁边","在你的车后面大约 20 到 30 英尺","在你的车后面大约 200 到 300 英尺","只放在你的车前面"],"h1":"要放得够远，让其他司机有时间换车道。","h2":"在 Ohio，如果你的车抛锚了，要把警示火焰放在车后面大约 200 到 300 英尺的地方，让其他司机有时间避开。","p":"对。在车后面大约 200 到 300 英尺。"},"vi":{"q":"Ở Ohio, xe của bạn bị hư trên đường. Nếu bạn có pháo sáng (flares), bạn nên đặt chúng ở đâu?","o":["Ngay cạnh xe của bạn","Khoảng 20 đến 30 feet phía sau xe của bạn","Khoảng 200 đến 300 feet phía sau xe của bạn","Chỉ ở phía trước xe của bạn"],"h1":"Đặt đủ xa phía sau để các tài xế khác có thời gian chuyển làn.","h2":"Ở Ohio, nếu xe của bạn bị hư, hãy đặt pháo sáng khoảng 200 đến 300 feet phía sau xe để các tài xế khác có thời gian tránh sang làn khác.","p":"Đúng. Khoảng 200 đến 300 feet phía sau xe."},"tl":{"q":"Sa Ohio, nasiraan ang kotse mo sa kalsada. Kung may flares ka, saan mo dapat ilagay ang mga ito?","o":["Mismo sa tabi ng kotse mo","Mga 20 hanggang 30 talampakan sa likod ng kotse mo","Mga 200 hanggang 300 talampakan sa likod ng kotse mo","Sa harap lang ng kotse mo"],"h1":"Ilagay ang mga ito nang sapat na malayo para may oras ang ibang driver na lumipat ng lane.","h2":"Sa Ohio, kung nasiraan ang kotse mo, ilagay ang flares mga 200 hanggang 300 talampakan sa likod nito para may oras ang ibang driver na lumipat.","p":"Tama. Mga 200 hanggang 300 talampakan sa likod ng kotse."},"ar":{"q":"في Ohio، تعطّلت سيارتك على الطريق. إذا كانت معك مشاعل تحذير (flares)، أين يجب أن تضعها؟","o":["بجانب سيارتك مباشرة","على بُعد 20 إلى 30 قدمًا تقريبًا خلف سيارتك","على بُعد 200 إلى 300 قدم تقريبًا خلف سيارتك","أمام سيارتك فقط"],"h1":"ضعها بعيدًا بما يكفي حتى يكون لدى السائقين وقت لتغيير المسار.","h2":"في Ohio، إذا تعطّلت سيارتك، ضع مشاعل التحذير على بُعد 200 إلى 300 قدم تقريبًا خلفها حتى يكون لدى السائقين الآخرين وقت للابتعاد.","p":"صحيح. على بُعد 200 إلى 300 قدم تقريبًا خلف السيارة."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-049","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, when does a driver license issued to someone under 21 expire?","o":["On the driver's 21st birthday","On the driver's 18th birthday","Eight years after it is issued","It never expires"],"h1":"It ends on a birthday that also ends the under-21 rules.","h2":"In Ohio, a driver license issued to someone under 21 expires on their 21st birthday and must be renewed in person.","p":"Right. It expires on your 21st birthday."},"es":{"q":"En Ohio, ¿cuándo vence una licencia de conducir dada a una persona menor de 21 años?","o":["El día que el conductor cumple 21 años","El día que el conductor cumple 18 años","Ocho años después de emitida","Nunca vence"],"h1":"Vence en un cumpleaños que también pone fin a las reglas para menores de 21.","h2":"En Ohio, una licencia de conducir dada a una persona menor de 21 años vence el día que cumple 21 años y se debe renovar en persona.","p":"Correcto. Vence el día que cumple 21 años."},"zh":{"q":"在 Ohio，发给未满 21 岁的人的驾照什么时候到期？","o":["在司机 21 岁生日那天","在司机 18 岁生日那天","发出后八年","永远不会到期"],"h1":"它在一个生日那天到期，那个生日也结束了未满 21 岁的规定。","h2":"在 Ohio，发给未满 21 岁的人的驾照在他们 21 岁生日那天到期，而且必须亲自去更新。","p":"对。它在你 21 岁生日那天到期。"},"vi":{"q":"Ở Ohio, bằng lái cấp cho người dưới 21 tuổi hết hạn khi nào?","o":["Vào sinh nhật 21 tuổi của tài xế","Vào sinh nhật 18 tuổi của tài xế","Tám năm sau khi được cấp","Không bao giờ hết hạn"],"h1":"Nó hết hạn vào một ngày sinh nhật, cũng là ngày kết thúc các quy định cho người dưới 21 tuổi.","h2":"Ở Ohio, bằng lái cấp cho người dưới 21 tuổi hết hạn vào sinh nhật 21 tuổi của họ và phải được gia hạn trực tiếp.","p":"Đúng. Nó hết hạn vào sinh nhật 21 tuổi của bạn."},"tl":{"q":"Sa Ohio, kailan mag-e-expire ang driver license na ibinigay sa isang wala pang 21?","o":["Sa ika-21 kaarawan ng driver","Sa ika-18 kaarawan ng driver","Walong taon matapos itong ibigay","Hindi ito nag-e-expire kailanman"],"h1":"Natatapos ito sa isang kaarawan na tumatapos din sa mga patakaran para sa wala pang 21.","h2":"Sa Ohio, ang driver license na ibinigay sa isang wala pang 21 ay mag-e-expire sa kanyang ika-21 kaarawan at dapat i-renew nang personal.","p":"Tama. Mag-e-expire ito sa ika-21 kaarawan mo."},"ar":{"q":"في Ohio، متى تنتهي رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة؟","o":["في عيد ميلاد السائق الحادي والعشرين","في عيد ميلاد السائق الثامن عشر","بعد ثماني سنوات من إصدارها","لا تنتهي أبدًا"],"h1":"تنتهي في عيد ميلاد تنتهي فيه أيضًا قواعد من هم دون 21 سنة.","h2":"في Ohio، رخصة القيادة الصادرة لشخص عمره أقل من 21 سنة تنتهي في عيد ميلاده الحادي والعشرين، ويجب تجديدها شخصيًا.","p":"صحيح. تنتهي في عيد ميلادك الحادي والعشرين."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-050","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, what is the youngest age to apply for a moped license?","o":["12","14","15 and a half","16"],"h1":"It is younger than the age for a car permit.","h2":"In Ohio, you can apply for a moped license at age 14, and riders who are 14 or 15 may ride only in daylight.","p":"Right. A moped license starts at 14."},"es":{"q":"En Ohio, ¿cuál es la edad mínima para solicitar una licencia de ciclomotor (moped)?","o":["12","14","15 y medio","16"],"h1":"Es menos que la edad para el permiso de carro.","h2":"En Ohio, usted puede solicitar una licencia de ciclomotor (moped) a los 14 años, y quienes tienen 14 o 15 años solo pueden manejarlo de día.","p":"Correcto. La licencia de ciclomotor empieza a los 14 años."},"zh":{"q":"在 Ohio，最小几岁可以申请轻便摩托车（moped）驾照？","o":["12","14","15 岁半","16"],"h1":"它比拿汽车学习驾照的年龄小。","h2":"在 Ohio，你 14 岁就可以申请轻便摩托车驾照，14 或 15 岁的骑手只能在白天骑。","p":"对。轻便摩托车驾照从 14 岁开始。"},"vi":{"q":"Ở Ohio, tuổi nhỏ nhất để xin bằng lái xe gắn máy nhỏ (moped) là bao nhiêu?","o":["12","14","15 tuổi rưỡi","16"],"h1":"Tuổi này nhỏ hơn tuổi xin giấy phép tập lái xe hơi.","h2":"Ở Ohio, bạn có thể xin bằng lái xe gắn máy nhỏ khi 14 tuổi, và người lái 14 hoặc 15 tuổi chỉ được chạy vào ban ngày.","p":"Đúng. Bằng lái xe gắn máy nhỏ bắt đầu từ 14 tuổi."},"tl":{"q":"Sa Ohio, ano ang pinakabatang edad para mag-apply ng moped license?","o":["12","14","15 at kalahati","16"],"h1":"Mas bata ito kaysa sa edad para sa car permit.","h2":"Sa Ohio, puwede kang mag-apply ng moped license sa edad na 14, at ang mga rider na 14 o 15 ay puwedeng magmaneho sa araw lang.","p":"Tama. Nagsisimula ang moped license sa 14."},"ar":{"q":"في Ohio، ما أصغر عمر للتقدّم بطلب رخصة دراجة نارية صغيرة (moped)؟","o":["12","14","15 ونصف","16"],"h1":"هو أصغر من عمر تصريح قيادة السيارة.","h2":"في Ohio، يمكنك التقدّم بطلب رخصة الدراجة النارية الصغيرة في عمر 14 سنة، والراكبون الذين عمرهم 14 أو 15 سنة يمكنهم القيادة في النهار فقط.","p":"صحيح. رخصة الدراجة النارية الصغيرة تبدأ من عمر 14 سنة."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-051","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what score do you need to pass the 40-question knowledge test?","o":["75 percent","70 percent","80 percent","90 percent"],"h1":"You need three out of every four answers right.","h2":"In Ohio, you must answer 75 percent of the 40 knowledge test questions correctly to pass.","p":"Right. You need 75 percent to pass."},"es":{"q":"En Ohio, ¿qué puntaje necesita para aprobar el examen de conocimientos de 40 preguntas?","o":["75 por ciento","70 por ciento","80 por ciento","90 por ciento"],"h1":"Necesita acertar tres de cada cuatro respuestas.","h2":"En Ohio, usted debe contestar bien el 75 por ciento de las 40 preguntas del examen de conocimientos para aprobarlo.","p":"Correcto. Necesita el 75 por ciento para aprobar."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-052","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, you fail the knowledge test at a Driver Exam Station. When may you take it again?","o":["Right away, the same day","After waiting one day","After 30 days","After six months"],"h1":"You may take the test only once in a day.","h2":"In Ohio, if you fail the knowledge test, you must wait one day before you take it again.","p":"Right. You wait one day and try again."},"es":{"q":"En Ohio, usted no aprueba el examen de conocimientos en una estación de exámenes. ¿Cuándo puede repetirlo?","o":["Enseguida, el mismo día","Después de esperar un día","Después de 30 días","Después de seis meses"],"h1":"Solo puede tomar el examen una vez al día.","h2":"En Ohio, si no aprueba el examen de conocimientos, debe esperar un día antes de volver a tomarlo.","p":"Correcto. Espera un día y lo intenta de nuevo."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-053","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a permit holder is 15 and a half. Who may sit in the front passenger seat to supervise?","o":["A licensed brother who is 19","Any licensed driver who is 18","A parent, guardian or licensed driving instructor","A friend who is 17 and has a license"],"h1":"Before age 16, the rules are stricter than just any licensed driver.","h2":"In Ohio, a permit holder under 16 must have a parent, guardian, custodian, licensed driving instructor, or an adult 21 or older acting as a parent in the front passenger seat.","p":"Right. Under 16, a parent, guardian or instructor must supervise."},"es":{"q":"En Ohio, una persona con permiso tiene 15 años y medio. ¿Quién puede ir en el asiento del pasajero delantero para supervisarla?","o":["Un hermano con licencia que tenga 19 años","Cualquier conductor con licencia que tenga 18 años","Un padre, tutor o instructor de manejo con licencia","Un amigo de 17 años que tenga licencia"],"h1":"Antes de los 16 años, las reglas son más estrictas que solo tener cualquier conductor con licencia.","h2":"En Ohio, una persona con permiso menor de 16 años debe llevar en el asiento del pasajero delantero a su padre o madre, tutor, custodio, un instructor de manejo con licencia o un adulto de 21 años o más que actúe como padre.","p":"Correcto. Antes de los 16 años, debe supervisar un padre, tutor o instructor."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-054","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a permit holder is 17. Who must ride with them to drive between midnight and 6 a.m.?","o":["No one; permit holders may not drive at night at all","Any licensed driver who is 21 or older","Any licensed driver who is 18 or older","A licensed parent, guardian or custodian"],"h1":"At these hours, it must be a family adult in charge of the teen.","h2":"In Ohio, a permit holder who is 16 or 17 may drive from midnight to 6 a.m. only with a parent, guardian or custodian who has a valid license.","p":"Right. From midnight to 6 a.m., a licensed parent, guardian or custodian must ride along."},"es":{"q":"En Ohio, una persona con permiso tiene 17 años. ¿Quién debe acompañarla para manejar entre la medianoche y las 6 a.m.?","o":["Nadie; con permiso no se puede manejar de noche","Cualquier conductor con licencia de 21 años o más","Cualquier conductor con licencia de 18 años o más","Su padre o madre, tutor o custodio con licencia"],"h1":"A esas horas, debe ser un adulto de la familia a cargo del joven.","h2":"En Ohio, una persona con permiso de 16 o 17 años puede manejar de la medianoche a las 6 a.m. solo con su padre o madre, tutor o custodio que tenga licencia válida.","p":"Correcto. De la medianoche a las 6 a.m. debe ir su padre o madre, tutor o custodio con licencia."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-055","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a temporary resident who is 21 or older gets a permit. How long must they hold it before getting a license?","o":["At least 14 days","At least six months","At least one year","At least 60 days"],"h1":"It is much shorter than the six months a teen must wait.","h2":"In Ohio, a temporary resident who is 21 or older must hold the permit for at least 14 days before getting a license.","p":"Right. A temporary resident 21 or older holds the permit for at least 14 days."},"es":{"q":"En Ohio, un residente temporal de 21 años o más obtiene un permiso. ¿Cuánto tiempo debe tenerlo antes de obtener la licencia?","o":["Por lo menos 14 días","Por lo menos seis meses","Por lo menos un año","Por lo menos 60 días"],"h1":"Es mucho menos que los seis meses que espera un adolescente.","h2":"En Ohio, un residente temporal de 21 años o más debe tener el permiso por lo menos 14 días antes de obtener la licencia.","p":"Correcto. Un residente temporal de 21 años o más tiene el permiso por lo menos 14 días."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-056","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, from how far away must your red taillight be visible?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"It is the same distance as for your brake lights.","h2":"In Ohio, a car's red taillight must be visible from 500 feet away.","p":"Right. The taillight must be seen from 500 feet."},"es":{"q":"En Ohio, ¿desde qué distancia se debe ver la luz trasera roja de su carro?","o":["100 pies","500 pies","200 pies","1,000 pies"],"h1":"Es la misma distancia que para las luces de freno.","h2":"En Ohio, la luz trasera roja de un carro se debe ver desde 500 pies de distancia.","p":"Correcto. La luz trasera se debe ver desde 500 pies."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-057","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, how much light must the side windows next to the front seats let through?","o":["35 percent","70 percent","50 percent, give or take 3 percent","20 percent"],"h1":"It is lower than the windshield, which must let 70 percent through.","h2":"In Ohio, the front side windows must let through 50 percent of light, plus or minus 3 percent.","p":"Right. Front side windows must let 50 percent of light through."},"es":{"q":"En Ohio, ¿cuánta luz deben dejar pasar las ventanas laterales junto a los asientos delanteros?","o":["35 por ciento","70 por ciento","50 por ciento, con 3 por ciento más o menos","20 por ciento"],"h1":"Es menos que el parabrisas, que debe dejar pasar el 70 por ciento.","h2":"En Ohio, las ventanas laterales delanteras deben dejar pasar el 50 por ciento de la luz, con 3 por ciento más o menos.","p":"Correcto. Las ventanas laterales delanteras deben dejar pasar el 50 por ciento de la luz."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-058","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, how far before a turn or lane change must you turn on your signal?","o":["At least 500 feet","At least 25 feet","At least 50 feet","At least 100 feet"],"h1":"Think of about a third of a football field.","h2":"In Ohio, you must turn on your signal at least 100 feet before you turn or change direction.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Ohio, ¿a qué distancia antes de girar o cambiar de carril debe poner la direccional?","o":["Por lo menos 500 pies","Por lo menos 25 pies","Por lo menos 50 pies","Por lo menos 100 pies"],"h1":"Piense en un tercio de una cancha de fútbol americano.","h2":"En Ohio, usted debe poner la direccional por lo menos 100 pies antes de girar o cambiar de dirección.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-059","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, you check your tire with a penny, putting Lincoln's head into the groove. You can see all of his head. What does this mean?","o":["The tire is too worn; replace it","The tread is deep enough","The tire has too much air","The tire needs to be rotated only"],"h1":"Deep tread would hide part of the head.","h2":"In Ohio, if you can see all of Lincoln's head in the penny test, the tire is too worn and must be replaced before you drive.","p":"Right. Seeing all of the head means the tire is worn out."},"es":{"q":"En Ohio, usted revisa una llanta con un centavo, poniendo la cabeza de Lincoln dentro de la ranura. Puede ver toda la cabeza. ¿Qué significa?","o":["La llanta está muy gastada; debe cambiarla","La banda tiene suficiente profundidad","La llanta tiene demasiado aire","Solo hay que rotar la llanta"],"h1":"Una banda profunda taparía parte de la cabeza.","h2":"En Ohio, si en la prueba del centavo ve toda la cabeza de Lincoln, la llanta está muy gastada y debe cambiarla antes de manejar.","p":"Correcto. Ver toda la cabeza significa que la llanta está gastada."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-060","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, an adult driver gets a second hand-held phone ticket within two years. What is the penalty?","o":["2 points and up to a $150 fine","3 points and up to a $250 fine","4 points and up to a $500 fine","A warning only"],"h1":"The penalty goes up one step from the first offense.","h2":"In Ohio, a second hand-held phone offense within two years brings 3 points and a fine of up to $250.","p":"Right. A second offense is 3 points and up to $250."},"es":{"q":"En Ohio, un conductor adulto recibe una segunda multa por tener el teléfono en la mano en dos años. ¿Cuál es la sanción?","o":["2 puntos y una multa de hasta $150","3 puntos y una multa de hasta $250","4 puntos y una multa de hasta $500","Solo una advertencia"],"h1":"La sanción sube un paso desde la primera vez.","h2":"En Ohio, una segunda infracción por tener el teléfono en la mano en dos años trae 3 puntos y una multa de hasta $250.","p":"Correcto. La segunda vez son 3 puntos y hasta $250."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-061","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, what can happen to an adult driver with a third hand-held phone offense within two years?","o":["Only a distracted driving course","2 points and a $150 fine","4 points, up to a $500 fine, and a possible 90-day suspension","The car is taken away for a year"],"h1":"This is the highest step, and the license itself may be at risk.","h2":"In Ohio, a third hand-held phone offense within two years brings 4 points, a fine of up to $500, and a possible 90-day license suspension.","p":"Right. A third offense is 4 points, up to $500, and a possible 90-day suspension."},"es":{"q":"En Ohio, ¿qué le puede pasar a un conductor adulto con una tercera infracción por tener el teléfono en la mano en dos años?","o":["Solo un curso sobre manejo distraído","2 puntos y una multa de $150","4 puntos, una multa de hasta $500 y una posible suspensión de 90 días","Le quitan el carro por un año"],"h1":"Es el paso más alto, y la licencia misma puede estar en riesgo.","h2":"En Ohio, una tercera infracción por tener el teléfono en la mano en dos años trae 4 puntos, una multa de hasta $500 y una posible suspensión de la licencia de 90 días.","p":"Correcto. La tercera vez son 4 puntos, hasta $500 y una posible suspensión de 90 días."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-062","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a driver under 18 is caught using a phone while driving for the second time. What is the penalty?","o":["A $50 fine only","A 60-day suspension and a $150 fine","2 points and a warning","A one-year suspension and a $300 fine"],"h1":"The first time is 60 days and $150; the second is much more.","h2":"In Ohio, a second phone violation by a driver under 18 brings a one-year license suspension and a $300 fine.","p":"Right. A second violation is a one-year suspension and $300."},"es":{"q":"En Ohio, a un conductor menor de 18 años lo sorprenden usando el teléfono al manejar por segunda vez. ¿Cuál es la sanción?","o":["Solo una multa de $50","Una suspensión de 60 días y una multa de $150","2 puntos y una advertencia","Una suspensión de un año y una multa de $300"],"h1":"La primera vez son 60 días y $150; la segunda es mucho más.","h2":"En Ohio, una segunda infracción con el teléfono de un conductor menor de 18 años trae una suspensión de la licencia de un año y una multa de $300.","p":"Correcto. La segunda vez es una suspensión de un año y $300."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-063","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, a 17-year-old driver is stopped at a red light. May they talk or text on a phone, even hands-free?","o":["No, not even while stopped at a light","Yes, while the car is stopped","Yes, if it is hands-free","Yes, for a short text"],"h1":"For drivers under 18, the rule covers traffic lights and traffic jams too.","h2":"In Ohio, a driver under 18 may not use any electronic device while driving, even hands-free or while stopped at a traffic light, except for navigation or an emergency call.","p":"Right. Under 18, no phone use, even at a red light."},"es":{"q":"En Ohio, un conductor de 17 años está detenido en una luz roja. ¿Puede hablar o escribir mensajes por teléfono, aunque sea con manos libres?","o":["No, ni siquiera detenido en una luz","Sí, mientras el carro está detenido","Sí, si es con manos libres","Sí, para un mensaje corto"],"h1":"Para menores de 18 años, la regla también incluye semáforos y tráfico detenido.","h2":"En Ohio, un conductor menor de 18 años no puede usar ningún aparato electrónico al manejar, ni con manos libres ni detenido en un semáforo, salvo para navegación o una llamada de emergencia.","p":"Correcto. Menores de 18 años no usan el teléfono, ni en una luz roja."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-064","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, the power is out and a traffic light is dark. No officer is there. What must you do?","o":["Drive through if the main road is yours","Treat it as a four-way stop","Slow down but do not stop","Treat it as a yield sign only"],"h1":"Every driver must come to a full stop first.","h2":"In Ohio, when a traffic signal is not working and no officer is directing traffic, you must treat the intersection as a four-way stop.","p":"Right. A dark signal is a four-way stop."},"es":{"q":"En Ohio, no hay electricidad y el semáforo está apagado. No hay ningún policía. ¿Qué debe hacer?","o":["Pasar si usted va por la calle principal","Tratarlo como un alto en las cuatro direcciones","Bajar la velocidad, pero sin parar","Tratarlo solo como señal de ceda el paso"],"h1":"Todos los conductores deben parar por completo primero.","h2":"En Ohio, cuando un semáforo no funciona y no hay un policía dirigiendo el tráfico, usted debe tratar el cruce como un alto en las cuatro direcciones.","p":"Correcto. Un semáforo apagado es un alto en las cuatro direcciones."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-065","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, you and another driver reach a four-way intersection at the same time. Who goes first?","o":["The driver going faster","The driver on the left","The driver on the right","The larger vehicle"],"h1":"Look to your right side.","h2":"In Ohio, when two drivers reach a four-way intersection at the same time, you yield to the driver on your right.","p":"Right. The driver on the right goes first."},"es":{"q":"En Ohio, usted y otro conductor llegan a un cruce de cuatro vías al mismo tiempo. ¿Quién pasa primero?","o":["El conductor que va más rápido","El conductor de la izquierda","El conductor de la derecha","El vehículo más grande"],"h1":"Mire hacia su lado derecho.","h2":"En Ohio, cuando dos conductores llegan al mismo tiempo a un cruce de cuatro vías, usted cede el paso al conductor de su derecha.","p":"Correcto. El conductor de la derecha pasa primero."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-066","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, when may you turn left on a red light?","o":["Never; left turns on red are not allowed","From any street, after a full stop","Only when a police officer waves you on","From a one-way street onto another one-way street, after a full stop"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Ohio, you may turn left on red only from the far left lane of a one-way street onto another one-way street, after a full stop, unless a sign forbids it.","p":"Right. Left on red is allowed from one one-way street onto another."},"es":{"q":"En Ohio, ¿cuándo puede girar a la izquierda con la luz roja?","o":["Nunca; no se permite girar a la izquierda con luz roja","Desde cualquier calle, después de parar por completo","Solo cuando un policía le hace señas","De una calle de un solo sentido a otra de un solo sentido, después de parar por completo"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Ohio, puede girar a la izquierda con luz roja solo desde el carril de la extrema izquierda de una calle de un solo sentido hacia otra calle de un solo sentido, después de parar por completo, salvo que una señal lo prohíba.","p":"Correcto. Se puede girar a la izquierda con luz roja de una calle de un solo sentido a otra."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-067","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, a slow car is ahead and the paved shoulder on the right is empty. May you pass on the shoulder?","o":["No, never pass on the shoulder, paved or not","Yes, if the shoulder is paved","Yes, if you signal first","Yes, if the car ahead is turning left"],"h1":"The shoulder is not a travel lane.","h2":"In Ohio, you must never pass on the shoulder, whether it is paved or not.","p":"Right. Never pass on the shoulder."},"es":{"q":"En Ohio, hay un carro lento adelante y el acotamiento pavimentado de la derecha está vacío. ¿Puede rebasar por el acotamiento?","o":["No, nunca rebase por el acotamiento, esté pavimentado o no","Sí, si el acotamiento está pavimentado","Sí, si pone la direccional primero","Sí, si el carro de adelante va a girar a la izquierda"],"h1":"El acotamiento no es un carril para circular.","h2":"En Ohio, nunca debe rebasar por el acotamiento, esté pavimentado o no.","p":"Correcto. Nunca rebase por el acotamiento."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-068","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, a train is coming toward a crossing. Where must you stop?","o":["Right on the edge of the first rail","No closer than 15 feet and no farther than 50 feet from the crossing","At least 100 feet back","Anywhere, as long as you can see the train"],"h1":"There is both a closest and a farthest point.","h2":"In Ohio, when a train is coming, you must stop no closer than 15 feet and no farther than 50 feet from the railroad crossing.","p":"Right. Stop between 15 and 50 feet from the crossing."},"es":{"q":"En Ohio, viene un tren hacia un cruce. ¿Dónde debe parar?","o":["Justo en el borde del primer riel","A no menos de 15 pies y no más de 50 pies del cruce","Por lo menos 100 pies antes","En cualquier lugar, si puede ver el tren"],"h1":"Hay una distancia más cercana y una más lejana.","h2":"En Ohio, cuando viene un tren, usted debe parar a no menos de 15 pies y a no más de 50 pies del cruce de tren.","p":"Correcto. Pare entre 15 y 50 pies del cruce."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-069","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, which of these vehicles must always stop at a railroad crossing, even with no train in sight?","o":["A motorcycle","A pickup truck","A school bus","A car pulling a small trailer"],"h1":"Think of vehicles carrying children, paying passengers, or explosives.","h2":"In Ohio, school buses, vehicles carrying passengers for hire, and vehicles carrying explosives or flammable liquids must stop at railroad crossings.","p":"Right. A school bus must stop at every railroad crossing."},"es":{"q":"En Ohio, ¿cuál de estos vehículos siempre debe parar en un cruce de tren, aunque no se vea ningún tren?","o":["Una motocicleta","Una camioneta pickup","Un autobús escolar","Un carro que jala un remolque pequeño"],"h1":"Piense en vehículos que llevan niños, pasajeros que pagan o explosivos.","h2":"En Ohio, los autobuses escolares, los vehículos que llevan pasajeros por pago y los que llevan explosivos o líquidos inflamables deben parar en los cruces de tren.","p":"Correcto. Un autobús escolar debe parar en todo cruce de tren."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-070","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, a school bus ahead turns on flashing amber (yellow) lights. What do they mean?","o":["You may pass the bus quickly","Children are crossing now; stop at once","The bus is broken down","The bus is getting ready to stop; prepare to stop"],"h1":"Amber comes before red.","h2":"In Ohio, flashing amber lights mean the school bus is about to stop; you do not have to stop yet, but you should be ready to stop when the red lights start.","p":"Right. Amber lights mean the bus is about to stop."},"es":{"q":"En Ohio, un autobús escolar adelante enciende luces ámbar (amarillas) intermitentes. ¿Qué significan?","o":["Puede rebasar el autobús rápido","Hay niños cruzando ahora; pare enseguida","El autobús está descompuesto","El autobús se prepara para parar; prepárese para parar"],"h1":"El ámbar viene antes del rojo.","h2":"En Ohio, las luces ámbar intermitentes significan que el autobús escolar está por parar; todavía no tiene que parar, pero debe estar listo para parar cuando empiecen las luces rojas.","p":"Correcto. Las luces ámbar significan que el autobús va a parar."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-071","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, when you park along a curb, how close to the curb must your wheels be?","o":["Within 12 inches","Within 18 inches","Within 24 inches","Within 6 feet"],"h1":"It is about one foot.","h2":"In Ohio, you must park parallel to the curb and no more than 12 inches from it.","p":"Right. Park within 12 inches of the curb."},"es":{"q":"En Ohio, cuando se estaciona junto a la banqueta, ¿a qué distancia de ella deben quedar las llantas?","o":["A no más de 12 pulgadas","A no más de 18 pulgadas","A no más de 24 pulgadas","A no más de 6 pies"],"h1":"Es más o menos un pie.","h2":"En Ohio, debe estacionarse paralelo a la banqueta y a no más de 12 pulgadas de ella.","p":"Correcto. Estaciónese a no más de 12 pulgadas de la banqueta."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-072","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, how close to an intersection or crosswalk may you park?","o":["No closer than 5 feet","No closer than 20 feet","No closer than 10 feet","No closer than 50 feet"],"h1":"It is twice the distance from a fire hydrant.","h2":"In Ohio, you may not stop, park or stand within 20 feet of an intersection or crosswalk.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Ohio, ¿qué tan cerca de un cruce o de un paso de peatones puede estacionarse?","o":["A no menos de 5 pies","A no menos de 20 pies","A no menos de 10 pies","A no menos de 50 pies"],"h1":"Es el doble de la distancia de un hidrante.","h2":"En Ohio, no puede parar ni estacionarse a menos de 20 pies de un cruce o de un paso de peatones.","p":"Correcto. Quédese por lo menos a 20 pies."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-073","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, you are on a divided highway. An ambulance with siren and lights comes the other way, across the median. What must you do?","o":["Stop in your lane","Pull to the right and stop","You do not have to pull over and stop","Speed up to get out of the way"],"h1":"The rule has an exception for the other side of a divided highway.","h2":"In Ohio, you must pull right and stop for an emergency vehicle with lights and siren, unless it is going the opposite way on a divided highway.","p":"Right. On a divided highway, you need not stop for one going the other way."},"es":{"q":"En Ohio, usted va por una carretera dividida. Una ambulancia con sirena y luces viene en sentido contrario, del otro lado de la división. ¿Qué debe hacer?","o":["Parar en su carril","Orillarse a la derecha y parar","No tiene que orillarse ni parar","Acelerar para quitarse del camino"],"h1":"La regla tiene una excepción para el otro lado de una carretera dividida.","h2":"En Ohio, debe orillarse a la derecha y parar ante un vehículo de emergencia con luces y sirena, salvo que vaya en sentido contrario en una carretera dividida.","p":"Correcto. En una carretera dividida no tiene que parar por uno que va en sentido contrario."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-074","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, after a crash, above what amount of property damage must you be able to show proof of insurance?","o":["More than $5,000","More than $100","More than $1,000","More than $400"],"h1":"It is a few hundred dollars.","h2":"In Ohio, a driver or owner in a crash with more than $400 in property damage must show proof of insurance.","p":"Right. Over $400 in damage means you must show proof of insurance."},"es":{"q":"En Ohio, después de un choque, ¿a partir de qué monto de daños a la propiedad debe poder mostrar prueba de seguro?","o":["Más de $5,000","Más de $100","Más de $1,000","Más de $400"],"h1":"Son unos pocos cientos de dólares.","h2":"En Ohio, un conductor o dueño en un choque con más de $400 en daños a la propiedad debe mostrar prueba de seguro.","p":"Correcto. Con más de $400 en daños debe mostrar prueba de seguro."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-075","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, what is the legal blood alcohol limit for a commercial driver?","o":["0.04 percent","0.02 percent","0.08 percent","0.10 percent"],"h1":"It is half the limit for other adult drivers.","h2":"In Ohio, it is illegal for a commercial driver to drive with a blood alcohol level of 0.04 percent or higher.","p":"Right. The limit for commercial drivers is 0.04."},"es":{"q":"En Ohio, ¿cuál es el límite legal de alcohol en la sangre para un conductor comercial?","o":["0.04 por ciento","0.02 por ciento","0.08 por ciento","0.10 por ciento"],"h1":"Es la mitad del límite para otros conductores adultos.","h2":"En Ohio, es ilegal que un conductor comercial maneje con un nivel de alcohol en la sangre de 0.04 por ciento o más.","p":"Correcto. El límite para conductores comerciales es 0.04."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-076","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a driver refuses a chemical test after an OVI arrest. They had one earlier refusal or OVI conviction in the past 10 years. How long is the license suspended?","o":["90 days","Two years","One year","Five years"],"h1":"The first refusal is one year; each earlier offense adds more.","h2":"In Ohio, a driver who refuses a chemical test with one earlier refusal or OVI conviction in 10 years gets a two-year license suspension.","p":"Right. With one earlier offense, a refusal brings two years."},"es":{"q":"En Ohio, un conductor se niega a la prueba química después de un arresto por OVI. Tuvo una negativa o condena por OVI anterior en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia?","o":["90 días","Dos años","Un año","Cinco años"],"h1":"La primera negativa es un año; cada falta anterior suma más.","h2":"En Ohio, un conductor que se niega a la prueba química y tiene una negativa o condena por OVI anterior en 10 años recibe una suspensión de la licencia de dos años.","p":"Correcto. Con una falta anterior, negarse trae dos años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-077","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a driver tests over the alcohol limit and has one earlier OVI conviction in the past 10 years. How long is the license suspended right away?","o":["Three years","90 days","One year","Five years"],"h1":"The first time is 90 days; this is the next step up.","h2":"In Ohio, a driver who tests over the limit with one earlier OVI conviction in 10 years gets an immediate one-year license suspension.","p":"Right. With one earlier conviction, it is one year."},"es":{"q":"En Ohio, un conductor da más del límite de alcohol en la prueba y tiene una condena por OVI anterior en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["Tres años","90 días","Un año","Cinco años"],"h1":"La primera vez son 90 días; este es el siguiente paso.","h2":"En Ohio, un conductor que da más del límite y tiene una condena por OVI anterior en 10 años recibe de inmediato una suspensión de la licencia de un año.","p":"Correcto. Con una condena anterior, es un año."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-078","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a driver under 21 is found guilty of driving after drinking alcohol (OVUAC). How long can the license suspension be?","o":["Ten years","One week to one month","Exactly 30 days","Three months to two years"],"h1":"The shortest is a few months; the longest is a couple of years.","h2":"In Ohio, an OVUAC for a driver under 21 can bring a license suspension of three months to two years.","p":"Right. It can be three months to two years."},"es":{"q":"En Ohio, a un conductor menor de 21 años lo declaran culpable de manejar después de tomar alcohol (OVUAC). ¿Cuánto puede durar la suspensión de la licencia?","o":["Diez años","De una semana a un mes","Exactamente 30 días","De tres meses a dos años"],"h1":"Lo más corto son unos meses; lo más largo, un par de años.","h2":"En Ohio, un OVUAC de un conductor menor de 21 años puede traer una suspensión de la licencia de tres meses a dos años.","p":"Correcto. Puede ser de tres meses a dos años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-079","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, how many OVI convictions in 20 years put a driver on the Habitual OVI Offender Registry?","o":["Five or more","Two","Three","Ten or more"],"h1":"It is the number of fingers on one hand.","h2":"In Ohio, a driver convicted of OVI five or more times in 20 years is placed on the Habitual OVI/OMWI Offender Registry and also faces jail time.","p":"Right. Five or more OVI convictions in 20 years."},"es":{"q":"En Ohio, ¿cuántas condenas por OVI en 20 años ponen a un conductor en el Registro de Infractores Habituales de OVI?","o":["Cinco o más","Dos","Tres","Diez o más"],"h1":"Es el número de dedos de una mano.","h2":"En Ohio, un conductor condenado por OVI cinco veces o más en 20 años entra en el Registro de Infractores Habituales de OVI/OMWI y también recibe cárcel.","p":"Correcto. Cinco o más condenas por OVI en 20 años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-080","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how many points are added for leaving a crash without stopping to give your name and information?","o":["2 points","6 points","4 points","1 point"],"h1":"It is among the most serious point violations.","h2":"In Ohio, failing to stop and give your identity after a crash adds 6 points to your license.","p":"Right. Leaving a crash without giving your information is 6 points."},"es":{"q":"En Ohio, ¿cuántos puntos le ponen por irse de un choque sin parar a dar su nombre y sus datos?","o":["2 puntos","6 puntos","4 puntos","1 punto"],"h1":"Es una de las infracciones de puntos más graves.","h2":"En Ohio, no parar y no dar su identidad después de un choque suma 6 puntos a su licencia.","p":"Correcto. Irse de un choque sin dar sus datos son 6 puntos."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-081","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a driver under 18 is convicted of driving under the influence. How long is the license suspended?","o":["90 days","One month","Six months","Five years"],"h1":"It is half a year.","h2":"In Ohio, a driver under 18 convicted of probationary OVI gets a six-month license suspension.","p":"Right. It is a six-month suspension."},"es":{"q":"En Ohio, a un conductor menor de 18 años lo condenan por manejar bajo los efectos del alcohol o drogas. ¿Por cuánto tiempo le suspenden la licencia?","o":["90 días","Un mes","Seis meses","Cinco años"],"h1":"Es medio año.","h2":"En Ohio, un conductor menor de 18 años condenado por OVI con licencia provisional recibe una suspensión de la licencia de seis meses.","p":"Correcto. Es una suspensión de seis meses."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-082","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a child is 3 years old. How must the child ride in a car?","o":["On an adult's lap in the back","In a booster seat","With only a lap and shoulder belt","In a child safety seat"],"h1":"Children under 4 or under 40 pounds need the most protection.","h2":"In Ohio, a child who is under 4 years old or weighs less than 40 pounds must ride in a child safety seat.","p":"Right. A child under 4 rides in a child safety seat."},"es":{"q":"En Ohio, un niño tiene 3 años. ¿Cómo debe viajar en el carro?","o":["En las piernas de un adulto atrás","En un asiento elevado (booster)","Solo con el cinturón de regazo y hombro","En un asiento de seguridad para niños"],"h1":"Los niños menores de 4 años o de menos de 40 libras necesitan la mayor protección.","h2":"En Ohio, un niño menor de 4 años o que pesa menos de 40 libras debe viajar en un asiento de seguridad para niños.","p":"Correcto. Un niño menor de 4 años viaja en un asiento de seguridad para niños."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-083","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a car owner knowingly lets a person with a suspended license drive the car. What can happen to the owner?","o":["A fine of up to $1,000 and a suspension of the owner's own license","Nothing; only the driver is punished","A warning letter only","The owner must retake the driving test"],"h1":"Letting that person drive is a crime of its own.","h2":"In Ohio, an owner who knowingly lets someone with a suspended license drive is guilty of wrongful entrustment and can be fined up to $1,000 and have their own license suspended for up to one year.","p":"Right. The owner can be fined and lose their own license for a time."},"es":{"q":"En Ohio, el dueño de un carro deja manejar, a sabiendas, a una persona con la licencia suspendida. ¿Qué le puede pasar al dueño?","o":["Una multa de hasta $1,000 y la suspensión de su propia licencia","Nada; solo castigan al conductor","Solo una carta de advertencia","El dueño debe repetir el examen de manejo"],"h1":"Dejar manejar a esa persona es un delito en sí mismo.","h2":"En Ohio, un dueño que a sabiendas deja manejar a alguien con la licencia suspendida comete el delito de confiar indebidamente el vehículo y puede recibir una multa de hasta $1,000 y la suspensión de su propia licencia por hasta un año.","p":"Correcto. El dueño puede recibir una multa y perder su propia licencia por un tiempo."},"ref":{"doc":"OH","page":null}},{"id":"oh-084","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, you are stopped by police and have a loaded handgun in the car. By law, when must you tell the officer about it?","o":["No later than when the officer asks if you are carrying one","Only after you get the ticket","Only if you are asked to step out of the car","Never; it is private"],"h1":"If the officer asks, you must say so right away.","h2":"In Ohio, a driver with a loaded handgun in the car must tell the officer no later than when the officer asks if they are carrying one, and many drivers choose to say so at first contact.","p":"Right. You must tell the officer no later than when they ask."},"es":{"q":"En Ohio, la policía lo detiene y usted tiene una pistola cargada en el carro. Según la ley, ¿cuándo debe decírselo al policía?","o":["A más tardar cuando el policía le pregunte si lleva una","Solo después de recibir la multa","Solo si le piden que salga del carro","Nunca; es algo privado"],"h1":"Si el policía le pregunta, debe decirlo de inmediato.","h2":"En Ohio, un conductor con una pistola cargada en el carro debe decírselo al policía a más tardar cuando el policía le pregunte si lleva una, y muchos conductores prefieren decirlo en el primer contacto.","p":"Correcto. Debe decírselo al policía a más tardar cuando le pregunte."},"ref":{"doc":"OH","page":null}},{"id":"oh-085","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, how far ahead does the driver manual say you should try to look while driving?","o":["Only to the car in front of you","2 to 3 seconds ahead","20 to 30 seconds ahead","5 minutes ahead"],"h1":"It is much more than a few seconds.","h2":"In Ohio, the driver manual says to try to look at what is happening 20 to 30 seconds ahead of your car.","p":"Right. Look 20 to 30 seconds ahead."},"es":{"q":"En Ohio, ¿qué tan adelante dice el manual que trate de mirar al manejar?","o":["Solo hasta el carro de enfrente","De 2 a 3 segundos adelante","De 20 a 30 segundos adelante","5 minutos adelante"],"h1":"Es mucho más que unos pocos segundos.","h2":"En Ohio, el manual dice que trate de mirar lo que pasa de 20 a 30 segundos delante de su carro.","p":"Correcto. Mire de 20 a 30 segundos adelante."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-086","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, about how far does a car need to brake to a stop from 50 mph on dry pavement with good brakes?","o":["About 600 feet","About 30 feet","About 60 feet","About 158 feet"],"h1":"It is about half the length of a football field.","h2":"In Ohio, the driver manual says that at 50 mph on dry pavement with good brakes, braking to a stop can take about 158 feet.","p":"Right. About 158 feet of braking at 50 mph."},"es":{"q":"En Ohio, ¿más o menos qué distancia necesita un carro para frenar hasta parar a 50 mph en pavimento seco con buenos frenos?","o":["Unos 600 pies","Unos 30 pies","Unos 60 pies","Unos 158 pies"],"h1":"Es más o menos la mitad de una cancha de fútbol americano.","h2":"En Ohio, el manual dice que a 50 mph en pavimento seco con buenos frenos, frenar hasta parar puede tomar unos 158 pies.","p":"Correcto. Unos 158 pies de frenado a 50 mph."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-087","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, you follow a motorcycle at low speed in ideal conditions. What is the smallest following distance you should keep?","o":["Three seconds","One second","Half a second","One car length"],"h1":"In worse conditions you would add one more second.","h2":"In Ohio, you should stay at least three seconds behind a motorcycle at low speeds in ideal conditions, and four seconds or more when conditions are worse.","p":"Right. At least three seconds behind a motorcycle."},"es":{"q":"En Ohio, usted va detrás de una motocicleta a baja velocidad y en condiciones ideales. ¿Cuál es la distancia mínima que debe dejar?","o":["Tres segundos","Un segundo","Medio segundo","El largo de un carro"],"h1":"En peores condiciones, sumaría un segundo más.","h2":"En Ohio, debe ir por lo menos tres segundos detrás de una motocicleta a baja velocidad en condiciones ideales, y cuatro segundos o más cuando las condiciones son peores.","p":"Correcto. Por lo menos tres segundos detrás de una motocicleta."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-088","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, how far behind a large truck can its rear blind spot reach?","o":["Up to 10 feet","Up to 200 feet","Up to 30 feet","Up to 1 mile"],"h1":"It is much longer than a car's blind spot.","h2":"In Ohio, the blind spot directly behind a large truck can reach up to 200 feet, so do not follow too closely.","p":"Right. A truck's rear blind spot can reach 200 feet."},"es":{"q":"En Ohio, ¿hasta qué distancia detrás de un camión grande puede llegar su punto ciego trasero?","o":["Hasta 10 pies","Hasta 200 pies","Hasta 30 pies","Hasta 1 milla"],"h1":"Es mucho más largo que el punto ciego de un carro.","h2":"En Ohio, el punto ciego justo detrás de un camión grande puede llegar hasta 200 pies, así que no lo siga muy de cerca.","p":"Correcto. El punto ciego trasero de un camión puede llegar a 200 pies."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-089","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, besides the slow-moving emblem, what light may farm machinery show to the rear at night?","o":["A green steady light","A blue flashing light","A red flashing light","Its horn every few seconds"],"h1":"Its color matches the back of the vehicle.","h2":"In Ohio, farm machinery with the slow-moving emblem may show a red flashing light to the rear at night, so a red flashing light ahead can mean a slow farm vehicle.","p":"Right. Farm machinery may use a red flashing light at night."},"es":{"q":"En Ohio, además del emblema de vehículo lento, ¿qué luz puede mostrar hacia atrás la maquinaria agrícola de noche?","o":["Una luz verde fija","Una luz azul intermitente","Una luz roja intermitente","La bocina cada pocos segundos"],"h1":"Su color combina con la parte de atrás del vehículo.","h2":"En Ohio, la maquinaria agrícola con el emblema de vehículo lento puede mostrar una luz roja intermitente hacia atrás de noche, así que una luz roja intermitente adelante puede ser un vehículo agrícola lento.","p":"Correcto. La maquinaria agrícola puede usar una luz roja intermitente de noche."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-090","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, a person with a white cane is about to cross the street. Who has the right-of-way?","o":["You, if they are not in a crosswalk","You, if your light is green","Whoever moves first","The person with the white cane"],"h1":"A white cane or guide dog means the person may be blind.","h2":"In Ohio, a pedestrian who is blind or visually impaired, carrying a white cane or using a guide dog, has the right-of-way.","p":"Right. The person with the white cane goes first."},"es":{"q":"En Ohio, una persona con un bastón blanco está por cruzar la calle. ¿Quién tiene el derecho de paso?","o":["Usted, si la persona no está en un paso de peatones","Usted, si su luz está verde","Quien se mueva primero","La persona con el bastón blanco"],"h1":"Un bastón blanco o un perro guía indica que la persona puede ser ciega.","h2":"En Ohio, un peatón ciego o con poca vista, que lleva un bastón blanco o usa un perro guía, tiene el derecho de paso.","p":"Correcto. La persona con el bastón blanco pasa primero."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-091","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, you are hit by an uninsured driver and the damage is over $400. How long do you have to file a crash report with the BMV?","o":["Six months","Ten days","30 days","Five years"],"h1":"It is half a year.","h2":"In Ohio, you may file a crash report (form BMV 3303) with the BMV within six months when the other driver had no insurance and there was injury or more than $400 in damage.","p":"Right. You have six months to file."},"es":{"q":"En Ohio, lo choca un conductor sin seguro y el daño es de más de $400. ¿Cuánto tiempo tiene para presentar un informe del choque al BMV?","o":["Seis meses","Diez días","30 días","Cinco años"],"h1":"Es medio año.","h2":"En Ohio, puede presentar un informe del choque (formulario BMV 3303) al BMV dentro de seis meses cuando el otro conductor no tenía seguro y hubo heridos o más de $400 en daños.","p":"Correcto. Tiene seis meses para presentarlo."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-092","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, an adult who failed the driving test takes the short training course with 24 hours of practice driving. How many hours may they drive in one day?","o":["No more than 8 hours","No more than 4 hours","No more than 12 hours","There is no daily limit"],"h1":"It matches the length of the short class.","h2":"In Ohio, an adult who picks the 24-hour practice driving option may not drive more than four hours in one day.","p":"Right. No more than four hours a day."},"es":{"q":"En Ohio, un adulto que no aprobó el examen de manejo toma el curso corto con 24 horas de práctica de manejo. ¿Cuántas horas puede manejar en un día?","o":["No más de 8 horas","No más de 4 horas","No más de 12 horas","No hay límite por día"],"h1":"Es igual a la duración de la clase corta.","h2":"En Ohio, un adulto que elige la opción de 24 horas de práctica no puede manejar más de cuatro horas en un día.","p":"Correcto. No más de cuatro horas al día."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-093","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a driver's license expires on the 21st birthday. How early can the driver renew it?","o":["Up to six months before","Up to one year before","Up to 30 days before the birthday","Only on or after the birthday"],"h1":"It is about one month.","h2":"In Ohio, a driver under 21 can renew the license up to 30 days before the 21st birthday, in person.","p":"Right. You can renew up to 30 days early."},"es":{"q":"En Ohio, una licencia vence el día que el conductor cumple 21 años. ¿Con cuánta anticipación puede renovarla?","o":["Hasta seis meses antes","Hasta un año antes","Hasta 30 días antes del cumpleaños","Solo el día del cumpleaños o después"],"h1":"Es más o menos un mes.","h2":"En Ohio, un conductor menor de 21 años puede renovar la licencia en persona hasta 30 días antes de cumplir 21 años.","p":"Correcto. Puede renovarla hasta 30 días antes."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-094","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a driver who is 70 renews the license. How long is the new license good for?","o":["Lifetime","8 years","1 year","4 years"],"h1":"The 8-year choice is only for drivers 21 to 64.","h2":"In Ohio, drivers 65 and older get a 4-year license, because the 8-year license is only for qualified drivers 21 to 64.","p":"Right. A driver 65 or older gets a 4-year license."},"es":{"q":"En Ohio, un conductor de 70 años renueva la licencia. ¿Por cuánto tiempo es válida la nueva licencia?","o":["De por vida","8 años","1 año","4 años"],"h1":"La opción de 8 años es solo para conductores de 21 a 64 años.","h2":"En Ohio, los conductores de 65 años o más reciben una licencia de 4 años, porque la de 8 años es solo para conductores de 21 a 64 años que califican.","p":"Correcto. Un conductor de 65 años o más recibe una licencia de 4 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-095","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a new driver under 18 is convicted of a traffic offense in the first months of the license. What may be required?","o":["A parent or guardian must ride along for six months, or until age 17","The driver must retake the knowledge test","A curfew starting at 9 p.m.","The driver may carry no passengers until 21"],"h1":"An adult in charge of the teen must be in the car again.","h2":"In Ohio, a traffic conviction in the first months of a new license may mean a parent or guardian must ride along for six months, or until the driver turns 17.","p":"Right. A parent or guardian may have to ride along for six months, or until 17."},"es":{"q":"En Ohio, a un conductor nuevo menor de 18 años lo condenan por una infracción de tráfico en los primeros meses de su licencia. ¿Qué le pueden exigir?","o":["Que su padre, madre o tutor lo acompañe por seis meses o hasta que cumpla 17 años","Que repita el examen de conocimientos","Un toque de queda desde las 9 p.m.","Que no lleve pasajeros hasta los 21 años"],"h1":"Un adulto a cargo del joven debe ir otra vez en el carro.","h2":"En Ohio, una condena de tráfico en los primeros meses de una licencia nueva puede significar que su padre, madre o tutor debe acompañarlo por seis meses, o hasta que cumpla 17 años.","p":"Correcto. Su padre, madre o tutor puede tener que acompañarlo por seis meses o hasta los 17 años."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-096","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, which CDL class covers a vehicle, not big enough for Class A or B, that is built to carry 16 or more people, counting the driver?","o":["Class D","Class C","Class M","No CDL is needed"],"h1":"It is the CDL class after A and B.","h2":"In Ohio, a vehicle built to carry 16 or more people, counting the driver, that is not Class A or B needs a Class C commercial driver license.","p":"Right. It needs a Class C CDL."},"es":{"q":"En Ohio, ¿qué clase de licencia comercial (CDL) se necesita para un vehículo, que no es de Clase A ni B, hecho para llevar 16 personas o más, contando al conductor?","o":["Clase D","Clase C","Clase M","No se necesita CDL"],"h1":"Es la clase de CDL que sigue a la A y la B.","h2":"En Ohio, un vehículo hecho para llevar 16 personas o más, contando al conductor, que no es de Clase A ni B, necesita una licencia comercial de Clase C.","p":"Correcto. Necesita una CDL de Clase C."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-097","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how fast can a moped's motor move it on a flat road, at most?","o":["45 mph","35 mph","20 mph","55 mph"],"h1":"A moped is slow, close to bicycle speed.","h2":"In Ohio, a moped has a motor of no more than 50 cc that can move it no faster than 20 mph on a flat road.","p":"Right. A moped goes no faster than 20 mph."},"es":{"q":"En Ohio, ¿a qué velocidad máxima puede moverlo el motor de un ciclomotor (moped) en un camino plano?","o":["45 mph","35 mph","20 mph","55 mph"],"h1":"Un ciclomotor es lento, cerca de la velocidad de una bicicleta.","h2":"En Ohio, un ciclomotor (moped) tiene un motor de no más de 50 cc que no puede moverlo a más de 20 mph en un camino plano.","p":"Correcto. Un ciclomotor no pasa de 20 mph."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-098","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, what must a rider under 18 complete before applying for a motorcycle endorsement?","o":["A CDL knowledge test","Nothing beyond a car permit","One year of moped riding","A Motorcycle Ohio safety course"],"h1":"It is a state training program for riders.","h2":"In Ohio, a rider under 18 must complete a Motorcycle Ohio course before applying for a motorcycle endorsement or license.","p":"Right. Riders under 18 must take a Motorcycle Ohio course."},"es":{"q":"En Ohio, ¿qué debe completar un motociclista menor de 18 años antes de solicitar el endoso de motocicleta?","o":["Un examen de conocimientos de CDL","Nada más que el permiso de carro","Un año manejando ciclomotor","Un curso de seguridad de Motorcycle Ohio"],"h1":"Es un programa estatal de entrenamiento para motociclistas.","h2":"En Ohio, un motociclista menor de 18 años debe completar un curso de Motorcycle Ohio antes de solicitar el endoso o la licencia de motocicleta.","p":"Correcto. Los menores de 18 años deben tomar un curso de Motorcycle Ohio."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-099","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, you want a federally compliant (REAL ID) license. How many documents proving your Ohio address must you bring?","o":["Two","One","Three","None"],"h1":"It is one more than a standard card needs.","h2":"In Ohio, a compliant driver license needs two documents that prove your Ohio street address.","p":"Right. A compliant card needs two address documents."},"es":{"q":"En Ohio, usted quiere una licencia que cumple con las normas federales (REAL ID). ¿Cuántos documentos que prueban su domicilio en Ohio debe llevar?","o":["Dos","Uno","Tres","Ninguno"],"h1":"Es uno más de lo que necesita una tarjeta estándar.","h2":"En Ohio, una licencia que cumple con las normas federales necesita dos documentos que prueben su domicilio en Ohio.","p":"Correcto. La tarjeta federal necesita dos documentos de domicilio."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-100","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, you move to the state and become a resident. How soon must you get an Ohio driver's license?","o":["Within 10 days","Within 30 days","Within 6 months","Within 1 year"],"h1":"It is about one month.","h2":"In Ohio, new residents must get an Ohio driver's license within 30 days of becoming a resident.","p":"Right. New residents have 30 days."},"es":{"q":"En Ohio, usted se muda al estado y se hace residente. ¿En cuánto tiempo debe obtener una licencia de Ohio?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses","Dentro de 1 año"],"h1":"Es más o menos un mes.","h2":"En Ohio, los nuevos residentes deben obtener una licencia de conducir de Ohio dentro de 30 días de hacerse residentes.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"OH","page":"§13"}},{"id":"oh-101","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, you take the knowledge test online through BMV Online Services. How many tries do you get in six months?","o":["Two","One","Three","As many as you want"],"h1":"Online tries are more limited than tries at a Driver Exam Station.","h2":"In Ohio, the online knowledge test allows two attempts in a six-month period.","p":"Right. Online, you get two tries in six months."},"es":{"q":"En Ohio, usted toma el examen de conocimientos en línea por BMV Online Services. ¿Cuántos intentos tiene en seis meses?","o":["Dos","Uno","Tres","Todos los que quiera"],"h1":"En línea hay menos intentos que en una estación de exámenes.","h2":"En Ohio, el examen de conocimientos en línea permite dos intentos en un período de seis meses.","p":"Correcto. En línea, tiene dos intentos en seis meses."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-102","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, the knowledge test is not offered in your language. What can you do?","o":["Take the test online with a translation app","Bring your own interpreter to a Driver Exam Station, by appointment","Skip the knowledge test and take only the driving test","Nothing; you must wait until your language is added"],"h1":"You need to book a visit at one kind of BMV office.","h2":"In Ohio, if the test is not offered in your language, you may make an appointment at a Driver Exam Station and bring your own interpreter.","p":"Right. You may bring your own interpreter to a Driver Exam Station."},"es":{"q":"En Ohio, el examen de conocimientos no se ofrece en su idioma. ¿Qué puede hacer?","o":["Tomar el examen en línea con una aplicación de traducción","Llevar su propio intérprete a una estación de exámenes, con cita","Saltarse el examen de conocimientos y tomar solo el de manejo","Nada; debe esperar a que agreguen su idioma"],"h1":"Necesita pedir una cita en un tipo de oficina del BMV.","h2":"En Ohio, si el examen no se ofrece en su idioma, puede pedir una cita en una estación de exámenes (Driver Exam Station) y llevar su propio intérprete.","p":"Correcto. Puede llevar su propio intérprete a una estación de exámenes."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-103","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a 16-year-old goes to buy a temporary instruction permit (TIPIC). Who must come along?","o":["Any licensed adult who is 21 or older","A licensed driving instructor","A parent or guardian, to co-sign the application","No one; teens may apply alone"],"h1":"For anyone under 18, an adult must sign too.","h2":"In Ohio, a permit applicant under 18 needs a parent or guardian present to co-sign the TIPIC application.","p":"Right. A parent or guardian must come and co-sign."},"es":{"q":"En Ohio, un joven de 16 años va a comprar su permiso de aprendizaje (TIPIC). ¿Quién debe acompañarlo?","o":["Cualquier adulto con licencia de 21 años o más","Un instructor de manejo con licencia","Su padre, madre o tutor, para firmar la solicitud con él","Nadie; los jóvenes pueden solicitarlo solos"],"h1":"Para menores de 18 años, un adulto también debe firmar.","h2":"En Ohio, un solicitante de permiso menor de 18 años necesita que su padre, madre o tutor esté presente para firmar con él la solicitud del TIPIC.","p":"Correcto. Un padre, madre o tutor debe ir y firmar con él."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-104","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, you have an Ohio ID card and then get a temporary instruction permit (TIPIC). What happens to the ID card?","o":["You keep it, but only for flying","You keep both cards","It stays valid until its date runs out","It is canceled, because you may hold only one license or ID card"],"h1":"Ohio lets you hold just one of these cards at a time.","h2":"In Ohio, your ID card is canceled when your TIPIC is issued, because you may hold only one driver license or ID card at a time.","p":"Right. The ID card is canceled; you may hold only one card."},"es":{"q":"En Ohio, usted tiene una tarjeta de identificación de Ohio y luego recibe un permiso de aprendizaje (TIPIC). ¿Qué pasa con la tarjeta de identificación?","o":["Se la queda, pero solo para viajar en avión","Se queda con las dos tarjetas","Sigue válida hasta que venza","Se cancela, porque solo puede tener una licencia o tarjeta de identificación"],"h1":"Ohio le permite tener solo una de estas tarjetas a la vez.","h2":"En Ohio, su tarjeta de identificación se cancela cuando le dan el TIPIC, porque solo puede tener una licencia o tarjeta de identificación a la vez.","p":"Correcto. La tarjeta de identificación se cancela; solo puede tener una."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-105","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, from how far away must the two red reflectors on the back of a car be visible?","o":["300 feet","50 feet","100 feet","1,000 feet"],"h1":"It is the length of a football field.","h2":"In Ohio, a car needs two red reflectors on the back that can be seen from 300 feet.","p":"Right. The rear reflectors must be visible from 300 feet."},"es":{"q":"En Ohio, ¿desde qué distancia deben verse los dos reflectores rojos de la parte trasera de un carro?","o":["300 pies","50 pies","100 pies","1,000 pies"],"h1":"Es el largo de un campo de fútbol americano.","h2":"En Ohio, un carro necesita dos reflectores rojos atrás que se vean desde 300 pies.","p":"Correcto. Los reflectores traseros deben verse desde 300 pies."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-106","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, from how far away must people be able to hear your car's horn?","o":["50 feet","200 feet","1,000 feet","One mile"],"h1":"It is about two-thirds of a football field.","h2":"In Ohio, a car horn must work well and be heard from 200 feet.","p":"Right. The horn must be heard from 200 feet."},"es":{"q":"En Ohio, ¿desde qué distancia deben poder oír la bocina de su carro?","o":["50 pies","200 pies","1,000 pies","Una milla"],"h1":"Es como dos tercios de un campo de fútbol americano.","h2":"En Ohio, la bocina de un carro debe funcionar bien y oírse desde 200 pies.","p":"Correcto. La bocina debe oírse desde 200 pies."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-107","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, how much light must a car's windshield let through?","o":["35 percent","50 percent","70 percent","20 percent"],"h1":"The windshield must be clearer than the front side windows.","h2":"In Ohio, a windshield must let through 70 percent of the light, which is standard on most new cars.","p":"Right. The windshield must let through 70 percent."},"es":{"q":"En Ohio, ¿cuánta luz debe dejar pasar el parabrisas de un carro?","o":["35 por ciento","50 por ciento","70 por ciento","20 por ciento"],"h1":"El parabrisas debe ser más claro que las ventanas laterales delanteras.","h2":"En Ohio, el parabrisas debe dejar pasar el 70 por ciento de la luz, lo normal en la mayoría de los carros nuevos.","p":"Correcto. El parabrisas debe dejar pasar el 70 por ciento."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-108","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, how much space does the driver manual say to leave between your chest and the steering wheel?","o":["At least 2 feet","At least 2 inches","At least 5 inches","At least 10 inches"],"h1":"The space is there so the air bag can open.","h2":"In Ohio, the driver manual says to keep at least 10 inches between your chest and the steering wheel so the air bag has room.","p":"Right. Keep at least 10 inches."},"es":{"q":"En Ohio, ¿cuánto espacio dice el manual que debe dejar entre su pecho y el volante?","o":["Por lo menos 2 pies","Por lo menos 2 pulgadas","Por lo menos 5 pulgadas","Por lo menos 10 pulgadas"],"h1":"El espacio es para que la bolsa de aire pueda abrirse.","h2":"En Ohio, el manual dice que debe dejar por lo menos 10 pulgadas entre su pecho y el volante para que la bolsa de aire tenga espacio.","p":"Correcto. Deje por lo menos 10 pulgadas."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-109","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, a 30-year-old drives a car with adult passengers. Under the safety belt law, who must wear a belt?","o":["The driver and anyone in the front seat","Only the driver","Only the passengers in the back seat","No one, if the car has air bags"],"h1":"The law names the driver and one more seat row.","h2":"In Ohio, the safety belt law requires the driver and front-seat passengers to wear safety belts.","p":"Right. The driver and front-seat riders must buckle up."},"es":{"q":"En Ohio, una persona de 30 años maneja un carro con pasajeros adultos. Según la ley del cinturón de seguridad, ¿quién debe usarlo?","o":["El conductor y quien vaya en el asiento delantero","Solo el conductor","Solo los pasajeros del asiento de atrás","Nadie, si el carro tiene bolsas de aire"],"h1":"La ley nombra al conductor y a una fila más de asientos.","h2":"En Ohio, la ley del cinturón exige que el conductor y los pasajeros del asiento delantero usen el cinturón de seguridad.","p":"Correcto. El conductor y quienes van adelante deben abrocharse."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-110","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, an adult driver may hold a phone while driving in which of these cases?","o":["To read a text at low speed","To report an emergency to police or a hospital","To check a map on a straight road","To type a short reply"],"h1":"The exception is for getting help fast.","h2":"In Ohio, an adult driver may use a hand-held phone to report an emergency to police, a hospital, the fire department or a similar emergency service.","p":"Right. Reporting an emergency is allowed."},"es":{"q":"En Ohio, ¿en cuál de estos casos puede un conductor adulto sostener un teléfono mientras maneja?","o":["Para leer un mensaje a poca velocidad","Para reportar una emergencia a la policía o a un hospital","Para mirar un mapa en una carretera recta","Para escribir una respuesta corta"],"h1":"La excepción es para pedir ayuda rápido.","h2":"En Ohio, un conductor adulto puede usar un teléfono en la mano para reportar una emergencia a la policía, un hospital, los bomberos u otro servicio de emergencia parecido.","p":"Correcto. Reportar una emergencia está permitido."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-111","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, what is the speed limit in an alley in a city or village, unless a sign says otherwise?","o":["20 mph","25 mph","15 mph","10 mph"],"h1":"It is the lowest limit on the Ohio list.","h2":"In Ohio, the speed limit in an alley within a city or village is 15 mph.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Ohio, ¿cuál es el límite de velocidad en un callejón de una ciudad o pueblo, si no hay una señal que diga otra cosa?","o":["20 mph","25 mph","15 mph","10 mph"],"h1":"Es el límite más bajo de la lista de Ohio.","h2":"En Ohio, el límite de velocidad en un callejón dentro de una ciudad o pueblo es de 15 mph.","p":"Correcto. En los callejones es 15 mph."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-112","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, what is the school zone speed limit during recess and when children are arriving at or leaving school?","o":["35 mph","15 mph","25 mph","20 mph"],"h1":"It is 5 mph less than the usual city street limit.","h2":"In Ohio, the school zone speed limit is 20 mph during recess and while children are going to or leaving school.","p":"Right. School zones are 20 mph at those times."},"es":{"q":"En Ohio, ¿cuál es el límite de velocidad en una zona escolar durante el recreo y cuando los niños llegan o salen de la escuela?","o":["35 mph","15 mph","25 mph","20 mph"],"h1":"Es 5 mph menos que el límite normal en las calles de la ciudad.","h2":"En Ohio, el límite en una zona escolar es de 20 mph durante el recreo y mientras los niños llegan o salen de la escuela.","p":"Correcto. En las zonas escolares es 20 mph en esas horas."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-113","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, what is the usual speed limit on streets in a city or village, when no other limit is posted?","o":["25 mph","35 mph","30 mph","20 mph"],"h1":"It is a little faster than a school zone.","h2":"In Ohio, the usual speed limit on streets within a city or village is 25 mph.","p":"Right. City streets are usually 25 mph."},"es":{"q":"En Ohio, ¿cuál es el límite de velocidad normal en las calles de una ciudad o pueblo, cuando no hay otro límite señalado?","o":["25 mph","35 mph","30 mph","20 mph"],"h1":"Es un poco más rápido que en una zona escolar.","h2":"En Ohio, el límite normal en las calles dentro de una ciudad o pueblo es de 25 mph.","p":"Correcto. En las calles de la ciudad suele ser 25 mph."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-114","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, what is the speed limit on rural freeways?","o":["55 mph","70 mph","65 mph","75 mph"],"h1":"It is the highest limit on the Ohio list.","h2":"In Ohio, the speed limit on rural freeways is 70 mph.","p":"Right. Rural freeways are 70 mph."},"es":{"q":"En Ohio, ¿cuál es el límite de velocidad en las autopistas rurales?","o":["55 mph","70 mph","65 mph","75 mph"],"h1":"Es el límite más alto de la lista de Ohio.","h2":"En Ohio, el límite de velocidad en las autopistas rurales es de 70 mph.","p":"Correcto. En las autopistas rurales es 70 mph."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-115","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, fog lets you see only a short way ahead. The sign says 55 mph. How fast may you drive?","o":["45 mph, 10 below the limit","55 mph, the posted limit","Only as fast as lets you stop within the distance you can see","Any speed, if your lights are on"],"h1":"Ohio law talks about the \"assured clear distance ahead.\"","h2":"In Ohio, the law says you may never drive faster than lets you stop within the clear distance you can see ahead, whatever the posted limit.","p":"Right. You must be able to stop in the distance you can see."},"es":{"q":"En Ohio, hay neblina y solo puede ver un poco hacia adelante. La señal dice 55 mph. ¿A qué velocidad puede manejar?","o":["45 mph, 10 menos que el límite","55 mph, el límite señalado","Solo tan rápido que pueda parar dentro de la distancia que ve","A cualquier velocidad, si tiene las luces prendidas"],"h1":"La ley de Ohio habla de la \"distancia libre asegurada hacia adelante\".","h2":"En Ohio, la ley dice que nunca puede manejar más rápido de lo que le permite parar dentro de la distancia libre que ve adelante, sin importar el límite señalado.","p":"Correcto. Debe poder parar en la distancia que ve."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-116","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, a funeral procession is going through an intersection. What should you do?","o":["Join the end of the line","Drive through when your light turns green","Honk and drive between the cars","Yield the right-of-way to it"],"h1":"The driver manual lists funeral processions among those you yield to.","h2":"In Ohio, you yield the right-of-way to a funeral procession.","p":"Right. Let the funeral procession go first."},"es":{"q":"En Ohio, un cortejo fúnebre está pasando por una intersección. ¿Qué debe hacer?","o":["Unirse al final de la fila","Pasar cuando su luz se ponga verde","Tocar la bocina y pasar entre los carros","Cederle el paso"],"h1":"El manual pone los cortejos fúnebres entre los que deben recibir el paso.","h2":"En Ohio, usted debe ceder el paso a un cortejo fúnebre.","p":"Correcto. Deje pasar primero al cortejo fúnebre."},"ref":{"doc":"OH","page":"§4"}},{"id":"oh-117","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, how does the driver manual tell you to hold the wheel when you back up and look through the rear window?","o":["Left hand at the top (12 o'clock), right arm on the back of the passenger seat","Both hands at 9 and 3 o'clock","Right hand at the top, left arm out the window","Both hands at the bottom of the wheel"],"h1":"You turn your body to the right to look back.","h2":"In Ohio, to back up you hold the top of the wheel with your left hand, put your right arm on the back of the passenger seat, and look through the rear window.","p":"Right. Left hand at 12 o'clock, right arm on the seat."},"es":{"q":"En Ohio, ¿cómo dice el manual que debe tomar el volante cuando va en reversa y mira por la ventana trasera?","o":["La mano izquierda arriba (a las 12), el brazo derecho sobre el respaldo del asiento del pasajero","Las dos manos a las 9 y a las 3","La mano derecha arriba, el brazo izquierdo por la ventana","Las dos manos en la parte de abajo del volante"],"h1":"Usted gira el cuerpo hacia la derecha para mirar atrás.","h2":"En Ohio, para ir en reversa toma la parte de arriba del volante con la mano izquierda, pone el brazo derecho sobre el respaldo del asiento del pasajero y mira por la ventana trasera.","p":"Correcto. Mano izquierda a las 12, brazo derecho sobre el asiento."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-118","scope":"OH","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Ohio, you drive out of a driveway in a neighborhood. There is a sidewalk, and no one is walking on it. What must you do?","o":["Slow down; you do not need to stop","Stop before the sidewalk, then go on when it is clear","Stop only at the edge of the street","Honk and drive across"],"h1":"The rule applies even when the sidewalk looks empty.","h2":"In Ohio, when you come out of an alley, driveway or private road in a business or residential area, you must stop at the sidewalk, or before the road if there is no sidewalk.","p":"Right. Stop before the sidewalk first."},"es":{"q":"En Ohio, usted sale de una entrada de garaje en un vecindario. Hay una acera y nadie camina por ella. ¿Qué debe hacer?","o":["Bajar la velocidad; no necesita parar","Parar antes de la acera y luego seguir cuando esté libre","Parar solo al borde de la calle","Tocar la bocina y cruzar"],"h1":"La regla se aplica aunque la acera parezca vacía.","h2":"En Ohio, cuando sale de un callejón, una entrada de garaje o un camino privado en una zona comercial o residencial, debe parar en la acera, o antes de la calle si no hay acera.","p":"Correcto. Primero pare antes de la acera."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-119","scope":"OH","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Ohio, you reach a roundabout with four exits and want to go straight. Which exit does the driver manual say to take?","o":["The third exit","The first exit","The second exit","The fourth exit"],"h1":"The first exit is for a right turn.","h2":"In Ohio, in a roundabout you take the first exit to turn right, the second to go straight, the third to turn left, and the fourth to make a U-turn.","p":"Right. The second exit takes you straight."},"es":{"q":"En Ohio, usted llega a una glorieta con cuatro salidas y quiere seguir derecho. ¿Qué salida dice el manual que debe tomar?","o":["La tercera salida","La primera salida","La segunda salida","La cuarta salida"],"h1":"La primera salida es para girar a la derecha.","h2":"En Ohio, en una glorieta toma la primera salida para girar a la derecha, la segunda para seguir derecho, la tercera para girar a la izquierda y la cuarta para dar vuelta en U.","p":"Correcto. La segunda salida lo lleva derecho."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-120","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, you are already inside a roundabout. May you change lanes?","o":["Yes, if no one is next to you","Yes, any time you signal","Yes, but only into the inside lane","No; choose your lane before you enter and stay in it"],"h1":"Read the signs before you go in.","h2":"In Ohio, you cannot change lanes once you are in a roundabout, so check the signs and choose your lane before you enter.","p":"Right. No lane changes inside a roundabout."},"es":{"q":"En Ohio, usted ya está dentro de una glorieta. ¿Puede cambiar de carril?","o":["Sí, si no hay nadie a su lado","Sí, siempre que ponga la direccional","Sí, pero solo al carril de adentro","No; escoja su carril antes de entrar y quédese en él"],"h1":"Lea las señales antes de entrar.","h2":"En Ohio, no puede cambiar de carril una vez que está dentro de una glorieta, así que mire las señales y escoja su carril antes de entrar.","p":"Correcto. No se cambia de carril dentro de una glorieta."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-121","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, you drive on a road with four or more lanes. Which lane should you normally use?","o":["The right lane; use the lane just right of center to pass or turn left","The lane just right of the center line, at all times","Any lane you like","The far left lane"],"h1":"The lane near the center has a special job.","h2":"In Ohio, on a road with four or more lanes you drive in the right lane and use the lane just right of center to pass and to turn left.","p":"Right. Keep right; use the center-side lane to pass or turn left."},"es":{"q":"En Ohio, usted maneja en una carretera de cuatro carriles o más. ¿Qué carril debe usar normalmente?","o":["El carril derecho; use el carril junto al centro para rebasar o girar a la izquierda","El carril junto a la línea del centro, siempre","Cualquier carril que quiera","El carril de más a la izquierda"],"h1":"El carril cerca del centro tiene un uso especial.","h2":"En Ohio, en una carretera de cuatro carriles o más usted maneja en el carril derecho y usa el carril junto al centro para rebasar y para girar a la izquierda.","p":"Correcto. Vaya a la derecha; use el carril del centro para rebasar o girar a la izquierda."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-122","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, you missed your freeway exit. You see an opening through the median. Who may use it?","o":["Any driver who missed an exit","Only emergency and public safety vehicles","Trucks and buses","Anyone, if no cars are coming"],"h1":"If you miss your exit, you take the next one.","h2":"In Ohio, openings through a freeway median are only for emergency and public safety vehicles.","p":"Right. Median openings are only for emergency and public safety vehicles."},"es":{"q":"En Ohio, usted se pasó de su salida en la autopista. Ve una abertura en la división central. ¿Quién puede usarla?","o":["Cualquier conductor que se pasó de su salida","Solo los vehículos de emergencia y de seguridad pública","Los camiones y autobuses","Cualquiera, si no vienen carros"],"h1":"Si se pasa de su salida, tome la siguiente.","h2":"En Ohio, las aberturas en la división central de una autopista son solo para vehículos de emergencia y de seguridad pública.","p":"Correcto. Esas aberturas son solo para vehículos de emergencia y de seguridad pública."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-123","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, you are passing a car. When should you move back into its lane?","o":["When you see it in your side mirror","As soon as your back bumper passes its front bumper","When you can see both of its headlights in your rear-view mirror","When the other driver flashes the lights"],"h1":"Use the mirror inside the car to check.","h2":"In Ohio, you keep passing until you can see both headlights of the car you passed in your rear-view mirror, then signal and move back.","p":"Right. Wait until both headlights show in your rear-view mirror."},"es":{"q":"En Ohio, usted está rebasando un carro. ¿Cuándo debe volver a su carril?","o":["Cuando lo vea en el espejo lateral","En cuanto su defensa trasera pase la defensa delantera del otro","Cuando vea sus dos faros en el espejo retrovisor","Cuando el otro conductor le haga señas con las luces"],"h1":"Use el espejo de adentro del carro para revisar.","h2":"En Ohio, usted sigue rebasando hasta ver los dos faros del carro que rebasó en el espejo retrovisor, y luego pone la direccional y vuelve a su carril.","p":"Correcto. Espere a ver los dos faros en el espejo retrovisor."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-124","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, where does the driver manual say you should not try to pass?","o":["On any road outside a city","On a straight road with a broken yellow line","In the left lane of a multi-lane road","Just before a railroad crossing or a bridge"],"h1":"Think of places where there is little room or a hidden danger.","h2":"In Ohio, you should not pass at an intersection or just before a railroad crossing or a bridge.","p":"Right. Do not pass just before a railroad crossing or a bridge."},"es":{"q":"En Ohio, ¿dónde dice el manual que no debe intentar rebasar?","o":["En cualquier carretera fuera de la ciudad","En una carretera recta con línea amarilla discontinua","En el carril izquierdo de una carretera de varios carriles","Justo antes de un cruce de tren o de un puente"],"h1":"Piense en lugares con poco espacio o un peligro escondido.","h2":"En Ohio, no debe rebasar en una intersección ni justo antes de un cruce de tren o de un puente.","p":"Correcto. No rebase justo antes de un cruce de tren o de un puente."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-125","scope":"OH","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Ohio, you are behind a school bus that stops with red lights flashing, but it has no stop arm. What must you do?","o":["Stop anyway","Go around it, because there is no stop arm","Slow to 10 mph and pass","Stop only if you see children"],"h1":"The red lights are what count.","h2":"In Ohio, you must stop for a school bus with flashing red lights even if the bus has no stop arm.","p":"Right. You must stop even without a stop arm."},"es":{"q":"En Ohio, usted va detrás de un autobús escolar que se detiene con luces rojas intermitentes, pero no tiene brazo de PARE. ¿Qué debe hacer?","o":["Parar de todos modos","Rebasarlo, porque no tiene brazo de PARE","Bajar a 10 mph y pasar","Parar solo si ve niños"],"h1":"Lo que cuenta son las luces rojas.","h2":"En Ohio, usted debe parar ante un autobús escolar con luces rojas intermitentes aunque no tenga brazo de PARE.","p":"Correcto. Debe parar aunque no haya brazo de PARE."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-126","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, you park on a one-way street. Where may you park?","o":["Only next to the right curb","Within 12 inches of either the right or the left curb","Only next to the left curb","In the middle of the street, if it is wide"],"h1":"On a one-way street, both sides are allowed.","h2":"In Ohio, on a one-way street you may park parallel to and within 12 inches of the right or the left curb.","p":"Right. On a one-way street, either curb is allowed."},"es":{"q":"En Ohio, usted se estaciona en una calle de un solo sentido. ¿Dónde puede estacionarse?","o":["Solo junto a la acera derecha","A no más de 12 pulgadas de la acera derecha o de la izquierda","Solo junto a la acera izquierda","En medio de la calle, si es ancha"],"h1":"En una calle de un solo sentido se permiten los dos lados.","h2":"En Ohio, en una calle de un solo sentido puede estacionarse en paralelo y a no más de 12 pulgadas de la acera derecha o de la izquierda.","p":"Correcto. En una calle de un solo sentido, cualquiera de las dos aceras sirve."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-127","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, which of these may be parked on a sidewalk, if it does not block people walking?","o":["A pickup truck, for a few minutes","A small car","A moped or a motor scooter of 150 cc or less","Any vehicle with its hazard lights on"],"h1":"Think of small two-wheelers.","h2":"In Ohio, a bicycle, electric bicycle, moped, motor scooter of 150 cc or less, or micro-mobility device may be parked on a sidewalk if it does not block people walking.","p":"Right. Mopeds and small scooters may park on the sidewalk if they do not block it."},"es":{"q":"En Ohio, ¿cuál de estos se puede estacionar en una acera, si no estorba a la gente que camina?","o":["Una camioneta pickup, por unos minutos","Un carro pequeño","Un ciclomotor o una motoneta de 150 cc o menos","Cualquier vehículo con las luces de emergencia prendidas"],"h1":"Piense en vehículos pequeños de dos ruedas.","h2":"En Ohio, una bicicleta, bicicleta eléctrica, ciclomotor, motoneta de 150 cc o menos o aparato de micromovilidad se puede estacionar en la acera si no estorba a la gente que camina.","p":"Correcto. Los ciclomotores y motonetas pequeñas pueden estacionarse en la acera si no estorban."},"ref":{"doc":"OH","page":"§5"}},{"id":"oh-128","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, besides an insurance policy or a bond, how else can you meet the financial responsibility law?","o":["Sign a promise to pay for any damage","Keep $5,000 in a bank account","Deposit $10,000 with a court","Deposit $30,000 with the Registrar"],"h1":"It is a cash deposit with the state.","h2":"In Ohio, you can meet the financial responsibility law by depositing $30,000 with the Registrar and showing you have no unpaid judgments.","p":"Right. A $30,000 deposit with the Registrar also works."},"es":{"q":"En Ohio, además de una póliza de seguro o una fianza, ¿de qué otra forma puede cumplir con la ley de responsabilidad financiera?","o":["Firmar una promesa de pagar cualquier daño","Tener $5,000 en una cuenta de banco","Depositar $10,000 en un tribunal","Depositar $30,000 con el Registrador"],"h1":"Es un depósito de dinero con el estado.","h2":"En Ohio, puede cumplir con la ley de responsabilidad financiera depositando $30,000 con el Registrador y mostrando que no tiene fallos judiciales sin pagar.","p":"Correcto. Un depósito de $30,000 con el Registrador también sirve."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-129","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, after an OVI arrest, you take the officer's chemical test. What right do you also have?","o":["To get your own independent chemical test, at your own cost","To retake the officer's test until you pass","To have the result erased if it is your first time","To keep your license until your court date"],"h1":"You may get a second test from someone else, but you pay for it.","h2":"In Ohio, after an OVI arrest you have the right to an independent chemical test, paid for by you.","p":"Right. You may get your own test at your own cost."},"es":{"q":"En Ohio, después de un arresto por OVI, usted toma la prueba química del oficial. ¿Qué otro derecho tiene?","o":["Hacerse su propia prueba química independiente, pagada por usted","Repetir la prueba del oficial hasta pasarla","Que borren el resultado si es la primera vez","Quedarse con su licencia hasta la fecha del tribunal"],"h1":"Puede hacerse una segunda prueba con otra persona, pero usted la paga.","h2":"En Ohio, después de un arresto por OVI usted tiene derecho a una prueba química independiente, pagada por usted.","p":"Correcto. Puede hacerse su propia prueba, pagada por usted."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-130","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a driver refuses the chemical test and is later found not guilty of OVI. What happens to the refusal suspension?","o":["It is canceled","It stays in place","It is cut in half","It is changed to points"],"h1":"The refusal is punished on its own.","h2":"In Ohio, the license suspension for refusing a chemical test stands even if the driver is later found not guilty of OVI.","p":"Right. The refusal suspension stays."},"es":{"q":"En Ohio, un conductor se niega a la prueba química y después lo declaran no culpable de OVI. ¿Qué pasa con la suspensión por negarse?","o":["Se cancela","Sigue vigente","Se reduce a la mitad","Se cambia por puntos"],"h1":"Negarse se castiga por sí solo.","h2":"En Ohio, la suspensión de licencia por negarse a la prueba química sigue vigente aunque después declaren al conductor no culpable de OVI.","p":"Correcto. La suspensión por negarse sigue."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-131","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a driver refuses the chemical test and has three or more earlier refusals or OVI convictions in the past 10 years. How long is the license suspended?","o":["Two years","One year","Five years","Three years"],"h1":"It is the longest refusal suspension.","h2":"In Ohio, a driver who refuses the test with three or more earlier refusals or OVI convictions in 10 years gets a five-year license suspension.","p":"Right. The suspension is five years."},"es":{"q":"En Ohio, un conductor se niega a la prueba química y tiene tres o más negativas o condenas por OVI anteriores en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia?","o":["Dos años","Un año","Cinco años","Tres años"],"h1":"Es la suspensión más larga por negarse.","h2":"En Ohio, un conductor que se niega a la prueba y tiene tres o más negativas o condenas por OVI anteriores en 10 años recibe una suspensión de licencia de cinco años.","p":"Correcto. La suspensión es de cinco años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-132","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a driver tests over the alcohol limit and has two earlier OVI convictions in the past 10 years. How long is the license suspended right away?","o":["Five years","90 days","One year","Two years"],"h1":"Each earlier conviction adds time.","h2":"In Ohio, a driver who tests over the limit with two earlier OVI convictions in 10 years gets a two-year administrative license suspension.","p":"Right. The suspension is two years."},"es":{"q":"En Ohio, un conductor da más del límite de alcohol y tiene dos condenas por OVI anteriores en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["Cinco años","90 días","Un año","Dos años"],"h1":"Cada condena anterior agrega tiempo.","h2":"En Ohio, un conductor que da más del límite y tiene dos condenas por OVI anteriores en 10 años recibe una suspensión administrativa de dos años.","p":"Correcto. La suspensión es de dos años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-133","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, what does the BMV do when a driver gets six points within two years?","o":["Sends a warning letter","Suspends the license for six months","Takes away the car's license plates","Nothing at all"],"h1":"It is a notice, not a suspension yet.","h2":"In Ohio, the BMV sends a warning letter to a driver who gets six points within two years.","p":"Right. Six points brings a warning letter."},"es":{"q":"En Ohio, ¿qué hace el BMV cuando un conductor acumula seis puntos en dos años?","o":["Le envía una carta de advertencia","Le suspende la licencia por seis meses","Le quita las placas al carro","Nada"],"h1":"Es un aviso, todavía no una suspensión.","h2":"En Ohio, el BMV envía una carta de advertencia al conductor que acumula seis puntos en dos años.","p":"Correcto. Seis puntos traen una carta de advertencia."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-134","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, what is an SR-22?","o":["A cheaper kind of car insurance","A form filed with the state that proves your insurance meets the minimum","A ticket for not wearing a seat belt","A permit for teen drivers"],"h1":"It is not a type of insurance.","h2":"In Ohio, an SR-22 is a certificate filed with the state that proves your car insurance meets the minimum required by law.","p":"Right. An SR-22 is a form that proves your insurance."},"es":{"q":"En Ohio, ¿qué es un SR-22?","o":["Un tipo de seguro de carro más barato","Un formulario que se presenta al estado y prueba que su seguro cumple el mínimo","Una multa por no usar el cinturón","Un permiso para conductores jóvenes"],"h1":"No es un tipo de seguro.","h2":"En Ohio, un SR-22 es un certificado que se presenta al estado y prueba que su seguro de carro cumple el mínimo que exige la ley.","p":"Correcto. Un SR-22 es un formulario que prueba su seguro."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-135","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, how many points are added for driving with willful or wanton disregard for the safety of people or property?","o":["6 points","2 points","4 points","12 points"],"h1":"It is more than a normal moving violation, but less than leaving a crash.","h2":"In Ohio, willful or wanton disregard for the safety of people or property adds 4 points.","p":"Right. It adds 4 points."},"es":{"q":"En Ohio, ¿cuántos puntos se agregan por manejar con desprecio intencional o temerario por la seguridad de personas o propiedad?","o":["6 puntos","2 puntos","4 puntos","12 puntos"],"h1":"Es más que una infracción de tránsito común, pero menos que irse de un choque.","h2":"En Ohio, manejar con desprecio intencional o temerario por la seguridad de personas o propiedad agrega 4 puntos.","p":"Correcto. Agrega 4 puntos."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-136","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a driver is convicted of driving while the license is suspended. Besides a fine, what else can happen?","o":["A free driving class","Only a warning letter","2 points and nothing more","One more year of license suspension"],"h1":"The license can be taken away for even longer.","h2":"In Ohio, a driver convicted of driving under suspension can get an extra one-year license suspension, besides a fine of up to $1,000.","p":"Right. Another year of suspension is possible."},"es":{"q":"En Ohio, condenan a un conductor por manejar con la licencia suspendida. Además de una multa, ¿qué más puede pasar?","o":["Una clase de manejo gratis","Solo una carta de advertencia","2 puntos y nada más","Un año más de suspensión de la licencia"],"h1":"Le pueden quitar la licencia por todavía más tiempo.","h2":"En Ohio, a un conductor condenado por manejar con la licencia suspendida le pueden dar un año más de suspensión, además de una multa de hasta $1,000.","p":"Correcto. Es posible otro año de suspensión."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-137","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, a pickup truck's open bed has no seats or seat belts. May a 12-year-old ride back there while the truck goes 40 mph?","o":["No, not when the truck goes faster than 25 mph","Yes, if an adult rides with them","Yes, on country roads","Yes, if the tailgate is closed"],"h1":"There is a speed limit for children under 16 riding in the bed.","h2":"In Ohio, a driver may not let anyone under 16 ride in an open truck bed when the truck goes faster than 25 mph, unless there is a secured seat with a belt or an emergency.","p":"Right. Not above 25 mph."},"es":{"q":"En Ohio, la caja abierta de una camioneta pickup no tiene asientos ni cinturones. ¿Puede un niño de 12 años ir ahí atrás mientras la camioneta va a 40 mph?","o":["No, no cuando la camioneta va a más de 25 mph","Sí, si un adulto va con él","Sí, en caminos del campo","Sí, si la puerta trasera está cerrada"],"h1":"Hay un límite de velocidad para menores de 16 años que van en la caja.","h2":"En Ohio, un conductor no puede dejar que una persona menor de 16 años vaya en la caja abierta de una camioneta cuando va a más de 25 mph, salvo que haya un asiento fijo con cinturón o una emergencia.","p":"Correcto. No a más de 25 mph."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-138","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a child is 10 years old and 5 feet tall. How must the child ride in a car?","o":["In a booster seat","Wearing a safety belt","In a child safety seat","No restraint is needed"],"h1":"The child is too old and too tall for a booster seat.","h2":"In Ohio, a child from age 8 to 15 must be buckled in with a safety belt.","p":"Right. The child must wear a safety belt."},"es":{"q":"En Ohio, un niño tiene 10 años y mide 5 pies. ¿Cómo debe viajar en un carro?","o":["En un asiento elevador (booster)","Con el cinturón de seguridad puesto","En un asiento de seguridad para niños","No necesita ninguna sujeción"],"h1":"El niño ya es muy grande y alto para un asiento elevador.","h2":"En Ohio, un niño de 8 a 15 años debe ir abrochado con el cinturón de seguridad.","p":"Correcto. El niño debe usar el cinturón de seguridad."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-139","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, a driver under 18 has served a license suspension. What must they do to drive again?","o":["Wait until they turn 18","Only pay a fee","Get a permit (TIPIC), finish a juvenile driver improvement program, and pass the driving test","Retake only the knowledge test"],"h1":"There are three steps, including a program and a test.","h2":"In Ohio, after a suspension a driver under 18 must get a TIPIC, complete an approved juvenile driver improvement program, and pass the driving test.","p":"Right. Permit, improvement program, and the driving test."},"es":{"q":"En Ohio, un conductor menor de 18 años cumplió una suspensión de licencia. ¿Qué debe hacer para volver a manejar?","o":["Esperar a cumplir 18 años","Solo pagar una cuota","Sacar un permiso (TIPIC), terminar un programa de mejoramiento para conductores jóvenes y aprobar el examen de manejo","Repetir solo el examen de conocimientos"],"h1":"Son tres pasos, entre ellos un programa y un examen.","h2":"En Ohio, después de una suspensión, un conductor menor de 18 años debe sacar un TIPIC, completar un programa aprobado de mejoramiento para conductores jóvenes y aprobar el examen de manejo.","p":"Correcto. Permiso, programa de mejoramiento y examen de manejo."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-140","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, the driver manual gives a car-length rule for following distance. What is it?","o":["One car length for every 20 mph","One car length for every 5 mph","Two car lengths at any speed","One car length for every 10 mph of speed"],"h1":"At 30 mph, it would be three car lengths.","h2":"In Ohio, the driver manual says to keep at least one vehicle length for every 10 mph of speed.","p":"Right. One car length for every 10 mph."},"es":{"q":"En Ohio, el manual da una regla en largos de carro para la distancia de seguimiento. ¿Cuál es?","o":["Un largo de carro por cada 20 mph","Un largo de carro por cada 5 mph","Dos largos de carro a cualquier velocidad","Un largo de carro por cada 10 mph de velocidad"],"h1":"A 30 mph, serían tres largos de carro.","h2":"En Ohio, el manual dice que debe dejar por lo menos un largo de vehículo por cada 10 mph de velocidad.","p":"Correcto. Un largo de carro por cada 10 mph."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-141","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, you follow a motorcycle at highway speed in heavy traffic. What following distance should you keep?","o":["Two seconds","At least four seconds","One second","Exactly three seconds"],"h1":"Conditions are less than ideal, so add time.","h2":"In Ohio, when conditions are less than ideal, such as higher speeds or heavy traffic, keep at least four seconds behind a motorcycle.","p":"Right. At least four seconds."},"es":{"q":"En Ohio, usted sigue a una motocicleta a velocidad de autopista con mucho tráfico. ¿Qué distancia debe dejar?","o":["Dos segundos","Por lo menos cuatro segundos","Un segundo","Exactamente tres segundos"],"h1":"Las condiciones no son ideales, así que agregue tiempo.","h2":"En Ohio, cuando las condiciones no son ideales, como a más velocidad o con mucho tráfico, deje por lo menos cuatro segundos detrás de una motocicleta.","p":"Correcto. Por lo menos cuatro segundos."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-143","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, why should you take extra care when you pass farm machinery?","o":["The operator must wave you past first","Farm machines may never be passed","Farm machines always turn right","The operator cannot hear vehicles coming up"],"h1":"Think about how loud a tractor is.","h2":"In Ohio, pass farm machinery with care, because its operator cannot hear vehicles coming.","p":"Right. The operator cannot hear you coming."},"es":{"q":"En Ohio, ¿por qué debe tener mucho cuidado al rebasar maquinaria agrícola?","o":["El operador primero debe hacerle señas para pasar","Nunca se puede rebasar maquinaria agrícola","La maquinaria agrícola siempre gira a la derecha","El operador no puede oír los vehículos que se acercan"],"h1":"Piense en lo ruidoso que es un tractor.","h2":"En Ohio, rebase la maquinaria agrícola con cuidado, porque el operador no puede oír los vehículos que se acercan.","p":"Correcto. El operador no lo oye venir."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-144","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a 15-year-old has a probationary moped license. When may they ride?","o":["Only in daylight","At any time","Only before 9 p.m.","Only with a parent riding along"],"h1":"Young moped riders may not ride in the dark.","h2":"In Ohio, probationary moped license holders aged 14 and 15 may ride only in daylight.","p":"Right. Only in daylight."},"es":{"q":"En Ohio, un joven de 15 años tiene una licencia provisional de ciclomotor. ¿Cuándo puede manejarlo?","o":["Solo de día","A cualquier hora","Solo antes de las 9 p.m.","Solo con uno de sus padres a bordo"],"h1":"Los jóvenes en ciclomotor no pueden manejar de noche.","h2":"En Ohio, quienes tienen una licencia provisional de ciclomotor a los 14 y 15 años solo pueden manejar de día.","p":"Correcto. Solo de día."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-145","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, how big is the course for the maneuverability part of the driving test?","o":["6 feet wide by 12 feet long","9 feet wide by 20 feet long","12 feet wide by 30 feet long","20 feet wide by 40 feet long"],"h1":"It is a little wider than a car and a bit longer than one.","h2":"In Ohio, the maneuverability test course is 9 feet by 20 feet, formed by four markers.","p":"Right. The course is 9 by 20 feet."},"es":{"q":"En Ohio, ¿qué tamaño tiene el recorrido de la parte de maniobras del examen de manejo?","o":["6 pies de ancho por 12 pies de largo","9 pies de ancho por 20 pies de largo","12 pies de ancho por 30 pies de largo","20 pies de ancho por 40 pies de largo"],"h1":"Es un poco más ancho que un carro y algo más largo que uno.","h2":"En Ohio, el recorrido del examen de maniobras mide 9 pies por 20 pies y lo forman cuatro marcadores.","p":"Correcto. El recorrido mide 9 por 20 pies."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-146","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, your driver's license expired last week. Is there a grace period to keep driving?","o":["Yes, 60 days","Yes, 30 days","No; driving on it risks a ticket","Yes, until your next birthday"],"h1":"It is your job to know when your license runs out.","h2":"In Ohio, there is no grace period for renewing a license, and driving after it expires risks a traffic ticket.","p":"Right. There is no grace period."},"es":{"q":"En Ohio, su licencia de conducir venció la semana pasada. ¿Hay un período de gracia para seguir manejando?","o":["Sí, 60 días","Sí, 30 días","No; si maneja con ella se arriesga a una multa","Sí, hasta su próximo cumpleaños"],"h1":"Es su responsabilidad saber cuándo vence su licencia.","h2":"En Ohio, no hay período de gracia para renovar la licencia, y manejar después de que vence lo expone a una multa de tránsito.","p":"Correcto. No hay período de gracia."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-147","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, an adult who is 25 fails the driving test. When can they skip the abbreviated adult driver training course before testing again?","o":["Never; there are no exceptions","If they wait 30 days","If they pay a higher fee","If they finished an approved driver education course within one year before the test"],"h1":"Recent training counts.","h2":"In Ohio, an adult who failed the driving test does not need the abbreviated course if they finished an approved driver education course within one year before the test.","p":"Right. Approved driver education within the past year is the exception."},"es":{"q":"En Ohio, un adulto de 25 años no aprueba el examen de manejo. ¿Cuándo puede saltarse el curso corto para adultos antes de volver a intentarlo?","o":["Nunca; no hay excepciones","Si espera 30 días","Si paga una cuota más alta","Si terminó un curso aprobado de educación vial en el año anterior al examen"],"h1":"Una capacitación reciente cuenta.","h2":"En Ohio, un adulto que no aprobó el examen de manejo no necesita el curso corto si terminó un curso aprobado de educación vial dentro del año anterior al examen.","p":"Correcto. La excepción es un curso aprobado en el último año."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-148","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, you choose a Standard driver license, not a Compliant one. What else will you need to board a domestic flight?","o":["A passport or another document the TSA accepts","Nothing else","A letter from the BMV","Your vehicle registration"],"h1":"The Standard card does not meet federal travel rules by itself.","h2":"In Ohio, a Standard license does not meet federal travel rules, so to fly you also need a passport or another document the TSA accepts.","p":"Right. You also need a passport or another TSA-approved document."},"es":{"q":"En Ohio, usted escoge una licencia Standard, no una Compliant. ¿Qué más necesitará para subir a un vuelo nacional?","o":["Un pasaporte u otro documento que acepte la TSA","Nada más","Una carta del BMV","El registro de su vehículo"],"h1":"La tarjeta Standard por sí sola no cumple las reglas federales de viaje.","h2":"En Ohio, una licencia Standard no cumple las reglas federales de viaje, así que para volar también necesita un pasaporte u otro documento que acepte la TSA.","p":"Correcto. También necesita un pasaporte u otro documento aceptado por la TSA."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-149","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, you are behind a large truck near a truck weigh station. Which lane does the driver manual say to avoid?","o":["The left lane","The right lane","The center lane","Any lane next to the median"],"h1":"Trucks may be coming back onto the road there.","h2":"In Ohio, avoid the right lane near truck weigh stations and on steep hills behind large vehicles, because trucks may be trying to get back into faster traffic.","p":"Right. Stay out of the right lane there."},"es":{"q":"En Ohio, usted va detrás de un camión grande cerca de una estación de pesaje de camiones. ¿Qué carril dice el manual que debe evitar?","o":["El carril izquierdo","El carril derecho","El carril del centro","Cualquier carril junto a la división central"],"h1":"Ahí los camiones pueden estar volviendo a la carretera.","h2":"En Ohio, evite el carril derecho cerca de las estaciones de pesaje y en cuestas empinadas detrás de vehículos grandes, porque los camiones pueden estar tratando de volver al tráfico más rápido.","p":"Correcto. Evite el carril derecho ahí."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-150","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a teen with a temporary instruction permit (TIPIC) is driving with a supervisor and two passengers. Who must wear a safety belt?","o":["The driver and every passenger","Only the driver","Only the driver and the front-seat supervisor","Only passengers under 15"],"h1":"Permit rules about belts are stricter than the adult rule.","h2":"In Ohio, when a permit holder drives, the driver and all passengers must wear safety belts, and there may not be more people than belts.","p":"Right. Everyone in the car must wear a belt."},"es":{"q":"En Ohio, un adolescente con permiso de aprendizaje (TIPIC) maneja con un supervisor y dos pasajeros. ¿Quién debe usar el cinturón de seguridad?","o":["El conductor y todos los pasajeros","Solo el conductor","Solo el conductor y el supervisor del asiento delantero","Solo los pasajeros menores de 15 años"],"h1":"Las reglas del permiso sobre cinturones son más estrictas que la regla para adultos.","h2":"En Ohio, cuando maneja alguien con permiso de aprendizaje, el conductor y todos los pasajeros deben usar el cinturón, y no puede haber más personas que cinturones.","p":"Correcto. Todos en el carro deben usar el cinturón."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-151","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a temporary resident who is 30 has a valid, current driver's license from Japan. What does Ohio require to get an Ohio license?","o":["Take 24 hours of class and 8 hours with a driving school","Show the Japanese license when applying; driver education and the 50 hours are not required","Hold a permit for six months first","Nothing; the Japanese license can be used in Ohio forever"],"h1":"Ohio has a short list of countries with a special arrangement.","h2":"In Ohio, a temporary resident with a current license from Canada, France, Germany, Japan, South Korea or Taiwan is exempt from the driver education and practice-hour rules and may get an Ohio license by showing that license.","p":"Right. They show their current license and skip driver education and the 50 hours."},"es":{"q":"En Ohio, un residente temporal de 30 años tiene una licencia de manejo vigente de Japón. ¿Qué exige Ohio para obtener una licencia de Ohio?","o":["Tomar 24 horas de clase y 8 horas con una escuela de manejo","Mostrar la licencia japonesa al solicitar; no se exigen la educación vial ni las 50 horas","Tener primero un permiso por seis meses","Nada; puede usar la licencia japonesa en Ohio para siempre"],"h1":"Ohio tiene una lista corta de países con un acuerdo especial.","h2":"En Ohio, un residente temporal con licencia vigente de Canadá, Francia, Alemania, Japón, Corea del Sur o Taiwán no tiene que cumplir los requisitos de educación vial ni de horas de práctica, y puede obtener una licencia de Ohio mostrando esa licencia.","p":"Correcto. Muestra su licencia vigente y no necesita la educación vial ni las 50 horas."},"ref":{"doc":"OH","page":"§1"}},{"id":"oh-152","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, when your seat is set correctly, how high should the top of the steering wheel be?","o":["Level with the top of your head","Level with your eyes","No higher than the top of your shoulders","Level with your belt"],"h1":"Think about the air bag in the middle of the wheel.","h2":"In Ohio, the driver manual says the top of the steering wheel should be no higher than the top of your shoulders and below your chin.","p":"Right. The top of the wheel should not be higher than your shoulders."},"es":{"q":"En Ohio, cuando su asiento está bien ajustado, ¿a qué altura debe quedar la parte de arriba del volante?","o":["A la altura de la parte de arriba de su cabeza","A la altura de sus ojos","No más alta que la parte de arriba de sus hombros","A la altura de su cinturón"],"h1":"Piense en la bolsa de aire que está en el centro del volante.","h2":"En Ohio, el manual dice que la parte de arriba del volante no debe quedar más alta que la parte de arriba de sus hombros, y debe quedar por debajo de su barbilla.","p":"Correcto. La parte de arriba del volante no debe pasar de sus hombros."},"ref":{"doc":"OH","page":"§2"}},{"id":"oh-153","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, you passed the vision screening wearing your glasses. What does this mean for your license?","o":["You may drive only in daylight","Nothing; glasses are only needed at night","You must retake the vision screening every year","It shows a vision restriction, and you must always wear your glasses or contacts to drive"],"h1":"The result is printed on your license.","h2":"In Ohio, if you pass the vision screening with corrective lenses, your license shows a vision restriction and you must always wear your glasses or contacts when you drive.","p":"Right. You must always wear your corrective lenses to drive."},"es":{"q":"En Ohio, usted pasó la prueba de la vista con sus lentes puestos. ¿Qué significa esto para su licencia?","o":["Solo puede manejar de día","Nada; los lentes solo se necesitan de noche","Debe repetir la prueba de la vista cada año","La licencia muestra una restricción de la vista, y siempre debe usar sus lentes o lentes de contacto para manejar"],"h1":"El resultado queda impreso en su licencia.","h2":"En Ohio, si pasa la prueba de la vista con lentes correctivos, su licencia muestra una restricción de la vista y siempre debe usar sus lentes o lentes de contacto al manejar.","p":"Correcto. Siempre debe usar sus lentes correctivos para manejar."},"ref":{"doc":"OH","page":"§3"}},{"id":"oh-154","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, which of these is a time when you must be able to show proof of insurance?","o":["Only when you register your vehicle","When a police officer gives you a traffic ticket","Only after a crash where someone is hurt","Only if you are under 18"],"h1":"It is needed in several everyday situations, not just one.","h2":"In Ohio, you must show proof of insurance whenever police give you a traffic ticket, at vehicle inspection stops, in traffic court, after a crash with more than $400 in damage, and when the BMV asks.","p":"Right. A traffic ticket is one of the times you must show it."},"es":{"q":"En Ohio, ¿en cuál de estos momentos debe poder mostrar prueba de seguro?","o":["Solo cuando registra su vehículo","Cuando un policía le da una multa de tránsito","Solo después de un choque en el que alguien sale herido","Solo si es menor de 18 años"],"h1":"Se necesita en varias situaciones comunes, no en una sola.","h2":"En Ohio, debe mostrar prueba de seguro cada vez que la policía le da una multa de tránsito, en los puntos de inspección de vehículos, en la corte de tránsito, después de un choque con más de $400 en daños y cuando el BMV lo pide.","p":"Correcto. Una multa de tránsito es uno de los momentos en que debe mostrarla."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-155","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a driver refuses the chemical test after an OVI arrest. They have two earlier refusals or OVI convictions in the past 10 years. How long is the license suspended?","o":["Six months","One year","Three years","Ten years"],"h1":"Each earlier refusal or conviction adds time.","h2":"In Ohio, refusing the chemical test with two earlier refusals or OVI convictions in the past 10 years brings a three-year license suspension.","p":"Right. The suspension is three years."},"es":{"q":"En Ohio, un conductor se niega a la prueba química después de un arresto por OVI. Tiene dos negativas o condenas por OVI anteriores en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia?","o":["Seis meses","Un año","Tres años","Diez años"],"h1":"Cada negativa o condena anterior agrega tiempo.","h2":"En Ohio, negarse a la prueba química con dos negativas o condenas por OVI anteriores en los últimos 10 años trae una suspensión de la licencia de tres años.","p":"Correcto. La suspensión es de tres años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-156","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a driver tests over the alcohol limit and has three or more earlier OVI convictions in the past 10 years. How long is the license suspended right away?","o":["Lifetime","90 days","One year","Three years"],"h1":"This is the longest step for testing over the limit.","h2":"In Ohio, a driver who tests over the limit with three or more earlier OVI convictions in the past 10 years gets an immediate three-year administrative license suspension.","p":"Right. The suspension starts right away and lasts three years."},"es":{"q":"En Ohio, un conductor da un resultado por encima del límite de alcohol y tiene tres o más condenas por OVI anteriores en los últimos 10 años. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["De por vida","90 días","Un año","Tres años"],"h1":"Este es el paso más largo para quien da por encima del límite.","h2":"En Ohio, un conductor que da por encima del límite y tiene tres o más condenas por OVI anteriores en los últimos 10 años recibe de inmediato una suspensión administrativa de la licencia de tres años.","p":"Correcto. La suspensión empieza de inmediato y dura tres años."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-157","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a driver is convicted of running a stop sign, an ordinary moving violation. How many points go on the license?","o":["2 points","1 point","4 points","6 points"],"h1":"It is the smallest number on Ohio's point list.","h2":"In Ohio, an ordinary moving violation adds 2 points to the driver's license.","p":"Right. An ordinary moving violation adds 2 points."},"es":{"q":"En Ohio, a un conductor lo condenan por no parar en una señal de alto, una infracción de tránsito común. ¿Cuántos puntos se agregan a su licencia?","o":["2 puntos","1 punto","4 puntos","6 puntos"],"h1":"Es el número más bajo de la lista de puntos de Ohio.","h2":"En Ohio, una infracción de tránsito común agrega 2 puntos a la licencia de manejo.","p":"Correcto. Una infracción común agrega 2 puntos."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-158","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a child is 5 years old but weighs only 35 pounds. How must the child ride in a car?","o":["In a booster seat","In a child safety seat","With a regular safety belt","On an adult's lap"],"h1":"Weight counts, not only age.","h2":"In Ohio, a child who is under 4 years old or weighs less than 40 pounds must ride in a child safety seat.","p":"Right. Under 40 pounds means a child safety seat."},"es":{"q":"En Ohio, un niño tiene 5 años pero pesa solo 35 libras. ¿Cómo debe viajar en el carro?","o":["En un asiento elevado (booster)","En un asiento de seguridad para niños","Con un cinturón de seguridad normal","En las piernas de un adulto"],"h1":"Cuenta el peso, no solo la edad.","h2":"En Ohio, un niño menor de 4 años o que pesa menos de 40 libras debe viajar en un asiento de seguridad para niños.","p":"Correcto. Menos de 40 libras significa asiento de seguridad para niños."},"ref":{"doc":"OH","page":"§6"}},{"id":"oh-159","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, a police officer pulls you over. After you stop and put the car in park, what should you do?","o":["Search the glove box for papers before the officer arrives","Get out and walk to the police car","Turn off the engine, lower the window, stay in the car and keep your hands on the wheel","Keep the engine running and take off your safety belt"],"h1":"The officer should be able to see your hands.","h2":"In Ohio, when you are pulled over, turn off the engine, lower the window, stay in the car with your belt on, and keep your hands on the steering wheel where the officer can see them.","p":"Right. Stay in the car with your hands on the wheel."},"es":{"q":"En Ohio, un policía le indica que se detenga. Después de parar y poner el carro en estacionamiento (park), ¿qué debe hacer?","o":["Buscar papeles en la guantera antes de que llegue el policía","Bajarse y caminar hacia la patrulla","Apagar el motor, bajar la ventana, quedarse en el carro y mantener las manos en el volante","Dejar el motor encendido y quitarse el cinturón"],"h1":"El policía debe poder ver sus manos.","h2":"En Ohio, cuando la policía lo detiene, apague el motor, baje la ventana, quédese en el carro con el cinturón puesto y mantenga las manos en el volante, donde el policía las pueda ver.","p":"Correcto. Quédese en el carro con las manos en el volante."},"ref":{"doc":"OH","page":"§7"}},{"id":"oh-160","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, you see a child alone in a hot, locked car. The child is not responding. What does the driver manual say to do?","o":["Call 911 and get the child out, breaking a window if needed","Wait by the car until the parent comes back","Leave a note on the windshield for the parent","Call 911, but never touch the car"],"h1":"Ohio has a Good Samaritan law that protects people who help.","h2":"In Ohio, if a child alone in a car is in distress or not responding, call 911 and take action to get the child out, even breaking a window if needed; Good Samaritan laws protect people who help in an emergency.","p":"Right. Call 911 and get the child out, even by breaking a window."},"es":{"q":"En Ohio, usted ve a un niño solo en un carro caliente y cerrado con llave. El niño no responde. ¿Qué dice el manual que haga?","o":["Llamar al 911 y sacar al niño, rompiendo una ventana si es necesario","Esperar junto al carro hasta que vuelva el padre o la madre","Dejar una nota en el parabrisas para el padre o la madre","Llamar al 911, pero nunca tocar el carro"],"h1":"Ohio tiene una ley del Buen Samaritano que protege a quien ayuda.","h2":"En Ohio, si un niño solo en un carro está en peligro o no responde, llame al 911 y actúe para sacarlo, incluso rompiendo una ventana si es necesario; las leyes del Buen Samaritano protegen a quien ayuda en una emergencia.","p":"Correcto. Llame al 911 y saque al niño, aunque tenga que romper una ventana."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-161","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, you are following a bus that carries passengers. Besides its size, why does the driver manual say to leave extra space?","o":["It never uses brake lights","It must stop at railroad crossings","It always drives faster than cars","It is not allowed to change lanes"],"h1":"Think about where some vehicles must always stop.","h2":"In Ohio, the driver manual says to leave more following distance behind vehicles that must stop at railroad crossings, such as buses and trucks carrying hazardous materials.","p":"Right. It must stop at railroad crossings, so leave more room."},"es":{"q":"En Ohio, usted va detrás de un autobús que lleva pasajeros. Además de su tamaño, ¿por qué dice el manual que debe dejar más espacio?","o":["Nunca usa las luces de freno","Debe parar en los cruces de ferrocarril","Siempre va más rápido que los carros","No puede cambiar de carril"],"h1":"Piense en dónde algunos vehículos siempre deben parar.","h2":"En Ohio, el manual dice que deje más distancia detrás de los vehículos que deben parar en los cruces de ferrocarril, como los autobuses y los camiones que llevan materiales peligrosos.","p":"Correcto. Debe parar en los cruces de ferrocarril, así que deje más espacio."},"ref":{"doc":"OH","page":"§8"}},{"id":"oh-162","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, may you drive side by side with a motorcycle in the same lane?","o":["Yes, but only on the freeway","Yes, if the lane is wide enough","No; give the motorcycle a full lane width","Yes, if the motorcycle is going slowly"],"h1":"The rider needs room to react to traffic.","h2":"In Ohio, you must allow a motorcyclist a full lane width, because the rider needs that space to react to other traffic.","p":"Right. A motorcycle gets the whole lane."},"es":{"q":"En Ohio, ¿puede manejar al lado de una motocicleta en el mismo carril?","o":["Sí, pero solo en la autopista","Sí, si el carril es bastante ancho","No; deje a la motocicleta todo el ancho del carril","Sí, si la motocicleta va despacio"],"h1":"El motociclista necesita espacio para reaccionar al tráfico.","h2":"En Ohio, debe dejar a la motocicleta todo el ancho del carril, porque el motociclista necesita ese espacio para reaccionar al resto del tráfico.","p":"Correcto. La motocicleta tiene derecho a todo el carril."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-163","scope":"OH","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Ohio, a horse-drawn buggy is on a rural road ahead of you. What rights does it have on the road?","o":["It has the right-of-way everywhere","None; it must always pull off the road for cars","It may use the road only in daylight","The same rights as a motor vehicle, and it must follow the same rules"],"h1":"Think of it like any other road user.","h2":"In Ohio, animal-drawn vehicles and horseback riders have the same rights as motor vehicles and must follow the same rules of the road.","p":"Right. It has the same rights and follows the same rules."},"es":{"q":"En Ohio, un coche tirado por caballos va delante de usted en un camino rural. ¿Qué derechos tiene en la vía?","o":["Tiene el derecho de paso en todas partes","Ninguno; siempre debe salirse del camino para los carros","Solo puede usar la vía de día","Los mismos derechos que un vehículo de motor, y debe seguir las mismas reglas"],"h1":"Piense en él como en cualquier otro usuario de la vía.","h2":"En Ohio, los vehículos tirados por animales y las personas a caballo tienen los mismos derechos que los vehículos de motor y deben seguir las mismas reglas de tránsito.","p":"Correcto. Tiene los mismos derechos y sigue las mismas reglas."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-164","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, you are driving slower than the other traffic on a road with more than one lane in your direction. Where must you drive?","o":["In the right lane, or as close as you can to the right edge","In the left lane","In the center turn lane","In any lane, as long as you use your flashers"],"h1":"Leave room for faster drivers to pass.","h2":"In Ohio, vehicles moving slower than the flow of traffic must use the right lane or stay as close as possible to the right curb or edge of the road.","p":"Right. Slower traffic keeps to the right."},"es":{"q":"En Ohio, usted maneja más despacio que el resto del tráfico en una vía con más de un carril en su dirección. ¿Por dónde debe ir?","o":["Por el carril derecho, o lo más cerca posible del borde derecho","Por el carril izquierdo","Por el carril central de vuelta","Por cualquier carril, si usa las luces intermitentes"],"h1":"Deje espacio para que pasen los conductores más rápidos.","h2":"En Ohio, los vehículos que van más despacio que el tráfico deben usar el carril derecho o ir lo más cerca posible de la acera o del borde derecho de la vía.","p":"Correcto. El tráfico lento va por la derecha."},"ref":{"doc":"OH","page":"§9"}},{"id":"oh-165","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, your engine shuts off while you are driving. What happens to the steering?","o":["It locks and cannot turn at all","It gets harder to turn, but you can still turn it","It becomes easier to turn","Nothing changes"],"h1":"Hold on firmly; the wheel still works.","h2":"In Ohio, if the engine shuts off while you drive, the steering wheel may be hard to turn but you can still turn it, so grip it firmly, brake with steady pressure and pull off the road.","p":"Right. It is harder to turn, but it still turns."},"es":{"q":"En Ohio, el motor se apaga mientras usted maneja. ¿Qué pasa con el volante?","o":["Se bloquea y no gira para nada","Cuesta más girarlo, pero todavía se puede girar","Se vuelve más fácil de girar","No cambia nada"],"h1":"Agárrelo con firmeza; el volante todavía funciona.","h2":"En Ohio, si el motor se apaga mientras maneja, el volante puede costar más de girar, pero todavía se puede girar; agárrelo con firmeza, frene con presión constante y salga de la vía.","p":"Correcto. Cuesta más girarlo, pero sí gira."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-166","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, your car breaks down. You get it off the road, turn on the flashers and set out flares. Where does the driver manual say to wait?","o":["Walking along the road to find help","Standing behind the car to wave at traffic","In your vehicle, until help arrives","Standing in front of the car"],"h1":"The manual's last step is about where you stay.","h2":"In Ohio, after a breakdown, get the car off the road, turn on the emergency flashers, warn traffic if you can, and stay in your vehicle until help arrives.","p":"Right. Stay in your vehicle until help comes."},"es":{"q":"En Ohio, su carro se descompone. Usted lo saca de la vía, prende las luces intermitentes y pone bengalas. ¿Dónde dice el manual que debe esperar?","o":["Caminando por la orilla de la vía para buscar ayuda","De pie detrás del carro, haciendo señas al tráfico","Dentro de su vehículo, hasta que llegue ayuda","De pie delante del carro"],"h1":"El último paso del manual es sobre dónde quedarse.","h2":"En Ohio, cuando el carro se descompone, sáquelo de la vía, prenda las luces intermitentes, avise al tráfico si puede y quédese dentro de su vehículo hasta que llegue ayuda.","p":"Correcto. Quédese en su vehículo hasta que llegue ayuda."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-167","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, you back into a parked car and no one is in it. What must you do?","o":["Report it only if the damage is over $1,000","Drive away; no one saw it","Wait at the scene for 10 minutes, then leave","Report the crash to police or leave your name and information on the car"],"h1":"The owner must be able to find you.","h2":"In Ohio, if you hit an unattended vehicle, you must report the crash to police or leave your name and information securely on that vehicle.","p":"Right. Report it to police or leave your information on the car."},"es":{"q":"En Ohio, usted choca de reversa contra un carro estacionado y no hay nadie adentro. ¿Qué debe hacer?","o":["Reportarlo solo si el daño pasa de $1,000","Irse; nadie lo vio","Esperar 10 minutos en el lugar y luego irse","Reportar el choque a la policía o dejar su nombre y sus datos en el carro"],"h1":"El dueño tiene que poder encontrarlo.","h2":"En Ohio, si choca contra un vehículo sin nadie adentro, debe reportar el choque a la policía o dejar su nombre y sus datos bien sujetos en ese vehículo.","p":"Correcto. Repórtelo a la policía o deje sus datos en el carro."},"ref":{"doc":"OH","page":"§10"}},{"id":"oh-168","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, your car has an automatic parking feature. What must you do with it for the driving test?","o":["Turn it off; automated assistance tools must be disabled","Use it for the parking part of the test","Use it only if the examiner says so","Nothing; it does not matter"],"h1":"The examiner wants to see your own skills.","h2":"In Ohio, automated assistance tools such as automatic parking must be turned off for the driving test.","p":"Right. It must be turned off for the test."},"es":{"q":"En Ohio, su carro tiene una función de estacionamiento automático. ¿Qué debe hacer con ella en el examen de manejo?","o":["Apagarla; las ayudas automáticas deben estar desactivadas","Usarla en la parte de estacionar del examen","Usarla solo si el examinador lo dice","Nada; no importa"],"h1":"El examinador quiere ver sus propias destrezas.","h2":"En Ohio, las ayudas automáticas, como el estacionamiento automático, deben estar desactivadas durante el examen de manejo.","p":"Correcto. Debe estar apagada durante el examen."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-169","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, during the maneuverability test, you run over and knock down one of the markers. What happens?","o":["You lose a few points but keep going","You fail the test right away","You may start that part again","Nothing, if you finish the course"],"h1":"Bumping a marker costs points; knocking one down is worse.","h2":"In Ohio, running over or knocking down a marker during the maneuverability test is an immediate failure.","p":"Right. Knocking down a marker is an automatic fail."},"es":{"q":"En Ohio, durante la prueba de maniobras, usted pasa por encima de uno de los marcadores y lo tumba. ¿Qué pasa?","o":["Pierde algunos puntos y sigue","Reprueba el examen de inmediato","Puede empezar esa parte otra vez","Nada, si termina el recorrido"],"h1":"Tocar un marcador quita puntos; tumbarlo es peor.","h2":"En Ohio, pasar por encima de un marcador o tumbarlo durante la prueba de maniobras significa reprobar de inmediato.","p":"Correcto. Tumbar un marcador es reprobar de inmediato."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-170","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, an adult takes the Abbreviated Adult Driver Training Course through a driving school. After the 4-hour class, how much driving instruction with the school is required?","o":["24 hours","8 hours","4 hours","50 hours"],"h1":"It is much less than the 24-hour option with a licensed adult.","h2":"In Ohio, one option for the Abbreviated Adult Driver Training Course is a 4-hour class followed by 4 hours of behind-the-wheel instruction from a licensed driving school.","p":"Right. Four hours of driving with the school."},"es":{"q":"En Ohio, un adulto toma el curso abreviado de manejo para adultos con una escuela de manejo. Después de la clase de 4 horas, ¿cuántas horas de práctica al volante con la escuela se exigen?","o":["24 horas","8 horas","4 horas","50 horas"],"h1":"Es mucho menos que la opción de 24 horas con un adulto con licencia.","h2":"En Ohio, una opción del curso abreviado para adultos es una clase de 4 horas seguida de 4 horas de práctica al volante con una escuela de manejo con licencia.","p":"Correcto. Cuatro horas al volante con la escuela."},"ref":{"doc":"OH","page":"§11"}},{"id":"oh-171","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, a 19-year-old's license expires on the 21st birthday. How must they renew it?","o":["They do not need to renew it","Online only","By mail only","In person"],"h1":"Online renewal is not an option at this age.","h2":"In Ohio, a license held by someone under 21 expires on the 21st birthday and must be renewed in person.","p":"Right. It must be renewed in person."},"es":{"q":"En Ohio, la licencia de una persona de 19 años vence el día que cumple 21. ¿Cómo debe renovarla?","o":["No necesita renovarla","Solo por internet","Solo por correo","En persona"],"h1":"A esta edad, la renovación por internet no es una opción.","h2":"En Ohio, la licencia de una persona menor de 21 años vence el día que cumple 21 y se debe renovar en persona.","p":"Correcto. Se debe renovar en persona."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-172","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, a parent co-signed a 16-year-old's license and now wants to take back that approval. What can the parent do?","o":["Mail the teen's license (or permit) or a notarized letter to the BMV asking to cancel it","Nothing; the approval lasts until the teen turns 18","Call the police and report the teen","Ask the teen's school to hold the license"],"h1":"The co-signer can cancel at any time by writing to the BMV.","h2":"In Ohio, a co-signer can cancel a minor's license at any time by mailing the minor's license or permit, or a notarized letter asking for cancellation, to the BMV; this also ends the co-signer's liability.","p":"Right. Mail the license or a notarized letter to the BMV."},"es":{"q":"En Ohio, un padre firmó como cofirmante la licencia de su hijo de 16 años y ahora quiere retirar esa aprobación. ¿Qué puede hacer?","o":["Enviar por correo al BMV la licencia (o el permiso) del joven o una carta notariada pidiendo cancelarla","Nada; la aprobación dura hasta que el joven cumpla 18 años","Llamar a la policía y denunciar al joven","Pedir a la escuela del joven que guarde la licencia"],"h1":"El cofirmante puede cancelar en cualquier momento escribiendo al BMV.","h2":"En Ohio, un cofirmante puede cancelar en cualquier momento la licencia de un menor enviando por correo al BMV la licencia o el permiso del menor, o una carta notariada que pida la cancelación; así también termina su responsabilidad.","p":"Correcto. Envíe la licencia o una carta notariada al BMV."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-173","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, which commercial license class covers a single vehicle with a weight rating of 26,001 pounds or more?","o":["Class A","Class B","Class C","Class D"],"h1":"Class A is for combinations, such as a truck pulling a heavy trailer.","h2":"In Ohio, a Class B commercial license covers a single vehicle with a gross vehicle weight rating of 26,001 pounds or more.","p":"Right. That is Class B."},"es":{"q":"En Ohio, ¿qué clase de licencia comercial cubre un solo vehículo con un peso nominal de 26,001 libras o más?","o":["Clase A","Clase B","Clase C","Clase D"],"h1":"La Clase A es para combinaciones, como un camión que jala un remolque pesado.","h2":"En Ohio, la licencia comercial Clase B cubre un solo vehículo con un peso bruto nominal de 26,001 libras o más.","p":"Correcto. Es la Clase B."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-174","scope":"OH","cat":"licensing","sign":null,"c":2,"en":{"q":"In Ohio, what is the largest engine a moped can have?","o":["150 cc","100 cc","50 cc","250 cc"],"h1":"Motor scooters start above this size.","h2":"In Ohio, a moped has a helper motor of not more than 50 cc.","p":"Right. A moped's engine is 50 cc or less."},"es":{"q":"En Ohio, ¿cuál es el motor más grande que puede tener un ciclomotor (moped)?","o":["150 cc","100 cc","50 cc","250 cc"],"h1":"Las motonetas (scooters) empiezan por encima de este tamaño.","h2":"En Ohio, un ciclomotor (moped) tiene un motor auxiliar de no más de 50 cc.","p":"Correcto. El motor de un moped es de 50 cc o menos."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-175","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, you already have a regular driver's license. Do you need a separate moped license to ride a moped?","o":["Only to ride at night","Yes, always","Yes, unless you are over 65","No; your driver's license lets you ride a moped"],"h1":"The moped license is meant for people who do not drive cars.","h2":"In Ohio, a moped license is not needed if you already have a driver's license, because a Class D license lets you operate a moped.","p":"Right. Your driver's license covers a moped."},"es":{"q":"En Ohio, usted ya tiene una licencia de manejo normal. ¿Necesita una licencia aparte para manejar un ciclomotor (moped)?","o":["Solo para manejar de noche","Sí, siempre","Sí, a menos que tenga más de 65 años","No; su licencia de manejo le permite manejar un moped"],"h1":"La licencia de moped es para personas que no manejan carros.","h2":"En Ohio, no se necesita licencia de moped si ya tiene licencia de manejo, porque la licencia Clase D le permite manejar un moped.","p":"Correcto. Su licencia de manejo cubre el moped."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-176","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, your motorcycle endorsement is for three-wheeled motorcycles. What may you ride with it?","o":["Only a three-wheeled motorcycle","Any motorcycle, two or three wheels","Any motorcycle or motor scooter","Only a motor scooter"],"h1":"Only the two-wheel endorsement covers more than one type.","h2":"In Ohio, a three-wheeled motorcycle endorsement allows you to ride only three-wheeled motorcycles, while a two-wheeled endorsement covers two- and three-wheeled motorcycles and scooters.","p":"Right. Only three-wheeled motorcycles."},"es":{"q":"En Ohio, su autorización (endorsement) de motocicleta es para motocicletas de tres ruedas. ¿Qué puede manejar con ella?","o":["Solo una motocicleta de tres ruedas","Cualquier motocicleta, de dos o tres ruedas","Cualquier motocicleta o motoneta (scooter)","Solo una motoneta (scooter)"],"h1":"Solo la autorización de dos ruedas cubre más de un tipo.","h2":"En Ohio, la autorización para motocicletas de tres ruedas solo le permite manejar motocicletas de tres ruedas, mientras que la de dos ruedas cubre motocicletas de dos y tres ruedas y motonetas.","p":"Correcto. Solo motocicletas de tres ruedas."},"ref":{"doc":"OH","page":"§12"}},{"id":"oh-177","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, which of these makes a newcomer an Ohio resident who needs an Ohio license?","o":["Staying in a hotel for a week","Taking a job in Ohio","Visiting family for a holiday","Driving through Ohio on a trip"],"h1":"Work, a lease, a home or school for your children all count.","h2":"In Ohio, you become a resident once you are employed, sign a lease, buy a home or enroll children in school, and then you must get an Ohio license within 30 days.","p":"Right. Taking a job in Ohio makes you a resident."},"es":{"q":"En Ohio, ¿cuál de estas cosas convierte a un recién llegado en residente de Ohio que necesita licencia de Ohio?","o":["Quedarse una semana en un hotel","Empezar a trabajar en Ohio","Visitar a la familia en un día festivo","Cruzar Ohio en un viaje"],"h1":"Cuentan el trabajo, un contrato de alquiler, una casa o la escuela de sus hijos.","h2":"En Ohio, usted es residente cuando empieza a trabajar, firma un contrato de alquiler, compra una casa o inscribe a sus hijos en la escuela, y luego debe obtener una licencia de Ohio dentro de 30 días.","p":"Correcto. Empezar a trabajar en Ohio lo hace residente."},"ref":{"doc":"OH","page":"§13"}},{"id":"oh-178","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, how close may you park to a stop sign or a traffic signal, on the side you approach it from?","o":["No closer than 15 feet","No closer than 10 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"It is more than the fire hydrant distance.","h2":"In Ohio, state law forbids parking within 30 feet of a stop sign, yield sign or traffic signal on the approach to it.","p":"Right. Stay at least 30 feet away."},"es":{"q":"En Ohio, ¿qué tan cerca puede estacionarse de una señal de alto o de un semáforo, del lado por donde se llega a ellos?","o":["No más cerca de 15 pies","No más cerca de 10 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Es más que la distancia de un hidrante.","h2":"En Ohio, la ley prohíbe estacionarse a menos de 30 pies de una señal de alto, de ceda el paso o de un semáforo, del lado por donde se llega a ellos.","p":"Correcto. Quédese al menos a 30 pies."},"ref":{"doc":"OH","page":null}},{"id":"oh-179","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, how close may you park to the nearest rail of a railroad crossing?","o":["No closer than 100 feet","No closer than 15 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"It is the farthest of the parking distances in Ohio law.","h2":"In Ohio, state law forbids parking within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the nearest rail."},"es":{"q":"En Ohio, ¿qué tan cerca puede estacionarse del riel más cercano de un cruce de ferrocarril?","o":["No más cerca de 100 pies","No más cerca de 15 pies","No más cerca de 20 pies","No más cerca de 50 pies"],"h1":"Es la mayor de las distancias para estacionar en la ley de Ohio.","h2":"En Ohio, la ley prohíbe estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese al menos a 50 pies del riel más cercano."},"ref":{"doc":"OH","page":null}},{"id":"oh-180","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, how close may you park to the driveway entrance of a fire station, on the same side of the street?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 10 feet","No closer than 100 feet"],"h1":"Fire trucks need room to pull out of the station.","h2":"In Ohio, state law forbids parking within 20 feet of a fire station driveway entrance, and within 75 feet on the opposite side of the street when signs are posted.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Ohio, ¿qué tan cerca puede estacionarse de la entrada de vehículos de una estación de bomberos, del mismo lado de la calle?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 100 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir de la estación.","h2":"En Ohio, la ley prohíbe estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos, y a menos de 75 pies en el lado opuesto de la calle cuando hay señales.","p":"Correcto. Quédese al menos a 20 pies."},"ref":{"doc":"OH","page":null}},{"id":"oh-181","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, you drive on a two-lane highway outside any city or village, and no speed limit sign is posted. What is the speed limit?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"It is the classic highway limit used in many states.","h2":"In Ohio, the speed limit on highways outside cities and villages is 55 mph unless a different limit is posted.","p":"Right. It is 55 mph."},"es":{"q":"En Ohio, usted maneja por una carretera de dos carriles fuera de cualquier ciudad o pueblo, y no hay señal de límite de velocidad. ¿Cuál es el límite?","o":["45 mph","55 mph","65 mph","70 mph"],"h1":"Es el límite clásico de carretera en muchos estados.","h2":"En Ohio, el límite de velocidad en las carreteras fuera de ciudades y pueblos es de 55 mph, a menos que una señal indique otro.","p":"Correcto. Es 55 mph."},"ref":{"doc":"OH","page":null}},{"id":"oh-182","scope":"OH","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Ohio, you drive on a state route through a built-up part of a city, but outside the business district. No other limit is posted. What is the speed limit?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"It is higher than the limit on ordinary city streets.","h2":"In Ohio, the speed limit on state routes or through highways inside a city or village, outside business districts, is 35 mph unless another limit is posted.","p":"Right. It is 35 mph."},"es":{"q":"En Ohio, usted maneja por una ruta estatal que pasa por una parte poblada de una ciudad, pero fuera de la zona comercial. No hay otro límite señalado. ¿Cuál es el límite de velocidad?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"Es más alto que el límite de las calles normales de la ciudad.","h2":"En Ohio, el límite en las rutas estatales o vías principales dentro de una ciudad o pueblo, fuera de las zonas comerciales, es de 35 mph, a menos que una señal indique otro.","p":"Correcto. Es 35 mph."},"ref":{"doc":"OH","page":null}},{"id":"oh-183","scope":"OH","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Ohio, what is the speed limit on a rural expressway that has no traffic signals?","o":["70 mph","55 mph","60 mph","65 mph"],"h1":"It is between the 55 mph highway limit and the rural freeway limit.","h2":"In Ohio, the speed limit on rural expressways without traffic signals is 65 mph.","p":"Right. It is 65 mph."},"es":{"q":"En Ohio, ¿cuál es el límite de velocidad en una vía rápida (expressway) rural que no tiene semáforos?","o":["70 mph","55 mph","60 mph","65 mph"],"h1":"Está entre el límite de carretera de 55 mph y el límite de las autopistas rurales.","h2":"En Ohio, el límite de velocidad en las vías rápidas (expressways) rurales sin semáforos es de 65 mph.","p":"Correcto. Es 65 mph."},"ref":{"doc":"OH","page":null}},{"id":"oh-184","scope":"OH","cat":"licensing","sign":null,"c":0,"en":{"q":"In Ohio, how many points go on the license of a driver convicted of OVI (driving under the influence)?","o":["6 points","2 points","4 points","12 points"],"h1":"It is the highest point value for a single offense.","h2":"In Ohio, an OVI conviction adds 6 points to the driver's license.","p":"Right. OVI adds 6 points."},"es":{"q":"En Ohio, ¿cuántos puntos se agregan a la licencia de un conductor condenado por OVI (manejar bajo la influencia)?","o":["6 puntos","2 puntos","4 puntos","12 puntos"],"h1":"Es el valor más alto para una sola infracción.","h2":"En Ohio, una condena por OVI agrega 6 puntos a la licencia de manejo.","p":"Correcto. El OVI agrega 6 puntos."},"ref":{"doc":"OH","page":null}},{"id":"oh-185","scope":"OH","cat":"licensing","sign":null,"c":1,"en":{"q":"In Ohio, a driver is convicted of going 30 mph or more over the speed limit. How many points are added?","o":["2 points","4 points","6 points","No points"],"h1":"It is more than an ordinary speeding ticket.","h2":"In Ohio, speeding by 30 mph or more over the limit adds 4 points to the driver's license.","p":"Right. It adds 4 points."},"es":{"q":"En Ohio, a un conductor lo condenan por ir 30 mph o más por encima del límite de velocidad. ¿Cuántos puntos se agregan?","o":["2 puntos","4 puntos","6 puntos","Ningún punto"],"h1":"Es más que una multa común por exceso de velocidad.","h2":"En Ohio, exceder el límite por 30 mph o más agrega 4 puntos a la licencia de manejo.","p":"Correcto. Agrega 4 puntos."},"ref":{"doc":"OH","page":null}},{"id":"oh-186","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, a driver is convicted of a first OVI. For how long can the court suspend the license?","o":["For life","30 days at most","Six months exactly","One to three years"],"h1":"This court suspension is longer than the 90-day suspension at arrest.","h2":"In Ohio, the court must suspend the license for one to three years for a first OVI conviction.","p":"Right. One to three years."},"es":{"q":"En Ohio, a un conductor lo condenan por un primer OVI. ¿Por cuánto tiempo puede la corte suspenderle la licencia?","o":["De por vida","30 días como máximo","Seis meses exactos","De uno a tres años"],"h1":"Esta suspensión de la corte es más larga que la de 90 días al momento del arresto.","h2":"En Ohio, la corte debe suspender la licencia por un período de uno a tres años por una primera condena por OVI.","p":"Correcto. De uno a tres años."},"ref":{"doc":"OH","page":null}},{"id":"oh-187","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, besides a fine and a license suspension, what must the court order for a first OVI?","o":["Three days in jail, or a three-day driver intervention program instead","Nothing more","One year in prison","Selling the car"],"h1":"It lasts three days in a row.","h2":"In Ohio, a first OVI conviction brings a mandatory three days in jail, which the court may replace with a three-day driver intervention program.","p":"Right. Three days in jail or a three-day intervention program."},"es":{"q":"En Ohio, además de una multa y la suspensión de la licencia, ¿qué debe ordenar la corte por un primer OVI?","o":["Tres días de cárcel, o en su lugar un programa de intervención para conductores de tres días","Nada más","Un año de prisión","Vender el carro"],"h1":"Dura tres días seguidos.","h2":"En Ohio, una primera condena por OVI trae tres días obligatorios de cárcel, que la corte puede cambiar por un programa de intervención para conductores de tres días.","p":"Correcto. Tres días de cárcel o un programa de intervención de tres días."},"ref":{"doc":"OH","page":null}},{"id":"oh-188","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, a driver is convicted of a second OVI within 10 years. What is the mandatory jail time for a standard (not high-test) OVI?","o":["3 days","10 days","1 day","No jail"],"h1":"It is much longer than for a first offense.","h2":"In Ohio, a second OVI within 10 years brings a mandatory 10 days in jail, or a mix of jail and monitored house arrest, plus a one- to seven-year license suspension.","p":"Right. The mandatory jail time is 10 days."},"es":{"q":"En Ohio, a un conductor lo condenan por un segundo OVI en 10 años. ¿Cuánta cárcel obligatoria hay para un OVI normal (no de nivel alto)?","o":["3 días","10 días","1 día","No hay cárcel"],"h1":"Es mucho más que por la primera vez.","h2":"En Ohio, un segundo OVI en 10 años trae 10 días obligatorios de cárcel, o una mezcla de cárcel y arresto domiciliario vigilado, además de una suspensión de la licencia de uno a siete años.","p":"Correcto. La cárcel obligatoria es de 10 días."},"ref":{"doc":"OH","page":null}},{"id":"oh-189","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, tougher \"high-test\" OVI penalties apply at a higher alcohol level. What is that level?","o":["0.08 percent or more","0.10 percent or more","0.17 percent or more","0.25 percent or more"],"h1":"It is well above the regular 0.08 adult limit.","h2":"In Ohio, an alcohol concentration of 0.17 percent or more brings stricter OVI penalties, such as longer mandatory jail time.","p":"Right. The high-test level is 0.17 percent."},"es":{"q":"En Ohio, las penas más duras de OVI \"de nivel alto\" se aplican a partir de cierto nivel de alcohol. ¿Cuál es ese nivel?","o":["0.08 por ciento o más","0.10 por ciento o más","0.17 por ciento o más","0.25 por ciento o más"],"h1":"Está muy por encima del límite normal de 0.08 para adultos.","h2":"En Ohio, una concentración de alcohol de 0.17 por ciento o más trae penas de OVI más estrictas, como más tiempo obligatorio en la cárcel.","p":"Correcto. El nivel alto es 0.17 por ciento."},"ref":{"doc":"OH","page":null}},{"id":"oh-190","scope":"OH","cat":"licensing","sign":null,"c":3,"en":{"q":"In Ohio, you move to a new address. How soon must you tell the BMV?","o":["Only when you renew your license","Within 30 days","Within 90 days","Within 10 days"],"h1":"It is less than two weeks.","h2":"In Ohio, a licensed driver must notify the Registrar of Motor Vehicles of a change of address within 10 days.","p":"Right. Within 10 days."},"es":{"q":"En Ohio, usted se muda a una dirección nueva. ¿En cuánto tiempo debe avisarle al BMV?","o":["Solo cuando renueve su licencia","Dentro de 30 días","Dentro de 90 días","Dentro de 10 días"],"h1":"Es menos de dos semanas.","h2":"En Ohio, un conductor con licencia debe avisar al Registro de Vehículos Motorizados (BMV) de su cambio de dirección dentro de 10 días.","p":"Correcto. Dentro de 10 días."},"ref":{"doc":"OH","page":null}},{"id":"oh-191","scope":"OH","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Ohio, you pass on a two-lane road using the lane for oncoming traffic. A car is coming toward you. By when must you be back in your lane?","o":["Before you come within 200 feet of the oncoming car","Before you come within 50 feet of it","Before it flashes its lights","Only after you are 100 feet ahead of the car you passed"],"h1":"Ohio law gives a set distance from the oncoming vehicle.","h2":"In Ohio, a driver who passes in the oncoming lane must return to their own lane before coming within 200 feet of any approaching vehicle.","p":"Right. Be back before you are within 200 feet of it."},"es":{"q":"En Ohio, usted rebasa en una carretera de dos carriles usando el carril contrario. Viene un carro de frente. ¿Cuándo debe estar ya de vuelta en su carril?","o":["Antes de quedar a 200 pies del carro que viene","Antes de quedar a 50 pies de él","Antes de que le haga cambio de luces","Solo después de estar 100 pies delante del carro que rebasó"],"h1":"La ley de Ohio da una distancia fija respecto al vehículo que viene.","h2":"En Ohio, el conductor que rebasa por el carril contrario debe volver a su carril antes de quedar a 200 pies de cualquier vehículo que venga de frente.","p":"Correcto. Vuelva antes de quedar a 200 pies de él."},"ref":{"doc":"OH","page":null}},{"id":"oh-192","scope":"OH","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Ohio, you are on a two-lane road and want to pass. How close to an intersection or railroad crossing does the law forbid driving on the left side of the road?","o":["Within 25 feet","Within 100 feet","Within 500 feet","There is no limit if the road looks clear"],"h1":"It is about the length of a city lot.","h2":"In Ohio, you may not drive on the left side of the road when you are within 100 feet of, or crossing, an intersection or railroad crossing.","p":"Right. Not within 100 feet."},"es":{"q":"En Ohio, usted va por una carretera de dos carriles y quiere rebasar. ¿A qué distancia de una intersección o de un cruce de ferrocarril prohíbe la ley ir por el lado izquierdo de la vía?","o":["A menos de 25 pies","A menos de 100 pies","A menos de 500 pies","No hay límite si la vía se ve despejada"],"h1":"Es más o menos el largo de un lote de la ciudad.","h2":"En Ohio, no puede ir por el lado izquierdo de la vía cuando está a menos de 100 pies de una intersección o de un cruce de ferrocarril, ni mientras lo cruza.","p":"Correcto. No a menos de 100 pies."},"ref":{"doc":"OH","page":null}},{"id":"oh-193","scope":"OH","cat":"signals","sign":null,"c":2,"en":{"q":"In Ohio, a driver behind you wants to pass. May you flash your turn signal to tell them it is safe to pass?","o":["Yes, the right signal means it is safe","Yes, the left signal means it is safe","No; turn signals may not be used as a courtesy \"go ahead and pass\" signal","Yes, but only on a two-lane road"],"h1":"Turn signals have one job.","h2":"In Ohio, the law says turn signals must not be flashed as a courtesy or \"do pass\" signal to drivers behind you.","p":"Right. Do not use your signals to wave someone past."},"es":{"q":"En Ohio, un conductor detrás de usted quiere rebasar. ¿Puede usar su direccional para avisarle que es seguro rebasar?","o":["Sí, la direccional derecha significa que es seguro","Sí, la direccional izquierda significa que es seguro","No; las direccionales no se pueden usar como señal de cortesía para \"pase\"","Sí, pero solo en una carretera de dos carriles"],"h1":"Las direccionales tienen un solo trabajo.","h2":"En Ohio, la ley dice que las direccionales no se deben usar como señal de cortesía o de \"pase\" para los conductores que vienen detrás.","p":"Correcto. No use las direccionales para indicar a otro que pase."},"ref":{"doc":"OH","page":null}},{"id":"oh-194","scope":"OH","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Ohio, can police stop a driver only because someone in the front seat is not wearing a safety belt?","o":["Only if the driver is under 18","Yes, it is a primary offense","Yes, but only at night","No; it is a secondary offense, ticketed only after a stop for another reason"],"h1":"Compare it with the hand-held phone law, which is primary.","h2":"In Ohio, the adult safety belt law is a secondary offense: police may not stop a vehicle only to check for belt use, but they can ticket it after stopping you for something else.","p":"Right. It is a secondary offense."},"es":{"q":"En Ohio, ¿puede la policía detener a un conductor solo porque alguien en el asiento delantero no lleva puesto el cinturón de seguridad?","o":["Solo si el conductor es menor de 18 años","Sí, es una infracción primaria","Sí, pero solo de noche","No; es una infracción secundaria y solo se multa después de una parada por otro motivo"],"h1":"Compárelo con la ley del teléfono en la mano, que es primaria.","h2":"En Ohio, la ley del cinturón para adultos es una infracción secundaria: la policía no puede detener un vehículo solo para revisar el cinturón, pero sí puede multarlo después de detenerlo por otra cosa.","p":"Correcto. Es una infracción secundaria."},"ref":{"doc":"OH","page":null}},{"id":"oh-195","scope":"OH","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Ohio, which motorcycle riders must wear a helmet by law?","o":["Riders under 18, and riders in their first year with a novice motorcycle license","All riders of every age","Only riders on the freeway","No one; helmets are never required"],"h1":"Age and experience both matter.","h2":"In Ohio, a helmet is required for motorcycle riders under 18, for riders in the first year of a novice motorcycle license or endorsement, and for anyone riding as their passenger.","p":"Right. Riders under 18 and first-year novice riders must wear one."},"es":{"q":"En Ohio, ¿qué motociclistas deben usar casco por ley?","o":["Los menores de 18 años y los que están en su primer año con una licencia de motocicleta de principiante (novice)","Todos los motociclistas de cualquier edad","Solo los que van por la autopista","Nadie; el casco nunca es obligatorio"],"h1":"Importan la edad y la experiencia.","h2":"En Ohio, el casco es obligatorio para los motociclistas menores de 18 años, para los que están en el primer año de una licencia o autorización de motocicleta de principiante (novice), y para cualquier pasajero que vaya con ellos.","p":"Correcto. Los menores de 18 y los principiantes de primer año deben usarlo."},"ref":{"doc":"OH","page":null}},{"id":"oh-196","scope":"OH","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Ohio, how many bicycle riders may ride side by side in a single lane?","o":["Only one; always single file","No more than two","No more than three","Any number"],"h1":"Pairs are allowed.","h2":"In Ohio, bicycle riders may ride no more than two abreast in a single lane, except on paths set aside for bicycles.","p":"Right. No more than two side by side."},"es":{"q":"En Ohio, ¿cuántos ciclistas pueden ir uno al lado del otro en un mismo carril?","o":["Solo uno; siempre en fila","No más de dos","No más de tres","Cualquier número"],"h1":"Se permiten parejas.","h2":"En Ohio, los ciclistas pueden ir como máximo de dos en fondo en un mismo carril, excepto en los caminos reservados para bicicletas.","p":"Correcto. No más de dos lado a lado."},"ref":{"doc":"OH","page":null}},{"id":"oh-197","scope":"OH","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Ohio, during the day, your load sticks out 5 feet past the back of your pickup. What must you put on the end of it?","o":["Nothing, if it is tied down","A white light","A red flag at least 16 inches square","A yellow sticker"],"h1":"At night it would be a red light instead.","h2":"In Ohio, when a load extends 4 feet or more past the back of a vehicle, you must show a red flag at least 16 inches square at its end by day, and a red light at night.","p":"Right. A red flag at least 16 inches square."},"es":{"q":"En Ohio, de día, su carga sobresale 5 pies por detrás de su camioneta (pickup). ¿Qué debe poner en el extremo?","o":["Nada, si está bien amarrada","Una luz blanca","Una bandera roja de al menos 16 pulgadas por lado","Una calcomanía amarilla"],"h1":"De noche sería una luz roja.","h2":"En Ohio, cuando una carga sobresale 4 pies o más por detrás de un vehículo, de día debe poner en su extremo una bandera roja de al menos 16 pulgadas por lado, y de noche una luz roja.","p":"Correcto. Una bandera roja de al menos 16 pulgadas por lado."},"ref":{"doc":"OH","page":null}},{"id":"ok-001","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many questions are on the written exam for a learner permit?","o":["10","20","30","50"],"h1":"It is a short test, fewer than in many states.","h2":"In Oklahoma, the written exam for a learner permit has 20 questions.","p":"Right. The Oklahoma written exam has 20 questions."},"es":{"q":"En Oklahoma, ¿cuántas preguntas tiene el examen escrito para el permiso de aprendiz?","o":["10","20","30","50"],"h1":"Es un examen corto, con menos preguntas que en muchos estados.","h2":"En Oklahoma, el examen escrito para el permiso de aprendiz tiene 20 preguntas.","p":"Correcto. El examen escrito de Oklahoma tiene 20 preguntas."},"zh":{"q":"在 Oklahoma，学习驾照（learner permit）的笔试有多少道题？","o":["10","20","30","50"],"h1":"它是一个短的考试，比很多州的题少。","h2":"在 Oklahoma，学习驾照的笔试有 20 道题。","p":"对。Oklahoma 的笔试有 20 道题。"},"vi":{"q":"Ở Oklahoma, bài thi viết để lấy giấy phép tập lái (learner permit) có bao nhiêu câu hỏi?","o":["10","20","30","50"],"h1":"Đây là bài thi ngắn, ít câu hơn so với nhiều tiểu bang khác.","h2":"Ở Oklahoma, bài thi viết để lấy giấy phép tập lái có 20 câu hỏi.","p":"Đúng. Bài thi viết ở Oklahoma có 20 câu hỏi."},"tl":{"q":"Sa Oklahoma, ilang tanong ang nasa written exam para sa learner permit?","o":["10","20","30","50"],"h1":"Maikli ang test na ito, mas kaunti kaysa sa maraming estado.","h2":"Sa Oklahoma, may 20 tanong ang written exam para sa learner permit.","p":"Tama. May 20 tanong ang written exam sa Oklahoma."},"ar":{"q":"في Oklahoma، كم سؤالًا في الاختبار الكتابي للحصول على تصريح التعلّم (learner permit)؟","o":["10","20","30","50"],"h1":"هو اختبار قصير، فيه أسئلة أقل من ولايات كثيرة.","h2":"في Oklahoma، الاختبار الكتابي للحصول على تصريح التعلّم فيه 20 سؤالًا.","p":"صحيح. الاختبار الكتابي في Oklahoma فيه 20 سؤالًا."},"ref":{"doc":"OK","page":null}},{"id":"ok-002","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what must a 15-year-old be doing to get a learner permit?","o":["Working a part-time job","Nothing extra; age is enough","Holding a high school diploma","Taking an approved driver education course"],"h1":"At 15 you are still learning in a class.","h2":"In Oklahoma, a 15-year-old must be enrolled in and taking an approved driver education course, and must pass the written exam, to get a learner permit.","p":"Right. At 15, driver education comes first."},"es":{"q":"En Oklahoma, ¿qué debe estar haciendo un joven de 15 años para obtener un permiso de aprendiz?","o":["Tener un trabajo de medio tiempo","Nada más; la edad es suficiente","Tener diploma de secundaria","Tomar un curso aprobado de educación vial"],"h1":"A los 15 años usted todavía está aprendiendo en una clase.","h2":"En Oklahoma, un joven de 15 años debe estar inscrito y tomando un curso aprobado de educación vial, y aprobar el examen escrito, para obtener el permiso de aprendiz.","p":"Correcto. A los 15, primero va la educación vial."},"zh":{"q":"在 Oklahoma，15 岁的青少年要拿学习驾照，必须正在做什么？","o":["做兼职工作","不用做别的，年龄够就行","有高中毕业证","上认可的驾驶教育课程"],"h1":"15 岁时你还在上课学习。","h2":"在 Oklahoma，15 岁的青少年必须报名并正在上认可的驾驶教育课程，还要通过笔试，才能拿学习驾照。","p":"对。15 岁时，先要上驾驶教育。"},"vi":{"q":"Ở Oklahoma, người 15 tuổi phải đang làm gì để lấy giấy phép tập lái (learner permit)?","o":["Đang làm việc bán thời gian","Không cần gì thêm; đủ tuổi là được","Đã có bằng tốt nghiệp trung học","Đang học một khóa giáo dục lái xe (driver education) được chấp thuận"],"h1":"Ở tuổi 15, bạn vẫn còn đang học trong một lớp học.","h2":"Ở Oklahoma, người 15 tuổi phải đã đăng ký và đang học một khóa giáo dục lái xe được chấp thuận, và phải đậu bài thi viết, để lấy giấy phép tập lái.","p":"Đúng. Ở tuổi 15, phải học giáo dục lái xe trước."},"tl":{"q":"Sa Oklahoma, ano ang dapat ginagawa ng isang 15 taong gulang para makakuha ng learner permit?","o":["Nagtatrabaho nang part-time","Wala nang iba; sapat na ang edad","May high school diploma","Kumukuha ng aprobadong kurso sa driver education"],"h1":"Sa edad na 15, nag-aaral ka pa sa isang klase.","h2":"Sa Oklahoma, ang isang 15 taong gulang ay dapat naka-enroll at kumukuha ng aprobadong kurso sa driver education, at dapat pumasa sa written exam, para makakuha ng learner permit.","p":"Tama. Sa edad na 15, driver education muna."},"ar":{"q":"في Oklahoma، ماذا يجب أن يفعل من عمره 15 سنة للحصول على تصريح التعلّم (learner permit)؟","o":["أن يعمل في وظيفة بدوام جزئي","لا شيء إضافي؛ العمر يكفي","أن يحمل شهادة الثانوية","أن يدرس في دورة تعليم قيادة (driver education) معتمدة"],"h1":"في عمر 15 سنة ما زلت تتعلّم في صف دراسي.","h2":"في Oklahoma، يجب على من عمره 15 سنة أن يكون مسجّلًا في دورة تعليم قيادة معتمدة ويدرس فيها، وأن ينجح في الاختبار الكتابي، للحصول على تصريح التعلّم.","p":"صحيح. في عمر 15 سنة يأتي تعليم القيادة أولًا."},"ref":{"doc":"OK","page":6}},{"id":"ok-003","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, is driver education required for a 16-year-old to get a learner permit?","o":["No, it is optional at 16","Yes, always","Yes, and you must pass the road test first","No, and you may drive alone right away"],"h1":"At 16 one requirement drops away.","h2":"In Oklahoma, driver education is optional at 16. You still pass the written exam, unless a finished driver education course lets you skip it.","p":"Right. At 16, driver education is optional."},"es":{"q":"En Oklahoma, ¿se requiere educación vial para que un joven de 16 años obtenga un permiso de aprendiz?","o":["No, es opcional a los 16","Sí, siempre","Sí, y primero debe aprobar el examen de manejo","No, y puede manejar solo de inmediato"],"h1":"A los 16 se quita un requisito.","h2":"En Oklahoma, la educación vial es opcional a los 16 años. Usted todavía debe aprobar el examen escrito, a menos que un curso de educación vial terminado le permita omitirlo.","p":"Correcto. A los 16, la educación vial es opcional."},"zh":{"q":"在 Oklahoma，16 岁的青少年拿学习驾照需要上驾驶教育吗？","o":["不需要，16 岁时可以选择上或不上","需要，一直都需要","需要，而且必须先通过路考","不需要，而且马上就可以自己开车"],"h1":"16 岁时少了一个要求。","h2":"在 Oklahoma，16 岁时驾驶教育可以选择上或不上。你仍然要通过笔试，除非你上完了驾驶教育课程，可以不用考。","p":"对。16 岁时，驾驶教育可以选择上或不上。"},"vi":{"q":"Ở Oklahoma, người 16 tuổi có bắt buộc phải học giáo dục lái xe (driver education) để lấy giấy phép tập lái không?","o":["Không, ở tuổi 16 thì không bắt buộc","Có, luôn luôn bắt buộc","Có, và bạn phải đậu bài thi lái xe trên đường trước","Không, và bạn có thể lái một mình ngay"],"h1":"Ở tuổi 16, có một yêu cầu không còn nữa.","h2":"Ở Oklahoma, giáo dục lái xe không bắt buộc ở tuổi 16. Bạn vẫn phải đậu bài thi viết, trừ khi đã học xong một khóa giáo dục lái xe cho phép bạn bỏ qua bài thi này.","p":"Đúng. Ở tuổi 16, giáo dục lái xe không bắt buộc."},"tl":{"q":"Sa Oklahoma, kailangan ba ang driver education para makakuha ng learner permit ang isang 16 taong gulang?","o":["Hindi, hindi ito kailangan sa edad na 16","Oo, palagi","Oo, at dapat ka munang pumasa sa road test","Hindi, at puwede ka nang magmaneho nang mag-isa agad"],"h1":"Sa edad na 16, nawawala ang isang kailangan.","h2":"Sa Oklahoma, hindi kailangan ang driver education sa edad na 16. Kailangan mo pa ring pumasa sa written exam, maliban kung may natapos kang kurso sa driver education na nagpapahintulot na laktawan ito.","p":"Tama. Sa edad na 16, hindi kailangan ang driver education."},"ar":{"q":"في Oklahoma، هل تعليم القيادة (driver education) مطلوب لمن عمره 16 سنة للحصول على تصريح التعلّم؟","o":["لا، هو اختياري في عمر 16 سنة","نعم، دائمًا","نعم، ويجب أن تنجح في اختبار القيادة على الطريق أولًا","لا، ويمكنك أن تقود وحدك فورًا"],"h1":"في عمر 16 سنة يسقط أحد الشروط.","h2":"في Oklahoma، تعليم القيادة اختياري في عمر 16 سنة. وما زال عليك أن تنجح في الاختبار الكتابي، إلا إذا أنهيت دورة تعليم قيادة تسمح لك بتخطّيه.","p":"صحيح. في عمر 16 سنة، تعليم القيادة اختياري."},"ref":{"doc":"OK","page":6}},{"id":"ok-004","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may a learner permit holder drive?","o":["Any time of day","6:00 a.m. to 9:00 p.m.","5:00 a.m. to 10:00 p.m.","Daylight hours only"],"h1":"The window starts very early and ends at ten.","h2":"In Oklahoma, a learner permit holder may drive between 5:00 in the morning and 10:00 at night, with a licensed driver at least 21 years old.","p":"Right. Oklahoma learners drive from 5 a.m. to 10 p.m."},"es":{"q":"En Oklahoma, ¿en qué horario puede manejar una persona con permiso de aprendiz?","o":["A cualquier hora","De 6:00 a.m. a 9:00 p.m.","De 5:00 a.m. a 10:00 p.m.","Solo con luz del día"],"h1":"El horario empieza muy temprano y termina a las diez.","h2":"En Oklahoma, quien tiene permiso de aprendiz puede manejar entre las 5:00 de la mañana y las 10:00 de la noche, con un conductor con licencia de por lo menos 21 años.","p":"Correcto. Los aprendices en Oklahoma manejan de 5 a.m. a 10 p.m."},"zh":{"q":"在 Oklahoma，学习驾照持有人在什么时间可以开车？","o":["白天晚上任何时间","早上 6:00 到晚上 9:00","早上 5:00 到晚上 10:00","只能在白天"],"h1":"可以开车的时间很早开始，到十点结束。","h2":"在 Oklahoma，学习驾照持有人可以在早上 5:00 到晚上 10:00 之间开车，要有一位至少 21 岁、有驾照的司机陪同。","p":"对。Oklahoma 的学员从早上 5 点开到晚上 10 点。"},"vi":{"q":"Ở Oklahoma, người có giấy phép tập lái được lái xe trong những giờ nào?","o":["Bất cứ giờ nào trong ngày","6:00 sáng đến 9:00 tối","5:00 sáng đến 10:00 tối","Chỉ khi trời sáng"],"h1":"Khung giờ bắt đầu rất sớm và kết thúc lúc mười giờ.","h2":"Ở Oklahoma, người có giấy phép tập lái được lái xe từ 5:00 sáng đến 10:00 tối, cùng với một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người tập lái ở Oklahoma được lái từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa Oklahoma, sa anong mga oras puwedeng magmaneho ang may hawak ng learner permit?","o":["Kahit anong oras","6:00 a.m. hanggang 9:00 p.m.","5:00 a.m. hanggang 10:00 p.m.","Kapag maliwanag lang"],"h1":"Napakaaga nagsisimula ang oras at natatapos ito nang alas-diyes.","h2":"Sa Oklahoma, puwedeng magmaneho ang may hawak ng learner permit mula 5:00 ng umaga hanggang 10:00 ng gabi, kasama ang isang lisensiyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Nagmamaneho ang mga learner sa Oklahoma mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في Oklahoma، في أي ساعات يمكن لحامل تصريح التعلّم أن يقود؟","o":["في أي وقت من اليوم","من 6:00 صباحًا إلى 9:00 مساءً","من 5:00 صباحًا إلى 10:00 مساءً","في ساعات النهار فقط"],"h1":"الفترة تبدأ مبكرًا جدًا وتنتهي في الساعة العاشرة.","h2":"في Oklahoma، يمكن لحامل تصريح التعلّم أن يقود بين الساعة 5:00 صباحًا والساعة 10:00 مساءً، مع سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. المتعلّمون في Oklahoma يقودون من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"OK","page":null}},{"id":"ok-005","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how old must the licensed driver with a learner permit holder be?","o":["At least 18","At least 21","At least 25","At least 30"],"h1":"The supervisor must be old enough to drink legally.","h2":"In Oklahoma, a learner permit holder must drive with a licensed driver who is at least 21 years old.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Oklahoma, ¿qué edad debe tener el conductor con licencia que acompaña a quien tiene permiso de aprendiz?","o":["Por lo menos 18","Por lo menos 21","Por lo menos 25","Por lo menos 30"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Oklahoma, quien tiene permiso de aprendiz debe manejar con un conductor con licencia de por lo menos 21 años.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 Oklahoma，陪同学习驾照持有人的有驾照司机必须几岁？","o":["至少 18 岁","至少 21 岁","至少 25 岁","至少 30 岁"],"h1":"监督的人必须到了可以合法喝酒的年龄。","h2":"在 Oklahoma，学习驾照持有人必须和一位至少 21 岁、有驾照的司机一起开车。","p":"对。监督的人必须 21 岁或以上。"},"vi":{"q":"Ở Oklahoma, người có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi","Ít nhất 30 tuổi"],"h1":"Người giám sát phải đủ tuổi để uống rượu hợp pháp.","h2":"Ở Oklahoma, người có giấy phép tập lái phải lái xe cùng một người có bằng lái từ 21 tuổi trở lên.","p":"Đúng. Người giám sát phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Oklahoma, ilang taon dapat ang lisensiyadong driver na kasama ng may hawak ng learner permit?","o":["Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25","Hindi bababa sa 30"],"h1":"Dapat sapat ang edad ng nagbabantay para legal na uminom ng alak.","h2":"Sa Oklahoma, ang may hawak ng learner permit ay dapat magmaneho kasama ang isang lisensiyadong driver na hindi bababa sa 21 taong gulang.","p":"Tama. Dapat 21 taong gulang pataas ang nagbabantay."},"ar":{"q":"في Oklahoma، كم يجب أن يكون عمر السائق المرخّص الذي يرافق حامل تصريح التعلّم؟","o":["18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل","30 سنة على الأقل"],"h1":"يجب أن يكون المشرف في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في Oklahoma، يجب على حامل تصريح التعلّم أن يقود مع سائق مرخّص عمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون عمر المشرف 21 سنة أو أكثر."},"ref":{"doc":"OK","page":6}},{"id":"ok-006","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many hours of supervised driving must a teen complete before the intermediate license?","o":["20 hours, including 5 at night","30 hours, including 10 at night","60 hours, including 15 at night","50 hours, including 10 at night"],"h1":"It is half of one hundred, with 10 of them at night.","h2":"In Oklahoma, a teen must complete 50 hours of supervised driving, including 10 hours at night, before getting an intermediate license.","p":"Right. 50 hours, 10 at night."},"es":{"q":"En Oklahoma, ¿cuántas horas de manejo supervisado debe completar un joven antes de la licencia intermedia?","o":["20 horas, 5 de ellas de noche","30 horas, 10 de ellas de noche","60 horas, 15 de ellas de noche","50 horas, 10 de ellas de noche"],"h1":"Es la mitad de cien, con 10 de ellas de noche.","h2":"En Oklahoma, un joven debe completar 50 horas de manejo supervisado, 10 de ellas de noche, antes de obtener la licencia intermedia.","p":"Correcto. 50 horas, 10 de noche."},"zh":{"q":"在 Oklahoma，青少年拿中级驾照（intermediate license）前，必须完成多少小时有人监督的驾驶？","o":["20 小时，其中 5 小时在晚上","30 小时，其中 10 小时在晚上","60 小时，其中 15 小时在晚上","50 小时，其中 10 小时在晚上"],"h1":"它是一百的一半，其中 10 小时在晚上。","h2":"在 Oklahoma，青少年拿中级驾照前必须完成 50 小时有人监督的驾驶，其中 10 小时在晚上。","p":"对。50 小时，10 小时在晚上。"},"vi":{"q":"Ở Oklahoma, thiếu niên phải lái xe có giám sát bao nhiêu giờ trước khi lấy bằng lái trung gian (intermediate license)?","o":["20 giờ, gồm 5 giờ ban đêm","30 giờ, gồm 10 giờ ban đêm","60 giờ, gồm 15 giờ ban đêm","50 giờ, gồm 10 giờ ban đêm"],"h1":"Đó là một nửa của một trăm, trong đó có 10 giờ ban đêm.","h2":"Ở Oklahoma, thiếu niên phải lái xe có giám sát 50 giờ, gồm 10 giờ ban đêm, trước khi lấy bằng lái trung gian.","p":"Đúng. 50 giờ, có 10 giờ ban đêm."},"tl":{"q":"Sa Oklahoma, ilang oras ng pagmamaneho na may nagbabantay ang dapat makumpleto ng isang teen bago ang intermediate license?","o":["20 oras, kasama ang 5 sa gabi","30 oras, kasama ang 10 sa gabi","60 oras, kasama ang 15 sa gabi","50 oras, kasama ang 10 sa gabi"],"h1":"Kalahati ito ng isang daan, at 10 dito ay sa gabi.","h2":"Sa Oklahoma, dapat makumpleto ng isang teen ang 50 oras ng pagmamaneho na may nagbabantay, kasama ang 10 oras sa gabi, bago makakuha ng intermediate license.","p":"Tama. 50 oras, 10 dito sa gabi."},"ar":{"q":"في Oklahoma، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل الرخصة المتوسطة (intermediate license)؟","o":["20 ساعة، منها 5 في الليل","30 ساعة، منها 10 في الليل","60 ساعة، منها 15 في الليل","50 ساعة، منها 10 في الليل"],"h1":"هو نصف المئة، و10 منها في الليل.","h2":"في Oklahoma، يجب أن يُكمل المراهق 50 ساعة من القيادة تحت الإشراف، منها 10 ساعات في الليل، قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 50 ساعة، منها 10 في الليل."},"ref":{"doc":"OK","page":null}},{"id":"ok-007","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how long must a teen hold a learner permit before getting an intermediate license?","o":["About 6 months (180 days)","30 days","1 year","2 years"],"h1":"It is half a year.","h2":"In Oklahoma, a teen must hold the learner permit for at least 180 days, about six months, before getting an intermediate license.","p":"Right. 180 days with the permit first."},"es":{"q":"En Oklahoma, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia?","o":["Unos 6 meses (180 días)","30 días","1 año","2 años"],"h1":"Es medio año.","h2":"En Oklahoma, un joven debe tener el permiso de aprendiz por lo menos 180 días, unos seis meses, antes de obtener la licencia intermedia.","p":"Correcto. Primero 180 días con el permiso."},"zh":{"q":"在 Oklahoma，青少年拿中级驾照前，必须持有学习驾照多久？","o":["大约 6 个月（180 天）","30 天","1 年","2 年"],"h1":"它是半年。","h2":"在 Oklahoma，青少年必须持有学习驾照至少 180 天，大约六个月，才能拿中级驾照。","p":"对。先持有学习驾照 180 天。"},"vi":{"q":"Ở Oklahoma, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung gian (intermediate license)?","o":["Khoảng 6 tháng (180 ngày)","30 ngày","1 năm","2 năm"],"h1":"Đó là nửa năm.","h2":"Ở Oklahoma, thiếu niên phải giữ giấy phép tập lái ít nhất 180 ngày, khoảng sáu tháng, trước khi lấy bằng lái trung gian.","p":"Đúng. Phải giữ giấy phép tập lái 180 ngày trước."},"tl":{"q":"Sa Oklahoma, gaano katagal dapat hawak ng isang teen ang learner permit bago makakuha ng intermediate license?","o":["Mga 6 na buwan (180 araw)","30 araw","1 taon","2 taon"],"h1":"Kalahating taon ito.","h2":"Sa Oklahoma, dapat hawak ng isang teen ang learner permit nang hindi bababa sa 180 araw, mga anim na buwan, bago makakuha ng intermediate license.","p":"Tama. 180 araw muna na hawak ang permit."},"ar":{"q":"في Oklahoma، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["حوالي 6 أشهر (180 يومًا)","30 يومًا","سنة واحدة","سنتان"],"h1":"هي نصف سنة.","h2":"في Oklahoma، يجب أن يحمل المراهق تصريح التعلّم 180 يومًا على الأقل، أي حوالي ستة أشهر، قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 180 يومًا مع التصريح أولًا."},"ref":{"doc":"OK","page":6}},{"id":"ok-008","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, during which hours may an intermediate license holder not drive alone, unless an exception applies?","o":["Midnight to 5:00 a.m.","9:00 p.m. to 6:00 a.m.","10:00 p.m. to 5:00 a.m.","There is no night limit"],"h1":"It starts at the same hour the learner permit day ends.","h2":"In Oklahoma, an intermediate license holder may not drive alone between 10:00 at night and 5:00 in the morning, unless an exception such as work, school or church applies.","p":"Right. No solo driving from 10 p.m. to 5 a.m."},"es":{"q":"En Oklahoma, ¿en qué horario no puede manejar solo quien tiene licencia intermedia, salvo una excepción?","o":["De medianoche a 5:00 a.m.","De 9:00 p.m. a 6:00 a.m.","De 10:00 p.m. a 5:00 a.m.","No hay límite de noche"],"h1":"Empieza a la misma hora en que termina el día del permiso de aprendiz.","h2":"En Oklahoma, quien tiene licencia intermedia no puede manejar solo entre las 10:00 de la noche y las 5:00 de la mañana, salvo una excepción como trabajo, escuela o iglesia.","p":"Correcto. No se maneja solo de 10 p.m. a 5 a.m."},"zh":{"q":"在 Oklahoma，除非有例外情况，中级驾照持有人在哪个时间段不能自己开车？","o":["午夜到早上 5:00","晚上 9:00 到早上 6:00","晚上 10:00 到早上 5:00","晚上没有限制"],"h1":"它开始的时间，和学习驾照可以开车的时间结束得一样。","h2":"在 Oklahoma，中级驾照持有人在晚上 10:00 到早上 5:00 之间不能自己开车，除非有例外情况，比如上班、上学或去教堂。","p":"对。晚上 10 点到早上 5 点不能自己开车。"},"vi":{"q":"Ở Oklahoma, người có bằng lái trung gian (intermediate license) không được lái xe một mình trong những giờ nào, trừ khi có trường hợp ngoại lệ?","o":["Nửa đêm đến 5:00 sáng","9:00 tối đến 6:00 sáng","10:00 tối đến 5:00 sáng","Không có giới hạn ban đêm"],"h1":"Nó bắt đầu đúng vào giờ mà ngày lái của giấy phép tập lái kết thúc.","h2":"Ở Oklahoma, người có bằng lái trung gian không được lái xe một mình từ 10:00 tối đến 5:00 sáng, trừ khi có ngoại lệ như đi làm, đi học hoặc đi nhà thờ.","p":"Đúng. Không lái một mình từ 10 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Oklahoma, sa anong mga oras hindi puwedeng magmaneho nang mag-isa ang may hawak ng intermediate license, maliban kung may exception?","o":["Hatinggabi hanggang 5:00 a.m.","9:00 p.m. hanggang 6:00 a.m.","10:00 p.m. hanggang 5:00 a.m.","Walang limitasyon sa gabi"],"h1":"Nagsisimula ito sa parehong oras kung kailan natatapos ang araw ng learner permit.","h2":"Sa Oklahoma, hindi puwedeng magmaneho nang mag-isa ang may hawak ng intermediate license mula 10:00 ng gabi hanggang 5:00 ng umaga, maliban kung may exception gaya ng trabaho, paaralan o simbahan.","p":"Tama. Bawal magmaneho nang mag-isa mula 10 p.m. hanggang 5 a.m."},"ar":{"q":"في Oklahoma، في أي ساعات لا يجوز لحامل الرخصة المتوسطة (intermediate license) أن يقود وحده، إلا إذا وُجد استثناء؟","o":["من منتصف الليل إلى 5:00 صباحًا","من 9:00 مساءً إلى 6:00 صباحًا","من 10:00 مساءً إلى 5:00 صباحًا","لا يوجد حدّ في الليل"],"h1":"تبدأ في نفس الساعة التي ينتهي فيها يوم تصريح التعلّم.","h2":"في Oklahoma، لا يجوز لحامل الرخصة المتوسطة أن يقود وحده بين الساعة 10:00 مساءً والساعة 5:00 صباحًا، إلا إذا وُجد استثناء مثل العمل أو المدرسة أو الكنيسة.","p":"صحيح. لا قيادة وحدك من 10 مساءً إلى 5 صباحًا."},"ref":{"doc":"OK","page":14}},{"id":"ok-009","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many passengers who do not live in the driver's home may an intermediate license holder carry, without a supervising driver?","o":["None","One","Two","Three"],"h1":"Think of one friend, not a carload.","h2":"In Oklahoma, an intermediate license holder may carry only one passenger who does not live in the driver's home, unless a licensed driver 21 or older sits in the front seat.","p":"Right. Only one passenger from outside the home."},"es":{"q":"En Oklahoma, ¿cuántos pasajeros que no viven en la casa del conductor puede llevar alguien con licencia intermedia, sin un conductor supervisor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Piense en un amigo, no en un carro lleno.","h2":"En Oklahoma, quien tiene licencia intermedia puede llevar solo un pasajero que no vive en su casa, a menos que un conductor con licencia de 21 años o más vaya en el asiento delantero.","p":"Correcto. Solo un pasajero de fuera de la casa."},"zh":{"q":"在 Oklahoma，没有监督司机时，中级驾照持有人可以载几位不住在司机家里的乘客？","o":["一位也不行","一位","两位","三位"],"h1":"想想一位朋友，不是一车人。","h2":"在 Oklahoma，中级驾照持有人只能载一位不住在司机家里的乘客，除非有一位 21 岁或以上、有驾照的司机坐在前排。","p":"对。只能载一位不住在家里的乘客。"},"vi":{"q":"Ở Oklahoma, khi không có người giám sát, người có bằng lái trung gian được chở bao nhiêu hành khách không sống chung nhà với người lái?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Hãy nghĩ đến một người bạn, không phải cả một xe đầy người.","h2":"Ở Oklahoma, người có bằng lái trung gian chỉ được chở một hành khách không sống chung nhà với người lái, trừ khi có một người có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Đúng. Chỉ một hành khách không sống chung nhà."},"tl":{"q":"Sa Oklahoma, ilang pasaherong hindi nakatira sa bahay ng driver ang puwedeng isakay ng may hawak ng intermediate license, kung walang nagbabantay na driver?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Isipin ang isang kaibigan, hindi isang buong kotse.","h2":"Sa Oklahoma, isang pasahero lang na hindi nakatira sa bahay ng driver ang puwedeng isakay ng may hawak ng intermediate license, maliban kung may lisensiyadong driver na 21 taong gulang pataas na nakaupo sa harap.","p":"Tama. Isang pasahero lang mula sa labas ng bahay."},"ar":{"q":"في Oklahoma، كم راكبًا لا يعيشون في بيت السائق يمكن لحامل الرخصة المتوسطة أن ينقلهم، بدون سائق مشرف؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"فكّر في صديق واحد، وليس في سيارة مليئة.","h2":"في Oklahoma، يمكن لحامل الرخصة المتوسطة أن ينقل راكبًا واحدًا فقط لا يعيش في بيت السائق، إلا إذا جلس في المقعد الأمامي سائق مرخّص عمره 21 سنة أو أكثر.","p":"صحيح. راكب واحد فقط من خارج البيت."},"ref":{"doc":"OK","page":14}},{"id":"ok-010","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, may a driver read or send a text message on a hand-held phone while driving?","o":["Yes, at a slow speed","Yes, on rural roads","Yes, if the message is short","No, it is against the law"],"h1":"Since 2015, the answer is the same for all drivers.","h2":"In Oklahoma, it is against the law to text on a hand-held phone while driving.","p":"Right. Texting while driving is against the law in Oklahoma."},"es":{"q":"En Oklahoma, ¿puede un conductor leer o enviar un mensaje de texto con el teléfono en la mano mientras maneja?","o":["Sí, a baja velocidad","Sí, en caminos rurales","Sí, si el mensaje es corto","No, es ilegal"],"h1":"Desde 2015, la respuesta es la misma para todos los conductores.","h2":"En Oklahoma, es ilegal enviar o leer mensajes de texto en un teléfono en la mano mientras maneja.","p":"Correcto. En Oklahoma es ilegal enviar mensajes de texto mientras maneja."},"zh":{"q":"在 Oklahoma，司机开车时可以用手持手机看或发短信吗？","o":["可以，开得慢时","可以，在乡村道路上","可以，如果短信很短","不可以，这是违法的"],"h1":"从 2015 年起，所有司机的答案都一样。","h2":"在 Oklahoma，开车时用手持手机发短信是违法的。","p":"对。在 Oklahoma，开车时发短信是违法的。"},"vi":{"q":"Ở Oklahoma, người lái xe có được đọc hoặc gửi tin nhắn trên điện thoại cầm tay khi đang lái xe không?","o":["Có, khi chạy chậm","Có, trên đường nông thôn","Có, nếu tin nhắn ngắn","Không, điều đó là phạm luật"],"h1":"Từ năm 2015, câu trả lời giống nhau cho mọi người lái xe.","h2":"Ở Oklahoma, nhắn tin trên điện thoại cầm tay khi đang lái xe là phạm luật.","p":"Đúng. Nhắn tin khi lái xe là phạm luật ở Oklahoma."},"tl":{"q":"Sa Oklahoma, puwede bang magbasa o magpadala ng text message ang driver sa hawak na cellphone habang nagmamaneho?","o":["Oo, kapag mabagal","Oo, sa mga daan sa probinsiya","Oo, kung maikli ang mensahe","Hindi, labag ito sa batas"],"h1":"Mula 2015, pareho ang sagot para sa lahat ng driver.","h2":"Sa Oklahoma, labag sa batas ang mag-text sa hawak na cellphone habang nagmamaneho.","p":"Tama. Labag sa batas sa Oklahoma ang mag-text habang nagmamaneho."},"ar":{"q":"في Oklahoma، هل يجوز للسائق أن يقرأ أو يرسل رسالة نصية على هاتف محمول باليد أثناء القيادة؟","o":["نعم، بسرعة بطيئة","نعم، على الطرق الريفية","نعم، إذا كانت الرسالة قصيرة","لا، هذا مخالف للقانون"],"h1":"منذ سنة 2015، الجواب نفسه لكل السائقين.","h2":"في Oklahoma، كتابة الرسائل النصية على هاتف محمول باليد أثناء القيادة مخالفة للقانون.","p":"صحيح. كتابة الرسائل أثناء القيادة مخالفة للقانون في Oklahoma."},"ref":{"doc":"OK","page":61}},{"id":"ok-011","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the fine for a first violation of the Move Over law?","o":["$1,000","$50","$100","$250"],"h1":"Since late 2023 the fine is very high, with four digits.","h2":"In Oklahoma, a first violation of the Move Over law carries a fine of $1,000.","p":"Right. $1,000 for a first offense."},"es":{"q":"En Oklahoma, ¿cuál es la multa por una primera infracción de la ley Move Over (cámbiese de carril)?","o":["$1,000","$50","$100","$250"],"h1":"Desde finales de 2023 la multa es muy alta, de cuatro cifras.","h2":"En Oklahoma, una primera infracción de la ley Move Over tiene una multa de $1,000.","p":"Correcto. $1,000 por la primera infracción."},"zh":{"q":"在 Oklahoma，第一次违反让道变道法（Move Over law）罚款多少？","o":["$1,000","$50","$100","$250"],"h1":"从 2023 年底起，罚款很高，有四位数。","h2":"在 Oklahoma，第一次违反让道变道法（Move Over law）罚款 $1,000。","p":"对。第一次罚 $1,000。"},"vi":{"q":"Ở Oklahoma, tiền phạt cho lần vi phạm đầu tiên của luật Tránh Sang Làn Khác (Move Over law) là bao nhiêu?","o":["$1,000","$50","$100","$250"],"h1":"Từ cuối năm 2023, tiền phạt rất cao, có bốn chữ số.","h2":"Ở Oklahoma, lần vi phạm đầu tiên luật Tránh Sang Làn Khác (Move Over law) bị phạt $1,000.","p":"Đúng. $1,000 cho lần vi phạm đầu tiên."},"tl":{"q":"Sa Oklahoma, magkano ang multa sa unang paglabag sa Move Over law?","o":["$1,000","$50","$100","$250"],"h1":"Mula sa huling bahagi ng 2023, napakataas ng multa, may apat na digit.","h2":"Sa Oklahoma, ang unang paglabag sa Move Over law ay may multang $1,000.","p":"Tama. $1,000 para sa unang paglabag."},"ar":{"q":"في Oklahoma، ما الغرامة على المخالفة الأولى لقانون الابتعاد إلى حارة أخرى (Move Over law)؟","o":["$1,000","$50","$100","$250"],"h1":"منذ أواخر سنة 2023 الغرامة عالية جدًا، من أربعة أرقام.","h2":"في Oklahoma، المخالفة الأولى لقانون الابتعاد إلى حارة أخرى (Move Over law) عليها غرامة $1,000.","p":"صحيح. $1,000 على المخالفة الأولى."},"ref":{"doc":"OK","page":null}},{"id":"ok-012","scope":"OK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oklahoma, a school bus stops with red lights flashing on a four-lane road with a center turn lane and no median. Who must stop?","o":["Only traffic behind the bus","Only traffic in the lane next to the bus","All traffic in both directions","No one, because of the turn lane"],"h1":"A center turn lane is not a median.","h2":"In Oklahoma, on a road with four or more lanes and no median, traffic in both directions must stop for a stopped school bus, even if there is a center turn lane.","p":"Right. No median means everyone stops."},"es":{"q":"En Oklahoma, un autobús escolar se detiene con luces rojas intermitentes en una calle de cuatro carriles con carril central de vuelta y sin camellón. ¿Quién debe detenerse?","o":["Solo el tráfico detrás del autobús","Solo el tráfico en el carril junto al autobús","Todo el tráfico en ambas direcciones","Nadie, por el carril de vuelta"],"h1":"Un carril central de vuelta no es un camellón.","h2":"En Oklahoma, en una calle de cuatro carriles o más sin camellón, el tráfico en ambas direcciones debe detenerse ante un autobús escolar detenido, aunque haya un carril central de vuelta.","p":"Correcto. Sin camellón, todos se detienen."},"zh":{"q":"在 Oklahoma，一辆校车在一条有中间转弯车道、没有中间隔离带的四车道路上停下，闪着红灯。谁必须停车？","o":["只有校车后面的车","只有校车旁边车道的车","两个方向的所有车","谁都不用，因为有转弯车道"],"h1":"中间转弯车道不是中间隔离带。","h2":"在 Oklahoma，在四条或更多车道、没有中间隔离带的路上，两个方向的车都必须为停着的校车停车，就算有中间转弯车道也一样。","p":"对。没有中间隔离带，所有人都要停车。"},"vi":{"q":"Ở Oklahoma, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy trên đường bốn làn có làn rẽ ở giữa và không có dải phân cách. Ai phải dừng lại?","o":["Chỉ xe phía sau xe buýt","Chỉ xe ở làn bên cạnh xe buýt","Tất cả xe ở cả hai chiều","Không ai, vì có làn rẽ"],"h1":"Làn rẽ ở giữa không phải là dải phân cách.","h2":"Ở Oklahoma, trên đường có bốn làn trở lên và không có dải phân cách, xe ở cả hai chiều phải dừng lại khi xe buýt trường học dừng, ngay cả khi có làn rẽ ở giữa.","p":"Đúng. Không có dải phân cách thì mọi người đều phải dừng."},"tl":{"q":"Sa Oklahoma, huminto ang isang school bus na kumikislap ang pulang ilaw sa daang may apat na lane, may center turn lane sa gitna at walang median. Sino ang dapat huminto?","o":["Ang mga sasakyan lang sa likod ng bus","Ang mga sasakyan lang sa lane na katabi ng bus","Lahat ng sasakyan sa dalawang direksiyon","Wala, dahil may turn lane"],"h1":"Hindi median ang center turn lane.","h2":"Sa Oklahoma, sa daang may apat o higit pang lane at walang median, dapat huminto ang mga sasakyan sa dalawang direksiyon para sa nakahintong school bus, kahit may center turn lane.","p":"Tama. Kapag walang median, lahat ay hihinto."},"ar":{"q":"في Oklahoma، توقّفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق من أربع حارات فيه حارة انعطاف في الوسط ولا يوجد فاصل وسطي (median). من يجب أن يتوقّف؟","o":["السيارات خلف الحافلة فقط","السيارات في الحارة المجاورة للحافلة فقط","كل السيارات في الاتجاهين","لا أحد، بسبب حارة الانعطاف"],"h1":"حارة الانعطاف في الوسط ليست فاصلًا وسطيًا.","h2":"في Oklahoma، على طريق من أربع حارات أو أكثر بدون فاصل وسطي، يجب على السيارات في الاتجاهين أن تتوقّف للحافلة المدرسية المتوقّفة، حتى لو كانت هناك حارة انعطاف في الوسط.","p":"صحيح. لا فاصل وسطي يعني أن الجميع يتوقّف."},"ref":{"doc":"OK","page":30}},{"id":"ok-013","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a school bus stops with red lights flashing on a road with a median. What must traffic going the opposite way do?","o":["Stop until the lights go off","Keep moving with caution","Stop, then pass at once","Change lanes toward the bus"],"h1":"The median separates the two sides of the road.","h2":"In Oklahoma, when a road has a median, traffic going the opposite way from the school bus may keep moving with caution, while traffic going the same way must stop.","p":"Right. With a median, oncoming traffic may continue with care."},"es":{"q":"En Oklahoma, un autobús escolar se detiene con luces rojas intermitentes en una calle con camellón. ¿Qué debe hacer el tráfico que va en dirección contraria?","o":["Detenerse hasta que se apaguen las luces","Seguir con precaución","Detenerse y luego pasar de inmediato","Cambiarse de carril hacia el autobús"],"h1":"El camellón separa los dos lados de la calle.","h2":"En Oklahoma, cuando la calle tiene camellón, el tráfico que va en dirección contraria al autobús escolar puede seguir con precaución, y el que va en la misma dirección debe detenerse.","p":"Correcto. Con camellón, el tráfico de frente puede seguir con cuidado."},"zh":{"q":"在 Oklahoma，一辆校车在有中间隔离带的路上停下，闪着红灯。相反方向的车必须怎么做？","o":["停车，直到灯熄灭","小心地继续开","停车，然后马上超过去","换到靠近校车的车道"],"h1":"中间隔离带把道路的两边分开。","h2":"在 Oklahoma，如果道路有中间隔离带，和校车方向相反的车可以小心地继续开，和校车同方向的车必须停车。","p":"对。有中间隔离带时，对面来的车可以小心地继续开。"},"vi":{"q":"Ở Oklahoma, một xe buýt trường học dừng lại với đèn đỏ nhấp nháy trên đường có dải phân cách. Xe đi ngược chiều phải làm gì?","o":["Dừng lại cho đến khi đèn tắt","Tiếp tục chạy một cách cẩn thận","Dừng lại, rồi vượt qua ngay","Chuyển làn về phía xe buýt"],"h1":"Dải phân cách chia hai bên đường ra.","h2":"Ở Oklahoma, khi đường có dải phân cách, xe đi ngược chiều với xe buýt trường học có thể tiếp tục chạy một cách cẩn thận, còn xe đi cùng chiều phải dừng lại.","p":"Đúng. Có dải phân cách thì xe ngược chiều có thể tiếp tục chạy cẩn thận."},"tl":{"q":"Sa Oklahoma, huminto ang isang school bus na kumikislap ang pulang ilaw sa daang may median. Ano ang dapat gawin ng mga sasakyang papunta sa kabilang direksiyon?","o":["Huminto hanggang mamatay ang ilaw","Magpatuloy nang maingat","Huminto, tapos lumampas agad","Lumipat ng lane papunta sa bus"],"h1":"Pinaghihiwalay ng median ang dalawang panig ng daan.","h2":"Sa Oklahoma, kapag may median ang daan, puwedeng magpatuloy nang maingat ang mga sasakyang papunta sa kabilang direksiyon ng school bus, pero dapat huminto ang mga sasakyang papunta sa parehong direksiyon.","p":"Tama. Kapag may median, puwedeng magpatuloy nang maingat ang mga paparating na sasakyan."},"ar":{"q":"في Oklahoma، توقّفت حافلة مدرسية وأضواؤها الحمراء تومض على طريق فيه فاصل وسطي (median). ماذا يجب أن تفعل السيارات القادمة من الاتجاه المعاكس؟","o":["تتوقّف حتى تنطفئ الأضواء","تستمر في السير بحذر","تتوقّف، ثم تتجاوز فورًا","تغيّر الحارة نحو الحافلة"],"h1":"الفاصل الوسطي يفصل بين جانبي الطريق.","h2":"في Oklahoma، عندما يكون في الطريق فاصل وسطي، يمكن للسيارات القادمة من الاتجاه المعاكس للحافلة المدرسية أن تستمر في السير بحذر، أما السيارات في نفس اتجاه الحافلة فيجب أن تتوقّف.","p":"صحيح. مع وجود فاصل وسطي، يمكن للسيارات القادمة أن تستمر بحذر."},"ref":{"doc":"OK","page":30}},{"id":"ok-014","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the speed limit on a turnpike when no other limit is posted?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Turnpikes have the highest limit in the state chart.","h2":"In Oklahoma, the speed limit on a turnpike is 80 mph unless a sign shows a different limit.","p":"Right. Oklahoma turnpikes allow 80 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una autopista de peaje (turnpike) cuando no hay otro límite señalado?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Las autopistas de peaje tienen el límite más alto de la tabla del estado.","h2":"En Oklahoma, el límite de velocidad en una autopista de peaje es de 80 mph, a menos que una señal indique otro límite.","p":"Correcto. En las autopistas de peaje de Oklahoma se permite 80 mph, salvo que se indique otra cosa."},"zh":{"q":"在 Oklahoma，如果没有标出别的限速，收费公路（turnpike）的限速是多少？","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"在州的限速表里，收费公路的限速最高。","h2":"在 Oklahoma，收费公路的限速是 80 mph，除非标志写着别的限速。","p":"对。Oklahoma 的收费公路限速是 80 mph，除非标志写着别的。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trên đường cao tốc thu phí (turnpike) là bao nhiêu khi không có biển báo giới hạn khác?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Đường cao tốc thu phí có giới hạn cao nhất trong bảng của tiểu bang.","h2":"Ở Oklahoma, tốc độ tối đa trên đường cao tốc thu phí là 80 mph, trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. Đường cao tốc thu phí ở Oklahoma cho phép 80 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa turnpike kapag walang ibang limit na nakapaskil?","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"Ang turnpike ang may pinakamataas na limit sa listahan ng estado.","h2":"Sa Oklahoma, 80 mph ang speed limit sa turnpike maliban kung may sign na nagpapakita ng ibang limit.","p":"Tama. Puwede ang 80 mph sa mga turnpike sa Oklahoma maliban kung iba ang nakapaskil."},"ar":{"q":"في Oklahoma، ما حدّ السرعة على الطريق السريع ذي الرسوم (turnpike) عندما لا توجد لافتة بحدّ آخر؟","o":["65 mph","70 mph","80 mph","85 mph"],"h1":"الطرق السريعة ذات الرسوم لها أعلى حدّ في جدول الولاية.","h2":"في Oklahoma، حدّ السرعة على الطريق السريع ذي الرسوم هو 80 mph، إلا إذا كانت هناك لافتة تُظهر حدًّا آخر.","p":"صحيح. الطرق السريعة ذات الرسوم في Oklahoma تسمح بـ 80 mph إلا إذا كانت هناك لافتة بحدّ آخر."},"ref":{"doc":"OK","page":41}},{"id":"ok-015","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the speed limit on a county road when no sign is posted?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than the limit on an undivided state highway.","h2":"In Oklahoma, the speed limit on a county road is 55 mph when no other limit is posted.","p":"Right. On Oklahoma county roads the limit is 55 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en un camino del condado cuando no hay señal?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es menor que el límite en una carretera estatal no dividida.","h2":"En Oklahoma, el límite de velocidad en un camino del condado es de 55 mph cuando no hay otro límite señalado.","p":"Correcto. En los caminos del condado de Oklahoma el límite es de 55 mph, salvo que se indique otra cosa."},"zh":{"q":"在 Oklahoma，如果没有限速标志，县道（county road）的限速是多少？","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"它比没有中间隔离带的州公路的限速低。","h2":"在 Oklahoma，如果没有标出别的限速，县道的限速是 55 mph。","p":"对。Oklahoma 县道的限速是 55 mph，除非标志写着别的。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trên đường quận (county road) là bao nhiêu khi không có biển báo?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó thấp hơn giới hạn trên đường tiểu bang không có dải phân cách.","h2":"Ở Oklahoma, tốc độ tối đa trên đường quận là 55 mph khi không có biển báo giới hạn khác.","p":"Đúng. Trên đường quận ở Oklahoma, giới hạn là 55 mph, trừ khi có biển báo khác."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa county road kapag walang sign na nakapaskil?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa limit sa state highway na walang divider.","h2":"Sa Oklahoma, 55 mph ang speed limit sa county road kapag walang ibang limit na nakapaskil.","p":"Tama. Sa mga county road sa Oklahoma, 55 mph ang limit maliban kung iba ang nakapaskil."},"ar":{"q":"في Oklahoma، ما حدّ السرعة على طريق المقاطعة (county road) عندما لا توجد لافتة؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هو أقل من الحدّ على طريق الولاية السريع الذي ليس فيه فاصل وسطي.","h2":"في Oklahoma، حدّ السرعة على طريق المقاطعة هو 55 mph عندما لا توجد لافتة بحدّ آخر.","p":"صحيح. على طرق المقاطعات في Oklahoma الحدّ هو 55 mph إلا إذا كانت هناك لافتة بحدّ آخر."},"ref":{"doc":"OK","page":41}},{"id":"ok-016","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, how many points on your driving record will lead to a license suspension?","o":["6 or more in 1 year","10 or more in 5 years","8 or more in 5 years","15 or more in 10 years"],"h1":"Count the points over several years, not just one.","h2":"In Oklahoma, your license will be suspended if you get 10 or more points within 5 years.","p":"Right. 10 or more points in 5 years means a suspension in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuántos puntos en su historial de manejo causan la suspensión de la licencia?","o":["6 o más en 1 año","10 o más en 5 años","8 o más en 5 años","15 o más en 10 años"],"h1":"Los puntos se cuentan durante varios años, no solo uno.","h2":"En Oklahoma, su licencia será suspendida si acumula 10 puntos o más en 5 años.","p":"Correcto. 10 puntos o más en 5 años significan una suspensión en Oklahoma."},"zh":{"q":"在 Oklahoma，驾驶记录上有多少分会导致驾照被暂停？","o":["1 年内 6 分或更多","5 年内 10 分或更多","5 年内 8 分或更多","10 年内 15 分或更多"],"h1":"要算好几年里的分数，不只是一年。","h2":"在 Oklahoma，如果你在 5 年内被记 10 分或更多，你的驾照会被暂停。","p":"对。在 Oklahoma，5 年内 10 分或更多就会被暂停驾照。"},"vi":{"q":"Ở Oklahoma, bao nhiêu điểm trong hồ sơ lái xe sẽ dẫn đến việc bị treo bằng lái?","o":["6 điểm trở lên trong 1 năm","10 điểm trở lên trong 5 năm","8 điểm trở lên trong 5 năm","15 điểm trở lên trong 10 năm"],"h1":"Hãy đếm điểm trong nhiều năm, không chỉ một năm.","h2":"Ở Oklahoma, bằng lái của bạn sẽ bị treo nếu bạn bị 10 điểm trở lên trong vòng 5 năm.","p":"Đúng. Ở Oklahoma, 10 điểm trở lên trong 5 năm nghĩa là bị treo bằng."},"tl":{"q":"Sa Oklahoma, ilang puntos sa driving record mo ang magdudulot ng suspensiyon ng lisensiya?","o":["6 o higit pa sa loob ng 1 taon","10 o higit pa sa loob ng 5 taon","8 o higit pa sa loob ng 5 taon","15 o higit pa sa loob ng 10 taon"],"h1":"Bilangin ang puntos sa loob ng ilang taon, hindi lang isa.","h2":"Sa Oklahoma, masususpinde ang lisensiya mo kung makakuha ka ng 10 o higit pang puntos sa loob ng 5 taon.","p":"Tama. Sa Oklahoma, ang 10 o higit pang puntos sa loob ng 5 taon ay nangangahulugang suspensiyon."},"ar":{"q":"في Oklahoma، كم نقطة في سجلّ قيادتك تؤدي إلى إيقاف الرخصة؟","o":["6 نقاط أو أكثر خلال سنة واحدة","10 نقاط أو أكثر خلال 5 سنوات","8 نقاط أو أكثر خلال 5 سنوات","15 نقطة أو أكثر خلال 10 سنوات"],"h1":"احسب النقاط على مدى عدة سنوات، وليس سنة واحدة فقط.","h2":"في Oklahoma، سيتم إيقاف رخصتك إذا حصلت على 10 نقاط أو أكثر خلال 5 سنوات.","p":"صحيح. في Oklahoma، 10 نقاط أو أكثر خلال 5 سنوات تعني إيقاف الرخصة."},"ref":{"doc":"OK","page":71}},{"id":"ok-017","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many points are added to your record for not stopping for a school bus that is loading or unloading?","o":["1 point","2 points","3 points","4 points"],"h1":"It is one of the most serious offenses on the point list.","h2":"In Oklahoma, failing to stop for a school bus that is loading or unloading adds 4 points to your record.","p":"Right. Not stopping for a loading school bus costs 4 points in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuántos puntos se agregan a su historial por no detenerse ante un autobús escolar que sube o baja estudiantes?","o":["1 punto","2 puntos","3 puntos","4 puntos"],"h1":"Es una de las faltas más graves de la lista de puntos.","h2":"En Oklahoma, no detenerse ante un autobús escolar que sube o baja estudiantes agrega 4 puntos a su historial.","p":"Correcto. No detenerse ante un autobús escolar cuesta 4 puntos en Oklahoma."},"zh":{"q":"在 Oklahoma，校车正在上下学生时你没有停车，记录上会加几分？","o":["1 分","2 分","3 分","4 分"],"h1":"这是记分表上最严重的违规之一。","h2":"在 Oklahoma，校车正在上下学生时没有停车，你的记录上会加 4 分。","p":"对。在 Oklahoma，校车上下学生时不停车要扣 4 分。"},"vi":{"q":"Ở Oklahoma, nếu không dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống, bạn bị cộng bao nhiêu điểm vào hồ sơ?","o":["1 điểm","2 điểm","3 điểm","4 điểm"],"h1":"Đây là một trong những vi phạm nghiêm trọng nhất trong danh sách tính điểm.","h2":"Ở Oklahoma, không dừng lại khi xe buýt trường học đang cho học sinh lên hoặc xuống sẽ bị cộng 4 điểm vào hồ sơ của bạn.","p":"Đúng. Ở Oklahoma, không dừng cho xe buýt trường học đang đón trả học sinh bị 4 điểm."},"tl":{"q":"Sa Oklahoma, ilang puntos ang idinadagdag sa iyong record kapag hindi ka huminto para sa school bus na nagsasakay o nagbababa ng mga bata?","o":["1 puntos","2 puntos","3 puntos","4 puntos"],"h1":"Isa ito sa pinakamabibigat na paglabag sa listahan ng puntos.","h2":"Sa Oklahoma, ang hindi paghinto para sa school bus na nagsasakay o nagbababa ng mga bata ay nagdadagdag ng 4 na puntos sa iyong record.","p":"Tama. Sa Oklahoma, 4 na puntos ang hindi paghinto para sa school bus na nagsasakay o nagbababa."},"ar":{"q":"في Oklahoma، كم نقطة تُضاف إلى سجلّك إذا لم تتوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها؟","o":["نقطة واحدة","نقطتان","3 نقاط","4 نقاط"],"h1":"هي من أخطر المخالفات في قائمة النقاط.","h2":"في Oklahoma، عدم التوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يضيف 4 نقاط إلى سجلّك.","p":"صحيح. عدم التوقّف لحافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يكلّف 4 نقاط في Oklahoma."},"ref":{"doc":"OK","page":71}},{"id":"ok-018","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how can points come off your driving record over time?","o":["2 points for each year with no convictions","1 point for each month with no tickets","All points after 6 months","Points never come off"],"h1":"A clean year helps you.","h2":"In Oklahoma, 2 points come off your record for each 12-month period with no convictions for pointable violations.","p":"Right. Each year with no pointable convictions removes 2 points in Oklahoma."},"es":{"q":"En Oklahoma, ¿cómo se pueden quitar puntos de su historial de manejo con el tiempo?","o":["2 puntos por cada año sin condenas","1 punto por cada mes sin multas","Todos los puntos después de 6 meses","Los puntos nunca se quitan"],"h1":"Un año sin faltas le ayuda.","h2":"En Oklahoma, se quitan 2 puntos de su historial por cada período de 12 meses sin condenas por infracciones con puntos.","p":"Correcto. Cada año sin condenas con puntos quita 2 puntos en Oklahoma."},"zh":{"q":"在 Oklahoma，驾驶记录上的分数怎样会随着时间被去掉？","o":["每一年没有定罪，去掉 2 分","每一个月没有罚单，去掉 1 分","6 个月后去掉所有分数","分数永远不会去掉"],"h1":"干净的一年对你有帮助。","h2":"在 Oklahoma，每 12 个月没有因要记分的违规被定罪，你的记录上会去掉 2 分。","p":"对。在 Oklahoma，每一年没有要记分的定罪，就去掉 2 分。"},"vi":{"q":"Ở Oklahoma, điểm trong hồ sơ lái xe có thể được xóa theo thời gian như thế nào?","o":["2 điểm cho mỗi năm không bị kết tội","1 điểm cho mỗi tháng không bị phạt","Tất cả điểm sau 6 tháng","Điểm không bao giờ được xóa"],"h1":"Một năm không vi phạm sẽ giúp bạn.","h2":"Ở Oklahoma, cứ mỗi 12 tháng không bị kết tội vì vi phạm có tính điểm, hồ sơ của bạn được xóa 2 điểm.","p":"Đúng. Ở Oklahoma, mỗi năm không bị kết tội vi phạm có tính điểm sẽ được xóa 2 điểm."},"tl":{"q":"Sa Oklahoma, paano natatanggal ang mga puntos sa iyong driving record sa paglipas ng panahon?","o":["2 puntos sa bawat taon na walang conviction","1 puntos sa bawat buwan na walang ticket","Lahat ng puntos pagkalipas ng 6 na buwan","Hindi kailanman natatanggal ang mga puntos"],"h1":"Nakakatulong sa iyo ang isang malinis na taon.","h2":"Sa Oklahoma, natatanggal ang 2 puntos sa iyong record sa bawat 12 buwan na walang conviction para sa paglabag na may puntos.","p":"Tama. Sa Oklahoma, bawat taon na walang conviction na may puntos ay nag-aalis ng 2 puntos."},"ar":{"q":"في Oklahoma، كيف يمكن أن تُزال النقاط من سجلّ القيادة مع الوقت؟","o":["نقطتان عن كل سنة بدون إدانات","نقطة واحدة عن كل شهر بدون مخالفات","كل النقاط بعد 6 أشهر","النقاط لا تُزال أبدًا"],"h1":"السنة النظيفة تساعدك.","h2":"في Oklahoma، تُزال نقطتان من سجلّك عن كل فترة 12 شهرًا بدون إدانات بمخالفات عليها نقاط.","p":"صحيح. كل سنة بدون إدانات بمخالفات عليها نقاط تُزيل نقطتين في Oklahoma."},"ref":{"doc":"OK","page":72}},{"id":"ok-019","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, what are the minimum amounts of liability insurance a driver must carry?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"The amount for two or more people is twice the amount for one person.","h2":"In Oklahoma, the minimum liability insurance is $25,000 for one person, $50,000 for two or more people, and $25,000 for property damage.","p":"Right. Oklahoma requires at least $25,000, $50,000 and $25,000 of liability coverage."},"es":{"q":"En Oklahoma, ¿cuáles son los montos mínimos del seguro de responsabilidad civil que debe tener un conductor?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"El monto para dos o más personas es el doble del monto para una persona.","h2":"En Oklahoma, el seguro de responsabilidad civil mínimo es de $25,000 por una persona, $50,000 por dos o más personas y $25,000 por daños a la propiedad.","p":"Correcto. Oklahoma exige como mínimo $25,000, $50,000 y $25,000 de cobertura de responsabilidad civil."},"zh":{"q":"在 Oklahoma，司机必须买的责任保险（liability insurance）最低金额是多少？","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"两人或以上的金额是一人金额的两倍。","h2":"在 Oklahoma，最低责任保险是：一人 $25,000，两人或以上 $50,000，财产损失 $25,000。","p":"对。Oklahoma 要求至少 $25,000、$50,000 和 $25,000 的责任保险。"},"vi":{"q":"Ở Oklahoma, số tiền bảo hiểm trách nhiệm (liability insurance) tối thiểu mà người lái xe phải có là bao nhiêu?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Số tiền cho hai người trở lên gấp đôi số tiền cho một người.","h2":"Ở Oklahoma, bảo hiểm trách nhiệm tối thiểu là $25,000 cho một người, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Oklahoma yêu cầu bảo hiểm trách nhiệm ít nhất $25,000, $50,000 và $25,000."},"tl":{"q":"Sa Oklahoma, ano ang pinakamababang halaga ng liability insurance na dapat mayroon ang isang driver?","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"Ang halaga para sa dalawa o higit pang tao ay doble ng halaga para sa isang tao.","h2":"Sa Oklahoma, ang pinakamababang liability insurance ay $25,000 para sa isang tao, $50,000 para sa dalawa o higit pang tao, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Hinihingi ng Oklahoma ang hindi bababa sa $25,000, $50,000 at $25,000 na liability coverage."},"ar":{"q":"في Oklahoma، ما الحدّ الأدنى لمبالغ تأمين المسؤولية (liability insurance) الذي يجب أن يكون عند السائق؟","o":["$10,000 / $20,000 / $10,000","$15,000 / $30,000 / $15,000","$25,000 / $50,000 / $25,000","$50,000 / $100,000 / $50,000"],"h1":"المبلغ لشخصين أو أكثر هو ضعف المبلغ لشخص واحد.","h2":"في Oklahoma، الحدّ الأدنى لتأمين المسؤولية هو $25,000 لشخص واحد، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. Oklahoma تطلب تغطية مسؤولية لا تقل عن $25,000 و$50,000 و$25,000."},"ref":{"doc":"OK","page":72}},{"id":"ok-020","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, what can happen if you cannot show proof of insurance to an officer who asks for it?","o":["A written warning, the first time only","A fine up to $250, possible jail, and suspension","A $25 fine, with no other penalty","A new written and driving test"],"h1":"The penalty affects both your license and your car's registration.","h2":"In Oklahoma, not showing proof of insurance when an officer asks can bring a fine of up to $250, up to 30 days in jail, and suspension of your license and registration.","p":"Right. In Oklahoma it can mean a fine up to $250, jail up to 30 days, and a suspended license and registration."},"es":{"q":"En Oklahoma, ¿qué puede pasar si no puede mostrar prueba de seguro a un oficial que se la pide?","o":["Una advertencia por escrito, solo la primera vez","Una multa de hasta $250, posible cárcel y suspensión","Una multa de $25, sin otra sanción","Repetir el examen escrito y el de manejo"],"h1":"La sanción afecta tanto su licencia como el registro de su carro.","h2":"En Oklahoma, no mostrar prueba de seguro cuando un oficial la pide puede causar una multa de hasta $250, hasta 30 días de cárcel y la suspensión de su licencia y registro.","p":"Correcto. En Oklahoma puede significar una multa de hasta $250, hasta 30 días de cárcel y la suspensión de la licencia y el registro."},"zh":{"q":"在 Oklahoma，如果警察要你出示保险证明而你拿不出来，会怎么样？","o":["书面警告，只限第一次","最高 $250 罚款，可能坐牢，并被暂停","$25 罚款，没有别的处罚","重新考笔试和路考"],"h1":"这个处罚会影响你的驾照，也会影响你的车辆登记。","h2":"在 Oklahoma，警察要求时拿不出保险证明，可能被罚款最高 $250，坐牢最多 30 天，驾照和车辆登记也会被暂停。","p":"对。在 Oklahoma，这可能是最高 $250 罚款、最多 30 天坐牢，以及驾照和车辆登记被暂停。"},"vi":{"q":"Ở Oklahoma, điều gì có thể xảy ra nếu bạn không đưa ra được giấy tờ chứng minh bảo hiểm khi cảnh sát yêu cầu?","o":["Cảnh cáo bằng văn bản, chỉ lần đầu tiên","Phạt đến $250, có thể bị tù, và bị đình chỉ","Phạt $25, không có hình phạt nào khác","Phải thi lại bài thi viết và bài thi lái xe"],"h1":"Hình phạt ảnh hưởng cả bằng lái lẫn giấy đăng ký xe của bạn.","h2":"Ở Oklahoma, không đưa ra được giấy tờ chứng minh bảo hiểm khi cảnh sát yêu cầu có thể bị phạt đến $250, bị tù đến 30 ngày, và bị đình chỉ bằng lái và giấy đăng ký xe.","p":"Đúng. Ở Oklahoma, có thể bị phạt đến $250, bị tù đến 30 ngày, và bị đình chỉ bằng lái và giấy đăng ký xe."},"tl":{"q":"Sa Oklahoma, ano ang puwedeng mangyari kung hindi mo maipakita ang proof of insurance sa pulis na humihingi nito?","o":["Isang nakasulat na babala, sa unang beses lang","Multang hanggang $250, posibleng kulong, at suspensiyon","Multang $25, walang ibang parusa","Bagong written test at driving test"],"h1":"Naaapektuhan ng parusa ang iyong lisensiya at ang registration ng iyong sasakyan.","h2":"Sa Oklahoma, ang hindi pagpapakita ng proof of insurance kapag hiningi ng pulis ay puwedeng magresulta sa multang hanggang $250, kulong nang hanggang 30 araw, at suspensiyon ng iyong lisensiya at registration.","p":"Tama. Sa Oklahoma, puwede itong mangahulugan ng multang hanggang $250, kulong nang hanggang 30 araw, at suspendidong lisensiya at registration."},"ar":{"q":"في Oklahoma، ماذا يمكن أن يحدث إذا لم تستطع أن تُظهر إثبات التأمين لشرطي يطلبه منك؟","o":["إنذار مكتوب، في المرة الأولى فقط","غرامة حتى $250، وسجن محتمل، وإيقاف","غرامة $25، بدون أي عقوبة أخرى","اختبار كتابي واختبار قيادة جديدان"],"h1":"العقوبة تؤثّر على رخصتك وعلى تسجيل سيارتك معًا.","h2":"في Oklahoma، عدم إظهار إثبات التأمين عندما يطلبه الشرطي يمكن أن يؤدّي إلى غرامة حتى $250، وسجن حتى 30 يومًا، وإيقاف رخصتك وتسجيل سيارتك.","p":"صحيح. في Oklahoma يمكن أن يعني ذلك غرامة حتى $250، وسجنًا حتى 30 يومًا، وإيقاف الرخصة وتسجيل السيارة."},"ref":{"doc":"OK","page":72}},{"id":"ok-021","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, the child passenger restraint law covers children up to what age?","o":["Under 3","Under 12","Under 16","Under 8"],"h1":"Think of a child in about second or third grade.","h2":"In Oklahoma, the child passenger restraint law covers every child under 8. A child under 8 must ride in a child safety seat or booster seat unless the child is taller than 4 feet 9 inches.","p":"Right. Oklahoma's child restraint law covers children under 8."},"es":{"q":"En Oklahoma, ¿hasta qué edad cubre la ley de sistemas de retención infantil?","o":["Menores de 3","Menores de 12","Menores de 16","Menores de 8"],"h1":"Piense en un niño de segundo o tercer grado, más o menos.","h2":"En Oklahoma, la ley de sistemas de retención infantil cubre a todo niño menor de 8 años. Un niño menor de 8 años debe ir en una silla de seguridad o un asiento elevador, a menos que mida más de 4 pies 9 pulgadas.","p":"Correcto. La ley de retención infantil de Oklahoma cubre a los niños menores de 8 años."},"zh":{"q":"在 Oklahoma，儿童乘客安全约束法适用于多大以下的孩子？","o":["3 岁以下","12 岁以下","16 岁以下","8 岁以下"],"h1":"想一想大约上二年级或三年级的孩子。","h2":"在 Oklahoma，儿童乘客安全约束法适用于每个 8 岁以下的孩子。8 岁以下的孩子必须坐儿童安全座椅或增高座椅，除非孩子身高超过 4 英尺 9 英寸。","p":"对。Oklahoma 的儿童安全约束法适用于 8 岁以下的孩子。"},"vi":{"q":"Ở Oklahoma, luật về ghế an toàn cho trẻ em áp dụng cho trẻ em đến bao nhiêu tuổi?","o":["Dưới 3 tuổi","Dưới 12 tuổi","Dưới 16 tuổi","Dưới 8 tuổi"],"h1":"Hãy nghĩ đến một đứa trẻ khoảng lớp hai hoặc lớp ba.","h2":"Ở Oklahoma, luật về ghế an toàn cho trẻ em áp dụng cho mọi trẻ em dưới 8 tuổi. Trẻ em dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng, trừ khi trẻ cao hơn 4 feet 9 inch.","p":"Đúng. Luật về ghế an toàn cho trẻ em của Oklahoma áp dụng cho trẻ em dưới 8 tuổi."},"tl":{"q":"Sa Oklahoma, hanggang anong edad ng bata sakop ang batas sa child passenger restraint?","o":["Wala pang 3","Wala pang 12","Wala pang 16","Wala pang 8"],"h1":"Isipin ang batang nasa mga ikalawa o ikatlong baitang.","h2":"Sa Oklahoma, sakop ng batas sa child passenger restraint ang bawat batang wala pang 8. Ang batang wala pang 8 ay dapat nakaupo sa child safety seat o booster seat, maliban kung mas matangkad ang bata sa 4 feet 9 inches.","p":"Tama. Sakop ng batas sa child restraint ng Oklahoma ang mga batang wala pang 8."},"ar":{"q":"في Oklahoma، حتى أي عمر يشمل قانون مقاعد أمان الأطفال الركّاب الأطفالَ؟","o":["أقل من 3","أقل من 12","أقل من 16","أقل من 8"],"h1":"فكّر في طفل في الصف الثاني أو الثالث تقريبًا.","h2":"في Oklahoma، يشمل قانون مقاعد أمان الأطفال الركّاب كل طفل عمره أقل من 8 سنوات. يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال أو مقعد رافع، إلا إذا كان طول الطفل أكثر من 4 أقدام و9 بوصات.","p":"صحيح. قانون مقاعد أمان الأطفال في Oklahoma يشمل الأطفال الذين عمرهم أقل من 8 سنوات."},"ref":{"doc":"OK","page":17}},{"id":"ok-022","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, until what age must a child ride in a rear-facing car seat, unless the child outgrows the seat's height or weight limit?","o":["2 years","1 year","3 years","4 years"],"h1":"It is before the child turns 3.","h2":"In Oklahoma, a child must ride in a rear-facing car seat until age 2, or until the child reaches the seat maker's height or weight limit.","p":"Right. In Oklahoma a child rides rear-facing until age 2 or until outgrowing the seat."},"es":{"q":"En Oklahoma, ¿hasta qué edad debe viajar un niño en un asiento orientado hacia atrás, a menos que supere el límite de altura o peso del asiento?","o":["2 años","1 año","3 años","4 años"],"h1":"Es antes de que el niño cumpla 3 años.","h2":"En Oklahoma, un niño debe viajar en un asiento orientado hacia atrás hasta los 2 años, o hasta que alcance el límite de altura o peso que fija el fabricante.","p":"Correcto. En Oklahoma un niño viaja mirando hacia atrás hasta los 2 años o hasta que el asiento le quede pequeño."},"zh":{"q":"在 Oklahoma，除非孩子超过了座椅的身高或体重限制，孩子必须坐后向安全座椅到几岁？","o":["2 岁","1 岁","3 岁","4 岁"],"h1":"是在孩子满 3 岁之前。","h2":"在 Oklahoma，孩子必须坐后向安全座椅到 2 岁，或者到孩子达到座椅制造商的身高或体重限制。","p":"对。在 Oklahoma，孩子坐后向座椅到 2 岁，或者到长大超过座椅的限制。"},"vi":{"q":"Ở Oklahoma, trẻ em phải ngồi ghế ô tô quay mặt về phía sau đến bao nhiêu tuổi, trừ khi trẻ đã vượt quá giới hạn chiều cao hoặc cân nặng của ghế?","o":["2 tuổi","1 tuổi","3 tuổi","4 tuổi"],"h1":"Đó là trước khi trẻ được 3 tuổi.","h2":"Ở Oklahoma, trẻ em phải ngồi ghế ô tô quay mặt về phía sau đến 2 tuổi, hoặc đến khi trẻ đạt giới hạn chiều cao hoặc cân nặng của nhà sản xuất ghế.","p":"Đúng. Ở Oklahoma, trẻ ngồi ghế quay về phía sau đến 2 tuổi hoặc đến khi lớn hơn giới hạn của ghế."},"tl":{"q":"Sa Oklahoma, hanggang ilang taong gulang dapat nakasakay ang bata sa rear-facing car seat, maliban kung lumampas na ang bata sa height o weight limit ng upuan?","o":["2 taon","1 taon","3 taon","4 na taon"],"h1":"Bago ito mag-3 taong gulang ang bata.","h2":"Sa Oklahoma, dapat nakasakay ang bata sa rear-facing car seat hanggang 2 taong gulang, o hanggang maabot ng bata ang height o weight limit ng gumawa ng upuan.","p":"Tama. Sa Oklahoma, rear-facing ang bata hanggang 2 taong gulang o hanggang lumaki na siya para sa upuan."},"ar":{"q":"في Oklahoma، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف، إلا إذا تجاوز الطفل حدّ الطول أو الوزن للمقعد؟","o":["سنتان","سنة واحدة","3 سنوات","4 سنوات"],"h1":"هو قبل أن يبلغ الطفل 3 سنوات.","h2":"في Oklahoma، يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف حتى عمر سنتين، أو حتى يصل إلى حدّ الطول أو الوزن الذي حدّده صانع المقعد.","p":"صحيح. في Oklahoma يجلس الطفل مواجهًا للخلف حتى عمر سنتين أو حتى يكبر على المقعد."},"ref":{"doc":"OK","page":17}},{"id":"ok-023","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, how early may you renew your driver license before it expires?","o":["30 days","90 days","1 year","2 years"],"h1":"You have quite a long time to do it.","h2":"In Oklahoma, you may renew your driver license up to 1 year before it expires.","p":"Right. Oklahoma lets you renew up to 1 year early."},"es":{"q":"En Oklahoma, ¿con cuánta anticipación puede renovar su licencia de manejo antes de que venza?","o":["30 días","90 días","1 año","2 años"],"h1":"Tiene bastante tiempo para hacerlo.","h2":"En Oklahoma, puede renovar su licencia de manejo hasta 1 año antes de que venza.","p":"Correcto. Oklahoma le permite renovar hasta 1 año antes."},"zh":{"q":"在 Oklahoma，驾照到期前最早可以提前多久续期？","o":["30 天","90 天","1 年","2 年"],"h1":"你有相当长的时间可以办。","h2":"在 Oklahoma，你最早可以在驾照到期前 1 年续期。","p":"对。Oklahoma 让你最早提前 1 年续期。"},"vi":{"q":"Ở Oklahoma, bạn có thể gia hạn bằng lái sớm nhất bao lâu trước khi hết hạn?","o":["30 ngày","90 ngày","1 năm","2 năm"],"h1":"Bạn có khá nhiều thời gian để làm việc này.","h2":"Ở Oklahoma, bạn có thể gia hạn bằng lái sớm nhất là 1 năm trước khi hết hạn.","p":"Đúng. Oklahoma cho phép gia hạn sớm nhất là 1 năm."},"tl":{"q":"Sa Oklahoma, gaano kaaga mo puwedeng i-renew ang iyong driver license bago ito mag-expire?","o":["30 araw","90 araw","1 taon","2 taon"],"h1":"Medyo mahaba ang panahon mo para gawin ito.","h2":"Sa Oklahoma, puwede mong i-renew ang iyong driver license hanggang 1 taon bago ito mag-expire.","p":"Tama. Pinapayagan ka ng Oklahoma na mag-renew hanggang 1 taon nang maaga."},"ar":{"q":"في Oklahoma، كم من الوقت قبل انتهاء رخصة القيادة يمكنك أن تجدّدها؟","o":["30 يومًا","90 يومًا","سنة واحدة","سنتان"],"h1":"عندك وقت طويل نوعًا ما لتفعل ذلك.","h2":"في Oklahoma، يمكنك أن تجدّد رخصة القيادة قبل انتهائها بمدة تصل إلى سنة واحدة.","p":"صحيح. Oklahoma تسمح لك بالتجديد قبل الموعد بمدة تصل إلى سنة واحدة."},"ref":{"doc":"OK","page":13}},{"id":"ok-024","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, after you move, how soon must you tell Service Oklahoma your new address?","o":["Within 5 days","Within 10 days","Within 30 days","Within 60 days"],"h1":"It is less than two weeks.","h2":"In Oklahoma, you must tell Service Oklahoma your new address within 10 days after you move.","p":"Right. Oklahoma drivers must report a new address within 10 days."},"es":{"q":"En Oklahoma, después de mudarse, ¿en cuánto tiempo debe informar su nueva dirección a Service Oklahoma?","o":["En 5 días","En 10 días","En 30 días","En 60 días"],"h1":"Es menos de dos semanas.","h2":"En Oklahoma, debe informar su nueva dirección a Service Oklahoma dentro de los 10 días después de mudarse.","p":"Correcto. Los conductores de Oklahoma deben informar su nueva dirección en 10 días."},"zh":{"q":"在 Oklahoma，你搬家以后，必须在多久内把新地址告诉 Service Oklahoma？","o":["5 天内","10 天内","30 天内","60 天内"],"h1":"不到两个星期。","h2":"在 Oklahoma，你搬家以后必须在 10 天内把新地址告诉 Service Oklahoma。","p":"对。Oklahoma 的司机必须在 10 天内报告新地址。"},"vi":{"q":"Ở Oklahoma, sau khi chuyển nhà, bạn phải báo địa chỉ mới cho Service Oklahoma trong bao lâu?","o":["Trong vòng 5 ngày","Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày"],"h1":"Ít hơn hai tuần.","h2":"Ở Oklahoma, bạn phải báo địa chỉ mới cho Service Oklahoma trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Người lái xe ở Oklahoma phải báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Oklahoma, pagkatapos mong lumipat, gaano kabilis mo dapat sabihin sa Service Oklahoma ang iyong bagong address?","o":["Sa loob ng 5 araw","Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa Oklahoma, dapat mong sabihin sa Service Oklahoma ang iyong bagong address sa loob ng 10 araw pagkatapos mong lumipat.","p":"Tama. Dapat i-report ng mga driver sa Oklahoma ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Oklahoma، بعد أن تنتقل إلى بيت جديد، خلال كم من الوقت يجب أن تُبلغ Service Oklahoma بعنوانك الجديد؟","o":["خلال 5 أيام","خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا"],"h1":"هي أقل من أسبوعين.","h2":"في Oklahoma، يجب أن تُبلغ Service Oklahoma بعنوانك الجديد خلال 10 أيام بعد أن تنتقل.","p":"صحيح. يجب على السائقين في Oklahoma أن يُبلغوا عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"OK","page":13}},{"id":"ok-025","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what happens if you refuse a breath or blood test when a police officer asks?","o":["Nothing, if you have not been drinking","You get a warning the first time","You pay a small fine only","Your driving privilege is automatically revoked"],"h1":"By driving, you have already agreed to be tested.","h2":"In Oklahoma, refusing a breath or blood test leads to automatic revocation of your driving privilege, even if you have not been drinking.","p":"Right. In Oklahoma a refusal means your license is revoked automatically."},"es":{"q":"En Oklahoma, ¿qué pasa si se niega a una prueba de aliento o de sangre cuando un oficial de policía se la pide?","o":["Nada, si no ha tomado alcohol","Recibe una advertencia la primera vez","Solo paga una multa pequeña","Su privilegio de manejar se revoca automáticamente"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"En Oklahoma, negarse a una prueba de aliento o de sangre causa la revocación automática de su privilegio de manejar, aunque no haya tomado alcohol.","p":"Correcto. En Oklahoma, negarse significa que su licencia se revoca automáticamente."},"zh":{"q":"在 Oklahoma，警察要求你做呼气或验血测试时，如果你拒绝，会怎么样？","o":["如果你没喝酒，就没事","第一次会得到警告","只要付一点小罚款","你的驾驶资格会被自动吊销"],"h1":"你开车时，就已经同意接受测试了。","h2":"在 Oklahoma，拒绝做呼气或验血测试，你的驾驶资格会被自动吊销，就算你没有喝酒也一样。","p":"对。在 Oklahoma，拒绝测试意味着你的驾照会被自动吊销。"},"vi":{"q":"Ở Oklahoma, điều gì xảy ra nếu bạn từ chối kiểm tra hơi thở hoặc thử máu khi cảnh sát yêu cầu?","o":["Không sao, nếu bạn không uống rượu","Bạn bị cảnh cáo lần đầu tiên","Bạn chỉ phải trả một khoản phạt nhỏ","Quyền lái xe của bạn bị tự động thu hồi"],"h1":"Khi lái xe, bạn đã đồng ý để được kiểm tra.","h2":"Ở Oklahoma, từ chối kiểm tra hơi thở hoặc thử máu sẽ làm quyền lái xe của bạn bị tự động thu hồi, ngay cả khi bạn không uống rượu.","p":"Đúng. Ở Oklahoma, từ chối kiểm tra nghĩa là bằng lái của bạn bị tự động thu hồi."},"tl":{"q":"Sa Oklahoma, ano ang mangyayari kung tumanggi ka sa breath test o blood test kapag hiningi ito ng pulis?","o":["Wala, kung hindi ka uminom","Babala lang sa unang beses","Maliit na multa lang ang babayaran mo","Awtomatikong babawiin ang iyong pribilehiyong magmaneho"],"h1":"Sa pagmamaneho, pumayag ka na na ma-test.","h2":"Sa Oklahoma, ang pagtanggi sa breath test o blood test ay nagdudulot ng awtomatikong pagbawi ng iyong pribilehiyong magmaneho, kahit hindi ka uminom.","p":"Tama. Sa Oklahoma, kapag tumanggi ka, awtomatikong babawiin ang iyong lisensiya."},"ar":{"q":"في Oklahoma، ماذا يحدث إذا رفضت فحص النفَس أو فحص الدم عندما يطلبه منك الشرطي؟","o":["لا شيء، إذا لم تكن قد شربت","تحصل على إنذار في المرة الأولى","تدفع غرامة صغيرة فقط","يُسحب حقّك في القيادة تلقائيًا"],"h1":"بمجرّد أن تقود، فأنت قد وافقت مسبقًا على الفحص.","h2":"في Oklahoma، رفض فحص النفَس أو فحص الدم يؤدّي إلى سحب حقّك في القيادة تلقائيًا، حتى لو لم تكن قد شربت.","p":"صحيح. في Oklahoma الرفض يعني أن رخصتك تُسحب تلقائيًا."},"ref":{"doc":"OK","page":65}},{"id":"ok-026","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you hit a parked car and cannot find the owner. What must you do?","o":["Leave your name, address and insurance information where the owner will find it","Drive away if the damage looks small and minor","Wait next to the parked car until the next day","Call the owner's insurance company to report it"],"h1":"The owner needs a way to reach you.","h2":"In Oklahoma, if you hit a parked car and cannot find the owner, you must leave the driver's and owner's name and address and your insurance information on the damaged car.","p":"Right. In Oklahoma you leave your name, address and insurance details where the owner will see them."},"es":{"q":"En Oklahoma, usted choca contra un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Dejar su nombre, dirección e información del seguro donde el dueño la encuentre","Irse si el daño parece pequeño y sin importancia","Esperar junto al carro estacionado hasta el día siguiente","Llamar a la compañía de seguros del dueño para avisar"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Oklahoma, si choca contra un carro estacionado y no encuentra al dueño, debe dejar el nombre y la dirección del conductor y del dueño, y la información de su seguro, en el carro dañado.","p":"Correcto. En Oklahoma usted deja su nombre, dirección y datos del seguro donde el dueño los vea."},"zh":{"q":"在 Oklahoma，你撞到一辆停着的车，找不到车主。你必须怎么做？","o":["把你的姓名、地址和保险信息留在车主会看到的地方","如果损坏看起来很小，就开走","在停着的车旁边等到第二天","打电话给车主的保险公司报告"],"h1":"车主需要有办法联系你。","h2":"在 Oklahoma，如果你撞到一辆停着的车，又找不到车主，你必须在被撞的车上留下司机和车主的姓名、地址，以及你的保险信息。","p":"对。在 Oklahoma，你要把你的姓名、地址和保险信息留在车主会看到的地方。"},"vi":{"q":"Ở Oklahoma, bạn đâm vào một xe đang đậu và không tìm được chủ xe. Bạn phải làm gì?","o":["Để lại tên, địa chỉ và thông tin bảo hiểm của bạn ở nơi chủ xe sẽ thấy","Lái đi nếu hư hỏng có vẻ nhỏ và không đáng kể","Chờ bên cạnh xe đang đậu đến ngày hôm sau","Gọi cho công ty bảo hiểm của chủ xe để báo"],"h1":"Chủ xe cần có cách liên lạc với bạn.","h2":"Ở Oklahoma, nếu bạn đâm vào một xe đang đậu và không tìm được chủ xe, bạn phải để lại tên và địa chỉ của người lái và của chủ xe, cùng thông tin bảo hiểm của bạn, trên chiếc xe bị hư hỏng.","p":"Đúng. Ở Oklahoma, bạn để lại tên, địa chỉ và thông tin bảo hiểm ở nơi chủ xe sẽ thấy."},"tl":{"q":"Sa Oklahoma, nabangga mo ang isang nakaparadang sasakyan at hindi mo makita ang may-ari. Ano ang dapat mong gawin?","o":["Iwan ang iyong pangalan, address at impormasyon ng insurance kung saan ito makikita ng may-ari","Umalis kung mukhang maliit at hindi malala ang sira","Maghintay sa tabi ng nakaparadang sasakyan hanggang kinabukasan","Tawagan ang insurance company ng may-ari para i-report ito"],"h1":"Kailangan ng may-ari ng paraan para makontak ka.","h2":"Sa Oklahoma, kung nabangga mo ang isang nakaparadang sasakyan at hindi mo makita ang may-ari, dapat mong iwan sa nasirang sasakyan ang pangalan at address ng driver at ng may-ari, at ang iyong impormasyon ng insurance.","p":"Tama. Sa Oklahoma, iniiwan mo ang iyong pangalan, address at detalye ng insurance kung saan makikita ito ng may-ari."},"ar":{"q":"في Oklahoma، صدمت سيارة متوقّفة ولا تستطيع أن تجد صاحبها. ماذا يجب أن تفعل؟","o":["أن تترك اسمك وعنوانك ومعلومات تأمينك في مكان سيجدها فيه صاحب السيارة","أن تبتعد بالسيارة إذا كان الضرر يبدو صغيرًا وبسيطًا","أن تنتظر بجانب السيارة المتوقّفة حتى اليوم التالي","أن تتّصل بشركة تأمين صاحب السيارة لتُبلغ عن الحادث"],"h1":"صاحب السيارة يحتاج إلى طريقة للتواصل معك.","h2":"في Oklahoma، إذا صدمت سيارة متوقّفة ولم تجد صاحبها، يجب أن تترك على السيارة المتضرّرة اسم السائق وعنوانه واسم صاحب السيارة وعنوانه ومعلومات تأمينك.","p":"صحيح. في Oklahoma تترك اسمك وعنوانك وتفاصيل تأمينك في مكان سيراها فيه صاحب السيارة."},"ref":{"doc":"OK","page":63}},{"id":"ok-027","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, you fail the written test. How long must you wait before you take it again?","o":["At least one week","At least one day","At least 30 days","At least 6 months"],"h1":"It is a short wait.","h2":"In Oklahoma, if you fail the written test, the law says you must wait at least one day before you take it again.","p":"Right. You must wait at least one day."},"es":{"q":"En Oklahoma, usted no aprueba el examen escrito. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Por lo menos una semana","Por lo menos un día","Por lo menos 30 días","Por lo menos 6 meses"],"h1":"Es una espera corta.","h2":"En Oklahoma, si no aprueba el examen escrito, la ley dice que debe esperar por lo menos un día antes de tomarlo otra vez.","p":"Correcto. Debe esperar por lo menos un día."},"zh":{"q":"在 Oklahoma，你笔试没有通过。你要等多久才能再考？","o":["至少一周","至少一天","至少 30 天","至少 6 个月"],"h1":"要等的时间很短。","h2":"在 Oklahoma，如果你笔试没有通过，法律规定你至少要等一天才能再考。","p":"对。你至少要等一天。"},"vi":{"q":"Ở Oklahoma, bạn thi viết bị rớt. Bạn phải chờ bao lâu mới được thi lại?","o":["Ít nhất một tuần","Ít nhất một ngày","Ít nhất 30 ngày","Ít nhất 6 tháng"],"h1":"Thời gian chờ ngắn.","h2":"Ở Oklahoma, nếu bạn thi viết bị rớt, luật nói bạn phải chờ ít nhất một ngày rồi mới được thi lại.","p":"Đúng. Bạn phải chờ ít nhất một ngày."},"tl":{"q":"Sa Oklahoma, bumagsak ka sa written test. Gaano katagal ka dapat maghintay bago ka kumuha ulit nito?","o":["Hindi bababa sa isang linggo","Hindi bababa sa isang araw","Hindi bababa sa 30 araw","Hindi bababa sa 6 na buwan"],"h1":"Maikli lang ang paghihintay.","h2":"Sa Oklahoma, kapag bumagsak ka sa written test, sinasabi ng batas na dapat kang maghintay nang hindi bababa sa isang araw bago ka kumuha ulit nito.","p":"Tama. Dapat kang maghintay nang hindi bababa sa isang araw."},"ar":{"q":"في Oklahoma، رسبت في الاختبار الكتابي. كم يجب أن تنتظر قبل أن تعيده؟","o":["أسبوع واحد على الأقل","يوم واحد على الأقل","30 يومًا على الأقل","6 أشهر على الأقل"],"h1":"الانتظار قصير.","h2":"في Oklahoma، إذا رسبت في الاختبار الكتابي، يقول القانون إنه يجب أن تنتظر يومًا واحدًا على الأقل قبل أن تعيده.","p":"صحيح. يجب أن تنتظر يومًا واحدًا على الأقل."},"ref":{"doc":"OK","page":9}},{"id":"ok-028","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, for how long can a driver license be issued?","o":["1 or 2 years","10 years only","For life","4 or 8 years"],"h1":"There are two choices, and one is twice the other.","h2":"In Oklahoma, a driver license can be issued for either 4 or 8 years, and it expires on the last day of the month.","p":"Right. It can be issued for 4 or 8 years."},"es":{"q":"En Oklahoma, ¿por cuánto tiempo se puede emitir una licencia de conducir?","o":["1 o 2 años","Solo 10 años","De por vida","4 u 8 años"],"h1":"Hay dos opciones, y una es el doble de la otra.","h2":"En Oklahoma, una licencia de conducir se puede emitir por 4 u 8 años, y vence el último día del mes.","p":"Correcto. Se puede emitir por 4 u 8 años."},"zh":{"q":"在 Oklahoma，驾照的有效期可以是多久？","o":["1 年或 2 年","只有 10 年","终身","4 年或 8 年"],"h1":"有两个选择，一个是另一个的两倍。","h2":"在 Oklahoma，驾照的有效期可以是 4 年或 8 年，并在那个月的最后一天到期。","p":"对。驾照的有效期可以是 4 年或 8 年。"},"vi":{"q":"Ở Oklahoma, bằng lái xe có thể được cấp trong bao lâu?","o":["1 hoặc 2 năm","Chỉ 10 năm","Suốt đời","4 hoặc 8 năm"],"h1":"Có hai lựa chọn, và một số gấp đôi số kia.","h2":"Ở Oklahoma, bằng lái xe có thể được cấp trong 4 hoặc 8 năm, và hết hạn vào ngày cuối cùng của tháng.","p":"Đúng. Bằng lái có thể được cấp trong 4 hoặc 8 năm."},"tl":{"q":"Sa Oklahoma, gaano katagal maaaring ibigay ang isang driver license?","o":["1 o 2 taon","10 taon lang","Habambuhay","4 o 8 taon"],"h1":"May dalawang pagpipilian, at doble ng isa ang isa pa.","h2":"Sa Oklahoma, maaaring ibigay ang driver license nang 4 o 8 taon, at mag-e-expire ito sa huling araw ng buwan.","p":"Tama. Maaari itong ibigay nang 4 o 8 taon."},"ar":{"q":"في Oklahoma، لأي مدة يمكن إصدار رخصة القيادة؟","o":["سنة أو سنتان","10 سنوات فقط","مدى الحياة","4 أو 8 سنوات"],"h1":"هناك خياران، وأحدهما ضعف الآخر.","h2":"في Oklahoma، يمكن إصدار رخصة القيادة لمدة 4 أو 8 سنوات، وتنتهي في آخر يوم من الشهر.","p":"صحيح. يمكن إصدارها لمدة 4 أو 8 سنوات."},"ref":{"doc":"OK","page":13}},{"id":"ok-029","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, a blind person with a white cane is in the road ahead. How far from the person must your vehicle stop?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"It is more than 10 feet but less than 20.","h2":"In Oklahoma, a vehicle must stop 15 feet from a blind person in the roadway or at an intersection, outside the crosswalk.","p":"Right. Stop 15 feet away."},"es":{"q":"En Oklahoma, una persona ciega con bastón blanco está en la calle adelante. ¿A qué distancia de la persona debe detenerse su vehículo?","o":["15 pies","2 pies","5 pies","100 pies"],"h1":"Es más de 10 pies pero menos de 20.","h2":"En Oklahoma, un vehículo debe detenerse a 15 pies de una persona ciega que está en la calle o en una intersección, fuera del cruce peatonal.","p":"Correcto. Deténgase a 15 pies."},"zh":{"q":"在 Oklahoma，前面路上有一位拿着白色手杖的盲人。你的车必须在离这个人多远的地方停下？","o":["15 英尺","2 英尺","5 英尺","100 英尺"],"h1":"比 10 英尺多，但比 20 英尺少。","h2":"在 Oklahoma，如果盲人在道路上或路口，车辆必须在离他 15 英尺的地方停下，停在人行横道外面。","p":"对。在 15 英尺外停下。"},"vi":{"q":"Ở Oklahoma, phía trước có một người mù cầm gậy trắng đang ở trên đường. Xe của bạn phải dừng cách người đó bao xa?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"Nhiều hơn 10 feet nhưng ít hơn 20 feet.","h2":"Ở Oklahoma, xe phải dừng cách người mù 15 feet khi người đó ở trên đường hoặc ở giao lộ, bên ngoài lối qua đường.","p":"Đúng. Hãy dừng cách 15 feet."},"tl":{"q":"Sa Oklahoma, may bulag na tao na may puting tungkod sa kalsada sa unahan. Gaano kalayo sa tao dapat huminto ang sasakyan mo?","o":["15 feet","2 feet","5 feet","100 feet"],"h1":"Higit ito sa 10 feet pero kulang sa 20.","h2":"Sa Oklahoma, dapat huminto ang sasakyan nang 15 feet ang layo sa bulag na tao na nasa kalsada o nasa intersection, sa labas ng crosswalk.","p":"Tama. Huminto nang 15 feet ang layo."},"ar":{"q":"في Oklahoma، يوجد شخص كفيف يحمل عصا بيضاء على الطريق أمامك. على أي مسافة من هذا الشخص يجب أن تتوقف سيارتك؟","o":["15 قدمًا","2 قدم","5 أقدام","100 قدم"],"h1":"هي أكثر من 10 أقدام وأقل من 20.","h2":"في Oklahoma، يجب أن تتوقف السيارة على بعد 15 قدمًا من الشخص الكفيف على الطريق أو عند التقاطع، خارج ممر المشاة.","p":"صحيح. توقف على بعد 15 قدمًا."},"ref":{"doc":"OK","page":28}},{"id":"ok-030","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 50 feet","No closer than 500 feet"],"h1":"It is a longer distance than for a fire hydrant.","h2":"In Oklahoma, you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the nearest rail."},"es":{"q":"En Oklahoma, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["A no menos de 5 pies","A no menos de 15 pies","A no menos de 50 pies","A no menos de 500 pies"],"h1":"Es una distancia mayor que la de un hidrante.","h2":"En Oklahoma, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Oklahoma，你可以在离铁路道口最近的铁轨多近的地方停车？","o":["不能少于 5 英尺","不能少于 15 英尺","不能少于 50 英尺","不能少于 500 英尺"],"h1":"这个距离比消防栓的距离更长。","h2":"在 Oklahoma，你不可以在离铁路道口最近的铁轨 50 英尺以内停车。","p":"对。要离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Oklahoma, bạn được đậu xe gần thanh ray gần nhất của chỗ giao với đường sắt đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 15 feet","Không gần hơn 50 feet","Không gần hơn 500 feet"],"h1":"Khoảng cách này dài hơn khoảng cách với vòi nước chữa cháy.","h2":"Ở Oklahoma, bạn không được đậu xe trong vòng 50 feet tính từ thanh ray gần nhất của chỗ giao với đường sắt.","p":"Đúng. Hãy cách thanh ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Oklahoma, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka maaaring mag-park?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 50 feet","Hindi lalapit sa 500 feet"],"h1":"Mas mahaba ito kaysa sa layo para sa fire hydrant.","h2":"Sa Oklahoma, hindi ka maaaring mag-park sa loob ng 50 feet mula sa pinakamalapit na riles ng railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 feet sa pinakamalapit na riles."},"ar":{"q":"في Oklahoma، إلى أي مدى يمكنك أن تركن سيارتك قريبًا من أقرب قضيب في معبر السكة الحديدية؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 50 قدمًا","ليس أقرب من 500 قدم"],"h1":"هي مسافة أطول من المسافة عند حنفية الإطفاء.","h2":"في Oklahoma، لا يجوز أن تركن سيارتك على مسافة أقل من 50 قدمًا من أقرب قضيب في معبر السكة الحديدية.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"OK","page":49}},{"id":"ok-031","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, you are on a road with four or more lanes. What is the rule about the left lane?","o":["Only trucks may use it","You may not drive there in a way that blocks the normal flow of traffic","You may drive there at any speed you like","You may use it only at night"],"h1":"Think about faster cars that want to pass.","h2":"In Oklahoma, on a road divided into four or more lanes, you may not block the normal flow of traffic by driving in the left lane.","p":"Right. Do not hold up traffic in the left lane."},"es":{"q":"En Oklahoma, usted va por una carretera de cuatro carriles o más. ¿Cuál es la regla sobre el carril izquierdo?","o":["Solo los camiones pueden usarlo","No puede manejar ahí de una forma que bloquee el flujo normal del tráfico","Puede manejar ahí a la velocidad que quiera","Solo puede usarlo de noche"],"h1":"Piense en los carros más rápidos que quieren pasar.","h2":"En Oklahoma, en una carretera dividida en cuatro carriles o más, usted no puede bloquear el flujo normal del tráfico manejando en el carril izquierdo.","p":"Correcto. No detenga el tráfico en el carril izquierdo."},"zh":{"q":"在 Oklahoma，你在一条有四条或更多车道的路上。关于左车道的规定是什么？","o":["只有卡车可以用","你不可以在那里开车挡住正常的交通","你可以在那里用任何速度开车","你只可以在晚上用"],"h1":"想一想想要超车的更快的车。","h2":"在 Oklahoma，在分成四条或更多车道的路上，你不可以在左车道开车挡住正常的交通。","p":"对。不要在左车道挡住交通。"},"vi":{"q":"Ở Oklahoma, bạn đang ở trên con đường có bốn làn xe trở lên. Quy định về làn bên trái là gì?","o":["Chỉ xe tải được đi","Bạn không được lái ở đó theo cách cản trở dòng xe bình thường","Bạn được lái ở đó với bất kỳ tốc độ nào bạn muốn","Bạn chỉ được đi làn đó vào ban đêm"],"h1":"Hãy nghĩ đến những xe chạy nhanh hơn muốn vượt.","h2":"Ở Oklahoma, trên con đường chia thành bốn làn xe trở lên, bạn không được cản trở dòng xe bình thường bằng cách lái ở làn bên trái.","p":"Đúng. Đừng làm chậm dòng xe ở làn bên trái."},"tl":{"q":"Sa Oklahoma, nasa kalsada ka na may apat o higit pang lane. Ano ang patakaran tungkol sa kaliwang lane?","o":["Mga trak lang ang maaaring gumamit nito","Hindi ka maaaring magmaneho roon sa paraang humaharang sa normal na daloy ng trapiko","Maaari kang magmaneho roon sa anumang bilis na gusto mo","Maaari mo lang itong gamitin sa gabi"],"h1":"Isipin ang mas mabibilis na sasakyan na gustong mag-overtake.","h2":"Sa Oklahoma, sa kalsadang hinati sa apat o higit pang lane, hindi mo maaaring harangan ang normal na daloy ng trapiko sa pagmamaneho sa kaliwang lane.","p":"Tama. Huwag pabagalin ang trapiko sa kaliwang lane."},"ar":{"q":"في Oklahoma، أنت على طريق فيه أربعة مسارات أو أكثر. ما القاعدة بخصوص المسار الأيسر؟","o":["الشاحنات فقط يمكنها استخدامه","لا يجوز أن تقود فيه بطريقة تعيق حركة المرور العادية","يمكنك أن تقود فيه بأي سرعة تريدها","يمكنك استخدامه في الليل فقط"],"h1":"فكّر في السيارات الأسرع التي تريد التجاوز.","h2":"في Oklahoma، على طريق مقسّم إلى أربعة مسارات أو أكثر، لا يجوز أن تعيق حركة المرور العادية بالقيادة في المسار الأيسر.","p":"صحيح. لا تعطّل حركة المرور في المسار الأيسر."},"ref":{"doc":"OK","page":35}},{"id":"ok-032","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a rider has a motorcycle-only license before age 16. What is the largest engine size allowed?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"It is a small bike, but not the smallest size on the list.","h2":"In Oklahoma, a rider under 16 with a motorcycle-only license may ride a motorcycle or scooter of no more than 300 cc.","p":"Right. Young riders are limited to 300 cc or less."},"es":{"q":"En Oklahoma, una persona menor de 16 años tiene una licencia solo para motocicleta. ¿Cuál es el motor más grande permitido?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"Es una moto pequeña, pero no el tamaño más pequeño de la lista.","h2":"En Oklahoma, una persona menor de 16 años con licencia solo para motocicleta puede manejar una motocicleta o scooter de no más de 300 cc.","p":"Correcto. Los motociclistas jóvenes están limitados a 300 cc o menos."},"zh":{"q":"在 Oklahoma，一个不到 16 岁的人只有摩托车驾照。允许的最大发动机排量是多少？","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"这是小型摩托车，但不是列表里最小的。","h2":"在 Oklahoma，不到 16 岁、只有摩托车驾照的人，只能骑不超过 300 cc 的摩托车或小型摩托车（scooter）。","p":"对。年轻骑手只能骑 300 cc 或更小的车。"},"vi":{"q":"Ở Oklahoma, một người dưới 16 tuổi có bằng lái chỉ dành cho xe máy. Dung tích động cơ lớn nhất được phép là bao nhiêu?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"Đây là xe nhỏ, nhưng không phải cỡ nhỏ nhất trong danh sách.","h2":"Ở Oklahoma, người dưới 16 tuổi có bằng lái chỉ dành cho xe máy chỉ được chạy xe máy hoặc xe tay ga (scooter) không quá 300 cc.","p":"Đúng. Người lái trẻ chỉ được chạy xe 300 cc trở xuống."},"tl":{"q":"Sa Oklahoma, may motorcycle-only license ang isang rider na wala pang 16 taong gulang. Ano ang pinakamalaking laki ng makina na pinapayagan?","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"Maliit na motor ito, pero hindi ang pinakamaliit sa listahan.","h2":"Sa Oklahoma, ang rider na wala pang 16 taong gulang na may motorcycle-only license ay puwedeng magmaneho ng motorsiklo o scooter na hindi hihigit sa 300 cc.","p":"Tama. Hanggang 300 cc lang ang puwede sa mga batang rider."},"ar":{"q":"في Oklahoma، شخص عمره أقل من 16 سنة معه رخصة للدراجة النارية فقط. ما أكبر حجم محرّك مسموح به؟","o":["50 cc","150 cc","300 cc","500 cc"],"h1":"هي دراجة صغيرة، لكنها ليست أصغر حجم في القائمة.","h2":"في Oklahoma، من عمره أقل من 16 سنة ومعه رخصة للدراجة النارية فقط يمكنه أن يقود دراجة نارية أو سكوتر (scooter) لا يزيد محرّكها على 300 cc.","p":"صحيح. الراكبون الصغار مسموح لهم بـ 300 cc أو أقل."},"ref":{"doc":"OK","page":7}},{"id":"ok-033","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, who must wear a helmet when riding a motorcycle?","o":["Every rider, at any age","Riders under 18","Riders under 21","Only riders with a learner permit"],"h1":"The law is about young riders only.","h2":"In Oklahoma, a motorcycle helmet is required for anyone under 18 years old.","p":"Right. Riders under 18 must wear a helmet in Oklahoma."},"es":{"q":"En Oklahoma, ¿quién debe usar casco al manejar una motocicleta?","o":["Todos, a cualquier edad","Los menores de 18 años","Los menores de 21 años","Solo quienes tienen permiso de aprendiz"],"h1":"La ley es solo para los motociclistas jóvenes.","h2":"En Oklahoma, el casco de motocicleta es obligatorio para toda persona menor de 18 años.","p":"Correcto. En Oklahoma, los menores de 18 años deben usar casco."},"zh":{"q":"在 Oklahoma，骑摩托车时谁必须戴头盔？","o":["所有骑手，不管几岁","不到 18 岁的骑手","不到 21 岁的骑手","只有持学习驾照的骑手"],"h1":"这条法律只针对年轻骑手。","h2":"在 Oklahoma，不到 18 岁的人骑摩托车必须戴头盔。","p":"对。在 Oklahoma，不到 18 岁的骑手必须戴头盔。"},"vi":{"q":"Ở Oklahoma, ai phải đội mũ bảo hiểm khi chạy xe máy?","o":["Mọi người lái, ở bất kỳ tuổi nào","Người lái dưới 18 tuổi","Người lái dưới 21 tuổi","Chỉ người có giấy phép tập lái"],"h1":"Luật này chỉ dành cho người lái trẻ.","h2":"Ở Oklahoma, bất kỳ ai dưới 18 tuổi đều phải đội mũ bảo hiểm khi chạy xe máy.","p":"Đúng. Ở Oklahoma, người lái dưới 18 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa Oklahoma, sino ang dapat magsuot ng helmet kapag nagmamaneho ng motorsiklo?","o":["Lahat ng rider, anuman ang edad","Mga rider na wala pang 18","Mga rider na wala pang 21","Mga rider lang na may learner permit"],"h1":"Para lang sa mga batang rider ang batas.","h2":"Sa Oklahoma, kailangan ng helmet sa motorsiklo ang sinumang wala pang 18 taong gulang.","p":"Tama. Dapat magsuot ng helmet ang mga rider na wala pang 18 sa Oklahoma."},"ar":{"q":"في Oklahoma، من يجب أن يلبس خوذة عند ركوب دراجة نارية؟","o":["كل راكب، في أي عمر","الراكبون الذين أعمارهم أقل من 18 سنة","الراكبون الذين أعمارهم أقل من 21 سنة","فقط من معه تصريح تعلّم"],"h1":"القانون للراكبين الصغار فقط.","h2":"في Oklahoma، الخوذة واجبة على كل من عمره أقل من 18 سنة عند ركوب دراجة نارية.","p":"صحيح. في Oklahoma، يجب على الراكبين الذين أعمارهم أقل من 18 سنة أن يلبسوا خوذة."},"ref":{"doc":"OK","page":7}},{"id":"ok-034","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, a motorcycle has no windshield. What must the rider wear?","o":["Approved goggles or a face shield","A bright reflective vest","Any pair of sunglasses","Nothing extra is needed"],"h1":"It protects the eyes and face from things flying through the air.","h2":"In Oklahoma, a motorcycle rider without a windshield must wear approved goggles or a face shield.","p":"Right. No windshield means approved goggles or a face shield."},"es":{"q":"En Oklahoma, una motocicleta no tiene parabrisas. ¿Qué debe usar quien la maneja?","o":["Gafas protectoras aprobadas o una careta","Un chaleco reflectante de color vivo","Cualquier par de lentes de sol","No necesita nada más"],"h1":"Protege los ojos y la cara de objetos que vuelan por el aire.","h2":"En Oklahoma, quien maneja una motocicleta sin parabrisas debe usar gafas protectoras aprobadas o una careta.","p":"Correcto. Sin parabrisas, se usan gafas protectoras aprobadas o una careta."},"zh":{"q":"在 Oklahoma，一辆摩托车没有挡风玻璃。骑手必须戴什么？","o":["合格的护目镜或面罩","颜色鲜艳的反光背心","任何一副太阳镜","不需要戴别的东西"],"h1":"它保护眼睛和脸，挡住空中飞来的东西。","h2":"在 Oklahoma，骑没有挡风玻璃的摩托车，骑手必须戴合格的护目镜或面罩。","p":"对。没有挡风玻璃，就要戴合格的护目镜或面罩。"},"vi":{"q":"Ở Oklahoma, một chiếc xe máy không có kính chắn gió. Người lái phải đeo gì?","o":["Kính bảo hộ hoặc tấm che mặt được chấp thuận","Áo phản quang màu sáng","Bất kỳ cặp kính râm nào","Không cần đeo gì thêm"],"h1":"Nó bảo vệ mắt và mặt khỏi những vật bay trong không khí.","h2":"Ở Oklahoma, người lái xe máy không có kính chắn gió phải đeo kính bảo hộ hoặc tấm che mặt được chấp thuận.","p":"Đúng. Không có kính chắn gió thì phải đeo kính bảo hộ hoặc tấm che mặt được chấp thuận."},"tl":{"q":"Sa Oklahoma, walang windshield ang isang motorsiklo. Ano ang dapat isuot ng rider?","o":["Aprubadong goggles o face shield","Matingkad na reflective vest","Kahit anong sunglasses","Wala nang kailangang dagdag"],"h1":"Pinoprotektahan nito ang mata at mukha mula sa mga bagay na lumilipad sa hangin.","h2":"Sa Oklahoma, ang rider ng motorsiklong walang windshield ay dapat magsuot ng aprubadong goggles o face shield.","p":"Tama. Kapag walang windshield, aprubadong goggles o face shield ang kailangan."},"ar":{"q":"في Oklahoma، دراجة نارية ليس فيها زجاج أمامي. ماذا يجب أن يلبس الراكب؟","o":["نظارة واقية معتمدة أو واقي وجه","سترة عاكسة بلون فاقع","أي نظارة شمسية","لا يحتاج شيئًا إضافيًا"],"h1":"هي تحمي العينين والوجه من الأشياء التي تطير في الهواء.","h2":"في Oklahoma، يجب على راكب الدراجة النارية التي ليس فيها زجاج أمامي أن يلبس نظارة واقية معتمدة أو واقي وجه.","p":"صحيح. بدون زجاج أمامي، يلزم نظارة واقية معتمدة أو واقي وجه."},"ref":{"doc":"OK","page":53}},{"id":"ok-035","scope":"OK","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oklahoma, you are convicted of not stopping for a school bus with its red loading lights flashing. What happens to your license?","o":["Nothing, if it is your first time","It is suspended for 30 days","You get a warning letter","It is revoked for one year"],"h1":"The law treats this very seriously, with a long loss of your license.","h2":"In Oklahoma, not stopping for a school bus with its red loading lights flashing leads to a mandatory one-year revocation of your license.","p":"Right. Passing a loading school bus costs your license for one year."},"es":{"q":"En Oklahoma, lo declaran culpable de no detenerse ante un autobús escolar con sus luces rojas de carga encendidas. ¿Qué pasa con su licencia?","o":["Nada, si es la primera vez","Se suspende por 30 días","Recibe una carta de advertencia","Se revoca por un año"],"h1":"La ley trata esto como algo muy grave, con una pérdida larga de la licencia.","h2":"En Oklahoma, no detenerse ante un autobús escolar con sus luces rojas de carga encendidas causa la revocación obligatoria de su licencia por un año.","p":"Correcto. No detenerse ante un autobús escolar le cuesta la licencia por un año."},"zh":{"q":"在 Oklahoma，你因为没有为闪着红色上下客灯的校车停车而被定罪。你的驾照会怎样？","o":["如果是第一次，就没事","暂停 30 天","你会收到一封警告信","吊销一年"],"h1":"法律把这件事看得很严重，你会很长时间没有驾照。","h2":"在 Oklahoma，没有为闪着红色上下客灯的校车停车，驾照必须被吊销一年。","p":"对。超过正在上下学生的校车，会让你一年没有驾照。"},"vi":{"q":"Ở Oklahoma, bạn bị kết tội không dừng lại khi xe buýt trường học đang nháy đèn đỏ đón trả học sinh. Bằng lái của bạn sẽ ra sao?","o":["Không sao, nếu là lần đầu","Bị treo 30 ngày","Bạn nhận một lá thư cảnh cáo","Bị thu hồi một năm"],"h1":"Luật coi việc này rất nghiêm trọng, bạn sẽ mất bằng lái trong thời gian dài.","h2":"Ở Oklahoma, không dừng lại khi xe buýt trường học đang nháy đèn đỏ đón trả học sinh sẽ bị bắt buộc thu hồi bằng lái một năm.","p":"Đúng. Vượt xe buýt trường học đang đón trả học sinh khiến bạn mất bằng lái một năm."},"tl":{"q":"Sa Oklahoma, napatunayang hindi ka huminto para sa school bus na kumikislap ang pulang loading lights. Ano ang mangyayari sa lisensiya mo?","o":["Wala, kung unang beses mo","Masususpinde ito nang 30 araw","Makakatanggap ka ng warning letter","Babawiin ito nang isang taon"],"h1":"Seryosong-seryoso ito sa batas, at matagal kang mawawalan ng lisensiya.","h2":"Sa Oklahoma, ang hindi paghinto para sa school bus na kumikislap ang pulang loading lights ay nagdudulot ng sapilitang pagbawi ng lisensiya mo nang isang taon.","p":"Tama. Ang paglampas sa school bus na nagsasakay o nagbababa ay magpapawala ng lisensiya mo nang isang taon."},"ar":{"q":"في Oklahoma، أُدِنتَ بأنك لم تتوقّف لحافلة مدرسية أضواء التحميل الحمراء فيها تومض. ماذا يحدث لرخصتك؟","o":["لا شيء، إذا كانت المرة الأولى","تُوقَف لمدة 30 يومًا","تصلك رسالة تحذير","تُسحب لمدة سنة واحدة"],"h1":"القانون يعامل هذا بجدية كبيرة، وتفقد رخصتك مدة طويلة.","h2":"في Oklahoma، عدم التوقّف لحافلة مدرسية أضواء التحميل الحمراء فيها تومض يؤدي إلى سحب رخصتك إلزاميًا لمدة سنة واحدة.","p":"صحيح. تجاوز حافلة مدرسية يصعد إليها الطلاب أو ينزلون منها يكلّفك رخصتك لمدة سنة."},"ref":{"doc":"OK","page":30}},{"id":"ok-036","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a driver is convicted of a second DUI within 10 years. What kind of crime is it?","o":["A warning only","A traffic ticket only","A felony","A misdemeanor, the same as the first"],"h1":"The second time is much more serious than the first.","h2":"In Oklahoma, a second DUI offense within 10 years is a felony.","p":"Right. A second DUI within 10 years is a felony in Oklahoma."},"es":{"q":"En Oklahoma, una persona es declarada culpable de un segundo DUI en 10 años. ¿Qué tipo de delito es?","o":["Solo una advertencia","Solo una multa de tránsito","Un delito grave (felony)","Un delito menor, igual que el primero"],"h1":"La segunda vez es mucho más grave que la primera.","h2":"En Oklahoma, un segundo DUI en 10 años es un delito grave (felony).","p":"Correcto. Un segundo DUI en 10 años es un delito grave en Oklahoma."},"zh":{"q":"在 Oklahoma，一个司机在 10 年内第二次因酒后驾驶（DUI）被定罪。这是什么样的罪？","o":["只是警告","只是交通罚单","重罪（felony）","轻罪，和第一次一样"],"h1":"第二次比第一次严重得多。","h2":"在 Oklahoma，10 年内第二次酒后驾驶（DUI）是重罪（felony）。","p":"对。在 Oklahoma，10 年内第二次酒后驾驶是重罪。"},"vi":{"q":"Ở Oklahoma, một tài xế bị kết tội lái xe say rượu (DUI) lần thứ hai trong vòng 10 năm. Đó là loại tội gì?","o":["Chỉ là cảnh cáo","Chỉ là vé phạt giao thông","Trọng tội (felony)","Tội nhẹ, giống lần đầu"],"h1":"Lần thứ hai nghiêm trọng hơn lần đầu rất nhiều.","h2":"Ở Oklahoma, lái xe say rượu (DUI) lần thứ hai trong vòng 10 năm là trọng tội (felony).","p":"Đúng. Ở Oklahoma, DUI lần thứ hai trong vòng 10 năm là trọng tội."},"tl":{"q":"Sa Oklahoma, napatunayang nagkasala ang isang driver ng ikalawang DUI sa loob ng 10 taon. Anong klaseng krimen ito?","o":["Babala lang","Traffic ticket lang","Felony","Misdemeanor, katulad ng una"],"h1":"Mas seryoso ang ikalawang beses kaysa sa una.","h2":"Sa Oklahoma, felony ang ikalawang DUI sa loob ng 10 taon.","p":"Tama. Felony sa Oklahoma ang ikalawang DUI sa loob ng 10 taon."},"ar":{"q":"في Oklahoma، أُدين سائق بالقيادة تحت تأثير الكحول (DUI) للمرة الثانية خلال 10 سنوات. ما نوع هذه الجريمة؟","o":["تحذير فقط","مخالفة مرور فقط","جناية (felony)","جنحة، مثل المرة الأولى"],"h1":"المرة الثانية أخطر بكثير من الأولى.","h2":"في Oklahoma، القيادة تحت تأثير الكحول (DUI) للمرة الثانية خلال 10 سنوات جناية (felony).","p":"صحيح. المرة الثانية للقيادة تحت تأثير الكحول خلال 10 سنوات جناية في Oklahoma."},"ref":{"doc":"OK","page":65}},{"id":"ok-037","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, your blood alcohol level is over 0.05 but under 0.08. Can you be charged?","o":["No, the limit is 0.08","Yes, with impaired driving","Only if you were in a crash","Only if you drive a truck"],"h1":"Oklahoma has a lower charge for drivers who are affected but below 0.08.","h2":"In Oklahoma, a driver with a blood alcohol level over 0.05 but under 0.08 can be convicted of impaired driving.","p":"Right. Over 0.05 can mean an impaired driving charge in Oklahoma."},"es":{"q":"En Oklahoma, su nivel de alcohol en la sangre es mayor de 0.05 pero menor de 0.08. ¿Pueden acusarlo?","o":["No, el límite es 0.08","Sí, de manejar con facultades disminuidas","Solo si tuvo un choque","Solo si maneja un camión"],"h1":"Oklahoma tiene un cargo menor para conductores afectados aunque estén por debajo de 0.08.","h2":"En Oklahoma, un conductor con un nivel de alcohol en la sangre mayor de 0.05 pero menor de 0.08 puede ser declarado culpable de manejar con facultades disminuidas.","p":"Correcto. Más de 0.05 puede significar un cargo por manejar con facultades disminuidas en Oklahoma."},"zh":{"q":"在 Oklahoma，你的血液酒精浓度高于 0.05，但低于 0.08。你会被起诉吗？","o":["不会，上限是 0.08","会，罪名是能力受损驾驶","只有发生车祸时才会","只有开卡车时才会"],"h1":"Oklahoma 对受到影响、但低于 0.08 的司机有一个较轻的罪名。","h2":"在 Oklahoma，血液酒精浓度高于 0.05、但低于 0.08 的司机，可以被判能力受损驾驶（impaired driving）。","p":"对。在 Oklahoma，高于 0.05 就可能被控能力受损驾驶。"},"vi":{"q":"Ở Oklahoma, nồng độ cồn trong máu của bạn trên 0.05 nhưng dưới 0.08. Bạn có thể bị buộc tội không?","o":["Không, giới hạn là 0.08","Có, tội lái xe khi bị suy giảm khả năng","Chỉ khi bạn gặp tai nạn","Chỉ khi bạn lái xe tải"],"h1":"Oklahoma có một tội nhẹ hơn cho tài xế bị ảnh hưởng dù dưới 0.08.","h2":"Ở Oklahoma, tài xế có nồng độ cồn trong máu trên 0.05 nhưng dưới 0.08 có thể bị kết tội lái xe khi bị suy giảm khả năng (impaired driving).","p":"Đúng. Ở Oklahoma, trên 0.05 có thể bị buộc tội lái xe khi bị suy giảm khả năng."},"tl":{"q":"Sa Oklahoma, lampas sa 0.05 pero mas mababa sa 0.08 ang blood alcohol level mo. Puwede ka bang kasuhan?","o":["Hindi, 0.08 ang limit","Oo, ng impaired driving","Kung nabangga ka lang","Kung trak ang minamaneho mo lang"],"h1":"May mas magaang kaso ang Oklahoma para sa mga driver na apektado kahit mas mababa sa 0.08.","h2":"Sa Oklahoma, ang driver na may blood alcohol level na lampas sa 0.05 pero mas mababa sa 0.08 ay puwedeng mapatunayang nagkasala ng impaired driving.","p":"Tama. Sa Oklahoma, ang lampas sa 0.05 ay puwedeng mauwi sa kasong impaired driving."},"ar":{"q":"في Oklahoma، نسبة الكحول في دمك أكثر من 0.05 لكن أقل من 0.08. هل يمكن أن تُتّهم؟","o":["لا، الحدّ هو 0.08","نعم، بالقيادة مع ضعف القدرة","فقط إذا وقع لك حادث","فقط إذا كنت تقود شاحنة"],"h1":"في Oklahoma تهمة أخفّ للسائقين المتأثرين حتى لو كانوا تحت 0.08.","h2":"في Oklahoma، السائق الذي نسبة الكحول في دمه أكثر من 0.05 لكن أقل من 0.08 يمكن أن يُدان بالقيادة مع ضعف القدرة (impaired driving).","p":"صحيح. أكثر من 0.05 قد يعني تهمة القيادة مع ضعف القدرة في Oklahoma."},"ref":{"doc":"OK","page":65}},{"id":"ok-038","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a driver under 21 has a first offense under the Zero Tolerance law. How long is the license revoked?","o":["6 months","30 days","2 years","5 years"],"h1":"It is half a year.","h2":"In Oklahoma, a first Zero Tolerance offense for a driver under 21 leads to a license revocation of six months.","p":"Right. A first Zero Tolerance offense means six months without a license."},"es":{"q":"En Oklahoma, un conductor menor de 21 años comete una primera falta bajo la ley de Tolerancia Cero. ¿Por cuánto tiempo se revoca la licencia?","o":["6 meses","30 días","2 años","5 años"],"h1":"Es medio año.","h2":"En Oklahoma, una primera falta de Tolerancia Cero de un conductor menor de 21 años causa la revocación de la licencia por seis meses.","p":"Correcto. Una primera falta de Tolerancia Cero significa seis meses sin licencia."},"zh":{"q":"在 Oklahoma，一个不到 21 岁的司机第一次违反零容忍（Zero Tolerance）法。驾照被吊销多久？","o":["6 个月","30 天","2 年","5 年"],"h1":"是半年。","h2":"在 Oklahoma，不到 21 岁的司机第一次违反零容忍法，驾照会被吊销六个月。","p":"对。第一次违反零容忍法，就是六个月没有驾照。"},"vi":{"q":"Ở Oklahoma, một tài xế dưới 21 tuổi vi phạm lần đầu luật Không Khoan Nhượng (Zero Tolerance). Bằng lái bị thu hồi bao lâu?","o":["6 tháng","30 ngày","2 năm","5 năm"],"h1":"Đó là nửa năm.","h2":"Ở Oklahoma, tài xế dưới 21 tuổi vi phạm lần đầu luật Không Khoan Nhượng sẽ bị thu hồi bằng lái sáu tháng.","p":"Đúng. Vi phạm lần đầu luật Không Khoan Nhượng nghĩa là sáu tháng không có bằng lái."},"tl":{"q":"Sa Oklahoma, unang paglabag ng isang driver na wala pang 21 sa Zero Tolerance law. Gaano katagal babawiin ang lisensiya?","o":["6 na buwan","30 araw","2 taon","5 taon"],"h1":"Kalahating taon ito.","h2":"Sa Oklahoma, ang unang paglabag sa Zero Tolerance ng driver na wala pang 21 ay nagdudulot ng pagbawi ng lisensiya nang anim na buwan.","p":"Tama. Ang unang paglabag sa Zero Tolerance ay anim na buwang walang lisensiya."},"ar":{"q":"في Oklahoma، سائق عمره أقل من 21 سنة ارتكب المخالفة الأولى لقانون عدم التسامح (Zero Tolerance). كم مدة سحب الرخصة؟","o":["6 أشهر","30 يومًا","سنتان","5 سنوات"],"h1":"هي نصف سنة.","h2":"في Oklahoma، المخالفة الأولى لقانون عدم التسامح من سائق عمره أقل من 21 سنة تؤدي إلى سحب الرخصة لمدة ستة أشهر.","p":"صحيح. المخالفة الأولى لقانون عدم التسامح تعني ستة أشهر بدون رخصة."},"ref":{"doc":"OK","page":67}},{"id":"ok-039","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, cannabis is legal for some medical uses. Is it legal to drive with cannabis in your system?","o":["Yes, if you have a medical card","Yes, if you feel fine","Yes, below a set legal limit","No, any detectable amount is illegal"],"h1":"Unlike alcohol for adults, there is no amount that is allowed.","h2":"In Oklahoma, it is illegal for anyone to drive with any detectable level of cannabis in their system.","p":"Right. Any detectable cannabis makes driving illegal in Oklahoma."},"es":{"q":"En Oklahoma, el cannabis es legal para algunos usos médicos. ¿Es legal manejar con cannabis en el cuerpo?","o":["Sí, si tiene una tarjeta médica","Sí, si se siente bien","Sí, por debajo de un límite legal","No, cualquier cantidad detectable es ilegal"],"h1":"A diferencia del alcohol para los adultos, no hay ninguna cantidad permitida.","h2":"En Oklahoma, es ilegal que cualquier persona maneje con cualquier nivel detectable de cannabis en el cuerpo.","p":"Correcto. Cualquier cantidad detectable de cannabis hace ilegal manejar en Oklahoma."},"zh":{"q":"在 Oklahoma，大麻（cannabis）在某些医疗用途上是合法的。体内有大麻时开车合法吗？","o":["合法，如果你有医疗卡","合法，如果你感觉没事","合法，只要低于法定上限","不合法，任何能测出的量都违法"],"h1":"和成年人喝酒不一样，没有任何允许的量。","h2":"在 Oklahoma，任何人体内有任何能测出的大麻时开车都是违法的。","p":"对。在 Oklahoma，体内有任何能测出的大麻，开车就是违法的。"},"vi":{"q":"Ở Oklahoma, cần sa (cannabis) hợp pháp cho một số mục đích y tế. Lái xe khi trong người có cần sa có hợp pháp không?","o":["Có, nếu bạn có thẻ y tế","Có, nếu bạn thấy bình thường","Có, nếu dưới một giới hạn luật định","Không, bất kỳ lượng nào đo được đều bất hợp pháp"],"h1":"Khác với rượu đối với người lớn, không có lượng nào được phép.","h2":"Ở Oklahoma, bất kỳ ai lái xe khi trong người có bất kỳ lượng cần sa nào đo được đều là bất hợp pháp.","p":"Đúng. Ở Oklahoma, có bất kỳ lượng cần sa nào đo được thì lái xe là bất hợp pháp."},"tl":{"q":"Sa Oklahoma, legal ang cannabis para sa ilang medikal na gamit. Legal bang magmaneho kapag may cannabis sa katawan mo?","o":["Oo, kung may medical card ka","Oo, kung maayos ang pakiramdam mo","Oo, kung mas mababa sa legal limit","Hindi, bawal ang anumang dami na nade-detect"],"h1":"Hindi tulad ng alak para sa mga adult, walang dami na pinapayagan.","h2":"Sa Oklahoma, bawal sa sinuman ang magmaneho kapag may anumang dami ng cannabis na nade-detect sa katawan.","p":"Tama. Sa Oklahoma, bawal magmaneho kapag may anumang cannabis na nade-detect."},"ar":{"q":"في Oklahoma، القنّب (cannabis) قانوني لبعض الاستخدامات الطبية. هل القيادة قانونية وفي جسمك قنّب؟","o":["نعم، إذا كانت معك بطاقة طبية","نعم، إذا كنت تشعر أنك بخير","نعم، تحت حدّ قانوني معيّن","لا، أي كمية يمكن كشفها غير قانونية"],"h1":"على عكس الكحول للبالغين، لا توجد أي كمية مسموح بها.","h2":"في Oklahoma، القيادة غير قانونية لأي شخص في جسمه أي مستوى من القنّب يمكن كشفه.","p":"صحيح. أي كمية من القنّب يمكن كشفها تجعل القيادة غير قانونية في Oklahoma."},"ref":{"doc":"OK","page":66}},{"id":"ok-040","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the highest fine for a speeding conviction, outside school and work zones?","o":["$100","$250","$654","$5,000"],"h1":"It is more than $500 but far less than $1,000.","h2":"In Oklahoma, a speeding conviction can bring a fine of up to $654 and up to 30 days in jail.","p":"Right. Speeding can cost up to $654 in Oklahoma."},"es":{"q":"En Oklahoma, ¿cuál es la multa más alta por exceso de velocidad, fuera de zonas escolares y de obras?","o":["$100","$250","$654","$5,000"],"h1":"Es más de $500 pero mucho menos de $1,000.","h2":"En Oklahoma, una condena por exceso de velocidad puede traer una multa de hasta $654 y hasta 30 días de cárcel.","p":"Correcto. El exceso de velocidad puede costar hasta $654 en Oklahoma."},"zh":{"q":"在 Oklahoma，在学校区和施工区以外，超速被定罪的最高罚款是多少？","o":["$100","$250","$654","$5,000"],"h1":"它比 $500 多，但比 $1,000 少很多。","h2":"在 Oklahoma，超速被定罪可能被罚款最多 $654，并坐牢最多 30 天。","p":"对。在 Oklahoma，超速最多可能罚 $654。"},"vi":{"q":"Ở Oklahoma, mức phạt cao nhất khi bị kết tội chạy quá tốc độ, ngoài khu vực trường học và khu công trường, là bao nhiêu?","o":["$100","$250","$654","$5,000"],"h1":"Nó hơn $500 nhưng ít hơn $1,000 rất nhiều.","h2":"Ở Oklahoma, bị kết tội chạy quá tốc độ có thể bị phạt đến $654 và ngồi tù đến 30 ngày.","p":"Đúng. Ở Oklahoma, chạy quá tốc độ có thể bị phạt đến $654."},"tl":{"q":"Sa Oklahoma, magkano ang pinakamataas na multa sa conviction sa speeding, sa labas ng school zone at work zone?","o":["$100","$250","$654","$5,000"],"h1":"Mas mataas ito sa $500 pero mas mababa nang malaki sa $1,000.","h2":"Sa Oklahoma, ang conviction sa speeding ay puwedeng magdulot ng multang hanggang $654 at hanggang 30 araw sa kulungan.","p":"Tama. Puwedeng umabot ng $654 ang multa sa speeding sa Oklahoma."},"ar":{"q":"في Oklahoma، ما أعلى غرامة على الإدانة بتجاوز السرعة، خارج مناطق المدارس ومناطق الأشغال؟","o":["$100","$250","$654","$5,000"],"h1":"هي أكثر من $500 لكنها أقل بكثير من $1,000.","h2":"في Oklahoma، الإدانة بتجاوز السرعة قد تؤدي إلى غرامة تصل إلى $654 وسجن حتى 30 يومًا.","p":"صحيح. تجاوز السرعة قد يكلّف حتى $654 في Oklahoma."},"ref":{"doc":"OK","page":40}},{"id":"ok-041","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, what is the speed limit on a highway inside a state park or wildlife refuge when no other limit is posted?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Parks have people and animals near the road, so the limit is low.","h2":"In Oklahoma, the speed limit on highways inside state parks or wildlife refuges is 35 mph unless another limit is posted.","p":"Right. 35 mph in state parks and wildlife refuges."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una carretera dentro de un parque estatal o refugio de vida silvestre si no hay otro límite señalado?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"En los parques hay personas y animales cerca del camino, así que el límite es bajo.","h2":"En Oklahoma, el límite de velocidad en las carreteras dentro de parques estatales o refugios de vida silvestre es 35 mph, a menos que haya otro límite señalado.","p":"Correcto. 35 mph en parques estatales y refugios de vida silvestre."},"zh":{"q":"在 Oklahoma，如果没有标出别的限速，州立公园或野生动物保护区内公路的限速是多少？","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"公园里路边有人和动物，所以限速低。","h2":"在 Oklahoma，州立公园或野生动物保护区内公路的限速是 35 mph，除非标志写着别的限速。","p":"对。州立公园和野生动物保护区内是 35 mph。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trên đường trong công viên tiểu bang hoặc khu bảo tồn động vật hoang dã là bao nhiêu khi không có biển báo giới hạn khác?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Trong công viên có người và động vật ở gần đường, nên giới hạn thấp.","h2":"Ở Oklahoma, tốc độ tối đa trên đường trong công viên tiểu bang hoặc khu bảo tồn động vật hoang dã là 35 mph, trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. 35 mph trong công viên tiểu bang và khu bảo tồn động vật hoang dã."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa highway sa loob ng state park o wildlife refuge kapag walang ibang limit na nakapaskil?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"May mga tao at hayop malapit sa daan sa mga park, kaya mababa ang limit.","h2":"Sa Oklahoma, 35 mph ang speed limit sa mga highway sa loob ng state park o wildlife refuge maliban kung iba ang nakapaskil.","p":"Tama. 35 mph sa mga state park at wildlife refuge."},"ar":{"q":"في Oklahoma، ما حدّ السرعة على طريق داخل حديقة الولاية أو محمية الحياة البرية عندما لا توجد لافتة بحدّ آخر؟","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"في الحدائق ناس وحيوانات قرب الطريق، لذلك الحدّ منخفض.","h2":"في Oklahoma، حدّ السرعة على الطرق داخل حدائق الولاية أو محميات الحياة البرية هو 35 mph، إلا إذا كانت هناك لافتة بحدّ آخر.","p":"صحيح. 35 mph في حدائق الولاية ومحميات الحياة البرية."},"ref":{"doc":"OK","page":41}},{"id":"ok-042","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, what is the speed limit in a marked school zone on a highway outside a city or town, when no other limit is posted?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"It is the same number as a common neighborhood limit.","h2":"In Oklahoma, the speed limit in a properly marked school zone on a highway outside a city or town is 25 mph unless another limit is posted.","p":"Right. 25 mph in a marked school zone outside town."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una zona escolar señalada en una carretera fuera de una ciudad o pueblo, si no hay otro límite señalado?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Es el mismo número que un límite común en los vecindarios.","h2":"En Oklahoma, el límite de velocidad en una zona escolar bien señalada en una carretera fuera de una ciudad o pueblo es 25 mph, a menos que haya otro límite señalado.","p":"Correcto. 25 mph en una zona escolar señalada fuera del pueblo."},"zh":{"q":"在 Oklahoma，如果没有标出别的限速，城镇以外公路上有标志的学校区限速是多少？","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"它和住宅区常见的限速是同一个数字。","h2":"在 Oklahoma，城镇以外公路上标志清楚的学校区限速是 25 mph，除非标志写着别的限速。","p":"对。城镇以外有标志的学校区是 25 mph。"},"vi":{"q":"Ở Oklahoma, tốc độ tối đa trong khu vực trường học có biển báo trên đường bên ngoài thành phố hoặc thị trấn là bao nhiêu, khi không có biển báo giới hạn khác?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Đó là cùng con số với giới hạn thường gặp trong khu dân cư.","h2":"Ở Oklahoma, tốc độ tối đa trong khu vực trường học có biển báo đúng quy định trên đường bên ngoài thành phố hoặc thị trấn là 25 mph, trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. 25 mph trong khu vực trường học có biển báo bên ngoài thị trấn."},"tl":{"q":"Sa Oklahoma, ano ang speed limit sa may markang school zone sa highway sa labas ng lungsod o bayan, kapag walang ibang limit na nakapaskil?","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"Pareho ito ng karaniwang limit sa mga neighborhood.","h2":"Sa Oklahoma, 25 mph ang speed limit sa maayos na minarkahang school zone sa highway sa labas ng lungsod o bayan maliban kung iba ang nakapaskil.","p":"Tama. 25 mph sa may markang school zone sa labas ng bayan."},"ar":{"q":"في Oklahoma، ما حدّ السرعة في منطقة مدرسة عليها علامات على طريق خارج مدينة أو بلدة، عندما لا توجد لافتة بحدّ آخر؟","o":["25 mph","15 mph","35 mph","45 mph"],"h1":"هو نفس الرقم الشائع في الأحياء السكنية.","h2":"في Oklahoma، حدّ السرعة في منطقة مدرسة عليها علامات صحيحة على طريق خارج مدينة أو بلدة هو 25 mph، إلا إذا كانت هناك لافتة بحدّ آخر.","p":"صحيح. 25 mph في منطقة مدرسة عليها علامات خارج البلدة."},"ref":{"doc":"OK","page":41}},{"id":"ok-043","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, what fine can you get for not obeying the signs, signals or markings in a work zone?","o":["$5 to $25","$10 to $50","$25 to $75","$100 to $1,000"],"h1":"It can reach four digits, and there may also be jail time.","h2":"In Oklahoma, not obeying work zone signs, signals or markings can bring a fine from $100 to $1,000 and up to 30 days in jail.","p":"Right. $100 to $1,000 for ignoring work zone signs."},"es":{"q":"En Oklahoma, ¿qué multa puede recibir por no obedecer las señales, semáforos o marcas en una zona de obras?","o":["De $5 a $25","De $10 a $50","De $25 a $75","De $100 a $1,000"],"h1":"Puede llegar a cuatro cifras, y también puede haber cárcel.","h2":"En Oklahoma, no obedecer las señales, semáforos o marcas de una zona de obras puede traer una multa de $100 a $1,000 y hasta 30 días de cárcel.","p":"Correcto. De $100 a $1,000 por no obedecer las señales de una zona de obras."},"zh":{"q":"在 Oklahoma，在施工区不遵守标志、信号或标线，可能被罚多少？","o":["$5 到 $25","$10 到 $50","$25 到 $75","$100 到 $1,000"],"h1":"罚款可以到四位数，还可能坐牢。","h2":"在 Oklahoma，不遵守施工区的标志、信号或标线，可能被罚款 $100 到 $1,000，并坐牢最多 30 天。","p":"对。不理施工区标志会被罚 $100 到 $1,000。"},"vi":{"q":"Ở Oklahoma, bạn có thể bị phạt bao nhiêu vì không tuân theo biển báo, đèn tín hiệu hoặc vạch kẻ trong khu công trường?","o":["$5 đến $25","$10 đến $50","$25 đến $75","$100 đến $1,000"],"h1":"Nó có thể lên đến bốn chữ số, và còn có thể bị ngồi tù.","h2":"Ở Oklahoma, không tuân theo biển báo, đèn tín hiệu hoặc vạch kẻ trong khu công trường có thể bị phạt từ $100 đến $1,000 và ngồi tù đến 30 ngày.","p":"Đúng. $100 đến $1,000 vì không tuân theo biển báo khu công trường."},"tl":{"q":"Sa Oklahoma, magkano ang puwedeng multa sa hindi pagsunod sa mga sign, signal o marka sa work zone?","o":["$5 hanggang $25","$10 hanggang $50","$25 hanggang $75","$100 hanggang $1,000"],"h1":"Puwede itong umabot ng apat na digit, at puwede ring makulong.","h2":"Sa Oklahoma, ang hindi pagsunod sa mga sign, signal o marka sa work zone ay puwedeng magdulot ng multang $100 hanggang $1,000 at hanggang 30 araw sa kulungan.","p":"Tama. $100 hanggang $1,000 sa hindi pagsunod sa mga sign sa work zone."},"ar":{"q":"في Oklahoma، ما الغرامة التي قد تدفعها إذا لم تلتزم باللافتات أو الإشارات أو العلامات في منطقة الأشغال؟","o":["من $5 إلى $25","من $10 إلى $50","من $25 إلى $75","من $100 إلى $1,000"],"h1":"قد تصل إلى أربعة أرقام، وقد يكون معها سجن أيضًا.","h2":"في Oklahoma، عدم الالتزام باللافتات أو الإشارات أو العلامات في منطقة الأشغال قد يؤدي إلى غرامة من $100 إلى $1,000 وسجن حتى 30 يومًا.","p":"صحيح. من $100 إلى $1,000 لتجاهل لافتات منطقة الأشغال."},"ref":{"doc":"OK","page":24}},{"id":"ok-044","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you drive in a caravan outside a business or residential area. How much space should you leave between vehicles?","o":["At least 20 feet","At least 50 feet","At least 200 feet","At least 1,000 feet"],"h1":"Other cars and trucks must be able to pull into the line safely.","h2":"In Oklahoma, cars in a caravan outside a business or residential area should keep at least 200 feet between each vehicle.","p":"Right. Leave at least 200 feet between vehicles in a caravan."},"es":{"q":"En Oklahoma, usted maneja en una caravana fuera de una zona comercial o residencial. ¿Cuánto espacio debe dejar entre los vehículos?","o":["Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 200 pies","Por lo menos 1,000 pies"],"h1":"Otros carros y camiones deben poder entrar en la fila sin peligro.","h2":"En Oklahoma, los vehículos en una caravana fuera de una zona comercial o residencial deben dejar por lo menos 200 pies entre cada uno.","p":"Correcto. Deje por lo menos 200 pies entre los vehículos de una caravana."},"zh":{"q":"在 Oklahoma，你在商业区或住宅区以外跟车队一起开车。车与车之间应该留多少距离？","o":["至少 20 英尺","至少 50 英尺","至少 200 英尺","至少 1,000 英尺"],"h1":"其他汽车和卡车必须能安全地开进车队中间。","h2":"在 Oklahoma，在商业区或住宅区以外，车队里的车之间应该至少留 200 英尺。","p":"对。车队里的车之间至少留 200 英尺。"},"vi":{"q":"Ở Oklahoma, bạn lái xe trong một đoàn xe bên ngoài khu thương mại hoặc khu dân cư. Bạn nên để khoảng cách bao nhiêu giữa các xe?","o":["Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 200 feet","Ít nhất 1,000 feet"],"h1":"Các xe hơi và xe tải khác phải có thể chen vào hàng một cách an toàn.","h2":"Ở Oklahoma, các xe trong một đoàn xe bên ngoài khu thương mại hoặc khu dân cư nên giữ khoảng cách ít nhất 200 feet giữa mỗi xe.","p":"Đúng. Để ít nhất 200 feet giữa các xe trong đoàn xe."},"tl":{"q":"Sa Oklahoma, nagmamaneho ka sa isang caravan sa labas ng business o residential area. Gaano kalaking espasyo ang dapat mong iwan sa pagitan ng mga sasakyan?","o":["Hindi bababa sa 20 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 200 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Dapat makapasok nang ligtas sa pila ang ibang kotse at trak.","h2":"Sa Oklahoma, ang mga kotse sa caravan sa labas ng business o residential area ay dapat mag-iwan ng hindi bababa sa 200 talampakan sa pagitan ng bawat sasakyan.","p":"Tama. Mag-iwan ng hindi bababa sa 200 talampakan sa pagitan ng mga sasakyan sa caravan."},"ar":{"q":"في Oklahoma، تقود ضمن قافلة سيارات خارج منطقة تجارية أو سكنية. كم مسافة يجب أن تترك بين السيارات؟","o":["20 قدمًا على الأقل","50 قدمًا على الأقل","200 قدم على الأقل","1,000 قدم على الأقل"],"h1":"يجب أن تستطيع السيارات والشاحنات الأخرى الدخول في الصف بأمان.","h2":"في Oklahoma، يجب أن تترك السيارات في القافلة خارج منطقة تجارية أو سكنية 200 قدم على الأقل بين كل سيارة وأخرى.","p":"صحيح. اترك 200 قدم على الأقل بين السيارات في القافلة."},"ref":{"doc":"OK","page":44}},{"id":"ok-045","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, you park next to a curb on a hill. How close to the curb should your car stop?","o":["Within 2 feet","Within 6 inches","Within 3 feet","Touching the sidewalk"],"h1":"On a hill, you need to be closer to the curb than in normal parallel parking.","h2":"In Oklahoma, when you park on a hill, you should stop within six inches of the curb.","p":"Right. On a hill, stop within six inches of the curb."},"es":{"q":"En Oklahoma, usted se estaciona junto a la acera en una cuesta. ¿Qué tan cerca de la acera debe quedar su carro?","o":["A menos de 2 pies","A menos de 6 pulgadas","A menos de 3 pies","Tocando la banqueta"],"h1":"En una cuesta debe quedar más cerca de la acera que al estacionarse en paralelo normalmente.","h2":"En Oklahoma, cuando se estaciona en una cuesta, debe quedar a menos de seis pulgadas de la acera.","p":"Correcto. En una cuesta, quede a menos de seis pulgadas de la acera."},"zh":{"q":"在 Oklahoma，你在坡上靠路缘停车。你的车应该离路缘多近？","o":["2 英尺以内","6 英寸以内","3 英尺以内","碰到人行道"],"h1":"在坡上，你要比平常的平行停车更靠近路缘。","h2":"在 Oklahoma，在坡上停车时，你应该停在离路缘六英寸以内。","p":"对。在坡上，停在离路缘六英寸以内。"},"vi":{"q":"Ở Oklahoma, bạn đậu xe sát lề đường trên dốc. Xe của bạn nên dừng cách lề đường bao gần?","o":["Trong vòng 2 feet","Trong vòng 6 inch","Trong vòng 3 feet","Chạm vào vỉa hè"],"h1":"Trên dốc, bạn cần ở gần lề đường hơn so với đậu xe song song bình thường.","h2":"Ở Oklahoma, khi đậu xe trên dốc, bạn nên dừng trong vòng sáu inch cách lề đường.","p":"Đúng. Trên dốc, dừng trong vòng sáu inch cách lề đường."},"tl":{"q":"Sa Oklahoma, pumarada ka sa tabi ng curb sa isang burol. Gaano kalapit sa curb dapat huminto ang kotse mo?","o":["Sa loob ng 2 talampakan","Sa loob ng 6 na pulgada","Sa loob ng 3 talampakan","Nakadikit sa sidewalk"],"h1":"Sa burol, kailangan mong mas malapit sa curb kaysa sa karaniwang parallel parking.","h2":"Sa Oklahoma, kapag pumarada ka sa burol, dapat kang huminto sa loob ng anim na pulgada mula sa curb.","p":"Tama. Sa burol, huminto sa loob ng anim na pulgada mula sa curb."},"ar":{"q":"في Oklahoma، تركن سيارتك بجانب الرصيف على منحدر. كم يجب أن تقترب سيارتك من حافة الرصيف؟","o":["في حدود قدمين","في حدود 6 بوصات","في حدود 3 أقدام","تلمس الرصيف"],"h1":"على المنحدر، يجب أن تكون أقرب إلى حافة الرصيف من الركن الموازي العادي.","h2":"في Oklahoma، عندما تركن على منحدر، يجب أن تتوقّف على بُعد ست بوصات أو أقل من حافة الرصيف.","p":"صحيح. على المنحدر، توقّف على بُعد ست بوصات أو أقل من حافة الرصيف."},"ref":{"doc":"OK","page":47}},{"id":"ok-046","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, how close to the driveway entrance of a fire station may you park on the same side of the street?","o":["As close as you like","No closer than 5 feet","No closer than 10 feet","No closer than 20 feet"],"h1":"Fire trucks need room to get out fast.","h2":"In Oklahoma, you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay at least 20 feet from a fire station entrance."},"es":{"q":"En Oklahoma, ¿qué tan cerca de la entrada de un cuartel de bomberos puede estacionarse del mismo lado de la calle?","o":["Tan cerca como quiera","A no menos de 5 pies","A no menos de 10 pies","A no menos de 20 pies"],"h1":"Los camiones de bomberos necesitan espacio para salir rápido.","h2":"En Oklahoma, no puede estacionarse a menos de 20 pies de la entrada de un cuartel de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de un cuartel de bomberos."},"zh":{"q":"在 Oklahoma，在街道同一边，你可以停在离消防站车道入口多近的地方？","o":["想多近都可以","不能近于 5 英尺","不能近于 10 英尺","不能近于 20 英尺"],"h1":"消防车需要空间才能快速开出去。","h2":"在 Oklahoma，你不可以停在离消防站车道入口 20 英尺以内的地方。","p":"对。离消防站入口至少 20 英尺。"},"vi":{"q":"Ở Oklahoma, bạn được đậu xe gần lối ra vào của trạm cứu hỏa đến mức nào nếu ở cùng phía đường?","o":["Gần bao nhiêu cũng được","Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet"],"h1":"Xe cứu hỏa cần chỗ để ra nhanh.","h2":"Ở Oklahoma, bạn không được đậu xe trong vòng 20 feet tính từ lối ra vào của trạm cứu hỏa.","p":"Đúng. Cách lối vào trạm cứu hỏa ít nhất 20 feet."},"tl":{"q":"Sa Oklahoma, gaano kalapit sa pasukan ng driveway ng fire station ka puwedeng pumarada sa parehong panig ng kalye?","o":["Kahit gaano kalapit","Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 20 talampakan"],"h1":"Kailangan ng mga fire truck ng espasyo para makalabas nang mabilis.","h2":"Sa Oklahoma, hindi ka puwedeng pumarada sa loob ng 20 talampakan mula sa pasukan ng driveway ng fire station.","p":"Tama. Lumayo nang hindi bababa sa 20 talampakan mula sa pasukan ng fire station."},"ar":{"q":"في Oklahoma، إلى أي مدى يمكنك أن تركن قرب مدخل محطة الإطفاء على نفس جهة الشارع؟","o":["بأي قرب تريد","ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا"],"h1":"سيارات الإطفاء تحتاج مساحة لتخرج بسرعة.","h2":"في Oklahoma، يجب ألّا تركن على بُعد أقل من 20 قدمًا من مدخل محطة الإطفاء.","p":"صحيح. ابقَ على بُعد 20 قدمًا على الأقل من مدخل محطة الإطفاء."},"ref":{"doc":"OK","page":49}},{"id":"ok-047","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, a bicyclist comes to a stop sign, and there is no danger. What does the law allow the bicyclist to do?","o":["Slow down, yield, and go on without a full stop","Nothing: the bicyclist must always stop fully","Get off and walk the bike across","Wait for a car to wave them on"],"h1":"Oklahoma has a special stop sign rule for bicycles.","h2":"In Oklahoma, a bicyclist must slow down at a stop sign and yield, but may go on without stopping when there is no danger.","p":"Right. With no danger, a bicyclist may slow, yield and roll through a stop sign."},"es":{"q":"En Oklahoma, un ciclista llega a una señal de alto y no hay peligro. ¿Qué le permite hacer la ley?","o":["Reducir la velocidad, ceder el paso y seguir sin detenerse por completo","Nada: el ciclista siempre debe detenerse por completo","Bajarse y cruzar caminando con la bicicleta","Esperar a que un carro le haga señas para pasar"],"h1":"Oklahoma tiene una regla especial de la señal de alto para las bicicletas.","h2":"En Oklahoma, un ciclista debe reducir la velocidad ante una señal de alto y ceder el paso, pero puede seguir sin detenerse cuando no hay peligro.","p":"Correcto. Sin peligro, el ciclista puede reducir la velocidad, ceder el paso y seguir."},"zh":{"q":"在 Oklahoma，一个骑自行车的人来到停车标志前，而且没有危险。法律允许骑车人怎么做？","o":["减速、让行，不用完全停下就继续走","不允许：骑车人必须每次都完全停下","下车推着自行车走过去","等一辆汽车挥手让他走"],"h1":"Oklahoma 对自行车有特别的停车标志规定。","h2":"在 Oklahoma，骑自行车的人在停车标志前必须减速并让行，但没有危险时可以不停车继续走。","p":"对。没有危险时，骑车人可以减速、让行，然后慢慢通过停车标志。"},"vi":{"q":"Ở Oklahoma, một người đi xe đạp đến biển báo dừng (stop sign) và không có nguy hiểm. Luật cho phép người đi xe đạp làm gì?","o":["Chạy chậm lại, nhường đường và đi tiếp mà không cần dừng hẳn","Không gì cả: người đi xe đạp luôn phải dừng hẳn","Xuống xe và dắt xe đạp qua","Đợi một xe hơi ra hiệu cho đi"],"h1":"Oklahoma có quy định đặc biệt về biển báo dừng cho xe đạp.","h2":"Ở Oklahoma, người đi xe đạp phải chạy chậm lại ở biển báo dừng và nhường đường, nhưng có thể đi tiếp mà không dừng khi không có nguy hiểm.","p":"Đúng. Khi không có nguy hiểm, người đi xe đạp có thể chạy chậm, nhường đường và đi qua biển báo dừng."},"tl":{"q":"Sa Oklahoma, dumating ang isang nagbibisikleta sa stop sign, at walang panganib. Ano ang pinapayagan ng batas na gawin ng nagbibisikleta?","o":["Bumagal, magbigay-daan, at tumuloy nang hindi humihinto nang buo","Wala: dapat laging huminto nang buo ang nagbibisikleta","Bumaba at itulak ang bisikleta pagtawid","Hintayin na senyasan siya ng isang kotse"],"h1":"May espesyal na patakaran sa stop sign ang Oklahoma para sa mga bisikleta.","h2":"Sa Oklahoma, dapat bumagal at magbigay-daan ang nagbibisikleta sa stop sign, pero puwede siyang tumuloy nang hindi humihinto kapag walang panganib.","p":"Tama. Kapag walang panganib, puwedeng bumagal, magbigay-daan at tumuloy ang nagbibisikleta sa stop sign."},"ar":{"q":"في Oklahoma، وصل راكب دراجة هوائية إلى لافتة قف (stop) ولا يوجد خطر. ماذا يسمح القانون لراكب الدراجة أن يفعل؟","o":["يخفّف السرعة، ويعطي الأولوية، ويكمل بدون توقّف كامل","لا شيء: يجب على راكب الدراجة أن يتوقّف توقّفًا كاملًا دائمًا","ينزل ويمشي بالدراجة ليعبر","ينتظر أن تشير له سيارة ليمرّ"],"h1":"في Oklahoma قاعدة خاصة للدراجات عند لافتة قف.","h2":"في Oklahoma، يجب على راكب الدراجة أن يخفّف السرعة عند لافتة قف ويعطي الأولوية، لكن يمكنه أن يكمل بدون توقّف عندما لا يوجد خطر.","p":"صحيح. عندما لا يوجد خطر، يمكن لراكب الدراجة أن يخفّف السرعة ويعطي الأولوية ويمرّ من لافتة قف."},"ref":{"doc":"OK","page":52}},{"id":"ok-048","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, a bicyclist has stopped at a red light, and no traffic is a danger. What may the bicyclist do?","o":["Wait for green, no matter what","Ride onto the sidewalk to cross","Go on through the red light with care","Wait two full minutes, then go"],"h1":"For bicycles, Oklahoma treats a red light much like a stop sign.","h2":"In Oklahoma, a bicyclist must stop at a red light, but may then go on through it when it is safe and no traffic is a danger.","p":"Right. After stopping, a bicyclist may go through a red light when it is safe."},"es":{"q":"En Oklahoma, un ciclista se detuvo en un semáforo en rojo y ningún vehículo es un peligro. ¿Qué puede hacer el ciclista?","o":["Esperar la luz verde, pase lo que pase","Subirse a la banqueta para cruzar","Seguir a través de la luz roja con cuidado","Esperar dos minutos completos y luego seguir"],"h1":"Para las bicicletas, Oklahoma trata la luz roja casi como una señal de alto.","h2":"En Oklahoma, un ciclista debe detenerse ante una luz roja, pero luego puede seguir cuando es seguro y ningún vehículo es un peligro.","p":"Correcto. Después de detenerse, el ciclista puede pasar la luz roja cuando es seguro."},"zh":{"q":"在 Oklahoma，一个骑自行车的人已经在红灯前停下，而且没有车辆构成危险。骑车人可以怎么做？","o":["不管怎样都等绿灯","骑上人行道过去","小心地闯过红灯继续走","等满两分钟，然后走"],"h1":"对自行车来说，Oklahoma 把红灯看得很像停车标志。","h2":"在 Oklahoma，骑自行车的人必须在红灯前停下，但之后在安全、没有车辆构成危险时，可以通过红灯继续走。","p":"对。停下以后，安全时骑车人可以通过红灯。"},"vi":{"q":"Ở Oklahoma, một người đi xe đạp đã dừng ở đèn đỏ, và không có xe nào gây nguy hiểm. Người đi xe đạp được làm gì?","o":["Đợi đèn xanh, dù thế nào đi nữa","Chạy lên vỉa hè để qua","Đi tiếp qua đèn đỏ một cách cẩn thận","Đợi đủ hai phút rồi đi"],"h1":"Đối với xe đạp, Oklahoma coi đèn đỏ gần giống như biển báo dừng.","h2":"Ở Oklahoma, người đi xe đạp phải dừng ở đèn đỏ, nhưng sau đó có thể đi tiếp qua đèn đỏ khi an toàn và không có xe nào gây nguy hiểm.","p":"Đúng. Sau khi dừng, người đi xe đạp có thể đi qua đèn đỏ khi an toàn."},"tl":{"q":"Sa Oklahoma, huminto na ang isang nagbibisikleta sa pulang ilaw, at walang trapikong mapanganib. Ano ang puwedeng gawin ng nagbibisikleta?","o":["Hintayin ang berde, anuman ang mangyari","Umakyat sa sidewalk para tumawid","Tumuloy nang maingat kahit pula ang ilaw","Maghintay nang buong dalawang minuto, saka tumuloy"],"h1":"Para sa mga bisikleta, halos parang stop sign ang turing ng Oklahoma sa pulang ilaw.","h2":"Sa Oklahoma, dapat huminto ang nagbibisikleta sa pulang ilaw, pero puwede na siyang tumuloy kapag ligtas at walang trapikong mapanganib.","p":"Tama. Pagkatapos huminto, puwedeng tumuloy ang nagbibisikleta sa pulang ilaw kapag ligtas."},"ar":{"q":"في Oklahoma، توقّف راكب دراجة هوائية عند إشارة حمراء، ولا توجد سيارات تشكّل خطرًا. ماذا يمكن لراكب الدراجة أن يفعل؟","o":["ينتظر الأخضر مهما حدث","يصعد إلى الرصيف ليعبر","يكمل عبر الإشارة الحمراء بحذر","ينتظر دقيقتين كاملتين، ثم يمشي"],"h1":"بالنسبة للدراجات، تعامل Oklahoma الإشارة الحمراء مثل لافتة قف تقريبًا.","h2":"في Oklahoma، يجب على راكب الدراجة أن يتوقّف عند الإشارة الحمراء، لكن بعد ذلك يمكنه أن يكمل عبرها عندما يكون ذلك آمنًا ولا توجد سيارات تشكّل خطرًا.","p":"صحيح. بعد التوقّف، يمكن لراكب الدراجة أن يعبر الإشارة الحمراء عندما يكون ذلك آمنًا."},"ref":{"doc":"OK","page":52}},{"id":"ok-049","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, may you coast down a hill with your car in neutral?","o":["Yes, it saves fuel","No, it is against the law","Yes, on steep hills only","Yes, if no one is behind you"],"h1":"On a downhill, you need the engine to help control your speed.","h2":"In Oklahoma, coasting downhill with the car in neutral is against the law.","p":"Right. Coasting downhill in neutral is illegal in Oklahoma."},"es":{"q":"En Oklahoma, ¿puede bajar una cuesta en neutro, dejando rodar el carro?","o":["Sí, ahorra gasolina","No, es contra la ley","Sí, solo en cuestas empinadas","Sí, si nadie viene detrás"],"h1":"Al bajar una cuesta, necesita el motor para ayudar a controlar la velocidad.","h2":"En Oklahoma, bajar una cuesta con el carro en neutro es contra la ley.","p":"Correcto. Bajar una cuesta en neutro es ilegal en Oklahoma."},"zh":{"q":"在 Oklahoma，你可以挂空挡（neutral）滑行下坡吗？","o":["可以，这样省油","不可以，这是违法的","可以，只在陡坡上","可以，如果后面没有人"],"h1":"下坡时，你需要发动机帮你控制车速。","h2":"在 Oklahoma，挂空挡滑行下坡是违法的。","p":"对。在 Oklahoma，挂空挡滑行下坡是违法的。"},"vi":{"q":"Ở Oklahoma, bạn có được để xe ở số mo (neutral) và thả trôi xuống dốc không?","o":["Có, nó tiết kiệm xăng","Không, việc đó trái luật","Có, chỉ trên dốc cao","Có, nếu không có ai phía sau"],"h1":"Khi xuống dốc, bạn cần động cơ giúp kiểm soát tốc độ.","h2":"Ở Oklahoma, để xe ở số mo và thả trôi xuống dốc là trái luật.","p":"Đúng. Ở Oklahoma, thả trôi xuống dốc ở số mo là bất hợp pháp."},"tl":{"q":"Sa Oklahoma, puwede ka bang magpadausdos pababa ng burol na naka-neutral ang kotse mo?","o":["Oo, nakakatipid ito ng gasolina","Hindi, labag ito sa batas","Oo, sa matatarik na burol lang","Oo, kung walang tao sa likod mo"],"h1":"Pababa ng burol, kailangan mo ang makina para makontrol ang bilis mo.","h2":"Sa Oklahoma, labag sa batas ang magpadausdos pababa ng burol na naka-neutral ang kotse.","p":"Tama. Bawal sa Oklahoma ang magpadausdos pababa na naka-neutral."},"ar":{"q":"في Oklahoma، هل يمكنك أن تنزل منحدرًا وسيارتك على وضع الحياد (neutral) لتسير وحدها؟","o":["نعم، هذا يوفّر الوقود","لا، هذا مخالف للقانون","نعم، على المنحدرات الشديدة فقط","نعم، إذا لم يكن أحد خلفك"],"h1":"عند النزول، تحتاج المحرّك ليساعدك على التحكّم في السرعة.","h2":"في Oklahoma، نزول المنحدر والسيارة على وضع الحياد مخالف للقانون.","p":"صحيح. نزول المنحدر على وضع الحياد غير قانوني في Oklahoma."},"ref":{"doc":"OK","page":59}},{"id":"ok-050","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a driver with no insurance is in a crash. When will Service Oklahoma suspend that driver's license?","o":["Only if someone is killed","Only after a third crash","Only if the police ask for it","If anyone is hurt or the damage is $500 or more"],"h1":"The damage amount is quite low.","h2":"In Oklahoma, an uninsured driver in a crash with any injury or with property damage of $500 or more will have the license suspended.","p":"Right. Any injury or $500 in damage means suspension for an uninsured driver."},"es":{"q":"En Oklahoma, un conductor sin seguro tiene un choque. ¿Cuándo le suspende Service Oklahoma la licencia?","o":["Solo si alguien muere","Solo después de un tercer choque","Solo si la policía lo pide","Si alguien sale herido o los daños son de $500 o más"],"h1":"La cantidad de daños es bastante baja.","h2":"En Oklahoma, a un conductor sin seguro que tiene un choque con cualquier herido o con daños de $500 o más se le suspende la licencia.","p":"Correcto. Cualquier herido o $500 en daños significa suspensión para un conductor sin seguro."},"zh":{"q":"在 Oklahoma，一个没有保险的司机发生了车祸。Service Oklahoma 什么时候会暂停这个司机的驾照？","o":["只有在有人死亡时","只有在第三次车祸以后","只有在警察要求时","如果有人受伤，或损失是 $500 或更多"],"h1":"损失金额很低。","h2":"在 Oklahoma，没有保险的司机发生车祸，如果有任何人受伤，或财产损失是 $500 或更多，驾照就会被暂停。","p":"对。对没有保险的司机来说，有人受伤或损失 $500，就会暂停驾照。"},"vi":{"q":"Ở Oklahoma, một tài xế không có bảo hiểm gặp tai nạn. Khi nào Service Oklahoma sẽ treo bằng lái của tài xế đó?","o":["Chỉ khi có người chết","Chỉ sau tai nạn thứ ba","Chỉ khi cảnh sát yêu cầu","Nếu có ai bị thương hoặc thiệt hại từ $500 trở lên"],"h1":"Số tiền thiệt hại khá thấp.","h2":"Ở Oklahoma, tài xế không có bảo hiểm gặp tai nạn có người bị thương hoặc thiệt hại tài sản từ $500 trở lên sẽ bị treo bằng lái.","p":"Đúng. Có người bị thương hoặc thiệt hại $500 nghĩa là tài xế không có bảo hiểm bị treo bằng lái."},"tl":{"q":"Sa Oklahoma, nabangga ang isang driver na walang insurance. Kailan sususpindihin ng Service Oklahoma ang lisensiya ng driver na iyon?","o":["Kung may namatay lang","Pagkatapos lang ng ikatlong banggaan","Kung hihilingin lang ng pulis","Kung may nasaktan o $500 o higit pa ang pinsala"],"h1":"Medyo mababa ang halaga ng pinsala.","h2":"Sa Oklahoma, masususpinde ang lisensiya ng driver na walang insurance na nabangga kapag may nasaktan o kapag $500 o higit pa ang pinsala sa ari-arian.","p":"Tama. Anumang nasaktan o $500 na pinsala ay suspensiyon para sa driver na walang insurance."},"ar":{"q":"في Oklahoma، سائق ليس معه تأمين وقع له حادث. متى تُوقف Service Oklahoma رخصة هذا السائق؟","o":["فقط إذا مات أحد","فقط بعد الحادث الثالث","فقط إذا طلبت الشرطة ذلك","إذا أُصيب أحد أو كانت الأضرار $500 أو أكثر"],"h1":"مبلغ الأضرار منخفض جدًا.","h2":"في Oklahoma، السائق الذي ليس معه تأمين ووقع له حادث فيه أي إصابة أو أضرار في الممتلكات بقيمة $500 أو أكثر تُوقَف رخصته.","p":"صحيح. أي إصابة أو أضرار بقيمة $500 تعني إيقاف الرخصة للسائق الذي ليس معه تأمين."},"ref":{"doc":"OK","page":16}},{"id":"ok-051","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Fire trucks need room to reach the hydrant quickly.","h2":"In Oklahoma, it is illegal to park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Oklahoma, ¿qué tan cerca de un hidrante puede estacionarse?","o":["A no menos de 5 pies","A no menos de 10 pies","A no menos de 15 pies","A no menos de 30 pies"],"h1":"Los bomberos necesitan espacio para llegar rápido al hidrante.","h2":"En Oklahoma, es ilegal estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"ref":{"doc":"OK","page":49}},{"id":"ok-052","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, how close to a crosswalk at an intersection may you park?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 50 feet","No closer than 100 feet"],"h1":"It is a bit more than the distance for a fire hydrant.","h2":"In Oklahoma, it is illegal to park within 20 feet of a crosswalk at an intersection.","p":"Right. Park no closer than 20 feet to a crosswalk at an intersection."},"es":{"q":"En Oklahoma, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["A no menos de 10 pies","A no menos de 20 pies","A no menos de 50 pies","A no menos de 100 pies"],"h1":"Es un poco más que la distancia para un hidrante.","h2":"En Oklahoma, es ilegal estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. No se estacione a menos de 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"OK","page":49}},{"id":"ok-053","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, you want to park as you come up to a stop sign at the side of the road. How far from the sign must you stay?","o":["At least 30 feet","At least 15 feet","At least 10 feet","At least 75 feet"],"h1":"Drivers must be able to see the sign and the traffic signal clearly.","h2":"In Oklahoma, you may not park within 30 feet before a stop sign, flashing beacon or traffic signal at the side of the road.","p":"Right. Stay at least 30 feet back from a stop sign or signal at the side of the road."},"es":{"q":"En Oklahoma, usted quiere estacionarse al acercarse a una señal de alto al lado del camino. ¿A qué distancia de la señal debe quedarse?","o":["Por lo menos a 30 pies","Por lo menos a 15 pies","Por lo menos a 10 pies","Por lo menos a 75 pies"],"h1":"Los conductores deben poder ver bien la señal y el semáforo.","h2":"En Oklahoma, no puede estacionarse a menos de 30 pies antes de una señal de alto, una luz intermitente o un semáforo al lado del camino.","p":"Correcto. Quédese por lo menos a 30 pies de una señal de alto o un semáforo al lado del camino."},"ref":{"doc":"OK","page":49}},{"id":"ok-054","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, you parallel park next to a curb on a flat street. How close to the curb must your car be?","o":["Within 6 feet","Within 3 feet","Within 24 inches","Within 18 inches"],"h1":"It is a little more than one foot.","h2":"In Oklahoma, when you parallel park on a flat street, your car must be within 18 inches of the curb.","p":"Right. Park within 18 inches of the curb."},"es":{"q":"En Oklahoma, usted se estaciona en paralelo junto a la acera en una calle plana. ¿Qué tan cerca de la acera debe quedar su carro?","o":["A menos de 6 pies","A menos de 3 pies","A menos de 24 pulgadas","A menos de 18 pulgadas"],"h1":"Es un poco más de un pie.","h2":"En Oklahoma, cuando se estaciona en paralelo en una calle plana, su carro debe quedar a menos de 18 pulgadas de la acera.","p":"Correcto. Estaciónese a menos de 18 pulgadas de la acera."},"ref":{"doc":"OK","page":47}},{"id":"ok-055","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","It does not matter if the parking brake is set","Away from the curb"],"h1":"If the car rolls back, the back of the front tire should hit the curb.","h2":"In Oklahoma, when you park facing uphill next to a curb, turn your front wheels away from the curb and let the tire rest against it.","p":"Right. Uphill with a curb, turn the wheels away from the curb."},"es":{"q":"En Oklahoma, usted se estaciona cuesta arriba junto a la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la acera","Derechas hacia adelante","No importa si puso el freno de mano","Hacia el lado contrario de la acera"],"h1":"Si el carro rueda hacia atrás, la parte de atrás de la llanta delantera debe tocar la acera.","h2":"En Oklahoma, cuando se estaciona cuesta arriba junto a la acera, gire las ruedas delanteras hacia el lado contrario de la acera y deje que la llanta se apoye en ella.","p":"Correcto. Cuesta arriba con acera, gire las ruedas hacia el lado contrario de la acera."},"ref":{"doc":"OK","page":48}},{"id":"ok-056","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you are using high beams. A car is coming toward you. Within what distance must you switch to low beams?","o":["200 feet","500 feet","1,000 feet","2,000 feet"],"h1":"It is a long distance, because high beams can blind a driver far away.","h2":"In Oklahoma, you must dim your high beams to low beams within 1,000 feet of a car coming toward you.","p":"Right. Switch to low beams within 1,000 feet of an oncoming car."},"es":{"q":"En Oklahoma, usted lleva las luces altas. Viene un carro hacia usted. ¿A qué distancia debe cambiar a luces bajas?","o":["200 pies","500 pies","1,000 pies","2,000 pies"],"h1":"Es una distancia larga, porque las luces altas pueden cegar a un conductor que está lejos.","h2":"En Oklahoma, debe cambiar de luces altas a luces bajas a menos de 1,000 pies de un carro que viene hacia usted.","p":"Correcto. Cambie a luces bajas a menos de 1,000 pies de un carro que viene de frente."},"ref":{"doc":"OK","page":59}},{"id":"ok-057","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, you are using high beams and you come up behind another car. Within what distance must you switch to low beams?","o":["100 feet","600 feet","300 feet","1,000 feet"],"h1":"It is less than the distance for a car coming toward you.","h2":"In Oklahoma, you must dim your high beams to low beams within 600 feet of a car you are following.","p":"Right. Switch to low beams within 600 feet of the car ahead."},"es":{"q":"En Oklahoma, usted lleva las luces altas y se acerca por detrás a otro carro. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","600 pies","300 pies","1,000 pies"],"h1":"Es menos que la distancia para un carro que viene de frente.","h2":"En Oklahoma, debe cambiar de luces altas a luces bajas a menos de 600 pies de un carro que va delante de usted.","p":"Correcto. Cambie a luces bajas a menos de 600 pies del carro de adelante."},"ref":{"doc":"OK","page":59}},{"id":"ok-058","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, at what times must your headlights be on?","o":["From 30 minutes after sunset until 30 minutes before sunrise","From 2 hours after sunset until 2 hours before sunrise","Only between midnight and 5 a.m.","Only on roads with no streetlights"],"h1":"The time is counted from sunset and sunrise, with a short gap.","h2":"In Oklahoma, you must use your headlights from 30 minutes after sunset until 30 minutes before sunrise, and whenever a sign says so.","p":"Right. Headlights go on from 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Oklahoma, ¿en qué horario debe llevar los faros encendidos?","o":["Desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol","Desde 2 horas después de la puesta del sol hasta 2 horas antes de la salida del sol","Solo entre la medianoche y las 5 a.m.","Solo en caminos sin alumbrado"],"h1":"El horario se cuenta desde la puesta y la salida del sol, con un margen corto.","h2":"En Oklahoma, debe usar los faros desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol, y siempre que una señal lo indique.","p":"Correcto. Los faros se encienden desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol."},"ref":{"doc":"OK","page":59}},{"id":"ok-059","scope":"OK","cat":"signals","sign":null,"c":2,"en":{"q":"In Oklahoma, how far ahead should you start to signal before you turn, slow down or stop?","o":["At least 20 feet","At least 50 feet","At least 100 feet, or one third of a block","At least half a mile"],"h1":"In a city, it is about a third of a block.","h2":"In Oklahoma, you should signal for at least 100 feet, or one third of a block, before you turn, slow down or stop.","p":"Right. Signal at least 100 feet, or a third of a block, ahead."},"es":{"q":"En Oklahoma, ¿con cuánta anticipación debe empezar a señalar antes de girar, reducir la velocidad o detenerse?","o":["Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 100 pies, o un tercio de cuadra","Por lo menos media milla"],"h1":"En la ciudad, es más o menos un tercio de cuadra.","h2":"En Oklahoma, debe señalar por lo menos 100 pies, o un tercio de cuadra, antes de girar, reducir la velocidad o detenerse.","p":"Correcto. Señale por lo menos 100 pies, o un tercio de cuadra, antes."},"ref":{"doc":"OK","page":36}},{"id":"ok-060","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, what is the usual minimum speed limit on an expressway?","o":["30 mph","40 mph","50 mph","Expressways have no minimum"],"h1":"Driving too slowly on an expressway is against the law.","h2":"In Oklahoma, the minimum speed limit on an expressway is usually 40 mph.","p":"Right. The usual expressway minimum is 40 mph."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad mínima habitual en una vía expresa?","o":["30 mph","40 mph","50 mph","Las vías expresas no tienen mínimo"],"h1":"Manejar demasiado lento en una vía expresa es contra la ley.","h2":"En Oklahoma, el límite de velocidad mínima en una vía expresa suele ser de 40 mph.","p":"Correcto. El mínimo habitual en una vía expresa es de 40 mph."},"ref":{"doc":"OK","page":33}},{"id":"ok-061","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, what is the speed limit on a controlled-access highway that is not a turnpike, when no other limit is posted?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"It is 5 mph less than the turnpike limit.","h2":"In Oklahoma, the speed limit on a controlled-access highway is 75 mph unless a sign shows a different limit.","p":"Right. Controlled-access highways allow 75 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una carretera de acceso controlado que no es autopista de peaje, cuando no hay otro límite señalado?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Es 5 mph menos que el límite de las autopistas de peaje.","h2":"En Oklahoma, el límite de velocidad en una carretera de acceso controlado es de 75 mph, a menos que una señal indique otro límite.","p":"Correcto. En las carreteras de acceso controlado se permite 75 mph, salvo que se indique otra cosa."},"ref":{"doc":"OK","page":41}},{"id":"ok-062","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, what is the speed limit on an undivided state highway when no other limit is posted?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"It is 10 mph more than the county road limit.","h2":"In Oklahoma, the speed limit on an undivided state highway is 65 mph unless a sign shows a different limit.","p":"Right. Undivided state highways allow 65 mph unless posted otherwise."},"es":{"q":"En Oklahoma, ¿cuál es el límite de velocidad en una carretera estatal sin división central cuando no hay otro límite señalado?","o":["55 mph","65 mph","70 mph","75 mph"],"h1":"Es 10 mph más que el límite de los caminos del condado.","h2":"En Oklahoma, el límite de velocidad en una carretera estatal sin división central es de 65 mph, a menos que una señal indique otro límite.","p":"Correcto. En las carreteras estatales sin división central se permite 65 mph, salvo que se indique otra cosa."},"ref":{"doc":"OK","page":41}},{"id":"ok-063","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, one way to judge your following distance is by car lengths. How much space should you leave?","o":["One car length for every 10 mph of speed","One car length for every 20 mph of speed","Two car lengths at any speed","One car length at any speed"],"h1":"The faster you go, the more car lengths you need.","h2":"In Oklahoma, you should leave at least one car length for every 10 mph of speed between you and the car ahead.","p":"Right. Leave one car length for every 10 mph."},"es":{"q":"En Oklahoma, una forma de calcular la distancia de seguimiento es por largos de carro. ¿Cuánto espacio debe dejar?","o":["Un largo de carro por cada 10 mph de velocidad","Un largo de carro por cada 20 mph de velocidad","Dos largos de carro a cualquier velocidad","Un largo de carro a cualquier velocidad"],"h1":"Mientras más rápido va, más largos de carro necesita.","h2":"En Oklahoma, debe dejar por lo menos un largo de carro por cada 10 mph de velocidad entre usted y el carro de adelante.","p":"Correcto. Deje un largo de carro por cada 10 mph."},"ref":{"doc":"OK","page":44}},{"id":"ok-064","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you use the three-second rule for following distance. How many seconds should you count in bad weather or on poor roads?","o":["Two","Three","Four","Ten"],"h1":"Add a little more time than in good weather.","h2":"In Oklahoma, in bad weather or on poor roads you should increase your following count to four seconds.","p":"Right. In bad weather, count four seconds."},"es":{"q":"En Oklahoma, usted usa la regla de los tres segundos para la distancia de seguimiento. ¿Cuántos segundos debe contar con mal tiempo o en caminos en mal estado?","o":["Dos","Tres","Cuatro","Diez"],"h1":"Agregue un poco más de tiempo que con buen tiempo.","h2":"En Oklahoma, con mal tiempo o en caminos en mal estado debe aumentar la cuenta de seguimiento a cuatro segundos.","p":"Correcto. Con mal tiempo, cuente cuatro segundos."},"ref":{"doc":"OK","page":44}},{"id":"ok-065","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, before you pass on the left, how much clear road with no No Passing Zone should you see ahead?","o":["At least 50 feet","At least 100 feet","At least 1 mile","At least 200 feet"],"h1":"It is the same distance a caravan leaves between vehicles outside town.","h2":"In Oklahoma, before you pass on the left, check that there are at least 200 feet of clear road ahead with no No Passing Zone.","p":"Right. You need at least 200 feet of clear road to pass."},"es":{"q":"En Oklahoma, antes de rebasar por la izquierda, ¿cuánto camino libre, sin zona de no rebasar, debe ver adelante?","o":["Por lo menos 50 pies","Por lo menos 100 pies","Por lo menos 1 milla","Por lo menos 200 pies"],"h1":"Es la misma distancia que deja una caravana entre vehículos fuera de la ciudad.","h2":"En Oklahoma, antes de rebasar por la izquierda, verifique que haya por lo menos 200 pies de camino libre adelante, sin zona de no rebasar.","p":"Correcto. Necesita por lo menos 200 pies de camino libre para rebasar."},"ref":{"doc":"OK","page":35}},{"id":"ok-066","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, you may not pass within a certain distance of a place where your view is blocked, like a bridge, tunnel or railroad crossing. What is that distance?","o":["25 feet","50 feet","100 feet","500 feet"],"h1":"It is half the clear distance you need ahead to pass.","h2":"In Oklahoma, you must not pass within 100 feet of a place where your view is blocked, such as a bridge, tunnel, railroad crossing or intersection.","p":"Right. Do not pass within 100 feet of a blocked view."},"es":{"q":"En Oklahoma, no puede rebasar a cierta distancia de un lugar donde no puede ver bien, como un puente, un túnel o un cruce de ferrocarril. ¿Cuál es esa distancia?","o":["25 pies","50 pies","100 pies","500 pies"],"h1":"Es la mitad del camino libre que necesita adelante para rebasar.","h2":"En Oklahoma, no debe rebasar a menos de 100 pies de un lugar donde no puede ver bien, como un puente, un túnel, un cruce de ferrocarril o una intersección.","p":"Correcto. No rebase a menos de 100 pies de un lugar sin buena visibilidad."},"ref":{"doc":"OK","page":35}},{"id":"ok-067","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, may you go over the speed limit to finish passing another vehicle?","o":["Yes, by up to 10 mph","No, never","Yes, if the road ahead is clear","Yes, but only on a highway"],"h1":"The speed limit still applies while you pass.","h2":"In Oklahoma, you may not go over the speed limit to pass another vehicle.","p":"Right. Passing never allows you to break the speed limit."},"es":{"q":"En Oklahoma, ¿puede pasar el límite de velocidad para terminar de rebasar a otro vehículo?","o":["Sí, hasta 10 mph más","No, nunca","Sí, si el camino adelante está libre","Sí, pero solo en carretera"],"h1":"El límite de velocidad se aplica también mientras rebasa.","h2":"En Oklahoma, no puede pasar el límite de velocidad para rebasar a otro vehículo.","p":"Correcto. Rebasar nunca le permite pasar el límite de velocidad."},"ref":{"doc":"OK","page":35}},{"id":"ok-068","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you are passing a bicycle rider going your way. How much space must you leave between your car and the bicycle?","o":["At least 1 foot","At least 2 feet","At least 3 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Oklahoma, when you pass a bicycle going the same way, you must leave at least 3 feet until you are safely past it.","p":"Right. Leave at least 3 feet when you pass a bicycle."},"es":{"q":"En Oklahoma, usted está rebasando a un ciclista que va en su misma dirección. ¿Cuánto espacio debe dejar entre su carro y la bicicleta?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 3 pies","Por lo menos 10 pies"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Oklahoma, cuando rebasa a una bicicleta que va en su misma dirección, debe dejar por lo menos 3 pies hasta que la haya pasado sin peligro.","p":"Correcto. Deje por lo menos 3 pies al rebasar a una bicicleta."},"ref":{"doc":"OK","page":51}},{"id":"ok-069","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you have points on your driving record. How long with no traffic convictions brings your points back to zero?","o":["3 years in a row","6 months","10 years","Points never go away"],"h1":"It takes a few years in a row with a clean record.","h2":"In Oklahoma, your points go back to zero after three years in a row with no traffic violation convictions.","p":"Right. Three clean years in a row bring your points to zero."},"es":{"q":"En Oklahoma, usted tiene puntos en su historial de manejo. ¿Cuánto tiempo sin condenas de tránsito hace que sus puntos vuelvan a cero?","o":["3 años seguidos","6 meses","10 años","Los puntos nunca se borran"],"h1":"Se necesitan algunos años seguidos con un historial limpio.","h2":"En Oklahoma, sus puntos vuelven a cero después de tres años seguidos sin condenas por infracciones de tránsito.","p":"Correcto. Tres años seguidos sin infracciones dejan sus puntos en cero."},"ref":{"doc":"OK","page":72}},{"id":"ok-070","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, how far behind a large truck can its blind spot reach?","o":["10 feet","30 feet","75 feet","Up to 200 feet"],"h1":"It is much longer than a car.","h2":"In Oklahoma, the blind spot behind a large truck can reach up to 200 feet.","p":"Right. A truck's rear blind spot can reach up to 200 feet."},"es":{"q":"En Oklahoma, ¿hasta qué distancia detrás de un camión grande puede llegar su punto ciego?","o":["10 pies","30 pies","75 pies","Hasta 200 pies"],"h1":"Es mucho más largo que un carro.","h2":"En Oklahoma, el punto ciego detrás de un camión grande puede llegar hasta 200 pies.","p":"Correcto. El punto ciego trasero de un camión puede llegar hasta 200 pies."},"ref":{"doc":"OK","page":54}},{"id":"ok-071","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, you are stopped behind a large truck on an uphill road. Where in your lane should you stay?","o":["Close behind the truck, in the middle of your lane","On the right side, on the shoulder","Beside the truck, in the next lane","On the left side of your lane, where the driver can see you"],"h1":"Think about where the truck driver's mirror can show you.","h2":"In Oklahoma, when you are stopped behind a truck on an uphill road, stay to the left in your lane so the driver can see you, and leave extra space in front.","p":"Right. Stay to the left in your lane so the truck driver can see you."},"es":{"q":"En Oklahoma, usted está detenido detrás de un camión grande en una cuesta arriba. ¿En qué parte de su carril debe quedarse?","o":["Muy cerca del camión, en el centro de su carril","A la derecha, en el acotamiento","Al lado del camión, en el otro carril","Al lado izquierdo de su carril, donde el conductor lo puede ver"],"h1":"Piense dónde lo puede mostrar el espejo del conductor del camión.","h2":"En Oklahoma, cuando está detenido detrás de un camión en una cuesta arriba, quédese a la izquierda de su carril para que el conductor lo vea, y deje espacio extra adelante.","p":"Correcto. Quédese a la izquierda de su carril para que el conductor del camión lo vea."},"ref":{"doc":"OK","page":54}},{"id":"ok-072","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you just passed a large truck, and the truck driver blinks the truck's lights. What does it mean?","o":["You are driving too slowly","Your own lights are off","You are clear to move back in front of the truck","The truck is about to turn"],"h1":"Truck drivers use this signal to help cars that are passing.","h2":"In Oklahoma, when a truck driver blinks the lights after you pass, it means you are clear to move back in front; still wait until you can see the front of the truck in your mirror.","p":"Right. The blinking lights tell you that you are clear to move back in."},"es":{"q":"En Oklahoma, usted acaba de rebasar a un camión grande y el conductor del camión parpadea las luces. ¿Qué significa?","o":["Que usted va demasiado lento","Que sus propias luces están apagadas","Que puede regresar sin peligro delante del camión","Que el camión va a girar"],"h1":"Los camioneros usan esta señal para ayudar a los carros que rebasan.","h2":"En Oklahoma, cuando un camionero parpadea las luces después de que usted rebasa, significa que puede regresar delante del camión; aun así, espere hasta ver el frente del camión en su espejo.","p":"Correcto. Las luces que parpadean le indican que puede regresar a su carril."},"ref":{"doc":"OK","page":54}},{"id":"ok-073","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, a train is coming at a railroad crossing. Where must you stop?","o":["Within 50 feet, but no closer than 15 feet, from the nearest rail","Right next to the nearest rail","Within 5 to 10 feet of the nearest rail","At least 100 feet back from the nearest rail"],"h1":"There is both a farthest and a closest point to stop.","h2":"In Oklahoma, when a train is coming, you must stop within 50 feet but no closer than 15 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Oklahoma, viene un tren en un cruce de ferrocarril. ¿Dónde debe detenerse?","o":["A menos de 50 pies, pero no a menos de 15 pies, del riel más cercano","Justo al lado del riel más cercano","A entre 5 y 10 pies del riel más cercano","Por lo menos a 100 pies del riel más cercano"],"h1":"Hay un punto más lejano y un punto más cercano para detenerse.","h2":"En Oklahoma, cuando viene un tren, debe detenerse a menos de 50 pies, pero no a menos de 15 pies, del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"OK","page":56}},{"id":"ok-074","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, your car is stuck on the railroad tracks and the crossing lights start to flash. How much time may you have before the train arrives?","o":["As little as 20 seconds","About 5 minutes","About 2 minutes","About 1 hour"],"h1":"It is less than half a minute, so get out right away.","h2":"In Oklahoma, once the crossing lights start to flash, you may have only 20 seconds before the train reaches the crossing.","p":"Right. You may have only 20 seconds, so get out right away."},"es":{"q":"En Oklahoma, su carro está atascado en las vías del tren y las luces del cruce empiezan a parpadear. ¿Cuánto tiempo puede tener antes de que llegue el tren?","o":["Apenas 20 segundos","Unos 5 minutos","Unos 2 minutos","Más o menos 1 hora"],"h1":"Es menos de medio minuto, así que salga de inmediato.","h2":"En Oklahoma, cuando las luces del cruce empiezan a parpadear, puede tener solo 20 segundos antes de que el tren llegue al cruce.","p":"Correcto. Puede tener solo 20 segundos, así que salga de inmediato."},"ref":{"doc":"OK","page":57}},{"id":"ok-075","scope":"OK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oklahoma, you are already driving across the tracks when the warning lights begin to flash. What should you do?","o":["Stop on the tracks","Back up off the tracks","Keep moving and finish crossing","Get out of the car right away"],"h1":"The signals give you enough time, and the far gate will not trap you.","h2":"In Oklahoma, if the lights begin to flash while you are crossing the tracks, keep moving and finish crossing; do not stop or back up.","p":"Right. Keep moving and clear the tracks."},"es":{"q":"En Oklahoma, usted ya está cruzando las vías cuando las luces de advertencia empiezan a parpadear. ¿Qué debe hacer?","o":["Detenerse sobre las vías","Retroceder para salir de las vías","Seguir avanzando y terminar de cruzar","Bajarse del carro de inmediato"],"h1":"Las señales le dan tiempo suficiente, y la barrera del otro lado no lo va a encerrar.","h2":"En Oklahoma, si las luces empiezan a parpadear mientras cruza las vías, siga avanzando y termine de cruzar; no se detenga ni retroceda.","p":"Correcto. Siga avanzando y salga de las vías."},"ref":{"doc":"OK","page":57}},{"id":"ok-076","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, a vehicle shows the Slow Moving Vehicle emblem. How fast do such vehicles travel on public roads?","o":["55 mph or less","45 mph or less","35 mph or less","25 mph or less"],"h1":"Farm and road equipment moves much slower than cars.","h2":"In Oklahoma, the Slow Moving Vehicle emblem is used on vehicles, like farm and road equipment, that travel at 25 mph or less.","p":"Right. Vehicles with this emblem go 25 mph or less."},"es":{"q":"En Oklahoma, un vehículo lleva el emblema de vehículo lento (Slow Moving Vehicle). ¿A qué velocidad viajan estos vehículos en los caminos públicos?","o":["55 mph o menos","45 mph o menos","35 mph o menos","25 mph o menos"],"h1":"La maquinaria agrícola y de caminos se mueve mucho más despacio que los carros.","h2":"En Oklahoma, el emblema de vehículo lento se usa en vehículos, como maquinaria agrícola y de caminos, que viajan a 25 mph o menos.","p":"Correcto. Los vehículos con este emblema van a 25 mph o menos."},"ref":{"doc":"OK","page":58}},{"id":"ok-077","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, the lead car of a funeral procession has entered an intersection. Then the light turns red. What may the other cars in the procession do?","o":["They must stop and wait for green","They may follow through the intersection","They may only turn right","They may go only if a police officer is there"],"h1":"A procession is allowed to stay together.","h2":"In Oklahoma, once the lead vehicle of a funeral procession enters an intersection, the rest of the procession may follow through, whatever the signals show.","p":"Right. The procession may follow its lead vehicle through the intersection."},"es":{"q":"En Oklahoma, el primer carro de un cortejo fúnebre ya entró en una intersección. Luego el semáforo cambia a rojo. ¿Qué pueden hacer los demás carros del cortejo?","o":["Deben detenerse y esperar la luz verde","Pueden seguir a través de la intersección","Solo pueden girar a la derecha","Solo pueden seguir si hay un policía"],"h1":"A un cortejo se le permite mantenerse unido.","h2":"En Oklahoma, cuando el primer vehículo de un cortejo fúnebre entra en una intersección, los demás pueden seguir a través de ella, sin importar lo que indiquen las señales.","p":"Correcto. El cortejo puede seguir a su primer vehículo a través de la intersección."},"ref":{"doc":"OK","page":28}},{"id":"ok-078","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a person who is blind may use a cane. What kind of cane should tell you to yield?","o":["Only an all-white cane","An all-white cane, a white cane with a red tip, or a chrome cane","Only a red cane","Only a cane with a bell"],"h1":"There is more than one kind.","h2":"In Oklahoma, a blind pedestrian's cane may be all white, white with a red tip, or chrome, and you must yield to that person.","p":"Right. White, red-tipped white, or chrome canes all mean you must yield."},"es":{"q":"En Oklahoma, una persona ciega puede usar un bastón. ¿Qué tipo de bastón le indica que debe ceder el paso?","o":["Solo un bastón todo blanco","Un bastón todo blanco, uno blanco con punta roja, o uno cromado","Solo un bastón rojo","Solo un bastón con campana"],"h1":"Hay más de un tipo.","h2":"En Oklahoma, el bastón de un peatón ciego puede ser todo blanco, blanco con punta roja o cromado, y usted debe cederle el paso a esa persona.","p":"Correcto. Un bastón blanco, blanco con punta roja o cromado significa que debe ceder el paso."},"ref":{"doc":"OK","page":28}},{"id":"ok-079","scope":"OK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oklahoma, you are driving in the left lane when a police officer signals you to stop. Where should you pull over?","o":["Stop right where you are, in the left lane","Onto the left shoulder","Onto the right shoulder, even if you must cross several lanes","Take the next exit and stop there"],"h1":"It is the same side you use for emergency vehicles.","h2":"In Oklahoma, if an officer signals you to stop while you are in the left lane, you must still pull over to the right shoulder, even if you must cross several lanes.","p":"Right. Always move safely to the right shoulder."},"es":{"q":"En Oklahoma, usted va por el carril izquierdo cuando un policía le indica que se detenga. ¿Dónde debe orillarse?","o":["Detenerse ahí mismo, en el carril izquierdo","En el acotamiento izquierdo","En el acotamiento derecho, aunque tenga que cruzar varios carriles","Tomar la próxima salida y detenerse ahí"],"h1":"Es el mismo lado que usa para los vehículos de emergencia.","h2":"En Oklahoma, si un policía le indica que se detenga cuando va por el carril izquierdo, de todos modos debe orillarse en el acotamiento derecho, aunque tenga que cruzar varios carriles.","p":"Correcto. Siempre muévase con cuidado al acotamiento derecho."},"ref":{"doc":"OK","page":29}},{"id":"ok-080","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, two cars arrive at a four-way stop at the same time. Which driver must yield?","o":["The driver on the left","The driver on the right","The driver going faster","The driver of the larger vehicle"],"h1":"Look to your right: that driver goes first.","h2":"In Oklahoma, when two vehicles reach a four-way stop at the same time, the driver on the left yields to the driver on the right.","p":"Right. The driver on the left yields to the driver on the right."},"es":{"q":"En Oklahoma, dos carros llegan al mismo tiempo a un alto de cuatro vías. ¿Qué conductor debe ceder el paso?","o":["El conductor de la izquierda","El conductor de la derecha","El conductor que va más rápido","El conductor del vehículo más grande"],"h1":"Mire a su derecha: ese conductor pasa primero.","h2":"En Oklahoma, cuando dos vehículos llegan al mismo tiempo a un alto de cuatro vías, el conductor de la izquierda le cede el paso al de la derecha.","p":"Correcto. El conductor de la izquierda cede el paso al de la derecha."},"ref":{"doc":"OK","page":29}},{"id":"ok-081","scope":"OK","cat":"signals","sign":null,"c":1,"en":{"q":"In Oklahoma, you are on a one-way street at a red light. You want to turn left onto another one-way street, and no sign forbids it. What may you do?","o":["Wait for the green light","Stop fully, then turn left while yielding to people and traffic","Turn left without stopping","Turn only if a police officer waves you on"],"h1":"It works like a right turn on red.","h2":"In Oklahoma, after a complete stop, you may turn left on red from a one-way street onto a one-way street, unless a sign forbids it, yielding to pedestrians and vehicles.","p":"Right. After a full stop, you may turn left on red from one one-way street onto another."},"es":{"q":"En Oklahoma, usted está en una calle de un solo sentido con la luz roja. Quiere girar a la izquierda hacia otra calle de un solo sentido, y ninguna señal lo prohíbe. ¿Qué puede hacer?","o":["Esperar la luz verde","Detenerse por completo y luego girar a la izquierda, cediendo el paso a peatones y vehículos","Girar a la izquierda sin detenerse","Girar solo si un policía le hace señas"],"h1":"Funciona como un giro a la derecha con luz roja.","h2":"En Oklahoma, después de detenerse por completo, puede girar a la izquierda con luz roja desde una calle de un solo sentido hacia otra de un solo sentido, a menos que una señal lo prohíba, cediendo el paso a peatones y vehículos.","p":"Correcto. Después de detenerse por completo, puede girar a la izquierda con luz roja de una calle de un solo sentido a otra."},"ref":{"doc":"OK","page":26}},{"id":"ok-082","scope":"OK","cat":"signals","sign":null,"c":2,"en":{"q":"In Oklahoma, a lane control signal over your lane shows a flashing yellow X. What does it mean?","o":["The lane is closed","The lane is open for all traffic","You may use the lane to turn left","Speed up to clear the lane"],"h1":"A steady yellow X means clear the lane; flashing means something else.","h2":"In Oklahoma, a flashing yellow X over a lane means you may use that lane to make a left turn.","p":"Right. A flashing yellow X means left turns are allowed from that lane."},"es":{"q":"En Oklahoma, una señal de control de carril sobre su carril muestra una X amarilla intermitente. ¿Qué significa?","o":["El carril está cerrado","El carril está abierto para todo el tráfico","Puede usar el carril para girar a la izquierda","Acelere para salir del carril"],"h1":"Una X amarilla fija significa que debe salir del carril; si parpadea, significa otra cosa.","h2":"En Oklahoma, una X amarilla intermitente sobre un carril significa que puede usar ese carril para girar a la izquierda.","p":"Correcto. Una X amarilla intermitente significa que se permite girar a la izquierda desde ese carril."},"ref":{"doc":"OK","page":27}},{"id":"ok-083","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, what is the recommended speed for making a turn?","o":["5 mph or less","10 mph or less","20 mph or less","25 mph or less"],"h1":"It is a slow speed, about the pace of a bicycle.","h2":"In Oklahoma, the recommended speed when turning is 10 mph or less.","p":"Right. Turn at 10 mph or less."},"es":{"q":"En Oklahoma, ¿cuál es la velocidad recomendada para dar una vuelta?","o":["5 mph o menos","10 mph o menos","20 mph o menos","25 mph o menos"],"h1":"Es una velocidad lenta, más o menos la de una bicicleta.","h2":"En Oklahoma, la velocidad recomendada para dar una vuelta es de 10 mph o menos.","p":"Correcto. Dé la vuelta a 10 mph o menos."},"ref":{"doc":"OK","page":41}},{"id":"ok-084","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, you are waiting to turn left while oncoming cars pass. How should your front wheels be?","o":["Turned to the left, ready to go","Turned to the right","It does not matter","Pointed straight ahead until you can finish the turn"],"h1":"Think about what happens if a car hits you from behind.","h2":"In Oklahoma, keep your front wheels straight while you wait to turn left, so a crash from behind will not push you into oncoming cars.","p":"Right. Keep your wheels straight until you can finish the turn."},"es":{"q":"En Oklahoma, usted espera para girar a la izquierda mientras pasan los carros que vienen de frente. ¿Cómo deben estar sus ruedas delanteras?","o":["Giradas a la izquierda, listas para salir","Giradas a la derecha","No importa","Derechas hacia adelante hasta que pueda terminar el giro"],"h1":"Piense en lo que pasa si un carro lo choca por detrás.","h2":"En Oklahoma, mantenga las ruedas delanteras derechas mientras espera para girar a la izquierda, para que un choque por detrás no lo empuje hacia los carros que vienen de frente.","p":"Correcto. Mantenga las ruedas derechas hasta que pueda terminar el giro."},"ref":{"doc":"OK","page":36}},{"id":"ok-085","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, you are turning from a one-way street. Which lane should you turn from?","o":["Any lane","The middle lane","The lane nearest the curb on the side you are turning to","The lane farthest from your turn"],"h1":"Turn from the edge of the street, on the side of your turn.","h2":"In Oklahoma, when you turn from a one-way or divided street, always turn from the lane nearest the curb on the side you are turning to.","p":"Right. Turn from the lane nearest the curb on that side."},"es":{"q":"En Oklahoma, usted va a girar desde una calle de un solo sentido. ¿Desde qué carril debe girar?","o":["Desde cualquier carril","Desde el carril del centro","Desde el carril más cercano a la acera del lado hacia el que gira","Desde el carril más lejano de su giro"],"h1":"Gire desde la orilla de la calle, del lado de su giro.","h2":"En Oklahoma, cuando gira desde una calle de un solo sentido o dividida, siempre gire desde el carril más cercano a la acera del lado hacia el que gira.","p":"Correcto. Gire desde el carril más cercano a la acera de ese lado."},"ref":{"doc":"OK","page":38}},{"id":"ok-086","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, you need to turn around on a city street. Should you back into an intersection to do it?","o":["Yes, if no cars are coming","Yes, but only at night","No; it is safer to drive around the block","Yes, if your hazard lights are on"],"h1":"There is a safer way that uses only forward driving.","h2":"In Oklahoma, you should never back into an intersection to turn around; it is much safer to drive around the block.","p":"Right. Drive around the block instead of backing into an intersection."},"es":{"q":"En Oklahoma, usted necesita dar la vuelta en una calle de la ciudad. ¿Debe retroceder hacia una intersección para hacerlo?","o":["Sí, si no vienen carros","Sí, pero solo de noche","No; es más seguro darle la vuelta a la cuadra","Sí, si tiene encendidas las luces de emergencia"],"h1":"Hay una forma más segura manejando solo hacia adelante.","h2":"En Oklahoma, nunca debe retroceder hacia una intersección para dar la vuelta; es mucho más seguro darle la vuelta a la cuadra.","p":"Correcto. Dele la vuelta a la cuadra en lugar de retroceder hacia una intersección."},"ref":{"doc":"OK","page":39}},{"id":"ok-087","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, during which months do crashes with deer happen most often?","o":["October to December","April to June","January to March","July to September"],"h1":"Think of the fall season.","h2":"In Oklahoma, crashes between deer and vehicles happen most often from October to December.","p":"Right. Watch for deer most of all from October to December."},"es":{"q":"En Oklahoma, ¿en qué meses ocurren con más frecuencia los choques con venados?","o":["De octubre a diciembre","De abril a junio","De enero a marzo","De julio a septiembre"],"h1":"Piense en el otoño.","h2":"En Oklahoma, los choques entre venados y vehículos ocurren con más frecuencia de octubre a diciembre.","p":"Correcto. Tenga más cuidado con los venados de octubre a diciembre."},"ref":{"doc":"OK","page":61}},{"id":"ok-088","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, which of these drivers may not make hand-held phone calls while driving?","o":["Commercial drivers and public transit drivers","Drivers of rental cars","Drivers over 65","Drivers on rural roads"],"h1":"Think of people who drive for their job.","h2":"In Oklahoma, commercial drivers and public transit drivers are not allowed to make hand-held phone calls while driving.","p":"Right. Commercial and public transit drivers may not make hand-held calls."},"es":{"q":"En Oklahoma, ¿cuáles de estos conductores no pueden hacer llamadas con el teléfono en la mano mientras manejan?","o":["Los conductores comerciales y los de transporte público","Los conductores de carros rentados","Los conductores mayores de 65 años","Los conductores en caminos rurales"],"h1":"Piense en las personas que manejan como trabajo.","h2":"En Oklahoma, los conductores comerciales y los de transporte público no pueden hacer llamadas con el teléfono en la mano mientras manejan.","p":"Correcto. Los conductores comerciales y de transporte público no pueden hacer llamadas con el teléfono en la mano."},"ref":{"doc":"OK","page":61}},{"id":"ok-089","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, at a low-water crossing, how deep can water be and still make you lose control of your car?","o":["At least 3 feet","As little as 6 inches","At least 5 feet","Water cannot move a car"],"h1":"It is much less than you might think.","h2":"In Oklahoma, as little as 6 inches of water may be enough to make you lose control of your vehicle.","p":"Right. Just 6 inches of water can make you lose control."},"es":{"q":"En Oklahoma, en un cruce bajo con agua, ¿qué tan profunda puede ser el agua y aun así hacerle perder el control del carro?","o":["Por lo menos 3 pies","Apenas 6 pulgadas","Por lo menos 5 pies","El agua no puede mover un carro"],"h1":"Es mucho menos de lo que usted cree.","h2":"En Oklahoma, apenas 6 pulgadas de agua pueden bastar para que pierda el control de su vehículo.","p":"Correcto. Solo 6 pulgadas de agua pueden hacerle perder el control."},"ref":{"doc":"OK","page":63}},{"id":"ok-090","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, you have a minor crash and no one is hurt. Your car is blocking traffic. What must you do?","o":["Leave it there so the police can see how it happened","Move it out of traffic, or have it moved","Leave the scene and call later","Turn off your lights and wait inside"],"h1":"A blocked road can lead to more crashes.","h2":"In Oklahoma, if a crash is minor and your vehicle is blocking traffic, you must move it or have it moved.","p":"Right. After a minor crash, move your car out of traffic."},"es":{"q":"En Oklahoma, usted tiene un choque leve y nadie está herido. Su carro bloquea el tráfico. ¿Qué debe hacer?","o":["Dejarlo ahí para que la policía vea cómo pasó","Moverlo fuera del tráfico, o hacer que lo muevan","Irse del lugar y llamar después","Apagar las luces y esperar adentro"],"h1":"Un camino bloqueado puede causar más choques.","h2":"En Oklahoma, si el choque es leve y su vehículo bloquea el tráfico, debe moverlo o hacer que lo muevan.","p":"Correcto. Después de un choque leve, saque su carro del tráfico."},"ref":{"doc":"OK","page":63}},{"id":"ok-091","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the highest fine for driving without a valid license?","o":["$50","$100","$500","$5,000"],"h1":"You could also go to jail for up to 6 months.","h2":"In Oklahoma, driving without a valid license can bring a fine of up to $500, up to 6 months in jail, or both.","p":"Right. The fine can be up to $500."},"es":{"q":"En Oklahoma, ¿cuál es la multa más alta por manejar sin una licencia válida?","o":["$50","$100","$500","$5,000"],"h1":"También podría ir a la cárcel hasta 6 meses.","h2":"En Oklahoma, manejar sin una licencia válida puede causar una multa de hasta $500, hasta 6 meses de cárcel, o ambas cosas.","p":"Correcto. La multa puede ser de hasta $500."},"ref":{"doc":"OK","page":14}},{"id":"ok-092","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a rider under 16 has a motorcycle-only license. During which hours may the rider ride?","o":["Any time of day or night","5:00 a.m. to 10:00 p.m.","6:00 a.m. to 6:00 p.m.","4:30 a.m. to 9:00 p.m."],"h1":"The evening limit is earlier than for a teen driving a car.","h2":"In Oklahoma, a rider under 16 with a motorcycle-only license may ride only between 4:30 a.m. and 9:00 p.m.","p":"Right. Young motorcycle-only riders may ride from 4:30 a.m. to 9:00 p.m."},"es":{"q":"En Oklahoma, una persona menor de 16 años tiene una licencia solo para motocicleta. ¿En qué horario puede manejar la moto?","o":["A cualquier hora del día o de la noche","De 5:00 a.m. a 10:00 p.m.","De 6:00 a.m. a 6:00 p.m.","De 4:30 a.m. a 9:00 p.m."],"h1":"El límite de la noche es más temprano que para un adolescente que maneja carro.","h2":"En Oklahoma, una persona menor de 16 años con licencia solo para motocicleta puede manejar solo entre las 4:30 a.m. y las 9:00 p.m.","p":"Correcto. Los motociclistas jóvenes con licencia solo para motocicleta pueden manejar de 4:30 a.m. a 9:00 p.m."},"ref":{"doc":"OK","page":7}},{"id":"ok-093","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a teen with a motorcycle learner permit is practicing. Who must be supervising?","o":["Any adult with a car license","A friend 18 or older who owns a motorcycle","No one, if the rider wears a helmet","A parent, guardian, or person 21 or older with a motorcycle endorsement who can see the rider"],"h1":"The supervisor must be licensed to ride a motorcycle and keep the rider in sight.","h2":"In Oklahoma, a motorcycle learner must be taught by a parent, legal guardian, or person 21 or older with an Oklahoma license and motorcycle endorsement who has visual contact with the rider.","p":"Right. The supervisor needs a motorcycle endorsement and must keep the rider in sight."},"es":{"q":"En Oklahoma, un adolescente con permiso de aprendiz de motocicleta está practicando. ¿Quién debe supervisarlo?","o":["Cualquier adulto con licencia de carro","Un amigo de 18 años o más que tenga motocicleta","Nadie, si usa casco","Un padre, tutor, o persona de 21 años o más con endoso de motocicleta que pueda ver al motociclista"],"h1":"El supervisor debe tener permiso para manejar motocicleta y no perder de vista al motociclista.","h2":"En Oklahoma, a un aprendiz de motocicleta lo debe instruir un padre, tutor legal, o persona de 21 años o más con licencia de Oklahoma y endoso de motocicleta, que tenga contacto visual con el motociclista.","p":"Correcto. El supervisor necesita endoso de motocicleta y debe mantener a la vista al motociclista."},"ref":{"doc":"OK","page":7}},{"id":"ok-094","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, a teen with a learner permit or intermediate license is convicted of a moving violation. What happens?","o":["Nothing changes","The teen stays at the current level until 6 months after the conviction","The teen must start over with a new permit","The teen must wait 3 years for a full license"],"h1":"The move to the next level is delayed for a while.","h2":"In Oklahoma, a teen convicted of a moving violation stays at the current GDL level, learner or intermediate, until 6 months after the conviction.","p":"Right. The teen stays at the same level for 6 months after the conviction."},"es":{"q":"En Oklahoma, un adolescente con permiso de aprendiz o licencia intermedia es condenado por una infracción de tránsito en movimiento. ¿Qué pasa?","o":["No cambia nada","Se queda en su nivel actual hasta 6 meses después de la condena","Debe empezar de nuevo con otro permiso","Debe esperar 3 años para la licencia completa"],"h1":"El paso al siguiente nivel se retrasa por un tiempo.","h2":"En Oklahoma, un adolescente condenado por una infracción en movimiento se queda en su nivel actual, de aprendiz o intermedio, hasta 6 meses después de la condena.","p":"Correcto. El adolescente se queda en el mismo nivel por 6 meses después de la condena."},"ref":{"doc":"OK","page":8}},{"id":"ok-095","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how much training does Parent-Taught Driver Education require?","o":["10 hours of class and 10 hours of driving","50 hours of class and 50 hours of driving","No set number of hours","30 hours of class and 55 hours of driving"],"h1":"There are more hours behind the wheel than in class.","h2":"In Oklahoma, Parent-Taught Driver Education requires 30 hours of classroom training and 55 hours of behind-the-wheel training.","p":"Right. Parent-taught driver education means 30 hours of class and 55 hours of driving."},"es":{"q":"En Oklahoma, ¿cuánta capacitación exige la educación vial enseñada por los padres (Parent-Taught Driver Education)?","o":["10 horas de clase y 10 horas de manejo","50 horas de clase y 50 horas de manejo","No hay un número fijo de horas","30 horas de clase y 55 horas de manejo"],"h1":"Hay más horas al volante que en clase.","h2":"En Oklahoma, la educación vial enseñada por los padres exige 30 horas de clase y 55 horas de práctica al volante.","p":"Correcto. Son 30 horas de clase y 55 horas de manejo."},"ref":{"doc":"OK","page":8}},{"id":"ok-096","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, your license expired more than 3 years ago. Which tests must you take to renew it?","o":["The vision, written and driving tests","No tests","Only the vision test","Only the written test"],"h1":"After so long, you are tested like a new driver.","h2":"In Oklahoma, if your license expired more than 3 years ago, you must take the vision, written and driving tests again.","p":"Right. After more than 3 years, you must take all three tests."},"es":{"q":"En Oklahoma, su licencia venció hace más de 3 años. ¿Qué exámenes debe tomar para renovarla?","o":["Los exámenes de la vista, escrito y de manejo","Ningún examen","Solo el examen de la vista","Solo el examen escrito"],"h1":"Después de tanto tiempo, lo evalúan como a un conductor nuevo.","h2":"En Oklahoma, si su licencia venció hace más de 3 años, debe tomar otra vez los exámenes de la vista, escrito y de manejo.","p":"Correcto. Después de más de 3 años, debe tomar los tres exámenes."},"ref":{"doc":"OK","page":10}},{"id":"ok-097","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, who must wear a seat belt under the state seat belt law?","o":["Only the driver","The driver and every front-seat passenger","Only passengers under 18","Only people on the highway"],"h1":"The law covers everyone in the front of the car.","h2":"In Oklahoma, the driver and every front-seat passenger must wear a properly fastened seat belt.","p":"Right. The driver and all front-seat passengers must buckle up."},"es":{"q":"En Oklahoma, según la ley estatal del cinturón de seguridad, ¿quién debe usar el cinturón?","o":["Solo el conductor","El conductor y todos los pasajeros del asiento delantero","Solo los pasajeros menores de 18 años","Solo las personas en la carretera"],"h1":"La ley cubre a todos los que van adelante en el carro.","h2":"En Oklahoma, el conductor y todos los pasajeros del asiento delantero deben usar el cinturón de seguridad bien abrochado.","p":"Correcto. El conductor y todos los pasajeros del asiento delantero deben abrocharse el cinturón."},"ref":{"doc":"OK","page":17}},{"id":"ok-098","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, your car has a passenger-side air bag. Where should children under 12 ride?","o":["In the front seat","In the back seat","On an adult's lap","Anywhere, as long as they wear a belt"],"h1":"An air bag opens with great force.","h2":"In Oklahoma, if your car has a passenger-side air bag, children under 12 should ride in the back seat.","p":"Right. Children under 12 belong in the back seat."},"es":{"q":"En Oklahoma, su carro tiene bolsa de aire del lado del pasajero. ¿Dónde deben ir los niños menores de 12 años?","o":["En el asiento delantero","En el asiento trasero","En las piernas de un adulto","En cualquier lugar, si llevan cinturón"],"h1":"Una bolsa de aire se abre con mucha fuerza.","h2":"En Oklahoma, si su carro tiene bolsa de aire del lado del pasajero, los niños menores de 12 años deben ir en el asiento trasero.","p":"Correcto. Los niños menores de 12 años van en el asiento trasero."},"ref":{"doc":"OK","page":17}},{"id":"ok-099","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, your license is revoked because you refused a breath or blood test. How long can the revocation last?","o":["30 days only","10 years","For life","From 180 days to 2 years"],"h1":"It depends on your past driving record.","h2":"In Oklahoma, a revocation under the Implied Consent Law lasts from 180 days to 2 years, depending on your driving record.","p":"Right. The revocation lasts from 180 days to 2 years."},"es":{"q":"En Oklahoma, le revocan la licencia porque se negó a una prueba de aliento o de sangre. ¿Cuánto puede durar la revocación?","o":["Solo 30 días","10 años","De por vida","De 180 días a 2 años"],"h1":"Depende de su historial de manejo anterior.","h2":"En Oklahoma, una revocación bajo la ley de consentimiento implícito dura de 180 días a 2 años, según su historial de manejo.","p":"Correcto. La revocación dura de 180 días a 2 años."},"ref":{"doc":"OK","page":65}},{"id":"ok-100","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a driver under 21 has a second offense under the Zero Tolerance law. How long is the license revoked?","o":["12 months","3 months","6 months","5 years"],"h1":"It is twice as long as for a first offense.","h2":"In Oklahoma, a second Zero Tolerance offense by a driver under 21 brings a license revocation of 12 months.","p":"Right. A second offense means a 12-month revocation."},"es":{"q":"En Oklahoma, un conductor menor de 21 años comete una segunda infracción bajo la ley de Tolerancia Cero. ¿Por cuánto tiempo le revocan la licencia?","o":["12 meses","3 meses","6 meses","5 años"],"h1":"Es el doble que para la primera infracción.","h2":"En Oklahoma, una segunda infracción de Tolerancia Cero de un conductor menor de 21 años causa la revocación de la licencia por 12 meses.","p":"Correcto. Una segunda infracción significa una revocación de 12 meses."},"ref":{"doc":"OK","page":67}},{"id":"ok-101","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you are 18 and have a learner permit. How soon after the permit is issued can you take the driving test?","o":["30 days","6 months","1 year","7 days"],"h1":"Adults wait a much shorter time than teens do.","h2":"In Oklahoma, a learner permit holder who is 18 or older can take the driving test 30 days after the permit is issued.","p":"Right. At 18 or older, you can take the driving test 30 days after you get the permit."},"es":{"q":"En Oklahoma, usted tiene 18 años y un permiso de aprendiz. ¿Cuánto tiempo después de recibir el permiso puede tomar el examen de manejo?","o":["30 días","6 meses","1 año","7 días"],"h1":"Los adultos esperan mucho menos tiempo que los adolescentes.","h2":"En Oklahoma, una persona de 18 años o más con permiso de aprendiz puede tomar el examen de manejo 30 días después de recibir el permiso.","p":"Correcto. Con 18 años o más, puede tomar el examen de manejo 30 días después de recibir el permiso."},"ref":{"doc":"OK","page":6}},{"id":"ok-102","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, you have used all three tries at the driving test after you became eligible. How often can you take it after that?","o":["Once a week","Once every 6 months","Once every 30 days","Never again"],"h1":"You must wait about a month between tries.","h2":"In Oklahoma, after three tries at the driving test, you can take it only once every 30 days.","p":"Right. After three tries, you can retake the driving test once every 30 days."},"es":{"q":"En Oklahoma, usted ya usó sus tres intentos del examen de manejo después de ser elegible. ¿Cada cuánto puede tomarlo después?","o":["Una vez por semana","Una vez cada 6 meses","Una vez cada 30 días","Nunca más"],"h1":"Debe esperar más o menos un mes entre intentos.","h2":"En Oklahoma, después de tres intentos del examen de manejo, solo puede tomarlo una vez cada 30 días.","p":"Correcto. Después de tres intentos, puede repetir el examen de manejo una vez cada 30 días."},"ref":{"doc":"OK","page":6}},{"id":"ok-103","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a teen did not take driver education. What is the youngest age to get an intermediate license?","o":["15","16","17","16 and a half"],"h1":"Driver education lets a teen get it six months sooner.","h2":"In Oklahoma, a teen without driver education can get an intermediate license at 16 and a half; with driver education, at 16.","p":"Right. Without driver education, the intermediate license comes at 16 and a half."},"es":{"q":"En Oklahoma, un adolescente no tomó un curso de educación vial. ¿Cuál es la edad mínima para obtener una licencia intermedia?","o":["15","16","17","16 y medio"],"h1":"La educación vial permite obtenerla seis meses antes.","h2":"En Oklahoma, un adolescente sin educación vial puede obtener la licencia intermedia a los 16 años y medio; con educación vial, a los 16.","p":"Correcto. Sin educación vial, la licencia intermedia se obtiene a los 16 años y medio."},"ref":{"doc":"OK","page":6}},{"id":"ok-104","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, a teen with an intermediate license never took driver education. How long until the intermediate restriction can be removed?","o":["6 months","1 year","2 years","At age 21"],"h1":"With driver education, the wait would be half as long.","h2":"In Oklahoma, the intermediate restriction can be removed after 1 year without driver education, or after 6 months with driver education.","p":"Right. Without driver education, the wait is 1 year."},"es":{"q":"En Oklahoma, un adolescente con licencia intermedia nunca tomó educación vial. ¿Cuánto tiempo debe pasar para quitar la restricción intermedia?","o":["6 meses","1 año","2 años","Hasta los 21 años"],"h1":"Con educación vial, la espera sería la mitad.","h2":"En Oklahoma, la restricción intermedia se puede quitar después de 1 año sin educación vial, o después de 6 meses con educación vial.","p":"Correcto. Sin educación vial, la espera es de 1 año."},"ref":{"doc":"OK","page":6}},{"id":"ok-105","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, which course certificate must a teen show to get an intermediate license?","o":["A first aid course","A motorcycle rider course","The Work Zone Safe course","A defensive driving course"],"h1":"The course is about driving safely where road crews are working.","h2":"In Oklahoma, a teen must show a Work Zone Safe completion certificate to get an intermediate license.","p":"Right. Teens must finish the Work Zone Safe course first."},"es":{"q":"En Oklahoma, ¿qué certificado de curso debe mostrar un adolescente para obtener una licencia intermedia?","o":["Un curso de primeros auxilios","Un curso para motociclistas","El curso Work Zone Safe (seguridad en zonas de trabajo)","Un curso de manejo defensivo"],"h1":"El curso trata de manejar con seguridad donde hay trabajadores en la carretera.","h2":"En Oklahoma, un adolescente debe mostrar el certificado del curso Work Zone Safe (seguridad en zonas de trabajo) para obtener la licencia intermedia.","p":"Correcto. Los adolescentes deben completar primero el curso Work Zone Safe."},"ref":{"doc":"OK","page":6}},{"id":"ok-106","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a rider under 16 has a motorcycle-only license and rides a scooter smaller than 150 cc. What is the top speed allowed?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"It is the same as the usual limit inside a state park.","h2":"In Oklahoma, a rider under 16 on a motorcycle or scooter smaller than 150 cc may not go faster than 35 mph.","p":"Right. Under 16 on a bike under 150 cc, the top speed is 35 mph."},"es":{"q":"En Oklahoma, una persona menor de 16 años tiene una licencia solo para motocicleta y maneja una motoneta de menos de 150 cc. ¿Cuál es la velocidad máxima permitida?","o":["35 mph","25 mph","45 mph","55 mph"],"h1":"Es igual al límite usual dentro de un parque estatal.","h2":"En Oklahoma, una persona menor de 16 años en una motocicleta o motoneta de menos de 150 cc no puede ir a más de 35 mph.","p":"Correcto. Menor de 16 años en una moto de menos de 150 cc, la velocidad máxima es 35 mph."},"ref":{"doc":"OK","page":14}},{"id":"ok-107","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a rider under 16 has a motorcycle-only license. May the rider carry a passenger?","o":["Yes, one passenger","Yes, if the passenger is over 18","Yes, in daylight only","No, never"],"h1":"This license comes with strict limits for young riders.","h2":"In Oklahoma, a rider under 16 with a motorcycle-only license cannot carry a passenger.","p":"Right. Young riders with this license may not carry passengers."},"es":{"q":"En Oklahoma, una persona menor de 16 años tiene una licencia solo para motocicleta. ¿Puede llevar un pasajero?","o":["Sí, un pasajero","Sí, si el pasajero es mayor de 18 años","Sí, solo de día","No, nunca"],"h1":"Esta licencia tiene límites estrictos para los motociclistas jóvenes.","h2":"En Oklahoma, una persona menor de 16 años con licencia solo para motocicleta no puede llevar pasajeros.","p":"Correcto. Los motociclistas jóvenes con esta licencia no pueden llevar pasajeros."},"ref":{"doc":"OK","page":7}},{"id":"ok-108","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, a 15-year-old has a motorcycle-only license and a 250 cc motorcycle. Which road may the rider not use?","o":["A city street","An interstate or turnpike","A county road","A street in a neighborhood"],"h1":"Think of roads that have a posted minimum speed.","h2":"In Oklahoma, a rider under 16 on a motorcycle over 150 cc, up to 300 cc, may ride at the posted speed limit but not on a highway with a posted minimum speed, such as an interstate or turnpike.","p":"Right. Young riders may not use highways with a minimum speed, like interstates and turnpikes."},"es":{"q":"En Oklahoma, una persona de 15 años tiene una licencia solo para motocicleta y una moto de 250 cc. ¿Qué camino no puede usar?","o":["Una calle de la ciudad","Una carretera interestatal o una autopista de peaje (turnpike)","Un camino del condado","Una calle de un vecindario"],"h1":"Piense en las carreteras que tienen una velocidad mínima indicada.","h2":"En Oklahoma, una persona menor de 16 años en una moto de más de 150 cc y hasta 300 cc puede ir al límite de velocidad indicado, pero no puede usar una carretera con velocidad mínima indicada, como una interestatal o una autopista de peaje.","p":"Correcto. Los motociclistas jóvenes no pueden usar carreteras con velocidad mínima, como las interestatales y las autopistas de peaje."},"ref":{"doc":"OK","page":7}},{"id":"ok-109","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, how soon can the learner restriction on a motorcycle learner permit be removed?","o":["The next day","After 1 year","30 days after the permit is issued","At age 18"],"h1":"It is about one month.","h2":"In Oklahoma, the learner restriction on a motorcycle permit can be removed 30 days after the permit is issued.","p":"Right. The motorcycle learner restriction can come off after 30 days."},"es":{"q":"En Oklahoma, ¿cuándo se puede quitar la restricción de aprendiz de un permiso de aprendiz de motocicleta?","o":["Al día siguiente","Después de 1 año","30 días después de recibir el permiso","A los 18 años"],"h1":"Es más o menos un mes.","h2":"En Oklahoma, la restricción de aprendiz de un permiso de motocicleta se puede quitar 30 días después de recibir el permiso.","p":"Correcto. La restricción de aprendiz de motocicleta se puede quitar después de 30 días."},"ref":{"doc":"OK","page":7}},{"id":"ok-110","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a rider under 18 wants a motorcycle license. What course must the rider complete?","o":["A state-approved motorcycle basic rider course","A commercial driver course","A defensive driving course","No course is required"],"h1":"The course teaches the basics of riding a motorcycle.","h2":"In Oklahoma, riders under 18 must complete a certified, state-approved motorcycle basic rider course.","p":"Right. Riders under 18 must finish a state-approved basic rider course."},"es":{"q":"En Oklahoma, una persona menor de 18 años quiere una licencia de motocicleta. ¿Qué curso debe completar?","o":["Un curso básico de motocicleta aprobado por el estado","Un curso para conductores comerciales","Un curso de manejo defensivo","No se requiere ningún curso"],"h1":"El curso enseña lo básico para manejar una motocicleta.","h2":"En Oklahoma, los menores de 18 años deben completar un curso básico de motocicleta certificado y aprobado por el estado.","p":"Correcto. Los menores de 18 años deben completar un curso básico de motocicleta aprobado por el estado."},"ref":{"doc":"OK","page":7}},{"id":"ok-111","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, you move here with a valid Class D license from another state. Which test must you always take?","o":["The written test","The driving test","The vision test","All three tests"],"h1":"The other two tests may be waived.","h2":"In Oklahoma, when you transfer a valid license from another state, you must take the vision test; the written and driving tests may be waived.","p":"Right. A license transfer always needs the vision test."},"es":{"q":"En Oklahoma, usted se muda aquí con una licencia Clase D válida de otro estado. ¿Qué examen siempre debe tomar?","o":["El examen escrito","El examen de manejo","El examen de la vista","Los tres exámenes"],"h1":"Los otros dos exámenes se pueden omitir.","h2":"En Oklahoma, cuando transfiere una licencia válida de otro estado, debe tomar el examen de la vista; el examen escrito y el de manejo se pueden omitir.","p":"Correcto. Al transferir una licencia, siempre se toma el examen de la vista."},"ref":{"doc":"OK","page":10}},{"id":"ok-112","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, you are in a collision. Who must you show your driver license to?","o":["No one but your insurance company","Only a judge","Only your passengers","Anyone involved in the collision"],"h1":"The other people in the crash have a right to see it.","h2":"In Oklahoma, you must show your driver license to anyone involved in a collision with you, and to an officer or judge who asks for it.","p":"Right. Show your license to anyone involved in the collision."},"es":{"q":"En Oklahoma, usted tiene un choque. ¿A quién debe mostrarle su licencia de manejo?","o":["Solo a su compañía de seguros","Solo a un juez","Solo a sus pasajeros","A cualquier persona involucrada en el choque"],"h1":"Las otras personas del choque tienen derecho a verla.","h2":"En Oklahoma, debe mostrar su licencia de manejo a cualquier persona involucrada en un choque con usted, y a un policía o juez que se la pida.","p":"Correcto. Muestre su licencia a cualquier persona involucrada en el choque."},"ref":{"doc":"OK","page":11}},{"id":"ok-113","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, how much does a Class D driver license cost for a person 65 or older?","o":["Nothing, it is free","$4","$25","$42.50"],"h1":"Older drivers get a special break on this fee.","h2":"In Oklahoma, a Class D driver license costs nothing for a person 65 or older.","p":"Right. The Class D license is free at 65 and older."},"es":{"q":"En Oklahoma, ¿cuánto cuesta una licencia de manejo Clase D para una persona de 65 años o más?","o":["Nada, es gratis","$4","$25","$42.50"],"h1":"Los conductores mayores reciben un beneficio especial en este pago.","h2":"En Oklahoma, una licencia de manejo Clase D no cuesta nada para una persona de 65 años o más.","p":"Correcto. La licencia Clase D es gratis a partir de los 65 años."},"ref":{"doc":"OK","page":11}},{"id":"ok-114","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, on what day does your driver license expire?","o":["On your birthday","On the last day of the month","On the first day of the month","On December 31"],"h1":"It is tied to the month you paid for the license, not your birthday.","h2":"In Oklahoma, a driver license expires on the last day of the month.","p":"Right. An Oklahoma license expires on the last day of the month."},"es":{"q":"En Oklahoma, ¿qué día vence su licencia de manejo?","o":["El día de su cumpleaños","El último día del mes","El primer día del mes","El 31 de diciembre"],"h1":"Depende del mes en que pagó la licencia, no de su cumpleaños.","h2":"En Oklahoma, una licencia de manejo vence el último día del mes.","p":"Correcto. Una licencia de Oklahoma vence el último día del mes."},"ref":{"doc":"OK","page":13}},{"id":"ok-115","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, you let a friend who has no license drive your car. What can happen?","o":["Only your friend can get a ticket","Nothing, if you are in the car","You and your friend can both be arrested","You only get a warning"],"h1":"The law blames the driver and the person who allowed it.","h2":"In Oklahoma, it is illegal to let someone without a valid license drive your vehicle, and both of you can be arrested.","p":"Right. Both the unlicensed driver and the person who let them drive can be arrested."},"es":{"q":"En Oklahoma, usted deja que un amigo sin licencia maneje su carro. ¿Qué puede pasar?","o":["Solo su amigo puede recibir una multa","Nada, si usted va en el carro","Usted y su amigo pueden ser arrestados","Usted solo recibe una advertencia"],"h1":"La ley culpa al conductor y a la persona que lo permitió.","h2":"En Oklahoma, es ilegal dejar que alguien sin licencia válida maneje su vehículo, y los dos pueden ser arrestados.","p":"Correcto. El conductor sin licencia y la persona que lo dejó manejar pueden ser arrestados."},"ref":{"doc":"OK","page":13}},{"id":"ok-116","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, what kind of crime is it to make a fake insurance verification form?","o":["No crime, only a warning","A ticket with no fine","A parking violation","A felony"],"h1":"It is a very serious crime.","h2":"In Oklahoma, making a counterfeit or fake insurance verification form can lead to a felony conviction.","p":"Right. Making a fake insurance form can be a felony."},"es":{"q":"En Oklahoma, ¿qué tipo de delito es hacer un formulario falso de verificación de seguro?","o":["No es delito, solo una advertencia","Una multa sin costo","Una infracción de estacionamiento","Un delito grave (felony)"],"h1":"Es un delito muy serio.","h2":"En Oklahoma, hacer un formulario falso de verificación de seguro puede llevar a una condena por delito grave (felony).","p":"Correcto. Hacer un formulario de seguro falso puede ser un delito grave."},"ref":{"doc":"OK","page":16}},{"id":"ok-117","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you are in a collision. Besides the police, who must see your proof of insurance?","o":["The other driver and the other people involved","No one else","Only your passengers","Only the tow truck driver"],"h1":"Think of the people who may need to file a claim.","h2":"In Oklahoma, after a collision you must show your proof of insurance to the other driver and the other people involved.","p":"Right. Show your proof of insurance to the other driver and others involved."},"es":{"q":"En Oklahoma, usted tiene un choque. Además de la policía, ¿quién debe ver su comprobante de seguro?","o":["El otro conductor y las otras personas involucradas","Nadie más","Solo sus pasajeros","Solo el conductor de la grúa"],"h1":"Piense en las personas que tal vez necesiten hacer un reclamo.","h2":"En Oklahoma, después de un choque debe mostrar su comprobante de seguro al otro conductor y a las otras personas involucradas.","p":"Correcto. Muestre su comprobante de seguro al otro conductor y a los demás involucrados."},"ref":{"doc":"OK","page":16}},{"id":"ok-118","scope":"OK","cat":"signals","sign":null,"c":1,"en":{"q":"In Oklahoma, someone removes a road sign, and a person is hurt as a result. What can the penalty be?","o":["A $50 fine","A felony, with up to 2 years in prison and a $1,000 fine","A warning letter","Community service only"],"h1":"When someone gets hurt, it becomes a much more serious crime.","h2":"In Oklahoma, damaging or removing a traffic sign is a crime, and if a person is hurt or killed because of it, it is a felony with up to 2 years in prison and a $1,000 fine.","p":"Right. If someone is hurt, removing a sign is a felony."},"es":{"q":"En Oklahoma, alguien quita una señal de tránsito y, por eso, una persona sale herida. ¿Cuál puede ser el castigo?","o":["Una multa de $50","Un delito grave, con hasta 2 años de prisión y una multa de $1,000","Una carta de advertencia","Solo servicio comunitario"],"h1":"Cuando alguien sale herido, el delito es mucho más serio.","h2":"En Oklahoma, dañar o quitar una señal de tránsito es un delito, y si una persona sale herida o muere por eso, es un delito grave con hasta 2 años de prisión y una multa de $1,000.","p":"Correcto. Si alguien sale herido, quitar una señal es un delito grave."},"ref":{"doc":"OK","page":19}},{"id":"ok-119","scope":"OK","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oklahoma, a church bus ahead of you stops at a railroad crossing on a two-lane road. What should you do?","o":["Pass it on the left","Honk so it moves on","Stop behind it and do not pass","Pass it on the right shoulder"],"h1":"Church buses must stop at crossings, and you may not go around them here.","h2":"In Oklahoma, church buses must stop at railroad crossings, and you may not pass a vehicle that must stop there, except on a multi-lane highway.","p":"Right. Stay behind the bus; do not pass it at the crossing."},"es":{"q":"En Oklahoma, un autobús de iglesia delante de usted se detiene en un cruce de ferrocarril en un camino de dos carriles. ¿Qué debe hacer?","o":["Rebasarlo por la izquierda","Tocar la bocina para que avance","Detenerse detrás de él y no rebasarlo","Rebasarlo por el acotamiento derecho"],"h1":"Los autobuses de iglesia deben detenerse en los cruces, y aquí usted no puede rodearlos.","h2":"En Oklahoma, los autobuses de iglesia deben detenerse en los cruces de ferrocarril, y usted no puede rebasar un vehículo que debe detenerse allí, excepto en una carretera de varios carriles.","p":"Correcto. Quédese detrás del autobús; no lo rebase en el cruce."},"ref":{"doc":"OK","page":22}},{"id":"ok-120","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, how can you tell which cars are part of a funeral procession?","o":["Their headlights are on","They drive with only hazard lights","They have a flag on the roof","They honk at each corner"],"h1":"It is a light signal that tells you not to cut into the line.","h2":"In Oklahoma, all cars in a funeral procession should have their headlights on, as a signal not to drive between them.","p":"Right. Cars in a funeral procession keep their headlights on."},"es":{"q":"En Oklahoma, ¿cómo puede saber qué carros son parte de un cortejo fúnebre?","o":["Llevan los faros encendidos","Solo llevan las luces intermitentes de emergencia","Llevan una bandera en el techo","Tocan la bocina en cada esquina"],"h1":"Es una señal de luz que le dice que no se meta en la fila.","h2":"En Oklahoma, todos los carros de un cortejo fúnebre deben llevar los faros encendidos, como señal para no manejar entre ellos.","p":"Correcto. Los carros de un cortejo fúnebre llevan los faros encendidos."},"ref":{"doc":"OK","page":28}},{"id":"ok-121","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a blind person is crossing the street at a crosswalk. Where should you stop?","o":["In the middle of the crosswalk","Outside the crosswalk","Right next to the person","Past the crosswalk"],"h1":"Leave the crossing area clear for the person.","h2":"In Oklahoma, you must stop outside the crosswalk, not in it, and let the blind person pass.","p":"Right. Stop outside the crosswalk and let the person cross."},"es":{"q":"En Oklahoma, una persona ciega está cruzando la calle en un cruce peatonal. ¿Dónde debe detenerse?","o":["En medio del cruce peatonal","Fuera del cruce peatonal","Justo al lado de la persona","Después del cruce peatonal"],"h1":"Deje libre el área por donde cruza la persona.","h2":"En Oklahoma, debe detenerse fuera del cruce peatonal, no dentro de él, y dejar pasar a la persona ciega.","p":"Correcto. Deténgase fuera del cruce peatonal y deje cruzar a la persona."},"ref":{"doc":"OK","page":28}},{"id":"ok-122","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, you have stopped for a school bus with its red lights flashing. Which of these lets you go again?","o":["The bus driver waves you on","You have waited one minute","The children are on the sidewalk","A car behind you honks"],"h1":"Someone on the bus can tell you it is safe.","h2":"In Oklahoma, you must stay stopped until the bus starts moving, the driver signals you to go, or the red lights go off and the stop sign is pulled back.","p":"Right. You may go when the bus driver signals you on."},"es":{"q":"En Oklahoma, usted se detuvo por un autobús escolar con luces rojas intermitentes. ¿Cuál de estas cosas le permite seguir?","o":["El conductor del autobús le hace señas para seguir","Ya esperó un minuto","Los niños están en la acera","Un carro detrás de usted toca la bocina"],"h1":"Alguien en el autobús puede decirle que es seguro.","h2":"En Oklahoma, debe quedarse detenido hasta que el autobús empiece a moverse, el conductor le haga señas para seguir, o las luces rojas se apaguen y se retire la señal de alto.","p":"Correcto. Puede seguir cuando el conductor del autobús le hace señas."},"ref":{"doc":"OK","page":30}},{"id":"ok-123","scope":"OK","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oklahoma, a school bus is stopped in a loading zone next to a controlled-access highway, where people may not cross. Must you stop?","o":["Yes, always","No","Yes, for 10 seconds","Only on school days"],"h1":"Children cannot cross the highway at this kind of stop.","h2":"In Oklahoma, you do not have to stop for a school bus in a loading zone next to a controlled-access highway where people may not cross.","p":"Right. You need not stop for a bus in that kind of loading zone."},"es":{"q":"En Oklahoma, un autobús escolar está detenido en una zona de carga junto a una carretera de acceso controlado, donde las personas no pueden cruzar. ¿Debe detenerse?","o":["Sí, siempre","No","Sí, por 10 segundos","Solo en días de escuela"],"h1":"En este tipo de parada los niños no pueden cruzar la carretera.","h2":"En Oklahoma, no tiene que detenerse por un autobús escolar en una zona de carga junto a una carretera de acceso controlado donde las personas no pueden cruzar.","p":"Correcto. No tiene que detenerse por un autobús en ese tipo de zona de carga."},"ref":{"doc":"OK","page":30}},{"id":"ok-124","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, on an expressway, how far ahead should you watch for cars braking, entering and exiting?","o":["2 to 3 seconds","About 5 seconds","15 to 20 seconds","A full minute"],"h1":"It is much more than your following distance.","h2":"In Oklahoma, on an expressway you should watch 15 to 20 seconds ahead for cars braking, entering and exiting.","p":"Right. Look 15 to 20 seconds ahead on the expressway."},"es":{"q":"En Oklahoma, en una autopista, ¿qué tan adelante debe mirar para ver carros que frenan, entran y salen?","o":["De 2 a 3 segundos","Unos 5 segundos","De 15 a 20 segundos","Un minuto completo"],"h1":"Es mucho más que su distancia de seguimiento.","h2":"En Oklahoma, en una autopista debe mirar de 15 a 20 segundos hacia adelante para ver carros que frenan, entran y salen.","p":"Correcto. Mire de 15 a 20 segundos hacia adelante en la autopista."},"ref":{"doc":"OK","page":34}},{"id":"ok-125","scope":"OK","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oklahoma, the car ahead is turning left. May you drive onto the shoulder to pass it on the right?","o":["Yes, if you go slowly","Yes, if you signal first","Yes, on any two-lane road","No, never off the pavement"],"h1":"Passing on the right is allowed only on the road itself.","h2":"In Oklahoma, you may pass on the right when the car ahead is turning left, but you may never pass by driving off the pavement or main part of the road.","p":"Right. Never leave the pavement to pass on the right."},"es":{"q":"En Oklahoma, el carro de adelante va a girar a la izquierda. ¿Puede salirse al acotamiento para rebasarlo por la derecha?","o":["Sí, si va despacio","Sí, si primero pone la direccional","Sí, en cualquier camino de dos carriles","No, nunca fuera del pavimento"],"h1":"Rebasar por la derecha solo se permite sobre el camino mismo.","h2":"En Oklahoma, puede rebasar por la derecha cuando el carro de adelante gira a la izquierda, pero nunca puede rebasar saliéndose del pavimento o de la parte principal del camino.","p":"Correcto. Nunca se salga del pavimento para rebasar por la derecha."},"ref":{"doc":"OK","page":35}},{"id":"ok-126","scope":"OK","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oklahoma, you and an oncoming driver both want to turn left at the same intersection. How should you turn?","o":["Each driver turns to the left of the other","Each driver drives around behind the other","The driver who came second goes first","Both wait for the light to turn red"],"h1":"The two cars pass each other driver side to driver side.","h2":"In Oklahoma, when you and an oncoming driver both turn left, each of you turns to the left of the other.","p":"Right. Each driver turns to the left of the other."},"es":{"q":"En Oklahoma, usted y un conductor que viene de frente quieren girar a la izquierda en la misma intersección. ¿Cómo deben girar?","o":["Cada conductor gira a la izquierda del otro","Cada conductor da la vuelta por detrás del otro","El que llegó segundo va primero","Los dos esperan a que la luz cambie a rojo"],"h1":"Los dos carros se cruzan lado del conductor con lado del conductor.","h2":"En Oklahoma, cuando usted y un conductor que viene de frente giran a la izquierda, cada uno gira a la izquierda del otro.","p":"Correcto. Cada conductor gira a la izquierda del otro."},"ref":{"doc":"OK","page":37}},{"id":"ok-127","scope":"OK","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oklahoma, your car has standard brakes, not antilock brakes. How should you brake on ice or snow?","o":["Press hard and hold the pedal down","Pull the parking brake","Tap the brakes lightly, about one second apart","Shift into neutral and coast"],"h1":"Gentle, repeated pressure helps keep the wheels from locking.","h2":"In Oklahoma, with standard brakes on ice, snow or other loose surfaces, tap the brakes lightly about one second apart; never tap antilock brakes.","p":"Right. With standard brakes, tap lightly about once a second."},"es":{"q":"En Oklahoma, su carro tiene frenos normales, no frenos antibloqueo (ABS). ¿Cómo debe frenar en hielo o nieve?","o":["Pisar fuerte y mantener el pedal abajo","Jalar el freno de mano","Tocar el freno suavemente, más o menos una vez por segundo","Poner neutral y dejar que el carro ruede"],"h1":"Una presión suave y repetida ayuda a que las ruedas no se bloqueen.","h2":"En Oklahoma, con frenos normales sobre hielo, nieve u otras superficies sueltas, toque el freno suavemente más o menos una vez por segundo; nunca haga esto con frenos antibloqueo.","p":"Correcto. Con frenos normales, toque el freno suavemente una vez por segundo."},"ref":{"doc":"OK","page":43}},{"id":"ok-128","scope":"OK","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oklahoma, to avoid rear-end crashes, how far down the line of traffic should you watch for brake lights?","o":["Only the car right in front of you","Only the cars behind you","Only at traffic lights","Four or five cars ahead"],"h1":"Looking farther ahead gives you more time to react.","h2":"In Oklahoma, you should watch for brake lights on the four or five cars ahead of you, so you have more time to stop.","p":"Right. Watch brake lights four or five cars ahead."},"es":{"q":"En Oklahoma, para evitar choques por detrás, ¿qué tan adelante en la fila de tráfico debe mirar las luces de freno?","o":["Solo el carro justo delante de usted","Solo los carros detrás de usted","Solo en los semáforos","Cuatro o cinco carros adelante"],"h1":"Mirar más lejos le da más tiempo para reaccionar.","h2":"En Oklahoma, debe mirar las luces de freno de los cuatro o cinco carros delante de usted, para tener más tiempo para detenerse.","p":"Correcto. Mire las luces de freno cuatro o cinco carros adelante."},"ref":{"doc":"OK","page":45}},{"id":"ok-129","scope":"OK","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oklahoma, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Away from the curb","Straight ahead","It does not matter"],"h1":"If the car rolls forward, the curb should stop it.","h2":"In Oklahoma, when you park facing downhill next to a curb, turn your front wheels toward the curb.","p":"Right. Facing downhill, turn your wheels toward the curb."},"es":{"q":"En Oklahoma, usted se estaciona cuesta abajo junto a la orilla de la acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la orilla de la acera","Lejos de la orilla de la acera","Derechas","No importa"],"h1":"Si el carro rueda hacia adelante, la orilla debe detenerlo.","h2":"En Oklahoma, cuando se estaciona cuesta abajo junto a la orilla de la acera, gire las ruedas delanteras hacia la orilla.","p":"Correcto. Cuesta abajo, gire las ruedas hacia la orilla de la acera."},"ref":{"doc":"OK","page":48}},{"id":"ok-130","scope":"OK","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oklahoma, a fire station is across the street, and signs are posted. How close to the station entrance may you park on the opposite side of the street?","o":["No closer than 20 feet","No closer than 75 feet","No closer than 15 feet","No closer than 200 feet"],"h1":"Across the street, the distance is much longer than on the same side.","h2":"In Oklahoma, when signs are posted, you may not park within 75 feet of a fire station entrance on the opposite side of the street.","p":"Right. Across from a fire station, stay at least 75 feet away."},"es":{"q":"En Oklahoma, hay una estación de bomberos al otro lado de la calle y hay señales. ¿Qué tan cerca de la entrada de la estación puede estacionarse en el lado opuesto de la calle?","o":["A no menos de 20 pies","A no menos de 75 pies","A no menos de 15 pies","A no menos de 200 pies"],"h1":"Al otro lado de la calle, la distancia es mucho mayor que en el mismo lado.","h2":"En Oklahoma, cuando hay señales, no puede estacionarse a menos de 75 pies de la entrada de una estación de bomberos en el lado opuesto de la calle.","p":"Correcto. Frente a una estación de bomberos, quédese por lo menos a 75 pies."},"ref":{"doc":"OK","page":49}},{"id":"ok-131","scope":"OK","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oklahoma, may you park on a bridge or in a highway underpass?","o":["Yes, if your hazard lights are on","Yes, for up to 10 minutes","No, it is illegal","Only at night"],"h1":"A parked car there blocks traffic and is hard to avoid.","h2":"In Oklahoma, it is illegal to park on a bridge or other raised structure on a highway, or in a highway underpass.","p":"Right. Never park on a bridge or in an underpass."},"es":{"q":"En Oklahoma, ¿puede estacionarse en un puente o debajo de un paso a desnivel de la carretera?","o":["Sí, si tiene las luces de emergencia encendidas","Sí, por hasta 10 minutos","No, es ilegal","Solo de noche"],"h1":"Un carro estacionado allí bloquea el tráfico y es difícil de esquivar.","h2":"En Oklahoma, es ilegal estacionarse en un puente u otra estructura elevada de la carretera, o debajo de un paso a desnivel.","p":"Correcto. Nunca se estacione en un puente ni debajo de un paso a desnivel."},"ref":{"doc":"OK","page":49}},{"id":"ok-132","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, you apply for a disabled parking placard. Who must complete the application?","o":["A police officer","A family member","A driver license examiner","A physician"],"h1":"Someone must confirm the disability.","h2":"In Oklahoma, the application for a disabled parking placard must be completed by a physician, who states that the person has a physical disability.","p":"Right. A physician must complete the placard application."},"es":{"q":"En Oklahoma, usted solicita un permiso de estacionamiento para personas con discapacidad. ¿Quién debe llenar la solicitud?","o":["Un policía","Un familiar","Un examinador de licencias","Un médico"],"h1":"Alguien debe confirmar la discapacidad.","h2":"En Oklahoma, la solicitud del permiso de estacionamiento para personas con discapacidad debe llenarla un médico, quien declara que la persona tiene una discapacidad física.","p":"Correcto. Un médico debe llenar la solicitud del permiso."},"ref":{"doc":"OK","page":49}},{"id":"ok-133","scope":"OK","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oklahoma, what must a bicycle have when it is ridden at night?","o":["A front light and a rear reflector","A horn and a flag","Only a bell","A rearview mirror"],"h1":"Drivers must be able to see the bike from the front and from behind.","h2":"In Oklahoma, bicycles ridden at night must have a front light and a rear reflector.","p":"Right. At night, a bicycle needs a front light and a rear reflector."},"es":{"q":"En Oklahoma, ¿qué debe tener una bicicleta cuando se usa de noche?","o":["Una luz delantera y un reflector trasero","Una bocina y una bandera","Solo un timbre","Un espejo retrovisor"],"h1":"Los conductores deben poder ver la bicicleta de frente y por detrás.","h2":"En Oklahoma, las bicicletas que se usan de noche deben tener una luz delantera y un reflector trasero.","p":"Correcto. De noche, una bicicleta necesita una luz delantera y un reflector trasero."},"ref":{"doc":"OK","page":51}},{"id":"ok-134","scope":"OK","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oklahoma, you are about to pass a bicycle on a narrow road, and the rider does not seem to know you are there. What should you do?","o":["Blast your horn to warn the rider","Tap your horn briefly","Flash your high beams","Pass fast without a sound"],"h1":"Let the rider know, but do not startle them.","h2":"In Oklahoma, if a bicycle rider on a narrow road may not know you are coming, honk your horn briefly before you pass, without startling the rider.","p":"Right. A short tap of the horn warns the rider without scaring them."},"es":{"q":"En Oklahoma, usted va a rebasar a una bicicleta en un camino angosto, y el ciclista parece no saber que usted está allí. ¿Qué debe hacer?","o":["Tocar la bocina fuerte y largo","Tocar la bocina brevemente","Hacer cambio de luces altas","Pasar rápido sin hacer ruido"],"h1":"Avísele al ciclista, pero sin asustarlo.","h2":"En Oklahoma, si un ciclista en un camino angosto tal vez no sabe que usted viene, toque la bocina brevemente antes de rebasar, sin asustarlo.","p":"Correcto. Un toque corto de bocina avisa al ciclista sin asustarlo."},"ref":{"doc":"OK","page":51}},{"id":"ok-135","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, what is the highest fine for a first DUI conviction, with a BAC of 0.08 or more?","o":["$100","$500","$1,000","$10,000"],"h1":"It is a four-digit number, but not the largest choice.","h2":"In Oklahoma, a first DUI conviction is a misdemeanor with 10 days to 1 year in jail and a fine of up to $1,000.","p":"Right. A first DUI can bring a fine of up to $1,000."},"es":{"q":"En Oklahoma, ¿cuál es la multa más alta por una primera condena de DUI, con un nivel de alcohol de 0.08 o más?","o":["$100","$500","$1,000","$10,000"],"h1":"Es un número de cuatro cifras, pero no la opción más grande.","h2":"En Oklahoma, una primera condena de DUI es un delito menor con 10 días a 1 año de cárcel y una multa de hasta $1,000.","p":"Correcto. Un primer DUI puede costar una multa de hasta $1,000."},"ref":{"doc":"OK","page":65}},{"id":"ok-136","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a driver is convicted of DUI for the first time. The license was not already revoked for the same arrest. How long is the license suspended?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about half a year.","h2":"In Oklahoma, after a first DUI conviction, the license is suspended for 180 days, unless it was already revoked for a refused or failed test in the same incident.","p":"Right. A first DUI conviction means a 180-day suspension."},"es":{"q":"En Oklahoma, un conductor es condenado por DUI por primera vez. La licencia no fue revocada antes por el mismo arresto. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","60 días","90 días","180 días"],"h1":"Es más o menos medio año.","h2":"En Oklahoma, después de una primera condena de DUI, la licencia se suspende por 180 días, a menos que ya haya sido revocada por negarse a la prueba o no pasarla en el mismo incidente.","p":"Correcto. Una primera condena de DUI significa una suspensión de 180 días."},"ref":{"doc":"OK","page":66}},{"id":"ok-137","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, a driver is convicted of impaired driving, with a BAC over 0.05 but under 0.08. What fine can the driver get?","o":["$100 to $500","$1,000 to $2,500","$5,000","No fine, only a warning"],"h1":"It is less than the fine for DUI at 0.08 or more.","h2":"In Oklahoma, a conviction for impaired driving, with a BAC over 0.05 but under 0.08, brings a fine of $100 to $500, up to 6 months in jail, or both.","p":"Right. Impaired driving can bring a fine of $100 to $500."},"es":{"q":"En Oklahoma, un conductor es condenado por manejar con facultades disminuidas, con un nivel de alcohol mayor de 0.05 pero menor de 0.08. ¿Qué multa puede recibir?","o":["De $100 a $500","De $1,000 a $2,500","$5,000","Ninguna multa, solo una advertencia"],"h1":"Es menos que la multa por DUI con 0.08 o más.","h2":"En Oklahoma, una condena por manejar con facultades disminuidas, con un nivel de alcohol mayor de 0.05 pero menor de 0.08, trae una multa de $100 a $500, hasta 6 meses de cárcel, o ambas.","p":"Correcto. Manejar con facultades disminuidas puede costar una multa de $100 a $500."},"ref":{"doc":"OK","page":65}},{"id":"ok-138","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, a driver gets a first impaired-driving conviction, with a BAC over 0.05 but under 0.08. How long is the license suspended?","o":["7 days","30 days","6 months","1 year"],"h1":"It is the shortest suspension in this list of penalties.","h2":"In Oklahoma, a first impaired-driving conviction brings a 30-day suspension; a second brings 6 months, and a third brings 1 year.","p":"Right. The first impaired-driving suspension is 30 days."},"es":{"q":"En Oklahoma, un conductor recibe su primera condena por manejar con facultades disminuidas, con un nivel de alcohol mayor de 0.05 pero menor de 0.08. ¿Por cuánto tiempo se suspende la licencia?","o":["7 días","30 días","6 meses","1 año"],"h1":"Es la suspensión más corta de estas sanciones.","h2":"En Oklahoma, una primera condena por manejar con facultades disminuidas trae una suspensión de 30 días; la segunda, de 6 meses, y la tercera, de 1 año.","p":"Correcto. La primera suspensión por facultades disminuidas es de 30 días."},"ref":{"doc":"OK","page":65}},{"id":"ok-139","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a person uses a fake ID. What is the longest prison time the person could face?","o":["30 days","1 year","7 years","No prison, only a fine"],"h1":"Using a fake ID is a felony.","h2":"In Oklahoma, using, carrying, borrowing or buying a fake ID is a felony, with up to 7 years in prison and a $10,000 fine.","p":"Right. A fake ID can mean up to 7 years in prison."},"es":{"q":"En Oklahoma, una persona usa una identificación falsa. ¿Cuál es el tiempo máximo de prisión que podría recibir?","o":["30 días","1 año","7 años","Nada de prisión, solo una multa"],"h1":"Usar una identificación falsa es un delito grave.","h2":"En Oklahoma, usar, llevar, pedir prestada o comprar una identificación falsa es un delito grave, con hasta 7 años de prisión y una multa de $10,000.","p":"Correcto. Una identificación falsa puede significar hasta 7 años de prisión."},"ref":{"doc":"OK","page":69}},{"id":"ok-140","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, how many points are added to your driving record for reckless driving?","o":["1","2","3","4"],"h1":"It is the same as for passing a stopped school bus.","h2":"In Oklahoma, a reckless driving conviction adds 4 points to your driving record.","p":"Right. Reckless driving adds 4 points."},"es":{"q":"En Oklahoma, ¿cuántos puntos se agregan a su historial de manejo por manejar de forma temeraria?","o":["1","2","3","4"],"h1":"Es lo mismo que por no detenerse ante un autobús escolar.","h2":"En Oklahoma, una condena por manejar de forma temeraria agrega 4 puntos a su historial de manejo.","p":"Correcto. Manejar de forma temeraria agrega 4 puntos."},"ref":{"doc":"OK","page":71}},{"id":"ok-141","scope":"OK","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oklahoma, you are convicted of driving more than 25 mph over the posted speed limit. How many points are added to your record?","o":["3","1","2","4"],"h1":"It is one more point than a regular speeding ticket.","h2":"In Oklahoma, speeding more than 25 mph over the posted limit adds 3 points, while regular speeding adds 2.","p":"Right. More than 25 mph over the limit adds 3 points."},"es":{"q":"En Oklahoma, lo condenan por manejar a más de 25 mph sobre el límite indicado. ¿Cuántos puntos se agregan a su historial?","o":["3","1","2","4"],"h1":"Es un punto más que una multa normal por exceso de velocidad.","h2":"En Oklahoma, ir a más de 25 mph sobre el límite indicado agrega 3 puntos, mientras que el exceso de velocidad normal agrega 2.","p":"Correcto. Más de 25 mph sobre el límite agrega 3 puntos."},"ref":{"doc":"OK","page":71}},{"id":"ok-142","scope":"OK","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oklahoma, you finish a defensive driving course approved by Service Oklahoma. How many points come off your record?","o":["1","2","4","All of them"],"h1":"It is the same number that comes off for a year with no convictions.","h2":"In Oklahoma, finishing an approved defensive driving or driver compliance course takes 2 points off your record, once every 24 months.","p":"Right. An approved course takes off 2 points."},"es":{"q":"En Oklahoma, usted termina un curso de manejo defensivo aprobado por Service Oklahoma. ¿Cuántos puntos se quitan de su historial?","o":["1","2","4","Todos"],"h1":"Es el mismo número que se quita por un año sin condenas.","h2":"En Oklahoma, terminar un curso aprobado de manejo defensivo o de cumplimiento quita 2 puntos de su historial, una vez cada 24 meses.","p":"Correcto. Un curso aprobado quita 2 puntos."},"ref":{"doc":"OK","page":72}},{"id":"ok-143","scope":"OK","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oklahoma, a driver is convicted of leaving the scene of a crash where someone was hurt, without stopping to help. What happens to the license?","o":["A warning letter","2 points are added","It is revoked for 6 months to 3 years","Nothing, if no one died"],"h1":"This is one of the offenses with a mandatory revocation.","h2":"In Oklahoma, failing to stop and help after a crash with injury or death means the license is revoked for 6 months to 3 years.","p":"Right. A hit-and-run conviction brings a revocation of 6 months to 3 years."},"es":{"q":"En Oklahoma, un conductor es condenado por irse del lugar de un choque donde alguien salió herido, sin detenerse a ayudar. ¿Qué pasa con su licencia?","o":["Una carta de advertencia","Se agregan 2 puntos","Se revoca por 6 meses a 3 años","Nada, si nadie murió"],"h1":"Es uno de los delitos con revocación obligatoria.","h2":"En Oklahoma, no detenerse y ayudar después de un choque con heridos o muertos significa que la licencia se revoca por 6 meses a 3 años.","p":"Correcto. Una condena por huir de un choque trae una revocación de 6 meses a 3 años."},"ref":{"doc":"OK","page":71}},{"id":"ok-144","scope":"OK","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oklahoma, a 15-year-old loses driving privileges under the Zero Tolerance law. The penalty would end before the teen turns 16. What happens?","o":["It ends as planned","It is cut in half","It becomes a warning","It is extended until the teen turns 16"],"h1":"The teen cannot drive before a certain birthday.","h2":"In Oklahoma, if a teen is under 16 or would still be under 16 when the Zero Tolerance cancellation ends, it is extended until the teen turns 16.","p":"Right. The cancellation lasts at least until the teen turns 16."},"es":{"q":"En Oklahoma, un adolescente de 15 años pierde el privilegio de manejar bajo la ley de Tolerancia Cero. La sanción terminaría antes de que cumpla 16 años. ¿Qué pasa?","o":["Termina como estaba previsto","Se reduce a la mitad","Se convierte en una advertencia","Se extiende hasta que cumpla 16 años"],"h1":"El adolescente no puede manejar antes de cierto cumpleaños.","h2":"En Oklahoma, si un adolescente es menor de 16 años, o lo seguiría siendo al terminar la cancelación por Tolerancia Cero, la cancelación se extiende hasta que cumpla 16 años.","p":"Correcto. La cancelación dura por lo menos hasta que el adolescente cumpla 16 años."},"ref":{"doc":"OK","page":67}},{"id":"or-001","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the provisional license.","h2":"In Oregon you can get an instruction permit at 15.","p":"Right. The Oregon instruction permit starts at 15."},"es":{"q":"En Oregon, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia provisional.","h2":"En Oregon usted puede obtener el permiso de instrucción a los 15 años.","p":"Correcto. El permiso de instrucción en Oregon empieza a los 15."},"zh":{"q":"在 Oregon，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比过渡驾照早一年。","h2":"在 Oregon，你 15 岁就可以拿到学习驾照。","p":"对。Oregon 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Oregon, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi lấy bằng lái tạm thời (provisional license).","h2":"Ở Oregon, bạn có thể lấy giấy phép tập lái khi 15 tuổi.","p":"Đúng. Giấy phép tập lái ở Oregon bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Oregon, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang provisional license.","h2":"Sa Oregon, puwede kang kumuha ng instruction permit sa edad na 15.","p":"Tama. Nagsisimula ang instruction permit sa Oregon sa edad na 15."},"ar":{"q":"في Oregon، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل الرخصة المؤقتة (provisional license).","h2":"في Oregon يمكنك الحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. في Oregon يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"OR","page":89}},{"id":"or-002","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how old must the licensed person beside a permit driver be?","o":["At least 16","At least 18","At least 21","At least 30"],"h1":"It is the age when an adult may legally buy alcohol.","h2":"An Oregon permit driver must have a licensed person who is at least 21 years old in the seat beside them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Oregon, ¿qué edad debe tener la persona con licencia que va al lado de un conductor con permiso?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 30"],"h1":"Es la edad en que un adulto ya puede comprar alcohol legalmente.","h2":"Un conductor con permiso en Oregon debe llevar al lado a una persona con licencia de por lo menos 21 años.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Oregon，坐在学习驾照司机旁边的有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 30 岁"],"h1":"它是成年人可以合法买酒的年龄。","h2":"Oregon 的学习驾照司机旁边的座位必须坐一位至少 21 岁、有驾照的人。","p":"对。你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Oregon, người có bằng lái ngồi bên cạnh người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 30 tuổi"],"h1":"Đó là tuổi người lớn được phép mua rượu theo luật.","h2":"Ở Oregon, người tập lái phải có một người có bằng lái, ít nhất 21 tuổi, ngồi ở ghế bên cạnh.","p":"Đúng. Người ngồi bên cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Oregon, ilang taon dapat ang taong may lisensya na nakaupo sa tabi ng nagmamaneho na may permit?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 30"],"h1":"Ito ang edad kung kailan legal nang bumili ng alak ang isang adulto.","h2":"Sa Oregon, ang nagmamaneho na may permit ay dapat may kasamang taong may lisensya na hindi bababa sa 21 taong gulang sa upuan sa tabi niya.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Oregon، كم يجب أن يكون عمر الشخص الحاصل على رخصة والجالس بجانب سائق التصريح؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","30 سنة على الأقل"],"h1":"هو العمر الذي يُسمح فيه للبالغ قانونًا بشراء الكحول.","h2":"في Oregon يجب أن يجلس بجانب سائق التصريح شخص حاصل على رخصة وعمره 21 سنة على الأقل.","p":"صحيح. يجب أن يكون الشخص بجانبك في عمر 21 سنة أو أكثر."},"ref":{"doc":"OR","page":90}},{"id":"or-003","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, how long must the adult beside a permit driver have held a valid license?","o":["At least 3 years","At least 1 month","At least 10 years","At least 20 years"],"h1":"It is a few years, fewer than five.","h2":"In Oregon, the adult beside a permit driver must have held a valid license for at least 3 years.","p":"Right. Three years of license experience is required."},"es":{"q":"En Oregon, ¿cuánto tiempo debe haber tenido una licencia válida el adulto que va al lado de un conductor con permiso?","o":["Por lo menos 3 años","Por lo menos 1 mes","Por lo menos 10 años","Por lo menos 20 años"],"h1":"Son pocos años, menos de cinco.","h2":"En Oregon, el adulto que va al lado de un conductor con permiso debe haber tenido una licencia válida por lo menos 3 años.","p":"Correcto. Se requieren tres años con licencia."},"zh":{"q":"在 Oregon，坐在学习驾照司机旁边的成年人必须有有效驾照多久？","o":["至少 3 年","至少 1 个月","至少 10 年","至少 20 年"],"h1":"它是几年，少于五年。","h2":"在 Oregon，坐在学习驾照司机旁边的成年人必须有有效驾照至少 3 年。","p":"对。需要有三年驾照经验。"},"vi":{"q":"Ở Oregon, người lớn ngồi bên cạnh người tập lái phải có bằng lái hợp lệ trong bao lâu?","o":["Ít nhất 3 năm","Ít nhất 1 tháng","Ít nhất 10 năm","Ít nhất 20 năm"],"h1":"Đó là vài năm, ít hơn năm năm.","h2":"Ở Oregon, người lớn ngồi bên cạnh người tập lái phải có bằng lái hợp lệ ít nhất 3 năm.","p":"Đúng. Cần có ba năm kinh nghiệm có bằng lái."},"tl":{"q":"Sa Oregon, gaano katagal na dapat may valid na lisensya ang adultong nakaupo sa tabi ng nagmamaneho na may permit?","o":["Hindi bababa sa 3 taon","Hindi bababa sa 1 buwan","Hindi bababa sa 10 taon","Hindi bababa sa 20 taon"],"h1":"Ilang taon ito, kulang sa lima.","h2":"Sa Oregon, ang adultong katabi ng nagmamaneho na may permit ay dapat may valid na lisensya nang hindi bababa sa 3 taon.","p":"Tama. Kailangan ang tatlong taong karanasan na may lisensya."},"ar":{"q":"في Oregon، منذ كم من الوقت يجب أن يحمل البالغ الجالس بجانب سائق التصريح رخصة سارية؟","o":["3 سنوات على الأقل","شهر واحد على الأقل","10 سنوات على الأقل","20 سنة على الأقل"],"h1":"هي بضع سنوات، أقل من خمس.","h2":"في Oregon يجب أن يكون البالغ الجالس بجانب سائق التصريح قد حمل رخصة سارية لمدة 3 سنوات على الأقل.","p":"صحيح. يلزم ثلاث سنوات من الخبرة مع الرخصة."},"ref":{"doc":"OR","page":90}},{"id":"or-004","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, how many supervised driving hours does a teen need if they took an approved driver education course?","o":["20 hours","30 hours","100 hours","50 hours"],"h1":"It is half of what a teen without the course needs.","h2":"An Oregon teen who completes an approved driver education course needs 50 hours of supervised driving.","p":"Right. With driver education, Oregon asks for 50 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente que tomó un curso aprobado de educación vial?","o":["20 horas","30 horas","100 horas","50 horas"],"h1":"Es la mitad de lo que necesita un adolescente sin el curso.","h2":"Un adolescente en Oregon que termina un curso aprobado de educación vial necesita 50 horas de manejo supervisado.","p":"Correcto. Con educación vial, Oregon pide 50 horas."},"zh":{"q":"在 Oregon，上过认可的驾驶教育课程的青少年，需要多少小时有人监督的驾驶？","o":["20 小时","30 小时","100 小时","50 小时"],"h1":"它是没上课程的青少年需要的一半。","h2":"Oregon 上完认可的驾驶教育课程的青少年，需要 50 小时有人监督的驾驶。","p":"对。上了驾驶教育，Oregon 要求 50 小时。"},"vi":{"q":"Ở Oregon, thiếu niên cần bao nhiêu giờ lái xe có người giám sát nếu đã học một khóa giáo dục lái xe được chấp thuận?","o":["20 giờ","30 giờ","100 giờ","50 giờ"],"h1":"Đó là một nửa số giờ của thiếu niên không học khóa này.","h2":"Ở Oregon, thiếu niên hoàn thành khóa giáo dục lái xe được chấp thuận cần 50 giờ lái xe có người giám sát.","p":"Đúng. Có học giáo dục lái xe, Oregon yêu cầu 50 giờ."},"tl":{"q":"Sa Oregon, ilang oras ng pagmamaneho na may gumagabay ang kailangan ng isang teen kung kumuha siya ng aprubadong kurso sa driver education?","o":["20 oras","30 oras","100 oras","50 oras"],"h1":"Kalahati ito ng kailangan ng teen na walang kurso.","h2":"Sa Oregon, ang teen na tapos sa aprubadong kurso sa driver education ay kailangan ng 50 oras ng pagmamaneho na may gumagabay.","p":"Tama. Kapag may driver education, 50 oras ang hinihingi ng Oregon."},"ar":{"q":"في Oregon، كم ساعة من القيادة تحت الإشراف يحتاج المراهق إذا أخذ دورة تعليم قيادة معتمدة؟","o":["20 ساعة","30 ساعة","100 ساعة","50 ساعة"],"h1":"هي نصف ما يحتاجه المراهق الذي لم يأخذ الدورة.","h2":"في Oregon يحتاج المراهق الذي أكمل دورة تعليم قيادة معتمدة إلى 50 ساعة من القيادة تحت الإشراف.","p":"صحيح. مع تعليم القيادة تطلب Oregon خمسين ساعة."},"ref":{"doc":"OR","page":90}},{"id":"or-005","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, how many supervised driving hours does a teen need without a driver education course?","o":["50 hours","70 hours","100 hours","150 hours"],"h1":"It is twice the number needed with the course.","h2":"An Oregon teen who does not take an approved driver education course needs 100 hours of supervised driving.","p":"Right. Without driver education, Oregon asks for 100 hours."},"es":{"q":"En Oregon, ¿cuántas horas de manejo supervisado necesita un adolescente sin curso de educación vial?","o":["50 horas","70 horas","100 horas","150 horas"],"h1":"Es el doble de lo que se necesita con el curso.","h2":"Un adolescente en Oregon que no toma un curso aprobado de educación vial necesita 100 horas de manejo supervisado.","p":"Correcto. Sin educación vial, Oregon pide 100 horas."},"zh":{"q":"在 Oregon，没上驾驶教育课程的青少年，需要多少小时有人监督的驾驶？","o":["50 小时","70 小时","100 小时","150 小时"],"h1":"它是上了课程需要的两倍。","h2":"Oregon 没上认可的驾驶教育课程的青少年，需要 100 小时有人监督的驾驶。","p":"对。没上驾驶教育，Oregon 要求 100 小时。"},"vi":{"q":"Ở Oregon, thiếu niên cần bao nhiêu giờ lái xe có người giám sát nếu không học khóa giáo dục lái xe?","o":["50 giờ","70 giờ","100 giờ","150 giờ"],"h1":"Đó là gấp đôi số giờ khi có học khóa này.","h2":"Ở Oregon, thiếu niên không học khóa giáo dục lái xe được chấp thuận cần 100 giờ lái xe có người giám sát.","p":"Đúng. Không học giáo dục lái xe, Oregon yêu cầu 100 giờ."},"tl":{"q":"Sa Oregon, ilang oras ng pagmamaneho na may gumagabay ang kailangan ng isang teen kung walang kurso sa driver education?","o":["50 oras","70 oras","100 oras","150 oras"],"h1":"Doble ito ng kailangan kapag may kurso.","h2":"Sa Oregon, ang teen na hindi kumuha ng aprubadong kurso sa driver education ay kailangan ng 100 oras ng pagmamaneho na may gumagabay.","p":"Tama. Kapag walang driver education, 100 oras ang hinihingi ng Oregon."},"ar":{"q":"في Oregon، كم ساعة من القيادة تحت الإشراف يحتاج المراهق بدون دورة تعليم قيادة؟","o":["50 ساعة","70 ساعة","100 ساعة","150 ساعة"],"h1":"هي ضعف العدد المطلوب مع الدورة.","h2":"في Oregon يحتاج المراهق الذي لم يأخذ دورة تعليم قيادة معتمدة إلى 100 ساعة من القيادة تحت الإشراف.","p":"صحيح. بدون تعليم القيادة تطلب Oregon مئة ساعة."},"ref":{"doc":"OR","page":90}},{"id":"or-006","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, how long must a teen hold an instruction permit before getting a provisional license?","o":["1 month","6 months","2 years","No minimum time"],"h1":"It is half a year.","h2":"An Oregon teen must hold the instruction permit for at least 6 months before getting a provisional license.","p":"Right. Six months with the permit first."},"es":{"q":"En Oregon, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de obtener la licencia provisional?","o":["1 mes","6 meses","2 años","No hay tiempo mínimo"],"h1":"Es medio año.","h2":"Un adolescente en Oregon debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia provisional.","p":"Correcto. Primero, seis meses con el permiso."},"zh":{"q":"在 Oregon，青少年拿过渡驾照（provisional license）前，必须持有学习驾照多久？","o":["1 个月","6 个月","2 年","没有最短时间"],"h1":"它是半年。","h2":"Oregon 的青少年必须持有学习驾照至少 6 个月，才能拿过渡驾照。","p":"对。先持有学习驾照六个月。"},"vi":{"q":"Ở Oregon, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời?","o":["1 tháng","6 tháng","2 năm","Không có thời gian tối thiểu"],"h1":"Đó là nửa năm.","h2":"Ở Oregon, thiếu niên phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái tạm thời.","p":"Đúng. Trước tiên phải có giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Oregon, gaano katagal dapat hawak ng isang teen ang instruction permit bago makakuha ng provisional license?","o":["1 buwan","6 na buwan","2 taon","Walang pinakamaikling panahon"],"h1":"Kalahating taon ito.","h2":"Sa Oregon, dapat hawak ng teen ang instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng provisional license.","p":"Tama. Anim na buwan muna na may permit."},"ar":{"q":"في Oregon، كم من الوقت يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المؤقتة؟","o":["شهر واحد","6 أشهر","سنتان","لا توجد مدة دنيا"],"h1":"هي نصف سنة.","h2":"في Oregon يجب أن يحمل المراهق تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المؤقتة.","p":"صحيح. ستة أشهر مع التصريح أولًا."},"ref":{"doc":"OR","page":90}},{"id":"or-007","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, during the first 6 months of a provisional license, who may ride as a passenger under age 20?","o":["Only immediate family members","Up to three friends","Any one friend","Anyone with a seat belt"],"h1":"Think of the people you live with.","h2":"During the first 6 months of an Oregon provisional license, passengers under 20 must be immediate family members.","p":"Right. Only family under 20 at first."},"es":{"q":"En Oregon, durante los primeros 6 meses de la licencia provisional, ¿quién puede viajar como pasajero menor de 20 años?","o":["Solo familiares directos","Hasta tres amigos","Un amigo cualquiera","Cualquiera con cinturón"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los primeros 6 meses de la licencia provisional de Oregon, los pasajeros menores de 20 años deben ser familiares directos.","p":"Correcto. Al principio, solo familiares menores de 20."},"zh":{"q":"在 Oregon，持过渡驾照的前 6 个月，谁可以作为未满 20 岁的乘客坐车？","o":["只有直系亲属","最多三个朋友","任何一个朋友","任何系了安全带的人"],"h1":"想想和你住在一起的人。","h2":"Oregon 持过渡驾照的前 6 个月，未满 20 岁的乘客必须是直系亲属。","p":"对。一开始只能载未满 20 岁的家人。"},"vi":{"q":"Ở Oregon, trong 6 tháng đầu có bằng lái tạm thời, ai dưới 20 tuổi được đi cùng xe làm hành khách?","o":["Chỉ người thân trong gia đình","Tối đa ba người bạn","Một người bạn bất kỳ","Bất kỳ ai có thắt dây an toàn"],"h1":"Hãy nghĩ đến những người sống cùng nhà với bạn.","h2":"Trong 6 tháng đầu có bằng lái tạm thời ở Oregon, hành khách dưới 20 tuổi phải là người thân trong gia đình.","p":"Đúng. Lúc đầu, chỉ người thân dưới 20 tuổi."},"tl":{"q":"Sa Oregon, sa unang 6 na buwan ng provisional license, sino ang puwedeng isakay na pasaherong wala pang 20 taong gulang?","o":["Mga kapamilya lamang","Hanggang tatlong kaibigan","Kahit sinong isang kaibigan","Kahit sino na naka-seat belt"],"h1":"Isipin ang mga taong kasama mo sa bahay.","h2":"Sa unang 6 na buwan ng provisional license sa Oregon, ang mga pasaherong wala pang 20 ay dapat kapamilya.","p":"Tama. Sa simula, kapamilya lamang ang puwede kung wala pang 20."},"ar":{"q":"في Oregon، خلال أول 6 أشهر من الرخصة المؤقتة، من يمكنه الركوب كراكب إذا كان عمره أقل من 20 سنة؟","o":["أفراد العائلة المباشرة فقط","حتى ثلاثة أصدقاء","صديق واحد أيًّا كان","أي شخص يضع حزام الأمان"],"h1":"فكّر في الأشخاص الذين تعيش معهم.","h2":"خلال أول 6 أشهر من الرخصة المؤقتة في Oregon، يجب أن يكون الركاب الذين أعمارهم أقل من 20 سنة من أفراد العائلة المباشرة.","p":"صحيح. في البداية العائلة فقط لمن هم أقل من 20 سنة."},"ref":{"doc":"OR","page":null}},{"id":"or-008","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, during the second 6 months of a provisional license, how many passengers under 20 who are not family may ride along?","o":["None","One","No more than three","No limit"],"h1":"The limit loosens, but there is still a limit.","h2":"During the second 6 months of an Oregon provisional license, the driver may carry no more than three passengers under 20 who are not family.","p":"Right. Up to three in the second six months."},"es":{"q":"En Oregon, durante los segundos 6 meses de la licencia provisional, ¿cuántos pasajeros menores de 20 años que no son familiares pueden viajar?","o":["Ninguno","Uno","No más de tres","Sin límite"],"h1":"El límite se afloja, pero todavía hay un límite.","h2":"Durante los segundos 6 meses de la licencia provisional de Oregon, el conductor puede llevar como máximo tres pasajeros menores de 20 años que no son familiares.","p":"Correcto. Hasta tres en los segundos seis meses."},"zh":{"q":"在 Oregon，持过渡驾照的第二个 6 个月，可以载几位不是家人、未满 20 岁的乘客？","o":["一位也不行","一位","不超过三位","没有限制"],"h1":"限制放宽了，但还是有限制。","h2":"Oregon 持过渡驾照的第二个 6 个月，司机最多可以载三位不是家人、未满 20 岁的乘客。","p":"对。第二个六个月最多三位。"},"vi":{"q":"Ở Oregon, trong 6 tháng thứ hai có bằng lái tạm thời, được chở bao nhiêu hành khách dưới 20 tuổi không phải người thân?","o":["Không ai","Một người","Không quá ba người","Không giới hạn"],"h1":"Giới hạn được nới ra, nhưng vẫn còn giới hạn.","h2":"Trong 6 tháng thứ hai có bằng lái tạm thời ở Oregon, người lái được chở không quá ba hành khách dưới 20 tuổi không phải người thân.","p":"Đúng. Tối đa ba người trong sáu tháng thứ hai."},"tl":{"q":"Sa Oregon, sa ikalawang 6 na buwan ng provisional license, ilang pasaherong wala pang 20 na hindi kapamilya ang puwedeng isakay?","o":["Wala","Isa","Hindi hihigit sa tatlo","Walang limitasyon"],"h1":"Lumuluwag ang limitasyon, pero may limitasyon pa rin.","h2":"Sa ikalawang 6 na buwan ng provisional license sa Oregon, puwedeng magsakay ang driver ng hindi hihigit sa tatlong pasaherong wala pang 20 na hindi kapamilya.","p":"Tama. Hanggang tatlo sa ikalawang anim na buwan."},"ar":{"q":"في Oregon، خلال الأشهر الستة الثانية من الرخصة المؤقتة، كم راكبًا أقل من 20 سنة من غير العائلة يمكن أن يركب معك؟","o":["لا أحد","واحد","ثلاثة على الأكثر","بلا حد"],"h1":"يصبح الحد أخفّ، لكن ما زال هناك حد.","h2":"خلال الأشهر الستة الثانية من الرخصة المؤقتة في Oregon، يمكن للسائق أن يحمل ثلاثة ركاب على الأكثر أعمارهم أقل من 20 سنة وليسوا من العائلة.","p":"صحيح. حتى ثلاثة في الأشهر الستة الثانية."},"ref":{"doc":"OR","page":null}},{"id":"or-009","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, during which hours may a provisional driver in the first year not drive, unless an exception applies?","o":["9 p.m. to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m.","Midnight to 5 a.m."],"h1":"It starts at the very start of a new day.","h2":"In the first year, an Oregon provisional driver may not drive from midnight to 5 a.m. unless an exception applies.","p":"Right. Midnight to 5 a.m. is off limits."},"es":{"q":"En Oregon, ¿en qué horario no puede manejar un conductor provisional en su primer año, salvo una excepción?","o":["De 9 p.m. a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m.","De medianoche a 5 a.m."],"h1":"Empieza justo al comienzo de un nuevo día.","h2":"En el primer año, un conductor provisional en Oregon no puede manejar de medianoche a 5 a.m., salvo una excepción.","p":"Correcto. De medianoche a 5 a.m. no se maneja."},"zh":{"q":"在 Oregon，除非有例外情况，持过渡驾照第一年的司机在哪个时间段不能开车？","o":["晚上 9 点到早上 6 点","晚上 10 点到早上 5 点","晚上 11 点到凌晨 4 点","午夜到早上 5 点"],"h1":"它从新的一天刚开始的时候开始。","h2":"在第一年，Oregon 持过渡驾照的司机从午夜到早上 5 点不能开车，除非有例外情况。","p":"对。午夜到早上 5 点不能开车。"},"vi":{"q":"Ở Oregon, trong năm đầu, người có bằng lái tạm thời không được lái xe vào giờ nào, trừ khi có ngoại lệ?","o":["9 giờ tối đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Nó bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Trong năm đầu, người có bằng lái tạm thời ở Oregon không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi có ngoại lệ.","p":"Đúng. Không được lái từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Oregon, sa unang taon, anong oras hindi puwedeng magmaneho ang may provisional license, maliban kung may exception?","o":["9 p.m. hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ito sa mismong simula ng bagong araw.","h2":"Sa unang taon, ang may provisional license sa Oregon ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung may exception.","p":"Tama. Bawal mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Oregon، في أي ساعات لا يجوز لسائق الرخصة المؤقتة في السنة الأولى أن يقود، إلا إذا انطبق استثناء؟","o":["من 9 مساءً إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"تبدأ في أول لحظة من يوم جديد.","h2":"في السنة الأولى لا يجوز لسائق الرخصة المؤقتة في Oregon أن يقود من منتصف الليل إلى 5 صباحًا، إلا إذا انطبق استثناء.","p":"صحيح. من منتصف الليل إلى 5 صباحًا ممنوع."},"ref":{"doc":"OR","page":null}},{"id":"or-010","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, a provisional driver may drive between midnight and 5 a.m. when riding with a licensed driver of what age?","o":["At least 18","At least 25","At least 21","At least 65"],"h1":"It is older than the usual permit supervisor.","h2":"An Oregon provisional driver may drive between midnight and 5 a.m. when a licensed driver who is at least 25 years old is along.","p":"Right. A licensed driver 25 or older makes it allowed."},"es":{"q":"En Oregon, un conductor provisional puede manejar entre medianoche y 5 a.m. si lo acompaña un conductor con licencia de ¿qué edad?","o":["Por lo menos 18","Por lo menos 25","Por lo menos 21","Por lo menos 65"],"h1":"Es mayor que la edad del supervisor normal del permiso.","h2":"Un conductor provisional en Oregon puede manejar entre medianoche y 5 a.m. si va con un conductor con licencia de por lo menos 25 años.","p":"Correcto. Con un conductor de 25 años o más, está permitido."},"zh":{"q":"在 Oregon，持过渡驾照的司机和几岁的有驾照司机在一起时，可以在午夜到早上 5 点之间开车？","o":["至少 18 岁","至少 25 岁","至少 21 岁","至少 65 岁"],"h1":"它比通常监督学习驾照的人年龄大。","h2":"Oregon 持过渡驾照的司机如果有一位至少 25 岁、有驾照的司机在车上，就可以在午夜到早上 5 点之间开车。","p":"对。有一位 25 岁或以上、有驾照的司机就可以。"},"vi":{"q":"Ở Oregon, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi đi cùng một người có bằng lái bao nhiêu tuổi?","o":["Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi","Ít nhất 65 tuổi"],"h1":"Người này lớn tuổi hơn người giám sát tập lái thông thường.","h2":"Ở Oregon, người có bằng lái tạm thời được lái xe từ nửa đêm đến 5 giờ sáng khi có một người có bằng lái ít nhất 25 tuổi đi cùng.","p":"Đúng. Có người có bằng lái từ 25 tuổi trở lên đi cùng thì được phép."},"tl":{"q":"Sa Oregon, puwedeng magmaneho ang may provisional license mula hatinggabi hanggang 5 a.m. kung kasama ang driver na may lisensya na ilang taong gulang?","o":["Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21","Hindi bababa sa 65"],"h1":"Mas matanda ito kaysa sa karaniwang gumagabay sa may permit.","h2":"Sa Oregon, puwedeng magmaneho ang may provisional license mula hatinggabi hanggang 5 a.m. kung kasama ang driver na may lisensya na hindi bababa sa 25 taong gulang.","p":"Tama. Puwede kapag kasama ang driver na may lisensya na 25 o higit pa."},"ar":{"q":"في Oregon، يجوز لسائق الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا إذا كان معه سائق حاصل على رخصة بأي عمر؟","o":["18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل","65 سنة على الأقل"],"h1":"هو أكبر من عمر المشرف المعتاد على سائق التصريح.","h2":"في Oregon يجوز لسائق الرخصة المؤقتة أن يقود بين منتصف الليل و5 صباحًا إذا كان معه سائق حاصل على رخصة وعمره 25 سنة على الأقل.","p":"صحيح. وجود سائق مرخّص عمره 25 سنة أو أكثر يجعل ذلك مسموحًا."},"ref":{"doc":"OR","page":null}},{"id":"or-011","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, may a driver under 18 talk on a cell phone with a hands-free device?","o":["No, not even hands-free","Yes, hands-free is always allowed","Yes, but only on highways","Yes, but only during the day"],"h1":"The rule for teens is stricter than for adults.","h2":"In Oregon, a driver under 18 may not use a cell phone while driving, not even with a hands-free device.","p":"Right. No phone at all for drivers under 18."},"es":{"q":"En Oregon, ¿puede un conductor menor de 18 años hablar por celular con un dispositivo de manos libres?","o":["No, ni siquiera con manos libres","Sí, manos libres siempre está permitido","Sí, pero solo en autopistas","Sí, pero solo de día"],"h1":"La regla para adolescentes es más estricta que para adultos.","h2":"En Oregon, un conductor menor de 18 años no puede usar el celular mientras maneja, ni siquiera con un dispositivo de manos libres.","p":"Correcto. Nada de teléfono para menores de 18."},"zh":{"q":"在 Oregon，未满 18 岁的司机可以用免提设备打手机吗？","o":["不可以，免提也不行","可以，免提一直都可以","可以，但只在高速公路上","可以，但只在白天"],"h1":"青少年的规定比成年人严。","h2":"在 Oregon，未满 18 岁的司机开车时不能用手机，用免提设备也不行。","p":"对。未满 18 岁的司机完全不能用手机。"},"vi":{"q":"Ở Oregon, người lái xe dưới 18 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay (hands-free) không?","o":["Không, kể cả rảnh tay","Có, rảnh tay luôn được phép","Có, nhưng chỉ trên xa lộ","Có, nhưng chỉ vào ban ngày"],"h1":"Quy định cho thiếu niên nghiêm hơn cho người lớn.","h2":"Ở Oregon, người lái xe dưới 18 tuổi không được dùng điện thoại khi lái xe, kể cả với thiết bị rảnh tay.","p":"Đúng. Người lái dưới 18 tuổi hoàn toàn không được dùng điện thoại."},"tl":{"q":"Sa Oregon, puwede bang makipag-usap sa cell phone gamit ang hands-free device ang driver na wala pang 18?","o":["Hindi, kahit hands-free","Oo, laging puwede ang hands-free","Oo, pero sa highway lamang","Oo, pero sa araw lamang"],"h1":"Mas mahigpit ang patakaran sa mga teen kaysa sa mga adulto.","h2":"Sa Oregon, ang driver na wala pang 18 ay hindi puwedeng gumamit ng cell phone habang nagmamaneho, kahit may hands-free device.","p":"Tama. Bawal ang anumang paggamit ng phone sa driver na wala pang 18."},"ar":{"q":"في Oregon، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلم في الهاتف المحمول بجهاز بدون استخدام اليدين (hands-free)؟","o":["لا، ولا حتى بدون استخدام اليدين","نعم، بدون استخدام اليدين مسموح دائمًا","نعم، لكن على الطرق السريعة فقط","نعم، لكن في النهار فقط"],"h1":"القاعدة للمراهقين أشد من القاعدة للبالغين.","h2":"في Oregon لا يجوز للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف المحمول أثناء القيادة، ولا حتى بجهاز بدون استخدام اليدين.","p":"صحيح. لا هاتف أبدًا للسائقين تحت 18 سنة."},"ref":{"doc":"OR","page":80}},{"id":"or-012","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, you approach a stopped emergency vehicle with lights flashing and cannot change lanes safely. What must you do?","o":["Keep your speed","Stop in your lane","Slow to at least 5 mph below the posted speed","Speed up to pass quickly"],"h1":"You must lower your speed by a set amount.","h2":"In Oregon, if you cannot safely move over, you must slow to at least 5 mph below the posted speed.","p":"Right. Slow down at least 5 mph below the limit."},"es":{"q":"En Oregon, usted se acerca a un vehículo de emergencia detenido con luces encendidas y no puede cambiar de carril con seguridad. ¿Qué debe hacer?","o":["Mantener su velocidad","Detenerse en su carril","Bajar a por lo menos 5 mph menos que la velocidad indicada","Acelerar para pasar rápido"],"h1":"Debe bajar su velocidad una cantidad fija.","h2":"En Oregon, si no puede cambiarse de carril con seguridad, debe bajar a por lo menos 5 mph menos que la velocidad indicada.","p":"Correcto. Baje por lo menos 5 mph del límite."},"zh":{"q":"在 Oregon，你接近一辆停着、闪着灯的紧急车辆，但不能安全地换车道。你必须怎么做？","o":["保持你的速度","在你的车道停下","减速到比标示的限速至少低 5 mph","加速快点开过去"],"h1":"你必须把速度降低一个规定的量。","h2":"在 Oregon，如果你不能安全地让道变道，你必须减速到比标示的限速至少低 5 mph。","p":"对。减速到比限速至少低 5 mph。"},"vi":{"q":"Ở Oregon, bạn đến gần một xe cấp cứu đang dừng và nháy đèn, nhưng không thể đổi làn an toàn. Bạn phải làm gì?","o":["Giữ nguyên tốc độ","Dừng lại trong làn của bạn","Giảm tốc độ xuống ít nhất 5 mph dưới tốc độ quy định trên biển","Tăng tốc để vượt qua nhanh"],"h1":"Bạn phải giảm tốc độ một mức nhất định.","h2":"Ở Oregon, nếu bạn không thể tránh sang làn khác an toàn, bạn phải giảm tốc độ xuống ít nhất 5 mph dưới tốc độ quy định trên biển.","p":"Đúng. Giảm tốc độ ít nhất 5 mph dưới giới hạn."},"tl":{"q":"Sa Oregon, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw at hindi ka ligtas na makakalipat ng lane. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis mo","Huminto sa lane mo","Bagalan sa hindi bababa sa 5 mph na mas mababa sa nakapaskil na speed limit","Bilisan para makalampas agad"],"h1":"Dapat mong ibaba ang bilis mo nang tiyak na halaga.","h2":"Sa Oregon, kung hindi ka ligtas na makakalipat ng lane, dapat kang magbagal nang hindi bababa sa 5 mph na mas mababa sa nakapaskil na speed limit.","p":"Tama. Magbagal nang hindi bababa sa 5 mph na mas mababa sa limit."},"ar":{"q":"في Oregon، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض، ولا تستطيع تغيير المسار بأمان. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك","توقف في مسارك","خفّف السرعة إلى 5 mph على الأقل تحت السرعة المكتوبة على اللافتة","أسرع لتتجاوزها بسرعة"],"h1":"يجب أن تخفض سرعتك بمقدار محدد.","h2":"في Oregon إذا لم تستطع الابتعاد إلى مسار آخر بأمان، يجب أن تخفف السرعة إلى 5 mph على الأقل تحت السرعة المكتوبة على اللافتة.","p":"صحيح. خفّف السرعة 5 mph على الأقل تحت الحد."},"ref":{"doc":"OR","page":null}},{"id":"or-013","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, for which stopped vehicles on the shoulder must you move over or slow down?","o":["Only police cars","Only ambulances","Only tow trucks","Any vehicle showing hazard lights, flares or an emergency sign"],"h1":"The law was expanded to cover more than emergency vehicles.","h2":"In Oregon, you must move over or slow down for any vehicle stopped on the shoulder that shows hazard lights, flares or an emergency sign.","p":"Right. The rule covers any stopped vehicle with warning signs."},"es":{"q":"En Oregon, ¿por cuáles vehículos detenidos en el acotamiento debe cambiarse de carril o bajar la velocidad?","o":["Solo patrullas de policía","Solo ambulancias","Solo grúas","Cualquier vehículo con luces de emergencia, bengalas o un letrero de emergencia"],"h1":"La ley se amplió para incluir más que vehículos de emergencia.","h2":"En Oregon, debe cambiarse de carril o bajar la velocidad por cualquier vehículo detenido en el acotamiento que tenga luces de emergencia, bengalas o un letrero de emergencia.","p":"Correcto. La regla incluye cualquier vehículo detenido con señales de aviso."},"zh":{"q":"在 Oregon，路肩上停着哪些车时，你必须让道变道或减速？","o":["只有警车","只有救护车","只有拖车","任何开着危险警示灯、放着照明弹（flare）或紧急标志的车"],"h1":"这条法律扩大了，不只包括紧急车辆。","h2":"在 Oregon，任何停在路肩、开着危险警示灯、放着照明弹（flare）或紧急标志的车，你都必须让道变道或减速。","p":"对。这条规定包括任何有警示标志的停着的车。"},"vi":{"q":"Ở Oregon, bạn phải tránh sang làn khác hoặc giảm tốc độ khi gặp những xe nào đang dừng bên lề đường?","o":["Chỉ xe cảnh sát","Chỉ xe cứu thương","Chỉ xe kéo","Bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc có biển báo khẩn cấp"],"h1":"Luật đã được mở rộng, không chỉ cho xe cấp cứu.","h2":"Ở Oregon, bạn phải tránh sang làn khác hoặc giảm tốc độ khi gặp bất kỳ xe nào dừng bên lề đường có bật đèn báo nguy hiểm, đặt pháo sáng hoặc có biển báo khẩn cấp.","p":"Đúng. Quy định áp dụng cho mọi xe đang dừng có dấu hiệu cảnh báo."},"tl":{"q":"Sa Oregon, para sa aling mga sasakyang nakahinto sa gilid ng daan (shoulder) ka dapat lumipat ng lane o magbagal?","o":["Mga sasakyan ng pulis lamang","Mga ambulansya lamang","Mga tow truck lamang","Anumang sasakyan na may hazard lights, flares o emergency sign"],"h1":"Pinalawak ang batas para sumaklaw sa higit pa sa mga emergency vehicle.","h2":"Sa Oregon, dapat kang lumipat ng lane o magbagal para sa anumang sasakyang nakahinto sa shoulder na may hazard lights, flares o emergency sign.","p":"Tama. Sakop ng patakaran ang anumang nakahintong sasakyan na may babala."},"ar":{"q":"في Oregon، لأي مركبات متوقفة على كتف الطريق (shoulder) يجب أن تبتعد إلى مسار آخر أو تخفف السرعة؟","o":["سيارات الشرطة فقط","سيارات الإسعاف فقط","شاحنات السحب فقط","أي مركبة تُظهر أضواء التحذير أو مشاعل أو لافتة طوارئ"],"h1":"تم توسيع القانون ليشمل أكثر من مركبات الطوارئ.","h2":"في Oregon يجب أن تبتعد إلى مسار آخر أو تخفف السرعة لأي مركبة متوقفة على كتف الطريق تُظهر أضواء التحذير أو مشاعل أو لافتة طوارئ.","p":"صحيح. القاعدة تشمل أي مركبة متوقفة عليها علامات تحذير."},"ref":{"doc":"OR","page":null}},{"id":"or-014","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, what is the speed limit in a business district when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same as in a school zone.","h2":"In Oregon, the speed limit in a business district is 20 mph unless another limit is posted.","p":"Right. Business districts are 20 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona comercial cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es igual que en una zona escolar.","h2":"En Oregon, el límite de velocidad en una zona comercial es 20 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas comerciales son de 20 mph."},"zh":{"q":"在 Oregon，没有标示其他限速时，商业区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它和学校区一样。","h2":"在 Oregon，除非标示了其他限速，商业区的限速是 20 mph。","p":"对。商业区是 20 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong khu thương mại là bao nhiêu khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Giống như trong khu trường học.","h2":"Ở Oregon, tốc độ giới hạn trong khu thương mại là 20 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu thương mại là 20 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa business district kapag walang ibang limit na nakapaskil?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Pareho ito sa school zone.","h2":"Sa Oregon, ang speed limit sa business district ay 20 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. 20 mph sa mga business district."},"ar":{"q":"في Oregon، ما حد السرعة في المنطقة التجارية عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو نفس الحد في منطقة المدرسة.","h2":"في Oregon حد السرعة في المنطقة التجارية هو 20 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق التجارية 20 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-015","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, what is the speed limit in a residential district when no other limit is posted?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is a little faster than a business district.","h2":"In Oregon, the speed limit in a residential district is 25 mph unless another limit is posted.","p":"Right. Residential districts are 25 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una zona residencial cuando no hay otro límite indicado?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es un poco más rápido que en una zona comercial.","h2":"En Oregon, el límite de velocidad en una zona residencial es 25 mph, salvo que haya otro límite indicado.","p":"Correcto. Las zonas residenciales son de 25 mph."},"zh":{"q":"在 Oregon，没有标示其他限速时，住宅区的限速是多少？","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"它比商业区快一点。","h2":"在 Oregon，除非标示了其他限速，住宅区的限速是 25 mph。","p":"对。住宅区是 25 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong khu dân cư là bao nhiêu khi không có biển báo giới hạn khác?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Nhanh hơn khu thương mại một chút.","h2":"Ở Oregon, tốc độ giới hạn trong khu dân cư là 25 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu dân cư là 25 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa residential district kapag walang ibang limit na nakapaskil?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Medyo mas mabilis ito kaysa sa business district.","h2":"Sa Oregon, ang speed limit sa residential district ay 25 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. 25 mph sa mga residential district."},"ar":{"q":"في Oregon، ما حد السرعة في المنطقة السكنية عندما لا توجد لافتة بحد آخر؟","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"هو أسرع قليلًا من المنطقة التجارية.","h2":"في Oregon حد السرعة في المنطقة السكنية هو 25 mph إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق السكنية 25 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-016","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, what is the speed limit in an alley?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"It is the slowest of the usual city limits.","h2":"In Oregon, the speed limit in an alley is 15 mph.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en un callejón?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Es el más lento de los límites comunes de la ciudad.","h2":"En Oregon, el límite de velocidad en un callejón es 15 mph.","p":"Correcto. Los callejones son de 15 mph."},"zh":{"q":"在 Oregon，小巷（alley）的限速是多少？","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"它是一般城市限速里最慢的。","h2":"在 Oregon，小巷的限速是 15 mph。","p":"对。小巷是 15 mph。"},"vi":{"q":"Ở Oregon, tốc độ giới hạn trong hẻm (alley) là bao nhiêu?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Đó là mức chậm nhất trong các giới hạn thường gặp trong thành phố.","h2":"Ở Oregon, tốc độ giới hạn trong hẻm là 15 mph.","p":"Đúng. Trong hẻm là 15 mph."},"tl":{"q":"Sa Oregon, ano ang speed limit sa eskinita (alley)?","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"Ito ang pinakamabagal sa mga karaniwang limit sa lungsod.","h2":"Sa Oregon, ang speed limit sa eskinita ay 15 mph.","p":"Tama. 15 mph sa mga eskinita."},"ar":{"q":"في Oregon، ما حد السرعة في الزقاق (alley)؟","o":["25 mph","20 mph","15 mph","5 mph"],"h1":"هو الأبطأ بين الحدود المعتادة في المدينة.","h2":"في Oregon حد السرعة في الزقاق هو 15 mph.","p":"صحيح. الأزقة 15 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-017","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, how much alcohol may a driver under 21 have in their body?","o":["Up to 0.08 percent","Up to 0.05 percent","Up to 0.02 percent","None at all"],"h1":"Oregon has zero tolerance for young drivers.","h2":"In Oregon, a driver under 21 may not drive with any amount of alcohol in their body.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Oregon, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Hasta 0.08 por ciento","Hasta 0.05 por ciento","Hasta 0.02 por ciento","Nada"],"h1":"Oregon tiene tolerancia cero para los conductores jóvenes.","h2":"En Oregon, un conductor menor de 21 años no puede manejar con ninguna cantidad de alcohol en el cuerpo.","p":"Correcto. Menores de 21, nada de alcohol."},"zh":{"q":"在 Oregon，未满 21 岁的司机体内可以有多少酒精？","o":["最多 0.08%","最多 0.05%","最多 0.02%","一点也不能有"],"h1":"Oregon 对年轻司机零容忍。","h2":"在 Oregon，未满 21 岁的司机体内有任何酒精都不能开车。","p":"对。未满 21 岁，一点酒精也不能有。"},"vi":{"q":"Ở Oregon, người lái xe dưới 21 tuổi được có bao nhiêu rượu trong cơ thể?","o":["Tối đa 0.08 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.02 phần trăm","Hoàn toàn không có"],"h1":"Oregon không khoan nhượng với người lái xe trẻ tuổi.","h2":"Ở Oregon, người lái xe dưới 21 tuổi không được lái xe khi có bất kỳ lượng rượu nào trong cơ thể.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có rượu."},"tl":{"q":"Sa Oregon, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Hanggang 0.08 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.02 porsiyento","Wala talaga"],"h1":"Zero tolerance ang Oregon para sa mga batang driver.","h2":"Sa Oregon, ang driver na wala pang 21 ay hindi puwedeng magmaneho na may kahit kaunting alak sa katawan.","p":"Tama. Kapag wala pang 21, walang alak talaga."},"ar":{"q":"في Oregon، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["حتى 0.08 بالمئة","حتى 0.05 بالمئة","حتى 0.02 بالمئة","لا شيء أبدًا"],"h1":"Oregon لا تتسامح أبدًا مع السائقين الصغار.","h2":"في Oregon لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود وفي جسمه أي كمية من الكحول.","p":"صحيح. تحت 21 سنة، لا كحول أبدًا."},"ref":{"doc":"OR","page":83}},{"id":"or-018","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, the knowledge test for a regular license has 35 questions. How many must you answer correctly to pass?","o":["21","25","28","32"],"h1":"You need about 80 percent right.","h2":"In Oregon you must answer 28 of the 35 questions correctly to pass the knowledge test.","p":"Right. You need 28 correct answers out of 35."},"es":{"q":"En Oregon, el examen de conocimientos para una licencia normal tiene 35 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["21","25","28","32"],"h1":"Necesita cerca del 80 por ciento correcto.","h2":"En Oregon usted debe contestar bien 28 de las 35 preguntas para aprobar el examen de conocimientos.","p":"Correcto. Necesita 28 respuestas correctas de 35."},"zh":{"q":"在 Oregon，普通驾照的笔试有 35 道题。你至少要答对几道才能通过？","o":["21","25","28","32"],"h1":"你大约需要答对 80%。","h2":"在 Oregon，笔试 35 道题中你必须答对 28 道才能通过。","p":"对。35 道题中需要答对 28 道。"},"vi":{"q":"Ở Oregon, bài thi kiến thức để lấy bằng lái thường có 35 câu hỏi. Bạn phải trả lời đúng bao nhiêu câu để đậu?","o":["21","25","28","32"],"h1":"Bạn cần đúng khoảng 80 phần trăm.","h2":"Ở Oregon, bạn phải trả lời đúng 28 trên 35 câu hỏi để đậu bài thi kiến thức.","p":"Đúng. Bạn cần 28 câu đúng trên 35 câu."},"tl":{"q":"Sa Oregon, may 35 tanong ang knowledge test para sa regular na lisensya. Ilan ang dapat mong masagot nang tama para pumasa?","o":["21","25","28","32"],"h1":"Kailangan mong makakuha ng mga 80 porsiyentong tama.","h2":"Sa Oregon, dapat mong masagot nang tama ang 28 sa 35 tanong para pumasa sa knowledge test.","p":"Tama. Kailangan mo ng 28 tamang sagot sa 35."},"ar":{"q":"في Oregon، اختبار المعرفة للرخصة العادية فيه 35 سؤالًا. كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["21","25","28","32"],"h1":"تحتاج إلى نحو 80 بالمئة من الإجابات الصحيحة.","h2":"في Oregon يجب أن تجيب إجابة صحيحة عن 28 سؤالًا من 35 لتنجح في اختبار المعرفة.","p":"صحيح. تحتاج إلى 28 إجابة صحيحة من 35."},"ref":{"doc":"OR","page":2}},{"id":"or-019","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you were in a crash that must be reported to the DMV. How soon must you file the report?","o":["Within 72 hours","Within 10 days","Within 30 days","Only if the police ask"],"h1":"It is counted in hours, not days.","h2":"In Oregon you must file a crash report with the DMV within 72 hours when the crash must be reported.","p":"Right. The DMV report is due within 72 hours."},"es":{"q":"En Oregon, usted tuvo un choque que debe reportarse al DMV. ¿En cuánto tiempo debe presentar el reporte?","o":["Dentro de 72 horas","Dentro de 10 días","Dentro de 30 días","Solo si la policía lo pide"],"h1":"Se cuenta en horas, no en días.","h2":"En Oregon usted debe presentar el reporte de choque al DMV dentro de 72 horas cuando el choque debe reportarse.","p":"Correcto. El reporte al DMV se entrega dentro de 72 horas."},"zh":{"q":"在 Oregon，你发生了一起必须向 DMV 报告的车祸。你必须在多长时间内提交报告？","o":["72 小时内","10 天内","30 天内","只有警察要求时才报"],"h1":"它是按小时算的，不是按天。","h2":"在 Oregon，必须报告的车祸要在 72 小时内向 DMV 提交车祸报告。","p":"对。DMV 报告要在 72 小时内提交。"},"vi":{"q":"Ở Oregon, bạn bị tai nạn mà phải báo cho DMV. Bạn phải nộp báo cáo trong bao lâu?","o":["Trong vòng 72 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày","Chỉ khi cảnh sát yêu cầu"],"h1":"Thời hạn được tính bằng giờ, không phải bằng ngày.","h2":"Ở Oregon, khi tai nạn phải được báo cáo, bạn phải nộp báo cáo tai nạn cho DMV trong vòng 72 giờ.","p":"Đúng. Báo cáo cho DMV phải nộp trong vòng 72 giờ."},"tl":{"q":"Sa Oregon, naaksidente ka at dapat itong i-report sa DMV. Gaano kabilis mo dapat i-file ang report?","o":["Sa loob ng 72 oras","Sa loob ng 10 araw","Sa loob ng 30 araw","Kung hihilingin lang ng pulis"],"h1":"Binibilang ito sa oras, hindi sa araw.","h2":"Sa Oregon, dapat kang mag-file ng crash report sa DMV sa loob ng 72 oras kapag kailangang i-report ang aksidente.","p":"Tama. Dapat maipasa ang report sa DMV sa loob ng 72 oras."},"ar":{"q":"في Oregon، وقع لك حادث يجب الإبلاغ عنه إلى DMV. خلال كم من الوقت يجب أن تقدّم التقرير؟","o":["خلال 72 ساعة","خلال 10 أيام","خلال 30 يومًا","فقط إذا طلبت الشرطة"],"h1":"المدة تُحسب بالساعات، لا بالأيام.","h2":"في Oregon يجب أن تقدّم تقرير الحادث إلى DMV خلال 72 ساعة عندما يجب الإبلاغ عن الحادث.","p":"صحيح. تقرير DMV مطلوب خلال 72 ساعة."},"ref":{"doc":"OR","page":94}},{"id":"or-020","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you must report a crash to the DMV if the damage to the car you were driving is more than what amount?","o":["$500","$1,000","$1,500","$2,500"],"h1":"It is the highest amount listed.","h2":"In Oregon you must report a crash to the DMV when the damage to the car you were driving is over $2,500.","p":"Right. Damage over $2,500 means you must file a report."},"es":{"q":"En Oregon, usted debe reportar un choque al DMV si el daño al carro que manejaba es mayor de ¿qué cantidad?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Es la cantidad más alta de la lista.","h2":"En Oregon usted debe reportar un choque al DMV cuando el daño al carro que manejaba es mayor de $2,500.","p":"Correcto. Un daño de más de $2,500 significa que debe presentar un reporte."},"zh":{"q":"在 Oregon，如果你所驾驶的车损坏超过多少钱，就必须向 DMV 报告车祸？","o":["$500","$1,000","$1,500","$2,500"],"h1":"是选项中最高的金额。","h2":"在 Oregon，如果你所驾驶的车损坏超过 $2,500，你必须向 DMV 报告车祸。","p":"对。损坏超过 $2,500 就必须提交报告。"},"vi":{"q":"Ở Oregon, bạn phải báo tai nạn cho DMV nếu thiệt hại của chiếc xe bạn đang lái vượt quá số tiền nào?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Đó là số tiền cao nhất trong các lựa chọn.","h2":"Ở Oregon, bạn phải báo tai nạn cho DMV khi thiệt hại của chiếc xe bạn đang lái vượt quá $2,500.","p":"Đúng. Thiệt hại trên $2,500 thì bạn phải nộp báo cáo."},"tl":{"q":"Sa Oregon, dapat mong i-report sa DMV ang aksidente kung ang sira sa sasakyang minamaneho mo ay higit sa anong halaga?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Ito ang pinakamataas na halaga sa listahan.","h2":"Sa Oregon, dapat mong i-report sa DMV ang aksidente kapag ang sira sa sasakyang minamaneho mo ay higit sa $2,500.","p":"Tama. Kapag higit sa $2,500 ang sira, dapat kang mag-file ng report."},"ar":{"q":"في Oregon، يجب أن تبلّغ DMV عن الحادث إذا كان ضرر السيارة التي كنت تقودها أكثر من أي مبلغ؟","o":["$500","$1,000","$1,500","$2,500"],"h1":"هو أعلى مبلغ في القائمة.","h2":"في Oregon يجب أن تبلّغ DMV عن الحادث عندما يكون ضرر السيارة التي كنت تقودها أكثر من $2,500.","p":"صحيح. الضرر فوق $2,500 يعني أنه يجب أن تقدّم تقريرًا."},"ref":{"doc":"OR","page":94}},{"id":"or-021","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, does a police report about your crash take the place of your own report to the DMV?","o":["Yes, the police send it for you","No, you must still file your own DMV report","Yes, if no one was hurt","Only if the other driver agrees"],"h1":"The duty to report is yours.","h2":"In Oregon a police report does not replace your own crash report, so you must still file one with the DMV.","p":"Right. You still file your own report with the DMV."},"es":{"q":"En Oregon, ¿un reporte de la policía sobre su choque reemplaza su propio reporte al DMV?","o":["Sí, la policía lo envía por usted","No, usted debe presentar su propio reporte al DMV","Sí, si nadie salió herido","Solo si el otro conductor está de acuerdo"],"h1":"La obligación de reportar es suya.","h2":"En Oregon un reporte de la policía no reemplaza su propio reporte de choque, así que usted debe presentar uno al DMV.","p":"Correcto. Usted presenta su propio reporte al DMV de todos modos."},"zh":{"q":"在 Oregon，警察写的车祸报告可以代替你自己向 DMV 提交的报告吗？","o":["可以，警察会替你寄","不可以，你仍然必须自己向 DMV 提交报告","可以，如果没有人受伤","只有对方司机同意时才可以"],"h1":"报告的责任在你自己。","h2":"在 Oregon，警察的报告不能代替你自己的车祸报告，所以你仍然必须向 DMV 提交一份。","p":"对。你仍然要自己向 DMV 提交报告。"},"vi":{"q":"Ở Oregon, biên bản của cảnh sát về vụ tai nạn có thay thế được báo cáo của chính bạn gửi cho DMV không?","o":["Có, cảnh sát gửi giúp bạn","Không, bạn vẫn phải tự nộp báo cáo cho DMV","Có, nếu không ai bị thương","Chỉ khi tài xế kia đồng ý"],"h1":"Trách nhiệm báo cáo là của bạn.","h2":"Ở Oregon, biên bản của cảnh sát không thay thế báo cáo tai nạn của bạn, nên bạn vẫn phải tự nộp một báo cáo cho DMV.","p":"Đúng. Bạn vẫn phải tự nộp báo cáo cho DMV."},"tl":{"q":"Sa Oregon, napapalitan ba ng police report tungkol sa aksidente mo ang sarili mong report sa DMV?","o":["Oo, ang pulis ang magpapadala nito para sa iyo","Hindi, dapat ka pa ring mag-file ng sarili mong report sa DMV","Oo, kung walang nasaktan","Kung papayag lang ang kabilang driver"],"h1":"Ikaw ang may tungkuling mag-report.","h2":"Sa Oregon, hindi napapalitan ng police report ang sarili mong crash report, kaya dapat ka pa ring mag-file nito sa DMV.","p":"Tama. Magfa-file ka pa rin ng sarili mong report sa DMV."},"ar":{"q":"في Oregon، هل يحلّ تقرير الشرطة عن حادثك محلّ تقريرك أنت إلى DMV؟","o":["نعم، الشرطة ترسله عنك","لا، يجب أن تقدّم تقريرك أنت إلى DMV","نعم، إذا لم يُصب أحد","فقط إذا وافق السائق الآخر"],"h1":"واجب الإبلاغ عليك أنت.","h2":"في Oregon تقرير الشرطة لا يحلّ محلّ تقرير الحادث الخاص بك، لذلك يجب أن تقدّم تقريرك إلى DMV.","p":"صحيح. ما زلت تقدّم تقريرك أنت إلى DMV."},"ref":{"doc":"OR","page":94}},{"id":"or-022","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, what is the minimum bodily injury liability coverage a car owner must carry for one person?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"It is half of the minimum for two or more people.","h2":"In Oregon, a car owner must carry at least $25,000 of bodily injury liability coverage for one person.","p":"Right. The bodily injury liability minimum is $25,000 per person."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima de responsabilidad por lesiones corporales que debe tener el dueño de un carro por una persona?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Es la mitad del mínimo para dos o más personas.","h2":"En Oregon, el dueño de un carro debe tener por lo menos $25,000 de cobertura de responsabilidad por lesiones corporales por persona.","p":"Correcto. El mínimo de responsabilidad por lesiones corporales es $25,000 por persona."},"zh":{"q":"在 Oregon，车主为一个人必须买的最低人身伤害责任保险（bodily injury liability）是多少？","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"它是两人或以上最低额度的一半。","h2":"在 Oregon，车主必须为一个人买至少 $25,000 的人身伤害责任保险。","p":"对。人身伤害责任保险的最低额度是每人 $25,000。"},"vi":{"q":"Ở Oregon, chủ xe phải có mức bảo hiểm trách nhiệm thương tích cơ thể (bodily injury liability) tối thiểu là bao nhiêu cho một người?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Đó là một nửa mức tối thiểu cho hai người trở lên.","h2":"Ở Oregon, chủ xe phải có ít nhất $25,000 bảo hiểm trách nhiệm thương tích cơ thể cho một người.","p":"Đúng. Mức tối thiểu cho trách nhiệm thương tích cơ thể là $25,000 mỗi người."},"tl":{"q":"Sa Oregon, ano ang pinakamababang bodily injury liability coverage na dapat mayroon ang may-ari ng kotse para sa isang tao?","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"Kalahati ito ng pinakamababa para sa dalawa o higit pang tao.","h2":"Sa Oregon, dapat may hindi bababa sa $25,000 na bodily injury liability coverage ang may-ari ng kotse para sa isang tao.","p":"Tama. Ang pinakamababang bodily injury liability ay $25,000 bawat tao."},"ar":{"q":"في Oregon، ما الحد الأدنى لتأمين المسؤولية عن الإصابات الجسدية (bodily injury liability) الذي يجب أن يملكه صاحب السيارة لشخص واحد؟","o":["$25,000","$10,000","$15,000","$50,000"],"h1":"هو نصف الحد الأدنى لشخصين أو أكثر.","h2":"في Oregon، يجب أن يملك صاحب السيارة على الأقل $25,000 من تأمين المسؤولية عن الإصابات الجسدية لشخص واحد.","p":"صحيح. الحد الأدنى لتأمين المسؤولية عن الإصابات الجسدية هو $25,000 لكل شخص."},"ref":{"doc":"OR","page":93}},{"id":"or-023","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, until when must a child ride in an approved child safety seat?","o":["Until age 4 or 40 pounds","Until age 6 or 4 feet tall","Until age 8 or 4 feet 9 inches tall, when the adult belt fits","Until age 12, no matter the height"],"h1":"It depends on both the age and the height of the child.","h2":"In Oregon a child must ride in an approved child safety seat until age 8 or 4 feet 9 inches tall, when the adult lap and shoulder belt fits correctly.","p":"Right. A child seat is needed until age 8 or 4 feet 9 inches, when the adult belt fits."},"es":{"q":"En Oregon, ¿hasta cuándo debe viajar un niño en un asiento de seguridad aprobado?","o":["Hasta los 4 años o 40 libras","Hasta los 6 años o 4 pies de altura","Hasta los 8 años o 4 pies 9 pulgadas, cuando el cinturón de adulto le queda bien","Hasta los 12 años, sin importar la altura"],"h1":"Depende de la edad y también de la estatura del niño.","h2":"En Oregon un niño debe viajar en un asiento de seguridad aprobado hasta los 8 años o hasta medir 4 pies 9 pulgadas, cuando el cinturón de regazo y hombro de adulto le queda bien.","p":"Correcto. Se necesita el asiento hasta los 8 años o 4 pies 9 pulgadas, cuando el cinturón de adulto le queda bien."},"zh":{"q":"在 Oregon，儿童必须坐在合格的儿童安全座椅里，直到什么时候？","o":["到 4 岁或 40 磅","到 6 岁或身高 4 英尺","到 8 岁或身高 4 英尺 9 英寸，成人安全带合适时","到 12 岁，不论身高"],"h1":"这要看孩子的年龄和身高。","h2":"在 Oregon，儿童必须坐在合格的儿童安全座椅里，直到 8 岁或身高 4 英尺 9 英寸，而且成人腰带和肩带能正确系好。","p":"对。儿童座椅要用到 8 岁或 4 英尺 9 英寸，成人安全带合适时为止。"},"vi":{"q":"Ở Oregon, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến khi nào?","o":["Đến 4 tuổi hoặc 40 pound","Đến 6 tuổi hoặc cao 4 feet","Đến 8 tuổi hoặc cao 4 feet 9 inch, khi dây an toàn người lớn vừa","Đến 12 tuổi, bất kể chiều cao"],"h1":"Điều này tùy vào cả tuổi và chiều cao của trẻ.","h2":"Ở Oregon, trẻ em phải ngồi ghế an toàn trẻ em được chấp thuận cho đến 8 tuổi hoặc cao 4 feet 9 inch, khi dây an toàn vai và hông của người lớn vừa đúng.","p":"Đúng. Cần ghế trẻ em đến 8 tuổi hoặc 4 feet 9 inch, khi dây an toàn người lớn vừa."},"tl":{"q":"Sa Oregon, hanggang kailan dapat nakasakay ang bata sa aprubadong child safety seat?","o":["Hanggang 4 na taon o 40 pounds","Hanggang 6 na taon o 4 feet ang taas","Hanggang 8 taon o 4 feet 9 inches ang taas, kapag kasya na ang seat belt ng adult","Hanggang 12 taon, anuman ang taas"],"h1":"Nakadepende ito sa edad at taas ng bata.","h2":"Sa Oregon, dapat nakasakay ang bata sa aprubadong child safety seat hanggang 8 taon o 4 feet 9 inches ang taas, kapag tama na ang kasya ng lap at shoulder belt ng adult.","p":"Tama. Kailangan ang child seat hanggang 8 taon o 4 feet 9 inches, kapag kasya na ang seat belt ng adult."},"ar":{"q":"في Oregon، حتى متى يجب أن يجلس الطفل في مقعد أمان للأطفال معتمد؟","o":["حتى عمر 4 سنوات أو 40 رطلًا","حتى عمر 6 سنوات أو طول 4 أقدام","حتى عمر 8 سنوات أو طول 4 أقدام و9 بوصات، عندما يناسبه حزام البالغين","حتى عمر 12 سنة، مهما كان الطول"],"h1":"يعتمد ذلك على عمر الطفل وطوله معًا.","h2":"في Oregon يجب أن يجلس الطفل في مقعد أمان للأطفال معتمد حتى عمر 8 سنوات أو طول 4 أقدام و9 بوصات، عندما يناسبه حزام الحضن والكتف للبالغين بشكل صحيح.","p":"صحيح. مقعد الطفل مطلوب حتى عمر 8 سنوات أو 4 أقدام و9 بوصات، عندما يناسبه حزام البالغين."},"ref":{"doc":"OR","page":74}},{"id":"or-024","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, during which months are studded tires generally allowed?","o":["October 1 through April 30","November 1 through March 31","December 1 through February 28","All year in the mountains"],"h1":"It starts in late fall and ends as spring begins.","h2":"In Oregon studded tires are generally allowed only from November 1 through March 31.","p":"Right. Studded tires are generally allowed from November 1 through March 31."},"es":{"q":"En Oregon, ¿en qué meses se permiten en general las llantas con clavos (studded tires)?","o":["Del 1 de octubre al 30 de abril","Del 1 de noviembre al 31 de marzo","Del 1 de diciembre al 28 de febrero","Todo el año en las montañas"],"h1":"Empieza a fines del otoño y termina al comenzar la primavera.","h2":"En Oregon las llantas con clavos se permiten en general solo del 1 de noviembre al 31 de marzo.","p":"Correcto. Las llantas con clavos se permiten en general del 1 de noviembre al 31 de marzo."},"zh":{"q":"在 Oregon，一般在哪几个月可以使用钉胎（studded tires）？","o":["10 月 1 日到 4 月 30 日","11 月 1 日到 3 月 31 日","12 月 1 日到 2 月 28 日","在山区全年都可以"],"h1":"它从深秋开始，到春天开始时结束。","h2":"在 Oregon，钉胎一般只能在 11 月 1 日到 3 月 31 日之间使用。","p":"对。钉胎一般在 11 月 1 日到 3 月 31 日可以使用。"},"vi":{"q":"Ở Oregon, lốp xe có đinh (studded tires) thường được phép dùng trong những tháng nào?","o":["Từ 1 tháng 10 đến 30 tháng 4","Từ 1 tháng 11 đến 31 tháng 3","Từ 1 tháng 12 đến 28 tháng 2","Cả năm ở vùng núi"],"h1":"Thời gian bắt đầu vào cuối mùa thu và kết thúc khi mùa xuân bắt đầu.","h2":"Ở Oregon, lốp xe có đinh thường chỉ được phép dùng từ 1 tháng 11 đến 31 tháng 3.","p":"Đúng. Lốp xe có đinh thường được phép dùng từ 1 tháng 11 đến 31 tháng 3."},"tl":{"q":"Sa Oregon, sa anong mga buwan karaniwang pinapayagan ang studded tires?","o":["Oktubre 1 hanggang Abril 30","Nobyembre 1 hanggang Marso 31","Disyembre 1 hanggang Pebrero 28","Buong taon sa kabundukan"],"h1":"Nagsisimula ito sa huling bahagi ng taglagas at natatapos pagsimula ng tagsibol.","h2":"Sa Oregon, karaniwang pinapayagan lang ang studded tires mula Nobyembre 1 hanggang Marso 31.","p":"Tama. Karaniwang pinapayagan ang studded tires mula Nobyembre 1 hanggang Marso 31."},"ar":{"q":"في Oregon، في أي أشهر يُسمح عادةً بالإطارات ذات المسامير (studded tires)؟","o":["من 1 أكتوبر حتى 30 أبريل","من 1 نوفمبر حتى 31 مارس","من 1 ديسمبر حتى 28 فبراير","طوال السنة في الجبال"],"h1":"تبدأ في أواخر الخريف وتنتهي مع بداية الربيع.","h2":"في Oregon يُسمح عادةً بالإطارات ذات المسامير فقط من 1 نوفمبر حتى 31 مارس.","p":"صحيح. يُسمح عادةً بالإطارات ذات المسامير من 1 نوفمبر حتى 31 مارس."},"ref":{"doc":"OR","page":79}},{"id":"or-025","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you are turning at an intersection with a traffic light. A person is crossing the street you are turning into. When may you start your turn?","o":["As soon as the person reaches the center line","When the person is 2 feet from your car","When your light turns green, no matter where the person is","When the person is at least 6 feet from the lane you are turning into"],"h1":"The person needs a safe space away from your lane.","h2":"In Oregon, at an intersection with a traffic light, you may start your turn only when the person is at least 6 feet from the lane you are turning into.","p":"Right. Wait until the person is 6 feet or more from your lane."},"es":{"q":"En Oregon, usted va a dar vuelta en una intersección con semáforo. Una persona está cruzando la calle a la que usted va a entrar. ¿Cuándo puede empezar la vuelta?","o":["En cuanto la persona llegue a la línea central","Cuando la persona esté a 2 pies de su carro","Cuando su luz cambie a verde, sin importar dónde esté la persona","Cuando la persona esté por lo menos a 6 pies del carril al que usted va a entrar"],"h1":"La persona necesita un espacio seguro lejos de su carril.","h2":"En Oregon, en una intersección con semáforo, usted puede empezar la vuelta solo cuando la persona está por lo menos a 6 pies del carril al que va a entrar.","p":"Correcto. Espere hasta que la persona esté a 6 pies o más de su carril."},"zh":{"q":"在 Oregon，你在有红绿灯的路口转弯。有一个人正在过你要转进去的那条街。你什么时候可以开始转弯？","o":["那个人一走到中线就可以","那个人离你的车 2 英尺时","你的灯变绿时，不管那个人在哪里","那个人离你要转进去的车道至少 6 英尺时"],"h1":"那个人需要离你的车道有一段安全距离。","h2":"在 Oregon，在有红绿灯的路口，只有当那个人离你要转进去的车道至少 6 英尺时，你才可以开始转弯。","p":"对。要等那个人离你的车道 6 英尺或更远。"},"vi":{"q":"Ở Oregon, bạn đang rẽ tại giao lộ có đèn giao thông. Có một người đang băng qua con đường bạn sắp rẽ vào. Khi nào bạn có thể bắt đầu rẽ?","o":["Ngay khi người đó đến vạch giữa đường","Khi người đó cách xe bạn 2 feet","Khi đèn của bạn chuyển xanh, bất kể người đó ở đâu","Khi người đó cách làn bạn sắp rẽ vào ít nhất 6 feet"],"h1":"Người đó cần một khoảng an toàn cách xa làn của bạn.","h2":"Ở Oregon, tại giao lộ có đèn giao thông, bạn chỉ được bắt đầu rẽ khi người đó cách làn bạn sắp rẽ vào ít nhất 6 feet.","p":"Đúng. Hãy chờ đến khi người đó cách làn của bạn 6 feet trở lên."},"tl":{"q":"Sa Oregon, liliko ka sa intersection na may traffic light. May taong tumatawid sa kalyeng liliko-an mo. Kailan ka puwedeng magsimulang lumiko?","o":["Kapag naabot na ng tao ang center line","Kapag 2 feet na lang ang layo ng tao sa sasakyan mo","Kapag naging green ang ilaw mo, kahit nasaan ang tao","Kapag hindi bababa sa 6 feet ang layo ng tao sa lane na liliko-an mo"],"h1":"Kailangan ng tao ng ligtas na layo mula sa lane mo.","h2":"Sa Oregon, sa intersection na may traffic light, puwede ka lang magsimulang lumiko kapag hindi bababa sa 6 feet ang layo ng tao sa lane na liliko-an mo.","p":"Tama. Maghintay hanggang 6 feet o higit pa ang layo ng tao sa lane mo."},"ar":{"q":"في Oregon، أنت تنعطف عند تقاطع فيه إشارة مرور. يوجد شخص يعبر الشارع الذي تنعطف إليه. متى يمكنك أن تبدأ الانعطاف؟","o":["بمجرد أن يصل الشخص إلى خط المنتصف","عندما يكون الشخص على بعد 2 قدم من سيارتك","عندما تصبح إشارتك خضراء، أينما كان الشخص","عندما يكون الشخص على بعد 6 أقدام على الأقل من المسار الذي تنعطف إليه"],"h1":"يحتاج الشخص إلى مسافة آمنة بعيدًا عن مسارك.","h2":"في Oregon، عند تقاطع فيه إشارة مرور، يمكنك أن تبدأ الانعطاف فقط عندما يكون الشخص على بعد 6 أقدام على الأقل من المسار الذي تنعطف إليه.","p":"صحيح. انتظر حتى يكون الشخص على بعد 6 أقدام أو أكثر من مسارك."},"ref":{"doc":"OR","page":47}},{"id":"or-026","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, how close to a fire hydrant may you park?","o":["No closer than 10 feet","No closer than 5 feet","No closer than 20 feet","No closer than 30 feet"],"h1":"It is a little less than the length of one car.","h2":"In Oregon you may not park within 10 feet of a fire hydrant.","p":"Right. Stay at least 10 feet away from a fire hydrant."},"es":{"q":"En Oregon, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 5 pies","No más cerca de 20 pies","No más cerca de 30 pies"],"h1":"Es un poco menos que el largo de un carro.","h2":"En Oregon usted no puede estacionarse a menos de 10 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 10 pies de un hidrante."},"zh":{"q":"在 Oregon，你停车时离消防栓最近可以多近？","o":["不能近于 10 英尺","不能近于 5 英尺","不能近于 20 英尺","不能近于 30 英尺"],"h1":"它比一辆车的长度短一点。","h2":"在 Oregon，你不能在消防栓 10 英尺以内停车。","p":"对。停车时要离消防栓至少 10 英尺。"},"vi":{"q":"Ở Oregon, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 5 feet","Không gần hơn 20 feet","Không gần hơn 30 feet"],"h1":"Khoảng cách này ngắn hơn chiều dài một chiếc xe một chút.","h2":"Ở Oregon, bạn không được đậu xe trong vòng 10 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 10 feet."},"tl":{"q":"Sa Oregon, gaano kalapit ka puwedeng pumarada sa fire hydrant?","o":["Hindi lalapit sa 10 feet","Hindi lalapit sa 5 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 30 feet"],"h1":"Medyo mas maikli ito sa haba ng isang kotse.","h2":"Sa Oregon, hindi ka puwedeng pumarada sa loob ng 10 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 10 feet mula sa fire hydrant."},"ar":{"q":"في Oregon، إلى أي مدى يمكنك أن تقترب من صنبور إطفاء الحريق عند الوقوف؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 5 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"هي أقل قليلًا من طول سيارة واحدة.","h2":"في Oregon لا يجوز لك الوقوف على بعد أقل من 10 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 10 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"OR","page":70}},{"id":"or-027","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"It is about the length of one large car.","h2":"In Oregon you may not park within 20 feet of a crosswalk at an intersection, marked or not.","p":"Right. Stay at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Oregon, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies"],"h1":"Es más o menos el largo de un carro grande.","h2":"En Oregon usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección, esté marcado o no.","p":"Correcto. Manténgase por lo menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Oregon，在路口的人行横道附近，你停车时最近可以多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 20 英尺","不能近于 50 英尺"],"h1":"它大约是一辆大车的长度。","h2":"在 Oregon，不论路口的人行横道有没有画线，你都不能在它 20 英尺以内停车。","p":"对。停车时要离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Oregon, bạn được đậu xe gần lối qua đường dành cho người đi bộ ở giao lộ đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 20 feet","Không gần hơn 50 feet"],"h1":"Khoảng cách này bằng chiều dài một chiếc xe lớn.","h2":"Ở Oregon, bạn không được đậu xe trong vòng 20 feet tính từ lối qua đường ở giao lộ, dù lối đó có kẻ vạch hay không.","p":"Đúng. Hãy đậu xe cách lối qua đường ở giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Oregon, gaano kalapit ka puwedeng pumarada sa tawiran (crosswalk) sa isang interseksyon?","o":["Hindi lalapit sa 5 feet","Hindi lalapit sa 10 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 50 feet"],"h1":"Halos kasinghaba ito ng isang malaking kotse.","h2":"Sa Oregon, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa tawiran sa interseksyon, may guhit man ito o wala.","p":"Tama. Lumayo nang hindi bababa sa 20 feet mula sa tawiran sa interseksyon."},"ar":{"q":"في Oregon، إلى أي مدى يمكنك أن تقترب من ممر المشاة عند التقاطع عند الوقوف؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 20 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"هي تقريبًا طول سيارة كبيرة واحدة.","h2":"في Oregon لا يجوز لك الوقوف على بعد أقل من 20 قدمًا من ممر المشاة عند التقاطع، سواء كان مرسومًا أم لا.","p":"صحيح. ابقَ على بعد 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ref":{"doc":"OR","page":71}},{"id":"or-028","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, you must stop at a railroad crossing that has no stop line. Where do you stop?","o":["At least 15 feet from the nearest rail","At least 5 feet from the nearest rail","Right next to the first rail","At least 100 feet from the tracks"],"h1":"Leave room so a train cannot hit the front of your car.","h2":"In Oregon, when a railroad crossing has no stop line, you must stop at least 15 feet from the nearest rail.","p":"Right. With no stop line, stop at least 15 feet from the nearest rail."},"es":{"q":"En Oregon, usted debe detenerse en un cruce de ferrocarril que no tiene línea de alto. ¿Dónde se detiene?","o":["Por lo menos a 15 pies del riel más cercano","Por lo menos a 5 pies del riel más cercano","Justo al lado del primer riel","Por lo menos a 100 pies de las vías"],"h1":"Deje espacio para que el tren no golpee el frente de su carro.","h2":"En Oregon, cuando un cruce de ferrocarril no tiene línea de alto, usted debe detenerse por lo menos a 15 pies del riel más cercano.","p":"Correcto. Sin línea de alto, deténgase por lo menos a 15 pies del riel más cercano."},"zh":{"q":"在 Oregon，你必须在一个没有停车线的铁路道口停车。你应该停在哪里？","o":["离最近的铁轨至少 15 英尺","离最近的铁轨至少 5 英尺","紧挨着第一条铁轨","离铁路至少 100 英尺"],"h1":"留出空间，让火车不会撞到你的车头。","h2":"在 Oregon，如果铁路道口没有停车线，你必须停在离最近的铁轨至少 15 英尺的地方。","p":"对。没有停车线时，要停在离最近的铁轨至少 15 英尺的地方。"},"vi":{"q":"Ở Oregon, bạn phải dừng lại ở một chỗ băng qua đường sắt không có vạch dừng. Bạn dừng ở đâu?","o":["Cách đường ray gần nhất ít nhất 15 feet","Cách đường ray gần nhất ít nhất 5 feet","Sát ngay đường ray đầu tiên","Cách đường sắt ít nhất 100 feet"],"h1":"Chừa khoảng trống để tàu hỏa không đụng vào đầu xe của bạn.","h2":"Ở Oregon, khi chỗ băng qua đường sắt không có vạch dừng, bạn phải dừng cách đường ray gần nhất ít nhất 15 feet.","p":"Đúng. Khi không có vạch dừng, hãy dừng cách đường ray gần nhất ít nhất 15 feet."},"tl":{"q":"Sa Oregon, kailangan mong huminto sa tawiran ng tren na walang stop line. Saan ka hihinto?","o":["Hindi bababa sa 15 feet mula sa pinakamalapit na riles","Hindi bababa sa 5 feet mula sa pinakamalapit na riles","Katabi mismo ng unang riles","Hindi bababa sa 100 feet mula sa riles"],"h1":"Mag-iwan ng puwang para hindi tamaan ng tren ang harap ng kotse mo.","h2":"Sa Oregon, kapag walang stop line ang tawiran ng tren, kailangan mong huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Kapag walang stop line, huminto nang hindi bababa sa 15 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Oregon، يجب أن تتوقف عند معبر سكة حديد ليس فيه خط توقف. أين تتوقف؟","o":["على بعد 15 قدمًا على الأقل من أقرب قضيب","على بعد 5 أقدام على الأقل من أقرب قضيب","بجانب القضيب الأول مباشرة","على بعد 100 قدم على الأقل من السكة"],"h1":"اترك مسافة حتى لا يصطدم القطار بمقدمة سيارتك.","h2":"في Oregon، عندما لا يكون في معبر السكة الحديد خط توقف، يجب أن تتوقف على بعد 15 قدمًا على الأقل من أقرب قضيب.","p":"صحيح. إذا لم يكن هناك خط توقف، فتوقف على بعد 15 قدمًا على الأقل من أقرب قضيب."},"ref":{"doc":"OR","page":64}},{"id":"or-029","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you pulled over for a fire truck with its siren on. After it passes, how far behind it must you stay?","o":["At least 50 feet","At least 100 feet","At least 200 feet","At least 500 feet"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Oregon, after an emergency vehicle passes, you must stay at least 500 feet behind it.","p":"Right. Stay at least 500 feet behind an emergency vehicle."},"es":{"q":"En Oregon, usted se orilló para dejar pasar a un camión de bomberos con la sirena prendida. Después de que pasa, ¿a qué distancia detrás de él debe quedarse?","o":["Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a 200 pies","Por lo menos a 500 pies"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Oregon, después de que pasa un vehículo de emergencia, usted debe quedarse por lo menos a 500 pies detrás de él.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un vehículo de emergencia."},"zh":{"q":"在 Oregon，你为一辆开着警笛的消防车靠边停车。它开过去以后，你必须在它后面保持多远？","o":["至少 50 英尺","至少 100 英尺","至少 200 英尺","至少 500 英尺"],"h1":"给它留足空间，因为它可能会突然停车或转弯。","h2":"在 Oregon，紧急车辆开过去以后，你必须在它后面保持至少 500 英尺。","p":"对。要在紧急车辆后面保持至少 500 英尺。"},"vi":{"q":"Ở Oregon, bạn đã tấp vào lề để nhường một xe cứu hỏa đang hú còi. Sau khi xe đó chạy qua, bạn phải giữ khoảng cách phía sau nó bao xa?","o":["Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet","Ít nhất 500 feet"],"h1":"Hãy chừa nhiều khoảng trống, vì xe đó có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Oregon, sau khi xe khẩn cấp chạy qua, bạn phải giữ khoảng cách ít nhất 500 feet phía sau nó.","p":"Đúng. Hãy giữ khoảng cách ít nhất 500 feet phía sau xe khẩn cấp."},"tl":{"q":"Sa Oregon, tumabi ka para sa isang fire truck na nakabukas ang sirena. Pagkalampas nito, gaano kalayo ka dapat manatili sa likod nito?","o":["Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet","Hindi bababa sa 500 feet"],"h1":"Bigyan ito ng malaking puwang, dahil baka bigla itong huminto o lumiko.","h2":"Sa Oregon, pagkalampas ng emergency vehicle, kailangan mong manatili nang hindi bababa sa 500 feet sa likod nito.","p":"Tama. Manatili nang hindi bababa sa 500 feet sa likod ng emergency vehicle."},"ar":{"q":"في Oregon، توقفت على جانب الطريق لسيارة إطفاء تعمل صفارتها. بعد أن تمر، على أي بعد يجب أن تبقى خلفها؟","o":["50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل","500 قدم على الأقل"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Oregon، بعد أن تمر سيارة الطوارئ، يجب أن تبقى خلفها على بعد 500 قدم على الأقل.","p":"صحيح. ابقَ خلف سيارة الطوارئ على بعد 500 قدم على الأقل."},"ref":{"doc":"OR","page":58}},{"id":"or-030","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, you are using your high beams. A car is coming toward you. When must you dim your lights?","o":["When it is within 100 feet","When it is within 500 feet","When it is within 1,000 feet","Only if the other driver flashes their lights"],"h1":"Switch early, so the other driver is not blinded.","h2":"In Oregon you must dim your high beams when an oncoming vehicle is within 500 feet.","p":"Right. Dim your high beams when an oncoming car is within 500 feet."},"es":{"q":"En Oregon, usted lleva las luces altas prendidas. Un carro viene hacia usted. ¿Cuándo debe bajar las luces?","o":["Cuando esté a menos de 100 pies","Cuando esté a menos de 500 pies","Cuando esté a menos de 1,000 pies","Solo si el otro conductor le hace cambio de luces"],"h1":"Cambie temprano, para no deslumbrar al otro conductor.","h2":"En Oregon usted debe bajar las luces altas cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. Baje las luces altas cuando un carro de frente esté a menos de 500 pies."},"zh":{"q":"在 Oregon，你正在开远光灯。前面有一辆车朝你开过来。你必须在什么时候把灯调暗？","o":["当它在 100 英尺以内时","当它在 500 英尺以内时","当它在 1,000 英尺以内时","只有当对方司机闪灯时"],"h1":"要早点换灯，这样对方司机不会被晃得看不见。","h2":"在 Oregon，当对面来车在 500 英尺以内时，你必须把远光灯调暗。","p":"对。对面来车在 500 英尺以内时，要把远光灯调暗。"},"vi":{"q":"Ở Oregon, bạn đang bật đèn pha (đèn chiếu xa). Có một xe đang chạy ngược chiều về phía bạn. Khi nào bạn phải giảm đèn?","o":["Khi xe đó cách bạn trong vòng 100 feet","Khi xe đó cách bạn trong vòng 500 feet","Khi xe đó cách bạn trong vòng 1,000 feet","Chỉ khi tài xế kia nháy đèn"],"h1":"Hãy đổi đèn sớm để tài xế kia không bị chói mắt.","h2":"Ở Oregon, bạn phải giảm đèn pha khi xe chạy ngược chiều cách bạn trong vòng 500 feet.","p":"Đúng. Hãy giảm đèn pha khi xe ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Oregon, gamit mo ang high beams. May kotseng papalapit sa iyo mula sa harap. Kailan mo kailangang i-dim ang ilaw mo?","o":["Kapag nasa loob na ito ng 100 feet","Kapag nasa loob na ito ng 500 feet","Kapag nasa loob na ito ng 1,000 feet","Kapag nag-flash lang ng ilaw ang ibang driver"],"h1":"Magpalit nang maaga para hindi masilaw ang ibang driver.","h2":"Sa Oregon, kailangan mong i-dim ang high beams mo kapag nasa loob ng 500 feet ang paparating na sasakyan.","p":"Tama. I-dim ang high beams kapag nasa loob ng 500 feet ang paparating na kotse."},"ar":{"q":"في Oregon، أنت تستخدم الأضواء العالية. هناك سيارة قادمة نحوك. متى يجب أن تخفض أضواءك؟","o":["عندما تصبح على بعد 100 قدم أو أقل","عندما تصبح على بعد 500 قدم أو أقل","عندما تصبح على بعد 1,000 قدم أو أقل","فقط إذا ومض السائق الآخر بأضوائه"],"h1":"بدّل الأضواء مبكرًا حتى لا يُبهَر السائق الآخر.","h2":"في Oregon يجب أن تخفض أضواءك العالية عندما تكون السيارة القادمة نحوك على بعد 500 قدم أو أقل.","p":"صحيح. اخفض أضواءك العالية عندما تكون السيارة القادمة على بعد 500 قدم أو أقل."},"ref":{"doc":"OR","page":76}},{"id":"or-031","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, inside city limits, you may not make a U-turn where traffic from either direction cannot see your car from how far away?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Outside city limits the distance is twice as far.","h2":"In Oregon, inside city limits, you may not make a U-turn where traffic from either direction cannot see your car within 500 feet.","p":"Right. In a city, other drivers must be able to see you from 500 feet."},"es":{"q":"En Oregon, dentro de los límites de una ciudad, no puede dar una vuelta en U donde el tráfico de cualquier dirección no puede ver su carro desde ¿qué distancia?","o":["100 pies","250 pies","500 pies","1,000 pies"],"h1":"Fuera de la ciudad la distancia es el doble.","h2":"En Oregon, dentro de los límites de una ciudad, usted no puede dar una vuelta en U donde el tráfico de cualquier dirección no puede ver su carro a 500 pies.","p":"Correcto. En la ciudad, los otros conductores deben poder verlo desde 500 pies."},"zh":{"q":"在 Oregon 的城市范围内，如果两个方向的车辆在多远的距离内看不到你的车，你就不能掉头（U-turn）？","o":["100 英尺","250 英尺","500 英尺","1,000 英尺"],"h1":"在城市范围外，这个距离是两倍远。","h2":"在 Oregon 的城市范围内，如果两个方向的车辆在 500 英尺内看不到你的车，你就不能掉头。","p":"对。在城市里，其他司机必须能在 500 英尺外看到你。"},"vi":{"q":"Ở Oregon, trong phạm vi thành phố, bạn không được quay đầu xe (U-turn) ở chỗ mà xe từ cả hai hướng không thể thấy xe bạn từ khoảng cách bao xa?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Ngoài phạm vi thành phố, khoảng cách này xa gấp đôi.","h2":"Ở Oregon, trong phạm vi thành phố, bạn không được quay đầu xe ở chỗ mà xe từ cả hai hướng không thể thấy xe bạn trong vòng 500 feet.","p":"Đúng. Trong thành phố, các tài xế khác phải thấy được bạn từ 500 feet."},"tl":{"q":"Sa Oregon, sa loob ng city limits, hindi ka puwedeng mag-U-turn kung saan hindi makikita ng trapiko mula sa alinmang direksyon ang kotse mo mula sa gaano kalayo?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Sa labas ng city limits, doble ang layo nito.","h2":"Sa Oregon, sa loob ng city limits, hindi ka puwedeng mag-U-turn kung saan hindi makikita ng trapiko mula sa alinmang direksyon ang kotse mo sa loob ng 500 feet.","p":"Tama. Sa lungsod, dapat kang makita ng ibang driver mula sa 500 feet."},"ar":{"q":"في Oregon، داخل حدود المدينة، لا يجوز لك الالتفاف للخلف (U-turn) في مكان لا تستطيع فيه السيارات من أي اتجاه أن ترى سيارتك من أي مسافة؟","o":["100 قدم","250 قدمًا","500 قدم","1,000 قدم"],"h1":"خارج حدود المدينة تكون المسافة ضعف ذلك.","h2":"في Oregon، داخل حدود المدينة، لا يجوز لك الالتفاف للخلف في مكان لا تستطيع فيه السيارات من أي اتجاه أن ترى سيارتك من مسافة 500 قدم.","p":"صحيح. في المدينة يجب أن يستطيع السائقون الآخرون رؤيتك من مسافة 500 قدم."},"ref":{"doc":"OR","page":41}},{"id":"or-032","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, what is the speed limit on a road or highway that does not fit any other speed rule, when no limit is posted?","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"It is the same number as the old national highway limit.","h2":"In Oregon the speed limit is 55 mph on roads and highways that fit no other speed rule, unless a different limit is posted.","p":"Right. In Oregon it is 55 mph when no other rule or sign applies."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una carretera que no entra en ninguna otra regla de velocidad, si no hay un límite señalado?","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"Es el mismo número que el antiguo límite nacional de las carreteras.","h2":"En Oregon el límite es de 55 mph en las carreteras que no entran en ninguna otra regla de velocidad, a menos que se señale otro límite.","p":"Correcto. En Oregon son 55 mph cuando no se aplica otra regla ni otra señal."},"zh":{"q":"在 Oregon，如果一条道路或公路不符合任何其他限速规定，而且没有标出限速，限速是多少？","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"它和以前全国公路的限速是同一个数字。","h2":"在 Oregon，不符合任何其他限速规定的道路和公路，限速是 55 mph，除非标出了不同的限速。","p":"对。在 Oregon，没有其他规定或标志时，限速是 55 mph。"},"vi":{"q":"Ở Oregon, tốc độ tối đa trên đường hoặc xa lộ không thuộc quy định tốc độ nào khác, khi không có biển báo tốc độ, là bao nhiêu?","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"Đó là cùng con số với giới hạn tốc độ xa lộ toàn quốc ngày trước.","h2":"Ở Oregon, tốc độ tối đa là 55 mph trên đường và xa lộ không thuộc quy định tốc độ nào khác, trừ khi có biển báo giới hạn khác.","p":"Đúng. Ở Oregon là 55 mph khi không có quy định hay biển báo nào khác."},"tl":{"q":"Sa Oregon, ano ang speed limit sa kalsada o highway na hindi sakop ng ibang tuntunin sa bilis, kapag walang nakapaskil na limit?","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"Pareho ito sa numero ng dating pambansang limit sa highway.","h2":"Sa Oregon, 55 mph ang speed limit sa mga kalsada at highway na hindi sakop ng ibang tuntunin sa bilis, maliban kung may ibang nakapaskil na limit.","p":"Tama. Sa Oregon, 55 mph ito kapag walang ibang tuntunin o karatula."},"ar":{"q":"في Oregon، ما حدّ السرعة على طريق أو طريق سريع لا تنطبق عليه أي قاعدة سرعة أخرى، عندما لا توجد لافتة بحدّ السرعة؟","o":["55 mph","45 mph","60 mph","65 mph"],"h1":"هو نفس رقم حدّ السرعة الوطني القديم على الطرق السريعة.","h2":"في Oregon حدّ السرعة هو 55 mph على الطرق والطرق السريعة التي لا تنطبق عليها أي قاعدة سرعة أخرى، إلا إذا كانت هناك لافتة بحدّ مختلف.","p":"صحيح. في Oregon يكون الحدّ 55 mph عندما لا تنطبق قاعدة أو لافتة أخرى."},"ref":{"doc":"OR","page":19}},{"id":"or-033","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, you are driving faster than 30 mph. How far behind the car ahead should you stay?","o":["At least 2 seconds","At least 4 seconds","At least 1 car length","At least 10 feet"],"h1":"The faster you go, the more time you need. Count in seconds.","h2":"In Oregon, at speeds over 30 mph, you should stay at least 4 seconds behind the car ahead.","p":"Right. Above 30 mph, Oregon says to keep 4 seconds or more."},"es":{"q":"En Oregon, usted maneja a más de 30 mph. ¿A qué distancia debe ir detrás del auto de adelante?","o":["Al menos 2 segundos","Al menos 4 segundos","Al menos el largo de 1 auto","Al menos 10 pies"],"h1":"Cuanto más rápido va, más tiempo necesita. Cuente en segundos.","h2":"En Oregon, a más de 30 mph, usted debe ir al menos 4 segundos detrás del auto de adelante.","p":"Correcto. A más de 30 mph, Oregon indica dejar 4 segundos o más."},"zh":{"q":"在 Oregon，你的车速超过 30 mph。你应该和前车保持多远的距离？","o":["至少 2 秒","至少 4 秒","至少 1 个车身长","至少 10 英尺"],"h1":"开得越快，需要的时间越多。用秒来数。","h2":"在 Oregon，车速超过 30 mph 时，你应该和前车保持至少 4 秒的距离。","p":"对。超过 30 mph 时，Oregon 要求保持 4 秒或更长。"},"vi":{"q":"Ở Oregon, bạn đang lái nhanh hơn 30 mph. Bạn nên giữ khoảng cách bao xa sau xe phía trước?","o":["Ít nhất 2 giây","Ít nhất 4 giây","Ít nhất 1 chiều dài xe","Ít nhất 10 feet"],"h1":"Càng chạy nhanh, bạn càng cần nhiều thời gian. Hãy đếm bằng giây.","h2":"Ở Oregon, khi chạy trên 30 mph, bạn nên giữ khoảng cách ít nhất 4 giây sau xe phía trước.","p":"Đúng. Trên 30 mph, Oregon nói phải giữ 4 giây hoặc hơn."},"tl":{"q":"Sa Oregon, nagmamaneho ka nang mas mabilis sa 30 mph. Gaano kalayo ka dapat sa likod ng kotse sa unahan?","o":["Hindi bababa sa 2 segundo","Hindi bababa sa 4 na segundo","Hindi bababa sa haba ng 1 kotse","Hindi bababa sa 10 feet"],"h1":"Mas mabilis ka, mas maraming oras ang kailangan mo. Magbilang sa segundo.","h2":"Sa Oregon, kapag lampas sa 30 mph ang bilis mo, dapat kang manatili nang hindi bababa sa 4 na segundo sa likod ng kotse sa unahan.","p":"Tama. Lampas sa 30 mph, sabi ng Oregon na panatilihin ang 4 na segundo o higit pa."},"ar":{"q":"في Oregon، أنت تقود بسرعة أكثر من 30 mph. كم يجب أن تبقى خلف السيارة التي أمامك؟","o":["ثانيتان على الأقل","4 ثوانٍ على الأقل","طول سيارة واحدة على الأقل","10 أقدام على الأقل"],"h1":"كلما أسرعت احتجت إلى وقت أكثر. احسب بالثواني.","h2":"في Oregon، عند سرعة أكثر من 30 mph، يجب أن تبقى خلف السيارة التي أمامك 4 ثوانٍ على الأقل.","p":"صحيح. فوق 30 mph تقول Oregon أن تترك 4 ثوانٍ أو أكثر."},"ref":{"doc":"OR","page":26}},{"id":"or-034","scope":"OR","cat":"signals","sign":null,"c":2,"en":{"q":"In Oregon, when may you use hand-and-arm signals instead of your signal lights?","o":["At night, if your signal lights are broken","Any time, day or night","In daylight, when you can see people and cars 1,000 feet away","Only when you drive a wide or long vehicle"],"h1":"Other drivers must be able to see your arm clearly.","h2":"In Oregon you may use hand-and-arm signals only in daylight, when you can clearly see people and cars 1,000 feet away.","p":"Right. Hand signals are for daylight with 1,000 feet of clear view."},"es":{"q":"En Oregon, ¿cuándo puede usar señales con la mano y el brazo en lugar de las luces direccionales?","o":["De noche, si sus luces direccionales no funcionan","En cualquier momento, de día o de noche","De día, cuando puede ver personas y autos a 1,000 pies","Solo cuando maneja un vehículo ancho o largo"],"h1":"Los otros conductores deben poder ver bien su brazo.","h2":"En Oregon usted puede usar señales con la mano y el brazo solo de día, cuando puede ver con claridad personas y autos a 1,000 pies.","p":"Correcto. Las señales con la mano son para el día, con 1,000 pies de vista clara."},"zh":{"q":"在 Oregon，什么时候可以用手臂信号代替车上的信号灯？","o":["在晚上，如果你的信号灯坏了","任何时候，白天或晚上都可以","在白天，能看到 1,000 英尺外的人和车时","只有在驾驶很宽或很长的车时"],"h1":"其他司机必须能清楚地看到你的手臂。","h2":"在 Oregon，只有在白天、你能清楚看到 1,000 英尺外的人和车时，才可以使用手臂信号。","p":"对。手臂信号只能在白天、视线清楚达 1,000 英尺时使用。"},"vi":{"q":"Ở Oregon, khi nào bạn được dùng tín hiệu tay thay cho đèn xi-nhan?","o":["Vào ban đêm, nếu đèn xi-nhan bị hỏng","Bất cứ lúc nào, ngày hay đêm","Vào ban ngày, khi bạn có thể thấy người và xe cách 1,000 feet","Chỉ khi bạn lái xe rộng hoặc dài"],"h1":"Các tài xế khác phải nhìn thấy cánh tay của bạn rõ ràng.","h2":"Ở Oregon, bạn chỉ được dùng tín hiệu tay vào ban ngày, khi bạn có thể thấy rõ người và xe cách 1,000 feet.","p":"Đúng. Tín hiệu tay dùng vào ban ngày khi nhìn rõ được 1,000 feet."},"tl":{"q":"Sa Oregon, kailan ka puwedeng gumamit ng hand-and-arm signals sa halip na signal lights?","o":["Sa gabi, kung sira ang signal lights mo","Kahit kailan, araw man o gabi","Sa araw, kapag nakikita mo ang mga tao at kotse na 1,000 feet ang layo","Kapag nagmamaneho ka lang ng malapad o mahabang sasakyan"],"h1":"Dapat malinaw na nakikita ng ibang driver ang braso mo.","h2":"Sa Oregon, puwede kang gumamit ng hand-and-arm signals sa araw lang, kapag malinaw mong nakikita ang mga tao at kotse na 1,000 feet ang layo.","p":"Tama. Para sa araw ang hand signals, kapag malinaw ang tanaw hanggang 1,000 feet."},"ar":{"q":"في Oregon، متى يجوز لك أن تستخدم إشارات اليد والذراع بدلًا من أضواء الإشارة؟","o":["في الليل، إذا كانت أضواء الإشارة معطّلة","في أي وقت، نهارًا أو ليلًا","في النهار، عندما ترى الناس والسيارات على بعد 1,000 قدم","فقط عندما تقود مركبة عريضة أو طويلة"],"h1":"يجب أن يرى السائقون الآخرون ذراعك بوضوح.","h2":"في Oregon يجوز لك أن تستخدم إشارات اليد والذراع في النهار فقط، عندما ترى الناس والسيارات بوضوح على بعد 1,000 قدم.","p":"صحيح. إشارات اليد للنهار مع رؤية واضحة لمسافة 1,000 قدم."},"ref":{"doc":"OR","page":38}},{"id":"or-035","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you are in a roundabout with two lanes. A large truck is in the circle with you. What does the law say?","o":["You may pass the truck on the right","You may drive beside the truck if you stay in your lane","You must stop inside the circle until the truck exits","You may not pass the truck or drive beside it"],"h1":"A truck may need both lanes to get around the circle.","h2":"In Oregon it is against the law to pass a truck or drive beside it inside a roundabout.","p":"Right. In an Oregon roundabout, never pass a truck or ride beside it."},"es":{"q":"En Oregon, usted está en una glorieta de dos carriles. Un camión grande está dentro del círculo con usted. ¿Qué dice la ley?","o":["Puede rebasar al camión por la derecha","Puede ir al lado del camión si se queda en su carril","Debe detenerse dentro del círculo hasta que el camión salga","No puede rebasar al camión ni ir a su lado"],"h1":"Un camión puede necesitar los dos carriles para dar la vuelta.","h2":"En Oregon es ilegal rebasar a un camión o ir a su lado dentro de una glorieta.","p":"Correcto. En una glorieta de Oregon, nunca rebase a un camión ni vaya a su lado."},"zh":{"q":"在 Oregon，你在一个有两条车道的环岛里。一辆大卡车和你一起在环岛里。法律怎么规定？","o":["你可以从右边超过卡车","如果你待在自己的车道，可以和卡车并排开","你必须在环岛里停下，直到卡车离开","你不可以超过卡车，也不可以和它并排开"],"h1":"卡车可能需要两条车道才能绕过环岛。","h2":"在 Oregon，在环岛里超过卡车或和卡车并排开是违法的。","p":"对。在 Oregon 的环岛里，绝对不要超过卡车或和它并排开。"},"vi":{"q":"Ở Oregon, bạn đang ở trong một vòng xoay có hai làn. Một xe tải lớn cũng đang ở trong vòng xoay với bạn. Luật nói gì?","o":["Bạn được vượt xe tải bên phải","Bạn được chạy song song với xe tải nếu bạn ở trong làn của mình","Bạn phải dừng lại trong vòng xoay cho đến khi xe tải ra khỏi","Bạn không được vượt xe tải hoặc chạy song song với nó"],"h1":"Xe tải có thể cần cả hai làn để đi vòng qua vòng xoay.","h2":"Ở Oregon, vượt xe tải hoặc chạy song song với xe tải trong vòng xoay là phạm luật.","p":"Đúng. Trong vòng xoay ở Oregon, không bao giờ vượt xe tải hoặc chạy song song với nó."},"tl":{"q":"Sa Oregon, nasa roundabout ka na may dalawang lane. May malaking trak na kasama mo sa loob ng bilog. Ano ang sabi ng batas?","o":["Puwede mong lampasan ang trak sa kanan","Puwede kang magmaneho sa tabi ng trak kung mananatili ka sa lane mo","Dapat kang huminto sa loob ng bilog hanggang lumabas ang trak","Hindi mo puwedeng lampasan ang trak o magmaneho sa tabi nito"],"h1":"Baka kailangan ng trak ang dalawang lane para makaikot sa bilog.","h2":"Sa Oregon, labag sa batas ang lampasan ang trak o magmaneho sa tabi nito sa loob ng roundabout.","p":"Tama. Sa roundabout sa Oregon, huwag kailanman lampasan ang trak o tumabi rito."},"ar":{"q":"في Oregon، أنت في دوّار له مساران. وهناك شاحنة كبيرة في الدوّار معك. ماذا يقول القانون؟","o":["يجوز لك أن تتجاوز الشاحنة من اليمين","يجوز لك أن تسير بجانب الشاحنة إذا بقيت في مسارك","يجب أن تتوقف داخل الدوّار حتى تخرج الشاحنة","لا يجوز لك أن تتجاوز الشاحنة أو تسير بجانبها"],"h1":"قد تحتاج الشاحنة إلى المسارين لتدور حول الدوّار.","h2":"في Oregon من المخالف للقانون أن تتجاوز شاحنة أو تسير بجانبها داخل الدوّار.","p":"صحيح. في دوّار في Oregon، لا تتجاوز شاحنة أبدًا ولا تسر بجانبها."},"ref":{"doc":"OR","page":44}},{"id":"or-036","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, you are turning at an intersection with no traffic light. A person is crossing the street you are turning into. When may you start your turn?","o":["When the person is past the lane you are turning into, plus the next lane","When the person is at least 6 feet from your lane","When the person reaches the middle of the street","As soon as the person sees you"],"h1":"Without a traffic light, you must give the person more room.","h2":"In Oregon, at an intersection with no traffic light, you may turn only when the person is past the lane you are turning into and the next lane too.","p":"Right. With no light, wait until the person is past your lane and the next one."},"es":{"q":"En Oregon, usted da vuelta en una intersección sin semáforo. Una persona cruza la calle a la que usted va a entrar. ¿Cuándo puede empezar la vuelta?","o":["Cuando la persona ya pasó el carril al que usted entra y también el carril siguiente","Cuando la persona está al menos a 6 pies de su carril","Cuando la persona llega a la mitad de la calle","En cuanto la persona lo ve a usted"],"h1":"Sin semáforo, usted debe dejarle más espacio a la persona.","h2":"En Oregon, en una intersección sin semáforo, usted puede dar vuelta solo cuando la persona ya pasó el carril al que usted entra y también el carril siguiente.","p":"Correcto. Sin semáforo, espere a que la persona pase su carril y el siguiente."},"zh":{"q":"在 Oregon，你在一个没有红绿灯的路口转弯。有一个人正在穿过你要转入的那条街。你什么时候可以开始转弯？","o":["当这个人走过你要转入的车道，再加上旁边的下一条车道时","当这个人离你的车道至少 6 英尺时","当这个人走到街道中间时","只要这个人看到你"],"h1":"没有红绿灯时，你必须给行人更多空间。","h2":"在 Oregon，在没有红绿灯的路口，只有当行人走过你要转入的车道，也走过下一条车道时，你才可以转弯。","p":"对。没有红绿灯时，要等行人走过你的车道和下一条车道。"},"vi":{"q":"Ở Oregon, bạn đang rẽ tại một giao lộ không có đèn giao thông. Có một người đang băng qua con đường mà bạn sắp rẽ vào. Khi nào bạn được bắt đầu rẽ?","o":["Khi người đó đã đi qua làn bạn sắp rẽ vào, và cả làn kế tiếp","Khi người đó cách làn của bạn ít nhất 6 feet","Khi người đó đến giữa đường","Ngay khi người đó thấy bạn"],"h1":"Không có đèn giao thông thì bạn phải chừa cho người đi bộ nhiều chỗ hơn.","h2":"Ở Oregon, tại giao lộ không có đèn giao thông, bạn chỉ được rẽ khi người đi bộ đã qua làn bạn sắp rẽ vào và cả làn kế tiếp.","p":"Đúng. Không có đèn thì chờ đến khi người đó đã qua làn của bạn và làn kế tiếp."},"tl":{"q":"Sa Oregon, liliko ka sa intersection na walang traffic light. May taong tumatawid sa kalyeng liliko-an mo. Kailan ka puwedeng magsimulang lumiko?","o":["Kapag nakalampas na ang tao sa lane na liliko-an mo, pati sa susunod na lane","Kapag hindi bababa sa 6 feet ang layo ng tao sa lane mo","Kapag nasa gitna na ng kalye ang tao","Sa sandaling makita ka ng tao"],"h1":"Kapag walang traffic light, dapat mong bigyan ng mas maraming espasyo ang tao.","h2":"Sa Oregon, sa intersection na walang traffic light, puwede ka lang lumiko kapag nakalampas na ang tao sa lane na liliko-an mo at sa susunod na lane din.","p":"Tama. Kapag walang ilaw, maghintay hanggang makalampas ang tao sa lane mo at sa susunod."},"ar":{"q":"في Oregon، أنت تنعطف عند تقاطع بلا إشارة مرور. هناك شخص يعبر الشارع الذي ستنعطف إليه. متى يجوز لك أن تبدأ الانعطاف؟","o":["عندما يتجاوز الشخص المسار الذي ستنعطف إليه، والمسار الذي يليه أيضًا","عندما يكون الشخص على بعد 6 أقدام على الأقل من مسارك","عندما يصل الشخص إلى منتصف الشارع","بمجرد أن يراك الشخص"],"h1":"بدون إشارة مرور، يجب أن تعطي الشخص مساحة أكبر.","h2":"في Oregon، عند تقاطع بلا إشارة مرور، يجوز لك أن تنعطف فقط عندما يتجاوز الشخص المسار الذي ستنعطف إليه والمسار الذي يليه أيضًا.","p":"صحيح. بدون إشارة، انتظر حتى يتجاوز الشخص مسارك والمسار الذي يليه."},"ref":{"doc":"OR","page":47}},{"id":"or-037","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, a school speed sign says the 20 mph limit applies during school hours. When does it apply?","o":["6 a.m. to 6 p.m. every day","7 a.m. to 5 p.m. on school days","8 a.m. to 3 p.m. on school days","Only when children are in the crosswalk"],"h1":"It covers the whole school day, from early morning to late afternoon.","h2":"In Oregon, a school hours speed sign means 20 mph from 7 a.m. to 5 p.m. on days when school is in session.","p":"Right. In Oregon, school hours mean 7 a.m. to 5 p.m. on school days."},"es":{"q":"En Oregon, una señal de zona escolar dice que el límite de 20 mph aplica en horario escolar. ¿Cuándo aplica?","o":["De 6 a.m. a 6 p.m. todos los días","De 7 a.m. a 5 p.m. en días de clases","De 8 a.m. a 3 p.m. en días de clases","Solo cuando hay niños en el cruce peatonal"],"h1":"Cubre todo el día escolar, desde temprano hasta la tarde.","h2":"En Oregon, una señal de horario escolar significa 20 mph de 7 a.m. a 5 p.m. en los días en que hay clases.","p":"Correcto. En Oregon, el horario escolar es de 7 a.m. a 5 p.m. en días de clases."},"zh":{"q":"在 Oregon，一个学校限速标志写着 20 mph 的限速在上学时间有效。它什么时候有效？","o":["每天早上 6 点到晚上 6 点","上学日早上 7 点到下午 5 点","上学日早上 8 点到下午 3 点","只有当孩子在人行横道上时"],"h1":"它包括整个上学日，从一大早到傍晚。","h2":"在 Oregon，写着上学时间的限速标志表示在学校上课的日子里，从早上 7 点到下午 5 点限速 20 mph。","p":"对。在 Oregon，上学时间是指上学日早上 7 点到下午 5 点。"},"vi":{"q":"Ở Oregon, một biển báo tốc độ khu trường học ghi rằng giới hạn 20 mph áp dụng trong giờ học. Khi nào giới hạn này áp dụng?","o":["6 giờ sáng đến 6 giờ chiều mỗi ngày","7 giờ sáng đến 5 giờ chiều vào ngày đi học","8 giờ sáng đến 3 giờ chiều vào ngày đi học","Chỉ khi có trẻ em trên lối băng qua đường"],"h1":"Nó bao gồm cả ngày học, từ sáng sớm đến chiều muộn.","h2":"Ở Oregon, biển báo tốc độ giờ học có nghĩa là 20 mph từ 7 giờ sáng đến 5 giờ chiều vào những ngày trường có học.","p":"Đúng. Ở Oregon, giờ học là từ 7 giờ sáng đến 5 giờ chiều vào ngày đi học."},"tl":{"q":"Sa Oregon, sinasabi ng school speed sign na ang 20 mph na limit ay para sa oras ng klase. Kailan ito ipinapatupad?","o":["6 a.m. hanggang 6 p.m. araw-araw","7 a.m. hanggang 5 p.m. sa mga araw na may pasok","8 a.m. hanggang 3 p.m. sa mga araw na may pasok","Kapag may mga bata lang sa crosswalk"],"h1":"Sakop nito ang buong araw ng klase, mula maagang umaga hanggang hapon.","h2":"Sa Oregon, ang speed sign para sa oras ng klase ay nangangahulugang 20 mph mula 7 a.m. hanggang 5 p.m. sa mga araw na may pasok ang paaralan.","p":"Tama. Sa Oregon, ang oras ng klase ay 7 a.m. hanggang 5 p.m. sa mga araw na may pasok."},"ar":{"q":"في Oregon، لافتة سرعة عند مدرسة تقول إن حدّ 20 mph يسري خلال ساعات الدراسة. متى يسري؟","o":["من 6 صباحًا إلى 6 مساءً كل يوم","من 7 صباحًا إلى 5 مساءً في أيام الدراسة","من 8 صباحًا إلى 3 مساءً في أيام الدراسة","فقط عندما يكون الأطفال على ممر المشاة"],"h1":"يشمل يوم الدراسة كله، من الصباح الباكر إلى آخر العصر.","h2":"في Oregon، لافتة السرعة لساعات الدراسة تعني 20 mph من 7 صباحًا إلى 5 مساءً في الأيام التي تكون فيها المدرسة مفتوحة للدراسة.","p":"صحيح. في Oregon، ساعات الدراسة تعني من 7 صباحًا إلى 5 مساءً في أيام الدراسة."},"ref":{"doc":"OR","page":49}},{"id":"or-038","scope":"OR","cat":"signals","sign":null,"c":2,"en":{"q":"In Oregon, there is a green bike box painted at the intersection ahead. The light is red and you want to turn right. What do you do?","o":["Stop inside the bike box, then turn right","Turn right on red after a full stop","Stop behind the bike box and wait for green","Move into the bike lane and turn right"],"h1":"The box is a space for people on bicycles, not for cars.","h2":"In Oregon you must stop behind a bike box, and you may not turn right there while the light is red.","p":"Right. At a bike box, stop behind it and wait for green to turn right."},"es":{"q":"En Oregon, hay una caja verde para bicicletas pintada en la intersección de adelante. La luz está en rojo y usted quiere dar vuelta a la derecha. ¿Qué hace?","o":["Se detiene dentro de la caja para bicicletas y luego da vuelta","Da vuelta a la derecha con luz roja después de un alto total","Se detiene detrás de la caja para bicicletas y espera la luz verde","Se mete al carril para bicicletas y da vuelta a la derecha"],"h1":"La caja es un espacio para las personas en bicicleta, no para los autos.","h2":"En Oregon usted debe detenerse detrás de una caja para bicicletas, y no puede dar vuelta a la derecha ahí con la luz en rojo.","p":"Correcto. En una caja para bicicletas, deténgase detrás y espere la luz verde para dar vuelta."},"zh":{"q":"在 Oregon，前面路口地面上画着一个绿色的自行车等候区（bike box）。现在是红灯，你想右转。你该怎么做？","o":["停在自行车等候区里面，然后右转","完全停下后红灯右转","停在自行车等候区后面，等绿灯","开进自行车道再右转"],"h1":"这个区域是给骑自行车的人用的，不是给汽车用的。","h2":"在 Oregon，你必须停在自行车等候区后面，而且红灯时不可以在那里右转。","p":"对。遇到自行车等候区，要停在它后面，等绿灯再右转。"},"vi":{"q":"Ở Oregon, có một ô chờ xe đạp (bike box) màu xanh lá sơn trên mặt đường ở giao lộ phía trước. Đèn đang đỏ và bạn muốn rẽ phải. Bạn làm gì?","o":["Dừng bên trong ô chờ xe đạp, rồi rẽ phải","Rẽ phải khi đèn đỏ sau khi dừng hẳn","Dừng phía sau ô chờ xe đạp và chờ đèn xanh","Đi vào làn xe đạp và rẽ phải"],"h1":"Ô này là chỗ dành cho người đi xe đạp, không phải cho xe hơi.","h2":"Ở Oregon, bạn phải dừng phía sau ô chờ xe đạp, và bạn không được rẽ phải ở đó khi đèn đang đỏ.","p":"Đúng. Gặp ô chờ xe đạp, hãy dừng phía sau nó và chờ đèn xanh để rẽ phải."},"tl":{"q":"Sa Oregon, may berdeng bike box na nakapinta sa intersection sa unahan. Pula ang ilaw at gusto mong kumanan. Ano ang gagawin mo?","o":["Huminto sa loob ng bike box, saka kumanan","Kumanan kahit pula pagkatapos ng buong paghinto","Huminto sa likod ng bike box at hintayin ang berde","Pumasok sa bike lane at kumanan"],"h1":"Ang box ay espasyo para sa mga nakabisikleta, hindi para sa mga kotse.","h2":"Sa Oregon, dapat kang huminto sa likod ng bike box, at hindi ka puwedeng kumanan doon habang pula ang ilaw.","p":"Tama. Sa bike box, huminto sa likod nito at hintayin ang berde bago kumanan."},"ar":{"q":"في Oregon، هناك مربع أخضر للدراجات (bike box) مرسوم عند التقاطع أمامك. الإشارة حمراء وتريد أن تنعطف يمينًا. ماذا تفعل؟","o":["توقف داخل مربع الدراجات، ثم انعطف يمينًا","انعطف يمينًا والإشارة حمراء بعد توقف كامل","توقف خلف مربع الدراجات وانتظر الأخضر","ادخل مسار الدراجات وانعطف يمينًا"],"h1":"المربع مساحة لراكبي الدراجات، وليس للسيارات.","h2":"في Oregon يجب أن تتوقف خلف مربع الدراجات، ولا يجوز لك أن تنعطف يمينًا هناك والإشارة حمراء.","p":"صحيح. عند مربع الدراجات، توقف خلفه وانتظر الأخضر لتنعطف يمينًا."},"ref":{"doc":"OR","page":51}},{"id":"or-039","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you are in a crash and a person is unconscious. How long must you stay at the scene?","o":["Until you trade names with the other driver","Until an ambulance takes the person away","For 15 minutes","Until the police arrive"],"h1":"Someone with authority needs to talk to you.","h2":"In Oregon, if a person is killed or unconscious after a crash, you must stay at the scene until the police arrive.","p":"Right. In Oregon you stay until the police get there."},"es":{"q":"En Oregon, usted tiene un choque y una persona está inconsciente. ¿Cuánto tiempo debe quedarse en el lugar?","o":["Hasta intercambiar nombres con el otro conductor","Hasta que una ambulancia se lleve a la persona","Durante 15 minutos","Hasta que llegue la policía"],"h1":"Una autoridad necesita hablar con usted.","h2":"En Oregon, si una persona muere o queda inconsciente en un choque, usted debe quedarse en el lugar hasta que llegue la policía.","p":"Correcto. En Oregon usted se queda hasta que llegue la policía."},"zh":{"q":"在 Oregon，你发生了车祸，有一个人昏迷了。你必须在现场待多久？","o":["直到你和另一位司机交换姓名","直到救护车把这个人送走","15 分钟","直到警察到达"],"h1":"需要有权力的人和你谈话。","h2":"在 Oregon，如果车祸后有人死亡或昏迷，你必须待在现场，直到警察到达。","p":"对。在 Oregon，你要一直待到警察来。"},"vi":{"q":"Ở Oregon, bạn bị tai nạn và có một người bị bất tỉnh. Bạn phải ở lại hiện trường bao lâu?","o":["Cho đến khi bạn trao đổi tên với tài xế kia","Cho đến khi xe cứu thương chở người đó đi","Trong 15 phút","Cho đến khi cảnh sát đến"],"h1":"Một người có thẩm quyền cần nói chuyện với bạn.","h2":"Ở Oregon, nếu có người chết hoặc bất tỉnh sau tai nạn, bạn phải ở lại hiện trường cho đến khi cảnh sát đến.","p":"Đúng. Ở Oregon, bạn ở lại cho đến khi cảnh sát tới."},"tl":{"q":"Sa Oregon, naaksidente ka at may taong walang malay. Gaano katagal ka dapat manatili sa lugar ng aksidente?","o":["Hanggang makapagpalitan kayo ng pangalan ng ibang driver","Hanggang maisakay ng ambulansya ang tao","Sa loob ng 15 minuto","Hanggang dumating ang pulis"],"h1":"May taong may awtoridad na kailangang makausap ka.","h2":"Sa Oregon, kung may namatay o walang malay pagkatapos ng aksidente, dapat kang manatili sa lugar hanggang dumating ang pulis.","p":"Tama. Sa Oregon, manatili ka hanggang dumating ang pulis."},"ar":{"q":"في Oregon، وقع لك حادث وهناك شخص فاقد للوعي. كم يجب أن تبقى في مكان الحادث؟","o":["حتى تتبادل الأسماء مع السائق الآخر","حتى تأخذ سيارة الإسعاف الشخص","لمدة 15 دقيقة","حتى تصل الشرطة"],"h1":"شخص صاحب سلطة يحتاج أن يتكلم معك.","h2":"في Oregon، إذا مات شخص أو فقد وعيه بعد حادث، يجب أن تبقى في مكان الحادث حتى تصل الشرطة.","p":"صحيح. في Oregon تبقى حتى تصل الشرطة."},"ref":{"doc":"OR","page":94}},{"id":"or-040","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, a work zone has a lower temporary speed limit posted. When must you obey it?","o":["At all times, even when you see no workers","Only when workers are in sight","Only during the day","Only when the orange lights are flashing"],"h1":"Dangers in a work zone are there even when the crew is gone.","h2":"In Oregon the temporary speed limit in a work zone applies at all times, even if you do not see any workers.","p":"Right. In Oregon the work zone speed applies all the time."},"es":{"q":"En Oregon, una zona de obras tiene un límite de velocidad temporal más bajo. ¿Cuándo debe obedecerlo?","o":["Siempre, aunque no vea trabajadores","Solo cuando se ven trabajadores","Solo durante el día","Solo cuando las luces anaranjadas parpadean"],"h1":"Los peligros de una zona de obras siguen ahí aunque los trabajadores se hayan ido.","h2":"En Oregon el límite temporal de una zona de obras aplica siempre, aunque usted no vea trabajadores.","p":"Correcto. En Oregon la velocidad de la zona de obras aplica todo el tiempo."},"zh":{"q":"在 Oregon，一个施工区标出了较低的临时限速。你什么时候必须遵守它？","o":["任何时候都要，即使你看不到工人","只有在看得到工人时","只有在白天","只有在橙色灯闪烁时"],"h1":"即使工人离开了，施工区里的危险还在。","h2":"在 Oregon，施工区的临时限速任何时候都有效，即使你没有看到任何工人。","p":"对。在 Oregon，施工区限速一直有效。"},"vi":{"q":"Ở Oregon, một khu công trường có biển báo giới hạn tốc độ tạm thời thấp hơn. Khi nào bạn phải tuân theo?","o":["Mọi lúc, kể cả khi bạn không thấy công nhân","Chỉ khi thấy công nhân","Chỉ vào ban ngày","Chỉ khi đèn màu cam đang nhấp nháy"],"h1":"Nguy hiểm trong khu công trường vẫn còn ngay cả khi công nhân đã đi.","h2":"Ở Oregon, giới hạn tốc độ tạm thời trong khu công trường áp dụng mọi lúc, kể cả khi bạn không thấy công nhân nào.","p":"Đúng. Ở Oregon, tốc độ khu công trường áp dụng mọi lúc."},"tl":{"q":"Sa Oregon, may nakapaskil na mas mababang pansamantalang speed limit sa isang work zone. Kailan mo ito dapat sundin?","o":["Sa lahat ng oras, kahit wala kang nakikitang trabahador","Kapag may nakikitang trabahador lang","Sa araw lang","Kapag kumikislap lang ang orange na ilaw"],"h1":"Nandiyan pa rin ang mga panganib sa work zone kahit wala na ang mga trabahador.","h2":"Sa Oregon, ipinapatupad ang pansamantalang speed limit sa work zone sa lahat ng oras, kahit wala kang nakikitang trabahador.","p":"Tama. Sa Oregon, laging ipinapatupad ang speed limit sa work zone."},"ar":{"q":"في Oregon، في منطقة أعمال طرق لافتة بحدّ سرعة مؤقت أقل. متى يجب أن تلتزم به؟","o":["في كل الأوقات، حتى عندما لا ترى عمّالًا","فقط عندما ترى العمّال","فقط في النهار","فقط عندما تومض الأضواء البرتقالية"],"h1":"المخاطر في منطقة الأعمال موجودة حتى بعد ذهاب العمّال.","h2":"في Oregon حدّ السرعة المؤقت في منطقة الأعمال يسري في كل الأوقات، حتى إذا لم ترَ أي عمّال.","p":"صحيح. في Oregon سرعة منطقة الأعمال تسري طوال الوقت."},"ref":{"doc":"OR","page":59}},{"id":"or-041","scope":"OR","cat":"signals","sign":null,"c":1,"en":{"q":"In Oregon, a work zone has an automated flagger machine with lights and a gate arm. When must you stop?","o":["When the yellow light flashes and the arm is up","When the red light is on and the arm is down","Only when a person stands next to the machine","Never, it is only a warning"],"h1":"The machine works like a person with a STOP sign.","h2":"In Oregon you must stop at an automated flagger when its red light is on and its arm is down, and go when the yellow light flashes and the arm is up.","p":"Right. Red light and arm down means stop."},"es":{"q":"En Oregon, una zona de obras tiene una máquina abanderada automática con luces y un brazo. ¿Cuándo debe detenerse?","o":["Cuando la luz amarilla parpadea y el brazo está arriba","Cuando la luz roja está encendida y el brazo está abajo","Solo cuando hay una persona junto a la máquina","Nunca, es solo una advertencia"],"h1":"La máquina funciona como una persona con una señal de ALTO.","h2":"En Oregon usted debe detenerse ante un abanderado automático cuando la luz roja está encendida y el brazo está abajo, y avanzar cuando la luz amarilla parpadea y el brazo está arriba.","p":"Correcto. Luz roja y brazo abajo significan alto."},"zh":{"q":"在 Oregon，一个施工区有一台带灯和栏杆的自动指挥机。你什么时候必须停下？","o":["黄灯闪烁、栏杆升起时","红灯亮着、栏杆放下时","只有在机器旁边站着人时","永远不用，它只是一个警告"],"h1":"这台机器的作用就像一个拿着 STOP 牌的人。","h2":"在 Oregon，自动指挥机红灯亮着、栏杆放下时，你必须停下；黄灯闪烁、栏杆升起时，你可以走。","p":"对。红灯亮、栏杆放下就是停车。"},"vi":{"q":"Ở Oregon, một khu công trường có máy điều khiển giao thông tự động với đèn và thanh chắn. Khi nào bạn phải dừng?","o":["Khi đèn vàng nhấp nháy và thanh chắn nâng lên","Khi đèn đỏ sáng và thanh chắn hạ xuống","Chỉ khi có người đứng cạnh máy","Không bao giờ, nó chỉ là lời cảnh báo"],"h1":"Máy này hoạt động giống như một người cầm biển STOP.","h2":"Ở Oregon, bạn phải dừng tại máy điều khiển giao thông tự động khi đèn đỏ sáng và thanh chắn hạ xuống, và đi khi đèn vàng nhấp nháy và thanh chắn nâng lên.","p":"Đúng. Đèn đỏ và thanh chắn hạ xuống nghĩa là dừng lại."},"tl":{"q":"Sa Oregon, may automated flagger na makina sa work zone na may mga ilaw at gate arm. Kailan ka dapat huminto?","o":["Kapag kumikislap ang dilaw na ilaw at nakataas ang arm","Kapag nakabukas ang pulang ilaw at nakababa ang arm","Kapag may taong nakatayo lang sa tabi ng makina","Hindi kailanman, babala lang ito"],"h1":"Gumagana ang makina na parang taong may hawak na STOP sign.","h2":"Sa Oregon, dapat kang huminto sa automated flagger kapag nakabukas ang pulang ilaw nito at nakababa ang arm, at umandar kapag kumikislap ang dilaw na ilaw at nakataas ang arm.","p":"Tama. Pulang ilaw at nakababang arm ay nangangahulugang huminto."},"ar":{"q":"في Oregon، في منطقة أعمال طرق جهاز آلي لتنظيم المرور له أضواء وذراع حاجز. متى يجب أن تتوقف؟","o":["عندما يومض الضوء الأصفر ويكون الذراع مرفوعًا","عندما يكون الضوء الأحمر مضاءً ويكون الذراع منخفضًا","فقط عندما يقف شخص بجانب الجهاز","أبدًا، إنه تحذير فقط"],"h1":"الجهاز يعمل مثل شخص يحمل لافتة STOP.","h2":"في Oregon يجب أن تتوقف عند جهاز تنظيم المرور الآلي عندما يكون ضوؤه الأحمر مضاءً وذراعه منخفضًا، وتتحرك عندما يومض الضوء الأصفر ويكون الذراع مرفوعًا.","p":"صحيح. الضوء الأحمر والذراع المنخفض يعنيان التوقف."},"ref":{"doc":"OR","page":59}},{"id":"or-042","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, a person riding a horse ahead of you raises a hand. What does it mean, and what do you do?","o":["They want you to pass, so speed up","They are saying hello, so wave back","The horse is frightened, so stop if you can do it safely","They are turning, so honk to warn them"],"h1":"Think about what a loud car can do to a nervous animal.","h2":"In Oregon a raised hand from a horse rider means the animal is frightened, so you must stop unless stopping would cause a crash.","p":"Right. A raised hand means a scared horse, so stop and stay quiet."},"es":{"q":"En Oregon, una persona que va a caballo delante de usted levanta la mano. ¿Qué significa y qué hace usted?","o":["Quiere que usted pase, así que acelera","Lo está saludando, así que usted la saluda","El caballo está asustado, así que se detiene si puede hacerlo con seguridad","Va a dar vuelta, así que toca la bocina para avisarle"],"h1":"Piense en lo que un auto ruidoso le puede hacer a un animal nervioso.","h2":"En Oregon, una mano levantada de quien va a caballo significa que el animal está asustado, y usted debe detenerse a menos que eso cause un choque.","p":"Correcto. Una mano levantada significa un caballo asustado: deténgase y no haga ruido."},"zh":{"q":"在 Oregon，前面一个骑马的人举起一只手。这是什么意思？你该怎么做？","o":["他们想让你超车，所以加速","他们在打招呼，所以向他们挥手","马受惊了，所以在安全的情况下停车","他们要转弯，所以按喇叭提醒他们"],"h1":"想一想很吵的汽车会对一只紧张的动物造成什么影响。","h2":"在 Oregon，骑马的人举起手表示马受惊了，所以你必须停车，除非停车会造成车祸。","p":"对。举手表示马受惊了，所以要停车并保持安静。"},"vi":{"q":"Ở Oregon, một người cưỡi ngựa phía trước bạn giơ tay lên. Điều đó có nghĩa là gì, và bạn làm gì?","o":["Họ muốn bạn vượt, nên chạy nhanh lên","Họ đang chào, nên vẫy tay lại","Con ngựa đang sợ, nên dừng lại nếu bạn có thể dừng an toàn","Họ đang rẽ, nên bóp còi để cảnh báo họ"],"h1":"Hãy nghĩ xem một chiếc xe ồn ào có thể làm gì với một con vật đang căng thẳng.","h2":"Ở Oregon, người cưỡi ngựa giơ tay lên nghĩa là con vật đang sợ, nên bạn phải dừng lại, trừ khi dừng lại sẽ gây tai nạn.","p":"Đúng. Giơ tay nghĩa là ngựa đang sợ, nên hãy dừng lại và giữ yên lặng."},"tl":{"q":"Sa Oregon, nagtaas ng kamay ang taong nakasakay sa kabayo sa unahan mo. Ano ang ibig sabihin nito, at ano ang gagawin mo?","o":["Gusto nilang lumampas ka, kaya bumilis ka","Bumabati sila, kaya kumaway ka rin","Natatakot ang kabayo, kaya huminto kung ligtas mo itong magagawa","Liliko sila, kaya bumusina para babalaan sila"],"h1":"Isipin kung ano ang puwedeng gawin ng maingay na kotse sa isang kabadong hayop.","h2":"Sa Oregon, ang nakataas na kamay ng nakasakay sa kabayo ay nangangahulugang natatakot ang hayop, kaya dapat kang huminto maliban kung magdudulot ng aksidente ang paghinto.","p":"Tama. Ang nakataas na kamay ay nangangahulugang takot ang kabayo, kaya huminto at manatiling tahimik."},"ar":{"q":"في Oregon، شخص يركب حصانًا أمامك يرفع يده. ماذا يعني ذلك، وماذا تفعل؟","o":["يريدك أن تتجاوزه، فأسرِع","إنه يسلّم عليك، فلوّح له","الحصان خائف، فتوقف إذا استطعت أن تتوقف بأمان","إنه سينعطف، فاستخدم البوق لتحذيره"],"h1":"فكّر ماذا يمكن أن تفعل سيارة عالية الصوت بحيوان متوتر.","h2":"في Oregon، رفع اليد من راكب الحصان يعني أن الحيوان خائف، لذلك يجب أن تتوقف إلا إذا كان التوقف سيسبب حادثًا.","p":"صحيح. رفع اليد يعني أن الحصان خائف، فتوقف وابقَ هادئًا."},"ref":{"doc":"OR","page":75}},{"id":"or-043","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, how many times in total may you take the knowledge test online before you must take it at a DMV office?","o":["One time","Two times","Three times","Four times"],"h1":"You may try twice in one day, and the total is double that.","h2":"In Oregon you may take the knowledge test online four times in total; after that you must test at a DMV office.","p":"Right. Oregon allows four online tries, then you go to a DMV office."},"es":{"q":"En Oregon, ¿cuántas veces en total puede tomar el examen de conocimientos en línea antes de tener que tomarlo en una oficina del DMV?","o":["Una vez","Dos veces","Tres veces","Cuatro veces"],"h1":"Puede intentarlo dos veces en un día, y el total es el doble.","h2":"En Oregon usted puede tomar el examen de conocimientos en línea cuatro veces en total; después debe tomarlo en una oficina del DMV.","p":"Correcto. Oregon permite cuatro intentos en línea; después usted va a una oficina del DMV."},"zh":{"q":"在 Oregon，你总共可以在网上考几次笔试，之后就必须去 DMV 办公室考？","o":["一次","两次","三次","四次"],"h1":"你一天可以考两次，总次数是它的两倍。","h2":"在 Oregon，你总共可以在网上考四次笔试；之后你必须去 DMV 办公室考。","p":"对。Oregon 允许在网上考四次，之后就要去 DMV 办公室。"},"vi":{"q":"Ở Oregon, tổng cộng bạn được thi lý thuyết trực tuyến bao nhiêu lần trước khi phải thi tại văn phòng DMV?","o":["Một lần","Hai lần","Ba lần","Bốn lần"],"h1":"Bạn được thử hai lần trong một ngày, và tổng số là gấp đôi.","h2":"Ở Oregon, tổng cộng bạn được thi lý thuyết trực tuyến bốn lần; sau đó bạn phải thi tại văn phòng DMV.","p":"Đúng. Oregon cho thi trực tuyến bốn lần, sau đó bạn đến văn phòng DMV."},"tl":{"q":"Sa Oregon, ilang beses ka sa kabuuan puwedeng kumuha ng knowledge test online bago ka kailangang kumuha nito sa DMV office?","o":["Isang beses","Dalawang beses","Tatlong beses","Apat na beses"],"h1":"Puwede kang sumubok nang dalawang beses sa isang araw, at doble nito ang kabuuan.","h2":"Sa Oregon, puwede kang kumuha ng knowledge test online nang apat na beses sa kabuuan; pagkatapos noon, dapat kang mag-test sa DMV office.","p":"Tama. Apat na online na pagsubok ang pinapayagan ng Oregon, saka ka pupunta sa DMV office."},"ar":{"q":"في Oregon، كم مرة في المجموع يجوز لك أن تقدّم اختبار المعرفة عبر الإنترنت قبل أن يجب عليك تقديمه في مكتب DMV؟","o":["مرة واحدة","مرتان","ثلاث مرات","أربع مرات"],"h1":"يجوز لك أن تحاول مرتين في يوم واحد، والمجموع ضعف ذلك.","h2":"في Oregon يجوز لك أن تقدّم اختبار المعرفة عبر الإنترنت أربع مرات في المجموع؛ وبعد ذلك يجب أن تقدّمه في مكتب DMV.","p":"صحيح. Oregon تسمح بأربع محاولات عبر الإنترنت، ثم تذهب إلى مكتب DMV."},"ref":{"doc":"OR","page":3}},{"id":"or-044","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, you want to park across the street from the driveway of a fire station. How close may you park to it?","o":["No closer than 75 feet","No closer than 15 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"Across the street, the distance is much larger than on the same side.","h2":"In Oregon you may not park within 75 feet of a fire station driveway on the other side of the street.","p":"Right. Across from a fire station driveway, stay 75 feet away."},"es":{"q":"En Oregon, usted quiere estacionarse en el lado opuesto de la calle, frente a la entrada de una estación de bomberos. ¿A qué distancia mínima puede estacionarse?","o":["A no menos de 75 pies","A no menos de 15 pies","A no menos de 20 pies","A no menos de 50 pies"],"h1":"En el lado opuesto de la calle, la distancia es mucho mayor que en el mismo lado.","h2":"En Oregon no puede estacionarse a menos de 75 pies de la entrada de una estación de bomberos en el lado opuesto de la calle.","p":"Correcto. Frente a la entrada de una estación de bomberos, quédese a 75 pies."},"zh":{"q":"在 Oregon，你想把车停在消防站车道出口的街对面。你最近可以停在离它多远的地方？","o":["不能近于 75 英尺","不能近于 15 英尺","不能近于 20 英尺","不能近于 50 英尺"],"h1":"在街对面，这个距离比在同一边大很多。","h2":"在 Oregon，你不可以把车停在街对面离消防站车道出口 75 英尺以内的地方。","p":"对。在消防站车道出口的街对面，要离开 75 英尺。"},"vi":{"q":"Ở Oregon, bạn muốn đậu xe bên kia đường, đối diện lối ra vào của trạm cứu hỏa. Bạn được đậu gần nhất là bao nhiêu?","o":["Không gần hơn 75 feet","Không gần hơn 15 feet","Không gần hơn 20 feet","Không gần hơn 50 feet"],"h1":"Ở bên kia đường, khoảng cách lớn hơn nhiều so với cùng một bên.","h2":"Ở Oregon, bạn không được đậu xe trong vòng 75 feet tính từ lối ra vào của trạm cứu hỏa ở bên kia đường.","p":"Đúng. Đối diện lối ra vào trạm cứu hỏa, hãy cách xa 75 feet."},"tl":{"q":"Sa Oregon, gusto mong pumarada sa kabilang panig ng kalye mula sa driveway ng fire station. Gaano kalapit ka puwedeng pumarada rito?","o":["Hindi lalapit sa 75 feet","Hindi lalapit sa 15 feet","Hindi lalapit sa 20 feet","Hindi lalapit sa 50 feet"],"h1":"Sa kabilang panig ng kalye, mas malaki ang layo kaysa sa parehong panig.","h2":"Sa Oregon, hindi ka puwedeng pumarada sa loob ng 75 feet mula sa driveway ng fire station sa kabilang panig ng kalye.","p":"Tama. Sa tapat ng driveway ng fire station, lumayo nang 75 feet."},"ar":{"q":"في Oregon، تريد أن توقف سيارتك في الجهة المقابلة من الشارع لمدخل محطة إطفاء. كم يجوز لك أن تقترب منه؟","o":["ليس أقرب من 75 قدمًا","ليس أقرب من 15 قدمًا","ليس أقرب من 20 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"في الجهة المقابلة من الشارع تكون المسافة أكبر بكثير منها في الجهة نفسها.","h2":"في Oregon لا يجوز لك أن توقف سيارتك على بعد أقل من 75 قدمًا من مدخل محطة إطفاء في الجهة الأخرى من الشارع.","p":"صحيح. مقابل مدخل محطة الإطفاء، ابقَ على بعد 75 قدمًا."},"ref":{"doc":"OR","page":71}},{"id":"or-045","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, until what age must a baby ride in a rear-facing car seat?","o":["Until age 1","Until age 2","Until age 4","Until age 8"],"h1":"It is past the first birthday.","h2":"In Oregon an infant must ride facing the rear until age 2.","p":"Right. In Oregon, babies ride rear-facing until they turn 2."},"es":{"q":"En Oregon, ¿hasta qué edad debe viajar un bebé en un asiento de seguridad mirando hacia atrás?","o":["Hasta 1 año","Hasta 2 años","Hasta 4 años","Hasta 8 años"],"h1":"Es después del primer cumpleaños.","h2":"En Oregon un bebé debe viajar mirando hacia atrás hasta los 2 años.","p":"Correcto. En Oregon los bebés viajan mirando hacia atrás hasta cumplir 2 años."},"zh":{"q":"在 Oregon，婴儿必须坐在面朝后的儿童座椅里，直到几岁？","o":["直到 1 岁","直到 2 岁","直到 4 岁","直到 8 岁"],"h1":"是在一周岁生日之后。","h2":"在 Oregon，婴儿必须面朝后坐，直到 2 岁。","p":"对。在 Oregon，婴儿面朝后坐到满 2 岁。"},"vi":{"q":"Ở Oregon, em bé phải ngồi ghế xe quay mặt về phía sau cho đến bao nhiêu tuổi?","o":["Cho đến 1 tuổi","Cho đến 2 tuổi","Cho đến 4 tuổi","Cho đến 8 tuổi"],"h1":"Đó là sau sinh nhật đầu tiên.","h2":"Ở Oregon, trẻ sơ sinh phải ngồi quay mặt về phía sau cho đến 2 tuổi.","p":"Đúng. Ở Oregon, em bé ngồi quay mặt về phía sau cho đến khi tròn 2 tuổi."},"tl":{"q":"Sa Oregon, hanggang anong edad dapat nakasakay ang sanggol sa rear-facing na car seat?","o":["Hanggang 1 taong gulang","Hanggang 2 taong gulang","Hanggang 4 na taong gulang","Hanggang 8 taong gulang"],"h1":"Lampas ito sa unang kaarawan.","h2":"Sa Oregon, dapat nakaharap sa likod ang sanggol hanggang 2 taong gulang.","p":"Tama. Sa Oregon, nakaharap sa likod ang mga sanggol hanggang mag-2 taon sila."},"ar":{"q":"في Oregon، حتى أي عمر يجب أن يجلس الطفل الرضيع في مقعد سيارة مواجه للخلف؟","o":["حتى عمر سنة واحدة","حتى عمر سنتين","حتى عمر 4 سنوات","حتى عمر 8 سنوات"],"h1":"هو بعد عيد الميلاد الأول.","h2":"في Oregon يجب أن يجلس الطفل الرضيع مواجهًا للخلف حتى عمر سنتين.","p":"صحيح. في Oregon يجلس الأطفال الرضّع مواجهين للخلف حتى يبلغوا سنتين."},"ref":{"doc":"OR","page":74}},{"id":"or-046","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, a car is coming toward you at night and you must dim your headlights. What must you do with your fog lights?","o":["Leave them on to help you see","Switch them on instead of the headlights","Turn them off","Flash them once as a greeting"],"h1":"Extra lights make it hard for the other driver to see.","h2":"In Oregon, whenever you must dim your headlights, your fog lights and other extra lights must be off.","p":"Right. When you dim your headlights, the fog lights go off too."},"es":{"q":"En Oregon, de noche viene un auto de frente y usted debe bajar las luces. ¿Qué debe hacer con las luces antiniebla?","o":["Dejarlas encendidas para ver mejor","Encenderlas en lugar de los faros","Apagarlas","Hacer un cambio de luces como saludo"],"h1":"Las luces adicionales le dificultan la vista al otro conductor.","h2":"En Oregon, siempre que deba bajar las luces, las luces antiniebla y otras luces adicionales deben estar apagadas.","p":"Correcto. Cuando baja las luces, también apaga las luces antiniebla."},"zh":{"q":"在 Oregon，晚上有一辆车朝你开过来，你必须把大灯调暗。你的雾灯必须怎么处理？","o":["开着，帮助你看清楚","打开雾灯来代替大灯","关掉","闪一下打招呼"],"h1":"多余的灯会让对面的司机很难看清。","h2":"在 Oregon，每当你必须把大灯调暗时，你的雾灯和其他额外的灯都必须关掉。","p":"对。把大灯调暗时，雾灯也要关掉。"},"vi":{"q":"Ở Oregon, ban đêm có một xe đang chạy về phía bạn và bạn phải chuyển sang đèn cốt. Bạn phải làm gì với đèn sương mù?","o":["Để đèn sáng để giúp bạn nhìn","Bật đèn sương mù thay cho đèn pha","Tắt đèn sương mù","Nháy đèn một lần để chào"],"h1":"Đèn phụ làm tài xế kia khó nhìn thấy.","h2":"Ở Oregon, bất cứ khi nào bạn phải chuyển sang đèn cốt, đèn sương mù và các đèn phụ khác phải tắt.","p":"Đúng. Khi bạn chuyển sang đèn cốt, đèn sương mù cũng phải tắt."},"tl":{"q":"Sa Oregon, may kotseng papalapit sa iyo sa gabi at kailangan mong i-dim ang headlights mo. Ano ang dapat mong gawin sa fog lights mo?","o":["Iwanang bukas para makatulong sa iyong makakita","Buksan ang mga ito kapalit ng headlights","Patayin ang mga ito","Ikislap nang isang beses bilang pagbati"],"h1":"Pinahihirapan ng dagdag na ilaw ang ibang driver na makakita.","h2":"Sa Oregon, tuwing kailangan mong i-dim ang headlights mo, dapat nakapatay ang fog lights mo at iba pang dagdag na ilaw.","p":"Tama. Kapag dinim mo ang headlights, patayin din ang fog lights."},"ar":{"q":"في Oregon، سيارة تقترب منك في الليل ويجب أن تخفّض أضواءك الأمامية. ماذا يجب أن تفعل بأضواء الضباب؟","o":["اتركها مضاءة لتساعدك على الرؤية","شغّلها بدلًا من الأضواء الأمامية","أطفئها","اومض بها مرة واحدة للتحية"],"h1":"الأضواء الإضافية تجعل الرؤية صعبة على السائق الآخر.","h2":"في Oregon، كلما وجب عليك أن تخفّض أضواءك الأمامية، يجب أن تكون أضواء الضباب والأضواء الإضافية الأخرى مطفأة.","p":"صحيح. عندما تخفّض أضواءك الأمامية، تُطفأ أضواء الضباب أيضًا."},"ref":{"doc":"OR","page":76}},{"id":"or-047","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, it is against the law to play your car's music so loud that someone can hear it how far away?","o":["10 feet","25 feet","100 feet","50 feet"],"h1":"It is a little more than the length of three cars.","h2":"In Oregon it is illegal to play a radio or sound system so loud that it can be heard 50 feet from your car.","p":"Right. In Oregon, music heard 50 feet away is too loud."},"es":{"q":"En Oregon, es ilegal poner la música del auto tan fuerte que se oiga desde cierta distancia. ¿Desde qué distancia?","o":["10 pies","25 pies","100 pies","50 pies"],"h1":"Es un poco más que el largo de tres autos.","h2":"En Oregon es ilegal poner la radio o un equipo de sonido tan fuerte que se oiga a 50 pies de su auto.","p":"Correcto. En Oregon, la música que se oye a 50 pies está demasiado fuerte."},"zh":{"q":"在 Oregon，车里的音乐开得太大声，让多远以外的人都能听到，就是违法的？","o":["10 英尺","25 英尺","100 英尺","50 英尺"],"h1":"它比三辆车的长度多一点。","h2":"在 Oregon，把收音机或音响开得太大声，让离你的车 50 英尺远的人都能听到，是违法的。","p":"对。在 Oregon，50 英尺外能听到的音乐就太大声了。"},"vi":{"q":"Ở Oregon, mở nhạc trong xe lớn đến mức người ở cách bao xa cũng nghe được thì là phạm luật?","o":["10 feet","25 feet","100 feet","50 feet"],"h1":"Đó là hơn chiều dài của ba chiếc xe một chút.","h2":"Ở Oregon, mở radio hoặc dàn âm thanh lớn đến mức nghe được từ cách xe bạn 50 feet là phạm luật.","p":"Đúng. Ở Oregon, nhạc nghe được từ 50 feet là quá lớn."},"tl":{"q":"Sa Oregon, labag sa batas na patugtugin nang napakalakas ang musika sa kotse mo na naririnig ito ng tao mula sa gaano kalayo?","o":["10 feet","25 feet","100 feet","50 feet"],"h1":"Medyo mas mahaba ito sa haba ng tatlong kotse.","h2":"Sa Oregon, labag sa batas na patugtugin ang radyo o sound system nang napakalakas na naririnig ito 50 feet mula sa kotse mo.","p":"Tama. Sa Oregon, masyadong malakas ang musikang naririnig 50 feet ang layo."},"ar":{"q":"في Oregon، من المخالف للقانون أن تشغّل الموسيقى في سيارتك بصوت عالٍ لدرجة أن شخصًا يسمعها من أي مسافة؟","o":["10 أقدام","25 قدمًا","100 قدم","50 قدمًا"],"h1":"هي أكثر قليلًا من طول ثلاث سيارات.","h2":"في Oregon من المخالف للقانون أن تشغّل الراديو أو نظام الصوت بصوت عالٍ لدرجة أنه يُسمع على بعد 50 قدمًا من سيارتك.","p":"صحيح. في Oregon، الموسيقى التي تُسمع على بعد 50 قدمًا عالية جدًا."},"ref":{"doc":"OR","page":80}},{"id":"or-048","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, who is not allowed by law to ride in the open bed of a pickup truck?","o":["Anyone under 18","Anyone under 12","Only children under 8","Anyone without a seat belt, but only on highways"],"h1":"The age is the same as the end of the teen phone ban.","h2":"In Oregon the law forbids anyone under 18 from riding in a pickup bed or on any outside part of a vehicle, and no one of any age should ride there.","p":"Right. In Oregon no one under 18 may ride in a pickup bed."},"es":{"q":"En Oregon, ¿a quién le prohíbe la ley viajar en la caja abierta de una camioneta pickup?","o":["A cualquier menor de 18 años","A cualquier menor de 12 años","Solo a los niños menores de 8 años","A cualquiera sin cinturón, pero solo en carreteras"],"h1":"Es la misma edad en que termina la prohibición del celular para jóvenes.","h2":"En Oregon la ley prohíbe que un menor de 18 años viaje en la caja de una pickup o en cualquier parte exterior de un vehículo, y nadie de ninguna edad debería viajar ahí.","p":"Correcto. En Oregon ningún menor de 18 años puede viajar en la caja de una pickup."},"zh":{"q":"在 Oregon，法律不允许谁坐在皮卡车敞开的后车斗里？","o":["任何未满 18 岁的人","任何未满 12 岁的人","只有未满 8 岁的儿童","任何没有系安全带的人，但只在公路上"],"h1":"这个年龄和青少年禁止开车用手机的结束年龄相同。","h2":"在 Oregon，法律禁止任何未满 18 岁的人坐在皮卡车后车斗里或车辆外面的任何部位，而且任何年龄的人都不应该坐在那里。","p":"对。在 Oregon，未满 18 岁的人不可以坐在皮卡车后车斗里。"},"vi":{"q":"Ở Oregon, theo luật, ai không được ngồi ở thùng sau để trống của xe bán tải?","o":["Bất kỳ ai dưới 18 tuổi","Bất kỳ ai dưới 12 tuổi","Chỉ trẻ em dưới 8 tuổi","Bất kỳ ai không có dây an toàn, nhưng chỉ trên xa lộ"],"h1":"Tuổi này giống với tuổi kết thúc lệnh cấm dùng điện thoại cho thanh thiếu niên.","h2":"Ở Oregon, luật cấm bất kỳ ai dưới 18 tuổi ngồi trong thùng sau xe bán tải hoặc ở bất kỳ phần nào bên ngoài xe, và không ai ở bất kỳ tuổi nào nên ngồi ở đó.","p":"Đúng. Ở Oregon, không ai dưới 18 tuổi được ngồi trong thùng sau xe bán tải."},"tl":{"q":"Sa Oregon, sino ang hindi pinapayagan ng batas na sumakay sa bukas na likod (bed) ng pickup truck?","o":["Sinumang wala pang 18","Sinumang wala pang 12","Mga batang wala pang 8 lang","Sinumang walang seat belt, pero sa highway lang"],"h1":"Pareho ang edad na ito sa pagtatapos ng pagbabawal sa cellphone para sa mga teen.","h2":"Sa Oregon, ipinagbabawal ng batas na sumakay ang sinumang wala pang 18 sa bed ng pickup o sa anumang bahagi sa labas ng sasakyan, at walang sinuman sa anumang edad ang dapat sumakay doon.","p":"Tama. Sa Oregon, walang wala pang 18 ang puwedeng sumakay sa bed ng pickup."},"ar":{"q":"في Oregon، من الذي لا يسمح له القانون بالركوب في الصندوق الخلفي المكشوف لشاحنة بيك أب؟","o":["أي شخص عمره أقل من 18 سنة","أي شخص عمره أقل من 12 سنة","الأطفال الذين أعمارهم أقل من 8 سنوات فقط","أي شخص بدون حزام أمان، لكن على الطرق السريعة فقط"],"h1":"هذا العمر هو نفس عمر انتهاء منع المراهقين من استخدام الهاتف.","h2":"في Oregon يمنع القانون أي شخص عمره أقل من 18 سنة من الركوب في صندوق شاحنة البيك أب أو على أي جزء خارجي من المركبة، ويجب ألّا يركب هناك أحد من أي عمر.","p":"صحيح. في Oregon لا يجوز لأحد عمره أقل من 18 سنة أن يركب في صندوق البيك أب."},"ref":{"doc":"OR","page":84}},{"id":"or-049","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, what is the minimum Personal Injury Protection (PIP) coverage a car owner must carry for each person?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"It is less than the bodily injury minimum for one person.","h2":"In Oregon a car owner must carry at least $15,000 of Personal Injury Protection for each person.","p":"Right. Oregon PIP is at least $15,000 per person."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima de Protección contra Lesiones Personales (PIP) que debe tener el dueño de un auto por cada persona?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"Es menos que el mínimo de lesiones corporales para una persona.","h2":"En Oregon el dueño de un auto debe tener al menos $15,000 de Protección contra Lesiones Personales por cada persona.","p":"Correcto. El PIP en Oregon es de al menos $15,000 por persona."},"zh":{"q":"在 Oregon，车主必须为每个人购买的人身伤害保障（Personal Injury Protection, PIP）最低是多少？","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"它比每个人的人身伤害最低保额少。","h2":"在 Oregon，车主必须为每个人购买至少 $15,000 的人身伤害保障（PIP）。","p":"对。Oregon 的 PIP 至少是每人 $15,000。"},"vi":{"q":"Ở Oregon, mức bảo hiểm thương tích cá nhân (Personal Injury Protection, PIP) tối thiểu mà chủ xe phải có cho mỗi người là bao nhiêu?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"Nó ít hơn mức tối thiểu cho thương tích thân thể của một người.","h2":"Ở Oregon, chủ xe phải có ít nhất $15,000 bảo hiểm thương tích cá nhân (PIP) cho mỗi người.","p":"Đúng. PIP ở Oregon ít nhất là $15,000 cho mỗi người."},"tl":{"q":"Sa Oregon, ano ang pinakamababang Personal Injury Protection (PIP) coverage na dapat mayroon ang may-ari ng kotse para sa bawat tao?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"Mas mababa ito sa minimum para sa bodily injury ng isang tao.","h2":"Sa Oregon, dapat mayroon ang may-ari ng kotse ng hindi bababa sa $15,000 na Personal Injury Protection para sa bawat tao.","p":"Tama. Ang PIP sa Oregon ay hindi bababa sa $15,000 bawat tao."},"ar":{"q":"في Oregon، ما الحدّ الأدنى لتغطية الحماية من الإصابات الشخصية (Personal Injury Protection, PIP) التي يجب أن يحملها مالك السيارة لكل شخص؟","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"هو أقل من الحدّ الأدنى لتغطية الإصابات الجسدية لشخص واحد.","h2":"في Oregon يجب أن يحمل مالك السيارة تغطية حماية من الإصابات الشخصية (PIP) لا تقل عن $15,000 لكل شخص.","p":"صحيح. تغطية PIP في Oregon لا تقل عن $15,000 لكل شخص."},"ref":{"doc":"OR","page":93}},{"id":"or-050","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, a city bus at the curb signals to pull back into your lane, and a YIELD sign is flashing on its back. What must you do?","o":["Speed up and pass before it moves","Honk so the driver waits for you","Yield and let the bus pull into the lane","Change lanes without slowing down"],"h1":"The flashing sign on the bus tells you what to do.","h2":"In Oregon you must yield to a transit bus that signals to re-enter traffic while the YIELD sign on its back is flashing.","p":"Right. In Oregon you let the bus back into the lane."},"es":{"q":"En Oregon, un autobús urbano junto a la acera señala que va a volver a su carril, y en su parte trasera parpadea una señal de YIELD (ceda el paso). ¿Qué debe hacer?","o":["Acelerar y pasar antes de que se mueva","Tocar la bocina para que el conductor lo espere","Ceder el paso y dejar que el autobús entre al carril","Cambiar de carril sin bajar la velocidad"],"h1":"La señal que parpadea en el autobús le dice qué hacer.","h2":"En Oregon usted debe ceder el paso a un autobús de transporte público que señala para volver al tráfico mientras parpadea la señal de YIELD en su parte trasera.","p":"Correcto. En Oregon usted deja que el autobús vuelva al carril."},"zh":{"q":"在 Oregon，一辆停在路边的公交车打信号要开回你的车道，车后面的 YIELD（让行）标志在闪烁。你必须怎么做？","o":["加速，在它开动前超过去","按喇叭让司机等你","让行，让公交车开进车道","不减速，直接换车道"],"h1":"公交车上闪烁的标志告诉你该怎么做。","h2":"在 Oregon，当公交车打信号要重新开进车流、车后的 YIELD 标志在闪烁时，你必须给它让行。","p":"对。在 Oregon，你要让公交车开回车道。"},"vi":{"q":"Ở Oregon, một xe buýt thành phố đang đậu sát lề bật tín hiệu để quay lại làn của bạn, và biển YIELD (nhường đường) phía sau xe đang nhấp nháy. Bạn phải làm gì?","o":["Tăng tốc và vượt trước khi nó chạy","Bóp còi để tài xế chờ bạn","Nhường đường và để xe buýt vào làn","Đổi làn mà không giảm tốc độ"],"h1":"Biển báo nhấp nháy trên xe buýt cho bạn biết phải làm gì.","h2":"Ở Oregon, bạn phải nhường đường cho xe buýt công cộng đang bật tín hiệu để quay lại dòng xe khi biển YIELD phía sau xe đang nhấp nháy.","p":"Đúng. Ở Oregon, bạn để xe buýt quay lại làn."},"tl":{"q":"Sa Oregon, nagsi-signal ang city bus na nasa gilid ng kalsada na babalik ito sa lane mo, at kumikislap ang YIELD sign sa likod nito. Ano ang dapat mong gawin?","o":["Bumilis at lumampas bago ito umandar","Bumusina para hintayin ka ng driver","Magbigay-daan at hayaang pumasok ang bus sa lane","Lumipat ng lane nang hindi bumabagal"],"h1":"Sinasabi sa iyo ng kumikislap na sign sa bus kung ano ang gagawin.","h2":"Sa Oregon, dapat kang magbigay-daan sa transit bus na nagsi-signal na babalik sa trapiko habang kumikislap ang YIELD sign sa likod nito.","p":"Tama. Sa Oregon, hayaan mong bumalik ang bus sa lane."},"ar":{"q":"في Oregon، حافلة مدينة متوقفة عند الرصيف تعطي إشارة للعودة إلى مسارك، ولافتة YIELD (أفسح الطريق) تومض على ظهرها. ماذا يجب أن تفعل؟","o":["أسرِع وتجاوزها قبل أن تتحرك","استخدم البوق لكي ينتظرك السائق","أفسح الطريق ودع الحافلة تدخل المسار","غيّر المسار بدون أن تخفّف السرعة"],"h1":"اللافتة الوامضة على الحافلة تخبرك بما يجب أن تفعل.","h2":"في Oregon يجب أن تفسح الطريق لحافلة النقل العام التي تعطي إشارة للعودة إلى حركة المرور بينما تومض لافتة YIELD على ظهرها.","p":"صحيح. في Oregon تدع الحافلة تعود إلى المسار."},"ref":{"doc":"OR","page":56}},{"id":"or-051","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, you are caught cheating on the knowledge test at a DMV office. How long must you wait before you may test again?","o":["Until the next business day","30 days","90 days","1 year"],"h1":"It is about three months.","h2":"In Oregon, if you are caught cheating on a knowledge test, you fail and may not test again for 90 days.","p":"Right. Cheating means you fail and wait 90 days to test again."},"es":{"q":"En Oregon, lo descubren haciendo trampa en el examen de conocimientos en una oficina del DMV. ¿Cuánto tiempo debe esperar para volver a hacer el examen?","o":["Hasta el siguiente día hábil","30 días","90 días","1 año"],"h1":"Son unos tres meses.","h2":"En Oregon, si lo descubren haciendo trampa en un examen de conocimientos, usted reprueba y no puede volver a hacerlo durante 90 días.","p":"Correcto. Si hace trampa, reprueba y espera 90 días para volver a hacer el examen."},"ref":{"doc":"OR","page":2}},{"id":"or-052","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, which of these may you use during the knowledge test at a DMV office, if staff give permission?","o":["A paper dictionary that translates a foreign language","Your phone with a translation app","The Oregon Driver Manual","Notes you wrote at home"],"h1":"It is made of paper and only helps with words in another language.","h2":"In Oregon, with permission, you may use a paper foreign language translation dictionary during the knowledge test, but no phone, manual or notes.","p":"Right. With permission, a paper translation dictionary is allowed."},"es":{"q":"En Oregon, ¿cuál de estas cosas puede usar durante el examen de conocimientos en una oficina del DMV, si el personal le da permiso?","o":["Un diccionario de papel que traduce un idioma extranjero","Su teléfono con una aplicación de traducción","El Manual del Conductor de Oregon","Notas que escribió en casa"],"h1":"Es de papel y solo ayuda con palabras de otro idioma.","h2":"En Oregon, con permiso, usted puede usar un diccionario de traducción de papel durante el examen de conocimientos, pero no un teléfono, el manual ni notas.","p":"Correcto. Con permiso, se permite un diccionario de traducción de papel."},"ref":{"doc":"OR","page":2}},{"id":"or-053","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you are 16 and want to take the knowledge test online. Who must watch over the test?","o":["No one, if your webcam is on","A DMV employee on a video call","Any friend who is 18 or older","A proctor who is over 21"],"h1":"An adult must supervise anyone under 18.","h2":"In Oregon, if you are under 18 and take the knowledge test online, a proctor over 21 years of age must supervise the test.","p":"Right. Under 18, an online test needs a proctor over 21."},"es":{"q":"En Oregon, usted tiene 16 años y quiere hacer el examen de conocimientos en línea. ¿Quién debe supervisar el examen?","o":["Nadie, si su cámara web está encendida","Un empleado del DMV por videollamada","Cualquier amigo de 18 años o más","Un supervisor (proctor) mayor de 21 años"],"h1":"Un adulto debe supervisar a cualquier persona menor de 18 años.","h2":"En Oregon, si usted es menor de 18 años y hace el examen de conocimientos en línea, un supervisor (proctor) mayor de 21 años debe supervisar el examen.","p":"Correcto. Si es menor de 18, el examen en línea necesita un supervisor mayor de 21 años."},"ref":{"doc":"OR","page":3}},{"id":"or-054","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, you are moving from another state. When may DMV waive your drive test?","o":["Never; every new resident takes the drive test","When you give up an out-of-state license that is valid or expired less than one year","When your out-of-state license expired less than five years ago","Only if you are over 25"],"h1":"Your old license must be current or only recently expired.","h2":"In Oregon, DMV may waive the drive test for a new resident who gives up an out-of-state license that is valid or expired less than one year.","p":"Right. A valid license, or one expired less than a year, can mean no drive test."},"es":{"q":"En Oregon, usted se muda desde otro estado. ¿Cuándo puede el DMV eximirlo del examen de manejo?","o":["Nunca; todo nuevo residente hace el examen de manejo","Cuando entrega una licencia de otro estado vigente o vencida hace menos de un año","Cuando su licencia de otro estado venció hace menos de cinco años","Solo si tiene más de 25 años"],"h1":"Su licencia anterior debe estar vigente o haber vencido hace poco.","h2":"En Oregon, el DMV puede eximir del examen de manejo a un nuevo residente que entrega una licencia de otro estado vigente o vencida hace menos de un año.","p":"Correcto. Una licencia vigente, o vencida hace menos de un año, puede evitarle el examen de manejo."},"ref":{"doc":"OR","page":3}},{"id":"or-055","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you did not pass your drive test. When is the soonest you may take it again?","o":["The next business day","Later the same day","After 7 days","After 30 days"],"h1":"You cannot retake it the same day.","h2":"In Oregon, if you fail the drive test, you must wait until the next business day before you take it again.","p":"Right. After a failed drive test, wait until the next business day."},"es":{"q":"En Oregon, usted no pasó el examen de manejo. ¿Cuándo es lo más pronto que puede volver a hacerlo?","o":["El siguiente día hábil","Más tarde el mismo día","Después de 7 días","Después de 30 días"],"h1":"No puede repetirlo el mismo día.","h2":"En Oregon, si reprueba el examen de manejo, debe esperar hasta el siguiente día hábil para volver a hacerlo.","p":"Correcto. Después de reprobar el examen de manejo, espere hasta el siguiente día hábil."},"ref":{"doc":"OR","page":4}},{"id":"or-056","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, a Class C non-commercial license lets you drive a vehicle that weighs up to how much?","o":["10,000 pounds","16,000 pounds","26,000 pounds","40,000 pounds"],"h1":"It is the same weight where most commercial licenses begin.","h2":"In Oregon, a Class C non-commercial license lets you drive a vehicle of not more than 26,000 pounds.","p":"Right. Class C covers vehicles up to 26,000 pounds."},"es":{"q":"En Oregon, ¿hasta cuánto puede pesar un vehículo que se maneja con una licencia no comercial Clase C?","o":["10,000 libras","16,000 libras","26,000 libras","40,000 libras"],"h1":"Es el mismo peso donde empiezan la mayoría de las licencias comerciales.","h2":"En Oregon, una licencia no comercial Clase C le permite manejar un vehículo de no más de 26,000 libras.","p":"Correcto. La Clase C cubre vehículos de hasta 26,000 libras."},"ref":{"doc":"OR","page":89}},{"id":"or-057","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you are 16 and applying for your first driving privilege. What must a parent or legal guardian certify about school?","o":["Your grades are a B average or higher","You have finished driver education at school","Nothing; school does not matter","You are enrolled in or attending school"],"h1":"DMV wants to know that you are still in school, or that you finished it.","h2":"In Oregon, when a person under 18 applies for a first driving privilege, a parent or legal guardian must certify that they are enrolled in or attending school, unless they show a high school diploma or GED.","p":"Right. A parent certifies that you are in school, or you show a diploma or GED."},"es":{"q":"En Oregon, usted tiene 16 años y solicita su primer privilegio de manejo. ¿Qué debe certificar su padre, madre o tutor legal sobre la escuela?","o":["Que sus calificaciones tienen promedio de B o más","Que terminó la educación vial en la escuela","Nada; la escuela no importa","Que usted está inscrito en la escuela o asiste a ella"],"h1":"El DMV quiere saber que usted sigue en la escuela, o que ya la terminó.","h2":"En Oregon, cuando una persona menor de 18 años solicita su primer privilegio de manejo, su padre, madre o tutor legal debe certificar que está inscrita en la escuela o asiste a ella, a menos que muestre un diploma de secundaria o un GED.","p":"Correcto. Su padre o tutor certifica que usted está en la escuela, o usted muestra un diploma o GED."},"ref":{"doc":"OR","page":89}},{"id":"or-058","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, you are 16. You held a learner's permit in another state for 4 months before moving here. Does that time count toward the 6-month permit rule?","o":["No, only an Oregon permit counts","Yes, time with an out-of-state permit counts","Only if you hold it for 12 months","Only if the other state is next to Oregon"],"h1":"The manual says permits from other states are not wasted.","h2":"In Oregon, time holding an out-of-state instruction permit does count toward the 6-month permit requirement for drivers under 18.","p":"Right. An out-of-state permit counts toward the 6 months."},"es":{"q":"En Oregon, usted tiene 16 años. Tuvo un permiso de aprendizaje en otro estado durante 4 meses antes de mudarse aquí. ¿Cuenta ese tiempo para la regla de 6 meses con permiso?","o":["No, solo cuenta un permiso de Oregon","Sí, el tiempo con un permiso de otro estado cuenta","Solo si lo tiene durante 12 meses","Solo si el otro estado está junto a Oregon"],"h1":"El manual dice que los permisos de otros estados no se pierden.","h2":"En Oregon, el tiempo con un permiso de instrucción de otro estado sí cuenta para el requisito de 6 meses con permiso para menores de 18 años.","p":"Correcto. Un permiso de otro estado cuenta para los 6 meses."},"ref":{"doc":"OR","page":90}},{"id":"or-059","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, what is the minimum bodily injury liability coverage for one crash in which two or more people are hurt or killed?","o":["$25,000","$40,000","$50,000","$100,000"],"h1":"It is double the minimum for one person.","h2":"In Oregon, a car owner must carry at least $50,000 of bodily injury coverage per crash when two or more people are hurt or killed.","p":"Right. The minimum is $50,000 per crash for two or more people."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima de responsabilidad por lesiones corporales en un choque en el que dos o más personas resultan heridas o muertas?","o":["$25,000","$40,000","$50,000","$100,000"],"h1":"Es el doble del mínimo para una persona.","h2":"En Oregon, el dueño de un auto debe tener al menos $50,000 de cobertura por lesiones corporales por choque cuando dos o más personas resultan heridas o muertas.","p":"Correcto. El mínimo es $50,000 por choque para dos o más personas."},"ref":{"doc":"OR","page":93}},{"id":"or-060","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you have a small crash. No one is hurt and both cars can still drive. What should you do?","o":["Leave the cars where they are until police arrive","Drive away and call the other driver later","Wait in your car in the lane","Stop, then move the cars out of the travel lanes"],"h1":"You may trade information somewhere safer.","h2":"In Oregon, after a crash with no injuries where the cars can be moved safely, you must stop and then move them out of the travel lanes as soon as possible.","p":"Right. Stop, then move the cars out of traffic and trade information there."},"es":{"q":"En Oregon, usted tiene un choque pequeño. Nadie está herido y los dos autos todavía pueden andar. ¿Qué debe hacer?","o":["Dejar los autos donde están hasta que llegue la policía","Irse y llamar al otro conductor después","Esperar dentro de su auto en el carril","Detenerse y luego sacar los autos de los carriles de circulación"],"h1":"Pueden intercambiar información en un lugar más seguro.","h2":"En Oregon, después de un choque sin heridos en el que los autos se pueden mover sin peligro, usted debe detenerse y luego sacarlos de los carriles de circulación lo antes posible.","p":"Correcto. Deténgase y luego saque los autos del tráfico para intercambiar información allí."},"ref":{"doc":"OR","page":93}},{"id":"or-061","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you hit a parked car with no one in it, and you cannot find the owner. What must you do?","o":["Leave a note with your name and address and what happened","Drive away, because no one saw it","Wait at the car for up to 24 hours","Call your insurance company only"],"h1":"The owner needs a way to reach you.","h2":"In Oregon, if you hit an unoccupied vehicle and cannot find the owner, you must leave a note with your name, address and a short description of what happened.","p":"Right. Leave a note with your name, address and what happened."},"es":{"q":"En Oregon, usted choca contra un auto estacionado sin nadie adentro y no puede encontrar al dueño. ¿Qué debe hacer?","o":["Dejar una nota con su nombre, su dirección y lo que pasó","Irse, porque nadie lo vio","Esperar junto al auto hasta 24 horas","Solo llamar a su compañía de seguros"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"En Oregon, si choca contra un vehículo sin ocupantes y no encuentra al dueño, debe dejar una nota con su nombre, su dirección y una breve descripción de lo que pasó.","p":"Correcto. Deje una nota con su nombre, su dirección y lo que pasó."},"ref":{"doc":"OR","page":94}},{"id":"or-062","scope":"OR","cat":"signals","sign":null,"c":2,"en":{"q":"In Oregon, you pass a sign that says SAFETY CORRIDOR. What does the manual ask you to do?","o":["Drive in the left lane only","Use your hazard lights","Turn on your lights","Stop at the next rest area"],"h1":"Safety corridors have more serious crashes than average. Help others see you.","h2":"In Oregon, a safety corridor is a stretch of highway with more deadly and serious crashes, and you should turn on your lights there.","p":"Right. In a safety corridor, turn on your lights."},"es":{"q":"En Oregon, usted pasa un letrero que dice SAFETY CORRIDOR (corredor de seguridad). ¿Qué le pide el manual que haga?","o":["Manejar solo en el carril izquierdo","Usar sus luces de emergencia","Encender sus luces","Detenerse en la próxima área de descanso"],"h1":"Los corredores de seguridad tienen más choques graves que el promedio. Ayude a que lo vean.","h2":"En Oregon, un corredor de seguridad es un tramo de carretera con más choques mortales y graves, y usted debe encender sus luces allí.","p":"Correcto. En un corredor de seguridad, encienda sus luces."},"ref":{"doc":"OR","page":13}},{"id":"or-063","scope":"OR","cat":"signals","sign":null,"c":3,"en":{"q":"In Oregon, the power is out and the traffic light at an intersection is completely dark. What should you do?","o":["Drive through if no one is coming","Treat it like a yield sign","Wait for a police officer to arrive","Stop as if there were stop signs in all directions"],"h1":"A dark signal works like a flashing red one.","h2":"In Oregon, when a traffic signal is dark, such as in a power failure, you must stop as if there were stop signs in all directions.","p":"Right. A dark signal means stop, like an all-way stop."},"es":{"q":"En Oregon, no hay electricidad y el semáforo de una intersección está completamente apagado. ¿Qué debe hacer?","o":["Pasar si no viene nadie","Tratarlo como un letrero de ceda el paso","Esperar a que llegue un policía","Detenerse como si hubiera letreros de alto en todas las direcciones"],"h1":"Un semáforo apagado funciona como una luz roja intermitente.","h2":"En Oregon, cuando un semáforo está apagado, por ejemplo en un corte de luz, usted debe detenerse como si hubiera letreros de alto en todas las direcciones.","p":"Correcto. Un semáforo apagado significa alto, como un alto en todas las direcciones."},"ref":{"doc":"OR","page":15}},{"id":"or-064","scope":"OR","cat":"signals","sign":null,"c":1,"en":{"q":"In Oregon, you are on a two-way road, stopped at a red light. You want to turn left onto a one-way road going left. What may you do?","o":["You must wait for a green light","Turn left on red after stopping and yielding to traffic and people walking","Turn left on red only if a sign allows it","Turn left on red without stopping"],"h1":"Turning onto a one-way road in its direction is treated like a right turn on red.","h2":"In Oregon, you may turn left on red from a two-way road onto a one-way road after you stop and yield to traffic and pedestrians, unless a sign forbids it.","p":"Right. From a two-way road onto a one-way road, you may turn left on red after a full stop and yielding."},"es":{"q":"En Oregon, usted está en una calle de doble sentido, detenido con luz roja. Quiere dar vuelta a la izquierda hacia una calle de un solo sentido que va a la izquierda. ¿Qué puede hacer?","o":["Debe esperar la luz verde","Dar vuelta a la izquierda con luz roja después de detenerse y ceder el paso al tráfico y a los peatones","Dar vuelta a la izquierda con luz roja solo si un letrero lo permite","Dar vuelta a la izquierda con luz roja sin detenerse"],"h1":"Entrar a una calle de un solo sentido en su dirección se trata como una vuelta a la derecha con luz roja.","h2":"En Oregon, usted puede dar vuelta a la izquierda con luz roja desde una calle de doble sentido hacia una calle de un solo sentido después de detenerse y ceder el paso al tráfico y a los peatones, a menos que un letrero lo prohíba.","p":"Correcto. De una calle de doble sentido a una de un solo sentido, puede dar vuelta a la izquierda con luz roja tras un alto total y ceder el paso."},"ref":{"doc":"OR","page":40}},{"id":"or-065","scope":"OR","cat":"signals","sign":null,"c":0,"en":{"q":"In Oregon, you are on a one-way road, stopped at a red light. You want to turn left onto a two-way road. What may you do?","o":["You must wait for a green light","Turn left on red after a full stop","Turn left on red if no cars are coming","Turn left on red only at night"],"h1":"On the road you are entering, cars come toward you from the left side.","h2":"In Oregon, you may not turn left on a red light from a one-way road onto a two-way road; you must wait for green.","p":"Right. A left turn onto a two-way road is never allowed on red."},"es":{"q":"En Oregon, usted está en una calle de un solo sentido, detenido con luz roja. Quiere dar vuelta a la izquierda hacia una calle de doble sentido. ¿Qué puede hacer?","o":["Debe esperar la luz verde","Dar vuelta a la izquierda con luz roja después de un alto total","Dar vuelta a la izquierda con luz roja si no vienen autos","Dar vuelta a la izquierda con luz roja solo de noche"],"h1":"En la calle a la que entra, los autos vienen hacia usted por el lado izquierdo.","h2":"En Oregon, no puede dar vuelta a la izquierda con luz roja desde una calle de un solo sentido hacia una calle de doble sentido; debe esperar la luz verde.","p":"Correcto. Nunca se permite dar vuelta a la izquierda con luz roja hacia una calle de doble sentido."},"ref":{"doc":"OR","page":40}},{"id":"or-066","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, an electronic black-and-white sign says SPEED LIMIT 45 because of fog. The usual limit is 65. What is true?","o":["It is only a suggestion","It applies only to trucks","You may drive 65 if you feel safe","It is the legal speed limit, and police may enforce it"],"h1":"Yellow electronic signs give advice. Black-and-white ones set the limit.","h2":"In Oregon, a black-and-white variable speed limit sign changes the legal limit for conditions, and police may enforce it like any other speed limit sign.","p":"Right. A black-and-white variable speed sign is the legal limit."},"es":{"q":"En Oregon, un letrero electrónico blanco y negro dice SPEED LIMIT 45 por la neblina. El límite normal es 65. ¿Qué es cierto?","o":["Es solo una sugerencia","Solo se aplica a los camiones","Puede manejar a 65 si se siente seguro","Es el límite legal de velocidad y la policía puede hacerlo cumplir"],"h1":"Los letreros electrónicos amarillos dan consejos. Los blanco y negro fijan el límite.","h2":"En Oregon, un letrero de límite de velocidad variable blanco y negro cambia el límite legal según las condiciones, y la policía puede hacerlo cumplir como cualquier otro letrero de límite de velocidad.","p":"Correcto. Un letrero variable blanco y negro es el límite legal."},"ref":{"doc":"OR","page":20}},{"id":"or-067","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, the limit is 55 mph. You drive 50 mph in thick snow, and it is too fast to be safe. Are you breaking the law?","o":["Yes, you are breaking the basic rule","No, you are under the speed limit","Only if you cause a crash","Only if a sign says to slow down"],"h1":"There is one speed rule that applies on all roads at all times.","h2":"In Oregon, driving at a speed that is unsafe for conditions breaks the basic rule, even if you are under the speed limit.","p":"Right. Too fast for conditions breaks the basic rule, even under the limit."},"es":{"q":"En Oregon, el límite es 55 mph. Usted maneja a 50 mph con nieve espesa, y es demasiado rápido para ser seguro. ¿Está violando la ley?","o":["Sí, está violando la regla básica","No, está por debajo del límite","Solo si causa un choque","Solo si un letrero dice que reduzca la velocidad"],"h1":"Hay una regla de velocidad que se aplica en todas las carreteras y en todo momento.","h2":"En Oregon, manejar a una velocidad que no es segura para las condiciones viola la regla básica, aunque usted vaya por debajo del límite de velocidad.","p":"Correcto. Ir demasiado rápido para las condiciones viola la regla básica, aun por debajo del límite."},"ref":{"doc":"OR","page":21}},{"id":"or-068","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, how should you use a two-way left turn lane in the center of the road?","o":["Drive in it for several blocks to pass slow cars","Enter it just before your turn, then wait there to turn left","Use it to merge when you enter the road from the right","Use it to make right turns"],"h1":"It is illegal to travel along in this lane.","h2":"In Oregon, it is illegal to travel in a two-way left turn lane, so you enter it just before your left turn and wait there until traffic clears.","p":"Right. Enter the center turn lane just before you turn."},"es":{"q":"En Oregon, ¿cómo debe usar un carril central para dar vuelta a la izquierda en ambos sentidos?","o":["Manejar en él varias cuadras para rebasar autos lentos","Entrar justo antes de su vuelta y esperar allí para dar vuelta a la izquierda","Usarlo para incorporarse cuando entra a la calle desde la derecha","Usarlo para dar vuelta a la derecha"],"h1":"Es ilegal circular a lo largo de este carril.","h2":"En Oregon, es ilegal circular por un carril central de vuelta a la izquierda, así que usted entra justo antes de su vuelta a la izquierda y espera allí hasta que se despeje el tráfico.","p":"Correcto. Entre al carril central justo antes de dar vuelta."},"ref":{"doc":"OR","page":23}},{"id":"or-069","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, the road has a painted median with double solid yellow lines on both sides. What may you do?","o":["Drive in it to pass other cars","Stop and wait in it as a left turn lane","Turn left across it after oncoming traffic clears","Park in it for a short time"],"h1":"You may cross it, but you may not use it as a lane.","h2":"In Oregon, you may turn left across a painted median after oncoming traffic clears, but you may not drive in it or use it as a turn lane.","p":"Right. You may cross a painted median to turn, but not drive or wait in it."},"es":{"q":"En Oregon, la calle tiene una mediana pintada con doble línea amarilla continua en ambos lados. ¿Qué puede hacer?","o":["Manejar dentro de ella para rebasar a otros autos","Detenerse y esperar en ella como carril para dar vuelta a la izquierda","Cruzarla para dar vuelta a la izquierda después de que pase el tráfico de frente","Estacionarse en ella por poco tiempo"],"h1":"Puede cruzarla, pero no puede usarla como carril.","h2":"En Oregon, usted puede cruzar una mediana pintada para dar vuelta a la izquierda después de que pase el tráfico de frente, pero no puede manejar en ella ni usarla como carril de vuelta.","p":"Correcto. Puede cruzar una mediana pintada para dar vuelta, pero no manejar ni esperar en ella."},"ref":{"doc":"OR","page":23}},{"id":"or-070","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, a red lane is marked for transit only. Some parts of it have striped red lines. What do the striped parts show?","o":["Where you may drive in the lane during rush hour","Where buses must stop","Where bicycles may not ride","Where you may enter the lane to turn, park or reach a driveway"],"h1":"Solid red means transit only. Stripes make a small exception for cars.","h2":"In Oregon, striped red lines show where you may enter a transit only lane to turn, park or enter a driveway.","p":"Right. Striped red lines show where you may enter the transit lane to turn or park."},"es":{"q":"En Oregon, un carril rojo está marcado solo para transporte público. Algunas partes tienen líneas rojas rayadas. ¿Qué muestran las partes rayadas?","o":["Dónde puede manejar en el carril en horas pico","Dónde deben detenerse los autobuses","Dónde no pueden circular las bicicletas","Dónde puede entrar al carril para dar vuelta, estacionarse o llegar a una entrada de autos"],"h1":"El rojo sólido significa solo transporte público. Las rayas hacen una pequeña excepción para los autos.","h2":"En Oregon, las líneas rojas rayadas muestran dónde puede entrar a un carril solo para transporte público para dar vuelta, estacionarse o entrar a una entrada de autos.","p":"Correcto. Las líneas rojas rayadas muestran dónde puede entrar al carril de transporte para dar vuelta o estacionarse."},"ref":{"doc":"OR","page":25}},{"id":"or-071","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, you are in a no-passing zone. When may you cross the center line?","o":["Only if the right side of the road is blocked, or to turn left","When the car ahead is going under the limit","When you can see no oncoming cars","Never, for any reason"],"h1":"Passing is not one of the reasons.","h2":"In Oregon, you may cross the center line in a no-passing zone only when the right side of the road is blocked or when you are turning left.","p":"Right. Only if the right side is blocked or you are turning left."},"es":{"q":"En Oregon, usted está en una zona donde no se permite rebasar. ¿Cuándo puede cruzar la línea central?","o":["Solo si el lado derecho de la calle está bloqueado, o para dar vuelta a la izquierda","Cuando el auto de adelante va por debajo del límite","Cuando no ve autos que vengan de frente","Nunca, por ninguna razón"],"h1":"Rebasar no es una de las razones.","h2":"En Oregon, usted puede cruzar la línea central en una zona de no rebasar solo cuando el lado derecho de la calle está bloqueado o cuando da vuelta a la izquierda.","p":"Correcto. Solo si el lado derecho está bloqueado o si da vuelta a la izquierda."},"ref":{"doc":"OR","page":32}},{"id":"or-072","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, the car ahead on a two-lane road is stopped to turn left. You want to pass it on the right. What rule applies?","o":["You may use the bike lane if no one is in it","You may pass only if you stay on the pavement and out of the bike lane","You may drive on the gravel shoulder if needed","Passing on the right is never allowed"],"h1":"There must be room to the right without leaving the road surface.","h2":"In Oregon, you may pass on the right of a car turning left only if there is room without leaving the paved road or driving in a bike lane.","p":"Right. Pass on the right only on the pavement and never in a bike lane."},"es":{"q":"En Oregon, el auto de adelante en una carretera de dos carriles está detenido para dar vuelta a la izquierda. Usted quiere rebasarlo por la derecha. ¿Qué regla se aplica?","o":["Puede usar el carril para bicicletas si no hay nadie en él","Puede rebasar solo si se queda en el pavimento y fuera del carril para bicicletas","Puede manejar por el acotamiento de grava si hace falta","Nunca se permite rebasar por la derecha"],"h1":"Debe haber espacio a la derecha sin salirse de la superficie pavimentada.","h2":"En Oregon, usted puede rebasar por la derecha a un auto que da vuelta a la izquierda solo si hay espacio sin salirse del pavimento ni manejar en un carril para bicicletas.","p":"Correcto. Rebase por la derecha solo sobre el pavimento y nunca en un carril para bicicletas."},"ref":{"doc":"OR","page":33}},{"id":"or-073","scope":"OR","cat":"signals","sign":null,"c":2,"en":{"q":"In Oregon, you are on a freeway on-ramp with a ramp meter. The light turns green. How many cars in your lane may go?","o":["All the cars that are waiting","Two cars","One car","As many as can go before it turns red"],"h1":"The meter lets traffic onto the freeway a little at a time.","h2":"In Oregon, only one vehicle may go each time a ramp meter light turns green.","p":"Right. One car goes on each green."},"es":{"q":"En Oregon, usted está en una rampa de entrada a la autopista con un semáforo de rampa. La luz cambia a verde. ¿Cuántos autos de su carril pueden avanzar?","o":["Todos los autos que esperan","Dos autos","Un auto","Todos los que alcancen a pasar antes de la luz roja"],"h1":"El semáforo deja entrar el tráfico a la autopista poco a poco.","h2":"En Oregon, solo un vehículo puede avanzar cada vez que la luz de un semáforo de rampa cambia a verde.","p":"Correcto. Pasa un auto con cada luz verde."},"ref":{"doc":"OR","page":35}},{"id":"or-074","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, you are driving a pickup and already towing a boat. Your friend wants you to also tow a small utility trailer behind the boat. Is that allowed?","o":["No, you may tow only one trailer or vehicle","Yes, if both are light","Yes, on roads outside cities","Yes, if the second trailer has its own lights"],"h1":"Oregon law sets a limit of one.","h2":"In Oregon, you may tow no more than one boat, utility trailer or other vehicle behind a passenger or recreational vehicle.","p":"Right. A passenger vehicle may tow only one trailer or vehicle."},"es":{"q":"En Oregon, usted maneja una camioneta y ya remolca un bote. Su amigo quiere que también remolque un remolque pequeño detrás del bote. ¿Está permitido?","o":["No, solo puede remolcar un remolque o vehículo","Sí, si los dos son livianos","Sí, en carreteras fuera de las ciudades","Sí, si el segundo remolque tiene sus propias luces"],"h1":"La ley de Oregon fija un límite de uno.","h2":"En Oregon, usted puede remolcar como máximo un bote, remolque utilitario u otro vehículo detrás de un vehículo de pasajeros o recreativo.","p":"Correcto. Un vehículo de pasajeros solo puede remolcar un remolque o vehículo."},"ref":{"doc":"OR","page":36}},{"id":"or-075","scope":"OR","cat":"signals","sign":null,"c":1,"en":{"q":"In Oregon, you are moving in traffic and plan to turn. At least how far before the turn must you use your turn signal?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is about one third of a football field.","h2":"In Oregon, when you are moving in traffic, you must signal at least 100 feet before a turn or lane change.","p":"Right. Signal at least 100 feet before you turn or change lanes."},"es":{"q":"En Oregon, usted circula en el tráfico y piensa dar vuelta. ¿Por lo menos a qué distancia antes de la vuelta debe usar la direccional?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es más o menos un tercio de un campo de fútbol americano.","h2":"En Oregon, cuando circula en el tráfico, debe poner la direccional por lo menos 100 pies antes de dar vuelta o cambiar de carril.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de dar vuelta o cambiar de carril."},"ref":{"doc":"OR","page":38}},{"id":"or-076","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, you are outside city limits and want to make a U-turn. Traffic from each direction must be able to see your car from at least how far away?","o":["200 feet","300 feet","500 feet","1,000 feet"],"h1":"Outside cities, speeds are higher, so the distance is double the city distance.","h2":"In Oregon, outside city limits you may not make a U-turn where traffic from either direction cannot see your car within 1,000 feet.","p":"Right. Outside city limits, other drivers must see you from 1,000 feet."},"es":{"q":"En Oregon, usted está fuera de los límites de la ciudad y quiere dar una vuelta en U. ¿Desde por lo menos qué distancia debe poder ver su auto el tráfico de cada dirección?","o":["200 pies","300 pies","500 pies","1,000 pies"],"h1":"Fuera de las ciudades las velocidades son más altas, así que la distancia es el doble que en la ciudad.","h2":"En Oregon, fuera de los límites de la ciudad no puede dar una vuelta en U donde el tráfico de cualquier dirección no pueda ver su auto a menos de 1,000 pies.","p":"Correcto. Fuera de la ciudad, los otros conductores deben verlo desde 1,000 pies."},"ref":{"doc":"OR","page":41}},{"id":"or-077","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, you and an oncoming car stop at stop signs across from each other. You want to turn left, and the other driver is going straight. Who should go first?","o":["You, because you stopped first","You, because left turns go first","The other driver going straight","Whoever is driving the larger vehicle"],"h1":"A driver turning left usually yields to traffic going straight.","h2":"In Oregon, at stop signs across from each other, the driver turning left should yield to oncoming traffic going straight.","p":"Right. The driver turning left yields to the driver going straight."},"es":{"q":"En Oregon, usted y un auto de frente se detienen en letreros de alto, uno frente al otro. Usted quiere dar vuelta a la izquierda y el otro conductor va derecho. ¿Quién debe pasar primero?","o":["Usted, porque se detuvo primero","Usted, porque las vueltas a la izquierda van primero","El otro conductor que va derecho","El que maneje el vehículo más grande"],"h1":"Quien da vuelta a la izquierda normalmente cede el paso al que va derecho.","h2":"En Oregon, en letreros de alto uno frente al otro, el conductor que da vuelta a la izquierda debe ceder el paso al tráfico de frente que va derecho.","p":"Correcto. El que da vuelta a la izquierda cede el paso al que va derecho."},"ref":{"doc":"OR","page":42}},{"id":"or-078","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, your road ends at a T intersection with no signs or signals. Who has the right of way?","o":["Drivers on the through road","You, because you arrived first","Whoever is on the right","Whoever is turning left"],"h1":"Your road is the one that ends.","h2":"In Oregon, when your road ends at a T intersection with no signs or signals, you must yield to drivers on the through road.","p":"Right. At a T intersection, yield to drivers on the through road."},"es":{"q":"En Oregon, su calle termina en una intersección en forma de T sin letreros ni semáforos. ¿Quién tiene el derecho de paso?","o":["Los conductores en la calle que continúa","Usted, porque llegó primero","El que esté a la derecha","El que dé vuelta a la izquierda"],"h1":"Su calle es la que termina.","h2":"En Oregon, cuando su calle termina en una intersección en forma de T sin letreros ni semáforos, usted debe ceder el paso a los conductores de la calle que continúa.","p":"Correcto. En una T, ceda el paso a los conductores de la calle que continúa."},"ref":{"doc":"OR","page":42}},{"id":"or-079","scope":"OR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oregon, a person on a bicycle has merged into the traffic lane inside a roundabout, just ahead of you. What should you do?","o":["Pass them quickly inside the roundabout","Give them the full lane and do not pass them in the roundabout","Honk so they move onto the sidewalk","Drive beside them in the same lane"],"h1":"Inside the circle, the rider uses the lane like a car.","h2":"In Oregon, you must give a person on a bicycle who has merged into a roundabout the full travel lane and not pass them inside the roundabout.","p":"Right. Give the rider the full lane and do not pass in the roundabout."},"es":{"q":"En Oregon, una persona en bicicleta se incorporó al carril de tráfico dentro de una glorieta, justo delante de usted. ¿Qué debe hacer?","o":["Rebasarla rápido dentro de la glorieta","Darle el carril completo y no rebasarla en la glorieta","Tocar el claxon para que se suba a la acera","Manejar a su lado en el mismo carril"],"h1":"Dentro del círculo, el ciclista usa el carril como un auto.","h2":"En Oregon, usted debe darle el carril completo a una persona en bicicleta que se incorporó a una glorieta y no rebasarla dentro de la glorieta.","p":"Correcto. Dele el carril completo al ciclista y no lo rebase en la glorieta."},"ref":{"doc":"OR","page":43}},{"id":"or-080","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, a person is walking in a crosswalk in the bike lane right next to your lane. You are not turning. What must you do?","o":["Keep going, because they are not in your lane","Slow down and pass carefully behind them","Honk to warn them","Stop and stay stopped"],"h1":"The rule covers your lane and the lanes next to it, including a bike lane.","h2":"In Oregon, you must stop and stay stopped for a pedestrian in a crosswalk who is in your lane, the lane next to yours including a bike lane, or the lane you are turning into.","p":"Right. A person in the lane next to yours, even a bike lane, means stop."},"es":{"q":"En Oregon, una persona camina por un cruce peatonal en el carril para bicicletas justo al lado de su carril. Usted no va a dar vuelta. ¿Qué debe hacer?","o":["Seguir, porque no está en su carril","Reducir la velocidad y pasar con cuidado detrás de ella","Tocar el claxon para avisarle","Detenerse y quedarse detenido"],"h1":"La regla incluye su carril y los carriles de al lado, incluido un carril para bicicletas.","h2":"En Oregon, usted debe detenerse y quedarse detenido por un peatón en un cruce peatonal que esté en su carril, en el carril de al lado (incluido un carril para bicicletas) o en el carril hacia donde da vuelta.","p":"Correcto. Una persona en el carril de al lado, aunque sea un carril para bicicletas, significa alto."},"ref":{"doc":"OR","page":46}},{"id":"or-081","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, a person with a white cane starts crossing the road while your light is green. How long must you stay stopped?","o":["Until the person has crossed the entire road","Until the person passes your lane","Until the person reaches the center line","Only until the light turns red"],"h1":"A green light does not change this rule.","h2":"In Oregon, you must stop for a pedestrian with a white cane or guide dog and stay stopped until they cross the entire road, even if you have a green light.","p":"Right. Stay stopped until the person has crossed the whole road."},"es":{"q":"En Oregon, una persona con un bastón blanco empieza a cruzar la calle mientras su luz está en verde. ¿Cuánto tiempo debe quedarse detenido?","o":["Hasta que la persona haya cruzado toda la calle","Hasta que la persona pase su carril","Hasta que la persona llegue a la línea central","Solo hasta que la luz cambie a rojo"],"h1":"Una luz verde no cambia esta regla.","h2":"En Oregon, usted debe detenerse por un peatón con bastón blanco o perro guía y quedarse detenido hasta que cruce toda la calle, aunque usted tenga luz verde.","p":"Correcto. Quédese detenido hasta que la persona haya cruzado toda la calle."},"ref":{"doc":"OR","page":48}},{"id":"or-082","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, a school speed sign says 20 MPH WHEN CHILDREN ARE PRESENT. Which of these counts as children being present?","o":["Children are playing on the school field","A traffic patrol member is at the crosswalk to help children","A school bus is parked at the school","It is a school day"],"h1":"The manual defines \"present\" by what is happening at the crosswalk.","h2":"In Oregon, children are present when children are waiting at or walking in a crosswalk, or when a traffic patrol member is at the crosswalk to help them.","p":"Right. A traffic patrol member at the crosswalk means children are present."},"es":{"q":"En Oregon, un letrero de velocidad escolar dice 20 MPH CUANDO HAY NIÑOS PRESENTES. ¿Cuál de estas situaciones cuenta como niños presentes?","o":["Hay niños jugando en el campo de la escuela","Un miembro de la patrulla de tránsito está en el cruce peatonal para ayudar a los niños","Hay un autobús escolar estacionado en la escuela","Es un día de clases"],"h1":"El manual define \"presentes\" según lo que pasa en el cruce peatonal.","h2":"En Oregon, hay niños presentes cuando hay niños esperando o caminando en un cruce peatonal, o cuando un miembro de la patrulla de tránsito está en el cruce para ayudarlos.","p":"Correcto. Un miembro de la patrulla de tránsito en el cruce significa que hay niños presentes."},"ref":{"doc":"OR","page":49}},{"id":"or-083","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, a school speed sign applies during school hours. It is 10 a.m. on a weekday, and you are not sure if school is in session. What should you do?","o":["Keep the normal speed limit","Slow to 25 mph","Slow down only if you see children","Slow down to 20 mph"],"h1":"When in doubt, treat it as a school day.","h2":"In Oregon, if you are not sure whether it is a school day in a school-hours speed zone, you should slow down to 20 mph.","p":"Right. If you are unsure, slow to 20 mph."},"es":{"q":"En Oregon, un letrero de velocidad escolar se aplica en horario escolar. Son las 10 a.m. de un día entre semana y usted no sabe si hay clases. ¿Qué debe hacer?","o":["Mantener el límite de velocidad normal","Bajar a 25 mph","Reducir la velocidad solo si ve niños","Bajar la velocidad a 20 mph"],"h1":"Si tiene dudas, trátelo como día de clases.","h2":"En Oregon, si no está seguro de si es día de clases en una zona escolar con horario, debe bajar la velocidad a 20 mph.","p":"Correcto. Si no está seguro, baje a 20 mph."},"ref":{"doc":"OR","page":49}},{"id":"or-084","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, you are driving 45 mph behind a person on a bicycle in your lane. You may pass only if you do what?","o":["Honk first so they move right","Stay at least 1 foot away","Leave enough room that you would not hit them if they fell","Pass only on the right"],"h1":"Think about what happens if the rider falls over toward your car.","h2":"In Oregon, at speeds over 35 mph you may pass a person on a bicycle in your lane only if you leave enough distance to avoid contact if they were to fall.","p":"Right. Leave enough room that a fall would not bring the rider into your car."},"es":{"q":"En Oregon, usted maneja a 45 mph detrás de una persona en bicicleta en su carril. ¿Solo puede rebasarla si hace qué?","o":["Tocar el claxon primero para que se mueva a la derecha","Mantenerse por lo menos a 1 pie de distancia","Dejar suficiente espacio para no golpearla si se cayera","Rebasar solo por la derecha"],"h1":"Piense en lo que pasa si el ciclista se cae hacia su auto.","h2":"En Oregon, a velocidades de más de 35 mph, usted puede rebasar a una persona en bicicleta en su carril solo si deja suficiente distancia para no tocarla si se cayera.","p":"Correcto. Deje suficiente espacio para que una caída no lleve al ciclista contra su auto."},"ref":{"doc":"OR","page":50}},{"id":"or-085","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, a motorcycle is riding on the left side of your lane. Is it legal to pull up beside it in the same lane?","o":["No, it is against the law to share a lane with a motorcycle","Yes, if there is enough room","Yes, at low speed in traffic","Yes, if the rider waves you on"],"h1":"When passing, a motorcycle gets the same space as a car.","h2":"In Oregon, it is against the law to share a lane with a motorcycle or moped, and when passing you must give the rider a full lane.","p":"Right. Never share a lane with a motorcycle; give it a full lane."},"es":{"q":"En Oregon, una motocicleta circula por el lado izquierdo de su carril. ¿Es legal ponerse a su lado en el mismo carril?","o":["No, es ilegal compartir un carril con una motocicleta","Sí, si hay suficiente espacio","Sí, a baja velocidad en el tráfico","Sí, si el motociclista le hace señas para pasar"],"h1":"Al rebasar, una motocicleta recibe el mismo espacio que un auto.","h2":"En Oregon, es ilegal compartir un carril con una motocicleta o un ciclomotor, y al rebasar debe darle al conductor un carril completo.","p":"Correcto. Nunca comparta un carril con una motocicleta; dele un carril completo."},"ref":{"doc":"OR","page":52}},{"id":"or-086","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you see a marked pilot vehicle coming toward you, leading a very wide load. What should you do?","o":["Speed up to get past quickly","Stop in your lane until it passes","Flash your high beams at it","Slow down and move as far right as you can while staying in your lane"],"h1":"Give the wide load room without leaving your lane.","h2":"In Oregon, when a pilot vehicle comes toward you, slow down and move as far to the right as possible while staying in your lane.","p":"Right. Slow down and keep far right in your lane."},"es":{"q":"En Oregon, usted ve un vehículo piloto marcado que viene de frente, guiando una carga muy ancha. ¿Qué debe hacer?","o":["Acelerar para pasar rápido","Detenerse en su carril hasta que pase","Hacerle cambio de luces altas","Reducir la velocidad y moverse lo más a la derecha posible sin salir de su carril"],"h1":"Dele espacio a la carga ancha sin salir de su carril.","h2":"En Oregon, cuando un vehículo piloto viene de frente, reduzca la velocidad y muévase lo más a la derecha posible sin salir de su carril.","p":"Correcto. Reduzca la velocidad y manténgase a la derecha en su carril."},"ref":{"doc":"OR","page":54}},{"id":"or-087","scope":"OR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oregon, you are on a divided highway with an unpaved median. A school bus on the other side of the median has its red lights flashing. What must you do?","o":["Stop until the red lights turn off","You do not have to stop","Slow to 20 mph","Stop, then go when no children are visible"],"h1":"An unpaved median or barrier makes two separate roads.","h2":"In Oregon, on a divided highway with an unpaved median or barrier, you must stop for a school bus with flashing red lights only if you are on the same side as the bus.","p":"Right. On the other side of an unpaved median, you do not have to stop."},"es":{"q":"En Oregon, usted está en una carretera dividida con una mediana sin pavimentar. Un autobús escolar al otro lado de la mediana tiene las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces rojas","No tiene que detenerse","Bajar a 20 mph","Detenerse y avanzar cuando no vea niños"],"h1":"Una mediana sin pavimentar o una barrera crea dos calles separadas.","h2":"En Oregon, en una carretera dividida con mediana sin pavimentar o barrera, usted debe detenerse por un autobús escolar con luces rojas intermitentes solo si está del mismo lado que el autobús.","p":"Correcto. Del otro lado de una mediana sin pavimentar, no tiene que detenerse."},"ref":{"doc":"OR","page":55}},{"id":"or-088","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, a bus that carries workers to a job site turns on flashing red lights and stops. What must you do?","o":["Nothing special; only school buses count","Slow down and pass with care","Treat it the same as a school bus and stop","Honk and pass on the left"],"h1":"Oregon lets some other buses use the same lights as school buses.","h2":"In Oregon, if a worker transport or place of worship bus turns on flashing amber or red lights, you must treat them the same as a school bus.","p":"Right. Treat those flashing lights like a school bus."},"es":{"q":"En Oregon, un autobús que lleva trabajadores a un lugar de trabajo enciende luces rojas intermitentes y se detiene. ¿Qué debe hacer?","o":["Nada especial; solo cuentan los autobuses escolares","Reducir la velocidad y pasar con cuidado","Tratarlo igual que a un autobús escolar y detenerse","Tocar el claxon y rebasar por la izquierda"],"h1":"Oregon permite que otros autobuses usen las mismas luces que los autobuses escolares.","h2":"En Oregon, si un autobús de trabajadores o de un lugar de culto enciende luces ámbar o rojas intermitentes, usted debe tratarlas igual que las de un autobús escolar.","p":"Correcto. Trate esas luces intermitentes como las de un autobús escolar."},"ref":{"doc":"OR","page":56}},{"id":"or-089","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, you are using high beams on a dark road and catch up to another car going the same way. When must you dim your lights?","o":["When you are within 100 feet of it","When you are within 200 feet of it","When you are within 1,000 feet of it","When you are within 350 feet of it"],"h1":"It is less than the distance for oncoming cars.","h2":"In Oregon, you must dim your high beams when you are following another vehicle within 350 feet.","p":"Right. Dim your lights within 350 feet of a car you are following."},"es":{"q":"En Oregon, usted usa las luces altas en un camino oscuro y se acerca a otro auto que va en la misma dirección. ¿Cuándo debe bajar sus luces?","o":["Cuando esté a menos de 100 pies","Cuando esté a menos de 200 pies","Cuando esté a menos de 1,000 pies","Cuando esté a menos de 350 pies"],"h1":"Es menos que la distancia para autos que vienen de frente.","h2":"En Oregon, usted debe bajar sus luces altas cuando sigue a otro vehículo a menos de 350 pies.","p":"Correcto. Baje sus luces a menos de 350 pies del auto que sigue."},"ref":{"doc":"OR","page":76}},{"id":"or-090","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, you are 30 years old. What kind of phone use is allowed while driving?","o":["Holding the phone to your ear for short calls","Texting at red lights","Using a hands-free accessory that needs only a small touch of a finger","Any use, because you are over 18"],"h1":"Adults may use a phone only if their hands stay free.","h2":"In Oregon, drivers 18 and older must use a hands-free accessory, which may only need minimal use of a finger to turn on or off, to use a phone while driving.","p":"Right. Adults may use only a hands-free accessory that needs a quick finger touch."},"es":{"q":"En Oregon, usted tiene 30 años. ¿Qué tipo de uso del teléfono se permite mientras maneja?","o":["Sostener el teléfono en la oreja para llamadas cortas","Enviar mensajes en los semáforos en rojo","Usar un accesorio de manos libres que solo necesite un toque pequeño con un dedo","Cualquier uso, porque tiene más de 18 años"],"h1":"Los adultos solo pueden usar el teléfono si sus manos quedan libres.","h2":"En Oregon, los conductores de 18 años o más deben usar un accesorio de manos libres, que solo requiera un uso mínimo de un dedo para encenderlo o apagarlo, para usar el teléfono mientras manejan.","p":"Correcto. Los adultos solo pueden usar un accesorio de manos libres que necesite un toque rápido con el dedo."},"ref":{"doc":"OR","page":80}},{"id":"or-091","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, your passenger wants to watch a movie on a tablet placed where you, the driver, can see it. Is this allowed?","o":["Yes, if the sound is off","No, a video display visible to the driver is illegal","Yes, on the freeway only","Yes, if the passenger holds it"],"h1":"The law is about what the driver can see.","h2":"In Oregon, it is illegal to have a TV, tablet or other video display that the driver can see while driving.","p":"Right. A video screen the driver can see is illegal."},"es":{"q":"En Oregon, su pasajero quiere ver una película en una tableta colocada donde usted, el conductor, puede verla. ¿Está permitido?","o":["Sí, si el sonido está apagado","No, una pantalla de video visible para el conductor es ilegal","Sí, solo en la autopista","Sí, si el pasajero la sostiene"],"h1":"La ley se refiere a lo que puede ver el conductor.","h2":"En Oregon, es ilegal tener un televisor, una tableta u otra pantalla de video que el conductor pueda ver mientras maneja.","p":"Correcto. Una pantalla de video que el conductor puede ver es ilegal."},"ref":{"doc":"OR","page":80}},{"id":"or-092","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, your blood alcohol is 0.06 percent, and you are 25. Can you be arrested for driving under the influence (DUII)?","o":["No, the limit is 0.08 percent","No, only if you cause a crash","Only if you are driving a truck","Yes, if the alcohol affects your driving"],"h1":"0.08 is when the law presumes you are impaired, not the only time.","h2":"In Oregon, a blood alcohol level of 0.08 percent or more is presumed impaired, but you can still be arrested for DUII at a lower level.","p":"Right. You can be arrested for DUII even below 0.08 percent."},"es":{"q":"En Oregon, su nivel de alcohol en la sangre es de 0.06 por ciento y usted tiene 25 años. ¿Lo pueden arrestar por manejar bajo la influencia (DUII)?","o":["No, el límite es 0.08 por ciento","No, solo si causa un choque","Solo si maneja un camión","Sí, si el alcohol afecta su manera de manejar"],"h1":"El 0.08 es cuando la ley supone que usted está afectado, no el único caso.","h2":"En Oregon, un nivel de alcohol en la sangre de 0.08 por ciento o más se considera afectado por ley, pero usted todavía puede ser arrestado por DUII con un nivel más bajo.","p":"Correcto. Lo pueden arrestar por DUII aun por debajo de 0.08 por ciento."},"ref":{"doc":"OR","page":82}},{"id":"or-093","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, a police officer asks you to take a breath test, and you refuse. What can happen?","o":["Nothing, the test is your choice","You must pay for the test yourself","You may get a fine, and your driving privileges could be suspended","You only get a warning the first time"],"h1":"By driving, you already agreed to be tested.","h2":"In Oregon, under the Implied Consent law, if you refuse a breath, blood or urine test, you may receive a fine and your driving privileges could be suspended.","p":"Right. Refusing can bring a fine and a suspension."},"es":{"q":"En Oregon, un policía le pide que haga una prueba de aliento y usted se niega. ¿Qué puede pasar?","o":["Nada, la prueba es opcional","Debe pagar la prueba usted mismo","Puede recibir una multa y le pueden suspender sus privilegios de manejo","Solo recibe una advertencia la primera vez"],"h1":"Al manejar, usted ya aceptó hacerse la prueba.","h2":"En Oregon, según la ley de Consentimiento Implícito, si se niega a una prueba de aliento, sangre u orina, puede recibir una multa y le pueden suspender sus privilegios de manejo.","p":"Correcto. Negarse puede traer una multa y una suspensión."},"ref":{"doc":"OR","page":83}},{"id":"or-094","scope":"OR","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Oregon, you opened a bottle of wine at dinner, put the cork back in, and now it is in your car. Where should it be?","o":["In the trunk","Under the passenger seat","In the back seat","Anywhere, because it is closed again"],"h1":"A broken seal means the bottle counts as open.","h2":"In Oregon, a container is open if its seal is broken, even if it was closed again, so it should be kept in the trunk.","p":"Right. A reclosed bottle is still open and belongs in the trunk."},"es":{"q":"En Oregon, usted abrió una botella de vino en la cena, le volvió a poner el corcho y ahora está en su auto. ¿Dónde debería ir?","o":["En la cajuela (maletero)","Debajo del asiento del pasajero","En el asiento de atrás","En cualquier lugar, porque está cerrada otra vez"],"h1":"Un sello roto significa que la botella cuenta como abierta.","h2":"En Oregon, un envase está abierto si su sello está roto, aunque se haya vuelto a cerrar, así que debe guardarse en la cajuela.","p":"Correcto. Una botella vuelta a cerrar sigue abierta y va en la cajuela."},"ref":{"doc":"OR","page":83}},{"id":"or-095","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, you want to carry your dog in the open bed of your pickup. What does the law require?","o":["Nothing, if you drive slowly","The dog must be protected by a framework, carrier or other device so it cannot fall","The dog must wear a collar","An adult must ride in the bed with the dog"],"h1":"The rule is about keeping the dog from falling out.","h2":"In Oregon, you may not carry a dog in a pickup bed unless it is protected by a framework, carrier or other device that keeps it from falling.","p":"Right. A dog in a pickup bed needs a carrier or device that keeps it from falling."},"es":{"q":"En Oregon, usted quiere llevar a su perro en la caja abierta de su camioneta. ¿Qué exige la ley?","o":["Nada, si maneja despacio","El perro debe estar protegido por una estructura, jaula u otro dispositivo para que no se caiga","El perro debe llevar collar","Un adulto debe ir en la caja con el perro"],"h1":"La regla se trata de evitar que el perro se caiga.","h2":"En Oregon, no puede llevar a un perro en la caja de una camioneta a menos que esté protegido por una estructura, jaula u otro dispositivo que evite que se caiga.","p":"Correcto. Un perro en la caja de una camioneta necesita una jaula o dispositivo que evite que se caiga."},"ref":{"doc":"OR","page":84}},{"id":"or-096","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, when you parallel park next to a curb, how close to the curb must your car be?","o":["No more than 6 inches","No more than 18 inches","No more than 12 inches","No more than 24 inches"],"h1":"It is the length of a ruler.","h2":"In Oregon, when you parallel park, you must park parallel to the curb and no more than 12 inches from it.","p":"Right. Park no more than 12 inches from the curb."},"es":{"q":"En Oregon, cuando se estaciona en paralelo junto a la acera, ¿qué tan cerca de la acera debe quedar su auto?","o":["A no más de 6 pulgadas","A no más de 18 pulgadas","A no más de 12 pulgadas","A no más de 24 pulgadas"],"h1":"Es el largo de una regla.","h2":"En Oregon, cuando se estaciona en paralelo, debe quedar paralelo a la acera y a no más de 12 pulgadas de ella.","p":"Correcto. Estaciónese a no más de 12 pulgadas de la acera."},"ref":{"doc":"OR","page":68}},{"id":"or-097","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","It does not matter if the brake is set","Toward the travel lane, away from the curb"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In Oregon, when you park uphill against a curb, turn your front wheels toward the travel lane, away from the curb.","p":"Right. Uphill with a curb, turn the wheels away from the curb."},"es":{"q":"En Oregon, usted se estaciona cuesta arriba junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la acera","Derechas","No importa si el freno está puesto","Hacia el carril de circulación, lejos de la acera"],"h1":"Si el auto rueda hacia atrás, la parte de atrás de la llanta delantera debe chocar con la acera.","h2":"En Oregon, cuando se estaciona cuesta arriba junto a una acera, gire las llantas delanteras hacia el carril de circulación, lejos de la acera.","p":"Correcto. Cuesta arriba con acera, gire las llantas lejos de la acera."},"ref":{"doc":"OR","page":69}},{"id":"or-098","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, you park in a disabled person parking space without a permit for \"just a few minutes.\" What is the lowest fine?","o":["$165","$50","$100","$500"],"h1":"Fines range up to $1,000.","h2":"In Oregon, fines for parking in a disabled person space without a permit begin at $165 and go up to $1,000, even for a few minutes.","p":"Right. The fine starts at $165."},"es":{"q":"En Oregon, usted se estaciona en un espacio para personas con discapacidad sin permiso \"solo por unos minutos\". ¿Cuál es la multa más baja?","o":["$165","$50","$100","$500"],"h1":"Las multas llegan hasta $1,000.","h2":"En Oregon, las multas por estacionarse en un espacio para personas con discapacidad sin permiso empiezan en $165 y llegan hasta $1,000, aunque sea por unos minutos.","p":"Correcto. La multa empieza en $165."},"ref":{"doc":"OR","page":70}},{"id":"or-099","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, how close may you park to the nearest rail of a railroad or light rail crossing?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is the same distance as for a sign your car would hide.","h2":"In Oregon, you may not park within 50 feet of the nearest rail of a railroad or light rail crossing.","p":"Right. Park no closer than 50 feet to a crossing."},"es":{"q":"En Oregon, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril o de tren ligero puede estacionarse?","o":["No más cerca de 15 pies","No más cerca de 50 pies","No más cerca de 25 pies","No más cerca de 100 pies"],"h1":"Es la misma distancia que para un letrero que su auto taparía.","h2":"En Oregon, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril o de tren ligero.","p":"Correcto. No se estacione a menos de 50 pies de un cruce."},"ref":{"doc":"OR","page":71}},{"id":"or-100","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, your car breaks down on a highway shoulder where drivers cannot see it from 200 feet away. How must you warn traffic?","o":["Leave the trunk open","Honk your horn every minute","Place flags, flares or signs at least 200 feet away in each direction","Put a cloth on the antenna only"],"h1":"The warning distance matches how far away drivers should be able to see your car.","h2":"In Oregon, if your stopped vehicle cannot be seen from 200 feet in each direction, you must warn traffic with flags, flares, signs or other warnings placed at least 200 feet away in each direction.","p":"Right. Put warnings at least 200 feet away in each direction."},"es":{"q":"En Oregon, su auto se descompone en el acotamiento de una carretera donde los conductores no lo pueden ver desde 200 pies. ¿Cómo debe avisar al tráfico?","o":["Dejando la cajuela abierta","Tocando el claxon cada minuto","Colocando banderas, bengalas o letreros por lo menos a 200 pies en cada dirección","Poniendo solo un trapo en la antena"],"h1":"La distancia del aviso es igual a la distancia desde la que deberían ver su auto.","h2":"En Oregon, si su vehículo detenido no se puede ver desde 200 pies en cada dirección, debe avisar al tráfico con banderas, bengalas, letreros u otros avisos colocados por lo menos a 200 pies en cada dirección.","p":"Correcto. Coloque avisos por lo menos a 200 pies en cada dirección."},"ref":{"doc":"OR","page":71}},{"id":"or-101","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you wear glasses when you take the DMV vision test. What happens?","o":["Your license will show that you must wear corrective lenses to drive","You must take the vision test again without glasses","You must pay an extra fee for the vision test","You may drive only in daylight"],"h1":"Your license records how you passed the test.","h2":"In Oregon, if you take the vision test wearing glasses or contact lenses, your driving privilege will show that corrective lenses are required.","p":"Right. Your license will say you must wear corrective lenses."},"es":{"q":"En Oregon, usted usa lentes cuando hace el examen de la vista en el DMV. ¿Qué pasa?","o":["Su licencia indicará que debe usar lentes correctivos para manejar","Debe repetir el examen de la vista sin lentes","Debe pagar una tarifa extra por el examen de la vista","Solo podrá manejar de día"],"h1":"Su licencia registra cómo pasó usted el examen.","h2":"En Oregon, si hace el examen de la vista con lentes o lentes de contacto, su permiso de manejar indicará que se requieren lentes correctivos.","p":"Correcto. Su licencia dirá que debe usar lentes correctivos."},"ref":{"doc":"OR","page":1}},{"id":"or-102","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, how many times may you take the knowledge test online in one 24-hour period?","o":["One time","Two times","Three times","As many times as you want"],"h1":"It is a small number, so study between tries.","h2":"In Oregon, you may take the knowledge test online two times in a 24-hour period, and four times in total.","p":"Right. You may test online two times in 24 hours."},"es":{"q":"En Oregon, ¿cuántas veces puede hacer el examen de conocimientos en línea en un período de 24 horas?","o":["Una vez","Dos veces","Tres veces","Todas las veces que quiera"],"h1":"Es un número pequeño, así que estudie entre intentos.","h2":"En Oregon, usted puede hacer el examen de conocimientos en línea dos veces en un período de 24 horas, y cuatro veces en total.","p":"Correcto. Puede hacer el examen en línea dos veces en 24 horas."},"ref":{"doc":"OR","page":3}},{"id":"or-103","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, DMV may waive your drive test if you finished an ODOT-approved driver education course within what time?","o":["The past six months","The past two years","The past five years","Any time in your life"],"h1":"The course must be fairly recent, but it does not have to be this year.","h2":"In Oregon, DMV may waive the drive test if it receives proof that you completed an ODOT-approved driver education course within the past two years.","p":"Right. The course must be within the past two years."},"es":{"q":"En Oregon, ¿dentro de qué plazo debe haber terminado un curso de educación vial aprobado por ODOT para que el DMV pueda eximirlo del examen de manejo?","o":["Los últimos seis meses","Los últimos dos años","Los últimos cinco años","En cualquier momento de su vida"],"h1":"El curso debe ser bastante reciente, pero no tiene que ser de este año.","h2":"En Oregon, el DMV puede eximirlo del examen de manejo si recibe prueba de que usted terminó un curso de educación vial aprobado por ODOT en los últimos dos años.","p":"Correcto. El curso debe ser de los últimos dos años."},"ref":{"doc":"OR","page":3}},{"id":"or-104","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, your mother wants to ride in the back seat during your drive test. Is that allowed?","o":["Yes, if she stays quiet","Yes, if she is a licensed driver","No, only you and the examiner may be in the vehicle","No, unless she is there to translate"],"h1":"Think about who the test is for and who grades it.","h2":"In Oregon, only you and the examiner may be in the vehicle during a drive test; family, friends, translators and pets are not allowed.","p":"Right. Only you and the examiner may be in the vehicle."},"es":{"q":"En Oregon, su madre quiere ir en el asiento de atrás durante su examen de manejo. ¿Está permitido?","o":["Sí, si se queda callada","Sí, si tiene licencia de manejar","No, solo usted y el examinador pueden estar en el vehículo","No, a menos que vaya para traducir"],"h1":"Piense en para quién es el examen y quién lo califica.","h2":"En Oregon, solo usted y el examinador pueden estar en el vehículo durante el examen de manejo; no se permiten familiares, amigos, traductores ni mascotas.","p":"Correcto. Solo usted y el examinador pueden estar en el vehículo."},"ref":{"doc":"OR","page":4}},{"id":"or-105","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, you arrive for your drive test but cannot show valid proof of insurance for the car. What happens?","o":["You must reschedule the test","The examiner lets you test anyway","You take the test in a DMV car","You pay a fine and then take the test"],"h1":"The examiner checks this before you start driving.","h2":"In Oregon, you must show valid proof of insurance for your vehicle before the drive test, or you will have to reschedule the test.","p":"Right. Without proof of insurance, you must reschedule."},"es":{"q":"En Oregon, usted llega a su examen de manejo pero no puede mostrar prueba válida de seguro del auto. ¿Qué pasa?","o":["Debe programar el examen para otro día","El examinador le deja hacer el examen de todos modos","Hace el examen en un auto del DMV","Paga una multa y luego hace el examen"],"h1":"El examinador revisa esto antes de que usted empiece a manejar.","h2":"En Oregon, usted debe mostrar prueba válida de seguro de su vehículo antes del examen de manejo, o tendrá que programar el examen para otro día.","p":"Correcto. Sin prueba de seguro, debe programar otra cita."},"ref":{"doc":"OR","page":4}},{"id":"or-106","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, you bring a birth certificate made by the hospital where you were born. Will DMV accept it as proof of identity and date of birth?","o":["Yes, any birth certificate is accepted","Yes, if it has your footprints on it","No, it must be a birth certificate issued by a U.S. government agency","Yes, if a parent signs it at DMV"],"h1":"DMV wants a document from the government office that records births.","h2":"In Oregon, DMV accepts a U.S. government-issued birth certificate, but hospital-issued birth certificates and baptismal records are not acceptable.","p":"Right. A hospital birth certificate is not accepted."},"es":{"q":"En Oregon, usted lleva un certificado de nacimiento hecho por el hospital donde nació. ¿Lo aceptará el DMV como prueba de identidad y fecha de nacimiento?","o":["Sí, se acepta cualquier certificado de nacimiento","Sí, si tiene sus huellas de los pies","No, debe ser un certificado de nacimiento emitido por una agencia del gobierno de EE. UU.","Sí, si uno de sus padres lo firma en el DMV"],"h1":"El DMV quiere un documento de la oficina del gobierno que registra los nacimientos.","h2":"En Oregon, el DMV acepta un certificado de nacimiento emitido por el gobierno de EE. UU., pero no acepta certificados emitidos por hospitales ni fes de bautismo.","p":"Correcto. No se acepta un certificado de nacimiento del hospital."},"ref":{"doc":"OR","page":90}},{"id":"or-107","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, which of these can you use to prove your home address when you apply for a driving privilege?","o":["A personal letter from a friend","Mail forwarded from your old address","A note you wrote yourself","A utility bill"],"h1":"Personal and forwarded mail do not count.","h2":"In Oregon, a utility bill can prove your home address, but personal mail and forwarded mail are not accepted.","p":"Right. A utility bill can prove your address."},"es":{"q":"En Oregon, ¿cuál de estos puede usar para probar su domicilio cuando solicita un permiso de manejar?","o":["Una carta personal de un amigo","Correo reenviado desde su domicilio anterior","Una nota que usted mismo escribió","Una factura de servicios públicos"],"h1":"El correo personal y el correo reenviado no cuentan.","h2":"En Oregon, una factura de servicios públicos puede probar su domicilio, pero no se acepta correo personal ni correo reenviado.","p":"Correcto. Una factura de servicios públicos puede probar su domicilio."},"ref":{"doc":"OR","page":91}},{"id":"or-108","scope":"OR","cat":"licensing","sign":null,"c":0,"en":{"q":"In Oregon, what is the minimum coverage a car owner must carry for damage to other people's property in one crash?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"It is less than the $25,000 for injury to one person.","h2":"In Oregon, the minimum insurance for damage to other people's property is $20,000 per crash.","p":"Right. The minimum is $20,000 for property damage."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima que el dueño de un auto debe tener por daños a la propiedad de otras personas en un choque?","o":["$20,000","$10,000","$25,000","$50,000"],"h1":"Es menos que los $25,000 por lesiones a una persona.","h2":"En Oregon, el seguro mínimo por daños a la propiedad de otras personas es de $20,000 por choque.","p":"Correcto. El mínimo es de $20,000 por daños a la propiedad."},"ref":{"doc":"OR","page":93}},{"id":"or-109","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, what is the minimum uninsured motorist coverage a car owner must carry for each person?","o":["$10,000","$15,000","$25,000","$100,000"],"h1":"It matches the minimum liability amount for injury to one person.","h2":"In Oregon, car insurance must include at least $25,000 per person and $50,000 per crash in uninsured motorist coverage.","p":"Right. The minimum is $25,000 per person."},"es":{"q":"En Oregon, ¿cuál es la cobertura mínima contra conductores sin seguro que el dueño de un auto debe tener por persona?","o":["$10,000","$15,000","$25,000","$100,000"],"h1":"Es igual al mínimo de responsabilidad por lesiones a una persona.","h2":"En Oregon, el seguro del auto debe incluir por lo menos $25,000 por persona y $50,000 por choque de cobertura contra conductores sin seguro.","p":"Correcto. El mínimo es de $25,000 por persona."},"ref":{"doc":"OR","page":93}},{"id":"or-110","scope":"OR","cat":"licensing","sign":null,"c":3,"en":{"q":"In Oregon, you are in a crash. The damage is only $500, but your passenger hurt her arm. Must you file a crash report with DMV?","o":["No, the damage is under $2,500","No, a police report is enough","Only if she goes to the hospital","Yes, a crash with any injury must be reported within 72 hours"],"h1":"The damage amount is not the only reason to file a report.","h2":"In Oregon, you must file a crash report with DMV within 72 hours when anyone is injured or killed, no matter how small the damage is.","p":"Right. Any injury means you must file a report."},"es":{"q":"En Oregon, usted tiene un choque. El daño es de solo $500, pero su pasajera se lastimó el brazo. ¿Debe presentar un informe del choque al DMV?","o":["No, el daño es menos de $2,500","No, basta con un informe de la policía","Solo si ella va al hospital","Sí, un choque con cualquier lesión se debe informar dentro de 72 horas"],"h1":"La cantidad del daño no es la única razón para presentar un informe.","h2":"En Oregon, usted debe presentar un informe del choque al DMV dentro de 72 horas cuando alguien resulta lesionado o muerto, sin importar lo pequeño que sea el daño.","p":"Correcto. Cualquier lesión significa que debe presentar un informe."},"ref":{"doc":"OR","page":94}},{"id":"or-111","scope":"OR","cat":"licensing","sign":null,"c":1,"en":{"q":"In Oregon, which of these can make you lose your driving privilege?","o":["Paying a traffic ticket on time","Driving without insurance","Taking a defensive driving class","Selling your car"],"h1":"Oregon requires every vehicle to be insured.","h2":"In Oregon, you can lose your driving privilege for driving uninsured, as well as for DUII, failing to report a crash, too many traffic convictions, or not paying court fines.","p":"Right. Driving uninsured can cost you your driving privilege."},"es":{"q":"En Oregon, ¿cuál de estas cosas puede hacer que pierda su permiso de manejar?","o":["Pagar una multa de tránsito a tiempo","Manejar sin seguro","Tomar una clase de manejo defensivo","Vender su auto"],"h1":"Oregon exige que todo vehículo tenga seguro.","h2":"En Oregon, usted puede perder su permiso de manejar por manejar sin seguro, y también por DUII, por no informar un choque, por demasiadas condenas de tránsito o por no pagar multas del tribunal.","p":"Correcto. Manejar sin seguro le puede costar su permiso de manejar."},"ref":{"doc":"OR","page":95}},{"id":"or-112","scope":"OR","cat":"licensing","sign":null,"c":2,"en":{"q":"In Oregon, which of these may you drive with a Class C non-commercial license?","o":["A large passenger bus","A motorcycle","A moped or an autocycle","A truck that weighs more than 26,000 pounds"],"h1":"A motorcycle needs a special endorsement.","h2":"In Oregon, a Class C license lets you drive passenger cars, mopeds, autocycles, vans and pickups up to 26,000 pounds that need no commercial license or motorcycle endorsement.","p":"Right. A Class C license covers mopeds and autocycles."},"es":{"q":"En Oregon, ¿cuál de estos puede manejar con una licencia Clase C no comercial?","o":["Un autobús grande de pasajeros","Una motocicleta","Un ciclomotor o un autociclo","Un camión que pesa más de 26,000 libras"],"h1":"Una motocicleta necesita un endoso especial.","h2":"En Oregon, una licencia Clase C le permite manejar autos de pasajeros, ciclomotores, autociclos, camionetas y pickups de hasta 26,000 libras que no requieren licencia comercial ni endoso de motocicleta.","p":"Correcto. La licencia Clase C incluye ciclomotores y autociclos."},"ref":{"doc":"OR","page":89}},{"id":"or-113","scope":"OR","cat":"signals","sign":null,"c":0,"en":{"q":"In Oregon, you are at a steady red arrow pointing right. No sign or officer says otherwise. What may you do?","o":["Turn right after a complete stop, yielding to traffic and people walking","Wait until the arrow turns green","Turn right without stopping","Turn right only if a police officer waves you on"],"h1":"Oregon treats a red arrow like a steady red light for turns.","h2":"In Oregon, the turns allowed on a steady red light are also allowed on a red arrow, so you may turn right after a complete stop and yielding, unless a sign or officer says not to.","p":"Right. You may turn after a complete stop and yielding."},"es":{"q":"En Oregon, usted está ante una flecha roja fija que apunta a la derecha. Ningún letrero ni agente indica otra cosa. ¿Qué puede hacer?","o":["Girar a la derecha después de detenerse por completo, cediendo el paso al tráfico y a los peatones","Esperar a que la flecha cambie a verde","Girar a la derecha sin detenerse","Girar a la derecha solo si un policía le hace señas"],"h1":"Oregon trata una flecha roja como una luz roja fija para los giros.","h2":"En Oregon, los giros permitidos con una luz roja fija también se permiten con una flecha roja, así que puede girar a la derecha después de detenerse por completo y ceder el paso, a menos que un letrero o un agente lo prohíba.","p":"Correcto. Puede girar después de detenerse por completo y ceder el paso."},"ref":{"doc":"OR","page":15}},{"id":"or-114","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, a yellow electronic sign says ADVISORY SPEED 40 because of ice. What is true?","o":["It is only a suggestion, and police can never ticket you for it","It is the new legal speed limit","It applies only to trucks","It is not a speed limit, but police may enforce it through the basic rule"],"h1":"Yellow advisory signs and black-and-white speed limit signs are treated differently.","h2":"In Oregon, yellow variable advisory speed signs are not speed limits, but police may enforce them through the basic rule law.","p":"Right. Police may enforce it through the basic rule."},"es":{"q":"En Oregon, un letrero electrónico amarillo dice ADVISORY SPEED 40 (velocidad recomendada 40) por el hielo. ¿Qué es cierto?","o":["Es solo una sugerencia, y la policía nunca le puede multar por ello","Es el nuevo límite de velocidad legal","Se aplica solo a los camiones","No es un límite de velocidad, pero la policía puede hacerlo cumplir mediante la regla básica"],"h1":"Los letreros amarillos de velocidad recomendada y los letreros blancos y negros de límite de velocidad se tratan de forma diferente.","h2":"En Oregon, los letreros amarillos variables de velocidad recomendada no son límites de velocidad, pero la policía puede hacerlos cumplir mediante la ley de la regla básica.","p":"Correcto. La policía puede hacerlo cumplir mediante la regla básica."},"ref":{"doc":"OR","page":20}},{"id":"or-115","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, what is the speed limit on an ocean shore where vehicles are allowed, when no other limit is posted?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is the same as the limit in a residential district.","h2":"In Oregon, the speed limit is 25 mph on ocean shores where vehicles are allowed, the same as in residential districts and public parks, unless another speed is posted.","p":"Right. The limit on an ocean shore is 25 mph."},"es":{"q":"En Oregon, ¿cuál es el límite de velocidad en una playa del océano donde se permiten vehículos, si no hay otro límite indicado?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es igual al límite en una zona residencial.","h2":"En Oregon, el límite de velocidad es de 25 mph en las playas del océano donde se permiten vehículos, igual que en zonas residenciales y parques públicos, a menos que se indique otra velocidad.","p":"Correcto. El límite en una playa del océano es de 25 mph."},"ref":{"doc":"OR","page":19}},{"id":"or-116","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, the driver manual shows how speed affects people walking. If a person is hit by a vehicle going 42 mph, what is the risk of death?","o":["10 percent","25 percent","50 percent","90 percent"],"h1":"At 23 mph the risk is 10 percent, and at 58 mph it is 90 percent.","h2":"The Oregon driver manual shows that a person hit by a vehicle going 42 mph has a 50 percent risk of death, compared with 10 percent at 23 mph.","p":"Right. At 42 mph, the risk of death is 50 percent."},"es":{"q":"En Oregon, el manual del conductor muestra cómo la velocidad afecta a los peatones. Si un vehículo que va a 42 mph atropella a una persona, ¿cuál es el riesgo de muerte?","o":["10 por ciento","25 por ciento","50 por ciento","90 por ciento"],"h1":"A 23 mph el riesgo es de 10 por ciento, y a 58 mph es de 90 por ciento.","h2":"El manual del conductor de Oregon muestra que una persona atropellada por un vehículo que va a 42 mph tiene un riesgo de muerte de 50 por ciento, comparado con 10 por ciento a 23 mph.","p":"Correcto. A 42 mph, el riesgo de muerte es de 50 por ciento."},"ref":{"doc":"OR","page":21}},{"id":"or-117","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, you are on a two-way road with no center line. A car comes toward you. How much of the road must you give it?","o":["At least half of the road","At least one quarter of the road","All of it; you must pull off the road","None; the first driver there may use the middle"],"h1":"Share the road fairly with the oncoming driver.","h2":"In Oregon, when a two-way road has no center line, you must give at least half of the road to oncoming traffic.","p":"Right. Give at least half of the road to oncoming traffic."},"es":{"q":"En Oregon, usted va por una calle de doble sentido sin línea central. Viene un auto hacia usted. ¿Cuánto de la calle le debe dejar?","o":["Por lo menos la mitad de la calle","Por lo menos una cuarta parte de la calle","Toda; usted debe salirse de la calle","Nada; el primero que llega puede usar el centro"],"h1":"Comparta la calle de forma justa con el conductor que viene.","h2":"En Oregon, cuando una calle de doble sentido no tiene línea central, usted debe dejar por lo menos la mitad de la calle al tráfico que viene en sentido contrario.","p":"Correcto. Deje por lo menos la mitad de la calle al tráfico que viene."},"ref":{"doc":"OR","page":18}},{"id":"or-118","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, a painted median ahead is filled with yellow diagonal stripes. You want to turn left across it into a driveway. What does the law say?","o":["You may turn after oncoming traffic clears","You may wait on the stripes, then turn","You may cross it only at night","You may not drive in or turn across the stripes"],"h1":"The stripes mark an area where vehicles are not allowed.","h2":"In Oregon, yellow diagonal stripes in a painted median mark fixed objects or areas where vehicles are not allowed, and it is illegal to drive in them or turn across them.","p":"Right. Do not drive in or turn across yellow diagonal stripes."},"es":{"q":"En Oregon, una mediana pintada más adelante está llena de rayas diagonales amarillas. Usted quiere girar a la izquierda cruzándola para entrar a una entrada de autos. ¿Qué dice la ley?","o":["Puede girar cuando pase el tráfico que viene","Puede esperar sobre las rayas y luego girar","Puede cruzarla solo de noche","No puede manejar sobre las rayas ni girar cruzándolas"],"h1":"Las rayas marcan una zona donde no se permiten vehículos.","h2":"En Oregon, las rayas diagonales amarillas en una mediana pintada marcan objetos fijos o zonas donde no se permiten vehículos, y es ilegal manejar sobre ellas o girar cruzándolas.","p":"Correcto. No maneje sobre rayas diagonales amarillas ni gire cruzándolas."},"ref":{"doc":"OR","page":23}},{"id":"or-119","scope":"OR","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Oregon, you are passing a slow car on a two-lane road with a 55 mph limit. You need more speed to finish the pass. What does the law say?","o":["You may go up to 10 mph over the limit to finish","You may not go over the speed limit, even when passing","You may speed if your signal is on","You may speed only on a straight road"],"h1":"Passing does not change the speed limit.","h2":"In Oregon, you may not exceed the speed limit when passing; it is against the law to exceed speed limits at any time.","p":"Right. Never go over the speed limit to pass."},"es":{"q":"En Oregon, usted está rebasando a un auto lento en una carretera de dos carriles con límite de 55 mph. Necesita más velocidad para terminar de rebasar. ¿Qué dice la ley?","o":["Puede ir hasta 10 mph sobre el límite para terminar","No puede pasar del límite de velocidad, ni siquiera al rebasar","Puede exceder el límite si tiene la direccional encendida","Puede exceder el límite solo en una carretera recta"],"h1":"Rebasar no cambia el límite de velocidad.","h2":"En Oregon, usted no puede exceder el límite de velocidad al rebasar; es contra la ley exceder los límites de velocidad en cualquier momento.","p":"Correcto. Nunca pase del límite de velocidad para rebasar."},"ref":{"doc":"OR","page":31}},{"id":"or-120","scope":"OR","cat":"signals","sign":null,"c":2,"en":{"q":"In Oregon, a car behind you wants to pass, and you can see the road ahead is clear. Should you flash your signals to tell the driver to go?","o":["Yes, flash your left turn signal","Yes, flash your right turn signal","No, the law forbids flashing your signals to tell drivers when to pass","Yes, or wave your hand out the window instead"],"h1":"Your job is to stay right and let the other driver decide.","h2":"In Oregon, the law prohibits flashing any of your signals to tell other drivers when to pass, and you should not use your hands either; stay to the right instead.","p":"Right. Do not signal other drivers when to pass."},"es":{"q":"En Oregon, un auto detrás de usted quiere rebasar, y usted ve que el camino adelante está libre. ¿Debe hacer parpadear sus luces de señal para decirle que pase?","o":["Sí, encienda la direccional izquierda","Sí, encienda la direccional derecha","No, la ley prohíbe usar sus luces de señal para decir a otros cuándo rebasar","Sí, o haga señas con la mano por la ventana"],"h1":"Su tarea es mantenerse a la derecha y dejar que el otro conductor decida.","h2":"En Oregon, la ley prohíbe usar cualquiera de sus luces de señal para decir a otros conductores cuándo rebasar, y tampoco debe usar las manos; manténgase a la derecha.","p":"Correcto. No le indique a otro conductor cuándo rebasar."},"ref":{"doc":"OR","page":33}},{"id":"or-121","scope":"OR","cat":"signals","sign":null,"c":0,"en":{"q":"In Oregon, you reach a freeway ramp meter, and all of its lights are dark. What should you do?","o":["Do not stop; the meter is not in use","Stop and wait for it to turn green","Stop, then go one car at a time","Back up and use another ramp"],"h1":"Ramp meters work only at certain times of day.","h2":"In Oregon, a dark ramp meter is not in use, so do not stop at it; speed up and merge with freeway traffic.","p":"Right. Do not stop at a dark ramp meter."},"es":{"q":"En Oregon, usted llega a un semáforo de rampa de la autopista y todas sus luces están apagadas. ¿Qué debe hacer?","o":["No se detenga; el semáforo no está en uso","Deténgase y espere a que cambie a verde","Deténgase y luego pase un auto a la vez","Retroceda y use otra rampa"],"h1":"Los semáforos de rampa funcionan solo a ciertas horas del día.","h2":"En Oregon, un semáforo de rampa apagado no está en uso, así que no se detenga; acelere y únase al tráfico de la autopista.","p":"Correcto. No se detenga ante un semáforo de rampa apagado."},"ref":{"doc":"OR","page":35}},{"id":"or-122","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, your friends want to ride inside a travel trailer that you tow with a regular ball hitch. Is that allowed?","o":["Yes, if they wear seat belts","Yes, on roads under 45 mph","Yes, if an adult rides with them","No; passengers may ride only in certain trailers, such as one towed with a fifth-wheel device"],"h1":"Oregon allows riders only in a few special kinds of trailers.","h2":"In Oregon, it is against the law for passengers to ride in a trailer, except a commercial bus trailer, an independently steered trailer, or a trailer towed with a fifth-wheel device.","p":"Right. Passengers may not ride in a regular towed trailer."},"es":{"q":"En Oregon, sus amigos quieren ir dentro de un remolque de viaje que usted jala con un enganche de bola común. ¿Está permitido?","o":["Sí, si usan cinturón de seguridad","Sí, en caminos de menos de 45 mph","Sí, si un adulto va con ellos","No; los pasajeros solo pueden ir en ciertos remolques, como uno jalado con un enganche de quinta rueda"],"h1":"Oregon permite pasajeros solo en unos pocos tipos especiales de remolque.","h2":"En Oregon, es contra la ley que los pasajeros vayan en un remolque, excepto en un remolque de autobús comercial, un remolque con dirección propia o un remolque jalado con un enganche de quinta rueda.","p":"Correcto. Los pasajeros no pueden ir en un remolque común."},"ref":{"doc":"OR","page":36}},{"id":"or-123","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, a first offense for towing a second trailer or vehicle behind your car can bring a fine of up to how much?","o":["$250","$1,000","$2,500","$5,000"],"h1":"The fine goes up to $2,000 for a second offense.","h2":"In Oregon, towing more than one trailer or vehicle can cost up to $1,000 for a first offense, up to $2,000 for a second, and up to $2,500 and six months in jail for a third.","p":"Right. A first offense can cost up to $1,000."},"es":{"q":"En Oregon, ¿hasta cuánto puede ser la multa por una primera infracción por jalar un segundo remolque o vehículo detrás de su auto?","o":["$250","$1,000","$2,500","$5,000"],"h1":"La multa sube hasta $2,000 en una segunda infracción.","h2":"En Oregon, jalar más de un remolque o vehículo puede costar hasta $1,000 la primera vez, hasta $2,000 la segunda, y hasta $2,500 y seis meses de cárcel la tercera.","p":"Correcto. Una primera infracción puede costar hasta $1,000."},"ref":{"doc":"OR","page":36}},{"id":"or-124","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, you want to turn right at the next corner, and there is a bike lane on your right. What should you do?","o":["Move into the bike lane early and turn from there","Drive in the bike lane for the last block","Stay in your lane, yield to people in the bike lane, then turn across it","Honk so riders leave the bike lane"],"h1":"You may cross a bike lane, but you may not use it to get ready.","h2":"In Oregon, you may turn across a bike lane, but you must not move into it to prepare for a turn, and you must yield to people riding in it.","p":"Right. Stay out of the bike lane until you turn, and yield."},"es":{"q":"En Oregon, usted quiere girar a la derecha en la próxima esquina y hay un carril de bicicletas a su derecha. ¿Qué debe hacer?","o":["Entrar al carril de bicicletas antes y girar desde ahí","Manejar por el carril de bicicletas la última cuadra","Quedarse en su carril, ceder el paso a quienes van en el carril de bicicletas y luego girar cruzándolo","Tocar el claxon para que los ciclistas salgan del carril"],"h1":"Puede cruzar un carril de bicicletas, pero no usarlo para prepararse.","h2":"En Oregon, usted puede girar cruzando un carril de bicicletas, pero no debe entrar en él para prepararse para el giro, y debe ceder el paso a quienes van en él.","p":"Correcto. No entre al carril de bicicletas antes de girar, y ceda el paso."},"ref":{"doc":"OR","page":39}},{"id":"or-125","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, may you make a U-turn at an intersection controlled by a traffic signal?","o":["Only if a sign permits it","Yes, on any green light","Yes, on any green arrow","Yes, if no cars are coming"],"h1":"Look for a sign at the intersection.","h2":"In Oregon, U-turns are prohibited at intersections controlled by a traffic signal, unless a sign permits the turn.","p":"Right. Only when a sign permits it."},"es":{"q":"En Oregon, ¿puede dar una vuelta en U en una intersección controlada por un semáforo?","o":["Solo si un letrero lo permite","Sí, con cualquier luz verde","Sí, con cualquier flecha verde","Sí, si no vienen autos"],"h1":"Busque un letrero en la intersección.","h2":"En Oregon, las vueltas en U están prohibidas en intersecciones controladas por un semáforo, a menos que un letrero permita la vuelta.","p":"Correcto. Solo cuando un letrero lo permite."},"ref":{"doc":"OR","page":41}},{"id":"or-126","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, you reach an intersection with no signs or signals at the same time as a car coming from your right. Who should go first?","o":["You, because you are going straight","The faster car","The driver who honks first","The car on your right"],"h1":"Look left first, but give way toward the right.","h2":"In Oregon, at an intersection with no signs or signals, you must yield to any vehicle already in the intersection or coming from your right.","p":"Right. Yield to the car on your right."},"es":{"q":"En Oregon, usted llega a una intersección sin letreros ni semáforos al mismo tiempo que un auto que viene por su derecha. ¿Quién debe pasar primero?","o":["Usted, porque va derecho","El auto más rápido","El conductor que toque primero el claxon","El auto de su derecha"],"h1":"Mire primero a la izquierda, pero ceda el paso hacia la derecha.","h2":"En Oregon, en una intersección sin letreros ni semáforos, usted debe ceder el paso a cualquier vehículo que ya esté en la intersección o que venga por su derecha.","p":"Correcto. Ceda el paso al auto de su derecha."},"ref":{"doc":"OR","page":42}},{"id":"or-127","scope":"OR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oregon, a person in a wheelchair rolls off the curb into a crosswalk. When is this person legally crossing the road?","o":["Only once the person reaches your lane","As soon as any part of the person or the wheelchair moves onto the road","Never; only people walking count","Only when the walk signal is on"],"h1":"Oregon counts things like canes, wheelchairs and bicycles as part of the person.","h2":"In Oregon, a pedestrian is crossing the road as soon as any part or extension of them, such as a cane, wheelchair or bicycle, moves onto the road.","p":"Right. Crossing starts as soon as any part moves onto the road."},"es":{"q":"En Oregon, una persona en silla de ruedas baja de la acera a un cruce peatonal. ¿Cuándo está esa persona cruzando la calle según la ley?","o":["Solo cuando llega a su carril","En cuanto cualquier parte de la persona o de la silla de ruedas entra a la calle","Nunca; solo cuentan las personas que caminan","Solo cuando la señal de cruce está encendida"],"h1":"Oregon cuenta cosas como bastones, sillas de ruedas y bicicletas como parte de la persona.","h2":"En Oregon, un peatón está cruzando la calle en cuanto cualquier parte o extensión de él, como un bastón, una silla de ruedas o una bicicleta, entra a la calle.","p":"Correcto. El cruce empieza en cuanto cualquier parte entra a la calle."},"ref":{"doc":"OR","page":46}},{"id":"or-128","scope":"OR","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Oregon, a person is in a crosswalk on the far side of a safety island from your lane. Must you stop?","o":["Yes, always stop for anyone in a crosswalk","Yes, and wait until the person reaches the curb","No, you are not required to stop","Only if the person waves at you"],"h1":"The island separates the person from your side of the road.","h2":"In Oregon, you are not required to stop for a pedestrian who is in a crosswalk on the other side of a safety island.","p":"Right. You do not have to stop for a person beyond a safety island."},"es":{"q":"En Oregon, una persona está en un cruce peatonal del otro lado de una isla de seguridad, lejos de su carril. ¿Debe detenerse?","o":["Sí, siempre deténgase por cualquier persona en un cruce","Sí, y espere hasta que la persona llegue a la acera","No, no está obligado a detenerse","Solo si la persona le hace señas"],"h1":"La isla separa a la persona de su lado de la calle.","h2":"En Oregon, usted no está obligado a detenerse por un peatón que está en un cruce peatonal del otro lado de una isla de seguridad.","p":"Correcto. No tiene que detenerse por una persona al otro lado de una isla de seguridad."},"ref":{"doc":"OR","page":47}},{"id":"or-129","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, an intersection has no painted crosswalk lines. Is there a crosswalk there?","o":["Yes, an unmarked crosswalk at least 6 feet wide","No, a crosswalk must be painted","Only if there is a sidewalk","Only near a school"],"h1":"Imagine the sidewalk or shoulder at the corner reaching across the road.","h2":"In Oregon, there is a crosswalk at every intersection, even if it is not painted, and an unmarked crosswalk is at least 6 feet wide even where there is no sidewalk or shoulder.","p":"Right. Every intersection has a crosswalk, at least 6 feet wide."},"es":{"q":"En Oregon, una intersección no tiene líneas pintadas de cruce peatonal. ¿Hay un cruce peatonal ahí?","o":["Sí, un cruce peatonal sin marcar de por lo menos 6 pies de ancho","No, un cruce peatonal tiene que estar pintado","Solo si hay acera","Solo cerca de una escuela"],"h1":"Imagine que la acera o el acotamiento de la esquina cruza la calle.","h2":"En Oregon, hay un cruce peatonal en cada intersección, aunque no esté pintado, y un cruce sin marcar mide por lo menos 6 pies de ancho aunque no haya acera ni acotamiento.","p":"Correcto. Cada intersección tiene un cruce peatonal de por lo menos 6 pies de ancho."},"ref":{"doc":"OR","page":47}},{"id":"or-130","scope":"OR","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Oregon, the car in the lane next to you has stopped at a crosswalk. You do not see anyone crossing. May you pass it?","o":["Yes, if you slow down","Yes, if you honk first","Yes, if the other driver waves you on","No, passing a vehicle stopped at a crosswalk is against the law"],"h1":"The other driver may see someone you cannot see.","h2":"In Oregon, it is against the law to pass a vehicle stopped at a crosswalk, because the driver may be waiting for a pedestrian to cross.","p":"Right. Never pass a vehicle stopped at a crosswalk."},"es":{"q":"En Oregon, el auto del carril de al lado se detuvo en un cruce peatonal. Usted no ve a nadie cruzando. ¿Puede pasarlo?","o":["Sí, si baja la velocidad","Sí, si toca el claxon primero","Sí, si el otro conductor le hace señas","No, es contra la ley pasar a un vehículo detenido en un cruce peatonal"],"h1":"El otro conductor puede ver a alguien que usted no ve.","h2":"En Oregon, es contra la ley pasar a un vehículo detenido en un cruce peatonal, porque el conductor puede estar esperando a que cruce un peatón.","p":"Correcto. Nunca pase a un vehículo detenido en un cruce peatonal."},"ref":{"doc":"OR","page":47}},{"id":"or-131","scope":"OR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oregon, a person on a motorized scooter is using the bike lane next to you. You want to turn right across the bike lane. What must you do?","o":["Turn ahead of them; scooters must yield to cars","Yield to them as you would to a person on a bicycle","Nothing; scooters may not use bike lanes","Honk so they stop"],"h1":"Oregon lets these riders use bike lanes and protects them the same way.","h2":"In Oregon, people using motorized wheelchairs, scooters and personal assistive mobility devices may use bike lanes and paths, and you must yield to them as you would to a person on a bicycle.","p":"Right. Yield to them as you would to a bicycle rider."},"es":{"q":"En Oregon, una persona en un scooter motorizado va por el carril de bicicletas junto a usted. Usted quiere girar a la derecha cruzando ese carril. ¿Qué debe hacer?","o":["Girar delante de ella; los scooters deben ceder el paso a los autos","Cederle el paso como lo haría con una persona en bicicleta","Nada; los scooters no pueden usar los carriles de bicicletas","Tocar el claxon para que se detenga"],"h1":"Oregon permite a estas personas usar los carriles de bicicletas y las protege de la misma manera.","h2":"En Oregon, las personas en sillas de ruedas motorizadas, scooters y aparatos personales de movilidad pueden usar los carriles y caminos de bicicletas, y usted debe cederles el paso como lo haría con una persona en bicicleta.","p":"Correcto. Cédale el paso como a un ciclista."},"ref":{"doc":"OR","page":51}},{"id":"or-132","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, compared with a smaller vehicle at the same speed, about how much distance does a large truck or bus need to stop?","o":["About the same distance","About half the distance","About three times the distance","About ten times the distance"],"h1":"It is much more than a car needs, but not ten times more.","h2":"In Oregon, the manual says large vehicles take about three times the distance to stop than smaller vehicles at the same speed.","p":"Right. A large vehicle needs about three times the distance to stop."},"es":{"q":"En Oregon, comparado con un vehículo más pequeño a la misma velocidad, ¿cuánta distancia más o menos necesita un camión grande o un autobús para detenerse?","o":["Más o menos la misma distancia","Más o menos la mitad de la distancia","Más o menos tres veces la distancia","Más o menos diez veces la distancia"],"h1":"Es mucho más de lo que necesita un auto, pero no diez veces más.","h2":"En Oregon, el manual dice que los vehículos grandes necesitan más o menos tres veces la distancia para detenerse que los vehículos más pequeños a la misma velocidad.","p":"Correcto. Un vehículo grande necesita unas tres veces la distancia para detenerse."},"ref":{"doc":"OR","page":53}},{"id":"or-133","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, you are on a four-lane road with a painted center turn lane. A school bus coming the other way stops with red lights flashing. What must you do?","o":["Stop; a painted median or turn lane does not make two separate roads","Keep going, because you are on the other side","Slow to 20 mph and pass carefully","Stop only if children are in your lane"],"h1":"Only an unpaved median or a barrier makes two separate roads.","h2":"In Oregon, a painted median strip or center turn lane does not create two separate roads, so traffic in all lanes must stop for a school bus with flashing red lights.","p":"Right. All lanes must stop."},"es":{"q":"En Oregon, usted va por una calle de cuatro carriles con un carril central de giro pintado. Un autobús escolar que viene en sentido contrario se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse; una mediana o carril de giro pintado no forma dos calles separadas","Seguir, porque usted está del otro lado","Bajar a 20 mph y pasar con cuidado","Detenerse solo si hay niños en su carril"],"h1":"Solo una mediana sin pavimentar o una barrera forma dos calles separadas.","h2":"En Oregon, una mediana pintada o un carril central de giro no forma dos calles separadas, así que el tráfico de todos los carriles debe detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. Todos los carriles deben detenerse."},"ref":{"doc":"OR","page":55}},{"id":"or-134","scope":"OR","cat":"signals","sign":null,"c":3,"en":{"q":"In Oregon, farm equipment ahead shows an emblem with a red reflective border and a bright orange center. What does it mean?","o":["The driver is about to turn left","It is carrying hazardous materials","It is a pilot vehicle for a wide load","It is a slow moving vehicle, so be ready to slow down"],"h1":"Farm equipment usually travels much slower than other traffic.","h2":"In Oregon, slow moving vehicles such as farm equipment must show the SLOW MOVING VEHICLE emblem, with a red reflective border and an orange center, so be ready to slow down or adjust your position.","p":"Right. It marks a slow moving vehicle."},"es":{"q":"En Oregon, una máquina agrícola adelante muestra un emblema con borde rojo reflectante y centro anaranjado brillante. ¿Qué significa?","o":["El conductor está por girar a la izquierda","Lleva materiales peligrosos","Es un vehículo guía de una carga ancha","Es un vehículo lento, así que prepárese para bajar la velocidad"],"h1":"La maquinaria agrícola suele ir mucho más lento que el resto del tráfico.","h2":"En Oregon, los vehículos lentos, como la maquinaria agrícola, deben mostrar el emblema de VEHÍCULO LENTO, con borde rojo reflectante y centro anaranjado, así que prepárese para bajar la velocidad o cambiar su posición.","p":"Correcto. Indica un vehículo lento."},"ref":{"doc":"OR","page":56}},{"id":"or-135","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, in daylight, your load sticks out 5 feet past the back of your pickup. What must you put on the end of it?","o":["A white cloth of any size","A red flag at least 12 inches square","A yellow flashing light","Nothing; only loads over 6 feet need a flag"],"h1":"The rule starts at 4 feet past the rear.","h2":"In Oregon, a load that extends 4 feet or more past the rear of a vehicle must have a red flag at least 12 inches square at the end, and a red light when visibility is limited.","p":"Right. Use a red flag at least 12 inches square."},"es":{"q":"En Oregon, de día, su carga sobresale 5 pies por detrás de su pickup. ¿Qué debe poner en el extremo?","o":["Un trapo blanco de cualquier tamaño","Una bandera roja de por lo menos 12 pulgadas por lado","Una luz amarilla intermitente","Nada; solo las cargas de más de 6 pies necesitan bandera"],"h1":"La regla empieza a los 4 pies por detrás.","h2":"En Oregon, una carga que sobresale 4 pies o más por detrás de un vehículo debe llevar en el extremo una bandera roja de por lo menos 12 pulgadas por lado, y una luz roja cuando hay poca visibilidad.","p":"Correcto. Use una bandera roja de por lo menos 12 pulgadas por lado."},"ref":{"doc":"OR","page":56}},{"id":"or-136","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, how far may a load stick out past the right fenders of a passenger vehicle?","o":["Not at all","Up to 2 feet","No more than 6 inches","Up to 4 feet"],"h1":"On the left side, a load may not stick out at all.","h2":"In Oregon, a load on a passenger vehicle may not extend more than 6 inches past the right fenders, and may not extend past the left fenders at all.","p":"Right. No more than 6 inches past the right fenders."},"es":{"q":"En Oregon, ¿cuánto puede sobresalir una carga por fuera de las salpicaderas derechas de un vehículo de pasajeros?","o":["Nada","Hasta 2 pies","No más de 6 pulgadas","Hasta 4 pies"],"h1":"Del lado izquierdo, una carga no puede sobresalir nada.","h2":"En Oregon, una carga en un vehículo de pasajeros no puede sobresalir más de 6 pulgadas por fuera de las salpicaderas derechas, y no puede sobresalir nada por fuera de las izquierdas.","p":"Correcto. No más de 6 pulgadas por fuera de las salpicaderas derechas."},"ref":{"doc":"OR","page":56}},{"id":"or-137","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, a funeral procession is passing, and there is a gap between two of its cars. May you drive into the gap to get through?","o":["No, it is against the law to join or drive between vehicles in the procession","Yes, if the gap is big enough","Yes, if you turn on your headlights","Yes, if your light is green"],"h1":"Other drivers must yield to the whole procession.","h2":"In Oregon, you must yield to funeral processions, and it is against the law to join one or drive between its vehicles if you are not part of it.","p":"Right. Never drive between vehicles in a funeral procession."},"es":{"q":"En Oregon, pasa un cortejo fúnebre y hay un espacio entre dos de sus autos. ¿Puede meterse en ese espacio para pasar?","o":["No, es contra la ley unirse al cortejo o manejar entre sus vehículos","Sí, si el espacio es grande","Sí, si enciende los faros","Sí, si tiene luz verde"],"h1":"Los demás conductores deben ceder el paso a todo el cortejo.","h2":"En Oregon, usted debe ceder el paso a los cortejos fúnebres, y es contra la ley unirse a uno o manejar entre sus vehículos si no forma parte de él.","p":"Correcto. Nunca maneje entre los vehículos de un cortejo fúnebre."},"ref":{"doc":"OR","page":57}},{"id":"or-138","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, you come to a fire scene, and fire hoses are lying across the road. What should you do?","o":["Drive over them slowly","Drive over them quickly so you do not block traffic","Honk so firefighters move them","Do not drive over them unless officials at the scene tell you to"],"h1":"Wait for directions from the people in charge.","h2":"In Oregon, at an emergency scene you should slow down, be ready to stop, and not drive over fire hoses unless officials at the scene tell you to.","p":"Right. Do not drive over fire hoses unless told to."},"es":{"q":"En Oregon, usted llega a un incendio y hay mangueras de bomberos atravesadas en la calle. ¿Qué debe hacer?","o":["Pasar sobre ellas despacio","Pasar sobre ellas rápido para no bloquear el tráfico","Tocar el claxon para que los bomberos las muevan","No pasar sobre ellas a menos que los encargados en el lugar se lo indiquen"],"h1":"Espere las indicaciones de las personas a cargo.","h2":"En Oregon, en una emergencia usted debe bajar la velocidad, estar listo para detenerse y no pasar sobre las mangueras de bomberos a menos que los encargados en el lugar se lo indiquen.","p":"Correcto. No pase sobre mangueras de bomberos a menos que se lo indiquen."},"ref":{"doc":"OR","page":57}},{"id":"or-139","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, a police officer pulls you over after dark. What should you do after you stop, before the officer reaches your car?","o":["Get out and walk to the police car","Turn on the light inside your car","Search the glove box for your papers","Turn on your high beams"],"h1":"Help the officer see you and your hands clearly.","h2":"In Oregon, if you are stopped by police in the dark, turn on your interior light after stopping and before the officer approaches, and keep your hands on the steering wheel.","p":"Right. Turn on your interior light."},"es":{"q":"En Oregon, un policía le indica que se detenga cuando ya está oscuro. ¿Qué debe hacer después de detenerse y antes de que el agente llegue a su auto?","o":["Bajarse y caminar hacia la patrulla","Encender la luz dentro de su auto","Buscar sus papeles en la guantera","Encender las luces altas"],"h1":"Ayude al agente a verlo a usted y a sus manos con claridad.","h2":"En Oregon, si la policía lo detiene cuando está oscuro, encienda la luz interior después de detenerse y antes de que el agente se acerque, y mantenga las manos en el volante.","p":"Correcto. Encienda la luz interior."},"ref":{"doc":"OR","page":58}},{"id":"or-140","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, what happens to traffic fines in a work zone?","o":["They stay the same","They go up by $50","They are doubled","They go up only when workers are present"],"h1":"The rule applies in all work zones.","h2":"In Oregon, traffic fines are doubled in all work zones.","p":"Right. Fines are doubled in work zones."},"es":{"q":"En Oregon, ¿qué pasa con las multas de tránsito en una zona de obras?","o":["Siguen igual","Suben $50","Se duplican","Suben solo cuando hay trabajadores presentes"],"h1":"La regla se aplica en todas las zonas de obras.","h2":"En Oregon, las multas de tránsito se duplican en todas las zonas de obras.","p":"Correcto. Las multas se duplican en las zonas de obras."},"ref":{"doc":"OR","page":59}},{"id":"or-141","scope":"OR","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Oregon, you are following a school bus toward a railroad crossing. No train is in sight. What should you expect?","o":["The bus must stop at the tracks, so be ready to stop too","The bus will speed up to cross quickly","The bus will pull onto the shoulder to let you pass","The bus will cross without slowing down"],"h1":"Some vehicles must always stop at railroad tracks.","h2":"In Oregon, all school buses, vehicles carrying hazardous materials and some school activity vehicles must stop at railroad tracks, so be prepared to stop when you follow them.","p":"Right. The bus must stop, so be ready to stop."},"es":{"q":"En Oregon, usted va detrás de un autobús escolar hacia un cruce de ferrocarril. No se ve ningún tren. ¿Qué debe esperar?","o":["El autobús debe detenerse en las vías, así que prepárese para detenerse también","El autobús acelerará para cruzar rápido","El autobús se orillará para dejarle pasar","El autobús cruzará sin bajar la velocidad"],"h1":"Algunos vehículos siempre deben detenerse en las vías del tren.","h2":"En Oregon, todos los autobuses escolares, los vehículos con materiales peligrosos y algunos vehículos de actividades escolares deben detenerse en las vías del tren, así que prepárese para detenerse cuando vaya detrás de ellos.","p":"Correcto. El autobús debe detenerse, así que prepárese para detenerse."},"ref":{"doc":"OR","page":63}},{"id":"or-142","scope":"OR","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Oregon, a streetcar going the same way as you is stopped in the lane next to you. You want to turn across its path. What must you do?","o":["Turn quickly before it starts moving","Do not turn in front of it, even while it is stopped","Honk, then turn","Turn if no passengers are getting on"],"h1":"Streetcars cannot stop quickly and may start moving at any time.","h2":"In Oregon, you must never turn in front of a streetcar or train traveling in the same direction from the lane next to you, even if it is stopped.","p":"Right. Never turn in front of it, even when it is stopped."},"es":{"q":"En Oregon, un tranvía que va en su misma dirección está detenido en el carril de al lado. Usted quiere girar cruzando por delante de él. ¿Qué debe hacer?","o":["Girar rápido antes de que arranque","No girar delante de él, aunque esté detenido","Tocar el claxon y luego girar","Girar si no están subiendo pasajeros"],"h1":"Los tranvías no pueden detenerse rápido y pueden arrancar en cualquier momento.","h2":"En Oregon, usted nunca debe girar delante de un tranvía o tren que va en su misma dirección en el carril de al lado, aunque esté detenido.","p":"Correcto. Nunca gire delante de él, aunque esté detenido."},"ref":{"doc":"OR","page":66}},{"id":"or-143","scope":"OR","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Oregon, how close may you park to the driveway entrance of a fire station on the same side of the street?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 15 feet"],"h1":"The distance across the street is 75 feet; on the same side it is much shorter.","h2":"In Oregon, you may not park within 15 feet of a fire station driveway on the same side of the street, or within 75 feet on the opposite side.","p":"Right. Stay at least 15 feet away on the same side."},"es":{"q":"En Oregon, ¿qué tan cerca puede estacionarse de la entrada de vehículos de una estación de bomberos del mismo lado de la calle?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 50 pies","No más cerca de 15 pies"],"h1":"Del otro lado de la calle son 75 pies; del mismo lado es mucho menos.","h2":"En Oregon, no puede estacionarse a menos de 15 pies de la entrada de una estación de bomberos del mismo lado de la calle, ni a menos de 75 pies del lado opuesto.","p":"Correcto. Quédese por lo menos a 15 pies del mismo lado."},"ref":{"doc":"OR","page":71}},{"id":"or-144","scope":"OR","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Oregon, you park 30 feet before a stop sign, and your car hides the sign from other drivers. Is this legal?","o":["Yes, 30 feet is far enough","Yes, if you stay in the car","No, you may not park within 50 feet of a sign or signal if your car hides it","No, you may never park on a street with a stop sign"],"h1":"The rule is about blocking the view of the sign.","h2":"In Oregon, you may not park within 50 feet of a traffic sign or signal if your vehicle hides it from view.","p":"Right. Do not park within 50 feet if your car hides the sign."},"es":{"q":"En Oregon, usted se estaciona 30 pies antes de un letrero de alto, y su auto tapa el letrero para otros conductores. ¿Es legal?","o":["Sí, 30 pies es suficiente distancia","Sí, si se queda en el auto","No, no puede estacionarse a menos de 50 pies de un letrero o semáforo si su auto lo tapa","No, nunca puede estacionarse en una calle con letrero de alto"],"h1":"La regla trata de no tapar la vista del letrero.","h2":"En Oregon, no puede estacionarse a menos de 50 pies de un letrero o semáforo si su vehículo lo tapa.","p":"Correcto. No se estacione a menos de 50 pies si su auto tapa el letrero."},"ref":{"doc":"OR","page":71}},{"id":"or-145","scope":"OR","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Oregon, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Toward the travel lane","Straight ahead","It does not matter if the parking brake is set"],"h1":"If the brake fails, the curb should stop the car from rolling.","h2":"In Oregon, when you park facing downhill against a curb, set the parking brake and turn your front wheels toward the curb.","p":"Right. Turn your wheels toward the curb."},"es":{"q":"En Oregon, usted se estaciona cuesta abajo junto a una acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la acera","Hacia el carril de circulación","Derechas hacia adelante","No importa si el freno de mano está puesto"],"h1":"Si el freno falla, la acera debe detener el auto.","h2":"En Oregon, cuando se estaciona cuesta abajo junto a una acera, ponga el freno de mano y gire las ruedas delanteras hacia la acera.","p":"Correcto. Gire las ruedas hacia la acera."},"ref":{"doc":"OR","page":69}},{"id":"or-146","scope":"OR","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Oregon, it is daytime, but heavy rain makes it hard to see. Your headlights must be on when you cannot see people or vehicles how far ahead?","o":["500 feet","1,000 feet","200 feet","1 mile"],"h1":"It is the same distance you must be able to see before using hand signals.","h2":"In Oregon, headlights must be on from sunset to sunrise, and any time conditions make it hard to see people or vehicles 1,000 feet ahead.","p":"Right. Headlights must be on when you cannot see 1,000 feet ahead."},"es":{"q":"En Oregon, es de día, pero la lluvia fuerte hace difícil ver. ¿Sus faros deben estar encendidos cuando no puede ver personas o vehículos a qué distancia?","o":["500 pies","1,000 pies","200 pies","1 milla"],"h1":"Es la misma distancia que debe poder ver antes de usar señales con la mano.","h2":"En Oregon, los faros deben estar encendidos desde la puesta hasta la salida del sol, y en cualquier momento en que sea difícil ver personas o vehículos a 1,000 pies adelante.","p":"Correcto. Los faros deben estar encendidos si no puede ver a 1,000 pies."},"ref":{"doc":"OR","page":76}},{"id":"or-147","scope":"OR","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Oregon, it is getting dark. May you drive with only your parking lights on?","o":["Yes, until it is fully dark","Yes, in a city with streetlights","Yes, if you drive slowly","No, it is illegal to drive at night or in bad weather with only parking lights on"],"h1":"Parking lights are for a vehicle that is stopped or parked.","h2":"In Oregon, it is illegal to drive at night or in bad weather with only your parking lights on.","p":"Right. Never drive with only parking lights on."},"es":{"q":"En Oregon, está oscureciendo. ¿Puede manejar solo con las luces de estacionamiento encendidas?","o":["Sí, hasta que esté completamente oscuro","Sí, en una ciudad con alumbrado público","Sí, si maneja despacio","No, es ilegal manejar de noche o con mal tiempo solo con las luces de estacionamiento"],"h1":"Las luces de estacionamiento son para un vehículo detenido o estacionado.","h2":"En Oregon, es ilegal manejar de noche o con mal tiempo solo con las luces de estacionamiento encendidas.","p":"Correcto. Nunca maneje solo con las luces de estacionamiento."},"ref":{"doc":"OR","page":76}},{"id":"or-148","scope":"OR","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Oregon, you hit and injure a dog with your car, and you cannot find its owner. What must you do?","o":["Drive on, because it was an accident","Take the dog home with you","Report it to local law enforcement","Wait 24 hours, then call DMV"],"h1":"Someone in authority needs to know when the owner cannot be found.","h2":"In Oregon, if you hit and injure a domestic animal, stop and check on it, report the injury to the owner right away, and if you cannot find the owner, report it to local law enforcement.","p":"Right. Report it to local law enforcement."},"es":{"q":"En Oregon, usted atropella y lastima a un perro con su auto y no puede encontrar al dueño. ¿Qué debe hacer?","o":["Seguir manejando, porque fue un accidente","Llevarse el perro a su casa","Informar a la policía local","Esperar 24 horas y luego llamar al DMV"],"h1":"Alguna autoridad debe saberlo cuando no se encuentra al dueño.","h2":"En Oregon, si atropella y lastima a un animal doméstico, deténgase y revíselo, informe de inmediato al dueño, y si no puede encontrarlo, informe a la policía local.","p":"Correcto. Informe a la policía local."},"ref":{"doc":"OR","page":75}},{"id":"pa-001","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the youngest age to apply for a learner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is later than in many other states.","h2":"In Pennsylvania you can apply for a learner's permit once you turn 16, with a parent or guardian's consent.","p":"Right. The Pennsylvania permit starts at 16."},"es":{"q":"En Pensilvania, ¿cuál es la edad mínima para solicitar el permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es más tarde que en muchos otros estados.","h2":"En Pensilvania usted puede solicitar el permiso de aprendiz al cumplir 16 años, con el consentimiento de su padre, madre o tutor.","p":"Correcto. El permiso en Pensilvania empieza a los 16."},"zh":{"q":"在 Pennsylvania，最小几岁可以申请学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比很多其他州晚。","h2":"在 Pennsylvania，你满 16 岁并得到父母或监护人同意后，就可以申请学习驾照。","p":"对。Pennsylvania 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Pennsylvania, tuổi nhỏ nhất để nộp đơn xin giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Tuổi này muộn hơn ở nhiều tiểu bang khác.","h2":"Ở Pennsylvania, bạn có thể nộp đơn xin giấy phép tập lái khi đủ 16 tuổi, có sự đồng ý của cha mẹ hoặc người giám hộ.","p":"Đúng. Giấy phép tập lái ở Pennsylvania bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Pennsylvania, ano ang pinakabatang edad para mag-apply ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli ito kaysa sa maraming ibang estado.","h2":"Sa Pennsylvania, puwede kang mag-apply ng learner's permit pagdating mo ng 16, kung may pahintulot ng magulang o guardian.","p":"Tama. Sa Pennsylvania, nagsisimula ang permit sa 16."},"ar":{"q":"في Pennsylvania، ما أصغر سن يمكنك فيه التقدم لتصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو أكبر من السن في كثير من الولايات الأخرى.","h2":"في Pennsylvania يمكنك التقدم لتصريح تعلّم القيادة عندما تبلغ 16 سنة، بموافقة أحد الوالدين أو الوصي.","p":"صحيح. تصريح التعلّم في Pennsylvania يبدأ من سن 16."},"ref":{"doc":"PA","page":1}},{"id":"pa-002","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many questions are on the learner's permit knowledge test?","o":["10 questions","18 questions","25 questions","50 questions"],"h1":"It is fewer than 20.","h2":"The Pennsylvania knowledge test has 18 multiple-choice questions.","p":"Right. The test has 18 questions."},"es":{"q":"En Pensilvania, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["10 preguntas","18 preguntas","25 preguntas","50 preguntas"],"h1":"Son menos de 20.","h2":"El examen de conocimientos de Pensilvania tiene 18 preguntas de opción múltiple.","p":"Correcto. El examen tiene 18 preguntas."},"zh":{"q":"在 Pennsylvania，学习驾照的笔试有多少道题？","o":["10 道题","18 道题","25 道题","50 道题"],"h1":"少于 20 道。","h2":"Pennsylvania 的笔试有 18 道选择题。","p":"对。笔试有 18 道题。"},"vi":{"q":"Ở Pennsylvania, bài thi kiến thức để lấy giấy phép tập lái có bao nhiêu câu hỏi?","o":["10 câu","18 câu","25 câu","50 câu"],"h1":"Ít hơn 20 câu.","h2":"Bài thi kiến thức ở Pennsylvania có 18 câu hỏi trắc nghiệm.","p":"Đúng. Bài thi có 18 câu."},"tl":{"q":"Sa Pennsylvania, ilang tanong ang nasa knowledge test para sa learner's permit?","o":["10 tanong","18 tanong","25 tanong","50 tanong"],"h1":"Mas kaunti ito sa 20.","h2":"Ang knowledge test ng Pennsylvania ay may 18 multiple-choice na tanong.","p":"Tama. May 18 tanong ang test."},"ar":{"q":"في Pennsylvania، كم سؤالًا في الاختبار النظري لتصريح تعلّم القيادة؟","o":["10 أسئلة","18 سؤالًا","25 سؤالًا","50 سؤالًا"],"h1":"العدد أقل من 20.","h2":"الاختبار النظري في Pennsylvania فيه 18 سؤالًا من نوع الاختيار من متعدد.","p":"صحيح. في الاختبار 18 سؤالًا."},"ref":{"doc":"PA","page":5}},{"id":"pa-003","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many questions must you answer correctly to pass the knowledge test?","o":["9","12","18","15"],"h1":"You may miss only three.","h2":"To pass the Pennsylvania knowledge test you must answer 15 of the 18 questions correctly.","p":"Right. You need 15 correct answers."},"es":{"q":"En Pensilvania, ¿cuántas preguntas debe contestar bien para aprobar el examen de conocimientos?","o":["9","12","18","15"],"h1":"Solo puede fallar tres.","h2":"Para aprobar el examen de conocimientos de Pensilvania debe contestar bien 15 de las 18 preguntas.","p":"Correcto. Necesita 15 respuestas correctas."},"zh":{"q":"在 Pennsylvania，笔试要答对多少道题才能通过？","o":["9","12","18","15"],"h1":"你最多只能答错三道。","h2":"要通过 Pennsylvania 的笔试，18 道题中你必须答对 15 道。","p":"对。你需要答对 15 道。"},"vi":{"q":"Ở Pennsylvania, bạn phải trả lời đúng bao nhiêu câu để đậu bài thi kiến thức?","o":["9","12","18","15"],"h1":"Bạn chỉ được sai ba câu.","h2":"Để đậu bài thi kiến thức ở Pennsylvania, bạn phải trả lời đúng 15 trên 18 câu.","p":"Đúng. Bạn cần 15 câu đúng."},"tl":{"q":"Sa Pennsylvania, ilang tanong ang dapat mong masagot nang tama para pumasa sa knowledge test?","o":["9","12","18","15"],"h1":"Tatlo lang ang puwede mong mali.","h2":"Para pumasa sa knowledge test ng Pennsylvania, dapat mong masagot nang tama ang 15 sa 18 tanong.","p":"Tama. Kailangan mo ng 15 tamang sagot."},"ar":{"q":"في Pennsylvania، كم سؤالًا يجب أن تجيب عنه إجابة صحيحة لتنجح في الاختبار النظري؟","o":["9","12","18","15"],"h1":"يمكنك أن تخطئ في ثلاثة أسئلة فقط.","h2":"لتنجح في الاختبار النظري في Pennsylvania يجب أن تجيب إجابة صحيحة عن 15 سؤالًا من 18.","p":"صحيح. تحتاج إلى 15 إجابة صحيحة."},"ref":{"doc":"PA","page":5}},{"id":"pa-004","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, if you are under 18, how long must you wait after getting your learner's permit before taking the road test?","o":["Six months","One month","Three months","Two years"],"h1":"It is half a year.","h2":"In Pennsylvania a driver under 18 may not take the road test until six months after receiving the learner's permit.","p":"Right. Wait six months."},"es":{"q":"En Pensilvania, si usted es menor de 18 años, ¿cuánto tiempo debe esperar después de obtener el permiso de aprendiz para hacer el examen de manejo?","o":["Seis meses","Un mes","Tres meses","Dos años"],"h1":"Es medio año.","h2":"En Pensilvania un conductor menor de 18 años no puede hacer el examen de manejo hasta seis meses después de recibir el permiso de aprendiz.","p":"Correcto. Debe esperar seis meses."},"zh":{"q":"在 Pennsylvania，如果你未满 18 岁，拿到学习驾照后要等多久才能考路考？","o":["六个月","一个月","三个月","两年"],"h1":"是半年。","h2":"在 Pennsylvania，未满 18 岁的司机拿到学习驾照六个月以后，才可以考路考。","p":"对。要等六个月。"},"vi":{"q":"Ở Pennsylvania, nếu bạn dưới 18 tuổi, sau khi có giấy phép tập lái bạn phải chờ bao lâu mới được thi lái xe trên đường?","o":["Sáu tháng","Một tháng","Ba tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Pennsylvania, người lái dưới 18 tuổi chỉ được thi lái xe trên đường sau sáu tháng kể từ khi nhận giấy phép tập lái.","p":"Đúng. Chờ sáu tháng."},"tl":{"q":"Sa Pennsylvania, kung wala ka pang 18, gaano katagal ka dapat maghintay matapos makuha ang learner's permit bago kumuha ng road test?","o":["Anim na buwan","Isang buwan","Tatlong buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Pennsylvania, ang driver na wala pang 18 ay hindi puwedeng kumuha ng road test hangga't hindi pa lumilipas ang anim na buwan mula nang matanggap ang learner's permit.","p":"Tama. Maghintay ng anim na buwan."},"ar":{"q":"في Pennsylvania، إذا كان عمرك أقل من 18 سنة، كم يجب أن تنتظر بعد حصولك على تصريح التعلّم قبل اختبار القيادة على الطريق؟","o":["ستة أشهر","شهر واحد","ثلاثة أشهر","سنتان"],"h1":"المدة نصف سنة.","h2":"في Pennsylvania لا يجوز للسائق الذي عمره أقل من 18 سنة أن يقدّم اختبار القيادة على الطريق إلا بعد ستة أشهر من حصوله على تصريح التعلّم.","p":"صحيح. انتظر ستة أشهر."},"ref":{"doc":"PA","page":2}},{"id":"pa-005","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how many hours of supervised behind-the-wheel practice must a driver under 18 complete before the road test?","o":["30 hours","50 hours","65 hours","100 hours"],"h1":"It is more than 60 and less than 70.","h2":"In Pennsylvania a driver under 18 must complete at least 65 hours of supervised behind-the-wheel practice before the road test.","p":"Right. Pennsylvania asks for 65 hours."},"es":{"q":"En Pensilvania, ¿cuántas horas de práctica supervisada al volante debe completar un conductor menor de 18 años antes del examen de manejo?","o":["30 horas","50 horas","65 horas","100 horas"],"h1":"Son más de 60 y menos de 70.","h2":"En Pensilvania un conductor menor de 18 años debe completar por lo menos 65 horas de práctica supervisada al volante antes del examen de manejo.","p":"Correcto. Pensilvania pide 65 horas."},"zh":{"q":"在 Pennsylvania，未满 18 岁的司机在路考前必须完成多少小时有人陪同的开车练习？","o":["30 小时","50 小时","65 小时","100 小时"],"h1":"多于 60，少于 70。","h2":"在 Pennsylvania，未满 18 岁的司机在路考前必须完成至少 65 小时有人陪同的开车练习。","p":"对。Pennsylvania 要求 65 小时。"},"vi":{"q":"Ở Pennsylvania, người lái dưới 18 tuổi phải tập lái có người kèm bao nhiêu giờ trước khi thi lái xe trên đường?","o":["30 giờ","50 giờ","65 giờ","100 giờ"],"h1":"Nhiều hơn 60 và ít hơn 70.","h2":"Ở Pennsylvania, người lái dưới 18 tuổi phải tập lái có người kèm ít nhất 65 giờ trước khi thi lái xe trên đường.","p":"Đúng. Pennsylvania yêu cầu 65 giờ."},"tl":{"q":"Sa Pennsylvania, ilang oras ng pagsasanay sa pagmamaneho na may kasamang tagabantay ang dapat tapusin ng driver na wala pang 18 bago ang road test?","o":["30 oras","50 oras","65 oras","100 oras"],"h1":"Higit sa 60 at kulang sa 70.","h2":"Sa Pennsylvania, ang driver na wala pang 18 ay dapat makatapos ng hindi bababa sa 65 oras ng pagsasanay sa pagmamaneho na may kasamang tagabantay bago ang road test.","p":"Tama. 65 oras ang hinihingi ng Pennsylvania."},"ar":{"q":"في Pennsylvania، كم ساعة من التدريب على القيادة مع مرافق يجب أن يكملها السائق الذي عمره أقل من 18 سنة قبل اختبار الطريق؟","o":["30 ساعة","50 ساعة","65 ساعة","100 ساعة"],"h1":"العدد أكثر من 60 وأقل من 70.","h2":"في Pennsylvania يجب على السائق الذي عمره أقل من 18 سنة أن يكمل 65 ساعة على الأقل من التدريب على القيادة مع مرافق قبل اختبار الطريق.","p":"صحيح. Pennsylvania تطلب 65 ساعة."},"ref":{"doc":"PA","page":2}},{"id":"pa-006","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven at night?","o":["5 hours","10 hours","20 hours","30 hours"],"h1":"It is twice the number of bad-weather hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 10 must be nighttime driving.","p":"Right. At least 10 hours at night."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser de noche?","o":["5 horas","10 horas","20 horas","30 horas"],"h1":"Es el doble de las horas con mal tiempo.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 10 deben ser de manejo nocturno.","p":"Correcto. Por lo menos 10 horas de noche."},"zh":{"q":"在 Pennsylvania，65 小时练习中，有多少小时必须在晚上开？","o":["5 小时","10 小时","20 小时","30 小时"],"h1":"是坏天气小时数的两倍。","h2":"在 Pennsylvania 的 65 小时练习中，至少 10 小时必须在晚上开车。","p":"对。晚上至少 10 小时。"},"vi":{"q":"Ở Pennsylvania, trong 65 giờ tập lái, bao nhiêu giờ phải lái vào ban đêm?","o":["5 giờ","10 giờ","20 giờ","30 giờ"],"h1":"Gấp đôi số giờ lái khi thời tiết xấu.","h2":"Trong 65 giờ tập lái ở Pennsylvania, ít nhất 10 giờ phải lái vào ban đêm.","p":"Đúng. Ít nhất 10 giờ ban đêm."},"tl":{"q":"Sa Pennsylvania, ilan sa 65 oras ng pagsasanay ang dapat imaneho sa gabi?","o":["5 oras","10 oras","20 oras","30 oras"],"h1":"Doble ito ng oras sa masamang panahon.","h2":"Sa 65 oras ng pagsasanay sa Pennsylvania, hindi bababa sa 10 ang dapat pagmamaneho sa gabi.","p":"Tama. Hindi bababa sa 10 oras sa gabi."},"ar":{"q":"في Pennsylvania، كم ساعة من ساعات التدريب الـ 65 يجب أن تكون قيادة في الليل؟","o":["5 ساعات","10 ساعات","20 ساعة","30 ساعة"],"h1":"العدد ضعف ساعات القيادة في الطقس السيئ.","h2":"من ساعات التدريب الـ 65 في Pennsylvania، يجب أن تكون 10 ساعات على الأقل قيادة في الليل.","p":"صحيح. 10 ساعات على الأقل في الليل."},"ref":{"doc":"PA","page":2}},{"id":"pa-007","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many of the 65 practice hours must be driven in bad weather?","o":["None","1 hour","15 hours","5 hours"],"h1":"It is half the number of night hours.","h2":"Of the 65 practice hours in Pennsylvania, at least 5 must be driven in bad weather, such as rain, snow or fog.","p":"Right. At least 5 hours in bad weather."},"es":{"q":"En Pensilvania, ¿cuántas de las 65 horas de práctica deben ser con mal tiempo?","o":["Ninguna","1 hora","15 horas","5 horas"],"h1":"Es la mitad de las horas de noche.","h2":"De las 65 horas de práctica en Pensilvania, por lo menos 5 deben ser con mal tiempo, como lluvia, nieve o niebla.","p":"Correcto. Por lo menos 5 horas con mal tiempo."},"zh":{"q":"在 Pennsylvania，65 小时练习中，有多少小时必须在坏天气里开？","o":["不需要","1 小时","15 小时","5 小时"],"h1":"是晚上小时数的一半。","h2":"在 Pennsylvania 的 65 小时练习中，至少 5 小时必须在坏天气里开车，例如下雨、下雪或有雾。","p":"对。坏天气里至少 5 小时。"},"vi":{"q":"Ở Pennsylvania, trong 65 giờ tập lái, bao nhiêu giờ phải lái khi thời tiết xấu?","o":["Không cần","1 giờ","15 giờ","5 giờ"],"h1":"Bằng một nửa số giờ lái ban đêm.","h2":"Trong 65 giờ tập lái ở Pennsylvania, ít nhất 5 giờ phải lái khi thời tiết xấu, như mưa, tuyết hoặc sương mù.","p":"Đúng. Ít nhất 5 giờ khi thời tiết xấu."},"tl":{"q":"Sa Pennsylvania, ilan sa 65 oras ng pagsasanay ang dapat imaneho sa masamang panahon?","o":["Wala","1 oras","15 oras","5 oras"],"h1":"Kalahati ito ng oras sa gabi.","h2":"Sa 65 oras ng pagsasanay sa Pennsylvania, hindi bababa sa 5 ang dapat imaneho sa masamang panahon, gaya ng ulan, niyebe o hamog.","p":"Tama. Hindi bababa sa 5 oras sa masamang panahon."},"ar":{"q":"في Pennsylvania، كم ساعة من ساعات التدريب الـ 65 يجب أن تكون قيادة في الطقس السيئ؟","o":["لا شيء","ساعة واحدة (1)","15 ساعة","5 ساعات"],"h1":"العدد نصف ساعات القيادة في الليل.","h2":"من ساعات التدريب الـ 65 في Pennsylvania، يجب أن تكون 5 ساعات على الأقل قيادة في الطقس السيئ، مثل المطر أو الثلج أو الضباب.","p":"صحيح. 5 ساعات على الأقل في الطقس السيئ."},"ref":{"doc":"PA","page":2}},{"id":"pa-008","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, who signs the form saying a teen finished the 65 hours of practice?","o":["A parent or guardian","The teen alone","A friend from school","Nobody; no form is needed"],"h1":"It is the adult responsible for the teen.","h2":"In Pennsylvania a parent or guardian signs the certification form saying the teen completed the 65 hours of supervised driving.","p":"Right. A parent or guardian signs it."},"es":{"q":"En Pensilvania, ¿quién firma el formulario que dice que un adolescente completó las 65 horas de práctica?","o":["Un padre, madre o tutor","El adolescente solo","Un amigo de la escuela","Nadie; no hace falta formulario"],"h1":"Es el adulto responsable del adolescente.","h2":"En Pensilvania un padre, madre o tutor firma el formulario de certificación que dice que el adolescente completó las 65 horas de manejo supervisado.","p":"Correcto. Lo firma un padre, madre o tutor."},"zh":{"q":"在 Pennsylvania，谁在表格上签字，证明青少年已完成 65 小时练习？","o":["父母或监护人","青少年自己","学校的朋友","没有人，不需要表格"],"h1":"是对这个青少年负责的大人。","h2":"在 Pennsylvania，由父母或监护人在证明表上签字，证明青少年已完成 65 小时有人陪同的开车练习。","p":"对。由父母或监护人签字。"},"vi":{"q":"Ở Pennsylvania, ai ký vào mẫu đơn xác nhận thiếu niên đã tập đủ 65 giờ?","o":["Cha mẹ hoặc người giám hộ","Chỉ thiếu niên đó","Một người bạn ở trường","Không ai cả; không cần mẫu đơn"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở Pennsylvania, cha mẹ hoặc người giám hộ ký vào mẫu đơn xác nhận thiếu niên đã tập lái có người kèm đủ 65 giờ.","p":"Đúng. Cha mẹ hoặc người giám hộ ký."},"tl":{"q":"Sa Pennsylvania, sino ang pumipirma sa form na nagsasabing natapos ng tinedyer ang 65 oras ng pagsasanay?","o":["Magulang o guardian","Ang tinedyer lang","Isang kaibigan sa paaralan","Wala; hindi kailangan ng form"],"h1":"Ito ang adultong may pananagutan sa tinedyer.","h2":"Sa Pennsylvania, ang magulang o guardian ang pumipirma sa certification form na nagsasabing natapos ng tinedyer ang 65 oras ng pagmamaneho na may kasamang tagabantay.","p":"Tama. Magulang o guardian ang pumipirma."},"ar":{"q":"في Pennsylvania، من يوقّع النموذج الذي يقول إن المراهق أكمل 65 ساعة من التدريب؟","o":["أحد الوالدين أو الوصي","المراهق وحده","صديق من المدرسة","لا أحد؛ لا حاجة إلى نموذج"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Pennsylvania يوقّع أحد الوالدين أو الوصي نموذج الإقرار الذي يقول إن المراهق أكمل 65 ساعة من القيادة مع مرافق.","p":"صحيح. يوقّعه أحد الوالدين أو الوصي."},"ref":{"doc":"PA","page":5}},{"id":"pa-009","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, during which hours may a junior license holder not drive, unless a parent, guardian or spouse 18 or older is in the car?","o":["9 p.m. to 6 a.m.","Midnight to 6 a.m.","11 p.m. to 5 a.m.","10 p.m. to 4 a.m."],"h1":"It starts one hour before midnight.","h2":"In Pennsylvania a junior license holder may not drive between 11 p.m. and 5 a.m. unless a parent, guardian or spouse 18 or older is with them, or an exception applies.","p":"Right. Not from 11 p.m. to 5 a.m."},"es":{"q":"En Pensilvania, ¿en qué horario no puede manejar el titular de una licencia junior, a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más?","o":["De 9 p.m. a 6 a.m.","De medianoche a 6 a.m.","De 11 p.m. a 5 a.m.","De 10 p.m. a 4 a.m."],"h1":"Empieza una hora antes de la medianoche.","h2":"En Pensilvania el titular de una licencia junior no puede manejar entre las 11 p.m. y las 5 a.m., a menos que vaya con él su padre, madre, tutor o cónyuge de 18 años o más, o que se aplique una excepción.","p":"Correcto. No de 11 p.m. a 5 a.m."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）的人在哪段时间不能开车，除非车里有 18 岁或以上的父母、监护人或配偶？","o":["晚上 9 点到早上 6 点","午夜 12 点到早上 6 点","晚上 11 点到早上 5 点","晚上 10 点到早上 4 点"],"h1":"它从午夜前一小时开始。","h2":"在 Pennsylvania，持青少年驾照的人在晚上 11 点到早上 5 点之间不能开车，除非有 18 岁或以上的父母、监护人或配偶在车里，或者符合例外情况。","p":"对。晚上 11 点到早上 5 点不能开。"},"vi":{"q":"Ở Pennsylvania, người có bằng lái thiếu niên (junior license) không được lái xe trong khoảng giờ nào, trừ khi có cha mẹ, người giám hộ hoặc vợ/chồng từ 18 tuổi trở lên ngồi trong xe?","o":["9 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng","11 giờ tối đến 5 giờ sáng","10 giờ tối đến 4 giờ sáng"],"h1":"Bắt đầu một giờ trước nửa đêm.","h2":"Ở Pennsylvania, người có bằng lái thiếu niên không được lái xe từ 11 giờ tối đến 5 giờ sáng, trừ khi có cha mẹ, người giám hộ hoặc vợ/chồng từ 18 tuổi trở lên đi cùng, hoặc có trường hợp ngoại lệ.","p":"Đúng. Không lái từ 11 giờ tối đến 5 giờ sáng."},"tl":{"q":"Sa Pennsylvania, sa anong mga oras hindi puwedeng magmaneho ang may hawak ng junior license, maliban kung may magulang, guardian o asawa na 18 pataas sa sasakyan?","o":["9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m.","11 p.m. hanggang 5 a.m.","10 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ito isang oras bago maghatinggabi.","h2":"Sa Pennsylvania, ang may hawak ng junior license ay hindi puwedeng magmaneho mula 11 p.m. hanggang 5 a.m., maliban kung kasama ang magulang, guardian o asawa na 18 pataas, o may exception na tumutugma.","p":"Tama. Bawal mula 11 p.m. hanggang 5 a.m."},"ar":{"q":"في Pennsylvania، في أي ساعات لا يجوز لحامل رخصة الناشئين (junior license) أن يقود، إلا إذا كان معه في السيارة أحد الوالدين أو الوصي أو الزوج أو الزوجة بعمر 18 سنة أو أكثر؟","o":["من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 6 صباحًا","من 11 مساءً إلى 5 صباحًا","من 10 مساءً إلى 4 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعة واحدة.","h2":"في Pennsylvania لا يجوز لحامل رخصة الناشئين أن يقود بين 11 مساءً و5 صباحًا، إلا إذا كان معه أحد الوالدين أو الوصي أو الزوج أو الزوجة بعمر 18 سنة أو أكثر، أو إذا انطبق استثناء.","p":"صحيح. لا قيادة من 11 مساءً إلى 5 صباحًا."},"ref":{"doc":"PA","page":3}},{"id":"pa-010","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, which reason lets a junior license holder drive alone between 11 p.m. and 5 a.m.?","o":["Working during those hours, with proper documentation","Visiting friends","Going out to eat","Driving to practice for the road test"],"h1":"It is a duty, not a social outing.","h2":"A Pennsylvania junior license holder may drive between 11 p.m. and 5 a.m. for a job, public or charitable service, or a volunteer fire company, carrying proper documentation.","p":"Right. Work or volunteer service is an exception."},"es":{"q":"En Pensilvania, ¿qué razón permite que el titular de una licencia junior maneje solo entre las 11 p.m. y las 5 a.m.?","o":["Trabajar en ese horario, con la documentación correcta","Visitar a amigos","Salir a comer","Practicar para el examen de manejo"],"h1":"Es una obligación, no una salida social.","h2":"El titular de una licencia junior en Pensilvania puede manejar entre las 11 p.m. y las 5 a.m. por su trabajo, por servicio público o caritativo, o como bombero voluntario, si lleva la documentación correcta.","p":"Correcto. El trabajo o el voluntariado son una excepción."},"zh":{"q":"在 Pennsylvania，哪个理由可以让持青少年驾照（junior license）的人在晚上 11 点到早上 5 点之间独自开车？","o":["在那段时间工作，并带着正式证明文件","去看朋友","出去吃饭","开车练习准备路考"],"h1":"它是一种职责，不是社交活动。","h2":"在 Pennsylvania，持青少年驾照的人可以在晚上 11 点到早上 5 点之间为了工作、公共或慈善服务、或志愿消防队开车，但要带着正式证明文件。","p":"对。工作或志愿服务是例外。"},"vi":{"q":"Ở Pennsylvania, lý do nào cho phép người có bằng lái thiếu niên (junior license) lái xe một mình từ 11 giờ tối đến 5 giờ sáng?","o":["Đi làm trong những giờ đó, có giấy tờ chứng minh hợp lệ","Đi thăm bạn bè","Đi ăn ngoài","Lái xe tập luyện cho kỳ thi lái xe trên đường"],"h1":"Đó là một nhiệm vụ, không phải đi chơi.","h2":"Ở Pennsylvania, người có bằng lái thiếu niên được lái xe từ 11 giờ tối đến 5 giờ sáng để đi làm, làm công việc công ích hoặc từ thiện, hoặc cho đội cứu hỏa tình nguyện, và phải mang theo giấy tờ chứng minh hợp lệ.","p":"Đúng. Đi làm hoặc làm tình nguyện là ngoại lệ."},"tl":{"q":"Sa Pennsylvania, anong dahilan ang nagpapahintulot sa may hawak ng junior license na magmaneho nang mag-isa mula 11 p.m. hanggang 5 a.m.?","o":["Pagtatrabaho sa mga oras na iyon, na may tamang dokumento","Pagbisita sa mga kaibigan","Paglabas para kumain","Pagmamaneho para magsanay para sa road test"],"h1":"Isa itong tungkulin, hindi lakad kasama ang barkada.","h2":"Sa Pennsylvania, ang may hawak ng junior license ay puwedeng magmaneho mula 11 p.m. hanggang 5 a.m. para sa trabaho, serbisyo publiko o kawanggawa, o volunteer fire company, basta may dalang tamang dokumento.","p":"Tama. Exception ang trabaho o boluntaryong serbisyo."},"ar":{"q":"في Pennsylvania، ما السبب الذي يسمح لحامل رخصة الناشئين (junior license) أن يقود وحده بين 11 مساءً و5 صباحًا؟","o":["العمل في تلك الساعات، مع وثائق رسمية مناسبة","زيارة الأصدقاء","الخروج لتناول الطعام","القيادة للتدريب على اختبار الطريق"],"h1":"هو واجب، وليس نزهة اجتماعية.","h2":"في Pennsylvania يجوز لحامل رخصة الناشئين أن يقود بين 11 مساءً و5 صباحًا من أجل العمل، أو خدمة عامة أو خيرية، أو فرقة إطفاء تطوعية، بشرط أن يحمل وثائق رسمية مناسبة.","p":"صحيح. العمل أو الخدمة التطوعية استثناء."},"ref":{"doc":"PA","page":3}},{"id":"pa-011","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, during the first six months with a junior license, how many passengers under 18 who are not immediate family may ride with the driver?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"During the first six months with a Pennsylvania junior license, the driver may carry only one passenger under 18 who is not immediate family, unless a parent or guardian is in the car.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Pensilvania, durante los primeros seis meses con licencia junior, ¿cuántos pasajeros menores de 18 años que no son familia inmediata pueden ir con el conductor?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Durante los primeros seis meses con licencia junior en Pensilvania, el conductor solo puede llevar un pasajero menor de 18 años que no sea familia inmediata, a menos que vaya su padre, madre o tutor.","p":"Correcto. Solo un pasajero menor de 18 que no es familia."},"zh":{"q":"在 Pennsylvania，拿到青少年驾照（junior license）的前六个月，可以载几个不是直系亲属、未满 18 岁的乘客？","o":["不能载","一个","两个","三个"],"h1":"是大于零的最小数字。","h2":"在 Pennsylvania 拿到青少年驾照的前六个月，司机只能载一个不是直系亲属、未满 18 岁的乘客，除非父母或监护人在车里。","p":"对。只能载一个非家人、未满 18 岁的乘客。"},"vi":{"q":"Ở Pennsylvania, trong sáu tháng đầu có bằng lái thiếu niên (junior license), người lái được chở bao nhiêu hành khách dưới 18 tuổi không phải người thân trong gia đình?","o":["Không được chở ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Trong sáu tháng đầu có bằng lái thiếu niên ở Pennsylvania, người lái chỉ được chở một hành khách dưới 18 tuổi không phải người thân trong gia đình, trừ khi có cha mẹ hoặc người giám hộ trong xe.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Pennsylvania, sa unang anim na buwan ng junior license, ilang pasaherong wala pang 18 na hindi malapit na pamilya ang puwedeng isakay ng driver?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa unang anim na buwan ng junior license sa Pennsylvania, isang pasahero lang na wala pang 18 at hindi malapit na pamilya ang puwedeng isakay ng driver, maliban kung may magulang o guardian sa sasakyan.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi pamilya."},"ar":{"q":"في Pennsylvania، خلال الأشهر الستة الأولى مع رخصة الناشئين (junior license)، كم راكبًا عمره أقل من 18 سنة وليس من العائلة المباشرة يمكن أن يركب مع السائق؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"خلال الأشهر الستة الأولى مع رخصة الناشئين في Pennsylvania، يمكن للسائق أن يحمل راكبًا واحدًا فقط عمره أقل من 18 سنة وليس من العائلة المباشرة، إلا إذا كان أحد الوالدين أو الوصي في السيارة.","p":"صحيح. راكب واحد فقط من غير العائلة عمره أقل من 18 سنة."},"ref":{"doc":"PA","page":4}},{"id":"pa-012","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, after six months with a junior license and a clean record, how many passengers under 18 who are not family may ride with the driver?","o":["One","Two","Any number","Three"],"h1":"The limit goes up, but there is still a limit.","h2":"After six months with a Pennsylvania junior license, with no at-fault crash and no driving conviction, the limit rises to three passengers under 18 who are not family.","p":"Right. The limit rises to three."},"es":{"q":"En Pensilvania, después de seis meses con licencia junior y un historial limpio, ¿cuántos pasajeros menores de 18 años que no son familia pueden ir con el conductor?","o":["Uno","Dos","Cualquier cantidad","Tres"],"h1":"El límite sube, pero todavía hay un límite.","h2":"Después de seis meses con licencia junior en Pensilvania, sin choques por su culpa y sin condenas de tránsito, el límite sube a tres pasajeros menores de 18 años que no sean familia.","p":"Correcto. El límite sube a tres."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）满六个月并且记录良好后，可以载几个不是家人、未满 18 岁的乘客？","o":["一个","两个","不限人数","三个"],"h1":"限制提高了，但还是有限制。","h2":"在 Pennsylvania 持青少年驾照满六个月后，如果没有负责任的车祸，也没有交通违法定罪，限制提高到三个不是家人、未满 18 岁的乘客。","p":"对。限制提高到三个。"},"vi":{"q":"Ở Pennsylvania, sau sáu tháng có bằng lái thiếu niên (junior license) và hồ sơ lái xe sạch, người lái được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Một","Hai","Bao nhiêu cũng được","Ba"],"h1":"Giới hạn tăng lên, nhưng vẫn còn giới hạn.","h2":"Sau sáu tháng có bằng lái thiếu niên ở Pennsylvania, nếu không gây tai nạn và không bị kết tội vi phạm lái xe, giới hạn tăng lên ba hành khách dưới 18 tuổi không phải người nhà.","p":"Đúng. Giới hạn tăng lên ba."},"tl":{"q":"Sa Pennsylvania, matapos ang anim na buwan sa junior license na malinis ang record, ilang pasaherong wala pang 18 na hindi pamilya ang puwedeng isakay ng driver?","o":["Isa","Dalawa","Kahit ilan","Tatlo"],"h1":"Tumataas ang limitasyon, pero may limitasyon pa rin.","h2":"Matapos ang anim na buwan sa junior license sa Pennsylvania, kung walang aksidenteng ikaw ang may kasalanan at walang conviction sa pagmamaneho, tumataas ang limitasyon sa tatlong pasaherong wala pang 18 na hindi pamilya.","p":"Tama. Tumataas ang limitasyon sa tatlo."},"ar":{"q":"في Pennsylvania، بعد ستة أشهر مع رخصة الناشئين (junior license) وسجل نظيف، كم راكبًا عمره أقل من 18 سنة وليس من العائلة يمكن أن يركب مع السائق؟","o":["واحد","اثنان","أي عدد","ثلاثة"],"h1":"الحد يرتفع، لكن ما زال هناك حد.","h2":"بعد ستة أشهر مع رخصة الناشئين في Pennsylvania، إذا لم يكن هناك حادث بخطأ السائق ولا إدانة في مخالفة قيادة، يرتفع الحد إلى ثلاثة ركاب أعمارهم أقل من 18 سنة وليسوا من العائلة.","p":"صحيح. يرتفع الحد إلى ثلاثة."},"ref":{"doc":"PA","page":4}},{"id":"pa-013","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, what is the most passengers a junior license holder may ever carry?","o":["Five, in any car","As many as fit","No more than the number of seat belts in the car","Two"],"h1":"Every passenger needs something to wear.","h2":"In Pennsylvania a junior driver may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Pensilvania, ¿cuál es el número máximo de pasajeros que puede llevar el titular de una licencia junior?","o":["Cinco, en cualquier carro","Todos los que quepan","No más que la cantidad de cinturones de seguridad del carro","Dos"],"h1":"Cada pasajero necesita algo que ponerse.","h2":"En Pensilvania un conductor con licencia junior nunca puede llevar más pasajeros que cinturones de seguridad tiene el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"zh":{"q":"在 Pennsylvania，持青少年驾照（junior license）的人最多能载多少乘客？","o":["五个，任何车都一样","坐得下多少就载多少","不超过车里安全带的数量","两个"],"h1":"每个乘客都需要系上一样东西。","h2":"在 Pennsylvania，青少年司机载的乘客永远不能多于车里的安全带数量。","p":"对。乘客不能多于安全带。"},"vi":{"q":"Ở Pennsylvania, người có bằng lái thiếu niên (junior license) được chở tối đa bao nhiêu hành khách?","o":["Năm người, với bất kỳ xe nào","Bao nhiêu người ngồi vừa cũng được","Không nhiều hơn số dây an toàn trong xe","Hai"],"h1":"Mỗi hành khách cần đeo một thứ.","h2":"Ở Pennsylvania, người lái có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số dây an toàn trong xe.","p":"Đúng. Không nhiều hành khách hơn số dây an toàn."},"tl":{"q":"Sa Pennsylvania, ano ang pinakamaraming pasahero na puwedeng isakay ng may hawak ng junior license?","o":["Lima, sa kahit anong sasakyan","Kung ilan ang kasya","Hindi hihigit sa bilang ng seat belt sa sasakyan","Dalawa"],"h1":"Bawat pasahero ay may kailangang isuot.","h2":"Sa Pennsylvania, ang junior driver ay hindi kailanman puwedeng magsakay ng mas maraming pasahero kaysa sa bilang ng seat belt sa sasakyan.","p":"Tama. Hindi hihigit ang pasahero sa seat belt."},"ar":{"q":"في Pennsylvania، ما أكبر عدد من الركاب يمكن أن يحمله حامل رخصة الناشئين (junior license)؟","o":["خمسة، في أي سيارة","بقدر ما تتسع السيارة","لا يزيد على عدد أحزمة الأمان في السيارة","اثنان"],"h1":"كل راكب يحتاج إلى شيء يلبسه.","h2":"في Pennsylvania لا يجوز أبدًا للسائق الناشئ أن يحمل ركابًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. لا ركاب أكثر من أحزمة الأمان."},"ref":{"doc":"PA","page":3}},{"id":"pa-014","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, when does the junior license limit on passengers under 18 not apply?","o":["When a parent or legal guardian is in the car","On weekends","When driving under 25 mph","When the passengers are 17"],"h1":"Think about which adult could be riding along.","h2":"The Pennsylvania junior license limit on passengers under 18 does not apply when a parent or legal guardian is in the vehicle.","p":"Right. A parent or guardian in the car lifts the limit."},"es":{"q":"En Pensilvania, ¿cuándo no se aplica el límite de pasajeros menores de 18 años de la licencia junior?","o":["Cuando va en el carro su padre, madre o tutor legal","Los fines de semana","Cuando maneja a menos de 25 mph","Cuando los pasajeros tienen 17 años"],"h1":"Piense en qué adulto podría ir con usted.","h2":"El límite de pasajeros menores de 18 años de la licencia junior en Pensilvania no se aplica cuando va en el vehículo su padre, madre o tutor legal.","p":"Correcto. Si va su padre, madre o tutor, no hay límite."},"zh":{"q":"在 Pennsylvania，青少年驾照（junior license）对未满 18 岁乘客的人数限制，什么时候不适用？","o":["父母或法定监护人在车里时","周末时","车速低于 25 mph 时","乘客是 17 岁时"],"h1":"想一想哪位大人可能坐在车里。","h2":"在 Pennsylvania，当父母或法定监护人在车里时，青少年驾照对未满 18 岁乘客的限制不适用。","p":"对。父母或监护人在车里，限制就取消。"},"vi":{"q":"Ở Pennsylvania, khi nào giới hạn hành khách dưới 18 tuổi của bằng lái thiếu niên (junior license) không áp dụng?","o":["Khi có cha mẹ hoặc người giám hộ hợp pháp trong xe","Vào cuối tuần","Khi lái dưới 25 mph","Khi hành khách 17 tuổi"],"h1":"Hãy nghĩ xem người lớn nào có thể ngồi cùng.","h2":"Ở Pennsylvania, giới hạn hành khách dưới 18 tuổi của bằng lái thiếu niên không áp dụng khi có cha mẹ hoặc người giám hộ hợp pháp trong xe.","p":"Đúng. Có cha mẹ hoặc người giám hộ trong xe thì không còn giới hạn."},"tl":{"q":"Sa Pennsylvania, kailan hindi umiiral ang limitasyon ng junior license sa mga pasaherong wala pang 18?","o":["Kapag may magulang o legal guardian sa sasakyan","Tuwing weekend","Kapag nagmamaneho nang mas mabagal sa 25 mph","Kapag 17 ang mga pasahero"],"h1":"Isipin kung sinong adulto ang puwedeng kasama sa biyahe.","h2":"Sa Pennsylvania, hindi umiiral ang limitasyon ng junior license sa mga pasaherong wala pang 18 kapag may magulang o legal guardian sa sasakyan.","p":"Tama. Nawawala ang limitasyon kapag may magulang o guardian sa sasakyan."},"ar":{"q":"في Pennsylvania، متى لا ينطبق حد رخصة الناشئين (junior license) على الركاب الذين أعمارهم أقل من 18 سنة؟","o":["عندما يكون أحد الوالدين أو الوصي القانوني في السيارة","في عطلة نهاية الأسبوع","عند القيادة بسرعة أقل من 25 mph","عندما يكون عمر الركاب 17 سنة"],"h1":"فكّر في الشخص البالغ الذي يمكن أن يركب معك.","h2":"في Pennsylvania لا ينطبق حد رخصة الناشئين على الركاب الذين أعمارهم أقل من 18 سنة عندما يكون أحد الوالدين أو الوصي القانوني في السيارة.","p":"صحيح. وجود أحد الوالدين أو الوصي في السيارة يلغي الحد."},"ref":{"doc":"PA","page":4}},{"id":"pa-015","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are on the opposite side of a divided highway, with a guide rail or grass median between you and a stopped school bus. What must you do?","o":["Stop until the bus moves","Honk to warn the children","Speed up to pass quickly","You do not have to stop, but slow down and drive with caution"],"h1":"A physical divider protects the other side of the road.","h2":"In Pennsylvania, on the opposite side of a divided highway, you do not have to stop for a school bus, but you must slow down and drive with caution.","p":"Right. No stop needed, but slow down with caution."},"es":{"q":"En Pensilvania, usted va del lado contrario de una carretera dividida, con una barrera o una mediana de pasto entre usted y un autobús escolar detenido. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Tocar la bocina para avisar a los niños","Acelerar para pasar rápido","No tiene que detenerse, pero debe bajar la velocidad y manejar con precaución"],"h1":"Una división física protege el otro lado de la carretera.","h2":"En Pensilvania, del lado contrario de una carretera dividida, usted no tiene que detenerse por un autobús escolar, pero debe bajar la velocidad y manejar con precaución.","p":"Correcto. No se detiene, pero baja la velocidad con precaución."},"zh":{"q":"在 Pennsylvania，你在分隔公路的对面一侧，你和停着的校车之间有护栏或草地中间带。你必须怎么做？","o":["停车，直到校车开走","按喇叭提醒孩子们","加速快点开过去","你不必停车，但要减速并小心驾驶"],"h1":"实体分隔物保护着公路的另一侧。","h2":"在 Pennsylvania，如果你在分隔公路的对面一侧，你不必为校车停车，但必须减速并小心驾驶。","p":"对。不用停车，但要减速小心。"},"vi":{"q":"Ở Pennsylvania, bạn ở phía bên kia của xa lộ có dải phân cách, giữa bạn và chiếc xe buýt trường học đang dừng có rào chắn hoặc dải cỏ. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy đi","Bấm còi để báo cho các em","Tăng tốc để vượt qua nhanh","Bạn không cần dừng, nhưng phải chạy chậm lại và lái cẩn thận"],"h1":"Vật ngăn cách bảo vệ phía bên kia đường.","h2":"Ở Pennsylvania, khi ở phía bên kia của xa lộ có dải phân cách, bạn không cần dừng lại vì xe buýt trường học, nhưng phải chạy chậm lại và lái cẩn thận.","p":"Đúng. Không cần dừng, nhưng chạy chậm và cẩn thận."},"tl":{"q":"Sa Pennsylvania, nasa kabilang panig ka ng divided highway, at may guide rail o damuhang median sa pagitan mo at ng nakahintong school bus. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Bumusina para bigyang-babala ang mga bata","Bumilis para mabilis na makalampas","Hindi mo kailangang huminto, pero bumagal at mag-ingat sa pagmamaneho"],"h1":"May pisikal na harang na nagpoprotekta sa kabilang panig ng daan.","h2":"Sa Pennsylvania, sa kabilang panig ng divided highway, hindi mo kailangang huminto para sa school bus, pero dapat kang bumagal at mag-ingat sa pagmamaneho.","p":"Tama. Hindi kailangang huminto, pero bumagal at mag-ingat."},"ar":{"q":"في Pennsylvania، أنت في الجهة المقابلة من طريق سريع مقسوم، وبينك وبين حافلة مدرسية متوقفة حاجز حديدي أو جزيرة وسطية من العشب. ماذا يجب أن تفعل؟","o":["توقف حتى تتحرك الحافلة","استخدم البوق لتحذير الأطفال","أسرِع لتتجاوز بسرعة","ليس عليك أن تتوقف، لكن خفّف السرعة وقُد بحذر"],"h1":"حاجز مادي يحمي الجهة الأخرى من الطريق.","h2":"في Pennsylvania، في الجهة المقابلة من طريق سريع مقسوم، ليس عليك أن تتوقف للحافلة المدرسية، لكن يجب أن تخفّف السرعة وتقود بحذر.","p":"صحيح. لا حاجة للتوقف، لكن خفّف السرعة وانتبه."},"ref":{"doc":"PA","page":58}},{"id":"pa-016","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, what happens to your license if you fail to stop for a school bus with red lights flashing and the stop arm out?","o":["Nothing happens to the license","A 60-day license suspension","A one-week suspension","Only a warning"],"h1":"It is about two months.","h2":"In Pennsylvania, failing to stop for a school bus with red lights flashing and the stop arm out brings a 60-day license suspension, five points and a fine.","p":"Right. A 60-day suspension."},"es":{"q":"En Pensilvania, ¿qué pasa con su licencia si no se detiene por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido?","o":["No le pasa nada a la licencia","Una suspensión de la licencia por 60 días","Una suspensión de una semana","Solo una advertencia"],"h1":"Son unos dos meses.","h2":"En Pensilvania, no detenerse por un autobús escolar con luces rojas intermitentes y el brazo de alto extendido trae una suspensión de la licencia por 60 días, cinco puntos y una multa.","p":"Correcto. Una suspensión de 60 días."},"zh":{"q":"在 Pennsylvania，如果校车红灯在闪、停车牌伸出来，你却没有停车，你的驾照会怎样？","o":["驾照没有任何影响","驾照被暂停 60 天","暂停一个星期","只是警告"],"h1":"大约两个月。","h2":"在 Pennsylvania，校车红灯在闪、停车牌伸出来时没有停车，驾照会被暂停 60 天，还要扣五分并罚款。","p":"对。暂停 60 天。"},"vi":{"q":"Ở Pennsylvania, bằng lái của bạn sẽ ra sao nếu bạn không dừng lại khi xe buýt trường học nháy đèn đỏ và đưa cần STOP ra?","o":["Bằng lái không bị gì cả","Bị treo bằng lái 60 ngày","Bị treo một tuần","Chỉ bị cảnh cáo"],"h1":"Khoảng hai tháng.","h2":"Ở Pennsylvania, không dừng lại khi xe buýt trường học nháy đèn đỏ và đưa cần STOP ra sẽ bị treo bằng lái 60 ngày, bị năm điểm và bị phạt tiền.","p":"Đúng. Bị treo 60 ngày."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa lisensya mo kung hindi ka huminto para sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm?","o":["Walang mangyayari sa lisensya","Suspensyon ng lisensya nang 60 araw","Suspensyon nang isang linggo","Babala lang"],"h1":"Mga dalawang buwan ito.","h2":"Sa Pennsylvania, ang hindi paghinto para sa school bus na kumikislap ang pulang ilaw at nakalabas ang stop arm ay may 60 araw na suspensyon ng lisensya, limang puntos at multa.","p":"Tama. 60 araw na suspensyon."},"ar":{"q":"في Pennsylvania، ماذا يحدث لرخصتك إذا لم تتوقف لحافلة مدرسية أضواؤها الحمراء تومض وذراع التوقف (STOP) ممدودة؟","o":["لا يحدث شيء للرخصة","تعليق الرخصة 60 يومًا","تعليق لمدة أسبوع","إنذار فقط"],"h1":"المدة شهران تقريبًا.","h2":"في Pennsylvania، عدم التوقف لحافلة مدرسية أضواؤها الحمراء تومض وذراع التوقف ممدودة يؤدي إلى تعليق الرخصة 60 يومًا، وخمس نقاط، وغرامة.","p":"صحيح. تعليق 60 يومًا."},"ref":{"doc":"PA","page":58}},{"id":"pa-017","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, how many points go on your driving record for failing to stop for a school bus?","o":["Five points","One point","Two points","No points"],"h1":"It is more than four and less than six.","h2":"In Pennsylvania, failing to stop for a school bus adds five points to your driving record, along with a suspension and a fine.","p":"Right. Five points."},"es":{"q":"En Pensilvania, ¿cuántos puntos se agregan a su historial de manejo por no detenerse por un autobús escolar?","o":["Cinco puntos","Un punto","Dos puntos","Ningún punto"],"h1":"Es más de cuatro y menos de seis.","h2":"En Pensilvania, no detenerse por un autobús escolar agrega cinco puntos a su historial de manejo, además de una suspensión y una multa.","p":"Correcto. Cinco puntos."},"zh":{"q":"在 Pennsylvania，没有为校车停车，你的驾驶记录上会记几分？","o":["五分","一分","两分","不记分"],"h1":"多于四，少于六。","h2":"在 Pennsylvania，没有为校车停车，你的驾驶记录会加五分，还会被暂停驾照并罚款。","p":"对。五分。"},"vi":{"q":"Ở Pennsylvania, không dừng lại vì xe buýt trường học sẽ bị ghi bao nhiêu điểm vào hồ sơ lái xe?","o":["Năm điểm","Một điểm","Hai điểm","Không bị điểm"],"h1":"Nhiều hơn bốn và ít hơn sáu.","h2":"Ở Pennsylvania, không dừng lại vì xe buýt trường học sẽ bị ghi năm điểm vào hồ sơ lái xe, cùng với bị treo bằng và bị phạt tiền.","p":"Đúng. Năm điểm."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang idinadagdag sa driving record mo kapag hindi ka huminto para sa school bus?","o":["Limang puntos","Isang puntos","Dalawang puntos","Walang puntos"],"h1":"Higit sa apat at kulang sa anim.","h2":"Sa Pennsylvania, ang hindi paghinto para sa school bus ay nagdadagdag ng limang puntos sa driving record mo, kasama ang suspensyon at multa.","p":"Tama. Limang puntos."},"ar":{"q":"في Pennsylvania، كم نقطة تُضاف إلى سجل القيادة إذا لم تتوقف لحافلة مدرسية؟","o":["خمس نقاط","نقطة واحدة","نقطتان","لا نقاط"],"h1":"العدد أكثر من أربعة وأقل من ستة.","h2":"في Pennsylvania، عدم التوقف لحافلة مدرسية يضيف خمس نقاط إلى سجل القيادة، مع تعليق الرخصة وغرامة.","p":"صحيح. خمس نقاط."},"ref":{"doc":"PA","page":58}},{"id":"pa-018","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, what does the Move Over law ask you to do near an emergency response area?","o":["Stop and wait until it is cleared","Turn on your hazard lights and keep going","Move into a lane that is not next to it, or slow down if you cannot","Use the shoulder to pass"],"h1":"The law's name tells you the first step.","h2":"Pennsylvania's Move Over law requires you to move into a lane that is not next to an emergency response area, or, if you cannot move over, to slow down to at least 20 mph below the speed limit.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Pensilvania, ¿qué le pide la ley Move Over (muévase al otro carril) cerca de un área de respuesta a emergencias?","o":["Detenerse y esperar hasta que se despeje","Encender las luces de emergencia y seguir","Pasarse a un carril que no esté junto a la zona o, si no puede, bajar la velocidad","Usar el acotamiento para pasar"],"h1":"El nombre de la ley le dice el primer paso.","h2":"La ley Move Over de Pensilvania le exige pasarse a un carril que no esté junto a un área de respuesta a emergencias o, si no puede cambiarse de carril, bajar la velocidad a por lo menos 20 mph por debajo del límite.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Pennsylvania，让道法（Move Over law）要求你在紧急救援区域附近怎么做？","o":["停车，等到清理完毕","打开双闪灯继续开","换到不紧挨着它的车道；如果换不了，就减速","用路肩超车"],"h1":"这条法律的名字告诉你第一步。","h2":"Pennsylvania 的让道法（Move Over law）要求你换到不紧挨着紧急救援区域的车道；如果换不了，就要减速到比限速至少低 20 mph。","p":"对。换车道，换不了就减速。"},"vi":{"q":"Ở Pennsylvania, luật Nhường Làn (Move Over law) yêu cầu bạn làm gì khi đến gần khu vực cấp cứu khẩn cấp?","o":["Dừng lại và chờ đến khi dọn xong","Bật đèn khẩn cấp và tiếp tục chạy","Chuyển sang làn không sát bên khu vực đó, hoặc chạy chậm lại nếu không chuyển được","Chạy trên lề đường để vượt qua"],"h1":"Tên của luật cho bạn biết bước đầu tiên.","h2":"Luật Nhường Làn (Move Over law) của Pennsylvania yêu cầu bạn chuyển sang làn không sát bên khu vực cấp cứu khẩn cấp, hoặc nếu không chuyển được thì chạy chậm lại ít nhất 20 mph dưới tốc độ giới hạn.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không chuyển được."},"tl":{"q":"Sa Pennsylvania, ano ang ipinagagawa sa iyo ng Move Over law malapit sa emergency response area?","o":["Huminto at maghintay hanggang malinis ito","Buksan ang hazard lights at magpatuloy","Lumipat sa lane na hindi katabi nito, o bumagal kung hindi ka makalipat","Gamitin ang shoulder para makalampas"],"h1":"Sinasabi ng pangalan ng batas ang unang hakbang.","h2":"Ang Move Over law ng Pennsylvania ay nag-uutos na lumipat ka sa lane na hindi katabi ng emergency response area, o kung hindi ka makalipat, bumagal nang hindi bababa sa 20 mph mas mababa sa speed limit.","p":"Tama. Lumipat ng lane, o bumagal kung hindi makalipat."},"ar":{"q":"في Pennsylvania، ماذا يطلب منك قانون إفساح الطريق (Move Over law) قرب منطقة استجابة للطوارئ؟","o":["توقف وانتظر حتى يتم إخلاؤها","شغّل أضواء التحذير واستمر في السير","انتقل إلى مسار غير مجاور لها، أو خفّف السرعة إذا لم تستطع","استخدم كتف الطريق لتتجاوز"],"h1":"اسم القانون يخبرك بالخطوة الأولى.","h2":"قانون إفساح الطريق (Move Over law) في Pennsylvania يطلب منك أن تنتقل إلى مسار غير مجاور لمنطقة الاستجابة للطوارئ، أو إذا لم تستطع الانتقال، أن تخفّف السرعة إلى 20 mph على الأقل تحت حد السرعة.","p":"صحيح. انتقل إلى مسار آخر، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"PA","page":59}},{"id":"pa-019","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, may you hold your phone while stopped at a red light?","o":["Yes, if the car is stopped","No, holding a phone is banned even when stopped in traffic or at a red light","Yes, for less than one minute","Yes, if you are over 21"],"h1":"Stopping for a moment still counts as driving.","h2":"Pennsylvania's Paul Miller's Law bans holding a phone while driving, even when stopped for a moment in traffic or at a red light; hands-free use is allowed.","p":"Right. No phone in your hand, even at a red light."},"es":{"q":"En Pensilvania, ¿puede sostener su teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, si el carro está detenido","No, sostener el teléfono está prohibido aunque esté detenido en el tráfico o en un semáforo en rojo","Sí, por menos de un minuto","Sí, si tiene más de 21 años"],"h1":"Detenerse un momento todavía cuenta como manejar.","h2":"La Ley Paul Miller de Pensilvania prohíbe sostener el teléfono mientras maneja, incluso cuando se detiene un momento en el tráfico o en un semáforo en rojo; el uso con manos libres está permitido.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo."},"zh":{"q":"在 Pennsylvania，停在红灯前时，你可以手拿手机吗？","o":["可以，只要车停着","不可以，即使在车流中停着或在红灯前，也禁止手拿手机","可以，不超过一分钟","可以，如果你超过 21 岁"],"h1":"停一下也还算是在开车。","h2":"Pennsylvania 的 Paul Miller 法（Paul Miller's Law）禁止开车时手拿手机，即使在车流中或红灯前暂时停下也一样；可以用免提。","p":"对。即使在红灯前，手里也不能拿手机。"},"vi":{"q":"Ở Pennsylvania, bạn có được cầm điện thoại khi dừng ở đèn đỏ không?","o":["Được, nếu xe đang dừng","Không, cấm cầm điện thoại ngay cả khi dừng trong dòng xe hoặc ở đèn đỏ","Được, nếu ít hơn một phút","Được, nếu bạn trên 21 tuổi"],"h1":"Dừng một lát vẫn được tính là đang lái xe.","h2":"Luật Paul Miller (Paul Miller's Law) của Pennsylvania cấm cầm điện thoại khi lái xe, ngay cả khi dừng một lát trong dòng xe hoặc ở đèn đỏ; được dùng loại rảnh tay.","p":"Đúng. Không cầm điện thoại trên tay, kể cả ở đèn đỏ."},"tl":{"q":"Sa Pennsylvania, puwede mo bang hawakan ang phone mo habang nakahinto sa pulang ilaw?","o":["Oo, kung nakahinto ang sasakyan","Hindi, bawal humawak ng phone kahit nakahinto sa trapiko o sa pulang ilaw","Oo, kung wala pang isang minuto","Oo, kung lampas 21 ka na"],"h1":"Ang sandaling paghinto ay itinuturing pa ring pagmamaneho.","h2":"Ipinagbabawal ng Paul Miller's Law ng Pennsylvania ang paghawak ng phone habang nagmamaneho, kahit sandaling nakahinto sa trapiko o sa pulang ilaw; puwede ang hands-free.","p":"Tama. Walang phone sa kamay, kahit sa pulang ilaw."},"ar":{"q":"في Pennsylvania، هل يجوز أن تمسك هاتفك بيدك وأنت متوقف عند إشارة حمراء؟","o":["نعم، إذا كانت السيارة متوقفة","لا، إمساك الهاتف ممنوع حتى عند التوقف في الزحام أو عند إشارة حمراء","نعم، لمدة أقل من دقيقة واحدة","نعم، إذا كان عمرك أكثر من 21 سنة"],"h1":"التوقف للحظة ما زال يُعتبر قيادة.","h2":"قانون Paul Miller (Paul Miller's Law) في Pennsylvania يمنع إمساك الهاتف أثناء القيادة، حتى عند التوقف للحظة في الزحام أو عند إشارة حمراء؛ الاستخدام بدون استعمال اليدين مسموح.","p":"صحيح. لا هاتف في يدك، حتى عند الإشارة الحمراء."},"ref":{"doc":"PA","page":null}},{"id":"pa-020","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, what blood alcohol level is illegal for a driver under 21?","o":["0.08 percent or more","0.05 percent or more","0.10 percent or more","0.02 percent or more"],"h1":"It is far lower than the adult limit.","h2":"In Pennsylvania a driver under 21 breaks the law at a blood alcohol level of 0.02 percent or more, far below the 0.08 adult limit.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Pensilvania, ¿qué nivel de alcohol en la sangre es ilegal para un conductor menor de 21 años?","o":["0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más","0.02 por ciento o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Pensilvania un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de 0.02 por ciento o más, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 Pennsylvania，未满 21 岁的司机，血液酒精浓度多少就违法？","o":["0.08% 或以上","0.05% 或以上","0.10% 或以上","0.02% 或以上"],"h1":"它比成年人的限制低很多。","h2":"在 Pennsylvania，未满 21 岁的司机血液酒精浓度达到 0.02% 或以上就违法，远低于成年人 0.08% 的限制。","p":"对。未满 21 岁，限制是 0.02%。"},"vi":{"q":"Ở Pennsylvania, nồng độ cồn trong máu bao nhiêu là phạm pháp đối với người lái dưới 21 tuổi?","o":["0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên","0.02 phần trăm trở lên"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Pennsylvania, người lái dưới 21 tuổi phạm luật khi nồng độ cồn trong máu từ 0.02 phần trăm trở lên, thấp hơn nhiều so với giới hạn 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02 phần trăm."},"tl":{"q":"Sa Pennsylvania, anong blood alcohol level ang ilegal para sa driver na wala pang 21?","o":["0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa","0.02 porsiyento o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa Pennsylvania, lumalabag sa batas ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02 porsiyento o higit pa, mas mababa nang malaki sa 0.08 na limitasyon ng adulto.","p":"Tama. Para sa wala pang 21, 0.02 porsiyento ang limitasyon."},"ar":{"q":"في Pennsylvania، ما نسبة الكحول في الدم التي تكون مخالفة للقانون للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر","0.02 بالمئة أو أكثر"],"h1":"هي أقل بكثير من الحد المسموح للبالغين.","h2":"في Pennsylvania يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر، وهذا أقل بكثير من حد البالغين 0.08.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02 بالمئة."},"ref":{"doc":"PA","page":33}},{"id":"pa-021","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how long is a learner's permit valid?","o":["90 days","Six months","One year","Two years"],"h1":"It lasts twice as long as the time a teen must wait before the road test.","h2":"In Pennsylvania, a learner's permit is valid for one year from the issue date printed on it.","p":"Right. A learner's permit lasts one year."},"es":{"q":"En Pensilvania, ¿por cuánto tiempo es válido un permiso de aprendizaje?","o":["90 días","Seis meses","Un año","Dos años"],"h1":"Dura el doble del tiempo que un adolescente debe esperar antes del examen de manejo.","h2":"En Pensilvania, el permiso de aprendizaje es válido por un año a partir de la fecha de emisión impresa en él.","p":"Correcto. El permiso de aprendizaje dura un año."},"zh":{"q":"在 Pennsylvania，学习驾照（learner's permit）的有效期是多久？","o":["90 天","六个月","一年","两年"],"h1":"它的时长是青少年参加路考前必须等待时间的两倍。","h2":"在 Pennsylvania，学习驾照从上面印的签发日期起有效一年。","p":"对。学习驾照有效一年。"},"vi":{"q":"Ở Pennsylvania, giấy phép tập lái (learner's permit) có giá trị trong bao lâu?","o":["90 ngày","Sáu tháng","Một năm","Hai năm"],"h1":"Thời gian này dài gấp đôi thời gian một thiếu niên phải chờ trước khi thi lái xe trên đường.","h2":"Ở Pennsylvania, giấy phép tập lái có giá trị một năm kể từ ngày cấp được in trên giấy phép.","p":"Đúng. Giấy phép tập lái có giá trị một năm."},"tl":{"q":"Sa Pennsylvania, gaano katagal valid ang learner's permit?","o":["90 araw","Anim na buwan","Isang taon","Dalawang taon"],"h1":"Doble ito ng panahong kailangang hintayin ng isang teen bago ang road test.","h2":"Sa Pennsylvania, valid ang learner's permit nang isang taon mula sa petsa ng pag-issue na nakalimbag dito.","p":"Tama. Isang taon ang learner's permit."},"ar":{"q":"في Pennsylvania، ما مدة صلاحية تصريح تعلّم القيادة (learner's permit)؟","o":["90 يومًا","ستة أشهر","سنة واحدة","سنتان"],"h1":"مدته ضعف المدة التي يجب أن ينتظرها المراهق قبل اختبار القيادة على الطريق.","h2":"في Pennsylvania، يكون تصريح تعلّم القيادة صالحًا لمدة سنة واحدة من تاريخ الإصدار المطبوع عليه.","p":"صحيح. تصريح تعلّم القيادة صالح لمدة سنة واحدة."},"ref":{"doc":"PA","page":3}},{"id":"pa-022","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, what happens the first time a driver's record reaches 6 points?","o":["The driver must take a written special point exam","The license is taken away for one year","Nothing happens yet","The driver must retake the road test"],"h1":"The first step is a test on paper, not a suspension.","h2":"In Pennsylvania, the first time a driving record reaches 6 or more points, the driver gets a notice to take a written special point exam.","p":"Right. The first time at 6 points means a written point exam."},"es":{"q":"En Pensilvania, ¿qué pasa la primera vez que el historial de un conductor llega a 6 puntos?","o":["El conductor debe tomar un examen escrito especial de puntos","Le quitan la licencia por un año","Todavía no pasa nada","El conductor debe repetir el examen de manejo"],"h1":"El primer paso es un examen en papel, no una suspensión.","h2":"En Pensilvania, la primera vez que el historial llega a 6 puntos o más, el conductor recibe un aviso para tomar un examen escrito especial de puntos.","p":"Correcto. La primera vez con 6 puntos significa un examen escrito de puntos."},"zh":{"q":"在 Pennsylvania，驾驶记录第一次达到 6 分时会怎样？","o":["驾驶人必须参加笔试形式的特别扣分考试（special point exam）","驾照被收回一年","暂时什么都不会发生","驾驶人必须重新参加路考"],"h1":"第一步是一次纸上考试，而不是吊销驾照。","h2":"在 Pennsylvania，驾驶记录第一次达到 6 分或以上时，驾驶人会收到通知，必须参加笔试形式的特别扣分考试。","p":"对。第一次达到 6 分，就要参加笔试形式的扣分考试。"},"vi":{"q":"Ở Pennsylvania, điều gì xảy ra lần đầu tiên hồ sơ lái xe của một tài xế đạt 6 điểm?","o":["Tài xế phải làm một bài thi viết đặc biệt về điểm (special point exam)","Bằng lái bị thu hồi một năm","Chưa có chuyện gì xảy ra","Tài xế phải thi lại phần lái xe trên đường"],"h1":"Bước đầu tiên là một bài thi trên giấy, không phải bị treo bằng lái.","h2":"Ở Pennsylvania, lần đầu tiên hồ sơ lái xe đạt 6 điểm trở lên, tài xế sẽ nhận được thông báo phải làm một bài thi viết đặc biệt về điểm.","p":"Đúng. Lần đầu đạt 6 điểm thì phải làm bài thi viết về điểm."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa unang beses na umabot sa 6 na puntos ang driving record ng isang driver?","o":["Kailangang kumuha ang driver ng nakasulat na special point exam","Kukunin ang lisensya nang isang taon","Wala pang mangyayari","Kailangang ulitin ng driver ang road test"],"h1":"Ang unang hakbang ay isang pagsusulit sa papel, hindi suspensyon.","h2":"Sa Pennsylvania, sa unang beses na umabot sa 6 o higit pang puntos ang driving record, makakatanggap ang driver ng abiso na kumuha ng nakasulat na special point exam.","p":"Tama. Sa unang beses na umabot sa 6 na puntos, may nakasulat na point exam."},"ar":{"q":"في Pennsylvania، ماذا يحدث في المرة الأولى التي يصل فيها سجل السائق إلى 6 نقاط؟","o":["يجب على السائق أن يجري امتحانًا كتابيًا خاصًا بالنقاط (special point exam)","تُسحب الرخصة لمدة سنة واحدة","لا يحدث شيء بعد","يجب على السائق أن يعيد اختبار القيادة على الطريق"],"h1":"الخطوة الأولى امتحان على الورق، وليست إيقاف الرخصة.","h2":"في Pennsylvania، في المرة الأولى التي يصل فيها سجل القيادة إلى 6 نقاط أو أكثر، يحصل السائق على إشعار بأن يجري امتحانًا كتابيًا خاصًا بالنقاط.","p":"صحيح. الوصول إلى 6 نقاط أول مرة يعني امتحانًا كتابيًا بالنقاط."},"ref":{"doc":"PA","page":79}},{"id":"pa-023","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, how many points come off your record for every 12 months in a row with no violations or suspension?","o":["1 point","2 points","All of your points","3 points"],"h1":"Safe driving for a full year removes a few points, but not all of them.","h2":"In Pennsylvania, 3 points are removed from your driving record for every 12 months in a row without a suspension or a violation that adds points.","p":"Right. Three points come off for each clean year."},"es":{"q":"En Pensilvania, ¿cuántos puntos se quitan de su historial por cada 12 meses seguidos sin infracciones ni suspensión?","o":["1 punto","2 puntos","Todos sus puntos","3 puntos"],"h1":"Manejar con seguridad un año completo quita algunos puntos, pero no todos.","h2":"En Pensilvania, se quitan 3 puntos de su historial por cada 12 meses seguidos sin suspensión ni infracciones que sumen puntos.","p":"Correcto. Se quitan tres puntos por cada año limpio."},"zh":{"q":"在 Pennsylvania，每连续 12 个月没有违规也没有被吊销驾照，记录上会减去几分？","o":["1 分","2 分","全部的分","3 分"],"h1":"安全驾驶整整一年会减去几分，但不是全部。","h2":"在 Pennsylvania，每连续 12 个月没有被吊销驾照、也没有会加分的违规，你的驾驶记录就会减去 3 分。","p":"对。每个没有违规的一年减去三分。"},"vi":{"q":"Ở Pennsylvania, cứ mỗi 12 tháng liên tục không vi phạm và không bị treo bằng lái, hồ sơ của bạn được xóa bao nhiêu điểm?","o":["1 điểm","2 điểm","Tất cả số điểm của bạn","3 điểm"],"h1":"Lái xe an toàn trọn một năm sẽ xóa vài điểm, nhưng không xóa hết.","h2":"Ở Pennsylvania, cứ mỗi 12 tháng liên tục không bị treo bằng lái và không có vi phạm bị cộng điểm, hồ sơ lái xe của bạn được xóa 3 điểm.","p":"Đúng. Mỗi năm không vi phạm được xóa ba điểm."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang inaalis sa record mo sa bawat 12 sunod-sunod na buwan na walang violation o suspensyon?","o":["1 puntos","2 puntos","Lahat ng puntos mo","3 puntos"],"h1":"Ang ligtas na pagmamaneho nang buong isang taon ay nag-aalis ng ilang puntos, pero hindi lahat.","h2":"Sa Pennsylvania, 3 puntos ang inaalis sa driving record mo sa bawat 12 sunod-sunod na buwan na walang suspensyon o violation na nagdadagdag ng puntos.","p":"Tama. Tatlong puntos ang inaalis sa bawat malinis na taon."},"ar":{"q":"في Pennsylvania، كم نقطة تُحذف من سجلك عن كل 12 شهرًا متتالية بلا مخالفات ولا إيقاف للرخصة؟","o":["نقطة واحدة (1)","نقطتان (2)","كل نقاطك","3 نقاط"],"h1":"القيادة الآمنة لسنة كاملة تحذف بعض النقاط، لكن ليس كلها.","h2":"في Pennsylvania، تُحذف 3 نقاط من سجل قيادتك عن كل 12 شهرًا متتالية بلا إيقاف للرخصة وبلا مخالفة تضيف نقاطًا.","p":"صحيح. تُحذف ثلاث نقاط عن كل سنة نظيفة."},"ref":{"doc":"PA","page":79}},{"id":"pa-024","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, what happens the first time a driver arrested for DUI refuses a breath or blood test?","o":["Only a warning","A one-year license suspension","A 30-day license suspension","Nothing, if found not guilty"],"h1":"By getting a license, you already agreed to be tested.","h2":"In Pennsylvania, refusing a breath or blood test for the first time brings a one-year license suspension, even if the driver is found not guilty of DUI.","p":"Right. A first refusal means a one-year suspension."},"es":{"q":"En Pensilvania, ¿qué pasa la primera vez que un conductor arrestado por manejar bajo los efectos (DUI) se niega a una prueba de aliento o de sangre?","o":["Solo una advertencia","Una suspensión de la licencia por un año","Una suspensión de la licencia por 30 días","Nada, si lo declaran inocente"],"h1":"Al sacar la licencia, usted ya aceptó hacerse la prueba.","h2":"En Pensilvania, negarse por primera vez a una prueba de aliento o de sangre trae una suspensión de la licencia por un año, aunque al conductor lo declaren inocente de DUI.","p":"Correcto. La primera negativa significa un año de suspensión."},"zh":{"q":"在 Pennsylvania，因酒后或药后驾驶（DUI）被逮捕的驾驶人第一次拒绝呼气或验血检测，会怎样？","o":["只是警告","吊销驾照一年","吊销驾照 30 天","如果被判无罪，就什么都没有"],"h1":"你拿到驾照时，就已经同意接受检测了。","h2":"在 Pennsylvania，第一次拒绝呼气或验血检测会被吊销驾照一年，即使驾驶人后来被判 DUI 无罪也一样。","p":"对。第一次拒绝检测会被吊销驾照一年。"},"vi":{"q":"Ở Pennsylvania, điều gì xảy ra lần đầu tiên một tài xế bị bắt vì lái xe khi say (DUI) từ chối thử hơi thở hoặc thử máu?","o":["Chỉ bị cảnh cáo","Bị treo bằng lái một năm","Bị treo bằng lái 30 ngày","Không có gì, nếu được tuyên vô tội"],"h1":"Khi nhận bằng lái, bạn đã đồng ý cho kiểm tra rồi.","h2":"Ở Pennsylvania, từ chối thử hơi thở hoặc thử máu lần đầu sẽ bị treo bằng lái một năm, ngay cả khi tài xế được tuyên vô tội về DUI.","p":"Đúng. Từ chối lần đầu nghĩa là bị treo bằng lái một năm."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa unang beses na tumanggi sa breath o blood test ang driver na inaresto dahil sa DUI?","o":["Babala lang","Isang taong suspensyon ng lisensya","30 araw na suspensyon ng lisensya","Wala, kung mapatunayang hindi nagkasala"],"h1":"Nang kumuha ka ng lisensya, pumayag ka na na ma-test.","h2":"Sa Pennsylvania, ang pagtanggi sa breath o blood test sa unang beses ay may isang taong suspensyon ng lisensya, kahit mapatunayang hindi nagkasala ng DUI ang driver.","p":"Tama. Ang unang pagtanggi ay isang taong suspensyon."},"ar":{"q":"في Pennsylvania، ماذا يحدث في المرة الأولى التي يرفض فيها سائق قُبض عليه بتهمة القيادة تحت تأثير الكحول أو المخدرات (DUI) اختبار النفَس أو الدم؟","o":["إنذار فقط","إيقاف الرخصة لمدة سنة واحدة","إيقاف الرخصة لمدة 30 يومًا","لا شيء، إذا ثبتت براءته"],"h1":"عندما حصلت على الرخصة، كنت قد وافقت مسبقًا على الخضوع للاختبار.","h2":"في Pennsylvania، رفض اختبار النفَس أو الدم لأول مرة يؤدي إلى إيقاف الرخصة لمدة سنة واحدة، حتى لو ثبتت براءة السائق من تهمة DUI.","p":"صحيح. الرفض الأول يعني إيقاف الرخصة لمدة سنة واحدة."},"ref":{"doc":"PA","page":82}},{"id":"pa-025","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, how must a 5-year-old child ride in a car?","o":["With only a seat belt","On an adult's lap","In a booster seat","In a rear-facing infant seat"],"h1":"Children from age 4 up to age 8 need a seat that raises them up.","h2":"In Pennsylvania, children age 4 and older but under 8 must ride in a booster seat used with a lap and shoulder belt, in the front or back seat.","p":"Right. A 5-year-old rides in a booster seat."},"es":{"q":"En Pensilvania, ¿cómo debe viajar en el carro un niño de 5 años?","o":["Solo con el cinturón de seguridad","En las piernas de un adulto","En un asiento elevado (booster)","En un asiento para bebé mirando hacia atrás"],"h1":"Los niños de 4 a 8 años necesitan un asiento que los suba.","h2":"En Pensilvania, los niños de 4 años o más pero menores de 8 deben viajar en un asiento elevado (booster) con cinturón de cadera y hombro, en el asiento delantero o trasero.","p":"Correcto. Un niño de 5 años viaja en un asiento elevado."},"zh":{"q":"在 Pennsylvania，5 岁的孩子坐车时必须怎样乘坐？","o":["只系安全带","坐在大人腿上","坐增高座椅（booster seat）","坐后向婴儿座椅"],"h1":"4 岁到 8 岁的孩子需要一个能把他们垫高的座椅。","h2":"在 Pennsylvania，4 岁及以上、未满 8 岁的孩子必须坐增高座椅，并配合腰部和肩部安全带使用，坐前排或后排都可以。","p":"对。5 岁的孩子要坐增高座椅。"},"vi":{"q":"Ở Pennsylvania, một trẻ 5 tuổi phải ngồi trên xe như thế nào?","o":["Chỉ thắt dây an toàn","Ngồi trên đùi người lớn","Ngồi ghế nâng (booster seat)","Ngồi ghế em bé quay mặt về phía sau"],"h1":"Trẻ từ 4 tuổi đến 8 tuổi cần một chiếc ghế nâng các em lên cao.","h2":"Ở Pennsylvania, trẻ từ 4 tuổi trở lên nhưng chưa đến 8 tuổi phải ngồi ghế nâng, dùng cùng dây an toàn ngang hông và chéo vai, ở ghế trước hoặc ghế sau.","p":"Đúng. Trẻ 5 tuổi ngồi ghế nâng."},"tl":{"q":"Sa Pennsylvania, paano dapat sumakay sa kotse ang isang batang 5 taong gulang?","o":["Naka-seat belt lang","Nakaupo sa kandungan ng matanda","Sa booster seat","Sa rear-facing na upuan ng sanggol"],"h1":"Ang mga batang 4 hanggang 8 taong gulang ay kailangan ng upuang nagpapataas sa kanila.","h2":"Sa Pennsylvania, ang mga batang 4 taong gulang pataas pero wala pang 8 ay dapat sumakay sa booster seat na may lap at shoulder belt, sa harap o likod na upuan.","p":"Tama. Sa booster seat sumasakay ang batang 5 taong gulang."},"ar":{"q":"في Pennsylvania، كيف يجب أن يركب طفل عمره 5 سنوات في السيارة؟","o":["بحزام الأمان فقط","في حضن شخص بالغ","في مقعد رافع (booster seat)","في مقعد رضيع موجّه إلى الخلف"],"h1":"الأطفال من سن 4 حتى سن 8 يحتاجون إلى مقعد يرفعهم إلى أعلى.","h2":"في Pennsylvania، يجب أن يركب الأطفال من سن 4 فما فوق ودون 8 سنوات في مقعد رافع يُستخدم مع حزام الحِجر والكتف، في المقعد الأمامي أو الخلفي.","p":"صحيح. الطفل الذي عمره 5 سنوات يركب في مقعد رافع."},"ref":{"doc":"PA","page":90}},{"id":"pa-026","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, when must your headlights be on during the day?","o":["When your wipers are on because of the weather","Only on the turnpike","Only after 5 p.m.","Never during the day"],"h1":"Think about what you turn on when it starts to rain.","h2":"In Pennsylvania, your headlights must be on any time your wipers are in use because of the weather, and also in work zones and when it is hard to see.","p":"Right. Wipers on for weather means headlights on."},"es":{"q":"En Pensilvania, ¿cuándo deben estar encendidas sus luces delanteras durante el día?","o":["Cuando usa los limpiaparabrisas por el mal tiempo","Solo en la autopista de peaje","Solo después de las 5 p.m.","Nunca durante el día"],"h1":"Piense en lo que enciende cuando empieza a llover.","h2":"En Pensilvania, las luces delanteras deben estar encendidas siempre que use los limpiaparabrisas por el mal tiempo, y también en zonas de construcción y cuando se ve poco.","p":"Correcto. Limpiaparabrisas por mal tiempo significa luces encendidas."},"zh":{"q":"在 Pennsylvania，白天什么时候必须打开车头灯？","o":["因为天气原因使用雨刷的时候","只在收费高速公路（turnpike）上","只在下午 5 点以后","白天从来不用"],"h1":"想一想开始下雨时你会打开什么。","h2":"在 Pennsylvania，只要因为天气原因使用雨刷，就必须打开车头灯；在施工区和看不清楚的时候也要打开。","p":"对。因为天气开雨刷，就要开车头灯。"},"vi":{"q":"Ở Pennsylvania, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Khi bạn bật cần gạt nước vì thời tiết","Chỉ trên đường cao tốc thu phí (turnpike)","Chỉ sau 5 giờ chiều","Không bao giờ vào ban ngày"],"h1":"Hãy nghĩ xem bạn bật cái gì khi trời bắt đầu mưa.","h2":"Ở Pennsylvania, bạn phải bật đèn pha bất cứ khi nào dùng cần gạt nước vì thời tiết, và cả trong khu vực công trường và khi khó nhìn thấy.","p":"Đúng. Bật cần gạt nước vì thời tiết thì phải bật đèn pha."},"tl":{"q":"Sa Pennsylvania, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nakabukas ang wipers mo dahil sa panahon","Sa turnpike lang","Pagkalipas lang ng 5 p.m.","Hindi kailanman sa araw"],"h1":"Isipin kung ano ang binubuksan mo kapag nagsisimulang umulan.","h2":"Sa Pennsylvania, dapat nakabukas ang headlights mo tuwing ginagamit mo ang wipers dahil sa panahon, at gayundin sa mga work zone at kapag mahirap makakita.","p":"Tama. Kapag bukas ang wipers dahil sa panahon, bukas din ang headlights."},"ar":{"q":"في Pennsylvania، متى يجب أن تكون المصابيح الأمامية مضاءة أثناء النهار؟","o":["عندما تكون المسّاحات تعمل بسبب الطقس","على الطريق السريع ذي الرسوم (turnpike) فقط","بعد الساعة 5 مساءً فقط","أبدًا أثناء النهار"],"h1":"فكّر فيما تشغّله عندما يبدأ المطر.","h2":"في Pennsylvania، يجب أن تكون المصابيح الأمامية مضاءة في أي وقت تستخدم فيه المسّاحات بسبب الطقس، وكذلك في مناطق العمل وعندما تصعب الرؤية.","p":"صحيح. المسّاحات تعمل بسبب الطقس يعني أن المصابيح الأمامية مضاءة."},"ref":{"doc":"PA","page":40}},{"id":"pa-027","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, police did not investigate a crash in which someone was hurt. How soon must you send a crash report to PennDOT?","o":["Within 30 days","Within 24 hours","Within 10 days","Within 5 days"],"h1":"It is less than one week.","h2":"In Pennsylvania, if police do not investigate a crash where someone was hurt or killed or a vehicle had to be towed, you must send a Driver's Accident Report to PennDOT within 5 days.","p":"Right. Send the report within 5 days."},"es":{"q":"En Pensilvania, la policía no investigó un choque en el que alguien resultó herido. ¿En qué plazo debe enviar un informe del choque a PennDOT?","o":["En 30 días","En 24 horas","En 10 días","En 5 días"],"h1":"Es menos de una semana.","h2":"En Pensilvania, si la policía no investiga un choque en el que alguien resultó herido o murió, o un vehículo tuvo que ser remolcado, usted debe enviar un informe de accidente del conductor a PennDOT en 5 días.","p":"Correcto. Envíe el informe en 5 días."},"zh":{"q":"在 Pennsylvania，一起有人受伤的车祸没有警察调查。你必须在多长时间内把车祸报告交给 PennDOT？","o":["30 天内","24 小时内","10 天内","5 天内"],"h1":"不到一个星期。","h2":"在 Pennsylvania，如果有人受伤或死亡、或有车辆需要拖走的车祸没有警察调查，你必须在 5 天内把驾驶人事故报告（Driver's Accident Report）交给 PennDOT。","p":"对。要在 5 天内交报告。"},"vi":{"q":"Ở Pennsylvania, cảnh sát không điều tra một vụ tai nạn có người bị thương. Bạn phải gửi báo cáo tai nạn cho PennDOT trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 24 giờ","Trong vòng 10 ngày","Trong vòng 5 ngày"],"h1":"Thời gian này ít hơn một tuần.","h2":"Ở Pennsylvania, nếu cảnh sát không điều tra một vụ tai nạn có người bị thương hoặc tử vong, hoặc có xe phải kéo đi, bạn phải gửi Báo cáo Tai nạn của Tài xế (Driver's Accident Report) cho PennDOT trong vòng 5 ngày.","p":"Đúng. Gửi báo cáo trong vòng 5 ngày."},"tl":{"q":"Sa Pennsylvania, hindi inimbestigahan ng pulis ang isang aksidente kung saan may nasaktan. Gaano kabilis mo dapat ipadala ang crash report sa PennDOT?","o":["Sa loob ng 30 araw","Sa loob ng 24 oras","Sa loob ng 10 araw","Sa loob ng 5 araw"],"h1":"Kulang ito sa isang linggo.","h2":"Sa Pennsylvania, kung hindi inimbestigahan ng pulis ang aksidente kung saan may nasaktan o namatay o may sasakyang kinailangang i-tow, dapat mong ipadala ang Driver's Accident Report sa PennDOT sa loob ng 5 araw.","p":"Tama. Ipadala ang report sa loob ng 5 araw."},"ar":{"q":"في Pennsylvania، لم تحقّق الشرطة في حادث أُصيب فيه شخص. خلال كم من الوقت يجب أن ترسل تقرير الحادث إلى PennDOT؟","o":["خلال 30 يومًا","خلال 24 ساعة","خلال 10 أيام","خلال 5 أيام"],"h1":"المدة أقل من أسبوع واحد.","h2":"في Pennsylvania، إذا لم تحقّق الشرطة في حادث أُصيب فيه شخص أو مات أو اضطُرّ فيه إلى سحب مركبة، يجب أن ترسل تقرير السائق عن الحادث (Driver's Accident Report) إلى PennDOT خلال 5 أيام.","p":"صحيح. أرسل التقرير خلال 5 أيام."},"ref":{"doc":"PA","page":81}},{"id":"pa-028","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, a car is coming toward you at night. Within what distance must you switch to low beams?","o":["100 feet","200 feet","500 feet","1 mile"],"h1":"It is the distance of about one and a half football fields.","h2":"Pennsylvania law requires low beams within 500 feet of an oncoming vehicle, and within 300 feet of a vehicle you are following.","p":"Right. Dim to low beams within 500 feet of an oncoming car."},"es":{"q":"En Pensilvania, un carro viene hacia usted de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","200 pies","500 pies","1 milla"],"h1":"Es la distancia de más o menos un campo y medio de fútbol americano.","h2":"La ley de Pensilvania exige luces bajas a menos de 500 pies de un vehículo que viene de frente, y a menos de 300 pies de un vehículo que usted sigue.","p":"Correcto. Cambie a luces bajas a menos de 500 pies de un carro que viene de frente."},"zh":{"q":"在 Pennsylvania，夜里有车迎面开来。你必须在多远距离内改用近光灯？","o":["100 英尺","200 英尺","500 英尺","1 英里"],"h1":"这个距离大约是一个半美式橄榄球场那么长。","h2":"Pennsylvania 法律规定，迎面来车在 500 英尺以内时要用近光灯；跟在别的车后面 300 英尺以内时也要用近光灯。","p":"对。迎面来车在 500 英尺以内时，要改用近光灯。"},"vi":{"q":"Ở Pennsylvania, ban đêm có một xe đang chạy ngược chiều về phía bạn. Bạn phải chuyển sang đèn cốt (đèn chiếu gần) khi xe đó cách bạn bao xa?","o":["100 feet","200 feet","500 feet","1 dặm"],"h1":"Khoảng cách này dài khoảng một sân bóng bầu dục Mỹ rưỡi.","h2":"Luật Pennsylvania bắt buộc dùng đèn cốt khi xe ngược chiều cách bạn trong vòng 500 feet, và khi bạn chạy sau một xe khác trong vòng 300 feet.","p":"Đúng. Chuyển sang đèn cốt khi xe ngược chiều cách bạn trong vòng 500 feet."},"tl":{"q":"Sa Pennsylvania, may kotseng paparating sa iyo sa gabi. Sa loob ng anong layo dapat kang lumipat sa low beam?","o":["100 talampakan","200 talampakan","500 talampakan","1 milya"],"h1":"Halos kasinghaba ito ng isa't kalahating football field.","h2":"Sa batas ng Pennsylvania, dapat kang gumamit ng low beam kapag ang paparating na sasakyan ay nasa loob ng 500 talampakan, at kapag sinusundan mo ang isang sasakyan sa loob ng 300 talampakan.","p":"Tama. Lumipat sa low beam kapag ang paparating na kotse ay nasa loob ng 500 talampakan."},"ar":{"q":"في Pennsylvania، سيارة قادمة نحوك في الليل. على أي مسافة يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["100 قدم","200 قدم","500 قدم","1 ميل"],"h1":"هذه المسافة تساوي تقريبًا طول ملعب ونصف من ملاعب كرة القدم الأمريكية.","h2":"قانون Pennsylvania يوجب استخدام الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل، وعندما تسير خلف سيارة على بُعد 300 قدم أو أقل.","p":"صحيح. انتقل إلى الأضواء المنخفضة عندما تكون السيارة القادمة على بُعد 500 قدم أو أقل."},"ref":{"doc":"PA","page":40}},{"id":"pa-029","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, how much space must you leave when you pass a bicycle?","o":["At least 2 feet","At least 4 feet","At least 8 feet","At least 12 feet"],"h1":"It is more than the 3 feet some states use.","h2":"In Pennsylvania you must leave at least four feet between your vehicle and a bicycle when you pass, and you may cross a double yellow line to do it if it is safe.","p":"Right. Pennsylvania requires at least four feet when passing a bicycle."},"es":{"q":"En Pensilvania, ¿cuánto espacio debe dejar cuando pasa a una bicicleta?","o":["Por lo menos 2 pies","Por lo menos 4 pies","Por lo menos 8 pies","Por lo menos 12 pies"],"h1":"Es más que los 3 pies que usan algunos estados.","h2":"En Pensilvania usted debe dejar por lo menos cuatro pies entre su vehículo y una bicicleta al pasarla, y puede cruzar una doble línea amarilla para hacerlo si es seguro.","p":"Correcto. Pensilvania exige por lo menos cuatro pies al pasar a una bicicleta."},"zh":{"q":"在 Pennsylvania，超过自行车时，你必须留出多少空间？","o":["至少 2 英尺","至少 4 英尺","至少 8 英尺","至少 12 英尺"],"h1":"它比有些州用的 3 英尺多。","h2":"在 Pennsylvania，超过自行车时，你的车和自行车之间必须至少留出四英尺；如果安全，你可以为此越过双黄线。","p":"对。Pennsylvania 规定超过自行车时至少要留四英尺。"},"vi":{"q":"Ở Pennsylvania, khi vượt qua một xe đạp, bạn phải chừa khoảng cách bao nhiêu?","o":["Ít nhất 2 feet","Ít nhất 4 feet","Ít nhất 8 feet","Ít nhất 12 feet"],"h1":"Khoảng cách này nhiều hơn 3 feet mà một số tiểu bang dùng.","h2":"Ở Pennsylvania, khi vượt xe đạp, bạn phải chừa ít nhất bốn feet giữa xe của bạn và xe đạp, và bạn có thể lấn qua vạch đôi màu vàng để làm việc này nếu an toàn.","p":"Đúng. Pennsylvania bắt buộc chừa ít nhất bốn feet khi vượt xe đạp."},"tl":{"q":"Sa Pennsylvania, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang bisikleta?","o":["Hindi bababa sa 2 talampakan","Hindi bababa sa 4 talampakan","Hindi bababa sa 8 talampakan","Hindi bababa sa 12 talampakan"],"h1":"Mas malaki ito kaysa sa 3 talampakan na ginagamit ng ilang estado.","h2":"Sa Pennsylvania, dapat kang mag-iwan ng hindi bababa sa apat na talampakan sa pagitan ng sasakyan mo at ng bisikleta kapag nilalampasan mo ito, at puwede kang tumawid sa dobleng dilaw na linya para gawin ito kung ligtas.","p":"Tama. Sa Pennsylvania, hindi bababa sa apat na talampakan kapag nilalampasan ang bisikleta."},"ar":{"q":"في Pennsylvania، ما المسافة التي يجب أن تتركها عندما تتجاوز دراجة هوائية؟","o":["2 قدم على الأقل","4 أقدام على الأقل","8 أقدام على الأقل","12 قدمًا على الأقل"],"h1":"هي أكثر من 3 أقدام التي تستخدمها بعض الولايات.","h2":"في Pennsylvania يجب أن تترك أربعة أقدام على الأقل بين سيارتك والدراجة الهوائية عندما تتجاوزها، ويمكنك أن تعبر الخط الأصفر المزدوج لذلك إذا كان آمنًا.","p":"صحيح. Pennsylvania تشترط أربعة أقدام على الأقل عند تجاوز دراجة هوائية."},"ref":{"doc":"PA","page":92}},{"id":"pa-030","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, how close to a bridge or tunnel may you pass another vehicle?","o":["Not within 100 feet","Not within 10 feet","Not within 25 feet","Not within 1 mile"],"h1":"The same distance applies to intersections and railroad crossings.","h2":"In Pennsylvania you may not pass another vehicle within 100 feet of a bridge, elevated structure or tunnel.","p":"Right. No passing within 100 feet of a bridge or tunnel."},"es":{"q":"En Pensilvania, ¿qué tan cerca de un puente o túnel puede pasar a otro vehículo?","o":["No a menos de 100 pies","No a menos de 10 pies","No a menos de 25 pies","No a menos de 1 milla"],"h1":"La misma distancia se aplica a intersecciones y cruces de ferrocarril.","h2":"En Pensilvania usted no puede pasar a otro vehículo a menos de 100 pies de un puente, una estructura elevada o un túnel.","p":"Correcto. No se pasa a menos de 100 pies de un puente o túnel."},"zh":{"q":"在 Pennsylvania，离桥或隧道多近时不可以超车？","o":["100 英尺以内不可以","10 英尺以内不可以","25 英尺以内不可以","1 英里以内不可以"],"h1":"路口和铁路道口也用同样的距离。","h2":"在 Pennsylvania，离桥、高架结构或隧道 100 英尺以内时，你不可以超车。","p":"对。离桥或隧道 100 英尺以内不可以超车。"},"vi":{"q":"Ở Pennsylvania, bạn được vượt xe khác khi cách cầu hoặc đường hầm bao xa?","o":["Không gần hơn 100 feet","Không gần hơn 10 feet","Không gần hơn 25 feet","Không gần hơn 1 dặm"],"h1":"Khoảng cách này cũng áp dụng cho giao lộ và chỗ băng qua đường sắt.","h2":"Ở Pennsylvania, bạn không được vượt xe khác khi cách cầu, công trình trên cao hoặc đường hầm trong vòng 100 feet.","p":"Đúng. Không được vượt xe trong vòng 100 feet trước cầu hoặc đường hầm."},"tl":{"q":"Sa Pennsylvania, gaano kalapit sa tulay o tunnel puwede kang lumampas sa ibang sasakyan?","o":["Hindi sa loob ng 100 talampakan","Hindi sa loob ng 10 talampakan","Hindi sa loob ng 25 talampakan","Hindi sa loob ng 1 milya"],"h1":"Pareho ang layong ito para sa mga intersection at tawiran ng tren.","h2":"Sa Pennsylvania, hindi ka puwedeng lumampas sa ibang sasakyan sa loob ng 100 talampakan mula sa tulay, mataas na istruktura, o tunnel.","p":"Tama. Bawal lumampas sa loob ng 100 talampakan mula sa tulay o tunnel."},"ar":{"q":"في Pennsylvania، على أي قُرب من جسر أو نفق يمكنك أن تتجاوز سيارة أخرى؟","o":["ليس على بُعد 100 قدم أو أقل","ليس على بُعد 10 أقدام أو أقل","ليس على بُعد 25 قدمًا أو أقل","ليس على بُعد 1 ميل أو أقل"],"h1":"المسافة نفسها تنطبق على التقاطعات ومعابر السكك الحديدية.","h2":"في Pennsylvania لا يجوز لك أن تتجاوز سيارة أخرى على بُعد 100 قدم أو أقل من جسر أو منشأة مرتفعة أو نفق.","p":"صحيح. لا تجاوز على بُعد 100 قدم أو أقل من جسر أو نفق."},"ref":{"doc":"PA","page":47}},{"id":"pa-031","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, what is the highest fine for throwing trash from a vehicle onto a road?","o":["$25","$50","$100","$300"],"h1":"It is the largest amount listed.","h2":"In Pennsylvania, throwing trash from a vehicle can bring a fine of up to $300, and the driver can be fined for what passengers throw out.","p":"Right. Littering from a vehicle can cost up to $300."},"es":{"q":"En Pensilvania, ¿cuál es la multa más alta por tirar basura desde un vehículo a la calle?","o":["$25","$50","$100","$300"],"h1":"Es la cantidad más alta de la lista.","h2":"En Pensilvania, tirar basura desde un vehículo puede costar una multa de hasta $300, y al conductor se le puede multar por lo que tiran los pasajeros.","p":"Correcto. Tirar basura desde un vehículo puede costar hasta $300."},"zh":{"q":"在 Pennsylvania，从车里往路上扔垃圾，最高罚款是多少？","o":["$25","$50","$100","$300"],"h1":"它是列出的最大金额。","h2":"在 Pennsylvania，从车里扔垃圾最高可罚 $300，而且乘客扔出去的东西，司机也可能被罚款。","p":"对。从车里乱扔垃圾最高可罚 $300。"},"vi":{"q":"Ở Pennsylvania, mức phạt cao nhất cho việc ném rác từ xe xuống đường là bao nhiêu?","o":["$25","$50","$100","$300"],"h1":"Đó là số tiền lớn nhất trong danh sách.","h2":"Ở Pennsylvania, ném rác từ xe có thể bị phạt đến $300, và người lái có thể bị phạt vì những gì hành khách ném ra.","p":"Đúng. Xả rác từ xe có thể bị phạt đến $300."},"tl":{"q":"Sa Pennsylvania, magkano ang pinakamataas na multa sa pagtatapon ng basura mula sa sasakyan papunta sa kalsada?","o":["$25","$50","$100","$300"],"h1":"Ito ang pinakamalaking halaga sa listahan.","h2":"Sa Pennsylvania, ang pagtatapon ng basura mula sa sasakyan ay puwedeng magmulta ng hanggang $300, at puwedeng multahan ang drayber sa itinatapon ng mga pasahero.","p":"Tama. Ang pagtatapon ng basura mula sa sasakyan ay puwedeng magmulta ng hanggang $300."},"ar":{"q":"في Pennsylvania، ما أعلى غرامة لرمي القمامة من السيارة على الطريق؟","o":["$25","$50","$100","$300"],"h1":"هو أكبر مبلغ في القائمة.","h2":"في Pennsylvania، رمي القمامة من السيارة قد يؤدي إلى غرامة تصل إلى $300، ويمكن تغريم السائق على ما يرميه الركاب.","p":"صحيح. رمي القمامة من السيارة قد يكلّف غرامة تصل إلى $300."},"ref":{"doc":"PA","page":92}},{"id":"pa-032","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, a learner is practicing with a supervising driver who is not a parent, guardian or spouse. How old must that licensed driver be?","o":["At least 21","At least 18","At least 16","At least 25"],"h1":"A parent or spouse may be younger, but anyone else must be older.","h2":"In Pennsylvania, a learner's supervising driver must be a licensed driver at least 21 years old, or a licensed parent, guardian or spouse who is 18 or older, sitting in the front seat.","p":"Right. Any other supervising driver must be at least 21."},"es":{"q":"En Pensilvania, un aprendiz practica con un conductor supervisor que no es su padre, madre, tutor ni cónyuge. ¿Qué edad debe tener ese conductor con licencia?","o":["Al menos 21 años","Al menos 18 años","Al menos 16 años","Al menos 25 años"],"h1":"Un padre o cónyuge puede ser más joven, pero cualquier otra persona debe ser mayor.","h2":"En Pensilvania, el conductor supervisor de un aprendiz debe tener licencia y al menos 21 años, o ser el padre, madre, tutor o cónyuge con licencia de 18 años o más, sentado en el asiento delantero.","p":"Correcto. Cualquier otro conductor supervisor debe tener al menos 21 años."},"zh":{"q":"在 Pennsylvania，一个学车的人和一位监督司机一起练习，这位司机不是他的父母、监护人或配偶。这位有驾照的司机必须至少几岁？","o":["至少 21 岁","至少 18 岁","至少 16 岁","至少 25 岁"],"h1":"父母或配偶可以年轻一些，但其他人必须年纪大一些。","h2":"在 Pennsylvania，学车的人的监督司机必须是至少 21 岁、有驾照的人，或者是 18 岁或以上、有驾照的父母、监护人或配偶，并且要坐在前排。","p":"对。其他任何监督司机都必须至少 21 岁。"},"vi":{"q":"Ở Pennsylvania, một người tập lái đang tập với một tài xế giám sát không phải là cha mẹ, người giám hộ hay vợ/chồng. Tài xế có bằng lái đó phải ít nhất bao nhiêu tuổi?","o":["Ít nhất 21 tuổi","Ít nhất 18 tuổi","Ít nhất 16 tuổi","Ít nhất 25 tuổi"],"h1":"Cha mẹ hoặc vợ/chồng có thể trẻ hơn, nhưng bất kỳ ai khác đều phải lớn tuổi hơn.","h2":"Ở Pennsylvania, tài xế giám sát người tập lái phải là người có bằng lái và ít nhất 21 tuổi, hoặc là cha mẹ, người giám hộ hay vợ/chồng có bằng lái từ 18 tuổi trở lên, ngồi ở ghế trước.","p":"Đúng. Bất kỳ tài xế giám sát nào khác phải ít nhất 21 tuổi."},"tl":{"q":"Sa Pennsylvania, nagsasanay ang isang learner kasama ang supervising driver na hindi niya magulang, guardian o asawa. Ilang taon dapat ang lisensyadong driver na iyon?","o":["Hindi bababa sa 21","Hindi bababa sa 18","Hindi bababa sa 16","Hindi bababa sa 25"],"h1":"Puwedeng mas bata ang magulang o asawa, pero mas matanda dapat ang iba.","h2":"Sa Pennsylvania, ang supervising driver ng learner ay dapat lisensyadong driver na hindi bababa sa 21 taong gulang, o lisensyadong magulang, guardian o asawa na 18 o higit pa, na nakaupo sa harapang upuan.","p":"Tama. Ang ibang supervising driver ay dapat hindi bababa sa 21."},"ar":{"q":"في Pennsylvania، متعلّم يتدرّب مع سائق مشرف ليس أحد والديه ولا الوصي عليه ولا زوجه. كم يجب أن يكون عمر هذا السائق المرخّص؟","o":["21 سنة على الأقل","18 سنة على الأقل","16 سنة على الأقل","25 سنة على الأقل"],"h1":"يمكن أن يكون أحد الوالدين أو الزوج أصغر سنًا، لكن أي شخص آخر يجب أن يكون أكبر.","h2":"في Pennsylvania يجب أن يكون السائق المشرف على المتعلّم سائقًا مرخّصًا عمره 21 سنة على الأقل، أو أحد الوالدين أو الوصي أو الزوج المرخّص الذي عمره 18 سنة أو أكثر، ويجلس في المقعد الأمامي.","p":"صحيح. أي سائق مشرف آخر يجب أن يكون عمره 21 سنة على الأقل."},"ref":{"doc":"PA","page":2}},{"id":"pa-033","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, a driver under 18 fails the road test. How long must they wait before trying again?","o":["The next business day","7 days","30 days","6 months"],"h1":"It is about one week.","h2":"In Pennsylvania, a driver under 18 who fails the road test must wait 7 days before taking it again.","p":"Right. Wait 7 days, and use them to practice."},"es":{"q":"En Pensilvania, un conductor menor de 18 años no aprueba el examen de manejo. ¿Cuánto tiempo debe esperar para intentarlo de nuevo?","o":["El siguiente día hábil","7 días","30 días","6 meses"],"h1":"Es más o menos una semana.","h2":"En Pensilvania, un conductor menor de 18 años que no aprueba el examen de manejo debe esperar 7 días para tomarlo de nuevo.","p":"Correcto. Espere 7 días y úselos para practicar."},"zh":{"q":"在 Pennsylvania，一个未满 18 岁的司机路考没有通过。他要等多久才能再考？","o":["下一个工作日","7 天","30 天","6 个月"],"h1":"大约是一个星期。","h2":"在 Pennsylvania，未满 18 岁的司机路考没有通过，必须等 7 天才能再考。","p":"对。等 7 天，用这段时间多练习。"},"vi":{"q":"Ở Pennsylvania, một tài xế dưới 18 tuổi thi trượt kỳ thi lái xe trên đường. Người đó phải chờ bao lâu mới được thi lại?","o":["Ngày làm việc tiếp theo","7 ngày","30 ngày","6 tháng"],"h1":"Khoảng một tuần.","h2":"Ở Pennsylvania, tài xế dưới 18 tuổi thi trượt kỳ thi lái xe trên đường phải chờ 7 ngày mới được thi lại.","p":"Đúng. Chờ 7 ngày, và dùng thời gian đó để tập luyện."},"tl":{"q":"Sa Pennsylvania, bumagsak sa road test ang isang driver na wala pang 18. Gaano katagal siya dapat maghintay bago sumubok ulit?","o":["Ang susunod na araw ng trabaho","7 araw","30 araw","6 na buwan"],"h1":"Mga isang linggo ito.","h2":"Sa Pennsylvania, ang driver na wala pang 18 na bumagsak sa road test ay dapat maghintay ng 7 araw bago kumuha ulit nito.","p":"Tama. Maghintay ng 7 araw, at gamitin ang mga ito sa pagsasanay."},"ar":{"q":"في Pennsylvania، سائق عمره أقل من 18 سنة رسب في اختبار الطريق. كم يجب أن ينتظر قبل أن يحاول مرة أخرى؟","o":["يوم العمل التالي","7 أيام","30 يومًا","6 أشهر"],"h1":"هي أسبوع تقريبًا.","h2":"في Pennsylvania، السائق الذي عمره أقل من 18 سنة ورسب في اختبار الطريق يجب أن ينتظر 7 أيام قبل أن يجريه مرة أخرى.","p":"صحيح. انتظر 7 أيام، واستخدمها للتدريب."},"ref":{"doc":"PA","page":6}},{"id":"pa-034","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how many chances do you get to pass the road test with one learner's permit?","o":["One","Two","Three","As many as you want"],"h1":"After the last failed try, you must apply to extend the permit.","h2":"In Pennsylvania you get three chances to pass the road test with each learner's permit; after the third failure you must apply to extend it.","p":"Right. Three tries per permit."},"es":{"q":"En Pensilvania, ¿cuántas oportunidades tiene para aprobar el examen de manejo con un mismo permiso de aprendiz?","o":["Una","Dos","Tres","Todas las que quiera"],"h1":"Después del último intento fallido, debe solicitar que se extienda el permiso.","h2":"En Pensilvania usted tiene tres oportunidades para aprobar el examen de manejo con cada permiso de aprendiz; después del tercer intento fallido debe solicitar que se extienda.","p":"Correcto. Tres intentos por permiso."},"zh":{"q":"在 Pennsylvania，用一张学习驾照，你有几次机会通过路考？","o":["一次","两次","三次","想考几次都可以"],"h1":"最后一次没通过以后，你必须申请延长学习驾照。","h2":"在 Pennsylvania，每张学习驾照有三次机会通过路考；第三次没通过以后，你必须申请延长学习驾照。","p":"对。每张学习驾照可以考三次。"},"vi":{"q":"Ở Pennsylvania, với một giấy phép tập lái, bạn có bao nhiêu lần cơ hội để thi đậu kỳ thi lái xe trên đường?","o":["Một","Hai","Ba","Bao nhiêu lần cũng được"],"h1":"Sau lần thi trượt cuối cùng, bạn phải nộp đơn xin gia hạn giấy phép.","h2":"Ở Pennsylvania, với mỗi giấy phép tập lái bạn có ba cơ hội để thi đậu kỳ thi lái xe trên đường; sau lần trượt thứ ba, bạn phải nộp đơn xin gia hạn giấy phép.","p":"Đúng. Ba lần thi cho mỗi giấy phép."},"tl":{"q":"Sa Pennsylvania, ilang pagkakataon ang mayroon ka para pumasa sa road test sa isang learner's permit?","o":["Isa","Dalawa","Tatlo","Kahit ilan ang gusto mo"],"h1":"Pagkatapos ng huling bagsak, dapat kang mag-apply para i-extend ang permit.","h2":"Sa Pennsylvania, may tatlong pagkakataon ka para pumasa sa road test sa bawat learner's permit; pagkatapos ng ikatlong bagsak, dapat kang mag-apply para i-extend ito.","p":"Tama. Tatlong subok bawat permit."},"ar":{"q":"في Pennsylvania، كم فرصة لديك لتنجح في اختبار الطريق بتصريح تعلّم واحد؟","o":["واحدة","اثنتان","ثلاث","بقدر ما تريد"],"h1":"بعد آخر محاولة فاشلة، يجب أن تطلب تمديد التصريح.","h2":"في Pennsylvania لديك ثلاث فرص لتنجح في اختبار الطريق مع كل تصريح تعلّم؛ وبعد الرسوب الثالث يجب أن تطلب تمديده.","p":"صحيح. ثلاث محاولات لكل تصريح."},"ref":{"doc":"PA","page":6}},{"id":"pa-035","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, you just moved here and have a valid license from another state. How soon must you get a Pennsylvania license?","o":["Within 10 days","Within 30 days","Within 1 year","Within 60 days"],"h1":"It is about two months.","h2":"In Pennsylvania, a new resident with a valid license from another state must get a Pennsylvania driver's license within 60 days and turn in the old license.","p":"Right. New residents have 60 days."},"es":{"q":"En Pensilvania, usted acaba de mudarse aquí y tiene una licencia válida de otro estado. ¿En qué plazo debe obtener una licencia de Pensilvania?","o":["En 10 días","En 30 días","En 1 año","En 60 días"],"h1":"Son unos dos meses.","h2":"En Pensilvania, un nuevo residente con una licencia válida de otro estado debe obtener una licencia de conducir de Pensilvania en 60 días y entregar la licencia anterior.","p":"Correcto. Los nuevos residentes tienen 60 días."},"zh":{"q":"在 Pennsylvania，你刚搬来这里，持有另一个州的有效驾照。你必须在多长时间内办 Pennsylvania 驾照？","o":["10 天内","30 天内","1 年内","60 天内"],"h1":"大约是两个月。","h2":"在 Pennsylvania，持有另一个州有效驾照的新居民，必须在 60 天内办 Pennsylvania 驾照，并交回旧驾照。","p":"对。新居民有 60 天时间。"},"vi":{"q":"Ở Pennsylvania, bạn vừa chuyển đến đây và có bằng lái hợp lệ của một tiểu bang khác. Bạn phải lấy bằng lái Pennsylvania trong thời hạn bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 1 năm","Trong vòng 60 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở Pennsylvania, cư dân mới có bằng lái hợp lệ của tiểu bang khác phải lấy bằng lái Pennsylvania trong vòng 60 ngày và nộp lại bằng lái cũ.","p":"Đúng. Cư dân mới có 60 ngày."},"tl":{"q":"Sa Pennsylvania, kalilipat mo lang dito at may valid kang lisensya mula sa ibang estado. Gaano kabilis ka dapat kumuha ng lisensya ng Pennsylvania?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 1 taon","Sa loob ng 60 araw"],"h1":"Mga dalawang buwan ito.","h2":"Sa Pennsylvania, ang bagong residente na may valid na lisensya mula sa ibang estado ay dapat kumuha ng driver's license ng Pennsylvania sa loob ng 60 araw at isuko ang lumang lisensya.","p":"Tama. May 60 araw ang mga bagong residente."},"ar":{"q":"في Pennsylvania، انتقلت إلى هنا للتو ومعك رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة Pennsylvania؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 1 سنة","خلال 60 يومًا"],"h1":"هي شهران تقريبًا.","h2":"في Pennsylvania، يجب على المقيم الجديد الذي معه رخصة سارية من ولاية أخرى أن يحصل على رخصة قيادة Pennsylvania خلال 60 يومًا وأن يسلّم الرخصة القديمة.","p":"صحيح. لدى المقيمين الجدد 60 يومًا."},"ref":{"doc":"PA","page":3}},{"id":"pa-036","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, a driver under 18 is convicted of speeding. How far over the limit leads to a license suspension, even with no other points?","o":["26 mph or more","10 mph or more","15 mph or more","5 mph or more"],"h1":"It is a little more than 25 mph over.","h2":"In Pennsylvania, a driver under 18 convicted of driving 26 mph or more over the speed limit has the license suspended, for 90 days the first time.","p":"Right. 26 mph or more over the limit means a suspension for drivers under 18."},"es":{"q":"En Pensilvania, un conductor menor de 18 años es condenado por exceso de velocidad. ¿Cuánto por encima del límite lleva a la suspensión de la licencia, aunque no tenga otros puntos?","o":["26 mph o más","10 mph o más","15 mph o más","5 mph o más"],"h1":"Es un poco más de 25 mph por encima.","h2":"En Pensilvania, a un conductor menor de 18 años condenado por manejar 26 mph o más por encima del límite se le suspende la licencia, por 90 días la primera vez.","p":"Correcto. 26 mph o más por encima del límite significa una suspensión para menores de 18 años."},"zh":{"q":"在 Pennsylvania，一个未满 18 岁的司机因超速被定罪。超过限速多少，即使没有其他扣分，驾照也会被暂停？","o":["26 mph 或以上","10 mph 或以上","15 mph 或以上","5 mph 或以上"],"h1":"比超速 25 mph 多一点。","h2":"在 Pennsylvania，未满 18 岁的司机如果因超过限速 26 mph 或以上被定罪，驾照会被暂停，第一次是 90 天。","p":"对。未满 18 岁的司机超过限速 26 mph 或以上，驾照会被暂停。"},"vi":{"q":"Ở Pennsylvania, một tài xế dưới 18 tuổi bị kết tội chạy quá tốc độ. Chạy quá giới hạn bao nhiêu thì bị treo bằng lái, dù không có điểm phạt nào khác?","o":["26 mph trở lên","10 mph trở lên","15 mph trở lên","5 mph trở lên"],"h1":"Hơn 25 mph một chút.","h2":"Ở Pennsylvania, tài xế dưới 18 tuổi bị kết tội chạy quá tốc độ giới hạn 26 mph trở lên sẽ bị treo bằng lái, lần đầu là 90 ngày.","p":"Đúng. Chạy quá giới hạn 26 mph trở lên thì tài xế dưới 18 tuổi bị treo bằng lái."},"tl":{"q":"Sa Pennsylvania, nahatulan sa speeding ang isang driver na wala pang 18. Gaano kalampas sa limit ang magdudulot ng suspensyon ng lisensya, kahit walang ibang puntos?","o":["26 mph o higit pa","10 mph o higit pa","15 mph o higit pa","5 mph o higit pa"],"h1":"Medyo higit ito sa 25 mph na lampas.","h2":"Sa Pennsylvania, ang driver na wala pang 18 na nahatulan sa pagmamaneho nang 26 mph o higit pa na lampas sa speed limit ay masususpinde ang lisensya, nang 90 araw sa unang beses.","p":"Tama. Ang 26 mph o higit pa na lampas sa limit ay suspensyon para sa mga driver na wala pang 18."},"ar":{"q":"في Pennsylvania، سائق عمره أقل من 18 سنة أُدين بتجاوز السرعة. كم يجب أن يتجاوز الحد حتى تُعلَّق رخصته، حتى لو لم تكن لديه نقاط أخرى؟","o":["26 mph أو أكثر","10 mph أو أكثر","15 mph أو أكثر","5 mph أو أكثر"],"h1":"هو أكثر قليلًا من 25 mph فوق الحد.","h2":"في Pennsylvania، السائق الذي عمره أقل من 18 سنة وأُدين بالقيادة بسرعة 26 mph أو أكثر فوق حد السرعة تُعلَّق رخصته، لمدة 90 يومًا في المرة الأولى.","p":"صحيح. تجاوز الحد بـ 26 mph أو أكثر يعني تعليق الرخصة للسائقين الذين أعمارهم أقل من 18 سنة."},"ref":{"doc":"PA","page":79}},{"id":"pa-037","scope":"PA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Pennsylvania, the yellow lights on a school zone speed sign are flashing. What is the speed limit?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"It is lower than 20 mph.","h2":"In Pennsylvania, you may drive no faster than 15 mph in a school zone when the yellow lights are flashing or during the times shown on the sign.","p":"Right. 15 mph in a school zone."},"es":{"q":"En Pensilvania, las luces amarillas de una señal de velocidad de zona escolar están parpadeando. ¿Cuál es el límite de velocidad?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Es menos de 20 mph.","h2":"En Pensilvania, no puede manejar a más de 15 mph en una zona escolar cuando las luces amarillas parpadean o durante el horario que indica la señal.","p":"Correcto. 15 mph en una zona escolar."},"zh":{"q":"在 Pennsylvania，学校区限速牌上的黄灯在闪。限速是多少？","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"比 20 mph 低。","h2":"在 Pennsylvania，黄灯在闪时或在限速牌写的时间内，你在学校区开车不能超过 15 mph。","p":"对。学校区限速 15 mph。"},"vi":{"q":"Ở Pennsylvania, đèn vàng trên biển báo tốc độ khu vực trường học đang nhấp nháy. Tốc độ giới hạn là bao nhiêu?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Thấp hơn 20 mph.","h2":"Ở Pennsylvania, bạn không được lái nhanh hơn 15 mph trong khu vực trường học khi đèn vàng nhấp nháy hoặc trong những giờ ghi trên biển báo.","p":"Đúng. 15 mph trong khu vực trường học."},"tl":{"q":"Sa Pennsylvania, kumikislap ang mga dilaw na ilaw sa speed sign ng school zone. Ano ang speed limit?","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"Mas mababa ito sa 20 mph.","h2":"Sa Pennsylvania, hindi ka puwedeng magmaneho nang mas mabilis sa 15 mph sa school zone kapag kumikislap ang mga dilaw na ilaw o sa mga oras na nakasulat sa sign.","p":"Tama. 15 mph sa school zone."},"ar":{"q":"في Pennsylvania، الأضواء الصفراء على لافتة السرعة في منطقة المدرسة تومض. ما حد السرعة؟","o":["10 mph","15 mph","20 mph","25 mph"],"h1":"هو أقل من 20 mph.","h2":"في Pennsylvania، لا يجوز أن تقود أسرع من 15 mph في منطقة المدرسة عندما تومض الأضواء الصفراء أو في الأوقات المكتوبة على اللافتة.","p":"صحيح. 15 mph في منطقة المدرسة."},"ref":{"doc":"PA","page":9}},{"id":"pa-038","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, how many points go on your record for speeding in a school zone?","o":["One point","Two points","Three points","Six points"],"h1":"You also pay a fine, and the points are fewer than for passing a stopped school bus.","h2":"In Pennsylvania, speeding in a school zone puts three points on your driving record, and you are also fined.","p":"Right. Three points, plus a fine."},"es":{"q":"En Pensilvania, ¿cuántos puntos se agregan a su historial por exceso de velocidad en una zona escolar?","o":["Un punto","Dos puntos","Tres puntos","Seis puntos"],"h1":"También paga una multa, y son menos puntos que por pasar un autobús escolar detenido.","h2":"En Pensilvania, el exceso de velocidad en una zona escolar agrega tres puntos a su historial de manejo, y además recibe una multa.","p":"Correcto. Tres puntos, más una multa."},"zh":{"q":"在 Pennsylvania，在学校区超速，你的驾驶记录会加几分？","o":["一分","两分","三分","六分"],"h1":"你还要交罚款，而且分数比超过停着的校车要少。","h2":"在 Pennsylvania，在学校区超速，你的驾驶记录会加三分，还会被罚款。","p":"对。加三分，还要罚款。"},"vi":{"q":"Ở Pennsylvania, chạy quá tốc độ trong khu vực trường học thì hồ sơ của bạn bị ghi bao nhiêu điểm?","o":["Một điểm","Hai điểm","Ba điểm","Sáu điểm"],"h1":"Bạn cũng bị phạt tiền, và số điểm ít hơn so với vượt qua xe buýt trường học đang dừng.","h2":"Ở Pennsylvania, chạy quá tốc độ trong khu vực trường học sẽ bị ghi ba điểm vào hồ sơ lái xe, và bạn cũng bị phạt tiền.","p":"Đúng. Ba điểm, cộng thêm tiền phạt."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang mapupunta sa record mo dahil sa speeding sa school zone?","o":["Isang puntos","Dalawang puntos","Tatlong puntos","Anim na puntos"],"h1":"Magbabayad ka rin ng multa, at mas kaunti ang puntos kaysa sa paglampas sa nakahintong school bus.","h2":"Sa Pennsylvania, ang speeding sa school zone ay naglalagay ng tatlong puntos sa iyong driving record, at may multa ka rin.","p":"Tama. Tatlong puntos, dagdag ang multa."},"ar":{"q":"في Pennsylvania، كم نقطة تُضاف إلى سجلك بسبب تجاوز السرعة في منطقة المدرسة؟","o":["نقطة واحدة","نقطتان","ثلاث نقاط","ست نقاط"],"h1":"ستدفع غرامة أيضًا، والنقاط أقل من نقاط تجاوز حافلة مدرسية متوقفة.","h2":"في Pennsylvania، تجاوز السرعة في منطقة المدرسة يضيف ثلاث نقاط إلى سجل قيادتك، وتدفع غرامة أيضًا.","p":"صحيح. ثلاث نقاط، مع غرامة."},"ref":{"doc":"PA","page":9}},{"id":"pa-039","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, police stop you for a traffic violation in a work zone, and your headlights are off. What happens?","o":["Nothing extra, if it is daytime","You get a warning only","Your license is suspended","You pay an extra $25 fine"],"h1":"Headlights are required in every posted work zone, day or night.","h2":"In Pennsylvania, if you are stopped for a traffic violation in a work zone with your headlights off, you pay an extra $25 fine.","p":"Right. Headlights off in a work zone adds $25 to the fine."},"es":{"q":"En Pensilvania, la policía lo detiene por una infracción en una zona de trabajo y sus faros están apagados. ¿Qué pasa?","o":["Nada más, si es de día","Solo recibe una advertencia","Le suspenden la licencia","Paga una multa adicional de $25"],"h1":"Los faros son obligatorios en toda zona de trabajo señalizada, de día o de noche.","h2":"En Pensilvania, si lo detienen por una infracción en una zona de trabajo con los faros apagados, paga una multa adicional de $25.","p":"Correcto. Los faros apagados en una zona de trabajo suman $25 a la multa."},"zh":{"q":"在 Pennsylvania，你在施工区因交通违规被警察拦下，而你的前灯没有开。会怎样？","o":["如果是白天，就没有额外处罚","只会得到警告","驾照会被暂停","要多交 $25 罚款"],"h1":"在每个有标志的施工区，不管白天还是晚上都必须开前灯。","h2":"在 Pennsylvania，如果你在施工区因交通违规被拦下，而前灯没有开，你要多交 $25 罚款。","p":"对。在施工区不开前灯，罚款会多 $25。"},"vi":{"q":"Ở Pennsylvania, cảnh sát chặn bạn lại vì vi phạm giao thông trong khu vực công trường, và đèn pha của bạn đang tắt. Chuyện gì xảy ra?","o":["Không có gì thêm, nếu là ban ngày","Bạn chỉ bị cảnh cáo","Bạn bị treo bằng lái","Bạn bị phạt thêm $25"],"h1":"Phải bật đèn pha trong mọi khu vực công trường có biển báo, cả ngày lẫn đêm.","h2":"Ở Pennsylvania, nếu bạn bị chặn lại vì vi phạm giao thông trong khu vực công trường mà đèn pha đang tắt, bạn bị phạt thêm $25.","p":"Đúng. Tắt đèn pha trong khu vực công trường thì bị phạt thêm $25."},"tl":{"q":"Sa Pennsylvania, pinahinto ka ng pulis dahil sa traffic violation sa work zone, at nakapatay ang headlights mo. Ano ang mangyayari?","o":["Walang dagdag, kung araw","Babala lang ang makukuha mo","Masususpinde ang lisensya mo","Magbabayad ka ng dagdag na $25 na multa"],"h1":"Kailangan ang headlights sa bawat work zone na may karatula, araw man o gabi.","h2":"Sa Pennsylvania, kung pinahinto ka dahil sa traffic violation sa work zone at nakapatay ang headlights mo, magbabayad ka ng dagdag na $25 na multa.","p":"Tama. Ang nakapatay na headlights sa work zone ay nagdadagdag ng $25 sa multa."},"ar":{"q":"في Pennsylvania، أوقفتك الشرطة بسبب مخالفة مرورية في منطقة أعمال طرق، وكانت أضواؤك الأمامية مطفأة. ماذا يحدث؟","o":["لا شيء إضافي، إذا كان الوقت نهارًا","تحصل على تحذير فقط","تُعلَّق رخصتك","تدفع غرامة إضافية قدرها $25"],"h1":"الأضواء الأمامية مطلوبة في كل منطقة أعمال عليها لافتات، في النهار أو الليل.","h2":"في Pennsylvania، إذا أُوقفت بسبب مخالفة مرورية في منطقة أعمال طرق وأضواؤك الأمامية مطفأة، تدفع غرامة إضافية قدرها $25.","p":"صحيح. الأضواء المطفأة في منطقة أعمال الطرق تضيف $25 إلى الغرامة."},"ref":{"doc":"PA","page":18}},{"id":"pa-040","scope":"PA","cat":"signals","sign":null,"c":0,"en":{"q":"In Pennsylvania, you are driving at 45 mph. How far before a turn must you turn on your signal?","o":["At least 300 feet","At least 100 feet","At least 50 feet","At least 1,000 feet"],"h1":"At 35 mph or more, you need more than the city distance of 100 feet.","h2":"In Pennsylvania, when you drive 35 mph or faster, you must signal at least 300 feet before you turn; below 35 mph it is at least 100 feet.","p":"Right. At 35 mph or more, signal at least 300 feet ahead."},"es":{"q":"En Pensilvania, usted maneja a 45 mph. ¿Con cuánta distancia antes de una vuelta debe poner la direccional?","o":["Al menos 300 pies","Al menos 100 pies","Al menos 50 pies","Al menos 1,000 pies"],"h1":"A 35 mph o más, necesita más que los 100 pies de la ciudad.","h2":"En Pensilvania, cuando maneja a 35 mph o más, debe poner la direccional al menos 300 pies antes de dar la vuelta; a menos de 35 mph son al menos 100 pies.","p":"Correcto. A 35 mph o más, ponga la direccional al menos 300 pies antes."},"zh":{"q":"在 Pennsylvania，你以 45 mph 的速度开车。转弯前多远必须打方向灯？","o":["至少 300 英尺","至少 100 英尺","至少 50 英尺","至少 1,000 英尺"],"h1":"在 35 mph 或以上，需要比市区的 100 英尺更远。","h2":"在 Pennsylvania，当你以 35 mph 或更快的速度开车时，必须在转弯前至少 300 英尺打方向灯；低于 35 mph 时，至少 100 英尺。","p":"对。在 35 mph 或以上，至少提前 300 英尺打方向灯。"},"vi":{"q":"Ở Pennsylvania, bạn đang lái xe ở tốc độ 45 mph. Bạn phải bật đèn xi nhan cách chỗ rẽ bao xa?","o":["Ít nhất 300 feet","Ít nhất 100 feet","Ít nhất 50 feet","Ít nhất 1,000 feet"],"h1":"Ở 35 mph trở lên, bạn cần xa hơn khoảng cách 100 feet trong thành phố.","h2":"Ở Pennsylvania, khi bạn lái từ 35 mph trở lên, bạn phải bật đèn xi nhan ít nhất 300 feet trước khi rẽ; dưới 35 mph thì ít nhất 100 feet.","p":"Đúng. Ở 35 mph trở lên, bật đèn xi nhan trước ít nhất 300 feet."},"tl":{"q":"Sa Pennsylvania, nagmamaneho ka sa 45 mph. Gaano kalayo bago lumiko dapat mong buksan ang signal mo?","o":["Hindi bababa sa 300 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 50 talampakan","Hindi bababa sa 1,000 talampakan"],"h1":"Sa 35 mph o higit pa, kailangan mo ng higit sa 100 talampakan na layo sa lungsod.","h2":"Sa Pennsylvania, kapag nagmamaneho ka sa 35 mph o mas mabilis, dapat kang mag-signal nang hindi bababa sa 300 talampakan bago lumiko; kapag mas mababa sa 35 mph, hindi bababa sa 100 talampakan.","p":"Tama. Sa 35 mph o higit pa, mag-signal nang hindi bababa sa 300 talampakan bago lumiko."},"ar":{"q":"في Pennsylvania، أنت تقود بسرعة 45 mph. على أي مسافة قبل المنعطف يجب أن تشغّل إشارة الانعطاف؟","o":["300 قدم على الأقل","100 قدم على الأقل","50 قدمًا على الأقل","1,000 قدم على الأقل"],"h1":"بسرعة 35 mph أو أكثر، تحتاج إلى أكثر من مسافة المدينة وهي 100 قدم.","h2":"في Pennsylvania، عندما تقود بسرعة 35 mph أو أسرع، يجب أن تشغّل الإشارة قبل المنعطف بـ 300 قدم على الأقل؛ وتحت 35 mph تكون المسافة 100 قدم على الأقل.","p":"صحيح. بسرعة 35 mph أو أكثر، شغّل الإشارة قبل 300 قدم على الأقل."},"ref":{"doc":"PA","page":44}},{"id":"pa-041","scope":"PA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Pennsylvania, you must drive slower than 40 mph on a limited access highway. What should you do?","o":["Drive on the shoulder","Turn on your hazard (four-way) flashers","Flash your high beams","Honk every few seconds"],"h1":"Warn the drivers coming up behind you.","h2":"In Pennsylvania, if you must drive below 40 mph on a limited access highway, you should turn on your hazard flashers to warn drivers behind you.","p":"Right. Below 40 mph on a limited access highway, use your hazard flashers."},"es":{"q":"En Pensilvania, usted debe manejar a menos de 40 mph en una autopista de acceso limitado. ¿Qué debe hacer?","o":["Manejar por el acotamiento","Encender las luces de emergencia (intermitentes)","Hacer señales con las luces altas","Tocar el claxon cada pocos segundos"],"h1":"Avise a los conductores que vienen detrás de usted.","h2":"En Pensilvania, si debe manejar a menos de 40 mph en una autopista de acceso limitado, debe encender las luces de emergencia para avisar a los conductores que vienen detrás.","p":"Correcto. A menos de 40 mph en una autopista de acceso limitado, use las luces de emergencia."},"zh":{"q":"在 Pennsylvania，你在限制出入的高速公路上必须以低于 40 mph 的速度开车。你应该怎么做？","o":["在路肩上开","打开危险警示灯（四个方向灯一起闪）","闪远光灯","每隔几秒按一次喇叭"],"h1":"提醒后面开过来的司机。","h2":"在 Pennsylvania，如果你在限制出入的高速公路上必须以低于 40 mph 的速度开车，你应该打开危险警示灯，提醒后面的司机。","p":"对。在限制出入的高速公路上低于 40 mph 时，要打开危险警示灯。"},"vi":{"q":"Ở Pennsylvania, bạn phải lái chậm hơn 40 mph trên xa lộ hạn chế lối ra vào. Bạn nên làm gì?","o":["Lái trên lề đường","Bật đèn cảnh báo nguy hiểm (đèn nháy bốn bên)","Nháy đèn pha chiếu xa","Bấm còi vài giây một lần"],"h1":"Cảnh báo những tài xế đang chạy tới phía sau bạn.","h2":"Ở Pennsylvania, nếu bạn phải lái dưới 40 mph trên xa lộ hạn chế lối ra vào, bạn nên bật đèn cảnh báo nguy hiểm để cảnh báo các tài xế phía sau.","p":"Đúng. Dưới 40 mph trên xa lộ hạn chế lối ra vào, hãy bật đèn cảnh báo nguy hiểm."},"tl":{"q":"Sa Pennsylvania, kailangan mong magmaneho nang mas mabagal sa 40 mph sa limited access highway. Ano ang dapat mong gawin?","o":["Magmaneho sa shoulder","Buksan ang hazard (four-way) flashers mo","I-flash ang high beams mo","Bumusina bawat ilang segundo"],"h1":"Babalaan ang mga driver na paparating sa likod mo.","h2":"Sa Pennsylvania, kung kailangan mong magmaneho nang mas mababa sa 40 mph sa limited access highway, dapat mong buksan ang hazard flashers mo para babalaan ang mga driver sa likod mo.","p":"Tama. Kapag mas mababa sa 40 mph sa limited access highway, gamitin ang hazard flashers mo."},"ar":{"q":"في Pennsylvania، يجب أن تقود بسرعة أقل من 40 mph على طريق سريع محدود المداخل. ماذا عليك أن تفعل؟","o":["أن تقود على كتف الطريق","أن تشغّل أضواء التحذير (الأضواء الأربعة الوامضة)","أن تومض بالأضواء العالية","أن تستخدم البوق كل بضع ثوانٍ"],"h1":"نبّه السائقين القادمين خلفك.","h2":"في Pennsylvania، إذا كان عليك أن تقود بسرعة أقل من 40 mph على طريق سريع محدود المداخل، فعليك أن تشغّل أضواء التحذير لتنبيه السائقين خلفك.","p":"صحيح. تحت 40 mph على طريق سريع محدود المداخل، استخدم أضواء التحذير."},"ref":{"doc":"PA","page":44}},{"id":"pa-042","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, snow or ice flies off your moving car and hits another vehicle, causing serious injury. What fine can you face?","o":["No fine, because it was an accident","Up to $50","$200 to $1,000","Exactly $25"],"h1":"The fine can reach four figures.","h2":"In Pennsylvania, if snow or ice from your moving vehicle strikes a vehicle or person and causes death or serious injury, you face a fine of $200 to $1,000 for each offense, so clear your car before you drive.","p":"Right. $200 to $1,000, so clear all snow and ice first."},"es":{"q":"En Pensilvania, nieve o hielo sale volando de su carro en movimiento y golpea otro vehículo, causando una lesión grave. ¿Qué multa puede recibir?","o":["Ninguna multa, porque fue un accidente","Hasta $50","De $200 a $1,000","Exactamente $25"],"h1":"La multa puede llegar a cuatro cifras.","h2":"En Pensilvania, si la nieve o el hielo de su vehículo en movimiento golpea a un vehículo o a una persona y causa la muerte o una lesión grave, puede recibir una multa de $200 a $1,000 por cada infracción, así que limpie su carro antes de manejar.","p":"Correcto. De $200 a $1,000, así que quite toda la nieve y el hielo primero."},"zh":{"q":"在 Pennsylvania，你开车时车上的雪或冰飞出去，打到另一辆车，造成重伤。你可能被罚多少钱？","o":["不罚款，因为那是意外","最多 $50","$200 到 $1,000","正好 $25"],"h1":"罚款可能达到四位数。","h2":"在 Pennsylvania，如果你行驶中的车上的雪或冰打到车辆或人，造成死亡或重伤，每次违规你可能被罚 $200 到 $1,000，所以开车前要把车清理干净。","p":"对。$200 到 $1,000，所以要先把所有的雪和冰清掉。"},"vi":{"q":"Ở Pennsylvania, tuyết hoặc băng bay ra từ xe đang chạy của bạn và đập vào một xe khác, gây thương tích nghiêm trọng. Bạn có thể bị phạt bao nhiêu?","o":["Không bị phạt, vì đó là tai nạn","Tối đa $50","Từ $200 đến $1,000","Đúng $25"],"h1":"Tiền phạt có thể lên đến bốn chữ số.","h2":"Ở Pennsylvania, nếu tuyết hoặc băng từ xe đang chạy của bạn đập vào một xe hoặc một người và gây tử vong hoặc thương tích nghiêm trọng, bạn có thể bị phạt từ $200 đến $1,000 cho mỗi vi phạm, vì vậy hãy dọn sạch xe trước khi lái.","p":"Đúng. Từ $200 đến $1,000, vì vậy hãy dọn hết tuyết và băng trước."},"tl":{"q":"Sa Pennsylvania, may niyebe o yelong lumipad mula sa umaandar mong kotse at tumama sa ibang sasakyan, at may malubhang nasaktan. Anong multa ang puwede mong harapin?","o":["Walang multa, dahil aksidente iyon","Hanggang $50","$200 hanggang $1,000","Eksaktong $25"],"h1":"Puwedeng umabot sa apat na digit ang multa.","h2":"Sa Pennsylvania, kung ang niyebe o yelo mula sa umaandar mong sasakyan ay tumama sa sasakyan o tao at nagdulot ng kamatayan o malubhang pinsala, puwede kang multahan ng $200 hanggang $1,000 sa bawat paglabag, kaya linisin ang kotse mo bago magmaneho.","p":"Tama. $200 hanggang $1,000, kaya alisin muna ang lahat ng niyebe at yelo."},"ar":{"q":"في Pennsylvania، طار ثلج أو جليد من سيارتك وهي تسير وأصاب مركبة أخرى، وسبّب إصابة خطيرة. ما الغرامة التي قد تواجهها؟","o":["لا غرامة، لأنه كان حادثًا","حتى $50","من $200 إلى $1,000","$25 بالضبط"],"h1":"قد تصل الغرامة إلى أربعة أرقام.","h2":"في Pennsylvania، إذا أصاب ثلج أو جليد من مركبتك وهي تسير مركبةً أو شخصًا وسبّب وفاة أو إصابة خطيرة، فقد تواجه غرامة من $200 إلى $1,000 عن كل مخالفة، لذلك نظّف سيارتك قبل أن تقود.","p":"صحيح. من $200 إلى $1,000، لذلك أزل كل الثلج والجليد أولًا."},"ref":{"doc":"PA","page":41}},{"id":"pa-043","scope":"PA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Pennsylvania, a person is riding in the open bed of a pickup truck. What is the fastest the truck may go?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"It is 10 mph faster than a typical neighborhood street limit.","h2":"In Pennsylvania, an open-bed pickup or flatbed truck may not go faster than 35 mph when anyone is riding in the bed, and children under 18 generally may not ride there at all.","p":"Right. No more than 35 mph with someone in the bed."},"es":{"q":"En Pensilvania, una persona va en la caja abierta de una camioneta pickup. ¿Cuál es la velocidad máxima de la camioneta?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Es 10 mph más que el límite típico de una calle de barrio.","h2":"En Pensilvania, una camioneta pickup o de plataforma abierta no puede ir a más de 35 mph cuando alguien va en la caja, y en general los menores de 18 años no pueden ir ahí.","p":"Correcto. No más de 35 mph con alguien en la caja."},"zh":{"q":"在 Pennsylvania，有人坐在皮卡车敞开的车斗里。这辆车最快可以开多快？","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"比一般住宅区街道的限速快 10 mph。","h2":"在 Pennsylvania，有人坐在车斗里时，敞开车斗的皮卡车或平板车不能开得比 35 mph 快，而且未满 18 岁的孩子一般完全不能坐在那里。","p":"对。车斗里有人时，不能超过 35 mph。"},"vi":{"q":"Ở Pennsylvania, có một người đang ngồi trong thùng xe mở của một xe bán tải. Xe đó được chạy nhanh nhất là bao nhiêu?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Nhanh hơn 10 mph so với giới hạn thường gặp trên đường trong khu dân cư.","h2":"Ở Pennsylvania, xe bán tải thùng mở hoặc xe sàn phẳng không được chạy nhanh hơn 35 mph khi có người ngồi trong thùng, và trẻ em dưới 18 tuổi nói chung hoàn toàn không được ngồi ở đó.","p":"Đúng. Không quá 35 mph khi có người ngồi trong thùng xe."},"tl":{"q":"Sa Pennsylvania, may taong nakasakay sa bukas na likod (bed) ng pickup truck. Ano ang pinakamabilis na puwedeng takbo ng truck?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Mas mabilis ito nang 10 mph kaysa sa karaniwang limit sa kalye ng isang neighborhood.","h2":"Sa Pennsylvania, ang open-bed pickup o flatbed truck ay hindi puwedeng tumakbo nang mas mabilis sa 35 mph kapag may nakasakay sa bed, at karaniwang hindi puwedeng sumakay doon ang mga batang wala pang 18.","p":"Tama. Hindi lalampas sa 35 mph kapag may tao sa bed."},"ar":{"q":"في Pennsylvania، شخص يركب في الصندوق المكشوف لشاحنة بيك أب. ما أقصى سرعة يجوز أن تسير بها الشاحنة؟","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"هي أسرع بـ 10 mph من حد السرعة المعتاد في شارع سكني.","h2":"في Pennsylvania، لا يجوز لشاحنة بيك أب ذات صندوق مكشوف أو شاحنة مسطحة أن تسير أسرع من 35 mph عندما يركب أي شخص في الصندوق، وفي العادة لا يجوز للأطفال الذين أعمارهم أقل من 18 سنة الركوب هناك أبدًا.","p":"صحيح. ليس أكثر من 35 mph عندما يكون شخص في الصندوق."},"ref":{"doc":"PA","page":59}},{"id":"pa-044","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, how many points go on your driving record if you are convicted of breaking the Move Over law?","o":["Two points","No points","Five points","Six points"],"h1":"It is fewer points than failing to stop for a school bus.","h2":"In Pennsylvania, a conviction for breaking the Move Over law puts 2 points on your driving record, along with a fine.","p":"Right. Two points, plus a fine."},"es":{"q":"En Pensilvania, ¿cuántos puntos se agregan a su historial de manejo si lo condenan por no cumplir la ley Move Over?","o":["Dos puntos","Ningún punto","Cinco puntos","Seis puntos"],"h1":"Son menos puntos que por no detenerse por un autobús escolar.","h2":"En Pensilvania, una condena por no cumplir la ley Move Over agrega 2 puntos a su historial de manejo, además de una multa.","p":"Correcto. Dos puntos, más una multa."},"zh":{"q":"在 Pennsylvania，如果你因违反让道法（Move Over law）被定罪，驾驶记录会加几分？","o":["两分","不加分","五分","六分"],"h1":"分数比没有为校车停车要少。","h2":"在 Pennsylvania，因违反让道法（Move Over law）被定罪，你的驾驶记录会加 2 分，还要罚款。","p":"对。加两分，还要罚款。"},"vi":{"q":"Ở Pennsylvania, nếu bạn bị kết tội vi phạm Luật Nhường Làn (Move Over law), hồ sơ lái xe của bạn bị ghi bao nhiêu điểm?","o":["Hai điểm","Không điểm nào","Năm điểm","Sáu điểm"],"h1":"Số điểm ít hơn so với không dừng lại vì xe buýt trường học.","h2":"Ở Pennsylvania, bị kết tội vi phạm Luật Nhường Làn (Move Over law) sẽ bị ghi 2 điểm vào hồ sơ lái xe, cùng với tiền phạt.","p":"Đúng. Hai điểm, cộng thêm tiền phạt."},"tl":{"q":"Sa Pennsylvania, ilang puntos ang mapupunta sa driving record mo kung nahatulan ka sa paglabag sa Move Over law?","o":["Dalawang puntos","Walang puntos","Limang puntos","Anim na puntos"],"h1":"Mas kaunti ito kaysa sa puntos sa hindi paghinto para sa school bus.","h2":"Sa Pennsylvania, ang pagkahatol sa paglabag sa Move Over law ay naglalagay ng 2 puntos sa iyong driving record, kasama ang multa.","p":"Tama. Dalawang puntos, dagdag ang multa."},"ar":{"q":"في Pennsylvania، كم نقطة تُضاف إلى سجل قيادتك إذا أُدنت بمخالفة قانون إفساح الطريق (Move Over law)؟","o":["نقطتان","لا نقاط","خمس نقاط","ست نقاط"],"h1":"هي نقاط أقل من نقاط عدم التوقف لحافلة مدرسية.","h2":"في Pennsylvania، الإدانة بمخالفة قانون إفساح الطريق (Move Over law) تضيف 2 نقطة إلى سجل قيادتك، مع غرامة.","p":"صحيح. نقطتان، مع غرامة."},"ref":{"doc":"PA","page":59}},{"id":"pa-045","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, PennDOT finds your car had no insurance for 31 days or more. What happens to the registration?","o":["Nothing, if you buy insurance now","It is suspended for three months","It is suspended for one week","It is canceled forever"],"h1":"It lasts one season of the year.","h2":"In Pennsylvania, if your vehicle had no insurance for 31 days or more, its registration is suspended for three months, and your license too if you drove it or let someone drive it.","p":"Right. Three months without registration."},"es":{"q":"En Pensilvania, PennDOT descubre que su carro no tuvo seguro por 31 días o más. ¿Qué pasa con el registro?","o":["Nada, si compra el seguro ahora","Se suspende por tres meses","Se suspende por una semana","Se cancela para siempre"],"h1":"Dura una estación del año.","h2":"En Pensilvania, si su vehículo no tuvo seguro por 31 días o más, el registro se suspende por tres meses, y también su licencia si usted lo manejó o dejó que otra persona lo manejara.","p":"Correcto. Tres meses sin registro."},"zh":{"q":"在 Pennsylvania，PennDOT 发现你的车有 31 天或以上没有保险。车辆登记会怎样？","o":["如果你现在买保险，就没事","会被暂停三个月","会被暂停一个星期","会被永久取消"],"h1":"它持续一年中的一个季节。","h2":"在 Pennsylvania，如果你的车有 31 天或以上没有保险，车辆登记会被暂停三个月；如果你开了这辆车或让别人开，你的驾照也会被暂停。","p":"对。三个月没有车辆登记。"},"vi":{"q":"Ở Pennsylvania, PennDOT phát hiện xe của bạn không có bảo hiểm trong 31 ngày trở lên. Chuyện gì xảy ra với giấy đăng ký xe?","o":["Không sao, nếu bạn mua bảo hiểm bây giờ","Bị đình chỉ ba tháng","Bị đình chỉ một tuần","Bị hủy vĩnh viễn"],"h1":"Kéo dài một mùa trong năm.","h2":"Ở Pennsylvania, nếu xe của bạn không có bảo hiểm trong 31 ngày trở lên, giấy đăng ký xe bị đình chỉ ba tháng, và bằng lái của bạn cũng bị treo nếu bạn đã lái xe đó hoặc cho người khác lái.","p":"Đúng. Ba tháng không có đăng ký xe."},"tl":{"q":"Sa Pennsylvania, natuklasan ng PennDOT na walang insurance ang kotse mo nang 31 araw o higit pa. Ano ang mangyayari sa registration?","o":["Wala, kung bibili ka na ng insurance ngayon","Masususpinde ito nang tatlong buwan","Masususpinde ito nang isang linggo","Kakanselahin ito habambuhay"],"h1":"Tumatagal ito nang isang season ng taon.","h2":"Sa Pennsylvania, kung walang insurance ang sasakyan mo nang 31 araw o higit pa, masususpinde ang registration nito nang tatlong buwan, at pati ang lisensya mo kung minaneho mo ito o pinamaneho mo sa iba.","p":"Tama. Tatlong buwan na walang registration."},"ar":{"q":"في Pennsylvania، اكتشفت PennDOT أن سيارتك كانت بلا تأمين لمدة 31 يومًا أو أكثر. ماذا يحدث لتسجيل السيارة؟","o":["لا شيء، إذا اشتريت التأمين الآن","يُعلَّق لمدة ثلاثة أشهر","يُعلَّق لمدة أسبوع","يُلغى إلى الأبد"],"h1":"يستمر فصلًا واحدًا من فصول السنة.","h2":"في Pennsylvania، إذا كانت مركبتك بلا تأمين لمدة 31 يومًا أو أكثر، يُعلَّق تسجيلها لمدة ثلاثة أشهر، وتُعلَّق رخصتك أيضًا إذا قدتها أو سمحت لشخص آخر بقيادتها.","p":"صحيح. ثلاثة أشهر بلا تسجيل."},"ref":{"doc":"PA","page":80}},{"id":"pa-046","scope":"PA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Pennsylvania, what happens to your license if you do not obey a railroad crossing gate?","o":["A one-year suspension","Only a warning","A 30-day suspension","Your license is revoked forever"],"h1":"It is about one month.","h2":"In Pennsylvania, failing to obey a railroad crossing gate or barrier brings a 30-day license suspension.","p":"Right. A 30-day suspension."},"es":{"q":"En Pensilvania, ¿qué pasa con su licencia si no respeta la barrera de un cruce de ferrocarril?","o":["Una suspensión de un año","Solo una advertencia","Una suspensión de 30 días","Le revocan la licencia para siempre"],"h1":"Es más o menos un mes.","h2":"En Pensilvania, no respetar la barrera o la reja de un cruce de ferrocarril lleva a una suspensión de la licencia por 30 días.","p":"Correcto. Una suspensión de 30 días."},"zh":{"q":"在 Pennsylvania，如果你不遵守铁路道口的栏杆，你的驾照会怎样？","o":["暂停一年","只会得到警告","暂停 30 天","驾照被永久吊销"],"h1":"大约是一个月。","h2":"在 Pennsylvania，不遵守铁路道口的栏杆或障碍物，驾照会被暂停 30 天。","p":"对。暂停 30 天。"},"vi":{"q":"Ở Pennsylvania, chuyện gì xảy ra với bằng lái của bạn nếu bạn không tuân theo thanh chắn tại chỗ giao nhau với đường sắt?","o":["Bị treo một năm","Chỉ bị cảnh cáo","Bị treo 30 ngày","Bị thu hồi bằng lái vĩnh viễn"],"h1":"Khoảng một tháng.","h2":"Ở Pennsylvania, không tuân theo thanh chắn hoặc rào chắn tại chỗ giao nhau với đường sắt sẽ bị treo bằng lái 30 ngày.","p":"Đúng. Bị treo 30 ngày."},"tl":{"q":"Sa Pennsylvania, ano ang mangyayari sa lisensya mo kung hindi mo susundin ang gate ng railroad crossing?","o":["Isang taong suspensyon","Babala lang","30 araw na suspensyon","Babawiin ang lisensya mo habambuhay"],"h1":"Mga isang buwan ito.","h2":"Sa Pennsylvania, ang hindi pagsunod sa gate o harang ng railroad crossing ay may 30 araw na suspensyon ng lisensya.","p":"Tama. 30 araw na suspensyon."},"ar":{"q":"في Pennsylvania، ماذا يحدث لرخصتك إذا لم تلتزم بحاجز معبر السكة الحديدية؟","o":["تعليق لمدة سنة","تحذير فقط","تعليق لمدة 30 يومًا","تُسحب رخصتك إلى الأبد"],"h1":"هي شهر تقريبًا.","h2":"في Pennsylvania، عدم الالتزام بحاجز أو بوابة معبر السكة الحديدية يؤدي إلى تعليق الرخصة لمدة 30 يومًا.","p":"صحيح. تعليق لمدة 30 يومًا."},"ref":{"doc":"PA","page":79}},{"id":"pa-047","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, a driver refuses a chemical test for the first time. Besides the suspension, what restoration fee must they pay?","o":["$50","$100","$2,000","$500"],"h1":"The fee doubles for a second refusal.","h2":"In Pennsylvania, a driver who refuses a chemical test pays a refusal restoration fee of $500 the first time, $1,000 the second time and $2,000 after that.","p":"Right. $500 for a first refusal."},"es":{"q":"En Pensilvania, un conductor se niega por primera vez a una prueba química. Además de la suspensión, ¿qué cargo de restablecimiento debe pagar?","o":["$50","$100","$2,000","$500"],"h1":"El cargo se duplica con una segunda negativa.","h2":"En Pensilvania, un conductor que se niega a una prueba química paga un cargo de restablecimiento de $500 la primera vez, $1,000 la segunda y $2,000 después.","p":"Correcto. $500 por la primera negativa."},"zh":{"q":"在 Pennsylvania，一个司机第一次拒绝化学检测。除了驾照被暂停，他还必须交多少恢复费？","o":["$50","$100","$2,000","$500"],"h1":"第二次拒绝时，费用会翻倍。","h2":"在 Pennsylvania，拒绝化学检测的司机要交拒绝检测恢复费：第一次 $500，第二次 $1,000，之后每次 $2,000。","p":"对。第一次拒绝要交 $500。"},"vi":{"q":"Ở Pennsylvania, một tài xế từ chối kiểm tra hóa học lần đầu tiên. Ngoài việc bị treo bằng, người đó phải trả phí phục hồi bao nhiêu?","o":["$50","$100","$2,000","$500"],"h1":"Phí tăng gấp đôi khi từ chối lần thứ hai.","h2":"Ở Pennsylvania, tài xế từ chối kiểm tra hóa học phải trả phí phục hồi do từ chối là $500 lần đầu, $1,000 lần thứ hai và $2,000 cho những lần sau đó.","p":"Đúng. $500 cho lần từ chối đầu tiên."},"tl":{"q":"Sa Pennsylvania, tumanggi ang isang driver sa chemical test sa unang beses. Bukod sa suspensyon, anong restoration fee ang dapat niyang bayaran?","o":["$50","$100","$2,000","$500"],"h1":"Dumodoble ang fee sa ikalawang pagtanggi.","h2":"Sa Pennsylvania, ang driver na tumanggi sa chemical test ay magbabayad ng refusal restoration fee na $500 sa unang beses, $1,000 sa ikalawang beses at $2,000 pagkatapos noon.","p":"Tama. $500 sa unang pagtanggi."},"ar":{"q":"في Pennsylvania، سائق رفض الفحص الكيميائي لأول مرة. بالإضافة إلى التعليق، ما رسوم استعادة الرخصة التي يجب أن يدفعها؟","o":["$50","$100","$2,000","$500"],"h1":"تتضاعف الرسوم عند الرفض الثاني.","h2":"في Pennsylvania، السائق الذي يرفض الفحص الكيميائي يدفع رسوم استعادة بسبب الرفض قدرها $500 في المرة الأولى، و$1,000 في المرة الثانية، و$2,000 بعد ذلك.","p":"صحيح. $500 عند الرفض الأول."},"ref":{"doc":"PA","page":82}},{"id":"pa-048","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, you change your name or address. How soon must you tell PennDOT?","o":["Within 15 days","Within 60 days","Within 6 months","Only when you renew your license"],"h1":"It is about two weeks.","h2":"In Pennsylvania, you must tell PennDOT about a change of name or address within 15 days, even if you move out of state.","p":"Right. Tell PennDOT within 15 days."},"es":{"q":"En Pensilvania, usted cambia de nombre o de dirección. ¿En qué plazo debe avisar a PennDOT?","o":["En 15 días","En 60 días","En 6 meses","Solo cuando renueve su licencia"],"h1":"Son unas dos semanas.","h2":"En Pensilvania, usted debe avisar a PennDOT de un cambio de nombre o de dirección en 15 días, aunque se mude a otro estado.","p":"Correcto. Avise a PennDOT en 15 días."},"zh":{"q":"在 Pennsylvania，你改了名字或地址。你必须在多长时间内通知 PennDOT？","o":["15 天内","60 天内","6 个月内","只在更新驾照时"],"h1":"大约是两个星期。","h2":"在 Pennsylvania，你改了名字或地址，必须在 15 天内通知 PennDOT，即使你搬到别的州也一样。","p":"对。15 天内通知 PennDOT。"},"vi":{"q":"Ở Pennsylvania, bạn đổi tên hoặc đổi địa chỉ. Bạn phải báo cho PennDOT trong thời hạn bao lâu?","o":["Trong vòng 15 ngày","Trong vòng 60 ngày","Trong vòng 6 tháng","Chỉ khi bạn gia hạn bằng lái"],"h1":"Khoảng hai tuần.","h2":"Ở Pennsylvania, bạn phải báo cho PennDOT về việc đổi tên hoặc đổi địa chỉ trong vòng 15 ngày, kể cả khi bạn chuyển ra khỏi tiểu bang.","p":"Đúng. Báo cho PennDOT trong vòng 15 ngày."},"tl":{"q":"Sa Pennsylvania, nagpalit ka ng pangalan o address. Gaano kabilis mo dapat sabihan ang PennDOT?","o":["Sa loob ng 15 araw","Sa loob ng 60 araw","Sa loob ng 6 na buwan","Kapag nire-renew mo lang ang lisensya mo"],"h1":"Mga dalawang linggo ito.","h2":"Sa Pennsylvania, dapat mong sabihan ang PennDOT tungkol sa pagpapalit ng pangalan o address sa loob ng 15 araw, kahit lumipat ka sa labas ng estado.","p":"Tama. Sabihan ang PennDOT sa loob ng 15 araw."},"ar":{"q":"في Pennsylvania، غيّرت اسمك أو عنوانك. خلال كم من الوقت يجب أن تُبلغ PennDOT؟","o":["خلال 15 يومًا","خلال 60 يومًا","خلال 6 أشهر","فقط عندما تجدّد رخصتك"],"h1":"هي أسبوعان تقريبًا.","h2":"في Pennsylvania يجب أن تُبلغ PennDOT بتغيير الاسم أو العنوان خلال 15 يومًا، حتى لو انتقلت إلى خارج الولاية.","p":"صحيح. أبلغ PennDOT خلال 15 يومًا."},"ref":{"doc":"PA","page":89}},{"id":"pa-049","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, a 12-year-old rides in the back seat. Must the child wear a seat belt?","o":["No, seat belts are only for the front seat","Yes, passengers 8 to 17 must buckle up in any seat","Only on highways","Only if the driver is under 18"],"h1":"For passengers under 18, the seat does not matter.","h2":"In Pennsylvania, passengers age 8 or older but under 18 must wear a seat belt no matter where they sit in the vehicle.","p":"Right. Ages 8 to 17 buckle up in every seat."},"es":{"q":"En Pensilvania, un niño de 12 años va en el asiento trasero. ¿Debe usar el cinturón de seguridad?","o":["No, el cinturón es solo para el asiento delantero","Sí, los pasajeros de 8 a 17 años deben abrocharse en cualquier asiento","Solo en las autopistas","Solo si el conductor es menor de 18 años"],"h1":"Para los pasajeros menores de 18 años, el asiento no importa.","h2":"En Pensilvania, los pasajeros de 8 años o más pero menores de 18 deben usar el cinturón de seguridad sin importar dónde vayan sentados en el vehículo.","p":"Correcto. De 8 a 17 años se abrochan en todos los asientos."},"zh":{"q":"在 Pennsylvania，一个 12 岁的孩子坐在后排。孩子必须系安全带吗？","o":["不用，安全带只是给前排的","要，8 到 17 岁的乘客坐在任何座位都必须系安全带","只在高速公路上要","只在司机未满 18 岁时要"],"h1":"对未满 18 岁的乘客来说，坐哪个座位都一样。","h2":"在 Pennsylvania，8 岁或以上、未满 18 岁的乘客，不管坐在车里哪个位置，都必须系安全带。","p":"对。8 到 17 岁的乘客坐在每个座位都要系安全带。"},"vi":{"q":"Ở Pennsylvania, một em 12 tuổi ngồi ở ghế sau. Em đó có phải thắt dây an toàn không?","o":["Không, dây an toàn chỉ dành cho ghế trước","Có, hành khách từ 8 đến 17 tuổi phải thắt dây an toàn ở mọi ghế","Chỉ khi đi trên xa lộ","Chỉ khi tài xế dưới 18 tuổi"],"h1":"Với hành khách dưới 18 tuổi, ngồi ghế nào cũng vậy.","h2":"Ở Pennsylvania, hành khách từ 8 tuổi trở lên nhưng dưới 18 tuổi phải thắt dây an toàn dù ngồi ở bất kỳ chỗ nào trong xe.","p":"Đúng. Từ 8 đến 17 tuổi phải thắt dây an toàn ở mọi ghế."},"tl":{"q":"Sa Pennsylvania, nakaupo sa likod na upuan ang isang batang 12 taong gulang. Kailangan bang mag-seat belt ang bata?","o":["Hindi, para lang sa harapang upuan ang seat belt","Oo, ang mga pasaherong 8 hanggang 17 ay dapat mag-seat belt sa kahit anong upuan","Sa highway lang","Kung wala pang 18 ang driver lang"],"h1":"Para sa mga pasaherong wala pang 18, hindi mahalaga kung saang upuan.","h2":"Sa Pennsylvania, ang mga pasaherong 8 taong gulang o higit pa pero wala pang 18 ay dapat mag-seat belt kahit saan sila nakaupo sa sasakyan.","p":"Tama. Ang edad 8 hanggang 17 ay nagse-seat belt sa bawat upuan."},"ar":{"q":"في Pennsylvania، طفل عمره 12 سنة يجلس في المقعد الخلفي. هل يجب أن يضع حزام الأمان؟","o":["لا، حزام الأمان للمقعد الأمامي فقط","نعم، يجب على الركاب من 8 إلى 17 سنة وضع الحزام في أي مقعد","على الطرق السريعة فقط","فقط إذا كان عمر السائق أقل من 18 سنة"],"h1":"بالنسبة للركاب الذين أعمارهم أقل من 18 سنة، لا يهم المقعد.","h2":"في Pennsylvania، يجب على الركاب الذين أعمارهم 8 سنوات أو أكثر وأقل من 18 سنة أن يضعوا حزام الأمان أينما جلسوا في المركبة.","p":"صحيح. من 8 إلى 17 سنة يضعون الحزام في كل مقعد."},"ref":{"doc":"PA","page":89}},{"id":"pa-050","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, how often must your vehicle pass a safety inspection?","o":["Every 6 months","Every 2 years","Every 12 months","Only when you buy it"],"h1":"The sticker on your windshield shows when it is due again.","h2":"In Pennsylvania, your vehicle must have a safety inspection at an authorized station every 12 months, and it may be done up to 90 days early.","p":"Right. A safety inspection every 12 months."},"es":{"q":"En Pensilvania, ¿cada cuánto debe pasar su vehículo una inspección de seguridad?","o":["Cada 6 meses","Cada 2 años","Cada 12 meses","Solo cuando lo compra"],"h1":"La calcomanía del parabrisas muestra cuándo le toca otra vez.","h2":"En Pensilvania, su vehículo debe pasar una inspección de seguridad en una estación autorizada cada 12 meses, y puede hacerse hasta 90 días antes.","p":"Correcto. Una inspección de seguridad cada 12 meses."},"zh":{"q":"在 Pennsylvania，你的车多久必须通过一次安全检查？","o":["每 6 个月","每 2 年","每 12 个月","只在买车时"],"h1":"挡风玻璃上的贴纸会显示下次什么时候要检查。","h2":"在 Pennsylvania，你的车每 12 个月必须在授权的检查站做一次安全检查，最多可以提前 90 天做。","p":"对。每 12 个月做一次安全检查。"},"vi":{"q":"Ở Pennsylvania, xe của bạn phải qua kiểm tra an toàn bao lâu một lần?","o":["Mỗi 6 tháng","Mỗi 2 năm","Mỗi 12 tháng","Chỉ khi bạn mua xe"],"h1":"Nhãn dán trên kính chắn gió cho biết khi nào đến hạn kiểm tra lại.","h2":"Ở Pennsylvania, xe của bạn phải được kiểm tra an toàn tại một trạm được cấp phép mỗi 12 tháng, và có thể kiểm tra sớm đến 90 ngày.","p":"Đúng. Kiểm tra an toàn mỗi 12 tháng."},"tl":{"q":"Sa Pennsylvania, gaano kadalas dapat pumasa ang sasakyan mo sa safety inspection?","o":["Bawat 6 na buwan","Bawat 2 taon","Bawat 12 buwan","Kapag binili mo lang ito"],"h1":"Ipinapakita ng sticker sa windshield mo kung kailan ulit ito kailangan.","h2":"Sa Pennsylvania, dapat may safety inspection ang sasakyan mo sa isang awtorisadong istasyon bawat 12 buwan, at puwede itong gawin hanggang 90 araw nang mas maaga.","p":"Tama. Safety inspection bawat 12 buwan."},"ar":{"q":"في Pennsylvania، كل كم من الوقت يجب أن تجتاز مركبتك فحص السلامة؟","o":["كل 6 أشهر","كل 2 سنة","كل 12 شهرًا","فقط عندما تشتريها"],"h1":"الملصق على الزجاج الأمامي يبيّن متى يحين موعده مرة أخرى.","h2":"في Pennsylvania، يجب أن تخضع مركبتك لفحص السلامة في محطة معتمدة كل 12 شهرًا، ويمكن إجراؤه قبل موعده بما يصل إلى 90 يومًا.","p":"صحيح. فحص سلامة كل 12 شهرًا."},"ref":{"doc":"PA","page":92}},{"id":"pa-051","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, your health care provider fills out the medical part of the learner's permit application (DL-180). What is the earliest this exam may be done?","o":["Six months before your 16th birthday","One year before your 16th birthday","On your 16th birthday, not before","Any time after your 14th birthday"],"h1":"It can be done a little before you turn 16, but not more than half a year early.","h2":"In Pennsylvania, the physical exam on the DL-180 may be done no earlier than six months before your 16th birthday.","p":"Right. No earlier than six months before you turn 16."},"es":{"q":"En Pensilvania, su proveedor de salud llena la parte médica de la solicitud del permiso de aprendizaje (DL-180). ¿Qué tan pronto se puede hacer este examen?","o":["Seis meses antes de cumplir 16 años","Un año antes de cumplir 16 años","El día que cumple 16 años, no antes","En cualquier momento después de cumplir 14 años"],"h1":"Se puede hacer un poco antes de cumplir 16, pero no más de medio año antes.","h2":"En Pensilvania, el examen físico de la DL-180 se puede hacer como máximo seis meses antes de cumplir 16 años.","p":"Correcto. No antes de seis meses antes de cumplir 16."},"ref":{"doc":"PA","page":1}},{"id":"pa-052","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, you fail the knowledge test for your learner's permit. When may you take it again?","o":["Later the same day","The next business day","After 7 days","After 30 days"],"h1":"You may take this test only once a day.","h2":"In Pennsylvania, if you fail the knowledge test, you may take it again on the next business day.","p":"Right. You can try again the next business day."},"es":{"q":"En Pensilvania, usted no aprueba el examen de conocimientos para el permiso de aprendizaje. ¿Cuándo puede tomarlo otra vez?","o":["Más tarde el mismo día","El siguiente día hábil","Después de 7 días","Después de 30 días"],"h1":"Solo puede tomar este examen una vez al día.","h2":"En Pensilvania, si no aprueba el examen de conocimientos, puede tomarlo otra vez el siguiente día hábil.","p":"Correcto. Puede intentarlo otra vez el siguiente día hábil."},"ref":{"doc":"PA","page":5}},{"id":"pa-053","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, you have a junior driver's license. What happens to it when you turn 18?","o":["It expires, and you must take the road test again","It stays a junior license until you renew it","It becomes a regular driver's license by itself","You must take the knowledge test again"],"h1":"You do not need to do anything at that birthday.","h2":"In Pennsylvania, a junior driver's license automatically becomes a regular driver's license when you turn 18.","p":"Right. At 18, it becomes a regular license automatically."},"es":{"q":"En Pensilvania, usted tiene una licencia de conducir junior. ¿Qué pasa con ella cuando cumple 18 años?","o":["Vence, y debe tomar otra vez el examen de manejo","Sigue siendo junior hasta que la renueve","Se convierte sola en una licencia regular","Debe tomar otra vez el examen de conocimientos"],"h1":"No necesita hacer nada en ese cumpleaños.","h2":"En Pensilvania, una licencia junior se convierte automáticamente en una licencia regular cuando usted cumple 18 años.","p":"Correcto. A los 18 se convierte en licencia regular automáticamente."},"ref":{"doc":"PA","page":4}},{"id":"pa-054","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, a visitor has a valid driver's license from their home country. How long may they drive here with it?","o":["Only 30 days","Up to five years","They may never drive with it","Up to one year from entering the U.S., or until it expires, whichever comes first"],"h1":"The limit is counted from the day they entered the United States.","h2":"In Pennsylvania, a person with a valid foreign driver's license may drive for up to one year from entering the United States, or until the license expires, whichever comes first.","p":"Right. Up to one year from entry, or until the license expires."},"es":{"q":"En Pensilvania, un visitante tiene una licencia válida de su país. ¿Por cuánto tiempo puede manejar aquí con ella?","o":["Solo 30 días","Hasta cinco años","Nunca puede manejar con ella","Hasta un año desde que entró a EE. UU., o hasta que venza, lo que ocurra primero"],"h1":"El plazo se cuenta desde el día en que entró a Estados Unidos.","h2":"En Pensilvania, una persona con una licencia extranjera válida puede manejar hasta un año desde que entró a Estados Unidos, o hasta que venza la licencia, lo que ocurra primero.","p":"Correcto. Hasta un año desde la entrada, o hasta que venza la licencia."},"ref":{"doc":"PA","page":3}},{"id":"pa-055","scope":"PA","cat":"signals","sign":null,"c":0,"en":{"q":"In Pennsylvania, you are in the left lane of a one-way street at a red light. You want to turn left onto another one-way street. No sign forbids it. What may you do?","o":["Stop, yield to people and traffic, then turn left","Turn left without stopping","Wait for the green light; left on red is never allowed","Turn left only if a police officer waves you on"],"h1":"Pennsylvania allows a left turn on red in one special case: one-way onto one-way.","h2":"In Pennsylvania, you may turn left on a red light from a one-way street onto another one-way street, after you stop and yield to pedestrians and other traffic, unless a sign says not to.","p":"Right. Stop, yield, then you may turn left from one-way onto one-way."},"es":{"q":"En Pensilvania, usted está en el carril izquierdo de una calle de un solo sentido con la luz en rojo. Quiere girar a la izquierda hacia otra calle de un solo sentido. Ningún letrero lo prohíbe. ¿Qué puede hacer?","o":["Detenerse, ceder el paso a peatones y tráfico, y luego girar a la izquierda","Girar a la izquierda sin detenerse","Esperar la luz verde; girar a la izquierda en rojo nunca está permitido","Girar a la izquierda solo si un policía le hace señas"],"h1":"Pensilvania permite girar a la izquierda en rojo en un caso especial: de un solo sentido a un solo sentido.","h2":"En Pensilvania, puede girar a la izquierda con la luz roja de una calle de un solo sentido a otra calle de un solo sentido, después de detenerse y ceder el paso a peatones y otro tráfico, a menos que un letrero lo prohíba.","p":"Correcto. Deténgase, ceda el paso, y luego puede girar de un solo sentido a un solo sentido."},"ref":{"doc":"PA","page":7}},{"id":"pa-056","scope":"PA","cat":"signals","sign":null,"c":1,"en":{"q":"In Pennsylvania, you come to an intersection where the traffic light is not working at all. How should you treat it?","o":["Like a green light, if you are on the bigger road","Like a four-way stop","Like a flashing yellow light","Like a yield sign for you only"],"h1":"Every driver at the intersection has the same duty.","h2":"In Pennsylvania, a traffic signal that is not working should be treated as a four-way stop.","p":"Right. A dark signal means a four-way stop."},"es":{"q":"En Pensilvania, llega a una intersección donde el semáforo no funciona para nada. ¿Cómo debe tratarlo?","o":["Como una luz verde, si usted va por la calle más grande","Como un alto en las cuatro direcciones","Como una luz amarilla intermitente","Como un letrero de ceda el paso solo para usted"],"h1":"Todos los conductores en la intersección tienen la misma obligación.","h2":"En Pensilvania, un semáforo que no funciona se debe tratar como un alto en las cuatro direcciones.","p":"Correcto. Un semáforo apagado es un alto en las cuatro direcciones."},"ref":{"doc":"PA","page":8}},{"id":"pa-057","scope":"PA","cat":"signals","sign":null,"c":2,"en":{"q":"In Pennsylvania, a one-lane highway on-ramp has a ramp-metering signal. The light turns green. How many cars may enter the highway?","o":["Two cars","All the cars waiting","One car","As many as can go before it turns red"],"h1":"These lights let cars in one at a time.","h2":"In Pennsylvania, on a single-lane ramp with a ramp-metering signal, only one car may enter the highway each time the light turns green, and that driver must still find a safe gap.","p":"Right. One car for each green light."},"es":{"q":"En Pensilvania, una rampa de entrada de un carril tiene un semáforo regulador de rampa. La luz se pone verde. ¿Cuántos carros pueden entrar a la autopista?","o":["Dos carros","Todos los carros que esperan","Un carro","Todos los que puedan antes de que se ponga roja"],"h1":"Estas luces dejan entrar a los carros de uno en uno.","h2":"En Pensilvania, en una rampa de un carril con semáforo regulador, solo un carro puede entrar a la autopista cada vez que la luz se pone verde, y ese conductor aún debe buscar un espacio seguro.","p":"Correcto. Un carro por cada luz verde."},"ref":{"doc":"PA","page":8}},{"id":"pa-058","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you and another car reach a four-way stop at the same time. The other car is on your right. Who goes first?","o":["You, because you are on the left","The bigger vehicle","Whoever honks first","The car on your right"],"h1":"The driver on the left gives way.","h2":"In Pennsylvania, when two vehicles reach a four-way stop at the same time, the driver on the left yields to the driver on the right.","p":"Right. The driver on the left yields to the driver on the right."},"es":{"q":"En Pensilvania, usted y otro carro llegan al mismo tiempo a un alto de cuatro direcciones. El otro carro está a su derecha. ¿Quién pasa primero?","o":["Usted, porque está a la izquierda","El vehículo más grande","El que toque el claxon primero","El carro a su derecha"],"h1":"El conductor de la izquierda cede el paso.","h2":"En Pensilvania, cuando dos vehículos llegan al mismo tiempo a un alto de cuatro direcciones, el conductor de la izquierda cede el paso al de la derecha.","p":"Correcto. El de la izquierda cede el paso al de la derecha."},"ref":{"doc":"PA","page":10}},{"id":"pa-059","scope":"PA","cat":"signals","sign":null,"c":0,"en":{"q":"In Pennsylvania, highway exit numbers match the mile markers. How far is it from Exit 20 to Exit 95?","o":["About 75 miles","About 7.5 miles","About 115 miles","You cannot tell from the numbers"],"h1":"Subtract one exit number from the other.","h2":"In Pennsylvania, exit numbers match the mile markers, so the distance from Exit 20 to Exit 95 is about 75 miles.","p":"Right. 95 minus 20 is about 75 miles."},"es":{"q":"En Pensilvania, los números de salida de las autopistas coinciden con los marcadores de millas. ¿Qué distancia hay de la Salida 20 a la Salida 95?","o":["Unas 75 millas","Unas 7.5 millas","Unas 115 millas","No se puede saber por los números"],"h1":"Reste un número de salida del otro.","h2":"En Pensilvania, los números de salida coinciden con los marcadores de millas, así que de la Salida 20 a la Salida 95 hay unas 75 millas.","p":"Correcto. 95 menos 20 son unas 75 millas."},"ref":{"doc":"PA","page":19}},{"id":"pa-060","scope":"PA","cat":"signals","sign":null,"c":1,"en":{"q":"In Pennsylvania, you see a route sign shaped like a keystone with a number on it. What kind of road is it?","o":["An Interstate highway","A Pennsylvania Traffic Route","A U.S. Traffic Route","A private toll road"],"h1":"Pennsylvania is called the Keystone State.","h2":"In Pennsylvania, a keystone-shaped route marker shows that the road is a Pennsylvania Traffic Route.","p":"Right. The keystone marks a Pennsylvania Traffic Route."},"es":{"q":"En Pensilvania, ve un letrero de ruta con forma de piedra clave (keystone) y un número. ¿Qué tipo de carretera es?","o":["Una autopista interestatal","Una ruta estatal de Pensilvania","Una ruta federal de EE. UU.","Una carretera privada de peaje"],"h1":"A Pensilvania la llaman el Estado de la Piedra Clave (Keystone State).","h2":"En Pensilvania, un marcador de ruta con forma de piedra clave indica que la carretera es una ruta estatal de Pensilvania.","p":"Correcto. La piedra clave marca una ruta estatal de Pensilvania."},"ref":{"doc":"PA","page":21}},{"id":"pa-061","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, may you hang a parking permit or air freshener from your rearview mirror while you drive?","o":["Yes, if it is small","Yes, on roads under 35 mph","No, nothing may hang there while the car is moving","Yes, if it is a parking permit"],"h1":"Tags and permits may hang there only when the car is parked.","h2":"In Pennsylvania, it is against the law to have anything hanging from the rearview mirror while the vehicle is moving; tags and permits may be hung there only when you are parked.","p":"Right. Nothing may hang from the mirror while you drive."},"es":{"q":"En Pensilvania, ¿puede colgar un permiso de estacionamiento o un aromatizante del espejo retrovisor mientras maneja?","o":["Sí, si es pequeño","Sí, en calles de menos de 35 mph","No, nada puede colgar allí mientras el carro se mueve","Sí, si es un permiso de estacionamiento"],"h1":"Los permisos solo pueden colgar allí cuando el carro está estacionado.","h2":"En Pensilvania, es ilegal tener algo colgado del espejo retrovisor mientras el vehículo se mueve; los permisos solo se pueden colgar allí cuando está estacionado.","p":"Correcto. Nada puede colgar del espejo mientras maneja."},"ref":{"doc":"PA","page":31}},{"id":"pa-062","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, the manual compares being tired to drinking. Being awake for 24 hours in a row affects your driving about as much as what blood alcohol level?","o":["0.02 percent","0.05 percent","It has no effect like alcohol","0.10 percent"],"h1":"It is more than the 0.08 legal limit for adults.","h2":"In Pennsylvania, the manual says being awake for 24 hours in a row harms your driving as much as a blood alcohol level of 0.10 percent.","p":"Right. 24 hours awake is like a 0.10 blood alcohol level."},"es":{"q":"En Pensilvania, el manual compara el cansancio con el alcohol. Estar despierto 24 horas seguidas afecta su manejo tanto como ¿qué nivel de alcohol en la sangre?","o":["0.02 por ciento","0.05 por ciento","No tiene un efecto parecido al alcohol","0.10 por ciento"],"h1":"Es más que el límite legal de 0.08 para adultos.","h2":"En Pensilvania, el manual dice que estar despierto 24 horas seguidas afecta su manejo tanto como un nivel de alcohol en la sangre de 0.10 por ciento.","p":"Correcto. 24 horas despierto es como un nivel de alcohol de 0.10."},"ref":{"doc":"PA","page":33}},{"id":"pa-063","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, on a dry road, how many seconds of following distance does the manual tell you to keep behind the car ahead?","o":["At least 4 seconds","At least 1 second","At least 2 seconds","At least 10 seconds"],"h1":"Count from when the car ahead passes a pole until you reach it.","h2":"In Pennsylvania, the manual says to keep at least a 4-second following distance on dry pavement.","p":"Right. Keep at least 4 seconds behind the car ahead."},"es":{"q":"En Pensilvania, en una carretera seca, ¿cuántos segundos de distancia detrás del carro de adelante le dice el manual que mantenga?","o":["Por lo menos 4 segundos","Por lo menos 1 segundo","Por lo menos 2 segundos","Por lo menos 10 segundos"],"h1":"Cuente desde que el carro de adelante pasa un poste hasta que usted llega a él.","h2":"En Pensilvania, el manual dice que mantenga por lo menos 4 segundos de distancia en pavimento seco.","p":"Correcto. Mantenga por lo menos 4 segundos detrás del carro de adelante."},"ref":{"doc":"PA","page":35}},{"id":"pa-064","scope":"PA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Pennsylvania, what is the highest speed limit allowed in the state?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"It is higher than 65 but lower than 75.","h2":"In Pennsylvania, the maximum speed limit is 70 mph.","p":"Right. The top speed limit in Pennsylvania is 70 mph."},"es":{"q":"En Pensilvania, ¿cuál es el límite de velocidad más alto permitido en el estado?","o":["55 mph","70 mph","65 mph","80 mph"],"h1":"Es más de 65 pero menos de 75.","h2":"En Pensilvania, el límite de velocidad máximo es de 70 mph.","p":"Correcto. El límite más alto en Pensilvania es de 70 mph."},"ref":{"doc":"PA","page":39}},{"id":"pa-065","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, it is daytime, but heavy smoke means you cannot see people or vehicles 1,000 feet ahead. What does the law require?","o":["Turn on only your parking lights","Use your high beams","Turn on your headlights","Nothing, because it is daytime"],"h1":"Lights help you see and help others see you.","h2":"In Pennsylvania, you must use your headlights whenever you cannot see pedestrians or vehicles 1,000 feet ahead, even in the daytime.","p":"Right. If you cannot see 1,000 feet ahead, turn on your headlights."},"es":{"q":"En Pensilvania, es de día, pero por el humo espeso no puede ver personas ni vehículos a 1,000 pies de distancia. ¿Qué exige la ley?","o":["Encender solo las luces de estacionamiento","Usar las luces altas","Encender los faros delanteros","Nada, porque es de día"],"h1":"Las luces le ayudan a ver y a que otros lo vean.","h2":"En Pensilvania, debe usar los faros delanteros siempre que no pueda ver peatones o vehículos a 1,000 pies de distancia, aunque sea de día.","p":"Correcto. Si no puede ver a 1,000 pies, encienda los faros."},"ref":{"doc":"PA","page":40}},{"id":"pa-066","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are driving at night with high beams behind another car going the same way. Within what distance must you switch to low beams?","o":["100 feet","500 feet","1,000 feet","300 feet"],"h1":"This distance is shorter than the one for oncoming cars.","h2":"In Pennsylvania, you must use low beams when you are following another vehicle within 300 feet.","p":"Right. Use low beams within 300 feet of the car ahead."},"es":{"q":"En Pensilvania, maneja de noche con las luces altas detrás de otro carro que va en su misma dirección. ¿A qué distancia debe cambiar a luces bajas?","o":["100 pies","500 pies","1,000 pies","300 pies"],"h1":"Esta distancia es más corta que la de los carros que vienen de frente.","h2":"En Pensilvania, debe usar las luces bajas cuando sigue a otro vehículo a menos de 300 pies.","p":"Correcto. Use luces bajas a menos de 300 pies del carro de adelante."},"ref":{"doc":"PA","page":40}},{"id":"pa-067","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, you are on a dark road at night using low beams, which light about 250 feet ahead. What top speed does the manual suggest so you do not overdrive your headlights?","o":["45 mph","25 mph","55 mph","65 mph"],"h1":"At 55 mph you need more than 250 feet to stop.","h2":"In Pennsylvania, the manual says that to avoid overdriving your low beams on a dark road, you should not drive faster than 45 mph.","p":"Right. On a dark road with low beams, stay at 45 mph or less."},"es":{"q":"En Pensilvania, maneja de noche por una carretera oscura con las luces bajas, que alumbran unos 250 pies adelante. ¿Qué velocidad máxima sugiere el manual para no ir más rápido de lo que alumbran sus faros?","o":["45 mph","25 mph","55 mph","65 mph"],"h1":"A 55 mph necesita más de 250 pies para detenerse.","h2":"En Pensilvania, el manual dice que para no ir más rápido de lo que alumbran sus luces bajas en una carretera oscura, no debe manejar a más de 45 mph.","p":"Correcto. En una carretera oscura con luces bajas, no pase de 45 mph."},"ref":{"doc":"PA","page":40}},{"id":"pa-068","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, how slow can a car be going and still start to hydroplane on a wet road?","o":["Only above 70 mph","As low as 35 mph","Only above 55 mph","Cars cannot hydroplane"],"h1":"Even 1/10 of an inch of water can be enough.","h2":"In Pennsylvania, the manual says you can hydroplane at speeds as low as 35 mph when water is only 1/10 of an inch deep.","p":"Right. Hydroplaning can start at about 35 mph."},"es":{"q":"En Pensilvania, ¿a qué velocidad tan baja puede un carro empezar a hidroplanear en una carretera mojada?","o":["Solo a más de 70 mph","A tan solo 35 mph","Solo a más de 55 mph","Los carros no pueden hidroplanear"],"h1":"Hasta 1/10 de pulgada de agua puede ser suficiente.","h2":"En Pensilvania, el manual dice que puede hidroplanear a tan solo 35 mph cuando el agua tiene apenas 1/10 de pulgada de profundidad.","p":"Correcto. El hidroplaneo puede empezar a unas 35 mph."},"ref":{"doc":"PA","page":41}},{"id":"pa-069","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, the road is covered with packed snow. How much should you lower your speed?","o":["Slow down by 2 or 3 mph","Slow down by 5 mph","Cut it by about half","Keep your normal speed if you have good tires"],"h1":"On ice you crawl; on packed snow it is a big cut too.","h2":"In Pennsylvania, the manual says to cut your speed by about half on packed snow, and to slow to a crawl on ice.","p":"Right. On packed snow, drive at about half your normal speed."},"es":{"q":"En Pensilvania, la carretera está cubierta de nieve compacta. ¿Cuánto debe bajar la velocidad?","o":["Bajar 2 o 3 mph","Bajar 5 mph","Reducirla a la mitad, más o menos","Mantener la velocidad normal si tiene buenas llantas"],"h1":"En hielo se va muy despacio; en nieve compacta también es una gran reducción.","h2":"En Pensilvania, el manual dice que reduzca su velocidad a la mitad, más o menos, en nieve compacta, y que vaya muy despacio en hielo.","p":"Correcto. En nieve compacta, maneje a la mitad de su velocidad normal."},"ref":{"doc":"PA","page":41}},{"id":"pa-070","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are on the interstate on a clear day and see a snow squall coming ahead. What does the manual advise?","o":["Speed up to get through it quickly","Stop in your lane until it passes","Turn on your high beams and keep going","Exit the road and wait for the squall to pass"],"h1":"A squall can drop visibility to near zero in seconds.","h2":"In Pennsylvania, if you see a snow squall coming, the manual advises you to exit the roadway and wait for the squall to pass.","p":"Right. Get off the road and wait for the squall to pass."},"es":{"q":"En Pensilvania, va por la autopista interestatal en un día despejado y ve que se acerca una ráfaga de nieve (snow squall). ¿Qué aconseja el manual?","o":["Acelerar para cruzarla rápido","Detenerse en su carril hasta que pase","Encender las luces altas y seguir","Salir de la carretera y esperar a que pase"],"h1":"Una ráfaga de nieve puede dejar la visibilidad casi en cero en segundos.","h2":"En Pensilvania, si ve que se acerca una ráfaga de nieve, el manual aconseja salir de la carretera y esperar a que pase.","p":"Correcto. Salga de la carretera y espere a que pase la ráfaga."},"ref":{"doc":"PA","page":43}},{"id":"pa-071","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, a farm tractor or horse-drawn buggy has an orange triangle on the back. What does it tell you?","o":["The vehicle is built to go 25 mph or less","The vehicle carries hazardous material","The vehicle makes wide right turns","The vehicle stops at all railroad crossings"],"h1":"This sign warns about speed.","h2":"In Pennsylvania, an orange triangle on the back of a farm tractor or horse-drawn vehicle means it is designed to go 25 mph or less, slower than normal traffic.","p":"Right. The orange triangle marks a vehicle that goes 25 mph or less."},"es":{"q":"En Pensilvania, un tractor agrícola o una carreta tirada por caballos lleva un triángulo anaranjado atrás. ¿Qué le indica?","o":["El vehículo está hecho para ir a 25 mph o menos","El vehículo lleva materiales peligrosos","El vehículo hace giros anchos a la derecha","El vehículo se detiene en todos los cruces de tren"],"h1":"Este letrero advierte sobre la velocidad.","h2":"En Pensilvania, un triángulo anaranjado atrás de un tractor o vehículo tirado por caballos significa que está hecho para ir a 25 mph o menos, más lento que el tráfico normal.","p":"Correcto. El triángulo anaranjado marca un vehículo que va a 25 mph o menos."},"ref":{"doc":"PA","page":44}},{"id":"pa-072","scope":"PA","cat":"signals","sign":null,"c":1,"en":{"q":"In Pennsylvania, you are driving at 30 mph. At least how far before your turn must you turn on your turn signal?","o":["50 feet","100 feet","300 feet","500 feet"],"h1":"Below 35 mph, the distance is shorter than at higher speeds.","h2":"In Pennsylvania, when you are driving less than 35 mph, you must signal at least 100 feet before you turn.","p":"Right. Under 35 mph, signal at least 100 feet before the turn."},"es":{"q":"En Pensilvania, maneja a 30 mph. ¿Por lo menos a qué distancia antes de girar debe poner la direccional?","o":["50 pies","100 pies","300 pies","500 pies"],"h1":"A menos de 35 mph, la distancia es más corta que a velocidades altas.","h2":"En Pensilvania, cuando maneja a menos de 35 mph, debe poner la direccional por lo menos 100 pies antes de girar.","p":"Correcto. A menos de 35 mph, ponga la direccional por lo menos 100 pies antes."},"ref":{"doc":"PA","page":44}},{"id":"pa-073","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, you want to make a U-turn where it is allowed. How far away should drivers coming from every direction be?","o":["At least 50 feet","At least 100 feet","At least 500 feet","At least one mile"],"h1":"Other drivers must be far away and able to see you clearly.","h2":"In Pennsylvania, before a U-turn, make sure drivers coming from all directions are at least 500 feet away and can see you clearly.","p":"Right. Other drivers should be at least 500 feet away."},"es":{"q":"En Pensilvania, quiere dar una vuelta en U donde está permitido. ¿A qué distancia deben estar los conductores que vienen de todas direcciones?","o":["Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a 500 pies","Por lo menos a una milla"],"h1":"Los otros conductores deben estar lejos y poder verlo bien.","h2":"En Pensilvania, antes de una vuelta en U, asegúrese de que los conductores que vienen de todas direcciones estén por lo menos a 500 pies y puedan verlo bien.","p":"Correcto. Los demás conductores deben estar por lo menos a 500 pies."},"ref":{"doc":"PA","page":46}},{"id":"pa-074","scope":"PA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are in the acceleration lane of a highway on-ramp, behind a slow car. May you pass it there?","o":["Yes, on the left","Yes, on the right shoulder","Yes, if you signal first","No, passing in an acceleration lane is illegal"],"h1":"The acceleration lane is only for reaching highway speed and merging.","h2":"In Pennsylvania, it is illegal to pass a vehicle ahead of you in an acceleration lane.","p":"Right. Do not pass in an acceleration lane."},"es":{"q":"En Pensilvania, está en el carril de aceleración de una rampa de entrada, detrás de un carro lento. ¿Puede pasarlo allí?","o":["Sí, por la izquierda","Sí, por el acotamiento derecho","Sí, si pone la direccional primero","No, pasar en un carril de aceleración es ilegal"],"h1":"El carril de aceleración es solo para alcanzar la velocidad y unirse al tráfico.","h2":"En Pensilvania, es ilegal pasar a un vehículo que va adelante en un carril de aceleración.","p":"Correcto. No pase en un carril de aceleración."},"ref":{"doc":"PA","page":46}},{"id":"pa-075","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, you are stopped at a two-way stop and want to drive straight across a 30 mph street. About how big a gap in traffic do you need from both directions?","o":["About 6 seconds","About 2 seconds","About 15 seconds","About 30 seconds"],"h1":"It is about a block of clear space to each side.","h2":"In Pennsylvania, to cross a 30 mph street from a two-way stop, you need about a 6-second gap in both directions, or about a block of clear space to the left and right.","p":"Right. Look for about a 6-second gap both ways."},"es":{"q":"En Pensilvania, está detenido en un alto de dos direcciones y quiere cruzar derecho una calle de 30 mph. ¿Más o menos qué espacio en el tráfico necesita de ambos lados?","o":["Unos 6 segundos","Unos 2 segundos","Unos 15 segundos","Unos 30 segundos"],"h1":"Es más o menos una cuadra libre a cada lado.","h2":"En Pensilvania, para cruzar una calle de 30 mph desde un alto de dos direcciones, necesita un espacio de unos 6 segundos en ambas direcciones, o una cuadra libre a la izquierda y a la derecha.","p":"Correcto. Busque un espacio de unos 6 segundos de cada lado."},"ref":{"doc":"PA","page":49}},{"id":"pa-076","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, signs at a busy divided road say NO LEFT TURN and ALL TURNS FROM RIGHT LANE. There is a jughandle. How do you go left?","o":["Turn left across the median","Take the right-side ramp that curves back to the road, then turn left at the light","Make a U-turn at the next break","Turn left from the right lane"],"h1":"A jughandle starts on the right.","h2":"In Pennsylvania, at a jughandle you turn left by using the right-turn lane that curves back to meet the main road at a traffic light, and then you turn left there.","p":"Right. Use the jughandle on the right, then turn left at the light."},"es":{"q":"En Pensilvania, en una calle dividida con mucho tráfico, los letreros dicen NO LEFT TURN y ALL TURNS FROM RIGHT LANE. Hay un 'jughandle' (rampa en forma de asa). ¿Cómo gira a la izquierda?","o":["Gira a la izquierda cruzando el camellón","Toma la rampa de la derecha que regresa a la calle y luego gira a la izquierda en el semáforo","Da una vuelta en U en la siguiente abertura","Gira a la izquierda desde el carril derecho"],"h1":"El jughandle empieza a la derecha.","h2":"En Pensilvania, en un jughandle usted gira a la izquierda usando el carril de giro a la derecha que regresa a la calle principal en un semáforo, y allí gira a la izquierda.","p":"Correcto. Use el jughandle de la derecha y luego gire a la izquierda en el semáforo."},"ref":{"doc":"PA","page":50}},{"id":"pa-077","scope":"PA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Pennsylvania, a bicycle rider is riding like a car through a roundabout ahead of you. What does the manual say?","o":["Pass on the left if there is room","Honk so the rider moves to the side","Never pass the bicycle inside the roundabout","Pass on the right near the curb"],"h1":"Stay behind until you both leave the circle.","h2":"In Pennsylvania, you must never pass a bicyclist who is acting as a vehicle in a roundabout.","p":"Right. Never pass a bicycle rider in a roundabout."},"es":{"q":"En Pensilvania, un ciclista va como un carro por una glorieta delante de usted. ¿Qué dice el manual?","o":["Pásela por la izquierda si hay espacio","Toque el claxon para que se haga a un lado","Nunca pase a la bicicleta dentro de la glorieta","Pásela por la derecha cerca de la banqueta"],"h1":"Quédese atrás hasta que ambos salgan de la glorieta.","h2":"En Pensilvania, nunca debe pasar a un ciclista que actúa como vehículo dentro de una glorieta.","p":"Correcto. Nunca pase a un ciclista en una glorieta."},"ref":{"doc":"PA","page":50}},{"id":"pa-078","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are entering a highway on a short weaving lane, and another driver is using it to exit. Who must yield?","o":["The driver exiting","Whoever is going slower","Whoever is in the bigger vehicle","You, the driver entering"],"h1":"The driver leaving the highway gets to go first.","h2":"In Pennsylvania, when entering and exiting traffic share a weaving lane, the driver entering the highway must yield to the exiting driver.","p":"Right. The entering driver yields to the exiting driver."},"es":{"q":"En Pensilvania, está entrando a una autopista por un carril corto de entrecruce, y otro conductor lo usa para salir. ¿Quién debe ceder el paso?","o":["El conductor que sale","El que va más lento","El que maneja el vehículo más grande","Usted, que está entrando"],"h1":"El que sale de la autopista pasa primero.","h2":"En Pensilvania, cuando el tráfico que entra y el que sale comparten un carril de entrecruce, el conductor que entra a la autopista debe ceder el paso al que sale.","p":"Correcto. El que entra cede el paso al que sale."},"ref":{"doc":"PA","page":52}},{"id":"pa-079","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, you park next to a curb. What is the farthest your wheels may be from the curb?","o":["12 inches","6 inches","18 inches","3 feet"],"h1":"Think of one foot.","h2":"In Pennsylvania, when you park next to a curb, you must park as close as you can and no more than 12 inches away.","p":"Right. No more than 12 inches from the curb."},"es":{"q":"En Pensilvania, se estaciona junto a la banqueta. ¿A qué distancia máxima pueden quedar sus llantas de la banqueta?","o":["12 pulgadas","6 pulgadas","18 pulgadas","3 pies"],"h1":"Piense en un pie.","h2":"En Pensilvania, cuando se estaciona junto a la banqueta, debe quedar lo más cerca posible y a no más de 12 pulgadas.","p":"Correcto. A no más de 12 pulgadas de la banqueta."},"ref":{"doc":"PA","page":52}},{"id":"pa-080","scope":"PA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Pennsylvania, you park facing uphill on a street with a curb. Which way should you turn your steering wheel?","o":["To the right, toward the curb","To the left, away from the curb","Keep the wheels straight","It does not matter if you set the parking brake"],"h1":"Uphill with a curb is the one case that is different.","h2":"In Pennsylvania, when you park uphill next to a curb, turn your steering wheel to the left, so the wheels point away from the curb.","p":"Right. Uphill with a curb, turn the wheel left."},"es":{"q":"En Pensilvania, se estaciona cuesta arriba en una calle con banqueta. ¿Hacia dónde debe girar el volante?","o":["A la derecha, hacia la banqueta","A la izquierda, lejos de la banqueta","Dejar las llantas derechas","No importa si pone el freno de mano"],"h1":"Cuesta arriba con banqueta es el único caso diferente.","h2":"En Pensilvania, cuando se estaciona cuesta arriba junto a una banqueta, gire el volante a la izquierda, para que las llantas apunten lejos de la banqueta.","p":"Correcto. Cuesta arriba con banqueta, gire el volante a la izquierda."},"ref":{"doc":"PA","page":52}},{"id":"pa-081","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Firefighters need room to connect their hoses.","h2":"In Pennsylvania, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Pensilvania, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 30 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Pensilvania, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"ref":{"doc":"PA","page":53}},{"id":"pa-082","scope":"PA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Pennsylvania, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 50 feet","No closer than 20 feet"],"h1":"Drivers need to see people stepping into the crosswalk.","h2":"In Pennsylvania, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Pensilvania, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 5 pies","No a menos de 10 pies","No a menos de 50 pies","No a menos de 20 pies"],"h1":"Los conductores necesitan ver a las personas que entran al cruce.","h2":"En Pensilvania, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese por lo menos a 20 pies de un cruce peatonal en una intersección."},"ref":{"doc":"PA","page":53}},{"id":"pa-083","scope":"PA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Pennsylvania, how close to a stop sign at the side of the road may you park?","o":["No closer than 30 feet","No closer than 10 feet","No closer than 15 feet","No closer than 100 feet"],"h1":"The same rule covers yield signs and flashing signals.","h2":"In Pennsylvania, you may not park within 30 feet of a stop sign, yield sign, flashing signal or other traffic control device at the side of the road.","p":"Right. Stay at least 30 feet from a stop sign."},"es":{"q":"En Pensilvania, ¿qué tan cerca de un letrero de alto al lado de la calle puede estacionarse?","o":["No a menos de 30 pies","No a menos de 10 pies","No a menos de 15 pies","No a menos de 100 pies"],"h1":"La misma regla aplica a letreros de ceda el paso y a luces intermitentes.","h2":"En Pensilvania, no puede estacionarse a menos de 30 pies de un letrero de alto, de ceda el paso, de una luz intermitente u otro dispositivo de tráfico al lado de la calle.","p":"Correcto. Quédese por lo menos a 30 pies de un letrero de alto."},"ref":{"doc":"PA","page":53}},{"id":"pa-084","scope":"PA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Pennsylvania, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 50 feet","No closer than 20 feet","No closer than 200 feet"],"h1":"It is farther than the distance for a fire hydrant or a crosswalk.","h2":"In Pennsylvania, you may not park within 50 feet of the nearest rail at a railroad crossing.","p":"Right. Stay at least 50 feet from the nearest rail."},"es":{"q":"En Pensilvania, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 15 pies","No a menos de 50 pies","No a menos de 20 pies","No a menos de 200 pies"],"h1":"Es más lejos que la distancia para un hidrante o un cruce peatonal.","h2":"En Pensilvania, no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Quédese por lo menos a 50 pies del riel más cercano."},"ref":{"doc":"PA","page":53}},{"id":"pa-085","scope":"PA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Pennsylvania, you are behind a motorcycle in a single lane. How much of the lane does the law let the rider use?","o":["Only the right half","Only the left half","The whole lane","Only the space near the shoulder"],"h1":"Do not try to share the lane with the motorcycle.","h2":"In Pennsylvania, the law says you must allow a motorcycle or moped rider to use one complete lane.","p":"Right. A motorcycle gets a complete lane."},"es":{"q":"En Pensilvania, va detrás de una motocicleta en un solo carril. ¿Cuánto del carril le permite la ley usar al motociclista?","o":["Solo la mitad derecha","Solo la mitad izquierda","El carril completo","Solo el espacio cerca del acotamiento"],"h1":"No intente compartir el carril con la motocicleta.","h2":"En Pensilvania, la ley dice que debe permitir que un motociclista o conductor de ciclomotor use un carril completo.","p":"Correcto. Una motocicleta tiene derecho a un carril completo."},"ref":{"doc":"PA","page":56}},{"id":"pa-086","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you pulled over for an ambulance with its siren on. It has passed you. How far behind it should you stay when you drive on?","o":["At least 50 feet","At least 100 feet","At least one mile","At least 500 feet"],"h1":"Leave a long gap of several hundred feet.","h2":"In Pennsylvania, after an emergency vehicle passes you, start driving again but keep at least 500 feet away from it.","p":"Right. Stay at least 500 feet behind the emergency vehicle."},"es":{"q":"En Pensilvania, se orilló para dejar pasar una ambulancia con la sirena encendida. Ya pasó. ¿A qué distancia detrás de ella debe quedarse al seguir manejando?","o":["Por lo menos a 50 pies","Por lo menos a 100 pies","Por lo menos a una milla","Por lo menos a 500 pies"],"h1":"Deje un espacio largo, de varios cientos de pies.","h2":"En Pensilvania, después de que pasa un vehículo de emergencia, siga manejando pero quédese por lo menos a 500 pies de él.","p":"Correcto. Quédese por lo menos a 500 pies detrás del vehículo de emergencia."},"ref":{"doc":"PA","page":59}},{"id":"pa-087","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, a driver breaks the Move Over law and seriously injures an emergency responder. What license suspension follows?","o":["6 months","15 days","30 days","10 years"],"h1":"It is longer than the 90 days for injuring another person.","h2":"In Pennsylvania, if breaking the Move Over law seriously injures an emergency responder or a person in or near a disabled vehicle, the license is suspended for 6 months, with a fine of up to $5,000.","p":"Right. A 6-month suspension and up to a $5,000 fine."},"es":{"q":"En Pensilvania, un conductor no cumple la ley Move Over (muévase) y lesiona gravemente a un socorrista. ¿Qué suspensión de licencia recibe?","o":["6 meses","15 días","30 días","10 años"],"h1":"Es más larga que los 90 días por lesionar a otra persona.","h2":"En Pensilvania, si no cumplir la ley Move Over causa lesiones graves a un socorrista o a una persona dentro o cerca de un vehículo descompuesto, la licencia se suspende por 6 meses, con una multa de hasta $5,000.","p":"Correcto. Una suspensión de 6 meses y una multa de hasta $5,000."},"ref":{"doc":"PA","page":59}},{"id":"pa-088","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, may a 15-year-old ride in the open bed of a pickup truck on a normal trip to the store?","o":["Yes, if the truck goes under 35 mph","No, a child under 18 may not ride in the open bed, except in a few special cases","Yes, if an adult rides with them","Yes, on roads with no traffic lights"],"h1":"The exceptions are for farm work, hunting trips and parades.","h2":"In Pennsylvania, a pickup or flatbed truck may not be driven with a child under 18 in the open bed, except in special cases like farm work, hunting trips or an official parade.","p":"Right. No riders under 18 in an open truck bed on a normal trip."},"es":{"q":"En Pensilvania, ¿puede un joven de 15 años ir en la caja abierta de una camioneta pickup en un viaje normal a la tienda?","o":["Sí, si la camioneta va a menos de 35 mph","No, un menor de 18 no puede ir en la caja abierta, salvo en unos pocos casos especiales","Sí, si un adulto va con él","Sí, en calles sin semáforos"],"h1":"Las excepciones son para trabajo agrícola, cacería y desfiles.","h2":"En Pensilvania, no se puede manejar una camioneta pickup o de plataforma con un menor de 18 años en la caja abierta, salvo en casos especiales como trabajo agrícola, viajes de cacería o un desfile oficial.","p":"Correcto. Ningún menor de 18 en una caja abierta en un viaje normal."},"ref":{"doc":"PA","page":59}},{"id":"pa-089","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, you are behind a snowplow that is clearing the road. What does the manual say about passing it?","o":["Pass on the right, where the snow is cleared","Pass on the left quickly","Do not try to pass it on the left or the right","Pass only if you honk first"],"h1":"Plows can have wing blades that stick out several feet on the sides.","h2":"In Pennsylvania, the manual says you should not try to pass a snowplow on either the left or the right, and you should follow at a safe distance.","p":"Right. Stay back and do not pass a snowplow."},"es":{"q":"En Pensilvania, va detrás de una barredora de nieve que limpia la carretera. ¿Qué dice el manual sobre pasarla?","o":["Pásela por la derecha, donde ya está limpio","Pásela rápido por la izquierda","No intente pasarla ni por la izquierda ni por la derecha","Pásela solo si toca el claxon primero"],"h1":"Las barredoras pueden tener cuchillas laterales que salen varios pies a los lados.","h2":"En Pensilvania, el manual dice que no debe intentar pasar a una barredora de nieve ni por la izquierda ni por la derecha, y que debe seguirla a una distancia segura.","p":"Correcto. Quédese atrás y no pase a la barredora de nieve."},"ref":{"doc":"PA","page":60}},{"id":"pa-090","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, how far should the driver sit from the steering wheel, in case the air bag opens?","o":["At least 2 inches","At least 5 inches","As close as possible","At least 10 inches"],"h1":"Move the seat back as far as you can while still reaching the pedals.","h2":"In Pennsylvania, the manual says you should sit at least 10 inches away from the steering wheel in case the air bag opens.","p":"Right. Sit at least 10 inches from the steering wheel."},"es":{"q":"En Pensilvania, ¿a qué distancia del volante debe sentarse el conductor, por si se abre la bolsa de aire?","o":["Por lo menos a 2 pulgadas","Por lo menos a 5 pulgadas","Lo más cerca posible","Por lo menos a 10 pulgadas"],"h1":"Mueva el asiento hacia atrás lo más que pueda sin dejar de alcanzar los pedales.","h2":"En Pensilvania, el manual dice que debe sentarse por lo menos a 10 pulgadas del volante por si se abre la bolsa de aire.","p":"Correcto. Siéntese por lo menos a 10 pulgadas del volante."},"ref":{"doc":"PA","page":91}},{"id":"pa-091","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, your gas pedal is stuck and you must stop fast. You turn the key. Which position should you use?","o":["OFF, not LOCK","LOCK, not OFF","START","ACCESSORY"],"h1":"One position also locks the steering wheel.","h2":"In Pennsylvania, if you must turn off the engine because the gas pedal is stuck, turn the key to OFF, not LOCK, because LOCK makes you lose steering.","p":"Right. Turn it to OFF so you can still steer."},"es":{"q":"En Pensilvania, el acelerador se atoró y necesita detenerse rápido. Gira la llave. ¿Qué posición debe usar?","o":["OFF (apagado), no LOCK","LOCK (bloqueo), no OFF","START (arranque)","ACCESSORY (accesorios)"],"h1":"Una de las posiciones también bloquea el volante.","h2":"En Pensilvania, si debe apagar el motor porque el acelerador se atoró, gire la llave a OFF, no a LOCK, porque LOCK hace que pierda la dirección.","p":"Correcto. Gírela a OFF para poder seguir manejando el volante."},"ref":{"doc":"PA","page":62}},{"id":"pa-092","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, the lead car of a funeral procession entered an intersection on a green light. The light is now red. What may the other cars in the procession do?","o":["Stop and wait for the next green light","Keep going through the intersection","Go only if a police officer is there","Turn right on red only"],"h1":"The procession stays together once its lead car has gone through.","h2":"In Pennsylvania, drivers in a funeral procession may go through a red light if the lead vehicle started through the intersection while the light was green, and other traffic must yield.","p":"Right. The procession may follow its lead car through the red light."},"es":{"q":"En Pensilvania, el primer carro de un cortejo fúnebre entró a la intersección con la luz verde. Ahora la luz está en rojo. ¿Qué pueden hacer los demás carros del cortejo?","o":["Detenerse y esperar la siguiente luz verde","Seguir cruzando la intersección","Pasar solo si hay un policía","Solo girar a la derecha en rojo"],"h1":"El cortejo se mantiene unido una vez que su primer carro ha pasado.","h2":"En Pensilvania, los conductores de un cortejo fúnebre pueden pasar con la luz roja si el primer vehículo entró a la intersección con la luz verde, y el resto del tráfico debe ceder el paso.","p":"Correcto. El cortejo puede seguir a su primer carro con la luz roja."},"ref":{"doc":"PA","page":64}},{"id":"pa-093","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, a driver's record is lowered below 6 points and later reaches 6 or more points a second time. What happens?","o":["The driver takes the written special point exam again","Nothing, if the driver pays the fines","The driver must go to a PennDOT hearing","The license is revoked for 5 years"],"h1":"The first time is a written exam; the second time is more serious.","h2":"In Pennsylvania, when a driving record reaches 6 or more points for the second time, the driver must attend a departmental hearing.","p":"Right. The second time at 6 points means a departmental hearing."},"es":{"q":"En Pensilvania, el récord de un conductor baja a menos de 6 puntos y después llega a 6 o más puntos por segunda vez. ¿Qué pasa?","o":["El conductor toma otra vez el examen escrito especial de puntos","Nada, si paga las multas","El conductor debe ir a una audiencia de PennDOT","La licencia se revoca por 5 años"],"h1":"La primera vez es un examen escrito; la segunda vez es más serio.","h2":"En Pensilvania, cuando el récord de manejo llega a 6 o más puntos por segunda vez, el conductor debe ir a una audiencia del departamento.","p":"Correcto. La segunda vez con 6 puntos significa una audiencia del departamento."},"ref":{"doc":"PA","page":79}},{"id":"pa-094","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, a driver under 18 already had a 90-day suspension for points. Now they reach 6 points again. How long is this suspension?","o":["30 days","90 days","Two years","120 days"],"h1":"Each repeat suspension is longer than the first one.","h2":"In Pennsylvania, a driver under 18 gets a 90-day suspension the first time and a 120-day suspension for any later time they reach 6 points or speed 26 mph or more over the limit.","p":"Right. Any later suspension for a driver under 18 is 120 days."},"es":{"q":"En Pensilvania, un conductor menor de 18 años ya tuvo una suspensión de 90 días por puntos. Ahora llega otra vez a 6 puntos. ¿Cuánto dura esta suspensión?","o":["30 días","90 días","Dos años","120 días"],"h1":"Cada suspensión repetida es más larga que la primera.","h2":"En Pensilvania, un conductor menor de 18 años recibe una suspensión de 90 días la primera vez y de 120 días cada vez siguiente que llega a 6 puntos o excede el límite por 26 mph o más.","p":"Correcto. Cualquier suspensión siguiente para un menor de 18 es de 120 días."},"ref":{"doc":"PA","page":79}},{"id":"pa-095","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, a car behind you is flashing only blue lights. What does the manual say about it?","o":["It is not a police officer","It is an unmarked police car","It is a state trooper","It is a tow truck asking you to stop"],"h1":"Police lights are red and blue, or red only on unmarked cars.","h2":"In Pennsylvania, police use flashing red and blue lights, or red only on unmarked cars; a vehicle flashing only blue lights is not a police officer.","p":"Right. Blue lights alone do not mean police."},"es":{"q":"En Pensilvania, un carro detrás de usted tiene encendidas solo luces azules intermitentes. ¿Qué dice el manual?","o":["No es un policía","Es una patrulla sin marcas","Es un policía estatal","Es una grúa que le pide detenerse"],"h1":"Las luces de la policía son rojas y azules, o solo rojas en carros sin marcas.","h2":"En Pensilvania, la policía usa luces intermitentes rojas y azules, o solo rojas en carros sin marcas; un vehículo con solo luces azules no es un policía.","p":"Correcto. Solo luces azules no significa policía."},"ref":{"doc":"PA","page":81}},{"id":"pa-096","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, a driver is convicted of fleeing or trying to elude the police. What license penalty follows?","o":["A warning letter","A one-year suspension","A 15-day suspension","Two points only"],"h1":"There is also a $500 fine and possibly jail.","h2":"In Pennsylvania, a conviction for fleeing or eluding police brings a one-year suspension, a $500 fine plus costs, and possibly jail.","p":"Right. Fleeing police means a one-year suspension."},"es":{"q":"En Pensilvania, un conductor es condenado por huir o tratar de escapar de la policía. ¿Qué castigo recibe en su licencia?","o":["Una carta de advertencia","Una suspensión de un año","Una suspensión de 15 días","Solo dos puntos"],"h1":"También hay una multa de $500 y posible cárcel.","h2":"En Pensilvania, una condena por huir o escapar de la policía trae una suspensión de un año, una multa de $500 más costos, y posible cárcel.","p":"Correcto. Huir de la policía significa una suspensión de un año."},"ref":{"doc":"PA","page":81}},{"id":"pa-097","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, a 19-year-old is convicted of DUI for the first time. How long is the license suspended?","o":["30 days","90 days","One full year","No suspension for a first offense"],"h1":"Drivers under 21 face the stricter penalties.","h2":"In Pennsylvania, a driver under 21 convicted of DUI for the first time loses their license for a full year, faces 2 days to 6 months in jail, and pays a $500 to $5,000 fine.","p":"Right. A first DUI under 21 means a one-year suspension."},"es":{"q":"En Pensilvania, un joven de 19 años es condenado por manejar bajo los efectos del alcohol (DUI) por primera vez. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","90 días","Un año completo","No hay suspensión la primera vez"],"h1":"Los conductores menores de 21 reciben los castigos más duros.","h2":"En Pensilvania, un conductor menor de 21 años condenado por DUI por primera vez pierde la licencia por un año completo, puede ir de 2 días a 6 meses a la cárcel y paga una multa de $500 a $5,000.","p":"Correcto. Un primer DUI antes de los 21 significa un año de suspensión."},"ref":{"doc":"PA","page":84}},{"id":"pa-098","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, how must a 3-year-old ride in a car?","o":["In a booster seat with a lap belt only","With an adult seat belt, if in the back seat","On an adult's lap in the back seat","In an approved child safety seat, in any seat of the car"],"h1":"Booster seats are for children 4 to 7.","h2":"In Pennsylvania, children under 4 must ride in a federally approved child safety seat, no matter where they sit in the vehicle.","p":"Right. Under 4 means a child safety seat."},"es":{"q":"En Pensilvania, ¿cómo debe viajar un niño de 3 años en un carro?","o":["En un asiento elevado con solo el cinturón de cadera","Con el cinturón de un adulto, si va atrás","En las piernas de un adulto en el asiento de atrás","En un asiento de seguridad infantil aprobado, en cualquier asiento del carro"],"h1":"Los asientos elevados son para niños de 4 a 7 años.","h2":"En Pensilvania, los niños menores de 4 años deben viajar en un asiento de seguridad infantil aprobado por el gobierno federal, sin importar dónde vayan sentados.","p":"Correcto. Menos de 4 años significa asiento de seguridad infantil."},"ref":{"doc":"PA","page":90}},{"id":"pa-099","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, how early may you get your vehicle's yearly safety inspection before the sticker runs out?","o":["Up to 90 days before","Up to 7 days before","Up to 30 days before","Only in the month it runs out"],"h1":"It is about three months.","h2":"In Pennsylvania, a vehicle may be inspected up to 90 days before its inspection sticker expires.","p":"Right. You may inspect up to 90 days early."},"es":{"q":"En Pensilvania, ¿con cuánta anticipación puede hacer la inspección de seguridad anual de su vehículo antes de que venza la calcomanía?","o":["Hasta 90 días antes","Hasta 7 días antes","Hasta 30 días antes","Solo en el mes en que vence"],"h1":"Son unos tres meses.","h2":"En Pensilvania, un vehículo se puede inspeccionar hasta 90 días antes de que venza su calcomanía de inspección.","p":"Correcto. Puede hacer la inspección hasta 90 días antes."},"ref":{"doc":"PA","page":92}},{"id":"pa-100","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, you drive around a ROAD CLOSED barrier that was put up because of flooding. How many points go on your record?","o":["No points, only a warning","2 points","5 points","11 points"],"h1":"There is also a fine of up to $250.","h2":"In Pennsylvania, driving around or through signs or devices that close a road for hazardous conditions brings 2 points and a fine of up to $250, or up to $500 plus costs if emergency responders must be called.","p":"Right. 2 points, and a fine of up to $250."},"es":{"q":"En Pensilvania, usted pasa alrededor de una barrera de ROAD CLOSED (camino cerrado) puesta por una inundación. ¿Cuántos puntos se le ponen en su récord?","o":["Ningún punto, solo una advertencia","2 puntos","5 puntos","11 puntos"],"h1":"También hay una multa de hasta $250.","h2":"En Pensilvania, pasar alrededor o a través de letreros o barreras que cierran un camino por condiciones peligrosas trae 2 puntos y una multa de hasta $250, o hasta $500 más costos si hay que llamar a los socorristas.","p":"Correcto. 2 puntos y una multa de hasta $250."},"ref":{"doc":"PA","page":93}},{"id":"pa-101","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, how long is the learner's permit application (DL-180) good for, counted from the date of your physical exam?","o":["One year","Six months","Two years","Five years"],"h1":"Count from the day your health care provider examined you.","h2":"In Pennsylvania, the DL-180 learner's permit application is valid for one year from the date of your physical exam.","p":"Right. The DL-180 is good for one year from the physical exam."},"es":{"q":"En Pensilvania, ¿por cuánto tiempo es válida la solicitud del permiso de aprendizaje (DL-180), contando desde la fecha de su examen físico?","o":["Un año","Seis meses","Dos años","Cinco años"],"h1":"Cuente desde el día en que su proveedor de salud lo examinó.","h2":"En Pensilvania, la solicitud del permiso de aprendizaje DL-180 es válida por un año desde la fecha de su examen físico.","p":"Correcto. La DL-180 es válida por un año desde el examen físico."},"ref":{"doc":"PA","page":1}},{"id":"pa-102","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, three years have passed since your permit physical exam, and you still have not passed the road test. What must you do?","o":["Nothing; your permit stays valid until you pass","Start over with a new DL-180 and take the knowledge test again","Only take a new vision test","Wait one more year, then take the road test"],"h1":"After that much time, you go back to the very first step.","h2":"In Pennsylvania, if you have not passed the road test within three years of your physical exam, you must start over with a new DL-180 and take the knowledge test again.","p":"Right. After three years, you start over with a new DL-180 and the knowledge test."},"es":{"q":"En Pensilvania, han pasado tres años desde el examen físico de su permiso y todavía no ha aprobado el examen de manejo. ¿Qué debe hacer?","o":["Nada; su permiso sigue válido hasta que apruebe","Empezar de nuevo con una nueva DL-180 y tomar otra vez el examen de conocimientos","Solo tomar un nuevo examen de la vista","Esperar un año más y luego tomar el examen de manejo"],"h1":"Después de tanto tiempo, vuelve al primer paso.","h2":"En Pensilvania, si no aprueba el examen de manejo dentro de los tres años desde su examen físico, debe empezar de nuevo con una nueva DL-180 y tomar otra vez el examen de conocimientos.","p":"Correcto. Después de tres años, empieza de nuevo con una nueva DL-180 y el examen de conocimientos."},"ref":{"doc":"PA","page":6}},{"id":"pa-103","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, you are 17 and have a junior license. How long must you have held it before you can apply to change it to a regular license?","o":["Six months","Two years","One year","You cannot; you must wait until you turn 18"],"h1":"You also need a clean record for that same length of time.","h2":"In Pennsylvania, you may apply for a regular license after holding a junior license for one year, if you meet the other conditions.","p":"Right. You must hold the junior license for one year first."},"es":{"q":"En Pensilvania, usted tiene 17 años y una licencia de menor (junior). ¿Cuánto tiempo debe haberla tenido antes de pedir cambiarla a una licencia regular?","o":["Seis meses","Dos años","Un año","No puede; debe esperar a cumplir 18"],"h1":"También necesita un récord limpio durante ese mismo tiempo.","h2":"En Pensilvania, puede pedir una licencia regular después de tener la licencia de menor por un año, si cumple con las demás condiciones.","p":"Correcto. Primero debe tener la licencia de menor por un año."},"ref":{"doc":"PA","page":4}},{"id":"pa-104","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, which of these is a condition for changing a junior license to a regular license before you turn 18?","o":["You retake the road test","You log 100 more hours of practice","You take the special point exam","You passed a driver training course approved by the PA Department of Education"],"h1":"It is a course, not a test or extra hours.","h2":"In Pennsylvania, to change a junior license to a regular license before 18, you must have passed a driver training course approved by the PA Department of Education, among other conditions.","p":"Right. You need an approved driver training course."},"es":{"q":"En Pensilvania, ¿cuál de estas es una condición para cambiar una licencia de menor (junior) a una licencia regular antes de cumplir 18 años?","o":["Tomar otra vez el examen de manejo","Practicar 100 horas más","Tomar el examen especial de puntos","Haber aprobado un curso de manejo aprobado por el Departamento de Educación de PA"],"h1":"Es un curso, no un examen ni horas extra.","h2":"En Pensilvania, para cambiar una licencia de menor a una licencia regular antes de los 18, debe haber aprobado un curso de manejo aprobado por el Departamento de Educación de PA, entre otras condiciones.","p":"Correcto. Necesita un curso de manejo aprobado."},"ref":{"doc":"PA","page":4}},{"id":"pa-105","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, you have a regular Class C license. Which of these may you also drive?","o":["A motor-driven cycle with an automatic transmission and 50 cc or less","Any two-wheeled motorcycle","A large motorcycle with a manual transmission","Any motorcycle, if you wear a helmet"],"h1":"Only a very small cycle is allowed.","h2":"In Pennsylvania, a Class C license lets you drive a motor-driven cycle with an automatic transmission and an engine of 50 cc or less.","p":"Right. Class C covers a small automatic cycle of 50 cc or less."},"es":{"q":"En Pensilvania, usted tiene una licencia regular Clase C. ¿Cuál de estos vehículos también puede manejar?","o":["Un ciclomotor con transmisión automática y de 50 cc o menos","Cualquier motocicleta de dos ruedas","Una motocicleta grande con transmisión manual","Cualquier motocicleta, si usa casco"],"h1":"Solo se permite un ciclomotor muy pequeño.","h2":"En Pensilvania, la licencia Clase C le permite manejar un ciclomotor con transmisión automática y motor de 50 cc o menos.","p":"Correcto. La Clase C cubre un ciclomotor automático de 50 cc o menos."},"ref":{"doc":"PA","page":4}},{"id":"pa-106","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, you want to drive a single motor home rated at 26,001 pounds. Which license class do you need?","o":["Class C","Class B","Class M","No special class; any license works"],"h1":"It is a single vehicle rated over 26,000 pounds.","h2":"In Pennsylvania, you need a Class B license to drive any single vehicle rated over 26,000 pounds, such as a motor home rated at 26,001 pounds or more.","p":"Right. Class B is for a single vehicle over 26,000 pounds."},"es":{"q":"En Pensilvania, usted quiere manejar una casa rodante (un solo vehículo) de 26,001 libras de peso nominal. ¿Qué clase de licencia necesita?","o":["Clase C","Clase B","Clase M","Ninguna clase especial; sirve cualquier licencia"],"h1":"Es un solo vehículo de más de 26,000 libras.","h2":"En Pensilvania, necesita una licencia Clase B para manejar cualquier vehículo individual de más de 26,000 libras, como una casa rodante de 26,001 libras o más.","p":"Correcto. La Clase B es para un solo vehículo de más de 26,000 libras."},"ref":{"doc":"PA","page":4}},{"id":"pa-107","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, how big is the space you must parallel park in during the road test?","o":["20 feet long and 6 feet wide","30 feet long and 10 feet wide","24 feet long and 8 feet wide","18 feet long and 8 feet wide"],"h1":"It is about one and a half car lengths long.","h2":"In Pennsylvania, the road test parallel parking space is 24 feet long and 8 feet wide.","p":"Right. The space is 24 feet by 8 feet."},"es":{"q":"En Pensilvania, ¿qué tamaño tiene el espacio donde debe estacionarse en paralelo durante el examen de manejo?","o":["20 pies de largo y 6 pies de ancho","30 pies de largo y 10 pies de ancho","24 pies de largo y 8 pies de ancho","18 pies de largo y 8 pies de ancho"],"h1":"Mide más o menos el largo de un auto y medio.","h2":"En Pensilvania, el espacio para estacionarse en paralelo en el examen de manejo mide 24 pies de largo y 8 pies de ancho.","p":"Correcto. El espacio mide 24 por 8 pies."},"ref":{"doc":"PA","page":6}},{"id":"pa-108","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, during the road test you parallel park. How many adjustments may you make?","o":["As many as you need","None; it must be done in one move","Up to five, in two attempts","No more than three, in one attempt"],"h1":"You get one try and a small number of corrections.","h2":"In Pennsylvania, on the road test you have one attempt to parallel park, using no more than three adjustments.","p":"Right. One attempt, no more than three adjustments."},"es":{"q":"En Pensilvania, durante el examen de manejo usted se estaciona en paralelo. ¿Cuántos ajustes puede hacer?","o":["Todos los que necesite","Ninguno; debe hacerlo en un solo movimiento","Hasta cinco, en dos intentos","No más de tres, en un solo intento"],"h1":"Tiene un intento y pocas correcciones.","h2":"En Pensilvania, en el examen de manejo tiene un intento para estacionarse en paralelo, con no más de tres ajustes.","p":"Correcto. Un intento, no más de tres ajustes."},"ref":{"doc":"PA","page":6}},{"id":"pa-109","scope":"PA","cat":"signals","sign":null,"c":0,"en":{"q":"In Pennsylvania, a DIVIDED HIGHWAY sign is posted where your road crosses a divided highway. At the first roadway you reach, which turn may you make?","o":["Only a right turn","Only a left turn","A left or a right turn","No turn; you must go straight across both roadways"],"h1":"A divided highway is two one-way roads. Think about which way the near side flows.","h2":"In Pennsylvania, at a divided highway you may only turn right onto the first roadway, and only turn left onto the second roadway.","p":"Right. Only right at the first roadway; left turns are made at the second."},"es":{"q":"En Pensilvania, hay un letrero de DIVIDED HIGHWAY (carretera dividida) donde su camino cruza una carretera dividida. En la primera calzada a la que llega, ¿qué vuelta puede hacer?","o":["Solo una vuelta a la derecha","Solo una vuelta a la izquierda","Una vuelta a la izquierda o a la derecha","Ninguna; debe cruzar derecho las dos calzadas"],"h1":"Una carretera dividida son dos caminos de un solo sentido. Piense hacia dónde va el lado más cercano.","h2":"En Pensilvania, en una carretera dividida solo puede dar vuelta a la derecha en la primera calzada, y solo a la izquierda en la segunda calzada.","p":"Correcto. Solo a la derecha en la primera calzada; a la izquierda se da vuelta en la segunda."},"ref":{"doc":"PA","page":11}},{"id":"pa-110","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, how far before a work zone may warning signs, warning vehicles or message boards first appear?","o":["Only right at the start of the work","At least 200 feet before it","At least 5 miles before it","Exactly 50 feet before it"],"h1":"It is more than 100 feet but much less than a mile.","h2":"In Pennsylvania, warning signs, advance warning vehicles or message boards may be placed a minimum of 200 feet before a work zone.","p":"Right. They may start at least 200 feet before the work zone."},"es":{"q":"En Pensilvania, ¿a qué distancia antes de una zona de obras pueden aparecer los primeros letreros, vehículos o tableros de aviso?","o":["Solo justo donde empieza la obra","Al menos 200 pies antes","Al menos 5 millas antes","Exactamente 50 pies antes"],"h1":"Es más de 100 pies pero mucho menos que una milla.","h2":"En Pensilvania, los letreros de aviso, los vehículos de aviso o los tableros de mensajes se pueden poner como mínimo a 200 pies antes de una zona de obras.","p":"Correcto. Pueden empezar al menos 200 pies antes de la zona de obras."},"ref":{"doc":"PA","page":54}},{"id":"pa-111","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, you are caught speeding in an active work zone. What happens to the fine?","o":["It is cut in half","It stays the same","It is doubled","There is no fine, only a warning"],"h1":"Work zones protect workers, so the penalty is higher.","h2":"In Pennsylvania, fines are doubled for certain violations in active work zones, including speeding.","p":"Right. Speeding fines are doubled in active work zones."},"es":{"q":"En Pensilvania, lo detienen por exceso de velocidad en una zona de obras activa. ¿Qué pasa con la multa?","o":["Se reduce a la mitad","Queda igual","Se duplica","No hay multa, solo una advertencia"],"h1":"Las zonas de obras protegen a los trabajadores, por eso la pena es mayor.","h2":"En Pensilvania, las multas se duplican por ciertas infracciones en zonas de obras activas, incluido el exceso de velocidad.","p":"Correcto. Las multas por velocidad se duplican en zonas de obras activas."},"ref":{"doc":"PA","page":54}},{"id":"pa-112","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you did not turn on your headlights when the law required it. The fine starts at $25. With court costs and fees, about how much can the total reach?","o":["About $10","About $500","About $1,000","About $100"],"h1":"It is about four times the starting fine.","h2":"In Pennsylvania, the fine for not using headlights when required starts at $25, and with other costs the penalty can approach $100.","p":"Right. With costs, it can approach $100."},"es":{"q":"En Pensilvania, usted no encendió los faros cuando la ley lo exigía. La multa empieza en $25. Con los costos y cargos, ¿a cuánto puede llegar el total?","o":["A unos $10","A unos $500","A unos $1,000","A unos $100"],"h1":"Es unas cuatro veces la multa inicial.","h2":"En Pensilvania, la multa por no usar los faros cuando se exige empieza en $25, y con otros costos la pena puede acercarse a $100.","p":"Correcto. Con los costos, puede acercarse a $100."},"ref":{"doc":"PA","page":40}},{"id":"pa-113","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, the road is wet and slick. What following distance does the manual tell you to keep?","o":["5 or 6 seconds","2 seconds","3 seconds","10 seconds or more"],"h1":"It is a little more than the normal dry-road rule.","h2":"In Pennsylvania, on wet roads you should slow down by 5 to 10 mph and increase your following distance to 5 or 6 seconds.","p":"Right. On wet roads, keep 5 or 6 seconds."},"es":{"q":"En Pensilvania, el camino está mojado y resbaloso. ¿Qué distancia de seguimiento le indica el manual?","o":["5 o 6 segundos","2 segundos","3 segundos","10 segundos o más"],"h1":"Es un poco más que la regla normal para camino seco.","h2":"En Pensilvania, en caminos mojados debe bajar la velocidad de 5 a 10 mph y aumentar la distancia de seguimiento a 5 o 6 segundos.","p":"Correcto. En camino mojado, deje 5 o 6 segundos."},"ref":{"doc":"PA","page":41}},{"id":"pa-114","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, you are driving on an icy or snow-covered road. How much space should you leave behind the vehicle ahead?","o":["The same as normal","About 10 times more than normal","About twice as much as normal","One car length for every 10 mph"],"h1":"It is far more than on a dry road.","h2":"In Pennsylvania, on ice or snow you should leave about 10 times more space than normal between you and the vehicle ahead.","p":"Right. Leave about 10 times the normal space."},"es":{"q":"En Pensilvania, usted maneja en un camino con hielo o cubierto de nieve. ¿Cuánto espacio debe dejar detrás del vehículo de adelante?","o":["Lo mismo de siempre","Unas 10 veces más de lo normal","Unas dos veces más de lo normal","El largo de un auto por cada 10 mph"],"h1":"Es mucho más que en un camino seco.","h2":"En Pensilvania, en hielo o nieve debe dejar unas 10 veces más espacio de lo normal entre usted y el vehículo de adelante.","p":"Correcto. Deje unas 10 veces el espacio normal."},"ref":{"doc":"PA","page":41}},{"id":"pa-115","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, you suddenly drive into a snow squall and can barely see. What does the manual tell you to do?","o":["Brake hard right away","Speed up to get through it quickly","Slow down gradually and turn on your hazard lights","Stop in your lane and turn off your lights"],"h1":"Avoid sudden moves, and help others see you.","h2":"In Pennsylvania, if you meet a snow squall, slow down gradually, turn on your hazard lights and do not slam on your brakes.","p":"Right. Slow gradually and use your hazard lights."},"es":{"q":"En Pensilvania, de repente entra en una ráfaga de nieve (snow squall) y casi no puede ver. ¿Qué le indica el manual?","o":["Frenar fuerte de inmediato","Acelerar para salir rápido","Bajar la velocidad poco a poco y encender las luces de emergencia","Parar en su carril y apagar las luces"],"h1":"Evite movimientos bruscos y ayude a que otros lo vean.","h2":"En Pensilvania, si encuentra una ráfaga de nieve, baje la velocidad poco a poco, encienda las luces de emergencia y no frene de golpe.","p":"Correcto. Baje poco a poco y use las luces de emergencia."},"ref":{"doc":"PA","page":43}},{"id":"pa-116","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, why should you not move into a center left-turn lane too early?","o":["It is only for buses","You must stay in it for at least one block","It makes your turn signal stop working","You are more likely to meet a car head-on coming the other way"],"h1":"Drivers from both directions use this lane.","h2":"In Pennsylvania, you should not enter a center turn lane too soon, because the longer you drive in it, the more likely you are to meet someone head-on.","p":"Right. The longer you drive in it, the bigger the head-on risk."},"es":{"q":"En Pensilvania, ¿por qué no debe entrar demasiado pronto a un carril central para dar vuelta a la izquierda?","o":["Es solo para autobuses","Debe quedarse en él por lo menos una cuadra","Hace que su direccional deje de funcionar","Es más probable encontrarse de frente con un auto que viene en sentido contrario"],"h1":"Conductores de los dos sentidos usan este carril.","h2":"En Pensilvania, no debe entrar demasiado pronto a un carril central de vuelta, porque mientras más tiempo maneje en él, más probable es encontrarse a alguien de frente.","p":"Correcto. Mientras más tiempo esté en él, mayor el riesgo de choque de frente."},"ref":{"doc":"PA","page":45}},{"id":"pa-117","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, where are U-turns not allowed, even with no sign?","o":["On a curve or near the top of a hill","On any two-lane road","On any street in daylight","Within 50 feet of a mailbox"],"h1":"Think about places where other drivers cannot see you in time.","h2":"In Pennsylvania, U-turns are not allowed on curves or when you are approaching or near the crest of a hill.","p":"Right. No U-turns on curves or near the top of a hill."},"es":{"q":"En Pensilvania, ¿dónde no se permiten las vueltas en U, aunque no haya letrero?","o":["En una curva o cerca de la cima de una colina","En cualquier camino de dos carriles","En cualquier calle de día","A menos de 50 pies de un buzón"],"h1":"Piense en lugares donde otros conductores no lo pueden ver a tiempo.","h2":"En Pensilvania, no se permiten las vueltas en U en curvas ni cuando se acerca o está cerca de la cima de una colina.","p":"Correcto. No hay vueltas en U en curvas ni cerca de la cima de una colina."},"ref":{"doc":"PA","page":46}},{"id":"pa-118","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, you are crossing a busy street. When is it safe to stop halfway across?","o":["Whenever traffic comes from the left","Only when a turning lane in the center median is big enough to hold your whole vehicle","Any time your hazard lights are on","Never, even if there is a large median lane"],"h1":"Your car must not stick out into any lane of traffic.","h2":"In Pennsylvania, stopping halfway across a street is safe only when there is a turning lane in the center median big enough to hold your entire vehicle.","p":"Right. Only if the median lane fits your whole vehicle."},"es":{"q":"En Pensilvania, usted cruza una calle con mucho tráfico. ¿Cuándo es seguro detenerse a la mitad?","o":["Siempre que vengan autos por la izquierda","Solo cuando hay un carril de vuelta en la mediana central lo bastante grande para todo su vehículo","Cuando tenga encendidas las luces de emergencia","Nunca, aunque haya un carril grande en la mediana"],"h1":"Su auto no debe quedar dentro de ningún carril de tráfico.","h2":"En Pensilvania, detenerse a la mitad de una calle solo es seguro cuando hay un carril de vuelta en la mediana central lo bastante grande para todo su vehículo.","p":"Correcto. Solo si el carril de la mediana cabe todo su vehículo."},"ref":{"doc":"PA","page":46}},{"id":"pa-119","scope":"PA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Pennsylvania, you want to pass a slower vehicle on a two-lane road at 45 mph. About how much clear road do you need?","o":["About 100 feet","About one car length","About a quarter of a mile","About 3 miles"],"h1":"You will be in the lane of oncoming traffic for a while.","h2":"In Pennsylvania, to pass safely on a two-lane road at 45 mph, you need about a quarter of a mile of clear road.","p":"Right. About a quarter of a mile at 45 mph."},"es":{"q":"En Pensilvania, usted quiere rebasar a un vehículo más lento en un camino de dos carriles a 45 mph. ¿Más o menos cuánto camino libre necesita?","o":["Como 100 pies","Como el largo de un auto","Como un cuarto de milla","Como 3 millas"],"h1":"Estará un buen rato en el carril del tráfico que viene de frente.","h2":"En Pensilvania, para rebasar con seguridad en un camino de dos carriles a 45 mph, necesita como un cuarto de milla de camino libre.","p":"Correcto. Como un cuarto de milla a 45 mph."},"ref":{"doc":"PA","page":47}},{"id":"pa-120","scope":"PA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Pennsylvania, you are about to turn right onto a street. How big a gap should you allow from any vehicle coming from your left?","o":["About 2 seconds","About 4 seconds","About 15 seconds","About 8 seconds"],"h1":"It is a little more than the gap needed to cross a 30 mph street.","h2":"In Pennsylvania, when you turn right, allow a gap of about 8 seconds between you and any vehicle approaching from the left.","p":"Right. Allow about 8 seconds."},"es":{"q":"En Pensilvania, usted va a dar vuelta a la derecha hacia una calle. ¿Qué espacio de tiempo debe dejar con cualquier vehículo que viene por su izquierda?","o":["Unos 2 segundos","Unos 4 segundos","Unos 15 segundos","Unos 8 segundos"],"h1":"Es un poco más que el espacio que necesita para cruzar una calle de 30 mph.","h2":"En Pensilvania, al dar vuelta a la derecha, deje un espacio de unos 8 segundos entre usted y cualquier vehículo que viene por la izquierda.","p":"Correcto. Deje unos 8 segundos."},"ref":{"doc":"PA","page":49}},{"id":"pa-121","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, you are turning left from a minor street onto a major street. How big a gap should you allow from any vehicle coming from your right?","o":["About 9 seconds","About 3 seconds","About 5 seconds","About 20 seconds"],"h1":"A left turn takes longer than a right turn, so you need a bit more than for a right turn.","h2":"In Pennsylvania, when turning left from a minor street onto a major street, allow a gap of about 9 seconds from any vehicle approaching from the right.","p":"Right. Allow about 9 seconds."},"es":{"q":"En Pensilvania, usted da vuelta a la izquierda desde una calle menor hacia una calle principal. ¿Qué espacio de tiempo debe dejar con cualquier vehículo que viene por su derecha?","o":["Unos 9 segundos","Unos 3 segundos","Unos 5 segundos","Unos 20 segundos"],"h1":"Una vuelta a la izquierda toma más tiempo, así que necesita un poco más que para una vuelta a la derecha.","h2":"En Pensilvania, al dar vuelta a la izquierda desde una calle menor hacia una principal, deje un espacio de unos 9 segundos con cualquier vehículo que viene por la derecha.","p":"Correcto. Deje unos 9 segundos."},"ref":{"doc":"PA","page":49}},{"id":"pa-122","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, how far ahead does the manual say you should be able to spot problems while you drive?","o":["2 to 3 seconds ahead","12 to 15 seconds ahead","Only the car right in front of you","1 minute ahead"],"h1":"In the city this is about one block.","h2":"In Pennsylvania, you should be able to identify problems 12 to 15 seconds ahead, about one block in the city or a quarter of a mile on the highway.","p":"Right. Look 12 to 15 seconds ahead."},"es":{"q":"En Pensilvania, según el manual, ¿con cuánta anticipación debe poder ver los problemas mientras maneja?","o":["De 2 a 3 segundos adelante","De 12 a 15 segundos adelante","Solo el auto que va justo delante","1 minuto adelante"],"h1":"En la ciudad, esto es como una cuadra.","h2":"En Pensilvania, debe poder identificar problemas de 12 a 15 segundos adelante, como una cuadra en la ciudad o un cuarto de milla en la carretera.","p":"Correcto. Mire de 12 a 15 segundos adelante."},"ref":{"doc":"PA","page":37}},{"id":"pa-123","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, you must stop and park on the roadway itself. Besides using your four-way flashers, what does the manual require?","o":["You must leave the engine running","You must park facing traffic","Your vehicle must be visible from at least 500 feet in both directions","You must stay no more than 5 minutes"],"h1":"Other drivers must be able to see you from far away.","h2":"In Pennsylvania, when you must park on the roadway, use your four-way flashers, leave room for passing vehicles and make sure your vehicle can be seen from at least 500 feet in both directions.","p":"Right. It must be visible from 500 feet both ways."},"es":{"q":"En Pensilvania, usted tiene que detenerse y estacionarse en la misma calzada. Además de usar las luces intermitentes de emergencia, ¿qué exige el manual?","o":["Que deje el motor encendido","Que se estacione de frente al tráfico","Que su vehículo se vea desde al menos 500 pies en ambas direcciones","Que no se quede más de 5 minutos"],"h1":"Los demás conductores deben poder verlo desde lejos.","h2":"En Pensilvania, si tiene que estacionarse en la calzada, use las luces intermitentes de emergencia, deje espacio para los vehículos que pasan y asegúrese de que su vehículo se vea desde al menos 500 pies en ambas direcciones.","p":"Correcto. Debe verse desde 500 pies en ambas direcciones."},"ref":{"doc":"PA","page":52}},{"id":"pa-124","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you park facing downhill next to a curb. Which way should you turn your steering wheel?","o":["To the left, away from the curb","Keep the wheels straight","It does not matter with the parking brake on","To the right, toward the curb"],"h1":"If the car rolls, the front wheels should stop against the curb.","h2":"In Pennsylvania, when you park downhill, with or without a curb, turn your steering wheel so the wheels point completely to the right.","p":"Right. Downhill, turn the wheels to the right, toward the curb."},"es":{"q":"En Pensilvania, usted se estaciona cuesta abajo junto a la acera. ¿Hacia dónde debe girar el volante?","o":["A la izquierda, lejos de la acera","Dejar las ruedas derechas","No importa si usa el freno de mano","A la derecha, hacia la acera"],"h1":"Si el auto rueda, las ruedas delanteras deben detenerse contra la acera.","h2":"En Pensilvania, cuando se estaciona cuesta abajo, con o sin acera, gire el volante para que las ruedas apunten completamente a la derecha.","p":"Correcto. Cuesta abajo, gire las ruedas a la derecha, hacia la acera."},"ref":{"doc":"PA","page":52}},{"id":"pa-125","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, how close to the driveway entrance of a fire station may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 100 feet","Right next to it, if you stay in the car"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In Pennsylvania, you may not park within 20 feet of a driveway entrance to a fire station.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Pensilvania, ¿qué tan cerca de la entrada de vehículos de una estación de bomberos puede estacionarse?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 100 pies","Justo al lado, si se queda en el auto"],"h1":"Es la misma distancia que de un cruce peatonal en una intersección.","h2":"En Pensilvania, no puede estacionarse a menos de 20 pies de la entrada de vehículos de una estación de bomberos.","p":"Correcto. Quédese al menos a 20 pies."},"ref":{"doc":"PA","page":53}},{"id":"pa-126","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, a loaded truck with good brakes is going 65 mph on a dry road. About how far does it need to stop, compared with about 400 feet for a car?","o":["About 200 feet","At least 600 feet","About 400 feet, the same as a car","About 100 feet"],"h1":"A heavy truck needs more room than a car, not less.","h2":"In Pennsylvania, a loaded truck at 65 mph on a dry road needs at least 600 feet to stop, compared with about 400 feet for a passenger vehicle.","p":"Right. The truck needs at least 600 feet."},"es":{"q":"En Pensilvania, un camión cargado con buenos frenos va a 65 mph en un camino seco. ¿Más o menos qué distancia necesita para detenerse, comparado con unos 400 pies para un auto?","o":["Unos 200 pies","Al menos 600 pies","Unos 400 pies, igual que un auto","Unos 100 pies"],"h1":"Un camión pesado necesita más espacio que un auto, no menos.","h2":"En Pensilvania, un camión cargado a 65 mph en camino seco necesita al menos 600 pies para detenerse, comparado con unos 400 pies para un vehículo de pasajeros.","p":"Correcto. El camión necesita al menos 600 pies."},"ref":{"doc":"PA","page":58}},{"id":"pa-127","scope":"PA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Pennsylvania, a school bus ahead has stopped with red lights flashing and its stop arm out. How far away from the bus must you stop?","o":["At least 3 feet","At least 50 feet","At least 10 feet","At least 100 feet"],"h1":"It is about the length of two adults lying end to end.","h2":"In Pennsylvania, you must stop at least 10 feet away from a school bus that has its red lights flashing and stop arm extended.","p":"Right. Stop at least 10 feet from the bus."},"es":{"q":"En Pensilvania, un autobús escolar adelante se detuvo con las luces rojas intermitentes y el brazo de alto extendido. ¿A qué distancia del autobús debe detenerse?","o":["Al menos a 3 pies","Al menos a 50 pies","Al menos a 10 pies","Al menos a 100 pies"],"h1":"Es como el largo de dos adultos acostados uno tras otro.","h2":"En Pensilvania, debe detenerse al menos a 10 pies de un autobús escolar que tiene las luces rojas intermitentes y el brazo de alto extendido.","p":"Correcto. Deténgase al menos a 10 pies del autobús."},"ref":{"doc":"PA","page":58}},{"id":"pa-128","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, you must avoid a sudden hazard at 40 mph. You can brake or steer around it. What does the manual say is usually better?","o":["Braking hard, always","Steering around it, because you react faster when you swerve","Honking and keeping the same speed","Speeding up to get past it"],"h1":"Above 25 mph, one of these takes less reaction time.","h2":"In Pennsylvania, when you can choose, steering to avoid a hazard is usually better than braking, especially above 25 mph, because your reaction time to swerve is faster.","p":"Right. Above 25 mph, steering is usually better."},"es":{"q":"En Pensilvania, a 40 mph debe evitar un peligro repentino. Puede frenar o esquivarlo con el volante. ¿Qué dice el manual que suele ser mejor?","o":["Frenar fuerte, siempre","Esquivarlo con el volante, porque reacciona más rápido al girar","Tocar la bocina y seguir a la misma velocidad","Acelerar para pasarlo"],"h1":"Arriba de 25 mph, una de estas acciones toma menos tiempo de reacción.","h2":"En Pensilvania, cuando puede elegir, esquivar un peligro con el volante suele ser mejor que frenar, sobre todo arriba de 25 mph, porque su tiempo de reacción para girar es más rápido.","p":"Correcto. Arriba de 25 mph, esquivar suele ser mejor."},"ref":{"doc":"PA","page":60}},{"id":"pa-129","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, the manual warns about flooded roads. How deep must water be to carry away most vehicles, even SUVs?","o":["About 1 inch","About 3 inches","About 2 feet","About 6 feet"],"h1":"It is measured in feet, but it is still not very deep.","h2":"In Pennsylvania, the manual warns that 2 feet of water will carry away most vehicles, including SUVs, so never drive into a flooded road.","p":"Right. About 2 feet of water can carry away most vehicles."},"es":{"q":"En Pensilvania, el manual advierte sobre caminos inundados. ¿Qué profundidad de agua puede arrastrar a la mayoría de los vehículos, incluso las camionetas SUV?","o":["Una pulgada","Unas 3 pulgadas","Unos 2 pies","Unos 6 pies"],"h1":"Se mide en pies, pero aun así no es muy profundo.","h2":"En Pensilvania, el manual advierte que 2 pies de agua arrastran a la mayoría de los vehículos, incluidas las SUV, así que nunca maneje por un camino inundado.","p":"Correcto. Unos 2 pies de agua pueden arrastrar a la mayoría de los vehículos."},"ref":{"doc":"PA","page":62}},{"id":"pa-130","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, your right wheels drop off the pavement onto a low shoulder. How slow should you get before you steer back onto the road?","o":["Below 50 mph","You should not slow down; steer back right away","You must come to a full stop first","Below 25 mph, and closer to 10 mph if possible"],"h1":"Ease off the gas and slow down gradually first.","h2":"In Pennsylvania, if you drift off the pavement, slow gradually to less than 25 mph, preferably closer to 10 mph, before you gently steer back onto the road.","p":"Right. Slow below 25 mph, ideally near 10 mph, then steer back gently."},"es":{"q":"En Pensilvania, sus ruedas derechas se salen del pavimento a un acotamiento más bajo. ¿Qué tan despacio debe ir antes de volver al camino?","o":["A menos de 50 mph","No debe bajar la velocidad; vuelva de inmediato","Primero debe parar por completo","A menos de 25 mph, y si puede cerca de 10 mph"],"h1":"Primero quite el pie del acelerador y baje la velocidad poco a poco.","h2":"En Pensilvania, si se sale del pavimento, baje poco a poco a menos de 25 mph, mejor cerca de 10 mph, antes de volver con suavidad al camino.","p":"Correcto. Baje a menos de 25 mph, mejor cerca de 10 mph, y vuelva con suavidad."},"ref":{"doc":"PA","page":64}},{"id":"pa-131","scope":"PA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Pennsylvania, how can you tell that a car is part of a funeral procession?","o":["Its headlights and emergency flashers are on, and it has a flag or other sign","It drives with all its lights off","It always has a police car right behind it","It drives faster than other traffic"],"h1":"The cars use their lights and a marker to show they belong together.","h2":"In Pennsylvania, all vehicles in a funeral procession must have their headlights and emergency flashers on and carry a flag or other insignia; they may also show a flashing purple light.","p":"Right. Headlights, flashers and a flag or other sign."},"es":{"q":"En Pensilvania, ¿cómo puede saber que un auto es parte de un cortejo fúnebre?","o":["Tiene encendidos los faros y las luces intermitentes de emergencia, y lleva una bandera u otra señal","Maneja con todas las luces apagadas","Siempre tiene una patrulla justo detrás","Maneja más rápido que el resto del tráfico"],"h1":"Los autos usan sus luces y una señal para mostrar que van juntos.","h2":"En Pensilvania, todos los vehículos de un cortejo fúnebre deben llevar encendidos los faros y las luces intermitentes de emergencia y una bandera u otra insignia; también pueden llevar una luz morada intermitente.","p":"Correcto. Faros, luces intermitentes y una bandera u otra señal."},"ref":{"doc":"PA","page":64}},{"id":"pa-132","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, your license was suspended and is now restored. How many points will your driving record show, in most cases?","o":["0 points","5 points","The same points you had before","11 points"],"h1":"It does not matter how many points you had before the suspension.","h2":"In Pennsylvania, after your driving privilege is restored, your record shows 5 points in most cases, no matter how many points you had before.","p":"Right. In most cases, your record restarts at 5 points."},"es":{"q":"En Pensilvania, le suspendieron la licencia y ahora se la devolvieron. ¿Cuántos puntos mostrará su récord, en la mayoría de los casos?","o":["0 puntos","5 puntos","Los mismos puntos que tenía antes","11 puntos"],"h1":"No importa cuántos puntos tenía antes de la suspensión.","h2":"En Pensilvania, después de que le devuelven el privilegio de manejar, su récord muestra 5 puntos en la mayoría de los casos, sin importar cuántos tenía antes.","p":"Correcto. En la mayoría de los casos, su récord vuelve a 5 puntos."},"ref":{"doc":"PA","page":80}},{"id":"pa-133","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, PennDOT mails you a notice that your license will be suspended. How long do you have to appeal in court?","o":["5 days","6 months","30 days from the mailing date of the notice","There is no right to appeal"],"h1":"It is about one month.","h2":"In Pennsylvania, you may appeal a suspension in the Court of Common Pleas in your county, and the appeal must be filed within 30 days of the mailing date of PennDOT's notice.","p":"Right. You have 30 days from the mailing date."},"es":{"q":"En Pensilvania, PennDOT le envía por correo un aviso de que su licencia será suspendida. ¿Cuánto tiempo tiene para apelar ante el tribunal?","o":["5 días","6 meses","30 días desde la fecha de envío del aviso","No hay derecho a apelar"],"h1":"Es como un mes.","h2":"En Pensilvania, puede apelar una suspensión en el Tribunal de Causas Comunes (Court of Common Pleas) de su condado, y la apelación debe presentarse dentro de los 30 días desde la fecha de envío del aviso de PennDOT.","p":"Correcto. Tiene 30 días desde la fecha de envío."},"ref":{"doc":"PA","page":80}},{"id":"pa-134","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, a car with flashing red lights signals you to pull over at night on a dark road. You are not sure it is really the police. What may you do?","o":["Speed up to get away from it","Ignore it and keep driving normally","Stop right away and get out of your car","Turn on your flashers, drive slowly and go to the nearest well-lit, busy area"],"h1":"Show that you understand, but find a safe, lighted place with people around.","h2":"In Pennsylvania, if you are not sure the vehicle stopping you is the police, you may turn on your flashers, drive at a reduced speed and go to the nearest well-lit, populated area before stopping.","p":"Right. Use your flashers, drive slowly and stop in a well-lit, busy place."},"es":{"q":"En Pensilvania, de noche en un camino oscuro, un auto con luces rojas intermitentes le indica que se detenga. Usted no está seguro de que sea la policía. ¿Qué puede hacer?","o":["Acelerar para alejarse","Ignorarlo y seguir manejando normal","Parar de inmediato y bajarse del auto","Encender las luces intermitentes, manejar despacio e ir al lugar más cercano bien iluminado y con gente"],"h1":"Muestre que entendió, pero busque un lugar seguro, iluminado y con gente.","h2":"En Pensilvania, si no está seguro de que quien lo detiene sea la policía, puede encender las luces intermitentes, manejar a menor velocidad e ir al lugar más cercano bien iluminado y con gente antes de detenerse.","p":"Correcto. Use las intermitentes, maneje despacio y pare en un lugar iluminado y con gente."},"ref":{"doc":"PA","page":81}},{"id":"pa-135","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, police stop you at night. What do police recommend you do before the officer walks up?","o":["Turn on your car's inside light","Get out and walk to the police car","Look for your papers under the seat","Unbuckle your seat belt"],"h1":"Help the officer see inside your car.","h2":"In Pennsylvania, if police stop you at night, turn on your interior light before the officer approaches, keep your seat belt on and keep your hands on the wheel.","p":"Right. Turn on the inside light."},"es":{"q":"En Pensilvania, la policía lo detiene de noche. ¿Qué recomienda la policía que haga antes de que el agente se acerque?","o":["Encender la luz interior del auto","Bajarse y caminar hasta la patrulla","Buscar sus papeles debajo del asiento","Quitarse el cinturón de seguridad"],"h1":"Ayude al agente a ver dentro de su auto.","h2":"En Pensilvania, si la policía lo detiene de noche, encienda la luz interior antes de que el agente se acerque, mantenga puesto el cinturón y las manos en el volante.","p":"Correcto. Encienda la luz interior."},"ref":{"doc":"PA","page":80}},{"id":"pa-136","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, an adult is convicted of a first DUI with a BAC of 0.08 to 0.099 (general impairment). What happens to the license?","o":["A 12-month suspension","No license suspension","An 18-month suspension","It is taken away for life"],"h1":"This lowest level brings probation and a fine instead.","h2":"In Pennsylvania, a first DUI at the general impairment level (0.08 to 0.099 BAC) brings 6 months of probation and a $300 fine, with no license action.","p":"Right. No license action for a first general-impairment DUI, but there is probation and a fine."},"es":{"q":"En Pensilvania, un adulto es condenado por un primer DUI con un BAC de 0.08 a 0.099 (deterioro general). ¿Qué pasa con su licencia?","o":["Una suspensión de 12 meses","No se suspende la licencia","Una suspensión de 18 meses","Se la quitan de por vida"],"h1":"Este nivel más bajo trae libertad condicional y una multa en su lugar.","h2":"En Pensilvania, un primer DUI en el nivel de deterioro general (BAC de 0.08 a 0.099) trae 6 meses de libertad condicional y una multa de $300, sin acción sobre la licencia.","p":"Correcto. No hay acción sobre la licencia en un primer DUI de deterioro general, pero sí libertad condicional y multa."},"ref":{"doc":"PA","page":83}},{"id":"pa-137","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, an adult knowingly gives alcohol to a person under 21. What is the lowest fine for a first offense?","o":["$25","$100","$1,000","$300"],"h1":"Each additional minor costs $2,500.","h2":"In Pennsylvania, an adult convicted of knowingly supplying alcohol to minors faces a fine of at least $1,000 for the first offense, $2,500 for each additional one, and up to a year in jail.","p":"Right. At least $1,000 for the first offense."},"es":{"q":"En Pensilvania, un adulto le da alcohol a sabiendas a una persona menor de 21 años. ¿Cuál es la multa mínima por una primera infracción?","o":["$25","$100","$1,000","$300"],"h1":"Cada menor adicional cuesta $2,500.","h2":"En Pensilvania, un adulto condenado por dar alcohol a sabiendas a menores recibe una multa de al menos $1,000 por la primera infracción, $2,500 por cada una adicional y hasta un año de cárcel.","p":"Correcto. Al menos $1,000 por la primera infracción."},"ref":{"doc":"PA","page":84}},{"id":"pa-138","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you park in a space for persons with disabilities without the right plate or placard. What fine can you face?","o":["$5 to $10","$1,000 to $5,000","No fine, only a warning","$50 to $200"],"h1":"Your car may also be towed at your cost.","h2":"In Pennsylvania, parking illegally in a space for persons with disabilities is a summary offense with a fine of $50 to $200, and the vehicle may be towed.","p":"Right. $50 to $200, and you may be towed."},"es":{"q":"En Pensilvania, usted se estaciona en un espacio para personas con discapacidad sin la placa o el permiso correcto. ¿Qué multa puede recibir?","o":["De $5 a $10","De $1,000 a $5,000","Ninguna multa, solo una advertencia","De $50 a $200"],"h1":"Además, su auto puede ser remolcado y usted paga el costo.","h2":"En Pensilvania, estacionarse ilegalmente en un espacio para personas con discapacidad es una infracción menor con multa de $50 a $200, y el vehículo puede ser remolcado.","p":"Correcto. De $50 a $200, y lo pueden remolcar."},"ref":{"doc":"PA","page":92}},{"id":"pa-139","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, a police officer notices a broken part on your car, such as a taillight. How soon may you be required to fix it to avoid a citation?","o":["Within 5 days","Within 1 hour","Within 60 days","At your next yearly inspection"],"h1":"It is less than a week.","h2":"In Pennsylvania, if a police officer notices faulty equipment on your vehicle, you may be required to fix it within 5 days to avoid a citation.","p":"Right. You may have 5 days to fix it."},"es":{"q":"En Pensilvania, un policía nota una pieza dañada en su auto, como una luz trasera. ¿En cuánto tiempo pueden exigirle que la arregle para evitar una multa?","o":["En 5 días","En 1 hora","En 60 días","En su próxima inspección anual"],"h1":"Es menos de una semana.","h2":"En Pensilvania, si un policía nota equipo defectuoso en su vehículo, pueden exigirle que lo arregle en 5 días para evitar una multa.","p":"Correcto. Puede tener 5 días para arreglarlo."},"ref":{"doc":"PA","page":92}},{"id":"pa-140","scope":"PA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Pennsylvania, you are passing a bicycle on a road with a double yellow center line. You cannot keep 4 feet of space in your lane. What does the law allow?","o":["You may pass with less space if you honk first","You may cross the double yellow line, if it is safe, to keep 4 feet of space","You may never cross the line, so pass closer","You must use the shoulder to pass"],"h1":"The 4-foot rule matters so much that the law makes an exception.","h2":"In Pennsylvania, if necessary and safe, you may cross the double yellow center line to keep at least 4 feet between your vehicle and a bicycle you are passing.","p":"Right. If it is safe, you may cross the double yellow to keep 4 feet."},"es":{"q":"En Pensilvania, usted rebasa a una bicicleta en un camino con doble línea amarilla en el centro. No puede dejar 4 pies de espacio dentro de su carril. ¿Qué permite la ley?","o":["Puede rebasar con menos espacio si toca la bocina antes","Puede cruzar la doble línea amarilla, si es seguro, para dejar 4 pies de espacio","Nunca puede cruzar la línea, así que rebase más cerca","Debe usar el acotamiento para rebasar"],"h1":"La regla de 4 pies es tan importante que la ley hace una excepción.","h2":"En Pensilvania, si es necesario y seguro, puede cruzar la doble línea amarilla central para dejar al menos 4 pies entre su vehículo y la bicicleta que rebasa.","p":"Correcto. Si es seguro, puede cruzar la doble línea amarilla para dejar 4 pies."},"ref":{"doc":"PA","page":92}},{"id":"pa-141","scope":"PA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Pennsylvania, you are about to open your car door on a street where bicycles ride. Which hand does the manual suggest you use?","o":["The hand closer to the door","Either hand, as long as you open it fast","The hand farther from the door","Neither; always open it with your foot"],"h1":"This method makes your body turn so you can look back.","h2":"In Pennsylvania, the manual suggests the Dutch Reach: check your mirrors, then open the door with your far hand so you turn and can see bicycles coming.","p":"Right. Use your far hand, the Dutch Reach."},"es":{"q":"En Pensilvania, usted va a abrir la puerta de su auto en una calle donde pasan bicicletas. ¿Qué mano sugiere el manual que use?","o":["La mano más cercana a la puerta","Cualquier mano, si la abre rápido","La mano más lejana a la puerta","Ninguna; ábrala siempre con el pie"],"h1":"Este método hace que su cuerpo gire para que pueda mirar hacia atrás.","h2":"En Pensilvania, el manual sugiere el método Dutch Reach: revise los espejos y abra la puerta con la mano más lejana, para girar y ver las bicicletas que vienen.","p":"Correcto. Use la mano más lejana, el Dutch Reach."},"ref":{"doc":"PA","page":93}},{"id":"pa-142","scope":"PA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Pennsylvania, you hit a parked car and cannot find the owner. What must you do?","o":["Drive away, since no one was hurt","Wait at the car for up to 24 hours","Only tell your own insurance company","Leave a note where it can be seen, with your name and phone number, and call the police"],"h1":"The owner must be able to reach you, and the police must know.","h2":"In Pennsylvania, if you hit a parked vehicle and cannot find the owner, leave a note where it can be seen with the date, time, your name and a phone number, and call the police.","p":"Right. Leave a note and call the police."},"es":{"q":"En Pensilvania, usted choca con un auto estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse, ya que nadie se lastimó","Esperar junto al auto hasta 24 horas","Avisar solo a su propia compañía de seguros","Dejar una nota visible con su nombre y teléfono, y llamar a la policía"],"h1":"El dueño debe poder comunicarse con usted, y la policía debe saberlo.","h2":"En Pensilvania, si choca con un vehículo estacionado y no encuentra al dueño, deje una nota visible con la fecha, la hora, su nombre y un teléfono, y llame a la policía.","p":"Correcto. Deje una nota y llame a la policía."},"ref":{"doc":"PA","page":81}},{"id":"pa-143","scope":"PA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Pennsylvania, how must a child under age 2 ride in a car?","o":["In a rear-facing car seat, until the child outgrows its weight and height limits","In a forward-facing seat in the front","In a booster seat with a lap belt","On an adult's lap with a seat belt around both"],"h1":"The child faces the back of the car.","h2":"In Pennsylvania, children younger than 2 must ride in a rear-facing car seat until they outgrow the seat maker's weight and height limits.","p":"Right. Under 2, the child rides rear-facing."},"es":{"q":"En Pensilvania, ¿cómo debe viajar en un auto un niño menor de 2 años?","o":["En un asiento de seguridad mirando hacia atrás, hasta que pase los límites de peso y estatura del asiento","En un asiento mirando hacia adelante en el frente","En un asiento elevado (booster) con cinturón de cadera","En las piernas de un adulto con un cinturón alrededor de los dos"],"h1":"El niño mira hacia la parte trasera del auto.","h2":"En Pensilvania, los niños menores de 2 años deben viajar en un asiento de seguridad mirando hacia atrás hasta que pasen los límites de peso y estatura del fabricante.","p":"Correcto. Menores de 2 años viajan mirando hacia atrás."},"ref":{"doc":"PA","page":90}},{"id":"pa-144","scope":"PA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Pennsylvania, which adults does the seat belt law require to buckle up?","o":["Only the driver","All drivers and front-seat passengers","Only passengers in the back seat","Only people on highways"],"h1":"Think of everyone in the front of the car.","h2":"In Pennsylvania, the seat belt law requires all drivers and front-seat passengers to wear seat belts, and passengers 8 to 17 must buckle up in any seat.","p":"Right. Drivers and front-seat passengers must buckle up."},"es":{"q":"En Pensilvania, ¿a qué adultos obliga la ley a usar el cinturón de seguridad?","o":["Solo al conductor","A todos los conductores y pasajeros del asiento delantero","Solo a los pasajeros del asiento trasero","Solo a quienes van en autopista"],"h1":"Piense en todos los que van en la parte delantera del auto.","h2":"En Pensilvania, la ley exige que todos los conductores y pasajeros del asiento delantero usen el cinturón, y los pasajeros de 8 a 17 años deben usarlo en cualquier asiento.","p":"Correcto. Conductores y pasajeros delanteros deben abrocharse."},"ref":{"doc":"PA","page":89}},{"id":"pa-145","scope":"PA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Pennsylvania, you report a name change to PennDOT. What do you get, and what must you do with it?","o":["A brand-new license, after a new road test","Nothing; you only tell the police","An update card, which you must carry with your license","A temporary permit good for 10 days"],"h1":"It is a small card, and there is no fee for it.","h2":"In Pennsylvania, after you report a name change, you get a driver's license update card with the new information, and you must carry it with your license.","p":"Right. Carry the update card with your license."},"es":{"q":"En Pensilvania, usted informa a PennDOT un cambio de nombre. ¿Qué recibe y qué debe hacer con eso?","o":["Una licencia nueva, después de otro examen de manejo","Nada; solo se le avisa a la policía","Una tarjeta de actualización, que debe llevar con su licencia","Un permiso temporal válido por 10 días"],"h1":"Es una tarjeta pequeña y no tiene costo.","h2":"En Pensilvania, después de informar un cambio de nombre, recibe una tarjeta de actualización de la licencia con los datos nuevos, y debe llevarla con su licencia.","p":"Correcto. Lleve la tarjeta de actualización con su licencia."},"ref":{"doc":"PA","page":89}},{"id":"pa-146","scope":"PA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Pennsylvania, a driver who has a prior DUI conviction refuses a chemical test and is then convicted of DUI again. How long is the total suspension?","o":["6 months","1 year","10 years","3 years"],"h1":"It is 18 months for the refusal plus 18 months for the DUI.","h2":"In Pennsylvania, a driver with a prior DUI or prior refusal who refuses a chemical test faces 18 months for the refusal plus 18 months for the DUI conviction, a total of 3 years.","p":"Right. 18 plus 18 months makes 3 years."},"es":{"q":"En Pensilvania, un conductor con una condena previa por DUI se niega a una prueba química y luego es condenado otra vez por DUI. ¿Cuánto dura la suspensión total?","o":["6 meses","1 año","10 años","3 años"],"h1":"Son 18 meses por la negativa más 18 meses por el DUI.","h2":"En Pensilvania, un conductor con un DUI o una negativa previa que se niega a una prueba química recibe 18 meses por la negativa más 18 meses por la condena de DUI, un total de 3 años.","p":"Correcto. 18 más 18 meses son 3 años."},"ref":{"doc":"PA","page":82}},{"id":"pa-147","scope":"PA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Pennsylvania, DUI penalties come in three levels. At what blood alcohol level does the \"highest rate\" begin?","o":["0.16 percent","0.02 percent","0.08 percent","0.30 percent"],"h1":"It is twice the adult legal limit.","h2":"In Pennsylvania, the highest rate of DUI impairment begins at a BAC of 0.16 percent, and it also applies to drivers who refuse chemical testing.","p":"Right. The highest rate starts at 0.16 percent."},"es":{"q":"En Pensilvania, las penas por DUI tienen tres niveles. ¿Con qué nivel de alcohol en la sangre empieza la \"tasa más alta\" (highest rate)?","o":["0.16 por ciento","0.02 por ciento","0.08 por ciento","0.30 por ciento"],"h1":"Es el doble del límite legal para adultos.","h2":"En Pensilvania, la tasa más alta de DUI empieza con un BAC de 0.16 por ciento, y también se aplica a quienes se niegan a la prueba química.","p":"Correcto. La tasa más alta empieza en 0.16 por ciento."},"ref":{"doc":"PA","page":83}},{"id":"pa-148","scope":"PA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Pennsylvania, you got a traffic ticket in another state and never responded to it. What happens to your Pennsylvania driving privilege?","o":["Nothing, because the ticket was out of state","It is suspended until you respond to the ticket","You only get 1 point","It is suspended for exactly 7 days"],"h1":"Under the Driver's License Compact, states share this information.","h2":"In Pennsylvania, not responding to an out-of-state citation leads to an indefinite suspension of your driving privilege until you respond.","p":"Right. It stays suspended until you respond."},"es":{"q":"En Pensilvania, usted recibió una multa de tránsito en otro estado y nunca respondió. ¿Qué pasa con su privilegio de manejar en Pensilvania?","o":["Nada, porque la multa fue en otro estado","Se suspende hasta que responda a la multa","Solo recibe 1 punto","Se suspende exactamente 7 días"],"h1":"Por el Acuerdo de Licencias de Conducir (Driver's License Compact), los estados comparten esta información.","h2":"En Pensilvania, no responder a una multa de otro estado lleva a una suspensión indefinida de su privilegio de manejar hasta que responda.","p":"Correcto. Sigue suspendido hasta que responda."},"ref":{"doc":"PA","page":85}},{"id":"ri-001","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the youngest age to get a limited instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"Rhode Island starts later than many states.","h2":"In Rhode Island you can get a limited instruction permit at 16 years old.","p":"Right. The Rhode Island permit starts at 16."},"es":{"q":"En Rhode Island, ¿cuál es la edad mínima para obtener un permiso de instrucción limitado?","o":["14 años","15 años","16 años","17 años"],"h1":"Rhode Island empieza más tarde que muchos estados.","h2":"En Rhode Island usted puede obtener un permiso de instrucción limitado a los 16 años.","p":"Correcto. El permiso en Rhode Island empieza a los 16."},"zh":{"q":"在 Rhode Island，最小几岁可以拿到受限学习驾照（limited instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"Rhode Island 开始得比很多州晚。","h2":"在 Rhode Island，你 16 岁就可以拿到受限学习驾照。","p":"对。Rhode Island 的学习驾照从 16 岁开始。"},"vi":{"q":"Ở Rhode Island, tuổi nhỏ nhất để lấy giấy phép tập lái có giới hạn (limited instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Rhode Island bắt đầu muộn hơn nhiều tiểu bang khác.","h2":"Ở Rhode Island, bạn có thể lấy giấy phép tập lái có giới hạn khi 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Rhode Island bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Rhode Island, ano ang pinakabatang edad para makakuha ng limited instruction permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Mas huli nagsisimula ang Rhode Island kaysa sa maraming estado.","h2":"Sa Rhode Island, puwede kang kumuha ng limited instruction permit sa edad na 16.","p":"Tama. Nagsisimula ang permit sa Rhode Island sa edad na 16."},"ar":{"q":"في Rhode Island، ما أصغر عمر للحصول على تصريح تعلّم محدود (limited instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"تبدأ Rhode Island في عمر أكبر من ولايات كثيرة.","h2":"في Rhode Island يمكنك الحصول على تصريح تعلّم محدود في عمر 16 سنة.","p":"صحيح. يبدأ التصريح في Rhode Island في عمر 16 سنة."},"ref":{"doc":"RI","page":10}},{"id":"ri-002","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how long is the driver education course a teen must finish for a permit?","o":["10 hours","33 hours","6 hours","100 hours"],"h1":"It is a little more than thirty hours.","h2":"A Rhode Island teen must complete a 33-hour driver education course to qualify for a limited instruction permit.","p":"Right. The course is 33 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas dura el curso de educación vial que un adolescente debe terminar para el permiso?","o":["10 horas","33 horas","6 horas","100 horas"],"h1":"Son un poco más de treinta horas.","h2":"Un adolescente en Rhode Island debe completar un curso de educación vial de 33 horas para obtener el permiso de instrucción limitado.","p":"Correcto. El curso es de 33 horas."},"zh":{"q":"在 Rhode Island，青少年为了拿学习驾照，必须完成多长的驾驶教育课程？","o":["10 小时","33 小时","6 小时","100 小时"],"h1":"它比三十小时多一点。","h2":"在 Rhode Island，青少年必须完成 33 小时的驾驶教育课程，才有资格拿受限学习驾照。","p":"对。这个课程是 33 小时。"},"vi":{"q":"Ở Rhode Island, khóa học lái xe mà thiếu niên phải hoàn thành để lấy giấy phép tập lái dài bao lâu?","o":["10 giờ","33 giờ","6 giờ","100 giờ"],"h1":"Nó hơn ba mươi giờ một chút.","h2":"Thiếu niên ở Rhode Island phải hoàn thành khóa học lái xe 33 giờ để đủ điều kiện lấy giấy phép tập lái có giới hạn.","p":"Đúng. Khóa học dài 33 giờ."},"tl":{"q":"Sa Rhode Island, gaano kahaba ang driver education course na dapat tapusin ng teenager para sa permit?","o":["10 oras","33 oras","6 na oras","100 oras"],"h1":"Medyo higit ito sa tatlumpung oras.","h2":"Ang teenager sa Rhode Island ay dapat tumapos ng 33 oras na driver education course para maging kwalipikado sa limited instruction permit.","p":"Tama. 33 oras ang course."},"ar":{"q":"في Rhode Island، كم مدة دورة تعليم القيادة التي يجب أن يكملها المراهق للحصول على التصريح؟","o":["10 ساعات","33 ساعة","6 ساعات","100 ساعة"],"h1":"هي أكثر قليلاً من ثلاثين ساعة.","h2":"يجب على المراهق في Rhode Island أن يكمل دورة تعليم قيادة مدتها 33 ساعة ليكون مؤهلاً للحصول على تصريح التعلّم المحدود.","p":"صحيح. مدة الدورة 33 ساعة."},"ref":{"doc":"RI","page":10}},{"id":"ri-003","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, where can a teen take the permit knowledge test?","o":["At any police station","Online at home","At the high school office","In the CCRI driver education course, or at the DMV in Cranston"],"h1":"One place is a college, the other is the DMV headquarters.","h2":"In Rhode Island the permit knowledge test is part of the CCRI driver education course; otherwise you take it at the DMV headquarters in Cranston.","p":"Right. CCRI or the Cranston DMV."},"es":{"q":"En Rhode Island, ¿dónde puede un adolescente presentar el examen de conocimientos para el permiso?","o":["En cualquier estación de policía","En línea desde la casa","En la oficina de la escuela secundaria","En el curso de educación vial de CCRI, o en el DMV de Cranston"],"h1":"Un lugar es un colegio comunitario y el otro es la sede del DMV.","h2":"En Rhode Island el examen de conocimientos para el permiso es parte del curso de educación vial de CCRI; si no, se presenta en la sede del DMV en Cranston.","p":"Correcto. CCRI o el DMV de Cranston."},"zh":{"q":"在 Rhode Island，青少年可以在哪里参加学习驾照的知识考试？","o":["在任何一个警察局","在家里上网考","在高中办公室","在 CCRI 驾驶教育课程里，或在 Cranston 的 DMV"],"h1":"一个地方是一所学院，另一个是 DMV 总部。","h2":"在 Rhode Island，学习驾照知识考试是 CCRI 驾驶教育课程的一部分；不然你要去 Cranston 的 DMV 总部考试。","p":"对。在 CCRI 或 Cranston 的 DMV。"},"vi":{"q":"Ở Rhode Island, thiếu niên có thể thi kiến thức để lấy giấy phép tập lái ở đâu?","o":["Ở bất kỳ đồn cảnh sát nào","Trên mạng tại nhà","Ở văn phòng trường trung học","Trong khóa học lái xe CCRI, hoặc tại DMV ở Cranston"],"h1":"Một nơi là trường cao đẳng, nơi kia là trụ sở DMV.","h2":"Ở Rhode Island, bài thi kiến thức để lấy giấy phép tập lái là một phần của khóa học lái xe CCRI; nếu không, bạn thi tại trụ sở DMV ở Cranston.","p":"Đúng. CCRI hoặc DMV ở Cranston."},"tl":{"q":"Sa Rhode Island, saan puwedeng kumuha ang teenager ng knowledge test para sa permit?","o":["Sa kahit anong police station","Online sa bahay","Sa opisina ng high school","Sa CCRI driver education course, o sa DMV sa Cranston"],"h1":"Ang isang lugar ay isang kolehiyo, ang isa ay ang punong-tanggapan ng DMV.","h2":"Sa Rhode Island, bahagi ng CCRI driver education course ang knowledge test para sa permit; kung hindi, kukunin mo ito sa punong-tanggapan ng DMV sa Cranston.","p":"Tama. Sa CCRI o sa DMV sa Cranston."},"ar":{"q":"في Rhode Island، أين يمكن للمراهق أن يؤدي اختبار المعرفة للحصول على التصريح؟","o":["في أي مركز شرطة","عبر الإنترنت في البيت","في مكتب المدرسة الثانوية","في دورة تعليم القيادة في CCRI، أو في DMV في Cranston"],"h1":"أحد المكانين كلية، والآخر هو المقر الرئيسي لـ DMV.","h2":"في Rhode Island يكون اختبار المعرفة للتصريح جزءاً من دورة تعليم القيادة في CCRI؛ وإلا فإنك تؤديه في المقر الرئيسي لـ DMV في Cranston.","p":"صحيح. في CCRI أو في DMV في Cranston."},"ref":{"doc":"RI","page":10}},{"id":"ri-004","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, who must come to the DMV to co-sign a teen's permit application?","o":["A parent, guardian or adult spouse","A teacher","Any adult friend","No one"],"h1":"It is an adult who is legally responsible for the teen.","h2":"In Rhode Island a parent, guardian or adult spouse must come to the DMV and co-sign the teen's permit application.","p":"Right. A parent, guardian or adult spouse signs too."},"es":{"q":"En Rhode Island, ¿quién debe ir al DMV a firmar junto con el adolescente la solicitud del permiso?","o":["Su padre, madre, tutor o cónyuge adulto","Un maestro","Cualquier amigo adulto","Nadie"],"h1":"Es un adulto que responde legalmente por el adolescente.","h2":"En Rhode Island su padre, madre, tutor o cónyuge adulto debe ir al DMV y firmar también la solicitud del permiso del adolescente.","p":"Correcto. Su padre, madre, tutor o cónyuge adulto también firma."},"zh":{"q":"在 Rhode Island，谁必须到 DMV 在青少年的学习驾照申请上共同签名？","o":["父母、监护人或成年配偶","老师","任何成年朋友","不需要任何人"],"h1":"这个人是对青少年负有法律责任的成年人。","h2":"在 Rhode Island，父母、监护人或成年配偶必须到 DMV，在青少年的学习驾照申请上共同签名。","p":"对。父母、监护人或成年配偶也要签名。"},"vi":{"q":"Ở Rhode Island, ai phải đến DMV để cùng ký đơn xin giấy phép tập lái của thiếu niên?","o":["Cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành","Một giáo viên","Bất kỳ người bạn trưởng thành nào","Không ai cả"],"h1":"Đó là một người lớn chịu trách nhiệm pháp lý cho thiếu niên.","h2":"Ở Rhode Island, cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành phải đến DMV và cùng ký đơn xin giấy phép tập lái của thiếu niên.","p":"Đúng. Cha mẹ, người giám hộ hoặc vợ/chồng đã trưởng thành cũng ký."},"tl":{"q":"Sa Rhode Island, sino ang dapat pumunta sa DMV para pumirma rin sa aplikasyon ng teenager para sa permit?","o":["Isang magulang, guardian, o asawang nasa hustong gulang","Isang guro","Kahit sinong kaibigang nasa hustong gulang","Wala"],"h1":"Isa itong adult na may legal na pananagutan sa teenager.","h2":"Sa Rhode Island, ang isang magulang, guardian, o asawang nasa hustong gulang ay dapat pumunta sa DMV at pumirma rin sa aplikasyon ng teenager para sa permit.","p":"Tama. Pumipirma rin ang magulang, guardian, o asawang nasa hustong gulang."},"ar":{"q":"في Rhode Island، من يجب أن يحضر إلى DMV ليوقّع مع المراهق على طلب التصريح؟","o":["أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ","معلّم","أي صديق بالغ","لا أحد"],"h1":"هو شخص بالغ مسؤول قانونياً عن المراهق.","h2":"في Rhode Island يجب أن يحضر أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ إلى DMV ويوقّع مع المراهق على طلب التصريح.","p":"صحيح. يوقّع أيضاً أحد الوالدين أو الوصي أو الزوج أو الزوجة البالغ."},"ref":{"doc":"RI","page":11}},{"id":"ri-005","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, how long must a teen hold the instruction permit before a limited provisional license?","o":["30 days","3 months","6 months","1 year"],"h1":"It is half a year.","h2":"A Rhode Island teen must hold the instruction permit for at least six months before applying for a limited provisional license.","p":"Right. You hold the permit six months."},"es":{"q":"En Rhode Island, ¿cuánto tiempo debe tener un adolescente el permiso de instrucción antes de la licencia provisional limitada?","o":["30 días","3 meses","6 meses","1 año"],"h1":"Es medio año.","h2":"Un adolescente en Rhode Island debe tener el permiso de instrucción por lo menos seis meses antes de solicitar la licencia provisional limitada.","p":"Correcto. Tiene el permiso seis meses."},"zh":{"q":"在 Rhode Island，青少年拿受限试用驾照（limited provisional license）前，必须持有学习驾照多久？","o":["30 天","3 个月","6 个月","1 年"],"h1":"它是半年。","h2":"在 Rhode Island，青少年必须持有学习驾照至少六个月，才能申请受限试用驾照。","p":"对。学习驾照要持有六个月。"},"vi":{"q":"Ở Rhode Island, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái tạm thời có giới hạn (limited provisional license)?","o":["30 ngày","3 tháng","6 tháng","1 năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Rhode Island phải giữ giấy phép tập lái ít nhất sáu tháng trước khi xin bằng lái tạm thời có giới hạn.","p":"Đúng. Bạn giữ giấy phép tập lái sáu tháng."},"tl":{"q":"Sa Rhode Island, gaano katagal dapat hawak ng teenager ang instruction permit bago makakuha ng limited provisional license?","o":["30 araw","3 buwan","6 na buwan","1 taon"],"h1":"Kalahating taon ito.","h2":"Ang teenager sa Rhode Island ay dapat humawak ng instruction permit nang hindi bababa sa anim na buwan bago mag-apply para sa limited provisional license.","p":"Tama. Hawak mo ang permit nang anim na buwan."},"ar":{"q":"في Rhode Island، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على رخصة مؤقتة محدودة (limited provisional license)؟","o":["30 يوماً","3 أشهر","6 أشهر","سنة واحدة"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Rhode Island أن يحمل تصريح التعلّم ستة أشهر على الأقل قبل أن يتقدّم بطلب رخصة مؤقتة محدودة.","p":"صحيح. تحمل التصريح ستة أشهر."},"ref":{"doc":"RI","page":12}},{"id":"ri-006","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many hours of supervised driving must a parent certify for a teen under 18?","o":["20 hours","50 hours","30 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A Rhode Island parent or guardian must sign a statement that a teen under 18 has driven at least 50 supervised hours.","p":"Right. The teen needs 50 hours."},"es":{"q":"En Rhode Island, ¿cuántas horas de manejo supervisado debe certificar un padre para un adolescente menor de 18?","o":["20 horas","50 horas","30 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"En Rhode Island, el padre, la madre o el tutor debe firmar que el adolescente menor de 18 ha manejado por lo menos 50 horas supervisadas.","p":"Correcto. El adolescente necesita 50 horas."},"zh":{"q":"在 Rhode Island，对 18 岁以下的青少年，父母必须证明他有多少小时有人监督的驾驶？","o":["20 小时","50 小时","30 小时","100 小时"],"h1":"它是一百的一半。","h2":"在 Rhode Island，父母或监护人必须签一份声明，证明 18 岁以下的青少年至少有 50 小时有人监督的驾驶。","p":"对。青少年需要 50 小时。"},"vi":{"q":"Ở Rhode Island, cha mẹ phải xác nhận bao nhiêu giờ lái xe có giám sát cho thiếu niên dưới 18 tuổi?","o":["20 giờ","50 giờ","30 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Ở Rhode Island, cha mẹ hoặc người giám hộ phải ký giấy xác nhận rằng thiếu niên dưới 18 tuổi đã lái xe có giám sát ít nhất 50 giờ.","p":"Đúng. Thiếu niên cần 50 giờ."},"tl":{"q":"Sa Rhode Island, ilang oras ng supervised driving ang dapat patunayan ng magulang para sa teenager na wala pang 18?","o":["20 oras","50 oras","30 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Sa Rhode Island, ang magulang o guardian ay dapat pumirma ng pahayag na ang teenager na wala pang 18 ay nakapagmaneho nang hindi bababa sa 50 oras na may gumagabay.","p":"Tama. Kailangan ng teenager ng 50 oras."},"ar":{"q":"في Rhode Island، كم ساعة من القيادة تحت الإشراف يجب أن يشهد بها أحد الوالدين لمراهق عمره أقل من 18 سنة؟","o":["20 ساعة","50 ساعة","30 ساعة","100 ساعة"],"h1":"هي نصف المئة.","h2":"في Rhode Island يجب على أحد الوالدين أو الوصي أن يوقّع بياناً بأن المراهق الذي عمره أقل من 18 سنة قاد 50 ساعة على الأقل تحت الإشراف.","p":"صحيح. يحتاج المراهق إلى 50 ساعة."},"ref":{"doc":"RI","page":12}},{"id":"ri-007","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how many of the 50 supervised hours must be at night?","o":["None","5 hours","25 hours","10 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 supervised driving hours for a Rhode Island teen must be at night.","p":"Right. Ten hours at night."},"es":{"q":"En Rhode Island, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Ninguna","5 horas","25 horas","10 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de manejo supervisado de un adolescente en Rhode Island deben ser de noche.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 Rhode Island，这 50 小时有人监督的驾驶中，必须有多少小时在夜间？","o":["不需要","5 小时","25 小时","10 小时"],"h1":"它是总数的五分之一。","h2":"在 Rhode Island，青少年 50 小时有人监督的驾驶中，至少 10 小时必须在夜间。","p":"对。夜间 10 小时。"},"vi":{"q":"Ở Rhode Island, trong 50 giờ lái xe có giám sát, bao nhiêu giờ phải là ban đêm?","o":["Không giờ nào","5 giờ","25 giờ","10 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ít nhất 10 trong 50 giờ lái xe có giám sát của thiếu niên ở Rhode Island phải là ban đêm.","p":"Đúng. Mười giờ vào ban đêm."},"tl":{"q":"Sa Rhode Island, ilan sa 50 oras ng supervised driving ang dapat sa gabi?","o":["Wala","5 oras","25 oras","10 oras"],"h1":"Isang-ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng supervised driving ng teenager sa Rhode Island ang dapat sa gabi.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في Rhode Island، كم ساعة من الـ 50 ساعة تحت الإشراف يجب أن تكون في الليل؟","o":["ولا ساعة","5 ساعات","25 ساعة","10 ساعات"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من القيادة تحت الإشراف للمراهق في Rhode Island في الليل.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"RI","page":12}},{"id":"ri-008","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, during which hours may a limited provisional licensee not drive without a qualified adult?","o":["1 a.m. to 5 a.m.","9 p.m. to 5 a.m.","11 p.m. to 6 a.m.","Midnight to 6 a.m."],"h1":"It starts one hour after midnight.","h2":"A Rhode Island limited provisional licensee may not drive between 1 a.m. and 5 a.m. unless a qualified adult is in the car.","p":"Right. The limit is 1 a.m. to 5 a.m."},"es":{"q":"En Rhode Island, ¿en qué horas no puede manejar sin un adulto calificado quien tiene licencia provisional limitada?","o":["De 1 a.m. a 5 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De medianoche a 6 a.m."],"h1":"Empieza una hora después de la medianoche.","h2":"Quien tiene licencia provisional limitada en Rhode Island no puede manejar entre la 1 a.m. y las 5 a.m., salvo que vaya un adulto calificado en el carro.","p":"Correcto. El límite es de 1 a.m. a 5 a.m."},"zh":{"q":"在 Rhode Island，持受限试用驾照的人在哪个时间段不能在没有合格成年人陪同的情况下开车？","o":["凌晨 1 点到 5 点","晚上 9 点到早上 5 点","晚上 11 点到早上 6 点","午夜到早上 6 点"],"h1":"它从午夜后一小时开始。","h2":"在 Rhode Island，持受限试用驾照的人在凌晨 1 点到 5 点之间不能开车，除非车里有一位合格的成年人。","p":"对。限制时间是凌晨 1 点到 5 点。"},"vi":{"q":"Ở Rhode Island, người có bằng lái tạm thời có giới hạn không được lái xe mà không có người lớn đủ điều kiện đi cùng trong những giờ nào?","o":["1 giờ sáng đến 5 giờ sáng","9 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","Nửa đêm đến 6 giờ sáng"],"h1":"Nó bắt đầu một giờ sau nửa đêm.","h2":"Người có bằng lái tạm thời có giới hạn ở Rhode Island không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có một người lớn đủ điều kiện ngồi trong xe.","p":"Đúng. Giới hạn là từ 1 giờ sáng đến 5 giờ sáng."},"tl":{"q":"Sa Rhode Island, sa anong mga oras hindi puwedeng magmaneho ang may limited provisional license nang walang kasamang qualified adult?","o":["1 a.m. hanggang 5 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","Hatinggabi hanggang 6 a.m."],"h1":"Nagsisimula ito isang oras pagkatapos ng hatinggabi.","h2":"Ang may limited provisional license sa Rhode Island ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. maliban kung may qualified adult sa kotse.","p":"Tama. Ang limitasyon ay 1 a.m. hanggang 5 a.m."},"ar":{"q":"في Rhode Island، في أي ساعات لا يجوز لحامل الرخصة المؤقتة المحدودة أن يقود بدون شخص بالغ مؤهل؟","o":["من 1 صباحاً إلى 5 صباحاً","من 9 مساءً إلى 5 صباحاً","من 11 مساءً إلى 6 صباحاً","من منتصف الليل إلى 6 صباحاً"],"h1":"تبدأ بعد منتصف الليل بساعة واحدة.","h2":"لا يجوز لحامل الرخصة المؤقتة المحدودة في Rhode Island أن يقود بين 1 صباحاً و5 صباحاً إلا إذا كان معه في السيارة شخص بالغ مؤهل.","p":"صحيح. القيد من 1 صباحاً إلى 5 صباحاً."},"ref":{"doc":"RI","page":14}},{"id":"ri-009","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, which trip is allowed alone during the 1 a.m. to 5 a.m. limit?","o":["Driving friends home from a party","Going out for food","Driving to or from work","Practicing on empty roads"],"h1":"Think of a trip you need for your job.","h2":"A Rhode Island limited provisional licensee may drive alone between 1 a.m. and 5 a.m. when driving to or from work.","p":"Right. A trip to or from work is allowed."},"es":{"q":"En Rhode Island, ¿qué viaje se permite manejar solo durante el límite de 1 a.m. a 5 a.m.?","o":["Llevar a los amigos a casa después de una fiesta","Salir a comprar comida","Manejar hacia o desde el trabajo","Practicar en calles vacías"],"h1":"Piense en un viaje que necesita para su empleo.","h2":"Quien tiene licencia provisional limitada en Rhode Island puede manejar solo entre la 1 a.m. y las 5 a.m. cuando va hacia o desde el trabajo.","p":"Correcto. Se permite ir o volver del trabajo."},"zh":{"q":"在 Rhode Island，在凌晨 1 点到 5 点的限制时间里，哪一种行程可以一个人开车？","o":["开车送朋友从聚会回家","出去买吃的","开车上班或下班","在空的马路上练习"],"h1":"想一想你工作需要的行程。","h2":"在 Rhode Island，持受限试用驾照的人在凌晨 1 点到 5 点之间，如果是开车上班或下班，可以一个人开车。","p":"对。上班或下班的行程是允许的。"},"vi":{"q":"Ở Rhode Island, trong giờ giới hạn từ 1 giờ sáng đến 5 giờ sáng, chuyến đi nào được phép lái một mình?","o":["Chở bạn bè từ tiệc về nhà","Đi ra ngoài mua đồ ăn","Lái xe đi làm hoặc đi làm về","Tập lái trên đường vắng"],"h1":"Hãy nghĩ đến chuyến đi bạn cần cho công việc.","h2":"Người có bằng lái tạm thời có giới hạn ở Rhode Island được lái một mình từ 1 giờ sáng đến 5 giờ sáng khi lái xe đi làm hoặc đi làm về.","p":"Đúng. Chuyến đi làm hoặc đi làm về được phép."},"tl":{"q":"Sa Rhode Island, aling biyahe ang puwedeng mag-isa sa oras ng limitasyon mula 1 a.m. hanggang 5 a.m.?","o":["Paghatid sa mga kaibigan pauwi mula sa party","Paglabas para bumili ng pagkain","Pagmamaneho papunta o pauwi galing sa trabaho","Pag-eensayo sa mga bakanteng kalsada"],"h1":"Isipin ang biyaheng kailangan mo para sa trabaho.","h2":"Ang may limited provisional license sa Rhode Island ay puwedeng magmaneho nang mag-isa mula 1 a.m. hanggang 5 a.m. kapag papunta o pauwi galing sa trabaho.","p":"Tama. Pinapayagan ang biyahe papunta o pauwi galing sa trabaho."},"ar":{"q":"في Rhode Island، أي رحلة مسموح بها وحدك خلال قيد الساعات من 1 صباحاً إلى 5 صباحاً؟","o":["توصيل الأصدقاء إلى بيوتهم من حفلة","الخروج لشراء طعام","القيادة إلى العمل أو منه","التدرّب على طرق فارغة"],"h1":"فكّر في رحلة تحتاجها لعملك.","h2":"يجوز لحامل الرخصة المؤقتة المحدودة في Rhode Island أن يقود وحده بين 1 صباحاً و5 صباحاً عندما يقود إلى العمل أو منه.","p":"صحيح. الرحلة إلى العمل أو منه مسموح بها."},"ref":{"doc":"RI","page":14}},{"id":"ri-010","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many passengers under 21 may a new limited provisional licensee carry?","o":["None","One","Two","Three"],"h1":"Count on one hand, and use just one finger.","h2":"During the first 12 months of a Rhode Island limited provisional license, the driver may carry no more than one passenger under 21, not counting immediate family.","p":"Right. Only one passenger under 21."},"es":{"q":"En Rhode Island, ¿cuántos pasajeros menores de 21 puede llevar quien acaba de recibir la licencia provisional limitada?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Cuente con una mano, y use solo un dedo.","h2":"Durante los primeros 12 meses de la licencia provisional limitada en Rhode Island, el conductor puede llevar como máximo a un pasajero menor de 21, sin contar a su familia inmediata.","p":"Correcto. Solo un pasajero menor de 21."},"zh":{"q":"在 Rhode Island，刚拿到受限试用驾照的人可以载多少名 21 岁以下的乘客？","o":["一个都不能","一名","两名","三名"],"h1":"用一只手数，只用一根手指。","h2":"在 Rhode Island，拿到受限试用驾照的头 12 个月里，司机最多只能载一名 21 岁以下的乘客，直系亲属不算在内。","p":"对。只能载一名 21 岁以下的乘客。"},"vi":{"q":"Ở Rhode Island, người mới có bằng lái tạm thời có giới hạn được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Đếm trên một bàn tay, và chỉ dùng một ngón.","h2":"Trong 12 tháng đầu của bằng lái tạm thời có giới hạn ở Rhode Island, người lái chỉ được chở tối đa một hành khách dưới 21 tuổi, không tính người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 21 tuổi."},"tl":{"q":"Sa Rhode Island, ilang pasaherong wala pang 21 ang puwedeng isakay ng bagong may limited provisional license?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Magbilang sa isang kamay, at isang daliri lang ang gamitin.","h2":"Sa unang 12 buwan ng limited provisional license sa Rhode Island, hindi puwedeng magsakay ang driver ng higit sa isang pasaherong wala pang 21, hindi kasama ang malapit na pamilya.","p":"Tama. Isang pasaherong wala pang 21 lang."},"ar":{"q":"في Rhode Island، كم راكباً عمره أقل من 21 سنة يمكن أن يحمل حامل الرخصة المؤقتة المحدودة الجديد؟","o":["ولا راكب","راكب واحد","راكبان","ثلاثة ركاب"],"h1":"عُدّ على يد واحدة، واستخدم إصبعاً واحداً فقط.","h2":"خلال أول 12 شهراً من الرخصة المؤقتة المحدودة في Rhode Island، لا يجوز للسائق أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة، دون احتساب أفراد الأسرة المباشرين.","p":"صحيح. راكب واحد فقط عمره أقل من 21 سنة."},"ref":{"doc":"RI","page":14}},{"id":"ri-011","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, how long does the passenger limit last on a limited provisional license?","o":["1 month","3 months","6 months","The first 12 months"],"h1":"It lasts a full year.","h2":"The Rhode Island passenger limit applies during the first 12 months of the limited provisional license.","p":"Right. It lasts the first 12 months."},"es":{"q":"En Rhode Island, ¿cuánto dura el límite de pasajeros en la licencia provisional limitada?","o":["1 mes","3 meses","6 meses","Los primeros 12 meses"],"h1":"Dura un año completo.","h2":"El límite de pasajeros en Rhode Island se aplica durante los primeros 12 meses de la licencia provisional limitada.","p":"Correcto. Dura los primeros 12 meses."},"zh":{"q":"在 Rhode Island，受限试用驾照的乘客限制持续多久？","o":["1 个月","3 个月","6 个月","最初的 12 个月"],"h1":"它持续整整一年。","h2":"在 Rhode Island，乘客限制适用于受限试用驾照的最初 12 个月。","p":"对。它持续最初的 12 个月。"},"vi":{"q":"Ở Rhode Island, giới hạn hành khách của bằng lái tạm thời có giới hạn kéo dài bao lâu?","o":["1 tháng","3 tháng","6 tháng","12 tháng đầu tiên"],"h1":"Nó kéo dài trọn một năm.","h2":"Giới hạn hành khách ở Rhode Island áp dụng trong 12 tháng đầu tiên của bằng lái tạm thời có giới hạn.","p":"Đúng. Nó kéo dài 12 tháng đầu tiên."},"tl":{"q":"Sa Rhode Island, gaano katagal ang limitasyon sa pasahero sa limited provisional license?","o":["1 buwan","3 buwan","6 na buwan","Ang unang 12 buwan"],"h1":"Tumatagal ito ng isang buong taon.","h2":"Ang limitasyon sa pasahero sa Rhode Island ay para sa unang 12 buwan ng limited provisional license.","p":"Tama. Tumatagal ito ng unang 12 buwan."},"ar":{"q":"في Rhode Island، كم يستمر قيد الركاب على الرخصة المؤقتة المحدودة؟","o":["شهر واحد","3 أشهر","6 أشهر","أول 12 شهراً"],"h1":"يستمر سنة كاملة.","h2":"ينطبق قيد الركاب في Rhode Island خلال أول 12 شهراً من الرخصة المؤقتة المحدودة.","p":"صحيح. يستمر أول 12 شهراً."},"ref":{"doc":"RI","page":14}},{"id":"ri-012","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, which young passengers do not count toward the provisional passenger limit?","o":["Immediate family members","Classmates","Teammates","Coworkers"],"h1":"Think of brothers and sisters.","h2":"In Rhode Island, immediate family members do not count toward the one-passenger limit on a limited provisional license.","p":"Right. Immediate family does not count."},"es":{"q":"En Rhode Island, ¿qué pasajeros jóvenes no cuentan en el límite de pasajeros de la licencia provisional?","o":["Los familiares inmediatos","Los compañeros de clase","Los compañeros de equipo","Los compañeros de trabajo"],"h1":"Piense en hermanos y hermanas.","h2":"En Rhode Island, los familiares inmediatos no cuentan en el límite de un pasajero de la licencia provisional limitada.","p":"Correcto. La familia inmediata no cuenta."},"zh":{"q":"在 Rhode Island，哪些年轻乘客不算在试用驾照的乘客限制里？","o":["直系亲属","同学","队友","同事"],"h1":"想一想兄弟姐妹。","h2":"在 Rhode Island，直系亲属不算在受限试用驾照的一名乘客限制里。","p":"对。直系亲属不算。"},"vi":{"q":"Ở Rhode Island, những hành khách trẻ nào không bị tính vào giới hạn hành khách của bằng lái tạm thời?","o":["Người thân trong gia đình","Bạn cùng lớp","Đồng đội","Đồng nghiệp"],"h1":"Hãy nghĩ đến anh chị em.","h2":"Ở Rhode Island, người thân trong gia đình không bị tính vào giới hạn một hành khách của bằng lái tạm thời có giới hạn.","p":"Đúng. Người thân trong gia đình không bị tính."},"tl":{"q":"Sa Rhode Island, aling mga batang pasahero ang hindi binibilang sa limitasyon sa pasahero ng provisional license?","o":["Malapit na pamilya (immediate family)","Mga kaklase","Mga kasama sa team","Mga katrabaho"],"h1":"Isipin ang mga kapatid na lalaki at babae.","h2":"Sa Rhode Island, hindi binibilang ang malapit na pamilya sa limitasyong isang pasahero sa limited provisional license.","p":"Tama. Hindi binibilang ang malapit na pamilya."},"ar":{"q":"في Rhode Island، أي ركاب صغار لا يُحسبون ضمن قيد الركاب على الرخصة المؤقتة؟","o":["أفراد الأسرة المباشرون","زملاء الصف","زملاء الفريق","زملاء العمل"],"h1":"فكّر في الإخوة والأخوات.","h2":"في Rhode Island لا يُحسب أفراد الأسرة المباشرون ضمن قيد الراكب الواحد على الرخصة المؤقتة المحدودة.","p":"صحيح. أفراد الأسرة المباشرون لا يُحسبون."},"ref":{"doc":"RI","page":14}},{"id":"ri-013","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, who may supervise a teen driving with an instruction permit?","o":["Any licensed driver over 18","Any passenger over 16","A licensed adult over 21 who has been licensed for five years","Only a police officer"],"h1":"The helper needs both age and years behind the wheel.","h2":"A Rhode Island permit holder must drive with a licensed adult over 21 who has held a license for at least five years.","p":"Right. Over 21 and licensed five years."},"es":{"q":"En Rhode Island, ¿quién puede supervisar a un adolescente que maneja con permiso de instrucción?","o":["Cualquier conductor con licencia mayor de 18","Cualquier pasajero mayor de 16","Un adulto mayor de 21 que tiene licencia desde hace cinco años","Solo un policía"],"h1":"El acompañante necesita edad y también años de manejo.","h2":"Quien tiene permiso en Rhode Island debe manejar con un adulto mayor de 21 que tenga licencia desde hace por lo menos cinco años.","p":"Correcto. Mayor de 21 y con licencia desde hace cinco años."},"zh":{"q":"在 Rhode Island，谁可以监督持学习驾照的青少年开车？","o":["任何 18 岁以上有驾照的司机","任何 16 岁以上的乘客","21 岁以上、已经有驾照五年的成年人","只有警察"],"h1":"陪同的人既要够年龄，也要有多年驾驶经验。","h2":"在 Rhode Island，持学习驾照的人必须和一位 21 岁以上、持有驾照至少五年的成年人一起开车。","p":"对。21 岁以上，并有驾照五年。"},"vi":{"q":"Ở Rhode Island, ai được giám sát thiếu niên lái xe với giấy phép tập lái?","o":["Bất kỳ tài xế có bằng nào trên 18 tuổi","Bất kỳ hành khách nào trên 16 tuổi","Một người lớn trên 21 tuổi đã có bằng lái được năm năm","Chỉ cảnh sát"],"h1":"Người kèm cần cả tuổi tác và nhiều năm lái xe.","h2":"Người có giấy phép tập lái ở Rhode Island phải lái xe cùng một người lớn có bằng lái, trên 21 tuổi, đã có bằng ít nhất năm năm.","p":"Đúng. Trên 21 tuổi và có bằng năm năm."},"tl":{"q":"Sa Rhode Island, sino ang puwedeng gumabay sa teenager na nagmamaneho na may instruction permit?","o":["Kahit sinong lisensyadong driver na higit 18","Kahit sinong pasaherong higit 16","Isang lisensyadong adult na higit 21 na may lisensya na nang limang taon","Pulis lang"],"h1":"Kailangan ng gabay ang tamang edad at maraming taon ng pagmamaneho.","h2":"Ang may permit sa Rhode Island ay dapat magmaneho kasama ang isang lisensyadong adult na higit 21 na may lisensya na nang hindi bababa sa limang taon.","p":"Tama. Higit 21 at may lisensya nang limang taon."},"ar":{"q":"في Rhode Island، من يجوز له الإشراف على مراهق يقود بتصريح تعلّم؟","o":["أي سائق مرخّص عمره أكثر من 18 سنة","أي راكب عمره أكثر من 16 سنة","شخص بالغ مرخّص عمره أكثر من 21 سنة ولديه رخصة منذ خمس سنوات","ضابط شرطة فقط"],"h1":"المرافق يحتاج إلى العمر وإلى سنوات من القيادة معاً.","h2":"يجب على حامل التصريح في Rhode Island أن يقود مع شخص بالغ مرخّص عمره أكثر من 21 سنة ويحمل رخصة منذ خمس سنوات على الأقل.","p":"صحيح. أكثر من 21 سنة ومرخّص منذ خمس سنوات."},"ref":{"doc":"RI","page":11}},{"id":"ri-014","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, may a driver read a text message while the car is moving?","o":["Yes, if it is short","No, texting while driving is banned","Yes, on the highway","Yes, if no one is in the car"],"h1":"Reading counts the same as writing.","h2":"Rhode Island bans texting while driving, which includes writing, sending or reading messages while the car is moving.","p":"Right. No reading or writing texts while driving."},"es":{"q":"En Rhode Island, ¿puede un conductor leer un mensaje de texto mientras el carro está en movimiento?","o":["Sí, si es corto","No, enviar o leer mensajes al manejar está prohibido","Sí, en la autopista","Sí, si no hay nadie en el carro"],"h1":"Leer cuenta igual que escribir.","h2":"Rhode Island prohíbe los mensajes de texto al manejar, lo que incluye escribir, enviar o leer mensajes mientras el carro está en movimiento.","p":"Correcto. Nada de leer ni escribir mensajes al manejar."},"zh":{"q":"在 Rhode Island，车在行驶时，司机可以看短信吗？","o":["可以，如果短信很短","不可以，开车时禁止发短信","可以，在高速公路上","可以，如果车里没有别人"],"h1":"看短信和写短信一样算。","h2":"Rhode Island 禁止开车时发短信，包括车在行驶时写、发送或阅读短信。","p":"对。开车时不能看也不能写短信。"},"vi":{"q":"Ở Rhode Island, tài xế có được đọc tin nhắn khi xe đang chạy không?","o":["Có, nếu tin nhắn ngắn","Không, cấm nhắn tin khi lái xe","Có, trên xa lộ","Có, nếu không có ai trong xe"],"h1":"Đọc cũng bị tính giống như viết.","h2":"Rhode Island cấm nhắn tin khi lái xe, bao gồm viết, gửi hoặc đọc tin nhắn khi xe đang chạy.","p":"Đúng. Không đọc và không viết tin nhắn khi lái xe."},"tl":{"q":"Sa Rhode Island, puwede bang magbasa ng text message ang driver habang umaandar ang kotse?","o":["Oo, kung maikli","Hindi, bawal ang pag-text habang nagmamaneho","Oo, sa highway","Oo, kung walang ibang tao sa kotse"],"h1":"Kapareho ng pagsulat ang pagbasa.","h2":"Bawal sa Rhode Island ang pag-text habang nagmamaneho, kasama ang pagsulat, pagpapadala, o pagbasa ng mensahe habang umaandar ang kotse.","p":"Tama. Bawal magbasa o magsulat ng text habang nagmamaneho."},"ar":{"q":"في Rhode Island، هل يجوز للسائق أن يقرأ رسالة نصية والسيارة تتحرك؟","o":["نعم، إذا كانت قصيرة","لا، الرسائل النصية أثناء القيادة ممنوعة","نعم، على الطريق السريع","نعم، إذا لم يكن أحد في السيارة"],"h1":"القراءة تُحسب مثل الكتابة.","h2":"تمنع Rhode Island الرسائل النصية أثناء القيادة، وهذا يشمل كتابة الرسائل أو إرسالها أو قراءتها والسيارة تتحرك.","p":"صحيح. لا قراءة ولا كتابة للرسائل أثناء القيادة."},"ref":{"doc":"RI","page":36}},{"id":"ri-015","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, how may an adult driver talk on a phone while driving?","o":["Holding the phone to the ear","On speaker, held in the hand","Any way they like","Only hands-free"],"h1":"Your hands must stay free for the wheel.","h2":"In Rhode Island an adult driver may talk on a phone while driving only hands-free, never holding it.","p":"Right. Only hands-free."},"es":{"q":"En Rhode Island, ¿cómo puede un conductor adulto hablar por teléfono mientras maneja?","o":["Con el teléfono en la oreja","En altavoz, con el teléfono en la mano","Como quiera","Solo con manos libres"],"h1":"Sus manos deben quedar libres para el volante.","h2":"En Rhode Island un conductor adulto solo puede hablar por teléfono al manejar con manos libres, nunca sosteniéndolo.","p":"Correcto. Solo con manos libres."},"zh":{"q":"在 Rhode Island，成年司机开车时可以怎样打电话？","o":["把手机拿到耳边","开扬声器，手拿着手机","怎样都可以","只能用免提（hands-free）"],"h1":"你的手必须空出来握方向盘。","h2":"在 Rhode Island，成年司机开车时只能用免提打电话，绝不能手拿手机。","p":"对。只能用免提。"},"vi":{"q":"Ở Rhode Island, tài xế người lớn được nói chuyện điện thoại khi lái xe bằng cách nào?","o":["Cầm điện thoại áp vào tai","Bật loa ngoài, cầm trên tay","Bằng bất kỳ cách nào","Chỉ dùng rảnh tay (hands-free)"],"h1":"Tay bạn phải rảnh để cầm vô lăng.","h2":"Ở Rhode Island, tài xế người lớn chỉ được nói chuyện điện thoại khi lái xe bằng cách rảnh tay, không bao giờ cầm điện thoại.","p":"Đúng. Chỉ dùng rảnh tay."},"tl":{"q":"Sa Rhode Island, paano puwedeng makipag-usap sa telepono ang adult na driver habang nagmamaneho?","o":["Hawak ang telepono sa tainga","Naka-speaker, hawak sa kamay","Kahit anong paraan","Hands-free lang"],"h1":"Dapat libre ang mga kamay mo para sa manibela.","h2":"Sa Rhode Island, ang adult na driver ay puwedeng makipag-usap sa telepono habang nagmamaneho nang hands-free lang, hindi kailanman hawak ito.","p":"Tama. Hands-free lang."},"ar":{"q":"في Rhode Island، كيف يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة؟","o":["بوضع الهاتف على الأذن","بمكبّر الصوت مع حمل الهاتف في اليد","بأي طريقة يريدها","بدون استخدام اليدين (hands-free) فقط"],"h1":"يجب أن تبقى يداك حرّتين لعجلة القيادة.","h2":"في Rhode Island يجوز للسائق البالغ أن يتكلم في الهاتف أثناء القيادة بدون استخدام اليدين فقط، ولا يحمله أبداً.","p":"صحيح. بدون استخدام اليدين فقط."},"ref":{"doc":"RI","page":null}},{"id":"ri-016","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver under 21?","o":["0.02 percent","0.08 percent","0.05 percent","0.10 percent"],"h1":"It is much lower than the adult limit.","h2":"In Rhode Island the alcohol limit for a driver under 21 is 0.02 percent.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor menor de 21?","o":["0.02 por ciento","0.08 por ciento","0.05 por ciento","0.10 por ciento"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Rhode Island el límite de alcohol para un conductor menor de 21 es de 0.02 por ciento.","p":"Correcto. Menor de 21, el límite es 0.02."},"zh":{"q":"在 Rhode Island，21 岁以下司机的法定酒精限度是多少？","o":["0.02%","0.08%","0.05%","0.10%"],"h1":"它比成年人的限度低很多。","h2":"在 Rhode Island，21 岁以下司机的酒精限度是 0.02%。","p":"对。21 岁以下，限度是 0.02。"},"vi":{"q":"Ở Rhode Island, giới hạn nồng độ cồn hợp pháp cho tài xế dưới 21 tuổi là bao nhiêu?","o":["0.02 phần trăm","0.08 phần trăm","0.05 phần trăm","0.10 phần trăm"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở Rhode Island, giới hạn nồng độ cồn cho tài xế dưới 21 tuổi là 0.02 phần trăm.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Rhode Island, ano ang legal na limitasyon sa alak para sa driver na wala pang 21?","o":["0.02 porsiyento","0.08 porsiyento","0.05 porsiyento","0.10 porsiyento"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adult.","h2":"Sa Rhode Island, ang limitasyon sa alak para sa driver na wala pang 21 ay 0.02 porsiyento.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Rhode Island، ما الحد القانوني للكحول للسائق الذي عمره أقل من 21 سنة؟","o":["0.02 بالمئة","0.08 بالمئة","0.05 بالمئة","0.10 بالمئة"],"h1":"هو أقل بكثير من حد البالغين.","h2":"في Rhode Island حد الكحول للسائق الذي عمره أقل من 21 سنة هو 0.02 بالمئة.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد 0.02."},"ref":{"doc":"RI","page":58}},{"id":"ri-017","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the legal alcohol limit for a driver 21 or older?","o":["0.02 percent","0.10 percent","0.08 percent","0.12 percent"],"h1":"It is the same limit used in most states.","h2":"In Rhode Island the alcohol limit for a driver 21 or older is 0.08 percent.","p":"Right. For adults, the limit is 0.08."},"es":{"q":"En Rhode Island, ¿cuál es el límite legal de alcohol para un conductor de 21 años o más?","o":["0.02 por ciento","0.10 por ciento","0.08 por ciento","0.12 por ciento"],"h1":"Es el mismo límite que usan la mayoría de los estados.","h2":"En Rhode Island el límite de alcohol para un conductor de 21 años o más es de 0.08 por ciento.","p":"Correcto. Para adultos, el límite es 0.08."},"zh":{"q":"在 Rhode Island，21 岁或以上司机的法定酒精限度是多少？","o":["0.02%","0.10%","0.08%","0.12%"],"h1":"它和大多数州用的限度一样。","h2":"在 Rhode Island，21 岁或以上司机的酒精限度是 0.08%。","p":"对。成年人的限度是 0.08。"},"vi":{"q":"Ở Rhode Island, giới hạn nồng độ cồn hợp pháp cho tài xế từ 21 tuổi trở lên là bao nhiêu?","o":["0.02 phần trăm","0.10 phần trăm","0.08 phần trăm","0.12 phần trăm"],"h1":"Đó là giới hạn giống như ở hầu hết các tiểu bang.","h2":"Ở Rhode Island, giới hạn nồng độ cồn cho tài xế từ 21 tuổi trở lên là 0.08 phần trăm.","p":"Đúng. Với người lớn, giới hạn là 0.08."},"tl":{"q":"Sa Rhode Island, ano ang legal na limitasyon sa alak para sa driver na 21 pataas?","o":["0.02 porsiyento","0.10 porsiyento","0.08 porsiyento","0.12 porsiyento"],"h1":"Ito ang parehong limitasyong ginagamit sa karamihan ng estado.","h2":"Sa Rhode Island, ang limitasyon sa alak para sa driver na 21 pataas ay 0.08 porsiyento.","p":"Tama. Para sa adult, ang limitasyon ay 0.08."},"ar":{"q":"في Rhode Island، ما الحد القانوني للكحول للسائق الذي عمره 21 سنة أو أكثر؟","o":["0.02 بالمئة","0.10 بالمئة","0.08 بالمئة","0.12 بالمئة"],"h1":"هو نفس الحد المستخدم في معظم الولايات.","h2":"في Rhode Island حد الكحول للسائق الذي عمره 21 سنة أو أكثر هو 0.08 بالمئة.","p":"صحيح. للبالغين، الحد 0.08."},"ref":{"doc":"RI","page":58}},{"id":"ri-018","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, what must you do when you approach a stopped police car with its lights on?","o":["Speed up to pass quickly","Change lanes away from it or slow down","Stop in your lane","Flash your high beams"],"h1":"Give the officer more room or more time.","h2":"Rhode Island's move over law says to change to a lane away from the stopped vehicle, or slow down, when it shows its emergency lights.","p":"Right. Move over or slow down."},"es":{"q":"En Rhode Island, ¿qué debe hacer al acercarse a un carro de policía detenido con las luces encendidas?","o":["Acelerar para pasar rápido","Cambiarse a un carril lejos de él o bajar la velocidad","Detenerse en su carril","Encender las luces altas"],"h1":"Dé al oficial más espacio o más tiempo.","h2":"La ley de Rhode Island para moverse de carril dice que debe cambiarse a un carril lejos del vehículo detenido, o bajar la velocidad, cuando tiene encendidas sus luces de emergencia.","p":"Correcto. Cámbiese de carril o baje la velocidad."},"zh":{"q":"在 Rhode Island，当你接近一辆停着并亮着灯的警车时，你必须怎么做？","o":["加速快速开过去","换到离它远的车道，或减速","在你的车道上停车","闪你的远光灯"],"h1":"给警察更多空间或更多时间。","h2":"Rhode Island 的让道法（move over law）规定，停着的车亮着紧急灯时，你要换到离它远的车道，或者减速。","p":"对。让道或减速。"},"vi":{"q":"Ở Rhode Island, bạn phải làm gì khi đến gần một xe cảnh sát đang dừng và bật đèn?","o":["Tăng tốc để vượt qua nhanh","Chuyển sang làn xa nó hoặc chạy chậm lại","Dừng lại trong làn của bạn","Nháy đèn pha"],"h1":"Hãy cho cảnh sát thêm khoảng trống hoặc thêm thời gian.","h2":"Luật nhường làn (move over law) của Rhode Island nói rằng bạn phải chuyển sang làn xa chiếc xe đang dừng, hoặc chạy chậm lại, khi xe đó bật đèn khẩn cấp.","p":"Đúng. Chuyển làn hoặc chạy chậm lại."},"tl":{"q":"Sa Rhode Island, ano ang dapat mong gawin kapag papalapit ka sa nakahintong police car na may ilaw na nakabukas?","o":["Bumilis para makalampas agad","Lumipat sa lane na malayo rito o bumagal","Huminto sa lane mo","I-flash ang high beams mo"],"h1":"Bigyan ang pulis ng mas maraming espasyo o mas maraming oras.","h2":"Sinasabi ng move over law ng Rhode Island na lumipat sa lane na malayo sa nakahintong sasakyan, o bumagal, kapag nakabukas ang emergency lights nito.","p":"Tama. Lumipat ng lane o bumagal."},"ar":{"q":"في Rhode Island، ماذا يجب أن تفعل عندما تقترب من سيارة شرطة متوقفة وأضواؤها مشتعلة؟","o":["تسرع لتتجاوزها بسرعة","تنتقل إلى مسار بعيد عنها أو تخفّف السرعة","تتوقف في مسارك","تومض بالأضواء العالية"],"h1":"أعطِ الشرطي مساحة أكبر أو وقتاً أطول.","h2":"يقول قانون الابتعاد (move over law) في Rhode Island أن تنتقل إلى مسار بعيد عن المركبة المتوقفة، أو تخفّف السرعة، عندما تكون أضواء الطوارئ فيها مشتعلة.","p":"صحيح. ابتعد بمسارك أو خفّف السرعة."},"ref":{"doc":"RI","page":null}},{"id":"ri-019","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, does the move over law apply to an ordinary car stopped on the shoulder?","o":["No, only police cars","No, only tow trucks","Only at night","Yes, move over or slow down for it too"],"h1":"Since 2023 the law protects more than emergency vehicles.","h2":"Yes. Rhode Island's move over law also covers any vehicle stopped on the shoulder or breakdown lane, so you move over or slow down for it.","p":"Right. Move over or slow down for any car stopped on the shoulder."},"es":{"q":"En Rhode Island, ¿la ley para moverse de carril se aplica a un carro común detenido en el acotamiento?","o":["No, solo a los carros de policía","No, solo a las grúas","Solo de noche","Sí, también debe cambiar de carril o bajar la velocidad"],"h1":"Desde 2023 la ley protege a más vehículos que los de emergencia.","h2":"Sí. La ley de Rhode Island para moverse de carril también cubre cualquier vehículo detenido en el acotamiento o carril de emergencia, así que usted debe cambiar de carril o bajar la velocidad.","p":"Correcto. Cambie de carril o baje la velocidad ante cualquier carro detenido en el acotamiento."},"zh":{"q":"在 Rhode Island，让道法也适用于停在路肩上的普通汽车吗？","o":["不，只适用于警车","不，只适用于拖车","只在夜间","是的，对它也要让道或减速"],"h1":"从 2023 年起，这条法律保护的不只是紧急车辆。","h2":"是的。Rhode Island 的让道法也包括任何停在路肩或故障车道上的车辆，所以你要为它让道或减速。","p":"对。对任何停在路肩上的车都要让道或减速。"},"vi":{"q":"Ở Rhode Island, luật nhường làn có áp dụng cho một chiếc xe bình thường đang dừng trên lề đường không?","o":["Không, chỉ xe cảnh sát","Không, chỉ xe kéo","Chỉ vào ban đêm","Có, cũng phải chuyển làn hoặc chạy chậm lại"],"h1":"Từ năm 2023, luật này bảo vệ nhiều hơn chỉ xe khẩn cấp.","h2":"Có. Luật nhường làn của Rhode Island cũng áp dụng cho bất kỳ xe nào dừng trên lề đường hoặc làn xe hư, nên bạn phải chuyển làn hoặc chạy chậm lại.","p":"Đúng. Chuyển làn hoặc chạy chậm lại với bất kỳ xe nào dừng trên lề đường."},"tl":{"q":"Sa Rhode Island, saklaw ba ng move over law ang ordinaryong kotse na nakahinto sa shoulder?","o":["Hindi, police car lang","Hindi, tow truck lang","Sa gabi lang","Oo, lumipat ng lane o bumagal din para rito"],"h1":"Mula 2023, mas marami na ang pinoprotektahan ng batas kaysa emergency vehicles lang.","h2":"Oo. Saklaw din ng move over law ng Rhode Island ang anumang sasakyang nakahinto sa shoulder o breakdown lane, kaya lumipat ka ng lane o bumagal para rito.","p":"Tama. Lumipat ng lane o bumagal para sa anumang kotseng nakahinto sa shoulder."},"ar":{"q":"في Rhode Island، هل ينطبق قانون الابتعاد على سيارة عادية متوقفة على كتف الطريق؟","o":["لا، فقط سيارات الشرطة","لا، فقط شاحنات السحب","في الليل فقط","نعم، ابتعد بمسارك أو خفّف السرعة لها أيضاً"],"h1":"منذ 2023 يحمي القانون أكثر من مركبات الطوارئ.","h2":"نعم. قانون الابتعاد في Rhode Island يشمل أيضاً أي مركبة متوقفة على كتف الطريق أو في مسار الأعطال، لذلك تبتعد بمسارك أو تخفّف السرعة لها.","p":"صحيح. ابتعد بمسارك أو خفّف السرعة لأي سيارة متوقفة على كتف الطريق."},"ref":{"doc":"RI","page":null}},{"id":"ri-020","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, on a highway with a median strip, must you stop for a school bus stopped on the other side?","o":["No, you do not have to stop","Yes, always","Only if children are visible","Only on school days"],"h1":"The median separates you from the children.","h2":"Under Rhode Island law, you do not have to stop for a school bus that is stopped on the other side of a divided highway.","p":"Right. The other side of a divided highway need not stop."},"es":{"q":"En Rhode Island, en una carretera con franja divisoria, ¿debe detenerse ante un autobús escolar detenido del otro lado?","o":["No, no tiene que detenerse","Sí, siempre","Solo si se ven niños","Solo en días de clases"],"h1":"La franja divisoria lo separa de los niños.","h2":"Según la ley de Rhode Island, usted no tiene que detenerse ante un autobús escolar detenido del otro lado de una carretera dividida.","p":"Correcto. El otro lado de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Rhode Island，在有中间隔离带的公路上，对面停着的校车，你必须停车吗？","o":["不，你不必停车","是的，一定要停","只有看得见孩子时才停","只有上学的日子才停"],"h1":"中间隔离带把你和孩子们隔开。","h2":"根据 Rhode Island 的法律，校车停在分隔公路的另一边时，你不必停车。","p":"对。分隔公路另一边的车不必停。"},"vi":{"q":"Ở Rhode Island, trên xa lộ có dải phân cách ở giữa, bạn có phải dừng lại cho xe buýt trường học đang dừng ở phía bên kia không?","o":["Không, bạn không phải dừng","Có, luôn luôn","Chỉ khi thấy trẻ em","Chỉ vào ngày đi học"],"h1":"Dải phân cách ngăn bạn với các em nhỏ.","h2":"Theo luật Rhode Island, bạn không phải dừng lại cho xe buýt trường học đang dừng ở phía bên kia của xa lộ có dải phân cách.","p":"Đúng. Xe ở phía bên kia của xa lộ có dải phân cách không cần dừng."},"tl":{"q":"Sa Rhode Island, sa highway na may median strip, dapat ka bang huminto para sa school bus na nakahinto sa kabilang panig?","o":["Hindi, hindi mo kailangang huminto","Oo, palagi","Kapag may nakikitang mga bata lang","Sa mga araw ng pasok lang"],"h1":"Pinaghihiwalay ka ng median sa mga bata.","h2":"Ayon sa batas ng Rhode Island, hindi mo kailangang huminto para sa school bus na nakahinto sa kabilang panig ng divided highway.","p":"Tama. Hindi kailangang huminto sa kabilang panig ng divided highway."},"ar":{"q":"في Rhode Island، على طريق سريع فيه جزيرة وسطية، هل يجب أن تتوقف لحافلة مدرسية متوقفة في الجهة الأخرى؟","o":["لا، ليس عليك أن تتوقف","نعم، دائماً","فقط إذا كان الأطفال ظاهرين","فقط في أيام الدراسة"],"h1":"الجزيرة الوسطية تفصلك عن الأطفال.","h2":"حسب قانون Rhode Island، ليس عليك أن تتوقف لحافلة مدرسية متوقفة في الجهة الأخرى من طريق مقسوم.","p":"صحيح. الجهة الأخرى من الطريق المقسوم لا تحتاج إلى التوقف."},"ref":{"doc":"RI","page":51}},{"id":"ri-021","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, on a road with no median, which drivers must stop for a school bus with flashing red lights?","o":["Only drivers behind the bus","Only drivers in the right lane","All drivers coming from either direction","No one, if the road is wide"],"h1":"On an undivided road, children may cross toward either side.","h2":"In Rhode Island, on a road with no median, drivers coming from either direction must stop for a school bus with flashing red lights.","p":"Right. Traffic from both directions stops."},"es":{"q":"En Rhode Island, en una vía sin división, ¿qué conductores deben detenerse ante un autobús escolar con luces rojas intermitentes?","o":["Solo los conductores detrás del autobús","Solo los del carril derecho","Todos los conductores que vienen de cualquier dirección","Nadie, si la vía es ancha"],"h1":"En una vía sin división, los niños pueden cruzar hacia cualquier lado.","h2":"En Rhode Island, en una vía sin división, los conductores que vienen de cualquier dirección deben detenerse ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El tráfico de ambos sentidos se detiene."},"zh":{"q":"在 Rhode Island，在没有中间隔离带的路上，哪些司机必须为闪着红灯的校车停车？","o":["只有校车后面的司机","只有右车道的司机","从两个方向来的所有司机","如果路很宽，谁都不用停"],"h1":"在没有分隔的路上，孩子可能往任何一边过马路。","h2":"在 Rhode Island，在没有中间隔离带的路上，两个方向来的司机都必须为闪着红灯的校车停车。","p":"对。两个方向的车都要停。"},"vi":{"q":"Ở Rhode Island, trên đường không có dải phân cách, những tài xế nào phải dừng lại cho xe buýt trường học đang nháy đèn đỏ?","o":["Chỉ tài xế phía sau xe buýt","Chỉ tài xế ở làn bên phải","Tất cả tài xế đến từ cả hai hướng","Không ai, nếu đường rộng"],"h1":"Trên đường không có phân cách, trẻ em có thể băng qua về bất kỳ phía nào.","h2":"Ở Rhode Island, trên đường không có dải phân cách, tài xế đến từ cả hai hướng phải dừng lại cho xe buýt trường học đang nháy đèn đỏ.","p":"Đúng. Xe từ cả hai hướng đều dừng."},"tl":{"q":"Sa Rhode Island, sa kalsadang walang median, aling mga driver ang dapat huminto para sa school bus na may kumikislap na pulang ilaw?","o":["Ang mga driver sa likod ng bus lang","Ang mga driver sa kanang lane lang","Lahat ng driver mula sa alinmang direksyon","Wala, kung malapad ang kalsada"],"h1":"Sa kalsadang walang hati, puwedeng tumawid ang mga bata sa alinmang panig.","h2":"Sa Rhode Island, sa kalsadang walang median, ang mga driver mula sa alinmang direksyon ay dapat huminto para sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Humihinto ang trapiko mula sa dalawang direksyon."},"ar":{"q":"في Rhode Island، على طريق بدون جزيرة وسطية، أي سائقين يجب أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض؟","o":["فقط السائقون خلف الحافلة","فقط السائقون في المسار الأيمن","كل السائقين القادمين من أي اتجاه","لا أحد، إذا كان الطريق عريضاً"],"h1":"على طريق غير مقسوم، قد يعبر الأطفال نحو أي جهة.","h2":"في Rhode Island، على طريق بدون جزيرة وسطية، يجب على السائقين القادمين من أي اتجاه أن يتوقفوا لحافلة مدرسية أضواؤها الحمراء تومض.","p":"صحيح. تتوقف حركة المرور من الاتجاهين."},"ref":{"doc":"RI","page":51}},{"id":"ri-023","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, how long is a limited instruction permit good for?","o":["Six months, then it must be renewed","Three years from the date it is issued","One year, or until age 18 if that comes first","Until the teen finishes high school"],"h1":"It is longer than the time you must hold it before the road test.","h2":"A Rhode Island limited instruction permit is valid for one year, or until the holder turns 18 if that comes first.","p":"Right. One year, or until age 18."},"es":{"q":"En Rhode Island, ¿por cuánto tiempo es válido un permiso de instrucción limitado?","o":["Seis meses, y luego se debe renovar","Tres años desde la fecha en que se emite","Un año, o hasta los 18 años si eso ocurre antes","Hasta que el joven termine la secundaria"],"h1":"Es más largo que el tiempo que debe tenerlo antes del examen de manejo.","h2":"En Rhode Island, el permiso de instrucción limitado es válido por un año, o hasta que el titular cumpla 18 años si eso ocurre antes.","p":"Correcto. Un año, o hasta los 18 años."},"zh":{"q":"在 Rhode Island，受限学习驾照（limited instruction permit）的有效期是多久？","o":["六个月，之后必须续期","从发证日期起三年","一年，或者到 18 岁为止，以先到者为准","直到青少年读完高中"],"h1":"它比你参加路考前必须持有的时间更长。","h2":"Rhode Island 的受限学习驾照有效期是一年，或者到持有人满 18 岁为止，以先到者为准。","p":"对。一年，或者到 18 岁为止。"},"vi":{"q":"Ở Rhode Island, giấy phép tập lái có giới hạn (limited instruction permit) có hiệu lực trong bao lâu?","o":["Sáu tháng, sau đó phải gia hạn","Ba năm kể từ ngày cấp","Một năm, hoặc đến 18 tuổi nếu điều đó đến trước","Đến khi thiếu niên học xong trung học"],"h1":"Thời gian này dài hơn thời gian bạn phải giữ giấy phép trước khi thi lái trên đường.","h2":"Giấy phép tập lái có giới hạn ở Rhode Island có hiệu lực một năm, hoặc đến khi người giữ giấy phép đủ 18 tuổi nếu điều đó đến trước.","p":"Đúng. Một năm, hoặc đến 18 tuổi."},"tl":{"q":"Sa Rhode Island, gaano katagal valid ang limited instruction permit?","o":["Anim na buwan, at pagkatapos ay kailangan itong i-renew","Tatlong taon mula sa araw na ibinigay ito","Isang taon, o hanggang edad 18 kung iyon ang mauna","Hanggang matapos ng teen ang high school"],"h1":"Mas mahaba ito kaysa sa panahong kailangan mo itong hawakan bago ang road test.","h2":"Ang limited instruction permit sa Rhode Island ay valid nang isang taon, o hanggang mag-18 ang may hawak nito kung iyon ang mauna.","p":"Tama. Isang taon, o hanggang edad 18."},"ar":{"q":"في Rhode Island، ما مدة صلاحية تصريح التعلّم المحدود (limited instruction permit)؟","o":["ستة أشهر، ثم يجب تجديده","ثلاث سنوات من تاريخ إصداره","سنة واحدة، أو حتى عمر 18 سنة إذا جاء ذلك أولًا","حتى ينهي المراهق المدرسة الثانوية"],"h1":"المدة أطول من الوقت الذي يجب أن تحمل فيه التصريح قبل اختبار القيادة على الطريق.","h2":"تصريح التعلّم المحدود في Rhode Island صالح لمدة سنة واحدة، أو حتى يبلغ حامله 18 سنة إذا جاء ذلك أولًا.","p":"صحيح. سنة واحدة، أو حتى عمر 18 سنة."},"ref":{"doc":"RI","page":11}},{"id":"ri-024","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, can police stop a car just because someone inside is not wearing a seat belt?","o":["Yes, for a person of any age","Only if the person is under 8","Only if the driver is under 18","No, only together with another offense"],"h1":"Rhode Island calls its seat belt law a primary law.","h2":"Rhode Island's seat belt law is a primary law for all ages, so police may pull a car over when anyone inside is not buckled up.","p":"Right. Police can stop you for an unbuckled person of any age."},"es":{"q":"En Rhode Island, ¿puede la policía detener un carro solo porque alguien adentro no lleva el cinturón de seguridad?","o":["Sí, por una persona de cualquier edad","Solo si la persona tiene menos de 8 años","Solo si el conductor tiene menos de 18 años","No, solo junto con otra infracción"],"h1":"Rhode Island llama a su ley del cinturón una ley primaria.","h2":"La ley del cinturón de seguridad de Rhode Island es una ley primaria para todas las edades, así que la policía puede detener un carro cuando alguien adentro no lleva el cinturón puesto.","p":"Correcto. La policía puede detenerlo por una persona sin cinturón de cualquier edad."},"zh":{"q":"在 Rhode Island，警察能不能只因为车里有人没系安全带就让车停下？","o":["能，任何年龄的人都算","只有那个人不满 8 岁时才能","只有司机不满 18 岁时才能","不能，只能和其他违规一起处理"],"h1":"Rhode Island 把它的安全带法律叫做主要法律（primary law）。","h2":"Rhode Island 的安全带法律对所有年龄都是主要法律，所以只要车里有人没系安全带，警察就可以让车停下。","p":"对。车里任何年龄的人没系安全带，警察都可以让你停车。"},"vi":{"q":"Ở Rhode Island, cảnh sát có thể chặn xe chỉ vì có người trong xe không thắt dây an toàn không?","o":["Có, với người ở bất kỳ tuổi nào","Chỉ khi người đó dưới 8 tuổi","Chỉ khi tài xế dưới 18 tuổi","Không, chỉ khi đi kèm với một vi phạm khác"],"h1":"Rhode Island gọi luật dây an toàn của mình là luật chính (primary law).","h2":"Luật dây an toàn ở Rhode Island là luật chính cho mọi lứa tuổi, nên cảnh sát có thể chặn xe khi có bất kỳ ai trong xe không thắt dây an toàn.","p":"Đúng. Cảnh sát có thể chặn bạn vì một người ở bất kỳ tuổi nào không thắt dây an toàn."},"tl":{"q":"Sa Rhode Island, puwede bang patigilin ng pulis ang kotse dahil lang may nakasakay na hindi naka-seat belt?","o":["Oo, para sa tao ng anumang edad","Kung wala pang 8 taong gulang ang tao lamang","Kung wala pang 18 taong gulang ang driver lamang","Hindi, kasama lang ng ibang paglabag"],"h1":"Tinatawag ng Rhode Island ang batas nito sa seat belt na primary law.","h2":"Ang batas sa seat belt ng Rhode Island ay primary law para sa lahat ng edad, kaya puwedeng patigilin ng pulis ang kotse kapag may sinumang nakasakay na hindi naka-seat belt.","p":"Tama. Puwede kang patigilin ng pulis dahil sa sinumang hindi naka-seat belt, anumang edad."},"ar":{"q":"في Rhode Island، هل يمكن للشرطة إيقاف سيارة فقط لأن شخصًا بداخلها لا يربط حزام الأمان؟","o":["نعم، لشخص من أي عمر","فقط إذا كان الشخص أقل من 8 سنوات","فقط إذا كان السائق أقل من 18 سنة","لا، فقط مع مخالفة أخرى"],"h1":"تسمّي Rhode Island قانون حزام الأمان فيها قانونًا أساسيًا (primary law).","h2":"قانون حزام الأمان في Rhode Island قانون أساسي لكل الأعمار، لذلك يمكن للشرطة إيقاف السيارة عندما لا يربط أي شخص بداخلها حزام الأمان.","p":"صحيح. يمكن للشرطة إيقافك بسبب شخص من أي عمر لا يربط الحزام."},"ref":{"doc":"RI","page":25}},{"id":"ri-025","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, where must a child under 8 who is shorter than 57 inches and under 80 pounds ride?","o":["In the front seat with a seat belt","Anywhere, as long as an adult holds the child","In the front seat in a booster seat","In a rear seat, in an approved child safety seat"],"h1":"Think about the safest part of the car for a small child.","h2":"In Rhode Island, a child under 8 who is less than 57 inches tall and less than 80 pounds must ride in a rear seat in an approved child restraint.","p":"Right. A rear seat, in an approved child safety seat."},"es":{"q":"En Rhode Island, ¿dónde debe viajar un niño menor de 8 años que mide menos de 57 pulgadas y pesa menos de 80 libras?","o":["En el asiento delantero con cinturón","En cualquier lugar, si un adulto lo sostiene","En el asiento delantero en un asiento elevado","En un asiento trasero, en un asiento de seguridad aprobado"],"h1":"Piense en la parte más segura del carro para un niño pequeño.","h2":"En Rhode Island, un niño menor de 8 años que mide menos de 57 pulgadas y pesa menos de 80 libras debe viajar en un asiento trasero, en un sistema de retención infantil aprobado.","p":"Correcto. En un asiento trasero, en un asiento de seguridad aprobado."},"zh":{"q":"在 Rhode Island，不满 8 岁、身高不到 57 英寸、体重不到 80 磅的孩子必须坐在哪里？","o":["坐在前座，系安全带","哪里都行，只要有大人抱着孩子","坐在前座的增高座椅上","坐在后座，使用合格的儿童安全座椅"],"h1":"想一想车里哪个位置对小孩子最安全。","h2":"在 Rhode Island，不满 8 岁、身高不到 57 英寸、体重不到 80 磅的孩子必须坐在后座，使用合格的儿童安全座椅。","p":"对。坐在后座，使用合格的儿童安全座椅。"},"vi":{"q":"Ở Rhode Island, trẻ dưới 8 tuổi, cao dưới 57 inch và nặng dưới 80 pound phải ngồi ở đâu?","o":["Ở ghế trước, có thắt dây an toàn","Ở bất kỳ đâu, miễn là có người lớn bế trẻ","Ở ghế trước, trên ghế nâng (booster seat)","Ở ghế sau, trong ghế an toàn trẻ em được chấp thuận"],"h1":"Hãy nghĩ xem chỗ nào trong xe an toàn nhất cho trẻ nhỏ.","h2":"Ở Rhode Island, trẻ dưới 8 tuổi, cao dưới 57 inch và nặng dưới 80 pound phải ngồi ở ghế sau, trong ghế an toàn trẻ em được chấp thuận.","p":"Đúng. Ở ghế sau, trong ghế an toàn trẻ em được chấp thuận."},"tl":{"q":"Sa Rhode Island, saan dapat umupo ang batang wala pang 8 taong gulang na mas mababa sa 57 pulgada at wala pang 80 libra?","o":["Sa upuan sa harap, naka-seat belt","Kahit saan, basta may adult na humahawak sa bata","Sa upuan sa harap, sa booster seat","Sa upuan sa likod, sa aprubadong child safety seat"],"h1":"Isipin kung aling bahagi ng kotse ang pinakaligtas para sa maliit na bata.","h2":"Sa Rhode Island, ang batang wala pang 8 taong gulang na mas mababa sa 57 pulgada at wala pang 80 libra ay dapat umupo sa upuan sa likod, sa aprubadong child safety seat.","p":"Tama. Sa upuan sa likod, sa aprubadong child safety seat."},"ar":{"q":"في Rhode Island، أين يجب أن يجلس طفل عمره أقل من 8 سنوات وطوله أقل من 57 بوصة ووزنه أقل من 80 رطلًا؟","o":["في المقعد الأمامي مع حزام الأمان","في أي مكان، ما دام شخص بالغ يحمل الطفل","في المقعد الأمامي على مقعد رافع (booster seat)","في مقعد خلفي، في مقعد أمان للأطفال معتمد"],"h1":"فكّر في أكثر مكان أمانًا في السيارة لطفل صغير.","h2":"في Rhode Island، يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات وطوله أقل من 57 بوصة ووزنه أقل من 80 رطلًا في مقعد خلفي، في مقعد أمان للأطفال معتمد.","p":"صحيح. في مقعد خلفي، في مقعد أمان للأطفال معتمد."},"ref":{"doc":"RI","page":25}},{"id":"ri-026","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, what happens to your license if you refuse a chemical test for alcohol?","o":["Nothing, the test is your choice","It is suspended for at least six months","You get a written warning only","It is suspended for one week"],"h1":"Driving in Rhode Island means you have already agreed to be tested.","h2":"In Rhode Island, refusing a chemical test for alcohol or drugs leads to a license suspension of at least six months, plus a fine and other penalties.","p":"Right. A suspension of at least six months."},"es":{"q":"En Rhode Island, ¿qué pasa con su licencia si se niega a hacerse una prueba química de alcohol?","o":["Nada, la prueba es opcional","Se suspende por al menos seis meses","Solo recibe una advertencia por escrito","Se suspende por una semana"],"h1":"Manejar en Rhode Island significa que usted ya aceptó hacerse la prueba.","h2":"En Rhode Island, negarse a una prueba química de alcohol o drogas lleva a una suspensión de la licencia de al menos seis meses, además de una multa y otras sanciones.","p":"Correcto. Una suspensión de al menos seis meses."},"zh":{"q":"在 Rhode Island，如果你拒绝做酒精化学检测，你的驾照会怎样？","o":["不会怎样，检测由你自己决定","至少被吊销六个月","你只会收到书面警告","被吊销一个星期"],"h1":"在 Rhode Island 开车，就表示你已经同意接受检测。","h2":"在 Rhode Island，拒绝做酒精或药物化学检测，驾照会被吊销至少六个月，还要交罚款并受到其他处罚。","p":"对。驾照至少被吊销六个月。"},"vi":{"q":"Ở Rhode Island, điều gì xảy ra với bằng lái của bạn nếu bạn từ chối xét nghiệm hóa học về rượu?","o":["Không có gì, xét nghiệm là do bạn chọn","Bằng lái bị treo ít nhất sáu tháng","Bạn chỉ bị cảnh cáo bằng văn bản","Bằng lái bị treo một tuần"],"h1":"Lái xe ở Rhode Island có nghĩa là bạn đã đồng ý cho xét nghiệm.","h2":"Ở Rhode Island, từ chối xét nghiệm hóa học về rượu hoặc ma túy sẽ khiến bằng lái bị treo ít nhất sáu tháng, cộng thêm tiền phạt và các hình phạt khác.","p":"Đúng. Bằng lái bị treo ít nhất sáu tháng."},"tl":{"q":"Sa Rhode Island, ano ang mangyayari sa lisensya mo kung tatanggi ka sa chemical test para sa alak?","o":["Wala, ikaw ang pipili kung magpapa-test ka","Masususpinde ito nang hindi bababa sa anim na buwan","Nakasulat na babala lang ang matatanggap mo","Masususpinde ito nang isang linggo"],"h1":"Ang pagmamaneho sa Rhode Island ay nangangahulugang pumayag ka na sa test.","h2":"Sa Rhode Island, ang pagtanggi sa chemical test para sa alak o droga ay nagdudulot ng suspensyon ng lisensya nang hindi bababa sa anim na buwan, kasama ang multa at iba pang parusa.","p":"Tama. Suspensyon nang hindi bababa sa anim na buwan."},"ar":{"q":"في Rhode Island، ماذا يحدث لرخصتك إذا رفضت إجراء فحص كيميائي للكحول؟","o":["لا شيء، الفحص اختياري لك","يتم إيقافها لمدة ستة أشهر على الأقل","تحصل على إنذار مكتوب فقط","يتم إيقافها لمدة أسبوع واحد"],"h1":"القيادة في Rhode Island تعني أنك وافقت مسبقًا على إجراء الفحص.","h2":"في Rhode Island، رفض الفحص الكيميائي للكحول أو المخدرات يؤدي إلى إيقاف الرخصة لمدة ستة أشهر على الأقل، مع غرامة وعقوبات أخرى.","p":"صحيح. إيقاف لمدة ستة أشهر على الأقل."},"ref":{"doc":"RI","page":58}},{"id":"ri-027","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, when must your headlights be on during the day?","o":["Only when driving inside a tunnel","Only when driving on an interstate highway","Whenever your windshield wipers are on because of the weather","Only when a police officer tells you"],"h1":"Think about rain, sleet or snow.","h2":"In Rhode Island, you must turn on your headlights any time your windshield wipers are in use because of rain, sleet or snow, as well as from sunset to sunrise.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Rhode Island, ¿cuándo debe tener las luces delanteras encendidas durante el día?","o":["Solo cuando maneja dentro de un túnel","Solo cuando maneja en una autopista interestatal","Siempre que use los limpiaparabrisas por el mal tiempo","Solo cuando un policía se lo indique"],"h1":"Piense en la lluvia, el aguanieve o la nieve.","h2":"En Rhode Island, debe encender las luces delanteras siempre que use los limpiaparabrisas por lluvia, aguanieve o nieve, además de desde la puesta hasta la salida del sol.","p":"Correcto. Si usa los limpiaparabrisas, encienda las luces."},"zh":{"q":"在 Rhode Island，白天什么时候必须开大灯？","o":["只有在隧道里开车时","只有在州际高速公路上开车时","只要因为天气开了雨刷","只有警察叫你开的时候"],"h1":"想一想下雨、下冻雨或下雪的时候。","h2":"在 Rhode Island，只要因为下雨、冻雨或下雪而使用雨刷，就必须开大灯；从日落到日出也必须开大灯。","p":"对。开雨刷，就要开大灯。"},"vi":{"q":"Ở Rhode Island, khi nào bạn phải bật đèn pha vào ban ngày?","o":["Chỉ khi lái xe trong đường hầm","Chỉ khi lái xe trên xa lộ liên tiểu bang","Bất cứ khi nào cần gạt nước đang bật vì thời tiết","Chỉ khi cảnh sát bảo bạn"],"h1":"Hãy nghĩ đến mưa, mưa tuyết hoặc tuyết.","h2":"Ở Rhode Island, bạn phải bật đèn pha bất cứ khi nào dùng cần gạt nước vì mưa, mưa tuyết hoặc tuyết, và cả từ lúc mặt trời lặn đến lúc mặt trời mọc.","p":"Đúng. Bật cần gạt nước thì bật đèn pha."},"tl":{"q":"Sa Rhode Island, kailan dapat nakabukas ang headlights mo sa araw?","o":["Kapag nagmamaneho sa loob ng tunnel lamang","Kapag nagmamaneho sa interstate highway lamang","Tuwing nakabukas ang windshield wipers mo dahil sa panahon","Kapag sinabihan ka ng pulis lamang"],"h1":"Isipin ang ulan, sleet o niyebe.","h2":"Sa Rhode Island, dapat mong buksan ang headlights mo tuwing ginagamit mo ang windshield wipers dahil sa ulan, sleet o niyebe, at gayundin mula paglubog hanggang pagsikat ng araw.","p":"Tama. Kapag nakabukas ang wipers, nakabukas din ang headlights."},"ar":{"q":"في Rhode Island، متى يجب تشغيل المصابيح الأمامية أثناء النهار؟","o":["فقط عند القيادة داخل نفق","فقط عند القيادة على طريق سريع بين الولايات","كلما كانت ماسحات الزجاج الأمامي تعمل بسبب الطقس","فقط عندما يطلب منك ضابط شرطة ذلك"],"h1":"فكّر في المطر أو المطر المتجمد أو الثلج.","h2":"في Rhode Island، يجب أن تشغّل المصابيح الأمامية كلما استخدمت ماسحات الزجاج الأمامي بسبب المطر أو المطر المتجمد أو الثلج، وكذلك من غروب الشمس حتى شروقها.","p":"صحيح. إذا عملت الماسحات، تعمل المصابيح الأمامية."},"ref":{"doc":"RI","page":49}},{"id":"ri-028","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 8 feet","No closer than 15 feet","No closer than 25 feet"],"h1":"It is less than 10 feet.","h2":"In Rhode Island you may not park within 8 feet of a fire hydrant.","p":"Right. Stay at least 8 feet away from a fire hydrant."},"es":{"q":"En Rhode Island, ¿qué tan cerca de un hidrante de incendios puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 8 pies","No más cerca de 15 pies","No más cerca de 25 pies"],"h1":"Es menos de 10 pies.","h2":"En Rhode Island usted no puede estacionarse a menos de 8 pies de un hidrante de incendios.","p":"Correcto. Manténgase por lo menos a 8 pies de un hidrante."},"zh":{"q":"在 Rhode Island，停车时可以离消防栓多近？","o":["不能近于 5 英尺","不能近于 8 英尺","不能近于 15 英尺","不能近于 25 英尺"],"h1":"少于 10 英尺。","h2":"在 Rhode Island，你不可以在离消防栓 8 英尺以内的地方停车。","p":"对。离消防栓至少 8 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần trụ nước chữa cháy đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 8 feet","Không gần hơn 15 feet","Không gần hơn 25 feet"],"h1":"Khoảng cách này ít hơn 10 feet.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 8 feet tính từ trụ nước chữa cháy.","p":"Đúng. Hãy cách trụ nước chữa cháy ít nhất 8 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 8 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan"],"h1":"Mas kaunti ito sa 10 talampakan.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 8 talampakan mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 8 talampakan mula sa fire hydrant."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من صنبور إطفاء الحريق؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 8 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا"],"h1":"المسافة أقل من 10 أقدام.","h2":"في Rhode Island لا يجوز لك أن تركن سيارتك على مسافة أقل من 8 أقدام من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 8 أقدام على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"RI","page":32}},{"id":"ri-029","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, how close to a stop sign or traffic light may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 15 feet","No closer than 30 feet"],"h1":"Other drivers need to see the sign or light from far away.","h2":"In Rhode Island you may not park within 30 feet of a stop sign, a traffic light or a flashing red or yellow light.","p":"Right. Park at least 30 feet from a stop sign or traffic light."},"es":{"q":"En Rhode Island, ¿qué tan cerca de una señal de alto o un semáforo puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los otros conductores necesitan ver la señal o la luz desde lejos.","h2":"En Rhode Island usted no puede estacionarse a menos de 30 pies de una señal de alto, un semáforo o una luz roja o amarilla intermitente.","p":"Correcto. Estaciónese por lo menos a 30 pies de una señal de alto o un semáforo."},"zh":{"q":"在 Rhode Island，停车时可以离停车标志（stop sign）或红绿灯多近？","o":["不能近于 5 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 30 英尺"],"h1":"其他司机需要从远处看到标志或灯。","h2":"在 Rhode Island，你不可以在离停车标志、红绿灯或闪烁的红灯、黄灯 30 英尺以内的地方停车。","p":"对。停车时离停车标志或红绿灯至少 30 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần biển báo dừng (stop sign) hoặc đèn giao thông đến mức nào?","o":["Không gần hơn 5 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Các tài xế khác cần nhìn thấy biển báo hoặc đèn từ xa.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 30 feet tính từ biển báo dừng, đèn giao thông hoặc đèn đỏ hay đèn vàng nhấp nháy.","p":"Đúng. Hãy đậu xe cách biển báo dừng hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa stop sign o traffic light ka puwedeng pumarada?","o":["Hindi lalapit sa 5 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 30 talampakan"],"h1":"Kailangang makita ng ibang driver ang sign o ilaw mula sa malayo.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 30 talampakan mula sa stop sign, traffic light, o kumikislap na pula o dilaw na ilaw.","p":"Tama. Pumarada nang hindi bababa sa 30 talampakan mula sa stop sign o traffic light."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من إشارة التوقف (stop sign) أو إشارة المرور الضوئية؟","o":["ليس أقرب من 5 أقدام","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 30 قدمًا"],"h1":"يحتاج السائقون الآخرون إلى رؤية الإشارة أو الضوء من بعيد.","h2":"في Rhode Island لا يجوز لك أن تركن سيارتك على مسافة أقل من 30 قدمًا من إشارة التوقف أو إشارة المرور الضوئية أو الضوء الأحمر أو الأصفر الوامض.","p":"صحيح. اركن سيارتك على بعد 30 قدمًا على الأقل من إشارة التوقف أو إشارة المرور الضوئية."},"ref":{"doc":"RI","page":32}},{"id":"ri-030","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, you are using high beams at night and following another car. When must you dim your lights?","o":["When you are within 200 feet of it","When you are within 50 feet of it","When you are within 1,000 feet of it","Only when it is raining"],"h1":"It is less than the 500 feet used for oncoming cars.","h2":"In Rhode Island you must dim your high beams when you follow another vehicle within 200 feet.","p":"Right. Dim your high beams when you are 200 feet or less behind another car."},"es":{"q":"En Rhode Island, usted lleva las luces altas de noche y va detrás de otro carro. ¿Cuándo debe bajar las luces?","o":["Cuando esté a menos de 200 pies de él","Cuando esté a menos de 50 pies de él","Cuando esté a menos de 1,000 pies de él","Solo cuando está lloviendo"],"h1":"Es menos que los 500 pies que se usan para los carros que vienen de frente.","h2":"En Rhode Island usted debe bajar las luces altas cuando va detrás de otro vehículo a menos de 200 pies.","p":"Correcto. Baje las luces altas cuando esté a 200 pies o menos detrás de otro carro."},"zh":{"q":"在 Rhode Island，你晚上开着远光灯，跟在另一辆车后面。你什么时候必须把灯调暗？","o":["在离它 200 英尺以内时","在离它 50 英尺以内时","在离它 1,000 英尺以内时","只有下雨时"],"h1":"它比对面来车用的 500 英尺要少。","h2":"在 Rhode Island，当你跟在另一辆车后面 200 英尺以内时，必须把远光灯调暗。","p":"对。当你在另一辆车后面 200 英尺或更近时，要把远光灯调暗。"},"vi":{"q":"Ở Rhode Island, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm và đi sau một xe khác. Khi nào bạn phải giảm đèn?","o":["Khi bạn cách xe đó trong vòng 200 feet","Khi bạn cách xe đó trong vòng 50 feet","Khi bạn cách xe đó trong vòng 1,000 feet","Chỉ khi trời mưa"],"h1":"Khoảng cách này ít hơn 500 feet dùng cho xe chạy ngược chiều.","h2":"Ở Rhode Island, bạn phải giảm đèn pha khi đi sau một xe khác trong vòng 200 feet.","p":"Đúng. Hãy giảm đèn pha khi bạn ở sau một xe khác 200 feet hoặc gần hơn."},"tl":{"q":"Sa Rhode Island, gumagamit ka ng high beams sa gabi at sumusunod sa ibang kotse. Kailan mo dapat hinaan ang iyong ilaw?","o":["Kapag nasa loob ka ng 200 talampakan mula rito","Kapag nasa loob ka ng 50 talampakan mula rito","Kapag nasa loob ka ng 1,000 talampakan mula rito","Kapag umuulan lang"],"h1":"Mas kaunti ito sa 500 talampakan na ginagamit para sa mga paparating na kotse.","h2":"Sa Rhode Island, dapat mong hinaan ang iyong high beams kapag sumusunod ka sa ibang sasakyan sa loob ng 200 talampakan.","p":"Tama. Hinaan ang high beams kapag 200 talampakan o mas malapit ka sa likod ng ibang kotse."},"ar":{"q":"في Rhode Island، تستخدم الأضواء العالية ليلًا وتسير خلف سيارة أخرى. متى يجب أن تخفّض أضواءك؟","o":["عندما تكون على بعد 200 قدم منها أو أقل","عندما تكون على بعد 50 قدمًا منها أو أقل","عندما تكون على بعد 1,000 قدم منها أو أقل","فقط عندما تمطر"],"h1":"المسافة أقل من 500 قدم المستخدمة مع السيارات القادمة من الاتجاه المقابل.","h2":"في Rhode Island يجب أن تخفّض أضواءك العالية عندما تسير خلف سيارة أخرى على بعد 200 قدم أو أقل.","p":"صحيح. خفّض أضواءك العالية عندما تكون على بعد 200 قدم أو أقل خلف سيارة أخرى."},"ref":{"doc":"RI","page":49}},{"id":"ri-031","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, a fire truck is going to a fire alarm. How close may you follow it?","o":["No closer than 50 feet","No closer than 200 feet","No closer than 500 feet","As close as you want if you are careful"],"h1":"Give it plenty of room, because it may stop or turn suddenly.","h2":"In Rhode Island you may not follow a fire truck going to an alarm any closer than 500 feet.","p":"Right. Stay at least 500 feet behind a fire truck on its way to an alarm."},"es":{"q":"En Rhode Island, un camión de bomberos va hacia una alarma de incendio. ¿Qué tan cerca puede seguirlo?","o":["No más cerca de 50 pies","No más cerca de 200 pies","No más cerca de 500 pies","Tan cerca como quiera si tiene cuidado"],"h1":"Dele mucho espacio, porque puede detenerse o dar vuelta de repente.","h2":"En Rhode Island usted no puede seguir a un camión de bomberos que va hacia una alarma a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás de un camión de bomberos que va a una alarma."},"zh":{"q":"在 Rhode Island，一辆消防车正在去处理火警。你跟在它后面可以多近？","o":["不能近于 50 英尺","不能近于 200 英尺","不能近于 500 英尺","只要小心，多近都可以"],"h1":"给它留很多空间，因为它可能会突然停下或转弯。","h2":"在 Rhode Island，跟在去处理火警的消防车后面时，不可以近于 500 英尺。","p":"对。跟在去处理火警的消防车后面时，至少保持 500 英尺。"},"vi":{"q":"Ở Rhode Island, một xe cứu hỏa đang đi đến nơi có báo cháy. Bạn được chạy theo sau nó gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 200 feet","Không gần hơn 500 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận"],"h1":"Hãy chừa nhiều khoảng trống, vì xe có thể dừng hoặc rẽ bất ngờ.","h2":"Ở Rhode Island, bạn không được chạy theo sau xe cứu hỏa đang đến nơi báo cháy gần hơn 500 feet.","p":"Đúng. Hãy ở sau xe cứu hỏa đang đến nơi báo cháy ít nhất 500 feet."},"tl":{"q":"Sa Rhode Island, may fire truck na papunta sa isang fire alarm. Gaano kalapit ka puwedeng sumunod dito?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 200 talampakan","Hindi lalapit sa 500 talampakan","Kahit gaano kalapit basta mag-ingat ka"],"h1":"Bigyan ito ng maraming espasyo, dahil puwede itong biglang huminto o lumiko.","h2":"Sa Rhode Island, hindi ka puwedeng sumunod sa fire truck na papunta sa alarm nang mas malapit sa 500 talampakan.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod ng fire truck na papunta sa alarm."},"ar":{"q":"في Rhode Island، شاحنة إطفاء متجهة إلى إنذار حريق. ما أقرب مسافة يمكنك أن تسير فيها خلفها؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 200 قدم","ليس أقرب من 500 قدم","بأي مسافة تريدها إذا كنت حذرًا"],"h1":"اترك لها مسافة كبيرة، لأنها قد تتوقف أو تنعطف فجأة.","h2":"في Rhode Island لا يجوز لك أن تسير خلف شاحنة إطفاء متجهة إلى إنذار على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل خلف شاحنة إطفاء في طريقها إلى إنذار."},"ref":{"doc":"RI","page":35}},{"id":"ri-032","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, what is the speed limit in a residential area when no other limit is posted?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"It is the same limit used in business districts.","h2":"In Rhode Island the speed limit in a residential area is 25 mph when no other limit is posted.","p":"Right. The limit in a residential area is 25 mph."},"es":{"q":"En Rhode Island, ¿cuál es el límite de velocidad en una zona residencial cuando no hay otro límite indicado?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Es el mismo límite que en las zonas comerciales.","h2":"En Rhode Island el límite de velocidad en una zona residencial es de 25 mph cuando no hay otro límite indicado.","p":"Correcto. El límite en una zona residencial es de 25 mph."},"zh":{"q":"在 Rhode Island，如果没有标出其他限速，住宅区的限速是多少？","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"它和商业区用的限速一样。","h2":"在 Rhode Island，如果没有标出其他限速，住宅区的限速是 25 mph。","p":"对。住宅区的限速是 25 mph。"},"vi":{"q":"Ở Rhode Island, tốc độ tối đa trong khu dân cư là bao nhiêu khi không có biển báo tốc độ khác?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Đó là cùng tốc độ tối đa dùng trong khu kinh doanh.","h2":"Ở Rhode Island, tốc độ tối đa trong khu dân cư là 25 mph khi không có biển báo tốc độ khác.","p":"Đúng. Tốc độ tối đa trong khu dân cư là 25 mph."},"tl":{"q":"Sa Rhode Island, ano ang speed limit sa residential area kapag walang ibang limit na nakapaskil?","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"Pareho ito sa limit na ginagamit sa mga business district.","h2":"Sa Rhode Island, ang speed limit sa residential area ay 25 mph kapag walang ibang limit na nakapaskil.","p":"Tama. Ang limit sa residential area ay 25 mph."},"ar":{"q":"في Rhode Island، ما حد السرعة في المنطقة السكنية عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","35 mph","40 mph"],"h1":"هو نفس الحد المستخدم في المناطق التجارية.","h2":"في Rhode Island حد السرعة في المنطقة السكنية هو 25 mph عندما لا توجد لافتة بحد آخر.","p":"صحيح. حد السرعة في المنطقة السكنية هو 25 mph."},"ref":{"doc":"RI","page":35}},{"id":"ri-033","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how good must your eyesight be to pass the vision test for a permit?","o":["At least 20/20","At least 20/40","At least 20/60","At least 20/100"],"h1":"You may wear your glasses or contact lenses for the test.","h2":"In Rhode Island your vision must be at least 20/40 to pass, with glasses or contact lenses if you normally wear them.","p":"Right. You need at least 20/40 vision, with your glasses or contacts if you use them."},"es":{"q":"En Rhode Island, ¿qué tan buena debe ser su vista para pasar el examen de la vista para el permiso?","o":["Por lo menos 20/20","Por lo menos 20/40","Por lo menos 20/60","Por lo menos 20/100"],"h1":"Puede usar sus anteojos o lentes de contacto durante el examen.","h2":"En Rhode Island su vista debe ser por lo menos 20/40 para pasar, con anteojos o lentes de contacto si normalmente los usa.","p":"Correcto. Necesita una vista de por lo menos 20/40, con sus anteojos o lentes de contacto si los usa."},"zh":{"q":"在 Rhode Island，学习驾照的视力测试要求视力至少多好才能通过？","o":["至少 20/20","至少 20/40","至少 20/60","至少 20/100"],"h1":"测试时你可以戴眼镜或隐形眼镜。","h2":"在 Rhode Island，你的视力必须至少达到 20/40 才能通过；如果你平时戴眼镜或隐形眼镜，测试时可以戴着。","p":"对。你的视力需要至少 20/40，如果你平时戴眼镜或隐形眼镜，可以戴着测试。"},"vi":{"q":"Ở Rhode Island, thị lực của bạn phải tốt đến mức nào để qua bài kiểm tra mắt khi xin giấy phép tập lái?","o":["Ít nhất 20/20","Ít nhất 20/40","Ít nhất 20/60","Ít nhất 20/100"],"h1":"Bạn có thể đeo kính hoặc kính áp tròng khi kiểm tra.","h2":"Ở Rhode Island, thị lực của bạn phải ít nhất là 20/40 để đậu, có đeo kính hoặc kính áp tròng nếu bạn thường đeo.","p":"Đúng. Bạn cần thị lực ít nhất 20/40, có đeo kính hoặc kính áp tròng nếu bạn dùng."},"tl":{"q":"Sa Rhode Island, gaano kalinaw dapat ang iyong paningin para pumasa sa vision test para sa permit?","o":["Hindi bababa sa 20/20","Hindi bababa sa 20/40","Hindi bababa sa 20/60","Hindi bababa sa 20/100"],"h1":"Puwede mong isuot ang iyong salamin o contact lens sa test.","h2":"Sa Rhode Island, ang iyong paningin ay dapat hindi bababa sa 20/40 para pumasa, suot ang salamin o contact lens kung karaniwan mo itong ginagamit.","p":"Tama. Kailangan mo ng paningin na hindi bababa sa 20/40, suot ang salamin o contact lens kung ginagamit mo ito."},"ar":{"q":"في Rhode Island، ما مدى جودة نظرك المطلوبة لتنجح في فحص النظر للحصول على التصريح؟","o":["20/20 على الأقل","20/40 على الأقل","20/60 على الأقل","20/100 على الأقل"],"h1":"يمكنك أن تلبس نظارتك أو عدساتك اللاصقة أثناء الفحص.","h2":"في Rhode Island يجب أن يكون نظرك 20/40 على الأقل لتنجح، مع النظارة أو العدسات اللاصقة إذا كنت تلبسها عادةً.","p":"صحيح. تحتاج إلى نظر 20/40 على الأقل، مع نظارتك أو عدساتك اللاصقة إذا كنت تستخدمها."},"ref":{"doc":"RI","page":11}},{"id":"ri-034","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you fail the road test. How long must you wait before you take it again?","o":["You may take it again the same day","At least 7 days","At least 30 days","At least 6 months"],"h1":"It is about one month.","h2":"In Rhode Island you must wait at least 30 days before you take the road test again.","p":"Right. After a failed road test, you wait at least 30 days."},"es":{"q":"En Rhode Island, usted no pasa el examen de manejo. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Puede tomarlo otra vez el mismo día","Por lo menos 7 días","Por lo menos 30 días","Por lo menos 6 meses"],"h1":"Es más o menos un mes.","h2":"En Rhode Island usted debe esperar por lo menos 30 días para tomar el examen de manejo otra vez.","p":"Correcto. Después de no pasar el examen de manejo, espere por lo menos 30 días."},"zh":{"q":"在 Rhode Island，你路考没有通过。你要等多久才能再考？","o":["当天就可以再考","至少 7 天","至少 30 天","至少 6 个月"],"h1":"大约一个月。","h2":"在 Rhode Island，你必须至少等 30 天才能再考路考。","p":"对。路考没通过后，你要至少等 30 天。"},"vi":{"q":"Ở Rhode Island, bạn thi trượt bài thi lái xe trên đường. Bạn phải chờ bao lâu mới được thi lại?","o":["Bạn có thể thi lại ngay trong ngày","Ít nhất 7 ngày","Ít nhất 30 ngày","Ít nhất 6 tháng"],"h1":"Khoảng một tháng.","h2":"Ở Rhode Island, bạn phải chờ ít nhất 30 ngày trước khi thi lại bài thi lái xe trên đường.","p":"Đúng. Sau khi thi trượt bài thi lái xe trên đường, bạn chờ ít nhất 30 ngày."},"tl":{"q":"Sa Rhode Island, bumagsak ka sa road test. Gaano katagal ka dapat maghintay bago ka kumuha ulit?","o":["Puwede kang kumuha ulit sa parehong araw","Hindi bababa sa 7 araw","Hindi bababa sa 30 araw","Hindi bababa sa 6 na buwan"],"h1":"Mga isang buwan ito.","h2":"Sa Rhode Island, dapat kang maghintay nang hindi bababa sa 30 araw bago ka kumuha ulit ng road test.","p":"Tama. Pagkatapos bumagsak sa road test, maghihintay ka nang hindi bababa sa 30 araw."},"ar":{"q":"في Rhode Island، رسبت في اختبار القيادة على الطريق. كم يجب أن تنتظر قبل أن تعيده؟","o":["يمكنك أن تعيده في اليوم نفسه","7 أيام على الأقل","30 يومًا على الأقل","6 أشهر على الأقل"],"h1":"المدة شهر تقريبًا.","h2":"في Rhode Island يجب أن تنتظر 30 يومًا على الأقل قبل أن تعيد اختبار القيادة على الطريق.","p":"صحيح. بعد الرسوب في اختبار القيادة على الطريق، تنتظر 30 يومًا على الأقل."},"ref":{"doc":"RI","page":14}},{"id":"ri-035","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, what is the youngest age to get a full operator's license?","o":["17 years and 6 months","16 years and 6 months","17 years","18 years"],"h1":"It is half a year before you turn 18.","h2":"In Rhode Island you must be at least 17 years and 6 months old to get a full operator's license.","p":"Right. The youngest age for a full license is 17 and a half."},"es":{"q":"En Rhode Island, ¿cuál es la edad mínima para obtener una licencia de conducir completa?","o":["17 años y 6 meses","16 años y 6 meses","17 años","18 años"],"h1":"Es medio año antes de cumplir 18.","h2":"En Rhode Island usted debe tener por lo menos 17 años y 6 meses para obtener una licencia de conducir completa.","p":"Correcto. La edad mínima para la licencia completa es 17 años y medio."},"zh":{"q":"在 Rhode Island，最小几岁可以拿到正式驾照（full operator's license）？","o":["17 岁 6 个月","16 岁 6 个月","17 岁","18 岁"],"h1":"比满 18 岁早半年。","h2":"在 Rhode Island，你必须至少 17 岁 6 个月才能拿到正式驾照。","p":"对。拿正式驾照的最小年龄是 17 岁半。"},"vi":{"q":"Ở Rhode Island, tuổi nhỏ nhất để lấy bằng lái đầy đủ (full operator's license) là bao nhiêu?","o":["17 tuổi 6 tháng","16 tuổi 6 tháng","17 tuổi","18 tuổi"],"h1":"Đó là nửa năm trước khi bạn tròn 18 tuổi.","h2":"Ở Rhode Island, bạn phải ít nhất 17 tuổi 6 tháng để lấy bằng lái đầy đủ.","p":"Đúng. Tuổi nhỏ nhất để lấy bằng lái đầy đủ là 17 tuổi rưỡi."},"tl":{"q":"Sa Rhode Island, ano ang pinakabatang edad para makakuha ng full operator's license?","o":["17 taon at 6 na buwan","16 na taon at 6 na buwan","17 taon","18 taon"],"h1":"Kalahating taon ito bago ka mag-18.","h2":"Sa Rhode Island, dapat ay hindi bababa sa 17 taon at 6 na buwan ang edad mo para makakuha ng full operator's license.","p":"Tama. Ang pinakabatang edad para sa full license ay 17 at kalahati."},"ar":{"q":"في Rhode Island، ما أصغر عمر للحصول على رخصة قيادة كاملة (full operator's license)؟","o":["17 سنة و6 أشهر","16 سنة و6 أشهر","17 سنة","18 سنة"],"h1":"إنه نصف سنة قبل أن تبلغ 18.","h2":"في Rhode Island يجب أن يكون عمرك 17 سنة و6 أشهر على الأقل لتحصل على رخصة قيادة كاملة.","p":"صحيح. أصغر عمر للرخصة الكاملة هو 17 سنة ونصف."},"ref":{"doc":"RI","page":14}},{"id":"ri-036","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, a teen wants to move up to the next license level. What must their record show for the last 6 months?","o":["Fewer than 3 points","No crashes of any kind","A finished defensive driving course","No moving violation and no seat belt ticket"],"h1":"Think of traffic tickets and buckling up.","h2":"In Rhode Island a teen moves up a license level only with no moving violation and no seat belt ticket in the last 6 months.","p":"Right. The last 6 months must be free of moving violations and seat belt tickets."},"es":{"q":"En Rhode Island, un adolescente quiere pasar al siguiente nivel de licencia. ¿Qué debe mostrar su historial de los últimos 6 meses?","o":["Menos de 3 puntos","Ningún choque de ningún tipo","Un curso de manejo defensivo terminado","Ninguna infracción de tránsito en movimiento y ninguna multa por el cinturón de seguridad"],"h1":"Piense en las multas de tránsito y en abrocharse el cinturón.","h2":"En Rhode Island un adolescente pasa al siguiente nivel de licencia solo si no tiene ninguna infracción en movimiento ni multa por el cinturón de seguridad en los últimos 6 meses.","p":"Correcto. Los últimos 6 meses deben estar libres de infracciones en movimiento y de multas por el cinturón."},"zh":{"q":"在 Rhode Island，一个青少年想升到下一级驾照。他最近 6 个月的记录必须是什么样？","o":["少于 3 分","没有任何车祸","完成了防御性驾驶课程","没有行车违规，也没有安全带罚单"],"h1":"想想交通罚单和系安全带。","h2":"在 Rhode Island，青少年只有在最近 6 个月没有行车违规、也没有安全带罚单时，才能升到下一级驾照。","p":"对。最近 6 个月必须没有行车违规和安全带罚单。"},"vi":{"q":"Ở Rhode Island, một thiếu niên muốn lên cấp bằng lái tiếp theo. Hồ sơ trong 6 tháng gần nhất phải như thế nào?","o":["Dưới 3 điểm","Không có tai nạn nào","Đã học xong khóa lái xe phòng vệ","Không vi phạm khi lái xe và không bị phạt vì dây an toàn"],"h1":"Hãy nghĩ đến vé phạt giao thông và việc thắt dây an toàn.","h2":"Ở Rhode Island, thiếu niên chỉ được lên cấp bằng lái khi không vi phạm khi lái xe và không bị phạt vì dây an toàn trong 6 tháng gần nhất.","p":"Đúng. 6 tháng gần nhất phải không có vi phạm khi lái xe và không có vé phạt dây an toàn."},"tl":{"q":"Sa Rhode Island, gustong umakyat ng isang teenager sa susunod na antas ng lisensya. Ano ang dapat ipakita ng kanyang record sa nakaraang 6 na buwan?","o":["Mas kaunti sa 3 puntos","Walang anumang banggaan","Tapos na ang defensive driving course","Walang moving violation at walang ticket sa seat belt"],"h1":"Isipin ang mga traffic ticket at ang pagsusuot ng seat belt.","h2":"Sa Rhode Island, makakaakyat lang ang teenager sa susunod na antas ng lisensya kung walang moving violation at walang ticket sa seat belt sa nakaraang 6 na buwan.","p":"Tama. Dapat walang moving violation at walang ticket sa seat belt sa nakaraang 6 na buwan."},"ar":{"q":"في Rhode Island، يريد مراهق أن ينتقل إلى المستوى التالي من الرخصة. ماذا يجب أن يُظهر سجله في آخر 6 أشهر؟","o":["أقل من 3 نقاط","لا حوادث من أي نوع","إنهاء دورة القيادة الوقائية","لا مخالفة قيادة ولا مخالفة حزام أمان"],"h1":"فكّر في مخالفات المرور وربط حزام الأمان.","h2":"في Rhode Island ينتقل المراهق إلى المستوى التالي من الرخصة فقط إذا لم تكن عليه مخالفة قيادة ولا مخالفة حزام أمان في آخر 6 أشهر.","p":"صحيح. يجب أن تكون آخر 6 أشهر بلا مخالفات قيادة وبلا مخالفات حزام أمان."},"ref":{"doc":"RI","page":12}},{"id":"ri-037","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, a teen is driving with a limited instruction permit. Who may sit in the front seat with them?","o":["Any passenger over 16","Only the supervising driver","The supervising driver and one friend","Nobody, the supervisor sits in back"],"h1":"The adult must be close enough to take control.","h2":"In Rhode Island only the supervising driver may sit in the front seat with a permit holder.","p":"Right. The supervising driver is the only other person in the front seat."},"es":{"q":"En Rhode Island, un adolescente maneja con un permiso limitado de aprendizaje. ¿Quién puede sentarse en el asiento delantero con él?","o":["Cualquier pasajero mayor de 16 años","Solo el conductor supervisor","El conductor supervisor y un amigo","Nadie, el supervisor se sienta atrás"],"h1":"El adulto debe estar lo bastante cerca para tomar el control.","h2":"En Rhode Island solo el conductor supervisor puede sentarse en el asiento delantero con quien tiene un permiso de aprendizaje.","p":"Correcto. El conductor supervisor es la única otra persona en el asiento delantero."},"zh":{"q":"在 Rhode Island，一个青少年持受限学习驾照开车。谁可以和他一起坐在前排？","o":["任何 16 岁以上的乘客","只有监督驾驶人","监督驾驶人和一个朋友","没有人，监督人坐在后排"],"h1":"成年人必须坐得够近，能接手控制车辆。","h2":"在 Rhode Island，只有监督驾驶人可以和学习驾照持有人一起坐在前排。","p":"对。前排的另一个人只能是监督驾驶人。"},"vi":{"q":"Ở Rhode Island, một thiếu niên đang lái xe với giấy phép tập lái có giới hạn. Ai được ngồi ở ghế trước cùng em?","o":["Bất kỳ hành khách nào trên 16 tuổi","Chỉ người lái xe giám sát","Người lái xe giám sát và một người bạn","Không ai cả, người giám sát ngồi phía sau"],"h1":"Người lớn phải ngồi đủ gần để điều khiển xe khi cần.","h2":"Ở Rhode Island, chỉ người lái xe giám sát được ngồi ở ghế trước cùng người có giấy phép tập lái.","p":"Đúng. Người lái xe giám sát là người duy nhất khác được ngồi ở ghế trước."},"tl":{"q":"Sa Rhode Island, nagmamaneho ang isang teenager na may limited instruction permit. Sino ang puwedeng umupo sa harap kasama niya?","o":["Kahit sinong pasahero na higit sa 16","Ang supervising driver lang","Ang supervising driver at isang kaibigan","Wala, sa likod umuupo ang supervisor"],"h1":"Dapat sapat na malapit ang adult para makontrol ang sasakyan.","h2":"Sa Rhode Island, ang supervising driver lang ang puwedeng umupo sa harap kasama ng may permit.","p":"Tama. Ang supervising driver lang ang ibang tao sa harap."},"ar":{"q":"في Rhode Island، يقود مراهق بتصريح تعلّم محدود. من يمكنه أن يجلس معه في المقعد الأمامي؟","o":["أي راكب عمره أكثر من 16","السائق المشرف فقط","السائق المشرف وصديق واحد","لا أحد، المشرف يجلس في الخلف"],"h1":"يجب أن يكون البالغ قريبًا بما يكفي ليتحكّم في السيارة.","h2":"في Rhode Island السائق المشرف فقط يمكنه أن يجلس في المقعد الأمامي مع حامل التصريح.","p":"صحيح. السائق المشرف هو الشخص الآخر الوحيد في المقعد الأمامي."},"ref":{"doc":"RI","page":15}},{"id":"ri-038","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, may a driver under 18 talk on a phone with a hands-free device?","o":["Yes, if it is hands-free","Yes, but only on the highway","No, except in an emergency","Yes, if a parent is calling"],"h1":"For young drivers the rule is stricter than for adults.","h2":"In Rhode Island a driver under 18 may not use a phone at all while driving, not even hands-free, except in an emergency.","p":"Right. Under 18, no phone use while driving, even hands-free, unless it is an emergency."},"es":{"q":"En Rhode Island, ¿puede un conductor menor de 18 años hablar por teléfono con un dispositivo de manos libres?","o":["Sí, si es de manos libres","Sí, pero solo en la autopista","No, excepto en una emergencia","Sí, si llama uno de sus padres"],"h1":"Para los conductores jóvenes la regla es más estricta que para los adultos.","h2":"En Rhode Island un conductor menor de 18 años no puede usar el teléfono mientras maneja, ni siquiera con manos libres, excepto en una emergencia.","p":"Correcto. Si es menor de 18 años, no use el teléfono al manejar, ni con manos libres, salvo en una emergencia."},"zh":{"q":"在 Rhode Island，18 岁以下的驾驶人可以用免提设备打电话吗？","o":["可以，只要是免提","可以，但只在高速公路上","不可以，紧急情况除外","可以，如果是父母打来的"],"h1":"对年轻驾驶人的规定比对成年人更严格。","h2":"在 Rhode Island，18 岁以下的驾驶人开车时完全不能用手机，免提也不行，紧急情况除外。","p":"对。18 岁以下开车时不能用手机，免提也不行，除非是紧急情况。"},"vi":{"q":"Ở Rhode Island, người lái xe dưới 18 tuổi có được nói chuyện điện thoại bằng thiết bị rảnh tay không?","o":["Được, nếu là rảnh tay","Được, nhưng chỉ trên xa lộ","Không, trừ khi khẩn cấp","Được, nếu cha mẹ gọi"],"h1":"Đối với người lái xe trẻ, luật nghiêm hơn so với người lớn.","h2":"Ở Rhode Island, người lái xe dưới 18 tuổi hoàn toàn không được dùng điện thoại khi lái xe, kể cả rảnh tay, trừ khi khẩn cấp.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại khi lái xe, kể cả rảnh tay, trừ khi khẩn cấp."},"tl":{"q":"Sa Rhode Island, puwede bang makipag-usap sa telepono gamit ang hands-free device ang driver na wala pang 18?","o":["Oo, kung hands-free","Oo, pero sa highway lang","Hindi, maliban kung emergency","Oo, kung magulang ang tumatawag"],"h1":"Mas mahigpit ang patakaran para sa mga batang driver kaysa sa mga adult.","h2":"Sa Rhode Island, ang driver na wala pang 18 ay hindi puwedeng gumamit ng telepono habang nagmamaneho, kahit hands-free, maliban kung emergency.","p":"Tama. Kapag wala pang 18, bawal gumamit ng telepono habang nagmamaneho, kahit hands-free, maliban kung emergency."},"ar":{"q":"في Rhode Island، هل يمكن لسائق عمره أقل من 18 سنة أن يتكلّم في الهاتف بجهاز بدون استخدام اليدين؟","o":["نعم، إذا كان بدون استخدام اليدين","نعم، لكن على الطريق السريع فقط","لا، إلا في حالة طوارئ","نعم، إذا كان المتصل أحد الوالدين"],"h1":"القاعدة للسائقين الصغار أشدّ منها للبالغين.","h2":"في Rhode Island يجب ألّا يستخدم السائق الذي عمره أقل من 18 سنة الهاتف أبدًا أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا في حالة طوارئ.","p":"صحيح. تحت 18 سنة، لا استخدام للهاتف أثناء القيادة، ولا حتى بدون استخدام اليدين، إلا في حالة طوارئ."},"ref":{"doc":"RI","page":35}},{"id":"ri-039","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, how close to a crosswalk at an intersection may you park?","o":["No closer than 20 feet","No closer than 10 feet","No closer than 5 feet","No closer than 50 feet"],"h1":"It is about the length of one big car plus a little more.","h2":"In Rhode Island you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Park at least 20 feet from a crosswalk at an intersection."},"es":{"q":"En Rhode Island, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 20 pies","No más cerca de 10 pies","No más cerca de 5 pies","No más cerca de 50 pies"],"h1":"Es más o menos el largo de un carro grande y un poco más.","h2":"En Rhode Island usted no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese por lo menos a 20 pies de un cruce peatonal en una intersección."},"zh":{"q":"在 Rhode Island，停车时可以离路口的人行横道多近？","o":["不能近于 20 英尺","不能近于 10 英尺","不能近于 5 英尺","不能近于 50 英尺"],"h1":"大约是一辆大车的长度再多一点。","h2":"在 Rhode Island，你不能在离路口人行横道 20 英尺以内停车。","p":"对。停车要离路口的人行横道至少 20 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần lối qua đường dành cho người đi bộ ở giao lộ đến mức nào?","o":["Không gần hơn 20 feet","Không gần hơn 10 feet","Không gần hơn 5 feet","Không gần hơn 50 feet"],"h1":"Khoảng chiều dài một chiếc xe lớn cộng thêm một chút.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 20 feet tính từ lối qua đường ở giao lộ.","p":"Đúng. Đậu xe cách lối qua đường ở giao lộ ít nhất 20 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa crosswalk sa intersection ka puwedeng pumarada?","o":["Hindi lalapit sa 20 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 5 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Mga haba ito ng isang malaking kotse at kaunti pa.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 20 talampakan mula sa crosswalk sa intersection.","p":"Tama. Pumarada nang hindi bababa sa 20 talampakan mula sa crosswalk sa intersection."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من ممر المشاة عند التقاطع؟","o":["ليس أقرب من 20 قدمًا","ليس أقرب من 10 أقدام","ليس أقرب من 5 أقدام","ليس أقرب من 50 قدمًا"],"h1":"إنها تقريبًا طول سيارة كبيرة وأكثر قليلًا.","h2":"في Rhode Island يجب ألّا تركن سيارتك على بعد أقل من 20 قدمًا من ممر المشاة عند التقاطع.","p":"صحيح. اركن على بعد 20 قدمًا على الأقل من ممر المشاة عند التقاطع."},"ref":{"doc":"RI","page":32}},{"id":"ri-040","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 25 feet","No closer than 50 feet"],"h1":"It is the largest of these distances.","h2":"In Rhode Island you may not park within 50 feet of the nearest rail of a railroad crossing, except for a short stop to load or unload.","p":"Right. Stay at least 50 feet from the nearest rail when you park."},"es":{"q":"En Rhode Island, ¿qué tan cerca del riel más cercano de un cruce de ferrocarril puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 25 pies","No más cerca de 50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Rhode Island usted no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril, excepto una parada corta para subir o bajar personas o cosas.","p":"Correcto. Al estacionarse, quédese por lo menos a 50 pies del riel más cercano."},"zh":{"q":"在 Rhode Island，停车时可以离铁路道口最近的铁轨多近？","o":["不能近于 10 英尺","不能近于 15 英尺","不能近于 25 英尺","不能近于 50 英尺"],"h1":"是这几个距离中最大的。","h2":"在 Rhode Island，你不能在离铁路道口最近铁轨 50 英尺以内停车，短暂停下上下人或装卸货物除外。","p":"对。停车时要离最近的铁轨至少 50 英尺。"},"vi":{"q":"Ở Rhode Island, bạn được đậu xe gần đường ray gần nhất của chỗ giao với đường sắt đến mức nào?","o":["Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 25 feet","Không gần hơn 50 feet"],"h1":"Đó là khoảng cách lớn nhất trong các lựa chọn.","h2":"Ở Rhode Island, bạn không được đậu xe trong vòng 50 feet tính từ đường ray gần nhất của chỗ giao với đường sắt, trừ khi dừng ngắn để đón, trả người hoặc bốc dỡ hàng.","p":"Đúng. Khi đậu xe, hãy cách đường ray gần nhất ít nhất 50 feet."},"tl":{"q":"Sa Rhode Island, gaano kalapit sa pinakamalapit na riles ng railroad crossing ka puwedeng pumarada?","o":["Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 25 talampakan","Hindi lalapit sa 50 talampakan"],"h1":"Ito ang pinakamalaki sa mga distansyang ito.","h2":"Sa Rhode Island, hindi ka puwedeng pumarada sa loob ng 50 talampakan mula sa pinakamalapit na riles ng railroad crossing, maliban sa maikling hinto para magsakay o magbaba.","p":"Tama. Lumayo nang hindi bababa sa 50 talampakan mula sa pinakamalapit na riles kapag pumarada ka."},"ar":{"q":"في Rhode Island، ما أقرب مسافة يمكنك أن تركن فيها سيارتك من أقرب قضيب في معبر السكة الحديدية؟","o":["ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 25 قدمًا","ليس أقرب من 50 قدمًا"],"h1":"إنها أكبر هذه المسافات.","h2":"في Rhode Island يجب ألّا تركن سيارتك على بعد أقل من 50 قدمًا من أقرب قضيب في معبر السكة الحديدية، إلا لتوقف قصير لإنزال أو تحميل.","p":"صحيح. ابقَ على بعد 50 قدمًا على الأقل من أقرب قضيب عندما تركن."},"ref":{"doc":"RI","page":32}},{"id":"ri-041","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, you park on a two-lane road. How far from the curb may your right wheels be?","o":["No more than 6 inches","No more than 12 inches","No more than 18 inches","No more than 24 inches"],"h1":"It is one foot.","h2":"In Rhode Island your right wheels must be no more than 12 inches from the curb or the edge of the road when you park.","p":"Right. Park with your right wheels within 12 inches of the curb."},"es":{"q":"En Rhode Island, usted se estaciona en una calle de dos carriles. ¿A qué distancia de la acera pueden estar sus ruedas derechas?","o":["No más de 6 pulgadas","No más de 12 pulgadas","No más de 18 pulgadas","No más de 24 pulgadas"],"h1":"Es un pie.","h2":"En Rhode Island, al estacionarse, sus ruedas derechas no deben estar a más de 12 pulgadas de la acera o del borde de la calle.","p":"Correcto. Estaciónese con las ruedas derechas a no más de 12 pulgadas de la acera."},"zh":{"q":"在 Rhode Island，你在双车道的路上停车。右边的车轮可以离路缘多远？","o":["不超过 6 英寸","不超过 12 英寸","不超过 18 英寸","不超过 24 英寸"],"h1":"是一英尺。","h2":"在 Rhode Island，停车时右边的车轮离路缘或路边不能超过 12 英寸。","p":"对。停车时右边车轮要在离路缘 12 英寸以内。"},"vi":{"q":"Ở Rhode Island, bạn đậu xe trên đường hai làn. Bánh xe bên phải được cách lề đường bao xa?","o":["Không quá 6 inch","Không quá 12 inch","Không quá 18 inch","Không quá 24 inch"],"h1":"Đó là một foot.","h2":"Ở Rhode Island, khi đậu xe, bánh xe bên phải phải cách lề hoặc mép đường không quá 12 inch.","p":"Đúng. Đậu xe với bánh bên phải cách lề không quá 12 inch."},"tl":{"q":"Sa Rhode Island, pumarada ka sa kalsadang may dalawang lane. Gaano kalayo sa gilid ng bangketa (curb) puwede ang iyong mga gulong sa kanan?","o":["Hindi hihigit sa 6 na pulgada","Hindi hihigit sa 12 pulgada","Hindi hihigit sa 18 pulgada","Hindi hihigit sa 24 na pulgada"],"h1":"Isang talampakan ito.","h2":"Sa Rhode Island, ang iyong mga gulong sa kanan ay dapat hindi hihigit sa 12 pulgada mula sa curb o sa gilid ng kalsada kapag pumarada ka.","p":"Tama. Pumarada nang nasa loob ng 12 pulgada mula sa curb ang mga gulong sa kanan."},"ar":{"q":"في Rhode Island، تركن سيارتك على طريق ذي مسارين. كم يمكن أن تبعد عجلاتك اليمنى عن الرصيف؟","o":["ليس أكثر من 6 بوصات","ليس أكثر من 12 بوصة","ليس أكثر من 18 بوصة","ليس أكثر من 24 بوصة"],"h1":"إنها قدم واحدة.","h2":"في Rhode Island يجب ألّا تبعد عجلاتك اليمنى أكثر من 12 بوصة عن الرصيف أو حافة الطريق عندما تركن.","p":"صحيح. اركن وعجلاتك اليمنى على بعد 12 بوصة أو أقل من الرصيف."},"ref":{"doc":"RI","page":32}},{"id":"ri-042","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Rhode Island, how far before a turn must you start to signal?","o":["At least 50 feet","At least 75 feet","At least 100 feet","At least 300 feet"],"h1":"It is a round number of feet.","h2":"In Rhode Island you must start to signal at least 100 feet before you turn or change lanes.","p":"Right. Signal at least 100 feet before a turn or lane change."},"es":{"q":"En Rhode Island, ¿a qué distancia antes de dar vuelta debe empezar a poner la señal?","o":["Por lo menos 50 pies","Por lo menos 75 pies","Por lo menos 100 pies","Por lo menos 300 pies"],"h1":"Es un número redondo de pies.","h2":"En Rhode Island usted debe empezar a poner la señal por lo menos 100 pies antes de dar vuelta o cambiar de carril.","p":"Correcto. Ponga la señal por lo menos 100 pies antes de dar vuelta o cambiar de carril."},"zh":{"q":"在 Rhode Island，转弯前至少要提前多远开始打灯？","o":["至少 50 英尺","至少 75 英尺","至少 100 英尺","至少 300 英尺"],"h1":"是一个整数的英尺数。","h2":"在 Rhode Island，转弯或换车道前，你必须至少提前 100 英尺开始打灯。","p":"对。转弯或换车道前至少 100 英尺打灯。"},"vi":{"q":"Ở Rhode Island, bạn phải bắt đầu bật xi nhan trước khi rẽ bao xa?","o":["Ít nhất 50 feet","Ít nhất 75 feet","Ít nhất 100 feet","Ít nhất 300 feet"],"h1":"Đó là một số feet tròn.","h2":"Ở Rhode Island, bạn phải bắt đầu bật xi nhan ít nhất 100 feet trước khi rẽ hoặc đổi làn.","p":"Đúng. Bật xi nhan ít nhất 100 feet trước khi rẽ hoặc đổi làn."},"tl":{"q":"Sa Rhode Island, gaano kalayo bago lumiko ka dapat magsimulang mag-signal?","o":["Hindi bababa sa 50 talampakan","Hindi bababa sa 75 talampakan","Hindi bababa sa 100 talampakan","Hindi bababa sa 300 talampakan"],"h1":"Ito ay isang buong bilang ng talampakan.","h2":"Sa Rhode Island, dapat kang magsimulang mag-signal nang hindi bababa sa 100 talampakan bago ka lumiko o lumipat ng lane.","p":"Tama. Mag-signal nang hindi bababa sa 100 talampakan bago lumiko o lumipat ng lane."},"ar":{"q":"في Rhode Island، على أي مسافة قبل المنعطف يجب أن تبدأ بإعطاء الإشارة؟","o":["50 قدمًا على الأقل","75 قدمًا على الأقل","100 قدم على الأقل","300 قدم على الأقل"],"h1":"إنه عدد أقدام مستدير.","h2":"في Rhode Island يجب أن تبدأ بإعطاء الإشارة قبل 100 قدم على الأقل من المنعطف أو من تغيير المسار.","p":"صحيح. أعطِ الإشارة قبل 100 قدم على الأقل من المنعطف أو تغيير المسار."},"ref":{"doc":"RI","page":55}},{"id":"ri-043","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, which vehicles may not travel in the far left lane of a freeway?","o":["Trucks and buses","Motorcycles","Cars with out-of-state plates","Cars with only one person inside"],"h1":"Think of the biggest and slowest vehicles.","h2":"In Rhode Island trucks, buses and other special vehicles may not travel in the far left lane of a freeway, which is for passing.","p":"Right. Trucks and buses stay out of the far left lane."},"es":{"q":"En Rhode Island, ¿qué vehículos no pueden ir por el carril de la extrema izquierda de una autopista?","o":["Camiones y autobuses","Motocicletas","Carros con placas de otro estado","Carros con una sola persona adentro"],"h1":"Piense en los vehículos más grandes y lentos.","h2":"En Rhode Island los camiones, autobuses y otros vehículos especiales no pueden ir por el carril de la extrema izquierda de una autopista, que es para rebasar.","p":"Correcto. Los camiones y autobuses no usan el carril de la extrema izquierda."},"zh":{"q":"在 Rhode Island，哪些车辆不能在高速公路（freeway）最左边的车道行驶？","o":["卡车和公共汽车","摩托车","挂外州车牌的汽车","车里只有一个人的汽车"],"h1":"想想最大、最慢的车。","h2":"在 Rhode Island，卡车、公共汽车和其他特殊车辆不能在高速公路最左边的车道行驶，那条车道是用来超车的。","p":"对。卡车和公共汽车不能走最左边的车道。"},"vi":{"q":"Ở Rhode Island, loại xe nào không được chạy ở làn ngoài cùng bên trái của xa lộ (freeway)?","o":["Xe tải và xe buýt","Xe máy","Xe mang biển số tiểu bang khác","Xe chỉ có một người bên trong"],"h1":"Hãy nghĩ đến những xe lớn nhất và chậm nhất.","h2":"Ở Rhode Island, xe tải, xe buýt và các loại xe đặc biệt khác không được chạy ở làn ngoài cùng bên trái của xa lộ, vì làn đó dùng để vượt.","p":"Đúng. Xe tải và xe buýt không chạy ở làn ngoài cùng bên trái."},"tl":{"q":"Sa Rhode Island, aling mga sasakyan ang hindi puwedeng dumaan sa pinakakaliwang lane ng freeway?","o":["Mga truck at bus","Mga motorsiklo","Mga kotseng may plaka ng ibang estado","Mga kotseng iisa lang ang sakay"],"h1":"Isipin ang pinakamalaki at pinakamabagal na mga sasakyan.","h2":"Sa Rhode Island, ang mga truck, bus at iba pang espesyal na sasakyan ay hindi puwedeng dumaan sa pinakakaliwang lane ng freeway, na para sa pag-overtake.","p":"Tama. Hindi dumadaan ang mga truck at bus sa pinakakaliwang lane."},"ar":{"q":"في Rhode Island، ما المركبات التي يجب ألّا تسير في المسار الأيسر الأقصى من الطريق السريع (freeway)؟","o":["الشاحنات والحافلات","الدراجات النارية","السيارات التي تحمل لوحات من ولاية أخرى","السيارات التي فيها شخص واحد فقط"],"h1":"فكّر في أكبر المركبات وأبطئها.","h2":"في Rhode Island يجب ألّا تسير الشاحنات والحافلات والمركبات الخاصة الأخرى في المسار الأيسر الأقصى من الطريق السريع، فهو مخصّص للتجاوز.","p":"صحيح. الشاحنات والحافلات تبقى خارج المسار الأيسر الأقصى."},"ref":{"doc":"RI","page":35}},{"id":"ri-044","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, you are using high beams at night. A car is coming toward you. When must you dim your lights?","o":["When it is 100 feet away","When it is 200 feet away","When it is 300 feet away","When it is still 500 feet away"],"h1":"Dim them early, long before the car is close.","h2":"In Rhode Island you must dim your high beams when a car coming toward you is still 500 feet away.","p":"Right. Dim your high beams for an oncoming car at 500 feet."},"es":{"q":"En Rhode Island, usted lleva las luces altas de noche. Un carro viene hacia usted. ¿Cuándo debe bajar las luces?","o":["Cuando está a 100 pies","Cuando está a 200 pies","Cuando está a 300 pies","Cuando todavía está a 500 pies"],"h1":"Bájelas temprano, mucho antes de que el carro esté cerca.","h2":"En Rhode Island usted debe bajar las luces altas cuando un carro que viene hacia usted todavía está a 500 pies.","p":"Correcto. Baje las luces altas a 500 pies de un carro que viene de frente."},"zh":{"q":"在 Rhode Island，你晚上开着远光灯。一辆车迎面开来。你什么时候必须把灯调暗？","o":["在它离你 100 英尺时","在它离你 200 英尺时","在它离你 300 英尺时","在它还离你 500 英尺时"],"h1":"要早点调暗，在那辆车离你很近之前。","h2":"在 Rhode Island，当迎面来的车还在 500 英尺远时，你就必须把远光灯调暗。","p":"对。迎面有车时，在 500 英尺远就要把远光灯调暗。"},"vi":{"q":"Ở Rhode Island, bạn đang bật đèn pha (đèn chiếu xa) vào ban đêm. Có một xe chạy ngược chiều về phía bạn. Khi nào bạn phải giảm đèn?","o":["Khi xe đó cách 100 feet","Khi xe đó cách 200 feet","Khi xe đó cách 300 feet","Khi xe đó vẫn còn cách 500 feet"],"h1":"Hãy giảm đèn sớm, trước khi xe kia đến gần.","h2":"Ở Rhode Island, bạn phải giảm đèn pha khi xe chạy ngược chiều vẫn còn cách bạn 500 feet.","p":"Đúng. Giảm đèn pha khi xe ngược chiều còn cách 500 feet."},"tl":{"q":"Sa Rhode Island, gumagamit ka ng high beams sa gabi. May kotseng paparating sa iyo. Kailan mo dapat hinaan ang iyong ilaw?","o":["Kapag 100 talampakan na lang ang layo nito","Kapag 200 talampakan na lang ang layo nito","Kapag 300 talampakan na lang ang layo nito","Kapag 500 talampakan pa ang layo nito"],"h1":"Hinaan ito nang maaga, bago pa lumapit ang kotse.","h2":"Sa Rhode Island, dapat mong hinaan ang iyong high beams kapag ang paparating na kotse ay 500 talampakan pa ang layo.","p":"Tama. Hinaan ang high beams para sa paparating na kotse sa 500 talampakan."},"ar":{"q":"في Rhode Island، تستخدم الأضواء العالية ليلًا. سيارة قادمة نحوك. متى يجب أن تخفّض أضواءك؟","o":["عندما تكون على بعد 100 قدم","عندما تكون على بعد 200 قدم","عندما تكون على بعد 300 قدم","عندما تكون ما زالت على بعد 500 قدم"],"h1":"خفّضها مبكرًا، قبل أن تقترب السيارة بكثير.","h2":"في Rhode Island يجب أن تخفّض أضواءك العالية عندما تكون السيارة القادمة نحوك ما زالت على بعد 500 قدم.","p":"صحيح. خفّض أضواءك العالية للسيارة القادمة على بعد 500 قدم."},"ref":{"doc":"RI","page":49}},{"id":"ri-045","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, does the rule to stop for a school bus with flashing red lights apply in a parking lot?","o":["No, only on public highways","Yes, on private roads and in parking lots too","Only if a police officer is there","Only on school property"],"h1":"Children can step off a bus anywhere.","h2":"In Rhode Island you must stop for a school bus with flashing red lights on public highways, on private roads and in parking lots.","p":"Right. The school bus stop rule also applies on private roads and in parking lots."},"es":{"q":"En Rhode Island, ¿la regla de detenerse ante un autobús escolar con luces rojas intermitentes se aplica en un estacionamiento?","o":["No, solo en las carreteras públicas","Sí, también en caminos privados y estacionamientos","Solo si hay un policía presente","Solo en terrenos de la escuela"],"h1":"Los niños pueden bajar de un autobús en cualquier lugar.","h2":"En Rhode Island usted debe detenerse ante un autobús escolar con luces rojas intermitentes en las carreteras públicas, en los caminos privados y en los estacionamientos.","p":"Correcto. La regla del autobús escolar también se aplica en caminos privados y estacionamientos."},"zh":{"q":"在 Rhode Island，校车亮着闪烁红灯时必须停车的规定，在停车场也适用吗？","o":["不适用，只在公共道路上","适用，在私人道路和停车场也适用","只在有警察时","只在学校里"],"h1":"孩子可能在任何地方下校车。","h2":"在 Rhode Island，校车亮着闪烁红灯时，你必须停车，不论是在公共道路、私人道路还是停车场。","p":"对。为校车停车的规定在私人道路和停车场也适用。"},"vi":{"q":"Ở Rhode Island, luật phải dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy có áp dụng trong bãi đậu xe không?","o":["Không, chỉ trên đường công cộng","Có, cả trên đường tư và trong bãi đậu xe","Chỉ khi có cảnh sát ở đó","Chỉ trong khuôn viên trường"],"h1":"Trẻ em có thể bước xuống xe buýt ở bất cứ đâu.","h2":"Ở Rhode Island, bạn phải dừng lại khi xe buýt trường học bật đèn đỏ nhấp nháy trên đường công cộng, trên đường tư và trong bãi đậu xe.","p":"Đúng. Luật dừng cho xe buýt trường học cũng áp dụng trên đường tư và trong bãi đậu xe."},"tl":{"q":"Sa Rhode Island, ang patakaran bang huminto para sa school bus na may kumikislap na pulang ilaw ay ipinapatupad din sa parking lot?","o":["Hindi, sa mga pampublikong highway lang","Oo, pati sa mga pribadong kalsada at parking lot","Kung may pulis lang doon","Sa loob lang ng paaralan"],"h1":"Puwedeng bumaba ang mga bata sa bus kahit saan.","h2":"Sa Rhode Island, dapat kang huminto para sa school bus na may kumikislap na pulang ilaw sa mga pampublikong highway, sa mga pribadong kalsada at sa mga parking lot.","p":"Tama. Ang patakaran sa paghinto para sa school bus ay ipinapatupad din sa mga pribadong kalsada at parking lot."},"ar":{"q":"في Rhode Island، هل قاعدة التوقف لحافلة مدرسية أضواؤها الحمراء تومض تنطبق في موقف السيارات؟","o":["لا، على الطرق العامة فقط","نعم، على الطرق الخاصة وفي مواقف السيارات أيضًا","فقط إذا كان شرطي هناك","فقط داخل أرض المدرسة"],"h1":"يمكن أن ينزل الأطفال من الحافلة في أي مكان.","h2":"في Rhode Island يجب أن تتوقف لحافلة مدرسية أضواؤها الحمراء تومض على الطرق العامة وعلى الطرق الخاصة وفي مواقف السيارات.","p":"صحيح. قاعدة التوقف للحافلة المدرسية تنطبق أيضًا على الطرق الخاصة وفي مواقف السيارات."},"ref":{"doc":"RI","page":51}},{"id":"ri-046","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, a police officer stops you at night. What must you do with the lights inside your car?","o":["Keep them off so the officer can see better","Flash them once to show you saw the officer","Turn them on and leave them on until the officer lets you go","Turn them on only if the officer asks"],"h1":"The officer needs to see inside your car.","h2":"In Rhode Island, when police stop you at night, you must turn on your inside lights and leave them on until the officer lets you drive off.","p":"Right. At night, turn on your inside lights and keep them on until the officer lets you go."},"es":{"q":"En Rhode Island, un policía lo detiene de noche. ¿Qué debe hacer con las luces de adentro de su carro?","o":["Dejarlas apagadas para que el policía vea mejor","Prenderlas y apagarlas una vez para mostrar que vio al policía","Prenderlas y dejarlas prendidas hasta que el policía lo deje ir","Prenderlas solo si el policía se lo pide"],"h1":"El policía necesita ver dentro de su carro.","h2":"En Rhode Island, cuando la policía lo detiene de noche, usted debe prender las luces de adentro y dejarlas prendidas hasta que el policía le permita irse.","p":"Correcto. De noche, prenda las luces de adentro y déjelas prendidas hasta que el policía lo deje ir."},"zh":{"q":"在 Rhode Island，晚上警察让你停车。你必须怎么处理车内的灯？","o":["关着，让警察看得更清楚","闪一下，表示你看到了警察","打开，并一直开着，直到警察让你离开","只有警察要求时才打开"],"h1":"警察需要看清你车里面。","h2":"在 Rhode Island，晚上被警察拦下时，你必须打开车内灯，并一直开着，直到警察让你开走。","p":"对。晚上要打开车内灯，并一直开着，直到警察让你离开。"},"vi":{"q":"Ở Rhode Island, cảnh sát chặn xe bạn vào ban đêm. Bạn phải làm gì với đèn bên trong xe?","o":["Tắt đèn để cảnh sát nhìn rõ hơn","Bật tắt một lần để cho thấy bạn đã thấy cảnh sát","Bật đèn và để đèn sáng cho đến khi cảnh sát cho bạn đi","Chỉ bật đèn nếu cảnh sát yêu cầu"],"h1":"Cảnh sát cần nhìn thấy bên trong xe bạn.","h2":"Ở Rhode Island, khi cảnh sát chặn xe bạn vào ban đêm, bạn phải bật đèn trong xe và để đèn sáng cho đến khi cảnh sát cho bạn lái đi.","p":"Đúng. Vào ban đêm, bật đèn trong xe và để sáng cho đến khi cảnh sát cho bạn đi."},"tl":{"q":"Sa Rhode Island, pinahinto ka ng pulis sa gabi. Ano ang dapat mong gawin sa mga ilaw sa loob ng iyong kotse?","o":["Patayin ang mga ito para mas makakita ang pulis","Paandap-andapin nang isang beses para ipakitang nakita mo ang pulis","Buksan ang mga ito at iwanang bukas hanggang paalisin ka ng pulis","Buksan lang kung hihilingin ng pulis"],"h1":"Kailangang makita ng pulis ang loob ng iyong kotse.","h2":"Sa Rhode Island, kapag pinahinto ka ng pulis sa gabi, dapat mong buksan ang mga ilaw sa loob at iwanang bukas hanggang payagan ka ng pulis na umalis.","p":"Tama. Sa gabi, buksan ang mga ilaw sa loob at iwanang bukas hanggang paalisin ka ng pulis."},"ar":{"q":"في Rhode Island، أوقفك شرطي ليلًا. ماذا يجب أن تفعل بالأضواء داخل سيارتك؟","o":["تتركها مطفأة ليرى الشرطي بشكل أفضل","تومض بها مرة لتُظهر أنك رأيت الشرطي","تشعلها وتتركها مشتعلة حتى يسمح لك الشرطي بالذهاب","تشعلها فقط إذا طلب الشرطي"],"h1":"يحتاج الشرطي إلى أن يرى داخل سيارتك.","h2":"في Rhode Island، عندما توقفك الشرطة ليلًا، يجب أن تشعل الأضواء داخل سيارتك وتتركها مشتعلة حتى يسمح لك الشرطي بالانطلاق.","p":"صحيح. ليلًا، أشعل الأضواء الداخلية واتركها مشتعلة حتى يسمح لك الشرطي بالذهاب."},"ref":{"doc":"RI","page":55}},{"id":"ri-047","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, who must wear a helmet when riding a bicycle on a public road?","o":["Riders and passengers age 15 or younger","Only riders under 12","All riders of any age","Only riders on state highways"],"h1":"The law covers children and young teens.","h2":"In Rhode Island every bicycle rider or passenger age 15 or younger must wear a certified helmet on public roads and paths.","p":"Right. Bicycle riders and passengers 15 or younger must wear a helmet."},"es":{"q":"En Rhode Island, ¿quién debe usar casco al andar en bicicleta en una vía pública?","o":["Ciclistas y pasajeros de 15 años o menos","Solo los ciclistas menores de 12 años","Todos los ciclistas de cualquier edad","Solo los ciclistas en carreteras estatales"],"h1":"La ley protege a los niños y a los adolescentes más jóvenes.","h2":"En Rhode Island todo ciclista o pasajero de bicicleta de 15 años o menos debe usar un casco certificado en las vías y senderos públicos.","p":"Correcto. Los ciclistas y pasajeros de 15 años o menos deben usar casco."},"zh":{"q":"在 Rhode Island，在公共道路上骑自行车时，谁必须戴头盔？","o":["15 岁或以下的骑车人和乘客","只有 12 岁以下的骑车人","所有年龄的骑车人","只有在州公路上的骑车人"],"h1":"这条法律保护儿童和年纪小的青少年。","h2":"在 Rhode Island，在公共道路和小路上，每一个 15 岁或以下的自行车骑车人或乘客都必须戴合格的头盔。","p":"对。15 岁或以下的自行车骑车人和乘客必须戴头盔。"},"vi":{"q":"Ở Rhode Island, ai phải đội mũ bảo hiểm khi đi xe đạp trên đường công cộng?","o":["Người đi xe và người ngồi sau từ 15 tuổi trở xuống","Chỉ người đi xe dưới 12 tuổi","Tất cả người đi xe ở mọi lứa tuổi","Chỉ người đi xe trên xa lộ của tiểu bang"],"h1":"Luật này áp dụng cho trẻ em và thiếu niên nhỏ tuổi.","h2":"Ở Rhode Island, mọi người đi xe đạp hoặc người ngồi sau từ 15 tuổi trở xuống phải đội mũ bảo hiểm đạt chuẩn trên đường và lối đi công cộng.","p":"Đúng. Người đi xe đạp và người ngồi sau từ 15 tuổi trở xuống phải đội mũ bảo hiểm."},"tl":{"q":"Sa Rhode Island, sino ang dapat magsuot ng helmet kapag nagbibisikleta sa pampublikong kalsada?","o":["Mga rider at pasahero na 15 taong gulang pababa","Mga rider lang na wala pang 12","Lahat ng rider kahit anong edad","Mga rider lang sa mga state highway"],"h1":"Sakop ng batas ang mga bata at mga batang teenager.","h2":"Sa Rhode Island, bawat rider o pasahero ng bisikleta na 15 taong gulang pababa ay dapat magsuot ng certified helmet sa mga pampublikong kalsada at daanan.","p":"Tama. Ang mga rider at pasahero ng bisikleta na 15 pababa ay dapat magsuot ng helmet."},"ar":{"q":"في Rhode Island، من يجب أن يلبس خوذة عند ركوب دراجة هوائية على طريق عام؟","o":["الراكبون والركاب الذين عمرهم 15 سنة أو أقل","الراكبون الذين عمرهم أقل من 12 فقط","كل الراكبين من أي عمر","الراكبون على طرق الولاية السريعة فقط"],"h1":"القانون يشمل الأطفال والمراهقين الصغار.","h2":"في Rhode Island يجب على كل راكب أو راكب خلفي لدراجة هوائية عمره 15 سنة أو أقل أن يلبس خوذة معتمدة على الطرق والممرات العامة.","p":"صحيح. راكبو الدراجات الهوائية وركّابها الذين عمرهم 15 سنة أو أقل يجب أن يلبسوا خوذة."},"ref":{"doc":"RI","page":51}},{"id":"ri-048","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, who must wear a helmet on a motorcycle?","o":["Only riders under 18","Nobody, helmets are a choice","Only the operator, never the passenger","Every passenger, operators under 21, and new operators in their first year"],"h1":"Passengers are always included.","h2":"In Rhode Island every motorcycle passenger, every operator under 21, and every new operator during the first year of the license must wear a helmet.","p":"Right. Passengers, operators under 21 and first-year operators must wear helmets."},"es":{"q":"En Rhode Island, ¿quién debe usar casco en una motocicleta?","o":["Solo los menores de 18 años","Nadie, el casco es opcional","Solo el conductor, nunca el pasajero","Todos los pasajeros, los conductores menores de 21 años y los conductores nuevos en su primer año"],"h1":"Los pasajeros siempre están incluidos.","h2":"En Rhode Island todo pasajero de motocicleta, todo conductor menor de 21 años y todo conductor nuevo durante el primer año de su licencia debe usar casco.","p":"Correcto. Los pasajeros, los conductores menores de 21 y los de primer año deben usar casco."},"zh":{"q":"在 Rhode Island，骑摩托车时谁必须戴头盔？","o":["只有 18 岁以下的骑手","没有人，戴不戴头盔自己选","只有驾驶人，乘客不用","所有乘客、21 岁以下的驾驶人，以及拿驾照第一年的新驾驶人"],"h1":"乘客总是包括在内。","h2":"在 Rhode Island，每一位摩托车乘客、每一位 21 岁以下的驾驶人，以及每一位拿驾照第一年的新驾驶人都必须戴头盔。","p":"对。乘客、21 岁以下的驾驶人和第一年的驾驶人必须戴头盔。"},"vi":{"q":"Ở Rhode Island, ai phải đội mũ bảo hiểm khi đi xe máy?","o":["Chỉ người lái dưới 18 tuổi","Không ai cả, đội mũ là tùy ý","Chỉ người lái, không bao giờ là người ngồi sau","Mọi người ngồi sau, người lái dưới 21 tuổi và người lái mới trong năm đầu tiên"],"h1":"Người ngồi sau luôn nằm trong số này.","h2":"Ở Rhode Island, mọi người ngồi sau xe máy, mọi người lái dưới 21 tuổi và mọi người lái mới trong năm đầu tiên có bằng phải đội mũ bảo hiểm.","p":"Đúng. Người ngồi sau, người lái dưới 21 tuổi và người lái năm đầu phải đội mũ bảo hiểm."},"tl":{"q":"Sa Rhode Island, sino ang dapat magsuot ng helmet sa motorsiklo?","o":["Mga rider lang na wala pang 18","Wala, pinipili lang ang helmet","Ang nagmamaneho lang, hindi kailanman ang pasahero","Bawat pasahero, mga nagmamaneho na wala pang 21, at mga bagong nagmamaneho sa unang taon nila"],"h1":"Laging kasama ang mga pasahero.","h2":"Sa Rhode Island, bawat pasahero ng motorsiklo, bawat nagmamaneho na wala pang 21, at bawat bagong nagmamaneho sa unang taon ng lisensya ay dapat magsuot ng helmet.","p":"Tama. Ang mga pasahero, nagmamaneho na wala pang 21 at mga nasa unang taon ay dapat magsuot ng helmet."},"ar":{"q":"في Rhode Island، من يجب أن يلبس خوذة على الدراجة النارية؟","o":["الراكبون الذين عمرهم أقل من 18 فقط","لا أحد، الخوذة اختيارية","السائق فقط، وليس الراكب أبدًا","كل راكب، والسائقون الذين عمرهم أقل من 21، والسائقون الجدد في سنتهم الأولى"],"h1":"الركاب مشمولون دائمًا.","h2":"في Rhode Island يجب على كل راكب دراجة نارية، وكل سائق عمره أقل من 21، وكل سائق جديد في السنة الأولى من رخصته أن يلبس خوذة.","p":"صحيح. الركاب والسائقون الذين عمرهم أقل من 21 والسائقون في سنتهم الأولى يجب أن يلبسوا خوذة."},"ref":{"doc":"RI","page":46}},{"id":"ri-049","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, may you wear earphones to listen to music while you drive?","o":["Yes, on short trips","No, it is not allowed","Yes, if the music is quiet","Yes, but only on the highway"],"h1":"You need to hear horns and sirens.","h2":"In Rhode Island you may not drive on a public road while wearing earphones or a headset to listen to music; the law only allows things like hearing aids or a phone headset that covers one ear.","p":"Right. No earphones or headsets for music while driving."},"es":{"q":"En Rhode Island, ¿puede usar audífonos para escuchar música mientras maneja?","o":["Sí, en viajes cortos","No, no está permitido","Sí, si la música está baja","Sí, pero solo en la autopista"],"h1":"Usted necesita oír las bocinas y las sirenas.","h2":"En Rhode Island usted no puede manejar en una vía pública con audífonos o auriculares puestos para escuchar música; la ley solo permite cosas como aparatos para la sordera o un auricular de teléfono que cubre un solo oído.","p":"Correcto. Nada de audífonos ni auriculares para música al manejar."},"zh":{"q":"在 Rhode Island，开车时可以戴耳机听音乐吗？","o":["可以，短途时可以","不可以，这是不允许的","可以，如果音乐声音小","可以，但只在高速公路上"],"h1":"你需要听到喇叭声和警笛声。","h2":"在 Rhode Island，在公共道路上开车时，你不能戴耳机或头戴式耳机听音乐；法律只允许助听器或只盖住一只耳朵的电话耳机这类东西。","p":"对。开车时不能戴耳机或头戴式耳机听音乐。"},"vi":{"q":"Ở Rhode Island, bạn có được đeo tai nghe để nghe nhạc khi lái xe không?","o":["Được, khi đi đoạn ngắn","Không, điều này không được phép","Được, nếu nhạc nhỏ","Được, nhưng chỉ trên xa lộ"],"h1":"Bạn cần nghe được tiếng còi xe và còi hụ.","h2":"Ở Rhode Island, bạn không được lái xe trên đường công cộng khi đeo tai nghe hoặc headset để nghe nhạc; luật chỉ cho phép những thứ như máy trợ thính hoặc tai nghe điện thoại che một bên tai.","p":"Đúng. Không đeo tai nghe hoặc headset để nghe nhạc khi lái xe."},"tl":{"q":"Sa Rhode Island, puwede ka bang magsuot ng earphones para makinig ng musika habang nagmamaneho?","o":["Oo, sa maiikling biyahe","Hindi, hindi ito pinapayagan","Oo, kung mahina ang musika","Oo, pero sa highway lang"],"h1":"Kailangan mong marinig ang mga busina at sirena.","h2":"Sa Rhode Island, hindi ka puwedeng magmaneho sa pampublikong kalsada habang may suot na earphones o headset para makinig ng musika; ang pinapayagan lang ng batas ay mga bagay tulad ng hearing aid o phone headset na tumatakip sa isang tainga.","p":"Tama. Bawal ang earphones o headset para sa musika habang nagmamaneho."},"ar":{"q":"في Rhode Island، هل يمكنك أن تلبس سماعات الأذن لتستمع إلى الموسيقى أثناء القيادة؟","o":["نعم، في الرحلات القصيرة","لا، هذا غير مسموح","نعم، إذا كانت الموسيقى هادئة","نعم، لكن على الطريق السريع فقط"],"h1":"تحتاج إلى أن تسمع أبواق السيارات وصفارات الإنذار.","h2":"في Rhode Island يجب ألّا تقود على طريق عام وأنت تلبس سماعات أذن أو سماعة رأس لتستمع إلى الموسيقى؛ القانون يسمح فقط بأشياء مثل أجهزة السمع أو سماعة هاتف تغطي أذنًا واحدة.","p":"صحيح. لا سماعات أذن ولا سماعات رأس للموسيقى أثناء القيادة."},"ref":{"doc":"RI","page":55}},{"id":"ri-050","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, nobody is hurt in a crash. When is a police report required?","o":["Never, if the drivers agree","Only if a car must be towed","When the property damage is over $1,000","Only if it happens on an interstate"],"h1":"It depends on how much damage there is.","h2":"In Rhode Island a police report is required when a crash causes property damage over $1,000, even if nobody is hurt.","p":"Right. Property damage over $1,000 means a police report is required."},"es":{"q":"En Rhode Island, nadie sale herido en un choque. ¿Cuándo se requiere un informe de la policía?","o":["Nunca, si los conductores se ponen de acuerdo","Solo si hay que remolcar un carro","Cuando los daños a la propiedad pasan de $1,000","Solo si ocurre en una carretera interestatal"],"h1":"Depende de cuántos daños hay.","h2":"En Rhode Island se requiere un informe de la policía cuando un choque causa daños a la propiedad de más de $1,000, aunque nadie salga herido.","p":"Correcto. Si los daños pasan de $1,000, se requiere un informe de la policía."},"zh":{"q":"在 Rhode Island，车祸中没有人受伤。什么时候必须报警做报告？","o":["从不需要，只要双方司机同意","只有车必须被拖走时","财产损失超过 $1,000 时","只有发生在州际公路上时"],"h1":"要看损失有多大。","h2":"在 Rhode Island，车祸造成的财产损失超过 $1,000 时，就必须报警做报告，即使没有人受伤。","p":"对。财产损失超过 $1,000，就必须做警察报告。"},"vi":{"q":"Ở Rhode Island, không ai bị thương trong một vụ tai nạn. Khi nào cần báo cáo với cảnh sát?","o":["Không bao giờ, nếu các tài xế đồng ý","Chỉ khi có xe phải kéo đi","Khi thiệt hại tài sản trên $1,000","Chỉ khi xảy ra trên xa lộ liên bang"],"h1":"Điều này tùy vào mức thiệt hại.","h2":"Ở Rhode Island, cần có báo cáo cảnh sát khi tai nạn gây thiệt hại tài sản trên $1,000, kể cả khi không ai bị thương.","p":"Đúng. Thiệt hại tài sản trên $1,000 nghĩa là phải có báo cáo cảnh sát."},"tl":{"q":"Sa Rhode Island, walang nasaktan sa isang banggaan. Kailan kailangan ang police report?","o":["Hindi kailanman, kung magkasundo ang mga driver","Kung may kotseng kailangang i-tow lang","Kapag ang pinsala sa ari-arian ay higit sa $1,000","Kung nangyari lang ito sa interstate"],"h1":"Depende ito sa laki ng pinsala.","h2":"Sa Rhode Island, kailangan ang police report kapag ang banggaan ay nagdulot ng pinsala sa ari-arian na higit sa $1,000, kahit walang nasaktan.","p":"Tama. Kapag higit sa $1,000 ang pinsala sa ari-arian, kailangan ang police report."},"ar":{"q":"في Rhode Island، لم يُصب أحد في حادث. متى يكون تقرير الشرطة مطلوبًا؟","o":["أبدًا، إذا اتفق السائقون","فقط إذا كان يجب سحب سيارة","عندما تكون الأضرار في الممتلكات أكثر من $1,000","فقط إذا وقع على طريق سريع بين الولايات"],"h1":"يعتمد ذلك على حجم الأضرار.","h2":"في Rhode Island يكون تقرير الشرطة مطلوبًا عندما يسبّب الحادث أضرارًا في الممتلكات أكثر من $1,000، حتى لو لم يُصب أحد.","p":"صحيح. أضرار في الممتلكات أكثر من $1,000 تعني أن تقرير الشرطة مطلوب."},"ref":{"doc":"RI","page":62}},{"id":"ri-051","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, when are speeding fines doubled in a construction work zone?","o":["24 hours a day","Only when workers are present","Only during daylight","Only on weekdays"],"h1":"The rule does not depend on the time.","h2":"In Rhode Island speeding fines in a marked work zone are doubled 24 hours a day.","p":"Right. Work zone speeding fines are doubled at all hours."},"es":{"q":"En Rhode Island, ¿cuándo se duplican las multas por exceso de velocidad en una zona de construcción?","o":["Las 24 horas del día","Solo cuando hay trabajadores","Solo durante el día","Solo de lunes a viernes"],"h1":"La regla no depende de la hora.","h2":"En Rhode Island las multas por exceso de velocidad en una zona de trabajo señalizada se duplican las 24 horas del día.","p":"Correcto. Las multas por velocidad en zonas de trabajo se duplican a toda hora."},"zh":{"q":"在 Rhode Island，施工区内超速的罚款什么时候加倍？","o":["一天 24 小时","只有工人在场时","只在白天","只在工作日"],"h1":"这条规定和时间无关。","h2":"在 Rhode Island，在有标志的施工区内超速，罚款一天 24 小时都加倍。","p":"对。施工区超速罚款在任何时间都加倍。"},"vi":{"q":"Ở Rhode Island, khi nào tiền phạt chạy quá tốc độ trong khu vực công trường bị tăng gấp đôi?","o":["24 giờ một ngày","Chỉ khi có công nhân","Chỉ vào ban ngày","Chỉ vào các ngày trong tuần"],"h1":"Luật này không phụ thuộc vào thời gian.","h2":"Ở Rhode Island, tiền phạt chạy quá tốc độ trong khu vực công trường có biển báo được tăng gấp đôi 24 giờ một ngày.","p":"Đúng. Tiền phạt chạy quá tốc độ trong khu vực công trường tăng gấp đôi vào mọi giờ."},"tl":{"q":"Sa Rhode Island, kailan dinodoble ang multa sa sobrang bilis sa construction work zone?","o":["24 na oras sa isang araw","Kapag may mga trabahador lang","Sa araw lang","Sa mga weekday lang"],"h1":"Hindi nakadepende sa oras ang patakaran.","h2":"Sa Rhode Island, ang multa sa sobrang bilis sa isang may-markang work zone ay dinodoble 24 na oras sa isang araw.","p":"Tama. Doble ang multa sa sobrang bilis sa work zone sa lahat ng oras."},"ar":{"q":"في Rhode Island، متى تتضاعف غرامات السرعة الزائدة في منطقة أعمال البناء؟","o":["24 ساعة في اليوم","فقط عندما يكون العمال موجودين","فقط في النهار","فقط في أيام العمل"],"h1":"القاعدة لا تعتمد على الوقت.","h2":"في Rhode Island تتضاعف غرامات السرعة الزائدة في منطقة الأعمال المحدّدة بعلامات 24 ساعة في اليوم.","p":"صحيح. غرامات السرعة في منطقة الأعمال تتضاعف في كل الساعات."},"ref":{"doc":"RI","page":71}},{"id":"ri-052","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, how old must a teen be when the driver education class begins?","o":["At least 15 years and 10 months","At least 14 years","At least 16 years and 6 months","At least 17 years"],"h1":"It is a little before the 16th birthday.","h2":"In Rhode Island a teen may sign up for driver education from age 15, as long as they are at least 15 years and 10 months old when the class begins.","p":"Right. You must be at least 15 years and 10 months old when class starts."},"es":{"q":"En Rhode Island, ¿qué edad debe tener un adolescente cuando empieza la clase de educación vial?","o":["Por lo menos 15 años y 10 meses","Por lo menos 14 años","Por lo menos 16 años y 6 meses","Por lo menos 17 años"],"h1":"Es un poco antes de cumplir 16 años.","h2":"En Rhode Island un adolescente puede inscribirse en educación vial desde los 15 años, siempre que tenga por lo menos 15 años y 10 meses cuando empiece la clase.","p":"Correcto. Debe tener por lo menos 15 años y 10 meses al empezar la clase."},"ref":{"doc":"RI","page":10}},{"id":"ri-053","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, you are 19 and have never had a license. Must you take the 33-hour driver education class?","o":["No, and you do not need any test","No, but you must pass the computerized test","Yes, everyone must take it","Yes, and a second class for adults"],"h1":"The class is required only for people under 18.","h2":"In Rhode Island an applicant over 18 does not have to take the classroom course but must still pass the computerized knowledge test.","p":"Right. Adults skip the class but still take the computerized test."},"es":{"q":"En Rhode Island, usted tiene 19 años y nunca ha tenido licencia. ¿Debe tomar la clase de educación vial de 33 horas?","o":["No, y no necesita ningún examen","No, pero debe aprobar el examen en computadora","Sí, todos deben tomarla","Sí, y otra clase para adultos"],"h1":"La clase es obligatoria solo para menores de 18.","h2":"En Rhode Island, un solicitante mayor de 18 años no tiene que tomar la clase, pero sí debe aprobar el examen de conocimientos en computadora.","p":"Correcto. Los adultos no toman la clase, pero sí el examen en computadora."},"ref":{"doc":"RI","page":10}},{"id":"ri-054","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the longest time allowed for the computerized knowledge test?","o":["45 minutes","3 hours","90 minutes","30 minutes"],"h1":"It is an hour and a half, though most people finish much sooner.","h2":"Rhode Island's computerized knowledge test has a 90-minute limit, although it usually takes only 20 to 30 minutes.","p":"Right. You have up to 90 minutes."},"es":{"q":"En Rhode Island, ¿cuál es el tiempo máximo permitido para el examen de conocimientos en computadora?","o":["45 minutos","3 horas","90 minutos","30 minutos"],"h1":"Es una hora y media, aunque casi todos terminan mucho antes.","h2":"El examen de conocimientos en computadora de Rhode Island tiene un límite de 90 minutos, aunque por lo general toma solo de 20 a 30 minutos.","p":"Correcto. Tiene hasta 90 minutos."},"ref":{"doc":"RI","page":10}},{"id":"ri-055","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, you hold an active driver's license from another country. What must you do to get a Rhode Island license?","o":["Nothing; just trade in your license","Only pass a vision test","Only take the 33-hour class","Pass both the knowledge test and the road test"],"h1":"A foreign license does not excuse you from the tests.","h2":"In Rhode Island a person with a license from a foreign country may keep it but must pass both the knowledge test and the driving test.","p":"Right. You take both the knowledge test and the road test."},"es":{"q":"En Rhode Island, usted tiene una licencia vigente de otro país. ¿Qué debe hacer para obtener una licencia de Rhode Island?","o":["Nada; solo cambiar su licencia","Solo aprobar un examen de la vista","Solo tomar la clase de 33 horas","Aprobar el examen de conocimientos y el examen de manejo"],"h1":"Una licencia extranjera no le exime de los exámenes.","h2":"En Rhode Island, una persona con licencia de otro país puede conservarla, pero debe aprobar el examen de conocimientos y el examen de manejo.","p":"Correcto. Debe tomar el examen de conocimientos y el de manejo."},"ref":{"doc":"RI","page":10}},{"id":"ri-056","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, a parent without a valid Rhode Island license signs a teen's permit application. Where must that parent sit during practice driving?","o":["In the back seat","In the front passenger seat","They may not ride in the car","Anywhere they like"],"h1":"The front seat is only for a qualified supervising driver.","h2":"In Rhode Island a parent without a valid Rhode Island license may sign a minor's application but must sit in the back seat during practice driving.","p":"Right. That parent rides in the back seat."},"es":{"q":"En Rhode Island, un padre sin licencia válida de Rhode Island firma la solicitud de permiso de un adolescente. ¿Dónde debe sentarse ese padre durante la práctica de manejo?","o":["En el asiento de atrás","En el asiento del pasajero de adelante","No puede ir en el carro","Donde quiera"],"h1":"El asiento de adelante es solo para un conductor supervisor calificado.","h2":"En Rhode Island, un padre sin licencia válida de Rhode Island puede firmar la solicitud de un menor, pero debe sentarse en el asiento de atrás durante la práctica.","p":"Correcto. Ese padre va en el asiento de atrás."},"ref":{"doc":"RI","page":11}},{"id":"ri-057","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, a teen with an instruction permit runs a stop sign during practice. Who is legally responsible for the violation?","o":["No one, because it is practice","The licensed supervising driver","Only the teen","The owner of the road"],"h1":"Think about who is supposed to be in charge of the car.","h2":"In Rhode Island the licensed driver supervising a permit holder is legally responsible for any driving violation the learner commits.","p":"Right. The supervising driver is responsible."},"es":{"q":"En Rhode Island, un adolescente con permiso de instrucción no para en un señal de PARE durante la práctica. ¿Quién es legalmente responsable de la infracción?","o":["Nadie, porque es práctica","El conductor supervisor con licencia","Solo el adolescente","El dueño de la calle"],"h1":"Piense en quién debe estar a cargo del carro.","h2":"En Rhode Island, el conductor con licencia que supervisa a quien tiene permiso es legalmente responsable de cualquier infracción que cometa el aprendiz.","p":"Correcto. El conductor supervisor es el responsable."},"ref":{"doc":"RI","page":11}},{"id":"ri-058","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, when may a permit holder drive without wearing a seat belt?","o":["When driving under 25 mph","Never, with no exceptions at all","Only with a doctor's letter on file at the DMV saying they cannot wear one","On short trips"],"h1":"There is one medical exception.","h2":"In Rhode Island a permit holder must always wear a seat belt unless they give the DMV a physician's letter saying they cannot wear one for medical reasons.","p":"Right. Only a doctor's letter given to the DMV excuses it."},"es":{"q":"En Rhode Island, ¿cuándo puede manejar sin cinturón de seguridad quien tiene permiso de instrucción?","o":["Cuando maneja a menos de 25 mph","Nunca, sin ninguna excepción","Solo si la DMV tiene una carta de un médico que diga que no puede usarlo","En viajes cortos"],"h1":"Hay una sola excepción médica.","h2":"En Rhode Island, quien tiene permiso debe usar siempre el cinturón, a menos que entregue a la DMV una carta médica que diga que no puede usarlo por razones de salud.","p":"Correcto. Solo una carta médica entregada a la DMV lo excusa."},"ref":{"doc":"RI","page":11}},{"id":"ri-059","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, your instruction permit expires before you pass the road test. What must you do?","o":["Keep driving on the old permit","Wait until age 18 with no permit","Take the 33-hour class over again","Take the computerized test again or be recertified by CCRI, then get a new permit"],"h1":"An expired permit cannot be used; you start that step again.","h2":"In Rhode Island, if your permit expires before you pass the driving test, you must retake the computerized test or be recertified by CCRI and get a new permit.","p":"Right. Retake the test or get recertified, then get a new permit."},"es":{"q":"En Rhode Island, su permiso de instrucción se vence antes de aprobar el examen de manejo. ¿Qué debe hacer?","o":["Seguir manejando con el permiso viejo","Esperar hasta los 18 años sin permiso","Tomar otra vez la clase de 33 horas","Tomar otra vez el examen en computadora o ser recertificado por CCRI, y sacar un permiso nuevo"],"h1":"Un permiso vencido no sirve; debe repetir ese paso.","h2":"En Rhode Island, si su permiso se vence antes de aprobar el examen de manejo, debe repetir el examen en computadora o ser recertificado por CCRI y sacar un permiso nuevo.","p":"Correcto. Repita el examen o recertifíquese, y saque un permiso nuevo."},"ref":{"doc":"RI","page":11}},{"id":"ri-060","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, can a limited instruction permit be extended past its normal time?","o":["Yes, if you show the DMV proof of a hardship","No, never","Yes, for anyone who asks","Yes, but only for people over 21"],"h1":"A special reason is needed.","h2":"In Rhode Island a limited instruction permit may be extended if the holder shows the DMV satisfactory evidence of a hardship.","p":"Right. It can be extended for a proven hardship."},"es":{"q":"En Rhode Island, ¿se puede extender un permiso de instrucción limitado más allá de su tiempo normal?","o":["Sí, si muestra a la DMV prueba de una dificultad especial","No, nunca","Sí, a cualquiera que lo pida","Sí, pero solo para mayores de 21"],"h1":"Hace falta una razón especial.","h2":"En Rhode Island se puede extender un permiso de instrucción limitado si quien lo tiene muestra a la DMV prueba suficiente de una dificultad especial.","p":"Correcto. Se puede extender por una dificultad comprobada."},"ref":{"doc":"RI","page":11}},{"id":"ri-061","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, you turn 18 before you have held your instruction permit for a full year. What may you do?","o":["Only drive with a parent until 21","Apply for a full operator's license","Nothing until the year is over","Get a second permit"],"h1":"At 18, the teen license levels no longer apply.","h2":"In Rhode Island, if you turn 18 before holding the limited instruction permit for one year, you may apply for a full operator's license.","p":"Right. At 18 you may apply for a full license."},"es":{"q":"En Rhode Island, usted cumple 18 años antes de tener su permiso de instrucción un año completo. ¿Qué puede hacer?","o":["Manejar solo con un padre hasta los 21","Solicitar una licencia de conducir completa","Nada hasta que pase el año","Sacar un segundo permiso"],"h1":"A los 18, los niveles de licencia para adolescentes ya no aplican.","h2":"En Rhode Island, si cumple 18 años antes de tener el permiso de instrucción limitado por un año, puede solicitar la licencia de conducir completa.","p":"Correcto. A los 18 puede solicitar la licencia completa."},"ref":{"doc":"RI","page":12}},{"id":"ri-062","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, the owner of the car you will use for your road test cannot come. What must you bring?","o":["A photo of the owner","The owner's house key","A notarized letter from the owner giving permission","Nothing; any car is fine"],"h1":"The examiner needs proof the owner agreed, signed before a notary.","h2":"In Rhode Island, if the registered owner is not in the car at the road test, you must give the examiner a notarized letter from the owner allowing use of the vehicle.","p":"Right. Bring a notarized letter from the owner."},"es":{"q":"En Rhode Island, el dueño del carro que usará en su examen de manejo no puede ir. ¿Qué debe llevar?","o":["Una foto del dueño","La llave de la casa del dueño","Una carta notariada del dueño que dé permiso","Nada; cualquier carro sirve"],"h1":"El examinador necesita prueba de que el dueño aceptó, firmada ante notario.","h2":"En Rhode Island, si el dueño registrado no va en el carro durante el examen de manejo, debe entregar al examinador una carta notariada del dueño que permita usar el vehículo.","p":"Correcto. Lleve una carta notariada del dueño."},"ref":{"doc":"RI","page":12}},{"id":"ri-063","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, which of these makes you fail the road test right away?","o":["Asking the examiner to repeat a direction","Driving at the speed limit","Using your turn signal early","Any moving violation"],"h1":"Breaking a traffic law during the test ends it.","h2":"In Rhode Island any moving violation during the road test is a reason for immediate failure, and so are leaving your lane or the roadway, a collision, and not cooperating with the examiner.","p":"Right. A moving violation is an immediate failure."},"es":{"q":"En Rhode Island, ¿cuál de estas cosas le hace reprobar el examen de manejo de inmediato?","o":["Pedir al examinador que repita una indicación","Manejar al límite de velocidad","Poner la direccional con tiempo","Cualquier infracción de tránsito en movimiento"],"h1":"Violar una ley de tránsito durante el examen lo termina.","h2":"En Rhode Island, cualquier infracción en movimiento durante el examen de manejo es motivo de reprobación inmediata, igual que salirse del carril o de la vía, un choque o no cooperar con el examinador.","p":"Correcto. Una infracción en movimiento reprueba de inmediato."},"ref":{"doc":"RI","page":12}},{"id":"ri-064","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, in what language are the road test instructions given?","o":["English only, with a vocabulary list in Spanish and Portuguese","Any language you choose","English or Spanish, your choice","Portuguese only"],"h1":"The examiner speaks one language, but a word list can help you prepare.","h2":"In Rhode Island all road test instructions are given in English, and the DMV offers a translated vocabulary list in Spanish and Portuguese.","p":"Right. Instructions are in English; a Spanish and Portuguese word list helps."},"es":{"q":"En Rhode Island, ¿en qué idioma se dan las instrucciones del examen de manejo?","o":["Solo en inglés, con una lista de vocabulario en español y portugués","En el idioma que usted elija","En inglés o español, a su elección","Solo en portugués"],"h1":"El examinador habla un solo idioma, pero una lista de palabras le ayuda a prepararse.","h2":"En Rhode Island todas las instrucciones del examen de manejo se dan en inglés, y la DMV ofrece una lista de vocabulario traducida al español y al portugués.","p":"Correcto. Las instrucciones son en inglés; la lista en español y portugués ayuda."},"ref":{"doc":"RI","page":12}},{"id":"ri-065","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, who must come with a teen to the road test?","o":["Two adult witnesses","A parent, guardian or instructor who qualifies as a supervising driver","No one","A lawyer"],"h1":"Someone qualified to supervise must be there.","h2":"In Rhode Island a parent, legal guardian or instructor who qualifies as a supervising driver must be present at the road test.","p":"Right. A qualified supervising adult must be there."},"es":{"q":"En Rhode Island, ¿quién debe ir con un adolescente al examen de manejo?","o":["Dos testigos adultos","Un padre, tutor o instructor que califique como conductor supervisor","Nadie","Un abogado"],"h1":"Debe estar alguien calificado para supervisar.","h2":"En Rhode Island debe estar presente en el examen de manejo un padre, tutor legal o instructor que califique como conductor supervisor.","p":"Correcto. Debe ir un adulto calificado para supervisar."},"ref":{"doc":"RI","page":12}},{"id":"ri-066","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, which car does not need an inspection sticker for the road test?","o":["Any car registered in another state","Any rental car","One less than 2 years old or with 24,000 miles or less","Any car with a full gas tank"],"h1":"Very new cars have not reached their first inspection yet.","h2":"In Rhode Island a car used for the road test needs a valid inspection sticker unless it is less than 2 years old or has 24,000 miles or less, whichever comes first.","p":"Right. Very new, low-mileage cars do not need the sticker yet."},"es":{"q":"En Rhode Island, ¿qué carro no necesita calcomanía de inspección para el examen de manejo?","o":["Cualquier carro registrado en otro estado","Cualquier carro rentado","Uno con menos de 2 años o con 24,000 millas o menos","Cualquier carro con el tanque lleno"],"h1":"Los carros muy nuevos todavía no llegan a su primera inspección.","h2":"En Rhode Island el carro del examen de manejo necesita calcomanía de inspección vigente, salvo que tenga menos de 2 años o 24,000 millas o menos, lo que ocurra primero.","p":"Correcto. Los carros muy nuevos y con pocas millas todavía no la necesitan."},"ref":{"doc":"RI","page":13}},{"id":"ri-067","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, may you take the road test in a rental car?","o":["Yes, any rental car","Yes, if it is rented for a week","Yes, if the rental company sends a letter","No, rental cars are not allowed"],"h1":"The DMV lists this kind of car as not allowed.","h2":"Rhode Island does not allow rental vehicles to be used for the road test.","p":"Right. No rental cars for the road test."},"es":{"q":"En Rhode Island, ¿puede tomar el examen de manejo en un carro rentado?","o":["Sí, cualquier carro rentado","Sí, si está rentado por una semana","Sí, si la compañía de renta manda una carta","No, no se permiten carros rentados"],"h1":"La DMV dice que este tipo de carro no se permite.","h2":"Rhode Island no permite usar vehículos rentados para el examen de manejo.","p":"Correcto. No se permiten carros rentados en el examen."},"ref":{"doc":"RI","page":13}},{"id":"ri-068","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, you arrive for the road test without one required document. What happens?","o":["You must reschedule; you may not leave to get it and come back","You may go home, get it and return the same day","The examiner skips that document","You take the test and bring it later"],"h1":"There are no same-day returns.","h2":"In Rhode Island, if you do not bring every required document, you must reschedule the road test; you may not leave the test area to get it and return.","p":"Right. You must reschedule."},"es":{"q":"En Rhode Island, usted llega al examen de manejo sin uno de los documentos requeridos. ¿Qué pasa?","o":["Debe programar otra cita; no puede ir por él y regresar","Puede ir a casa, buscarlo y volver el mismo día","El examinador no pide ese documento","Toma el examen y lo lleva después"],"h1":"No hay regresos el mismo día.","h2":"En Rhode Island, si no lleva todos los documentos requeridos, debe programar otra cita para el examen de manejo; no puede salir del área del examen a buscarlo y regresar.","p":"Correcto. Debe programar otra cita."},"ref":{"doc":"RI","page":13}},{"id":"ri-069","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, when does a limited provisional license expire?","o":["On your 21st birthday","On your 18th birthday","After 6 months","After 5 years"],"h1":"It is tied to the age when the teen license system ends.","h2":"In Rhode Island a limited provisional license expires on the holder's eighteenth birthday.","p":"Right. It expires on your 18th birthday."},"es":{"q":"En Rhode Island, ¿cuándo vence una licencia provisional limitada?","o":["El día que cumple 21 años","El día que cumple 18 años","Después de 6 meses","Después de 5 años"],"h1":"Está ligada a la edad en que termina el sistema de licencias para adolescentes.","h2":"En Rhode Island la licencia provisional limitada vence el día en que su titular cumple dieciocho años.","p":"Correcto. Vence cuando cumple 18 años."},"ref":{"doc":"RI","page":14}},{"id":"ri-070","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, a 17-year-old with a limited provisional license is a member of a volunteer fire department. May they drive alone to a fire call at 2 a.m.?","o":["Only with a parent","Only if they also work at night","Yes, trips to or from volunteer fire, rescue or EMS activities are allowed","No, never between 1 a.m. and 5 a.m."],"h1":"There is an exception for volunteer emergency service members.","h2":"In Rhode Island a limited provisional licensee may drive alone at any hour to or from an activity of a volunteer fire department, rescue squad or emergency medical service they belong to.","p":"Right. Volunteer fire, rescue and EMS trips are allowed."},"es":{"q":"En Rhode Island, un joven de 17 años con licencia provisional limitada es miembro de un departamento de bomberos voluntarios. ¿Puede manejar solo a una emergencia a las 2 a.m.?","o":["Solo con un padre","Solo si también trabaja de noche","Sí, se permiten viajes a actividades de bomberos, rescate o emergencias médicas voluntarias","No, nunca entre la 1 a.m. y las 5 a.m."],"h1":"Hay una excepción para miembros de servicios de emergencia voluntarios.","h2":"En Rhode Island quien tiene licencia provisional limitada puede manejar solo a cualquier hora para ir o volver de una actividad del departamento de bomberos, escuadrón de rescate o servicio médico de emergencia voluntario al que pertenece.","p":"Correcto. Se permiten los viajes de bomberos, rescate y emergencias voluntarias."},"ref":{"doc":"RI","page":14}},{"id":"ri-071","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, a 17-year-old with a limited provisional license has an early school sports practice and the school gives no ride. When may they drive alone from home to it?","o":["From midnight to 1 a.m.","From 2 a.m. to 3 a.m.","Never before 6 a.m.","From 4 a.m. to 5 a.m."],"h1":"The exception starts one hour before the normal night limit ends.","h2":"Rhode Island law lets a limited provisional licensee drive alone from 4 a.m. to 5 a.m. between home and a school-sponsored athletic activity when the school provides no transportation.","p":"Right. From 4 a.m. to 5 a.m. for school sports with no school ride."},"es":{"q":"En Rhode Island, un joven de 17 años con licencia provisional limitada tiene práctica deportiva escolar muy temprano y la escuela no da transporte. ¿Cuándo puede manejar solo de su casa a la práctica?","o":["De medianoche a 1 a.m.","De 2 a.m. a 3 a.m.","Nunca antes de las 6 a.m.","De 4 a.m. a 5 a.m."],"h1":"La excepción empieza una hora antes de que termine el límite nocturno normal.","h2":"La ley de Rhode Island permite a quien tiene licencia provisional limitada manejar solo de 4 a.m. a 5 a.m. entre su casa y una actividad deportiva de la escuela cuando la escuela no da transporte.","p":"Correcto. De 4 a.m. a 5 a.m. para deportes escolares sin transporte de la escuela."},"ref":{"doc":"RI","page":null}},{"id":"ri-072","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, how long must a teen hold a limited provisional license before getting a full operator's license?","o":["At least 12 months","At least 3 months","At least 6 months","At least 2 years"],"h1":"It is a full year.","h2":"In Rhode Island a teen must hold a limited provisional license for at least twelve months before getting a full operator's license.","p":"Right. Hold it at least 12 months."},"es":{"q":"En Rhode Island, ¿cuánto tiempo debe tener un adolescente la licencia provisional limitada antes de obtener la licencia completa?","o":["Por lo menos 12 meses","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 2 años"],"h1":"Es un año completo.","h2":"En Rhode Island un adolescente debe tener la licencia provisional limitada por lo menos doce meses antes de obtener la licencia de conducir completa.","p":"Correcto. Debe tenerla por lo menos 12 meses."},"ref":{"doc":"RI","page":14}},{"id":"ri-073","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, a teen who meets all the rules for a full operator's license wants to get it. How may they get it?","o":["Only through their high school","By mail","Only by taking a second road test","Only at the DMV main office in person"],"h1":"No extra trip or test is needed.","h2":"Rhode Island law lets a teen who meets all the requirements get the full operator's license by mail.","p":"Right. It can be obtained by mail."},"es":{"q":"En Rhode Island, un adolescente que cumple todas las reglas para la licencia completa quiere obtenerla. ¿Cómo puede hacerlo?","o":["Solo a través de su escuela","Por correo","Solo tomando un segundo examen de manejo","Solo en persona en la oficina principal de la DMV"],"h1":"No hace falta otro viaje ni otro examen.","h2":"La ley de Rhode Island permite que un adolescente que cumple todos los requisitos obtenga la licencia de conducir completa por correo.","p":"Correcto. Se puede obtener por correo."},"ref":{"doc":"RI","page":null}},{"id":"ri-074","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, may lessons with a commercial driving school count toward a teen's 50 supervised hours?","o":["Only if they are at night","Only after the teen turns 18","Yes, they may be included","No, only a parent's hours count"],"h1":"Any supervised driving can count.","h2":"Rhode Island law says the 50 hours of supervised driving may include lessons with a commercial driving school or any other supervised driving.","p":"Right. Driving school lessons can count."},"es":{"q":"En Rhode Island, ¿pueden las clases con una escuela de manejo comercial contar para las 50 horas supervisadas de un adolescente?","o":["Solo si son de noche","Solo después de que cumpla 18","Sí, pueden incluirse","No, solo cuentan las horas con un padre"],"h1":"Cualquier manejo supervisado puede contar.","h2":"La ley de Rhode Island dice que las 50 horas de manejo supervisado pueden incluir clases con una escuela de manejo comercial o cualquier otro manejo supervisado.","p":"Correcto. Las clases de escuela de manejo pueden contar."},"ref":{"doc":"RI","page":null}},{"id":"ri-075","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, you are over 18 and get a temporary driver's permit. How long must you hold it before you can take the road test?","o":["At least 6 months","At least 1 year","No waiting time","At least 30 days"],"h1":"For adults the wait is about one month.","h2":"Rhode Island law says a person 18 or older must hold the temporary driver's permit for at least 30 days before being eligible for the road test.","p":"Right. Adults hold the permit at least 30 days."},"es":{"q":"En Rhode Island, usted es mayor de 18 y saca un permiso temporal de manejo. ¿Cuánto tiempo debe tenerlo antes de poder tomar el examen de manejo?","o":["Por lo menos 6 meses","Por lo menos 1 año","No hay que esperar","Por lo menos 30 días"],"h1":"Para adultos la espera es de un mes más o menos.","h2":"La ley de Rhode Island dice que una persona de 18 años o más debe tener el permiso temporal por lo menos 30 días antes de poder tomar el examen de manejo.","p":"Correcto. Los adultos tienen el permiso por lo menos 30 días."},"ref":{"doc":"RI","page":null}},{"id":"ri-076","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, your license is suspended. When does the suspension period start?","o":["When you turn in your license to the DMV","On the day of your ticket","On the first day of the next month","When your insurance company is told"],"h1":"The clock does not start until the DMV has the license.","h2":"In Rhode Island a suspension period does not begin until your license has been surrendered or sent to the DMV.","p":"Right. It starts when the DMV has your license."},"es":{"q":"En Rhode Island, su licencia está suspendida. ¿Cuándo empieza el periodo de suspensión?","o":["Cuando entrega su licencia a la DMV","El día de su multa","El primer día del mes siguiente","Cuando se avisa a su compañía de seguros"],"h1":"El tiempo no empieza a contar hasta que la DMV tiene la licencia.","h2":"En Rhode Island el periodo de suspensión no empieza hasta que usted entrega o envía su licencia a la DMV.","p":"Correcto. Empieza cuando la DMV tiene su licencia."},"ref":{"doc":"RI","page":15}},{"id":"ri-077","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, your license is suspended. Where may you legally drive during the suspension?","o":["Only on weekends","Nowhere, not in Rhode Island or any other state","In any other state","Only to work"],"h1":"A suspension follows you across state lines.","h2":"During a Rhode Island suspension you may not legally drive in Rhode Island or any other state for any reason.","p":"Right. You may not drive anywhere."},"es":{"q":"En Rhode Island, su licencia está suspendida. ¿Dónde puede manejar legalmente durante la suspensión?","o":["Solo los fines de semana","En ningún lugar, ni en Rhode Island ni en otro estado","En cualquier otro estado","Solo al trabajo"],"h1":"La suspensión le sigue a otros estados.","h2":"Durante una suspensión de Rhode Island no puede manejar legalmente ni en Rhode Island ni en ningún otro estado, por ninguna razón.","p":"Correcto. No puede manejar en ningún lugar."},"ref":{"doc":"RI","page":15}},{"id":"ri-078","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you just moved from another state. Your old license expired 8 months ago. Must you take the knowledge and road tests?","o":["Only the road test","Only the knowledge test","No, not if it has been expired one year or less","Yes, both tests"],"h1":"The limit is one year.","h2":"In Rhode Island a new resident whose out-of-state license is valid or has been expired for not more than one year does not have to take the computerized test or the road test.","p":"Right. Expired less than a year means no tests."},"es":{"q":"En Rhode Island, usted acaba de mudarse de otro estado. Su licencia anterior venció hace 8 meses. ¿Debe tomar los exámenes de conocimientos y de manejo?","o":["Solo el examen de manejo","Solo el examen de conocimientos","No, si no lleva más de un año vencida","Sí, los dos exámenes"],"h1":"El límite es un año.","h2":"En Rhode Island un nuevo residente cuya licencia de otro estado está vigente o no lleva más de un año vencida no tiene que tomar el examen en computadora ni el de manejo.","p":"Correcto. Con menos de un año vencida no hay exámenes."},"ref":{"doc":"RI","page":16}},{"id":"ri-079","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, you had a Rhode Island license that has been expired for 4 years. What happens to your license number?","o":["You keep your old number","You choose any number","You must wait a year for a number","You get a new license number"],"h1":"The cutoff for keeping the old number is three years.","h2":"In Rhode Island a previous license expired more than three years gets a new license number; if it is expired three years or less, the old number is reissued.","p":"Right. After more than three years you get a new number."},"es":{"q":"En Rhode Island, usted tuvo una licencia de Rhode Island que lleva 4 años vencida. ¿Qué pasa con su número de licencia?","o":["Conserva su número anterior","Elige cualquier número","Debe esperar un año para tener número","Recibe un número nuevo"],"h1":"El límite para conservar el número anterior es de tres años.","h2":"En Rhode Island, si su licencia anterior lleva más de tres años vencida, recibe un número nuevo; si lleva tres años o menos, se le vuelve a dar el número anterior.","p":"Correcto. Después de más de tres años recibe un número nuevo."},"ref":{"doc":"RI","page":16}},{"id":"ri-080","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, you move in with a motorcycle endorsement on your out-of-state license. What happens to it?","o":["It moves to your new Rhode Island license","It is cancelled and you must test again","It lasts only 30 days","You must give up motorcycles"],"h1":"Endorsements carry over.","h2":"In Rhode Island restrictions and endorsements on an out-of-state license, such as a motorcycle endorsement, are moved to your new Rhode Island license.","p":"Right. The endorsement transfers."},"es":{"q":"En Rhode Island, usted se muda con un permiso especial de motocicleta en su licencia de otro estado. ¿Qué pasa con él?","o":["Pasa a su nueva licencia de Rhode Island","Se cancela y debe examinarse otra vez","Dura solo 30 días","Debe dejar las motocicletas"],"h1":"Los permisos especiales se transfieren.","h2":"En Rhode Island las restricciones y permisos especiales de una licencia de otro estado, como el de motocicleta, pasan a su nueva licencia de Rhode Island.","p":"Correcto. El permiso especial se transfiere."},"ref":{"doc":"RI","page":16}},{"id":"ri-081","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, you move here and become a resident. How soon must you get a Rhode Island driver's license?","o":["Within 1 year","Within 30 days","Within 10 days","Within 6 months"],"h1":"It is about one month.","h2":"Rhode Island law requires a new resident to get a Rhode Island driver's license within thirty days of establishing residency.","p":"Right. Within 30 days."},"es":{"q":"En Rhode Island, usted se muda aquí y se hace residente. ¿En cuánto tiempo debe sacar una licencia de Rhode Island?","o":["Dentro de 1 año","Dentro de 30 días","Dentro de 10 días","Dentro de 6 meses"],"h1":"Es más o menos un mes.","h2":"La ley de Rhode Island exige que un nuevo residente saque una licencia de Rhode Island dentro de los treinta días de establecer su residencia.","p":"Correcto. Dentro de 30 días."},"ref":{"doc":"RI","page":null}},{"id":"ri-082","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you move to a new address. How soon must you tell the DMV?","o":["Within 90 days","At your next renewal","Within 10 days","Within 30 days"],"h1":"It is less than two weeks.","h2":"Rhode Island law requires you to notify the DMV in writing within ten days after moving or changing your name.","p":"Right. Tell the DMV within 10 days."},"es":{"q":"En Rhode Island, usted se muda a otra dirección. ¿En cuánto tiempo debe avisar a la DMV?","o":["Dentro de 90 días","En su próxima renovación","Dentro de 10 días","Dentro de 30 días"],"h1":"Es menos de dos semanas.","h2":"La ley de Rhode Island exige avisar por escrito a la DMV dentro de los diez días después de mudarse o cambiar de nombre.","p":"Correcto. Avise a la DMV dentro de 10 días."},"ref":{"doc":"RI","page":null}},{"id":"ri-083","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, after your first license, how long is a renewed license usually valid?","o":["1 year","10 years","For life","5 years"],"h1":"It is half a decade.","h2":"Rhode Island law says a license renewed after the first one expires on your birthday in the fifth year, so it lasts about five years.","p":"Right. About five years."},"es":{"q":"En Rhode Island, después de su primera licencia, ¿por cuánto tiempo vale normalmente una licencia renovada?","o":["1 año","10 años","Toda la vida","5 años"],"h1":"Es medio decenio.","h2":"La ley de Rhode Island dice que la licencia renovada después de la primera vence en su cumpleaños del quinto año, así que dura unos cinco años.","p":"Correcto. Unos cinco años."},"ref":{"doc":"RI","page":null}},{"id":"ri-084","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, how long is the very first driver's license valid?","o":["Until your birthday in the second year after it is issued","Exactly 6 months","5 years","10 years"],"h1":"It covers about two birthdays.","h2":"Rhode Island law says a first license expires on the driver's birthday in the second year after it is issued.","p":"Right. It runs to your birthday in the second year."},"es":{"q":"En Rhode Island, ¿por cuánto tiempo vale la primera licencia de conducir?","o":["Hasta su cumpleaños del segundo año después de emitirse","Exactamente 6 meses","5 años","10 años"],"h1":"Abarca unos dos cumpleaños.","h2":"La ley de Rhode Island dice que la primera licencia vence en el cumpleaños del conductor del segundo año después de emitirse.","p":"Correcto. Dura hasta su cumpleaños del segundo año."},"ref":{"doc":"RI","page":null}},{"id":"ri-085","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, at what age does a renewed license become valid for only 2 years instead of 5?","o":["85","75","60","65"],"h1":"It is three quarters of a century.","h2":"Rhode Island law says a driver 75 or older gets a license that expires on their birthday in the second year, instead of the fifth.","p":"Right. At 75 it is renewed for 2 years."},"es":{"q":"En Rhode Island, ¿a qué edad la licencia renovada vale solo 2 años en lugar de 5?","o":["85","75","60","65"],"h1":"Son tres cuartos de siglo.","h2":"La ley de Rhode Island dice que un conductor de 75 años o más recibe una licencia que vence en su cumpleaños del segundo año, en lugar del quinto.","p":"Correcto. A los 75 se renueva por 2 años."},"ref":{"doc":"RI","page":null}},{"id":"ri-086","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you renew your license at the DMV. What do you get to use until the new card arrives by mail?","o":["Nothing; you may not drive","A permit that requires a supervisor","A temporary license good for 60 days","Your expired license"],"h1":"It lasts about two months.","h2":"When you renew at the Rhode Island DMV, you get a temporary license valid for sixty days, and the card is mailed to you.","p":"Right. A 60-day temporary license."},"es":{"q":"En Rhode Island, usted renueva su licencia en la DMV. ¿Qué usa hasta que le llegue la tarjeta nueva por correo?","o":["Nada; no puede manejar","Un permiso que exige un supervisor","Una licencia temporal válida por 60 días","Su licencia vencida"],"h1":"Dura unos dos meses.","h2":"Al renovar en la DMV de Rhode Island, recibe una licencia temporal válida por sesenta días, y la tarjeta se le envía por correo.","p":"Correcto. Una licencia temporal de 60 días."},"ref":{"doc":"RI","page":73}},{"id":"ri-087","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, where besides a DMV branch may a current AAA member renew a driver's license?","o":["At any gas station","At a post office","At a car dealer","At a AAA branch"],"h1":"Think of the auto club.","h2":"In Rhode Island you may renew your license in person at a DMV branch office or, if you are a current member, at a AAA branch.","p":"Right. AAA members may renew at a AAA branch."},"es":{"q":"En Rhode Island, ¿dónde, además de una oficina de la DMV, puede un miembro actual de AAA renovar su licencia?","o":["En cualquier gasolinera","En una oficina de correos","En una agencia de carros","En una sucursal de AAA"],"h1":"Piense en el club de automovilistas.","h2":"En Rhode Island puede renovar su licencia en persona en una oficina de la DMV o, si es miembro actual, en una sucursal de AAA.","p":"Correcto. Los miembros de AAA pueden renovar en una sucursal de AAA."},"ref":{"doc":"RI","page":73}},{"id":"ri-088","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, you want to change your name on your license. What must you do first?","o":["Change your name with the Social Security Administration","Get a new car registration","Take the knowledge test again","Wait until your license expires"],"h1":"The DMV checks your name against another federal record.","h2":"In Rhode Island you must change your name with the Social Security Administration first, and allow at least 24 hours, before the DMV can change your license.","p":"Right. Change it with Social Security first."},"es":{"q":"En Rhode Island, usted quiere cambiar su nombre en la licencia. ¿Qué debe hacer primero?","o":["Cambiar su nombre en la Administración del Seguro Social","Sacar un registro nuevo del carro","Tomar otra vez el examen de conocimientos","Esperar a que se venza su licencia"],"h1":"La DMV compara su nombre con otro registro federal.","h2":"En Rhode Island primero debe cambiar su nombre en la Administración del Seguro Social, y esperar por lo menos 24 horas, antes de que la DMV pueda cambiar su licencia.","p":"Correcto. Primero cámbielo en el Seguro Social."},"ref":{"doc":"RI","page":73}},{"id":"ri-089","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, which Social Security card will the DMV accept from a new applicant?","o":["A metal copy of the card","The official card, not laminated or metal","A photocopy","A laminated card"],"h1":"It must be the real paper card, unchanged.","h2":"The Rhode Island DMV requires new applicants to show an official Social Security card; copies, laminated cards and metal cards are not accepted.","p":"Right. Only the official, unlaminated card."},"es":{"q":"En Rhode Island, ¿qué tarjeta del Seguro Social acepta la DMV de un nuevo solicitante?","o":["Una copia de metal de la tarjeta","La tarjeta oficial, sin plastificar ni de metal","Una fotocopia","Una tarjeta plastificada"],"h1":"Debe ser la tarjeta de papel real, sin cambios.","h2":"La DMV de Rhode Island exige que los nuevos solicitantes muestren la tarjeta oficial del Seguro Social; no acepta copias, tarjetas plastificadas ni de metal.","p":"Correcto. Solo la tarjeta oficial sin plastificar."},"ref":{"doc":"RI","page":74}},{"id":"ri-090","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, which birth certificate is NOT accepted as proof of identity?","o":["A certified copy with a seal","One issued by a government agency","One issued by the hospital","An original from Vital Statistics"],"h1":"It must come from a government office.","h2":"The Rhode Island DMV accepts birth certificates issued by an authorized government agency, but not certificates issued by a hospital.","p":"Right. Hospital-issued certificates are not accepted."},"es":{"q":"En Rhode Island, ¿qué acta de nacimiento NO se acepta como prueba de identidad?","o":["Una copia certificada con sello","Una emitida por una agencia del gobierno","Una emitida por el hospital","Un original del Registro Civil"],"h1":"Debe venir de una oficina del gobierno.","h2":"La DMV de Rhode Island acepta actas de nacimiento emitidas por una agencia autorizada del gobierno, pero no las emitidas por un hospital.","p":"Correcto. No se aceptan las del hospital."},"ref":{"doc":"RI","page":74}},{"id":"ri-091","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, a teen applicant has no bills in their own name. How can they prove where they live?","o":["A letter from a friend","A library card","Their phone number","Current school records with the address, plus a parent's license with the same address"],"h1":"A school document can work when a parent backs it up.","h2":"In Rhode Island a minor may prove residency with current school records showing their address, such as a report card, together with a parent's license or ID with the same address.","p":"Right. School records plus a parent's ID with the same address."},"es":{"q":"En Rhode Island, un solicitante adolescente no tiene recibos a su nombre. ¿Cómo puede probar dónde vive?","o":["Con una carta de un amigo","Con una tarjeta de biblioteca","Con su número de teléfono","Con documentos escolares actuales con su dirección, más la licencia de un padre con la misma dirección"],"h1":"Un documento escolar sirve si un padre lo respalda.","h2":"En Rhode Island un menor puede probar su residencia con documentos escolares actuales que muestren su dirección, como una boleta de calificaciones, junto con la licencia o identificación de un padre con la misma dirección.","p":"Correcto. Documentos escolares más la identificación de un padre con la misma dirección."},"ref":{"doc":"RI","page":74}},{"id":"ri-092","scope":"RI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Rhode Island, you are 17 and want to be an organ donor on your license. What do you need?","o":["A parent's consent","Nothing; anyone can sign up alone","A doctor's exam","To wait until age 21"],"h1":"Under 18, an adult must agree.","h2":"In Rhode Island anyone can be a potential organ donor, but a person under 18 needs parental consent.","p":"Right. Under 18 you need a parent's consent."},"es":{"q":"En Rhode Island, usted tiene 17 años y quiere ser donante de órganos en su licencia. ¿Qué necesita?","o":["El permiso de un padre","Nada; cualquiera puede inscribirse solo","Un examen médico","Esperar hasta los 21 años"],"h1":"Si es menor de 18, un adulto debe estar de acuerdo.","h2":"En Rhode Island cualquiera puede ser donante de órganos, pero una persona menor de 18 años necesita el permiso de sus padres.","p":"Correcto. Si es menor de 18 necesita el permiso de un padre."},"ref":{"doc":"RI","page":66}},{"id":"ri-093","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, what happens to your crash risk when you look away from the road for two seconds or more?","o":["It goes up only at night","It doubles","It stays the same","It drops by half"],"h1":"Even two seconds is a long time at speed.","h2":"The Rhode Island driver's manual says looking away from the road for two or more seconds doubles the chance of a crash.","p":"Right. Two seconds away doubles the risk."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué pasa con su riesgo de choque si aparta la vista del camino dos segundos o más?","o":["Sube solo de noche","Se duplica","Sigue igual","Baja a la mitad"],"h1":"Hasta dos segundos son mucho tiempo a velocidad.","h2":"El manual de manejo de Rhode Island dice que apartar la vista del camino dos segundos o más duplica la probabilidad de un choque.","p":"Correcto. Dos segundos sin mirar duplican el riesgo."},"ref":{"doc":"RI","page":17}},{"id":"ri-094","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, how does adding just one teen passenger change a teen driver's chance of a fatal crash?","o":["It cuts it in half","It raises it only on highways","It doubles it","It does not change it"],"h1":"Passengers are a big distraction for new drivers.","h2":"The Rhode Island driver's manual says adding just one teen passenger doubles a teen driver's likelihood of a fatal crash.","p":"Right. One teen passenger doubles the risk."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cómo cambia la probabilidad de un choque mortal de un conductor adolescente al llevar solo un pasajero adolescente?","o":["Baja a la mitad","Sube solo en autopistas","Se duplica","No cambia"],"h1":"Los pasajeros distraen mucho a los conductores nuevos.","h2":"El manual de manejo de Rhode Island dice que llevar solo un pasajero adolescente duplica la probabilidad de que un conductor adolescente tenga un choque mortal.","p":"Correcto. Un pasajero adolescente duplica el riesgo."},"ref":{"doc":"RI","page":18}},{"id":"ri-095","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, being awake for 18 hours affects your driving about as much as what?","o":["Drinking one cup of coffee","Driving with the radio on","Having a full stomach","A blood alcohol level of about .05 percent"],"h1":"Tiredness can act like alcohol.","h2":"The Rhode Island driver's manual says being awake for 18 hours causes impairment roughly equal to a blood alcohol concentration of .05 percent.","p":"Right. Eighteen hours awake is like a .05 BAC."},"es":{"q":"Según el manual de manejo de Rhode Island, estar despierto 18 horas afecta su manejo más o menos como ¿qué?","o":["Tomar una taza de café","Manejar con el radio prendido","Tener el estómago lleno","Un nivel de alcohol en la sangre de cerca de .05 por ciento"],"h1":"El cansancio puede actuar como el alcohol.","h2":"El manual de manejo de Rhode Island dice que estar despierto 18 horas causa un deterioro parecido a una concentración de alcohol en la sangre de .05 por ciento.","p":"Correcto. Dieciocho horas despierto es como .05 de alcohol."},"ref":{"doc":"RI","page":21}},{"id":"ri-096","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, during which hours do most people have their natural low in alertness?","o":["About midnight to 6 a.m., and again about 2 to 4 p.m.","About 8 to 10 a.m. only","About 6 to 8 p.m. only","Only right after waking up"],"h1":"There are two low times each day.","h2":"The Rhode Island driver's manual says most people feel a natural low in alertness from about midnight to 6 a.m. and again from about 2 to 4 p.m.","p":"Right. Midnight to 6 a.m. and 2 to 4 p.m."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿en qué horas tiene la mayoría de la gente su bajón natural de alerta?","o":["Más o menos de medianoche a 6 a.m., y otra vez de 2 a 4 p.m.","Solo de 8 a 10 a.m.","Solo de 6 a 8 p.m.","Solo al despertar"],"h1":"Hay dos momentos bajos cada día.","h2":"El manual de manejo de Rhode Island dice que la mayoría de la gente tiene un bajón natural de alerta más o menos de medianoche a 6 a.m. y otra vez de 2 a 4 p.m.","p":"Correcto. De medianoche a 6 a.m. y de 2 a 4 p.m."},"ref":{"doc":"RI","page":21}},{"id":"ri-097","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, how much sleep do experts recommend for teens each night?","o":["11 to 12 hours","8 and a half to 9 and a half hours","5 to 6 hours","6 to 7 hours"],"h1":"Teens need a bit more than adults' 7 to 9 hours.","h2":"The Rhode Island driver's manual says sleep experts recommend 8 and a half to 9 and a half hours of sleep a night for teens.","p":"Right. Teens need 8.5 to 9.5 hours."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuántas horas de sueño recomiendan los expertos para los adolescentes cada noche?","o":["De 11 a 12 horas","De 8 horas y media a 9 horas y media","De 5 a 6 horas","De 6 a 7 horas"],"h1":"Los adolescentes necesitan un poco más que las 7 a 9 horas de los adultos.","h2":"El manual de manejo de Rhode Island dice que los expertos recomiendan de 8 horas y media a 9 horas y media de sueño por noche para los adolescentes.","p":"Correcto. Los adolescentes necesitan de 8.5 a 9.5 horas."},"ref":{"doc":"RI","page":21}},{"id":"ri-098","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, how often should you take a break on a long trip?","o":["Only when you need gas","Every 15 minutes","About every 100 miles or every two hours","Every 300 miles"],"h1":"The rule uses both miles and hours.","h2":"The Rhode Island driver's manual suggests stopping for at least 10 minutes about every 100 miles or every two hours on long trips.","p":"Right. Every 100 miles or two hours."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cada cuánto debe tomar un descanso en un viaje largo?","o":["Solo cuando necesita gasolina","Cada 15 minutos","Más o menos cada 100 millas o cada dos horas","Cada 300 millas"],"h1":"La regla usa millas y horas.","h2":"El manual de manejo de Rhode Island sugiere parar por lo menos 10 minutos más o menos cada 100 millas o cada dos horas en viajes largos.","p":"Correcto. Cada 100 millas o cada dos horas."},"ref":{"doc":"RI","page":22}},{"id":"ri-099","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, you nap more than 20 minutes at a rest stop. What should you expect when you wake up?","o":["You will be fully alert right away","You will not be able to drive that day","You will need coffee before you can see","You may feel groggy for at least five minutes"],"h1":"Walk a few minutes before driving again.","h2":"The Rhode Island driver's manual warns that sleeping more than 20 minutes can leave you groggy for at least five minutes after waking, so walk around before driving.","p":"Right. Expect a few groggy minutes."},"es":{"q":"Según el manual de manejo de Rhode Island, usted duerme más de 20 minutos en un área de descanso. ¿Qué debe esperar al despertar?","o":["Estará totalmente alerta enseguida","No podrá manejar ese día","Necesitará café para poder ver","Puede sentirse atontado por lo menos cinco minutos"],"h1":"Camine unos minutos antes de volver a manejar.","h2":"El manual de manejo de Rhode Island advierte que dormir más de 20 minutos puede dejarle atontado por lo menos cinco minutos al despertar, así que camine antes de manejar.","p":"Correcto. Espere unos minutos de atontamiento."},"ref":{"doc":"RI","page":22}},{"id":"ri-100","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, how can you use your horn so it seems less aggressive?","o":["A couple of short taps instead of one long blast","One long, loud blast","Honking again and again","Holding the horn until they move"],"h1":"Short and gentle reads as friendly.","h2":"The Rhode Island driver's manual says to use the horn sparingly, because a couple of short taps seem less aggressive than one long blast.","p":"Right. A couple of short taps."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cómo puede usar la bocina para que parezca menos agresiva?","o":["Con un par de toques cortos en vez de un toque largo","Con un toque largo y fuerte","Tocando una y otra vez","Sin soltarla hasta que se muevan"],"h1":"Corto y suave se entiende como amable.","h2":"El manual de manejo de Rhode Island dice que use poco la bocina, porque un par de toques cortos parecen menos agresivos que un toque largo.","p":"Correcto. Un par de toques cortos."},"ref":{"doc":"RI","page":24}},{"id":"ri-101","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, what is the fine for not wearing a seat belt?","o":["$500","$40","$10","$250"],"h1":"It is less than $50.","h2":"Rhode Island's fine schedule sets the fine for a driver or passenger not wearing a seat belt at $40.","p":"Right. The fine is $40."},"es":{"q":"En Rhode Island, ¿cuál es la multa por no usar el cinturón de seguridad?","o":["$500","$40","$10","$250"],"h1":"Es menos de $50.","h2":"La tabla de multas de Rhode Island fija en $40 la multa por no usar el cinturón, para el conductor o un pasajero.","p":"Correcto. La multa es de $40."},"ref":{"doc":"RI","page":null}},{"id":"ri-102","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, your adult friend rides with you and will not buckle up. Who is responsible under the seat belt law?","o":["The car's maker","No one, because your friend is an adult","You, the driver","Only your friend"],"h1":"The law places the duty on the person at the wheel.","h2":"Rhode Island law makes the driver responsible for making sure passengers 18 and older wear a seat belt, as well as wearing one themselves.","p":"Right. The driver is responsible."},"es":{"q":"En Rhode Island, un amigo adulto va con usted y no quiere ponerse el cinturón. ¿Quién es responsable según la ley del cinturón?","o":["El fabricante del carro","Nadie, porque su amigo es adulto","Usted, el conductor","Solo su amigo"],"h1":"La ley pone la obligación en quien maneja.","h2":"La ley de Rhode Island hace al conductor responsable de que los pasajeros de 18 años o más usen el cinturón, además de usarlo él mismo.","p":"Correcto. El conductor es el responsable."},"ref":{"doc":"RI","page":25}},{"id":"ri-103","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, which children must ride in a rear-facing car seat?","o":["Only newborns under 1 month","Children under 5 years old","Children under 50 pounds","Children under 2 years old or under 30 pounds"],"h1":"Think of babies and young toddlers.","h2":"Rhode Island law requires infants and toddlers under two years old or weighing less than 30 pounds to ride in a rear-facing car seat.","p":"Right. Under 2 or under 30 pounds rides rear-facing."},"es":{"q":"En Rhode Island, ¿qué niños deben ir en un asiento de seguridad mirando hacia atrás?","o":["Solo los recién nacidos de menos de 1 mes","Los menores de 5 años","Los de menos de 50 libras","Los menores de 2 años o de menos de 30 libras"],"h1":"Piense en bebés y niños pequeños.","h2":"La ley de Rhode Island exige que los bebés y niños pequeños menores de dos años o de menos de 30 libras vayan en un asiento de seguridad mirando hacia atrás.","p":"Correcto. Menores de 2 años o de menos de 30 libras van mirando hacia atrás."},"ref":{"doc":"RI","page":null}},{"id":"ri-104","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, a 7-year-old is 58 inches tall. How must the child ride?","o":["In a seat belt, in a rear seat","In a car seat in the front","In a booster seat in the front","Without any belt in the back"],"h1":"Height of 57 inches or more changes the rule, but not the seat location.","h2":"In Rhode Island a child under 8 who is at least 57 inches tall or 80 pounds must wear a seat belt in a rear seating position.","p":"Right. A seat belt in the back seat."},"es":{"q":"En Rhode Island, un niño de 7 años mide 58 pulgadas. ¿Cómo debe viajar?","o":["Con cinturón de seguridad, en un asiento de atrás","En un asiento de seguridad adelante","En un asiento elevado adelante","Sin cinturón atrás"],"h1":"Medir 57 pulgadas o más cambia la regla, pero no el lugar del asiento.","h2":"En Rhode Island, un niño menor de 8 años que mide por lo menos 57 pulgadas o pesa 80 libras debe usar cinturón en un asiento de atrás.","p":"Correcto. Cinturón en el asiento de atrás."},"ref":{"doc":"RI","page":25}},{"id":"ri-105","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, when may a child under 8 ride in the front seat?","o":["When a parent is driving","When the car has no back seat or all rear seats are used by other children","When the trip is short","When the child asks"],"h1":"There are two exceptions about seat space.","h2":"In Rhode Island a child under 8 may ride in front only if the vehicle has no back seat or all rear seats are already used by other children.","p":"Right. Only with no back seat or a full back seat of children."},"es":{"q":"En Rhode Island, ¿cuándo puede un niño menor de 8 años ir en el asiento de adelante?","o":["Cuando maneja uno de sus padres","Cuando el carro no tiene asiento de atrás o todos los de atrás los ocupan otros niños","Cuando el viaje es corto","Cuando el niño lo pide"],"h1":"Hay dos excepciones sobre el espacio en los asientos.","h2":"En Rhode Island un niño menor de 8 años puede ir adelante solo si el vehículo no tiene asiento de atrás o si todos los asientos de atrás ya los ocupan otros niños.","p":"Correcto. Solo sin asiento de atrás o con el de atrás lleno de niños."},"ref":{"doc":"RI","page":25}},{"id":"ri-106","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, you get a ticket because your child had no car seat. How can the ticket be cancelled?","o":["Write a letter of apology","It cannot be cancelled","Show the police department proof you bought an approved car seat within 7 days","Pay double the fine"],"h1":"Buying the right seat quickly helps.","h2":"Rhode Island law voids a child restraint ticket if the driver shows the police department proof of buying an approved child seat within seven days.","p":"Right. Proof of purchase within 7 days voids it."},"es":{"q":"En Rhode Island, le ponen una multa porque su niño no tenía asiento de seguridad. ¿Cómo se puede anular la multa?","o":["Escribiendo una carta de disculpa","No se puede anular","Mostrando a la policía, dentro de 7 días, prueba de que compró un asiento aprobado","Pagando el doble de la multa"],"h1":"Comprar pronto el asiento correcto ayuda.","h2":"La ley de Rhode Island anula la multa por asiento de niño si el conductor muestra al departamento de policía, dentro de siete días, prueba de haber comprado un asiento aprobado.","p":"Correcto. La prueba de compra dentro de 7 días la anula."},"ref":{"doc":"RI","page":null}},{"id":"ri-107","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, until about what age do most children need a booster seat?","o":["Until 2 years old","Until 4 years old","Until 16 years old","Until at least 8 to 12 years old"],"h1":"Many children need one longer than parents expect.","h2":"The Rhode Island driver's manual says most children need a booster seat from about age 4 until at least between 8 and 12, which a simple five-step fit test can check.","p":"Right. Until somewhere from 8 to 12."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿hasta más o menos qué edad necesitan la mayoría de los niños un asiento elevado?","o":["Hasta los 2 años","Hasta los 4 años","Hasta los 16 años","Hasta por lo menos los 8 a 12 años"],"h1":"Muchos niños lo necesitan más tiempo de lo que los padres creen.","h2":"El manual de manejo de Rhode Island dice que la mayoría de los niños necesitan asiento elevado desde los 4 años hasta por lo menos entre los 8 y los 12, y una prueba sencilla de cinco pasos lo puede comprobar.","p":"Correcto. Hasta algún momento entre los 8 y los 12."},"ref":{"doc":"RI","page":26}},{"id":"ri-108","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, how long does it take the average driver to put on the brake after seeing danger?","o":["About three quarters of a second","About 3 seconds","About 10 seconds","No time at all"],"h1":"It is less than one second.","h2":"The Rhode Island driver's manual says the average driver takes about three quarters of a second to apply the brake after seeing danger.","p":"Right. About three quarters of a second."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuánto tarda el conductor promedio en pisar el freno después de ver un peligro?","o":["Más o menos tres cuartos de segundo","Más o menos 3 segundos","Más o menos 10 segundos","Nada de tiempo"],"h1":"Es menos de un segundo.","h2":"El manual de manejo de Rhode Island dice que el conductor promedio tarda más o menos tres cuartos de segundo en pisar el freno después de ver un peligro.","p":"Correcto. Más o menos tres cuartos de segundo."},"ref":{"doc":"RI","page":27}},{"id":"ri-109","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, what is velocitizing?","o":["Braking too hard on ice","Feeling that you are going slower than you really are","Speeding up to pass a truck","Your tires losing grip on water"],"h1":"It happens after a long time at highway speed.","h2":"The Rhode Island driver's manual calls velocitizing the feeling that you are going slower than your real speed, which is a risk when leaving a highway.","p":"Right. You feel slower than you really are."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué es el velocitizing?","o":["Frenar demasiado fuerte en el hielo","Sentir que va más despacio de lo que realmente va","Acelerar para rebasar un camión","Que las llantas pierdan agarre en el agua"],"h1":"Pasa después de mucho tiempo a velocidad de autopista.","h2":"El manual de manejo de Rhode Island llama velocitizing a la sensación de ir más despacio que su velocidad real, lo que es un riesgo al salir de una autopista.","p":"Correcto. Siente que va más despacio de lo que va."},"ref":{"doc":"RI","page":27}},{"id":"ri-110","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, about what share of all crashes happen when a vehicle is turning left?","o":["One hundredth","Nine out of ten","One sixth","One half"],"h1":"It is a little less than one in five.","h2":"The Rhode Island driver's manual says about one sixth of all crashes happen when one vehicle is turning left.","p":"Right. About one in six."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿más o menos qué parte de todos los choques ocurre cuando un vehículo da vuelta a la izquierda?","o":["Un centésimo","Nueve de cada diez","Un sexto","La mitad"],"h1":"Es un poco menos de uno de cada cinco.","h2":"El manual de manejo de Rhode Island dice que más o menos un sexto de todos los choques ocurre cuando un vehículo da vuelta a la izquierda.","p":"Correcto. Más o menos uno de cada seis."},"ref":{"doc":"RI","page":28}},{"id":"ri-111","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In the Rhode Island driver's manual, what is lane position 2?","o":["Your car in the middle of the lane","Your car 3 to 6 inches from the right line or curb","Your car on the shoulder","Your car 3 to 6 inches from the left line of your lane"],"h1":"Use it before a left turn or when there are hazards on the right.","h2":"In the Rhode Island driver's manual, lane position 2 means driving 3 to 6 inches from the left line of the lane, used before a left turn or when hazards are on the right.","p":"Right. Lane position 2 hugs the left line."},"es":{"q":"En el manual de manejo de Rhode Island, ¿qué es la posición de carril 2?","o":["Su carro en el centro del carril","Su carro a 3 a 6 pulgadas de la línea derecha o de la acera","Su carro en el acotamiento","Su carro a 3 a 6 pulgadas de la línea izquierda del carril"],"h1":"Úsela antes de dar vuelta a la izquierda o si hay peligros a la derecha.","h2":"En el manual de manejo de Rhode Island, la posición de carril 2 es manejar a 3 a 6 pulgadas de la línea izquierda del carril, antes de dar vuelta a la izquierda o cuando hay peligros a la derecha.","p":"Correcto. La posición 2 va pegada a la línea izquierda."},"ref":{"doc":"RI","page":48}},{"id":"ri-112","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In the Rhode Island driver's manual, which lane position is the safest under normal conditions?","o":["Lane position 1, in the middle of the lane","Lane position 2, near the left line","Lane position 3, near the right line","Half on the shoulder"],"h1":"With no hazards on either side, stay centered.","h2":"The Rhode Island driver's manual says lane position 1, in the middle of the lane, is the safest position when there are no hazards to the left or right.","p":"Right. Lane position 1, centered."},"es":{"q":"En el manual de manejo de Rhode Island, ¿qué posición de carril es la más segura en condiciones normales?","o":["La posición 1, en el centro del carril","La posición 2, cerca de la línea izquierda","La posición 3, cerca de la línea derecha","Medio carro en el acotamiento"],"h1":"Sin peligros a ningún lado, manténgase centrado.","h2":"El manual de manejo de Rhode Island dice que la posición de carril 1, en el centro del carril, es la más segura cuando no hay peligros a la izquierda ni a la derecha.","p":"Correcto. La posición 1, centrada."},"ref":{"doc":"RI","page":48}},{"id":"ri-113","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the Rhode Island driver's manual, when should you use lane position 3, near the right line or curb?","o":["When a bike rider is on your right","When there are hazards on your left or you plan to turn right","When you plan to turn left","On every straight road"],"h1":"It moves you away from the left side.","h2":"In the Rhode Island driver's manual, lane position 3 puts your car 3 to 6 inches from the right line or curb, used when hazards are on your left or you plan to turn right.","p":"Right. Hazards on the left or a right turn ahead."},"es":{"q":"En el manual de manejo de Rhode Island, ¿cuándo debe usar la posición de carril 3, cerca de la línea derecha o de la acera?","o":["Cuando hay un ciclista a su derecha","Cuando hay peligros a su izquierda o piensa dar vuelta a la derecha","Cuando piensa dar vuelta a la izquierda","En toda calle recta"],"h1":"Le aleja del lado izquierdo.","h2":"En el manual de manejo de Rhode Island, la posición de carril 3 pone su carro a 3 a 6 pulgadas de la línea derecha o de la acera, cuando hay peligros a su izquierda o va a dar vuelta a la derecha.","p":"Correcto. Peligros a la izquierda o vuelta a la derecha."},"ref":{"doc":"RI","page":48}},{"id":"ri-114","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In the Rhode Island driver's manual's A-B-C-D steps for turning, what does C stand for?","o":["Check your blind spot","Cross the center line","Coast into the first half of the turn, covering the brake","Cancel your signal"],"h1":"After you brake, you ease into the curve.","h2":"In the Rhode Island driver's manual, the C step means coasting into the first half of the turn with your foot covering the brake.","p":"Right. C means coast in while covering the brake."},"es":{"q":"En los pasos A-B-C-D para dar vuelta del manual de manejo de Rhode Island, ¿qué significa la C?","o":["Revisar el punto ciego","Cruzar la línea central","Entrar sin acelerar en la primera mitad de la vuelta, con el pie listo sobre el freno","Cancelar la direccional"],"h1":"Después de frenar, entra suavemente en la curva.","h2":"En el manual de manejo de Rhode Island, el paso C significa entrar sin acelerar en la primera mitad de la vuelta, con el pie listo sobre el freno.","p":"Correcto. La C es entrar sin acelerar, listo para frenar."},"ref":{"doc":"RI","page":29}},{"id":"ri-115","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, before you turn your car around on a street, how far must you be able to see in each direction?","o":["50 feet","100 feet","1 mile","500 feet"],"h1":"It is the same distance used for the headlight rule.","h2":"The Rhode Island driver's manual says to make a turnabout only where you can see clearly for 500 feet in each direction.","p":"Right. You need 500 feet of clear view each way."},"es":{"q":"En Rhode Island, antes de dar la vuelta con su carro en una calle, ¿qué tan lejos debe poder ver en cada dirección?","o":["50 pies","100 pies","1 milla","500 pies"],"h1":"Es la misma distancia de la regla de los faros.","h2":"El manual de manejo de Rhode Island dice que solo dé la vuelta en un lugar donde pueda ver claramente 500 pies en cada dirección.","p":"Correcto. Necesita 500 pies de vista libre en cada dirección."},"ref":{"doc":"RI","page":29}},{"id":"ri-116","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, how far from an intersection should you be before you turn your car around?","o":["At least 200 feet","At least 20 feet","At least 50 feet","At least 1,000 feet"],"h1":"Turning near an intersection surprises other drivers.","h2":"The Rhode Island driver's manual says to be at least 200 feet from an intersection when you make a turnabout.","p":"Right. At least 200 feet away."},"es":{"q":"En Rhode Island, ¿a qué distancia de una intersección debe estar antes de dar la vuelta con su carro?","o":["Por lo menos 200 pies","Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 1,000 pies"],"h1":"Dar la vuelta cerca de una intersección sorprende a otros conductores.","h2":"El manual de manejo de Rhode Island dice que esté por lo menos a 200 pies de una intersección al dar la vuelta.","p":"Correcto. Por lo menos 200 pies."},"ref":{"doc":"RI","page":29}},{"id":"ri-117","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, when may you make a U-turn?","o":["Only on a highway","Only where it is allowed and does not interfere with traffic","Anywhere if you signal","Across a double yellow line if the road is empty"],"h1":"It must be legal and not get in anyone's way.","h2":"In Rhode Island you may make a U-turn only where it is allowed and it does not interfere with the free flow of traffic in either direction.","p":"Right. Only where allowed and safe for traffic."},"es":{"q":"En Rhode Island, ¿cuándo puede dar una vuelta en U?","o":["Solo en una autopista","Solo donde se permite y no estorba al tráfico","En cualquier lugar si pone la direccional","Cruzando una doble línea amarilla si la calle está vacía"],"h1":"Debe ser legal y no estorbar a nadie.","h2":"En Rhode Island solo puede dar una vuelta en U donde está permitido y no estorba el paso del tráfico en ninguna dirección.","p":"Correcto. Solo donde se permite y sin estorbar."},"ref":{"doc":"RI","page":29}},{"id":"ri-118","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, how long should you stay fully stopped at a stop sign?","o":["Half a second","You may roll through slowly","At least three seconds","At least ten seconds"],"h1":"Use the time to look left, right and left again.","h2":"The Rhode Island driver's manual says to stop all forward motion for at least three seconds, giving you time to look left, right and left again.","p":"Right. At least three seconds."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuánto tiempo debe quedarse detenido por completo en un señal de PARE?","o":["Medio segundo","Puede pasar despacio sin parar","Por lo menos tres segundos","Por lo menos diez segundos"],"h1":"Use ese tiempo para mirar a la izquierda, a la derecha y otra vez a la izquierda.","h2":"El manual de manejo de Rhode Island dice que detenga todo movimiento por lo menos tres segundos, para mirar a la izquierda, a la derecha y otra vez a la izquierda.","p":"Correcto. Por lo menos tres segundos."},"ref":{"doc":"RI","page":31}},{"id":"ri-119","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, you and another car arrive at a four-way stop at the same time. The other car is on your right. Who goes first?","o":["You do","The bigger vehicle","The car that honks first","The car on your right"],"h1":"At the same time, yield to the right.","h2":"In Rhode Island, when two vehicles arrive at a four-way stop at the same time, you must yield to the vehicle on your right.","p":"Right. The car on your right goes first."},"es":{"q":"En Rhode Island, usted y otro carro llegan al mismo tiempo a un cruce con PARE en las cuatro esquinas. El otro carro está a su derecha. ¿Quién pasa primero?","o":["Usted","El vehículo más grande","El que toque la bocina primero","El carro a su derecha"],"h1":"Si llegan al mismo tiempo, ceda a la derecha.","h2":"En Rhode Island, cuando dos vehículos llegan al mismo tiempo a un cruce con PARE en las cuatro esquinas, debe ceder el paso al vehículo a su derecha.","p":"Correcto. Pasa primero el carro a su derecha."},"ref":{"doc":"RI","page":31}},{"id":"ri-120","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, how close may you park to the driveway of a fire station on the same side of the street?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 8 feet","No closer than 100 feet"],"h1":"It is the same distance as from a crosswalk at an intersection.","h2":"In Rhode Island you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay 20 feet away."},"es":{"q":"En Rhode Island, ¿qué tan cerca de la entrada de una estación de bomberos puede estacionarse del mismo lado de la calle?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 8 pies","No más cerca de 100 pies"],"h1":"Es la misma distancia que de un cruce peatonal en una intersección.","h2":"En Rhode Island no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos.","p":"Correcto. Quédese a 20 pies."},"ref":{"doc":"RI","page":32}},{"id":"ri-121","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, signs are posted at a fire station. How far must you stay from its driveway when you park across the street?","o":["500 feet","75 feet","10 feet","25 feet"],"h1":"Across the street the distance is much longer.","h2":"In Rhode Island, where signs are posted, you may not park on the opposite side of the street within 75 feet of a fire station driveway.","p":"Right. 75 feet across the street."},"es":{"q":"En Rhode Island, hay letreros en una estación de bomberos. ¿A qué distancia de su entrada debe quedarse si se estaciona del otro lado de la calle?","o":["500 pies","75 pies","10 pies","25 pies"],"h1":"Del otro lado de la calle la distancia es mucho mayor.","h2":"En Rhode Island, donde hay letreros, no puede estacionarse del lado opuesto de la calle a menos de 75 pies de la entrada de una estación de bomberos.","p":"Correcto. 75 pies del otro lado de la calle."},"ref":{"doc":"RI","page":32}},{"id":"ri-122","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Rhode Island, may you park on a bridge or in a tunnel?","o":["Yes, with your hazard lights on","Yes, for up to one hour","No, it is not allowed","Yes, at night"],"h1":"These are places where a stopped car blocks traffic badly.","h2":"Rhode Island does not allow you to stop or park on a bridge or in a tunnel.","p":"Right. No parking on bridges or in tunnels."},"es":{"q":"En Rhode Island, ¿puede estacionarse en un puente o en un túnel?","o":["Sí, con las luces intermitentes prendidas","Sí, hasta por una hora","No, no se permite","Sí, de noche"],"h1":"Son lugares donde un carro parado estorba mucho.","h2":"Rhode Island no permite parar ni estacionarse en un puente o en un túnel.","p":"Correcto. No se estacione en puentes ni túneles."},"ref":{"doc":"RI","page":32}},{"id":"ri-123","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, you are driving out of a driveway across a sidewalk to the street. Where must you stop?","o":["Only at the curb line","Only in the street","You do not need to stop if you signal","At the sidewalk, and again at the curb line"],"h1":"One stop checks for people walking, the other for cars.","h2":"In Rhode Island, when leaving a driveway or private road, you stop at the sidewalk to check for pedestrians and stop again at the curb line to check for traffic.","p":"Right. Stop at the sidewalk and again at the curb."},"es":{"q":"En Rhode Island, usted sale de una entrada de casa cruzando la acera hacia la calle. ¿Dónde debe parar?","o":["Solo en la orilla de la acera","Solo en la calle","No necesita parar si pone la direccional","En la acera y otra vez en la orilla de la acera"],"h1":"Una parada es para revisar peatones; la otra, carros.","h2":"En Rhode Island, al salir de una entrada o camino privado, para en la acera para revisar si hay peatones y otra vez en la orilla de la acera para revisar el tráfico.","p":"Correcto. Pare en la acera y otra vez en la orilla."},"ref":{"doc":"RI","page":33}},{"id":"ri-124","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, how can you warn the driver ahead at night that you are about to pass?","o":["Flash your lights from low beam to high beam and back to low","Turn on your hazard lights","Honk for three seconds","Turn off your headlights for a moment"],"h1":"Use your headlights briefly.","h2":"The Rhode Island driver's manual says at night you may blink your headlights from low to high and back to low to warn the driver ahead that you intend to pass.","p":"Right. Blink low, high, low."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cómo puede avisar de noche al conductor de adelante que lo va a rebasar?","o":["Cambiando las luces de bajas a altas y otra vez a bajas","Prendiendo las luces intermitentes","Tocando la bocina por tres segundos","Apagando los faros un momento"],"h1":"Use sus faros por un momento.","h2":"El manual de manejo de Rhode Island dice que de noche puede cambiar sus faros de bajas a altas y otra vez a bajas para avisar al conductor de adelante que lo va a rebasar.","p":"Correcto. Bajas, altas, bajas."},"ref":{"doc":"RI","page":33}},{"id":"ri-125","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, how many vehicles should you pass at one time?","o":["Two, if they are small","Never more than one","Up to three","As many as you can see"],"h1":"Passing a line of cars keeps you in the wrong lane too long.","h2":"The Rhode Island driver's manual says never to pass more than one vehicle at a time.","p":"Right. Pass only one vehicle at a time."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuántos vehículos debe rebasar a la vez?","o":["Dos, si son pequeños","Nunca más de uno","Hasta tres","Todos los que pueda ver"],"h1":"Rebasar una fila de carros le deja demasiado tiempo en el carril contrario.","h2":"El manual de manejo de Rhode Island dice que nunca rebase más de un vehículo a la vez.","p":"Correcto. Rebase solo un vehículo a la vez."},"ref":{"doc":"RI","page":33}},{"id":"ri-126","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Rhode Island, when may you pass another vehicle on the right?","o":["By driving on the shoulder","On a narrow street lined with parked cars","When the vehicle ahead is turning left and there is room","Whenever the driver ahead is slow"],"h1":"Think of a car waiting to turn left.","h2":"In Rhode Island you may pass on the right when the vehicle ahead is turning left, or on roads wide enough for two or more lanes, but never by driving off the pavement.","p":"Right. When the car ahead is turning left."},"es":{"q":"En Rhode Island, ¿cuándo puede rebasar a otro vehículo por la derecha?","o":["Manejando por el acotamiento","En una calle angosta con carros estacionados","Cuando el vehículo de adelante va a dar vuelta a la izquierda y hay espacio","Siempre que el de adelante vaya lento"],"h1":"Piense en un carro esperando para dar vuelta a la izquierda.","h2":"En Rhode Island puede rebasar por la derecha cuando el vehículo de adelante da vuelta a la izquierda, o en calles con espacio para dos carriles o más, pero nunca saliéndose del pavimento.","p":"Correcto. Cuando el de adelante da vuelta a la izquierda."},"ref":{"doc":"RI","page":33}},{"id":"ri-127","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, you need to back up more than 30 feet. What is recommended?","o":["Honk the whole time","Back up fast to finish quickly","Open your door to look back","Turn on your hazard lights"],"h1":"Warn other drivers about the unusual move.","h2":"The Rhode Island driver's manual recommends turning on your hazard lights when backing up more than 30 feet to warn other drivers.","p":"Right. Use your hazard lights."},"es":{"q":"Según el manual de manejo de Rhode Island, necesita ir en reversa más de 30 pies. ¿Qué se recomienda?","o":["Tocar la bocina todo el tiempo","Ir rápido para terminar pronto","Abrir la puerta para mirar atrás","Prender las luces intermitentes"],"h1":"Avise a otros conductores de esta maniobra poco común.","h2":"El manual de manejo de Rhode Island recomienda prender las luces intermitentes al ir en reversa más de 30 pies para avisar a otros conductores.","p":"Correcto. Use las luces intermitentes."},"ref":{"doc":"RI","page":33}},{"id":"ri-128","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, you must stop on a highway to fix your car. Where should the car be?","o":["With all four wheels off the main pavement","With two wheels on the shoulder","In the left lane","In the travel lane with the hood up"],"h1":"Get the whole car out of the traffic lanes.","h2":"The Rhode Island driver's manual says to move the car so all four wheels are off the main pavement and turn on your hazard lights before making repairs.","p":"Right. All four wheels off the pavement."},"es":{"q":"En Rhode Island, debe parar en una autopista para arreglar su carro. ¿Dónde debe quedar el carro?","o":["Con las cuatro ruedas fuera del pavimento principal","Con dos ruedas en el acotamiento","En el carril izquierdo","En el carril de tráfico con el cofre abierto"],"h1":"Saque todo el carro de los carriles de tráfico.","h2":"El manual de manejo de Rhode Island dice que mueva el carro para que las cuatro ruedas queden fuera del pavimento principal y prenda las luces intermitentes antes de hacer reparaciones.","p":"Correcto. Las cuatro ruedas fuera del pavimento."},"ref":{"doc":"RI","page":34}},{"id":"ri-129","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"On a Rhode Island freeway, what is an acceleration lane for?","o":["Parking in an emergency","Letting entering drivers speed up to match traffic","Passing slow trucks","Slowing down before an exit"],"h1":"It is at the start of an on-ramp merge.","h2":"In Rhode Island an acceleration lane lets drivers entering a freeway speed up to the speed of traffic before merging.","p":"Right. It helps you reach traffic speed."},"es":{"q":"En una autopista de Rhode Island, ¿para qué sirve un carril de aceleración?","o":["Para estacionarse en una emergencia","Para que quienes entran aceleren hasta la velocidad del tráfico","Para rebasar camiones lentos","Para frenar antes de una salida"],"h1":"Está al inicio de la incorporación desde una rampa.","h2":"En Rhode Island un carril de aceleración permite que quienes entran a una autopista aceleren hasta la velocidad del tráfico antes de incorporarse.","p":"Correcto. Le ayuda a alcanzar la velocidad del tráfico."},"ref":{"doc":"RI","page":34}},{"id":"ri-130","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"On a Rhode Island freeway with three lanes, which lane is meant for through traffic?","o":["The breakdown lane","The right lane only","The middle lane","The far left lane"],"h1":"The left lane is for passing, and the right lane is for entering and exiting.","h2":"On Rhode Island freeways the far left lane is for passing, the middle lane is for through traffic, and the right lane is for slower traffic and drivers entering or exiting.","p":"Right. The middle lane is for through traffic."},"es":{"q":"En una autopista de tres carriles en Rhode Island, ¿qué carril es para el tráfico que sigue de largo?","o":["El carril de emergencia","Solo el carril derecho","El carril del centro","El carril de la extrema izquierda"],"h1":"El izquierdo es para rebasar, y el derecho para entrar y salir.","h2":"En las autopistas de Rhode Island el carril de la extrema izquierda es para rebasar, el del centro para el tráfico que sigue de largo, y el derecho para el tráfico lento y para entrar o salir.","p":"Correcto. El del centro es para seguir de largo."},"ref":{"doc":"RI","page":35}},{"id":"ri-131","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, outside business and residential districts, what is the speed limit during the daytime when no other limit is posted?","o":["25 mph","40 mph","65 mph","50 mph"],"h1":"It is higher than the 25 mph town limit but lower than most interstates.","h2":"Rhode Island law sets 50 mph as the daytime speed limit outside business and residential districts when no other limit is posted.","p":"Right. 50 mph in the daytime."},"es":{"q":"En Rhode Island, fuera de zonas comerciales y residenciales, ¿cuál es el límite de velocidad de día cuando no hay otro límite indicado?","o":["25 mph","40 mph","65 mph","50 mph"],"h1":"Es más alto que las 25 mph del pueblo, pero más bajo que la mayoría de las interestatales.","h2":"La ley de Rhode Island fija 50 mph como límite de día fuera de zonas comerciales y residenciales cuando no hay otro límite indicado.","p":"Correcto. 50 mph de día."},"ref":{"doc":"RI","page":null}},{"id":"ri-132","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, outside business and residential districts, what is the speed limit at night when no other limit is posted?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"It is 5 mph lower than the daytime limit of 50.","h2":"Rhode Island law sets 45 mph as the nighttime speed limit outside business and residential districts when no other limit is posted.","p":"Right. 45 mph at night."},"es":{"q":"En Rhode Island, fuera de zonas comerciales y residenciales, ¿cuál es el límite de velocidad de noche cuando no hay otro límite indicado?","o":["45 mph","25 mph","35 mph","55 mph"],"h1":"Es 5 mph menos que el límite de día de 50.","h2":"La ley de Rhode Island fija 45 mph como límite de noche fuera de zonas comerciales y residenciales cuando no hay otro límite indicado.","p":"Correcto. 45 mph de noche."},"ref":{"doc":"RI","page":null}},{"id":"ri-133","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Rhode Island, what is the speed limit near a school entrance on a school day, where warning signs are posted?","o":["30 mph at all times","20 mph within 300 feet of the entrances and exits","15 mph within 50 feet","25 mph within 1 mile"],"h1":"It is lower than the 25 mph residential limit.","h2":"Rhode Island law sets a 20 mph limit within 300 feet of school grounds entrances and exits during the daytime on school days, where warning signs are posted.","p":"Right. 20 mph within 300 feet."},"es":{"q":"En Rhode Island, ¿cuál es el límite de velocidad cerca de la entrada de una escuela en día de clases, donde hay letreros de aviso?","o":["30 mph a toda hora","20 mph a menos de 300 pies de las entradas y salidas","15 mph a menos de 50 pies","25 mph a menos de 1 milla"],"h1":"Es más bajo que el límite residencial de 25 mph.","h2":"La ley de Rhode Island fija un límite de 20 mph a menos de 300 pies de las entradas y salidas de una escuela, de día y en días de clases, donde hay letreros de aviso.","p":"Correcto. 20 mph a menos de 300 pies."},"ref":{"doc":"RI","page":null}},{"id":"ri-134","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Rhode Island, the posted limit is 55 mph, but it is snowing hard. What does the Basic Speed Law say?","o":["Drive 10 mph over to get home sooner","The speed limit does not matter in snow","Drive only as fast as conditions safely allow, even below the limit","Drive 55 mph to keep up"],"h1":"The posted limit is the top speed for ideal conditions.","h2":"Rhode Island's Basic Speed Law requires you to drive only as fast as road conditions allow, because the posted limit is the maximum for ideal conditions.","p":"Right. Slow down for the conditions."},"es":{"q":"En Rhode Island, el límite indicado es 55 mph, pero está nevando fuerte. ¿Qué dice la Ley Básica de Velocidad?","o":["Maneje 10 mph más para llegar antes","El límite no importa cuando nieva","Maneje solo tan rápido como las condiciones lo permitan, aunque sea menos del límite","Maneje a 55 mph para no quedarse atrás"],"h1":"El límite indicado es la velocidad máxima en condiciones ideales.","h2":"La Ley Básica de Velocidad de Rhode Island exige manejar solo tan rápido como lo permitan las condiciones, porque el límite indicado es el máximo para condiciones ideales.","p":"Correcto. Baje la velocidad según las condiciones."},"ref":{"doc":"RI","page":35}},{"id":"ri-135","scope":"RI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Rhode Island, what is the fine for driving 1 to 10 mph over the posted speed limit?","o":["$25","$300","$1,000","$95"],"h1":"It is a little under $100.","h2":"Rhode Island's fine schedule sets a $95 fine for driving 1 to 10 mph over the posted speed limit.","p":"Right. The fine is $95."},"es":{"q":"En Rhode Island, ¿cuál es la multa por manejar de 1 a 10 mph sobre el límite indicado?","o":["$25","$300","$1,000","$95"],"h1":"Es un poco menos de $100.","h2":"La tabla de multas de Rhode Island fija una multa de $95 por manejar de 1 a 10 mph sobre el límite indicado.","p":"Correcto. La multa es de $95."},"ref":{"doc":"RI","page":null}},{"id":"ri-136","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Rhode Island, you are caught driving 15 mph over the limit. How is the fine figured?","o":["$10 for each mph over the limit, with a $205 minimum","A flat $50","A flat $95","$1 for each mph over"],"h1":"Above 10 mph over, the fine grows with every mile per hour.","h2":"Rhode Island's fine schedule charges $10 per mph over the limit, with a $205 minimum, once you are 11 mph or more over.","p":"Right. $10 per mph over, at least $205."},"es":{"q":"En Rhode Island, lo detienen manejando 15 mph sobre el límite. ¿Cómo se calcula la multa?","o":["$10 por cada mph sobre el límite, con un mínimo de $205","$50 fijos","$95 fijos","$1 por cada mph sobre el límite"],"h1":"Pasando de 10 mph sobre el límite, la multa crece con cada milla por hora.","h2":"La tabla de multas de Rhode Island cobra $10 por cada mph sobre el límite, con un mínimo de $205, cuando va 11 mph o más sobre el límite.","p":"Correcto. $10 por mph de exceso, por lo menos $205."},"ref":{"doc":"RI","page":null}},{"id":"ri-137","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, your car breaks down on the highway and you need help. What does the driver's manual suggest?","o":["Leave the car in the travel lane with the doors open","Raise the hood, tie a white cloth to the door handle and stay in your locked car","Walk along the highway to find help","Stand behind your car in the lane"],"h1":"Signal for help but keep yourself protected.","h2":"The Rhode Island driver's manual says to move off the traffic lane, raise the hood, tie a white cloth on the door handle and stay in your locked vehicle.","p":"Right. Hood up, white cloth, stay locked inside."},"es":{"q":"En Rhode Island, su carro se descompone en la autopista y necesita ayuda. ¿Qué sugiere el manual de manejo?","o":["Dejar el carro en el carril con las puertas abiertas","Levantar el cofre, amarrar un trapo blanco en la manija de la puerta y quedarse en el carro con seguro","Caminar por la autopista buscando ayuda","Pararse detrás del carro en el carril"],"h1":"Pida ayuda, pero manténgase protegido.","h2":"El manual de manejo de Rhode Island dice que salga del carril, levante el cofre, amarre un trapo blanco en la manija y se quede dentro del vehículo con seguro.","p":"Correcto. Cofre arriba, trapo blanco y adentro con seguro."},"ref":{"doc":"RI","page":35}},{"id":"ri-138","scope":"RI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Rhode Island, traffic on the highway is stopped. May you drive in the breakdown lane to get around it?","o":["Yes, during rush hour","Yes, to reach your exit","No, driving in the breakdown lane is against the law","Yes, if you go slowly"],"h1":"That lane is kept clear for emergencies.","h2":"Rhode Island law prohibits driving a motor vehicle for travel in the emergency breakdown lane of any highway.","p":"Right. Do not travel in the breakdown lane."},"es":{"q":"En Rhode Island, el tráfico en la autopista está detenido. ¿Puede manejar por el carril de emergencia para pasarlo?","o":["Sí, en horas pico","Sí, para llegar a su salida","No, manejar por el carril de emergencia es ilegal","Sí, si va despacio"],"h1":"Ese carril se deja libre para emergencias.","h2":"La ley de Rhode Island prohíbe manejar por el carril de emergencia de cualquier autopista.","p":"Correcto. No maneje por el carril de emergencia."},"ref":{"doc":"RI","page":null}},{"id":"ri-139","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, what is the fine for a driver under 18 caught using a cell phone for the first time?","o":["$10","$500","There is no fine, only a warning","$100"],"h1":"It is a round number.","h2":"Rhode Island law fines a driver under 18 $100 for a first conviction of using a wireless device while driving.","p":"Right. The first fine is $100."},"es":{"q":"En Rhode Island, ¿cuál es la multa para un conductor menor de 18 años por usar el celular por primera vez?","o":["$10","$500","No hay multa, solo una advertencia","$100"],"h1":"Es un número redondo.","h2":"La ley de Rhode Island multa con $100 al conductor menor de 18 años la primera vez que lo condenan por usar un aparato inalámbrico al manejar.","p":"Correcto. La primera multa es de $100."},"ref":{"doc":"RI","page":null}},{"id":"ri-140","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, a 17-year-old is caught using a phone while driving for the third time. What can happen to the license?","o":["It can be lost until the driver turns 18","Nothing; only a fine","It is suspended for one day","It is upgraded to a full license"],"h1":"The penalty can last until the end of the teen years.","h2":"Rhode Island law says a third phone conviction for a driver under 18 brings a $250 fine and/or loss of license until the driver's 18th birthday.","p":"Right. The license can be lost until age 18."},"es":{"q":"En Rhode Island, a un joven de 17 años lo detienen por tercera vez usando el teléfono al manejar. ¿Qué puede pasar con su licencia?","o":["Puede perderla hasta cumplir 18 años","Nada; solo una multa","Se suspende un día","Se cambia a licencia completa"],"h1":"La pena puede durar hasta el fin de la adolescencia.","h2":"La ley de Rhode Island dice que una tercera condena por usar el teléfono, para un conductor menor de 18, trae una multa de $250 y/o la pérdida de la licencia hasta cumplir 18.","p":"Correcto. Puede perder la licencia hasta los 18."},"ref":{"doc":"RI","page":null}},{"id":"ri-141","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, what is the fine for an adult's first ticket for holding a phone or texting while driving?","o":["$1,000","$100","$25","$500"],"h1":"It is the same amount as a teen's first phone fine.","h2":"Rhode Island law sets a $100 fine for a first conviction for using a hand-held wireless device, including texting, while driving.","p":"Right. The first fine is $100."},"es":{"q":"En Rhode Island, ¿cuál es la multa para un adulto la primera vez que lo multan por tener el teléfono en la mano o mandar mensajes al manejar?","o":["$1,000","$100","$25","$500"],"h1":"Es la misma cantidad que la primera multa de un adolescente por el teléfono.","h2":"La ley de Rhode Island fija una multa de $100 la primera vez que lo condenan por usar un aparato inalámbrico en la mano, incluidos los mensajes, al manejar.","p":"Correcto. La primera multa es de $100."},"ref":{"doc":"RI","page":null}},{"id":"ri-142","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, you are stopped at a red light. May you pick up your phone and read a message?","o":["Yes, if the light is long","Yes, if you put the car in park","No, being stopped at a light still counts as driving","Yes, the car is not moving"],"h1":"The law counts traffic stops as part of driving.","h2":"Rhode Island's distracted driving law counts time stopped at a traffic light or stop sign as driving, so hand-held phone use is not allowed there.","p":"Right. A red light still counts as driving."},"es":{"q":"En Rhode Island, usted está detenido en un semáforo en rojo. ¿Puede tomar el teléfono y leer un mensaje?","o":["Sí, si el semáforo es largo","Sí, si pone el carro en estacionamiento","No, estar detenido en un semáforo todavía cuenta como manejar","Sí, el carro no se mueve"],"h1":"La ley cuenta las paradas de tráfico como parte de manejar.","h2":"La ley de Rhode Island contra la distracción cuenta como manejar el tiempo detenido en un semáforo o señal de PARE, así que no se permite usar el teléfono en la mano.","p":"Correcto. Un semáforo en rojo todavía cuenta como manejar."},"ref":{"doc":"RI","page":null}},{"id":"ri-143","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, how may an adult driver use a phone's map app while driving?","o":["Holding it in one hand","Resting it on your lap","Typing a new address while moving","With the phone mounted to the car, using it hands-free"],"h1":"The phone must not be in your hand.","h2":"Rhode Island law allows a driver to start, view or stop a GPS or navigation app when the phone is mounted or attached to the vehicle for hands-free use.","p":"Right. Mount it and use it hands-free."},"es":{"q":"En Rhode Island, ¿cómo puede un conductor adulto usar la aplicación de mapas del teléfono al manejar?","o":["Sosteniéndolo en una mano","Apoyándolo en las piernas","Escribiendo una dirección nueva en movimiento","Con el teléfono montado en el carro, sin usar las manos"],"h1":"El teléfono no debe estar en su mano.","h2":"La ley de Rhode Island permite iniciar, ver o apagar una aplicación de GPS o navegación cuando el teléfono está montado o sujeto al vehículo para usarlo sin las manos.","p":"Correcto. Móntelo y úselo sin las manos."},"ref":{"doc":"RI","page":null}},{"id":"ri-144","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, by about how much does using a cell phone raise your overall risk of a crash?","o":["About 400 percent","About 4 percent","About 40 percent","It does not raise it"],"h1":"It is many times higher, not a little.","h2":"The Rhode Island driver's manual says the overall risk of a collision while using a cell phone goes up by about 400 percent.","p":"Right. About 400 percent."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿más o menos cuánto aumenta el riesgo total de choque al usar el celular?","o":["Más o menos 400 por ciento","Más o menos 4 por ciento","Más o menos 40 por ciento","No lo aumenta"],"h1":"Es varias veces más alto, no un poco.","h2":"El manual de manejo de Rhode Island dice que el riesgo total de choque al usar el celular aumenta más o menos un 400 por ciento.","p":"Correcto. Más o menos 400 por ciento."},"ref":{"doc":"RI","page":18}},{"id":"ri-145","scope":"RI","cat":"signals","sign":null,"c":1,"en":{"q":"In Rhode Island, besides before a turn, when does the law require you to signal?","o":["When you drive past a school","When you drive out of a parking space","When you stay in your lane on a straight road","When you go straight through a green light"],"h1":"Think of pulling away from the curb.","h2":"Rhode Island law requires a signal by hand or turn signal when you drive out of a parking space, as well as before turning.","p":"Right. Signal when leaving a parking space."},"es":{"q":"En Rhode Island, además de antes de una vuelta, ¿cuándo exige la ley que haga una señal?","o":["Al pasar frente a una escuela","Al salir de un espacio de estacionamiento","Al seguir en su carril en una calle recta","Al seguir derecho con luz verde"],"h1":"Piense en cuando se aleja de la orilla de la acera.","h2":"La ley de Rhode Island exige hacer una señal con la mano o la direccional al salir de un espacio de estacionamiento, además de antes de dar vuelta.","p":"Correcto. Haga una señal al salir de un estacionamiento."},"ref":{"doc":"RI","page":37}},{"id":"ri-146","scope":"RI","cat":"signals","sign":null,"c":2,"en":{"q":"In Rhode Island, when may you enter a shared center turn lane?","o":["To wait for traffic over a long distance","Whenever the road is busy","Only when you will turn within 100 feet","To pass slow cars"],"h1":"It is for turning only, and only just before the turn.","h2":"In Rhode Island drivers should not enter a shared turn lane unless they intend to turn within 100 feet.","p":"Right. Enter it only to turn within 100 feet."},"es":{"q":"En Rhode Island, ¿cuándo puede entrar a un carril central compartido para dar vuelta?","o":["Para esperar el tráfico por una distancia larga","Siempre que haya mucho tráfico","Solo cuando va a dar vuelta a menos de 100 pies","Para rebasar carros lentos"],"h1":"Es solo para dar vuelta, y justo antes de la vuelta.","h2":"En Rhode Island no se debe entrar a un carril compartido para vueltas a menos que vaya a dar vuelta dentro de 100 pies.","p":"Correcto. Entre solo para dar vuelta dentro de 100 pies."},"ref":{"doc":"RI","page":37}},{"id":"ri-147","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, you come to an intersection with no signs or signals. How should you treat it?","o":["As if you had the right of way","As if it were a four-way stop for everyone else","As a place to speed up","As if there were a yield sign"],"h1":"Be ready to let others go first.","h2":"The Rhode Island driver's manual says to treat an uncontrolled intersection as if there were a yield sign.","p":"Right. Treat it like a yield sign."},"es":{"q":"En Rhode Island, llega a una intersección sin letreros ni semáforos. ¿Cómo debe tratarla?","o":["Como si usted tuviera el derecho de paso","Como si los demás tuvieran señal de PARE","Como un lugar para acelerar","Como si hubiera una señal de CEDA EL PASO"],"h1":"Esté listo para dejar pasar a otros.","h2":"El manual de manejo de Rhode Island dice que trate una intersección sin control como si tuviera una señal de CEDA EL PASO.","p":"Correcto. Trátela como CEDA EL PASO."},"ref":{"doc":"RI","page":40}},{"id":"ri-148","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, what does it mean to cover the brake?","o":["Take your foot off the gas and hold it over the brake without pressing","Press the brake hard","Rest your left foot on the brake","Put a mat over the brake pedal"],"h1":"You are getting ready to brake, not braking yet.","h2":"The Rhode Island driver's manual says to cover the brake means taking your foot off the gas and holding it just over the brake pedal, ready to press.","p":"Right. Foot off the gas, hovering over the brake."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué significa cubrir el freno?","o":["Quitar el pie del acelerador y tenerlo sobre el freno sin pisarlo","Pisar el freno fuerte","Apoyar el pie izquierdo en el freno","Poner un tapete sobre el pedal"],"h1":"Se prepara para frenar, todavía no frena.","h2":"El manual de manejo de Rhode Island dice que cubrir el freno es quitar el pie del acelerador y tenerlo justo sobre el pedal del freno, listo para pisar.","p":"Correcto. Pie fuera del acelerador, listo sobre el freno."},"ref":{"doc":"RI","page":40}},{"id":"ri-149","scope":"RI","cat":"signals","sign":null,"c":1,"en":{"q":"In Rhode Island, you are stopped at a red light and want to turn right. There is no NO TURN ON RED sign. Must you turn on red?","o":["No, right turns on red are never allowed","No, it is allowed after a full stop but not required","Yes, you must turn right away","Yes, if someone honks"],"h1":"The law gives you a choice.","h2":"In Rhode Island drivers are permitted, but not required, to turn right on red after a full stop, yielding to traffic and pedestrians, unless a sign forbids it.","p":"Right. Allowed, but not required."},"es":{"q":"En Rhode Island, está detenido en un semáforo en rojo y quiere dar vuelta a la derecha. No hay letrero que lo prohíba. ¿Está obligado a dar vuelta en rojo?","o":["No, nunca se permite dar vuelta en rojo","No, se permite después de parar por completo, pero no es obligatorio","Sí, debe dar vuelta enseguida","Sí, si alguien toca la bocina"],"h1":"La ley le da a elegir.","h2":"En Rhode Island se permite, pero no se exige, dar vuelta a la derecha en rojo después de parar por completo y ceder el paso al tráfico y a los peatones, salvo que un letrero lo prohíba.","p":"Correcto. Se permite, pero no es obligatorio."},"ref":{"doc":"RI","page":55}},{"id":"ri-150","scope":"RI","cat":"signals","sign":null,"c":2,"en":{"q":"In the Rhode Island driver's manual, what is a stale green light?","o":["A green light that is broken","A green arrow for buses","A light that has been green for a while","A light that just turned green"],"h1":"It may turn yellow soon.","h2":"The Rhode Island driver's manual calls a light that has been green for a while a stale green light, so be ready for it to change.","p":"Right. It has been green a while."},"es":{"q":"En el manual de manejo de Rhode Island, ¿qué es una luz verde vieja (stale green)?","o":["Una luz verde descompuesta","Una flecha verde para autobuses","Una luz que lleva rato en verde","Una luz que acaba de cambiar a verde"],"h1":"Puede cambiar a amarillo pronto.","h2":"El manual de manejo de Rhode Island llama luz verde vieja a la que lleva un rato en verde, así que esté listo para que cambie.","p":"Correcto. Lleva rato en verde."},"ref":{"doc":"RI","page":40}},{"id":"ri-151","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, how should most bicycle riders get through a roundabout?","o":["Ride on the center island","Ride against traffic","Ride close to the curb next to cars","Walk the bicycle across the pedestrian crosswalks"],"h1":"Only experienced riders ride through like a car.","h2":"The Rhode Island driver's manual says cyclists should generally walk their bicycles across the pedestrian crosswalk at a roundabout; experienced riders may ride in the middle of the lane like a car.","p":"Right. Most riders walk the bike across the crosswalks."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cómo deben pasar la mayoría de los ciclistas por una rotonda?","o":["Por la isla central","En sentido contrario","Pegados a la orilla, junto a los carros","Caminando con la bicicleta por los cruces peatonales"],"h1":"Solo los ciclistas con experiencia pasan como un carro.","h2":"El manual de manejo de Rhode Island dice que en general los ciclistas deben cruzar la rotonda caminando con la bicicleta por el cruce peatonal; los que tienen experiencia pueden ir en el centro del carril como un carro.","p":"Correcto. La mayoría cruza caminando por los cruces peatonales."},"ref":{"doc":"RI","page":39}},{"id":"ri-152","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, your brake pedal goes to the floor and you pump it. How soon will you know if the brakes will hold?","o":["After three or four pumps","After one pump","After twenty pumps","Only after the car stops"],"h1":"It takes only a few tries.","h2":"The Rhode Island driver's manual says that when pumping a failed brake pedal, you will know after three or four pumps if the brakes are going to hold.","p":"Right. Three or four pumps."},"es":{"q":"Según el manual de manejo de Rhode Island, el pedal del freno se va hasta el piso y usted bombea. ¿Cuándo sabrá si los frenos van a funcionar?","o":["Después de tres o cuatro bombeos","Después de un bombeo","Después de veinte bombeos","Solo cuando el carro se pare"],"h1":"Se necesitan solo unos pocos intentos.","h2":"El manual de manejo de Rhode Island dice que, al bombear un freno que falla, sabrá después de tres o cuatro bombeos si los frenos van a funcionar.","p":"Correcto. Tres o cuatro bombeos."},"ref":{"doc":"RI","page":42}},{"id":"ri-153","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, your gas pedal sticks. What should you try first?","o":["Open your door","Kick the side of the pedal once to try to free it","Turn off the engine at high speed","Pull the parking brake as hard as you can"],"h1":"A quick tap might jar it loose.","h2":"The Rhode Island driver's manual says to first kick the side of a stuck accelerator once to try to free it, then shift to neutral while braking.","p":"Right. Kick the side of the pedal once."},"es":{"q":"Según el manual de manejo de Rhode Island, el acelerador se atora. ¿Qué debe intentar primero?","o":["Abrir la puerta","Golpear una vez el lado del pedal con el pie para soltarlo","Apagar el motor a alta velocidad","Jalar el freno de mano con toda su fuerza"],"h1":"Un golpe rápido podría soltarlo.","h2":"El manual de manejo de Rhode Island dice que primero golpee una vez con el pie el lado del acelerador atorado para soltarlo, y luego cambie a neutral mientras frena.","p":"Correcto. Golpee una vez el lado del pedal."},"ref":{"doc":"RI","page":43}},{"id":"ri-154","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, your engine suddenly dies while you are driving. What should you do right away?","o":["Turn the steering wheel sharply","Turn off the hazard lights","Shift to neutral","Brake hard in your lane"],"h1":"This lets the car roll freely while you try to restart.","h2":"The Rhode Island driver's manual says to shift to neutral when the engine first sputters or stops, then move out of traffic and try to restart.","p":"Right. Shift to neutral."},"es":{"q":"Según el manual de manejo de Rhode Island, el motor se apaga de repente mientras maneja. ¿Qué debe hacer enseguida?","o":["Girar el volante bruscamente","Apagar las luces intermitentes","Cambiar a neutral","Frenar fuerte en su carril"],"h1":"Así el carro rueda libre mientras intenta arrancarlo.","h2":"El manual de manejo de Rhode Island dice que cambie a neutral cuando el motor empiece a fallar o se apague, luego salga del tráfico e intente arrancarlo.","p":"Correcto. Cambie a neutral."},"ref":{"doc":"RI","page":43}},{"id":"ri-155","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, your right wheels drop off the road edge. About how slow should you get before steering back?","o":["30 to 40 mph","45 mph","You should speed up","5 to 10 mph"],"h1":"Slow down gently to a walking-to-jogging pace for a car.","h2":"The Rhode Island driver's manual says to let up on the gas and brake gently to 5 or 10 mph before returning to the roadway.","p":"Right. Slow to 5 to 10 mph."},"es":{"q":"Según el manual de manejo de Rhode Island, sus ruedas derechas se salen de la orilla del camino. ¿A más o menos qué velocidad debe bajar antes de regresar?","o":["De 30 a 40 mph","A 45 mph","Debe acelerar","De 5 a 10 mph"],"h1":"Baje suavemente a una velocidad muy lenta.","h2":"El manual de manejo de Rhode Island dice que suelte el acelerador y frene suavemente hasta 5 o 10 mph antes de regresar al camino.","p":"Correcto. Baje a 5 a 10 mph."},"ref":{"doc":"RI","page":43}},{"id":"ri-156","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, a car behind you is about to hit you and you cannot escape. What should you do just before the impact?","o":["Release your brakes, then brake right after the crash","Press the gas pedal to the floor","Turn sharply into the next lane","Open your door"],"h1":"This helps soften the hit.","h2":"The Rhode Island driver's manual says to release your brakes just before an unavoidable rear-end collision to soften the impact, then brake right after to avoid sliding into traffic.","p":"Right. Let off the brake just before, then brake after."},"es":{"q":"Según el manual de manejo de Rhode Island, un carro detrás de usted está a punto de chocarle y no puede escapar. ¿Qué debe hacer justo antes del golpe?","o":["Soltar el freno y frenar justo después del choque","Pisar el acelerador a fondo","Girar bruscamente al otro carril","Abrir la puerta"],"h1":"Esto ayuda a suavizar el golpe.","h2":"El manual de manejo de Rhode Island dice que suelte el freno justo antes de un choque por detrás que no puede evitar, para suavizar el golpe, y que frene justo después para no deslizarse al tráfico.","p":"Correcto. Suelte el freno justo antes y frene después."},"ref":{"doc":"RI","page":44}},{"id":"ri-157","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, a car is about to hit the side of your car. What should you do?","o":["Turn on your wipers","Brake or speed up quickly, whichever seems to lessen the impact, and honk","Close your eyes and hold the wheel","Stop and wait in place"],"h1":"Change your speed and warn the other driver.","h2":"The Rhode Island driver's manual says to brake or accelerate quickly, whichever seems more likely to lessen the impact, blow the horn and swerve away if you can.","p":"Right. Change speed, honk and swerve away."},"es":{"q":"Según el manual de manejo de Rhode Island, un carro está a punto de chocar contra el costado del suyo. ¿Qué debe hacer?","o":["Prender los limpiaparabrisas","Frenar o acelerar rápido, lo que parezca reducir el golpe, y tocar la bocina","Cerrar los ojos y sostener el volante","Parar y esperar en su lugar"],"h1":"Cambie la velocidad y avise al otro conductor.","h2":"El manual de manejo de Rhode Island dice que frene o acelere rápido, lo que parezca reducir más el golpe, toque la bocina y se aparte si puede.","p":"Correcto. Cambie la velocidad, toque la bocina y apártese."},"ref":{"doc":"RI","page":44}},{"id":"ri-158","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, your car is sinking in water before you can get out. Where should you go?","o":["Get on the floor","Open the door right away","Climb into the back seat, where air may stay longer","Stay in the driver's seat"],"h1":"The heavy engine makes the front sink first.","h2":"The Rhode Island driver's manual says that if the car sinks before you get out, climb into the rear seat, because the engine makes the car sink nose first and air may remain in the back.","p":"Right. Move to the back seat."},"es":{"q":"Según el manual de manejo de Rhode Island, su carro se hunde en el agua antes de que pueda salir. ¿A dónde debe ir?","o":["Al piso del carro","Abrir la puerta enseguida","Al asiento de atrás, donde el aire puede durar más","Quedarse en el asiento del conductor"],"h1":"El motor pesado hace que el frente se hunda primero.","h2":"El manual de manejo de Rhode Island dice que si el carro se hunde antes de salir, pase al asiento de atrás, porque el motor hace que se hunda de frente y puede quedar aire atrás.","p":"Correcto. Pase al asiento de atrás."},"ref":{"doc":"RI","page":45}},{"id":"ri-159","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, which vehicles must always stop before crossing railroad tracks?","o":["Only motorcycles","Only farm tractors","Only cars pulling a trailer","All buses and trucks carrying hazardous materials"],"h1":"Be patient behind these vehicles at a crossing.","h2":"The Rhode Island driver's manual says all buses, trucks carrying hazardous materials and certain other vehicles must always stop before crossing railroad tracks.","p":"Right. Buses and hazmat trucks always stop."},"es":{"q":"En Rhode Island, ¿qué vehículos deben parar siempre antes de cruzar las vías del tren?","o":["Solo las motocicletas","Solo los tractores de granja","Solo los carros que jalan un remolque","Todos los autobuses y los camiones que llevan materiales peligrosos"],"h1":"Tenga paciencia detrás de estos vehículos en un cruce.","h2":"El manual de manejo de Rhode Island dice que todos los autobuses, los camiones con materiales peligrosos y algunos otros vehículos deben parar siempre antes de cruzar las vías del tren.","p":"Correcto. Los autobuses y camiones con materiales peligrosos siempre paran."},"ref":{"doc":"RI","page":45}},{"id":"ri-160","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, the lights at a railroad crossing are flashing. Where must you stop?","o":["Within 50 feet but no closer than 15 feet from the nearest rail","Right on the tracks","At least 100 feet away","Within 5 feet of the rail"],"h1":"Stay clear of the tracks but not too far back.","h2":"Rhode Island law requires you to stop within 50 feet but not less than 15 feet from the nearest rail when a crossing signal warns of a train.","p":"Right. Between 15 and 50 feet from the rail."},"es":{"q":"En Rhode Island, las luces de un cruce de tren están parpadeando. ¿Dónde debe parar?","o":["A menos de 50 pies, pero no más cerca de 15 pies del riel más cercano","Sobre las vías","Por lo menos a 100 pies","A menos de 5 pies del riel"],"h1":"Quédese lejos de las vías, pero no demasiado atrás.","h2":"La ley de Rhode Island exige parar a menos de 50 pies, pero no a menos de 15 pies del riel más cercano, cuando una señal del cruce avisa que viene un tren.","p":"Correcto. Entre 15 y 50 pies del riel."},"ref":{"doc":"RI","page":null}},{"id":"ri-161","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, how much following distance should you keep behind a motorcycle?","o":["10 seconds","3 to 4 seconds","1 second","Half a second"],"h1":"It is more than the normal three-second rule.","h2":"The Rhode Island driver's manual says to keep at least 3 to 4 seconds of following distance behind a motorcycle.","p":"Right. 3 to 4 seconds."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué distancia debe dejar detrás de una motocicleta?","o":["10 segundos","De 3 a 4 segundos","1 segundo","Medio segundo"],"h1":"Es más que la regla normal de tres segundos.","h2":"El manual de manejo de Rhode Island dice que deje por lo menos de 3 a 4 segundos de distancia detrás de una motocicleta.","p":"Correcto. De 3 a 4 segundos."},"ref":{"doc":"RI","page":46}},{"id":"ri-162","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, which motorcycle riders must wear eye protection?","o":["Only passengers","Only at night","All motorcycle operators","Only riders under 21"],"h1":"Unlike the helmet rule, this one has no age limit.","h2":"Rhode Island law requires every motorcycle operator to wear approved eye protection, such as glasses, goggles or a face shield.","p":"Right. All operators need eye protection."},"es":{"q":"En Rhode Island, ¿qué motociclistas deben usar protección para los ojos?","o":["Solo los pasajeros","Solo de noche","Todos los que manejan motocicleta","Solo los menores de 21"],"h1":"A diferencia de la regla del casco, esta no tiene límite de edad.","h2":"La ley de Rhode Island exige que todo conductor de motocicleta use protección aprobada para los ojos, como lentes, gafas o careta.","p":"Correcto. Todos los conductores necesitan protección para los ojos."},"ref":{"doc":"RI","page":46}},{"id":"ri-163","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, why may a motorcycle look farther away than it really is?","o":["Its loud engine","Its bright paint","Its single headlight is too bright","Its small size"],"h1":"Small things seem farther away.","h2":"The Rhode Island driver's manual says that because of its small size a motorcycle may look farther away than it is, so assume it is closer when you turn.","p":"Right. Its small size fools your eyes."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿por qué una motocicleta puede parecer más lejos de lo que está?","o":["Por su motor ruidoso","Por su pintura brillante","Porque su único faro es muy fuerte","Por su tamaño pequeño"],"h1":"Las cosas pequeñas parecen más lejanas.","h2":"El manual de manejo de Rhode Island dice que, por su tamaño pequeño, una motocicleta puede parecer más lejos de lo que está, así que suponga que está más cerca al dar vuelta.","p":"Correcto. Su tamaño pequeño engaña la vista."},"ref":{"doc":"RI","page":46}},{"id":"ri-164","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In the Rhode Island driver's manual, what do the letters IPDE stand for?","o":["Identify, Predict, Decide, Execute","Inspect, Park, Drive, Exit","Indicate, Pass, Drive, Enter","Ignite, Proceed, Drive, End"],"h1":"It is a thinking-and-doing process to avoid crashes.","h2":"In the Rhode Island driver's manual, IPDE stands for Identify, Predict, Decide and Execute, a process that helps you avoid collisions.","p":"Right. Identify, Predict, Decide, Execute."},"es":{"q":"En el manual de manejo de Rhode Island, ¿qué significan las letras IPDE?","o":["Identificar, Predecir, Decidir, Ejecutar","Inspeccionar, Parar, Dirigir, Entrar","Indicar, Pasar, Dirigir, Entrar","Iniciar, Proceder, Dirigir, Estacionar"],"h1":"Es un proceso de pensar y actuar para evitar choques.","h2":"En el manual de manejo de Rhode Island, IPDE significa Identificar, Predecir, Decidir y Ejecutar, un proceso que ayuda a evitar choques.","p":"Correcto. Identificar, Predecir, Decidir, Ejecutar."},"ref":{"doc":"RI","page":47}},{"id":"ri-165","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual's Smith System, how far ahead should you look on a highway?","o":["About 10 miles","About half a mile","About 10 feet","Only to the car in front"],"h1":"In town it is a full block; on highways it is much farther.","h2":"The Rhode Island driver's manual's Smith System says to look ahead a full block in cities and towns and about half a mile on highways.","p":"Right. About half a mile on highways."},"es":{"q":"Según el Sistema Smith del manual de manejo de Rhode Island, ¿qué tan lejos debe mirar hacia adelante en una autopista?","o":["Más o menos 10 millas","Más o menos media milla","Más o menos 10 pies","Solo hasta el carro de adelante"],"h1":"En la ciudad es una cuadra completa; en autopistas, mucho más.","h2":"El Sistema Smith del manual de manejo de Rhode Island dice que mire una cuadra completa adelante en ciudades y pueblos, y más o menos media milla en autopistas.","p":"Correcto. Más o menos media milla en autopistas."},"ref":{"doc":"RI","page":47}},{"id":"ri-166","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In the Rhode Island driver's manual, what is the target area you should search ahead of your car?","o":["Only the area in your mirrors","The area 1 minute ahead","The area you will reach in 12 to 15 seconds","The area 1 second ahead"],"h1":"It is more than ten seconds ahead.","h2":"The Rhode Island driver's manual says to search your 12 to 15 second target area, the space you will reach in that time, for possible problems.","p":"Right. 12 to 15 seconds ahead."},"es":{"q":"En el manual de manejo de Rhode Island, ¿cuál es el área objetivo que debe revisar delante de su carro?","o":["Solo el área de sus espejos","El área a 1 minuto","El área a la que llegará en 12 a 15 segundos","El área a 1 segundo"],"h1":"Es más de diez segundos adelante.","h2":"El manual de manejo de Rhode Island dice que revise su área objetivo de 12 a 15 segundos, el espacio al que llegará en ese tiempo, buscando posibles problemas.","p":"Correcto. De 12 a 15 segundos adelante."},"ref":{"doc":"RI","page":47}},{"id":"ri-167","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In the Rhode Island driver's manual's zone system, how many zones surround your car?","o":["Two","Four","Ten","Six"],"h1":"Think front, back and the sides, with more than one in front.","h2":"The Rhode Island driver's manual's zone system divides the space around your car into six zones, each a lane wide.","p":"Right. Six zones."},"es":{"q":"En el sistema de zonas del manual de manejo de Rhode Island, ¿cuántas zonas rodean su carro?","o":["Dos","Cuatro","Diez","Seis"],"h1":"Piense en adelante, atrás y los lados, con más de una adelante.","h2":"El sistema de zonas del manual de manejo de Rhode Island divide el espacio alrededor de su carro en seis zonas, cada una del ancho de un carril.","p":"Correcto. Seis zonas."},"ref":{"doc":"RI","page":47}},{"id":"ri-168","scope":"RI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"According to the Rhode Island driver's manual, how many seconds of following distance should you keep behind the car ahead in good conditions?","o":["At least 3 seconds","1 second","Half a second","At least 10 seconds"],"h1":"Count one-thousand-one and keep going a little.","h2":"The Rhode Island driver's manual uses the three-second rule: you should pass a fixed point no sooner than three seconds after the car ahead, and add more time in bad weather.","p":"Right. At least three seconds."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuántos segundos de distancia debe dejar detrás del carro de adelante en buenas condiciones?","o":["Por lo menos 3 segundos","1 segundo","Medio segundo","Por lo menos 10 segundos"],"h1":"Cuente mil uno y siga un poco más.","h2":"El manual de manejo de Rhode Island usa la regla de los tres segundos: debe pasar un punto fijo no antes de tres segundos después del carro de adelante, y dejar más tiempo con mal clima.","p":"Correcto. Por lo menos tres segundos."},"ref":{"doc":"RI","page":48}},{"id":"ri-169","scope":"RI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In the Rhode Island driver's manual's stopping rule, you count to a fixed object ahead. If you reach it before you count how many seconds, you are going too fast to stop safely?","o":["Ten seconds","Four seconds","One second","Two seconds"],"h1":"It is one second more than the following-distance rule.","h2":"The Rhode Island driver's manual's stopping rule says you need a safe stopping distance of four seconds; if you reach the object before counting to four, slow down.","p":"Right. Four seconds."},"es":{"q":"En la regla para detenerse del manual de manejo de Rhode Island, usted cuenta hasta un objeto fijo adelante. Si llega a él antes de contar ¿cuántos segundos, va demasiado rápido para parar con seguridad?","o":["Diez segundos","Cuatro segundos","Un segundo","Dos segundos"],"h1":"Es un segundo más que la regla de distancia para seguir a otro carro.","h2":"La regla para detenerse del manual de manejo de Rhode Island dice que necesita una distancia segura de cuatro segundos; si llega al objeto antes de contar cuatro, baje la velocidad.","p":"Correcto. Cuatro segundos."},"ref":{"doc":"RI","page":48}},{"id":"ri-170","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, how far behind a large truck should you stay if you want the driver to see you?","o":["At least 10 feet","At least 1 mile","At least 50 feet","At least 5 feet"],"h1":"You should be able to see the truck's side mirrors.","h2":"The Rhode Island driver's manual says to stay at least 50 feet behind a truck if you expect the driver to see you; you are far enough back when you can see its side mirrors.","p":"Right. At least 50 feet back."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿a qué distancia detrás de un camión grande debe quedarse si quiere que el conductor lo vea?","o":["Por lo menos 10 pies","Por lo menos 1 milla","Por lo menos 50 pies","Por lo menos 5 pies"],"h1":"Debe poder ver los espejos laterales del camión.","h2":"El manual de manejo de Rhode Island dice que se quede por lo menos a 50 pies detrás de un camión si quiere que el conductor lo vea; está bastante atrás cuando puede ver sus espejos laterales.","p":"Correcto. Por lo menos 50 pies atrás."},"ref":{"doc":"RI","page":49}},{"id":"ri-171","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, from how far behind the car must the rear license plate light let the plate be read?","o":["At least 6 feet","At least 20 feet","At least 1,000 feet","At least 60 feet"],"h1":"It is a bit more than four car lengths.","h2":"Rhode Island requires the rear license plate to be lighted so it can be seen and read from at least 60 feet behind the vehicle.","p":"Right. At least 60 feet."},"es":{"q":"En Rhode Island, ¿desde qué distancia detrás del carro debe poder leerse la placa trasera gracias a su luz?","o":["Por lo menos 6 pies","Por lo menos 20 pies","Por lo menos 1,000 pies","Por lo menos 60 pies"],"h1":"Es un poco más que cuatro carros de largo.","h2":"Rhode Island exige que la placa trasera esté iluminada para que se pueda ver y leer por lo menos desde 60 pies detrás del vehículo.","p":"Correcto. Por lo menos 60 pies."},"ref":{"doc":"RI","page":49}},{"id":"ri-172","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, there is no sidewalk. Where should people walk?","o":["On the left side of the road, facing traffic","On the right side, with their back to traffic","In the middle of the road","On either side, it does not matter"],"h1":"Walkers should be able to see cars coming at them.","h2":"The Rhode Island driver's manual says that where there are no sidewalks, pedestrians should walk on the left side of the road facing traffic.","p":"Right. On the left, facing traffic."},"es":{"q":"En Rhode Island, no hay acera. ¿Por dónde deben caminar las personas?","o":["Por el lado izquierdo del camino, de frente al tráfico","Por el lado derecho, de espaldas al tráfico","Por el centro del camino","Por cualquier lado, no importa"],"h1":"Los peatones deben poder ver los carros que vienen hacia ellos.","h2":"El manual de manejo de Rhode Island dice que donde no hay aceras, los peatones deben caminar por el lado izquierdo del camino, de frente al tráfico.","p":"Correcto. Por la izquierda, de frente al tráfico."},"ref":{"doc":"RI","page":50}},{"id":"ri-173","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, is there a legal crosswalk at an intersection of public roads that has no painted lines?","o":["Only when a crossing guard is there","Yes, every such intersection has a legal crosswalk, marked or not","No, only painted crosswalks count","Only near schools"],"h1":"Paint is not what makes a crosswalk legal.","h2":"The Rhode Island driver's manual says any intersection of public roads is a legal crosswalk, whether it is marked or not.","p":"Right. Marked or not, it is a crosswalk."},"es":{"q":"En Rhode Island, ¿hay un cruce peatonal legal en una intersección de calles públicas sin líneas pintadas?","o":["Solo cuando hay un guardia de cruce","Sí, toda intersección así tiene un cruce legal, marcado o no","No, solo cuentan los cruces pintados","Solo cerca de escuelas"],"h1":"La pintura no es lo que hace legal un cruce.","h2":"El manual de manejo de Rhode Island dice que toda intersección de calles públicas es un cruce peatonal legal, esté marcado o no.","p":"Correcto. Marcado o no, es un cruce peatonal."},"ref":{"doc":"RI","page":50}},{"id":"ri-174","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the largest fine for failing to yield to a blind or low-vision pedestrian?","o":["Up to $50","There is no fine","Up to $1,000","Up to $10"],"h1":"It is one of the bigger traffic fines.","h2":"The Rhode Island driver's manual says failing to yield to a pedestrian who is blind or has low vision may bring a fine of up to $1,000.","p":"Right. Up to $1,000."},"es":{"q":"En Rhode Island, ¿cuál es la multa más alta por no ceder el paso a un peatón ciego o con poca visión?","o":["Hasta $50","No hay multa","Hasta $1,000","Hasta $10"],"h1":"Es una de las multas de tránsito más altas.","h2":"El manual de manejo de Rhode Island dice que no ceder el paso a un peatón ciego o con poca visión puede costar una multa de hasta $1,000.","p":"Correcto. Hasta $1,000."},"ref":{"doc":"RI","page":50}},{"id":"ri-175","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, what penalty can you get the first time you pass a school bus with flashing red lights?","o":["A warning only","A $20 fine","Loss of your license for life","A fine up to $300 and/or a license suspension up to 30 days"],"h1":"It is both a fine and possible time without your license.","h2":"In Rhode Island a first violation of the school bus stop law can bring a fine of up to $300 and/or a license suspension of up to 30 days, with higher penalties after that.","p":"Right. Up to $300 and up to 30 days' suspension."},"es":{"q":"En Rhode Island, ¿qué pena le pueden dar la primera vez que rebasa un autobús escolar con luces rojas intermitentes?","o":["Solo una advertencia","Una multa de $20","Perder la licencia de por vida","Una multa de hasta $300 y/o suspensión de la licencia hasta 30 días"],"h1":"Es una multa y posiblemente un tiempo sin licencia.","h2":"En Rhode Island la primera violación de la ley de parar por el autobús escolar puede traer una multa de hasta $300 y/o suspensión de la licencia hasta 30 días, con penas más altas después.","p":"Correcto. Hasta $300 y hasta 30 días de suspensión."},"ref":{"doc":"RI","page":51}},{"id":"ri-176","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, how close may you follow a school bus in the same lane?","o":["No closer than 50 feet","No closer than 10 feet","No closer than 20 feet","As close as you like when it is moving"],"h1":"Leave room in case it stops suddenly to load children.","h2":"Rhode Island law says no driver except an emergency vehicle on duty may follow a school bus in the same lane closer than 50 feet.","p":"Right. Stay at least 50 feet behind."},"es":{"q":"En Rhode Island, ¿qué tan cerca puede seguir a un autobús escolar en el mismo carril?","o":["No más cerca de 50 pies","No más cerca de 10 pies","No más cerca de 20 pies","Tan cerca como quiera si va en movimiento"],"h1":"Deje espacio por si para de repente para subir niños.","h2":"La ley de Rhode Island dice que ningún conductor, salvo un vehículo de emergencia en servicio, puede seguir a un autobús escolar en el mismo carril a menos de 50 pies.","p":"Correcto. Quédese por lo menos a 50 pies."},"ref":{"doc":"RI","page":null}},{"id":"ri-177","scope":"RI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Rhode Island, how many bicycles may ride side by side on a road?","o":["Any number","No more than two","No more than three","Only one; never side by side"],"h1":"It is a pair.","h2":"Rhode Island allows no more than two bicycles to ride side by side.","p":"Right. No more than two."},"es":{"q":"En Rhode Island, ¿cuántas bicicletas pueden ir lado a lado en un camino?","o":["Cualquier cantidad","No más de dos","No más de tres","Solo una; nunca lado a lado"],"h1":"Es un par.","h2":"Rhode Island no permite que vayan más de dos bicicletas lado a lado.","p":"Correcto. No más de dos."},"ref":{"doc":"RI","page":51}},{"id":"ri-178","scope":"RI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"According to the Rhode Island driver's manual, how much space should you give a bicycle rider when you pass?","o":["About 1 foot","No space is needed if you honk","As much as possible, about 3 to 5 feet","About 6 inches"],"h1":"Leave room in case the rider falls toward you.","h2":"The Rhode Island driver's manual says to allow as much clearance as possible, about 3 to 5 feet, when passing a bicycle rider, and be ready to stop if they fall into your lane.","p":"Right. About 3 to 5 feet or more."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿cuánto espacio debe dejar a un ciclista al rebasarlo?","o":["Más o menos 1 pie","No hace falta espacio si toca la bocina","Todo lo posible, más o menos de 3 a 5 pies","Más o menos 6 pulgadas"],"h1":"Deje espacio por si el ciclista cae hacia usted.","h2":"El manual de manejo de Rhode Island dice que deje todo el espacio posible, más o menos de 3 a 5 pies, al rebasar a un ciclista, y que esté listo para parar si cae en su carril.","p":"Correcto. De 3 a 5 pies o más."},"ref":{"doc":"RI","page":52}},{"id":"ri-179","scope":"RI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Rhode Island, when may you drive across a bicycle lane?","o":["Whenever traffic is slow","To pass cars on the right","To park in it for a few minutes","When you are turning or entering or leaving a driveway, alley or private road"],"h1":"You may cross it, but not drive along it.","h2":"In Rhode Island you may not drive in a bicycle lane, but you may cross it when turning or entering or leaving an alley, private road or driveway, after yielding to bicycle riders.","p":"Right. Only to turn or use a driveway, after yielding."},"es":{"q":"En Rhode Island, ¿cuándo puede cruzar un carril para bicicletas?","o":["Siempre que el tráfico vaya lento","Para rebasar carros por la derecha","Para estacionarse en él unos minutos","Al dar vuelta o al entrar o salir de una entrada, callejón o camino privado"],"h1":"Puede cruzarlo, pero no manejar a lo largo de él.","h2":"En Rhode Island no puede manejar en un carril para bicicletas, pero puede cruzarlo al dar vuelta o al entrar o salir de un callejón, camino privado o entrada, después de ceder el paso a los ciclistas.","p":"Correcto. Solo para dar vuelta o usar una entrada, cediendo el paso."},"ref":{"doc":"RI","page":52}},{"id":"ri-180","scope":"RI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Rhode Island, you park on a busy street. When may you open your door on the traffic side?","o":["Only when it is safe and will not interfere with traffic, including bicycles","Any time, because drivers should watch for you","Only after honking","Only at night"],"h1":"Opening a door into a bike rider is called dooring.","h2":"Rhode Island law says you may not open a car door on the traffic side until it is reasonably safe and will not interfere with traffic, including pedestrians and bicycles.","p":"Right. Only when it is safe for traffic and bicycles."},"es":{"q":"En Rhode Island, usted se estaciona en una calle con mucho tráfico. ¿Cuándo puede abrir la puerta del lado del tráfico?","o":["Solo cuando es seguro y no estorba al tráfico, incluidas las bicicletas","En cualquier momento, porque los conductores deben fijarse","Solo después de tocar la bocina","Solo de noche"],"h1":"Abrir la puerta contra un ciclista se llama dooring.","h2":"La ley de Rhode Island dice que no puede abrir la puerta del carro del lado del tráfico hasta que sea razonablemente seguro y no estorbe al tráfico, incluidos peatones y bicicletas.","p":"Correcto. Solo cuando es seguro para el tráfico y las bicicletas."},"ref":{"doc":"RI","page":53}},{"id":"ri-181","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, snow is piled on the roof of your car. What does state law require?","o":["Clear it only if you drive on a highway","Clear the snow that could blow onto other cars, and any snow and ice that blocks your view","Leave it; it will blow off","Clear only the front windshield"],"h1":"Snow flying off your roof can blind the driver behind you.","h2":"Rhode Island law makes the driver responsible for removing snow and ice that limit vision and clearing roof snow that could blow onto other vehicles.","p":"Right. Clear the windows and the roof."},"es":{"q":"En Rhode Island, hay nieve acumulada en el techo de su carro. ¿Qué exige la ley del estado?","o":["Quitarla solo si va por autopista","Quitar la nieve que podría volar sobre otros carros, y la nieve y el hielo que tapan su vista","Dejarla; se va a caer sola","Limpiar solo el parabrisas"],"h1":"La nieve que vuela del techo puede cegar al conductor de atrás.","h2":"La ley de Rhode Island hace al conductor responsable de quitar la nieve y el hielo que limitan la vista, y la nieve del techo que podría volar sobre otros vehículos.","p":"Correcto. Limpie las ventanas y el techo."},"ref":{"doc":"RI","page":55}},{"id":"ri-182","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you are stopped and cannot prove you had car insurance in effect. What can a first offense bring?","o":["A fine of $5","Loss of your license for life","A fine of $100 to $250 and a suspension of up to 30 days","A fine of $5,000"],"h1":"It is a fine of a few hundred dollars and possibly a short suspension.","h2":"Rhode Island law says a first offense of driving without proof of insurance in effect can bring a fine of $100 to $250 and a license suspension of up to 30 days, but the ticket is withdrawn if you show within one business day that you were insured.","p":"Right. $100 to $250 and up to 30 days' suspension."},"es":{"q":"En Rhode Island, lo detienen y no puede demostrar que tenía seguro de carro vigente. ¿Qué puede traer una primera infracción?","o":["Una multa de $5","Perder la licencia de por vida","Una multa de $100 a $250 y suspensión de hasta 30 días","Una multa de $5,000"],"h1":"Es una multa de unos cientos de dólares y posiblemente una suspensión corta.","h2":"La ley de Rhode Island dice que la primera infracción por manejar sin prueba de seguro vigente puede traer una multa de $100 a $250 y suspensión de la licencia de hasta 30 días, pero la multa se retira si usted demuestra en un día hábil que tenía seguro.","p":"Correcto. De $100 a $250 y hasta 30 días de suspensión."},"ref":{"doc":"RI","page":null}},{"id":"ri-183","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, what is the minimum car liability insurance?","o":["$5,000 total","$10,000 per person only","$100,000 per person and $300,000 per crash","$25,000 per person and $50,000 per crash for injuries, plus $25,000 for property damage"],"h1":"People call it 25/50/25.","h2":"Rhode Island law requires at least $25,000 for injury to one person, $50,000 for injury to two or more people in one crash, and $25,000 for property damage, or $75,000 combined.","p":"Right. 25/50/25."},"es":{"q":"En Rhode Island, ¿cuál es el seguro mínimo de responsabilidad para un carro?","o":["$5,000 en total","Solo $10,000 por persona","$100,000 por persona y $300,000 por choque","$25,000 por persona y $50,000 por choque por lesiones, más $25,000 por daños a la propiedad"],"h1":"Se le llama 25/50/25.","h2":"La ley de Rhode Island exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones a dos o más personas en un choque y $25,000 por daños a la propiedad, o $75,000 combinados.","p":"Correcto. 25/50/25."},"ref":{"doc":"RI","page":null}},{"id":"ri-184","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, earphones are not allowed while driving. Which of these is allowed?","o":["A phone headset that covers only one ear","Earbuds in both ears playing music","Over-ear headphones playing a podcast","A headset in both ears turned down low"],"h1":"You must still hear what is around you with at least one ear.","h2":"Rhode Island bans driving while wearing earphones or headsets, but allows a phone headset that gives sound through only one ear, leaving the other ear free to hear.","p":"Right. A one-ear phone headset is allowed."},"es":{"q":"En Rhode Island, no se permiten audífonos al manejar. ¿Cuál de estos sí se permite?","o":["Un audífono de teléfono que cubre solo un oído","Audífonos en los dos oídos con música","Audífonos grandes con un pódcast","Audífonos en los dos oídos a bajo volumen"],"h1":"Debe poder oír lo que pasa alrededor con por lo menos un oído.","h2":"Rhode Island prohíbe manejar con audífonos, pero permite un audífono de teléfono que da sonido por un solo oído y deja el otro libre para oír.","p":"Correcto. Se permite un audífono de un solo oído."},"ref":{"doc":"RI","page":null}},{"id":"ri-185","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, how many moving violations within 18 months can lead to driver retraining, community service and a possible suspension?","o":["Twenty","Four","Two","Ten"],"h1":"It is more than three.","h2":"Rhode Island law says a driver convicted of moving violations on four separate occasions within 18 months must attend 60 hours of retraining and do 60 hours of community service, and may be suspended.","p":"Right. Four in 18 months."},"es":{"q":"En Rhode Island, ¿cuántas infracciones en movimiento en 18 meses pueden llevar a un curso de reeducación, servicio comunitario y una posible suspensión?","o":["Veinte","Cuatro","Dos","Diez"],"h1":"Son más de tres.","h2":"La ley de Rhode Island dice que a un conductor condenado por infracciones en movimiento en cuatro ocasiones distintas en 18 meses se le ordena un curso de 60 horas y 60 horas de servicio comunitario, y se le puede suspender.","p":"Correcto. Cuatro en 18 meses."},"ref":{"doc":"RI","page":null}},{"id":"ri-186","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, a driver who is 25 has a blood alcohol level of .06 percent. Can they be convicted of drunk driving?","o":["No, only drivers under 21 can be charged","Only if they crash","Yes, if there is other evidence they were under the influence","No, it is under .08, so it is always legal"],"h1":"Below .08 is not automatically safe.","h2":"The Rhode Island driver's manual says a driver 21 or older with a BAC over .05 but under .08 can still be convicted if there is other evidence of driving under the influence.","p":"Right. Other evidence can lead to a conviction."},"es":{"q":"En Rhode Island, un conductor de 25 años tiene un nivel de alcohol en la sangre de .06 por ciento. ¿Lo pueden condenar por manejar ebrio?","o":["No, solo se puede acusar a menores de 21","Solo si choca","Sí, si hay otra prueba de que estaba bajo la influencia","No, está debajo de .08, así que siempre es legal"],"h1":"Debajo de .08 no es seguro automáticamente.","h2":"El manual de manejo de Rhode Island dice que un conductor de 21 años o más con más de .05 pero menos de .08 todavía puede ser condenado si hay otra prueba de que manejaba bajo la influencia.","p":"Correcto. Otra prueba puede llevar a una condena."},"ref":{"doc":"RI","page":58}},{"id":"ri-187","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, what does implied consent mean?","o":["You agree to let police search your phone","You agree to pay any ticket without court","You agree to let others drive your car","By driving, you have agreed to a chemical test for alcohol or drugs if arrested"],"h1":"It is about breath, blood or urine tests.","h2":"In Rhode Island implied consent means anyone who drives has already agreed to a chemical test of breath, blood or urine if arrested for suspected impaired driving.","p":"Right. Driving means you agreed to testing."},"es":{"q":"En Rhode Island, ¿qué significa el consentimiento implícito?","o":["Que acepta que la policía revise su teléfono","Que acepta pagar cualquier multa sin ir a la corte","Que acepta que otros manejen su carro","Que al manejar ya aceptó una prueba química de alcohol o drogas si lo arrestan"],"h1":"Se trata de pruebas de aliento, sangre u orina.","h2":"En Rhode Island el consentimiento implícito significa que quien maneja ya aceptó una prueba química de aliento, sangre u orina si lo arrestan por sospecha de manejar bajo la influencia.","p":"Correcto. Manejar significa que aceptó la prueba."},"ref":{"doc":"RI","page":58}},{"id":"ri-188","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, what can happen for a first offense of driving with an open alcohol container in the passenger area?","o":["A fine up to $200 and/or a license suspension up to 6 months","Nothing, if the driver is not drinking","A $5 fine","Loss of the car"],"h1":"Even an unsealed bottle you are not drinking from counts.","h2":"Rhode Island law bans any unsealed alcohol container in the passenger section, and a first violation can bring a fine up to $200 and/or a license suspension up to six months.","p":"Right. Up to $200 and up to 6 months' suspension."},"es":{"q":"En Rhode Island, ¿qué puede pasar la primera vez que maneja con un envase de alcohol abierto en el área de pasajeros?","o":["Una multa de hasta $200 y/o suspensión de la licencia hasta 6 meses","Nada, si el conductor no está tomando","Una multa de $5","Perder el carro"],"h1":"Cuenta hasta una botella abierta de la que no está tomando.","h2":"La ley de Rhode Island prohíbe cualquier envase de alcohol abierto en el área de pasajeros, y la primera violación puede traer una multa de hasta $200 y/o suspensión de la licencia hasta seis meses.","p":"Correcto. Hasta $200 y hasta 6 meses de suspensión."},"ref":{"doc":"RI","page":null}},{"id":"ri-189","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Rhode Island, an adult is convicted of a first DUI with a BAC of .08 to under .10. How long can the license be suspended?","o":["It cannot be suspended","30 to 180 days","1 to 2 days","5 to 10 years"],"h1":"It is from one month to about six months.","h2":"Rhode Island law sets a license suspension of 30 to 180 days for a first DUI with a blood alcohol level of .08 up to .10, along with a fine and community service.","p":"Right. 30 to 180 days."},"es":{"q":"En Rhode Island, condenan a un adulto por un primer caso de manejar ebrio con un nivel de alcohol de .08 a menos de .10. ¿Por cuánto tiempo pueden suspender su licencia?","o":["No se puede suspender","De 30 a 180 días","De 1 a 2 días","De 5 a 10 años"],"h1":"Es de un mes a unos seis meses.","h2":"La ley de Rhode Island fija una suspensión de 30 a 180 días por un primer caso de manejar ebrio con un nivel de alcohol de .08 a menos de .10, además de una multa y servicio comunitario.","p":"Correcto. De 30 a 180 días."},"ref":{"doc":"RI","page":60}},{"id":"ri-190","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, a second DUI counts as a repeat offense if it happens within how many years of the first?","o":["3 years","Only within 6 months","10 years","1 year"],"h1":"The look-back period is a full decade.","h2":"Rhode Island law treats a DUI as a second or third offense when it happens within a ten-year period, which brings much harsher penalties.","p":"Right. Within 10 years."},"es":{"q":"En Rhode Island, un segundo caso de manejar ebrio cuenta como reincidencia si ocurre dentro de ¿cuántos años del primero?","o":["3 años","Solo dentro de 6 meses","10 años","1 año"],"h1":"El periodo que se revisa es una década completa.","h2":"La ley de Rhode Island trata un caso de manejar ebrio como segunda o tercera ofensa cuando ocurre dentro de un periodo de diez años, lo que trae penas mucho más duras.","p":"Correcto. Dentro de 10 años."},"ref":{"doc":"RI","page":null}},{"id":"ri-191","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Rhode Island, a 19-year-old drives alone with closed cans of beer in the trunk. It is not for a job. What can happen for a first offense?","o":["Nothing, because the cans are closed","Only a warning","A lifetime license ban","A fine up to $250 and a license suspension up to 30 days"],"h1":"Under 21, even unopened alcohol in the car counts.","h2":"Rhode Island law says a driver under 21 who knowingly has alcohol in the vehicle, opened or unopened, without a parent or certain adult relatives, faces up to a $250 fine and up to 30 days' suspension for a first offense.","p":"Right. Up to $250 and up to 30 days' suspension."},"es":{"q":"En Rhode Island, un joven de 19 años maneja solo con latas de cerveza cerradas en la cajuela. No es por trabajo. ¿Qué puede pasar la primera vez?","o":["Nada, porque las latas están cerradas","Solo una advertencia","Perder la licencia de por vida","Una multa de hasta $250 y suspensión de la licencia hasta 30 días"],"h1":"Si es menor de 21, hasta el alcohol cerrado en el carro cuenta.","h2":"La ley de Rhode Island dice que un conductor menor de 21 que a sabiendas lleva alcohol en el vehículo, abierto o cerrado, sin un padre o ciertos parientes adultos, puede recibir hasta $250 de multa y hasta 30 días de suspensión la primera vez.","p":"Correcto. Hasta $250 y hasta 30 días de suspensión."},"ref":{"doc":"RI","page":null}},{"id":"ri-192","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, a person under 21 is caught with an alcoholic drink. What happens to their driver's license?","o":["It is suspended for at least 60 days","Nothing happens to the license","It is suspended for one day","It is upgraded"],"h1":"It is about two months or more.","h2":"Rhode Island law says a person under 21 found possessing alcohol is fined and is subject to a driver's license suspension of at least 60 days.","p":"Right. At least 60 days' suspension."},"es":{"q":"En Rhode Island, a una persona menor de 21 años la encuentran con una bebida alcohólica. ¿Qué pasa con su licencia de conducir?","o":["Se suspende por lo menos 60 días","No le pasa nada a la licencia","Se suspende un día","Se mejora"],"h1":"Son unos dos meses o más.","h2":"La ley de Rhode Island dice que a una persona menor de 21 que tiene alcohol se le multa y se le puede suspender la licencia por lo menos 60 días.","p":"Correcto. Por lo menos 60 días de suspensión."},"ref":{"doc":"RI","page":61}},{"id":"ri-193","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, you hit a parked car and the owner is not there. What must you do?","o":["Only call your insurance company","Leave your name and address in writing on the car and report it to the police","Drive away if the damage is small","Wait one hour, then leave"],"h1":"The owner must be able to find you, and police must be told.","h2":"In Rhode Island, if you hit an unattended vehicle, you must securely attach your name and address in writing to it and report the collision to the nearest state or local police right away.","p":"Right. Leave a written note and call the police."},"es":{"q":"En Rhode Island, choca contra un carro estacionado y el dueño no está. ¿Qué debe hacer?","o":["Solo llamar a su compañía de seguros","Dejar su nombre y dirección por escrito en el carro y avisar a la policía","Irse si el daño es pequeño","Esperar una hora y luego irse"],"h1":"El dueño debe poder encontrarle, y hay que avisar a la policía.","h2":"En Rhode Island, si choca contra un vehículo sin nadie, debe dejar bien sujetos en él su nombre y dirección por escrito y avisar enseguida a la policía estatal o local más cercana.","p":"Correcto. Deje una nota escrita y llame a la policía."},"ref":{"doc":"RI","page":62}},{"id":"ri-194","scope":"RI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Rhode Island, you have a crash with an injury or more than $1,000 in damage. How soon must you send a written report to the DMV?","o":["Within 6 months","Only if police ask","Within 21 days","Within 24 hours"],"h1":"It is three weeks.","h2":"Rhode Island law requires a driver in a crash with injury, death or more than $1,000 property damage to send a written report to the DMV within 21 days.","p":"Right. Within 21 days."},"es":{"q":"En Rhode Island, usted tiene un choque con un herido o con más de $1,000 de daños. ¿En cuánto tiempo debe enviar un informe escrito a la DMV?","o":["Dentro de 6 meses","Solo si la policía lo pide","Dentro de 21 días","Dentro de 24 horas"],"h1":"Son tres semanas.","h2":"La ley de Rhode Island exige que el conductor en un choque con heridos, muertos o más de $1,000 de daños envíe un informe escrito a la DMV dentro de 21 días.","p":"Correcto. Dentro de 21 días."},"ref":{"doc":"RI","page":null}},{"id":"ri-195","scope":"RI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Rhode Island, what kind of crime is it to leave the scene of a crash in which someone was hurt?","o":["A parking ticket","A warning","No crime if you call later","A felony"],"h1":"It is the most serious kind of charge.","h2":"In Rhode Island failing to stop after a collision that causes personal injury or death is a felony.","p":"Right. It is a felony."},"es":{"q":"En Rhode Island, ¿qué tipo de delito es irse del lugar de un choque donde alguien resultó herido?","o":["Una multa de estacionamiento","Una advertencia","No es delito si llama después","Un delito grave (felony)"],"h1":"Es el tipo de cargo más serio.","h2":"En Rhode Island no parar después de un choque que causa lesiones o muerte es un delito grave (felony).","p":"Correcto. Es un delito grave."},"ref":{"doc":"RI","page":63}},{"id":"ri-196","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, a police officer pulls you over. When should you take off your seat belt?","o":["Not until the officer has seen you wearing it","Right away, before the officer arrives","As soon as you stop","Before you open the window"],"h1":"Show the officer you were buckled up.","h2":"The Rhode Island driver's manual says to keep your seat belt fastened until the officer has seen you wearing it, and not to take it off without asking.","p":"Right. Keep it on until the officer sees it."},"es":{"q":"En Rhode Island, un policía le hace parar. ¿Cuándo debe quitarse el cinturón de seguridad?","o":["No antes de que el policía le haya visto con él puesto","Enseguida, antes de que llegue el policía","En cuanto se detenga","Antes de bajar la ventana"],"h1":"Muestre al policía que traía el cinturón.","h2":"El manual de manejo de Rhode Island dice que mantenga el cinturón puesto hasta que el policía le haya visto con él, y que no se lo quite sin preguntar.","p":"Correcto. Déjelo puesto hasta que el policía lo vea."},"ref":{"doc":"RI","page":69}},{"id":"ri-197","scope":"RI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Rhode Island, an officer asks you to sign a traffic ticket. What does signing mean?","o":["That you will pay double","Only that you received the ticket, not that you are guilty","That you admit you are guilty","That you give up your right to court"],"h1":"It is just a receipt.","h2":"In Rhode Island signing a citation is not an admission of guilt; it only shows you received it, and refusing to sign can lead to arrest.","p":"Right. It only shows you got the ticket."},"es":{"q":"En Rhode Island, un policía le pide que firme una multa. ¿Qué significa firmar?","o":["Que pagará el doble","Solo que recibió la multa, no que es culpable","Que admite que es culpable","Que renuncia a ir a la corte"],"h1":"Es solo un recibo.","h2":"En Rhode Island firmar una multa no es admitir la culpa; solo muestra que la recibió, y negarse a firmar puede llevar al arresto.","p":"Correcto. Solo muestra que recibió la multa."},"ref":{"doc":"RI","page":64}},{"id":"ri-198","scope":"RI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Rhode Island, what is the least tread depth allowed on a tire?","o":["1/2 inch","1 inch","2/32 of an inch","1/64 of an inch"],"h1":"It is measured in thirty-seconds of an inch.","h2":"Rhode Island law says no tire on a vehicle on the highway may have less than 2/32 of an inch of tread depth.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En Rhode Island, ¿cuál es la profundidad mínima permitida en el dibujo de una llanta?","o":["1/2 pulgada","1 pulgada","2/32 de pulgada","1/64 de pulgada"],"h1":"Se mide en treintaidosavos de pulgada.","h2":"La ley de Rhode Island dice que ninguna llanta de un vehículo en la vía puede tener menos de 2/32 de pulgada de profundidad en el dibujo.","p":"Correcto. Por lo menos 2/32 de pulgada."},"ref":{"doc":"RI","page":null}},{"id":"ri-199","scope":"RI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Rhode Island driver's manual, what should you never do with your car's tires?","o":["Check the pressure when they are cold","Follow the owner's manual schedule","Measure the tread","Mix radial tires with bias-belted tires"],"h1":"All four tires should be the same kind.","h2":"The Rhode Island driver's manual says never to mix and match tire types, such as radial with bias-belted tires.","p":"Right. Never mix radial and bias-belted tires."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué nunca debe hacer con las llantas de su carro?","o":["Revisar la presión cuando están frías","Seguir el calendario del manual del dueño","Medir el dibujo","Mezclar llantas radiales con llantas de capas diagonales"],"h1":"Las cuatro llantas deben ser del mismo tipo.","h2":"El manual de manejo de Rhode Island dice que nunca mezcle tipos de llantas, como radiales con llantas de capas diagonales.","p":"Correcto. Nunca mezcle radiales con diagonales."},"ref":{"doc":"RI","page":65}},{"id":"ri-200","scope":"RI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Rhode Island, how much light must pass through tinted car windows?","o":["At least 70 percent","At least 5 percent","At least 20 percent","At least 35 percent"],"h1":"It is more than two thirds of the light.","h2":"The Rhode Island driver's manual says the state follows the federal standard of at least 70 percent visible light through the windows, and an illegal tint can bring a $250 fine.","p":"Right. At least 70 percent."},"es":{"q":"En Rhode Island, ¿cuánta luz debe pasar por las ventanas polarizadas de un carro?","o":["Por lo menos 70 por ciento","Por lo menos 5 por ciento","Por lo menos 20 por ciento","Por lo menos 35 por ciento"],"h1":"Es más de dos tercios de la luz.","h2":"El manual de manejo de Rhode Island dice que el estado sigue la norma federal de por lo menos 70 por ciento de luz visible por las ventanas, y un polarizado ilegal puede costar una multa de $250.","p":"Correcto. Por lo menos 70 por ciento."},"ref":{"doc":"RI","page":69}},{"id":"ri-201","scope":"RI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Rhode Island driver's manual, what should you avoid doing inside a work zone?","o":["Watching for workers","Changing lanes","Following the flagger","Slowing down"],"h1":"Merge early, before you enter the zone.","h2":"The Rhode Island driver's manual says to pay close attention to merge signs and flaggers and not change lanes within the work zone; merge as soon as you can before it.","p":"Right. Do not change lanes in a work zone."},"es":{"q":"Según el manual de manejo de Rhode Island, ¿qué debe evitar hacer dentro de una zona de construcción?","o":["Fijarse en los trabajadores","Cambiar de carril","Seguir las señales del abanderado","Bajar la velocidad"],"h1":"Incorpórese pronto, antes de entrar a la zona.","h2":"El manual de manejo de Rhode Island dice que preste atención a los letreros de incorporación y a los abanderados, y que no cambie de carril dentro de la zona de construcción; incorpórese lo antes posible antes de ella.","p":"Correcto. No cambie de carril en una zona de construcción."},"ref":{"doc":"RI","page":71}},{"id":"sc-001","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, what is the youngest age to get a beginner's permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the special restricted license.","h2":"In South Carolina you can get a beginner's permit at 15, after you pass the vision and knowledge tests.","p":"Right. The beginner's permit starts at 15."},"es":{"q":"En Carolina del Sur, ¿cuál es la edad mínima para obtener el permiso de principiante?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia restringida especial.","h2":"En Carolina del Sur usted puede obtener el permiso de principiante a los 15 años, después de aprobar el examen de la vista y el examen de conocimientos.","p":"Correcto. El permiso de principiante empieza a los 15."},"zh":{"q":"在 South Carolina，最小几岁可以拿到初学者学习驾照（beginner's permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比特别限制驾照早一年。","h2":"在 South Carolina，你 15 岁通过视力考试和知识考试后，就可以拿到初学者学习驾照。","p":"对。初学者学习驾照从 15 岁开始。"},"vi":{"q":"Ở South Carolina, tuổi nhỏ nhất để lấy giấy phép tập lái (beginner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước bằng lái hạn chế đặc biệt.","h2":"Ở South Carolina, bạn có thể lấy giấy phép tập lái lúc 15 tuổi, sau khi đậu bài kiểm tra thị lực và bài kiểm tra kiến thức.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa South Carolina, ano ang pinakabatang edad para makakuha ng permit ng baguhan (beginner's permit)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang espesyal na limitadong lisensya.","h2":"Sa South Carolina, makakakuha ka ng permit ng baguhan sa edad na 15, pagkatapos mong pumasa sa pagsusulit sa paningin at sa pagsusulit sa kaalaman.","p":"Tama. Nagsisimula ang permit ng baguhan sa 15."},"ar":{"q":"في South Carolina، ما أصغر عمر للحصول على تصريح المبتدئ (beginner's permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل الرخصة المقيدة الخاصة بسنة واحدة.","h2":"في South Carolina يمكنك الحصول على تصريح المبتدئ في عمر 15 سنة، بعد أن تنجح في فحص النظر واختبار المعرفة.","p":"صحيح. تصريح المبتدئ يبدأ من عمر 15 سنة."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-002","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, who must supervise a driver with a beginner's permit?","o":["Any passenger 16 or older","Any adult with a car","A licensed driver 18 or older","A licensed driver 21 or older with at least one year of driving experience"],"h1":"The helper must be an adult with some experience behind the wheel.","h2":"A South Carolina permit holder must be supervised by a licensed driver who is at least 21 and has at least one year of driving experience.","p":"Right. 21 or older, with a year of experience."},"es":{"q":"En Carolina del Sur, ¿quién debe supervisar a un conductor con permiso de principiante?","o":["Cualquier pasajero de 16 años o más","Cualquier adulto con carro","Un conductor con licencia de 18 años o más","Un conductor con licencia de 21 años o más con por lo menos un año de experiencia"],"h1":"El acompañante debe ser un adulto con algo de experiencia al volante.","h2":"Quien tiene permiso en Carolina del Sur debe estar supervisado por un conductor con licencia de por lo menos 21 años y con por lo menos un año de experiencia manejando.","p":"Correcto. 21 años o más, con un año de experiencia."},"zh":{"q":"在 South Carolina，谁必须陪同持有初学者学习驾照的司机？","o":["任何 16 岁或以上的乘客","任何有车的成年人","18 岁或以上的持照司机","21 岁或以上、至少有一年驾驶经验的持照司机"],"h1":"陪同的人必须是有一些开车经验的成年人。","h2":"在 South Carolina，学习驾照持有人必须由至少 21 岁、至少有一年驾驶经验的持照司机陪同。","p":"对。21 岁或以上，有一年经验。"},"vi":{"q":"Ở South Carolina, ai phải giám sát người lái có giấy phép tập lái?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Bất kỳ người lớn nào có xe","Một người có bằng lái từ 18 tuổi trở lên","Một người có bằng lái từ 21 tuổi trở lên, có ít nhất một năm kinh nghiệm lái xe"],"h1":"Người giúp phải là người lớn có kinh nghiệm lái xe.","h2":"Ở South Carolina, người có giấy phép tập lái phải được giám sát bởi một người có bằng lái ít nhất 21 tuổi và có ít nhất một năm kinh nghiệm lái xe.","p":"Đúng. Từ 21 tuổi trở lên, có một năm kinh nghiệm."},"tl":{"q":"Sa South Carolina, sino ang dapat magbantay sa drayber na may permit ng baguhan?","o":["Kahit sinong pasahero na 16 o mas matanda","Kahit sinong adulto na may kotse","Isang drayber na may lisensya na 18 o mas matanda","Isang drayber na may lisensya na 21 o mas matanda at may hindi bababa sa isang taon na karanasan sa pagmamaneho"],"h1":"Ang tagabantay ay dapat adulto na may karanasan sa pagmamaneho.","h2":"Sa South Carolina, ang may hawak ng permit ay dapat bantayan ng drayber na may lisensya na hindi bababa sa 21 taong gulang at may hindi bababa sa isang taon na karanasan sa pagmamaneho.","p":"Tama. 21 o mas matanda, na may isang taon na karanasan."},"ar":{"q":"في South Carolina، من يجب أن يشرف على سائق معه تصريح المبتدئ؟","o":["أي راكب عمره 16 سنة أو أكثر","أي شخص بالغ عنده سيارة","سائق مرخص عمره 18 سنة أو أكثر","سائق مرخص عمره 21 سنة أو أكثر وعنده خبرة قيادة سنة واحدة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا عنده بعض الخبرة في القيادة.","h2":"في South Carolina يجب أن يشرف على صاحب التصريح سائق مرخص عمره 21 سنة على الأقل وعنده خبرة قيادة سنة واحدة على الأقل.","p":"صحيح. 21 سنة أو أكثر، مع سنة من الخبرة."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-003","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, a permit holder wants to practice at 1 a.m. Who must be the supervisor?","o":["A licensed parent or guardian","Any licensed adult 21 or older","A driving instructor only","No one; practice is not allowed"],"h1":"Late at night, the rule is about family.","h2":"In South Carolina, a permit holder driving between midnight and 6 a.m. must be supervised by a licensed parent or guardian, or another adult the law allows, such as one with notarized permission from a parent.","p":"Right. A licensed parent or guardian after midnight."},"es":{"q":"En Carolina del Sur, quien tiene permiso quiere practicar a la 1 a.m. ¿Quién debe ser el supervisor?","o":["Un padre, madre o tutor con licencia","Cualquier adulto con licencia de 21 años o más","Solo un instructor de manejo","Nadie; no se permite practicar"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"En Carolina del Sur, quien tiene permiso y maneja entre la medianoche y las 6 a.m. debe estar supervisado por su padre, madre o tutor con licencia, u otro adulto que la ley permite, como uno con permiso notariado de un padre.","p":"Correcto. Un padre o tutor con licencia después de la medianoche."},"zh":{"q":"在 South Carolina，学习驾照持有人想在凌晨 1 点练车。谁必须陪同？","o":["持有驾照的父母或监护人","任何 21 岁或以上的持照成年人","只能是驾驶教练","没有人；不允许练车"],"h1":"深夜的规定和家人有关。","h2":"在 South Carolina，学习驾照持有人在午夜到早上 6 点之间开车，必须由持有驾照的父母或监护人陪同，或由法律允许的其他成年人陪同，例如有父母公证许可的人。","p":"对。午夜以后要有持照的父母或监护人。"},"vi":{"q":"Ở South Carolina, người có giấy phép tập lái muốn tập lúc 1 giờ sáng. Ai phải giám sát?","o":["Cha mẹ hoặc người giám hộ có bằng lái","Bất kỳ người lớn nào có bằng lái từ 21 tuổi trở lên","Chỉ huấn luyện viên lái xe","Không ai cả; không được tập"],"h1":"Vào khuya, luật liên quan đến gia đình.","h2":"Ở South Carolina, người có giấy phép tập lái lái xe từ nửa đêm đến 6 giờ sáng phải được giám sát bởi cha mẹ hoặc người giám hộ có bằng lái, hoặc một người lớn khác mà luật cho phép, ví dụ người có giấy phép của cha mẹ được công chứng.","p":"Đúng. Sau nửa đêm phải có cha mẹ hoặc người giám hộ có bằng lái."},"tl":{"q":"Sa South Carolina, gustong magpraktis ng may hawak ng permit nang 1 a.m. Sino ang dapat magbantay?","o":["Magulang o tagapag-alaga na may lisensya","Kahit sinong adulto na may lisensya na 21 o mas matanda","Instruktor sa pagmamaneho lamang","Wala; hindi pinapayagan ang praktis"],"h1":"Sa hatinggabi, tungkol sa pamilya ang patakaran.","h2":"Sa South Carolina, ang may hawak ng permit na nagmamaneho mula hatinggabi hanggang 6 a.m. ay dapat bantayan ng magulang o tagapag-alaga na may lisensya, o ng ibang adulto na pinapayagan ng batas, gaya ng may notaryadong pahintulot mula sa magulang.","p":"Tama. Magulang o tagapag-alaga na may lisensya pagkalipas ng hatinggabi."},"ar":{"q":"في South Carolina، صاحب تصريح يريد أن يتدرب الساعة 1 بعد منتصف الليل. من يجب أن يكون المشرف؟","o":["أحد الوالدين أو الوصي المرخص","أي شخص بالغ مرخص عمره 21 سنة أو أكثر","مدرب قيادة فقط","لا أحد؛ التدريب غير مسموح"],"h1":"في وقت متأخر من الليل، القاعدة تتعلق بالعائلة.","h2":"في South Carolina، صاحب التصريح الذي يقود بين منتصف الليل والساعة 6 صباحًا يجب أن يشرف عليه أحد الوالدين أو الوصي المرخص، أو شخص بالغ آخر يسمح به القانون، مثل شخص معه إذن موثق من أحد الوالدين.","p":"صحيح. أحد الوالدين أو الوصي المرخص بعد منتصف الليل."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-004","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long must a teen hold a beginner's permit before taking the road test?","o":["30 days","90 days","180 days","365 days"],"h1":"It is about six months.","h2":"A South Carolina driver with no experience must hold the beginner's permit for 180 days before the road test, unless they are 18 or older.","p":"Right. 180 days with the permit."},"es":{"q":"En Carolina del Sur, ¿cuánto tiempo debe tener un adolescente el permiso de principiante antes del examen de manejo?","o":["30 días","90 días","180 días","365 días"],"h1":"Son unos seis meses.","h2":"En Carolina del Sur, un conductor sin experiencia debe tener el permiso de principiante 180 días antes del examen de manejo, salvo que tenga 18 años o más.","p":"Correcto. 180 días con el permiso."},"zh":{"q":"在 South Carolina，青少年必须持有初学者学习驾照多久，才能参加路考？","o":["30 天","90 天","180 天","365 天"],"h1":"大约六个月。","h2":"在 South Carolina，没有驾驶经验的司机必须持有初学者学习驾照 180 天才能参加路考，18 岁或以上的人除外。","p":"对。持有学习驾照 180 天。"},"vi":{"q":"Ở South Carolina, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi thi lái trên đường?","o":["30 ngày","90 ngày","180 ngày","365 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở South Carolina, người chưa có kinh nghiệm lái xe phải giữ giấy phép tập lái 180 ngày trước khi thi lái trên đường, trừ khi họ từ 18 tuổi trở lên.","p":"Đúng. Giữ giấy phép 180 ngày."},"tl":{"q":"Sa South Carolina, gaano katagal dapat hawak ng tinedyer ang permit ng baguhan bago kumuha ng pagsusulit sa kalsada?","o":["30 araw","90 araw","180 araw","365 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa South Carolina, ang drayber na walang karanasan ay dapat humawak ng permit ng baguhan nang 180 araw bago ang pagsusulit sa kalsada, maliban kung sila ay 18 o mas matanda.","p":"Tama. 180 araw na may permit."},"ar":{"q":"في South Carolina، كم مدة يجب أن يحمل المراهق تصريح المبتدئ قبل اختبار القيادة على الطريق؟","o":["30 يومًا","90 يومًا","180 يومًا","365 يومًا"],"h1":"إنها حوالي ستة أشهر.","h2":"في South Carolina، السائق الذي ليس عنده خبرة يجب أن يحمل تصريح المبتدئ 180 يومًا قبل اختبار القيادة على الطريق، إلا إذا كان عمره 18 سنة أو أكثر.","p":"صحيح. 180 يومًا مع التصريح."},"ref":{"doc":"SC","page":"1-4"}},{"id":"sc-005","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, how many hours of supervised practice must a teen complete before a conditional license?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is less than a full week of work hours.","h2":"A South Carolina teen must complete at least 40 hours of supervised practice before a conditional license.","p":"Right. 40 hours of practice."},"es":{"q":"En Carolina del Sur, ¿cuántas horas de práctica supervisada debe completar un adolescente antes de la licencia condicional?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Son menos que una semana completa de horas de trabajo.","h2":"Un adolescente en Carolina del Sur debe completar por lo menos 40 horas de práctica supervisada antes de la licencia condicional.","p":"Correcto. 40 horas de práctica."},"zh":{"q":"在 South Carolina，青少年拿条件驾照（conditional license）前，必须完成多少小时有人陪同的练习？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它比一整周的工作时间少。","h2":"在 South Carolina，青少年必须完成至少 40 小时有人陪同的练习，才能拿条件驾照。","p":"对。练习 40 小时。"},"vi":{"q":"Ở South Carolina, thiếu niên phải tập lái có giám sát bao nhiêu giờ trước khi lấy bằng lái có điều kiện (conditional license)?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Ít hơn số giờ làm việc của một tuần.","h2":"Ở South Carolina, thiếu niên phải tập lái có giám sát ít nhất 40 giờ trước khi lấy bằng lái có điều kiện.","p":"Đúng. Tập 40 giờ."},"tl":{"q":"Sa South Carolina, ilang oras ng praktis na may bantay ang dapat tapusin ng tinedyer bago makakuha ng kondisyonal na lisensya (conditional license)?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Mas kaunti ito sa oras ng trabaho sa isang buong linggo.","h2":"Sa South Carolina, ang tinedyer ay dapat tumapos ng hindi bababa sa 40 oras ng praktis na may bantay bago makakuha ng kondisyonal na lisensya.","p":"Tama. 40 oras ng praktis."},"ar":{"q":"في South Carolina، كم ساعة من التدريب تحت الإشراف يجب أن يكملها المراهق قبل الرخصة المشروطة (conditional license)؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنها أقل من ساعات العمل في أسبوع كامل.","h2":"في South Carolina يجب أن يكمل المراهق 40 ساعة على الأقل من التدريب تحت الإشراف قبل الرخصة المشروطة.","p":"صحيح. 40 ساعة من التدريب."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-006","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, how many of the 40 practice hours must be driven in darkness?","o":["None","2 hours","5 hours","10 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in South Carolina must be driven in darkness.","p":"Right. Ten hours after dark."},"es":{"q":"En Carolina del Sur, ¿cuántas de las 40 horas de práctica deben manejarse en la oscuridad?","o":["Ninguna","2 horas","5 horas","10 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Carolina del Sur deben manejarse en la oscuridad.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 South Carolina，40 小时练习中有多少小时必须在天黑时开？","o":["不需要","2 小时","5 小时","10 小时"],"h1":"它是总数的四分之一。","h2":"在 South Carolina，40 小时练习中至少有 10 小时必须在天黑时开。","p":"对。天黑后开 10 小时。"},"vi":{"q":"Ở South Carolina, trong 40 giờ tập lái, bao nhiêu giờ phải lái khi trời tối?","o":["Không giờ nào","2 giờ","5 giờ","10 giờ"],"h1":"Đó là một phần tư tổng số giờ.","h2":"Ở South Carolina, ít nhất 10 trong 40 giờ tập lái phải lái khi trời tối.","p":"Đúng. Mười giờ sau khi trời tối."},"tl":{"q":"Sa South Carolina, ilan sa 40 oras ng praktis ang dapat imaneho sa dilim?","o":["Wala","2 oras","5 oras","10 oras"],"h1":"Isang-kapat ito ng kabuuan.","h2":"Sa South Carolina, hindi bababa sa 10 sa 40 oras ng praktis ang dapat imaneho sa dilim.","p":"Tama. Sampung oras pagkadilim."},"ar":{"q":"في South Carolina، كم ساعة من ساعات التدريب الـ 40 يجب أن تكون في الظلام؟","o":["ولا ساعة","2 ساعة","5 ساعات","10 ساعات"],"h1":"إنها ربع المجموع.","h2":"في South Carolina يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 في الظلام.","p":"صحيح. عشر ساعات بعد حلول الظلام."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-007","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, until what time may a conditional license holder drive alone in standard time (not daylight saving time)?","o":["Midnight","9 p.m.","6 p.m.","10 p.m."],"h1":"It is early in the evening.","h2":"A South Carolina conditional license holder may drive alone from 6 a.m. until 6 p.m. in standard time.","p":"Right. Alone until 6 p.m."},"es":{"q":"En Carolina del Sur, ¿hasta qué hora puede manejar solo quien tiene licencia condicional en horario normal (no de verano)?","o":["Medianoche","9 p.m.","6 p.m.","10 p.m."],"h1":"Es temprano por la tarde.","h2":"Quien tiene licencia condicional en Carolina del Sur puede manejar solo de 6 a.m. a 6 p.m. en horario normal.","p":"Correcto. Solo hasta las 6 p.m."},"zh":{"q":"在 South Carolina，在标准时间（不是夏令时），条件驾照持有人可以独自开车到几点？","o":["午夜","晚上 9 点","晚上 6 点","晚上 10 点"],"h1":"是傍晚比较早的时候。","h2":"在 South Carolina，在标准时间，条件驾照持有人可以从早上 6 点到晚上 6 点独自开车。","p":"对。独自开车到晚上 6 点。"},"vi":{"q":"Ở South Carolina, vào giờ chuẩn (không phải giờ mùa hè), người có bằng lái có điều kiện được lái một mình đến mấy giờ?","o":["Nửa đêm","9 giờ tối","6 giờ chiều","10 giờ tối"],"h1":"Đó là lúc chiều tối sớm.","h2":"Ở South Carolina, vào giờ chuẩn, người có bằng lái có điều kiện được lái một mình từ 6 giờ sáng đến 6 giờ chiều.","p":"Đúng. Lái một mình đến 6 giờ chiều."},"tl":{"q":"Sa South Carolina, hanggang anong oras puwedeng magmaneho nang mag-isa ang may hawak ng kondisyonal na lisensya sa standard time (hindi daylight saving time)?","o":["Hatinggabi","9 p.m.","6 p.m.","10 p.m."],"h1":"Maaga pa ito sa gabi.","h2":"Sa South Carolina, ang may hawak ng kondisyonal na lisensya ay puwedeng magmaneho nang mag-isa mula 6 a.m. hanggang 6 p.m. sa standard time.","p":"Tama. Mag-isa hanggang 6 p.m."},"ar":{"q":"في South Carolina، حتى أي ساعة يمكن لصاحب الرخصة المشروطة أن يقود وحده في التوقيت العادي (وليس التوقيت الصيفي)؟","o":["منتصف الليل","9 مساءً","6 مساءً","10 مساءً"],"h1":"إنها في أول المساء.","h2":"في South Carolina يمكن لصاحب الرخصة المشروطة أن يقود وحده من 6 صباحًا حتى 6 مساءً في التوقيت العادي.","p":"صحيح. وحده حتى 6 مساءً."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-008","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, during daylight saving time, until what time may a conditional license holder drive alone?","o":["8 p.m.","6 p.m.","10 p.m.","Midnight"],"h1":"It is two hours later than in winter.","h2":"During daylight saving time, a South Carolina conditional license holder may drive alone until 8 p.m.","p":"Right. Until 8 p.m. in daylight saving time."},"es":{"q":"En Carolina del Sur, durante el horario de verano, ¿hasta qué hora puede manejar solo quien tiene licencia condicional?","o":["8 p.m.","6 p.m.","10 p.m.","Medianoche"],"h1":"Son dos horas más tarde que en invierno.","h2":"Durante el horario de verano, quien tiene licencia condicional en Carolina del Sur puede manejar solo hasta las 8 p.m.","p":"Correcto. Hasta las 8 p.m. en horario de verano."},"zh":{"q":"在 South Carolina，在夏令时期间，条件驾照持有人可以独自开车到几点？","o":["晚上 8 点","晚上 6 点","晚上 10 点","午夜"],"h1":"它比冬天晚两个小时。","h2":"在夏令时期间，South Carolina 的条件驾照持有人可以独自开车到晚上 8 点。","p":"对。夏令时可以开到晚上 8 点。"},"vi":{"q":"Ở South Carolina, vào giờ mùa hè, người có bằng lái có điều kiện được lái một mình đến mấy giờ?","o":["8 giờ tối","6 giờ chiều","10 giờ tối","Nửa đêm"],"h1":"Muộn hơn mùa đông hai giờ.","h2":"Vào giờ mùa hè, người có bằng lái có điều kiện ở South Carolina được lái một mình đến 8 giờ tối.","p":"Đúng. Đến 8 giờ tối vào giờ mùa hè."},"tl":{"q":"Sa South Carolina, sa panahon ng daylight saving time, hanggang anong oras puwedeng magmaneho nang mag-isa ang may hawak ng kondisyonal na lisensya?","o":["8 p.m.","6 p.m.","10 p.m.","Hatinggabi"],"h1":"Dalawang oras itong mas huli kaysa sa taglamig.","h2":"Sa panahon ng daylight saving time, ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho nang mag-isa hanggang 8 p.m.","p":"Tama. Hanggang 8 p.m. sa daylight saving time."},"ar":{"q":"في South Carolina، في فترة التوقيت الصيفي، حتى أي ساعة يمكن لصاحب الرخصة المشروطة أن يقود وحده؟","o":["8 مساءً","6 مساءً","10 مساءً","منتصف الليل"],"h1":"إنها بعد وقت الشتاء بساعتين.","h2":"في فترة التوقيت الصيفي، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود وحده حتى 8 مساءً.","p":"صحيح. حتى 8 مساءً في التوقيت الصيفي."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-009","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, a conditional license holder wants to drive at 9 p.m. Who must be in the car?","o":["A friend with a permit","A licensed driver 21 or older","Any passenger 18 or older","No one; driving after dark is banned"],"h1":"An experienced adult driver allows evening driving.","h2":"After the evening limit, a South Carolina conditional license holder may drive until midnight with a licensed driver 21 or older in the car.","p":"Right. A licensed driver 21 or older."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional quiere manejar a las 9 p.m. ¿Quién debe ir en el carro?","o":["Un amigo con permiso","Un conductor con licencia de 21 años o más","Cualquier pasajero de 18 años o más","Nadie; está prohibido manejar de noche"],"h1":"Un conductor adulto con experiencia permite manejar por la noche.","h2":"Después del límite de la tarde, quien tiene licencia condicional en Carolina del Sur puede manejar hasta la medianoche con un conductor con licencia de 21 años o más en el carro.","p":"Correcto. Un conductor con licencia de 21 años o más."},"zh":{"q":"在 South Carolina，条件驾照持有人想在晚上 9 点开车。车里必须有谁？","o":["一个有学习驾照的朋友","21 岁或以上的持照司机","任何 18 岁或以上的乘客","没有人；天黑后禁止开车"],"h1":"有经验的成年司机在车上，晚上就可以开车。","h2":"过了晚上的时间限制后，South Carolina 的条件驾照持有人如果车上有 21 岁或以上的持照司机，可以开车到午夜。","p":"对。21 岁或以上的持照司机。"},"vi":{"q":"Ở South Carolina, người có bằng lái có điều kiện muốn lái xe lúc 9 giờ tối. Ai phải ở trong xe?","o":["Một người bạn có giấy phép tập lái","Một người có bằng lái từ 21 tuổi trở lên","Bất kỳ hành khách nào từ 18 tuổi trở lên","Không ai cả; cấm lái xe sau khi trời tối"],"h1":"Có một người lớn lái xe nhiều kinh nghiệm thì được lái buổi tối.","h2":"Sau giới hạn buổi tối, người có bằng lái có điều kiện ở South Carolina được lái đến nửa đêm nếu có một người có bằng lái từ 21 tuổi trở lên trong xe.","p":"Đúng. Một người có bằng lái từ 21 tuổi trở lên."},"tl":{"q":"Sa South Carolina, gustong magmaneho ng may hawak ng kondisyonal na lisensya nang 9 p.m. Sino ang dapat nasa kotse?","o":["Isang kaibigan na may permit","Isang drayber na may lisensya na 21 o mas matanda","Kahit sinong pasahero na 18 o mas matanda","Wala; bawal magmaneho pagkadilim"],"h1":"Kapag may kasamang adultong drayber na may karanasan, puwedeng magmaneho sa gabi.","h2":"Pagkalipas ng limitasyon sa gabi, ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho hanggang hatinggabi kung may kasamang drayber na may lisensya na 21 o mas matanda sa kotse.","p":"Tama. Isang drayber na may lisensya na 21 o mas matanda."},"ar":{"q":"في South Carolina، صاحب رخصة مشروطة يريد أن يقود الساعة 9 مساءً. من يجب أن يكون في السيارة؟","o":["صديق معه تصريح","سائق مرخص عمره 21 سنة أو أكثر","أي راكب عمره 18 سنة أو أكثر","لا أحد؛ القيادة بعد الظلام ممنوعة"],"h1":"وجود سائق بالغ عنده خبرة يسمح بالقيادة في المساء.","h2":"بعد حد المساء، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود حتى منتصف الليل إذا كان معه في السيارة سائق مرخص عمره 21 سنة أو أكثر.","p":"صحيح. سائق مرخص عمره 21 سنة أو أكثر."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-010","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a conditional license holder drives between midnight and 6 a.m. Who must be in the car?","o":["Any licensed adult","A friend over 18","A police officer","A licensed parent or guardian"],"h1":"Late at night, the rule is about family.","h2":"Between midnight and 6 a.m., a South Carolina conditional license holder may drive only with a licensed parent or guardian, or another adult the law allows, in the car.","p":"Right. A licensed parent or guardian."},"es":{"q":"En Carolina del Sur, quien tiene licencia condicional maneja entre la medianoche y las 6 a.m. ¿Quién debe ir en el carro?","o":["Cualquier adulto con licencia","Un amigo mayor de 18","Un policía","Un padre, madre o tutor con licencia"],"h1":"De madrugada, la regla tiene que ver con la familia.","h2":"Entre la medianoche y las 6 a.m., quien tiene licencia condicional en Carolina del Sur solo puede manejar con su padre, madre o tutor con licencia, u otro adulto que la ley permite, en el carro.","p":"Correcto. Un padre o tutor con licencia."},"zh":{"q":"在 South Carolina，条件驾照持有人在午夜到早上 6 点之间开车。车里必须有谁？","o":["任何持照成年人","一个 18 岁以上的朋友","一名警察","持有驾照的父母或监护人"],"h1":"深夜的规定和家人有关。","h2":"在午夜到早上 6 点之间，South Carolina 的条件驾照持有人只能在车上有持照的父母或监护人，或法律允许的其他成年人时开车。","p":"对。持有驾照的父母或监护人。"},"vi":{"q":"Ở South Carolina, người có bằng lái có điều kiện lái xe từ nửa đêm đến 6 giờ sáng. Ai phải ở trong xe?","o":["Bất kỳ người lớn nào có bằng lái","Một người bạn trên 18 tuổi","Một cảnh sát","Cha mẹ hoặc người giám hộ có bằng lái"],"h1":"Vào khuya, luật liên quan đến gia đình.","h2":"Từ nửa đêm đến 6 giờ sáng, người có bằng lái có điều kiện ở South Carolina chỉ được lái khi có cha mẹ hoặc người giám hộ có bằng lái, hoặc một người lớn khác mà luật cho phép, trong xe.","p":"Đúng. Cha mẹ hoặc người giám hộ có bằng lái."},"tl":{"q":"Sa South Carolina, nagmamaneho ang may hawak ng kondisyonal na lisensya mula hatinggabi hanggang 6 a.m. Sino ang dapat nasa kotse?","o":["Kahit sinong adulto na may lisensya","Isang kaibigan na lampas 18","Isang pulis","Magulang o tagapag-alaga na may lisensya"],"h1":"Sa hatinggabi, tungkol sa pamilya ang patakaran.","h2":"Mula hatinggabi hanggang 6 a.m., ang may hawak ng kondisyonal na lisensya sa South Carolina ay puwedeng magmaneho lamang kung may kasamang magulang o tagapag-alaga na may lisensya, o ibang adulto na pinapayagan ng batas, sa kotse.","p":"Tama. Magulang o tagapag-alaga na may lisensya."},"ar":{"q":"في South Carolina، صاحب رخصة مشروطة يقود بين منتصف الليل والساعة 6 صباحًا. من يجب أن يكون في السيارة؟","o":["أي شخص بالغ مرخص","صديق عمره أكثر من 18 سنة","شرطي","أحد الوالدين أو الوصي المرخص"],"h1":"في وقت متأخر من الليل، القاعدة تتعلق بالعائلة.","h2":"بين منتصف الليل والساعة 6 صباحًا، يمكن لصاحب الرخصة المشروطة في South Carolina أن يقود فقط إذا كان معه في السيارة أحد الوالدين أو الوصي المرخص، أو شخص بالغ آخر يسمح به القانون.","p":"صحيح. أحد الوالدين أو الوصي المرخص."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-011","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how many passengers under 21 may a conditional license holder carry without an adult, not counting family or students going to school?","o":["None","One","Two","Four"],"h1":"It is a small number, but more than one.","h2":"A South Carolina conditional license holder may carry no more than two passengers under 21, unless a licensed adult 21 or older rides along or the riders are family or students going to or from school.","p":"Right. No more than two."},"es":{"q":"En Carolina del Sur, ¿cuántos pasajeros menores de 21 años puede llevar sin un adulto quien tiene licencia condicional, sin contar familiares ni estudiantes que van a la escuela?","o":["Ninguno","Uno","Dos","Cuatro"],"h1":"Es un número pequeño, pero más de uno.","h2":"Quien tiene licencia condicional en Carolina del Sur puede llevar no más de dos pasajeros menores de 21 años, salvo que lo acompañe un adulto con licencia de 21 años o más, o que sean familiares o estudiantes que van o vuelven de la escuela.","p":"Correcto. No más de dos."},"zh":{"q":"在 South Carolina，没有成年人在车上时，条件驾照持有人最多可以载几名 21 岁以下的乘客（不算家人或上学的学生）？","o":["不能载","一名","两名","四名"],"h1":"数量很少，但不止一名。","h2":"在 South Carolina，条件驾照持有人最多只能载两名 21 岁以下的乘客，除非车上有 21 岁或以上的持照成年人，或乘客是家人或上下学的学生。","p":"对。最多两名。"},"vi":{"q":"Ở South Carolina, khi không có người lớn, người có bằng lái có điều kiện được chở bao nhiêu hành khách dưới 21 tuổi, không tính người trong gia đình hoặc học sinh đi học?","o":["Không ai","Một","Hai","Bốn"],"h1":"Đó là số nhỏ, nhưng nhiều hơn một.","h2":"Ở South Carolina, người có bằng lái có điều kiện được chở không quá hai hành khách dưới 21 tuổi, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên đi cùng, hoặc hành khách là người trong gia đình hoặc học sinh đi học hay đi học về.","p":"Đúng. Không quá hai."},"tl":{"q":"Sa South Carolina, ilang pasahero na wala pang 21 ang puwedeng isakay ng may hawak ng kondisyonal na lisensya nang walang adulto, hindi kasama ang pamilya o mga estudyanteng papasok sa paaralan?","o":["Wala","Isa","Dalawa","Apat"],"h1":"Maliit na bilang ito, pero higit sa isa.","h2":"Sa South Carolina, ang may hawak ng kondisyonal na lisensya ay puwedeng magsakay ng hindi hihigit sa dalawang pasahero na wala pang 21, maliban kung may kasamang adulto na may lisensya na 21 o mas matanda, o ang mga pasahero ay pamilya o mga estudyanteng papunta o pauwi mula sa paaralan.","p":"Tama. Hindi hihigit sa dalawa."},"ar":{"q":"في South Carolina، كم راكبًا عمره أقل من 21 سنة يمكن لصاحب الرخصة المشروطة أن يحمل بدون شخص بالغ، من غير أفراد العائلة أو الطلاب الذاهبين إلى المدرسة؟","o":["ولا أحد","واحد","اثنان","أربعة"],"h1":"إنه عدد صغير، لكنه أكثر من واحد.","h2":"في South Carolina لا يمكن لصاحب الرخصة المشروطة أن يحمل أكثر من راكبين عمرهما أقل من 21 سنة، إلا إذا كان معه شخص بالغ مرخص عمره 21 سنة أو أكثر، أو كان الركاب من العائلة أو طلابًا ذاهبين إلى المدرسة أو عائدين منها.","p":"صحيح. ليس أكثر من اثنين."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-012","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, at what age can a teen who meets the conditional license rules get a special restricted license instead?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"The only difference from the conditional license is age.","h2":"A South Carolina teen who is 16 but not yet 17 and meets the conditional license rules can get a special restricted license.","p":"Right. The special restricted license is for age 16."},"es":{"q":"En Carolina del Sur, ¿a qué edad puede un adolescente que cumple las reglas de la licencia condicional obtener la licencia restringida especial?","o":["16 años","15 años","17 años","18 años"],"h1":"La única diferencia con la licencia condicional es la edad.","h2":"Un adolescente en Carolina del Sur que tiene 16 años pero todavía no 17 y cumple las reglas de la licencia condicional puede obtener la licencia restringida especial.","p":"Correcto. La licencia restringida especial es para los 16 años."},"zh":{"q":"在 South Carolina，符合条件驾照规定的青少年几岁可以改拿特别限制驾照（special restricted license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它和条件驾照唯一的不同是年龄。","h2":"在 South Carolina，16 岁但还不到 17 岁、并符合条件驾照规定的青少年，可以拿特别限制驾照。","p":"对。特别限制驾照是给 16 岁的人。"},"vi":{"q":"Ở South Carolina, thiếu niên đáp ứng các quy định của bằng lái có điều kiện được lấy bằng lái hạn chế đặc biệt (special restricted license) thay vào đó ở tuổi nào?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Điểm khác duy nhất so với bằng lái có điều kiện là tuổi.","h2":"Ở South Carolina, thiếu niên 16 tuổi nhưng chưa 17 tuổi và đáp ứng các quy định của bằng lái có điều kiện có thể lấy bằng lái hạn chế đặc biệt.","p":"Đúng. Bằng lái hạn chế đặc biệt dành cho tuổi 16."},"tl":{"q":"Sa South Carolina, sa anong edad puwedeng kumuha ng espesyal na limitadong lisensya (special restricted license) ang tinedyer na sumusunod sa mga patakaran ng kondisyonal na lisensya?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Ang tanging pagkakaiba sa kondisyonal na lisensya ay ang edad.","h2":"Sa South Carolina, ang tinedyer na 16 pero hindi pa 17 at sumusunod sa mga patakaran ng kondisyonal na lisensya ay puwedeng kumuha ng espesyal na limitadong lisensya.","p":"Tama. Ang espesyal na limitadong lisensya ay para sa edad na 16."},"ar":{"q":"في South Carolina، في أي عمر يمكن للمراهق الذي يستوفي شروط الرخصة المشروطة أن يحصل بدلًا منها على الرخصة المقيدة الخاصة (special restricted license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"الفرق الوحيد عن الرخصة المشروطة هو العمر.","h2":"في South Carolina، المراهق الذي عمره 16 سنة ولم يبلغ 17 بعد ويستوفي شروط الرخصة المشروطة يمكنه الحصول على الرخصة المقيدة الخاصة.","p":"صحيح. الرخصة المقيدة الخاصة لعمر 16 سنة."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-013","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what blood alcohol level breaks the zero tolerance law for a driver under 21?","o":["0.08","0.02","0.05","0.10"],"h1":"It is much lower than the adult limit.","h2":"In South Carolina a driver under 21 with a blood alcohol level of 0.02 breaks the zero tolerance law.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Carolina del Sur, ¿qué nivel de alcohol en la sangre viola la ley de tolerancia cero para un conductor menor de 21 años?","o":["0.08","0.02","0.05","0.10"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Carolina del Sur un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 viola la ley de tolerancia cero.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 South Carolina，21 岁以下的司机血液酒精浓度达到多少就违反零容忍法（zero tolerance law）？","o":["0.08","0.02","0.05","0.10"],"h1":"它比成年人的上限低很多。","h2":"在 South Carolina，21 岁以下的司机血液酒精浓度达到 0.02 就违反零容忍法。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở South Carolina, nồng độ cồn trong máu bao nhiêu thì người lái dưới 21 tuổi vi phạm luật không khoan nhượng (zero tolerance law)?","o":["0.08","0.02","0.05","0.10"],"h1":"Thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở South Carolina, người lái dưới 21 tuổi có nồng độ cồn trong máu 0.02 là vi phạm luật không khoan nhượng.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa South Carolina, anong antas ng alak sa dugo ang lumalabag sa batas na zero tolerance (zero tolerance law) para sa drayber na wala pang 21?","o":["0.08","0.02","0.05","0.10"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon para sa adulto.","h2":"Sa South Carolina, ang drayber na wala pang 21 na may antas ng alak sa dugo na 0.02 ay lumalabag sa batas na zero tolerance.","p":"Tama. Kapag wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في South Carolina، ما نسبة الكحول في الدم التي تخالف قانون عدم التسامح (zero tolerance law) لسائق عمره أقل من 21 سنة؟","o":["0.08","0.02","0.05","0.10"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 يخالف قانون عدم التسامح.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-014","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, what happens on a first zero tolerance offense for a driver under 21?","o":["Only a warning","A one-week suspension","A five-year suspension","A suspension of at least three months"],"h1":"It is a few months.","h2":"In South Carolina, a driver under 21 with a blood alcohol level of 0.02 or more loses the right to drive right away, for at least three months.","p":"Right. At least three months without driving."},"es":{"q":"En Carolina del Sur, ¿qué pasa en la primera infracción de tolerancia cero de un conductor menor de 21 años?","o":["Solo una advertencia","Una suspensión de una semana","Una suspensión de cinco años","Una suspensión de por lo menos tres meses"],"h1":"Son unos pocos meses.","h2":"En Carolina del Sur, un conductor menor de 21 años con un nivel de alcohol en la sangre de 0.02 o más pierde el derecho a manejar de inmediato, por lo menos por tres meses.","p":"Correcto. Por lo menos tres meses sin manejar."},"zh":{"q":"在 South Carolina，21 岁以下的司机第一次违反零容忍法，会怎样？","o":["只是警告","吊销驾照一周","吊销驾照五年","吊销驾照至少三个月"],"h1":"是几个月。","h2":"在 South Carolina，21 岁以下的司机血液酒精浓度达到 0.02 或以上，会马上失去开车的权利，至少三个月。","p":"对。至少三个月不能开车。"},"vi":{"q":"Ở South Carolina, chuyện gì xảy ra khi người lái dưới 21 tuổi vi phạm luật không khoan nhượng lần đầu?","o":["Chỉ bị cảnh cáo","Bị treo bằng một tuần","Bị treo bằng năm năm","Bị treo bằng ít nhất ba tháng"],"h1":"Đó là vài tháng.","h2":"Ở South Carolina, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên mất quyền lái xe ngay lập tức, ít nhất ba tháng.","p":"Đúng. Ít nhất ba tháng không được lái."},"tl":{"q":"Sa South Carolina, ano ang mangyayari sa unang paglabag sa zero tolerance ng drayber na wala pang 21?","o":["Babala lamang","Isang linggong suspensyon","Limang taong suspensyon","Suspensyon na hindi bababa sa tatlong buwan"],"h1":"Ilang buwan ito.","h2":"Sa South Carolina, ang drayber na wala pang 21 na may antas ng alak sa dugo na 0.02 o higit pa ay agad na nawawalan ng karapatang magmaneho, nang hindi bababa sa tatlong buwan.","p":"Tama. Hindi bababa sa tatlong buwan na walang pagmamaneho."},"ar":{"q":"في South Carolina، ماذا يحدث في أول مخالفة لقانون عدم التسامح لسائق عمره أقل من 21 سنة؟","o":["تحذير فقط","إيقاف الرخصة لمدة أسبوع","إيقاف الرخصة لمدة خمس سنوات","إيقاف الرخصة لمدة ثلاثة أشهر على الأقل"],"h1":"إنها بضعة أشهر.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر يفقد حق القيادة فورًا، لمدة ثلاثة أشهر على الأقل.","p":"صحيح. ثلاثة أشهر على الأقل بدون قيادة."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-015","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, can police stop a driver only for holding a phone while driving?","o":["No, only with another violation","Only on interstates","Yes, it is a primary offense","Only in school zones"],"h1":"The hands-free law is enforced on its own.","h2":"South Carolina's hands-free law is a primary offense, so police can stop a driver they clearly see holding a phone, with no other reason.","p":"Right. Holding a phone is enough for a stop."},"es":{"q":"En Carolina del Sur, ¿puede la policía detener a un conductor solo por sostener el teléfono mientras maneja?","o":["No, solo con otra infracción","Solo en interestatales","Sí, es una infracción primaria","Solo en zonas escolares"],"h1":"La ley de manos libres se aplica por sí sola.","h2":"La ley de manos libres de Carolina del Sur es una infracción primaria, así que la policía puede detener a un conductor que ve claramente con el teléfono en la mano, sin otra razón.","p":"Correcto. Sostener el teléfono basta para que lo detengan."},"zh":{"q":"在 South Carolina，警察可以只因为司机开车时手拿手机就拦车吗？","o":["不可以，必须还有其他违规","只在州际公路上","可以，这是主要违规（primary offense）","只在学校区域"],"h1":"免提法本身就可以执法。","h2":"South Carolina 的免提法是主要违规，所以警察清楚看到司机手拿手机时，不需要其他理由就可以拦车。","p":"对。手拿手机就足以被拦车。"},"vi":{"q":"Ở South Carolina, cảnh sát có thể chặn xe chỉ vì người lái cầm điện thoại khi lái không?","o":["Không, chỉ khi có vi phạm khác","Chỉ trên xa lộ liên bang","Có, đó là vi phạm chính (primary offense)","Chỉ trong khu vực trường học"],"h1":"Luật rảnh tay được thi hành riêng.","h2":"Luật rảnh tay của South Carolina là vi phạm chính, nên cảnh sát có thể chặn người lái mà họ thấy rõ đang cầm điện thoại, không cần lý do nào khác.","p":"Đúng. Cầm điện thoại là đủ để bị chặn xe."},"tl":{"q":"Sa South Carolina, puwede bang patigilin ng pulis ang drayber dahil lamang may hawak siyang telepono habang nagmamaneho?","o":["Hindi, kailangan may iba pang paglabag","Sa interstate lamang","Oo, ito ay pangunahing paglabag (primary offense)","Sa school zone lamang"],"h1":"Ang batas na hands-free ay ipinapatupad nang mag-isa.","h2":"Ang batas na hands-free ng South Carolina ay pangunahing paglabag, kaya puwedeng patigilin ng pulis ang drayber na malinaw nilang nakikitang may hawak na telepono, kahit walang ibang dahilan.","p":"Tama. Sapat na ang paghawak ng telepono para patigilin ka."},"ar":{"q":"في South Carolina، هل يمكن للشرطة أن توقف السائق فقط لأنه يمسك الهاتف أثناء القيادة؟","o":["لا، فقط مع مخالفة أخرى","فقط على الطرق السريعة بين الولايات","نعم، إنها مخالفة أساسية (primary offense)","فقط في مناطق المدارس"],"h1":"قانون عدم استخدام اليدين يُطبَّق وحده.","h2":"قانون عدم استخدام اليدين في South Carolina مخالفة أساسية، لذلك يمكن للشرطة أن توقف السائق الذي تراه بوضوح يمسك الهاتف، بدون أي سبب آخر.","p":"صحيح. إمساك الهاتف يكفي لإيقافك."},"ref":{"doc":"SC","page":null}},{"id":"sc-016","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, how may you make a phone call while driving?","o":["Hands-free, such as a car speaker or earpiece","Holding the phone to your ear","Holding the phone on speaker","Holding the phone, if you drive slowly"],"h1":"Your hands stay on the wheel.","h2":"South Carolina allows phone calls while driving only hands-free, such as through the car's speaker or an earpiece.","p":"Right. Hands-free calls only."},"es":{"q":"En Carolina del Sur, ¿cómo puede hacer una llamada mientras maneja?","o":["Con manos libres, como la bocina del carro o un audífono","Sosteniendo el teléfono en la oreja","Sosteniendo el teléfono en altavoz","Sosteniendo el teléfono, si maneja despacio"],"h1":"Sus manos se quedan en el volante.","h2":"Carolina del Sur permite llamadas mientras maneja solo con manos libres, como la bocina del carro o un audífono.","p":"Correcto. Solo llamadas con manos libres."},"zh":{"q":"在 South Carolina，开车时怎样才可以打电话？","o":["用免提，例如车上的扬声器或耳机","把手机拿到耳边","手拿手机开扬声器","手拿手机，只要开得慢"],"h1":"你的手要放在方向盘上。","h2":"在 South Carolina，开车时只能用免提打电话，例如通过车上的扬声器或耳机。","p":"对。只能用免提打电话。"},"vi":{"q":"Ở South Carolina, bạn được gọi điện thoại khi lái xe bằng cách nào?","o":["Rảnh tay, ví dụ loa trong xe hoặc tai nghe","Cầm điện thoại áp vào tai","Cầm điện thoại bật loa ngoài","Cầm điện thoại, nếu lái chậm"],"h1":"Tay bạn luôn ở trên vô lăng.","h2":"Ở South Carolina, khi lái xe chỉ được gọi điện thoại bằng cách rảnh tay, ví dụ qua loa trong xe hoặc tai nghe.","p":"Đúng. Chỉ gọi điện rảnh tay."},"tl":{"q":"Sa South Carolina, paano ka puwedeng tumawag sa telepono habang nagmamaneho?","o":["Hands-free, gaya ng speaker ng kotse o earpiece","Hawak ang telepono sa tainga","Hawak ang telepono na naka-speaker","Hawak ang telepono, kung mabagal ang takbo"],"h1":"Nananatili ang mga kamay mo sa manibela.","h2":"Sa South Carolina, puwede lamang tumawag habang nagmamaneho kung hands-free, gaya ng sa speaker ng kotse o sa earpiece.","p":"Tama. Hands-free na tawag lamang."},"ar":{"q":"في South Carolina، كيف يمكنك إجراء مكالمة هاتفية أثناء القيادة؟","o":["بدون استخدام اليدين، مثل سماعة السيارة أو سماعة الأذن","بإمساك الهاتف على أذنك","بإمساك الهاتف مع مكبر الصوت","بإمساك الهاتف، إذا كنت تقود ببطء"],"h1":"يداك تبقيان على المقود.","h2":"في South Carolina يُسمح بالمكالمات أثناء القيادة فقط بدون استخدام اليدين، مثل سماعة السيارة أو سماعة الأذن.","p":"صحيح. مكالمات بدون استخدام اليدين فقط."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-017","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, you approach a stopped emergency vehicle with flashing lights. What should you do if it is safe?","o":["Keep your speed and lane","Slow down and change to a lane not next to it","Stop in your lane","Use the shoulder to pass"],"h1":"Give it a whole lane of space.","h2":"In South Carolina you must slow down and, if possible, change to a lane that is not next to a stopped emergency vehicle with flashing lights.","p":"Right. Slow down and move over."},"es":{"q":"En Carolina del Sur, se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué debe hacer si es seguro?","o":["Mantener su velocidad y su carril","Bajar la velocidad y cambiarse a un carril que no esté junto a él","Detenerse en su carril","Usar el acotamiento para pasar"],"h1":"Déjele un carril completo de espacio.","h2":"En Carolina del Sur usted debe bajar la velocidad y, si es posible, cambiarse a un carril que no esté junto al vehículo de emergencia detenido con luces intermitentes.","p":"Correcto. Bajar la velocidad y cambiarse de carril."},"zh":{"q":"在 South Carolina，你接近一辆停着并闪灯的紧急车辆。如果安全，你应该怎么做？","o":["保持车速和车道","减速，并换到不紧挨着它的车道","在你的车道上停车","从路肩超过去"],"h1":"给它让出一整条车道的空间。","h2":"在 South Carolina，你必须减速，并且如果可能，换到不紧挨着停着并闪灯的紧急车辆的车道。","p":"对。减速并让出车道。"},"vi":{"q":"Ở South Carolina, bạn đến gần một xe cấp cứu đang dừng và nháy đèn. Nếu an toàn, bạn nên làm gì?","o":["Giữ tốc độ và làn đường","Giảm tốc độ và đổi sang làn không sát bên nó","Dừng lại trong làn của bạn","Đi lên lề đường để vượt"],"h1":"Chừa cho nó trống cả một làn đường.","h2":"Ở South Carolina, bạn phải giảm tốc độ và, nếu có thể, đổi sang làn không sát bên xe cấp cứu đang dừng và nháy đèn.","p":"Đúng. Giảm tốc độ và tránh sang làn khác."},"tl":{"q":"Sa South Carolina, papalapit ka sa nakahintong sasakyang pang-emergency na may kumikislap na ilaw. Ano ang dapat mong gawin kung ligtas?","o":["Panatilihin ang bilis at linya mo","Bumagal at lumipat sa linyang hindi katabi nito","Huminto sa linya mo","Dumaan sa gilid ng kalsada para lumampas"],"h1":"Bigyan ito ng isang buong linya na espasyo.","h2":"Sa South Carolina, dapat kang bumagal at, kung puwede, lumipat sa linyang hindi katabi ng nakahintong sasakyang pang-emergency na may kumikislap na ilaw.","p":"Tama. Bumagal at lumipat ng linya."},"ar":{"q":"في South Carolina، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض. ماذا يجب أن تفعل إذا كان ذلك آمنًا؟","o":["حافظ على سرعتك ومسارك","خفف السرعة وانتقل إلى مسار ليس بجانبها","توقف في مسارك","استخدم كتف الطريق لتتجاوزها"],"h1":"اترك لها مسارًا كاملًا فارغًا.","h2":"في South Carolina يجب أن تخفف السرعة، وإذا أمكن، تنتقل إلى مسار ليس بجانب مركبة الطوارئ المتوقفة التي تومض أضواؤها.","p":"صحيح. خفف السرعة وابتعد إلى مسار آخر."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-018","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, you cannot safely change lanes away from a stopped emergency vehicle. What must you do?","o":["Speed up to pass quickly","Stop completely","Honk as you pass","Slow down and keep a safe speed"],"h1":"If moving over is not possible, there is still one thing to do.","h2":"In South Carolina, when you cannot safely change lanes, you must slow down and keep a safe speed as you pass a stopped emergency vehicle.","p":"Right. Slow down when you cannot move over."},"es":{"q":"En Carolina del Sur, no puede cambiarse de carril con seguridad para alejarse de un vehículo de emergencia detenido. ¿Qué debe hacer?","o":["Acelerar para pasar rápido","Detenerse por completo","Tocar la bocina al pasar","Bajar la velocidad y mantener una velocidad segura"],"h1":"Si no puede cambiarse, todavía hay algo que hacer.","h2":"En Carolina del Sur, cuando no puede cambiarse de carril con seguridad, debe bajar la velocidad y mantener una velocidad segura al pasar un vehículo de emergencia detenido.","p":"Correcto. Bajar la velocidad cuando no puede cambiarse."},"zh":{"q":"在 South Carolina，你不能安全地换道离开停着的紧急车辆。你必须怎么做？","o":["加速快点超过","完全停车","经过时按喇叭","减速，保持安全车速"],"h1":"如果不能换道，还有一件事要做。","h2":"在 South Carolina，当你不能安全换道时，经过停着的紧急车辆时必须减速，并保持安全车速。","p":"对。不能换道时要减速。"},"vi":{"q":"Ở South Carolina, bạn không thể đổi làn an toàn để tránh xa một xe cấp cứu đang dừng. Bạn phải làm gì?","o":["Tăng tốc để vượt nhanh","Dừng hẳn lại","Bấm còi khi đi qua","Giảm tốc độ và giữ tốc độ an toàn"],"h1":"Nếu không tránh sang làn khác được, vẫn còn một việc phải làm.","h2":"Ở South Carolina, khi không thể đổi làn an toàn, bạn phải giảm tốc độ và giữ tốc độ an toàn khi đi qua xe cấp cứu đang dừng.","p":"Đúng. Giảm tốc độ khi không thể tránh sang làn khác."},"tl":{"q":"Sa South Carolina, hindi ka ligtas na makalipat ng linya palayo sa nakahintong sasakyang pang-emergency. Ano ang dapat mong gawin?","o":["Bumilis para mabilis na lumampas","Huminto nang tuluyan","Bumusina habang dumadaan","Bumagal at panatilihin ang ligtas na bilis"],"h1":"Kung hindi puwedeng lumipat ng linya, may isa pang dapat gawin.","h2":"Sa South Carolina, kapag hindi ka ligtas na makalipat ng linya, dapat kang bumagal at panatilihin ang ligtas na bilis habang dumadaan sa nakahintong sasakyang pang-emergency.","p":"Tama. Bumagal kapag hindi ka makalipat ng linya."},"ar":{"q":"في South Carolina، لا يمكنك أن تغير المسار بأمان بعيدًا عن مركبة طوارئ متوقفة. ماذا يجب أن تفعل؟","o":["زد السرعة لتتجاوز بسرعة","توقف تمامًا","استخدم البوق وأنت تمر","خفف السرعة وحافظ على سرعة آمنة"],"h1":"إذا لم يمكنك الابتعاد إلى مسار آخر، يبقى شيء واحد يجب فعله.","h2":"في South Carolina، عندما لا يمكنك تغيير المسار بأمان، يجب أن تخفف السرعة وتحافظ على سرعة آمنة وأنت تمر بمركبة الطوارئ المتوقفة.","p":"صحيح. خفف السرعة عندما لا يمكنك الابتعاد."},"ref":{"doc":"SC","page":"10-15"}},{"id":"sc-019","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, on a highway with at least two lanes in each direction, you meet a stopped school bus coming the other way. What must you do?","o":["Stop until the bus moves","Stop only if there is no median","You do not have to stop, but go with caution","Stop and wait for the driver's signal"],"h1":"The number of lanes matters more than the median.","h2":"On a South Carolina highway with at least two lanes in each direction, traffic going the opposite way does not have to stop for a school bus, whatever the median, but should go with caution.","p":"Right. Oncoming traffic may pass with caution."},"es":{"q":"En Carolina del Sur, en una carretera con por lo menos dos carriles en cada sentido, usted se encuentra con un autobús escolar detenido que viene en sentido contrario. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Detenerse solo si no hay camellón","No tiene que detenerse, pero avance con cuidado","Detenerse y esperar la señal del chofer"],"h1":"El número de carriles importa más que el camellón.","h2":"En una carretera de Carolina del Sur con por lo menos dos carriles en cada sentido, el tráfico en sentido contrario no tiene que detenerse por un autobús escolar, haya o no camellón, pero debe avanzar con cuidado.","p":"Correcto. El tráfico contrario puede pasar con cuidado."},"zh":{"q":"在 South Carolina，在每个方向至少有两条车道的公路上，你遇到对面方向一辆停着的校车。你必须怎么做？","o":["停车，直到校车开走","只有没有中间隔离带时才停车","你不用停车，但要小心行驶","停车，等司机的手势"],"h1":"车道的数量比中间隔离带更重要。","h2":"在 South Carolina，每个方向至少有两条车道的公路上，对面方向的车辆不论有没有中间隔离带，都不用为校车停车，但应该小心行驶。","p":"对。对面来车可以小心通过。"},"vi":{"q":"Ở South Carolina, trên xa lộ có ít nhất hai làn mỗi chiều, bạn gặp một xe buýt trường học đang dừng ở chiều ngược lại. Bạn phải làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Chỉ dừng nếu không có dải phân cách","Bạn không phải dừng, nhưng hãy đi cẩn thận","Dừng lại và chờ tín hiệu của tài xế"],"h1":"Số làn đường quan trọng hơn dải phân cách.","h2":"Trên xa lộ ở South Carolina có ít nhất hai làn mỗi chiều, xe đi chiều ngược lại không phải dừng cho xe buýt trường học, dù có dải phân cách hay không, nhưng nên đi cẩn thận.","p":"Đúng. Xe đi ngược chiều có thể đi qua cẩn thận."},"tl":{"q":"Sa South Carolina, sa highway na may hindi bababa sa dalawang linya sa bawat direksyon, nakasalubong mo ang nakahintong school bus mula sa kabilang direksyon. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Huminto lamang kung walang median","Hindi mo kailangang huminto, pero mag-ingat sa pagdaan","Huminto at hintayin ang senyas ng drayber"],"h1":"Mas mahalaga ang bilang ng linya kaysa sa median.","h2":"Sa highway sa South Carolina na may hindi bababa sa dalawang linya sa bawat direksyon, ang trapiko sa kabilang direksyon ay hindi kailangang huminto para sa school bus, may median man o wala, pero dapat mag-ingat sa pagdaan.","p":"Tama. Ang kasalubong na trapiko ay puwedeng dumaan nang may pag-iingat."},"ar":{"q":"في South Carolina، على طريق سريع فيه مساران على الأقل في كل اتجاه، تقابل حافلة مدرسية متوقفة قادمة من الاتجاه المعاكس. ماذا يجب أن تفعل؟","o":["توقف حتى تتحرك الحافلة","توقف فقط إذا لم يكن هناك فاصل في الوسط","ليس عليك أن تتوقف، لكن تقدم بحذر","توقف وانتظر إشارة السائق"],"h1":"عدد المسارات أهم من الفاصل في الوسط.","h2":"على طريق سريع في South Carolina فيه مساران على الأقل في كل اتجاه، السيارات في الاتجاه المعاكس ليس عليها أن تتوقف للحافلة المدرسية، سواء كان هناك فاصل في الوسط أم لا، لكن يجب أن تتقدم بحذر.","p":"صحيح. السيارات القادمة من الاتجاه المعاكس يمكنها أن تمر بحذر."},"ref":{"doc":"SC","page":"7-10"}},{"id":"sc-020","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, on a four-lane highway, you are behind a school bus that stops with its red lights flashing. What must you do?","o":["Pass it carefully on the left","Stop","Slow to 15 mph and pass","Stop only if a child is in the road"],"h1":"Traffic going the same way as the bus never passes it.","h2":"On a South Carolina four-lane highway, traffic going the same direction as a stopped school bus must stop.","p":"Right. You stop behind the bus."},"es":{"q":"En Carolina del Sur, en una carretera de cuatro carriles, usted va detrás de un autobús escolar que se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Rebasarlo con cuidado por la izquierda","Detenerse","Bajar a 15 mph y pasar","Detenerse solo si hay un niño en el camino"],"h1":"El tráfico que va en el mismo sentido que el autobús nunca lo rebasa.","h2":"En una carretera de cuatro carriles de Carolina del Sur, el tráfico que va en el mismo sentido que un autobús escolar detenido debe detenerse.","p":"Correcto. Usted se detiene detrás del autobús."},"zh":{"q":"在 South Carolina，在四车道公路上，你跟在一辆校车后面，校车停下并闪着红灯。你必须怎么做？","o":["从左边小心超过","停车","减速到 15 mph 再超过","只有孩子在路上时才停车"],"h1":"和校车同方向的车辆永远不能超过它。","h2":"在 South Carolina 的四车道公路上，和停着的校车同方向的车辆必须停车。","p":"对。你要在校车后面停车。"},"vi":{"q":"Ở South Carolina, trên xa lộ bốn làn, bạn đi sau một xe buýt trường học dừng lại và nháy đèn đỏ. Bạn phải làm gì?","o":["Vượt cẩn thận bên trái","Dừng lại","Giảm còn 15 mph và vượt","Chỉ dừng nếu có trẻ em trên đường"],"h1":"Xe đi cùng chiều với xe buýt không bao giờ được vượt nó.","h2":"Trên xa lộ bốn làn ở South Carolina, xe đi cùng chiều với xe buýt trường học đang dừng phải dừng lại.","p":"Đúng. Bạn dừng lại sau xe buýt."},"tl":{"q":"Sa South Carolina, sa highway na may apat na linya, nasa likod ka ng school bus na huminto na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Lampasan ito nang maingat sa kaliwa","Huminto","Bumagal sa 15 mph at lumampas","Huminto lamang kung may bata sa kalsada"],"h1":"Ang trapiko na kapareho ng direksyon ng bus ay hindi kailanman lumalampas dito.","h2":"Sa highway sa South Carolina na may apat na linya, ang trapiko na kapareho ng direksyon ng nakahintong school bus ay dapat huminto.","p":"Tama. Huminto ka sa likod ng bus."},"ar":{"q":"في South Carolina، على طريق سريع من أربعة مسارات، أنت خلف حافلة مدرسية توقفت وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["تجاوزها بحذر من اليسار","توقف","خفف السرعة إلى 15 mph وتجاوزها","توقف فقط إذا كان هناك طفل في الطريق"],"h1":"السيارات التي تسير في نفس اتجاه الحافلة لا تتجاوزها أبدًا.","h2":"على طريق سريع من أربعة مسارات في South Carolina، يجب أن تتوقف السيارات التي تسير في نفس اتجاه الحافلة المدرسية المتوقفة.","p":"صحيح. تتوقف خلف الحافلة."},"ref":{"doc":"SC","page":"7-9"}},{"id":"sc-021","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, what is the highest speed limit on interstate highways?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"It is lower than in some western states.","h2":"The highest speed limit on South Carolina interstate highways is 70 mph, where signs show it.","p":"Right. 70 mph on interstates."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Es más bajo que en algunos estados del oeste.","h2":"El límite de velocidad más alto en las autopistas interestatales de Carolina del Sur es de 70 millas por hora, donde las señales lo indican.","p":"Correcto. 70 mph en las interestatales."},"zh":{"q":"在 South Carolina，州际公路的最高限速是多少？","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"它比一些西部州低。","h2":"在 South Carolina，州际公路的最高限速是 70 mph，以标志显示的为准。","p":"对。州际公路 70 mph。"},"vi":{"q":"Ở South Carolina, tốc độ tối đa cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Thấp hơn so với một số tiểu bang miền tây.","h2":"Tốc độ tối đa cao nhất trên xa lộ liên bang ở South Carolina là 70 mph, ở nơi có biển báo ghi như vậy.","p":"Đúng. 70 mph trên xa lộ liên bang."},"tl":{"q":"Sa South Carolina, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"Mas mababa ito kaysa sa ilang estado sa kanluran.","h2":"Ang pinakamataas na speed limit sa mga interstate highway sa South Carolina ay 70 mph, kung saan ito ipinapakita ng mga karatula.","p":"Tama. 70 mph sa mga interstate."},"ar":{"q":"في South Carolina، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["55 mph","60 mph","75 mph","70 mph"],"h1":"إنه أقل مما في بعض الولايات الغربية.","h2":"أعلى حد للسرعة على الطرق السريعة بين الولايات في South Carolina هو 70 mph، حيث تُظهره اللافتات.","p":"صحيح. 70 mph على الطرق السريعة بين الولايات."},"ref":{"doc":"SC","page":null}},{"id":"sc-022","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how many points on a driver's record lead to a license suspension for a driver 17 or older?","o":["4 points","6 points","12 points","20 points"],"h1":"At 6 points you only get a warning letter.","h2":"In South Carolina, a driver 17 or older gets a warning letter at 6 points, and the license is suspended when the total reaches 12 points or more.","p":"Right. 12 points means a suspension."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos en el historial llevan a la suspensión de la licencia de un conductor de 17 años o más?","o":["4 puntos","6 puntos","12 puntos","20 puntos"],"h1":"Con 6 puntos solo recibe una carta de advertencia.","h2":"En Carolina del Sur, un conductor de 17 años o más recibe una carta de advertencia con 6 puntos, y la licencia se suspende cuando el total llega a 12 puntos o más.","p":"Correcto. Con 12 puntos se suspende la licencia."},"zh":{"q":"在 South Carolina，17 岁或以上的司机驾驶记录上有多少分会被吊销驾照？","o":["4 分","6 分","12 分","20 分"],"h1":"到 6 分时，你只会收到一封警告信。","h2":"在 South Carolina，17 岁或以上的司机到 6 分时会收到警告信，总分达到 12 分或以上时驾照会被吊销。","p":"对。12 分就会被吊销驾照。"},"vi":{"q":"Ở South Carolina, người lái từ 17 tuổi trở lên bị bao nhiêu điểm trong hồ sơ lái xe thì bị treo bằng lái?","o":["4 điểm","6 điểm","12 điểm","20 điểm"],"h1":"Ở 6 điểm bạn chỉ nhận một thư cảnh cáo.","h2":"Ở South Carolina, người lái từ 17 tuổi trở lên nhận thư cảnh cáo khi có 6 điểm, và bị treo bằng lái khi tổng số điểm lên đến 12 điểm trở lên.","p":"Đúng. 12 điểm là bị treo bằng lái."},"tl":{"q":"Sa South Carolina, ilang puntos sa rekord ng drayber ang nagdudulot ng suspensyon ng lisensya para sa drayber na 17 o mas matanda?","o":["4 na puntos","6 na puntos","12 puntos","20 puntos"],"h1":"Sa 6 na puntos, sulat ng babala lang ang matatanggap mo.","h2":"Sa South Carolina, ang drayber na 17 o mas matanda ay nakakatanggap ng sulat ng babala sa 6 na puntos, at sinususpinde ang lisensya kapag umabot ang kabuuan sa 12 puntos o higit pa.","p":"Tama. Ang 12 puntos ay nangangahulugang suspensyon."},"ar":{"q":"في South Carolina، كم نقطة في سجل السائق تؤدي إلى إيقاف الرخصة للسائق الذي عمره 17 سنة أو أكثر؟","o":["4 نقاط","6 نقاط","12 نقطة","20 نقطة"],"h1":"عند 6 نقاط تحصل فقط على رسالة تحذير.","h2":"في South Carolina، السائق الذي عمره 17 سنة أو أكثر يحصل على رسالة تحذير عند 6 نقاط، وتُوقَف رخصته عندما يصل المجموع إلى 12 نقطة أو أكثر.","p":"صحيح. 12 نقطة تعني إيقاف الرخصة."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-023","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, how many points will get a beginner's permit or conditional license suspended?","o":["6 points or more","2 points or more","10 points or more","15 points or more"],"h1":"New drivers have a lower limit than adult drivers.","h2":"In South Carolina, a holder of a beginner's permit, conditional license or special restricted license who gets 6 or more points has the driving privilege suspended.","p":"Right. 6 points is the limit for new drivers."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos hacen que se suspenda un permiso de principiante o una licencia condicional?","o":["6 puntos o más","2 puntos o más","10 puntos o más","15 puntos o más"],"h1":"Los conductores nuevos tienen un límite más bajo que los adultos.","h2":"En Carolina del Sur, quien tiene un permiso de principiante, una licencia condicional o una licencia restringida especial y acumula 6 puntos o más pierde el privilegio de manejar por suspensión.","p":"Correcto. 6 puntos es el límite para conductores nuevos."},"zh":{"q":"在 South Carolina，初学者学习驾照或条件驾照有多少分会被吊销？","o":["6 分或以上","2 分或以上","10 分或以上","15 分或以上"],"h1":"新司机的上限比成年司机低。","h2":"在 South Carolina，持有初学者学习驾照、条件驾照或特别限制驾照的人，如果有 6 分或以上，开车的权利就会被吊销。","p":"对。新司机的上限是 6 分。"},"vi":{"q":"Ở South Carolina, bao nhiêu điểm thì giấy phép tập lái hoặc bằng lái có điều kiện bị treo?","o":["6 điểm trở lên","2 điểm trở lên","10 điểm trở lên","15 điểm trở lên"],"h1":"Người mới lái có giới hạn thấp hơn người lái trưởng thành.","h2":"Ở South Carolina, người có giấy phép tập lái, bằng lái có điều kiện hoặc bằng lái hạn chế đặc biệt mà bị 6 điểm trở lên thì bị treo quyền lái xe.","p":"Đúng. 6 điểm là giới hạn cho người mới lái."},"tl":{"q":"Sa South Carolina, ilang puntos ang magpapasuspinde sa permit ng baguhan o kondisyonal na lisensya?","o":["6 na puntos o higit pa","2 puntos o higit pa","10 puntos o higit pa","15 puntos o higit pa"],"h1":"Mas mababa ang limitasyon ng mga bagong drayber kaysa sa mga adultong drayber.","h2":"Sa South Carolina, ang may hawak ng permit ng baguhan, kondisyonal na lisensya o espesyal na limitadong lisensya na nagkaroon ng 6 o higit pang puntos ay sinususpinde ang pribilehiyong magmaneho.","p":"Tama. Ang 6 na puntos ang limitasyon para sa mga bagong drayber."},"ar":{"q":"في South Carolina، كم نقطة تؤدي إلى إيقاف تصريح المبتدئ أو الرخصة المشروطة؟","o":["6 نقاط أو أكثر","2 نقطة أو أكثر","10 نقاط أو أكثر","15 نقطة أو أكثر"],"h1":"الحد للسائقين الجدد أقل من الحد للسائقين البالغين.","h2":"في South Carolina، صاحب تصريح المبتدئ أو الرخصة المشروطة أو الرخصة المقيدة الخاصة الذي يحصل على 6 نقاط أو أكثر يُوقَف حقه في القيادة.","p":"صحيح. 6 نقاط هي الحد للسائقين الجدد."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-024","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, what happens to the points from a traffic ticket one year after the violation?","o":["They double","They stay the same for ten years","They are moved to your insurance company","They are cut in half"],"h1":"Points get smaller over time.","h2":"In South Carolina, the points from a traffic violation are reduced by half one year after the violation date, so 4 points become 2.","p":"Right. After one year the points are cut in half."},"es":{"q":"En Carolina del Sur, ¿qué pasa con los puntos de una multa de tránsito un año después de la infracción?","o":["Se duplican","Se quedan igual por diez años","Pasan a su compañía de seguros","Se reducen a la mitad"],"h1":"Los puntos bajan con el tiempo.","h2":"En Carolina del Sur, los puntos de una infracción de tránsito se reducen a la mitad un año después de la fecha de la infracción, así que 4 puntos pasan a ser 2.","p":"Correcto. Después de un año los puntos se reducen a la mitad."},"zh":{"q":"在 South Carolina，交通罚单的分数在违规一年后会怎样？","o":["分数加倍","十年内保持不变","转给你的保险公司","分数减半"],"h1":"分数会随着时间变少。","h2":"在 South Carolina，交通违规的分数在违规日期一年后会减半，所以 4 分会变成 2 分。","p":"对。一年后分数减半。"},"vi":{"q":"Ở South Carolina, điểm từ một vé phạt giao thông sẽ ra sao một năm sau khi vi phạm?","o":["Điểm tăng gấp đôi","Điểm giữ nguyên trong mười năm","Điểm được chuyển cho công ty bảo hiểm của bạn","Điểm giảm một nửa"],"h1":"Điểm giảm dần theo thời gian.","h2":"Ở South Carolina, điểm từ một lần vi phạm giao thông được giảm một nửa một năm sau ngày vi phạm, nên 4 điểm trở thành 2 điểm.","p":"Đúng. Sau một năm điểm giảm một nửa."},"tl":{"q":"Sa South Carolina, ano ang nangyayari sa mga puntos mula sa tiket sa trapiko isang taon pagkatapos ng paglabag?","o":["Nadodoble ang mga ito","Nananatiling pareho ang mga ito nang sampung taon","Inililipat ang mga ito sa kompanya ng insurance mo","Nahahati ang mga ito sa kalahati"],"h1":"Lumiliit ang mga puntos habang tumatagal.","h2":"Sa South Carolina, ang mga puntos mula sa paglabag sa trapiko ay nababawasan ng kalahati isang taon pagkatapos ng petsa ng paglabag, kaya ang 4 na puntos ay nagiging 2.","p":"Tama. Pagkalipas ng isang taon, nahahati sa kalahati ang mga puntos."},"ar":{"q":"في South Carolina، ماذا يحدث لنقاط مخالفة المرور بعد سنة واحدة من المخالفة؟","o":["تتضاعف","تبقى كما هي لمدة عشر سنوات","تُنقَل إلى شركة التأمين الخاصة بك","تنخفض إلى النصف"],"h1":"النقاط تصغر مع مرور الوقت.","h2":"في South Carolina، تنخفض نقاط مخالفة المرور إلى النصف بعد سنة واحدة من تاريخ المخالفة، فتصبح 4 نقاط نقطتين (2).","p":"صحيح. بعد سنة واحدة تنخفض النقاط إلى النصف."},"ref":{"doc":"SC","page":"1-18"}},{"id":"sc-025","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what happens if a driver under 21 refuses a test for alcohol?","o":["A fine, but no loss of driving","Loss of driving privileges for at least six months","A warning letter from the DMV","Loss of driving privileges for one day"],"h1":"Refusing is treated more harshly than a 0.02 result.","h2":"In South Carolina, a driver under 21 who refuses a test for alcohol or drugs loses the privilege to drive right away, for at least six months.","p":"Right. At least six months without driving."},"es":{"q":"En Carolina del Sur, ¿qué pasa si un conductor menor de 21 años se niega a una prueba de alcohol?","o":["Una multa, pero sigue manejando","Pierde el privilegio de manejar por lo menos seis meses","Una carta de advertencia del DMV","Pierde el privilegio de manejar por un día"],"h1":"Negarse se castiga más que un resultado de 0.02.","h2":"En Carolina del Sur, un conductor menor de 21 años que se niega a una prueba de alcohol o drogas pierde de inmediato el privilegio de manejar, por lo menos por seis meses.","p":"Correcto. Por lo menos seis meses sin manejar."},"zh":{"q":"在 South Carolina，21 岁以下的司机如果拒绝酒精检测，会怎样？","o":["罚款，但不会失去开车的权利","失去开车的权利至少六个月","收到 DMV 的警告信","失去开车的权利一天"],"h1":"拒绝检测的处罚比测出 0.02 更重。","h2":"在 South Carolina，21 岁以下的司机如果拒绝酒精或毒品检测，会马上失去开车的权利，至少六个月。","p":"对。至少六个月不能开车。"},"vi":{"q":"Ở South Carolina, điều gì xảy ra nếu người lái dưới 21 tuổi từ chối kiểm tra nồng độ cồn?","o":["Bị phạt tiền, nhưng không mất quyền lái xe","Mất quyền lái xe ít nhất sáu tháng","Nhận thư cảnh cáo từ DMV","Mất quyền lái xe một ngày"],"h1":"Từ chối bị xử phạt nặng hơn kết quả 0.02.","h2":"Ở South Carolina, người lái dưới 21 tuổi từ chối kiểm tra rượu bia hoặc ma túy sẽ mất quyền lái xe ngay lập tức, ít nhất sáu tháng.","p":"Đúng. Ít nhất sáu tháng không được lái xe."},"tl":{"q":"Sa South Carolina, ano ang mangyayari kung tumanggi ang drayber na wala pang 21 sa pagsusuri para sa alak?","o":["Multa, pero hindi mawawalan ng karapatang magmaneho","Mawawalan ng pribilehiyong magmaneho nang hindi bababa sa anim na buwan","Sulat ng babala mula sa DMV","Mawawalan ng pribilehiyong magmaneho nang isang araw"],"h1":"Mas mabigat ang parusa sa pagtanggi kaysa sa resultang 0.02.","h2":"Sa South Carolina, ang drayber na wala pang 21 na tumanggi sa pagsusuri para sa alak o droga ay agad na nawawalan ng pribilehiyong magmaneho, nang hindi bababa sa anim na buwan.","p":"Tama. Hindi bababa sa anim na buwan na walang pagmamaneho."},"ar":{"q":"في South Carolina، ماذا يحدث إذا رفض سائق عمره أقل من 21 سنة اختبار الكحول؟","o":["غرامة، لكن دون فقدان حق القيادة","فقدان حق القيادة لمدة ستة أشهر على الأقل","رسالة تحذير من DMV","فقدان حق القيادة ليوم واحد"],"h1":"الرفض يُعاقَب بشدة أكبر من نتيجة 0.02.","h2":"في South Carolina، السائق الذي عمره أقل من 21 سنة ويرفض اختبار الكحول أو المخدرات يفقد حق القيادة فورًا، لمدة ستة أشهر على الأقل.","p":"صحيح. ستة أشهر على الأقل بدون قيادة."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-026","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, can an officer stop a driver only because someone in the car is not wearing a seat belt?","o":["No, only after a crash","Only if the person is a child","Yes, it is a primary law","Only on interstate highways"],"h1":"South Carolina has primary seat belt enforcement.","h2":"In South Carolina, the seat belt law is a primary law, so an officer who clearly sees a driver or passenger without a seat belt or child seat may stop the car.","p":"Right. It is a primary law."},"es":{"q":"En Carolina del Sur, ¿puede un policía detener a un conductor solo porque alguien en el carro no lleva el cinturón de seguridad?","o":["No, solo después de un choque","Solo si la persona es un niño","Sí, es una ley primaria","Solo en las autopistas interestatales"],"h1":"Carolina del Sur aplica el cinturón como ley primaria.","h2":"En Carolina del Sur, la ley del cinturón de seguridad es una ley primaria, así que un policía que ve claramente a un conductor o pasajero sin cinturón o sin asiento infantil puede detener el carro.","p":"Correcto. Es una ley primaria."},"zh":{"q":"在 South Carolina，警察可以只因为车上有人没系安全带就让司机停车吗？","o":["不可以，只有在发生车祸后才可以","只有当这个人是儿童时才可以","可以，这是主要执法法律（primary law）","只有在州际高速公路上才可以"],"h1":"South Carolina 的安全带法律是主要执法。","h2":"在 South Carolina，安全带法律是主要执法法律，所以警察如果清楚看到司机或乘客没有系安全带或没有坐儿童座椅，就可以让车停下。","p":"对。这是主要执法法律。"},"vi":{"q":"Ở South Carolina, cảnh sát có thể chặn xe chỉ vì có người trong xe không thắt dây an toàn không?","o":["Không, chỉ sau khi có tai nạn","Chỉ khi người đó là trẻ em","Có, đó là luật chính (primary law)","Chỉ trên đường cao tốc liên bang"],"h1":"South Carolina thi hành luật dây an toàn theo kiểu luật chính.","h2":"Ở South Carolina, luật dây an toàn là luật chính, nên cảnh sát thấy rõ người lái hoặc hành khách không thắt dây an toàn hoặc không ngồi ghế trẻ em thì có thể chặn xe.","p":"Đúng. Đó là luật chính."},"tl":{"q":"Sa South Carolina, puwede bang pahintuin ng pulis ang drayber dahil lang may isang tao sa kotse na hindi nakasuot ng seat belt?","o":["Hindi, pagkatapos lang ng banggaan","Kung bata lang ang tao","Oo, ito ay pangunahing batas (primary law)","Sa mga interstate highway lang"],"h1":"Ang South Carolina ay may pangunahing pagpapatupad ng batas sa seat belt.","h2":"Sa South Carolina, ang batas sa seat belt ay pangunahing batas, kaya ang pulis na malinaw na nakakita ng drayber o pasahero na walang seat belt o upuan ng bata ay puwedeng magpahinto ng kotse.","p":"Tama. Ito ay pangunahing batas."},"ar":{"q":"في South Carolina، هل يمكن للشرطي أن يوقف السائق فقط لأن شخصًا في السيارة لا يربط حزام الأمان؟","o":["لا، فقط بعد حادث","فقط إذا كان الشخص طفلًا","نعم، إنه قانون أساسي (primary law)","فقط على الطرق السريعة بين الولايات"],"h1":"في South Carolina يُطبَّق قانون حزام الأمان بشكل أساسي.","h2":"في South Carolina، قانون حزام الأمان قانون أساسي، لذلك يمكن للشرطي الذي يرى بوضوح سائقًا أو راكبًا بدون حزام أمان أو مقعد طفل أن يوقف السيارة.","p":"صحيح. إنه قانون أساسي."},"ref":{"doc":"SC","page":"4-6"}},{"id":"sc-027","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, where must a child age seven or younger ride?","o":["In a car seat in the back seat","In the front seat with a seat belt","On an adult's lap in the back seat","Anywhere with an adult seat belt"],"h1":"Air bags in the front can hurt small children.","h2":"In South Carolina, children age seven and younger must ride in a car seat in the back seat of the vehicle, away from the front air bag.","p":"Right. A car seat, in the back seat."},"es":{"q":"En Carolina del Sur, ¿dónde debe viajar un niño de siete años o menos?","o":["En un asiento de seguridad en el asiento trasero","En el asiento delantero con cinturón","En las piernas de un adulto en el asiento trasero","En cualquier lugar con un cinturón de adulto"],"h1":"Las bolsas de aire de adelante pueden lastimar a los niños pequeños.","h2":"En Carolina del Sur, los niños de siete años o menos deben viajar en un asiento de seguridad en el asiento trasero del vehículo, lejos de la bolsa de aire delantera.","p":"Correcto. En un asiento de seguridad, en el asiento trasero."},"zh":{"q":"在 South Carolina，七岁或以下的儿童必须坐在哪里？","o":["后座的儿童座椅里","前座，系上安全带","后座，坐在大人的腿上","任何地方，系上大人的安全带就行"],"h1":"前面的安全气囊可能会伤到小孩。","h2":"在 South Carolina，七岁和以下的儿童必须坐在车子后座的儿童座椅里，远离前面的安全气囊。","p":"对。坐儿童座椅，在后座。"},"vi":{"q":"Ở South Carolina, trẻ em từ bảy tuổi trở xuống phải ngồi ở đâu?","o":["Trong ghế trẻ em ở ghế sau","Ở ghế trước, có thắt dây an toàn","Ngồi trên đùi người lớn ở ghế sau","Ở bất cứ chỗ nào có dây an toàn của người lớn"],"h1":"Túi khí ở phía trước có thể làm trẻ nhỏ bị thương.","h2":"Ở South Carolina, trẻ em từ bảy tuổi trở xuống phải ngồi trong ghế trẻ em ở ghế sau của xe, tránh xa túi khí phía trước.","p":"Đúng. Ghế trẻ em, ở ghế sau."},"tl":{"q":"Sa South Carolina, saan dapat sumakay ang batang pitong taong gulang o mas bata?","o":["Sa upuan ng bata sa likurang upuan","Sa harapang upuan na may seat belt","Sa kandungan ng adulto sa likurang upuan","Kahit saan basta may seat belt ng adulto"],"h1":"Ang mga air bag sa harapan ay puwedeng makasakit sa maliliit na bata.","h2":"Sa South Carolina, ang mga batang pitong taong gulang at mas bata ay dapat sumakay sa upuan ng bata sa likurang upuan ng sasakyan, malayo sa air bag sa harapan.","p":"Tama. Upuan ng bata, sa likurang upuan."},"ar":{"q":"في South Carolina، أين يجب أن يجلس الطفل الذي عمره سبع سنوات أو أقل؟","o":["في مقعد طفل في المقعد الخلفي","في المقعد الأمامي مع حزام الأمان","في حضن شخص بالغ في المقعد الخلفي","في أي مكان مع حزام أمان للبالغين"],"h1":"الوسائد الهوائية في الأمام يمكن أن تؤذي الأطفال الصغار.","h2":"في South Carolina، يجب أن يجلس الأطفال الذين عمرهم سبع سنوات أو أقل في مقعد طفل في المقعد الخلفي للسيارة، بعيدًا عن الوسادة الهوائية الأمامية.","p":"صحيح. مقعد طفل، في المقعد الخلفي."},"ref":{"doc":"SC","page":"4-7"}},{"id":"sc-028","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, what is the smallest following distance the driver's manual says to keep behind the car ahead?","o":["2 seconds","3 seconds","4 seconds","1 second"],"h1":"Pick a sign or pole and count how long it takes you to reach it after the car ahead passes it.","h2":"In South Carolina, the driver's manual says to stay at least 4 seconds behind the vehicle in front of you.","p":"Right. At least 4 seconds behind."},"es":{"q":"En Carolina del Sur, ¿cuál es la distancia mínima que, según el manual, debe dejar detrás del auto de adelante?","o":["2 segundos","3 segundos","4 segundos","1 segundo"],"h1":"Elija un letrero o un poste y cuente cuánto tarda en llegar a él después de que pase el auto de adelante.","h2":"En Carolina del Sur, el manual de manejo dice que debe mantenerse al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Al menos 4 segundos detrás."},"zh":{"q":"在 South Carolina，驾驶手册说你和前面的车之间最少要保持多远的跟车距离？","o":["2 秒","3 秒","4 秒","1 秒"],"h1":"选一个路牌或电线杆，前面的车经过它以后，数一数你要多久才到那里。","h2":"在 South Carolina，驾驶手册说你要和前面的车保持至少 4 秒的距离。","p":"对。至少保持 4 秒的距离。"},"vi":{"q":"Ở South Carolina, sổ tay lái xe nói bạn phải giữ khoảng cách ít nhất bao nhiêu với xe phía trước?","o":["2 giây","3 giây","4 giây","1 giây"],"h1":"Chọn một biển báo hoặc cột điện, rồi đếm xem bạn mất bao lâu để tới đó sau khi xe phía trước chạy qua.","h2":"Ở South Carolina, sổ tay lái xe nói bạn phải đi cách xe phía trước ít nhất 4 giây.","p":"Đúng. Cách xe phía trước ít nhất 4 giây."},"tl":{"q":"Sa South Carolina, ano ang pinakamaikling layo na sinasabi ng driver's manual na dapat mong panatilihin sa likod ng sasakyan sa unahan?","o":["2 segundo","3 segundo","4 segundo","1 segundo"],"h1":"Pumili ng karatula o poste at bilangin kung gaano katagal bago ka makarating doon matapos itong lampasan ng sasakyan sa unahan.","h2":"Sa South Carolina, sinasabi ng driver's manual na dapat kang manatili nang hindi bababa sa 4 segundo sa likod ng sasakyan sa unahan mo.","p":"Tama. Hindi bababa sa 4 segundo sa likod."},"ar":{"q":"في South Carolina، ما أقل مسافة يقول دليل القيادة أن تتركها خلف السيارة التي أمامك؟","o":["2 ثانية","3 ثوانٍ","4 ثوانٍ","1 ثانية"],"h1":"اختر لافتة أو عمودًا، وعُدّ كم من الوقت تحتاج لتصل إليه بعد أن تمر به السيارة التي أمامك.","h2":"في South Carolina، يقول دليل القيادة أن تبقى على الأقل 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. على الأقل 4 ثوانٍ خلفها."},"ref":{"doc":"SC","page":"8-6"}},{"id":"sc-029","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, your driver's license has been expired for more than nine months. What must you do to get a license again?","o":["Pay a late fee online","Pass the vision, knowledge and skills tests again","Show a new photo ID only","Wait 30 days and renew by mail"],"h1":"After a long time, the state wants to check your skills again.","h2":"In South Carolina, if your license has been expired for more than nine months, you must go to an SCDMV branch and pass the vision, knowledge and skills tests again.","p":"Right. All three tests again."},"es":{"q":"En Carolina del Sur, su licencia de conducir lleva más de nueve meses vencida. ¿Qué debe hacer para obtener una licencia otra vez?","o":["Pagar un recargo por internet","Aprobar otra vez los exámenes de la vista, de conocimientos y de manejo","Mostrar solo una nueva identificación con foto","Esperar 30 días y renovar por correo"],"h1":"Después de mucho tiempo, el estado quiere revisar otra vez sus habilidades.","h2":"En Carolina del Sur, si su licencia lleva más de nueve meses vencida, debe ir a una oficina del SCDMV y aprobar otra vez los exámenes de la vista, de conocimientos y de manejo.","p":"Correcto. Los tres exámenes otra vez."},"zh":{"q":"在 South Carolina，你的驾照已经过期超过九个月。你要怎样才能再拿到驾照？","o":["在网上交滞纳金","重新通过视力、笔试和路考","只出示新的带照片的身份证件","等 30 天，然后用邮寄方式更新"],"h1":"过了很长时间以后，州政府要再检查一次你的驾驶能力。","h2":"在 South Carolina，如果你的驾照过期超过九个月，你必须去 SCDMV 办公室，重新通过视力、笔试和路考。","p":"对。三项考试都要重新考。"},"vi":{"q":"Ở South Carolina, bằng lái của bạn đã hết hạn hơn chín tháng. Bạn phải làm gì để có lại bằng lái?","o":["Trả phí trễ hạn trên mạng","Thi lại bài kiểm tra thị lực, lý thuyết và lái xe","Chỉ cần đưa giấy tờ tùy thân có ảnh mới","Đợi 30 ngày rồi gia hạn qua bưu điện"],"h1":"Sau một thời gian dài, tiểu bang muốn kiểm tra lại kỹ năng của bạn.","h2":"Ở South Carolina, nếu bằng lái của bạn đã hết hạn hơn chín tháng, bạn phải đến văn phòng SCDMV và thi lại bài kiểm tra thị lực, lý thuyết và lái xe.","p":"Đúng. Thi lại cả ba bài."},"tl":{"q":"Sa South Carolina, mahigit siyam na buwan nang expired ang iyong lisensya. Ano ang dapat mong gawin para magkaroon ulit ng lisensya?","o":["Magbayad ng multa sa pagkahuli online","Pumasa ulit sa vision, knowledge at skills test","Magpakita lang ng bagong ID na may litrato","Maghintay ng 30 araw at mag-renew sa koreo"],"h1":"Pagkatapos ng mahabang panahon, gusto ng estado na suriin ulit ang iyong kakayahan.","h2":"Sa South Carolina, kung mahigit siyam na buwan nang expired ang iyong lisensya, dapat kang pumunta sa isang sangay ng SCDMV at pumasa ulit sa vision, knowledge at skills test.","p":"Tama. Lahat ng tatlong test ulit."},"ar":{"q":"في South Carolina، انتهت رخصة القيادة الخاصة بك منذ أكثر من تسعة أشهر. ماذا يجب أن تفعل لتحصل على رخصة مرة أخرى؟","o":["تدفع غرامة تأخير عبر الإنترنت","تنجح مرة أخرى في اختبارات النظر والمعرفة والقيادة","تُظهر بطاقة هوية جديدة بصورة فقط","تنتظر 30 يومًا وتجدد بالبريد"],"h1":"بعد وقت طويل، تريد الولاية أن تفحص مهاراتك مرة أخرى.","h2":"في South Carolina، إذا انتهت رخصتك منذ أكثر من تسعة أشهر، يجب أن تذهب إلى فرع SCDMV وتنجح مرة أخرى في اختبارات النظر والمعرفة والقيادة.","p":"صحيح. الاختبارات الثلاثة كلها مرة أخرى."},"ref":{"doc":"SC","page":"1-18"}},{"id":"sc-030","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, a car is coming toward you at night. When should you dim your high beams?","o":["When it is still 500 feet or more away","When it is about 100 feet away","Only if it flashes its lights at you","When it is right beside you"],"h1":"Bright lights can blind the other driver from far away.","h2":"In South Carolina, you should dim your high beams while an oncoming vehicle is still 500 feet or more away.","p":"Right. Dim them at 500 feet or more."},"es":{"q":"En Carolina del Sur, un auto viene hacia usted de noche. ¿Cuándo debe bajar las luces altas?","o":["Cuando todavía está a 500 pies o más","Cuando está a unos 100 pies","Solo si le hace cambio de luces","Cuando está justo a su lado"],"h1":"Las luces fuertes pueden encandilar al otro conductor desde lejos.","h2":"En Carolina del Sur, debe bajar las luces altas cuando el vehículo que viene de frente todavía está a 500 pies o más.","p":"Correcto. Bájelas a 500 pies o más."},"zh":{"q":"在 South Carolina，晚上有一辆车朝你开过来。你应该什么时候把远光灯调成近光灯？","o":["在它还在 500 英尺或更远的时候","在它大约 100 英尺远的时候","只有在它对你闪灯的时候","在它就在你旁边的时候"],"h1":"很亮的车灯从很远的地方就会让对面的司机看不清。","h2":"在 South Carolina，对面来车还在 500 英尺或更远的时候，你就应该把远光灯调成近光灯。","p":"对。在 500 英尺或更远就调暗。"},"vi":{"q":"Ở South Carolina, ban đêm có một xe đang chạy về phía bạn. Khi nào bạn nên hạ đèn pha xuống đèn cốt?","o":["Khi xe đó vẫn còn cách 500 feet hoặc xa hơn","Khi xe đó cách khoảng 100 feet","Chỉ khi xe đó nháy đèn với bạn","Khi xe đó ở ngay bên cạnh bạn"],"h1":"Đèn sáng có thể làm người lái xe kia bị chói từ rất xa.","h2":"Ở South Carolina, bạn nên hạ đèn pha xuống khi xe chạy ngược chiều vẫn còn cách 500 feet hoặc xa hơn.","p":"Đúng. Hạ đèn khi còn cách 500 feet hoặc xa hơn."},"tl":{"q":"Sa South Carolina, may sasakyang papalapit sa iyo sa gabi. Kailan mo dapat i-dim ang iyong high beams?","o":["Kapag 500 feet pa o mas malayo ito","Kapag mga 100 feet na lang ito","Kapag nag-flash lang ito ng ilaw sa iyo","Kapag nasa tabi mo na ito"],"h1":"Ang maliliwanag na ilaw ay puwedeng makasilaw sa ibang driver kahit malayo pa.","h2":"Sa South Carolina, dapat mong i-dim ang iyong high beams habang ang paparating na sasakyan ay 500 feet pa o mas malayo.","p":"Tama. I-dim ang mga ito sa 500 feet o higit pa."},"ar":{"q":"في South Carolina، سيارة قادمة نحوك في الليل. متى يجب أن تخفض الأضواء العالية؟","o":["عندما تكون ما زالت على بعد 500 قدم أو أكثر","عندما تكون على بعد حوالي 100 قدم","فقط إذا أومضت أضواءها لك","عندما تكون بجانبك تمامًا"],"h1":"الأضواء القوية يمكن أن تُعمي السائق الآخر من مسافة بعيدة.","h2":"في South Carolina، يجب أن تخفض الأضواء العالية عندما تكون السيارة القادمة ما زالت على بعد 500 قدم أو أكثر.","p":"صحيح. اخفضها على بعد 500 قدم أو أكثر."},"ref":{"doc":"SC","page":"11-1"}},{"id":"sc-031","scope":"SC","cat":"signals","sign":null,"c":3,"en":{"q":"In South Carolina, how far before a turn or lane change does state law say you must turn on your signal?","o":["At least 25 feet","At least 50 feet","Only as you begin to turn","At least 100 feet"],"h1":"The distance is about the length of five or six cars.","h2":"In South Carolina, state law says you must signal at least 100 feet before you turn, change lanes or merge.","p":"Right. At least 100 feet ahead."},"es":{"q":"En Carolina del Sur, ¿con cuánta anticipación exige la ley estatal poner la direccional antes de girar o cambiar de carril?","o":["Al menos 25 pies","Al menos 50 pies","Solo al empezar a girar","Al menos 100 pies"],"h1":"La distancia es más o menos el largo de cinco o seis autos.","h2":"En Carolina del Sur, la ley estatal exige poner la direccional al menos 100 pies antes de girar, cambiar de carril o incorporarse al tráfico.","p":"Correcto. Al menos 100 pies antes."},"zh":{"q":"在 South Carolina，州法律规定你在转弯或换车道前多远就必须打方向灯？","o":["至少 25 英尺","至少 50 英尺","只在开始转弯的时候","至少 100 英尺"],"h1":"这个距离大约是五六辆车的长度。","h2":"在 South Carolina，州法律规定你在转弯、换车道或并道前至少 100 英尺就必须打方向灯。","p":"对。至少提前 100 英尺。"},"vi":{"q":"Ở South Carolina, luật tiểu bang nói bạn phải bật đèn xi nhan cách bao xa trước khi rẽ hoặc đổi làn?","o":["Ít nhất 25 feet","Ít nhất 50 feet","Chỉ khi bạn bắt đầu rẽ","Ít nhất 100 feet"],"h1":"Khoảng cách này dài bằng khoảng năm hoặc sáu chiếc xe.","h2":"Ở South Carolina, luật tiểu bang nói bạn phải bật đèn xi nhan ít nhất 100 feet trước khi rẽ, đổi làn hoặc nhập làn.","p":"Đúng. Ít nhất 100 feet trước đó."},"tl":{"q":"Sa South Carolina, gaano kalayo bago lumiko o lumipat ng lane sinasabi ng batas ng estado na dapat mong buksan ang iyong signal?","o":["Hindi bababa sa 25 feet","Hindi bababa sa 50 feet","Kapag nagsisimula ka na lang lumiko","Hindi bababa sa 100 feet"],"h1":"Ang layo ay halos haba ng lima o anim na sasakyan.","h2":"Sa South Carolina, sinasabi ng batas ng estado na dapat kang mag-signal nang hindi bababa sa 100 feet bago ka lumiko, lumipat ng lane o sumanib sa trapiko.","p":"Tama. Hindi bababa sa 100 feet bago."},"ar":{"q":"في South Carolina، على أي مسافة قبل الانعطاف أو تغيير المسار يقول قانون الولاية إنه يجب أن تشغّل الإشارة؟","o":["على الأقل 25 قدمًا","على الأقل 50 قدمًا","فقط عندما تبدأ الانعطاف","على الأقل 100 قدم"],"h1":"هذه المسافة تساوي تقريبًا طول خمس أو ست سيارات.","h2":"في South Carolina، يقول قانون الولاية إنه يجب أن تشغّل الإشارة على الأقل 100 قدم قبل أن تنعطف أو تغيّر المسار أو تندمج في حركة السير.","p":"صحيح. على الأقل 100 قدم قبلها."},"ref":{"doc":"SC","page":"8-9"}},{"id":"sc-032","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, what must you have with you every time you drive?","o":["Only your driver's license","Your license and your birth certificate","Your license, the vehicle registration and an insurance card","Your license and the car's title"],"h1":"Think of one paper for you, one for the car, and one for the insurance.","h2":"In South Carolina, you must carry your driver's license, the vehicle registration and a valid insurance card when you drive, or you can be fined.","p":"Right. License, registration and insurance card."},"es":{"q":"En Carolina del Sur, ¿qué debe llevar consigo cada vez que maneja?","o":["Solo su licencia de conducir","Su licencia y su acta de nacimiento","Su licencia, el registro del vehículo y una tarjeta de seguro","Su licencia y el título del carro"],"h1":"Piense en un papel para usted, uno para el carro y uno para el seguro.","h2":"En Carolina del Sur, debe llevar su licencia de conducir, el registro del vehículo y una tarjeta de seguro válida cuando maneja, o le pueden poner una multa.","p":"Correcto. Licencia, registro y tarjeta de seguro."},"zh":{"q":"在 South Carolina，每次开车时你必须随身带着什么？","o":["只带驾照","驾照和出生证明","驾照、车辆登记证和保险卡","驾照和汽车所有权证"],"h1":"想一想：一份文件是你的，一份是车的，一份是保险的。","h2":"在 South Carolina，开车时你必须带着驾照、车辆登记证和有效的保险卡，否则可能被罚款。","p":"对。驾照、登记证和保险卡。"},"vi":{"q":"Ở South Carolina, bạn phải mang theo gì mỗi lần lái xe?","o":["Chỉ bằng lái xe","Bằng lái và giấy khai sinh","Bằng lái, giấy đăng ký xe và thẻ bảo hiểm","Bằng lái và giấy chủ quyền xe"],"h1":"Hãy nghĩ đến một giấy cho bạn, một giấy cho xe và một giấy cho bảo hiểm.","h2":"Ở South Carolina, khi lái xe bạn phải mang theo bằng lái, giấy đăng ký xe và thẻ bảo hiểm còn hiệu lực, nếu không bạn có thể bị phạt tiền.","p":"Đúng. Bằng lái, giấy đăng ký và thẻ bảo hiểm."},"tl":{"q":"Sa South Carolina, ano ang dapat mong dala tuwing nagmamaneho ka?","o":["Ang lisensya mo lamang","Ang lisensya mo at ang birth certificate mo","Ang lisensya mo, ang rehistro ng sasakyan at isang insurance card","Ang lisensya mo at ang titulo ng kotse"],"h1":"Isipin ang isang papel para sa iyo, isa para sa kotse, at isa para sa insurance.","h2":"Sa South Carolina, dapat mong dala ang lisensya mo, ang rehistro ng sasakyan at isang valid na insurance card kapag nagmamaneho ka, o puwede kang multahan.","p":"Tama. Lisensya, rehistro at insurance card."},"ar":{"q":"في South Carolina، ماذا يجب أن يكون معك في كل مرة تقود فيها؟","o":["رخصة القيادة فقط","رخصتك وشهادة ميلادك","رخصتك وتسجيل المركبة وبطاقة التأمين","رخصتك وسند ملكية السيارة"],"h1":"فكّر في ورقة لك، وورقة للسيارة، وورقة للتأمين.","h2":"في South Carolina يجب أن تحمل رخصة القيادة وتسجيل المركبة وبطاقة تأمين سارية عندما تقود، وإلا قد تدفع غرامة.","p":"صحيح. الرخصة والتسجيل وبطاقة التأمين."},"ref":{"doc":"SC","page":"1-3"}},{"id":"sc-033","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a 16-year-old has a special restricted license with a waiver for work. Until what time may they drive alone?","o":["6 p.m.","8 p.m.","10 p.m.","Midnight"],"h1":"The waiver gives more time than the usual 6 p.m. or 8 p.m. limit, but never past the end of the day.","h2":"In South Carolina, a special restricted license with a waiver lets a 16-year-old drive alone until midnight for work or certain after-school activities, but never after midnight.","p":"Right. Until midnight, never later."},"es":{"q":"En Carolina del Sur, un joven de 16 años tiene una licencia restringida especial con una exención por trabajo. ¿Hasta qué hora puede manejar solo?","o":["6 p.m.","8 p.m.","10 p.m.","Medianoche"],"h1":"La exención da más tiempo que el límite normal de 6 p.m. u 8 p.m., pero nunca después de que termina el día.","h2":"En Carolina del Sur, una licencia restringida especial con exención permite a un joven de 16 años manejar solo hasta la medianoche por trabajo o ciertas actividades extracurriculares, pero nunca después de la medianoche.","p":"Correcto. Hasta la medianoche, nunca más tarde."},"zh":{"q":"在 South Carolina，一名 16 岁的青少年持有特别限制驾照，并有工作豁免。他最晚可以独自开车到几点？","o":["晚上 6 点","晚上 8 点","晚上 10 点","午夜"],"h1":"豁免给的时间比平常晚上 6 点或 8 点的限制更晚，但绝不会超过一天的结束。","h2":"在 South Carolina，有豁免的特别限制驾照让 16 岁的青少年为了工作或某些课后活动独自开车到午夜，但午夜以后绝对不行。","p":"对。到午夜，不能更晚。"},"vi":{"q":"Ở South Carolina, một thiếu niên 16 tuổi có bằng lái hạn chế đặc biệt với giấy miễn trừ vì đi làm. Người đó được lái một mình đến mấy giờ?","o":["6 giờ chiều","8 giờ tối","10 giờ tối","Nửa đêm"],"h1":"Giấy miễn trừ cho thêm thời gian so với giới hạn thường là 6 giờ chiều hoặc 8 giờ tối, nhưng không bao giờ quá hết ngày.","h2":"Ở South Carolina, bằng lái hạn chế đặc biệt có giấy miễn trừ cho phép thiếu niên 16 tuổi lái một mình đến nửa đêm để đi làm hoặc một số hoạt động sau giờ học, nhưng không bao giờ sau nửa đêm.","p":"Đúng. Đến nửa đêm, không trễ hơn."},"tl":{"q":"Sa South Carolina, may espesyal na limitadong lisensya ang isang 16 taong gulang na may waiver para sa trabaho. Hanggang anong oras siya puwedeng magmaneho nang mag-isa?","o":["6 p.m.","8 p.m.","10 p.m.","Hatinggabi"],"h1":"Mas mahabang oras ang ibinibigay ng waiver kaysa sa karaniwang limitasyon na 6 p.m. o 8 p.m., pero hindi kailanman lampas sa katapusan ng araw.","h2":"Sa South Carolina, ang espesyal na limitadong lisensya na may waiver ay nagpapahintulot sa 16 taong gulang na magmaneho nang mag-isa hanggang hatinggabi para sa trabaho o ilang gawain pagkatapos ng klase, pero hindi kailanman lampas sa hatinggabi.","p":"Tama. Hanggang hatinggabi, hindi lampas doon."},"ar":{"q":"في South Carolina، مراهق عمره 16 سنة معه رخصة مقيدة خاصة مع إعفاء من أجل العمل. حتى أي ساعة يمكنه أن يقود وحده؟","o":["6 مساءً","8 مساءً","10 مساءً","منتصف الليل"],"h1":"الإعفاء يعطي وقتًا أطول من الحد العادي، 6 مساءً أو 8 مساءً، لكن ليس بعد نهاية اليوم أبدًا.","h2":"في South Carolina، الرخصة المقيدة الخاصة مع إعفاء تسمح لمن عمره 16 سنة أن يقود وحده حتى منتصف الليل من أجل العمل أو بعض الأنشطة بعد المدرسة، لكن ليس بعد منتصف الليل أبدًا.","p":"صحيح. حتى منتصف الليل، وليس بعده."},"ref":{"doc":"SC","page":"1-9"}},{"id":"sc-034","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, what happens if you do not wear your seat belt during the driving (skills) test?","o":["The examiner gives you a warning","You fail the test automatically","You lose a few points but can still pass","The test is moved to another day"],"h1":"The manual treats this as a serious mistake, not a small one.","h2":"In South Carolina, you automatically fail the skills test if you do not use your seat belt.","p":"Right. No seat belt means you fail."},"es":{"q":"En Carolina del Sur, ¿qué pasa si no usa el cinturón de seguridad durante el examen de manejo?","o":["El examinador le da una advertencia","Reprueba el examen automáticamente","Pierde algunos puntos pero aún puede aprobar","El examen se cambia para otro día"],"h1":"El manual lo trata como un error grave, no pequeño.","h2":"En Carolina del Sur, usted reprueba automáticamente el examen de manejo si no usa el cinturón de seguridad.","p":"Correcto. Sin cinturón, reprueba."},"zh":{"q":"在 South Carolina，如果你在路考（技能考试）中不系安全带，会怎样？","o":["考官给你一个警告","你自动考试不及格","你会扣几分，但还可以通过","考试改到另一天"],"h1":"手册把这当作严重的错误，不是小错误。","h2":"在 South Carolina，如果你不系安全带，路考会自动不及格。","p":"对。不系安全带就不及格。"},"vi":{"q":"Ở South Carolina, chuyện gì xảy ra nếu bạn không thắt dây an toàn trong bài thi lái trên đường (kỹ năng)?","o":["Giám khảo cảnh cáo bạn","Bạn tự động bị rớt","Bạn bị trừ vài điểm nhưng vẫn có thể đậu","Bài thi được dời sang ngày khác"],"h1":"Sách hướng dẫn coi đây là lỗi nặng, không phải lỗi nhỏ.","h2":"Ở South Carolina, bạn tự động bị rớt bài thi lái trên đường nếu bạn không thắt dây an toàn.","p":"Đúng. Không thắt dây an toàn là rớt."},"tl":{"q":"Sa South Carolina, ano ang mangyayari kung hindi ka magsuot ng seat belt sa pagsusulit sa kalsada (skills test)?","o":["Bibigyan ka ng babala ng examiner","Awtomatiko kang babagsak","Mababawasan ka ng ilang puntos pero puwede ka pang pumasa","Ililipat ang pagsusulit sa ibang araw"],"h1":"Itinuturing ito ng manual na seryosong pagkakamali, hindi maliit.","h2":"Sa South Carolina, awtomatiko kang babagsak sa pagsusulit sa kalsada kung hindi mo gagamitin ang seat belt mo.","p":"Tama. Walang seat belt, bagsak ka."},"ar":{"q":"في South Carolina، ماذا يحدث إذا لم تربط حزام الأمان أثناء اختبار القيادة على الطريق (اختبار المهارات)؟","o":["يعطيك الفاحص تحذيرًا","ترسب في الاختبار تلقائيًا","تخسر بعض النقاط لكن يمكنك أن تنجح","يتأجل الاختبار إلى يوم آخر"],"h1":"الدليل يعتبر هذا خطأً كبيرًا، وليس خطأً صغيرًا.","h2":"في South Carolina ترسب تلقائيًا في اختبار القيادة على الطريق إذا لم تربط حزام الأمان.","p":"صحيح. بدون حزام الأمان ترسب."},"ref":{"doc":"SC","page":"1-12"}},{"id":"sc-035","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, you fail the driving (skills) test on your first try. How long must you wait to take it again?","o":["2 business days","The same day","7 calendar days","30 calendar days"],"h1":"The wait gets longer each time you fail. The first wait is the shortest.","h2":"In South Carolina, after you fail the skills test the first time, you must wait two business days before you take it again.","p":"Right. Two business days."},"es":{"q":"En Carolina del Sur, reprueba el examen de manejo en su primer intento. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["2 días hábiles","El mismo día","7 días calendario","30 días calendario"],"h1":"La espera es más larga cada vez que reprueba. La primera espera es la más corta.","h2":"En Carolina del Sur, después de reprobar el examen de manejo la primera vez, debe esperar dos días hábiles antes de tomarlo otra vez.","p":"Correcto. Dos días hábiles."},"zh":{"q":"在 South Carolina，你第一次路考（技能考试）不及格。你必须等多久才能再考？","o":["2 个工作日","同一天","7 个日历日","30 个日历日"],"h1":"每次不及格，等的时间会更长。第一次等的时间最短。","h2":"在 South Carolina，第一次路考不及格后，你必须等两个工作日才能再考。","p":"对。两个工作日。"},"vi":{"q":"Ở South Carolina, bạn rớt bài thi lái trên đường (kỹ năng) lần đầu. Bạn phải chờ bao lâu mới được thi lại?","o":["2 ngày làm việc","Ngay trong ngày","7 ngày lịch","30 ngày lịch"],"h1":"Mỗi lần rớt, thời gian chờ lại dài hơn. Lần chờ đầu tiên là ngắn nhất.","h2":"Ở South Carolina, sau khi rớt bài thi lái trên đường lần đầu, bạn phải chờ hai ngày làm việc rồi mới được thi lại.","p":"Đúng. Hai ngày làm việc."},"tl":{"q":"Sa South Carolina, bumagsak ka sa pagsusulit sa kalsada (skills test) sa unang subok mo. Gaano katagal ka dapat maghintay bago kumuha ulit?","o":["2 araw ng trabaho","Sa parehong araw","7 araw sa kalendaryo","30 araw sa kalendaryo"],"h1":"Humahaba ang paghihintay sa bawat pagbagsak. Ang unang paghihintay ang pinakamaikli.","h2":"Sa South Carolina, pagkatapos mong bumagsak sa pagsusulit sa kalsada sa unang pagkakataon, dapat kang maghintay ng dalawang araw ng trabaho bago kumuha ulit.","p":"Tama. Dalawang araw ng trabaho."},"ar":{"q":"في South Carolina، رسبت في اختبار القيادة على الطريق (اختبار المهارات) في المحاولة الأولى. كم يجب أن تنتظر قبل أن تعيده؟","o":["2 يوم عمل","في اليوم نفسه","7 أيام تقويمية","30 يومًا تقويميًا"],"h1":"الانتظار يصبح أطول في كل مرة ترسب. الانتظار الأول هو الأقصر.","h2":"في South Carolina، بعد أن ترسب في اختبار القيادة على الطريق أول مرة، يجب أن تنتظر يومَي عمل قبل أن تعيد الاختبار.","p":"صحيح. يوما عمل."},"ref":{"doc":"SC","page":"1-13"}},{"id":"sc-036","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, you have a valid license from another state and move here to stay. How soon must you apply for a South Carolina license?","o":["Within 10 days","Within 30 days","Within 45 days","Within 90 days"],"h1":"It is more than a month, but less than two months.","h2":"In South Carolina, a new resident with a license from another state must apply for a South Carolina license within 45 days of moving.","p":"Right. Within 45 days."},"es":{"q":"En Carolina del Sur, usted tiene una licencia válida de otro estado y se muda aquí para quedarse. ¿En cuánto tiempo debe solicitar una licencia de Carolina del Sur?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 45 días","Dentro de 90 días"],"h1":"Es más de un mes, pero menos de dos meses.","h2":"En Carolina del Sur, un nuevo residente con licencia de otro estado debe solicitar una licencia de Carolina del Sur dentro de los 45 días después de mudarse.","p":"Correcto. Dentro de 45 días."},"zh":{"q":"在 South Carolina，你有另一个州的有效驾照，搬来这里长期居住。你必须在多长时间内申请 South Carolina 驾照？","o":["10 天内","30 天内","45 天内","90 天内"],"h1":"比一个月长，但比两个月短。","h2":"在 South Carolina，持有另一个州驾照的新居民必须在搬来后 45 天内申请 South Carolina 驾照。","p":"对。45 天内。"},"vi":{"q":"Ở South Carolina, bạn có bằng lái còn hiệu lực của tiểu bang khác và dọn đến đây sống lâu dài. Bạn phải xin bằng lái South Carolina trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 45 ngày","Trong vòng 90 ngày"],"h1":"Hơn một tháng, nhưng ít hơn hai tháng.","h2":"Ở South Carolina, cư dân mới có bằng lái của tiểu bang khác phải xin bằng lái South Carolina trong vòng 45 ngày sau khi dọn đến.","p":"Đúng. Trong vòng 45 ngày."},"tl":{"q":"Sa South Carolina, may valid kang lisensya mula sa ibang estado at lumipat ka rito para dito na tumira. Gaano kabilis ka dapat mag-apply ng lisensya ng South Carolina?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 45 araw","Sa loob ng 90 araw"],"h1":"Higit ito sa isang buwan, pero kulang sa dalawang buwan.","h2":"Sa South Carolina, ang bagong residente na may lisensya mula sa ibang estado ay dapat mag-apply ng lisensya ng South Carolina sa loob ng 45 araw pagkatapos lumipat.","p":"Tama. Sa loob ng 45 araw."},"ar":{"q":"في South Carolina، معك رخصة سارية من ولاية أخرى وانتقلت إلى هنا لتقيم. خلال كم من الوقت يجب أن تقدّم طلبًا لرخصة South Carolina؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 45 يومًا","خلال 90 يومًا"],"h1":"المدة أكثر من شهر، لكنها أقل من شهرين.","h2":"في South Carolina يجب على المقيم الجديد الذي معه رخصة من ولاية أخرى أن يقدّم طلبًا لرخصة South Carolina خلال 45 يومًا من انتقاله.","p":"صحيح. خلال 45 يومًا."},"ref":{"doc":"SC","page":"1-13"}},{"id":"sc-037","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, a US citizen renews a driver's license online. For how many years is the new license issued?","o":["4 years","8 years","5 years","10 years"],"h1":"It is a long license, close to a decade, but not a full ten years.","h2":"In South Carolina, a US citizen who renews online or by mail gets an eight-year license.","p":"Right. An eight-year license."},"es":{"q":"En Carolina del Sur, un ciudadano de EE. UU. renueva su licencia de conducir en línea. ¿Por cuántos años se emite la nueva licencia?","o":["4 años","8 años","5 años","10 años"],"h1":"Es una licencia larga, casi una década, pero no diez años completos.","h2":"En Carolina del Sur, un ciudadano de EE. UU. que renueva en línea o por correo recibe una licencia de ocho años.","p":"Correcto. Una licencia de ocho años."},"zh":{"q":"在 South Carolina，一位美国公民在网上更新驾照。新驾照的有效期是几年？","o":["4 年","8 年","5 年","10 年"],"h1":"有效期很长，接近十年，但不是整整十年。","h2":"在 South Carolina，美国公民在网上或通过邮寄更新驾照，会拿到有效期八年的驾照。","p":"对。八年的驾照。"},"vi":{"q":"Ở South Carolina, một công dân Mỹ gia hạn bằng lái xe trên mạng. Bằng lái mới có hạn bao nhiêu năm?","o":["4 năm","8 năm","5 năm","10 năm"],"h1":"Đó là bằng lái có hạn dài, gần mười năm, nhưng không đủ mười năm.","h2":"Ở South Carolina, công dân Mỹ gia hạn trên mạng hoặc qua thư sẽ nhận bằng lái có hạn tám năm.","p":"Đúng. Bằng lái tám năm."},"tl":{"q":"Sa South Carolina, nag-renew online ng lisensya sa pagmamaneho ang isang mamamayan ng US. Ilang taon ang bisa ng bagong lisensya?","o":["4 na taon","8 taon","5 taon","10 taon"],"h1":"Mahaba ang bisa ng lisensyang ito, malapit sa isang dekada, pero hindi buong sampung taon.","h2":"Sa South Carolina, ang mamamayan ng US na nag-renew online o sa koreo ay makakakuha ng lisensyang may bisang walong taon.","p":"Tama. Lisensyang walong taon."},"ar":{"q":"في South Carolina، مواطن أمريكي يجدد رخصة القيادة عبر الإنترنت. كم سنة تكون مدة الرخصة الجديدة؟","o":["4 سنوات","8 سنوات","5 سنوات","10 سنوات"],"h1":"إنها رخصة طويلة، قريبة من عشر سنوات، لكنها ليست عشر سنوات كاملة.","h2":"في South Carolina، المواطن الأمريكي الذي يجدد عبر الإنترنت أو بالبريد يحصل على رخصة مدتها ثماني سنوات.","p":"صحيح. رخصة مدتها ثماني سنوات."},"ref":{"doc":"SC","page":"1-15"}},{"id":"sc-038","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, how often can a defensive driving course be used to reduce the points on your record?","o":["Once a year","As often as you like","Once every five years","Once every three years"],"h1":"You cannot use it every year. The wait is a few years.","h2":"In South Carolina, a defensive driving course can reduce your points only one time in a three-year period.","p":"Right. Once every three years."},"es":{"q":"En Carolina del Sur, ¿con qué frecuencia puede usar un curso de manejo defensivo para reducir los puntos en su historial?","o":["Una vez al año","Todas las veces que quiera","Una vez cada cinco años","Una vez cada tres años"],"h1":"No puede usarlo cada año. La espera es de unos años.","h2":"En Carolina del Sur, un curso de manejo defensivo puede reducir sus puntos solo una vez en un período de tres años.","p":"Correcto. Una vez cada tres años."},"zh":{"q":"在 South Carolina，防御性驾驶课程多久可以用一次来减少你记录上的扣分？","o":["每年一次","想用几次就用几次","每五年一次","每三年一次"],"h1":"你不能每年都用。要等几年。","h2":"在 South Carolina，防御性驾驶课程在三年内只能减少一次你的扣分。","p":"对。每三年一次。"},"vi":{"q":"Ở South Carolina, bao lâu thì bạn được dùng một khóa lái xe phòng vệ (defensive driving) để giảm điểm trong hồ sơ của mình?","o":["Mỗi năm một lần","Bao nhiêu lần cũng được","Mỗi năm năm một lần","Mỗi ba năm một lần"],"h1":"Bạn không thể dùng nó mỗi năm. Phải chờ vài năm.","h2":"Ở South Carolina, khóa lái xe phòng vệ chỉ được dùng để giảm điểm một lần trong khoảng thời gian ba năm.","p":"Đúng. Mỗi ba năm một lần."},"tl":{"q":"Sa South Carolina, gaano kadalas puwedeng gamitin ang kurso sa defensive driving para bawasan ang mga puntos sa rekord mo?","o":["Isang beses sa isang taon","Kahit ilang beses mo gusto","Isang beses bawat limang taon","Isang beses bawat tatlong taon"],"h1":"Hindi mo ito magagamit taon-taon. Ilang taon ang paghihintay.","h2":"Sa South Carolina, ang kurso sa defensive driving ay puwedeng magbawas ng mga puntos mo nang isang beses lamang sa loob ng tatlong taon.","p":"Tama. Isang beses bawat tatlong taon."},"ar":{"q":"في South Carolina، كم مرة يمكن استخدام دورة القيادة الوقائية لتقليل النقاط في سجلك؟","o":["مرة في السنة","كلما أردت","مرة كل خمس سنوات","مرة كل ثلاث سنوات"],"h1":"لا يمكنك أن تستخدمها كل سنة. الانتظار بضع سنوات.","h2":"في South Carolina يمكن لدورة القيادة الوقائية أن تقلل نقاطك مرة واحدة فقط في كل فترة ثلاث سنوات.","p":"صحيح. مرة كل ثلاث سنوات."},"ref":{"doc":"SC","page":"1-20"}},{"id":"sc-039","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, what is the penalty for a second offense under the Hands-Free and Distracted Driving Act?","o":["A $200 fine and 2 points on your record","A $100 fine only","A $500 fine and 4 points on your record","A one-year license suspension"],"h1":"The first offense is a $100 fine. The second costs more and also adds points.","h2":"In South Carolina, a second or later hands-free offense brings a $200 fine and two points on your driving record.","p":"Right. $200 and 2 points."},"es":{"q":"En Carolina del Sur, ¿cuál es la sanción por una segunda infracción de la Ley de Manos Libres y Manejo Distraído?","o":["Una multa de $200 y 2 puntos en su historial","Solo una multa de $100","Una multa de $500 y 4 puntos en su historial","La suspensión de la licencia por un año"],"h1":"La primera infracción es una multa de $100. La segunda cuesta más y también suma puntos.","h2":"En Carolina del Sur, una segunda infracción o una posterior de la ley de manos libres trae una multa de $200 y dos puntos en su historial de manejo.","p":"Correcto. $200 y 2 puntos."},"zh":{"q":"在 South Carolina，第二次违反《免提与分心驾驶法》（Hands-Free and Distracted Driving Act），会受到什么处罚？","o":["罚款 $200，记录上加 2 分","只罚款 $100","罚款 $500，记录上加 4 分","吊销驾照一年"],"h1":"第一次违反罚款 $100。第二次罚得更多，还会加分。","h2":"在 South Carolina，第二次或以后违反免提法，会被罚款 $200，驾驶记录上加两分。","p":"对。$200 和 2 分。"},"vi":{"q":"Ở South Carolina, hình phạt cho lần vi phạm thứ hai Luật Rảnh Tay và Lái Xe Mất Tập Trung (Hands-Free and Distracted Driving Act) là gì?","o":["Phạt $200 và 2 điểm trong hồ sơ","Chỉ phạt $100","Phạt $500 và 4 điểm trong hồ sơ","Treo bằng lái một năm"],"h1":"Lần vi phạm đầu bị phạt $100. Lần thứ hai bị phạt nhiều hơn và còn bị cộng điểm.","h2":"Ở South Carolina, lần vi phạm luật rảnh tay thứ hai trở đi bị phạt $200 và bị ghi hai điểm vào hồ sơ lái xe.","p":"Đúng. $200 và 2 điểm."},"tl":{"q":"Sa South Carolina, ano ang parusa sa ikalawang paglabag sa Hands-Free and Distracted Driving Act?","o":["Multang $200 at 2 puntos sa rekord mo","Multang $100 lamang","Multang $500 at 4 na puntos sa rekord mo","Isang taong suspensyon ng lisensya"],"h1":"Multang $100 ang unang paglabag. Mas mahal ang ikalawa at may dagdag pang puntos.","h2":"Sa South Carolina, ang ikalawa o susunod na paglabag sa batas na hands-free ay may multang $200 at dalawang puntos sa rekord mo sa pagmamaneho.","p":"Tama. $200 at 2 puntos."},"ar":{"q":"في South Carolina، ما عقوبة المخالفة الثانية لقانون القيادة بدون استخدام اليدين والقيادة المشتتة (Hands-Free and Distracted Driving Act)؟","o":["غرامة $200 و2 نقطة في سجلك","غرامة $100 فقط","غرامة $500 و4 نقاط في سجلك","إيقاف الرخصة لمدة سنة"],"h1":"المخالفة الأولى غرامتها $100. الثانية تكلف أكثر وتضيف نقاطًا أيضًا.","h2":"في South Carolina، المخالفة الثانية أو ما بعدها لقانون القيادة بدون استخدام اليدين عقوبتها غرامة $200 ونقطتان في سجل القيادة.","p":"صحيح. $200 و2 نقطة."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-040","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, a child may use an adult seat belt (if it fits well) at age 8, or once the child is at least how tall?","o":["48 inches","52 inches","57 inches","62 inches"],"h1":"It is just under 5 feet.","h2":"In South Carolina, a child who is at least 8 years old or at least 57 inches tall may use an adult seat belt if it fits properly.","p":"Right. 57 inches tall."},"es":{"q":"En Carolina del Sur, un niño puede usar el cinturón de seguridad de adulto (si le queda bien) a los 8 años, o cuando mide por lo menos ¿cuánto?","o":["48 pulgadas","52 pulgadas","57 pulgadas","62 pulgadas"],"h1":"Es un poco menos de 5 pies.","h2":"En Carolina del Sur, un niño de por lo menos 8 años o que mide por lo menos 57 pulgadas puede usar el cinturón de seguridad de adulto si le queda bien.","p":"Correcto. 57 pulgadas de estatura."},"zh":{"q":"在 South Carolina，孩子满 8 岁，或身高至少多少时，可以使用成人安全带（如果安全带合身）？","o":["48 英寸","52 英寸","57 英寸","62 英寸"],"h1":"比 5 英尺稍矮一点。","h2":"在 South Carolina，至少 8 岁或身高至少 57 英寸的孩子，如果成人安全带合身，就可以使用。","p":"对。身高 57 英寸。"},"vi":{"q":"Ở South Carolina, trẻ em được dùng dây an toàn của người lớn (nếu vừa vặn) khi 8 tuổi, hoặc khi cao ít nhất bao nhiêu?","o":["48 inch","52 inch","57 inch","62 inch"],"h1":"Hơi thấp hơn 5 feet một chút.","h2":"Ở South Carolina, trẻ em ít nhất 8 tuổi hoặc cao ít nhất 57 inch được dùng dây an toàn của người lớn nếu dây vừa vặn.","p":"Đúng. Cao 57 inch."},"tl":{"q":"Sa South Carolina, puwedeng gumamit ng seat belt ng adulto (kung bagay ito nang maayos) ang bata sa edad na 8, o kapag ang taas niya ay hindi bababa sa ilan?","o":["48 pulgada","52 pulgada","57 pulgada","62 pulgada"],"h1":"Kaunti lang ang kulang sa 5 talampakan.","h2":"Sa South Carolina, ang batang hindi bababa sa 8 taong gulang o hindi bababa sa 57 pulgada ang taas ay puwedeng gumamit ng seat belt ng adulto kung bagay ito nang maayos.","p":"Tama. 57 pulgada ang taas."},"ar":{"q":"في South Carolina، يمكن للطفل أن يستخدم حزام الأمان الخاص بالكبار (إذا كان مناسبًا له) في عمر 8 سنوات، أو عندما يصل طوله على الأقل إلى كم؟","o":["48 بوصة","52 بوصة","57 بوصة","62 بوصة"],"h1":"أقل قليلًا من 5 أقدام.","h2":"في South Carolina، الطفل الذي عمره 8 سنوات على الأقل أو طوله 57 بوصة على الأقل يمكنه أن يستخدم حزام الأمان الخاص بالكبار إذا كان مناسبًا له.","p":"صحيح. طوله 57 بوصة."},"ref":{"doc":"SC","page":"4-7"}},{"id":"sc-041","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, how far does the driver's manual say a loaded truck going 55 mph needs to stop, at the least, in ideal conditions?","o":["100 feet","158 feet","200 feet","335 feet"],"h1":"It is more than one and a half times what a car needs.","h2":"South Carolina's manual says a loaded truck at 55 mph needs at least 335 feet to stop, even in ideal conditions, so never cut in front of one.","p":"Right. At least 335 feet."},"es":{"q":"En Carolina del Sur, según el manual, ¿qué distancia necesita como mínimo un camión cargado que va a 55 mph para detenerse en condiciones ideales?","o":["100 pies","158 pies","200 pies","335 pies"],"h1":"Es más de una vez y media lo que necesita un carro.","h2":"El manual de Carolina del Sur dice que un camión cargado a 55 mph necesita por lo menos 335 pies para detenerse, aun en condiciones ideales, así que nunca se meta delante de uno.","p":"Correcto. Por lo menos 335 pies."},"zh":{"q":"在 South Carolina，驾驶手册说，一辆以 55 mph 行驶的满载卡车，在理想条件下至少需要多长距离才能停下？","o":["100 英尺","158 英尺","200 英尺","335 英尺"],"h1":"是汽车所需距离的一倍半以上。","h2":"South Carolina 的手册说，满载卡车以 55 mph 行驶时，即使在理想条件下也至少需要 335 英尺才能停下，所以绝不要突然插到卡车前面。","p":"对。至少 335 英尺。"},"vi":{"q":"Ở South Carolina, sách hướng dẫn lái xe nói một xe tải chở đầy hàng chạy 55 mph cần ít nhất bao xa để dừng lại trong điều kiện lý tưởng?","o":["100 feet","158 feet","200 feet","335 feet"],"h1":"Hơn một lần rưỡi khoảng cách mà một xe hơi cần.","h2":"Sách hướng dẫn của South Carolina nói xe tải chở đầy hàng chạy 55 mph cần ít nhất 335 feet để dừng lại, ngay cả trong điều kiện lý tưởng, vì vậy đừng bao giờ chen ngang trước xe tải.","p":"Đúng. Ít nhất 335 feet."},"tl":{"q":"Sa South Carolina, ayon sa manual sa pagmamaneho, gaano kalayo ang kailangan, hindi bababa, ng isang trak na may karga na tumatakbo nang 55 mph para huminto sa pinakamagandang kondisyon?","o":["100 talampakan","158 talampakan","200 talampakan","335 talampakan"],"h1":"Higit ito sa isa't kalahating beses ng kailangan ng kotse.","h2":"Sinasabi ng manual ng South Carolina na ang trak na may karga sa 55 mph ay nangangailangan ng hindi bababa sa 335 talampakan para huminto, kahit sa pinakamagandang kondisyon, kaya huwag kailanman sumingit sa harap nito.","p":"Tama. Hindi bababa sa 335 talampakan."},"ar":{"q":"في South Carolina، حسب دليل القيادة، ما أقل مسافة تحتاجها شاحنة محمّلة تسير بسرعة 55 mph لتتوقف في ظروف مثالية؟","o":["100 قدم","158 قدمًا","200 قدم","335 قدمًا"],"h1":"إنها أكثر من مرة ونصف من المسافة التي تحتاجها السيارة.","h2":"دليل South Carolina يقول إن الشاحنة المحمّلة بسرعة 55 mph تحتاج 335 قدمًا على الأقل لتتوقف، حتى في الظروف المثالية، لذلك يجب ألّا تدخل أمامها فجأة أبدًا.","p":"صحيح. 335 قدمًا على الأقل."},"ref":{"doc":"SC","page":"10-9"}},{"id":"sc-042","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, an officer gives you a traffic ticket. Must you sign it?","o":["Yes, or you will be arrested","No, South Carolina does not require you to sign it","Yes, and signing means you admit you are guilty","Only if you want to go to court"],"h1":"In South Carolina, taking the ticket is not an admission of guilt, and there is no signature rule.","h2":"In South Carolina, a driver does not have to sign a traffic ticket, and accepting the ticket does not mean you admit guilt.","p":"Right. No signature is required in South Carolina."},"es":{"q":"En Carolina del Sur, un oficial le da una multa de tránsito. ¿Tiene que firmarla?","o":["Sí, o lo arrestarán","No, Carolina del Sur no exige que la firme","Sí, y firmar significa que admite que es culpable","Solo si quiere ir a la corte"],"h1":"En Carolina del Sur, recibir la multa no es admitir la culpa, y no hay una regla de firma.","h2":"En Carolina del Sur, el conductor no tiene que firmar una multa de tránsito, y aceptar la multa no significa que admite la culpa.","p":"Correcto. En Carolina del Sur no se exige la firma."},"zh":{"q":"在 South Carolina，警察给你开了一张交通罚单。你必须签字吗？","o":["必须，否则你会被逮捕","不必，South Carolina 不要求你签字","必须，而且签字表示你承认有罪","只有你想上法庭时才要签"],"h1":"在 South Carolina，接受罚单不等于承认有罪，也没有签字的规定。","h2":"在 South Carolina，司机不必在交通罚单上签字，接受罚单也不表示你承认有罪。","p":"对。在 South Carolina 不需要签字。"},"vi":{"q":"Ở South Carolina, cảnh sát đưa bạn giấy phạt giao thông. Bạn có phải ký tên không?","o":["Có, nếu không bạn sẽ bị bắt","Không, South Carolina không bắt buộc bạn ký","Có, và ký tên nghĩa là bạn nhận mình có lỗi","Chỉ khi bạn muốn ra tòa"],"h1":"Ở South Carolina, nhận giấy phạt không phải là nhận lỗi, và không có quy định phải ký tên.","h2":"Ở South Carolina, người lái không phải ký tên vào giấy phạt giao thông, và nhận giấy phạt không có nghĩa là bạn nhận mình có lỗi.","p":"Đúng. Ở South Carolina không cần ký tên."},"tl":{"q":"Sa South Carolina, binigyan ka ng pulis ng tiket sa trapiko. Kailangan mo ba itong pirmahan?","o":["Oo, o aarestuhin ka","Hindi, hindi ito hinihingi ng South Carolina","Oo, at ang pagpirma ay pag-amin na nagkasala ka","Kung gusto mo lamang pumunta sa korte"],"h1":"Sa South Carolina, ang pagtanggap ng tiket ay hindi pag-amin ng kasalanan, at walang patakaran sa pagpirma.","h2":"Sa South Carolina, hindi kailangang pirmahan ng drayber ang tiket sa trapiko, at ang pagtanggap ng tiket ay hindi nangangahulugang inaamin mo ang kasalanan.","p":"Tama. Hindi kailangan ang pirma sa South Carolina."},"ar":{"q":"في South Carolina، أعطاك ضابط مخالفة مرورية. هل عليك أن توقّعها؟","o":["نعم، وإلا سيتم القبض عليك","لا، South Carolina لا تطلب منك أن توقّعها","نعم، والتوقيع يعني أنك تعترف بالذنب","فقط إذا أردت أن تذهب إلى المحكمة"],"h1":"في South Carolina، أخذ المخالفة ليس اعترافًا بالذنب، ولا توجد قاعدة للتوقيع.","h2":"في South Carolina ليس على السائق أن يوقّع المخالفة المرورية، وقبول المخالفة لا يعني أنك تعترف بالذنب.","p":"صحيح. التوقيع غير مطلوب في South Carolina."},"ref":{"doc":"SC","page":"10-13"}},{"id":"sc-043","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, how does the driver's manual say the cargo weight in a trailer should be split?","o":["60 percent in the front and 40 percent in the back","Half in the front and half in the back","40 percent in the front and 60 percent in the back","All of it at the very back"],"h1":"A trailer that is heavier in the back is more likely to sway.","h2":"South Carolina's manual says to load a trailer heavier in the front: about 60 percent of the weight in the front and 40 percent in the back.","p":"Right. 60 percent front, 40 percent back."},"es":{"q":"En Carolina del Sur, según el manual, ¿cómo se debe repartir el peso de la carga en un remolque?","o":["60 por ciento adelante y 40 por ciento atrás","La mitad adelante y la mitad atrás","40 por ciento adelante y 60 por ciento atrás","Todo bien atrás"],"h1":"Un remolque más pesado atrás tiene más riesgo de balancearse.","h2":"El manual de Carolina del Sur dice que el remolque debe ir más pesado adelante: cerca del 60 por ciento del peso adelante y el 40 por ciento atrás.","p":"Correcto. 60 por ciento adelante, 40 por ciento atrás."},"zh":{"q":"在 South Carolina，驾驶手册说拖车里货物的重量应该怎样分配？","o":["前面 60%，后面 40%","前面一半，后面一半","前面 40%，后面 60%","全部放在最后面"],"h1":"后面比较重的拖车更容易摇摆。","h2":"South Carolina 的手册说，拖车要装得前面重一些：大约 60% 的重量在前面，40% 在后面。","p":"对。前面 60%，后面 40%。"},"vi":{"q":"Ở South Carolina, sách hướng dẫn lái xe nói trọng lượng hàng trong rơ-moóc nên được chia thế nào?","o":["60 phần trăm ở phía trước và 40 phần trăm ở phía sau","Một nửa phía trước và một nửa phía sau","40 phần trăm ở phía trước và 60 phần trăm ở phía sau","Tất cả ở tận phía sau"],"h1":"Rơ-moóc nặng phía sau dễ bị lắc lư hơn.","h2":"Sách hướng dẫn của South Carolina nói rơ-moóc phải nặng hơn ở phía trước: khoảng 60 phần trăm trọng lượng ở phía trước và 40 phần trăm ở phía sau.","p":"Đúng. 60 phần trăm phía trước, 40 phần trăm phía sau."},"tl":{"q":"Sa South Carolina, ayon sa manual sa pagmamaneho, paano dapat hatiin ang bigat ng karga sa trailer?","o":["60 porsiyento sa harap at 40 porsiyento sa likod","Kalahati sa harap at kalahati sa likod","40 porsiyento sa harap at 60 porsiyento sa likod","Lahat sa pinakalikod"],"h1":"Mas malamang na umuga ang trailer na mas mabigat sa likod.","h2":"Sinasabi ng manual ng South Carolina na kargahan ang trailer nang mas mabigat sa harap: mga 60 porsiyento ng bigat sa harap at 40 porsiyento sa likod.","p":"Tama. 60 porsiyento sa harap, 40 porsiyento sa likod."},"ar":{"q":"في South Carolina، حسب دليل القيادة، كيف يجب توزيع وزن الحمولة في المقطورة؟","o":["60 بالمئة في الأمام و40 بالمئة في الخلف","النصف في الأمام والنصف في الخلف","40 بالمئة في الأمام و60 بالمئة في الخلف","كله في آخر الخلف"],"h1":"المقطورة الأثقل من الخلف تتمايل أكثر.","h2":"دليل South Carolina يقول أن تحمّل المقطورة بحيث تكون أثقل من الأمام: حوالي 60 بالمئة من الوزن في الأمام و40 بالمئة في الخلف.","p":"صحيح. 60 بالمئة في الأمام، و40 بالمئة في الخلف."},"ref":{"doc":"SC","page":"11-10"}},{"id":"sc-044","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, a golf cart with a permit may be driven in the daytime on secondary roads with a posted speed limit of at most what?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Golf carts are slow, so they stay on slower roads.","h2":"In South Carolina, a permitted golf cart may be driven in the daytime only on secondary roads with a posted speed limit of 35 mph or less.","p":"Right. 35 mph or less."},"es":{"q":"En Carolina del Sur, un carrito de golf con permiso puede circular de día en carreteras secundarias con un límite de velocidad de ¿cuánto como máximo?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Los carritos de golf son lentos, así que van por calles más lentas.","h2":"En Carolina del Sur, un carrito de golf con permiso puede circular de día solo en carreteras secundarias con un límite de velocidad de 35 mph o menos.","p":"Correcto. 35 mph o menos."},"zh":{"q":"在 South Carolina，有许可证的高尔夫球车白天可以在限速最高多少的次要道路上行驶？","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"高尔夫球车很慢，所以只走比较慢的道路。","h2":"在 South Carolina，有许可证的高尔夫球车只能在白天、在限速 35 mph 或以下的次要道路上行驶。","p":"对。35 mph 或以下。"},"vi":{"q":"Ở South Carolina, xe golf có giấy phép được chạy ban ngày trên đường phụ có biển tốc độ tối đa cao nhất là bao nhiêu?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Xe golf chạy chậm, nên chỉ đi trên đường chậm hơn.","h2":"Ở South Carolina, xe golf có giấy phép chỉ được chạy ban ngày trên đường phụ có biển tốc độ tối đa 35 mph hoặc thấp hơn.","p":"Đúng. 35 mph hoặc thấp hơn."},"tl":{"q":"Sa South Carolina, ang golf cart na may permit ay puwedeng imaneho sa araw sa mga secondary road na may nakapaskil na speed limit na hanggang ilan lamang?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Mabagal ang golf cart, kaya sa mas mabagal na daan lamang ito.","h2":"Sa South Carolina, ang golf cart na may permit ay puwedeng imaneho sa araw lamang sa mga secondary road na may nakapaskil na speed limit na 35 mph o mas mababa.","p":"Tama. 35 mph o mas mababa."},"ar":{"q":"في South Carolina، يمكن قيادة عربة الغولف التي لها تصريح في النهار على الطرق الفرعية التي حد السرعة المكتوب فيها كم على الأكثر؟","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"عربات الغولف بطيئة، لذلك تبقى على الطرق الأبطأ.","h2":"في South Carolina يمكن قيادة عربة الغولف التي لها تصريح في النهار فقط على الطرق الفرعية التي حد السرعة المكتوب فيها 35 mph أو أقل.","p":"صحيح. 35 mph أو أقل."},"ref":{"doc":"SC","page":"2-3"}},{"id":"sc-045","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, when you park along a road, how far from the curb or edge of the pavement may your car be, at the most?","o":["6 inches","12 inches","24 inches","18 inches"],"h1":"Park as close to the curb as you can. The legal limit is less than two feet.","h2":"In South Carolina, when you park along the road, your car must be no more than 18 inches from the curb or the edge of the pavement.","p":"Right. No more than 18 inches."},"es":{"q":"En Carolina del Sur, cuando se estaciona junto a la calle, ¿a qué distancia máxima de la acera o del borde del pavimento puede quedar su carro?","o":["6 pulgadas","12 pulgadas","24 pulgadas","18 pulgadas"],"h1":"Estaciónese lo más cerca posible de la acera. El límite legal es menos de dos pies.","h2":"En Carolina del Sur, cuando se estaciona junto a la calle, su carro debe quedar a no más de 18 pulgadas de la acera o del borde del pavimento.","p":"Correcto. No más de 18 pulgadas."},"zh":{"q":"在 South Carolina，当你在路边停车时，你的车离路缘或路面边缘最远可以有多远？","o":["6 英寸","12 英寸","24 英寸","18 英寸"],"h1":"尽量靠近路缘停车。法律规定的上限不到两英尺。","h2":"在 South Carolina，在路边停车时，你的车离路缘或路面边缘不能超过 18 英寸。","p":"对。不超过 18 英寸。"},"vi":{"q":"Ở South Carolina, khi đậu xe dọc theo đường, xe của bạn được cách lề đường hoặc mép mặt đường xa nhất là bao nhiêu?","o":["6 inch","12 inch","24 inch","18 inch"],"h1":"Hãy đậu xe sát lề đường nhất có thể. Giới hạn theo luật là chưa đến hai feet.","h2":"Ở South Carolina, khi đậu xe dọc theo đường, xe của bạn phải cách lề đường hoặc mép mặt đường không quá 18 inch.","p":"Đúng. Không quá 18 inch."},"tl":{"q":"Sa South Carolina, kapag pumarada ka sa tabi ng daan, gaano kalayo, pinakamalayo na, ang kotse mo mula sa gilid ng bangketa o gilid ng sementadong daan?","o":["6 pulgada","12 pulgada","24 pulgada","18 pulgada"],"h1":"Pumarada nang pinakamalapit hangga't kaya sa gilid ng bangketa. Kulang sa dalawang talampakan ang limitasyon ng batas.","h2":"Sa South Carolina, kapag pumarada ka sa tabi ng daan, ang kotse mo ay dapat hindi hihigit sa 18 pulgada mula sa gilid ng bangketa o gilid ng sementadong daan.","p":"Tama. Hindi hihigit sa 18 pulgada."},"ar":{"q":"في South Carolina، عندما تركن سيارتك بجانب الطريق، ما أبعد مسافة يمكن أن تكون بين سيارتك والرصيف أو حافة الطريق المرصوف؟","o":["6 بوصات","12 بوصة","24 بوصة","18 بوصة"],"h1":"اركن أقرب ما يمكن إلى الرصيف. الحد القانوني أقل من قدمين.","h2":"في South Carolina، عندما تركن بجانب الطريق، يجب ألّا تكون سيارتك أبعد من 18 بوصة عن الرصيف أو حافة الطريق المرصوف.","p":"صحيح. ليس أكثر من 18 بوصة."},"ref":{"doc":"SC","page":"7-11"}},{"id":"sc-046","scope":"SC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Carolina, what does the driver's manual say is the highest recommended speed for most cars towing a trailer?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is lower than most interstate limits.","h2":"South Carolina's manual says the highest recommended speed for most vehicles towing a trailer is 55 mph, and never more than the posted limit.","p":"Right. 55 mph."},"es":{"q":"En Carolina del Sur, según el manual, ¿cuál es la velocidad máxima recomendada para la mayoría de los vehículos que llevan un remolque?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es menor que la mayoría de los límites de las autopistas interestatales.","h2":"El manual de Carolina del Sur dice que la velocidad máxima recomendada para la mayoría de los vehículos con remolque es 55 mph, y nunca más que el límite indicado.","p":"Correcto. 55 mph."},"zh":{"q":"在 South Carolina，驾驶手册说大多数拖着拖车的汽车，建议的最高车速是多少？","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"比大多数州际公路的限速低。","h2":"South Carolina 的手册说，大多数拖着拖车的车辆，建议的最高车速是 55 mph，而且绝不能超过标示的限速。","p":"对。55 mph。"},"vi":{"q":"Ở South Carolina, sách hướng dẫn lái xe nói tốc độ cao nhất được khuyên dùng cho hầu hết xe đang kéo rơ-moóc là bao nhiêu?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Thấp hơn giới hạn tốc độ của hầu hết xa lộ liên bang.","h2":"Sách hướng dẫn của South Carolina nói tốc độ cao nhất được khuyên dùng cho hầu hết xe kéo rơ-moóc là 55 mph, và không bao giờ vượt quá tốc độ tối đa trên biển báo.","p":"Đúng. 55 mph."},"tl":{"q":"Sa South Carolina, ayon sa manual sa pagmamaneho, ano ang pinakamataas na inirerekomendang bilis para sa karamihan ng kotseng humihila ng trailer?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Mas mababa ito sa karamihan ng speed limit sa interstate.","h2":"Sinasabi ng manual ng South Carolina na ang pinakamataas na inirerekomendang bilis para sa karamihan ng sasakyang humihila ng trailer ay 55 mph, at hindi kailanman lampas sa nakapaskil na limitasyon.","p":"Tama. 55 mph."},"ar":{"q":"في South Carolina، حسب دليل القيادة، ما أعلى سرعة يُنصح بها لمعظم السيارات التي تسحب مقطورة؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"إنها أقل من حدود السرعة على معظم الطرق السريعة بين الولايات.","h2":"دليل South Carolina يقول إن أعلى سرعة يُنصح بها لمعظم المركبات التي تسحب مقطورة هي 55 mph، وليس أكثر من الحد المكتوب أبدًا.","p":"صحيح. 55 mph."},"ref":{"doc":"SC","page":"11-11"}},{"id":"sc-047","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, a school bus is stopped in a loading zone completely off the main road, and people may not cross the road there. Must you stop?","o":["Yes, you must always stop for a stopped school bus","Yes, and wait until the bus drives away","Yes, but only if its lights are amber","No, you do not have to stop, but drive with care"],"h1":"The bus is fully out of the travel lanes and no one crosses in front of you.","h2":"In South Carolina, you do not have to stop for a school bus that is in a loading zone completely off the main travel lanes when people are not allowed to cross the road.","p":"Right. You do not have to stop there."},"es":{"q":"En Carolina del Sur, un autobús escolar está detenido en una zona de carga completamente fuera de la vía principal, y allí no se permite cruzar la calle. ¿Debe detenerse?","o":["Sí, siempre debe detenerse ante un autobús escolar detenido","Sí, y esperar hasta que el autobús se vaya","Sí, pero solo si sus luces son ámbar","No, no tiene que detenerse, pero maneje con cuidado"],"h1":"El autobús está totalmente fuera de los carriles y nadie cruza delante de usted.","h2":"En Carolina del Sur, no tiene que detenerse ante un autobús escolar que está en una zona de carga completamente fuera de los carriles principales cuando no se permite que la gente cruce la calle.","p":"Correcto. Allí no tiene que detenerse."},"zh":{"q":"在 South Carolina，一辆校车停在完全离开主路的上下车区，那里的人不准过马路。你必须停车吗？","o":["必须，遇到停着的校车一定要停","必须，而且要等校车开走","必须，但只在它亮黄灯时","不必停车，但要小心驾驶"],"h1":"校车完全在行车道外面，也没有人在你前面过马路。","h2":"在 South Carolina，如果校车停在完全离开主行车道的上下车区，而且不准行人过马路，你就不必停车。","p":"对。在那里你不必停车。"},"vi":{"q":"Ở South Carolina, một xe buýt trường học dừng trong khu vực đón trả học sinh hoàn toàn nằm ngoài đường chính, và người ta không được băng qua đường ở đó. Bạn có phải dừng lại không?","o":["Có, bạn luôn phải dừng khi gặp xe buýt trường học đang dừng","Có, và chờ đến khi xe buýt chạy đi","Có, nhưng chỉ khi đèn của nó màu vàng","Không, bạn không phải dừng, nhưng hãy lái cẩn thận"],"h1":"Xe buýt nằm hoàn toàn ngoài các làn xe chạy và không ai băng qua trước mặt bạn.","h2":"Ở South Carolina, bạn không phải dừng lại khi xe buýt trường học ở trong khu vực đón trả hoàn toàn ngoài các làn xe chính và người ta không được phép băng qua đường.","p":"Đúng. Ở đó bạn không phải dừng lại."},"tl":{"q":"Sa South Carolina, nakahinto ang isang school bus sa loading zone na ganap na nasa labas ng pangunahing daan, at hindi puwedeng tumawid ng daan ang mga tao roon. Dapat ka bang huminto?","o":["Oo, dapat kang laging huminto sa nakahintong school bus","Oo, at maghintay hanggang umalis ang bus","Oo, pero kung kulay amber lamang ang ilaw nito","Hindi, hindi mo kailangang huminto, pero magmaneho nang maingat"],"h1":"Ganap na nasa labas ng mga linya ng daanan ang bus at walang tumatawid sa harap mo.","h2":"Sa South Carolina, hindi mo kailangang huminto para sa school bus na nasa loading zone na ganap na nasa labas ng mga pangunahing linya ng daanan kapag hindi pinapayagang tumawid ng daan ang mga tao.","p":"Tama. Hindi mo kailangang huminto roon."},"ar":{"q":"في South Carolina، حافلة مدرسية متوقفة في منطقة تحميل خارج الطريق الرئيسي تمامًا، ولا يُسمح للناس بعبور الطريق هناك. هل يجب أن تتوقف؟","o":["نعم، يجب أن تتوقف دائمًا عند حافلة مدرسية متوقفة","نعم، وتنتظر حتى تتحرك الحافلة","نعم، لكن فقط إذا كانت أضواؤها كهرمانية","لا، ليس عليك أن تتوقف، لكن قُد بحذر"],"h1":"الحافلة خارج مسارات السير تمامًا، ولا أحد يعبر أمامك.","h2":"في South Carolina ليس عليك أن تتوقف عند حافلة مدرسية في منطقة تحميل خارج مسارات السير الرئيسية تمامًا عندما لا يُسمح للناس بعبور الطريق.","p":"صحيح. ليس عليك أن تتوقف هناك."},"ref":{"doc":"SC","page":"7-9"}},{"id":"sc-048","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, two cars come to a narrow single-lane bridge from opposite ends. Who generally goes first?","o":["The larger vehicle","The driver on the right","The driver who reaches the bridge first","The driver going faster"],"h1":"Drivers take turns, and arrival order decides.","h2":"In South Carolina, drivers take turns on a single-lane bridge, and generally the driver who reaches the bridge first has the right of way.","p":"Right. The first one to the bridge goes first."},"es":{"q":"En Carolina del Sur, dos carros llegan a un puente angosto de un solo carril desde lados opuestos. ¿Quién pasa primero, por lo general?","o":["El vehículo más grande","El conductor de la derecha","El conductor que llega primero al puente","El conductor que va más rápido"],"h1":"Los conductores toman turnos, y el orden de llegada decide.","h2":"En Carolina del Sur, los conductores toman turnos en un puente de un solo carril, y por lo general el conductor que llega primero al puente tiene el derecho de paso.","p":"Correcto. El primero en llegar al puente pasa primero."},"zh":{"q":"在 South Carolina，两辆车从两头来到一座很窄的单车道桥。一般由谁先过？","o":["比较大的车","右边的司机","先到桥的司机","开得比较快的司机"],"h1":"司机轮流通过，看谁先到。","h2":"在 South Carolina，司机在单车道桥上要轮流通过，一般先到桥的司机有先行权。","p":"对。先到桥的人先过。"},"vi":{"q":"Ở South Carolina, hai xe đến một cây cầu hẹp chỉ có một làn từ hai đầu ngược nhau. Thường thì ai được đi trước?","o":["Xe lớn hơn","Người lái bên phải","Người lái đến cầu trước","Người lái chạy nhanh hơn"],"h1":"Người lái thay phiên nhau, và thứ tự đến sẽ quyết định.","h2":"Ở South Carolina, người lái thay phiên nhau qua cầu một làn, và thường thì người lái đến cầu trước có quyền ưu tiên.","p":"Đúng. Ai đến cầu trước thì đi trước."},"tl":{"q":"Sa South Carolina, dalawang kotse ang dumating sa makitid na tulay na isa lang ang linya mula sa magkabilang dulo. Sino ang karaniwang mauuna?","o":["Ang mas malaking sasakyan","Ang drayber sa kanan","Ang drayber na unang dumating sa tulay","Ang drayber na mas mabilis"],"h1":"Nagsasalitan ang mga drayber, at ang pagkakasunod ng pagdating ang nagpapasya.","h2":"Sa South Carolina, nagsasalitan ang mga drayber sa tulay na isa lang ang linya, at karaniwang ang drayber na unang dumating sa tulay ang may karapatang dumaan.","p":"Tama. Ang unang dumating sa tulay ang mauuna."},"ar":{"q":"في South Carolina، سيارتان تصلان إلى جسر ضيق بمسار واحد من طرفين متقابلين. من يمر أولًا في العادة؟","o":["المركبة الأكبر","السائق الذي على اليمين","السائق الذي يصل إلى الجسر أولًا","السائق الأسرع"],"h1":"السائقون يتناوبون، وترتيب الوصول هو الذي يقرر.","h2":"في South Carolina يتناوب السائقون على الجسر ذي المسار الواحد، وفي العادة السائق الذي يصل إلى الجسر أولًا له حق الأولوية.","p":"صحيح. من يصل إلى الجسر أولًا يمر أولًا."},"ref":{"doc":"SC","page":"11-5"}},{"id":"sc-049","scope":"SC","cat":"signals","sign":null,"c":1,"en":{"q":"In South Carolina, on a secondary road marker, what does the first number after the letter S show?","o":["The speed limit","The number of the county the road is in","The miles to the next town","The number of lanes"],"h1":"Each county has its own set of secondary road numbers.","h2":"In South Carolina, the first number after the letter S on a secondary road marker is the number of the county, and the last number is the road number.","p":"Right. It shows the county."},"es":{"q":"En Carolina del Sur, en un marcador de carretera secundaria, ¿qué indica el primer número después de la letra S?","o":["El límite de velocidad","El número del condado donde está la carretera","Las millas hasta el próximo pueblo","El número de carriles"],"h1":"Cada condado tiene su propio grupo de números de carreteras secundarias.","h2":"En Carolina del Sur, el primer número después de la letra S en un marcador de carretera secundaria es el número del condado, y el último número es el número de la carretera.","p":"Correcto. Indica el condado."},"zh":{"q":"在 South Carolina，次要道路标志上字母 S 后面的第一个数字表示什么？","o":["限速","这条路所在县的编号","到下一个镇的英里数","车道数"],"h1":"每个县都有自己的一组次要道路编号。","h2":"在 South Carolina，次要道路标志上字母 S 后面的第一个数字是县的编号，最后一个数字是道路编号。","p":"对。它表示县。"},"vi":{"q":"Ở South Carolina, trên bảng số đường phụ, số đầu tiên sau chữ S cho biết điều gì?","o":["Tốc độ tối đa","Số của quận nơi con đường nằm","Số dặm đến thị trấn kế tiếp","Số làn xe"],"h1":"Mỗi quận có một bộ số đường phụ riêng.","h2":"Ở South Carolina, số đầu tiên sau chữ S trên bảng số đường phụ là số của quận, và số cuối cùng là số của con đường.","p":"Đúng. Nó cho biết quận."},"tl":{"q":"Sa South Carolina, sa marker ng secondary road, ano ang ipinapakita ng unang numero pagkatapos ng letrang S?","o":["Ang speed limit","Ang numero ng county kung saan naroon ang daan","Ang milya papunta sa susunod na bayan","Ang bilang ng mga linya"],"h1":"Bawat county ay may sariling grupo ng numero ng secondary road.","h2":"Sa South Carolina, ang unang numero pagkatapos ng letrang S sa marker ng secondary road ay ang numero ng county, at ang huling numero ay ang numero ng daan.","p":"Tama. Ipinapakita nito ang county."},"ar":{"q":"في South Carolina، على علامة الطريق الفرعي، ماذا يبيّن الرقم الأول بعد الحرف S؟","o":["حد السرعة","رقم المقاطعة التي فيها الطريق","عدد الأميال إلى البلدة التالية","عدد المسارات"],"h1":"لكل مقاطعة مجموعتها الخاصة من أرقام الطرق الفرعية.","h2":"في South Carolina، الرقم الأول بعد الحرف S على علامة الطريق الفرعي هو رقم المقاطعة، والرقم الأخير هو رقم الطريق.","p":"صحيح. إنه يبيّن المقاطعة."},"ref":{"doc":"SC","page":"6-11"}},{"id":"sc-050","scope":"SC","cat":"signals","sign":null,"c":2,"en":{"q":"In South Carolina, a farm vehicle has an orange and red triangle on its back. What does it tell you about its speed?","o":["It goes less than 15 mph","It goes less than 45 mph","It goes less than 25 mph","It is stopped"],"h1":"It is a slow-moving vehicle sign. The speed is about the limit on many neighborhood streets.","h2":"In South Carolina, an orange and red triangle on the back of a vehicle means it travels at less than 25 mph, so pass only when it is safe.","p":"Right. Less than 25 mph."},"es":{"q":"En Carolina del Sur, un vehículo agrícola tiene un triángulo anaranjado y rojo en la parte de atrás. ¿Qué le indica sobre su velocidad?","o":["Va a menos de 15 mph","Va a menos de 45 mph","Va a menos de 25 mph","Está detenido"],"h1":"Es la señal de vehículo lento. La velocidad es parecida al límite de muchas calles de barrio.","h2":"En Carolina del Sur, un triángulo anaranjado y rojo en la parte de atrás de un vehículo significa que va a menos de 25 mph, así que adelántelo solo cuando sea seguro.","p":"Correcto. A menos de 25 mph."},"zh":{"q":"在 South Carolina，一辆农用车后面有一个橙色和红色的三角形。它告诉你这辆车的速度是多少？","o":["时速低于 15 mph","时速低于 45 mph","时速低于 25 mph","它停着不动"],"h1":"这是慢行车辆标志。这个速度和很多住宅区街道的限速差不多。","h2":"在 South Carolina，车辆后面的橙色和红色三角形表示这辆车的时速低于 25 mph，所以只在安全时才超车。","p":"对。低于 25 mph。"},"vi":{"q":"Ở South Carolina, một xe nông nghiệp có hình tam giác màu cam và đỏ ở phía sau. Nó cho bạn biết gì về tốc độ của xe?","o":["Xe chạy dưới 15 mph","Xe chạy dưới 45 mph","Xe chạy dưới 25 mph","Xe đang dừng"],"h1":"Đây là biển xe chạy chậm. Tốc độ này gần bằng giới hạn trên nhiều đường trong khu dân cư.","h2":"Ở South Carolina, hình tam giác màu cam và đỏ ở phía sau xe có nghĩa là xe chạy dưới 25 mph, vì vậy chỉ vượt khi an toàn.","p":"Đúng. Dưới 25 mph."},"tl":{"q":"Sa South Carolina, may tatsulok na kulay kahel at pula sa likod ng isang sasakyang pansakahan. Ano ang sinasabi nito tungkol sa bilis nito?","o":["Tumatakbo ito nang mas mababa sa 15 mph","Tumatakbo ito nang mas mababa sa 45 mph","Tumatakbo ito nang mas mababa sa 25 mph","Nakahinto ito"],"h1":"Ito ang karatula ng mabagal na sasakyan. Ang bilis ay halos kapareho ng limitasyon sa maraming kalye sa mga komunidad.","h2":"Sa South Carolina, ang tatsulok na kulay kahel at pula sa likod ng sasakyan ay nangangahulugang tumatakbo ito nang mas mababa sa 25 mph, kaya lumampas lamang kapag ligtas.","p":"Tama. Mas mababa sa 25 mph."},"ar":{"q":"في South Carolina، مركبة زراعية عليها مثلث برتقالي وأحمر من الخلف. ماذا يخبرك عن سرعتها؟","o":["تسير بأقل من 15 mph","تسير بأقل من 45 mph","تسير بأقل من 25 mph","إنها متوقفة"],"h1":"إنها علامة المركبة البطيئة. السرعة قريبة من الحد في كثير من شوارع الأحياء.","h2":"في South Carolina، المثلث البرتقالي والأحمر على خلف المركبة يعني أنها تسير بأقل من 25 mph، لذلك تجاوزها فقط عندما يكون ذلك آمنًا.","p":"صحيح. أقل من 25 mph."},"ref":{"doc":"SC","page":"10-16"}},{"id":"sc-051","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, a Class D license lets you drive regular cars and trucks up to what weight?","o":["10,000 pounds","16,000 pounds","26,000 pounds","40,000 pounds"],"h1":"It is the same weight where the larger classes begin.","h2":"In South Carolina, a Class D license covers non-commercial cars and trucks that weigh no more than 26,000 pounds.","p":"Right. Class D goes up to 26,000 pounds."},"es":{"q":"En Carolina del Sur, ¿hasta qué peso puede tener un carro o camioneta común para manejarlo con una licencia Clase D?","o":["10,000 libras","16,000 libras","26,000 libras","40,000 libras"],"h1":"Es el mismo peso donde empiezan las clases más grandes.","h2":"En Carolina del Sur, la licencia Clase D cubre carros y camionetas no comerciales que pesan 26,000 libras o menos.","p":"Correcto. La Clase D llega hasta 26,000 libras."},"ref":{"doc":"SC","page":"1-1"}},{"id":"sc-052","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, which license class is for a non-commercial single vehicle over 26,000 pounds, such as a large motor home with no trailer?","o":["Class E","Class D","Class G","Class M"],"h1":"It comes right after the regular car class in the alphabet.","h2":"In South Carolina, a Class E license is for non-commercial single vehicles over 26,000 pounds, like big trucks and motor homes.","p":"Right. A large single vehicle like that needs Class E."},"es":{"q":"En Carolina del Sur, ¿qué clase de licencia es para un vehículo no comercial de una sola unidad de más de 26,000 libras, como una casa rodante grande sin remolque?","o":["Clase E","Clase D","Clase G","Clase M"],"h1":"Viene justo después de la clase de carro normal en el alfabeto.","h2":"En Carolina del Sur, la licencia Clase E es para vehículos no comerciales de una sola unidad de más de 26,000 libras, como camiones grandes y casas rodantes.","p":"Correcto. Un vehículo grande así necesita la Clase E."},"ref":{"doc":"SC","page":"1-2"}},{"id":"sc-053","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, which license class is for a non-commercial combination over 26,000 pounds, such as a motor home towing a car?","o":["Class D","Class F","Class E","Class G"],"h1":"A combination is a vehicle plus something it tows.","h2":"In South Carolina, a Class F license is for non-commercial combination vehicles over 26,000 pounds, like a motor home towing a trailer or car.","p":"Right. Large non-commercial combinations need Class F."},"es":{"q":"En Carolina del Sur, ¿qué clase de licencia es para una combinación no comercial de más de 26,000 libras, como una casa rodante que remolca un carro?","o":["Clase D","Clase F","Clase E","Clase G"],"h1":"Una combinación es un vehículo más algo que remolca.","h2":"En Carolina del Sur, la licencia Clase F es para combinaciones no comerciales de más de 26,000 libras, como una casa rodante que remolca un remolque o un carro.","p":"Correcto. Las combinaciones grandes no comerciales necesitan la Clase F."},"ref":{"doc":"SC","page":"1-2"}},{"id":"sc-054","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, which license class is only for driving a moped?","o":["Class D","Class F","Class M","Class G"],"h1":"It is not the motorcycle class.","h2":"In South Carolina, a Class G license lets you drive a moped, and you can get it at 15.","p":"Right. Class G is the moped license."},"es":{"q":"En Carolina del Sur, ¿qué clase de licencia es solo para manejar un ciclomotor (moped)?","o":["Clase D","Clase F","Clase M","Clase G"],"h1":"No es la clase de motocicleta.","h2":"En Carolina del Sur, la licencia Clase G le permite manejar un ciclomotor, y la puede obtener a los 15 años.","p":"Correcto. La Clase G es la licencia de ciclomotor."},"ref":{"doc":"SC","page":"1-2"}},{"id":"sc-055","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, which license class do you need to drive a two-wheel motorcycle?","o":["Class M","Class D","Class E","Class G"],"h1":"Think of the first letter of the vehicle's name.","h2":"In South Carolina, you need a Class M license to drive a two-wheel motorcycle.","p":"Right. Motorcycles need Class M."},"es":{"q":"En Carolina del Sur, ¿qué clase de licencia necesita para manejar una motocicleta de dos ruedas?","o":["Clase M","Clase D","Clase E","Clase G"],"h1":"Piense en la primera letra de la palabra en inglés (motorcycle).","h2":"En Carolina del Sur, necesita una licencia Clase M para manejar una motocicleta de dos ruedas.","p":"Correcto. Las motocicletas necesitan la Clase M."},"ref":{"doc":"SC","page":"1-2"}},{"id":"sc-056","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, a commercial Class C license covers vehicles made to carry at least how many people, counting the driver?","o":["8","10","16","24"],"h1":"It is more than a large van holds.","h2":"In South Carolina, a commercial Class C license covers vehicles made to carry 16 or more people, including the driver, or vehicles placarded for hazardous materials.","p":"Right. Class C starts at 16 people, counting the driver."},"es":{"q":"En Carolina del Sur, ¿para al menos cuántas personas, contando al conductor, están hechos los vehículos de la licencia comercial Clase C?","o":["8","10","16","24"],"h1":"Es más de lo que cabe en una camioneta grande.","h2":"En Carolina del Sur, la licencia comercial Clase C cubre vehículos hechos para llevar 16 personas o más, contando al conductor, o vehículos marcados para materiales peligrosos.","p":"Correcto. La Clase C empieza en 16 personas, contando al conductor."},"ref":{"doc":"SC","page":"1-3"}},{"id":"sc-057","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you drive both a car and a motorcycle. How many driver's licenses may you hold?","o":["Two licenses, one for each vehicle","One license, endorsed for both classes","One for each vehicle you own","As many as you pass tests for"],"h1":"Having more than one valid license is against the law.","h2":"In South Carolina, you may hold only one driver's license, and it is endorsed for each class you have passed.","p":"Right. One license, with both classes on it."},"es":{"q":"En Carolina del Sur, usted maneja un carro y una motocicleta. ¿Cuántas licencias de manejar puede tener?","o":["Dos licencias, una por cada vehículo","Una sola licencia, con las dos clases","Una por cada vehículo que tenga","Tantas como exámenes apruebe"],"h1":"Tener más de una licencia válida va contra la ley.","h2":"En Carolina del Sur, usted solo puede tener una licencia de manejar, y en ella se anotan todas las clases que haya aprobado.","p":"Correcto. Una sola licencia, con las dos clases."},"ref":{"doc":"SC","page":"1-3"}},{"id":"sc-058","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you are 19 and just got a beginner's permit. How long must you hold it before you apply for your driver's license?","o":["10 days","30 days","90 days","180 days"],"h1":"Adults wait much less than teens.","h2":"In South Carolina, a person 18 or older must hold a beginner's permit for at least 30 days before applying for a driver's license.","p":"Right. At 18 or older, the wait is 30 days."},"es":{"q":"En Carolina del Sur, usted tiene 19 años y acaba de obtener el permiso de principiante. ¿Cuánto tiempo debe tenerlo antes de solicitar su licencia de manejar?","o":["10 días","30 días","90 días","180 días"],"h1":"Los adultos esperan mucho menos que los adolescentes.","h2":"En Carolina del Sur, una persona de 18 años o más debe tener el permiso de principiante al menos 30 días antes de solicitar la licencia de manejar.","p":"Correcto. A los 18 años o más, la espera es de 30 días."},"ref":{"doc":"SC","page":"1-5"}},{"id":"sc-059","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long is the driver's education course a 15- or 16-year-old must pass for a first license?","o":["4 hours in class and 4 hours of driving","6 hours in class and 8 hours of driving","8 hours in class and 6 hours of driving","30 hours in class and 6 hours of driving"],"h1":"The classroom part is a full work day long.","h2":"In South Carolina, the driver's education course for a 15- or 16-year-old has 8 hours in the classroom and 6 hours of driving.","p":"Right. Eight hours in class and six behind the wheel."},"es":{"q":"En Carolina del Sur, ¿cuánto dura el curso de educación vial que debe aprobar un joven de 15 o 16 años para su primera licencia?","o":["4 horas en clase y 4 horas manejando","6 horas en clase y 8 horas manejando","8 horas en clase y 6 horas manejando","30 horas en clase y 6 horas manejando"],"h1":"La parte en el salón dura una jornada de trabajo completa.","h2":"En Carolina del Sur, el curso de educación vial para un joven de 15 o 16 años tiene 8 horas en el salón de clase y 6 horas manejando.","p":"Correcto. Ocho horas en clase y seis al volante."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-060","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a 16-year-old applies for a first license. What must be true about school?","o":["They have graduated from high school","They have a B average or better","School does not matter for a license","They are enrolled, not suspended or expelled, with good attendance"],"h1":"The state links a teen's license to going to school.","h2":"In South Carolina, a 15- or 16-year-old must be enrolled in school, not suspended or expelled, and have satisfactory attendance to get a first license.","p":"Right. The teen must be in school with good attendance."},"es":{"q":"En Carolina del Sur, un joven de 16 años solicita su primera licencia. ¿Qué debe cumplir sobre la escuela?","o":["Haberse graduado de la secundaria","Tener un promedio de B o más","La escuela no importa para la licencia","Estar inscrito, sin suspensión ni expulsión, y con buena asistencia"],"h1":"El estado relaciona la licencia de un adolescente con ir a la escuela.","h2":"En Carolina del Sur, un joven de 15 o 16 años debe estar inscrito en la escuela, sin suspensión ni expulsión, y con asistencia satisfactoria para obtener su primera licencia.","p":"Correcto. Debe estar en la escuela y asistir bien."},"ref":{"doc":"SC","page":"1-6"}},{"id":"sc-061","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, what is the youngest age to get a conditional license?","o":["15","15 and a half","16","16 and a half"],"h1":"It is between the permit age and 16.","h2":"In South Carolina, you can get a conditional license at 15 and a half, if you meet all the requirements.","p":"Right. The conditional license starts at 15 and a half."},"es":{"q":"En Carolina del Sur, ¿cuál es la edad mínima para obtener la licencia condicional?","o":["15 años","15 años y medio","16 años","16 años y medio"],"h1":"Está entre la edad del permiso y los 16 años.","h2":"En Carolina del Sur, usted puede obtener la licencia condicional a los 15 años y medio, si cumple todos los requisitos.","p":"Correcto. La licencia condicional empieza a los 15 años y medio."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-062","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, a teen holds a conditional license with no tickets and no at-fault crashes. When do they earn full driving privileges?","o":["After one year with the conditional license","After 90 days","After six months","Only at age 18"],"h1":"It takes a full clean year.","h2":"In South Carolina, a conditional license holder earns full driving privileges after one year with no traffic offenses and no at-fault collisions.","p":"Right. One clean year brings full privileges."},"es":{"q":"En Carolina del Sur, un adolescente tiene licencia condicional, sin multas y sin choques por su culpa. ¿Cuándo obtiene todos los privilegios de manejo?","o":["Después de un año con la licencia condicional","Después de 90 días","Después de seis meses","Solo a los 18 años"],"h1":"Se necesita un año completo sin problemas.","h2":"En Carolina del Sur, quien tiene licencia condicional obtiene todos los privilegios después de un año sin infracciones de tránsito y sin choques por su culpa.","p":"Correcto. Un año limpio da todos los privilegios."},"ref":{"doc":"SC","page":"1-7"}},{"id":"sc-063","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, a 16-year-old gets 6 points in the first year of having a license. How long is the license suspended?","o":["One month","Three months","Six months","Two years"],"h1":"It is half a year.","h2":"In South Carolina, a driver under 17 who gets six or more points in the first year of having a license is suspended for six months.","p":"Right. The suspension lasts six months."},"es":{"q":"En Carolina del Sur, un joven de 16 años recibe 6 puntos en su primer año con licencia. ¿Por cuánto tiempo le suspenden la licencia?","o":["Un mes","Tres meses","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Carolina del Sur, un conductor menor de 17 años que recibe seis puntos o más en su primer año con licencia queda suspendido por seis meses.","p":"Correcto. La suspensión dura seis meses."},"ref":{"doc":"SC","page":"1-8"}},{"id":"sc-064","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how much does a new license with a waiver cost for a 16-year-old who needs to drive alone later for work?","o":["$2.50","$10","$25","$100"],"h1":"It costs the same as a regular license renewal.","h2":"In South Carolina, a new special restricted license with the waiver added costs $25.","p":"Right. The license with a waiver costs $25."},"es":{"q":"En Carolina del Sur, ¿cuánto cuesta la nueva licencia con exención (waiver) para un joven de 16 años que necesita manejar solo más tarde por su trabajo?","o":["$2.50","$10","$25","$100"],"h1":"Cuesta lo mismo que renovar una licencia normal.","h2":"En Carolina del Sur, la nueva licencia restringida especial con la exención cuesta $25.","p":"Correcto. La licencia con exención cuesta $25."},"ref":{"doc":"SC","page":"1-9"}},{"id":"sc-065","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a 16-year-old asks for a waiver to drive alone until midnight. Besides a parent's letter, what letter must they bring?","o":["A letter from a police officer","A letter from their doctor","A letter from their driving instructor","A letter from their school, church, job or activity saying why they need it"],"h1":"It comes from the place they need to drive to.","h2":"In South Carolina, the teen must bring a letter from their school, church, work or extracurricular activity that explains why they need the waiver, plus a letter from a parent or guardian.","p":"Right. The school, church, job or activity writes a letter."},"es":{"q":"En Carolina del Sur, un joven de 16 años pide una exención para manejar solo hasta la medianoche. Además de una carta de sus padres, ¿qué carta debe traer?","o":["Una carta de un policía","Una carta de su médico","Una carta de su instructor de manejo","Una carta de su escuela, iglesia, trabajo o actividad que diga por qué la necesita"],"h1":"Viene del lugar al que necesita manejar.","h2":"En Carolina del Sur, el joven debe traer una carta de su escuela, iglesia, trabajo o actividad extracurricular que explique por qué necesita la exención, además de una carta de su padre, madre o tutor.","p":"Correcto. La escuela, iglesia, trabajo o actividad escribe una carta."},"ref":{"doc":"SC","page":"1-9"}},{"id":"sc-066","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, a teen earns full driving privileges. How do they show it on their license?","o":["They keep the license in a sleeve the SCDMV mails to them","They must visit a branch for a new photo","They get a sticker from their school","They pass a new road test"],"h1":"No branch visit is needed.","h2":"In South Carolina, the SCDMV mails a sleeve to wrap around the license, and the driver must keep the license in it to use full privileges.","p":"Right. The mailed sleeve shows full privileges."},"es":{"q":"En Carolina del Sur, un adolescente obtiene todos los privilegios de manejo. ¿Cómo lo muestra en su licencia?","o":["Guarda la licencia en una funda que el SCDMV le envía por correo","Debe ir a una oficina para una foto nueva","Recibe una calcomanía de su escuela","Aprueba un nuevo examen de manejo"],"h1":"No hace falta ir a una oficina.","h2":"En Carolina del Sur, el SCDMV envía por correo una funda para envolver la licencia, y el conductor debe guardar la licencia en ella para usar todos los privilegios.","p":"Correcto. La funda que llega por correo muestra los privilegios completos."},"ref":{"doc":"SC","page":"1-10"}},{"id":"sc-067","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, you are taking the knowledge test and you ask the person next to you a question. What happens?","o":["You get a warning","You lose one point","Nothing, if you whisper","You fail the test"],"h1":"The rules about talking during the test are strict.","h2":"In South Carolina, you fail the knowledge test if you talk to anyone, leave the room before you finish, or bring in anything that could help you.","p":"Right. Talking to anyone means you fail."},"es":{"q":"En Carolina del Sur, usted está tomando el examen de conocimientos y le hace una pregunta a la persona de al lado. ¿Qué pasa?","o":["Recibe una advertencia","Pierde un punto","Nada, si habla en voz baja","Reprueba el examen"],"h1":"Las reglas sobre hablar durante el examen son estrictas.","h2":"En Carolina del Sur, usted reprueba el examen de conocimientos si habla con alguien, sale del salón antes de terminar o entra con algo que pueda ayudarle.","p":"Correcto. Hablar con alguien significa reprobar."},"ref":{"doc":"SC","page":"1-10"}},{"id":"sc-068","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, you passed your skills test with a driving school tester. What could still happen before your license is issued?","o":["The SCDMV could pick you at random to take the skills test again","You must take a written essay test","You must drive with an officer for a week","You must retake the vision test every month"],"h1":"State law lets the SCDMV double-check some new drivers.","h2":"In South Carolina, the SCDMV may randomly select you to pass the skills test again before it issues your driver's license.","p":"Right. You could be picked at random to retest."},"es":{"q":"En Carolina del Sur, usted aprobó el examen práctico con un examinador de una escuela de manejo. ¿Qué podría pasar todavía antes de recibir su licencia?","o":["El SCDMV podría escogerle al azar para repetir el examen práctico","Debe escribir un ensayo","Debe manejar con un policía por una semana","Debe repetir el examen de la vista cada mes"],"h1":"La ley permite al SCDMV volver a revisar a algunos conductores nuevos.","h2":"En Carolina del Sur, el SCDMV puede escogerle al azar para aprobar otra vez el examen práctico antes de darle la licencia.","p":"Correcto. Le pueden escoger al azar para repetirlo."},"ref":{"doc":"SC","page":"1-11"}},{"id":"sc-069","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, which tests do you take for a moped-only license?","o":["Only a skills test","Vision and knowledge tests, with no skills test","Vision, knowledge and skills tests","No tests at all"],"h1":"The SCDMV does not ride along for a moped license.","h2":"In South Carolina, a moped license needs only the vision and knowledge tests; there is no skills test.","p":"Right. Vision and knowledge, but no skills test."},"es":{"q":"En Carolina del Sur, ¿qué exámenes toma para una licencia solo de ciclomotor (moped)?","o":["Solo un examen práctico","El de la vista y el de conocimientos, sin examen práctico","El de la vista, el de conocimientos y el práctico","Ningún examen"],"h1":"El SCDMV no le acompaña manejando para la licencia de ciclomotor.","h2":"En Carolina del Sur, la licencia de ciclomotor solo requiere el examen de la vista y el de conocimientos; no hay examen práctico.","p":"Correcto. Vista y conocimientos, sin examen práctico."},"ref":{"doc":"SC","page":"1-11"}},{"id":"sc-070","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, which of these must work on the car you bring for the skills test?","o":["The radio and the clock","The cruise control","The backup camera","The speedometer and the defroster"],"h1":"Think of what keeps you legal and able to see.","h2":"In South Carolina, the skills test car must have working headlights, brakes, mirrors, wipers, speedometer, seat belts, defroster, turn signals and horn.","p":"Right. The speedometer and defroster must work."},"es":{"q":"En Carolina del Sur, ¿cuál de estas cosas debe funcionar en el carro que lleva al examen práctico?","o":["El radio y el reloj","El control de velocidad crucero","La cámara de reversa","El velocímetro y el desempañador"],"h1":"Piense en lo que le mantiene dentro de la ley y le deja ver bien.","h2":"En Carolina del Sur, el carro del examen práctico debe tener funcionando las luces, frenos, espejos, limpiaparabrisas, velocímetro, cinturones, desempañador, direccionales y bocina.","p":"Correcto. El velocímetro y el desempañador deben funcionar."},"ref":{"doc":"SC","page":"1-12"}},{"id":"sc-071","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, the examiner finds that the car you brought for the skills test is not safe. What happens?","o":["The test is postponed","You take the test anyway","You fail and must wait 30 days","The examiner lends you a car"],"h1":"The test does not go on in an unsafe car.","h2":"In South Carolina, the skills test must be postponed if the vehicle you bring is not safe.","p":"Right. The test is put off until you have a safe car."},"es":{"q":"En Carolina del Sur, el examinador ve que el carro que usted trajo al examen práctico no es seguro. ¿Qué pasa?","o":["Se pospone el examen","Toma el examen de todos modos","Reprueba y debe esperar 30 días","El examinador le presta un carro"],"h1":"El examen no sigue en un carro inseguro.","h2":"En Carolina del Sur, el examen práctico se debe posponer si el vehículo que usted trae no es seguro.","p":"Correcto. El examen se pospone hasta que tenga un carro seguro."},"ref":{"doc":"SC","page":"1-12"}},{"id":"sc-072","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, who should come with you to your skills test?","o":["A lawyer","A licensed driver","Two witnesses","Nobody at all"],"h1":"Someone has to be able to drive the car legally if needed.","h2":"In South Carolina, you should bring a licensed driver to the skills test, along with your permit and proof of insurance.","p":"Right. Bring a licensed driver with you."},"es":{"q":"En Carolina del Sur, ¿quién debe ir con usted a su examen práctico?","o":["Un abogado","Un conductor con licencia","Dos testigos","Nadie"],"h1":"Alguien debe poder manejar el carro legalmente si hace falta.","h2":"En Carolina del Sur, usted debe llevar a un conductor con licencia al examen práctico, junto con su permiso y prueba de seguro.","p":"Correcto. Lleve a un conductor con licencia."},"ref":{"doc":"SC","page":"1-12"}},{"id":"sc-073","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, during the skills test you may have to back up in a straight line. How far?","o":["20 feet","50 feet","100 feet","300 feet"],"h1":"It is the same distance as the turn signal rule.","h2":"In South Carolina, the skills test can include backing in a straight line for 100 feet.","p":"Right. The straight-line backing is 100 feet."},"es":{"q":"En Carolina del Sur, durante el examen práctico puede tener que dar reversa en línea recta. ¿Qué distancia?","o":["20 pies","50 pies","100 pies","300 pies"],"h1":"Es la misma distancia de la regla de la direccional.","h2":"En Carolina del Sur, el examen práctico puede incluir dar reversa en línea recta por 100 pies.","p":"Correcto. La reversa en línea recta es de 100 pies."},"ref":{"doc":"SC","page":"1-12"}},{"id":"sc-074","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you fail the skills test for the second time. How long must you wait to try again?","o":["2 business days","7 calendar days","14 calendar days","30 calendar days"],"h1":"It is one week.","h2":"In South Carolina, after a second failed skills test you must wait seven calendar days before you can test again.","p":"Right. After a second fail, wait seven days."},"es":{"q":"En Carolina del Sur, usted reprueba el examen práctico por segunda vez. ¿Cuánto debe esperar para intentarlo otra vez?","o":["2 días hábiles","7 días calendario","14 días calendario","30 días calendario"],"h1":"Es una semana.","h2":"En Carolina del Sur, después de reprobar el examen práctico por segunda vez debe esperar siete días calendario para volver a tomarlo.","p":"Correcto. Después del segundo intento fallido, espere siete días."},"ref":{"doc":"SC","page":"1-13"}},{"id":"sc-075","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you fail the skills test for the third time. How long must you wait to try again?","o":["7 calendar days","30 calendar days","60 calendar days","90 calendar days"],"h1":"It is about one month.","h2":"In South Carolina, after a third or later failed skills test you must wait 30 calendar days before you can test again.","p":"Right. After a third fail, wait 30 days."},"es":{"q":"En Carolina del Sur, usted reprueba el examen práctico por tercera vez. ¿Cuánto debe esperar para intentarlo otra vez?","o":["7 días calendario","30 días calendario","60 días calendario","90 días calendario"],"h1":"Es más o menos un mes.","h2":"En Carolina del Sur, después de reprobar el examen práctico por tercera vez o más debe esperar 30 días calendario para volver a tomarlo.","p":"Correcto. Después del tercer intento fallido, espere 30 días."},"ref":{"doc":"SC","page":"1-13"}},{"id":"sc-076","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, you move here for one year to go to college and keep your home in another state. Must you get a South Carolina driver's license?","o":["Yes, within 10 days","Yes, within 45 days","Yes, before you drive at all","No, but your out-of-state license must be valid"],"h1":"Students and military members who are here for a while are treated as temporary residents.","h2":"In South Carolina, a temporary resident such as a student does not have to get a South Carolina license, but must have a valid out-of-state license to drive.","p":"Right. A temporary resident can drive on a valid out-of-state license."},"es":{"q":"En Carolina del Sur, usted se muda aquí por un año para estudiar en la universidad y mantiene su hogar en otro estado. ¿Debe sacar una licencia de Carolina del Sur?","o":["Sí, en 10 días","Sí, en 45 días","Sí, antes de manejar","No, pero su licencia de otro estado debe estar vigente"],"h1":"Los estudiantes y militares que están aquí por un tiempo se consideran residentes temporales.","h2":"En Carolina del Sur, un residente temporal, como un estudiante, no tiene que sacar licencia de Carolina del Sur, pero debe tener una licencia vigente de otro estado para manejar.","p":"Correcto. Un residente temporal puede manejar con una licencia vigente de otro estado."},"ref":{"doc":"SC","page":"1-13"}},{"id":"sc-077","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, you move away and plan to cancel your South Carolina car insurance. What should you do first?","o":["Turn in your South Carolina license plate to the SCDMV","Throw the plate away","Keep the plate as a souvenir","Mail the plate to your insurance company"],"h1":"If you skip this step, you could owe up to $400 in fees.","h2":"In South Carolina, you should turn in your license plate to the SCDMV before you cancel your insurance, or you could owe up to $400 in fees.","p":"Right. Return the plate before you cancel the insurance."},"es":{"q":"En Carolina del Sur, usted se muda a otro estado y piensa cancelar el seguro de su carro de Carolina del Sur. ¿Qué debe hacer primero?","o":["Entregar la placa de Carolina del Sur al SCDMV","Tirar la placa a la basura","Guardar la placa de recuerdo","Enviar la placa a su compañía de seguros"],"h1":"Si se salta este paso, podría deber hasta $400 en cargos.","h2":"En Carolina del Sur, debe entregar la placa al SCDMV antes de cancelar el seguro; si no, podría deber hasta $400 en cargos.","p":"Correcto. Devuelva la placa antes de cancelar el seguro."},"ref":{"doc":"SC","page":"1-14"}},{"id":"sc-078","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, a visitor from a non-English-speaking country carries an International Driving Permit. What is it?","o":["A South Carolina driver's license","A license that replaces their home license","A translation used together with their own valid license","A permit to drive commercial trucks"],"h1":"It helps an officer read the license; it does not replace it.","h2":"In South Carolina, an International Driving Permit is not a license; it translates the visitor's own valid license into English.","p":"Right. It is a translation that goes with the real license."},"es":{"q":"En Carolina del Sur, un visitante de un país donde no se habla inglés lleva un Permiso Internacional de Manejo. ¿Qué es?","o":["Una licencia de Carolina del Sur","Una licencia que reemplaza la de su país","Una traducción que se usa junto con su propia licencia vigente","Un permiso para manejar camiones comerciales"],"h1":"Ayuda a un policía a leer la licencia; no la reemplaza.","h2":"En Carolina del Sur, el Permiso Internacional de Manejo no es una licencia; traduce al inglés la licencia vigente del visitante.","p":"Correcto. Es una traducción que va con la licencia real."},"ref":{"doc":"SC","page":"1-14"}},{"id":"sc-079","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, you renew your license with a vision exam from your own eye doctor. How recent must that exam be?","o":["Within the past 30 days","Within the past 6 months","Within the past 36 months","Within the past 10 years"],"h1":"It is three years.","h2":"In South Carolina, the SCDMV may accept a Certificate of Vision Examination from a licensed eye care professional dated within the past 36 months.","p":"Right. The eye exam must be from the last 36 months."},"es":{"q":"En Carolina del Sur, usted renueva su licencia con un examen de la vista de su propio oculista. ¿Qué tan reciente debe ser ese examen?","o":["De los últimos 30 días","De los últimos 6 meses","De los últimos 36 meses","De los últimos 10 años"],"h1":"Son tres años.","h2":"En Carolina del Sur, el SCDMV puede aceptar un Certificado de Examen de la Vista de un profesional de la vista con licencia, con fecha de los últimos 36 meses.","p":"Correcto. El examen de la vista debe ser de los últimos 36 meses."},"ref":{"doc":"SC","page":"1-15"}},{"id":"sc-080","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, who cannot renew a driver's license online or by mail?","o":["A driver over 30","A driver with a Class D license","A driver who wears glasses","A driver who is not a US citizen"],"h1":"Online and mail renewal is limited by citizenship.","h2":"In South Carolina, only US citizens may renew a driver's license online or by mail; a driver who is not a US citizen must renew in person.","p":"Right. Non-citizens cannot renew online or by mail."},"es":{"q":"En Carolina del Sur, ¿quién no puede renovar la licencia de manejar por internet ni por correo?","o":["Un conductor mayor de 30 años","Un conductor con licencia Clase D","Un conductor que usa lentes","Un conductor que no es ciudadano de EE. UU."],"h1":"La renovación por internet y por correo depende de la ciudadanía.","h2":"En Carolina del Sur, solo los ciudadanos de EE. UU. pueden renovar la licencia por internet o por correo; quien no es ciudadano debe renovarla en persona.","p":"Correcto. Los no ciudadanos no pueden renovar por internet ni por correo."},"ref":{"doc":"SC","page":"1-15"}},{"id":"sc-081","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, how many points in the last two years would stop you from renewing your license online?","o":["More than 5 points","Any points at all","More than 12 points","More than 20 points"],"h1":"It is less than half of the number that brings a suspension.","h2":"In South Carolina, you cannot renew online if you have received more than five points on your record in the last two years.","p":"Right. More than five points blocks online renewal."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos en los últimos dos años le impedirían renovar la licencia por internet?","o":["Más de 5 puntos","Cualquier punto","Más de 12 puntos","Más de 20 puntos"],"h1":"Es menos de la mitad del número que causa una suspensión.","h2":"En Carolina del Sur, usted no puede renovar por internet si ha recibido más de cinco puntos en su historial en los últimos dos años.","p":"Correcto. Más de cinco puntos impide renovar por internet."},"ref":{"doc":"SC","page":"1-16"}},{"id":"sc-082","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, you renewed your license online last time. How must you renew it this time?","o":["Online again","By mail","By phone","In person at an SCDMV branch"],"h1":"You cannot skip the branch two renewals in a row.","h2":"In South Carolina, you cannot renew online or by mail if you renewed that way during the last renewal period, so you must renew at a branch.","p":"Right. This time you renew in person."},"es":{"q":"En Carolina del Sur, la última vez usted renovó su licencia por internet. ¿Cómo debe renovarla esta vez?","o":["Otra vez por internet","Por correo","Por teléfono","En persona en una oficina del SCDMV"],"h1":"No puede evitar la oficina dos renovaciones seguidas.","h2":"En Carolina del Sur, no puede renovar por internet ni por correo si la última vez renovó de esa forma, así que debe renovar en una oficina.","p":"Correcto. Esta vez se renueva en persona."},"ref":{"doc":"SC","page":"1-16"}},{"id":"sc-083","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how much does it cost to renew a regular driver's license at a branch?","o":["$2.50","$12.50","$25","$100"],"h1":"It is the same price as renewing by mail.","h2":"In South Carolina, renewing a regular driver's license costs $25.","p":"Right. Renewal costs $25."},"es":{"q":"En Carolina del Sur, ¿cuánto cuesta renovar una licencia de manejar normal en una oficina?","o":["$2.50","$12.50","$25","$100"],"h1":"Es el mismo precio que renovar por correo.","h2":"En Carolina del Sur, renovar una licencia de manejar normal cuesta $25.","p":"Correcto. La renovación cuesta $25."},"ref":{"doc":"SC","page":"1-17"}},{"id":"sc-084","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, you renew your license by mail. How early should you mail it?","o":["At least three weeks before it expires","On the day it expires","One week after it expires","Exactly one year before it expires"],"h1":"Give the mail and the SCDMV time to work.","h2":"In South Carolina, you should mail your renewal application and payment at least three weeks before your license expires.","p":"Right. Mail it at least three weeks early."},"es":{"q":"En Carolina del Sur, usted renueva su licencia por correo. ¿Con cuánta anticipación debe enviarla?","o":["Al menos tres semanas antes de que venza","El mismo día que vence","Una semana después de que vence","Exactamente un año antes de que venza"],"h1":"Dele tiempo al correo y al SCDMV.","h2":"En Carolina del Sur, debe enviar por correo la solicitud y el pago al menos tres semanas antes de que venza su licencia.","p":"Correcto. Envíela al menos tres semanas antes."},"ref":{"doc":"SC","page":"1-17"}},{"id":"sc-085","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you get a speeding ticket while driving in Georgia. Can it add points to your South Carolina record?","o":["No, only South Carolina tickets count","Yes, violations in other states count too","Only if you are under 18","Only if you were driving a truck"],"h1":"The SCDMV hears about convictions from other states.","h2":"In South Carolina, traffic convictions from any state are sent to the SCDMV and can add points to your record.","p":"Right. Out-of-state tickets can add points."},"es":{"q":"En Carolina del Sur, usted recibe una multa por exceso de velocidad mientras maneja en Georgia. ¿Puede sumar puntos en su historial de Carolina del Sur?","o":["No, solo cuentan las multas de Carolina del Sur","Sí, las infracciones en otros estados también cuentan","Solo si es menor de 18 años","Solo si manejaba un camión"],"h1":"El SCDMV se entera de las condenas de otros estados.","h2":"En Carolina del Sur, las condenas de tránsito de cualquier estado se envían al SCDMV y pueden sumar puntos a su historial.","p":"Correcto. Las multas de otros estados pueden sumar puntos."},"ref":{"doc":"SC","page":"1-18"}},{"id":"sc-086","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, at what point totals does the SCDMV send a 15- or 16-year-old a letter to drive more carefully?","o":["At 1 point","At 2 points and at 4 points","At 6 points and at 10 points","Only at 12 points"],"h1":"Young drivers get warned early, with small numbers.","h2":"In South Carolina, the SCDMV sends a 15- or 16-year-old a warning letter at two points and again at four points.","p":"Right. Warnings come at two and four points."},"es":{"q":"En Carolina del Sur, ¿con cuántos puntos le envía el SCDMV una carta a un joven de 15 o 16 años para que maneje con más cuidado?","o":["Con 1 punto","Con 2 puntos y con 4 puntos","Con 6 puntos y con 10 puntos","Solo con 12 puntos"],"h1":"A los conductores jóvenes se les advierte temprano, con números pequeños.","h2":"En Carolina del Sur, el SCDMV le envía a un joven de 15 o 16 años una carta de advertencia con dos puntos y otra con cuatro puntos.","p":"Correcto. Las advertencias llegan con dos y con cuatro puntos."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-087","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, a driver 17 or older gets a warning letter from the SCDMV when the record reaches how many points?","o":["2 points","4 points","6 points","12 points"],"h1":"It is half the number that brings a suspension.","h2":"In South Carolina, a driver 17 or older with six or more points gets a letter to drive more carefully; at 12 points the license is suspended.","p":"Right. The warning letter comes at six points."},"es":{"q":"En Carolina del Sur, ¿con cuántos puntos en su historial recibe una carta de advertencia del SCDMV un conductor de 17 años o más?","o":["2 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Es la mitad del número que causa una suspensión.","h2":"En Carolina del Sur, un conductor de 17 años o más con seis puntos o más recibe una carta para que maneje con más cuidado; con 12 puntos se suspende la licencia.","p":"Correcto. La carta de advertencia llega con seis puntos."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-088","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a permit holder is suspended for having too many points. Will a defensive driving course end the suspension?","o":["Yes, right away","Yes, if taken online","Yes, but only on weekends","No, the course will not reinstate it"],"h1":"Point reduction does not undo this kind of suspension.","h2":"In South Carolina, finishing a defensive driving course will not reinstate a permit, conditional or special restricted license suspended for excessive points.","p":"Right. The course does not end that suspension."},"es":{"q":"En Carolina del Sur, a alguien con permiso le suspenden por tener demasiados puntos. ¿Un curso de manejo defensivo termina la suspensión?","o":["Sí, de inmediato","Sí, si lo toma por internet","Sí, pero solo los fines de semana","No, el curso no la levanta"],"h1":"Reducir puntos no deshace este tipo de suspensión.","h2":"En Carolina del Sur, terminar un curso de manejo defensivo no levanta la suspensión de un permiso o licencia condicional o restringida especial por exceso de puntos.","p":"Correcto. El curso no termina esa suspensión."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-089","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, how is a license suspension for driving under the influence (DUI) handled?","o":["It is a mandatory suspension outside the point system","It adds 2 points","It adds 12 points","It only brings a warning letter"],"h1":"Some violations skip the points and go straight to suspension.","h2":"In South Carolina, certain violations such as DUI require a mandatory license suspension and are not under the point system.","p":"Right. DUI brings a mandatory suspension, not points."},"es":{"q":"En Carolina del Sur, ¿cómo se maneja la suspensión de licencia por manejar bajo la influencia (DUI)?","o":["Es una suspensión obligatoria fuera del sistema de puntos","Suma 2 puntos","Suma 12 puntos","Solo trae una carta de advertencia"],"h1":"Algunas infracciones no usan puntos y van directo a la suspensión.","h2":"En Carolina del Sur, ciertas infracciones, como el DUI, exigen una suspensión obligatoria de la licencia y no forman parte del sistema de puntos.","p":"Correcto. El DUI trae una suspensión obligatoria, no puntos."},"ref":{"doc":"SC","page":"1-19"}},{"id":"sc-090","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, can you take the point-reduction defensive driving course online?","o":["Yes, from any state","Yes, but only on a phone","Only if you have over 12 points","No, it must be taken in a classroom in South Carolina"],"h1":"The course must be in person and in this state.","h2":"In South Carolina, the defensive driving course for point reduction cannot be completed online and must be taken in South Carolina.","p":"Right. It is an in-person course in South Carolina."},"es":{"q":"En Carolina del Sur, ¿puede tomar por internet el curso de manejo defensivo para reducir puntos?","o":["Sí, desde cualquier estado","Sí, pero solo en un teléfono","Solo si tiene más de 12 puntos","No, debe tomarse en un salón de clase en Carolina del Sur"],"h1":"El curso debe ser en persona y en este estado.","h2":"En Carolina del Sur, el curso de manejo defensivo para reducir puntos no se puede hacer por internet y se debe tomar en Carolina del Sur.","p":"Correcto. Es un curso en persona en Carolina del Sur."},"ref":{"doc":"SC","page":"1-20"}},{"id":"sc-091","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long is the defensive driving course that can reduce your points?","o":["1 hour","4 hours","8 hours","40 hours"],"h1":"It is about one work day.","h2":"In South Carolina, the point-reduction defensive driving course must be eight hours of classroom training.","p":"Right. The course is eight hours in a classroom."},"es":{"q":"En Carolina del Sur, ¿cuánto dura el curso de manejo defensivo que puede reducir sus puntos?","o":["1 hora","4 horas","8 horas","40 horas"],"h1":"Es más o menos una jornada de trabajo.","h2":"En Carolina del Sur, el curso de manejo defensivo para reducir puntos debe tener ocho horas de clase en un salón.","p":"Correcto. El curso dura ocho horas en un salón."},"ref":{"doc":"SC","page":"1-20"}},{"id":"sc-092","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, an approved defensive driving course can take up to how many points off your record?","o":["1 point","4 points","8 points","12 points"],"h1":"Schools are certified for this number of points.","h2":"In South Carolina, approved defensive driving courses are certified for a four-point reduction.","p":"Right. The course can reduce up to four points."},"es":{"q":"En Carolina del Sur, ¿hasta cuántos puntos puede quitar de su historial un curso aprobado de manejo defensivo?","o":["1 punto","4 puntos","8 puntos","12 puntos"],"h1":"Las escuelas están certificadas para este número de puntos.","h2":"En Carolina del Sur, los cursos aprobados de manejo defensivo están certificados para reducir cuatro puntos.","p":"Correcto. El curso puede reducir hasta cuatro puntos."},"ref":{"doc":"SC","page":"1-20"}},{"id":"sc-093","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, your license is about to be suspended for points. When must you finish a defensive driving course for it to help?","o":["Before the suspension begins","Any time during the suspension","Within a year after the suspension","It never helps"],"h1":"After the suspension starts, the course cannot cancel it.","h2":"In South Carolina, you must finish the course before the suspension begins; once it begins, the point reduction will not cancel or shorten it.","p":"Right. Finish the course before the suspension starts."},"es":{"q":"En Carolina del Sur, le van a suspender la licencia por puntos. ¿Cuándo debe terminar un curso de manejo defensivo para que le ayude?","o":["Antes de que empiece la suspensión","En cualquier momento durante la suspensión","Dentro de un año después de la suspensión","Nunca ayuda"],"h1":"Después de que empieza la suspensión, el curso no la puede cancelar.","h2":"En Carolina del Sur, debe terminar el curso antes de que empiece la suspensión; una vez que empieza, la reducción de puntos no la cancela ni la acorta.","p":"Correcto. Termine el curso antes de que empiece la suspensión."},"ref":{"doc":"SC","page":"1-20"}},{"id":"sc-094","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, can a driver suspended for a first DUI that happened after May 19, 2024, get a provisional license?","o":["Yes, for $100","Yes, if the BAC was under 0.14","Yes, after one week","No, the provisional license is not available for it"],"h1":"The law changed for DUIs from that date on.","h2":"In South Carolina, the provisional driver's license is not available for any DUI or DUAC on or after May 19, 2024.","p":"Right. No provisional license for DUIs from that date."},"es":{"q":"En Carolina del Sur, ¿puede un conductor suspendido por un primer DUI ocurrido después del 19 de mayo de 2024 obtener una licencia provisional?","o":["Sí, por $100","Sí, si el nivel de alcohol era menor de 0.14","Sí, después de una semana","No, la licencia provisional no está disponible para ese caso"],"h1":"La ley cambió para los DUI desde esa fecha.","h2":"En Carolina del Sur, la licencia provisional no está disponible para ningún DUI o DUAC ocurrido el 19 de mayo de 2024 o después.","p":"Correcto. No hay licencia provisional para los DUI desde esa fecha."},"ref":{"doc":"SC","page":"1-21"}},{"id":"sc-095","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how much does a route restricted license cost if it is approved?","o":["$25","$50","$100","$500"],"h1":"It costs four times a regular renewal.","h2":"In South Carolina, an approved route restricted license costs $100.","p":"Right. A route restricted license costs $100."},"es":{"q":"En Carolina del Sur, ¿cuánto cuesta una licencia con ruta restringida si se aprueba?","o":["$25","$50","$100","$500"],"h1":"Cuesta cuatro veces una renovación normal.","h2":"En Carolina del Sur, una licencia con ruta restringida aprobada cuesta $100.","p":"Correcto. La licencia con ruta restringida cuesta $100."},"ref":{"doc":"SC","page":"1-22"}},{"id":"sc-096","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you were suspended for refusing an alcohol test. To get a temporary alcohol license, within how many days must you ask for a hearing?","o":["3 days","30 days","90 days","180 days"],"h1":"It is about one month.","h2":"In South Carolina, you may get a temporary alcohol license if you file for an administrative hearing within 30 days.","p":"Right. Ask for the hearing within 30 days."},"es":{"q":"En Carolina del Sur, le suspendieron por negarse a una prueba de alcohol. Para obtener una licencia temporal de alcohol, ¿en cuántos días debe pedir una audiencia?","o":["3 días","30 días","90 días","180 días"],"h1":"Es más o menos un mes.","h2":"En Carolina del Sur, puede obtener una licencia temporal de alcohol si pide una audiencia administrativa dentro de 30 días.","p":"Correcto. Pida la audiencia dentro de 30 días."},"ref":{"doc":"SC","page":"1-23"}},{"id":"sc-097","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, who must fill out the Selective Service form when applying for a permit, license or ID card?","o":["A male US citizen or immigrant under 26","Every applicant of any age","Only women over 18","Only people who served in the military"],"h1":"It is about registering young men for possible military service.","h2":"In South Carolina, a male US citizen or immigrant under 26 must complete the Selective Service supplement when applying for a permit, license or ID.","p":"Right. Males under 26 fill out the form."},"es":{"q":"En Carolina del Sur, ¿quién debe llenar el formulario del Servicio Selectivo al solicitar un permiso, licencia o tarjeta de identificación?","o":["Un hombre ciudadano o inmigrante menor de 26 años","Todos los solicitantes de cualquier edad","Solo las mujeres mayores de 18","Solo quienes sirvieron en el ejército"],"h1":"Se trata de registrar a los hombres jóvenes para un posible servicio militar.","h2":"En Carolina del Sur, un hombre ciudadano de EE. UU. o inmigrante menor de 26 años debe llenar el formulario del Servicio Selectivo al solicitar un permiso, licencia o identificación.","p":"Correcto. Los hombres menores de 26 llenan el formulario."},"ref":{"doc":"SC","page":"2-1"}},{"id":"sc-098","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, you register as an organ donor at the SCDMV. What is added to your license?","o":["A blue star","A green cross","The word DONOR in big letters","A red heart"],"h1":"It is a symbol of love and life.","h2":"In South Carolina, a red heart is added to the license, permit or ID card of a registered organ and tissue donor.","p":"Right. Donors get a red heart on the license."},"es":{"q":"En Carolina del Sur, usted se registra como donante de órganos en el SCDMV. ¿Qué se agrega a su licencia?","o":["Una estrella azul","Una cruz verde","La palabra DONANTE en letras grandes","Un corazón rojo"],"h1":"Es un símbolo de amor y vida.","h2":"En Carolina del Sur, se agrega un corazón rojo a la licencia, permiso o identificación de un donante registrado de órganos y tejidos.","p":"Correcto. Los donantes llevan un corazón rojo en la licencia."},"ref":{"doc":"SC","page":"2-1"}},{"id":"sc-099","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, what do you need to drive a golf cart on public roads?","o":["Be at least 16 with a valid driver's license","Be at least 12 with a parent nearby","Be at least 14 with a beginner's permit","Nothing; golf carts need no license"],"h1":"It is the same age as a special restricted license.","h2":"In South Carolina, you must be at least 16 and have a valid driver's license to drive a golf cart, and the cart needs an SCDMV permit decal.","p":"Right. You must be 16 with a valid license."},"es":{"q":"En Carolina del Sur, ¿qué necesita para manejar un carrito de golf en vías públicas?","o":["Tener al menos 16 años y una licencia de manejar vigente","Tener al menos 12 años con un padre cerca","Tener al menos 14 años con permiso de principiante","Nada; los carritos de golf no necesitan licencia"],"h1":"Es la misma edad de la licencia restringida especial.","h2":"En Carolina del Sur, debe tener al menos 16 años y una licencia de manejar vigente para manejar un carrito de golf, y el carrito necesita una calcomanía de permiso del SCDMV.","p":"Correcto. Debe tener 16 años y licencia vigente."},"ref":{"doc":"SC","page":"2-2"}},{"id":"sc-100","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, a permitted golf cart may be driven in the daytime within how many miles of the address on its registration?","o":["1 mile","4 miles","10 miles","25 miles"],"h1":"It is a short trip around your neighborhood.","h2":"In South Carolina, a permitted golf cart may be driven in the daytime within four miles of the address on its registration, or of a gated community's gate.","p":"Right. Golf carts stay within four miles."},"es":{"q":"En Carolina del Sur, ¿a cuántas millas de la dirección de su registro se puede manejar de día un carrito de golf con permiso?","o":["1 milla","4 millas","10 millas","25 millas"],"h1":"Es un viaje corto por su vecindario.","h2":"En Carolina del Sur, un carrito de golf con permiso se puede manejar de día a no más de cuatro millas de la dirección de su registro o de la entrada de una comunidad cerrada.","p":"Correcto. Los carritos de golf se quedan dentro de cuatro millas."},"ref":{"doc":"SC","page":"2-2"}},{"id":"sc-101","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, you finish a cigarette while driving. What does the driver's manual say to do with the butt?","o":["Toss it out the window onto the grass","Drop it on the road where it cannot burn anything","Keep it in the car until you can throw it away properly","Flick it into the median"],"h1":"Cigarette butts count as litter.","h2":"In South Carolina, cigarettes and cigarette butts are litter, so keep them inside your vehicle until you can dispose of them properly.","p":"Right. Keep the butt in the car; it is litter."},"es":{"q":"En Carolina del Sur, usted termina un cigarrillo mientras maneja. ¿Qué dice el manual que haga con la colilla?","o":["Tirarla por la ventana al pasto","Dejarla caer en la carretera donde no queme nada","Guardarla en el carro hasta poder tirarla en un lugar adecuado","Lanzarla a la mediana"],"h1":"Las colillas de cigarrillo cuentan como basura.","h2":"En Carolina del Sur, los cigarrillos y las colillas son basura, así que guárdelos dentro del vehículo hasta poder tirarlos en un lugar adecuado.","p":"Correcto. Guarde la colilla en el carro; es basura."},"ref":{"doc":"SC","page":"2-2"}},{"id":"sc-102","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a driver uses bioptic telescopic lenses. How often must vision paperwork be sent to the SCDMV?","o":["Only once, when first licensed","Every 8 years","Every 10 years","Every year"],"h1":"It is more often than license renewal.","h2":"In South Carolina, a driver who uses bioptic telescopic lenses must send vision screening paperwork to the SCDMV's Driver Improvement unit every year.","p":"Right. Bioptic lens users send paperwork every year."},"es":{"q":"En Carolina del Sur, un conductor usa lentes telescópicos biópticos. ¿Cada cuánto debe enviar los documentos de la vista al SCDMV?","o":["Solo una vez, al sacar la licencia","Cada 8 años","Cada 10 años","Cada año"],"h1":"Es más seguido que la renovación de la licencia.","h2":"En Carolina del Sur, quien usa lentes telescópicos biópticos debe enviar cada año los documentos del examen de la vista a la unidad de Mejoramiento del Conductor del SCDMV.","p":"Correcto. Quien usa lentes biópticos envía documentos cada año."},"ref":{"doc":"SC","page":"3-1"}},{"id":"sc-103","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, what is the minimum vision needed to drive, with glasses or contacts if needed?","o":["20/40 in one eye","20/20 in both eyes","20/100 in one eye","20/200 in both eyes"],"h1":"It is a common standard used in many states.","h2":"In South Carolina, the minimum vision standard does not require better than 20/40 corrected in one eye.","p":"Right. The standard is 20/40 in one eye."},"es":{"q":"En Carolina del Sur, ¿cuál es la visión mínima para manejar, con lentes o lentes de contacto si hacen falta?","o":["20/40 en un ojo","20/20 en los dos ojos","20/100 en un ojo","20/200 en los dos ojos"],"h1":"Es una norma común en muchos estados.","h2":"En Carolina del Sur, la norma mínima de visión no exige más de 20/40 corregido en un ojo.","p":"Correcto. La norma es 20/40 en un ojo."},"ref":{"doc":"SC","page":"3-2"}},{"id":"sc-104","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you need glasses to pass the vision test. What restriction code goes on your license?","o":["Code B","Code A","Code M","Code Z"],"h1":"It is the first letter of the alphabet.","h2":"In South Carolina, restriction code A on a permit or license means you must wear corrective lenses to drive.","p":"Right. Code A means corrective lenses."},"es":{"q":"En Carolina del Sur, usted necesita lentes para pasar el examen de la vista. ¿Qué código de restricción va en su licencia?","o":["Código B","Código A","Código M","Código Z"],"h1":"Es la primera letra del alfabeto.","h2":"En Carolina del Sur, el código de restricción A en un permiso o licencia significa que debe usar lentes correctivos para manejar.","p":"Correcto. El código A significa lentes correctivos."},"ref":{"doc":"SC","page":"3-2"}},{"id":"sc-105","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, how often does the driver's manual suggest stopping on a long trip?","o":["Every 20 miles","Every 500 miles","About every 100 miles or 2 hours","Only when the gas tank is empty"],"h1":"Think of a regular break about every two hours.","h2":"In South Carolina, the driver's manual suggests stopping about every 100 miles or two hours on long trips to avoid fatigue.","p":"Right. Stop about every 100 miles or two hours."},"es":{"q":"En Carolina del Sur, ¿cada cuánto sugiere el manual parar en un viaje largo?","o":["Cada 20 millas","Cada 500 millas","Más o menos cada 100 millas o 2 horas","Solo cuando se acaba la gasolina"],"h1":"Piense en un descanso regular cada dos horas más o menos.","h2":"En Carolina del Sur, el manual sugiere parar más o menos cada 100 millas o dos horas en viajes largos para evitar el cansancio.","p":"Correcto. Pare más o menos cada 100 millas o dos horas."},"ref":{"doc":"SC","page":"3-3"}},{"id":"sc-107","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, what is the fine for a first offense under the Hands-Free and Distracted Driving Act?","o":["$25","$100","$500","$1,000"],"h1":"The second offense costs twice as much.","h2":"In South Carolina, a first offense under the Hands-Free and Distracted Driving Act is a $100 fine.","p":"Right. The first offense is $100."},"es":{"q":"En Carolina del Sur, ¿cuál es la multa por una primera infracción de la Ley de Manos Libres y Manejo Distraído?","o":["$25","$100","$500","$1,000"],"h1":"La segunda infracción cuesta el doble.","h2":"En Carolina del Sur, una primera infracción de la Ley de Manos Libres y Manejo Distraído tiene una multa de $100.","p":"Correcto. La primera infracción cuesta $100."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-108","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, which of these breaks the Hands-Free and Distracted Driving Act while you drive?","o":["Watching a video call on a phone in a dashboard mount","Talking through an earpiece","Talking through a watch on your wrist","Listening to the radio"],"h1":"The law bans viewing moving images, even when the phone is not in your hand.","h2":"In South Carolina, drivers may not hold a phone, text, or watch moving images such as videos, games or video calls.","p":"Right. Watching a video call while driving is against the law."},"es":{"q":"En Carolina del Sur, ¿cuál de estas acciones viola la Ley de Manos Libres y Manejo Distraído mientras maneja?","o":["Ver una videollamada en un teléfono montado en el tablero","Hablar con un audífono","Hablar con un reloj en la muñeca","Escuchar la radio"],"h1":"La ley prohíbe ver imágenes en movimiento, aunque el teléfono no esté en su mano.","h2":"En Carolina del Sur, los conductores no pueden sostener el teléfono, escribir mensajes ni ver imágenes en movimiento como videos, juegos o videollamadas.","p":"Correcto. Ver una videollamada mientras maneja va contra la ley."},"ref":{"doc":"SC","page":"3-5"}},{"id":"sc-109","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, the driver's manual says alcohol starts to affect every driver's vision at what blood alcohol level?","o":["0.02 percent","0.08 percent","0.15 percent","0.20 percent"],"h1":"It is far below the legal limit for adults.","h2":"In South Carolina, the driver's manual says vision is affected at 0.02 percent blood alcohol for all drivers.","p":"Right. Vision is affected at 0.02 percent."},"es":{"q":"En Carolina del Sur, según el manual, ¿con qué nivel de alcohol en la sangre empieza a afectarse la vista de todo conductor?","o":["0.02 por ciento","0.08 por ciento","0.15 por ciento","0.20 por ciento"],"h1":"Es mucho menos que el límite legal para adultos.","h2":"En Carolina del Sur, el manual dice que la vista se afecta con 0.02 por ciento de alcohol en la sangre en todos los conductores.","p":"Correcto. La vista se afecta con 0.02 por ciento."},"ref":{"doc":"SC","page":"3-6"}},{"id":"sc-110","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, your blood alcohol is 0.05 and you also took a cold medicine that makes you drowsy. Can you be convicted of impaired driving?","o":["No, you are under 0.08","No, cold medicine is legal","Yes, even at a lower BAC when combined with drugs","Only if you crash"],"h1":"The legal limit is not a safe level.","h2":"In South Carolina, you can be convicted of impaired driving with a BAC of 0.05 or lower when it is combined with drugs, including prescription and over-the-counter medicines.","p":"Right. You can be convicted below 0.08 when drugs are involved."},"es":{"q":"En Carolina del Sur, su nivel de alcohol es 0.05 y además tomó un medicamento para el resfriado que da sueño. ¿Le pueden condenar por manejar afectado?","o":["No, está por debajo de 0.08","No, el medicamento es legal","Sí, aun con un nivel más bajo si se combina con drogas","Solo si choca"],"h1":"El límite legal no es un nivel seguro.","h2":"En Carolina del Sur, le pueden condenar por manejar afectado con un nivel de 0.05 o menos si se combina con drogas, incluidos los medicamentos con y sin receta.","p":"Correcto. Le pueden condenar por debajo de 0.08 si hay drogas."},"ref":{"doc":"SC","page":"3-7"}},{"id":"sc-111","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, a driver with a North Carolina license is arrested here for impaired driving. Which state's implied consent law applies?","o":["North Carolina's, where the license is from","Neither state's","The driver may choose","South Carolina's, where the arrest happened"],"h1":"It depends on where you are, not where your license is from.","h2":"In South Carolina, implied consent laws apply in the state where you were arrested, not the state that issued your license.","p":"Right. The law of the state where you are arrested applies."},"es":{"q":"En Carolina del Sur, un conductor con licencia de Carolina del Norte es arrestado aquí por manejar afectado. ¿Qué ley de consentimiento implícito se aplica?","o":["La de Carolina del Norte, donde sacó la licencia","La de ninguno de los dos estados","El conductor puede escoger","La de Carolina del Sur, donde ocurrió el arresto"],"h1":"Depende de dónde está, no de dónde es su licencia.","h2":"En Carolina del Sur, la ley de consentimiento implícito que se aplica es la del estado donde le arrestan, no la del estado que dio su licencia.","p":"Correcto. Se aplica la ley del estado donde le arrestan."},"ref":{"doc":"SC","page":"3-8"}},{"id":"sc-112","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, how is a conviction for driving under the influence of drugs treated?","o":["As a parking ticket","Like a DUI or DUAC conviction for alcohol","As a warning only","It is not a crime if the drug was prescribed"],"h1":"Drugs and alcohol are treated the same way here.","h2":"In South Carolina, a conviction for driving under the influence of drugs is treated like a DUI or DUAC conviction.","p":"Right. It is treated like an alcohol DUI."},"es":{"q":"En Carolina del Sur, ¿cómo se trata una condena por manejar bajo la influencia de drogas?","o":["Como una multa de estacionamiento","Igual que una condena por DUI o DUAC por alcohol","Solo como una advertencia","No es delito si la droga fue recetada"],"h1":"Aquí las drogas y el alcohol se tratan igual.","h2":"En Carolina del Sur, una condena por manejar bajo la influencia de drogas se trata igual que una condena por DUI o DUAC.","p":"Correcto. Se trata igual que un DUI por alcohol."},"ref":{"doc":"SC","page":"3-9"}},{"id":"sc-113","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, how often does the driver's manual say to check your tire pressure with a gauge?","o":["Once a year","Only at oil changes","Monthly","Only when a tire looks flat"],"h1":"It is a regular habit, about twelve times a year.","h2":"In South Carolina, the driver's manual says to check your tire pressure with a gauge every month, when the tires are cold.","p":"Right. Check the tire pressure monthly."},"es":{"q":"En Carolina del Sur, ¿cada cuánto dice el manual que revise la presión de las llantas con un medidor?","o":["Una vez al año","Solo en los cambios de aceite","Cada mes","Solo cuando una llanta se ve baja"],"h1":"Es un hábito regular, unas doce veces al año.","h2":"En Carolina del Sur, el manual dice que revise la presión de las llantas con un medidor cada mes, con las llantas frías.","p":"Correcto. Revise la presión cada mes."},"ref":{"doc":"SC","page":"4-1"}},{"id":"sc-114","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, you put a penny head-first into your tire tread and can see all of Lincoln's head. What does it mean?","o":["The tread is deep and safe","The tire pressure is too high","The tires need to be rotated only","The tires are too worn; replace them"],"h1":"Deep tread would cover part of his head.","h2":"In South Carolina, if you can see all of Lincoln's head in the penny test, your tires are too worn and should be replaced.","p":"Right. Seeing all of his head means the tires are worn out."},"es":{"q":"En Carolina del Sur, usted mete un centavo de cabeza en la banda de rodamiento de la llanta y ve toda la cabeza de Lincoln. ¿Qué significa?","o":["La banda es profunda y segura","La presión está demasiado alta","Las llantas solo necesitan rotarse","Las llantas están muy gastadas; cámbielas"],"h1":"Una banda profunda taparía parte de su cabeza.","h2":"En Carolina del Sur, si en la prueba del centavo ve toda la cabeza de Lincoln, sus llantas están muy gastadas y se deben cambiar.","p":"Correcto. Ver toda la cabeza significa que las llantas están gastadas."},"ref":{"doc":"SC","page":"4-2"}},{"id":"sc-115","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, how much space does the driver's manual say to keep between your chest and the steering wheel?","o":["At least 2 inches","At least 4 inches","At least 10 inches","At least 24 inches"],"h1":"It leaves room for the air bag to open.","h2":"In South Carolina, the driver's manual says to keep at least 10 inches between your chest and the steering wheel.","p":"Right. Keep at least 10 inches."},"es":{"q":"En Carolina del Sur, ¿cuánto espacio dice el manual que debe haber entre su pecho y el volante?","o":["Al menos 2 pulgadas","Al menos 4 pulgadas","Al menos 10 pulgadas","Al menos 24 pulgadas"],"h1":"Deja espacio para que se abra la bolsa de aire.","h2":"En Carolina del Sur, el manual dice que debe haber al menos 10 pulgadas entre su pecho y el volante.","p":"Correcto. Deje al menos 10 pulgadas."},"ref":{"doc":"SC","page":"4-3"}},{"id":"sc-116","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, how high should the top of the steering wheel be when your seat is set right?","o":["No higher than the top of your shoulders","Level with your eyes","Above your head","Level with your belt"],"h1":"You should be able to see over it easily.","h2":"In South Carolina, the driver's manual says the top of the steering wheel should be no higher than the top of your shoulders.","p":"Right. No higher than your shoulders."},"es":{"q":"En Carolina del Sur, ¿a qué altura debe estar la parte de arriba del volante cuando su asiento está bien ajustado?","o":["No más alto que la parte de arriba de sus hombros","A la altura de sus ojos","Por encima de su cabeza","A la altura de su cinturón"],"h1":"Debe poder ver por encima con facilidad.","h2":"En Carolina del Sur, el manual dice que la parte de arriba del volante no debe estar más alta que la parte de arriba de sus hombros.","p":"Correcto. No más alto que sus hombros."},"ref":{"doc":"SC","page":"4-3"}},{"id":"sc-117","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, until what age must a baby ride in a rear-facing car seat (unless it outgrows the seat's limits)?","o":["Under 6 months old","Under 1 year old","Under 2 years old","Under 4 years old"],"h1":"After this birthday, the child may face forward.","h2":"In South Carolina, a child under two must ride in a rear-facing car seat in a rear seat until the child exceeds the seat maker's height or weight limit.","p":"Right. Children under two ride rear-facing."},"es":{"q":"En Carolina del Sur, ¿hasta qué edad debe un bebé ir en una silla de carro mirando hacia atrás (a menos que pase los límites de la silla)?","o":["Menos de 6 meses","Menos de 1 año","Menos de 2 años","Menos de 4 años"],"h1":"Después de este cumpleaños, el niño puede ir mirando hacia adelante.","h2":"En Carolina del Sur, un niño menor de dos años debe ir en una silla mirando hacia atrás en un asiento trasero hasta que pase el límite de altura o peso del fabricante.","p":"Correcto. Los menores de dos años van mirando hacia atrás."},"ref":{"doc":"SC","page":"4-7"}},{"id":"sc-118","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, a child has outgrown a forward-facing car seat. From what age does the child move to a booster seat?","o":["At least 1 year old","At least 2 years old","At least 4 years old","At least 10 years old"],"h1":"It is two years after the rear-facing stage usually ends.","h2":"In South Carolina, a child at least four who has outgrown the forward-facing seat must use a booster seat in a rear seat until an adult seat belt fits.","p":"Right. Booster seats start at age four."},"es":{"q":"En Carolina del Sur, un niño ya no cabe en su silla mirando hacia adelante. ¿Desde qué edad pasa a un asiento elevado (booster)?","o":["Al menos 1 año","Al menos 2 años","Al menos 4 años","Al menos 10 años"],"h1":"Es dos años después de que suele terminar la etapa mirando hacia atrás.","h2":"En Carolina del Sur, un niño de al menos cuatro años que ya no cabe en la silla mirando hacia adelante debe usar un asiento elevado en un asiento trasero hasta que le quede bien el cinturón de adulto.","p":"Correcto. El asiento elevado empieza a los cuatro años."},"ref":{"doc":"SC","page":"4-7"}},{"id":"sc-119","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, a driver hauls a load that is not tied down and pieces blow onto the road. What does the driver's manual say?","o":["It is legal if you drive slowly","It is a misdemeanor, with a fine and the cleanup cost","It is only a warning","Only trucks over 26,000 pounds must secure loads"],"h1":"A load counts as secure only when nothing can fall, shift or blow off.","h2":"In South Carolina, a driver who fails to secure a load is guilty of a misdemeanor and may face a fine and the cost of cleaning up the load.","p":"Right. An unsecured load is a misdemeanor."},"es":{"q":"En Carolina del Sur, un conductor lleva una carga sin amarrar y algunas piezas vuelan a la carretera. ¿Qué dice el manual?","o":["Es legal si maneja despacio","Es un delito menor, con multa y el costo de la limpieza","Es solo una advertencia","Solo los camiones de más de 26,000 libras deben asegurar la carga"],"h1":"Una carga está segura solo cuando nada se puede caer, mover o volar.","h2":"En Carolina del Sur, el conductor que no asegura la carga comete un delito menor y puede recibir una multa y pagar la limpieza de la carga.","p":"Correcto. Una carga sin asegurar es un delito menor."},"ref":{"doc":"SC","page":"4-8"}},{"id":"sc-120","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, which car features may you not use during your driving test?","o":["Turn signals","Headlights","Seat belts","Parking assist and cruise control"],"h1":"The examiner wants to see your own skills.","h2":"In South Carolina, you will not be allowed to use some safety features, such as parking assist and cruise control, during the driving test.","p":"Right. No parking assist or cruise control on the test."},"es":{"q":"En Carolina del Sur, ¿qué funciones del carro no puede usar durante su examen de manejo?","o":["Las direccionales","Las luces delanteras","Los cinturones de seguridad","La asistencia para estacionar y el control de velocidad crucero"],"h1":"El examinador quiere ver sus propias habilidades.","h2":"En Carolina del Sur, durante el examen de manejo no le dejarán usar algunas funciones, como la asistencia para estacionar y el control de velocidad crucero.","p":"Correcto. Nada de asistencia para estacionar ni control crucero en el examen."},"ref":{"doc":"SC","page":"4-9"}},{"id":"sc-121","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, where does the driver's manual say to place your hands on the steering wheel, thinking of it as a clock?","o":["One hand at 6 o'clock","Left hand at 7 to 9 o'clock, right hand at 3 to 5 o'clock","Left hand at 10, right hand at 2","Both hands at 12 o'clock"],"h1":"Lower positions keep your arms clear of the air bag.","h2":"In South Carolina, the driver's manual says to place your left hand at 7 to 9 o'clock and your right hand at 3 to 5 o'clock; 10 and 2 is not recommended with air bags.","p":"Right. Left at 7 to 9, right at 3 to 5."},"es":{"q":"En Carolina del Sur, pensando en el volante como un reloj, ¿dónde dice el manual que ponga las manos?","o":["Una mano en las 6","La izquierda entre las 7 y las 9, la derecha entre las 3 y las 5","La izquierda en las 10 y la derecha en las 2","Las dos manos en las 12"],"h1":"Las posiciones más bajas alejan sus brazos de la bolsa de aire.","h2":"En Carolina del Sur, el manual dice que ponga la mano izquierda entre las 7 y las 9 y la derecha entre las 3 y las 5; las 10 y las 2 no se recomiendan con bolsas de aire.","p":"Correcto. Izquierda entre 7 y 9, derecha entre 3 y 5."},"ref":{"doc":"SC","page":"5-2"}},{"id":"sc-122","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, the driver's manual says to use hand-to-hand (push/pull) steering for normal turns above about what speed?","o":["2 to 3 mph","10 to 15 mph","35 to 40 mph","55 to 60 mph"],"h1":"Below this speed, such as when parking, you use hand-over-hand.","h2":"In South Carolina, the driver's manual says to use hand-to-hand, or push/pull, steering during normal driving above 10 to 15 mph.","p":"Right. Push/pull steering is for speeds above 10 to 15 mph."},"es":{"q":"En Carolina del Sur, según el manual, ¿por encima de qué velocidad se usa la dirección mano a mano (empujar y jalar) en curvas normales?","o":["2 a 3 mph","10 a 15 mph","35 a 40 mph","55 a 60 mph"],"h1":"Por debajo de esta velocidad, como al estacionarse, se usa mano sobre mano.","h2":"En Carolina del Sur, el manual dice que se use la dirección mano a mano, o empujar y jalar, al manejar normalmente por encima de 10 a 15 mph.","p":"Correcto. Empujar y jalar es para más de 10 a 15 mph."},"ref":{"doc":"SC","page":"5-3"}},{"id":"sc-123","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, which steering method does the driver's manual say to use at low speeds, such as when parking?","o":["Hand-over-hand steering","One finger on the wheel","Palming the wheel with one hand","Steering from the inside of the rim"],"h1":"At higher speeds you use push/pull; this is the other main method.","h2":"In South Carolina, the driver's manual says to use hand-over-hand steering at low speeds, such as at an intersection or when parking.","p":"Right. Use hand-over-hand at low speeds."},"es":{"q":"En Carolina del Sur, ¿qué forma de mover el volante dice el manual que se use a baja velocidad, como al estacionarse?","o":["Mano sobre mano","Un dedo en el volante","Girar con la palma de una mano","Girar agarrando el volante por dentro del aro"],"h1":"A mayor velocidad se usa empujar y jalar; esta es la otra forma principal.","h2":"En Carolina del Sur, el manual dice que se use la forma mano sobre mano a baja velocidad, como en una intersección o al estacionarse.","p":"Correcto. Use mano sobre mano a baja velocidad."},"ref":{"doc":"SC","page":"5-4"}},{"id":"sc-124","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, how does the driver's manual say to sit and hold the wheel when backing straight up?","o":["Both hands at 10 and 2, looking only at the mirrors","Right hand at 6 o'clock, looking at the dashboard camera only","Both hands in your lap","Left hand at 12 o'clock, right arm on the passenger seat, looking through the rear window"],"h1":"You turn your body to look directly behind you.","h2":"In South Carolina, to back up you hold the wheel at 12 o'clock with your left hand, put your right arm on the back of the passenger seat, and look through the rear window.","p":"Right. Left hand at 12, turn, and look out the back window."},"es":{"q":"En Carolina del Sur, ¿cómo dice el manual que se siente y agarre el volante al dar reversa en línea recta?","o":["Las dos manos en las 10 y las 2, mirando solo los espejos","Mano derecha en las 6, mirando solo la cámara del tablero","Las dos manos en las piernas","Mano izquierda en las 12, brazo derecho en el asiento del pasajero, mirando por el vidrio de atrás"],"h1":"Usted gira el cuerpo para mirar directamente hacia atrás.","h2":"En Carolina del Sur, para dar reversa agarre el volante en las 12 con la mano izquierda, ponga el brazo derecho en el respaldo del asiento del pasajero y mire por el vidrio de atrás.","p":"Correcto. Mano izquierda en las 12, gírese y mire por el vidrio de atrás."},"ref":{"doc":"SC","page":"5-5"}},{"id":"sc-125","scope":"SC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Carolina, you are pulling out of a private driveway onto a public road. Who has the right-of-way?","o":["The drivers already on the public road","You do, because you are moving first","Whoever is larger","Whoever honks first"],"h1":"Traffic on the main road does not stop for you.","h2":"In South Carolina, a driver entering a public highway from a driveway or private road must yield to drivers already on the highway.","p":"Right. Yield to the traffic on the road."},"es":{"q":"En Carolina del Sur, usted sale de una entrada privada a una calle pública. ¿Quién tiene el derecho de paso?","o":["Los conductores que ya están en la calle pública","Usted, porque se mueve primero","El vehículo más grande","El primero que toque la bocina"],"h1":"El tráfico de la calle principal no se detiene por usted.","h2":"En Carolina del Sur, el conductor que entra a una vía pública desde una entrada o camino privado debe ceder el paso a los conductores que ya están en la vía.","p":"Correcto. Ceda el paso al tráfico de la calle."},"ref":{"doc":"SC","page":"6-2"}},{"id":"sc-126","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, what is special about a diverging diamond interchange (DDI)?","o":["It has no traffic signals at all","Every driver must make a U-turn","It is a roundabout with four lanes","Traffic briefly crosses to the left side of the road, so left turns onto ramps do not cross oncoming traffic"],"h1":"The design moves the cross street's traffic to the other side between two signals.","h2":"In South Carolina, a diverging diamond interchange shifts cross-street traffic to the left side between signals, so drivers turning left to or from the ramps do not cross oncoming traffic.","p":"Right. Traffic crosses to the left so left turns are safer."},"es":{"q":"En Carolina del Sur, ¿qué tiene de especial un intercambio de diamante divergente (DDI)?","o":["No tiene ningún semáforo","Todos deben dar vuelta en U","Es una glorieta de cuatro carriles","El tráfico pasa por un tramo al lado izquierdo de la calle, así las vueltas a la izquierda hacia las rampas no cruzan el tráfico de frente"],"h1":"El diseño pasa el tráfico de la calle transversal al otro lado entre dos semáforos.","h2":"En Carolina del Sur, un intercambio de diamante divergente pasa el tráfico de la calle transversal al lado izquierdo entre semáforos, así quienes dan vuelta a la izquierda hacia o desde las rampas no cruzan el tráfico de frente.","p":"Correcto. El tráfico pasa a la izquierda para que las vueltas a la izquierda sean más seguras."},"ref":{"doc":"SC","page":"7-5"}},{"id":"sc-127","scope":"SC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Carolina, you are on a side street at a restricted crossing U-turn (RCUT) intersection and want to go left. What do you do?","o":["Turn right onto the main road, then make a U-turn at a median opening","Turn left straight across the main road","Back up to the next street","Wait for a police officer"],"h1":"Left turns and straight crossings from the side street are removed.","h2":"In South Carolina, at an RCUT intersection drivers from the side street turn right onto the main road and then make a U-turn at a one-way median opening.","p":"Right. Turn right, then U-turn at the median."},"es":{"q":"En Carolina del Sur, usted está en una calle lateral en una intersección de vuelta en U restringida (RCUT) y quiere ir a la izquierda. ¿Qué hace?","o":["Da vuelta a la derecha en la calle principal y luego da vuelta en U en una abertura de la mediana","Da vuelta a la izquierda cruzando la calle principal","Da reversa hasta la próxima calle","Espera a un policía"],"h1":"Las vueltas a la izquierda y los cruces rectos desde la calle lateral están eliminados.","h2":"En Carolina del Sur, en una intersección RCUT los conductores de la calle lateral dan vuelta a la derecha en la calle principal y luego dan vuelta en U en una abertura de la mediana de un solo sentido.","p":"Correcto. A la derecha y luego vuelta en U en la mediana."},"ref":{"doc":"SC","page":"7-6"}},{"id":"sc-128","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, why does the driver's manual say roundabouts are safer than traditional intersections?","o":["They let drivers go faster","They remove head-on and high-speed right-angle crashes","They have no pedestrians","Drivers never have to yield"],"h1":"Think about which crash types cannot happen when everyone circles the same way.","h2":"In South Carolina, the driver's manual says roundabouts are safer because they eliminate head-on and high-speed right-angle collisions.","p":"Right. Roundabouts remove head-on and high-speed side crashes."},"es":{"q":"En Carolina del Sur, ¿por qué dice el manual que las glorietas son más seguras que las intersecciones tradicionales?","o":["Dejan manejar más rápido","Eliminan los choques de frente y los choques en ángulo recto a alta velocidad","No tienen peatones","Nunca hay que ceder el paso"],"h1":"Piense en qué choques no pueden pasar cuando todos circulan en la misma dirección.","h2":"En Carolina del Sur, el manual dice que las glorietas son más seguras porque eliminan los choques de frente y los choques en ángulo recto a alta velocidad.","p":"Correcto. Las glorietas eliminan los choques de frente y los laterales a alta velocidad."},"ref":{"doc":"SC","page":"7-8"}},{"id":"sc-129","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, you are on a two-lane road. A school bus coming toward you stops with its red lights flashing. What must you do?","o":["Keep going, since you are going the other way","Slow to 25 mph and pass","Stop until the bus moves or the red lights stop flashing","Honk and drive around it"],"h1":"On a two-lane road, traffic in both directions has to stop.","h2":"In South Carolina, you must stop for a stopped school bus on a two-lane road, even when you are coming from the opposite direction.","p":"Right. On a two-lane road, both directions stop."},"es":{"q":"En Carolina del Sur, usted va por una calle de dos carriles. Un autobús escolar que viene de frente se detiene con las luces rojas encendidas. ¿Qué debe hacer?","o":["Seguir, porque va en sentido contrario","Bajar a 25 mph y pasar","Detenerse hasta que el autobús avance o las luces rojas se apaguen","Tocar la bocina y rodearlo"],"h1":"En una calle de dos carriles, el tráfico en los dos sentidos debe detenerse.","h2":"En Carolina del Sur, debe detenerse ante un autobús escolar detenido en una calle de dos carriles, aunque venga en sentido contrario.","p":"Correcto. En una calle de dos carriles, los dos sentidos se detienen."},"ref":{"doc":"SC","page":"7-9"}},{"id":"sc-130","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, your car has a disability placard issued to your grandmother. When may you park in a disability space?","o":["Any time you use her car","Only at night","Any time, if you leave the hazard lights on","Only when you are driving her or she is with you"],"h1":"The placard belongs to the person, not the car.","h2":"In South Carolina, a vehicle with a disability plate or placard may use a disability space only when it is driven by or carrying the person whose name is on the registration.","p":"Right. Only when the person with the disability is with you."},"es":{"q":"En Carolina del Sur, su carro tiene un permiso de discapacidad a nombre de su abuela. ¿Cuándo puede estacionarse en un espacio para personas con discapacidad?","o":["Cada vez que use el carro de ella","Solo de noche","Siempre, si deja las luces de emergencia encendidas","Solo cuando la lleva a ella o ella va con usted"],"h1":"El permiso es de la persona, no del carro.","h2":"En Carolina del Sur, un vehículo con placa o permiso de discapacidad puede usar esos espacios solo cuando lo maneja o lleva a la persona cuyo nombre aparece en el registro.","p":"Correcto. Solo cuando la persona con discapacidad va con usted."},"ref":{"doc":"SC","page":"7-10"}},{"id":"sc-131","scope":"SC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Carolina, you park facing downhill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb (to the right)","Away from the curb","Straight ahead","It does not matter"],"h1":"If the car rolls, the curb should stop it.","h2":"In South Carolina, when parked facing downhill, with or without a curb, turn your wheels to the right, toward the curb.","p":"Right. Downhill, turn the wheels toward the curb."},"es":{"q":"En Carolina del Sur, usted se estaciona cuesta abajo junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la acera (a la derecha)","Lejos de la acera","Rectas","No importa"],"h1":"Si el carro rueda, la acera lo debe detener.","h2":"En Carolina del Sur, al estacionarse cuesta abajo, con o sin acera, gire las llantas a la derecha, hacia la acera.","p":"Correcto. Cuesta abajo, llantas hacia la acera."},"ref":{"doc":"SC","page":"7-13"}},{"id":"sc-132","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Away from the curb, so the back of the tire rests against it","Straight ahead","All the way to the right"],"h1":"If the car rolls back, the curb should catch the back of the tire.","h2":"In South Carolina, when parked uphill with a curb, turn your wheels toward the center of the street so the back of the front tire rests against the curb.","p":"Right. Uphill with a curb, turn the wheels away from it."},"es":{"q":"En Carolina del Sur, usted se estaciona cuesta arriba junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la acera","Lejos de la acera, para que la parte de atrás de la llanta quede contra ella","Rectas","Todo a la derecha"],"h1":"Si el carro rueda hacia atrás, la acera debe atrapar la parte de atrás de la llanta.","h2":"En Carolina del Sur, al estacionarse cuesta arriba con acera, gire las llantas hacia el centro de la calle para que la parte de atrás de la llanta delantera quede contra la acera.","p":"Correcto. Cuesta arriba con acera, llantas lejos de ella."},"ref":{"doc":"SC","page":"7-13"}},{"id":"sc-133","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, you park a car with a manual transmission on a hill. Which gear should you leave it in?","o":["Neutral","Third","First or reverse","Fifth"],"h1":"Pick a low gear that holds the car.","h2":"In South Carolina, a car with a manual transmission should be parked in first or reverse, with the parking brake set and the engine off.","p":"Right. Leave a manual car in first or reverse."},"es":{"q":"En Carolina del Sur, usted estaciona un carro de transmisión manual en una cuesta. ¿En qué cambio debe dejarlo?","o":["Neutro","Tercera","Primera o reversa","Quinta"],"h1":"Escoja un cambio bajo que sostenga el carro.","h2":"En Carolina del Sur, un carro de transmisión manual se debe estacionar en primera o en reversa, con el freno de mano puesto y el motor apagado.","p":"Correcto. Deje un carro manual en primera o reversa."},"ref":{"doc":"SC","page":"7-13"}},{"id":"sc-134","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, traffic ahead is slow and the paved shoulder is empty. May you use the shoulder to pass?","o":["Yes, if it is paved","Yes, if you use your turn signal","Yes, if you go under 25 mph","No, never pass on the shoulder, paved or not"],"h1":"The shoulder is for emergency stops.","h2":"In South Carolina, you must never pass on the shoulder, whether it is paved or not; it is an emergency stopping lane.","p":"Right. Never pass on the shoulder."},"es":{"q":"En Carolina del Sur, el tráfico de adelante va lento y el acotamiento pavimentado está vacío. ¿Puede usar el acotamiento para rebasar?","o":["Sí, si está pavimentado","Sí, si pone la direccional","Sí, si va a menos de 25 mph","No, nunca rebase por el acotamiento, esté pavimentado o no"],"h1":"El acotamiento es para paradas de emergencia.","h2":"En Carolina del Sur, nunca debe rebasar por el acotamiento, esté pavimentado o no; es un carril para paradas de emergencia.","p":"Correcto. Nunca rebase por el acotamiento."},"ref":{"doc":"SC","page":"7-15"}},{"id":"sc-135","scope":"SC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Carolina, another car is passing you. What should you do?","o":["Stay in your lane and keep a steady speed","Speed up so they cannot pass","Move onto the shoulder","Brake hard right away"],"h1":"Make it easy for the other driver to finish the pass.","h2":"In South Carolina, when you are being passed, stay in your lane and keep a constant speed so the other driver can pass you.","p":"Right. Stay in your lane at a steady speed."},"es":{"q":"En Carolina del Sur, otro carro le está rebasando. ¿Qué debe hacer?","o":["Quedarse en su carril y mantener una velocidad constante","Acelerar para que no pueda rebasar","Pasarse al acotamiento","Frenar fuerte de inmediato"],"h1":"Facilítele al otro conductor terminar de rebasar.","h2":"En Carolina del Sur, cuando le rebasan, quédese en su carril y mantenga una velocidad constante para que el otro conductor pueda pasar.","p":"Correcto. Quédese en su carril a velocidad constante."},"ref":{"doc":"SC","page":"7-16"}},{"id":"sc-136","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, where does the driver's manual say you should not try to pass, even on a road with a broken line?","o":["On a long straight road with a clear view","Just before a railroad crossing or a bridge","On a road with two lanes going your way","When the car ahead is going well under the limit"],"h1":"Think of places where there is little room or a hidden danger.","h2":"In South Carolina, do not pass when an oncoming vehicle is near, when a curve or hill blocks your view, at intersections, or before a railroad crossing or bridge.","p":"Right. Do not pass before a railroad crossing or bridge."},"es":{"q":"En Carolina del Sur, ¿dónde dice el manual que no debe intentar rebasar, aunque la línea sea discontinua?","o":["En una recta larga con buena vista","Justo antes de un cruce de tren o un puente","En una calle con dos carriles en su sentido","Cuando el carro de adelante va muy por debajo del límite"],"h1":"Piense en lugares con poco espacio o un peligro escondido.","h2":"En Carolina del Sur, no rebase cuando viene un vehículo de frente, cuando una curva o loma tapa la vista, en intersecciones, ni antes de un cruce de tren o un puente.","p":"Correcto. No rebase antes de un cruce de tren o un puente."},"ref":{"doc":"SC","page":"7-16"}},{"id":"sc-137","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, traffic is backing up where a lane closes ahead. What does the driver's manual call the best practice?","o":["Move over at the first sign, then block the closing lane","Stop and wait for a gap at the start of the backup","Use both lanes up to the merge point, then take turns merging (zipper merge)","Drive on the shoulder past the line"],"h1":"Picture the teeth of a zipper closing.","h2":"In South Carolina, the driver's manual recommends the zipper merge: when traffic is backing up, stay in your lane until the merge point, then take turns moving into the open lane.","p":"Right. Use both lanes, then take turns at the merge point."},"es":{"q":"En Carolina del Sur, el tráfico se está acumulando donde se cierra un carril más adelante. ¿Qué llama el manual la mejor práctica?","o":["Cambiarse al primer aviso y luego bloquear el carril que se cierra","Detenerse y esperar un espacio al principio de la fila","Usar los dos carriles hasta el punto de unión y luego turnarse para entrar (unión en cremallera)","Manejar por el acotamiento hasta pasar la fila"],"h1":"Imagine los dientes de una cremallera al cerrarse.","h2":"En Carolina del Sur, el manual recomienda la unión en cremallera: cuando el tráfico se acumula, quédese en su carril hasta el punto de unión y luego túrnese para entrar al carril abierto.","p":"Correcto. Use los dos carriles y túrnese en el punto de unión."},"ref":{"doc":"SC","page":"7-17"}},{"id":"sc-138","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, a lane will close ahead, but traffic is moving at highway speed with no backup. What does the driver's manual suggest?","o":["Stay in the closing lane until the very end","Stop at the merge point","Speed up past the other lane","Move to the lane that stays open sooner"],"h1":"The zipper merge is for slow, heavy traffic.","h2":"In South Carolina, when traffic is moving at highway speeds and there is no backup, it makes sense to move sooner into the lane that will stay open.","p":"Right. At highway speed with no backup, merge early."},"es":{"q":"En Carolina del Sur, un carril se va a cerrar más adelante, pero el tráfico va a velocidad de autopista sin fila. ¿Qué sugiere el manual?","o":["Quedarse en el carril que se cierra hasta el final","Detenerse en el punto de unión","Acelerar para pasar al otro carril","Pasarse antes al carril que sigue abierto"],"h1":"La unión en cremallera es para tráfico lento y pesado.","h2":"En Carolina del Sur, cuando el tráfico va a velocidad de autopista y no hay fila, conviene pasarse antes al carril que seguirá abierto.","p":"Correcto. A velocidad de autopista sin fila, únase temprano."},"ref":{"doc":"SC","page":"7-18"}},{"id":"sc-139","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, how far ahead does the driver's manual say you should try to look while driving?","o":["1 to 2 seconds ahead","5 seconds ahead","20 to 30 seconds ahead","2 minutes ahead"],"h1":"Looking far ahead gives you time to plan.","h2":"In South Carolina, the driver's manual says you should try to look at what is happening 20 to 30 seconds in front of your vehicle.","p":"Right. Look 20 to 30 seconds ahead."},"es":{"q":"En Carolina del Sur, ¿qué tan adelante dice el manual que trate de mirar mientras maneja?","o":["De 1 a 2 segundos adelante","5 segundos adelante","De 20 a 30 segundos adelante","2 minutos adelante"],"h1":"Mirar lejos le da tiempo para planear.","h2":"En Carolina del Sur, el manual dice que trate de mirar lo que pasa de 20 a 30 segundos delante de su vehículo.","p":"Correcto. Mire de 20 a 30 segundos adelante."},"ref":{"doc":"SC","page":"8-1"}},{"id":"sc-140","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, the driver's manual warns that how much water can reach the bottom of most passenger cars and cause stalling or loss of control?","o":["1 inch","6 inches","18 inches","30 inches"],"h1":"It is only about half a foot.","h2":"In South Carolina, the driver's manual says six inches of water will reach the bottom of most passenger cars and can cause loss of control or stalling.","p":"Right. Just six inches of water is enough."},"es":{"q":"En Carolina del Sur, según el manual, ¿cuánta agua puede llegar a la parte de abajo de la mayoría de los carros y hacer que se apaguen o se pierda el control?","o":["1 pulgada","6 pulgadas","18 pulgadas","30 pulgadas"],"h1":"Es solo como medio pie.","h2":"En Carolina del Sur, el manual dice que seis pulgadas de agua llegan a la parte de abajo de la mayoría de los carros y pueden hacer que se apaguen o se pierda el control.","p":"Correcto. Solo seis pulgadas de agua bastan."},"ref":{"doc":"SC","page":"8-4"}},{"id":"sc-141","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, the driver's manual says an alert driver usually takes how long to notice the need to stop (perception time)?","o":["1/10 of a second","3/4 of a second to 1 second","3 to 4 seconds","10 seconds"],"h1":"It is less than the time it takes to say your name.","h2":"In South Carolina, the driver's manual says the average perception time for an alert driver is three-quarters of a second to one second.","p":"Right. Perception takes about three-quarters of a second to a second."},"es":{"q":"En Carolina del Sur, según el manual, ¿cuánto tarda normalmente un conductor alerta en darse cuenta de que debe frenar (tiempo de percepción)?","o":["1/10 de segundo","De 3/4 de segundo a 1 segundo","De 3 a 4 segundos","10 segundos"],"h1":"Es menos de lo que tarda en decir su nombre.","h2":"En Carolina del Sur, el manual dice que el tiempo de percepción promedio de un conductor alerta es de tres cuartos de segundo a un segundo.","p":"Correcto. La percepción toma de tres cuartos de segundo a un segundo."},"ref":{"doc":"SC","page":"8-5"}},{"id":"sc-142","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, the driver's manual says that at 50 mph on dry pavement with good brakes, braking alone can take about how far?","o":["20 feet","50 feet","158 feet","500 feet"],"h1":"It is about half the length of a football field.","h2":"In South Carolina, the driver's manual says braking distance at 50 mph on dry pavement with good brakes can be about 158 feet.","p":"Right. About 158 feet just for braking."},"es":{"q":"En Carolina del Sur, según el manual, a 50 mph en pavimento seco y con buenos frenos, ¿más o menos qué distancia puede tomar solo el frenado?","o":["20 pies","50 pies","158 pies","500 pies"],"h1":"Es como la mitad de una cancha de fútbol americano.","h2":"En Carolina del Sur, el manual dice que la distancia de frenado a 50 mph en pavimento seco con buenos frenos puede ser de unos 158 pies.","p":"Correcto. Unos 158 pies solo para frenar."},"ref":{"doc":"SC","page":"8-5"}},{"id":"sc-143","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, a tractor-trailer is passing you on the highway. What does the driver's manual suggest?","o":["Move to the side of your lane away from the truck as it passes","Speed up to stay beside it","Move closer to the truck","Brake hard in your lane"],"h1":"Give the big truck a little more room.","h2":"In South Carolina, when a tractor-trailer passes you, move to the outside part of your lane, away from the truck, to leave a little more space.","p":"Right. Move to the far side of your lane."},"es":{"q":"En Carolina del Sur, un tráiler le está rebasando en la autopista. ¿Qué sugiere el manual?","o":["Moverse al lado de su carril más lejos del camión mientras pasa","Acelerar para ir a su lado","Acercarse al camión","Frenar fuerte en su carril"],"h1":"Dele un poco más de espacio al camión grande.","h2":"En Carolina del Sur, cuando un tráiler le rebasa, muévase a la parte de su carril más lejos del camión para dejar un poco más de espacio.","p":"Correcto. Muévase al lado lejano de su carril."},"ref":{"doc":"SC","page":"8-8"}},{"id":"sc-144","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, the driver's manual says you should not use your horn near whom?","o":["Other drivers who are not paying attention","Bicyclists moving into your lane right in front of you","Drivers starting to turn into your lane","Blind pedestrians"],"h1":"A sudden loud sound can confuse someone who relies on hearing.","h2":"In South Carolina, the driver's manual says you should not use your horn near blind pedestrians.","p":"Right. Do not honk near blind pedestrians."},"es":{"q":"En Carolina del Sur, según el manual, ¿cerca de quién no debe usar la bocina?","o":["Otros conductores distraídos","Ciclistas que se meten en su carril justo delante de usted","Conductores que empiezan a meterse en su carril","Peatones ciegos"],"h1":"Un ruido fuerte y repentino puede confundir a quien se guía por el oído.","h2":"En Carolina del Sur, el manual dice que no debe usar la bocina cerca de peatones ciegos.","p":"Correcto. No toque la bocina cerca de peatones ciegos."},"ref":{"doc":"SC","page":"8-9"}},{"id":"sc-145","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, your car breaks down on the highway and you have flares. How far behind the car does the driver's manual say to place them?","o":["About 10 to 20 feet","About 50 feet","About 200 to 300 feet","About 1 mile"],"h1":"Give other drivers time to change lanes.","h2":"In South Carolina, the driver's manual says to place emergency flares about 200 to 300 feet behind your disabled vehicle.","p":"Right. Put flares about 200 to 300 feet back."},"es":{"q":"En Carolina del Sur, su carro se descompone en la autopista y usted tiene bengalas. ¿A qué distancia detrás del carro dice el manual que las ponga?","o":["Unos 10 a 20 pies","Unos 50 pies","Unos 200 a 300 pies","Una milla"],"h1":"Dele tiempo a los otros conductores para cambiar de carril.","h2":"En Carolina del Sur, el manual dice que ponga las bengalas de emergencia unos 200 a 300 pies detrás de su vehículo descompuesto.","p":"Correcto. Ponga las bengalas unos 200 a 300 pies atrás."},"ref":{"doc":"SC","page":"9-5"}},{"id":"sc-146","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, why should you add emergency contact information to your SCDMV record online?","o":["So officers can reach your contacts if you are in a crash or medical emergency","To lower your insurance rate","To remove points from your record","So you can skip the vision test"],"h1":"It helps the people who respond to an emergency.","h2":"In South Carolina, if you enter emergency contacts on your SCDMV record, law enforcement can see them after a crash or medical emergency and may share them with medical staff.","p":"Right. It lets officers reach your contacts in an emergency."},"es":{"q":"En Carolina del Sur, ¿por qué debe agregar contactos de emergencia a su historial del SCDMV por internet?","o":["Para que la policía pueda avisar a sus contactos si tiene un choque o una emergencia médica","Para bajar el precio de su seguro","Para quitar puntos de su historial","Para no tener que hacer el examen de la vista"],"h1":"Ayuda a quienes atienden una emergencia.","h2":"En Carolina del Sur, si pone contactos de emergencia en su historial del SCDMV, la policía puede verlos después de un choque o emergencia médica y compartirlos con el personal médico.","p":"Correcto. Así la policía puede avisar a sus contactos en una emergencia."},"ref":{"doc":"SC","page":"9-6"}},{"id":"sc-147","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, a person with a white cane or a guide dog is crossing the street ahead. What must you do?","o":["Slow down and drive around them","Honk so they know you are there","Keep going if you have a green light","Come to a complete stop"],"h1":"The law gives these pedestrians the right-of-way every time.","h2":"In South Carolina, you must always yield to visually impaired pedestrians, and come to a complete stop when someone crosses with a guide dog or a white cane.","p":"Right. Stop completely for a white cane or guide dog."},"es":{"q":"En Carolina del Sur, una persona con bastón blanco o perro guía está cruzando la calle adelante. ¿Qué debe hacer?","o":["Bajar la velocidad y rodearla","Tocar la bocina para que sepa que usted está ahí","Seguir si tiene luz verde","Detenerse por completo"],"h1":"La ley les da el derecho de paso a estos peatones siempre.","h2":"En Carolina del Sur, siempre debe ceder el paso a los peatones con discapacidad visual, y detenerse por completo cuando alguien cruza con perro guía o bastón blanco.","p":"Correcto. Deténgase por completo ante un bastón blanco o un perro guía."},"ref":{"doc":"SC","page":"10-1"}},{"id":"sc-148","scope":"SC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Carolina, when may you drive in a marked bicycle lane?","o":["Only to enter or leave a driveway or alley, or when an officer or an emergency requires it","Whenever traffic is slow","To pass a car turning left","Any time no bicycle is in sight"],"h1":"A bike lane is not an extra lane for cars.","h2":"In South Carolina, you may not stop, park or drive in a bicycle lane except to enter or leave an alley or driveway, on official duty, when directed by police, or in an emergency.","p":"Right. Only to reach a driveway or alley, or in special cases."},"es":{"q":"En Carolina del Sur, ¿cuándo puede manejar en un carril para bicicletas marcado?","o":["Solo para entrar o salir de una entrada o callejón, o cuando un policía o una emergencia lo exige","Cuando el tráfico va lento","Para rebasar a un carro que da vuelta a la izquierda","Cuando no se ve ninguna bicicleta"],"h1":"Un carril para bicicletas no es un carril extra para carros.","h2":"En Carolina del Sur, no puede detenerse, estacionarse ni manejar en un carril para bicicletas, salvo para entrar o salir de un callejón o entrada, en servicio oficial, si la policía se lo indica o en una emergencia.","p":"Correcto. Solo para llegar a una entrada o callejón, o en casos especiales."},"ref":{"doc":"SC","page":"10-3"}},{"id":"sc-149","scope":"SC","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Carolina, you parked on the street. What should you do before opening your car door?","o":["Honk twice","Check to the sides and rear for bicyclists","Turn on your high beams","Nothing; riders must watch for doors"],"h1":"A door opened in front of a bike can cause a bad crash.","h2":"In South Carolina, when parked on the street, check to the sides and rear for bicyclists before you open your door.","p":"Right. Look for bicyclists before opening the door."},"es":{"q":"En Carolina del Sur, usted se estacionó en la calle. ¿Qué debe hacer antes de abrir la puerta del carro?","o":["Tocar la bocina dos veces","Mirar a los lados y hacia atrás por si vienen ciclistas","Prender las luces altas","Nada; los ciclistas deben cuidarse de las puertas"],"h1":"Una puerta abierta delante de una bicicleta puede causar un choque grave.","h2":"En Carolina del Sur, cuando está estacionado en la calle, mire a los lados y hacia atrás por si vienen ciclistas antes de abrir la puerta.","p":"Correcto. Busque ciclistas antes de abrir la puerta."},"ref":{"doc":"SC","page":"10-5"}},{"id":"sc-150","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, the blind spot directly behind a large truck can stretch back up to how far?","o":["10 feet","50 feet","200 feet","1,000 feet"],"h1":"It is about two-thirds of a football field.","h2":"In South Carolina, the driver's manual says the rear no zone behind a large vehicle can extend up to 200 feet.","p":"Right. The rear no zone can reach 200 feet."},"es":{"q":"En Carolina del Sur, ¿hasta qué distancia puede llegar el punto ciego justo detrás de un camión grande?","o":["10 pies","50 pies","200 pies","1,000 pies"],"h1":"Es como dos tercios de una cancha de fútbol americano.","h2":"En Carolina del Sur, el manual dice que la zona ciega de atrás de un vehículo grande puede llegar hasta 200 pies.","p":"Correcto. La zona ciega de atrás puede llegar a 200 pies."},"ref":{"doc":"SC","page":"10-9"}},{"id":"sc-151","scope":"SC","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Carolina, the driver's manual suggests avoiding the right lane when possible in which places?","o":["In school zones","On any road with a speed limit over 45","Near rest areas only at night","On steep hills and near truck weigh stations"],"h1":"Think of where slow trucks drive or try to rejoin traffic.","h2":"In South Carolina, large trucks go slowly on steep hills and re-enter traffic near weigh stations, so avoid the right lane there when you can.","p":"Right. Avoid the right lane on steep hills and near weigh stations."},"es":{"q":"En Carolina del Sur, ¿en qué lugares sugiere el manual evitar el carril derecho cuando se pueda?","o":["En zonas escolares","En cualquier calle con límite de más de 45","Cerca de áreas de descanso solo de noche","En cuestas empinadas y cerca de las básculas para camiones"],"h1":"Piense en dónde los camiones van lentos o tratan de volver al tráfico.","h2":"En Carolina del Sur, los camiones grandes van despacio en cuestas empinadas y vuelven al tráfico cerca de las básculas, así que evite allí el carril derecho cuando pueda.","p":"Correcto. Evite el carril derecho en cuestas empinadas y cerca de las básculas."},"ref":{"doc":"SC","page":"10-10"}},{"id":"sc-152","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, a large truck is coming toward you on a two-lane road. What should you do?","o":["Keep as far to the right as you safely can","Move toward the center line","Speed up to pass it quickly","Flash your high beams"],"h1":"The wind between the two vehicles pushes them apart.","h2":"In South Carolina, when you meet a truck from the opposite direction, keep as far right as possible to avoid a sideswipe and reduce wind turbulence.","p":"Right. Keep well to the right."},"es":{"q":"En Carolina del Sur, un camión grande viene de frente en una calle de dos carriles. ¿Qué debe hacer?","o":["Mantenerse lo más a la derecha que pueda con seguridad","Acercarse a la línea central","Acelerar para pasarlo rápido","Hacer cambio de luces altas"],"h1":"El viento entre los dos vehículos los empuja hacia los lados.","h2":"En Carolina del Sur, cuando se cruza con un camión que viene de frente, manténgase lo más a la derecha posible para evitar un roce y reducir la turbulencia del viento.","p":"Correcto. Manténgase bien a la derecha."},"ref":{"doc":"SC","page":"10-11"}},{"id":"sc-153","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, an officer pulls you over at night. What does the driver's manual suggest you do once you stop?","o":["Get out and walk to the police car","Turn on your interior lights","Look for your papers in the glove box right away","Turn on your high beams"],"h1":"Help the officer see inside your car.","h2":"In South Carolina, if you are stopped at night, turn on your interior lights as soon as you stop so the officer can see inside the vehicle.","p":"Right. Turn on the interior lights."},"es":{"q":"En Carolina del Sur, un policía le detiene de noche. ¿Qué sugiere el manual que haga una vez detenido?","o":["Bajarse y caminar hacia la patrulla","Prender las luces de adentro del carro","Buscar sus papeles en la guantera de inmediato","Prender las luces altas"],"h1":"Ayude al policía a ver dentro de su carro.","h2":"En Carolina del Sur, si le detienen de noche, prenda las luces interiores en cuanto se detenga para que el policía pueda ver dentro del vehículo.","p":"Correcto. Prenda las luces interiores."},"ref":{"doc":"SC","page":"10-13"}},{"id":"sc-154","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, you are stopped by an officer and have a gun in the car. When should you tell the officer?","o":["Only if the officer asks","Only after you get a ticket","Never","At first contact"],"h1":"Telling early keeps everyone calm and safe.","h2":"In South Carolina, if you have one or more weapons in the vehicle, tell the officer about all of them at first contact.","p":"Right. Tell the officer at first contact."},"es":{"q":"En Carolina del Sur, un policía le detiene y usted tiene un arma en el carro. ¿Cuándo se lo debe decir?","o":["Solo si el policía le pregunta","Solo después de recibir la multa","Nunca","En el primer contacto"],"h1":"Decirlo pronto mantiene a todos tranquilos y seguros.","h2":"En Carolina del Sur, si tiene una o más armas en el vehículo, informe al policía sobre todas en el primer contacto.","p":"Correcto. Dígaselo al policía en el primer contacto."},"ref":{"doc":"SC","page":"10-12"}},{"id":"sc-155","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, an officer hands you a traffic ticket and you think it is wrong. What does accepting the ticket mean?","o":["It is not an admission of guilt; you can explain in court","It means you admit you are guilty","It means you must pay on the spot","It cancels your right to a court date"],"h1":"Arguing at the roadside does not help.","h2":"In South Carolina, accepting a traffic ticket is not an admission of guilt, and you can contest it in court.","p":"Right. Taking the ticket does not mean you admit guilt."},"es":{"q":"En Carolina del Sur, un policía le da una multa y usted cree que está equivocada. ¿Qué significa aceptar la multa?","o":["No es admitir culpa; puede explicarse en la corte","Significa que admite que es culpable","Significa que debe pagar ahí mismo","Cancela su derecho a ir a la corte"],"h1":"Discutir al lado de la carretera no ayuda.","h2":"En Carolina del Sur, aceptar una multa de tránsito no es admitir culpa, y puede disputarla en la corte.","p":"Correcto. Aceptar la multa no es admitir culpa."},"ref":{"doc":"SC","page":"10-13"}},{"id":"sc-156","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, you are pulled over by a car with no police markings and the driver is not in uniform. What may you do?","o":["Drive away","Ask to see the officer's law enforcement credentials","Refuse to roll down the window at all","Get out and walk away"],"h1":"You have a right to know the person is a real officer.","h2":"In South Carolina, if the officer is in an unmarked vehicle or not in uniform, you may ask to see the officer's law enforcement credentials.","p":"Right. Ask to see the credentials."},"es":{"q":"En Carolina del Sur, le detiene un carro sin marcas de policía y el conductor no lleva uniforme. ¿Qué puede hacer?","o":["Irse manejando","Pedir ver la identificación oficial del policía","Negarse a bajar la ventana","Bajarse y alejarse caminando"],"h1":"Usted tiene derecho a saber que es un policía de verdad.","h2":"En Carolina del Sur, si el policía va en un vehículo sin marcas o sin uniforme, usted puede pedir ver su identificación oficial.","p":"Correcto. Pida ver la identificación oficial."},"ref":{"doc":"SC","page":"10-13"}},{"id":"sc-157","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, you are behind a horse-drawn buggy on a rural road. What does the driver's manual say?","o":["Honk so the horse moves over","Follow very closely so you can pass quickly","Pass with care, do not honk or rev your engine, and expect left turns into fields and driveways","Flash your lights to ask the driver to pull over"],"h1":"Loud noises can scare the animal.","h2":"In South Carolina, pass animal-drawn vehicles with caution, do not use your horn or rev your engine, and expect them to turn left into fields and driveways.","p":"Right. Pass quietly and watch for left turns."},"es":{"q":"En Carolina del Sur, usted va detrás de una carreta tirada por caballo en una calle rural. ¿Qué dice el manual?","o":["Toque la bocina para que el caballo se haga a un lado","Sígala muy de cerca para rebasar rápido","Rebase con cuidado, no toque la bocina ni acelere el motor, y espere vueltas a la izquierda hacia campos y entradas","Haga cambio de luces para que se orille"],"h1":"Los ruidos fuertes pueden asustar al animal.","h2":"En Carolina del Sur, rebase con cuidado a los vehículos tirados por animales, no use la bocina ni acelere el motor, y espere que den vuelta a la izquierda hacia campos y entradas.","p":"Correcto. Rebase en silencio y cuídese de las vueltas a la izquierda."},"ref":{"doc":"SC","page":"10-16"}},{"id":"sc-158","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, the driver's manual says high beams let you see how far compared with low beams?","o":["About half as far","The same distance","About twice as far","About ten times as far"],"h1":"Use them when no one is coming toward you.","h2":"In South Carolina, the driver's manual says high beams let you see twice as far as low beams.","p":"Right. High beams show about twice as far."},"es":{"q":"En Carolina del Sur, según el manual, ¿qué tan lejos le dejan ver las luces altas comparadas con las bajas?","o":["Más o menos la mitad","La misma distancia","Más o menos el doble","Más o menos diez veces más"],"h1":"Úselas cuando nadie viene de frente.","h2":"En Carolina del Sur, el manual dice que las luces altas le dejan ver el doble de lejos que las bajas.","p":"Correcto. Las luces altas alumbran como el doble."},"ref":{"doc":"SC","page":"11-1"}},{"id":"sc-159","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, you are following another car at night. Within what distance must you switch to low beams?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is less than half the distance for an oncoming car.","h2":"In South Carolina, use your low beams when you follow another vehicle that is less than 200 feet ahead of you.","p":"Right. Use low beams within 200 feet of the car ahead."},"es":{"q":"En Carolina del Sur, usted va detrás de otro carro de noche. ¿A qué distancia debe cambiar a luces bajas?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es menos de la mitad de la distancia para un carro que viene de frente.","h2":"En Carolina del Sur, use las luces bajas cuando siga a otro vehículo que va a menos de 200 pies delante de usted.","p":"Correcto. Use luces bajas a menos de 200 pies del carro de adelante."},"ref":{"doc":"SC","page":"11-2"}},{"id":"sc-160","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, you are driving at night on a road you do not know. How much should you add to your following distance?","o":["Nothing extra","Half a second","At least ten extra seconds","At least two extra seconds"],"h1":"Night adds one second; an unfamiliar road at night adds more.","h2":"In South Carolina, add at least one second to your following distance at night and at least two seconds on unfamiliar roads at night.","p":"Right. Add at least two seconds on an unfamiliar road at night."},"es":{"q":"En Carolina del Sur, usted maneja de noche por una calle que no conoce. ¿Cuánto debe agregar a su distancia de seguimiento?","o":["Nada más","Medio segundo","Al menos diez segundos más","Al menos dos segundos más"],"h1":"La noche agrega un segundo; una calle desconocida de noche agrega más.","h2":"En Carolina del Sur, agregue al menos un segundo a su distancia de seguimiento de noche y al menos dos segundos en calles desconocidas de noche.","p":"Correcto. Agregue al menos dos segundos en una calle desconocida de noche."},"ref":{"doc":"SC","page":"11-2"}},{"id":"sc-161","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, why does the driver's manual suggest keeping a full gas tank in winter weather?","o":["To prevent water from forming in the tank and freezing","To make the car lighter","So the heater works faster","Because gas is cheaper in winter"],"h1":"Moisture in a half-empty tank can turn to ice.","h2":"In South Carolina, keep a full tank of gas in winter to prevent condensation in the tank, which may freeze.","p":"Right. A full tank prevents condensation that can freeze."},"es":{"q":"En Carolina del Sur, ¿por qué sugiere el manual tener el tanque lleno de gasolina cuando hace frío?","o":["Para evitar que se forme agua en el tanque y se congele","Para que el carro pese menos","Para que la calefacción funcione más rápido","Porque la gasolina es más barata en invierno"],"h1":"La humedad en un tanque medio vacío se puede volver hielo.","h2":"En Carolina del Sur, tenga el tanque lleno en invierno para evitar la condensación en el tanque, que se puede congelar.","p":"Correcto. Un tanque lleno evita la condensación que se congela."},"ref":{"doc":"SC","page":"11-7"}},{"id":"sc-162","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, your car is stuck in snow. What does the driver's manual say to do first?","o":["Press the gas to the floor","Do not spin the wheels; turn them side to side and use a light touch on the gas","Shift between drive and reverse at full power","Let all the air out of the tires"],"h1":"Spinning only digs you in deeper.","h2":"In South Carolina, if you are stuck in snow, do not spin your wheels; turn them side to side, use a light touch on the gas, and clear or add traction under the wheels.","p":"Right. No spinning; rock the wheels gently."},"es":{"q":"En Carolina del Sur, su carro está atascado en la nieve. ¿Qué dice el manual que haga primero?","o":["Pisar el acelerador a fondo","No hacer patinar las llantas; girarlas de lado a lado y acelerar suavemente","Cambiar entre avanzar y reversa con toda la fuerza","Sacarles todo el aire a las llantas"],"h1":"Hacer patinar las llantas solo le hunde más.","h2":"En Carolina del Sur, si está atascado en la nieve, no haga patinar las llantas; gírelas de lado a lado, acelere suavemente y limpie o ponga algo para agarre bajo las llantas.","p":"Correcto. Sin patinar; mueva las llantas con suavidad."},"ref":{"doc":"SC","page":"11-7"}},{"id":"sc-163","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, your car has standard brakes, not ABS, and starts to skid on ice. What does the driver's manual say about braking?","o":["Press the brake as hard as you can and hold it","Pull the parking brake hard","Never touch the brakes at all","Pump the brakes gently"],"h1":"With ABS you hold steady pressure; without it, you do something different.","h2":"In South Carolina, if you skid with standard brakes, take your foot off the gas, steer where you want to go, and pump the brakes gently.","p":"Right. With standard brakes, pump them gently."},"es":{"q":"En Carolina del Sur, su carro tiene frenos normales, sin ABS, y empieza a patinar en el hielo. ¿Qué dice el manual sobre frenar?","o":["Pisar el freno con toda la fuerza y mantenerlo","Jalar fuerte el freno de mano","Nunca tocar el freno","Bombear el freno suavemente"],"h1":"Con ABS se mantiene una presión constante; sin ABS, se hace algo distinto.","h2":"En Carolina del Sur, si patina con frenos normales, quite el pie del acelerador, gire hacia donde quiere ir y bombee el freno suavemente.","p":"Correcto. Con frenos normales, bombéelos suavemente."},"ref":{"doc":"SC","page":"11-8"}},{"id":"sc-164","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, the trailer you are towing starts to sway. What does the driver's manual say to do?","o":["Steer straight and slow down gradually without braking","Brake hard right away","Speed up to pull it straight","Turn the wheel quickly back and forth"],"h1":"Sudden moves make sway worse.","h2":"In South Carolina, if a trailer sways or whips, steer straight and reduce speed gradually; do not brake and never speed up.","p":"Right. Steer straight and ease off the gas."},"es":{"q":"En Carolina del Sur, el remolque que usted lleva empieza a balancearse. ¿Qué dice el manual que haga?","o":["Mantener el volante recto y bajar la velocidad poco a poco sin frenar","Frenar fuerte de inmediato","Acelerar para enderezarlo","Girar el volante rápido de un lado a otro"],"h1":"Los movimientos bruscos empeoran el balanceo.","h2":"En Carolina del Sur, si un remolque se balancea o coletea, mantenga el volante recto y baje la velocidad poco a poco; no frene y nunca acelere.","p":"Correcto. Volante recto y suelte el acelerador."},"ref":{"doc":"SC","page":"11-10"}},{"id":"sc-165","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, you are backing up with a trailer. How does the driver's manual say to steer?","o":["Hold the top of the wheel and turn the way you want the trailer to go","Hold the bottom of the wheel and move your hand the way you want the trailer to go","Turn the wheel as far as it goes, then let go","Do not steer at all"],"h1":"The bottom-of-the-wheel trick makes the direction easy to remember.","h2":"In South Carolina, when backing a trailer, keep your hand at the bottom of the steering wheel; move your hand left to move the trailer left, and right to move it right.","p":"Right. Hand at the bottom, move it the way the trailer should go."},"es":{"q":"En Carolina del Sur, usted está dando reversa con un remolque. ¿Cómo dice el manual que mueva el volante?","o":["Agarrar la parte de arriba y girar hacia donde quiere que vaya el remolque","Agarrar la parte de abajo del volante y mover la mano hacia donde quiere que vaya el remolque","Girar el volante hasta el tope y soltarlo","No mover el volante"],"h1":"El truco de la parte de abajo hace fácil recordar la dirección.","h2":"En Carolina del Sur, al dar reversa con un remolque, ponga la mano en la parte de abajo del volante; mueva la mano a la izquierda para llevar el remolque a la izquierda, y a la derecha para la derecha.","p":"Correcto. Mano abajo, muévala hacia donde debe ir el remolque."},"ref":{"doc":"SC","page":"11-12"}},{"id":"sc-166","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, you are towing a trailer on a long trip. When does the driver's manual say to walk around and recheck the hitch, chains, lights and tires?","o":["Only once a year","Only if a light comes on","Only when you reach your destination","Before driving and at each fuel stop"],"h1":"Check often, every time you stop for gas.","h2":"In South Carolina, before driving and at each fuel stop, walk around the vehicle and trailer and recheck the hitch, safety chains, lights and tire pressures.","p":"Right. Recheck before you leave and at every fuel stop."},"es":{"q":"En Carolina del Sur, usted lleva un remolque en un viaje largo. ¿Cuándo dice el manual que camine alrededor y revise el enganche, las cadenas, las luces y las llantas?","o":["Solo una vez al año","Solo si se prende una luz","Solo al llegar a su destino","Antes de salir y en cada parada para echar gasolina"],"h1":"Revise seguido, cada vez que pare a echar gasolina.","h2":"En Carolina del Sur, antes de manejar y en cada parada para echar gasolina, camine alrededor del vehículo y el remolque y revise el enganche, las cadenas de seguridad, las luces y la presión de las llantas.","p":"Correcto. Revise antes de salir y en cada parada para echar gasolina."},"ref":{"doc":"SC","page":"11-12"}},{"id":"sc-167","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, what is the speed limit on a paved road outside town when no other limit is posted?","o":["45 mph","55 mph","60 mph","70 mph"],"h1":"It is lower than the interstate and divided highway limits.","h2":"In South Carolina, state law sets 55 mph as the maximum on roads where no other limit is set, such as a paved two-lane road outside town.","p":"Right. The basic limit is 55 mph."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad en una carretera pavimentada fuera del pueblo cuando no hay otro límite señalado?","o":["45 mph","55 mph","60 mph","70 mph"],"h1":"Es más bajo que el límite de las interestatales y de las carreteras divididas.","h2":"En Carolina del Sur, la ley fija 55 mph como máximo en las vías donde no hay otro límite, como una carretera pavimentada de dos carriles fuera del pueblo.","p":"Correcto. El límite básico es 55 mph."},"ref":{"doc":"SC","page":null}},{"id":"sc-168","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, what is the highest speed limit state law allows on a multilane divided primary highway (not an interstate) when posted?","o":["50 mph","55 mph","60 mph","75 mph"],"h1":"It is between the basic limit and the interstate limit.","h2":"In South Carolina, state law allows up to 60 mph on multilane divided primary highways where signs post that limit.","p":"Right. Divided primary highways can be posted at 60 mph."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite más alto que permite la ley en una carretera primaria dividida de varios carriles (no interestatal) cuando está señalado?","o":["50 mph","55 mph","60 mph","75 mph"],"h1":"Está entre el límite básico y el de las interestatales.","h2":"En Carolina del Sur, la ley permite hasta 60 mph en carreteras primarias divididas de varios carriles donde hay señales con ese límite.","p":"Correcto. Las carreteras primarias divididas pueden tener 60 mph."},"ref":{"doc":"SC","page":null}},{"id":"sc-169","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, what is the speed limit in an urban district (a built-up area of homes or businesses) unless signs say otherwise?","o":["20 mph","30 mph","35 mph","45 mph"],"h1":"It is the lowest of the basic state limits.","h2":"In South Carolina, state law sets 30 mph as the maximum speed in an urban district unless a different limit is posted.","p":"Right. Urban districts are 30 mph."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad en un distrito urbano (una zona con muchas casas o negocios) si no hay señales que digan otra cosa?","o":["20 mph","30 mph","35 mph","45 mph"],"h1":"Es el más bajo de los límites básicos del estado.","h2":"En Carolina del Sur, la ley fija 30 mph como velocidad máxima en un distrito urbano, a menos que se señale otro límite.","p":"Correcto. Los distritos urbanos son de 30 mph."},"ref":{"doc":"SC","page":null}},{"id":"sc-170","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, what is the speed limit on an unpaved (dirt or gravel) road unless signs say otherwise?","o":["25 mph","40 mph","45 mph","55 mph"],"h1":"It is lower than the 55 mph limit for paved roads.","h2":"In South Carolina, state law limits unpaved roads to 40 mph unless a different limit is set.","p":"Right. Unpaved roads are limited to 40 mph."},"es":{"q":"En Carolina del Sur, ¿cuál es el límite de velocidad en un camino sin pavimentar (de tierra o grava) si no hay señales que digan otra cosa?","o":["25 mph","40 mph","45 mph","55 mph"],"h1":"Es más bajo que el límite de 55 mph de las carreteras pavimentadas.","h2":"En Carolina del Sur, la ley limita los caminos sin pavimentar a 40 mph, a menos que se fije otro límite.","p":"Correcto. Los caminos sin pavimentar tienen un límite de 40 mph."},"ref":{"doc":"SC","page":null}},{"id":"sc-171","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you get a ticket for going 8 mph over the speed limit. How many points go on your record?","o":["0 points","2 points","4 points","6 points"],"h1":"Speeding points grow with how far over the limit you were.","h2":"In South Carolina, speeding no more than 10 mph over the posted limit adds 2 points to your record.","p":"Right. Up to 10 mph over is 2 points."},"es":{"q":"En Carolina del Sur, le multan por ir 8 mph por encima del límite. ¿Cuántos puntos se suman a su historial?","o":["0 puntos","2 puntos","4 puntos","6 puntos"],"h1":"Los puntos por velocidad aumentan según cuánto se pasó del límite.","h2":"En Carolina del Sur, ir a no más de 10 mph por encima del límite señalado suma 2 puntos a su historial.","p":"Correcto. Hasta 10 mph por encima son 2 puntos."},"ref":{"doc":"SC","page":null}},{"id":"sc-172","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, you get a ticket for going 25 mph or more over the speed limit. How many points go on your record?","o":["2 points","4 points","6 points","12 points"],"h1":"It is the same as for reckless driving.","h2":"In South Carolina, speeding 25 mph or more over the posted limit adds 6 points to your record.","p":"Right. 25 mph or more over is 6 points."},"es":{"q":"En Carolina del Sur, le multan por ir 25 mph o más por encima del límite. ¿Cuántos puntos se suman a su historial?","o":["2 puntos","4 puntos","6 puntos","12 puntos"],"h1":"Es lo mismo que por manejar de forma temeraria.","h2":"En Carolina del Sur, ir a 25 mph o más por encima del límite señalado suma 6 puntos a su historial.","p":"Correcto. 25 mph o más por encima son 6 puntos."},"ref":{"doc":"SC","page":null}},{"id":"sc-173","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, how many points are added for passing a stopped school bus?","o":["2 points","3 points","4 points","6 points"],"h1":"It is one of the highest point values on the list.","h2":"In South Carolina, passing a stopped school bus adds 6 points to your driving record.","p":"Right. Passing a stopped school bus is 6 points."},"es":{"q":"En Carolina del Sur, ¿cuántos puntos se suman por rebasar un autobús escolar detenido?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Es uno de los valores más altos de la lista.","h2":"En Carolina del Sur, rebasar un autobús escolar detenido suma 6 puntos a su historial de manejo.","p":"Correcto. Rebasar un autobús escolar detenido son 6 puntos."},"ref":{"doc":"SC","page":null}},{"id":"sc-174","scope":"SC","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Carolina, an officer gives you a written warning instead of a ticket. How many points does it add to your record?","o":["None","1 point","2 points","4 points"],"h1":"A warning is not a conviction.","h2":"In South Carolina, warning tickets are not given any point value.","p":"Right. A warning adds no points."},"es":{"q":"En Carolina del Sur, un policía le da una advertencia por escrito en vez de una multa. ¿Cuántos puntos suma a su historial?","o":["Ninguno","1 punto","2 puntos","4 puntos"],"h1":"Una advertencia no es una condena.","h2":"En Carolina del Sur, las advertencias escritas no tienen ningún valor en puntos.","p":"Correcto. Una advertencia no suma puntos."},"ref":{"doc":"SC","page":null}},{"id":"sc-175","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, you get a ticket for not wearing a seat belt. What is the penalty?","o":["2 points and a warning letter","A fine of up to $25, with no points on your record","A license suspension of 30 days","A $250 fine and 4 points"],"h1":"It is a small civil fine.","h2":"In South Carolina, a seat belt violation is a fine of no more than $25, and no points may be assessed for it.","p":"Right. Up to $25 and no points."},"es":{"q":"En Carolina del Sur, le multan por no usar el cinturón de seguridad. ¿Cuál es la sanción?","o":["2 puntos y una carta de advertencia","Una multa de hasta $25, sin puntos en su historial","Una suspensión de licencia de 30 días","Una multa de $250 y 4 puntos"],"h1":"Es una multa civil pequeña.","h2":"En Carolina del Sur, no usar el cinturón tiene una multa de no más de $25, y no se pueden sumar puntos por ello.","p":"Correcto. Hasta $25 y sin puntos."},"ref":{"doc":"SC","page":null}},{"id":"sc-176","scope":"SC","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Carolina, on a controlled-access highway like an interstate, when may you drive in the far left lane?","o":["When passing, or when the law allows an exception such as heavy traffic or a left exit","Any time you are at the speed limit","Only at night","Whenever you plan to exit in the next 10 miles"],"h1":"The far left lane is meant for passing.","h2":"In South Carolina, you may not drive in the far left lane of a controlled-access highway except to pass, with exceptions such as no car behind you, heavy traffic, bad weather, a hazard, or a left exit.","p":"Right. The far left lane is for passing."},"es":{"q":"En Carolina del Sur, en una autopista de acceso controlado como una interestatal, ¿cuándo puede manejar en el carril de más a la izquierda?","o":["Al rebasar, o cuando la ley permite una excepción como tráfico pesado o una salida a la izquierda","Siempre que vaya al límite de velocidad","Solo de noche","Siempre que piense salir en las próximas 10 millas"],"h1":"El carril de más a la izquierda es para rebasar.","h2":"En Carolina del Sur, no puede manejar en el carril de más a la izquierda de una autopista de acceso controlado salvo para rebasar, con excepciones como no tener carros detrás, tráfico pesado, mal tiempo, un peligro o una salida a la izquierda.","p":"Correcto. El carril de más a la izquierda es para rebasar."},"ref":{"doc":"SC","page":null}},{"id":"sc-177","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, a driver ignores work zone traffic controls while highway workers are present, but no one is hurt. What is the fine?","o":["$25 to $50","$100 to $200","$500 to $1,000","$5,000 to $10,000"],"h1":"The fine is mandatory and cannot be reduced below the minimum.","h2":"In South Carolina, endangering a highway worker when no worker is injured carries a fine of $500 to $1,000, plus points.","p":"Right. The fine is $500 to $1,000."},"es":{"q":"En Carolina del Sur, un conductor no obedece las señales de una zona de trabajo cuando hay trabajadores presentes, pero nadie sale herido. ¿Cuál es la multa?","o":["De $25 a $50","De $100 a $200","De $500 a $1,000","De $5,000 a $10,000"],"h1":"La multa es obligatoria y no se puede bajar del mínimo.","h2":"En Carolina del Sur, poner en peligro a un trabajador de carreteras sin que nadie salga herido tiene una multa de $500 a $1,000, además de puntos.","p":"Correcto. La multa es de $500 a $1,000."},"ref":{"doc":"SC","page":null}},{"id":"sc-178","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, a fire truck is on its way to an emergency. How close may you follow it?","o":["No closer than 50 feet","No closer than 100 feet","As close as you want if your flashers are on","No closer than 500 feet"],"h1":"Stay about a tenth of a mile back.","h2":"In South Carolina, unless you are on official business, you may not follow a fire truck answering an emergency closer than 500 feet, or stop within 500 feet of one stopped at an emergency.","p":"Right. Stay at least 500 feet behind a fire truck."},"es":{"q":"En Carolina del Sur, un camión de bomberos va a una emergencia. ¿Qué tan cerca lo puede seguir?","o":["No más cerca de 50 pies","No más cerca de 100 pies","Tan cerca como quiera si lleva las intermitentes","No más cerca de 500 pies"],"h1":"Quédese como a una décima de milla.","h2":"En Carolina del Sur, si no está en servicio oficial, no puede seguir a menos de 500 pies a un camión de bomberos que va a una emergencia, ni detenerse a menos de 500 pies de uno detenido en una emergencia.","p":"Correcto. Quédese al menos a 500 pies detrás de un camión de bomberos."},"ref":{"doc":"SC","page":null}},{"id":"sc-179","scope":"SC","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Carolina, what is the fine for breaking the move-over law near a stopped emergency vehicle?","o":["$25","$50 to $100","$300 to $500","$2,000 to $5,000"],"h1":"It is a misdemeanor with a fine in the hundreds of dollars.","h2":"In South Carolina, failing to slow down and move over for a stopped emergency vehicle is a misdemeanor with a fine of $300 to $500.","p":"Right. The fine is $300 to $500."},"es":{"q":"En Carolina del Sur, ¿cuál es la multa por no cumplir la ley de moverse de carril cerca de un vehículo de emergencia detenido?","o":["$25","De $50 a $100","De $300 a $500","De $2,000 a $5,000"],"h1":"Es un delito menor con una multa de cientos de dólares.","h2":"En Carolina del Sur, no bajar la velocidad y no moverse de carril ante un vehículo de emergencia detenido es un delito menor con multa de $300 a $500.","p":"Correcto. La multa es de $300 a $500."},"ref":{"doc":"SC","page":null}},{"id":"sc-180","scope":"SC","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Carolina, does the move-over law also cover a tow truck stopped at a crash with its warning lights flashing?","o":["Yes, recovery and towing vehicles are covered","No, only police cars","No, only ambulances and fire trucks","Only if a police officer is also there"],"h1":"The law lists more than police, fire and ambulance.","h2":"In South Carolina, the move-over law covers ambulance, police, fire, rescue, recovery and towing vehicles responding to a traffic incident, including ones with amber or yellow lights.","p":"Right. Tow trucks are covered too."},"es":{"q":"En Carolina del Sur, ¿la ley de moverse de carril también cubre a una grúa detenida en un choque con sus luces de advertencia encendidas?","o":["Sí, los vehículos de rescate y las grúas están cubiertos","No, solo las patrullas","No, solo ambulancias y bomberos","Solo si también hay un policía"],"h1":"La ley incluye más que policía, bomberos y ambulancias.","h2":"En Carolina del Sur, la ley de moverse de carril cubre ambulancias, policía, bomberos, rescate, recuperación y grúas que atienden un incidente de tránsito, incluso con luces ámbar o amarillas.","p":"Correcto. Las grúas también están cubiertas."},"ref":{"doc":"SC","page":null}},{"id":"sc-181","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, you have a crash with $1,500 in damage and no officer investigates it. What must you do?","o":["Nothing, since no one was hurt","Call your insurance company within 1 year","Report it to the SCDMV within 60 days","Send a written report to the SCDMV within 15 days"],"h1":"The report also verifies your liability insurance.","h2":"In South Carolina, if a crash causes injury, death or $1,000 or more in damage and no officer investigates it, the driver or owner must send a written report to the SCDMV within 15 days.","p":"Right. Report it to the SCDMV within 15 days."},"es":{"q":"En Carolina del Sur, usted tiene un choque con $1,500 en daños y ningún policía lo investiga. ¿Qué debe hacer?","o":["Nada, porque nadie salió herido","Llamar a su seguro dentro de 1 año","Informarlo al SCDMV dentro de 60 días","Enviar un informe escrito al SCDMV dentro de 15 días"],"h1":"El informe también comprueba su seguro de responsabilidad.","h2":"En Carolina del Sur, si un choque causa lesiones, muerte o $1,000 o más en daños y ningún policía lo investiga, el conductor o dueño debe enviar un informe escrito al SCDMV dentro de 15 días.","p":"Correcto. Infórmelo al SCDMV dentro de 15 días."},"ref":{"doc":"SC","page":null}},{"id":"sc-182","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, you have a minor crash with damage only, and your car blocks traffic but can still be driven. What should you do?","o":["Move it off the roadway so it does not block traffic","Leave it exactly where it stopped until police arrive","Drive home and call later","Push the other car into a ditch"],"h1":"Moving the car does not make you at fault.","h2":"In South Carolina, after a damage-only crash, the driver should make every reasonable effort to move a drivable vehicle off the roadway so it does not block traffic.","p":"Right. Move a drivable car out of traffic."},"es":{"q":"En Carolina del Sur, usted tiene un choque leve, solo con daños, y su carro bloquea el tráfico pero todavía se puede manejar. ¿Qué debe hacer?","o":["Moverlo fuera de la vía para que no bloquee el tráfico","Dejarlo exactamente donde quedó hasta que llegue la policía","Irse a su casa y llamar después","Empujar el otro carro a una zanja"],"h1":"Mover el carro no le hace culpable.","h2":"En Carolina del Sur, después de un choque solo con daños, el conductor debe hacer todo lo razonable para sacar de la vía un vehículo que se pueda manejar, para no bloquear el tráfico.","p":"Correcto. Saque de la vía un carro que se pueda manejar."},"ref":{"doc":"SC","page":null}},{"id":"sc-183","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, the lights are flashing at a railroad crossing. Where must you stop?","o":["Right on the tracks","Between 5 and 10 feet from the nearest rail","At least 100 feet from the nearest rail","Between 15 and 50 feet from the nearest rail"],"h1":"Not too close, and not too far.","h2":"In South Carolina, when a signal warns of a train, you must stop within 50 feet but not less than 15 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Carolina del Sur, las luces están parpadeando en un cruce de tren. ¿Dónde debe detenerse?","o":["Encima de las vías","Entre 5 y 10 pies del riel más cercano","Al menos a 100 pies del riel más cercano","Entre 15 y 50 pies del riel más cercano"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Carolina del Sur, cuando una señal avisa que viene un tren, debe detenerse a no más de 50 pies y no menos de 15 pies del riel más cercano.","p":"Correcto. Deténgase a entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"SC","page":null}},{"id":"sc-184","scope":"SC","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Carolina, how close to a fire hydrant may you park?","o":["No closer than 5 feet","No closer than 15 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Firefighters need room to connect hoses.","h2":"In South Carolina, you may not stand or park a vehicle within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Carolina del Sur, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 50 pies"],"h1":"Los bomberos necesitan espacio para conectar las mangueras.","h2":"En Carolina del Sur, no puede detenerse ni estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies de un hidrante."},"ref":{"doc":"SC","page":null}},{"id":"sc-185","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, how close to a crosswalk at an intersection may you park?","o":["No closer than 5 feet","No closer than 10 feet","No closer than 20 feet","No closer than 50 feet"],"h1":"Drivers need to see people stepping into the crosswalk.","h2":"In South Carolina, you may not stand or park within 20 feet of a crosswalk at an intersection.","p":"Right. Park at least 20 feet from the crosswalk."},"es":{"q":"En Carolina del Sur, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No más cerca de 5 pies","No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 50 pies"],"h1":"Los conductores necesitan ver a las personas que entran al cruce.","h2":"En Carolina del Sur, no puede detenerse ni estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Estaciónese al menos a 20 pies del cruce peatonal."},"ref":{"doc":"SC","page":null}},{"id":"sc-186","scope":"SC","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Carolina, how close to a stop sign or traffic signal at the side of the road may you park?","o":["No closer than 10 feet","No closer than 15 feet","No closer than 30 feet","No closer than 100 feet"],"h1":"A parked car must not hide the sign from drivers.","h2":"In South Carolina, you may not stand or park within 30 feet of a flashing signal, stop sign, yield sign or traffic signal at the side of the road.","p":"Right. Park at least 30 feet before a stop sign."},"es":{"q":"En Carolina del Sur, ¿qué tan cerca de una señal de alto o un semáforo al lado de la calle puede estacionarse?","o":["No más cerca de 10 pies","No más cerca de 15 pies","No más cerca de 30 pies","No más cerca de 100 pies"],"h1":"Un carro estacionado no debe tapar la señal a los conductores.","h2":"En Carolina del Sur, no puede detenerse ni estacionarse a menos de 30 pies de una luz intermitente, señal de alto, señal de ceda el paso o semáforo al lado de la calle.","p":"Correcto. Estaciónese al menos a 30 pies de una señal de alto."},"ref":{"doc":"SC","page":null}},{"id":"sc-187","scope":"SC","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Carolina, what is the minimum fine for a first offense of passing a stopped school bus with red lights flashing?","o":["$50","$100","$250","$500"],"h1":"It is at least half of a thousand dollars.","h2":"In South Carolina, a first offense of illegally passing a stopped school bus brings a fine of at least $500 or up to 30 days in jail.","p":"Right. The fine is at least $500."},"es":{"q":"En Carolina del Sur, ¿cuál es la multa mínima por una primera vez de rebasar un autobús escolar detenido con las luces rojas encendidas?","o":["$50","$100","$250","$500"],"h1":"Es al menos la mitad de mil dólares.","h2":"En Carolina del Sur, la primera vez que alguien rebasa ilegalmente un autobús escolar detenido recibe una multa de al menos $500 o hasta 30 días de cárcel.","p":"Correcto. La multa es de al menos $500."},"ref":{"doc":"SC","page":null}},{"id":"sc-188","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, what is the penalty for a first DUI conviction with a blood alcohol level under 0.10?","o":["A $400 fine or 48 hours to 30 days in jail","A $25 fine","A warning letter","A $10,000 fine and 5 years in prison"],"h1":"Higher alcohol levels bring higher penalties.","h2":"In South Carolina, a first DUI offense is punished by a $400 fine or 48 hours to 30 days in jail, and the penalties rise with higher alcohol levels.","p":"Right. A $400 fine or 48 hours to 30 days in jail."},"es":{"q":"En Carolina del Sur, ¿cuál es la sanción por una primera condena de DUI con un nivel de alcohol menor de 0.10?","o":["Una multa de $400 o de 48 horas a 30 días de cárcel","Una multa de $25","Una carta de advertencia","Una multa de $10,000 y 5 años de prisión"],"h1":"Los niveles de alcohol más altos traen sanciones más altas.","h2":"En Carolina del Sur, una primera infracción de DUI se castiga con una multa de $400 o de 48 horas a 30 días de cárcel, y las sanciones suben con niveles más altos de alcohol.","p":"Correcto. Multa de $400 o de 48 horas a 30 días de cárcel."},"ref":{"doc":"SC","page":null}},{"id":"sc-189","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, after a first DUI conviction, how long must an ignition interlock device stay on the vehicle to get an interlock license?","o":["1 week","6 months","2 years","For life"],"h1":"It is half a year for a first offense.","h2":"In South Carolina, a person convicted of a first DUI must enroll in the Ignition Interlock Device Program, and the device must stay on the vehicle for six months.","p":"Right. Six months for a first offense."},"es":{"q":"En Carolina del Sur, después de una primera condena por DUI, ¿cuánto tiempo debe estar instalado el dispositivo de bloqueo de encendido (interlock) para tener licencia con esa restricción?","o":["1 semana","6 meses","2 años","De por vida"],"h1":"Es medio año para una primera infracción.","h2":"En Carolina del Sur, quien es condenado por un primer DUI debe inscribirse en el Programa de Dispositivo de Bloqueo de Encendido, y el dispositivo debe quedarse en el vehículo seis meses.","p":"Correcto. Seis meses por una primera infracción."},"ref":{"doc":"SC","page":null}},{"id":"sc-190","scope":"SC","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Carolina, an adult driver arrested for DUI takes a breath test that shows 0.15 or higher. On a first offense, how long is the license suspended right away?","o":["One week","One month","One year","Five years"],"h1":"Refusing the test brings a longer suspension than this.","h2":"In South Carolina, a first-time driver whose test shows an alcohol level of 0.15 or more has the license suspended for one month, while refusing the test brings six months.","p":"Right. A first test result of 0.15 or more brings a one-month suspension."},"es":{"q":"En Carolina del Sur, a un conductor adulto arrestado por DUI le hacen una prueba de aliento que marca 0.15 o más. En una primera vez, ¿por cuánto tiempo le suspenden la licencia de inmediato?","o":["Una semana","Un mes","Un año","Cinco años"],"h1":"Negarse a la prueba trae una suspensión más larga que esta.","h2":"En Carolina del Sur, si en una primera vez la prueba marca 0.15 o más de alcohol, la licencia se suspende por un mes, mientras que negarse a la prueba trae seis meses.","p":"Correcto. Una primera prueba de 0.15 o más trae un mes de suspensión."},"ref":{"doc":"SC","page":null}},{"id":"sc-191","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, where may an opened can of beer be in a car on a public road?","o":["Only in the trunk or luggage compartment","In a cup holder, if the driver is not drinking it","Under the passenger seat","Anywhere, if the driver is over 21"],"h1":"It must be out of reach of the driver and passengers.","h2":"In South Carolina, it is against the law to have open beer or wine in a vehicle on a public road except in the trunk or luggage compartment.","p":"Right. An open container may only be in the trunk."},"es":{"q":"En Carolina del Sur, ¿dónde puede ir una lata de cerveza abierta en un carro en una vía pública?","o":["Solo en la cajuela o el compartimiento de equipaje","En el portavasos, si el conductor no la está tomando","Debajo del asiento del pasajero","En cualquier lugar, si el conductor tiene más de 21 años"],"h1":"Debe estar fuera del alcance del conductor y los pasajeros.","h2":"En Carolina del Sur, es ilegal tener cerveza o vino abiertos en un vehículo en una vía pública, salvo en la cajuela o el compartimiento de equipaje.","p":"Correcto. Un envase abierto solo puede ir en la cajuela."},"ref":{"doc":"SC","page":null}},{"id":"sc-192","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, what are the minimum liability insurance limits for a car?","o":["$10,000 per person, $20,000 per crash, and $10,000 for property","$15,000 per person, $30,000 per crash, and $5,000 for property","$25,000 per person, $50,000 per crash for injuries, and $25,000 for property damage","$100,000 per person, $300,000 per crash, and $100,000 for property"],"h1":"People often call it 25/50/25.","h2":"In South Carolina, car liability insurance must cover at least $25,000 for one person's injuries, $50,000 for injuries to two or more people, and $25,000 for property damage in one crash.","p":"Right. The minimum is 25/50/25."},"es":{"q":"En Carolina del Sur, ¿cuáles son los límites mínimos del seguro de responsabilidad para un carro?","o":["$10,000 por persona, $20,000 por choque y $10,000 por propiedad","$15,000 por persona, $30,000 por choque y $5,000 por propiedad","$25,000 por persona, $50,000 por choque por lesiones y $25,000 por daños a la propiedad","$100,000 por persona, $300,000 por choque y $100,000 por propiedad"],"h1":"Se suele decir 25/50/25.","h2":"En Carolina del Sur, el seguro de responsabilidad de un carro debe cubrir al menos $25,000 por las lesiones de una persona, $50,000 por lesiones de dos o más personas y $25,000 por daños a la propiedad en un choque.","p":"Correcto. El mínimo es 25/50/25."},"ref":{"doc":"SC","page":null}},{"id":"sc-193","scope":"SC","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Carolina, you move to a new home address. Within how many days must you tell the SCDMV?","o":["3 days","10 days","45 days","90 days"],"h1":"It is a short deadline, less than two weeks.","h2":"In South Carolina, a licensed driver who moves permanently must notify the SCDMV of the old and new address within 10 days.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Carolina del Sur, usted se muda a una nueva dirección. ¿En cuántos días debe avisar al SCDMV?","o":["3 días","10 días","45 días","90 días"],"h1":"Es un plazo corto, menos de dos semanas.","h2":"En Carolina del Sur, un conductor con licencia que se muda permanentemente debe avisar al SCDMV su dirección anterior y la nueva dentro de 10 días.","p":"Correcto. Avise su nueva dirección dentro de 10 días."},"ref":{"doc":"SC","page":null}},{"id":"sc-194","scope":"SC","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Carolina, after-market window tint on the side windows must let through at least how much light?","o":["5 percent","10 percent","27 percent","70 percent"],"h1":"It is a little over one quarter.","h2":"In South Carolina, tint film on the side and rear windows must be nonreflective and, together with the factory glass, let through at least 27 percent of light.","p":"Right. At least 27 percent of light must pass through."},"es":{"q":"En Carolina del Sur, ¿al menos cuánta luz debe dejar pasar el polarizado que se agrega a las ventanas laterales?","o":["5 por ciento","10 por ciento","27 por ciento","70 por ciento"],"h1":"Es un poco más de un cuarto.","h2":"En Carolina del Sur, el polarizado de las ventanas laterales y traseras no debe reflejar y, junto con el vidrio de fábrica, debe dejar pasar al menos el 27 por ciento de la luz.","p":"Correcto. Debe pasar al menos el 27 por ciento de la luz."},"ref":{"doc":"SC","page":null}},{"id":"sc-195","scope":"SC","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Carolina, who must wear a helmet when riding a motorcycle?","o":["Everyone, at any age","Only riders under 16","No one; helmets are optional for all","Riders and passengers under 21"],"h1":"The law sets an age limit, not a rule for all riders.","h2":"In South Carolina, anyone under 21 who drives or rides on a two-wheeled motorized vehicle must wear an approved helmet.","p":"Right. Helmets are required under 21."},"es":{"q":"En Carolina del Sur, ¿quién debe usar casco al andar en motocicleta?","o":["Todos, a cualquier edad","Solo los conductores menores de 16 años","Nadie; el casco es opcional para todos","Los conductores y pasajeros menores de 21 años"],"h1":"La ley pone un límite de edad, no una regla para todos.","h2":"En Carolina del Sur, toda persona menor de 21 años que maneje o vaya en un vehículo motorizado de dos ruedas debe usar un casco aprobado.","p":"Correcto. El casco es obligatorio para menores de 21 años."},"ref":{"doc":"SC","page":null}},{"id":"sc-196","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, it is daytime and raining hard enough that your windshield wipers are on all the time. What must you do?","o":["Turn on your headlights","Turn on only your parking lights","Turn on your hazard flashers","Nothing, since it is daytime"],"h1":"Wipers on means lights on.","h2":"In South Carolina, you must turn on your headlights whenever your windshield wipers are in use because of rain, sleet or snow, except for occasional wiping in a light mist.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Carolina del Sur, es de día y llueve tanto que sus limpiaparabrisas van todo el tiempo. ¿Qué debe hacer?","o":["Prender las luces delanteras","Prender solo las luces de estacionamiento","Prender las luces intermitentes de emergencia","Nada, porque es de día"],"h1":"Limpiaparabrisas prendidos significa luces prendidas.","h2":"En Carolina del Sur, debe prender las luces delanteras siempre que use los limpiaparabrisas por lluvia, aguanieve o nieve, salvo cuando los usa de vez en cuando en una llovizna.","p":"Correcto. Limpiaparabrisas prendidos, luces prendidas."},"ref":{"doc":"SC","page":null}},{"id":"sc-197","scope":"SC","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Carolina, how long is a beginner's permit valid before it must be renewed?","o":["30 days","6 months","12 months","8 years"],"h1":"It can be renewed for more periods of the same length.","h2":"In South Carolina, a beginner's permit is valid for up to 12 months and may be renewed for additional 12-month periods.","p":"Right. A permit is good for 12 months."},"es":{"q":"En Carolina del Sur, ¿por cuánto tiempo es válido el permiso de principiante antes de tener que renovarlo?","o":["30 días","6 meses","12 meses","8 años"],"h1":"Se puede renovar por más periodos de la misma duración.","h2":"En Carolina del Sur, el permiso de principiante es válido hasta 12 meses y se puede renovar por otros periodos de 12 meses.","p":"Correcto. El permiso vale por 12 meses."},"ref":{"doc":"SC","page":null}},{"id":"sc-198","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, an officer asks for proof of insurance. May you show it on your phone?","o":["No, only a paper card counts","Only if the officer searches your phone","Only in the daytime","Yes, in an electronic format issued by your insurance company"],"h1":"The law allows digital proof from the insurer.","h2":"In South Carolina, you may show proof of insurance on a mobile device in a format issued by your insurer, and the officer may not search the rest of your phone because of it.","p":"Right. Digital proof from your insurer is allowed."},"es":{"q":"En Carolina del Sur, un policía le pide prueba de seguro. ¿Puede mostrarla en su teléfono?","o":["No, solo vale una tarjeta de papel","Solo si el policía revisa su teléfono","Solo de día","Sí, en un formato electrónico dado por su compañía de seguros"],"h1":"La ley permite una prueba digital de la aseguradora.","h2":"En Carolina del Sur, puede mostrar la prueba de seguro en un dispositivo móvil en un formato dado por su aseguradora, y el policía no puede revisar el resto de su teléfono por eso.","p":"Correcto. Se permite la prueba digital de su aseguradora."},"ref":{"doc":"SC","page":null}},{"id":"sc-199","scope":"SC","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Carolina, may a 12-year-old ride in the open bed of a pickup truck on a city street?","o":["No, not without an exception such as an adult supervising in the bed","Yes, any time","Yes, if the tailgate is down","Yes, if the truck goes under 50 mph"],"h1":"The law protects children under 15 in open truck beds.","h2":"In South Carolina, it is against the law to carry a person under 15 in the open bed of a pickup truck unless an exception applies, such as an adult supervising in the bed.","p":"Right. Children under 15 may not ride in an open bed without an exception."},"es":{"q":"En Carolina del Sur, ¿puede un niño de 12 años ir en la caja abierta de una camioneta pickup por una calle de la ciudad?","o":["No, salvo una excepción como un adulto que lo cuide en la caja","Sí, siempre","Sí, si la puerta trasera está abierta","Sí, si la camioneta va a menos de 50 mph"],"h1":"La ley protege a los menores de 15 años en cajas abiertas de camionetas.","h2":"En Carolina del Sur, es ilegal llevar a una persona menor de 15 años en la caja abierta de una camioneta pickup, salvo una excepción, como un adulto que la cuide en la caja.","p":"Correcto. Los menores de 15 no pueden ir en una caja abierta sin una excepción."},"ref":{"doc":"SC","page":null}},{"id":"sc-200","scope":"SC","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Carolina, a 15-year-old has a moped operator's license. When may they ride alone?","o":["Any time, day or night","Only on weekends","Never; an adult must always ride along","Only during daylight hours"],"h1":"At night, a licensed adult must be with them.","h2":"In South Carolina, a moped license holder under 16 may ride alone only in daylight; at night a licensed driver 21 or older with a year of experience must be with them.","p":"Right. Under 16, alone only in daylight."},"es":{"q":"En Carolina del Sur, un joven de 15 años tiene licencia de ciclomotor (moped). ¿Cuándo puede manejarlo solo?","o":["A cualquier hora, de día o de noche","Solo los fines de semana","Nunca; siempre debe ir con un adulto","Solo de día"],"h1":"De noche, un adulto con licencia debe acompañarle.","h2":"En Carolina del Sur, quien tiene licencia de ciclomotor y es menor de 16 años puede manejar solo únicamente de día; de noche debe acompañarle un conductor con licencia de 21 años o más con un año de experiencia.","p":"Correcto. Menor de 16, solo de día."},"ref":{"doc":"SC","page":null}},{"id":"sd-001","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what is the youngest age to get an instruction permit?","o":["14 years old","15 years old","16 years old","15 and a half"],"h1":"South Dakota lets teens start earlier than most states.","h2":"In South Dakota you can get an instruction permit at age 14, which is earlier than in most states.","p":"Right. The South Dakota instruction permit starts at age 14."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para obtener el permiso de instrucción?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Dakota del Sur deja empezar antes que la mayoría de los estados.","h2":"En Dakota del Sur usted puede obtener el permiso de instrucción a los 14 años, antes que en la mayoría de los estados.","p":"Correcto. El permiso de instrucción en Dakota del Sur empieza a los 14 años."},"zh":{"q":"在 South Dakota，最小几岁可以拿到学习驾照（instruction permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"South Dakota 让青少年比大多数州更早开始。","h2":"在 South Dakota，你 14 岁就可以拿到学习驾照，这比大多数州都早。","p":"对。South Dakota 的学习驾照从 14 岁开始。"},"vi":{"q":"Ở South Dakota, tuổi nhỏ nhất để có giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"South Dakota cho thanh thiếu niên bắt đầu sớm hơn hầu hết các tiểu bang.","h2":"Ở South Dakota, bạn có thể có giấy phép tập lái khi 14 tuổi, sớm hơn hầu hết các tiểu bang khác.","p":"Đúng. Giấy phép tập lái ở South Dakota bắt đầu từ 14 tuổi."},"tl":{"q":"Sa South Dakota, ano ang pinakabatang edad para makakuha ng instruction permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahati"],"h1":"Mas maaga pinapayagang magsimula ng South Dakota ang mga kabataan kaysa sa karamihan ng estado.","h2":"Sa South Dakota, makakakuha ka ng instruction permit sa edad na 14, na mas maaga kaysa sa karamihan ng estado.","p":"Tama. Sa South Dakota, nagsisimula ang instruction permit sa edad na 14."},"ar":{"q":"في South Dakota، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"تسمح South Dakota للمراهقين بالبدء أبكر من معظم الولايات.","h2":"في South Dakota يمكنك الحصول على تصريح التعلّم في عمر 14 سنة، وهذا أبكر من معظم الولايات.","p":"صحيح. يبدأ تصريح التعلّم في South Dakota من عمر 14 سنة."},"ref":{"doc":"SD","page":8}},{"id":"sd-002","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, during which hours may an instruction permit holder drive with any qualified licensed adult beside them?","o":["6 a.m. to 8 p.m.","5 a.m. to midnight","6 a.m. to 10 p.m.","6 a.m. to 6 p.m."],"h1":"It ends in the late evening, before midnight.","h2":"A South Dakota instruction permit allows driving from 6 a.m. to 10 p.m. with a qualified licensed adult beside you; from 10 p.m. to 6 a.m. it must be your parent or guardian.","p":"Right. Instruction permit driving is from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar quien tiene permiso de instrucción con cualquier adulto con licencia autorizado a su lado?","o":["De 6 a.m. a 8 p.m.","De 5 a.m. a medianoche","De 6 a.m. a 10 p.m.","De 6 a.m. a 6 p.m."],"h1":"Termina tarde en la noche, antes de la medianoche.","h2":"En Dakota del Sur el permiso de instrucción permite manejar de 6 a.m. a 10 p.m. con un adulto con licencia autorizado a su lado; de 10 p.m. a 6 a.m. debe ser su padre, madre o tutor.","p":"Correcto. Con permiso de instrucción se maneja de 6 a.m. a 10 p.m."},"zh":{"q":"在 South Dakota，持有学习驾照的人在哪个时间段可以在任何合格的有驾照成年人陪同下开车？","o":["早上 6 点到晚上 8 点","早上 5 点到午夜","早上 6 点到晚上 10 点","早上 6 点到晚上 6 点"],"h1":"结束时间在晚上较晚的时候，在午夜之前。","h2":"在 South Dakota，持学习驾照的人可以在早上 6 点到晚上 10 点之间，在合格的有驾照成年人陪同下开车；晚上 10 点到早上 6 点，陪同的人必须是父母或监护人。","p":"对。持学习驾照开车的时间是早上 6 点到晚上 10 点。"},"vi":{"q":"Ở South Dakota, người có giấy phép tập lái được lái xe với bất kỳ người lớn có bằng lái đủ điều kiện ngồi bên cạnh trong những giờ nào?","o":["6 giờ sáng đến 8 giờ tối","5 giờ sáng đến nửa đêm","6 giờ sáng đến 10 giờ tối","6 giờ sáng đến 6 giờ chiều"],"h1":"Giờ kết thúc là vào buổi tối muộn, trước nửa đêm.","h2":"Giấy phép tập lái ở South Dakota cho phép lái xe từ 6 giờ sáng đến 10 giờ tối với một người lớn có bằng lái đủ điều kiện ngồi bên cạnh; từ 10 giờ tối đến 6 giờ sáng, người đó phải là cha mẹ hoặc người giám hộ của bạn.","p":"Đúng. Lái xe với giấy phép tập lái là từ 6 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa South Dakota, sa anong oras puwedeng magmaneho ang may instruction permit kasama ang sinumang kwalipikadong adult na may lisensya sa tabi niya?","o":["6 a.m. hanggang 8 p.m.","5 a.m. hanggang hatinggabi","6 a.m. hanggang 10 p.m.","6 a.m. hanggang 6 p.m."],"h1":"Natatapos ito sa gabi, bago maghatinggabi.","h2":"Pinapayagan ng South Dakota instruction permit ang pagmamaneho mula 6 a.m. hanggang 10 p.m. kasama ang kwalipikadong adult na may lisensya sa tabi mo; mula 10 p.m. hanggang 6 a.m., dapat ay magulang o guardian mo ito.","p":"Tama. Ang pagmamaneho gamit ang instruction permit ay mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في South Dakota، في أي ساعات يمكن لحامل تصريح التعلّم أن يقود مع أي شخص بالغ مؤهَّل يحمل رخصة بجانبه؟","o":["من 6 صباحًا إلى 8 مساءً","من 5 صباحًا إلى منتصف الليل","من 6 صباحًا إلى 10 مساءً","من 6 صباحًا إلى 6 مساءً"],"h1":"تنتهي في وقت متأخر من المساء، قبل منتصف الليل.","h2":"يسمح تصريح التعلّم في South Dakota بالقيادة من 6 صباحًا إلى 10 مساءً مع شخص بالغ مؤهَّل يحمل رخصة بجانبك؛ ومن 10 مساءً إلى 6 صباحًا يجب أن يكون والدك أو وليّ أمرك.","p":"صحيح. القيادة بتصريح التعلّم من 6 صباحًا إلى 10 مساءً."},"ref":{"doc":"SD","page":null}},{"id":"sd-003","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, who may sit beside an instruction permit holder while driving?","o":["Any passenger age 16 or older","A parent, guardian, or licensed adult with 1+ year of experience","Any licensed driver, even a new one","Only a certified driving instructor"],"h1":"The helper needs a license and some driving experience.","h2":"A South Dakota instruction permit holder must drive with a parent, a guardian, or another licensed adult with at least one year of driving experience seated beside them.","p":"Right. The helper is a parent, guardian, or experienced licensed adult."},"es":{"q":"En Dakota del Sur, ¿quién puede ir sentado al lado de quien tiene permiso de instrucción mientras maneja?","o":["Cualquier pasajero de 16 años o más","Un padre, tutor o adulto con licencia y 1+ año de experiencia","Cualquier conductor con licencia, aunque sea nuevo","Solo un instructor de manejo certificado"],"h1":"El acompañante necesita licencia y algo de experiencia manejando.","h2":"En Dakota del Sur quien tiene permiso de instrucción debe manejar con un padre, un tutor u otro adulto con licencia y por lo menos un año de experiencia sentado a su lado.","p":"Correcto. El acompañante es un padre, tutor o adulto con licencia y experiencia."},"zh":{"q":"在 South Dakota，持学习驾照的人开车时，谁可以坐在旁边？","o":["任何 16 岁或以上的乘客","父母、监护人，或有 1 年以上驾驶经验的有驾照成年人","任何有驾照的司机，即使是新司机","只有持证的驾驶教练"],"h1":"陪同的人需要有驾照，也需要一些驾驶经验。","h2":"在 South Dakota，持学习驾照的人开车时，旁边必须坐着父母、监护人，或另一位至少有一年驾驶经验的有驾照成年人。","p":"对。陪同的人是父母、监护人，或有经验的有驾照成年人。"},"vi":{"q":"Ở South Dakota, ai được ngồi bên cạnh người có giấy phép tập lái khi lái xe?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Cha mẹ, người giám hộ, hoặc người lớn có bằng lái với 1 năm kinh nghiệm trở lên","Bất kỳ tài xế có bằng lái nào, kể cả người mới lái","Chỉ giáo viên dạy lái xe có chứng nhận"],"h1":"Người hướng dẫn cần có bằng lái và một chút kinh nghiệm lái xe.","h2":"Người có giấy phép tập lái ở South Dakota phải lái xe với cha mẹ, người giám hộ, hoặc một người lớn khác có bằng lái và ít nhất một năm kinh nghiệm lái xe ngồi bên cạnh.","p":"Đúng. Người hướng dẫn là cha mẹ, người giám hộ, hoặc người lớn có bằng lái và có kinh nghiệm."},"tl":{"q":"Sa South Dakota, sino ang puwedeng umupo sa tabi ng may instruction permit habang nagmamaneho?","o":["Sinumang pasaherong 16 taong gulang pataas","Magulang, guardian, o adult na may lisensya at 1+ taon na karanasan","Sinumang drayber na may lisensya, kahit bago pa lang","Isang sertipikadong instruktor sa pagmamaneho lamang"],"h1":"Kailangan ng katulong ang lisensya at kaunting karanasan sa pagmamaneho.","h2":"Ang may South Dakota instruction permit ay dapat magmaneho kasama ang magulang, guardian, o ibang adult na may lisensya at hindi bababa sa isang taon na karanasan sa pagmamaneho na nakaupo sa tabi niya.","p":"Tama. Ang katulong ay magulang, guardian, o adult na may lisensya at may karanasan."},"ar":{"q":"في South Dakota، من يمكنه أن يجلس بجانب حامل تصريح التعلّم أثناء القيادة؟","o":["أي راكب عمره 16 سنة أو أكثر","أحد الوالدين أو وليّ الأمر أو بالغ يحمل رخصة وله خبرة سنة أو أكثر","أي سائق يحمل رخصة، حتى لو كان جديدًا","مدرّب قيادة معتمد فقط"],"h1":"يحتاج المرافق إلى رخصة وبعض الخبرة في القيادة.","h2":"يجب على حامل تصريح التعلّم في South Dakota أن يقود ويجلس بجانبه أحد الوالدين أو وليّ الأمر أو شخص بالغ آخر يحمل رخصة وله خبرة في القيادة لا تقل عن سنة واحدة.","p":"صحيح. المرافق هو أحد الوالدين أو وليّ الأمر أو بالغ ذو خبرة يحمل رخصة."},"ref":{"doc":"SD","page":8}},{"id":"sd-004","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how long must a teen hold an instruction permit before applying for a restricted minor's permit, without driver education?","o":["90 days","180 days","365 days","275 days"],"h1":"It is about nine months.","h2":"A South Dakota teen without approved driver education must hold the instruction permit for at least 275 days before applying for a restricted minor's permit.","p":"Right. Without driver education, the wait is 275 days."},"es":{"q":"En Dakota del Sur, ¿cuánto tiempo debe tener un joven el permiso de instrucción antes de solicitar el permiso restringido de menor, sin educación vial?","o":["90 días","180 días","365 días","275 días"],"h1":"Son unos nueve meses.","h2":"En Dakota del Sur un joven sin educación vial aprobada debe tener el permiso de instrucción por lo menos 275 días antes de solicitar el permiso restringido de menor.","p":"Correcto. Sin educación vial, la espera es de 275 días."},"zh":{"q":"在 South Dakota，如果没有上驾驶教育课，青少年必须持有学习驾照多久，才能申请未成年人限制驾照（restricted minor's permit）？","o":["90 天","180 天","365 天","275 天"],"h1":"大约九个月。","h2":"在 South Dakota，没有上过批准的驾驶教育课的青少年，必须持有学习驾照至少 275 天，才能申请未成年人限制驾照。","p":"对。没有驾驶教育课，要等 275 天。"},"vi":{"q":"Ở South Dakota, nếu không học lớp giáo dục lái xe, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi xin giấy phép hạn chế cho người chưa thành niên (restricted minor's permit)?","o":["90 ngày","180 ngày","365 ngày","275 ngày"],"h1":"Khoảng chín tháng.","h2":"Ở South Dakota, thanh thiếu niên không học lớp giáo dục lái xe được chấp thuận phải giữ giấy phép tập lái ít nhất 275 ngày trước khi xin giấy phép hạn chế cho người chưa thành niên.","p":"Đúng. Không học giáo dục lái xe thì phải chờ 275 ngày."},"tl":{"q":"Sa South Dakota, gaano katagal dapat hawak ng kabataan ang instruction permit bago mag-apply ng restricted minor's permit, kung walang driver education?","o":["90 araw","180 araw","365 araw","275 araw"],"h1":"Mga siyam na buwan ito.","h2":"Ang kabataan sa South Dakota na walang aprubadong driver education ay dapat humawak ng instruction permit nang hindi bababa sa 275 araw bago mag-apply ng restricted minor's permit.","p":"Tama. Kung walang driver education, 275 araw ang paghihintay."},"ar":{"q":"في South Dakota، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل التقدّم لتصريح القاصر المقيَّد (restricted minor's permit)، بدون دورة تعليم القيادة؟","o":["90 يومًا","180 يومًا","365 يومًا","275 يومًا"],"h1":"إنها نحو تسعة أشهر.","h2":"يجب على المراهق في South Dakota الذي لم يأخذ دورة تعليم قيادة معتمدة أن يحمل تصريح التعلّم 275 يومًا على الأقل قبل التقدّم لتصريح القاصر المقيَّد.","p":"صحيح. بدون تعليم القيادة، الانتظار 275 يومًا."},"ref":{"doc":"SD","page":8}},{"id":"sd-005","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, if a teen passes an approved driver education course, how long must they hold the instruction permit?","o":["90 days","180 days","275 days","30 days"],"h1":"It is about six months.","h2":"In South Dakota a teen who passes an approved driver education course needs to hold the instruction permit for only 180 days instead of 275.","p":"Right. With driver education, the wait is 180 days."},"es":{"q":"En Dakota del Sur, si un joven aprueba un curso de educación vial aprobado, ¿cuánto tiempo debe tener el permiso de instrucción?","o":["90 días","180 días","275 días","30 días"],"h1":"Son unos seis meses.","h2":"En Dakota del Sur un joven que aprueba un curso de educación vial aprobado solo necesita tener el permiso de instrucción 180 días en lugar de 275.","p":"Correcto. Con educación vial, la espera es de 180 días."},"zh":{"q":"在 South Dakota，如果青少年通过了批准的驾驶教育课，必须持有学习驾照多久？","o":["90 天","180 天","275 天","30 天"],"h1":"大约六个月。","h2":"在 South Dakota，通过批准的驾驶教育课的青少年只需要持有学习驾照 180 天，而不是 275 天。","p":"对。有驾驶教育课，要等 180 天。"},"vi":{"q":"Ở South Dakota, nếu thanh thiếu niên học đậu một lớp giáo dục lái xe được chấp thuận, họ phải giữ giấy phép tập lái bao lâu?","o":["90 ngày","180 ngày","275 ngày","30 ngày"],"h1":"Khoảng sáu tháng.","h2":"Ở South Dakota, thanh thiếu niên học đậu lớp giáo dục lái xe được chấp thuận chỉ cần giữ giấy phép tập lái 180 ngày thay vì 275 ngày.","p":"Đúng. Có học giáo dục lái xe thì chờ 180 ngày."},"tl":{"q":"Sa South Dakota, kung pumasa ang kabataan sa aprubadong driver education course, gaano katagal niya dapat hawak ang instruction permit?","o":["90 araw","180 araw","275 araw","30 araw"],"h1":"Mga anim na buwan ito.","h2":"Sa South Dakota, ang kabataang pumasa sa aprubadong driver education course ay kailangang humawak ng instruction permit nang 180 araw lamang sa halip na 275.","p":"Tama. Kung may driver education, 180 araw ang paghihintay."},"ar":{"q":"في South Dakota، إذا نجح المراهق في دورة تعليم قيادة معتمدة، كم مدة يجب أن يحمل تصريح التعلّم؟","o":["90 يومًا","180 يومًا","275 يومًا","30 يومًا"],"h1":"إنها نحو ستة أشهر.","h2":"في South Dakota، المراهق الذي ينجح في دورة تعليم قيادة معتمدة يحتاج أن يحمل تصريح التعلّم 180 يومًا فقط بدلًا من 275.","p":"صحيح. مع تعليم القيادة، الانتظار 180 يومًا."},"ref":{"doc":"SD","page":8}},{"id":"sd-006","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how many hours of supervised driving must a teen complete on an instruction permit?","o":["20 hours","40 hours","50 hours","60 hours"],"h1":"It is a round number between 40 and 60.","h2":"A South Dakota teen must complete at least 50 hours of supervised driving on an instruction permit, and a parent or guardian confirms it in writing.","p":"Right. Fifty hours of supervised driving."},"es":{"q":"En Dakota del Sur, ¿cuántas horas de manejo supervisado debe completar un joven con el permiso de instrucción?","o":["20 horas","40 horas","50 horas","60 horas"],"h1":"Es un número redondo entre 40 y 60.","h2":"En Dakota del Sur un joven debe completar por lo menos 50 horas de manejo supervisado con el permiso de instrucción, y un padre o tutor lo confirma por escrito.","p":"Correcto. Cincuenta horas de manejo supervisado."},"zh":{"q":"在 South Dakota，青少年持学习驾照时必须完成多少小时有人监督的驾驶？","o":["20 小时","40 小时","50 小时","60 小时"],"h1":"它是 40 和 60 之间的一个整数。","h2":"在 South Dakota，青少年持学习驾照时必须完成至少 50 小时有人监督的驾驶，并由父母或监护人书面确认。","p":"对。50 小时有人监督的驾驶。"},"vi":{"q":"Ở South Dakota, thanh thiếu niên phải lái xe có người giám sát bao nhiêu giờ khi có giấy phép tập lái?","o":["20 giờ","40 giờ","50 giờ","60 giờ"],"h1":"Đó là một số tròn ở giữa 40 và 60.","h2":"Thanh thiếu niên ở South Dakota phải lái xe có người giám sát ít nhất 50 giờ khi có giấy phép tập lái, và cha mẹ hoặc người giám hộ xác nhận bằng văn bản.","p":"Đúng. Năm mươi giờ lái xe có người giám sát."},"tl":{"q":"Sa South Dakota, ilang oras ng pagmamanehong may nagbabantay ang dapat matapos ng kabataan habang may instruction permit?","o":["20 oras","40 oras","50 oras","60 oras"],"h1":"Isa itong buong numero sa pagitan ng 40 at 60.","h2":"Ang kabataan sa South Dakota ay dapat makatapos ng hindi bababa sa 50 oras ng pagmamanehong may nagbabantay habang may instruction permit, at pinapatunayan ito ng magulang o guardian nang nakasulat.","p":"Tama. Limampung oras ng pagmamanehong may nagbabantay."},"ar":{"q":"في South Dakota، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق بتصريح التعلّم؟","o":["20 ساعة","40 ساعة","50 ساعة","60 ساعة"],"h1":"إنه رقم مستدير بين 40 و60.","h2":"يجب على المراهق في South Dakota أن يكمل 50 ساعة على الأقل من القيادة تحت الإشراف بتصريح التعلّم، ويؤكد ذلك أحد الوالدين أو وليّ الأمر كتابيًا.","p":"صحيح. خمسون ساعة من القيادة تحت الإشراف."},"ref":{"doc":"SD","page":8}},{"id":"sd-007","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, of the required supervised hours, how many must be in bad weather and how many at night?","o":["At least 10 of each","At least 5 of each","At least 20 of each","At least 15 of each"],"h1":"It is the same small number for both.","h2":"In South Dakota at least 10 of the supervised hours must be in bad weather and at least 10 at night, so new drivers practice in hard conditions with an adult.","p":"Right. At least 10 hours in bad weather and 10 at night."},"es":{"q":"En Dakota del Sur, de las horas supervisadas que se exigen, ¿cuántas deben ser con mal tiempo y cuántas de noche?","o":["Por lo menos 10 de cada una","Por lo menos 5 de cada una","Por lo menos 20 de cada una","Por lo menos 15 de cada una"],"h1":"Es el mismo número pequeño para las dos.","h2":"En Dakota del Sur por lo menos 10 de las horas supervisadas deben ser con mal tiempo y por lo menos 10 de noche, para que el conductor nuevo practique en condiciones difíciles con un adulto.","p":"Correcto. Por lo menos 10 horas con mal tiempo y 10 de noche."},"zh":{"q":"在 South Dakota，规定的监督驾驶时间中，多少小时必须在恶劣天气中，多少小时必须在夜间？","o":["各至少 10 小时","各至少 5 小时","各至少 20 小时","各至少 15 小时"],"h1":"两者是同一个较小的数字。","h2":"在 South Dakota，监督驾驶时间中至少 10 小时必须在恶劣天气中，至少 10 小时必须在夜间，这样新司机可以在成年人陪同下练习困难的路况。","p":"对。至少 10 小时恶劣天气，10 小时夜间。"},"vi":{"q":"Ở South Dakota, trong số giờ lái có giám sát bắt buộc, bao nhiêu giờ phải lái khi thời tiết xấu và bao nhiêu giờ vào ban đêm?","o":["Mỗi loại ít nhất 10 giờ","Mỗi loại ít nhất 5 giờ","Mỗi loại ít nhất 20 giờ","Mỗi loại ít nhất 15 giờ"],"h1":"Cả hai là cùng một con số nhỏ.","h2":"Ở South Dakota, ít nhất 10 giờ lái có giám sát phải là khi thời tiết xấu và ít nhất 10 giờ vào ban đêm, để tài xế mới tập lái trong điều kiện khó với người lớn đi cùng.","p":"Đúng. Ít nhất 10 giờ khi thời tiết xấu và 10 giờ ban đêm."},"tl":{"q":"Sa South Dakota, sa mga kinakailangang oras na may nagbabantay, ilan ang dapat sa masamang panahon at ilan sa gabi?","o":["Hindi bababa sa 10 bawat isa","Hindi bababa sa 5 bawat isa","Hindi bababa sa 20 bawat isa","Hindi bababa sa 15 bawat isa"],"h1":"Pareho itong maliit na numero para sa dalawa.","h2":"Sa South Dakota, hindi bababa sa 10 sa mga oras na may nagbabantay ang dapat sa masamang panahon at hindi bababa sa 10 sa gabi, para makapagsanay ang mga bagong drayber sa mahihirap na kondisyon kasama ang isang adult.","p":"Tama. Hindi bababa sa 10 oras sa masamang panahon at 10 sa gabi."},"ar":{"q":"في South Dakota، من ساعات الإشراف المطلوبة، كم ساعة يجب أن تكون في طقس سيئ وكم ساعة في الليل؟","o":["10 على الأقل لكل منهما","5 على الأقل لكل منهما","20 على الأقل لكل منهما","15 على الأقل لكل منهما"],"h1":"إنه نفس الرقم الصغير للاثنين.","h2":"في South Dakota يجب أن تكون 10 ساعات على الأقل من ساعات الإشراف في طقس سيئ و10 على الأقل في الليل، حتى يتدرّب السائقون الجدد على الظروف الصعبة مع شخص بالغ.","p":"صحيح. 10 ساعات على الأقل في طقس سيئ و10 في الليل."},"ref":{"doc":"SD","page":8}},{"id":"sd-008","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, what is the rule about phones for instruction permit holders while driving?","o":["Hands-free calls are allowed","Texting is allowed when stopped","Calls to parents are allowed","No wireless device may be used"],"h1":"The rule for permit holders is strict.","h2":"A South Dakota instruction permit holder may not use any kind of wireless communication device while driving, so all attention stays on learning to drive.","p":"Right. Permit holders may not use any wireless device while driving."},"es":{"q":"En Dakota del Sur, ¿cuál es la regla sobre el teléfono para quien tiene permiso de instrucción mientras maneja?","o":["Se permiten llamadas con manos libres","Se permite escribir mensajes parado","Se permiten llamadas a los padres","No se puede usar ningún aparato inalámbrico"],"h1":"La regla para los aprendices es estricta.","h2":"En Dakota del Sur quien tiene permiso de instrucción no puede usar ningún tipo de aparato de comunicación inalámbrico mientras maneja, para que toda la atención esté en aprender a manejar.","p":"Correcto. Con permiso de instrucción no se usa ningún aparato inalámbrico al manejar."},"zh":{"q":"在 South Dakota，持学习驾照的人开车时，关于手机的规定是什么？","o":["可以用免提打电话","停车时可以发短信","可以给父母打电话","不可以使用任何无线设备"],"h1":"对持学习驾照的人，规定很严格。","h2":"在 South Dakota，持学习驾照的人开车时不可以使用任何无线通信设备，这样所有注意力都放在学开车上。","p":"对。持学习驾照的人开车时不可以使用任何无线设备。"},"vi":{"q":"Ở South Dakota, quy định về điện thoại cho người có giấy phép tập lái khi đang lái xe là gì?","o":["Được gọi điện rảnh tay","Được nhắn tin khi xe dừng","Được gọi cho cha mẹ","Không được dùng bất kỳ thiết bị không dây nào"],"h1":"Quy định cho người có giấy phép tập lái rất nghiêm.","h2":"Người có giấy phép tập lái ở South Dakota không được dùng bất kỳ loại thiết bị liên lạc không dây nào khi lái xe, để mọi sự chú ý dành cho việc học lái.","p":"Đúng. Người có giấy phép tập lái không được dùng thiết bị không dây khi lái xe."},"tl":{"q":"Sa South Dakota, ano ang patakaran tungkol sa telepono para sa may instruction permit habang nagmamaneho?","o":["Puwede ang hands-free na tawag","Puwedeng mag-text kapag nakahinto","Puwedeng tumawag sa magulang","Bawal gumamit ng anumang wireless device"],"h1":"Mahigpit ang patakaran para sa may permit.","h2":"Ang may South Dakota instruction permit ay hindi puwedeng gumamit ng anumang uri ng wireless communication device habang nagmamaneho, para nasa pag-aaral magmaneho ang buong atensyon.","p":"Tama. Bawal sa may permit ang anumang wireless device habang nagmamaneho."},"ar":{"q":"في South Dakota، ما القاعدة بشأن الهواتف لحاملي تصريح التعلّم أثناء القيادة؟","o":["المكالمات بدون استخدام اليدين مسموحة","الرسائل النصية مسموحة عند التوقف","الاتصال بالوالدين مسموح","لا يجوز استخدام أي جهاز لاسلكي"],"h1":"القاعدة لحاملي التصريح صارمة.","h2":"لا يجوز لحامل تصريح التعلّم في South Dakota استخدام أي نوع من أجهزة الاتصال اللاسلكية أثناء القيادة، حتى يبقى كل انتباهه على تعلّم القيادة.","p":"صحيح. لا يجوز لحاملي التصريح استخدام أي جهاز لاسلكي أثناء القيادة."},"ref":{"doc":"SD","page":8}},{"id":"sd-009","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, during which hours may a restricted minor's permit holder drive alone with a parent's permission?","o":["5 a.m. to 9 p.m.","6 a.m. to 10 p.m.","7 a.m. to 11 p.m.","6 a.m. to midnight"],"h1":"They are the same hours as the instruction permit.","h2":"A South Dakota restricted minor's permit holder may drive alone between 6 a.m. and 10 p.m. with a parent's permission; at other hours a parent or guardian must ride along, with some exceptions.","p":"Right. Alone from 6 a.m. to 10 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar solo quien tiene permiso restringido de menor, con permiso de sus padres?","o":["De 5 a.m. a 9 p.m.","De 6 a.m. a 10 p.m.","De 7 a.m. a 11 p.m.","De 6 a.m. a medianoche"],"h1":"Es el mismo horario del permiso de instrucción.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo entre las 6 a.m. y las 10 p.m. con permiso de sus padres; en otras horas debe ir un padre o tutor, con algunas excepciones.","p":"Correcto. Solo de 6 a.m. a 10 p.m."},"zh":{"q":"在 South Dakota，持未成年人限制驾照的人在父母允许下，哪个时间段可以单独开车？","o":["早上 5 点到晚上 9 点","早上 6 点到晚上 10 点","早上 7 点到晚上 11 点","早上 6 点到午夜"],"h1":"和学习驾照的时间相同。","h2":"在 South Dakota，持未成年人限制驾照的人在父母允许下，可以在早上 6 点到晚上 10 点之间单独开车；其他时间必须有父母或监护人同车，但有一些例外。","p":"对。早上 6 点到晚上 10 点可以单独开车。"},"vi":{"q":"Ở South Dakota, người có giấy phép hạn chế cho người chưa thành niên được lái xe một mình, khi cha mẹ cho phép, trong những giờ nào?","o":["5 giờ sáng đến 9 giờ tối","6 giờ sáng đến 10 giờ tối","7 giờ sáng đến 11 giờ tối","6 giờ sáng đến nửa đêm"],"h1":"Đó là cùng giờ với giấy phép tập lái.","h2":"Người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được lái xe một mình từ 6 giờ sáng đến 10 giờ tối khi cha mẹ cho phép; vào giờ khác, cha mẹ hoặc người giám hộ phải đi cùng, trừ một số trường hợp.","p":"Đúng. Được lái một mình từ 6 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa South Dakota, sa anong oras puwedeng magmanehong mag-isa ang may restricted minor's permit kung may pahintulot ng magulang?","o":["5 a.m. hanggang 9 p.m.","6 a.m. hanggang 10 p.m.","7 a.m. hanggang 11 p.m.","6 a.m. hanggang hatinggabi"],"h1":"Pareho ito sa oras ng instruction permit.","h2":"Ang may South Dakota restricted minor's permit ay puwedeng magmanehong mag-isa mula 6 a.m. hanggang 10 p.m. kung may pahintulot ng magulang; sa ibang oras, dapat kasama ang magulang o guardian, maliban sa ilang eksepsyon.","p":"Tama. Mag-isa mula 6 a.m. hanggang 10 p.m."},"ar":{"q":"في South Dakota، في أي ساعات يمكن لحامل تصريح القاصر المقيَّد أن يقود وحده بإذن أحد الوالدين؟","o":["من 5 صباحًا إلى 9 مساءً","من 6 صباحًا إلى 10 مساءً","من 7 صباحًا إلى 11 مساءً","من 6 صباحًا إلى منتصف الليل"],"h1":"هي نفس ساعات تصريح التعلّم.","h2":"يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن يقود وحده بين 6 صباحًا و10 مساءً بإذن أحد الوالدين؛ وفي الساعات الأخرى يجب أن يركب معه أحد الوالدين أو وليّ الأمر، مع بعض الاستثناءات.","p":"صحيح. وحده من 6 صباحًا إلى 10 مساءً."},"ref":{"doc":"SD","page":8}},{"id":"sd-010","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, which trip lets a restricted minor's permit holder drive alone after 10 p.m., by the most direct route?","o":["Going to a friend's party","Going to a late movie","Going to or from work","Going for a practice drive"],"h1":"Think of a needed trip, not one for fun.","h2":"A South Dakota restricted minor's permit holder may drive alone after 10 p.m. by the most direct route to or from work, school or church events, or farm work.","p":"Right. A direct trip to or from work is allowed."},"es":{"q":"En Dakota del Sur, ¿qué viaje permite a quien tiene permiso restringido de menor manejar solo después de las 10 p.m., por la ruta más directa?","o":["Ir a la fiesta de un amigo","Ir al cine tarde","Ir al trabajo o volver de él","Salir a practicar manejo"],"h1":"Piense en un viaje necesario, no en uno por diversión.","h2":"En Dakota del Sur quien tiene permiso restringido de menor puede manejar solo después de las 10 p.m. por la ruta más directa para ir o volver del trabajo, de eventos de la escuela o la iglesia, o de trabajo en el campo.","p":"Correcto. Un viaje directo al trabajo o desde él está permitido."},"zh":{"q":"在 South Dakota，哪种行程可以让持未成年人限制驾照的人在晚上 10 点以后走最直接的路线单独开车？","o":["去朋友的聚会","去看晚场电影","上班或下班","去练习开车"],"h1":"想一想必要的行程，而不是为了玩。","h2":"在 South Dakota，持未成年人限制驾照的人在晚上 10 点以后，可以走最直接的路线单独开车上下班、去或离开学校或教会的活动，或去做农场工作。","p":"对。直接上下班是允许的。"},"vi":{"q":"Ở South Dakota, chuyến đi nào cho phép người có giấy phép hạn chế cho người chưa thành niên lái xe một mình sau 10 giờ tối, theo đường ngắn nhất?","o":["Đi dự tiệc của bạn","Đi xem phim suất khuya","Đi làm hoặc đi làm về","Đi tập lái xe"],"h1":"Hãy nghĩ đến chuyến đi cần thiết, không phải đi chơi.","h2":"Người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được lái xe một mình sau 10 giờ tối theo đường ngắn nhất để đi làm hoặc về, đi hoặc về từ hoạt động của trường hoặc nhà thờ, hoặc làm việc nông trại.","p":"Đúng. Được đi thẳng đến chỗ làm hoặc về nhà từ chỗ làm."},"tl":{"q":"Sa South Dakota, aling biyahe ang nagpapahintulot sa may restricted minor's permit na magmanehong mag-isa pagkatapos ng 10 p.m., sa pinakadiretsong ruta?","o":["Pagpunta sa party ng kaibigan","Pagpunta sa late na sine","Papunta o pauwi mula sa trabaho","Pagpunta para magsanay magmaneho"],"h1":"Isipin ang kailangang biyahe, hindi para sa kasiyahan.","h2":"Ang may South Dakota restricted minor's permit ay puwedeng magmanehong mag-isa pagkatapos ng 10 p.m. sa pinakadiretsong ruta papunta o pauwi mula sa trabaho, mga aktibidad ng paaralan o simbahan, o trabaho sa bukid.","p":"Tama. Pinapayagan ang diretsong biyahe papunta o pauwi mula sa trabaho."},"ar":{"q":"في South Dakota، أي رحلة تسمح لحامل تصريح القاصر المقيَّد أن يقود وحده بعد 10 مساءً، بأقصر طريق مباشر؟","o":["الذهاب إلى حفلة صديق","الذهاب إلى فيلم في وقت متأخر","الذهاب إلى العمل أو العودة منه","الذهاب للتدرّب على القيادة"],"h1":"فكّر في رحلة ضرورية، وليست للتسلية.","h2":"يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن يقود وحده بعد 10 مساءً بأقصر طريق مباشر إلى العمل أو منه، أو إلى أنشطة المدرسة أو الكنيسة أو منها، أو لعمل المزرعة.","p":"صحيح. الرحلة المباشرة إلى العمل أو منه مسموحة."},"ref":{"doc":"SD","page":8}},{"id":"sd-011","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, during the first six months of a restricted minor's permit, who may ride as a passenger?","o":["Only immediate family or household members","Up to two friends under 18","Any passenger with a seat belt","Only passengers age 21 or older"],"h1":"The rule keeps friends out of the car at first.","h2":"For the first six months, a South Dakota restricted minor's permit holder may carry only immediate family or members of the same household, because friends in the car raise crash risk.","p":"Right. Only family or household members for the first six months."},"es":{"q":"En Dakota del Sur, durante los primeros seis meses del permiso restringido de menor, ¿quién puede ir como pasajero?","o":["Solo familia directa o personas de su hogar","Hasta dos amigos menores de 18","Cualquier pasajero con cinturón","Solo pasajeros de 21 años o más"],"h1":"La regla deja a los amigos fuera del carro al principio.","h2":"Durante los primeros seis meses, quien tiene permiso restringido de menor en Dakota del Sur solo puede llevar a su familia directa o a personas de su mismo hogar, porque los amigos en el carro aumentan el riesgo de choque.","p":"Correcto. Solo familia o personas del hogar los primeros seis meses."},"zh":{"q":"在 South Dakota，持未成年人限制驾照的最初六个月里，谁可以坐车当乘客？","o":["只有直系亲属或同住的家人","最多两个 18 岁以下的朋友","任何系好安全带的乘客","只有 21 岁或以上的乘客"],"h1":"这条规定在一开始不让朋友坐车。","h2":"在最初六个月里，South Dakota 持未成年人限制驾照的人只能载直系亲属或同住的家人，因为车上有朋友会提高车祸风险。","p":"对。最初六个月只能载家人或同住的人。"},"vi":{"q":"Ở South Dakota, trong sáu tháng đầu của giấy phép hạn chế cho người chưa thành niên, ai được đi xe làm hành khách?","o":["Chỉ người thân trong gia đình hoặc người cùng nhà","Tối đa hai bạn dưới 18 tuổi","Bất kỳ hành khách nào có thắt dây an toàn","Chỉ hành khách từ 21 tuổi trở lên"],"h1":"Quy định này không cho bạn bè lên xe lúc đầu.","h2":"Trong sáu tháng đầu, người có giấy phép hạn chế cho người chưa thành niên ở South Dakota chỉ được chở người thân trong gia đình hoặc người cùng nhà, vì có bạn bè trên xe làm tăng nguy cơ tai nạn.","p":"Đúng. Sáu tháng đầu chỉ chở người thân hoặc người cùng nhà."},"tl":{"q":"Sa South Dakota, sa unang anim na buwan ng restricted minor's permit, sino ang puwedeng sumakay bilang pasahero?","o":["Malapit na pamilya o kasama sa bahay lamang","Hanggang dalawang kaibigang wala pang 18","Sinumang pasaherong naka-seat belt","Mga pasaherong 21 pataas lamang"],"h1":"Hindi pinapasakay ng patakaran ang mga kaibigan sa simula.","h2":"Sa unang anim na buwan, ang may South Dakota restricted minor's permit ay puwedeng magsakay lamang ng malapit na pamilya o mga kasama sa iisang bahay, dahil tumataas ang panganib ng banggaan kapag may mga kaibigan sa sasakyan.","p":"Tama. Pamilya o kasama sa bahay lamang sa unang anim na buwan."},"ar":{"q":"في South Dakota، خلال الأشهر الستة الأولى من تصريح القاصر المقيَّد، من يمكنه الركوب كراكب؟","o":["أفراد العائلة المقرّبون أو من يسكنون في نفس البيت فقط","حتى صديقين عمرهما أقل من 18","أي راكب يربط حزام الأمان","الركاب الذين عمرهم 21 سنة أو أكثر فقط"],"h1":"القاعدة تُبعد الأصدقاء عن السيارة في البداية.","h2":"خلال الأشهر الستة الأولى، يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن ينقل أفراد العائلة المقرّبين أو من يسكنون في نفس البيت فقط، لأن وجود الأصدقاء في السيارة يزيد خطر الحوادث.","p":"صحيح. العائلة أو أهل البيت فقط خلال الأشهر الستة الأولى."},"ref":{"doc":"SD","page":8}},{"id":"sd-012","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, after the first six months of a restricted minor's permit, how many non-family passengers under 18 may ride along?","o":["None at all","Two","Three","One"],"h1":"The limit is the smallest number above zero.","h2":"After six months, a South Dakota restricted minor's permit holder may carry no more than one passenger under 18 who is not family or from the same household.","p":"Right. Only one young non-family passenger."},"es":{"q":"En Dakota del Sur, después de los primeros seis meses del permiso restringido de menor, ¿cuántos pasajeros menores de 18 que no son familia pueden ir?","o":["Ninguno","Dos","Tres","Uno"],"h1":"El límite es el número más pequeño mayor que cero.","h2":"Después de seis meses, quien tiene permiso restringido de menor en Dakota del Sur puede llevar como máximo un pasajero menor de 18 que no sea de su familia ni de su hogar.","p":"Correcto. Solo un pasajero joven que no sea de la familia."},"zh":{"q":"在 South Dakota，持未成年人限制驾照满六个月以后，可以载几个 18 岁以下的非家人乘客？","o":["一个也不行","两个","三个","一个"],"h1":"这个限制是比零大的最小数字。","h2":"满六个月以后，South Dakota 持未成年人限制驾照的人最多只能载一个 18 岁以下、不是家人也不同住的乘客。","p":"对。只能载一个非家人的年轻乘客。"},"vi":{"q":"Ở South Dakota, sau sáu tháng đầu của giấy phép hạn chế cho người chưa thành niên, được chở bao nhiêu hành khách dưới 18 tuổi không phải người nhà?","o":["Không ai cả","Hai","Ba","Một"],"h1":"Giới hạn là số nhỏ nhất lớn hơn không.","h2":"Sau sáu tháng, người có giấy phép hạn chế cho người chưa thành niên ở South Dakota được chở không quá một hành khách dưới 18 tuổi không phải người nhà hoặc người cùng nhà.","p":"Đúng. Chỉ một hành khách trẻ không phải người nhà."},"tl":{"q":"Sa South Dakota, pagkatapos ng unang anim na buwan ng restricted minor's permit, ilang pasaherong hindi kapamilya na wala pang 18 ang puwedeng isakay?","o":["Wala talaga","Dalawa","Tatlo","Isa"],"h1":"Ang limitasyon ay ang pinakamaliit na numerong higit sa zero.","h2":"Pagkatapos ng anim na buwan, ang may South Dakota restricted minor's permit ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 18 na hindi kapamilya o hindi kasama sa iisang bahay.","p":"Tama. Isang batang pasaherong hindi kapamilya lamang."},"ar":{"q":"في South Dakota، بعد الأشهر الستة الأولى من تصريح القاصر المقيَّد، كم راكبًا من غير العائلة عمره أقل من 18 يمكن أن يركب معه؟","o":["لا أحد أبدًا","اثنان","ثلاثة","واحد"],"h1":"الحد هو أصغر رقم أكبر من الصفر.","h2":"بعد ستة أشهر، يمكن لحامل تصريح القاصر المقيَّد في South Dakota أن ينقل راكبًا واحدًا فقط عمره أقل من 18 ليس من العائلة ولا من نفس البيت.","p":"صحيح. راكب شاب واحد فقط من غير العائلة."},"ref":{"doc":"SD","page":null}},{"id":"sd-013","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the youngest age for a full operator's license?","o":["15 years old","15 and a half","16 years old","17 years old"],"h1":"It comes two years after the instruction permit age.","h2":"A South Dakota teen can get a full operator's license at 16, after holding a restricted minor's permit for six months with no traffic convictions.","p":"Right. The full license starts at age 16."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para la licencia de operador completa?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es dos años después de la edad del permiso de instrucción.","h2":"En Dakota del Sur un joven puede obtener la licencia de operador completa a los 16 años, después de tener el permiso restringido de menor seis meses sin infracciones de tránsito.","p":"Correcto. La licencia completa empieza a los 16 años."},"zh":{"q":"在 South Dakota，最小几岁可以拿到正式驾照（operator's license）？","o":["15 岁","15 岁半","16 岁","17 岁"],"h1":"它比拿学习驾照的年龄晚两年。","h2":"在 South Dakota，青少年持有未成年人限制驾照六个月、没有交通违规定罪后，16 岁就可以拿到正式驾照。","p":"对。正式驾照从 16 岁开始。"},"vi":{"q":"Ở South Dakota, tuổi nhỏ nhất để có bằng lái đầy đủ (operator's license) là bao nhiêu?","o":["15 tuổi","15 tuổi rưỡi","16 tuổi","17 tuổi"],"h1":"Nó đến hai năm sau tuổi có giấy phép tập lái.","h2":"Thanh thiếu niên ở South Dakota có thể có bằng lái đầy đủ khi 16 tuổi, sau khi giữ giấy phép hạn chế cho người chưa thành niên sáu tháng mà không bị kết tội vi phạm giao thông.","p":"Đúng. Bằng lái đầy đủ bắt đầu từ 16 tuổi."},"tl":{"q":"Sa South Dakota, ano ang pinakabatang edad para sa buong operator's license (lisensya sa pagmamaneho)?","o":["15 taong gulang","15 at kalahati","16 taong gulang","17 taong gulang"],"h1":"Dumarating ito dalawang taon pagkatapos ng edad para sa instruction permit.","h2":"Makakakuha ang kabataan sa South Dakota ng buong operator's license sa edad na 16, pagkatapos humawak ng restricted minor's permit nang anim na buwan nang walang traffic conviction.","p":"Tama. Nagsisimula ang buong lisensya sa edad na 16."},"ar":{"q":"في South Dakota، ما أصغر عمر للحصول على رخصة القيادة الكاملة (operator's license)؟","o":["15 سنة","15 سنة ونصف","16 سنة","17 سنة"],"h1":"تأتي بعد سنتين من عمر تصريح التعلّم.","h2":"يمكن للمراهق في South Dakota الحصول على رخصة القيادة الكاملة في عمر 16، بعد أن يحمل تصريح القاصر المقيَّد ستة أشهر بدون أي إدانة مرورية.","p":"صحيح. تبدأ الرخصة الكاملة من عمر 16 سنة."},"ref":{"doc":"SD","page":8}},{"id":"sd-014","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a teen may not get a restricted minor's permit if they had a traffic conviction within the past how many months?","o":["3 months","6 months","12 months","24 months"],"h1":"It is half a year.","h2":"A South Dakota teen must have no traffic convictions in the six months before applying for a restricted minor's permit, which shows safe driving first.","p":"Right. No traffic convictions in the past six months."},"es":{"q":"En Dakota del Sur, ¿cuántos meses seguidos sin infracciones de tránsito necesita un joven antes de obtener el permiso restringido de menor?","o":["3 meses","6 meses","12 meses","24 meses"],"h1":"Es medio año.","h2":"En Dakota del Sur un joven no debe tener infracciones de tránsito en los seis meses antes de solicitar el permiso restringido de menor, para mostrar primero que maneja con seguridad.","p":"Correcto. Sin infracciones en los últimos seis meses."},"zh":{"q":"在 South Dakota，如果青少年在过去几个月内有交通违规定罪，就不能拿到未成年人限制驾照？","o":["3 个月","6 个月","12 个月","24 个月"],"h1":"它是半年。","h2":"在 South Dakota，青少年申请未成年人限制驾照前的六个月内，必须没有交通违规定罪，这先证明他能安全驾驶。","p":"对。过去六个月内没有交通违规定罪。"},"vi":{"q":"Ở South Dakota, thanh thiếu niên không được cấp giấy phép hạn chế cho người chưa thành niên nếu đã bị kết tội vi phạm giao thông trong bao nhiêu tháng vừa qua?","o":["3 tháng","6 tháng","12 tháng","24 tháng"],"h1":"Đó là nửa năm.","h2":"Thanh thiếu niên ở South Dakota phải không bị kết tội vi phạm giao thông nào trong sáu tháng trước khi xin giấy phép hạn chế cho người chưa thành niên, để chứng tỏ lái xe an toàn trước.","p":"Đúng. Không bị kết tội vi phạm giao thông trong sáu tháng qua."},"tl":{"q":"Sa South Dakota, hindi makakakuha ng restricted minor's permit ang kabataan kung nagkaroon siya ng traffic conviction sa nakaraang ilang buwan?","o":["3 buwan","6 na buwan","12 buwan","24 na buwan"],"h1":"Kalahating taon ito.","h2":"Ang kabataan sa South Dakota ay dapat walang traffic conviction sa anim na buwan bago mag-apply ng restricted minor's permit, na nagpapakita muna ng ligtas na pagmamaneho.","p":"Tama. Walang traffic conviction sa nakaraang anim na buwan."},"ar":{"q":"في South Dakota، لا يمكن للمراهق الحصول على تصريح القاصر المقيَّد إذا كانت لديه إدانة مرورية خلال كم شهرًا الماضية؟","o":["3 أشهر","6 أشهر","12 شهرًا","24 شهرًا"],"h1":"إنها نصف سنة.","h2":"يجب ألا تكون على المراهق في South Dakota أي إدانة مرورية في الأشهر الستة قبل التقدّم لتصريح القاصر المقيَّد، وهذا يُظهر القيادة الآمنة أولًا.","p":"صحيح. لا إدانات مرورية في الأشهر الستة الماضية."},"ref":{"doc":"SD","page":8}},{"id":"sd-015","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what happens to a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits?","o":["A 30-day suspension","Only a written warning","A free safety video","Nothing until age 18"],"h1":"The driver loses the right to drive for a short time.","h2":"In South Dakota a permit holder under 16 who is convicted of a traffic violation or breaks the permit limits has the permit suspended for 30 days.","p":"Right. It means a 30-day suspension."},"es":{"q":"En Dakota del Sur, ¿qué le pasa a quien tiene un permiso y es menor de 16 años si lo condenan por una infracción de tránsito o no cumple los límites del permiso?","o":["Una suspensión de 30 días","Solo una advertencia escrita","Un video gratis de seguridad","Nada hasta cumplir 18"],"h1":"El conductor pierde el derecho de manejar por un tiempo corto.","h2":"En Dakota del Sur, si una persona menor de 16 años con permiso es condenada por una infracción de tránsito o no cumple los límites del permiso, su permiso se suspende por 30 días.","p":"Correcto. Significa una suspensión de 30 días."},"zh":{"q":"在 South Dakota，16 岁以下持驾照许可的人如果交通违规被定罪，或违反许可的限制，会怎样？","o":["暂停 30 天","只有书面警告","一个免费的安全视频","到 18 岁前什么也不会发生"],"h1":"司机会在短时间内失去开车的权利。","h2":"在 South Dakota，16 岁以下持驾照许可的人如果交通违规被定罪，或违反许可的限制，许可会被暂停 30 天。","p":"对。这意味着暂停 30 天。"},"vi":{"q":"Ở South Dakota, điều gì xảy ra với người có giấy phép dưới 16 tuổi bị kết tội vi phạm giao thông hoặc vi phạm giới hạn của giấy phép?","o":["Bị đình chỉ 30 ngày","Chỉ bị cảnh cáo bằng văn bản","Một video an toàn miễn phí","Không có gì cho đến 18 tuổi"],"h1":"Tài xế mất quyền lái xe trong một thời gian ngắn.","h2":"Ở South Dakota, người có giấy phép dưới 16 tuổi bị kết tội vi phạm giao thông hoặc vi phạm giới hạn của giấy phép sẽ bị đình chỉ giấy phép 30 ngày.","p":"Đúng. Nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa South Dakota, ano ang mangyayari sa may permit na wala pang 16 na nahatulan sa traffic violation o lumabag sa mga limitasyon ng permit?","o":["30 araw na suspensyon","Nakasulat na babala lamang","Libreng safety video","Wala hanggang edad 18"],"h1":"Mawawalan ang drayber ng karapatang magmaneho nang maikling panahon.","h2":"Sa South Dakota, ang may permit na wala pang 16 na nahatulan sa traffic violation o lumabag sa mga limitasyon ng permit ay masususpinde ang permit nang 30 araw.","p":"Tama. Ibig sabihin nito ay 30 araw na suspensyon."},"ar":{"q":"في South Dakota، ماذا يحدث لحامل تصريح عمره أقل من 16 إذا أُدين بمخالفة مرورية أو خالف حدود التصريح؟","o":["إيقاف لمدة 30 يومًا","إنذار مكتوب فقط","فيديو سلامة مجاني","لا شيء حتى عمر 18"],"h1":"يفقد السائق حق القيادة لفترة قصيرة.","h2":"في South Dakota، حامل التصريح الذي عمره أقل من 16 ويُدان بمخالفة مرورية أو يخالف حدود التصريح يُوقَف تصريحه لمدة 30 يومًا.","p":"صحيح. يعني ذلك إيقافًا لمدة 30 يومًا."},"ref":{"doc":"SD","page":null}},{"id":"sd-016","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, what score do you need to pass the knowledge test?","o":["60 percent or higher","70 percent or higher","75 percent or higher","80 percent or higher"],"h1":"It is four out of every five questions.","h2":"To pass the South Dakota knowledge test you need a score of 80 percent or higher.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Dakota del Sur, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["60 por ciento o más","70 por ciento o más","75 por ciento o más","80 por ciento o más"],"h1":"Son cuatro de cada cinco preguntas.","h2":"Para aprobar el examen de conocimientos de Dakota del Sur usted necesita un puntaje de 80 por ciento o más.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 South Dakota，笔试（knowledge test）需要多少分才能通过？","o":["60% 或以上","70% 或以上","75% 或以上","80% 或以上"],"h1":"每五道题要答对四道。","h2":"要通过 South Dakota 的笔试，你需要得到 80% 或以上。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở South Dakota, bạn cần bao nhiêu điểm để đậu bài thi kiến thức (knowledge test)?","o":["60% trở lên","70% trở lên","75% trở lên","80% trở lên"],"h1":"Đó là bốn trên mỗi năm câu hỏi.","h2":"Để đậu bài thi kiến thức ở South Dakota, bạn cần được 80% trở lên.","p":"Đúng. Bạn cần 80% để đậu."},"tl":{"q":"Sa South Dakota, anong score ang kailangan mo para pumasa sa knowledge test (nakasulat na pagsusulit)?","o":["60 porsiyento pataas","70 porsiyento pataas","75 porsiyento pataas","80 porsiyento pataas"],"h1":"Apat ito sa bawat limang tanong.","h2":"Para pumasa sa South Dakota knowledge test, kailangan mo ng score na 80 porsiyento pataas.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في South Dakota، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة (knowledge test)؟","o":["60 بالمئة أو أكثر","70 بالمئة أو أكثر","75 بالمئة أو أكثر","80 بالمئة أو أكثر"],"h1":"إنها أربعة من كل خمسة أسئلة.","h2":"للنجاح في اختبار المعرفة في South Dakota تحتاج إلى درجة 80 بالمئة أو أكثر.","p":"صحيح. تحتاج إلى 80 بالمئة للنجاح."},"ref":{"doc":"SD","page":null}},{"id":"sd-017","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, in which languages does state law say the written knowledge test must be offered?","o":["English only","English or Spanish","English, French, or German","Any language with a fee"],"h1":"State law names one language besides English.","h2":"South Dakota law says applicants may take the written knowledge test in English or Spanish.","p":"Right. The written test is offered in English or Spanish."},"es":{"q":"En Dakota del Sur, ¿en qué idiomas dice la ley del estado que se debe ofrecer el examen escrito de conocimientos?","o":["Solo en inglés","En inglés o en español","En inglés, francés o alemán","En cualquier idioma, pagando"],"h1":"La ley del estado nombra un idioma además del inglés.","h2":"La ley de Dakota del Sur dice que se puede tomar el examen escrito de conocimientos en inglés o en español.","p":"Correcto. El examen escrito se ofrece en inglés o en español."},"zh":{"q":"在 South Dakota，州法律规定笔试必须用哪些语言提供？","o":["只有英语","英语或西班牙语","英语、法语或德语","付费后任何语言"],"h1":"州法律除了英语，还写了一种语言。","h2":"South Dakota 法律规定，申请人可以用英语或西班牙语参加笔试。","p":"对。笔试用英语或西班牙语提供。"},"vi":{"q":"Ở South Dakota, luật tiểu bang nói bài thi kiến thức viết phải có bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh hoặc tiếng Tây Ban Nha","Tiếng Anh, tiếng Pháp hoặc tiếng Đức","Bất kỳ ngôn ngữ nào nếu trả phí"],"h1":"Luật tiểu bang nêu một ngôn ngữ ngoài tiếng Anh.","h2":"Luật South Dakota nói người nộp đơn có thể làm bài thi kiến thức viết bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Bài thi viết có bằng tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa South Dakota, sa anong mga wika sinasabi ng batas ng estado na dapat ibigay ang nakasulat na knowledge test?","o":["Ingles lamang","Ingles o Espanyol","Ingles, Pranses, o Aleman","Anumang wika kung may bayad"],"h1":"Isang wika bukod sa Ingles ang binabanggit ng batas ng estado.","h2":"Sinasabi ng batas ng South Dakota na puwedeng kumuha ang mga aplikante ng nakasulat na knowledge test sa Ingles o Espanyol.","p":"Tama. Ibinibigay ang nakasulat na test sa Ingles o Espanyol."},"ar":{"q":"في South Dakota، بأي لغات يقول قانون الولاية إنه يجب تقديم اختبار المعرفة المكتوب؟","o":["الإنجليزية فقط","الإنجليزية أو الإسبانية","الإنجليزية أو الفرنسية أو الألمانية","أي لغة مقابل رسوم"],"h1":"يذكر قانون الولاية لغة واحدة غير الإنجليزية.","h2":"يقول قانون South Dakota إن المتقدّمين يمكنهم أداء اختبار المعرفة المكتوب بالإنجليزية أو الإسبانية.","p":"صحيح. يُقدَّم الاختبار المكتوب بالإنجليزية أو الإسبانية."},"ref":{"doc":"SD","page":null}},{"id":"sd-018","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, what is the highest posted speed limit on rural stretches of interstate?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Since 2015, South Dakota law allows up to 80 mph on interstates, and rural stretches may be posted at 80 mph, though the limit is lower near towns.","p":"Right. Rural South Dakota interstates go up to 80 mph."},"es":{"q":"En Dakota del Sur, ¿cuál es el límite de velocidad más alto en los tramos rurales de las interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Desde 2015, la ley de Dakota del Sur permite hasta 80 mph en las interestatales, y los tramos rurales pueden tener un límite de 80 mph, aunque el límite es más bajo cerca de los pueblos.","p":"Correcto. Las interestatales rurales de Dakota del Sur llegan a 80 mph."},"zh":{"q":"在 South Dakota，乡村路段的州际公路（interstate）上，标出的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它比大多数州都高。","h2":"从 2015 年起，South Dakota 法律允许州际公路限速最高到 80 mph，乡村路段可以标 80 mph，但靠近城镇时限速较低。","p":"对。South Dakota 乡村州际公路最高 80 mph。"},"vi":{"q":"Ở South Dakota, tốc độ tối đa được ghi trên biển ở các đoạn xa lộ liên bang (interstate) vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn hầu hết các tiểu bang.","h2":"Từ năm 2015, luật South Dakota cho phép tối đa 80 mph trên xa lộ liên bang, và các đoạn nông thôn có thể ghi 80 mph, nhưng giới hạn thấp hơn khi gần thị trấn.","p":"Đúng. Xa lộ liên bang vùng nông thôn ở South Dakota lên đến 80 mph."},"tl":{"q":"Sa South Dakota, ano ang pinakamataas na nakapaskil na speed limit sa mga bahagi ng interstate sa probinsya?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito kaysa sa karamihan ng estado.","h2":"Mula 2015, pinapayagan ng batas ng South Dakota ang hanggang 80 mph sa mga interstate, at puwedeng nakapaskil na 80 mph ang mga bahagi sa probinsya, pero mas mababa ang limit malapit sa mga bayan.","p":"Tama. Hanggang 80 mph ang mga interstate sa probinsya ng South Dakota."},"ar":{"q":"في South Dakota، ما أعلى حد سرعة مكتوب على الأجزاء الريفية من الطرق السريعة بين الولايات (interstate)؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"إنه أعلى من معظم الولايات.","h2":"منذ 2015، يسمح قانون South Dakota بسرعة تصل إلى 80 mph على الطرق السريعة بين الولايات، ويمكن أن تُكتب 80 mph على الأجزاء الريفية، لكن الحد أقل قرب المدن.","p":"صحيح. الطرق السريعة الريفية في South Dakota تصل إلى 80 mph."},"ref":{"doc":"SD","page":null}},{"id":"sd-019","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, on a two-lane highway, how much must you slow down for a vehicle on the shoulder with warning lights (limit above 20 mph)?","o":["At least 20 mph below the limit","At least 5 mph below the limit","At least 10 mph below the limit","To exactly 15 mph"],"h1":"The number is the same as the speed in the 20 mph exception.","h2":"Under the South Dakota Move Over law, on a two-lane highway you must slow to at least 20 mph below the posted limit before passing a vehicle with warning lights on the shoulder.","p":"Right. Slow to at least 20 mph below the limit."},"es":{"q":"En Dakota del Sur, en una carretera de dos carriles, ¿cuánto debe bajar la velocidad ante un vehículo en el acotamiento con luces de advertencia (límite mayor de 20 mph)?","o":["Por lo menos 20 mph menos que el límite","Por lo menos 5 mph menos que el límite","Por lo menos 10 mph menos que el límite","Exactamente a 15 mph"],"h1":"Es el mismo número de la excepción de 20 mph.","h2":"Según la ley Move Over de Dakota del Sur, en una carretera de dos carriles usted debe bajar por lo menos a 20 mph menos que el límite antes de pasar junto a un vehículo con luces de advertencia en el acotamiento.","p":"Correcto. Baje por lo menos a 20 mph menos que el límite."},"zh":{"q":"在 South Dakota，在双车道公路上，遇到路肩上开着警示灯的车辆（限速高于 20 mph），你必须减速多少？","o":["至少比限速低 20 mph","至少比限速低 5 mph","至少比限速低 10 mph","正好减到 15 mph"],"h1":"这个数字和 20 mph 例外中的速度一样。","h2":"根据 South Dakota 的让道法（Move Over law），在双车道公路上，经过路肩上开着警示灯的车辆前，你必须减速到至少比标出的限速低 20 mph。","p":"对。减速到至少比限速低 20 mph。"},"vi":{"q":"Ở South Dakota, trên đường hai làn xe, bạn phải giảm tốc bao nhiêu khi gặp xe đậu bên lề có đèn cảnh báo (giới hạn tốc độ trên 20 mph)?","o":["Thấp hơn giới hạn ít nhất 20 mph","Thấp hơn giới hạn ít nhất 5 mph","Thấp hơn giới hạn ít nhất 10 mph","Đúng 15 mph"],"h1":"Con số này giống với tốc độ trong trường hợp ngoại lệ 20 mph.","h2":"Theo luật Nhường Làn (Move Over law) của South Dakota, trên đường hai làn xe, bạn phải giảm tốc xuống thấp hơn giới hạn ghi trên biển ít nhất 20 mph trước khi đi qua xe có đèn cảnh báo bên lề.","p":"Đúng. Giảm xuống thấp hơn giới hạn ít nhất 20 mph."},"tl":{"q":"Sa South Dakota, sa highway na may dalawang lane, gaano ka dapat bumagal para sa sasakyang nasa gilid ng daan na may warning lights (limit na higit sa 20 mph)?","o":["Hindi bababa sa 20 mph na mas mababa sa limit","Hindi bababa sa 5 mph na mas mababa sa limit","Hindi bababa sa 10 mph na mas mababa sa limit","Eksaktong 15 mph"],"h1":"Pareho ang numero sa bilis sa eksepsyon na 20 mph.","h2":"Ayon sa South Dakota Move Over law, sa highway na may dalawang lane, dapat kang bumagal nang hindi bababa sa 20 mph na mas mababa sa nakapaskil na limit bago lumampas sa sasakyang may warning lights sa gilid ng daan.","p":"Tama. Bumagal nang hindi bababa sa 20 mph na mas mababa sa limit."},"ar":{"q":"في South Dakota، على طريق ذي مسارين، كم يجب أن تخفّف سرعتك لمركبة على كتف الطريق بأضواء تحذير (الحد أعلى من 20 mph)؟","o":["20 mph على الأقل تحت الحد","5 mph على الأقل تحت الحد","10 mph على الأقل تحت الحد","إلى 15 mph بالضبط"],"h1":"الرقم هو نفس السرعة في استثناء 20 mph.","h2":"حسب قانون الإفساح (Move Over law) في South Dakota، على طريق ذي مسارين يجب أن تخفّف سرعتك إلى 20 mph على الأقل تحت الحد المكتوب قبل أن تمرّ بمركبة بأضواء تحذير على كتف الطريق.","p":"صحيح. خفّف إلى 20 mph على الأقل تحت الحد."},"ref":{"doc":"SD","page":2}},{"id":"sd-020","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, on a highway with two or more lanes in your direction, when must you move to the lane farthest from a vehicle with warning lights?","o":["Only when you are beside it","Within 50 feet of it","At least 300 feet before it","After you pass it"],"h1":"Start early, about the length of a football field.","h2":"The South Dakota Move Over law says to move into the lane farthest from the vehicle at least 300 feet before reaching it, then proceed with caution.","p":"Right. Move over at least 300 feet before the vehicle."},"es":{"q":"En Dakota del Sur, en una carretera con dos o más carriles en su dirección, ¿cuándo debe pasarse al carril más lejano de un vehículo con luces de advertencia?","o":["Solo cuando esté a su lado","A menos de 50 pies de él","Por lo menos 300 pies antes","Después de pasarlo"],"h1":"Empiece temprano, como a la distancia de una cancha de fútbol americano.","h2":"La ley Move Over de Dakota del Sur dice que usted debe pasarse al carril más lejano del vehículo por lo menos 300 pies antes de llegar a él, y seguir con cuidado.","p":"Correcto. Cámbiese de carril por lo menos 300 pies antes."},"zh":{"q":"在 South Dakota，在你的方向有两条或更多车道的公路上，什么时候必须换到离开着警示灯的车辆最远的车道？","o":["只有在它旁边时","在离它 50 英尺内","在到它之前至少 300 英尺","经过它以后"],"h1":"要早一点开始，大约一个足球场的长度。","h2":"South Dakota 的让道法（Move Over law）规定，在到达那辆车之前至少 300 英尺，就要换到离它最远的车道，然后小心通过。","p":"对。在那辆车前至少 300 英尺就要让道。"},"vi":{"q":"Ở South Dakota, trên đường có hai làn trở lên theo hướng của bạn, khi nào bạn phải chuyển sang làn xa nhất so với xe có đèn cảnh báo?","o":["Chỉ khi bạn ở bên cạnh nó","Trong vòng 50 feet từ nó","Ít nhất 300 feet trước khi tới nó","Sau khi bạn đi qua nó"],"h1":"Bắt đầu sớm, khoảng chiều dài một sân bóng bầu dục.","h2":"Luật Nhường Làn (Move Over law) của South Dakota nói phải chuyển sang làn xa nhất so với chiếc xe đó ít nhất 300 feet trước khi tới nó, rồi đi tiếp cẩn thận.","p":"Đúng. Chuyển làn ít nhất 300 feet trước chiếc xe đó."},"tl":{"q":"Sa South Dakota, sa highway na may dalawa o higit pang lane sa direksyon mo, kailan ka dapat lumipat sa lane na pinakamalayo sa sasakyang may warning lights?","o":["Kapag katabi mo na lamang ito","Sa loob ng 50 talampakan mula rito","Hindi bababa sa 300 talampakan bago ito","Pagkatapos mo itong lampasan"],"h1":"Magsimula nang maaga, mga haba ng isang football field.","h2":"Sinasabi ng South Dakota Move Over law na lumipat sa lane na pinakamalayo sa sasakyan nang hindi bababa sa 300 talampakan bago ito marating, at magpatuloy nang maingat.","p":"Tama. Lumipat nang hindi bababa sa 300 talampakan bago ang sasakyan."},"ar":{"q":"في South Dakota، على طريق فيه مساران أو أكثر في اتجاهك، متى يجب أن تنتقل إلى المسار الأبعد عن مركبة بأضواء تحذير؟","o":["فقط عندما تكون بجانبها","على بعد 50 قدمًا منها","قبلها بـ 300 قدم على الأقل","بعد أن تتجاوزها"],"h1":"ابدأ مبكرًا، بطول ملعب كرة قدم أمريكية تقريبًا.","h2":"يقول قانون الإفساح (Move Over law) في South Dakota أن تنتقل إلى المسار الأبعد عن المركبة قبل الوصول إليها بـ 300 قدم على الأقل، ثم تتابع بحذر.","p":"صحيح. انتقل قبل المركبة بـ 300 قدم على الأقل."},"ref":{"doc":"SD","page":2}},{"id":"sd-021","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, since July 2025, the Move Over law covers vehicles with which lights?","o":["Only red and blue police lights","Amber, yellow, or blue warning lights","Only white headlights","Only lights on fire trucks"],"h1":"The law grew to cover road crews and tow trucks too.","h2":"Since July 2025, the South Dakota Move Over law covers any vehicle on the shoulder showing amber, yellow, or blue warning lights, not only emergency vehicles.","p":"Right. Amber, yellow, and blue warning lights are covered."},"es":{"q":"En Dakota del Sur, desde julio de 2025, la ley Move Over incluye vehículos con ¿qué luces?","o":["Solo luces rojas y azules de policía","Luces de advertencia ámbar, amarillas o azules","Solo luces delanteras blancas","Solo las luces de los bomberos"],"h1":"La ley se amplió para incluir a cuadrillas de carretera y grúas.","h2":"Desde julio de 2025, la ley Move Over de Dakota del Sur incluye a cualquier vehículo en el acotamiento con luces de advertencia ámbar, amarillas o azules, no solo a los vehículos de emergencia.","p":"Correcto. Se incluyen las luces ámbar, amarillas y azules."},"zh":{"q":"在 South Dakota，从 2025 年 7 月起，让道法（Move Over law）包括开着哪些灯的车辆？","o":["只有红色和蓝色的警灯","琥珀色、黄色或蓝色的警示灯","只有白色的车头灯","只有消防车上的灯"],"h1":"这条法律扩大了，也包括道路施工车和拖车。","h2":"从 2025 年 7 月起，South Dakota 的让道法包括任何停在路肩上、开着琥珀色、黄色或蓝色警示灯的车辆，不只是紧急车辆。","p":"对。琥珀色、黄色和蓝色警示灯都包括在内。"},"vi":{"q":"Ở South Dakota, từ tháng 7 năm 2025, luật Nhường Làn (Move Over law) áp dụng cho xe có những loại đèn nào?","o":["Chỉ đèn cảnh sát màu đỏ và xanh dương","Đèn cảnh báo màu hổ phách, vàng hoặc xanh dương","Chỉ đèn pha màu trắng","Chỉ đèn trên xe cứu hỏa"],"h1":"Luật đã mở rộng để bao gồm cả đội sửa đường và xe kéo.","h2":"Từ tháng 7 năm 2025, luật Nhường Làn của South Dakota áp dụng cho mọi xe đậu bên lề có đèn cảnh báo màu hổ phách, vàng hoặc xanh dương, không chỉ xe cấp cứu.","p":"Đúng. Đèn cảnh báo màu hổ phách, vàng và xanh dương đều được bao gồm."},"tl":{"q":"Sa South Dakota, mula Hulyo 2025, saklaw ng Move Over law ang mga sasakyang may anong mga ilaw?","o":["Pula at asul na ilaw ng pulis lamang","Amber, dilaw, o asul na warning lights","Puting headlights lamang","Mga ilaw sa trak ng bumbero lamang"],"h1":"Lumawak ang batas para saklawin din ang mga road crew at tow truck.","h2":"Mula Hulyo 2025, saklaw ng South Dakota Move Over law ang anumang sasakyan sa gilid ng daan na may amber, dilaw, o asul na warning lights, hindi lamang mga emergency vehicle.","p":"Tama. Saklaw ang amber, dilaw, at asul na warning lights."},"ar":{"q":"في South Dakota، منذ يوليو 2025، يشمل قانون الإفساح (Move Over law) المركبات ذات أي أضواء؟","o":["أضواء الشرطة الحمراء والزرقاء فقط","أضواء تحذير كهرمانية أو صفراء أو زرقاء","المصابيح الأمامية البيضاء فقط","أضواء سيارات الإطفاء فقط"],"h1":"توسّع القانون ليشمل أيضًا عمّال الطرق وشاحنات السحب.","h2":"منذ يوليو 2025، يشمل قانون الإفساح في South Dakota أي مركبة على كتف الطريق تُظهر أضواء تحذير كهرمانية أو صفراء أو زرقاء، وليس مركبات الطوارئ فقط.","p":"صحيح. أضواء التحذير الكهرمانية والصفراء والزرقاء مشمولة."},"ref":{"doc":"SD","page":2}},{"id":"sd-023","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, a driver under 21 breaks the law when driving with what blood alcohol level?","o":["0.01 percent or more","0.02 percent or more","0.05 percent or more","0.08 percent or more"],"h1":"It is far below the adult limit.","h2":"In South Dakota a driver under 21 may not drive with a blood alcohol level of 0.02 percent or more, because young drivers should not drink at all.","p":"Right. Under 21, the limit is 0.02 percent."},"es":{"q":"En Dakota del Sur, un conductor menor de 21 años viola la ley si maneja con ¿qué nivel de alcohol en la sangre?","o":["0.01 por ciento o más","0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más"],"h1":"Es mucho más bajo que el límite de los adultos.","h2":"En Dakota del Sur un conductor menor de 21 años no puede manejar con 0.02 por ciento de alcohol en la sangre o más, porque los jóvenes no deben tomar nada.","p":"Correcto. Para menores de 21, el límite es 0.02 por ciento."},"zh":{"q":"在 South Dakota，21 岁以下的司机血液酒精浓度达到多少时开车就是违法？","o":["0.01% 或以上","0.02% 或以上","0.05% 或以上","0.08% 或以上"],"h1":"它远低于成年人的限度。","h2":"在 South Dakota，21 岁以下的司机血液酒精浓度达到 0.02% 或以上时不可以开车，因为年轻司机完全不应该喝酒。","p":"对。21 岁以下，限度是 0.02%。"},"vi":{"q":"Ở South Dakota, tài xế dưới 21 tuổi phạm luật khi lái xe với nồng độ cồn trong máu bao nhiêu?","o":["0.01% trở lên","0.02% trở lên","0.05% trở lên","0.08% trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở South Dakota, tài xế dưới 21 tuổi không được lái xe với nồng độ cồn trong máu từ 0.02% trở lên, vì tài xế trẻ hoàn toàn không nên uống rượu bia.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02%."},"tl":{"q":"Sa South Dakota, lumalabag sa batas ang drayber na wala pang 21 kapag nagmamaneho na may anong blood alcohol level?","o":["0.01 porsiyento pataas","0.02 porsiyento pataas","0.05 porsiyento pataas","0.08 porsiyento pataas"],"h1":"Mas mababa ito nang malayo sa limit para sa adult.","h2":"Sa South Dakota, ang drayber na wala pang 21 ay hindi puwedeng magmaneho na may blood alcohol level na 0.02 porsiyento pataas, dahil hindi dapat uminom ng alak ang mga batang drayber.","p":"Tama. Kung wala pang 21, ang limit ay 0.02 porsiyento."},"ar":{"q":"في South Dakota، يخالف السائق الذي عمره أقل من 21 القانون عند القيادة بأي نسبة كحول في الدم؟","o":["0.01 بالمئة أو أكثر","0.02 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.08 بالمئة أو أكثر"],"h1":"إنها أقل بكثير من حد البالغين.","h2":"في South Dakota لا يجوز للسائق الذي عمره أقل من 21 أن يقود بنسبة كحول في الدم 0.02 بالمئة أو أكثر، لأن السائقين الصغار يجب ألا يشربوا الكحول أبدًا.","p":"صحيح. تحت 21، الحد هو 0.02 بالمئة."},"ref":{"doc":"SD","page":20}},{"id":"sd-024","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how long is an instruction permit valid?","o":["One year","Two years","Five years","Ten years"],"h1":"It lasts several years.","h2":"A South Dakota instruction permit is valid for five years, so a learner has plenty of time to complete the requirements.","p":"Right. The instruction permit is valid for five years."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo es válido el permiso de instrucción?","o":["Un año","Dos años","Cinco años","Diez años"],"h1":"Dura varios años.","h2":"En Dakota del Sur el permiso de instrucción es válido por cinco años, así que el aprendiz tiene mucho tiempo para cumplir los requisitos.","p":"Correcto. El permiso de instrucción es válido por cinco años."},"zh":{"q":"在 South Dakota，学习驾照有效期多久？","o":["一年","两年","五年","十年"],"h1":"它可以用好几年。","h2":"South Dakota 的学习驾照有效期是五年，所以学习的人有足够的时间完成各项要求。","p":"对。学习驾照有效期是五年。"},"vi":{"q":"Ở South Dakota, giấy phép tập lái có giá trị bao lâu?","o":["Một năm","Hai năm","Năm năm","Mười năm"],"h1":"Nó kéo dài vài năm.","h2":"Giấy phép tập lái ở South Dakota có giá trị năm năm, nên người học có nhiều thời gian để hoàn thành các yêu cầu.","p":"Đúng. Giấy phép tập lái có giá trị năm năm."},"tl":{"q":"Sa South Dakota, gaano katagal valid ang instruction permit?","o":["Isang taon","Dalawang taon","Limang taon","Sampung taon"],"h1":"Tumatagal ito nang ilang taon.","h2":"Valid nang limang taon ang South Dakota instruction permit, kaya maraming oras ang nag-aaral para matapos ang mga kinakailangan.","p":"Tama. Valid nang limang taon ang instruction permit."},"ar":{"q":"في South Dakota، ما مدة صلاحية تصريح التعلّم؟","o":["سنة واحدة","سنتان","خمس سنوات","عشر سنوات"],"h1":"يدوم عدة سنوات.","h2":"تصريح التعلّم في South Dakota صالح لمدة خمس سنوات، لذلك لدى المتعلّم وقت كافٍ لإكمال المتطلبات.","p":"صحيح. تصريح التعلّم صالح لمدة خمس سنوات."},"ref":{"doc":"SD","page":8}},{"id":"sd-025","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how many points within 12 months can lead to a license suspension?","o":["10 points","15 points","12 points","20 points"],"h1":"Over 24 months the number is 22.","h2":"In South Dakota you can have your license suspended if you collect 15 points within 12 months, or 22 points within 24 months.","p":"Right. Fifteen points in 12 months can bring a suspension."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos en 12 meses pueden llevar a la suspensión de la licencia?","o":["10 puntos","15 puntos","12 puntos","20 puntos"],"h1":"En 24 meses el número es 22.","h2":"En Dakota del Sur le pueden suspender la licencia si acumula 15 puntos en 12 meses, o 22 puntos en 24 meses.","p":"Correcto. Quince puntos en 12 meses pueden traer una suspensión."},"zh":{"q":"在 South Dakota，12 个月内累计多少分可能会导致驾照被吊销？","o":["10 分","15 分","12 分","20 分"],"h1":"在 24 个月内，这个数字是 22 分。","h2":"在 South Dakota，如果你在 12 个月内累计 15 分，或在 24 个月内累计 22 分，你的驾照可能会被吊销。","p":"对。12 个月内累计 15 分可能会导致驾照被吊销。"},"vi":{"q":"Ở South Dakota, bị bao nhiêu điểm trong 12 tháng thì có thể bị treo bằng lái?","o":["10 điểm","15 điểm","12 điểm","20 điểm"],"h1":"Trong 24 tháng thì con số là 22 điểm.","h2":"Ở South Dakota, bạn có thể bị treo bằng lái nếu bị 15 điểm trong 12 tháng, hoặc 22 điểm trong 24 tháng.","p":"Đúng. Bị 15 điểm trong 12 tháng có thể khiến bạn bị treo bằng lái."},"tl":{"q":"Sa South Dakota, ilang puntos sa loob ng 12 buwan ang maaaring magdulot ng suspensyon ng lisensya?","o":["10 puntos","15 puntos","12 puntos","20 puntos"],"h1":"Sa loob ng 24 na buwan, ang bilang ay 22.","h2":"Sa South Dakota, maaaring masuspinde ang iyong lisensya kung makakuha ka ng 15 puntos sa loob ng 12 buwan, o 22 puntos sa loob ng 24 na buwan.","p":"Tama. Ang 15 puntos sa loob ng 12 buwan ay maaaring magdulot ng suspensyon."},"ar":{"q":"في South Dakota، كم نقطة خلال 12 شهرًا يمكن أن تؤدي إلى إيقاف رخصة القيادة؟","o":["10 نقاط","15 نقطة","12 نقطة","20 نقطة"],"h1":"خلال 24 شهرًا يكون العدد 22 نقطة.","h2":"في South Dakota يمكن إيقاف رخصتك إذا جمعت 15 نقطة خلال 12 شهرًا، أو 22 نقطة خلال 24 شهرًا.","p":"صحيح. جمع 15 نقطة خلال 12 شهرًا يمكن أن يؤدي إلى إيقاف الرخصة."},"ref":{"doc":"SD","page":14}},{"id":"sd-026","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, how long can you lose your driver license for refusing an alcohol test when an officer asks?","o":["30 days","90 days","Six months","One year"],"h1":"Driving on a public road means you agreed to be tested.","h2":"South Dakota can take away your driver license for a year if you say no to an alcohol test.","p":"Right. Refusing the test can cost you your license for one year."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo puede perder su licencia de manejar si se niega a una prueba de alcohol cuando un oficial se lo pide?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Manejar en una vía pública significa que usted aceptó hacerse la prueba.","h2":"Dakota del Sur le puede quitar la licencia de manejar por un año si usted dice que no a una prueba de alcohol.","p":"Correcto. Negarse a la prueba le puede costar la licencia por un año."},"zh":{"q":"在 South Dakota，如果警察要求你做酒精测试而你拒绝，你可能会失去驾照多久？","o":["30 天","90 天","六个月","一年"],"h1":"在公共道路上开车，就表示你已经同意接受测试。","h2":"在 South Dakota，如果你拒绝做酒精测试，你的驾照可能会被收回一年。","p":"对。拒绝测试可能让你失去驾照一年。"},"vi":{"q":"Ở South Dakota, bạn có thể bị mất bằng lái bao lâu nếu từ chối kiểm tra nồng độ cồn khi cảnh sát yêu cầu?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Lái xe trên đường công cộng có nghĩa là bạn đã đồng ý để được kiểm tra.","h2":"Ở South Dakota, bằng lái của bạn có thể bị lấy đi một năm nếu bạn từ chối kiểm tra nồng độ cồn.","p":"Đúng. Từ chối kiểm tra có thể làm bạn mất bằng lái một năm."},"tl":{"q":"Sa South Dakota, gaano katagal puwedeng mawala ang driver license mo kung tumanggi ka sa alcohol test kapag hiningi ito ng pulis?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Ang pagmamaneho sa pampublikong daan ay nangangahulugang pumayag kang ma-test.","h2":"Sa South Dakota, puwedeng kunin ang driver license mo nang isang taon kung tumanggi ka sa alcohol test.","p":"Tama. Ang pagtanggi sa test ay puwedeng magpawala ng lisensya mo nang isang taon."},"ar":{"q":"في South Dakota، كم من الوقت قد تفقد رخصة القيادة إذا رفضت اختبار الكحول عندما يطلبه منك شرطي؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"القيادة على طريق عام تعني أنك وافقت على إجراء الاختبار.","h2":"في South Dakota، قد تُسحب منك رخصة القيادة لمدة سنة إذا رفضت اختبار الكحول.","p":"صحيح. رفض الاختبار قد يُفقدك رخصتك لمدة سنة واحدة."},"ref":{"doc":"SD","page":20}},{"id":"sd-027","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, children under what age must ride in a child safety seat, unless they weigh at least 40 pounds?","o":["Under 5","Under 8","Under 3","Under 10"],"h1":"Children from this age up to 18 must wear a seat belt.","h2":"In South Dakota children under 5 must ride in a child safety seat, but a child under 5 who weighs at least 40 pounds may use a seat belt.","p":"Right. Children under 5 need a child safety seat unless they weigh 40 pounds or more."},"es":{"q":"En Dakota del Sur, ¿los niños menores de qué edad deben viajar en un asiento de seguridad para niños, a menos que pesen al menos 40 libras?","o":["Menores de 5","Menores de 8","Menores de 3","Menores de 10"],"h1":"Los niños desde esta edad hasta los 18 deben usar el cinturón de seguridad.","h2":"En Dakota del Sur los niños menores de 5 años deben viajar en un asiento de seguridad para niños, pero un niño menor de 5 que pese al menos 40 libras puede usar el cinturón.","p":"Correcto. Los niños menores de 5 años necesitan un asiento de seguridad, a menos que pesen 40 libras o más."},"zh":{"q":"在 South Dakota，几岁以下的儿童必须坐儿童安全座椅，除非体重至少 40 磅？","o":["5 岁以下","8 岁以下","3 岁以下","10 岁以下"],"h1":"从这个年龄到 18 岁的孩子必须系安全带。","h2":"在 South Dakota，5 岁以下的儿童必须坐儿童安全座椅，但体重至少 40 磅的 5 岁以下儿童可以使用安全带。","p":"对。5 岁以下的儿童需要坐儿童安全座椅，除非体重达到 40 磅或以上。"},"vi":{"q":"Ở South Dakota, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em, trừ khi nặng ít nhất 40 pound?","o":["Dưới 5 tuổi","Dưới 8 tuổi","Dưới 3 tuổi","Dưới 10 tuổi"],"h1":"Trẻ em từ tuổi này đến 18 tuổi phải thắt dây an toàn.","h2":"Ở South Dakota, trẻ em dưới 5 tuổi phải ngồi ghế an toàn cho trẻ em, nhưng trẻ dưới 5 tuổi nặng ít nhất 40 pound có thể dùng dây an toàn.","p":"Đúng. Trẻ em dưới 5 tuổi cần ngồi ghế an toàn cho trẻ em, trừ khi nặng từ 40 pound trở lên."},"tl":{"q":"Sa South Dakota, ang mga batang wala pang ilang taong gulang ang dapat nakaupo sa child safety seat, maliban kung sila ay may timbang na hindi bababa sa 40 pounds?","o":["Wala pang 5","Wala pang 8","Wala pang 3","Wala pang 10"],"h1":"Ang mga bata mula sa edad na ito hanggang 18 ay dapat magsuot ng seat belt.","h2":"Sa South Dakota, ang mga batang wala pang 5 taong gulang ay dapat nakaupo sa child safety seat, pero ang batang wala pang 5 na may timbang na hindi bababa sa 40 pounds ay maaaring gumamit ng seat belt.","p":"Tama. Ang mga batang wala pang 5 ay kailangan ng child safety seat maliban kung sila ay 40 pounds o higit pa."},"ar":{"q":"في South Dakota، الأطفال دون أي عمر يجب أن يجلسوا في مقعد أمان للأطفال، إلا إذا كان وزنهم 40 رطلًا على الأقل؟","o":["دون 5 سنوات","دون 8 سنوات","دون 3 سنوات","دون 10 سنوات"],"h1":"الأطفال من هذا العمر حتى 18 سنة يجب أن يربطوا حزام الأمان.","h2":"في South Dakota يجب أن يجلس الأطفال دون 5 سنوات في مقعد أمان للأطفال، لكن الطفل دون 5 سنوات الذي يزن 40 رطلًا على الأقل يمكنه استخدام حزام الأمان.","p":"صحيح. الأطفال دون 5 سنوات يحتاجون إلى مقعد أمان للأطفال إلا إذا كان وزنهم 40 رطلًا أو أكثر."},"ref":{"doc":"SD","page":27}},{"id":"sd-028","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how long is a driver license valid?","o":["2 years","4 years","8 years","5 years"],"h1":"It is the same length of time as the instruction permit.","h2":"In South Dakota, a driver license is valid for 5 years and expires on your birthday.","p":"Right. Five years."},"es":{"q":"En Dakota del Sur, ¿por cuánto tiempo es válida una licencia de conducir?","o":["2 años","4 años","8 años","5 años"],"h1":"Es el mismo tiempo que el permiso de aprendizaje.","h2":"En Dakota del Sur, una licencia de conducir es válida por 5 años y vence el día de su cumpleaños.","p":"Correcto. Cinco años."},"zh":{"q":"在 South Dakota，驾照的有效期是多长时间？","o":["2 年","4 年","8 年","5 年"],"h1":"它和学习驾照的有效期一样长。","h2":"在 South Dakota，驾照的有效期是 5 年，在你的生日那天到期。","p":"对。5 年。"},"vi":{"q":"Ở South Dakota, bằng lái xe có giá trị trong bao lâu?","o":["2 năm","4 năm","8 năm","5 năm"],"h1":"Thời gian này bằng với thời gian của giấy phép tập lái.","h2":"Ở South Dakota, bằng lái xe có giá trị trong 5 năm và hết hạn vào ngày sinh nhật của bạn.","p":"Đúng. 5 năm."},"tl":{"q":"Sa South Dakota, gaano katagal valid ang driver license?","o":["2 taon","4 na taon","8 taon","5 taon"],"h1":"Kapareho ito ng tagal ng instruction permit.","h2":"Sa South Dakota, valid ang driver license nang 5 taon at mag-e-expire ito sa iyong kaarawan.","p":"Tama. Limang taon."},"ar":{"q":"في South Dakota، ما مدة صلاحية رخصة القيادة؟","o":["2 سنة","4 سنوات","8 سنوات","5 سنوات"],"h1":"هي نفس مدة تصريح التعلّم.","h2":"في South Dakota، تكون رخصة القيادة صالحة لمدة 5 سنوات، وتنتهي في يوم عيد ميلادك.","p":"صحيح. خمس سنوات."},"ref":{"doc":"SD","page":12}},{"id":"sd-029","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you renew a driver license that has already expired. Which test must you take besides the vision test?","o":["The knowledge test","The road skills test","A hearing test","No other test"],"h1":"It is the written test about road rules.","h2":"In South Dakota, if the license you turn in has expired, you must pass the knowledge test as well as the vision test.","p":"Right. The knowledge test too."},"es":{"q":"En Dakota del Sur, usted renueva una licencia que ya está vencida. ¿Qué examen debe tomar además del de la vista?","o":["El examen de conocimientos","El examen práctico de manejo","Un examen de audición","Ningún otro examen"],"h1":"Es el examen escrito sobre las reglas de tránsito.","h2":"En Dakota del Sur, si la licencia que entrega está vencida, debe aprobar el examen de conocimientos además del examen de la vista.","p":"Correcto. También el de conocimientos."},"zh":{"q":"在 South Dakota，你要更新一张已经过期的驾照。除了视力测试，你还必须参加哪项考试？","o":["知识考试（笔试）","路考","听力测试","不需要其他考试"],"h1":"就是关于交通规则的笔试。","h2":"在 South Dakota，如果你交回的驾照已经过期，除了视力测试，你还必须通过知识考试。","p":"对。还要考知识考试。"},"vi":{"q":"Ở South Dakota, bạn gia hạn một bằng lái đã hết hạn. Ngoài bài kiểm tra thị lực, bạn phải làm bài thi nào?","o":["Bài thi kiến thức","Bài thi lái xe trên đường","Bài kiểm tra thính lực","Không cần bài thi nào khác"],"h1":"Đó là bài thi viết về luật đi đường.","h2":"Ở South Dakota, nếu bằng lái bạn nộp lại đã hết hạn, bạn phải đậu bài thi kiến thức cùng với bài kiểm tra thị lực.","p":"Đúng. Phải thi cả bài thi kiến thức."},"tl":{"q":"Sa South Dakota, nagre-renew ka ng driver license na expired na. Anong pagsusulit ang dapat mong kunin bukod sa vision test?","o":["Ang knowledge test","Ang road skills test","Isang hearing test","Walang ibang pagsusulit"],"h1":"Ito ang nakasulat na pagsusulit tungkol sa mga patakaran sa daan.","h2":"Sa South Dakota, kung expired na ang license na isinusuko mo, kailangan mong pumasa sa knowledge test pati na sa vision test.","p":"Tama. Pati ang knowledge test."},"ar":{"q":"في South Dakota، تجدّد رخصة قيادة انتهت صلاحيتها بالفعل. ما الاختبار الذي يجب أن تأخذه إلى جانب اختبار النظر؟","o":["اختبار المعرفة","اختبار مهارات القيادة على الطريق","اختبار السمع","لا يوجد اختبار آخر"],"h1":"هو الاختبار الكتابي عن قواعد الطريق.","h2":"في South Dakota، إذا كانت الرخصة التي تسلّمها منتهية الصلاحية، يجب أن تنجح في اختبار المعرفة بالإضافة إلى اختبار النظر.","p":"صحيح. اختبار المعرفة أيضًا."},"ref":{"doc":"SD","page":12}},{"id":"sd-030","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, you park on a rural highway. How much road width must you leave for other traffic to pass?","o":["At least 5 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"Other cars must still fit past you safely.","h2":"In South Dakota, when you park on a rural highway you must leave at least 15 feet of road width for other traffic to pass.","p":"Right. At least 15 feet."},"es":{"q":"En Dakota del Sur, usted se estaciona en una carretera rural. ¿Cuánto ancho de camino debe dejar para que pase el resto del tráfico?","o":["Al menos 5 pies","Al menos 10 pies","Al menos 15 pies","Al menos 30 pies"],"h1":"Los otros autos todavía deben poder pasar con seguridad.","h2":"En Dakota del Sur, cuando se estaciona en una carretera rural debe dejar al menos 15 pies de ancho de camino para que pase el resto del tráfico.","p":"Correcto. Al menos 15 pies."},"zh":{"q":"在 South Dakota，你把车停在乡村公路上。你必须留出多宽的路面让其他车辆通过？","o":["至少 5 英尺","至少 10 英尺","至少 15 英尺","至少 30 英尺"],"h1":"其他车辆仍然必须能安全地从你旁边开过去。","h2":"在 South Dakota，当你把车停在乡村公路上时，必须留出至少 15 英尺宽的路面让其他车辆通过。","p":"对。至少 15 英尺。"},"vi":{"q":"Ở South Dakota, bạn đậu xe trên đường cao tốc ở vùng nông thôn. Bạn phải chừa lại bao nhiêu bề rộng mặt đường để xe khác đi qua?","o":["Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 15 feet","Ít nhất 30 feet"],"h1":"Các xe khác vẫn phải đi qua bạn một cách an toàn.","h2":"Ở South Dakota, khi đậu xe trên đường cao tốc ở vùng nông thôn, bạn phải chừa lại ít nhất 15 feet bề rộng mặt đường để xe khác đi qua.","p":"Đúng. Ít nhất 15 feet."},"tl":{"q":"Sa South Dakota, pumarada ka sa isang rural highway. Gaano kalapad na daan ang dapat mong iwan para makadaan ang ibang sasakyan?","o":["Hindi bababa sa 5 talampakan","Hindi bababa sa 10 talampakan","Hindi bababa sa 15 talampakan","Hindi bababa sa 30 talampakan"],"h1":"Dapat ay ligtas pa ring makadaan sa tabi mo ang ibang sasakyan.","h2":"Sa South Dakota, kapag pumarada ka sa rural highway, dapat kang mag-iwan ng hindi bababa sa 15 talampakan na lapad ng daan para makadaan ang ibang sasakyan.","p":"Tama. Hindi bababa sa 15 talampakan."},"ar":{"q":"في South Dakota، توقف سيارتك على طريق سريع ريفي. ما عرض الطريق الذي يجب أن تتركه لتمرّ السيارات الأخرى؟","o":["5 أقدام على الأقل","10 أقدام على الأقل","15 قدمًا على الأقل","30 قدمًا على الأقل"],"h1":"يجب أن تتمكن السيارات الأخرى من المرور بجانبك بأمان.","h2":"في South Dakota، عندما توقف سيارتك على طريق سريع ريفي يجب أن تترك 15 قدمًا على الأقل من عرض الطريق لتمرّ السيارات الأخرى.","p":"صحيح. 15 قدمًا على الأقل."},"ref":{"doc":"SD","page":43}},{"id":"sd-031","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, what is the smallest following distance the manual says to keep behind the vehicle ahead?","o":["2 seconds","4 seconds","1 second","6 seconds"],"h1":"Count \"one thousand one, one thousand two...\" after the car ahead passes a pole.","h2":"In South Dakota, the manual says to keep a following distance of at least 4 seconds behind the vehicle in front.","p":"Right. At least 4 seconds."},"es":{"q":"En Dakota del Sur, ¿cuál es la distancia mínima que, según el manual, debe dejar detrás del vehículo de adelante?","o":["2 segundos","4 segundos","1 segundo","6 segundos"],"h1":"Cuente \"mil uno, mil dos...\" después de que el auto de adelante pase un poste.","h2":"En Dakota del Sur, el manual dice que debe mantener una distancia de al menos 4 segundos detrás del vehículo de adelante.","p":"Correcto. Al menos 4 segundos."},"zh":{"q":"在 South Dakota，手册说与前车之间至少要保持多长的跟车距离？","o":["2 秒","4 秒","1 秒","6 秒"],"h1":"前车经过一根电线杆后，开始数“一千零一，一千零二……”。","h2":"在 South Dakota，手册说与前车之间至少要保持 4 秒的跟车距离。","p":"对。至少 4 秒。"},"vi":{"q":"Ở South Dakota, theo sách hướng dẫn, khoảng cách tối thiểu cần giữ với xe phía trước là bao nhiêu?","o":["2 giây","4 giây","1 giây","6 giây"],"h1":"Đếm \"một nghìn lẻ một, một nghìn lẻ hai...\" sau khi xe phía trước đi qua một cột điện.","h2":"Ở South Dakota, sách hướng dẫn nói phải giữ khoảng cách ít nhất 4 giây với xe phía trước.","p":"Đúng. Ít nhất 4 giây."},"tl":{"q":"Sa South Dakota, ano ang pinakamaikling layo sa sasakyang nasa unahan na sinasabi ng manual na dapat mong panatilihin?","o":["2 segundo","4 na segundo","1 segundo","6 na segundo"],"h1":"Magbilang ng \"one thousand one, one thousand two...\" pagkalampas ng sasakyan sa unahan sa isang poste.","h2":"Sa South Dakota, sinasabi ng manual na panatilihin ang layong hindi bababa sa 4 na segundo sa likod ng sasakyang nasa unahan.","p":"Tama. Hindi bababa sa 4 na segundo."},"ar":{"q":"في South Dakota، ما أقل مسافة متابعة يقول الدليل أن تتركها خلف السيارة التي أمامك؟","o":["2 ثانية","4 ثوانٍ","1 ثانية","6 ثوانٍ"],"h1":"عُدّ \"ألف وواحد، ألف واثنان...\" بعد أن تمرّ السيارة التي أمامك بعمود.","h2":"في South Dakota، يقول الدليل أن تترك مسافة متابعة لا تقل عن 4 ثوانٍ خلف السيارة التي أمامك.","p":"صحيح. 4 ثوانٍ على الأقل."},"ref":{"doc":"SD","page":51}},{"id":"sd-032","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, you just moved here and have a valid license from another state (not a CDL). How soon must you apply for a South Dakota license?","o":["Within 30 days","Within 1 year","Within 90 days","Within 10 days"],"h1":"It is about three months.","h2":"In South Dakota, a new resident with a valid out-of-state license (not a CDL) must apply for a South Dakota license within 90 days.","p":"Right. Within 90 days."},"es":{"q":"En Dakota del Sur, usted acaba de mudarse y tiene una licencia válida de otro estado (no comercial). ¿En cuánto tiempo debe solicitar una licencia de Dakota del Sur?","o":["Dentro de 30 días","Dentro de 1 año","Dentro de 90 días","Dentro de 10 días"],"h1":"Son unos tres meses.","h2":"En Dakota del Sur, un nuevo residente con una licencia válida de otro estado (no comercial) debe solicitar la licencia de Dakota del Sur dentro de 90 días.","p":"Correcto. Dentro de 90 días."},"zh":{"q":"在 South Dakota，你刚搬来，持有其他州的有效驾照（不是 CDL）。你必须在多久之内申请 South Dakota 驾照？","o":["30 天之内","1 年之内","90 天之内","10 天之内"],"h1":"大约三个月。","h2":"在 South Dakota，持有其他州有效驾照（不是 CDL）的新居民，必须在 90 天之内申请 South Dakota 驾照。","p":"对。90 天之内。"},"vi":{"q":"Ở South Dakota, bạn vừa chuyển đến và có bằng lái còn hiệu lực của tiểu bang khác (không phải CDL). Bạn phải xin bằng lái South Dakota trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 1 năm","Trong vòng 90 ngày","Trong vòng 10 ngày"],"h1":"Khoảng ba tháng.","h2":"Ở South Dakota, cư dân mới có bằng lái còn hiệu lực của tiểu bang khác (không phải CDL) phải xin bằng lái South Dakota trong vòng 90 ngày.","p":"Đúng. Trong vòng 90 ngày."},"tl":{"q":"Sa South Dakota, kakalipat mo lang dito at may valid na lisensya ka mula sa ibang estado (hindi CDL). Gaano kabilis ka dapat mag-apply para sa lisensya ng South Dakota?","o":["Sa loob ng 30 araw","Sa loob ng 1 taon","Sa loob ng 90 araw","Sa loob ng 10 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa South Dakota, ang bagong residente na may valid na lisensya mula sa ibang estado (hindi CDL) ay dapat mag-apply para sa lisensya ng South Dakota sa loob ng 90 araw.","p":"Tama. Sa loob ng 90 araw."},"ar":{"q":"في South Dakota، انتقلت للتو إلى هنا ولديك رخصة سارية من ولاية أخرى (ليست CDL). خلال كم من الوقت يجب أن تتقدّم بطلب رخصة South Dakota؟","o":["خلال 30 يومًا","خلال سنة واحدة (1)","خلال 90 يومًا","خلال 10 أيام"],"h1":"حوالي ثلاثة أشهر.","h2":"في South Dakota، يجب على المقيم الجديد الذي يحمل رخصة سارية من ولاية أخرى (ليست CDL) أن يتقدّم بطلب رخصة South Dakota خلال 90 يومًا.","p":"صحيح. خلال 90 يومًا."},"ref":{"doc":"SD","page":5}},{"id":"sd-033","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what vision score with both eyes do you need for a license with no vision limits?","o":["20/40 or better","20/100 or better","20/70 or better","20/200 or better"],"h1":"It is the same number many states use for driving without glasses limits.","h2":"In South Dakota, you need 20/40 or better with both eyes, and no worse than 20/50 in either eye, for a license with no vision limits.","p":"Right. 20/40 or better with both eyes."},"es":{"q":"En Dakota del Sur, ¿qué resultado de visión con ambos ojos necesita para una licencia sin restricciones de visión?","o":["20/40 o mejor","20/100 o mejor","20/70 o mejor","20/200 o mejor"],"h1":"Es el mismo número que usan muchos estados para manejar sin restricciones de lentes.","h2":"En Dakota del Sur, necesita 20/40 o mejor con ambos ojos, y no peor que 20/50 en ningún ojo, para una licencia sin restricciones de visión.","p":"Correcto. 20/40 o mejor con ambos ojos."},"zh":{"q":"在 South Dakota，要拿到没有视力限制的驾照，双眼视力需要达到多少？","o":["20/40 或更好","20/100 或更好","20/70 或更好","20/200 或更好"],"h1":"这和许多州用来判断开车不受眼镜限制的数字相同。","h2":"在 South Dakota，要拿到没有视力限制的驾照，双眼视力需要 20/40 或更好，而且任何一只眼睛都不能差于 20/50。","p":"对。双眼 20/40 或更好。"},"vi":{"q":"Ở South Dakota, bạn cần thị lực hai mắt là bao nhiêu để có bằng lái không bị giới hạn về thị lực?","o":["20/40 hoặc tốt hơn","20/100 hoặc tốt hơn","20/70 hoặc tốt hơn","20/200 hoặc tốt hơn"],"h1":"Đó là cùng con số mà nhiều tiểu bang dùng để cho lái xe không bị giới hạn phải đeo kính.","h2":"Ở South Dakota, bạn cần thị lực hai mắt 20/40 hoặc tốt hơn, và mỗi mắt không kém hơn 20/50, để có bằng lái không bị giới hạn về thị lực.","p":"Đúng. 20/40 hoặc tốt hơn với cả hai mắt."},"tl":{"q":"Sa South Dakota, anong vision score gamit ang dalawang mata ang kailangan mo para sa lisensya na walang limitasyon sa paningin?","o":["20/40 o mas mabuti","20/100 o mas mabuti","20/70 o mas mabuti","20/200 o mas mabuti"],"h1":"Ito ang parehong numero na ginagamit ng maraming estado para makapagmaneho nang walang limitasyon sa salamin.","h2":"Sa South Dakota, kailangan mo ng 20/40 o mas mabuti gamit ang dalawang mata, at hindi mas malala sa 20/50 sa alinmang mata, para sa lisensya na walang limitasyon sa paningin.","p":"Tama. 20/40 o mas mabuti gamit ang dalawang mata."},"ar":{"q":"في South Dakota، ما درجة النظر بالعينين معًا التي تحتاجها للحصول على رخصة بلا قيود على النظر؟","o":["20/40 أو أفضل","20/100 أو أفضل","20/70 أو أفضل","20/200 أو أفضل"],"h1":"إنه الرقم نفسه الذي تستخدمه ولايات كثيرة للقيادة بلا قيد النظارات.","h2":"في South Dakota تحتاج إلى نظر 20/40 أو أفضل بالعينين معًا، وألّا تكون أيّ عين أسوأ من 20/50، للحصول على رخصة بلا قيود على النظر.","p":"صحيح. 20/40 أو أفضل بالعينين معًا."},"ref":{"doc":"SD","page":18}},{"id":"sd-034","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how early may most drivers renew a license before it expires?","o":["Only on the day it expires","Up to 30 days before","Up to 2 years before","Up to 180 days before"],"h1":"It is about six months.","h2":"In South Dakota, most drivers may renew a license up to 180 days before it expires (drivers turning 21 follow a different rule).","p":"Right. Up to 180 days before."},"es":{"q":"En Dakota del Sur, ¿con cuánta anticipación puede la mayoría de los conductores renovar la licencia antes de que venza?","o":["Solo el día en que vence","Hasta 30 días antes","Hasta 2 años antes","Hasta 180 días antes"],"h1":"Son unos seis meses.","h2":"En Dakota del Sur, la mayoría de los conductores puede renovar la licencia hasta 180 días antes de que venza (quienes cumplen 21 años siguen otra regla).","p":"Correcto. Hasta 180 días antes."},"zh":{"q":"在 South Dakota，大多数司机最早可以在驾照到期前多久续期？","o":["只能在到期当天","最多提前 30 天","最多提前 2 年","最多提前 180 天"],"h1":"大约六个月。","h2":"在 South Dakota，大多数司机最多可以在驾照到期前 180 天续期（快满 21 岁的司机适用不同的规定）。","p":"对。最多提前 180 天。"},"vi":{"q":"Ở South Dakota, hầu hết tài xế có thể gia hạn bằng lái sớm nhất là bao lâu trước khi hết hạn?","o":["Chỉ vào ngày hết hạn","Tối đa 30 ngày trước","Tối đa 2 năm trước","Tối đa 180 ngày trước"],"h1":"Khoảng sáu tháng.","h2":"Ở South Dakota, hầu hết tài xế có thể gia hạn bằng lái tối đa 180 ngày trước khi hết hạn (tài xế sắp tròn 21 tuổi theo một quy định khác).","p":"Đúng. Tối đa 180 ngày trước."},"tl":{"q":"Sa South Dakota, gaano kaaga puwedeng mag-renew ng lisensya ang karamihan ng drayber bago ito mag-expire?","o":["Sa mismong araw lang ng pag-expire","Hanggang 30 araw bago","Hanggang 2 taon bago","Hanggang 180 araw bago"],"h1":"Mga anim na buwan ito.","h2":"Sa South Dakota, ang karamihan ng drayber ay puwedeng mag-renew ng lisensya hanggang 180 araw bago ito mag-expire (iba ang patakaran para sa mga drayber na magiging 21).","p":"Tama. Hanggang 180 araw bago."},"ar":{"q":"في South Dakota، كم مبكرًا يمكن لمعظم السائقين تجديد الرخصة قبل انتهائها؟","o":["فقط في يوم انتهائها","حتى 30 يومًا قبل ذلك","حتى سنتين (2) قبل ذلك","حتى 180 يومًا قبل ذلك"],"h1":"حوالي ستة أشهر.","h2":"في South Dakota يمكن لمعظم السائقين تجديد الرخصة حتى 180 يومًا قبل انتهائها (وللسائقين الذين سيبلغون 21 قاعدة مختلفة).","p":"صحيح. حتى 180 يومًا قبل ذلك."},"ref":{"doc":"SD","page":12}},{"id":"sd-035","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you fail the knowledge test. When is the earliest you may take it again?","o":["The same day","The next working day","After 30 days","After 6 months"],"h1":"You do not have to wait long, but not the same day.","h2":"In South Dakota, if you fail a license test, you may not test again before the next working day.","p":"Right. The next working day at the earliest."},"es":{"q":"En Dakota del Sur, usted reprueba el examen de conocimientos. ¿Cuándo es lo más pronto que puede volver a tomarlo?","o":["El mismo día","El siguiente día hábil","Después de 30 días","Después de 6 meses"],"h1":"No tiene que esperar mucho, pero no el mismo día.","h2":"En Dakota del Sur, si reprueba un examen de licencia, no puede repetirlo antes del siguiente día hábil.","p":"Correcto. Lo más pronto, el siguiente día hábil."},"zh":{"q":"在 South Dakota，你笔试没通过。最早什么时候可以再考？","o":["当天","下一个工作日","30 天以后","6 个月以后"],"h1":"不用等很久，但不能是当天。","h2":"在 South Dakota，如果你驾照考试没通过，最早要到下一个工作日才能再考。","p":"对。最早是下一个工作日。"},"vi":{"q":"Ở South Dakota, bạn thi trượt bài thi kiến thức. Sớm nhất khi nào bạn được thi lại?","o":["Ngay trong ngày","Ngày làm việc tiếp theo","Sau 30 ngày","Sau 6 tháng"],"h1":"Bạn không phải chờ lâu, nhưng không được thi lại trong cùng ngày.","h2":"Ở South Dakota, nếu bạn thi trượt một bài thi bằng lái, bạn không được thi lại trước ngày làm việc tiếp theo.","p":"Đúng. Sớm nhất là ngày làm việc tiếp theo."},"tl":{"q":"Sa South Dakota, bumagsak ka sa knowledge test. Kailan ang pinakamaagang puwede kang kumuha ulit?","o":["Sa parehong araw","Sa susunod na araw ng trabaho","Pagkalipas ng 30 araw","Pagkalipas ng 6 na buwan"],"h1":"Hindi mo kailangang maghintay nang matagal, pero hindi sa parehong araw.","h2":"Sa South Dakota, kapag bumagsak ka sa isang license test, hindi ka puwedeng kumuha ulit bago ang susunod na araw ng trabaho.","p":"Tama. Sa susunod na araw ng trabaho, pinakamaaga."},"ar":{"q":"في South Dakota، رسبت في اختبار المعرفة. ما أقرب وقت يمكنك فيه إعادته؟","o":["في اليوم نفسه","في يوم العمل التالي","بعد 30 يومًا","بعد 6 أشهر"],"h1":"ليس عليك أن تنتظر طويلًا، لكن ليس في اليوم نفسه.","h2":"في South Dakota، إذا رسبت في اختبار للرخصة، لا يجوز لك إعادته قبل يوم العمل التالي.","p":"صحيح. يوم العمل التالي هو أقرب موعد."},"ref":{"doc":"SD","page":10}},{"id":"sd-036","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, besides the 12-month rule, how many points within 24 months can lead to a license suspension?","o":["10 points","30 points","22 points","18 points"],"h1":"It is a bit more than 20.","h2":"In South Dakota, a driver who gets 22 points within 24 months can have the license suspended.","p":"Right. 22 points in 24 months."},"es":{"q":"En Dakota del Sur, además de la regla de 12 meses, ¿cuántos puntos en 24 meses pueden causar la suspensión de la licencia?","o":["10 puntos","30 puntos","22 puntos","18 puntos"],"h1":"Es un poco más de 20.","h2":"En Dakota del Sur, un conductor que acumula 22 puntos en 24 meses puede perder la licencia por suspensión.","p":"Correcto. 22 puntos en 24 meses."},"zh":{"q":"在 South Dakota，除了 12 个月的规定以外，24 个月内累计多少分可能导致驾照被吊销？","o":["10 分","30 分","22 分","18 分"],"h1":"比 20 多一点。","h2":"在 South Dakota，24 个月内累计 22 分的司机，驾照可能会被吊销。","p":"对。24 个月内 22 分。"},"vi":{"q":"Ở South Dakota, ngoài quy định 12 tháng, bao nhiêu điểm trong vòng 24 tháng có thể khiến bạn bị treo bằng lái?","o":["10 điểm","30 điểm","22 điểm","18 điểm"],"h1":"Nhiều hơn 20 một chút.","h2":"Ở South Dakota, tài xế bị 22 điểm trong vòng 24 tháng có thể bị treo bằng lái.","p":"Đúng. 22 điểm trong 24 tháng."},"tl":{"q":"Sa South Dakota, bukod sa patakarang 12 buwan, ilang puntos sa loob ng 24 na buwan ang puwedeng humantong sa suspensyon ng lisensya?","o":["10 puntos","30 puntos","22 puntos","18 puntos"],"h1":"Medyo higit sa 20 ito.","h2":"Sa South Dakota, ang drayber na makakuha ng 22 puntos sa loob ng 24 na buwan ay maaaring masuspinde ang lisensya.","p":"Tama. 22 puntos sa loob ng 24 na buwan."},"ar":{"q":"في South Dakota، إضافةً إلى قاعدة الـ 12 شهرًا، كم نقطة خلال 24 شهرًا قد تؤدي إلى إيقاف الرخصة؟","o":["10 نقاط","30 نقطة","22 نقطة","18 نقطة"],"h1":"أكثر من 20 بقليل.","h2":"في South Dakota، السائق الذي يجمع 22 نقطة خلال 24 شهرًا يمكن أن تُوقَف رخصته.","p":"صحيح. 22 نقطة خلال 24 شهرًا."},"ref":{"doc":"SD","page":14}},{"id":"sd-037","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, how long does a first license suspension for too many points last?","o":["60 days","10 days","5 years","Until age 25"],"h1":"It is about two months.","h2":"In South Dakota, a first suspension under the point system lasts 60 days.","p":"Right. 60 days."},"es":{"q":"En Dakota del Sur, ¿cuánto dura una primera suspensión de la licencia por acumular demasiados puntos?","o":["60 días","10 días","5 años","Hasta los 25 años"],"h1":"Son unos dos meses.","h2":"En Dakota del Sur, una primera suspensión por el sistema de puntos dura 60 días.","p":"Correcto. 60 días."},"zh":{"q":"在 South Dakota，因扣分过多第一次被吊销驾照，会持续多久？","o":["60 天","10 天","5 年","到 25 岁为止"],"h1":"大约两个月。","h2":"在 South Dakota，根据扣分制度第一次吊销驾照的时间是 60 天。","p":"对。60 天。"},"vi":{"q":"Ở South Dakota, lần đầu bị treo bằng lái vì quá nhiều điểm kéo dài bao lâu?","o":["60 ngày","10 ngày","5 năm","Cho đến 25 tuổi"],"h1":"Khoảng hai tháng.","h2":"Ở South Dakota, lần treo bằng đầu tiên theo hệ thống tính điểm kéo dài 60 ngày.","p":"Đúng. 60 ngày."},"tl":{"q":"Sa South Dakota, gaano katagal ang unang suspensyon ng lisensya dahil sa sobrang daming puntos?","o":["60 araw","10 araw","5 taon","Hanggang edad 25"],"h1":"Mga dalawang buwan ito.","h2":"Sa South Dakota, ang unang suspensyon sa ilalim ng point system ay tumatagal ng 60 araw.","p":"Tama. 60 araw."},"ar":{"q":"في South Dakota، كم يستمر أول إيقاف للرخصة بسبب كثرة النقاط؟","o":["60 يومًا","10 أيام","5 سنوات","حتى عمر 25"],"h1":"حوالي شهرين.","h2":"في South Dakota، يستمر أول إيقاف للرخصة بموجب نظام النقاط 60 يومًا.","p":"صحيح. 60 يومًا."},"ref":{"doc":"SD","page":14}},{"id":"sd-038","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how many points go on your record for a reckless driving conviction?","o":["2 points","3 points","4 points","8 points"],"h1":"It is one of the highest point values, just below drunk driving.","h2":"In South Dakota, a reckless driving conviction puts 8 points on your driving record.","p":"Right. 8 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos se agregan a su historial por una condena por manejo imprudente?","o":["2 puntos","3 puntos","4 puntos","8 puntos"],"h1":"Es uno de los valores más altos, justo por debajo de manejar ebrio.","h2":"En Dakota del Sur, una condena por manejo imprudente agrega 8 puntos a su historial de manejo.","p":"Correcto. 8 puntos."},"zh":{"q":"在 South Dakota，被判鲁莽驾驶（reckless driving）会在你的记录上加几分？","o":["2 分","3 分","4 分","8 分"],"h1":"这是最高的分数之一，仅次于酒后驾驶。","h2":"在 South Dakota，被判鲁莽驾驶会在你的驾驶记录上加 8 分。","p":"对。8 分。"},"vi":{"q":"Ở South Dakota, bị kết tội lái xe liều lĩnh (reckless driving) thì bị ghi bao nhiêu điểm vào hồ sơ?","o":["2 điểm","3 điểm","4 điểm","8 điểm"],"h1":"Đây là một trong những mức điểm cao nhất, chỉ thấp hơn lái xe khi say rượu.","h2":"Ở South Dakota, bị kết tội lái xe liều lĩnh sẽ bị ghi 8 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. 8 điểm."},"tl":{"q":"Sa South Dakota, ilang puntos ang ilalagay sa record mo kapag nahatulan ka ng reckless driving (pabayang pagmamaneho)?","o":["2 puntos","3 puntos","4 puntos","8 puntos"],"h1":"Isa ito sa pinakamataas na puntos, kasunod lang ng pagmamaneho nang lasing.","h2":"Sa South Dakota, ang hatol sa reckless driving ay naglalagay ng 8 puntos sa iyong driving record.","p":"Tama. 8 puntos."},"ar":{"q":"في South Dakota، كم نقطة تُضاف إلى سجلك إذا أُدِنت بالقيادة المتهوّرة (reckless driving)؟","o":["2 نقاط","3 نقاط","4 نقاط","8 نقاط"],"h1":"إنها من أعلى قيم النقاط، أقل بقليل من القيادة تحت تأثير الكحول.","h2":"في South Dakota، الإدانة بالقيادة المتهوّرة تضيف 8 نقاط إلى سجل قيادتك.","p":"صحيح. 8 نقاط."},"ref":{"doc":"SD","page":14}},{"id":"sd-039","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you are convicted of driving without proof of insurance. For how long must you file proof of insurance (an SR22) with the state?","o":["6 months","3 years","10 years","Only until the fine is paid"],"h1":"It is more than one year but less than five.","h2":"In South Dakota, after a conviction for no proof of insurance, you must file proof of insurance (an SR22) with the state for 3 years.","p":"Right. For 3 years."},"es":{"q":"En Dakota del Sur, a usted lo condenan por manejar sin prueba de seguro. ¿Por cuánto tiempo debe presentar prueba de seguro (un SR22) ante el estado?","o":["6 meses","3 años","10 años","Solo hasta pagar la multa"],"h1":"Es más de un año, pero menos de cinco.","h2":"En Dakota del Sur, después de una condena por no tener prueba de seguro, debe presentar prueba de seguro (un SR22) ante el estado durante 3 años.","p":"Correcto. Durante 3 años."},"zh":{"q":"在 South Dakota，你被判没有保险证明而开车。你必须向州政府提交保险证明（SR22）多久？","o":["6 个月","3 年","10 年","只到罚款交清为止"],"h1":"超过一年，但少于五年。","h2":"在 South Dakota，被判没有保险证明之后，你必须向州政府提交保险证明（SR22）3 年。","p":"对。3 年。"},"vi":{"q":"Ở South Dakota, bạn bị kết tội lái xe không có giấy chứng nhận bảo hiểm. Bạn phải nộp giấy chứng nhận bảo hiểm (SR22) cho tiểu bang trong bao lâu?","o":["6 tháng","3 năm","10 năm","Chỉ đến khi trả xong tiền phạt"],"h1":"Hơn một năm nhưng ít hơn năm năm.","h2":"Ở South Dakota, sau khi bị kết tội không có giấy chứng nhận bảo hiểm, bạn phải nộp giấy chứng nhận bảo hiểm (SR22) cho tiểu bang trong 3 năm.","p":"Đúng. Trong 3 năm."},"tl":{"q":"Sa South Dakota, nahatulan ka ng pagmamaneho nang walang proof of insurance (patunay ng insurance). Gaano katagal ka dapat mag-file ng proof of insurance (SR22) sa estado?","o":["6 na buwan","3 taon","10 taon","Hanggang mabayaran lang ang multa"],"h1":"Higit sa isang taon pero mas mababa sa lima.","h2":"Sa South Dakota, pagkatapos mahatulan dahil walang proof of insurance, dapat kang mag-file ng proof of insurance (SR22) sa estado nang 3 taon.","p":"Tama. Nang 3 taon."},"ar":{"q":"في South Dakota، أُدِنت بالقيادة دون إثبات تأمين. لكم من الوقت يجب أن تقدّم إثبات التأمين (SR22) إلى الولاية؟","o":["6 أشهر","3 سنوات","10 سنوات","فقط حتى تُدفع الغرامة"],"h1":"أكثر من سنة وأقل من خمس سنوات.","h2":"في South Dakota، بعد الإدانة بعدم وجود إثبات تأمين، يجب أن تقدّم إثبات التأمين (SR22) إلى الولاية لمدة 3 سنوات.","p":"صحيح. لمدة 3 سنوات."},"ref":{"doc":"SD","page":14}},{"id":"sd-040","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, a driver under 21 is caught for the first time with a blood alcohol level of 0.02 percent or more. How long is the license lost?","o":["7 days","5 years","30 days","Nothing happens the first time"],"h1":"It is about one month.","h2":"In South Dakota, a first zero tolerance offense by a driver under 21 brings a fine and a 30-day loss of the license.","p":"Right. 30 days."},"es":{"q":"En Dakota del Sur, a un conductor menor de 21 años lo detienen por primera vez con un nivel de alcohol en la sangre de 0.02 por ciento o más. ¿Por cuánto tiempo pierde la licencia?","o":["7 días","5 años","30 días","No pasa nada la primera vez"],"h1":"Es cerca de un mes.","h2":"En Dakota del Sur, una primera infracción de tolerancia cero de un conductor menor de 21 años trae una multa y la pérdida de la licencia por 30 días.","p":"Correcto. 30 días."},"zh":{"q":"在 South Dakota，一名 21 岁以下的司机第一次被查到血液酒精浓度达到 0.02% 或以上。驾照会被收回多久？","o":["7 天","5 年","30 天","第一次不会有任何后果"],"h1":"大约一个月。","h2":"在 South Dakota，21 岁以下的司机第一次违反零容忍规定，会被罚款，并失去驾照 30 天。","p":"对。30 天。"},"vi":{"q":"Ở South Dakota, một tài xế dưới 21 tuổi lần đầu bị phát hiện có nồng độ cồn trong máu từ 0.02% trở lên. Bằng lái bị mất trong bao lâu?","o":["7 ngày","5 năm","30 ngày","Lần đầu không bị gì cả"],"h1":"Khoảng một tháng.","h2":"Ở South Dakota, tài xế dưới 21 tuổi vi phạm quy định không dung thứ (zero tolerance) lần đầu sẽ bị phạt tiền và mất bằng lái 30 ngày.","p":"Đúng. 30 ngày."},"tl":{"q":"Sa South Dakota, unang beses nahuli ang drayber na wala pang 21 na may blood alcohol level na 0.02 porsiyento pataas. Gaano katagal mawawala ang lisensya?","o":["7 araw","5 taon","30 araw","Walang mangyayari sa unang beses"],"h1":"Mga isang buwan ito.","h2":"Sa South Dakota, ang unang zero tolerance na paglabag ng drayber na wala pang 21 ay may multa at pagkawala ng lisensya nang 30 araw.","p":"Tama. 30 araw."},"ar":{"q":"في South Dakota، ضُبط سائق عمره أقل من 21 لأول مرة ونسبة الكحول في دمه 0.02 بالمئة أو أكثر. لكم من الوقت يفقد الرخصة؟","o":["7 أيام","5 سنوات","30 يومًا","لا يحدث شيء في المرة الأولى"],"h1":"حوالي شهر واحد.","h2":"في South Dakota، المخالفة الأولى لقاعدة عدم التسامح (zero tolerance) من سائق عمره أقل من 21 تؤدي إلى غرامة وفقدان الرخصة لمدة 30 يومًا.","p":"صحيح. 30 يومًا."},"ref":{"doc":"SD","page":20}},{"id":"sd-041","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, what kind of crime is a third offense for driving while intoxicated (DWI)?","o":["A parking ticket","A petty offense","A warning only","A felony"],"h1":"The third time is much more serious than the first two.","h2":"In South Dakota, a third DWI offense is a felony, with possible prison time and at least one year without a license.","p":"Right. A felony."},"es":{"q":"En Dakota del Sur, ¿qué tipo de delito es una tercera infracción por manejar en estado de ebriedad (DWI)?","o":["Una multa de estacionamiento","Una infracción menor","Solo una advertencia","Un delito grave (felonía)"],"h1":"La tercera vez es mucho más grave que las dos primeras.","h2":"En Dakota del Sur, una tercera infracción por DWI es un delito grave (felonía), con posible prisión y al menos un año sin licencia.","p":"Correcto. Un delito grave (felonía)."},"zh":{"q":"在 South Dakota，第三次醉酒驾驶（DWI）属于哪种罪行？","o":["停车罚单","轻微违法（petty offense）","只是警告","重罪（felony）"],"h1":"第三次比前两次严重得多。","h2":"在 South Dakota，第三次醉酒驾驶（DWI）是重罪，可能要坐牢，而且至少一年不能有驾照。","p":"对。重罪。"},"vi":{"q":"Ở South Dakota, lái xe khi say rượu (DWI) lần thứ ba là loại tội gì?","o":["Một vé phạt đậu xe","Một vi phạm nhẹ (petty offense)","Chỉ bị cảnh cáo","Một trọng tội (felony)"],"h1":"Lần thứ ba nghiêm trọng hơn nhiều so với hai lần đầu.","h2":"Ở South Dakota, phạm tội DWI lần thứ ba là trọng tội, có thể bị đi tù và mất bằng lái ít nhất một năm.","p":"Đúng. Một trọng tội."},"tl":{"q":"Sa South Dakota, anong uri ng krimen ang ikatlong paglabag sa pagmamaneho nang lasing (DWI)?","o":["Isang parking ticket","Isang petty offense (maliit na paglabag)","Babala lang","Isang felony (mabigat na krimen)"],"h1":"Mas mabigat ang ikatlong beses kaysa sa unang dalawa.","h2":"Sa South Dakota, ang ikatlong DWI ay isang felony, na may posibleng pagkakulong at hindi bababa sa isang taon na walang lisensya.","p":"Tama. Isang felony."},"ar":{"q":"في South Dakota، ما نوع الجريمة في المخالفة الثالثة للقيادة تحت تأثير الكحول (DWI)؟","o":["مخالفة وقوف","مخالفة بسيطة (petty offense)","إنذار فقط","جناية (felony)"],"h1":"المرة الثالثة أخطر بكثير من المرتين الأوليين.","h2":"في South Dakota، المخالفة الثالثة للقيادة تحت تأثير الكحول (DWI) جناية، مع احتمال السجن وسنة واحدة على الأقل بلا رخصة.","p":"صحيح. جناية."},"ref":{"doc":"SD","page":21}},{"id":"sd-042","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, who must wear a seat belt while the car is moving?","o":["The driver, front-seat passengers, and children under 18","Only the driver","Only children under 5","Only people on the interstate"],"h1":"Think of the front seat, and young people in any seat.","h2":"In South Dakota, the driver, all front-seat passengers, and children under 18 must wear a seat belt or proper restraint while the car is moving.","p":"Right. The driver, front-seat passengers, and children under 18."},"es":{"q":"En Dakota del Sur, ¿quién debe usar el cinturón de seguridad mientras el auto está en movimiento?","o":["El conductor, los pasajeros del asiento delantero y los menores de 18 años","Solo el conductor","Solo los niños menores de 5 años","Solo las personas en la autopista interestatal"],"h1":"Piense en el asiento delantero y en los jóvenes en cualquier asiento.","h2":"En Dakota del Sur, el conductor, todos los pasajeros del asiento delantero y los menores de 18 años deben usar cinturón de seguridad o el sistema de retención adecuado mientras el auto está en movimiento.","p":"Correcto. El conductor, los pasajeros del asiento delantero y los menores de 18 años."},"zh":{"q":"在 South Dakota，车子行驶时谁必须系安全带？","o":["司机、前座乘客和 18 岁以下的儿童","只有司机","只有 5 岁以下的儿童","只有在州际公路上的人"],"h1":"想想前座，以及坐在任何座位的年轻人。","h2":"在 South Dakota，车子行驶时，司机、所有前座乘客和 18 岁以下的儿童都必须系安全带或使用合适的约束装置。","p":"对。司机、前座乘客和 18 岁以下的儿童。"},"vi":{"q":"Ở South Dakota, ai phải thắt dây an toàn khi xe đang chạy?","o":["Tài xế, hành khách ngồi ghế trước, và trẻ em dưới 18 tuổi","Chỉ tài xế","Chỉ trẻ em dưới 5 tuổi","Chỉ người đi trên xa lộ liên bang (interstate)"],"h1":"Hãy nghĩ đến ghế trước, và người trẻ ở bất kỳ ghế nào.","h2":"Ở South Dakota, tài xế, tất cả hành khách ngồi ghế trước, và trẻ em dưới 18 tuổi phải thắt dây an toàn hoặc dùng dụng cụ bảo vệ phù hợp khi xe đang chạy.","p":"Đúng. Tài xế, hành khách ngồi ghế trước, và trẻ em dưới 18 tuổi."},"tl":{"q":"Sa South Dakota, sino ang dapat magsuot ng seat belt habang umaandar ang sasakyan?","o":["Ang drayber, mga pasahero sa harap, at mga batang wala pang 18","Ang drayber lang","Mga batang wala pang 5 lang","Mga tao lang sa interstate"],"h1":"Isipin ang upuan sa harap, at mga kabataan sa kahit anong upuan.","h2":"Sa South Dakota, ang drayber, lahat ng pasahero sa harap, at mga batang wala pang 18 ay dapat magsuot ng seat belt o tamang restraint habang umaandar ang sasakyan.","p":"Tama. Ang drayber, mga pasahero sa harap, at mga batang wala pang 18."},"ar":{"q":"في South Dakota، من يجب أن يضع حزام الأمان أثناء سير السيارة؟","o":["السائق وركاب المقعد الأمامي والأطفال الذين أعمارهم أقل من 18","السائق فقط","الأطفال الذين أعمارهم أقل من 5 فقط","الأشخاص على الطريق السريع بين الولايات (interstate) فقط"],"h1":"فكّر في المقعد الأمامي، وفي الصغار في أي مقعد.","h2":"في South Dakota، يجب على السائق وجميع ركاب المقعد الأمامي والأطفال الذين أعمارهم أقل من 18 وضع حزام الأمان أو وسيلة تثبيت مناسبة أثناء سير السيارة.","p":"صحيح. السائق وركاب المقعد الأمامي والأطفال الذين أعمارهم أقل من 18."},"ref":{"doc":"SD","page":26}},{"id":"sd-043","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, what is the least light that window tint on the windshield and the front side windows must let through?","o":["5 percent","35 percent","90 percent","Any tint is allowed"],"h1":"It is about one third of the light.","h2":"In South Dakota, film on the windshield and the windows next to the driver may not cut the light that gets through below 35 percent.","p":"Right. 35 percent."},"es":{"q":"En Dakota del Sur, ¿cuál es la cantidad mínima de luz que debe dejar pasar el polarizado del parabrisas y de las ventanas laterales delanteras?","o":["5 por ciento","35 por ciento","90 por ciento","Se permite cualquier polarizado"],"h1":"Es cerca de un tercio de la luz.","h2":"En Dakota del Sur, la película en el parabrisas y en las ventanas junto al conductor no puede reducir la luz que pasa a menos del 35 por ciento.","p":"Correcto. 35 por ciento."},"zh":{"q":"在 South Dakota，挡风玻璃和前侧车窗的贴膜至少要让多少光线透过？","o":["5%","35%","90%","任何贴膜都可以"],"h1":"大约三分之一的光线。","h2":"在 South Dakota，挡风玻璃和司机旁边车窗上的贴膜，不能让透过的光线低于 35%。","p":"对。35%。"},"vi":{"q":"Ở South Dakota, phim dán kính trên kính chắn gió và cửa sổ bên phía trước phải cho ít nhất bao nhiêu ánh sáng đi qua?","o":["5%","35%","90%","Phim loại nào cũng được"],"h1":"Khoảng một phần ba ánh sáng.","h2":"Ở South Dakota, phim dán trên kính chắn gió và cửa sổ cạnh tài xế không được làm ánh sáng đi qua thấp hơn 35%.","p":"Đúng. 35%."},"tl":{"q":"Sa South Dakota, ano ang pinakamababang dami ng liwanag na dapat palusutin ng window tint sa windshield at sa mga bintana sa harap na gilid?","o":["5 porsiyento","35 porsiyento","90 porsiyento","Puwede ang kahit anong tint"],"h1":"Mga isang-katlo ng liwanag ito.","h2":"Sa South Dakota, ang film sa windshield at sa mga bintana sa tabi ng drayber ay hindi puwedeng magpababa sa liwanag na lumulusot nang mas mababa sa 35 porsiyento.","p":"Tama. 35 porsiyento."},"ar":{"q":"في South Dakota، ما أقل نسبة من الضوء يجب أن يسمح التظليل على الزجاج الأمامي والنوافذ الجانبية الأمامية بمرورها؟","o":["5 بالمئة","35 بالمئة","90 بالمئة","أي تظليل مسموح"],"h1":"حوالي ثلث الضوء.","h2":"في South Dakota، يجب ألّا يقلّل الفيلم على الزجاج الأمامي والنوافذ المجاورة للسائق الضوء المارّ إلى أقل من 35 بالمئة.","p":"صحيح. 35 بالمئة."},"ref":{"doc":"SD","page":24}},{"id":"sd-044","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, you pass a bicycle on a road where the speed limit is above 35 mph. How much space must you leave?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"On faster roads, the law asks for twice the space used on slow streets.","h2":"In South Dakota, you must leave at least 6 feet when passing a bicycle where the limit is above 35 mph, and at least 3 feet where it is 35 mph or less.","p":"Right. At least 6 feet."},"es":{"q":"En Dakota del Sur, usted rebasa a una bicicleta en una vía con límite de velocidad mayor de 35 mph. ¿Cuánto espacio debe dejar?","o":["1 pie","2 pies","3 pies","6 pies"],"h1":"En vías más rápidas, la ley pide el doble del espacio que en calles lentas.","h2":"En Dakota del Sur, debe dejar al menos 6 pies al rebasar a una bicicleta donde el límite es mayor de 35 mph, y al menos 3 pies donde es de 35 mph o menos.","p":"Correcto. Al menos 6 pies."},"zh":{"q":"在 South Dakota，你在限速高于 35 mph 的路上超过一辆自行车。你必须留出多少空间？","o":["1 英尺","2 英尺","3 英尺","6 英尺"],"h1":"在较快的路上，法律要求的空间是慢速街道的两倍。","h2":"在 South Dakota，在限速高于 35 mph 的路上超过自行车时，你必须留出至少 6 英尺；在限速 35 mph 或以下的地方，至少 3 英尺。","p":"对。至少 6 英尺。"},"vi":{"q":"Ở South Dakota, bạn vượt một xe đạp trên con đường có giới hạn tốc độ trên 35 mph. Bạn phải chừa khoảng cách bao nhiêu?","o":["1 foot","2 feet","3 feet","6 feet"],"h1":"Trên đường nhanh hơn, luật yêu cầu khoảng cách gấp đôi so với đường chậm.","h2":"Ở South Dakota, bạn phải chừa ít nhất 6 feet khi vượt xe đạp ở nơi giới hạn tốc độ trên 35 mph, và ít nhất 3 feet ở nơi giới hạn là 35 mph trở xuống.","p":"Đúng. Ít nhất 6 feet."},"tl":{"q":"Sa South Dakota, nilalampasan mo ang isang bisikleta sa daan na ang speed limit ay higit sa 35 mph. Gaano kalaking espasyo ang dapat mong iwan?","o":["1 talampakan","2 talampakan","3 talampakan","6 talampakan"],"h1":"Sa mas mabibilis na daan, doble ang hinihinging espasyo ng batas kumpara sa mabagal na kalye.","h2":"Sa South Dakota, dapat kang mag-iwan ng hindi bababa sa 6 talampakan kapag nilalampasan ang bisikleta kung saan higit sa 35 mph ang limit, at hindi bababa sa 3 talampakan kung saan 35 mph o mas mababa ito.","p":"Tama. Hindi bababa sa 6 talampakan."},"ar":{"q":"في South Dakota، تتجاوز درّاجة هوائية على طريق حدّ السرعة فيه أكثر من 35 mph. ما المسافة التي يجب أن تتركها؟","o":["1 قدم","2 قدم","3 أقدام","6 أقدام"],"h1":"على الطرق الأسرع يطلب القانون ضعف المسافة المطلوبة في الشوارع البطيئة.","h2":"في South Dakota، يجب أن تترك 6 أقدام على الأقل عند تجاوز درّاجة هوائية حيث يكون حدّ السرعة أكثر من 35 mph، و3 أقدام على الأقل حيث يكون 35 mph أو أقل.","p":"صحيح. 6 أقدام على الأقل."},"ref":{"doc":"SD","page":62}},{"id":"sd-045","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, how far before a turn should you turn on your signal?","o":["10 feet","1,000 feet","100 feet","Only once you start turning"],"h1":"It is about the length of a few houses.","h2":"In South Dakota, you should signal at least 100 feet before you turn.","p":"Right. 100 feet before the turn."},"es":{"q":"En Dakota del Sur, ¿con cuánta distancia antes de girar debe poner la direccional?","o":["10 pies","1,000 pies","100 pies","Solo cuando empieza a girar"],"h1":"Es más o menos el largo de unas cuantas casas.","h2":"En Dakota del Sur, debe poner la direccional al menos 100 pies antes de girar.","p":"Correcto. 100 pies antes del giro."},"zh":{"q":"在 South Dakota，转弯前多远应该打开转向灯？","o":["10 英尺","1,000 英尺","100 英尺","开始转弯时才打"],"h1":"大约几栋房子的长度。","h2":"在 South Dakota，你应该在转弯前至少 100 英尺打转向灯。","p":"对。转弯前 100 英尺。"},"vi":{"q":"Ở South Dakota, bạn nên bật đèn xi nhan bao xa trước khi rẽ?","o":["10 feet","1,000 feet","100 feet","Chỉ khi bắt đầu rẽ"],"h1":"Khoảng chiều dài của vài căn nhà.","h2":"Ở South Dakota, bạn nên bật xi nhan ít nhất 100 feet trước khi rẽ.","p":"Đúng. 100 feet trước khi rẽ."},"tl":{"q":"Sa South Dakota, gaano kalayo bago lumiko dapat mong buksan ang iyong signal?","o":["10 talampakan","1,000 talampakan","100 talampakan","Kapag nagsisimula ka na lang lumiko"],"h1":"Mga haba ito ng ilang bahay.","h2":"Sa South Dakota, dapat kang mag-signal nang hindi bababa sa 100 talampakan bago ka lumiko.","p":"Tama. 100 talampakan bago lumiko."},"ar":{"q":"في South Dakota، قبل المنعطف بكم يجب أن تشغّل إشارة الانعطاف؟","o":["10 أقدام","1,000 قدم","100 قدم","فقط عندما تبدأ الانعطاف"],"h1":"حوالي طول بضعة بيوت.","h2":"في South Dakota، يجب أن تشغّل الإشارة قبل الانعطاف بـ 100 قدم على الأقل.","p":"صحيح. قبل المنعطف بـ 100 قدم."},"ref":{"doc":"SD","page":56}},{"id":"sd-046","scope":"SD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Dakota, a car is coming toward you at night. Within what distance should you dim your high beams?","o":["500 feet","50 feet","100 feet","2 miles"],"h1":"It is about one block.","h2":"In South Dakota, you should dim your high beams when you come within 500 feet of a car coming toward you.","p":"Right. Within 500 feet."},"es":{"q":"En Dakota del Sur, de noche, un auto viene hacia usted. ¿A qué distancia debe bajar las luces altas?","o":["500 pies","50 pies","100 pies","2 millas"],"h1":"Es más o menos una cuadra.","h2":"En Dakota del Sur, debe bajar las luces altas cuando esté a menos de 500 pies de un auto que viene hacia usted.","p":"Correcto. A 500 pies."},"zh":{"q":"在 South Dakota，晚上有车迎面开来。在多远的距离内你应该把远光灯调暗？","o":["500 英尺","50 英尺","100 英尺","2 英里"],"h1":"大约一个街区。","h2":"在 South Dakota，当你和迎面开来的车距离 500 英尺以内时，应该把远光灯调暗。","p":"对。500 英尺以内。"},"vi":{"q":"Ở South Dakota, ban đêm có xe chạy ngược chiều về phía bạn. Trong khoảng cách bao nhiêu bạn nên hạ đèn pha?","o":["500 feet","50 feet","100 feet","2 dặm"],"h1":"Khoảng một dãy phố.","h2":"Ở South Dakota, bạn nên hạ đèn pha khi cách xe chạy ngược chiều trong vòng 500 feet.","p":"Đúng. Trong vòng 500 feet."},"tl":{"q":"Sa South Dakota, may sasakyang paparating sa iyo sa gabi. Sa loob ng anong layo dapat mong i-dim ang iyong high beams?","o":["500 talampakan","50 talampakan","100 talampakan","2 milya"],"h1":"Mga isang block ito.","h2":"Sa South Dakota, dapat mong i-dim ang iyong high beams kapag nasa loob ka ng 500 talampakan mula sa sasakyang paparating sa iyo.","p":"Tama. Sa loob ng 500 talampakan."},"ar":{"q":"في South Dakota، تقترب منك سيارة من الاتجاه المقابل ليلًا. ضمن أي مسافة يجب أن تخفض الأضواء العالية؟","o":["500 قدم","50 قدمًا","100 قدم","2 ميل"],"h1":"حوالي مربع سكني واحد.","h2":"في South Dakota، يجب أن تخفض الأضواء العالية عندما تصبح على بُعد 500 قدم من سيارة قادمة نحوك.","p":"صحيح. ضمن 500 قدم."},"ref":{"doc":"SD","page":55}},{"id":"sd-047","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, a snowplow has its red or amber lights on, on a road with a limit of 35 mph or more. How far behind it must you stay?","o":["20 feet","At least 200 feet","At least 1 mile","You may pass it on the right at any time"],"h1":"Plows throw snow and stop often. Leave a lot of room.","h2":"In South Dakota, on roads with a limit of 35 mph or more, you must stay at least 200 feet behind a snowplow with its red or amber lights on.","p":"Right. At least 200 feet."},"es":{"q":"En Dakota del Sur, un quitanieves tiene encendidas sus luces rojas o ámbar, en una vía con límite de 35 mph o más. ¿A qué distancia detrás de él debe mantenerse?","o":["20 pies","Al menos 200 pies","Al menos 1 milla","Puede rebasarlo por la derecha en cualquier momento"],"h1":"Los quitanieves lanzan nieve y se detienen a menudo. Deje mucho espacio.","h2":"En Dakota del Sur, en vías con límite de 35 mph o más, debe mantenerse al menos a 200 pies detrás de un quitanieves con sus luces rojas o ámbar encendidas.","p":"Correcto. Al menos 200 pies."},"zh":{"q":"在 South Dakota，一辆扫雪车开着红灯或琥珀色灯，在限速 35 mph 或以上的路上。你必须在它后面保持多远？","o":["20 英尺","至少 200 英尺","至少 1 英里","任何时候都可以从右边超过它"],"h1":"扫雪车会把雪抛出来，还经常停车。要留很多空间。","h2":"在 South Dakota，在限速 35 mph 或以上的路上，你必须在开着红灯或琥珀色灯的扫雪车后面保持至少 200 英尺。","p":"对。至少 200 英尺。"},"vi":{"q":"Ở South Dakota, một xe ủi tuyết đang bật đèn đỏ hoặc vàng hổ phách, trên con đường có giới hạn tốc độ 35 mph trở lên. Bạn phải giữ khoảng cách bao xa phía sau nó?","o":["20 feet","Ít nhất 200 feet","Ít nhất 1 dặm","Bạn có thể vượt bên phải bất cứ lúc nào"],"h1":"Xe ủi tuyết hất tuyết và hay dừng lại. Hãy chừa nhiều khoảng trống.","h2":"Ở South Dakota, trên đường có giới hạn tốc độ 35 mph trở lên, bạn phải giữ khoảng cách ít nhất 200 feet phía sau xe ủi tuyết đang bật đèn đỏ hoặc vàng hổ phách.","p":"Đúng. Ít nhất 200 feet."},"tl":{"q":"Sa South Dakota, nakabukas ang pula o amber na ilaw ng isang snowplow, sa daan na may limit na 35 mph o higit pa. Gaano kalayo sa likod nito ka dapat manatili?","o":["20 talampakan","Hindi bababa sa 200 talampakan","Hindi bababa sa 1 milya","Puwede mo itong lampasan sa kanan kahit kailan"],"h1":"Nagtatapon ng niyebe ang mga snowplow at madalas tumigil. Mag-iwan ng maraming espasyo.","h2":"Sa South Dakota, sa mga daan na may limit na 35 mph o higit pa, dapat kang manatili nang hindi bababa sa 200 talampakan sa likod ng snowplow na nakabukas ang pula o amber na ilaw.","p":"Tama. Hindi bababa sa 200 talampakan."},"ar":{"q":"في South Dakota، كاسحة ثلج أضواؤها الحمراء أو الكهرمانية مضاءة، على طريق حدّ السرعة فيه 35 mph أو أكثر. على أي مسافة خلفها يجب أن تبقى؟","o":["20 قدمًا","200 قدم على الأقل","1 ميل على الأقل","يمكنك تجاوزها من اليمين في أي وقت"],"h1":"كاسحات الثلج ترمي الثلج وتتوقف كثيرًا. اترك مسافة كبيرة.","h2":"في South Dakota، على الطرق التي حدّ السرعة فيها 35 mph أو أكثر، يجب أن تبقى 200 قدم على الأقل خلف كاسحة ثلج أضواؤها الحمراء أو الكهرمانية مضاءة.","p":"صحيح. 200 قدم على الأقل."},"ref":{"doc":"SD","page":67}},{"id":"sd-048","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, in which months should you be most alert for deer, because car-deer crashes are highest?","o":["June and July","January and February","March and April","October and November"],"h1":"Think of the fall season.","h2":"In South Dakota, car-deer crashes are highest in October and November, so be most alert for deer in those months, mainly at dusk and dawn.","p":"Right. October and November."},"es":{"q":"En Dakota del Sur, ¿en qué meses debe estar más atento a los venados, porque hay más choques con ellos?","o":["Junio y julio","Enero y febrero","Marzo y abril","Octubre y noviembre"],"h1":"Piense en el otoño.","h2":"En Dakota del Sur, los choques con venados son más frecuentes en octubre y noviembre, así que esté más atento en esos meses, sobre todo al amanecer y al anochecer.","p":"Correcto. Octubre y noviembre."},"zh":{"q":"在 South Dakota，哪两个月汽车撞鹿的事故最多，所以你要特别注意鹿？","o":["六月和七月","一月和二月","三月和四月","十月和十一月"],"h1":"想想秋天。","h2":"在 South Dakota，汽车撞鹿的事故在十月和十一月最多，所以这两个月要特别注意鹿，尤其是在黄昏和清晨。","p":"对。十月和十一月。"},"vi":{"q":"Ở South Dakota, vào những tháng nào bạn nên cảnh giác nhất với hươu nai, vì tai nạn xe đâm hươu nai nhiều nhất?","o":["Tháng Sáu và tháng Bảy","Tháng Một và tháng Hai","Tháng Ba và tháng Tư","Tháng Mười và tháng Mười Một"],"h1":"Hãy nghĩ đến mùa thu.","h2":"Ở South Dakota, tai nạn xe đâm hươu nai nhiều nhất vào tháng Mười và tháng Mười Một, nên hãy cảnh giác nhất với hươu nai trong những tháng này, nhất là lúc chạng vạng và rạng sáng.","p":"Đúng. Tháng Mười và tháng Mười Một."},"tl":{"q":"Sa South Dakota, sa anong mga buwan ka dapat pinakaalerto sa usa, dahil pinakamarami ang banggaan ng sasakyan at usa?","o":["Hunyo at Hulyo","Enero at Pebrero","Marso at Abril","Oktubre at Nobyembre"],"h1":"Isipin ang panahon ng taglagas.","h2":"Sa South Dakota, pinakamarami ang banggaan ng sasakyan at usa sa Oktubre at Nobyembre, kaya maging pinakaalerto sa usa sa mga buwang iyon, lalo na sa dapit-hapon at madaling-araw.","p":"Tama. Oktubre at Nobyembre."},"ar":{"q":"في South Dakota، في أي شهرين يجب أن تكون أكثر انتباهًا للغزلان، لأن حوادث اصطدام السيارات بالغزلان تكون في أعلى مستوياتها؟","o":["يونيو ويوليو","يناير وفبراير","مارس وأبريل","أكتوبر ونوفمبر"],"h1":"فكّر في فصل الخريف.","h2":"في South Dakota، تكون حوادث اصطدام السيارات بالغزلان في أعلى مستوياتها في أكتوبر ونوفمبر، لذلك كن أكثر انتباهًا للغزلان في هذين الشهرين، وخاصة عند الغروب والفجر.","p":"صحيح. أكتوبر ونوفمبر."},"ref":{"doc":"SD","page":50}},{"id":"sd-049","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, during which hours may a motorcycle instruction permit holder ride?","o":["6 a.m. to 8 p.m.","6 a.m. to 10 p.m.","Any time of day or night","Only after dark"],"h1":"Motorcycle permit riding ends earlier than car permit driving.","h2":"In South Dakota, a motorcycle instruction permit holder may ride only from 6 a.m. to 8 p.m., with a licensed rider on another motorcycle.","p":"Right. 6 a.m. to 8 p.m."},"es":{"q":"En Dakota del Sur, ¿en qué horario puede manejar quien tiene un permiso de aprendizaje de motocicleta?","o":["De 6 a.m. a 8 p.m.","De 6 a.m. a 10 p.m.","A cualquier hora del día o de la noche","Solo cuando está oscuro"],"h1":"El horario del permiso de motocicleta termina más temprano que el del permiso de auto.","h2":"En Dakota del Sur, quien tiene un permiso de aprendizaje de motocicleta solo puede manejar de 6 a.m. a 8 p.m., acompañado por un motociclista con licencia en otra motocicleta.","p":"Correcto. De 6 a.m. a 8 p.m."},"zh":{"q":"在 South Dakota，持摩托车学习驾照的人可以在哪些时间骑车？","o":["早上 6 点到晚上 8 点","早上 6 点到晚上 10 点","白天晚上任何时间","只能在天黑以后"],"h1":"摩托车学习驾照的骑车时间比汽车学习驾照结束得早。","h2":"在 South Dakota，持摩托车学习驾照的人只能在早上 6 点到晚上 8 点之间骑车，而且要有一位有驾照的骑手骑另一辆摩托车陪同。","p":"对。早上 6 点到晚上 8 点。"},"vi":{"q":"Ở South Dakota, người có giấy phép tập lái xe mô tô được chạy xe vào những giờ nào?","o":["6 giờ sáng đến 8 giờ tối","6 giờ sáng đến 10 giờ tối","Bất cứ giờ nào, ngày hay đêm","Chỉ sau khi trời tối"],"h1":"Giờ chạy xe với giấy phép tập lái mô tô kết thúc sớm hơn giấy phép tập lái ô tô.","h2":"Ở South Dakota, người có giấy phép tập lái xe mô tô chỉ được chạy xe từ 6 giờ sáng đến 8 giờ tối, với một người có bằng lái đi trên một chiếc mô tô khác.","p":"Đúng. 6 giờ sáng đến 8 giờ tối."},"tl":{"q":"Sa South Dakota, sa anong mga oras puwedeng magmaneho ng motorsiklo ang may motorcycle instruction permit?","o":["6 a.m. hanggang 8 p.m.","6 a.m. hanggang 10 p.m.","Kahit anong oras, araw man o gabi","Pagkadilim lang"],"h1":"Mas maagang natatapos ang pagmamaneho sa motorcycle permit kaysa sa car permit.","h2":"Sa South Dakota, ang may motorcycle instruction permit ay puwedeng magmaneho lang mula 6 a.m. hanggang 8 p.m., kasama ang isang lisensyadong rider sa ibang motorsiklo.","p":"Tama. 6 a.m. hanggang 8 p.m."},"ar":{"q":"في South Dakota، في أي ساعات يمكن لحامل تصريح تعلّم الدراجة النارية أن يقودها؟","o":["من 6 صباحًا إلى 8 مساءً","من 6 صباحًا إلى 10 مساءً","في أي وقت ليلًا أو نهارًا","بعد حلول الظلام فقط"],"h1":"تنتهي قيادة الدراجة النارية بالتصريح أبكر من قيادة السيارة بالتصريح.","h2":"في South Dakota، يمكن لحامل تصريح تعلّم الدراجة النارية أن يقود فقط من 6 صباحًا إلى 8 مساءً، مع سائق يحمل رخصة على دراجة نارية أخرى.","p":"صحيح. من 6 صباحًا إلى 8 مساءً."},"ref":{"doc":"SD","page":9}},{"id":"sd-050","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, a funeral procession goes through an intersection. Which vehicle in it must obey the traffic signs and signals?","o":["Every vehicle in the procession","Only the last vehicle","Only the first vehicle","None of the vehicles"],"h1":"The others follow the one in front, with headlights on.","h2":"In South Dakota, only the first vehicle in a funeral procession must obey traffic signs and signals; the others keep their headlights on, and you must not cut into the line.","p":"Right. Only the first vehicle."},"es":{"q":"En Dakota del Sur, un cortejo fúnebre pasa por una intersección. ¿Qué vehículo del cortejo debe obedecer las señales y los semáforos?","o":["Todos los vehículos del cortejo","Solo el último vehículo","Solo el primer vehículo","Ninguno de los vehículos"],"h1":"Los demás siguen al de adelante, con los faros encendidos.","h2":"En Dakota del Sur, solo el primer vehículo de un cortejo fúnebre debe obedecer las señales y los semáforos; los demás llevan los faros encendidos, y usted no debe meterse en la fila.","p":"Correcto. Solo el primer vehículo."},"zh":{"q":"在 South Dakota，一支送葬车队经过路口。车队中哪辆车必须遵守交通标志和信号？","o":["车队中的每一辆车","只有最后一辆车","只有第一辆车","没有一辆车需要"],"h1":"其他车开着大灯，跟着前面的车。","h2":"在 South Dakota，送葬车队中只有第一辆车必须遵守交通标志和信号；其他车要开着大灯，你也不可以插进车队。","p":"对。只有第一辆车。"},"vi":{"q":"Ở South Dakota, một đoàn xe tang đi qua giao lộ. Xe nào trong đoàn phải tuân theo biển báo và đèn giao thông?","o":["Mọi xe trong đoàn","Chỉ xe cuối cùng","Chỉ xe đầu tiên","Không xe nào cả"],"h1":"Các xe khác đi theo xe phía trước, có bật đèn pha.","h2":"Ở South Dakota, chỉ xe đầu tiên trong đoàn xe tang phải tuân theo biển báo và đèn giao thông; các xe khác bật đèn pha, và bạn không được chen vào đoàn.","p":"Đúng. Chỉ xe đầu tiên."},"tl":{"q":"Sa South Dakota, dumadaan sa intersection ang isang funeral procession (prusisyon ng libing). Aling sasakyan dito ang dapat sumunod sa mga traffic sign at signal?","o":["Bawat sasakyan sa prusisyon","Ang huling sasakyan lang","Ang unang sasakyan lang","Wala sa mga sasakyan"],"h1":"Sumusunod ang iba sa nasa harap, nakabukas ang headlights.","h2":"Sa South Dakota, ang unang sasakyan lang sa funeral procession ang dapat sumunod sa mga traffic sign at signal; nakabukas ang headlights ng iba, at hindi ka dapat sumingit sa hanay.","p":"Tama. Ang unang sasakyan lang."},"ar":{"q":"في South Dakota، يمرّ موكب جنازة عبر تقاطع. أي مركبة فيه يجب أن تلتزم بعلامات المرور وإشاراتها؟","o":["كل مركبة في الموكب","المركبة الأخيرة فقط","المركبة الأولى فقط","لا مركبة منها"],"h1":"الباقون يتبعون المركبة التي أمامهم، وأضواؤهم الأمامية مضاءة.","h2":"في South Dakota، المركبة الأولى فقط في موكب الجنازة يجب أن تلتزم بعلامات المرور وإشاراتها؛ والباقون يُبقون أضواءهم الأمامية مضاءة، ويجب ألّا تدخل بين سيارات الموكب.","p":"صحيح. المركبة الأولى فقط."},"ref":{"doc":"SD","page":31}},{"id":"sd-051","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you just moved here and hold a commercial driver license (CDL) from another state. How soon must you apply for a South Dakota license?","o":["Within 30 days","Within 60 days","Within 90 days","Within 1 year"],"h1":"It is a shorter deadline than for a regular license.","h2":"A CDL holder who moves to South Dakota must apply for a South Dakota license within 30 days of becoming a resident.","p":"Right. CDL holders have 30 days."},"es":{"q":"En Dakota del Sur, usted acaba de mudarse aquí y tiene una licencia de conducir comercial (CDL) de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Dakota del Sur?","o":["En 30 días","En 60 días","En 90 días","En 1 año"],"h1":"Es un plazo más corto que para una licencia normal.","h2":"Quien tiene una CDL y se muda a Dakota del Sur debe solicitar una licencia de Dakota del Sur dentro de los 30 días de hacerse residente.","p":"Correcto. Quienes tienen CDL tienen 30 días."},"ref":{"doc":"SD","page":5}},{"id":"sd-052","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a visitor from another state has a valid license from home. From what age may they drive here on that license?","o":["14 years old","16 years old","18 years old","21 years old"],"h1":"It is the age when a full license is possible in South Dakota.","h2":"A non-resident who is at least 16 years old may drive in South Dakota on a valid license from their home state.","p":"Right. Visitors 16 and older may use their home-state license."},"es":{"q":"En Dakota del Sur, una persona de visita de otro estado tiene una licencia válida de su estado. ¿Desde qué edad puede manejar aquí con esa licencia?","o":["14 años","16 años","18 años","21 años"],"h1":"Es la edad en que se puede tener una licencia completa en Dakota del Sur.","h2":"Una persona no residente de por lo menos 16 años puede manejar en Dakota del Sur con una licencia válida de su estado.","p":"Correcto. Los visitantes de 16 años o más pueden usar la licencia de su estado."},"ref":{"doc":"SD","page":5}},{"id":"sd-053","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, an applicant is 17. How often is a parent's or guardian's consent needed?","o":["Only for the road test","Only for the first permit","For every application","Never, at 17"],"h1":"Think about each time a form is filled out.","h2":"In South Dakota, an applicant under 18 needs a parent's or guardian's consent on every application.","p":"Right. Every application under 18 needs consent."},"es":{"q":"En Dakota del Sur, una persona que solicita tiene 17 años. ¿Cada cuánto se necesita el permiso de un padre o tutor?","o":["Solo para el examen de manejo","Solo para el primer permiso","En cada solicitud","Nunca, a los 17"],"h1":"Piense en cada vez que se llena un formulario.","h2":"En Dakota del Sur, quien solicita y tiene menos de 18 años necesita el permiso de un padre o tutor en cada solicitud.","p":"Correcto. Cada solicitud de un menor de 18 necesita permiso."},"ref":{"doc":"SD","page":5}},{"id":"sd-054","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, which of these can stop you from getting a driver license?","o":["Having a license from another state","An unpaid parking ticket from a store lot","Not owning a car","Unpaid fines for moving traffic violations"],"h1":"It is about money owed for driving offenses.","h2":"South Dakota will not issue a driver license to someone who has unpaid fines for moving traffic violations.","p":"Right. Unpaid moving-violation fines block a license."},"es":{"q":"En Dakota del Sur, ¿cuál de estas cosas puede impedir que usted obtenga una licencia de conducir?","o":["Tener licencia de otro estado","Una multa sin pagar del estacionamiento de una tienda","No tener carro","Multas sin pagar por infracciones de tránsito en movimiento"],"h1":"Se trata de dinero que se debe por faltas al manejar.","h2":"Dakota del Sur no da licencia de conducir a quien tiene multas sin pagar por infracciones de tránsito en movimiento.","p":"Correcto. Las multas sin pagar por infracciones en movimiento impiden la licencia."},"ref":{"doc":"SD","page":5}},{"id":"sd-055","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you bring photocopies of your documents to the exam station. Will they be accepted?","o":["No, photocopies are not accepted","Yes, if they are clear","Yes, if a parent signs them","Only for renewals"],"h1":"The manual is strict about copies.","h2":"South Dakota exam stations do not accept photocopies of required documents; you must bring the originals or certified copies.","p":"Right. Photocopies are not accepted."},"es":{"q":"En Dakota del Sur, usted lleva fotocopias de sus documentos a la oficina de exámenes. ¿Las aceptarán?","o":["No, no se aceptan fotocopias","Sí, si se ven claras","Sí, si las firma un padre","Solo para renovaciones"],"h1":"El manual es estricto con las copias.","h2":"Las oficinas de exámenes de Dakota del Sur no aceptan fotocopias de los documentos requeridos; debe llevar los originales o copias certificadas.","p":"Correcto. No se aceptan fotocopias."},"ref":{"doc":"SD","page":5}},{"id":"sd-056","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how many documents proving your physical address must you bring, and how old may they be?","o":["One, less than five years old","Two, each less than one year old","Three, of any age","Two, less than ten years old"],"h1":"More than one, and they must be fairly recent.","h2":"South Dakota asks for two documents proving your physical address in the state, each less than one year old.","p":"Right. Two address documents, under one year old."},"es":{"q":"En Dakota del Sur, ¿cuántos documentos que prueban su domicilio debe llevar, y qué antigüedad pueden tener?","o":["Uno, de menos de cinco años","Dos, de menos de un año cada uno","Tres, de cualquier fecha","Dos, de menos de diez años"],"h1":"Más de uno, y deben ser bastante recientes.","h2":"Dakota del Sur pide dos documentos que prueben su domicilio en el estado, cada uno de menos de un año.","p":"Correcto. Dos documentos de domicilio, de menos de un año."},"ref":{"doc":"SD","page":5}},{"id":"sd-057","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, you want to prove your date of birth with a birth certificate. Which kind is NOT accepted?","o":["A certified copy with the issuing office's stamp","A certified state copy with a raised seal","A hospital-issued certificate","A Consular Report of Birth Abroad"],"h1":"Think about who issued it.","h2":"South Dakota does not accept a hospital-issued birth certificate; it must be a certified copy from the state with a stamp or raised seal.","p":"Right. A hospital certificate is not accepted."},"es":{"q":"En Dakota del Sur, usted quiere probar su fecha de nacimiento con un acta de nacimiento. ¿Cuál NO se acepta?","o":["Una copia certificada con el sello de la oficina que la emite","Una copia certificada del estado con sello en relieve","Un certificado dado por el hospital","Un Informe Consular de Nacimiento en el Extranjero"],"h1":"Piense en quién lo emitió.","h2":"Dakota del Sur no acepta un certificado de nacimiento dado por el hospital; debe ser una copia certificada del estado con sello o sello en relieve.","p":"Correcto. El certificado del hospital no se acepta."},"ref":{"doc":"SD","page":6}},{"id":"sd-058","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, which document may you use to prove your Social Security number?","o":["A school yearbook","A library card","A utility bill","A W-2 form"],"h1":"It is a tax or pay paper that shows your full number.","h2":"To prove your Social Security number in South Dakota, you may bring a Social Security card, a W-2, a 1099 form, or a paystub with your full number.","p":"Right. A W-2 shows your Social Security number."},"es":{"q":"En Dakota del Sur, ¿qué documento puede usar para probar su número de Seguro Social?","o":["Un anuario escolar","Una tarjeta de la biblioteca","Una factura de luz","Un formulario W-2"],"h1":"Es un papel de impuestos o de pago que muestra su número completo.","h2":"Para probar su número de Seguro Social en Dakota del Sur, puede llevar la tarjeta de Seguro Social, un W-2, un formulario 1099 o un talón de pago con su número completo.","p":"Correcto. El W-2 muestra su número de Seguro Social."},"ref":{"doc":"SD","page":6}},{"id":"sd-059","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, a 15-year-old has no bills in their own name. How can they prove their address?","o":["With the accompanying parent's address documents","They cannot get a permit until 18","With a note from a friend","With a phone photo of the house"],"h1":"A family member can help.","h2":"In South Dakota, a minor may use a parent's proof of address, as long as the parent who comes along is named on the documents.","p":"Right. A parent's address documents work for a minor."},"es":{"q":"En Dakota del Sur, una persona de 15 años no tiene facturas a su nombre. ¿Cómo puede probar su domicilio?","o":["Con los documentos de domicilio del padre o madre que la acompaña","No puede sacar permiso hasta los 18","Con una nota de un amigo","Con una foto de la casa en el teléfono"],"h1":"Un familiar puede ayudar.","h2":"En Dakota del Sur, un menor puede usar la prueba de domicilio de un padre, siempre que el padre que lo acompaña aparezca en los documentos.","p":"Correcto. Los documentos de domicilio del padre sirven para un menor."},"ref":{"doc":"SD","page":6}},{"id":"sd-060","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a full-time traveler uses a mail forwarding address. What must they show about staying in the state?","o":["A lease for at least six months","A receipt for one night's stay in South Dakota within the last year","A South Dakota job letter","Nothing extra"],"h1":"It is proof of a short stay, like at a hotel or campground.","h2":"A full-time traveler in South Dakota must show a receipt from a South Dakota hotel, campground or RV park for one night's stay within the last year, plus a residency affidavit.","p":"Right. One night's stay within the past year must be shown."},"es":{"q":"En Dakota del Sur, una persona que viaja todo el tiempo usa una dirección de reenvío de correo. ¿Qué debe mostrar sobre su estadía en el estado?","o":["Un contrato de renta de por lo menos seis meses","Un recibo de una noche de estadía en Dakota del Sur en el último año","Una carta de trabajo en Dakota del Sur","Nada más"],"h1":"Es prueba de una estadía corta, como en un hotel o campamento.","h2":"Quien viaja todo el tiempo debe mostrar un recibo de un hotel, campamento o parque de casas rodantes de Dakota del Sur por una noche de estadía en el último año, además de una declaración de residencia.","p":"Correcto. Debe mostrar una noche de estadía en el último año."},"ref":{"doc":"SD","page":7}},{"id":"sd-061","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, a veteran wants the word \"Veteran\" on their license. Which document shows honorable discharge?","o":["A vehicle title","A high school diploma","A DD-214 form","A voter card"],"h1":"It is the military release paper.","h2":"To add the Veteran mark to a South Dakota license, an honorably discharged veteran can show a DD-214 form, among other accepted military papers.","p":"Right. A DD-214 shows honorable discharge."},"es":{"q":"En Dakota del Sur, un veterano quiere la palabra \"Veteran\" en su licencia. ¿Qué documento muestra la baja honorable?","o":["El título de un vehículo","Un diploma de secundaria","Un formulario DD-214","Una tarjeta de votante"],"h1":"Es el papel de baja del servicio militar.","h2":"Para agregar la marca de veterano a una licencia de Dakota del Sur, un veterano con baja honorable puede mostrar un formulario DD-214, entre otros papeles militares aceptados.","p":"Correcto. El DD-214 muestra la baja honorable."},"ref":{"doc":"SD","page":7}},{"id":"sd-062","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, a man applying for a license is 20. What must his application say about the Selective Service?","o":["That he will register at 26","Nothing, it is optional","That he has served in the military","That he is registered, or lets the state send his information to register"],"h1":"It applies to men aged 18 to 25.","h2":"A male South Dakota applicant aged 18 to 25 must state that he is registered with the Selective Service or allow the Department of Public Safety to send his information to register.","p":"Right. He must be registered or authorize the state to register him."},"es":{"q":"En Dakota del Sur, un hombre de 20 años solicita una licencia. ¿Qué debe decir su solicitud sobre el Servicio Selectivo?","o":["Que se inscribirá a los 26","Nada, es opcional","Que sirvió en el ejército","Que está inscrito, o que permite al estado enviar sus datos para inscribirlo"],"h1":"Se aplica a hombres de 18 a 25 años.","h2":"Un hombre de 18 a 25 años que solicita en Dakota del Sur debe declarar que está inscrito en el Servicio Selectivo o permitir que el Departamento de Seguridad Pública envíe sus datos para inscribirlo.","p":"Correcto. Debe estar inscrito o autorizar al estado a inscribirlo."},"ref":{"doc":"SD","page":7}},{"id":"sd-063","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, how much does a regular driver license or instruction permit cost, according to the manual?","o":["$38","$20","$43","$50"],"h1":"It is the same fee as an ID card.","h2":"The South Dakota manual lists $38 for a regular driver license or instruction permit, and the same for an ID card.","p":"Right. The fee is $38."},"es":{"q":"En Dakota del Sur, ¿cuánto cuesta una licencia de conducir normal o un permiso de aprendizaje, según el manual?","o":["$38","$20","$43","$50"],"h1":"Es el mismo costo que una tarjeta de identificación.","h2":"El manual de Dakota del Sur indica $38 por una licencia de conducir normal o un permiso de aprendizaje, y lo mismo por una tarjeta de identificación.","p":"Correcto. El costo es $38."},"ref":{"doc":"SD","page":7}},{"id":"sd-064","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how much does it cost to change the address or name on your license, or to replace it?","o":["$38","$20","$10","$5"],"h1":"It is less than a new license.","h2":"The South Dakota manual lists $20 for an address change, a name change, or a replacement license or ID card.","p":"Right. Changes and replacements cost $20."},"es":{"q":"En Dakota del Sur, ¿cuánto cuesta cambiar la dirección o el nombre en su licencia, o reemplazarla?","o":["$38","$20","$10","$5"],"h1":"Es menos que una licencia nueva.","h2":"El manual de Dakota del Sur indica $20 por un cambio de dirección, un cambio de nombre o el reemplazo de la licencia o tarjeta de identificación.","p":"Correcto. Los cambios y reemplazos cuestan $20."},"ref":{"doc":"SD","page":7}},{"id":"sd-065","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how many tries at a test does one paid fee cover?","o":["Five tries within a year","One try only","Three tries within 6 months","Unlimited tries"],"h1":"There is a limit on tries and on time.","h2":"In South Dakota, one fee covers three attempts to pass a test within 6 months; after that, you pay again.","p":"Right. One fee covers three tries in 6 months."},"es":{"q":"En Dakota del Sur, ¿cuántos intentos de examen cubre un pago?","o":["Cinco intentos en un año","Solo un intento","Tres intentos en 6 meses","Intentos ilimitados"],"h1":"Hay un límite de intentos y de tiempo.","h2":"En Dakota del Sur, un pago cubre tres intentos para aprobar un examen en 6 meses; después debe pagar otra vez.","p":"Correcto. Un pago cubre tres intentos en 6 meses."},"ref":{"doc":"SD","page":7}},{"id":"sd-066","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, a person owes child support. From what amount owed can they be refused a license?","o":["Any amount","$100 or more","$5,000 or more","$1,000 or more"],"h1":"It is a four-digit number.","h2":"South Dakota will not issue a license to a person who owes $1,000 or more in child support, though they may qualify for one 6-month temporary license.","p":"Right. $1,000 or more in child support arrears."},"es":{"q":"En Dakota del Sur, una persona debe manutención de hijos. ¿Desde qué cantidad pueden negarle la licencia?","o":["Cualquier cantidad","$100 o más","$5,000 o más","$1,000 o más"],"h1":"Es un número de cuatro cifras.","h2":"Dakota del Sur no da licencia a quien debe $1,000 o más de manutención de hijos, aunque puede recibir una licencia temporal de 6 meses.","p":"Correcto. $1,000 o más de manutención atrasada."},"ref":{"doc":"SD","page":7}},{"id":"sd-067","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, a teen took driver education to shorten the permit period. What score was needed on both the written and driving parts?","o":["80 percent or better","70 percent or better","60 percent or better","100 percent"],"h1":"It is the same as the passing score for the knowledge test.","h2":"To shorten the permit period, a South Dakota teen must pass an approved driver education course with 80 percent or better on both the written and driving parts.","p":"Right. Driver education needs 80 percent on both parts."},"es":{"q":"En Dakota del Sur, un adolescente tomó un curso de manejo para acortar el tiempo del permiso. ¿Qué calificación necesitaba en la parte escrita y en la de manejo?","o":["80 por ciento o más","70 por ciento o más","60 por ciento o más","100 por ciento"],"h1":"Es igual a la calificación para aprobar el examen de conocimientos.","h2":"Para acortar el tiempo del permiso, un adolescente de Dakota del Sur debe aprobar un curso de manejo aprobado con 80 por ciento o más en la parte escrita y en la de manejo.","p":"Correcto. El curso necesita 80 por ciento en ambas partes."},"ref":{"doc":"SD","page":8}},{"id":"sd-068","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, an adult over 18 has an instruction permit. What must they pass before getting an operator's license?","o":["A second knowledge test","A drive test","Driver education","Nothing more"],"h1":"It shows you can handle the car on the road.","h2":"An adult with a South Dakota instruction permit must pass a drive test before upgrading to an operator's license.","p":"Right. Adults must pass a drive test."},"es":{"q":"En Dakota del Sur, un adulto mayor de 18 tiene permiso de aprendizaje. ¿Qué debe aprobar antes de obtener una licencia de operador?","o":["Un segundo examen de conocimientos","Un examen de manejo","Un curso de manejo","Nada más"],"h1":"Demuestra que puede manejar el carro en la calle.","h2":"Un adulto con permiso de aprendizaje de Dakota del Sur debe aprobar un examen de manejo antes de pasar a una licencia de operador.","p":"Correcto. Los adultos deben aprobar un examen de manejo."},"ref":{"doc":"SD","page":8}},{"id":"sd-069","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the shortest time a teen must drive on a restricted minor's permit?","o":["1 year","3 months","6 months","30 days"],"h1":"It is half a year.","h2":"A South Dakota teen must drive on a restricted minor's permit for at least 6 months.","p":"Right. At least 6 months on the restricted permit."},"es":{"q":"En Dakota del Sur, ¿cuál es el tiempo mínimo que un adolescente debe manejar con un permiso restringido para menores?","o":["1 año","3 meses","6 meses","30 días"],"h1":"Es medio año.","h2":"Un adolescente de Dakota del Sur debe manejar con el permiso restringido para menores por lo menos 6 meses.","p":"Correcto. Por lo menos 6 meses con el permiso restringido."},"ref":{"doc":"SD","page":8}},{"id":"sd-070","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, what happens to a restricted minor's permit when the holder turns 18?","o":["It becomes an instruction permit","It expires and you start over","You must retake all tests","It changes into an operator's license automatically"],"h1":"The limits for minors end.","h2":"In South Dakota, a restricted minor's permit automatically converts to an operator's license when the holder turns 18.","p":"Right. At 18 it converts to an operator's license."},"es":{"q":"En Dakota del Sur, ¿qué pasa con el permiso restringido para menores cuando la persona cumple 18 años?","o":["Se vuelve permiso de aprendizaje","Vence y hay que empezar de nuevo","Debe repetir todos los exámenes","Se convierte en licencia de operador automáticamente"],"h1":"Terminan los límites para menores.","h2":"En Dakota del Sur, el permiso restringido para menores se convierte automáticamente en licencia de operador cuando la persona cumple 18 años.","p":"Correcto. A los 18 se convierte en licencia de operador."},"ref":{"doc":"SD","page":8}},{"id":"sd-071","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you are 15 and drive on a restricted minor's permit. A friend texts you while you drive. What does the law allow?","o":["You may not use any wireless device while driving","You may read but not reply","You may reply at red lights","You may use it hands-free"],"h1":"The rule for restricted permit holders covers every type of device.","h2":"A South Dakota restricted minor's permit holder may not use any wireless communication device, including a cell phone, while driving.","p":"Right. No wireless device at all while driving on this permit."},"es":{"q":"En Dakota del Sur, usted tiene 15 años y maneja con permiso restringido para menores. Un amigo le manda un mensaje mientras maneja. ¿Qué permite la ley?","o":["No puede usar ningún aparato inalámbrico mientras maneja","Puede leer pero no contestar","Puede contestar en los semáforos en rojo","Puede usarlo con manos libres"],"h1":"La regla para el permiso restringido cubre todo tipo de aparato.","h2":"Quien tiene permiso restringido para menores en Dakota del Sur no puede usar ningún aparato de comunicación inalámbrica, incluido el celular, mientras maneja.","p":"Correcto. Ningún aparato inalámbrico mientras maneja con este permiso."},"ref":{"doc":"SD","page":8}},{"id":"sd-072","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how long is a motorcycle instruction permit valid?","o":["Five years","One year","Six months","Two years"],"h1":"It is much shorter than a car instruction permit.","h2":"A South Dakota motorcycle instruction permit is valid for one year, or until your lawful presence documents expire if that is sooner.","p":"Right. A motorcycle instruction permit lasts one year."},"es":{"q":"En Dakota del Sur, ¿cuánto tiempo es válido un permiso de aprendizaje de motocicleta?","o":["Cinco años","Un año","Seis meses","Dos años"],"h1":"Es mucho más corto que el permiso de aprendizaje para carro.","h2":"En Dakota del Sur, el permiso de aprendizaje de motocicleta es válido por un año, o hasta que venzan sus documentos de estancia legal si eso ocurre antes.","p":"Correcto. El permiso de aprendizaje de motocicleta dura un año."},"ref":{"doc":"SD","page":9}},{"id":"sd-073","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, may a motorcycle instruction permit holder carry a passenger?","o":["Yes, during the day","Yes, if the passenger is an adult","No, never","Yes, if both wear helmets"],"h1":"The permit is for learning to ride alone.","h2":"A South Dakota motorcycle instruction permit holder may not carry another person on the motorcycle.","p":"Right. No passengers on a motorcycle instruction permit."},"es":{"q":"En Dakota del Sur, ¿puede una persona con permiso de aprendizaje de motocicleta llevar un pasajero?","o":["Sí, de día","Sí, si el pasajero es adulto","No, nunca","Sí, si ambos usan casco"],"h1":"El permiso es para aprender a manejar solo.","h2":"En Dakota del Sur, quien tiene permiso de aprendizaje de motocicleta no puede llevar a otra persona en la moto.","p":"Correcto. Sin pasajeros con permiso de aprendizaje de motocicleta."},"ref":{"doc":"SD","page":9}},{"id":"sd-074","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, who must ride with a motorcycle instruction permit holder?","o":["No one","Any adult riding on the back","A parent in a car behind","A licensed motorcyclist 18 or older with 1+ year of experience, on another motorcycle"],"h1":"The supervisor rides separately.","h2":"A South Dakota motorcycle instruction permit holder must be accompanied by a licensed motorcyclist at least 18 years old with at least one year of experience, riding another motorcycle.","p":"Right. The supervisor rides their own motorcycle alongside."},"es":{"q":"En Dakota del Sur, ¿quién debe acompañar a una persona con permiso de aprendizaje de motocicleta?","o":["Nadie","Cualquier adulto sentado atrás","Un padre en un carro detrás","Un motociclista con licencia, de 18 años o más y con 1 año o más de experiencia, en otra moto"],"h1":"El supervisor va por separado.","h2":"En Dakota del Sur, quien tiene permiso de aprendizaje de motocicleta debe ir acompañado por un motociclista con licencia de por lo menos 18 años y un año de experiencia, que maneje otra moto.","p":"Correcto. El supervisor maneja su propia moto al lado."},"ref":{"doc":"SD","page":9}},{"id":"sd-075","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what do you need to ride a moped on public roads?","o":["A valid operator's license","No license at all","Only a helmet","An ID card"],"h1":"A moped is not license-free here.","h2":"To ride a moped in South Dakota, you must have a valid operator's license.","p":"Right. Moped riders need a valid operator's license."},"es":{"q":"En Dakota del Sur, ¿qué necesita para manejar un ciclomotor (moped) en vías públicas?","o":["Una licencia de operador válida","Ninguna licencia","Solo un casco","Una tarjeta de identificación"],"h1":"Aquí el ciclomotor no está libre de licencia.","h2":"Para manejar un ciclomotor en Dakota del Sur, debe tener una licencia de operador válida.","p":"Correcto. Quien maneja un ciclomotor necesita licencia de operador válida."},"ref":{"doc":"SD","page":9}},{"id":"sd-076","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, what is the minimum age for a state ID card (not a driver license)?","o":["14 years old","There is no age requirement","16 years old","18 years old"],"h1":"Even a baby can have one.","h2":"A South Dakota identification card has no age requirement; anyone with the required documents can get one.","p":"Right. There is no minimum age for an ID card."},"es":{"q":"En Dakota del Sur, ¿cuál es la edad mínima para una tarjeta de identificación del estado (no licencia de conducir)?","o":["14 años","No hay edad mínima","16 años","18 años"],"h1":"Hasta un bebé puede tener una.","h2":"La tarjeta de identificación de Dakota del Sur no tiene edad mínima; cualquier persona con los documentos requeridos puede obtenerla.","p":"Correcto. No hay edad mínima para la tarjeta de identificación."},"ref":{"doc":"SD","page":9}},{"id":"sd-077","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, a license is issued to someone who is 18. When does it expire?","o":["Five years after it is issued","On their 21st birthday","30 days after their 21st birthday","On their 25th birthday"],"h1":"Licenses for people under 21 end soon after a certain birthday.","h2":"A South Dakota license issued to someone under 21 with five years or less until age 21 expires 30 days after the 21st birthday.","p":"Right. It expires 30 days after the 21st birthday."},"es":{"q":"En Dakota del Sur, se le da una licencia a una persona de 18 años. ¿Cuándo vence?","o":["Cinco años después de emitida","El día que cumple 21 años","30 días después de cumplir 21 años","Al cumplir 25 años"],"h1":"Las licencias de menores de 21 terminan poco después de cierto cumpleaños.","h2":"En Dakota del Sur, una licencia dada a alguien menor de 21, a quien le faltan cinco años o menos para cumplir 21, vence 30 días después de cumplir 21 años.","p":"Correcto. Vence 30 días después de cumplir 21."},"ref":{"doc":"SD","page":9}},{"id":"sd-078","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, you lose your license and get a duplicate. What expiration date will the duplicate have?","o":["No expiration date","Five years from today","One year from today","The same date as the original"],"h1":"A duplicate is a copy, not a renewal.","h2":"A South Dakota duplicate license keeps the original license's expiration date.","p":"Right. A duplicate keeps the original expiration date."},"es":{"q":"En Dakota del Sur, usted pierde su licencia y saca un duplicado. ¿Qué fecha de vencimiento tendrá el duplicado?","o":["Ninguna fecha de vencimiento","Cinco años desde hoy","Un año desde hoy","La misma que la original"],"h1":"Un duplicado es una copia, no una renovación.","h2":"En Dakota del Sur, el duplicado de la licencia mantiene la fecha de vencimiento de la licencia original.","p":"Correcto. El duplicado mantiene la fecha de vencimiento original."},"ref":{"doc":"SD","page":9}},{"id":"sd-079","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you move here with a valid non-commercial license from another state. Which tests must you take to transfer it?","o":["None, unless you have a hazardous materials endorsement","The knowledge and driving tests","Only the driving test","Only the knowledge test"],"h1":"A valid out-of-state license usually carries over.","h2":"In South Dakota, no testing is required to transfer a valid out-of-state license unless you have a hazardous materials endorsement.","p":"Right. No tests, unless you carry a hazmat endorsement."},"es":{"q":"En Dakota del Sur, usted se muda aquí con una licencia no comercial válida de otro estado. ¿Qué exámenes debe tomar para transferirla?","o":["Ninguno, a menos que tenga un endoso de materiales peligrosos","El de conocimientos y el de manejo","Solo el de manejo","Solo el de conocimientos"],"h1":"Una licencia válida de otro estado por lo general se pasa.","h2":"En Dakota del Sur no se requiere examen para transferir una licencia válida de otro estado, a menos que tenga un endoso de materiales peligrosos.","p":"Correcto. Ningún examen, salvo que tenga endoso de materiales peligrosos."},"ref":{"doc":"SD","page":10}},{"id":"sd-080","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, who may ride along during your on-the-road driving test?","o":["A parent","No passengers or pets, only the examiner","Any licensed adult","Your younger brother or sister"],"h1":"The examiner wants no distractions.","h2":"Pets and passengers are not allowed in the car during the South Dakota on-the-road skill test; only you and the examiner.","p":"Right. No passengers or pets on the drive test."},"es":{"q":"En Dakota del Sur, ¿quién puede ir con usted durante el examen de manejo en la calle?","o":["Uno de sus padres","Ningún pasajero ni mascota, solo el examinador","Cualquier adulto con licencia","Su hermano menor"],"h1":"El examinador no quiere distracciones.","h2":"En Dakota del Sur no se permiten mascotas ni pasajeros en el carro durante el examen de manejo; solo usted y el examinador.","p":"Correcto. Sin pasajeros ni mascotas en el examen de manejo."},"ref":{"doc":"SD","page":10}},{"id":"sd-081","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, whose vehicle is used for the on-the-road driving test?","o":["The examiner's car","The state provides one","You must bring your own safe vehicle","A driving school car only"],"h1":"The state does not lend cars.","h2":"South Dakota license applicants must supply their own safe vehicle for the on-the-road skill test.","p":"Right. You bring your own safe vehicle."},"es":{"q":"En Dakota del Sur, ¿qué vehículo se usa para el examen de manejo en la calle?","o":["El carro del examinador","El estado da uno","Usted debe llevar su propio vehículo seguro","Solo un carro de escuela de manejo"],"h1":"El estado no presta carros.","h2":"En Dakota del Sur, quien solicita la licencia debe llevar su propio vehículo seguro para el examen de manejo.","p":"Correcto. Usted lleva su propio vehículo seguro."},"ref":{"doc":"SD","page":10}},{"id":"sd-082","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, a person is caught cheating on the knowledge test. How long must they wait to test again?","o":["Six months","Until the next working day","24 hours","At least two weeks"],"h1":"It is longer than the wait after a normal fail.","h2":"In South Dakota, someone caught cheating on a test must wait at least two weeks before testing again.","p":"Right. Cheating means a wait of at least two weeks."},"es":{"q":"En Dakota del Sur, una persona es sorprendida haciendo trampa en el examen de conocimientos. ¿Cuánto debe esperar para volver a tomarlo?","o":["Seis meses","Hasta el siguiente día hábil","24 horas","Por lo menos dos semanas"],"h1":"Es más tiempo que la espera después de reprobar normalmente.","h2":"En Dakota del Sur, quien es sorprendido haciendo trampa en un examen debe esperar por lo menos dos semanas para volver a tomarlo.","p":"Correcto. Hacer trampa significa esperar por lo menos dos semanas."},"ref":{"doc":"SD","page":10}},{"id":"sd-083","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, you do not pass the vision test at the exam station. What do you need to continue?","o":["A statement from an optometrist or ophthalmologist","A note from your parent","A second try the same day","Nothing, the vision test is optional"],"h1":"An eye professional must sign off.","h2":"If you fail the South Dakota vision test, you must bring a statement from an optometrist or ophthalmologist saying you can see well enough to drive safely.","p":"Right. An eye doctor's statement is needed."},"es":{"q":"En Dakota del Sur, usted no aprueba el examen de la vista en la oficina. ¿Qué necesita para continuar?","o":["Una constancia de un optometrista u oftalmólogo","Una nota de su padre o madre","Un segundo intento el mismo día","Nada, el examen de la vista es opcional"],"h1":"Un profesional de los ojos debe aprobarlo.","h2":"Si no aprueba el examen de la vista en Dakota del Sur, debe llevar una constancia de un optometrista u oftalmólogo que diga que ve lo suficiente para manejar con seguridad.","p":"Correcto. Se necesita una constancia del oculista."},"ref":{"doc":"SD","page":10}},{"id":"sd-084","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you wear glasses for the vision test. What does this mean for your driving?","o":["Only at night","You must wear them whenever you drive","Only on the interstate","Nothing, it is your choice"],"h1":"The test shows how you see with them.","h2":"If you wear glasses or contact lenses for the South Dakota vision test, you must wear them whenever you drive.","p":"Right. Glasses on the test means glasses every time you drive."},"es":{"q":"En Dakota del Sur, usted usa lentes en el examen de la vista. ¿Qué significa esto para su manejo?","o":["Solo de noche","Debe usarlos siempre que maneje","Solo en la interestatal","Nada, usted decide"],"h1":"El examen muestra cómo ve con ellos.","h2":"Si usa lentes o lentes de contacto en el examen de la vista de Dakota del Sur, debe usarlos siempre que maneje.","p":"Correcto. Lentes en el examen significa lentes cada vez que maneja."},"ref":{"doc":"SD","page":10}},{"id":"sd-085","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, a driver license shows restriction code B. What does it mean?","o":["Automatic transmission","No night driving","Corrective lenses","50-mile radius of home"],"h1":"Think of glasses or contacts.","h2":"Restriction code B on a South Dakota license means the driver must wear corrective lenses.","p":"Right. B means corrective lenses."},"es":{"q":"En Dakota del Sur, una licencia muestra el código de restricción B. ¿Qué significa?","o":["Transmisión automática","No manejar de noche","Lentes correctivos","Radio de 50 millas de su casa"],"h1":"Piense en lentes o lentes de contacto.","h2":"El código de restricción B en una licencia de Dakota del Sur significa que la persona debe usar lentes correctivos.","p":"Correcto. B significa lentes correctivos."},"ref":{"doc":"SD","page":11}},{"id":"sd-086","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, a driver cannot see clearly with the right eye. What restriction may the license carry?","o":["Must not drive on interstates","Must drive only in daylight","Must have a passenger","Must drive a vehicle with a left outside mirror"],"h1":"It is about a mirror.","h2":"A South Dakota driver who cannot see clearly with the right eye may be restricted to driving a vehicle with a left outside rearview mirror.","p":"Right. A left outside mirror is required."},"es":{"q":"En Dakota del Sur, una persona no ve bien con el ojo derecho. ¿Qué restricción puede tener su licencia?","o":["No puede manejar en interestatales","Solo puede manejar de día","Debe llevar un pasajero","Debe manejar un vehículo con espejo exterior izquierdo"],"h1":"Se trata de un espejo.","h2":"En Dakota del Sur, quien no ve bien con el ojo derecho puede tener la restricción de manejar un vehículo con espejo retrovisor exterior izquierdo.","p":"Correcto. Se exige un espejo exterior izquierdo."},"ref":{"doc":"SD","page":11}},{"id":"sd-087","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, a license shows restriction code G. What does it mean?","o":["No night driving","Corrective lenses","No driving outside of town","Special equipped vehicle"],"h1":"It is about the time of day.","h2":"Restriction code G on a South Dakota license means the driver may not drive at night.","p":"Right. G means no night driving."},"es":{"q":"En Dakota del Sur, una licencia muestra el código de restricción G. ¿Qué significa?","o":["No manejar de noche","Lentes correctivos","No manejar fuera del pueblo","Vehículo con equipo especial"],"h1":"Tiene que ver con la hora del día.","h2":"El código de restricción G en una licencia de Dakota del Sur significa que la persona no puede manejar de noche.","p":"Correcto. G significa no manejar de noche."},"ref":{"doc":"SD","page":11}},{"id":"sd-088","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, under the Skip the Trip program, how often may an eligible person renew or replace a license by mail or online?","o":["Every time","Once in any ten-year period","Once a year","Never, it must be in person"],"h1":"You still have to visit in person some of the time.","h2":"In South Dakota, an eligible person may renew or replace a license by mail or online once in any ten-year period.","p":"Right. Once every ten years by mail or online."},"es":{"q":"En Dakota del Sur, con el programa Skip the Trip, ¿cada cuánto puede una persona elegible renovar o reemplazar la licencia por correo o en línea?","o":["Todas las veces","Una vez en cualquier período de diez años","Una vez al año","Nunca, debe ser en persona"],"h1":"Algunas veces todavía debe ir en persona.","h2":"En Dakota del Sur, una persona elegible puede renovar o reemplazar la licencia por correo o en línea una vez en cualquier período de diez años.","p":"Correcto. Una vez cada diez años por correo o en línea."},"ref":{"doc":"SD","page":12}},{"id":"sd-089","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the reinstatement fee after a license is revoked for a first DWI?","o":["$200","$50","$100","$225"],"h1":"It goes up with each DWI: the second is $150.","h2":"The South Dakota reinstatement fee after a first DWI revocation is $100, plus the application fee.","p":"Right. A first DWI reinstatement costs $100."},"es":{"q":"En Dakota del Sur, ¿cuánto cuesta restablecer la licencia después de que se la quitan por un primer DWI?","o":["$200","$50","$100","$225"],"h1":"Sube con cada DWI: el segundo cuesta $150.","h2":"En Dakota del Sur, el cargo para restablecer la licencia después de un primer DWI es $100, más el costo de la solicitud.","p":"Correcto. Restablecer tras un primer DWI cuesta $100."},"ref":{"doc":"SD","page":12}},{"id":"sd-090","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, your license was suspended (not revoked) and has not expired. What do you need to get it back?","o":["Only a vision test","All the tests again","A new driver education course","An application fee and a $50 reinstatement fee, with no tests"],"h1":"Suspensions are handled more simply than revocations.","h2":"After a suspension in South Dakota, no testing is needed unless the license has expired; you pay the application fee and a $50 reinstatement fee.","p":"Right. Pay the fees; no tests needed."},"es":{"q":"En Dakota del Sur, le suspendieron (no revocaron) la licencia y no ha vencido. ¿Qué necesita para recuperarla?","o":["Solo el examen de la vista","Todos los exámenes otra vez","Un curso de manejo nuevo","El costo de solicitud y un cargo de $50 para restablecerla, sin exámenes"],"h1":"Las suspensiones se manejan de forma más sencilla que las revocaciones.","h2":"Después de una suspensión en Dakota del Sur no se exigen exámenes, salvo que la licencia haya vencido; paga el costo de solicitud y un cargo de $50 para restablecerla.","p":"Correcto. Paga los cargos; no hacen falta exámenes."},"ref":{"doc":"SD","page":12}},{"id":"sd-091","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, your license was revoked. Which tests must you pass when you reapply?","o":["Vision and knowledge tests","No tests","Only the driving test","Only a hearing test"],"h1":"A revocation is more serious than a suspension.","h2":"After a revocation in South Dakota, you must pass the vision and knowledge tests when you reapply, along with paying the fees.","p":"Right. Vision and knowledge tests after a revocation."},"es":{"q":"En Dakota del Sur, le revocaron la licencia. ¿Qué exámenes debe aprobar cuando vuelva a solicitarla?","o":["Los de la vista y de conocimientos","Ningún examen","Solo el de manejo","Solo un examen del oído"],"h1":"Una revocación es más seria que una suspensión.","h2":"Después de una revocación en Dakota del Sur, debe aprobar los exámenes de la vista y de conocimientos al volver a solicitar, además de pagar los cargos.","p":"Correcto. Vista y conocimientos después de una revocación."},"ref":{"doc":"SD","page":12}},{"id":"sd-092","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, a 15-year-old permit holder is convicted of a second traffic violation. How long is the suspension?","o":["30 days","180 days or until age 16, whichever is longer","60 days","One year"],"h1":"It is longer than the 30 days for a first violation.","h2":"A second traffic violation on a South Dakota instruction or restricted minor's permit brings a suspension of 180 days or until the driver's 16th birthday, whichever is longer.","p":"Right. 180 days or until 16, whichever is longer."},"es":{"q":"En Dakota del Sur, una persona de 15 años con permiso es condenada por una segunda infracción de tránsito. ¿Cuánto dura la suspensión?","o":["30 días","180 días o hasta cumplir 16, lo que sea más largo","60 días","Un año"],"h1":"Es más largo que los 30 días por la primera infracción.","h2":"Una segunda infracción de tránsito con permiso de aprendizaje o permiso restringido en Dakota del Sur trae una suspensión de 180 días o hasta cumplir 16 años, lo que sea más largo.","p":"Correcto. 180 días o hasta los 16, lo que sea más largo."},"ref":{"doc":"SD","page":13}},{"id":"sd-093","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, you bring a car from another state after moving here. How long do you have to register it?","o":["10 days","30 days","90 days","1 year"],"h1":"It is about three months.","h2":"In South Dakota, you have 90 days to register a vehicle brought in from another state, with the County Treasurer where you live.","p":"Right. You have 90 days to register it."},"es":{"q":"En Dakota del Sur, usted trae un carro de otro estado después de mudarse aquí. ¿Cuánto tiempo tiene para registrarlo?","o":["10 días","30 días","90 días","1 año"],"h1":"Son unos tres meses.","h2":"En Dakota del Sur, tiene 90 días para registrar un vehículo traído de otro estado, con el Tesorero del condado donde vive.","p":"Correcto. Tiene 90 días para registrarlo."},"ref":{"doc":"SD","page":13}},{"id":"sd-094","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, your last name starts with S. In which month do you renew your vehicle registration?","o":["November","January","July","September"],"h1":"The month starts with the same letter.","h2":"South Dakota staggers registration renewals by last name, and names starting with S renew in September.","p":"Right. S names renew in September."},"es":{"q":"En Dakota del Sur, su apellido empieza con S. ¿En qué mes renueva el registro de su vehículo?","o":["Noviembre","Enero","Julio","Septiembre"],"h1":"El mes en inglés empieza con la misma letra (September).","h2":"Dakota del Sur reparte las renovaciones del registro según el apellido, y los apellidos que empiezan con S renuevan en septiembre.","p":"Correcto. Los apellidos con S renuevan en septiembre."},"ref":{"doc":"SD","page":13}},{"id":"sd-095","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, where should you keep your vehicle's Certificate of Title?","o":["In a safe place, not in the vehicle","In the glove box","Under the driver's seat","With the license plate"],"h1":"Think about what a thief could use to sell your car.","h2":"In South Dakota, the title should be kept in a safe place and not in the vehicle, while the registration certificate must always be carried in the vehicle.","p":"Right. Keep the title somewhere safe, outside the car."},"es":{"q":"En Dakota del Sur, ¿dónde debe guardar el Certificado de Título de su vehículo?","o":["En un lugar seguro, fuera del vehículo","En la guantera","Debajo del asiento del conductor","Con la placa"],"h1":"Piense en lo que un ladrón podría usar para vender su carro.","h2":"En Dakota del Sur, el título debe guardarse en un lugar seguro y no en el vehículo, mientras que el certificado de registro debe llevarse siempre en el vehículo.","p":"Correcto. Guarde el título en un lugar seguro, fuera del carro."},"ref":{"doc":"SD","page":13}},{"id":"sd-096","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, instead of an insurance policy, a vehicle owner may deposit money with the State Treasurer. How much?","o":["$5,000","$50,000","$25,000","$100,000"],"h1":"It is a large five-digit amount.","h2":"One way to meet South Dakota's financial responsibility law is a certificate of deposit or securities of $50,000 deposited with the State Treasurer.","p":"Right. A $50,000 deposit with the State Treasurer."},"es":{"q":"En Dakota del Sur, en lugar de una póliza de seguro, el dueño de un vehículo puede depositar dinero con el Tesorero del Estado. ¿Cuánto?","o":["$5,000","$50,000","$25,000","$100,000"],"h1":"Es una cantidad grande de cinco cifras.","h2":"Una forma de cumplir la ley de responsabilidad financiera de Dakota del Sur es un certificado de depósito o valores de $50,000 depositados con el Tesorero del Estado.","p":"Correcto. Un depósito de $50,000 con el Tesorero del Estado."},"ref":{"doc":"SD","page":13}},{"id":"sd-097","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, what is the penalty for a conviction of failing to keep proof of insurance?","o":["A $10 fine","A warning only","Up to 30 days in jail, a fine of up to $500, or both, plus a license suspension","Losing the car"],"h1":"It is a Class 2 misdemeanor with jail time possible.","h2":"In South Dakota, failing to maintain proof of insurance is a Class 2 misdemeanor, punishable by up to 30 days in jail, a fine of up to $500, or both, plus a license suspension of 30 days to one year.","p":"Right. Jail, a fine, or both, and a suspension."},"es":{"q":"En Dakota del Sur, ¿cuál es la pena por una condena por no mantener prueba de seguro?","o":["Una multa de $10","Solo una advertencia","Hasta 30 días de cárcel, una multa de hasta $500 o ambas, más la suspensión de la licencia","Perder el carro"],"h1":"Es un delito menor de Clase 2 y puede haber cárcel.","h2":"En Dakota del Sur, no mantener prueba de seguro es un delito menor de Clase 2, castigado con hasta 30 días de cárcel, una multa de hasta $500 o ambas, más una suspensión de la licencia de 30 días a un año.","p":"Correcto. Cárcel, multa o ambas, y una suspensión."},"ref":{"doc":"SD","page":14}},{"id":"sd-098","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how many points go on your record for a speeding conviction?","o":["6 points","2 points","4 points","None; speeding does not carry points"],"h1":"South Dakota's point list leaves out some violations.","h2":"Under the South Dakota point system, no points are given for speeding, parking, equipment, size or weight violations.","p":"Right. Speeding carries no points in South Dakota."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos se ponen en su historial por una condena por exceso de velocidad?","o":["6 puntos","2 puntos","4 puntos","Ninguno; el exceso de velocidad no da puntos"],"h1":"La lista de puntos de Dakota del Sur deja fuera algunas infracciones.","h2":"En el sistema de puntos de Dakota del Sur no se dan puntos por exceso de velocidad, estacionamiento, equipo, tamaño o peso.","p":"Correcto. El exceso de velocidad no da puntos en Dakota del Sur."},"ref":{"doc":"SD","page":14}},{"id":"sd-099","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, one traffic stop leads to several convictions. How are points given?","o":["Only for the offense with the highest point value","For every offense added together","Only for the first offense written","No points are given"],"h1":"You are not charged points twice for one incident.","h2":"When several offenses come from one incident in South Dakota, points are given only for the offense with the highest point value.","p":"Right. Only the highest-point offense counts."},"es":{"q":"En Dakota del Sur, una sola parada de tránsito termina en varias condenas. ¿Cómo se dan los puntos?","o":["Solo por la infracción con más puntos","Por todas las infracciones sumadas","Solo por la primera infracción escrita","No se dan puntos"],"h1":"No le cobran puntos dos veces por un solo incidente.","h2":"Cuando varias infracciones vienen de un solo incidente en Dakota del Sur, se dan puntos solo por la infracción que tiene más puntos.","p":"Correcto. Solo cuenta la infracción con más puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-100","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, you are convicted of a moving violation while driving in another state. What happens to your South Dakota record?","o":["Nothing, it does not count","Points are added as if it happened in South Dakota","Only half the points are added","It is added only if you lived there"],"h1":"State lines do not erase your record.","h2":"South Dakota adds points for out-of-state convictions just as if they had happened in South Dakota.","p":"Right. Out-of-state convictions count the same."},"es":{"q":"En Dakota del Sur, a usted lo condenan por una infracción en movimiento mientras manejaba en otro estado. ¿Qué pasa con su historial en Dakota del Sur?","o":["Nada, no cuenta","Se agregan puntos como si hubiera pasado en Dakota del Sur","Solo se agrega la mitad de los puntos","Solo se agrega si usted vivía allá"],"h1":"Las fronteras entre estados no borran su historial.","h2":"Dakota del Sur agrega puntos por condenas en otros estados igual que si hubieran pasado en Dakota del Sur.","p":"Correcto. Las condenas de otros estados cuentan igual."},"ref":{"doc":"SD","page":14}},{"id":"sd-101","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how long is a second license suspension for too many points?","o":["1 year","60 days","6 months","2 years"],"h1":"The first is 60 days and the third is a year.","h2":"A second South Dakota points suspension lasts 6 months; the first lasts 60 days and any later one lasts 1 year.","p":"Right. A second points suspension is 6 months."},"es":{"q":"En Dakota del Sur, ¿cuánto dura una segunda suspensión de la licencia por demasiados puntos?","o":["1 año","60 días","6 meses","2 años"],"h1":"La primera es de 60 días y la tercera de un año.","h2":"Una segunda suspensión por puntos en Dakota del Sur dura 6 meses; la primera dura 60 días y las siguientes, 1 año.","p":"Correcto. Una segunda suspensión por puntos dura 6 meses."},"ref":{"doc":"SD","page":14}},{"id":"sd-102","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how many points does a conviction for driving while intoxicated (DWI) carry?","o":["15 points","6 points","8 points","10 points"],"h1":"It is the highest number on the point table.","h2":"A DWI conviction in South Dakota carries 10 points, and state law also requires the license to be revoked.","p":"Right. DWI carries 10 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos da una condena por manejar intoxicado (DWI)?","o":["15 puntos","6 puntos","8 puntos","10 puntos"],"h1":"Es el número más alto de la tabla de puntos.","h2":"Una condena por DWI en Dakota del Sur da 10 puntos, y la ley también exige que se revoque la licencia.","p":"Correcto. El DWI da 10 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-103","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, how many points does a drag racing conviction carry?","o":["6 points","2 points","3 points","10 points"],"h1":"It is the same as eluding the police.","h2":"Drag racing and eluding the police each carry 6 points in South Dakota.","p":"Right. Drag racing carries 6 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos da una condena por carreras de arrancones (drag racing)?","o":["6 puntos","2 puntos","3 puntos","10 puntos"],"h1":"Es lo mismo que huir de la policía.","h2":"Las carreras de arrancones y huir de la policía dan 6 puntos cada una en Dakota del Sur.","p":"Correcto. Las carreras de arrancones dan 6 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-104","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, how many points does a conviction for failing to yield the right-of-way carry?","o":["2 points","4 points","6 points","8 points"],"h1":"It is the same as improper passing.","h2":"Failure to yield the right-of-way carries 4 points in South Dakota, the same as improper passing or driving on the wrong side of the road.","p":"Right. Failing to yield carries 4 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos da una condena por no ceder el paso?","o":["2 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Es lo mismo que rebasar de forma indebida.","h2":"No ceder el paso da 4 puntos en Dakota del Sur, igual que rebasar de forma indebida o manejar en el lado equivocado de la vía.","p":"Correcto. No ceder el paso da 4 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-105","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, how many points does running a stop sign or red light carry?","o":["4 points","2 points","3 points","6 points"],"h1":"It is one more than an ordinary moving violation.","h2":"A stop sign or traffic light violation carries 3 points in South Dakota.","p":"Right. A stop sign or light violation carries 3 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos da pasarse un alto o una luz roja?","o":["4 puntos","2 puntos","3 puntos","6 puntos"],"h1":"Es uno más que una infracción en movimiento común.","h2":"Una infracción de señal de alto o semáforo da 3 puntos en Dakota del Sur.","p":"Correcto. Una infracción de alto o semáforo da 3 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-106","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, how many points does a moving violation carry if it is not listed separately on the point table?","o":["5 points","1 point","3 points","2 points"],"h1":"It is the lowest number on the table.","h2":"Any other moving violation not listed separately carries 2 points in South Dakota.","p":"Right. Other moving violations carry 2 points."},"es":{"q":"En Dakota del Sur, ¿cuántos puntos da una infracción en movimiento que no aparece aparte en la tabla de puntos?","o":["5 puntos","1 punto","3 puntos","2 puntos"],"h1":"Es el número más bajo de la tabla.","h2":"Cualquier otra infracción en movimiento que no aparece aparte da 2 puntos en Dakota del Sur.","p":"Correcto. Las demás infracciones en movimiento dan 2 puntos."},"ref":{"doc":"SD","page":14}},{"id":"sd-107","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, besides 20/40 with both eyes, what is the worst vision allowed in either single eye for a license with no vision limits?","o":["20/50","20/40","20/70","20/100"],"h1":"It is a little worse than 20/40.","h2":"For a South Dakota license without vision restrictions, you need 20/40 or better with both eyes and no worse than 20/50 in either eye.","p":"Right. No worse than 20/50 in either eye."},"es":{"q":"En Dakota del Sur, además de 20/40 con ambos ojos, ¿cuál es la peor vista permitida en cada ojo por separado para una licencia sin límites de vista?","o":["20/50","20/40","20/70","20/100"],"h1":"Es un poco peor que 20/40.","h2":"Para una licencia de Dakota del Sur sin restricciones de vista, necesita 20/40 o mejor con ambos ojos y no peor que 20/50 en cada ojo.","p":"Correcto. No peor que 20/50 en cada ojo."},"ref":{"doc":"SD","page":18}},{"id":"sd-108","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, the manual gives advice for long trips. How often should you plan to stop?","o":["Every 300 miles","About every 100 miles or 2 hours","Only when you need gas","Every 30 minutes"],"h1":"Think of a two-hour stretch.","h2":"The South Dakota manual says to plan a stop about every 100 miles or 2 hours to stay alert.","p":"Right. Stop about every 100 miles or 2 hours."},"es":{"q":"En Dakota del Sur, el manual da consejos para viajes largos. ¿Cada cuánto debe planear detenerse?","o":["Cada 300 millas","Más o menos cada 100 millas o 2 horas","Solo cuando necesite gasolina","Cada 30 minutos"],"h1":"Piense en un tramo de dos horas.","h2":"El manual de Dakota del Sur dice que planee detenerse más o menos cada 100 millas o 2 horas para mantenerse alerta.","p":"Correcto. Deténgase más o menos cada 100 millas o 2 horas."},"ref":{"doc":"SD","page":18}},{"id":"sd-109","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, you start to feel tired on the road. How long a nap does the manual suggest at a rest area?","o":["1 hour","5 minutes","15 to 20 minutes","2 hours"],"h1":"A short nap, less than half an hour.","h2":"The South Dakota manual suggests pulling off at the next exit or rest area for a 15 to 20-minute nap, or finding a place to sleep for the night.","p":"Right. A 15 to 20-minute nap."},"es":{"q":"En Dakota del Sur, empieza a sentirse cansado en el camino. ¿De cuánto tiempo es la siesta que sugiere el manual en un área de descanso?","o":["1 hora","5 minutos","De 15 a 20 minutos","2 horas"],"h1":"Una siesta corta, de menos de media hora.","h2":"El manual de Dakota del Sur sugiere salir en la próxima salida o área de descanso para una siesta de 15 a 20 minutos, o buscar dónde dormir esa noche.","p":"Correcto. Una siesta de 15 a 20 minutos."},"ref":{"doc":"SD","page":19}},{"id":"sd-110","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, which of these does state law ban for every driver, not just teens?","o":["Drinking water","Listening to the radio","Talking to passengers","Texting, reading texts, and social networking while driving"],"h1":"It involves using your phone's screen to read or write.","h2":"South Dakota law bans texting, reading texts and social networking while driving for all drivers.","p":"Right. Texting and social media are banned for everyone."},"es":{"q":"En Dakota del Sur, ¿cuál de estas cosas prohíbe la ley a todos los conductores, no solo a los adolescentes?","o":["Tomar agua","Escuchar la radio","Hablar con los pasajeros","Mandar o leer mensajes de texto y usar redes sociales al manejar"],"h1":"Se trata de usar la pantalla del teléfono para leer o escribir.","h2":"La ley de Dakota del Sur prohíbe a todos los conductores mandar o leer mensajes de texto y usar redes sociales mientras manejan.","p":"Correcto. Los mensajes y las redes sociales están prohibidos para todos."},"ref":{"doc":"SD","page":19}},{"id":"sd-111","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, you are drunk and sitting in the driver's seat of a parked car with the keys. Can you be arrested?","o":["Yes, having physical control of the vehicle is enough","No, only if the car is moving","No, if the engine is off","Only if you are under 21"],"h1":"You do not have to be driving.","h2":"In South Dakota, you can be arrested if you have physical control of a vehicle with a blood alcohol level over the limit, even if you are not driving.","p":"Right. Physical control is enough for an arrest."},"es":{"q":"En Dakota del Sur, usted está borracho y sentado en el asiento del conductor de un carro estacionado con las llaves. ¿Lo pueden arrestar?","o":["Sí, basta con tener el control físico del vehículo","No, solo si el carro está en movimiento","No, si el motor está apagado","Solo si tiene menos de 21 años"],"h1":"No hace falta estar manejando.","h2":"En Dakota del Sur lo pueden arrestar si tiene el control físico de un vehículo con un nivel de alcohol en la sangre mayor al límite, aunque no esté manejando.","p":"Correcto. El control físico basta para un arresto."},"ref":{"doc":"SD","page":20}},{"id":"sd-112","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, at what blood alcohol level does the manual say vision is already affected for all drivers?","o":["0.08 percent","0.02 percent","0.10 percent","0.15 percent"],"h1":"It is the same number as the limit for drivers under 21.","h2":"The South Dakota manual says vision is affected at a blood alcohol level of 0.02 percent for all drivers.","p":"Right. Vision is affected at 0.02 percent."},"es":{"q":"En Dakota del Sur, ¿con qué nivel de alcohol en la sangre dice el manual que la vista ya se afecta en todos los conductores?","o":["0.08 por ciento","0.02 por ciento","0.10 por ciento","0.15 por ciento"],"h1":"Es el mismo número que el límite para menores de 21.","h2":"El manual de Dakota del Sur dice que la vista se afecta con un nivel de alcohol en la sangre de 0.02 por ciento en todos los conductores.","p":"Correcto. La vista se afecta con 0.02 por ciento."},"ref":{"doc":"SD","page":20}},{"id":"sd-114","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, a driver under 21 is caught a second time with a blood alcohol level of 0.02 percent or more. How long is the license lost?","o":["5 years","30 days","60 days","180 days"],"h1":"It is about six months.","h2":"A second zero-tolerance offense in South Dakota (under 21, 0.02 percent or more) is a Class 2 misdemeanor with a fine and a 180-day loss of license.","p":"Right. A second offense means 180 days without a license."},"es":{"q":"En Dakota del Sur, a un conductor menor de 21 lo detienen por segunda vez con 0.02 por ciento o más de alcohol en la sangre. ¿Por cuánto tiempo pierde la licencia?","o":["5 años","30 días","60 días","180 días"],"h1":"Son unos seis meses.","h2":"Una segunda falta de tolerancia cero en Dakota del Sur (menor de 21, con 0.02 por ciento o más) es un delito menor de Clase 2 con multa y 180 días sin licencia.","p":"Correcto. Una segunda falta significa 180 días sin licencia."},"ref":{"doc":"SD","page":20}},{"id":"sd-115","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, what is the shortest license loss for a first DWI (0.08 percent or more)?","o":["30 days","7 days","180 days","5 years"],"h1":"It is about one month.","h2":"A first DWI in South Dakota is a Class 1 misdemeanor, and you lose your license for at least 30 days.","p":"Right. At least 30 days for a first DWI."},"es":{"q":"En Dakota del Sur, ¿cuál es la pérdida de licencia más corta por un primer DWI (0.08 por ciento o más)?","o":["30 días","7 días","180 días","5 años"],"h1":"Es más o menos un mes.","h2":"Un primer DWI en Dakota del Sur es un delito menor de Clase 1, y usted pierde la licencia por lo menos 30 días.","p":"Correcto. Por lo menos 30 días por un primer DWI."},"ref":{"doc":"SD","page":20}},{"id":"sd-116","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, what is the shortest license loss for a second DWI?","o":["30 days","One year","90 days","6 months"],"h1":"It is much longer than for a first DWI.","h2":"A second DWI in South Dakota brings a license loss of at least one year, along with a fine, jail of up to one year, or both.","p":"Right. At least one year for a second DWI."},"es":{"q":"En Dakota del Sur, ¿cuál es la pérdida de licencia más corta por un segundo DWI?","o":["30 días","Un año","90 días","6 meses"],"h1":"Es mucho más larga que por un primer DWI.","h2":"Un segundo DWI en Dakota del Sur trae una pérdida de licencia de por lo menos un año, junto con multa, cárcel de hasta un año o ambas.","p":"Correcto. Por lo menos un año por un segundo DWI."},"ref":{"doc":"SD","page":20}},{"id":"sd-117","scope":"SD","cat":"licensing","sign":null,"c":2,"en":{"q":"In South Dakota, a person's license is revoked for a second DWI, and they are caught driving without a license. What is the minimum jail sentence?","o":["1 day, which can be suspended","No jail, only a fine","3 days, which cannot be suspended","30 days"],"h1":"It is a few days, and the judge cannot waive it.","h2":"After a second DWI in South Dakota, a person convicted of driving without a license during the revocation must spend at least three days in county jail, which may not be suspended.","p":"Right. At least 3 days in jail, not suspendable."},"es":{"q":"En Dakota del Sur, a una persona le revocan la licencia por un segundo DWI y la detienen manejando sin licencia. ¿Cuál es la cárcel mínima?","o":["1 día, que se puede suspender","Sin cárcel, solo multa","3 días, que no se pueden suspender","30 días"],"h1":"Son unos pocos días, y el juez no puede perdonarlos.","h2":"Después de un segundo DWI en Dakota del Sur, quien es condenado por manejar sin licencia durante la revocación debe pasar por lo menos tres días en la cárcel del condado, sin posibilidad de suspensión.","p":"Correcto. Por lo menos 3 días de cárcel, sin suspensión."},"ref":{"doc":"SD","page":20}},{"id":"sd-118","scope":"SD","cat":"signs","sign":null,"c":3,"en":{"q":"In South Dakota, you see a small \"THINK\" sign on a post along a state highway. What does it mark?","o":["A school zone","A speed camera","A rest area ahead","A place where a person was killed in a crash"],"h1":"It is a memorial and a reminder.","h2":"South Dakota puts up one THINK sign on a state highway for each person killed in a crash there, as a memorial and a reminder to drive safely.","p":"Right. Each THINK sign marks a crash death."},"es":{"q":"En Dakota del Sur, ve un letrero pequeño que dice \"THINK\" en un poste a lo largo de una carretera estatal. ¿Qué marca?","o":["Una zona escolar","Una cámara de velocidad","Un área de descanso más adelante","Un lugar donde murió una persona en un choque"],"h1":"Es un recuerdo y un aviso.","h2":"Dakota del Sur pone un letrero THINK en la carretera estatal por cada persona que murió en un choque en ese lugar, como recuerdo y aviso para manejar con cuidado.","p":"Correcto. Cada letrero THINK marca una muerte en un choque."},"ref":{"doc":"SD","page":21}},{"id":"sd-119","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, the manual describes the penny test for tires. You put Lincoln's head into the tread and can see all of his head. What does it mean?","o":["The tires are too worn and should be replaced","The tires are fine","The tire pressure is too high","The tires are new"],"h1":"Deep tread would cover part of his head.","h2":"In the penny test from the South Dakota manual, if you can see all of Lincoln's head, the tread is too worn and the tires should be replaced.","p":"Right. Seeing all of Lincoln's head means worn-out tires."},"es":{"q":"En Dakota del Sur, el manual describe la prueba de la moneda para las llantas. Usted mete la cabeza de Lincoln en la ranura y ve toda su cabeza. ¿Qué significa?","o":["Las llantas están muy gastadas y hay que cambiarlas","Las llantas están bien","La presión de las llantas está muy alta","Las llantas son nuevas"],"h1":"Una ranura profunda taparía parte de la cabeza.","h2":"En la prueba de la moneda del manual de Dakota del Sur, si se ve toda la cabeza de Lincoln, la ranura está muy gastada y hay que cambiar las llantas.","p":"Correcto. Ver toda la cabeza de Lincoln significa llantas gastadas."},"ref":{"doc":"SD","page":23}},{"id":"sd-120","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, what is the least light that tint on the rear windows (behind the driver) must let through?","o":["35 percent","20 percent","50 percent","5 percent"],"h1":"It is lower than the limit for the front side windows.","h2":"South Dakota law does not allow rear-window tint or film that lets through less than 20 percent of light, with a 9 percent enforcement tolerance.","p":"Right. Rear windows must let through at least 20 percent."},"es":{"q":"En Dakota del Sur, ¿cuánta luz como mínimo debe dejar pasar el polarizado de las ventanas traseras (detrás del conductor)?","o":["35 por ciento","20 por ciento","50 por ciento","5 por ciento"],"h1":"Es menos que el límite de las ventanas laterales delanteras.","h2":"La ley de Dakota del Sur no permite polarizado o película en las ventanas traseras que deje pasar menos del 20 por ciento de la luz, con una tolerancia de 9 por ciento.","p":"Correcto. Las ventanas traseras deben dejar pasar por lo menos 20 por ciento."},"ref":{"doc":"SD","page":24}},{"id":"sd-121","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, how much space does the manual say to leave between your chest and the steering wheel?","o":["5 inches","2 inches","10 inches","24 inches"],"h1":"It leaves room for the air bag.","h2":"The South Dakota manual says there should be 10 inches between your chest and the steering wheel.","p":"Right. Leave 10 inches."},"es":{"q":"En Dakota del Sur, ¿cuánto espacio dice el manual que debe dejar entre su pecho y el volante?","o":["5 pulgadas","2 pulgadas","10 pulgadas","24 pulgadas"],"h1":"Deja lugar para la bolsa de aire.","h2":"El manual de Dakota del Sur dice que debe haber 10 pulgadas entre su pecho y el volante.","p":"Correcto. Deje 10 pulgadas."},"ref":{"doc":"SD","page":25}},{"id":"sd-122","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, how does the manual say to set your left side mirror?","o":["Point it straight out to the side","Set it so half the mirror shows your car","Point it at the ground","Rest your head against the closed window and set it to barely show the side of your car"],"h1":"Lean toward the window first.","h2":"The South Dakota manual says to rest your head against the closed driver's window and set the left mirror so it barely shows the edge of your car, which shrinks the blind spot.","p":"Right. Head on the window, then barely see your car's edge."},"es":{"q":"En Dakota del Sur, ¿cómo dice el manual que ajuste el espejo lateral izquierdo?","o":["Apúntelo derecho hacia el costado","Ajústelo para que la mitad del espejo muestre su carro","Apúntelo hacia el suelo","Apoye la cabeza en la ventana cerrada y ajústelo para que apenas se vea el costado del carro"],"h1":"Primero inclínese hacia la ventana.","h2":"El manual de Dakota del Sur dice que apoye la cabeza en la ventana cerrada del conductor y ajuste el espejo izquierdo para que apenas se vea el borde de su carro, lo que reduce el punto ciego.","p":"Correcto. Cabeza en la ventana y apenas ver el borde del carro."},"ref":{"doc":"SD","page":25}},{"id":"sd-123","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, children up to what age should sit in the back seat to avoid air bag injuries?","o":["12 and younger","5 and younger","8 and younger","16 and younger"],"h1":"It is the last age before the teen years.","h2":"The South Dakota manual says children age 12 and younger should sit in the rear seat to avoid injury from an air bag in a crash.","p":"Right. Children 12 and younger ride in back."},"es":{"q":"En Dakota del Sur, ¿hasta qué edad deben ir los niños en el asiento de atrás para evitar lesiones por la bolsa de aire?","o":["12 años o menos","5 años o menos","8 años o menos","16 años o menos"],"h1":"Es la última edad antes de la adolescencia.","h2":"El manual de Dakota del Sur dice que los niños de 12 años o menos deben ir en el asiento de atrás para evitar lesiones por la bolsa de aire en un choque.","p":"Correcto. Los niños de 12 o menos van atrás."},"ref":{"doc":"SD","page":26}},{"id":"sd-124","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, is breaking the front-seat seat belt law counted as a moving traffic offense?","o":["Yes, it adds 2 points","No, it is not a moving traffic offense","Yes, it adds 4 points","Only for drivers under 18"],"h1":"The law says so directly.","h2":"South Dakota's seat belt law (SDCL 32-38-1) says a violation is not a moving traffic offense, so it does not add points to your record.","p":"Right. It is not a moving traffic offense."},"es":{"q":"En Dakota del Sur, ¿no cumplir la ley del cinturón de seguridad en los asientos delanteros cuenta como infracción de tránsito en movimiento?","o":["Sí, agrega 2 puntos","No, no es una infracción en movimiento","Sí, agrega 4 puntos","Solo para menores de 18"],"h1":"La ley lo dice directamente.","h2":"La ley del cinturón de Dakota del Sur (SDCL 32-38-1) dice que la falta no es una infracción de tránsito en movimiento, así que no agrega puntos a su historial.","p":"Correcto. No es una infracción en movimiento."},"ref":{"doc":"SD","page":26}},{"id":"sd-125","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, according to the manual's car seat guide, infant seats are for babies up to what weight?","o":["40 pounds","10 pounds","20 pounds","60 pounds"],"h1":"Toddler seats go up to 40 pounds.","h2":"The South Dakota manual's car seat guide says infant seats are for children up to 20 pounds, always facing rearward.","p":"Right. Infant seats are for babies up to 20 pounds."},"es":{"q":"En Dakota del Sur, según la guía de asientos del manual, ¿hasta qué peso son los asientos para bebé?","o":["40 libras","10 libras","20 libras","60 libras"],"h1":"Los asientos para niños pequeños llegan hasta 40 libras.","h2":"La guía de asientos del manual de Dakota del Sur dice que los asientos para bebé son para niños de hasta 20 libras, siempre mirando hacia atrás.","p":"Correcto. Los asientos para bebé son hasta 20 libras."},"ref":{"doc":"SD","page":27}},{"id":"sd-126","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, according to the manual's car seat guide, booster seats are for children who weigh at least how much?","o":["80 pounds","10 pounds","20 pounds","30 pounds"],"h1":"It is less than the 40-pound limit for toddler seats.","h2":"The South Dakota manual's car seat guide says booster seats are for toddlers who weigh at least 30 pounds.","p":"Right. Boosters start at 30 pounds."},"es":{"q":"En Dakota del Sur, según la guía de asientos del manual, ¿cuánto deben pesar como mínimo los niños para usar un asiento elevado (booster)?","o":["80 libras","10 libras","20 libras","30 libras"],"h1":"Es menos que el límite de 40 libras de los asientos para niños pequeños.","h2":"La guía de asientos del manual de Dakota del Sur dice que los asientos elevados son para niños pequeños que pesan por lo menos 30 libras.","p":"Correcto. El booster empieza en 30 libras."},"ref":{"doc":"SD","page":27}},{"id":"sd-127","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, the manual says many people skip seat belts on short trips. Where do over half of all traffic deaths happen?","o":["Within 25 miles of home","On interstates far from home","Only in big cities","In parking lots"],"h1":"Short trips are not as safe as people think.","h2":"The South Dakota manual says over half of all traffic deaths happen within 25 miles of home, so wear a seat belt on every trip.","p":"Right. Most deaths happen within 25 miles of home."},"es":{"q":"En Dakota del Sur, el manual dice que mucha gente no usa el cinturón en viajes cortos. ¿Dónde ocurren más de la mitad de las muertes en el tránsito?","o":["A menos de 25 millas de casa","En interestatales lejos de casa","Solo en ciudades grandes","En estacionamientos"],"h1":"Los viajes cortos no son tan seguros como se cree.","h2":"El manual de Dakota del Sur dice que más de la mitad de las muertes en el tránsito ocurren a menos de 25 millas de casa, así que use el cinturón en cada viaje.","p":"Correcto. La mayoría de las muertes ocurren a menos de 25 millas de casa."},"ref":{"doc":"SD","page":28}},{"id":"sd-128","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, where does the manual say to place your hands on the steering wheel?","o":["At 10 and 2 o'clock","At 3 and 9 o'clock","Both at 12 o'clock","One hand at 6 o'clock"],"h1":"The older 10-and-2 position is no longer advised because of air bags.","h2":"The South Dakota manual says to hold the wheel at the 3 and 9 o'clock positions; 10 and 2 is no longer recommended in cars with air bags.","p":"Right. Hands at 3 and 9 o'clock."},"es":{"q":"En Dakota del Sur, ¿dónde dice el manual que ponga las manos en el volante?","o":["En las 10 y las 2","En las 3 y las 9","Las dos en las 12","Una mano en las 6"],"h1":"La posición antigua de las 10 y las 2 ya no se recomienda por las bolsas de aire.","h2":"El manual de Dakota del Sur dice que tome el volante en las posiciones de las 3 y las 9; las 10 y las 2 ya no se recomiendan en carros con bolsas de aire.","p":"Correcto. Manos en las 3 y las 9."},"ref":{"doc":"SD","page":29}},{"id":"sd-129","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, why must you never turn the ignition to the \"lock\" position while the car is moving?","o":["The doors will lock","The radio will turn off","The steering will lock and you will lose control","It saves gas"],"h1":"Think about what the word lock does to the wheel.","h2":"The South Dakota manual warns that turning the ignition to lock while moving will lock the steering when you turn the wheel, and you will lose control.","p":"Right. The steering locks and you lose control."},"es":{"q":"En Dakota del Sur, ¿por qué nunca debe girar la llave a la posición \"lock\" mientras el carro está en movimiento?","o":["Se cierran las puertas","Se apaga la radio","El volante se bloquea y usted pierde el control","Ahorra gasolina"],"h1":"Piense en lo que la palabra bloqueo le hace al volante.","h2":"El manual de Dakota del Sur advierte que girar la llave a lock en movimiento bloquea el volante al girarlo, y usted pierde el control.","p":"Correcto. El volante se bloquea y pierde el control."},"ref":{"doc":"SD","page":29}},{"id":"sd-130","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, when backing up, where does the manual say to hold the steering wheel with your left hand?","o":["Do not hold it","At the 6 o'clock position","At 3 o'clock","At the 12 o'clock position"],"h1":"Your right arm goes over the passenger seat.","h2":"When backing up, the South Dakota manual says to hold the wheel at 12 o'clock with your left hand, put your right arm on the back of the passenger seat, and look through the rear window.","p":"Right. Left hand at 12 o'clock."},"es":{"q":"En Dakota del Sur, al dar reversa, ¿dónde dice el manual que tome el volante con la mano izquierda?","o":["No lo tome","En la posición de las 6","En las 3","En la posición de las 12"],"h1":"El brazo derecho va sobre el asiento del pasajero.","h2":"Al dar reversa, el manual de Dakota del Sur dice que tome el volante en las 12 con la mano izquierda, ponga el brazo derecho en el respaldo del asiento del pasajero y mire por la ventana trasera.","p":"Correcto. Mano izquierda en las 12."},"ref":{"doc":"SD","page":30}},{"id":"sd-131","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, what must vehicles in a funeral procession have on?","o":["Their headlights","Their hazard flashers only","Their high beams","Their radios"],"h1":"It helps others see that they are part of the procession.","h2":"In South Dakota, vehicles in a funeral procession must have their headlights on, and other drivers must not cut into the procession.","p":"Right. Headlights on in a funeral procession."},"es":{"q":"En Dakota del Sur, ¿qué deben llevar encendido los vehículos en un cortejo fúnebre?","o":["Los faros","Solo las luces intermitentes","Las luces altas","La radio"],"h1":"Ayuda a que otros vean que forman parte del cortejo.","h2":"En Dakota del Sur, los vehículos en un cortejo fúnebre deben llevar los faros encendidos, y los demás conductores no deben meterse en el cortejo.","p":"Correcto. Faros encendidos en un cortejo fúnebre."},"ref":{"doc":"SD","page":31}},{"id":"sd-132","scope":"SD","cat":"signals","sign":null,"c":1,"en":{"q":"In South Dakota, you come to a traffic light that is completely dark because of a power outage. What must you do?","o":["Drive through without slowing","Stop as if it were a stop sign","Slow down but do not stop","Wait until the power comes back"],"h1":"A dark signal is treated like a red one.","h2":"In South Dakota, if a traffic signal is completely unlit or showing red while broken, you must stop as if you were at a stop sign.","p":"Right. Treat a dark signal like a stop sign."},"es":{"q":"En Dakota del Sur, llega a un semáforo que está completamente apagado por un corte de luz. ¿Qué debe hacer?","o":["Pasar sin bajar la velocidad","Detenerse como si fuera una señal de alto","Bajar la velocidad sin detenerse","Esperar a que regrese la luz"],"h1":"Un semáforo apagado se trata como uno en rojo.","h2":"En Dakota del Sur, si un semáforo está completamente apagado o muestra rojo mientras falla, debe detenerse como si estuviera ante una señal de alto.","p":"Correcto. Trate un semáforo apagado como un alto."},"ref":{"doc":"SD","page":32}},{"id":"sd-133","scope":"SD","cat":"signs","sign":null,"c":2,"en":{"q":"In South Dakota, a reflective orange triangle on the back of a vehicle means it is going slower than what speed?","o":["45 mph","10 mph","25 mph","55 mph"],"h1":"Think of farm tractors and horse-drawn wagons.","h2":"In South Dakota, the reflective orange slow-moving vehicle triangle means the vehicle travels less than 25 mph, like farm equipment or horse-drawn wagons.","p":"Right. It means slower than 25 mph."},"es":{"q":"En Dakota del Sur, un triángulo anaranjado reflejante en la parte de atrás de un vehículo significa que va más lento que ¿qué velocidad?","o":["45 mph","10 mph","25 mph","55 mph"],"h1":"Piense en tractores y carretas de caballos.","h2":"En Dakota del Sur, el triángulo anaranjado reflejante de vehículo lento significa que el vehículo va a menos de 25 mph, como la maquinaria agrícola o las carretas de caballos.","p":"Correcto. Significa más lento que 25 mph."},"ref":{"doc":"SD","page":36}},{"id":"sd-134","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, a roundabout has a raised paved area inside the circle called a truck apron. Who may drive on it?","o":["Anyone in a hurry","Cars that want to pass","Pickups and SUVs","The rear wheels of large trucks only"],"h1":"It is for vehicles that need extra room to turn.","h2":"In South Dakota, a roundabout's truck apron is for the rear wheels of large trucks; cars, SUVs and pickup trucks must not use it.","p":"Right. Only large trucks' rear wheels use the apron."},"es":{"q":"En Dakota del Sur, una glorieta tiene dentro del círculo un área pavimentada elevada llamada plataforma para camiones. ¿Quién puede pasar por ella?","o":["Cualquiera que tenga prisa","Carros que quieren rebasar","Camionetas pickup y SUV","Solo las ruedas traseras de camiones grandes"],"h1":"Es para vehículos que necesitan más espacio para dar vuelta.","h2":"En Dakota del Sur, la plataforma para camiones de una glorieta es para las ruedas traseras de camiones grandes; los carros, las SUV y las pickup no deben usarla.","p":"Correcto. Solo las ruedas traseras de camiones grandes usan la plataforma."},"ref":{"doc":"SD","page":39}},{"id":"sd-135","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, before entering an intersection after a stop, which way does the manual recommend looking?","o":["Left, then right, then left again","Right only","Straight ahead only","Right, then left"],"h1":"You check the nearest lane twice.","h2":"The South Dakota manual recommends looking left, then right, and then left again before you enter an intersection.","p":"Right. Left, right, then left again."},"es":{"q":"En Dakota del Sur, antes de entrar a una intersección después de detenerse, ¿hacia dónde recomienda mirar el manual?","o":["A la izquierda, a la derecha y otra vez a la izquierda","Solo a la derecha","Solo de frente","A la derecha y luego a la izquierda"],"h1":"Revisa dos veces el carril más cercano.","h2":"El manual de Dakota del Sur recomienda mirar a la izquierda, luego a la derecha y otra vez a la izquierda antes de entrar a una intersección.","p":"Correcto. Izquierda, derecha y otra vez izquierda."},"ref":{"doc":"SD","page":39}},{"id":"sd-136","scope":"SD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Dakota, on an undivided road near a curve or hilltop, when is a U-turn not allowed?","o":["When the road is wet","When other drivers cannot see you within 500 feet","Only at night","When there is a yellow center line"],"h1":"It is about how far other drivers can see your car.","h2":"In South Dakota, you may not make a U-turn on a curve or near the top of a hill on an undivided highway if drivers coming from any direction cannot see you within 500 feet.","p":"Right. Not where you cannot be seen within 500 feet."},"es":{"q":"En Dakota del Sur, en una vía sin división cerca de una curva o la cima de una colina, ¿cuándo no se permite una vuelta en U?","o":["Cuando la vía está mojada","Cuando otros conductores no pueden verlo a menos de 500 pies","Solo de noche","Cuando hay una línea central amarilla"],"h1":"Se trata de qué tan lejos pueden ver su carro los demás.","h2":"En Dakota del Sur no puede dar vuelta en U en una curva o cerca de la cima de una colina en una carretera sin división si los conductores que vienen de cualquier dirección no pueden verlo a menos de 500 pies.","p":"Correcto. No donde no lo vean a menos de 500 pies."},"ref":{"doc":"SD","page":39}},{"id":"sd-137","scope":"SD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Dakota, may you make a U-turn in the middle of a block on a street in a business district?","o":["Yes, if you signal","Yes, any time","No, unless it is a divided street with a legal opening","Only at night"],"h1":"Business streets are busy with cars and people.","h2":"In South Dakota, U-turns are not allowed mid-block on a business district street, except on a divided street at a legal opening or crossover.","p":"Right. No mid-block U-turns in a business district."},"es":{"q":"En Dakota del Sur, ¿puede dar vuelta en U a mitad de cuadra en una calle de una zona comercial?","o":["Sí, si pone la direccional","Sí, en cualquier momento","No, salvo en una calle dividida con una abertura permitida","Solo de noche"],"h1":"Las calles comerciales están llenas de carros y gente.","h2":"En Dakota del Sur no se permiten vueltas en U a mitad de cuadra en una calle de zona comercial, salvo en una calle dividida en una abertura o cruce permitido.","p":"Correcto. Nada de vueltas en U a mitad de cuadra en zona comercial."},"ref":{"doc":"SD","page":39}},{"id":"sd-138","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, when should you use a three-point turnabout (Y-turn)?","o":["In a busy intersection","On any interstate","Whenever you miss a turn","When the street is too narrow for a U-turn and you cannot go around the block"],"h1":"It is a last choice on a narrow two-lane road.","h2":"The South Dakota manual says to use a three-point turnabout only on a two-lane road that is too narrow for a U-turn, when you cannot go around the block.","p":"Right. Only when a U-turn will not fit and going around the block is not possible."},"es":{"q":"En Dakota del Sur, ¿cuándo debe hacer una vuelta en tres puntos (vuelta en Y)?","o":["En una intersección con mucho tráfico","En cualquier interestatal","Siempre que se pase de una vuelta","Cuando la calle es muy angosta para una vuelta en U y no puede rodear la cuadra"],"h1":"Es la última opción en una vía angosta de dos carriles.","h2":"El manual de Dakota del Sur dice que use la vuelta en tres puntos solo en una vía de dos carriles muy angosta para una vuelta en U, cuando no pueda rodear la cuadra.","p":"Correcto. Solo cuando la vuelta en U no cabe y no puede rodear la cuadra."},"ref":{"doc":"SD","page":38}},{"id":"sd-139","scope":"SD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Dakota, what does the manual say about crossing the median of an interstate highway?","o":["You must not cross it","You may cross it to turn around","You may cross it at night","You may cross it if traffic is light"],"h1":"Use the next exit instead.","h2":"The South Dakota manual says you must not cross the median of an interstate highway; go on to the next exit instead.","p":"Right. Never cross the interstate median."},"es":{"q":"En Dakota del Sur, ¿qué dice el manual sobre cruzar el camellón (mediana) de una interestatal?","o":["No debe cruzarlo","Puede cruzarlo para dar la vuelta","Puede cruzarlo de noche","Puede cruzarlo si hay poco tráfico"],"h1":"Mejor use la siguiente salida.","h2":"El manual de Dakota del Sur dice que no debe cruzar el camellón de una interestatal; siga hasta la siguiente salida.","p":"Correcto. Nunca cruce el camellón de la interestatal."},"ref":{"doc":"SD","page":42}},{"id":"sd-140","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, at a Diverging Diamond Interchange (DDI), how do left turns onto the freeway work?","o":["You must always stop at a stop sign","They are free flow; you do not stop to reach the ramp","You must make a U-turn first","Left turns are not allowed"],"h1":"The design keeps these turns moving.","h2":"At a Diverging Diamond Interchange in South Dakota, all left turns onto the freeway are free flow, so vehicles do not stop to get onto the ramp.","p":"Right. Left turns onto the freeway flow freely."},"es":{"q":"En Dakota del Sur, en un intercambio de diamante divergente (DDI), ¿cómo funcionan las vueltas a la izquierda hacia la autopista?","o":["Siempre debe detenerse en un alto","Son de flujo libre; no se detiene para llegar a la rampa","Primero debe dar vuelta en U","No se permiten vueltas a la izquierda"],"h1":"El diseño mantiene estas vueltas en movimiento.","h2":"En un intercambio de diamante divergente en Dakota del Sur, todas las vueltas a la izquierda hacia la autopista son de flujo libre, así que los vehículos no se detienen para entrar a la rampa.","p":"Correcto. Las vueltas a la izquierda hacia la autopista fluyen libremente."},"ref":{"doc":"SD","page":42}},{"id":"sd-141","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, in very cold weather, when might you leave the parking brake off?","o":["Whenever you park on a hill","Never","When it could freeze in the on position","Only overnight in a garage"],"h1":"Ice can be a problem for the brake.","h2":"The South Dakota manual says that in cold weather, when the parking brake could freeze on, you may leave it off, but the car should still be left in park or the lowest gear.","p":"Right. When it might freeze on, but still leave the car in park or low gear."},"es":{"q":"En Dakota del Sur, con mucho frío, ¿cuándo podría dejar sin poner el freno de estacionamiento?","o":["Siempre que se estacione en una colina","Nunca","Cuando podría congelarse puesto","Solo de noche en un garaje"],"h1":"El hielo puede causar problemas con el freno.","h2":"El manual de Dakota del Sur dice que con frío, cuando el freno de estacionamiento podría congelarse puesto, puede dejarlo sin poner, pero el carro debe quedar en park o en la velocidad más baja.","p":"Correcto. Cuando podría congelarse, pero deje el carro en park o en primera."},"ref":{"doc":"SD","page":43}},{"id":"sd-142","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, you park on a rural highway after dark. Which lights must be on?","o":["Only the dome light","High beams","No lights","Parking lights and taillights"],"h1":"Other drivers need to see where your car is.","h2":"The South Dakota manual says that when you park on a rural highway in the dark, your parking lights and taillights must be on.","p":"Right. Parking lights and taillights on."},"es":{"q":"En Dakota del Sur, se estaciona en una carretera rural después de que oscurece. ¿Qué luces deben estar encendidas?","o":["Solo la luz interior","Las luces altas","Ninguna luz","Las luces de estacionamiento y las traseras"],"h1":"Los otros conductores necesitan ver dónde está su carro.","h2":"El manual de Dakota del Sur dice que cuando se estaciona en una carretera rural de noche, las luces de estacionamiento y las traseras deben estar encendidas.","p":"Correcto. Luces de estacionamiento y traseras encendidas."},"ref":{"doc":"SD","page":43}},{"id":"sd-143","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Sharply to the left, away from the curb","Sharply to the right, toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, the tire should catch the curb.","h2":"When parking uphill with a curb in South Dakota, turn the wheels sharply to the left so the car rolls back into the curb, not into traffic.","p":"Right. Uphill with a curb, turn the wheels left."},"es":{"q":"En Dakota del Sur, se estaciona cuesta arriba junto a la banqueta. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Bien a la izquierda, lejos de la banqueta","Bien a la derecha, hacia la banqueta","Derechas","No importa"],"h1":"Si el carro rueda hacia atrás, la llanta debe topar con la banqueta.","h2":"Al estacionarse cuesta arriba con banqueta en Dakota del Sur, gire las ruedas bien a la izquierda para que el carro ruede hacia la banqueta y no hacia el tráfico.","p":"Correcto. Cuesta arriba con banqueta, ruedas a la izquierda."},"ref":{"doc":"SD","page":43}},{"id":"sd-144","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, you park a manual-transmission car facing downhill. Which gear should you leave it in?","o":["First gear","Reverse","Neutral","Fifth gear"],"h1":"Choose the gear that pushes against rolling forward.","h2":"The South Dakota manual says to leave a manual-transmission car in reverse when parked downhill, and in the lowest gear when parked uphill, with the parking brake set.","p":"Right. Downhill, leave it in reverse."},"es":{"q":"En Dakota del Sur, estaciona un carro de transmisión manual cuesta abajo. ¿En qué velocidad debe dejarlo?","o":["Primera","Reversa","Neutral","Quinta"],"h1":"Elija la velocidad que se opone a rodar hacia adelante.","h2":"El manual de Dakota del Sur dice que deje un carro de transmisión manual en reversa al estacionarse cuesta abajo, y en la velocidad más baja cuesta arriba, con el freno de estacionamiento puesto.","p":"Correcto. Cuesta abajo, déjelo en reversa."},"ref":{"doc":"SD","page":43}},{"id":"sd-145","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, after parallel parking, how close to the curb or edge of the road should your car be?","o":["Within 24 inches","Within 3 feet","Within 12 inches","Touching the curb"],"h1":"It is about one foot.","h2":"The South Dakota manual says that after parallel parking your car should be within 12 inches of the curb and at least 2 feet from the parked cars.","p":"Right. Within 12 inches of the curb."},"es":{"q":"En Dakota del Sur, después de estacionarse en paralelo, ¿qué tan cerca de la banqueta o del borde de la vía debe quedar su carro?","o":["A 24 pulgadas o menos","A 3 pies o menos","A 12 pulgadas o menos","Tocando la banqueta"],"h1":"Es más o menos un pie.","h2":"El manual de Dakota del Sur dice que después de estacionarse en paralelo su carro debe quedar a 12 pulgadas o menos de la banqueta y a por lo menos 2 pies de los carros estacionados.","p":"Correcto. A 12 pulgadas o menos de la banqueta."},"ref":{"doc":"SD","page":44}},{"id":"sd-146","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, when you start to parallel park, how far from the car in the space ahead should you stop, side by side?","o":["About 10 feet","About 6 inches","About 5 feet","About 2 feet"],"h1":"Close, but with room so you do not scrape it.","h2":"The South Dakota manual says to stop even with the car in the space ahead and about 2 feet away from it before you start backing in.","p":"Right. About 2 feet away."},"es":{"q":"En Dakota del Sur, al empezar a estacionarse en paralelo, ¿a qué distancia del carro del espacio de adelante debe detenerse, uno al lado del otro?","o":["Unos 10 pies","Unas 6 pulgadas","Unos 5 pies","Unos 2 pies"],"h1":"Cerca, pero con espacio para no rasparlo.","h2":"El manual de Dakota del Sur dice que se detenga a la par del carro del espacio de adelante y a unos 2 pies de él antes de empezar a dar reversa.","p":"Correcto. A unos 2 pies."},"ref":{"doc":"SD","page":44}},{"id":"sd-147","scope":"SD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Dakota, may you pass another vehicle by driving on the shoulder?","o":["No, never, paved or not","Yes, if the shoulder is paved","Yes, if the car ahead is slow","Yes, on the right only"],"h1":"The shoulder is not a lane.","h2":"The South Dakota manual says never to pass on the shoulder, whether it is paved or not.","p":"Right. Never pass on the shoulder."},"es":{"q":"En Dakota del Sur, ¿puede rebasar a otro vehículo manejando por el acotamiento?","o":["No, nunca, esté pavimentado o no","Sí, si el acotamiento está pavimentado","Sí, si el carro de adelante va lento","Sí, solo por la derecha"],"h1":"El acotamiento no es un carril.","h2":"El manual de Dakota del Sur dice que nunca rebase por el acotamiento, esté pavimentado o no.","p":"Correcto. Nunca rebase por el acotamiento."},"ref":{"doc":"SD","page":46}},{"id":"sd-148","scope":"SD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Dakota, you pass a bicycle on a road with a speed limit of 35 mph or less. How much space must you leave?","o":["At least 1 foot","At least 3 feet","At least 6 feet","At least 10 feet"],"h1":"It is half the distance required on faster roads.","h2":"South Dakota law (SDCL 32-26-26.1) requires at least 3 feet when passing a bicycle where the limit is 35 mph or less, and 6 feet where it is higher.","p":"Right. At least 3 feet at 35 mph or less."},"es":{"q":"En Dakota del Sur, rebasa a una bicicleta en una vía con límite de 35 mph o menos. ¿Cuánto espacio debe dejar?","o":["Por lo menos 1 pie","Por lo menos 3 pies","Por lo menos 6 pies","Por lo menos 10 pies"],"h1":"Es la mitad de la distancia exigida en vías más rápidas.","h2":"La ley de Dakota del Sur (SDCL 32-26-26.1) exige por lo menos 3 pies al rebasar a una bicicleta donde el límite es 35 mph o menos, y 6 pies donde es mayor.","p":"Correcto. Por lo menos 3 pies a 35 mph o menos."},"ref":{"doc":"SD","page":46}},{"id":"sd-149","scope":"SD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Dakota, to give a bicycle enough room, may you partly cross the center line while passing it?","o":["Only on the interstate","No, never","Yes, if it can be done safely","Only if the cyclist waves you on"],"h1":"The bicycle law allows it under one condition.","h2":"South Dakota law lets a driver partly cross the center line or lane line to pass a bicycle, as long as it can be done safely.","p":"Right. Yes, when it is safe."},"es":{"q":"En Dakota del Sur, para dar suficiente espacio a una bicicleta, ¿puede cruzar en parte la línea central al rebasarla?","o":["Solo en la interestatal","No, nunca","Sí, si se puede hacer con seguridad","Solo si el ciclista le hace señas"],"h1":"La ley de bicicletas lo permite con una condición.","h2":"La ley de Dakota del Sur permite cruzar en parte la línea central o la línea de carril para rebasar a una bicicleta, siempre que se pueda hacer con seguridad.","p":"Correcto. Sí, cuando es seguro."},"ref":{"doc":"SD","page":46}},{"id":"sd-150","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, a police car with lights on is behind you. How does the manual say to show the officer you see them?","o":["Honk twice","Flash your high beams","Wave out the window","Turn on your right turn signal"],"h1":"Use a signal that also shows where you are going.","h2":"The South Dakota manual says to turn on your right turn signal to let the officer know you see them, then move to the right shoulder.","p":"Right. Turn on your right turn signal."},"es":{"q":"En Dakota del Sur, una patrulla con las luces encendidas va detrás de usted. ¿Cómo dice el manual que le muestre al oficial que lo vio?","o":["Tocando el claxon dos veces","Con las luces altas","Saludando por la ventana","Encendiendo la direccional derecha"],"h1":"Use una señal que también muestre hacia dónde va.","h2":"El manual de Dakota del Sur dice que encienda la direccional derecha para que el oficial sepa que lo vio, y luego vaya al acotamiento derecho.","p":"Correcto. Encienda la direccional derecha."},"ref":{"doc":"SD","page":46}},{"id":"sd-151","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, you are pulled over and your car has tinted windows. What does the manual recommend?","o":["Roll down your windows before the officer reaches you","Keep the windows up","Get out and walk to the officer","Turn on the radio"],"h1":"The officer needs to see inside.","h2":"The South Dakota manual recommends rolling down tinted windows after you stop on the right shoulder and before the officer comes to your car.","p":"Right. Roll down tinted windows."},"es":{"q":"En Dakota del Sur, lo detiene la policía y su carro tiene ventanas polarizadas. ¿Qué recomienda el manual?","o":["Bajar las ventanas antes de que llegue el oficial","Dejar las ventanas cerradas","Bajarse y caminar hacia el oficial","Encender la radio"],"h1":"El oficial necesita ver adentro.","h2":"El manual de Dakota del Sur recomienda bajar las ventanas polarizadas después de detenerse en el acotamiento derecho y antes de que el oficial llegue a su carro.","p":"Correcto. Baje las ventanas polarizadas."},"ref":{"doc":"SD","page":47}},{"id":"sd-152","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, how far ahead of your car does the manual say you should ideally look?","o":["2 to 3 seconds","20 to 30 seconds","5 seconds","1 minute"],"h1":"It is much farther than the car just in front of you.","h2":"The South Dakota manual says you should ideally look 20 to 30 seconds ahead of your car.","p":"Right. Look 20 to 30 seconds ahead."},"es":{"q":"En Dakota del Sur, ¿qué tan lejos delante de su carro dice el manual que debería mirar idealmente?","o":["De 2 a 3 segundos","De 20 a 30 segundos","5 segundos","1 minuto"],"h1":"Es mucho más lejos que el carro que va justo adelante.","h2":"El manual de Dakota del Sur dice que idealmente debe mirar de 20 a 30 segundos delante de su carro.","p":"Correcto. Mire de 20 a 30 segundos adelante."},"ref":{"doc":"SD","page":48}},{"id":"sd-153","scope":"SD","cat":"signals","sign":null,"c":2,"en":{"q":"In South Dakota, at higher speeds, how early does the manual say it is better to signal before a turn?","o":["As you begin to turn","1 second before","At least 4 to 5 seconds before","Half a mile before"],"h1":"The legal minimum is 100 feet, but more time helps at speed.","h2":"The South Dakota manual says that at higher speeds it is better to signal at least 4 to 5 seconds before you turn, not just the 100-foot minimum.","p":"Right. Signal at least 4 to 5 seconds ahead at speed."},"es":{"q":"En Dakota del Sur, a velocidades más altas, ¿con cuánta anticipación dice el manual que es mejor poner la direccional antes de dar vuelta?","o":["Al empezar a dar vuelta","1 segundo antes","Por lo menos 4 a 5 segundos antes","Media milla antes"],"h1":"El mínimo legal es 100 pies, pero más tiempo ayuda a mayor velocidad.","h2":"El manual de Dakota del Sur dice que a velocidades más altas es mejor señalar por lo menos 4 a 5 segundos antes de dar vuelta, no solo el mínimo de 100 pies.","p":"Correcto. Señale por lo menos 4 a 5 segundos antes a mayor velocidad."},"ref":{"doc":"SD","page":49}},{"id":"sd-154","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, at what times of day are deer most active?","o":["Late morning","Noon","Mid-afternoon","Dusk and dawn"],"h1":"Think of when the light is low.","h2":"The South Dakota manual says deer are most active at dusk and dawn, so watch the roadsides for the shine of your headlights in their eyes.","p":"Right. Dusk and dawn."},"es":{"q":"En Dakota del Sur, ¿a qué horas del día están más activos los venados?","o":["A media mañana","Al mediodía","A media tarde","Al atardecer y al amanecer"],"h1":"Piense en cuando hay poca luz.","h2":"El manual de Dakota del Sur dice que los venados están más activos al atardecer y al amanecer, así que vigile los lados del camino por el brillo de sus faros en sus ojos.","p":"Correcto. Al atardecer y al amanecer."},"ref":{"doc":"SD","page":50}},{"id":"sd-155","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, about how long is the average perception time for an alert driver, according to the manual?","o":["3/4 second to 1 second","3 to 4 seconds","1/10 of a second","5 seconds"],"h1":"It is about the same as the average reaction time.","h2":"The South Dakota manual says the average perception time for an alert driver is 3/4 of a second to 1 second.","p":"Right. About 3/4 second to 1 second."},"es":{"q":"En Dakota del Sur, según el manual, ¿cuánto dura más o menos el tiempo de percepción de un conductor alerta?","o":["De 3/4 de segundo a 1 segundo","De 3 a 4 segundos","1/10 de segundo","5 segundos"],"h1":"Es más o menos igual que el tiempo promedio de reacción.","h2":"El manual de Dakota del Sur dice que el tiempo de percepción promedio de un conductor alerta es de 3/4 de segundo a 1 segundo.","p":"Correcto. De 3/4 de segundo a 1 segundo."},"ref":{"doc":"SD","page":50}},{"id":"sd-156","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, about how far does the manual say it can take to brake to a stop from 50 mph on dry pavement?","o":["About 30 feet","About 158 feet","About 60 feet","About 500 feet"],"h1":"It is longer than half a football field.","h2":"The South Dakota manual says braking from 50 mph on dry pavement with good brakes can take about 158 feet, not counting perception and reaction time.","p":"Right. About 158 feet of braking."},"es":{"q":"En Dakota del Sur, ¿cuánta distancia dice el manual que puede tomar frenar hasta detenerse a 50 mph en pavimento seco?","o":["Unos 30 pies","Unos 158 pies","Unos 60 pies","Unos 500 pies"],"h1":"Es más de la mitad de un campo de fútbol americano.","h2":"El manual de Dakota del Sur dice que frenar desde 50 mph en pavimento seco con buenos frenos puede tomar unos 158 pies, sin contar el tiempo de percepción y de reacción.","p":"Correcto. Unos 158 pies de frenado."},"ref":{"doc":"SD","page":50}},{"id":"sd-157","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, how far back can the blind spot behind a large truck reach?","o":["About 50 feet","About 10 feet","Up to 200 feet","Up to one mile"],"h1":"It is longer than most city blocks are wide.","h2":"The South Dakota manual says the blind spot behind a large truck can reach up to 200 feet, so the driver may not know you are there.","p":"Right. Up to 200 feet behind."},"es":{"q":"En Dakota del Sur, ¿hasta qué distancia hacia atrás puede llegar el punto ciego de un camión grande?","o":["Unos 50 pies","Unos 10 pies","Hasta 200 pies","Hasta una milla"],"h1":"Es más largo de lo que mide el ancho de muchas cuadras.","h2":"El manual de Dakota del Sur dice que el punto ciego detrás de un camión grande puede llegar hasta 200 pies, así que el conductor quizá no sepa que usted está ahí.","p":"Correcto. Hasta 200 pies atrás."},"ref":{"doc":"SD","page":51}},{"id":"sd-158","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, how far does the manual say you must be able to see ahead to pass safely at 55 mph on a two-lane road?","o":["Five miles","About 100 feet","About 500 feet","About one-third of a mile (over 1,600 feet)"],"h1":"At 55 mph, a pass takes about 10 seconds, and the other car is moving too.","h2":"The South Dakota manual says passing at 55 mph takes about 10 seconds, so you need over 1,600 feet, about one-third of a mile, of clear road ahead.","p":"Right. About one-third of a mile."},"es":{"q":"En Dakota del Sur, ¿qué tan lejos dice el manual que debe poder ver hacia adelante para rebasar con seguridad a 55 mph en una vía de dos carriles?","o":["Cinco millas","Unos 100 pies","Unos 500 pies","Más o menos un tercio de milla (más de 1,600 pies)"],"h1":"A 55 mph rebasar toma unos 10 segundos, y el otro carro también avanza.","h2":"El manual de Dakota del Sur dice que rebasar a 55 mph toma unos 10 segundos, así que necesita más de 1,600 pies, más o menos un tercio de milla, de vía libre adelante.","p":"Correcto. Más o menos un tercio de milla."},"ref":{"doc":"SD","page":53}},{"id":"sd-159","scope":"SD","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In South Dakota, how long can a multiple-trailer truck be, compared with a typical 15-foot car?","o":["75 feet or longer","20 feet","30 feet","40 feet"],"h1":"It is about five cars long.","h2":"The South Dakota manual says a typical car is 15 feet long, while a multiple-trailer truck can be 75 feet long or longer, so it takes much longer to pass.","p":"Right. 75 feet or longer."},"es":{"q":"En Dakota del Sur, ¿cuánto puede medir un camión de varios remolques, comparado con un carro típico de 15 pies?","o":["75 pies o más","20 pies","30 pies","40 pies"],"h1":"Es como cinco carros de largo.","h2":"El manual de Dakota del Sur dice que un carro típico mide 15 pies, mientras que un camión de varios remolques puede medir 75 pies o más, así que tarda mucho más en rebasarlo.","p":"Correcto. 75 pies o más."},"ref":{"doc":"SD","page":53}},{"id":"sd-160","scope":"SD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Dakota, after passing a car, when does the manual say it is safe to return to your lane?","o":["As soon as your front bumper is past it","When you can see both of its headlights in your rearview mirror","After you count to one","When the other driver honks"],"h1":"Use your inside mirror to check.","h2":"The South Dakota manual says it is safe to move back into the driving lane when you can see both headlights of the car you passed in your rearview mirror.","p":"Right. When both headlights show in your rearview mirror."},"es":{"q":"En Dakota del Sur, después de rebasar a un carro, ¿cuándo dice el manual que es seguro volver a su carril?","o":["En cuanto su defensa delantera lo pase","Cuando pueda ver sus dos faros en el espejo retrovisor","Después de contar hasta uno","Cuando el otro conductor toque el claxon"],"h1":"Use el espejo de adentro para revisar.","h2":"El manual de Dakota del Sur dice que es seguro volver al carril cuando pueda ver los dos faros del carro que rebasó en su espejo retrovisor.","p":"Correcto. Cuando vea los dos faros en el retrovisor."},"ref":{"doc":"SD","page":53}},{"id":"sd-161","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, how much farther does the manual say high beams let you see compared with low beams?","o":["Four times as far","The same distance","Twice as far","Ten times as far"],"h1":"Think of double.","h2":"The South Dakota manual says high beams let you see twice as far as low beams, so use them when no vehicles are coming toward you.","p":"Right. High beams let you see twice as far."},"es":{"q":"En Dakota del Sur, ¿cuánto más lejos dice el manual que se ve con las luces altas que con las bajas?","o":["Cuatro veces más","La misma distancia","El doble","Diez veces más"],"h1":"Piense en el doble.","h2":"El manual de Dakota del Sur dice que con las luces altas se ve el doble de lejos que con las bajas, así que úselas cuando no vengan vehículos de frente.","p":"Correcto. Las luces altas permiten ver el doble."},"ref":{"doc":"SD","page":55}},{"id":"sd-162","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, the manual gives a simple rule for rain or snow. When should you turn on your headlights?","o":["Only in heavy fog","Only after sunset","Only on the interstate","Whenever you turn on your wipers"],"h1":"It links two switches in your car.","h2":"The South Dakota manual says a good rule is: if you turn on the wipers, turn on the headlights.","p":"Right. Wipers on, headlights on."},"es":{"q":"En Dakota del Sur, el manual da una regla sencilla para la lluvia o la nieve. ¿Cuándo debe encender los faros?","o":["Solo con niebla espesa","Solo después de la puesta del sol","Solo en la interestatal","Siempre que encienda los limpiaparabrisas"],"h1":"Une dos interruptores de su carro.","h2":"El manual de Dakota del Sur dice que una buena regla es: si enciende los limpiaparabrisas, encienda los faros.","p":"Correcto. Limpiaparabrisas encendidos, faros encendidos."},"ref":{"doc":"SD","page":54}},{"id":"sd-163","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, you are driving away from a rising or setting sun. Why does the manual say to turn on your headlights?","o":["Drivers coming toward you face glare and may not see you","It makes your car warmer","It is required only for trucks","It helps you read signs"],"h1":"Think of the drivers facing the sun.","h2":"The South Dakota manual says to turn on your headlights when driving away from a rising or setting sun, because oncoming drivers face glare and the lights help them see you.","p":"Right. Oncoming drivers face glare and need to see you."},"es":{"q":"En Dakota del Sur, usted maneja de espaldas al sol que sale o se pone. ¿Por qué dice el manual que encienda los faros?","o":["Los conductores que vienen de frente tienen el sol encima y quizá no lo vean","Calienta su carro","Solo se exige a los camiones","Le ayuda a leer letreros"],"h1":"Piense en los conductores que miran hacia el sol.","h2":"El manual de Dakota del Sur dice que encienda los faros al manejar de espaldas al sol que sale o se pone, porque los conductores de frente tienen deslumbramiento y las luces les ayudan a verlo.","p":"Correcto. Los que vienen de frente tienen deslumbramiento y necesitan verlo."},"ref":{"doc":"SD","page":54}},{"id":"sd-164","scope":"SD","cat":"signals","sign":null,"c":1,"en":{"q":"In South Dakota, near which of these does the manual say NOT to use your horn?","o":["A driver drifting into your lane","A blind pedestrian","A child about to run into the street","A blind curve on a narrow road"],"h1":"A sudden loud noise could confuse someone who cannot see.","h2":"The South Dakota manual says not to use the horn around blind pedestrians, or around animals and animal-drawn vehicles.","p":"Right. Do not honk around blind pedestrians."},"es":{"q":"En Dakota del Sur, ¿cerca de cuál de estos dice el manual que NO use el claxon?","o":["Un conductor que se mete a su carril","Un peatón ciego","Un niño a punto de correr a la calle","Una curva cerrada sin visibilidad en una vía angosta"],"h1":"Un ruido fuerte y repentino podría confundir a alguien que no ve.","h2":"El manual de Dakota del Sur dice que no use el claxon cerca de peatones ciegos, ni cerca de animales o vehículos tirados por animales.","p":"Correcto. No toque el claxon cerca de peatones ciegos."},"ref":{"doc":"SD","page":55}},{"id":"sd-165","scope":"SD","cat":"signals","sign":null,"c":2,"en":{"q":"In South Dakota, you are going to slow down where drivers behind you would not expect it. What does the manual suggest?","o":["Wave your arm up and down","Turn on your high beams","Tap the brake pedal 3 or 4 times","Turn on the dome light"],"h1":"Your brake lights can flash a warning.","h2":"The South Dakota manual says to quickly tap the brake pedal 3 or 4 times to warn drivers behind you that you are about to slow down.","p":"Right. Tap the brakes 3 or 4 times."},"es":{"q":"En Dakota del Sur, va a bajar la velocidad donde los conductores de atrás no lo esperan. ¿Qué sugiere el manual?","o":["Mover el brazo de arriba abajo","Encender las luces altas","Tocar el pedal del freno 3 o 4 veces","Encender la luz interior"],"h1":"Las luces de freno pueden dar un aviso con destellos.","h2":"El manual de Dakota del Sur dice que toque rápido el pedal del freno 3 o 4 veces para avisar a los de atrás que va a bajar la velocidad.","p":"Correcto. Toque el freno 3 o 4 veces."},"ref":{"doc":"SD","page":56}},{"id":"sd-166","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, your car breaks down on the highway. How far behind it does the manual say to place emergency flares?","o":["About one mile","About 10 feet","About 50 feet","About 200 to 300 feet"],"h1":"Far enough to give drivers time to change lanes.","h2":"The South Dakota manual says to place emergency flares about 200 to 300 feet behind a disabled vehicle so other drivers have time to change lanes.","p":"Right. About 200 to 300 feet behind."},"es":{"q":"En Dakota del Sur, su carro se descompone en la carretera. ¿A qué distancia detrás dice el manual que ponga las bengalas de emergencia?","o":["A una milla","A unos 10 pies","A unos 50 pies","A unos 200 a 300 pies"],"h1":"Lo bastante lejos para que los conductores tengan tiempo de cambiar de carril.","h2":"El manual de Dakota del Sur dice que ponga las bengalas de emergencia a unos 200 a 300 pies detrás de un vehículo descompuesto para que los demás tengan tiempo de cambiar de carril.","p":"Correcto. A unos 200 a 300 pies detrás."},"ref":{"doc":"SD","page":58}},{"id":"sd-167","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, your engine shuts off while you are driving. What does the manual say about steering?","o":["It may be hard to turn, but you can still turn it","It locks completely","It becomes easier","You should let go of it"],"h1":"Power steering stops helping, but the wheel still works.","h2":"The South Dakota manual says that if the engine dies, the steering wheel may be hard to turn, but you can still turn it; keep a firm grip and pull off the road.","p":"Right. Hard to turn, but it still turns."},"es":{"q":"En Dakota del Sur, el motor se apaga mientras maneja. ¿Qué dice el manual sobre el volante?","o":["Puede costar girarlo, pero todavía se puede","Se bloquea por completo","Se vuelve más fácil","Debe soltarlo"],"h1":"La dirección hidráulica deja de ayudar, pero el volante sigue funcionando.","h2":"El manual de Dakota del Sur dice que si el motor se apaga, puede costar girar el volante, pero todavía se puede; sujételo firme y salga de la vía.","p":"Correcto. Cuesta girarlo, pero todavía gira."},"ref":{"doc":"SD","page":58}},{"id":"sd-168","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, your car is about to be hit from behind. What does the manual say to do?","o":["Lean forward toward the wheel","Press back against your seat with your head on the head restraint","Unbuckle your seat belt","Turn around to look"],"h1":"Your body will be thrown backward.","h2":"The South Dakota manual says that if you are hit from the rear, press yourself against the seat back, put your head against the head restraint, and be ready to brake.","p":"Right. Press back with your head on the restraint."},"es":{"q":"En Dakota del Sur, están a punto de chocarlo por detrás. ¿Qué dice el manual que haga?","o":["Inclinarse hacia el volante","Apoyarse contra el respaldo con la cabeza en el cabezal","Quitarse el cinturón","Voltear a mirar"],"h1":"Su cuerpo será lanzado hacia atrás.","h2":"El manual de Dakota del Sur dice que si lo chocan por detrás, se apoye contra el respaldo, ponga la cabeza contra el cabezal y esté listo para frenar.","p":"Correcto. Apóyese atrás con la cabeza en el cabezal."},"ref":{"doc":"SD","page":59}},{"id":"sd-169","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, a crash from the front cannot be avoided. What does the manual say to try for?","o":["Closing your eyes","Speeding up to hit harder","A glancing blow instead of a head-on hit","Taking your hands off the wheel"],"h1":"Turning even a little can help.","h2":"The South Dakota manual says that if a front crash is coming, try to turn the car so you get a glancing blow rather than a head-on hit.","p":"Right. Try for a glancing blow."},"es":{"q":"En Dakota del Sur, no puede evitar un choque de frente. ¿Qué dice el manual que intente?","o":["Cerrar los ojos","Acelerar para golpear más fuerte","Un golpe de lado en vez de un choque de frente","Soltar el volante"],"h1":"Girar aunque sea un poco puede ayudar.","h2":"El manual de Dakota del Sur dice que si viene un choque de frente, trate de girar el carro para que el golpe sea de lado y no de frente.","p":"Correcto. Busque un golpe de lado."},"ref":{"doc":"SD","page":59}},{"id":"sd-170","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, you stop to help at a crash. Several people are hurt. Whom does the manual say to help first?","o":["The driver who caused it","Whoever is shouting the loudest","The person standing up","Anyone who is not walking and talking"],"h1":"People who cannot walk or talk may be hurt the worst.","h2":"The South Dakota manual says to help first anyone who is not already walking and talking: check for breathing, then for bleeding.","p":"Right. First help those not walking and talking."},"es":{"q":"En Dakota del Sur, se detiene a ayudar en un choque. Hay varias personas heridas. ¿A quién dice el manual que ayude primero?","o":["Al conductor que lo causó","A quien grita más fuerte","A la persona que está de pie","A quien no esté caminando ni hablando"],"h1":"Quienes no pueden caminar ni hablar pueden estar más graves.","h2":"El manual de Dakota del Sur dice que primero ayude a quien no esté caminando ni hablando: revise si respira y luego si sangra.","p":"Correcto. Primero ayude a quien no camina ni habla."},"ref":{"doc":"SD","page":59}},{"id":"sd-171","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, an injured person at a crash asks for water. What does the manual say?","o":["Do not give injured people anything to drink, not even water","Give them small sips of water","Give them coffee to stay awake","Give them any drink they want"],"h1":"The manual is firm about this.","h2":"The South Dakota manual says not to give injured persons anything to drink, not even water; keep them warm to help prevent shock.","p":"Right. Nothing to drink, not even water."},"es":{"q":"En Dakota del Sur, una persona herida en un choque pide agua. ¿Qué dice el manual?","o":["No dé nada de tomar a los heridos, ni siquiera agua","Dele pequeños sorbos de agua","Dele café para que no se duerma","Dele lo que quiera tomar"],"h1":"El manual es firme en esto.","h2":"El manual de Dakota del Sur dice que no dé nada de tomar a los heridos, ni siquiera agua; manténgalos abrigados para ayudar a evitar el choque (shock).","p":"Correcto. Nada de tomar, ni siquiera agua."},"ref":{"doc":"SD","page":59}},{"id":"sd-172","scope":"SD","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In South Dakota, according to the manual, which violation is the number one cause of injury and fatal crashes?","o":["Speeding on the interstate","Careless driving","Driving without insurance","Parking violations"],"h1":"It is a lack of care and attention.","h2":"The South Dakota manual ranks careless driving as the top violation causing injury and fatal crashes in the state.","p":"Right. Careless driving ranks first."},"es":{"q":"En Dakota del Sur, según el manual, ¿qué infracción es la causa número uno de choques con heridos y muertos?","o":["El exceso de velocidad en la interestatal","Manejar sin cuidado","Manejar sin seguro","Las infracciones de estacionamiento"],"h1":"Es falta de cuidado y atención.","h2":"El manual de Dakota del Sur pone el manejo sin cuidado como la principal infracción que causa choques con heridos y muertos en el estado.","p":"Correcto. Manejar sin cuidado está en primer lugar."},"ref":{"doc":"SD","page":60}},{"id":"sd-173","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, according to the manual, which violation ranks second as a cause of injury and fatal crashes?","o":["Reckless driving","Improper turn","Following too closely","Emerging from an alley"],"h1":"It is about the space in front of you.","h2":"The South Dakota manual ranks following too closely second among violations causing injury and fatal crashes, right after careless driving.","p":"Right. Following too closely ranks second."},"es":{"q":"En Dakota del Sur, según el manual, ¿qué infracción está en segundo lugar como causa de choques con heridos y muertos?","o":["Manejar de forma temeraria","Dar vuelta de forma indebida","Seguir muy de cerca","Salir de un callejón"],"h1":"Se trata del espacio delante de usted.","h2":"El manual de Dakota del Sur pone seguir muy de cerca en segundo lugar entre las infracciones que causan choques con heridos y muertos, justo después del manejo sin cuidado.","p":"Correcto. Seguir muy de cerca está en segundo lugar."},"ref":{"doc":"SD","page":60}},{"id":"sd-174","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, a pedestrian with a white cane or a guide dog is crossing the street. What must you do?","o":["Keep going if you have a green light","Slow down and go around","Honk so they know you are there","Come to a complete stop"],"h1":"Always give way to people who are visually impaired.","h2":"The South Dakota manual says to always yield to people who are visually impaired and come to a complete stop when a pedestrian with a guide dog or white cane is crossing.","p":"Right. Come to a complete stop."},"es":{"q":"En Dakota del Sur, un peatón con bastón blanco o perro guía está cruzando la calle. ¿Qué debe hacer?","o":["Seguir si tiene luz verde","Bajar la velocidad y rodearlo","Tocar el claxon para que sepa que está ahí","Detenerse por completo"],"h1":"Siempre ceda el paso a las personas con discapacidad visual.","h2":"El manual de Dakota del Sur dice que siempre ceda el paso a las personas con discapacidad visual y se detenga por completo cuando un peatón con perro guía o bastón blanco está cruzando.","p":"Correcto. Deténgase por completo."},"ref":{"doc":"SD","page":61}},{"id":"sd-175","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, when may you drive in a marked bicycle lane?","o":["Only to enter or leave an alley or driveway, or in an emergency or when directed by police","Whenever traffic is slow","To pass a car turning left","To park for a minute"],"h1":"Bike lanes are for bikes, with a few exceptions.","h2":"The South Dakota manual says not to stop, park or drive in a bicycle lane unless you are entering or leaving an alley or driveway, on official duty, directed by police, or in an emergency.","p":"Right. Only for those few exceptions."},"es":{"q":"En Dakota del Sur, ¿cuándo puede manejar en un carril marcado para bicicletas?","o":["Solo para entrar o salir de un callejón o entrada, en una emergencia o si la policía lo indica","Siempre que el tráfico esté lento","Para rebasar a un carro que da vuelta a la izquierda","Para estacionarse un minuto"],"h1":"Los carriles para bicicletas son para bicicletas, con pocas excepciones.","h2":"El manual de Dakota del Sur dice que no se detenga, estacione ni maneje en un carril para bicicletas salvo para entrar o salir de un callejón o entrada, en servicio oficial, por orden de la policía o en una emergencia.","p":"Correcto. Solo en esas pocas excepciones."},"ref":{"doc":"SD","page":61}},{"id":"sd-176","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, how much of a traffic lane does a motorcycle have the right to use?","o":["Half a lane","A full lane width","Only the right edge","Only the shoulder"],"h1":"Do not share the lane.","h2":"The South Dakota manual says to allow a motorcyclist a full lane width and not to share the lane with a motorcycle.","p":"Right. A motorcycle gets a full lane."},"es":{"q":"En Dakota del Sur, ¿cuánto de un carril tiene derecho a usar una motocicleta?","o":["Medio carril","Todo el ancho del carril","Solo la orilla derecha","Solo el acotamiento"],"h1":"No comparta el carril.","h2":"El manual de Dakota del Sur dice que deje a la motocicleta todo el ancho del carril y no comparta el carril con ella.","p":"Correcto. La motocicleta tiene derecho a todo el carril."},"ref":{"doc":"SD","page":62}},{"id":"sd-177","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, on which side does a large truck have its bigger side blind spot?","o":["Directly on the roof","The left side, in front of the cab","The right side, behind the cab","There is no difference"],"h1":"It is the side away from the driver.","h2":"The South Dakota manual says trucks have a larger blind spot on their right side, starting behind the cab and reaching up to the length of the truck.","p":"Right. The right side is the bigger blind spot."},"es":{"q":"En Dakota del Sur, ¿de qué lado tiene un camión grande el punto ciego lateral más grande?","o":["Justo sobre el techo","Del lado izquierdo, frente a la cabina","Del lado derecho, detrás de la cabina","No hay diferencia"],"h1":"Es el lado contrario al conductor.","h2":"El manual de Dakota del Sur dice que los camiones tienen un punto ciego más grande del lado derecho, que empieza detrás de la cabina y puede llegar a todo el largo del camión.","p":"Correcto. El lado derecho tiene el punto ciego más grande."},"ref":{"doc":"SD","page":63}},{"id":"sd-178","scope":"SD","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In South Dakota, why does the manual suggest avoiding the right lane near truck weigh stations?","o":["The speed limit is higher there","The right lane is closed there","Cars must stop at weigh stations","Large trucks will be trying to re-enter faster traffic there"],"h1":"Think of trucks coming back onto the highway.","h2":"The South Dakota manual suggests avoiding the right lane near weigh stations and on steep hills, where large trucks move slowly or try to re-enter faster traffic.","p":"Right. Trucks are re-entering traffic there."},"es":{"q":"En Dakota del Sur, ¿por qué sugiere el manual evitar el carril derecho cerca de las básculas para camiones?","o":["El límite de velocidad es más alto ahí","El carril derecho está cerrado ahí","Los carros deben detenerse en las básculas","Los camiones grandes intentan volver al tráfico más rápido ahí"],"h1":"Piense en los camiones que vuelven a la carretera.","h2":"El manual de Dakota del Sur sugiere evitar el carril derecho cerca de las básculas y en las cuestas empinadas, donde los camiones grandes van lento o intentan volver al tráfico más rápido.","p":"Correcto. Los camiones vuelven al tráfico ahí."},"ref":{"doc":"SD","page":63}},{"id":"sd-179","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, you see smoke coming from the brakes of a truck on a long downhill. What may it mean?","o":["The truck may be a runaway that cannot stop","The truck is about to park","The truck is low on fuel","Nothing, it is normal"],"h1":"Hot brakes can fail.","h2":"The South Dakota manual says smoke from a truck's or bus's brakes can mean it is a runaway, so get out of the way and do not get in front of it.","p":"Right. It may be a runaway truck."},"es":{"q":"En Dakota del Sur, ve humo saliendo de los frenos de un camión en una bajada larga. ¿Qué puede significar?","o":["Que el camión puede ir sin frenos y no puede detenerse","Que el camión va a estacionarse","Que le queda poca gasolina","Nada, es normal"],"h1":"Los frenos calientes pueden fallar.","h2":"El manual de Dakota del Sur dice que el humo de los frenos de un camión o autobús puede significar que va sin control, así que quítese del camino y no se ponga delante.","p":"Correcto. Puede ser un camión sin frenos."},"ref":{"doc":"SD","page":64}},{"id":"sd-180","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, how far in front of a truck's cab can a car disappear from the truck driver's view?","o":["Up to 2 feet","Up to 20 feet","Up to 100 feet","Up to 300 feet"],"h1":"It is a little more than a car length.","h2":"The South Dakota manual says a car can disappear from a truck driver's view when it is up to 20 feet in front of the cab.","p":"Right. Up to 20 feet in front of the cab."},"es":{"q":"En Dakota del Sur, ¿hasta qué distancia frente a la cabina de un camión puede un carro desaparecer de la vista del camionero?","o":["Hasta 2 pies","Hasta 20 pies","Hasta 100 pies","Hasta 300 pies"],"h1":"Es un poco más que el largo de un carro.","h2":"El manual de Dakota del Sur dice que un carro puede desaparecer de la vista del camionero cuando está hasta 20 pies frente a la cabina.","p":"Correcto. Hasta 20 pies frente a la cabina."},"ref":{"doc":"SD","page":56}},{"id":"sd-181","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, you are pulled over by police at night. What does the manual say to turn on inside the car?","o":["The heater","The radio","The interior lights","The high beams"],"h1":"It helps the officer see that everything is in order.","h2":"The South Dakota manual says that during a night traffic stop you should turn on the interior lights, turn off the engine, and turn on the hazard flashers.","p":"Right. Turn on the interior lights."},"es":{"q":"En Dakota del Sur, la policía lo detiene de noche. ¿Qué dice el manual que encienda dentro del carro?","o":["La calefacción","La radio","Las luces interiores","Las luces altas"],"h1":"Ayuda al oficial a ver que todo está en orden.","h2":"El manual de Dakota del Sur dice que en una parada de tránsito de noche encienda las luces interiores, apague el motor y encienda las luces intermitentes.","p":"Correcto. Encienda las luces interiores."},"ref":{"doc":"SD","page":64}},{"id":"sd-182","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, why must you pass farm machinery with extra care?","o":["Farm machines go faster than cars","Farm machines always turn right","Farm machines have the right to the whole road","The operator cannot hear vehicles coming up behind"],"h1":"Think about the noise of a tractor or combine.","h2":"The South Dakota manual says to pass farm machinery with caution because the operator cannot hear vehicles approaching.","p":"Right. The operator cannot hear you coming."},"es":{"q":"En Dakota del Sur, ¿por qué debe rebasar la maquinaria agrícola con mucho cuidado?","o":["Las máquinas agrícolas van más rápido que los carros","Las máquinas agrícolas siempre dan vuelta a la derecha","Las máquinas agrícolas tienen derecho a toda la vía","El operador no oye los vehículos que vienen detrás"],"h1":"Piense en el ruido de un tractor o una cosechadora.","h2":"El manual de Dakota del Sur dice que rebase la maquinaria agrícola con cuidado porque el operador no oye los vehículos que se acercan.","p":"Correcto. El operador no lo oye venir."},"ref":{"doc":"SD","page":65}},{"id":"sd-183","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, how much should you add to your following distance on unfamiliar roads at night?","o":["At least two extra seconds","Nothing","Half a second","Ten extra seconds"],"h1":"At night on any road, add at least one second; unfamiliar roads need more.","h2":"The South Dakota manual says to add at least one second to your following distance at night, and at least two seconds on unfamiliar roads at night.","p":"Right. At least two extra seconds."},"es":{"q":"En Dakota del Sur, ¿cuánto debe agregar a su distancia de seguimiento en vías desconocidas de noche?","o":["Por lo menos dos segundos más","Nada","Medio segundo","Diez segundos más"],"h1":"De noche en cualquier vía, agregue por lo menos un segundo; en vías desconocidas, más.","h2":"El manual de Dakota del Sur dice que agregue por lo menos un segundo a su distancia de seguimiento de noche, y por lo menos dos segundos en vías desconocidas de noche.","p":"Correcto. Por lo menos dos segundos más."},"ref":{"doc":"SD","page":66}},{"id":"sd-184","scope":"SD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Dakota, in winter, what does the manual say posted speed limits are meant for?","o":["Snowy roads","Summer months on dry pavement","Icy bridges","Nighttime only"],"h1":"In snow you should drive well below the limit.","h2":"The South Dakota manual says posted limits are intended for summer months on dry pavement, so in winter you should drive well below them.","p":"Right. They are meant for dry summer roads."},"es":{"q":"En Dakota del Sur, en invierno, ¿para qué dice el manual que son los límites de velocidad indicados?","o":["Para vías con nieve","Para los meses de verano con pavimento seco","Para puentes con hielo","Solo para la noche"],"h1":"Con nieve debe manejar muy por debajo del límite.","h2":"El manual de Dakota del Sur dice que los límites indicados son para los meses de verano con pavimento seco, así que en invierno maneje muy por debajo de ellos.","p":"Correcto. Son para vías secas de verano."},"ref":{"doc":"SD","page":67}},{"id":"sd-185","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, you drive on a road that is closed for a snowstorm and get stuck. What can happen?","o":["You get a free tow","Nothing, rescue is always free","You may be ticketed and charged for rescue costs","Your license is automatically renewed"],"h1":"Closed roads are closed for a reason.","h2":"The South Dakota manual says that if you drive on a closed road and get stuck, help may be slow to reach you, and you could be ticketed and held responsible for rescue costs.","p":"Right. A ticket and rescue costs are possible."},"es":{"q":"En Dakota del Sur, maneja por una vía cerrada por una tormenta de nieve y se queda atascado. ¿Qué puede pasar?","o":["Le dan una grúa gratis","Nada, el rescate siempre es gratis","Le pueden poner una multa y cobrarle el costo del rescate","Le renuevan la licencia automáticamente"],"h1":"Las vías cerradas están cerradas por una razón.","h2":"El manual de Dakota del Sur dice que si maneja por una vía cerrada y se atasca, la ayuda puede tardar, y le pueden poner una multa y hacerlo responsable del costo del rescate.","p":"Correcto. Pueden multarlo y cobrarle el rescate."},"ref":{"doc":"SD","page":67}},{"id":"sd-186","scope":"SD","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In South Dakota, two cars come to a narrow, single-lane bridge from opposite ends. Who generally goes first?","o":["The driver who honks first","The larger vehicle","The driver going downhill","The first driver to reach the bridge"],"h1":"Take turns.","h2":"The South Dakota manual says to take turns on narrow or single-lane bridges, and generally the first driver to reach the bridge has the right-of-way.","p":"Right. The first driver to the bridge goes first."},"es":{"q":"En Dakota del Sur, dos carros llegan a un puente angosto de un solo carril desde lados opuestos. ¿Quién pasa primero, por lo general?","o":["El que toca el claxon primero","El vehículo más grande","El que va de bajada","El primer conductor que llega al puente"],"h1":"Túrnense.","h2":"El manual de Dakota del Sur dice que se turnen en los puentes angostos o de un solo carril, y por lo general el primer conductor que llega al puente tiene el derecho de paso.","p":"Correcto. El primero en llegar al puente pasa primero."},"ref":{"doc":"SD","page":67}},{"id":"sd-187","scope":"SD","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In South Dakota, you approach a rural intersection with no stop or yield signs. What should you do?","o":["Slow down and be ready to stop for other traffic","Keep your speed; you have the right-of-way","Speed up to get through first","Honk and drive through"],"h1":"No signs does not mean no danger.","h2":"The South Dakota manual says to slow down at an uncontrolled rural intersection and be prepared to stop for crossing or oncoming traffic.","p":"Right. Slow down and be ready to stop."},"es":{"q":"En Dakota del Sur, se acerca a una intersección rural sin señales de alto ni de ceda el paso. ¿Qué debe hacer?","o":["Bajar la velocidad y estar listo para detenerse por otros vehículos","Mantener la velocidad; usted tiene el derecho de paso","Acelerar para pasar primero","Tocar el claxon y pasar"],"h1":"Que no haya señales no quiere decir que no haya peligro.","h2":"El manual de Dakota del Sur dice que baje la velocidad en una intersección rural sin control y esté listo para detenerse por el tráfico que cruza o que viene de frente.","p":"Correcto. Baje la velocidad y esté listo para detenerse."},"ref":{"doc":"SD","page":67}},{"id":"sd-188","scope":"SD","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In South Dakota, you drive on a narrow rural road with ditches instead of shoulders. What does the manual suggest?","o":["Drive on the edge of the road","Slow down, center your car in the lane, and watch for oncoming traffic","Drive in the middle of the road","Speed up to get through quickly"],"h1":"Stay away from the drop-offs, but watch for cars coming toward you.","h2":"The South Dakota manual says that on narrow rural roads you should reduce speed, center your vehicle in the lane, and watch for oncoming traffic that may try to share the lane.","p":"Right. Slow down and center your car in the lane."},"es":{"q":"En Dakota del Sur, maneja por una vía rural angosta con zanjas en lugar de acotamientos. ¿Qué sugiere el manual?","o":["Manejar por la orilla de la vía","Bajar la velocidad, centrar el carro en el carril y fijarse en el tráfico de frente","Manejar por el centro de la vía","Acelerar para pasar rápido"],"h1":"Aléjese de los desniveles, pero fíjese en los carros que vienen de frente.","h2":"El manual de Dakota del Sur dice que en vías rurales angostas baje la velocidad, centre el vehículo en el carril y fíjese en el tráfico de frente que podría querer compartir el carril.","p":"Correcto. Baje la velocidad y centre el carro en el carril."},"ref":{"doc":"SD","page":67}},{"id":"sd-189","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, you come up on a stopped ambulance or police car using its red lights. What does state law require?","o":["Honk and pass quickly","Slow to 20 mph below the limit and keep going","Come to a complete stop before reaching it, then go on with caution when safe","Nothing, unless an officer waves at you"],"h1":"Red lights call for more than slowing down.","h2":"South Dakota law (SDCL 32-31-6.1) requires drivers from any direction to come to a complete stop before reaching a stopped emergency vehicle using red lights, then go on with caution only when it is safe.","p":"Right. Stop completely first, then go on carefully."},"es":{"q":"En Dakota del Sur, se acerca a una ambulancia o patrulla detenida con las luces rojas encendidas. ¿Qué exige la ley del estado?","o":["Tocar el claxon y pasar rápido","Bajar a 20 mph menos que el límite y seguir","Detenerse por completo antes de llegar a ella y luego seguir con cuidado cuando sea seguro","Nada, a menos que un oficial le haga señas"],"h1":"Las luces rojas piden algo más que bajar la velocidad.","h2":"La ley de Dakota del Sur (SDCL 32-31-6.1) exige que los conductores de cualquier dirección se detengan por completo antes de llegar a un vehículo de emergencia detenido con luces rojas, y luego sigan con cuidado solo cuando sea seguro.","p":"Correcto. Deténgase por completo y luego siga con cuidado."},"ref":{"doc":"SD","page":2}},{"id":"sd-190","scope":"SD","cat":"licensing","sign":null,"c":3,"en":{"q":"In South Dakota, what are the minimum liability insurance limits for a vehicle owner's policy?","o":["$5,000 per person, $10,000 per crash, and $5,000 property","$10,000 per person, $20,000 per crash, and $10,000 property","$50,000 per person, $100,000 per crash, and $50,000 property","$25,000 per person, $50,000 per crash for injuries, and $25,000 for property damage"],"h1":"People call it 25/50/25.","h2":"South Dakota law (SDCL 32-35-70) requires liability coverage of at least $25,000 for injury or death of one person, $50,000 for two or more people in one crash, and $25,000 for property damage.","p":"Right. 25/50/25 is the minimum."},"es":{"q":"En Dakota del Sur, ¿cuáles son los límites mínimos del seguro de responsabilidad en la póliza del dueño de un vehículo?","o":["$5,000 por persona, $10,000 por choque y $5,000 de propiedad","$10,000 por persona, $20,000 por choque y $10,000 de propiedad","$50,000 por persona, $100,000 por choque y $50,000 de propiedad","$25,000 por persona, $50,000 por choque por lesiones y $25,000 por daños a la propiedad"],"h1":"La gente lo llama 25/50/25.","h2":"La ley de Dakota del Sur (SDCL 32-35-70) exige una cobertura de responsabilidad de por lo menos $25,000 por lesiones o muerte de una persona, $50,000 por dos o más personas en un choque y $25,000 por daños a la propiedad.","p":"Correcto. 25/50/25 es el mínimo."},"ref":{"doc":"SD","page":null}},{"id":"sd-191","scope":"SD","cat":"licensing","sign":null,"c":0,"en":{"q":"In South Dakota, a crash injures no one. When must you notify law enforcement right away?","o":["When damage looks like $1,000 or more to one person's property, or $2,000 or more in all","Only when damage is over $10,000","Never, if no one is hurt","Only if a car must be towed"],"h1":"There are two dollar amounts in the law.","h2":"South Dakota law (SDCL 32-34-7) requires immediate notice to the nearest law enforcement officer for any crash with injury or death, or apparent damage of $1,000 or more to one person's property or $2,000 or more per crash.","p":"Right. $1,000 to one person's property or $2,000 in all."},"es":{"q":"En Dakota del Sur, en un choque no hay heridos. ¿Cuándo debe avisar de inmediato a la policía?","o":["Cuando los daños parecen de $1,000 o más a la propiedad de una persona, o de $2,000 o más en total","Solo si los daños pasan de $10,000","Nunca, si no hay heridos","Solo si hay que remolcar un carro"],"h1":"En la ley hay dos cantidades de dinero.","h2":"La ley de Dakota del Sur (SDCL 32-34-7) exige avisar de inmediato al oficial más cercano en todo choque con heridos o muertos, o con daños aparentes de $1,000 o más a la propiedad de una persona o de $2,000 o más por choque.","p":"Correcto. $1,000 a la propiedad de una persona o $2,000 en total."},"ref":{"doc":"SD","page":null}},{"id":"sd-192","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, on a two-lane road, a school bus ahead has its amber (yellow) warning lights flashing. What must you do?","o":["Stop at least 15 feet away","Slow to 15 mph or less and pass with caution","Speed up to pass before it stops","Nothing until the red lights come on"],"h1":"Amber means the bus is getting ready to stop.","h2":"South Dakota law (SDCL 32-32-6) says that on a road with fewer than two lanes each way, you must slow to 15 mph or less and pass with caution when a school bus has its amber lights flashing.","p":"Right. Slow to 15 mph or less and pass carefully."},"es":{"q":"En Dakota del Sur, en una vía de dos carriles, un autobús escolar delante tiene las luces ámbar (amarillas) de advertencia encendidas. ¿Qué debe hacer?","o":["Detenerse a por lo menos 15 pies","Bajar a 15 mph o menos y pasar con cuidado","Acelerar para pasar antes de que se detenga","Nada hasta que se enciendan las luces rojas"],"h1":"El ámbar significa que el autobús se prepara para detenerse.","h2":"La ley de Dakota del Sur (SDCL 32-32-6) dice que en una vía con menos de dos carriles por sentido debe bajar a 15 mph o menos y pasar con cuidado cuando un autobús escolar tiene las luces ámbar encendidas.","p":"Correcto. Baje a 15 mph o menos y pase con cuidado."},"ref":{"doc":"SD","page":null}},{"id":"sd-193","scope":"SD","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In South Dakota, how close to a fire hydrant may you park?","o":["No closer than 50 feet","No closer than 5 feet","No closer than 15 feet","Right next to it if you stay in the car"],"h1":"Fire trucks need room to hook up a hose.","h2":"South Dakota law (SDCL 32-30-6) says you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a hydrant."},"es":{"q":"En Dakota del Sur, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 50 pies","No a menos de 5 pies","No a menos de 15 pies","Justo al lado si se queda en el carro"],"h1":"Los bomberos necesitan espacio para conectar la manguera.","h2":"La ley de Dakota del Sur (SDCL 32-30-6) dice que no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a por lo menos 15 pies del hidrante."},"ref":{"doc":"SD","page":null}},{"id":"sd-194","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, how far back from a stop sign at the side of the road must you park?","o":["At least 100 feet","At least 10 feet","At least 15 feet","At least 30 feet"],"h1":"Parked cars must not hide the sign from drivers.","h2":"South Dakota law (SDCL 32-30-6) says you may not park within 30 feet of the approach to a stop sign, yield sign, flashing signal or traffic signal at the side of the road.","p":"Right. At least 30 feet before a stop sign."},"es":{"q":"En Dakota del Sur, ¿a qué distancia antes de una señal de alto a un lado de la vía debe estacionarse?","o":["Por lo menos a 100 pies","Por lo menos a 10 pies","Por lo menos a 15 pies","Por lo menos a 30 pies"],"h1":"Los carros estacionados no deben tapar la señal.","h2":"La ley de Dakota del Sur (SDCL 32-30-6) dice que no puede estacionarse a menos de 30 pies antes de una señal de alto, ceda el paso, luz intermitente o semáforo a un lado de la vía.","p":"Correcto. Por lo menos 30 pies antes de un alto."},"ref":{"doc":"SD","page":null}},{"id":"sd-195","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, how close to a crosswalk at an intersection may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 50 feet","Any distance, if the curb is not painted"],"h1":"Drivers need to see people stepping into the crosswalk.","h2":"South Dakota law (SDCL 32-30-6) says you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Dakota del Sur, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["No a menos de 20 pies","No a menos de 5 pies","No a menos de 50 pies","A cualquier distancia si la banqueta no está pintada"],"h1":"Los conductores necesitan ver a la gente que entra al cruce.","h2":"La ley de Dakota del Sur (SDCL 32-30-6) dice que no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese a por lo menos 20 pies del cruce."},"ref":{"doc":"SD","page":null}},{"id":"sd-196","scope":"SD","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In South Dakota, a railroad signal warns that a train is coming. Where must you stop?","o":["Right on the edge of the tracks","Between 15 and 50 feet from the nearest rail","At least 100 feet away","Anywhere, as long as you stop"],"h1":"Not too close, and not too far back.","h2":"South Dakota law (SDCL 32-29-4) says that when a signal or officer warns of a train, you must stop within 50 feet but not less than 15 feet from the nearest rail.","p":"Right. Between 15 and 50 feet from the nearest rail."},"es":{"q":"En Dakota del Sur, una señal del ferrocarril avisa que viene un tren. ¿Dónde debe detenerse?","o":["Justo a la orilla de las vías","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies","En cualquier lugar, mientras se detenga"],"h1":"Ni muy cerca ni muy atrás.","h2":"La ley de Dakota del Sur (SDCL 32-29-4) dice que cuando una señal o un oficial avisa de un tren, debe detenerse a no más de 50 pies y no menos de 15 pies del riel más cercano.","p":"Correcto. Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"SD","page":null}},{"id":"sd-197","scope":"SD","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In South Dakota, a fire truck is going to a fire. How close behind it may you follow?","o":["No closer than 100 feet","No closer than 50 feet","No closer than 500 feet","As close as you like"],"h1":"It is about one city block or more.","h2":"South Dakota law (SDCL 32-31-7) says you may not follow a fire truck answering an alarm closer than 500 feet, or park within the block where it has stopped.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Dakota del Sur, un camión de bomberos va hacia un incendio. ¿Qué tan cerca puede seguirlo?","o":["No a menos de 100 pies","No a menos de 50 pies","No a menos de 500 pies","Tan cerca como quiera"],"h1":"Es más o menos una cuadra o más.","h2":"La ley de Dakota del Sur (SDCL 32-31-7) dice que no puede seguir a un camión de bomberos que responde a una alarma a menos de 500 pies, ni estacionarse en la cuadra donde se detuvo.","p":"Correcto. Manténgase a por lo menos 500 pies."},"ref":{"doc":"SD","page":null}},{"id":"sd-198","scope":"SD","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In South Dakota, you are an adult with a full license. Which use of your phone does state law allow while driving?","o":["Typing an address into the GPS","Typing a text message","Posting on social media","A call in hands-free or voice-operated mode"],"h1":"The law allows talking without using your hands, but not typing.","h2":"South Dakota law (SDCL 32-26-47.1) bans using a mobile device while driving, with exceptions that include phone calls and hands-free or voice-operated use; typing texts, social media and typing an address into the GPS are not allowed.","p":"Right. A hands-free call is allowed."},"es":{"q":"En Dakota del Sur, usted es adulto y tiene licencia completa. ¿Qué uso del teléfono permite la ley del estado mientras maneja?","o":["Escribir una dirección en el GPS","Escribir un mensaje de texto","Publicar en redes sociales","Una llamada en modo manos libres o por voz"],"h1":"La ley permite hablar sin usar las manos, pero no escribir.","h2":"La ley de Dakota del Sur (SDCL 32-26-47.1) prohíbe usar un aparato móvil al manejar, con excepciones que incluyen las llamadas telefónicas y el uso con manos libres o por voz; escribir mensajes, usar redes sociales y escribir una dirección en el GPS no se permiten.","p":"Correcto. Una llamada con manos libres está permitida."},"ref":{"doc":"SD","page":null}},{"id":"sd-199","scope":"SD","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In South Dakota, a passenger has an opened can of beer in the car on a public highway. Is this allowed?","o":["No, an open container in the passenger area is a Class 2 misdemeanor","Yes, if the driver is not drinking","Yes, if the passenger is over 21","Yes, if the car is parked on the shoulder"],"h1":"It only is legal if the seal is unbroken or it is out of reach.","h2":"South Dakota law (SDCL 35-1-9.1) makes it a Class 2 misdemeanor for anyone in a vehicle on a public highway to have an open alcoholic drink, unless it is sealed or kept where no one inside can reach it.","p":"Right. Open alcohol in the passenger area is illegal for everyone."},"es":{"q":"En Dakota del Sur, un pasajero tiene una lata de cerveza abierta en el carro en una carretera pública. ¿Está permitido?","o":["No, un envase abierto en el área de pasajeros es un delito menor de Clase 2","Sí, si el conductor no está tomando","Sí, si el pasajero tiene más de 21 años","Sí, si el carro está estacionado en el acotamiento"],"h1":"Solo es legal si el sello está intacto o si está fuera del alcance.","h2":"La ley de Dakota del Sur (SDCL 35-1-9.1) hace que sea un delito menor de Clase 2 que cualquier persona en un vehículo en una carretera pública tenga una bebida alcohólica abierta, salvo que esté sellada o guardada donde nadie adentro pueda alcanzarla.","p":"Correcto. El alcohol abierto en el área de pasajeros es ilegal para todos."},"ref":{"doc":"SD","page":null}},{"id":"sd-200","scope":"SD","cat":"licensing","sign":null,"c":1,"en":{"q":"In South Dakota, who must wear a helmet on a motorcycle?","o":["Everyone, at every age","Riders and passengers under 18","Only the driver, at every age","No one; helmets are optional for all"],"h1":"The law is based on age.","h2":"South Dakota law (SDCL 32-20-4) requires anyone under 18 who drives or rides on a motorcycle to wear an approved protective helmet.","p":"Right. Everyone under 18 must wear a helmet."},"es":{"q":"En Dakota del Sur, ¿quién debe usar casco en una motocicleta?","o":["Todos, a cualquier edad","Quienes manejan o van de pasajeros y tienen menos de 18 años","Solo quien maneja, a cualquier edad","Nadie; el casco es opcional para todos"],"h1":"La ley se basa en la edad.","h2":"La ley de Dakota del Sur (SDCL 32-20-4) exige que toda persona menor de 18 años que maneje o vaya en una motocicleta use un casco protector aprobado.","p":"Correcto. Todos los menores de 18 deben usar casco."},"ref":{"doc":"SD","page":null}},{"id":"sd-201","scope":"SD","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In South Dakota, unless signs say otherwise, what is the top speed allowed on roads other than interstates?","o":["70 mph","55 mph","65 mph","80 mph"],"h1":"It is 15 mph lower than the interstate maximum.","h2":"South Dakota law (SDCL 32-25-1.1) sets 65 mph as the maximum on streets and highways other than interstates, unless a different limit is posted.","p":"Right. 65 mph off the interstate."},"es":{"q":"En Dakota del Sur, a menos que los letreros digan otra cosa, ¿cuál es la velocidad máxima permitida en vías que no son interestatales?","o":["70 mph","55 mph","65 mph","80 mph"],"h1":"Es 15 mph menos que el máximo de la interestatal.","h2":"La ley de Dakota del Sur (SDCL 32-25-1.1) fija 65 mph como máximo en calles y carreteras que no son interestatales, a menos que haya otro límite indicado.","p":"Correcto. 65 mph fuera de la interestatal."},"ref":{"doc":"SD","page":null}},{"id":"tn-001","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get an intermediate license.","h2":"You can get a Tennessee learner permit at 15 after passing the written and vision tests.","p":"Right. The learner permit starts at age 15."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia intermedia.","h2":"Usted puede obtener el permiso de aprendiz en Tennessee a los 15 años, después de aprobar los exámenes escrito y de la vista.","p":"Correcto. El permiso de aprendiz empieza a los 15 años."},"zh":{"q":"在 Tennessee，最小几岁可以拿到学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"比可以拿中级驾照的年龄早一年。","h2":"你 15 岁通过笔试和视力测试后，就可以拿到 Tennessee 的学习驾照。","p":"对。学习驾照从 15 岁开始。"},"vi":{"q":"Ở Tennessee, tuổi nhỏ nhất để có giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái trung cấp.","h2":"Bạn có thể lấy giấy phép tập lái của Tennessee lúc 15 tuổi sau khi đậu bài thi viết và bài kiểm tra thị lực.","p":"Đúng. Giấy phép tập lái bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Tennessee, ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng intermediate license.","h2":"Makakakuha ka ng Tennessee learner permit sa edad na 15 pagkatapos pumasa sa nakasulat na pagsusulit at sa pagsusuri sa mata.","p":"Tama. Nagsisimula ang learner permit sa edad na 15."},"ar":{"q":"في Tennessee، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل أن تستطيع الحصول على الرخصة المتوسطة.","h2":"يمكنك الحصول على تصريح التعلّم في Tennessee في عمر 15 سنة بعد النجاح في الاختبار الكتابي وفحص النظر.","p":"صحيح. يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"TN","page":14}},{"id":"tn-002","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, who must be in the car when a learner permit holder drives?","o":["Any passenger age 16 or older","A licensed driver 18 or older in the back seat","A licensed driver 21 or older in the front seat","No one, during daylight hours"],"h1":"The helper must be an adult who can reach you and see the road.","h2":"A learner permit holder must always have a licensed driver who is 21 or older sitting in the front seat.","p":"Right. A licensed driver 21 or older must sit in the front seat."},"es":{"q":"En Tennessee, ¿quién debe ir en el carro cuando maneja alguien con permiso de aprendiz?","o":["Cualquier pasajero de 16 años o más","Un conductor con licencia de 18 años o más en el asiento de atrás","Un conductor con licencia de 21 años o más en el asiento de adelante","Nadie, durante el día"],"h1":"El acompañante debe ser un adulto que pueda alcanzarlo y ver el camino.","h2":"Quien tiene permiso de aprendiz siempre debe ir con un conductor con licencia de 21 años o más sentado en el asiento de adelante.","p":"Correcto. Un conductor con licencia de 21 años o más debe ir adelante."},"zh":{"q":"在 Tennessee，持学习驾照的人开车时，谁必须在车里？","o":["任何 16 岁或以上的乘客","坐在后座、18 岁或以上的持照司机","坐在前座、21 岁或以上的持照司机","不需要任何人，白天时"],"h1":"陪同的人必须是成年人，能碰到你，也能看到道路。","h2":"持学习驾照的人开车时，前座必须一直坐着一位 21 岁或以上的持照司机。","p":"对。一位 21 岁或以上的持照司机必须坐在前座。"},"vi":{"q":"Ở Tennessee, ai phải ngồi trong xe khi người có giấy phép tập lái lái xe?","o":["Bất kỳ hành khách nào từ 16 tuổi trở lên","Một tài xế có bằng lái từ 18 tuổi trở lên ngồi ở ghế sau","Một tài xế có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước","Không cần ai, vào ban ngày"],"h1":"Người giúp đỡ phải là người lớn có thể với tới bạn và nhìn thấy đường.","h2":"Người có giấy phép tập lái luôn phải có một tài xế có bằng lái từ 21 tuổi trở lên ngồi ở ghế trước.","p":"Đúng. Một tài xế có bằng lái từ 21 tuổi trở lên phải ngồi ở ghế trước."},"tl":{"q":"Sa Tennessee, sino ang dapat nasa loob ng sasakyan kapag nagmamaneho ang may learner permit?","o":["Kahit sinong pasahero na 16 taong gulang pataas","Isang lisensyadong driver na 18 pataas sa likod na upuan","Isang lisensyadong driver na 21 pataas sa harap na upuan","Wala, kapag araw"],"h1":"Ang tutulong ay dapat isang adulto na maaabot ka at nakakakita ng daan.","h2":"Ang may learner permit ay dapat laging may kasamang lisensyadong driver na 21 taong gulang pataas na nakaupo sa harap na upuan.","p":"Tama. Isang lisensyadong driver na 21 pataas ang dapat nakaupo sa harap."},"ar":{"q":"في Tennessee، من يجب أن يكون في السيارة عندما يقود حامل تصريح التعلّم؟","o":["أي راكب عمره 16 سنة أو أكثر","سائق مرخّص عمره 18 سنة أو أكثر في المقعد الخلفي","سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي","لا أحد، في ساعات النهار"],"h1":"يجب أن يكون المساعد شخصًا بالغًا يستطيع الوصول إليك ورؤية الطريق.","h2":"يجب أن يكون مع حامل تصريح التعلّم دائمًا سائق مرخّص عمره 21 سنة أو أكثر يجلس في المقعد الأمامي.","p":"صحيح. يجب أن يجلس سائق مرخّص عمره 21 سنة أو أكثر في المقعد الأمامي."},"ref":{"doc":"TN","page":14}},{"id":"tn-003","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, during which hours may a learner permit holder not drive?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It starts two hours before midnight.","h2":"A learner permit holder may not drive between 10 p.m. and 6 a.m., even with an adult, because night driving is harder for beginners.","p":"Right. Learners do not drive from 10 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar quien tiene permiso de aprendiz?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Empieza dos horas antes de la medianoche.","h2":"Quien tiene permiso de aprendiz no puede manejar entre las 10 p.m. y las 6 a.m., aun con un adulto, porque manejar de noche es más difícil para los principiantes.","p":"Correcto. Los aprendices no manejan de 10 p.m. a 6 a.m."},"zh":{"q":"在 Tennessee，持学习驾照的人在哪个时间段不可以开车？","o":["晚上 10 点到早上 6 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 5 点"],"h1":"从午夜前两个小时开始。","h2":"持学习驾照的人在晚上 10 点到早上 6 点之间不可以开车，即使有成年人陪同也不行，因为晚上开车对新手更难。","p":"对。学习者从晚上 10 点到早上 6 点不开车。"},"vi":{"q":"Ở Tennessee, người có giấy phép tập lái không được lái xe trong khoảng giờ nào?","o":["10 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng"],"h1":"Bắt đầu hai giờ trước nửa đêm.","h2":"Người có giấy phép tập lái không được lái xe từ 10 giờ tối đến 6 giờ sáng, kể cả khi có người lớn đi cùng, vì lái xe ban đêm khó hơn cho người mới.","p":"Đúng. Người tập lái không lái xe từ 10 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Tennessee, sa anong mga oras hindi puwedeng magmaneho ang may learner permit?","o":["10 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m."],"h1":"Nagsisimula ito dalawang oras bago maghatinggabi.","h2":"Hindi puwedeng magmaneho ang may learner permit mula 10 p.m. hanggang 6 a.m., kahit may kasamang adulto, dahil mas mahirap ang pagmamaneho sa gabi para sa mga baguhan.","p":"Tama. Hindi nagmamaneho ang mga learner mula 10 p.m. hanggang 6 a.m."},"ar":{"q":"في Tennessee، في أي ساعات لا يجوز لحامل تصريح التعلّم أن يقود؟","o":["من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"تبدأ قبل منتصف الليل بساعتين.","h2":"لا يجوز لحامل تصريح التعلّم أن يقود بين 10 مساءً و6 صباحًا، حتى مع شخص بالغ، لأن القيادة في الليل أصعب على المبتدئين.","p":"صحيح. المتعلّمون لا يقودون من 10 مساءً إلى 6 صباحًا."},"ref":{"doc":"TN","page":14}},{"id":"tn-004","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a teen hold a learner permit before getting an intermediate restricted license?","o":["90 days","30 days","One year","180 days"],"h1":"It is about half a year.","h2":"A teen must hold the learner permit for at least 180 days before moving up to the intermediate restricted license.","p":"Right. You must hold the permit for 180 days."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un joven el permiso de aprendiz antes de obtener la licencia intermedia restringida?","o":["90 días","30 días","Un año","180 días"],"h1":"Es más o menos medio año.","h2":"Un joven debe tener el permiso de aprendiz por lo menos 180 días antes de pasar a la licencia intermedia restringida.","p":"Correcto. Debe tener el permiso 180 días."},"zh":{"q":"在 Tennessee，青少年必须持有学习驾照多久，才能拿到中级限制驾照（intermediate restricted license）？","o":["90 天","30 天","一年","180 天"],"h1":"大约是半年。","h2":"青少年必须持有学习驾照至少 180 天，才能升级到中级限制驾照。","p":"对。你必须持有学习驾照 180 天。"},"vi":{"q":"Ở Tennessee, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung cấp có hạn chế (intermediate restricted license)?","o":["90 ngày","30 ngày","Một năm","180 ngày"],"h1":"Khoảng nửa năm.","h2":"Thiếu niên phải giữ giấy phép tập lái ít nhất 180 ngày trước khi lên bằng lái trung cấp có hạn chế.","p":"Đúng. Bạn phải giữ giấy phép 180 ngày."},"tl":{"q":"Sa Tennessee, gaano katagal dapat hawak ng isang teen ang learner permit bago makakuha ng intermediate restricted license?","o":["90 araw","30 araw","Isang taon","180 araw"],"h1":"Mga kalahating taon ito.","h2":"Dapat hawak ng teen ang learner permit nang hindi bababa sa 180 araw bago umakyat sa intermediate restricted license.","p":"Tama. Dapat mong hawakan ang permit nang 180 araw."},"ar":{"q":"في Tennessee، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة المقيّدة (intermediate restricted license)؟","o":["90 يومًا","30 يومًا","سنة واحدة","180 يومًا"],"h1":"هي نحو نصف سنة.","h2":"يجب أن يحمل المراهق تصريح التعلّم 180 يومًا على الأقل قبل الانتقال إلى الرخصة المتوسطة المقيّدة.","p":"صحيح. يجب أن تحمل التصريح 180 يومًا."},"ref":{"doc":"TN","page":14}},{"id":"tn-005","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how many hours of driving practice must a teen complete before an intermediate restricted license?","o":["30 hours","50 hours","40 hours","100 hours"],"h1":"It is half of one hundred.","h2":"A teen needs 50 hours of behind-the-wheel practice before an intermediate restricted license, signed off by a parent, guardian or driving instructor.","p":"Right. Tennessee asks for 50 hours of practice."},"es":{"q":"En Tennessee, ¿cuántas horas de práctica de manejo debe completar un joven antes de la licencia intermedia restringida?","o":["30 horas","50 horas","40 horas","100 horas"],"h1":"Es la mitad de cien.","h2":"Un joven necesita 50 horas de práctica al volante antes de la licencia intermedia restringida, certificadas por su padre, madre, tutor o instructor de manejo.","p":"Correcto. Tennessee pide 50 horas de práctica."},"zh":{"q":"在 Tennessee，青少年在拿中级限制驾照之前，必须完成多少小时的开车练习？","o":["30 小时","50 小时","40 小时","100 小时"],"h1":"是一百的一半。","h2":"青少年在拿中级限制驾照之前，需要 50 小时的实际开车练习，并由父母、监护人或驾驶教练签字确认。","p":"对。Tennessee 要求 50 小时的练习。"},"vi":{"q":"Ở Tennessee, thiếu niên phải tập lái bao nhiêu giờ trước khi lấy bằng lái trung cấp có hạn chế?","o":["30 giờ","50 giờ","40 giờ","100 giờ"],"h1":"Đó là một nửa của một trăm.","h2":"Thiếu niên cần 50 giờ tập lái thực tế trước khi lấy bằng lái trung cấp có hạn chế, có chữ ký xác nhận của cha mẹ, người giám hộ hoặc thầy dạy lái.","p":"Đúng. Tennessee yêu cầu 50 giờ tập lái."},"tl":{"q":"Sa Tennessee, ilang oras ng pagsasanay sa pagmamaneho ang dapat tapusin ng isang teen bago ang intermediate restricted license?","o":["30 oras","50 oras","40 oras","100 oras"],"h1":"Kalahati ito ng isang daan.","h2":"Kailangan ng teen ang 50 oras ng aktuwal na pagsasanay sa pagmamaneho bago ang intermediate restricted license, na pinirmahan ng magulang, guardian o driving instructor.","p":"Tama. Humihingi ang Tennessee ng 50 oras na pagsasanay."},"ar":{"q":"في Tennessee، كم ساعة من التدريب على القيادة يجب أن يكملها المراهق قبل الرخصة المتوسطة المقيّدة؟","o":["30 ساعة","50 ساعة","40 ساعة","100 ساعة"],"h1":"هي نصف المئة.","h2":"يحتاج المراهق إلى 50 ساعة من التدريب الفعلي خلف المقود قبل الرخصة المتوسطة المقيّدة، ويوقّع عليها أحد الوالدين أو الوصي أو مدرّب القيادة.","p":"صحيح. تطلب Tennessee خمسين ساعة (50) من التدريب."},"ref":{"doc":"TN","page":14}},{"id":"tn-006","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, how many of the required practice hours must be at night?","o":["2 hours","5 hours","10 hours","25 hours"],"h1":"It is one fifth of the total.","h2":"At least 10 of the 50 practice hours must be at night, so the teen has practiced in the dark with help.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Tennessee, ¿cuántas de las horas de práctica requeridas deben ser de noche?","o":["2 horas","5 horas","10 horas","25 horas"],"h1":"Es la quinta parte del total.","h2":"Por lo menos 10 de las 50 horas de práctica deben ser de noche, para que el joven haya practicado en la oscuridad con ayuda.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Tennessee，规定的练习时间中，有多少小时必须在晚上？","o":["2 小时","5 小时","10 小时","25 小时"],"h1":"是总数的五分之一。","h2":"50 小时练习中至少有 10 小时必须在晚上，这样青少年就在有人帮助的情况下练习过在黑暗中开车。","p":"对。至少 10 小时必须在晚上。"},"vi":{"q":"Ở Tennessee, trong số giờ tập lái bắt buộc, bao nhiêu giờ phải vào ban đêm?","o":["2 giờ","5 giờ","10 giờ","25 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ít nhất 10 trong 50 giờ tập lái phải vào ban đêm, để thiếu niên đã tập lái trong bóng tối khi có người giúp.","p":"Đúng. Ít nhất 10 giờ phải vào ban đêm."},"tl":{"q":"Sa Tennessee, ilan sa mga kailangang oras ng pagsasanay ang dapat sa gabi?","o":["2 oras","5 oras","10 oras","25 oras"],"h1":"Isang ikalima ito ng kabuuan.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay ang dapat sa gabi, para nakapagsanay ang teen sa dilim nang may tumutulong.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Tennessee، كم ساعة من ساعات التدريب المطلوبة يجب أن تكون في الليل؟","o":["ساعتان (2)","5 ساعات","10 ساعات","25 ساعة"],"h1":"هي خُمس المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة تدريب في الليل، حتى يكون المراهق قد تدرّب في الظلام مع من يساعده.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"TN","page":14}},{"id":"tn-007","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the youngest age for an intermediate restricted license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It is one year after the learner permit age.","h2":"You can get an intermediate restricted license at 16, after holding your permit 180 days, finishing your practice hours and passing a road test.","p":"Right. The intermediate restricted license starts at 16."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para la licencia intermedia restringida?","o":["16 años","15 años","17 años","18 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"Usted puede obtener la licencia intermedia restringida a los 16 años, después de tener el permiso 180 días, terminar sus horas de práctica y aprobar el examen de manejo.","p":"Correcto. La licencia intermedia restringida empieza a los 16."},"zh":{"q":"在 Tennessee，最小几岁可以拿到中级限制驾照？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"比拿学习驾照的年龄晚一年。","h2":"你 16 岁时，在持有学习驾照 180 天、完成练习时间并通过路考之后，就可以拿到中级限制驾照。","p":"对。中级限制驾照从 16 岁开始。"},"vi":{"q":"Ở Tennessee, tuổi nhỏ nhất để có bằng lái trung cấp có hạn chế là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Đó là một năm sau tuổi lấy giấy phép tập lái.","h2":"Bạn có thể lấy bằng lái trung cấp có hạn chế lúc 16 tuổi, sau khi giữ giấy phép tập lái 180 ngày, hoàn thành số giờ tập lái và đậu bài thi lái xe trên đường.","p":"Đúng. Bằng lái trung cấp có hạn chế bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Tennessee, ano ang pinakabatang edad para sa intermediate restricted license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad para sa learner permit.","h2":"Makakakuha ka ng intermediate restricted license sa edad na 16, pagkatapos hawakan ang permit nang 180 araw, tapusin ang mga oras ng pagsasanay at pumasa sa road test.","p":"Tama. Nagsisimula ang intermediate restricted license sa edad na 16."},"ar":{"q":"في Tennessee، ما أصغر عمر للرخصة المتوسطة المقيّدة؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"هو سنة واحدة بعد عمر تصريح التعلّم.","h2":"يمكنك الحصول على الرخصة المتوسطة المقيّدة في عمر 16 سنة، بعد أن تحمل التصريح 180 يومًا، وتكمل ساعات التدريب، وتنجح في اختبار القيادة على الطريق.","p":"صحيح. تبدأ الرخصة المتوسطة المقيّدة في عمر 16 سنة."},"ref":{"doc":"TN","page":14}},{"id":"tn-008","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, who may sign the form that certifies a teen’s 50 hours of practice?","o":["Any friend who is 18","A school principal","A police officer","A parent, guardian or driving instructor"],"h1":"It is an adult who rode along and is responsible for the teen’s training.","h2":"A parent, legal guardian or driving instructor signs the 50-hour certification form to confirm the teen’s practice.","p":"Right. A parent, guardian or driving instructor signs the form."},"es":{"q":"En Tennessee, ¿quién puede firmar el formulario que certifica las 50 horas de práctica de un joven?","o":["Cualquier amigo de 18 años","El director de la escuela","Un policía","Su padre, madre, tutor o instructor de manejo"],"h1":"Es un adulto que lo acompañó y es responsable de su práctica.","h2":"Su padre, madre, tutor legal o instructor de manejo firma el formulario de certificación de 50 horas para confirmar la práctica del joven.","p":"Correcto. Firma su padre, madre, tutor o instructor de manejo."},"zh":{"q":"在 Tennessee，谁可以在证明青少年完成 50 小时练习的表格上签字？","o":["任何 18 岁的朋友","学校校长","警察","父母、监护人或驾驶教练"],"h1":"是一位陪同开车、并负责青少年训练的成年人。","h2":"父母、法定监护人或驾驶教练在 50 小时证明表上签字，确认青少年的练习。","p":"对。父母、监护人或驾驶教练在表格上签字。"},"vi":{"q":"Ở Tennessee, ai được ký vào mẫu đơn xác nhận 50 giờ tập lái của thiếu niên?","o":["Bất kỳ người bạn nào 18 tuổi","Hiệu trưởng trường học","Cảnh sát","Cha mẹ, người giám hộ hoặc thầy dạy lái"],"h1":"Đó là một người lớn đã đi cùng xe và chịu trách nhiệm việc tập lái của thiếu niên.","h2":"Cha mẹ, người giám hộ hợp pháp hoặc thầy dạy lái ký vào mẫu xác nhận 50 giờ để xác nhận việc tập lái của thiếu niên.","p":"Đúng. Cha mẹ, người giám hộ hoặc thầy dạy lái ký vào mẫu đơn."},"tl":{"q":"Sa Tennessee, sino ang puwedeng pumirma sa form na nagpapatunay sa 50 oras ng pagsasanay ng isang teen?","o":["Kahit sinong kaibigan na 18","Isang punong-guro ng paaralan","Isang pulis","Isang magulang, guardian o driving instructor"],"h1":"Isa itong adulto na sumama sa biyahe at responsable sa pagsasanay ng teen.","h2":"Ang magulang, legal na guardian o driving instructor ang pumipirma sa 50-hour certification form para kumpirmahin ang pagsasanay ng teen.","p":"Tama. Ang magulang, guardian o driving instructor ang pumipirma sa form."},"ar":{"q":"في Tennessee، من يجوز له أن يوقّع على النموذج الذي يثبت 50 ساعة تدريب للمراهق؟","o":["أي صديق عمره 18 سنة","مدير مدرسة","شرطي","أحد الوالدين أو الوصي أو مدرّب القيادة"],"h1":"هو شخص بالغ ركب مع المراهق وهو مسؤول عن تدريبه.","h2":"يوقّع أحد الوالدين أو الوصي القانوني أو مدرّب القيادة على نموذج الـ 50 ساعة لتأكيد تدريب المراهق.","p":"صحيح. يوقّع على النموذج أحد الوالدين أو الوصي أو مدرّب القيادة."},"ref":{"doc":"TN","page":14}},{"id":"tn-009","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, during which hours may an intermediate restricted driver not drive without a parent or an adult 21 or older?","o":["10 p.m. to 6 a.m.","Midnight to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 5 a.m."],"h1":"It is one hour later than the learner permit limit.","h2":"An intermediate restricted driver may not drive from 11 p.m. to 6 a.m. unless a parent, guardian or other allowed adult is in the car, or another exception in the law applies.","p":"Right. Intermediate drivers stay off the road from 11 p.m. to 6 a.m."},"es":{"q":"En Tennessee, ¿en qué horario no puede manejar un conductor con licencia intermedia restringida sin su padre, madre o un adulto de 21 años o más?","o":["De 10 p.m. a 6 a.m.","De medianoche a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 5 a.m."],"h1":"Es una hora más tarde que el límite del permiso de aprendiz.","h2":"Un conductor con licencia intermedia restringida no puede manejar de 11 p.m. a 6 a.m., salvo que vaya su padre, madre, tutor u otro adulto permitido, o que aplique otra excepción de la ley.","p":"Correcto. Los conductores intermedios no manejan de 11 p.m. a 6 a.m."},"zh":{"q":"在 Tennessee，持中级限制驾照的司机在没有父母或 21 岁或以上成年人陪同时，哪个时间段不可以开车？","o":["晚上 10 点到早上 6 点","午夜到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 5 点"],"h1":"比学习驾照的限制晚一个小时。","h2":"持中级限制驾照的司机从晚上 11 点到早上 6 点不可以开车，除非父母、监护人或其他允许的成年人在车里，或符合法律中的其他例外。","p":"对。中级驾照司机从晚上 11 点到早上 6 点不上路。"},"vi":{"q":"Ở Tennessee, tài xế có bằng lái trung cấp có hạn chế không được lái xe trong khoảng giờ nào nếu không có cha mẹ hoặc người lớn từ 21 tuổi trở lên?","o":["10 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng"],"h1":"Muộn hơn một giờ so với giới hạn của giấy phép tập lái.","h2":"Tài xế có bằng lái trung cấp có hạn chế không được lái xe từ 11 giờ tối đến 6 giờ sáng, trừ khi có cha mẹ, người giám hộ hoặc người lớn được phép khác trong xe, hoặc có trường hợp ngoại lệ khác theo luật.","p":"Đúng. Tài xế bằng trung cấp không ra đường từ 11 giờ tối đến 6 giờ sáng."},"tl":{"q":"Sa Tennessee, sa anong mga oras hindi puwedeng magmaneho ang may intermediate restricted license kung walang magulang o adultong 21 pataas?","o":["10 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m."],"h1":"Isang oras itong mas huli kaysa sa limitasyon ng learner permit.","h2":"Hindi puwedeng magmaneho ang may intermediate restricted license mula 11 p.m. hanggang 6 a.m. maliban kung may magulang, guardian o ibang pinapayagang adulto sa sasakyan, o may ibang exception sa batas.","p":"Tama. Wala sa daan ang mga intermediate driver mula 11 p.m. hanggang 6 a.m."},"ar":{"q":"في Tennessee، في أي ساعات لا يجوز لسائق الرخصة المتوسطة المقيّدة أن يقود بدون أحد الوالدين أو شخص بالغ عمره 21 سنة أو أكثر؟","o":["من 10 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا"],"h1":"هي بعد حدّ تصريح التعلّم بساعة واحدة.","h2":"لا يجوز لسائق الرخصة المتوسطة المقيّدة أن يقود من 11 مساءً إلى 6 صباحًا، إلا إذا كان في السيارة أحد الوالدين أو الوصي أو شخص بالغ آخر مسموح له، أو إذا انطبق استثناء آخر في القانون.","p":"صحيح. سائقو الرخصة المتوسطة لا يقودون من 11 مساءً إلى 6 صباحًا."},"ref":{"doc":"TN","page":19}},{"id":"tn-010","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many passengers may an intermediate restricted driver carry when no licensed adult 21 or older is in the car?","o":["One passenger","No passengers","Two passengers","Three passengers"],"h1":"More than zero, but fewer than two.","h2":"An intermediate restricted driver may carry only one passenger unless a licensed driver 21 or older is in the car, because more young passengers raise crash risk.","p":"Right. Only one passenger without an adult."},"es":{"q":"En Tennessee, ¿cuántos pasajeros puede llevar un conductor con licencia intermedia restringida si no va un adulto con licencia de 21 años o más?","o":["Un pasajero","Ningún pasajero","Dos pasajeros","Tres pasajeros"],"h1":"Más que cero, pero menos que dos.","h2":"Un conductor con licencia intermedia restringida solo puede llevar un pasajero, salvo que vaya un conductor con licencia de 21 años o más, porque más pasajeros jóvenes aumentan el riesgo de choque.","p":"Correcto. Solo un pasajero sin un adulto."},"zh":{"q":"在 Tennessee，车里没有 21 岁或以上的持照成年人时，持中级限制驾照的司机可以载几名乘客？","o":["一名乘客","不能载乘客","两名乘客","三名乘客"],"h1":"比零多，但比二少。","h2":"除非车里有一位 21 岁或以上的持照司机，持中级限制驾照的司机只能载一名乘客，因为年轻乘客越多，车祸风险越高。","p":"对。没有成年人时只能载一名乘客。"},"vi":{"q":"Ở Tennessee, khi trong xe không có người lớn có bằng lái từ 21 tuổi trở lên, tài xế có bằng lái trung cấp có hạn chế được chở bao nhiêu hành khách?","o":["Một hành khách","Không được chở hành khách","Hai hành khách","Ba hành khách"],"h1":"Nhiều hơn không, nhưng ít hơn hai.","h2":"Tài xế có bằng lái trung cấp có hạn chế chỉ được chở một hành khách, trừ khi có tài xế có bằng lái từ 21 tuổi trở lên trong xe, vì càng nhiều hành khách trẻ thì nguy cơ tai nạn càng cao.","p":"Đúng. Chỉ một hành khách khi không có người lớn."},"tl":{"q":"Sa Tennessee, ilang pasahero ang puwedeng isakay ng may intermediate restricted license kapag walang lisensyadong adulto na 21 pataas sa sasakyan?","o":["Isang pasahero","Walang pasahero","Dalawang pasahero","Tatlong pasahero"],"h1":"Higit sa zero, pero kulang sa dalawa.","h2":"Isang pasahero lang ang puwedeng isakay ng may intermediate restricted license maliban kung may lisensyadong driver na 21 pataas sa sasakyan, dahil mas maraming batang pasahero ay mas mataas na panganib ng banggaan.","p":"Tama. Isang pasahero lang kapag walang adulto."},"ar":{"q":"في Tennessee، كم راكبًا يجوز لسائق الرخصة المتوسطة المقيّدة أن ينقل عندما لا يكون في السيارة شخص بالغ مرخّص عمره 21 سنة أو أكثر؟","o":["راكب واحد","لا ركّاب","راكبان","ثلاثة ركّاب"],"h1":"أكثر من صفر، لكن أقل من اثنين.","h2":"يجوز لسائق الرخصة المتوسطة المقيّدة أن ينقل راكبًا واحدًا فقط، إلا إذا كان في السيارة سائق مرخّص عمره 21 سنة أو أكثر، لأن كثرة الركّاب الصغار ترفع خطر الحوادث.","p":"صحيح. راكب واحد فقط بدون شخص بالغ."},"ref":{"doc":"TN","page":19}},{"id":"tn-011","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long must a driver hold the intermediate restricted license before moving to the intermediate unrestricted license?","o":["Three months","Six months","Two years","One year"],"h1":"It is twelve months.","h2":"A driver must hold the intermediate restricted license for one year, without disqualifying violations, before moving up to the unrestricted license.","p":"Right. The restricted license is held for one year."},"es":{"q":"En Tennessee, ¿cuánto tiempo debe tener un conductor la licencia intermedia restringida antes de pasar a la licencia intermedia sin restricciones?","o":["Tres meses","Seis meses","Dos años","Un año"],"h1":"Son doce meses.","h2":"Un conductor debe tener la licencia intermedia restringida por un año, sin infracciones que lo descalifiquen, antes de pasar a la licencia sin restricciones.","p":"Correcto. La licencia restringida se tiene por un año."},"zh":{"q":"在 Tennessee，司机必须持有中级限制驾照多久，才能换成中级无限制驾照（intermediate unrestricted license）？","o":["三个月","六个月","两年","一年"],"h1":"是十二个月。","h2":"司机必须持有中级限制驾照一年，并且没有会取消资格的违规，才能升级到无限制驾照。","p":"对。限制驾照要持有一年。"},"vi":{"q":"Ở Tennessee, tài xế phải giữ bằng lái trung cấp có hạn chế bao lâu trước khi chuyển sang bằng lái trung cấp không hạn chế (intermediate unrestricted license)?","o":["Ba tháng","Sáu tháng","Hai năm","Một năm"],"h1":"Đó là mười hai tháng.","h2":"Tài xế phải giữ bằng lái trung cấp có hạn chế một năm, không có vi phạm làm mất tư cách, trước khi lên bằng lái không hạn chế.","p":"Đúng. Bằng lái có hạn chế được giữ một năm."},"tl":{"q":"Sa Tennessee, gaano katagal dapat hawak ng driver ang intermediate restricted license bago lumipat sa intermediate unrestricted license?","o":["Tatlong buwan","Anim na buwan","Dalawang taon","Isang taon"],"h1":"Labindalawang buwan ito.","h2":"Dapat hawak ng driver ang intermediate restricted license nang isang taon, nang walang paglabag na nakakadiskwalipika, bago umakyat sa unrestricted license.","p":"Tama. Hawak ang restricted license nang isang taon."},"ar":{"q":"في Tennessee، كم مدة يجب أن يحمل السائق الرخصة المتوسطة المقيّدة قبل الانتقال إلى الرخصة المتوسطة غير المقيّدة (intermediate unrestricted license)؟","o":["ثلاثة أشهر","ستة أشهر","سنتان","سنة واحدة"],"h1":"هي اثنا عشر شهرًا.","h2":"يجب أن يحمل السائق الرخصة المتوسطة المقيّدة سنة واحدة، بدون مخالفات تُسقط الأهلية، قبل الانتقال إلى الرخصة غير المقيّدة.","p":"صحيح. تُحمل الرخصة المقيّدة سنة واحدة."},"ref":{"doc":"TN","page":14}},{"id":"tn-012","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, what is the rule on phones for drivers with a learner permit or an intermediate license?","o":["They may text only at red lights","They may not use a cell phone while driving","They may use a phone if it is on speaker","They may call only family members"],"h1":"The rule for new drivers is stricter than for adults.","h2":"Drivers with a learner permit or an intermediate license may not use a cell phone while driving, so all their attention stays on the road.","p":"Right. New Tennessee drivers may not use a phone while driving."},"es":{"q":"En Tennessee, ¿cuál es la regla sobre teléfonos para conductores con permiso de aprendiz o licencia intermedia?","o":["Pueden escribir textos solo en luces rojas","No pueden usar el celular mientras manejan","Pueden usar el teléfono si está en altavoz","Pueden llamar solo a familiares"],"h1":"La regla para conductores nuevos es más estricta que para adultos.","h2":"Los conductores con permiso de aprendiz o licencia intermedia no pueden usar el celular mientras manejan, para que toda su atención esté en el camino.","p":"Correcto. Los conductores nuevos en Tennessee no pueden usar el teléfono al manejar."},"zh":{"q":"在 Tennessee，对持学习驾照或中级驾照的司机，手机的规定是什么？","o":["只能在红灯时发短信","开车时不可以使用手机","如果开免提就可以用手机","只能打电话给家人"],"h1":"对新司机的规定比对成年人更严格。","h2":"持学习驾照或中级驾照的司机开车时不可以使用手机，这样所有注意力都放在道路上。","p":"对。Tennessee 的新司机开车时不可以用手机。"},"vi":{"q":"Ở Tennessee, quy định về điện thoại cho tài xế có giấy phép tập lái hoặc bằng lái trung cấp là gì?","o":["Họ chỉ được nhắn tin khi đèn đỏ","Họ không được dùng điện thoại di động khi lái xe","Họ được dùng điện thoại nếu bật loa ngoài","Họ chỉ được gọi cho người trong gia đình"],"h1":"Quy định cho tài xế mới nghiêm hơn so với người lớn.","h2":"Tài xế có giấy phép tập lái hoặc bằng lái trung cấp không được dùng điện thoại di động khi lái xe, để toàn bộ sự chú ý dành cho con đường.","p":"Đúng. Tài xế mới ở Tennessee không được dùng điện thoại khi lái xe."},"tl":{"q":"Sa Tennessee, ano ang patakaran sa telepono para sa mga driver na may learner permit o intermediate license?","o":["Puwede silang mag-text sa pulang ilaw lang","Hindi sila puwedeng gumamit ng cell phone habang nagmamaneho","Puwede silang gumamit ng telepono kung naka-speaker","Puwede lang silang tumawag sa pamilya"],"h1":"Mas mahigpit ang patakaran para sa mga bagong driver kaysa sa mga adulto.","h2":"Hindi puwedeng gumamit ng cell phone habang nagmamaneho ang mga driver na may learner permit o intermediate license, para nasa daan ang buong atensyon nila.","p":"Tama. Hindi puwedeng gumamit ng telepono habang nagmamaneho ang mga bagong driver sa Tennessee."},"ar":{"q":"في Tennessee، ما قاعدة الهاتف للسائقين الذين يحملون تصريح التعلّم أو الرخصة المتوسطة؟","o":["يجوز لهم إرسال الرسائل عند الإشارة الحمراء فقط","لا يجوز لهم استخدام الهاتف المحمول أثناء القيادة","يجوز لهم استخدام الهاتف إذا كان على مكبّر الصوت","يجوز لهم الاتصال بأفراد العائلة فقط"],"h1":"القاعدة للسائقين الجدد أشدّ منها للبالغين.","h2":"لا يجوز للسائقين الذين يحملون تصريح التعلّم أو الرخصة المتوسطة استخدام الهاتف المحمول أثناء القيادة، حتى يبقى كل انتباههم على الطريق.","p":"صحيح. السائقون الجدد في Tennessee لا يستخدمون الهاتف أثناء القيادة."},"ref":{"doc":"TN","page":18}},{"id":"tn-013","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, what does the hands-free law forbid for all drivers?","o":["Using a phone mounted on the dashboard","Making a call with an earpiece","Holding a phone with any part of the body","Calling 911 in an emergency"],"h1":"Your hands, and even your shoulder, must stay free of the phone.","h2":"Tennessee’s hands-free law forbids every driver from holding a phone with any part of the body while driving.","p":"Right. Drivers may not hold a phone with any part of the body."},"es":{"q":"En Tennessee, ¿qué prohíbe la ley de manos libres a todos los conductores?","o":["Usar un teléfono montado en el tablero","Hacer una llamada con un audífono","Sostener el teléfono con cualquier parte del cuerpo","Llamar al 911 en una emergencia"],"h1":"Sus manos, y hasta su hombro, deben quedar libres del teléfono.","h2":"La ley de manos libres de Tennessee prohíbe a todo conductor sostener un teléfono con cualquier parte del cuerpo mientras maneja.","p":"Correcto. No puede sostener el teléfono con ninguna parte del cuerpo."},"zh":{"q":"在 Tennessee，免手持法（hands-free law）禁止所有司机做什么？","o":["使用固定在仪表板上的手机","用耳机打电话","用身体的任何部位拿着手机","紧急情况时拨打 911"],"h1":"你的手，甚至你的肩膀，都不能拿着手机。","h2":"Tennessee 的免手持法禁止每一位司机在开车时用身体的任何部位拿着手机。","p":"对。司机不可以用身体的任何部位拿着手机。"},"vi":{"q":"Ở Tennessee, luật rảnh tay (hands-free law) cấm tất cả tài xế làm gì?","o":["Dùng điện thoại gắn trên bảng điều khiển","Gọi điện bằng tai nghe","Cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể","Gọi 911 khi khẩn cấp"],"h1":"Tay của bạn, và cả vai của bạn, không được giữ điện thoại.","h2":"Luật rảnh tay của Tennessee cấm mọi tài xế cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể khi lái xe.","p":"Đúng. Tài xế không được cầm điện thoại bằng bất kỳ bộ phận nào của cơ thể."},"tl":{"q":"Sa Tennessee, ano ang ipinagbabawal ng hands-free law sa lahat ng driver?","o":["Paggamit ng teleponong nakakabit sa dashboard","Pagtawag gamit ang earpiece","Paghawak ng telepono gamit ang anumang bahagi ng katawan","Pagtawag sa 911 sa emergency"],"h1":"Ang mga kamay mo, at pati ang balikat mo, ay dapat walang hawak na telepono.","h2":"Ipinagbabawal ng hands-free law ng Tennessee sa bawat driver ang paghawak ng telepono gamit ang anumang bahagi ng katawan habang nagmamaneho.","p":"Tama. Hindi puwedeng humawak ng telepono ang driver gamit ang anumang bahagi ng katawan."},"ar":{"q":"في Tennessee، ماذا يمنع قانون عدم استخدام اليدين (hands-free law) على كل السائقين؟","o":["استخدام هاتف مثبّت على لوحة القيادة","إجراء مكالمة بسمّاعة أذن","حمل الهاتف بأي جزء من الجسم","الاتصال بالرقم 911 في حالة طوارئ"],"h1":"يداك، وحتى كتفك، يجب أن تبقى بعيدة عن الهاتف.","h2":"يمنع قانون عدم استخدام اليدين في Tennessee كل سائق من حمل الهاتف بأي جزء من الجسم أثناء القيادة.","p":"صحيح. لا يجوز للسائق حمل الهاتف بأي جزء من الجسم."},"ref":{"doc":"TN","page":30}},{"id":"tn-014","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many questions are on the knowledge test for a learner permit?","o":["30 questions","20 questions","25 questions","50 questions"],"h1":"It is a round number between 25 and 50.","h2":"The Tennessee knowledge test has 30 questions about road rules and signs.","p":"Right. The Tennessee test has 30 questions."},"es":{"q":"En Tennessee, ¿cuántas preguntas tiene el examen de conocimientos para el permiso de aprendiz?","o":["30 preguntas","20 preguntas","25 preguntas","50 preguntas"],"h1":"Es un número redondo entre 25 y 50.","h2":"El examen de conocimientos de Tennessee tiene 30 preguntas sobre reglas de tránsito y señales.","p":"Correcto. El examen de Tennessee tiene 30 preguntas."},"zh":{"q":"在 Tennessee，学习驾照的笔试有多少道题？","o":["30 道题","20 道题","25 道题","50 道题"],"h1":"是 25 和 50 之间的一个整数。","h2":"Tennessee 的笔试有 30 道关于交通规则和标志的题目。","p":"对。Tennessee 的考试有 30 道题。"},"vi":{"q":"Ở Tennessee, bài thi kiến thức để lấy giấy phép tập lái có bao nhiêu câu hỏi?","o":["30 câu hỏi","20 câu hỏi","25 câu hỏi","50 câu hỏi"],"h1":"Đó là một số tròn giữa 25 và 50.","h2":"Bài thi kiến thức của Tennessee có 30 câu hỏi về luật đi đường và biển báo.","p":"Đúng. Bài thi của Tennessee có 30 câu hỏi."},"tl":{"q":"Sa Tennessee, ilang tanong ang nasa knowledge test para sa learner permit?","o":["30 tanong","20 tanong","25 tanong","50 tanong"],"h1":"Isang buong numero ito sa pagitan ng 25 at 50.","h2":"May 30 tanong ang knowledge test ng Tennessee tungkol sa mga patakaran sa daan at mga karatula.","p":"Tama. May 30 tanong ang test ng Tennessee."},"ar":{"q":"في Tennessee، كم سؤالًا في الاختبار النظري لتصريح التعلّم؟","o":["30 سؤالًا","20 سؤالًا","25 سؤالًا","50 سؤالًا"],"h1":"هو عدد كامل بين 25 و50.","h2":"في الاختبار النظري في Tennessee يوجد 30 سؤالًا عن قواعد الطريق والإشارات.","p":"صحيح. في اختبار Tennessee يوجد 30 سؤالًا."},"ref":{"doc":"TN","page":null}},{"id":"tn-015","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, what score do you need to pass the knowledge test?","o":["At least 60 percent","At least 70 percent","At least 90 percent","At least 80 percent"],"h1":"You can miss only one question in five.","h2":"You need at least 80 percent to pass, which means 24 correct answers out of 30.","p":"Right. You need 80 percent, or 24 of 30."},"es":{"q":"En Tennessee, ¿qué puntaje necesita para aprobar el examen de conocimientos?","o":["Por lo menos 60 por ciento","Por lo menos 70 por ciento","Por lo menos 90 por ciento","Por lo menos 80 por ciento"],"h1":"Solo puede fallar una pregunta de cada cinco.","h2":"Necesita por lo menos 80 por ciento para aprobar, es decir, 24 respuestas correctas de 30.","p":"Correcto. Necesita 80 por ciento, o 24 de 30."},"zh":{"q":"在 Tennessee，笔试需要多少分才能通过？","o":["至少 60%","至少 70%","至少 90%","至少 80%"],"h1":"每五道题你只能错一道。","h2":"你需要至少 80% 才能通过，也就是 30 道题中答对 24 道。","p":"对。你需要 80%，也就是 30 道答对 24 道。"},"vi":{"q":"Ở Tennessee, bạn cần bao nhiêu điểm để đậu bài thi kiến thức?","o":["Ít nhất 60%","Ít nhất 70%","Ít nhất 90%","Ít nhất 80%"],"h1":"Bạn chỉ được sai một câu trong năm câu.","h2":"Bạn cần ít nhất 80% để đậu, nghĩa là trả lời đúng 24 trên 30 câu.","p":"Đúng. Bạn cần 80%, tức là 24 trên 30 câu."},"tl":{"q":"Sa Tennessee, anong score ang kailangan mo para pumasa sa knowledge test?","o":["Hindi bababa sa 60%","Hindi bababa sa 70%","Hindi bababa sa 90%","Hindi bababa sa 80%"],"h1":"Isang tanong lang sa bawat lima ang puwede mong mamali.","h2":"Kailangan mo ng hindi bababa sa 80% para pumasa, ibig sabihin 24 na tamang sagot sa 30.","p":"Tama. Kailangan mo ng 80%, o 24 sa 30."},"ar":{"q":"في Tennessee، ما الدرجة التي تحتاجها للنجاح في الاختبار النظري؟","o":["60% على الأقل","70% على الأقل","90% على الأقل","80% على الأقل"],"h1":"يمكنك أن تخطئ في سؤال واحد فقط من كل خمسة.","h2":"تحتاج إلى 80% على الأقل للنجاح، أي 24 إجابة صحيحة من 30.","p":"صحيح. تحتاج إلى 80%، أي 24 من 30."},"ref":{"doc":"TN","page":null}},{"id":"tn-016","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, in which languages can you take the online knowledge test?","o":["English only","English and Spanish","Spanish only","Any language you choose"],"h1":"One of them is the language of this sentence.","h2":"The online knowledge test in Tennessee is offered in English and in Spanish.","p":"Right. The online test is in English and Spanish."},"es":{"q":"En Tennessee, ¿en qué idiomas puede hacer el examen de conocimientos en línea?","o":["Solo en inglés","En inglés y en español","Solo en español","En cualquier idioma que elija"],"h1":"Uno de ellos es el idioma de esta oración.","h2":"El examen de conocimientos en línea de Tennessee se ofrece en inglés y en español.","p":"Correcto. El examen en línea está en inglés y en español."},"zh":{"q":"在 Tennessee，网上笔试可以用哪些语言参加？","o":["只有英语","英语和西班牙语","只有西班牙语","你选择的任何语言"],"h1":"其中一种是这句话原文的语言（英语）。","h2":"Tennessee 的网上笔试提供英语和西班牙语两种语言。","p":"对。网上考试有英语和西班牙语。"},"vi":{"q":"Ở Tennessee, bạn có thể làm bài thi kiến thức trực tuyến bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh và tiếng Tây Ban Nha","Chỉ tiếng Tây Ban Nha","Bất kỳ ngôn ngữ nào bạn chọn"],"h1":"Một trong số đó là ngôn ngữ gốc của câu này (tiếng Anh).","h2":"Bài thi kiến thức trực tuyến ở Tennessee có bằng tiếng Anh và tiếng Tây Ban Nha.","p":"Đúng. Bài thi trực tuyến có tiếng Anh và tiếng Tây Ban Nha."},"tl":{"q":"Sa Tennessee, sa anong mga wika puwede mong kunin ang online knowledge test?","o":["Ingles lang","Ingles at Espanyol","Espanyol lang","Kahit anong wikang piliin mo"],"h1":"Isa sa mga ito ang orihinal na wika ng pangungusap na ito (Ingles).","h2":"Ang online knowledge test sa Tennessee ay nasa Ingles at Espanyol.","p":"Tama. Nasa Ingles at Espanyol ang online test."},"ar":{"q":"في Tennessee، بأي لغات يمكنك أن تأخذ الاختبار النظري عبر الإنترنت؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية","الإسبانية فقط","أي لغة تختارها"],"h1":"إحداهما هي اللغة الأصلية لهذه الجملة (الإنجليزية).","h2":"يُقدَّم الاختبار النظري عبر الإنترنت في Tennessee باللغة الإنجليزية واللغة الإسبانية.","p":"صحيح. الاختبار عبر الإنترنت بالإنجليزية والإسبانية."},"ref":{"doc":"TN","page":null}},{"id":"tn-017","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, you approach a stopped emergency vehicle with flashing lights. What does the move-over law require?","o":["Honk to warn the crew","Stop completely in your lane","Move to a lane farther away if safe, or else slow down","Pass at the same speed in the next lane"],"h1":"Give the crew more room, or more time.","h2":"You must move into a lane away from the stopped vehicle when it is safe; if you cannot, you must slow down as you pass.","p":"Right. Move over if it is safe, or slow down."},"es":{"q":"En Tennessee, usted se acerca a un vehículo de emergencia detenido con luces intermitentes. ¿Qué exige la ley de cambio de carril?","o":["Tocar la bocina para avisar al equipo","Detenerse por completo en su carril","Pasarse a un carril más lejano si es seguro, o si no, bajar la velocidad","Pasar a la misma velocidad en el carril de al lado"],"h1":"Déle al equipo más espacio, o más tiempo.","h2":"Usted debe pasarse a un carril alejado del vehículo detenido cuando sea seguro; si no puede, debe bajar la velocidad al pasar.","p":"Correcto. Cámbiese de carril si es seguro, o baje la velocidad."},"zh":{"q":"在 Tennessee，你接近一辆停着、闪着灯的紧急车辆。让道法（move-over law）要求你做什么？","o":["按喇叭提醒工作人员","在你的车道上完全停下","如果安全，换到离它更远的车道；否则就减速","在旁边车道用同样的速度开过去"],"h1":"给工作人员更多空间，或者更多时间。","h2":"在安全时，你必须换到远离那辆停着的车的车道；如果不能换道，经过时必须减速。","p":"对。安全就换道，否则就减速。"},"vi":{"q":"Ở Tennessee, bạn đến gần một xe cấp cứu đang dừng và nháy đèn. Luật nhường làn (move-over law) yêu cầu gì?","o":["Bấm còi để báo cho nhân viên","Dừng hẳn trong làn của bạn","Chuyển sang làn xa hơn nếu an toàn, nếu không thì chạy chậm lại","Chạy qua với cùng tốc độ ở làn bên cạnh"],"h1":"Cho nhân viên thêm chỗ, hoặc thêm thời gian.","h2":"Bạn phải chuyển sang làn xa chiếc xe đang dừng khi an toàn; nếu không thể, bạn phải chạy chậm lại khi đi qua.","p":"Đúng. Chuyển làn nếu an toàn, nếu không thì chạy chậm lại."},"tl":{"q":"Sa Tennessee, papalapit ka sa nakahintong emergency vehicle na may kumikislap na ilaw. Ano ang hinihingi ng move-over law?","o":["Bumusina para balaan ang mga tauhan","Huminto nang tuluyan sa iyong lane","Lumipat sa lane na mas malayo kung ligtas, o kung hindi ay bumagal","Lumampas sa parehong bilis sa katabing lane"],"h1":"Bigyan ang mga tauhan ng mas maraming espasyo, o mas maraming oras.","h2":"Dapat kang lumipat sa lane na malayo sa nakahintong sasakyan kapag ligtas; kung hindi mo kaya, dapat kang bumagal habang dumadaan.","p":"Tama. Lumipat ng lane kung ligtas, o bumagal."},"ar":{"q":"في Tennessee، تقترب من مركبة طوارئ متوقفة وأضواؤها تومض. ماذا يطلب قانون الابتعاد (move-over law)؟","o":["استخدم البوق لتنبيه الطاقم","توقّف تمامًا في مسارك","انتقل إلى مسار أبعد إذا كان ذلك آمنًا، وإلا فخفّف السرعة","مرّ بنفس السرعة في المسار المجاور"],"h1":"أعطِ الطاقم مساحة أكبر، أو وقتًا أكثر.","h2":"يجب أن تنتقل إلى مسار بعيد عن المركبة المتوقفة عندما يكون ذلك آمنًا؛ وإذا لم تستطع، يجب أن تخفّف السرعة وأنت تمرّ.","p":"صحيح. ابتعد إذا كان ذلك آمنًا، أو خفّف السرعة."},"ref":{"doc":"TN","page":55}},{"id":"tn-018","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, besides emergency vehicles, which of these must you move over or slow down for?","o":["Any stopped vehicle with its flashing lights on","Only police cars","Only tow trucks","Only vehicles parked in a driveway"],"h1":"Since 2017 the law covers more than work vehicles.","h2":"Tennessee’s move-over law covers tow trucks, road crews, utility and garbage trucks, and also any stopped vehicle with its flashing lights on.","p":"Right. Move over or slow down for any stopped vehicle with flashing lights."},"es":{"q":"En Tennessee, además de los vehículos de emergencia, ¿por cuál de estos debe cambiarse de carril o bajar la velocidad?","o":["Cualquier vehículo detenido con sus luces intermitentes encendidas","Solo carros de policía","Solo grúas","Solo vehículos estacionados en una entrada de casa"],"h1":"Desde 2017 la ley cubre más que vehículos de trabajo.","h2":"La ley de Tennessee cubre grúas, cuadrillas de carreteras, camiones de servicios públicos y de basura, y también cualquier vehículo detenido con luces intermitentes.","p":"Correcto. Cámbiese de carril o baje la velocidad por cualquier vehículo detenido con luces intermitentes."},"zh":{"q":"在 Tennessee，除了紧急车辆，你还必须为下面哪一种车换道或减速？","o":["任何停着、开着闪灯的车辆","只有警车","只有拖车","只有停在车道（driveway）上的车辆"],"h1":"从 2017 年起，这条法律不只包括工作车辆。","h2":"Tennessee 的让道法包括拖车、道路工作人员、公用事业车和垃圾车，也包括任何停着、开着闪灯的车辆。","p":"对。遇到任何停着、开着闪灯的车辆，都要换道或减速。"},"vi":{"q":"Ở Tennessee, ngoài xe cấp cứu, bạn còn phải chuyển làn hoặc chạy chậm lại cho loại xe nào dưới đây?","o":["Bất kỳ xe nào đang dừng và bật đèn nháy","Chỉ xe cảnh sát","Chỉ xe kéo","Chỉ xe đậu trong lối vào nhà (driveway)"],"h1":"Từ năm 2017, luật này áp dụng cho nhiều hơn xe công vụ.","h2":"Luật nhường làn của Tennessee áp dụng cho xe kéo, đội sửa đường, xe điện nước và xe rác, và cả bất kỳ xe nào đang dừng và bật đèn nháy.","p":"Đúng. Chuyển làn hoặc chạy chậm lại cho bất kỳ xe nào đang dừng và bật đèn nháy."},"tl":{"q":"Sa Tennessee, bukod sa mga emergency vehicle, alin dito ang dapat mong lipatan ng lane o bagalan?","o":["Anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw","Mga sasakyan ng pulis lang","Mga tow truck lang","Mga sasakyang nakaparada sa driveway lang"],"h1":"Mula 2017, sakop ng batas ang higit pa sa mga sasakyang pantrabaho.","h2":"Sakop ng move-over law ng Tennessee ang mga tow truck, road crew, utility truck at garbage truck, at pati ang anumang nakahintong sasakyan na nakabukas ang kumikislap na ilaw.","p":"Tama. Lumipat ng lane o bumagal para sa anumang nakahintong sasakyan na may kumikislap na ilaw."},"ar":{"q":"في Tennessee، بالإضافة إلى مركبات الطوارئ، لأيّ مما يلي يجب أن تبتعد أو تخفّف السرعة؟","o":["أي مركبة متوقفة أضواؤها الوامضة مشغّلة","سيارات الشرطة فقط","شاحنات السحب فقط","المركبات المتوقفة في ممر المنزل (driveway) فقط"],"h1":"منذ 2017 يشمل القانون أكثر من مركبات العمل.","h2":"يشمل قانون الابتعاد في Tennessee شاحنات السحب، وطواقم الطرق، وشاحنات المرافق والقمامة، وأيضًا أي مركبة متوقفة أضواؤها الوامضة مشغّلة.","p":"صحيح. ابتعد أو خفّف السرعة لأي مركبة متوقفة أضواؤها تومض."},"ref":{"doc":"TN","page":72}},{"id":"tn-019","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, a school bus stops with flashing red lights on the other side of a highway divided by a median. What should you do?","o":["Stop until the bus moves","Speed up to pass quickly","Stop only if children are outside","Keep going with caution; you do not need to stop"],"h1":"The median separates you from the children.","h2":"On a highway divided by a median or barrier, traffic going the other way does not need to stop for the bus but must drive with care; traffic behind the bus must stop.","p":"Right. On the far side of a divided highway, go on with caution."},"es":{"q":"En Tennessee, un autobús escolar se detiene con luces rojas intermitentes en el otro lado de una carretera dividida por un camellón. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Acelerar para pasar rápido","Detenerse solo si hay niños afuera","Seguir con precaución; no necesita detenerse"],"h1":"El camellón lo separa de los niños.","h2":"En una carretera dividida por un camellón o barrera, el tráfico que va en sentido contrario no necesita detenerse por el autobús, pero debe manejar con cuidado; el tráfico detrás del autobús sí debe detenerse.","p":"Correcto. Del otro lado de una carretera dividida, siga con precaución."},"zh":{"q":"在 Tennessee，一辆校车在有中间隔离带的公路另一边停下，闪着红灯。你应该怎么做？","o":["停下，直到校车开走","加速快速开过去","只有孩子在车外时才停","小心继续开；你不需要停车"],"h1":"中间隔离带把你和孩子们分开了。","h2":"在有中间隔离带或护栏分开的公路上，对向的车不需要为校车停下，但必须小心开车；校车后面的车必须停下。","p":"对。在分隔公路的另一边，小心继续开。"},"vi":{"q":"Ở Tennessee, một xe buýt trường học dừng lại và nháy đèn đỏ ở phía bên kia của xa lộ có dải phân cách giữa. Bạn nên làm gì?","o":["Dừng lại cho đến khi xe buýt chạy","Tăng tốc để vượt qua nhanh","Chỉ dừng nếu trẻ em đang ở ngoài","Tiếp tục đi một cách cẩn thận; bạn không cần dừng"],"h1":"Dải phân cách ngăn bạn với các em nhỏ.","h2":"Trên xa lộ có dải phân cách hoặc rào chắn ở giữa, xe đi chiều ngược lại không cần dừng cho xe buýt nhưng phải lái cẩn thận; xe phía sau xe buýt phải dừng lại.","p":"Đúng. Ở phía bên kia của xa lộ có phân cách, tiếp tục đi một cách cẩn thận."},"tl":{"q":"Sa Tennessee, huminto ang isang school bus na may kumikislap na pulang ilaw sa kabilang panig ng highway na hinahati ng median. Ano ang dapat mong gawin?","o":["Huminto hanggang umandar ang bus","Bumilis para mabilis na makalampas","Huminto lang kung may mga bata sa labas","Magpatuloy nang maingat; hindi mo kailangang huminto"],"h1":"Ang median ang naghihiwalay sa iyo at sa mga bata.","h2":"Sa highway na hinahati ng median o harang, hindi kailangang huminto para sa bus ang mga sasakyang papunta sa kabilang direksyon pero dapat magmaneho nang maingat; ang mga sasakyan sa likod ng bus ay dapat huminto.","p":"Tama. Sa kabilang panig ng hinating highway, magpatuloy nang maingat."},"ar":{"q":"في Tennessee، توقفت حافلة مدرسية وأضواؤها الحمراء تومض على الجانب الآخر من طريق سريع يفصله حاجز وسطي (median). ماذا يجب أن تفعل؟","o":["توقّف حتى تتحرك الحافلة","زِد السرعة لتمرّ بسرعة","توقّف فقط إذا كان الأطفال في الخارج","استمر بحذر؛ لا تحتاج إلى التوقف"],"h1":"الحاجز الوسطي يفصلك عن الأطفال.","h2":"على طريق سريع يفصله حاجز وسطي أو حاجز، لا تحتاج حركة المرور في الاتجاه المعاكس إلى التوقف للحافلة لكن يجب أن تقود بحذر؛ أما المركبات خلف الحافلة فيجب أن تتوقف.","p":"صحيح. على الجانب الآخر من طريق مقسوم، استمر بحذر."},"ref":{"doc":"TN","page":51}},{"id":"tn-020","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a driver 21 or older is legally drunk at what blood alcohol level?","o":["0.05 percent or more","0.08 percent or more","0.10 percent or more","0.12 percent or more"],"h1":"It is less than one tenth of one percent.","h2":"A driver 21 or older breaks Tennessee’s drunk driving law at a blood alcohol level of 0.08 percent or more.","p":"Right. The adult limit is 0.08 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre se considera legalmente ebrio a un conductor de 21 años o más?","o":["0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más","0.12 por ciento o más"],"h1":"Es menos de una décima de uno por ciento.","h2":"Un conductor de 21 años o más viola la ley de Tennessee sobre manejar ebrio con 0.08 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para adultos es 0.08 por ciento."},"zh":{"q":"在 Tennessee，21 岁或以上的司机，血液酒精浓度达到多少就算法律上的醉酒？","o":["0.05% 或以上","0.08% 或以上","0.10% 或以上","0.12% 或以上"],"h1":"比百分之一的十分之一还少。","h2":"21 岁或以上的司机，血液酒精浓度达到 0.08% 或以上，就违反了 Tennessee 的醉酒驾驶法。","p":"对。成年人的上限是 0.08%。"},"vi":{"q":"Ở Tennessee, tài xế từ 21 tuổi trở lên bị coi là say rượu theo luật ở mức nồng độ cồn trong máu nào?","o":["0.05% trở lên","0.08% trở lên","0.10% trở lên","0.12% trở lên"],"h1":"Ít hơn một phần mười của một phần trăm.","h2":"Tài xế từ 21 tuổi trở lên vi phạm luật lái xe say rượu của Tennessee khi nồng độ cồn trong máu là 0.08% trở lên.","p":"Đúng. Giới hạn cho người lớn là 0.08%."},"tl":{"q":"Sa Tennessee, ang driver na 21 pataas ay legal na lasing sa anong blood alcohol level?","o":["0.05% o higit pa","0.08% o higit pa","0.10% o higit pa","0.12% o higit pa"],"h1":"Mas mababa ito sa isang ikasampu ng isang porsyento.","h2":"Lumalabag sa batas ng Tennessee laban sa lasing na pagmamaneho ang driver na 21 pataas kapag ang blood alcohol level ay 0.08% o higit pa.","p":"Tama. Ang limitasyon para sa adulto ay 0.08%."},"ar":{"q":"في Tennessee، يُعدّ السائق الذي عمره 21 سنة أو أكثر سكرانًا قانونيًا عند أي نسبة كحول في الدم؟","o":["0.05% أو أكثر","0.08% أو أكثر","0.10% أو أكثر","0.12% أو أكثر"],"h1":"هي أقل من عُشر واحد في المئة.","h2":"السائق الذي عمره 21 سنة أو أكثر يخالف قانون القيادة تحت تأثير الكحول في Tennessee عند نسبة كحول في الدم 0.08% أو أكثر.","p":"صحيح. حدّ البالغين هو 0.08%."},"ref":{"doc":"TN","page":81}},{"id":"tn-021","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a driver under 21 breaks the law at what blood alcohol level?","o":["0.02 percent or more","0.05 percent or more","0.08 percent or more","0.10 percent or more"],"h1":"It is a very small amount, far below the adult limit.","h2":"Tennessee’s underage law makes it illegal for a driver under 21 to drive with a blood alcohol level of 0.02 percent or more.","p":"Right. The limit under 21 is 0.02 percent."},"es":{"q":"En Tennessee, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años?","o":["0.02 por ciento o más","0.05 por ciento o más","0.08 por ciento o más","0.10 por ciento o más"],"h1":"Es una cantidad muy pequeña, muy por debajo del límite de adultos.","h2":"La ley de Tennessee para menores prohíbe manejar a un conductor menor de 21 años con 0.02 por ciento o más de alcohol en la sangre.","p":"Correcto. El límite para menores de 21 es 0.02 por ciento."},"zh":{"q":"在 Tennessee，21 岁以下的司机，血液酒精浓度达到多少就违法？","o":["0.02% 或以上","0.05% 或以上","0.08% 或以上","0.10% 或以上"],"h1":"是很少的量，远低于成年人的上限。","h2":"Tennessee 的未成年人法律规定，21 岁以下的司机在血液酒精浓度 0.02% 或以上时开车是违法的。","p":"对。21 岁以下的上限是 0.02%。"},"vi":{"q":"Ở Tennessee, tài xế dưới 21 tuổi phạm luật ở mức nồng độ cồn trong máu nào?","o":["0.02% trở lên","0.05% trở lên","0.08% trở lên","0.10% trở lên"],"h1":"Đó là một lượng rất nhỏ, thấp hơn nhiều so với giới hạn của người lớn.","h2":"Luật dành cho người dưới tuổi của Tennessee cấm tài xế dưới 21 tuổi lái xe khi nồng độ cồn trong máu là 0.02% trở lên.","p":"Đúng. Giới hạn dưới 21 tuổi là 0.02%."},"tl":{"q":"Sa Tennessee, ang driver na wala pang 21 ay lumalabag sa batas sa anong blood alcohol level?","o":["0.02% o higit pa","0.05% o higit pa","0.08% o higit pa","0.10% o higit pa"],"h1":"Napakaliit na halaga ito, malayo sa ilalim ng limitasyon ng adulto.","h2":"Ayon sa batas ng Tennessee para sa mga menor de edad, bawal magmaneho ang driver na wala pang 21 kapag ang blood alcohol level ay 0.02% o higit pa.","p":"Tama. Ang limitasyon para sa wala pang 21 ay 0.02%."},"ar":{"q":"في Tennessee، السائق الذي عمره أقل من 21 سنة يخالف القانون عند أي نسبة كحول في الدم؟","o":["0.02% أو أكثر","0.05% أو أكثر","0.08% أو أكثر","0.10% أو أكثر"],"h1":"هي كمية صغيرة جدًا، أقل بكثير من حدّ البالغين.","h2":"قانون القاصرين في Tennessee يجعل من غير القانوني أن يقود سائق عمره أقل من 21 سنة بنسبة كحول في الدم 0.02% أو أكثر.","p":"صحيح. الحدّ لمن هم أقل من 21 سنة هو 0.02%."},"ref":{"doc":"TN","page":83}},{"id":"tn-022","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, what is the minimum liability insurance a driver must carry?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"The first and last numbers are the same.","h2":"Tennessee requires at least $25,000 for injury to one person, $50,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. Tennessee minimums are 25/50/25."},"es":{"q":"En Tennessee, ¿cuál es el seguro mínimo de responsabilidad que debe tener un conductor?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"El primer y el último número son iguales.","h2":"Tennessee exige por lo menos $25,000 por lesiones a una persona, $50,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. Los mínimos en Tennessee son 25/50/25."},"zh":{"q":"在 Tennessee，司机必须购买的最低责任保险是多少？","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"第一个和最后一个数字相同。","h2":"Tennessee 要求至少：一人受伤 $25,000，一次车祸中的伤害 $50,000，财产损失 $25,000。","p":"对。Tennessee 的最低标准是 25/50/25。"},"vi":{"q":"Ở Tennessee, bảo hiểm trách nhiệm tối thiểu mà tài xế phải có là bao nhiêu?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"Số đầu tiên và số cuối cùng giống nhau.","h2":"Tennessee yêu cầu ít nhất $25,000 cho thương tích của một người, $50,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Tennessee là 25/50/25."},"tl":{"q":"Sa Tennessee, ano ang pinakamababang liability insurance na dapat mayroon ang driver?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"Pareho ang una at huling numero.","h2":"Hinihingi ng Tennessee ang hindi bababa sa $25,000 para sa pinsala sa isang tao, $50,000 para sa mga pinsala sa isang banggaan, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum ng Tennessee ay 25/50/25."},"ar":{"q":"في Tennessee، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يحمله السائق؟","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $25,000","$100,000 / $300,000 / $50,000"],"h1":"الرقم الأول والرقم الأخير متساويان.","h2":"تطلب Tennessee على الأقل $25,000 لإصابة شخص واحد، و$50,000 للإصابات في حادث واحد، و$25,000 للأضرار في الممتلكات.","p":"صحيح. الحد الأدنى في Tennessee هو 25/50/25."},"ref":{"doc":"TN","page":null}},{"id":"tn-023","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, you are arrested and refuse an officer's request for an alcohol or drug test. What is the likely result?","o":["A warning letter","A $20 fine only","Nothing, if you pass a later test","Your license is suspended for 12 months"],"h1":"By driving in Tennessee, you have already agreed to be tested.","h2":"In Tennessee, refusing an alcohol or drug test after an arrest will likely lead a court to suspend your license for 12 months.","p":"Right. Refusing can cost you your license for 12 months."},"es":{"q":"En Tennessee, usted es arrestado y se niega a la prueba de alcohol o drogas que le pide un oficial. ¿Cuál es el resultado probable?","o":["Una carta de advertencia","Solo una multa de $20","Nada, si pasa una prueba después","Le suspenden la licencia por 12 meses"],"h1":"Al manejar en Tennessee, usted ya aceptó hacerse la prueba.","h2":"En Tennessee, negarse a una prueba de alcohol o drogas después de un arresto probablemente hará que un tribunal le suspenda la licencia por 12 meses.","p":"Correcto. Negarse puede costarle la licencia por 12 meses."},"zh":{"q":"在 Tennessee，你被逮捕后拒绝警察要求的酒精或药物检测。可能的结果是什么？","o":["一封警告信","只罚款 $20","如果之后的检测通过，就没事","你的驾照被吊销 12 个月"],"h1":"在 Tennessee 开车，就表示你已经同意接受检测。","h2":"在 Tennessee，被逮捕后拒绝酒精或药物检测，法院很可能会吊销你的驾照 12 个月。","p":"对。拒绝检测可能让你失去驾照 12 个月。"},"vi":{"q":"Ở Tennessee, bạn bị bắt và từ chối yêu cầu thử rượu bia hoặc ma túy của cảnh sát. Kết quả có thể là gì?","o":["Một thư cảnh cáo","Chỉ bị phạt $20","Không sao, nếu bạn đậu một lần thử sau đó","Bằng lái của bạn bị treo 12 tháng"],"h1":"Khi lái xe ở Tennessee, bạn đã đồng ý cho thử rồi.","h2":"Ở Tennessee, nếu bạn từ chối thử rượu bia hoặc ma túy sau khi bị bắt, tòa án có thể sẽ treo bằng lái của bạn 12 tháng.","p":"Đúng. Từ chối có thể làm bạn mất bằng lái 12 tháng."},"tl":{"q":"Sa Tennessee, inaresto ka at tumanggi ka sa hiling ng pulis na magpasuri para sa alak o droga. Ano ang malamang na mangyari?","o":["Isang sulat ng babala","Multa na $20 lang","Wala, kung pumasa ka sa susunod na pagsusuri","Masususpinde ang lisensya mo nang 12 buwan"],"h1":"Sa pagmamaneho sa Tennessee, pumayag ka na na masuri.","h2":"Sa Tennessee, kapag tumanggi ka sa pagsusuri para sa alak o droga pagkatapos maaresto, malamang na sususpindihin ng korte ang lisensya mo nang 12 buwan.","p":"Tama. Ang pagtanggi ay maaaring magpawala ng lisensya mo nang 12 buwan."},"ar":{"q":"في Tennessee، تم القبض عليك ورفضت طلب الشرطي إجراء فحص الكحول أو المخدرات. ما النتيجة المحتملة؟","o":["رسالة تحذير","غرامة $20 فقط","لا شيء، إذا نجحت في فحص لاحق","تُعلَّق رخصتك لمدة 12 شهرًا"],"h1":"عندما تقود في Tennessee، فأنت قد وافقت مسبقًا على إجراء الفحص.","h2":"في Tennessee، إذا رفضت فحص الكحول أو المخدرات بعد القبض عليك، فمن المحتمل أن تعلّق المحكمة رخصتك لمدة 12 شهرًا.","p":"صحيح. الرفض قد يُفقدك رخصتك لمدة 12 شهرًا."},"ref":{"doc":"TN","page":81}},{"id":"tn-024","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, after a crash with injuries or more than $400 in damage, how soon must the owner or driver send a crash report to the Department of Safety?","o":["Within 24 hours","Within 20 days","Within 6 months","Only if the police ask"],"h1":"You have about three weeks.","h2":"In Tennessee, after a crash with injury, death or more than $400 in damage, the owner or driver must file a report with the Department of Safety within 20 days.","p":"Right. File the report within 20 days."},"es":{"q":"En Tennessee, después de un choque con heridos o más de $400 en daños, ¿en cuánto tiempo debe el dueño o el conductor enviar un reporte del choque al Departamento de Seguridad?","o":["En 24 horas","En 20 días","En 6 meses","Solo si la policía lo pide"],"h1":"Tiene más o menos tres semanas.","h2":"En Tennessee, después de un choque con heridos, muertos o más de $400 en daños, el dueño o el conductor debe presentar un reporte al Departamento de Seguridad en 20 días.","p":"Correcto. Presente el reporte en 20 días."},"zh":{"q":"在 Tennessee，发生有人受伤或损失超过 $400 的车祸后，车主或司机必须在多长时间内向安全部（Department of Safety）提交车祸报告？","o":["24 小时内","20 天内","6 个月内","只有警察要求时才需要"],"h1":"你大约有三个星期。","h2":"在 Tennessee，发生有人受伤、死亡或损失超过 $400 的车祸后，车主或司机必须在 20 天内向安全部（Department of Safety）提交报告。","p":"对。要在 20 天内提交报告。"},"vi":{"q":"Ở Tennessee, sau một vụ tai nạn có người bị thương hoặc thiệt hại hơn $400, chủ xe hoặc tài xế phải gửi báo cáo tai nạn cho Sở An toàn (Department of Safety) trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 20 ngày","Trong vòng 6 tháng","Chỉ khi cảnh sát yêu cầu"],"h1":"Bạn có khoảng ba tuần.","h2":"Ở Tennessee, sau một vụ tai nạn có người bị thương, chết hoặc thiệt hại hơn $400, chủ xe hoặc tài xế phải nộp báo cáo cho Sở An toàn (Department of Safety) trong vòng 20 ngày.","p":"Đúng. Nộp báo cáo trong vòng 20 ngày."},"tl":{"q":"Sa Tennessee, pagkatapos ng banggaan na may nasaktan o pinsalang higit sa $400, gaano kabilis dapat magpadala ang may-ari o drayber ng ulat ng banggaan sa Department of Safety?","o":["Sa loob ng 24 oras","Sa loob ng 20 araw","Sa loob ng 6 na buwan","Kung hihilingin lang ng pulis"],"h1":"May mga tatlong linggo ka.","h2":"Sa Tennessee, pagkatapos ng banggaan na may nasaktan, namatay, o pinsalang higit sa $400, dapat magsumite ang may-ari o drayber ng ulat sa Department of Safety sa loob ng 20 araw.","p":"Tama. Isumite ang ulat sa loob ng 20 araw."},"ar":{"q":"في Tennessee، بعد حادث فيه إصابات أو أضرار تزيد على $400، خلال كم من الوقت يجب على المالك أو السائق إرسال تقرير الحادث إلى إدارة السلامة (Department of Safety)؟","o":["خلال 24 ساعة","خلال 20 يومًا","خلال 6 أشهر","فقط إذا طلبت الشرطة ذلك"],"h1":"لديك نحو ثلاثة أسابيع.","h2":"في Tennessee، بعد حادث فيه إصابة أو وفاة أو أضرار تزيد على $400، يجب على المالك أو السائق تقديم تقرير إلى إدارة السلامة (Department of Safety) خلال 20 يومًا.","p":"صحيح. قدّم التقرير خلال 20 يومًا."},"ref":{"doc":"TN","page":89}},{"id":"tn-025","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your home address changes. How soon must you tell the Department of Safety?","o":["Within 10 days","Within 90 days","At your next renewal","Within one year"],"h1":"It is a short time, less than two weeks.","h2":"In Tennessee you must tell the Department of Safety about a change of address within 10 days.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Tennessee, su dirección de casa cambia. ¿En cuánto tiempo debe avisar al Departamento de Seguridad?","o":["En 10 días","En 90 días","En su próxima renovación","En un año"],"h1":"Es poco tiempo, menos de dos semanas.","h2":"En Tennessee usted debe avisar al Departamento de Seguridad de un cambio de dirección en 10 días.","p":"Correcto. Avise su nueva dirección en 10 días."},"zh":{"q":"在 Tennessee，你的住址改变了。你必须在多长时间内通知安全部（Department of Safety）？","o":["10 天内","90 天内","下次更新驾照时","一年内"],"h1":"时间很短，不到两个星期。","h2":"在 Tennessee，你必须在 10 天内把地址变更通知安全部（Department of Safety）。","p":"对。要在 10 天内报告新地址。"},"vi":{"q":"Ở Tennessee, địa chỉ nhà của bạn thay đổi. Bạn phải báo cho Sở An toàn (Department of Safety) trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 90 ngày","Vào lần gia hạn tới","Trong vòng một năm"],"h1":"Đó là thời gian ngắn, chưa tới hai tuần.","h2":"Ở Tennessee, bạn phải báo cho Sở An toàn (Department of Safety) về việc đổi địa chỉ trong vòng 10 ngày.","p":"Đúng. Báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Tennessee, nagbago ang address ng bahay mo. Gaano kabilis mo dapat sabihin sa Department of Safety?","o":["Sa loob ng 10 araw","Sa loob ng 90 araw","Sa susunod mong renewal","Sa loob ng isang taon"],"h1":"Maikling panahon ito, wala pang dalawang linggo.","h2":"Sa Tennessee, dapat mong sabihin sa Department of Safety ang pagbabago ng address mo sa loob ng 10 araw.","p":"Tama. Iulat ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Tennessee، تغيّر عنوان منزلك. خلال كم من الوقت يجب أن تُبلغ إدارة السلامة (Department of Safety)؟","o":["خلال 10 أيام","خلال 90 يومًا","عند التجديد القادم","خلال سنة واحدة"],"h1":"إنها مدة قصيرة، أقل من أسبوعين.","h2":"في Tennessee يجب أن تُبلغ إدارة السلامة (Department of Safety) بتغيير عنوانك خلال 10 أيام.","p":"صحيح. أبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"TN","page":13}},{"id":"tn-026","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, a child is 6 years old and shorter than 4 feet 9 inches. How must the child ride?","o":["With a seat belt only, in any seat","In a rear-facing car seat","In a booster seat with a seat belt","On a parent's lap"],"h1":"The child is too small for an adult belt alone, but too old for a rear-facing seat.","h2":"In Tennessee, children 4 through 8 years old who are shorter than 4 feet 9 inches must ride in a booster seat and wear a seat belt.","p":"Right. A booster seat with a seat belt."},"es":{"q":"En Tennessee, un niño tiene 6 años y mide menos de 4 pies 9 pulgadas. ¿Cómo debe viajar?","o":["Solo con cinturón, en cualquier asiento","En un asiento de auto mirando hacia atrás","En un asiento elevado con cinturón de seguridad","En las piernas de su padre o madre"],"h1":"El niño es muy pequeño para usar solo el cinturón de adulto, pero muy grande para un asiento mirando hacia atrás.","h2":"En Tennessee, los niños de 4 a 8 años que miden menos de 4 pies 9 pulgadas deben viajar en un asiento elevado y usar el cinturón de seguridad.","p":"Correcto. Un asiento elevado con cinturón."},"zh":{"q":"在 Tennessee，一个孩子 6 岁，身高不到 4 英尺 9 英寸。这个孩子必须怎样乘车？","o":["只系安全带，坐任何座位都可以","坐后向式儿童安全座椅","坐增高座椅（booster seat）并系安全带","坐在父母腿上"],"h1":"孩子太小，不能只用大人的安全带，但又太大，不适合后向式座椅。","h2":"在 Tennessee，4 到 8 岁、身高不到 4 英尺 9 英寸的孩子，必须坐增高座椅（booster seat）并系安全带。","p":"对。坐增高座椅并系安全带。"},"vi":{"q":"Ở Tennessee, một đứa trẻ 6 tuổi và thấp hơn 4 feet 9 inch. Đứa trẻ phải ngồi xe như thế nào?","o":["Chỉ thắt dây an toàn, ngồi ghế nào cũng được","Ngồi ghế xe quay mặt về phía sau","Ngồi ghế nâng (booster seat) và thắt dây an toàn","Ngồi trên đùi cha mẹ"],"h1":"Đứa trẻ quá nhỏ để chỉ dùng dây an toàn của người lớn, nhưng quá lớn để ngồi ghế quay mặt về phía sau.","h2":"Ở Tennessee, trẻ từ 4 đến 8 tuổi và thấp hơn 4 feet 9 inch phải ngồi ghế nâng (booster seat) và thắt dây an toàn.","p":"Đúng. Ngồi ghế nâng và thắt dây an toàn."},"tl":{"q":"Sa Tennessee, 6 na taong gulang ang isang bata at mas maikli sa 4 feet 9 inches. Paano dapat sumakay ang bata?","o":["Seat belt lang, sa kahit anong upuan","Sa car seat na nakaharap sa likod","Sa booster seat na may seat belt","Sa kandungan ng magulang"],"h1":"Masyadong maliit ang bata para sa seat belt ng matanda lang, pero masyadong malaki na para sa upuang nakaharap sa likod.","h2":"Sa Tennessee, ang mga batang 4 hanggang 8 taong gulang na mas maikli sa 4 feet 9 inches ay dapat sumakay sa booster seat at magsuot ng seat belt.","p":"Tama. Booster seat na may seat belt."},"ar":{"q":"في Tennessee، طفل عمره 6 سنوات وطوله أقل من 4 أقدام و9 بوصات. كيف يجب أن يركب الطفل؟","o":["بحزام الأمان فقط، في أي مقعد","في مقعد سيارة مواجه للخلف","في مقعد رافع (booster seat) مع حزام الأمان","في حضن أحد الوالدين"],"h1":"الطفل صغير جدًا على حزام الكبار وحده، لكنه كبير على المقعد المواجه للخلف.","h2":"في Tennessee، يجب على الأطفال من عمر 4 إلى 8 سنوات الذين طولهم أقل من 4 أقدام و9 بوصات أن يركبوا في مقعد رافع (booster seat) وأن يربطوا حزام الأمان.","p":"صحيح. مقعد رافع مع حزام الأمان."},"ref":{"doc":"TN","page":31}},{"id":"tn-027","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how often does a driver license expire for a person over 21?","o":["Every 2 years","Every 8 years","Every 15 years","Never"],"h1":"It lasts more than five years.","h2":"In Tennessee a driver license for a person over 21 expires every 8 years from the date it was issued.","p":"Right. Every 8 years."},"es":{"q":"En Tennessee, ¿cada cuánto vence la licencia de conducir de una persona mayor de 21 años?","o":["Cada 2 años","Cada 8 años","Cada 15 años","Nunca"],"h1":"Dura más de cinco años.","h2":"En Tennessee la licencia de conducir de una persona mayor de 21 años vence cada 8 años desde la fecha en que se emitió.","p":"Correcto. Cada 8 años."},"zh":{"q":"在 Tennessee，21 岁以上的人的驾照多久过期一次？","o":["每 2 年","每 8 年","每 15 年","永远不过期"],"h1":"有效期超过五年。","h2":"在 Tennessee，21 岁以上的人的驾照从发证日期起每 8 年过期一次。","p":"对。每 8 年。"},"vi":{"q":"Ở Tennessee, bằng lái của người trên 21 tuổi hết hạn bao lâu một lần?","o":["Mỗi 2 năm","Mỗi 8 năm","Mỗi 15 năm","Không bao giờ"],"h1":"Nó kéo dài hơn năm năm.","h2":"Ở Tennessee, bằng lái của người trên 21 tuổi hết hạn mỗi 8 năm, tính từ ngày cấp.","p":"Đúng. Mỗi 8 năm."},"tl":{"q":"Sa Tennessee, gaano kadalas mag-expire ang driver license ng taong higit 21 taong gulang?","o":["Tuwing 2 taon","Tuwing 8 taon","Tuwing 15 taon","Hindi kailanman"],"h1":"Tumatagal ito nang higit sa limang taon.","h2":"Sa Tennessee, nag-e-expire ang driver license ng taong higit 21 taong gulang tuwing 8 taon mula sa petsa na ibinigay ito.","p":"Tama. Tuwing 8 taon."},"ar":{"q":"في Tennessee، كل كم تنتهي رخصة القيادة لشخص عمره أكثر من 21 سنة؟","o":["كل سنتين (2)","كل 8 سنوات","كل 15 سنة","لا تنتهي أبدًا"],"h1":"تدوم أكثر من خمس سنوات.","h2":"في Tennessee تنتهي رخصة القيادة لشخص عمره أكثر من 21 سنة كل 8 سنوات من تاريخ إصدارها.","p":"صحيح. كل 8 سنوات."},"ref":{"doc":"TN","page":11}},{"id":"tn-028","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, you fail the knowledge test. How long must you wait before you try again?","o":["One week","At least one day","30 days","Six months"],"h1":"The wait is short, just enough time to study again.","h2":"In Tennessee, you must wait at least one day after failing the knowledge test before you take it again.","p":"Right. At least one day."},"es":{"q":"En Tennessee, usted no aprueba el examen de conocimientos. ¿Cuánto tiempo debe esperar para intentarlo otra vez?","o":["Una semana","Al menos un día","30 días","Seis meses"],"h1":"La espera es corta, solo para que pueda estudiar otra vez.","h2":"En Tennessee, debe esperar al menos un día después de reprobar el examen de conocimientos antes de tomarlo otra vez.","p":"Correcto. Al menos un día."},"zh":{"q":"在 Tennessee，你笔试没有通过。你要等多久才能再考一次？","o":["一个星期","至少一天","30 天","六个月"],"h1":"等的时间很短，刚好够你再复习一下。","h2":"在 Tennessee，笔试没有通过以后，你必须至少等一天才能再考。","p":"对。至少一天。"},"vi":{"q":"Ở Tennessee, bạn thi trượt bài thi lý thuyết. Bạn phải chờ bao lâu mới được thi lại?","o":["Một tuần","Ít nhất một ngày","30 ngày","Sáu tháng"],"h1":"Thời gian chờ ngắn, vừa đủ để học lại.","h2":"Ở Tennessee, sau khi thi trượt bài thi lý thuyết, bạn phải chờ ít nhất một ngày rồi mới được thi lại.","p":"Đúng. Ít nhất một ngày."},"tl":{"q":"Sa Tennessee, bumagsak ka sa knowledge test. Gaano katagal ka dapat maghintay bago ka sumubok ulit?","o":["Isang linggo","Hindi bababa sa isang araw","30 araw","Anim na buwan"],"h1":"Maikli ang paghihintay, sapat lang para mag-aral ulit.","h2":"Sa Tennessee, dapat kang maghintay nang hindi bababa sa isang araw pagkatapos bumagsak sa knowledge test bago ka kumuha ulit nito.","p":"Tama. Hindi bababa sa isang araw."},"ar":{"q":"في Tennessee، رسبت في الاختبار النظري. كم يجب أن تنتظر قبل أن تحاول مرة أخرى؟","o":["أسبوع واحد","يوم واحد على الأقل","30 يومًا","ستة أشهر"],"h1":"الانتظار قصير، يكفي فقط لتدرس مرة أخرى.","h2":"في Tennessee، يجب أن تنتظر يومًا واحدًا على الأقل بعد الرسوب في الاختبار النظري قبل أن تعيده.","p":"صحيح. يوم واحد على الأقل."},"ref":{"doc":"TN","page":22}},{"id":"tn-029","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, you are following another vehicle at night with your high beams on. Within what distance must you dim them?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is about the length of one city block.","h2":"In Tennessee, you must dim your high beams when you are following another vehicle within 500 feet, and also when an oncoming vehicle is within 500 feet.","p":"Right. Within 500 feet."},"es":{"q":"En Tennessee, usted va detrás de otro vehículo de noche con las luces altas encendidas. ¿A qué distancia debe bajarlas?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es más o menos el largo de una cuadra de ciudad.","h2":"En Tennessee, debe bajar las luces altas cuando va detrás de otro vehículo a menos de 500 pies, y también cuando un vehículo que viene de frente está a menos de 500 pies.","p":"Correcto. A menos de 500 pies."},"zh":{"q":"在 Tennessee，你晚上开着远光灯跟在另一辆车后面。在多远的距离以内你必须把远光灯调暗？","o":["100 英尺","200 英尺","500 英尺","1,000 英尺"],"h1":"大约是城市里一个街区的长度。","h2":"在 Tennessee，当你跟在另一辆车后面 500 英尺以内时，你必须把远光灯调暗；对面来车在 500 英尺以内时也一样。","p":"对。500 英尺以内。"},"vi":{"q":"Ở Tennessee, bạn đang chạy sau một xe khác vào ban đêm và bật đèn pha. Trong khoảng cách bao nhiêu bạn phải hạ đèn xuống?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"Khoảng bằng chiều dài một dãy nhà trong thành phố.","h2":"Ở Tennessee, bạn phải hạ đèn pha khi chạy sau một xe khác trong vòng 500 feet, và cả khi có xe chạy ngược chiều trong vòng 500 feet.","p":"Đúng. Trong vòng 500 feet."},"tl":{"q":"Sa Tennessee, sumusunod ka sa ibang sasakyan sa gabi at nakabukas ang high beams mo. Sa loob ng anong layo mo dapat hinaan ang mga ito?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"Halos kasinghaba ito ng isang block sa lungsod.","h2":"Sa Tennessee, dapat mong hinaan ang high beams mo kapag sumusunod ka sa ibang sasakyan sa loob ng 500 feet, at gayundin kapag may paparating na sasakyan sa loob ng 500 feet.","p":"Tama. Sa loob ng 500 feet."},"ar":{"q":"في Tennessee، تسير خلف سيارة أخرى ليلًا والأضواء العالية مُشغّلة. ضمن أي مسافة يجب أن تخفضها؟","o":["100 قدم","200 قدم","500 قدم","1,000 قدم"],"h1":"إنها تقريبًا طول مربع سكني واحد في المدينة.","h2":"في Tennessee، يجب أن تخفض الأضواء العالية عندما تسير خلف سيارة أخرى ضمن 500 قدم، وأيضًا عندما تقترب سيارة من الاتجاه المقابل ضمن 500 قدم.","p":"صحيح. ضمن 500 قدم."},"ref":{"doc":"TN","page":45}},{"id":"tn-030","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, you may not park within how many feet of a fire hydrant?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In Tennessee, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay 15 feet away."},"es":{"q":"En Tennessee, ¿a menos de cuántos pies de un hidrante no puede estacionarse?","o":["15 pies","5 pies","10 pies","30 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Tennessee, no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese a 15 pies."},"zh":{"q":"在 Tennessee，你不可以把车停在离消防栓多少英尺以内的地方？","o":["15 英尺","5 英尺","10 英尺","30 英尺"],"h1":"消防车需要空间来接水管。","h2":"在 Tennessee，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。要离开 15 英尺。"},"vi":{"q":"Ở Tennessee, bạn không được đậu xe trong vòng bao nhiêu feet tính từ trụ nước cứu hỏa?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Xe cứu hỏa cần chỗ để nối ống nước.","h2":"Ở Tennessee, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Đậu cách xa 15 feet."},"tl":{"q":"Sa Tennessee, hindi ka puwedeng pumarada sa loob ng ilang feet mula sa fire hydrant?","o":["15 feet","5 feet","10 feet","30 feet"],"h1":"Kailangan ng mga fire truck ng espasyo para ikabit ang kanilang mga hose.","h2":"Sa Tennessee, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang 15 feet."},"ar":{"q":"في Tennessee، لا يجوز لك أن تركن ضمن كم قدمًا من صنبور إطفاء الحريق؟","o":["15 قدمًا","5 أقدام","10 أقدام","30 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل خراطيمها.","h2":"في Tennessee، لا يجوز لك أن تركن ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا."},"ref":{"doc":"TN","page":65}},{"id":"tn-031","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, littering fines start at $50. How high can they go?","o":["$100","$500","$1,000","$3,000"],"h1":"The fine grows with the amount of litter, and it can be very large.","h2":"In Tennessee, littering fines start at $50 and can reach $3,000, depending on how much litter there is.","p":"Right. Up to $3,000."},"es":{"q":"En Tennessee, las multas por tirar basura empiezan en $50. ¿Hasta cuánto pueden llegar?","o":["$100","$500","$1,000","$3,000"],"h1":"La multa sube según la cantidad de basura, y puede ser muy alta.","h2":"En Tennessee, las multas por tirar basura empiezan en $50 y pueden llegar a $3,000, según la cantidad de basura.","p":"Correcto. Hasta $3,000."},"zh":{"q":"在 Tennessee，乱扔垃圾的罚款从 $50 起。最高可以罚多少？","o":["$100","$500","$1,000","$3,000"],"h1":"罚款会随着垃圾的多少而增加，而且可能非常高。","h2":"在 Tennessee，乱扔垃圾的罚款从 $50 起，最高可以到 $3,000，要看垃圾有多少。","p":"对。最高 $3,000。"},"vi":{"q":"Ở Tennessee, tiền phạt xả rác bắt đầu từ $50. Tiền phạt có thể lên cao đến mức nào?","o":["$100","$500","$1,000","$3,000"],"h1":"Tiền phạt tăng theo lượng rác, và có thể rất lớn.","h2":"Ở Tennessee, tiền phạt xả rác bắt đầu từ $50 và có thể lên đến $3,000, tùy theo lượng rác nhiều hay ít.","p":"Đúng. Lên đến $3,000."},"tl":{"q":"Sa Tennessee, nagsisimula sa $50 ang multa sa pagkakalat ng basura. Gaano ito kataas puwedeng umabot?","o":["$100","$500","$1,000","$3,000"],"h1":"Lumalaki ang multa ayon sa dami ng basura, at puwede itong maging napakalaki.","h2":"Sa Tennessee, nagsisimula sa $50 ang multa sa pagkakalat ng basura at puwedeng umabot sa $3,000, depende sa dami ng basura.","p":"Tama. Hanggang $3,000."},"ar":{"q":"في Tennessee، تبدأ غرامات رمي النفايات من $50. إلى أي حد يمكن أن ترتفع؟","o":["$100","$500","$1,000","$3,000"],"h1":"تزيد الغرامة مع كمية النفايات، ويمكن أن تكون كبيرة جدًا.","h2":"في Tennessee، تبدأ غرامات رمي النفايات من $50 ويمكن أن تصل إلى $3,000، حسب كمية النفايات.","p":"صحيح. حتى $3,000."},"ref":{"doc":"TN","page":46}},{"id":"tn-032","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, you are caught cheating on the knowledge test. How long must you wait before you may take it again?","o":["1 day","30 days","7 days","1 year"],"h1":"Cheating is treated much more strictly than simply failing.","h2":"In Tennessee, cheating on the knowledge test is an automatic fail, and you must wait 30 days before you try again.","p":"Right. You must wait 30 days."},"es":{"q":"En Tennessee, lo descubren haciendo trampa en el examen de conocimientos. ¿Cuánto tiempo debe esperar para volver a tomarlo?","o":["1 día","30 días","7 días","1 año"],"h1":"Hacer trampa se castiga mucho más que simplemente reprobar.","h2":"En Tennessee, hacer trampa en el examen de conocimientos es un reprobado automático, y debe esperar 30 días antes de intentarlo de nuevo.","p":"Correcto. Debe esperar 30 días."},"zh":{"q":"在 Tennessee，你在知识考试中被发现作弊。你要等多久才能再考？","o":["1 天","30 天","7 天","1 年"],"h1":"作弊的处理比单纯不及格严格得多。","h2":"在 Tennessee，知识考试作弊会被自动判为不及格，你必须等 30 天才能再考。","p":"对。你必须等 30 天。"},"vi":{"q":"Ở Tennessee, bạn bị phát hiện gian lận trong bài thi kiến thức. Bạn phải chờ bao lâu mới được thi lại?","o":["1 ngày","30 ngày","7 ngày","1 năm"],"h1":"Gian lận bị xử lý nghiêm hơn nhiều so với chỉ thi rớt.","h2":"Ở Tennessee, gian lận trong bài thi kiến thức là tự động rớt, và bạn phải chờ 30 ngày mới được thi lại.","p":"Đúng. Bạn phải chờ 30 ngày."},"tl":{"q":"Sa Tennessee, nahuli kang nandaraya sa knowledge test. Gaano katagal ka dapat maghintay bago mo ito kunin ulit?","o":["1 araw","30 araw","7 araw","1 taon"],"h1":"Mas mahigpit ang parusa sa pandaraya kaysa sa simpleng hindi pagpasa.","h2":"Sa Tennessee, awtomatikong bagsak ang pandaraya sa knowledge test, at dapat kang maghintay ng 30 araw bago sumubok ulit.","p":"Tama. Dapat kang maghintay ng 30 araw."},"ar":{"q":"في Tennessee، تم ضبطك وأنت تغشّ في اختبار المعرفة. كم يجب أن تنتظر قبل أن تعيده؟","o":["1 يوم","30 يومًا","7 أيام","1 سنة"],"h1":"يُعامَل الغش بصرامة أكبر بكثير من مجرد الرسوب.","h2":"في Tennessee، الغش في اختبار المعرفة رسوب تلقائي، ويجب أن تنتظر 30 يومًا قبل أن تحاول مرة أخرى.","p":"صحيح. يجب أن تنتظر 30 يومًا."},"ref":{"doc":"TN","page":21}},{"id":"tn-033","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, what vision do you need to pass the vision screening for a license?","o":["20/100 in at least one eye","20/60 with both eyes together only","20/200 in each eye","20/40 in each eye and with both eyes together"],"h1":"Each eye is checked on its own, and then both eyes are checked together. Glasses or contact lenses are allowed.","h2":"In Tennessee, you need at least 20/40 vision in each eye and with both eyes together, with or without glasses or contact lenses.","p":"Right. 20/40 in each eye and both together."},"es":{"q":"En Tennessee, ¿qué visión necesita para aprobar el examen de la vista para una licencia?","o":["20/100 en al menos un ojo","20/60 solo con los dos ojos juntos","20/200 en cada ojo","20/40 en cada ojo y con los dos ojos juntos"],"h1":"Se revisa cada ojo por separado, y luego los dos ojos juntos. Se permiten anteojos o lentes de contacto.","h2":"En Tennessee, necesita una visión de al menos 20/40 en cada ojo y con los dos ojos juntos, con o sin anteojos o lentes de contacto.","p":"Correcto. 20/40 en cada ojo y con los dos juntos."},"zh":{"q":"在 Tennessee，要通过驾照的视力检查，你需要什么样的视力？","o":["至少一只眼睛 20/100","只要两只眼睛一起 20/60","每只眼睛 20/200","每只眼睛和两只眼睛一起都是 20/40"],"h1":"先分别检查每只眼睛，再一起检查两只眼睛。可以戴眼镜或隐形眼镜。","h2":"在 Tennessee，你的每只眼睛和两只眼睛一起都需要至少 20/40 的视力，戴不戴眼镜或隐形眼镜都可以。","p":"对。每只眼睛和两只一起都是 20/40。"},"vi":{"q":"Ở Tennessee, bạn cần thị lực như thế nào để đậu bài kiểm tra thị lực khi lấy bằng lái?","o":["20/100 ở ít nhất một mắt","20/60 chỉ khi nhìn bằng cả hai mắt","20/200 ở mỗi mắt","20/40 ở mỗi mắt và khi nhìn bằng cả hai mắt"],"h1":"Từng mắt được kiểm tra riêng, rồi kiểm tra cả hai mắt cùng lúc. Được phép đeo kính hoặc kính áp tròng.","h2":"Ở Tennessee, bạn cần thị lực ít nhất 20/40 ở mỗi mắt và khi nhìn bằng cả hai mắt, có hoặc không có kính hoặc kính áp tròng.","p":"Đúng. 20/40 ở mỗi mắt và cả hai mắt cùng lúc."},"tl":{"q":"Sa Tennessee, anong paningin ang kailangan mo para pumasa sa vision screening para sa lisensya?","o":["20/100 sa hindi bababa sa isang mata","20/60 kapag magkasama lang ang dalawang mata","20/200 sa bawat mata","20/40 sa bawat mata at kapag magkasama ang dalawang mata"],"h1":"Sinusuri nang hiwalay ang bawat mata, tapos sabay ang dalawang mata. Puwede ang salamin sa mata o contact lens.","h2":"Sa Tennessee, kailangan mo ng paninging hindi bababa sa 20/40 sa bawat mata at kapag magkasama ang dalawang mata, may salamin man o contact lens o wala.","p":"Tama. 20/40 sa bawat mata at sa dalawang mata nang magkasama."},"ar":{"q":"في Tennessee، ما قوة النظر التي تحتاجها لتنجح في فحص النظر للحصول على رخصة؟","o":["20/100 في عين واحدة على الأقل","20/60 بالعينين معًا فقط","20/200 في كل عين","20/40 في كل عين وبالعينين معًا"],"h1":"تُفحص كل عين وحدها، ثم تُفحص العينان معًا. يُسمح بالنظارات أو العدسات اللاصقة.","h2":"في Tennessee، تحتاج إلى نظر 20/40 على الأقل في كل عين وبالعينين معًا، مع النظارات أو العدسات اللاصقة أو بدونها.","p":"صحيح. 20/40 في كل عين وبالعينين معًا."},"ref":{"doc":"TN","page":21}},{"id":"tn-034","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your license has been expired for 5 years. What must you do to get a license again?","o":["Pay the late fee and pass the vision, knowledge and road tests","Only pay a $5 late fee","Only pass a vision test","Nothing, because there is a grace period"],"h1":"After this long, the state wants to check all your skills again.","h2":"In Tennessee, if you go 5 years without renewing, you must pay the late fee and pass the vision, knowledge and road tests again.","p":"Right. You pay the late fee and take all the tests again."},"es":{"q":"En Tennessee, su licencia lleva 5 años vencida. ¿Qué debe hacer para obtener una licencia otra vez?","o":["Pagar el recargo por atraso y aprobar los exámenes de la vista, de conocimientos y de manejo","Solo pagar un recargo de $5","Solo aprobar un examen de la vista","Nada, porque hay un período de gracia"],"h1":"Después de tanto tiempo, el estado quiere revisar otra vez todas sus habilidades.","h2":"En Tennessee, si pasan 5 años sin renovar, debe pagar el recargo por atraso y aprobar de nuevo los exámenes de la vista, de conocimientos y de manejo.","p":"Correcto. Paga el recargo y toma todos los exámenes de nuevo."},"zh":{"q":"在 Tennessee，你的驾照已经过期 5 年了。你要怎样才能再拿到驾照？","o":["交滞纳金，并通过视力、知识和路考","只交 $5 的滞纳金","只通过视力检查","什么都不用做，因为有宽限期"],"h1":"过了这么久，州政府要再检查一次你所有的能力。","h2":"在 Tennessee，如果你 5 年没有更新驾照，就必须交滞纳金，并重新通过视力、知识和路考。","p":"对。交滞纳金，并重新参加所有考试。"},"vi":{"q":"Ở Tennessee, bằng lái của bạn đã hết hạn 5 năm. Bạn phải làm gì để có bằng lái lại?","o":["Trả phí trễ hạn và đậu bài kiểm tra thị lực, bài thi kiến thức và bài thi lái xe","Chỉ trả phí trễ hạn $5","Chỉ đậu bài kiểm tra thị lực","Không cần làm gì, vì có thời gian ân hạn"],"h1":"Sau thời gian dài như vậy, tiểu bang muốn kiểm tra lại tất cả kỹ năng của bạn.","h2":"Ở Tennessee, nếu bạn để 5 năm không gia hạn, bạn phải trả phí trễ hạn và đậu lại bài kiểm tra thị lực, bài thi kiến thức và bài thi lái xe.","p":"Đúng. Bạn trả phí trễ hạn và thi lại tất cả các bài."},"tl":{"q":"Sa Tennessee, 5 taon nang expired ang lisensya mo. Ano ang dapat mong gawin para magkaroon ulit ng lisensya?","o":["Magbayad ng late fee at pumasa sa vision test, knowledge test at road test","Magbayad lang ng $5 na late fee","Pumasa lang sa vision test","Wala, dahil may grace period"],"h1":"Pagkatapos ng ganito katagal, gusto ng estado na suriin ulit ang lahat ng kakayahan mo.","h2":"Sa Tennessee, kung 5 taon kang hindi nag-renew, dapat kang magbayad ng late fee at pumasa ulit sa vision test, knowledge test at road test.","p":"Tama. Magbabayad ka ng late fee at kukunin ulit ang lahat ng test."},"ar":{"q":"في Tennessee، انتهت صلاحية رخصتك منذ 5 سنوات. ماذا يجب أن تفعل لتحصل على رخصة مرة أخرى؟","o":["أن تدفع رسوم التأخير وتنجح في فحص النظر واختبار المعرفة واختبار القيادة","أن تدفع فقط رسوم تأخير قدرها $5","أن تنجح في فحص النظر فقط","لا شيء، لأن هناك فترة سماح"],"h1":"بعد هذه المدة الطويلة، تريد الولاية أن تفحص كل مهاراتك من جديد.","h2":"في Tennessee، إذا مرّت 5 سنوات دون تجديد، يجب أن تدفع رسوم التأخير وتنجح من جديد في فحص النظر واختبار المعرفة واختبار القيادة.","p":"صحيح. تدفع رسوم التأخير وتعيد كل الاختبارات."},"ref":{"doc":"TN","page":13}},{"id":"tn-035","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a teen with a learner permit is convicted of using a cell phone while driving. How many points go on the teen's driving record?","o":["2 points","4 points","6 points","8 points"],"h1":"It is a large number of points, the same as the number that can hold back a teen's next license.","h2":"In Tennessee, a teen with a learner permit or intermediate license who is convicted of using a cell phone while driving gets 6 points on the driving record and a $50 fine.","p":"Right. 6 points."},"es":{"q":"En Tennessee, un adolescente con permiso de aprendiz es declarado culpable de usar el celular mientras maneja. ¿Cuántos puntos se agregan a su historial de manejo?","o":["2 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Es una cantidad grande de puntos, la misma que puede retrasar la siguiente licencia de un adolescente.","h2":"En Tennessee, un adolescente con permiso de aprendiz o licencia intermedia que es declarado culpable de usar el celular mientras maneja recibe 6 puntos en su historial de manejo y una multa de $50.","p":"Correcto. 6 puntos."},"zh":{"q":"在 Tennessee，一个持学习驾照的青少年因开车时使用手机被定罪。这个青少年的驾驶记录上会加多少分？","o":["2 分","4 分","6 分","8 分"],"h1":"这是很多分，和可能推迟青少年拿下一级驾照的分数一样。","h2":"在 Tennessee，持学习驾照或中级驾照的青少年如果因开车时使用手机被定罪，驾驶记录上会加 6 分，并罚款 $50。","p":"对。6 分。"},"vi":{"q":"Ở Tennessee, một thiếu niên có giấy phép tập lái bị kết tội dùng điện thoại di động khi lái xe. Hồ sơ lái xe của thiếu niên đó bị ghi bao nhiêu điểm?","o":["2 điểm","4 điểm","6 điểm","8 điểm"],"h1":"Đó là số điểm lớn, bằng số điểm có thể làm chậm bằng lái tiếp theo của thiếu niên.","h2":"Ở Tennessee, thiếu niên có giấy phép tập lái hoặc bằng lái trung cấp bị kết tội dùng điện thoại di động khi lái xe sẽ bị ghi 6 điểm vào hồ sơ lái xe và bị phạt $50.","p":"Đúng. 6 điểm."},"tl":{"q":"Sa Tennessee, napatunayang nagkasala ang isang teen na may learner permit sa paggamit ng cell phone habang nagmamaneho. Ilang points ang ilalagay sa driving record ng teen?","o":["2 points","4 points","6 points","8 points"],"h1":"Malaking bilang ito ng points, kapareho ng bilang na puwedeng magpaantala sa susunod na lisensya ng teen.","h2":"Sa Tennessee, ang teen na may learner permit o intermediate license na napatunayang gumamit ng cell phone habang nagmamaneho ay makakakuha ng 6 points sa driving record at multang $50.","p":"Tama. 6 points."},"ar":{"q":"في Tennessee، أُدين مراهق يحمل تصريح التعلّم باستخدام الهاتف المحمول أثناء القيادة. كم نقطة تُضاف إلى سجل القيادة الخاص به؟","o":["2 نقطة","4 نقاط","6 نقاط","8 نقاط"],"h1":"هو عدد كبير من النقاط، وهو نفس العدد الذي قد يؤخّر الرخصة التالية للمراهق.","h2":"في Tennessee، المراهق الذي يحمل تصريح التعلّم أو الرخصة المتوسطة ويُدان باستخدام الهاتف المحمول أثناء القيادة تُضاف إلى سجل قيادته 6 نقاط ويدفع غرامة $50.","p":"صحيح. 6 نقاط."},"ref":{"doc":"TN","page":18}},{"id":"tn-036","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a teen with an intermediate restricted license gets a second moving violation. What must the teen do before getting the intermediate unrestricted license?","o":["Pay a $100 fine only","Complete an approved driver education class","Retake the knowledge test","Wait until age 21"],"h1":"The state wants the teen to learn more about safe driving.","h2":"In Tennessee, a teen who gets a second moving violation on an intermediate restricted license must complete an approved driver education class before getting the intermediate unrestricted license.","p":"Right. The teen must take a driver education class."},"es":{"q":"En Tennessee, un adolescente con licencia intermedia restringida recibe una segunda infracción de tránsito en movimiento. ¿Qué debe hacer antes de obtener la licencia intermedia sin restricciones?","o":["Solo pagar una multa de $100","Completar un curso aprobado de educación vial","Volver a tomar el examen de conocimientos","Esperar hasta los 21 años"],"h1":"El estado quiere que el adolescente aprenda más sobre manejar con seguridad.","h2":"En Tennessee, un adolescente que recibe una segunda infracción en movimiento con licencia intermedia restringida debe completar un curso aprobado de educación vial antes de obtener la licencia intermedia sin restricciones.","p":"Correcto. Debe tomar un curso de educación vial."},"zh":{"q":"在 Tennessee，一个持中级限制驾照的青少年第二次有行车违规。在拿到中级无限制驾照之前，这个青少年必须做什么？","o":["只交 $100 罚款","完成一门经批准的驾驶教育课","重新参加知识考试","等到 21 岁"],"h1":"州政府希望青少年多学一些安全驾驶的知识。","h2":"在 Tennessee，持中级限制驾照的青少年如果第二次有行车违规，必须先完成一门经批准的驾驶教育课，才能拿到中级无限制驾照。","p":"对。这个青少年必须上驾驶教育课。"},"vi":{"q":"Ở Tennessee, một thiếu niên có bằng lái trung cấp có hạn chế bị vi phạm khi lái xe lần thứ hai. Thiếu niên đó phải làm gì trước khi lấy bằng lái trung cấp không hạn chế?","o":["Chỉ trả tiền phạt $100","Hoàn thành một lớp giáo dục lái xe được chấp thuận","Thi lại bài thi kiến thức","Chờ đến 21 tuổi"],"h1":"Tiểu bang muốn thiếu niên học thêm về lái xe an toàn.","h2":"Ở Tennessee, thiếu niên bị vi phạm khi lái xe lần thứ hai trong lúc có bằng lái trung cấp có hạn chế phải hoàn thành một lớp giáo dục lái xe được chấp thuận trước khi lấy bằng lái trung cấp không hạn chế.","p":"Đúng. Thiếu niên phải học một lớp giáo dục lái xe."},"tl":{"q":"Sa Tennessee, nagkaroon ng ikalawang moving violation ang isang teen na may intermediate restricted license. Ano ang dapat gawin ng teen bago makuha ang intermediate unrestricted license?","o":["Magbayad lang ng $100 na multa","Tapusin ang isang aprubadong driver education class","Kunin ulit ang knowledge test","Maghintay hanggang edad 21"],"h1":"Gusto ng estado na matuto pa ang teen tungkol sa ligtas na pagmamaneho.","h2":"Sa Tennessee, ang teen na nagkaroon ng ikalawang moving violation habang may intermediate restricted license ay dapat tapusin ang isang aprubadong driver education class bago makuha ang intermediate unrestricted license.","p":"Tama. Dapat kumuha ang teen ng driver education class."},"ar":{"q":"في Tennessee، ارتكب مراهق يحمل الرخصة المتوسطة المقيّدة مخالفة سير ثانية أثناء القيادة. ماذا يجب أن يفعل قبل الحصول على الرخصة المتوسطة غير المقيّدة؟","o":["أن يدفع غرامة $100 فقط","أن يُكمل دورة معتمدة في تعليم القيادة","أن يعيد اختبار المعرفة","أن ينتظر حتى عمر 21 سنة"],"h1":"تريد الولاية أن يتعلم المراهق المزيد عن القيادة الآمنة.","h2":"في Tennessee، المراهق الذي يرتكب مخالفة سير ثانية وهو يحمل الرخصة المتوسطة المقيّدة يجب أن يُكمل دورة معتمدة في تعليم القيادة قبل الحصول على الرخصة المتوسطة غير المقيّدة.","p":"صحيح. يجب أن يأخذ المراهق دورة في تعليم القيادة."},"ref":{"doc":"TN","page":19}},{"id":"tn-037","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, when can a teen get a regular Class D license, without the word \"Intermediate\"?","o":["At age 17","After 2 years with any license","At age 21","At age 18, or sooner if the teen finishes high school or gets a GED"],"h1":"Finishing school can move this date earlier.","h2":"In Tennessee, a teen can get a regular Class D license at age 18, or sooner after graduating from high school or getting a GED, whichever comes first.","p":"Right. At 18, or sooner with a diploma or GED."},"es":{"q":"En Tennessee, ¿cuándo puede un adolescente obtener una licencia Clase D regular, sin la palabra \"Intermediate\"?","o":["A los 17 años","Después de 2 años con cualquier licencia","A los 21 años","A los 18 años, o antes si termina la escuela secundaria u obtiene un GED"],"h1":"Terminar la escuela puede adelantar esta fecha.","h2":"En Tennessee, un adolescente puede obtener una licencia Clase D regular a los 18 años, o antes si se gradúa de la escuela secundaria u obtiene un GED, lo que ocurra primero.","p":"Correcto. A los 18, o antes con diploma o GED."},"zh":{"q":"在 Tennessee，青少年什么时候可以拿到没有“Intermediate”字样的普通 Class D 驾照？","o":["17 岁","持有任何驾照 2 年以后","21 岁","18 岁，如果高中毕业或拿到 GED 可以更早"],"h1":"完成学业可以让这个时间提前。","h2":"在 Tennessee，青少年 18 岁时可以拿到普通 Class D 驾照；如果先高中毕业或拿到 GED，可以更早，以先到者为准。","p":"对。18 岁，有毕业证书或 GED 可以更早。"},"vi":{"q":"Ở Tennessee, khi nào thiếu niên có thể lấy bằng lái Class D thông thường, không có chữ \"Intermediate\"?","o":["Lúc 17 tuổi","Sau 2 năm có bất kỳ bằng lái nào","Lúc 21 tuổi","Lúc 18 tuổi, hoặc sớm hơn nếu thiếu niên tốt nghiệp trung học hoặc có GED"],"h1":"Học xong có thể làm mốc thời gian này đến sớm hơn.","h2":"Ở Tennessee, thiếu niên có thể lấy bằng lái Class D thông thường lúc 18 tuổi, hoặc sớm hơn sau khi tốt nghiệp trung học hoặc có GED, tùy điều nào đến trước.","p":"Đúng. Lúc 18 tuổi, hoặc sớm hơn nếu có bằng tốt nghiệp hoặc GED."},"tl":{"q":"Sa Tennessee, kailan makakakuha ang isang teen ng regular na Class D license, na wala nang salitang \"Intermediate\"?","o":["Sa edad na 17","Pagkatapos ng 2 taon na may kahit anong lisensya","Sa edad na 21","Sa edad na 18, o mas maaga kung matapos ng teen ang high school o makakuha ng GED"],"h1":"Puwedeng mapaaga ang petsang ito kapag natapos ang pag-aaral.","h2":"Sa Tennessee, makakakuha ang teen ng regular na Class D license sa edad na 18, o mas maaga pagkatapos magtapos ng high school o makakuha ng GED, alinman ang mauna.","p":"Tama. Sa 18, o mas maaga kung may diploma o GED."},"ar":{"q":"في Tennessee، متى يستطيع المراهق الحصول على رخصة Class D عادية، بدون كلمة \"Intermediate\"؟","o":["في عمر 17 سنة","بعد 2 سنة من حمل أي رخصة","في عمر 21 سنة","في عمر 18 سنة، أو قبل ذلك إذا أنهى المراهق المدرسة الثانوية أو حصل على GED"],"h1":"إنهاء الدراسة قد يقدّم هذا الموعد.","h2":"في Tennessee، يستطيع المراهق الحصول على رخصة Class D عادية في عمر 18 سنة، أو قبل ذلك بعد التخرج من المدرسة الثانوية أو الحصول على GED، أيهما يأتي أولًا.","p":"صحيح. في عمر 18، أو قبل ذلك مع شهادة الثانوية أو GED."},"ref":{"doc":"TN","page":14}},{"id":"tn-038","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, how must a baby under 1 year old ride in a car?","o":["In a car seat that faces the rear of the car","In a car seat that faces forward","In a booster seat with a seat belt","On an adult's lap with a seat belt"],"h1":"The baby's back takes the force of a crash best.","h2":"In Tennessee, a child under 1 year old, or any child under 20 pounds, must ride in a car seat that faces the rear of the car.","p":"Right. The car seat faces the rear."},"es":{"q":"En Tennessee, ¿cómo debe viajar en un carro un bebé de menos de 1 año?","o":["En un asiento de seguridad mirando hacia atrás","En un asiento de seguridad mirando hacia adelante","En un asiento elevado con cinturón de seguridad","En las piernas de un adulto con cinturón de seguridad"],"h1":"La espalda del bebé es la que mejor resiste la fuerza de un choque.","h2":"En Tennessee, un niño de menos de 1 año, o cualquier niño de menos de 20 libras, debe viajar en un asiento de seguridad mirando hacia atrás.","p":"Correcto. El asiento mira hacia atrás."},"zh":{"q":"在 Tennessee，不满 1 岁的婴儿必须怎样乘车？","o":["坐后向式儿童安全座椅","坐前向式儿童安全座椅","坐增高座椅并系安全带","坐在大人腿上并系安全带"],"h1":"车祸时，婴儿的背部最能承受撞击的力量。","h2":"在 Tennessee，不满 1 岁的孩子，或任何不到 20 磅的孩子，都必须坐后向式儿童安全座椅。","p":"对。安全座椅朝后。"},"vi":{"q":"Ở Tennessee, em bé dưới 1 tuổi phải ngồi xe như thế nào?","o":["Ngồi ghế xe quay mặt về phía sau","Ngồi ghế xe quay mặt về phía trước","Ngồi ghế nâng có thắt dây an toàn","Ngồi trên đùi người lớn có thắt dây an toàn"],"h1":"Lưng của em bé chịu lực va chạm tốt nhất.","h2":"Ở Tennessee, trẻ dưới 1 tuổi, hoặc bất kỳ trẻ nào nặng dưới 20 pound, phải ngồi ghế xe quay mặt về phía sau.","p":"Đúng. Ghế xe quay mặt về phía sau."},"tl":{"q":"Sa Tennessee, paano dapat sumakay sa kotse ang sanggol na wala pang 1 taong gulang?","o":["Sa car seat na nakaharap sa likod ng kotse","Sa car seat na nakaharap sa harap","Sa booster seat na may seat belt","Sa kandungan ng adulto na may seat belt"],"h1":"Ang likod ng sanggol ang pinakamahusay na sumasalo sa lakas ng banggaan.","h2":"Sa Tennessee, ang batang wala pang 1 taong gulang, o kahit anong batang wala pang 20 pounds, ay dapat sumakay sa car seat na nakaharap sa likod ng kotse.","p":"Tama. Nakaharap sa likod ang car seat."},"ar":{"q":"في Tennessee، كيف يجب أن يركب الرضيع الذي عمره أقل من 1 سنة في السيارة؟","o":["في مقعد سيارة مواجه لخلف السيارة","في مقعد سيارة مواجه للأمام","في مقعد رافع مع حزام الأمان","في حضن شخص بالغ مع حزام الأمان"],"h1":"ظهر الرضيع هو الأقدر على تحمّل قوة الاصطدام.","h2":"في Tennessee، يجب على الطفل الذي عمره أقل من 1 سنة، أو أي طفل وزنه أقل من 20 رطلًا، أن يركب في مقعد سيارة مواجه لخلف السيارة.","p":"صحيح. مقعد السيارة مواجه للخلف."},"ref":{"doc":"TN","page":31}},{"id":"tn-039","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, children under what age may not ride in the bed of a pickup truck on any road?","o":["16 years old","18 years old","6 years old","21 years old"],"h1":"It is a young age, before most children start first grade.","h2":"In Tennessee, a child under 6 years old may not ride in the bed of a pickup truck, except in a parade or for farm work.","p":"Right. Under 6, never in the truck bed."},"es":{"q":"En Tennessee, ¿los niños menores de qué edad no pueden viajar en la caja de una camioneta pickup en ninguna carretera?","o":["16 años","18 años","6 años","21 años"],"h1":"Es una edad temprana, antes de que la mayoría de los niños empiecen el primer grado.","h2":"En Tennessee, un niño menor de 6 años no puede viajar en la caja de una camioneta pickup, excepto en un desfile o en trabajos del campo.","p":"Correcto. Menores de 6, nunca en la caja de la camioneta."},"zh":{"q":"在 Tennessee，几岁以下的孩子在任何道路上都不可以坐在皮卡车的车斗里？","o":["16 岁","18 岁","6 岁","21 岁"],"h1":"这个年龄很小，大多数孩子还没上一年级。","h2":"在 Tennessee，不满 6 岁的孩子不可以坐在皮卡车的车斗里，游行或农场工作时除外。","p":"对。不满 6 岁，绝对不能坐车斗。"},"vi":{"q":"Ở Tennessee, trẻ em dưới bao nhiêu tuổi không được ngồi ở thùng sau xe bán tải trên bất kỳ con đường nào?","o":["16 tuổi","18 tuổi","6 tuổi","21 tuổi"],"h1":"Đó là độ tuổi nhỏ, trước khi phần lớn trẻ em vào lớp một.","h2":"Ở Tennessee, trẻ dưới 6 tuổi không được ngồi ở thùng sau xe bán tải, trừ khi đi diễu hành hoặc làm việc nông trại.","p":"Đúng. Dưới 6 tuổi, không bao giờ ngồi thùng xe."},"tl":{"q":"Sa Tennessee, ang mga batang wala pa sa anong edad ang hindi puwedeng sumakay sa likod (bed) ng pickup truck sa kahit anong daan?","o":["16 taong gulang","18 taong gulang","6 na taong gulang","21 taong gulang"],"h1":"Batang edad ito, bago pumasok sa Grade 1 ang karamihan ng mga bata.","h2":"Sa Tennessee, ang batang wala pang 6 na taong gulang ay hindi puwedeng sumakay sa likod ng pickup truck, maliban sa parada o sa trabaho sa bukid.","p":"Tama. Wala pang 6, hindi kailanman sa likod ng truck."},"ar":{"q":"في Tennessee، الأطفال الذين عمرهم أقل من كم سنة لا يجوز لهم الركوب في صندوق شاحنة البيك أب (pickup) على أي طريق؟","o":["16 سنة","18 سنة","6 سنوات","21 سنة"],"h1":"هو عمر صغير، قبل أن يبدأ معظم الأطفال الصف الأول.","h2":"في Tennessee، لا يجوز للطفل الذي عمره أقل من 6 سنوات أن يركب في صندوق شاحنة البيك أب، إلا في استعراض أو في العمل الزراعي.","p":"صحيح. من عمره أقل من 6 سنوات لا يركب أبدًا في صندوق الشاحنة."},"ref":{"doc":"TN","page":33}},{"id":"tn-040","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, it is against the law to leave a child alone in a car with the engine running in a public parking lot if the child is younger than what age?","o":["5 years old","7 years old","10 years old","12 years old"],"h1":"Think of a child in about first or second grade.","h2":"In Tennessee, you may not leave a child younger than 7 in a car without someone at least 13 years old if the engine is running, the keys are inside, or the child could be in danger.","p":"Right. Younger than 7."},"es":{"q":"En Tennessee, ¿es ilegal dejar a un niño solo en un carro con el motor encendido en un estacionamiento público si el niño es menor de qué edad?","o":["5 años","7 años","10 años","12 años"],"h1":"Piense en un niño de primero o segundo grado.","h2":"En Tennessee, no puede dejar a un niño menor de 7 años en un carro sin una persona de al menos 13 años si el motor está encendido, las llaves están adentro o el niño puede estar en peligro.","p":"Correcto. Menor de 7 años."},"zh":{"q":"在 Tennessee，在公共停车场把孩子单独留在发动机开着的车里是违法的，如果孩子小于几岁？","o":["5 岁","7 岁","10 岁","12 岁"],"h1":"想想大约上一年级或二年级的孩子。","h2":"在 Tennessee，如果发动机开着、钥匙在车里，或孩子可能有危险，你不可以把不满 7 岁的孩子留在车里，除非有一个至少 13 岁的人陪着。","p":"对。不满 7 岁。"},"vi":{"q":"Ở Tennessee, để một đứa trẻ một mình trong xe đang nổ máy ở bãi đậu xe công cộng là phạm luật nếu đứa trẻ nhỏ hơn bao nhiêu tuổi?","o":["5 tuổi","7 tuổi","10 tuổi","12 tuổi"],"h1":"Hãy nghĩ đến một đứa trẻ khoảng lớp một hoặc lớp hai.","h2":"Ở Tennessee, bạn không được để trẻ dưới 7 tuổi trong xe mà không có người ít nhất 13 tuổi ở cùng nếu xe đang nổ máy, chìa khóa ở trong xe, hoặc đứa trẻ có thể gặp nguy hiểm.","p":"Đúng. Dưới 7 tuổi."},"tl":{"q":"Sa Tennessee, labag sa batas na iwanang mag-isa ang bata sa kotseng umaandar ang makina sa pampublikong paradahan kung mas bata ang bata sa anong edad?","o":["5 taong gulang","7 taong gulang","10 taong gulang","12 taong gulang"],"h1":"Isipin ang batang nasa Grade 1 o Grade 2.","h2":"Sa Tennessee, hindi mo puwedeng iwan ang batang wala pang 7 taong gulang sa kotse nang walang kasamang hindi bababa sa 13 taong gulang kung umaandar ang makina, nasa loob ang susi, o puwedeng mapahamak ang bata.","p":"Tama. Wala pang 7 taong gulang."},"ar":{"q":"في Tennessee، يُخالف القانون أن تترك طفلًا وحده في سيارة محرّكها يعمل في موقف سيارات عام إذا كان عمر الطفل أقل من كم سنة؟","o":["5 سنوات","7 سنوات","10 سنوات","12 سنة"],"h1":"فكّر في طفل في الصف الأول أو الثاني تقريبًا.","h2":"في Tennessee، يجب ألّا تترك طفلًا عمره أقل من 7 سنوات في السيارة بدون شخص عمره 13 سنة على الأقل إذا كان المحرّك يعمل، أو كانت المفاتيح في الداخل، أو كان الطفل قد يكون في خطر.","p":"صحيح. أقل من 7 سنوات."},"ref":{"doc":"TN","page":33}},{"id":"tn-041","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, during which hours must your headlights be on?","o":["From sunset to sunrise","Only when it is fully dark","From 1 hour after sunset to 1 hour before sunrise","From 30 minutes after sunset to 30 minutes before sunrise"],"h1":"The time is measured in minutes from sunset and sunrise.","h2":"In Tennessee, your headlights must be on from 30 minutes after sunset until 30 minutes before sunrise.","p":"Right. 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Tennessee, ¿durante qué horas debe tener encendidas las luces delanteras?","o":["Desde la puesta del sol hasta la salida del sol","Solo cuando está completamente oscuro","Desde 1 hora después de la puesta del sol hasta 1 hora antes de la salida del sol","Desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol"],"h1":"El tiempo se cuenta en minutos desde la puesta y la salida del sol.","h2":"En Tennessee, debe tener las luces delanteras encendidas desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol.","p":"Correcto. De 30 minutos después de la puesta a 30 minutos antes de la salida del sol."},"zh":{"q":"在 Tennessee，你必须在哪些时间打开车头灯？","o":["从日落到日出","只有天完全黑的时候","从日落后 1 小时到日出前 1 小时","从日落后 30 分钟到日出前 30 分钟"],"h1":"时间是从日落和日出算起，以分钟计算。","h2":"在 Tennessee，从日落后 30 分钟到日出前 30 分钟，你必须打开车头灯。","p":"对。日落后 30 分钟到日出前 30 分钟。"},"vi":{"q":"Ở Tennessee, bạn phải bật đèn pha trong những giờ nào?","o":["Từ lúc mặt trời lặn đến lúc mặt trời mọc","Chỉ khi trời tối hẳn","Từ 1 giờ sau khi mặt trời lặn đến 1 giờ trước khi mặt trời mọc","Từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc"],"h1":"Thời gian được tính bằng phút kể từ lúc mặt trời lặn và mọc.","h2":"Ở Tennessee, bạn phải bật đèn pha từ 30 phút sau khi mặt trời lặn cho đến 30 phút trước khi mặt trời mọc.","p":"Đúng. Từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc."},"tl":{"q":"Sa Tennessee, sa anong mga oras dapat nakabukas ang headlights mo?","o":["Mula paglubog hanggang pagsikat ng araw","Kapag ganap nang madilim lang","Mula 1 oras pagkalubog ng araw hanggang 1 oras bago sumikat ang araw","Mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw"],"h1":"Binibilang ang oras sa minuto mula sa paglubog at pagsikat ng araw.","h2":"Sa Tennessee, dapat nakabukas ang headlights mo mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw.","p":"Tama. 30 minuto pagkalubog hanggang 30 minuto bago sumikat ang araw."},"ar":{"q":"في Tennessee، في أي ساعات يجب أن تكون الأضواء الأمامية مضاءة؟","o":["من غروب الشمس إلى شروقها","فقط عندما يكون الظلام كاملًا","من 1 ساعة بعد الغروب إلى 1 ساعة قبل الشروق","من 30 دقيقة بعد الغروب إلى 30 دقيقة قبل الشروق"],"h1":"يُحسب الوقت بالدقائق من غروب الشمس ومن شروقها.","h2":"في Tennessee، يجب أن تكون الأضواء الأمامية مضاءة من 30 دقيقة بعد غروب الشمس حتى 30 دقيقة قبل شروقها.","p":"صحيح. من 30 دقيقة بعد الغروب إلى 30 دقيقة قبل الشروق."},"ref":{"doc":"TN","page":45}},{"id":"tn-042","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, you are driving slowly and five or more vehicles are lined up behind you. What should you do?","o":["Turn off or pull off the road as soon as it is safe","Speed up past the speed limit","Keep going, because they must wait","Stop in your lane and wave them past"],"h1":"Let the line of traffic go by, but only where it is safe.","h2":"In Tennessee, if five or more vehicles are lined up behind your slow vehicle, you should turn off or pull off the road as soon as it is safe.","p":"Right. Pull off when it is safe and let them pass."},"es":{"q":"En Tennessee, usted maneja despacio y hay cinco o más vehículos en fila detrás de usted. ¿Qué debe hacer?","o":["Salir o apartarse de la carretera en cuanto sea seguro","Acelerar por encima del límite de velocidad","Seguir igual, porque ellos deben esperar","Detenerse en su carril y hacerles señas para que pasen"],"h1":"Deje pasar la fila de vehículos, pero solo donde sea seguro.","h2":"En Tennessee, si cinco o más vehículos van en fila detrás de su vehículo lento, debe salir o apartarse de la carretera en cuanto sea seguro.","p":"Correcto. Apártese cuando sea seguro y déjelos pasar."},"zh":{"q":"在 Tennessee，你开得很慢，后面排了五辆或更多的车。你应该怎么做？","o":["一旦安全，就转出或开到路边","加速超过限速","继续开，因为他们必须等","在你的车道上停下，挥手让他们过去"],"h1":"让排队的车过去，但只能在安全的地方。","h2":"在 Tennessee，如果你的慢车后面排了五辆或更多的车，你应该一旦安全就转出或开到路边。","p":"对。安全时靠边，让他们过去。"},"vi":{"q":"Ở Tennessee, bạn đang lái chậm và có năm xe hoặc nhiều hơn xếp hàng phía sau bạn. Bạn nên làm gì?","o":["Rẽ ra hoặc tấp vào lề ngay khi an toàn","Tăng tốc vượt quá giới hạn tốc độ","Cứ tiếp tục đi, vì họ phải chờ","Dừng lại trong làn của bạn và vẫy tay cho họ vượt"],"h1":"Hãy để hàng xe đi qua, nhưng chỉ ở nơi an toàn.","h2":"Ở Tennessee, nếu có năm xe hoặc nhiều hơn xếp hàng phía sau xe chạy chậm của bạn, bạn nên rẽ ra hoặc tấp vào lề ngay khi an toàn.","p":"Đúng. Tấp vào lề khi an toàn và để họ vượt."},"tl":{"q":"Sa Tennessee, mabagal kang nagmamaneho at lima o higit pang sasakyan ang nakapila sa likod mo. Ano ang dapat mong gawin?","o":["Lumiko palabas o tumabi sa gilid ng daan sa sandaling ligtas na","Bumilis nang lampas sa speed limit","Magpatuloy, dahil dapat silang maghintay","Huminto sa lane mo at kawayan sila para lumampas"],"h1":"Padaanin ang pila ng sasakyan, pero sa ligtas na lugar lang.","h2":"Sa Tennessee, kung lima o higit pang sasakyan ang nakapila sa likod ng mabagal mong sasakyan, dapat kang lumiko palabas o tumabi sa gilid ng daan sa sandaling ligtas na.","p":"Tama. Tumabi kapag ligtas at padaanin sila."},"ar":{"q":"في Tennessee، أنت تقود ببطء وخلفك صف من خمس مركبات أو أكثر. ماذا يجب أن تفعل؟","o":["انعطف خارج الطريق أو قف على جانبه بمجرد أن يكون ذلك آمنًا","زِد السرعة فوق الحد الأقصى","استمر، لأن عليهم أن ينتظروا","توقّف في مسارك وأشِر لهم بيدك ليمرّوا"],"h1":"دَع صف المركبات يمرّ، لكن فقط في مكان آمن.","h2":"في Tennessee، إذا كان خلف مركبتك البطيئة صف من خمس مركبات أو أكثر، يجب أن تنعطف خارج الطريق أو تقف على جانبه بمجرد أن يكون ذلك آمنًا.","p":"صحيح. قف على جانب الطريق عندما يكون ذلك آمنًا ودَعهم يمرّون."},"ref":{"doc":"TN","page":46}},{"id":"tn-043","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, how far may you drive in a shared center turn lane before you turn?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"It is about the length of a football field.","h2":"In Tennessee, you may not drive in a shared center turn lane for more than 300 feet, and you may never use it to pass.","p":"Right. No more than 300 feet."},"es":{"q":"En Tennessee, ¿qué distancia puede recorrer en un carril central compartido para girar antes de hacer el giro?","o":["50 pies","100 pies","300 pies","1,000 pies"],"h1":"Es más o menos el largo de una cancha de fútbol americano.","h2":"En Tennessee, no puede recorrer más de 300 pies en un carril central compartido para girar, y nunca puede usarlo para rebasar.","p":"Correcto. No más de 300 pies."},"zh":{"q":"在 Tennessee，转弯前你最多可以在共用中央转弯车道里开多远？","o":["50 英尺","100 英尺","300 英尺","1,000 英尺"],"h1":"大约是一个美式足球场的长度。","h2":"在 Tennessee，你在共用中央转弯车道里开的距离不可以超过 300 英尺，而且绝对不可以用它来超车。","p":"对。不超过 300 英尺。"},"vi":{"q":"Ở Tennessee, bạn được lái bao xa trong làn rẽ chung ở giữa đường trước khi rẽ?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Khoảng bằng chiều dài một sân bóng bầu dục Mỹ.","h2":"Ở Tennessee, bạn không được lái quá 300 feet trong làn rẽ chung ở giữa đường, và không bao giờ được dùng làn này để vượt xe.","p":"Đúng. Không quá 300 feet."},"tl":{"q":"Sa Tennessee, gaano kalayo ka puwedeng magmaneho sa shared center turn lane bago ka lumiko?","o":["50 feet","100 feet","300 feet","1,000 feet"],"h1":"Halos kasinghaba ito ng isang football field.","h2":"Sa Tennessee, hindi ka puwedeng magmaneho nang higit sa 300 feet sa shared center turn lane, at hindi mo ito kailanman puwedeng gamitin para lumampas.","p":"Tama. Hindi hihigit sa 300 feet."},"ar":{"q":"في Tennessee، ما المسافة التي يجوز لك أن تقطعها في مسار الانعطاف الأوسط المشترك قبل أن تنعطف؟","o":["50 قدمًا","100 قدم","300 قدم","1,000 قدم"],"h1":"هي تقريبًا طول ملعب كرة القدم الأمريكية.","h2":"في Tennessee، يجب ألّا تقود في مسار الانعطاف الأوسط المشترك أكثر من 300 قدم، ويجب ألّا تستخدمه أبدًا للتجاوز.","p":"صحيح. ليس أكثر من 300 قدم."},"ref":{"doc":"TN","page":60}},{"id":"tn-044","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, what fine can a driver get for not stopping for a stopped school bus?","o":["$50 to $100","$250 to $1,000","$1,000 to $5,000","$100 to $200"],"h1":"It is a serious crime, a Class A misdemeanor, so the fine is high.","h2":"In Tennessee, not stopping for a stopped school bus is a Class A misdemeanor, with a fine of $250 to $1,000.","p":"Right. $250 to $1,000."},"es":{"q":"En Tennessee, ¿qué multa puede recibir un conductor por no detenerse ante un autobús escolar detenido?","o":["De $50 a $100","De $250 a $1,000","De $1,000 a $5,000","De $100 a $200"],"h1":"Es un delito serio, un delito menor Clase A, así que la multa es alta.","h2":"En Tennessee, no detenerse ante un autobús escolar detenido es un delito menor Clase A, con una multa de $250 a $1,000.","p":"Correcto. De $250 a $1,000."},"zh":{"q":"在 Tennessee，司机没有为停下的校车停车，可能被罚多少钱？","o":["$50 到 $100","$250 到 $1,000","$1,000 到 $5,000","$100 到 $200"],"h1":"这是严重的罪行，属于 A 级轻罪（Class A misdemeanor），所以罚款很高。","h2":"在 Tennessee，没有为停下的校车停车属于 A 级轻罪，罚款 $250 到 $1,000。","p":"对。$250 到 $1,000。"},"vi":{"q":"Ở Tennessee, tài xế có thể bị phạt bao nhiêu tiền vì không dừng lại cho xe buýt trường học đang dừng?","o":["$50 đến $100","$250 đến $1,000","$1,000 đến $5,000","$100 đến $200"],"h1":"Đây là tội nghiêm trọng, tội nhẹ hạng A (Class A misdemeanor), nên tiền phạt cao.","h2":"Ở Tennessee, không dừng lại cho xe buýt trường học đang dừng là tội nhẹ hạng A, với tiền phạt từ $250 đến $1,000.","p":"Đúng. Từ $250 đến $1,000."},"tl":{"q":"Sa Tennessee, anong multa ang puwedeng makuha ng driver na hindi huminto para sa nakahintong school bus?","o":["$50 hanggang $100","$250 hanggang $1,000","$1,000 hanggang $5,000","$100 hanggang $200"],"h1":"Seryosong krimen ito, isang Class A misdemeanor, kaya mataas ang multa.","h2":"Sa Tennessee, ang hindi paghinto para sa nakahintong school bus ay Class A misdemeanor, na may multang $250 hanggang $1,000.","p":"Tama. $250 hanggang $1,000."},"ar":{"q":"في Tennessee، ما الغرامة التي قد يدفعها السائق إذا لم يتوقف لحافلة مدرسية متوقفة؟","o":["من $50 إلى $100","من $250 إلى $1,000","من $1,000 إلى $5,000","من $100 إلى $200"],"h1":"هي جريمة خطيرة، جنحة من الدرجة A (Class A misdemeanor)، لذلك الغرامة عالية.","h2":"في Tennessee، عدم التوقف لحافلة مدرسية متوقفة جنحة من الدرجة A، وغرامتها من $250 إلى $1,000.","p":"صحيح. من $250 إلى $1,000."},"ref":{"doc":"TN","page":51}},{"id":"tn-045","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, a blind person with a white cane is crossing the road ahead of you. How far away should you stop?","o":["At least 2 feet","At least 5 feet","At least 3 feet","At least 10 feet"],"h1":"Give the person plenty of room, and do not honk.","h2":"In Tennessee, you should stop at least 10 feet away from a blind person crossing the road and wait until the person is off the road, without using your horn.","p":"Right. Stop at least 10 feet away."},"es":{"q":"En Tennessee, una persona ciega con un bastón blanco está cruzando la calle delante de usted. ¿A qué distancia debe detenerse?","o":["Al menos a 2 pies","Al menos a 5 pies","Al menos a 3 pies","Al menos a 10 pies"],"h1":"Dele bastante espacio a la persona y no toque la bocina.","h2":"En Tennessee, debe detenerse al menos a 10 pies de una persona ciega que cruza la calle y esperar hasta que salga de la calle, sin tocar la bocina.","p":"Correcto. Deténgase al menos a 10 pies."},"zh":{"q":"在 Tennessee，一位拿着白手杖的盲人正在你前面过马路。你应该在多远的地方停车？","o":["至少 2 英尺","至少 5 英尺","至少 3 英尺","至少 10 英尺"],"h1":"给这个人留出足够的空间，也不要按喇叭。","h2":"在 Tennessee，你应该在离过马路的盲人至少 10 英尺的地方停车，等这个人走出马路，而且不要按喇叭。","p":"对。在至少 10 英尺外停车。"},"vi":{"q":"Ở Tennessee, một người mù cầm gậy trắng đang băng qua đường phía trước bạn. Bạn nên dừng xe cách bao xa?","o":["Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 3 feet","Ít nhất 10 feet"],"h1":"Hãy chừa nhiều chỗ cho người đó, và đừng bấm còi.","h2":"Ở Tennessee, bạn nên dừng xe cách người mù đang băng qua đường ít nhất 10 feet và chờ đến khi người đó ra khỏi mặt đường, không bấm còi.","p":"Đúng. Dừng xe cách ít nhất 10 feet."},"tl":{"q":"Sa Tennessee, may bulag na may puting tungkod na tumatawid sa daan sa harap mo. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 2 feet","Hindi bababa sa 5 feet","Hindi bababa sa 3 feet","Hindi bababa sa 10 feet"],"h1":"Bigyan ng maraming espasyo ang tao, at huwag bumusina.","h2":"Sa Tennessee, dapat kang huminto nang hindi bababa sa 10 feet ang layo sa bulag na tumatawid sa daan at maghintay hanggang makaalis siya sa daan, nang hindi bumubusina.","p":"Tama. Huminto nang hindi bababa sa 10 feet ang layo."},"ar":{"q":"في Tennessee، شخص كفيف يحمل عصا بيضاء يعبر الطريق أمامك. على أي مسافة يجب أن تتوقف؟","o":["2 قدم على الأقل","5 أقدام على الأقل","3 أقدام على الأقل","10 أقدام على الأقل"],"h1":"اترك للشخص مساحة كبيرة، ولا تستخدم البوق.","h2":"في Tennessee، يجب أن تتوقف على بُعد 10 أقدام على الأقل من الشخص الكفيف الذي يعبر الطريق، وأن تنتظر حتى يخرج من الطريق، بدون استخدام البوق.","p":"صحيح. توقّف على بُعد 10 أقدام على الأقل."},"ref":{"doc":"TN","page":53}},{"id":"tn-046","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, which of these vehicles must stop at every railroad crossing, even when no train is signaled?","o":["A motorcycle","A pickup truck","A school bus, even with no passengers","A rental car"],"h1":"Think of vehicles that carry children, passengers for pay, or dangerous cargo.","h2":"In Tennessee, school and church buses must stop at every railroad crossing, even with no passengers, and so must taxis and vehicles carrying dangerous cargo.","p":"Right. A school bus always stops at the tracks."},"es":{"q":"En Tennessee, ¿cuál de estos vehículos debe detenerse en todos los cruces de ferrocarril, aunque no haya señal de tren?","o":["Una motocicleta","Una camioneta pickup","Un autobús escolar, aunque no lleve pasajeros","Un carro de alquiler"],"h1":"Piense en vehículos que llevan niños, pasajeros que pagan o carga peligrosa.","h2":"En Tennessee, los autobuses escolares y de iglesia deben detenerse en todos los cruces de ferrocarril, aunque no lleven pasajeros, y también los taxis y los vehículos con carga peligrosa.","p":"Correcto. Un autobús escolar siempre se detiene en las vías."},"zh":{"q":"在 Tennessee，下面哪一种车即使没有火车信号，也必须在每个铁路道口停车？","o":["摩托车","皮卡车","校车，即使车上没有乘客","租来的汽车"],"h1":"想想载孩子、载付费乘客或载危险货物的车。","h2":"在 Tennessee，校车和教会巴士即使没有乘客，也必须在每个铁路道口停车，出租车和载危险货物的车也一样。","p":"对。校车在铁轨前一定要停。"},"vi":{"q":"Ở Tennessee, xe nào sau đây phải dừng lại ở mọi chỗ giao với đường ray xe lửa, ngay cả khi không có tín hiệu tàu đến?","o":["Xe máy","Xe bán tải","Xe buýt trường học, ngay cả khi không chở hành khách","Xe thuê"],"h1":"Hãy nghĩ đến những xe chở trẻ em, chở hành khách trả tiền, hoặc chở hàng nguy hiểm.","h2":"Ở Tennessee, xe buýt trường học và xe buýt nhà thờ phải dừng lại ở mọi chỗ giao với đường ray xe lửa, ngay cả khi không chở hành khách, và taxi cùng xe chở hàng nguy hiểm cũng vậy.","p":"Đúng. Xe buýt trường học luôn dừng lại ở đường ray."},"tl":{"q":"Sa Tennessee, alin sa mga sasakyang ito ang dapat huminto sa bawat tawiran ng riles, kahit walang senyas ng tren?","o":["Motorsiklo","Pickup truck","School bus, kahit walang pasahero","Inupahang kotse"],"h1":"Isipin ang mga sasakyang may sakay na bata, pasaherong nagbabayad, o mapanganib na kargamento.","h2":"Sa Tennessee, ang mga school bus at church bus ay dapat huminto sa bawat tawiran ng riles, kahit walang pasahero, at ganoon din ang mga taxi at mga sasakyang may mapanganib na kargamento.","p":"Tama. Laging humihinto ang school bus sa riles."},"ar":{"q":"في Tennessee، أي من هذه المركبات يجب أن تتوقف عند كل تقاطع مع سكة حديد، حتى عندما لا توجد إشارة إلى قطار؟","o":["دراجة نارية","شاحنة بيك أب (pickup)","حافلة مدرسية، حتى بدون ركاب","سيارة مستأجرة"],"h1":"فكّر في المركبات التي تنقل أطفالًا، أو ركابًا يدفعون أجرة، أو حمولة خطرة.","h2":"في Tennessee، يجب على الحافلات المدرسية وحافلات الكنائس أن تتوقف عند كل تقاطع مع سكة حديد، حتى بدون ركاب، وكذلك سيارات الأجرة والمركبات التي تحمل حمولة خطرة.","p":"صحيح. الحافلة المدرسية تتوقف دائمًا عند السكة."},"ref":{"doc":"TN","page":51}},{"id":"tn-047","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the shortest jail time for a first DUI conviction?","o":["48 hours","No jail time","30 days","6 months"],"h1":"Even a first DUI means some time in jail.","h2":"In Tennessee, a first DUI conviction means at least 48 hours in jail, or at least 7 days if the blood alcohol level was 0.20 percent or more.","p":"Right. At least 48 hours."},"es":{"q":"En Tennessee, ¿cuál es el tiempo mínimo de cárcel por una primera condena de DUI (manejar bajo los efectos del alcohol o drogas)?","o":["48 horas","Nada de cárcel","30 días","6 meses"],"h1":"Incluso un primer DUI significa algo de tiempo en la cárcel.","h2":"En Tennessee, una primera condena de DUI significa al menos 48 horas de cárcel, o al menos 7 días si el nivel de alcohol en la sangre era de 0.20 por ciento o más.","p":"Correcto. Al menos 48 horas."},"zh":{"q":"在 Tennessee，第一次 DUI（酒后或吸毒后驾驶）定罪，最少要坐多久的牢？","o":["48 小时","不用坐牢","30 天","6 个月"],"h1":"即使是第一次 DUI，也要坐一段时间的牢。","h2":"在 Tennessee，第一次 DUI 定罪至少要坐 48 小时的牢；如果血液酒精浓度是 0.20% 或以上，至少要坐 7 天。","p":"对。至少 48 小时。"},"vi":{"q":"Ở Tennessee, thời gian ngồi tù ngắn nhất cho lần đầu bị kết tội DUI (lái xe khi say rượu hoặc dùng chất gây nghiện) là bao lâu?","o":["48 giờ","Không phải ngồi tù","30 ngày","6 tháng"],"h1":"Ngay cả lần DUI đầu tiên cũng có nghĩa là phải ngồi tù một thời gian.","h2":"Ở Tennessee, lần đầu bị kết tội DUI có nghĩa là ngồi tù ít nhất 48 giờ, hoặc ít nhất 7 ngày nếu nồng độ cồn trong máu là 0.20% trở lên.","p":"Đúng. Ít nhất 48 giờ."},"tl":{"q":"Sa Tennessee, ano ang pinakamaikling panahon sa kulungan para sa unang conviction sa DUI (pagmamaneho nang lasing o lango sa droga)?","o":["48 oras","Walang kulong","30 araw","6 na buwan"],"h1":"Kahit ang unang DUI ay may kasamang panahon sa kulungan.","h2":"Sa Tennessee, ang unang conviction sa DUI ay nangangahulugang hindi bababa sa 48 oras sa kulungan, o hindi bababa sa 7 araw kung 0.20% o higit pa ang blood alcohol level.","p":"Tama. Hindi bababa sa 48 oras."},"ar":{"q":"في Tennessee، ما أقل مدة سجن لأول إدانة بـ DUI (القيادة تحت تأثير الكحول أو المخدرات)؟","o":["48 ساعة","لا سجن","30 يومًا","6 أشهر"],"h1":"حتى أول DUI يعني قضاء بعض الوقت في السجن.","h2":"في Tennessee، أول إدانة بـ DUI تعني 48 ساعة على الأقل في السجن، أو 7 أيام على الأقل إذا كانت نسبة الكحول في الدم 0.20% أو أكثر.","p":"صحيح. 48 ساعة على الأقل."},"ref":{"doc":"TN","page":82}},{"id":"tn-048","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, a driver is convicted of DUI while a child under 18 was in the car. What is the extra minimum jail time?","o":["48 hours","7 days","10 days","30 days"],"h1":"The law adds a long extra penalty to protect children.","h2":"In Tennessee, a DUI with a child under 18 in the car adds at least 30 days in jail and a fine of at least $1,000, on top of the other DUI penalties.","p":"Right. At least 30 more days in jail."},"es":{"q":"En Tennessee, un conductor es condenado por DUI y había un niño menor de 18 años en el carro. ¿Cuál es el tiempo mínimo de cárcel adicional?","o":["48 horas","7 días","10 días","30 días"],"h1":"La ley agrega un castigo largo para proteger a los niños.","h2":"En Tennessee, un DUI con un niño menor de 18 años en el carro agrega al menos 30 días de cárcel y una multa de al menos $1,000, además de los otros castigos por DUI.","p":"Correcto. Al menos 30 días más de cárcel."},"zh":{"q":"在 Tennessee，一名司机因 DUI 被定罪，当时车里有一个不满 18 岁的孩子。额外最少要坐多久的牢？","o":["48 小时","7 天","10 天","30 天"],"h1":"为了保护孩子，法律会额外加上很长的处罚。","h2":"在 Tennessee，DUI 时车里有不满 18 岁的孩子，除了其他 DUI 处罚之外，还要额外坐至少 30 天的牢，并罚款至少 $1,000。","p":"对。至少多坐 30 天牢。"},"vi":{"q":"Ở Tennessee, một tài xế bị kết tội DUI trong khi có một đứa trẻ dưới 18 tuổi ở trong xe. Thời gian ngồi tù thêm tối thiểu là bao lâu?","o":["48 giờ","7 ngày","10 ngày","30 ngày"],"h1":"Luật thêm một hình phạt dài để bảo vệ trẻ em.","h2":"Ở Tennessee, DUI khi có trẻ dưới 18 tuổi trong xe sẽ bị thêm ít nhất 30 ngày tù và tiền phạt ít nhất $1,000, ngoài các hình phạt DUI khác.","p":"Đúng. Thêm ít nhất 30 ngày tù."},"tl":{"q":"Sa Tennessee, napatunayang nagkasala sa DUI ang isang driver habang may batang wala pang 18 taong gulang sa kotse. Ano ang pinakamaikling dagdag na panahon sa kulungan?","o":["48 oras","7 araw","10 araw","30 araw"],"h1":"Nagdadagdag ang batas ng mahabang parusa para protektahan ang mga bata.","h2":"Sa Tennessee, ang DUI na may batang wala pang 18 taong gulang sa kotse ay nagdadagdag ng hindi bababa sa 30 araw sa kulungan at multang hindi bababa sa $1,000, bukod pa sa ibang parusa sa DUI.","p":"Tama. Hindi bababa sa 30 araw na dagdag sa kulungan."},"ar":{"q":"في Tennessee، أُدين سائق بـ DUI وكان في السيارة طفل عمره أقل من 18 سنة. ما أقل مدة سجن إضافية؟","o":["48 ساعة","7 أيام","10 أيام","30 يومًا"],"h1":"يضيف القانون عقوبة طويلة لحماية الأطفال.","h2":"في Tennessee، الـ DUI مع وجود طفل عمره أقل من 18 سنة في السيارة يضيف 30 يومًا على الأقل في السجن وغرامة لا تقل عن $1,000، فوق عقوبات DUI الأخرى.","p":"صحيح. 30 يومًا إضافية على الأقل في السجن."},"ref":{"doc":"TN","page":82}},{"id":"tn-049","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a driver age 16 to 20 is convicted of underage driving while impaired. What is the penalty?","o":["A warning letter only","Loss of the license for one year and a $250 fine","A $50 fine only","Loss of the license for 30 days"],"h1":"The license is lost for a long time, and there is also a fine.","h2":"In Tennessee, underage driving while impaired means losing your license for one year and paying a $250 fine, and sometimes public service work.","p":"Right. One year without a license and a $250 fine."},"es":{"q":"En Tennessee, un conductor de 16 a 20 años es condenado por manejar bajo los efectos del alcohol siendo menor de edad. ¿Cuál es el castigo?","o":["Solo una carta de advertencia","Perder la licencia por un año y una multa de $250","Solo una multa de $50","Perder la licencia por 30 días"],"h1":"Se pierde la licencia por mucho tiempo, y también hay una multa.","h2":"En Tennessee, manejar bajo los efectos del alcohol siendo menor de 21 años significa perder la licencia por un año y pagar una multa de $250, y a veces hacer servicio comunitario.","p":"Correcto. Un año sin licencia y una multa de $250."},"zh":{"q":"在 Tennessee，一名 16 到 20 岁的司机因未成年饮酒后驾驶（underage driving while impaired）被定罪。处罚是什么？","o":["只有一封警告信","吊销驾照一年，并罚款 $250","只罚款 $50","吊销驾照 30 天"],"h1":"驾照会被吊销很长时间，还要交罚款。","h2":"在 Tennessee，未成年饮酒后驾驶会被吊销驾照一年，并罚款 $250，有时还要做社区服务。","p":"对。一年没有驾照，并罚款 $250。"},"vi":{"q":"Ở Tennessee, một tài xế từ 16 đến 20 tuổi bị kết tội lái xe khi đã uống rượu lúc chưa đủ tuổi (underage driving while impaired). Hình phạt là gì?","o":["Chỉ một thư cảnh cáo","Mất bằng lái một năm và bị phạt $250","Chỉ bị phạt $50","Mất bằng lái 30 ngày"],"h1":"Bằng lái bị mất trong thời gian dài, và còn có tiền phạt.","h2":"Ở Tennessee, lái xe khi đã uống rượu lúc chưa đủ tuổi có nghĩa là mất bằng lái một năm và trả tiền phạt $250, đôi khi còn phải làm công tác phục vụ cộng đồng.","p":"Đúng. Một năm không có bằng lái và tiền phạt $250."},"tl":{"q":"Sa Tennessee, napatunayang nagkasala ang isang driver na 16 hanggang 20 taong gulang sa underage driving while impaired (pagmamaneho nang nakainom habang menor de edad). Ano ang parusa?","o":["Sulat ng babala lang","Pagkawala ng lisensya nang isang taon at multang $250","Multang $50 lang","Pagkawala ng lisensya nang 30 araw"],"h1":"Matagal na mawawala ang lisensya, at may multa rin.","h2":"Sa Tennessee, ang underage driving while impaired ay nangangahulugang mawawalan ka ng lisensya nang isang taon at magbabayad ng multang $250, at kung minsan ay community service.","p":"Tama. Isang taon na walang lisensya at multang $250."},"ar":{"q":"في Tennessee، أُدين سائق عمره من 16 إلى 20 سنة بالقيادة تحت تأثير الكحول وهو قاصر (underage driving while impaired). ما العقوبة؟","o":["رسالة تحذير فقط","سحب الرخصة لمدة سنة وغرامة $250","غرامة $50 فقط","سحب الرخصة لمدة 30 يومًا"],"h1":"تُسحب الرخصة لمدة طويلة، وهناك غرامة أيضًا.","h2":"في Tennessee، القيادة تحت تأثير الكحول للقاصر تعني سحب رخصتك لمدة سنة ودفع غرامة $250، وأحيانًا خدمة المجتمع.","p":"صحيح. سنة بدون رخصة وغرامة $250."},"ref":{"doc":"TN","page":83}},{"id":"tn-050","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a person age 18 to 20 is convicted of buying alcohol. They were not driving. What happens to their driving privilege?","o":["They lose it for one year","Nothing, because they were not driving","They pay a $50 fine only","They lose it for 30 days"],"h1":"This law applies even when no car is involved.","h2":"In Tennessee, a person age 18 to 20 convicted of buying or having alcohol loses the privilege to drive for one year, even if they were not driving.","p":"Right. They lose it for one year."},"es":{"q":"En Tennessee, una persona de 18 a 20 años es condenada por comprar alcohol. No estaba manejando. ¿Qué pasa con su privilegio de manejar?","o":["Lo pierde por un año","Nada, porque no estaba manejando","Solo paga una multa de $50","Lo pierde por 30 días"],"h1":"Esta ley se aplica aunque no haya ningún carro de por medio.","h2":"En Tennessee, una persona de 18 a 20 años condenada por comprar o tener alcohol pierde el privilegio de manejar por un año, aunque no estuviera manejando.","p":"Correcto. Lo pierde por un año."},"zh":{"q":"在 Tennessee，一个 18 到 20 岁的人因购买酒类被定罪。他们当时没有开车。他们的驾驶权会怎样？","o":["失去驾驶权一年","没事，因为他们没有开车","只罚款 $50","失去驾驶权 30 天"],"h1":"即使和汽车无关，这条法律也适用。","h2":"在 Tennessee，18 到 20 岁的人如果因购买或持有酒类被定罪，即使没有开车，也会失去驾驶权一年。","p":"对。失去驾驶权一年。"},"vi":{"q":"Ở Tennessee, một người từ 18 đến 20 tuổi bị kết tội mua rượu. Họ không lái xe. Quyền lái xe của họ sẽ ra sao?","o":["Họ bị mất quyền lái xe một năm","Không sao, vì họ không lái xe","Họ chỉ bị phạt $50","Họ bị mất quyền lái xe 30 ngày"],"h1":"Luật này áp dụng ngay cả khi không liên quan đến xe.","h2":"Ở Tennessee, người từ 18 đến 20 tuổi bị kết tội mua hoặc có rượu sẽ mất quyền lái xe một năm, ngay cả khi họ không lái xe.","p":"Đúng. Họ mất quyền lái xe một năm."},"tl":{"q":"Sa Tennessee, napatunayang nagkasala sa pagbili ng alak ang isang taong 18 hanggang 20 taong gulang. Hindi siya nagmamaneho. Ano ang mangyayari sa pribilehiyo niyang magmaneho?","o":["Mawawala ito nang isang taon","Wala, dahil hindi siya nagmamaneho","Multang $50 lang ang babayaran niya","Mawawala ito nang 30 araw"],"h1":"Ipinapatupad ang batas na ito kahit walang sasakyang sangkot.","h2":"Sa Tennessee, ang taong 18 hanggang 20 taong gulang na napatunayang bumili o may hawak na alak ay mawawalan ng pribilehiyong magmaneho nang isang taon, kahit hindi siya nagmamaneho.","p":"Tama. Mawawala ito nang isang taon."},"ar":{"q":"في Tennessee، أُدين شخص عمره من 18 إلى 20 سنة بشراء الكحول. لم يكن يقود. ماذا يحدث لحقّه في القيادة؟","o":["يفقده لمدة سنة","لا شيء، لأنه لم يكن يقود","يدفع غرامة $50 فقط","يفقده لمدة 30 يومًا"],"h1":"ينطبق هذا القانون حتى عندما لا تكون هناك سيارة.","h2":"في Tennessee، الشخص الذي عمره من 18 إلى 20 سنة ويُدان بشراء الكحول أو حيازته يفقد حقّه في القيادة لمدة سنة، حتى لو لم يكن يقود.","p":"صحيح. يفقده لمدة سنة."},"ref":{"doc":"TN","page":83}},{"id":"tn-051","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, what is the heaviest vehicle you may drive with a regular Class D license?","o":["10,000 pounds","16,000 pounds","26,000 pounds","40,000 pounds"],"h1":"Above this weight you need a commercial license.","h2":"A Tennessee Class D license covers vehicles up to 26,000 pounds.","p":"Right. The Class D limit is 26,000 pounds."},"es":{"q":"En Tennessee, ¿cuál es el vehículo más pesado que puede manejar con una licencia Clase D normal?","o":["10,000 libras","16,000 libras","26,000 libras","40,000 libras"],"h1":"Por encima de este peso necesita una licencia comercial.","h2":"Una licencia Clase D de Tennessee cubre vehículos de hasta 26,000 libras.","p":"Correcto. El límite de la Clase D es 26,000 libras."},"ref":{"doc":"TN","page":2}},{"id":"tn-052","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your main job is driving a taxi or delivering pizzas in your own car. What must your Class D license have?","o":["A For-Hire (F) endorsement","A motorcycle (M) class","A hardship (H) class","Nothing extra"],"h1":"It is for people who drive people or goods as their job.","h2":"A Tennessee driver whose main job is carrying people or goods in a Class D vehicle needs a For-Hire endorsement.","p":"Right. Driving for hire needs the F endorsement."},"es":{"q":"En Tennessee, su trabajo principal es manejar un taxi o repartir pizzas en su propio carro. ¿Qué debe tener su licencia Clase D?","o":["Un endoso For-Hire (F)","Una clase de motocicleta (M)","Una clase de dificultad (H)","Nada adicional"],"h1":"Es para personas que transportan pasajeros o mercancía como trabajo.","h2":"En Tennessee, quien tiene como trabajo principal transportar personas o mercancía en un vehículo Clase D necesita un endoso For-Hire.","p":"Correcto. Manejar por pago requiere el endoso F."},"ref":{"doc":"TN","page":2}},{"id":"tn-053","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what license do you need for a motor-driven cycle under 125 cc?","o":["A regular Class D license","A Class M limited license","A Class PD learner permit","No license at all"],"h1":"Engine size decides which motorcycle license you need.","h2":"In Tennessee, a cycle under 125 cubic centimeters needs a Class M limited license, and a bigger one needs a full Class M.","p":"Right. Under 125 cc needs a Class M limited license."},"es":{"q":"En Tennessee, ¿qué licencia necesita para un ciclomotor de menos de 125 cc?","o":["Una licencia Clase D normal","Una licencia Clase M limitada","Un permiso de aprendiz Clase PD","Ninguna licencia"],"h1":"El tamaño del motor decide qué licencia de motocicleta necesita.","h2":"En Tennessee, un ciclomotor de menos de 125 centímetros cúbicos requiere una licencia Clase M limitada, y uno más grande requiere una Clase M completa.","p":"Correcto. Menos de 125 cc requiere una Clase M limitada."},"ref":{"doc":"TN","page":3}},{"id":"tn-054","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the youngest age for a Class H hardship license?","o":["14 years old","15 years old","13 years old","16 years old"],"h1":"It is one year younger than the learner permit age.","h2":"Tennessee may issue a Class H hardship license at age 14 in cases of family hardship.","p":"Right. A hardship license can start at 14."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para una licencia de dificultad (hardship) Clase H?","o":["14 años","15 años","13 años","16 años"],"h1":"Es un año menos que la edad del permiso de aprendiz.","h2":"Tennessee puede dar una licencia de dificultad Clase H a los 14 años en casos de necesidad familiar.","p":"Correcto. La licencia de dificultad puede empezar a los 14 años."},"ref":{"doc":"TN","page":3}},{"id":"tn-055","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, you move here with a valid license from another state. How soon must you get a Tennessee license?","o":["Within 10 days","Within 6 months","Within 1 year","Within 30 days"],"h1":"It is about one month.","h2":"A new Tennessee resident with an out-of-state license must get a Tennessee license within 30 days of moving here.","p":"Right. New residents have 30 days."},"es":{"q":"En Tennessee, usted se muda aquí con una licencia válida de otro estado. ¿En cuánto tiempo debe obtener una licencia de Tennessee?","o":["En 10 días","En 6 meses","En 1 año","En 30 días"],"h1":"Es más o menos un mes.","h2":"Un nuevo residente de Tennessee con licencia de otro estado debe obtener la licencia de Tennessee dentro de 30 días después de mudarse.","p":"Correcto. Los nuevos residentes tienen 30 días."},"ref":{"doc":"TN","page":11}},{"id":"tn-056","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what is the highest penalty for driving while your license is revoked or suspended?","o":["A $50 fine only","A $1,000 fine and/or 6 months in jail","A warning letter","A $100 fine and 2 days in jail"],"h1":"It is a Class B misdemeanor.","h2":"Driving on a revoked or suspended Tennessee license can bring a fine of up to $1,000, up to 6 months in jail, or both.","p":"Right. Up to $1,000 and 6 months in jail."},"es":{"q":"En Tennessee, ¿cuál es la pena más alta por manejar con la licencia revocada o suspendida?","o":["Solo una multa de $50","Una multa de $1,000 y/o 6 meses de cárcel","Una carta de advertencia","Una multa de $100 y 2 días de cárcel"],"h1":"Es un delito menor Clase B.","h2":"Manejar con la licencia revocada o suspendida en Tennessee puede traer una multa de hasta $1,000, hasta 6 meses de cárcel, o ambas cosas.","p":"Correcto. Hasta $1,000 y 6 meses de cárcel."},"ref":{"doc":"TN","page":4}},{"id":"tn-057","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, you have a valid license but left it at home while driving. What fine can you get?","o":["$100 to $500","Nothing, if it is valid","$2 to $50","$250 to $1,000"],"h1":"The fine is small.","h2":"In Tennessee, not having your license with you while driving can bring a fine of $2 to $50.","p":"Right. The fine is $2 to $50."},"es":{"q":"En Tennessee, tiene una licencia válida pero la dejó en casa mientras manejaba. ¿Qué multa le pueden poner?","o":["De $100 a $500","Nada, si es válida","De $2 a $50","De $250 a $1,000"],"h1":"La multa es pequeña.","h2":"En Tennessee, no llevar consigo la licencia mientras maneja puede traer una multa de $2 a $50.","p":"Correcto. La multa es de $2 a $50."},"ref":{"doc":"TN","page":4}},{"id":"tn-058","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a student age 15 or older drops out of school for the second time. When can the student apply for a license again?","o":["After 6 months","At age 18","After one school year","As soon as the student returns to school"],"h1":"There is no second chance to return to school for this.","h2":"In Tennessee, a student who drops out a second time must wait until age 18 to apply for a license again.","p":"Right. After a second dropout, the student must wait until 18."},"es":{"q":"En Tennessee, un estudiante de 15 años o más deja la escuela por segunda vez. ¿Cuándo puede volver a solicitar una licencia?","o":["Después de 6 meses","A los 18 años","Después de un año escolar","En cuanto regrese a la escuela"],"h1":"No hay segunda oportunidad de regresar a la escuela para esto.","h2":"En Tennessee, un estudiante que deja la escuela por segunda vez debe esperar hasta los 18 años para solicitar una licencia otra vez.","p":"Correcto. Después de dejar la escuela por segunda vez, debe esperar hasta los 18."},"ref":{"doc":"TN","page":17}},{"id":"tn-059","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, a driver under 18 can lose the license for dropping out of school. How many unexcused absences count as dropping out?","o":["3 days in a row","5 days in a row or 8 in a semester","20 days in a school year","10 days in a row or 15 in a semester"],"h1":"Both a \"days in a row\" number and a semester total count.","h2":"For a Tennessee license, a minor has dropped out after 10 unexcused absences in a row or 15 in one semester.","p":"Right. 10 in a row or 15 in a semester."},"es":{"q":"En Tennessee, un conductor menor de 18 puede perder la licencia por dejar la escuela. ¿Cuántas faltas sin excusa cuentan como dejar la escuela?","o":["3 días seguidos","5 días seguidos u 8 en un semestre","20 días en un año escolar","10 días seguidos o 15 en un semestre"],"h1":"Cuentan tanto los días seguidos como el total del semestre.","h2":"Para la licencia de Tennessee, un menor dejó la escuela si tiene 10 faltas sin excusa seguidas o 15 en un semestre.","p":"Correcto. 10 seguidas o 15 en un semestre."},"ref":{"doc":"TN","page":85}},{"id":"tn-060","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a driver under 18 must make \"satisfactory progress\" in school. What does that generally mean?","o":["Perfect attendance","A B average in all classes","Passing three subjects each grading period","Passing every single class"],"h1":"It is a number of subjects.","h2":"For a Tennessee license, satisfactory school progress generally means passing three subjects each grading period.","p":"Right. Passing three subjects each grading period."},"es":{"q":"En Tennessee, un conductor menor de 18 debe tener \"progreso satisfactorio\" en la escuela. ¿Qué significa eso en general?","o":["Asistencia perfecta","Un promedio de B en todas las clases","Aprobar tres materias en cada período de calificaciones","Aprobar absolutamente todas las clases"],"h1":"Es un número de materias.","h2":"Para la licencia de Tennessee, el progreso satisfactorio en general significa aprobar tres materias en cada período de calificaciones.","p":"Correcto. Aprobar tres materias en cada período."},"ref":{"doc":"TN","page":85}},{"id":"tn-061","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, the school attendance form (SF1010) is signed by a school official. For how long is it valid at the Driver Service Center?","o":["30 days","7 days","90 days","One full school year"],"h1":"It is about one month.","h2":"A Tennessee SF1010 school attendance form is valid for 30 days from the day the school official signs it.","p":"Right. The form is good for 30 days."},"es":{"q":"En Tennessee, el formulario de asistencia escolar (SF1010) lo firma un funcionario de la escuela. ¿Por cuánto tiempo es válido en el Centro de Servicio al Conductor?","o":["30 días","7 días","90 días","Un año escolar completo"],"h1":"Es más o menos un mes.","h2":"El formulario SF1010 de asistencia escolar de Tennessee es válido por 30 días desde que lo firma el funcionario de la escuela.","p":"Correcto. El formulario vale por 30 días."},"ref":{"doc":"TN","page":17}},{"id":"tn-062","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, how many documents do you need to prove your Tennessee residency when you first apply?","o":["Two","One","Three","Four"],"h1":"It is more than one.","h2":"A first-time Tennessee applicant must bring two proofs of residency, such as a utility bill and a bank statement.","p":"Right. You need two proofs of residency."},"es":{"q":"En Tennessee, ¿cuántos documentos necesita para probar que vive en Tennessee cuando solicita por primera vez?","o":["Dos","Uno","Tres","Cuatro"],"h1":"Es más de uno.","h2":"Quien solicita por primera vez en Tennessee debe traer dos pruebas de residencia, como un recibo de servicios y un estado de cuenta bancario.","p":"Correcto. Necesita dos pruebas de residencia."},"ref":{"doc":"TN","page":7}},{"id":"tn-063","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, which of these documents is NOT accepted to prove your identity?","o":["A certified birth certificate from a state","A valid U.S. passport","A military ID card","A birth certificate issued by the hospital"],"h1":"The document must come from a government office with a seal.","h2":"Tennessee does not accept hospital-issued or baptismal certificates; a birth certificate must be certified by a government agency.","p":"Right. Hospital certificates are not accepted."},"es":{"q":"En Tennessee, ¿cuál de estos documentos NO se acepta para probar su identidad?","o":["Un acta de nacimiento certificada de un estado","Un pasaporte válido de EE. UU.","Una tarjeta de identificación militar","Un certificado de nacimiento hecho por el hospital"],"h1":"El documento debe venir de una oficina del gobierno con sello.","h2":"Tennessee no acepta certificados del hospital ni de bautizo; el acta de nacimiento debe estar certificada por una agencia del gobierno.","p":"Correcto. Los certificados del hospital no se aceptan."},"ref":{"doc":"TN","page":9}},{"id":"tn-064","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, you move here and your out-of-state license expired more than 6 months ago. Which tests must you take?","o":["Only the vision screening","Only the knowledge test","Vision, knowledge and road tests","No tests, just pay the fee"],"h1":"An old, expired license does not let you skip testing.","h2":"A new Tennessee resident whose out-of-state license expired more than 6 months ago must pass the vision, knowledge and road tests.","p":"Right. All three tests are needed."},"es":{"q":"En Tennessee, usted se muda aquí y su licencia de otro estado venció hace más de 6 meses. ¿Qué exámenes debe tomar?","o":["Solo el examen de la vista","Solo el examen de conocimientos","Los exámenes de vista, de conocimientos y de manejo","Ningún examen, solo pagar"],"h1":"Una licencia vencida hace tiempo no le permite saltarse los exámenes.","h2":"Un nuevo residente de Tennessee cuya licencia de otro estado venció hace más de 6 meses debe aprobar los exámenes de vista, de conocimientos y de manejo.","p":"Correcto. Necesita los tres exámenes."},"ref":{"doc":"TN","page":11}},{"id":"tn-065","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how much does a learner permit cost for someone under 18?","o":["$5.50","$10.50","$28.00","It is free"],"h1":"It is between $10 and $11.","h2":"A Tennessee learner permit for someone under 18 costs $10.50 and lasts one year.","p":"Right. It costs $10.50."},"es":{"q":"En Tennessee, ¿cuánto cuesta el permiso de aprendiz para un menor de 18 años?","o":["$5.50","$10.50","$28.00","Es gratis"],"h1":"Está entre $10 y $11.","h2":"El permiso de aprendiz de Tennessee para un menor de 18 cuesta $10.50 y dura un año.","p":"Correcto. Cuesta $10.50."},"ref":{"doc":"TN","page":12}},{"id":"tn-066","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long is a learner permit normally valid?","o":["30 days","6 months","Until age 18","One year"],"h1":"It lasts longer than the 180 days you must hold it.","h2":"A Tennessee learner permit normally expires one year after it is issued.","p":"Right. A permit lasts one year."},"es":{"q":"En Tennessee, ¿por cuánto tiempo es válido normalmente un permiso de aprendiz?","o":["30 días","6 meses","Hasta los 18 años","Un año"],"h1":"Dura más que los 180 días que debe tenerlo.","h2":"El permiso de aprendiz de Tennessee normalmente vence un año después de emitirse.","p":"Correcto. El permiso dura un año."},"ref":{"doc":"TN","page":12}},{"id":"tn-067","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your license expired 6 weeks ago. What late fee will you pay when you renew?","o":["$5","$10","$25","No fee"],"h1":"The fee is small and doubles later.","h2":"In Tennessee, a license expired more than 30 days has a $5 late fee.","p":"Right. After 30 days the late fee is $5."},"es":{"q":"En Tennessee, su licencia venció hace 6 semanas. ¿Qué recargo por atraso pagará al renovar?","o":["$5","$10","$25","Ningún recargo"],"h1":"El recargo es pequeño y luego se duplica.","h2":"En Tennessee, una licencia vencida por más de 30 días tiene un recargo de $5.","p":"Correcto. Después de 30 días el recargo es de $5."},"ref":{"doc":"TN","page":13}},{"id":"tn-068","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, your license expired yesterday. May you still drive during a grace period?","o":["Yes, for 30 days","Yes, for 6 months","Yes, if you mailed your renewal","No, there is no grace period"],"h1":"Once the date passes, you are treated as unlicensed.","h2":"Tennessee has no grace period, so once your license expires you may not drive until you renew it.","p":"Right. There is no grace period."},"es":{"q":"En Tennessee, su licencia venció ayer. ¿Puede seguir manejando durante un período de gracia?","o":["Sí, por 30 días","Sí, por 6 meses","Sí, si envió la renovación por correo","No, no hay período de gracia"],"h1":"Cuando pasa la fecha, lo tratan como si no tuviera licencia.","h2":"Tennessee no tiene período de gracia, así que cuando vence su licencia no puede manejar hasta que la renueve.","p":"Correcto. No hay período de gracia."},"ref":{"doc":"TN","page":13}},{"id":"tn-069","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a 16-year-old is legally emancipated by marriage, military service or a court order. Which license may the teen get?","o":["Only a learner permit","An intermediate restricted license","A regular Class D license","No license until 18"],"h1":"Emancipation lets the teen skip the graduated steps.","h2":"In Tennessee, a 16-year-old emancipated by active military duty, marriage or court order may get a regular Class D license.","p":"Right. An emancipated 16-year-old may get a regular Class D."},"es":{"q":"En Tennessee, un joven de 16 años está emancipado por matrimonio, servicio militar u orden de un juez. ¿Qué licencia puede obtener?","o":["Solo un permiso de aprendiz","Una licencia intermedia restringida","Una licencia Clase D normal","Ninguna licencia hasta los 18"],"h1":"La emancipación le permite saltarse los pasos graduados.","h2":"En Tennessee, un joven de 16 años emancipado por servicio militar activo, matrimonio u orden de un juez puede obtener una licencia Clase D normal.","p":"Correcto. Un joven emancipado de 16 años puede obtener una Clase D normal."},"ref":{"doc":"TN","page":20}},{"id":"tn-070","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, what is the youngest age to move up to the intermediate unrestricted license?","o":["16 years old","16 and a half","17 years old","18 years old"],"h1":"It comes one year after the intermediate restricted license.","h2":"In Tennessee, you must be at least 17 to get the intermediate unrestricted license.","p":"Right. The intermediate unrestricted license starts at 17."},"es":{"q":"En Tennessee, ¿cuál es la edad mínima para pasar a la licencia intermedia sin restricciones?","o":["16 años","16 años y medio","17 años","18 años"],"h1":"Viene un año después de la licencia intermedia restringida.","h2":"En Tennessee, debe tener por lo menos 17 años para obtener la licencia intermedia sin restricciones.","p":"Correcto. La licencia intermedia sin restricciones empieza a los 17."},"ref":{"doc":"TN","page":14}},{"id":"tn-071","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a teen with a learner permit gets 6 or more points. What must happen before the teen can get an intermediate restricted license?","o":["Keep the permit until the record has under 6 points for 180 days in a row","Pay a $100 fine","Wait until age 18","Retake the vision test"],"h1":"The teen needs a clean stretch of time.","h2":"A Tennessee permit holder with 6 or more points must keep the permit until the record stays under 6 points for 180 days in a row.","p":"Right. The record must stay under 6 points for 180 days in a row."},"es":{"q":"En Tennessee, un joven con permiso de aprendiz acumula 6 puntos o más. ¿Qué debe pasar antes de obtener la licencia intermedia restringida?","o":["Mantener el permiso hasta tener menos de 6 puntos por 180 días seguidos","Pagar una multa de $100","Esperar hasta los 18 años","Repetir el examen de la vista"],"h1":"El joven necesita un tiempo limpio.","h2":"En Tennessee, quien tiene permiso y acumula 6 puntos o más debe mantener el permiso hasta tener menos de 6 puntos por 180 días seguidos.","p":"Correcto. Debe tener menos de 6 puntos por 180 días seguidos."},"ref":{"doc":"TN","page":19}},{"id":"tn-072","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, a teen with an intermediate restricted license gets 6 or more points. How much longer must the teen hold that license?","o":["30 more days","1 more year","6 more months","90 more days"],"h1":"It adds about three months.","h2":"In Tennessee, 6 or more points on an intermediate restricted license adds 90 days before the teen can move up.","p":"Right. It adds 90 days."},"es":{"q":"En Tennessee, un joven con licencia intermedia restringida acumula 6 puntos o más. ¿Cuánto tiempo más debe tener esa licencia?","o":["30 días más","1 año más","6 meses más","90 días más"],"h1":"Agrega unos tres meses.","h2":"En Tennessee, 6 puntos o más en una licencia intermedia restringida agregan 90 días antes de poder subir de nivel.","p":"Correcto. Agrega 90 días."},"ref":{"doc":"TN","page":19}},{"id":"tn-073","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a teen driver contributes to a crash in which someone dies. What happens to the teen's license?","o":["A $500 fine only","Only a learner permit until age 18","90 extra days on the current level","A one-week suspension"],"h1":"It is the harshest graduated-license penalty.","h2":"In Tennessee, a teen who contributes to a fatal crash may hold only a learner permit until age 18.","p":"Right. Only a learner permit until 18."},"es":{"q":"En Tennessee, un conductor joven contribuye a un choque en el que muere alguien. ¿Qué pasa con su licencia?","o":["Solo una multa de $500","Solo permiso de aprendiz hasta los 18 años","90 días extra en su nivel actual","Una suspensión de una semana"],"h1":"Es el castigo más duro de la licencia graduada.","h2":"En Tennessee, un joven que contribuye a un choque mortal solo puede tener permiso de aprendiz hasta los 18 años.","p":"Correcto. Solo permiso de aprendiz hasta los 18."},"ref":{"doc":"TN","page":16}},{"id":"tn-074","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a teen with an intermediate restricted license is caught with a fake parent letter to drive at night. What happens?","o":["A written warning","A $50 fine","The license is revoked and the teen gets only a learner permit until 18","Nothing, if the teen was not speeding"],"h1":"Forgery is treated very seriously.","h2":"In Tennessee, an intermediate restricted driver convicted of using a forged permission letter loses the license and gets only a learner permit until age 18.","p":"Right. The teen drops back to a learner permit until 18."},"es":{"q":"En Tennessee, a un joven con licencia intermedia restringida lo encuentran con una carta falsa de sus padres para manejar de noche. ¿Qué pasa?","o":["Una advertencia por escrito","Una multa de $50","Le revocan la licencia y solo tiene permiso de aprendiz hasta los 18","Nada, si no iba a exceso de velocidad"],"h1":"La falsificación se toma muy en serio.","h2":"En Tennessee, un conductor con licencia intermedia restringida que usa una carta de permiso falsa pierde la licencia y solo tiene permiso de aprendiz hasta los 18 años.","p":"Correcto. Vuelve al permiso de aprendiz hasta los 18."},"ref":{"doc":"TN","page":19}},{"id":"tn-075","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a 16-year-old with an intermediate restricted license wants to drive to go hunting at 5 a.m. When is this allowed?","o":["When the teen has a valid hunting or fishing license","Never before 6 a.m.","Only with two adult passengers","Only on weekends"],"h1":"The teen must carry a certain document.","h2":"A Tennessee intermediate restricted driver may drive to or from hunting or fishing between 4 and 6 a.m. while carrying a valid hunting or fishing license.","p":"Right. A valid hunting or fishing license allows it."},"es":{"q":"En Tennessee, un joven de 16 años con licencia intermedia restringida quiere manejar para ir de cacería a las 5 a.m. ¿Cuándo se permite?","o":["Cuando tiene una licencia válida de caza o pesca","Nunca antes de las 6 a.m.","Solo con dos pasajeros adultos","Solo los fines de semana"],"h1":"El joven debe llevar cierto documento.","h2":"En Tennessee, un conductor con licencia intermedia restringida puede manejar para ir o volver de cazar o pescar entre las 4 y las 6 a.m. si lleva una licencia válida de caza o pesca.","p":"Correcto. Una licencia válida de caza o pesca lo permite."},"ref":{"doc":"TN","page":19}},{"id":"tn-076","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, an intermediate restricted driver wants to drive two younger siblings to school. What is needed?","o":["Nothing, family is always allowed","The siblings must sit in the back seat","The siblings must be over 16","A letter from a parent allowing it, kept with the driver"],"h1":"A parent must give permission in writing.","h2":"A Tennessee intermediate restricted driver may carry siblings who live in the same home to and from school if the driver carries a parent's letter allowing it.","p":"Right. A parent's letter is needed."},"es":{"q":"En Tennessee, un conductor con licencia intermedia restringida quiere llevar a dos hermanos menores a la escuela. ¿Qué necesita?","o":["Nada, la familia siempre está permitida","Que los hermanos vayan en el asiento de atrás","Que los hermanos tengan más de 16 años","Una carta de un padre que lo permita, que el conductor lleve consigo"],"h1":"Uno de los padres debe dar permiso por escrito.","h2":"En Tennessee, un conductor con licencia intermedia restringida puede llevar a hermanos que viven en la misma casa hacia y desde la escuela si lleva una carta de un padre que lo permita.","p":"Correcto. Necesita una carta de uno de los padres."},"ref":{"doc":"TN","page":19}},{"id":"tn-077","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a teen with a learner permit is convicted of using a cell phone while driving. Besides the fine and points, what else happens?","o":["The permit is canceled for a year","The teen must retake the knowledge test","A 90-day delay before the teen can get the intermediate restricted license","Nothing else"],"h1":"It pushes back the next license step.","h2":"In Tennessee, a teen convicted of cell phone use while driving faces a 90-day delay in getting the intermediate restricted license.","p":"Right. It brings a 90-day delay."},"es":{"q":"En Tennessee, un joven con permiso de aprendiz es condenado por usar el celular mientras maneja. Además de la multa y los puntos, ¿qué más pasa?","o":["Le cancelan el permiso por un año","Debe repetir el examen de conocimientos","Un retraso de 90 días antes de poder obtener la licencia intermedia restringida","Nada más"],"h1":"Retrasa el siguiente paso de la licencia.","h2":"En Tennessee, un joven condenado por usar el celular al manejar tiene un retraso de 90 días para obtener la licencia intermedia restringida.","p":"Correcto. Hay un retraso de 90 días."},"ref":{"doc":"TN","page":18}},{"id":"tn-078","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a 16-year-old moves here with a license from another state that was issued at least 90 days ago. What license does the teen apply for?","o":["A learner permit","An intermediate restricted license","An intermediate unrestricted license","A regular Class D license"],"h1":"The teen joins the graduated program at the first license level.","h2":"In Tennessee, a 16-year-old with an out-of-state license held at least 90 days applies for an intermediate restricted license.","p":"Right. The teen applies for an intermediate restricted license."},"es":{"q":"En Tennessee, un joven de 16 años se muda aquí con una licencia de otro estado emitida hace por lo menos 90 días. ¿Qué licencia solicita?","o":["Un permiso de aprendiz","Una licencia intermedia restringida","Una licencia intermedia sin restricciones","Una licencia Clase D normal"],"h1":"Entra al programa graduado en el primer nivel de licencia.","h2":"En Tennessee, un joven de 16 años con licencia de otro estado de por lo menos 90 días solicita una licencia intermedia restringida.","p":"Correcto. Solicita la licencia intermedia restringida."},"ref":{"doc":"TN","page":16}},{"id":"tn-079","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, by law, at least how much of the knowledge test must be about alcohol and drugs?","o":["5 percent","10 percent","50 percent","25 percent"],"h1":"It is one out of every four questions.","h2":"Tennessee law requires at least 25 percent of the knowledge test questions to be about alcohol and drugs.","p":"Right. At least 25 percent."},"es":{"q":"En Tennessee, por ley, ¿por lo menos qué parte del examen de conocimientos debe tratar sobre alcohol y drogas?","o":["5 por ciento","10 por ciento","50 por ciento","25 por ciento"],"h1":"Es una de cada cuatro preguntas.","h2":"La ley de Tennessee exige que por lo menos el 25 por ciento de las preguntas del examen de conocimientos traten sobre alcohol y drogas.","p":"Correcto. Por lo menos el 25 por ciento."},"ref":{"doc":"TN","page":79}},{"id":"tn-080","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, may an interpreter help you during the driver license knowledge test?","o":["Yes, any family member","Yes, if you pay a fee","No, interpreters are not allowed","Only for the road test"],"h1":"The rule is meant to make sure you understand the test yourself.","h2":"Tennessee does not allow interpreters to help with driver license tests, except a certified sign language interpreter for a deaf applicant.","p":"Right. Interpreters are not allowed."},"es":{"q":"En Tennessee, ¿puede un intérprete ayudarle durante el examen de conocimientos para la licencia?","o":["Sí, cualquier familiar","Sí, si paga un cargo","No, no se permiten intérpretes","Solo para el examen de manejo"],"h1":"La regla busca asegurar que usted mismo entienda el examen.","h2":"Tennessee no permite intérpretes en los exámenes de licencia, excepto un intérprete certificado de lenguaje de señas para un solicitante sordo.","p":"Correcto. No se permiten intérpretes."},"ref":{"doc":"TN","page":21}},{"id":"tn-081","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a 16-year-old with a learning disability asks for an oral knowledge test. What must the teen bring?","o":["A written statement from a doctor or educational specialist","A letter from a friend","A report card","Nothing, anyone may ask"],"h1":"A professional must confirm the need.","h2":"In Tennessee, an applicant under 18 who wants an oral test needs a written statement from a physician or educational specialist about the condition.","p":"Right. A doctor or specialist must write a statement."},"es":{"q":"En Tennessee, un joven de 16 años con una dificultad de aprendizaje pide un examen oral. ¿Qué debe traer?","o":["Una declaración escrita de un médico o especialista en educación","Una carta de un amigo","Una boleta de calificaciones","Nada, cualquiera puede pedirlo"],"h1":"Un profesional debe confirmar la necesidad.","h2":"En Tennessee, un solicitante menor de 18 que quiere un examen oral necesita una declaración escrita de un médico o especialista en educación sobre su condición.","p":"Correcto. Un médico o especialista debe escribir una declaración."},"ref":{"doc":"TN","page":21}},{"id":"tn-082","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what must you pay each time you take a learner permit or license test and fail?","o":["Nothing","A $2 application fee","The full license fee again","A $25 retest fee"],"h1":"It is a very small fee.","h2":"In Tennessee, you pay a $2 application fee each time you take a PD, D or H test and fail.","p":"Right. Each failed test costs $2."},"es":{"q":"En Tennessee, ¿qué debe pagar cada vez que toma un examen de permiso o de licencia y no lo aprueba?","o":["Nada","Un cargo de solicitud de $2","Otra vez el precio completo de la licencia","Un cargo de $25 por repetir"],"h1":"Es un cargo muy pequeño.","h2":"En Tennessee, usted paga $2 de solicitud cada vez que toma un examen PD, D o H y no lo aprueba.","p":"Correcto. Cada examen reprobado cuesta $2."},"ref":{"doc":"TN","page":21}},{"id":"tn-083","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, you arrive 10 minutes late for your road test appointment. What happens?","o":["You take the test as planned","You get a shorter test","The test is canceled and you must reschedule","You pay a $5 late fee and test"],"h1":"The Driver Service Center keeps a tight schedule.","h2":"In Tennessee, a road test is canceled if you are more than 5 minutes late, and you must make a new appointment.","p":"Right. Being that late cancels the test."},"es":{"q":"En Tennessee, llega 10 minutos tarde a su cita del examen de manejo. ¿Qué pasa?","o":["Toma el examen como estaba planeado","Le hacen un examen más corto","Cancelan el examen y debe hacer otra cita","Paga un recargo de $5 y hace el examen"],"h1":"El Centro de Servicio al Conductor tiene un horario estricto.","h2":"En Tennessee, el examen de manejo se cancela si llega más de 5 minutos tarde, y debe hacer otra cita.","p":"Correcto. Llegar tan tarde cancela el examen."},"ref":{"doc":"TN","page":22}},{"id":"tn-084","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, on which day would a road test still be given?","o":["During a tornado warning","When roads are packed with snow and ice","In heavy rain and thunderstorms","In light rain"],"h1":"Only dangerous weather cancels the test.","h2":"Tennessee gives road tests in light to moderate rain, fog or snow, but not in heavy rain, thunderstorms, icy roads or severe weather warnings.","p":"Right. Light rain does not stop the road test."},"es":{"q":"En Tennessee, ¿en cuál de estos días sí se haría el examen de manejo?","o":["Durante una alerta de tornado","Cuando las calles están cubiertas de nieve y hielo","Con lluvia fuerte y tormentas eléctricas","Con lluvia ligera"],"h1":"Solo el mal tiempo peligroso cancela el examen.","h2":"Tennessee hace exámenes de manejo con lluvia, niebla o nieve ligeras o moderadas, pero no con lluvia fuerte, tormentas, calles con hielo ni alertas de mal tiempo.","p":"Correcto. La lluvia ligera no impide el examen."},"ref":{"doc":"TN","page":22}},{"id":"tn-085","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, what is the highest number of errors you can make on the road test and still pass?","o":["3 errors","6 errors","10 errors","12 errors"],"h1":"Seven or more errors means a retest.","h2":"On the Tennessee road test, 1 to 6 errors is a pass and no retest is needed.","p":"Right. Up to 6 errors is a pass."},"es":{"q":"En Tennessee, ¿cuál es el número más alto de errores que puede tener en el examen de manejo y aun así aprobar?","o":["3 errores","6 errores","10 errores","12 errores"],"h1":"Siete errores o más significa repetir el examen.","h2":"En el examen de manejo de Tennessee, de 1 a 6 errores es aprobado y no hay que repetirlo.","p":"Correcto. Hasta 6 errores es aprobado."},"ref":{"doc":"TN","page":23}},{"id":"tn-086","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, you make 11 errors on the road test. How long must you practice before a retest?","o":["One day","Fourteen days","Seven days","Thirty days"],"h1":"It is one week.","h2":"On the Tennessee road test, 10 to 12 errors means you must wait seven days before a retest.","p":"Right. Wait seven days."},"es":{"q":"En Tennessee, tiene 11 errores en el examen de manejo. ¿Cuánto tiempo debe practicar antes de repetirlo?","o":["Un día","Catorce días","Siete días","Treinta días"],"h1":"Es una semana.","h2":"En el examen de manejo de Tennessee, de 10 a 12 errores significa esperar siete días antes de repetirlo.","p":"Correcto. Espere siete días."},"ref":{"doc":"TN","page":23}},{"id":"tn-087","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, you make 16 or more errors on the road test. How long must you wait before a retest?","o":["One day","Seven days","Fourteen days","Thirty days"],"h1":"It is the longest wait in the table.","h2":"On the Tennessee road test, 16 or more errors means you must wait thirty days before a retest.","p":"Right. Wait thirty days."},"es":{"q":"En Tennessee, tiene 16 errores o más en el examen de manejo. ¿Cuánto debe esperar antes de repetirlo?","o":["Un día","Siete días","Catorce días","Treinta días"],"h1":"Es la espera más larga de la tabla.","h2":"En el examen de manejo de Tennessee, 16 errores o más significa esperar treinta días antes de repetirlo.","p":"Correcto. Espere treinta días."},"ref":{"doc":"TN","page":23}},{"id":"tn-088","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, which of these makes you fail the road test right away?","o":["Breaking any traffic law","Driving a little slowly in a school zone","Asking the examiner to repeat a direction","Adjusting your mirrors before starting"],"h1":"Any illegal action ends the test.","h2":"A Tennessee road test ends in immediate failure for any traffic law violation, a dangerous action, refusing directions or contributing to a crash.","p":"Right. Breaking any traffic law is an automatic fail."},"es":{"q":"En Tennessee, ¿cuál de estos le hace reprobar el examen de manejo de inmediato?","o":["Violar cualquier ley de tránsito","Manejar un poco despacio en una zona escolar","Pedir al examinador que repita una indicación","Ajustar los espejos antes de arrancar"],"h1":"Cualquier acción ilegal termina el examen.","h2":"El examen de manejo de Tennessee se reprueba de inmediato por violar cualquier ley de tránsito, hacer algo peligroso, no seguir indicaciones o contribuir a un choque.","p":"Correcto. Violar cualquier ley de tránsito es reprobar automáticamente."},"ref":{"doc":"TN","page":23}},{"id":"tn-089","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, who may ride in the car during your road test?","o":["A parent in the back seat","Only you and the examiner (or other authorized staff)","Your instructor and your dog","Any licensed adult"],"h1":"No passengers, and no animals.","h2":"During a Tennessee road test, only you and the examiner or other authorized personnel may be in the vehicle, and no animal may be in it.","p":"Right. Only you and the examiner."},"es":{"q":"En Tennessee, ¿quién puede ir en el carro durante su examen de manejo?","o":["Uno de sus padres en el asiento de atrás","Solo usted y el examinador (u otro personal autorizado)","Su instructor y su perro","Cualquier adulto con licencia"],"h1":"Ni pasajeros ni animales.","h2":"Durante el examen de manejo de Tennessee, solo usted y el examinador u otro personal autorizado pueden estar en el vehículo, y no puede haber animales.","p":"Correcto. Solo usted y el examinador."},"ref":{"doc":"TN","page":23}},{"id":"tn-090","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, which skill most often causes new drivers to fail the road test?","o":["Using the horn","Starting the engine","Backing up","Turning on the headlights"],"h1":"It is a slow maneuver, but many beginners find it the hardest.","h2":"According to the Tennessee manual, backing is the skill that most often makes new drivers fail the road test.","p":"Right. Backing up causes the most failures."},"es":{"q":"En Tennessee, ¿qué habilidad hace que los nuevos conductores reprueben el examen de manejo con más frecuencia?","o":["Usar la bocina","Encender el motor","Manejar en reversa","Prender las luces"],"h1":"Es una maniobra lenta, pero a muchos principiantes les parece la más difícil.","h2":"Según el manual de Tennessee, manejar en reversa es la habilidad que más hace reprobar el examen de manejo a los nuevos conductores.","p":"Correcto. La reversa causa más reprobados."},"ref":{"doc":"TN","page":64}},{"id":"tn-091","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how many white headlights must a car have for the road test?","o":["Exactly one","At least six","Any number","At least two, but no more than four"],"h1":"There is both a minimum and a maximum.","h2":"Tennessee requires motor vehicles to have at least two but no more than four white headlights.","p":"Right. Two to four white headlights."},"es":{"q":"En Tennessee, ¿cuántas luces delanteras blancas debe tener un carro para el examen de manejo?","o":["Exactamente una","Por lo menos seis","Cualquier número","Por lo menos dos, pero no más de cuatro"],"h1":"Hay un mínimo y un máximo.","h2":"Tennessee exige que los vehículos tengan por lo menos dos y no más de cuatro luces delanteras blancas.","p":"Correcto. De dos a cuatro luces blancas."},"ref":{"doc":"TN","page":22}},{"id":"tn-092","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, how much light must a passenger car's side and back windows let through if tinting is added?","o":["At least 10 percent","At least 35 percent","At least 70 percent","Any amount is legal"],"h1":"It is about one third.","h2":"In Tennessee, tint on a passenger car's windows may not let through less than 35 percent of visible light.","p":"Right. At least 35 percent of light must pass through."},"es":{"q":"En Tennessee, ¿cuánta luz deben dejar pasar las ventanas laterales y traseras de un carro de pasajeros si se les pone polarizado?","o":["Por lo menos 10 por ciento","Por lo menos 35 por ciento","Por lo menos 70 por ciento","Cualquier cantidad es legal"],"h1":"Es más o menos un tercio.","h2":"En Tennessee, el polarizado en las ventanas de un carro de pasajeros no puede dejar pasar menos del 35 por ciento de la luz visible.","p":"Correcto. Debe pasar por lo menos el 35 por ciento de la luz."},"ref":{"doc":"TN","page":23}},{"id":"tn-093","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, may you put tinting film on your car's windshield?","o":["No, no tint may be put on the windshield","Yes, any darkness","Yes, if it lets 35 percent through","Only on cars older than 1990"],"h1":"Clear vision to the front is required.","h2":"Tennessee law does not allow any tinting material to be put on a vehicle's windshield.","p":"Right. No tint on the windshield."},"es":{"q":"En Tennessee, ¿puede ponerle película polarizada al parabrisas de su carro?","o":["No, no se permite polarizado en el parabrisas","Sí, de cualquier oscuridad","Sí, si deja pasar el 35 por ciento","Solo en carros de antes de 1990"],"h1":"Se exige vista clara hacia el frente.","h2":"La ley de Tennessee no permite poner ningún material polarizado en el parabrisas de un vehículo.","p":"Correcto. Nada de polarizado en el parabrisas."},"ref":{"doc":"TN","page":23}},{"id":"tn-094","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, since January 1, 2018, what colors may steady-burning lights on the front of a car be?","o":["Any color","Blue or green","Red or white","Only white, amber, or both"],"h1":"Think of normal headlights and front turn signals.","h2":"Since January 1, 2018, Tennessee vehicles may not have steady front lights in any color other than white or amber.","p":"Right. Only white or amber to the front."},"es":{"q":"En Tennessee, desde el 1 de enero de 2018, ¿de qué colores pueden ser las luces fijas en el frente de un carro?","o":["De cualquier color","Azul o verde","Rojo o blanco","Solo blanco, ámbar, o ambos"],"h1":"Piense en las luces normales y las direccionales de adelante.","h2":"Desde el 1 de enero de 2018, los vehículos en Tennessee no pueden tener luces fijas al frente de ningún color que no sea blanco o ámbar.","p":"Correcto. Solo blanco o ámbar al frente."},"ref":{"doc":"TN","page":45}},{"id":"tn-095","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, may you install flashing blue lights on your private car?","o":["Yes, if they are small","No, it is against the law","Yes, if you are a volunteer","Only for parades"],"h1":"Blue lights are for police and emergency vehicles.","h2":"Tennessee law forbids an unauthorized private vehicle from having flashing blue, or blue and red, emergency lights.","p":"Right. Private cars may not have flashing blue lights."},"es":{"q":"En Tennessee, ¿puede instalar luces azules intermitentes en su carro particular?","o":["Sí, si son pequeñas","No, es contra la ley","Sí, si es voluntario","Solo para desfiles"],"h1":"Las luces azules son para policías y vehículos de emergencia.","h2":"La ley de Tennessee prohíbe que un vehículo particular sin autorización tenga luces de emergencia azules, o azules y rojas, intermitentes.","p":"Correcto. Los carros particulares no pueden tener luces azules intermitentes."},"ref":{"doc":"TN","page":54}},{"id":"tn-096","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, you are 25 and drive through a marked school zone with its warning lights flashing. What is the phone rule?","o":["You may not use a hand-held phone; hands-free is allowed","You may talk on a hand-held phone if you go slowly","Phones are only banned for drivers under 18","You must turn the phone off completely"],"h1":"The law here is about holding the phone.","h2":"Since 2018, Tennessee drivers 18 and older may not use a hand-held phone in a marked school zone while its warning lights are flashing, but hands-free use is allowed.","p":"Right. No hand-held phone; hands-free is allowed."},"es":{"q":"En Tennessee, usted tiene 25 años y pasa por una zona escolar marcada con las luces de advertencia encendidas. ¿Cuál es la regla del teléfono?","o":["No puede usar el teléfono en la mano; manos libres sí se permite","Puede hablar con el teléfono en la mano si va despacio","Los teléfonos solo están prohibidos para menores de 18","Debe apagar el teléfono por completo"],"h1":"La ley aquí trata de sostener el teléfono.","h2":"Desde 2018, los conductores de 18 años o más en Tennessee no pueden usar el teléfono en la mano en una zona escolar marcada mientras las luces de advertencia están encendidas, pero sí pueden usar manos libres.","p":"Correcto. Nada de teléfono en la mano; manos libres sí."},"ref":{"doc":"TN","page":30}},{"id":"tn-097","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, besides holding a phone, which of these does the hands-free law also forbid while driving?","o":["Using a voice command to call","Listening to music on the radio","Following GPS directions by voice","Watching a video on your phone"],"h1":"Think about something that keeps your eyes on the screen.","h2":"Tennessee's hands-free law forbids drivers from watching a video or movie on a phone, as well as recording or broadcasting video.","p":"Right. Watching video while driving is illegal."},"es":{"q":"En Tennessee, además de sostener el teléfono, ¿cuál de estos también prohíbe la ley de manos libres al manejar?","o":["Usar un comando de voz para llamar","Escuchar música en la radio","Seguir las indicaciones del GPS por voz","Ver un video en el teléfono"],"h1":"Piense en algo que mantiene sus ojos en la pantalla.","h2":"La ley de manos libres de Tennessee prohíbe ver videos o películas en el teléfono al manejar, y también grabar o transmitir video.","p":"Correcto. Ver videos al manejar es ilegal."},"ref":{"doc":"TN","page":30}},{"id":"tn-098","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, what is the basic fine for a first offense of texting or holding a phone while driving?","o":["$10","$50","$500","$1,000"],"h1":"Court costs of up to $10 can be added.","h2":"In Tennessee, a first offense of texting or holding a phone while driving brings a $50 fine, plus court costs of up to $10.","p":"Right. The basic fine is $50."},"es":{"q":"En Tennessee, ¿cuál es la multa básica por una primera infracción de enviar mensajes de texto o sostener el teléfono al manejar?","o":["$10","$50","$500","$1,000"],"h1":"Se pueden sumar hasta $10 de costos de la corte.","h2":"En Tennessee, una primera infracción de enviar mensajes de texto o sostener el teléfono al manejar trae una multa de $50, más hasta $10 de costos de la corte.","p":"Correcto. La multa básica es de $50."},"ref":{"doc":"TN","page":30}},{"id":"tn-099","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, a teen with an intermediate license is driving. Who must wear a seat belt?","o":["Only the driver","Only front-seat riders","The driver and every passenger","Only passengers under 8"],"h1":"Everyone in the car is included.","h2":"In Tennessee, when a teen with a learner permit or intermediate license drives, the driver and all passengers must wear seat belts.","p":"Right. The driver and every passenger."},"es":{"q":"En Tennessee, un joven con licencia intermedia está manejando. ¿Quién debe usar cinturón de seguridad?","o":["Solo el conductor","Solo los del asiento delantero","El conductor y todos los pasajeros","Solo los pasajeros menores de 8"],"h1":"Todos en el carro están incluidos.","h2":"En Tennessee, cuando maneja un joven con permiso de aprendiz o licencia intermedia, el conductor y todos los pasajeros deben usar cinturón.","p":"Correcto. El conductor y todos los pasajeros."},"ref":{"doc":"TN","page":14}},{"id":"tn-100","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, how must a 2-year-old who weighs more than 20 pounds ride?","o":["In a car seat that faces forward","In a booster seat","With only a seat belt","On an adult's lap"],"h1":"Children 1 through 3 over 20 pounds have moved past rear-facing.","h2":"In Tennessee, children 1 through 3 years old who weigh more than 20 pounds must ride in a forward-facing child safety seat.","p":"Right. A forward-facing car seat."},"es":{"q":"En Tennessee, ¿cómo debe viajar un niño de 2 años que pesa más de 20 libras?","o":["En un asiento de seguridad mirando hacia adelante","En un asiento elevado (booster)","Solo con cinturón","En las piernas de un adulto"],"h1":"Los niños de 1 a 3 años de más de 20 libras ya pasaron de mirar hacia atrás.","h2":"En Tennessee, los niños de 1 a 3 años que pesan más de 20 libras deben ir en un asiento de seguridad mirando hacia adelante.","p":"Correcto. Un asiento mirando hacia adelante."},"ref":{"doc":"TN","page":31}},{"id":"tn-101","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, a child in a booster seat is riding in a car that has a back seat. Where must the child sit?","o":["In the front seat","Anywhere the child likes","Next to the driver","In the back seat"],"h1":"It is safer away from the front air bag.","h2":"Tennessee law says children in booster seats must ride in the back seat if the vehicle has one.","p":"Right. Booster seats go in the back seat."},"es":{"q":"En Tennessee, un niño en asiento elevado (booster) viaja en un carro que tiene asiento trasero. ¿Dónde debe sentarse?","o":["En el asiento delantero","Donde quiera","Al lado del conductor","En el asiento trasero"],"h1":"Es más seguro lejos de la bolsa de aire delantera.","h2":"La ley de Tennessee dice que los niños en asiento elevado deben ir en el asiento trasero si el vehículo tiene uno.","p":"Correcto. El asiento elevado va atrás."},"ref":{"doc":"TN","page":31}},{"id":"tn-102","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, the driver is responsible for making sure children are buckled up until what age?","o":["Age 8","Age 16","Age 12","Age 18"],"h1":"It is the age you can get an intermediate license.","h2":"A Tennessee driver is responsible for properly restraining children up to age 16 and can be fined $50 if they are not.","p":"Right. Up to age 16."},"es":{"q":"En Tennessee, ¿hasta qué edad es responsable el conductor de que los niños lleven el cinturón abrochado?","o":["Hasta los 8 años","Hasta los 16 años","Hasta los 12 años","Hasta los 18 años"],"h1":"Es la edad en que se puede obtener la licencia intermedia.","h2":"En Tennessee, el conductor es responsable de que los niños vayan bien asegurados hasta los 16 años y le pueden poner una multa de $50 si no.","p":"Correcto. Hasta los 16 años."},"ref":{"doc":"TN","page":31}},{"id":"tn-103","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, may a 10-year-old ride in the bed of a pickup truck on an interstate highway?","o":["No, not on state or interstate highways","Yes, if sitting down","Yes, if an adult is in the bed too","Yes, under 45 mph"],"h1":"Children 6 through 12 have a rule for these big roads.","h2":"Tennessee law forbids children ages 6 to 12 from riding in a pickup truck bed on any state or interstate highway.","p":"Right. Not on state or interstate highways."},"es":{"q":"En Tennessee, ¿puede un niño de 10 años viajar en la caja de una camioneta pickup en una autopista interestatal?","o":["No, ni en carreteras estatales ni interestatales","Sí, si va sentado","Sí, si un adulto va también en la caja","Sí, a menos de 45 mph"],"h1":"Los niños de 6 a 12 años tienen una regla para estas carreteras grandes.","h2":"La ley de Tennessee prohíbe que niños de 6 a 12 años viajen en la caja de una camioneta pickup en cualquier carretera estatal o interestatal.","p":"Correcto. No en carreteras estatales ni interestatales."},"ref":{"doc":"TN","page":33}},{"id":"tn-104","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, what is the fine for a first offense of leaving a child under 7 alone in a car with the engine running?","o":["$50","$200","$1,000","$2,500"],"h1":"A second offense costs $500.","h2":"In Tennessee, leaving a young child unattended in a vehicle under these conditions is a Class B misdemeanor with a $200 fine for a first offense.","p":"Right. The first offense fine is $200."},"es":{"q":"En Tennessee, ¿cuál es la multa por primera vez por dejar solo en el carro a un niño menor de 7 años con el motor encendido?","o":["$50","$200","$1,000","$2,500"],"h1":"La segunda vez cuesta $500.","h2":"En Tennessee, dejar solo en un vehículo a un niño pequeño en estas condiciones es un delito menor Clase B con multa de $200 la primera vez.","p":"Correcto. La multa la primera vez es de $200."},"ref":{"doc":"TN","page":33}},{"id":"tn-105","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, in a car with air bags, where is the safest place for children 12 and under to ride?","o":["The front passenger seat","On an adult's lap","The back seat","The cargo area"],"h1":"Air bags can hurt young children.","h2":"The Tennessee manual says children 12 and under are safest buckled in the back seat.","p":"Right. The back seat is safest."},"es":{"q":"En Tennessee, en un carro con bolsas de aire, ¿cuál es el lugar más seguro para niños de 12 años o menos?","o":["El asiento delantero del pasajero","En las piernas de un adulto","El asiento trasero","El área de carga"],"h1":"Las bolsas de aire pueden lastimar a los niños pequeños.","h2":"El manual de Tennessee dice que los niños de 12 años o menos van más seguros con cinturón en el asiento trasero.","p":"Correcto. El asiento trasero es el más seguro."},"ref":{"doc":"TN","page":33}},{"id":"tn-106","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, about how far should your chest be from the steering wheel, so the air bag has room?","o":["10 to 12 inches","2 to 4 inches","24 to 30 inches","As close as possible"],"h1":"It is about one foot.","h2":"The Tennessee manual says to sit about 10 to 12 inches back from the steering wheel so an air bag does not hit your face or chin.","p":"Right. About 10 to 12 inches."},"es":{"q":"En Tennessee, ¿a qué distancia del volante debe estar su pecho para que la bolsa de aire tenga espacio?","o":["De 10 a 12 pulgadas","De 2 a 4 pulgadas","De 24 a 30 pulgadas","Lo más cerca posible"],"h1":"Es más o menos un pie.","h2":"El manual de Tennessee dice que se siente a unas 10 a 12 pulgadas del volante para que la bolsa de aire no le golpee la cara o la barbilla.","p":"Correcto. Unas 10 a 12 pulgadas."},"ref":{"doc":"TN","page":27}},{"id":"tn-107","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, who must wear a safety belt in a 15-passenger van?","o":["Only the driver","Only front-seat riders","Only children","Every person in the van, at all times"],"h1":"The van's rollover risk makes this extra important.","h2":"Tennessee law requires every occupant of a 15-passenger van to wear a safety belt at all times.","p":"Right. Everyone in the van must buckle up."},"es":{"q":"En Tennessee, ¿quién debe usar cinturón en una camioneta (van) de 15 pasajeros?","o":["Solo el conductor","Solo los del asiento delantero","Solo los niños","Todas las personas en la van, siempre"],"h1":"El riesgo de volcadura de la van hace esto muy importante.","h2":"La ley de Tennessee exige que todos los ocupantes de una van de 15 pasajeros usen cinturón en todo momento.","p":"Correcto. Todos en la van deben abrocharse."},"ref":{"doc":"TN","page":114}},{"id":"tn-108","scope":"TN","cat":"signs","sign":null,"c":2,"en":{"q":"In Tennessee, a yellow turn sign (a sharp bend arrow) marks turns with what recommended speed?","o":["55 mph or more","40 to 50 mph","30 mph or less","Any speed"],"h1":"A turn is sharper than a curve.","h2":"On Tennessee roads, the turn sign marks bends with a recommended speed of 30 mph or less, while the curve sign marks 30 to 55 mph.","p":"Right. Turn signs mean 30 mph or less."},"es":{"q":"En Tennessee, una señal amarilla de vuelta (flecha de giro cerrado) marca vueltas con ¿qué velocidad recomendada?","o":["55 mph o más","De 40 a 50 mph","30 mph o menos","Cualquier velocidad"],"h1":"Una vuelta es más cerrada que una curva.","h2":"En las carreteras de Tennessee, la señal de vuelta marca giros con velocidad recomendada de 30 mph o menos, y la señal de curva marca de 30 a 55 mph.","p":"Correcto. La señal de vuelta significa 30 mph o menos."},"ref":{"doc":"TN","page":38}},{"id":"tn-109","scope":"TN","cat":"signs","sign":null,"c":0,"en":{"q":"In Tennessee, a reverse turn sign warns of two turns in opposite directions. How close together are they?","o":["Less than 600 feet apart","More than a mile apart","About 2,000 feet apart","Exactly 100 feet apart"],"h1":"The second turn comes quickly after the first.","h2":"A Tennessee reverse turn sign marks two turns in opposite directions that are less than 600 feet apart.","p":"Right. Less than 600 feet apart."},"es":{"q":"En Tennessee, una señal de vuelta doble (reverse turn) avisa de dos vueltas en direcciones opuestas. ¿Qué tan cerca están?","o":["A menos de 600 pies","A más de una milla","A unos 2,000 pies","Exactamente a 100 pies"],"h1":"La segunda vuelta llega rápido después de la primera.","h2":"Una señal de vuelta doble en Tennessee marca dos vueltas en direcciones opuestas a menos de 600 pies una de otra.","p":"Correcto. A menos de 600 pies."},"ref":{"doc":"TN","page":38}},{"id":"tn-110","scope":"TN","cat":"signs","sign":null,"c":3,"en":{"q":"In Tennessee, on busy urban interstates, how often are emergency reference markers placed?","o":["Every 10 miles","Every 5 miles","Every mile","Every 1,000 feet"],"h1":"They are much closer together than mile markers.","h2":"Tennessee placed emergency reference markers every 1,000 feet on busy interstates in cities like Nashville, Memphis and Knoxville, so callers can give an exact location.","p":"Right. Every 1,000 feet."},"es":{"q":"En Tennessee, en las autopistas interestatales urbanas con mucho tráfico, ¿cada cuánto hay marcadores de referencia para emergencias?","o":["Cada 10 millas","Cada 5 millas","Cada milla","Cada 1,000 pies"],"h1":"Están mucho más juntos que los marcadores de millas.","h2":"Tennessee puso marcadores de referencia para emergencias cada 1,000 pies en las interestatales con mucho tráfico de ciudades como Nashville, Memphis y Knoxville, para que quien llame dé el lugar exacto.","p":"Correcto. Cada 1,000 pies."},"ref":{"doc":"TN","page":41}},{"id":"tn-111","scope":"TN","cat":"signals","sign":null,"c":2,"en":{"q":"In Tennessee, at least how long must a yellow traffic light show before it turns red?","o":["1 second","10 seconds","3 seconds","30 seconds"],"h1":"It is only a few seconds.","h2":"Tennessee law requires the yellow light to show for at least three seconds before the red light.","p":"Right. At least three seconds."},"es":{"q":"En Tennessee, ¿por lo menos cuánto tiempo debe estar encendida la luz amarilla antes de cambiar a roja?","o":["1 segundo","10 segundos","3 segundos","30 segundos"],"h1":"Son solo unos segundos.","h2":"La ley de Tennessee exige que la luz amarilla se muestre por lo menos tres segundos antes de la roja.","p":"Correcto. Por lo menos tres segundos."},"ref":{"doc":"TN","page":41}},{"id":"tn-112","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, is it legal to stand on the road to ask for a ride (hitchhike)?","o":["No, it is illegal","Yes, on any road","Yes, but only in daylight","Yes, on interstates only"],"h1":"It is dangerous for both the walker and the driver.","h2":"In Tennessee, it is illegal to stand on a roadway to ask for a ride.","p":"Right. Hitchhiking on the roadway is illegal."},"es":{"q":"En Tennessee, ¿es legal pararse en la carretera para pedir que lo lleven (pedir aventón)?","o":["No, es ilegal","Sí, en cualquier carretera","Sí, pero solo de día","Sí, solo en interestatales"],"h1":"Es peligroso para quien camina y para quien maneja.","h2":"En Tennessee, es ilegal pararse en la carretera para pedir que lo lleven.","p":"Correcto. Pedir aventón en la carretera es ilegal."},"ref":{"doc":"TN","page":37}},{"id":"tn-113","scope":"TN","cat":"signals","sign":null,"c":1,"en":{"q":"In Tennessee, over a reversible lane you see a flashing yellow X. What does it mean?","o":["You may drive straight in the lane","The lane may be used only for turning","The lane is closed to all traffic","Speed up and leave the lane"],"h1":"A steady yellow X means something different.","h2":"On Tennessee roads, a flashing yellow X over a lane means the lane is only for turning.","p":"Right. A flashing yellow X means turning only."},"es":{"q":"En Tennessee, sobre un carril reversible ve una X amarilla intermitente. ¿Qué significa?","o":["Puede seguir derecho en el carril","El carril solo se puede usar para dar vuelta","El carril está cerrado para todos","Acelere y salga del carril"],"h1":"Una X amarilla fija significa otra cosa.","h2":"En las calles de Tennessee, una X amarilla intermitente sobre un carril significa que el carril es solo para dar vuelta.","p":"Correcto. Una X amarilla intermitente significa solo para dar vuelta."},"ref":{"doc":"TN","page":61}},{"id":"tn-114","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, during daytime you must turn on your headlights when you cannot see people or vehicles clearly at what distance?","o":["50 feet","1,000 feet","200 feet","2 miles"],"h1":"It is a little less than the length of a city block.","h2":"Tennessee law requires headlights whenever daylight is not good enough to see people or vehicles clearly 200 feet ahead.","p":"Right. At 200 feet."},"es":{"q":"En Tennessee, de día debe prender las luces cuando no puede ver claramente a personas o vehículos ¿a qué distancia?","o":["50 pies","1,000 pies","200 pies","2 millas"],"h1":"Es un poco menos que una cuadra de ciudad.","h2":"La ley de Tennessee exige luces cuando la luz del día no basta para ver claramente personas o vehículos a 200 pies.","p":"Correcto. A 200 pies."},"ref":{"doc":"TN","page":45}},{"id":"tn-115","scope":"TN","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Tennessee, it is raining and you need your windshield wipers all the time. What does the law say about headlights?","o":["They are optional","Use only parking lights","Use high beams","You must turn them on"],"h1":"Wipers on, lights on.","h2":"Tennessee law requires headlights whenever rain, mist, snow or other weather needs constant use of windshield wipers.","p":"Right. Wipers on means headlights on."},"es":{"q":"En Tennessee, está lloviendo y necesita los limpiaparabrisas todo el tiempo. ¿Qué dice la ley de las luces?","o":["Son opcionales","Use solo las luces de estacionamiento","Use las luces altas","Debe prenderlas"],"h1":"Limpiaparabrisas prendidos, luces prendidas.","h2":"La ley de Tennessee exige prender las luces cuando la lluvia, la neblina, la nieve u otro clima requiere usar los limpiaparabrisas todo el tiempo.","p":"Correcto. Con limpiaparabrisas, luces prendidas."},"ref":{"doc":"TN","page":45}},{"id":"tn-116","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, it is dusk and hard to see. May you drive with only your parking lights on?","o":["Yes, if you go slowly","No, it is unsafe and against the law","Yes, in town","Yes, if your fog lights are also on"],"h1":"Small lights can make your car seem farther away.","h2":"In Tennessee, driving with only parking lights on when visibility is limited is unsafe and against the law.","p":"Right. Parking lights alone are not allowed."},"es":{"q":"En Tennessee, está anocheciendo y cuesta ver. ¿Puede manejar solo con las luces de estacionamiento prendidas?","o":["Sí, si va despacio","No, es peligroso y contra la ley","Sí, en el pueblo","Sí, si también lleva las luces de niebla"],"h1":"Las luces pequeñas pueden hacer que su carro parezca más lejos.","h2":"En Tennessee, manejar solo con las luces de estacionamiento cuando hay poca visibilidad es peligroso y contra la ley.","p":"Correcto. Las luces de estacionamiento solas no se permiten."},"ref":{"doc":"TN","page":45}},{"id":"tn-117","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, you are behind a funeral procession on a two-lane road. What does the law say?","o":["You may not pass the procession","You may pass if you honk first","You may pass on the right","You may drive between the cars"],"h1":"Show respect and stay behind.","h2":"Tennessee law says vehicles following a funeral procession on a two-lane road may not try to pass it.","p":"Right. Do not pass the procession."},"es":{"q":"En Tennessee, va detrás de un cortejo fúnebre en una carretera de dos carriles. ¿Qué dice la ley?","o":["No puede rebasar el cortejo","Puede rebasar si toca la bocina antes","Puede rebasar por la derecha","Puede meterse entre los carros"],"h1":"Muestre respeto y quédese atrás.","h2":"La ley de Tennessee dice que los vehículos detrás de un cortejo fúnebre en una carretera de dos carriles no pueden intentar rebasarlo.","p":"Correcto. No rebase el cortejo."},"ref":{"doc":"TN","page":46}},{"id":"tn-118","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, you are considered a slow-moving vehicle when you drive how far below the speed limit?","o":["2 mph or more","5 mph or more","10 mph or more","25 mph or more"],"h1":"It is a round number.","h2":"In Tennessee, you are driving a slow-moving vehicle when you go 10 miles per hour or more below the lawful maximum speed.","p":"Right. 10 mph or more below the limit."},"es":{"q":"En Tennessee, se le considera vehículo lento cuando maneja ¿cuánto por debajo del límite de velocidad?","o":["2 mph o más","5 mph o más","10 mph o más","25 mph o más"],"h1":"Es un número redondo.","h2":"En Tennessee, usted maneja un vehículo lento cuando va 10 millas por hora o más por debajo de la velocidad máxima legal.","p":"Correcto. 10 mph o más por debajo del límite."},"ref":{"doc":"TN","page":46}},{"id":"tn-120","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, what is the highest speed limit the law sets for interstate highways?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is posted on most rural interstates.","h2":"Tennessee law sets 70 miles per hour as the maximum interstate speed, and it is posted on most rural interstate sections.","p":"Right. The interstate maximum is 70 mph."},"es":{"q":"En Tennessee, ¿cuál es el límite de velocidad más alto que fija la ley para las autopistas interestatales?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Está señalado en la mayoría de las interestatales rurales.","h2":"La ley de Tennessee fija 70 millas por hora como velocidad máxima en interestatales, y se señala en la mayoría de los tramos rurales.","p":"Correcto. El máximo en interestatales es 70 mph."},"ref":{"doc":"TN","page":47}},{"id":"tn-121","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, unless traffic is heavy, what is the slowest you may drive in the far left lane of an interstate?","o":["55 mph","40 mph","45 mph","65 mph"],"h1":"The left lane is for faster traffic.","h2":"In Tennessee, it is unlawful to drive less than 55 miles per hour in the left-most interstate lane unless congestion prevents it.","p":"Right. At least 55 mph in the left lane."},"es":{"q":"En Tennessee, a menos que haya mucho tráfico, ¿qué es lo más despacio que puede ir en el carril de la extrema izquierda de una interestatal?","o":["55 mph","40 mph","45 mph","65 mph"],"h1":"El carril izquierdo es para el tráfico más rápido.","h2":"En Tennessee, es ilegal ir a menos de 55 millas por hora en el carril de más a la izquierda de una interestatal, a menos que el tráfico lo impida.","p":"Correcto. Por lo menos 55 mph en el carril izquierdo."},"ref":{"doc":"TN","page":47}},{"id":"tn-122","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, under normal conditions, what is the minimum speed in the right lanes of an interstate?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"It is 10 mph less than the left-lane minimum.","h2":"On Tennessee interstates, the minimum speed in the right lanes is 45 miles per hour under normal conditions.","p":"Right. The minimum is 45 mph."},"es":{"q":"En Tennessee, en condiciones normales, ¿cuál es la velocidad mínima en los carriles derechos de una interestatal?","o":["25 mph","35 mph","45 mph","55 mph"],"h1":"Es 10 mph menos que el mínimo del carril izquierdo.","h2":"En las interestatales de Tennessee, la velocidad mínima en los carriles derechos es de 45 millas por hora en condiciones normales.","p":"Correcto. El mínimo es 45 mph."},"ref":{"doc":"TN","page":47}},{"id":"tn-123","scope":"TN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Tennessee, you speed in a school zone while the limit is in effect. How does the law treat this?","o":["As a minor warning","As reckless driving, with 6 points","As a parking ticket","As careless driving with no points"],"h1":"It is treated as one of the most serious moving violations.","h2":"In Tennessee, going over the school zone speed limit is considered reckless driving and adds 6 points to your record.","p":"Right. It counts as reckless driving with 6 points."},"es":{"q":"En Tennessee, usted va a exceso de velocidad en una zona escolar cuando el límite está vigente. ¿Cómo lo trata la ley?","o":["Como una advertencia menor","Como manejo temerario, con 6 puntos","Como una multa de estacionamiento","Como manejo descuidado sin puntos"],"h1":"Se trata como una de las infracciones más graves.","h2":"En Tennessee, pasarse del límite de velocidad de una zona escolar se considera manejo temerario y suma 6 puntos a su historial.","p":"Correcto. Cuenta como manejo temerario con 6 puntos."},"ref":{"doc":"TN","page":47}},{"id":"tn-124","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, what fine does the law set for speeding in an active work zone?","o":["$25 to $50","$1,000 to $2,500","A warning only","$250 to $500"],"h1":"The minimum is a few hundred dollars.","h2":"Tennessee law sets a fine of at least $250 and up to $500 for speeding in an active work zone.","p":"Right. $250 to $500."},"es":{"q":"En Tennessee, ¿qué multa fija la ley por exceso de velocidad en una zona de trabajo activa?","o":["De $25 a $50","De $1,000 a $2,500","Solo una advertencia","De $250 a $500"],"h1":"El mínimo es de unos cientos de dólares.","h2":"La ley de Tennessee fija una multa de por lo menos $250 y hasta $500 por exceso de velocidad en una zona de trabajo activa.","p":"Correcto. De $250 a $500."},"ref":{"doc":"TN","page":47}},{"id":"tn-125","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, you drive on the interstate at night or in bad weather. How far behind the car ahead should you stay?","o":["At least 4 seconds","1 second","2 car lengths","Exactly 2 seconds"],"h1":"Double the usual rule.","h2":"The Tennessee manual says to increase the two-second rule to at least four seconds at night, in bad weather, on fast interstates and when following a motorcycle.","p":"Right. At least four seconds."},"es":{"q":"En Tennessee, maneja en la interestatal de noche o con mal tiempo. ¿Qué distancia debe dejar con el carro de adelante?","o":["Por lo menos 4 segundos","1 segundo","2 largos de carro","Exactamente 2 segundos"],"h1":"El doble de la regla normal.","h2":"El manual de Tennessee dice que aumente la regla de dos segundos a por lo menos cuatro segundos de noche, con mal tiempo, en interestatales rápidas y detrás de una motocicleta.","p":"Correcto. Por lo menos cuatro segundos."},"ref":{"doc":"TN","page":49}},{"id":"tn-126","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, you drive 70 mph on a good road at night and a deer appears. About how far will you travel before you stop, counting reaction time?","o":["About 100 feet","About 200 feet","About 418 feet","About 50 feet"],"h1":"It is close to one and a half football fields.","h2":"At 70 mph, the Tennessee manual says you travel about 128 feet before braking and 290 feet while braking, about 418 feet in all.","p":"Right. About 418 feet."},"es":{"q":"En Tennessee, maneja a 70 mph en un buen camino de noche y aparece un venado. ¿Más o menos cuánto avanzará antes de detenerse, contando el tiempo de reacción?","o":["Unos 100 pies","Unos 200 pies","Unos 418 pies","Unos 50 pies"],"h1":"Es casi un campo de fútbol americano y medio.","h2":"A 70 mph, el manual de Tennessee dice que avanza unos 128 pies antes de frenar y 290 pies frenando, unos 418 pies en total.","p":"Correcto. Unos 418 pies."},"ref":{"doc":"TN","page":49}},{"id":"tn-127","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, a train is coming at a railroad crossing. How far from the tracks must you stop?","o":["At least 100 feet away","Between 15 and 50 feet from the nearest rail","Right on the edge of the tracks","Between 5 and 10 feet"],"h1":"Not too close, and not too far.","h2":"When a train is coming, Tennessee drivers must stop between 15 and 50 feet from the nearest rail.","p":"Right. Between 15 and 50 feet."},"es":{"q":"En Tennessee, viene un tren en un cruce de ferrocarril. ¿A qué distancia de las vías debe detenerse?","o":["Por lo menos a 100 pies","Entre 15 y 50 pies del riel más cercano","Justo en la orilla de las vías","Entre 5 y 10 pies"],"h1":"Ni muy cerca ni muy lejos.","h2":"Cuando viene un tren, los conductores en Tennessee deben detenerse entre 15 y 50 pies del riel más cercano.","p":"Correcto. Entre 15 y 50 pies."},"ref":{"doc":"TN","page":50}},{"id":"tn-128","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, about how far from a crossing must a train start sounding its horn?","o":["100 feet","500 feet","1 mile","1,500 feet"],"h1":"It is more than a quarter mile.","h2":"The Tennessee manual says trains must sound the horn about 1,500 feet before passing through a railroad crossing.","p":"Right. About 1,500 feet."},"es":{"q":"En Tennessee, ¿más o menos a qué distancia del cruce debe un tren empezar a tocar el silbato?","o":["100 pies","500 pies","1 milla","1,500 pies"],"h1":"Es más de un cuarto de milla.","h2":"El manual de Tennessee dice que los trenes deben tocar el silbato unos 1,500 pies antes de pasar por un cruce de ferrocarril.","p":"Correcto. Unos 1,500 pies."},"ref":{"doc":"TN","page":50}},{"id":"tn-129","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, a school bus stops with red lights flashing on a four-lane road that has a center turn lane. Who must stop?","o":["Traffic in both directions","Only traffic behind the bus","Only traffic in the turn lane","No one; a turn lane counts as a median"],"h1":"A turn lane is not a barrier.","h2":"In Tennessee, a center turn lane is not a barrier, so traffic in both directions must stop for a school bus on that kind of road.","p":"Right. Both directions must stop."},"es":{"q":"En Tennessee, un autobús escolar se detiene con luces rojas intermitentes en una carretera de cuatro carriles con carril central para dar vuelta. ¿Quién debe detenerse?","o":["El tráfico en ambas direcciones","Solo el tráfico detrás del autobús","Solo el tráfico en el carril de vuelta","Nadie; un carril de vuelta cuenta como camellón"],"h1":"Un carril de vuelta no es una barrera.","h2":"En Tennessee, un carril central de vuelta no es una barrera, así que el tráfico en ambas direcciones debe detenerse por un autobús escolar en ese tipo de carretera.","p":"Correcto. Ambas direcciones deben detenerse."},"ref":{"doc":"TN","page":51}},{"id":"tn-130","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, the yellow lights on a school bus start flashing. What do they mean?","o":["The bus is done and you may pass","The bus is broken down","The bus is getting ready to stop, so slow down and prepare to stop","Only buses behind it must stop"],"h1":"Yellow comes before red.","h2":"On a Tennessee school bus, flashing yellow lights mean the bus is preparing to stop to load or unload children, so slow down and get ready to stop.","p":"Right. Slow down and get ready to stop."},"es":{"q":"En Tennessee, las luces amarillas de un autobús escolar empiezan a parpadear. ¿Qué significan?","o":["El autobús terminó y puede rebasar","El autobús está descompuesto","El autobús se prepara para parar; baje la velocidad y prepárese para detenerse","Solo los autobuses detrás deben parar"],"h1":"El amarillo viene antes del rojo.","h2":"En un autobús escolar de Tennessee, las luces amarillas intermitentes significan que se prepara para parar a subir o bajar niños, así que baje la velocidad y prepárese para detenerse.","p":"Correcto. Baje la velocidad y prepárese para detenerse."},"ref":{"doc":"TN","page":51}},{"id":"tn-131","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, what lights does a police vehicle use when it wants you to pull over?","o":["Flashing green lights","Flashing blue, or blue and red, lights","Steady white lights","Flashing amber lights only"],"h1":"Tennessee police lights include one cool color.","h2":"In Tennessee, police signal drivers to stop with flashing blue lights or flashing blue and red lights, and may use a siren.","p":"Right. Blue, or blue and red, lights."},"es":{"q":"En Tennessee, ¿qué luces usa una patrulla cuando quiere que usted se detenga?","o":["Luces verdes intermitentes","Luces azules, o azules y rojas, intermitentes","Luces blancas fijas","Solo luces ámbar intermitentes"],"h1":"Las luces de la policía de Tennessee incluyen un color frío.","h2":"En Tennessee, la policía indica a los conductores que se detengan con luces azules intermitentes o azules y rojas, y puede usar sirena.","p":"Correcto. Luces azules, o azules y rojas."},"ref":{"doc":"TN","page":52}},{"id":"tn-132","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, at night an UNMARKED police car signals you to pull over. What may you do?","o":["Speed away","Stop in the dark right away, no matter where","Ignore it","Drive slowly a short distance to a place with other people, like a lit parking lot"],"h1":"Your safety matters, but do not flee.","h2":"The Tennessee manual says that if an unmarked police car signals you, you may drive slowly a short way to the nearest place with other people, such as a business parking lot or the next exit.","p":"Right. Drive slowly to a public place."},"es":{"q":"En Tennessee, de noche una patrulla SIN marcas le indica que se detenga. ¿Qué puede hacer?","o":["Acelerar y huir","Detenerse en lo oscuro de inmediato, en cualquier lugar","Ignorarla","Manejar despacio una distancia corta hasta un lugar con gente, como un estacionamiento iluminado"],"h1":"Su seguridad importa, pero no huya.","h2":"El manual de Tennessee dice que si una patrulla sin marcas le indica detenerse, puede manejar despacio una distancia corta hasta el lugar más cercano con gente, como el estacionamiento de un negocio o la siguiente salida.","p":"Correcto. Maneje despacio hasta un lugar público."},"ref":{"doc":"TN","page":52}},{"id":"tn-133","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, you are stopped by police after dark. What should you do before the officer walks up?","o":["Turn on your interior light and keep your hands on the wheel","Get out and walk to the police car","Search your glove box for papers","Turn off all lights"],"h1":"Help the officer see you clearly.","h2":"The Tennessee manual says to turn on the interior light at night, keep your hands on the steering wheel and stay in the car unless asked to get out.","p":"Right. Interior light on, hands on the wheel."},"es":{"q":"En Tennessee, la policía lo detiene de noche. ¿Qué debe hacer antes de que llegue el oficial?","o":["Prender la luz interior y mantener las manos en el volante","Bajarse y caminar hacia la patrulla","Buscar papeles en la guantera","Apagar todas las luces"],"h1":"Ayude a que el oficial lo vea bien.","h2":"El manual de Tennessee dice que de noche prenda la luz interior, mantenga las manos en el volante y quédese en el carro a menos que le pidan bajarse.","p":"Correcto. Luz interior prendida, manos en el volante."},"ref":{"doc":"TN","page":52}},{"id":"tn-134","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, a person crossing the road has a dog on a blaze orange leash. What does that usually tell you?","o":["The dog is lost","The person is training a police dog","The person has a hearing impairment","The person is hunting"],"h1":"A white cane shows one disability; this shows another.","h2":"Tennessee law treats a pedestrian with a dog on a blaze orange leash as hearing impaired, so drivers must take special care and stop if needed.","p":"Right. It shows a person with a hearing impairment."},"es":{"q":"En Tennessee, una persona que cruza la calle lleva un perro con correa de color naranja fosforescente. ¿Qué le indica eso por lo general?","o":["El perro está perdido","La persona entrena un perro policía","La persona tiene una discapacidad auditiva","La persona está cazando"],"h1":"Un bastón blanco muestra una discapacidad; esto muestra otra.","h2":"La ley de Tennessee trata a un peatón con un perro con correa naranja fosforescente como persona con discapacidad auditiva, así que el conductor debe tener cuidado especial y detenerse si es necesario.","p":"Correcto. Indica una persona con discapacidad auditiva."},"ref":{"doc":"TN","page":53}},{"id":"tn-135","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, you are in a marked school zone with the warning lights flashing. A child starts across the crosswalk. What must you do?","o":["Slow down and go around the child","Stop and stay stopped until the child has crossed the road","Honk so the child hurries","Stop only if the child is in your lane"],"h1":"In a school zone, you wait for the whole crossing.","h2":"In a Tennessee school zone with flashers on, drivers must stop for a pedestrian in a crosswalk and stay stopped until the person has crossed the road.","p":"Right. Stay stopped until the child has crossed."},"es":{"q":"En Tennessee, está en una zona escolar marcada con las luces de advertencia encendidas. Un niño empieza a cruzar por el cruce peatonal. ¿Qué debe hacer?","o":["Bajar la velocidad y rodear al niño","Detenerse y seguir detenido hasta que el niño termine de cruzar","Tocar la bocina para que se apure","Detenerse solo si el niño está en su carril"],"h1":"En una zona escolar, espera a que cruce por completo.","h2":"En una zona escolar de Tennessee con luces encendidas, el conductor debe detenerse por un peatón en el cruce y seguir detenido hasta que la persona termine de cruzar la calle.","p":"Correcto. Siga detenido hasta que el niño termine de cruzar."},"ref":{"doc":"TN","page":53}},{"id":"tn-136","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, a fire truck is backing into the driveway of its fire station. What should you do?","o":["Drive around it quickly","Honk to warn it","Pass on the left","Stop and yield to it"],"h1":"Emergency vehicles returning to the station still get the right-of-way.","h2":"The Tennessee manual says to yield to any emergency vehicle about to back into, or backing into, a fire station driveway.","p":"Right. Stop and yield to it."},"es":{"q":"En Tennessee, un camión de bomberos se mete en reversa a la entrada de su estación. ¿Qué debe hacer?","o":["Rodearlo rápido","Tocar la bocina para avisarle","Rebasarlo por la izquierda","Detenerse y cederle el paso"],"h1":"Los vehículos de emergencia que regresan a la estación también tienen el derecho de paso.","h2":"El manual de Tennessee dice que ceda el paso a cualquier vehículo de emergencia que va a meterse, o se está metiendo, en reversa a la entrada de una estación de bomberos.","p":"Correcto. Deténgase y cédale el paso."},"ref":{"doc":"TN","page":53}},{"id":"tn-137","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, a fire truck is on its way to a fire alarm ahead of you. How close may you follow it?","o":["No closer than 500 feet","No closer than 100 feet","One car length behind","As close as you like if your flashers are on"],"h1":"Keep a long gap, about the length of a city block or more.","h2":"Tennessee law says you may not follow a fire truck answering a fire alarm closer than 500 feet, or park in the block where it has stopped.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Tennessee, un camión de bomberos va hacia una alarma de incendio delante de usted. ¿A qué distancia mínima puede seguirlo?","o":["No más cerca de 500 pies","No más cerca de 100 pies","A un auto de distancia","Tan cerca como quiera si tiene las luces intermitentes encendidas"],"h1":"Deje un espacio grande, del largo de una cuadra o más.","h2":"La ley de Tennessee dice que no puede seguir a un camión de bomberos que atiende una alarma de incendio a menos de 500 pies, ni estacionarse en la cuadra donde se detuvo.","p":"Correcto. Quédese al menos a 500 pies de distancia."},"ref":{"doc":"TN","page":null}},{"id":"tn-138","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, firefighters have laid a hose across the street. When may you drive over it?","o":["Whenever it looks flat","If you go very slowly","Only if the fire official in charge says it is okay","At night only"],"h1":"Someone in charge must give permission.","h2":"In Tennessee, you may not drive over an unprotected fire hose unless the fire department official in command says it is okay.","p":"Right. Only with the fire official's okay."},"es":{"q":"En Tennessee, los bomberos pusieron una manguera atravesada en la calle. ¿Cuándo puede pasar por encima?","o":["Cuando se vea aplanada","Si va muy despacio","Solo si el jefe de bomberos a cargo dice que está bien","Solo de noche"],"h1":"Alguien a cargo debe dar permiso.","h2":"En Tennessee, no puede pasar por encima de una manguera de bomberos sin protección a menos que el oficial de bomberos a cargo diga que está bien.","p":"Correcto. Solo con permiso del oficial de bomberos."},"ref":{"doc":"TN","page":54}},{"id":"tn-139","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, you are already inside an intersection when an ambulance with a siren comes up behind you. What should you do?","o":["Stop right where you are","Drive through the intersection first, then pull to the right and stop","Back up out of the intersection","Turn left in front of it"],"h1":"Do not block its path through the intersection.","h2":"The Tennessee manual says that if you are in an intersection, drive on through before pulling over to the right, so you do not block the emergency vehicle.","p":"Right. Clear the intersection, then pull over."},"es":{"q":"En Tennessee, usted ya está dentro de una intersección cuando llega detrás una ambulancia con sirena. ¿Qué debe hacer?","o":["Detenerse ahí mismo","Cruzar la intersección primero y luego orillarse a la derecha y parar","Retroceder fuera de la intersección","Dar vuelta a la izquierda frente a ella"],"h1":"No le bloquee el paso por la intersección.","h2":"El manual de Tennessee dice que si está en una intersección, termine de cruzarla antes de orillarse a la derecha, para no bloquear al vehículo de emergencia.","p":"Correcto. Salga de la intersección y luego oríllese."},"ref":{"doc":"TN","page":54}},{"id":"tn-140","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, you are stopped at a red light when an ambulance approaches. The light turns green before it passes. What should you do?","o":["Go, because the light is green","Turn right to get out of the way","Speed up to stay ahead of it","Stay where you are until the ambulance has passed"],"h1":"A green light does not beat a siren.","h2":"The Tennessee manual says that if the light turns green before the emergency vehicle has passed, do not go; wait until it has passed or turned.","p":"Right. Wait until the ambulance has passed."},"es":{"q":"En Tennessee, está detenido en un semáforo en rojo cuando se acerca una ambulancia. La luz cambia a verde antes de que pase. ¿Qué debe hacer?","o":["Avanzar, porque la luz está en verde","Dar vuelta a la derecha para quitarse","Acelerar para ir delante de ella","Quedarse donde está hasta que pase la ambulancia"],"h1":"Una luz verde no le gana a una sirena.","h2":"El manual de Tennessee dice que si la luz cambia a verde antes de que pase el vehículo de emergencia, no avance; espere hasta que pase o dé vuelta.","p":"Correcto. Espere hasta que pase la ambulancia."},"ref":{"doc":"TN","page":54}},{"id":"tn-141","scope":"TN","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Tennessee, a city bus has signaled and is pulling back into traffic from a bus stop. What must you do?","o":["Yield the right-of-way to the bus","Speed up to pass it","Honk and keep going","Stop as you would for a school bus with red lights"],"h1":"Let the bus back into the lane.","h2":"Tennessee drivers must yield the right-of-way to a transit bus that has signaled and is pulling back onto the road from a bus stop.","p":"Right. Yield to the bus."},"es":{"q":"En Tennessee, un autobús urbano puso la direccional y está regresando al tráfico desde una parada. ¿Qué debe hacer?","o":["Cederle el paso al autobús","Acelerar para rebasarlo","Tocar la bocina y seguir","Detenerse como ante un autobús escolar con luces rojas"],"h1":"Deje que el autobús regrese al carril.","h2":"Los conductores en Tennessee deben ceder el paso a un autobús de transporte público que puso la direccional y regresa a la calle desde una parada.","p":"Correcto. Cédale el paso al autobús."},"ref":{"doc":"TN","page":54}},{"id":"tn-142","scope":"TN","cat":"signals","sign":null,"c":2,"en":{"q":"In Tennessee, at least how far before a turn must you turn on your turn signal?","o":["10 feet","500 feet","50 feet","1 mile"],"h1":"It is a short distance, about three car lengths.","h2":"Tennessee drivers must turn on the turn signal at least 50 feet before turning or changing lanes.","p":"Right. At least 50 feet."},"es":{"q":"En Tennessee, ¿por lo menos a qué distancia antes de dar vuelta debe poner la direccional?","o":["10 pies","500 pies","50 pies","1 milla"],"h1":"Es una distancia corta, unos tres largos de carro.","h2":"Los conductores en Tennessee deben poner la direccional por lo menos 50 pies antes de dar vuelta o cambiar de carril.","p":"Correcto. Por lo menos 50 pies."},"ref":{"doc":"TN","page":56}},{"id":"tn-143","scope":"TN","cat":"signals","sign":null,"c":1,"en":{"q":"In Tennessee, you plan to turn into a driveway just past an intersection. When should you signal?","o":["Before the intersection","After you are in the intersection","After you have finished the turn","Do not signal at all"],"h1":"An early signal could make others think you are turning at the intersection.","h2":"The Tennessee manual says that if you plan to turn just beyond an intersection, do not signal until you are in the intersection.","p":"Right. Signal once you are in the intersection."},"es":{"q":"En Tennessee, piensa dar vuelta en una entrada justo después de una intersección. ¿Cuándo debe poner la direccional?","o":["Antes de la intersección","Después de entrar a la intersección","Después de terminar la vuelta","No debe poner direccional"],"h1":"Una señal temprana podría hacer creer a otros que da vuelta en la intersección.","h2":"El manual de Tennessee dice que si va a dar vuelta justo después de una intersección, no ponga la direccional hasta estar dentro de la intersección.","p":"Correcto. Ponga la direccional ya dentro de la intersección."},"ref":{"doc":"TN","page":56}},{"id":"tn-144","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, you are waiting to turn left while oncoming cars pass. How should your front wheels point?","o":["Turned fully left","Turned right","Any direction is fine","Straight ahead until you start the turn"],"h1":"If you are hit from behind, the wheels decide where you go.","h2":"The Tennessee manual says to keep your wheels straight while waiting to turn left, so a rear-end hit does not push you into oncoming traffic.","p":"Right. Keep the wheels straight until you turn."},"es":{"q":"En Tennessee, espera para dar vuelta a la izquierda mientras pasan los carros de enfrente. ¿Hacia dónde deben apuntar sus llantas delanteras?","o":["Totalmente a la izquierda","A la derecha","A cualquier lado","Derechas hasta que empiece la vuelta"],"h1":"Si le pegan por detrás, las llantas deciden a dónde va.","h2":"El manual de Tennessee dice que mantenga las llantas derechas mientras espera para dar vuelta a la izquierda, para que un golpe por detrás no lo empuje hacia el tráfico de enfrente.","p":"Correcto. Llantas derechas hasta dar la vuelta."},"ref":{"doc":"TN","page":56}},{"id":"tn-145","scope":"TN","cat":"signals","sign":null,"c":0,"en":{"q":"In Tennessee, when may you turn left on a red light, after a full stop?","o":["From a one-way street onto another one-way street going left","From any street when no cars are coming","From a two-way street onto a one-way street","Never"],"h1":"Both streets must be one-way.","h2":"Tennessee allows a left turn on red, after a complete stop and yielding, only from a one-way street onto a one-way street whose traffic moves to the left, unless a sign forbids it.","p":"Right. Only from one-way onto one-way."},"es":{"q":"En Tennessee, ¿cuándo puede dar vuelta a la izquierda con la luz roja, después de detenerse por completo?","o":["De una calle de un sentido a otra de un sentido que va hacia la izquierda","Desde cualquier calle si no vienen carros","De una calle de doble sentido a una de un sentido","Nunca"],"h1":"Ambas calles deben ser de un solo sentido.","h2":"Tennessee permite dar vuelta a la izquierda con luz roja, después de parar por completo y ceder el paso, solo de una calle de un sentido a otra de un sentido cuyo tráfico va hacia la izquierda, si ninguna señal lo prohíbe.","p":"Correcto. Solo de un sentido a un sentido."},"ref":{"doc":"TN","page":58}},{"id":"tn-146","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, you may not make a U-turn where you cannot see traffic coming from both directions for at least how far?","o":["50 feet","100 feet","500 feet","1 mile"],"h1":"It is about one city block.","h2":"Tennessee forbids U-turns where you cannot see traffic coming from both directions for at least 500 feet, including near curves and hilltops.","p":"Right. At least 500 feet each way."},"es":{"q":"En Tennessee, no puede dar vuelta en U donde no pueda ver el tráfico de ambas direcciones por lo menos a ¿qué distancia?","o":["50 pies","100 pies","500 pies","1 milla"],"h1":"Es más o menos una cuadra de ciudad.","h2":"Tennessee prohíbe las vueltas en U donde no pueda ver el tráfico de ambas direcciones por lo menos a 500 pies, incluso cerca de curvas y cimas de cerros.","p":"Correcto. Por lo menos 500 pies en cada dirección."},"ref":{"doc":"TN","page":59}},{"id":"tn-147","scope":"TN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Tennessee, you miss your exit on the interstate. May you use the paved emergency crossover in the median to turn around?","o":["Yes, if no one is coming","No, crossovers are only for emergency and highway maintenance vehicles","Yes, at night","Yes, if you signal first"],"h1":"U-turns on the interstate are illegal for regular drivers.","h2":"In Tennessee, U-turns on interstates are illegal, and emergency crossovers are only for emergency vehicles and highway maintenance crews.","p":"Right. Crossovers are only for emergency and maintenance vehicles."},"es":{"q":"En Tennessee, se pasó de su salida en la interestatal. ¿Puede usar el cruce pavimentado de emergencia en el camellón para regresarse?","o":["Sí, si no viene nadie","No, los cruces son solo para vehículos de emergencia y mantenimiento de carreteras","Sí, de noche","Sí, si pone la direccional antes"],"h1":"Las vueltas en U en la interestatal son ilegales para conductores normales.","h2":"En Tennessee, las vueltas en U en las interestatales son ilegales, y los cruces de emergencia son solo para vehículos de emergencia y cuadrillas de mantenimiento.","p":"Correcto. Los cruces son solo para emergencias y mantenimiento."},"ref":{"doc":"TN","page":59}},{"id":"tn-148","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, you drive on a road with no center line and a car comes toward you. How much of the road must you give it?","o":["None; first come, first served","A quarter of the road","The whole road","At least half of the road"],"h1":"Share it fairly.","h2":"On a Tennessee road with no center line, drivers must give oncoming traffic at least half of the road.","p":"Right. Give at least half the road."},"es":{"q":"En Tennessee, maneja en un camino sin línea central y viene un carro de frente. ¿Cuánto del camino debe darle?","o":["Nada; el primero que llega pasa","Una cuarta parte del camino","Todo el camino","Por lo menos la mitad del camino"],"h1":"Compártalo de forma justa.","h2":"En un camino de Tennessee sin línea central, los conductores deben dar al tráfico de enfrente por lo menos la mitad del camino.","p":"Correcto. Dé por lo menos la mitad del camino."},"ref":{"doc":"TN","page":59}},{"id":"tn-149","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, on a two-way road with three or five lanes, what is the center lane used for?","o":["Only for turning left","For passing","For slow trucks","For parking"],"h1":"Both directions share it, but not for driving along.","h2":"On a Tennessee two-way road with three or five lanes, the center lane is used only for turning left.","p":"Right. The center lane is only for left turns."},"es":{"q":"En Tennessee, en una calle de doble sentido con tres o cinco carriles, ¿para qué se usa el carril central?","o":["Solo para dar vuelta a la izquierda","Para rebasar","Para camiones lentos","Para estacionarse"],"h1":"Lo comparten ambas direcciones, pero no para avanzar.","h2":"En una calle de doble sentido de Tennessee con tres o cinco carriles, el carril central se usa solo para dar vuelta a la izquierda.","p":"Correcto. El carril central es solo para vueltas a la izquierda."},"ref":{"doc":"TN","page":59}},{"id":"tn-150","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, you and a car coming the other way both want to use the shared center turn lane. Who has the right-of-way?","o":["The bigger vehicle","The first vehicle to enter the lane","The vehicle turning right","The vehicle on the left"],"h1":"Timing decides it.","h2":"In a Tennessee shared center turn lane, when vehicles enter from opposite directions, the first vehicle to enter the lane has the right-of-way.","p":"Right. The first one in the lane goes first."},"es":{"q":"En Tennessee, usted y un carro que viene en sentido contrario quieren usar el carril central compartido para dar vuelta. ¿Quién tiene el derecho de paso?","o":["El vehículo más grande","El primer vehículo que entra al carril","El vehículo que da vuelta a la derecha","El vehículo de la izquierda"],"h1":"Lo decide quién llega primero.","h2":"En un carril central compartido de Tennessee, cuando entran vehículos de direcciones opuestas, el primero que entra al carril tiene el derecho de paso.","p":"Correcto. El primero en el carril va primero."},"ref":{"doc":"TN","page":60}},{"id":"tn-151","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, you want to turn left through a crossover on a divided four-lane highway, but another car is already waiting in it. What should you do?","o":["Pull in beside it","Pull in behind it, even if your car sticks out","Make a U-turn instead","Wait in the left lane with your signal on until the crossover is clear"],"h1":"Do not crowd into the opening.","h2":"The Tennessee manual says to stay stopped in the left lane with your turn signal on until the waiting vehicle has cleared the crossover.","p":"Right. Wait in the left lane until it clears."},"es":{"q":"En Tennessee, quiere dar vuelta a la izquierda por un cruce en una carretera dividida de cuatro carriles, pero otro carro ya está esperando en él. ¿Qué debe hacer?","o":["Meterse a su lado","Meterse detrás, aunque su carro quede salido","Mejor dar vuelta en U","Esperar en el carril izquierdo con la direccional puesta hasta que el cruce quede libre"],"h1":"No se amontone en la abertura.","h2":"El manual de Tennessee dice que se quede detenido en el carril izquierdo con la direccional puesta hasta que el vehículo que espera salga del cruce.","p":"Correcto. Espere en el carril izquierdo hasta que quede libre."},"ref":{"doc":"TN","page":60}},{"id":"tn-152","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, a lane sign says HOV 2. Who may use the lane when the rule is in effect?","o":["Vehicles with at least two people in them","Only buses","Only trucks with two axles","Anyone driving alone"],"h1":"HOV means high occupancy vehicle.","h2":"On Tennessee roads, HOV 2 means a vehicle must carry at least two people to use that lane.","p":"Right. At least two people in the vehicle."},"es":{"q":"En Tennessee, una señal de carril dice HOV 2. ¿Quién puede usar el carril cuando la regla está vigente?","o":["Vehículos con por lo menos dos personas","Solo autobuses","Solo camiones de dos ejes","Cualquiera que maneje solo"],"h1":"HOV significa vehículo de alta ocupación.","h2":"En las carreteras de Tennessee, HOV 2 significa que el vehículo debe llevar por lo menos dos personas para usar ese carril.","p":"Correcto. Por lo menos dos personas en el vehículo."},"ref":{"doc":"TN","page":61}},{"id":"tn-153","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, during the hours an interstate HOV lane is reserved, which of these may use it?","o":["A car with only the driver","A large truck with one driver","A motorcycle with one rider","A car pulling a trailer with one driver"],"h1":"Besides cars with passengers, the list includes buses, emergency vehicles and one more type.","h2":"During Tennessee HOV hours, the lane is for vehicles with two or more people, buses, emergency vehicles and motorcycles with one rider.","p":"Right. A motorcycle with one rider may use it."},"es":{"q":"En Tennessee, durante las horas en que el carril HOV de la interestatal está reservado, ¿cuál de estos puede usarlo?","o":["Un carro solo con el conductor","Un camión grande con un conductor","Una motocicleta con un solo conductor","Un carro con remolque y un conductor"],"h1":"Además de los carros con pasajeros, la lista incluye autobuses, vehículos de emergencia y un tipo más.","h2":"Durante las horas HOV en Tennessee, el carril es para vehículos con dos o más personas, autobuses, vehículos de emergencia y motocicletas con un solo conductor.","p":"Correcto. Una motocicleta con un conductor puede usarlo."},"ref":{"doc":"TN","page":69}},{"id":"tn-154","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, is it legal to pass more than one vehicle at a time on a two-lane road?","o":["No, never","Yes, at any time","Only at night","It is not illegal, but you must be back in your lane at least 100 feet before a no-passing zone or oncoming car"],"h1":"The manual says it is not illegal, but it is risky.","h2":"Passing several vehicles is not illegal in Tennessee, but you should only do it if you can be back in the right lane at least 100 feet before a no-passing zone or any oncoming vehicle.","p":"Right. It is legal, with that 100-foot margin."},"es":{"q":"En Tennessee, ¿es legal rebasar a más de un vehículo a la vez en una carretera de dos carriles?","o":["No, nunca","Sí, en cualquier momento","Solo de noche","No es ilegal, pero debe volver a su carril por lo menos 100 pies antes de una zona de no rebasar o de un carro de frente"],"h1":"El manual dice que no es ilegal, pero es arriesgado.","h2":"Rebasar a varios vehículos no es ilegal en Tennessee, pero solo debe hacerlo si puede volver al carril derecho por lo menos 100 pies antes de una zona de no rebasar o de cualquier vehículo de frente.","p":"Correcto. Es legal, con ese margen de 100 pies."},"ref":{"doc":"TN","page":62}},{"id":"tn-155","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, cars are stopped at a red light. May you pass them on the right by driving in the bike lane or parking lane?","o":["No, never","Yes, if the bike lane is empty","Yes, if you are turning right later","Yes, at low speed"],"h1":"Those lanes are not for passing.","h2":"Tennessee drivers may never pass on the right by using a bike lane or parking lane, or the emergency lane near a traffic light or stop sign.","p":"Right. Never pass in a bike or parking lane."},"es":{"q":"En Tennessee, hay carros detenidos en un semáforo en rojo. ¿Puede rebasarlos por la derecha manejando en el carril de bicicletas o de estacionamiento?","o":["No, nunca","Sí, si el carril de bicicletas está vacío","Sí, si después va a dar vuelta a la derecha","Sí, a baja velocidad"],"h1":"Esos carriles no son para rebasar.","h2":"Los conductores en Tennessee nunca pueden rebasar por la derecha usando un carril de bicicletas o de estacionamiento, ni el carril de emergencia cerca de un semáforo o un alto.","p":"Correcto. Nunca rebase en un carril de bicicletas o de estacionamiento."},"ref":{"doc":"TN","page":62}},{"id":"tn-156","scope":"TN","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Tennessee, on a multi-lane road you stop for people at a crosswalk. About how far before the crosswalk should you stop?","o":["Right on the crosswalk line","5 feet","About 30 feet","About 300 feet"],"h1":"Stopping back lets drivers in other lanes see the walkers.","h2":"The Tennessee manual suggests stopping about 30 feet before a crosswalk on a multi-lane road, so you do not block other drivers' view of the people crossing.","p":"Right. About 30 feet back."},"es":{"q":"En Tennessee, en una calle de varios carriles se detiene por personas en un cruce peatonal. ¿Más o menos a qué distancia antes del cruce debe detenerse?","o":["Justo en la línea del cruce","5 pies","Unos 30 pies","Unos 300 pies"],"h1":"Detenerse más atrás deja que los conductores de otros carriles vean a quienes cruzan.","h2":"El manual de Tennessee sugiere detenerse unos 30 pies antes del cruce en una calle de varios carriles, para no tapar la vista de los otros conductores hacia las personas que cruzan.","p":"Correcto. Unos 30 pies antes."},"ref":{"doc":"TN","page":63}},{"id":"tn-157","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, how much space does the law require when you pass a bicycle going your way?","o":["1 foot","At least 3 feet","At least 10 feet","Any amount, if you honk"],"h1":"It is about the length of a yardstick.","h2":"Tennessee law requires drivers to pass a bicycle slowly and leave at least 3 feet of space until safely past.","p":"Right. At least 3 feet."},"es":{"q":"En Tennessee, ¿cuánto espacio exige la ley cuando rebasa a una bicicleta que va en su misma dirección?","o":["1 pie","Por lo menos 3 pies","Por lo menos 10 pies","Cualquier espacio, si toca la bocina"],"h1":"Es más o menos el largo de una yarda.","h2":"La ley de Tennessee exige rebasar a una bicicleta despacio y dejar por lo menos 3 pies de espacio hasta terminar de pasarla.","p":"Correcto. Por lo menos 3 pies."},"ref":{"doc":"TN","page":63}},{"id":"tn-158","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, you park beside a road outside city limits and cannot get all four wheels off the pavement. How much road width must you leave for traffic?","o":["6 feet","10 feet","25 feet","At least 18 feet"],"h1":"It is about the width of one and a half lanes.","h2":"Outside Tennessee city limits, a parked vehicle must leave at least 18 feet of road width for traffic and be visible for 200 feet in both directions.","p":"Right. At least 18 feet."},"es":{"q":"En Tennessee, se estaciona junto a una carretera fuera de la ciudad y no puede sacar las cuatro llantas del pavimento. ¿Cuánto ancho de camino debe dejar para el tráfico?","o":["6 pies","10 pies","25 pies","Por lo menos 18 pies"],"h1":"Es más o menos el ancho de un carril y medio.","h2":"Fuera de los límites de la ciudad en Tennessee, un vehículo estacionado debe dejar por lo menos 18 pies de ancho de camino para el tráfico y verse a 200 pies en ambas direcciones.","p":"Correcto. Por lo menos 18 pies."},"ref":{"doc":"TN","page":65}},{"id":"tn-159","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, may you leave your car's engine running while it is parked and no one is in it?","o":["No, it is against the law","Yes, for up to 10 minutes","Yes, if the doors are locked","Yes, in cold weather"],"h1":"Take the keys with you.","h2":"Tennessee law forbids leaving the engine running in a parked, unattended vehicle.","p":"Right. It is against the law."},"es":{"q":"En Tennessee, ¿puede dejar el motor encendido en su carro estacionado sin nadie adentro?","o":["No, es contra la ley","Sí, hasta por 10 minutos","Sí, si cierra las puertas con llave","Sí, cuando hace frío"],"h1":"Llévese las llaves.","h2":"La ley de Tennessee prohíbe dejar el motor encendido en un vehículo estacionado sin nadie.","p":"Correcto. Es contra la ley."},"ref":{"doc":"TN","page":65}},{"id":"tn-160","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, you may not park within how many feet of a crosswalk?","o":["5 feet","10 feet","20 feet","50 feet"],"h1":"It is more than the fire hydrant distance.","h2":"In Tennessee, it is illegal to park within 20 feet of a crosswalk or in the crosswalk itself.","p":"Right. Not within 20 feet of a crosswalk."},"es":{"q":"En Tennessee, ¿a cuántos pies de un cruce peatonal no puede estacionarse?","o":["5 pies","10 pies","20 pies","50 pies"],"h1":"Es más que la distancia del hidrante.","h2":"En Tennessee, es ilegal estacionarse a menos de 20 pies de un cruce peatonal o dentro del cruce.","p":"Correcto. No a menos de 20 pies del cruce."},"ref":{"doc":"TN","page":65}},{"id":"tn-161","scope":"TN","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Tennessee, you want to park across the street from a fire station driveway. How far away must you be?","o":["20 feet","75 feet","15 feet","150 feet"],"h1":"It is farther than the same-side rule of 20 feet.","h2":"In Tennessee, you may not park within 20 feet of a fire station driveway on the same side, or within 75 feet on the other side of the street.","p":"Right. 75 feet on the opposite side."},"es":{"q":"En Tennessee, quiere estacionarse al otro lado de la calle frente a la entrada de una estación de bomberos. ¿A qué distancia debe quedar?","o":["20 pies","75 pies","15 pies","150 pies"],"h1":"Es más que la regla de 20 pies del mismo lado.","h2":"En Tennessee, no puede estacionarse a menos de 20 pies de la entrada de una estación de bomberos del mismo lado, ni a menos de 75 pies del otro lado de la calle.","p":"Correcto. 75 pies del lado contrario."},"ref":{"doc":"TN","page":65}},{"id":"tn-162","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, you may not park within how many feet of a stop sign or traffic signal?","o":["5 feet","10 feet","100 feet","30 feet"],"h1":"It is twice the fire hydrant distance.","h2":"In Tennessee, it is illegal to park within 30 feet of a traffic signal, stop sign or other traffic control device.","p":"Right. Not within 30 feet."},"es":{"q":"En Tennessee, ¿a cuántos pies de un alto o un semáforo no puede estacionarse?","o":["5 pies","10 pies","100 pies","30 pies"],"h1":"Es el doble de la distancia del hidrante.","h2":"En Tennessee, es ilegal estacionarse a menos de 30 pies de un semáforo, un alto u otro dispositivo de control de tránsito.","p":"Correcto. No a menos de 30 pies."},"ref":{"doc":"TN","page":65}},{"id":"tn-163","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, you may not park within how many feet of a railroad crossing?","o":["10 feet","15 feet","50 feet","500 feet"],"h1":"It is the far end of the stopping range for trains.","h2":"In Tennessee, it is illegal to park within 50 feet of a railroad crossing.","p":"Right. Not within 50 feet."},"es":{"q":"En Tennessee, ¿a cuántos pies de un cruce de ferrocarril no puede estacionarse?","o":["10 pies","15 pies","50 pies","500 pies"],"h1":"Es el extremo lejano del rango para detenerse por un tren.","h2":"En Tennessee, es ilegal estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. No a menos de 50 pies."},"ref":{"doc":"TN","page":65}},{"id":"tn-164","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, what does a curb painted yellow mean?","o":["Stop only long enough to load or unload, and stay with your car","Park as long as you like","Never stop for any reason","Parking for buses only"],"h1":"White is for passengers; red is for no stopping.","h2":"On a Tennessee curb, yellow means stop only long enough to load or unload and stay with your car.","p":"Right. Yellow means load or unload only."},"es":{"q":"En Tennessee, ¿qué significa la orilla de la acera pintada de amarillo?","o":["Pare solo el tiempo necesario para cargar o descargar, y quédese con su carro","Estaciónese el tiempo que quiera","Nunca se detenga por ningún motivo","Estacionamiento solo para autobuses"],"h1":"El blanco es para pasajeros; el rojo es para no detenerse.","h2":"En la orilla de la acera en Tennessee, el amarillo significa parar solo el tiempo necesario para cargar o descargar y quedarse con su carro.","p":"Correcto. El amarillo significa solo cargar o descargar."},"ref":{"doc":"TN","page":66}},{"id":"tn-165","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, after parallel parking, how far from the curb may your car be at most?","o":["6 inches","3 feet","24 inches","18 inches"],"h1":"It is a foot and a half.","h2":"In Tennessee, a parallel-parked car should be no farther than 18 inches from the curb.","p":"Right. No more than 18 inches."},"es":{"q":"En Tennessee, después de estacionarse en paralelo, ¿a qué distancia máxima de la acera puede quedar su carro?","o":["6 pulgadas","3 pies","24 pulgadas","18 pulgadas"],"h1":"Es un pie y medio.","h2":"En Tennessee, un carro estacionado en paralelo no debe quedar a más de 18 pulgadas de la acera.","p":"Correcto. No más de 18 pulgadas."},"ref":{"doc":"TN","page":66}},{"id":"tn-166","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, your car breaks down and you cannot move it off the highway. How can you warn other drivers, besides the flashers?","o":["Leave the trunk open and walk away","Raise the hood or tie a cloth to the left door handle or antenna","Turn on your high beams","Park in the middle of the lane"],"h1":"Use a signal other drivers recognize as trouble.","h2":"The Tennessee manual says to raise the hood or tie a handkerchief or white cloth to the left door handle or antenna, and turn on your emergency flashers.","p":"Right. Raise the hood or tie a cloth to the door handle or antenna."},"es":{"q":"En Tennessee, su carro se descompone y no puede sacarlo de la carretera. ¿Cómo puede avisar a otros conductores, además de las intermitentes?","o":["Dejar la cajuela abierta e irse caminando","Levantar el cofre o amarrar un trapo en la manija de la puerta izquierda o en la antena","Prender las luces altas","Estacionarse en medio del carril"],"h1":"Use una señal que otros reconozcan como problema.","h2":"El manual de Tennessee dice que levante el cofre o amarre un pañuelo o trapo blanco en la manija de la puerta izquierda o en la antena, y prenda las luces intermitentes de emergencia.","p":"Correcto. Levante el cofre o amarre un trapo en la manija o la antena."},"ref":{"doc":"TN","page":66}},{"id":"tn-167","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, your car breaks down on the interstate. Should you walk along the interstate for help?","o":["Yes, it is the fastest way","Yes, on the left shoulder","No, it is illegal and dangerous; stay in or near your car","Yes, if you wear bright clothes"],"h1":"Help usually comes to you.","h2":"Walking on a Tennessee interstate is illegal and dangerous, so except in an extreme emergency, stay with your vehicle until an officer or helper arrives.","p":"Right. Do not walk on the interstate."},"es":{"q":"En Tennessee, su carro se descompone en la interestatal. ¿Debe caminar por la interestatal para buscar ayuda?","o":["Sí, es lo más rápido","Sí, por el acotamiento izquierdo","No, es ilegal y peligroso; quédese en su carro o cerca de él","Sí, si lleva ropa de colores vivos"],"h1":"La ayuda por lo general llega a usted.","h2":"Caminar por una interestatal de Tennessee es ilegal y peligroso, así que salvo una emergencia extrema, quédese con su vehículo hasta que llegue un oficial o alguien a ayudar.","p":"Correcto. No camine por la interestatal."},"ref":{"doc":"TN","page":66}},{"id":"tn-168","scope":"TN","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Tennessee, what is the fine for parking in a space reserved for people with disabilities without a placard or plate?","o":["$200, and your car may be towed","$10","$25 with no towing","A warning only"],"h1":"It is a misdemeanor, and the fine cannot be waived.","h2":"In Tennessee, parking in a disability space without the right placard or plate is a misdemeanor with a $200 fine, and the car may be towed.","p":"Right. $200, and possible towing."},"es":{"q":"En Tennessee, ¿cuál es la multa por estacionarse en un lugar reservado para personas con discapacidad sin placa o permiso?","o":["$200, y le pueden llevar el carro con grúa","$10","$25 sin grúa","Solo una advertencia"],"h1":"Es un delito menor, y la multa no se puede perdonar.","h2":"En Tennessee, estacionarse en un lugar para personas con discapacidad sin el permiso o placa correctos es un delito menor con multa de $200, y el carro puede ser remolcado.","p":"Correcto. $200 y posible grúa."},"ref":{"doc":"TN","page":null}},{"id":"tn-170","scope":"TN","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Tennessee, exit signs on the interstate are usually placed how far ahead of the exit?","o":["100 feet","500 feet","10 miles","At least one mile"],"h1":"It gives you time to move to the right lane.","h2":"On Tennessee interstates, exit signs are usually placed at least one mile ahead of the exit.","p":"Right. At least one mile ahead."},"es":{"q":"En Tennessee, ¿a qué distancia antes de la salida se ponen por lo general las señales de salida en la interestatal?","o":["100 pies","500 pies","10 millas","Por lo menos una milla"],"h1":"Le da tiempo para pasarse al carril derecho.","h2":"En las interestatales de Tennessee, las señales de salida se ponen por lo general por lo menos una milla antes de la salida.","p":"Correcto. Por lo menos una milla antes."},"ref":{"doc":"TN","page":69}},{"id":"tn-171","scope":"TN","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Tennessee, at a cloverleaf interchange, how do you turn left onto the crossroad?","o":["Turn left before the overpass","Cross the median","Take the right-turn ramp just after the overpass","Stop and back up"],"h1":"At a cloverleaf, every turn is a right turn.","h2":"At a Tennessee cloverleaf interchange, you turn left by taking the right-turn ramp just after the overpass, which loops you onto the crossroad.","p":"Right. Take the right ramp after the overpass."},"es":{"q":"En Tennessee, en un intercambio tipo trébol (cloverleaf), ¿cómo da vuelta a la izquierda hacia la calle que cruza?","o":["Dar vuelta a la izquierda antes del puente","Cruzar el camellón","Tomar la rampa de vuelta a la derecha justo después del puente","Detenerse y retroceder"],"h1":"En un trébol, todas las vueltas son a la derecha.","h2":"En un intercambio tipo trébol de Tennessee, para ir a la izquierda toma la rampa de vuelta a la derecha justo después del puente, que da la vuelta hacia la calle que cruza.","p":"Correcto. Tome la rampa derecha después del puente."},"ref":{"doc":"TN","page":70}},{"id":"tn-172","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, on a long interstate trip, how often should you stop and get out of the car for a break?","o":["At least every two hours or about 100 miles","Only when you need gas","Every 6 hours","Every 500 miles"],"h1":"Regular breaks help fight highway hypnosis.","h2":"The Tennessee manual says to take a break and get out of the car at least every two hours or about every 100 miles.","p":"Right. Every two hours or about 100 miles."},"es":{"q":"En Tennessee, en un viaje largo por la interestatal, ¿cada cuánto debe parar y bajarse del carro a descansar?","o":["Por lo menos cada dos horas o unas 100 millas","Solo cuando necesite gasolina","Cada 6 horas","Cada 500 millas"],"h1":"Los descansos regulares ayudan contra la hipnosis de carretera.","h2":"El manual de Tennessee dice que descanse y se baje del carro por lo menos cada dos horas o más o menos cada 100 millas.","p":"Correcto. Cada dos horas o unas 100 millas."},"ref":{"doc":"TN","page":71}},{"id":"tn-173","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, can you be convicted of DUI if your blood alcohol is below 0.08?","o":["No, never","Yes, if you are impaired by alcohol or drugs","Only if you are under 18","Only on a second offense"],"h1":"The 0.08 number is not the only test of impairment.","h2":"In Tennessee, a driver can be convicted of DUI with a blood alcohol level below 0.08, even 0.00, if impaired by alcohol or drugs, including prescription drugs.","p":"Right. Impairment alone can bring a DUI."},"es":{"q":"En Tennessee, ¿lo pueden condenar por DUI si su nivel de alcohol en la sangre es menor de 0.08?","o":["No, nunca","Sí, si el alcohol o las drogas lo afectan","Solo si es menor de 18","Solo la segunda vez"],"h1":"El número 0.08 no es la única prueba de que está afectado.","h2":"En Tennessee, a un conductor lo pueden condenar por DUI con un nivel de alcohol menor de 0.08, incluso 0.00, si el alcohol o las drogas, incluso recetadas, lo afectan.","p":"Correcto. Estar afectado basta para un DUI."},"ref":{"doc":"TN","page":81}},{"id":"tn-174","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, what does the 2012 \"No Refusal\" law allow officers to do?","o":["Take your car keys at any traffic stop","Skip the arrest for DUI","Test every driver at checkpoints without cause","Seek a search warrant for a blood sample from a suspected impaired driver"],"h1":"It is about getting a blood test.","h2":"Tennessee's No Refusal law lets law enforcement seek search warrants for blood samples in cases of suspected impaired driving.","p":"Right. Officers can seek a warrant for a blood sample."},"es":{"q":"En Tennessee, ¿qué permite a los oficiales la ley \"No Refusal\" de 2012?","o":["Quitarle las llaves en cualquier parada","No arrestar por DUI","Hacer la prueba a todos en los retenes sin motivo","Pedir una orden judicial para una muestra de sangre de un conductor sospechoso de estar afectado"],"h1":"Se trata de obtener una prueba de sangre.","h2":"La ley No Refusal de Tennessee permite a la policía pedir órdenes judiciales para muestras de sangre en casos de sospecha de manejo bajo los efectos.","p":"Correcto. Pueden pedir una orden para una muestra de sangre."},"ref":{"doc":"TN","page":81}},{"id":"tn-175","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a first DUI conviction usually brings at least 48 hours in jail. What is the minimum if the blood alcohol was 0.15 or more?","o":["24 hours","72 hours","7 days","30 days"],"h1":"It is one week.","h2":"For a first DUI in Tennessee, the minimum jail time rises from 48 hours to 7 days when the blood alcohol level was 0.15 or more.","p":"Right. At least 7 days."},"es":{"q":"En Tennessee, una primera condena por DUI por lo general trae por lo menos 48 horas de cárcel. ¿Cuál es el mínimo si el alcohol en la sangre era 0.15 o más?","o":["24 horas","72 horas","7 días","30 días"],"h1":"Es una semana.","h2":"En un primer DUI en Tennessee, la cárcel mínima sube de 48 horas a 7 días cuando el nivel de alcohol era 0.15 o más.","p":"Correcto. Por lo menos 7 días."},"ref":{"doc":"TN","page":null}},{"id":"tn-176","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, what is the fine range for a first DUI conviction?","o":["$350 to $1,500","$50 to $100","$5,000 to $10,000","$100 to $250"],"h1":"It starts at a few hundred dollars.","h2":"A first DUI conviction in Tennessee carries a fine of $350 to $1,500, plus other costs.","p":"Right. $350 to $1,500."},"es":{"q":"En Tennessee, ¿cuál es el rango de la multa por una primera condena por DUI?","o":["De $350 a $1,500","De $50 a $100","De $5,000 a $10,000","De $100 a $250"],"h1":"Empieza en unos cientos de dólares.","h2":"Una primera condena por DUI en Tennessee trae una multa de $350 a $1,500, más otros costos.","p":"Correcto. De $350 a $1,500."},"ref":{"doc":"TN","page":82}},{"id":"tn-177","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how long is the license revocation for a first DUI conviction?","o":["30 days","90 days","6 months","1 year"],"h1":"A second DUI doubles it.","h2":"A first DUI conviction in Tennessee brings a license revocation of one year.","p":"Right. One year."},"es":{"q":"En Tennessee, ¿por cuánto tiempo revocan la licencia por una primera condena por DUI?","o":["30 días","90 días","6 meses","1 año"],"h1":"Un segundo DUI lo duplica.","h2":"Una primera condena por DUI en Tennessee trae la revocación de la licencia por un año.","p":"Correcto. Un año."},"ref":{"doc":"TN","page":82}},{"id":"tn-178","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, a person convicted of DUI must pick up litter as part of probation. What must the person wear?","o":["A bright orange hat","A vest that says \"I am a DRUNK DRIVER\"","An ankle monitor only","A school uniform"],"h1":"It is meant to make the reason for the work public.","h2":"A Tennessee DUI conviction requires three eight-hour shifts of litter pickup while wearing clothing with the words \"I am a DRUNK DRIVER\" on it.","p":"Right. A vest saying \"I am a DRUNK DRIVER.\""},"es":{"q":"En Tennessee, una persona condenada por DUI debe recoger basura como parte de su libertad condicional. ¿Qué debe llevar puesto?","o":["Una gorra naranja brillante","Un chaleco que dice \"I am a DRUNK DRIVER\" (soy un conductor ebrio)","Solo un brazalete en el tobillo","Un uniforme escolar"],"h1":"Busca que todos sepan el motivo de ese trabajo.","h2":"Una condena por DUI en Tennessee exige tres turnos de ocho horas recogiendo basura con ropa que dice \"I am a DRUNK DRIVER\" (soy un conductor ebrio).","p":"Correcto. Un chaleco que dice \"I am a DRUNK DRIVER\"."},"ref":{"doc":"TN","page":81}},{"id":"tn-179","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a person has two DUIs within five years. After the license is reinstated, what must the person use for six months?","o":["A GPS tracker","A speed limiter","An ignition interlock device","A special red license plate"],"h1":"The device checks your breath before the car starts.","h2":"In Tennessee, a person with two DUIs in a five-year period must drive only a vehicle with an ignition interlock device for six months after reinstatement.","p":"Right. An ignition interlock device."},"es":{"q":"En Tennessee, una persona tiene dos DUI en cinco años. Después de que le devuelven la licencia, ¿qué debe usar por seis meses?","o":["Un rastreador GPS","Un limitador de velocidad","Un dispositivo de bloqueo de encendido (interlock)","Una placa roja especial"],"h1":"El aparato revisa su aliento antes de que arranque el carro.","h2":"En Tennessee, una persona con dos DUI en cinco años solo puede manejar un vehículo con dispositivo de bloqueo de encendido durante seis meses después de recuperar la licencia.","p":"Correcto. Un dispositivo de bloqueo de encendido."},"ref":{"doc":"TN","page":82}},{"id":"tn-180","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a 14-year-old is found guilty of having alcohol. What happens to the teen's driving privilege?","o":["It is suspended for one year or until age 17, whichever is longer","Nothing, because the teen has no license","A warning letter only","It is suspended for 30 days"],"h1":"Even someone never licensed can lose the privilege.","h2":"In Tennessee, a person 13 to 17 found to have possessed, used or sold alcohol or drugs loses the driving privilege for one year or until age 17, whichever is longer.","p":"Right. One year or until 17, whichever is longer."},"es":{"q":"En Tennessee, a un joven de 14 años lo declaran culpable de tener alcohol. ¿Qué pasa con su privilegio de manejar?","o":["Se suspende por un año o hasta los 17 años, lo que sea más largo","Nada, porque no tiene licencia","Solo una carta de advertencia","Se suspende por 30 días"],"h1":"Incluso alguien que nunca tuvo licencia puede perder el privilegio.","h2":"En Tennessee, una persona de 13 a 17 años a quien encuentran con alcohol o drogas, o usándolos o vendiéndolos, pierde el privilegio de manejar por un año o hasta los 17 años, lo que sea más largo.","p":"Correcto. Un año o hasta los 17, lo que sea más largo."},"ref":{"doc":"TN","page":83}},{"id":"tn-181","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, according to the manual, a driver with a blood alcohol level of 0.10 is how much more likely to cause a crash than a sober driver?","o":["Twice as likely","Seven times as likely","50 percent more likely","No more likely"],"h1":"The risk rises fast with each drink.","h2":"The Tennessee manual says that at a blood alcohol level of 0.10, you are seven times more likely to cause a crash than if you were sober.","p":"Right. Seven times as likely."},"es":{"q":"En Tennessee, según el manual, un conductor con 0.10 de alcohol en la sangre ¿cuántas veces más probable es que cause un choque que un conductor sobrio?","o":["Dos veces","Siete veces","50 por ciento más","Igual de probable"],"h1":"El riesgo sube rápido con cada trago.","h2":"El manual de Tennessee dice que con 0.10 de alcohol en la sangre, es siete veces más probable que cause un choque que si estuviera sobrio.","p":"Correcto. Siete veces más probable."},"ref":{"doc":"TN","page":79}},{"id":"tn-182","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, an adult driver gets 12 or more points within 12 months. What happens?","o":["Nothing until 24 points","A fine only","The license is canceled forever","The driver gets a notice of proposed suspension"],"h1":"An advisory letter comes earlier, at 6 to 11 points.","h2":"In Tennessee, an adult with 12 or more points in 12 months receives a notice of proposed suspension.","p":"Right. A notice of proposed suspension."},"es":{"q":"En Tennessee, un conductor adulto acumula 12 puntos o más en 12 meses. ¿Qué pasa?","o":["Nada hasta los 24 puntos","Solo una multa","Le cancelan la licencia para siempre","Recibe un aviso de suspensión propuesta"],"h1":"Antes llega una carta de advertencia, con 6 a 11 puntos.","h2":"En Tennessee, un adulto con 12 puntos o más en 12 meses recibe un aviso de suspensión propuesta.","p":"Correcto. Un aviso de suspensión propuesta."},"ref":{"doc":"TN","page":86}},{"id":"tn-183","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, a driver under 18 gets points within 12 months. At how many points does the teen get a notice of proposed suspension?","o":["12 points","3 points","6 points","10 points"],"h1":"It is half the adult number.","h2":"In Tennessee, a driver under 18 with 6 or more points in 12 months receives a notice of proposed suspension.","p":"Right. 6 points for drivers under 18."},"es":{"q":"En Tennessee, un conductor menor de 18 acumula puntos en 12 meses. ¿Con cuántos puntos recibe un aviso de suspensión propuesta?","o":["12 puntos","3 puntos","6 puntos","10 puntos"],"h1":"Es la mitad del número para adultos.","h2":"En Tennessee, un conductor menor de 18 con 6 puntos o más en 12 meses recibe un aviso de suspensión propuesta.","p":"Correcto. 6 puntos para menores de 18."},"ref":{"doc":"TN","page":86}},{"id":"tn-184","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, a driver may take a Defensive Driving Course to avoid or shorten a suspension. How often can this option be used?","o":["Once in any five-year period","Once a year","Any number of times","Only once in a lifetime"],"h1":"It is not available every year.","h2":"In Tennessee, the Defensive Driving Course option to avoid or reduce a suspension can be used only once in any five-year period.","p":"Right. Once every five years."},"es":{"q":"En Tennessee, un conductor puede tomar un Curso de Manejo Defensivo para evitar o acortar una suspensión. ¿Cada cuánto puede usar esta opción?","o":["Una vez en cualquier período de cinco años","Una vez al año","Las veces que quiera","Solo una vez en la vida"],"h1":"No está disponible cada año.","h2":"En Tennessee, la opción del Curso de Manejo Defensivo para evitar o reducir una suspensión solo se puede usar una vez en cualquier período de cinco años.","p":"Correcto. Una vez cada cinco años."},"ref":{"doc":"TN","page":86}},{"id":"tn-185","scope":"TN","cat":"licensing","sign":null,"c":1,"en":{"q":"In Tennessee, how many points go on your record for driving 6 to 15 mph over the speed limit (outside a work zone)?","o":["1 point","3 points","6 points","8 points"],"h1":"It is a small number, but more than 1.","h2":"In Tennessee, speeding 6 to 15 mph over the limit adds 3 points, or 4 points in a construction zone.","p":"Right. 3 points."},"es":{"q":"En Tennessee, ¿cuántos puntos le ponen por manejar de 6 a 15 mph sobre el límite (fuera de una zona de trabajo)?","o":["1 punto","3 puntos","6 puntos","8 puntos"],"h1":"Es un número pequeño, pero más de 1.","h2":"En Tennessee, ir de 6 a 15 mph sobre el límite suma 3 puntos, o 4 puntos en una zona de construcción.","p":"Correcto. 3 puntos."},"ref":{"doc":"TN","page":87}},{"id":"tn-186","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, how many points go on your record for passing a stopped school bus that is loading or unloading?","o":["2 points","4 points","6 points","8 points"],"h1":"It is one of the highest point values in the table.","h2":"Passing a stopped school, church or youth bus that is loading or unloading adds 8 points to a Tennessee driving record.","p":"Right. 8 points."},"es":{"q":"En Tennessee, ¿cuántos puntos le ponen por rebasar un autobús escolar detenido que está subiendo o bajando pasajeros?","o":["2 puntos","4 puntos","6 puntos","8 puntos"],"h1":"Es uno de los valores más altos de la tabla.","h2":"Rebasar un autobús escolar, de iglesia o juvenil detenido que sube o baja pasajeros suma 8 puntos al historial de manejo en Tennessee.","p":"Correcto. 8 puntos."},"ref":{"doc":"TN","page":87}},{"id":"tn-187","scope":"TN","cat":"licensing","sign":null,"c":2,"en":{"q":"In Tennessee, your license is suspended. Within how many days must you turn it in to the Department of Safety?","o":["5 days","10 days","20 days","60 days"],"h1":"Not turning it in brings an extra $75 fine.","h2":"A suspended or revoked Tennessee license must be turned in within 20 days, or you will be fined $75 on top of other costs.","p":"Right. Within 20 days."},"es":{"q":"En Tennessee, le suspendieron la licencia. ¿En cuántos días debe entregarla al Departamento de Seguridad?","o":["5 días","10 días","20 días","60 días"],"h1":"Si no la entrega, le ponen una multa extra de $75.","h2":"Una licencia suspendida o revocada en Tennessee debe entregarse en 20 días, o le ponen una multa de $75 además de otros costos.","p":"Correcto. En 20 días."},"ref":{"doc":"TN","page":85}},{"id":"tn-188","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, which of these can get your driver license suspended?","o":["Driving away from a gas pump without paying","Forgetting to wash your car","Driving with the radio on","Parking in a paid lot"],"h1":"It is a kind of theft involving a car.","h2":"Tennessee can suspend a license for driving away from a gas station without paying for the fuel.","p":"Right. A gas drive-off can cost you your license."},"es":{"q":"En Tennessee, ¿cuál de estos puede hacer que le suspendan la licencia?","o":["Irse de la gasolinera sin pagar la gasolina","Olvidar lavar su carro","Manejar con la radio prendida","Estacionarse en un lugar de pago"],"h1":"Es un tipo de robo que tiene que ver con un carro.","h2":"Tennessee puede suspender la licencia por irse de una gasolinera sin pagar el combustible.","p":"Correcto. Irse sin pagar la gasolina puede costarle la licencia."},"ref":{"doc":"TN","page":85}},{"id":"tn-189","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, after a crash, you must notify the police right away if anyone is hurt or killed, or if property damage is over what amount?","o":["$400","$1,000","$2,500","$50"],"h1":"This amount is much lower than the one for the written state report.","h2":"Tennessee drivers must immediately notify local police, the sheriff or the Highway Patrol of any crash with death, injury or property damage over $50.","p":"Right. Over $50."},"es":{"q":"En Tennessee, después de un choque debe avisar a la policía de inmediato si hay heridos o muertos, o si los daños pasan de ¿qué cantidad?","o":["$400","$1,000","$2,500","$50"],"h1":"Esta cantidad es mucho menor que la del reporte escrito al estado.","h2":"Los conductores en Tennessee deben avisar de inmediato a la policía local, al sheriff o a la Patrulla de Carreteras de cualquier choque con muertos, heridos o daños de más de $50.","p":"Correcto. Más de $50."},"ref":{"doc":"TN","page":89}},{"id":"tn-190","scope":"TN","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Tennessee, you have a minor crash on the interstate. No one is seriously hurt and the cars still run. What does the law allow?","o":["Leaving the scene to call later","Moving the cars to the shoulder or emergency lane to wait for police","Leaving the cars in the lane until police arrive, no matter what","Driving home and reporting it the next day"],"h1":"Signs along Tennessee interstates remind drivers of this.","h2":"Tennessee law lets you move drivable vehicles to the shoulder or emergency lane after a crash with no serious injuries, then wait for police there.","p":"Right. Move the cars to the shoulder and wait."},"es":{"q":"En Tennessee, tiene un choque leve en la interestatal. Nadie está gravemente herido y los carros todavía funcionan. ¿Qué permite la ley?","o":["Irse del lugar y llamar después","Mover los carros al acotamiento o carril de emergencia y esperar a la policía","Dejar los carros en el carril hasta que llegue la policía, pase lo que pase","Irse a casa y reportarlo al día siguiente"],"h1":"Hay letreros en las interestatales de Tennessee que lo recuerdan.","h2":"La ley de Tennessee permite mover los vehículos que funcionan al acotamiento o carril de emergencia después de un choque sin heridos graves, y esperar ahí a la policía.","p":"Correcto. Mueva los carros al acotamiento y espere."},"ref":{"doc":"TN","page":73}},{"id":"tn-191","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, what number can you dial free on a cell phone to reach the Tennessee Highway Patrol about a highway emergency?","o":["411","*911#","*THP (*847)","1-800-ROADS"],"h1":"The letters stand for Tennessee Highway Patrol.","h2":"In Tennessee, dialing *THP (*847) on a cell phone connects you free to the nearest Tennessee Highway Patrol dispatcher.","p":"Right. Dial *THP (*847)."},"es":{"q":"En Tennessee, ¿qué número puede marcar gratis desde un celular para comunicarse con la Patrulla de Carreteras de Tennessee por una emergencia en la carretera?","o":["411","*911#","*THP (*847)","1-800-ROADS"],"h1":"Las letras significan Tennessee Highway Patrol.","h2":"En Tennessee, al marcar *THP (*847) desde un celular lo comunican gratis con el despachador más cercano de la Patrulla de Carreteras de Tennessee.","p":"Correcto. Marque *THP (*847)."},"ref":{"doc":"TN","page":73}},{"id":"tn-192","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, when must a driver show evidence of financial responsibility, such as an insurance card?","o":["When charged with any traffic violation or involved in a crash","Only when buying a car","Only at license renewal","Never, if the driver has a clean record"],"h1":"Fault does not matter.","h2":"Tennessee's Financial Responsibility Law requires drivers to show proof of insurance or other financial responsibility when charged with any violation or involved in a crash, no matter who was at fault.","p":"Right. When charged with a violation or in a crash."},"es":{"q":"En Tennessee, ¿cuándo debe un conductor mostrar prueba de responsabilidad financiera, como una tarjeta de seguro?","o":["Cuando lo acusan de cualquier infracción o tiene un choque","Solo al comprar un carro","Solo al renovar la licencia","Nunca, si tiene buen historial"],"h1":"No importa de quién fue la culpa.","h2":"La Ley de Responsabilidad Financiera de Tennessee exige mostrar prueba de seguro u otra responsabilidad financiera cuando lo acusan de cualquier infracción o tiene un choque, sin importar quién tuvo la culpa.","p":"Correcto. Cuando lo acusan de una infracción o tiene un choque."},"ref":{"doc":"TN","page":88}},{"id":"tn-193","scope":"TN","cat":"licensing","sign":null,"c":3,"en":{"q":"In Tennessee, a driver lost consciousness behind the wheel because of a medical condition. How long must the driver stay episode-free before the license can be reinstated?","o":["2 weeks","30 days","2 years","At least 6 months"],"h1":"It is half a year.","h2":"In Tennessee, drivers who lose consciousness or control because of epilepsy, fainting, diabetes or another condition must stay free of episodes for at least six months before reinstatement.","p":"Right. At least six months."},"es":{"q":"En Tennessee, un conductor perdió el conocimiento al volante por una condición médica. ¿Cuánto tiempo debe pasar sin episodios antes de que le devuelvan la licencia?","o":["2 semanas","30 días","2 años","Por lo menos 6 meses"],"h1":"Es medio año.","h2":"En Tennessee, los conductores que pierden el conocimiento o el control por epilepsia, desmayos, diabetes u otra condición deben pasar por lo menos seis meses sin episodios antes de recuperar la licencia.","p":"Correcto. Por lo menos seis meses."},"ref":{"doc":"TN","page":88}},{"id":"tn-194","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, according to the manual, a large truck's blind spot behind it can stretch up to how far?","o":["10 feet","50 feet","200 feet","1 mile"],"h1":"It is far longer than a car length.","h2":"The Tennessee manual says a truck's blind spots include the area right in front, both sides, and up to 200 feet behind it.","p":"Right. Up to 200 feet behind."},"es":{"q":"En Tennessee, según el manual, ¿hasta qué distancia detrás de un camión grande puede llegar su punto ciego?","o":["10 pies","50 pies","200 pies","1 milla"],"h1":"Es mucho más que el largo de un carro.","h2":"El manual de Tennessee dice que los puntos ciegos de un camión incluyen justo enfrente, ambos lados y hasta 200 pies detrás.","p":"Correcto. Hasta 200 pies detrás."},"ref":{"doc":"TN","page":109}},{"id":"tn-195","scope":"TN","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Tennessee, according to the manual, a car at 55 mph can stop in about 240 feet. About how far does a truck at 55 mph need?","o":["450 feet or more","100 feet","240 feet, the same","2 miles"],"h1":"A heavy truck needs almost twice the distance.","h2":"The Tennessee manual says a car at 55 mph can stop in about 240 feet, but a truck at the same speed needs about 450 feet or more.","p":"Right. About 450 feet or more."},"es":{"q":"En Tennessee, según el manual, un carro a 55 mph puede detenerse en unos 240 pies. ¿Más o menos cuánto necesita un camión a 55 mph?","o":["450 pies o más","100 pies","240 pies, lo mismo","2 millas"],"h1":"Un camión pesado necesita casi el doble.","h2":"El manual de Tennessee dice que un carro a 55 mph puede detenerse en unos 240 pies, pero un camión a la misma velocidad necesita unos 450 pies o más.","p":"Correcto. Unos 450 pies o más."},"ref":{"doc":"TN","page":109}},{"id":"tn-196","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, according to the manual, who causes about two-thirds of car-motorcycle crashes?","o":["The motorcyclist, by speeding","Bad weather","Road defects","The car driver, by turning in front of the motorcycle"],"h1":"Many drivers say they never saw the motorcycle.","h2":"The Tennessee manual says about two-thirds of car-motorcycle crashes are caused by the car driver turning in front of the motorcycle.","p":"Right. The car driver turning in front of it."},"es":{"q":"En Tennessee, según el manual, ¿quién causa más o menos dos tercios de los choques entre carro y motocicleta?","o":["El motociclista, por ir rápido","El mal tiempo","Los defectos del camino","El conductor del carro, al dar vuelta frente a la motocicleta"],"h1":"Muchos conductores dicen que nunca vieron la motocicleta.","h2":"El manual de Tennessee dice que más o menos dos tercios de los choques entre carro y motocicleta los causa el conductor del carro al dar vuelta frente a la motocicleta.","p":"Correcto. El conductor del carro al dar vuelta frente a ella."},"ref":{"doc":"TN","page":107}},{"id":"tn-197","scope":"TN","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Tennessee, a bicycle has a red or orange pennant flag on a pole. What does this commonly tell drivers?","o":["The rider is in a race","The rider has impaired hearing","The bike is for sale","The rider is a police officer"],"h1":"The flag tells you something about the rider, not the bike.","h2":"The Tennessee manual says a red or orange pennant on a bicycle commonly means the rider has impaired hearing, so slow down.","p":"Right. The rider has impaired hearing."},"es":{"q":"En Tennessee, una bicicleta lleva un banderín rojo o naranja en un poste. ¿Qué les indica normalmente a los conductores?","o":["El ciclista está en una carrera","El ciclista tiene problemas de audición","La bicicleta está a la venta","El ciclista es policía"],"h1":"El banderín le dice algo sobre el ciclista, no sobre la bicicleta.","h2":"El manual de Tennessee dice que un banderín rojo o naranja en una bicicleta normalmente indica que el ciclista tiene problemas de audición, así que baje la velocidad.","p":"Correcto. El ciclista tiene problemas de audición."},"ref":{"doc":"TN","page":106}},{"id":"tn-198","scope":"TN","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Tennessee, you knowingly drive around a clearly posted flood barricade into a flooded road. What can happen?","o":["Nothing, if your car makes it through","A $10 parking ticket","You can be charged with reckless driving and made to pay for your rescue","Only a warning"],"h1":"Ignoring flood warnings is treated seriously.","h2":"In Tennessee, a driver who knowingly ignores clear flood warning signs or barricades and drives into a flooded road can be charged with reckless driving and have to pay rescue costs.","p":"Right. Reckless driving, plus rescue costs."},"es":{"q":"En Tennessee, usted rodea a propósito una barricada de inundación bien señalada y entra en un camino inundado. ¿Qué puede pasar?","o":["Nada, si su carro logra pasar","Una multa de estacionamiento de $10","Lo pueden acusar de manejo temerario y hacerle pagar su rescate","Solo una advertencia"],"h1":"Ignorar las advertencias de inundación se toma en serio.","h2":"En Tennessee, un conductor que ignora a propósito señales o barricadas claras de inundación y entra en un camino inundado puede ser acusado de manejo temerario y tener que pagar el costo del rescate.","p":"Correcto. Manejo temerario, más el costo del rescate."},"ref":{"doc":"TN","page":77}},{"id":"tn-199","scope":"TN","cat":"licensing","sign":null,"c":0,"en":{"q":"In Tennessee, your license shows Restriction Code 01. What does it mean?","o":["You must wear glasses or contact lenses when you drive","You may drive only in daylight","You may not drive on interstates","You need an automatic car"],"h1":"It is the restriction for drivers who passed the vision screening with help.","h2":"Restriction Code 01 on a Tennessee license means you must wear corrective lenses whenever you drive.","p":"Right. Glasses or contacts are required."},"es":{"q":"En Tennessee, su licencia muestra la Restricción Código 01. ¿Qué significa?","o":["Debe usar lentes o lentes de contacto cuando maneja","Solo puede manejar de día","No puede manejar en interestatales","Necesita un carro automático"],"h1":"Es la restricción para quienes pasaron el examen de la vista con ayuda.","h2":"La Restricción Código 01 en una licencia de Tennessee significa que debe usar lentes correctivos siempre que maneje.","p":"Correcto. Debe usar lentes o lentes de contacto."},"ref":{"doc":"TN","page":99}},{"id":"tn-200","scope":"TN","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Tennessee, during which season do deer-car crashes peak?","o":["Spring","Summer","Winter","Fall"],"h1":"It is the deer mating and hunting season.","h2":"The Tennessee manual says fall is the peak season for deer-car crashes because it is mating and hunting season, so deer roam more.","p":"Right. Fall is the peak season."},"es":{"q":"En Tennessee, ¿en qué temporada hay más choques de carros con venados?","o":["Primavera","Verano","Invierno","Otoño"],"h1":"Es la temporada de apareamiento y de caza de los venados.","h2":"El manual de Tennessee dice que el otoño es la temporada con más choques con venados, porque es temporada de apareamiento y de caza y los venados se mueven más.","p":"Correcto. El otoño es la temporada más alta."},"ref":{"doc":"TN","page":97}},{"id":"tx-001","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the youngest age to get a learner license?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a provisional license.","h2":"You can get a Texas learner license at 15, which lets you practice for a year before the provisional license at 16.","p":"Right. The Texas learner license starts at 15."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener una licencia de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia provisional.","h2":"Usted puede obtener la licencia de aprendiz en Texas a los 15 años, lo que le permite practicar un año antes de la licencia provisional a los 16.","p":"Correcto. La licencia de aprendiz en Texas empieza a los 15."},"zh":{"q":"在 Texas，最小几岁可以拿到学习驾照（learner license）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿临时驾照早一年。","h2":"你 15 岁就可以拿到 Texas 学习驾照，这样你可以练习一年，16 岁再拿临时驾照。","p":"对。Texas 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Texas, tuổi nhỏ nhất để có bằng lái tập (learner license) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái tạm thời.","h2":"Bạn có thể lấy bằng lái tập ở Texas khi 15 tuổi, để tập lái một năm trước khi lấy bằng lái tạm thời lúc 16 tuổi.","p":"Đúng. Ở Texas, bằng lái tập bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Texas, ano ang pinakabatang edad para makakuha ng learner license?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng provisional license.","h2":"Puwede kang makakuha ng Texas learner license sa edad na 15, para makapagsanay ka nang isang taon bago ang provisional license sa edad na 16.","p":"Tama. Nagsisimula ang Texas learner license sa edad na 15."},"ar":{"q":"في Texas، ما أصغر عمر للحصول على رخصة التعلّم (learner license)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو قبل سنة واحدة من العمر الذي تحصل فيه على الرخصة المؤقتة.","h2":"يمكنك الحصول على رخصة التعلّم في Texas في عمر 15 سنة، فتتدرّب سنة كاملة قبل الرخصة المؤقتة في عمر 16 سنة.","p":"صحيح. تبدأ رخصة التعلّم في Texas في عمر 15 سنة."},"ref":{"doc":"TX","page":1}},{"id":"tx-002","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how old must the licensed person beside a learner driver be?","o":["At least 16","At least 18","At least 25","At least 21"],"h1":"The helper must be an adult who can legally drink.","h2":"A Texas learner must drive with a licensed person who is at least 21 years old, so an experienced adult is guiding them.","p":"Right. The person beside you must be 21 or older."},"es":{"q":"En Texas, ¿qué edad debe tener la persona con licencia que va al lado de un conductor aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 25","Por lo menos 21"],"h1":"El acompañante debe ser un adulto que ya puede tomar alcohol legalmente.","h2":"Un aprendiz en Texas debe manejar con una persona con licencia de por lo menos 21 años, para que lo guíe un adulto con experiencia.","p":"Correcto. Su acompañante debe tener 21 años o más."},"zh":{"q":"在 Texas，坐在学习司机旁边的有驾照的人必须几岁？","o":["至少 16 岁","至少 18 岁","至少 25 岁","至少 21 岁"],"h1":"这个人必须是可以合法喝酒的成年人。","h2":"Texas 的学习司机必须和至少 21 岁、有驾照的人一起开车，这样有一个有经验的成年人在旁边指导。","p":"对。坐在你旁边的人必须 21 岁或以上。"},"vi":{"q":"Ở Texas, người có bằng lái ngồi cạnh người tập lái phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 25 tuổi","Ít nhất 21 tuổi"],"h1":"Người giúp phải là người lớn được phép uống rượu theo luật.","h2":"Người tập lái ở Texas phải lái cùng một người có bằng lái và ít nhất 21 tuổi, để có một người lớn có kinh nghiệm hướng dẫn.","p":"Đúng. Người ngồi cạnh bạn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Texas, ilang taon dapat ang may lisensyang tao na katabi ng learner driver?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 25","Hindi bababa sa 21"],"h1":"Dapat ay adulto ang katulong na legal nang makainom ng alak.","h2":"Ang learner sa Texas ay dapat magmaneho kasama ang may lisensyang tao na hindi bababa sa 21 taong gulang, para may adultong may karanasan na gumagabay.","p":"Tama. Ang katabi mo ay dapat 21 taong gulang o higit pa."},"ar":{"q":"في Texas، كم يجب أن يكون عمر الشخص المرخَّص الذي يجلس بجانب السائق المتعلّم؟","o":["16 سنة على الأقل","18 سنة على الأقل","25 سنة على الأقل","21 سنة على الأقل"],"h1":"يجب أن يكون المرافق شخصًا بالغًا يُسمح له قانونيًا بشرب الكحول.","h2":"يجب أن يقود المتعلّم في Texas مع شخص مرخَّص عمره 21 سنة على الأقل، حتى يرشده شخص بالغ صاحب خبرة.","p":"صحيح. الشخص الذي بجانبك يجب أن يكون عمره 21 سنة أو أكثر."},"ref":{"doc":"TX","page":1}},{"id":"tx-003","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, how much driving experience must the person supervising a learner have?","o":["At least one year","At least one month","At least five years","At least ten years"],"h1":"It is the shortest period that still means real experience.","h2":"The adult with a Texas learner must have at least one year of driving experience, so they know the road well enough to guide a beginner.","p":"Right. The supervisor needs at least one year of experience."},"es":{"q":"En Texas, ¿cuánta experiencia de manejo debe tener la persona que supervisa a un aprendiz?","o":["Por lo menos un año","Por lo menos un mes","Por lo menos cinco años","Por lo menos diez años"],"h1":"Es el periodo más corto que todavía significa experiencia real.","h2":"El adulto que acompaña a un aprendiz en Texas debe tener por lo menos un año de experiencia manejando, para conocer bien la vía y guiar a un principiante.","p":"Correcto. El supervisor necesita por lo menos un año de experiencia."},"zh":{"q":"在 Texas，监督学习司机的人必须有多少开车经验？","o":["至少一年","至少一个月","至少五年","至少十年"],"h1":"它是能算作真正经验的最短时间。","h2":"陪 Texas 学习司机的成年人必须有至少一年的开车经验，这样他足够了解道路，可以指导新手。","p":"对。监督人至少要有一年经验。"},"vi":{"q":"Ở Texas, người giám sát người tập lái phải có bao nhiêu kinh nghiệm lái xe?","o":["Ít nhất một năm","Ít nhất một tháng","Ít nhất năm năm","Ít nhất mười năm"],"h1":"Đó là thời gian ngắn nhất mà vẫn là kinh nghiệm thật.","h2":"Người lớn đi cùng người tập lái ở Texas phải có ít nhất một năm kinh nghiệm lái xe, để họ hiểu đường đủ rõ mà hướng dẫn người mới.","p":"Đúng. Người giám sát cần ít nhất một năm kinh nghiệm."},"tl":{"q":"Sa Texas, gaano karaming karanasan sa pagmamaneho ang dapat mayroon ang taong nagbabantay sa learner?","o":["Hindi bababa sa isang taon","Hindi bababa sa isang buwan","Hindi bababa sa limang taon","Hindi bababa sa sampung taon"],"h1":"Ito ang pinakamaikling panahon na tunay na karanasan pa rin.","h2":"Ang adultong kasama ng learner sa Texas ay dapat may hindi bababa sa isang taon na karanasan sa pagmamaneho, para alam niya ang daan at kaya niyang gabayan ang baguhan.","p":"Tama. Kailangan ng nagbabantay ng hindi bababa sa isang taon na karanasan."},"ar":{"q":"في Texas، كم سنة من خبرة القيادة يجب أن تكون عند الشخص الذي يشرف على المتعلّم؟","o":["سنة واحدة على الأقل","شهر واحد على الأقل","خمس سنوات على الأقل","عشر سنوات على الأقل"],"h1":"هي أقصر مدة تُعدّ خبرة حقيقية.","h2":"يجب أن يكون عند الشخص البالغ المرافق للمتعلّم في Texas سنة واحدة على الأقل من خبرة القيادة، حتى يعرف الطريق جيدًا ويرشد المبتدئ.","p":"صحيح. المشرف يحتاج إلى سنة واحدة على الأقل من الخبرة."},"ref":{"doc":"TX","page":1}},{"id":"tx-004","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, where must the supervising adult sit when a learner is driving?","o":["In any back seat","Anywhere in the vehicle","In the seat beside the driver","In the middle of the back seat"],"h1":"They must be able to reach and help right away.","h2":"The supervising adult must sit in the seat beside a Texas learner, so they can see the road and help quickly.","p":"Right. The supervisor sits beside the learner."},"es":{"q":"En Texas, ¿dónde debe sentarse el adulto supervisor cuando maneja un aprendiz?","o":["En cualquier asiento de atrás","En cualquier lugar del vehículo","En el asiento al lado del conductor","En el centro del asiento de atrás"],"h1":"Debe poder alcanzar y ayudar enseguida.","h2":"El adulto supervisor debe sentarse al lado del aprendiz en Texas, para ver la vía y ayudar rápido.","p":"Correcto. El supervisor se sienta al lado del aprendiz."},"zh":{"q":"在 Texas，学习司机开车时，监督的成年人必须坐在哪里？","o":["任何一个后座","车里任何地方","司机旁边的座位","后排中间的座位"],"h1":"他必须能马上伸手帮忙。","h2":"监督的成年人必须坐在 Texas 学习司机旁边的座位，这样他能看到路，也能很快帮忙。","p":"对。监督人坐在学习司机旁边。"},"vi":{"q":"Ở Texas, khi người tập lái đang lái, người lớn giám sát phải ngồi ở đâu?","o":["Ở bất kỳ ghế sau nào","Ở bất kỳ chỗ nào trong xe","Ở ghế bên cạnh tài xế","Ở giữa ghế sau"],"h1":"Họ phải có thể với tới và giúp ngay.","h2":"Người lớn giám sát phải ngồi ở ghế bên cạnh người tập lái ở Texas, để họ nhìn thấy đường và giúp nhanh.","p":"Đúng. Người giám sát ngồi bên cạnh người tập lái."},"tl":{"q":"Sa Texas, saan dapat umupo ang nagbabantay na adulto habang nagmamaneho ang learner?","o":["Sa kahit anong upuan sa likod","Kahit saan sa sasakyan","Sa upuang katabi ng driver","Sa gitna ng upuan sa likod"],"h1":"Dapat ay maabot niya at makatulong agad.","h2":"Ang nagbabantay na adulto ay dapat umupo sa upuang katabi ng learner sa Texas, para makita niya ang daan at makatulong agad.","p":"Tama. Katabi ng learner umuupo ang nagbabantay."},"ar":{"q":"في Texas، أين يجب أن يجلس الشخص البالغ المشرف عندما يقود المتعلّم؟","o":["في أي مقعد خلفي","في أي مكان في السيارة","في المقعد الذي بجانب السائق","في وسط المقعد الخلفي"],"h1":"يجب أن يستطيع الوصول والمساعدة فورًا.","h2":"يجب أن يجلس الشخص البالغ المشرف في المقعد الذي بجانب المتعلّم في Texas، حتى يرى الطريق ويساعد بسرعة.","p":"صحيح. المشرف يجلس بجانب المتعلّم."},"ref":{"doc":"TX","page":1}},{"id":"tx-005","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what must a teen finish before getting a learner license?","o":["A full year of supervised driving","The classroom part of driver education","A road test with an examiner","A first aid course"],"h1":"It happens in a classroom or a parent-taught course, before the wheel.","h2":"A Texas teen must finish the classroom part of an approved driver education course and pass the knowledge test before getting a learner license.","p":"Right. Finish the classroom part of driver education first."},"es":{"q":"En Texas, ¿qué debe terminar un adolescente antes de obtener la licencia de aprendiz?","o":["Un año completo de manejo supervisado","La parte de clases de la educación vial","Un examen de manejo con un examinador","Un curso de primeros auxilios"],"h1":"Se hace en un salón o en un curso enseñado por los padres, antes de manejar.","h2":"Un adolescente en Texas debe terminar la parte de clases de un curso aprobado de educación vial y aprobar el examen de conocimientos antes de obtener la licencia de aprendiz.","p":"Correcto. Primero se termina la parte de clases de educación vial."},"zh":{"q":"在 Texas，青少年拿学习驾照前必须完成什么？","o":["一整年有人监督的驾驶","驾驶教育的课堂部分","和考官一起的路考","急救课程"],"h1":"它在教室里或家长教的课程里完成，在摸方向盘之前。","h2":"Texas 青少年必须完成认可的驾驶教育课程的课堂部分，并通过笔试，才能拿学习驾照。","p":"对。先完成驾驶教育的课堂部分。"},"vi":{"q":"Ở Texas, thiếu niên phải hoàn thành gì trước khi lấy bằng lái tập?","o":["Một năm lái xe có người giám sát","Phần học trên lớp của khóa giáo dục lái xe","Bài thi lái xe với giám khảo","Một khóa sơ cứu"],"h1":"Nó diễn ra trong lớp học hoặc khóa do cha mẹ dạy, trước khi cầm vô lăng.","h2":"Thiếu niên ở Texas phải hoàn thành phần học trên lớp của một khóa giáo dục lái xe được chấp thuận và đậu bài thi kiến thức trước khi lấy bằng lái tập.","p":"Đúng. Hoàn thành phần học trên lớp của khóa giáo dục lái xe trước."},"tl":{"q":"Sa Texas, ano ang dapat tapusin ng isang teenager bago makakuha ng learner license?","o":["Isang buong taon ng pagmamaneho na may nagbabantay","Ang bahagi sa classroom ng driver education","Isang road test kasama ang examiner","Isang kurso sa first aid"],"h1":"Nangyayari ito sa classroom o sa kursong itinuturo ng magulang, bago humawak ng manibela.","h2":"Ang teenager sa Texas ay dapat tapusin ang bahagi sa classroom ng isang aprubadong driver education course at pumasa sa knowledge test bago makakuha ng learner license.","p":"Tama. Tapusin muna ang bahagi sa classroom ng driver education."},"ar":{"q":"في Texas، ماذا يجب أن يُكمل المراهق قبل الحصول على رخصة التعلّم؟","o":["سنة كاملة من القيادة تحت الإشراف","الجزء الصفّي من دورة تعليم القيادة","اختبار القيادة مع الفاحص","دورة إسعافات أولية"],"h1":"يكون في صفّ دراسي أو في دورة يعلّمها أحد الوالدين، قبل الجلوس خلف المقود.","h2":"يجب أن يُكمل المراهق في Texas الجزء الصفّي من دورة تعليم قيادة معتمدة وأن ينجح في اختبار المعرفة قبل الحصول على رخصة التعلّم.","p":"صحيح. أكمِل أولًا الجزء الصفّي من دورة تعليم القيادة."},"ref":{"doc":"TX","page":1}},{"id":"tx-006","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, how long must a teen hold a learner license before getting a provisional license?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"A Texas teen must hold the learner license for at least 6 months before applying for a provisional license.","p":"Right. Hold the learner license for at least 6 months."},"es":{"q":"En Texas, ¿cuánto tiempo debe tener un adolescente la licencia de aprendiz antes de obtener la licencia provisional?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"Un adolescente en Texas debe tener la licencia de aprendiz por lo menos 6 meses antes de solicitar la licencia provisional.","p":"Correcto. Debe tenerla por lo menos 6 meses."},"zh":{"q":"在 Texas，青少年拿临时驾照前，必须持有学习驾照多久？","o":["1 个月","3 个月","6 个月","2 年"],"h1":"它是半年。","h2":"Texas 青少年必须持有学习驾照至少 6 个月，才能申请临时驾照。","p":"对。持有学习驾照至少 6 个月。"},"vi":{"q":"Ở Texas, thiếu niên phải giữ bằng lái tập bao lâu trước khi lấy bằng lái tạm thời?","o":["1 tháng","3 tháng","6 tháng","2 năm"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Texas phải giữ bằng lái tập ít nhất 6 tháng trước khi nộp đơn xin bằng lái tạm thời.","p":"Đúng. Giữ bằng lái tập ít nhất 6 tháng."},"tl":{"q":"Sa Texas, gaano katagal dapat hawak ng teenager ang learner license bago makakuha ng provisional license?","o":["1 buwan","3 buwan","6 na buwan","2 taon"],"h1":"Kalahating taon ito.","h2":"Ang teenager sa Texas ay dapat hawak ang learner license nang hindi bababa sa 6 na buwan bago mag-apply ng provisional license.","p":"Tama. Hawakan ang learner license nang hindi bababa sa 6 na buwan."},"ar":{"q":"في Texas، كم مدة يجب أن يحمل المراهق رخصة التعلّم قبل الحصول على الرخصة المؤقتة؟","o":["شهر واحد","3 أشهر","6 أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"يجب أن يحمل المراهق في Texas رخصة التعلّم 6 أشهر على الأقل قبل أن يتقدّم بطلب الرخصة المؤقتة.","p":"صحيح. احمل رخصة التعلّم 6 أشهر على الأقل."},"ref":{"doc":"TX","page":2}},{"id":"tx-007","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what is the youngest age to get a provisional license?","o":["16 years old","15 years old","17 years old","18 years old"],"h1":"It comes one year after the learner license.","h2":"A Texas teen can get a provisional license at 16 after holding a learner license for at least 6 months.","p":"Right. The provisional license starts at 16."},"es":{"q":"En Texas, ¿cuál es la edad mínima para obtener la licencia provisional?","o":["16 años","15 años","17 años","18 años"],"h1":"Viene un año después de la licencia de aprendiz.","h2":"Un adolescente en Texas puede obtener la licencia provisional a los 16 años, después de tener la licencia de aprendiz por lo menos 6 meses.","p":"Correcto. La licencia provisional empieza a los 16."},"zh":{"q":"在 Texas，最小几岁可以拿到临时驾照（provisional license）？","o":["16 岁","15 岁","17 岁","18 岁"],"h1":"它在学习驾照之后一年。","h2":"Texas 青少年持有学习驾照至少 6 个月以后，16 岁就可以拿到临时驾照。","p":"对。临时驾照从 16 岁开始。"},"vi":{"q":"Ở Texas, tuổi nhỏ nhất để có bằng lái tạm thời (provisional license) là bao nhiêu?","o":["16 tuổi","15 tuổi","17 tuổi","18 tuổi"],"h1":"Nó đến một năm sau bằng lái tập.","h2":"Thiếu niên ở Texas có thể lấy bằng lái tạm thời lúc 16 tuổi, sau khi giữ bằng lái tập ít nhất 6 tháng.","p":"Đúng. Bằng lái tạm thời bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Texas, ano ang pinakabatang edad para makakuha ng provisional license?","o":["16 taong gulang","15 taong gulang","17 taong gulang","18 taong gulang"],"h1":"Dumarating ito isang taon pagkatapos ng learner license.","h2":"Ang teenager sa Texas ay puwedeng makakuha ng provisional license sa edad na 16, pagkatapos hawakan ang learner license nang hindi bababa sa 6 na buwan.","p":"Tama. Nagsisimula ang provisional license sa edad na 16."},"ar":{"q":"في Texas، ما أصغر عمر للحصول على الرخصة المؤقتة (provisional license)؟","o":["16 سنة","15 سنة","17 سنة","18 سنة"],"h1":"تأتي بعد سنة واحدة من رخصة التعلّم.","h2":"يمكن للمراهق في Texas أن يحصل على الرخصة المؤقتة في عمر 16 سنة بعد أن يحمل رخصة التعلّم 6 أشهر على الأقل.","p":"صحيح. تبدأ الرخصة المؤقتة في عمر 16 سنة."},"ref":{"doc":"TX","page":3}},{"id":"tx-008","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many hours of supervised driving must a teen log, including night driving?","o":["20 hours","30 hours","40 hours","50 hours"],"h1":"Ten of these hours are at night.","h2":"A Texas teen must log 30 hours of supervised driving, including 10 hours at night, before the provisional license.","p":"Right. Texas asks for 30 supervised hours."},"es":{"q":"En Texas, ¿cuántas horas de manejo supervisado debe registrar un adolescente, incluidas las de noche?","o":["20 horas","30 horas","40 horas","50 horas"],"h1":"Diez de estas horas son de noche.","h2":"Un adolescente en Texas debe registrar 30 horas de manejo supervisado, incluidas 10 horas de noche, antes de la licencia provisional.","p":"Correcto. Texas pide 30 horas supervisadas."},"zh":{"q":"在 Texas，青少年必须记录多少小时有人监督的驾驶（包括夜间驾驶）？","o":["20 小时","30 小时","40 小时","50 小时"],"h1":"其中十个小时是在晚上。","h2":"Texas 青少年在拿临时驾照前，必须记录 30 小时有人监督的驾驶，其中包括 10 小时夜间驾驶。","p":"对。Texas 要求 30 小时有人监督的驾驶。"},"vi":{"q":"Ở Texas, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát, kể cả lái ban đêm?","o":["20 giờ","30 giờ","40 giờ","50 giờ"],"h1":"Mười giờ trong số này là ban đêm.","h2":"Thiếu niên ở Texas phải ghi lại 30 giờ lái xe có người giám sát, trong đó có 10 giờ ban đêm, trước khi lấy bằng lái tạm thời.","p":"Đúng. Texas yêu cầu 30 giờ có người giám sát."},"tl":{"q":"Sa Texas, ilang oras ng pagmamaneho na may nagbabantay ang dapat itala ng teenager, kasama ang pagmamaneho sa gabi?","o":["20 oras","30 oras","40 oras","50 oras"],"h1":"Sampu sa mga oras na ito ay sa gabi.","h2":"Ang teenager sa Texas ay dapat magtala ng 30 oras ng pagmamaneho na may nagbabantay, kasama ang 10 oras sa gabi, bago ang provisional license.","p":"Tama. Humihingi ang Texas ng 30 oras na may nagbabantay."},"ar":{"q":"في Texas، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق، ومنها القيادة في الليل؟","o":["20 ساعة","30 ساعة","40 ساعة","50 ساعة"],"h1":"عشر ساعات منها في الليل.","h2":"يجب أن يسجّل المراهق في Texas 30 ساعة من القيادة تحت الإشراف، منها 10 ساعات في الليل، قبل الرخصة المؤقتة.","p":"صحيح. تطلب Texas 30 ساعة تحت الإشراف."},"ref":{"doc":"TX","page":null}},{"id":"tx-009","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how many of the supervised practice hours must be at night?","o":["2 hours","5 hours","15 hours","10 hours"],"h1":"It is one third of the 30 hours.","h2":"At least 10 of the 30 supervised hours in Texas must be at night, because driving in the dark is different and needs practice.","p":"Right. 10 of the hours must be at night."},"es":{"q":"En Texas, ¿cuántas de las horas de práctica supervisada deben ser de noche?","o":["2 horas","5 horas","15 horas","10 horas"],"h1":"Es la tercera parte de las 30 horas.","h2":"Por lo menos 10 de las 30 horas supervisadas en Texas deben ser de noche, porque manejar en la oscuridad es distinto y necesita práctica.","p":"Correcto. 10 de las horas deben ser de noche."},"zh":{"q":"在 Texas，有人监督的练习时间里，必须有多少小时是在晚上？","o":["2 小时","5 小时","15 小时","10 小时"],"h1":"它是 30 小时的三分之一。","h2":"在 Texas，30 小时有人监督的驾驶中至少 10 小时必须在晚上，因为天黑时开车不一样，需要练习。","p":"对。其中 10 小时必须在晚上。"},"vi":{"q":"Ở Texas, bao nhiêu giờ tập lái có người giám sát phải là ban đêm?","o":["2 giờ","5 giờ","15 giờ","10 giờ"],"h1":"Đó là một phần ba của 30 giờ.","h2":"Ở Texas, ít nhất 10 trong 30 giờ có người giám sát phải là ban đêm, vì lái xe trong bóng tối khác và cần tập.","p":"Đúng. 10 giờ phải là ban đêm."},"tl":{"q":"Sa Texas, ilan sa mga oras ng pagsasanay na may nagbabantay ang dapat sa gabi?","o":["2 oras","5 oras","15 oras","10 oras"],"h1":"Isang katlo ito ng 30 oras.","h2":"Hindi bababa sa 10 sa 30 oras na may nagbabantay sa Texas ang dapat sa gabi, dahil iba ang pagmamaneho sa dilim at kailangan itong sanayin.","p":"Tama. 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Texas، كم ساعة من ساعات التدريب تحت الإشراف يجب أن تكون في الليل؟","o":["ساعتان","5 ساعات","15 ساعة","10 ساعات"],"h1":"هي ثلث الثلاثين ساعة.","h2":"يجب أن تكون 10 ساعات على الأقل من الثلاثين ساعة تحت الإشراف في Texas في الليل، لأن القيادة في الظلام مختلفة وتحتاج إلى تدريب.","p":"صحيح. 10 ساعات منها يجب أن تكون في الليل."},"ref":{"doc":"TX","page":null}},{"id":"tx-010","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what video course must a teen finish within 90 days before the road test?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Its name includes the word Impact.","h2":"A Texas teen must complete the Impact Texas Teen Drivers course within 90 days before the driving test.","p":"Right. The course is Impact Texas Teen Drivers."},"es":{"q":"En Texas, ¿qué curso en video debe terminar un adolescente dentro de los 90 días antes del examen de manejo?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Su nombre incluye la palabra Impact.","h2":"Un adolescente en Texas debe completar el curso Impact Texas Teen Drivers dentro de los 90 días antes del examen de manejo.","p":"Correcto. El curso es Impact Texas Teen Drivers."},"zh":{"q":"在 Texas，青少年必须在路考前 90 天内完成哪个视频课程？","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"它的名字里有 Impact 这个词。","h2":"Texas 青少年必须在路考前 90 天内完成 Impact Texas Teen Drivers 课程。","p":"对。这个课程是 Impact Texas Teen Drivers。"},"vi":{"q":"Ở Texas, thiếu niên phải hoàn thành khóa học video nào trong vòng 90 ngày trước bài thi lái xe?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"Tên của nó có chữ Impact.","h2":"Thiếu niên ở Texas phải hoàn thành khóa Impact Texas Teen Drivers trong vòng 90 ngày trước bài thi lái xe.","p":"Đúng. Khóa học là Impact Texas Teen Drivers."},"tl":{"q":"Sa Texas, anong video course ang dapat tapusin ng teenager sa loob ng 90 araw bago ang road test?","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"May salitang Impact sa pangalan nito.","h2":"Ang teenager sa Texas ay dapat tapusin ang Impact Texas Teen Drivers course sa loob ng 90 araw bago ang driving test.","p":"Tama. Ang course ay Impact Texas Teen Drivers."},"ar":{"q":"في Texas، أي دورة فيديو يجب أن يُكملها المراهق خلال 90 يومًا قبل اختبار القيادة؟","o":["Texas Safe Teens","Drive Smart Texas","Impact Texas Teen Drivers","Texas Road Ready"],"h1":"اسمها فيه كلمة Impact.","h2":"يجب أن يُكمل المراهق في Texas دورة Impact Texas Teen Drivers خلال 90 يومًا قبل اختبار القيادة.","p":"صحيح. الدورة هي Impact Texas Teen Drivers."},"ref":{"doc":"TX","page":null}},{"id":"tx-011","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver under 18 with a provisional license may not drive during which hours?","o":["Midnight to 5 a.m.","10 p.m. to 6 a.m.","9 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The limit starts when a new day begins.","h2":"A Texas driver under 18 with a provisional license may not drive from midnight to 5 a.m., except for work, a school activity or a medical emergency.","p":"Right. No driving from midnight to 5 a.m."},"es":{"q":"En Texas, un conductor menor de 18 con licencia provisional no puede manejar en ¿qué horario?","o":["De medianoche a 5 a.m.","De 10 p.m. a 6 a.m.","De 9 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El límite empieza cuando comienza un nuevo día.","h2":"Un conductor menor de 18 con licencia provisional en Texas no puede manejar de medianoche a 5 a.m., salvo por trabajo, una actividad escolar o una emergencia médica.","p":"Correcto. No se maneja de medianoche a 5 a.m."},"zh":{"q":"在 Texas，持有临时驾照、未满 18 岁的司机在哪个时段不可以开车？","o":["半夜 12 点到早上 5 点","晚上 10 点到早上 6 点","晚上 9 点到早上 5 点","晚上 11 点到早上 4 点"],"h1":"这个限制从新的一天开始的时候开始。","h2":"Texas 持有临时驾照、未满 18 岁的司机，从半夜 12 点到早上 5 点不可以开车，除非是为了工作、学校活动或医疗紧急情况。","p":"对。半夜 12 点到早上 5 点不能开车。"},"vi":{"q":"Ở Texas, tài xế dưới 18 tuổi có bằng lái tạm thời không được lái xe trong giờ nào?","o":["Nửa đêm đến 5 giờ sáng","10 giờ tối đến 6 giờ sáng","9 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Giới hạn bắt đầu khi một ngày mới bắt đầu.","h2":"Tài xế dưới 18 tuổi có bằng lái tạm thời ở Texas không được lái xe từ nửa đêm đến 5 giờ sáng, trừ khi đi làm, đi sinh hoạt của trường hoặc có cấp cứu y tế.","p":"Đúng. Không lái xe từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Texas, sa anong mga oras hindi puwedeng magmaneho ang driver na wala pang 18 na may provisional license?","o":["Hatinggabi hanggang 5 a.m.","10 p.m. hanggang 6 a.m.","9 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Nagsisimula ang limitasyon kapag nagsimula ang bagong araw.","h2":"Ang driver sa Texas na wala pang 18 na may provisional license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung para sa trabaho, aktibidad sa paaralan o medical emergency.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Texas، في أي ساعات لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة أن يقود؟","o":["من منتصف الليل إلى 5 صباحًا","من 10 مساءً إلى 6 صباحًا","من 9 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"يبدأ المنع عندما يبدأ يوم جديد.","h2":"لا يجوز للسائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة أن يقود من منتصف الليل إلى 5 صباحًا، إلا للعمل أو لنشاط مدرسي أو لحالة طبية طارئة.","p":"صحيح. لا قيادة من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"TX","page":3}},{"id":"tx-012","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a 16-year-old with a provisional license wants to drive at 1 a.m. Which reason is allowed?","o":["Going to a party","Getting fast food","Visiting a friend","Driving home from work"],"h1":"Only work, school activities and medical emergencies count.","h2":"A Texas provisional driver under 18 may drive between midnight and 5 a.m. only for work, a school-related activity or a medical emergency, so driving home from work is allowed.","p":"Right. Driving for work is one of the allowed reasons."},"es":{"q":"En Texas, un joven de 16 años con licencia provisional quiere manejar a la 1 a.m. ¿Qué motivo está permitido?","o":["Ir a una fiesta","Comprar comida rápida","Visitar a un amigo","Regresar a casa del trabajo"],"h1":"Solo cuentan el trabajo, las actividades escolares y las emergencias médicas.","h2":"Un conductor provisional menor de 18 en Texas puede manejar entre medianoche y 5 a.m. solo por trabajo, una actividad escolar o una emergencia médica, así que regresar del trabajo está permitido.","p":"Correcto. Manejar por trabajo es uno de los motivos permitidos."},"zh":{"q":"在 Texas，一个持有临时驾照的 16 岁青少年想在凌晨 1 点开车。哪个理由是允许的？","o":["去参加派对","去买快餐","去看朋友","下班开车回家"],"h1":"只有工作、学校活动和医疗紧急情况才算。","h2":"Texas 未满 18 岁的临时驾照司机，在半夜 12 点到早上 5 点之间，只能为了工作、学校相关活动或医疗紧急情况开车，所以下班开车回家是允许的。","p":"对。为了工作开车是允许的理由之一。"},"vi":{"q":"Ở Texas, một thiếu niên 16 tuổi có bằng lái tạm thời muốn lái xe lúc 1 giờ sáng. Lý do nào được phép?","o":["Đi dự tiệc","Đi mua đồ ăn nhanh","Đi thăm bạn","Lái xe về nhà sau giờ làm"],"h1":"Chỉ tính công việc, sinh hoạt của trường và cấp cứu y tế.","h2":"Tài xế có bằng lái tạm thời dưới 18 tuổi ở Texas chỉ được lái từ nửa đêm đến 5 giờ sáng vì công việc, sinh hoạt liên quan đến trường hoặc cấp cứu y tế, nên lái xe về nhà sau giờ làm là được phép.","p":"Đúng. Lái xe vì công việc là một lý do được phép."},"tl":{"q":"Sa Texas, gustong magmaneho ng isang 16 taong gulang na may provisional license nang 1 a.m. Aling dahilan ang pinapayagan?","o":["Pagpunta sa party","Pagbili ng fast food","Pagbisita sa kaibigan","Pag-uwi galing sa trabaho"],"h1":"Trabaho, aktibidad sa paaralan at medical emergency lang ang binibilang.","h2":"Ang provisional driver sa Texas na wala pang 18 ay puwedeng magmaneho mula hatinggabi hanggang 5 a.m. para lang sa trabaho, aktibidad na may kinalaman sa paaralan o medical emergency, kaya pinapayagan ang pag-uwi galing sa trabaho.","p":"Tama. Ang pagmamaneho para sa trabaho ay isa sa mga pinapayagang dahilan."},"ar":{"q":"في Texas، مراهق عمره 16 سنة يحمل رخصة مؤقتة يريد أن يقود في الساعة 1 صباحًا. أي سبب مسموح به؟","o":["الذهاب إلى حفلة","شراء وجبة سريعة","زيارة صديق","العودة إلى البيت من العمل"],"h1":"فقط العمل والأنشطة المدرسية والحالات الطبية الطارئة تُحسب.","h2":"السائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة يجوز له أن يقود بين منتصف الليل و5 صباحًا فقط للعمل أو لنشاط مدرسي أو لحالة طبية طارئة، لذلك العودة إلى البيت من العمل مسموح بها.","p":"صحيح. القيادة من أجل العمل سبب من الأسباب المسموح بها."},"ref":{"doc":"TX","page":3}},{"id":"tx-013","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many passengers under 21 who are not family may a provisional driver under 18 carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number above zero.","h2":"A Texas provisional driver under 18 may carry no more than one passenger under 21 who is not a family member, because young passengers distract new drivers.","p":"Right. Only one young passenger who is not family."},"es":{"q":"En Texas, ¿cuántos pasajeros menores de 21 que no son familiares puede llevar un conductor provisional menor de 18?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"Un conductor provisional menor de 18 en Texas puede llevar como máximo un pasajero menor de 21 que no sea familiar, porque los pasajeros jóvenes distraen a los conductores nuevos.","p":"Correcto. Solo un pasajero joven que no sea familiar."},"zh":{"q":"在 Texas，未满 18 岁的临时驾照司机可以载几个不是家人、未满 21 岁的乘客？","o":["一个都不行","一个","两个","三个"],"h1":"它是大于零的最小数字。","h2":"Texas 未满 18 岁的临时驾照司机，最多只能载一个不是家人、未满 21 岁的乘客，因为年轻乘客会让新司机分心。","p":"对。只能载一个不是家人的年轻乘客。"},"vi":{"q":"Ở Texas, tài xế có bằng lái tạm thời dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi không phải người trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Tài xế có bằng lái tạm thời dưới 18 tuổi ở Texas được chở không quá một hành khách dưới 21 tuổi không phải người trong gia đình, vì hành khách trẻ làm tài xế mới mất tập trung.","p":"Đúng. Chỉ một hành khách trẻ không phải người trong gia đình."},"tl":{"q":"Sa Texas, ilang pasaherong wala pang 21 na hindi kapamilya ang puwedeng isakay ng provisional driver na wala pang 18?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na numerong higit sa zero.","h2":"Ang provisional driver sa Texas na wala pang 18 ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21 na hindi kapamilya, dahil nakaka-distract sa bagong driver ang mga batang pasahero.","p":"Tama. Isang batang pasahero lang na hindi kapamilya."},"ar":{"q":"في Texas، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يجوز أن يحمله سائق برخصة مؤقتة عمره أقل من 18 سنة؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من صفر.","h2":"السائق في Texas الذي عمره أقل من 18 سنة ويحمل رخصة مؤقتة لا يجوز أن يحمل أكثر من راكب واحد عمره أقل من 21 سنة وليس من العائلة، لأن الركاب الصغار يشتّتون انتباه السائقين الجدد.","p":"صحيح. راكب صغير واحد فقط ليس من العائلة."},"ref":{"doc":"TX","page":3}},{"id":"tx-014","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, may a driver under 18 talk on a phone using a hands-free device while driving?","o":["Yes, hands-free is always allowed","Yes, but only on the highway","No, only in an emergency","Yes, if the call is short"],"h1":"Teen drivers have a stricter rule than adults.","h2":"A Texas driver under 18 may not use any wireless device while driving, hands-free included, except to call for help in an emergency.","p":"Right. Under 18, no phone at all except in an emergency."},"es":{"q":"En Texas, ¿puede un conductor menor de 18 hablar por teléfono con manos libres mientras maneja?","o":["Sí, manos libres siempre está permitido","Sí, pero solo en la autopista","No, solo en una emergencia","Sí, si la llamada es corta"],"h1":"Los conductores adolescentes tienen una regla más estricta que los adultos.","h2":"Un conductor menor de 18 en Texas no puede usar ningún aparato inalámbrico mientras maneja, ni siquiera con manos libres, salvo para pedir ayuda en una emergencia.","p":"Correcto. Menor de 18, nada de teléfono salvo en emergencia."},"zh":{"q":"在 Texas，未满 18 岁的司机开车时可以用免提设备打电话吗？","o":["可以，免提总是允许的","可以，但只能在高速公路上","不可以，只有紧急情况可以","可以，如果电话很短"],"h1":"青少年司机的规定比成年人更严格。","h2":"Texas 未满 18 岁的司机开车时不可以用任何无线设备，包括免提，只有在紧急情况下打电话求助才可以。","p":"对。未满 18 岁，除了紧急情况，完全不能用手机。"},"vi":{"q":"Ở Texas, tài xế dưới 18 tuổi có được nói điện thoại bằng thiết bị rảnh tay khi lái xe không?","o":["Có, rảnh tay luôn được phép","Có, nhưng chỉ trên xa lộ","Không, chỉ khi khẩn cấp","Có, nếu cuộc gọi ngắn"],"h1":"Tài xế thiếu niên có luật nghiêm hơn người lớn.","h2":"Tài xế dưới 18 tuổi ở Texas không được dùng bất kỳ thiết bị không dây nào khi lái xe, kể cả rảnh tay, trừ khi gọi giúp đỡ lúc khẩn cấp.","p":"Đúng. Dưới 18 tuổi, không dùng điện thoại gì cả trừ khi khẩn cấp."},"tl":{"q":"Sa Texas, puwede bang makipag-usap sa telepono gamit ang hands-free device ang driver na wala pang 18 habang nagmamaneho?","o":["Oo, laging pinapayagan ang hands-free","Oo, pero sa highway lang","Hindi, sa emergency lang","Oo, kung maikli ang tawag"],"h1":"Mas mahigpit ang patakaran para sa teen driver kaysa sa adulto.","h2":"Ang driver sa Texas na wala pang 18 ay hindi puwedeng gumamit ng kahit anong wireless device habang nagmamaneho, kasama ang hands-free, maliban sa pagtawag para humingi ng tulong sa emergency.","p":"Tama. Kung wala pang 18, bawal ang telepono maliban sa emergency."},"ar":{"q":"في Texas، هل يجوز للسائق الذي عمره أقل من 18 سنة أن يتكلّم في الهاتف بجهاز من غير استخدام اليدين (hands-free) أثناء القيادة؟","o":["نعم، استخدام الهاتف من غير اليدين مسموح دائمًا","نعم، لكن على الطريق السريع فقط","لا، إلا في حالة طارئة","نعم، إذا كانت المكالمة قصيرة"],"h1":"للسائقين المراهقين قاعدة أشدّ من الكبار.","h2":"لا يجوز للسائق في Texas الذي عمره أقل من 18 سنة أن يستخدم أي جهاز لاسلكي أثناء القيادة، حتى من غير اليدين، إلا للاتصال طلبًا للمساعدة في حالة طارئة.","p":"صحيح. تحت 18 سنة، لا هاتف أبدًا إلا في حالة طارئة."},"ref":{"doc":"TX","page":3}},{"id":"tx-015","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, is it legal for an adult driver to text while driving?","o":["No, texting while driving is illegal statewide","Yes, outside of school zones","Yes, below 30 mph","Yes, on rural roads only"],"h1":"The rule covers every driver, everywhere in Texas.","h2":"Texas law makes it illegal for every driver to read, write or send text messages while driving, anywhere in the state.","p":"Right. Texting while driving is illegal in all of Texas."},"es":{"q":"En Texas, ¿es legal que un conductor adulto envíe mensajes de texto mientras maneja?","o":["No, es ilegal en todo el estado","Sí, fuera de las zonas escolares","Sí, a menos de 30 mph","Sí, solo en caminos rurales"],"h1":"La regla es para todos los conductores, en todo Texas.","h2":"La ley de Texas prohíbe a todos los conductores leer, escribir o enviar mensajes de texto mientras manejan, en cualquier parte del estado.","p":"Correcto. Enviar textos al manejar es ilegal en todo Texas."},"zh":{"q":"在 Texas，成年司机开车时发短信合法吗？","o":["不合法，开车发短信在全州都违法","合法，在学校区以外","合法，车速低于 30 mph 时","合法，只在乡村道路上"],"h1":"这条规定适用于每个司机，在 Texas 的每个地方。","h2":"Texas 法律规定，每个司机开车时读、写或发短信都是违法的，在全州任何地方都一样。","p":"对。在整个 Texas，开车发短信都是违法的。"},"vi":{"q":"Ở Texas, tài xế người lớn nhắn tin khi lái xe có hợp pháp không?","o":["Không, nhắn tin khi lái xe là bất hợp pháp trên toàn tiểu bang","Có, bên ngoài khu vực trường học","Có, khi chạy dưới 30 mph","Có, chỉ trên đường nông thôn"],"h1":"Luật này áp dụng cho mọi tài xế, ở mọi nơi trong Texas.","h2":"Luật Texas cấm mọi tài xế đọc, viết hoặc gửi tin nhắn khi lái xe, ở bất kỳ đâu trong tiểu bang.","p":"Đúng. Nhắn tin khi lái xe là bất hợp pháp ở khắp Texas."},"tl":{"q":"Sa Texas, legal ba para sa adultong driver ang mag-text habang nagmamaneho?","o":["Hindi, ilegal ang pag-text habang nagmamaneho sa buong estado","Oo, sa labas ng school zone","Oo, kapag mas mababa sa 30 mph","Oo, sa mga daan sa probinsya lang"],"h1":"Para sa bawat driver ang patakaran, saanman sa Texas.","h2":"Ayon sa batas ng Texas, ilegal para sa bawat driver ang magbasa, magsulat o magpadala ng text message habang nagmamaneho, kahit saan sa estado.","p":"Tama. Ilegal ang pag-text habang nagmamaneho sa buong Texas."},"ar":{"q":"في Texas، هل يجوز قانونيًا للسائق البالغ أن يكتب رسائل نصية أثناء القيادة؟","o":["لا، الرسائل النصية أثناء القيادة ممنوعة في كل الولاية","نعم، خارج مناطق المدارس","نعم، تحت 30 mph","نعم، على الطرق الريفية فقط"],"h1":"القاعدة تشمل كل سائق، في كل مكان في Texas.","h2":"قانون Texas يمنع كل سائق من قراءة الرسائل النصية أو كتابتها أو إرسالها أثناء القيادة، في أي مكان في الولاية.","p":"صحيح. الرسائل النصية أثناء القيادة ممنوعة في كل Texas."},"ref":{"doc":"TX","page":54}},{"id":"tx-016","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, what is the rule for hand-held phones in an active school zone?","o":["They are allowed below 20 mph","Drivers may not use them","They are allowed for short calls","Only teens are banned"],"h1":"Children are crossing nearby.","h2":"Texas drivers may not use a hand-held phone in an active school zone, so their eyes and hands stay ready for children; hands-free use and emergency calls are exceptions.","p":"Right. No hand-held phone in an active school zone."},"es":{"q":"En Texas, ¿cuál es la regla para los teléfonos en la mano en una zona escolar activa?","o":["Se permiten a menos de 20 mph","Los conductores no pueden usarlos","Se permiten para llamadas cortas","Solo están prohibidos para adolescentes"],"h1":"Hay niños cruzando cerca.","h2":"En Texas los conductores no pueden usar un teléfono en la mano en una zona escolar activa, para tener la vista y las manos listas por los niños; el uso con manos libres y las llamadas de emergencia son excepciones.","p":"Correcto. No se usa el teléfono en la mano en una zona escolar activa."},"zh":{"q":"在 Texas，在正在生效的学校区（active school zone）里，手持手机有什么规定？","o":["车速低于 20 mph 时可以用","司机不可以用","短电话可以用","只禁止青少年用"],"h1":"附近有孩子在过马路。","h2":"Texas 司机在正在生效的学校区里不可以用手持手机，这样眼睛和手都能随时注意孩子；免提和紧急电话是例外。","p":"对。在正在生效的学校区里不能用手持手机。"},"vi":{"q":"Ở Texas, luật về điện thoại cầm tay trong khu vực trường học đang hoạt động (active school zone) là gì?","o":["Được phép khi chạy dưới 20 mph","Tài xế không được dùng","Được phép cho cuộc gọi ngắn","Chỉ cấm thiếu niên"],"h1":"Trẻ em đang băng qua đường gần đó.","h2":"Tài xế ở Texas không được dùng điện thoại cầm tay trong khu vực trường học đang hoạt động, để mắt và tay luôn sẵn sàng cho trẻ em; dùng rảnh tay và gọi khẩn cấp là ngoại lệ.","p":"Đúng. Không dùng điện thoại cầm tay trong khu vực trường học đang hoạt động."},"tl":{"q":"Sa Texas, ano ang patakaran sa hand-held na telepono sa active school zone?","o":["Pinapayagan kapag mas mababa sa 20 mph","Hindi puwedeng gamitin ng mga driver","Pinapayagan para sa maikling tawag","Teenager lang ang bawal"],"h1":"May mga batang tumatawid sa malapit.","h2":"Ang mga driver sa Texas ay hindi puwedeng gumamit ng hand-held na telepono sa active school zone, para handa ang mata at kamay para sa mga bata; eksepsiyon ang hands-free at mga tawag sa emergency.","p":"Tama. Bawal ang hand-held na telepono sa active school zone."},"ar":{"q":"في Texas، ما القاعدة بشأن الهاتف المحمول باليد في منطقة مدرسة نشطة (active school zone)؟","o":["مسموح تحت 20 mph","لا يجوز للسائقين استخدامه","مسموح للمكالمات القصيرة","الممنوع هم المراهقون فقط"],"h1":"هناك أطفال يعبرون الطريق قريبًا منك.","h2":"لا يجوز للسائقين في Texas استخدام الهاتف المحمول باليد في منطقة مدرسة نشطة، حتى تبقى العينان واليدان جاهزة من أجل الأطفال؛ والاستخدام من غير اليدين ومكالمات الطوارئ مستثناة.","p":"صحيح. لا هاتف محمول باليد في منطقة مدرسة نشطة."},"ref":{"doc":"TX","page":31}},{"id":"tx-017","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what score do you need to pass the driver license knowledge test?","o":["60 percent","65 percent","70 percent","80 percent"],"h1":"It is lower than in many other states.","h2":"Texas requires a score of 70 percent or better on the knowledge test to qualify for a license.","p":"Right. You need 70 percent to pass in Texas."},"es":{"q":"En Texas, ¿qué puntaje necesita para aprobar el examen de conocimientos para la licencia?","o":["60 por ciento","65 por ciento","70 por ciento","80 por ciento"],"h1":"Es más bajo que en muchos otros estados.","h2":"Texas exige 70 por ciento o más en el examen de conocimientos para obtener la licencia.","p":"Correcto. Necesita 70 por ciento para aprobar en Texas."},"zh":{"q":"在 Texas，驾照笔试要多少分才能通过？","o":["60%","65%","70%","80%"],"h1":"它比很多其他州低。","h2":"Texas 要求笔试得到 70% 或以上，才符合拿驾照的条件。","p":"对。在 Texas 要 70% 才能通过。"},"vi":{"q":"Ở Texas, bạn cần bao nhiêu điểm để đậu bài thi kiến thức lấy bằng lái?","o":["60 phần trăm","65 phần trăm","70 phần trăm","80 phần trăm"],"h1":"Nó thấp hơn so với nhiều tiểu bang khác.","h2":"Texas yêu cầu đạt 70 phần trăm trở lên trong bài thi kiến thức để đủ điều kiện lấy bằng lái.","p":"Đúng. Bạn cần 70 phần trăm để đậu ở Texas."},"tl":{"q":"Sa Texas, anong score ang kailangan mo para pumasa sa driver license knowledge test?","o":["60 porsiyento","65 porsiyento","70 porsiyento","80 porsiyento"],"h1":"Mas mababa ito kaysa sa maraming ibang estado.","h2":"Humihingi ang Texas ng score na 70 porsiyento o higit pa sa knowledge test para makakuha ng lisensya.","p":"Tama. Kailangan mo ng 70 porsiyento para pumasa sa Texas."},"ar":{"q":"في Texas، ما الدرجة التي تحتاجها للنجاح في اختبار المعرفة لرخصة القيادة؟","o":["60 في المئة","65 في المئة","70 في المئة","80 في المئة"],"h1":"هي أقل مما في ولايات أخرى كثيرة.","h2":"تطلب Texas درجة 70 في المئة أو أكثر في اختبار المعرفة لتكون مؤهّلًا للرخصة.","p":"صحيح. تحتاج إلى 70 في المئة للنجاح في Texas."},"ref":{"doc":"TX","page":7}},{"id":"tx-018","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, in which languages does DPS give the driver license knowledge test?","o":["English only","English, Spanish and French","Any language you ask for","English and Spanish"],"h1":"Texas offers exactly two languages.","h2":"Texas DPS gives the regular driver license knowledge test in English or Spanish only.","p":"Right. The Texas test is in English or Spanish."},"es":{"q":"En Texas, ¿en qué idiomas da el DPS el examen de conocimientos para la licencia?","o":["Solo en inglés","En inglés, español y francés","En cualquier idioma que pida","En inglés y español"],"h1":"Texas ofrece exactamente dos idiomas.","h2":"El DPS de Texas da el examen de conocimientos para la licencia de manejo normal solo en inglés o en español.","p":"Correcto. El examen de Texas es en inglés o en español."},"zh":{"q":"在 Texas，DPS 用哪些语言进行驾照笔试？","o":["只有英语","英语、西班牙语和法语","你要求的任何语言","英语和西班牙语"],"h1":"Texas 刚好提供两种语言。","h2":"Texas DPS 的普通驾照笔试只用英语或西班牙语。","p":"对。Texas 的考试用英语或西班牙语。"},"vi":{"q":"Ở Texas, DPS cho thi kiến thức lấy bằng lái bằng những ngôn ngữ nào?","o":["Chỉ tiếng Anh","Tiếng Anh, tiếng Tây Ban Nha và tiếng Pháp","Bất kỳ ngôn ngữ nào bạn yêu cầu","Tiếng Anh và tiếng Tây Ban Nha"],"h1":"Texas có đúng hai ngôn ngữ.","h2":"Texas DPS cho thi kiến thức lấy bằng lái thông thường chỉ bằng tiếng Anh hoặc tiếng Tây Ban Nha.","p":"Đúng. Bài thi ở Texas bằng tiếng Anh hoặc tiếng Tây Ban Nha."},"tl":{"q":"Sa Texas, sa anong mga wika ibinibigay ng DPS ang driver license knowledge test?","o":["Ingles lang","Ingles, Espanyol at Pranses","Kahit anong wika na hilingin mo","Ingles at Espanyol"],"h1":"Eksaktong dalawang wika ang inaalok ng Texas.","h2":"Ibinibigay ng Texas DPS ang regular na driver license knowledge test sa Ingles o Espanyol lang.","p":"Tama. Ang test sa Texas ay nasa Ingles o Espanyol."},"ar":{"q":"في Texas، بأي لغات يقدّم DPS اختبار المعرفة لرخصة القيادة؟","o":["الإنجليزية فقط","الإنجليزية والإسبانية والفرنسية","أي لغة تطلبها","الإنجليزية والإسبانية"],"h1":"تقدّم Texas لغتين بالضبط.","h2":"يقدّم Texas DPS اختبار المعرفة لرخصة القيادة العادية بالإنجليزية أو بالإسبانية فقط.","p":"صحيح. اختبار Texas بالإنجليزية أو بالإسبانية."},"ref":{"doc":"TX","page":null}},{"id":"tx-019","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, you are on a road with a 60 mph limit and you cannot leave the lane next to a stopped police car with flashing lights. How fast may you pass?","o":["40 mph or slower","50 mph or slower","55 mph or slower","60 mph or slower"],"h1":"Take 20 away from the speed limit.","h2":"Texas law says that if you cannot move out of the lane next to a stopped emergency vehicle, you must slow to 20 mph below the limit, so 40 mph on a 60 mph road.","p":"Right. Slow to 20 below the limit, so 40 mph."},"es":{"q":"En Texas, va por una vía con límite de 60 mph y no puede salir del carril junto a una patrulla detenida con luces intermitentes. ¿A qué velocidad puede pasar?","o":["A 40 mph o menos","A 50 mph o menos","A 55 mph o menos","A 60 mph o menos"],"h1":"Réstele 20 al límite de velocidad.","h2":"La ley de Texas dice que si no puede salir del carril junto a un vehículo de emergencia detenido, debe bajar a 20 mph menos que el límite, o sea 40 mph en una vía de 60 mph.","p":"Correcto. Baje a 20 menos que el límite: 40 mph."},"zh":{"q":"在 Texas，你在限速 60 mph 的路上，无法离开紧挨着一辆闪灯停着的警车的车道。你可以用多快的速度经过？","o":["40 mph 或更慢","50 mph 或更慢","55 mph 或更慢","60 mph 或更慢"],"h1":"用限速减去 20。","h2":"Texas 法律规定，如果你无法离开紧挨着停着的紧急车辆的车道，你必须减速到比限速低 20 mph，所以在 60 mph 的路上是 40 mph。","p":"对。减速到比限速低 20，所以是 40 mph。"},"vi":{"q":"Ở Texas, bạn đang đi trên đường có giới hạn 60 mph và không thể rời làn xe kế bên một xe cảnh sát đang đỗ có đèn nhấp nháy. Bạn được chạy qua với tốc độ bao nhiêu?","o":["40 mph hoặc chậm hơn","50 mph hoặc chậm hơn","55 mph hoặc chậm hơn","60 mph hoặc chậm hơn"],"h1":"Lấy giới hạn tốc độ trừ đi 20.","h2":"Luật Texas nói nếu bạn không thể rời làn xe kế bên một xe khẩn cấp đang đỗ, bạn phải chạy chậm hơn giới hạn 20 mph, tức là 40 mph trên đường 60 mph.","p":"Đúng. Chạy chậm hơn giới hạn 20, tức là 40 mph."},"tl":{"q":"Sa Texas, nasa daan ka na may 60 mph na limit at hindi ka makaalis sa lane na katabi ng nakahintong police car na may kumikislap na ilaw. Gaano kabilis ka puwedeng dumaan?","o":["40 mph o mas mabagal","50 mph o mas mabagal","55 mph o mas mabagal","60 mph o mas mabagal"],"h1":"Bawasan ng 20 ang speed limit.","h2":"Sinasabi ng batas ng Texas na kung hindi ka makaalis sa lane na katabi ng nakahintong emergency vehicle, dapat kang bumagal sa 20 mph na mas mababa sa limit, kaya 40 mph sa daang 60 mph.","p":"Tama. Bumagal sa 20 na mas mababa sa limit, kaya 40 mph."},"ar":{"q":"في Texas، أنت على طريق حدّ السرعة فيه 60 mph، ولا تستطيع ترك الحارة التي بجانب سيارة شرطة متوقفة أضواؤها تومض. بأي سرعة يجوز أن تمرّ؟","o":["40 mph أو أبطأ","50 mph أو أبطأ","55 mph أو أبطأ","60 mph أو أبطأ"],"h1":"اطرح 20 من حدّ السرعة.","h2":"يقول قانون Texas إنك إذا لم تستطع ترك الحارة التي بجانب مركبة طوارئ متوقفة، يجب أن تخفّف سرعتك إلى 20 mph أقل من الحدّ، أي 40 mph على طريق حدّه 60 mph.","p":"صحيح. خفّف إلى 20 أقل من الحدّ، أي 40 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-020","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, the speed limit is 25 mph. You pass a stopped emergency vehicle with flashing lights and cannot move out of the lane next to it. How fast may you go?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Take 20 away from the speed limit.","h2":"On a Texas road posted 25 mph, you must slow to 20 mph below the limit, which is 5 mph, when you pass a stopped emergency vehicle with its lights on.","p":"Right. At a 25 mph limit, pass at 5 mph."},"es":{"q":"En Texas, el límite es 25 mph. Usted pasa junto a un vehículo de emergencia detenido con luces intermitentes y no puede salir del carril de al lado. ¿A qué velocidad puede ir?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Réstele 20 al límite de velocidad.","h2":"En una vía de Texas con límite de 25 mph, debe bajar a 20 mph menos que el límite, es decir 5 mph, al pasar junto a un vehículo de emergencia detenido con las luces encendidas.","p":"Correcto. Con límite de 25 mph, pase a 5 mph."},"zh":{"q":"在 Texas，限速是 25 mph。你经过一辆闪灯停着的紧急车辆，无法离开紧挨着它的车道。你可以开多快？","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"用限速减去 20。","h2":"在 Texas 限速 25 mph 的路上，经过闪灯停着的紧急车辆时，你必须减速到比限速低 20 mph，也就是 5 mph。","p":"对。限速 25 mph 时，用 5 mph 经过。"},"vi":{"q":"Ở Texas, giới hạn tốc độ là 25 mph. Bạn đi ngang một xe khẩn cấp đang đỗ có đèn nhấp nháy và không thể rời làn xe kế bên nó. Bạn được chạy bao nhanh?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Lấy giới hạn tốc độ trừ đi 20.","h2":"Trên đường ở Texas có giới hạn 25 mph, bạn phải chạy chậm hơn giới hạn 20 mph, tức là 5 mph, khi đi ngang một xe khẩn cấp đang đỗ có bật đèn.","p":"Đúng. Ở giới hạn 25 mph, chạy qua với 5 mph."},"tl":{"q":"Sa Texas, 25 mph ang speed limit. Dumaraan ka sa nakahintong emergency vehicle na may kumikislap na ilaw at hindi ka makaalis sa lane na katabi nito. Gaano kabilis ka puwedeng pumunta?","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"Bawasan ng 20 ang speed limit.","h2":"Sa daan sa Texas na may nakapaskil na 25 mph, dapat kang bumagal sa 20 mph na mas mababa sa limit, na 5 mph, kapag dumaraan ka sa nakahintong emergency vehicle na nakabukas ang ilaw.","p":"Tama. Sa 25 mph na limit, dumaan sa 5 mph."},"ar":{"q":"في Texas، حدّ السرعة 25 mph. تمرّ بمركبة طوارئ متوقفة أضواؤها تومض، ولا تستطيع ترك الحارة التي بجانبها. بأي سرعة يجوز أن تسير؟","o":["15 mph","5 mph","10 mph","20 mph"],"h1":"اطرح 20 من حدّ السرعة.","h2":"على طريق في Texas حدّه 25 mph، يجب أن تخفّف سرعتك إلى 20 mph أقل من الحدّ، أي 5 mph، عندما تمرّ بمركبة طوارئ متوقفة أضواؤها مضاءة.","p":"صحيح. عند حدّ 25 mph، مُرّ بسرعة 5 mph."},"ref":{"doc":"TX","page":23}},{"id":"tx-021","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, a school bus with flashing red lights is stopped on the other side of a road divided only by a center left-turn lane. What must you do?","o":["Keep going, the turn lane divides the road","Slow to 20 mph and pass","Stop, because a turn lane does not divide the road","Honk and pass with care"],"h1":"A turn lane is not a barrier.","h2":"In Texas a center left-turn lane does not make separate roadways, so drivers going both ways must stop for a school bus with flashing red lights.","p":"Right. A turn lane does not count; you must stop."},"es":{"q":"En Texas, un autobús escolar con luces rojas intermitentes está detenido al otro lado de una vía dividida solo por un carril central para girar a la izquierda. ¿Qué debe hacer?","o":["Seguir, el carril de giro divide la vía","Bajar a 20 mph y pasar","Parar, porque un carril de giro no divide la vía","Tocar el claxon y pasar con cuidado"],"h1":"Un carril de giro no es una barrera.","h2":"En Texas un carril central para girar a la izquierda no crea vías separadas, así que los conductores en ambos sentidos deben parar ante un autobús escolar con luces rojas intermitentes.","p":"Correcto. El carril de giro no cuenta; debe parar."},"zh":{"q":"在 Texas，一辆闪红灯的校车停在路的另一边，这条路只用中间的左转车道分开。你必须怎么做？","o":["继续开，转弯车道把路分开了","减速到 20 mph 再经过","停车，因为转弯车道不算把路分开","按喇叭，小心经过"],"h1":"转弯车道不是隔离物。","h2":"在 Texas，中间的左转车道不会把路分成两条独立的道路，所以两个方向的司机都必须为闪红灯的校车停车。","p":"对。转弯车道不算，你必须停车。"},"vi":{"q":"Ở Texas, một xe buýt trường học có đèn đỏ nhấp nháy đang dừng ở phía bên kia con đường, và con đường chỉ được chia bằng một làn rẽ trái ở giữa. Bạn phải làm gì?","o":["Cứ đi tiếp, làn rẽ chia con đường","Giảm xuống 20 mph rồi chạy qua","Dừng lại, vì làn rẽ không chia con đường","Bấm còi rồi cẩn thận chạy qua"],"h1":"Làn rẽ không phải là vật chắn.","h2":"Ở Texas, làn rẽ trái ở giữa không tạo thành hai con đường riêng, nên tài xế đi cả hai chiều phải dừng lại cho xe buýt trường học có đèn đỏ nhấp nháy.","p":"Đúng. Làn rẽ không được tính; bạn phải dừng lại."},"tl":{"q":"Sa Texas, nakahinto ang school bus na may kumikislap na pulang ilaw sa kabilang panig ng daan na hinahati lang ng center left-turn lane. Ano ang dapat mong gawin?","o":["Tumuloy, hinahati ng turn lane ang daan","Bumagal sa 20 mph at dumaan","Huminto, dahil hindi hinahati ng turn lane ang daan","Bumusina at dumaan nang maingat"],"h1":"Hindi harang ang turn lane.","h2":"Sa Texas, hindi gumagawa ng magkahiwalay na daan ang center left-turn lane, kaya ang mga driver sa magkabilang direksyon ay dapat huminto para sa school bus na may kumikislap na pulang ilaw.","p":"Tama. Hindi binibilang ang turn lane; dapat kang huminto."},"ar":{"q":"في Texas، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الجانب الآخر من طريق لا يفصله إلا حارة انعطاف يسار في الوسط. ماذا يجب أن تفعل؟","o":["استمرّ، فحارة الانعطاف تفصل الطريق","خفّف إلى 20 mph ومُرّ","توقّف، لأن حارة الانعطاف لا تفصل الطريق","استخدم البوق ومُرّ بحذر"],"h1":"حارة الانعطاف ليست حاجزًا.","h2":"في Texas، حارة الانعطاف يسارًا في الوسط لا تجعل الطريق طريقين منفصلين، لذلك يجب على السائقين في الاتجاهين أن يتوقّفوا للحافلة المدرسية التي أضواؤها الحمراء تومض.","p":"صحيح. حارة الانعطاف لا تُحسب؛ يجب أن تتوقّف."},"ref":{"doc":"TX","page":null}},{"id":"tx-022","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, when may you keep going past a stopped school bus with flashing red lights coming the other way?","o":["When no children are in sight","When you are late for work","When the bus is more than 50 feet away","When a physical barrier or median separates the roads"],"h1":"The two directions must be truly separated.","h2":"In Texas you need not stop for a school bus on the other roadway only when the roads are separated by a physical barrier or a space where cars cannot drive.","p":"Right. Only a real barrier or median lets you keep going."},"es":{"q":"En Texas, ¿cuándo puede seguir adelante si viene en sentido contrario a un autobús escolar detenido con luces rojas intermitentes?","o":["Cuando no se ven niños","Cuando va tarde al trabajo","Cuando el autobús está a más de 50 pies","Cuando una barrera física o un camellón separa las vías"],"h1":"Los dos sentidos deben estar realmente separados.","h2":"En Texas no tiene que parar ante un autobús escolar en la otra vía solo cuando las vías están separadas por una barrera física o un espacio por donde no pueden pasar carros.","p":"Correcto. Solo una barrera o un camellón real le permite seguir."},"zh":{"q":"在 Texas，对面方向有一辆闪红灯停着的校车，什么时候你可以继续开过去？","o":["看不到孩子的时候","你上班快迟到的时候","校车在 50 英尺以外的时候","有实体隔离物或中央分隔带把两边道路分开的时候"],"h1":"两个方向必须真的被分开。","h2":"在 Texas，只有当两边道路被实体隔离物或车辆不能开过去的空间分开时，你才不需要为另一边道路上的校车停车。","p":"对。只有真正的隔离物或中央分隔带才能让你继续开。"},"vi":{"q":"Ở Texas, khi nào bạn được đi tiếp qua một xe buýt trường học đang dừng có đèn đỏ nhấp nháy ở chiều ngược lại?","o":["Khi không thấy trẻ em nào","Khi bạn sắp trễ giờ làm","Khi xe buýt cách xa hơn 50 feet","Khi có vật chắn thật hoặc dải phân cách chia hai con đường"],"h1":"Hai chiều xe phải thật sự được tách ra.","h2":"Ở Texas, bạn chỉ không cần dừng cho xe buýt trường học ở con đường bên kia khi hai con đường được chia bằng vật chắn thật hoặc một khoảng mà xe không thể chạy qua.","p":"Đúng. Chỉ vật chắn thật hoặc dải phân cách mới cho bạn đi tiếp."},"tl":{"q":"Sa Texas, kailan ka puwedeng tumuloy sa pagdaan sa nakahintong school bus na may kumikislap na pulang ilaw na nasa kabilang direksyon?","o":["Kapag walang makitang bata","Kapag huli ka na sa trabaho","Kapag mahigit 50 feet ang layo ng bus","Kapag may pisikal na harang o median na naghihiwalay sa mga daan"],"h1":"Dapat ay tunay na magkahiwalay ang dalawang direksyon.","h2":"Sa Texas, hindi mo kailangang huminto para sa school bus sa kabilang daan kapag lang hinihiwalay ang mga daan ng pisikal na harang o espasyong hindi madadaanan ng mga sasakyan.","p":"Tama. Tunay na harang o median lang ang nagpapahintulot sa iyong tumuloy."},"ar":{"q":"في Texas، متى يجوز أن تستمرّ وتمرّ بحافلة مدرسية متوقفة أضواؤها الحمراء تومض وهي في الاتجاه المعاكس؟","o":["عندما لا ترى أي أطفال","عندما تكون متأخرًا عن العمل","عندما تكون الحافلة على بُعد أكثر من 50 قدمًا","عندما يفصل بين الطريقين حاجز مادي أو جزيرة وسطية"],"h1":"يجب أن يكون الاتجاهان منفصلين فعلًا.","h2":"في Texas لا تحتاج إلى التوقّف لحافلة مدرسية على الطريق الآخر إلا إذا كان الطريقان مفصولين بحاجز مادي أو بمساحة لا تستطيع السيارات السير فيها.","p":"صحيح. فقط حاجز حقيقي أو جزيرة وسطية تسمح لك بالاستمرار."},"ref":{"doc":"TX","page":null}},{"id":"tx-023","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, what fine range applies for a first offense of passing a stopped school bus illegally?","o":["$500 to $1,250","$50 to $200","$100 to $500","$2,000 to $5,000"],"h1":"It starts at five hundred dollars.","h2":"In Texas a first offense of illegally passing a stopped school bus carries a fine of $500 to $1,250, and repeat offenses cost more.","p":"Right. A first offense costs $500 to $1,250."},"es":{"q":"En Texas, ¿qué rango de multa se aplica la primera vez que se pasa ilegalmente un autobús escolar detenido?","o":["De $500 a $1,250","De $50 a $200","De $100 a $500","De $2,000 a $5,000"],"h1":"Empieza en quinientos dólares.","h2":"En Texas, la primera vez que se pasa ilegalmente un autobús escolar detenido la multa es de $500 a $1,250, y si se repite cuesta más.","p":"Correcto. La primera vez cuesta de $500 a $1,250."},"zh":{"q":"在 Texas，第一次违法超过停着的校车，罚款范围是多少？","o":["$500 到 $1,250","$50 到 $200","$100 到 $500","$2,000 到 $5,000"],"h1":"它从五百美元开始。","h2":"在 Texas，第一次违法超过停着的校车，罚款是 $500 到 $1,250，再犯罚得更多。","p":"对。第一次违法罚 $500 到 $1,250。"},"vi":{"q":"Ở Texas, mức phạt cho lần vi phạm đầu tiên vì vượt qua xe buýt trường học đang dừng một cách bất hợp pháp là bao nhiêu?","o":["$500 đến $1,250","$50 đến $200","$100 đến $500","$2,000 đến $5,000"],"h1":"Nó bắt đầu từ năm trăm đô la.","h2":"Ở Texas, lần đầu vượt qua xe buýt trường học đang dừng một cách bất hợp pháp bị phạt từ $500 đến $1,250, và các lần sau bị phạt nặng hơn.","p":"Đúng. Lần vi phạm đầu bị phạt $500 đến $1,250."},"tl":{"q":"Sa Texas, magkano ang multa para sa unang paglabag sa ilegal na pag-overtake sa nakahintong school bus?","o":["$500 hanggang $1,250","$50 hanggang $200","$100 hanggang $500","$2,000 hanggang $5,000"],"h1":"Nagsisimula ito sa limandaang dolyar.","h2":"Sa Texas, ang unang paglabag sa ilegal na pag-overtake sa nakahintong school bus ay may multang $500 hanggang $1,250, at mas mahal ang mga sumunod na paglabag.","p":"Tama. Ang unang paglabag ay $500 hanggang $1,250."},"ar":{"q":"في Texas، ما نطاق الغرامة على المخالفة الأولى لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني؟","o":["$500 إلى $1,250","$50 إلى $200","$100 إلى $500","$2,000 إلى $5,000"],"h1":"تبدأ من خمسمئة دولار.","h2":"في Texas، المخالفة الأولى لتجاوز حافلة مدرسية متوقفة بشكل غير قانوني عليها غرامة من $500 إلى $1,250، والمخالفات المتكرّرة تكلّف أكثر.","p":"صحيح. المخالفة الأولى تكلّف من $500 إلى $1,250."},"ref":{"doc":"TX","page":23}},{"id":"tx-024","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, unless a sign says otherwise, what is the speed limit on a street in an urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"It is a round number that is lower than 35.","h2":"Texas law sets 30 mph as the speed limit on streets in an urban district when no other limit is posted.","p":"Right. The urban district limit is 30 mph."},"es":{"q":"En Texas, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en una calle de zona urbana?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Es un número redondo menor que 35.","h2":"La ley de Texas fija 30 mph como límite en las calles de zona urbana cuando no hay otro límite indicado.","p":"Correcto. El límite en zona urbana es 30 mph."},"zh":{"q":"在 Texas，如果没有标志另外规定，市区（urban district）街道的限速是多少？","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"它是一个比 35 小的整数。","h2":"Texas 法律规定，没有标出其他限速时，市区街道的限速是 30 mph。","p":"对。市区限速是 30 mph。"},"vi":{"q":"Ở Texas, nếu không có biển báo khác, giới hạn tốc độ trên đường phố trong khu đô thị (urban district) là bao nhiêu?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Đó là một số tròn nhỏ hơn 35.","h2":"Luật Texas đặt giới hạn 30 mph trên đường phố trong khu đô thị khi không có giới hạn nào khác được ghi.","p":"Đúng. Giới hạn trong khu đô thị là 30 mph."},"tl":{"q":"Sa Texas, kung walang ibang sinasabi ang karatula, ano ang speed limit sa kalye sa urban district?","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"Isa itong buong numero na mas mababa sa 35.","h2":"Itinatakda ng batas ng Texas ang 30 mph bilang speed limit sa mga kalye sa urban district kapag walang ibang limit na nakapaskil.","p":"Tama. 30 mph ang limit sa urban district."},"ar":{"q":"في Texas، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في شارع داخل منطقة حضرية (urban district)؟","o":["25 mph","30 mph","35 mph","40 mph"],"h1":"هو رقم مدوَّر أقل من 35.","h2":"يحدّد قانون Texas سرعة 30 mph حدًّا للسرعة في شوارع المنطقة الحضرية عندما لا يكون هناك حدّ آخر مكتوب.","p":"صحيح. حدّ السرعة في المنطقة الحضرية 30 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-025","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, how much alcohol may a driver under 21 have in their system?","o":["Less than 0.08","Less than 0.05","Less than 0.02","None that can be detected"],"h1":"Texas has zero tolerance for young drivers.","h2":"A Texas driver under 21 commits an offense with any detectable amount of alcohol, even below the adult limit of 0.08.","p":"Right. Under 21 means no detectable alcohol."},"es":{"q":"En Texas, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años?","o":["Menos de 0.08","Menos de 0.05","Menos de 0.02","Nada que se pueda detectar"],"h1":"Texas tiene tolerancia cero para conductores jóvenes.","h2":"Un conductor menor de 21 en Texas comete un delito con cualquier cantidad de alcohol que se pueda detectar, aunque esté por debajo del límite de 0.08 para adultos.","p":"Correcto. Menor de 21 significa nada de alcohol detectable."},"zh":{"q":"在 Texas，未满 21 岁的司机体内可以有多少酒精？","o":["低于 0.08","低于 0.05","低于 0.02","一点都不能被检测到"],"h1":"Texas 对年轻司机是零容忍。","h2":"Texas 未满 21 岁的司机，只要体内能检测到任何酒精就是违法，即使低于成年人的 0.08 上限。","p":"对。未满 21 岁，不能有任何能检测到的酒精。"},"vi":{"q":"Ở Texas, tài xế dưới 21 tuổi được có bao nhiêu rượu bia trong cơ thể?","o":["Dưới 0.08","Dưới 0.05","Dưới 0.02","Không có chút nào đo được"],"h1":"Texas không khoan nhượng với tài xế trẻ.","h2":"Tài xế dưới 21 tuổi ở Texas phạm luật nếu có bất kỳ lượng rượu bia nào đo được, kể cả dưới mức 0.08 của người lớn.","p":"Đúng. Dưới 21 tuổi là không có rượu bia nào đo được."},"tl":{"q":"Sa Texas, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21?","o":["Mas mababa sa 0.08","Mas mababa sa 0.05","Mas mababa sa 0.02","Wala na kayang ma-detect"],"h1":"Zero tolerance ang Texas para sa mga batang driver.","h2":"Ang driver sa Texas na wala pang 21 ay lumalabag sa batas kapag may kahit anong dami ng alak na kayang ma-detect, kahit mas mababa sa 0.08 na limit para sa adulto.","p":"Tama. Kung wala pang 21, walang alak na kayang ma-detect."},"ar":{"q":"في Texas، كم من الكحول يجوز أن يكون في جسم السائق الذي عمره أقل من 21 سنة؟","o":["أقل من 0.08","أقل من 0.05","أقل من 0.02","لا شيء يمكن اكتشافه"],"h1":"Texas لا تتسامح أبدًا مع السائقين الصغار.","h2":"السائق في Texas الذي عمره أقل من 21 سنة يرتكب مخالفة إذا وُجدت في جسمه أي كمية من الكحول يمكن اكتشافها، حتى لو كانت أقل من حدّ الكبار 0.08.","p":"صحيح. تحت 21 سنة يعني لا كحول يمكن اكتشافه."},"ref":{"doc":"TX","page":56}},{"id":"tx-026","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what is the minimum liability insurance for injury to one person in a crash?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"It is the first number in 30/60/25.","h2":"Texas requires at least $30,000 of bodily injury coverage for one person in a crash, the first number in the 30/60/25 minimum.","p":"Right. The minimum for one injured person is $30,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por lesiones a una persona en un choque?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Es el primer número de 30/60/25.","h2":"Texas exige por lo menos $30,000 de cobertura por lesiones a una persona en un choque, el primer número del mínimo 30/60/25.","p":"Correcto. El mínimo por una persona lesionada es $30,000."},"zh":{"q":"在 Texas，车祸中一个人受伤的最低责任保险是多少？","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"它是 30/60/25 里的第一个数字。","h2":"Texas 要求车祸中一个人的人身伤害保险至少 $30,000，也就是 30/60/25 最低标准里的第一个数字。","p":"对。一个人受伤的最低保额是 $30,000。"},"vi":{"q":"Ở Texas, bảo hiểm trách nhiệm tối thiểu cho thương tích của một người trong tai nạn là bao nhiêu?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Đó là số đầu tiên trong 30/60/25.","h2":"Texas yêu cầu ít nhất $30,000 bảo hiểm thương tích cho một người trong tai nạn, là số đầu tiên trong mức tối thiểu 30/60/25.","p":"Đúng. Mức tối thiểu cho một người bị thương là $30,000."},"tl":{"q":"Sa Texas, ano ang minimum na liability insurance para sa pinsala sa katawan ng isang tao sa banggaan?","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"Ito ang unang numero sa 30/60/25.","h2":"Humihingi ang Texas ng hindi bababa sa $30,000 na bodily injury coverage para sa isang tao sa banggaan, ang unang numero sa 30/60/25 na minimum.","p":"Tama. $30,000 ang minimum para sa isang taong nasaktan."},"ar":{"q":"في Texas، ما الحدّ الأدنى لتأمين المسؤولية عن إصابة شخص واحد في حادث؟","o":["$15,000","$25,000","$30,000","$50,000"],"h1":"هو الرقم الأول في 30/60/25.","h2":"تطلب Texas تأمينًا لا يقلّ عن $30,000 للإصابات الجسدية لشخص واحد في حادث، وهو الرقم الأول في الحدّ الأدنى 30/60/25.","p":"صحيح. الحدّ الأدنى لشخص واحد مصاب هو $30,000."},"ref":{"doc":"TX","page":18}},{"id":"tx-027","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"It is the last number in 30/60/25.","h2":"Texas requires at least $25,000 of property damage liability for one crash, the last number in the 30/60/25 minimum.","p":"Right. The property damage minimum is $25,000."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por daños a la propiedad de otros en un choque?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Es el último número de 30/60/25.","h2":"Texas exige por lo menos $25,000 de cobertura por daños a la propiedad en un choque, el último número del mínimo 30/60/25.","p":"Correcto. El mínimo por daños a la propiedad es $25,000."},"zh":{"q":"在 Texas，一次车祸中对别人财产损失的最低责任保险是多少？","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"它是 30/60/25 里的最后一个数字。","h2":"Texas 要求一次车祸的财产损失责任保险至少 $25,000，也就是 30/60/25 最低标准里的最后一个数字。","p":"对。财产损失的最低保额是 $25,000。"},"vi":{"q":"Ở Texas, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản của người khác trong một tai nạn là bao nhiêu?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Đó là số cuối cùng trong 30/60/25.","h2":"Texas yêu cầu ít nhất $25,000 bảo hiểm trách nhiệm thiệt hại tài sản cho một tai nạn, là số cuối cùng trong mức tối thiểu 30/60/25.","p":"Đúng. Mức tối thiểu cho thiệt hại tài sản là $25,000."},"tl":{"q":"Sa Texas, ano ang minimum na liability insurance para sa pinsala sa ari-arian ng ibang tao sa isang banggaan?","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"Ito ang huling numero sa 30/60/25.","h2":"Humihingi ang Texas ng hindi bababa sa $25,000 na property damage liability para sa isang banggaan, ang huling numero sa 30/60/25 na minimum.","p":"Tama. $25,000 ang minimum para sa pinsala sa ari-arian."},"ar":{"q":"في Texas، ما الحدّ الأدنى لتأمين المسؤولية عن الأضرار في ممتلكات الآخرين في حادث واحد؟","o":["$10,000","$25,000","$30,000","$60,000"],"h1":"هو الرقم الأخير في 30/60/25.","h2":"تطلب Texas تأمين مسؤولية لا يقلّ عن $25,000 لأضرار الممتلكات في حادث واحد، وهو الرقم الأخير في الحدّ الأدنى 30/60/25.","p":"صحيح. الحدّ الأدنى لأضرار الممتلكات هو $25,000."},"ref":{"doc":"TX","page":18}},{"id":"tx-028","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, when does a teen's learner license expire?","o":["One year after it is issued","On the teen's 18th birthday","Six months after it is issued","On the teen's 21st birthday"],"h1":"It is tied to a birthday.","h2":"In Texas a learner license expires on the minor's 18th birthday.","p":"Right. It expires on the 18th birthday."},"es":{"q":"En Texas, ¿cuándo vence la licencia de aprendiz de un adolescente?","o":["Un año después de emitida","En el cumpleaños número 18 del adolescente","Seis meses después de emitida","En el cumpleaños número 21 del adolescente"],"h1":"Depende de un cumpleaños.","h2":"En Texas una licencia de aprendiz vence en el cumpleaños número 18 del menor.","p":"Correcto. Vence en el cumpleaños número 18."},"zh":{"q":"在 Texas，青少年的学习驾照（learner license）什么时候过期？","o":["发证一年后","在青少年 18 岁生日那天","发证六个月后","在青少年 21 岁生日那天"],"h1":"它和生日有关。","h2":"在 Texas，未成年人的学习驾照在他 18 岁生日那天过期。","p":"对。它在 18 岁生日那天过期。"},"vi":{"q":"Ở Texas, bằng lái tập (learner license) của thiếu niên hết hạn khi nào?","o":["Một năm sau khi được cấp","Vào ngày sinh nhật 18 tuổi của thiếu niên","Sáu tháng sau khi được cấp","Vào ngày sinh nhật 21 tuổi của thiếu niên"],"h1":"Nó gắn với một ngày sinh nhật.","h2":"Ở Texas, bằng lái tập của người chưa thành niên hết hạn vào ngày sinh nhật 18 tuổi.","p":"Đúng. Nó hết hạn vào ngày sinh nhật 18 tuổi."},"tl":{"q":"Sa Texas, kailan mag-e-expire ang learner license ng isang teenager?","o":["Isang taon matapos itong ibigay","Sa ika-18 kaarawan ng teenager","Anim na buwan matapos itong ibigay","Sa ika-21 kaarawan ng teenager"],"h1":"Nakatali ito sa isang kaarawan.","h2":"Sa Texas, nag-e-expire ang learner license ng isang menor de edad sa kanyang ika-18 kaarawan.","p":"Tama. Nag-e-expire ito sa ika-18 kaarawan."},"ar":{"q":"في Texas، متى تنتهي رخصة التعلّم (learner license) للمراهق؟","o":["بعد سنة من إصدارها","في عيد ميلاد المراهق الثامن عشر (18)","بعد ستة أشهر من إصدارها","في عيد ميلاد المراهق الحادي والعشرين (21)"],"h1":"ترتبط بعيد ميلاد.","h2":"في Texas تنتهي رخصة التعلّم للقاصر في عيد ميلاده الثامن عشر (18).","p":"صحيح. تنتهي في عيد الميلاد الثامن عشر (18)."},"ref":{"doc":"TX","page":1}},{"id":"tx-029","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what fine can a driver get for a first conviction of driving without proof of liability insurance?","o":["$175 to $350","$50 to $100","$500 to $750","$1,000 to $2,000"],"h1":"A second conviction costs more, up to $1,000.","h2":"In Texas a first conviction for driving without proof of liability insurance brings a fine of $175 to $350.","p":"Right. The first fine is $175 to $350."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por una primera condena por manejar sin prueba de seguro de responsabilidad civil?","o":["De $175 a $350","De $50 a $100","De $500 a $750","De $1,000 a $2,000"],"h1":"Una segunda condena cuesta más, hasta $1,000.","h2":"En Texas una primera condena por manejar sin prueba de seguro de responsabilidad civil trae una multa de $175 a $350.","p":"Correcto. La primera multa es de $175 a $350."},"zh":{"q":"在 Texas，司机第一次因为开车时没有责任保险证明而被定罪，可能被罚多少钱？","o":["$175 到 $350","$50 到 $100","$500 到 $750","$1,000 到 $2,000"],"h1":"第二次定罪罚得更多，最高 $1,000。","h2":"在 Texas，第一次因为开车时没有责任保险证明而被定罪，罚款是 $175 到 $350。","p":"对。第一次罚款是 $175 到 $350。"},"vi":{"q":"Ở Texas, tài xế có thể bị phạt bao nhiêu khi bị kết tội lần đầu vì lái xe không có giấy chứng nhận bảo hiểm trách nhiệm?","o":["$175 đến $350","$50 đến $100","$500 đến $750","$1,000 đến $2,000"],"h1":"Bị kết tội lần thứ hai sẽ tốn nhiều hơn, đến $1,000.","h2":"Ở Texas, bị kết tội lần đầu vì lái xe không có giấy chứng nhận bảo hiểm trách nhiệm sẽ bị phạt từ $175 đến $350.","p":"Đúng. Tiền phạt lần đầu là $175 đến $350."},"tl":{"q":"Sa Texas, magkano ang multa na puwedeng makuha ng driver sa unang conviction dahil nagmaneho nang walang patunay ng liability insurance?","o":["$175 hanggang $350","$50 hanggang $100","$500 hanggang $750","$1,000 hanggang $2,000"],"h1":"Mas mahal ang ikalawang conviction, hanggang $1,000.","h2":"Sa Texas, ang unang conviction dahil nagmaneho nang walang patunay ng liability insurance ay may multang $175 hanggang $350.","p":"Tama. Ang unang multa ay $175 hanggang $350."},"ar":{"q":"في Texas، ما الغرامة التي قد يتلقاها السائق عند إدانته أول مرة بالقيادة دون إثبات تأمين المسؤولية؟","o":["من $175 إلى $350","من $50 إلى $100","من $500 إلى $750","من $1,000 إلى $2,000"],"h1":"الإدانة الثانية تكلّف أكثر، حتى $1,000.","h2":"في Texas، الإدانة الأولى بالقيادة دون إثبات تأمين المسؤولية تعني غرامة من $175 إلى $350.","p":"صحيح. الغرامة الأولى من $175 إلى $350."},"ref":{"doc":"TX","page":18}},{"id":"tx-030","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, how close may you follow a fire truck that is answering an alarm with its red lights flashing?","o":["No closer than 50 feet","No closer than 100 feet","No closer than 250 feet","No closer than 500 feet"],"h1":"It is more than the length of a football field.","h2":"In Texas you may not follow within 500 feet of a fire truck answering an alarm, or an ambulance, when its flashing red lights are on.","p":"Right. Stay at least 500 feet behind."},"es":{"q":"En Texas, ¿qué tan cerca puede seguir a un camión de bomberos que atiende una alarma con sus luces rojas intermitentes?","o":["No más cerca de 50 pies","No más cerca de 100 pies","No más cerca de 250 pies","No más cerca de 500 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"En Texas usted no puede seguir a menos de 500 pies a un camión de bomberos que atiende una alarma, ni a una ambulancia, cuando tiene encendidas sus luces rojas intermitentes.","p":"Correcto. Quédese por lo menos a 500 pies detrás."},"zh":{"q":"在 Texas，消防车闪着红灯去处理警报时，你可以跟在它后面多近？","o":["不能近于 50 英尺","不能近于 100 英尺","不能近于 250 英尺","不能近于 500 英尺"],"h1":"它比一个橄榄球场还长。","h2":"在 Texas，消防车去处理警报或救护车闪着红灯时，你不能跟在它后面 500 英尺以内。","p":"对。至少保持在 500 英尺以外。"},"vi":{"q":"Ở Texas, bạn được chạy theo sau xe cứu hỏa đang đi xử lý báo động và nháy đèn đỏ gần đến mức nào?","o":["Không gần hơn 50 feet","Không gần hơn 100 feet","Không gần hơn 250 feet","Không gần hơn 500 feet"],"h1":"Nó dài hơn một sân bóng bầu dục.","h2":"Ở Texas, bạn không được chạy theo trong vòng 500 feet sau xe cứu hỏa đang đi xử lý báo động, hoặc xe cứu thương, khi xe đang nháy đèn đỏ.","p":"Đúng. Hãy giữ cách xa ít nhất 500 feet."},"tl":{"q":"Sa Texas, gaano kalapit ka puwedeng sumunod sa isang fire truck na rumeresponde sa alarma at kumikislap ang pulang ilaw?","o":["Hindi lalapit sa 50 talampakan","Hindi lalapit sa 100 talampakan","Hindi lalapit sa 250 talampakan","Hindi lalapit sa 500 talampakan"],"h1":"Mas mahaba ito kaysa sa isang football field.","h2":"Sa Texas, hindi ka puwedeng sumunod nang mas malapit sa 500 talampakan sa isang fire truck na rumeresponde sa alarma, o sa ambulansya, kapag kumikislap ang pulang ilaw nito.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod."},"ar":{"q":"في Texas، إلى أي مسافة يمكنك أن تقترب وأنت تسير خلف سيارة إطفاء تستجيب لإنذار وأضواؤها الحمراء تومض؟","o":["ليس أقرب من 50 قدمًا","ليس أقرب من 100 قدم","ليس أقرب من 250 قدمًا","ليس أقرب من 500 قدم"],"h1":"المسافة أطول من ملعب كرة قدم أمريكية.","h2":"في Texas لا يجوز لك أن تسير على بعد أقل من 500 قدم خلف سيارة إطفاء تستجيب لإنذار، أو خلف سيارة إسعاف، عندما تكون أضواؤها الحمراء تومض.","p":"صحيح. ابقَ على بعد 500 قدم على الأقل."},"ref":{"doc":"TX","page":22}},{"id":"tx-031","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, what is the highest fine for having an open container of alcohol in the passenger area of a vehicle on a public road?","o":["$50","$100","$500","$5,000"],"h1":"The car does not even have to be moving.","h2":"In Texas having an open container of alcohol in the passenger area on a public road can bring a fine of up to $500, even if the vehicle is stopped or parked.","p":"Right. The fine can be up to $500."},"es":{"q":"En Texas, ¿cuál es la multa más alta por tener un envase abierto de alcohol en el área de pasajeros de un vehículo en una vía pública?","o":["$50","$100","$500","$5,000"],"h1":"El carro ni siquiera tiene que estar en movimiento.","h2":"En Texas tener un envase abierto de alcohol en el área de pasajeros en una vía pública puede traer una multa de hasta $500, aunque el vehículo esté detenido o estacionado.","p":"Correcto. La multa puede ser de hasta $500."},"zh":{"q":"在 Texas，在公共道路上的车辆乘客区放着打开的酒类容器，最高罚款是多少？","o":["$50","$100","$500","$5,000"],"h1":"车子甚至不需要在开动。","h2":"在 Texas，在公共道路上的车辆乘客区放着打开的酒类容器，最高可罚 $500，即使车子停着或已经停放。","p":"对。罚款最高 $500。"},"vi":{"q":"Ở Texas, tiền phạt cao nhất cho việc để đồ uống có cồn đã mở trong khu vực hành khách của xe trên đường công cộng là bao nhiêu?","o":["$50","$100","$500","$5,000"],"h1":"Xe thậm chí không cần đang chạy.","h2":"Ở Texas, để đồ uống có cồn đã mở trong khu vực hành khách của xe trên đường công cộng có thể bị phạt đến $500, ngay cả khi xe đang dừng hoặc đậu.","p":"Đúng. Tiền phạt có thể đến $500."},"tl":{"q":"Sa Texas, ano ang pinakamataas na multa kapag may bukas na lalagyan ng alak sa lugar ng pasahero ng sasakyan sa pampublikong kalsada?","o":["$50","$100","$500","$5,000"],"h1":"Hindi na kailangang umaandar ang sasakyan.","h2":"Sa Texas, ang pagkakaroon ng bukas na lalagyan ng alak sa lugar ng pasahero sa pampublikong kalsada ay puwedeng magmulta nang hanggang $500, kahit nakahinto o nakaparada ang sasakyan.","p":"Tama. Ang multa ay puwedeng umabot sa $500."},"ar":{"q":"في Texas، ما أعلى غرامة لوجود عبوة كحول مفتوحة في مكان الركّاب في مركبة على طريق عام؟","o":["$50","$100","$500","$5,000"],"h1":"لا يلزم حتى أن تكون السيارة تتحرك.","h2":"في Texas، وجود عبوة كحول مفتوحة في مكان الركّاب على طريق عام قد يؤدي إلى غرامة تصل إلى $500، حتى لو كانت المركبة متوقفة أو مركونة.","p":"صحيح. قد تصل الغرامة إلى $500."},"ref":{"doc":"TX","page":56}},{"id":"tx-032","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, which new driver license applicants must finish an approved driver education course?","o":["Only applicants under 18","Only applicants under 21","Applicants younger than 25","Every applicant, at any age"],"h1":"The rule covers teens and many young adults too.","h2":"In Texas every license applicant younger than 25 must finish an approved driver education course.","p":"Right. Under 25 means driver education first."},"es":{"q":"En Texas, ¿qué solicitantes nuevos de licencia de manejo deben terminar un curso aprobado de educación vial?","o":["Solo los menores de 18 años","Solo los menores de 21 años","Los menores de 25 años","Todos los solicitantes, de cualquier edad"],"h1":"La regla incluye a los adolescentes y también a muchos adultos jóvenes.","h2":"En Texas todo solicitante de licencia menor de 25 años debe terminar un curso aprobado de educación vial.","p":"Correcto. Si tiene menos de 25 años, primero hace educación vial."},"zh":{"q":"在 Texas，哪些新申请驾照的人必须完成经批准的驾驶员教育课程？","o":["只有未满 18 岁的申请人","只有未满 21 岁的申请人","未满 25 岁的申请人","所有申请人，不论年龄"],"h1":"这条规定也包括青少年和很多年轻成年人。","h2":"在 Texas，所有未满 25 岁的驾照申请人都必须完成经批准的驾驶员教育课程。","p":"对。未满 25 岁，要先上驾驶员教育课。"},"vi":{"q":"Ở Texas, những người mới xin bằng lái nào phải hoàn thành một khóa học giáo dục lái xe được chấp thuận?","o":["Chỉ người dưới 18 tuổi","Chỉ người dưới 21 tuổi","Người dưới 25 tuổi","Mọi người xin bằng, ở bất kỳ tuổi nào"],"h1":"Quy định này bao gồm cả thanh thiếu niên và nhiều người trẻ tuổi.","h2":"Ở Texas, mọi người xin bằng lái dưới 25 tuổi phải hoàn thành một khóa học giáo dục lái xe được chấp thuận.","p":"Đúng. Dưới 25 tuổi thì phải học giáo dục lái xe trước."},"tl":{"q":"Sa Texas, sinong mga bagong aplikante ng driver license ang dapat tumapos ng aprubadong driver education course?","o":["Mga aplikanteng wala pang 18 lang","Mga aplikanteng wala pang 21 lang","Mga aplikanteng wala pang 25","Lahat ng aplikante, kahit anong edad"],"h1":"Kasama sa patakaran ang mga teenager at marami ring young adult.","h2":"Sa Texas, lahat ng aplikante ng lisensya na wala pang 25 taong gulang ay dapat tumapos ng aprubadong driver education course.","p":"Tama. Kapag wala pang 25, driver education muna."},"ar":{"q":"في Texas، أيّ المتقدّمين الجدد لرخصة القيادة يجب أن يُكملوا دورة تعليم قيادة معتمدة؟","o":["فقط من عمرهم أقل من 18 سنة","فقط من عمرهم أقل من 21 سنة","من عمرهم أقل من 25 سنة","كل المتقدّمين، في أي عمر"],"h1":"القاعدة تشمل المراهقين وكثيرًا من الشباب البالغين أيضًا.","h2":"في Texas يجب على كل متقدّم لرخصة القيادة عمره أقل من 25 سنة أن يُكمل دورة تعليم قيادة معتمدة.","p":"صحيح. أقل من 25 سنة يعني تعليم القيادة أولًا."},"ref":{"doc":"TX","page":7}},{"id":"tx-033","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, even if you can renew online, how often must you go to a driver license office for a vision exam and a new photo?","o":["At least once every 4 years","At least once every 8 years","At least once every 12 years","At least once every 16 years"],"h1":"It is twice as long as one license period of eight years.","h2":"In Texas you must visit a driver license office at least once every 16 years for a vision exam and to update your photo, signature and fingerprints.","p":"Right. Once every 16 years, in person."},"es":{"q":"En Texas, aunque pueda renovar en línea, ¿cada cuánto tiempo debe ir a una oficina de licencias para un examen de la vista y una foto nueva?","o":["Por lo menos una vez cada 4 años","Por lo menos una vez cada 8 años","Por lo menos una vez cada 12 años","Por lo menos una vez cada 16 años"],"h1":"Es el doble de un periodo de licencia de ocho años.","h2":"En Texas usted debe ir a una oficina de licencias por lo menos una vez cada 16 años para un examen de la vista y para actualizar su foto, firma y huellas.","p":"Correcto. Una vez cada 16 años, en persona."},"zh":{"q":"在 Texas，即使你可以网上续驾照，你至少多久必须去一次驾照办公室做视力检查和拍新照片？","o":["至少每 4 年一次","至少每 8 年一次","至少每 12 年一次","至少每 16 年一次"],"h1":"它是一个八年驾照期的两倍。","h2":"在 Texas，你至少每 16 年必须去一次驾照办公室，做视力检查，并更新你的照片、签名和指纹。","p":"对。每 16 年亲自去一次。"},"vi":{"q":"Ở Texas, dù bạn có thể gia hạn trên mạng, bao lâu bạn phải đến văn phòng cấp bằng lái một lần để kiểm tra mắt và chụp ảnh mới?","o":["Ít nhất 4 năm một lần","Ít nhất 8 năm một lần","Ít nhất 12 năm một lần","Ít nhất 16 năm một lần"],"h1":"Đó là gấp đôi một kỳ hạn bằng lái tám năm.","h2":"Ở Texas, bạn phải đến văn phòng cấp bằng lái ít nhất 16 năm một lần để kiểm tra mắt và cập nhật ảnh, chữ ký và dấu vân tay.","p":"Đúng. 16 năm một lần, phải đến tận nơi."},"tl":{"q":"Sa Texas, kahit puwede kang mag-renew online, gaano kadalas ka dapat pumunta sa driver license office para sa vision exam at bagong litrato?","o":["Kahit isang beses bawat 4 na taon","Kahit isang beses bawat 8 taon","Kahit isang beses bawat 12 taon","Kahit isang beses bawat 16 na taon"],"h1":"Doble ito ng isang license period na walong taon.","h2":"Sa Texas, dapat kang pumunta sa driver license office kahit isang beses bawat 16 na taon para sa vision exam at para i-update ang iyong litrato, pirma at fingerprint.","p":"Tama. Isang beses bawat 16 na taon, nang personal."},"ar":{"q":"في Texas، حتى لو كنت تستطيع التجديد عبر الإنترنت، كم مرة يجب أن تذهب إلى مكتب رخص القيادة لفحص النظر وصورة جديدة؟","o":["مرة واحدة على الأقل كل 4 سنوات","مرة واحدة على الأقل كل 8 سنوات","مرة واحدة على الأقل كل 12 سنة","مرة واحدة على الأقل كل 16 سنة"],"h1":"هي ضعف مدة رخصة واحدة من ثماني سنوات.","h2":"في Texas يجب أن تذهب إلى مكتب رخص القيادة مرة واحدة على الأقل كل 16 سنة لفحص النظر ولتحديث صورتك وتوقيعك وبصمات أصابعك.","p":"صحيح. مرة كل 16 سنة، بنفسك."},"ref":{"doc":"TX","page":10}},{"id":"tx-034","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what fine can a driver get for a first conviction of driving without a license?","o":["Up to $50","Up to $200","Up to $1,000","Up to $4,000"],"h1":"A second conviction within one year carries a fine of $25 to the same top amount.","h2":"In Texas a first conviction for driving without a license brings a fine of up to $200.","p":"Right. The fine can be up to $200."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por una primera condena por manejar sin licencia?","o":["Hasta $50","Hasta $200","Hasta $1,000","Hasta $4,000"],"h1":"Una segunda condena en un año trae una multa de $25 hasta la misma cantidad máxima.","h2":"En Texas una primera condena por manejar sin licencia trae una multa de hasta $200.","p":"Correcto. La multa puede ser de hasta $200."},"zh":{"q":"在 Texas，司机第一次因无照驾驶被定罪，可能被罚多少钱？","o":["最多 $50","最多 $200","最多 $1,000","最多 $4,000"],"h1":"一年内第二次定罪，罚款是 $25 到同样的最高金额。","h2":"在 Texas，第一次因无照驾驶被定罪，罚款最多 $200。","p":"对。罚款最多 $200。"},"vi":{"q":"Ở Texas, tài xế có thể bị phạt bao nhiêu khi lần đầu bị kết tội lái xe không có bằng?","o":["Tối đa $50","Tối đa $200","Tối đa $1,000","Tối đa $4,000"],"h1":"Lần kết tội thứ hai trong vòng một năm bị phạt từ $25 đến cùng mức cao nhất đó.","h2":"Ở Texas, lần đầu bị kết tội lái xe không có bằng bị phạt tối đa $200.","p":"Đúng. Tiền phạt có thể lên đến $200."},"tl":{"q":"Sa Texas, anong multa ang puwedeng makuha ng driver sa unang conviction sa pagmamaneho nang walang lisensya?","o":["Hanggang $50","Hanggang $200","Hanggang $1,000","Hanggang $4,000"],"h1":"Ang ikalawang conviction sa loob ng isang taon ay may multang $25 hanggang sa parehong pinakamataas na halaga.","h2":"Sa Texas, ang unang conviction sa pagmamaneho nang walang lisensya ay may multang hanggang $200.","p":"Tama. Puwedeng umabot sa $200 ang multa."},"ar":{"q":"في Texas، ما الغرامة التي قد يحصل عليها السائق عند الإدانة الأولى بالقيادة بدون رخصة؟","o":["حتى $50","حتى $200","حتى $1,000","حتى $4,000"],"h1":"الإدانة الثانية خلال سنة واحدة عليها غرامة من $25 حتى المبلغ الأعلى نفسه.","h2":"في Texas، الإدانة الأولى بالقيادة بدون رخصة عليها غرامة تصل إلى $200.","p":"صحيح. الغرامة قد تصل إلى $200."},"ref":{"doc":"TX","page":9}},{"id":"tx-035","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what is the basic penalty for driving while your license is suspended or revoked?","o":["A fine of up to $500","A warning only","A fine of up to $25","Ten years in prison"],"h1":"In the simplest case it is a Class C misdemeanor, like many traffic tickets.","h2":"In Texas driving while your license is suspended, cancelled, denied or revoked is a Class C misdemeanor with a fine of up to $500, and the penalty is higher in some cases.","p":"Right. The basic fine is up to $500."},"es":{"q":"En Texas, ¿cuál es la sanción básica por manejar con la licencia suspendida o revocada?","o":["Una multa de hasta $500","Solo una advertencia","Una multa de hasta $25","Diez años de prisión"],"h1":"En el caso más simple es un delito menor de clase C, como muchas multas de tránsito.","h2":"En Texas manejar con la licencia suspendida, cancelada, negada o revocada es un delito menor de clase C con una multa de hasta $500, y la sanción es más alta en algunos casos.","p":"Correcto. La multa básica es de hasta $500."},"zh":{"q":"在 Texas，驾照被暂停或吊销时开车，基本处罚是什么？","o":["最多 $500 的罚款","只有警告","最多 $25 的罚款","坐牢十年"],"h1":"最简单的情况是 C 级轻罪，跟很多交通罚单一样。","h2":"在 Texas，驾照被暂停、取消、拒发或吊销时开车，是 C 级轻罪，罚款最多 $500，有些情况处罚更重。","p":"对。基本罚款最多 $500。"},"vi":{"q":"Ở Texas, hình phạt cơ bản cho việc lái xe khi bằng lái đang bị đình chỉ hoặc thu hồi là gì?","o":["Phạt tối đa $500","Chỉ bị cảnh cáo","Phạt tối đa $25","Mười năm tù"],"h1":"Trong trường hợp đơn giản nhất, đó là tội nhẹ hạng C, giống nhiều vé phạt giao thông.","h2":"Ở Texas, lái xe khi bằng lái đang bị đình chỉ, hủy, từ chối hoặc thu hồi là tội nhẹ hạng C, bị phạt tối đa $500, và hình phạt nặng hơn trong một số trường hợp.","p":"Đúng. Tiền phạt cơ bản tối đa $500."},"tl":{"q":"Sa Texas, ano ang basic na parusa sa pagmamaneho habang suspendido o binawi ang lisensya mo?","o":["Multang hanggang $500","Babala lang","Multang hanggang $25","Sampung taon sa bilangguan"],"h1":"Sa pinakasimpleng kaso, Class C misdemeanor ito, gaya ng maraming traffic ticket.","h2":"Sa Texas, ang pagmamaneho habang suspendido, kinansela, tinanggihan o binawi ang lisensya mo ay Class C misdemeanor na may multang hanggang $500, at mas mabigat ang parusa sa ilang kaso.","p":"Tama. Ang basic na multa ay hanggang $500."},"ar":{"q":"في Texas، ما العقوبة الأساسية على القيادة ورخصتك موقوفة أو ملغاة؟","o":["غرامة تصل إلى $500","تحذير فقط","غرامة تصل إلى $25","عشر سنوات في السجن"],"h1":"في أبسط حالة هي جنحة من الدرجة C، مثل كثير من مخالفات المرور.","h2":"في Texas، القيادة ورخصتك موقوفة أو ملغاة أو مرفوضة أو مسحوبة جنحة من الدرجة C عليها غرامة تصل إلى $500، والعقوبة أعلى في بعض الحالات.","p":"صحيح. الغرامة الأساسية تصل إلى $500."},"ref":{"doc":"TX","page":13}},{"id":"tx-036","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, a driver age 18 or older can have the license suspended for repeated traffic violations. How many separate convictions within 12 months can lead to this?","o":["Two or more","Four or more","Ten or more","Twenty or more"],"h1":"For drivers under 18 the number is lower.","h2":"In Texas, after a hearing, DPS may suspend the license of a driver with four or more separate traffic convictions within any 12 months.","p":"Right. Four or more in 12 months."},"es":{"q":"En Texas, a un conductor de 18 años o más le pueden suspender la licencia por infracciones de tránsito repetidas. ¿Cuántas condenas separadas en 12 meses pueden causarlo?","o":["Dos o más","Cuatro o más","Diez o más","Veinte o más"],"h1":"Para los conductores menores de 18 años el número es menor.","h2":"En Texas, después de una audiencia, el DPS puede suspender la licencia de un conductor con cuatro o más condenas de tránsito separadas en cualquier periodo de 12 meses.","p":"Correcto. Cuatro o más en 12 meses."},"zh":{"q":"在 Texas，18 岁或以上的司机如果多次交通违规，驾照可能被暂停。12 个月内有多少次不同的定罪会导致这种情况？","o":["两次或更多","四次或更多","十次或更多","二十次或更多"],"h1":"对未满 18 岁的司机，这个次数更少。","h2":"在 Texas，经过听证后，DPS 可以暂停任何 12 个月内有四次或更多次不同交通定罪的司机的驾照。","p":"对。12 个月内四次或更多。"},"vi":{"q":"Ở Texas, tài xế từ 18 tuổi trở lên có thể bị đình chỉ bằng lái vì vi phạm giao thông nhiều lần. Bao nhiêu lần bị kết tội riêng biệt trong 12 tháng có thể dẫn đến việc này?","o":["Hai lần trở lên","Bốn lần trở lên","Mười lần trở lên","Hai mươi lần trở lên"],"h1":"Với tài xế dưới 18 tuổi, con số này thấp hơn.","h2":"Ở Texas, sau một phiên điều trần, DPS có thể đình chỉ bằng lái của tài xế có từ bốn lần bị kết tội giao thông riêng biệt trở lên trong bất kỳ 12 tháng nào.","p":"Đúng. Bốn lần trở lên trong 12 tháng."},"tl":{"q":"Sa Texas, puwedeng masuspinde ang lisensya ng driver na 18 taong gulang pataas dahil sa paulit-ulit na traffic violation. Ilang hiwalay na conviction sa loob ng 12 buwan ang puwedeng magdulot nito?","o":["Dalawa o higit pa","Apat o higit pa","Sampu o higit pa","Dalawampu o higit pa"],"h1":"Para sa mga driver na wala pang 18, mas mababa ang bilang.","h2":"Sa Texas, pagkatapos ng hearing, puwedeng suspindihin ng DPS ang lisensya ng driver na may apat o higit pang hiwalay na traffic conviction sa loob ng kahit anong 12 buwan.","p":"Tama. Apat o higit pa sa loob ng 12 buwan."},"ar":{"q":"في Texas، قد تُوقَف رخصة السائق الذي عمره 18 سنة أو أكثر بسبب مخالفات مرور متكرّرة. كم إدانة منفصلة خلال 12 شهرًا قد تؤدّي إلى ذلك؟","o":["اثنتان أو أكثر","أربع أو أكثر","عشر أو أكثر","عشرون أو أكثر"],"h1":"للسائقين الذين عمرهم أقل من 18 سنة يكون العدد أقل.","h2":"في Texas، بعد جلسة استماع، يجوز لـ DPS أن توقف رخصة السائق الذي عليه أربع إدانات مرور منفصلة أو أكثر خلال أي 12 شهرًا.","p":"صحيح. أربع أو أكثر خلال 12 شهرًا."},"ref":{"doc":"TX","page":11}},{"id":"tx-037","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, an adult driver refuses a breath or blood test for the first time. How long is the license suspended?","o":["30 days","90 days","180 days","5 years"],"h1":"It is longer than the suspension for failing the test.","h2":"In Texas an adult who refuses a breath or blood test has the license suspended for 180 days, and up to 730 days for a later refusal.","p":"Right. A first refusal means 180 days."},"es":{"q":"En Texas, un conductor adulto se niega por primera vez a una prueba de aliento o de sangre. ¿Por cuánto tiempo le suspenden la licencia?","o":["30 días","90 días","180 días","5 años"],"h1":"Es más tiempo que la suspensión por no pasar la prueba.","h2":"En Texas a un adulto que se niega a una prueba de aliento o de sangre le suspenden la licencia por 180 días, y hasta 730 días si se niega otra vez más adelante.","p":"Correcto. La primera negativa son 180 días."},"zh":{"q":"在 Texas，一名成年司机第一次拒绝做呼气或验血测试。驾照会被暂停多久？","o":["30 天","90 天","180 天","5 年"],"h1":"它比测试不合格的暂停时间更长。","h2":"在 Texas，成年人拒绝做呼气或验血测试，驾照会被暂停 180 天，之后再拒绝最多会被暂停 730 天。","p":"对。第一次拒绝是 180 天。"},"vi":{"q":"Ở Texas, một tài xế người lớn lần đầu từ chối kiểm tra hơi thở hoặc thử máu. Bằng lái bị đình chỉ bao lâu?","o":["30 ngày","90 ngày","180 ngày","5 năm"],"h1":"Thời gian này dài hơn mức đình chỉ khi không đạt bài kiểm tra.","h2":"Ở Texas, người lớn từ chối kiểm tra hơi thở hoặc thử máu bị đình chỉ bằng lái 180 ngày, và đến 730 ngày nếu từ chối lần sau.","p":"Đúng. Lần từ chối đầu tiên là 180 ngày."},"tl":{"q":"Sa Texas, isang adultong driver ang tumanggi sa breath o blood test sa unang pagkakataon. Gaano katagal masususpinde ang lisensya?","o":["30 araw","90 araw","180 araw","5 taon"],"h1":"Mas matagal ito kaysa sa suspension kapag bumagsak ka sa test.","h2":"Sa Texas, ang adultong tumanggi sa breath o blood test ay masususpinde ang lisensya nang 180 araw, at hanggang 730 araw kapag tumanggi ulit sa susunod.","p":"Tama. Ang unang pagtanggi ay 180 araw."},"ar":{"q":"في Texas، يرفض سائق بالغ لأول مرة فحص التنفّس أو فحص الدم. كم مدة إيقاف الرخصة؟","o":["30 يومًا","90 يومًا","180 يومًا","5 سنوات"],"h1":"هي أطول من الإيقاف بسبب الرسوب في الفحص.","h2":"في Texas، البالغ الذي يرفض فحص التنفّس أو فحص الدم تُوقَف رخصته 180 يومًا، وحتى 730 يومًا إذا رفض مرة أخرى لاحقًا.","p":"صحيح. الرفض الأول يعني 180 يومًا."},"ref":{"doc":"TX","page":58}},{"id":"tx-038","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, what is the highest fine for an adult's first DWI offense when the blood alcohol level is under 0.15?","o":["$200","$500","$1,000","$2,000"],"h1":"It also comes with 72 hours to 180 days in jail.","h2":"In Texas a first DWI offense by an adult can bring a fine of up to $2,000, plus jail time and a license suspension; with a blood alcohol level of 0.15 or more, the fine can reach $4,000.","p":"Right. The fine can be up to $2,000."},"es":{"q":"En Texas, ¿cuál es la multa más alta para un adulto por una primera infracción de DWI (manejar intoxicado) cuando el nivel de alcohol en la sangre es menor de 0.15?","o":["$200","$500","$1,000","$2,000"],"h1":"También trae de 72 horas a 180 días de cárcel.","h2":"En Texas una primera infracción de DWI de un adulto puede traer una multa de hasta $2,000, además de cárcel y suspensión de la licencia; con un nivel de alcohol de 0.15 o más, la multa puede llegar a $4,000.","p":"Correcto. La multa puede ser de hasta $2,000."},"zh":{"q":"在 Texas，成年人第一次 DWI（酒后驾驶）违法，血液酒精浓度低于 0.15 时，最高罚款是多少？","o":["$200","$500","$1,000","$2,000"],"h1":"它还会带来 72 小时到 180 天的监禁。","h2":"在 Texas，成年人第一次 DWI 违法，罚款最多 $2,000，还会坐牢和暂停驾照；如果血液酒精浓度是 0.15 或更高，罚款最多可到 $4,000。","p":"对。罚款最多 $2,000。"},"vi":{"q":"Ở Texas, mức phạt cao nhất cho người lớn vi phạm DWI (lái xe khi say) lần đầu, khi nồng độ cồn trong máu dưới 0.15, là bao nhiêu?","o":["$200","$500","$1,000","$2,000"],"h1":"Kèm theo đó là từ 72 giờ đến 180 ngày tù.","h2":"Ở Texas, người lớn vi phạm DWI lần đầu có thể bị phạt tối đa $2,000, cộng thêm tù và đình chỉ bằng lái; nếu nồng độ cồn trong máu từ 0.15 trở lên, tiền phạt có thể lên đến $4,000.","p":"Đúng. Tiền phạt có thể lên đến $2,000."},"tl":{"q":"Sa Texas, ano ang pinakamataas na multa sa unang DWI (pagmamaneho nang lasing) ng adulto kapag ang blood alcohol level ay mas mababa sa 0.15?","o":["$200","$500","$1,000","$2,000"],"h1":"May kasama rin itong 72 oras hanggang 180 araw sa kulungan.","h2":"Sa Texas, ang unang DWI ng adulto ay puwedeng may multang hanggang $2,000, kasama ang pagkakakulong at suspension ng lisensya; kapag ang blood alcohol level ay 0.15 o higit pa, puwedeng umabot sa $4,000 ang multa.","p":"Tama. Puwedeng umabot sa $2,000 ang multa."},"ar":{"q":"في Texas، ما أعلى غرامة على البالغ في أول مخالفة DWI (القيادة تحت تأثير الكحول) عندما تكون نسبة الكحول في الدم أقل من 0.15؟","o":["$200","$500","$1,000","$2,000"],"h1":"ويأتي معها أيضًا سجن من 72 ساعة إلى 180 يومًا.","h2":"في Texas، أول مخالفة DWI للبالغ قد تجلب غرامة تصل إلى $2,000، مع السجن وإيقاف الرخصة؛ وإذا كانت نسبة الكحول في الدم 0.15 أو أكثر، قد تصل الغرامة إلى $4,000.","p":"صحيح. الغرامة قد تصل إلى $2,000."},"ref":{"doc":"TX","page":58}},{"id":"tx-039","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, a driver under 21 takes a breath test that shows a small amount of alcohol, below 0.08. For a first offense, how long is the license suspended?","o":["7 days","60 days","2 years","It is not suspended"],"h1":"A second offense doubles the time.","h2":"In Texas a driver under 21 whose test shows any detectable alcohol loses the license for 60 days the first time, 120 days the second time.","p":"Right. The first suspension is 60 days."},"es":{"q":"En Texas, un conductor menor de 21 años hace una prueba de aliento que muestra un poco de alcohol, menos de 0.08. Si es la primera vez, ¿por cuánto tiempo le suspenden la licencia?","o":["7 días","60 días","2 años","No se la suspenden"],"h1":"La segunda vez el tiempo se duplica.","h2":"En Texas a un conductor menor de 21 años cuya prueba muestra cualquier cantidad de alcohol le suspenden la licencia por 60 días la primera vez y 120 días la segunda vez.","p":"Correcto. La primera suspensión es de 60 días."},"zh":{"q":"在 Texas，一名未满 21 岁的司机做呼气测试，显示有少量酒精，低于 0.08。如果是第一次违法，驾照会被暂停多久？","o":["7 天","60 天","2 年","不会被暂停"],"h1":"第二次违法，时间会加倍。","h2":"在 Texas，未满 21 岁的司机只要测试显示有任何能检测到的酒精，第一次会被暂停驾照 60 天，第二次 120 天。","p":"对。第一次暂停 60 天。"},"vi":{"q":"Ở Texas, một tài xế dưới 21 tuổi làm kiểm tra hơi thở và kết quả cho thấy có một ít rượu bia, dưới 0.08. Nếu là lần vi phạm đầu tiên, bằng lái bị đình chỉ bao lâu?","o":["7 ngày","60 ngày","2 năm","Không bị đình chỉ"],"h1":"Lần vi phạm thứ hai thì thời gian tăng gấp đôi.","h2":"Ở Texas, tài xế dưới 21 tuổi có kết quả kiểm tra cho thấy bất kỳ lượng rượu bia nào đo được sẽ mất bằng lái 60 ngày lần đầu, 120 ngày lần thứ hai.","p":"Đúng. Lần đình chỉ đầu tiên là 60 ngày."},"tl":{"q":"Sa Texas, ang driver na wala pang 21 ay kumuha ng breath test na nagpakita ng kaunting alak, mas mababa sa 0.08. Kung unang paglabag ito, gaano katagal masususpinde ang lisensya?","o":["7 araw","60 araw","2 taon","Hindi ito masususpinde"],"h1":"Sa ikalawang paglabag, nadodoble ang tagal.","h2":"Sa Texas, ang driver na wala pang 21 na ang test ay nagpakita ng kahit anong alak na kayang ma-detect ay mawawalan ng lisensya nang 60 araw sa unang beses, at 120 araw sa ikalawang beses.","p":"Tama. Ang unang suspension ay 60 araw."},"ar":{"q":"في Texas، سائق عمره أقل من 21 سنة أجرى فحص التنفّس فأظهر كمية صغيرة من الكحول، أقل من 0.08. إذا كانت هذه المخالفة الأولى، كم مدة إيقاف الرخصة؟","o":["7 أيام","60 يومًا","سنتان (2)","لا تُوقَف الرخصة"],"h1":"في المخالفة الثانية تتضاعف المدة.","h2":"في Texas، السائق الذي عمره أقل من 21 سنة ويُظهر فحصه أي كمية من الكحول يمكن اكتشافها تُوقَف رخصته 60 يومًا في المرة الأولى، و120 يومًا في المرة الثانية.","p":"صحيح. الإيقاف الأول 60 يومًا."},"ref":{"doc":"TX","page":57}},{"id":"tx-040","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, a driver fails to yield the right-of-way and causes bodily injury to another person. What fine can the driver get?","o":["$500 to $2,000","$25 to $50","$50 to $100","$10,000 to $20,000"],"h1":"If the injury is serious, the fine goes up to as much as $4,000.","h2":"In Texas failing to yield the right-of-way and causing bodily injury brings a fine of $500 to $2,000.","p":"Right. The fine is $500 to $2,000."},"es":{"q":"En Texas, un conductor no cede el paso y causa una lesión a otra persona. ¿Qué multa puede recibir?","o":["De $500 a $2,000","De $25 a $50","De $50 a $100","De $10,000 a $20,000"],"h1":"Si la lesión es grave, la multa sube hasta $4,000.","h2":"En Texas no ceder el paso y causar una lesión a otra persona trae una multa de $500 a $2,000.","p":"Correcto. La multa es de $500 a $2,000."},"zh":{"q":"在 Texas，一名司机没有让行，造成别人身体受伤。这名司机可能被罚多少钱？","o":["$500 到 $2,000","$25 到 $50","$50 到 $100","$10,000 到 $20,000"],"h1":"如果伤得很重，罚款最高可到 $4,000。","h2":"在 Texas，没有让行并造成别人身体受伤，罚款是 $500 到 $2,000。","p":"对。罚款是 $500 到 $2,000。"},"vi":{"q":"Ở Texas, một tài xế không nhường đường và gây thương tích cho người khác. Tài xế có thể bị phạt bao nhiêu?","o":["Từ $500 đến $2,000","Từ $25 đến $50","Từ $50 đến $100","Từ $10,000 đến $20,000"],"h1":"Nếu thương tích nghiêm trọng, tiền phạt tăng lên đến $4,000.","h2":"Ở Texas, không nhường đường và gây thương tích cho người khác bị phạt từ $500 đến $2,000.","p":"Đúng. Tiền phạt từ $500 đến $2,000."},"tl":{"q":"Sa Texas, hindi nagbigay-daan ang isang driver at nakasakit ng ibang tao. Anong multa ang puwede niyang makuha?","o":["$500 hanggang $2,000","$25 hanggang $50","$50 hanggang $100","$10,000 hanggang $20,000"],"h1":"Kung malubha ang pinsala, tumataas ang multa hanggang $4,000.","h2":"Sa Texas, ang hindi pagbibigay ng right-of-way na nakasakit ng ibang tao ay may multang $500 hanggang $2,000.","p":"Tama. Ang multa ay $500 hanggang $2,000."},"ar":{"q":"في Texas، سائق لم يُعطِ حق الأولوية وتسبّب في إصابة جسدية لشخص آخر. ما الغرامة التي قد يحصل عليها؟","o":["$500 إلى $2,000","$25 إلى $50","$50 إلى $100","$10,000 إلى $20,000"],"h1":"إذا كانت الإصابة خطيرة، ترتفع الغرامة حتى $4,000.","h2":"في Texas، عدم إعطاء حق الأولوية مع التسبّب في إصابة جسدية لشخص آخر عليه غرامة من $500 إلى $2,000.","p":"صحيح. الغرامة من $500 إلى $2,000."},"ref":{"doc":"TX","page":20}},{"id":"tx-041","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you must stop at a railroad crossing when an approaching train is about how close?","o":["Within 100 feet","Within 500 feet","Within 1,500 feet","Within 5,000 feet"],"h1":"The train will sound a warning at about this distance.","h2":"In Texas you must stop at a railroad crossing when an approaching train is within about 1,500 feet of it.","p":"Right. About 1,500 feet means stop."},"es":{"q":"En Texas, ¿a qué distancia, más o menos, debe estar un tren que se acerca para que usted tenga que detenerse en un cruce de ferrocarril?","o":["A menos de 100 pies","A menos de 500 pies","A menos de 1,500 pies","A menos de 5,000 pies"],"h1":"El tren hace sonar un aviso más o menos a esa distancia.","h2":"En Texas usted debe detenerse en un cruce de ferrocarril cuando un tren que se acerca está a unos 1,500 pies o menos.","p":"Correcto. A unos 1,500 pies, deténgase."},"zh":{"q":"在 Texas，开过来的火车大约离多近时，你必须在铁路道口停车？","o":["100 英尺以内","500 英尺以内","1,500 英尺以内","5,000 英尺以内"],"h1":"火车大约在这个距离会鸣笛警告。","h2":"在 Texas，开过来的火车离铁路道口大约 1,500 英尺以内时，你必须停车。","p":"对。大约 1,500 英尺就要停车。"},"vi":{"q":"Ở Texas, bạn phải dừng ở chỗ giao với đường sắt khi tàu hỏa đang đến cách khoảng bao xa?","o":["Trong vòng 100 feet","Trong vòng 500 feet","Trong vòng 1,500 feet","Trong vòng 5,000 feet"],"h1":"Tàu sẽ kéo còi cảnh báo ở khoảng cách này.","h2":"Ở Texas, bạn phải dừng ở chỗ giao với đường sắt khi tàu đang đến cách đó khoảng 1,500 feet trở lại.","p":"Đúng. Khoảng 1,500 feet là phải dừng."},"tl":{"q":"Sa Texas, dapat kang huminto sa railroad crossing kapag ang paparating na tren ay mga gaano kalapit?","o":["Sa loob ng 100 talampakan","Sa loob ng 500 talampakan","Sa loob ng 1,500 talampakan","Sa loob ng 5,000 talampakan"],"h1":"Magpapatunog ng babala ang tren sa mga ganitong layo.","h2":"Sa Texas, dapat kang huminto sa railroad crossing kapag ang paparating na tren ay nasa loob ng mga 1,500 talampakan mula rito.","p":"Tama. Mga 1,500 talampakan, huminto ka."},"ar":{"q":"في Texas، يجب أن تتوقف عند تقاطع سكة الحديد عندما يكون القطار القادم على بُعد كم تقريبًا؟","o":["ضمن 100 قدم","ضمن 500 قدم","ضمن 1,500 قدم","ضمن 5,000 قدم"],"h1":"يُطلق القطار صوت تحذير على هذه المسافة تقريبًا.","h2":"في Texas يجب أن تتوقف عند تقاطع سكة الحديد عندما يكون القطار القادم على بُعد 1,500 قدم تقريبًا أو أقل.","p":"صحيح. نحو 1,500 قدم يعني أن تتوقف."},"ref":{"doc":"TX","page":21}},{"id":"tx-042","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, what fine can a driver get for breaking the law at a railroad crossing?","o":["$1 to $10","$10 to $25","$1,000 to $5,000","$50 to $200"],"h1":"It is a modest fine, in the same range as many traffic tickets.","h2":"In Texas a driver who does not obey the law at a railroad crossing can be fined $50 to $200.","p":"Right. The fine is $50 to $200."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por no cumplir la ley en un cruce de ferrocarril?","o":["De $1 a $10","De $10 a $25","De $1,000 a $5,000","De $50 a $200"],"h1":"Es una multa moderada, parecida a muchas multas de tránsito.","h2":"En Texas un conductor que no cumple la ley en un cruce de ferrocarril puede recibir una multa de $50 a $200.","p":"Correcto. La multa es de $50 a $200."},"zh":{"q":"在 Texas，司机在铁路道口违法，可能被罚多少钱？","o":["$1 到 $10","$10 到 $25","$1,000 到 $5,000","$50 到 $200"],"h1":"这是不算高的罚款，跟很多交通罚单差不多。","h2":"在 Texas，在铁路道口不遵守法律的司机，可能被罚 $50 到 $200。","p":"对。罚款是 $50 到 $200。"},"vi":{"q":"Ở Texas, tài xế có thể bị phạt bao nhiêu khi vi phạm luật ở chỗ giao với đường sắt?","o":["Từ $1 đến $10","Từ $10 đến $25","Từ $1,000 đến $5,000","Từ $50 đến $200"],"h1":"Đó là mức phạt vừa phải, giống nhiều vé phạt giao thông.","h2":"Ở Texas, tài xế không tuân theo luật ở chỗ giao với đường sắt có thể bị phạt từ $50 đến $200.","p":"Đúng. Tiền phạt từ $50 đến $200."},"tl":{"q":"Sa Texas, anong multa ang puwedeng makuha ng driver sa paglabag sa batas sa railroad crossing?","o":["$1 hanggang $10","$10 hanggang $25","$1,000 hanggang $5,000","$50 hanggang $200"],"h1":"Katamtaman lang ang multang ito, kapareho ng maraming traffic ticket.","h2":"Sa Texas, ang driver na hindi sumusunod sa batas sa railroad crossing ay puwedeng multahan ng $50 hanggang $200.","p":"Tama. Ang multa ay $50 hanggang $200."},"ar":{"q":"في Texas، ما الغرامة التي قد يحصل عليها السائق لمخالفة القانون عند تقاطع سكة الحديد؟","o":["$1 إلى $10","$10 إلى $25","$1,000 إلى $5,000","$50 إلى $200"],"h1":"هي غرامة متوسطة، في نفس مستوى كثير من مخالفات المرور.","h2":"في Texas، السائق الذي لا يلتزم بالقانون عند تقاطع سكة الحديد قد يُغرَّم من $50 إلى $200.","p":"صحيح. الغرامة من $50 إلى $200."},"ref":{"doc":"TX","page":22}},{"id":"tx-043","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, a barricade is placed where water covers the road. What can happen if you drive around it?","o":["A fine of up to $2,000, up to 180 days in jail, or both","A warning only","A $25 fine","A fine of $1 to $200 only"],"h1":"Around flood water, this is treated much more seriously than an ordinary sign violation.","h2":"In Texas driving around a barricade or warning sign placed where water covers the road is a Class B misdemeanor, with a fine of up to $2,000, up to 180 days in jail, or both.","p":"Right. It can mean up to $2,000 and jail."},"es":{"q":"En Texas, hay una barrera donde el agua cubre la calle. ¿Qué puede pasar si usted maneja alrededor de ella?","o":["Una multa de hasta $2,000, hasta 180 días de cárcel, o ambas","Solo una advertencia","Una multa de $25","Solo una multa de $1 a $200"],"h1":"Cuando hay agua de inundación, esto es mucho más grave que no cumplir una señal común.","h2":"En Texas manejar alrededor de una barrera o señal de advertencia puesta donde el agua cubre la calle es un delito menor de clase B, con una multa de hasta $2,000, hasta 180 días de cárcel, o ambas.","p":"Correcto. Puede costar hasta $2,000 y cárcel."},"zh":{"q":"在 Texas，水淹过路面的地方放了路障。如果你绕过路障开车，可能会怎样？","o":["最多 $2,000 罚款、最多 180 天监禁，或两者都有","只有警告","$25 罚款","只有 $1 到 $200 的罚款"],"h1":"在洪水附近，这比一般的违反标志严重得多。","h2":"在 Texas，绕过放在水淹路面处的路障或警告标志开车，是 B 级轻罪，罚款最多 $2,000、监禁最多 180 天，或两者都有。","p":"对。可能罚最多 $2,000，还可能坐牢。"},"vi":{"q":"Ở Texas, có rào chắn đặt ở chỗ nước ngập mặt đường. Điều gì có thể xảy ra nếu bạn lái vòng qua nó?","o":["Phạt tối đa $2,000, tù tối đa 180 ngày, hoặc cả hai","Chỉ bị cảnh cáo","Phạt $25","Chỉ phạt từ $1 đến $200"],"h1":"Khi có nước lũ, việc này bị xem nặng hơn nhiều so với vi phạm biển báo thông thường.","h2":"Ở Texas, lái vòng qua rào chắn hoặc biển cảnh báo đặt ở chỗ nước ngập mặt đường là tội nhẹ hạng B, bị phạt tối đa $2,000, tù tối đa 180 ngày, hoặc cả hai.","p":"Đúng. Có thể bị phạt đến $2,000 và ngồi tù."},"tl":{"q":"Sa Texas, may barikada sa lugar kung saan may tubig na tumatakip sa daan. Ano ang puwedeng mangyari kung iikutan mo ito?","o":["Multang hanggang $2,000, hanggang 180 araw sa kulungan, o pareho","Babala lang","Multang $25","Multang $1 hanggang $200 lang"],"h1":"Kapag may baha, mas seryoso ito kaysa sa karaniwang paglabag sa karatula.","h2":"Sa Texas, ang pagmamaneho paikot sa barikada o warning sign na nakalagay kung saan may tubig na tumatakip sa daan ay Class B misdemeanor, na may multang hanggang $2,000, hanggang 180 araw sa kulungan, o pareho.","p":"Tama. Puwede itong umabot sa $2,000 at kulungan."},"ar":{"q":"في Texas، وُضع حاجز في مكان تغطّي فيه المياه الطريق. ماذا قد يحدث إذا قُدت حوله؟","o":["غرامة تصل إلى $2,000، أو سجن حتى 180 يومًا، أو الاثنان معًا","تحذير فقط","غرامة $25","غرامة من $1 إلى $200 فقط"],"h1":"عند مياه الفيضانات، يُعامَل هذا بجدية أكبر بكثير من مخالفة لافتة عادية.","h2":"في Texas، القيادة حول حاجز أو لافتة تحذير موضوعة حيث تغطّي المياه الطريق جنحة من الدرجة B، عليها غرامة تصل إلى $2,000، أو سجن حتى 180 يومًا، أو الاثنان معًا.","p":"صحيح. قد تعني حتى $2,000 والسجن."},"ref":{"doc":"TX","page":37}},{"id":"tx-044","scope":"TX","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Texas, what fine can you get for a first offense of parking illegally in a space for people with disabilities?","o":["$25 to $50","$100 to $200","$500 to $750","$5,000 to $10,000"],"h1":"The fine grows with more offenses, up to $1,250.","h2":"In Texas parking illegally in a disabled parking space brings a fine of $500 to $750 for a first offense.","p":"Right. The first fine is $500 to $750."},"es":{"q":"En Texas, ¿qué multa puede recibir por una primera vez que estaciona sin permiso en un espacio para personas con discapacidad?","o":["De $25 a $50","De $100 a $200","De $500 a $750","De $5,000 a $10,000"],"h1":"La multa sube con más infracciones, hasta $1,250.","h2":"En Texas estacionar sin permiso en un espacio para personas con discapacidad trae una multa de $500 a $750 la primera vez.","p":"Correcto. La primera multa es de $500 a $750."},"zh":{"q":"在 Texas，第一次违法停在残障人士车位，可能被罚多少钱？","o":["$25 到 $50","$100 到 $200","$500 到 $750","$5,000 到 $10,000"],"h1":"违法次数越多罚款越高，最高到 $1,250。","h2":"在 Texas，第一次违法停在残障人士车位，罚款是 $500 到 $750。","p":"对。第一次罚 $500 到 $750。"},"vi":{"q":"Ở Texas, lần đầu đậu xe trái phép ở chỗ dành cho người khuyết tật có thể bị phạt bao nhiêu?","o":["Từ $25 đến $50","Từ $100 đến $200","Từ $500 đến $750","Từ $5,000 đến $10,000"],"h1":"Tiền phạt tăng theo số lần vi phạm, lên đến $1,250.","h2":"Ở Texas, đậu xe trái phép ở chỗ dành cho người khuyết tật bị phạt từ $500 đến $750 cho lần đầu.","p":"Đúng. Lần phạt đầu tiên từ $500 đến $750."},"tl":{"q":"Sa Texas, anong multa ang puwede mong makuha sa unang beses na ilegal kang pumarada sa puwesto para sa mga taong may kapansanan?","o":["$25 hanggang $50","$100 hanggang $200","$500 hanggang $750","$5,000 hanggang $10,000"],"h1":"Tumataas ang multa sa bawat paglabag, hanggang $1,250.","h2":"Sa Texas, ang ilegal na pagparada sa puwesto para sa may kapansanan ay may multang $500 hanggang $750 sa unang paglabag.","p":"Tama. Ang unang multa ay $500 hanggang $750."},"ar":{"q":"في Texas، ما الغرامة على أول مرة تركن فيها بشكل غير قانوني في مكان مخصّص للأشخاص ذوي الإعاقة؟","o":["$25 إلى $50","$100 إلى $200","$500 إلى $750","$5,000 إلى $10,000"],"h1":"تزيد الغرامة مع تكرار المخالفة، حتى $1,250.","h2":"في Texas، الركن بشكل غير قانوني في مكان مخصّص لذوي الإعاقة عليه غرامة من $500 إلى $750 في المخالفة الأولى.","p":"صحيح. الغرامة الأولى من $500 إلى $750."},"ref":{"doc":"TX","page":42}},{"id":"tx-045","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, when you parallel park next to a curb, what is the farthest your car may be from it?","o":["12 inches","18 inches","24 inches","36 inches"],"h1":"It is a foot and a half.","h2":"In Texas when you parallel park, your car may not be more than 18 inches from the curb or edge of the road.","p":"Right. No more than 18 inches."},"es":{"q":"En Texas, cuando se estaciona en paralelo junto a la acera, ¿a qué distancia máxima puede quedar su carro de ella?","o":["12 pulgadas","18 pulgadas","24 pulgadas","36 pulgadas"],"h1":"Es un pie y medio.","h2":"En Texas cuando se estaciona en paralelo, su carro no puede quedar a más de 18 pulgadas de la acera o del borde de la calle.","p":"Correcto. No más de 18 pulgadas."},"zh":{"q":"在 Texas，你靠着路缘平行停车时，车离路缘最远可以多远？","o":["12 英寸","18 英寸","24 英寸","36 英寸"],"h1":"它是一英尺半。","h2":"在 Texas，平行停车时，你的车离路缘或路边不可以超过 18 英寸。","p":"对。不超过 18 英寸。"},"vi":{"q":"Ở Texas, khi bạn đậu xe song song cạnh lề đường, xe của bạn được cách lề xa nhất là bao nhiêu?","o":["12 inch","18 inch","24 inch","36 inch"],"h1":"Đó là một foot rưỡi.","h2":"Ở Texas, khi đậu xe song song, xe của bạn không được cách lề hoặc mép đường quá 18 inch.","p":"Đúng. Không quá 18 inch."},"tl":{"q":"Sa Texas, kapag nag-parallel park ka sa tabi ng curb, ano ang pinakamalayong puwedeng layo ng kotse mo rito?","o":["12 pulgada","18 pulgada","24 pulgada","36 pulgada"],"h1":"Isa't kalahating talampakan ito.","h2":"Sa Texas, kapag nag-parallel park ka, hindi puwedeng lumayo nang higit sa 18 pulgada ang kotse mo mula sa curb o gilid ng daan.","p":"Tama. Hindi hihigit sa 18 pulgada."},"ar":{"q":"في Texas، عندما تركن بشكل موازٍ بجانب الرصيف، ما أبعد مسافة يجوز أن تكون سيارتك عنه؟","o":["12 بوصة","18 بوصة","24 بوصة","36 بوصة"],"h1":"هي قدم ونصف.","h2":"في Texas، عندما تركن بشكل موازٍ، يجب ألّا تكون سيارتك على بُعد أكثر من 18 بوصة من الرصيف أو حافة الطريق.","p":"صحيح. ليس أكثر من 18 بوصة."},"ref":{"doc":"TX","page":44}},{"id":"tx-046","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a child under 8 must ride in a child car seat unless the child is taller than what?","o":["4 feet 9 inches","3 feet","4 feet","5 feet 6 inches"],"h1":"It is a little under five feet.","h2":"In Texas a child under 8 must be secured in a child car seat unless the child is taller than 4 feet 9 inches.","p":"Right. Taller than 4 feet 9 inches."},"es":{"q":"En Texas, ¿qué estatura debe pasar un niño menor de 8 años para no tener que ir en un asiento de seguridad para niños?","o":["4 pies 9 pulgadas","3 pies","4 pies","5 pies 6 pulgadas"],"h1":"Es un poco menos de cinco pies.","h2":"En Texas un niño menor de 8 años debe ir sujeto en un asiento de seguridad para niños, a menos que mida más de 4 pies 9 pulgadas.","p":"Correcto. Más de 4 pies 9 pulgadas."},"zh":{"q":"在 Texas，未满 8 岁的孩子必须坐儿童安全座椅，除非孩子的身高超过多少？","o":["4 英尺 9 英寸","3 英尺","4 英尺","5 英尺 6 英寸"],"h1":"它比五英尺少一点。","h2":"在 Texas，未满 8 岁的孩子必须固定在儿童安全座椅里，除非孩子身高超过 4 英尺 9 英寸。","p":"对。身高超过 4 英尺 9 英寸。"},"vi":{"q":"Ở Texas, trẻ dưới 8 tuổi phải ngồi ghế an toàn cho trẻ em, trừ khi trẻ cao hơn bao nhiêu?","o":["4 feet 9 inches","3 feet","4 feet","5 feet 6 inches"],"h1":"Thấp hơn năm feet một chút.","h2":"Ở Texas, trẻ dưới 8 tuổi phải được giữ chặt trong ghế an toàn cho trẻ em, trừ khi trẻ cao hơn 4 feet 9 inches.","p":"Đúng. Cao hơn 4 feet 9 inches."},"tl":{"q":"Sa Texas, ang batang wala pang 8 ay dapat nakaupo sa child car seat maliban kung mas matangkad ang bata sa gaano?","o":["4 feet 9 inches","3 feet","4 feet","5 feet 6 inches"],"h1":"Medyo kulang ito sa limang talampakan.","h2":"Sa Texas, ang batang wala pang 8 ay dapat nakakabit sa child car seat maliban kung mas matangkad ito sa 4 feet 9 inches.","p":"Tama. Mas matangkad sa 4 feet 9 inches."},"ar":{"q":"في Texas، يجب أن يجلس الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال، إلا إذا كان طوله أكثر من كم؟","o":["4 أقدام و9 بوصات","3 أقدام","4 أقدام","5 أقدام و6 بوصات"],"h1":"هو أقل قليلًا من خمسة أقدام.","h2":"في Texas يجب تثبيت الطفل الذي عمره أقل من 8 سنوات في مقعد أمان للأطفال، إلا إذا كان طوله أكثر من 4 أقدام و9 بوصات.","p":"صحيح. أطول من 4 أقدام و9 بوصات."},"ref":{"doc":"TX","page":64}},{"id":"tx-047","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, how much following distance should you leave behind a motorcycle?","o":["1 second","2 seconds","3 seconds","At least 4 to 6 seconds"],"h1":"Leave more room than you would behind a car, because the slightest contact can make the rider fall.","h2":"In Texas you should stay at least 4 to 6 seconds behind a motorcycle, so the rider has time to move or stop in an emergency.","p":"Right. Stay 4 to 6 seconds back."},"es":{"q":"En Texas, ¿cuánta distancia debe dejar cuando va detrás de una motocicleta?","o":["1 segundo","2 segundos","3 segundos","Por lo menos de 4 a 6 segundos"],"h1":"Deje más espacio que detrás de un carro, porque el menor contacto puede hacer caer al motociclista.","h2":"En Texas usted debe quedarse por lo menos de 4 a 6 segundos detrás de una motocicleta, para que el motociclista tenga tiempo de moverse o detenerse en una emergencia.","p":"Correcto. Quédese de 4 a 6 segundos atrás."},"zh":{"q":"在 Texas，跟在摩托车后面时，你应该留多少跟车距离？","o":["1 秒","2 秒","3 秒","至少 4 到 6 秒"],"h1":"要比跟在汽车后面留更多空间，因为最轻的碰触也可能让骑车人摔倒。","h2":"在 Texas，你应该在摩托车后面保持至少 4 到 6 秒的距离，让骑车人在紧急情况下有时间避开或停下。","p":"对。保持 4 到 6 秒的距离。"},"vi":{"q":"Ở Texas, bạn nên giữ khoảng cách bao nhiêu khi chạy sau xe mô tô?","o":["1 giây","2 giây","3 giây","Ít nhất 4 đến 6 giây"],"h1":"Hãy chừa nhiều chỗ hơn so với khi chạy sau xe hơi, vì chỉ một va chạm nhẹ nhất cũng có thể làm người lái mô tô ngã.","h2":"Ở Texas, bạn nên giữ khoảng cách ít nhất 4 đến 6 giây phía sau xe mô tô, để người lái có thời gian tránh hoặc dừng lại khi khẩn cấp.","p":"Đúng. Giữ khoảng cách 4 đến 6 giây."},"tl":{"q":"Sa Texas, gaano kalaking following distance ang dapat mong iwan sa likod ng motorsiklo?","o":["1 segundo","2 segundo","3 segundo","Hindi bababa sa 4 hanggang 6 na segundo"],"h1":"Mag-iwan ng mas malaking espasyo kaysa sa likod ng kotse, dahil ang pinakamaliit na banggaan ay puwedeng magpabagsak sa rider.","h2":"Sa Texas, dapat kang manatili nang hindi bababa sa 4 hanggang 6 na segundo sa likod ng motorsiklo, para may oras ang rider na umiwas o huminto kapag may emergency.","p":"Tama. Manatili nang 4 hanggang 6 na segundo sa likod."},"ar":{"q":"في Texas، ما مسافة المتابعة التي يجب أن تتركها خلف دراجة نارية؟","o":["ثانية واحدة (1)","ثانيتان (2)","3 ثوانٍ","من 4 إلى 6 ثوانٍ على الأقل"],"h1":"اترك مسافة أكبر مما تتركه خلف سيارة، لأن أخفّ لمسة قد تُسقط سائق الدراجة.","h2":"في Texas يجب أن تبقى من 4 إلى 6 ثوانٍ على الأقل خلف الدراجة النارية، حتى يكون عند سائقها وقت ليبتعد أو يتوقف في حالة طوارئ.","p":"صحيح. ابقَ من 4 إلى 6 ثوانٍ خلفها."},"ref":{"doc":"TX","page":53}},{"id":"tx-048","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, from when to when must your headlights be on at night?","o":["From sunset to sunrise","From 30 minutes after sunset to 30 minutes before sunrise","From 1 hour after sunset to 1 hour before sunrise","Only when there are no streetlights"],"h1":"There is a half-hour of twilight at each end.","h2":"In Texas you must use your headlights from 30 minutes after sunset until 30 minutes before sunrise, and any time you cannot see people or vehicles clearly for 1,000 feet.","p":"Right. 30 minutes after sunset to 30 minutes before sunrise."},"es":{"q":"En Texas, ¿desde cuándo y hasta cuándo debe tener encendidas las luces delanteras de noche?","o":["Desde la puesta del sol hasta la salida del sol","Desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol","Desde 1 hora después de la puesta del sol hasta 1 hora antes de la salida del sol","Solo cuando no hay luces en la calle"],"h1":"Hay media hora de crepúsculo en cada extremo.","h2":"En Texas usted debe usar las luces delanteras desde 30 minutos después de la puesta del sol hasta 30 minutos antes de la salida del sol, y siempre que no pueda ver bien a personas o vehículos a 1,000 pies.","p":"Correcto. Desde 30 minutos después de la puesta hasta 30 minutos antes de la salida del sol."},"zh":{"q":"在 Texas，晚上从什么时候到什么时候必须开前大灯？","o":["从日落到日出","从日落后 30 分钟到日出前 30 分钟","从日落后 1 小时到日出前 1 小时","只有没有路灯的时候"],"h1":"两头各有半小时的黄昏。","h2":"在 Texas，从日落后 30 分钟到日出前 30 分钟，你必须开前大灯；只要你看不清 1,000 英尺内的人或车辆，任何时候也都要开。","p":"对。从日落后 30 分钟到日出前 30 分钟。"},"vi":{"q":"Ở Texas, ban đêm bạn phải bật đèn pha từ lúc nào đến lúc nào?","o":["Từ lúc mặt trời lặn đến lúc mặt trời mọc","Từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc","Từ 1 giờ sau khi mặt trời lặn đến 1 giờ trước khi mặt trời mọc","Chỉ khi không có đèn đường"],"h1":"Mỗi đầu có nửa giờ chạng vạng.","h2":"Ở Texas, bạn phải bật đèn pha từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc, và bất cứ lúc nào bạn không thấy rõ người hoặc xe trong vòng 1,000 feet.","p":"Đúng. Từ 30 phút sau khi mặt trời lặn đến 30 phút trước khi mặt trời mọc."},"tl":{"q":"Sa Texas, mula kailan hanggang kailan dapat nakabukas ang headlights mo sa gabi?","o":["Mula paglubog hanggang pagsikat ng araw","Mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw","Mula 1 oras pagkalubog ng araw hanggang 1 oras bago sumikat ang araw","Kapag walang streetlight lang"],"h1":"May kalahating oras na takipsilim sa bawat dulo.","h2":"Sa Texas, dapat mong gamitin ang headlights mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw, at anumang oras na hindi mo malinaw na makita ang mga tao o sasakyan sa layong 1,000 talampakan.","p":"Tama. Mula 30 minuto pagkalubog ng araw hanggang 30 minuto bago sumikat ang araw."},"ar":{"q":"في Texas، من متى إلى متى يجب أن تكون أضواؤك الأمامية مضاءة في الليل؟","o":["من غروب الشمس إلى شروقها","من 30 دقيقة بعد غروب الشمس إلى 30 دقيقة قبل شروقها","من ساعة واحدة (1) بعد غروب الشمس إلى ساعة واحدة (1) قبل شروقها","فقط عندما لا توجد أضواء في الشارع"],"h1":"في كل طرف نصف ساعة من الشفق.","h2":"في Texas يجب أن تستخدم أضواءك الأمامية من 30 دقيقة بعد غروب الشمس حتى 30 دقيقة قبل شروقها، وفي أي وقت لا تستطيع فيه أن ترى الناس أو المركبات بوضوح على بُعد 1,000 قدم.","p":"صحيح. من 30 دقيقة بعد الغروب إلى 30 دقيقة قبل الشروق."},"ref":{"doc":"TX","page":47}},{"id":"tx-049","scope":"TX","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Texas, unless a sign says otherwise, what is the speed limit in an alley?","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"It is half the speed limit of a city street.","h2":"In Texas the speed limit in an alley is 15 mph unless a sign shows a different limit.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Texas, a menos que una señal diga otra cosa, ¿cuál es el límite de velocidad en un callejón?","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"Es la mitad del límite de una calle de ciudad.","h2":"En Texas el límite de velocidad en un callejón es de 15 mph, a menos que una señal muestre otro límite.","p":"Correcto. En los callejones son 15 mph."},"zh":{"q":"在 Texas，如果没有标志另外规定，小巷（alley）的限速是多少？","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"它是市区街道限速的一半。","h2":"在 Texas，小巷的限速是 15 mph，除非有标志显示不同的限速。","p":"对。小巷限速 15 mph。"},"vi":{"q":"Ở Texas, trừ khi có biển báo khác, giới hạn tốc độ trong hẻm (alley) là bao nhiêu?","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"Đó là một nửa giới hạn tốc độ của đường phố trong thành phố.","h2":"Ở Texas, giới hạn tốc độ trong hẻm là 15 mph, trừ khi có biển báo ghi giới hạn khác.","p":"Đúng. Trong hẻm là 15 mph."},"tl":{"q":"Sa Texas, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa eskinita (alley)?","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"Kalahati ito ng speed limit sa kalye sa lungsod.","h2":"Sa Texas, 15 mph ang speed limit sa eskinita maliban kung may karatulang nagpapakita ng ibang limit.","p":"Tama. 15 mph sa mga eskinita."},"ar":{"q":"في Texas، إذا لم تقل لافتة غير ذلك، ما حدّ السرعة في الزقاق (alley)؟","o":["15 mph","5 mph","25 mph","30 mph"],"h1":"هو نصف حدّ السرعة في شارع داخل المدينة.","h2":"في Texas حدّ السرعة في الزقاق 15 mph، إلا إذا كانت هناك لافتة تُظهر حدًّا مختلفًا.","p":"صحيح. حدّ السرعة في الأزقّة 15 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-050","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you are on a two-lane road that meets a divided road or a road with three or more lanes. No sign or signal controls the intersection. Who must yield?","o":["Traffic on the larger road must yield to you","The driver on the right goes first","You must yield to traffic on the larger road","The faster car goes first"],"h1":"Think about which road carries more traffic.","h2":"In Texas a driver on a one-lane or two-lane road must yield the right-of-way to vehicles on a divided road or a road with three or more lanes.","p":"Right. You yield to the larger road."},"es":{"q":"En Texas, usted va por un camino de dos carriles que se cruza con una carretera dividida o con tres carriles o más. Ninguna señal ni semáforo controla el cruce. ¿Quién debe ceder el paso?","o":["El tráfico de la carretera más grande debe cederle el paso a usted","El conductor de la derecha pasa primero","Usted debe ceder el paso al tráfico de la carretera más grande","El carro más rápido pasa primero"],"h1":"Piense en cuál camino lleva más tráfico.","h2":"En Texas el conductor que va por un camino de uno o dos carriles debe ceder el paso a los vehículos de una carretera dividida o de tres carriles o más.","p":"Correcto. Usted cede el paso a la carretera más grande."},"zh":{"q":"在 Texas，你在一条双车道的路上，前面和一条分隔道路或三条或更多车道的路相交。路口没有标志或信号灯。谁必须让行？","o":["大路上的车必须让你","右边的司机先走","你必须让大路上的车","开得快的车先走"],"h1":"想一想哪条路车更多。","h2":"在 Texas，在单车道或双车道路上的司机，必须让分隔道路或三条或更多车道道路上的车辆先行。","p":"对。你要让大路上的车。"},"vi":{"q":"Ở Texas, bạn đang đi trên đường hai làn gặp một đường có dải phân cách hoặc đường có từ ba làn trở lên. Không có biển báo hay đèn giao thông ở giao lộ. Ai phải nhường đường?","o":["Xe trên đường lớn hơn phải nhường bạn","Tài xế bên phải đi trước","Bạn phải nhường xe trên đường lớn hơn","Xe chạy nhanh hơn đi trước"],"h1":"Hãy nghĩ xem đường nào có nhiều xe hơn.","h2":"Ở Texas, tài xế trên đường một làn hoặc hai làn phải nhường đường cho xe trên đường có dải phân cách hoặc đường có từ ba làn trở lên.","p":"Đúng. Bạn nhường đường lớn hơn."},"tl":{"q":"Sa Texas, nasa daang may dalawang lane ka na sumasalubong sa divided road o daang may tatlo o higit pang lane. Walang karatula o signal sa intersection. Sino ang dapat magbigay-daan?","o":["Ang trapiko sa mas malaking daan ang dapat magbigay-daan sa iyo","Ang driver sa kanan ang mauuna","Dapat kang magbigay-daan sa trapiko sa mas malaking daan","Ang mas mabilis na kotse ang mauuna"],"h1":"Isipin kung aling daan ang may mas maraming trapiko.","h2":"Sa Texas, ang driver sa daang may isa o dalawang lane ay dapat magbigay ng right-of-way sa mga sasakyan sa divided road o daang may tatlo o higit pang lane.","p":"Tama. Magbigay-daan ka sa mas malaking daan."},"ar":{"q":"في Texas، أنت على طريق من حارتين يلتقي بطريق مقسوم أو طريق فيه ثلاث حارات أو أكثر. لا توجد لافتة أو إشارة تنظّم التقاطع. من يجب أن يعطي حق الأولوية؟","o":["السيارات على الطريق الأكبر يجب أن تعطيك الأولوية","السائق الذي على اليمين يمرّ أولًا","يجب أن تعطي الأولوية للسيارات على الطريق الأكبر","السيارة الأسرع تمرّ أولًا"],"h1":"فكّر في أيّ طريق تمرّ عليه سيارات أكثر.","h2":"في Texas، السائق على طريق من حارة واحدة أو حارتين يجب أن يعطي حق الأولوية للمركبات على طريق مقسوم أو طريق فيه ثلاث حارات أو أكثر.","p":"صحيح. أنت تعطي الأولوية للطريق الأكبر."},"ref":{"doc":"TX","page":20}},{"id":"tx-051","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, a new resident has a valid license from another state. How long do they have to get a Texas driver license?","o":["30 days","60 days","90 days","1 year"],"h1":"It is about three months.","h2":"A new Texas resident with a valid out-of-state license has 90 days to get a Texas driver license.","p":"Right. New residents have 90 days."},"es":{"q":"En Texas, un nuevo residente tiene una licencia válida de otro estado. ¿Cuánto tiempo tiene para obtener una licencia de Texas?","o":["30 días","60 días","90 días","1 año"],"h1":"Son unos tres meses.","h2":"Un nuevo residente de Texas con una licencia válida de otro estado tiene 90 días para obtener una licencia de Texas.","p":"Correcto. Los nuevos residentes tienen 90 días."},"ref":{"doc":"TX","page":1}},{"id":"tx-052","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, which of these would make an adult unfit to supervise a learner driver?","o":["Being 30 years old","Having 5 years of driving experience","Sitting in the front passenger seat","Being asleep in the passenger seat"],"h1":"The supervisor must be able to watch and react.","h2":"A Texas learner supervisor must not be asleep, intoxicated, or busy with anything that stops them from watching the driver and reacting.","p":"Right. A sleeping adult cannot supervise a learner."},"es":{"q":"En Texas, ¿cuál de estas cosas impide que un adulto supervise a un conductor aprendiz?","o":["Tener 30 años","Tener 5 años de experiencia manejando","Ir sentado en el asiento delantero del pasajero","Estar dormido en el asiento del pasajero"],"h1":"El supervisor debe poder mirar y reaccionar.","h2":"En Texas, el supervisor de un aprendiz no puede estar dormido, intoxicado ni ocupado en algo que le impida observar al conductor y reaccionar.","p":"Correcto. Un adulto dormido no puede supervisar a un aprendiz."},"ref":{"doc":"TX","page":1}},{"id":"tx-053","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, what is the total fee for a learner license for a teen?","o":["$6","$16","$33","$48"],"h1":"It is $15 for the license plus a $1 fee.","h2":"A Texas learner license for someone under 18 costs $16: $15 for the license and a $1 administrative fee.","p":"Right. A learner license costs $16."},"es":{"q":"En Texas, ¿cuánto cuesta en total la licencia de aprendiz para un adolescente?","o":["$6","$16","$33","$48"],"h1":"Son $15 por la licencia más un cargo de $1.","h2":"En Texas, la licencia de aprendiz para menores de 18 años cuesta $16: $15 por la licencia y $1 de cargo administrativo.","p":"Correcto. La licencia de aprendiz cuesta $16."},"ref":{"doc":"TX","page":1}},{"id":"tx-054","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a 19-year-old wants to practice driving legally before passing the road test. What do they get?","o":["A provisional license","A hardship license","A temporary visitor permit","A Class C license with the same limits as a learner license"],"h1":"Learner licenses are for people under 18.","h2":"In Texas, an applicant 18 or older who wants to practice driving gets a Class C license with the same restrictions as a learner license.","p":"Right. Adults get a Class C license with learner limits."},"es":{"q":"En Texas, una persona de 19 años quiere practicar manejo legalmente antes de pasar el examen de manejo. ¿Qué recibe?","o":["Una licencia provisional","Una licencia por necesidad (hardship)","Un permiso de visitante temporal","Una licencia Clase C con los mismos límites que la licencia de aprendiz"],"h1":"La licencia de aprendiz es para menores de 18 años.","h2":"En Texas, quien tiene 18 años o más y quiere practicar manejo recibe una licencia Clase C con las mismas restricciones que una licencia de aprendiz.","p":"Correcto. Los adultos reciben una Clase C con límites de aprendiz."},"ref":{"doc":"TX","page":1}},{"id":"tx-055","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, a student under 18 applying for a first license needs a school attendance form (VOE). How many days must the student have attended in the fall or spring semester before applying?","o":["30 days","45 days","80 days","120 days"],"h1":"It is more than half of a typical semester.","h2":"For the Texas VOE form, a student must have attended school at least 80 days in the fall or spring semester before the application.","p":"Right. The student needs at least 80 days of attendance."},"es":{"q":"En Texas, un estudiante menor de 18 años que pide su primera licencia necesita un formulario de asistencia escolar (VOE). ¿Cuántos días debe haber asistido en el semestre de otoño o primavera antes de solicitarla?","o":["30 días","45 días","80 días","120 días"],"h1":"Es más de la mitad de un semestre normal.","h2":"Para el formulario VOE de Texas, el estudiante debe haber asistido a la escuela al menos 80 días en el semestre de otoño o primavera antes de la solicitud.","p":"Correcto. El estudiante necesita al menos 80 días de asistencia."},"ref":{"doc":"TX","page":2}},{"id":"tx-056","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, during the school year, how old may the school attendance form (VOE) be when you apply for a license?","o":["No more than 30 days old","No more than 60 days old","No more than 6 months old","Any age, as long as it is signed"],"h1":"In summer the limit is longer, 90 days.","h2":"During the school year, the Texas VOE form may not be dated more than 30 days before the license application.","p":"Right. During the school year it must be 30 days old or less."},"es":{"q":"En Texas, durante el año escolar, ¿qué antigüedad puede tener el formulario de asistencia escolar (VOE) al solicitar la licencia?","o":["No más de 30 días","No más de 60 días","No más de 6 meses","Cualquiera, si está firmado"],"h1":"En verano el límite es mayor, 90 días.","h2":"Durante el año escolar, el formulario VOE de Texas no puede tener fecha de más de 30 días antes de la solicitud de licencia.","p":"Correcto. Durante el año escolar debe tener 30 días o menos."},"ref":{"doc":"TX","page":2}},{"id":"tx-057","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a teen's learner license is suspended for 20 days during the required six months. What happens to the six-month waiting period?","o":["It is extended by the 20 days of suspension","It starts over from zero","Nothing; the suspension days still count","The teen must wait an extra year"],"h1":"The license is not valid while it is suspended.","h2":"In Texas, if a learner license is suspended during Phase One, the six-month period is extended by the number of days of the suspension.","p":"Right. The wait grows by the days of suspension."},"es":{"q":"En Texas, la licencia de aprendiz de un adolescente se suspende 20 días durante los seis meses requeridos. ¿Qué pasa con el periodo de seis meses?","o":["Se alarga por los 20 días de suspensión","Empieza de nuevo desde cero","Nada; los días de suspensión cuentan igual","El adolescente debe esperar un año más"],"h1":"La licencia no es válida mientras está suspendida.","h2":"En Texas, si la licencia de aprendiz se suspende durante la Fase Uno, el periodo de seis meses se alarga por el número de días de la suspensión.","p":"Correcto. La espera aumenta por los días de suspensión."},"ref":{"doc":"TX","page":2}},{"id":"tx-058","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, what words are printed on every driver license issued to a person younger than 21?","o":["LEARNER","PROVISIONAL","MINOR","UNDER 21"],"h1":"It tells sellers of alcohol your age group.","h2":"Every Texas driver license issued to a person younger than 21 is marked \"UNDER 21\".","p":"Right. It says UNDER 21."},"es":{"q":"En Texas, ¿qué palabras se imprimen en toda licencia de manejar de una persona menor de 21 años?","o":["LEARNER","PROVISIONAL","MINOR","UNDER 21"],"h1":"Les indica la edad a quienes venden alcohol.","h2":"Toda licencia de manejar de Texas para una persona menor de 21 años lleva la marca \"UNDER 21\".","p":"Correcto. Dice UNDER 21."},"ref":{"doc":"TX","page":3}},{"id":"tx-059","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, how often must most adult drivers renew their driver license?","o":["Every 4 years","Every 6 years","Every 8 years","Every 10 years"],"h1":"The vision exam rule is every 16 years, which is twice this.","h2":"Most Texas driver licenses for adults must be renewed every eight years.","p":"Right. Most adult licenses last eight years."},"es":{"q":"En Texas, ¿cada cuánto deben renovar su licencia de manejar la mayoría de los adultos?","o":["Cada 4 años","Cada 6 años","Cada 8 años","Cada 10 años"],"h1":"La regla del examen de la vista es cada 16 años, el doble de esto.","h2":"La mayoría de las licencias de manejar de adultos en Texas deben renovarse cada ocho años.","p":"Correcto. La mayoría de las licencias de adultos duran ocho años."},"ref":{"doc":"TX","page":10}},{"id":"tx-060","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, a driver who is 85 or older gets a new license. How long is it valid?","o":["1 year","2 years","4 years","8 years"],"h1":"It is much shorter than the usual eight years.","h2":"In Texas, a driver license for someone 85 or older expires after two years.","p":"Right. At 85 and older, the license lasts two years."},"es":{"q":"En Texas, un conductor de 85 años o más recibe una licencia nueva. ¿Cuánto tiempo es válida?","o":["1 año","2 años","4 años","8 años"],"h1":"Es mucho menos que los ocho años normales.","h2":"En Texas, la licencia de manejar de una persona de 85 años o más vence a los dos años.","p":"Correcto. A partir de los 85 años, la licencia dura dos años."},"ref":{"doc":"TX","page":81}},{"id":"tx-061","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, with a Class C license, what is the heaviest trailer (by weight rating) you may tow behind a regular car or pickup?","o":["3,000 lbs.","5,000 lbs.","8,000 lbs.","10,000 lbs."],"h1":"Above this, you need Class A.","h2":"A Texas Class C license lets you tow a trailer with a weight rating of no more than 10,000 lbs. (a farm trailer up to 20,000 lbs.).","p":"Right. Class C covers trailers up to 10,000 lbs."},"es":{"q":"En Texas, con una licencia Clase C, ¿cuál es el remolque más pesado (por clasificación de peso) que puede jalar con un carro o camioneta normal?","o":["3,000 lbs.","5,000 lbs.","8,000 lbs.","10,000 lbs."],"h1":"Por encima de esto se necesita la Clase A.","h2":"La licencia Clase C de Texas permite jalar un remolque con clasificación de peso de no más de 10,000 lbs. (un remolque agrícola hasta 20,000 lbs.).","p":"Correcto. La Clase C cubre remolques hasta 10,000 lbs."},"ref":{"doc":"TX","page":4}},{"id":"tx-062","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, which license class lets you drive an autocycle (a three-wheeled vehicle with a steering wheel and regular seats)?","o":["Class M","Class B","Class A","Class C"],"h1":"You do not straddle an autocycle like a motorcycle.","h2":"In Texas, an autocycle can be driven with a Class C license; a motorcycle license is not needed.","p":"Right. An autocycle needs only a Class C license."},"es":{"q":"En Texas, ¿qué clase de licencia permite manejar un autociclo (vehículo de tres ruedas con volante y asientos normales)?","o":["Clase M","Clase B","Clase A","Clase C"],"h1":"En un autociclo no se va montado como en una motocicleta.","h2":"En Texas, un autociclo se puede manejar con una licencia Clase C; no hace falta licencia de motocicleta.","p":"Correcto. Un autociclo solo requiere licencia Clase C."},"ref":{"doc":"TX","page":4}},{"id":"tx-063","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a 15-year-old finished the driver education classroom phase and a motorcycle safety course. What is the largest motorcycle engine they may be licensed for?","o":["250 cc or less","500 cc or less","750 cc or less","Any size"],"h1":"Full motorcycle licenses start at 16.","h2":"In Texas, a 15-year-old may be licensed only for a motorcycle of 250 cc or less; the full Class M starts at 16.","p":"Right. At 15, it is 250 cc or less."},"es":{"q":"En Texas, un joven de 15 años terminó la parte de aula de educación vial y un curso de seguridad en motocicleta. ¿Cuál es el motor más grande para el que puede tener licencia?","o":["250 cc o menos","500 cc o menos","750 cc o menos","Cualquier tamaño"],"h1":"La licencia completa de motocicleta empieza a los 16.","h2":"En Texas, un joven de 15 años solo puede tener licencia para una motocicleta de 250 cc o menos; la Clase M completa empieza a los 16.","p":"Correcto. A los 15 años, es 250 cc o menos."},"ref":{"doc":"TX","page":5}},{"id":"tx-064","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how many hours long is the classroom phase of a teen driver education course?","o":["16 hours","32 hours","44 hours","60 hours"],"h1":"It is twice the length of the 16-hour motorcycle course.","h2":"The classroom phase of a Texas driver education course is 32 hours.","p":"Right. The classroom phase is 32 hours."},"es":{"q":"En Texas, ¿cuántas horas dura la parte de aula del curso de educación vial para adolescentes?","o":["16 horas","32 horas","44 horas","60 horas"],"h1":"Es el doble del curso de motocicleta de 16 horas.","h2":"La parte de aula de un curso de educación vial en Texas dura 32 horas.","p":"Correcto. La parte de aula dura 32 horas."},"ref":{"doc":"TX","page":4}},{"id":"tx-065","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a minor's license application was signed by a parent. Who may later ask DPS to cancel the minor's license?","o":["The person who signed the application","Any teacher at the minor's school","Any police officer","No one until the minor turns 18"],"h1":"The adult who signed can take it back before the 18th birthday.","h2":"In Texas, the person who signed a minor's application may ask DPS in writing, under oath, to cancel the license any time before the minor turns 18.","p":"Right. The signer may ask DPS to cancel it."},"es":{"q":"En Texas, un padre firmó la solicitud de licencia de un menor. ¿Quién puede pedir después al DPS que cancele la licencia del menor?","o":["La persona que firmó la solicitud","Cualquier maestro de la escuela del menor","Cualquier policía","Nadie hasta que el menor cumpla 18"],"h1":"El adulto que firmó puede retirarla antes de los 18 años.","h2":"En Texas, la persona que firmó la solicitud de un menor puede pedir al DPS por escrito y bajo juramento que cancele la licencia en cualquier momento antes de que el menor cumpla 18 años.","p":"Correcto. Quien firmó puede pedir la cancelación."},"ref":{"doc":"TX","page":7}},{"id":"tx-066","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, after how many failed exams must you start a new application and pay the fee again?","o":["One","Two","Three","Five"],"h1":"The application is also held for 90 days.","h2":"In Texas, after 90 days or three failed exams, you must submit a new application and fee.","p":"Right. After three failed exams you must reapply."},"es":{"q":"En Texas, ¿después de cuántos exámenes reprobados debe hacer una nueva solicitud y pagar otra vez?","o":["Uno","Dos","Tres","Cinco"],"h1":"La solicitud también se guarda por 90 días.","h2":"En Texas, después de 90 días o de tres exámenes reprobados, debe presentar una nueva solicitud y pagar la tarifa.","p":"Correcto. Después de tres exámenes reprobados hay que volver a solicitar."},"ref":{"doc":"TX","page":7}},{"id":"tx-067","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, after you pass your exams, you get a temporary license. How long can you use it while you wait for the card in the mail?","o":["10 days","45 days","90 days","6 months"],"h1":"It is about a month and a half.","h2":"In Texas, the temporary license may be used for 45 days or until the permanent license arrives in the mail.","p":"Right. The temporary license is good for 45 days."},"es":{"q":"En Texas, después de aprobar los exámenes recibe una licencia temporal. ¿Cuánto tiempo puede usarla mientras espera la tarjeta por correo?","o":["10 días","45 días","90 días","6 meses"],"h1":"Es como mes y medio.","h2":"En Texas, la licencia temporal se puede usar por 45 días o hasta que llegue por correo la licencia permanente.","p":"Correcto. La licencia temporal vale por 45 días."},"ref":{"doc":"TX","page":7}},{"id":"tx-068","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a 30-year-old moves from another state and turns in a valid license from that state. Which exams are usually skipped?","o":["Only the vision exam","No exams are skipped","Only the driving exam, never the knowledge exam","The knowledge and driving exams"],"h1":"Adults with a valid license from another state have already shown they can drive.","h2":"In Texas, applicants 18 or older who surrender a valid out-of-state license do not have to take the knowledge and driving exams.","p":"Right. The knowledge and driving exams are skipped."},"es":{"q":"En Texas, una persona de 30 años se muda de otro estado y entrega una licencia válida de ese estado. ¿Qué exámenes normalmente no tiene que tomar?","o":["Solo el examen de la vista","Ninguno; debe tomarlos todos","Solo el de manejo, nunca el de conocimientos","Los exámenes de conocimientos y de manejo"],"h1":"Los adultos con licencia válida de otro estado ya demostraron que saben manejar.","h2":"En Texas, los solicitantes de 18 años o más que entregan una licencia válida de otro estado no tienen que tomar los exámenes de conocimientos y de manejo.","p":"Correcto. No toman los exámenes de conocimientos y de manejo."},"ref":{"doc":"TX","page":7}},{"id":"tx-069","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what does restriction code \"A\" on a driver license mean?","o":["You must wear corrective lenses","You may drive only in daylight","You must drive an automatic car","You may not drive faster than 45 mph"],"h1":"It is often added after the vision exam.","h2":"Restriction code A on a Texas driver license means you must drive with corrective lenses, such as glasses or contacts.","p":"Right. Code A means corrective lenses."},"es":{"q":"En Texas, ¿qué significa el código de restricción \"A\" en una licencia de manejar?","o":["Debe usar lentes correctivos","Solo puede manejar de día","Debe manejar un carro automático","No puede ir a más de 45 mph"],"h1":"Muchas veces se agrega después del examen de la vista.","h2":"El código de restricción A en una licencia de Texas significa que debe manejar con lentes correctivos, como anteojos o lentes de contacto.","p":"Correcto. El código A significa lentes correctivos."},"ref":{"doc":"TX","page":83}},{"id":"tx-070","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how many points can be taken off during the driving exam before you fail?","o":["More than 10 points","More than 15 points","More than 20 points","More than 30 points"],"h1":"It is a round number between 25 and 35.","h2":"In Texas, your license application is not approved if more than 30 points are deducted on the driving exam.","p":"Right. More than 30 points off means you fail."},"es":{"q":"En Texas, ¿cuántos puntos le pueden quitar en el examen de manejo antes de reprobar?","o":["Más de 10 puntos","Más de 15 puntos","Más de 20 puntos","Más de 30 puntos"],"h1":"Es un número redondo entre 25 y 35.","h2":"En Texas, su solicitud no se aprueba si le quitan más de 30 puntos en el examen de manejo.","p":"Correcto. Si le quitan más de 30 puntos, reprueba."},"ref":{"doc":"TX","page":8}},{"id":"tx-071","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, the driving exam may include a quick stop. About how fast will you be going when asked to stop as quickly as you can without skidding?","o":["10 mph","20 mph","35 mph","45 mph"],"h1":"It is a low city speed.","h2":"In the Texas driving exam, you may be asked to stop as quickly as possible from about 20 mph without skidding the tires.","p":"Right. The quick stop is from about 20 mph."},"es":{"q":"En Texas, el examen de manejo puede incluir una parada rápida. ¿A qué velocidad aproximada irá cuando le pidan parar lo más rápido posible sin derrapar?","o":["10 mph","20 mph","35 mph","45 mph"],"h1":"Es una velocidad baja de ciudad.","h2":"En el examen de manejo de Texas le pueden pedir que pare lo más rápido posible desde unas 20 mph sin que las llantas derrapen.","p":"Correcto. La parada rápida es desde unas 20 mph."},"ref":{"doc":"TX","page":8}},{"id":"tx-072","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, your car can park itself and also has a back-up camera. What may you use during the parallel parking part of the driving exam?","o":["The back-up camera, but not the self-parking feature","The self-parking feature","Both the camera and the self-parking feature","Neither one"],"h1":"You must show that you can control the car yourself.","h2":"In the Texas driving exam you may use a back-up camera for parallel parking, but an automated parking function is not allowed.","p":"Right. The camera is allowed; self-parking is not."},"es":{"q":"En Texas, su carro puede estacionarse solo y también tiene cámara de reversa. ¿Qué puede usar en la parte de estacionamiento en paralelo del examen de manejo?","o":["La cámara de reversa, pero no el estacionamiento automático","El estacionamiento automático","La cámara y el estacionamiento automático","Ninguno de los dos"],"h1":"Debe demostrar que usted mismo controla el carro.","h2":"En el examen de manejo de Texas puede usar la cámara de reversa para estacionar en paralelo, pero no se permite la función de estacionamiento automático.","p":"Correcto. La cámara se permite; el estacionamiento automático no."},"ref":{"doc":"TX","page":8}},{"id":"tx-073","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, every driving exam grades four basic skills. Which one of these is one of them?","o":["Speed","Radio use","Observation","Fuel economy"],"h1":"The four are control, positioning, signaling, and one about seeing traffic.","h2":"Every Texas driving exam grades four basic skills: control, observation, positioning, and signaling.","p":"Right. Observation is one of the four skills."},"es":{"q":"En Texas, todo examen de manejo califica cuatro destrezas básicas. ¿Cuál de estas es una de ellas?","o":["Velocidad","Uso del radio","Observación","Ahorro de gasolina"],"h1":"Las cuatro son control, posición, señales y una sobre ver el tráfico.","h2":"Todo examen de manejo en Texas califica cuatro destrezas básicas: control, observación, posición en el carril y uso de señales.","p":"Correcto. La observación es una de las cuatro destrezas."},"ref":{"doc":"TX","page":8}},{"id":"tx-074","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, you are not yet allowed to drive and you have a driving exam today. How must your car get to the driver license office?","o":["You may drive it there slowly","You may drive it if you carry your permit application","It must be towed","A licensed driver must drive it there"],"h1":"You may not drive on public roads without a license.","h2":"If you are not eligible to drive in Texas, a licensed driver must drive the car to the office and, if you do not get a license, drive you away.","p":"Right. A licensed driver must bring the car."},"es":{"q":"En Texas, todavía no tiene permiso para manejar y hoy tiene el examen de manejo. ¿Cómo debe llegar su carro a la oficina de licencias?","o":["Usted puede llevarlo despacio","Puede manejarlo si lleva su solicitud","Debe llegar en grúa","Un conductor con licencia debe llevarlo"],"h1":"No puede manejar en vías públicas sin licencia.","h2":"Si usted no puede manejar legalmente en Texas, un conductor con licencia debe llevar el carro a la oficina y, si no obtiene la licencia, llevarlo a usted de regreso.","p":"Correcto. Un conductor con licencia debe llevar el carro."},"ref":{"doc":"TX","page":8}},{"id":"tx-075","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, besides a peace officer, who may ask to see your driver license?","o":["A gas station worker","Any passenger in your car","A parking lot attendant","Anyone involved with you in a crash"],"h1":"Think about who needs your information after a collision.","h2":"In Texas you must show your license on request to a peace officer, judge, or trooper, and to anyone involved with you in a crash.","p":"Right. Anyone in a crash with you may ask to see it."},"es":{"q":"En Texas, además de un agente de la ley, ¿quién le puede pedir ver su licencia de manejar?","o":["Un empleado de la gasolinera","Cualquier pasajero de su carro","Un encargado de estacionamiento","Cualquier persona involucrada con usted en un choque"],"h1":"Piense en quién necesita sus datos después de un choque.","h2":"En Texas debe mostrar su licencia cuando se lo pida un agente de la ley, un juez o un patrullero, y también cualquier persona involucrada con usted en un choque.","p":"Correcto. Cualquiera en un choque con usted puede pedirla."},"ref":{"doc":"TX","page":9}},{"id":"tx-076","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, what fine can a driver get for a second conviction of driving without a license within one year?","o":["$25 to $200","$100 to $500","$500 to $1,000","Up to $4,000"],"h1":"The top of the range is the same as for a first conviction.","h2":"In Texas, a second conviction of driving without a license within one year brings a fine of $25 to $200.","p":"Right. The fine is $25 to $200."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por una segunda condena por manejar sin licencia en un año?","o":["$25 a $200","$100 a $500","$500 a $1,000","Hasta $4,000"],"h1":"El máximo es igual que en la primera condena.","h2":"En Texas, una segunda condena por manejar sin licencia dentro de un año tiene una multa de $25 a $200.","p":"Correcto. La multa es de $25 a $200."},"ref":{"doc":"TX","page":9}},{"id":"tx-077","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver with no license and no insurance causes a crash that seriously injures someone. What can the penalty be?","o":["A fine up to $4,000, up to 365 days in jail, or both","A warning only","A fine of $25 to $200","A fine of $175 to $350"],"h1":"This is a Class A misdemeanor, the most serious kind.","h2":"In Texas, driving without a license and without insurance and causing a crash with serious injury or death is a Class A misdemeanor: up to $4,000, up to 365 days in jail, or both.","p":"Right. Up to $4,000 and up to 365 days in jail."},"es":{"q":"En Texas, un conductor sin licencia y sin seguro causa un choque que deja a alguien gravemente herido. ¿Cuál puede ser la pena?","o":["Multa de hasta $4,000, hasta 365 días de cárcel, o ambas","Solo una advertencia","Multa de $25 a $200","Multa de $175 a $350"],"h1":"Es un delito menor Clase A, el más grave de ese tipo.","h2":"En Texas, manejar sin licencia y sin seguro y causar un choque con lesiones graves o muerte es un delito menor Clase A: hasta $4,000, hasta 365 días de cárcel, o ambas.","p":"Correcto. Hasta $4,000 y hasta 365 días de cárcel."},"ref":{"doc":"TX","page":9}},{"id":"tx-078","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, you moved to a new home. How soon must you report your new address to DPS?","o":["Within 10 days","Within 30 days","Within 60 days","At your next renewal"],"h1":"It is about one month.","h2":"In Texas, a change of address must be reported to DPS within 30 days.","p":"Right. Report it within 30 days."},"es":{"q":"En Texas, usted se mudó a una casa nueva. ¿En cuánto tiempo debe informar su nueva dirección al DPS?","o":["En 10 días","En 30 días","En 60 días","En su próxima renovación"],"h1":"Es como un mes.","h2":"En Texas, el cambio de dirección se debe informar al DPS dentro de 30 días.","p":"Correcto. Infórmelo dentro de 30 días."},"ref":{"doc":"TX","page":9}},{"id":"tx-079","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, from what age must a driver renew the license in person instead of online, by phone, or by mail?","o":["65","70","75","79"],"h1":"It is just under 80.","h2":"In Texas, drivers 79 or older may not renew online, by phone, or by mail; they must renew in person.","p":"Right. At 79 and older, renewal is in person."},"es":{"q":"En Texas, ¿a partir de qué edad debe renovar la licencia en persona y no por internet, teléfono o correo?","o":["65","70","75","79"],"h1":"Es justo antes de los 80.","h2":"En Texas, los conductores de 79 años o más no pueden renovar por internet, teléfono ni correo; deben renovar en persona.","p":"Correcto. A partir de los 79 años se renueva en persona."},"ref":{"doc":"TX","page":10}},{"id":"tx-080","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, which of these license holders may NOT use online or mail renewal?","o":["A 40-year-old with a clean Class C license","A 25-year-old U.S. citizen with a photo on file","A 60-year-old with no medical limits","A teen with a provisional license"],"h1":"Graduated licenses for teens have special rules.","h2":"In Texas, holders of a provisional, learner, or occupational license may not renew online, by phone, or by mail.","p":"Right. Provisional license holders cannot renew online."},"es":{"q":"En Texas, ¿cuál de estos titulares NO puede renovar por internet o por correo?","o":["Una persona de 40 años con Clase C sin problemas","Un ciudadano de 25 años con foto en el sistema","Una persona de 60 años sin límites médicos","Un adolescente con licencia provisional"],"h1":"Las licencias graduales para adolescentes tienen reglas especiales.","h2":"En Texas, quienes tienen licencia provisional, de aprendiz u ocupacional no pueden renovar por internet, teléfono ni correo.","p":"Correcto. Una licencia provisional no se renueva por internet."},"ref":{"doc":"TX","page":10}},{"id":"tx-081","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a conviction for which of these leads to an automatic license suspension?","o":["Racing a motor vehicle on a public street","Parking too far from the curb","Driving with a burned-out license plate light","Forgetting to signal a lane change"],"h1":"It is a dangerous act at high speed.","h2":"In Texas, a conviction for racing a motor vehicle on a public highway or street results in an automatic license suspension.","p":"Right. Street racing brings an automatic suspension."},"es":{"q":"En Texas, ¿una condena por cuál de estas cosas causa la suspensión automática de la licencia?","o":["Hacer carreras con un vehículo en una calle pública","Estacionarse muy lejos de la acera","Manejar con la luz de la placa fundida","Olvidar poner la direccional al cambiar de carril"],"h1":"Es algo peligroso a alta velocidad.","h2":"En Texas, una condena por hacer carreras con un vehículo en una carretera o calle pública causa la suspensión automática de la licencia.","p":"Correcto. Las carreras en la calle causan suspensión automática."},"ref":{"doc":"TX","page":11}},{"id":"tx-082","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, DPS may suspend an adult's license for repeated violations. How many traffic convictions within any 24 months can lead to this?","o":["Three or more","Five or more","Seven or more","Ten or more"],"h1":"It is more than the four convictions in 12 months rule.","h2":"In Texas, seven or more traffic convictions within any 24-month period can lead DPS to suspend a license.","p":"Right. Seven or more in 24 months."},"es":{"q":"En Texas, el DPS puede suspender la licencia de un adulto por infracciones repetidas. ¿Cuántas condenas de tránsito en cualquier periodo de 24 meses pueden causarlo?","o":["Tres o más","Cinco o más","Siete o más","Diez o más"],"h1":"Es más que la regla de cuatro condenas en 12 meses.","h2":"En Texas, siete o más condenas de tránsito dentro de cualquier periodo de 24 meses pueden llevar al DPS a suspender una licencia.","p":"Correcto. Siete o más en 24 meses."},"ref":{"doc":"TX","page":11}},{"id":"tx-083","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver younger than 18 can lose the license after a hearing for repeated violations. How many separate traffic convictions within 12 months can cause this?","o":["Two or more","Four or more","Six or more","Eight or more"],"h1":"Teens get fewer chances than adults.","h2":"In Texas, DPS may suspend the license of a driver under 18 who has two or more separate traffic convictions within 12 months.","p":"Right. Two or more within 12 months."},"es":{"q":"En Texas, un conductor menor de 18 años puede perder la licencia después de una audiencia por infracciones repetidas. ¿Cuántas condenas de tránsito separadas en 12 meses pueden causarlo?","o":["Dos o más","Cuatro o más","Seis o más","Ocho o más"],"h1":"Los adolescentes tienen menos oportunidades que los adultos.","h2":"En Texas, el DPS puede suspender la licencia de un conductor menor de 18 años que tenga dos o más condenas de tránsito separadas en 12 meses.","p":"Correcto. Dos o más en 12 meses."},"ref":{"doc":"TX","page":12}},{"id":"tx-084","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, which of these can lead a court to order DPS to suspend your driver license even though it has nothing to do with driving?","o":["An unpaid library fine","A bad credit score","Unpaid child support","Moving to a new city"],"h1":"It is a family court matter.","h2":"In Texas, DPS will suspend, revoke, or cancel a license when it receives a court order for delinquent child support.","p":"Right. Unpaid child support can cost you your license."},"es":{"q":"En Texas, ¿cuál de estas cosas puede hacer que un tribunal ordene al DPS suspender su licencia aunque no tenga que ver con manejar?","o":["Una multa de biblioteca sin pagar","Un mal historial de crédito","No pagar la manutención de los hijos","Mudarse a otra ciudad"],"h1":"Es un asunto de un tribunal de familia.","h2":"En Texas, el DPS suspende, revoca o cancela una licencia cuando recibe una orden judicial por manutención de hijos atrasada.","p":"Correcto. No pagar la manutención puede costarle la licencia."},"ref":{"doc":"TX","page":12}},{"id":"tx-085","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a driver who was convicted before of driving with a suspended license does it again. What is the highest fine?","o":["$200","$500","$1,000","$2,000"],"h1":"It becomes a Class B misdemeanor, with possible jail.","h2":"In Texas, driving while license invalid with a previous conviction is a Class B misdemeanor: a fine up to $2,000, up to 180 days in jail, or both.","p":"Right. The fine can be up to $2,000."},"es":{"q":"En Texas, un conductor que ya fue condenado antes por manejar con la licencia suspendida lo vuelve a hacer. ¿Cuál es la multa máxima?","o":["$200","$500","$1,000","$2,000"],"h1":"Pasa a ser un delito menor Clase B, con posible cárcel.","h2":"En Texas, manejar con licencia inválida teniendo una condena anterior es un delito menor Clase B: multa de hasta $2,000, hasta 180 días de cárcel, o ambas.","p":"Correcto. La multa puede ser de hasta $2,000."},"ref":{"doc":"TX","page":13}},{"id":"tx-086","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a 19-year-old is convicted for the first time of having alcohol (not while driving). How long is the license suspended?","o":["30 days","60 days","180 days","1 year"],"h1":"It is the shortest suspension in the minor alcohol table.","h2":"In Texas, a minor's first non-driving alcohol offense brings a 30-day license suspension, a fine up to $500, community service, and an alcohol awareness course.","p":"Right. The first offense means a 30-day suspension."},"es":{"q":"En Texas, una persona de 19 años es condenada por primera vez por tener alcohol (sin estar manejando). ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","60 días","180 días","1 año"],"h1":"Es la suspensión más corta de la tabla de alcohol para menores.","h2":"En Texas, la primera infracción de alcohol de un menor sin manejar trae una suspensión de 30 días, multa de hasta $500, servicio comunitario y un curso sobre el alcohol.","p":"Correcto. La primera infracción causa 30 días de suspensión."},"ref":{"doc":"TX","page":13}},{"id":"tx-087","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, an adult buys beer for a 17-year-old. What is the highest penalty?","o":["A $50 fine","A $500 fine","A fine up to $4,000, up to one year in jail, or both","Community service only"],"h1":"The law treats furnishing alcohol to minors very seriously.","h2":"In Texas, a person who buys, furnishes, or sells alcohol to a minor can be fined up to $4,000, jailed up to one year, or both.","p":"Right. Up to $4,000 and up to a year in jail."},"es":{"q":"En Texas, un adulto le compra cerveza a un joven de 17 años. ¿Cuál es la pena máxima?","o":["Multa de $50","Multa de $500","Multa de hasta $4,000, hasta un año de cárcel, o ambas","Solo servicio comunitario"],"h1":"La ley castiga muy en serio dar alcohol a menores.","h2":"En Texas, quien compra, da o vende alcohol a un menor puede recibir una multa de hasta $4,000, hasta un año de cárcel, o ambas.","p":"Correcto. Hasta $4,000 y hasta un año de cárcel."},"ref":{"doc":"TX","page":14}},{"id":"tx-088","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, your license was suspended and you must drive to work. What lets DPS issue you an occupational (essential need) license?","o":["A letter from your boss","Paying double the normal fee","A court order","Passing the knowledge test again"],"h1":"You must prove your need to a judge.","h2":"In Texas, an occupational license is issued only after a court finds an essential need to drive and issues a court order.","p":"Right. You need a court order."},"es":{"q":"En Texas, su licencia fue suspendida y necesita manejar al trabajo. ¿Qué permite al DPS darle una licencia ocupacional (por necesidad esencial)?","o":["Una carta de su jefe","Pagar el doble de la tarifa normal","Una orden judicial","Volver a aprobar el examen de conocimientos"],"h1":"Debe demostrar su necesidad ante un juez.","h2":"En Texas, la licencia ocupacional solo se emite después de que un tribunal determina que hay una necesidad esencial de manejar y emite una orden judicial.","p":"Correcto. Necesita una orden judicial."},"ref":{"doc":"TX","page":14}},{"id":"tx-089","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a 17-year-old has a valid license from another state. Must they take the Texas driving exam?","o":["Yes, no one under 18 is exempt from the driving exam","No, never","Only if they fail the vision exam","Only if they want a Class M"],"h1":"The exemption for out-of-state licenses is only for adults.","h2":"In Texas, no one younger than 18 is exempt from the driving exam, so a 17-year-old with an out-of-state license must pass it.","p":"Right. Everyone under 18 must take the driving exam."},"es":{"q":"En Texas, un joven de 17 años tiene una licencia válida de otro estado. ¿Debe tomar el examen de manejo de Texas?","o":["Sí, nadie menor de 18 está exento del examen de manejo","No, nunca","Solo si reprueba el examen de la vista","Solo si quiere una Clase M"],"h1":"La excepción para licencias de otros estados es solo para adultos.","h2":"En Texas, nadie menor de 18 años está exento del examen de manejo, así que un joven de 17 con licencia de otro estado debe aprobarlo.","p":"Correcto. Todos los menores de 18 deben tomar el examen de manejo."},"ref":{"doc":"TX","page":8}},{"id":"tx-090","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, since 2025, most passenger cars no longer need a yearly safety inspection. What do owners pay instead when they register the car each year?","o":["Nothing at all","A $50 safety fee","A $100 road use fee","A $7.50 inspection program replacement fee"],"h1":"It is a small fee, less than $10.","h2":"Texas ended the yearly safety inspection for most passenger cars in 2025, and owners now pay a $7.50 inspection program replacement fee at registration (emissions tests still apply in some counties).","p":"Right. The replacement fee is $7.50 a year."},"es":{"q":"En Texas, desde 2025 la mayoría de los carros de pasajeros ya no necesitan inspección de seguridad anual. ¿Qué pagan los dueños en su lugar al registrar el carro cada año?","o":["Nada","Un cargo de seguridad de $50","Un cargo de uso de carreteras de $100","Un cargo de reemplazo del programa de inspección de $7.50"],"h1":"Es un cargo pequeño, de menos de $10.","h2":"Texas eliminó en 2025 la inspección de seguridad anual para la mayoría de los carros de pasajeros, y ahora los dueños pagan un cargo de reemplazo de $7.50 al registrar (las pruebas de emisiones siguen en algunos condados).","p":"Correcto. El cargo de reemplazo es de $7.50 al año."},"ref":{"doc":"TX","page":null}},{"id":"tx-091","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, where must the registration sticker be displayed on a car?","o":["On the windshield","On the rear bumper","On the driver's door","In the glove box"],"h1":"It is where an officer can see it from the front.","h2":"In Texas, the registration sticker must be displayed on the windshield of a car (on the rear plate of a motorcycle or moped).","p":"Right. It goes on the windshield."},"es":{"q":"En Texas, ¿dónde se debe poner la calcomanía de registro en un carro?","o":["En el parabrisas","En la defensa trasera","En la puerta del conductor","En la guantera"],"h1":"Es donde un oficial la puede ver desde el frente.","h2":"En Texas, la calcomanía de registro se debe poner en el parabrisas del carro (en la placa trasera de una motocicleta o moped).","p":"Correcto. Va en el parabrisas."},"ref":{"doc":"TX","page":16}},{"id":"tx-092","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, you just bought a car. How soon must you register it?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is about one month.","h2":"In Texas, an owner must register a newly purchased vehicle within 30 days of purchase.","p":"Right. Register it within 30 days."},"es":{"q":"En Texas, usted acaba de comprar un carro. ¿En cuánto tiempo debe registrarlo?","o":["En 10 días","En 30 días","En 60 días","En 90 días"],"h1":"Es como un mes.","h2":"En Texas, el dueño debe registrar un vehículo recién comprado dentro de los 30 días de la compra.","p":"Correcto. Regístrelo dentro de 30 días."},"ref":{"doc":"TX","page":16}},{"id":"tx-093","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, for how many days are a buyer's temporary tags recognized?","o":["10 days","30 days","60 days","6 months"],"h1":"It is about two months.","h2":"In Texas, buyers' temporary tags are recognized for 60 days.","p":"Right. Buyer's temporary tags are good for 60 days."},"es":{"q":"En Texas, ¿por cuántos días se reconocen las placas temporales del comprador?","o":["10 días","30 días","60 días","6 meses"],"h1":"Son como dos meses.","h2":"En Texas, las placas temporales del comprador se reconocen por 60 días.","p":"Correcto. Las placas temporales del comprador valen 60 días."},"ref":{"doc":"TX","page":16}},{"id":"tx-094","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a person moves to Texas and starts a job. How long may they drive their car with its out-of-state registration?","o":["30 days","90 days","6 months","Until the old registration expires"],"h1":"It is shorter than the time allowed to change the driver license.","h2":"In Texas, a new resident's vehicle may be driven for 30 days; after that it must be registered in Texas.","p":"Right. The car must be registered in Texas after 30 days."},"es":{"q":"En Texas, una persona se muda a Texas y empieza a trabajar. ¿Cuánto tiempo puede manejar su carro con el registro de otro estado?","o":["30 días","90 días","6 meses","Hasta que venza el registro anterior"],"h1":"Es menos que el tiempo para cambiar la licencia de manejar.","h2":"En Texas, el vehículo de un nuevo residente se puede manejar por 30 días; después debe registrarse en Texas.","p":"Correcto. El carro debe registrarse en Texas después de 30 días."},"ref":{"doc":"TX","page":17}},{"id":"tx-095","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, your car registration just expired. After how many working days can you be ticketed for driving with the old sticker?","o":["1 working day","2 working days","3 working days","5 working days"],"h1":"It is one work week.","h2":"In Texas, driving with an expired registration becomes an offense after the fifth working day after it expires.","p":"Right. You have 5 working days."},"es":{"q":"En Texas, el registro de su carro acaba de vencer. ¿Después de cuántos días hábiles le pueden multar por manejar con la calcomanía vieja?","o":["1 día hábil","2 días hábiles","3 días hábiles","5 días hábiles"],"h1":"Es una semana de trabajo.","h2":"En Texas, manejar con el registro vencido es una infracción después del quinto día hábil siguiente al vencimiento.","p":"Correcto. Tiene 5 días hábiles."},"ref":{"doc":"TX","page":null}},{"id":"tx-096","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, from 20 mph, within what distance must a car's foot brake be able to stop it?","o":["25 feet","50 feet","75 feet","100 feet"],"h1":"It is about the length of one and a half cars.","h2":"In Texas, a car's foot brake must be able to stop it within 25 feet at a speed of 20 mph.","p":"Right. Within 25 feet from 20 mph."},"es":{"q":"En Texas, desde 20 mph, ¿en qué distancia debe poder detener el carro el freno de pie?","o":["25 pies","50 pies","75 pies","100 pies"],"h1":"Es como el largo de un carro y medio.","h2":"En Texas, el freno de pie de un carro debe poder detenerlo en 25 pies a una velocidad de 20 mph.","p":"Correcto. En 25 pies desde 20 mph."},"ref":{"doc":"TX","page":15}},{"id":"tx-097","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, from how far away must your car horn be heard?","o":["50 feet","200 feet","500 feet","1,000 feet"],"h1":"It is less than the length of a football field.","h2":"In Texas, a car horn must be heard from at least 200 feet away.","p":"Right. At least 200 feet."},"es":{"q":"En Texas, ¿desde qué distancia se debe escuchar el claxon de su carro?","o":["50 pies","200 pies","500 pies","1,000 pies"],"h1":"Es menos que el largo de un campo de fútbol americano.","h2":"En Texas, el claxon de un carro se debe escuchar desde al menos 200 pies.","p":"Correcto. Al menos 200 pies."},"ref":{"doc":"TX","page":15}},{"id":"tx-098","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, how many license plates must a regular passenger car display?","o":["One, on the rear only","One, on the front only","None if the sticker is on the windshield","Two: one on the front and one on the rear"],"h1":"Texas does not allow a rear-only plate for regular cars.","h2":"In Texas, a passenger car must have one valid plate on the front and one on the rear.","p":"Right. Texas requires front and rear plates."},"es":{"q":"En Texas, ¿cuántas placas debe llevar un carro de pasajeros normal?","o":["Una, solo atrás","Una, solo adelante","Ninguna si la calcomanía está en el parabrisas","Dos: una adelante y una atrás"],"h1":"Texas no permite solo la placa trasera en carros normales.","h2":"En Texas, un carro de pasajeros debe llevar una placa válida adelante y otra atrás.","p":"Correcto. Texas exige placa adelante y atrás."},"ref":{"doc":"TX","page":15}},{"id":"tx-099","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, what is the minimum tread depth for the tires on your car?","o":["1/32 of an inch","2/32 of an inch","4/32 of an inch","6/32 of an inch"],"h1":"It is the depth of the tread wear bars on most tires.","h2":"In Texas, tires must be in safe condition with a tread depth of at least 2/32 of an inch.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En Texas, ¿cuál es la profundidad mínima del dibujo de las llantas de su carro?","o":["1/32 de pulgada","2/32 de pulgada","4/32 de pulgada","6/32 de pulgada"],"h1":"Es la altura de las barras indicadoras de desgaste de la mayoría de las llantas.","h2":"En Texas, las llantas deben estar en buen estado con un dibujo de al menos 2/32 de pulgada de profundidad.","p":"Correcto. Al menos 2/32 de pulgada."},"ref":{"doc":"TX","page":15}},{"id":"tx-100","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, which light is NOT allowed to show from the front of a regular passenger car?","o":["A white headlight","A red light","An amber parking light","An amber turn signal"],"h1":"This color in front is kept for emergency vehicles.","h2":"In Texas, a red light showing from the front of a vehicle is not allowed except on an emergency vehicle.","p":"Right. No red light may show from the front."},"es":{"q":"En Texas, ¿qué luz NO se permite que se vea desde el frente de un carro de pasajeros normal?","o":["Un faro blanco","Una luz roja","Una luz de estacionamiento ámbar","Una direccional ámbar"],"h1":"Ese color al frente está reservado para vehículos de emergencia.","h2":"En Texas, no se permite una luz roja visible desde el frente de un vehículo, excepto en un vehículo de emergencia.","p":"Correcto. Ninguna luz roja puede verse al frente."},"ref":{"doc":"TX","page":16}},{"id":"tx-101","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, how far may a load stick out beyond the left side of your car's body or fenders?","o":["No more than 3 inches","No more than 6 inches","No more than 12 inches","No more than 3 feet"],"h1":"The limit on the right side is twice this.","h2":"In Texas, nothing may extend more than three inches beyond the left side (or six inches beyond the right side) of your car's body, running board, or fenders.","p":"Right. No more than 3 inches on the left."},"es":{"q":"En Texas, ¿cuánto puede sobresalir una carga del lado izquierdo de la carrocería o los guardafangos de su carro?","o":["No más de 3 pulgadas","No más de 6 pulgadas","No más de 12 pulgadas","No más de 3 pies"],"h1":"El límite del lado derecho es el doble.","h2":"En Texas, nada puede sobresalir más de tres pulgadas del lado izquierdo (o seis pulgadas del lado derecho) de la carrocería, el estribo o los guardafangos de su carro.","p":"Correcto. No más de 3 pulgadas a la izquierda."},"ref":{"doc":"TX","page":16}},{"id":"tx-102","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, which of these devices is illegal to have on your car?","o":["A backup camera","Fog lights","A device that jams police radar or laser speed guns","A phone holder that keeps the phone out of your hand"],"h1":"It interferes with speed enforcement.","h2":"In Texas, a radar interference device made or used to disrupt a radar or laser speed-measuring device is not allowed on your vehicle.","p":"Right. Radar or laser jammers are illegal."},"es":{"q":"En Texas, ¿cuál de estos aparatos es ilegal tener en su carro?","o":["Una cámara de reversa","Faros de niebla","Un aparato que bloquea el radar o el láser de velocidad de la policía","Un soporte que mantiene el teléfono fuera de su mano"],"h1":"Interfiere con el control de velocidad.","h2":"En Texas, no se permite en su vehículo un aparato hecho o usado para interferir con un radar o láser que mide la velocidad.","p":"Correcto. Los bloqueadores de radar o láser son ilegales."},"ref":{"doc":"TX","page":16}},{"id":"tx-103","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, after-market tint on the front side windows (next to the driver) must let through at least how much light?","o":["10 percent","25 percent","50 percent","70 percent"],"h1":"It is one quarter.","h2":"In Texas, tint on the windows to the left and right of the driver must, together with the glass, let through at least 25 percent of the light.","p":"Right. At least 25 percent of the light."},"es":{"q":"En Texas, ¿cuánta luz debe dejar pasar como mínimo el polarizado agregado en las ventanas laterales delanteras (junto al conductor)?","o":["10 por ciento","25 por ciento","50 por ciento","70 por ciento"],"h1":"Es una cuarta parte.","h2":"En Texas, el polarizado de las ventanas a la izquierda y derecha del conductor, junto con el vidrio, debe dejar pasar al menos el 25 por ciento de la luz.","p":"Correcto. Al menos el 25 por ciento de la luz."},"ref":{"doc":"TX","page":null}},{"id":"tx-104","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, where may a tint strip be placed on the windshield?","o":["Only at the top, no lower than the AS-1 line or 5 inches from the top","Across the whole windshield if it is light","Only on the bottom half","Nowhere on the windshield"],"h1":"It works like a sun visor at the top.","h2":"In Texas, windshield tint may not extend below the AS-1 line or more than five inches from the top, whichever is closer to the top.","p":"Right. Only a strip at the top."},"es":{"q":"En Texas, ¿dónde se puede poner una franja de polarizado en el parabrisas?","o":["Solo arriba, sin bajar de la línea AS-1 ni de 5 pulgadas desde arriba","En todo el parabrisas si es claro","Solo en la mitad de abajo","En ninguna parte del parabrisas"],"h1":"Funciona como una visera arriba.","h2":"En Texas, el polarizado del parabrisas no puede bajar de la línea AS-1 ni de cinco pulgadas desde la parte de arriba, lo que quede más cerca de arriba.","p":"Correcto. Solo una franja arriba."},"ref":{"doc":"TX","page":null}},{"id":"tx-105","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what is the minimum liability insurance for injury or death of two or more people in one crash?","o":["$25,000","$30,000","$60,000","$100,000"],"h1":"It is twice the amount for one person.","h2":"Texas minimum liability insurance covers $60,000 for injury or death of two or more people in one crash.","p":"Right. $60,000 for two or more people."},"es":{"q":"En Texas, ¿cuál es el seguro mínimo de responsabilidad por lesiones o muerte de dos o más personas en un choque?","o":["$25,000","$30,000","$60,000","$100,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"El seguro mínimo de responsabilidad en Texas cubre $60,000 por lesiones o muerte de dos o más personas en un choque.","p":"Correcto. $60,000 para dos o más personas."},"ref":{"doc":"TX","page":18}},{"id":"tx-106","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, an officer asks for proof of insurance. Which of these is accepted?","o":["Telling the officer the name of your insurer","A receipt for gas","Your vehicle title","An image of your insurance card on your phone"],"h1":"Your phone can carry it.","h2":"In Texas, an image on a wireless device showing the information on a standard insurance card is accepted as proof of financial responsibility.","p":"Right. A picture of your insurance card on your phone is accepted."},"es":{"q":"En Texas, un oficial le pide prueba de seguro. ¿Cuál de estas se acepta?","o":["Decirle al oficial el nombre de su aseguradora","Un recibo de gasolina","El título de su vehículo","Una imagen de su tarjeta de seguro en el teléfono"],"h1":"Su teléfono puede mostrarla.","h2":"En Texas, una imagen en un aparato inalámbrico con los datos de la tarjeta de seguro estándar se acepta como prueba de responsabilidad financiera.","p":"Correcto. Se acepta una imagen de la tarjeta de seguro en su teléfono."},"ref":{"doc":"TX","page":18}},{"id":"tx-107","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a car owner is convicted a second time of driving without insurance. For how long can the court impound the car?","o":["10 days","30 days","90 days","180 days"],"h1":"It is about six months.","h2":"In Texas, on a second conviction for no insurance, an owner's vehicle is impounded for 180 days, along with a license suspension and a fine of $350 to $1,000.","p":"Right. The vehicle can be impounded for 180 days."},"es":{"q":"En Texas, el dueño de un carro es condenado por segunda vez por manejar sin seguro. ¿Por cuánto tiempo puede el tribunal confiscar el carro?","o":["10 días","30 días","90 días","180 días"],"h1":"Son como seis meses.","h2":"En Texas, en la segunda condena por no tener seguro, el vehículo del dueño se confisca por 180 días, además de la suspensión de la licencia y una multa de $350 a $1,000.","p":"Correcto. El vehículo puede quedar confiscado 180 días."},"ref":{"doc":"TX","page":18}},{"id":"tx-108","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, after certain convictions you must keep proof of insurance (SR-22) on file. For how long from the latest conviction?","o":["1 year","2 years","5 years","10 years"],"h1":"It is a couple of years.","h2":"In Texas, a driver required to maintain proof of financial responsibility must do so for two years from the most recent conviction date.","p":"Right. For two years."},"es":{"q":"En Texas, después de ciertas condenas debe mantener prueba de seguro (SR-22) registrada. ¿Por cuánto tiempo desde la condena más reciente?","o":["1 año","2 años","5 años","10 años"],"h1":"Piense en un par de años.","h2":"En Texas, el conductor que debe mantener prueba de responsabilidad financiera debe hacerlo por dos años desde la fecha de la condena más reciente.","p":"Correcto. Por dos años."},"ref":{"doc":"TX","page":19}},{"id":"tx-109","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, a driver's failure to yield causes a crash in which someone is seriously injured (serious bodily injury). What fine range applies?","o":["$200 to $500","$1,000 to $4,000","$5,000 to $10,000","Up to $100"],"h1":"It is twice the fine for a crash that causes a less serious injury.","h2":"In Texas, failing to yield the right-of-way and causing serious bodily injury brings a fine of $1,000 to $4,000.","p":"Right. The fine is $1,000 to $4,000."},"es":{"q":"En Texas, un conductor no cede el paso y causa un choque en el que alguien queda gravemente herido (lesiones corporales graves). ¿Qué rango de multa aplica?","o":["$200 a $500","$1,000 a $4,000","$5,000 a $10,000","Hasta $100"],"h1":"Es el doble de la multa por un choque con lesiones menos graves.","h2":"En Texas, no ceder el paso y causar lesiones corporales graves tiene una multa de $1,000 a $4,000.","p":"Correcto. La multa es de $1,000 a $4,000."},"ref":{"doc":"TX","page":20}},{"id":"tx-110","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you are on a dirt road that meets a paved road. No sign controls the intersection. Who must yield?","o":["Traffic on the paved road, to you","Whoever is going faster","You, to traffic on the paved road","The driver on the left"],"h1":"The bigger, better road gets priority.","h2":"In Texas, a driver on an unpaved road must yield the right-of-way to vehicles on the paved road it meets.","p":"Right. The unpaved road yields to the paved road."},"es":{"q":"En Texas, usted va por un camino de tierra que llega a una carretera pavimentada. Ninguna señal controla el cruce. ¿Quién debe ceder el paso?","o":["El tráfico pavimentado, a usted","El que vaya más rápido","Usted, al tráfico de la carretera pavimentada","El conductor de la izquierda"],"h1":"El camino más grande y mejor tiene prioridad.","h2":"En Texas, el conductor en un camino sin pavimentar debe ceder el paso a los vehículos de la carretera pavimentada.","p":"Correcto. El camino sin pavimentar cede al pavimentado."},"ref":{"doc":"TX","page":20}},{"id":"tx-111","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, you come to an intersection with no signs or signals, and both roads are the same size. A car is arriving from the road on your right. Who should go first?","o":["The car on your right","You, because you are on the left","The bigger vehicle","Whoever honks first"],"h1":"Look to your right.","h2":"At a Texas intersection with no signs, signals, or difference in road size, you must yield to a vehicle that has entered or is approaching from your right.","p":"Right. Yield to the car on your right."},"es":{"q":"En Texas, llega a un cruce sin señales ni semáforos, y las dos calles son del mismo tamaño. Un carro viene por la calle de su derecha. ¿Quién debe pasar primero?","o":["El carro de su derecha","Usted, porque está a la izquierda","El vehículo más grande","El que toque el claxon primero"],"h1":"Mire a su derecha.","h2":"En un cruce de Texas sin señales, semáforos ni diferencia en el tamaño de las calles, debe ceder el paso al vehículo que entró o se acerca por su derecha.","p":"Correcto. Ceda el paso al carro de su derecha."},"ref":{"doc":"TX","page":20}},{"id":"tx-112","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you are driving out of a parking lot driveway onto a street with a sidewalk. Where must you stop?","o":["Past the sidewalk, at the edge of the street","Only if a car is coming","Before the sidewalk","In the first traffic lane"],"h1":"People walking must be safe first.","h2":"In Texas, when entering a street from a driveway, alley, or private road, you must stop before the sidewalk and yield to pedestrians and approaching vehicles.","p":"Right. Stop before the sidewalk."},"es":{"q":"En Texas, usted sale de la entrada de un estacionamiento hacia una calle con banqueta. ¿Dónde debe detenerse?","o":["Pasando la banqueta, al borde de la calle","Solo si viene un carro","Antes de la banqueta","En el primer carril de tráfico"],"h1":"Primero deben estar seguros los peatones.","h2":"En Texas, al entrar a una calle desde una entrada de cochera, un callejón o un camino privado, debe detenerse antes de la banqueta y ceder el paso a peatones y vehículos.","p":"Correcto. Deténgase antes de la banqueta."},"ref":{"doc":"TX","page":20}},{"id":"tx-113","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, your street ends where it meets a through street (a T-intersection). What must you do?","o":["Go first, because you are turning","Stop and yield to traffic on the through street","Yield only to cars on your right","Keep going if you do not see a sign"],"h1":"The road that keeps going has priority.","h2":"In Texas, at a T-intersection, a driver on the street that ends must stop and yield the right-of-way to vehicles on the through street.","p":"Right. The street that ends yields to the through street."},"es":{"q":"En Texas, su calle termina donde se une con una calle principal (cruce en T). ¿Qué debe hacer?","o":["Pasar primero, porque usted va a dar vuelta","Detenerse y ceder el paso al tráfico de la calle principal","Ceder solo a los carros de su derecha","Seguir si no ve una señal"],"h1":"La calle que continúa tiene prioridad.","h2":"En Texas, en un cruce en T, el conductor de la calle que termina debe detenerse y ceder el paso a los vehículos de la calle principal.","p":"Correcto. La calle que termina cede a la calle principal."},"ref":{"doc":"TX","page":20}},{"id":"tx-114","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, you are driving on a highway frontage (access) road. A car is leaving the highway and entering the frontage road. Who must yield?","o":["The exiting car must yield to you","Whoever is going faster","Neither; both may go at once","You must yield to the car coming from the highway"],"h1":"Frontage road drivers must make room for cars getting on or off the highway.","h2":"In Texas, a driver on a frontage road must yield to vehicles entering the frontage road from the highway and to vehicles leaving it to enter the highway.","p":"Right. The frontage road driver yields."},"es":{"q":"En Texas, usted maneja por una carretera de acceso lateral (frontage road). Un carro sale de la autopista y entra a la calle lateral. ¿Quién debe ceder el paso?","o":["El carro que sale debe cederle el paso a usted","El que vaya más rápido","Ninguno; los dos pueden pasar","Usted debe ceder el paso al carro que viene de la autopista"],"h1":"Quien va por la calle lateral debe dar espacio a los que entran o salen de la autopista.","h2":"En Texas, el conductor en una calle lateral (frontage road) debe ceder el paso a los vehículos que entran desde la autopista y a los que salen de ella para entrar a la autopista.","p":"Correcto. El conductor de la calle lateral cede el paso."},"ref":{"doc":"TX","page":21}},{"id":"tx-115","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, on a road with three or more lanes going your way, you and a car on your left both move into the same middle lane. Who must yield?","o":["You, the driver coming from the right","The driver coming from the left","The slower driver","The larger vehicle"],"h1":"The rule favors the car coming from the left.","h2":"In Texas, on a road with three or more lanes in the same direction, a vehicle entering a lane from the right must yield to a vehicle entering the same lane from the left.","p":"Right. The car coming from the right yields."},"es":{"q":"En Texas, en una vía con tres o más carriles en su dirección, usted y un carro a su izquierda se pasan al mismo carril del medio. ¿Quién debe ceder el paso?","o":["Usted, que viene de la derecha","El que viene de la izquierda","El más lento","El vehículo más grande"],"h1":"La regla favorece al carro que viene de la izquierda.","h2":"En Texas, en una vía con tres o más carriles en la misma dirección, el vehículo que entra a un carril desde la derecha debe ceder el paso al que entra al mismo carril desde la izquierda.","p":"Correcto. El que viene de la derecha cede el paso."},"ref":{"doc":"TX","page":21}},{"id":"tx-116","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, when you must stop at a railroad crossing, how far from the nearest rail should you stop?","o":["5 to 10 feet","10 to 20 feet","15 to 50 feet","100 to 200 feet"],"h1":"Not too close, not too far.","h2":"In Texas, when you must stop at a railroad crossing, stop between 15 and 50 feet from the nearest rail.","p":"Right. Stop 15 to 50 feet from the nearest rail."},"es":{"q":"En Texas, cuando debe detenerse en un cruce de tren, ¿a qué distancia del riel más cercano debe parar?","o":["5 a 10 pies","10 a 20 pies","15 a 50 pies","100 a 200 pies"],"h1":"Ni muy cerca ni muy lejos.","h2":"En Texas, cuando debe detenerse en un cruce de tren, pare entre 15 y 50 pies del riel más cercano.","p":"Correcto. Pare a 15 a 50 pies del riel más cercano."},"ref":{"doc":"TX","page":21}},{"id":"tx-117","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, the lights at a railroad crossing are flashing but no train ever comes. Where can you find the number to report the problem to the railroad?","o":["On the back of the stop sign","On the blue and white Emergency Notification System sign at the crossing","On your insurance card","On the crossbuck post's yellow sticker"],"h1":"Look for a blue sign near the tracks.","h2":"At Texas railroad crossings, a blue and white Emergency Notification System (ENS) sign shows the railroad's emergency phone number and the crossing's ID number.","p":"Right. Use the number on the blue ENS sign."},"es":{"q":"En Texas, las luces de un cruce de tren parpadean pero nunca llega un tren. ¿Dónde encuentra el número para reportar el problema al ferrocarril?","o":["Detrás de la señal de alto","En el letrero azul y blanco del Sistema de Notificación de Emergencias en el cruce","En su tarjeta de seguro","En una calcomanía amarilla del poste de la cruz"],"h1":"Busque un letrero azul cerca de las vías.","h2":"En los cruces de tren de Texas, un letrero azul y blanco del Sistema de Notificación de Emergencias (ENS) muestra el teléfono de emergencia del ferrocarril y el número de identificación del cruce.","p":"Correcto. Use el número del letrero azul ENS."},"ref":{"doc":"TX","page":22}},{"id":"tx-118","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, a fire truck has stopped to answer an alarm on a street. What does the law say about that street?","o":["You may park there if you leave room","You may drive past at 10 mph","You may follow the fire truck to help","Do not drive or park on that street"],"h1":"Firefighters need the whole street.","h2":"In Texas, you must not drive or park on the street where a fire truck has answered an alarm.","p":"Right. Stay off that street."},"es":{"q":"En Texas, un camión de bomberos se detuvo para atender una alarma en una calle. ¿Qué dice la ley sobre esa calle?","o":["Puede estacionarse si deja espacio","Puede pasar a 10 mph","Puede seguir al camión para ayudar","No maneje ni se estacione en esa calle"],"h1":"Los bomberos necesitan toda la calle.","h2":"En Texas, no debe manejar ni estacionarse en la calle donde un camión de bomberos atiende una alarma.","p":"Correcto. No use esa calle."},"ref":{"doc":"TX","page":22}},{"id":"tx-119","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, a driver is convicted a second time within 5 years of passing a stopped school bus illegally. What fine applies?","o":["$100 to $200","$200 to $500","$500 to $750","$1,000 to $2,000"],"h1":"It is higher than the first-offense range of $500 to $1,250.","h2":"In Texas, a second school bus conviction within five years brings a fine of $1,000 to $2,000 and a possible license suspension of up to six months.","p":"Right. The fine is $1,000 to $2,000."},"es":{"q":"En Texas, un conductor es condenado por segunda vez en 5 años por pasar ilegalmente un autobús escolar detenido. ¿Qué multa aplica?","o":["$100 a $200","$200 a $500","$500 a $750","$1,000 a $2,000"],"h1":"Es más alta que la primera vez, de $500 a $1,250.","h2":"En Texas, una segunda condena por el autobús escolar en cinco años tiene una multa de $1,000 a $2,000 y una posible suspensión de licencia de hasta seis meses.","p":"Correcto. La multa es de $1,000 a $2,000."},"ref":{"doc":"TX","page":23}},{"id":"tx-120","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you are stopped behind a school bus with flashing red lights. The lights are still flashing, but the bus driver signals you to go. What may you do?","o":["Stay stopped until the bus drives away","Honk and wait","Proceed with care","Back up and go around another way"],"h1":"The bus driver can release you.","h2":"In Texas, you may pass a stopped school bus once it starts moving, the red lights stop flashing, or the bus driver signals you to proceed.","p":"Right. You may go when the driver signals you."},"es":{"q":"En Texas, usted está detenido detrás de un autobús escolar con luces rojas intermitentes. Las luces siguen encendidas, pero el chofer le hace señas para que pase. ¿Qué puede hacer?","o":["Seguir detenido hasta que el autobús se vaya","Tocar el claxon y esperar","Avanzar con cuidado","Retroceder y tomar otro camino"],"h1":"El chofer del autobús puede darle el paso.","h2":"En Texas, puede pasar un autobús escolar detenido cuando empieza a moverse, cuando dejan de parpadear las luces rojas o cuando el chofer le indica que avance.","p":"Correcto. Puede pasar cuando el chofer le hace la señal."},"ref":{"doc":"TX","page":23}},{"id":"tx-121","scope":"TX","cat":"signals","sign":null,"c":2,"en":{"q":"In Texas, you are on a one-way street, stopped at a red light, and want to turn left onto another one-way street going left. No sign forbids it. What may you do?","o":["Wait for the green light; left on red is never allowed","Turn left without stopping","Turn left after stopping and yielding","Turn only if a police officer waves you on"],"h1":"It works like a right turn on red.","h2":"In Texas, after stopping at a red light, you may turn left from a one-way street onto another one-way street, unless a sign forbids it, after yielding to pedestrians and traffic.","p":"Right. Left on red is allowed from one-way to one-way."},"es":{"q":"En Texas, está en una calle de un solo sentido, detenido en luz roja, y quiere dar vuelta a la izquierda hacia otra calle de un solo sentido que va a la izquierda. Ninguna señal lo prohíbe. ¿Qué puede hacer?","o":["Esperar la luz verde; nunca se permite izquierda en rojo","Dar vuelta sin detenerse","Dar vuelta a la izquierda después de parar y ceder el paso","Dar vuelta solo si un policía le hace señas"],"h1":"Funciona como la vuelta a la derecha en rojo.","h2":"En Texas, después de detenerse en luz roja, puede dar vuelta a la izquierda de una calle de un solo sentido a otra de un solo sentido, si ninguna señal lo prohíbe y cediendo el paso a peatones y tráfico.","p":"Correcto. Se permite izquierda en rojo de un solo sentido a un solo sentido."},"ref":{"doc":"TX","page":25}},{"id":"tx-122","scope":"TX","cat":"signals","sign":null,"c":1,"en":{"q":"In Texas, how far before a turn must you start signaling and keep signaling?","o":["At least 50 feet","At least 100 feet","At least 300 feet","At least 500 feet"],"h1":"It is about a third of a football field.","h2":"In Texas, you must signal continuously for at least 100 feet before turning or stopping.","p":"Right. Signal for at least 100 feet."},"es":{"q":"En Texas, ¿desde cuántos pies antes de una vuelta debe empezar a poner la direccional y mantenerla?","o":["Al menos 50 pies","Al menos 100 pies","Al menos 300 pies","Al menos 500 pies"],"h1":"Es como un tercio de un campo de fútbol americano.","h2":"En Texas, debe poner la señal sin interrupción durante al menos 100 pies antes de dar vuelta o detenerse.","p":"Correcto. Señale al menos 100 pies antes."},"ref":{"doc":"TX","page":38}},{"id":"tx-123","scope":"TX","cat":"signals","sign":null,"c":0,"en":{"q":"In Texas, what does the handbook suggest you do to draw attention when you signal that you are stopping?","o":["Tap the brake pedal a few times","Flash your high beams","Honk three times","Turn on your left turn signal"],"h1":"It makes your brake lights blink.","h2":"The Texas handbook says to pump your brakes a few times when signaling a stop, to attract the attention of drivers behind you.","p":"Right. Pump your brakes a few times."},"es":{"q":"En Texas, ¿qué sugiere el manual hacer para llamar la atención cuando indica que va a detenerse?","o":["Pisar el freno varias veces","Prender las luces altas","Tocar el claxon tres veces","Poner la direccional izquierda"],"h1":"Hace que sus luces de freno parpadeen.","h2":"El manual de Texas dice que bombee el freno varias veces al indicar que va a parar, para llamar la atención de los conductores de atrás.","p":"Correcto. Bombee el freno varias veces."},"ref":{"doc":"TX","page":38}},{"id":"tx-124","scope":"TX","cat":"signs","sign":null,"c":3,"en":{"q":"In Texas, you see a special flag on the back of a bicycle. What does it tell you about the rider?","o":["The rider is in a race","The rider is a police officer","The rider is carrying a heavy load","The rider may be hearing impaired, so slow down"],"h1":"The rider may not hear your horn or engine.","h2":"In Texas, a hearing-impaired flag on the back of a bicycle means the rider may be hearing impaired, so you should slow down.","p":"Right. The rider may not hear you; slow down."},"es":{"q":"En Texas, ve una bandera especial en la parte de atrás de una bicicleta. ¿Qué le dice sobre el ciclista?","o":["Que el ciclista está en una carrera","Que el ciclista es policía","Que el ciclista lleva una carga pesada","Que el ciclista puede tener problemas de audición, así que baje la velocidad"],"h1":"Puede que el ciclista no oiga su claxon ni su motor.","h2":"En Texas, la bandera de discapacidad auditiva en una bicicleta significa que el ciclista puede tener problemas de audición, así que debe bajar la velocidad.","p":"Correcto. Quizás no lo oiga; baje la velocidad."},"ref":{"doc":"TX","page":35}},{"id":"tx-125","scope":"TX","cat":"signs","sign":null,"c":0,"en":{"q":"In Texas, what fine can you get for ignoring a warning sign or driving around a barricade (not at a flooded road)?","o":["$1 to $200","$500 to $1,000","$1,000 to $2,000","Up to $4,000"],"h1":"It is the general traffic fine range.","h2":"In Texas, disobeying a warning sign or driving around a barricade is a misdemeanor with a fine of $1 to $200; it is far higher at a flooded road.","p":"Right. The fine is $1 to $200."},"es":{"q":"En Texas, ¿qué multa puede recibir por no obedecer una señal de advertencia o rodear una barricada (no en una calle inundada)?","o":["$1 a $200","$500 a $1,000","$1,000 a $2,000","Hasta $4,000"],"h1":"Es el rango general de multas de tránsito.","h2":"En Texas, desobedecer una señal de advertencia o rodear una barricada es un delito menor con multa de $1 a $200; en una calle inundada es mucho mayor.","p":"Correcto. La multa es de $1 a $200."},"ref":{"doc":"TX","page":37}},{"id":"tx-126","scope":"TX","cat":"signs","sign":null,"c":1,"en":{"q":"In Texas, you get a traffic ticket in a construction work zone while workers are present. What happens to the fine?","o":["It stays the same","It doubles","It is cut in half","It is replaced by a warning"],"h1":"Work zones protect people on foot right next to traffic.","h2":"In Texas, traffic fines double in a construction or maintenance work zone when workers are present.","p":"Right. Fines double when workers are present."},"es":{"q":"En Texas, le dan una multa de tránsito en una zona de construcción con trabajadores presentes. ¿Qué pasa con la multa?","o":["Sigue igual","Se duplica","Se reduce a la mitad","Se cambia por una advertencia"],"h1":"Las zonas de trabajo protegen a personas a pie junto al tráfico.","h2":"En Texas, las multas de tránsito se duplican en una zona de construcción o mantenimiento cuando hay trabajadores presentes.","p":"Correcto. Las multas se duplican con trabajadores presentes."},"ref":{"doc":"TX","page":37}},{"id":"tx-127","scope":"TX","cat":"signs","sign":null,"c":0,"en":{"q":"In Texas, a barricade in a work zone has diagonal stripes that slope down to the right. Which way should you go?","o":["Bear to the right","Bear to the left","Stop and wait","Go either way"],"h1":"Follow the direction the stripes slope down toward.","h2":"In Texas, stripes on a barricade or panel that slope downward to the right mean you should bear to the right.","p":"Right. Stripes sloping down to the right mean bear right."},"es":{"q":"En Texas, una barricada en una zona de trabajo tiene rayas diagonales que bajan hacia la derecha. ¿Hacia dónde debe ir?","o":["Hacia la derecha","Hacia la izquierda","Detenerse y esperar","Hacia cualquier lado"],"h1":"Siga la dirección hacia donde bajan las rayas.","h2":"En Texas, las rayas de una barricada o panel que bajan hacia la derecha indican que debe ir hacia la derecha.","p":"Correcto. Rayas que bajan a la derecha: vaya a la derecha."},"ref":{"doc":"TX","page":36}},{"id":"tx-128","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, a person on foot crosses the street in the middle of a block, not at a crosswalk. Who must yield?","o":["Drivers must always stop for them first","Only buses must yield","No one has to yield","The pedestrian must yield to vehicles"],"h1":"Outside a crosswalk, the pedestrian has less priority, though drivers must still be careful.","h2":"In Texas, a pedestrian who crosses anywhere other than a crosswalk at an intersection must yield the right-of-way to vehicles, but drivers must still try to avoid them.","p":"Right. The pedestrian must yield outside a crosswalk."},"es":{"q":"En Texas, un peatón cruza la calle a media cuadra, no en un cruce peatonal. ¿Quién debe ceder el paso?","o":["Los conductores siempre deben parar primero","Solo los autobuses deben ceder","Nadie tiene que ceder","El peatón debe ceder el paso a los vehículos"],"h1":"Fuera del cruce peatonal, el peatón tiene menos prioridad, aunque los conductores deben tener cuidado.","h2":"En Texas, un peatón que cruza fuera de un cruce peatonal en una intersección debe ceder el paso a los vehículos, pero los conductores igual deben tratar de evitarlo.","p":"Correcto. Fuera del cruce, el peatón debe ceder el paso."},"ref":{"doc":"TX","page":61}},{"id":"tx-129","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, a person is walking along a road with no sidewalk. Which side should they walk on?","o":["The right side, with traffic","In the middle of the lane","The left side, facing traffic","Either side, it does not matter"],"h1":"They should be able to see cars coming toward them.","h2":"In Texas, pedestrians should walk on the left side of the road, facing traffic, when there is no sidewalk.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Texas, una persona camina por una calle sin banqueta. ¿De qué lado debe caminar?","o":["Del lado derecho, con el tráfico","En medio del carril","Del lado izquierdo, de frente al tráfico","De cualquier lado"],"h1":"Debe poder ver los carros que vienen hacia ella.","h2":"En Texas, cuando no hay banqueta, los peatones deben caminar por el lado izquierdo de la calle, de frente al tráfico.","p":"Correcto. Camine por la izquierda, de frente al tráfico."},"ref":{"doc":"TX","page":61}},{"id":"tx-130","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, a person with a white cane is about to cross the street in front of you. What must you do?","o":["Honk so they know you are there","Drive around them quickly","Take every precaution, and stop completely if that is the only way to avoid danger","Keep going if you have a green light"],"h1":"A white cane usually means the person cannot see you.","h2":"In Texas, a white cane shows the person may be blind or disabled; drivers must take care and come to a full stop if that is needed to avoid injuring them.","p":"Right. Be careful and stop if needed."},"es":{"q":"En Texas, una persona con bastón blanco está por cruzar la calle frente a usted. ¿Qué debe hacer?","o":["Tocar el claxon para que sepa que usted está ahí","Rodearla rápido","Tomar todas las precauciones y parar por completo si es la única forma de evitar peligro","Seguir si tiene luz verde"],"h1":"Un bastón blanco por lo general indica que la persona no puede verlo.","h2":"En Texas, el bastón blanco indica que la persona puede ser ciega o tener una discapacidad; el conductor debe tener cuidado y parar por completo si es necesario para no lastimarla.","p":"Correcto. Tenga cuidado y pare si es necesario."},"ref":{"doc":"TX","page":61}},{"id":"tx-131","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, a careless driver hits and injures a person walking in a crosswalk. What kind of crime can this be?","o":["Only a traffic warning","A Class A misdemeanor, or a state jail felony if the injury is serious","A $25 fine","Not a crime if the light was green"],"h1":"Texas has a special law to protect people in crosswalks.","h2":"In Texas, a driver who with criminal negligence injures a pedestrian or cyclist in a crosswalk commits a Class A misdemeanor, or a state jail felony if the injury is serious.","p":"Right. It is a Class A misdemeanor or a felony."},"es":{"q":"En Texas, un conductor descuidado atropella y lesiona a un peatón en un cruce peatonal. ¿Qué tipo de delito puede ser?","o":["Solo una advertencia de tránsito","Un delito menor Clase A, o un delito grave estatal si la lesión es seria","Una multa de $25","No es delito si la luz estaba verde"],"h1":"Texas tiene una ley especial para proteger a las personas en los cruces peatonales.","h2":"En Texas, el conductor que por negligencia criminal lesiona a un peatón o ciclista en un cruce peatonal comete un delito menor Clase A, o un delito grave estatal (state jail felony) si la lesión es seria.","p":"Correcto. Es un delito menor Clase A o un delito grave."},"ref":{"doc":"TX","page":null}},{"id":"tx-132","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, you may not drive on the left side of the road within how many feet of an intersection, railroad crossing, bridge, or tunnel?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is the same distance as the turn signal rule.","h2":"In Texas, you must never drive on the left side of the road within 100 feet of an intersection, railroad crossing, bridge, viaduct, or tunnel.","p":"Right. Not within 100 feet."},"es":{"q":"En Texas, ¿a cuántos pies de un cruce, un paso de tren, un puente o un túnel no puede manejar por el lado izquierdo de la calle?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es la misma distancia que la regla de la direccional.","h2":"En Texas, nunca debe manejar por el lado izquierdo de la calle a menos de 100 pies de un cruce, un paso de tren, un puente, un viaducto o un túnel.","p":"Correcto. No a menos de 100 pies."},"ref":{"doc":"TX","page":38}},{"id":"tx-133","scope":"TX","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Texas, when passing on a two-lane road, you must be back in the right lane before an oncoming car comes within how many feet of you?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is about the length of 12 cars.","h2":"In Texas, when passing on a two-lane road, you must have time to return to the right lane before an approaching car comes within 200 feet of you.","p":"Right. Before it comes within 200 feet."},"es":{"q":"En Texas, al rebasar en una calle de dos carriles, ¿antes de que un carro que viene de frente llegue a cuántos pies de usted debe estar de vuelta en el carril derecho?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Es como el largo de 12 carros.","h2":"En Texas, al rebasar en una calle de dos carriles, debe tener tiempo para volver al carril derecho antes de que un carro que viene de frente llegue a 200 pies de usted.","p":"Correcto. Antes de que llegue a 200 pies."},"ref":{"doc":"TX","page":39}},{"id":"tx-134","scope":"TX","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Texas, the car ahead of you has stopped to turn left. May you pass it on the right using a paved shoulder?","o":["No, passing on the right is never allowed","Yes, even on the grass or dirt","Only if you honk first","Yes, on the paved shoulder, but never off the pavement"],"h1":"The shoulder must be paved.","h2":"In Texas, you may pass on a paved shoulder when the vehicle ahead is preparing to turn left, is slowing or stopped, or is disabled, but never by driving off the pavement.","p":"Right. On the paved shoulder only."},"es":{"q":"En Texas, el carro de adelante se detuvo para dar vuelta a la izquierda. ¿Puede rebasarlo por la derecha usando un acotamiento pavimentado?","o":["No, nunca se permite rebasar por la derecha","Sí, aun por el pasto o la tierra","Solo si toca el claxon primero","Sí, por el acotamiento pavimentado, pero nunca fuera del pavimento"],"h1":"El acotamiento debe estar pavimentado.","h2":"En Texas, puede rebasar por un acotamiento pavimentado cuando el vehículo de adelante se prepara para dar vuelta a la izquierda, va despacio o está detenido o descompuesto, pero nunca saliéndose del pavimento.","p":"Correcto. Solo por el acotamiento pavimentado."},"ref":{"doc":"TX","page":39}},{"id":"tx-135","scope":"TX","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Texas, you want to turn, but you cannot get into the proper lane by half a block before the turn. What should you do?","o":["Do not turn; keep going straight and find another way","Turn from the lane you are in","Stop in your lane until someone lets you over","Cut across quickly at the corner"],"h1":"A last-minute turn is dangerous.","h2":"In Texas, if you cannot get into the proper lane within one-half block before turning, do not turn; continue straight ahead.","p":"Right. Go straight and turn somewhere else."},"es":{"q":"En Texas, quiere dar vuelta, pero no puede pasarse al carril correcto media cuadra antes. ¿Qué debe hacer?","o":["No dar vuelta; seguir derecho y buscar otro camino","Dar vuelta desde el carril en que está","Detenerse en su carril hasta que lo dejen pasar","Cruzarse rápido en la esquina"],"h1":"Una vuelta de último momento es peligrosa.","h2":"En Texas, si no puede pasarse al carril correcto media cuadra antes de la vuelta, no dé vuelta; siga derecho.","p":"Correcto. Siga derecho y dé vuelta en otro lugar."},"ref":{"doc":"TX","page":39}},{"id":"tx-136","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 30 feet","No closer than 50 feet"],"h1":"Firefighters need room to connect a hose.","h2":"In Texas, you may not park or stand a vehicle within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet away."},"es":{"q":"En Texas, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 30 pies","No a menos de 50 pies"],"h1":"Los bomberos necesitan espacio para conectar la manguera.","h2":"En Texas, no puede estacionar ni dejar parado un vehículo a menos de 15 pies de un hidrante.","p":"Correcto. Quédese al menos a 15 pies."},"ref":{"doc":"TX","page":42}},{"id":"tx-137","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, how close to a crosswalk at an intersection may you park?","o":["10 feet","20 feet","30 feet","50 feet"],"h1":"It is a little more than the hydrant distance.","h2":"In Texas, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet away."},"es":{"q":"En Texas, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["10 pies","20 pies","30 pies","50 pies"],"h1":"Es un poco más que la distancia del hidrante.","h2":"En Texas, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese al menos a 20 pies."},"ref":{"doc":"TX","page":42}},{"id":"tx-138","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, how far from a stop sign or traffic signal at the side of the road must you park?","o":["10 feet","20 feet","30 feet","75 feet"],"h1":"Parked cars must not hide the sign from drivers.","h2":"In Texas, you may not park within 30 feet of the approach to a flashing signal, stop sign, yield sign, or traffic signal at the side of the road.","p":"Right. At least 30 feet away."},"es":{"q":"En Texas, ¿a qué distancia de una señal de alto o un semáforo al lado de la calle debe estacionarse?","o":["10 pies","20 pies","30 pies","75 pies"],"h1":"Los carros estacionados no deben tapar la señal.","h2":"En Texas, no puede estacionarse a menos de 30 pies antes de una luz intermitente, una señal de alto, una de ceda el paso o un semáforo al lado de la calle.","p":"Correcto. Al menos a 30 pies."},"ref":{"doc":"TX","page":42}},{"id":"tx-139","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, you want to park on the side of the street across from a fire station entrance. How far from the entrance must you be?","o":["15 feet","20 feet","50 feet","75 feet"],"h1":"On the same side the limit is 20 feet; across the street it is much more.","h2":"In Texas, on the side of the street opposite a fire station entrance, you may not park within 75 feet of the entrance.","p":"Right. At least 75 feet away."},"es":{"q":"En Texas, quiere estacionarse del lado de la calle de enfrente a la entrada de una estación de bomberos. ¿A qué distancia de la entrada debe estar?","o":["15 pies","20 pies","50 pies","75 pies"],"h1":"Del mismo lado el límite es 20 pies; enfrente es mucho más.","h2":"En Texas, del lado de la calle opuesto a la entrada de una estación de bomberos, no puede estacionarse a menos de 75 pies de la entrada.","p":"Correcto. Al menos a 75 pies."},"ref":{"doc":"TX","page":42}},{"id":"tx-140","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 50 feet","No closer than 15 feet","No closer than 25 feet","No closer than 100 feet"],"h1":"It is the far end of the 15-to-50-foot stopping range.","h2":"In Texas, you may not park a vehicle within 50 feet of the nearest rail of a railroad crossing.","p":"Right. At least 50 feet from the rail."},"es":{"q":"En Texas, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No a menos de 50 pies","No a menos de 15 pies","No a menos de 25 pies","No a menos de 100 pies"],"h1":"Es el extremo lejano del rango de parada de 15 a 50 pies.","h2":"En Texas, no puede estacionar un vehículo a menos de 50 pies del riel más cercano de un cruce de tren.","p":"Correcto. Al menos a 50 pies del riel."},"ref":{"doc":"TX","page":42}},{"id":"tx-141","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, you must stop on the pavement of a rural highway because you cannot get off the road. From how far away must your car be visible in each direction?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is the same number of feet as the horn rule.","h2":"In Texas, if you must stop on a highway outside a city, leave room to pass and make sure your vehicle can be seen for at least 200 feet from each direction.","p":"Right. At least 200 feet each way."},"es":{"q":"En Texas, debe detenerse sobre el pavimento de una carretera rural porque no puede salirse del camino. ¿Desde qué distancia debe verse su carro en cada dirección?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es la misma cantidad de pies que la regla del claxon.","h2":"En Texas, si debe detenerse en una carretera fuera de la ciudad, deje espacio para pasar y asegúrese de que su vehículo se vea desde al menos 200 pies en cada dirección.","p":"Correcto. Al menos 200 pies en cada dirección."},"ref":{"doc":"TX","page":42}},{"id":"tx-142","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, what are the striped areas next to disabled parking spaces for?","o":["Motorcycle parking","Short stops of 5 minutes or less","Wheelchair lifts, so no one may park there","Shopping cart return"],"h1":"People with disabilities need room to get in and out.","h2":"In Texas, you may not park in the striped areas next to disabled parking spaces, because they are for wheelchair lifts.","p":"Right. They are for wheelchair lifts."},"es":{"q":"En Texas, ¿para qué son las áreas rayadas junto a los espacios de estacionamiento para personas con discapacidad?","o":["Para estacionar motocicletas","Para paradas de 5 minutos o menos","Para rampas de silla de ruedas, así que nadie puede estacionarse ahí","Para devolver los carritos del súper"],"h1":"Las personas con discapacidad necesitan espacio para subir y bajar.","h2":"En Texas, no puede estacionarse en las áreas rayadas junto a los espacios para personas con discapacidad, porque son para las rampas de silla de ruedas.","p":"Correcto. Son para rampas de silla de ruedas."},"ref":{"doc":"TX","page":43}},{"id":"tx-143","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, is it legal to coast down a hill with the transmission in neutral?","o":["Yes, it saves gas","No, it is illegal","Yes, but only on highways","Only with a manual transmission"],"h1":"You lose engine braking and some control.","h2":"In Texas, it is illegal to coast on a downgrade with the gears or transmission in neutral.","p":"Right. Coasting in neutral is illegal."},"es":{"q":"En Texas, ¿es legal bajar una cuesta en neutral, dejando que el carro ruede solo?","o":["Sí, ahorra gasolina","No, es ilegal","Sí, pero solo en autopistas","Solo con transmisión manual"],"h1":"Pierde el freno del motor y algo de control.","h2":"En Texas, es ilegal bajar una pendiente con los cambios o la transmisión en neutral.","p":"Correcto. Rodar en neutral es ilegal."},"ref":{"doc":"TX","page":44}},{"id":"tx-144","scope":"TX","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Texas, in good conditions, what following time should you keep at speeds above 30 mph?","o":["1 second","2 seconds","4 seconds","8 seconds"],"h1":"At 30 mph or less it is 2 seconds; above that it doubles.","h2":"The Texas handbook says to keep a 4-second gap at speeds above 30 mph in good conditions, and more in poor conditions.","p":"Right. Keep at least 4 seconds above 30 mph."},"es":{"q":"En Texas, en buenas condiciones, ¿qué tiempo de distancia debe mantener a más de 30 mph?","o":["1 segundo","2 segundos","4 segundos","8 segundos"],"h1":"A 30 mph o menos son 2 segundos; arriba de eso se duplica.","h2":"El manual de Texas dice que mantenga una distancia de 4 segundos a más de 30 mph en buenas condiciones, y más en malas condiciones.","p":"Correcto. Mantenga al menos 4 segundos a más de 30 mph."},"ref":{"doc":"TX","page":45}},{"id":"tx-145","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, according to the handbook, how long does it take an average driver to think, react, and put on the brakes?","o":["Half a second","One and a half seconds","Three seconds","Five seconds"],"h1":"It is more than one second but less than two.","h2":"The Texas handbook says it takes the average person 1-1/2 seconds to think, react, and apply the brakes.","p":"Right. About one and a half seconds."},"es":{"q":"En Texas, según el manual, ¿cuánto tarda un conductor promedio en pensar, reaccionar y pisar el freno?","o":["Medio segundo","Un segundo y medio","Tres segundos","Cinco segundos"],"h1":"Es más de un segundo pero menos de dos.","h2":"El manual de Texas dice que una persona promedio tarda 1-1/2 segundos en pensar, reaccionar y aplicar los frenos.","p":"Correcto. Como un segundo y medio."},"ref":{"doc":"TX","page":45}},{"id":"tx-146","scope":"TX","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Texas, according to the handbook, about how many feet does it take to stop a car going 70 mph on dry pavement, including reaction time?","o":["109 feet","164 feet","229 feet","387 feet"],"h1":"It is more than the length of a football field.","h2":"The Texas handbook says a car going 70 mph needs about 387 feet to stop, with good brakes and tires on dry, level pavement.","p":"Right. About 387 feet."},"es":{"q":"En Texas, según el manual, ¿cuántos pies aproximados se necesitan para detener un carro a 70 mph en pavimento seco, contando el tiempo de reacción?","o":["109 pies","164 pies","229 pies","387 pies"],"h1":"Es más que el largo de un campo de fútbol americano.","h2":"El manual de Texas dice que un carro a 70 mph necesita unos 387 pies para detenerse, con buenos frenos y llantas en pavimento seco y plano.","p":"Correcto. Unos 387 pies."},"ref":{"doc":"TX","page":45}},{"id":"tx-147","scope":"TX","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Texas, unless a sign says otherwise, what is the speed limit for a car on a numbered state or U.S. highway outside an urban district?","o":["55 mph","60 mph","70 mph","80 mph"],"h1":"Numbered highways, including Farm to Market roads, get the higher limit.","h2":"In Texas, the speed limit for passenger cars on a highway numbered by Texas or the U.S. outside an urban district is 70 mph unless posted otherwise.","p":"Right. It is 70 mph."},"es":{"q":"En Texas, salvo que una señal diga otra cosa, ¿cuál es el límite de velocidad para un carro en una carretera estatal o federal numerada fuera de una zona urbana?","o":["55 mph","60 mph","70 mph","80 mph"],"h1":"Las carreteras numeradas, incluidas las Farm to Market, tienen el límite más alto.","h2":"En Texas, el límite para carros de pasajeros en una carretera numerada por Texas o EE. UU. fuera de una zona urbana es de 70 mph, salvo que se indique otro.","p":"Correcto. Es de 70 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-148","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, you drive a car on a county road outside any city. The road has no state or U.S. highway number and no speed limit sign. What is the speed limit?","o":["50 mph","60 mph","65 mph","70 mph"],"h1":"It is 10 mph less than on numbered highways.","h2":"In Texas, the speed limit for passenger cars on a highway outside an urban district that is not numbered by Texas or the U.S. is 60 mph unless posted otherwise.","p":"Right. It is 60 mph."},"es":{"q":"En Texas, maneja un carro por un camino del condado fuera de cualquier ciudad. El camino no tiene número de carretera estatal ni federal, ni señal de velocidad. ¿Cuál es el límite de velocidad?","o":["50 mph","60 mph","65 mph","70 mph"],"h1":"Es 10 mph menos que en las carreteras numeradas.","h2":"En Texas, el límite para carros de pasajeros en una carretera fuera de zona urbana sin número de Texas ni de EE. UU. es de 60 mph, salvo que se indique otro.","p":"Correcto. Es de 60 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-149","scope":"TX","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Texas, what is the speed limit on a public beach where the county has set one?","o":["15 mph","25 mph","30 mph","35 mph"],"h1":"It is the same as in an alley.","h2":"In Texas, the speed limit on beaches and on county roads next to a public beach, if declared by the county, is 15 mph.","p":"Right. It is 15 mph."},"es":{"q":"En Texas, ¿cuál es el límite de velocidad en una playa pública donde el condado lo fijó?","o":["15 mph","25 mph","30 mph","35 mph"],"h1":"Es el mismo que en un callejón.","h2":"En Texas, el límite en playas y en caminos del condado junto a una playa pública, si el condado lo declara, es de 15 mph.","p":"Correcto. Es de 15 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-150","scope":"TX","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Texas, what is the highest speed limit that may be posted on some limited-access highways?","o":["65 mph","70 mph","75 mph","85 mph"],"h1":"Texas has some of the fastest posted limits in the country.","h2":"The Texas handbook says many limited-access highways have speed limits of 75 up to 85 mph.","p":"Right. Up to 85 mph."},"es":{"q":"En Texas, ¿cuál es el límite de velocidad más alto que se puede poner en algunas autopistas de acceso controlado?","o":["65 mph","70 mph","75 mph","85 mph"],"h1":"Texas tiene algunos de los límites más altos del país.","h2":"El manual de Texas dice que muchas autopistas de acceso controlado tienen límites de 75 hasta 85 mph.","p":"Correcto. Hasta 85 mph."},"ref":{"doc":"TX","page":46}},{"id":"tx-151","scope":"TX","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Texas, the \"slow down or move over\" law covers emergency vehicles. Which of these is also covered when stopped with its lights on?","o":["A tow truck","A school bus that is parked for the night","A pizza delivery car","A taxi"],"h1":"Think of vehicles that work beside traffic on the roadside.","h2":"In Texas, the slow down or move over law also covers stopped tow trucks, utility service vehicles, and TxDOT or highway work vehicles with their lights on.","p":"Right. Tow trucks are covered."},"es":{"q":"En Texas, la ley de \"bajar la velocidad o cambiarse de carril\" cubre a los vehículos de emergencia. ¿Cuál de estos también está cubierto cuando está detenido con las luces encendidas?","o":["Una grúa","Un autobús escolar estacionado por la noche","Un carro repartidor de pizza","Un taxi"],"h1":"Piense en vehículos que trabajan al lado del tráfico.","h2":"En Texas, la ley de bajar la velocidad o cambiarse de carril también cubre a grúas, vehículos de servicios públicos y vehículos de TxDOT u obras de carretera detenidos con las luces encendidas.","p":"Correcto. Las grúas están cubiertas."},"ref":{"doc":"TX","page":46}},{"id":"tx-152","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, where may you not stop, stand, or park, even for a moment?","o":["In a marked parking space","Beside a curb with no signs","In a driveway you own","On a bridge on a highway"],"h1":"It is a raised structure where stopped cars block traffic.","h2":"In Texas, you must not park, stop, or let a vehicle stand on a bridge or other elevated structure on a highway, or in a highway tunnel.","p":"Right. Do not stop on a highway bridge."},"es":{"q":"En Texas, ¿dónde no puede detenerse, quedarse parado ni estacionarse, ni por un momento?","o":["En un espacio de estacionamiento marcado","Junto a una acera sin señales","En la entrada de su propia cochera","En un puente de una carretera"],"h1":"Es una estructura elevada donde un carro parado bloquea el tráfico.","h2":"En Texas, no debe estacionarse, detenerse ni dejar parado un vehículo en un puente u otra estructura elevada de una carretera, ni en un túnel.","p":"Correcto. No se detenga en un puente de carretera."},"ref":{"doc":"TX","page":42}},{"id":"tx-153","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, where does the law forbid backing up a vehicle at all?","o":["Out of a parking space","On the shoulder or lanes of a freeway (controlled-access highway)","In your own driveway","In a store parking lot"],"h1":"Traffic there moves fast and does not expect a car coming backward.","h2":"In Texas, a driver may not back up on the shoulder or roadway of a limited-access or controlled-access highway, and may back up elsewhere only when it is safe.","p":"Right. Never back up on a freeway or its shoulder."},"es":{"q":"En Texas, ¿dónde prohíbe la ley por completo manejar en reversa?","o":["Al salir de un espacio de estacionamiento","En el acotamiento o los carriles de una autopista (de acceso controlado)","En la entrada de su cochera","En el estacionamiento de una tienda"],"h1":"Ahí el tráfico va rápido y no espera un carro en reversa.","h2":"En Texas, un conductor no puede retroceder en el acotamiento ni en los carriles de una autopista de acceso limitado o controlado, y en otros lugares solo cuando sea seguro.","p":"Correcto. Nunca retroceda en una autopista ni en su acotamiento."},"ref":{"doc":"TX","page":null}},{"id":"tx-154","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, besides at night, you must use headlights whenever you cannot clearly see people or vehicles at what distance?","o":["200 feet","500 feet","1,000 feet","1 mile"],"h1":"It is a little more than three football fields.","h2":"In Texas, you must use headlights from 30 minutes after sunset to 30 minutes before sunrise, and any time you cannot clearly see people or vehicles at least 1,000 feet away.","p":"Right. When you cannot see 1,000 feet ahead."},"es":{"q":"En Texas, además de la noche, debe usar los faros siempre que no pueda ver bien a personas o vehículos a cierta distancia. ¿Cuál es esa distancia?","o":["200 pies","500 pies","1,000 pies","1 milla"],"h1":"Es un poco más que tres campos de fútbol americano.","h2":"En Texas, debe usar los faros desde 30 minutos después de la puesta del sol hasta 30 minutos antes del amanecer, y siempre que no pueda ver bien personas o vehículos a 1,000 pies.","p":"Correcto. Cuando no puede ver a 1,000 pies."},"ref":{"doc":"TX","page":47}},{"id":"tx-155","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, you are using high beams at night. A car comes toward you. Within what distance must you switch to low beams?","o":["200 feet","500 feet","1,000 feet","1,500 feet"],"h1":"It is half of 1,000.","h2":"In Texas, use your low beams when you are within 500 feet of an approaching vehicle.","p":"Right. Dim your lights within 500 feet."},"es":{"q":"En Texas, maneja de noche con las luces altas. Viene un carro de frente. ¿A qué distancia debe cambiar a luces bajas?","o":["200 pies","500 pies","1,000 pies","1,500 pies"],"h1":"Es la mitad de 1,000.","h2":"En Texas, use las luces bajas cuando esté a menos de 500 pies de un vehículo que se acerca.","p":"Correcto. Baje las luces a 500 pies."},"ref":{"doc":"TX","page":47}},{"id":"tx-156","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, you are following another car at night. Within what distance behind it should you use low beams?","o":["300 feet","100 feet","600 feet","1,000 feet"],"h1":"It is the length of a football field.","h2":"In Texas, use your low beams when you are following within 300 feet behind another vehicle.","p":"Right. Use low beams within 300 feet."},"es":{"q":"En Texas, de noche va detrás de otro carro. ¿A qué distancia detrás de él debe usar luces bajas?","o":["300 pies","100 pies","600 pies","1,000 pies"],"h1":"Es el largo de un campo de fútbol americano.","h2":"En Texas, use las luces bajas cuando vaya a menos de 300 pies detrás de otro vehículo.","p":"Correcto. Use luces bajas a menos de 300 pies."},"ref":{"doc":"TX","page":47}},{"id":"tx-157","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, you must park on an unlit highway at night. Which lights should you leave on?","o":["High beams","No lights, to save the battery","Parking lights or low-beam headlights","Only the dome light"],"h1":"Other drivers must see you without being blinded.","h2":"In Texas, if you must park on an unlighted highway at night, leave your parking lights or low-beam headlights on.","p":"Right. Parking lights or low beams."},"es":{"q":"En Texas, de noche debe estacionarse en una carretera sin alumbrado. ¿Qué luces debe dejar encendidas?","o":["Las luces altas","Ninguna, para ahorrar batería","Las luces de estacionamiento o las luces bajas","Solo la luz interior"],"h1":"Los demás deben verlo sin quedar deslumbrados.","h2":"En Texas, si debe estacionarse de noche en una carretera sin alumbrado, deje encendidas las luces de estacionamiento o las luces bajas.","p":"Correcto. Luces de estacionamiento o bajas."},"ref":{"doc":"TX","page":47}},{"id":"tx-158","scope":"TX","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Texas, about how far ahead of a highway exit are exit signs usually placed?","o":["100 feet","500 feet","100 yards","At least 1,000 yards"],"h1":"It is more than half a mile.","h2":"In Texas, exit signs are usually placed at least 1,000 yards ahead of the exit, so you can move into the proper lane early.","p":"Right. At least 1,000 yards ahead."},"es":{"q":"En Texas, ¿a qué distancia aproximada antes de una salida de autopista se ponen normalmente los letreros de salida?","o":["100 pies","500 pies","100 yardas","Al menos 1,000 yardas"],"h1":"Es más de media milla.","h2":"En Texas, los letreros de salida normalmente se ponen al menos 1,000 yardas antes de la salida, para que pueda pasarse al carril correcto con tiempo.","p":"Correcto. Al menos 1,000 yardas antes."},"ref":{"doc":"TX","page":48}},{"id":"tx-159","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, to fight highway hypnosis on a long trip, how often does the handbook say to stop?","o":["Every 30 minutes","Every 2 hours or 100 miles","Every 5 hours","Only when you feel sleepy"],"h1":"Stop even if you feel fine.","h2":"The Texas handbook says to stop at least every two hours or every 100 miles, get out, and walk around, even if you feel well.","p":"Right. Every 2 hours or 100 miles."},"es":{"q":"En Texas, para combatir la hipnosis de carretera en un viaje largo, ¿cada cuánto dice el manual que debe parar?","o":["Cada 30 minutos","Cada 2 horas o 100 millas","Cada 5 horas","Solo cuando tenga sueño"],"h1":"Pare aunque se sienta bien.","h2":"El manual de Texas dice que pare al menos cada dos horas o cada 100 millas, se baje y camine, aunque se sienta bien.","p":"Correcto. Cada 2 horas o 100 millas."},"ref":{"doc":"TX","page":48}},{"id":"tx-160","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, your car broke down at the side of the road. What does the handbook suggest to show you need help?","o":["Leave the driver's door wide open","Tie a white cloth to the antenna or door handle, or raise the hood","Turn on your high beams","Stand in the traffic lane and wave"],"h1":"Use something white that others can see easily.","h2":"The Texas handbook says to tie a white cloth to the antenna, door handle, or another visible place, or raise the hood if you have no cloth.","p":"Right. A white cloth or a raised hood."},"es":{"q":"En Texas, su carro se descompuso al lado de la calle. ¿Qué sugiere el manual para mostrar que necesita ayuda?","o":["Dejar la puerta del conductor abierta","Amarrar un trapo blanco a la antena o la manija, o levantar el cofre","Prender las luces altas","Pararse en el carril y hacer señas"],"h1":"Use algo blanco que se vea fácilmente.","h2":"El manual de Texas dice que amarre un trapo blanco a la antena, la manija de la puerta u otro lugar visible, o que levante el cofre si no tiene trapo.","p":"Correcto. Un trapo blanco o el cofre levantado."},"ref":{"doc":"TX","page":48}},{"id":"tx-161","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, you are driving inside a roundabout that has two lanes. What should you not do?","o":["Use your signal to exit","Give room to large trucks","Watch for pedestrians at the exits","Change lanes inside the circle"],"h1":"Choose your lane before you enter.","h2":"In a Texas multi-lane roundabout, pick the correct lane from the advance signs before entering, and do not change lanes while driving in the circle.","p":"Right. Do not change lanes inside the circle."},"es":{"q":"En Texas, maneja dentro de una glorieta de dos carriles. ¿Qué no debe hacer?","o":["Usar la direccional para salir","Dar espacio a los camiones grandes","Fijarse en los peatones en las salidas","Cambiarse de carril dentro del círculo"],"h1":"Escoja su carril antes de entrar.","h2":"En una glorieta de varios carriles en Texas, escoja el carril correcto según los letreros antes de entrar, y no se cambie de carril dentro del círculo.","p":"Correcto. No se cambie de carril dentro del círculo."},"ref":{"doc":"TX","page":50}},{"id":"tx-162","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, how deep must water be to reach the bottom of most passenger cars, causing loss of control and possible stalling?","o":["6 inches","2 inches","18 inches","3 feet"],"h1":"It is half of the depth that floats many cars.","h2":"The Texas handbook says six inches of water will reach the bottom of most passenger cars, causing loss of control and possible stalling.","p":"Right. Just 6 inches."},"es":{"q":"En Texas, ¿qué profundidad de agua basta para llegar a la parte de abajo de la mayoría de los carros, causando pérdida de control y que se apaguen?","o":["6 pulgadas","2 pulgadas","18 pulgadas","3 pies"],"h1":"Es la mitad de la profundidad que hace flotar a muchos carros.","h2":"El manual de Texas dice que seis pulgadas de agua llegan a la parte de abajo de la mayoría de los carros, causando pérdida de control y que se puedan apagar.","p":"Correcto. Solo 6 pulgadas."},"ref":{"doc":"TX","page":50}},{"id":"tx-163","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, on a level highway, about how much longer does it take to pass a large truck than to pass a car?","o":["No longer","Half a second longer","3 to 5 seconds longer","30 seconds longer"],"h1":"Trucks are much longer than cars.","h2":"The Texas handbook says it takes three to five seconds longer to pass a truck than a car on a level highway.","p":"Right. About 3 to 5 seconds longer."},"es":{"q":"En Texas, en una carretera plana, ¿cuánto tiempo más se tarda en rebasar un camión grande que un carro?","o":["Nada más","Medio segundo más","De 3 a 5 segundos más","30 segundos más"],"h1":"Los camiones son mucho más largos que los carros.","h2":"El manual de Texas dice que se tarda de tres a cinco segundos más en rebasar un camión que un carro en una carretera plana.","p":"Correcto. De 3 a 5 segundos más."},"ref":{"doc":"TX","page":51}},{"id":"tx-164","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, a car at 55 mph can stop in about 240 feet. How far may a fully loaded tractor-trailer need at the same speed?","o":["About 100 feet","About 240 feet, the same","More than 400 feet","About 150 feet"],"h1":"Heavy trucks need much more room than cars.","h2":"The Texas handbook says a fully loaded tractor-trailer may take more than 400 feet to stop from 55 mph, compared with about 240 feet for a car.","p":"Right. More than 400 feet."},"es":{"q":"En Texas, un carro a 55 mph puede detenerse en unos 240 pies. ¿Cuánto puede necesitar un tráiler totalmente cargado a la misma velocidad?","o":["Unos 100 pies","Unos 240 pies, lo mismo","Más de 400 pies","Unos 150 pies"],"h1":"Los camiones pesados necesitan mucho más espacio que los carros.","h2":"El manual de Texas dice que un tráiler totalmente cargado puede necesitar más de 400 pies para detenerse desde 55 mph, contra unos 240 pies de un carro.","p":"Correcto. Más de 400 pies."},"ref":{"doc":"TX","page":51}},{"id":"tx-165","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, a large truck is coming toward you on a two-lane road. What does the wind turbulence between you do?","o":["It pushes the vehicles apart, so keep to the far side of your lane","It pulls the vehicles together","Nothing at all","It slows your car down to a stop"],"h1":"Keep as far to your side as you safely can.","h2":"The Texas handbook says turbulence between a truck and a car pushes them apart, so keep as far to the side as possible to avoid a sideswipe.","p":"Right. It pushes you apart."},"es":{"q":"En Texas, un camión grande viene de frente en una calle de dos carriles. ¿Qué hace el viento entre los dos vehículos?","o":["Los empuja para separarlos, así que manténgase del lado lejano de su carril","Los jala para juntarlos","Nada","Hace que su carro se detenga"],"h1":"Manténgase lo más a su lado que pueda con seguridad.","h2":"El manual de Texas dice que la turbulencia entre un camión y un carro los empuja para separarlos, así que manténgase lo más a un lado posible para evitar un roce.","p":"Correcto. Los empuja para separarlos."},"ref":{"doc":"TX","page":51}},{"id":"tx-166","scope":"TX","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Texas, what is the most common crash between a car and a motorcycle?","o":["A motorcycle hitting a parked car","A car backing into a motorcycle in a driveway","A motorcycle running a red light","A car turning left in front of a motorcycle at an intersection"],"h1":"It happens when drivers misjudge an oncoming motorcycle.","h2":"The Texas handbook says the most common car-motorcycle crash is at an intersection when a car makes a left turn in front of a motorcycle.","p":"Right. A car turning left in front of a motorcycle."},"es":{"q":"En Texas, ¿cuál es el choque más común entre un carro y una motocicleta?","o":["Una moto que choca con un carro estacionado","Un carro que retrocede contra una moto en una cochera","Una moto que se pasa un alto","Un carro que da vuelta a la izquierda frente a una moto en un cruce"],"h1":"Pasa cuando el conductor calcula mal a una moto que viene de frente.","h2":"El manual de Texas dice que el choque más común entre carro y motocicleta es en un cruce, cuando un carro da vuelta a la izquierda frente a una moto.","p":"Correcto. Un carro que da vuelta a la izquierda frente a la moto."},"ref":{"doc":"TX","page":52}},{"id":"tx-167","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, you stop behind a motorcycle at a red light. How much space does the handbook recommend leaving?","o":["1 foot","3 feet","Half a car length","A full vehicle length"],"h1":"If someone hits you from behind, you should not be pushed into the rider.","h2":"The Texas handbook recommends stopping a full vehicle length behind a motorcycle at intersections, signals, or crossings.","p":"Right. A full vehicle length."},"es":{"q":"En Texas, se detiene detrás de una motocicleta en un semáforo en rojo. ¿Cuánto espacio recomienda dejar el manual?","o":["1 pie","3 pies","Medio carro","El largo de un vehículo completo"],"h1":"Si alguien le pega por detrás, no debe empujarlo contra el motociclista.","h2":"El manual de Texas recomienda detenerse a un largo de vehículo completo detrás de una motocicleta en cruces, semáforos o pasos.","p":"Correcto. El largo de un vehículo completo."},"ref":{"doc":"TX","page":53}},{"id":"tx-168","scope":"TX","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Texas, traffic is stopped on a highway. May a motorcycle ride between the two lanes of stopped cars (lane splitting)?","o":["No, riding between lanes is illegal","Yes, at any speed","Yes, if traffic is stopped","Yes, but only on the shoulder side"],"h1":"A motorcycle is entitled to a full lane, but not the space between lanes.","h2":"In Texas, a motorcyclist may not ride between lanes of traffic moving in the same direction, and may not pass a vehicle in the same lane.","p":"Right. Lane splitting is illegal in Texas."},"es":{"q":"En Texas, el tráfico está detenido en una autopista. ¿Puede una motocicleta pasar entre los dos carriles de carros detenidos?","o":["No, ir entre carriles es ilegal","Sí, a cualquier velocidad","Sí, si el tráfico está detenido","Sí, pero solo del lado del acotamiento"],"h1":"La moto tiene derecho a un carril completo, pero no al espacio entre carriles.","h2":"En Texas, un motociclista no puede ir entre carriles de tráfico que van en la misma dirección, ni rebasar a un vehículo dentro del mismo carril.","p":"Correcto. Ir entre carriles es ilegal en Texas."},"ref":{"doc":"TX","page":null}},{"id":"tx-169","scope":"TX","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Texas, how many motorcycles may ride side by side in one traffic lane?","o":["One only","Two","Three","Any number"],"h1":"They may ride in pairs.","h2":"In Texas, a motorcycle may ride two abreast in a single lane with another motorcycle, but not more than two.","p":"Right. Two motorcycles may share a lane side by side."},"es":{"q":"En Texas, ¿cuántas motocicletas pueden ir lado a lado en un mismo carril?","o":["Solo una","Dos","Tres","Cualquier número"],"h1":"Pueden ir en parejas.","h2":"En Texas, una motocicleta puede ir lado a lado con otra en un mismo carril, pero no más de dos.","p":"Correcto. Dos motos pueden compartir un carril lado a lado."},"ref":{"doc":"TX","page":null}},{"id":"tx-170","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, which motorcycle riders must always wear a helmet?","o":["Only riders on highways","No one; helmets are optional for all","Riders and passengers younger than 21","Only riders older than 65"],"h1":"Adults 21 and older can be exempt if they took a safety course or have health insurance.","h2":"In Texas, motorcycle riders and passengers younger than 21 must wear a helmet; those 21 or older may skip it only if they completed a safety course or have health insurance that covers crash injuries.","p":"Right. Everyone under 21 must wear a helmet."},"es":{"q":"En Texas, ¿qué motociclistas siempre deben usar casco?","o":["Solo los que van por autopistas","Nadie; el casco es opcional para todos","Los conductores y pasajeros menores de 21 años","Solo los mayores de 65 años"],"h1":"Los adultos de 21 o más pueden quedar exentos si tomaron un curso o tienen seguro médico.","h2":"En Texas, los motociclistas y pasajeros menores de 21 años deben usar casco; los de 21 o más solo pueden no usarlo si completaron un curso de seguridad o tienen seguro médico que cubra lesiones por choque.","p":"Correcto. Todos los menores de 21 deben usar casco."},"ref":{"doc":"TX","page":null}},{"id":"tx-171","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, why must you be extra careful near light rail trains in city streets?","o":["They always stop for cars","They are very quiet, quieter than most buses and cars","They only run at night","They can swerve around your car"],"h1":"You may not hear one coming.","h2":"The Texas handbook warns that light rail is very quiet, quieter than most buses and cars, so you may not hear a train coming.","p":"Right. Light rail is very quiet."},"es":{"q":"En Texas, ¿por qué debe tener mucho cuidado cerca de los trenes ligeros en las calles de la ciudad?","o":["Siempre se detienen por los carros","Son muy silenciosos, más que la mayoría de los autobuses y carros","Solo funcionan de noche","Pueden esquivar su carro"],"h1":"Quizás no lo oiga venir.","h2":"El manual de Texas advierte que el tren ligero es muy silencioso, más que la mayoría de los autobuses y carros, así que tal vez no lo oiga venir.","p":"Correcto. El tren ligero es muy silencioso."},"ref":{"doc":"TX","page":53}},{"id":"tx-172","scope":"TX","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Texas, a cyclist does not have to keep to the right edge in an outside lane with no bike lane if the lane is narrower than what?","o":["10 feet","14 feet","20 feet","24 feet"],"h1":"A car and a bike cannot safely share a lane this narrow.","h2":"In Texas, a slower cyclist need not ride near the right edge in an outside lane less than 14 feet wide with no bike lane next to it, or any lane too narrow to share safely.","p":"Right. Less than 14 feet wide."},"es":{"q":"En Texas, un ciclista no tiene que ir pegado a la orilla derecha en un carril exterior sin ciclovía si el carril es angosto. ¿Menos de qué ancho?","o":["10 pies","14 pies","20 pies","24 pies"],"h1":"Un carro y una bici no pueden compartir con seguridad un carril tan angosto.","h2":"En Texas, un ciclista más lento no tiene que ir cerca de la orilla derecha en un carril exterior de menos de 14 pies de ancho sin ciclovía al lado, ni en un carril demasiado angosto para compartir.","p":"Correcto. Menos de 14 pies de ancho."},"ref":{"doc":"TX","page":62}},{"id":"tx-173","scope":"TX","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Texas, you want to turn right and a bicycle is riding next to you on the right. What should you do?","o":["Speed up and turn in front of it","Honk so the rider stops","Slow down and merge behind the bicycle, then turn","Turn quickly before the rider reaches the corner"],"h1":"Never cut across a cyclist's path.","h2":"In Texas, a motorist turning right should slow down and merge with bicycle traffic instead of turning directly across the bicycle's path.","p":"Right. Merge behind the bicycle, then turn."},"es":{"q":"En Texas, quiere dar vuelta a la derecha y una bicicleta va junto a usted por la derecha. ¿Qué debe hacer?","o":["Acelerar y dar vuelta delante de ella","Tocar el claxon para que el ciclista se detenga","Bajar la velocidad, ponerse detrás de la bicicleta y luego dar vuelta","Dar vuelta rápido antes de que el ciclista llegue a la esquina"],"h1":"Nunca se atraviese en el camino de un ciclista.","h2":"En Texas, el conductor que va a dar vuelta a la derecha debe bajar la velocidad e incorporarse detrás del tráfico de bicicletas, en vez de cruzar directamente su camino.","p":"Correcto. Póngase detrás de la bicicleta y luego dé vuelta."},"ref":{"doc":"TX","page":53}},{"id":"tx-174","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, a bicycle ridden at night must have a white front lamp visible from at least how far?","o":["50 feet","100 feet","300 feet","500 feet"],"h1":"It is the same distance as a red rear light, if one is used.","h2":"In Texas, a bicycle used at night must have a front lamp with a white light visible from at least 500 feet, plus a red rear reflector.","p":"Right. At least 500 feet."},"es":{"q":"En Texas, ¿desde qué distancia mínima debe verse la luz blanca delantera de una bicicleta que se usa de noche?","o":["50 pies","100 pies","300 pies","500 pies"],"h1":"Es la misma distancia que una luz roja trasera, si se usa.","h2":"En Texas, una bicicleta que se usa de noche debe tener una luz delantera blanca visible desde al menos 500 pies, además de un reflector rojo atrás.","p":"Correcto. Al menos 500 pies."},"ref":{"doc":"TX","page":63}},{"id":"tx-175","scope":"TX","cat":"signals","sign":null,"c":0,"en":{"q":"In Texas, a cyclist holds the right arm straight out to the side. What does this mean?","o":["The cyclist is turning right","The cyclist is turning left","The cyclist is stopping","The cyclist wants you to pass"],"h1":"Texas allows two ways to show this turn: left arm up or right arm out.","h2":"In Texas, a cyclist may signal a right turn with the left arm pointing up or with the right arm held straight out to the side.","p":"Right. The cyclist is turning right."},"es":{"q":"En Texas, un ciclista extiende el brazo derecho recto hacia un lado. ¿Qué significa?","o":["Va a dar vuelta a la derecha","Va a dar vuelta a la izquierda","Se va a detener","Quiere que usted lo rebase"],"h1":"Texas permite dos formas de indicar esta vuelta: brazo izquierdo arriba o brazo derecho extendido.","h2":"En Texas, un ciclista puede indicar vuelta a la derecha con el brazo izquierdo hacia arriba o con el brazo derecho extendido hacia un lado.","p":"Correcto. Va a dar vuelta a la derecha."},"ref":{"doc":"TX","page":62}},{"id":"tx-176","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, does state law require all adult bicycle riders to wear a helmet?","o":["Yes, everywhere in Texas","Only on highways","Only at night","No; a helmet may be required depending on local laws"],"h1":"Some cities have their own rules.","h2":"The Texas handbook says a bicycle rider may be required to wear a helmet depending on local laws; there is no statewide helmet law for adult cyclists.","p":"Right. It depends on local laws."},"es":{"q":"En Texas, ¿la ley del estado obliga a todos los ciclistas adultos a usar casco?","o":["Sí, en todo Texas","Solo en carreteras","Solo de noche","No; puede ser obligatorio según las leyes locales"],"h1":"Algunas ciudades tienen sus propias reglas.","h2":"El manual de Texas dice que un ciclista puede estar obligado a usar casco según las leyes locales; no hay una ley estatal de casco para ciclistas adultos.","p":"Correcto. Depende de las leyes locales."},"ref":{"doc":"TX","page":63}},{"id":"tx-177","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, according to the handbook, about how long does the body take to get rid of the alcohol in one drink?","o":["15 minutes","About one hour","About three hours","A whole day"],"h1":"Only time sobers you up, roughly one drink at a time.","h2":"The Texas handbook says it takes about one hour for the body to rid itself of each drink.","p":"Right. About one hour per drink."},"es":{"q":"En Texas, según el manual, ¿cuánto tarda más o menos el cuerpo en eliminar el alcohol de una bebida?","o":["15 minutos","Como una hora","Como tres horas","Un día entero"],"h1":"Solo el tiempo quita la borrachera, más o menos una bebida a la vez.","h2":"El manual de Texas dice que el cuerpo tarda como una hora en eliminar cada bebida.","p":"Correcto. Como una hora por bebida."},"ref":{"doc":"TX","page":56}},{"id":"tx-178","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, a driver under 21 fails a breath test (some alcohol, but below 0.08) for the second time. How long is the license suspended?","o":["30 days","60 days","120 days","2 years"],"h1":"It is twice the first-offense suspension of 60 days.","h2":"In Texas, a minor whose breath or blood test shows a detectable amount of alcohol for a second time has the license suspended for 120 days.","p":"Right. A second failure means 120 days."},"es":{"q":"En Texas, un conductor menor de 21 años reprueba por segunda vez una prueba de aliento (algo de alcohol, pero menos de 0.08). ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","60 días","120 días","2 años"],"h1":"Es el doble de la primera suspensión de 60 días.","h2":"En Texas, a un menor cuya prueba de aliento o sangre muestra alcohol por segunda vez se le suspende la licencia por 120 días.","p":"Correcto. La segunda vez son 120 días."},"ref":{"doc":"TX","page":57}},{"id":"tx-179","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a driver under 21 refuses a breath or blood test for the second time. How long is the license suspended?","o":["60 days","90 days","180 days","2 years"],"h1":"The first refusal is 180 days; the second is much longer.","h2":"In Texas, a minor who refuses a breath or blood test a second time has the license suspended for two years.","p":"Right. Two years for a second refusal."},"es":{"q":"En Texas, un conductor menor de 21 años se niega por segunda vez a una prueba de aliento o sangre. ¿Por cuánto tiempo se suspende la licencia?","o":["60 días","90 días","180 días","2 años"],"h1":"La primera negativa son 180 días; la segunda es mucho más.","h2":"En Texas, a un menor que se niega por segunda vez a la prueba de aliento o sangre se le suspende la licencia por dos años.","p":"Correcto. Dos años por la segunda negativa."},"ref":{"doc":"TX","page":57}},{"id":"tx-180","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, a 19-year-old is convicted for the first time of driving under the influence (any detectable alcohol). Which penalty applies?","o":["Only a written warning","Two years in prison","A fine up to $500, 20 to 40 hours of community service, and an alcohol awareness course","A $10,000 fine"],"h1":"It is a Class C misdemeanor, but with community service and a class.","h2":"In Texas, a minor's first DUI conviction is a Class C misdemeanor with a fine up to $500, 20 to 40 hours of community service, and a required alcohol awareness course.","p":"Right. Up to $500, community service, and an alcohol course."},"es":{"q":"En Texas, un joven de 19 años es condenado por primera vez por manejar bajo la influencia (cualquier cantidad de alcohol). ¿Qué pena aplica?","o":["Solo una advertencia por escrito","Dos años de prisión","Multa de hasta $500, de 20 a 40 horas de servicio comunitario y un curso sobre el alcohol","Una multa de $10,000"],"h1":"Es un delito menor Clase C, pero con servicio comunitario y un curso.","h2":"En Texas, la primera condena de un menor por DUI es un delito menor Clase C con multa de hasta $500, de 20 a 40 horas de servicio comunitario y un curso obligatorio sobre el alcohol.","p":"Correcto. Hasta $500, servicio comunitario y un curso."},"ref":{"doc":"TX","page":57}},{"id":"tx-181","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, an adult takes a breath test and it shows 0.08 or more. For a first time, how long can the license be suspended?","o":["90 days","30 days","2 years","5 years"],"h1":"It is about three months, shorter than the 180 days for refusing.","h2":"In Texas, an adult whose breath or blood test shows 0.08 or more may have the license suspended for 90 days, or up to 365 days for later offenses.","p":"Right. 90 days for a first failed test."},"es":{"q":"En Texas, un adulto hace la prueba de aliento y marca 0.08 o más. Por primera vez, ¿por cuánto tiempo se puede suspender la licencia?","o":["90 días","30 días","2 años","5 años"],"h1":"Son como tres meses, menos que los 180 días por negarse.","h2":"En Texas, a un adulto cuya prueba de aliento o sangre marca 0.08 o más se le puede suspender la licencia por 90 días, o hasta 365 días en infracciones posteriores.","p":"Correcto. 90 días por la primera prueba reprobada."},"ref":{"doc":"TX","page":58}},{"id":"tx-182","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, how much jail time can an adult get for a first DWI?","o":["None","72 hours to 180 days","2 to 10 years","Exactly 30 days"],"h1":"There is a minimum of three days.","h2":"In Texas, a first DWI offense can bring 72 hours to 180 days in jail, a fine up to $2,000, and a license suspension.","p":"Right. 72 hours to 180 days."},"es":{"q":"En Texas, ¿cuánto tiempo de cárcel puede recibir un adulto por un primer DWI?","o":["Nada","De 72 horas a 180 días","De 2 a 10 años","Exactamente 30 días"],"h1":"Hay un mínimo de tres días.","h2":"En Texas, un primer DWI puede traer de 72 horas a 180 días de cárcel, una multa de hasta $2,000 y la suspensión de la licencia.","p":"Correcto. De 72 horas a 180 días."},"ref":{"doc":"TX","page":58}},{"id":"tx-183","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, what is the highest fine for a second DWI offense?","o":["$500","$2,000","$4,000","$10,000"],"h1":"It is twice the first-offense fine.","h2":"In Texas, a second DWI offense can bring a fine up to $4,000, 30 days to 1 year in jail, and a license suspension of 180 days to 2 years.","p":"Right. Up to $4,000."},"es":{"q":"En Texas, ¿cuál es la multa máxima por un segundo DWI?","o":["$500","$2,000","$4,000","$10,000"],"h1":"Es el doble de la multa de la primera vez.","h2":"En Texas, un segundo DWI puede traer una multa de hasta $4,000, de 30 días a 1 año de cárcel y una suspensión de licencia de 180 días a 2 años.","p":"Correcto. Hasta $4,000."},"ref":{"doc":"TX","page":58}},{"id":"tx-184","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, a driver is arrested for DWI with a 10-year-old child in the car. What kind of crime is this?","o":["A Class C misdemeanor","A state jail felony, with 180 days to 2 years in state jail","Only a traffic ticket","The same as a DWI with no passengers"],"h1":"Driving drunk with a child under 15 is treated as a felony.","h2":"In Texas, DWI with a passenger younger than 15 is a state jail felony, with a fine up to $10,000 and 180 days to 2 years in state jail.","p":"Right. It is a state jail felony."},"es":{"q":"En Texas, arrestan a un conductor por DWI con un niño de 10 años en el carro. ¿Qué tipo de delito es?","o":["Un delito menor Clase C","Un delito grave estatal, con 180 días a 2 años en cárcel estatal","Solo una multa de tránsito","Lo mismo que un DWI sin pasajeros"],"h1":"Manejar ebrio con un menor de 15 años se trata como delito grave.","h2":"En Texas, el DWI con un pasajero menor de 15 años es un delito grave estatal (state jail felony), con multa de hasta $10,000 y de 180 días a 2 años en cárcel estatal.","p":"Correcto. Es un delito grave estatal."},"ref":{"doc":"TX","page":58}},{"id":"tx-185","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a driver convicted of DWI had an open container of alcohol within reach. What is the minimum jail time?","o":["None","24 hours","72 hours","6 days"],"h1":"It is longer than the usual 72-hour minimum.","h2":"In Texas, if a DWI driver had an open container of alcohol in their immediate possession, the minimum jail time rises from 72 hours to six days.","p":"Right. At least six days."},"es":{"q":"En Texas, un conductor condenado por DWI tenía un envase abierto de alcohol a su alcance. ¿Cuál es el tiempo mínimo de cárcel?","o":["Nada","24 horas","72 horas","6 días"],"h1":"Es más que el mínimo normal de 72 horas.","h2":"En Texas, si el conductor con DWI tenía un envase abierto de alcohol a su alcance, el mínimo de cárcel sube de 72 horas a seis días.","p":"Correcto. Al menos seis días."},"ref":{"doc":"TX","page":null}},{"id":"tx-186","scope":"TX","cat":"licensing","sign":null,"c":2,"en":{"q":"In Texas, a first DWI is normally a Class B misdemeanor. What blood or breath alcohol level makes it a Class A misdemeanor?","o":["0.02 or more","0.08 or more","0.15 or more","0.30 or more"],"h1":"It is almost twice the legal limit.","h2":"In Texas, a DWI becomes a Class A misdemeanor if a test shows an alcohol concentration of 0.15 or more.","p":"Right. 0.15 or more."},"es":{"q":"En Texas, un primer DWI normalmente es un delito menor Clase B. ¿Qué nivel de alcohol en sangre o aliento lo convierte en Clase A?","o":["0.02 o más","0.08 o más","0.15 o más","0.30 o más"],"h1":"Es casi el doble del límite legal.","h2":"En Texas, un DWI pasa a ser delito menor Clase A si la prueba muestra una concentración de alcohol de 0.15 o más.","p":"Correcto. 0.15 o más."},"ref":{"doc":"TX","page":null}},{"id":"tx-187","scope":"TX","cat":"licensing","sign":null,"c":0,"en":{"q":"In Texas, a driver commits DWI in a school crossing zone while the reduced school speed limit is in effect. What kind of offense is this?","o":["A state jail felony","A Class C misdemeanor","A traffic warning","The same as any other first DWI"],"h1":"Texas treats drunk driving near children at school times far more seriously.","h2":"In Texas, a DWI committed in a school crossing zone while the reduced speed limit applies is a state jail felony.","p":"Right. It is a state jail felony."},"es":{"q":"En Texas, un conductor comete DWI en una zona escolar de cruce mientras está en vigor el límite reducido de velocidad. ¿Qué tipo de delito es?","o":["Un delito grave estatal","Un delito menor Clase C","Una advertencia de tránsito","Lo mismo que cualquier primer DWI"],"h1":"Texas castiga mucho más el manejo en estado de ebriedad cerca de niños en horario escolar.","h2":"En Texas, un DWI cometido en una zona escolar de cruce mientras aplica el límite reducido de velocidad es un delito grave estatal (state jail felony).","p":"Correcto. Es un delito grave estatal."},"ref":{"doc":"TX","page":null}},{"id":"tx-188","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, a driver's blood alcohol is 0.06, but the alcohol has clearly taken away the normal use of their mental and physical abilities. Can they be legally intoxicated?","o":["No, only 0.08 or more counts","No, unless they crash","Only if they are under 18","Yes, losing normal use of mental or physical faculties counts as intoxicated"],"h1":"The legal limit has two parts: a number and a condition.","h2":"In Texas, the legal limit is 0.08 BAC or any amount that causes loss of the normal use of mental or physical faculties.","p":"Right. You can be intoxicated below 0.08."},"es":{"q":"En Texas, un conductor tiene 0.06 de alcohol en la sangre, pero el alcohol claramente le quitó el uso normal de sus facultades mentales y físicas. ¿Puede estar legalmente intoxicado?","o":["No, solo cuenta 0.08 o más","No, a menos que choque","Solo si es menor de 18","Sí, perder el uso normal de las facultades mentales o físicas cuenta como intoxicación"],"h1":"El límite legal tiene dos partes: un número y una condición.","h2":"En Texas, el límite legal es 0.08 de alcohol en la sangre o cualquier cantidad que cause la pérdida del uso normal de las facultades mentales o físicas.","p":"Correcto. Se puede estar intoxicado con menos de 0.08."},"ref":{"doc":"TX","page":58}},{"id":"tx-189","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, a driver leaves the scene after a crash that only caused less than $200 of damage to an attended vehicle. What is the penalty?","o":["A Class C misdemeanor, fine up to $500","No penalty","Up to 2 years in prison","A fine of $5,000"],"h1":"It is the lowest kind of misdemeanor, but still a crime.","h2":"In Texas, failing to stop after a crash with less than $200 in damage is a Class C misdemeanor with a fine up to $500; $200 or more is a Class B misdemeanor.","p":"Right. A Class C misdemeanor, fine up to $500."},"es":{"q":"En Texas, un conductor se va del lugar después de un choque que solo causó menos de $200 de daño a un vehículo con gente. ¿Cuál es la pena?","o":["Un delito menor Clase C, multa de hasta $500","Ninguna pena","Hasta 2 años de prisión","Una multa de $5,000"],"h1":"Es el tipo más bajo de delito menor, pero sigue siendo delito.","h2":"En Texas, no detenerse después de un choque con menos de $200 de daño es un delito menor Clase C con multa de hasta $500; con $200 o más es Clase B.","p":"Correcto. Delito menor Clase C, multa de hasta $500."},"ref":{"doc":"TX","page":60}},{"id":"tx-190","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, you hit a parked car and cannot find the owner. What must you do?","o":["Drive away, since no one saw it","Wait one hour, then leave","Leave a note on the car with your name, address, and what happened","Call your insurance company only"],"h1":"The owner must be able to find you.","h2":"In Texas, if you damage an unattended vehicle and cannot find the owner, you must securely attach a written note with your name, address, and a statement of what happened.","p":"Right. Leave a note with your name and address."},"es":{"q":"En Texas, usted choca un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse, porque nadie lo vio","Esperar una hora y luego irse","Dejar una nota en el carro con su nombre, dirección y lo que pasó","Solo llamar a su aseguradora"],"h1":"El dueño debe poder encontrarlo.","h2":"En Texas, si daña un vehículo sin nadie y no encuentra al dueño, debe dejar bien sujeta una nota escrita con su nombre, su dirección y lo que pasó.","p":"Correcto. Deje una nota con su nombre y dirección."},"ref":{"doc":"TX","page":60}},{"id":"tx-191","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, you have a minor crash on a freeway main lane. No one is hurt and both cars can be driven safely. What should you do?","o":["Leave the cars where they are until police arrive","Move the cars as soon as possible to a safe place, like the frontage road or a cross street","Drive home and call later","Stay in your car in the lane"],"h1":"Stopped cars in the lanes can cause another crash.","h2":"In Texas, if a crash on a main lane, ramp, or shoulder leaves each vehicle drivable, the drivers must move them as soon as possible to a safe spot such as the frontage road or the nearest cross street.","p":"Right. Move the cars out of traffic."},"es":{"q":"En Texas, tiene un choque leve en un carril principal de autopista. Nadie está herido y los dos carros se pueden manejar con seguridad. ¿Qué debe hacer?","o":["Dejar los carros donde están hasta que llegue la policía","Mover los carros cuanto antes a un lugar seguro, como la calle lateral o una calle transversal","Irse a casa y llamar después","Quedarse en su carro en el carril"],"h1":"Los carros parados en los carriles pueden causar otro choque.","h2":"En Texas, si después de un choque en un carril principal, rampa o acotamiento cada vehículo se puede manejar, los conductores deben moverlos cuanto antes a un lugar seguro, como la calle lateral o la calle transversal más cercana.","p":"Correcto. Saque los carros del tráfico."},"ref":{"doc":"TX","page":59}},{"id":"tx-192","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, after a crash, when should you notify the police right away?","o":["Only if the other driver asks","When someone is hurt, or a vehicle cannot be moved off the road","Only if damage is more than $10,000","Never; call your insurer instead"],"h1":"Think of injuries and blocked roads.","h2":"In Texas, notify law enforcement as soon as possible when there is an injury or death, the vehicles cannot be moved off the road, a driver leaves the scene, or a driver seems intoxicated.","p":"Right. Call when someone is hurt or a car cannot be moved."},"es":{"q":"En Texas, después de un choque, ¿cuándo debe avisar a la policía de inmediato?","o":["Solo si el otro conductor lo pide","Cuando alguien está herido o un vehículo no se puede quitar del camino","Solo si el daño pasa de $10,000","Nunca; mejor llame a su aseguradora"],"h1":"Piense en heridos y calles bloqueadas.","h2":"En Texas, avise a la policía lo antes posible cuando haya heridos o muertos, los vehículos no se puedan sacar del camino, un conductor se vaya del lugar o un conductor parezca intoxicado.","p":"Correcto. Llame si hay heridos o un carro no se puede mover."},"ref":{"doc":"TX","page":59}},{"id":"tx-193","scope":"TX","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Texas, what fine can a driver get for not wearing a seat belt?","o":["$5 to $10","$25 to $50","$200 to $500","$1,000"],"h1":"It is the smallest fine in the seat belt table.","h2":"In Texas, driving without a safety belt brings a fine of $25 to $50.","p":"Right. The fine is $25 to $50."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor por no usar el cinturón de seguridad?","o":["$5 a $10","$25 a $50","$200 a $500","$1,000"],"h1":"Es la multa más baja de la tabla del cinturón.","h2":"En Texas, manejar sin cinturón de seguridad tiene una multa de $25 a $50.","p":"Correcto. La multa es de $25 a $50."},"ref":{"doc":"TX","page":64}},{"id":"tx-194","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, a 12-year-old passenger is riding without a seat belt. Who is fined, and how much?","o":["The child, $25","The parent at home, $50","The driver, $100 to $200","No one; the child is old enough"],"h1":"The driver is responsible for passengers under 17.","h2":"In Texas, the driver is fined $100 to $200 when a passenger younger than 17 rides without a safety belt.","p":"Right. The driver pays $100 to $200."},"es":{"q":"En Texas, un pasajero de 12 años va sin cinturón de seguridad. ¿A quién multan y cuánto?","o":["Al niño, $25","Al padre que está en casa, $50","Al conductor, de $100 a $200","A nadie; el niño ya tiene edad"],"h1":"El conductor responde por los pasajeros menores de 17.","h2":"En Texas, se multa al conductor con $100 a $200 cuando un pasajero menor de 17 años va sin cinturón de seguridad.","p":"Correcto. El conductor paga de $100 a $200."},"ref":{"doc":"TX","page":64}},{"id":"tx-195","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, may a 16-year-old ride in the open bed of a pickup truck on a city street?","o":["No; children under 18 may not ride in an open bed, except in special cases like a parade","Yes, if they sit down","Yes, if the truck goes under 30 mph","Yes, with a parent's permission"],"h1":"The age limit is 18.","h2":"In Texas, it is an offense to drive an open-bed or flatbed truck while a child younger than 18 rides in the bed, except in cases such as a parade, an emergency, or a permitted hayride.","p":"Right. No one under 18 may ride in the open bed."},"es":{"q":"En Texas, ¿puede un joven de 16 años ir en la caja abierta de una camioneta pickup por una calle de la ciudad?","o":["No; los menores de 18 no pueden ir en la caja abierta, salvo casos especiales como un desfile","Sí, si va sentado","Sí, si la camioneta va a menos de 30 mph","Sí, con permiso de sus padres"],"h1":"El límite de edad es 18.","h2":"En Texas, es una infracción manejar una camioneta de caja abierta o plataforma con un menor de 18 años en la caja, salvo casos como un desfile, una emergencia o un paseo en heno autorizado.","p":"Correcto. Ningún menor de 18 puede ir en la caja abierta."},"ref":{"doc":"TX","page":64}},{"id":"tx-196","scope":"TX","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Texas, you are towing a boat on the highway. Your 14-year-old wants to ride inside the boat. Is that allowed?","o":["Yes, if they wear a life jacket","Yes, at speeds under 45 mph","Yes, if an adult rides with them","No, no one under 18 may ride in a boat being towed, except in a parade, an emergency, or on a beach"],"h1":"The rule for towed boats is like the rule for open truck beds.","h2":"In Texas, it is an offense to tow a boat or personal watercraft with a person younger than 18 riding in or on it, except in a parade, an emergency, or on a beach.","p":"Right. No one under 18 may ride in a towed boat."},"es":{"q":"En Texas, usted jala una lancha por la carretera. Su hijo de 14 años quiere ir dentro de la lancha. ¿Está permitido?","o":["Sí, si usa chaleco salvavidas","Sí, a menos de 45 mph","Sí, si va un adulto con él","No, ningún menor de 18 puede ir en una lancha remolcada, salvo en un desfile, una emergencia o en la playa"],"h1":"La regla para lanchas remolcadas es como la de la caja abierta de una camioneta.","h2":"En Texas, es una infracción remolcar una lancha o moto acuática con una persona menor de 18 años adentro o encima, salvo en un desfile, una emergencia o en la playa.","p":"Correcto. Ningún menor de 18 puede ir en una lancha remolcada."},"ref":{"doc":"TX","page":65}},{"id":"tx-197","scope":"TX","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Texas, an unmarked car with flashing lights signals you to pull over at night on a dark road, and you are not sure it is real police. What does the handbook say you may do?","o":["Speed up and drive home","Ignore it until it goes away","Turn on your hazard lights, drive slowly to a well-lit, busy place, and you may call 911","Stop in the travel lane and get out of the car"],"h1":"Show you are cooperating while you get somewhere safe.","h2":"The Texas handbook says that if you are unsure about stopping, you may turn on your hazard lights, drive slowly below the limit, call 9-1-1, and drive to a nearby well-lit, populated place to stop.","p":"Right. Hazard lights, drive slowly to a lit place, and call 911."},"es":{"q":"En Texas, de noche en un camino oscuro, un carro sin marcas con luces intermitentes le indica que se orille, y no está seguro de que sea policía de verdad. ¿Qué dice el manual que puede hacer?","o":["Acelerar e irse a casa","Ignorarlo hasta que se vaya","Prender las intermitentes, manejar despacio a un lugar iluminado y con gente, y puede llamar al 911","Detenerse en el carril y bajarse del carro"],"h1":"Muestre que coopera mientras llega a un lugar seguro.","h2":"El manual de Texas dice que si no está seguro de detenerse, puede prender las luces intermitentes, manejar despacio por debajo del límite, llamar al 9-1-1 e ir a un lugar cercano bien iluminado y con gente para detenerse.","p":"Correcto. Intermitentes, manejar despacio a un lugar iluminado y llamar al 911."},"ref":{"doc":"TX","page":65}},{"id":"tx-198","scope":"TX","cat":"licensing","sign":null,"c":3,"en":{"q":"In Texas, an officer gives you a traffic ticket and asks you to sign it. What does your signature mean?","o":["You admit you are guilty","You give up your right to a trial","You agree to have your car searched","You promise to pay the fine or contact the court; it is not an admission of guilt"],"h1":"You can still fight the ticket in court.","h2":"In Texas, signing a citation is not admitting guilt; it only confirms your promise to pay the fine or contact the court.","p":"Right. Signing is a promise, not an admission."},"es":{"q":"En Texas, un oficial le da una multa de tránsito y le pide que la firme. ¿Qué significa su firma?","o":["Que admite que es culpable","Que renuncia a su derecho a un juicio","Que acepta que registren su carro","Que promete pagar la multa o comunicarse con el tribunal; no es admitir culpa"],"h1":"Todavía puede pelear la multa en el tribunal.","h2":"En Texas, firmar una multa no es admitir culpa; solo confirma su promesa de pagarla o de comunicarse con el tribunal.","p":"Correcto. Firmar es una promesa, no una admisión."},"ref":{"doc":"TX","page":66}},{"id":"tx-199","scope":"TX","cat":"licensing","sign":null,"c":1,"en":{"q":"In Texas, a 16-year-old with a provisional license wants to drive at 1 a.m. to see a friend. Her mother, a licensed driver over 21, sits beside her. Is this allowed?","o":["No, never between midnight and 5 a.m.","Yes, the night and passenger limits do not apply with a licensed adult 21 or older beside her","Only if she is driving to work","Only on weekends"],"h1":"The limits are lifted when she drives the way a learner does.","h2":"In Texas, the midnight-to-5 a.m. and passenger limits for drivers under 18 do not apply when a licensed driver 21 or older, with at least one year of experience, sits beside them.","p":"Right. It is allowed with a licensed adult 21 or older beside her."},"es":{"q":"En Texas, una joven de 16 años con licencia provisional quiere manejar a la 1 a.m. para ver a una amiga. Su mamá, conductora con licencia y mayor de 21, va sentada a su lado. ¿Está permitido?","o":["No, nunca entre la medianoche y las 5 a.m.","Sí, los límites de noche y de pasajeros no aplican con un adulto con licencia de 21 años o más a su lado","Solo si va al trabajo","Solo los fines de semana"],"h1":"Los límites no aplican cuando maneja como lo hace un aprendiz.","h2":"En Texas, los límites de medianoche a 5 a.m. y de pasajeros para menores de 18 no aplican cuando a su lado va un conductor con licencia de 21 años o más y al menos un año de experiencia.","p":"Correcto. Está permitido con un adulto con licencia de 21 o más a su lado."},"ref":{"doc":"TX","page":null}},{"id":"tx-200","scope":"TX","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Texas, what fine can an adult driver get for a first conviction of reading or sending a text while driving?","o":["$25 to $99","$100 to $200","$500 to $1,000","Up to $4,000"],"h1":"It is under $100 the first time.","h2":"In Texas, a first conviction for reading, writing, or sending an electronic message while driving brings a fine of $25 to $99; repeat offenses cost $100 to $200.","p":"Right. The first fine is $25 to $99."},"es":{"q":"En Texas, ¿qué multa puede recibir un conductor adulto por una primera condena por leer o enviar un mensaje de texto mientras maneja?","o":["$25 a $99","$100 a $200","$500 a $1,000","Hasta $4,000"],"h1":"Es menos de $100 la primera vez.","h2":"En Texas, la primera condena por leer, escribir o enviar un mensaje electrónico mientras maneja tiene una multa de $25 a $99; las siguientes cuestan de $100 a $200.","p":"Correcto. La primera multa es de $25 a $99."},"ref":{"doc":"TX","page":null}},{"id":"ut-001","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what is the youngest age to get a learner permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before you can get a driver license.","h2":"In Utah, you can get a learner permit when you are at least 15 years old, one year before you can get a license at 16.","p":"Right. A Utah learner permit starts at age 15."},"es":{"q":"En Utah, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de poder obtener la licencia de conducir.","h2":"En Utah, usted puede obtener el permiso de aprendiz cuando tiene por lo menos 15 años, un año antes de poder obtener la licencia a los 16.","p":"Correcto. El permiso de aprendiz en Utah empieza a los 15 años."},"zh":{"q":"在 Utah，最小几岁可以拿到学习驾照（learner permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿驾照的年龄早一年。","h2":"在 Utah，你至少 15 岁就可以拿到学习驾照，比 16 岁拿驾照早一年。","p":"对。Utah 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Utah, tuổi nhỏ nhất để lấy giấy phép tập lái (learner permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm trước khi bạn có thể lấy bằng lái.","h2":"Ở Utah, bạn có thể lấy giấy phép tập lái khi ít nhất 15 tuổi, một năm trước khi có thể lấy bằng lái lúc 16 tuổi.","p":"Đúng. Giấy phép tập lái ở Utah bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Utah, ano ang pinakabatang edad para makakuha ng learner permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ka makakuha ng driver license.","h2":"Sa Utah, puwede kang kumuha ng learner permit kapag hindi bababa sa 15 taong gulang ka, isang taon bago ka makakuha ng license sa edad na 16.","p":"Tama. Nagsisimula ang learner permit sa Utah sa edad na 15."},"ar":{"q":"في Utah، ما أصغر عمر للحصول على تصريح التعلّم (learner permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو سنة واحدة قبل أن تحصل على رخصة القيادة.","h2":"في Utah يمكنك الحصول على تصريح التعلّم عندما يكون عمرك 15 سنة على الأقل، أي قبل سنة من الحصول على الرخصة في عمر 16.","p":"صحيح. في Utah يبدأ تصريح التعلّم في عمر 15 سنة."},"ref":{"doc":"UT","page":7}},{"id":"ut-002","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how long is a learner permit valid?","o":["6 months","12 months","18 months","24 months"],"h1":"It is a year and a half.","h2":"Utah law says a learner permit is valid for 18 months, which gives a new driver time to practice and finish the requirements.","p":"Right. A Utah learner permit lasts 18 months."},"es":{"q":"En Utah, ¿cuánto tiempo es válido el permiso de aprendiz?","o":["6 meses","12 meses","18 meses","24 meses"],"h1":"Es un año y medio.","h2":"La ley de Utah dice que el permiso de aprendiz es válido por 18 meses, lo que le da tiempo al nuevo conductor para practicar y cumplir los requisitos.","p":"Correcto. El permiso de aprendiz en Utah dura 18 meses."},"zh":{"q":"在 Utah，学习驾照的有效期是多久？","o":["6 个月","12 个月","18 个月","24 个月"],"h1":"是一年半。","h2":"Utah 法律规定，学习驾照的有效期是 18 个月，让新司机有时间练习并完成要求。","p":"对。Utah 的学习驾照有效期是 18 个月。"},"vi":{"q":"Ở Utah, giấy phép tập lái có giá trị trong bao lâu?","o":["6 tháng","12 tháng","18 tháng","24 tháng"],"h1":"Đó là một năm rưỡi.","h2":"Luật Utah nói giấy phép tập lái có giá trị trong 18 tháng, cho người lái mới thời gian để tập và hoàn thành các yêu cầu.","p":"Đúng. Giấy phép tập lái ở Utah có giá trị 18 tháng."},"tl":{"q":"Sa Utah, gaano katagal may bisa ang learner permit?","o":["6 na buwan","12 buwan","18 buwan","24 na buwan"],"h1":"Isang taon at kalahati ito.","h2":"Sinasabi ng batas ng Utah na may bisa ang learner permit nang 18 buwan, para may oras ang bagong driver na magsanay at tapusin ang mga kailangan.","p":"Tama. Tumatagal nang 18 buwan ang learner permit sa Utah."},"ar":{"q":"في Utah، كم مدة صلاحية تصريح التعلّم؟","o":["6 أشهر","12 شهرًا","18 شهرًا","24 شهرًا"],"h1":"هي سنة ونصف.","h2":"قانون Utah يقول إن تصريح التعلّم صالح لمدة 18 شهرًا، وهذا يعطي السائق الجديد وقتًا للتدريب وإكمال الشروط.","p":"صحيح. تصريح التعلّم في Utah صالح لمدة 18 شهرًا."},"ref":{"doc":"UT","page":7}},{"id":"ut-003","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many hours of supervised driving must a teen log before getting a license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"Ten of these hours must be at night.","h2":"In Utah, a teen must log at least 40 hours of supervised driving, including at least 10 hours at night, before getting a license.","p":"Right. Utah requires 40 supervised hours."},"es":{"q":"En Utah, ¿cuántas horas de manejo supervisado debe registrar un joven antes de obtener la licencia?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Diez de estas horas deben ser de noche.","h2":"En Utah, un joven debe registrar por lo menos 40 horas de manejo supervisado, incluidas por lo menos 10 horas de noche, antes de obtener la licencia.","p":"Correcto. Utah exige 40 horas supervisadas."},"zh":{"q":"在 Utah，青少年在拿驾照之前，必须记录多少小时有人陪同的驾驶？","o":["20 小时","30 小时","40 小时","60 小时"],"h1":"其中 10 小时必须在夜间。","h2":"在 Utah，青少年拿驾照之前，必须记录至少 40 小时有人陪同的驾驶，其中至少 10 小时在夜间。","p":"对。Utah 要求 40 小时有人陪同的驾驶。"},"vi":{"q":"Ở Utah, thiếu niên phải ghi lại bao nhiêu giờ lái xe có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","40 giờ","60 giờ"],"h1":"Mười giờ trong số đó phải lái vào ban đêm.","h2":"Ở Utah, thiếu niên phải ghi lại ít nhất 40 giờ lái xe có người giám sát, trong đó ít nhất 10 giờ vào ban đêm, trước khi lấy bằng lái.","p":"Đúng. Utah yêu cầu 40 giờ có người giám sát."},"tl":{"q":"Sa Utah, ilang oras ng pagmamaneho na may gumagabay ang dapat itala ng isang teen bago makakuha ng license?","o":["20 oras","30 oras","40 oras","60 oras"],"h1":"Sampu sa mga oras na ito ay dapat sa gabi.","h2":"Sa Utah, dapat magtala ang isang teen ng hindi bababa sa 40 oras ng pagmamaneho na may gumagabay, kasama ang hindi bababa sa 10 oras sa gabi, bago makakuha ng license.","p":"Tama. Kailangan ng Utah ang 40 oras na may gumagabay."},"ar":{"q":"في Utah، كم ساعة من القيادة تحت الإشراف يجب أن يسجّل المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","40 ساعة","60 ساعة"],"h1":"عشر ساعات منها يجب أن تكون في الليل.","h2":"في Utah يجب أن يسجّل المراهق 40 ساعة على الأقل من القيادة تحت الإشراف، منها 10 ساعات على الأقل في الليل، قبل الحصول على الرخصة.","p":"صحيح. تطلب Utah 40 ساعة تحت الإشراف."},"ref":{"doc":"UT","page":6}},{"id":"ut-004","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many of a teen's supervised practice hours must be at night?","o":["At least 10 hours","At least 2 hours","At least 5 hours","At least 20 hours"],"h1":"It is a small part of the 40 total hours, but more than a few.","h2":"Of the 40 supervised hours Utah requires, at least 10 must be driven at night so the teen gains experience in the dark.","p":"Right. At least 10 of the hours must be at night."},"es":{"q":"En Utah, ¿cuántas de las horas de práctica supervisada de un joven deben ser de noche?","o":["Por lo menos 10 horas","Por lo menos 2 horas","Por lo menos 5 horas","Por lo menos 20 horas"],"h1":"Es una parte pequeña de las 40 horas en total, pero más que unas pocas.","h2":"De las 40 horas supervisadas que exige Utah, por lo menos 10 deben ser de noche para que el joven gane experiencia en la oscuridad.","p":"Correcto. Por lo menos 10 de las horas deben ser de noche."},"zh":{"q":"在 Utah，青少年有人陪同的练习时间中，有多少小时必须在夜间？","o":["至少 10 小时","至少 2 小时","至少 5 小时","至少 20 小时"],"h1":"这是总共 40 小时中的一小部分，但不只几个小时。","h2":"在 Utah 要求的 40 小时有人陪同的驾驶中，至少 10 小时必须在夜间，让青少年积累在黑暗中开车的经验。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Utah, trong số giờ tập lái có người giám sát của thiếu niên, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 10 giờ","Ít nhất 2 giờ","Ít nhất 5 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần nhỏ của tổng 40 giờ, nhưng nhiều hơn vài giờ.","h2":"Trong 40 giờ có người giám sát mà Utah yêu cầu, ít nhất 10 giờ phải lái vào ban đêm để thiếu niên có kinh nghiệm lái trong bóng tối.","p":"Đúng. Ít nhất 10 giờ phải lái vào ban đêm."},"tl":{"q":"Sa Utah, ilan sa mga oras ng pagsasanay na may gumagabay ng isang teen ang dapat sa gabi?","o":["Hindi bababa sa 10 oras","Hindi bababa sa 2 oras","Hindi bababa sa 5 oras","Hindi bababa sa 20 oras"],"h1":"Maliit na bahagi ito ng kabuuang 40 oras, pero higit sa ilan lang.","h2":"Sa 40 oras na may gumagabay na kailangan ng Utah, hindi bababa sa 10 ang dapat imaneho sa gabi para magkaroon ng karanasan ang teen sa dilim.","p":"Tama. Hindi bababa sa 10 sa mga oras ang dapat sa gabi."},"ar":{"q":"في Utah، كم ساعة من ساعات التدريب تحت الإشراف للمراهق يجب أن تكون في الليل؟","o":["10 ساعات على الأقل","2 ساعة على الأقل","5 ساعات على الأقل","20 ساعة على الأقل"],"h1":"هي جزء صغير من مجموع 40 ساعة، لكنها أكثر من بضع ساعات.","h2":"من الـ 40 ساعة تحت الإشراف التي تطلبها Utah، يجب أن تكون 10 ساعات على الأقل في الليل حتى يكتسب المراهق خبرة القيادة في الظلام.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"UT","page":6}},{"id":"ut-005","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, how long must a 16- or 17-year-old hold a learner permit before getting a license?","o":["30 days","90 days","One year","Six months"],"h1":"It is half of a year.","h2":"In Utah, a driver who is 16 or 17 must hold the learner permit for at least six months before getting a driver license.","p":"Right. Drivers who are 16 or 17 hold the permit for at least six months."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un joven de 16 o 17 años antes de obtener la licencia?","o":["30 días","90 días","Un año","Seis meses"],"h1":"Es la mitad de un año.","h2":"En Utah, un conductor de 16 o 17 años debe tener el permiso de aprendiz por lo menos seis meses antes de obtener la licencia de conducir.","p":"Correcto. Los conductores de 16 o 17 años tienen el permiso por lo menos seis meses."},"zh":{"q":"在 Utah，16 岁或 17 岁的人必须持有学习驾照多久，才能拿驾照？","o":["30 天","90 天","一年","六个月"],"h1":"是半年。","h2":"在 Utah，16 岁或 17 岁的司机必须持有学习驾照至少六个月，才能拿到驾照。","p":"对。16 岁或 17 岁的司机要持有学习驾照至少六个月。"},"vi":{"q":"Ở Utah, người 16 hoặc 17 tuổi phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["30 ngày","90 ngày","Một năm","Sáu tháng"],"h1":"Đó là nửa năm.","h2":"Ở Utah, người lái 16 hoặc 17 tuổi phải giữ giấy phép tập lái ít nhất sáu tháng trước khi lấy bằng lái.","p":"Đúng. Người lái 16 hoặc 17 tuổi giữ giấy phép ít nhất sáu tháng."},"tl":{"q":"Sa Utah, gaano katagal dapat hawak ng isang 16 o 17 taong gulang ang learner permit bago makakuha ng license?","o":["30 araw","90 araw","Isang taon","Anim na buwan"],"h1":"Kalahating taon ito.","h2":"Sa Utah, ang driver na 16 o 17 taong gulang ay dapat humawak ng learner permit nang hindi bababa sa anim na buwan bago makakuha ng driver license.","p":"Tama. Hawak ng mga driver na 16 o 17 ang permit nang hindi bababa sa anim na buwan."},"ar":{"q":"في Utah، كم مدة يجب أن يحمل الشخص الذي عمره 16 أو 17 سنة تصريح التعلّم قبل الحصول على الرخصة؟","o":["30 يومًا","90 يومًا","سنة واحدة","ستة أشهر"],"h1":"هي نصف سنة.","h2":"في Utah يجب على السائق الذي عمره 16 أو 17 سنة أن يحمل تصريح التعلّم ستة أشهر على الأقل قبل الحصول على رخصة القيادة.","p":"صحيح. السائقون في عمر 16 أو 17 يحملون التصريح ستة أشهر على الأقل."},"ref":{"doc":"UT","page":7}},{"id":"ut-006","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, how long must a driver who is 19 or older hold a learner permit before getting a license?","o":["30 days","90 days","Six months","One year"],"h1":"It is shorter than the time for teens, about three months.","h2":"In Utah, a driver who is 19 or older must hold the learner permit for at least 90 days, unless they finish an approved driver education course.","p":"Right. Drivers 19 and older hold the permit for at least 90 days."},"es":{"q":"En Utah, ¿cuánto tiempo debe tener el permiso de aprendiz un conductor de 19 años o más antes de obtener la licencia?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Es menos tiempo que para los jóvenes, unos tres meses.","h2":"En Utah, un conductor de 19 años o más debe tener el permiso de aprendiz por lo menos 90 días, a menos que termine un curso aprobado de educación vial.","p":"Correcto. Los conductores de 19 años o más tienen el permiso por lo menos 90 días."},"zh":{"q":"在 Utah，19 岁或以上的人必须持有学习驾照多久，才能拿驾照？","o":["30 天","90 天","六个月","一年"],"h1":"比青少年的时间短，大约三个月。","h2":"在 Utah，19 岁或以上的司机必须持有学习驾照至少 90 天，除非他们完成了经过批准的驾驶教育课程。","p":"对。19 岁及以上的司机要持有学习驾照至少 90 天。"},"vi":{"q":"Ở Utah, người lái từ 19 tuổi trở lên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["30 ngày","90 ngày","Sáu tháng","Một năm"],"h1":"Ngắn hơn thời gian của thiếu niên, khoảng ba tháng.","h2":"Ở Utah, người lái từ 19 tuổi trở lên phải giữ giấy phép tập lái ít nhất 90 ngày, trừ khi họ hoàn thành một khóa học lái xe được chấp thuận.","p":"Đúng. Người lái từ 19 tuổi trở lên giữ giấy phép ít nhất 90 ngày."},"tl":{"q":"Sa Utah, gaano katagal dapat hawak ng driver na 19 taong gulang o pataas ang learner permit bago makakuha ng license?","o":["30 araw","90 araw","Anim na buwan","Isang taon"],"h1":"Mas maikli ito kaysa sa oras para sa mga teen, mga tatlong buwan.","h2":"Sa Utah, ang driver na 19 taong gulang o pataas ay dapat humawak ng learner permit nang hindi bababa sa 90 araw, maliban kung natapos nila ang isang aprubadong driver education course.","p":"Tama. Hawak ng mga driver na 19 pataas ang permit nang hindi bababa sa 90 araw."},"ar":{"q":"في Utah، كم مدة يجب أن يحمل السائق الذي عمره 19 سنة أو أكثر تصريح التعلّم قبل الحصول على الرخصة؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنة واحدة"],"h1":"هي أقصر من مدة المراهقين، حوالي ثلاثة أشهر.","h2":"في Utah يجب على السائق الذي عمره 19 سنة أو أكثر أن يحمل تصريح التعلّم 90 يومًا على الأقل، إلا إذا أكمل دورة معتمدة لتعليم القيادة.","p":"صحيح. السائقون في عمر 19 فأكثر يحملون التصريح 90 يومًا على الأقل."},"ref":{"doc":"UT","page":7}},{"id":"ut-007","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, a driver under 18 with a learner permit must have a qualified adult in which seat?","o":["The seat beside the driver","Any back seat","The seat behind the driver","Any seat in the car"],"h1":"The adult must be close enough to help right away.","h2":"In Utah, a learner under 18 may drive only when a parent or guardian, a driving instructor, or a responsible adult who signed for them sits in the seat beside them.","p":"Right. The adult sits in the seat beside the learner."},"es":{"q":"En Utah, un conductor menor de 18 años con permiso de aprendiz debe llevar a un adulto autorizado. ¿En qué asiento?","o":["En el asiento al lado del conductor","En cualquier asiento trasero","En el asiento detrás del conductor","En cualquier asiento del carro"],"h1":"El adulto debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Utah, un aprendiz menor de 18 años solo puede manejar si un padre o tutor, un instructor de manejo o un adulto responsable que firmó por él va sentado a su lado.","p":"Correcto. El adulto va sentado al lado del aprendiz."},"zh":{"q":"在 Utah，未满 18 岁、持有学习驾照的司机开车时，合格的成年人必须坐在哪个座位？","o":["司机旁边的座位","任何后座","司机后面的座位","车里任何座位"],"h1":"这个成年人必须离得够近，可以马上帮忙。","h2":"在 Utah，未满 18 岁的学员只有在父母或监护人、驾驶教练，或为他们签字的负责任成年人坐在旁边座位时，才可以开车。","p":"对。成年人坐在学员旁边的座位。"},"vi":{"q":"Ở Utah, người lái dưới 18 tuổi có giấy phép tập lái phải có một người lớn đủ điều kiện ngồi ở ghế nào?","o":["Ghế bên cạnh người lái","Bất kỳ ghế sau nào","Ghế phía sau người lái","Bất kỳ ghế nào trong xe"],"h1":"Người lớn phải ở đủ gần để giúp ngay lập tức.","h2":"Ở Utah, người tập lái dưới 18 tuổi chỉ được lái khi cha mẹ hoặc người giám hộ, giáo viên dạy lái, hoặc một người lớn có trách nhiệm đã ký cho họ ngồi ở ghế bên cạnh.","p":"Đúng. Người lớn ngồi ở ghế bên cạnh người tập lái."},"tl":{"q":"Sa Utah, ang driver na wala pang 18 na may learner permit ay dapat may kuwalipikadong adult sa aling upuan?","o":["Ang upuan sa tabi ng driver","Kahit anong upuan sa likod","Ang upuan sa likod ng driver","Kahit anong upuan sa sasakyan"],"h1":"Dapat sapat na malapit ang adult para tumulong agad.","h2":"Sa Utah, ang learner na wala pang 18 ay puwedeng magmaneho lamang kapag nakaupo sa tabi niya ang magulang o guardian, isang driving instructor, o isang responsableng adult na pumirma para sa kanya.","p":"Tama. Nakaupo ang adult sa tabi ng learner."},"ar":{"q":"في Utah، السائق الأصغر من 18 سنة الذي يحمل تصريح التعلّم يجب أن يكون معه شخص بالغ مؤهّل في أي مقعد؟","o":["المقعد بجانب السائق","أي مقعد خلفي","المقعد خلف السائق","أي مقعد في السيارة"],"h1":"يجب أن يكون الشخص البالغ قريبًا بما يكفي ليساعد فورًا.","h2":"في Utah لا يجوز للمتعلّم الأصغر من 18 سنة أن يقود إلا إذا جلس بجانبه أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ مسؤول وقّع له.","p":"صحيح. يجلس الشخص البالغ في المقعد بجانب المتعلّم."},"ref":{"doc":"UT","page":6}},{"id":"ut-008","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, during which hours may a young driver with a provisional license not drive, unless an exception applies?","o":["10 p.m. to 5 a.m.","11 p.m. to 6 a.m.","9 p.m. to 6 a.m.","Midnight to 5 a.m."],"h1":"The limit starts at the very start of a new day.","h2":"In Utah, a young provisional license holder may not drive from midnight to 5 a.m., unless with a licensed adult 21 or older in front, going to or from work, for a school activity, for farm work, or in an emergency.","p":"Right. Young provisional drivers stay off the road from midnight to 5 a.m."},"es":{"q":"En Utah, ¿en qué horario no puede manejar un conductor joven con licencia provisional, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 6 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 5 a.m."],"h1":"El límite empieza justo al inicio de un nuevo día.","h2":"En Utah, un joven con licencia provisional no puede manejar de medianoche a 5 a.m., salvo con un adulto con licencia de 21 años o más en el asiento delantero, para ir o volver del trabajo, por una actividad escolar, por trabajo agrícola o en una emergencia.","p":"Correcto. Los conductores jóvenes con licencia provisional no manejan de medianoche a 5 a.m."},"zh":{"q":"在 Utah，持有临时驾照（provisional license）的年轻司机，在哪个时间段不可以开车（除非有例外情况）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 6 点","晚上 9 点到早上 6 点","午夜 12 点到早上 5 点"],"h1":"这个限制从新的一天刚开始的时候开始。","h2":"在 Utah，年轻的临时驾照持有人从午夜 12 点到早上 5 点不可以开车，除非前座有 21 岁或以上的有驾照成年人、上下班、参加学校活动、做农活，或遇到紧急情况。","p":"对。年轻的临时驾照司机从午夜 12 点到早上 5 点不能上路。"},"vi":{"q":"Ở Utah, người lái trẻ có bằng lái tạm thời (provisional license) không được lái trong khoảng giờ nào, trừ khi có ngoại lệ?","o":["10 giờ tối đến 5 giờ sáng","11 giờ tối đến 6 giờ sáng","9 giờ tối đến 6 giờ sáng","Nửa đêm đến 5 giờ sáng"],"h1":"Giới hạn bắt đầu ngay lúc bắt đầu một ngày mới.","h2":"Ở Utah, người trẻ có bằng lái tạm thời không được lái từ nửa đêm đến 5 giờ sáng, trừ khi có một người lớn có bằng lái từ 21 tuổi trở lên ngồi phía trước, đi làm hoặc đi làm về, cho hoạt động của trường, làm việc nông trại, hoặc trong trường hợp khẩn cấp.","p":"Đúng. Người lái trẻ có bằng tạm thời không lên đường từ nửa đêm đến 5 giờ sáng."},"tl":{"q":"Sa Utah, sa anong mga oras hindi puwedeng magmaneho ang batang driver na may provisional license, maliban kung may exception?","o":["10 p.m. hanggang 5 a.m.","11 p.m. hanggang 6 a.m.","9 p.m. hanggang 6 a.m.","Hatinggabi hanggang 5 a.m."],"h1":"Nagsisimula ang limitasyon sa mismong simula ng bagong araw.","h2":"Sa Utah, ang batang may provisional license ay hindi puwedeng magmaneho mula hatinggabi hanggang 5 a.m., maliban kung may kasamang adult na may license na 21 pataas sa harap, papunta o pauwi galing trabaho, para sa aktibidad ng paaralan, para sa trabaho sa bukid, o sa emergency.","p":"Tama. Hindi nagmamaneho ang mga batang provisional driver mula hatinggabi hanggang 5 a.m."},"ar":{"q":"في Utah، في أي ساعات لا يجوز للسائق الصغير الذي يحمل رخصة مؤقتة (provisional license) أن يقود، إلا في حالة استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 6 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 5 صباحًا"],"h1":"يبدأ المنع في أول لحظة من يوم جديد.","h2":"في Utah لا يجوز لحامل الرخصة المؤقتة الصغير أن يقود من منتصف الليل إلى 5 صباحًا، إلا مع شخص بالغ عمره 21 سنة أو أكثر ويحمل رخصة في المقعد الأمامي، أو في الذهاب إلى العمل أو العودة منه، أو لنشاط مدرسي، أو لعمل في مزرعة، أو في حالة طارئة.","p":"صحيح. السائقون الصغار برخصة مؤقتة لا يقودون من منتصف الليل إلى 5 صباحًا."},"ref":{"doc":"UT","page":8}},{"id":"ut-009","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, for how long after getting a provisional license may a teen carry only immediate family members as passengers, unless an exception applies?","o":["The first month","The first six months","The first year","Until age 21"],"h1":"It is half of a year.","h2":"In Utah, for the first six months with a provisional license, a teen may carry only immediate family members, unless a licensed driver 21 or older is in the front seat, the trip is for farm work, or there is an emergency.","p":"Right. For the first six months, only family members may ride along."},"es":{"q":"En Utah, ¿durante cuánto tiempo después de obtener la licencia provisional puede un joven llevar solo a familiares directos como pasajeros, salvo que aplique una excepción?","o":["El primer mes","Los primeros seis meses","El primer año","Hasta los 21 años"],"h1":"Es la mitad de un año.","h2":"En Utah, durante los primeros seis meses con licencia provisional, un joven puede llevar solo a familiares directos, salvo que vaya un conductor con licencia de 21 años o más en el asiento delantero, el viaje sea por trabajo agrícola o haya una emergencia.","p":"Correcto. Durante los primeros seis meses, solo los familiares pueden ir como pasajeros."},"zh":{"q":"在 Utah，青少年拿到临时驾照后，在多长时间内只能载直系家庭成员作为乘客（除非有例外情况）？","o":["第一个月","前六个月","第一年","到 21 岁为止"],"h1":"是半年。","h2":"在 Utah，拿到临时驾照的前六个月，青少年只能载直系家庭成员，除非前座有 21 岁或以上的有驾照司机、出行是为了农活，或遇到紧急情况。","p":"对。前六个月只有家庭成员可以搭车。"},"vi":{"q":"Ở Utah, sau khi có bằng lái tạm thời, trong bao lâu thiếu niên chỉ được chở người thân trong gia đình trực hệ, trừ khi có ngoại lệ?","o":["Tháng đầu tiên","Sáu tháng đầu","Năm đầu tiên","Cho đến 21 tuổi"],"h1":"Đó là nửa năm.","h2":"Ở Utah, trong sáu tháng đầu có bằng lái tạm thời, thiếu niên chỉ được chở người thân trong gia đình trực hệ, trừ khi có người lái có bằng từ 21 tuổi trở lên ở ghế trước, chuyến đi là để làm việc nông trại, hoặc có trường hợp khẩn cấp.","p":"Đúng. Trong sáu tháng đầu, chỉ người trong gia đình được đi cùng."},"tl":{"q":"Sa Utah, gaano katagal pagkatapos makakuha ng provisional license na ang isang teen ay puwedeng magsakay lamang ng malapit na kapamilya, maliban kung may exception?","o":["Ang unang buwan","Ang unang anim na buwan","Ang unang taon","Hanggang edad 21"],"h1":"Kalahating taon ito.","h2":"Sa Utah, sa unang anim na buwan na may provisional license, ang teen ay puwedeng magsakay lamang ng malapit na kapamilya, maliban kung may driver na may license na 21 pataas sa harap na upuan, ang biyahe ay para sa trabaho sa bukid, o may emergency.","p":"Tama. Sa unang anim na buwan, mga kapamilya lang ang puwedeng sumakay."},"ar":{"q":"في Utah، بعد الحصول على الرخصة المؤقتة، لأي مدة لا يجوز للمراهق أن ينقل إلا أفراد العائلة المباشرين كركّاب، إلا في حالة استثناء؟","o":["الشهر الأول","الأشهر الستة الأولى","السنة الأولى","حتى عمر 21"],"h1":"هي نصف سنة.","h2":"في Utah، في الأشهر الستة الأولى مع الرخصة المؤقتة، لا يجوز للمراهق أن ينقل إلا أفراد العائلة المباشرين، إلا إذا كان في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو كانت الرحلة لعمل في مزرعة، أو كانت هناك حالة طارئة.","p":"صحيح. في الأشهر الستة الأولى، أفراد العائلة فقط يمكنهم الركوب."},"ref":{"doc":"UT","page":8}},{"id":"ut-010","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a teen got a provisional license two months ago. When may the teen carry a friend as a passenger?","o":["When the passenger is under 16","When the trip is under 10 miles","When a licensed driver 21 or older is in the front seat","When the teen drives only in daylight"],"h1":"An experienced adult changes the rule.","h2":"In Utah, during the first six months a teen may carry friends only when a licensed driver 21 or older sits in the front seat, or for farm work or an emergency.","p":"Right. A licensed driver 21 or older in front lifts the passenger limit."},"es":{"q":"En Utah, un joven obtuvo la licencia provisional hace dos meses. ¿Cuándo puede llevar a un amigo como pasajero?","o":["Cuando el pasajero es menor de 16 años","Cuando el viaje es de menos de 10 millas","Cuando va un conductor con licencia de 21 años o más en el asiento delantero","Cuando maneja solo de día"],"h1":"Un adulto con experiencia cambia la regla.","h2":"En Utah, durante los primeros seis meses un joven puede llevar amigos solo cuando un conductor con licencia de 21 años o más va en el asiento delantero, o por trabajo agrícola o una emergencia.","p":"Correcto. Un conductor con licencia de 21 años o más adelante quita el límite de pasajeros."},"zh":{"q":"在 Utah，一名青少年两个月前拿到了临时驾照。他什么时候可以载朋友作为乘客？","o":["当乘客未满 16 岁时","当路程少于 10 英里时","当前座有 21 岁或以上的有驾照司机时","当青少年只在白天开车时"],"h1":"有经验的成年人会改变这个规定。","h2":"在 Utah，在前六个月内，青少年只有在前座有 21 岁或以上的有驾照司机时，或为了农活或紧急情况，才可以载朋友。","p":"对。前座有 21 岁或以上的有驾照司机，就可以不受乘客限制。"},"vi":{"q":"Ở Utah, một thiếu niên có bằng lái tạm thời được hai tháng. Khi nào thiếu niên này được chở một người bạn?","o":["Khi người đi cùng dưới 16 tuổi","Khi chuyến đi dưới 10 dặm","Khi có người lái có bằng từ 21 tuổi trở lên ở ghế trước","Khi thiếu niên chỉ lái vào ban ngày"],"h1":"Một người lớn có kinh nghiệm làm thay đổi quy định.","h2":"Ở Utah, trong sáu tháng đầu, thiếu niên chỉ được chở bạn bè khi có người lái có bằng từ 21 tuổi trở lên ngồi ở ghế trước, hoặc để làm việc nông trại hoặc trong trường hợp khẩn cấp.","p":"Đúng. Người lái có bằng từ 21 tuổi trở lên ở phía trước bỏ giới hạn người đi cùng."},"tl":{"q":"Sa Utah, nakakuha ng provisional license ang isang teen dalawang buwan na ang nakaraan. Kailan puwedeng magsakay ang teen ng kaibigan?","o":["Kapag wala pang 16 ang pasahero","Kapag ang biyahe ay wala pang 10 milya","Kapag may driver na may license na 21 pataas sa harap na upuan","Kapag sa araw lang nagmamaneho ang teen"],"h1":"Binabago ng isang may karanasang adult ang patakaran.","h2":"Sa Utah, sa unang anim na buwan, ang teen ay puwedeng magsakay ng mga kaibigan lamang kapag may driver na may license na 21 pataas na nakaupo sa harap na upuan, o para sa trabaho sa bukid o emergency.","p":"Tama. Inaalis ng driver na may license na 21 pataas sa harap ang limitasyon sa pasahero."},"ar":{"q":"في Utah، حصل مراهق على رخصة مؤقتة قبل شهرين. متى يجوز له أن ينقل صديقًا كراكب؟","o":["عندما يكون عمر الراكب أقل من 16 سنة","عندما تكون الرحلة أقل من 10 أميال","عندما يكون في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر","عندما يقود المراهق في النهار فقط"],"h1":"وجود شخص بالغ له خبرة يغيّر القاعدة.","h2":"في Utah، في الأشهر الستة الأولى، لا يجوز للمراهق أن ينقل أصدقاء إلا إذا جلس في المقعد الأمامي سائق يحمل رخصة وعمره 21 سنة أو أكثر، أو لعمل في مزرعة أو في حالة طارئة.","p":"صحيح. وجود سائق يحمل رخصة وعمره 21 سنة أو أكثر في الأمام يرفع حدّ الركّاب."},"ref":{"doc":"UT","page":8}},{"id":"ut-011","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, what is the rule on talking on a cell phone for drivers under 18?","o":["Only to talk with a parent or guardian, in a medical emergency, or to report a hazard or a crime","They may talk only with a hands-free device","They may talk only on roads under 45 mph","They may talk if the call is short"],"h1":"For the youngest drivers, the rule is stricter than for adults.","h2":"In Utah, a driver younger than 18 may use a phone while driving only in a medical emergency, to report a safety hazard or a crime, or to talk with a parent or guardian.","p":"Right. Under 18, the phone is only for a parent or guardian, an emergency, a hazard or a crime."},"es":{"q":"En Utah, ¿cuál es la regla sobre hablar por celular para conductores menores de 18 años?","o":["Solo para hablar con su padre, madre o tutor, en una emergencia médica, o para reportar un peligro o un delito","Pueden hablar solo con manos libres","Pueden hablar solo en calles de menos de 45 mph","Pueden hablar si la llamada es corta"],"h1":"Para los conductores más jóvenes, la regla es más estricta que para los adultos.","h2":"En Utah, un conductor menor de 18 años puede usar el teléfono mientras maneja solo en una emergencia médica, para reportar un peligro o un delito, o para hablar con su padre, madre o tutor.","p":"Correcto. Si es menor de 18, el teléfono es solo para su padre, madre o tutor, una emergencia, un peligro o un delito."},"zh":{"q":"在 Utah，未满 18 岁的驾驶人开车时打电话有什么规定？","o":["只能和父母或监护人通话、在医疗紧急情况下通话，或报告危险或犯罪","只能使用免提设备通话","只能在时速低于 45 mph 的道路上通话","如果通话很短就可以"],"h1":"对最年轻的驾驶人，规定比成人更严格。","h2":"在 Utah，未满 18 岁的驾驶人开车时只能在医疗紧急情况下、报告安全危险或犯罪时，或和父母或监护人通话时使用手机。","p":"对。未满 18 岁时，手机只能用于联系父母或监护人、紧急情况、报告危险或犯罪。"},"vi":{"q":"Ở Utah, quy định về việc nói chuyện điện thoại khi lái xe đối với tài xế dưới 18 tuổi là gì?","o":["Chỉ được nói chuyện với cha mẹ hoặc người giám hộ, khi có cấp cứu y tế, hoặc để báo cáo mối nguy hiểm hay tội phạm","Chỉ được nói chuyện bằng thiết bị rảnh tay","Chỉ được nói chuyện trên đường có tốc độ dưới 45 mph","Được nói chuyện nếu cuộc gọi ngắn"],"h1":"Với những tài xế trẻ nhất, quy định nghiêm hơn so với người lớn.","h2":"Ở Utah, tài xế dưới 18 tuổi chỉ được dùng điện thoại khi lái xe trong trường hợp cấp cứu y tế, để báo cáo mối nguy hiểm về an toàn hay tội phạm, hoặc để nói chuyện với cha mẹ hay người giám hộ.","p":"Đúng. Dưới 18 tuổi, điện thoại chỉ dùng để gọi cha mẹ hoặc người giám hộ, khi cấp cứu, hoặc báo cáo nguy hiểm hay tội phạm."},"tl":{"q":"Sa Utah, ano ang patakaran sa pakikipag-usap sa cell phone para sa mga driver na wala pang 18 taong gulang?","o":["Para lang makipag-usap sa magulang o guardian, sa medical emergency, o para mag-report ng panganib o krimen","Puwede lang silang makipag-usap gamit ang hands-free device","Puwede lang silang makipag-usap sa mga kalsadang mas mababa sa 45 mph","Puwede silang makipag-usap kung maikli ang tawag"],"h1":"Para sa pinakabatang mga driver, mas mahigpit ang patakaran kaysa sa matatanda.","h2":"Sa Utah, ang driver na wala pang 18 taong gulang ay puwedeng gumamit ng phone habang nagmamaneho lang kapag may medical emergency, para mag-report ng panganib sa kaligtasan o krimen, o para makipag-usap sa magulang o guardian.","p":"Tama. Kapag wala pang 18, ang phone ay para lang sa magulang o guardian, emergency, panganib o krimen."},"ar":{"q":"في Utah، ما القاعدة بشأن التحدث بالهاتف المحمول للسائقين الذين أعمارهم أقل من 18 سنة؟","o":["فقط للتحدث مع أحد الوالدين أو الوصي، أو في حالة طوارئ طبية، أو للإبلاغ عن خطر أو جريمة","يمكنهم التحدث فقط باستخدام جهاز بدون استعمال اليدين","يمكنهم التحدث فقط على الطرق التي سرعتها أقل من 45 mph","يمكنهم التحدث إذا كانت المكالمة قصيرة"],"h1":"بالنسبة لأصغر السائقين، القاعدة أشد من القاعدة للكبار.","h2":"في Utah، يمكن للسائق الذي عمره أقل من 18 سنة أن يستخدم الهاتف أثناء القيادة فقط في حالة طوارئ طبية، أو للإبلاغ عن خطر على السلامة أو عن جريمة، أو للتحدث مع أحد الوالدين أو الوصي.","p":"صحيح. تحت 18 سنة، الهاتف فقط للتحدث مع أحد الوالدين أو الوصي، أو للطوارئ، أو للإبلاغ عن خطر أو جريمة."},"ref":{"doc":"UT","page":59}},{"id":"ut-012","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, which of these may an adult driver do with a handheld phone while driving?","o":["Write a text message","Read an email","Watch a video","Talk on a call started by voice command"],"h1":"Typing, reading and watching are not allowed.","h2":"In Utah, a driver 18 or older may not type, read, browse or watch video on a handheld phone, but may talk on a call that was started by voice command.","p":"Right. An adult may talk on a call started by voice command."},"es":{"q":"En Utah, ¿cuál de estas cosas puede hacer un conductor adulto con el teléfono en la mano mientras maneja?","o":["Escribir un mensaje de texto","Leer un correo","Ver un video","Hablar en una llamada iniciada con comandos de voz"],"h1":"Escribir, leer y ver videos no está permitido.","h2":"En Utah, un conductor de 18 años o más no puede escribir, leer, navegar ni ver videos en el teléfono en la mano, pero puede hablar en una llamada iniciada con comandos de voz.","p":"Correcto. Un adulto puede hablar en una llamada iniciada con comandos de voz."},"zh":{"q":"在 Utah，成年司机开车时可以用手持电话做下面哪件事？","o":["写短信","读电子邮件","看视频","进行用语音指令拨出的通话"],"h1":"打字、阅读和观看都不可以。","h2":"在 Utah，18 岁或以上的司机不可以在手持电话上打字、阅读、浏览或看视频，但可以进行用语音指令拨出的通话。","p":"对。成年人可以进行用语音指令拨出的通话。"},"vi":{"q":"Ở Utah, người lái trưởng thành được làm điều nào sau đây với điện thoại cầm tay khi lái xe?","o":["Viết tin nhắn","Đọc email","Xem video","Nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói"],"h1":"Gõ chữ, đọc và xem đều không được phép.","h2":"Ở Utah, người lái từ 18 tuổi trở lên không được gõ chữ, đọc, lướt web hoặc xem video trên điện thoại cầm tay, nhưng được nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói.","p":"Đúng. Người lớn được nói chuyện trong cuộc gọi bắt đầu bằng lệnh giọng nói."},"tl":{"q":"Sa Utah, alin sa mga ito ang puwedeng gawin ng adult na driver gamit ang hawak na phone habang nagmamaneho?","o":["Sumulat ng text message","Magbasa ng email","Manood ng video","Makipag-usap sa tawag na sinimulan sa voice command"],"h1":"Hindi puwede ang mag-type, magbasa at manood.","h2":"Sa Utah, ang driver na 18 pataas ay hindi puwedeng mag-type, magbasa, mag-browse o manood ng video sa hawak na phone, pero puwedeng makipag-usap sa tawag na sinimulan sa voice command.","p":"Tama. Puwedeng makipag-usap ang adult sa tawag na sinimulan sa voice command."},"ar":{"q":"في Utah، أيّ من هذه الأشياء يجوز للسائق البالغ أن يفعله بهاتف في يده أثناء القيادة؟","o":["كتابة رسالة نصية","قراءة بريد إلكتروني","مشاهدة فيديو","الحديث في مكالمة بدأت بأمر صوتي"],"h1":"الكتابة والقراءة والمشاهدة غير مسموحة.","h2":"في Utah لا يجوز للسائق الذي عمره 18 سنة أو أكثر أن يكتب أو يقرأ أو يتصفّح أو يشاهد فيديو على هاتف في يده، لكن يجوز له الحديث في مكالمة بدأت بأمر صوتي.","p":"صحيح. يجوز للبالغ الحديث في مكالمة بدأت بأمر صوتي."},"ref":{"doc":"UT","page":59}},{"id":"ut-013","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, at what blood alcohol level can a driver 21 or older be charged with DUI?","o":["0.02 percent or higher","0.08 percent or higher","0.05 percent or higher","0.10 percent or higher"],"h1":"Utah's limit is lower than the one most states use.","h2":"In Utah, a driver 21 or older breaks the DUI law with a blood alcohol level of 0.05 percent or higher.","p":"Right. Utah's adult limit is 0.05 percent."},"es":{"q":"En Utah, ¿con qué nivel de alcohol en la sangre se puede acusar de DUI a un conductor de 21 años o más?","o":["0.02 por ciento o más","0.08 por ciento o más","0.05 por ciento o más","0.10 por ciento o más"],"h1":"El límite de Utah es más bajo que el de la mayoría de los estados.","h2":"En Utah, un conductor de 21 años o más viola la ley de DUI con un nivel de alcohol en la sangre de 0.05 por ciento o más.","p":"Correcto. El límite para adultos en Utah es 0.05 por ciento."},"zh":{"q":"在 Utah，21 岁或以上的司机血液酒精浓度达到多少，就可以被控酒后驾驶（DUI）？","o":["0.02% 或更高","0.08% 或更高","0.05% 或更高","0.10% 或更高"],"h1":"Utah 的标准比大多数州低。","h2":"在 Utah，21 岁或以上的司机血液酒精浓度达到 0.05% 或更高，就违反了酒后驾驶（DUI）法律。","p":"对。Utah 成年人的标准是 0.05%。"},"vi":{"q":"Ở Utah, người lái từ 21 tuổi trở lên có thể bị buộc tội lái xe khi say (DUI) ở nồng độ cồn trong máu bao nhiêu?","o":["0.02 phần trăm trở lên","0.08 phần trăm trở lên","0.05 phần trăm trở lên","0.10 phần trăm trở lên"],"h1":"Giới hạn của Utah thấp hơn giới hạn mà hầu hết các tiểu bang dùng.","h2":"Ở Utah, người lái từ 21 tuổi trở lên vi phạm luật DUI khi nồng độ cồn trong máu từ 0.05 phần trăm trở lên.","p":"Đúng. Giới hạn cho người lớn ở Utah là 0.05 phần trăm."},"tl":{"q":"Sa Utah, sa anong antas ng alak sa dugo puwedeng kasuhan ng DUI ang driver na 21 pataas?","o":["0.02 porsiyento o higit pa","0.08 porsiyento o higit pa","0.05 porsiyento o higit pa","0.10 porsiyento o higit pa"],"h1":"Mas mababa ang limitasyon ng Utah kaysa sa ginagamit ng karamihan ng estado.","h2":"Sa Utah, nilalabag ng driver na 21 pataas ang batas sa DUI kapag ang antas ng alak sa dugo ay 0.05 porsiyento o higit pa.","p":"Tama. Ang limitasyon para sa adult sa Utah ay 0.05 porsiyento."},"ar":{"q":"في Utah، عند أي نسبة كحول في الدم يمكن اتهام السائق الذي عمره 21 سنة أو أكثر بالقيادة تحت تأثير الكحول (DUI)؟","o":["0.02 بالمئة أو أكثر","0.08 بالمئة أو أكثر","0.05 بالمئة أو أكثر","0.10 بالمئة أو أكثر"],"h1":"حدّ Utah أقل من الحدّ الذي تستخدمه معظم الولايات.","h2":"في Utah يخالف السائق الذي عمره 21 سنة أو أكثر قانون القيادة تحت تأثير الكحول (DUI) عندما تكون نسبة الكحول في دمه 0.05 بالمئة أو أكثر.","p":"صحيح. حدّ البالغين في Utah هو 0.05 بالمئة."},"ref":{"doc":"UT","page":52}},{"id":"ut-014","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, how does the adult blood alcohol limit compare with most other states?","o":["It is the same 0.08 percent","It is lower, at 0.05 percent","It is higher, at 0.10 percent","Utah has no fixed limit"],"h1":"Utah changed its law in 2018.","h2":"Utah lowered its adult limit from 0.08 to 0.05 percent in 2018, which made it the lowest limit in the country at the time.","p":"Right. Utah's 0.05 percent limit is lower than most states."},"es":{"q":"En Utah, ¿cómo se compara el límite de alcohol para adultos con el de la mayoría de los estados?","o":["Es el mismo, 0.08 por ciento","Es más bajo, 0.05 por ciento","Es más alto, 0.10 por ciento","Utah no tiene un límite fijo"],"h1":"Utah cambió su ley en 2018.","h2":"Utah bajó su límite para adultos de 0.08 a 0.05 por ciento en 2018, y así tuvo el límite más bajo del país en ese momento.","p":"Correcto. El límite de 0.05 por ciento de Utah es más bajo que en la mayoría de los estados."},"zh":{"q":"在 Utah，成年人的血液酒精浓度标准和大多数其他州相比怎么样？","o":["一样是 0.08%","更低，是 0.05%","更高，是 0.10%","Utah 没有固定标准"],"h1":"Utah 在 2018 年修改了法律。","h2":"Utah 在 2018 年把成年人的标准从 0.08% 降到 0.05%，这在当时是全国最低的标准。","p":"对。Utah 的 0.05% 标准比大多数州低。"},"vi":{"q":"Ở Utah, giới hạn nồng độ cồn trong máu cho người lớn so với hầu hết các tiểu bang khác thì thế nào?","o":["Giống nhau, 0.08 phần trăm","Thấp hơn, 0.05 phần trăm","Cao hơn, 0.10 phần trăm","Utah không có giới hạn cố định"],"h1":"Utah đã thay đổi luật vào năm 2018.","h2":"Năm 2018, Utah hạ giới hạn cho người lớn từ 0.08 xuống 0.05 phần trăm, khiến đó là giới hạn thấp nhất cả nước vào thời điểm đó.","p":"Đúng. Giới hạn 0.05 phần trăm của Utah thấp hơn hầu hết các tiểu bang."},"tl":{"q":"Sa Utah, paano maihahambing ang limitasyon ng alak sa dugo para sa adult sa karamihan ng ibang estado?","o":["Pareho ito, 0.08 porsiyento","Mas mababa ito, 0.05 porsiyento","Mas mataas ito, 0.10 porsiyento","Walang tiyak na limitasyon ang Utah"],"h1":"Binago ng Utah ang batas nito noong 2018.","h2":"Ibinaba ng Utah ang limitasyon para sa adult mula 0.08 hanggang 0.05 porsiyento noong 2018, kaya ito ang naging pinakamababang limitasyon sa bansa noong panahong iyon.","p":"Tama. Mas mababa ang 0.05 porsiyento na limitasyon ng Utah kaysa sa karamihan ng estado."},"ar":{"q":"في Utah، كيف يُقارَن حدّ الكحول في الدم للبالغين مع معظم الولايات الأخرى؟","o":["هو نفسه 0.08 بالمئة","هو أقل، 0.05 بالمئة","هو أعلى، 0.10 بالمئة","ليس في Utah حدّ ثابت"],"h1":"غيّرت Utah قانونها في سنة 2018.","h2":"خفّضت Utah حدّ البالغين من 0.08 إلى 0.05 بالمئة في سنة 2018، وكان هذا أقل حدّ في البلد في ذلك الوقت.","p":"صحيح. حدّ Utah وهو 0.05 بالمئة أقل من معظم الولايات."},"ref":{"doc":"UT","page":52}},{"id":"ut-015","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how much alcohol may a driver under 21 have in their body while driving?","o":["None at all","Up to 0.02 percent","Up to 0.05 percent","Up to 0.08 percent"],"h1":"Utah calls this rule \"not a drop.\"","h2":"Utah does not allow a driver under 21 to drive with any measurable alcohol in their body.","p":"Right. Under 21, the limit is not a drop."},"es":{"q":"En Utah, ¿cuánto alcohol puede tener en el cuerpo un conductor menor de 21 años mientras maneja?","o":["Nada en absoluto","Hasta 0.02 por ciento","Hasta 0.05 por ciento","Hasta 0.08 por ciento"],"h1":"En Utah esta regla se conoce como \"ni una gota\".","h2":"Utah no permite que un conductor menor de 21 años maneje con alcohol medible en el cuerpo.","p":"Correcto. Para menores de 21, el límite es ni una gota."},"zh":{"q":"在 Utah，未满 21 岁的司机开车时，体内可以有多少酒精？","o":["完全不可以有","最多 0.02%","最多 0.05%","最多 0.08%"],"h1":"Utah 把这条规定叫做“一滴都不行”（not a drop）。","h2":"Utah 不允许未满 21 岁的司机在体内有任何可测出的酒精时开车。","p":"对。未满 21 岁，一滴都不行。"},"vi":{"q":"Ở Utah, người lái dưới 21 tuổi được có bao nhiêu cồn trong cơ thể khi lái xe?","o":["Hoàn toàn không có","Tối đa 0.02 phần trăm","Tối đa 0.05 phần trăm","Tối đa 0.08 phần trăm"],"h1":"Utah gọi quy định này là \"không một giọt\" (not a drop).","h2":"Utah không cho phép người lái dưới 21 tuổi lái xe khi có bất kỳ lượng cồn đo được nào trong cơ thể.","p":"Đúng. Dưới 21 tuổi, giới hạn là không một giọt."},"tl":{"q":"Sa Utah, gaano karaming alak ang puwedeng nasa katawan ng driver na wala pang 21 habang nagmamaneho?","o":["Wala talaga","Hanggang 0.02 porsiyento","Hanggang 0.05 porsiyento","Hanggang 0.08 porsiyento"],"h1":"Tinatawag ng Utah ang patakarang ito na \"kahit isang patak, hindi\" (not a drop).","h2":"Hindi pinapayagan ng Utah ang driver na wala pang 21 na magmaneho nang may kahit anong nasusukat na alak sa katawan.","p":"Tama. Kapag wala pang 21, kahit isang patak ay hindi puwede."},"ar":{"q":"في Utah، كم من الكحول يجوز أن يكون في جسم السائق الأصغر من 21 سنة أثناء القيادة؟","o":["لا شيء أبدًا","حتى 0.02 بالمئة","حتى 0.05 بالمئة","حتى 0.08 بالمئة"],"h1":"تسمّي Utah هذه القاعدة \"ولا قطرة\" (not a drop).","h2":"لا تسمح Utah للسائق الأصغر من 21 سنة بالقيادة مع أي كمية كحول يمكن قياسها في جسمه.","p":"صحيح. تحت 21 سنة، الحدّ هو ولا قطرة."},"ref":{"doc":"UT","page":52}},{"id":"ut-016","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, what is the highest speed limit posted on some rural interstate stretches?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is higher than in most states.","h2":"Utah allows speed limits up to 80 mph on some rural interstate highways, where signs show it.","p":"Right. Some rural Utah interstates allow 80 mph."},"es":{"q":"En Utah, ¿cuál es el límite de velocidad más alto en algunos tramos rurales de interestatales?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es más alto que en la mayoría de los estados.","h2":"Utah permite límites de hasta 80 mph en algunas carreteras interestatales rurales, donde las señales lo indican.","p":"Correcto. Algunas interestatales rurales de Utah permiten 80 mph."},"zh":{"q":"在 Utah，一些乡村州际公路路段上标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"比大多数州都高。","h2":"Utah 在一些乡村州际公路上允许最高 80 mph 的限速，以路标标示为准。","p":"对。Utah 一些乡村州际公路允许 80 mph。"},"vi":{"q":"Ở Utah, tốc độ tối đa cao nhất được ghi trên biển ở một số đoạn xa lộ liên tiểu bang vùng nông thôn là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó cao hơn so với hầu hết các tiểu bang.","h2":"Utah cho phép tốc độ tối đa đến 80 mph trên một số xa lộ liên tiểu bang vùng nông thôn, nơi có biển báo ghi rõ.","p":"Đúng. Một số xa lộ liên tiểu bang vùng nông thôn ở Utah cho phép 80 mph."},"tl":{"q":"Sa Utah, ano ang pinakamataas na speed limit na nakapaskil sa ilang bahagi ng rural interstate?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito kaysa sa karamihan ng estado.","h2":"Pinapayagan ng Utah ang speed limit hanggang 80 mph sa ilang rural interstate highway, kung saan ito ipinapakita ng mga sign.","p":"Tama. Pinapayagan ang 80 mph sa ilang rural interstate sa Utah."},"ar":{"q":"في Utah، ما أعلى حدّ للسرعة مكتوب على بعض أجزاء الطرق السريعة بين الولايات (interstate) في المناطق الريفية؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أعلى من معظم الولايات.","h2":"تسمح Utah بحدّ سرعة يصل إلى 80 mph على بعض الطرق السريعة بين الولايات في المناطق الريفية، حيث تُظهر اللافتات ذلك.","p":"صحيح. بعض الطرق السريعة الريفية في Utah تسمح بـ 80 mph."},"ref":{"doc":"UT","page":44}},{"id":"ut-017","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, when should you drive in the left lane of a multi-lane highway?","o":["Whenever you drive at the speed limit","Whenever traffic is light","To pass slower vehicles, then move back right","Whenever you plan to exit soon"],"h1":"The left lane is not a lane to stay in.","h2":"In Utah, the left lane of a multi-lane road is for passing slower vehicles, and you must move right when someone comes up behind you.","p":"Right. Use the left lane to pass, then move back right."},"es":{"q":"En Utah, ¿cuándo debe usar el carril izquierdo de una carretera de varios carriles?","o":["Siempre que maneje al límite de velocidad","Siempre que haya poco tráfico","Para rebasar a vehículos más lentos y luego volver a la derecha","Siempre que piense salir pronto"],"h1":"El carril izquierdo no es un carril para quedarse.","h2":"En Utah, el carril izquierdo de una carretera de varios carriles es para rebasar a vehículos más lentos, y usted debe pasarse a la derecha cuando alguien se acerca por detrás.","p":"Correcto. Use el carril izquierdo para rebasar y luego vuelva a la derecha."},"zh":{"q":"在 Utah，在多车道公路上，你什么时候应该在左车道行驶？","o":["只要你按限速行驶的时候","只要车流量少的时候","超过较慢的车辆时，然后回到右边","只要你打算很快下高速的时候"],"h1":"左车道不是用来一直待着的车道。","h2":"在 Utah，多车道道路的左车道是用来超过较慢车辆的，有人从后面靠近时，你必须移到右边。","p":"对。用左车道超车，然后回到右边。"},"vi":{"q":"Ở Utah, khi nào bạn nên lái ở làn bên trái của xa lộ nhiều làn?","o":["Bất cứ khi nào bạn lái đúng tốc độ tối đa","Bất cứ khi nào xe ít","Để vượt xe chậm hơn, rồi trở lại bên phải","Bất cứ khi nào bạn sắp ra khỏi xa lộ"],"h1":"Làn bên trái không phải là làn để ở lại.","h2":"Ở Utah, làn bên trái của đường nhiều làn là để vượt xe chậm hơn, và bạn phải sang phải khi có xe đến gần phía sau bạn.","p":"Đúng. Dùng làn bên trái để vượt, rồi trở lại bên phải."},"tl":{"q":"Sa Utah, kailan ka dapat magmaneho sa kaliwang lane ng highway na maraming lane?","o":["Tuwing nagmamaneho ka sa speed limit","Tuwing kaunti ang trapiko","Para lampasan ang mas mabagal na sasakyan, saka bumalik sa kanan","Tuwing malapit ka nang lumabas"],"h1":"Hindi lane na tinitirhan ang kaliwang lane.","h2":"Sa Utah, ang kaliwang lane ng daan na maraming lane ay para sa paglampas sa mas mabagal na sasakyan, at dapat kang lumipat sa kanan kapag may dumarating sa likod mo.","p":"Tama. Gamitin ang kaliwang lane para lumampas, saka bumalik sa kanan."},"ar":{"q":"في Utah، متى يجب أن تقود في الحارة اليسرى من طريق سريع متعدد الحارات؟","o":["كلما كنت تقود بحدّ السرعة","كلما كانت حركة المرور خفيفة","لتجاوز المركبات الأبطأ، ثم العودة إلى اليمين","كلما كنت تنوي الخروج قريبًا"],"h1":"الحارة اليسرى ليست حارة للبقاء فيها.","h2":"في Utah، الحارة اليسرى في الطريق متعدد الحارات هي لتجاوز المركبات الأبطأ، ويجب أن تنتقل إلى اليمين عندما تقترب منك سيارة من الخلف.","p":"صحيح. استخدم الحارة اليسرى للتجاوز، ثم عُد إلى اليمين."},"ref":{"doc":"UT","page":34}},{"id":"ut-018","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, which stopped vehicles does the move-over law cover?","o":["Only police cars with red and blue lights","Any stopped vehicle by the road with flashing lights, including hazard lights","Only ambulances carrying a patient","Only cars parked in a legal parking area"],"h1":"It is not only for police and emergency vehicles.","h2":"Utah's move-over law covers any vehicle stopped by the road with flashing lights, including a car with its hazard lights on, unless it is in a legal parking area.","p":"Right. The law covers any stopped vehicle with flashing lights, even hazard lights."},"es":{"q":"En Utah, ¿qué vehículos detenidos cubre la ley de moverse de carril?","o":["Solo patrullas con luces rojas y azules","Cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso luces de emergencia","Solo ambulancias que llevan a un paciente","Solo carros estacionados en un lugar legal"],"h1":"No es solo para la policía y los vehículos de emergencia.","h2":"La ley de Utah de moverse de carril cubre cualquier vehículo detenido junto a la carretera con luces intermitentes, incluso un carro con las luces de emergencia encendidas, salvo que esté en un lugar legal de estacionamiento.","p":"Correcto. La ley cubre cualquier vehículo detenido con luces intermitentes, incluso luces de emergencia."},"zh":{"q":"在 Utah，让道法（move-over law）适用于哪些停着的车辆？","o":["只有亮红蓝灯的警车","路边任何亮着闪光灯的停着的车辆，包括亮着危险警示灯的车","只有载着病人的救护车","只有停在合法停车区的车"],"h1":"它不只适用于警车和紧急车辆。","h2":"Utah 的让道法适用于路边任何亮着闪光灯的停着的车辆，包括亮着危险警示灯的汽车，除非它停在合法停车区。","p":"对。这条法律适用于任何亮着闪光灯的停着的车辆，即使是危险警示灯。"},"vi":{"q":"Ở Utah, luật nhường làn (move-over law) áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát có đèn đỏ và xanh","Bất kỳ xe nào dừng bên đường có đèn nhấp nháy, kể cả đèn báo nguy hiểm","Chỉ xe cứu thương đang chở bệnh nhân","Chỉ xe đậu trong khu vực đậu xe hợp pháp"],"h1":"Nó không chỉ dành cho xe cảnh sát và xe cấp cứu.","h2":"Luật nhường làn của Utah áp dụng cho bất kỳ xe nào dừng bên đường có đèn nhấp nháy, kể cả xe bật đèn báo nguy hiểm, trừ khi xe ở trong khu vực đậu xe hợp pháp.","p":"Đúng. Luật áp dụng cho bất kỳ xe đang dừng nào có đèn nhấp nháy, kể cả đèn báo nguy hiểm."},"tl":{"q":"Sa Utah, aling nakahintong sasakyan ang sakop ng move-over law?","o":["Mga sasakyan lang ng pulis na may pula at asul na ilaw","Kahit anong sasakyang nakahinto sa tabi ng daan na may kumikislap na ilaw, kasama ang hazard lights","Mga ambulansiya lang na may sakay na pasyente","Mga sasakyan lang na nakaparada sa legal na paradahan"],"h1":"Hindi lang ito para sa pulis at emergency vehicle.","h2":"Sakop ng move-over law ng Utah ang kahit anong sasakyang nakahinto sa tabi ng daan na may kumikislap na ilaw, kasama ang sasakyang naka-on ang hazard lights, maliban kung nasa legal na paradahan ito.","p":"Tama. Sakop ng batas ang kahit anong nakahintong sasakyan na may kumikislap na ilaw, kahit hazard lights."},"ar":{"q":"في Utah، ما المركبات المتوقفة التي يشملها قانون الابتعاد (move-over law)؟","o":["سيارات الشرطة ذات الأضواء الحمراء والزرقاء فقط","أي مركبة متوقفة بجانب الطريق لها أضواء وامضة، ومنها أضواء التحذير (hazard lights)","سيارات الإسعاف التي تنقل مريضًا فقط","السيارات المتوقفة في مكان وقوف قانوني فقط"],"h1":"ليس فقط للشرطة ومركبات الطوارئ.","h2":"قانون الابتعاد في Utah يشمل أي مركبة متوقفة بجانب الطريق لها أضواء وامضة، ومنها سيارة أضواء التحذير فيها مُشغَّلة، إلا إذا كانت في مكان وقوف قانوني.","p":"صحيح. القانون يشمل أي مركبة متوقفة لها أضواء وامضة، حتى أضواء التحذير."},"ref":{"doc":"UT","page":77}},{"id":"ut-019","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, you cannot safely move over a lane for a stopped tow truck with flashing amber lights. What must you do?","o":["Slow down and leave as much space as you can","Keep your speed and pass quickly","Stop in your lane until it leaves","Flash your headlights and pass"],"h1":"If you cannot add a lane, add space and reduce speed.","h2":"Under Utah's move-over law, if you cannot safely change lanes, you must slow down and give the stopped vehicle as much space as you can.","p":"Right. Slow down and give as much space as possible."},"es":{"q":"En Utah, usted no puede cambiarse de carril con seguridad ante una grúa detenida con luces ámbar intermitentes. ¿Qué debe hacer?","o":["Reducir la velocidad y dejar todo el espacio que pueda","Mantener la velocidad y pasar rápido","Detenerse en su carril hasta que se vaya","Hacer cambio de luces y pasar"],"h1":"Si no puede cambiar de carril, deje espacio y reduzca la velocidad.","h2":"Según la ley de Utah, si usted no puede cambiarse de carril con seguridad, debe reducir la velocidad y dejar al vehículo detenido todo el espacio que pueda.","p":"Correcto. Reduzca la velocidad y deje todo el espacio posible."},"zh":{"q":"在 Utah，你无法安全地为一辆亮着琥珀色闪光灯的停着的拖车让出一条车道。你必须怎么做？","o":["减速，并尽量留出空间","保持速度，快速通过","停在你的车道上，直到它离开","闪一下大灯然后通过"],"h1":"如果不能让出一条车道，就留出空间并减速。","h2":"根据 Utah 的让道法，如果你不能安全换道，你必须减速，并尽量给停着的车辆留出空间。","p":"对。减速，并尽量留出空间。"},"vi":{"q":"Ở Utah, bạn không thể sang làn khác một cách an toàn để nhường một xe kéo đang dừng có đèn vàng hổ phách nhấp nháy. Bạn phải làm gì?","o":["Giảm tốc độ và chừa khoảng cách càng nhiều càng tốt","Giữ tốc độ và vượt nhanh","Dừng trong làn của bạn cho đến khi xe đó đi","Nháy đèn pha và vượt qua"],"h1":"Nếu không thể sang làn, hãy chừa thêm khoảng cách và giảm tốc độ.","h2":"Theo luật nhường làn của Utah, nếu bạn không thể đổi làn một cách an toàn, bạn phải giảm tốc độ và chừa cho xe đang dừng khoảng cách càng nhiều càng tốt.","p":"Đúng. Giảm tốc độ và chừa khoảng cách càng nhiều càng tốt."},"tl":{"q":"Sa Utah, hindi ka ligtas na makakalipat ng lane para sa nakahintong tow truck na may kumikislap na amber na ilaw. Ano ang dapat mong gawin?","o":["Bumagal at mag-iwan ng pinakamaraming espasyo na kaya mo","Panatilihin ang bilis at lumampas nang mabilis","Huminto sa lane mo hanggang umalis ito","I-flash ang headlights at lumampas"],"h1":"Kung hindi ka makalipat ng lane, magdagdag ng espasyo at bawasan ang bilis.","h2":"Ayon sa move-over law ng Utah, kung hindi ka ligtas na makakalipat ng lane, dapat kang bumagal at bigyan ang nakahintong sasakyan ng pinakamaraming espasyo na kaya mo.","p":"Tama. Bumagal at magbigay ng pinakamaraming espasyo hangga't maaari."},"ar":{"q":"في Utah، لا يمكنك أن تنتقل بأمان إلى حارة أخرى من أجل شاحنة سحب متوقفة لها أضواء وامضة كهرمانية. ماذا يجب أن تفعل؟","o":["خفّف السرعة واترك أكبر مسافة ممكنة","حافظ على سرعتك وتجاوز بسرعة","توقّف في حارتك حتى تغادر","أومض بالأضواء الأمامية وتجاوز"],"h1":"إذا لم تستطع أن تترك حارة، فاترك مسافة وخفّف السرعة.","h2":"بحسب قانون الابتعاد في Utah، إذا لم تستطع تغيير الحارة بأمان، يجب أن تخفّف السرعة وتترك للمركبة المتوقفة أكبر مسافة ممكنة.","p":"صحيح. خفّف السرعة واترك أكبر مسافة ممكنة."},"ref":{"doc":"UT","page":77}},{"id":"ut-020","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, what must a driver do after being convicted of breaking the move-over law?","o":["Pay a $25 fine only","Retake the driving skills test","Take a four-hour live defensive driving class within 90 days","Lose your license for one year"],"h1":"It is a class you attend in person.","h2":"In Utah, a driver convicted of breaking the move-over law must take a four-hour live defensive driving class within 90 days, or the license is suspended for 90 days.","p":"Right. The driver must take a four-hour defensive driving class within 90 days."},"es":{"q":"En Utah, ¿qué debe hacer un conductor declarado culpable de no cumplir la ley de moverse de carril?","o":["Pagar solo una multa de $25","Volver a tomar el examen práctico de manejo","Tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días","Perder la licencia por un año"],"h1":"Es una clase a la que se asiste en persona.","h2":"En Utah, un conductor declarado culpable de no cumplir la ley de moverse de carril debe tomar una clase presencial de manejo defensivo de cuatro horas dentro de 90 días, o su licencia se suspende por 90 días.","p":"Correcto. El conductor debe tomar una clase de manejo defensivo de cuatro horas dentro de 90 días."},"zh":{"q":"在 Utah，司机因违反让道法被定罪后，必须做什么？","o":["只需支付 $25 罚款","重新参加驾驶技能考试","在 90 天内参加四小时的现场防御性驾驶课","驾照被吊销一年"],"h1":"这是一门要亲自去上的课。","h2":"在 Utah，因违反让道法被定罪的司机必须在 90 天内参加四小时的现场防御性驾驶课，否则驾照会被暂停 90 天。","p":"对。司机必须在 90 天内参加四小时的防御性驾驶课。"},"vi":{"q":"Ở Utah, người lái bị kết tội vi phạm luật nhường làn phải làm gì?","o":["Chỉ trả tiền phạt $25","Thi lại bài thi kỹ năng lái xe","Học một lớp lái xe phòng thủ trực tiếp bốn giờ trong vòng 90 ngày","Bị mất bằng lái một năm"],"h1":"Đó là một lớp học bạn phải đến tham dự trực tiếp.","h2":"Ở Utah, người lái bị kết tội vi phạm luật nhường làn phải học một lớp lái xe phòng thủ trực tiếp bốn giờ trong vòng 90 ngày, nếu không bằng lái sẽ bị đình chỉ 90 ngày.","p":"Đúng. Người lái phải học một lớp lái xe phòng thủ bốn giờ trong vòng 90 ngày."},"tl":{"q":"Sa Utah, ano ang dapat gawin ng driver pagkatapos mahatulang lumabag sa move-over law?","o":["Magbayad lang ng $25 na multa","Ulitin ang driving skills test","Kumuha ng apat na oras na live na defensive driving class sa loob ng 90 araw","Mawalan ng license nang isang taon"],"h1":"Isa itong klase na personal mong pupuntahan.","h2":"Sa Utah, ang driver na nahatulang lumabag sa move-over law ay dapat kumuha ng apat na oras na live na defensive driving class sa loob ng 90 araw, o masususpinde ang license nang 90 araw.","p":"Tama. Dapat kumuha ang driver ng apat na oras na defensive driving class sa loob ng 90 araw."},"ar":{"q":"في Utah، ماذا يجب أن يفعل السائق بعد إدانته بمخالفة قانون الابتعاد؟","o":["دفع غرامة $25 فقط","إعادة اختبار مهارات القيادة","حضور درس مباشر في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا","فقدان الرخصة لمدة سنة"],"h1":"هو درس تحضره بنفسك.","h2":"في Utah، السائق المُدان بمخالفة قانون الابتعاد يجب أن يحضر درسًا مباشرًا في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا، وإلا تُوقَف رخصته لمدة 90 يومًا.","p":"صحيح. يجب أن يحضر السائق درسًا في القيادة الوقائية مدته أربع ساعات خلال 90 يومًا."},"ref":{"doc":"UT","page":77}},{"id":"ut-021","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, you are on a divided highway with four or more lanes and a median. A school bus stops on the other side with red lights flashing. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not need to stop, but stay alert","Honk and keep your speed"],"h1":"A median separates you from the bus and the children.","h2":"In Utah, on a divided highway with four or more lanes and a median, drivers coming toward a stopped school bus do not need to stop, but drivers behind the bus must stop.","p":"Right. On a divided highway, oncoming traffic does not need to stop."},"es":{"q":"En Utah, usted va por una carretera dividida de cuatro carriles o más con franja central. Un autobús escolar se detiene del otro lado con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No necesita detenerse, pero debe estar atento","Tocar la bocina y mantener la velocidad"],"h1":"Una franja central lo separa del autobús y de los niños.","h2":"En Utah, en una carretera dividida de cuatro carriles o más con franja central, los conductores que vienen de frente a un autobús escolar detenido no necesitan detenerse, pero los que van detrás del autobús sí deben detenerse.","p":"Correcto. En una carretera dividida, el tráfico que viene de frente no necesita detenerse."},"zh":{"q":"在 Utah，你在一条有四条或以上车道和中间分隔带的分隔公路上。一辆校车在对面停下，红灯在闪。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 通过","你不需要停车，但要保持警觉","按喇叭并保持速度"],"h1":"中间分隔带把你和校车及孩子们隔开。","h2":"在 Utah，在有四条或以上车道和中间分隔带的分隔公路上，迎面驶向停着的校车的司机不需要停车，但在校车后面的司机必须停车。","p":"对。在分隔公路上，对向车辆不需要停车。"},"vi":{"q":"Ở Utah, bạn đang ở trên xa lộ có dải phân cách với bốn làn trở lên. Một xe buýt trường học dừng ở phía bên kia với đèn đỏ nhấp nháy. Bạn phải làm gì?","o":["Dừng cho đến khi đèn tắt","Dừng, rồi vượt qua với tốc độ 10 mph","Bạn không cần dừng, nhưng hãy chú ý","Bấm còi và giữ tốc độ"],"h1":"Dải phân cách tách bạn khỏi xe buýt và các em học sinh.","h2":"Ở Utah, trên xa lộ có dải phân cách với bốn làn trở lên, người lái đi ngược chiều về phía xe buýt trường học đang dừng không cần dừng, nhưng người lái phía sau xe buýt phải dừng.","p":"Đúng. Trên xa lộ có dải phân cách, xe đi ngược chiều không cần dừng."},"tl":{"q":"Sa Utah, nasa divided highway ka na may apat o higit pang lane at median. Huminto ang school bus sa kabilang panig na kumikislap ang pulang ilaw. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang mga ilaw","Huminto, saka lumampas sa 10 mph","Hindi mo kailangang huminto, pero manatiling alerto","Bumusina at panatilihin ang bilis"],"h1":"Inihihiwalay ka ng median sa bus at sa mga bata.","h2":"Sa Utah, sa divided highway na may apat o higit pang lane at median, ang mga driver na papalapit mula sa kabilang direksiyon sa nakahintong school bus ay hindi kailangang huminto, pero ang mga driver sa likod ng bus ay dapat huminto.","p":"Tama. Sa divided highway, hindi kailangang huminto ang trapiko sa kabilang direksiyon."},"ar":{"q":"في Utah، أنت على طريق سريع مقسوم فيه أربع حارات أو أكثر وفاصل في الوسط. توقفت حافلة مدرسية على الجهة الأخرى وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["توقّف حتى تنطفئ الأضواء","توقّف، ثم تجاوز بسرعة 10 mph","لا تحتاج أن تتوقف، لكن ابقَ منتبهًا","استخدم البوق وحافظ على سرعتك"],"h1":"الفاصل في الوسط يفصلك عن الحافلة والأطفال.","h2":"في Utah، على الطريق السريع المقسوم الذي فيه أربع حارات أو أكثر وفاصل في الوسط، السائقون القادمون من الاتجاه المقابل نحو حافلة مدرسية متوقفة لا يحتاجون أن يتوقفوا، لكن السائقين خلف الحافلة يجب أن يتوقفوا.","p":"صحيح. على الطريق المقسوم، السير في الاتجاه المقابل لا يحتاج أن يتوقف."},"ref":{"doc":"UT","page":36}},{"id":"ut-022","scope":"UT","cat":"signals","sign":null,"c":1,"en":{"q":"In Utah, when is a left turn on a red light allowed after a full stop?","o":["From any street onto a two-way street","From a one-way street onto another one-way street","Only when a police officer is present","Never, under any condition"],"h1":"Both streets must carry traffic in only one direction.","h2":"In Utah, you may turn left on red after a full stop only where two one-way streets meet, when it is safe and no sign forbids it.","p":"Right. Left on red is allowed only from one one-way street onto another."},"es":{"q":"En Utah, ¿cuándo se permite girar a la izquierda con luz roja después de detenerse por completo?","o":["Desde cualquier calle hacia una calle de doble sentido","Desde una calle de un solo sentido hacia otra de un solo sentido","Solo cuando hay un policía presente","Nunca, en ningún caso"],"h1":"Las dos calles deben tener tráfico en un solo sentido.","h2":"En Utah, usted puede girar a la izquierda con luz roja después de detenerse por completo solo donde se cruzan dos calles de un solo sentido, si es seguro y ninguna señal lo prohíbe.","p":"Correcto. Girar a la izquierda en rojo se permite solo de una calle de un solo sentido a otra."},"zh":{"q":"在 Utah，什么时候可以在完全停车后红灯左转？","o":["从任何街道转入双向街道","从单行道转入另一条单行道","只有在有警察在场时","在任何情况下都不可以"],"h1":"两条街道都必须只有一个方向的车流。","h2":"在 Utah，只有在两条单行道相交的地方，在安全且没有标志禁止时，你才可以在完全停车后红灯左转。","p":"对。只有从一条单行道转入另一条单行道时，才可以红灯左转。"},"vi":{"q":"Ở Utah, khi nào được rẽ trái khi đèn đỏ sau khi dừng hẳn?","o":["Từ bất kỳ đường nào vào đường hai chiều","Từ đường một chiều vào một đường một chiều khác","Chỉ khi có cảnh sát ở đó","Không bao giờ, trong bất kỳ trường hợp nào"],"h1":"Cả hai con đường đều phải chỉ có xe chạy một chiều.","h2":"Ở Utah, bạn chỉ được rẽ trái khi đèn đỏ sau khi dừng hẳn ở nơi hai đường một chiều gặp nhau, khi an toàn và không có biển cấm.","p":"Đúng. Rẽ trái khi đèn đỏ chỉ được phép từ một đường một chiều vào một đường một chiều khác."},"tl":{"q":"Sa Utah, kailan pinapayagan ang pagliko sa kaliwa sa pulang ilaw pagkatapos ng buong paghinto?","o":["Mula sa kahit anong kalye papunta sa two-way na kalye","Mula sa one-way na kalye papunta sa isa pang one-way na kalye","Kapag may pulis lang","Hindi kailanman, sa anumang kondisyon"],"h1":"Dapat iisang direksiyon lang ang trapiko sa parehong kalye.","h2":"Sa Utah, puwede kang lumiko sa kaliwa sa pulang ilaw pagkatapos ng buong paghinto lamang kung saan nagtatagpo ang dalawang one-way na kalye, kapag ligtas at walang sign na nagbabawal.","p":"Tama. Ang kaliwa sa pula ay pinapayagan lamang mula sa isang one-way na kalye papunta sa isa pa."},"ar":{"q":"في Utah، متى يُسمح بالانعطاف يسارًا عند الإشارة الحمراء بعد التوقف الكامل؟","o":["من أي شارع إلى شارع باتجاهين","من شارع باتجاه واحد إلى شارع آخر باتجاه واحد","فقط عندما يكون شرطي موجودًا","أبدًا، في أي حالة"],"h1":"يجب أن يكون السير في الشارعين باتجاه واحد فقط.","h2":"في Utah يجوز لك الانعطاف يسارًا عند الإشارة الحمراء بعد التوقف الكامل فقط حيث يلتقي شارعان باتجاه واحد، عندما يكون ذلك آمنًا ولا توجد لافتة تمنعه.","p":"صحيح. الانعطاف يسارًا عند الأحمر مسموح فقط من شارع باتجاه واحد إلى شارع آخر باتجاه واحد."},"ref":{"doc":"UT","page":null}},{"id":"ut-023","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what is the minimum liability insurance for policies issued since January 1, 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah raised its limits in 2025; the middle number is $65,000.","h2":"Since January 1, 2025, Utah requires at least $30,000 for injury to one person, $65,000 for injuries in one crash, and $25,000 for property damage.","p":"Right. The Utah minimum is now 30, 65 and 25 thousand dollars."},"es":{"q":"En Utah, ¿cuál es el seguro mínimo de responsabilidad civil para pólizas emitidas desde el 1 de enero de 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah subió sus límites en 2025; el número del medio es $65,000.","h2":"Desde el 1 de enero de 2025, Utah exige por lo menos $30,000 por lesiones a una persona, $65,000 por lesiones en un choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Utah ahora es de 30, 65 y 25 mil dólares."},"zh":{"q":"在 Utah，2025 年 1 月 1 日以后签发的保单，最低责任保险是多少？","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah 在 2025 年提高了标准；中间的数字是 $65,000。","h2":"从 2025 年 1 月 1 日起，Utah 要求至少：一个人受伤 $30,000，一次事故多人受伤 $65,000，财产损失 $25,000。","p":"对。Utah 现在的最低标准是 3 万、6 万 5 千和 2 万 5 千美元。"},"vi":{"q":"Ở Utah, bảo hiểm trách nhiệm tối thiểu cho các hợp đồng được cấp từ ngày 1 tháng 1 năm 2025 là bao nhiêu?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Utah đã tăng mức tối thiểu vào năm 2025; số ở giữa là $65,000.","h2":"Từ ngày 1 tháng 1 năm 2025, Utah yêu cầu ít nhất $30,000 cho thương tích của một người, $65,000 cho thương tích trong một vụ tai nạn, và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu ở Utah bây giờ là 30, 65 và 25 nghìn đô la."},"tl":{"q":"Sa Utah, ano ang minimum na liability insurance para sa mga policy na inilabas mula Enero 1, 2025?","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"Itinaas ng Utah ang mga limitasyon noong 2025; $65,000 ang gitnang numero.","h2":"Mula Enero 1, 2025, kailangan ng Utah ang hindi bababa sa $30,000 para sa pinsala sa isang tao, $65,000 para sa mga pinsala sa isang aksidente, at $25,000 para sa pinsala sa ari-arian.","p":"Tama. Ang minimum sa Utah ngayon ay 30, 65 at 25 libong dolyar."},"ar":{"q":"في Utah، ما الحدّ الأدنى لتأمين المسؤولية للوثائق الصادرة منذ 1 يناير 2025؟","o":["$30,000 / $65,000 / $25,000","$25,000 / $50,000 / $25,000","$25,000 / $65,000 / $15,000","$15,000 / $30,000 / $10,000"],"h1":"رفعت Utah حدودها في سنة 2025؛ الرقم الأوسط هو $65,000.","h2":"منذ 1 يناير 2025 تطلب Utah على الأقل $30,000 لإصابة شخص واحد، و$65,000 للإصابات في حادث واحد، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحدّ الأدنى في Utah الآن هو 30 و65 و25 ألف دولار."},"ref":{"doc":"UT","page":null}},{"id":"ut-024","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, besides liability, what minimum personal injury protection must a driver carry?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah is a no-fault state, and this amount is a few thousand dollars.","h2":"Utah is a no-fault state, so drivers must also carry at least $3,000 of personal injury protection to pay their own medical costs after a crash.","p":"Right. Utah requires $3,000 of personal injury protection."},"es":{"q":"En Utah, además de la responsabilidad civil, ¿qué protección mínima contra lesiones personales debe tener un conductor?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah es un estado sin culpa, y esta cantidad es de unos miles de dólares.","h2":"Utah es un estado sin culpa, así que los conductores también deben tener por lo menos $3,000 de protección contra lesiones personales para pagar sus propios gastos médicos después de un choque.","p":"Correcto. Utah exige $3,000 de protección contra lesiones personales."},"zh":{"q":"在 Utah，除了责任保险以外，司机还必须买多少最低的个人伤害保障（personal injury protection）？","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah 是无过失（no-fault）州，这个金额是几千美元。","h2":"Utah 是无过失（no-fault）州，所以司机还必须买至少 $3,000 的个人伤害保障（personal injury protection），用来支付自己在事故后的医疗费用。","p":"对。Utah 要求 $3,000 的个人伤害保障。"},"vi":{"q":"Ở Utah, ngoài bảo hiểm trách nhiệm, người lái phải có mức bảo vệ thương tích cá nhân (personal injury protection) tối thiểu là bao nhiêu?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah là tiểu bang không lỗi (no-fault), và số tiền này là vài nghìn đô la.","h2":"Utah là tiểu bang không lỗi (no-fault), nên người lái cũng phải có ít nhất $3,000 bảo vệ thương tích cá nhân (personal injury protection) để trả chi phí y tế của chính mình sau tai nạn.","p":"Đúng. Utah yêu cầu $3,000 bảo vệ thương tích cá nhân."},"tl":{"q":"Sa Utah, bukod sa liability, anong minimum na personal injury protection ang dapat mayroon ang driver?","o":["$500","$1,000","$10,000","$3,000"],"h1":"Isang no-fault state ang Utah, at ilang libong dolyar ang halagang ito.","h2":"Isang no-fault state ang Utah, kaya dapat ding may hindi bababa sa $3,000 na personal injury protection ang mga driver para bayaran ang sarili nilang gastos sa pagpapagamot pagkatapos ng aksidente.","p":"Tama. Kailangan ng Utah ang $3,000 na personal injury protection."},"ar":{"q":"في Utah، بالإضافة إلى تأمين المسؤولية، ما الحدّ الأدنى لتأمين الحماية من الإصابة الشخصية (personal injury protection) الذي يجب أن يكون لدى السائق؟","o":["$500","$1,000","$10,000","$3,000"],"h1":"Utah ولاية بدون خطأ (no-fault)، وهذا المبلغ بضعة آلاف من الدولارات.","h2":"Utah ولاية بدون خطأ (no-fault)، لذلك يجب أن يكون لدى السائقين أيضًا $3,000 على الأقل من الحماية من الإصابة الشخصية (personal injury protection) لدفع تكاليفهم الطبية بعد الحادث.","p":"صحيح. تطلب Utah مبلغ $3,000 للحماية من الإصابة الشخصية."},"ref":{"doc":"UT","page":null}},{"id":"ut-025","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how many questions are on the written knowledge test for a person who has never had a license?","o":["20 questions","25 questions","50 questions","100 questions"],"h1":"Drivers who had a license before take a shorter test.","h2":"In Utah, a person who has never been licensed takes a 50-question knowledge test, while a previously licensed driver takes a 25-question test.","p":"Right. New drivers answer 50 questions."},"es":{"q":"En Utah, ¿cuántas preguntas tiene el examen escrito para una persona que nunca ha tenido licencia?","o":["20 preguntas","25 preguntas","50 preguntas","100 preguntas"],"h1":"Quienes ya tuvieron licencia hacen un examen más corto.","h2":"En Utah, una persona que nunca ha tenido licencia hace un examen de 50 preguntas, mientras que quien ya tuvo licencia hace un examen de 25 preguntas.","p":"Correcto. Los conductores nuevos responden 50 preguntas."},"zh":{"q":"在 Utah，从来没有拿过驾照的人，笔试有多少道题？","o":["20 道题","25 道题","50 道题","100 道题"],"h1":"以前有过驾照的司机考的题目更少。","h2":"在 Utah，从来没有拿过驾照的人要考 50 道题的笔试，以前有过驾照的司机考 25 道题。","p":"对。新司机要回答 50 道题。"},"vi":{"q":"Ở Utah, bài thi kiến thức viết có bao nhiêu câu hỏi cho người chưa bao giờ có bằng lái?","o":["20 câu hỏi","25 câu hỏi","50 câu hỏi","100 câu hỏi"],"h1":"Người đã từng có bằng lái làm bài thi ngắn hơn.","h2":"Ở Utah, người chưa bao giờ có bằng lái làm bài thi kiến thức 50 câu, còn người đã từng có bằng lái làm bài thi 25 câu.","p":"Đúng. Người lái mới trả lời 50 câu hỏi."},"tl":{"q":"Sa Utah, ilang tanong ang nasa written knowledge test para sa taong hindi pa nagkaroon ng license?","o":["20 tanong","25 tanong","50 tanong","100 tanong"],"h1":"Mas maikling test ang kinukuha ng mga driver na nagkaroon na ng license dati.","h2":"Sa Utah, ang taong hindi pa nagkaroon ng license ay kumukuha ng knowledge test na may 50 tanong, habang ang driver na nagkaroon na ng license dati ay kumukuha ng test na may 25 tanong.","p":"Tama. Sinasagot ng mga bagong driver ang 50 tanong."},"ar":{"q":"في Utah، كم سؤالًا في الاختبار النظري المكتوب للشخص الذي لم تكن لديه رخصة أبدًا؟","o":["20 سؤالًا","25 سؤالًا","50 سؤالًا","100 سؤال"],"h1":"السائقون الذين كانت لديهم رخصة من قبل يأخذون اختبارًا أقصر.","h2":"في Utah، الشخص الذي لم تكن لديه رخصة أبدًا يأخذ اختبارًا نظريًا فيه 50 سؤالًا، أما السائق الذي كانت لديه رخصة من قبل فيأخذ اختبارًا فيه 25 سؤالًا.","p":"صحيح. السائقون الجدد يجيبون عن 50 سؤالًا."},"ref":{"doc":"UT","page":null}},{"id":"ut-026","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what score do you need to pass the written knowledge test?","o":["70 percent","80 percent","75 percent","90 percent"],"h1":"It is the same passing score many states use.","h2":"Utah requires you to answer at least 80 percent of the knowledge test questions correctly, which is 40 out of 50.","p":"Right. You need 80 percent to pass."},"es":{"q":"En Utah, ¿qué puntaje necesita para aprobar el examen escrito?","o":["70 por ciento","80 por ciento","75 por ciento","90 por ciento"],"h1":"Es el mismo puntaje que usan muchos estados para aprobar.","h2":"Utah exige que usted conteste bien por lo menos el 80 por ciento de las preguntas del examen, es decir, 40 de 50.","p":"Correcto. Necesita 80 por ciento para aprobar."},"zh":{"q":"在 Utah，笔试需要多少分才能通过？","o":["70%","80%","75%","90%"],"h1":"和很多州的及格分数一样。","h2":"Utah 要求你答对至少 80% 的笔试题目，也就是 50 道题中答对 40 道。","p":"对。你需要 80% 才能通过。"},"vi":{"q":"Ở Utah, bạn cần bao nhiêu điểm để đậu bài thi kiến thức viết?","o":["70 phần trăm","80 phần trăm","75 phần trăm","90 phần trăm"],"h1":"Đó là điểm đậu giống nhiều tiểu bang khác.","h2":"Utah yêu cầu bạn trả lời đúng ít nhất 80 phần trăm câu hỏi của bài thi kiến thức, tức là 40 trên 50 câu.","p":"Đúng. Bạn cần 80 phần trăm để đậu."},"tl":{"q":"Sa Utah, anong score ang kailangan mo para pumasa sa written knowledge test?","o":["70 porsiyento","80 porsiyento","75 porsiyento","90 porsiyento"],"h1":"Ito ang parehong passing score na ginagamit ng maraming estado.","h2":"Kailangan ng Utah na masagot mo nang tama ang hindi bababa sa 80 porsiyento ng mga tanong sa knowledge test, ibig sabihin 40 sa 50.","p":"Tama. Kailangan mo ng 80 porsiyento para pumasa."},"ar":{"q":"في Utah، ما الدرجة التي تحتاجها للنجاح في الاختبار النظري المكتوب؟","o":["70 بالمئة","80 بالمئة","75 بالمئة","90 بالمئة"],"h1":"هي نفس درجة النجاح التي تستخدمها ولايات كثيرة.","h2":"تطلب Utah أن تجيب إجابة صحيحة عن 80 بالمئة على الأقل من أسئلة الاختبار النظري، أي 40 من 50.","p":"صحيح. تحتاج 80 بالمئة للنجاح."},"ref":{"doc":"UT","page":23}},{"id":"ut-027","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, how close to a fire hydrant may you park?","o":["Up to 5 feet away","Up to 10 feet away","No closer than 15 feet","No closer than 30 feet"],"h1":"Firefighters need room to reach the hydrant.","h2":"In Utah, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant."},"es":{"q":"En Utah, ¿a qué distancia de un hidrante puede estacionarse?","o":["Hasta 5 pies de distancia","Hasta 10 pies de distancia","No más cerca de 15 pies","No más cerca de 30 pies"],"h1":"Los bomberos necesitan espacio para llegar al hidrante.","h2":"En Utah, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Utah，你可以把车停在离消防栓多近的地方？","o":["最近 5 英尺","最近 10 英尺","不能少于 15 英尺","不能少于 30 英尺"],"h1":"消防员需要空间才能接到消防栓。","h2":"在 Utah，你不能把车停在离消防栓 15 英尺以内的地方。","p":"对。要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Utah, bạn được đậu xe gần trụ nước cứu hỏa đến mức nào?","o":["Cách tối đa 5 feet","Cách tối đa 10 feet","Không gần hơn 15 feet","Không gần hơn 30 feet"],"h1":"Lính cứu hỏa cần chỗ trống để đến được trụ nước.","h2":"Ở Utah, bạn không được đậu xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Hãy đậu xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Utah, gaano kalapit sa fire hydrant ka puwedeng mag-park?","o":["Hanggang 5 feet ang layo","Hanggang 10 feet ang layo","Hindi lalapit sa 15 feet","Hindi lalapit sa 30 feet"],"h1":"Kailangan ng mga bumbero ng espasyo para maabot ang hydrant.","h2":"Sa Utah, hindi ka puwedeng mag-park sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant."},"ar":{"q":"في Utah، إلى أي مدى يمكنك أن تركن قرب حنفية إطفاء الحريق؟","o":["حتى 5 feet بعيدًا","حتى 10 feet بعيدًا","ليس أقرب من 15 feet","ليس أقرب من 30 feet"],"h1":"يحتاج رجال الإطفاء إلى مساحة للوصول إلى الحنفية.","h2":"في Utah لا يجوز لك أن تركن على مسافة أقل من 15 feet من حنفية إطفاء الحريق.","p":"صحيح. ابقَ على بُعد 15 feet على الأقل من حنفية إطفاء الحريق."},"ref":{"doc":"UT","page":32}},{"id":"ut-028","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, how much space must you leave when you pass a bicyclist?","o":["At least 3 feet","At least 1 foot","At least 10 feet","Any space is fine if you honk"],"h1":"Utah law sets a minimum distance for passing people on bikes.","h2":"In Utah, the law requires you to leave at least three feet between your vehicle and a bicyclist you are passing.","p":"Right. Give a bicyclist at least 3 feet."},"es":{"q":"En Utah, ¿cuánto espacio debe dejar al rebasar a un ciclista?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 10 pies","Cualquier espacio si toca la bocina"],"h1":"La ley de Utah fija una distancia mínima para rebasar a personas en bicicleta.","h2":"En Utah, la ley exige que deje por lo menos tres pies entre su vehículo y el ciclista que rebasa.","p":"Correcto. Deje por lo menos 3 pies al ciclista."},"zh":{"q":"在 Utah，超过骑自行车的人时，你必须留出多大的空间？","o":["至少 3 英尺","至少 1 英尺","至少 10 英尺","只要按喇叭，多少空间都可以"],"h1":"Utah 法律规定了超过骑车人时的最小距离。","h2":"在 Utah，法律要求你超过骑自行车的人时，你的车和骑车人之间至少要留 3 英尺。","p":"对。要给骑自行车的人留至少 3 英尺。"},"vi":{"q":"Ở Utah, bạn phải chừa khoảng cách bao nhiêu khi vượt người đi xe đạp?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 10 feet","Khoảng cách nào cũng được nếu bạn bấm còi"],"h1":"Luật Utah đặt ra khoảng cách tối thiểu khi vượt người đi xe đạp.","h2":"Ở Utah, luật bắt buộc bạn chừa ít nhất 3 feet giữa xe của bạn và người đi xe đạp mà bạn đang vượt.","p":"Đúng. Hãy chừa cho người đi xe đạp ít nhất 3 feet."},"tl":{"q":"Sa Utah, gaano kalaking espasyo ang dapat mong iwan kapag nilalampasan mo ang nagbibisikleta?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet","Ayos lang ang kahit anong espasyo kung bubusina ka"],"h1":"May itinakdang pinakamaliit na layo ang batas ng Utah sa paglampas sa mga nagbibisikleta.","h2":"Sa Utah, iniuutos ng batas na mag-iwan ka ng hindi bababa sa 3 feet sa pagitan ng sasakyan mo at ng nagbibisikletang nilalampasan mo.","p":"Tama. Bigyan ang nagbibisikleta ng hindi bababa sa 3 feet."},"ar":{"q":"في Utah، ما المسافة التي يجب أن تتركها عندما تتجاوز راكب دراجة هوائية؟","o":["3 feet على الأقل","1 foot على الأقل","10 feet على الأقل","أي مسافة مقبولة إذا استخدمت البوق"],"h1":"قانون Utah يحدد مسافة دنيا عند تجاوز راكبي الدراجات.","h2":"في Utah يُلزمك القانون بأن تترك 3 feet على الأقل بين سيارتك وراكب الدراجة الذي تتجاوزه.","p":"صحيح. اترك لراكب الدراجة 3 feet على الأقل."},"ref":{"doc":"UT","page":75}},{"id":"ut-029","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, when may a motorcycle rider pass between cars in the same lane (lane filtering)?","o":["At any speed on the freeway","Only on an on-ramp","Whenever traffic is moving slowly","When the cars are stopped and the speed limit is 45 mph or less"],"h1":"The cars being passed must not be moving.","h2":"In Utah, a motorcycle may filter between lanes only past vehicles that are stopped, at 15 mph or less, on a road with two or more lanes going the same way and a speed limit of 45 mph or less, or on an off-ramp, and never on an on-ramp.","p":"Right. Only past stopped cars, at 15 mph or less, on roads of 45 mph or less."},"es":{"q":"En Utah, ¿cuándo puede un motociclista pasar entre autos en el mismo carril (lane filtering)?","o":["A cualquier velocidad en la autopista","Solo en una rampa de entrada","Siempre que el tráfico avance despacio","Cuando los autos están detenidos y el límite es de 45 mph o menos"],"h1":"Los autos que rebasa no deben estar en movimiento.","h2":"En Utah, una motocicleta puede pasar entre carriles (lane filtering) solo junto a vehículos detenidos, a 15 mph o menos, en una vía con dos o más carriles en el mismo sentido y un límite de 45 mph o menos, o en una rampa de salida, y nunca en una rampa de entrada.","p":"Correcto. Solo junto a autos detenidos, a 15 mph o menos, en vías de 45 mph o menos."},"zh":{"q":"在 Utah，骑摩托车的人什么时候可以在同一车道的车辆之间穿行（lane filtering）？","o":["在高速公路上任何速度都可以","只在高速公路入口匝道上","只要车流走得慢就可以","当车辆停着，而且限速是 45 mph 或以下时"],"h1":"被超过的车辆必须是停着不动的。","h2":"在 Utah，摩托车只能从停着的车辆旁边穿行，速度要在 15 mph 或以下，道路要有两条或更多同方向车道且限速 45 mph 或以下，或者在出口匝道上，绝不能在入口匝道上。","p":"对。只能从停着的车旁边穿行，速度 15 mph 或以下，在限速 45 mph 或以下的道路上。"},"vi":{"q":"Ở Utah, khi nào người lái xe máy được chạy len giữa các xe trong cùng làn (lane filtering)?","o":["Ở bất kỳ tốc độ nào trên xa lộ","Chỉ trên đường dẫn vào xa lộ","Bất cứ khi nào xe cộ chạy chậm","Khi các xe đang dừng và tốc độ giới hạn là 45 mph hoặc thấp hơn"],"h1":"Các xe được vượt phải đang đứng yên.","h2":"Ở Utah, xe máy chỉ được chạy len qua các xe đang dừng, ở tốc độ 15 mph hoặc thấp hơn, trên đường có hai làn trở lên cùng chiều và tốc độ giới hạn 45 mph hoặc thấp hơn, hoặc trên đường dẫn ra khỏi xa lộ, và không bao giờ trên đường dẫn vào xa lộ.","p":"Đúng. Chỉ qua các xe đang dừng, ở 15 mph hoặc thấp hơn, trên đường 45 mph hoặc thấp hơn."},"tl":{"q":"Sa Utah, kailan puwedeng sumingit ang nagmomotorsiklo sa pagitan ng mga kotse sa iisang lane (lane filtering)?","o":["Sa kahit anong bilis sa freeway","Sa on-ramp lang","Tuwing mabagal ang takbo ng trapiko","Kapag nakahinto ang mga kotse at 45 mph o mas mababa ang speed limit"],"h1":"Hindi dapat gumagalaw ang mga kotseng nilalampasan.","h2":"Sa Utah, puwede lang sumingit ang motorsiklo sa mga sasakyang nakahinto, sa bilis na 15 mph o mas mababa, sa daan na may dalawa o higit pang lane na pareho ang direksyon at may speed limit na 45 mph o mas mababa, o sa off-ramp, at hindi kailanman sa on-ramp.","p":"Tama. Sa mga nakahintong kotse lang, sa 15 mph o mas mababa, sa mga daang 45 mph o mas mababa."},"ar":{"q":"في Utah، متى يجوز لسائق الدراجة النارية أن يمرّ بين السيارات في المسار نفسه (lane filtering)؟","o":["بأي سرعة على الطريق السريع","فقط على منحدر الدخول إلى الطريق السريع","كلما كانت حركة السير بطيئة","عندما تكون السيارات متوقفة وحد السرعة 45 mph أو أقل"],"h1":"يجب ألا تكون السيارات التي يمرّ بجانبها متحركة.","h2":"في Utah يجوز للدراجة النارية أن تمرّ بين المسارات فقط بجانب سيارات متوقفة، بسرعة 15 mph أو أقل، على طريق فيه مساران أو أكثر في الاتجاه نفسه وحد سرعته 45 mph أو أقل، أو على منحدر الخروج، ولا يجوز ذلك أبدًا على منحدر الدخول.","p":"صحيح. فقط بجانب سيارات متوقفة، بسرعة 15 mph أو أقل، على طرق حد سرعتها 45 mph أو أقل."},"ref":{"doc":"UT","page":82}},{"id":"ut-030","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, which children must ride in an approved child safety seat?","o":["Only babies under 1 year","Children 8 and under, unless they are 57 inches tall","Children under 4 only","Children under 12 riding in front"],"h1":"The rule uses an age and a height.","h2":"In Utah, all children aged eight and under must be secured in an approved child safety seat unless they are 57 inches tall.","p":"Right. Age 8 and under, unless 57 inches tall."},"es":{"q":"En Utah, ¿qué niños deben ir en un asiento de seguridad aprobado?","o":["Solo los bebés menores de 1 año","Los niños de 8 años o menos, salvo que midan 57 pulgadas","Solo los menores de 4 años","Los menores de 12 años que van adelante"],"h1":"La regla usa una edad y una estatura.","h2":"En Utah, todos los niños de ocho años o menos deben ir sujetos en un asiento de seguridad aprobado, salvo que midan 57 pulgadas.","p":"Correcto. Ocho años o menos, salvo que midan 57 pulgadas."},"zh":{"q":"在 Utah，哪些孩子必须坐在合格的儿童安全座椅里？","o":["只有 1 岁以下的婴儿","8 岁及以下的孩子，除非身高达到 57 英寸","只有 4 岁以下的孩子","坐在前排的 12 岁以下孩子"],"h1":"这条规定用的是年龄和身高。","h2":"在 Utah，所有 8 岁及以下的孩子都必须坐在合格的儿童安全座椅里并固定好，除非身高达到 57 英寸。","p":"对。8 岁及以下，除非身高 57 英寸。"},"vi":{"q":"Ở Utah, những trẻ em nào phải ngồi ghế an toàn cho trẻ em được chấp thuận?","o":["Chỉ em bé dưới 1 tuổi","Trẻ từ 8 tuổi trở xuống, trừ khi cao 57 inches","Chỉ trẻ dưới 4 tuổi","Trẻ dưới 12 tuổi ngồi ghế trước"],"h1":"Quy định này dùng cả tuổi và chiều cao.","h2":"Ở Utah, mọi trẻ em từ 8 tuổi trở xuống phải được cài chặt trong ghế an toàn cho trẻ em được chấp thuận, trừ khi trẻ cao 57 inches.","p":"Đúng. Từ 8 tuổi trở xuống, trừ khi cao 57 inches."},"tl":{"q":"Sa Utah, aling mga bata ang dapat nakaupo sa aprubadong child safety seat?","o":["Mga sanggol lang na wala pang 1 taon","Mga batang 8 taong gulang pababa, maliban kung 57 inches ang taas nila","Mga batang wala pang 4 taon lang","Mga batang wala pang 12 taon na nakaupo sa harap"],"h1":"Gumagamit ang patakaran ng edad at taas.","h2":"Sa Utah, lahat ng batang 8 taong gulang pababa ay dapat nakakabit sa aprubadong child safety seat, maliban kung 57 inches ang taas nila.","p":"Tama. 8 taong gulang pababa, maliban kung 57 inches ang taas."},"ar":{"q":"في Utah، أي الأطفال يجب أن يجلسوا في مقعد أمان معتمد للأطفال؟","o":["الرُّضّع تحت عمر سنة واحدة فقط","الأطفال بعمر 8 سنوات وأقل، إلا إذا كان طولهم 57 inches","الأطفال تحت 4 سنوات فقط","الأطفال تحت 12 سنة الذين يجلسون في الأمام"],"h1":"القاعدة تستخدم العمر والطول.","h2":"في Utah يجب تثبيت جميع الأطفال بعمر 8 سنوات وأقل في مقعد أمان معتمد للأطفال، إلا إذا كان طولهم 57 inches.","p":"صحيح. بعمر 8 سنوات وأقل، إلا إذا كان الطول 57 inches."},"ref":{"doc":"UT","page":28}},{"id":"ut-031","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, when you renew a regular driver license, for how long is the new license good?","o":["Two years","Four years","Eight years","For life"],"h1":"It is longer than in many states.","h2":"In Utah, a renewed regular driver license expires on your birthday eight years after it is issued.","p":"Right. A renewed license lasts eight years."},"es":{"q":"En Utah, cuando renueva una licencia de conducir regular, ¿por cuánto tiempo es válida la nueva licencia?","o":["Dos años","Cuatro años","Ocho años","De por vida"],"h1":"Es más tiempo que en muchos estados.","h2":"En Utah, una licencia regular renovada vence en su cumpleaños ocho años después de emitida.","p":"Correcto. Una licencia renovada dura ocho años."},"zh":{"q":"在 Utah，换发普通驾照后，新驾照的有效期是多久？","o":["两年","四年","八年","终身有效"],"h1":"它比很多州的有效期都长。","h2":"在 Utah，换发的普通驾照在签发八年后你生日那天到期。","p":"对。换发的驾照有效八年。"},"vi":{"q":"Ở Utah, khi bạn gia hạn bằng lái thường, bằng lái mới có giá trị trong bao lâu?","o":["Hai năm","Bốn năm","Tám năm","Suốt đời"],"h1":"Thời hạn này dài hơn ở nhiều tiểu bang khác.","h2":"Ở Utah, bằng lái thường được gia hạn sẽ hết hạn vào ngày sinh nhật của bạn tám năm sau khi được cấp.","p":"Đúng. Bằng lái được gia hạn có giá trị tám năm."},"tl":{"q":"Sa Utah, kapag nag-renew ka ng regular na driver license, gaano katagal valid ang bagong license?","o":["Dalawang taon","Apat na taon","Walong taon","Habambuhay"],"h1":"Mas mahaba ito kaysa sa maraming estado.","h2":"Sa Utah, ang na-renew na regular na driver license ay mag-e-expire sa kaarawan mo walong taon matapos itong ibigay.","p":"Tama. Walong taon ang bisa ng na-renew na license."},"ar":{"q":"في Utah، عندما تجدّد رخصة القيادة العادية، كم مدة صلاحية الرخصة الجديدة؟","o":["سنتان","أربع سنوات","ثماني سنوات","مدى الحياة"],"h1":"هي أطول مما في كثير من الولايات.","h2":"في Utah تنتهي رخصة القيادة العادية المجدّدة في يوم عيد ميلادك بعد ثماني سنوات من إصدارها.","p":"صحيح. الرخصة المجدّدة صالحة لثماني سنوات."},"ref":{"doc":"UT","page":18}},{"id":"ut-032","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, you moved to a new home. How soon must you tell the Driver License Division your new address?","o":["Within 10 days","Within 30 days","Within 60 days","When you renew your license"],"h1":"It is a short time, well under a month.","h2":"In Utah, you must give the Driver License Division your new address within 10 days of moving.","p":"Right. In Utah, you report a new address within 10 days."},"es":{"q":"En Utah, usted se mudó a una casa nueva. ¿En cuánto tiempo debe informar su nueva dirección a la División de Licencias de Conducir?","o":["En 10 días","En 30 días","En 60 días","Cuando renueve su licencia"],"h1":"Es poco tiempo, mucho menos de un mes.","h2":"En Utah, usted debe dar su nueva dirección a la División de Licencias de Conducir dentro de los 10 días después de mudarse.","p":"Correcto. En Utah, usted informa su nueva dirección en 10 días."},"zh":{"q":"在 Utah，你搬了新家。你必须在多长时间内把新地址告诉驾照部门（Driver License Division）？","o":["10 天内","30 天内","60 天内","更新驾照的时候"],"h1":"时间很短，远少于一个月。","h2":"在 Utah，搬家后你必须在 10 天内把新地址告诉驾照部门。","p":"对。在 Utah，你要在 10 天内报告新地址。"},"vi":{"q":"Ở Utah, bạn đã dọn đến nhà mới. Bạn phải báo địa chỉ mới cho Sở Bằng Lái (Driver License Division) trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 60 ngày","Khi bạn gia hạn bằng lái"],"h1":"Đó là một thời gian ngắn, ít hơn nhiều so với một tháng.","h2":"Ở Utah, bạn phải báo địa chỉ mới cho Sở Bằng Lái trong vòng 10 ngày sau khi dọn nhà.","p":"Đúng. Ở Utah, bạn báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Utah, lumipat ka sa bagong bahay. Gaano kabilis mo dapat sabihin sa Driver License Division ang bago mong address?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 60 araw","Kapag nag-renew ka ng license"],"h1":"Maikling panahon ito, mas maikli pa nang malaki sa isang buwan.","h2":"Sa Utah, dapat mong ibigay sa Driver License Division ang bago mong address sa loob ng 10 araw pagkalipat mo.","p":"Tama. Sa Utah, iniuulat mo ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Utah، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تُبلغ قسم رخص القيادة (Driver License Division) بعنوانك الجديد؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 60 يومًا","عندما تجدّد رخصتك"],"h1":"هي مدة قصيرة، أقل بكثير من شهر.","h2":"في Utah يجب أن تُبلغ قسم رخص القيادة بعنوانك الجديد خلال 10 أيام من انتقالك.","p":"صحيح. في Utah تُبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"UT","page":19}},{"id":"ut-033","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, a first-time Class D applicant must also pass the online Traffic Safety and Trends exam. What score is needed?","o":["70 percent","80 percent","90 percent","100 percent"],"h1":"This exam can be taken as many times as needed, so no mistakes are allowed in the end.","h2":"In Utah, a first-time Class D applicant must score 100 percent on the online Traffic Safety and Trends exam.","p":"Right. The Utah Traffic Safety and Trends exam needs a perfect score of 100 percent."},"es":{"q":"En Utah, quien solicita por primera vez una licencia Clase D también debe aprobar el examen en línea Traffic Safety and Trends. ¿Qué puntaje necesita?","o":["70 por ciento","80 por ciento","90 por ciento","100 por ciento"],"h1":"Este examen se puede tomar todas las veces que haga falta, así que al final no se permiten errores.","h2":"En Utah, quien solicita por primera vez una licencia Clase D debe sacar 100 por ciento en el examen en línea Traffic Safety and Trends.","p":"Correcto. El examen Traffic Safety and Trends de Utah exige un puntaje perfecto de 100 por ciento."},"zh":{"q":"在 Utah，第一次申请 Class D 驾照的人还必须通过网上的交通安全与趋势考试（Traffic Safety and Trends exam）。需要考多少分？","o":["70%","80%","90%","100%"],"h1":"这个考试可以考很多次，所以最后不能有任何错误。","h2":"在 Utah，第一次申请 Class D 驾照的人必须在网上的交通安全与趋势考试中考到 100%。","p":"对。Utah 的交通安全与趋势考试需要考满分 100%。"},"vi":{"q":"Ở Utah, người xin bằng Class D lần đầu cũng phải đậu bài thi trực tuyến về An toàn và Xu hướng Giao thông (Traffic Safety and Trends exam). Cần đạt bao nhiêu điểm?","o":["70 phần trăm","80 phần trăm","90 phần trăm","100 phần trăm"],"h1":"Bài thi này có thể làm lại bao nhiêu lần cũng được, nên cuối cùng không được sai câu nào.","h2":"Ở Utah, người xin bằng Class D lần đầu phải đạt 100 phần trăm trong bài thi trực tuyến về An toàn và Xu hướng Giao thông.","p":"Đúng. Bài thi An toàn và Xu hướng Giao thông ở Utah cần điểm tuyệt đối 100 phần trăm."},"tl":{"q":"Sa Utah, ang unang beses na aplikante ng Class D ay dapat ding pumasa sa online na Traffic Safety and Trends exam. Anong score ang kailangan?","o":["70 porsiyento","80 porsiyento","90 porsiyento","100 porsiyento"],"h1":"Puwedeng kunin ang exam na ito nang ilang beses hangga't kailangan, kaya sa huli walang puwedeng mali.","h2":"Sa Utah, ang unang beses na aplikante ng Class D ay dapat makakuha ng 100 porsiyento sa online na Traffic Safety and Trends exam.","p":"Tama. Kailangan ng perpektong score na 100 porsiyento sa Utah Traffic Safety and Trends exam."},"ar":{"q":"في Utah، يجب على من يتقدّم لأول مرة لرخصة Class D أن ينجح أيضًا في امتحان السلامة والاتجاهات المرورية عبر الإنترنت (Traffic Safety and Trends exam). ما الدرجة المطلوبة؟","o":["70 بالمئة","80 بالمئة","90 بالمئة","100 بالمئة"],"h1":"يمكن إعادة هذا الامتحان كلما احتجت، لذلك في النهاية لا يُسمح بأي خطأ.","h2":"في Utah يجب على من يتقدّم لأول مرة لرخصة Class D أن يحصل على 100 بالمئة في امتحان السلامة والاتجاهات المرورية عبر الإنترنت.","p":"صحيح. امتحان السلامة والاتجاهات المرورية في Utah يحتاج إلى درجة كاملة 100 بالمئة."},"ref":{"doc":"UT","page":23}},{"id":"ut-034","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, what vision do you need to drive a regular Class D vehicle?","o":["20/20 in both eyes","20/40 in at least one eye","20/60 in at least one eye","20/100 in both eyes"],"h1":"Only one eye has to meet the standard.","h2":"In Utah, you need 20/40 vision in at least one eye to drive a regular Class D vehicle.","p":"Right. Utah asks for 20/40 vision in at least one eye."},"es":{"q":"En Utah, ¿qué visión necesita para conducir un vehículo regular Clase D?","o":["20/20 en ambos ojos","20/40 en por lo menos un ojo","20/60 en por lo menos un ojo","20/100 en ambos ojos"],"h1":"Solo un ojo tiene que cumplir el requisito.","h2":"En Utah, usted necesita una visión de 20/40 en por lo menos un ojo para conducir un vehículo regular Clase D.","p":"Correcto. Utah pide una visión de 20/40 en por lo menos un ojo."},"zh":{"q":"在 Utah，驾驶普通 Class D 车辆需要什么视力？","o":["两只眼睛都是 20/20","至少一只眼睛 20/40","至少一只眼睛 20/60","两只眼睛都是 20/100"],"h1":"只需要一只眼睛达到标准。","h2":"在 Utah，驾驶普通 Class D 车辆需要至少一只眼睛的视力达到 20/40。","p":"对。Utah 要求至少一只眼睛视力 20/40。"},"vi":{"q":"Ở Utah, bạn cần thị lực thế nào để lái xe Class D thông thường?","o":["20/20 ở cả hai mắt","20/40 ở ít nhất một mắt","20/60 ở ít nhất một mắt","20/100 ở cả hai mắt"],"h1":"Chỉ cần một mắt đạt tiêu chuẩn.","h2":"Ở Utah, bạn cần thị lực 20/40 ở ít nhất một mắt để lái xe Class D thông thường.","p":"Đúng. Utah yêu cầu thị lực 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa Utah, anong paningin ang kailangan mo para magmaneho ng karaniwang Class D na sasakyan?","o":["20/20 sa dalawang mata","20/40 sa kahit isang mata","20/60 sa kahit isang mata","20/100 sa dalawang mata"],"h1":"Isang mata lang ang kailangang umabot sa pamantayan.","h2":"Sa Utah, kailangan mo ng 20/40 na paningin sa kahit isang mata para magmaneho ng karaniwang Class D na sasakyan.","p":"Tama. Humihingi ang Utah ng 20/40 na paningin sa kahit isang mata."},"ar":{"q":"في Utah، ما قوة النظر التي تحتاجها لقيادة مركبة عادية من فئة Class D؟","o":["20/20 في العينين كلتيهما","20/40 في عين واحدة على الأقل","20/60 في عين واحدة على الأقل","20/100 في العينين كلتيهما"],"h1":"يكفي أن تبلغ عين واحدة المستوى المطلوب.","h2":"في Utah تحتاج إلى نظر 20/40 في عين واحدة على الأقل لقيادة مركبة عادية من فئة Class D.","p":"صحيح. تطلب Utah نظرًا 20/40 في عين واحدة على الأقل."},"ref":{"doc":"UT","page":21}},{"id":"ut-035","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a driver under 21 is caught driving with any alcohol in their body for the first time. For how long are driving privileges denied?","o":["30 days","90 days","Six months","Two years"],"h1":"It is half a year.","h2":"In Utah, under the Not-a-Drop Act, a driver under 21 with any alcohol in their body loses driving privileges for six months on a first offense.","p":"Right. In Utah, a first Not-a-Drop offense means six months without driving."},"es":{"q":"En Utah, un conductor menor de 21 años es detenido por primera vez conduciendo con alcohol en el cuerpo. ¿Por cuánto tiempo se le niega el privilegio de conducir?","o":["30 días","90 días","Seis meses","Dos años"],"h1":"Es medio año.","h2":"En Utah, según la ley Not-a-Drop, un conductor menor de 21 años con cualquier cantidad de alcohol en el cuerpo pierde el privilegio de conducir por seis meses en la primera infracción.","p":"Correcto. En Utah, una primera infracción Not-a-Drop significa seis meses sin conducir."},"zh":{"q":"在 Utah，一名未满 21 岁的司机第一次被发现开车时体内有任何酒精。驾驶权利会被取消多久？","o":["30 天","90 天","六个月","两年"],"h1":"是半年。","h2":"在 Utah，根据「一滴都不行」法（Not-a-Drop Act），未满 21 岁的司机第一次被发现体内有任何酒精，会失去驾驶权利六个月。","p":"对。在 Utah，第一次违反「一滴都不行」法，六个月不能开车。"},"vi":{"q":"Ở Utah, một người lái dưới 21 tuổi lần đầu bị phát hiện lái xe khi có bất kỳ chút cồn nào trong cơ thể. Quyền lái xe bị từ chối trong bao lâu?","o":["30 ngày","90 ngày","Sáu tháng","Hai năm"],"h1":"Đó là nửa năm.","h2":"Ở Utah, theo luật Không Một Giọt (Not-a-Drop Act), người lái dưới 21 tuổi có bất kỳ chút cồn nào trong cơ thể sẽ mất quyền lái xe sáu tháng cho lần vi phạm đầu tiên.","p":"Đúng. Ở Utah, vi phạm luật Không Một Giọt lần đầu nghĩa là sáu tháng không được lái xe."},"tl":{"q":"Sa Utah, nahuli sa unang beses ang driver na wala pang 21 na nagmamaneho na may kahit kaunting alak sa katawan. Gaano katagal ipagkakait ang karapatang magmaneho?","o":["30 araw","90 araw","Anim na buwan","Dalawang taon"],"h1":"Kalahating taon ito.","h2":"Sa Utah, sa ilalim ng Not-a-Drop Act, ang driver na wala pang 21 na may kahit kaunting alak sa katawan ay mawawalan ng karapatang magmaneho nang anim na buwan sa unang paglabag.","p":"Tama. Sa Utah, ang unang paglabag sa Not-a-Drop ay anim na buwang walang pagmamaneho."},"ar":{"q":"في Utah، ضُبط سائق عمره أقل من 21 سنة لأول مرة وهو يقود وفي جسمه أي كمية من الكحول. لكم من الوقت يُمنع من حق القيادة؟","o":["30 يومًا","90 يومًا","ستة أشهر","سنتان"],"h1":"هي نصف سنة.","h2":"في Utah، بموجب قانون «ولا قطرة» (Not-a-Drop Act)، يفقد السائق الأصغر من 21 سنة الذي في جسمه أي كمية من الكحول حق القيادة لمدة ستة أشهر في المخالفة الأولى.","p":"صحيح. في Utah، المخالفة الأولى لقانون «ولا قطرة» تعني ستة أشهر بلا قيادة."},"ref":{"doc":"UT","page":52}},{"id":"ut-036","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a driver 21 or older is convicted of a first DUI. For how long is the license suspended?","o":["30 days","90 days","120 days","One year"],"h1":"It is about four months.","h2":"In Utah, a driver 21 or older convicted of a first DUI has the license suspended for 120 days.","p":"Right. A first DUI in Utah for a driver 21 or older means a 120-day suspension."},"es":{"q":"En Utah, un conductor de 21 años o más es condenado por un primer DUI. ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","90 días","120 días","Un año"],"h1":"Son unos cuatro meses.","h2":"En Utah, a un conductor de 21 años o más condenado por un primer DUI se le suspende la licencia por 120 días.","p":"Correcto. Un primer DUI en Utah para un conductor de 21 años o más significa una suspensión de 120 días."},"zh":{"q":"在 Utah，一名 21 岁或以上的司机第一次被判酒后驾驶（DUI）。驾照会被暂停多久？","o":["30 天","90 天","120 天","一年"],"h1":"大约四个月。","h2":"在 Utah，21 岁或以上的司机第一次被判酒后驾驶（DUI），驾照会被暂停 120 天。","p":"对。在 Utah，21 岁或以上的司机第一次 DUI，驾照暂停 120 天。"},"vi":{"q":"Ở Utah, một người lái từ 21 tuổi trở lên bị kết án lái xe khi say (DUI) lần đầu. Bằng lái bị đình chỉ trong bao lâu?","o":["30 ngày","90 ngày","120 ngày","Một năm"],"h1":"Khoảng bốn tháng.","h2":"Ở Utah, người lái từ 21 tuổi trở lên bị kết án DUI lần đầu sẽ bị đình chỉ bằng lái 120 ngày.","p":"Đúng. Ở Utah, DUI lần đầu với người lái từ 21 tuổi trở lên nghĩa là bị đình chỉ 120 ngày."},"tl":{"q":"Sa Utah, nahatulan sa unang DUI ang driver na 21 pataas. Gaano katagal sususpindihin ang license?","o":["30 araw","90 araw","120 araw","Isang taon"],"h1":"Mga apat na buwan ito.","h2":"Sa Utah, ang driver na 21 pataas na nahatulan sa unang DUI ay masususpinde ang license nang 120 araw.","p":"Tama. Sa Utah, ang unang DUI ng driver na 21 pataas ay 120 araw na suspensyon."},"ar":{"q":"في Utah، أُدين سائق عمره 21 سنة أو أكثر بأول مخالفة قيادة تحت تأثير الكحول (DUI). لكم من الوقت تُعلَّق الرخصة؟","o":["30 يومًا","90 يومًا","120 يومًا","سنة واحدة"],"h1":"هي نحو أربعة أشهر.","h2":"في Utah، السائق الذي عمره 21 سنة أو أكثر ويُدان بأول DUI تُعلَّق رخصته لمدة 120 يومًا.","p":"صحيح. أول DUI في Utah لسائق عمره 21 سنة أو أكثر يعني تعليق الرخصة 120 يومًا."},"ref":{"doc":"UT","page":52}},{"id":"ut-037","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, a driver 21 or older refuses a chemical test after a DUI arrest. It is the first refusal. For how long is the license revoked?","o":["Six months","18 months","Three years","Five years"],"h1":"It is a year and a half.","h2":"In Utah, a driver 21 or older who refuses a chemical test for the first time has the license revoked for 18 months.","p":"Right. A first refusal in Utah means an 18-month revocation."},"es":{"q":"En Utah, un conductor de 21 años o más se niega a hacerse una prueba química después de ser arrestado por DUI. Es la primera vez. ¿Por cuánto tiempo se revoca su licencia?","o":["Seis meses","18 meses","Tres años","Cinco años"],"h1":"Es un año y medio.","h2":"En Utah, a un conductor de 21 años o más que se niega por primera vez a una prueba química se le revoca la licencia por 18 meses.","p":"Correcto. Una primera negativa en Utah significa una revocación de 18 meses."},"zh":{"q":"在 Utah，一名 21 岁或以上的司机因酒后驾驶（DUI）被捕后拒绝做化学检测。这是第一次拒绝。驾照会被吊销多久？","o":["六个月","18 个月","三年","五年"],"h1":"是一年半。","h2":"在 Utah，21 岁或以上的司机第一次拒绝做化学检测，驾照会被吊销 18 个月。","p":"对。在 Utah，第一次拒绝检测会被吊销驾照 18 个月。"},"vi":{"q":"Ở Utah, một người lái từ 21 tuổi trở lên từ chối xét nghiệm hóa học sau khi bị bắt vì DUI. Đây là lần từ chối đầu tiên. Bằng lái bị thu hồi trong bao lâu?","o":["Sáu tháng","18 tháng","Ba năm","Năm năm"],"h1":"Đó là một năm rưỡi.","h2":"Ở Utah, người lái từ 21 tuổi trở lên từ chối xét nghiệm hóa học lần đầu sẽ bị thu hồi bằng lái 18 tháng.","p":"Đúng. Ở Utah, từ chối lần đầu nghĩa là bị thu hồi bằng lái 18 tháng."},"tl":{"q":"Sa Utah, tumanggi sa chemical test ang driver na 21 pataas matapos maaresto dahil sa DUI. Ito ang unang pagtanggi. Gaano katagal babawiin ang license?","o":["Anim na buwan","18 buwan","Tatlong taon","Limang taon"],"h1":"Isang taon at kalahati ito.","h2":"Sa Utah, ang driver na 21 pataas na tumanggi sa chemical test sa unang beses ay babawian ng license nang 18 buwan.","p":"Tama. Sa Utah, ang unang pagtanggi ay 18 buwang pagbawi ng license."},"ar":{"q":"في Utah، رفض سائق عمره 21 سنة أو أكثر إجراء فحص كيميائي بعد القبض عليه بتهمة DUI. هذا أول رفض. لكم من الوقت تُلغى الرخصة؟","o":["ستة أشهر","18 شهرًا","ثلاث سنوات","خمس سنوات"],"h1":"هي سنة ونصف.","h2":"في Utah، السائق الذي عمره 21 سنة أو أكثر ويرفض الفحص الكيميائي لأول مرة تُلغى رخصته لمدة 18 شهرًا.","p":"صحيح. أول رفض في Utah يعني إلغاء الرخصة 18 شهرًا."},"ref":{"doc":"UT","page":53}},{"id":"ut-038","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a driver who was under 21 when arrested is convicted of a first DUI. For how long may they drive only a vehicle with an ignition interlock device?","o":["Six months","One year","18 months","Three years"],"h1":"It is twice as long as the rule for drivers 21 and older.","h2":"In Utah, a driver who was under 21 when arrested for a first DUI must drive only vehicles with an ignition interlock device for three years.","p":"Right. In Utah, a first DUI under 21 means three years with an ignition interlock."},"es":{"q":"En Utah, un conductor que tenía menos de 21 años cuando lo arrestaron es condenado por un primer DUI. ¿Por cuánto tiempo puede conducir solo un vehículo con dispositivo de bloqueo de encendido (ignition interlock)?","o":["Seis meses","Un año","18 meses","Tres años"],"h1":"Es el doble del tiempo que se aplica a los conductores de 21 años o más.","h2":"En Utah, un conductor que tenía menos de 21 años cuando lo arrestaron por un primer DUI debe conducir solo vehículos con dispositivo de bloqueo de encendido durante tres años.","p":"Correcto. En Utah, un primer DUI antes de los 21 años significa tres años con bloqueo de encendido."},"zh":{"q":"在 Utah，一名被捕时未满 21 岁的司机第一次被判酒后驾驶（DUI）。他们必须在多长时间内只驾驶装有点火联锁装置（ignition interlock device）的车？","o":["六个月","一年","18 个月","三年"],"h1":"它是 21 岁及以上司机规定时间的两倍。","h2":"在 Utah，被捕时未满 21 岁、第一次酒后驾驶（DUI）的司机，三年内只能驾驶装有点火联锁装置的车。","p":"对。在 Utah，未满 21 岁第一次 DUI，要用点火联锁装置三年。"},"vi":{"q":"Ở Utah, một người lái dưới 21 tuổi lúc bị bắt bị kết án DUI lần đầu. Trong bao lâu họ chỉ được lái xe có gắn thiết bị khóa khởi động (ignition interlock device)?","o":["Sáu tháng","Một năm","18 tháng","Ba năm"],"h1":"Thời gian này dài gấp đôi quy định cho người lái từ 21 tuổi trở lên.","h2":"Ở Utah, người lái dưới 21 tuổi lúc bị bắt vì DUI lần đầu chỉ được lái xe có thiết bị khóa khởi động trong ba năm.","p":"Đúng. Ở Utah, DUI lần đầu khi dưới 21 tuổi nghĩa là ba năm dùng thiết bị khóa khởi động."},"tl":{"q":"Sa Utah, nahatulan sa unang DUI ang driver na wala pang 21 noong inaresto. Gaano katagal sila puwedeng magmaneho lang ng sasakyang may ignition interlock device?","o":["Anim na buwan","Isang taon","18 buwan","Tatlong taon"],"h1":"Doble ito ng haba ng patakaran para sa mga driver na 21 pataas.","h2":"Sa Utah, ang driver na wala pang 21 noong inaresto para sa unang DUI ay dapat magmaneho lang ng sasakyang may ignition interlock device nang tatlong taon.","p":"Tama. Sa Utah, ang unang DUI ng wala pang 21 ay tatlong taon na may ignition interlock."},"ar":{"q":"في Utah، أُدين سائق كان عمره أقل من 21 سنة عند القبض عليه بأول DUI. لكم من الوقت لا يجوز له أن يقود إلا مركبة فيها جهاز قفل التشغيل (ignition interlock device)؟","o":["ستة أشهر","سنة واحدة","18 شهرًا","ثلاث سنوات"],"h1":"هي ضعف مدة القاعدة الخاصة بالسائقين الذين عمرهم 21 سنة أو أكثر.","h2":"في Utah، السائق الذي كان عمره أقل من 21 سنة عند القبض عليه بأول DUI يجب ألّا يقود إلا مركبات فيها جهاز قفل التشغيل لمدة ثلاث سنوات.","p":"صحيح. في Utah، أول DUI تحت 21 سنة يعني ثلاث سنوات مع جهاز قفل التشغيل."},"ref":{"doc":"UT","page":54}},{"id":"ut-039","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, a driver under 21 is called to a hearing after getting how many points within three years?","o":["50 points","70 points","100 points","200 points"],"h1":"Young drivers reach a hearing with far fewer points than adults, who need 200.","h2":"In Utah, a driver under 21 who gets 70 or more points within three years is asked to appear for a hearing.","p":"Right. In Utah, 70 points in three years brings a hearing for a driver under 21."},"es":{"q":"En Utah, ¿después de acumular cuántos puntos en tres años es llamado a una audiencia un conductor menor de 21 años?","o":["50 puntos","70 puntos","100 puntos","200 puntos"],"h1":"Los conductores jóvenes llegan a una audiencia con muchos menos puntos que los adultos, que necesitan 200.","h2":"En Utah, un conductor menor de 21 años que acumula 70 puntos o más en tres años es llamado a una audiencia.","p":"Correcto. En Utah, 70 puntos en tres años llevan a una audiencia para un conductor menor de 21 años."},"zh":{"q":"在 Utah，未满 21 岁的司机在三年内被记多少分，就会被叫去参加听证会？","o":["50 分","70 分","100 分","200 分"],"h1":"年轻司机被叫去听证会所需的分数比成年人少得多，成年人要 200 分。","h2":"在 Utah，未满 21 岁的司机在三年内被记 70 分或更多，就会被要求参加听证会。","p":"对。在 Utah，未满 21 岁的司机三年内被记 70 分，就要参加听证会。"},"vi":{"q":"Ở Utah, người lái dưới 21 tuổi bị gọi đến buổi điều trần sau khi bị bao nhiêu điểm trong vòng ba năm?","o":["50 điểm","70 điểm","100 điểm","200 điểm"],"h1":"Người lái trẻ bị gọi điều trần với số điểm ít hơn nhiều so với người lớn, vốn cần 200 điểm.","h2":"Ở Utah, người lái dưới 21 tuổi bị 70 điểm trở lên trong vòng ba năm sẽ bị yêu cầu đến buổi điều trần.","p":"Đúng. Ở Utah, 70 điểm trong ba năm sẽ dẫn đến buổi điều trần cho người lái dưới 21 tuổi."},"tl":{"q":"Sa Utah, ipinatatawag sa hearing ang driver na wala pang 21 matapos makakuha ng ilang puntos sa loob ng tatlong taon?","o":["50 puntos","70 puntos","100 puntos","200 puntos"],"h1":"Mas kaunti nang malaki ang puntos ng batang driver bago ipatawag sa hearing kaysa sa adult, na kailangan ng 200.","h2":"Sa Utah, ang driver na wala pang 21 na nakakuha ng 70 o higit pang puntos sa loob ng tatlong taon ay pinahaharap sa isang hearing.","p":"Tama. Sa Utah, ang 70 puntos sa tatlong taon ay nagdadala ng hearing para sa driver na wala pang 21."},"ar":{"q":"في Utah، يُستدعى السائق الأصغر من 21 سنة إلى جلسة استماع بعد أن يحصل على كم نقطة خلال ثلاث سنوات؟","o":["50 نقطة","70 نقطة","100 نقطة","200 نقطة"],"h1":"السائقون الصغار يصلون إلى جلسة الاستماع بنقاط أقل بكثير من البالغين، الذين يحتاجون إلى 200.","h2":"في Utah، السائق الأصغر من 21 سنة الذي يحصل على 70 نقطة أو أكثر خلال ثلاث سنوات يُطلب منه حضور جلسة استماع.","p":"صحيح. في Utah، 70 نقطة خلال ثلاث سنوات تؤدي إلى جلسة استماع للسائق الأصغر من 21 سنة."},"ref":{"doc":"UT","page":72}},{"id":"ut-040","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many points can a division-recommended defensive driving course remove from your record?","o":["50 points","25 points","75 points","All of your points"],"h1":"It is a round number, and you can use it only once every three years.","h2":"In Utah, finishing a defensive driving course recommended by the division can remove 50 points from your record, once in any three-year period.","p":"Right. A Utah defensive driving course can take off 50 points."},"es":{"q":"En Utah, ¿cuántos puntos puede quitar de su historial un curso de manejo defensivo recomendado por la división?","o":["50 puntos","25 puntos","75 puntos","Todos sus puntos"],"h1":"Es un número redondo, y solo se puede usar una vez cada tres años.","h2":"En Utah, terminar un curso de manejo defensivo recomendado por la división puede quitar 50 puntos de su historial, una vez en cualquier período de tres años.","p":"Correcto. Un curso de manejo defensivo en Utah puede quitar 50 puntos."},"zh":{"q":"在 Utah，一门由驾照部门推荐的防御性驾驶课程可以从你的记录中去掉多少分？","o":["50 分","25 分","75 分","你所有的分数"],"h1":"这是一个整数，而且每三年只能用一次。","h2":"在 Utah，完成驾照部门推荐的防御性驾驶课程，可以从你的记录中去掉 50 分，每三年只能用一次。","p":"对。Utah 的防御性驾驶课程可以去掉 50 分。"},"vi":{"q":"Ở Utah, một khóa học lái xe phòng vệ do Sở đề nghị có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["50 điểm","25 điểm","75 điểm","Tất cả điểm của bạn"],"h1":"Đó là một số tròn, và bạn chỉ được dùng một lần mỗi ba năm.","h2":"Ở Utah, hoàn thành một khóa học lái xe phòng vệ do Sở đề nghị có thể xóa 50 điểm khỏi hồ sơ của bạn, một lần trong mỗi khoảng ba năm.","p":"Đúng. Một khóa học lái xe phòng vệ ở Utah có thể xóa 50 điểm."},"tl":{"q":"Sa Utah, ilang puntos ang puwedeng alisin sa record mo ng defensive driving course na inirerekomenda ng division?","o":["50 puntos","25 puntos","75 puntos","Lahat ng puntos mo"],"h1":"Bilog na numero ito, at puwede mo lang itong gamitin minsan bawat tatlong taon.","h2":"Sa Utah, ang pagtatapos ng defensive driving course na inirerekomenda ng division ay puwedeng mag-alis ng 50 puntos sa record mo, minsan sa bawat tatlong taon.","p":"Tama. Puwedeng mag-alis ng 50 puntos ang defensive driving course sa Utah."},"ar":{"q":"في Utah، كم نقطة يمكن أن تزيلها من سجلك دورةُ القيادة الوقائية التي يوصي بها القسم؟","o":["50 نقطة","25 نقطة","75 نقطة","كل نقاطك"],"h1":"هو رقم مُدوَّر، ولا يمكنك استخدامه إلا مرة واحدة كل ثلاث سنوات.","h2":"في Utah، إتمام دورة القيادة الوقائية التي يوصي بها القسم يمكن أن يزيل 50 نقطة من سجلك، مرة واحدة في كل فترة ثلاث سنوات.","p":"صحيح. دورة القيادة الوقائية في Utah يمكن أن تزيل 50 نقطة."},"ref":{"doc":"UT","page":73}},{"id":"ut-041","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, what is the highest fine for a first texting-while-driving conviction when no one is hurt?","o":["$100","$50","$250","$500"],"h1":"It is a Class C misdemeanor, the lowest class of misdemeanor.","h2":"In Utah, a first texting-while-driving conviction with no injury is a Class C misdemeanor with a fine of up to $100.","p":"Right. In Utah, a first texting conviction can cost up to $100."},"es":{"q":"En Utah, ¿cuál es la multa más alta por una primera condena por enviar mensajes de texto mientras conduce, si nadie resulta herido?","o":["$100","$50","$250","$500"],"h1":"Es un delito menor Clase C, la clase más baja de delito menor.","h2":"En Utah, una primera condena por enviar mensajes de texto al conducir, sin heridos, es un delito menor Clase C con una multa de hasta $100.","p":"Correcto. En Utah, una primera condena por mensajes de texto puede costar hasta $100."},"zh":{"q":"在 Utah，第一次因开车时发短信被定罪、而且没有人受伤，最高罚款是多少？","o":["$100","$50","$250","$500"],"h1":"这是 C 级轻罪（Class C misdemeanor），是最低一级的轻罪。","h2":"在 Utah，第一次因开车时发短信被定罪、没有人受伤，属于 C 级轻罪，最高罚款 $100。","p":"对。在 Utah，第一次因发短信被定罪，最高罚款 $100。"},"vi":{"q":"Ở Utah, mức phạt cao nhất cho lần đầu bị kết án nhắn tin khi lái xe mà không ai bị thương là bao nhiêu?","o":["$100","$50","$250","$500"],"h1":"Đây là tội nhẹ Class C (Class C misdemeanor), loại tội nhẹ thấp nhất.","h2":"Ở Utah, lần đầu bị kết án nhắn tin khi lái xe mà không ai bị thương là tội nhẹ Class C với tiền phạt tối đa $100.","p":"Đúng. Ở Utah, lần đầu bị kết án nhắn tin có thể bị phạt tối đa $100."},"tl":{"q":"Sa Utah, ano ang pinakamataas na multa sa unang conviction sa pag-text habang nagmamaneho kapag walang nasaktan?","o":["$100","$50","$250","$500"],"h1":"Isa itong Class C misdemeanor, ang pinakamababang uri ng misdemeanor.","h2":"Sa Utah, ang unang conviction sa pag-text habang nagmamaneho na walang nasaktan ay Class C misdemeanor na may multang hanggang $100.","p":"Tama. Sa Utah, ang unang conviction sa pag-text ay puwedeng magmulta nang hanggang $100."},"ar":{"q":"في Utah، ما أعلى غرامة لأول إدانة بكتابة الرسائل أثناء القيادة إذا لم يُصب أحد؟","o":["$100","$50","$250","$500"],"h1":"هي جنحة من الفئة C (Class C misdemeanor)، وهي أدنى فئة من الجنح.","h2":"في Utah، أول إدانة بكتابة الرسائل أثناء القيادة دون إصابات هي جنحة من الفئة C وغرامتها تصل إلى $100.","p":"صحيح. في Utah، أول إدانة بكتابة الرسائل قد تكلّف حتى $100."},"ref":{"doc":"UT","page":59}},{"id":"ut-042","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, you must call the police right away after a crash with any injury or death, or with property damage of at least how much?","o":["$500","$1,000","$1,500","$2,500"],"h1":"It is the largest amount listed.","h2":"In Utah, you must call the police right away after a crash that causes injury, death, or at least $2,500 in total property damage.","p":"Right. In Utah, $2,500 or more in damage means you call the police right away."},"es":{"q":"En Utah, debe llamar a la policía de inmediato después de un choque con heridos o muertos. ¿A partir de qué cantidad de daños a la propiedad también debe llamarla?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Es la cantidad más alta de la lista.","h2":"En Utah, usted debe llamar a la policía de inmediato después de un choque que cause heridos, muertos o por lo menos $2,500 en daños a la propiedad en total.","p":"Correcto. En Utah, $2,500 o más en daños significa que usted llama a la policía de inmediato."},"zh":{"q":"在 Utah，发生有人受伤或死亡的车祸，或者财产损失至少达到多少时，你必须马上报警？","o":["$500","$1,000","$1,500","$2,500"],"h1":"是列出的最大金额。","h2":"在 Utah，车祸造成有人受伤、死亡，或财产损失总共至少 $2,500 时，你必须马上报警。","p":"对。在 Utah，损失达到 $2,500 或更多，就要马上报警。"},"vi":{"q":"Ở Utah, bạn phải gọi cảnh sát ngay sau một vụ tai nạn có người bị thương hoặc chết, hoặc có thiệt hại tài sản ít nhất là bao nhiêu?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Đó là số tiền lớn nhất trong danh sách.","h2":"Ở Utah, bạn phải gọi cảnh sát ngay sau một vụ tai nạn gây thương tích, tử vong, hoặc tổng thiệt hại tài sản ít nhất $2,500.","p":"Đúng. Ở Utah, thiệt hại từ $2,500 trở lên nghĩa là bạn gọi cảnh sát ngay."},"tl":{"q":"Sa Utah, dapat kang tumawag agad sa pulis pagkatapos ng banggaan na may nasaktan o namatay, o may pinsala sa ari-arian na hindi bababa sa magkano?","o":["$500","$1,000","$1,500","$2,500"],"h1":"Ito ang pinakamalaking halaga sa listahan.","h2":"Sa Utah, dapat kang tumawag agad sa pulis pagkatapos ng banggaan na nagdulot ng pinsala sa tao, kamatayan, o hindi bababa sa $2,500 na kabuuang pinsala sa ari-arian.","p":"Tama. Sa Utah, kapag $2,500 o higit pa ang pinsala, tumawag agad sa pulis."},"ar":{"q":"في Utah، يجب أن تتصل بالشرطة فورًا بعد حادث فيه إصابة أو وفاة، أو فيه أضرار في الممتلكات لا تقل عن كم؟","o":["$500","$1,000","$1,500","$2,500"],"h1":"هو أكبر مبلغ في القائمة.","h2":"في Utah يجب أن تتصل بالشرطة فورًا بعد حادث يسبّب إصابة أو وفاة أو أضرارًا في الممتلكات مجموعها $2,500 على الأقل.","p":"صحيح. في Utah، أضرار بقيمة $2,500 أو أكثر تعني أن تتصل بالشرطة فورًا."},"ref":{"doc":"UT","page":65}},{"id":"ut-043","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, during which dates may you use snow tires with metal studs?","o":["All year","November 1 to April 30","October 15 to March 31","December 1 to February 28"],"h1":"The season starts in the middle of October.","h2":"In Utah, snow tires with metal studs may be used from October 15 through March 31 each year.","p":"Right. In Utah, studded snow tires are allowed from October 15 to March 31."},"es":{"q":"En Utah, ¿en qué fechas puede usar llantas de nieve con clavos de metal?","o":["Todo el año","Del 1 de noviembre al 30 de abril","Del 15 de octubre al 31 de marzo","Del 1 de diciembre al 28 de febrero"],"h1":"La temporada empieza a mediados de octubre.","h2":"En Utah, las llantas de nieve con clavos de metal se pueden usar del 15 de octubre al 31 de marzo de cada año.","p":"Correcto. En Utah, las llantas con clavos se permiten del 15 de octubre al 31 de marzo."},"zh":{"q":"在 Utah，哪段日期可以使用带金属钉的雪地轮胎？","o":["全年","11 月 1 日到 4 月 30 日","10 月 15 日到 3 月 31 日","12 月 1 日到 2 月 28 日"],"h1":"这个季节从十月中开始。","h2":"在 Utah，每年 10 月 15 日到 3 月 31 日可以使用带金属钉的雪地轮胎。","p":"对。在 Utah，带钉雪地轮胎可以在 10 月 15 日到 3 月 31 日使用。"},"vi":{"q":"Ở Utah, bạn được dùng lốp đi tuyết có đinh kim loại trong khoảng ngày nào?","o":["Cả năm","Từ 1 tháng 11 đến 30 tháng 4","Từ 15 tháng 10 đến 31 tháng 3","Từ 1 tháng 12 đến 28 tháng 2"],"h1":"Mùa này bắt đầu vào giữa tháng Mười.","h2":"Ở Utah, lốp đi tuyết có đinh kim loại được dùng từ 15 tháng 10 đến 31 tháng 3 mỗi năm.","p":"Đúng. Ở Utah, lốp đi tuyết có đinh được phép dùng từ 15 tháng 10 đến 31 tháng 3."},"tl":{"q":"Sa Utah, sa anong mga petsa puwedeng gumamit ng snow tires na may metal na stud?","o":["Buong taon","Nobyembre 1 hanggang Abril 30","Oktubre 15 hanggang Marso 31","Disyembre 1 hanggang Pebrero 28"],"h1":"Nagsisimula ang panahong ito sa kalagitnaan ng Oktubre.","h2":"Sa Utah, puwedeng gamitin ang snow tires na may metal na stud mula Oktubre 15 hanggang Marso 31 bawat taon.","p":"Tama. Sa Utah, pinapayagan ang snow tires na may stud mula Oktubre 15 hanggang Marso 31."},"ar":{"q":"في Utah، في أي فترة يُسمح باستخدام إطارات الثلج ذات المسامير المعدنية؟","o":["طوال السنة","من 1 نوفمبر إلى 30 أبريل","من 15 أكتوبر إلى 31 مارس","من 1 ديسمبر إلى 28 فبراير"],"h1":"يبدأ الموسم في منتصف أكتوبر.","h2":"في Utah يُسمح باستخدام إطارات الثلج ذات المسامير المعدنية من 15 أكتوبر حتى 31 مارس كل سنة.","p":"صحيح. في Utah يُسمح بإطارات الثلج ذات المسامير من 15 أكتوبر إلى 31 مارس."},"ref":{"doc":"UT","page":63}},{"id":"ut-044","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, three or more snowplows with flashing yellow lights are working side by side in a group. How may you pass them?","o":["On the left side only","On the right side only","On the side with more room","You may not pass them on either side"],"h1":"With a single plow, you only stay off the side where the blade is out. A group is stricter.","h2":"In Utah, when three or more snowplows work side by side in a group, you may not pass them on either side.","p":"Right. In Utah, you never pass a group of three or more snowplows working side by side."},"es":{"q":"En Utah, tres o más quitanieves con luces amarillas intermitentes trabajan uno al lado del otro en grupo. ¿Cómo puede rebasarlos?","o":["Solo por la izquierda","Solo por la derecha","Por el lado con más espacio","No puede rebasarlos por ningún lado"],"h1":"Con un solo quitanieves, solo evita el lado donde está la cuchilla. Con un grupo la regla es más estricta.","h2":"En Utah, cuando tres o más quitanieves trabajan uno al lado del otro en grupo, usted no puede rebasarlos por ningún lado.","p":"Correcto. En Utah, nunca rebase un grupo de tres o más quitanieves que trabajan uno al lado del otro."},"zh":{"q":"在 Utah，三辆或更多亮着黄色闪灯的扫雪车并排成一组在工作。你可以怎样超过它们？","o":["只能从左边超","只能从右边超","从空间较大的一边超","两边都不可以超"],"h1":"如果只有一辆扫雪车，你只要避开铲子伸出的那一边。成组的扫雪车规定更严。","h2":"在 Utah，当三辆或更多扫雪车并排成一组工作时，你两边都不可以超过它们。","p":"对。在 Utah，你绝对不能超过三辆或更多并排工作的扫雪车。"},"vi":{"q":"Ở Utah, ba xe ủi tuyết trở lên có đèn vàng nhấp nháy đang làm việc cạnh nhau thành một nhóm. Bạn được vượt chúng như thế nào?","o":["Chỉ bên trái","Chỉ bên phải","Bên nào rộng hơn","Bạn không được vượt chúng ở bên nào cả"],"h1":"Với một xe ủi tuyết, bạn chỉ cần tránh bên có lưỡi ủi chìa ra. Một nhóm xe thì nghiêm ngặt hơn.","h2":"Ở Utah, khi ba xe ủi tuyết trở lên làm việc cạnh nhau thành một nhóm, bạn không được vượt chúng ở bên nào cả.","p":"Đúng. Ở Utah, bạn không bao giờ vượt một nhóm ba xe ủi tuyết trở lên đang làm việc cạnh nhau."},"tl":{"q":"Sa Utah, tatlo o higit pang snowplow na may kumikislap na dilaw na ilaw ang magkakatabing nagtatrabaho bilang isang grupo. Paano mo sila puwedeng lampasan?","o":["Sa kaliwa lang","Sa kanan lang","Sa gilid na mas maluwag","Hindi mo sila puwedeng lampasan sa alinmang gilid"],"h1":"Kapag isang snowplow lang, iiwasan mo lang ang gilid kung saan nakalabas ang blade. Mas mahigpit kapag grupo.","h2":"Sa Utah, kapag tatlo o higit pang snowplow ang magkakatabing nagtatrabaho bilang grupo, hindi mo sila puwedeng lampasan sa alinmang gilid.","p":"Tama. Sa Utah, hindi mo kailanman nilalampasan ang grupo ng tatlo o higit pang snowplow na magkakatabing nagtatrabaho."},"ar":{"q":"في Utah، ثلاث كاسحات ثلج أو أكثر بأضواء صفراء وامضة تعمل جنبًا إلى جنب في مجموعة. كيف يجوز لك تجاوزها؟","o":["من الجهة اليسرى فقط","من الجهة اليمنى فقط","من الجهة التي فيها مساحة أكبر","لا يجوز لك تجاوزها من أي جهة"],"h1":"مع كاسحة واحدة، تبتعد فقط عن الجهة التي تبرز منها الشفرة. أما المجموعة فالقاعدة فيها أشدّ.","h2":"في Utah، عندما تعمل ثلاث كاسحات ثلج أو أكثر جنبًا إلى جنب في مجموعة، لا يجوز لك تجاوزها من أي جهة.","p":"صحيح. في Utah لا تتجاوز أبدًا مجموعة من ثلاث كاسحات ثلج أو أكثر تعمل جنبًا إلى جنب."},"ref":{"doc":"UT","page":34}},{"id":"ut-045","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, if no other limit is posted, what is the speed limit near a school while children are going to or leaving school?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"It is 5 mph less than the limit in a residential area.","h2":"In Utah, unless another limit is posted, the speed limit near a school is 20 mph while children are going to or leaving school.","p":"Right. In Utah, the school speed limit is 20 mph."},"es":{"q":"En Utah, si no hay otro límite indicado, ¿cuál es el límite de velocidad cerca de una escuela mientras los niños llegan o salen?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Es 5 mph menos que el límite en una zona residencial.","h2":"En Utah, si no hay otro límite indicado, el límite de velocidad cerca de una escuela es de 20 mph mientras los niños llegan o salen.","p":"Correcto. En Utah, el límite de velocidad escolar es de 20 mph."},"zh":{"q":"在 Utah，如果没有标出别的限速，在孩子上学或放学的时间，学校附近的限速是多少？","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"它比住宅区的限速少 5 mph。","h2":"在 Utah，除非标出别的限速，在孩子上学或放学的时间，学校附近的限速是 20 mph。","p":"对。在 Utah，学校区的限速是 20 mph。"},"vi":{"q":"Ở Utah, nếu không có biển báo giới hạn khác, giới hạn tốc độ gần trường học khi trẻ em đang đi học hoặc tan học là bao nhiêu?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Nó thấp hơn 5 mph so với giới hạn trong khu dân cư.","h2":"Ở Utah, trừ khi có biển báo giới hạn khác, giới hạn tốc độ gần trường học là 20 mph khi trẻ em đang đi học hoặc tan học.","p":"Đúng. Ở Utah, giới hạn tốc độ ở trường học là 20 mph."},"tl":{"q":"Sa Utah, kung walang ibang nakapaskil na limitasyon, ano ang speed limit malapit sa paaralan habang papasok o pauwi ang mga bata?","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"Mas mababa ito nang 5 mph kaysa sa limitasyon sa residential area.","h2":"Sa Utah, maliban kung may ibang nakapaskil na limitasyon, ang speed limit malapit sa paaralan ay 20 mph habang papasok o pauwi ang mga bata.","p":"Tama. Sa Utah, ang speed limit sa paaralan ay 20 mph."},"ar":{"q":"في Utah، إذا لم يكن هناك حدّ آخر مكتوب، ما حدّ السرعة قرب المدرسة أثناء ذهاب الأطفال إلى المدرسة أو خروجهم منها؟","o":["15 mph","20 mph","25 mph","30 mph"],"h1":"هو أقل بـ 5 mph من الحدّ في المنطقة السكنية.","h2":"في Utah، ما لم يكن هناك حدّ آخر مكتوب، حدّ السرعة قرب المدرسة هو 20 mph أثناء ذهاب الأطفال إلى المدرسة أو خروجهم منها.","p":"صحيح. في Utah حدّ السرعة عند المدارس هو 20 mph."},"ref":{"doc":"UT","page":44}},{"id":"ut-046","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, you plan to turn left from a shared center left-turn lane. How far before the turn may you enter that lane?","o":["No more than 100 feet","No more than 200 feet","No more than 500 feet","No more than 1,000 feet"],"h1":"It is more than 200 feet but much less than 1,000 feet.","h2":"In Utah, you may not enter a shared center left-turn lane more than 500 feet before your turn.","p":"Right. In Utah, you enter the shared center turn lane no more than 500 feet before turning."},"es":{"q":"En Utah, usted piensa girar a la izquierda desde un carril central compartido para girar a la izquierda. ¿A qué distancia antes del giro puede entrar a ese carril?","o":["A no más de 100 pies","A no más de 200 pies","A no más de 500 pies","A no más de 1,000 pies"],"h1":"Son más de 200 pies, pero mucho menos de 1,000 pies.","h2":"En Utah, usted no puede entrar a un carril central compartido para girar a la izquierda más de 500 pies antes de su giro.","p":"Correcto. En Utah, usted entra al carril central compartido a no más de 500 pies antes de girar."},"zh":{"q":"在 Utah，你打算从中间共用左转车道左转。在转弯前多远可以进入这条车道？","o":["不超过 100 英尺","不超过 200 英尺","不超过 500 英尺","不超过 1,000 英尺"],"h1":"比 200 英尺多，但比 1,000 英尺少很多。","h2":"在 Utah，你不可以在转弯前超过 500 英尺就进入中间共用左转车道。","p":"对。在 Utah，你在转弯前不超过 500 英尺才进入中间共用转弯车道。"},"vi":{"q":"Ở Utah, bạn định rẽ trái từ làn rẽ trái dùng chung ở giữa đường. Bạn được vào làn đó trước chỗ rẽ bao xa?","o":["Không quá 100 feet","Không quá 200 feet","Không quá 500 feet","Không quá 1,000 feet"],"h1":"Xa hơn 200 feet nhưng ngắn hơn nhiều so với 1,000 feet.","h2":"Ở Utah, bạn không được vào làn rẽ trái dùng chung ở giữa đường sớm hơn 500 feet trước chỗ rẽ.","p":"Đúng. Ở Utah, bạn vào làn rẽ dùng chung ở giữa không quá 500 feet trước khi rẽ."},"tl":{"q":"Sa Utah, balak mong kumaliwa mula sa shared center left-turn lane. Gaano kalayo bago ang liko puwede kang pumasok sa lane na iyon?","o":["Hindi hihigit sa 100 talampakan","Hindi hihigit sa 200 talampakan","Hindi hihigit sa 500 talampakan","Hindi hihigit sa 1,000 talampakan"],"h1":"Higit ito sa 200 talampakan pero mas maikli nang malaki sa 1,000 talampakan.","h2":"Sa Utah, hindi ka puwedeng pumasok sa shared center left-turn lane nang higit sa 500 talampakan bago ang liko mo.","p":"Tama. Sa Utah, pumapasok ka sa shared center turn lane nang hindi hihigit sa 500 talampakan bago lumiko."},"ar":{"q":"في Utah، تنوي الانعطاف يسارًا من مسار الانعطاف يسارًا المشترك في الوسط. على أي بُعد قبل الانعطاف يجوز لك دخول هذا المسار؟","o":["ليس أكثر من 100 قدم","ليس أكثر من 200 قدم","ليس أكثر من 500 قدم","ليس أكثر من 1,000 قدم"],"h1":"هو أكثر من 200 قدم لكنه أقل بكثير من 1,000 قدم.","h2":"في Utah لا يجوز لك دخول مسار الانعطاف يسارًا المشترك في الوسط قبل أكثر من 500 قدم من مكان انعطافك.","p":"صحيح. في Utah تدخل مسار الانعطاف المشترك في الوسط قبل الانعطاف بما لا يزيد على 500 قدم."},"ref":{"doc":"UT","page":44}},{"id":"ut-047","scope":"UT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Utah, a fire truck is answering an alarm. Unless you are on official business, how close may you follow it?","o":["No closer than 100 feet","No closer than 200 feet","No closer than 300 feet","No closer than 500 feet"],"h1":"It is the longest distance listed.","h2":"In Utah, unless you are on official business, you may not follow a fire truck answering an alarm within 500 feet.","p":"Right. In Utah, stay at least 500 feet behind a fire truck answering an alarm."},"es":{"q":"En Utah, un camión de bomberos responde a una alarma. A menos que usted esté en asuntos oficiales, ¿qué tan cerca puede seguirlo?","o":["A no menos de 100 pies","A no menos de 200 pies","A no menos de 300 pies","A no menos de 500 pies"],"h1":"Es la distancia más larga de la lista.","h2":"En Utah, a menos que esté en asuntos oficiales, usted no puede seguir a menos de 500 pies a un camión de bomberos que responde a una alarma.","p":"Correcto. En Utah, manténgase por lo menos a 500 pies detrás de un camión de bomberos que responde a una alarma."},"zh":{"q":"在 Utah，一辆消防车正在出警。除非你在执行公务，你可以跟它跟多近？","o":["不能近于 100 英尺","不能近于 200 英尺","不能近于 300 英尺","不能近于 500 英尺"],"h1":"是列出的最长距离。","h2":"在 Utah，除非你在执行公务，你不可以在出警消防车后面 500 英尺以内跟车。","p":"对。在 Utah，要在出警的消防车后面保持至少 500 英尺。"},"vi":{"q":"Ở Utah, một xe cứu hỏa đang đi chữa cháy. Trừ khi bạn đang làm việc công vụ, bạn được đi theo sau nó gần đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 200 feet","Không gần hơn 300 feet","Không gần hơn 500 feet"],"h1":"Đó là khoảng cách dài nhất trong danh sách.","h2":"Ở Utah, trừ khi bạn đang làm việc công vụ, bạn không được đi theo sau xe cứu hỏa đang đi chữa cháy trong vòng 500 feet.","p":"Đúng. Ở Utah, hãy ở cách ít nhất 500 feet phía sau xe cứu hỏa đang đi chữa cháy."},"tl":{"q":"Sa Utah, rumeresponde sa alarma ang isang fire truck. Maliban kung nasa opisyal na tungkulin ka, gaano kalapit mo ito puwedeng sundan?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 200 talampakan","Hindi lalapit sa 300 talampakan","Hindi lalapit sa 500 talampakan"],"h1":"Ito ang pinakamahabang distansiya sa listahan.","h2":"Sa Utah, maliban kung nasa opisyal na tungkulin ka, hindi mo puwedeng sundan sa loob ng 500 talampakan ang fire truck na rumeresponde sa alarma.","p":"Tama. Sa Utah, manatili nang hindi bababa sa 500 talampakan sa likod ng fire truck na rumeresponde sa alarma."},"ar":{"q":"في Utah، شاحنة إطفاء تستجيب لنداء طوارئ. ما لم تكن في مهمة رسمية، إلى أي مسافة يجوز لك أن تقترب منها وأنت تسير خلفها؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 200 قدم","ليس أقرب من 300 قدم","ليس أقرب من 500 قدم"],"h1":"هي أطول مسافة في القائمة.","h2":"في Utah، ما لم تكن في مهمة رسمية، لا يجوز لك أن تسير خلف شاحنة إطفاء تستجيب لنداء طوارئ على مسافة أقل من 500 قدم.","p":"صحيح. في Utah ابقَ على بُعد 500 قدم على الأقل خلف شاحنة الإطفاء التي تستجيب لنداء طوارئ."},"ref":{"doc":"UT","page":77}},{"id":"ut-048","scope":"UT","cat":"signals","sign":null,"c":2,"en":{"q":"In Utah, a motorcycle rider 16 or older has fully stopped at a traffic light that does not detect the motorcycle. No one else is coming. How long must the rider wait before going through?","o":["At least 30 seconds","At least 60 seconds","At least 90 seconds","At least 3 minutes"],"h1":"It is a minute and a half.","h2":"In Utah, a rider 16 or older on a motorcycle, moped or bicycle may go through after a full stop and a wait of at least 90 seconds if the light does not detect them and no one is coming.","p":"Right. In Utah, the rider waits at least 90 seconds, then goes only if the way is clear."},"es":{"q":"En Utah, un motociclista de 16 años o más se detuvo por completo en un semáforo que no detecta la motocicleta. No viene nadie más. ¿Cuánto tiempo debe esperar antes de cruzar?","o":["Por lo menos 30 segundos","Por lo menos 60 segundos","Por lo menos 90 segundos","Por lo menos 3 minutos"],"h1":"Es un minuto y medio.","h2":"En Utah, quien maneja una motocicleta, un ciclomotor o una bicicleta y tiene 16 años o más puede cruzar después de detenerse por completo y esperar por lo menos 90 segundos si el semáforo no lo detecta y no viene nadie.","p":"Correcto. En Utah, se espera por lo menos 90 segundos y se cruza solo si el camino está libre."},"zh":{"q":"在 Utah，一名 16 岁或以上的摩托车骑手在一个检测不到摩托车的红绿灯前已经完全停下。没有其他车或人过来。骑手必须等多久才可以通过？","o":["至少 30 秒","至少 60 秒","至少 90 秒","至少 3 分钟"],"h1":"是一分半钟。","h2":"在 Utah，16 岁或以上骑摩托车、轻便摩托车（moped）或自行车的人，如果灯检测不到他们而且没有人过来，可以在完全停下并等至少 90 秒后通过。","p":"对。在 Utah，骑手至少等 90 秒，然后只在路上安全时才通过。"},"vi":{"q":"Ở Utah, một người đi xe máy từ 16 tuổi trở lên đã dừng hẳn ở đèn giao thông không nhận ra xe máy. Không có ai khác đang tới. Người đó phải chờ bao lâu trước khi đi qua?","o":["Ít nhất 30 giây","Ít nhất 60 giây","Ít nhất 90 giây","Ít nhất 3 phút"],"h1":"Đó là một phút rưỡi.","h2":"Ở Utah, người từ 16 tuổi trở lên đi xe máy, xe gắn máy (moped) hoặc xe đạp có thể đi qua sau khi dừng hẳn và chờ ít nhất 90 giây nếu đèn không nhận ra họ và không có ai đang tới.","p":"Đúng. Ở Utah, người lái chờ ít nhất 90 giây, rồi chỉ đi khi đường thông thoáng."},"tl":{"q":"Sa Utah, ganap nang huminto ang motorcycle rider na 16 pataas sa traffic light na hindi nakakadetekta sa motorsiklo. Walang ibang paparating. Gaano katagal dapat maghintay ang rider bago tumawid?","o":["Hindi bababa sa 30 segundo","Hindi bababa sa 60 segundo","Hindi bababa sa 90 segundo","Hindi bababa sa 3 minuto"],"h1":"Isang minuto at kalahati ito.","h2":"Sa Utah, ang rider na 16 pataas sa motorsiklo, moped o bisikleta ay puwedeng tumawid matapos ganap na huminto at maghintay nang hindi bababa sa 90 segundo kung hindi sila nadedetekta ng ilaw at walang paparating.","p":"Tama. Sa Utah, naghihintay ang rider nang hindi bababa sa 90 segundo, at tatawid lang kapag malinaw ang daan."},"ar":{"q":"في Utah، سائق دراجة نارية عمره 16 سنة أو أكثر توقف تمامًا عند إشارة مرور لا تكتشف الدراجة النارية. لا أحد قادم. كم يجب أن ينتظر قبل أن يعبر؟","o":["30 ثانية على الأقل","60 ثانية على الأقل","90 ثانية على الأقل","3 دقائق على الأقل"],"h1":"هي دقيقة ونصف.","h2":"في Utah، من عمره 16 سنة أو أكثر ويقود دراجة نارية أو دراجة صغيرة بمحرك (moped) أو دراجة هوائية يجوز له العبور بعد توقف تام وانتظار 90 ثانية على الأقل، إذا كانت الإشارة لا تكتشفه ولا أحد قادم.","p":"صحيح. في Utah ينتظر السائق 90 ثانية على الأقل، ثم يعبر فقط إذا كان الطريق خاليًا."},"ref":{"doc":"UT","page":82}},{"id":"ut-049","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, how close to a stop sign may you park?","o":["No closer than 30 feet","No closer than 10 feet","No closer than 15 feet","No closer than 20 feet"],"h1":"It is twice the distance you must keep from a fire hydrant.","h2":"In Utah, you may not park within 30 feet of a stop sign, yield sign, flashing beacon or traffic signal.","p":"Right. In Utah, park at least 30 feet from a stop sign."},"es":{"q":"En Utah, ¿qué tan cerca de una señal de alto puede estacionarse?","o":["A no menos de 30 pies","A no menos de 10 pies","A no menos de 15 pies","A no menos de 20 pies"],"h1":"Es el doble de la distancia que debe dejar de un hidrante.","h2":"En Utah, usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso, una luz intermitente o un semáforo.","p":"Correcto. En Utah, estaciónese por lo menos a 30 pies de una señal de alto."},"zh":{"q":"在 Utah，你可以把车停在离停车标志（stop sign）多近的地方？","o":["不能近于 30 英尺","不能近于 10 英尺","不能近于 15 英尺","不能近于 20 英尺"],"h1":"是你必须和消防栓保持的距离的两倍。","h2":"在 Utah，你不可以把车停在停车标志、让行标志、闪光信号灯或交通信号灯 30 英尺以内。","p":"对。在 Utah，停车要离停车标志至少 30 英尺。"},"vi":{"q":"Ở Utah, bạn được đậu xe gần biển báo dừng (stop sign) đến mức nào?","o":["Không gần hơn 30 feet","Không gần hơn 10 feet","Không gần hơn 15 feet","Không gần hơn 20 feet"],"h1":"Đó là gấp đôi khoảng cách bạn phải giữ với trụ nước cứu hỏa.","h2":"Ở Utah, bạn không được đậu xe trong vòng 30 feet của biển báo dừng, biển báo nhường đường, đèn nhấp nháy hoặc đèn giao thông.","p":"Đúng. Ở Utah, hãy đậu xe cách biển báo dừng ít nhất 30 feet."},"tl":{"q":"Sa Utah, gaano kalapit sa stop sign ka puwedeng pumarada?","o":["Hindi lalapit sa 30 talampakan","Hindi lalapit sa 10 talampakan","Hindi lalapit sa 15 talampakan","Hindi lalapit sa 20 talampakan"],"h1":"Doble ito ng layo na dapat mong panatilihin mula sa fire hydrant.","h2":"Sa Utah, hindi ka puwedeng pumarada sa loob ng 30 talampakan mula sa stop sign, yield sign, kumikislap na beacon o traffic signal.","p":"Tama. Sa Utah, pumarada nang hindi bababa sa 30 talampakan mula sa stop sign."},"ar":{"q":"في Utah، إلى أي مسافة يجوز لك أن تركن سيارتك قرب إشارة التوقف (stop sign)؟","o":["ليس أقرب من 30 قدمًا","ليس أقرب من 10 أقدام","ليس أقرب من 15 قدمًا","ليس أقرب من 20 قدمًا"],"h1":"هي ضعف المسافة التي يجب أن تتركها عن صنبور إطفاء الحريق.","h2":"في Utah لا يجوز لك أن تركن على مسافة أقل من 30 قدمًا من إشارة التوقف أو إشارة إفساح الطريق أو الضوء الوامض أو إشارة المرور.","p":"صحيح. في Utah اركن على بُعد 30 قدمًا على الأقل من إشارة التوقف."},"ref":{"doc":"UT","page":32}},{"id":"ut-050","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, who must wear an approved DOT helmet on a motorcycle?","o":["Riders and passengers under 21","Every rider and passenger","Only riders under 18","Only passengers"],"h1":"The rule depends on age, and the age is the same as the legal drinking age.","h2":"In Utah, any motorcycle rider or passenger under 21 must wear an approved DOT helmet.","p":"Right. In Utah, motorcycle riders and passengers under 21 must wear a helmet."},"es":{"q":"En Utah, ¿quién debe usar un casco aprobado por el DOT en una motocicleta?","o":["Conductores y pasajeros menores de 21 años","Todos los conductores y pasajeros","Solo los conductores menores de 18 años","Solo los pasajeros"],"h1":"La regla depende de la edad, y es la misma edad legal para beber alcohol.","h2":"En Utah, todo conductor o pasajero de motocicleta menor de 21 años debe usar un casco aprobado por el DOT.","p":"Correcto. En Utah, los conductores y pasajeros de motocicleta menores de 21 años deben usar casco."},"zh":{"q":"在 Utah，谁骑摩托车时必须戴经过认可的 DOT 头盔？","o":["未满 21 岁的骑手和乘客","每一位骑手和乘客","只有未满 18 岁的骑手","只有乘客"],"h1":"规定取决于年龄，这个年龄和合法饮酒年龄一样。","h2":"在 Utah，未满 21 岁的摩托车骑手或乘客都必须戴经过认可的 DOT 头盔。","p":"对。在 Utah，未满 21 岁的摩托车骑手和乘客必须戴头盔。"},"vi":{"q":"Ở Utah, ai phải đội mũ bảo hiểm DOT được chấp thuận khi đi xe máy?","o":["Người lái và người ngồi sau dưới 21 tuổi","Mọi người lái và người ngồi sau","Chỉ người lái dưới 18 tuổi","Chỉ người ngồi sau"],"h1":"Quy định tùy theo tuổi, và tuổi này giống tuổi được phép uống rượu hợp pháp.","h2":"Ở Utah, mọi người lái hoặc người ngồi sau xe máy dưới 21 tuổi phải đội mũ bảo hiểm DOT được chấp thuận.","p":"Đúng. Ở Utah, người lái và người ngồi sau xe máy dưới 21 tuổi phải đội mũ bảo hiểm."},"tl":{"q":"Sa Utah, sino ang dapat magsuot ng aprobadong DOT helmet sa motorsiklo?","o":["Mga rider at pasaherong wala pang 21","Bawat rider at pasahero","Mga rider lang na wala pang 18","Mga pasahero lang"],"h1":"Nakadepende sa edad ang patakaran, at kapareho ito ng legal na edad sa pag-inom ng alak.","h2":"Sa Utah, ang sinumang rider o pasahero ng motorsiklo na wala pang 21 ay dapat magsuot ng aprobadong DOT helmet.","p":"Tama. Sa Utah, ang mga rider at pasahero ng motorsiklo na wala pang 21 ay dapat magsuot ng helmet."},"ar":{"q":"في Utah، من يجب أن يلبس خوذة معتمدة من DOT على الدراجة النارية؟","o":["السائقون والركاب الأصغر من 21 سنة","كل سائق وكل راكب","السائقون الأصغر من 18 سنة فقط","الركاب فقط"],"h1":"القاعدة تعتمد على العمر، وهذا العمر هو نفسه السن القانونية لشرب الكحول.","h2":"في Utah يجب على أي سائق دراجة نارية أو راكب معه عمره أقل من 21 سنة أن يلبس خوذة معتمدة من DOT.","p":"صحيح. في Utah يجب على سائقي الدراجات النارية وركابها الأصغر من 21 سنة لبس الخوذة."},"ref":{"doc":"UT","page":81}},{"id":"ut-051","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, a visitor has a valid license from another state. For how long may the visitor drive in Utah with that license?","o":["30 days","90 days","Up to six months","Up to two years"],"h1":"It is half of a year.","h2":"In Utah, a visitor with a valid out-of-state or out-of-country license may drive for up to six months.","p":"Right. Visitors may drive in Utah for up to six months."},"es":{"q":"En Utah, un visitante tiene una licencia válida de otro estado. ¿Por cuánto tiempo puede manejar en Utah con esa licencia?","o":["30 días","90 días","Hasta seis meses","Hasta dos años"],"h1":"Es la mitad de un año.","h2":"En Utah, un visitante con una licencia válida de otro estado o país puede manejar hasta seis meses.","p":"Correcto. Los visitantes pueden manejar en Utah hasta seis meses."},"ref":{"doc":"UT","page":4}},{"id":"ut-052","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how old must a non-resident with a license from another state be to drive in Utah?","o":["At least 16","At least 15","At least 18","At least 21"],"h1":"It is the same as the youngest age for a regular Utah license.","h2":"In Utah, a non-resident licensed in another state or country may drive if they are at least 16 years old.","p":"Right. A licensed non-resident must be at least 16 to drive in Utah."},"es":{"q":"En Utah, ¿qué edad debe tener una persona no residente con licencia de otro estado para manejar en Utah?","o":["Por lo menos 16 años","Por lo menos 15 años","Por lo menos 18 años","Por lo menos 21 años"],"h1":"Es la misma edad mínima de una licencia regular de Utah.","h2":"En Utah, una persona no residente con licencia de otro estado o país puede manejar si tiene por lo menos 16 años.","p":"Correcto. Un no residente con licencia debe tener por lo menos 16 años para manejar en Utah."},"ref":{"doc":"UT","page":4}},{"id":"ut-053","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, how many REAL ID-compliant cards (license or ID) may one person hold at the same time?","o":["Two, one license and one ID","Three","As many as they want","Only one"],"h1":"Even a card from another state counts.","h2":"In Utah, the law says you may hold only one REAL ID-compliant card at a time, even counting cards from other states.","p":"Right. You may hold only one REAL ID-compliant card at a time."},"es":{"q":"En Utah, ¿cuántas tarjetas que cumplen con REAL ID (licencia o identificación) puede tener una persona al mismo tiempo?","o":["Dos, una licencia y una identificación","Tres","Todas las que quiera","Solo una"],"h1":"Incluso una tarjeta de otro estado cuenta.","h2":"En Utah, la ley dice que usted puede tener solo una tarjeta que cumpla con REAL ID a la vez, contando tarjetas de otros estados.","p":"Correcto. Solo puede tener una tarjeta REAL ID a la vez."},"ref":{"doc":"UT","page":4}},{"id":"ut-054","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, you have a driver license. May you also hold a Utah identification card?","o":["Yes, if you pay both fees","Yes, but only after age 65","No, the law does not allow both at the same time","Yes, if the ID is a REAL ID"],"h1":"Utah lets you carry one or the other.","h2":"In Utah, the law does not allow a person to have a driver license and an identification card at the same time.","p":"Right. You cannot hold a Utah license and a Utah ID card at the same time."},"es":{"q":"En Utah, usted tiene licencia de manejar. ¿Puede tener también una tarjeta de identificación de Utah?","o":["Sí, si paga las dos tarifas","Sí, pero solo después de los 65 años","No, la ley no permite tener las dos al mismo tiempo","Sí, si la identificación es REAL ID"],"h1":"Utah le permite tener una o la otra.","h2":"En Utah, la ley no permite que una persona tenga licencia de manejar y tarjeta de identificación al mismo tiempo.","p":"Correcto. No puede tener licencia y tarjeta de identificación de Utah al mismo tiempo."},"ref":{"doc":"UT","page":19}},{"id":"ut-055","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, how many hours of classroom instruction does a high school driver education course include?","o":["18 hours","27 hours","30 hours","40 hours"],"h1":"A private school needs fewer hours, and online study needs more.","h2":"In Utah, high school driver education includes 27 hours of classroom instruction.","p":"Right. High school driver education has 27 classroom hours."},"es":{"q":"En Utah, ¿cuántas horas de clase en el salón incluye un curso de educación vial en la escuela secundaria?","o":["18 horas","27 horas","30 horas","40 horas"],"h1":"Una escuela privada pide menos horas, y el estudio en línea pide más.","h2":"En Utah, la educación vial de la escuela secundaria incluye 27 horas de clase en el salón.","p":"Correcto. La educación vial de la secundaria tiene 27 horas de clase."},"ref":{"doc":"UT","page":6}},{"id":"ut-056","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many hours of behind-the-wheel instruction are part of driver education?","o":["6 hours","2 hours","10 hours","20 hours"],"h1":"It is the same number as the hours of observation.","h2":"In Utah, driver education includes 6 hours of behind-the-wheel instruction.","p":"Right. Driver education includes 6 hours behind the wheel."},"es":{"q":"En Utah, ¿cuántas horas de práctica al volante con un instructor forman parte de la educación vial?","o":["6 horas","2 horas","10 horas","20 horas"],"h1":"Es el mismo número que las horas de observación.","h2":"En Utah, la educación vial incluye 6 horas de práctica al volante con un instructor.","p":"Correcto. La educación vial incluye 6 horas al volante."},"ref":{"doc":"UT","page":6}},{"id":"ut-057","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, you took an online driver education course in another state. Will Utah accept the certificate?","o":["Yes, any certificate is accepted","Yes, if you are over 18","Yes, if you also pass a road test","No, out-of-state online or home study certificates are not accepted"],"h1":"Utah treats online courses from other states differently from classroom courses.","h2":"In Utah, driver education certificates from out-of-state online or home study courses are not accepted.","p":"Right. Utah does not accept out-of-state online or home study certificates."},"es":{"q":"En Utah, usted tomó un curso de educación vial en línea en otro estado. ¿Acepta Utah ese certificado?","o":["Sí, se acepta cualquier certificado","Sí, si tiene más de 18 años","Sí, si también pasa el examen de manejo","No, no se aceptan certificados en línea o de estudio en casa de otro estado"],"h1":"Utah trata los cursos en línea de otros estados de forma distinta a los cursos en salón.","h2":"En Utah, no se aceptan certificados de educación vial de cursos en línea o de estudio en casa de otro estado.","p":"Correcto. Utah no acepta certificados en línea o de estudio en casa de otro estado."},"ref":{"doc":"UT","page":6}},{"id":"ut-058","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, you are 20 and have never had a license. How can you skip the 90-day learner permit wait?","o":["Pay an extra fee","Pass the knowledge test twice","Complete an approved driver education course","Bring a parent to the test"],"h1":"It involves a class.","h2":"In Utah, an applicant 19 or older can skip the 90-day permit holding period by completing an approved driver education course.","p":"Right. Finishing approved driver education waives the 90-day wait."},"es":{"q":"En Utah, usted tiene 20 años y nunca ha tenido licencia. ¿Cómo puede evitar la espera de 90 días con el permiso de aprendiz?","o":["Pagando una tarifa extra","Pasando el examen escrito dos veces","Completando un curso aprobado de educación vial","Llevando a uno de sus padres al examen"],"h1":"Tiene que ver con una clase.","h2":"En Utah, una persona de 19 años o más puede evitar la espera de 90 días con el permiso si completa un curso aprobado de educación vial.","p":"Correcto. Terminar un curso aprobado de educación vial quita la espera de 90 días."},"ref":{"doc":"UT","page":6}},{"id":"ut-059","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, you get your first learner permit at age 18. How long must you hold it before getting a license?","o":["Six months","There is no holding period, but you must finish driver education","90 days","One year"],"h1":"Age 18 is treated differently from ages 16-17 and 19+.","h2":"In Utah, an 18-year-old has no permit holding period but must complete an approved driver education course.","p":"Right. At 18 there is no holding period, but driver education is required."},"es":{"q":"En Utah, usted obtiene su primer permiso de aprendiz a los 18 años. ¿Cuánto tiempo debe tenerlo antes de obtener la licencia?","o":["Seis meses","No hay tiempo de espera, pero debe terminar la educación vial","90 días","Un año"],"h1":"Los 18 años se tratan distinto que los 16-17 y los 19 o más.","h2":"En Utah, una persona de 18 años no tiene tiempo de espera con el permiso, pero debe completar un curso aprobado de educación vial.","p":"Correcto. A los 18 no hay espera, pero se requiere la educación vial."},"ref":{"doc":"UT","page":7}},{"id":"ut-060","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, where must your learner permit be while you are driving?","o":["In your immediate possession","At home in a safe place","With your parent at home","On file at the driver license office only"],"h1":"You must be able to show it right away.","h2":"In Utah, your learner permit must be in your immediate possession whenever you drive.","p":"Right. Keep your learner permit with you when you drive."},"es":{"q":"En Utah, ¿dónde debe estar su permiso de aprendiz mientras maneja?","o":["Con usted, a la mano","En casa, en un lugar seguro","Con su padre o madre en casa","Solo en el archivo de la oficina de licencias"],"h1":"Debe poder mostrarlo enseguida.","h2":"En Utah, su permiso de aprendiz debe estar con usted, a la mano, siempre que maneje.","p":"Correcto. Lleve su permiso de aprendiz con usted cuando maneje."},"ref":{"doc":"UT","page":7}},{"id":"ut-061","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, a 16-year-old's parent has no driver license. A licensed aunt, age 30, wants to supervise the teen's permit driving. What does she need?","o":["Nothing, any adult may supervise","Her own learner permit","A CDL","A note or proof from the parent allowing her to supervise"],"h1":"The parent must give permission.","h2":"In Utah, when the parent is not licensed, a licensed adult 21 or older may supervise only with a note or proof from the parent allowing it.","p":"Right. She needs a note or proof of permission from the parent."},"es":{"q":"En Utah, el padre de un joven de 16 años no tiene licencia. Una tía con licencia, de 30 años, quiere supervisar al joven con permiso de aprendiz. ¿Qué necesita ella?","o":["Nada, cualquier adulto puede supervisar","Su propio permiso de aprendiz","Una licencia comercial (CDL)","Una nota o prueba del padre que le permita supervisar"],"h1":"El padre debe dar permiso.","h2":"En Utah, cuando el padre no tiene licencia, un adulto con licencia de 21 años o más puede supervisar solo con una nota o prueba del padre que lo permita.","p":"Correcto. Ella necesita una nota o prueba de permiso del padre."},"ref":{"doc":"UT","page":6}},{"id":"ut-062","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, may a licensed stepparent supervise a teen who has a learner permit?","o":["No, only a birth parent may","Yes, a stepparent counts as a parent","Only if the stepparent is over 30","Only on weekends"],"h1":"A 2026 law made the meaning of parent clear.","h2":"In Utah, a licensed parent, stepparent or foster parent may supervise a teen who has a learner permit.","p":"Right. A licensed stepparent may supervise a permit driver."},"es":{"q":"En Utah, ¿puede un padrastro o madrastra con licencia supervisar a un joven con permiso de aprendiz?","o":["No, solo un padre biológico puede","Sí, un padrastro o madrastra cuenta como padre","Solo si tiene más de 30 años","Solo los fines de semana"],"h1":"Una ley de 2026 aclaró qué significa padre.","h2":"En Utah, un padre, padrastro, madrastra o padre de crianza con licencia puede supervisar a un joven con permiso de aprendiz.","p":"Correcto. Un padrastro o madrastra con licencia puede supervisar."},"ref":{"doc":"UT","page":6}},{"id":"ut-063","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, what is the fee for a learner permit?","o":["$9.00","$52.00","$19.00","$39.00"],"h1":"It is less than half of a provisional license fee.","h2":"In Utah, the learner permit fee is $19.00.","p":"Right. A Utah learner permit costs $19.00."},"es":{"q":"En Utah, ¿cuánto cuesta el permiso de aprendiz?","o":["$9.00","$52.00","$19.00","$39.00"],"h1":"Es menos de la mitad de lo que cuesta una licencia provisional.","h2":"En Utah, el permiso de aprendiz cuesta $19.00.","p":"Correcto. El permiso de aprendiz de Utah cuesta $19.00."},"ref":{"doc":"UT","page":9}},{"id":"ut-064","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what is the fee for a provisional Class D license for a driver under 21?","o":["$39.00","$19.00","$52.00","$85.00"],"h1":"It costs less than a regular license for drivers 21 and over.","h2":"In Utah, a provisional Class D license for a driver under 21 costs $39.00.","p":"Right. The provisional license costs $39.00."},"es":{"q":"En Utah, ¿cuánto cuesta una licencia provisional Clase D para un conductor menor de 21 años?","o":["$39.00","$19.00","$52.00","$85.00"],"h1":"Cuesta menos que una licencia regular para mayores de 21.","h2":"En Utah, una licencia provisional Clase D para un conductor menor de 21 años cuesta $39.00.","p":"Correcto. La licencia provisional cuesta $39.00."},"ref":{"doc":"UT","page":9}},{"id":"ut-065","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, a regular Class D license lets you drive personal vehicles up to what weight?","o":["26,000 pounds","10,000 pounds","16,000 pounds","40,000 pounds"],"h1":"One pound more and you need a commercial license.","h2":"In Utah, a regular Class D license covers personal vehicles up to 26,000 pounds.","p":"Right. Class D covers vehicles up to 26,000 pounds."},"es":{"q":"En Utah, ¿hasta qué peso de vehículos personales le permite manejar una licencia regular Clase D?","o":["26,000 libras","10,000 libras","16,000 libras","40,000 libras"],"h1":"Una libra más y necesita una licencia comercial.","h2":"En Utah, una licencia regular Clase D cubre vehículos personales de hasta 26,000 libras.","p":"Correcto. La Clase D cubre vehículos de hasta 26,000 libras."},"ref":{"doc":"UT","page":10}},{"id":"ut-066","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, why do drivers under 21 get a provisional license?","o":["So they cannot drive on freeways","So they pay a higher fee","So they must retest every year","So a separate point system applies to them"],"h1":"It has to do with how violations are counted.","h2":"In Utah, drivers under 21 get a provisional license so that a separate, stricter point system applies to them.","p":"Right. Provisional licenses use a separate point system."},"es":{"q":"En Utah, ¿por qué los conductores menores de 21 años reciben una licencia provisional?","o":["Para que no puedan manejar en autopistas","Para que paguen una tarifa más alta","Para que repitan el examen cada año","Para que se les aplique un sistema de puntos aparte"],"h1":"Tiene que ver con cómo se cuentan las infracciones.","h2":"En Utah, los conductores menores de 21 años reciben licencia provisional para que se les aplique un sistema de puntos aparte y más estricto.","p":"Correcto. La licencia provisional usa un sistema de puntos aparte."},"ref":{"doc":"UT","page":10}},{"id":"ut-067","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, a provisional license is issued to a driver under 21. When does it expire?","o":["On the driver's 21st birthday","On the driver's birthday five years after issue","Eight years after issue","Two years after issue"],"h1":"It is shorter than the eight years for older drivers.","h2":"In Utah, a provisional license expires on the driver's birthday five years after it is issued.","p":"Right. A provisional license expires on the birthday five years after issue."},"es":{"q":"En Utah, una licencia provisional se emite a un conductor menor de 21 años. ¿Cuándo vence?","o":["El día que cumple 21 años","En el cumpleaños del conductor cinco años después de emitirse","Ocho años después de emitirse","Dos años después de emitirse"],"h1":"Es menos que los ocho años de los conductores mayores.","h2":"En Utah, una licencia provisional vence en el cumpleaños del conductor cinco años después de emitirse.","p":"Correcto. La licencia provisional vence en el cumpleaños cinco años después."},"ref":{"doc":"UT","page":18}},{"id":"ut-068","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how often does a Driving Privilege Card (DPC) expire?","o":["Every eight years","Every five years","Every year on the holder's birthday","Never"],"h1":"It is the shortest term of any Utah driving card.","h2":"In Utah, a Driving Privilege Card expires every year on the holder's birthday.","p":"Right. A DPC expires each year on your birthday."},"es":{"q":"En Utah, ¿cada cuánto vence una Tarjeta de Privilegio para Manejar (DPC)?","o":["Cada ocho años","Cada cinco años","Cada año en el cumpleaños del titular","Nunca"],"h1":"Es el plazo más corto de todas las tarjetas para manejar de Utah.","h2":"En Utah, la Tarjeta de Privilegio para Manejar vence cada año en el cumpleaños del titular.","p":"Correcto. La DPC vence cada año en su cumpleaños."},"ref":{"doc":"UT","page":10}},{"id":"ut-069","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what may a Driving Privilege Card (DPC) be used for?","o":["Driving only","Driving and boarding airplanes","Proof of age to buy alcohol","Any official identification"],"h1":"It is not an ID card.","h2":"In Utah, a Driving Privilege Card may be used for driving only; it is not valid identification or proof of age.","p":"Right. A DPC is for driving only."},"es":{"q":"En Utah, ¿para qué se puede usar la Tarjeta de Privilegio para Manejar (DPC)?","o":["Solo para manejar","Para manejar y subir a aviones","Como prueba de edad para comprar alcohol","Como cualquier identificación oficial"],"h1":"No es una tarjeta de identificación.","h2":"En Utah, la Tarjeta de Privilegio para Manejar sirve solo para manejar; no es identificación válida ni prueba de edad.","p":"Correcto. La DPC es solo para manejar."},"ref":{"doc":"UT","page":10}},{"id":"ut-070","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, you were just approved for a Driving Privilege Card. When may you start driving?","o":["Right away with a paper temporary license","Only after the plastic card arrives by mail","After 30 days","After you pass a second road test"],"h1":"Utah law gives no temporary license for this card.","h2":"In Utah, there is no temporary license for a Driving Privilege Card, so you may not drive until the plastic card arrives by mail.","p":"Right. With a DPC, you wait for the plastic card before driving."},"es":{"q":"En Utah, le acaban de aprobar una Tarjeta de Privilegio para Manejar. ¿Cuándo puede empezar a manejar?","o":["Enseguida con una licencia temporal de papel","Solo después de que llegue la tarjeta de plástico por correo","Después de 30 días","Después de pasar un segundo examen de manejo"],"h1":"La ley de Utah no da licencia temporal para esta tarjeta.","h2":"En Utah, no hay licencia temporal para la Tarjeta de Privilegio para Manejar, así que no puede manejar hasta que llegue la tarjeta de plástico por correo.","p":"Correcto. Con la DPC, espere la tarjeta de plástico antes de manejar."},"ref":{"doc":"UT","page":10}},{"id":"ut-071","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, which letter on a license is the motorcycle endorsement?","o":["D","C","Z","M"],"h1":"It is the first letter of the word.","h2":"In Utah, the letter M on a license is the motorcycle endorsement.","p":"Right. M means motorcycle."},"es":{"q":"En Utah, ¿qué letra en la licencia es el endoso de motocicleta?","o":["D","C","Z","M"],"h1":"Es la primera letra de la palabra en inglés (motorcycle).","h2":"En Utah, la letra M en la licencia es el endoso de motocicleta.","p":"Correcto. M significa motocicleta."},"ref":{"doc":"UT","page":12}},{"id":"ut-072","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what does restriction code B on a license mean?","o":["The driver must wear corrective lenses","Daylight driving only","Automatic transmission only","No freeway driving"],"h1":"It has to do with eyesight.","h2":"In Utah, restriction B means the driver must wear corrective lenses, such as glasses or contacts, while driving.","p":"Right. Restriction B means corrective lenses are required."},"es":{"q":"En Utah, ¿qué significa el código de restricción B en una licencia?","o":["El conductor debe usar lentes correctivos","Solo puede manejar de día","Solo transmisión automática","No puede manejar en autopistas"],"h1":"Tiene que ver con la vista.","h2":"En Utah, la restricción B significa que el conductor debe usar lentes correctivos, como anteojos o lentes de contacto, al manejar.","p":"Correcto. La restricción B exige lentes correctivos."},"ref":{"doc":"UT","page":12}},{"id":"ut-073","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, which kind of document will the driver license office accept?","o":["A faxed copy","An original or a copy certified by the agency that issued it","A photocopy","A photo on your phone"],"h1":"Copies you make yourself do not count.","h2":"In Utah, documents must be originals or copies certified by the issuing agency; faxed or photocopied documents are not accepted.","p":"Right. Bring originals or certified copies."},"es":{"q":"En Utah, ¿qué tipo de documento acepta la oficina de licencias?","o":["Una copia por fax","El original o una copia certificada por la agencia que lo emitió","Una fotocopia","Una foto en su teléfono"],"h1":"Las copias que usted mismo hace no cuentan.","h2":"En Utah, los documentos deben ser originales o copias certificadas por la agencia que los emitió; no se aceptan copias por fax ni fotocopias.","p":"Correcto. Lleve originales o copias certificadas."},"ref":{"doc":"UT","page":13}},{"id":"ut-074","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, how many documents must you bring to prove your Utah residence address?","o":["None","One","Three","Two"],"h1":"A bank statement and a utility bill together would do it.","h2":"In Utah, you must bring two acceptable documents that prove your Utah residence address.","p":"Right. You need two proofs of your Utah address."},"es":{"q":"En Utah, ¿cuántos documentos debe llevar para probar su dirección de residencia en Utah?","o":["Ninguno","Uno","Tres","Dos"],"h1":"Un estado de cuenta del banco y una factura de servicios juntos servirían.","h2":"En Utah, usted debe llevar dos documentos aceptables que prueben su dirección de residencia en Utah.","p":"Correcto. Necesita dos pruebas de su dirección en Utah."},"ref":{"doc":"UT","page":13}},{"id":"ut-075","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, how recent must your proof-of-address documents, like a utility bill, be?","o":["Dated within 30 days","Dated within one year","Dated within 90 days","Any date is fine"],"h1":"About three months.","h2":"In Utah, residency documents must show your name and address and be dated within 90 days.","p":"Right. Proof of address must be dated within 90 days."},"es":{"q":"En Utah, ¿qué tan recientes deben ser sus documentos de dirección, como una factura de servicios?","o":["Con fecha de los últimos 30 días","Con fecha del último año","Con fecha de los últimos 90 días","Cualquier fecha sirve"],"h1":"Unos tres meses.","h2":"En Utah, los documentos de residencia deben mostrar su nombre y dirección y tener fecha de los últimos 90 días.","p":"Correcto. La prueba de dirección debe tener fecha de los últimos 90 días."},"ref":{"doc":"UT","page":15}},{"id":"ut-076","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, which birth certificate will NOT be accepted as proof of identity?","o":["A certificate issued by the hospital","A certified copy from the state office of vital statistics","A certified copy from your birth state's records agency","A Consular Report of Birth Abroad"],"h1":"It must come from a government records office.","h2":"In Utah, hospital-issued, small laminated or photocopied birth certificates are not accepted; you need a state-certified copy.","p":"Right. A hospital birth certificate is not accepted."},"es":{"q":"En Utah, ¿qué acta de nacimiento NO se acepta como prueba de identidad?","o":["Un certificado emitido por el hospital","Una copia certificada de la oficina estatal de estadísticas vitales","Una copia certificada de la agencia de registros de su estado de nacimiento","Un Informe Consular de Nacimiento en el Extranjero"],"h1":"Debe venir de una oficina de registros del gobierno.","h2":"En Utah, no se aceptan actas de nacimiento del hospital, pequeñas plastificadas o fotocopiadas; necesita una copia certificada por el estado.","p":"Correcto. Un certificado del hospital no se acepta."},"ref":{"doc":"UT","page":14}},{"id":"ut-077","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, you are moving here and apply for a Utah license. What happens to your out-of-state license?","o":["You keep it as a backup","It is mailed back to your old state after a year","You may keep it until it expires","You must surrender it"],"h1":"You may have only one license.","h2":"In Utah, you must surrender your out-of-state license when you apply for a Utah driver license.","p":"Right. You hand in your out-of-state license."},"es":{"q":"En Utah, usted se muda aquí y solicita una licencia de Utah. ¿Qué pasa con su licencia de otro estado?","o":["La guarda como respaldo","Se envía a su estado anterior después de un año","Puede guardarla hasta que venza","Debe entregarla"],"h1":"Solo puede tener una licencia.","h2":"En Utah, usted debe entregar su licencia de otro estado cuando solicita una licencia de manejar de Utah.","p":"Correcto. Usted entrega su licencia de otro estado."},"ref":{"doc":"UT","page":18}},{"id":"ut-078","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, a visiting teen has a learner permit from another state. May the teen practice driving in Utah?","o":["Yes, for up to six months","Yes, with any adult","No, an out-of-state learner permit is not valid in Utah","Yes, but only on weekends"],"h1":"The six-month visitor rule is for full licenses.","h2":"In Utah, a driver with an out-of-state learner permit may not drive.","p":"Right. Out-of-state learner permits are not valid in Utah."},"es":{"q":"En Utah, un joven de visita tiene un permiso de aprendiz de otro estado. ¿Puede practicar manejo en Utah?","o":["Sí, hasta seis meses","Sí, con cualquier adulto","No, un permiso de aprendiz de otro estado no es válido en Utah","Sí, pero solo los fines de semana"],"h1":"La regla de seis meses para visitantes es para licencias completas.","h2":"En Utah, un conductor con permiso de aprendiz de otro estado no puede manejar.","p":"Correcto. Los permisos de aprendiz de otros estados no valen en Utah."},"ref":{"doc":"UT","page":18}},{"id":"ut-079","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how early may you renew your driver license before it expires?","o":["Up to six months before","Up to one month before","Up to two years before","Only after it expires"],"h1":"It is half a year.","h2":"In Utah, you may renew your driver license up to six months before it expires.","p":"Right. You can renew up to six months early."},"es":{"q":"En Utah, ¿con cuánta anticipación puede renovar su licencia antes de que venza?","o":["Hasta seis meses antes","Hasta un mes antes","Hasta dos años antes","Solo después de que venza"],"h1":"Es medio año.","h2":"En Utah, usted puede renovar su licencia de manejar hasta seis meses antes de que venza.","p":"Correcto. Puede renovar hasta seis meses antes."},"ref":{"doc":"UT","page":18}},{"id":"ut-080","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, you lost your license and get a replacement. When does the replacement expire?","o":["Eight years from the replacement date","One year from the replacement date","Five years from the replacement date","On the same date as the license it replaces"],"h1":"A replacement does not restart the clock.","h2":"In Utah, a replacement license expires on the same date as the license it replaces.","p":"Right. A replacement keeps the old expiration date."},"es":{"q":"En Utah, usted perdió su licencia y saca un duplicado. ¿Cuándo vence el duplicado?","o":["Ocho años después de la fecha del duplicado","Un año después de la fecha del duplicado","Cinco años después de la fecha del duplicado","En la misma fecha que la licencia que reemplaza"],"h1":"Un duplicado no reinicia el plazo.","h2":"En Utah, un duplicado de licencia vence en la misma fecha que la licencia que reemplaza.","p":"Correcto. El duplicado conserva la fecha de vencimiento anterior."},"ref":{"doc":"UT","page":19}},{"id":"ut-081","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, to qualify for the Good Driver Program (online renewal), you may have no more than how many reportable violations in the past eight years?","o":["None at all","Two","Six","Twelve"],"h1":"The limit is more than a few.","h2":"In Utah, you qualify for the Good Driver Program if you have had no more than six reportable violations in the past eight years and your license is valid.","p":"Right. No more than six reportable violations in eight years."},"es":{"q":"En Utah, para calificar al Programa de Buen Conductor (renovación en línea), ¿cuántas infracciones reportables como máximo puede tener en los últimos ocho años?","o":["Ninguna","Dos","Seis","Doce"],"h1":"El límite es más que unas pocas.","h2":"En Utah, usted califica al Programa de Buen Conductor si no ha tenido más de seis infracciones reportables en los últimos ocho años y su licencia es válida.","p":"Correcto. No más de seis infracciones reportables en ocho años."},"ref":{"doc":"UT","page":19}},{"id":"ut-082","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, you cannot pass the vision test at the office. What happens next?","o":["Your license is denied for one year","You may retest in five minutes with no glasses","You must take a road test instead","You take a Certificate of Visual Examination form to an eye doctor"],"h1":"A specialist fills out a form.","h2":"In Utah, if you cannot pass the vision test, you are asked to take a Certificate of Visual Examination (CVE) form to an eye doctor.","p":"Right. An eye doctor completes the CVE form."},"es":{"q":"En Utah, usted no pasa el examen de la vista en la oficina. ¿Qué sigue?","o":["Le niegan la licencia por un año","Puede repetirlo en cinco minutos sin anteojos","Debe tomar un examen de manejo en su lugar","Lleva un formulario de Certificado de Examen Visual a un oculista"],"h1":"Un especialista llena un formulario.","h2":"En Utah, si no pasa el examen de la vista, le piden llevar un formulario de Certificado de Examen Visual (CVE) a un médico de los ojos.","p":"Correcto. Un médico de los ojos llena el formulario CVE."},"ref":{"doc":"UT","page":21}},{"id":"ut-083","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, how many written knowledge tests may you take in one day?","o":["Two","One","Three","As many as you like"],"h1":"You get a second try the same day.","h2":"In Utah, you may take two written knowledge tests per day, if the office can fit you in.","p":"Right. You may take two knowledge tests in one day."},"es":{"q":"En Utah, ¿cuántos exámenes escritos de conocimientos puede tomar en un día?","o":["Dos","Uno","Tres","Todos los que quiera"],"h1":"Tiene un segundo intento el mismo día.","h2":"En Utah, usted puede tomar dos exámenes escritos de conocimientos por día, si la oficina tiene espacio.","p":"Correcto. Puede tomar dos exámenes escritos en un día."},"ref":{"doc":"UT","page":23}},{"id":"ut-084","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, how many tries at the written knowledge test does one fee cover?","o":["One","Three within 12 months","Five within 6 months","Unlimited"],"h1":"After that many failures, you pay again.","h2":"In Utah, one fee covers up to three attempts at the written knowledge test within 12 months.","p":"Right. One fee covers three attempts in 12 months."},"es":{"q":"En Utah, ¿cuántos intentos del examen escrito cubre una tarifa?","o":["Uno","Tres en 12 meses","Cinco en 6 meses","Ilimitados"],"h1":"Después de esa cantidad de fallas, paga otra vez.","h2":"En Utah, una tarifa cubre hasta tres intentos del examen escrito de conocimientos en 12 meses.","p":"Correcto. Una tarifa cubre tres intentos en 12 meses."},"ref":{"doc":"UT","page":23}},{"id":"ut-085","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, a driver who was licensed before (for example, in another state) takes what kind of written knowledge test?","o":["A closed-book 50-question test","No written test at all","An oral test only","An open-book 25-question test"],"h1":"It is shorter than the test for brand-new drivers, and you may look at the book.","h2":"In Utah, a previously licensed driver takes an open-book written test with 25 questions.","p":"Right. Previously licensed drivers take a 25-question open-book test."},"es":{"q":"En Utah, un conductor que ya tuvo licencia (por ejemplo, en otro estado), ¿qué tipo de examen escrito toma?","o":["Un examen a libro cerrado de 50 preguntas","Ningún examen escrito","Solo un examen oral","Un examen a libro abierto de 25 preguntas"],"h1":"Es más corto que el de conductores nuevos, y puede consultar el manual.","h2":"En Utah, un conductor que ya tuvo licencia toma un examen escrito a libro abierto de 25 preguntas.","p":"Correcto. Quienes ya tuvieron licencia toman un examen de 25 preguntas a libro abierto."},"ref":{"doc":"UT","page":null}},{"id":"ut-086","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, what is the youngest age to take the driving skills test with a certified third-party tester or a high school?","o":["15","16","17","18"],"h1":"It is one year younger than at a Driver License Division office.","h2":"In Utah, you may take the driving skills test at 15 with a third-party tester or high school, but you must be 16 at a division office.","p":"Right. Third-party testers and high schools may test you at 15."},"es":{"q":"En Utah, ¿cuál es la edad mínima para tomar el examen de manejo con un examinador externo certificado o en una escuela secundaria?","o":["15","16","17","18"],"h1":"Es un año menos que en una oficina de la División de Licencias.","h2":"En Utah, puede tomar el examen de manejo a los 15 años con un examinador externo o en la escuela secundaria, pero debe tener 16 en una oficina de la división.","p":"Correcto. Los examinadores externos y las escuelas pueden examinarlo a los 15."},"ref":{"doc":"UT","page":23}},{"id":"ut-087","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, who may be in the car during your driving skills test?","o":["You, the examiner and one parent","You and a licensed friend","Anyone who has a seat belt","Only you and the examiner"],"h1":"No passengers are allowed.","h2":"In Utah, only the applicant and the examiner may be in the vehicle during the driving skills test.","p":"Right. Only you and the examiner ride during the test."},"es":{"q":"En Utah, ¿quién puede estar en el carro durante su examen de manejo?","o":["Usted, el examinador y uno de sus padres","Usted y un amigo con licencia","Cualquiera que tenga cinturón","Solo usted y el examinador"],"h1":"No se permiten pasajeros.","h2":"En Utah, solo el solicitante y el examinador pueden estar en el vehículo durante el examen de manejo.","p":"Correcto. Solo usted y el examinador van en el examen."},"ref":{"doc":"UT","page":23}},{"id":"ut-088","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, you failed the driving skills test. How many driving skills tests may you take in one day?","o":["Two","One","Three","No limit"],"h1":"You are expected to practice before trying again.","h2":"In Utah, you may take only one driving skills test per day.","p":"Right. Only one driving skills test per day."},"es":{"q":"En Utah, usted no pasó el examen de manejo. ¿Cuántos exámenes de manejo puede tomar en un día?","o":["Dos","Uno","Tres","Sin límite"],"h1":"Se espera que practique antes de volver a intentar.","h2":"En Utah, solo puede tomar un examen de manejo por día.","p":"Correcto. Solo un examen de manejo por día."},"ref":{"doc":"UT","page":24}},{"id":"ut-089","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, after you pay the driving skills test fee, how long do you have to finish all the tests?","o":["30 days","One year","Six months","Two years"],"h1":"It is half a year from the day you pay.","h2":"In Utah, all tests must be completed within six months from the day you pay your fee.","p":"Right. You have six months from paying the fee."},"es":{"q":"En Utah, después de pagar la tarifa del examen de manejo, ¿cuánto tiempo tiene para terminar todos los exámenes?","o":["30 días","Un año","Seis meses","Dos años"],"h1":"Es medio año desde el día en que paga.","h2":"En Utah, todos los exámenes deben completarse dentro de seis meses desde el día en que paga la tarifa.","p":"Correcto. Tiene seis meses desde que paga la tarifa."},"ref":{"doc":"UT","page":24}},{"id":"ut-090","scope":"UT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Utah, the car you bring to the driving skills test must have how many rear view mirrors?","o":["Two, with one outside on the driver's left","One inside mirror only","Three, all outside","None, if it has a backup camera"],"h1":"One must be outside the car.","h2":"In Utah, a car used for the driving skills test must have two rear view mirrors, and one must be on the outside, to the driver's left.","p":"Right. Two mirrors, with one outside on the driver's left."},"es":{"q":"En Utah, ¿cuántos espejos retrovisores debe tener el carro que lleva al examen de manejo?","o":["Dos, con uno afuera a la izquierda del conductor","Solo un espejo interior","Tres, todos afuera","Ninguno, si tiene cámara de reversa"],"h1":"Uno debe estar afuera del carro.","h2":"En Utah, el carro del examen de manejo debe tener dos espejos retrovisores, y uno debe estar afuera, a la izquierda del conductor.","p":"Correcto. Dos espejos, uno afuera a la izquierda del conductor."},"ref":{"doc":"UT","page":25}},{"id":"ut-091","scope":"UT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Utah, which license plate must the test vehicle show for the driving skills test?","o":["Front and rear plates","Only a front plate","A temporary paper plate taped inside","A rear plate with current registration"],"h1":"Since January 1, 2025, the front plate is not required.","h2":"In Utah, the test vehicle's rear plate must show current registration; a front plate is not required after January 1, 2025.","p":"Right. The rear plate with current registration is what counts."},"es":{"q":"En Utah, ¿qué placa debe mostrar el vehículo para el examen de manejo?","o":["Placas delantera y trasera","Solo la placa delantera","Una placa temporal de papel pegada adentro","Una placa trasera con registro vigente"],"h1":"Desde el 1 de enero de 2025 no se exige la placa delantera.","h2":"En Utah, la placa trasera del vehículo del examen debe mostrar registro vigente; la placa delantera no se exige después del 1 de enero de 2025.","p":"Correcto. Lo que cuenta es la placa trasera con registro vigente."},"ref":{"doc":"UT","page":25}},{"id":"ut-092","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, which of these causes an automatic failure on the driving skills test?","o":["Signaling a lane change","The examiner has to take control of the vehicle","Asking a question before the test starts","Stopping behind the stop line"],"h1":"Think of something unsafe.","h2":"In Utah, the driving skills test is failed automatically if the examiner has to take control of the vehicle, among other dangerous actions.","p":"Right. If the examiner must take control, you fail automatically."},"es":{"q":"En Utah, ¿cuál de estas cosas causa que falle automáticamente el examen de manejo?","o":["Señalar un cambio de carril","Que el examinador tenga que tomar el control del vehículo","Hacer una pregunta antes de empezar el examen","Detenerse detrás de la línea de alto"],"h1":"Piense en algo peligroso.","h2":"En Utah, el examen de manejo se falla automáticamente si el examinador tiene que tomar el control del vehículo, entre otras acciones peligrosas.","p":"Correcto. Si el examinador debe tomar el control, falla automáticamente."},"ref":{"doc":"UT","page":25}},{"id":"ut-093","scope":"UT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Utah, which car features may you NOT use during the driving skills test?","o":["Headlights and wipers","Mirrors and turn signals","Parking assist and cruise control","The parking brake"],"h1":"The examiner wants to see you do the work yourself.","h2":"In Utah, you cannot use certain safety features, such as parking assist and cruise control, during the driving skills test.","p":"Right. Parking assist and cruise control are not allowed on the test."},"es":{"q":"En Utah, ¿qué funciones del carro NO puede usar durante el examen de manejo?","o":["Las luces y los limpiaparabrisas","Los espejos y las direccionales","La asistencia para estacionar y el control de velocidad crucero","El freno de estacionamiento"],"h1":"El examinador quiere verle hacer el trabajo a usted.","h2":"En Utah, no puede usar ciertas funciones de seguridad, como la asistencia para estacionar y el control de velocidad crucero, durante el examen de manejo.","p":"Correcto. No se permite la asistencia para estacionar ni el control crucero en el examen."},"ref":{"doc":"UT","page":90}},{"id":"ut-094","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, how much space should you leave between your chest and the steering wheel?","o":["2 inches","10 inches","24 inches","36 inches"],"h1":"It is about the length of a pencil and a half.","h2":"In Utah, you should leave 10 inches between your chest and the steering wheel.","p":"Right. Leave 10 inches between your chest and the wheel."},"es":{"q":"En Utah, ¿cuánto espacio debe dejar entre su pecho y el volante?","o":["2 pulgadas","10 pulgadas","24 pulgadas","36 pulgadas"],"h1":"Es como el largo de un lápiz y medio.","h2":"En Utah, debe dejar 10 pulgadas entre su pecho y el volante.","p":"Correcto. Deje 10 pulgadas entre su pecho y el volante."},"ref":{"doc":"UT","page":27}},{"id":"ut-095","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, you got a ticket because a passenger was not buckled. How can the fine be waived?","o":["By completing an online 30-minute seat belt safety course","By paying double","By taking the road test again","It can never be waived"],"h1":"It involves a short online class.","h2":"In Utah, a seat belt fine may be waived when you complete an online 30-minute seat belt safety course.","p":"Right. A 30-minute online course can waive the fine."},"es":{"q":"En Utah, le dieron una multa porque un pasajero no tenía puesto el cinturón. ¿Cómo se puede perdonar la multa?","o":["Completando un curso en línea de 30 minutos sobre el cinturón de seguridad","Pagando el doble","Tomando otra vez el examen de manejo","Nunca se puede perdonar"],"h1":"Tiene que ver con una clase corta en línea.","h2":"En Utah, la multa por cinturón se puede perdonar si completa un curso en línea de 30 minutos sobre el cinturón de seguridad.","p":"Correcto. Un curso en línea de 30 minutos puede perdonar la multa."},"ref":{"doc":"UT","page":28}},{"id":"ut-096","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, an officer may stop your car only because a passenger is not buckled if the passenger is younger than what age?","o":["8","12","16","21"],"h1":"Older passengers can be cited only if you are stopped for something else.","h2":"In Utah, you may be stopped and cited if anyone under 16 is unrestrained; occupants 16 and older may be cited for no seat belt if stopped for another reason.","p":"Right. An unbuckled passenger under 16 is enough reason to be stopped."},"es":{"q":"En Utah, un oficial puede detener su carro solo porque un pasajero no tiene puesto el cinturón si el pasajero es menor de qué edad?","o":["8","12","16","21"],"h1":"A los pasajeros mayores solo los pueden multar si lo detienen por otra razón.","h2":"En Utah, pueden detenerlo y multarlo si alguien menor de 16 años no va asegurado; a los ocupantes de 16 años o más los pueden multar por el cinturón si lo detienen por otra razón.","p":"Correcto. Un pasajero menor de 16 sin cinturón es razón suficiente para detenerlo."},"ref":{"doc":"UT","page":28}},{"id":"ut-097","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, until when must a child ride rear-facing in the back seat?","o":["Until 1 year old and 20 pounds","Until at least 2 years old and 30 pounds, or longer if the seat allows","Until 4 years old and 40 pounds, no matter the seat","Until 8 years old"],"h1":"The age is two.","h2":"In Utah, children must ride rear-facing in the back seat until at least two years old and 30 pounds, or longer if the car seat allows.","p":"Right. Rear-facing until at least age 2 and 30 pounds."},"es":{"q":"En Utah, ¿hasta cuándo debe un niño viajar mirando hacia atrás en el asiento trasero?","o":["Hasta 1 año y 20 libras","Hasta por lo menos 2 años y 30 libras, o más si el asiento lo permite","Hasta 4 años y 40 libras, sin importar el asiento","Hasta 8 años"],"h1":"La edad es dos años.","h2":"En Utah, los niños deben viajar mirando hacia atrás en el asiento trasero hasta por lo menos los dos años y 30 libras, o más si el asiento lo permite.","p":"Correcto. Mirando hacia atrás hasta por lo menos 2 años y 30 libras."},"ref":{"doc":"UT","page":28}},{"id":"ut-098","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a child rides forward-facing in a seat with a harness until at least what age and weight?","o":["2 years and 30 pounds","8 years and 57 inches","12 years and 80 pounds","4 years and 40 pounds"],"h1":"After this, the child moves to a booster seat.","h2":"In Utah, children ride forward-facing with a harness in the back seat until at least four years old and 40 pounds, or longer if the seat allows.","p":"Right. A harnessed seat until at least 4 years and 40 pounds."},"es":{"q":"En Utah, un niño viaja mirando hacia adelante en un asiento con arnés hasta por lo menos qué edad y peso?","o":["2 años y 30 libras","8 años y 57 pulgadas","12 años y 80 libras","4 años y 40 libras"],"h1":"Después de esto, el niño pasa a un asiento elevado (booster).","h2":"En Utah, los niños viajan mirando hacia adelante con arnés en el asiento trasero hasta por lo menos los cuatro años y 40 libras, o más si el asiento lo permite.","p":"Correcto. Asiento con arnés hasta por lo menos 4 años y 40 libras."},"ref":{"doc":"UT","page":28}},{"id":"ut-099","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, children of what age should ride buckled up in a back seat?","o":["12 and under","5 and under","2 and under","Only babies in car seats"],"h1":"It includes most children through grade school.","h2":"In Utah, children 12 and under should ride buckled up in a back seat, which is the safest place for them.","p":"Right. Children 12 and under should ride in the back seat."},"es":{"q":"En Utah, ¿los niños de qué edad deben viajar con cinturón en un asiento trasero?","o":["De 12 años o menos","De 5 años o menos","De 2 años o menos","Solo los bebés en sillas de auto"],"h1":"Incluye a la mayoría de los niños de primaria.","h2":"En Utah, los niños de 12 años o menos deben viajar con cinturón en un asiento trasero, el lugar más seguro para ellos.","p":"Correcto. Los niños de 12 años o menos deben ir en el asiento trasero."},"ref":{"doc":"UT","page":29}},{"id":"ut-100","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, it is an infraction to smoke in a vehicle while carrying children of what age?","o":["5 or younger","10 or younger","15 or younger","17 or younger"],"h1":"It covers children up to their mid-teens.","h2":"In Utah, it is an infraction to be stopped for smoking in a vehicle while carrying children 15 years old or younger.","p":"Right. No smoking with children 15 or younger in the car."},"es":{"q":"En Utah, es una infracción fumar en un vehículo cuando lleva niños de qué edad?","o":["5 años o menos","10 años o menos","15 años o menos","17 años o menos"],"h1":"Cubre a niños hasta la mitad de la adolescencia.","h2":"En Utah, es una infracción que lo detengan por fumar en un vehículo cuando lleva niños de 15 años o menos.","p":"Correcto. No fume con niños de 15 años o menos en el carro."},"ref":{"doc":"UT","page":29}},{"id":"ut-101","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, what is it called when someone disables or removes a car's air bag on purpose?","o":["A warning only","Legal if you own the car","An infraction with no fine","A Class B misdemeanor"],"h1":"It is a crime, not just a ticket.","h2":"In Utah, removing, modifying or failing to repair an air bag so it will not work is a Class B misdemeanor.","p":"Right. Disabling an air bag is a Class B misdemeanor."},"es":{"q":"En Utah, ¿qué es desactivar o quitar a propósito la bolsa de aire de un carro?","o":["Solo una advertencia","Legal si el carro es suyo","Una infracción sin multa","Un delito menor Clase B"],"h1":"Es un delito, no solo una multa.","h2":"En Utah, quitar, modificar o no reparar una bolsa de aire para que no funcione es un delito menor Clase B.","p":"Correcto. Desactivar una bolsa de aire es un delito menor Clase B."},"ref":{"doc":"UT","page":29}},{"id":"ut-102","scope":"UT","cat":"signals","sign":null,"c":2,"en":{"q":"In Utah, for how long must you signal before you turn or change lanes?","o":["Half a second","One second","At least two seconds","Ten seconds"],"h1":"Count it out: one-thousand-one, one-thousand-two.","h2":"In Utah, you must signal for at least two seconds before turning or changing lanes.","p":"Right. Signal for at least two seconds."},"es":{"q":"En Utah, ¿por cuánto tiempo debe poner la direccional antes de dar vuelta o cambiar de carril?","o":["Medio segundo","Un segundo","Por lo menos dos segundos","Diez segundos"],"h1":"Cuéntelo: mil uno, mil dos.","h2":"En Utah, debe poner la direccional por lo menos dos segundos antes de dar vuelta o cambiar de carril.","p":"Correcto. Ponga la direccional por lo menos dos segundos."},"ref":{"doc":"UT","page":34}},{"id":"ut-103","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, you make a left turn from a single left-turn lane onto a road with several lanes. Which lane should you finish in?","o":["The far-left lane, closest to the center","The far-right lane","Any lane that is open","The center turn lane"],"h1":"Finish in the lane that matches the one you started from.","h2":"In Utah, when you turn from a single left-turn lane, you finish your turn in the far-left lane.","p":"Right. Finish a single-lane left turn in the far-left lane."},"es":{"q":"En Utah, usted da vuelta a la izquierda desde un solo carril de vuelta hacia una calle de varios carriles. ¿En qué carril debe terminar?","o":["El carril de más a la izquierda, junto al centro","El carril de más a la derecha","Cualquier carril libre","El carril central de vuelta"],"h1":"Termine en el carril que corresponde al que usó al empezar.","h2":"En Utah, cuando da vuelta desde un solo carril de vuelta a la izquierda, termina la vuelta en el carril de más a la izquierda.","p":"Correcto. Termine la vuelta en el carril de más a la izquierda."},"ref":{"doc":"UT","page":31}},{"id":"ut-104","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, what is the \"gore area\" where a ramp meets the freeway, and what is the rule?","o":["A lane for slow trucks that anyone may use","A parking area for breakdowns","A passing lane","The striped area between solid white lines that you may not cross or drive in"],"h1":"It is marked off by solid white lines.","h2":"In Utah, the gore area is the space between solid white lines where a ramp joins or leaves traffic, and it is against the law to cross or drive in it.","p":"Right. Never cross or drive in the gore area."},"es":{"q":"En Utah, ¿qué es el \"área de gore\" donde una rampa se une a la autopista, y cuál es la regla?","o":["Un carril para camiones lentos que cualquiera puede usar","Un área para estacionarse si se descompone","Un carril para rebasar","El área entre líneas blancas continuas que no se puede cruzar ni usar"],"h1":"Está marcada por líneas blancas continuas.","h2":"En Utah, el área de gore es el espacio entre líneas blancas continuas donde una rampa entra o sale del tráfico, y es ilegal cruzarla o manejar en ella.","p":"Correcto. Nunca cruce ni maneje en el área de gore."},"ref":{"doc":"UT","page":31}},{"id":"ut-105","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, two lanes merge into one at a busy work zone. What is the \"zipper method\"?","o":["Merge as early as possible and leave one lane empty","Use both lanes up to the merge point, then take turns merging","Speed up to get ahead before the merge","Stop and wait until the other lane is empty"],"h1":"Think of how the teeth of a zipper come together.","h2":"In Utah, the zipper method means using both lanes until the merge point and then taking turns, one car from each lane.","p":"Right. Use both lanes to the merge point, then take turns."},"es":{"q":"En Utah, dos carriles se unen en uno en una zona de obras con mucho tráfico. ¿Qué es el \"método del cierre\" (zipper)?","o":["Unirse lo antes posible y dejar un carril vacío","Usar los dos carriles hasta el punto de unión y luego turnarse para entrar","Acelerar para adelantarse antes de la unión","Parar y esperar a que el otro carril quede vacío"],"h1":"Piense en cómo se juntan los dientes de un cierre.","h2":"En Utah, el método del cierre significa usar los dos carriles hasta el punto de unión y luego turnarse, un carro de cada carril.","p":"Correcto. Use los dos carriles hasta la unión y luego túrnense."},"ref":{"doc":"UT","page":31}},{"id":"ut-106","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","Away from the curb, with the front tire touching it","It does not matter if the parking brake is set"],"h1":"If the car rolls back, the tire should catch the curb.","h2":"In Utah, when you park uphill next to a curb, turn your wheels away from the curb so the front tire touches it, then set the parking brake.","p":"Right. Uphill with a curb, turn the wheels away from the curb."},"es":{"q":"En Utah, usted se estaciona cuesta arriba junto a la banqueta. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia la banqueta","Derecho","Lejos de la banqueta, con la llanta delantera tocándola","No importa si puso el freno de estacionamiento"],"h1":"Si el carro se va hacia atrás, la llanta debe detenerse contra la banqueta.","h2":"En Utah, cuando se estaciona cuesta arriba junto a la banqueta, gire las llantas lejos de la banqueta para que la llanta delantera la toque, y ponga el freno de estacionamiento.","p":"Correcto. Cuesta arriba con banqueta, gire las llantas lejos de la banqueta."},"ref":{"doc":"UT","page":32}},{"id":"ut-107","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, how close to a crosswalk may you park?","o":["No closer than 20 feet","No closer than 5 feet","No closer than 50 feet","Right up to its edge"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Utah, you may not park on a crosswalk or within 20 feet of one.","p":"Right. Stay at least 20 feet from a crosswalk."},"es":{"q":"En Utah, ¿qué tan cerca de un cruce peatonal puede estacionarse?","o":["No más cerca de 20 pies","No más cerca de 5 pies","No más cerca de 50 pies","Justo en la orilla"],"h1":"Es más que la distancia para un hidrante.","h2":"En Utah, no puede estacionarse en un cruce peatonal ni a menos de 20 pies de uno.","p":"Correcto. Quédese por lo menos a 20 pies de un cruce peatonal."},"ref":{"doc":"UT","page":32}},{"id":"ut-108","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, signs are posted near a fire station. How far from its entrance must you stay when parking on the opposite side of the street?","o":["15 feet","20 feet","30 feet","75 feet"],"h1":"It is farther than the limit on the same side.","h2":"In Utah, where signs are posted, you may not park on the opposite side of the road within 75 feet of a fire station entrance.","p":"Right. On the opposite side, stay 75 feet away when signs are posted."},"es":{"q":"En Utah, hay señales cerca de una estación de bomberos. ¿A qué distancia de la entrada debe quedarse si se estaciona del otro lado de la calle?","o":["15 pies","20 pies","30 pies","75 pies"],"h1":"Es más lejos que el límite del mismo lado.","h2":"En Utah, donde hay señales, no puede estacionarse del lado opuesto de la calle a menos de 75 pies de la entrada de una estación de bomberos.","p":"Correcto. Del lado opuesto, quédese a 75 pies cuando hay señales."},"ref":{"doc":"UT","page":32}},{"id":"ut-109","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, how close to the driveway entrance of a fire station may you park on the same side?","o":["No closer than 10 feet","No closer than 20 feet","No closer than 100 feet","Right next to it"],"h1":"It is the same distance as for a crosswalk.","h2":"In Utah, you may not park within 20 feet of the driveway entrance to a fire station.","p":"Right. Stay at least 20 feet from a fire station driveway."},"es":{"q":"En Utah, ¿qué tan cerca de la entrada de autos de una estación de bomberos puede estacionarse del mismo lado?","o":["No más cerca de 10 pies","No más cerca de 20 pies","No más cerca de 100 pies","Justo al lado"],"h1":"Es la misma distancia que para un cruce peatonal.","h2":"En Utah, no puede estacionarse a menos de 20 pies de la entrada de autos de una estación de bomberos.","p":"Correcto. Quédese por lo menos a 20 pies de la entrada de los bomberos."},"ref":{"doc":"UT","page":32}},{"id":"ut-110","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, how close to the nearest rail of a railroad crossing may you park?","o":["No closer than 15 feet","No closer than 25 feet","No closer than 50 feet","No closer than 500 feet"],"h1":"It is the far end of the stopping range at a crossing.","h2":"In Utah, you may not park on a railroad track or within 50 feet of the nearest rail of a crossing.","p":"Right. Park no closer than 50 feet to the nearest rail."},"es":{"q":"En Utah, ¿qué tan cerca del riel más cercano de un cruce de tren puede estacionarse?","o":["No más cerca de 15 pies","No más cerca de 25 pies","No más cerca de 50 pies","No más cerca de 500 pies"],"h1":"Es el extremo lejano de la distancia para detenerse en un cruce.","h2":"En Utah, no puede estacionarse sobre las vías ni a menos de 50 pies del riel más cercano de un cruce.","p":"Correcto. Estaciónese a no menos de 50 pies del riel más cercano."},"ref":{"doc":"UT","page":32}},{"id":"ut-111","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, when you park next to a curb, how far from the curb may your back wheel be?","o":["No more than 12 inches","No more than 24 inches","No more than 3 feet","Any distance if you are in a marked space"],"h1":"It is one foot.","h2":"In Utah, when parking next to a curb, your back wheel must be no more than 12 inches from the curb.","p":"Right. Your back wheel must be within 12 inches of the curb."},"es":{"q":"En Utah, cuando se estaciona junto a la banqueta, ¿a qué distancia puede quedar su llanta trasera?","o":["A no más de 12 pulgadas","A no más de 24 pulgadas","A no más de 3 pies","A cualquier distancia si está en un espacio marcado"],"h1":"Es un pie.","h2":"En Utah, al estacionarse junto a la banqueta, su llanta trasera debe quedar a no más de 12 pulgadas de la banqueta.","p":"Correcto. Su llanta trasera debe quedar a 12 pulgadas o menos de la banqueta."},"ref":{"doc":"UT","page":33}},{"id":"ut-112","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, after passing on a two-lane road, how far ahead of an oncoming vehicle must you be back in the right lane?","o":["At least 50 feet","At least 200 feet","At least 1,000 feet","Any distance, if you signal"],"h1":"It is more than half a football field.","h2":"In Utah, when you pass, you must return to the right lane no less than 200 feet from oncoming vehicles.","p":"Right. Be back in your lane at least 200 feet before oncoming traffic."},"es":{"q":"En Utah, después de rebasar en una carretera de dos carriles, ¿a qué distancia de un vehículo que viene de frente debe estar de vuelta en el carril derecho?","o":["Por lo menos a 50 pies","Por lo menos a 200 pies","Por lo menos a 1,000 pies","A cualquier distancia, si pone la direccional"],"h1":"Es más de la mitad de una cancha de fútbol americano.","h2":"En Utah, cuando rebasa, debe volver al carril derecho a no menos de 200 pies de los vehículos que vienen de frente.","p":"Correcto. Vuelva a su carril por lo menos 200 pies antes del tráfico de frente."},"ref":{"doc":"UT","page":34}},{"id":"ut-113","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, you are passing a car on its right on a multi-lane road. What is not allowed?","o":["Leaving the roadway, such as driving on the shoulder","Signaling before you move","Checking your mirrors","Keeping a steady speed"],"h1":"Stay on the pavement meant for travel.","h2":"In Utah, when you pass on the right it is illegal to leave the roadway, and you may never pass on the shoulder.","p":"Right. Never leave the roadway or use the shoulder to pass."},"es":{"q":"En Utah, usted rebasa a un carro por la derecha en una calle de varios carriles. ¿Qué no está permitido?","o":["Salirse del camino, como manejar por el acotamiento","Poner la direccional antes de moverse","Revisar sus espejos","Mantener una velocidad constante"],"h1":"Quédese en el pavimento hecho para circular.","h2":"En Utah, cuando rebasa por la derecha es ilegal salirse del camino, y nunca puede rebasar por el acotamiento.","p":"Correcto. Nunca se salga del camino ni use el acotamiento para rebasar."},"ref":{"doc":"UT","page":34}},{"id":"ut-114","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, one snowplow with flashing yellow lights is ahead of you with its plow blade out on the right side. What is the rule?","o":["You may pass on either side","You must stay 500 feet behind it","You may not pass it on the side where the blade is deployed","You must stop until it leaves the road"],"h1":"The blade side is the dangerous side.","h2":"In Utah, you may not pass or overtake a snowplow with flashing yellow lights on the side where its plow blade is deployed.","p":"Right. Never pass a snowplow on its blade side."},"es":{"q":"En Utah, adelante va una quitanieves con luces amarillas intermitentes y su pala extendida del lado derecho. ¿Cuál es la regla?","o":["Puede rebasarla por cualquier lado","Debe quedarse a 500 pies detrás","No puede rebasarla del lado donde está la pala","Debe detenerse hasta que salga del camino"],"h1":"El lado de la pala es el lado peligroso.","h2":"En Utah, no puede rebasar a una quitanieves con luces amarillas intermitentes del lado donde tiene la pala extendida.","p":"Correcto. Nunca rebase a una quitanieves del lado de la pala."},"ref":{"doc":"UT","page":34}},{"id":"ut-115","scope":"UT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Utah, you must stop at a railroad crossing. How far from the nearest rail must you stop?","o":["Right at the rail","At least 5 feet away","At least 100 feet away","More than 15 feet but not more than 50 feet away"],"h1":"There is both a closest and a farthest distance.","h2":"In Utah, when you stop at a railroad crossing, stop more than 15 feet but not more than 50 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Utah, debe detenerse en un cruce de tren. ¿A qué distancia del riel más cercano debe detenerse?","o":["Justo en el riel","Por lo menos a 5 pies","Por lo menos a 100 pies","A más de 15 pies pero no más de 50 pies"],"h1":"Hay una distancia mínima y una máxima.","h2":"En Utah, cuando se detiene en un cruce de tren, deténgase a más de 15 pies pero no más de 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"UT","page":35}},{"id":"ut-116","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, you are on a four-lane road with no median. A school bus stops on the other side with red lights flashing. What must you do?","o":["Keep going, since it is on the other side","Stop, because traffic in both directions must stop","Slow to 20 mph and pass","Honk and pass carefully"],"h1":"With no median, both sides are treated the same.","h2":"In Utah, on a four-lane road without a median, traffic in both directions must stop for a school bus with flashing red lights.","p":"Right. With no median on four lanes, both directions stop."},"es":{"q":"En Utah, usted va por una calle de cuatro carriles sin camellón. Un autobús escolar se detiene del otro lado con luces rojas intermitentes. ¿Qué debe hacer?","o":["Seguir, porque está del otro lado","Detenerse, porque el tráfico en ambas direcciones debe parar","Bajar a 20 mph y pasar","Tocar el claxon y pasar con cuidado"],"h1":"Sin camellón, los dos lados se tratan igual.","h2":"En Utah, en una calle de cuatro carriles sin camellón, el tráfico en ambas direcciones debe detenerse por un autobús escolar con luces rojas intermitentes.","p":"Correcto. Sin camellón en cuatro carriles, paran ambas direcciones."},"ref":{"doc":"UT","page":36}},{"id":"ut-117","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, a school bus driver reports you for passing the bus illegally. Up to how much can the fine be?","o":["$100","$500","$3,000","$10,000"],"h1":"It is in the thousands.","h2":"In Utah, fines for illegally passing a school bus can run up to $3,000, and a conviction usually raises insurance rates.","p":"Right. The fine can be up to $3,000."},"es":{"q":"En Utah, el chofer de un autobús escolar lo reporta por rebasar el autobús ilegalmente. ¿Hasta cuánto puede ser la multa?","o":["$100","$500","$3,000","$10,000"],"h1":"Son miles de dólares.","h2":"En Utah, la multa por rebasar ilegalmente un autobús escolar puede llegar a $3,000, y una condena suele subir el costo del seguro.","p":"Correcto. La multa puede llegar a $3,000."},"ref":{"doc":"UT","page":36}},{"id":"ut-118","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, you may not make a U-turn on a curve or near a hilltop where other drivers cannot see you from how far away?","o":["500 feet","50 feet","100 feet","1 mile"],"h1":"It is the same distance used for dimming high beams.","h2":"In Utah, never make a U-turn on a curve or near the top of a hill where you cannot see or be seen from both directions for 500 feet.","p":"Right. You need 500 feet of view both ways for a U-turn."},"es":{"q":"En Utah, no puede dar una vuelta en U en una curva o cerca de la cima de una colina donde otros conductores no lo vean desde qué distancia?","o":["500 pies","50 pies","100 pies","1 milla"],"h1":"Es la misma distancia que se usa para bajar las luces altas.","h2":"En Utah, nunca dé una vuelta en U en una curva o cerca de la cima de una colina donde no pueda ver ni ser visto desde ambas direcciones a 500 pies.","p":"Correcto. Necesita 500 pies de visibilidad en ambas direcciones para una vuelta en U."},"ref":{"doc":"UT","page":38}},{"id":"ut-119","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, when should a three-point turn be used?","o":["On a freeway when you miss your exit","At any busy intersection","On a one-way street","Only when a two-lane road is too narrow for a U-turn"],"h1":"Going around the block is better if you can.","h2":"In Utah, use a three-point turn only on a two-lane road that is too narrow for a U-turn; going around the block is best when possible.","p":"Right. A three-point turn is for a narrow two-lane road."},"es":{"q":"En Utah, ¿cuándo se debe usar una vuelta en tres movimientos?","o":["En una autopista cuando se pasa la salida","En cualquier cruce con mucho tráfico","En una calle de un solo sentido","Solo cuando una calle de dos carriles es muy angosta para una vuelta en U"],"h1":"Si puede, es mejor dar la vuelta a la cuadra.","h2":"En Utah, use la vuelta en tres movimientos solo en una calle de dos carriles muy angosta para una vuelta en U; es mejor dar la vuelta a la cuadra si se puede.","p":"Correcto. La vuelta en tres movimientos es para una calle angosta de dos carriles."},"ref":{"doc":"UT","page":38}},{"id":"ut-120","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, traffic is jammed on the freeway. May you use an entrance ramp to get off?","o":["Yes, if traffic is stopped","No, it is illegal, even in a traffic jam","Yes, with your hazard lights on","Yes, if an exit is far away"],"h1":"Ramps work in one direction only.","h2":"In Utah, using an entrance ramp to exit the freeway is illegal, even in a traffic jam.","p":"Right. Never exit the freeway by an entrance ramp."},"es":{"q":"En Utah, el tráfico está detenido en la autopista. ¿Puede usar una rampa de entrada para salir?","o":["Sí, si el tráfico está parado","No, es ilegal, aun en un embotellamiento","Sí, con las luces intermitentes encendidas","Sí, si la salida está lejos"],"h1":"Las rampas funcionan en un solo sentido.","h2":"En Utah, usar una rampa de entrada para salir de la autopista es ilegal, aun en un embotellamiento.","p":"Correcto. Nunca salga de la autopista por una rampa de entrada."},"ref":{"doc":"UT","page":39}},{"id":"ut-121","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, what is the area outside the solid white line at the edge of the freeway for?","o":["Passing slow trucks","Picking up passengers","Emergency use only","Motorcycles in heavy traffic"],"h1":"Passing or picking up riders there is illegal.","h2":"In Utah, the freeway area outside the solid white edge line is for emergency use only; passing or stopping to pick up passengers there is illegal.","p":"Right. The freeway shoulder is for emergencies only."},"es":{"q":"En Utah, ¿para qué es el área fuera de la línea blanca continua en la orilla de la autopista?","o":["Para rebasar camiones lentos","Para recoger pasajeros","Solo para emergencias","Para motocicletas cuando hay mucho tráfico"],"h1":"Rebasar o recoger pasajeros ahí es ilegal.","h2":"En Utah, el área de la autopista fuera de la línea blanca de la orilla es solo para emergencias; rebasar o detenerse a recoger pasajeros ahí es ilegal.","p":"Correcto. El acotamiento de la autopista es solo para emergencias."},"ref":{"doc":"UT","page":39}},{"id":"ut-122","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, who may use the I-15 express lanes for free as a carpool?","o":["Vehicles with two or more people","Any vehicle at night","Only vehicles with four or more people","Only trucks"],"h1":"You need at least one passenger.","h2":"In Utah, vehicles with two or more people may use the I-15 express lanes free as a carpool.","p":"Right. Two or more people ride free in the express lanes."},"es":{"q":"En Utah, ¿quién puede usar gratis los carriles exprés de la I-15 como carro compartido?","o":["Vehículos con dos o más personas","Cualquier vehículo de noche","Solo vehículos con cuatro o más personas","Solo camiones"],"h1":"Necesita por lo menos un pasajero.","h2":"En Utah, los vehículos con dos o más personas pueden usar gratis los carriles exprés de la I-15 como carro compartido.","p":"Correcto. Con dos o más personas, el carril exprés es gratis."},"ref":{"doc":"UT","page":40}},{"id":"ut-123","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, where may you move in or out of an I-15 express lane?","o":["Anywhere, if you signal","Across the double white lines when traffic is light","Only at exits","Only at access points marked with white dotted lines"],"h1":"Crossing a double white line is illegal.","h2":"In Utah, you may enter or leave the express lanes only at access points marked with white dotted lines, never across the double white line.","p":"Right. Use the dotted-line access points only."},"es":{"q":"En Utah, ¿dónde puede entrar o salir de un carril exprés de la I-15?","o":["En cualquier lugar, si pone la direccional","Cruzando las dos líneas blancas cuando hay poco tráfico","Solo en las salidas","Solo en los puntos de acceso marcados con líneas blancas punteadas"],"h1":"Cruzar una doble línea blanca es ilegal.","h2":"En Utah, solo puede entrar o salir de los carriles exprés en los puntos de acceso marcados con líneas blancas punteadas, nunca cruzando la doble línea blanca.","p":"Correcto. Use solo los puntos de acceso con línea punteada."},"ref":{"doc":"UT","page":40}},{"id":"ut-124","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, besides carpools, which of these may use the I-15 express lanes free of charge?","o":["Any rental car","Motorcycles","Trucks pulling trailers","Drivers under 18"],"h1":"Buses and vehicles with a C decal also ride free.","h2":"In Utah, motorcycles, buses and vehicles with a clean fuel C decal may use the express lanes free of charge.","p":"Right. Motorcycles may use the express lanes for free."},"es":{"q":"En Utah, además de los carros compartidos, ¿cuál de estos puede usar gratis los carriles exprés de la I-15?","o":["Cualquier carro de renta","Las motocicletas","Camiones con remolque","Conductores menores de 18 años"],"h1":"Los autobuses y los vehículos con calcomanía C también van gratis.","h2":"En Utah, las motocicletas, los autobuses y los vehículos con calcomanía C de combustible limpio pueden usar gratis los carriles exprés.","p":"Correcto. Las motocicletas pueden usar gratis los carriles exprés."},"ref":{"doc":"UT","page":40}},{"id":"ut-125","scope":"UT","cat":"signals","sign":null,"c":0,"en":{"q":"In Utah, how many vehicles may go each time a freeway ramp meter turns green, unless a sign says otherwise?","o":["One","Two","Five","As many as fit"],"h1":"The meter spaces cars out.","h2":"In Utah, a ramp meter lets only one vehicle go each time the green light comes on, unless posted differently.","p":"Right. One vehicle per green light."},"es":{"q":"En Utah, ¿cuántos vehículos pueden pasar cada vez que el semáforo de la rampa de la autopista se pone verde, si no hay una señal que diga otra cosa?","o":["Uno","Dos","Cinco","Todos los que quepan"],"h1":"El semáforo separa a los carros.","h2":"En Utah, el semáforo de rampa deja pasar solo un vehículo cada vez que se pone verde, a menos que se indique otra cosa.","p":"Correcto. Un vehículo por cada luz verde."},"ref":{"doc":"UT","page":40}},{"id":"ut-126","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, the power is out at a single-point urban interchange and there is no battery backup. How should you treat it?","o":["As a four-way stop","With extreme caution and courtesy; it is not handled like a four-way stop","As a green light for the freeway ramps","As a roundabout"],"h1":"An officer will be sent as soon as possible.","h2":"In Utah, a single-point urban interchange without power is not handled like a four-way stop; go with extreme caution and courtesy until an officer arrives.","p":"Right. It is not a four-way stop; use extreme caution and courtesy."},"es":{"q":"En Utah, se fue la luz en un intercambio urbano de un solo punto y no hay batería de respaldo. ¿Cómo debe tratarlo?","o":["Como un alto de cuatro vías","Con extrema precaución y cortesía; no se maneja como un alto de cuatro vías","Como luz verde para las rampas de la autopista","Como una glorieta"],"h1":"Se enviará a un oficial lo antes posible.","h2":"En Utah, un intercambio urbano de un solo punto sin luz no se maneja como un alto de cuatro vías; avance con extrema precaución y cortesía hasta que llegue un oficial.","p":"Correcto. No es un alto de cuatro vías; use extrema precaución y cortesía."},"ref":{"doc":"UT","page":41}},{"id":"ut-127","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, at a single-point urban interchange, when may you make a U-turn from the off-ramp to get back on the freeway?","o":["Never","Only at night","When you face a green arrow as you begin","Whenever no cars are coming"],"h1":"It depends on the signal when you start.","h2":"In Utah, a U-turn from the off-ramp at a single-point urban interchange is legal if you face a green arrow when you begin it.","p":"Right. Start the U-turn on a green arrow."},"es":{"q":"En Utah, en un intercambio urbano de un solo punto, ¿cuándo puede dar vuelta en U desde la rampa de salida para volver a la autopista?","o":["Nunca","Solo de noche","Cuando tiene una flecha verde al empezar","Cuando no viene ningún carro"],"h1":"Depende de la señal cuando empieza.","h2":"En Utah, la vuelta en U desde la rampa de salida en un intercambio urbano de un solo punto es legal si tiene una flecha verde al empezarla.","p":"Correcto. Empiece la vuelta en U con flecha verde."},"ref":{"doc":"UT","page":41}},{"id":"ut-128","scope":"UT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Utah, how do you turn left at a ThrU-turn intersection?","o":["Go straight through, make a signaled U-turn farther down, come back and turn right","Turn left from the right lane","Wait in the middle of the intersection","Make a left turn on red"],"h1":"Left turns are removed at the intersection itself.","h2":"In Utah, at a ThrU-turn intersection you drive through, make a signaled U-turn down the road, then return and turn right.","p":"Right. Go through, U-turn, and come back to turn right."},"es":{"q":"En Utah, ¿cómo da vuelta a la izquierda en un cruce ThrU-turn?","o":["Sigue derecho, da una vuelta en U con semáforo más adelante, regresa y da vuelta a la derecha","Da vuelta a la izquierda desde el carril derecho","Espera en medio del cruce","Da vuelta a la izquierda con luz roja"],"h1":"En el cruce mismo no hay vueltas a la izquierda.","h2":"En Utah, en un cruce ThrU-turn usted sigue derecho, da una vuelta en U con semáforo más adelante, y luego regresa y da vuelta a la derecha.","p":"Correcto. Siga derecho, dé la vuelta en U y regrese para dar vuelta a la derecha."},"ref":{"doc":"UT","page":43}},{"id":"ut-129","scope":"UT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Utah, what is unusual about driving through a diverging diamond interchange?","o":["You must stop on the bridge","Left turns are made from the right shoulder","Only buses may use it","You briefly drive on the opposite side of the road"],"h1":"Traffic crosses over on the bridge.","h2":"In Utah, at a diverging diamond interchange, traffic crosses over and briefly drives on the opposite side of the road on the bridge.","p":"Right. You briefly drive on the opposite side."},"es":{"q":"En Utah, ¿qué tiene de distinto manejar por un intercambio de diamante divergente?","o":["Debe detenerse en el puente","Las vueltas a la izquierda se hacen desde el acotamiento derecho","Solo lo pueden usar autobuses","Por un tramo corto maneja del lado contrario del camino"],"h1":"El tráfico se cruza en el puente.","h2":"En Utah, en un intercambio de diamante divergente, el tráfico se cruza y por un tramo corto maneja del lado contrario del camino en el puente.","p":"Correcto. Por un tramo corto maneja del lado contrario."},"ref":{"doc":"UT","page":43}},{"id":"ut-130","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, how do you turn left at a continuous flow intersection?","o":["Turn left from the right lane at the main signal","Cross the oncoming lanes at an earlier signal, then turn left at a second signal","Make a U-turn and then a right turn","Wait in the center of the intersection for a gap"],"h1":"There are two signals to obey.","h2":"In Utah, at a continuous flow intersection you cross the oncoming lanes on green at the first signal, then turn left on green at the second signal.","p":"Right. Cross over at the first signal, then turn left at the second."},"es":{"q":"En Utah, ¿cómo da vuelta a la izquierda en un cruce de flujo continuo?","o":["Da vuelta a la izquierda desde el carril derecho en el semáforo principal","Cruza los carriles contrarios en un semáforo anterior y luego da vuelta a la izquierda en un segundo semáforo","Da vuelta en U y luego a la derecha","Espera en el centro del cruce a que haya espacio"],"h1":"Hay dos semáforos que obedecer.","h2":"En Utah, en un cruce de flujo continuo usted cruza los carriles contrarios con luz verde en el primer semáforo y luego da vuelta a la izquierda con luz verde en el segundo.","p":"Correcto. Cruce en el primer semáforo y dé vuelta en el segundo."},"ref":{"doc":"UT","page":42}},{"id":"ut-131","scope":"UT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Utah, when no sign is posted, what speed is allowed in a business or residential area?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"It is 5 mph more than a school zone.","h2":"In Utah, when no sign is posted, 25 mph is the speed allowed in any business or residential area.","p":"Right. 25 mph in business and residential areas."},"es":{"q":"En Utah, cuando no hay señal, ¿qué velocidad se permite en una zona comercial o residencial?","o":["15 mph","35 mph","25 mph","45 mph"],"h1":"Son 5 mph más que en una zona escolar.","h2":"En Utah, cuando no hay señal, la velocidad permitida en cualquier zona comercial o residencial es de 25 mph.","p":"Correcto. 25 mph en zonas comerciales y residenciales."},"ref":{"doc":"UT","page":44}},{"id":"ut-132","scope":"UT","cat":"signals","sign":null,"c":0,"en":{"q":"In Utah, you come to an intersection where the traffic lights are not working. What must you do?","o":["Come to a complete stop and yield to vehicles on your right","Go through if no one is coming","Treat it as a yield sign","Flash your lights and go first"],"h1":"Treat it like an all-way stop.","h2":"In Utah, at an intersection where the traffic lights are not working, come to a complete stop and yield to any vehicle on your right, unless an officer directs you.","p":"Right. Stop fully and yield to the vehicle on your right."},"es":{"q":"En Utah, llega a un cruce donde los semáforos no funcionan. ¿Qué debe hacer?","o":["Detenerse por completo y ceder el paso a los vehículos de su derecha","Pasar si no viene nadie","Tratarlo como una señal de ceda el paso","Hacer cambio de luces y pasar primero"],"h1":"Trátelo como un alto en todas las direcciones.","h2":"En Utah, en un cruce donde los semáforos no funcionan, deténgase por completo y ceda el paso a cualquier vehículo de su derecha, a menos que un oficial le indique otra cosa.","p":"Correcto. Deténgase por completo y ceda el paso al vehículo de su derecha."},"ref":{"doc":"UT","page":46}},{"id":"ut-133","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a DUI becomes an \"extreme DUI\" when the driver's blood or breath alcohol level is at least what?","o":["0.02","0.05","0.08","0.16"],"h1":"It is more than three times the regular adult limit.","h2":"In Utah, a DUI is an extreme DUI when the blood or breath alcohol level is 0.16 or higher, among other cases.","p":"Right. Extreme DUI starts at 0.16."},"es":{"q":"En Utah, un DUI se considera \"DUI extremo\" cuando el nivel de alcohol en la sangre o el aliento es por lo menos de cuánto?","o":["0.02","0.05","0.08","0.16"],"h1":"Es más de tres veces el límite regular para adultos.","h2":"En Utah, un DUI es extremo cuando el nivel de alcohol en la sangre o el aliento es de 0.16 o más, entre otros casos.","p":"Correcto. El DUI extremo empieza en 0.16."},"ref":{"doc":"UT","page":1}},{"id":"ut-134","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, what is the alcohol limit for a driver with a commercial driver license (CDL)?","o":["0.08","0.04","0.05","0.10"],"h1":"It is lower than the 0.05 limit for other adult drivers.","h2":"In Utah, the alcohol limit for a CDL driver is 0.04, lower than the 0.05 limit for other adults.","p":"Right. The CDL limit is 0.04."},"es":{"q":"En Utah, ¿cuál es el límite de alcohol para un conductor con licencia comercial (CDL)?","o":["0.08","0.04","0.05","0.10"],"h1":"Es más bajo que el límite de 0.05 para otros adultos.","h2":"En Utah, el límite de alcohol para un conductor con CDL es de 0.04, más bajo que el límite de 0.05 para otros adultos.","p":"Correcto. El límite para CDL es de 0.04."},"ref":{"doc":"UT","page":52}},{"id":"ut-135","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a 19-year-old is convicted for the first time of having or drinking alcohol. For how long is the license suspended?","o":["30 days","Six months","One year","Until age 21"],"h1":"A second offense doubles it.","h2":"In Utah, a person 13 to 20 convicted of having or drinking alcohol has the license suspended for one year on a first offense and two years after that.","p":"Right. A first underage alcohol conviction means a one-year suspension."},"es":{"q":"En Utah, un joven de 19 años es condenado por primera vez por tener o tomar alcohol. ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","Seis meses","Un año","Hasta los 21 años"],"h1":"Una segunda vez lo duplica.","h2":"En Utah, a una persona de 13 a 20 años condenada por tener o tomar alcohol se le suspende la licencia un año la primera vez y dos años después de eso.","p":"Correcto. La primera condena por alcohol siendo menor es una suspensión de un año."},"ref":{"doc":"UT","page":52}},{"id":"ut-136","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, a driver under 21 breaks the Not-a-Drop law a second time within 10 years. How long are driving privileges lost?","o":["Two years or until age 21, whichever is longer","Six months","90 days","Lifetime"],"h1":"It is longer than the six months for a first offense.","h2":"In Utah, a second Not-a-Drop offense within 10 years means losing driving privileges for two years or until age 21, whichever is longer.","p":"Right. Two years or until 21, whichever is longer."},"es":{"q":"En Utah, un conductor menor de 21 años viola la ley \"Ni una gota\" (Not-a-Drop) por segunda vez en 10 años. ¿Por cuánto tiempo pierde el privilegio de manejar?","o":["Dos años o hasta los 21, lo que sea más largo","Seis meses","90 días","De por vida"],"h1":"Es más que los seis meses de la primera vez.","h2":"En Utah, una segunda violación de la ley \"Ni una gota\" en 10 años significa perder el privilegio de manejar por dos años o hasta los 21, lo que sea más largo.","p":"Correcto. Dos años o hasta los 21, lo que sea más largo."},"ref":{"doc":"UT","page":52}},{"id":"ut-137","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a driver 21 or older is convicted of a second DUI. For how long is the license suspended?","o":["120 days","Six months","One year","Two years"],"h1":"A first DUI is 120 days; a second is much longer.","h2":"In Utah, a second or later DUI conviction for a driver 21 or older means a two-year license suspension.","p":"Right. A second DUI means a two-year suspension."},"es":{"q":"En Utah, un conductor de 21 años o más es condenado por un segundo DUI. ¿Por cuánto tiempo se suspende la licencia?","o":["120 días","Seis meses","Un año","Dos años"],"h1":"El primer DUI es de 120 días; el segundo es mucho más.","h2":"En Utah, una segunda condena por DUI o más para un conductor de 21 años o más significa una suspensión de la licencia de dos años.","p":"Correcto. Un segundo DUI significa dos años de suspensión."},"ref":{"doc":"UT","page":52}},{"id":"ut-138","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, after a DUI arrest, when may the division's license suspension begin?","o":["The same day as the arrest","On the 45th to 60th day after the arrest","One year after the arrest","Only after a jury trial"],"h1":"There is a short delay after the arrest.","h2":"In Utah, the division may suspend the license beginning on the 45th to 60th day after the date of arrest.","p":"Right. The suspension may begin 45 to 60 days after arrest."},"es":{"q":"En Utah, después de un arresto por DUI, ¿cuándo puede empezar la suspensión de la licencia por parte de la división?","o":["El mismo día del arresto","Entre el día 45 y el 60 después del arresto","Un año después del arresto","Solo después de un juicio con jurado"],"h1":"Hay un plazo corto después del arresto.","h2":"En Utah, la división puede suspender la licencia a partir del día 45 al 60 después de la fecha del arresto.","p":"Correcto. La suspensión puede empezar de 45 a 60 días después del arresto."},"ref":{"doc":"UT","page":52}},{"id":"ut-139","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, which kinds of chemical tests does the implied consent law cover?","o":["Breath only","Blood only","Breath, blood, urine or oral fluids","Only a field sobriety walk"],"h1":"There are four kinds.","h2":"In Utah, by driving you agree to a chemical test of your breath, blood, urine or oral fluids if a peace officer asks.","p":"Right. Breath, blood, urine or oral fluids."},"es":{"q":"En Utah, ¿qué tipos de pruebas químicas cubre la ley de consentimiento implícito?","o":["Solo de aliento","Solo de sangre","De aliento, sangre, orina o saliva","Solo una prueba de caminar"],"h1":"Son cuatro tipos.","h2":"En Utah, al manejar usted acepta una prueba química de aliento, sangre, orina o saliva si un oficial se lo pide.","p":"Correcto. Aliento, sangre, orina o saliva."},"ref":{"doc":"UT","page":53}},{"id":"ut-140","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, a driver 21 or older refuses a chemical test after a DUI arrest for the second time. For how long is the license revoked?","o":["36 months","18 months","6 months","10 years"],"h1":"It is double the first refusal.","h2":"In Utah, a second or later refusal of a chemical test means a 36-month revocation for a driver 21 or older.","p":"Right. A second refusal means a 36-month revocation."},"es":{"q":"En Utah, un conductor de 21 años o más se niega por segunda vez a una prueba química después de un arresto por DUI. ¿Por cuánto tiempo se revoca la licencia?","o":["36 meses","18 meses","6 meses","10 años"],"h1":"Es el doble de la primera negativa.","h2":"En Utah, una segunda negativa o más a una prueba química significa una revocación de 36 meses para un conductor de 21 años o más.","p":"Correcto. Una segunda negativa significa 36 meses de revocación."},"ref":{"doc":"UT","page":53}},{"id":"ut-141","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, an 18-year-old refuses a chemical test after a DUI arrest for the first time. How long is the license revoked?","o":["90 days","Six months","18 months","Two years or until age 21, whichever is longer"],"h1":"Drivers under 21 get a longer penalty than adults for a first refusal.","h2":"In Utah, a driver under 21 who refuses a chemical test for the first time loses the license for two years or until age 21, whichever is longer.","p":"Right. Two years or until 21, whichever is longer."},"es":{"q":"En Utah, un joven de 18 años se niega por primera vez a una prueba química después de un arresto por DUI. ¿Por cuánto tiempo se revoca la licencia?","o":["90 días","Seis meses","18 meses","Dos años o hasta los 21, lo que sea más largo"],"h1":"Los menores de 21 reciben una sanción más larga que los adultos por la primera negativa.","h2":"En Utah, un conductor menor de 21 años que se niega por primera vez a una prueba química pierde la licencia por dos años o hasta los 21, lo que sea más largo.","p":"Correcto. Dos años o hasta los 21, lo que sea más largo."},"ref":{"doc":"UT","page":53}},{"id":"ut-142","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, what happens to a driver who is convicted of automobile homicide or a felony DUI, regarding alcohol-restricted status?","o":["Two years of alcohol-restricted status","Lifetime alcohol-restricted status","No restriction after jail","Five years of alcohol-restricted status"],"h1":"It is the longest possible.","h2":"In Utah, a conviction for automobile homicide or felony DUI results in a lifetime alcohol-restricted status.","p":"Right. It means lifetime alcohol-restricted status."},"es":{"q":"En Utah, ¿qué le pasa a un conductor condenado por homicidio con vehículo o DUI grave (felony), en cuanto a la restricción de alcohol?","o":["Dos años de restricción de alcohol","Restricción de alcohol de por vida","Ninguna restricción después de la cárcel","Cinco años de restricción de alcohol"],"h1":"Es la más larga posible.","h2":"En Utah, una condena por homicidio con vehículo o DUI grave resulta en una restricción de alcohol de por vida.","p":"Correcto. Significa restricción de alcohol de por vida."},"ref":{"doc":"UT","page":53}},{"id":"ut-143","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, an alcohol-restricted driver is convicted of driving with any measurable alcohol. What happens?","o":["A warning letter","A $50 fine only","The license is revoked for one year","Points are added but no suspension"],"h1":"An alcohol-restricted driver may have no alcohol at all while driving.","h2":"In Utah, if an alcohol-restricted driver is convicted of driving with any measurable alcohol, the license is revoked for one year.","p":"Right. It means a one-year revocation."},"es":{"q":"En Utah, un conductor con restricción de alcohol es condenado por manejar con cualquier cantidad medible de alcohol. ¿Qué pasa?","o":["Una carta de advertencia","Solo una multa de $50","Se le revoca la licencia por un año","Se le agregan puntos pero sin suspensión"],"h1":"Un conductor con restricción de alcohol no puede tener nada de alcohol al manejar.","h2":"En Utah, si un conductor con restricción de alcohol es condenado por manejar con cualquier cantidad medible de alcohol, se le revoca la licencia por un año.","p":"Correcto. Significa un año de revocación."},"ref":{"doc":"UT","page":53}},{"id":"ut-144","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, a driver 21 or older is convicted of a first DUI. For how long must they drive only vehicles with an ignition interlock device?","o":["18 months","3 years","6 months","10 years"],"h1":"It is one and a half years.","h2":"In Utah, after a first DUI conviction, a driver 21 or older is restricted to vehicles with an ignition interlock device for 18 months.","p":"Right. A first DUI means 18 months with an ignition interlock."},"es":{"q":"En Utah, un conductor de 21 años o más es condenado por un primer DUI. ¿Por cuánto tiempo solo puede manejar vehículos con un dispositivo de bloqueo de encendido (interlock)?","o":["18 meses","3 años","6 meses","10 años"],"h1":"Es un año y medio.","h2":"En Utah, después de un primer DUI, un conductor de 21 años o más solo puede manejar vehículos con dispositivo de bloqueo de encendido durante 18 meses.","p":"Correcto. Un primer DUI significa 18 meses con dispositivo de bloqueo."},"ref":{"doc":"UT","page":54}},{"id":"ut-145","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a driver's license is revoked for refusing a chemical test after a DUI arrest. How long is the ignition interlock restriction?","o":["6 months","One year","18 months","Two years"],"h1":"It is the same as for a second DUI.","h2":"In Utah, a driver revoked for refusing a chemical test is restricted to vehicles with an ignition interlock device for two years.","p":"Right. A refusal brings a two-year ignition interlock restriction."},"es":{"q":"En Utah, se revoca la licencia de un conductor por negarse a una prueba química después de un arresto por DUI. ¿Cuánto dura la restricción de bloqueo de encendido?","o":["6 meses","Un año","18 meses","Dos años"],"h1":"Es igual que para un segundo DUI.","h2":"En Utah, un conductor revocado por negarse a una prueba química solo puede manejar vehículos con dispositivo de bloqueo de encendido durante dos años.","p":"Correcto. Negarse trae dos años de restricción de bloqueo de encendido."},"ref":{"doc":"UT","page":54}},{"id":"ut-146","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a driver with an ignition interlock tries to start the car with an alcohol level of 0.02 or higher. What happens?","o":["Nothing, it is below 0.05","The car is taken away for good","The interlock requirement is extended by 60 days","The driver pays a $10 fee"],"h1":"Each time it happens, more time is added.","h2":"In Utah, each attempt to start the vehicle with an alcohol level of 0.02 or higher extends the ignition interlock requirement by 60 days.","p":"Right. It adds 60 days to the interlock requirement."},"es":{"q":"En Utah, un conductor con dispositivo de bloqueo intenta encender el carro con un nivel de alcohol de 0.02 o más. ¿Qué pasa?","o":["Nada, está debajo de 0.05","Le quitan el carro para siempre","El requisito del bloqueo se extiende 60 días","El conductor paga $10"],"h1":"Cada vez que pasa, se agrega más tiempo.","h2":"En Utah, cada intento de encender el vehículo con un nivel de alcohol de 0.02 o más extiende el requisito del bloqueo de encendido 60 días.","p":"Correcto. Se agregan 60 días al requisito del bloqueo."},"ref":{"doc":"UT","page":54}},{"id":"ut-147","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how long is the ignition interlock restriction after a conviction for automobile homicide?","o":["10 years","18 months","3 years","6 months"],"h1":"It is the longest interlock restriction in the handbook.","h2":"In Utah, automobile homicide carries a 10-year ignition interlock restriction.","p":"Right. Automobile homicide means 10 years with an interlock."},"es":{"q":"En Utah, ¿cuánto dura la restricción de bloqueo de encendido después de una condena por homicidio con vehículo?","o":["10 años","18 meses","3 años","6 meses"],"h1":"Es la restricción de bloqueo más larga del manual.","h2":"En Utah, el homicidio con vehículo trae una restricción de bloqueo de encendido de 10 años.","p":"Correcto. El homicidio con vehículo significa 10 años con bloqueo."},"ref":{"doc":"UT","page":54}},{"id":"ut-148","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah's handbook, at what blood alcohol level does alcohol already start to affect every driver's vision?","o":["0.16","0.08","0.05","0.02"],"h1":"It is far below the legal limit.","h2":"In Utah's handbook, vision is affected at a blood alcohol level of just 0.02 for all drivers.","p":"Right. Vision is affected at 0.02."},"es":{"q":"Según el manual de Utah, ¿a qué nivel de alcohol en la sangre ya empieza a afectarse la vista de todo conductor?","o":["0.16","0.08","0.05","0.02"],"h1":"Está muy por debajo del límite legal.","h2":"Según el manual de Utah, la vista se afecta con un nivel de alcohol en la sangre de solo 0.02 en todos los conductores.","p":"Correcto. La vista se afecta a 0.02."},"ref":{"doc":"UT","page":51}},{"id":"ut-149","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, what does an interdicted driver license or ID card show?","o":["The holder is a new driver","The holder may not buy alcohol in Utah","The holder is an organ donor","The holder may drive only in daylight"],"h1":"It is about purchases at bars and liquor stores.","h2":"In Utah, an interdicted license or ID card shows that the holder cannot buy alcohol in Utah restaurants, bars or state liquor stores.","p":"Right. It shows the holder may not buy alcohol."},"es":{"q":"En Utah, ¿qué indica una licencia o identificación con marca de \"interdicción\" (interdicted)?","o":["Que el titular es conductor nuevo","Que el titular no puede comprar alcohol en Utah","Que el titular es donante de órganos","Que el titular solo puede manejar de día"],"h1":"Tiene que ver con compras en bares y licorerías.","h2":"En Utah, una licencia o identificación con interdicción indica que el titular no puede comprar alcohol en restaurantes, bares ni licorerías estatales de Utah.","p":"Correcto. Indica que el titular no puede comprar alcohol."},"ref":{"doc":"UT","page":55}},{"id":"ut-150","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, a driver is convicted of a crime with a road rage enhancement for the first time. What may the court order?","o":["A warning only","A 30-day suspension","A one-year license suspension","A lifetime revocation"],"h1":"It is a full year.","h2":"In Utah, the court may order a one-year license suspension on a first conviction with a road rage enhancement.","p":"Right. The court may suspend the license for one year."},"es":{"q":"En Utah, un conductor es condenado por primera vez por un delito con agravante de furia al volante (road rage). ¿Qué puede ordenar el tribunal?","o":["Solo una advertencia","Una suspensión de 30 días","Una suspensión de la licencia de un año","Una revocación de por vida"],"h1":"Es un año completo.","h2":"En Utah, el tribunal puede ordenar una suspensión de la licencia de un año en la primera condena con agravante de furia al volante.","p":"Correcto. El tribunal puede suspender la licencia un año."},"ref":{"doc":"UT","page":56}},{"id":"ut-151","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a driver texting while driving causes bodily injury. What kind of offense is it?","o":["An infraction with no fine","A Class C misdemeanor with a $100 maximum fine","A warning","A Class B misdemeanor"],"h1":"It is more serious than a first texting offense with no injury.","h2":"In Utah, texting while driving is a Class B misdemeanor if the driver causes bodily injury or has a previous texting violation.","p":"Right. Causing injury makes it a Class B misdemeanor."},"es":{"q":"En Utah, un conductor que escribe mensajes de texto mientras maneja causa lesiones a alguien. ¿Qué tipo de delito es?","o":["Una infracción sin multa","Un delito menor Clase C con multa máxima de $100","Una advertencia","Un delito menor Clase B"],"h1":"Es más grave que una primera vez sin lesiones.","h2":"En Utah, escribir mensajes al manejar es un delito menor Clase B si el conductor causa lesiones o ya tiene una infracción anterior por esto.","p":"Correcto. Causar lesiones lo hace delito menor Clase B."},"ref":{"doc":"UT","page":59}},{"id":"ut-152","scope":"UT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Utah, a 16-year-old with a provisional license drives home alone from a job at 12:30 a.m. Is this allowed?","o":["No, never after midnight","Yes, driving to or from work is an exception to the night limit","Only with a parent in the car","Only on weekends"],"h1":"Some trips are exceptions to the midnight to 5 a.m. rule.","h2":"In Utah, driving to and from work is one of the exceptions to the midnight to 5 a.m. limit for young provisional drivers.","p":"Right. Driving to or from work is allowed during those hours."},"es":{"q":"En Utah, un joven de 16 años con licencia provisional maneja solo a casa desde su trabajo a las 12:30 a.m. ¿Está permitido?","o":["No, nunca después de medianoche","Sí, ir o volver del trabajo es una excepción al límite de noche","Solo con uno de sus padres en el carro","Solo los fines de semana"],"h1":"Algunos viajes son excepciones a la regla de medianoche a 5 a.m.","h2":"En Utah, ir y volver del trabajo es una de las excepciones al límite de medianoche a 5 a.m. para conductores jóvenes con licencia provisional.","p":"Correcto. Ir o volver del trabajo está permitido en esas horas."},"ref":{"doc":"UT","page":8}},{"id":"ut-153","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, your car breaks down on a desert highway. What does the handbook advise?","o":["Walk to the nearest town right away","Stay with your vehicle unless help is a few minutes' walk away","Hitchhike with the first driver who stops","Leave the car and walk at night when it is cool"],"h1":"Most people are found near their car.","h2":"In Utah, if your vehicle breaks down in the desert, stay with it unless you can reach a visible call box or a building within a few minutes' walk.","p":"Right. Stay with your vehicle in the desert."},"es":{"q":"En Utah, su carro se descompone en una carretera del desierto. ¿Qué aconseja el manual?","o":["Caminar enseguida al pueblo más cercano","Quedarse con su vehículo, a menos que la ayuda esté a pocos minutos caminando","Pedir aventón al primer conductor que pare","Dejar el carro y caminar de noche cuando hace fresco"],"h1":"A la mayoría de las personas las encuentran cerca de su carro.","h2":"En Utah, si su vehículo se descompone en el desierto, quédese con él, a menos que pueda llegar a un teléfono de emergencia visible o a un edificio a pocos minutos caminando.","p":"Correcto. En el desierto, quédese con su vehículo."},"ref":{"doc":"UT","page":57}},{"id":"ut-154","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, how often should you plan to stop for a break on a long trip?","o":["Every 30 minutes","Every five hours","Every two hours","Only when you need gas"],"h1":"It is a short span of time.","h2":"In Utah, plan to stop every two hours on long trips to take a break from driving.","p":"Right. Stop about every two hours."},"es":{"q":"En Utah, ¿cada cuánto debe planear detenerse a descansar en un viaje largo?","o":["Cada 30 minutos","Cada cinco horas","Cada dos horas","Solo cuando necesite gasolina"],"h1":"Es un tiempo corto.","h2":"En Utah, planee detenerse cada dos horas en los viajes largos para descansar de manejar.","p":"Correcto. Deténgase más o menos cada dos horas."},"ref":{"doc":"UT","page":57}},{"id":"ut-155","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, you start to feel tired on the highway. What does the handbook suggest?","o":["Drive faster to get there sooner","Drink coffee and keep driving","Pull off at an exit or rest area and take a 20-minute power nap","Turn the radio up loud"],"h1":"A short nap helps.","h2":"In Utah, if you feel tired, stop driving, pull off at an exit or rest area and take a 20-minute power nap, or find a place to sleep.","p":"Right. Pull off and take a 20-minute nap."},"es":{"q":"En Utah, empieza a sentirse cansado en la carretera. ¿Qué sugiere el manual?","o":["Manejar más rápido para llegar antes","Tomar café y seguir manejando","Salir en una salida o área de descanso y tomar una siesta de 20 minutos","Subir el volumen del radio"],"h1":"Una siesta corta ayuda.","h2":"En Utah, si se siente cansado, deje de manejar, salga en una salida o área de descanso y tome una siesta de 20 minutos, o busque dónde dormir.","p":"Correcto. Salga y tome una siesta de 20 minutos."},"ref":{"doc":"UT","page":58}},{"id":"ut-156","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, what must a court do when a driver is convicted of speeding in a highway construction zone?","o":["Give a warning only","Fine the driver at least twice the regular speeding fine","Add 10 dollars to the fine","Suspend the license for one year"],"h1":"Work zone fines are doubled.","h2":"In Utah, courts must fine a driver who speeds in a highway construction zone at least twice the regular fine for speeding.","p":"Right. Work zone speeding fines are at least doubled."},"es":{"q":"En Utah, ¿qué debe hacer un tribunal cuando un conductor es condenado por exceso de velocidad en una zona de construcción en la carretera?","o":["Dar solo una advertencia","Multar al conductor con por lo menos el doble de la multa regular por velocidad","Agregar 10 dólares a la multa","Suspender la licencia un año"],"h1":"Las multas en zonas de obras se duplican.","h2":"En Utah, los tribunales deben multar a quien maneje con exceso de velocidad en una zona de construcción con por lo menos el doble de la multa regular.","p":"Correcto. Las multas por velocidad en zonas de obras son por lo menos el doble."},"ref":{"doc":"UT","page":59}},{"id":"ut-157","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, you are driving downhill on a narrow mountain road and meet a car coming uphill. Who must yield?","o":["The car going uphill","Whoever is bigger","Whoever honks first","You, the driver going downhill"],"h1":"It is harder for the uphill car to start again.","h2":"In Utah, on a narrow mountain road, a driver going downhill must yield to vehicles going uphill.","p":"Right. Downhill drivers yield to uphill drivers."},"es":{"q":"En Utah, usted maneja cuesta abajo en un camino angosto de montaña y se encuentra con un carro que sube. ¿Quién debe ceder el paso?","o":["El carro que sube","El más grande","El que toque primero el claxon","Usted, el que baja"],"h1":"Al carro que sube le cuesta más volver a arrancar.","h2":"En Utah, en un camino angosto de montaña, el conductor que baja debe ceder el paso a los vehículos que suben.","p":"Correcto. El que baja cede el paso al que sube."},"ref":{"doc":"UT","page":60}},{"id":"ut-158","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, you are on a narrow mountain road and come to a sharp curve where you cannot see ahead. What should you do?","o":["Sound your horn","Speed up to get through quickly","Turn on your high beams in daylight","Move to the center of the road"],"h1":"Let unseen drivers know you are coming.","h2":"In Utah, sound your horn when you approach a sharp curve on a narrow road where your view is blocked.","p":"Right. Sound your horn before a blind curve on a narrow road."},"es":{"q":"En Utah, va por un camino angosto de montaña y llega a una curva cerrada donde no ve lo que viene. ¿Qué debe hacer?","o":["Tocar el claxon","Acelerar para pasar rápido","Prender las luces altas de día","Irse al centro del camino"],"h1":"Avise a los conductores que no puede ver que usted viene.","h2":"En Utah, toque el claxon cuando se acerque a una curva cerrada en un camino angosto donde no tiene buena visibilidad.","p":"Correcto. Toque el claxon antes de una curva ciega en un camino angosto."},"ref":{"doc":"UT","page":60}},{"id":"ut-159","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, you have your high beams on and a car is coming toward you. Before you get within how many feet must you dim them?","o":["100 feet","200 feet","500 feet","2,000 feet"],"h1":"It is about a tenth of a mile.","h2":"In Utah, dim your high beams before you get within 500 feet of an oncoming vehicle.","p":"Right. Dim within 500 feet of oncoming traffic."},"es":{"q":"En Utah, usted lleva las luces altas y viene un carro de frente. ¿Antes de estar a cuántos pies debe bajarlas?","o":["100 pies","200 pies","500 pies","2,000 pies"],"h1":"Es como una décima de milla.","h2":"En Utah, baje las luces altas antes de estar a menos de 500 pies de un vehículo que viene de frente.","p":"Correcto. Bájelas a 500 pies del tráfico de frente."},"ref":{"doc":"UT","page":60}},{"id":"ut-160","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, you are following another car at night. Within how many feet of it must you dim your high beams?","o":["100 feet","300 feet","500 feet","1,000 feet"],"h1":"It is less than the distance for oncoming cars.","h2":"In Utah, dim your high beams when you are within 300 feet of a vehicle you are following.","p":"Right. Dim within 300 feet when following."},"es":{"q":"En Utah, de noche usted va detrás de otro carro. ¿A cuántos pies de él debe bajar las luces altas?","o":["100 pies","300 pies","500 pies","1,000 pies"],"h1":"Es menos que la distancia para los carros de frente.","h2":"En Utah, baje las luces altas cuando esté a menos de 300 pies del vehículo que va adelante.","p":"Correcto. Bájelas a 300 pies cuando va detrás de otro."},"ref":{"doc":"UT","page":60}},{"id":"ut-161","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, besides from sunset to sunrise, when must you use your headlights?","o":["Only in tunnels","Only on freeways","Only when it snows","Any time you cannot see clearly 1,000 feet ahead"],"h1":"Think of fog, smoke or a storm.","h2":"In Utah, use your headlights any time poor light or weather keeps you from seeing people and vehicles 1,000 feet ahead.","p":"Right. Use headlights whenever you cannot see 1,000 feet ahead."},"es":{"q":"En Utah, además de la puesta a la salida del sol, ¿cuándo debe usar las luces delanteras?","o":["Solo en túneles","Solo en autopistas","Solo cuando nieva","Siempre que no pueda ver claramente a 1,000 pies"],"h1":"Piense en niebla, humo o tormenta.","h2":"En Utah, use las luces delanteras siempre que la poca luz o el mal tiempo no le permitan ver personas y vehículos a 1,000 pies.","p":"Correcto. Use las luces siempre que no vea a 1,000 pies."},"ref":{"doc":"UT","page":61}},{"id":"ut-162","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how much should you add to your following distance at night?","o":["At least two seconds","Nothing, it is the same as day","Half a second","Ten seconds"],"h1":"It doubles the basic rule.","h2":"In Utah, increase your following distance at night by at least two seconds.","p":"Right. Add at least two seconds at night."},"es":{"q":"En Utah, ¿cuánto debe aumentar su distancia de seguimiento de noche?","o":["Por lo menos dos segundos","Nada, es igual que de día","Medio segundo","Diez segundos"],"h1":"Duplica la regla básica.","h2":"En Utah, aumente su distancia de seguimiento de noche por lo menos dos segundos.","p":"Correcto. Agregue por lo menos dos segundos de noche."},"ref":{"doc":"UT","page":61}},{"id":"ut-163","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, above what speed may your car start to hydroplane on a wet road?","o":["10 mph","20 mph","35 mph","70 mph"],"h1":"It is lower than many people think.","h2":"In Utah, your car may start to hydroplane at speeds over 35 mph on a wet road.","p":"Right. Hydroplaning can start above 35 mph."},"es":{"q":"En Utah, ¿a partir de qué velocidad puede su carro empezar a hidroplanear en un camino mojado?","o":["10 mph","20 mph","35 mph","70 mph"],"h1":"Es menos de lo que mucha gente cree.","h2":"En Utah, su carro puede empezar a hidroplanear a más de 35 mph en un camino mojado.","p":"Correcto. Puede hidroplanear a más de 35 mph."},"ref":{"doc":"UT","page":61}},{"id":"ut-164","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, two cars come to a narrow, single-lane bridge from opposite sides. Who has the right-of-way?","o":["The bigger vehicle","The first driver to reach the bridge","The driver going north","The faster driver"],"h1":"Take turns.","h2":"In Utah, at a narrow or single-lane bridge, the first driver to reach the bridge has the right-of-way.","p":"Right. The first driver to the bridge goes first."},"es":{"q":"En Utah, dos carros llegan a un puente angosto de un solo carril desde lados opuestos. ¿Quién tiene el derecho de paso?","o":["El vehículo más grande","El primer conductor que llega al puente","El que va hacia el norte","El que va más rápido"],"h1":"Túrnense.","h2":"En Utah, en un puente angosto o de un solo carril, el primer conductor que llega al puente tiene el derecho de paso.","p":"Correcto. El primero que llega al puente pasa primero."},"ref":{"doc":"UT","page":61}},{"id":"ut-165","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, how deep must water be to reach the bottom of most passenger cars and cause a stall or loss of control?","o":["Two feet","One foot","Three inches","Six inches"],"h1":"It is less than you might think.","h2":"In Utah's handbook, six inches of water will reach the bottom of most passenger cars and can cause loss of control or stalling.","p":"Right. Just six inches of water can cause trouble."},"es":{"q":"En Utah, ¿qué tan profunda debe ser el agua para llegar a la parte de abajo de la mayoría de los carros y hacer que se apaguen o pierdan control?","o":["Dos pies","Un pie","Tres pulgadas","Seis pulgadas"],"h1":"Es menos de lo que podría creer.","h2":"Según el manual de Utah, seis pulgadas de agua llegan a la parte de abajo de la mayoría de los carros y pueden causar pérdida de control o que se apaguen.","p":"Correcto. Solo seis pulgadas de agua pueden causar problemas."},"ref":{"doc":"UT","page":58}},{"id":"ut-166","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, your car goes into a lake. About how long will it float on the surface?","o":["30 to 60 seconds","5 to 10 minutes","About an hour","It will not sink"],"h1":"Get out right away.","h2":"In Utah's handbook, a vehicle that enters water floats for only 30 to 60 seconds, so try to get out immediately.","p":"Right. It floats only 30 to 60 seconds."},"es":{"q":"En Utah, su carro cae a un lago. ¿Más o menos cuánto tiempo flotará?","o":["De 30 a 60 segundos","De 5 a 10 minutos","Como una hora","No se hundirá"],"h1":"Salga enseguida.","h2":"Según el manual de Utah, un vehículo que cae al agua flota solo de 30 a 60 segundos, así que trate de salir de inmediato.","p":"Correcto. Flota solo de 30 a 60 segundos."},"ref":{"doc":"UT","page":62}},{"id":"ut-167","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, you are stranded in your car in cold weather. About how long each hour should you run the engine for heat?","o":["The whole time","About 10 minutes","Not at all","About 45 minutes"],"h1":"Keep the exhaust pipe clear and a window open a little.","h2":"In Utah, if you are stranded in the cold, run the engine about 10 minutes each hour for heat, keep the exhaust pipe clear and leave a window open a little.","p":"Right. Run the engine about 10 minutes each hour."},"es":{"q":"En Utah, usted queda atrapado en su carro con mucho frío. ¿Más o menos cuánto tiempo cada hora debe prender el motor para calentarse?","o":["Todo el tiempo","Unos 10 minutos","Nada","Unos 45 minutos"],"h1":"Mantenga libre el tubo de escape y una ventana un poco abierta.","h2":"En Utah, si queda atrapado con frío, prenda el motor unos 10 minutos cada hora para calentarse, mantenga libre el tubo de escape y deje una ventana un poco abierta.","p":"Correcto. Prenda el motor unos 10 minutos cada hora."},"ref":{"doc":"UT","page":63}},{"id":"ut-168","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, what kind of crime is it to fail to stop at the scene of a crash in which someone is injured?","o":["An infraction","A Class C misdemeanor","A third-degree felony","Not a crime if you call later"],"h1":"It is a felony.","h2":"In Utah, failing to stop at the scene of an injury crash is a third-degree felony.","p":"Right. It is a third-degree felony."},"es":{"q":"En Utah, ¿qué tipo de delito es no detenerse en el lugar de un choque donde alguien resultó herido?","o":["Una infracción","Un delito menor Clase C","Un delito grave de tercer grado","No es delito si llama después"],"h1":"Es un delito grave.","h2":"En Utah, no detenerse en el lugar de un choque con heridos es un delito grave de tercer grado.","p":"Correcto. Es un delito grave de tercer grado."},"ref":{"doc":"UT","page":65}},{"id":"ut-169","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, you have a minor crash with only property damage and no one is hurt. What may you do with your car?","o":["Leave the scene if the damage is small","Leave it in the lane until police arrive","Drive home and report it later","Move it out of the travel lanes to a safe nearby spot, and stay there"],"h1":"Clear the lanes, but do not leave.","h2":"In Utah, after a property-damage-only crash, you may move your vehicle out of the travel lanes to a safe nearby place and must remain there until all requirements are met.","p":"Right. Move out of the lanes and stay at the nearby spot."},"es":{"q":"En Utah, tiene un choque leve solo con daños materiales y nadie está herido. ¿Qué puede hacer con su carro?","o":["Irse si el daño es pequeño","Dejarlo en el carril hasta que llegue la policía","Irse a casa y reportarlo después","Sacarlo de los carriles a un lugar seguro cercano y quedarse ahí"],"h1":"Despeje los carriles, pero no se vaya.","h2":"En Utah, después de un choque solo con daños materiales, puede sacar su vehículo de los carriles a un lugar seguro cercano y debe quedarse ahí hasta cumplir todos los requisitos.","p":"Correcto. Salga de los carriles y quédese en el lugar cercano."},"ref":{"doc":"UT","page":65}},{"id":"ut-170","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, your car breaks down on the highway. Where should you put flares or reflective triangles?","o":["Right next to your car","In front of your car only","On top of your car","200 to 300 feet behind your car"],"h1":"Give drivers behind you time to slow down or change lanes.","h2":"In Utah, put emergency flares or triangles 200 to 300 feet behind your vehicle so other drivers have time to react.","p":"Right. Place them 200 to 300 feet behind your car."},"es":{"q":"En Utah, su carro se descompone en la carretera. ¿Dónde debe poner bengalas o triángulos reflectantes?","o":["Justo al lado de su carro","Solo delante de su carro","Encima de su carro","De 200 a 300 pies detrás de su carro"],"h1":"Dé tiempo a los conductores de atrás para frenar o cambiar de carril.","h2":"En Utah, ponga las bengalas o triángulos de emergencia de 200 a 300 pies detrás de su vehículo para que otros conductores tengan tiempo de reaccionar.","p":"Correcto. Póngalos de 200 a 300 pies detrás de su carro."},"ref":{"doc":"UT","page":67}},{"id":"ut-171","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, records show a vehicle owner has no insurance. Within how many days must insurance be bought to keep the registration?","o":["10 days","30 days","90 days","One year"],"h1":"It is about a month.","h2":"In Utah, the DMV must revoke the registration of an uninsured vehicle unless insurance is purchased within 30 days.","p":"Right. Insurance must be bought within 30 days."},"es":{"q":"En Utah, los registros muestran que el dueño de un vehículo no tiene seguro. ¿En cuántos días debe comprar seguro para conservar el registro?","o":["10 días","30 días","90 días","Un año"],"h1":"Es como un mes.","h2":"En Utah, el DMV debe revocar el registro de un vehículo sin seguro a menos que se compre seguro en 30 días.","p":"Correcto. Debe comprar seguro en 30 días."},"ref":{"doc":"UT","page":69}},{"id":"ut-172","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, an officer asks for proof of insurance. How may you show it?","o":["Only with a paper card mailed by the insurer","Only at the police station within 10 days","On paper or electronically on a mobile device","You do not have to show it"],"h1":"Your phone can help.","h2":"In Utah, proof of insurance must be in the vehicle, and you may show it to an officer on paper or electronically on a mobile device.","p":"Right. Paper or electronic proof on a phone both work."},"es":{"q":"En Utah, un oficial le pide prueba de seguro. ¿Cómo puede mostrarla?","o":["Solo con una tarjeta de papel enviada por la aseguradora","Solo en la estación de policía en 10 días","En papel o de forma electrónica en un dispositivo móvil","No tiene que mostrarla"],"h1":"Su teléfono puede ayudar.","h2":"En Utah, la prueba de seguro debe estar en el vehículo, y puede mostrarla al oficial en papel o de forma electrónica en un dispositivo móvil.","p":"Correcto. Sirve en papel o en el teléfono."},"ref":{"doc":"UT","page":69}},{"id":"ut-173","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, you are convicted of driving without insurance. For how long must you carry SR22 proof of insurance?","o":["Three years","Six months","One year","Ten years"],"h1":"You also pay a $40 reinstatement fee.","h2":"In Utah, a conviction for driving without insurance or without proof of insurance requires an SR22 for three years and a $40 reinstatement fee.","p":"Right. You must carry an SR22 for three years."},"es":{"q":"En Utah, lo condenan por manejar sin seguro. ¿Por cuánto tiempo debe tener la prueba de seguro SR22?","o":["Tres años","Seis meses","Un año","Diez años"],"h1":"También paga $40 de restablecimiento.","h2":"En Utah, una condena por manejar sin seguro o sin prueba de seguro exige un SR22 por tres años y una tarifa de restablecimiento de $40.","p":"Correcto. Debe tener un SR22 por tres años."},"ref":{"doc":"UT","page":69}},{"id":"ut-174","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a court orders you to pay damages from a crash. If you do not pay within how many days will your driving privilege be suspended?","o":["10 days","30 days","One year","60 days"],"h1":"It is about two months.","h2":"In Utah, if a court judgment for crash damages is not paid within 60 days, your driving privilege will be suspended.","p":"Right. An unpaid judgment after 60 days leads to suspension."},"es":{"q":"En Utah, un tribunal le ordena pagar los daños de un choque. ¿Si no paga en cuántos días se suspende su privilegio de manejar?","o":["10 días","30 días","Un año","60 días"],"h1":"Son unos dos meses.","h2":"En Utah, si no paga en 60 días una sentencia por daños de un choque, se suspende su privilegio de manejar.","p":"Correcto. Una sentencia sin pagar después de 60 días lleva a la suspensión."},"ref":{"doc":"UT","page":68}},{"id":"ut-175","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, how long do alcohol- and drug-related violations stay on your driving record?","o":["One year","Three years","10 years","Forever"],"h1":"It is longer than the three years for other moving violations.","h2":"In Utah, all alcohol- and drug-related violations, suspensions and revocations stay on your driving record for 10 years.","p":"Right. They stay on the record for 10 years."},"es":{"q":"En Utah, ¿cuánto tiempo quedan en su historial de manejo las infracciones relacionadas con alcohol y drogas?","o":["Un año","Tres años","10 años","Para siempre"],"h1":"Es más que los tres años de otras infracciones de tránsito.","h2":"En Utah, todas las infracciones, suspensiones y revocaciones relacionadas con alcohol y drogas quedan en su historial por 10 años.","p":"Correcto. Quedan en el historial 10 años."},"ref":{"doc":"UT","page":70}},{"id":"ut-176","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, your license was suspended for three months and you are caught driving anyway. What happens to the suspension?","o":["Nothing changes","Another three months is added","It ends early","One week is added"],"h1":"The original time period is added again.","h2":"In Utah, if you drive while suspended, the suspension is increased by the length of the original period, so three months becomes six.","p":"Right. Another three months is added."},"es":{"q":"En Utah, le suspendieron la licencia por tres meses y lo encuentran manejando de todos modos. ¿Qué pasa con la suspensión?","o":["No cambia nada","Se agregan otros tres meses","Termina antes","Se agrega una semana"],"h1":"Se vuelve a sumar el periodo original.","h2":"En Utah, si maneja con la licencia suspendida, la suspensión aumenta por el mismo tiempo del periodo original, así que tres meses se vuelven seis.","p":"Correcto. Se agregan otros tres meses."},"ref":{"doc":"UT","page":70}},{"id":"ut-177","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how many points does a reckless driving conviction add to your record?","o":["80","40","50","200"],"h1":"It is the highest number on the point table.","h2":"In Utah, reckless driving adds 80 points, the most of any violation on the point table.","p":"Right. Reckless driving is 80 points."},"es":{"q":"En Utah, ¿cuántos puntos agrega a su historial una condena por manejo imprudente (reckless driving)?","o":["80","40","50","200"],"h1":"Es el número más alto de la tabla de puntos.","h2":"En Utah, el manejo imprudente agrega 80 puntos, la mayor cantidad de la tabla de puntos.","p":"Correcto. El manejo imprudente son 80 puntos."},"ref":{"doc":"UT","page":72}},{"id":"ut-178","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, how many points are given for following too closely (tailgating)?","o":["20","40","80","60"],"h1":"It is the same as failing to yield the right-of-way.","h2":"In Utah, following too closely adds 60 points, the same as failing to yield the right-of-way.","p":"Right. Tailgating is 60 points."},"es":{"q":"En Utah, ¿cuántos puntos se dan por seguir demasiado cerca a otro vehículo?","o":["20","40","80","60"],"h1":"Es lo mismo que no ceder el derecho de paso.","h2":"En Utah, seguir demasiado cerca agrega 60 puntos, lo mismo que no ceder el derecho de paso.","p":"Correcto. Seguir demasiado cerca son 60 puntos."},"ref":{"doc":"UT","page":72}},{"id":"ut-179","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, how many points can a driver 21 or older get within three years before being called to a hearing?","o":["70 points","200 points","100 points","500 points"],"h1":"It is much higher than the 70-point limit for drivers under 21.","h2":"In Utah, a driver over 21 who gets 200 or more points within three years is asked to appear for a hearing.","p":"Right. Drivers over 21 face a hearing at 200 points."},"es":{"q":"En Utah, ¿cuántos puntos en tres años llevan a un conductor de 21 años o más a una audiencia?","o":["70 puntos","200 puntos","100 puntos","500 puntos"],"h1":"Es mucho más que el límite de 70 puntos para menores de 21.","h2":"En Utah, un conductor mayor de 21 años que acumula 200 puntos o más en tres años debe presentarse a una audiencia.","p":"Correcto. Los mayores de 21 van a audiencia con 200 puntos."},"ref":{"doc":"UT","page":72}},{"id":"ut-180","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, you drive one full year without a moving violation conviction. What happens to the points on your record?","o":["Nothing","10 points are removed","Half of the points are removed","All points are removed"],"h1":"Two clean years remove all of them.","h2":"In Utah, half of the points on your record are removed when you drive one full year without a moving violation conviction.","p":"Right. One clean year removes half your points."},"es":{"q":"En Utah, usted maneja un año completo sin condenas por infracciones de tránsito. ¿Qué pasa con los puntos de su historial?","o":["Nada","Se quitan 10 puntos","Se quita la mitad de los puntos","Se quitan todos los puntos"],"h1":"Dos años sin infracciones quitan todos.","h2":"En Utah, se quita la mitad de los puntos de su historial cuando maneja un año completo sin condenas por infracciones de tránsito.","p":"Correcto. Un año sin infracciones quita la mitad de los puntos."},"ref":{"doc":"UT","page":73}},{"id":"ut-181","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, how often may you use the 50-point reduction from a division-recommended defensive driving course?","o":["Only once in any three-year period","Once a year","Every six months","As often as you take the course"],"h1":"It is the same span of time that points stay on your record.","h2":"In Utah, the 50-point reduction for a defensive driving course is allowed only once during any three-year period.","p":"Right. Only once every three years."},"es":{"q":"En Utah, ¿cada cuánto puede usar la reducción de 50 puntos por un curso de manejo defensivo recomendado por la división?","o":["Solo una vez en cualquier periodo de tres años","Una vez al año","Cada seis meses","Cada vez que tome el curso"],"h1":"Es el mismo tiempo que los puntos quedan en su historial.","h2":"En Utah, la reducción de 50 puntos por un curso de manejo defensivo se permite solo una vez en cualquier periodo de tres años.","p":"Correcto. Solo una vez cada tres años."},"ref":{"doc":"UT","page":73}},{"id":"ut-182","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, a bicyclist is going slowly on a road with a two-way center left-turn lane. May you use that center lane to pass?","o":["No, never","Only if you honk first","Yes, the handbook allows driving in the center lane to pass a slow bicyclist","Only at night"],"h1":"The center lane can help you give the rider room.","h2":"In Utah, if a bicyclist is moving at less than a reasonable speed, you may drive in a two-way center left-turn lane to pass.","p":"Right. You may use the center lane to pass a slow bicyclist."},"es":{"q":"En Utah, un ciclista va despacio en una calle con carril central de vuelta a la izquierda en ambos sentidos. ¿Puede usar ese carril central para rebasarlo?","o":["No, nunca","Solo si toca el claxon primero","Sí, el manual permite usar el carril central para rebasar a un ciclista lento","Solo de noche"],"h1":"El carril central puede ayudarle a darle espacio al ciclista.","h2":"En Utah, si un ciclista va a menos de una velocidad razonable, usted puede manejar por el carril central de vuelta a la izquierda para rebasarlo.","p":"Correcto. Puede usar el carril central para rebasar a un ciclista lento."},"ref":{"doc":"UT","page":75}},{"id":"ut-183","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, unless a traffic sign allows it, you may not pass a bicycle going your way when you are within how many feet of an intersection or railroad crossing?","o":["100 feet","25 feet","500 feet","1,000 feet"],"h1":"It is about the length of a few houses.","h2":"In Utah, you may not pass a bicycle or moped going the same way within 100 feet of an intersection or railroad grade crossing, unless a traffic control device allows it.","p":"Right. Do not pass a bicycle within 100 feet of an intersection or crossing."},"es":{"q":"En Utah, si no hay una señal que lo permita, no puede rebasar a una bicicleta que va en su misma dirección cuando está a menos de cuántos pies de un cruce o de un cruce de tren?","o":["100 pies","25 pies","500 pies","1,000 pies"],"h1":"Es como el largo de unas cuantas casas.","h2":"En Utah, no puede rebasar a una bicicleta o motoneta que va en su misma dirección a menos de 100 pies de un cruce o de un cruce de tren, a menos que una señal lo permita.","p":"Correcto. No rebase a una bicicleta a menos de 100 pies de un cruce."},"ref":{"doc":"UT","page":75}},{"id":"ut-184","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, a bicycle's brakes must be able to stop it within what distance from a speed of 10 mph?","o":["5 feet","50 feet","100 feet","25 feet"],"h1":"It is less than the length of two cars.","h2":"In Utah, every bicycle must have brakes that can stop it within 25 feet from a speed of 10 mph.","p":"Right. A bicycle must stop within 25 feet from 10 mph."},"es":{"q":"En Utah, ¿en qué distancia deben poder detener los frenos de una bicicleta desde una velocidad de 10 mph?","o":["5 pies","50 pies","100 pies","25 pies"],"h1":"Es menos que el largo de dos carros.","h2":"En Utah, toda bicicleta debe tener frenos que la detengan en 25 pies desde una velocidad de 10 mph.","p":"Correcto. Una bicicleta debe detenerse en 25 pies desde 10 mph."},"ref":{"doc":"UT","page":76}},{"id":"ut-185","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, a bicyclist rides after dark. From how far away must the white headlight, red taillight or reflector, and side reflectors be visible?","o":["50 feet","500 feet","100 feet","1 mile"],"h1":"It is the same distance as many car lights.","h2":"In Utah, a bicycle ridden at night needs a white headlight, a red taillight or reflector and side reflectors, all visible for at least 500 feet.","p":"Right. Bicycle lights and reflectors must be visible for 500 feet."},"es":{"q":"En Utah, un ciclista anda de noche. ¿Desde qué distancia deben verse la luz blanca delantera, la luz o reflector rojo trasero y los reflectores laterales?","o":["50 pies","500 pies","100 pies","1 milla"],"h1":"Es la misma distancia que muchas luces de carro.","h2":"En Utah, una bicicleta de noche necesita luz blanca delantera, luz o reflector rojo trasero y reflectores laterales, todos visibles por lo menos a 500 pies.","p":"Correcto. Las luces y reflectores de la bicicleta deben verse a 500 pies."},"ref":{"doc":"UT","page":76}},{"id":"ut-186","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, who may not ride a Class 3 electric-assisted bicycle (assist up to 28 mph while pedaling)?","o":["Anyone over 65","Anyone without a car license","Anyone under 16","Anyone under 21"],"h1":"It is the age when many teens start driving.","h2":"In Utah, a person under 16 years old may not operate a Class 3 electric-assisted bicycle.","p":"Right. Riders under 16 may not use a Class 3 e-bike."},"es":{"q":"En Utah, ¿quién no puede usar una bicicleta eléctrica Clase 3 (ayuda hasta 28 mph al pedalear)?","o":["Mayores de 65 años","Quien no tenga licencia de carro","Menores de 16 años","Menores de 21 años"],"h1":"Es la edad en que muchos jóvenes empiezan a manejar.","h2":"En Utah, una persona menor de 16 años no puede usar una bicicleta eléctrica Clase 3.","p":"Correcto. Los menores de 16 no pueden usar una bicicleta eléctrica Clase 3."},"ref":{"doc":"UT","page":77}},{"id":"ut-187","scope":"UT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Utah, a fire truck has stopped to answer an alarm. Where may you not drive or park?","o":["Anywhere in the same city","On the same block where the fire truck stopped","Within 5 feet of it only","There is no rule"],"h1":"Give firefighters the whole block.","h2":"In Utah, you may not drive or park on the same block where a fire vehicle has stopped to answer an alarm.","p":"Right. Stay off the block where the fire truck stopped."},"es":{"q":"En Utah, un camión de bomberos se detuvo para atender una alarma. ¿Dónde no puede manejar ni estacionarse?","o":["En ninguna parte de la misma ciudad","En la misma cuadra donde se detuvo el camión de bomberos","Solo a menos de 5 pies de él","No hay regla"],"h1":"Deje toda la cuadra a los bomberos.","h2":"En Utah, no puede manejar ni estacionarse en la misma cuadra donde un vehículo de bomberos se detuvo para atender una alarma.","p":"Correcto. No entre a la cuadra donde se detuvo el camión de bomberos."},"ref":{"doc":"UT","page":77}},{"id":"ut-188","scope":"UT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Utah, you are in the HOV lane and see a stopped vehicle ahead showing amber lights. What should you do if it is safe?","o":["Stay in the HOV lane and speed up","Stop in the HOV lane","Turn on your high beams","Move out of the HOV lane into a lane not next to the stopped vehicle"],"h1":"The move-over law applies in the HOV lane too.","h2":"In Utah, a driver in the HOV lane approaching a stopped vehicle with amber lights should, if practical and safe, change lanes out of the HOV lane into a lane not next to it.","p":"Right. Move out of the HOV lane, away from the stopped vehicle."},"es":{"q":"En Utah, usted va en el carril HOV y ve adelante un vehículo detenido con luces ámbar. ¿Qué debe hacer si es seguro?","o":["Seguir en el carril HOV y acelerar","Detenerse en el carril HOV","Prender las luces altas","Salir del carril HOV a un carril que no esté junto al vehículo detenido"],"h1":"La ley de moverse a otro carril también aplica en el carril HOV.","h2":"En Utah, un conductor en el carril HOV que se acerca a un vehículo detenido con luces ámbar debe, si es práctico y seguro, salir del carril HOV a un carril que no esté junto a él.","p":"Correcto. Salga del carril HOV, lejos del vehículo detenido."},"ref":{"doc":"UT","page":77}},{"id":"ut-189","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah's handbook, how far behind a large truck can its rear blind spot reach?","o":["Up to 200 feet","Up to 10 feet","Up to 50 feet","There is no rear blind spot"],"h1":"It is much longer than the truck itself.","h2":"In Utah's handbook, a large truck's rear blind spot can reach up to 200 feet behind it.","p":"Right. The rear blind spot can reach 200 feet."},"es":{"q":"Según el manual de Utah, ¿hasta qué distancia detrás de un camión grande llega su punto ciego trasero?","o":["Hasta 200 pies","Hasta 10 pies","Hasta 50 pies","No tiene punto ciego trasero"],"h1":"Es mucho más largo que el camión mismo.","h2":"Según el manual de Utah, el punto ciego trasero de un camión grande puede llegar hasta 200 pies detrás de él.","p":"Correcto. El punto ciego trasero puede llegar a 200 pies."},"ref":{"doc":"UT","page":80}},{"id":"ut-190","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, on which side does a large truck have its biggest blind spot?","o":["The left side","Directly in front","The right side, from behind the cab along the trailer","On top of the cab"],"h1":"It is the side opposite the driver.","h2":"In Utah, a truck's largest blind spot is on the right side, starting behind the cab and running the length of the truck.","p":"Right. The biggest blind spot is on the right side."},"es":{"q":"En Utah, ¿de qué lado tiene un camión grande su punto ciego más grande?","o":["Del lado izquierdo","Justo enfrente","Del lado derecho, desde detrás de la cabina a lo largo del remolque","Encima de la cabina"],"h1":"Es el lado contrario al conductor.","h2":"En Utah, el punto ciego más grande de un camión está del lado derecho, empieza detrás de la cabina y sigue a lo largo del camión.","p":"Correcto. El punto ciego más grande está del lado derecho."},"ref":{"doc":"UT","page":80}},{"id":"ut-191","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, when a motorcycle lane filters between stopped cars, how fast may the motorcycle go?","o":["25 mph or less","15 mph or less","45 mph or less","Any speed if safe"],"h1":"It is a walking-to-jogging pace for a motorcycle.","h2":"In Utah, lane filtering is allowed only when the motorcycle travels 15 mph or less past stopped vehicles, on a road with a limit of 45 mph or less.","p":"Right. Filtering motorcycles may go 15 mph or less."},"es":{"q":"En Utah, cuando una motocicleta pasa entre carros detenidos en el mismo carril (lane filtering), ¿a qué velocidad puede ir?","o":["25 mph o menos","15 mph o menos","45 mph o menos","A cualquier velocidad si es seguro"],"h1":"Es un paso lento para una motocicleta.","h2":"En Utah, el lane filtering se permite solo si la motocicleta va a 15 mph o menos junto a vehículos detenidos, en una calle con límite de 45 mph o menos.","p":"Correcto. La motocicleta puede ir a 15 mph o menos."},"ref":{"doc":"UT","page":82}},{"id":"ut-192","scope":"UT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Utah, you stopped for a pedestrian crossing the street. How long must you stay stopped?","o":["Until the pedestrian has crossed at least your half of the road","Until the pedestrian takes one step","For five seconds","Until the light turns green"],"h1":"Think about your side of the road.","h2":"In Utah, you must remain stopped until the pedestrian has crossed at least your half of the road.","p":"Right. Stay stopped until they have crossed your half of the road."},"es":{"q":"En Utah, usted se detuvo por un peatón que cruza la calle. ¿Hasta cuándo debe seguir detenido?","o":["Hasta que el peatón haya cruzado por lo menos su mitad de la calle","Hasta que el peatón dé un paso","Por cinco segundos","Hasta que el semáforo se ponga verde"],"h1":"Piense en su lado de la calle.","h2":"En Utah, debe seguir detenido hasta que el peatón haya cruzado por lo menos su mitad de la calle.","p":"Correcto. Siga detenido hasta que cruce su mitad de la calle."},"ref":{"doc":"UT","page":82}},{"id":"ut-193","scope":"UT","cat":"signs","sign":null,"c":3,"en":{"q":"In Utah, an orange and red triangle is on the back of a vehicle ahead. What does it tell you?","o":["The vehicle carries explosives","The driver is a student","The vehicle is about to turn","The vehicle moves at less than 25 mph"],"h1":"You often see it on farm equipment.","h2":"In Utah, a reflective orange and red triangle on the rear of a vehicle means it moves at less than 25 mph.","p":"Right. It marks a vehicle going under 25 mph."},"es":{"q":"En Utah, hay un triángulo anaranjado y rojo en la parte de atrás de un vehículo adelante. ¿Qué le indica?","o":["Que lleva explosivos","Que el conductor es estudiante","Que va a dar vuelta","Que el vehículo va a menos de 25 mph"],"h1":"Se ve mucho en maquinaria agrícola.","h2":"En Utah, un triángulo reflectante anaranjado y rojo atrás de un vehículo significa que va a menos de 25 mph.","p":"Correcto. Marca un vehículo que va a menos de 25 mph."},"ref":{"doc":"UT","page":84}},{"id":"ut-194","scope":"UT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Utah, you stopped at a railroad crossing and think the flashing lights are broken. When may you cross?","o":["After waiting one minute","Whenever you see no train nearby","Only if you can see at least one mile down the tracks both ways, no train is coming, and it is safe","Never, you must turn around"],"h1":"You need a very long clear view.","h2":"In Utah, if you suspect crossing lights are not working, after stopping you may cross only with a clear view of at least one mile both ways, no sign of a train, and a safe path.","p":"Right. You need a one-mile clear view both ways."},"es":{"q":"En Utah, usted se detuvo en un cruce de tren y cree que las luces intermitentes están descompuestas. ¿Cuándo puede cruzar?","o":["Después de esperar un minuto","Cuando no vea un tren cerca","Solo si puede ver por lo menos una milla de vías en ambas direcciones, no viene tren y es seguro","Nunca, debe dar la vuelta"],"h1":"Necesita una vista despejada muy larga.","h2":"En Utah, si cree que las luces del cruce no funcionan, después de detenerse puede cruzar solo con una vista despejada de por lo menos una milla en ambas direcciones, sin señal de tren y con paso seguro.","p":"Correcto. Necesita ver una milla despejada en ambas direcciones."},"ref":{"doc":"UT","page":86}},{"id":"ut-195","scope":"UT","cat":"signs","sign":null,"c":3,"en":{"q":"In Utah, an overhead sign near a TRAX light rail line flashes a train symbol. What does it mean?","o":["Trains are not running today","You must stop right now","The tracks are closed","A train is approaching; pay extra attention to the signals"],"h1":"It is a warning, not a stop signal.","h2":"In Utah, a flashing train logo means a light rail train is coming; it is an extra warning to obey the signals, not a signal to stop.","p":"Right. It warns that a train is approaching."},"es":{"q":"En Utah, un letrero elevado cerca de una línea de tren ligero TRAX muestra un tren que parpadea. ¿Qué significa?","o":["Hoy no hay trenes","Debe detenerse en ese momento","Las vías están cerradas","Se acerca un tren; ponga más atención a los semáforos"],"h1":"Es una advertencia, no una señal de alto.","h2":"En Utah, el símbolo de tren que parpadea significa que viene un tren ligero; es una advertencia extra para obedecer los semáforos, no una señal para detenerse.","p":"Correcto. Avisa que se acerca un tren."},"ref":{"doc":"UT","page":89}},{"id":"ut-196","scope":"UT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Utah, from how far away must your car's horn be heard under normal conditions?","o":["50 feet","200 feet","1,000 feet","1 mile"],"h1":"It is about the length of 12 cars.","h2":"In Utah, every motor vehicle must have a working horn that can be heard from at least 200 feet under normal conditions.","p":"Right. A horn must be heard from 200 feet."},"es":{"q":"En Utah, ¿desde qué distancia se debe oír el claxon de su carro en condiciones normales?","o":["50 pies","200 pies","1,000 pies","1 milla"],"h1":"Es como el largo de 12 carros.","h2":"En Utah, todo vehículo debe tener un claxon que funcione y que se oiga por lo menos a 200 pies en condiciones normales.","p":"Correcto. El claxon se debe oír a 200 pies."},"ref":{"doc":"UT","page":91}},{"id":"ut-197","scope":"UT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Utah, how far must headlights shine on high beam and on low beam?","o":["100 feet high and 50 feet low","1,000 feet high and 500 feet low","500 feet both","350 feet high and 100 feet low"],"h1":"High beams reach more than three times as far as low beams.","h2":"In Utah, headlights must be white and shine 350 feet on high beam and 100 feet on low beam.","p":"Right. 350 feet on high and 100 feet on low."},"es":{"q":"En Utah, ¿qué tan lejos deben alumbrar las luces delanteras en luz alta y en luz baja?","o":["100 pies alta y 50 pies baja","1,000 pies alta y 500 pies baja","500 pies las dos","350 pies alta y 100 pies baja"],"h1":"La luz alta llega más de tres veces más lejos que la baja.","h2":"En Utah, las luces delanteras deben ser blancas y alumbrar 350 pies en luz alta y 100 pies en luz baja.","p":"Correcto. 350 pies en alta y 100 pies en baja."},"ref":{"doc":"UT","page":91}},{"id":"ut-198","scope":"UT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Utah, you carry a load in your passenger car. How far may it stick out past the fenders on the left side?","o":["6 inches","1 foot","Not at all","3 feet"],"h1":"The left side is next to oncoming traffic.","h2":"In Utah, no vehicle may carry a load extending beyond the fenders on the left side; on the right side it may extend up to 6 inches.","p":"Right. Nothing may stick out past the left fenders."},"es":{"q":"En Utah, lleva una carga en su carro de pasajeros. ¿Cuánto puede sobresalir de las salpicaderas del lado izquierdo?","o":["6 pulgadas","1 pie","Nada","3 pies"],"h1":"El lado izquierdo está junto al tráfico de frente.","h2":"En Utah, ningún vehículo puede llevar carga que sobresalga de las salpicaderas del lado izquierdo; del lado derecho puede sobresalir hasta 6 pulgadas.","p":"Correcto. Nada puede sobresalir del lado izquierdo."},"ref":{"doc":"UT","page":79}},{"id":"ut-199","scope":"UT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Utah, you are towing another vehicle. How long may the drawbar or other connection between them be?","o":["No more than 15 feet","No more than 5 feet","No more than 30 feet","Any length"],"h1":"It is about the length of one car.","h2":"In Utah, the drawbar or other connection between a towing vehicle and the towed vehicle may not be longer than 15 feet.","p":"Right. The connection may be no more than 15 feet."},"es":{"q":"En Utah, usted remolca otro vehículo. ¿Qué tan larga puede ser la barra u otra conexión entre ellos?","o":["No más de 15 pies","No más de 5 pies","No más de 30 pies","De cualquier largo"],"h1":"Es como el largo de un carro.","h2":"En Utah, la barra u otra conexión entre el vehículo que remolca y el remolcado no puede medir más de 15 pies.","p":"Correcto. La conexión puede medir no más de 15 pies."},"ref":{"doc":"UT","page":93}},{"id":"ut-200","scope":"UT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Utah, what is the top speed for a street-legal ATV or UTV on a highway?","o":["25 mph","The posted limit or 50 mph, whichever is lower","65 mph","The posted limit, whatever it is"],"h1":"There is a cap even where the posted limit is higher.","h2":"In Utah, a street-legal ATV, UTV or full-size all-terrain vehicle may not go faster than the posted limit or 50 mph, whichever is lower.","p":"Right. The lower of the posted limit or 50 mph."},"es":{"q":"En Utah, ¿cuál es la velocidad máxima de un ATV o UTV legal para la calle en una carretera?","o":["25 mph","El límite señalado o 50 mph, lo que sea menor","65 mph","El límite señalado, sea cual sea"],"h1":"Hay un tope aunque el límite señalado sea mayor.","h2":"En Utah, un ATV, UTV o vehículo todo terreno de tamaño completo legal para la calle no puede ir más rápido que el límite señalado o 50 mph, lo que sea menor.","p":"Correcto. El menor entre el límite señalado y 50 mph."},"ref":{"doc":"UT","page":86}},{"id":"va-001","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 years and 6 months","16 years old"],"h1":"It is halfway between two birthdays.","h2":"In Virginia you can get a learner's permit when you are at least 15 years and 6 months old.","p":"Right. The Virginia permit starts at 15 and a half."},"es":{"q":"En Virginia, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y 6 meses","16 años"],"h1":"Está a mitad de camino entre dos cumpleaños.","h2":"En Virginia usted puede obtener un permiso de aprendiz cuando tiene por lo menos 15 años y 6 meses.","p":"Correcto. El permiso en Virginia empieza a los 15 años y medio."},"zh":{"q":"在 Virginia，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","15 岁 6 个月","16 岁"],"h1":"它在两个生日的正中间。","h2":"在 Virginia，你至少 15 岁 6 个月时就可以拿到学习驾照。","p":"对。Virginia 的学习驾照从 15 岁半开始。"},"vi":{"q":"Ở Virginia, tuổi nhỏ nhất để lấy giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi 6 tháng","16 tuổi"],"h1":"Đó là khoảng giữa hai ngày sinh nhật.","h2":"Ở Virginia, bạn có thể lấy giấy phép tập lái khi được ít nhất 15 tuổi 6 tháng.","p":"Đúng. Ở Virginia, giấy phép tập lái bắt đầu từ 15 tuổi rưỡi."},"tl":{"q":"Sa Virginia, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","15 taon at 6 na buwan","16 taong gulang"],"h1":"Nasa gitna ito ng dalawang kaarawan.","h2":"Sa Virginia, puwede kang kumuha ng learner's permit kapag ikaw ay hindi bababa sa 15 taon at 6 na buwang gulang.","p":"Tama. Nagsisimula ang permit sa Virginia sa 15 at kalahati."},"ar":{"q":"في Virginia، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","15 سنة و6 أشهر","16 سنة"],"h1":"هو في منتصف المسافة بين عيدَي ميلاد.","h2":"في Virginia يمكنك الحصول على تصريح التعلّم عندما يكون عمرك 15 سنة و6 أشهر على الأقل.","p":"صحيح. في Virginia يبدأ التصريح في عمر 15 سنة ونصف."},"ref":{"doc":"VA","page":null}},{"id":"va-002","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how long must a teen hold a learner's permit before getting a license?","o":["6 months","9 months","12 months","3 months"],"h1":"It is three quarters of a year.","h2":"A Virginia teen must hold the learner's permit for at least nine months before getting a driver's license.","p":"Right. The permit is held for nine months."},"es":{"q":"En Virginia, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia?","o":["6 meses","9 meses","12 meses","3 meses"],"h1":"Son tres cuartas partes de un año.","h2":"En Virginia, un adolescente debe tener el permiso de aprendiz por lo menos nueve meses antes de obtener la licencia de manejar.","p":"Correcto. El permiso se tiene nueve meses."},"zh":{"q":"在 Virginia，青少年拿到学习驾照后，至少要持有多久才能拿驾照？","o":["6 个月","9 个月","12 个月","3 个月"],"h1":"它是一年的四分之三。","h2":"Virginia 的青少年必须持有学习驾照至少 9 个月，才能拿到驾照。","p":"对。学习驾照要持有 9 个月。"},"vi":{"q":"Ở Virginia, thanh thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái?","o":["6 tháng","9 tháng","12 tháng","3 tháng"],"h1":"Đó là ba phần tư của một năm.","h2":"Thanh thiếu niên ở Virginia phải giữ giấy phép tập lái ít nhất 9 tháng trước khi lấy bằng lái.","p":"Đúng. Giấy phép tập lái được giữ 9 tháng."},"tl":{"q":"Sa Virginia, gaano katagal dapat hawak ng isang teen ang learner's permit bago kumuha ng lisensya?","o":["6 na buwan","9 na buwan","12 buwan","3 buwan"],"h1":"Tatlong-kapat ito ng isang taon.","h2":"Ang teen sa Virginia ay dapat humawak ng learner's permit nang hindi bababa sa 9 na buwan bago makakuha ng driver's license.","p":"Tama. Hawak ang permit nang 9 na buwan."},"ar":{"q":"في Virginia، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة؟","o":["6 أشهر","9 أشهر","12 شهرًا","3 أشهر"],"h1":"هي ثلاثة أرباع السنة.","h2":"يجب أن يحمل المراهق في Virginia تصريح التعلّم 9 أشهر على الأقل قبل الحصول على رخصة القيادة.","p":"صحيح. يُحمل التصريح 9 أشهر."},"ref":{"doc":"VA","page":null}},{"id":"va-003","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, how many hours of supervised driving must a teen complete before getting a license?","o":["20 hours","30 hours","50 hours","45 hours"],"h1":"It is a little less than 50.","h2":"A Virginia teen must complete at least 45 hours of supervised driving practice before getting a license.","p":"Right. Virginia asks for 45 supervised hours."},"es":{"q":"En Virginia, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de obtener la licencia?","o":["20 horas","30 horas","50 horas","45 horas"],"h1":"Es un poco menos de 50.","h2":"En Virginia, un adolescente debe completar por lo menos 45 horas de práctica de manejo supervisado antes de obtener la licencia.","p":"Correcto. Virginia pide 45 horas supervisadas."},"zh":{"q":"在 Virginia，青少年拿驾照前，必须完成多少小时有人陪同的驾驶练习？","o":["20 小时","30 小时","50 小时","45 小时"],"h1":"它比 50 少一点。","h2":"Virginia 的青少年拿驾照前，必须完成至少 45 小时有人陪同的驾驶练习。","p":"对。Virginia 要求 45 小时有人陪同的练习。"},"vi":{"q":"Ở Virginia, thanh thiếu niên phải lái bao nhiêu giờ có người giám sát trước khi lấy bằng lái?","o":["20 giờ","30 giờ","50 giờ","45 giờ"],"h1":"Con số này ít hơn 50 một chút.","h2":"Thanh thiếu niên ở Virginia phải tập lái có người giám sát ít nhất 45 giờ trước khi lấy bằng lái.","p":"Đúng. Virginia yêu cầu 45 giờ có người giám sát."},"tl":{"q":"Sa Virginia, ilang oras ng pagmamaneho na may gumagabay ang dapat tapusin ng teen bago kumuha ng lisensya?","o":["20 oras","30 oras","50 oras","45 oras"],"h1":"Medyo mas mababa ito sa 50.","h2":"Ang teen sa Virginia ay dapat tumapos ng hindi bababa sa 45 oras ng pagsasanay sa pagmamaneho na may gumagabay bago kumuha ng lisensya.","p":"Tama. 45 oras na may gumagabay ang hinihingi ng Virginia."},"ar":{"q":"في Virginia، كم ساعة من القيادة تحت الإشراف يجب أن يكملها المراهق قبل الحصول على الرخصة؟","o":["20 ساعة","30 ساعة","50 ساعة","45 ساعة"],"h1":"هو أقل من 50 بقليل.","h2":"يجب أن يكمل المراهق في Virginia 45 ساعة على الأقل من التدريب على القيادة تحت الإشراف قبل الحصول على الرخصة.","p":"صحيح. تطلب Virginia 45 ساعة تحت الإشراف."},"ref":{"doc":"VA","page":null}},{"id":"va-004","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 45 supervised hours must be driven at night?","o":["15 hours","5 hours","10 hours","20 hours"],"h1":"It is one third of the total.","h2":"Of the 45 supervised hours in Virginia, at least 15 must be driven at night, so the teen practices in the dark.","p":"Right. 15 of the 45 hours are at night."},"es":{"q":"En Virginia, ¿cuántas de las 45 horas supervisadas deben ser de noche?","o":["15 horas","5 horas","10 horas","20 horas"],"h1":"Es una tercera parte del total.","h2":"De las 45 horas supervisadas en Virginia, por lo menos 15 deben ser de noche, para que el adolescente practique en la oscuridad.","p":"Correcto. 15 de las 45 horas son de noche."},"zh":{"q":"在 Virginia，这 45 小时有人陪同的练习中，有多少小时必须在晚上开？","o":["15 小时","5 小时","10 小时","20 小时"],"h1":"它是总数的三分之一。","h2":"在 Virginia 的 45 小时有人陪同练习中，至少 15 小时必须在晚上开，这样青少年可以练习在黑暗中开车。","p":"对。45 小时中有 15 小时在晚上。"},"vi":{"q":"Ở Virginia, trong 45 giờ có người giám sát, bao nhiêu giờ phải lái vào ban đêm?","o":["15 giờ","5 giờ","10 giờ","20 giờ"],"h1":"Đó là một phần ba của tổng số.","h2":"Trong 45 giờ có người giám sát ở Virginia, ít nhất 15 giờ phải lái vào ban đêm, để thanh thiếu niên tập lái trong bóng tối.","p":"Đúng. 15 trong 45 giờ là vào ban đêm."},"tl":{"q":"Sa Virginia, ilan sa 45 oras na may gumagabay ang dapat gawin sa gabi?","o":["15 oras","5 oras","10 oras","20 oras"],"h1":"Isang-katlo ito ng kabuuan.","h2":"Sa 45 oras na may gumagabay sa Virginia, hindi bababa sa 15 ang dapat gawin sa gabi, para masanay ang teen na magmaneho sa dilim.","p":"Tama. 15 sa 45 oras ay sa gabi."},"ar":{"q":"في Virginia، كم ساعة من الـ45 ساعة تحت الإشراف يجب أن تكون في الليل؟","o":["15 ساعة","5 ساعات","10 ساعات","20 ساعة"],"h1":"هي ثلث المجموع.","h2":"من الـ45 ساعة تحت الإشراف في Virginia، يجب أن تكون 15 ساعة على الأقل في الليل، حتى يتدرّب المراهق على القيادة في الظلام.","p":"صحيح. 15 ساعة من الـ45 تكون في الليل."},"ref":{"doc":"VA","page":null}},{"id":"va-005","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, how old must the licensed driver beside a learner usually be?","o":["At least 16","At least 18","At least 21","At least 25"],"h1":"A legal guardian or a brother or sister may be younger than the usual age.","h2":"A Virginia learner must drive with a licensed driver seated beside them who is at least 21, or with a parent, a legal guardian, or a brother or sister who is at least 18.","p":"Right. The supervisor is usually 21 or older."},"es":{"q":"En Virginia, ¿qué edad debe tener normalmente el conductor con licencia que va al lado del aprendiz?","o":["Por lo menos 16","Por lo menos 18","Por lo menos 21","Por lo menos 25"],"h1":"Un tutor legal o un hermano puede ser menor que la edad habitual.","h2":"En Virginia, el aprendiz debe manejar con un conductor con licencia sentado a su lado que tenga por lo menos 21 años, o con su padre o madre, su tutor legal, o un hermano o hermana de por lo menos 18 años.","p":"Correcto. El supervisor normalmente tiene 21 años o más."},"zh":{"q":"在 Virginia，坐在学车人旁边的持照司机通常至少要几岁？","o":["至少 16 岁","至少 18 岁","至少 21 岁","至少 25 岁"],"h1":"法定监护人或兄弟姐妹可以比通常的年龄小。","h2":"Virginia 的学车人必须由坐在旁边、至少 21 岁的持照司机陪同，或由至少 18 岁的父母、法定监护人或兄弟姐妹陪同。","p":"对。陪同的人通常要 21 岁或以上。"},"vi":{"q":"Ở Virginia, người có bằng lái ngồi cạnh người tập lái thường phải bao nhiêu tuổi?","o":["Ít nhất 16 tuổi","Ít nhất 18 tuổi","Ít nhất 21 tuổi","Ít nhất 25 tuổi"],"h1":"Người giám hộ hợp pháp hoặc anh chị em có thể nhỏ tuổi hơn mức thường lệ.","h2":"Người tập lái ở Virginia phải lái cùng một người có bằng lái ngồi bên cạnh, ít nhất 21 tuổi, hoặc cùng cha mẹ, người giám hộ hợp pháp, hay anh chị em ít nhất 18 tuổi.","p":"Đúng. Người giám sát thường từ 21 tuổi trở lên."},"tl":{"q":"Sa Virginia, karaniwang ilang taon dapat ang may lisensyang driver na katabi ng nag-aaral magmaneho?","o":["Hindi bababa sa 16","Hindi bababa sa 18","Hindi bababa sa 21","Hindi bababa sa 25"],"h1":"Ang legal na tagapag-alaga o kapatid ay puwedeng mas bata sa karaniwang edad.","h2":"Ang nag-aaral magmaneho sa Virginia ay dapat may katabing driver na may lisensya na hindi bababa sa 21 taong gulang, o magulang, legal na tagapag-alaga, o kapatid na hindi bababa sa 18 taong gulang.","p":"Tama. Karaniwang 21 pataas ang gumagabay."},"ar":{"q":"في Virginia، كم يجب أن يكون عمر السائق المرخَّص الذي يجلس بجانب المتعلّم عادةً؟","o":["16 سنة على الأقل","18 سنة على الأقل","21 سنة على الأقل","25 سنة على الأقل"],"h1":"يمكن أن يكون الوصي القانوني أو الأخ أو الأخت أصغر من العمر المعتاد.","h2":"يجب أن يقود المتعلّم في Virginia ومعه سائق مرخَّص يجلس بجانبه عمره 21 سنة على الأقل، أو مع أحد الوالدين أو الوصي القانوني أو أخ أو أخت عمره 18 سنة على الأقل.","p":"صحيح. المشرف عادةً عمره 21 سنة أو أكثر."},"ref":{"doc":"VA","page":31}},{"id":"va-006","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how many passengers under 21 who are not family may ride with a learner's permit holder?","o":["None at all","No more than one","No more than two","No more than three"],"h1":"Think of just one friend.","h2":"A Virginia learner's permit holder may carry no more than one passenger under 21 who is not a family member.","p":"Right. With a permit, only one passenger under 21 who is not family."},"es":{"q":"En Virginia, ¿cuántos pasajeros menores de 21 años que no son familiares pueden viajar con alguien que tiene permiso de aprendiz?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"Piense en un solo amigo.","h2":"En Virginia, quien tiene permiso de aprendiz puede llevar como máximo un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Con permiso, solo un pasajero menor de 21 años que no sea familiar."},"zh":{"q":"在 Virginia，持学习驾照的人开车时，可以载几位不是家人、未满 21 岁的乘客？","o":["一个也不行","最多一位","最多两位","最多三位"],"h1":"想一想只带一个朋友。","h2":"Virginia 持学习驾照的人，最多只能载一位不是家人、未满 21 岁的乘客。","p":"对。持学习驾照时，只能载一位不是家人、未满 21 岁的乘客。"},"vi":{"q":"Ở Virginia, người có giấy phép tập lái được chở bao nhiêu hành khách dưới 21 tuổi không phải người trong gia đình?","o":["Không ai cả","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Hãy nghĩ đến chỉ một người bạn.","h2":"Người có giấy phép tập lái ở Virginia được chở không quá một hành khách dưới 21 tuổi không phải người trong gia đình.","p":"Đúng. Với giấy phép tập lái, chỉ một hành khách dưới 21 tuổi không phải người nhà."},"tl":{"q":"Sa Virginia, ilang pasaherong wala pang 21 at hindi kapamilya ang puwedeng isakay ng may hawak ng learner's permit?","o":["Wala talaga","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Isipin ang isang kaibigan lang.","h2":"Ang may hawak ng learner's permit sa Virginia ay puwedeng magsakay ng hindi hihigit sa isang pasaherong wala pang 21 na hindi kapamilya.","p":"Tama. Kapag may permit, isang pasahero lang na wala pang 21 na hindi kapamilya."},"ar":{"q":"في Virginia، كم راكبًا عمره أقل من 21 سنة وليس من العائلة يمكن أن يركب مع حامل تصريح التعلّم؟","o":["لا أحد أبدًا","واحد فقط على الأكثر","اثنان على الأكثر","ثلاثة على الأكثر"],"h1":"فكّر في صديق واحد فقط.","h2":"يمكن لحامل تصريح التعلّم في Virginia أن يحمل راكبًا واحدًا فقط على الأكثر عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. مع التصريح، راكب واحد فقط عمره أقل من 21 سنة وليس من العائلة."},"ref":{"doc":"VA","page":null}},{"id":"va-007","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, when may a driver under 18 with a driver's license not drive, unless an exception applies?","o":["From 10 p.m. to 5 a.m.","From 11 p.m. to 5 a.m.","From 9 p.m. to 6 a.m.","From midnight to 4 a.m."],"h1":"It starts at midnight.","h2":"A Virginia driver under 18 with a license may not drive from midnight to 4 a.m., except for reasons such as work, a supervised school activity or an emergency. A learner's permit holder may not drive in those hours at all.","p":"Right. No driving from midnight to 4 a.m. under 18."},"es":{"q":"En Virginia, ¿cuándo no puede manejar un conductor menor de 18 años con licencia de manejar, salvo que aplique una excepción?","o":["De 10 p.m. a 5 a.m.","De 11 p.m. a 5 a.m.","De 9 p.m. a 6 a.m.","De medianoche a 4 a.m."],"h1":"Empieza a la medianoche.","h2":"En Virginia, un conductor menor de 18 años con licencia no puede manejar de la medianoche a las 4 a.m., salvo por razones como el trabajo, una actividad escolar supervisada o una emergencia. Quien tiene permiso de aprendiz no puede manejar en esas horas.","p":"Correcto. No se maneja de medianoche a 4 a.m. si es menor de 18."},"zh":{"q":"在 Virginia，未满 18 岁、有驾照的司机，在什么时间不可以开车（除非有例外）？","o":["晚上 10 点到早上 5 点","晚上 11 点到早上 5 点","晚上 9 点到早上 6 点","半夜 12 点到早上 4 点"],"h1":"它从半夜开始。","h2":"Virginia 未满 18 岁、有驾照的司机，从半夜 12 点到早上 4 点不可以开车，除非是为了工作、有人监督的学校活动或紧急情况等原因。持学习驾照的人在这段时间完全不可以开车。","p":"对。未满 18 岁，半夜 12 点到早上 4 点不可以开车。"},"vi":{"q":"Ở Virginia, khi nào tài xế dưới 18 tuổi có bằng lái không được lái xe, trừ khi có ngoại lệ?","o":["Từ 10 giờ tối đến 5 giờ sáng","Từ 11 giờ tối đến 5 giờ sáng","Từ 9 giờ tối đến 6 giờ sáng","Từ nửa đêm đến 4 giờ sáng"],"h1":"Nó bắt đầu lúc nửa đêm.","h2":"Ở Virginia, tài xế dưới 18 tuổi có bằng lái không được lái xe từ nửa đêm đến 4 giờ sáng, trừ các lý do như đi làm, hoạt động ở trường có người giám sát, hoặc trường hợp khẩn cấp. Người có giấy phép tập lái hoàn toàn không được lái xe trong những giờ đó.","p":"Đúng. Dưới 18 tuổi, không lái xe từ nửa đêm đến 4 giờ sáng."},"tl":{"q":"Sa Virginia, kailan hindi puwedeng magmaneho ang driver na wala pang 18 na may driver's license, maliban kung may eksepsiyon?","o":["Mula 10 p.m. hanggang 5 a.m.","Mula 11 p.m. hanggang 5 a.m.","Mula 9 p.m. hanggang 6 a.m.","Mula hatinggabi hanggang 4 a.m."],"h1":"Nagsisimula ito sa hatinggabi.","h2":"Ang driver sa Virginia na wala pang 18 na may lisensya ay hindi puwedeng magmaneho mula hatinggabi hanggang 4 a.m., maliban sa mga dahilan gaya ng trabaho, aktibidad sa paaralan na may gumagabay, o emergency. Ang may hawak ng learner's permit ay hindi talaga puwedeng magmaneho sa mga oras na iyon.","p":"Tama. Bawal magmaneho mula hatinggabi hanggang 4 a.m. kapag wala pang 18."},"ar":{"q":"في Virginia، متى لا يجوز للسائق الذي عمره أقل من 18 سنة ومعه رخصة قيادة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 5 صباحًا","من 9 مساءً إلى 6 صباحًا","من منتصف الليل إلى 4 صباحًا"],"h1":"يبدأ عند منتصف الليل.","h2":"في Virginia لا يجوز للسائق الذي عمره أقل من 18 سنة ومعه رخصة أن يقود من منتصف الليل إلى 4 صباحًا، إلا لأسباب مثل العمل أو نشاط مدرسي تحت الإشراف أو حالة طوارئ. أما حامل تصريح التعلّم فلا يجوز له أن يقود في هذه الساعات أبدًا.","p":"صحيح. لا قيادة من منتصف الليل إلى 4 صباحًا لمن عمره أقل من 18 سنة."},"ref":{"doc":"VA","page":null}},{"id":"va-008","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, which trip is allowed between midnight and 4 a.m. for a driver under 18 with a driver's license?","o":["Driving to or from a job","Driving home from a party","Driving a friend to the store","Driving to practice for the road test"],"h1":"It is a trip connected to earning money.","h2":"Virginia lets a licensed driver under 18 drive between midnight and 4 a.m. to or from a job, and for a few other listed reasons such as an emergency.","p":"Right. Driving to or from work is allowed."},"es":{"q":"En Virginia, ¿qué viaje se permite entre la medianoche y las 4 a.m. a un conductor menor de 18 años con licencia de manejar?","o":["Ir o volver del trabajo","Volver a casa de una fiesta","Llevar a un amigo a la tienda","Practicar para el examen de manejo"],"h1":"Es un viaje relacionado con ganar dinero.","h2":"Virginia permite que un conductor menor de 18 años con licencia maneje entre la medianoche y las 4 a.m. para ir o volver del trabajo, y por otras pocas razones, como una emergencia.","p":"Correcto. Se permite ir o volver del trabajo."},"zh":{"q":"在 Virginia，未满 18 岁、有驾照的司机，在半夜 12 点到早上 4 点之间，可以开哪一种车程？","o":["开车去上班或下班回家","参加派对后开车回家","开车送朋友去商店","开车去练习路考"],"h1":"这是和赚钱有关的车程。","h2":"Virginia 允许未满 18 岁、有驾照的司机在半夜 12 点到早上 4 点之间开车去上班或下班回家，也允许其他几个列出的原因，例如紧急情况。","p":"对。开车上下班是允许的。"},"vi":{"q":"Ở Virginia, chuyến đi nào được phép từ nửa đêm đến 4 giờ sáng đối với tài xế dưới 18 tuổi có bằng lái?","o":["Lái xe đi làm hoặc đi làm về","Lái xe về nhà sau bữa tiệc","Chở bạn đi cửa hàng","Lái xe đi tập cho kỳ thi lái xe"],"h1":"Đó là chuyến đi liên quan đến việc kiếm tiền.","h2":"Virginia cho phép tài xế dưới 18 tuổi có bằng lái được lái xe từ nửa đêm đến 4 giờ sáng để đi làm hoặc đi làm về, và vì một vài lý do khác được liệt kê như trường hợp khẩn cấp.","p":"Đúng. Được phép lái xe đi làm hoặc đi làm về."},"tl":{"q":"Sa Virginia, aling biyahe ang pinapayagan mula hatinggabi hanggang 4 a.m. para sa driver na wala pang 18 na may driver's license?","o":["Pagmamaneho papunta o pauwi mula sa trabaho","Pagmamaneho pauwi mula sa party","Paghatid sa kaibigan sa tindahan","Pagmamaneho para magsanay para sa road test"],"h1":"Biyahe ito na may kinalaman sa pagkita ng pera.","h2":"Pinapayagan ng Virginia ang driver na wala pang 18 na may lisensya na magmaneho mula hatinggabi hanggang 4 a.m. papunta o pauwi mula sa trabaho, at sa ilang iba pang nakalistang dahilan gaya ng emergency.","p":"Tama. Pinapayagan ang pagmamaneho papunta o pauwi mula sa trabaho."},"ar":{"q":"في Virginia، أي رحلة مسموح بها بين منتصف الليل و4 صباحًا للسائق الذي عمره أقل من 18 سنة ومعه رخصة قيادة؟","o":["القيادة إلى العمل أو العودة منه","القيادة إلى البيت بعد حفلة","توصيل صديق إلى المتجر","القيادة للتدرّب على اختبار القيادة العملي"],"h1":"هي رحلة لها علاقة بكسب المال.","h2":"تسمح Virginia للسائق المرخَّص الذي عمره أقل من 18 سنة بالقيادة بين منتصف الليل و4 صباحًا للذهاب إلى العمل أو العودة منه، ولبعض الأسباب الأخرى المذكورة مثل حالة الطوارئ.","p":"صحيح. القيادة إلى العمل أو العودة منه مسموح بها."},"ref":{"doc":"VA","page":null}},{"id":"va-009","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, during the first year with a license, how many passengers under 21 may a driver under 18 carry?","o":["None at all","Two","One","Three"],"h1":"Family members do not count toward this limit.","h2":"In the first year with a Virginia license, a driver under 18 may carry only one passenger under 21 who is not a family member.","p":"Right. One passenger under 21 in the first year."},"es":{"q":"En Virginia, durante el primer año con licencia, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18?","o":["Ninguno","Dos","Uno","Tres"],"h1":"Los familiares no cuentan para este límite.","h2":"En el primer año con licencia en Virginia, un conductor menor de 18 años solo puede llevar un pasajero menor de 21 años que no sea familiar.","p":"Correcto. Un pasajero menor de 21 el primer año."},"zh":{"q":"在 Virginia，未满 18 岁的司机拿到驾照后的第一年，可以载几位未满 21 岁的乘客？","o":["一个也不行","两位","一位","三位"],"h1":"家人不算在这个限制里。","h2":"在 Virginia 拿到驾照后的第一年，未满 18 岁的司机只能载一位不是家人、未满 21 岁的乘客。","p":"对。第一年只能载一位未满 21 岁的乘客。"},"vi":{"q":"Ở Virginia, trong năm đầu có bằng lái, tài xế dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi?","o":["Không ai cả","Hai người","Một người","Ba người"],"h1":"Người trong gia đình không tính vào giới hạn này.","h2":"Trong năm đầu có bằng lái ở Virginia, tài xế dưới 18 tuổi chỉ được chở một hành khách dưới 21 tuổi không phải người trong gia đình.","p":"Đúng. Một hành khách dưới 21 tuổi trong năm đầu."},"tl":{"q":"Sa Virginia, sa unang taon na may lisensya, ilang pasaherong wala pang 21 ang puwedeng isakay ng driver na wala pang 18?","o":["Wala talaga","Dalawa","Isa","Tatlo"],"h1":"Hindi kasama sa limitasyong ito ang mga kapamilya.","h2":"Sa unang taon na may lisensya sa Virginia, ang driver na wala pang 18 ay puwedeng magsakay ng isang pasahero lang na wala pang 21 na hindi kapamilya.","p":"Tama. Isang pasaherong wala pang 21 sa unang taon."},"ar":{"q":"في Virginia، في السنة الأولى مع الرخصة، كم راكبًا عمره أقل من 21 سنة يمكن أن يحمل السائق الذي عمره أقل من 18 سنة؟","o":["لا أحد أبدًا","اثنان","واحد","ثلاثة"],"h1":"أفراد العائلة لا يُحسبون في هذا الحد.","h2":"في السنة الأولى مع رخصة Virginia، يمكن للسائق الذي عمره أقل من 18 سنة أن يحمل راكبًا واحدًا فقط عمره أقل من 21 سنة وليس من العائلة.","p":"صحيح. راكب واحد عمره أقل من 21 سنة في السنة الأولى."},"ref":{"doc":"VA","page":null}},{"id":"va-010","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, after holding a license for one year, how many passengers under 21 may a driver under 18 carry in limited situations, such as going to a school activity?","o":["Two","Up to three","Up to five","Any number"],"h1":"The number goes up after the first year, but only for certain trips.","h2":"After one year with a license, a Virginia driver under 18 may carry up to three passengers under 21 in limited situations, such as a trip to or from a school activity.","p":"Right. Up to three, in limited situations."},"es":{"q":"En Virginia, después de tener la licencia un año, ¿cuántos pasajeros menores de 21 años puede llevar un conductor menor de 18 en situaciones limitadas, como ir a una actividad escolar?","o":["Dos","Hasta tres","Hasta cinco","Cualquier número"],"h1":"El número sube después del primer año, pero solo para ciertos viajes.","h2":"Después de un año con licencia, un conductor menor de 18 años en Virginia puede llevar hasta tres pasajeros menores de 21 en situaciones limitadas, como ir o volver de una actividad escolar.","p":"Correcto. Hasta tres, en situaciones limitadas."},"zh":{"q":"在 Virginia，未满 18 岁的司机拿驾照满一年后，在少数情况下（例如去参加学校活动），可以载几位未满 21 岁的乘客？","o":["两位","最多三位","最多五位","不限人数"],"h1":"第一年后人数会增加，但只限某些车程。","h2":"在 Virginia，未满 18 岁的司机拿驾照满一年后，在少数情况下（例如往返学校活动），最多可以载三位未满 21 岁的乘客。","p":"对。在少数情况下最多三位。"},"vi":{"q":"Ở Virginia, sau khi có bằng lái một năm, tài xế dưới 18 tuổi được chở bao nhiêu hành khách dưới 21 tuổi trong một số trường hợp, như đi đến hoạt động ở trường?","o":["Hai người","Tối đa ba người","Tối đa năm người","Bao nhiêu cũng được"],"h1":"Số người tăng lên sau năm đầu, nhưng chỉ cho một số chuyến đi.","h2":"Sau một năm có bằng lái, tài xế dưới 18 tuổi ở Virginia được chở tối đa ba hành khách dưới 21 tuổi trong một số trường hợp, như đi đến hoặc về từ hoạt động ở trường.","p":"Đúng. Tối đa ba người, trong một số trường hợp."},"tl":{"q":"Sa Virginia, pagkatapos ng isang taon na may lisensya, ilang pasaherong wala pang 21 ang puwedeng isakay ng driver na wala pang 18 sa ilang sitwasyon, gaya ng pagpunta sa aktibidad sa paaralan?","o":["Dalawa","Hanggang tatlo","Hanggang lima","Kahit ilan"],"h1":"Tumataas ang bilang pagkatapos ng unang taon, pero para lang sa ilang biyahe.","h2":"Pagkatapos ng isang taon na may lisensya, ang driver sa Virginia na wala pang 18 ay puwedeng magsakay ng hanggang tatlong pasaherong wala pang 21 sa ilang sitwasyon, gaya ng biyahe papunta o pauwi mula sa aktibidad sa paaralan.","p":"Tama. Hanggang tatlo, sa ilang sitwasyon."},"ar":{"q":"في Virginia، بعد سنة واحدة مع الرخصة، كم راكبًا عمره أقل من 21 سنة يمكن أن يحمل السائق الذي عمره أقل من 18 سنة في حالات محدودة، مثل الذهاب إلى نشاط مدرسي؟","o":["اثنان","حتى ثلاثة","حتى خمسة","أي عدد"],"h1":"يزيد العدد بعد السنة الأولى، لكن لبعض الرحلات فقط.","h2":"بعد سنة واحدة مع الرخصة، يمكن للسائق في Virginia الذي عمره أقل من 18 سنة أن يحمل حتى ثلاثة ركاب أعمارهم أقل من 21 سنة في حالات محدودة، مثل الذهاب إلى نشاط مدرسي أو العودة منه.","p":"صحيح. حتى ثلاثة، في حالات محدودة."},"ref":{"doc":"VA","page":null}},{"id":"va-011","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, when may a driver use a phone for navigation while driving?","o":["When holding it in one hand to see the map","When typing a new address while moving slowly","When not holding it and not typing into it","Never; map apps are banned while driving"],"h1":"Following directions is allowed; holding or typing is not.","h2":"In Virginia, a driver may use a phone for navigation while driving, as long as the driver is not holding it or entering information into it.","p":"Right. Navigation is allowed if you do not hold the phone or type into it."},"es":{"q":"En Virginia, ¿cuándo puede un conductor usar el celular para navegar mientras maneja?","o":["Cuando lo sostiene en una mano para ver el mapa","Cuando escribe una dirección nueva mientras avanza despacio","Cuando no lo sostiene ni escribe en él","Nunca; las aplicaciones de mapas están prohibidas al manejar"],"h1":"Seguir indicaciones está permitido; sostenerlo o escribir no.","h2":"En Virginia, un conductor puede usar el celular para navegar mientras maneja, siempre que no lo sostenga ni escriba información en él.","p":"Correcto. Navegar está permitido si no sostiene el celular ni escribe en él."},"zh":{"q":"在 Virginia，司机开车时什么时候可以用手机导航？","o":["一只手拿着手机看地图的时候","车开得慢时输入新地址的时候","不拿着手机、也不在手机上打字的时候","永远不可以；开车时禁止用地图应用"],"h1":"跟着路线走是可以的；拿着手机或打字是不可以的。","h2":"在 Virginia，司机开车时可以用手机导航，只要不拿着手机，也不在手机上输入信息。","p":"对。只要不拿着手机、不在上面打字，就可以导航。"},"vi":{"q":"Ở Virginia, khi nào tài xế được dùng điện thoại để chỉ đường trong lúc lái xe?","o":["Khi cầm điện thoại bằng một tay để xem bản đồ","Khi gõ địa chỉ mới trong lúc chạy chậm","Khi không cầm điện thoại và không gõ vào điện thoại","Không bao giờ; ứng dụng bản đồ bị cấm khi lái xe"],"h1":"Đi theo chỉ đường thì được; cầm hoặc gõ thì không được.","h2":"Ở Virginia, tài xế được dùng điện thoại để chỉ đường trong lúc lái xe, miễn là tài xế không cầm điện thoại và không nhập thông tin vào điện thoại.","p":"Đúng. Được dùng chỉ đường nếu bạn không cầm điện thoại và không gõ vào nó."},"tl":{"q":"Sa Virginia, kailan puwedeng gumamit ang driver ng telepono para sa navigation habang nagmamaneho?","o":["Kapag hawak ito sa isang kamay para makita ang mapa","Kapag nagta-type ng bagong address habang mabagal ang takbo","Kapag hindi ito hawak at hindi nagta-type dito","Hindi kailanman; bawal ang map apps habang nagmamaneho"],"h1":"Puwede ang pagsunod sa direksyon; hindi puwede ang paghawak o pag-type.","h2":"Sa Virginia, puwedeng gumamit ang driver ng telepono para sa navigation habang nagmamaneho, basta hindi niya ito hawak at hindi siya naglalagay ng impormasyon dito.","p":"Tama. Puwede ang navigation kung hindi mo hawak ang telepono at hindi ka nagta-type dito."},"ar":{"q":"في Virginia، متى يجوز للسائق أن يستخدم الهاتف للملاحة أثناء القيادة؟","o":["عندما يمسكه بيد واحدة ليرى الخريطة","عندما يكتب عنوانًا جديدًا وهو يسير ببطء","عندما لا يمسكه ولا يكتب فيه","أبدًا؛ تطبيقات الخرائط ممنوعة أثناء القيادة"],"h1":"اتباع الاتجاهات مسموح؛ الإمساك بالهاتف أو الكتابة فيه غير مسموح.","h2":"في Virginia، يجوز للسائق أن يستخدم الهاتف للملاحة أثناء القيادة، بشرط ألا يمسكه وألا يُدخل فيه معلومات.","p":"صحيح. الملاحة مسموحة إذا كنت لا تمسك الهاتف ولا تكتب فيه."},"ref":{"doc":"VA","page":24}},{"id":"va-012","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, since January 1, 2021, what is illegal for every driver while the car is moving?","o":["Holding a phone in your hand","Listening to the radio","Using a hands-free phone","Talking to passengers"],"h1":"The law is about where the phone is.","h2":"Since January 1, 2021, Virginia drivers may not hold a hand-held phone or other communication device while driving, except in an emergency or when lawfully stopped or parked.","p":"Right. Holding a phone while driving is illegal."},"es":{"q":"En Virginia, desde el 1 de enero de 2021, ¿qué es ilegal para todo conductor mientras el carro está en movimiento?","o":["Sostener el teléfono en la mano","Escuchar la radio","Usar el teléfono con manos libres","Hablar con los pasajeros"],"h1":"La ley trata de dónde está el teléfono.","h2":"Desde el 1 de enero de 2021, los conductores en Virginia no pueden sostener un teléfono u otro dispositivo de comunicación al manejar, salvo en una emergencia o cuando están detenidos o estacionados legalmente.","p":"Correcto. Sostener el teléfono al manejar es ilegal."},"zh":{"q":"在 Virginia，从 2021 年 1 月 1 日起，车在行驶时，所有司机都不可以做什么？","o":["用手拿着手机","听收音机","用免提电话","和乘客说话"],"h1":"这条法律和手机放在哪里有关。","h2":"从 2021 年 1 月 1 日起，Virginia 的司机开车时不可以用手拿着手机或其他通讯设备，除非是紧急情况，或车已合法停下或停好。","p":"对。开车时拿着手机是违法的。"},"vi":{"q":"Ở Virginia, từ ngày 1 tháng 1 năm 2021, điều gì là bất hợp pháp với mọi tài xế khi xe đang chạy?","o":["Cầm điện thoại trên tay","Nghe radio","Dùng điện thoại rảnh tay","Nói chuyện với hành khách"],"h1":"Luật này nói về vị trí của điện thoại.","h2":"Từ ngày 1 tháng 1 năm 2021, tài xế ở Virginia không được cầm điện thoại hoặc thiết bị liên lạc khác trên tay khi lái xe, trừ trường hợp khẩn cấp hoặc khi xe đã dừng hay đỗ hợp pháp.","p":"Đúng. Cầm điện thoại khi lái xe là bất hợp pháp."},"tl":{"q":"Sa Virginia, mula Enero 1, 2021, ano ang bawal sa bawat driver habang umaandar ang sasakyan?","o":["Paghawak ng telepono sa kamay","Pakikinig sa radyo","Paggamit ng hands-free na telepono","Pakikipag-usap sa mga pasahero"],"h1":"Tungkol ang batas sa kung nasaan ang telepono.","h2":"Mula Enero 1, 2021, hindi puwedeng humawak ang mga driver sa Virginia ng telepono o ibang communication device habang nagmamaneho, maliban sa emergency o kapag legal na nakahinto o nakaparada.","p":"Tama. Bawal humawak ng telepono habang nagmamaneho."},"ar":{"q":"في Virginia، منذ 1 يناير 2021، ما الممنوع على كل سائق أثناء حركة السيارة؟","o":["إمساك الهاتف في يدك","الاستماع إلى الراديو","استخدام هاتف بدون استعمال اليدين","التحدث مع الركاب"],"h1":"القانون يتعلّق بمكان الهاتف.","h2":"منذ 1 يناير 2021، لا يجوز للسائقين في Virginia أن يمسكوا الهاتف أو أي جهاز اتصال آخر في اليد أثناء القيادة، إلا في حالة طوارئ أو عند التوقف أو الوقوف بشكل قانوني.","p":"صحيح. إمساك الهاتف أثناء القيادة ممنوع."},"ref":{"doc":"VA","page":24}},{"id":"va-013","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, what is the fine for a first offense of holding a phone while driving?","o":["$25","$50","$125","$500"],"h1":"It is more than one hundred dollars.","h2":"A first offense of holding a phone while driving in Virginia carries a $125 fine.","p":"Right. The first offense is $125."},"es":{"q":"En Virginia, ¿cuál es la multa por la primera vez que se sostiene el teléfono al manejar?","o":["$25","$50","$125","$500"],"h1":"Es más de cien dólares.","h2":"La primera infracción por sostener el teléfono al manejar en Virginia tiene una multa de $125.","p":"Correcto. La primera vez son $125."},"zh":{"q":"在 Virginia，第一次被抓到开车时拿着手机，罚款是多少？","o":["$25","$50","$125","$500"],"h1":"它超过一百美元。","h2":"在 Virginia，第一次开车时拿着手机，罚款是 $125。","p":"对。第一次罚 $125。"},"vi":{"q":"Ở Virginia, tiền phạt cho lần vi phạm đầu tiên vì cầm điện thoại khi lái xe là bao nhiêu?","o":["$25","$50","$125","$500"],"h1":"Số tiền này hơn một trăm đô la.","h2":"Ở Virginia, lần đầu cầm điện thoại khi lái xe bị phạt $125.","p":"Đúng. Lần vi phạm đầu tiên là $125."},"tl":{"q":"Sa Virginia, magkano ang multa sa unang paglabag ng paghawak ng telepono habang nagmamaneho?","o":["$25","$50","$125","$500"],"h1":"Higit ito sa isang daang dolyar.","h2":"Sa Virginia, ang unang paglabag ng paghawak ng telepono habang nagmamaneho ay may multang $125.","p":"Tama. $125 ang unang paglabag."},"ar":{"q":"في Virginia، كم غرامة المخالفة الأولى لإمساك الهاتف أثناء القيادة؟","o":["$25","$50","$125","$500"],"h1":"هي أكثر من مئة دولار.","h2":"في Virginia، المخالفة الأولى لإمساك الهاتف أثناء القيادة غرامتها $125.","p":"صحيح. المخالفة الأولى $125."},"ref":{"doc":"VA","page":null}},{"id":"va-014","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, what is the fine for holding a phone while driving in a highway work zone?","o":["$125","$250","$75","$1,000"],"h1":"It is the same as the fine for a second offense.","h2":"Holding a phone while driving in a Virginia highway work zone, or a second offense, carries a $250 fine, double the first-offense fine.","p":"Right. In a work zone the fine is $250."},"es":{"q":"En Virginia, ¿cuál es la multa por sostener el teléfono al manejar en una zona de trabajos en la carretera?","o":["$125","$250","$75","$1,000"],"h1":"Es igual a la multa por una segunda infracción.","h2":"Sostener el teléfono al manejar en una zona de trabajos en una carretera de Virginia, o una segunda infracción, tiene una multa de $250, el doble que la primera vez.","p":"Correcto. En una zona de trabajos la multa es $250."},"zh":{"q":"在 Virginia，在高速公路施工区开车时拿着手机，罚款是多少？","o":["$125","$250","$75","$1,000"],"h1":"它和第二次违规的罚款一样。","h2":"在 Virginia 的高速公路施工区开车时拿着手机，或第二次违规，罚款是 $250，是第一次罚款的两倍。","p":"对。在施工区罚 $250。"},"vi":{"q":"Ở Virginia, tiền phạt vì cầm điện thoại khi lái xe trong khu vực thi công trên xa lộ là bao nhiêu?","o":["$125","$250","$75","$1,000"],"h1":"Số tiền này bằng tiền phạt cho lần vi phạm thứ hai.","h2":"Cầm điện thoại khi lái xe trong khu vực thi công trên xa lộ ở Virginia, hoặc vi phạm lần thứ hai, bị phạt $250, gấp đôi tiền phạt lần đầu.","p":"Đúng. Trong khu vực thi công, tiền phạt là $250."},"tl":{"q":"Sa Virginia, magkano ang multa sa paghawak ng telepono habang nagmamaneho sa work zone ng highway?","o":["$125","$250","$75","$1,000"],"h1":"Kapareho ito ng multa sa ikalawang paglabag.","h2":"Ang paghawak ng telepono habang nagmamaneho sa work zone ng highway sa Virginia, o ang ikalawang paglabag, ay may multang $250, doble ng multa sa unang paglabag.","p":"Tama. Sa work zone, $250 ang multa."},"ar":{"q":"في Virginia، كم غرامة إمساك الهاتف أثناء القيادة في منطقة أعمال على الطريق السريع؟","o":["$125","$250","$75","$1,000"],"h1":"هي نفس غرامة المخالفة الثانية.","h2":"إمساك الهاتف أثناء القيادة في منطقة أعمال على طريق سريع في Virginia، أو المخالفة الثانية، غرامته $250، أي ضعف غرامة المخالفة الأولى.","p":"صحيح. في منطقة الأعمال الغرامة $250."},"ref":{"doc":"VA","page":null}},{"id":"va-015","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver under 21 who has been drinking breaks the law at what blood alcohol level?","o":["0.08 percent","0.05 percent","0.10 percent","0.02 percent"],"h1":"It is the lowest number on the list.","h2":"In Virginia a driver under 21 who drives after drinking alcohol breaks the law with a blood alcohol level of 0.02 percent or more.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Virginia, ¿con qué nivel de alcohol en la sangre viola la ley un conductor menor de 21 años que ha bebido?","o":["0.08 por ciento","0.05 por ciento","0.10 por ciento","0.02 por ciento"],"h1":"Es el número más bajo de la lista.","h2":"En Virginia, un conductor menor de 21 años que maneja después de beber viola la ley con un nivel de alcohol de 0.02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Virginia，未满 21 岁的司机喝酒后开车，血液酒精浓度达到多少就违法？","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"它是选项中最小的数字。","h2":"在 Virginia，未满 21 岁的司机喝酒后开车，血液酒精浓度达到 0.02% 或以上就违法。","p":"对。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở Virginia, tài xế dưới 21 tuổi đã uống rượu bia sẽ phạm luật ở nồng độ cồn trong máu bao nhiêu?","o":["0.08%","0.05%","0.10%","0.02%"],"h1":"Đó là con số nhỏ nhất trong danh sách.","h2":"Ở Virginia, tài xế dưới 21 tuổi lái xe sau khi uống rượu bia sẽ phạm luật khi nồng độ cồn trong máu từ 0.02% trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Virginia, ang driver na wala pang 21 na uminom ng alak ay lumalabag sa batas sa anong antas ng alkohol sa dugo?","o":["0.08 porsiyento","0.05 porsiyento","0.10 porsiyento","0.02 porsiyento"],"h1":"Ito ang pinakamababang numero sa listahan.","h2":"Sa Virginia, ang driver na wala pang 21 na nagmaneho pagkatapos uminom ng alak ay lumalabag sa batas kapag 0.02 porsiyento o higit pa ang alkohol sa dugo niya.","p":"Tama. Kapag wala pang 21, 0.02 ang limitasyon."},"ar":{"q":"في Virginia، السائق الذي عمره أقل من 21 سنة وشرب الكحول يخالف القانون عند أي نسبة كحول في الدم؟","o":["0.08 بالمئة","0.05 بالمئة","0.10 بالمئة","0.02 بالمئة"],"h1":"هي أصغر رقم في القائمة.","h2":"في Virginia، السائق الذي عمره أقل من 21 سنة ويقود بعد شرب الكحول يخالف القانون إذا كانت نسبة الكحول في دمه 0.02 بالمئة أو أكثر.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو 0.02."},"ref":{"doc":"VA","page":24}},{"id":"va-016","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, what happens to the license of a driver under 21 convicted of driving after drinking?","o":["It is lost for one year","It gets a warning stamp","It is lost for one week","Nothing happens to it"],"h1":"The loss lasts a full year.","h2":"A driver under 21 convicted of driving after drinking in Virginia loses the license for one year and must also pay at least $500 or do 50 hours of community service.","p":"Right. The license is lost for one year."},"es":{"q":"En Virginia, ¿qué le pasa a la licencia de un conductor menor de 21 años condenado por manejar después de beber?","o":["La pierde por un año","Recibe un sello de advertencia","La pierde por una semana","No le pasa nada"],"h1":"La pérdida dura un año completo.","h2":"En Virginia, un conductor menor de 21 años condenado por manejar después de beber pierde la licencia por un año y además debe pagar por lo menos $500 o hacer 50 horas de servicio comunitario.","p":"Correcto. Pierde la licencia por un año."},"zh":{"q":"在 Virginia，未满 21 岁的司机因喝酒后开车被定罪，驾照会怎样？","o":["被吊销一年","被盖上警告章","被吊销一周","驾照没有任何影响"],"h1":"吊销时间是整整一年。","h2":"在 Virginia，未满 21 岁的司机因喝酒后开车被定罪，会被吊销驾照一年，还必须付至少 $500 罚款或做 50 小时社区服务。","p":"对。驾照会被吊销一年。"},"vi":{"q":"Ở Virginia, điều gì xảy ra với bằng lái của tài xế dưới 21 tuổi bị kết tội lái xe sau khi uống rượu bia?","o":["Bị mất bằng một năm","Bị đóng dấu cảnh cáo","Bị mất bằng một tuần","Không có gì xảy ra"],"h1":"Thời gian mất bằng là trọn một năm.","h2":"Ở Virginia, tài xế dưới 21 tuổi bị kết tội lái xe sau khi uống rượu bia sẽ mất bằng lái một năm, và còn phải trả ít nhất $500 hoặc làm 50 giờ phục vụ cộng đồng.","p":"Đúng. Bằng lái bị mất một năm."},"tl":{"q":"Sa Virginia, ano ang mangyayari sa lisensya ng driver na wala pang 21 na nahatulan sa pagmamaneho pagkatapos uminom?","o":["Mawawala ito nang isang taon","Lalagyan ito ng tatak ng babala","Mawawala ito nang isang linggo","Walang mangyayari dito"],"h1":"Buong isang taon ang pagkawala.","h2":"Sa Virginia, ang driver na wala pang 21 na nahatulan sa pagmamaneho pagkatapos uminom ay mawawalan ng lisensya nang isang taon, at dapat ding magbayad ng hindi bababa sa $500 o gumawa ng 50 oras na community service.","p":"Tama. Mawawala ang lisensya nang isang taon."},"ar":{"q":"في Virginia، ماذا يحدث لرخصة السائق الذي عمره أقل من 21 سنة إذا أُدين بالقيادة بعد الشرب؟","o":["تُسحب لمدة سنة","يوضع عليها ختم تحذير","تُسحب لمدة أسبوع","لا يحدث لها شيء"],"h1":"السحب يستمر سنة كاملة.","h2":"في Virginia، السائق الذي عمره أقل من 21 سنة ويُدان بالقيادة بعد الشرب تُسحب رخصته لمدة سنة، ويجب أيضًا أن يدفع $500 على الأقل أو يقوم بـ50 ساعة من خدمة المجتمع.","p":"صحيح. تُسحب الرخصة لمدة سنة."},"ref":{"doc":"VA","page":30}},{"id":"va-017","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, driving how much over the speed limit counts as reckless driving?","o":["5 mph or more","10 mph or more","20 mph or more","30 mph or more"],"h1":"In Virginia this is a crime, not just a ticket.","h2":"In Virginia, driving 20 mph or more over the speed limit is reckless driving, a serious offense.","p":"Right. 20 mph or more over the limit is reckless driving."},"es":{"q":"En Virginia, ¿cuánto por encima del límite de velocidad se considera manejo imprudente (reckless driving)?","o":["5 mph o más","10 mph o más","20 mph o más","30 mph o más"],"h1":"En Virginia esto es un delito, no solo una multa.","h2":"En Virginia, manejar 20 mph o más por encima del límite es manejo imprudente, una infracción grave.","p":"Correcto. 20 mph o más sobre el límite es manejo imprudente."},"zh":{"q":"在 Virginia，开车超过限速多少就算鲁莽驾驶（reckless driving）？","o":["超过 5 mph 或以上","超过 10 mph 或以上","超过 20 mph 或以上","超过 30 mph 或以上"],"h1":"在 Virginia，这是犯罪，不只是罚单。","h2":"在 Virginia，超过限速 20 mph 或以上就是鲁莽驾驶，是严重的违法行为。","p":"对。超过限速 20 mph 或以上就是鲁莽驾驶。"},"vi":{"q":"Ở Virginia, lái xe vượt tốc độ giới hạn bao nhiêu thì bị coi là lái xe liều lĩnh (reckless driving)?","o":["Từ 5 mph trở lên","Từ 10 mph trở lên","Từ 20 mph trở lên","Từ 30 mph trở lên"],"h1":"Ở Virginia, đây là tội, không chỉ là một vé phạt.","h2":"Ở Virginia, lái xe vượt tốc độ giới hạn từ 20 mph trở lên là lái xe liều lĩnh, một vi phạm nghiêm trọng.","p":"Đúng. Vượt giới hạn từ 20 mph trở lên là lái xe liều lĩnh."},"tl":{"q":"Sa Virginia, gaano kalaki ang lampas sa speed limit para ituring na reckless driving?","o":["5 mph o higit pa","10 mph o higit pa","20 mph o higit pa","30 mph o higit pa"],"h1":"Sa Virginia, krimen ito, hindi lang tiket.","h2":"Sa Virginia, ang pagmamaneho nang 20 mph o higit pa sa speed limit ay reckless driving, isang mabigat na paglabag.","p":"Tama. 20 mph o higit pa sa limit ay reckless driving."},"ar":{"q":"في Virginia، القيادة بكم فوق حد السرعة تُعتبر قيادة متهورة (reckless driving)؟","o":["5 mph أو أكثر","10 mph أو أكثر","20 mph أو أكثر","30 mph أو أكثر"],"h1":"في Virginia هذه جريمة، وليست مجرد مخالفة.","h2":"في Virginia، القيادة بسرعة 20 mph أو أكثر فوق حد السرعة هي قيادة متهورة، وهي مخالفة خطيرة.","p":"صحيح. 20 mph أو أكثر فوق الحد هي قيادة متهورة."},"ref":{"doc":"VA","page":14}},{"id":"va-018","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, above what speed is driving always reckless, whatever the posted limit?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"It is 15 mph above the top interstate limit.","h2":"In Virginia, driving faster than 85 mph is reckless driving no matter what the posted speed limit is.","p":"Right. Over 85 mph is always reckless driving."},"es":{"q":"En Virginia, ¿a partir de qué velocidad es siempre manejo imprudente, sin importar el límite indicado?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"Es 15 mph más que el límite máximo de las interestatales.","h2":"En Virginia, manejar a más de 85 mph es manejo imprudente sin importar el límite de velocidad indicado.","p":"Correcto. Más de 85 mph es siempre manejo imprudente."},"zh":{"q":"在 Virginia，不管标示的限速是多少，车速超过多少就一定算鲁莽驾驶？","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"它比州际公路的最高限速高 15 mph。","h2":"在 Virginia，不管标示的限速是多少，车速超过 85 mph 就是鲁莽驾驶。","p":"对。超过 85 mph 一定是鲁莽驾驶。"},"vi":{"q":"Ở Virginia, trên tốc độ nào thì lái xe luôn bị coi là liều lĩnh, dù giới hạn ghi trên biển là bao nhiêu?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"Nó cao hơn giới hạn cao nhất trên xa lộ liên tiểu bang 15 mph.","h2":"Ở Virginia, lái xe nhanh hơn 85 mph là lái xe liều lĩnh, dù tốc độ giới hạn ghi trên biển là bao nhiêu.","p":"Đúng. Trên 85 mph luôn là lái xe liều lĩnh."},"tl":{"q":"Sa Virginia, lampas sa anong bilis ay laging reckless driving, anuman ang nakapaskil na limit?","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"15 mph ito sa itaas ng pinakamataas na limit sa interstate.","h2":"Sa Virginia, ang pagmamaneho nang mas mabilis sa 85 mph ay reckless driving, anuman ang nakapaskil na speed limit.","p":"Tama. Lampas sa 85 mph ay laging reckless driving."},"ar":{"q":"في Virginia، فوق أي سرعة تكون القيادة متهورة دائمًا، مهما كان الحد المكتوب على اللافتة؟","o":["75 mph","85 mph","80 mph","100 mph"],"h1":"هي أعلى بـ15 mph من أعلى حد على الطرق السريعة بين الولايات.","h2":"في Virginia، القيادة بسرعة أكثر من 85 mph هي قيادة متهورة مهما كان حد السرعة المكتوب على اللافتة.","p":"صحيح. أكثر من 85 mph هي دائمًا قيادة متهورة."},"ref":{"doc":"VA","page":14}},{"id":"va-019","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, what is the highest speed limit on rural interstates?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is lower than in many western states.","h2":"The highest posted limit on Virginia's rural interstates is 70 mph; always follow the posted signs.","p":"Right. Rural interstates in Virginia go up to 70 mph."},"es":{"q":"En Virginia, ¿cuál es el límite de velocidad más alto en las interestatales rurales?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es más bajo que en muchos estados del oeste.","h2":"El límite más alto en las interestatales rurales de Virginia es de 70 mph; siempre siga los letreros.","p":"Correcto. Las interestatales rurales de Virginia llegan a 70 mph."},"zh":{"q":"在 Virginia，乡村州际公路（interstate）的最高限速是多少？","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"它比很多西部州低。","h2":"Virginia 乡村州际公路标示的最高限速是 70 mph；一定要遵守标示的路牌。","p":"对。Virginia 乡村州际公路最高 70 mph。"},"vi":{"q":"Ở Virginia, tốc độ giới hạn cao nhất trên xa lộ liên tiểu bang (interstate) ở vùng nông thôn là bao nhiêu?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Nó thấp hơn ở nhiều tiểu bang miền tây.","h2":"Tốc độ giới hạn cao nhất ghi trên biển ở xa lộ liên tiểu bang vùng nông thôn của Virginia là 70 mph; luôn làm theo biển báo.","p":"Đúng. Xa lộ liên tiểu bang vùng nông thôn ở Virginia lên đến 70 mph."},"tl":{"q":"Sa Virginia, ano ang pinakamataas na speed limit sa mga rural interstate?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Mas mababa ito kaysa sa maraming estado sa kanluran.","h2":"Ang pinakamataas na nakapaskil na limit sa mga rural interstate ng Virginia ay 70 mph; laging sundin ang mga nakapaskil na sign.","p":"Tama. Hanggang 70 mph ang mga rural interstate sa Virginia."},"ar":{"q":"في Virginia، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate) في المناطق الريفية؟","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"هو أقل مما في كثير من الولايات الغربية.","h2":"أعلى حد مكتوب على الطرق السريعة بين الولايات في المناطق الريفية في Virginia هو 70 mph؛ اتبع دائمًا اللافتات المكتوبة.","p":"صحيح. الطرق السريعة الريفية في Virginia تصل إلى 70 mph."},"ref":{"doc":"VA","page":null}},{"id":"va-020","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, on a highway with two lanes in your direction, you approach a stopped vehicle with flashing lights. What should you do?","o":["Change to a lane not next to it, or slow down if that is unsafe","Stop in your lane until it leaves","Speed up to pass it quickly","Flash your lights and keep going"],"h1":"First try to give it a whole lane of space.","h2":"Virginia's move-over law asks you to change to a lane not next to the stopped vehicle when safe, and if you cannot, to slow down and pass with care.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Virginia, en una carretera con dos carriles en su dirección, usted se acerca a un vehículo detenido con luces intermitentes. ¿Qué debe hacer?","o":["Pasarse a un carril que no esté junto a él, o bajar la velocidad si no es seguro","Pararse en su carril hasta que se vaya","Acelerar para pasarlo rápido","Hacer cambio de luces y seguir"],"h1":"Primero trate de dejarle un carril completo de espacio.","h2":"La ley de Virginia le pide pasarse a un carril que no esté junto al vehículo detenido cuando sea seguro, y si no puede, bajar la velocidad y pasar con cuidado.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Virginia，你在同方向有两条车道的公路上，前面有一辆停着、亮着闪灯的车。你应该怎么做？","o":["换到不紧挨着它的车道；如果不安全就减速","在你的车道停下，等它离开","加速快快超过它","闪你的车灯然后继续开"],"h1":"先试着给它让出一整条车道。","h2":"Virginia 的让道法（move-over law）要求你在安全时换到不紧挨着停着车辆的车道；如果做不到，就减速并小心开过去。","p":"对。让出车道；做不到就减速。"},"vi":{"q":"Ở Virginia, trên xa lộ có hai làn cùng chiều với bạn, bạn đến gần một xe đang dừng có đèn nhấp nháy. Bạn nên làm gì?","o":["Chuyển sang làn không sát bên xe đó, hoặc chạy chậm lại nếu chuyển làn không an toàn","Dừng lại trong làn của bạn cho đến khi xe đó đi","Tăng tốc để vượt qua nhanh","Nháy đèn rồi chạy tiếp"],"h1":"Trước hết hãy cố chừa cho xe đó cả một làn đường.","h2":"Luật nhường làn (move-over law) của Virginia yêu cầu bạn chuyển sang làn không sát bên xe đang dừng khi an toàn, và nếu không thể, hãy chạy chậm lại và đi qua cẩn thận.","p":"Đúng. Chuyển làn, hoặc chạy chậm lại nếu không thể."},"tl":{"q":"Sa Virginia, sa highway na may dalawang lane sa direksyon mo, may papalapit kang nakahintong sasakyan na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Lumipat sa lane na hindi katabi nito, o bumagal kung hindi ligtas lumipat","Huminto sa lane mo hanggang umalis ito","Bumilis para malampasan ito agad","Ikislap ang ilaw mo at magpatuloy"],"h1":"Subukan munang bigyan ito ng isang buong lane na espasyo.","h2":"Ang move-over law ng Virginia ay humihiling na lumipat ka sa lane na hindi katabi ng nakahintong sasakyan kapag ligtas, at kung hindi mo kaya, bumagal at dumaan nang maingat.","p":"Tama. Lumipat ng lane, o bumagal kung hindi kaya."},"ar":{"q":"في Virginia، على طريق سريع فيه حارتان في اتجاهك، تقترب من سيارة متوقفة أضواؤها تومض. ماذا يجب أن تفعل؟","o":["انتقل إلى حارة غير ملاصقة لها، أو خفّف السرعة إذا كان الانتقال غير آمن","توقّف في حارتك حتى تذهب","زِد السرعة لتتجاوزها بسرعة","أومِض بأضوائك واستمر"],"h1":"حاول أولًا أن تترك لها حارة كاملة.","h2":"قانون الابتعاد (move-over law) في Virginia يطلب منك أن تنتقل إلى حارة غير ملاصقة للسيارة المتوقفة عندما يكون ذلك آمنًا، وإذا لم تستطع، أن تخفّف السرعة وتمر بحذر.","p":"صحيح. ابتعد بحارة، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"VA","page":16}},{"id":"va-021","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, the move-over law also covers which stopped vehicles?","o":["Only police cars","Only school buses","Any vehicle with hazard lights, flares or warning signs","Only vehicles from the power company"],"h1":"Think of an ordinary car with its flashers on.","h2":"Virginia's move-over law also covers any stopped vehicle that shows hazard lights, flares or warning signs, not only emergency vehicles.","p":"Right. It covers any vehicle with hazard lights, flares or warning signs."},"es":{"q":"En Virginia, ¿qué otros vehículos detenidos protege también la ley de cambiarse de carril?","o":["Solo los carros de policía","Solo los autobuses escolares","Cualquier vehículo con luces de emergencia, bengalas o señales de aviso","Solo los vehículos de la compañía eléctrica"],"h1":"Piense en un carro común con las luces intermitentes encendidas.","h2":"En Virginia, la ley de cambiarse de carril también protege a cualquier vehículo detenido que muestre luces de emergencia, bengalas o señales de advertencia, no solo a los vehículos de emergencia.","p":"Correcto. Protege a cualquier vehículo con luces de emergencia, bengalas o señales."},"zh":{"q":"在 Virginia，让道法（move-over law）也适用于哪些停着的车？","o":["只有警车","只有校车","任何亮着危险警示灯、放了照明弹或警告牌的车","只有电力公司的车"],"h1":"想一想一辆亮着双闪灯的普通汽车。","h2":"Virginia 的让道法也适用于任何亮着危险警示灯、放了照明弹或警告牌的停着的车，不只是紧急车辆。","p":"对。适用于任何亮着危险警示灯、放了照明弹或警告牌的车。"},"vi":{"q":"Ở Virginia, luật nhường làn (move-over law) cũng áp dụng cho những xe đang dừng nào?","o":["Chỉ xe cảnh sát","Chỉ xe buýt trường học","Bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo","Chỉ xe của công ty điện"],"h1":"Hãy nghĩ đến một chiếc xe bình thường đang bật đèn nháy.","h2":"Luật nhường làn của Virginia cũng áp dụng cho bất kỳ xe đang dừng nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo, không chỉ xe khẩn cấp.","p":"Đúng. Luật áp dụng cho bất kỳ xe nào bật đèn báo nguy hiểm, đặt pháo sáng hoặc biển cảnh báo."},"tl":{"q":"Sa Virginia, saklaw din ng move-over law ang aling mga nakahintong sasakyan?","o":["Mga sasakyan ng pulis lang","Mga school bus lang","Anumang sasakyan na may hazard lights, flare o warning sign","Mga sasakyan lang ng kompanya ng kuryente"],"h1":"Isipin ang isang ordinaryong kotse na nakabukas ang flashers.","h2":"Saklaw din ng move-over law ng Virginia ang anumang nakahintong sasakyan na may hazard lights, flare o warning sign, hindi lang mga emergency vehicle.","p":"Tama. Saklaw nito ang anumang sasakyan na may hazard lights, flare o warning sign."},"ar":{"q":"في Virginia، قانون الابتعاد (move-over law) يشمل أيضًا أي سيارات متوقفة؟","o":["سيارات الشرطة فقط","الحافلات المدرسية فقط","أي سيارة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير","سيارات شركة الكهرباء فقط"],"h1":"فكّر في سيارة عادية أضواء التحذير فيها تعمل.","h2":"قانون الابتعاد في Virginia يشمل أيضًا أي سيارة متوقفة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير، وليس سيارات الطوارئ فقط.","p":"صحيح. يشمل أي سيارة تُشغّل أضواء التحذير أو تضع مشاعل أو لافتات تحذير."},"ref":{"doc":"VA","page":16}},{"id":"va-022","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, for policies issued or renewed since January 1, 2025, what is the minimum liability insurance?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"The amounts went up in 2025 from 30/60/20.","h2":"Virginia policies issued or renewed since January 1, 2025 must have at least $50,000 for injury to one person, $100,000 per crash and $25,000 for property damage.","p":"Right. Virginia's minimum is now 50/100/25."},"es":{"q":"En Virginia, para las pólizas emitidas o renovadas desde el 1 de enero de 2025, ¿cuál es el seguro de responsabilidad mínimo?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Los montos subieron en 2025 desde 30/60/20.","h2":"Las pólizas de Virginia emitidas o renovadas desde el 1 de enero de 2025 deben tener por lo menos $50,000 por lesiones a una persona, $100,000 por choque y $25,000 por daños a la propiedad.","p":"Correcto. El mínimo en Virginia ahora es 50/100/25."},"zh":{"q":"在 Virginia，从 2025 年 1 月 1 日起签发或续保的保单，最低责任保险是多少？","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"2025 年金额从 30/60/20 提高了。","h2":"Virginia 从 2025 年 1 月 1 日起签发或续保的保单，必须至少有：每人受伤 $50,000、每次车祸 $100,000、财产损失 $25,000。","p":"对。Virginia 现在的最低标准是 50/100/25。"},"vi":{"q":"Ở Virginia, với hợp đồng bảo hiểm được cấp hoặc gia hạn từ ngày 1 tháng 1 năm 2025, mức bảo hiểm trách nhiệm tối thiểu là bao nhiêu?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Các mức này đã tăng lên vào năm 2025 từ 30/60/20.","h2":"Hợp đồng bảo hiểm ở Virginia được cấp hoặc gia hạn từ ngày 1 tháng 1 năm 2025 phải có ít nhất $50,000 cho thương tích của một người, $100,000 cho mỗi tai nạn và $25,000 cho thiệt hại tài sản.","p":"Đúng. Mức tối thiểu của Virginia bây giờ là 50/100/25."},"tl":{"q":"Sa Virginia, para sa mga policy na inilabas o ni-renew mula Enero 1, 2025, ano ang pinakamababang liability insurance?","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"Tumaas ang mga halaga noong 2025 mula 30/60/20.","h2":"Ang mga policy sa Virginia na inilabas o ni-renew mula Enero 1, 2025 ay dapat may hindi bababa sa $50,000 para sa pinsala sa isang tao, $100,000 bawat aksidente at $25,000 para sa pinsala sa ari-arian.","p":"Tama. 50/100/25 na ngayon ang minimum ng Virginia."},"ar":{"q":"في Virginia، للوثائق التي صدرت أو جُدّدت منذ 1 يناير 2025، ما الحد الأدنى لتأمين المسؤولية؟","o":["$30,000 / $60,000 / $20,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $20,000","$100,000 / $300,000 / $100,000"],"h1":"المبالغ ارتفعت في 2025 من 30/60/20.","h2":"وثائق التأمين في Virginia التي صدرت أو جُدّدت منذ 1 يناير 2025 يجب أن يكون فيها على الأقل $50,000 لإصابة شخص واحد، و$100,000 لكل حادث، و$25,000 لأضرار الممتلكات.","p":"صحيح. الحد الأدنى في Virginia الآن 50/100/25."},"ref":{"doc":"VA","page":null}},{"id":"va-023","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, since July 1, 2024, what must a vehicle owner have to register a car?","o":["A $500 uninsured motor vehicle fee","A clean driving record","A safety course certificate","Insurance that meets the state minimum"],"h1":"Paying a fee instead is no longer an option.","h2":"Since July 1, 2024, Virginia no longer lets owners pay a fee to drive uninsured, so every registered vehicle must carry insurance that meets the state minimum.","p":"Right. Insurance is now required to register."},"es":{"q":"En Virginia, desde el 1 de julio de 2024, ¿qué debe tener el dueño de un vehículo para registrarlo?","o":["La cuota de $500 por vehículo sin seguro","Un historial de manejo limpio","Un certificado de curso de seguridad","Un seguro que cumpla el mínimo del estado"],"h1":"Pagar una cuota en su lugar ya no es una opción.","h2":"Desde el 1 de julio de 2024, Virginia ya no permite pagar una cuota para manejar sin seguro, así que todo vehículo registrado debe tener un seguro que cumpla el mínimo del estado.","p":"Correcto. Ahora se necesita seguro para registrar."},"zh":{"q":"在 Virginia，从 2024 年 7 月 1 日起，车主必须有什么才能登记汽车？","o":["$500 的无保险车辆费","没有违规的驾驶记录","安全课程证书","符合州最低标准的保险"],"h1":"不能再用付费来代替了。","h2":"从 2024 年 7 月 1 日起，Virginia 不再允许车主付费后无保险开车，所以每辆登记的车都必须有符合州最低标准的保险。","p":"对。现在登记汽车必须有保险。"},"vi":{"q":"Ở Virginia, từ ngày 1 tháng 7 năm 2024, chủ xe phải có gì để đăng ký xe?","o":["Phí xe không bảo hiểm $500","Hồ sơ lái xe không vi phạm","Giấy chứng nhận khóa học an toàn","Bảo hiểm đạt mức tối thiểu của tiểu bang"],"h1":"Không còn được trả phí thay cho bảo hiểm nữa.","h2":"Từ ngày 1 tháng 7 năm 2024, Virginia không còn cho chủ xe trả phí để lái xe không có bảo hiểm, nên mọi xe đã đăng ký phải có bảo hiểm đạt mức tối thiểu của tiểu bang.","p":"Đúng. Bây giờ phải có bảo hiểm mới đăng ký xe được."},"tl":{"q":"Sa Virginia, mula Hulyo 1, 2024, ano ang dapat mayroon ang may-ari ng sasakyan para mairehistro ang kotse?","o":["$500 na uninsured motor vehicle fee","Malinis na driving record","Sertipiko ng safety course","Insurance na umaabot sa minimum ng estado"],"h1":"Hindi na puwedeng magbayad ng fee bilang kapalit.","h2":"Mula Hulyo 1, 2024, hindi na pinapayagan ng Virginia ang mga may-ari na magbayad ng fee para magmaneho nang walang insurance, kaya bawat rehistradong sasakyan ay dapat may insurance na umaabot sa minimum ng estado.","p":"Tama. Kailangan na ang insurance para makapagrehistro."},"ar":{"q":"في Virginia، منذ 1 يوليو 2024، ماذا يجب أن يكون عند مالك السيارة لتسجيلها؟","o":["رسم $500 للسيارة غير المؤمَّنة","سجل قيادة نظيف","شهادة دورة سلامة","تأمين يحقق الحد الأدنى للولاية"],"h1":"دفع رسم بدلًا من ذلك لم يعد ممكنًا.","h2":"منذ 1 يوليو 2024، لم تعد Virginia تسمح للمالكين بدفع رسم للقيادة بدون تأمين، لذلك يجب أن يكون لكل سيارة مسجّلة تأمين يحقق الحد الأدنى للولاية.","p":"صحيح. التأمين مطلوب الآن للتسجيل."},"ref":{"doc":"VA","page":null}},{"id":"va-024","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how many of the 10 road sign questions on the knowledge exam must you answer correctly?","o":["All 10","8 of them","7 of them","5 of them"],"h1":"Not a single mistake is allowed in this part.","h2":"On the Virginia knowledge exam you must answer all 10 road sign questions correctly before the general knowledge part is scored.","p":"Right. All 10 sign questions must be correct."},"es":{"q":"En Virginia, ¿cuántas de las 10 preguntas sobre señales del examen de conocimientos debe contestar bien?","o":["Las 10","8 de ellas","7 de ellas","5 de ellas"],"h1":"En esta parte no se permite ni un solo error.","h2":"En el examen de conocimientos de Virginia usted debe contestar bien las 10 preguntas sobre señales antes de que se califique la parte de conocimientos generales.","p":"Correcto. Las 10 preguntas sobre señales deben estar bien."},"zh":{"q":"在 Virginia 的笔试中，10 道路牌题你必须答对几道？","o":["全部 10 道","8 道","7 道","5 道"],"h1":"这一部分一个错误都不可以有。","h2":"在 Virginia 的笔试中，你必须答对全部 10 道路牌题，才会计算一般知识部分的分数。","p":"对。10 道路牌题必须全部答对。"},"vi":{"q":"Ở Virginia, trong bài thi kiến thức, bạn phải trả lời đúng bao nhiêu câu trong 10 câu về biển báo?","o":["Cả 10 câu","8 câu","7 câu","5 câu"],"h1":"Phần này không được sai câu nào.","h2":"Trong bài thi kiến thức ở Virginia, bạn phải trả lời đúng cả 10 câu về biển báo thì phần kiến thức chung mới được chấm điểm.","p":"Đúng. Cả 10 câu biển báo phải đúng."},"tl":{"q":"Sa Virginia, ilan sa 10 tanong tungkol sa road sign sa knowledge exam ang dapat mong masagot nang tama?","o":["Lahat ng 10","8 sa mga ito","7 sa mga ito","5 sa mga ito"],"h1":"Walang kahit isang mali ang puwede sa bahaging ito.","h2":"Sa knowledge exam ng Virginia, dapat mong masagot nang tama ang lahat ng 10 tanong tungkol sa road sign bago bigyan ng marka ang bahaging general knowledge.","p":"Tama. Dapat tama ang lahat ng 10 tanong sa sign."},"ar":{"q":"في Virginia، كم سؤالًا من أسئلة لافتات الطريق العشرة في الامتحان النظري يجب أن تجيب عنه بشكل صحيح؟","o":["كل الأسئلة الـ10","8 منها","7 منها","5 منها"],"h1":"لا يُسمح بأي خطأ في هذا الجزء.","h2":"في الامتحان النظري في Virginia يجب أن تجيب عن كل أسئلة لافتات الطريق الـ10 بشكل صحيح قبل أن يُصحَّح جزء المعلومات العامة.","p":"صحيح. يجب أن تكون كل أسئلة اللافتات الـ10 صحيحة."},"ref":{"doc":"VA","page":3}},{"id":"va-025","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, the general knowledge part of the exam has 30 questions. How many must you answer correctly?","o":["18","20","24","28"],"h1":"You need 80 percent.","h2":"To pass the general knowledge part of the Virginia exam you must answer at least 24 of the 30 questions correctly, which is 80 percent.","p":"Right. You need 24 of 30."},"es":{"q":"En Virginia, la parte de conocimientos generales del examen tiene 30 preguntas. ¿Cuántas debe contestar bien?","o":["18","20","24","28"],"h1":"Necesita el 80 por ciento.","h2":"Para aprobar la parte de conocimientos generales del examen de Virginia debe contestar bien por lo menos 24 de las 30 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 24 de 30."},"zh":{"q":"在 Virginia，笔试的一般知识部分有 30 道题。你必须答对几道？","o":["18","20","24","28"],"h1":"你需要 80%。","h2":"要通过 Virginia 笔试的一般知识部分，你必须在 30 道题中至少答对 24 道，也就是 80%。","p":"对。30 道题中要答对 24 道。"},"vi":{"q":"Ở Virginia, phần kiến thức chung của bài thi có 30 câu. Bạn phải trả lời đúng bao nhiêu câu?","o":["18","20","24","28"],"h1":"Bạn cần 80%.","h2":"Để đậu phần kiến thức chung của bài thi ở Virginia, bạn phải trả lời đúng ít nhất 24 trong 30 câu, tức là 80%.","p":"Đúng. Bạn cần 24 trên 30 câu."},"tl":{"q":"Sa Virginia, may 30 tanong ang bahaging general knowledge ng exam. Ilan ang dapat mong masagot nang tama?","o":["18","20","24","28"],"h1":"Kailangan mo ng 80 porsiyento.","h2":"Para makapasa sa bahaging general knowledge ng exam sa Virginia, dapat mong masagot nang tama ang hindi bababa sa 24 sa 30 tanong, na 80 porsiyento.","p":"Tama. Kailangan mo ng 24 sa 30."},"ar":{"q":"في Virginia، جزء المعلومات العامة في الامتحان فيه 30 سؤالًا. كم سؤالًا يجب أن تجيب عنه بشكل صحيح؟","o":["18","20","24","28"],"h1":"تحتاج إلى 80 بالمئة.","h2":"لتنجح في جزء المعلومات العامة في امتحان Virginia يجب أن تجيب عن 24 سؤالًا على الأقل من 30 بشكل صحيح، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 24 من 30."},"ref":{"doc":"VA","page":null}},{"id":"va-026","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, what must you do after failing the knowledge exam three times?","o":["Wait one full year","Pay a $500 fine","Bring a lawyer to the next test","Complete a driver education classroom course"],"h1":"The state wants you to study with a teacher first.","h2":"After three failed knowledge exams in Virginia, you must complete a driver education classroom course before you may take the exam again.","p":"Right. After three failures, take a classroom course first."},"es":{"q":"En Virginia, ¿qué debe hacer después de reprobar tres veces el examen de conocimientos?","o":["Esperar un año completo","Pagar una multa de $500","Llevar un abogado al próximo examen","Completar un curso de educación vial en el aula"],"h1":"El estado quiere que primero estudie con un maestro.","h2":"Después de reprobar tres veces el examen de conocimientos en Virginia, usted debe completar un curso de educación vial en el aula antes de volver a presentarlo.","p":"Correcto. Después de tres fallos, primero tome un curso en el aula."},"zh":{"q":"在 Virginia，笔试考了三次没通过后，你必须做什么？","o":["等整整一年","付 $500 罚款","下次考试带律师","完成驾驶教育课堂课程"],"h1":"州政府希望你先跟老师学习。","h2":"在 Virginia，笔试三次没通过后，你必须先完成驾驶教育课堂课程，才可以再考。","p":"对。三次没通过后，要先上课堂课程。"},"vi":{"q":"Ở Virginia, bạn phải làm gì sau khi trượt bài thi kiến thức ba lần?","o":["Chờ trọn một năm","Trả $500 tiền phạt","Mang luật sư đến lần thi sau","Hoàn thành khóa học lái xe trên lớp"],"h1":"Tiểu bang muốn bạn học với giáo viên trước.","h2":"Sau ba lần trượt bài thi kiến thức ở Virginia, bạn phải hoàn thành khóa học lái xe trên lớp rồi mới được thi lại.","p":"Đúng. Sau ba lần trượt, hãy học khóa trên lớp trước."},"tl":{"q":"Sa Virginia, ano ang dapat mong gawin pagkatapos bumagsak nang tatlong beses sa knowledge exam?","o":["Maghintay ng buong isang taon","Magbayad ng $500 na multa","Magdala ng abogado sa susunod na exam","Tapusin ang driver education classroom course"],"h1":"Gusto ng estado na mag-aral ka muna kasama ang guro.","h2":"Pagkatapos ng tatlong bagsak na knowledge exam sa Virginia, dapat mong tapusin ang driver education classroom course bago ka makapag-exam ulit.","p":"Tama. Pagkatapos ng tatlong bagsak, kumuha muna ng classroom course."},"ar":{"q":"في Virginia، ماذا يجب أن تفعل بعد الرسوب في الامتحان النظري ثلاث مرات؟","o":["أن تنتظر سنة كاملة","أن تدفع غرامة $500","أن تُحضر محاميًا إلى الامتحان القادم","أن تُكمل دورة تعليم القيادة في الصف"],"h1":"الولاية تريد أن تدرس مع معلّم أولًا.","h2":"بعد الرسوب في الامتحان النظري ثلاث مرات في Virginia، يجب أن تُكمل دورة تعليم القيادة في الصف قبل أن يُسمح لك بالامتحان مرة أخرى.","p":"صحيح. بعد ثلاث مرات رسوب، خذ دورة في الصف أولًا."},"ref":{"doc":"VA","page":3}},{"id":"va-027","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, can you take the driver knowledge exam in Spanish?","o":["No, only in English","Yes, Spanish is one of the offered languages","Only with your own translator","Only in large cities"],"h1":"The DMV offers it in many languages.","h2":"The Virginia DMV offers the driver knowledge exam in Spanish and other languages, and translators may not be used for the languages that are offered.","p":"Right. The exam is offered in Spanish."},"es":{"q":"En Virginia, ¿puede presentar el examen de conocimientos de manejo en español?","o":["No, solo en inglés","Sí, el español es uno de los idiomas ofrecidos","Solo con su propio traductor","Solo en las ciudades grandes"],"h1":"El DMV lo ofrece en muchos idiomas.","h2":"El DMV de Virginia ofrece el examen de conocimientos en español y en otros idiomas, y no se permiten traductores para los idiomas que se ofrecen.","p":"Correcto. El examen se ofrece en español."},"zh":{"q":"在 Virginia，可以用西班牙语考驾驶笔试吗？","o":["不行，只能用英语","可以，西班牙语是提供的语言之一","只能带自己的翻译","只在大城市可以"],"h1":"DMV 提供很多种语言。","h2":"Virginia DMV 提供西班牙语和其他语言的驾驶笔试；对于已提供的语言，不可以使用翻译员。","p":"对。笔试有西班牙语版本。"},"vi":{"q":"Ở Virginia, bạn có thể thi kiến thức lái xe bằng tiếng Tây Ban Nha không?","o":["Không, chỉ bằng tiếng Anh","Có, tiếng Tây Ban Nha là một trong các ngôn ngữ được cung cấp","Chỉ khi có người phiên dịch riêng","Chỉ ở các thành phố lớn"],"h1":"DMV cung cấp bài thi bằng nhiều ngôn ngữ.","h2":"DMV của Virginia cung cấp bài thi kiến thức lái xe bằng tiếng Tây Ban Nha và các ngôn ngữ khác, và không được dùng người phiên dịch cho các ngôn ngữ đã được cung cấp.","p":"Đúng. Bài thi có bằng tiếng Tây Ban Nha."},"tl":{"q":"Sa Virginia, puwede mo bang kunin ang driver knowledge exam sa Spanish?","o":["Hindi, sa English lang","Oo, isa ang Spanish sa mga inaalok na wika","Kung may sarili kang tagasalin lang","Sa malalaking lungsod lang"],"h1":"Inaalok ito ng DMV sa maraming wika.","h2":"Inaalok ng Virginia DMV ang driver knowledge exam sa Spanish at iba pang wika, at hindi puwedeng gumamit ng tagasalin para sa mga wikang inaalok.","p":"Tama. Inaalok ang exam sa Spanish."},"ar":{"q":"في Virginia، هل يمكنك أن تقدّم امتحان القيادة النظري باللغة الإسبانية؟","o":["لا، بالإنجليزية فقط","نعم، الإسبانية من اللغات المتوفرة","فقط مع مترجمك الخاص","فقط في المدن الكبيرة"],"h1":"إدارة المركبات (DMV) تقدّمه بلغات كثيرة.","h2":"إدارة المركبات في Virginia (Virginia DMV) تقدّم امتحان القيادة النظري بالإسبانية ولغات أخرى، ولا يُسمح باستخدام مترجمين للغات المتوفرة.","p":"صحيح. الامتحان متوفر بالإسبانية."},"ref":{"doc":"VA","page":null}},{"id":"va-028","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, how close may you follow an emergency vehicle that has its lights flashing?","o":["No closer than 100 feet","No closer than 500 feet","No closer than 50 feet","As close as you like if you are careful"],"h1":"The distance is longer than a city block.","h2":"In Virginia, you must never follow an emergency vehicle with flashing lights closer than 500 feet.","p":"Right. Stay at least 500 feet behind it."},"es":{"q":"En Virginia, ¿qué tan cerca puede seguir a un vehículo de emergencia con las luces encendidas?","o":["No más cerca de 100 pies","No más cerca de 500 pies","No más cerca de 50 pies","Tan cerca como quiera si tiene cuidado"],"h1":"La distancia es más larga que una cuadra.","h2":"En Virginia, nunca debe seguir a un vehículo de emergencia con luces intermitentes a menos de 500 pies.","p":"Correcto. Quédese por lo menos a 500 pies detrás."},"zh":{"q":"在 Virginia，跟在闪着灯的紧急车辆后面时，最近可以跟多近？","o":["不能近于 100 英尺","不能近于 500 英尺","不能近于 50 英尺","只要小心，多近都可以"],"h1":"这个距离比城市里的一个街区还长。","h2":"在 Virginia，跟在闪着灯的紧急车辆后面时，绝不能近于 500 英尺。","p":"对。至少在它后面 500 英尺。"},"vi":{"q":"Ở Virginia, bạn được đi theo sau xe khẩn cấp đang nháy đèn gần đến mức nào?","o":["Không gần hơn 100 feet","Không gần hơn 500 feet","Không gần hơn 50 feet","Gần bao nhiêu cũng được nếu bạn cẩn thận"],"h1":"Khoảng cách này dài hơn một dãy phố trong thành phố.","h2":"Ở Virginia, bạn không bao giờ được đi theo sau xe khẩn cấp đang nháy đèn gần hơn 500 feet.","p":"Đúng. Hãy ở phía sau xe đó ít nhất 500 feet."},"tl":{"q":"Sa Virginia, gaano kalapit ka puwedeng sumunod sa emergency vehicle na kumikislap ang mga ilaw?","o":["Hindi lalapit sa 100 talampakan","Hindi lalapit sa 500 talampakan","Hindi lalapit sa 50 talampakan","Kahit gaano kalapit basta mag-ingat ka"],"h1":"Mas mahaba ang layo kaysa sa isang city block.","h2":"Sa Virginia, hindi ka dapat sumunod sa emergency vehicle na kumikislap ang mga ilaw nang mas malapit sa 500 talampakan.","p":"Tama. Manatili nang hindi bababa sa 500 talampakan sa likod nito."},"ar":{"q":"في Virginia، إلى أي مدى يمكنك أن تقترب وأنت تسير خلف مركبة طوارئ أضواؤها تومض؟","o":["ليس أقرب من 100 قدم","ليس أقرب من 500 قدم","ليس أقرب من 50 قدمًا","بالقرب الذي تريده إذا كنت حذرًا"],"h1":"المسافة أطول من شارع واحد في المدينة.","h2":"في Virginia، لا يجوز لك أبدًا أن تسير خلف مركبة طوارئ أضواؤها تومض على مسافة أقرب من 500 قدم.","p":"صحيح. ابقَ خلفها بمسافة 500 قدم على الأقل."},"ref":{"doc":"VA","page":16}},{"id":"va-029","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, you want to pass a bicyclist, but the lane is too narrow to leave 3 feet. What must you do?","o":["Honk and pass anyway","Drive in the bike lane to pass","Pass quickly with less space","Change lanes to pass safely"],"h1":"The 3-foot rule still applies.","h2":"In Virginia, you must give a bicyclist at least three feet when passing, and if the lane is too narrow for that, you must change lanes to pass.","p":"Right. Change lanes if you cannot leave 3 feet."},"es":{"q":"En Virginia, quiere rebasar a un ciclista, pero el carril es muy angosto para dejar 3 pies. ¿Qué debe hacer?","o":["Tocar la bocina y rebasar de todos modos","Usar el carril de bicicletas para rebasar","Rebasar rápido con menos espacio","Cambiarse de carril para rebasar con seguridad"],"h1":"La regla de los 3 pies sigue vigente.","h2":"En Virginia, debe dejar por lo menos tres pies al rebasar a un ciclista, y si el carril es muy angosto para eso, debe cambiarse de carril para rebasar.","p":"Correcto. Cámbiese de carril si no puede dejar 3 pies."},"zh":{"q":"在 Virginia，你想超过一个骑自行车的人，但车道太窄，留不出 3 英尺。你必须怎么做？","o":["按喇叭，照样超车","开进自行车道去超车","留更小的空间快速超过","换车道，安全地超车"],"h1":"3 英尺的规定仍然有效。","h2":"在 Virginia，超过骑自行车的人时必须留出至少 3 英尺；如果车道太窄做不到，你必须换车道再超车。","p":"对。留不出 3 英尺就换车道。"},"vi":{"q":"Ở Virginia, bạn muốn vượt người đi xe đạp, nhưng làn đường quá hẹp để chừa 3 feet. Bạn phải làm gì?","o":["Bấm còi và cứ vượt","Chạy vào làn xe đạp để vượt","Vượt nhanh với khoảng cách ít hơn","Chuyển làn để vượt an toàn"],"h1":"Quy định 3 feet vẫn áp dụng.","h2":"Ở Virginia, khi vượt người đi xe đạp bạn phải chừa ít nhất 3 feet, và nếu làn đường quá hẹp để làm vậy thì bạn phải chuyển làn để vượt.","p":"Đúng. Nếu không chừa được 3 feet thì hãy chuyển làn."},"tl":{"q":"Sa Virginia, gusto mong lampasan ang isang nagbibisikleta, pero masyadong makitid ang lane para mag-iwan ng 3 talampakan. Ano ang dapat mong gawin?","o":["Bumusina at lumampas pa rin","Magmaneho sa bike lane para lumampas","Lumampas nang mabilis na mas maliit ang agwat","Lumipat ng lane para ligtas na lumampas"],"h1":"May bisa pa rin ang patakaran na 3 talampakan.","h2":"Sa Virginia, dapat kang mag-iwan ng hindi bababa sa 3 talampakan kapag lumalampas sa nagbibisikleta, at kung masyadong makitid ang lane para doon, dapat kang lumipat ng lane para lumampas.","p":"Tama. Lumipat ng lane kung hindi ka makapag-iwan ng 3 talampakan."},"ar":{"q":"في Virginia، تريد أن تتجاوز راكب دراجة، لكن الحارة ضيقة جدًا ولا تسمح بترك 3 أقدام. ماذا يجب أن تفعل؟","o":["تطلق البوق وتتجاوز على أي حال","تسير في حارة الدراجات لتتجاوز","تتجاوز بسرعة مع مسافة أقل","تغيّر الحارة لتتجاوز بأمان"],"h1":"قاعدة الأقدام الثلاثة ما زالت سارية.","h2":"في Virginia، يجب أن تترك 3 أقدام على الأقل عند تجاوز راكب دراجة، وإذا كانت الحارة ضيقة جدًا لذلك، يجب أن تغيّر الحارة لتتجاوز.","p":"صحيح. غيّر الحارة إذا لم تستطع ترك 3 أقدام."},"ref":{"doc":"VA","page":20}},{"id":"va-030","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, on a two-lane road, you come up on a stopped trash truck collecting garbage. What must you do?","o":["Slow to 10 mph below the limit and pass at least 2 feet away","Keep your speed and pass close to it","Stop and wait until it drives away","Honk so the workers move aside"],"h1":"You need to lower your speed and leave a gap.","h2":"In Virginia, if you cannot change lanes around a stopped trash truck, you must slow to 10 mph below the speed limit and pass at least two feet to its left.","p":"Right. Slow down by 10 mph and leave at least 2 feet."},"es":{"q":"En Virginia, en una vía de dos carriles, se acerca a un camión de basura detenido que recoge basura. ¿Qué debe hacer?","o":["Bajar a 10 mph menos del límite y pasar a por lo menos 2 pies","Mantener su velocidad y pasar cerca","Detenerse y esperar a que se vaya","Tocar la bocina para que los trabajadores se aparten"],"h1":"Debe bajar la velocidad y dejar espacio.","h2":"En Virginia, si no puede cambiarse de carril junto a un camión de basura detenido, debe bajar a 10 mph menos del límite y pasar por lo menos a dos pies a su izquierda.","p":"Correcto. Baje 10 mph y deje por lo menos 2 pies."},"zh":{"q":"在 Virginia，在双车道的路上，你遇到一辆停着收垃圾的垃圾车。你必须怎么做？","o":["减速到比限速低 10 mph，并在至少 2 英尺外超过","保持车速，贴近它超过","停下来，等它开走","按喇叭让工人让开"],"h1":"你需要降低车速，并留出空隙。","h2":"在 Virginia，如果你不能换车道绕过停着的垃圾车，你必须减速到比限速低 10 mph，并在它左边至少 2 英尺外超过。","p":"对。减速 10 mph，并留出至少 2 英尺。"},"vi":{"q":"Ở Virginia, trên đường hai làn, bạn gặp một xe rác đang dừng để gom rác. Bạn phải làm gì?","o":["Giảm xuống thấp hơn tốc độ giới hạn 10 mph và vượt cách xa ít nhất 2 feet","Giữ tốc độ và vượt sát xe đó","Dừng lại và chờ đến khi xe chạy đi","Bấm còi để công nhân tránh ra"],"h1":"Bạn cần giảm tốc độ và chừa khoảng cách.","h2":"Ở Virginia, nếu bạn không thể chuyển làn để đi vòng qua xe rác đang dừng, bạn phải giảm xuống thấp hơn tốc độ giới hạn 10 mph và vượt cách bên trái xe đó ít nhất 2 feet.","p":"Đúng. Giảm 10 mph và chừa ít nhất 2 feet."},"tl":{"q":"Sa Virginia, sa kalsadang may dalawang lane, nakasalubong mo ang nakahintong trak ng basura na nangongolekta ng basura. Ano ang dapat mong gawin?","o":["Bumagal sa 10 mph na mas mababa sa limit at lumampas nang hindi bababa sa 2 talampakan ang layo","Panatilihin ang bilis at lumampas nang malapit dito","Huminto at maghintay hanggang umalis ito","Bumusina para tumabi ang mga manggagawa"],"h1":"Kailangan mong bawasan ang bilis at mag-iwan ng agwat.","h2":"Sa Virginia, kung hindi ka makalipat ng lane para iwasan ang nakahintong trak ng basura, dapat kang bumagal sa 10 mph na mas mababa sa speed limit at lumampas nang hindi bababa sa 2 talampakan sa kaliwa nito.","p":"Tama. Bumagal nang 10 mph at mag-iwan ng hindi bababa sa 2 talampakan."},"ar":{"q":"في Virginia، على طريق بحارتين، تصل إلى شاحنة قمامة متوقفة تجمع القمامة. ماذا يجب أن تفعل؟","o":["تخفّض سرعتك إلى أقل من الحد بمقدار 10 mph وتتجاوز على بُعد 2 قدم على الأقل","تحافظ على سرعتك وتتجاوز قريبًا منها","تتوقف وتنتظر حتى تبتعد","تطلق البوق ليبتعد العمّال"],"h1":"عليك أن تخفّض سرعتك وأن تترك مسافة.","h2":"في Virginia، إذا لم تستطع تغيير الحارة لتمرّ حول شاحنة قمامة متوقفة، يجب أن تخفّض سرعتك إلى أقل من الحد الأقصى بمقدار 10 mph وأن تتجاوز على بُعد 2 قدم على الأقل إلى يسارها.","p":"صحيح. خفّف سرعتك بمقدار 10 mph واترك 2 قدم على الأقل."},"ref":{"doc":"VA","page":16}},{"id":"va-031","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, when must you turn on your headlights during the day?","o":["Only on the interstate","Only in a work zone","When your wipers are on because of bad weather","Only when it snows"],"h1":"Think about rain and what you use to clear the windshield.","h2":"In Virginia, you must use your headlights whenever you use your windshield wipers because of bad weather, and when rain, fog or snow cut visibility to 500 feet.","p":"Right. Wipers on for bad weather means headlights on."},"es":{"q":"En Virginia, ¿cuándo debe encender los faros durante el día?","o":["Solo en la autopista interestatal","Solo en una zona de obras","Cuando usa los limpiaparabrisas por mal tiempo","Solo cuando nieva"],"h1":"Piense en la lluvia y en lo que usa para limpiar el parabrisas.","h2":"En Virginia, debe usar los faros siempre que use los limpiaparabrisas por mal tiempo, y cuando la lluvia, la neblina o la nieve reducen la visibilidad a 500 pies.","p":"Correcto. Limpiaparabrisas por mal tiempo significa faros encendidos."},"zh":{"q":"在 Virginia，白天什么时候必须打开大灯？","o":["只在州际公路上","只在施工区","因为天气不好而开着雨刷的时候","只在下雪的时候"],"h1":"想一想下雨，以及你用什么来清理挡风玻璃。","h2":"在 Virginia，只要你因为天气不好而使用雨刷，就必须打开大灯；当雨、雾或雪让能见度降到 500 英尺时也必须打开。","p":"对。因为天气不好开雨刷，就要开大灯。"},"vi":{"q":"Ở Virginia, ban ngày khi nào bạn phải bật đèn pha?","o":["Chỉ trên xa lộ liên bang","Chỉ trong khu vực đang thi công","Khi bạn bật cần gạt nước vì thời tiết xấu","Chỉ khi có tuyết rơi"],"h1":"Hãy nghĩ đến trời mưa và thứ bạn dùng để làm sạch kính chắn gió.","h2":"Ở Virginia, bạn phải bật đèn pha mỗi khi dùng cần gạt nước vì thời tiết xấu, và khi mưa, sương mù hoặc tuyết làm tầm nhìn giảm còn 500 feet.","p":"Đúng. Bật cần gạt nước vì thời tiết xấu thì phải bật đèn pha."},"tl":{"q":"Sa Virginia, kailan mo dapat buksan ang headlights sa araw?","o":["Sa interstate lang","Sa work zone lang","Kapag naka-on ang wipers mo dahil sa masamang panahon","Kapag umuulan lang ng niyebe"],"h1":"Isipin ang ulan at ang ginagamit mo para linisin ang windshield.","h2":"Sa Virginia, dapat mong gamitin ang headlights tuwing ginagamit mo ang windshield wipers dahil sa masamang panahon, at kapag ang ulan, hamog o niyebe ay nagpababa ng visibility sa 500 talampakan.","p":"Tama. Kapag naka-on ang wipers dahil sa masamang panahon, dapat naka-on din ang headlights."},"ar":{"q":"في Virginia، متى يجب أن تشغّل المصابيح الأمامية أثناء النهار؟","o":["على الطريق السريع بين الولايات فقط","في منطقة أعمال الطرق فقط","عندما تكون المسّاحات تعمل بسبب سوء الطقس","عندما يتساقط الثلج فقط"],"h1":"فكّر في المطر وفي ما تستخدمه لتنظيف الزجاج الأمامي.","h2":"في Virginia، يجب أن تستخدم المصابيح الأمامية كلما استخدمت مسّاحات الزجاج الأمامي بسبب سوء الطقس، وعندما يقلّل المطر أو الضباب أو الثلج مدى الرؤية إلى 500 قدم.","p":"صحيح. إذا شغّلت المسّاحات بسبب سوء الطقس فشغّل المصابيح الأمامية."},"ref":{"doc":"VA","page":22}},{"id":"va-032","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, if no sign says otherwise, what is the speed limit in a residential area?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is the same limit as in school and business areas.","h2":"In Virginia, when no sign shows a different limit, the speed limit in residential, business and school areas is 25 mph.","p":"Right. With no sign, a Virginia neighborhood street is 25 mph."},"es":{"q":"En Virginia, si ninguna señal indica otra cosa, ¿cuál es el límite de velocidad en una zona residencial?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es el mismo límite que en las zonas escolares y comerciales.","h2":"En Virginia, cuando ninguna señal muestra otro límite, el límite de velocidad en zonas residenciales, comerciales y escolares es de 25 mph.","p":"Correcto. Sin señal, una calle de barrio en Virginia es de 25 mph."},"zh":{"q":"在 Virginia，如果没有路牌另外说明，住宅区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它和学校区、商业区的限速一样。","h2":"在 Virginia，如果没有路牌标示其他限速，住宅区、商业区和学校区的限速是 25 mph。","p":"对。没有路牌时，Virginia 住宅区街道的限速是 25 mph。"},"vi":{"q":"Ở Virginia, nếu không có biển báo nào ghi khác, tốc độ giới hạn trong khu dân cư là bao nhiêu?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Đó là cùng mức giới hạn như ở khu trường học và khu kinh doanh.","h2":"Ở Virginia, khi không có biển báo ghi mức giới hạn khác, tốc độ giới hạn trong khu dân cư, khu kinh doanh và khu trường học là 25 mph.","p":"Đúng. Khi không có biển báo, đường trong khu dân cư ở Virginia có giới hạn 25 mph."},"tl":{"q":"Sa Virginia, kung walang sign na nagsasabi ng iba, ano ang speed limit sa residential area?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Pareho ito ng limit sa mga school at business area.","h2":"Sa Virginia, kapag walang sign na nagpapakita ng ibang limit, ang speed limit sa residential, business at school area ay 25 mph.","p":"Tama. Kapag walang sign, 25 mph ang kalye sa isang neighborhood sa Virginia."},"ar":{"q":"في Virginia، إذا لم تذكر لافتة غير ذلك، ما حد السرعة في منطقة سكنية؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"إنه نفس الحد في مناطق المدارس والمناطق التجارية.","h2":"في Virginia، عندما لا توجد لافتة تبيّن حدًا مختلفًا، يكون حد السرعة في المناطق السكنية والتجارية ومناطق المدارس 25 mph.","p":"صحيح. بدون لافتة، حد السرعة في شارع حيّ سكني في Virginia هو 25 mph."},"ref":{"doc":"VA","page":15}},{"id":"va-033","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, if no sign says otherwise, what is the speed limit on an unpaved road?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"It is 10 mph more than the limit in a neighborhood.","h2":"In Virginia, when no sign shows a different limit, the speed limit on an unpaved road is 35 mph.","p":"Right. With no sign, a Virginia dirt or gravel road is 35 mph."},"es":{"q":"En Virginia, si ninguna señal indica otra cosa, ¿cuál es el límite de velocidad en un camino sin pavimentar?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Es 10 mph más que el límite en un barrio.","h2":"En Virginia, cuando ninguna señal muestra otro límite, el límite de velocidad en un camino sin pavimentar es de 35 mph.","p":"Correcto. Sin señal, un camino de tierra o grava en Virginia es de 35 mph."},"zh":{"q":"在 Virginia，如果没有路牌另外说明，没有铺路面的道路限速是多少？","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"它比住宅区的限速多 10 mph。","h2":"在 Virginia，如果没有路牌标示其他限速，没有铺路面的道路限速是 35 mph。","p":"对。没有路牌时，Virginia 的土路或碎石路限速是 35 mph。"},"vi":{"q":"Ở Virginia, nếu không có biển báo nào ghi khác, tốc độ giới hạn trên đường không trải nhựa là bao nhiêu?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Nó cao hơn giới hạn trong khu dân cư 10 mph.","h2":"Ở Virginia, khi không có biển báo ghi mức giới hạn khác, tốc độ giới hạn trên đường không trải nhựa là 35 mph.","p":"Đúng. Khi không có biển báo, đường đất hoặc đường sỏi ở Virginia có giới hạn 35 mph."},"tl":{"q":"Sa Virginia, kung walang sign na nagsasabi ng iba, ano ang speed limit sa daang hindi sementado?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Mas mataas ito nang 10 mph kaysa sa limit sa isang neighborhood.","h2":"Sa Virginia, kapag walang sign na nagpapakita ng ibang limit, ang speed limit sa daang hindi sementado ay 35 mph.","p":"Tama. Kapag walang sign, 35 mph ang daang lupa o graba sa Virginia."},"ar":{"q":"في Virginia، إذا لم تذكر لافتة غير ذلك، ما حد السرعة على طريق غير معبّد؟","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"إنه أكثر بـ10 mph من الحد في حيّ سكني.","h2":"في Virginia، عندما لا توجد لافتة تبيّن حدًا مختلفًا، يكون حد السرعة على الطريق غير المعبّد 35 mph.","p":"صحيح. بدون لافتة، حد السرعة على طريق ترابي أو حصوي في Virginia هو 35 mph."},"ref":{"doc":"VA","page":15}},{"id":"va-034","scope":"VA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Virginia, a driver is convicted of going 83 mph where the limit is 65 mph. What extra penalty does the law add?","o":["An extra $100 fine","An extra $25 fine","No extra penalty","An extra 30 days in jail"],"h1":"It is an added fine for driving between 81 and 85 mph in a 65 mph zone.","h2":"In Virginia, a driver convicted of going between 81 and 85 mph in a 65 mph zone pays an extra $100 fine.","p":"Right. Driving 81 to 85 mph in a 65 zone adds a $100 fine in Virginia."},"es":{"q":"En Virginia, un conductor es condenado por ir a 83 mph donde el límite es de 65 mph. ¿Qué castigo adicional agrega la ley?","o":["Una multa adicional de $100","Una multa adicional de $25","Ningún castigo adicional","30 días adicionales de cárcel"],"h1":"Es una multa añadida por manejar entre 81 y 85 mph en una zona de 65 mph.","h2":"En Virginia, un conductor condenado por ir entre 81 y 85 mph en una zona de 65 mph paga una multa adicional de $100.","p":"Correcto. Manejar de 81 a 85 mph en una zona de 65 agrega una multa de $100 en Virginia."},"zh":{"q":"在 Virginia，一名司机在限速 65 mph 的地方开到 83 mph 被定罪。法律会额外加什么处罚？","o":["额外罚款 $100","额外罚款 $25","没有额外处罚","额外坐牢 30 天"],"h1":"这是在 65 mph 区域开到 81 到 85 mph 之间要加的罚款。","h2":"在 Virginia，在 65 mph 区域开到 81 到 85 mph 之间被定罪的司机，要额外付 $100 罚款。","p":"对。在 Virginia 的 65 mph 区域开到 81 到 85 mph，会加罚 $100。"},"vi":{"q":"Ở Virginia, một tài xế bị kết tội chạy 83 mph ở nơi có giới hạn 65 mph. Luật thêm hình phạt gì?","o":["Phạt thêm $100","Phạt thêm $25","Không có hình phạt thêm","Thêm 30 ngày tù"],"h1":"Đó là tiền phạt thêm khi lái từ 81 đến 85 mph trong khu vực 65 mph.","h2":"Ở Virginia, tài xế bị kết tội chạy từ 81 đến 85 mph trong khu vực 65 mph phải trả thêm $100 tiền phạt.","p":"Đúng. Ở Virginia, lái 81 đến 85 mph trong khu vực 65 mph bị phạt thêm $100."},"tl":{"q":"Sa Virginia, nahatulan ang isang driver sa pagmamaneho nang 83 mph kung saan 65 mph ang limit. Anong dagdag na parusa ang idinadagdag ng batas?","o":["Dagdag na multang $100","Dagdag na multang $25","Walang dagdag na parusa","Dagdag na 30 araw sa kulungan"],"h1":"Ito ay dagdag na multa sa pagmamaneho nang 81 hanggang 85 mph sa 65 mph zone.","h2":"Sa Virginia, ang driver na nahatulan sa pagmamaneho nang 81 hanggang 85 mph sa 65 mph zone ay magbabayad ng dagdag na multang $100.","p":"Tama. Sa Virginia, ang pagmamaneho nang 81 hanggang 85 mph sa 65 mph zone ay may dagdag na multang $100."},"ar":{"q":"في Virginia، أُدين سائق بالقيادة بسرعة 83 mph في مكان حدّه 65 mph. ما العقوبة الإضافية التي يضيفها القانون؟","o":["غرامة إضافية $100","غرامة إضافية $25","لا توجد عقوبة إضافية","30 يومًا إضافية في السجن"],"h1":"إنها غرامة مضافة للقيادة بين 81 و85 mph في منطقة حدّها 65 mph.","h2":"في Virginia، السائق الذي يُدان بالقيادة بسرعة بين 81 و85 mph في منطقة حدّها 65 mph يدفع غرامة إضافية قدرها $100.","p":"صحيح. القيادة بسرعة 81 إلى 85 mph في منطقة حدّها 65 mph تضيف غرامة $100 في Virginia."},"ref":{"doc":"VA","page":14}},{"id":"va-035","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, what is the highest fine for speeding in a highway work zone?","o":["Up to $100","Up to $250","Up to $500","Up to $2,500"],"h1":"It is twice the fine for holding a phone in a work zone.","h2":"In Virginia, a driver convicted of speeding in a highway work zone can be fined up to $500.","p":"Right. Speeding in a Virginia work zone can cost up to $500."},"es":{"q":"En Virginia, ¿cuál es la multa más alta por exceso de velocidad en una zona de obras en la carretera?","o":["Hasta $100","Hasta $250","Hasta $500","Hasta $2,500"],"h1":"Es el doble de la multa por sostener un teléfono en una zona de obras.","h2":"En Virginia, a un conductor condenado por exceso de velocidad en una zona de obras en la carretera se le puede multar con hasta $500.","p":"Correcto. Ir con exceso de velocidad en una zona de obras en Virginia puede costar hasta $500."},"zh":{"q":"在 Virginia，在高速公路施工区超速，最高罚款是多少？","o":["最多 $100","最多 $250","最多 $500","最多 $2,500"],"h1":"它是在施工区拿着手机的罚款的两倍。","h2":"在 Virginia，在高速公路施工区超速被定罪的司机，最高可被罚款 $500。","p":"对。在 Virginia 的施工区超速，最多可罚 $500。"},"vi":{"q":"Ở Virginia, tiền phạt cao nhất cho việc chạy quá tốc độ trong khu vực thi công trên xa lộ là bao nhiêu?","o":["Tối đa $100","Tối đa $250","Tối đa $500","Tối đa $2,500"],"h1":"Nó gấp đôi tiền phạt cầm điện thoại trong khu vực thi công.","h2":"Ở Virginia, tài xế bị kết tội chạy quá tốc độ trong khu vực thi công trên xa lộ có thể bị phạt tối đa $500.","p":"Đúng. Chạy quá tốc độ trong khu vực thi công ở Virginia có thể bị phạt tới $500."},"tl":{"q":"Sa Virginia, ano ang pinakamataas na multa sa pag-speeding sa work zone ng highway?","o":["Hanggang $100","Hanggang $250","Hanggang $500","Hanggang $2,500"],"h1":"Doble ito ng multa sa paghawak ng telepono sa work zone.","h2":"Sa Virginia, ang driver na nahatulan sa pag-speeding sa work zone ng highway ay puwedeng pagmultahin nang hanggang $500.","p":"Tama. Ang pag-speeding sa work zone sa Virginia ay puwedeng magkahalaga ng hanggang $500."},"ar":{"q":"في Virginia، ما أعلى غرامة لتجاوز السرعة في منطقة أعمال على طريق سريع؟","o":["حتى $100","حتى $250","حتى $500","حتى $2,500"],"h1":"إنها ضعف غرامة إمساك الهاتف في منطقة أعمال.","h2":"في Virginia، السائق الذي يُدان بتجاوز السرعة في منطقة أعمال على طريق سريع قد يُغرَّم حتى $500.","p":"صحيح. تجاوز السرعة في منطقة أعمال في Virginia قد يكلّف حتى $500."},"ref":{"doc":"VA","page":10}},{"id":"va-036","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, you use a shared center lane to make a left turn. How far may you drive in that lane?","o":["Up to 50 feet","No more than 150 feet","Up to 500 feet","As far as you need"],"h1":"It is about half the length of a football field.","h2":"In Virginia, you may use a shared center left-turn lane for no more than 150 feet.","p":"Right. Stay in a Virginia center turn lane for 150 feet at most."},"es":{"q":"En Virginia, usted usa un carril central compartido para girar a la izquierda. ¿Qué distancia puede recorrer en ese carril?","o":["Hasta 50 pies","No más de 150 pies","Hasta 500 pies","Toda la que necesite"],"h1":"Es más o menos la mitad del largo de un campo de fútbol americano.","h2":"En Virginia, puede usar un carril central compartido para girar a la izquierda por no más de 150 pies.","p":"Correcto. En Virginia, quédese en un carril central de giro 150 pies como máximo."},"zh":{"q":"在 Virginia，你用中间共用车道来左转。你在这条车道上最多可以开多远？","o":["最多 50 英尺","不超过 150 英尺","最多 500 英尺","你需要多远就多远"],"h1":"大约是半个美式足球场的长度。","h2":"在 Virginia，你在中间共用左转车道上行驶不可以超过 150 英尺。","p":"对。在 Virginia 的中间转弯车道上，最多只开 150 英尺。"},"vi":{"q":"Ở Virginia, bạn dùng làn giữa dùng chung để rẽ trái. Bạn được lái trong làn đó bao xa?","o":["Tối đa 50 feet","Không quá 150 feet","Tối đa 500 feet","Xa bao nhiêu tùy bạn cần"],"h1":"Khoảng một nửa chiều dài sân bóng bầu dục.","h2":"Ở Virginia, bạn chỉ được dùng làn rẽ trái ở giữa dùng chung không quá 150 feet.","p":"Đúng. Ở Virginia, chỉ ở trong làn rẽ ở giữa nhiều nhất 150 feet."},"tl":{"q":"Sa Virginia, gumagamit ka ng shared center lane para kumaliwa. Gaano kalayo ka puwedeng magmaneho sa lane na iyon?","o":["Hanggang 50 talampakan","Hindi hihigit sa 150 talampakan","Hanggang 500 talampakan","Hanggang kailangan mo"],"h1":"Mga kalahati ito ng haba ng football field.","h2":"Sa Virginia, puwede mong gamitin ang shared center left-turn lane nang hindi hihigit sa 150 talampakan.","p":"Tama. Sa Virginia, manatili sa center turn lane nang 150 talampakan lang ang pinakamalayo."},"ar":{"q":"في Virginia، تستخدم الحارة الوسطى المشتركة لتنعطف يسارًا. ما المسافة التي يمكنك أن تقودها في تلك الحارة؟","o":["حتى 50 قدمًا","ليس أكثر من 150 قدمًا","حتى 500 قدم","المسافة التي تحتاجها"],"h1":"إنها نحو نصف طول ملعب كرة القدم الأمريكية.","h2":"في Virginia، يمكنك أن تستخدم حارة الانعطاف يسارًا الوسطى المشتركة لمسافة لا تزيد على 150 قدمًا.","p":"صحيح. في Virginia، ابقَ في حارة الانعطاف الوسطى 150 قدمًا على الأكثر."},"ref":{"doc":"VA","page":12}},{"id":"va-037","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, how close to a fire hydrant may you park?","o":["5 feet","10 feet","25 feet","No closer than 15 feet"],"h1":"It is a little more than the length of a small car.","h2":"In Virginia, you may not park within 15 feet of a fire hydrant.","p":"Right. In Virginia, park at least 15 feet from a fire hydrant."},"es":{"q":"En Virginia, ¿a qué distancia de un hidrante de incendios puede estacionarse?","o":["5 pies","10 pies","25 pies","No más cerca de 15 pies"],"h1":"Es un poco más que el largo de un carro pequeño.","h2":"En Virginia, no puede estacionarse a menos de 15 pies de un hidrante de incendios.","p":"Correcto. En Virginia, estaciónese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Virginia，你可以把车停在离消防栓多近的地方？","o":["5 英尺","10 英尺","25 英尺","不可以近于 15 英尺"],"h1":"比一辆小汽车的长度多一点。","h2":"在 Virginia，你不可以把车停在离消防栓 15 英尺以内的地方。","p":"对。在 Virginia，停车要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Virginia, bạn được đỗ xe gần trụ nước cứu hỏa đến mức nào?","o":["5 feet","10 feet","25 feet","Không gần hơn 15 feet"],"h1":"Dài hơn một chiếc xe nhỏ một chút.","h2":"Ở Virginia, bạn không được đỗ xe trong vòng 15 feet tính từ trụ nước cứu hỏa.","p":"Đúng. Ở Virginia, đỗ xe cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Virginia, gaano kalapit sa fire hydrant ka puwedeng pumarada?","o":["5 talampakan","10 talampakan","25 talampakan","Hindi mas malapit sa 15 talampakan"],"h1":"Medyo mas mahaba ito sa haba ng isang maliit na kotse.","h2":"Sa Virginia, hindi ka puwedeng pumarada sa loob ng 15 talampakan mula sa fire hydrant.","p":"Tama. Sa Virginia, pumarada nang hindi bababa sa 15 talampakan mula sa fire hydrant."},"ar":{"q":"في Virginia، على أي مسافة من صنبور إطفاء الحريق يمكنك أن تركن سيارتك؟","o":["5 أقدام","10 أقدام","25 قدمًا","ليس أقرب من 15 قدمًا"],"h1":"إنها أكثر قليلًا من طول سيارة صغيرة.","h2":"في Virginia، يجب ألّا تركن سيارتك على بُعد أقل من 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. في Virginia، اركن على بُعد 15 قدمًا على الأقل من صنبور إطفاء الحريق."},"ref":{"doc":"VA","page":22}},{"id":"va-038","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, the road has double solid yellow center lines. When may you cross them to pass?","o":["Never, for any reason","To pass a slow car when no one is coming","To pass a bicyclist when the other lane is clear and it is safe","Only at night"],"h1":"The exception is for people who are not in cars.","h2":"In Virginia, you may cross double solid yellow lines to pass a bicyclist, a pedestrian, or a scooter or skateboard rider when the other lane is clear and it is safe.","p":"Right. In Virginia, you may cross the double yellow only to pass someone like a bicyclist, when it is clear and safe."},"es":{"q":"En Virginia, la carretera tiene doble línea amarilla continua en el centro. ¿Cuándo puede cruzarla para rebasar?","o":["Nunca, por ningún motivo","Para rebasar un carro lento cuando no viene nadie","Para rebasar a un ciclista cuando el otro carril está libre y es seguro","Solo de noche"],"h1":"La excepción es para personas que no van en carros.","h2":"En Virginia, puede cruzar la doble línea amarilla continua para rebasar a un ciclista, a un peatón o a alguien en patineta o scooter cuando el otro carril está libre y es seguro.","p":"Correcto. En Virginia, solo puede cruzar la doble línea amarilla para rebasar a alguien como un ciclista, cuando está libre y es seguro."},"zh":{"q":"在 Virginia，道路中间有双实黄线。你什么时候可以越过它们去超车？","o":["无论什么原因都不可以","在没有来车时超过一辆慢车","在对面车道没有车而且安全时，超过骑自行车的人","只在晚上"],"h1":"例外是给不在汽车里的人的。","h2":"在 Virginia，当对面车道没有车而且安全时，你可以越过双实黄线去超过骑自行车的人、行人，或骑滑板车、玩滑板的人。","p":"对。在 Virginia，只有在没有车而且安全时，为了超过骑自行车的人这类人，才可以越过双黄线。"},"vi":{"q":"Ở Virginia, đường có hai vạch vàng liền ở giữa. Khi nào bạn được đi qua các vạch đó để vượt?","o":["Không bao giờ, vì bất cứ lý do gì","Để vượt một xe chạy chậm khi không có xe nào tới","Để vượt người đi xe đạp khi làn bên kia trống và an toàn","Chỉ vào ban đêm"],"h1":"Ngoại lệ là dành cho những người không ở trong xe hơi.","h2":"Ở Virginia, bạn được đi qua hai vạch vàng liền để vượt người đi xe đạp, người đi bộ, hoặc người đi xe scooter hay ván trượt khi làn bên kia trống và an toàn.","p":"Đúng. Ở Virginia, bạn chỉ được đi qua hai vạch vàng để vượt người như người đi xe đạp, khi đường trống và an toàn."},"tl":{"q":"Sa Virginia, may dobleng tuloy-tuloy na dilaw na guhit sa gitna ng daan. Kailan mo puwedeng tawirin ang mga ito para mag-overtake?","o":["Hindi kailanman, sa anumang dahilan","Para lampasan ang mabagal na kotse kapag walang paparating","Para lampasan ang nagbibisikleta kapag malinaw ang kabilang lane at ligtas","Sa gabi lang"],"h1":"Ang eksepsiyon ay para sa mga taong wala sa kotse.","h2":"Sa Virginia, puwede mong tawirin ang dobleng tuloy-tuloy na dilaw na guhit para lampasan ang nagbibisikleta, naglalakad, o nakasakay sa scooter o skateboard kapag malinaw ang kabilang lane at ligtas.","p":"Tama. Sa Virginia, puwede mo lang tawirin ang dobleng dilaw para lampasan ang tulad ng nagbibisikleta, kapag malinaw at ligtas."},"ar":{"q":"في Virginia، في وسط الطريق خطّان أصفران متصلان. متى يمكنك أن تعبرهما لتتجاوز؟","o":["أبدًا، لأي سبب","لتتجاوز سيارة بطيئة عندما لا يأتي أحد","لتتجاوز راكب دراجة هوائية عندما تكون الحارة الأخرى خالية ويكون ذلك آمنًا","في الليل فقط"],"h1":"الاستثناء للأشخاص الذين ليسوا في سيارات.","h2":"في Virginia، يمكنك أن تعبر الخطين الأصفرين المتصلين لتتجاوز راكب دراجة هوائية أو شخصًا يمشي أو راكب سكوتر أو لوح تزلج، عندما تكون الحارة الأخرى خالية ويكون ذلك آمنًا.","p":"صحيح. في Virginia، يمكنك أن تعبر الخطين الأصفرين فقط لتتجاوز شخصًا مثل راكب دراجة هوائية، عندما يكون الطريق خاليًا وآمنًا."},"ref":{"doc":"VA","page":11}},{"id":"va-039","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, what is the law about radar detectors in cars?","o":["They are illegal","They are allowed for everyone","They are allowed only on interstates","They are allowed only for drivers over 21"],"h1":"Virginia does not let drivers use devices that warn of police radar.","h2":"In Virginia, it is illegal to use a radar detector.","p":"Right. Radar detectors are against the law in Virginia."},"es":{"q":"En Virginia, ¿qué dice la ley sobre los detectores de radar en los carros?","o":["Son ilegales","Están permitidos para todos","Están permitidos solo en las autopistas interestatales","Están permitidos solo para conductores mayores de 21 años"],"h1":"Virginia no deja que los conductores usen aparatos que avisan del radar de la policía.","h2":"En Virginia, es ilegal usar un detector de radar.","p":"Correcto. Los detectores de radar están prohibidos en Virginia."},"zh":{"q":"在 Virginia，关于车里的雷达测速探测器，法律是怎么规定的？","o":["它们是违法的","每个人都可以用","只能在州际公路上用","只有 21 岁以上的司机可以用"],"h1":"Virginia 不让司机使用会提醒警察雷达的装置。","h2":"在 Virginia，使用雷达测速探测器是违法的。","p":"对。在 Virginia，雷达测速探测器是违法的。"},"vi":{"q":"Ở Virginia, luật nói gì về máy dò radar trong xe?","o":["Chúng là bất hợp pháp","Ai cũng được dùng","Chỉ được dùng trên xa lộ liên bang","Chỉ tài xế trên 21 tuổi được dùng"],"h1":"Virginia không cho tài xế dùng thiết bị cảnh báo radar của cảnh sát.","h2":"Ở Virginia, dùng máy dò radar là bất hợp pháp.","p":"Đúng. Máy dò radar là trái luật ở Virginia."},"tl":{"q":"Sa Virginia, ano ang batas tungkol sa radar detector sa kotse?","o":["Ilegal ang mga ito","Puwede sa lahat","Puwede lang sa mga interstate","Puwede lang sa mga driver na lampas 21"],"h1":"Hindi pinapayagan ng Virginia ang mga driver na gumamit ng device na nagbababala tungkol sa radar ng pulis.","h2":"Sa Virginia, ilegal ang paggamit ng radar detector.","p":"Tama. Labag sa batas ang radar detector sa Virginia."},"ar":{"q":"في Virginia، ما القانون بشأن أجهزة كشف الرادار في السيارات؟","o":["إنها غير قانونية","مسموح بها للجميع","مسموح بها على الطرق السريعة بين الولايات فقط","مسموح بها فقط للسائقين الذين أعمارهم أكثر من 21 سنة"],"h1":"Virginia لا تسمح للسائقين باستخدام أجهزة تنبّه إلى رادار الشرطة.","h2":"في Virginia، استخدام جهاز كشف الرادار غير قانوني.","p":"صحيح. أجهزة كشف الرادار مخالفة للقانون في Virginia."},"ref":{"doc":"VA","page":14}},{"id":"va-040","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, you are following another car at night. Within what distance must you use low beams?","o":["50 feet","200 feet","1,000 feet","1 mile"],"h1":"It is less than half the distance used for oncoming cars.","h2":"In Virginia, you must switch to low beams when you are within 200 feet of the vehicle ahead of you.","p":"Right. Use low beams within 200 feet of a car you are following in Virginia."},"es":{"q":"En Virginia, usted va detrás de otro carro de noche. ¿A qué distancia debe usar las luces bajas?","o":["50 pies","200 pies","1,000 pies","1 milla"],"h1":"Es menos de la mitad de la distancia que se usa para los carros que vienen de frente.","h2":"En Virginia, debe cambiar a luces bajas cuando está a menos de 200 pies del vehículo que va delante de usted.","p":"Correcto. En Virginia, use las luces bajas a menos de 200 pies del carro que sigue."},"zh":{"q":"在 Virginia，晚上你跟在另一辆车后面。在多近的距离内你必须用近光灯？","o":["50 英尺","200 英尺","1,000 英尺","1 英里"],"h1":"它比对面来车时用的距离的一半还少。","h2":"在 Virginia，当你离前面的车 200 英尺以内时，必须换成近光灯。","p":"对。在 Virginia，跟车时在 200 英尺以内要用近光灯。"},"vi":{"q":"Ở Virginia, bạn đang chạy sau một xe khác vào ban đêm. Trong khoảng cách nào bạn phải dùng đèn cốt (đèn chiếu gần)?","o":["50 feet","200 feet","1,000 feet","1 dặm"],"h1":"Nó ít hơn một nửa khoảng cách dùng cho xe chạy ngược chiều.","h2":"Ở Virginia, bạn phải chuyển sang đèn cốt khi bạn ở trong vòng 200 feet sau xe phía trước.","p":"Đúng. Ở Virginia, dùng đèn cốt khi ở trong vòng 200 feet sau xe bạn đang chạy theo."},"tl":{"q":"Sa Virginia, may sinusundan kang kotse sa gabi. Sa loob ng anong layo mo dapat gamitin ang low beams?","o":["50 talampakan","200 talampakan","1,000 talampakan","1 milya"],"h1":"Kulang ito sa kalahati ng layong ginagamit para sa mga paparating na kotse.","h2":"Sa Virginia, dapat kang lumipat sa low beams kapag nasa loob ka ng 200 talampakan mula sa sasakyan sa unahan mo.","p":"Tama. Sa Virginia, gumamit ng low beams sa loob ng 200 talampakan mula sa kotseng sinusundan mo."},"ar":{"q":"في Virginia، تقود خلف سيارة أخرى في الليل. ضمن أي مسافة يجب أن تستخدم الأضواء المنخفضة؟","o":["50 قدمًا","200 قدم","1,000 قدم","1 ميل"],"h1":"إنها أقل من نصف المسافة المستخدمة مع السيارات القادمة من الاتجاه المقابل.","h2":"في Virginia، يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون على بُعد 200 قدم أو أقل من السيارة التي أمامك.","p":"صحيح. في Virginia، استخدم الأضواء المنخفضة ضمن 200 قدم من السيارة التي تتبعها."},"ref":{"doc":"VA","page":23}},{"id":"va-041","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver is convicted of aggressive driving. How long can the license be suspended?","o":["It cannot be suspended","Exactly one day","Five years","From 10 days up to six months"],"h1":"The shortest time is a little over a week.","h2":"In Virginia, a driver convicted of aggressive driving can lose the license for 10 days or for as long as six months.","p":"Right. Aggressive driving in Virginia can mean a suspension from 10 days to six months."},"es":{"q":"En Virginia, un conductor es condenado por manejo agresivo. ¿Por cuánto tiempo pueden suspenderle la licencia?","o":["No se la pueden suspender","Exactamente un día","Cinco años","De 10 días hasta seis meses"],"h1":"El tiempo más corto es un poco más de una semana.","h2":"En Virginia, a un conductor condenado por manejo agresivo le pueden suspender la licencia por 10 días o hasta por seis meses.","p":"Correcto. El manejo agresivo en Virginia puede significar una suspensión de 10 días a seis meses."},"zh":{"q":"在 Virginia，一名司机因攻击性驾驶被定罪。驾照可以被暂停多久？","o":["不能被暂停","正好一天","五年","从 10 天到六个月"],"h1":"最短的时间比一个星期多一点。","h2":"在 Virginia，因攻击性驾驶被定罪的司机，驾照可以被暂停 10 天，最长六个月。","p":"对。在 Virginia，攻击性驾驶可能被暂停驾照 10 天到六个月。"},"vi":{"q":"Ở Virginia, một tài xế bị kết tội lái xe hung hăng. Bằng lái có thể bị treo bao lâu?","o":["Không thể bị treo","Đúng một ngày","Năm năm","Từ 10 ngày đến sáu tháng"],"h1":"Thời gian ngắn nhất là hơn một tuần một chút.","h2":"Ở Virginia, tài xế bị kết tội lái xe hung hăng có thể bị treo bằng lái từ 10 ngày đến tối đa sáu tháng.","p":"Đúng. Lái xe hung hăng ở Virginia có thể bị treo bằng từ 10 ngày đến sáu tháng."},"tl":{"q":"Sa Virginia, nahatulan ang isang driver sa aggressive driving. Gaano katagal puwedeng masuspinde ang lisensya?","o":["Hindi ito puwedeng masuspinde","Eksaktong isang araw","Limang taon","Mula 10 araw hanggang anim na buwan"],"h1":"Ang pinakamaikling panahon ay medyo lampas sa isang linggo.","h2":"Sa Virginia, ang driver na nahatulan sa aggressive driving ay puwedeng mawalan ng lisensya nang 10 araw o hanggang anim na buwan.","p":"Tama. Ang aggressive driving sa Virginia ay puwedeng humantong sa suspensyon nang 10 araw hanggang anim na buwan."},"ar":{"q":"في Virginia، أُدين سائق بالقيادة العدوانية. كم مدة يمكن أن تُوقَف رخصته؟","o":["لا يمكن إيقافها","يوم واحد بالضبط","خمس سنوات","من 10 أيام حتى ستة أشهر"],"h1":"أقصر مدة أكثر قليلًا من أسبوع.","h2":"في Virginia، السائق الذي يُدان بالقيادة العدوانية قد تُوقَف رخصته لمدة 10 أيام أو حتى ستة أشهر.","p":"صحيح. القيادة العدوانية في Virginia قد تعني إيقاف الرخصة من 10 أيام إلى ستة أشهر."},"ref":{"doc":"VA","page":23}},{"id":"va-042","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, a driver refuses a breath test and is charged with DUI for the first time. How long is the license suspended right away?","o":["One day","30 days","Seven days","One year"],"h1":"It is about one week.","h2":"In Virginia, on a first DUI charge, refusing a breath test or having a BAC of 0.08 or more means an automatic seven-day license suspension.","p":"Right. A first offense brings an automatic seven-day suspension in Virginia."},"es":{"q":"En Virginia, un conductor se niega a una prueba de aliento y lo acusan de DUI por primera vez. ¿Por cuánto tiempo le suspenden la licencia de inmediato?","o":["Un día","30 días","Siete días","Un año"],"h1":"Es más o menos una semana.","h2":"En Virginia, en una primera acusación de DUI, negarse a la prueba de aliento o tener un nivel de alcohol de 0.08 o más significa una suspensión automática de la licencia por siete días.","p":"Correcto. Una primera infracción trae una suspensión automática de siete días en Virginia."},"zh":{"q":"在 Virginia，一名司机拒绝做呼气测试，并且第一次被控 DUI（酒后或药后驾驶）。驾照会马上被暂停多久？","o":["一天","30 天","七天","一年"],"h1":"大约一个星期。","h2":"在 Virginia，第一次被控 DUI 时，拒绝呼气测试或血液酒精浓度（BAC）在 0.08 或以上，驾照会被自动暂停七天。","p":"对。在 Virginia，第一次违规会自动暂停驾照七天。"},"vi":{"q":"Ở Virginia, một tài xế từ chối thử hơi thở và bị buộc tội DUI (lái xe khi say) lần đầu. Bằng lái bị treo ngay bao lâu?","o":["Một ngày","30 ngày","Bảy ngày","Một năm"],"h1":"Khoảng một tuần.","h2":"Ở Virginia, khi bị buộc tội DUI lần đầu, từ chối thử hơi thở hoặc có nồng độ cồn trong máu (BAC) từ 0.08 trở lên sẽ bị tự động treo bằng lái bảy ngày.","p":"Đúng. Ở Virginia, vi phạm lần đầu bị tự động treo bằng lái bảy ngày."},"tl":{"q":"Sa Virginia, tumanggi ang isang driver sa breath test at kinasuhan ng DUI sa unang pagkakataon. Gaano katagal agad masususpinde ang lisensya?","o":["Isang araw","30 araw","Pitong araw","Isang taon"],"h1":"Mga isang linggo ito.","h2":"Sa Virginia, sa unang kaso ng DUI, ang pagtanggi sa breath test o pagkakaroon ng BAC na 0.08 o higit pa ay nangangahulugan ng awtomatikong pitong araw na suspensyon ng lisensya.","p":"Tama. Ang unang paglabag ay may awtomatikong pitong araw na suspensyon sa Virginia."},"ar":{"q":"في Virginia، رفض سائق اختبار التنفّس ووُجّهت إليه تهمة القيادة تحت تأثير الكحول (DUI) لأول مرة. كم مدة تُوقَف رخصته فورًا؟","o":["يوم واحد","30 يومًا","سبعة أيام","سنة واحدة"],"h1":"إنها نحو أسبوع واحد.","h2":"في Virginia، عند أول تهمة DUI، رفض اختبار التنفّس أو وجود نسبة كحول في الدم (BAC) تبلغ 0.08 أو أكثر يعني إيقاف الرخصة تلقائيًا لمدة سبعة أيام.","p":"صحيح. المخالفة الأولى تؤدي إلى إيقاف تلقائي للرخصة لمدة سبعة أيام في Virginia."},"ref":{"doc":"VA","page":30}},{"id":"va-043","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, a driver is convicted of DUI with a child age 17 or younger in the car. What is added to the other penalties?","o":["Five more days in jail that cannot be skipped","Only a warning letter","A $10 fine","Nothing extra"],"h1":"The extra penalty is time in jail, and it is required.","h2":"In Virginia, a DUI conviction with a passenger age 17 or younger adds a mandatory five days in jail to all other penalties.","p":"Right. A child in the car adds five mandatory days in jail for a Virginia DUI."},"es":{"q":"En Virginia, un conductor es condenado por DUI con un menor de 17 años o menos en el carro. ¿Qué se agrega a los otros castigos?","o":["Cinco días más de cárcel que no se pueden evitar","Solo una carta de advertencia","Una multa de $10","Nada adicional"],"h1":"El castigo adicional es tiempo en la cárcel, y es obligatorio.","h2":"En Virginia, una condena por DUI con un pasajero de 17 años o menos agrega cinco días obligatorios de cárcel a todos los demás castigos.","p":"Correcto. Un menor en el carro agrega cinco días obligatorios de cárcel a un DUI en Virginia."},"zh":{"q":"在 Virginia，一名司机在车里有 17 岁或以下的孩子时被判 DUI。除了其他处罚，还会加什么？","o":["再坐牢五天，而且不能免除","只有一封警告信","$10 罚款","没有额外处罚"],"h1":"额外处罚是坐牢，而且是必须的。","h2":"在 Virginia，车上有 17 岁或以下乘客时被判 DUI，会在所有其他处罚之外，再加上强制坐牢五天。","p":"对。在 Virginia，DUI 时车里有孩子，会加上强制坐牢五天。"},"vi":{"q":"Ở Virginia, một tài xế bị kết tội DUI khi có trẻ em từ 17 tuổi trở xuống trong xe. Điều gì được thêm vào các hình phạt khác?","o":["Thêm năm ngày tù không được miễn","Chỉ một lá thư cảnh cáo","Phạt $10","Không có gì thêm"],"h1":"Hình phạt thêm là ngồi tù, và đó là bắt buộc.","h2":"Ở Virginia, bị kết tội DUI khi có hành khách từ 17 tuổi trở xuống sẽ bị thêm năm ngày tù bắt buộc, ngoài tất cả các hình phạt khác.","p":"Đúng. Ở Virginia, có trẻ em trong xe khi DUI sẽ bị thêm năm ngày tù bắt buộc."},"tl":{"q":"Sa Virginia, nahatulan ng DUI ang isang driver habang may batang edad 17 pababa sa kotse. Ano ang idinadagdag sa ibang parusa?","o":["Limang araw pa sa kulungan na hindi puwedeng laktawan","Isang sulat ng babala lang","Multang $10","Walang dagdag"],"h1":"Ang dagdag na parusa ay pagkakakulong, at sapilitan ito.","h2":"Sa Virginia, ang hatol na DUI na may pasaherong edad 17 pababa ay nagdadagdag ng sapilitang limang araw sa kulungan sa lahat ng ibang parusa.","p":"Tama. Kapag may bata sa kotse, may dagdag na sapilitang limang araw sa kulungan para sa DUI sa Virginia."},"ar":{"q":"في Virginia، أُدين سائق بتهمة DUI وكان معه في السيارة طفل عمره 17 سنة أو أقل. ماذا يُضاف إلى العقوبات الأخرى؟","o":["خمسة أيام أخرى في السجن لا يمكن تجنّبها","رسالة تحذير فقط","غرامة $10","لا شيء إضافي"],"h1":"العقوبة الإضافية هي وقت في السجن، وهي إلزامية.","h2":"في Virginia، الإدانة بتهمة DUI مع راكب عمره 17 سنة أو أقل تضيف خمسة أيام إلزامية في السجن إلى كل العقوبات الأخرى.","p":"صحيح. وجود طفل في السيارة يضيف خمسة أيام إلزامية في السجن عند الإدانة بتهمة DUI في Virginia."},"ref":{"doc":"VA","page":30}},{"id":"va-044","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, children under what age must ride in a child safety seat or booster seat?","o":["Under 4","Under 8","Under 12","Under 16"],"h1":"Think of a child in second or third grade.","h2":"In Virginia, all children under age 8 must be secured in a child safety seat or a booster seat.","p":"Right. Virginia children under 8 need a car seat or booster."},"es":{"q":"En Virginia, ¿los niños menores de qué edad deben ir en un asiento de seguridad o un asiento elevado (booster)?","o":["Menores de 4","Menores de 8","Menores de 12","Menores de 16"],"h1":"Piense en un niño de segundo o tercer grado.","h2":"En Virginia, todos los niños menores de 8 años deben ir asegurados en un asiento de seguridad o un asiento elevado (booster).","p":"Correcto. En Virginia, los niños menores de 8 años necesitan asiento de seguridad o booster."},"zh":{"q":"在 Virginia，几岁以下的孩子必须坐儿童安全座椅或增高座椅？","o":["4 岁以下","8 岁以下","12 岁以下","16 岁以下"],"h1":"想一想读二年级或三年级的孩子。","h2":"在 Virginia，所有 8 岁以下的孩子都必须固定在儿童安全座椅或增高座椅里。","p":"对。在 Virginia，8 岁以下的孩子需要儿童座椅或增高座椅。"},"vi":{"q":"Ở Virginia, trẻ em dưới bao nhiêu tuổi phải ngồi ghế an toàn cho trẻ em hoặc ghế nâng?","o":["Dưới 4 tuổi","Dưới 8 tuổi","Dưới 12 tuổi","Dưới 16 tuổi"],"h1":"Hãy nghĩ đến một đứa trẻ học lớp hai hoặc lớp ba.","h2":"Ở Virginia, tất cả trẻ em dưới 8 tuổi phải được giữ chặt trong ghế an toàn cho trẻ em hoặc ghế nâng.","p":"Đúng. Ở Virginia, trẻ em dưới 8 tuổi cần ghế ô tô hoặc ghế nâng."},"tl":{"q":"Sa Virginia, ang mga batang wala pang anong edad ang dapat nakaupo sa child safety seat o booster seat?","o":["Wala pang 4","Wala pang 8","Wala pang 12","Wala pang 16"],"h1":"Isipin ang batang nasa ikalawa o ikatlong baitang.","h2":"Sa Virginia, lahat ng batang wala pang 8 taong gulang ay dapat nakakabit sa child safety seat o booster seat.","p":"Tama. Sa Virginia, kailangan ng car seat o booster ng mga batang wala pang 8."},"ar":{"q":"في Virginia، الأطفال الذين أعمارهم أقل من كم سنة يجب أن يجلسوا في مقعد أمان للأطفال أو مقعد رافع؟","o":["أقل من 4","أقل من 8","أقل من 12","أقل من 16"],"h1":"فكّر في طفل في الصف الثاني أو الثالث.","h2":"في Virginia، يجب أن يُثبَّت كل الأطفال الذين أعمارهم أقل من 8 سنوات في مقعد أمان للأطفال أو مقعد رافع.","p":"صحيح. الأطفال في Virginia الذين أعمارهم أقل من 8 سنوات يحتاجون إلى مقعد سيارة أو مقعد رافع."},"ref":{"doc":"VA","page":27}},{"id":"va-045","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, who may not ride in the open bed of a pickup truck?","o":["Only children under 5","No one, unless the truck is parked","Only people over 65","Children under 16, even with a camper shell"],"h1":"The rule covers most children and teens.","h2":"In Virginia, it is illegal to carry children under age 16 in the bed of a pickup truck, even if it has a camper shell.","p":"Right. In Virginia, no child under 16 may ride in a pickup truck bed."},"es":{"q":"En Virginia, ¿quién no puede ir en la caja abierta de una camioneta pickup?","o":["Solo los niños menores de 5 años","Nadie, a menos que la camioneta esté estacionada","Solo las personas mayores de 65 años","Los menores de 16 años, aunque tenga una cubierta (camper)"],"h1":"La regla cubre a la mayoría de los niños y adolescentes.","h2":"En Virginia, es ilegal llevar a menores de 16 años en la caja de una camioneta pickup, aunque tenga una cubierta (camper).","p":"Correcto. En Virginia, ningún menor de 16 años puede ir en la caja de una pickup."},"zh":{"q":"在 Virginia，谁不可以坐在皮卡车开放的后车厢里？","o":["只有 5 岁以下的孩子","没有人可以，除非车停着","只有 65 岁以上的人","16 岁以下的孩子，即使有车厢顶盖也不可以"],"h1":"这条规定包括大多数儿童和青少年。","h2":"在 Virginia，让 16 岁以下的孩子坐在皮卡车的后车厢里是违法的，即使后车厢有顶盖也一样。","p":"对。在 Virginia，16 岁以下的孩子都不可以坐在皮卡车后车厢里。"},"vi":{"q":"Ở Virginia, ai không được ngồi trên thùng hở phía sau của xe bán tải?","o":["Chỉ trẻ em dưới 5 tuổi","Không ai, trừ khi xe đang đỗ","Chỉ người trên 65 tuổi","Trẻ em dưới 16 tuổi, kể cả khi thùng xe có mui che"],"h1":"Quy định này áp dụng cho hầu hết trẻ em và thiếu niên.","h2":"Ở Virginia, chở trẻ em dưới 16 tuổi trên thùng xe bán tải là bất hợp pháp, kể cả khi thùng xe có mui che.","p":"Đúng. Ở Virginia, không trẻ em nào dưới 16 tuổi được ngồi trên thùng xe bán tải."},"tl":{"q":"Sa Virginia, sino ang hindi puwedeng sumakay sa bukas na likod (bed) ng pickup truck?","o":["Mga batang wala pang 5 lang","Walang sinuman, maliban kung nakaparada ang truck","Mga taong lampas 65 lang","Mga batang wala pang 16, kahit may camper shell"],"h1":"Saklaw ng patakaran ang karamihan ng mga bata at teenager.","h2":"Sa Virginia, ilegal ang pagsakay ng mga batang wala pang 16 taong gulang sa likod ng pickup truck, kahit may camper shell ito.","p":"Tama. Sa Virginia, walang batang wala pang 16 ang puwedeng sumakay sa likod ng pickup truck."},"ar":{"q":"في Virginia، من لا يجوز له الركوب في الصندوق الخلفي المكشوف لشاحنة بيك أب؟","o":["الأطفال الذين أعمارهم أقل من 5 سنوات فقط","لا أحد، إلا إذا كانت الشاحنة متوقفة","الأشخاص الذين أعمارهم أكثر من 65 سنة فقط","الأطفال الذين أعمارهم أقل من 16 سنة، حتى مع وجود غطاء للصندوق"],"h1":"القاعدة تشمل معظم الأطفال والمراهقين.","h2":"في Virginia، نقل الأطفال الذين أعمارهم أقل من 16 سنة في صندوق شاحنة البيك أب غير قانوني، حتى لو كان للصندوق غطاء.","p":"صحيح. في Virginia، يجب ألّا يركب أي طفل عمره أقل من 16 سنة في صندوق شاحنة بيك أب."},"ref":{"doc":"VA","page":27}},{"id":"va-046","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, you damage a parked car and cannot find the owner. You leave a note. What else must you do?","o":["Nothing else","Call your insurance company within a week","Report the crash to the police within 24 hours","Wait at the car until the owner comes back"],"h1":"The police must hear about it within one day.","h2":"In Virginia, if you damage an unattended car, you must leave a note with your contact details and report the crash to the police within 24 hours.","p":"Right. Leave a note and tell the police within 24 hours in Virginia."},"es":{"q":"En Virginia, usted daña un carro estacionado y no encuentra al dueño. Deja una nota. ¿Qué más debe hacer?","o":["Nada más","Llamar a su compañía de seguros dentro de una semana","Reportar el choque a la policía dentro de 24 horas","Esperar junto al carro hasta que vuelva el dueño"],"h1":"La policía debe saberlo dentro de un día.","h2":"En Virginia, si daña un carro sin nadie adentro, debe dejar una nota con sus datos y reportar el choque a la policía dentro de 24 horas.","p":"Correcto. En Virginia, deje una nota y avise a la policía dentro de 24 horas."},"zh":{"q":"在 Virginia，你撞坏了一辆停着的车，找不到车主。你留了一张纸条。你还必须做什么？","o":["不用做别的","在一个星期内打电话给你的保险公司","在 24 小时内向警察报告这次车祸","在车旁边等到车主回来"],"h1":"必须在一天之内让警察知道。","h2":"在 Virginia，如果你撞坏了没有人看管的车，你必须留下写有你联系方式的纸条，并在 24 小时内向警察报告这次车祸。","p":"对。在 Virginia，要留纸条，并在 24 小时内告诉警察。"},"vi":{"q":"Ở Virginia, bạn làm hư một xe đang đỗ và không tìm được chủ xe. Bạn để lại một mẩu giấy. Bạn còn phải làm gì nữa?","o":["Không cần làm gì nữa","Gọi công ty bảo hiểm của bạn trong vòng một tuần","Báo tai nạn cho cảnh sát trong vòng 24 giờ","Chờ ở xe cho đến khi chủ xe quay lại"],"h1":"Cảnh sát phải được biết trong vòng một ngày.","h2":"Ở Virginia, nếu bạn làm hư một xe không có người trông, bạn phải để lại giấy ghi thông tin liên lạc của bạn và báo tai nạn cho cảnh sát trong vòng 24 giờ.","p":"Đúng. Ở Virginia, để lại giấy và báo cảnh sát trong vòng 24 giờ."},"tl":{"q":"Sa Virginia, nasira mo ang isang nakaparadang kotse at hindi mo makita ang may-ari. Nag-iwan ka ng sulat. Ano pa ang dapat mong gawin?","o":["Wala na","Tawagan ang insurance company mo sa loob ng isang linggo","I-report ang aksidente sa pulis sa loob ng 24 oras","Maghintay sa kotse hanggang bumalik ang may-ari"],"h1":"Dapat malaman ito ng pulis sa loob ng isang araw.","h2":"Sa Virginia, kung nasira mo ang kotseng walang nagbabantay, dapat kang mag-iwan ng sulat na may contact details mo at i-report ang aksidente sa pulis sa loob ng 24 oras.","p":"Tama. Sa Virginia, mag-iwan ng sulat at sabihan ang pulis sa loob ng 24 oras."},"ar":{"q":"في Virginia، ألحقتَ ضررًا بسيارة متوقفة ولم تجد صاحبها. تركتَ ورقة. ماذا يجب أن تفعل أيضًا؟","o":["لا شيء آخر","أن تتصل بشركة التأمين خلال أسبوع","أن تبلّغ الشرطة عن الحادث خلال 24 ساعة","أن تنتظر عند السيارة حتى يعود صاحبها"],"h1":"يجب أن تعرف الشرطة بالأمر خلال يوم واحد.","h2":"في Virginia، إذا ألحقت ضررًا بسيارة ليس معها أحد، يجب أن تترك ورقة فيها بيانات الاتصال بك وأن تبلّغ الشرطة عن الحادث خلال 24 ساعة.","p":"صحيح. في Virginia، اترك ورقة وأخبر الشرطة خلال 24 ساعة."},"ref":{"doc":"VA","page":25}},{"id":"va-047","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, a driver age 18 or older gets 12 demerit points in 12 months. What does DMV require?","o":["A driver improvement clinic","Nothing until 24 points","A new road skills test","A one-year revocation"],"h1":"It is a class to help the driver improve.","h2":"In Virginia, a driver age 18 or older with 12 demerit points in 12 months, or 18 points in 24 months, must complete a driver improvement clinic.","p":"Right. Twelve points in a year sends a Virginia adult driver to a driver improvement clinic."},"es":{"q":"En Virginia, un conductor de 18 años o más acumula 12 puntos de demérito en 12 meses. ¿Qué exige el DMV?","o":["Una clínica de mejoramiento para conductores","Nada hasta llegar a 24 puntos","Un nuevo examen de manejo en la calle","Una revocación de un año"],"h1":"Es una clase para ayudar al conductor a mejorar.","h2":"En Virginia, un conductor de 18 años o más con 12 puntos de demérito en 12 meses, o 18 puntos en 24 meses, debe completar una clínica de mejoramiento para conductores.","p":"Correcto. Doce puntos en un año llevan a un conductor adulto de Virginia a una clínica de mejoramiento."},"zh":{"q":"在 Virginia，一名 18 岁或以上的司机在 12 个月内被记了 12 个违规点数。DMV 要求什么？","o":["参加驾驶改进课程","到 24 点之前什么都不用做","重新考路考","吊销驾照一年"],"h1":"这是一门帮助司机改进的课。","h2":"在 Virginia，18 岁或以上的司机在 12 个月内有 12 个违规点数，或在 24 个月内有 18 个点数，必须完成驾驶改进课程。","p":"对。在 Virginia，成年司机一年内有 12 个点数，就要去上驾驶改进课程。"},"vi":{"q":"Ở Virginia, một tài xế từ 18 tuổi trở lên bị 12 điểm phạt trong 12 tháng. DMV yêu cầu gì?","o":["Một lớp cải thiện kỹ năng lái xe","Không gì cả cho đến khi bị 24 điểm","Một bài thi kỹ năng lái xe trên đường mới","Bị thu hồi bằng một năm"],"h1":"Đó là một lớp học giúp tài xế lái tốt hơn.","h2":"Ở Virginia, tài xế từ 18 tuổi trở lên bị 12 điểm phạt trong 12 tháng, hoặc 18 điểm trong 24 tháng, phải hoàn thành một lớp cải thiện kỹ năng lái xe.","p":"Đúng. Ở Virginia, tài xế người lớn bị 12 điểm trong một năm phải đi học lớp cải thiện kỹ năng lái xe."},"tl":{"q":"Sa Virginia, ang driver na edad 18 pataas ay nagkaroon ng 12 demerit points sa loob ng 12 buwan. Ano ang hinihingi ng DMV?","o":["Isang driver improvement clinic","Wala hanggang 24 points","Isang bagong road skills test","Isang taong revocation"],"h1":"Ito ay klase para tulungang humusay ang driver.","h2":"Sa Virginia, ang driver na edad 18 pataas na may 12 demerit points sa loob ng 12 buwan, o 18 points sa loob ng 24 buwan, ay dapat tapusin ang isang driver improvement clinic.","p":"Tama. Kapag may 12 points sa isang taon ang adult driver sa Virginia, kailangan niyang pumasok sa driver improvement clinic."},"ar":{"q":"في Virginia، سائق عمره 18 سنة أو أكثر حصل على 12 نقطة مخالفة خلال 12 شهرًا. ماذا تطلب إدارة المركبات (DMV)؟","o":["دورة لتحسين القيادة","لا شيء حتى 24 نقطة","اختبار قيادة جديد على الطريق","سحب الرخصة لمدة سنة"],"h1":"إنها دروس تساعد السائق على أن يتحسّن.","h2":"في Virginia، السائق الذي عمره 18 سنة أو أكثر ولديه 12 نقطة مخالفة خلال 12 شهرًا، أو 18 نقطة خلال 24 شهرًا، يجب أن يُكمل دورة لتحسين القيادة.","p":"صحيح. 12 نقطة في سنة ترسل السائق البالغ في Virginia إلى دورة لتحسين القيادة."},"ref":{"doc":"VA","page":29}},{"id":"va-048","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, you move to a new address. How soon must you tell DMV?","o":["Within 10 days","Within 30 days","Within 6 months","Only when you renew your license"],"h1":"It is about one month.","h2":"In Virginia, you must tell DMV about your new address within 30 days of moving.","p":"Right. Tell Virginia DMV about a move within 30 days."},"es":{"q":"En Virginia, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar al DMV?","o":["Dentro de 10 días","Dentro de 30 días","Dentro de 6 meses","Solo cuando renueve su licencia"],"h1":"Es más o menos un mes.","h2":"En Virginia, debe avisar al DMV de su nueva dirección dentro de 30 días después de mudarse.","p":"Correcto. Avise al DMV de Virginia de una mudanza dentro de 30 días."},"zh":{"q":"在 Virginia，你搬到新地址。你必须多快告诉 DMV？","o":["10 天内","30 天内","6 个月内","只在你更新驾照时"],"h1":"大约一个月。","h2":"在 Virginia，你必须在搬家后 30 天内把新地址告诉 DMV。","p":"对。在 Virginia，搬家后 30 天内要告诉 DMV。"},"vi":{"q":"Ở Virginia, bạn chuyển đến địa chỉ mới. Bạn phải báo cho DMV trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 6 tháng","Chỉ khi bạn gia hạn bằng lái"],"h1":"Khoảng một tháng.","h2":"Ở Virginia, bạn phải báo địa chỉ mới cho DMV trong vòng 30 ngày sau khi chuyển nhà.","p":"Đúng. Báo cho DMV Virginia về việc chuyển nhà trong vòng 30 ngày."},"tl":{"q":"Sa Virginia, lumipat ka sa bagong address. Gaano kabilis mo dapat sabihan ang DMV?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 6 na buwan","Kapag ire-renew mo lang ang lisensya mo"],"h1":"Mga isang buwan ito.","h2":"Sa Virginia, dapat mong sabihan ang DMV tungkol sa bago mong address sa loob ng 30 araw pagkalipat mo.","p":"Tama. Sabihan ang Virginia DMV tungkol sa paglipat sa loob ng 30 araw."},"ar":{"q":"في Virginia، انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تُخبر إدارة المركبات (DMV)؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 6 أشهر","فقط عندما تجدّد رخصتك"],"h1":"إنها نحو شهر واحد.","h2":"في Virginia، يجب أن تُخبر إدارة المركبات (DMV) بعنوانك الجديد خلال 30 يومًا من انتقالك.","p":"صحيح. أخبر إدارة المركبات في Virginia بانتقالك خلال 30 يومًا."},"ref":{"doc":"VA","page":33}},{"id":"va-049","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a new resident who drives must get a Virginia driver's license within how many days of moving there?","o":["10 days","30 days","1 year","60 days"],"h1":"It is about two months.","h2":"In Virginia, a new resident who drives must get a Virginia driver's license within 60 days of moving to the state.","p":"Right. New Virginia residents have 60 days to get a Virginia license."},"es":{"q":"En Virginia, ¿dentro de cuántos días después de mudarse debe un nuevo residente que maneja obtener una licencia de Virginia?","o":["10 días","30 días","1 año","60 días"],"h1":"Son más o menos dos meses.","h2":"En Virginia, un nuevo residente que maneja debe obtener una licencia de conducir de Virginia dentro de 60 días después de mudarse al estado.","p":"Correcto. Los nuevos residentes de Virginia tienen 60 días para obtener la licencia de Virginia."},"zh":{"q":"在 Virginia，一位开车的新居民必须在搬来后多少天内办 Virginia 驾照？","o":["10 天","30 天","1 年","60 天"],"h1":"大约两个月。","h2":"在 Virginia，开车的新居民必须在搬到这个州后 60 天内办 Virginia 驾照。","p":"对。Virginia 的新居民有 60 天时间办 Virginia 驾照。"},"vi":{"q":"Ở Virginia, một cư dân mới có lái xe phải lấy bằng lái Virginia trong vòng bao nhiêu ngày sau khi chuyển đến?","o":["10 ngày","30 ngày","1 năm","60 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở Virginia, cư dân mới có lái xe phải lấy bằng lái Virginia trong vòng 60 ngày sau khi chuyển đến tiểu bang.","p":"Đúng. Cư dân mới ở Virginia có 60 ngày để lấy bằng lái Virginia."},"tl":{"q":"Sa Virginia, ang bagong residenteng nagmamaneho ay dapat kumuha ng Virginia driver's license sa loob ng ilang araw mula nang lumipat doon?","o":["10 araw","30 araw","1 taon","60 araw"],"h1":"Mga dalawang buwan ito.","h2":"Sa Virginia, ang bagong residenteng nagmamaneho ay dapat kumuha ng Virginia driver's license sa loob ng 60 araw mula nang lumipat sa estado.","p":"Tama. May 60 araw ang mga bagong residente ng Virginia para kumuha ng Virginia license."},"ar":{"q":"في Virginia، المقيم الجديد الذي يقود يجب أن يحصل على رخصة قيادة من Virginia خلال كم يومًا من انتقاله إليها؟","o":["10 أيام","30 يومًا","1 سنة","60 يومًا"],"h1":"إنها نحو شهرين.","h2":"في Virginia، المقيم الجديد الذي يقود يجب أن يحصل على رخصة قيادة من Virginia خلال 60 يومًا من انتقاله إلى الولاية.","p":"صحيح. المقيمون الجدد في Virginia لديهم 60 يومًا للحصول على رخصة من Virginia."},"ref":{"doc":"VA","page":33}},{"id":"va-050","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a learner under 18 fails the knowledge exam. How long must they wait to take it again?","o":["They can retake it the same day","One full week","A full 15 days","Six months"],"h1":"It is about half a month.","h2":"In Virginia, an applicant under 18 who fails the knowledge exam must wait a full 15 days before taking it again.","p":"Right. Under 18 in Virginia, you wait a full 15 days to retake the exam."},"es":{"q":"En Virginia, un aprendiz menor de 18 años no aprueba el examen de conocimientos. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Puede repetirlo el mismo día","Una semana completa","15 días completos","Seis meses"],"h1":"Es más o menos medio mes.","h2":"En Virginia, un solicitante menor de 18 años que no aprueba el examen de conocimientos debe esperar 15 días completos antes de tomarlo otra vez.","p":"Correcto. Si es menor de 18 años en Virginia, espera 15 días completos para repetir el examen."},"zh":{"q":"在 Virginia，一名未满 18 岁的学员笔试没有通过。他们必须等多久才能再考？","o":["当天就可以再考","整整一个星期","整整 15 天","六个月"],"h1":"大约半个月。","h2":"在 Virginia，未满 18 岁的申请人笔试没有通过，必须等整整 15 天才能再考。","p":"对。在 Virginia，未满 18 岁要等整整 15 天才能重考。"},"vi":{"q":"Ở Virginia, một người học lái dưới 18 tuổi thi trượt bài thi kiến thức. Họ phải chờ bao lâu để thi lại?","o":["Họ có thể thi lại ngay trong ngày","Trọn một tuần","Trọn 15 ngày","Sáu tháng"],"h1":"Khoảng nửa tháng.","h2":"Ở Virginia, người nộp đơn dưới 18 tuổi thi trượt bài thi kiến thức phải chờ trọn 15 ngày rồi mới được thi lại.","p":"Đúng. Dưới 18 tuổi ở Virginia, bạn phải chờ trọn 15 ngày để thi lại."},"tl":{"q":"Sa Virginia, bumagsak sa knowledge exam ang isang learner na wala pang 18. Gaano katagal sila dapat maghintay bago kumuha ulit?","o":["Puwede silang kumuha ulit sa parehong araw","Isang buong linggo","Buong 15 araw","Anim na buwan"],"h1":"Mga kalahating buwan ito.","h2":"Sa Virginia, ang aplikanteng wala pang 18 na bumagsak sa knowledge exam ay dapat maghintay ng buong 15 araw bago kumuha ulit.","p":"Tama. Kung wala ka pang 18 sa Virginia, maghihintay ka ng buong 15 araw bago kumuha ulit ng exam."},"ar":{"q":"في Virginia، متعلّم عمره أقل من 18 سنة رسب في الامتحان النظري. كم يجب أن ينتظر قبل أن يتقدّم له مرة أخرى؟","o":["يمكنه أن يعيده في اليوم نفسه","أسبوع كامل","15 يومًا كاملة","ستة أشهر"],"h1":"إنها نحو نصف شهر.","h2":"في Virginia، المتقدّم الذي عمره أقل من 18 سنة ويرسب في الامتحان النظري يجب أن ينتظر 15 يومًا كاملة قبل أن يتقدّم له مرة أخرى.","p":"صحيح. إذا كان عمرك أقل من 18 سنة في Virginia، تنتظر 15 يومًا كاملة لتعيد الامتحان."},"ref":{"doc":"VA","page":3}},{"id":"va-051","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, how often may you take the knowledge exam?","o":["As many times as you want in one day","Only once per business day","Once a month","Once a year"],"h1":"Think of a single working day.","h2":"In Virginia, you may take the knowledge exam only once per business day.","p":"Right. One try per business day."},"es":{"q":"En Virginia, ¿con qué frecuencia puede tomar el examen de conocimientos?","o":["Todas las veces que quiera en un día","Solo una vez por día hábil","Una vez al mes","Una vez al año"],"h1":"Piense en un solo día de trabajo.","h2":"En Virginia, usted puede tomar el examen de conocimientos solo una vez por día hábil.","p":"Correcto. Un intento por día hábil."},"ref":{"doc":"VA","page":3}},{"id":"va-052","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a valid driver's license from which of these countries lets a new resident skip the knowledge exam?","o":["Mexico","Brazil","India","Germany"],"h1":"It is a country in Europe.","h2":"In Virginia, you do not need the knowledge exam if you hold a valid license from another U.S. state, Canada, Germany, France or the Republic of Korea.","p":"Right. A valid German license lets you skip the Virginia knowledge exam."},"es":{"q":"En Virginia, ¿una licencia válida de cuál de estos países le permite a un nuevo residente no tomar el examen de conocimientos?","o":["México","Brasil","India","Alemania"],"h1":"Es un país de Europa.","h2":"En Virginia, usted no necesita el examen de conocimientos si tiene una licencia válida de otro estado de EE. UU., Canadá, Alemania, Francia o la República de Corea.","p":"Correcto. Una licencia alemana válida le evita el examen de conocimientos de Virginia."},"ref":{"doc":"VA","page":3}},{"id":"va-053","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, the knowledge exam is offered in your language. May you bring a translator?","o":["No, translators are not allowed for offered languages","Yes, any translator may help","Yes, if the translator is family","Only for the sign questions"],"h1":"The exam already comes in many languages.","h2":"In Virginia, translators may not be used when the exam is offered in your language, because it is given in many languages and in American Sign Language.","p":"Right. No translators for languages the exam already offers."},"es":{"q":"En Virginia, el examen de conocimientos se ofrece en su idioma. ¿Puede llevar un traductor?","o":["No, no se permiten traductores para los idiomas que se ofrecen","Sí, cualquier traductor puede ayudar","Sí, si el traductor es de la familia","Solo para las preguntas de señales"],"h1":"El examen ya viene en muchos idiomas.","h2":"En Virginia, no se pueden usar traductores cuando el examen se ofrece en su idioma, porque se da en muchos idiomas y en lenguaje de señas americano.","p":"Correcto. No hay traductores para los idiomas que el examen ya ofrece."},"ref":{"doc":"VA","page":3}},{"id":"va-054","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a regular driver's license lets you drive any vehicle or small truck under what weight, if no commercial license is needed?","o":["10,000 pounds","15,000 pounds","26,001 pounds","80,000 pounds"],"h1":"It is just over 26,000.","h2":"In Virginia, a regular driver's license lets you drive any vehicle or small truck under 26,001 pounds that does not need a commercial driver's license.","p":"Right. Under 26,001 pounds."},"es":{"q":"En Virginia, ¿una licencia de manejo normal le permite manejar cualquier vehículo o camión pequeño de menos de qué peso, si no se necesita licencia comercial?","o":["10,000 libras","15,000 libras","26,001 libras","80,000 libras"],"h1":"Es un poco más de 26,000.","h2":"En Virginia, una licencia de manejo normal le permite manejar cualquier vehículo o camión pequeño de menos de 26,001 libras que no necesite licencia de manejo comercial.","p":"Correcto. Menos de 26,001 libras."},"ref":{"doc":"VA","page":32}},{"id":"va-055","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, you fail the road skills test. How long must you wait to take it again?","o":["You may retest the same day","Two days","Two weeks","Six months"],"h1":"It is a very short wait.","h2":"In Virginia, if you fail the road skills test, you must wait two days before you take it again.","p":"Right. Wait two days, then try again."},"es":{"q":"En Virginia, usted reprueba el examen de manejo en la calle. ¿Cuánto debe esperar para tomarlo otra vez?","o":["Puede repetirlo el mismo día","Dos días","Dos semanas","Seis meses"],"h1":"Es una espera muy corta.","h2":"En Virginia, si reprueba el examen de manejo en la calle, debe esperar dos días antes de tomarlo otra vez.","p":"Correcto. Espere dos días y vuelva a intentarlo."},"ref":{"doc":"VA","page":4}},{"id":"va-056","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, you fail the road skills test at DMV three times. What must you do before a fourth try?","o":["Wait one full year","Pay a $500 fee","Take the knowledge exam again","Complete the in-car part of driver education"],"h1":"You need more time behind the wheel with a teacher.","h2":"In Virginia, after three failed road skills tests at DMV, you must complete and pass the in-vehicle part of driver education at an approved school before you can test again.","p":"Right. Three road test failures mean in-car driver education first."},"es":{"q":"En Virginia, usted reprueba tres veces el examen de manejo en la calle en el DMV. ¿Qué debe hacer antes de un cuarto intento?","o":["Esperar un año completo","Pagar una tarifa de $500","Tomar otra vez el examen de conocimientos","Completar la parte en el carro de la educación vial"],"h1":"Necesita más tiempo al volante con un instructor.","h2":"En Virginia, después de reprobar tres veces el examen de manejo en el DMV, debe completar y aprobar la parte en el vehículo de la educación vial en una escuela aprobada antes de volver a examinarse.","p":"Correcto. Tres fracasos en el examen de manejo exigen primero educación vial en el carro."},"ref":{"doc":"VA","page":4}},{"id":"va-057","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how does an applicant under 18 take the road skills test?","o":["As part of the driver education course","With a police officer on the highway","With a parent as the examiner","Only at the main DMV office in Richmond"],"h1":"It is part of a class teens must take.","h2":"In Virginia, for applicants under 18, the road skills test is given as part of the driver education course.","p":"Right. Teens take the road test through driver education."},"es":{"q":"En Virginia, ¿cómo toma el examen de manejo en la calle un solicitante menor de 18 años?","o":["Como parte del curso de educación vial","Con un policía en la autopista","Con uno de sus padres como examinador","Solo en la oficina principal del DMV en Richmond"],"h1":"Es parte de una clase que los adolescentes deben tomar.","h2":"En Virginia, para los solicitantes menores de 18 años, el examen de manejo en la calle se da como parte del curso de educación vial.","p":"Correcto. Los adolescentes toman el examen de manejo a través de la educación vial."},"ref":{"doc":"VA","page":4}},{"id":"va-058","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, what vision is needed in at least one eye for a license with no vision restriction?","o":["20/100","20/70","20/40 or better","Exactly 20/20"],"h1":"It is a common standard in many states.","h2":"In Virginia, a license with no vision restriction needs 20/40 or better vision in one or both eyes.","p":"Right. You need 20/40 or better."},"es":{"q":"En Virginia, ¿qué visión se necesita en por lo menos un ojo para una licencia sin restricción de la vista?","o":["20/100","20/70","20/40 o mejor","Exactamente 20/20"],"h1":"Es un estándar común en muchos estados.","h2":"En Virginia, una licencia sin restricción de la vista requiere una visión de 20/40 o mejor en uno o en ambos ojos.","p":"Correcto. Necesita 20/40 o mejor."},"ref":{"doc":"VA","page":4}},{"id":"va-059","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, a driver's vision is 20/70 in the better eye, with enough side vision. What kind of license may the driver get?","o":["No license at all","A license for daylight driving only","A license with no limits","A license for highways only"],"h1":"The limit has to do with the sun.","h2":"In Virginia, 20/70 or better vision, with enough side vision, can qualify for a license restricted to daylight hours.","p":"Right. With 20/70 vision, driving is limited to daylight."},"es":{"q":"En Virginia, la visión de un conductor es 20/70 en el mejor ojo, con suficiente visión lateral. ¿Qué tipo de licencia puede obtener?","o":["Ninguna licencia","Una licencia solo para manejar de día","Una licencia sin límites","Una licencia solo para autopistas"],"h1":"El límite tiene que ver con el sol.","h2":"En Virginia, una visión de 20/70 o mejor, con suficiente visión lateral, puede calificar para una licencia limitada a las horas de luz del día.","p":"Correcto. Con visión de 20/70, solo se puede manejar de día."},"ref":{"doc":"VA","page":4}},{"id":"va-060","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a license restricted to daylight driving allows driving during which hours?","o":["From sunrise to sunset","From 6 a.m. to 9 p.m.","Any time except midnight to 4 a.m.","From a half-hour after sunrise to a half-hour before sunset"],"h1":"It is a little shorter than the full day at both ends.","h2":"In Virginia, a daylight-only license lets you drive from a half-hour after sunrise until a half-hour before sunset.","p":"Right. Half an hour after sunrise to half an hour before sunset."},"es":{"q":"En Virginia, ¿en qué horas permite manejar una licencia limitada a manejar de día?","o":["Desde la salida hasta la puesta del sol","De 6 a.m. a 9 p.m.","A cualquier hora menos de medianoche a 4 a.m.","Desde media hora después de la salida del sol hasta media hora antes de la puesta del sol"],"h1":"Es un poco más corto que el día completo en ambos extremos.","h2":"En Virginia, una licencia solo de día le permite manejar desde media hora después de la salida del sol hasta media hora antes de la puesta del sol.","p":"Correcto. Media hora después del amanecer hasta media hora antes del atardecer."},"ref":{"doc":"VA","page":4}},{"id":"va-061","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, you need glasses to pass the vision screening. What does your license show?","o":["A C restriction, so you must wear them when driving","Nothing at all","A D restriction for daytime only","A note that you need a new test each year"],"h1":"It is a single letter on the license.","h2":"In Virginia, if you need glasses or contact lenses to pass the vision screening, your license shows a C restriction and you must wear them when you drive.","p":"Right. A C on the license means wear your glasses or contacts."},"es":{"q":"En Virginia, usted necesita lentes para pasar la prueba de la vista. ¿Qué muestra su licencia?","o":["Una restricción C, así que debe usarlos al manejar","Nada","Una restricción D solo para el día","Una nota de que necesita una nueva prueba cada año"],"h1":"Es una sola letra en la licencia.","h2":"En Virginia, si necesita lentes o lentes de contacto para pasar la prueba de la vista, su licencia muestra una restricción C y debe usarlos cuando maneja.","p":"Correcto. Una C en la licencia significa que debe usar sus lentes o lentes de contacto."},"ref":{"doc":"VA","page":4}},{"id":"va-062","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, you are caught driving a car with no insurance. What fee must you pay to get your driving privilege back?","o":["$50","A $600 noncompliance fee","$5,000","No fee"],"h1":"It is several hundred dollars.","h2":"In Virginia, a driver caught without insurance must pay a $600 noncompliance fee (or get a payment plan) and have proof of insurance filed for three years.","p":"Right. $600, plus three years of proof of insurance."},"es":{"q":"En Virginia, lo detienen manejando un carro sin seguro. ¿Qué tarifa debe pagar para recuperar su privilegio de manejar?","o":["$50","Una tarifa de incumplimiento de $600","$5,000","Ninguna tarifa"],"h1":"Son varios cientos de dólares.","h2":"En Virginia, un conductor detenido sin seguro debe pagar una tarifa de incumplimiento de $600 (o conseguir un plan de pagos) y presentar prueba de seguro durante tres años.","p":"Correcto. $600, más tres años de prueba de seguro."},"ref":{"doc":"VA","page":34}},{"id":"va-063","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, what is the youngest age to get a driver's license?","o":["16 years old","16 years and 3 months","16 years and 6 months","17 years old"],"h1":"It is a few months after a birthday.","h2":"In Virginia, a teen must be at least 16 years and 3 months old to get a driver's license.","p":"Right. Sixteen and three months."},"es":{"q":"En Virginia, ¿cuál es la edad mínima para obtener una licencia de manejo?","o":["16 años","16 años y 3 meses","16 años y 6 meses","17 años"],"h1":"Es unos meses después de un cumpleaños.","h2":"En Virginia, un adolescente debe tener por lo menos 16 años y 3 meses para obtener una licencia de manejo.","p":"Correcto. Dieciséis años y tres meses."},"ref":{"doc":"VA","page":null}},{"id":"va-064","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, what is the fee for the learner's permit itself, not counting the license fee?","o":["$50","$25","$10","$3"],"h1":"It is a very small amount.","h2":"In Virginia, the learner's permit fee is $3, plus the yearly cost of the driver's license.","p":"Right. The permit itself costs $3."},"es":{"q":"En Virginia, ¿cuánto cuesta el permiso de aprendiz en sí, sin contar la tarifa de la licencia?","o":["$50","$25","$10","$3"],"h1":"Es una cantidad muy pequeña.","h2":"En Virginia, la tarifa del permiso de aprendiz es de $3, más el costo anual de la licencia de manejo.","p":"Correcto. El permiso en sí cuesta $3."},"ref":{"doc":"VA","page":null}},{"id":"va-065","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, you have a learner's permit and a licensed adult is with you. May you drive at 1 a.m.?","o":["No, permit holders may not drive from midnight to 4 a.m.","Yes, if the adult is 21 or older","Yes, if you are going to work","Yes, on weekends only"],"h1":"The permit has a stricter night rule than the license.","h2":"In Virginia, a learner's permit never allows driving between midnight and 4 a.m., even with a licensed adult beside you.","p":"Right. No permit driving from midnight to 4 a.m."},"es":{"q":"En Virginia, usted tiene permiso de aprendiz y lo acompaña un adulto con licencia. ¿Puede manejar a la 1 a.m.?","o":["No, con permiso no se puede manejar de medianoche a 4 a.m.","Sí, si el adulto tiene 21 años o más","Sí, si va al trabajo","Sí, solo los fines de semana"],"h1":"El permiso tiene una regla de noche más estricta que la licencia.","h2":"En Virginia, el permiso de aprendiz nunca permite manejar entre medianoche y las 4 a.m., aunque lo acompañe un adulto con licencia.","p":"Correcto. Con permiso no se maneja de medianoche a 4 a.m."},"ref":{"doc":"VA","page":null}},{"id":"va-066","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a teen finishes driver education. For how long does the training certificate, carried with the learner's permit, work as a license?","o":["30 days","90 days","180 days","Two years"],"h1":"It is about six months.","h2":"In Virginia, the driver training certificate (DTS B) together with a valid learner's permit works as a license for 180 days from the eligibility date, or until age 18.","p":"Right. It works as a temporary license for 180 days."},"es":{"q":"En Virginia, un adolescente termina la educación vial. ¿Por cuánto tiempo el certificado de entrenamiento, junto con el permiso de aprendiz, sirve como licencia?","o":["30 días","90 días","180 días","Dos años"],"h1":"Son unos seis meses.","h2":"En Virginia, el certificado de entrenamiento (DTS B) junto con un permiso de aprendiz válido sirve como licencia por 180 días desde la fecha de elegibilidad, o hasta los 18 años.","p":"Correcto. Sirve como licencia temporal por 180 días."},"ref":{"doc":"VA","page":null}},{"id":"va-067","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a driver age 76 renews a license. For how long can it be valid?","o":["Two years","Eight years","Ten years","Up to five years"],"h1":"It is shorter than for younger drivers.","h2":"In Virginia, a license issued to a person age 75 or older is valid for no more than five years.","p":"Right. Up to five years."},"es":{"q":"En Virginia, un conductor de 76 años renueva su licencia. ¿Por cuánto tiempo puede ser válida?","o":["Dos años","Ocho años","Diez años","Hasta cinco años"],"h1":"Es menos tiempo que para los conductores más jóvenes.","h2":"En Virginia, una licencia emitida a una persona de 75 años o más es válida por no más de cinco años.","p":"Correcto. Hasta cinco años."},"ref":{"doc":"VA","page":null}},{"id":"va-068","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, driver education for students under 18 includes an extra part for parents and teens together. How long is it?","o":["15 minutes","One full day","Eight hours","At least 90 minutes"],"h1":"It is about the length of a movie.","h2":"In Virginia, driver education for students under 18 includes a parent/teen part of at least 90 minutes.","p":"Right. The parent/teen part is at least 90 minutes."},"es":{"q":"En Virginia, la educación vial para estudiantes menores de 18 años incluye una parte extra para padres y adolescentes juntos. ¿Cuánto dura?","o":["15 minutos","Un día completo","Ocho horas","Por lo menos 90 minutos"],"h1":"Dura más o menos lo que una película.","h2":"En Virginia, la educación vial para estudiantes menores de 18 años incluye una parte para padres y adolescentes de por lo menos 90 minutos.","p":"Correcto. La parte para padres y adolescentes dura por lo menos 90 minutos."},"ref":{"doc":"VA","page":null}},{"id":"va-069","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how long does a renewed driver's license usually last?","o":["Eight years","Two years","Four years","For life"],"h1":"It is the longest time the law allows.","h2":"In Virginia, a renewed driver's license is usually valid for eight years and expires on your birthday.","p":"Right. Eight years."},"es":{"q":"En Virginia, ¿cuánto dura normalmente una licencia de manejo renovada?","o":["Ocho años","Dos años","Cuatro años","Toda la vida"],"h1":"Es el tiempo más largo que permite la ley.","h2":"En Virginia, una licencia de manejo renovada normalmente es válida por ocho años y vence en su cumpleaños.","p":"Correcto. Ocho años."},"ref":{"doc":"VA","page":null}},{"id":"va-070","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, starting January 1, 2027, what must a first-time applicant age 19 do before getting a license?","o":["Only pass the road test","Hold a permit for 60 days or take driver education","Hold a permit for 90 days and complete driver education","Nothing, adults have no rules"],"h1":"Both a waiting time and a course are needed.","h2":"In Virginia, from January 1, 2027, first-time applicants age 18 through 20 must hold a learner's permit for at least 90 days and complete driver education.","p":"Right. Ages 18 to 20 will need 90 days and driver education."},"es":{"q":"En Virginia, a partir del 1 de enero de 2027, ¿qué debe hacer un solicitante de 19 años que pide su primera licencia?","o":["Solo aprobar el examen de manejo","Tener el permiso 60 días o tomar educación vial","Tener el permiso 90 días y completar la educación vial","Nada, los adultos no tienen reglas"],"h1":"Se necesitan un tiempo de espera y un curso.","h2":"En Virginia, desde el 1 de enero de 2027, quienes piden su primera licencia entre los 18 y los 20 años deben tener el permiso de aprendiz por lo menos 90 días y completar la educación vial.","p":"Correcto. De 18 a 20 años se necesitarán 90 días y educación vial."},"ref":{"doc":"VA","page":null}},{"id":"va-071","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, a first-time applicant age 25 does not take driver education. How long must they hold a learner's permit before the road test?","o":["30 days","60 days","9 months","One year"],"h1":"It is about two months.","h2":"In Virginia, an adult first-time applicant who skips driver education must hold the learner's permit for at least 60 days before the road skills test.","p":"Right. At least 60 days."},"es":{"q":"En Virginia, un solicitante de 25 años que pide su primera licencia no toma educación vial. ¿Cuánto tiempo debe tener el permiso de aprendiz antes del examen de manejo?","o":["30 días","60 días","9 meses","Un año"],"h1":"Son unos dos meses.","h2":"En Virginia, un adulto que pide su primera licencia sin tomar educación vial debe tener el permiso de aprendiz por lo menos 60 días antes del examen de manejo en la calle.","p":"Correcto. Por lo menos 60 días."},"ref":{"doc":"VA","page":4}},{"id":"va-072","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a parent asks DMV to cancel a 16-year-old's license. When can it be issued again?","o":["The next day","After 30 days","Never","After six months or at age 18, whichever comes first"],"h1":"It is half a year, unless a birthday comes sooner.","h2":"In Virginia, if a parent has a minor's license canceled, DMV will not reissue it until six months pass or the teen turns 18, whichever comes first.","p":"Right. Six months, or age 18 if that comes first."},"es":{"q":"En Virginia, uno de los padres le pide al DMV que cancele la licencia de un joven de 16 años. ¿Cuándo se puede emitir de nuevo?","o":["Al día siguiente","Después de 30 días","Nunca","Después de seis meses o a los 18 años, lo que ocurra primero"],"h1":"Es medio año, a menos que llegue antes un cumpleaños.","h2":"En Virginia, si uno de los padres hace cancelar la licencia de un menor, el DMV no la vuelve a emitir hasta que pasen seis meses o el joven cumpla 18 años, lo que ocurra primero.","p":"Correcto. Seis meses, o a los 18 si eso llega antes."},"ref":{"doc":"VA","page":null}},{"id":"va-073","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, may a police officer stop a teen driver only because of a curfew or passenger limit violation?","o":["No, it cannot be the only reason for a stop","Yes, at any time","Only after midnight","Only on weekends"],"h1":"This rule is enforced only along with another reason.","h2":"In Virginia, a law-enforcement officer may not stop a vehicle only for a violation of the teen curfew or passenger limits.","p":"Right. It is not by itself a reason to pull a teen over."},"es":{"q":"En Virginia, ¿puede un policía detener a un conductor adolescente solo por violar el horario nocturno o el límite de pasajeros?","o":["No, no puede ser la única razón para detenerlo","Sí, en cualquier momento","Solo después de medianoche","Solo los fines de semana"],"h1":"Esta regla solo se aplica junto con otra razón.","h2":"En Virginia, un policía no puede detener un vehículo solo por una violación del horario nocturno o del límite de pasajeros para adolescentes.","p":"Correcto. Eso por sí solo no es razón para detener a un adolescente."},"ref":{"doc":"VA","page":null}},{"id":"va-074","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a 17-year-old breaks the teen passenger limit for the second time. What may the court do?","o":["Nothing, it is only a warning","Take the license until age 25","Suspend driving for up to six months","Require a new permit test only"],"h1":"It is up to half a year.","h2":"In Virginia, for a second or later violation of the teen curfew or passenger limits, the court may suspend the driving privilege for up to six months.","p":"Right. Up to six months off the road."},"es":{"q":"En Virginia, un joven de 17 años viola por segunda vez el límite de pasajeros para adolescentes. ¿Qué puede hacer el tribunal?","o":["Nada, es solo una advertencia","Quitarle la licencia hasta los 25 años","Suspenderle el manejo hasta por seis meses","Solo exigir un nuevo examen del permiso"],"h1":"Es hasta medio año.","h2":"En Virginia, por una segunda violación o más del horario nocturno o del límite de pasajeros para adolescentes, el tribunal puede suspender el privilegio de manejar hasta por seis meses.","p":"Correcto. Hasta seis meses sin manejar."},"ref":{"doc":"VA","page":null}},{"id":"va-075","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, is an international driver's license a valid license to drive?","o":["Yes, it replaces your license","No, it is only a translation of your valid license","Yes, if you bought it online","Yes, for one year"],"h1":"It must go together with another document.","h2":"In Virginia, an international driver's license is not a valid license by itself; it is only a translation of your valid license for use when traveling.","p":"Right. It is only a translation."},"es":{"q":"En Virginia, ¿es válida para manejar una licencia internacional de manejo?","o":["Sí, reemplaza su licencia","No, es solo una traducción de su licencia válida","Sí, si la compró por internet","Sí, por un año"],"h1":"Debe ir junto con otro documento.","h2":"En Virginia, una licencia internacional de manejo no es una licencia válida por sí sola; es solo una traducción de su licencia válida para usarla cuando viaja.","p":"Correcto. Es solo una traducción."},"ref":{"doc":"VA","page":32}},{"id":"va-076","scope":"VA","cat":"signals","sign":null,"c":2,"en":{"q":"In Virginia, a steady red arrow points right, and no sign about turning is posted. May you turn right after stopping?","o":["Yes, just as at a red light","Yes, if no pedestrians are near","No, wait until the red arrow changes","Only if the car behind you honks"],"h1":"A red arrow is stricter than a round red light here.","h2":"In Virginia, you may not turn on a steady red arrow unless a sign says Right (or Left) on Red Arrow After Stop.","p":"Right. In Virginia, no turn on a red arrow unless a sign allows it."},"es":{"q":"En Virginia, una flecha roja fija apunta a la derecha y no hay ningún letrero sobre vueltas. ¿Puede doblar a la derecha después de detenerse?","o":["Sí, igual que con una luz roja","Sí, si no hay peatones cerca","No, espere a que cambie la flecha roja","Solo si el carro de atrás toca la bocina"],"h1":"Aquí la flecha roja es más estricta que la luz roja redonda.","h2":"En Virginia, no se puede doblar con una flecha roja fija a menos que un letrero diga Right (o Left) on Red Arrow After Stop.","p":"Correcto. En Virginia no se dobla con flecha roja a menos que un letrero lo permita."},"ref":{"doc":"VA","page":5}},{"id":"va-077","scope":"VA","cat":"signals","sign":null,"c":0,"en":{"q":"In Virginia, is it legal to drive through a parking lot to get around a red light?","o":["No, cutting through to avoid a traffic control is illegal","Yes, if you drive slowly","Yes, if the lot is empty","Only at night"],"h1":"Think about why signals exist.","h2":"In Virginia, it is illegal to avoid traffic signals, signs or markings by cutting through a parking lot or field.","p":"Right. Cutting through to skip a light is against the law."},"es":{"q":"En Virginia, ¿es legal pasar por un estacionamiento para evitar un semáforo en rojo?","o":["No, es ilegal cortar camino para evitar un control de tránsito","Sí, si maneja despacio","Sí, si el estacionamiento está vacío","Solo de noche"],"h1":"Piense en para qué existen los semáforos.","h2":"En Virginia, es ilegal evitar semáforos, señales o marcas cortando camino por un estacionamiento o un campo.","p":"Correcto. Cortar camino para evitar un semáforo va contra la ley."},"ref":{"doc":"VA","page":5}},{"id":"va-078","scope":"VA","cat":"signs","sign":null,"c":3,"en":{"q":"In Virginia, a NO LEFT TURN sign is posted. May you make a U-turn there?","o":["Yes, U-turns are different","Yes, if no cars are coming","Only at night","No, a U-turn counts as two left turns"],"h1":"Think about which way your car turns during a U-turn.","h2":"In Virginia, a U-turn is treated as two left turns, so it is illegal where a No Left Turn sign is posted.","p":"Right. A U-turn is two left turns, so no U-turn there."},"es":{"q":"En Virginia, hay un letrero de NO DOBLAR A LA IZQUIERDA. ¿Puede dar una vuelta en U allí?","o":["Sí, la vuelta en U es diferente","Sí, si no vienen carros","Solo de noche","No, una vuelta en U cuenta como dos vueltas a la izquierda"],"h1":"Piense hacia qué lado gira su carro en una vuelta en U.","h2":"En Virginia, una vuelta en U se considera como dos vueltas a la izquierda, así que es ilegal donde hay un letrero de No Doblar a la Izquierda.","p":"Correcto. La vuelta en U son dos vueltas a la izquierda, así que no se permite allí."},"ref":{"doc":"VA","page":7}},{"id":"va-079","scope":"VA","cat":"signs","sign":null,"c":1,"en":{"q":"In Virginia, a MERGE sign shows two lanes becoming one. Who is responsible for merging safely?","o":["Only the driver in the ending lane","Drivers in both lanes","Only the driver in front","Only trucks"],"h1":"The job is shared.","h2":"In Virginia, when two lanes merge into one, drivers in both lanes are responsible for merging safely.","p":"Right. Both lanes share the job."},"es":{"q":"En Virginia, un letrero de MERGE muestra dos carriles que se unen en uno. ¿Quién es responsable de incorporarse con seguridad?","o":["Solo el conductor del carril que termina","Los conductores de ambos carriles","Solo el conductor de adelante","Solo los camiones"],"h1":"La tarea es compartida.","h2":"En Virginia, cuando dos carriles se unen en uno, los conductores de ambos carriles son responsables de incorporarse con seguridad.","p":"Correcto. Los dos carriles comparten la tarea."},"ref":{"doc":"VA","page":8}},{"id":"va-080","scope":"VA","cat":"signs","sign":null,"c":2,"en":{"q":"In Virginia, what does an OPEN JOINTS warning sign mean?","o":["A rest area is open","More lanes will open ahead","Gaps on a bridge or ramp could make a motorcycle rider lose control","Road work has ended"],"h1":"Think about two wheels crossing a gap.","h2":"In Virginia, an Open Joints sign warns that gaps on a bridge or ramp could cause a motorcyclist to lose control, so slow down.","p":"Right. Open joints can be dangerous for motorcycles."},"es":{"q":"En Virginia, ¿qué significa un letrero de advertencia OPEN JOINTS?","o":["Hay un área de descanso abierta","Se abrirán más carriles adelante","Las juntas abiertas en un puente o rampa podrían hacer que un motociclista pierda el control","Terminó la obra en la vía"],"h1":"Piense en dos ruedas que cruzan una abertura.","h2":"En Virginia, un letrero de Open Joints advierte que las aberturas en un puente o rampa podrían hacer que un motociclista pierda el control, así que baje la velocidad.","p":"Correcto. Las juntas abiertas pueden ser peligrosas para las motos."},"ref":{"doc":"VA","page":9}},{"id":"va-081","scope":"VA","cat":"signs","sign":null,"c":0,"en":{"q":"In Virginia, a yellow sign shows the road splitting into a Y shape. What must you do ahead?","o":["Bear to the right or to the left","Stop and yield to trains","Merge with traffic from the side","Expect a roundabout"],"h1":"The road goes two ways and does not continue straight.","h2":"In Virginia, a Y Intersection sign means you must bear either right or left ahead.","p":"Right. At a Y intersection you go right or left."},"es":{"q":"En Virginia, un letrero amarillo muestra la vía dividiéndose en forma de Y. ¿Qué debe hacer más adelante?","o":["Seguir hacia la derecha o hacia la izquierda","Detenerse y ceder el paso a los trenes","Incorporarse al tránsito que viene del lado","Esperar una glorieta"],"h1":"La vía se abre en dos y no sigue recta.","h2":"En Virginia, un letrero de intersección en Y significa que más adelante debe seguir a la derecha o a la izquierda.","p":"Correcto. En una intersección en Y se va a la derecha o a la izquierda."},"ref":{"doc":"VA","page":9}},{"id":"va-082","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, which vehicles must always stop at railroad crossings, even when the lights are not flashing?","o":["Motorcycles","Pickup trucks","Cars pulling trailers","School buses"],"h1":"They carry children.","h2":"In Virginia, school buses must always stop at railroad crossings, even when the lights are not flashing.","p":"Right. School buses always stop at the tracks."},"es":{"q":"En Virginia, ¿qué vehículos deben detenerse siempre en los cruces de tren, aunque las luces no estén parpadeando?","o":["Las motocicletas","Las camionetas pickup","Los carros que jalan remolques","Los autobuses escolares"],"h1":"Llevan niños.","h2":"En Virginia, los autobuses escolares deben detenerse siempre en los cruces de tren, aunque las luces no estén parpadeando.","p":"Correcto. Los autobuses escolares siempre se detienen en las vías."},"ref":{"doc":"VA","page":10}},{"id":"va-083","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, you call the number on the emergency sign at a railroad crossing to report a stuck car. What should you tell them?","o":["Your license number","The posted crossing number","The color of the train","Your insurance company"],"h1":"It helps them know exactly where the problem is.","h2":"In Virginia, when you call the number on a crossing's emergency sign, give the posted crossing number so the rail company can find the exact spot.","p":"Right. Give the crossing number."},"es":{"q":"En Virginia, usted llama al número del letrero de emergencia de un cruce de tren para reportar un carro atascado. ¿Qué debe decirles?","o":["Su número de licencia","El número del cruce que aparece en el letrero","El color del tren","Su compañía de seguros"],"h1":"Les ayuda a saber exactamente dónde está el problema.","h2":"En Virginia, cuando llame al número del letrero de emergencia de un cruce, dé el número del cruce para que la compañía de trenes encuentre el lugar exacto.","p":"Correcto. Dé el número del cruce."},"ref":{"doc":"VA","page":10}},{"id":"va-084","scope":"VA","cat":"signs","sign":null,"c":2,"en":{"q":"In Virginia, a work zone sign says photo speed enforcement is in use. What does it mean?","o":["Photos of the road work are being taken","You may speed if no workers are seen","Cameras may record and ticket speeding in the work zone","Only trucks are checked"],"h1":"A camera is watching your speed.","h2":"In Virginia, a Photo Speed Enforcement sign means automated cameras enforce the speed limit in that work zone.","p":"Right. Cameras may ticket speeders in the work zone."},"es":{"q":"En Virginia, un letrero en una zona de obras dice que hay control de velocidad con foto. ¿Qué significa?","o":["Se toman fotos de la obra","Puede ir rápido si no ve trabajadores","Las cámaras pueden registrar y multar el exceso de velocidad en la zona de obras","Solo se revisa a los camiones"],"h1":"Una cámara vigila su velocidad.","h2":"En Virginia, un letrero de control de velocidad con foto significa que cámaras automáticas hacen cumplir el límite de velocidad en esa zona de obras.","p":"Correcto. Las cámaras pueden multar a quien va rápido en la zona de obras."},"ref":{"doc":"VA","page":10}},{"id":"va-085","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, you are leaving a work zone lined with cones and drums. When may you change lanes?","o":["Only after you are completely clear of the work zone","As soon as you pass the last worker","Any time you want","Only when a flagger waves"],"h1":"Wait until all the cones are behind you.","h2":"In Virginia, stay in your lane and keep your speed as you leave a work zone; do not change lanes until you are completely clear of it.","p":"Right. Change lanes only after the work zone ends."},"es":{"q":"En Virginia, usted sale de una zona de obras con conos y barriles. ¿Cuándo puede cambiar de carril?","o":["Solo cuando haya salido por completo de la zona de obras","En cuanto pase al último trabajador","Cuando quiera","Solo cuando un abanderado le haga señas"],"h1":"Espere hasta que todos los conos queden atrás.","h2":"En Virginia, quédese en su carril y mantenga la velocidad al salir de una zona de obras; no cambie de carril hasta haber salido por completo.","p":"Correcto. Cambie de carril solo cuando termine la zona de obras."},"ref":{"doc":"VA","page":10}},{"id":"va-086","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a sign warns of rumble strips before a work zone. How should you handle the strips?","o":["Swerve around them","Speed up to cross them fast","Stop before them","Drive over them slowly"],"h1":"They are meant to be felt, not avoided.","h2":"In Virginia, rumble strips before a work zone should be driven over slowly, not swerved around.","p":"Right. Slow down and drive over them."},"es":{"q":"En Virginia, un letrero advierte de franjas sonoras antes de una zona de obras. ¿Qué debe hacer con las franjas?","o":["Esquivarlas","Acelerar para cruzarlas rápido","Detenerse antes de ellas","Pasar despacio por encima de ellas"],"h1":"Están hechas para sentirse, no para evitarse.","h2":"En Virginia, las franjas sonoras antes de una zona de obras se deben pasar despacio, sin esquivarlas.","p":"Correcto. Baje la velocidad y pase por encima."},"ref":{"doc":"VA","page":11}},{"id":"va-087","scope":"VA","cat":"signs","sign":null,"c":1,"en":{"q":"In Virginia, the orange triangle slow-moving vehicle sign is shown on vehicles that travel at what speed or less?","o":["10 mph","25 mph","45 mph","55 mph"],"h1":"It is the same as the speed limit in many neighborhoods.","h2":"In Virginia, vehicles that travel at 25 mph or less, like farm equipment and horse-drawn vehicles, must show the slow-moving vehicle sign.","p":"Right. 25 mph or less."},"es":{"q":"En Virginia, ¿a qué velocidad o menos van los vehículos que llevan el letrero triangular anaranjado de vehículo lento?","o":["10 mph","25 mph","45 mph","55 mph"],"h1":"Es igual al límite de velocidad de muchos vecindarios.","h2":"En Virginia, los vehículos que van a 25 mph o menos, como la maquinaria agrícola y los carruajes de caballos, deben mostrar el letrero de vehículo lento.","p":"Correcto. 25 mph o menos."},"ref":{"doc":"VA","page":11}},{"id":"va-088","scope":"VA","cat":"signals","sign":null,"c":2,"en":{"q":"In Virginia, the center of the road has double solid yellow lines. When may you cross them?","o":["To pass a slow car","Never, for any reason","To make a left turn","To get ahead in heavy traffic"],"h1":"You are not passing; you are leaving the road.","h2":"In Virginia, you may cross double solid yellow lines to make a left turn, or to pass a pedestrian or bicyclist when the other lane is clear.","p":"Right. You may cross them to turn left."},"es":{"q":"En Virginia, el centro de la vía tiene doble línea amarilla continua. ¿Cuándo puede cruzarla?","o":["Para rebasar a un carro lento","Nunca, por ninguna razón","Para doblar a la izquierda","Para adelantarse en tránsito pesado"],"h1":"No está rebasando; está saliendo de la vía.","h2":"En Virginia, puede cruzar la doble línea amarilla continua para doblar a la izquierda, o para pasar a un peatón o ciclista cuando el otro carril está libre.","p":"Correcto. Puede cruzarla para doblar a la izquierda."},"ref":{"doc":"VA","page":11}},{"id":"va-089","scope":"VA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Virginia, a two-lane road has no lane markings at all. May you pass a slow vehicle?","o":["Yes, on the left, if no sign forbids it and the way is clear","No, never without markings","Yes, on the right shoulder","Only if you honk first"],"h1":"No lines does not automatically mean no passing.","h2":"In Virginia, on an unmarked two-lane road, you may pass a slow vehicle on the left if no signs prohibit passing and the way is clear.","p":"Right. Pass on the left when it is clear and allowed."},"es":{"q":"En Virginia, una vía de dos carriles no tiene ninguna marca de carril. ¿Puede rebasar a un vehículo lento?","o":["Sí, por la izquierda, si ningún letrero lo prohíbe y el camino está libre","No, nunca sin marcas","Sí, por el acotamiento derecho","Solo si toca la bocina primero"],"h1":"Que no haya líneas no significa automáticamente que no se pueda rebasar.","h2":"En Virginia, en una vía de dos carriles sin marcas, puede rebasar a un vehículo lento por la izquierda si ningún letrero lo prohíbe y el camino está libre.","p":"Correcto. Rebase por la izquierda cuando esté libre y permitido."},"ref":{"doc":"VA","page":11}},{"id":"va-090","scope":"VA","cat":"signals","sign":null,"c":3,"en":{"q":"In Virginia, on a three-lane road, the center lane has a single broken yellow line on both sides. What may it be used for?","o":["Parking","Left turns only","Buses only","Passing, by drivers from either direction"],"h1":"Broken lines allow crossing to pass.","h2":"In Virginia, a center lane marked by a single broken yellow line on both sides may be used for passing by drivers going either way.","p":"Right. It is a passing lane for both directions."},"es":{"q":"En Virginia, en una vía de tres carriles, el carril central tiene una sola línea amarilla discontinua a cada lado. ¿Para qué se puede usar?","o":["Para estacionarse","Solo para doblar a la izquierda","Solo para autobuses","Para rebasar, por conductores de ambos sentidos"],"h1":"Las líneas discontinuas permiten cruzar para rebasar.","h2":"En Virginia, un carril central marcado con una sola línea amarilla discontinua a cada lado se puede usar para rebasar por conductores de ambos sentidos.","p":"Correcto. Es un carril para rebasar en ambos sentidos."},"ref":{"doc":"VA","page":12}},{"id":"va-091","scope":"VA","cat":"signals","sign":null,"c":1,"en":{"q":"In Virginia, when may a driver drive in a bicycle lane?","o":["To pass slow traffic","Only when needed to turn, after yielding to bicycles","Any time no bicycle is in sight","During rush hour"],"h1":"It is a short move just before a corner.","h2":"In Virginia, drivers should not drive in a bicycle lane except when needed to turn left or right, and must yield to bicycles in the lane.","p":"Right. Only to make a turn, after yielding to bikes."},"es":{"q":"En Virginia, ¿cuándo puede un conductor manejar en un carril para bicicletas?","o":["Para rebasar al tránsito lento","Solo cuando lo necesita para doblar, después de ceder el paso a las bicicletas","Siempre que no se vea ninguna bicicleta","En las horas pico"],"h1":"Es un movimiento corto justo antes de una esquina.","h2":"En Virginia, los conductores no deben manejar en un carril para bicicletas excepto cuando lo necesitan para doblar a la izquierda o a la derecha, y deben ceder el paso a las bicicletas del carril.","p":"Correcto. Solo para doblar, después de ceder el paso a las bicicletas."},"ref":{"doc":"VA","page":12}},{"id":"va-092","scope":"VA","cat":"signals","sign":null,"c":2,"en":{"q":"In Virginia, an intersection has a green bike box painted before the crosswalk. The light is red. May you turn right?","o":["Yes, after a full stop","Yes, if you stop inside the box","No, right turns on red are not allowed there","Only if a bicycle is in the box"],"h1":"The box is space saved for bicycles.","h2":"In Virginia, right turns on red are not allowed at intersections with bike boxes, and drivers must stop behind the box.","p":"Right. No right turn on red at a bike box."},"es":{"q":"En Virginia, una intersección tiene una caja verde para bicicletas pintada antes del cruce peatonal. El semáforo está en rojo. ¿Puede doblar a la derecha?","o":["Sí, después de detenerse por completo","Sí, si se detiene dentro de la caja","No, allí no se permite doblar a la derecha con luz roja","Solo si hay una bicicleta en la caja"],"h1":"La caja es un espacio reservado para bicicletas.","h2":"En Virginia, no se permite doblar a la derecha con luz roja en intersecciones con caja para bicicletas, y los conductores deben detenerse detrás de la caja.","p":"Correcto. No se dobla a la derecha con rojo donde hay caja para bicicletas."},"ref":{"doc":"VA","page":13}},{"id":"va-093","scope":"VA","cat":"signs","sign":null,"c":0,"en":{"q":"In Virginia, you enter an E-ZPass-only toll lane by mistake, with no transponder. What should you do?","o":["Keep driving; do not stop","Stop and back up","Stop and wait for a worker","Change lanes across the barrier"],"h1":"Stopping there could cause a crash behind you.","h2":"In Virginia, if you enter an E-ZPass-only lane by mistake, do not stop; a camera records the plate and the owner is billed for the toll.","p":"Right. Keep going and pay the bill later."},"es":{"q":"En Virginia, usted entra por error a un carril de peaje solo para E-ZPass, sin transpondedor. ¿Qué debe hacer?","o":["Seguir manejando; no detenerse","Detenerse y dar marcha atrás","Detenerse y esperar a un empleado","Cambiarse de carril cruzando la barrera"],"h1":"Detenerse allí podría causar un choque por detrás.","h2":"En Virginia, si entra por error a un carril solo para E-ZPass, no se detenga; una cámara registra la placa y se le cobra el peaje al dueño.","p":"Correcto. Siga y pague la cuenta después."},"ref":{"doc":"VA","page":13}},{"id":"va-094","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, a curb is painted white. What does it generally mean?","o":["Park for up to two hours","Load and unload goods while staying with the car","Do not stop at all","Stop only long enough to pick up or drop off passengers"],"h1":"Think of a quick stop at an airport.","h2":"In Virginia, a white curb generally means stop only long enough to pick up or drop off passengers.","p":"Right. White means passenger pickup or drop-off only."},"es":{"q":"En Virginia, una acera tiene el borde pintado de blanco. ¿Qué significa generalmente?","o":["Estacionarse hasta dos horas","Cargar y descargar mercancía quedándose con el carro","No detenerse para nada","Detenerse solo el tiempo necesario para recoger o dejar pasajeros"],"h1":"Piense en una parada rápida en un aeropuerto.","h2":"En Virginia, un borde de acera blanco generalmente significa detenerse solo el tiempo necesario para recoger o dejar pasajeros.","p":"Correcto. Blanco significa solo recoger o dejar pasajeros."},"ref":{"doc":"VA","page":13}},{"id":"va-095","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, a curb is painted yellow. What does it generally mean?","o":["Park any time","Stop only to load or unload, and stay with your car","Fire trucks only","Free parking on weekends"],"h1":"This color is for loading.","h2":"In Virginia, a yellow curb generally means stop only long enough to load or unload, and stay with your car.","p":"Right. Yellow means load or unload and stay with the car."},"es":{"q":"En Virginia, una acera tiene el borde pintado de amarillo. ¿Qué significa generalmente?","o":["Estacionarse a cualquier hora","Detenerse solo para cargar o descargar, y quedarse con el carro","Solo camiones de bomberos","Estacionamiento gratis los fines de semana"],"h1":"Este color es para cargar.","h2":"En Virginia, un borde de acera amarillo generalmente significa detenerse solo el tiempo necesario para cargar o descargar, y quedarse con el carro.","p":"Correcto. Amarillo significa cargar o descargar y quedarse con el carro."},"ref":{"doc":"VA","page":13}},{"id":"va-096","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, which vehicle may use an HOV lane during HOV hours even with only one person on it?","o":["A pickup truck","A rental car","A motorcycle","A large SUV"],"h1":"It has two wheels.","h2":"In Virginia, motorcycles may use HOV lanes during HOV hours no matter how many people are riding.","p":"Right. Motorcycles may use HOV lanes."},"es":{"q":"En Virginia, ¿qué vehículo puede usar un carril HOV en horario HOV aunque lleve solo una persona?","o":["Una camioneta pickup","Un carro de alquiler","Una motocicleta","Un SUV grande"],"h1":"Tiene dos ruedas.","h2":"En Virginia, las motocicletas pueden usar los carriles HOV en horario HOV sin importar cuántas personas vayan.","p":"Correcto. Las motos pueden usar los carriles HOV."},"ref":{"doc":"VA","page":13}},{"id":"va-097","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, you move into the state with your car. How soon must you title and register it and get Virginia plates?","o":["Within 7 days","Within one year","Within 30 days","When your old registration runs out"],"h1":"It is the same as the deadline to report a new address.","h2":"In Virginia, new residents must title and register their vehicle and get Virginia license plates within 30 days of moving there.","p":"Right. Within 30 days."},"es":{"q":"En Virginia, usted se muda al estado con su carro. ¿En cuánto tiempo debe titularlo, registrarlo y obtener placas de Virginia?","o":["En 7 días","En un año","En 30 días","Cuando venza su registro anterior"],"h1":"Es el mismo plazo que para reportar una nueva dirección.","h2":"En Virginia, los nuevos residentes deben titular y registrar su vehículo y obtener placas de Virginia en un plazo de 30 días después de mudarse.","p":"Correcto. En 30 días."},"ref":{"doc":"VA","page":33}},{"id":"va-098","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, picture the steering wheel as a clock. Where should your hands be?","o":["One hand at 12 o'clock","At 10 and 2 o'clock, gripping hard with the palms","Both at 6 o'clock","At 8 and 4 o'clock"],"h1":"Lower than the old 10 and 2.","h2":"In Virginia, hold the steering wheel with your hands at about the 8 o'clock and 4 o'clock positions, using your fingers and thumbs.","p":"Right. Hands at 8 and 4."},"es":{"q":"En Virginia, imagine que el volante es un reloj. ¿Dónde deben ir sus manos?","o":["Una mano en las 12","En las 10 y las 2, agarrando fuerte con las palmas","Las dos en las 6","En las 8 y las 4"],"h1":"Más abajo que las antiguas 10 y 2.","h2":"En Virginia, sostenga el volante con las manos más o menos en la posición de las 8 y las 4, usando los dedos y los pulgares.","p":"Correcto. Manos en las 8 y las 4."},"ref":{"doc":"VA","page":14}},{"id":"va-099","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, what kind of offense is reckless driving?","o":["A parking ticket","A criminal misdemeanor","Only a warning","A civil fine that never goes on your record"],"h1":"It can mean jail time.","h2":"In Virginia, reckless driving is a criminal misdemeanor, and the court can fine you, suspend your license or send you to jail.","p":"Right. Reckless driving is a crime in Virginia."},"es":{"q":"En Virginia, ¿qué tipo de delito es el manejo imprudente (reckless driving)?","o":["Una multa de estacionamiento","Un delito menor penal","Solo una advertencia","Una multa civil que nunca aparece en su historial"],"h1":"Puede significar cárcel.","h2":"En Virginia, el manejo imprudente es un delito menor penal, y el tribunal puede multarlo, suspenderle la licencia o mandarlo a la cárcel.","p":"Correcto. El manejo imprudente es un delito en Virginia."},"ref":{"doc":"VA","page":14}},{"id":"va-100","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, it is snowing and you drive at the posted speed limit. Can you still get a speeding-related ticket?","o":["No, the limit is always safe","Only if you pass someone","Yes, for driving too fast for the conditions","Only on interstates"],"h1":"The posted limit is for good weather.","h2":"In Virginia, during rain, snow or ice you may get a ticket for driving too fast for conditions even at or below the posted speed limit.","p":"Right. Too fast for conditions is still a violation."},"es":{"q":"En Virginia, está nevando y usted maneja al límite de velocidad indicado. ¿Le pueden poner una multa relacionada con la velocidad?","o":["No, el límite siempre es seguro","Solo si rebasa a alguien","Sí, por manejar demasiado rápido para las condiciones","Solo en las autopistas interestatales"],"h1":"El límite indicado es para buen tiempo.","h2":"En Virginia, con lluvia, nieve o hielo le pueden poner una multa por manejar demasiado rápido para las condiciones aunque vaya al límite indicado o por debajo.","p":"Correcto. Ir demasiado rápido para las condiciones sigue siendo una infracción."},"ref":{"doc":"VA","page":7}},{"id":"va-101","scope":"VA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Virginia, if no sign says otherwise, what is the speed limit on roads that are not school, business, residential or unpaved?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is the general limit for most other roads.","h2":"In Virginia, unless a sign says otherwise, the speed limit is 55 mph on all roads that are not school, business, residential or unpaved.","p":"Right. 55 mph is the general limit."},"es":{"q":"En Virginia, si ningún letrero dice otra cosa, ¿cuál es el límite de velocidad en las vías que no son escolares, comerciales, residenciales ni sin pavimentar?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es el límite general para la mayoría de las demás vías.","h2":"En Virginia, a menos que un letrero diga otra cosa, el límite es de 55 mph en todas las vías que no son escolares, comerciales, residenciales ni sin pavimentar.","p":"Correcto. 55 mph es el límite general."},"ref":{"doc":"VA","page":15}},{"id":"va-102","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, school crossing zone signs are usually turned on how long before and after regular school hours?","o":["5 minutes","2 hours","All day","30 minutes"],"h1":"It is half an hour.","h2":"In Virginia, school crossing zone signs are set out or lit for 30 minutes before and 30 minutes after regular school hours, and at other times when children are present.","p":"Right. 30 minutes before and after school hours."},"es":{"q":"En Virginia, ¿cuánto tiempo antes y después del horario escolar normal se encienden por lo general los letreros de zona de cruce escolar?","o":["5 minutos","2 horas","Todo el día","30 minutos"],"h1":"Es media hora.","h2":"En Virginia, los letreros de zona de cruce escolar se colocan o se encienden 30 minutos antes y 30 minutos después del horario escolar normal, y en otros momentos en que hay niños.","p":"Correcto. 30 minutos antes y después del horario escolar."},"ref":{"doc":"VA","page":null}},{"id":"va-103","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, what is the highest fine for speeding in an active, posted school crossing zone?","o":["$50","$250","$1,000","$2,500"],"h1":"It is half of the work zone maximum.","h2":"In Virginia, speeding in an active, posted school crossing zone can bring a fine of up to $250, plus other penalties.","p":"Right. Up to $250."},"es":{"q":"En Virginia, ¿cuál es la multa más alta por exceso de velocidad en una zona de cruce escolar activa y señalizada?","o":["$50","$250","$1,000","$2,500"],"h1":"Es la mitad del máximo en zonas de obras.","h2":"En Virginia, ir a exceso de velocidad en una zona de cruce escolar activa y señalizada puede costar una multa de hasta $250, además de otras sanciones.","p":"Correcto. Hasta $250."},"ref":{"doc":"VA","page":null}},{"id":"va-104","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, a sign on a residential street shows the speed limit and says $200 ADDITIONAL FINE. What does it mean?","o":["The fine applies only to trucks","It is only a warning","Speeding there adds a $200 fine on top of other penalties","Parking there costs $200"],"h1":"It comes on top of the normal ticket.","h2":"In Virginia, on residential streets posted with this sign, speeding brings a $200 fine in addition to other penalties.","p":"Right. Speeding there costs an extra $200."},"es":{"q":"En Virginia, un letrero en una calle residencial muestra el límite de velocidad y dice $200 ADDITIONAL FINE. ¿Qué significa?","o":["La multa es solo para camiones","Es solo una advertencia","Ir a exceso de velocidad allí suma una multa de $200 a las demás sanciones","Estacionarse allí cuesta $200"],"h1":"Se suma a la multa normal.","h2":"En Virginia, en calles residenciales con este letrero, ir a exceso de velocidad trae una multa de $200 además de otras sanciones.","p":"Correcto. Ir rápido allí cuesta $200 extra."},"ref":{"doc":"VA","page":null}},{"id":"va-105","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, a driver is convicted of a first DUI with a blood alcohol level of 0.16. What is added to the penalty?","o":["At least five extra days in jail","Nothing more","A $10 fine","A free safety class"],"h1":"A higher blood alcohol level means mandatory jail time.","h2":"In Virginia, a first DUI with a blood alcohol level of 0.15 to 0.20 adds a mandatory minimum of five days in jail; above 0.20, it adds 10 days.","p":"Right. Five more days in jail."},"es":{"q":"En Virginia, un conductor es condenado por un primer DUI con un nivel de alcohol en la sangre de 0.16. ¿Qué se agrega a la pena?","o":["Por lo menos cinco días extra de cárcel","Nada más","Una multa de $10","Una clase de seguridad gratis"],"h1":"Un nivel de alcohol más alto significa cárcel obligatoria.","h2":"En Virginia, un primer DUI con un nivel de alcohol en la sangre de 0.15 a 0.20 agrega un mínimo obligatorio de cinco días de cárcel; por encima de 0.20, agrega 10 días.","p":"Correcto. Cinco días más de cárcel."},"ref":{"doc":"VA","page":null}},{"id":"va-106","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, at a stop sign, the car in front of you stops and then goes. What should you do?","o":["Follow it through without stopping","Honk so it hurries","Go around it on the shoulder","Stop at the sign yourself, then go when it is clear"],"h1":"Each car must make its own stop.","h2":"In Virginia, when the car ahead goes through a stop sign, you must still stop at the sign and go only when the way is clear.","p":"Right. Every car stops at the sign."},"es":{"q":"En Virginia, en un letrero de alto, el carro de adelante se detiene y luego sigue. ¿Qué debe hacer?","o":["Seguirlo sin detenerse","Tocar la bocina para que se apure","Rodearlo por el acotamiento","Detenerse usted también en el letrero y seguir cuando esté despejado"],"h1":"Cada carro debe hacer su propio alto.","h2":"En Virginia, cuando el carro de adelante pasa un letrero de alto, usted igual debe detenerse en el letrero y seguir solo cuando el camino esté libre.","p":"Correcto. Cada carro se detiene en el letrero."},"ref":{"doc":"VA","page":15}},{"id":"va-107","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, a school bus is stopped in a school driveway with its red lights flashing and its stop sign out. Must you stop?","o":["No, the rule is for highways only","Yes, the rule also covers private roads and school driveways","Only if children are in the road","Only in the morning"],"h1":"The rule is not only for public streets.","h2":"In Virginia, you must stop for a stopped school bus with flashing red lights and its stop sign out on a highway, a private road or a school driveway.","p":"Right. Stop for it there too."},"es":{"q":"En Virginia, un autobús escolar está detenido en la entrada de una escuela con las luces rojas parpadeando y la señal de alto extendida. ¿Debe detenerse?","o":["No, la regla es solo para carreteras","Sí, la regla también cubre caminos privados y entradas de escuelas","Solo si hay niños en la vía","Solo en la mañana"],"h1":"La regla no es solo para calles públicas.","h2":"En Virginia, debe detenerse ante un autobús escolar detenido con luces rojas parpadeando y la señal de alto extendida en una carretera, un camino privado o la entrada de una escuela.","p":"Correcto. También debe detenerse allí."},"ref":{"doc":"VA","page":15}},{"id":"va-108","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, a school bus is loading children, but its warning signals are not on. What must you do?","o":["Pass slowly","Honk and pass","Stop anyway","Flash your lights and pass"],"h1":"What matters is children getting on and off.","h2":"In Virginia, you must also stop for a school bus that is loading or unloading passengers even when its signals are not on.","p":"Right. Stop whenever the bus is loading or unloading."},"es":{"q":"En Virginia, un autobús escolar está subiendo niños, pero sus señales de advertencia no están encendidas. ¿Qué debe hacer?","o":["Pasar despacio","Tocar la bocina y pasar","Detenerse de todos modos","Hacer cambio de luces y pasar"],"h1":"Lo que importa son los niños que suben y bajan.","h2":"En Virginia, también debe detenerse ante un autobús escolar que está subiendo o bajando pasajeros aunque sus señales no estén encendidas.","p":"Correcto. Deténgase siempre que el autobús esté subiendo o bajando pasajeros."},"ref":{"doc":"VA","page":15}},{"id":"va-109","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, you pass a school bus that is stopped to let children off. What can you be charged with?","o":["Reckless driving","Improper parking","A seat belt violation","Nothing, if no child was hurt"],"h1":"It is the same charge as driving 20 mph over the limit.","h2":"In Virginia, passing a school bus that is stopped to load or unload children is reckless driving.","p":"Right. Passing a stopped school bus is reckless driving."},"es":{"q":"En Virginia, usted rebasa a un autobús escolar detenido para bajar niños. ¿De qué lo pueden acusar?","o":["De manejo imprudente (reckless driving)","De estacionarse mal","De no usar el cinturón","De nada, si ningún niño salió herido"],"h1":"Es el mismo cargo que manejar 20 mph sobre el límite.","h2":"En Virginia, rebasar a un autobús escolar detenido para subir o bajar niños es manejo imprudente.","p":"Correcto. Rebasar un autobús escolar detenido es manejo imprudente."},"ref":{"doc":"VA","page":null}},{"id":"va-110","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, a camera on a school bus records a car passing it while it is stopped with its signals on. What civil penalty can the owner face?","o":["$25","$50","$100","$250"],"h1":"It is a few hundred dollars.","h2":"In Virginia, a driver who passes a stopped school bus can face a $250 civil penalty, and cameras on the bus may be used to prove it.","p":"Right. The civil penalty is $250."},"es":{"q":"En Virginia, una cámara en un autobús escolar graba a un carro que lo rebasa mientras está detenido con las señales encendidas. ¿Qué multa civil puede recibir el dueño?","o":["$25","$50","$100","$250"],"h1":"Son unos cientos de dólares.","h2":"En Virginia, un conductor que rebasa a un autobús escolar detenido puede recibir una multa civil de $250, y se pueden usar las cámaras del autobús como prueba.","p":"Correcto. La multa civil es de $250."},"ref":{"doc":"VA","page":null}},{"id":"va-111","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, how can wet pavement change your braking distance?","o":["It cuts it in half","It can double it","It does not change it","It makes it much shorter"],"h1":"It gets longer, by a lot.","h2":"In Virginia, wet pavement can double your braking distance.","p":"Right. Wet roads can double the distance."},"es":{"q":"En Virginia, ¿cómo puede cambiar el pavimento mojado su distancia de frenado?","o":["La reduce a la mitad","La puede duplicar","No la cambia","La hace mucho más corta"],"h1":"Se hace más larga, y mucho.","h2":"En Virginia, el pavimento mojado puede duplicar su distancia de frenado.","p":"Correcto. El pavimento mojado puede duplicar la distancia."},"ref":{"doc":"VA","page":15}},{"id":"va-112","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, a military convoy is passing on the road. What should you do?","o":["Join the end of it","Cut through a gap in it","Yield, and never cut through or join it","Pass it on the shoulder"],"h1":"Treat it like a funeral procession.","h2":"In Virginia, you must yield to military convoys and must never cut through or join one.","p":"Right. Yield and stay out of the convoy."},"es":{"q":"En Virginia, un convoy militar pasa por la vía. ¿Qué debe hacer?","o":["Unirse al final","Cruzar por un espacio entre los vehículos","Ceder el paso, y nunca cruzarlo ni unirse a él","Rebasarlo por el acotamiento"],"h1":"Trátelo como un cortejo fúnebre.","h2":"En Virginia, debe ceder el paso a los convoyes militares y nunca debe cruzarlos ni unirse a ellos.","p":"Correcto. Ceda el paso y manténgase fuera del convoy."},"ref":{"doc":"VA","page":16}},{"id":"va-113","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, a funeral procession has no police escort. Who must obey traffic signs and signals?","o":["The lead vehicle","No one in the procession","Only the last car","Only cars without flashers"],"h1":"The first car sets the path for the others.","h2":"In Virginia, unless a police escort leads it, the lead vehicle of a funeral procession must obey all traffic signs and signals, and the others may follow carefully.","p":"Right. The lead vehicle must obey signs and signals."},"es":{"q":"En Virginia, un cortejo fúnebre no tiene escolta policial. ¿Quién debe obedecer las señales y semáforos?","o":["El vehículo que va adelante","Nadie del cortejo","Solo el último carro","Solo los carros sin luces intermitentes"],"h1":"El primer carro marca el camino para los demás.","h2":"En Virginia, a menos que lo dirija una escolta policial, el vehículo que encabeza un cortejo fúnebre debe obedecer todas las señales y semáforos, y los demás pueden seguirlo con cuidado.","p":"Correcto. El vehículo de adelante debe obedecer las señales y semáforos."},"ref":{"doc":"VA","page":16}},{"id":"va-114","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, fire trucks are stopped to answer an alarm. How close may you park to them?","o":["50 feet","100 feet","200 feet","No closer than 500 feet"],"h1":"It is the same distance as for following a fire truck.","h2":"In Virginia, you may not park within 500 feet of where fire trucks or equipment are stopped answering an alarm.","p":"Right. Park at least 500 feet away."},"es":{"q":"En Virginia, unos camiones de bomberos están detenidos atendiendo una alarma. ¿Qué tan cerca de ellos puede estacionarse?","o":["50 pies","100 pies","200 pies","No más cerca de 500 pies"],"h1":"Es la misma distancia que para seguir a un camión de bomberos.","h2":"En Virginia, no puede estacionarse a menos de 500 pies de donde hay camiones o equipos de bomberos detenidos atendiendo una alarma.","p":"Correcto. Estaciónese por lo menos a 500 pies."},"ref":{"doc":"VA","page":16}},{"id":"va-115","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, an ambulance with its siren and lights on is coming toward you on an undivided two-lane road. What must you do?","o":["Keep driving at the same speed","Pull to the edge of the road and stop until it passes","Speed up to clear the way","Stop in the middle of your lane"],"h1":"It does not matter that it is in the other lane.","h2":"In Virginia, when an emergency vehicle approaches from the opposite direction on an undivided highway, pull over to the edge of the road and stop until it passes.","p":"Right. Pull over and stop, even for oncoming emergency vehicles."},"es":{"q":"En Virginia, una ambulancia con la sirena y las luces encendidas viene hacia usted en una vía de dos carriles sin división. ¿Qué debe hacer?","o":["Seguir a la misma velocidad","Orillarse al borde de la vía y detenerse hasta que pase","Acelerar para abrir paso","Detenerse en medio de su carril"],"h1":"No importa que vaya por el otro carril.","h2":"En Virginia, cuando un vehículo de emergencia viene en sentido contrario en una carretera sin división, orille el carro al borde de la vía y deténgase hasta que pase.","p":"Correcto. Oríllese y deténgase, aunque el vehículo de emergencia venga de frente."},"ref":{"doc":"VA","page":16}},{"id":"va-116","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, a driver passes a moving ambulance that has its siren on and lights flashing. What offense is this?","o":["A parking violation","No offense if done carefully","Reckless driving","Only a warning"],"h1":"It is as serious as passing a stopped school bus.","h2":"In Virginia, overtaking or passing a moving emergency vehicle that is using its siren and warning lights is reckless driving.","p":"Right. It is reckless driving."},"es":{"q":"En Virginia, un conductor rebasa a una ambulancia en movimiento que lleva la sirena y las luces encendidas. ¿Qué infracción es?","o":["Una infracción de estacionamiento","Ninguna si lo hace con cuidado","Manejo imprudente (reckless driving)","Solo una advertencia"],"h1":"Es tan grave como rebasar un autobús escolar detenido.","h2":"En Virginia, alcanzar o rebasar a un vehículo de emergencia en movimiento que usa la sirena y las luces de advertencia es manejo imprudente.","p":"Correcto. Es manejo imprudente."},"ref":{"doc":"VA","page":null}},{"id":"va-117","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, you are going straight through a roundabout that has two lanes. Which lane may you use?","o":["Either lane","Only the left lane","Only the right lane","The shoulder"],"h1":"Going straight gives you a choice.","h2":"In Virginia, if you plan to go straight through a two-lane roundabout, you may use either lane.","p":"Right. Either lane works for going straight."},"es":{"q":"En Virginia, usted va a seguir derecho por una glorieta de dos carriles. ¿Qué carril puede usar?","o":["Cualquiera de los dos carriles","Solo el carril izquierdo","Solo el carril derecho","El acotamiento"],"h1":"Seguir derecho le da a escoger.","h2":"En Virginia, si piensa seguir derecho por una glorieta de dos carriles, puede usar cualquiera de los dos carriles.","p":"Correcto. Para seguir derecho sirve cualquier carril."},"ref":{"doc":"VA","page":16}},{"id":"va-118","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, you are passing a slow car on a highway. May you go over the speed limit to finish passing?","o":["Yes, by up to 10 mph","Yes, for 15 seconds","Yes, if the other car speeds up","No, it is against the law"],"h1":"The limit does not change while you pass.","h2":"In Virginia, it is against the law to go over the speed limit while passing.","p":"Right. Passing does not allow speeding."},"es":{"q":"En Virginia, usted está rebasando a un carro lento en una carretera. ¿Puede pasarse del límite de velocidad para terminar de rebasar?","o":["Sí, hasta 10 mph más","Sí, por 15 segundos","Sí, si el otro carro acelera","No, va contra la ley"],"h1":"El límite no cambia mientras rebasa.","h2":"En Virginia, es ilegal pasarse del límite de velocidad mientras rebasa.","p":"Correcto. Rebasar no permite ir a exceso de velocidad."},"ref":{"doc":"VA","page":17}},{"id":"va-119","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, you are passing on a two-lane road and reach a No Passing zone while still in the left lane. What is true?","o":["It is fine if you hurry","You are breaking the law","You may stay left until the next curve","You only need to signal"],"h1":"The pass must be finished before the zone starts.","h2":"In Virginia, you must finish passing before you reach a No Passing zone; if you are still in the left lane there, you are breaking the law.","p":"Right. Finish the pass before the zone."},"es":{"q":"En Virginia, usted está rebasando en una vía de dos carriles y llega a una zona de No Rebasar todavía en el carril izquierdo. ¿Qué es cierto?","o":["Está bien si se apura","Está violando la ley","Puede seguir a la izquierda hasta la próxima curva","Solo necesita poner la direccional"],"h1":"Debe terminar de rebasar antes de que empiece la zona.","h2":"En Virginia, debe terminar de rebasar antes de llegar a una zona de No Rebasar; si todavía está en el carril izquierdo allí, está violando la ley.","p":"Correcto. Termine de rebasar antes de la zona."},"ref":{"doc":"VA","page":17}},{"id":"va-120","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, the car ahead is turning left. May you pass it on the right by driving onto the shoulder?","o":["Yes, the shoulder is always open","Yes, if you go slowly","No, not by driving off the pavement or onto the shoulder","Only on interstates"],"h1":"Stay on the main road surface.","h2":"In Virginia, you may pass on the right only if you can do it without driving off the pavement or onto the shoulder.","p":"Right. Do not use the shoulder to pass."},"es":{"q":"En Virginia, el carro de adelante va a doblar a la izquierda. ¿Puede rebasarlo por la derecha manejando por el acotamiento?","o":["Sí, el acotamiento siempre está disponible","Sí, si va despacio","No, no saliéndose del pavimento ni por el acotamiento","Solo en autopistas interestatales"],"h1":"Quédese en la superficie principal de la vía.","h2":"En Virginia, solo puede rebasar por la derecha si puede hacerlo sin salirse del pavimento ni manejar por el acotamiento.","p":"Correcto. No use el acotamiento para rebasar."},"ref":{"doc":"VA","page":17}},{"id":"va-121","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, a driver is convicted of reckless driving for passing on the crest of a hill. How many demerit points are added?","o":["6","1","3","12"],"h1":"It is the highest point level.","h2":"In Virginia, reckless driving, including passing on the crest of a hill where the view is blocked, carries 6 demerit points.","p":"Right. Reckless driving is a 6-point violation."},"es":{"q":"En Virginia, un conductor es condenado por manejo imprudente por rebasar en la cima de una colina. ¿Cuántos puntos de demérito se le agregan?","o":["6","1","3","12"],"h1":"Es el nivel de puntos más alto.","h2":"En Virginia, el manejo imprudente, incluido rebasar en la cima de una colina sin visibilidad, lleva 6 puntos de demérito.","p":"Correcto. El manejo imprudente es una infracción de 6 puntos."},"ref":{"doc":"VA","page":null}},{"id":"va-122","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, you and an oncoming car both want to turn left at the same intersection. How should you turn?","o":["Behind each other, with the driver's sides together","One waits until the other finishes and leaves","Both make a U-turn","In front of each other, so the passenger sides pass side by side"],"h1":"Each car passes in front of the other.","h2":"In Virginia, when two facing cars both turn left, they should turn in front of each other so their passenger sides are beside each other.","p":"Right. Turn in front of each other."},"es":{"q":"En Virginia, usted y un carro que viene de frente quieren doblar a la izquierda en la misma intersección. ¿Cómo deben doblar?","o":["Por detrás uno del otro, con los lados del conductor juntos","Uno espera a que el otro termine y se vaya","Los dos dan vuelta en U","Por delante uno del otro, de modo que los lados del pasajero queden uno junto al otro"],"h1":"Cada carro pasa por delante del otro.","h2":"En Virginia, cuando dos carros de frente doblan a la izquierda, deben doblar por delante uno del otro para que los lados del pasajero queden uno junto al otro.","p":"Correcto. Doblen por delante uno del otro."},"ref":{"doc":"VA","page":18}},{"id":"va-123","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, you are stopped, waiting to turn left. How should your front wheels point?","o":["Turned left, ready to go","Straight ahead until you start the turn","Turned right","It does not matter"],"h1":"Think about what happens if someone hits you from behind.","h2":"In Virginia, keep your front wheels pointed straight ahead until you actually turn left, so a rear-end crash does not push you into oncoming traffic.","p":"Right. Keep the wheels straight until you turn."},"es":{"q":"En Virginia, usted está detenido esperando para doblar a la izquierda. ¿Hacia dónde deben apuntar sus ruedas delanteras?","o":["Giradas a la izquierda, listas para salir","Rectas hasta que empiece a doblar","Giradas a la derecha","No importa"],"h1":"Piense en qué pasa si alguien lo choca por detrás.","h2":"En Virginia, mantenga las ruedas delanteras rectas hasta que realmente doble a la izquierda, para que un choque por detrás no lo empuje hacia el tránsito que viene de frente.","p":"Correcto. Mantenga las ruedas rectas hasta doblar."},"ref":{"doc":"VA","page":18}},{"id":"va-124","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, in a business district of a city or town, where may you make a U-turn?","o":["Anywhere in the middle of a block","In a private driveway","Only at intersections","On the highway"],"h1":"Think of a place where streets cross.","h2":"In Virginia, in business districts, cities and towns, U-turns are allowed only at intersections, and never on a highway.","p":"Right. Only at intersections."},"es":{"q":"En Virginia, en una zona comercial de una ciudad o pueblo, ¿dónde puede dar una vuelta en U?","o":["En cualquier punto a mitad de cuadra","En una entrada privada","Solo en las intersecciones","En la carretera"],"h1":"Piense en un lugar donde se cruzan las calles.","h2":"En Virginia, en zonas comerciales, ciudades y pueblos, las vueltas en U se permiten solo en las intersecciones, y nunca en una carretera.","p":"Correcto. Solo en las intersecciones."},"ref":{"doc":"VA","page":18}},{"id":"va-125","scope":"VA","cat":"signals","sign":null,"c":0,"en":{"q":"In Virginia, the speed limit is 25 mph. At least how far before a turn must you signal?","o":["50 feet","500 feet","300 feet","Only as you turn"],"h1":"It is half the distance used on faster roads.","h2":"In Virginia, a turn signal must be given for at least 100 feet where the speed limit is over 35 mph, and for at least 50 feet on slower roads.","p":"Right. At least 50 feet on a 25 mph road."},"es":{"q":"En Virginia, el límite de velocidad es de 25 mph. ¿Por lo menos a qué distancia antes de doblar debe poner la señal?","o":["50 pies","500 pies","300 pies","Solo al momento de doblar"],"h1":"Es la mitad de la distancia que se usa en vías más rápidas.","h2":"En Virginia, la señal para doblar se debe dar por lo menos 100 pies antes donde el límite es mayor de 35 mph, y por lo menos 50 pies en vías más lentas.","p":"Correcto. Por lo menos 50 pies en una vía de 25 mph."},"ref":{"doc":"VA","page":null}},{"id":"va-126","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, you are driving 40 mph on a dry road. How many seconds should you stay behind the car ahead?","o":["1 second","2 seconds","6 seconds","3 seconds"],"h1":"Your speed is between 35 and 45 mph.","h2":"In Virginia, the manual suggests 2 seconds under 35 mph, 3 seconds at 35 to 45 mph, and 4 seconds at 46 to 70 mph on dry roads.","p":"Right. 3 seconds at 40 mph."},"es":{"q":"En Virginia, usted maneja a 40 mph en una vía seca. ¿Cuántos segundos debe mantenerse detrás del carro de adelante?","o":["1 segundo","2 segundos","6 segundos","3 segundos"],"h1":"Su velocidad está entre 35 y 45 mph.","h2":"En Virginia, el manual sugiere 2 segundos a menos de 35 mph, 3 segundos de 35 a 45 mph y 4 segundos de 46 a 70 mph en vías secas.","p":"Correcto. 3 segundos a 40 mph."},"ref":{"doc":"VA","page":19}},{"id":"va-127","scope":"VA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Virginia, you are driving 60 mph on a dry highway. What following distance does the manual suggest?","o":["2 seconds","4 seconds","10 seconds","1 second"],"h1":"It is the longest gap in the manual's table.","h2":"In Virginia, at 46 to 70 mph on a dry road, keep at least a 4-second following distance.","p":"Right. 4 seconds at highway speed."},"es":{"q":"En Virginia, usted maneja a 60 mph en una carretera seca. ¿Qué distancia de seguimiento sugiere el manual?","o":["2 segundos","4 segundos","10 segundos","1 segundo"],"h1":"Es el espacio más largo de la tabla del manual.","h2":"En Virginia, de 46 a 70 mph en una vía seca, mantenga por lo menos 4 segundos de distancia.","p":"Correcto. 4 segundos a velocidad de carretera."},"ref":{"doc":"VA","page":19}},{"id":"va-128","scope":"VA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Virginia, you are following a motorcycle on a dry road. How should you change your following distance?","o":["Follow closer","Keep the usual distance","Add an extra second","Drive beside it instead"],"h1":"Give yourself more room to brake.","h2":"In Virginia, add an extra second to the following distance rule when you are behind a motorcycle, and double the distance in bad weather.","p":"Right. Add a second behind a motorcycle."},"es":{"q":"En Virginia, usted va detrás de una motocicleta en una vía seca. ¿Cómo debe cambiar su distancia de seguimiento?","o":["Acercarse más","Mantener la distancia normal","Agregar un segundo más","Manejar a su lado"],"h1":"Dese más espacio para frenar.","h2":"En Virginia, agregue un segundo más a la regla de distancia cuando va detrás de una motocicleta, y duplique la distancia con mal tiempo.","p":"Correcto. Agregue un segundo detrás de una moto."},"ref":{"doc":"VA","page":20}},{"id":"va-129","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, how far ahead do expert drivers try to look, which is about one block in the city?","o":["20 to 30 seconds","2 to 3 seconds","5 minutes","Only to the car in front"],"h1":"It is less than a minute.","h2":"In Virginia, expert drivers focus their eyes 20 to 30 seconds ahead, which is about one block in the city.","p":"Right. 20 to 30 seconds ahead."},"es":{"q":"En Virginia, ¿qué tan adelante tratan de mirar los conductores expertos, lo que en la ciudad es como una cuadra?","o":["De 20 a 30 segundos","De 2 a 3 segundos","5 minutos","Solo hasta el carro de adelante"],"h1":"Es menos de un minuto.","h2":"En Virginia, los conductores expertos fijan la vista de 20 a 30 segundos adelante, lo que en la ciudad es más o menos una cuadra.","p":"Correcto. De 20 a 30 segundos adelante."},"ref":{"doc":"VA","page":19}},{"id":"va-130","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, before you drive through an intersection, which way should you look first?","o":["Right","Straight up","Behind you","Left"],"h1":"Cars from that side will reach you first.","h2":"In Virginia, look left first at an intersection because cars coming from the left are closer to you, then look right, then left again.","p":"Right. Left, right, then left again."},"es":{"q":"En Virginia, antes de cruzar una intersección, ¿hacia dónde debe mirar primero?","o":["A la derecha","Hacia arriba","Hacia atrás","A la izquierda"],"h1":"Los carros de ese lado lo alcanzarán primero.","h2":"En Virginia, mire primero a la izquierda en una intersección porque los carros que vienen de la izquierda están más cerca, luego a la derecha y otra vez a la izquierda.","p":"Correcto. Izquierda, derecha y otra vez izquierda."},"ref":{"doc":"VA","page":19}},{"id":"va-131","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, may you drive while wearing earphones in both ears?","o":["Yes, if the music is quiet","No, it is illegal","Yes, on highways","Only for phone calls"],"h1":"You need to hear sirens and horns.","h2":"In Virginia, it is illegal to drive a car, or ride a bicycle or moped, while wearing earphones in both ears.","p":"Right. Not in both ears."},"es":{"q":"En Virginia, ¿puede manejar con audífonos en los dos oídos?","o":["Sí, si la música está baja","No, es ilegal","Sí, en las carreteras","Solo para llamadas"],"h1":"Necesita oír sirenas y bocinas.","h2":"En Virginia, es ilegal manejar un carro, o andar en bicicleta o motoneta, con audífonos en los dos oídos.","p":"Correcto. No en los dos oídos."},"ref":{"doc":"VA","page":null}},{"id":"va-132","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, on which roads are bicycles generally not allowed?","o":["Neighborhood streets","Two-lane country roads","Interstates and most freeways","Any road with a speed limit over 25 mph"],"h1":"Think of high-speed, limited-access roads.","h2":"In Virginia, bicyclists may ride on all public roads except interstates and most freeways (limited access highways).","p":"Right. No bicycles on interstates and most freeways."},"es":{"q":"En Virginia, ¿en qué vías por lo general no se permiten bicicletas?","o":["En las calles de vecindario","En caminos rurales de dos carriles","En autopistas interestatales y la mayoría de las autopistas de acceso limitado","En cualquier vía con límite de más de 25 mph"],"h1":"Piense en vías rápidas de acceso limitado.","h2":"En Virginia, los ciclistas pueden andar en todas las vías públicas excepto en las autopistas interestatales y la mayoría de las autopistas de acceso limitado.","p":"Correcto. No hay bicicletas en interestatales ni en la mayoría de las autopistas."},"ref":{"doc":"VA","page":20}},{"id":"va-133","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, a driver fails to stop for a pedestrian who is lawfully crossing and seriously injures them. What can the offense be?","o":["A Class 1 misdemeanor","A parking ticket","Only a warning","No offense"],"h1":"It is a crime, not just a ticket.","h2":"In Virginia, failing to stop for a pedestrian who is lawfully crossing and causing serious injury or death can be a Class 1 misdemeanor.","p":"Right. It can be a Class 1 misdemeanor."},"es":{"q":"En Virginia, un conductor no se detiene ante un peatón que cruza legalmente y lo hiere gravemente. ¿Qué delito puede ser?","o":["Un delito menor de Clase 1","Una multa de estacionamiento","Solo una advertencia","Ningún delito"],"h1":"Es un delito, no solo una multa.","h2":"En Virginia, no detenerse ante un peatón que cruza legalmente y causarle heridas graves o la muerte puede ser un delito menor de Clase 1.","p":"Correcto. Puede ser un delito menor de Clase 1."},"ref":{"doc":"VA","page":20}},{"id":"va-134","scope":"VA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Virginia, when may a bicyclist ride in the center of the lane?","o":["Never","Only on interstates","Only at night","When needed, such as before a left turn or when the lane is too narrow to share"],"h1":"Sometimes the edge of the road is not safe.","h2":"In Virginia, a bicyclist may ride in the center of the lane when necessary, such as when about to turn left or when the lane is too narrow to share side by side with a car.","p":"Right. Bikes may take the lane when needed."},"es":{"q":"En Virginia, ¿cuándo puede un ciclista andar en el centro del carril?","o":["Nunca","Solo en las autopistas interestatales","Solo de noche","Cuando sea necesario, por ejemplo antes de doblar a la izquierda o si el carril es muy angosto para compartirlo"],"h1":"A veces la orilla de la vía no es segura.","h2":"En Virginia, un ciclista puede andar en el centro del carril cuando sea necesario, por ejemplo cuando va a doblar a la izquierda o cuando el carril es muy angosto para compartirlo lado a lado con un carro.","p":"Correcto. Las bicicletas pueden ocupar el carril cuando hace falta."},"ref":{"doc":"VA","page":20}},{"id":"va-135","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, you must stop for pedestrians crossing at any intersection, even without crosswalk lines, on roads with speed limits up to what?","o":["15 mph","35 mph","55 mph","70 mph"],"h1":"It is a typical city street speed.","h2":"In Virginia, drivers must stop for pedestrians at marked crosswalks, and at any intersection on roads with a speed limit of 35 mph or less.","p":"Right. Up to 35 mph."},"es":{"q":"En Virginia, ¿hasta qué límite de velocidad debe detenerse ante peatones que cruzan en cualquier intersección, aun sin líneas de cruce?","o":["15 mph","35 mph","55 mph","70 mph"],"h1":"Es una velocidad típica de calle de ciudad.","h2":"En Virginia, los conductores deben detenerse ante peatones en los cruces marcados, y en cualquier intersección de vías con límite de 35 mph o menos.","p":"Correcto. Hasta 35 mph."},"ref":{"doc":"VA","page":null}},{"id":"va-136","scope":"VA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Virginia, a car in the lane next to you is stopped at a crosswalk for a pedestrian. What must you do?","o":["Pass it carefully","Honk and pass","Do not pass it; stop as well","Drive around it on the shoulder"],"h1":"Someone may be walking in front of that car.","h2":"In Virginia, passing at a crosswalk is illegal; do not pass a vehicle that is stopped for a pedestrian at a crosswalk.","p":"Right. Do not pass a car stopped at a crosswalk."},"es":{"q":"En Virginia, un carro en el carril de al lado está detenido en un cruce peatonal por un peatón. ¿Qué debe hacer?","o":["Rebasarlo con cuidado","Tocar la bocina y rebasar","No rebasarlo; detenerse también","Rodearlo por el acotamiento"],"h1":"Puede haber alguien caminando delante de ese carro.","h2":"En Virginia, rebasar en un cruce peatonal es ilegal; no rebase a un vehículo detenido por un peatón en un cruce.","p":"Correcto. No rebase a un carro detenido en un cruce peatonal."},"ref":{"doc":"VA","page":20}},{"id":"va-137","scope":"VA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Virginia, you drive near The Tide light rail in Norfolk. What should you never do on the train tracks?","o":["Stop, pass or shift gears","Look both ways","Obey the signals","Cross when the way is clear"],"h1":"Keep moving straight across.","h2":"In Virginia, near The Tide light rail, never stop, pass or shift gears on the train tracks.","p":"Right. Never stop, pass or shift on the tracks."},"es":{"q":"En Virginia, usted maneja cerca del tren ligero The Tide en Norfolk. ¿Qué nunca debe hacer sobre las vías del tren?","o":["Detenerse, rebasar o cambiar de marcha","Mirar a ambos lados","Obedecer las señales","Cruzar cuando esté despejado"],"h1":"Siga derecho sin detenerse.","h2":"En Virginia, cerca del tren ligero The Tide, nunca se detenga, rebase ni cambie de marcha sobre las vías del tren.","p":"Correcto. Nunca se detenga, rebase ni cambie de marcha sobre las vías."},"ref":{"doc":"VA","page":21}},{"id":"va-138","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, a low speed vehicle may be driven on public roads with speed limits up to what?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"It is a little more than the vehicle's own top speed.","h2":"In Virginia, low speed vehicles may be driven on public roads with speed limits of 35 mph or less.","p":"Right. Roads posted 35 mph or less."},"es":{"q":"En Virginia, ¿en vías públicas con límites de hasta cuánto se puede manejar un vehículo de baja velocidad?","o":["25 mph","45 mph","55 mph","35 mph"],"h1":"Es un poco más que la velocidad máxima del propio vehículo.","h2":"En Virginia, los vehículos de baja velocidad se pueden manejar en vías públicas con límites de 35 mph o menos.","p":"Correcto. Vías con límite de 35 mph o menos."},"ref":{"doc":"VA","page":21}},{"id":"va-139","scope":"VA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Virginia, a large truck's blind spot behind it can stretch about how far?","o":["10 feet","200 feet","2 miles","50 feet"],"h1":"It is longer than half a football field.","h2":"In Virginia, the blind spots of trucks, buses and RVs may stretch up to 20 feet in front of the cab and about 200 feet behind the vehicle.","p":"Right. About 200 feet behind."},"es":{"q":"En Virginia, ¿más o menos hasta dónde puede extenderse el punto ciego detrás de un camión grande?","o":["10 pies","200 pies","2 millas","50 pies"],"h1":"Es más que la mitad de un campo de fútbol americano.","h2":"En Virginia, los puntos ciegos de camiones, autobuses y casas rodantes pueden extenderse hasta 20 pies delante de la cabina y unos 200 pies detrás del vehículo.","p":"Correcto. Unos 200 pies detrás."},"ref":{"doc":"VA","page":21}},{"id":"va-140","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, who on a motorcycle must wear a helmet?","o":["Only riders under 18","Only the driver","Both the operator and any passenger","No one, helmets are optional"],"h1":"Everyone on the bike.","h2":"In Virginia, motorcycle operators and their passengers must wear protective helmets.","p":"Right. Operator and passenger both."},"es":{"q":"En Virginia, ¿quién debe usar casco en una motocicleta?","o":["Solo los menores de 18 años","Solo el conductor","Tanto el conductor como cualquier pasajero","Nadie, el casco es opcional"],"h1":"Todos los que van en la moto.","h2":"En Virginia, los conductores de motocicleta y sus pasajeros deben usar casco protector.","p":"Correcto. El conductor y el pasajero."},"ref":{"doc":"VA","page":null}},{"id":"va-141","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, the trailer you are towing starts to sway. What should you do?","o":["Slow down","Speed up","Brake hard and turn sharply","Steer from side to side"],"h1":"Less speed means more control.","h2":"In Virginia, if your trailer starts to sway, slow down.","p":"Right. Slow down when a trailer sways."},"es":{"q":"En Virginia, el remolque que usted jala empieza a balancearse. ¿Qué debe hacer?","o":["Bajar la velocidad","Acelerar","Frenar fuerte y girar bruscamente","Mover el volante de lado a lado"],"h1":"Menos velocidad significa más control.","h2":"En Virginia, si su remolque empieza a balancearse, baje la velocidad.","p":"Correcto. Baje la velocidad cuando el remolque se balancea."},"ref":{"doc":"VA","page":21}},{"id":"va-142","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, you are backing up with a trailer and want the trailer to go left. With your hand at the bottom of the wheel, what do you do?","o":["Move the wheel to the right","Hold the wheel still","Use only the top of the wheel","Move your hand and the wheel to the left"],"h1":"With your hand at the bottom, the trailer follows your hand.","h2":"In Virginia, when backing a trailer, place a hand on the bottom of the steering wheel; to back the trailer to the left, move the wheel to the left.","p":"Right. Hand at the bottom, move left to go left."},"es":{"q":"En Virginia, usted va en reversa con un remolque y quiere que el remolque vaya a la izquierda. Con la mano en la parte de abajo del volante, ¿qué hace?","o":["Mover el volante a la derecha","Dejar el volante quieto","Usar solo la parte de arriba del volante","Mover la mano y el volante a la izquierda"],"h1":"Con la mano abajo, el remolque sigue a su mano.","h2":"En Virginia, al ir en reversa con un remolque, ponga una mano en la parte de abajo del volante; para llevar el remolque a la izquierda, mueva el volante a la izquierda.","p":"Correcto. Mano abajo, mueva a la izquierda para ir a la izquierda."},"ref":{"doc":"VA","page":21}},{"id":"va-143","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, you check your tires with the penny test, putting Lincoln's head into a groove. What shows a safe amount of tread?","o":["You can see all of Lincoln's head","The penny falls out","The penny turns green","Part of Lincoln's head is covered by the tread"],"h1":"The tread should hide some of the head.","h2":"In Virginia, if any part of Lincoln's head is covered by the tread, you have a safe amount of tread.","p":"Right. Some of the head should be covered."},"es":{"q":"En Virginia, usted revisa sus llantas con la prueba del centavo, metiendo la cabeza de Lincoln en una ranura. ¿Qué muestra que el dibujo es suficiente?","o":["Se ve toda la cabeza de Lincoln","El centavo se cae","El centavo se pone verde","El dibujo de la llanta tapa parte de la cabeza de Lincoln"],"h1":"El dibujo debe tapar algo de la cabeza.","h2":"En Virginia, si el dibujo de la llanta tapa cualquier parte de la cabeza de Lincoln, la llanta tiene suficiente dibujo.","p":"Correcto. Debe quedar tapada parte de la cabeza."},"ref":{"doc":"VA","page":34}},{"id":"va-144","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, what is the most common mistake drivers make when backing up?","o":["Backing too slowly","Using the parking brake","Not looking both ways behind them","Turning on the headlights"],"h1":"Mirrors do not show everything.","h2":"In Virginia, the most common backing mistake is failing to look both ways behind the car.","p":"Right. Look both ways behind you."},"es":{"q":"En Virginia, ¿cuál es el error más común de los conductores al ir en reversa?","o":["Ir demasiado despacio","Usar el freno de mano","No mirar a ambos lados detrás del carro","Encender las luces delanteras"],"h1":"Los espejos no muestran todo.","h2":"En Virginia, el error más común al ir en reversa es no mirar a ambos lados detrás del carro.","p":"Correcto. Mire a ambos lados detrás de usted."},"ref":{"doc":"VA","page":22}},{"id":"va-145","scope":"VA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Virginia, you park on a two-way street. On which side of the road must you park?","o":["The right side","The left side","Either side","In the middle"],"h1":"Park facing the same way as traffic in your lane.","h2":"In Virginia, on a two-way street you must park on the right side; on a one-way street you may park on either side.","p":"Right. Park on the right side of a two-way street."},"es":{"q":"En Virginia, usted se estaciona en una calle de doble sentido. ¿En qué lado de la calle debe estacionarse?","o":["En el lado derecho","En el lado izquierdo","En cualquier lado","En el medio"],"h1":"Estaciónese mirando en el mismo sentido que el tránsito de su carril.","h2":"En Virginia, en una calle de doble sentido debe estacionarse en el lado derecho; en una calle de un solo sentido puede estacionarse en cualquier lado.","p":"Correcto. A la derecha en una calle de doble sentido."},"ref":{"doc":"VA","page":22}},{"id":"va-146","scope":"VA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Virginia, how close may you park to the entrance of a fire, ambulance or rescue squad station?","o":["5 feet","10 feet","Right next to it","No closer than 15 feet"],"h1":"It is the same as for a fire hydrant.","h2":"In Virginia, you may not park within 15 feet of the entrance to a fire, ambulance or rescue squad station.","p":"Right. Stay 15 feet away."},"es":{"q":"En Virginia, ¿qué tan cerca de la entrada de una estación de bomberos, ambulancias o rescate puede estacionarse?","o":["5 pies","10 pies","Justo al lado","No más cerca de 15 pies"],"h1":"Es lo mismo que para un hidrante.","h2":"En Virginia, no puede estacionarse a menos de 15 pies de la entrada de una estación de bomberos, ambulancias o rescate.","p":"Correcto. Manténgase a 15 pies."},"ref":{"doc":"VA","page":22}},{"id":"va-147","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, a car's horn must be loud enough to be heard from at least how far away?","o":["20 feet","200 feet","2,000 feet","1 mile"],"h1":"It is a couple hundred feet.","h2":"In Virginia, every motor vehicle must have a working horn that can be heard for at least 200 feet.","p":"Right. At least 200 feet."},"es":{"q":"En Virginia, ¿desde por lo menos qué distancia se debe poder oír la bocina de un carro?","o":["20 pies","200 pies","2,000 pies","1 milla"],"h1":"Son un par de cientos de pies.","h2":"En Virginia, todo vehículo motorizado debe tener una bocina que funcione y que se pueda oír por lo menos a 200 pies.","p":"Correcto. Por lo menos 200 pies."},"ref":{"doc":"VA","page":null}},{"id":"va-148","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, rain or fog cuts how far you can see. At what visibility must your headlights be on?","o":["50 feet","100 feet","500 feet","1 mile"],"h1":"It is the same distance used for dimming high beams for oncoming cars.","h2":"In Virginia, you must use headlights in bad weather such as rain, fog, snow or sleet when visibility is reduced to 500 feet.","p":"Right. Lights on when you can see only 500 feet."},"es":{"q":"En Virginia, la lluvia o la neblina reducen lo que usted puede ver. ¿Con qué visibilidad debe tener las luces encendidas?","o":["50 pies","100 pies","500 pies","1 milla"],"h1":"Es la misma distancia que se usa para bajar las luces altas ante carros de frente.","h2":"En Virginia, debe usar las luces delanteras con mal tiempo, como lluvia, neblina, nieve o aguanieve, cuando la visibilidad baja a 500 pies.","p":"Correcto. Luces encendidas cuando solo se ve a 500 pies."},"ref":{"doc":"VA","page":22}},{"id":"va-149","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, the street is lit well enough to see people and objects 350 feet ahead. Which headlights must you use?","o":["Low beams","High beams","No headlights","Fog lights only"],"h1":"Bright lights are not needed here.","h2":"In Virginia, on a road lit well enough to see people and objects 350 feet ahead, you must use low beams.","p":"Right. Low beams on well-lit roads."},"es":{"q":"En Virginia, la calle tiene suficiente alumbrado para ver personas y objetos a 350 pies. ¿Qué luces debe usar?","o":["Luces bajas","Luces altas","Ninguna luz","Solo las luces de neblina"],"h1":"Aquí no se necesitan luces fuertes.","h2":"En Virginia, en una vía con suficiente alumbrado para ver personas y objetos a 350 pies, debe usar las luces bajas.","p":"Correcto. Luces bajas en vías bien iluminadas."},"ref":{"doc":"VA","page":null}},{"id":"va-150","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, the law defines aggressive driving as committing a traffic offense with what intent?","o":["To arrive on time","To save fuel","To keep up with traffic","To harass, intimidate, injure or obstruct another person"],"h1":"It is about targeting someone else.","h2":"In Virginia, aggressive driving means committing traffic offenses with the intent to harass, intimidate, injure or obstruct another person.","p":"Right. Aggressive driving targets another person."},"es":{"q":"En Virginia, la ley define el manejo agresivo como cometer una infracción de tránsito, ¿con qué intención?","o":["Llegar a tiempo","Ahorrar gasolina","Seguir el ritmo del tránsito","Acosar, intimidar, herir u obstaculizar a otra persona"],"h1":"Se trata de ir contra otra persona.","h2":"En Virginia, el manejo agresivo significa cometer infracciones de tránsito con la intención de acosar, intimidar, herir u obstaculizar a otra persona.","p":"Correcto. El manejo agresivo va contra otra persona."},"ref":{"doc":"VA","page":23}},{"id":"va-151","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, on a long trip, how often does the manual say to stop for rest?","o":["Every six hours","At least every two hours","Only when you run out of gas","Once a day"],"h1":"It is a short time.","h2":"In Virginia, to avoid drowsy driving on long trips, stop at least every two hours for rest.","p":"Right. Rest at least every two hours."},"es":{"q":"En Virginia, en un viaje largo, ¿cada cuánto dice el manual que debe parar a descansar?","o":["Cada seis horas","Por lo menos cada dos horas","Solo cuando se acabe la gasolina","Una vez al día"],"h1":"Es poco tiempo.","h2":"En Virginia, para evitar manejar con sueño en viajes largos, pare a descansar por lo menos cada dos horas.","p":"Correcto. Descanse por lo menos cada dos horas."},"ref":{"doc":"VA","page":24}},{"id":"va-152","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, window tint on the front side windows must let in at least how much light?","o":["10 percent","35 percent","50 percent","90 percent"],"h1":"It is half.","h2":"In Virginia, tint on the front side windows must let through at least 50 percent of the light.","p":"Right. At least 50 percent."},"es":{"q":"En Virginia, ¿cuánta luz, como mínimo, debe dejar pasar el polarizado de las ventanas laterales delanteras?","o":["10 por ciento","35 por ciento","50 por ciento","90 por ciento"],"h1":"Es la mitad.","h2":"En Virginia, el polarizado de las ventanas laterales delanteras debe dejar pasar por lo menos el 50 por ciento de la luz.","p":"Correcto. Por lo menos el 50 por ciento."},"ref":{"doc":"VA","page":null}},{"id":"va-153","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, tint on a sedan's rear side windows and rear window must let in at least how much light?","o":["35 percent","5 percent","70 percent","100 percent"],"h1":"It may be darker than in front.","h2":"In Virginia, tint on a car's rear side windows and rear window must let through at least 35 percent of the light; pickups and SUVs are exempt.","p":"Right. At least 35 percent."},"es":{"q":"En Virginia, ¿cuánta luz, como mínimo, debe dejar pasar el polarizado de las ventanas laterales traseras y la ventana trasera de un sedán?","o":["35 por ciento","5 por ciento","70 por ciento","100 por ciento"],"h1":"Puede ser más oscuro que adelante.","h2":"En Virginia, el polarizado de las ventanas laterales traseras y la ventana trasera de un carro debe dejar pasar por lo menos el 35 por ciento de la luz; las pickups y los SUV están exentos.","p":"Correcto. Por lo menos el 35 por ciento."},"ref":{"doc":"VA","page":null}},{"id":"va-154","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver is convicted of a first DUI. For how long does the conviction take away the privilege to drive?","o":["One week","30 days","Five years","One year"],"h1":"It is twelve months.","h2":"In Virginia, a first DUI conviction takes away the privilege to drive for one year, in addition to the administrative suspension.","p":"Right. One year."},"es":{"q":"En Virginia, un conductor es condenado por un primer DUI. ¿Por cuánto tiempo pierde el privilegio de manejar por la condena?","o":["Una semana","30 días","Cinco años","Un año"],"h1":"Son doce meses.","h2":"En Virginia, una condena por un primer DUI quita el privilegio de manejar por un año, además de la suspensión administrativa.","p":"Correcto. Un año."},"ref":{"doc":"VA","page":null}},{"id":"va-155","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, police must send a written crash report to DMV when property damage is more than what amount?","o":["$500","$3,000","$10,000","$25,000"],"h1":"It is a few thousand dollars.","h2":"In Virginia, officers must send a written report to DMV when a crash causes injury or death, or more than $3,000 in property damage.","p":"Right. More than $3,000."},"es":{"q":"En Virginia, ¿de qué cantidad deben pasar los daños a la propiedad para que la policía envíe un reporte escrito del choque al DMV?","o":["$500","$3,000","$10,000","$25,000"],"h1":"Son unos miles de dólares.","h2":"En Virginia, los policías deben enviar un reporte escrito al DMV cuando un choque causa heridos o muertos, o más de $3,000 en daños a la propiedad.","p":"Correcto. Más de $3,000."},"ref":{"doc":"VA","page":25}},{"id":"va-156","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, where is information about a reported crash recorded?","o":["Only at the repair shop","Nowhere","On the DMV record of each driver involved","Only on the at-fault driver's record"],"h1":"Every driver in the crash is affected.","h2":"In Virginia, crash information is recorded on the DMV records of each driver involved in the crash.","p":"Right. It goes on every involved driver's record."},"es":{"q":"En Virginia, ¿dónde se registra la información de un choque reportado?","o":["Solo en el taller","En ningún lado","En el historial del DMV de cada conductor involucrado","Solo en el historial del conductor culpable"],"h1":"Afecta a todos los conductores del choque.","h2":"En Virginia, la información del choque se registra en el historial del DMV de cada conductor involucrado.","p":"Correcto. Va al historial de cada conductor involucrado."},"ref":{"doc":"VA","page":25}},{"id":"va-157","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, you hit a parked car and cannot find the owner. What must your note include?","o":["Your name, phone number, the date and time, and a description of the damage","Only your first name","Only your plate number","Only an apology"],"h1":"The owner must be able to reach you and know what happened.","h2":"In Virginia, the note must include your name, telephone number, the date and time of the crash, and a description of the damage.","p":"Right. Name, phone, date, time and the damage."},"es":{"q":"En Virginia, usted choca un carro estacionado y no encuentra al dueño. ¿Qué debe incluir su nota?","o":["Su nombre, número de teléfono, la fecha y hora, y una descripción del daño","Solo su primer nombre","Solo su número de placa","Solo una disculpa"],"h1":"El dueño debe poder comunicarse con usted y saber qué pasó.","h2":"En Virginia, la nota debe incluir su nombre, número de teléfono, la fecha y hora del choque, y una descripción del daño.","p":"Correcto. Nombre, teléfono, fecha, hora y el daño."},"ref":{"doc":"VA","page":25}},{"id":"va-158","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver leaves the scene of a crash in which someone was hurt. What crime is it?","o":["A traffic infraction","A Class 4 misdemeanor","No crime if they call later","A Class 5 felony"],"h1":"It is a felony.","h2":"In Virginia, leaving the scene of a crash with injury or death, or with more than $1,000 in property damage, is a Class 5 felony.","p":"Right. Hit and run with injury is a felony."},"es":{"q":"En Virginia, un conductor se va del lugar de un choque en el que alguien salió herido. ¿Qué delito es?","o":["Una infracción de tránsito","Un delito menor de Clase 4","Ningún delito si llama después","Un delito grave de Clase 5"],"h1":"Es un delito grave.","h2":"En Virginia, irse del lugar de un choque con heridos o muertos, o con más de $1,000 en daños a la propiedad, es un delito grave de Clase 5.","p":"Correcto. Huir de un choque con heridos es un delito grave."},"ref":{"doc":"VA","page":null}},{"id":"va-159","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, when should you be most alert for deer?","o":["At noon in summer","At dusk and dawn, especially in the fall","At midnight in spring","Only when it snows"],"h1":"Think of early morning and early evening.","h2":"In Virginia, be most alert for deer and other large animals at dusk and dawn, especially in the fall.","p":"Right. Dusk and dawn in the fall."},"es":{"q":"En Virginia, ¿cuándo debe estar más atento a los venados?","o":["Al mediodía en verano","Al anochecer y al amanecer, sobre todo en otoño","A medianoche en primavera","Solo cuando nieva"],"h1":"Piense en temprano en la mañana y al caer la tarde.","h2":"En Virginia, esté más atento a los venados y otros animales grandes al anochecer y al amanecer, sobre todo en otoño.","p":"Correcto. Al anochecer y al amanecer en otoño."},"ref":{"doc":"VA","page":25}},{"id":"va-160","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, a driver arrested for DUI unreasonably refuses a breath test for the first time. What must the court do?","o":["Nothing","Suspend the license for one year","Give a warning","Suspend it for one day"],"h1":"It is a full year.","h2":"In Virginia, a first unreasonable refusal of a breath or blood test is a civil offense, and the court suspends the driving privilege for one year.","p":"Right. One year."},"es":{"q":"En Virginia, un conductor arrestado por DUI se niega sin razón a una prueba de aliento por primera vez. ¿Qué debe hacer el tribunal?","o":["Nada","Suspender la licencia por un año","Dar una advertencia","Suspenderla por un día"],"h1":"Es un año completo.","h2":"En Virginia, una primera negativa sin razón a una prueba de aliento o de sangre es una falta civil, y el tribunal suspende el privilegio de manejar por un año.","p":"Correcto. Un año."},"ref":{"doc":"VA","page":null}},{"id":"va-161","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, you hit a deer with your car. Whom should you report it to?","o":["Law enforcement","Nobody","A hunting club","Your neighbor"],"h1":"The same people you call for a crash.","h2":"In Virginia, if you hit a large animal, report it to law enforcement.","p":"Right. Report it to the police."},"es":{"q":"En Virginia, usted atropella un venado con su carro. ¿A quién debe reportarlo?","o":["A la policía","A nadie","A un club de caza","A su vecino"],"h1":"A los mismos que llama por un choque.","h2":"En Virginia, si choca con un animal grande, repórtelo a la policía.","p":"Correcto. Repórtelo a la policía."},"ref":{"doc":"VA","page":25}},{"id":"va-162","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a police officer pulls you over at night. What should you turn on inside your car?","o":["The radio","The high beams","The air conditioning","The interior lights"],"h1":"Help the officer see you.","h2":"In Virginia, if you are stopped at night, turn on your interior lights, and keep your hands in plain view.","p":"Right. Turn on the interior lights."},"es":{"q":"En Virginia, un policía lo detiene de noche. ¿Qué debe encender dentro de su carro?","o":["El radio","Las luces altas","El aire acondicionado","Las luces interiores"],"h1":"Ayude al policía a verlo.","h2":"En Virginia, si lo detienen de noche, encienda las luces interiores y mantenga las manos a la vista.","p":"Correcto. Encienda las luces interiores."},"ref":{"doc":"VA","page":26}},{"id":"va-163","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, an officer asks you to sign a traffic ticket. What does signing mean?","o":["You admit you are guilty","It is not an admission of guilt; refusing can lead to arrest","You give up your right to go to court","You agree to pay double"],"h1":"You can still argue your case in court.","h2":"In Virginia, signing a citation is not an admission of guilt, and refusing to sign may result in arrest.","p":"Right. Signing is not admitting guilt."},"es":{"q":"En Virginia, un policía le pide que firme una multa de tránsito. ¿Qué significa firmar?","o":["Que admite que es culpable","No es admitir culpa; negarse puede llevar a un arresto","Que renuncia a su derecho a ir al tribunal","Que acepta pagar el doble"],"h1":"Igual puede defender su caso en el tribunal.","h2":"En Virginia, firmar una citación no es admitir culpa, y negarse a firmar puede llevar a un arresto.","p":"Correcto. Firmar no es admitir culpa."},"ref":{"doc":"VA","page":26}},{"id":"va-164","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, a driver is convicted of a third DUI within 10 years. What kind of crime is it?","o":["A traffic infraction","A Class 3 misdemeanor","A Class 6 felony","A civil offense"],"h1":"It is a felony.","h2":"In Virginia, a third DUI within 10 years is a Class 6 felony, with mandatory jail time and a fine of at least $1,000.","p":"Right. A third DUI in 10 years is a felony."},"es":{"q":"En Virginia, un conductor es condenado por un tercer DUI en 10 años. ¿Qué tipo de delito es?","o":["Una infracción de tránsito","Un delito menor de Clase 3","Un delito grave de Clase 6","Una falta civil"],"h1":"Es un delito grave.","h2":"En Virginia, un tercer DUI en 10 años es un delito grave de Clase 6, con cárcel obligatoria y una multa de por lo menos $1,000.","p":"Correcto. Un tercer DUI en 10 años es un delito grave."},"ref":{"doc":"VA","page":null}},{"id":"va-165","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, a 30-year-old rides in the back seat. Must they wear a seat belt?","o":["Yes, all passengers, front and rear, must buckle up","No, only front-seat riders","Only on interstates","Only riders under 18"],"h1":"The law covers every seat.","h2":"In Virginia, the driver and all passengers, in both front and rear seats, must wear seat belts.","p":"Right. Everyone buckles up, front and back."},"es":{"q":"En Virginia, una persona de 30 años va en el asiento de atrás. ¿Debe usar el cinturón de seguridad?","o":["Sí, todos los pasajeros, adelante y atrás, deben abrocharse","No, solo los de adelante","Solo en las autopistas interestatales","Solo los menores de 18 años"],"h1":"La ley cubre todos los asientos.","h2":"En Virginia, el conductor y todos los pasajeros, tanto en los asientos de adelante como en los de atrás, deben usar el cinturón de seguridad.","p":"Correcto. Todos se abrochan, adelante y atrás."},"ref":{"doc":"VA","page":26}},{"id":"va-166","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, what is the civil penalty for an adult who does not wear a seat belt?","o":["$250 and 3 points","$100 and 1 point","$500","$25, with no demerit points"],"h1":"It is a small fine.","h2":"In Virginia, the penalty for an adult seat belt violation is $25, with no demerit points and no court costs.","p":"Right. $25 and no points."},"es":{"q":"En Virginia, ¿cuál es la multa civil para un adulto que no usa el cinturón de seguridad?","o":["$250 y 3 puntos","$100 y 1 punto","$500","$25, sin puntos de demérito"],"h1":"Es una multa pequeña.","h2":"En Virginia, la multa para un adulto que no usa el cinturón es de $25, sin puntos de demérito y sin costos judiciales.","p":"Correcto. $25 y sin puntos."},"ref":{"doc":"VA","page":null}},{"id":"va-167","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, may police stop a car only because an adult in it is not wearing a seat belt?","o":["Yes, at any time","No, that alone is not a reason to stop the car","Only at night","Only on highways"],"h1":"It is a secondary rule.","h2":"In Virginia, an officer may not stop a vehicle only because an adult is not wearing a seat belt.","p":"Right. An unbuckled adult alone is not a reason to stop a car."},"es":{"q":"En Virginia, ¿puede la policía detener un carro solo porque un adulto no usa el cinturón de seguridad?","o":["Sí, en cualquier momento","No, eso solo no es razón para detener el carro","Solo de noche","Solo en carreteras"],"h1":"Es una regla secundaria.","h2":"En Virginia, un policía no puede detener un vehículo solo porque un adulto no usa el cinturón de seguridad.","p":"Correcto. Un adulto sin cinturón no es por sí solo razón para detener un carro."},"ref":{"doc":"VA","page":null}},{"id":"va-168","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, you are driving a 15-year-old friend. Who is responsible for making sure the friend is buckled up?","o":["The friend","The friend's parent","You, the driver","No one"],"h1":"The person behind the wheel.","h2":"In Virginia, a driver carrying anyone younger than 18 must make sure that person is properly secured in a seat belt, booster seat or child safety seat.","p":"Right. The driver is responsible for riders under 18."},"es":{"q":"En Virginia, usted lleva en su carro a un amigo de 15 años. ¿Quién es responsable de que el amigo use el cinturón?","o":["El amigo","El padre o la madre del amigo","Usted, el conductor","Nadie"],"h1":"La persona que va al volante.","h2":"En Virginia, un conductor que lleva a cualquier menor de 18 años debe asegurarse de que use correctamente el cinturón, un asiento elevador o un asiento de seguridad para niños.","p":"Correcto. El conductor es responsable de los pasajeros menores de 18 años."},"ref":{"doc":"VA","page":26}},{"id":"va-169","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, a doctor says a passenger cannot safely wear a seat belt. What must the passenger carry?","o":["The doctor's signed written statement","Nothing","A DMV sticker","A police permit"],"h1":"It is a paper from the doctor.","h2":"In Virginia, a person with a doctor's seat belt waiver must carry the physician's signed written statement giving the reason.","p":"Right. Carry the signed doctor's statement."},"es":{"q":"En Virginia, un médico dice que un pasajero no puede usar el cinturón de seguridad sin riesgo. ¿Qué debe llevar el pasajero?","o":["La declaración escrita y firmada del médico","Nada","Una calcomanía del DMV","Un permiso de la policía"],"h1":"Es un papel del médico.","h2":"En Virginia, una persona con una exención médica del cinturón debe llevar la declaración escrita y firmada del médico con el motivo.","p":"Correcto. Lleve la declaración firmada del médico."},"ref":{"doc":"VA","page":26}},{"id":"va-170","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, if your car has air bags, how far should you sit from the steering wheel?","o":["2 inches","As close as possible","5 inches","At least 10 inches"],"h1":"It is about the length of a pencil.","h2":"In Virginia, move your seat back so you are at least 10 inches from the steering wheel.","p":"Right. At least 10 inches."},"es":{"q":"En Virginia, si su carro tiene bolsas de aire, ¿a qué distancia del volante debe sentarse?","o":["2 pulgadas","Lo más cerca posible","5 pulgadas","Por lo menos 10 pulgadas"],"h1":"Es más o menos el largo de un lápiz.","h2":"En Virginia, mueva su asiento hacia atrás para quedar por lo menos a 10 pulgadas del volante.","p":"Correcto. Por lo menos 10 pulgadas."},"ref":{"doc":"VA","page":27}},{"id":"va-171","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, children up to what age are safer buckled up in the back seat?","o":["5 and under only","12 and under","16 and under","Only babies"],"h1":"Think of preteens.","h2":"In Virginia, children ages 12 and under are safer buckled up in the back seat.","p":"Right. 12 and under ride in back."},"es":{"q":"En Virginia, ¿hasta qué edad los niños van más seguros abrochados en el asiento de atrás?","o":["Solo hasta los 5 años","Hasta los 12 años","Hasta los 16 años","Solo los bebés"],"h1":"Piense en preadolescentes.","h2":"En Virginia, los niños de 12 años o menos van más seguros abrochados en el asiento de atrás.","p":"Correcto. Hasta los 12 años van atrás."},"ref":{"doc":"VA","page":27}},{"id":"va-172","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, until what age should a child ride rear-facing, or as long as the seat maker allows?","o":["6 months","1 year","2 years","5 years"],"h1":"It is the second birthday.","h2":"In Virginia, children should ride rear-facing from birth to 2 years, or as long as the safety seat manufacturer allows.","p":"Right. Rear-facing until age 2."},"es":{"q":"En Virginia, ¿hasta qué edad debe un niño ir mirando hacia atrás, o mientras el fabricante del asiento lo permita?","o":["6 meses","1 año","2 años","5 años"],"h1":"Es el segundo cumpleaños.","h2":"En Virginia, los niños deben ir mirando hacia atrás desde que nacen hasta los 2 años, o mientras el fabricante del asiento lo permita.","p":"Correcto. Mirando hacia atrás hasta los 2 años."},"ref":{"doc":"VA","page":27}},{"id":"va-173","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, where is the safest place to install a child safety seat?","o":["The center of the back seat","The front passenger seat","In the cargo area","Behind the driver, without a belt"],"h1":"It is the spot farthest from all the doors.","h2":"In Virginia, the safest place for a child safety seat is the center of the back seat.","p":"Right. The center of the back seat."},"es":{"q":"En Virginia, ¿cuál es el lugar más seguro para instalar un asiento de seguridad para niños?","o":["El centro del asiento de atrás","El asiento del pasajero de adelante","El área de carga","Detrás del conductor, sin cinturón"],"h1":"Es el lugar más lejos de todas las puertas.","h2":"En Virginia, el lugar más seguro para un asiento de seguridad para niños es el centro del asiento de atrás.","p":"Correcto. El centro del asiento de atrás."},"ref":{"doc":"VA","page":27}},{"id":"va-174","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver is convicted for the first time of not properly securing a child. What is the fine?","o":["$5","$1,000","No fine","$50"],"h1":"It can go up to $500 for a second offense.","h2":"In Virginia, a first child restraint violation brings a $50 fine, and a second or later one can mean up to $500.","p":"Right. $50 for a first offense."},"es":{"q":"En Virginia, un conductor es condenado por primera vez por no asegurar bien a un niño. ¿Cuál es la multa?","o":["$5","$1,000","Ninguna multa","$50"],"h1":"Puede llegar a $500 por una segunda vez.","h2":"En Virginia, una primera infracción de asientos para niños tiene una multa de $50, y una segunda o más puede llegar a $500.","p":"Correcto. $50 la primera vez."},"ref":{"doc":"VA","page":27}},{"id":"va-175","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, which is one sign that a child can use a seat belt without a booster seat?","o":["The child is 5 years old","The child's knees bend naturally over the edge of the seat","The child sits in the front seat","The shoulder belt crosses the child's neck"],"h1":"Check how the child sits on the seat.","h2":"In Virginia, a child may ride without a booster when the lap belt fits the upper thighs, the shoulder belt fits the shoulder and chest, the knees bend over the seat edge and the feet are flat on the floor.","p":"Right. Knees bending over the edge is one of the signs."},"es":{"q":"En Virginia, ¿cuál es una señal de que un niño puede usar el cinturón sin asiento elevador?","o":["El niño tiene 5 años","Las rodillas del niño se doblan naturalmente sobre el borde del asiento","El niño va en el asiento de adelante","El cinturón del hombro le cruza el cuello"],"h1":"Fíjese en cómo se sienta el niño.","h2":"En Virginia, un niño puede ir sin asiento elevador cuando el cinturón de la cintura le queda sobre la parte alta de los muslos, el del hombro sobre el hombro y el pecho, las rodillas se doblan sobre el borde del asiento y los pies quedan planos en el piso.","p":"Correcto. Que las rodillas se doblen sobre el borde es una de las señales."},"ref":{"doc":"VA","page":27}},{"id":"va-176","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, how long do demerit points stay valid after the offense?","o":["Six months","One year","Two years","Ten years"],"h1":"It is more than one year.","h2":"In Virginia, demerit points remain valid for two years from the date you commit the offense.","p":"Right. Two years."},"es":{"q":"En Virginia, ¿por cuánto tiempo siguen vigentes los puntos de demérito después de la infracción?","o":["Seis meses","Un año","Dos años","Diez años"],"h1":"Es más de un año.","h2":"En Virginia, los puntos de demérito siguen vigentes por dos años desde la fecha en que comete la infracción.","p":"Correcto. Dos años."},"ref":{"doc":"VA","page":null}},{"id":"va-177","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, how do drivers earn safe driving points on their own?","o":["One point for each full calendar year with no violations or suspensions","One point for each month","By driving more miles","By paying a fee"],"h1":"It comes once a year.","h2":"In Virginia, you earn one safe driving point for each full calendar year with a valid license and no violations or suspensions, up to five points.","p":"Right. One point per clean year, up to five."},"es":{"q":"En Virginia, ¿cómo ganan los conductores puntos de manejo seguro por su cuenta?","o":["Un punto por cada año calendario completo sin infracciones ni suspensiones","Un punto por cada mes","Manejando más millas","Pagando una tarifa"],"h1":"Llega una vez al año.","h2":"En Virginia, usted gana un punto de manejo seguro por cada año calendario completo con licencia válida y sin infracciones ni suspensiones, hasta cinco puntos.","p":"Correcto. Un punto por año limpio, hasta cinco."},"ref":{"doc":"VA","page":null}},{"id":"va-178","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, a driver chooses on their own to complete a driver improvement clinic. How many safe driving points can they get?","o":["1","10","20","5"],"h1":"It is the most a driver can hold.","h2":"In Virginia, completing a driver improvement clinic can earn 5 safe driving points, once every 24 months, and 5 is the highest balance allowed.","p":"Right. Five safe driving points."},"es":{"q":"En Virginia, un conductor decide por su cuenta completar una clínica de mejoramiento para conductores. ¿Cuántos puntos de manejo seguro puede ganar?","o":["1","10","20","5"],"h1":"Es lo máximo que un conductor puede tener.","h2":"En Virginia, completar una clínica de mejoramiento puede dar 5 puntos de manejo seguro, una vez cada 24 meses, y 5 es el saldo máximo permitido.","p":"Correcto. Cinco puntos de manejo seguro."},"ref":{"doc":"VA","page":null}},{"id":"va-179","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, a driver age 30 gets 8 demerit points in 12 months. What happens?","o":["The license is suspended for one year","DMV sends an advisory letter","Nothing at all","A new road test is required"],"h1":"It is a warning.","h2":"In Virginia, a driver 18 or older with 8 demerit points in 12 months, or 12 points in 24 months, gets an advisory letter from DMV.","p":"Right. An advisory letter warns the driver."},"es":{"q":"En Virginia, un conductor de 30 años acumula 8 puntos de demérito en 12 meses. ¿Qué pasa?","o":["Le suspenden la licencia por un año","El DMV le envía una carta de advertencia","Nada","Le exigen un nuevo examen de manejo"],"h1":"Es una advertencia.","h2":"En Virginia, un conductor de 18 años o más con 8 puntos de demérito en 12 meses, o 12 puntos en 24 meses, recibe una carta de advertencia del DMV.","p":"Correcto. Una carta de advertencia le avisa al conductor."},"ref":{"doc":"VA","page":null}},{"id":"va-180","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a driver age 18 or older gets 18 demerit points in 12 months. What does DMV do?","o":["Sends a letter only","Requires a vision test","Suspends the license for 90 days and requires a clinic","Takes the car away"],"h1":"It is a three-month suspension plus a class.","h2":"In Virginia, 18 demerit points in 12 months, or 24 points in 24 months, leads to a 90-day suspension and a required driver improvement clinic.","p":"Right. A 90-day suspension and a clinic."},"es":{"q":"En Virginia, un conductor de 18 años o más acumula 18 puntos de demérito en 12 meses. ¿Qué hace el DMV?","o":["Solo envía una carta","Exige una prueba de la vista","Suspende la licencia por 90 días y exige una clínica","Le quita el carro"],"h1":"Es una suspensión de tres meses más una clase.","h2":"En Virginia, 18 puntos de demérito en 12 meses, o 24 puntos en 24 meses, llevan a una suspensión de 90 días y a una clínica de mejoramiento obligatoria.","p":"Correcto. Una suspensión de 90 días y una clínica."},"ref":{"doc":"VA","page":29}},{"id":"va-181","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, DMV orders you to attend a driver improvement clinic. How long do you have to finish it?","o":["90 days","One week","One year","Five years"],"h1":"It is about three months.","h2":"In Virginia, you must complete a required driver improvement clinic within 90 days, or DMV will suspend your driving privilege.","p":"Right. Within 90 days."},"es":{"q":"En Virginia, el DMV le ordena asistir a una clínica de mejoramiento para conductores. ¿Cuánto tiempo tiene para terminarla?","o":["90 días","Una semana","Un año","Cinco años"],"h1":"Son unos tres meses.","h2":"En Virginia, debe completar una clínica de mejoramiento obligatoria en un plazo de 90 días, o el DMV suspenderá su privilegio de manejar.","p":"Correcto. En 90 días."},"ref":{"doc":"VA","page":29}},{"id":"va-182","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, what is the youngest age to drive a moped on a highway?","o":["12","14","15","16"],"h1":"It is the age when many teens start driving.","h2":"In Virginia, no one under 16 may drive a moped on a highway, and moped riders must carry a government photo ID.","p":"Right. 16."},"es":{"q":"En Virginia, ¿cuál es la edad mínima para manejar una motoneta (moped) en una carretera?","o":["12","14","15","16"],"h1":"Es la edad en que muchos adolescentes empiezan a manejar.","h2":"En Virginia, nadie menor de 16 años puede manejar una motoneta en una carretera, y quienes la manejan deben llevar una identificación oficial con foto.","p":"Correcto. 16 años."},"ref":{"doc":"VA","page":null}},{"id":"va-183","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, a 17-year-old is convicted of a second demerit point violation committed under 18. What does DMV do?","o":["Sends a warning letter","Suspends the license for 90 days","Revokes it until age 25","Nothing"],"h1":"It is about three months.","h2":"In Virginia, a second demerit point (or seat belt) conviction for a violation committed under 18 brings a 90-day suspension.","p":"Right. 90 days."},"es":{"q":"En Virginia, un joven de 17 años es condenado por una segunda infracción con puntos de demérito cometida antes de los 18. ¿Qué hace el DMV?","o":["Envía una carta de advertencia","Suspende la licencia por 90 días","La revoca hasta los 25 años","Nada"],"h1":"Son unos tres meses.","h2":"En Virginia, una segunda condena por una infracción con puntos de demérito (o de cinturón) cometida antes de los 18 años trae una suspensión de 90 días.","p":"Correcto. 90 días."},"ref":{"doc":"VA","page":29}},{"id":"va-184","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, a driver gets a third demerit point conviction for a violation committed under age 18. What happens?","o":["A $50 fine","A 30-day suspension","Revocation for one year or until age 18, whichever is longer","An advisory letter"],"h1":"It lasts at least a year.","h2":"In Virginia, a third such conviction leads to revocation of the license for one year or until age 18, whichever is longer.","p":"Right. One year or until 18, whichever is longer."},"es":{"q":"En Virginia, un conductor recibe una tercera condena con puntos de demérito por una infracción cometida antes de los 18 años. ¿Qué pasa?","o":["Una multa de $50","Una suspensión de 30 días","La revocación por un año o hasta los 18 años, lo que sea más largo","Una carta de advertencia"],"h1":"Dura por lo menos un año.","h2":"En Virginia, una tercera condena de este tipo lleva a la revocación de la licencia por un año o hasta los 18 años, lo que sea más largo.","p":"Correcto. Un año o hasta los 18, lo que sea más largo."},"ref":{"doc":"VA","page":29}},{"id":"va-185","scope":"VA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Virginia, a 19-year-old is convicted of one demerit point violation. What does DMV require?","o":["A driver improvement clinic","Nothing","A 90-day suspension","A new learner's permit"],"h1":"It is a class.","h2":"In Virginia, a driver convicted of a demerit point or seat belt violation committed at age 18 or 19 must complete a driver improvement clinic.","p":"Right. Even one violation at 18 or 19 means a clinic."},"es":{"q":"En Virginia, un joven de 19 años es condenado por una infracción con puntos de demérito. ¿Qué exige el DMV?","o":["Una clínica de mejoramiento para conductores","Nada","Una suspensión de 90 días","Un nuevo permiso de aprendiz"],"h1":"Es una clase.","h2":"En Virginia, un conductor condenado por una infracción con puntos de demérito o de cinturón cometida a los 18 o 19 años debe completar una clínica de mejoramiento para conductores.","p":"Correcto. Incluso una infracción a los 18 o 19 significa una clínica."},"ref":{"doc":"VA","page":29}},{"id":"va-186","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, how many demerit points is speeding 1 to 9 mph over the limit?","o":["6","4","1","3"],"h1":"It is the lowest level.","h2":"In Virginia, speeding 1 to 9 mph over the posted limit is a 3-point violation.","p":"Right. Three points."},"es":{"q":"En Virginia, ¿cuántos puntos de demérito tiene ir de 1 a 9 mph sobre el límite?","o":["6","4","1","3"],"h1":"Es el nivel más bajo.","h2":"En Virginia, ir de 1 a 9 mph sobre el límite indicado es una infracción de 3 puntos.","p":"Correcto. Tres puntos."},"ref":{"doc":"VA","page":null}},{"id":"va-187","scope":"VA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Virginia, your car's safety inspection sticker has expired. When may police first stop you only for the expired sticker?","o":["The day after it expires","On the first day of the fourth month after it expires","After one full year","Never, inspections are optional"],"h1":"There is a grace period of a few months.","h2":"In Virginia, every registered car needs a yearly safety inspection, but police may not stop a car only for an expired sticker until the first day of the fourth month after it expired.","p":"Right. Not until the first day of the fourth month."},"es":{"q":"En Virginia, la calcomanía de inspección de seguridad de su carro está vencida. ¿Desde cuándo puede la policía detenerlo solo por la calcomanía vencida?","o":["Desde el día después de vencer","Desde el primer día del cuarto mes después de vencer","Después de un año completo","Nunca, las inspecciones son opcionales"],"h1":"Hay un periodo de gracia de unos meses.","h2":"En Virginia, todo carro registrado necesita una inspección de seguridad cada año, pero la policía no puede detener un carro solo por una calcomanía vencida hasta el primer día del cuarto mes después del vencimiento.","p":"Correcto. No antes del primer día del cuarto mes."},"ref":{"doc":"VA","page":null}},{"id":"va-188","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, how many demerit points does a conviction for holding a phone while driving carry?","o":["0","6","3","12"],"h1":"It is the lowest level.","h2":"In Virginia, using a handheld communications device while driving is a 3-point violation.","p":"Right. Three points."},"es":{"q":"En Virginia, ¿cuántos puntos de demérito tiene una condena por sostener el teléfono mientras maneja?","o":["0","6","3","12"],"h1":"Es el nivel más bajo.","h2":"En Virginia, usar un aparato de comunicación en la mano mientras maneja es una infracción de 3 puntos.","p":"Correcto. Tres puntos."},"ref":{"doc":"VA","page":null}},{"id":"va-189","scope":"VA","cat":"signals","sign":null,"c":0,"en":{"q":"In Virginia, a motorcycle rider is stopped at a red light that does not turn green. When may the rider go through?","o":["After a full stop for two light cycles or two minutes, whichever is shorter, when it is safe","Right away","Never","After 10 seconds"],"h1":"It takes some waiting, then treating it like a stop sign.","h2":"In Virginia, a motorcycle, moped or bicycle rider may go through a steady red light after stopping for two full cycles or two minutes, whichever is shorter, treating it like a stop sign and yielding.","p":"Right. Two cycles or two minutes, then go carefully."},"es":{"q":"En Virginia, un motociclista está detenido en un semáforo en rojo que no cambia a verde. ¿Cuándo puede pasar?","o":["Después de detenerse por completo durante dos ciclos del semáforo o dos minutos, lo que sea más corto, cuando sea seguro","De inmediato","Nunca","Después de 10 segundos"],"h1":"Hay que esperar un poco y luego tratarlo como un letrero de alto.","h2":"En Virginia, quien maneja una moto, una motoneta o una bicicleta puede pasar un semáforo en rojo fijo después de detenerse dos ciclos completos o dos minutos, lo que sea más corto, tratándolo como un letrero de alto y cediendo el paso.","p":"Correcto. Dos ciclos o dos minutos, y luego pase con cuidado."},"ref":{"doc":"VA","page":null}},{"id":"va-190","scope":"VA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Virginia, your insurance coverage stops. To avoid a suspension, what must you do?","o":["Pay a toll","Renew your license early","Take a road test","Return your license plates to DMV"],"h1":"Something on the car goes back to DMV.","h2":"In Virginia, DMV will suspend your driving privilege if there is a break in your insurance and you do not return your license plates to DMV.","p":"Right. Return the plates if coverage stops."},"es":{"q":"En Virginia, su seguro deja de tener cobertura. Para evitar una suspensión, ¿qué debe hacer?","o":["Pagar un peaje","Renovar su licencia antes","Tomar un examen de manejo","Devolver sus placas al DMV"],"h1":"Algo del carro regresa al DMV.","h2":"En Virginia, el DMV suspenderá su privilegio de manejar si hay una interrupción en su seguro y usted no devuelve las placas al DMV.","p":"Correcto. Devuelva las placas si se acaba la cobertura."},"ref":{"doc":"VA","page":30}},{"id":"va-191","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, after a crash, an officer with probable cause may arrest a driver for DUI without a warrant within how many hours?","o":["One hour","Three hours","24 hours","48 hours"],"h1":"It is a few hours.","h2":"In Virginia, after a crash, an officer with probable cause can arrest a driver for DUI within three hours of the crash, without a warrant and at any location.","p":"Right. Within three hours."},"es":{"q":"En Virginia, después de un choque, ¿dentro de cuántas horas puede un policía con causa probable arrestar a un conductor por DUI sin orden judicial?","o":["Una hora","Tres horas","24 horas","48 horas"],"h1":"Son unas pocas horas.","h2":"En Virginia, después de un choque, un policía con causa probable puede arrestar a un conductor por DUI dentro de las tres horas siguientes, sin orden judicial y en cualquier lugar.","p":"Correcto. Dentro de tres horas."},"ref":{"doc":"VA","page":30}},{"id":"va-192","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, a driver is charged with a second DUI after a breath test of 0.08 or more. How long is the automatic license suspension?","o":["Seven days","One day","60 days or until trial, whichever comes first","Five years"],"h1":"It is about two months.","h2":"In Virginia, for a second DUI offense, the automatic administrative suspension lasts 60 days or until the trial, whichever comes first.","p":"Right. 60 days or until trial."},"es":{"q":"En Virginia, a un conductor lo acusan de un segundo DUI después de una prueba de aliento de 0.08 o más. ¿Cuánto dura la suspensión automática de la licencia?","o":["Siete días","Un día","60 días o hasta el juicio, lo que ocurra primero","Cinco años"],"h1":"Son unos dos meses.","h2":"En Virginia, por un segundo DUI, la suspensión administrativa automática dura 60 días o hasta el juicio, lo que ocurra primero.","p":"Correcto. 60 días o hasta el juicio."},"ref":{"doc":"VA","page":30}},{"id":"va-193","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, an open container of alcohol counts as being in the passenger area if it is where?","o":["In an unlocked glove compartment","In the locked trunk","Sealed, in the trunk","Behind the last upright seat of an SUV"],"h1":"It is within the driver's reach.","h2":"In Virginia, the passenger area includes the seats and any area within the driver's reach, including an unlocked glove compartment, but not the trunk.","p":"Right. An unlocked glove box counts."},"es":{"q":"En Virginia, ¿dónde debe estar un envase abierto de alcohol para que cuente como que está en el área de pasajeros?","o":["En una guantera sin llave","En la cajuela cerrada con llave","Sellado, en la cajuela","Detrás del último asiento vertical de un SUV"],"h1":"Está al alcance del conductor.","h2":"En Virginia, el área de pasajeros incluye los asientos y cualquier lugar al alcance del conductor, incluida una guantera sin llave, pero no la cajuela.","p":"Correcto. Una guantera sin llave cuenta."},"ref":{"doc":"VA","page":30}},{"id":"va-194","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, a driver is convicted of a second DUI with a passenger age 17 or younger in the car. What extra requirement is added?","o":["A 5-hour class","A $10 fine","Nothing more","80 hours of community service"],"h1":"It is many hours of service.","h2":"In Virginia, a second DUI with a juvenile passenger in the vehicle adds 80 hours of community service to all other penalties.","p":"Right. 80 hours of community service."},"es":{"q":"En Virginia, un conductor es condenado por un segundo DUI con un pasajero de 17 años o menos en el carro. ¿Qué requisito extra se agrega?","o":["Una clase de 5 horas","Una multa de $10","Nada más","80 horas de servicio comunitario"],"h1":"Son muchas horas de servicio.","h2":"En Virginia, un segundo DUI con un pasajero menor de edad en el vehículo agrega 80 horas de servicio comunitario a todas las demás penas.","p":"Correcto. 80 horas de servicio comunitario."},"ref":{"doc":"VA","page":30}},{"id":"va-195","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, a driver is caught driving while the license is suspended for an alcohol-related offense. What happens to the car right away?","o":["Nothing","It is impounded for 30 days","It gets a warning sticker","It is booted for one hour"],"h1":"The driver loses the car for about a month.","h2":"In Virginia, the vehicle is impounded immediately for 30 days if you drive after your license was suspended for an alcohol-related offense.","p":"Right. It is impounded for 30 days."},"es":{"q":"En Virginia, a un conductor lo detienen manejando con la licencia suspendida por un delito relacionado con alcohol. ¿Qué le pasa al carro de inmediato?","o":["Nada","Lo incautan por 30 días","Le ponen una calcomanía de advertencia","Le ponen un cepo por una hora"],"h1":"El conductor se queda sin carro por casi un mes.","h2":"En Virginia, el vehículo se incauta de inmediato por 30 días si usted maneja después de que le suspendieron la licencia por un delito relacionado con alcohol.","p":"Correcto. Lo incautan por 30 días."},"ref":{"doc":"VA","page":30}},{"id":"va-196","scope":"VA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Virginia, your car fails the safety inspection and gets a rejection sticker. For how many days is the rejection sticker valid?","o":["One day","Three days","15 days","Six months"],"h1":"It is about two weeks.","h2":"In Virginia, a rejection sticker is valid for 15 days, giving you time to fix the problems and have the car checked again.","p":"Right. 15 days."},"es":{"q":"En Virginia, su carro no pasa la inspección de seguridad y le ponen una calcomanía de rechazo. ¿Por cuántos días es válida esa calcomanía?","o":["Un día","Tres días","15 días","Seis meses"],"h1":"Son unas dos semanas.","h2":"En Virginia, una calcomanía de rechazo es válida por 15 días, lo que le da tiempo para arreglar los problemas y volver a revisar el carro.","p":"Correcto. 15 días."},"ref":{"doc":"VA","page":null}},{"id":"va-197","scope":"VA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Virginia, a driver under 21 is convicted of driving after drinking, with a blood alcohol level from 0.02 to under 0.08. Besides losing the license, what penalty applies?","o":["A minimum $500 fine or at least 50 hours of community service","A $10 fine","A warning letter only","Six months in jail"],"h1":"It is either money or hours of service.","h2":"In Virginia, an under-21 driver convicted with a blood alcohol level from 0.02 to under 0.08 loses the license for one year and must pay at least $500 or do at least 50 hours of community service.","p":"Right. $500 or 50 hours of service."},"es":{"q":"En Virginia, un conductor menor de 21 años es condenado por manejar después de beber, con un nivel de alcohol en la sangre de 0.02 a menos de 0.08. Además de perder la licencia, ¿qué pena recibe?","o":["Una multa mínima de $500 o por lo menos 50 horas de servicio comunitario","Una multa de $10","Solo una carta de advertencia","Seis meses de cárcel"],"h1":"Es dinero u horas de servicio.","h2":"En Virginia, un conductor menor de 21 años condenado con un nivel de alcohol de 0.02 a menos de 0.08 pierde la licencia por un año y debe pagar por lo menos $500 o hacer por lo menos 50 horas de servicio comunitario.","p":"Correcto. $500 o 50 horas de servicio."},"ref":{"doc":"VA","page":30}},{"id":"va-198","scope":"VA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Virginia, an adult buys alcohol for a 19-year-old. What is the highest fine?","o":["$100","$500","$1,000","$2,500"],"h1":"It is a few thousand dollars.","h2":"In Virginia, giving or selling alcohol to someone under 21 can bring a fine of up to $2,500, up to 12 months in jail and a license suspension of up to one year.","p":"Right. Up to $2,500."},"es":{"q":"En Virginia, un adulto le compra alcohol a un joven de 19 años. ¿Cuál es la multa más alta?","o":["$100","$500","$1,000","$2,500"],"h1":"Son unos miles de dólares.","h2":"En Virginia, dar o vender alcohol a un menor de 21 años puede costar una multa de hasta $2,500, hasta 12 meses de cárcel y una suspensión de la licencia de hasta un año.","p":"Correcto. Hasta $2,500."},"ref":{"doc":"VA","page":31}},{"id":"va-199","scope":"VA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Virginia, a 19-year-old uses a fake ID to try to buy alcohol. How long is the license suspension?","o":["One week","Six months to one year","Five years","There is none"],"h1":"It is at least half a year.","h2":"In Virginia, a person under 21 who uses a fake ID to buy alcohol faces a fine of at least $500, at least 50 hours of community service, and a license suspension of six months to one year.","p":"Right. Six months to one year."},"es":{"q":"En Virginia, un joven de 19 años usa una identificación falsa para intentar comprar alcohol. ¿Cuánto dura la suspensión de la licencia?","o":["Una semana","De seis meses a un año","Cinco años","No hay suspensión"],"h1":"Es por lo menos medio año.","h2":"En Virginia, un menor de 21 años que usa una identificación falsa para comprar alcohol recibe una multa de por lo menos $500, por lo menos 50 horas de servicio comunitario y una suspensión de la licencia de seis meses a un año.","p":"Correcto. De seis meses a un año."},"ref":{"doc":"VA","page":31}},{"id":"va-200","scope":"VA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Virginia, what is the minimum fine for a first DUI conviction?","o":["$50","$100","$250","$5,000"],"h1":"It is a few hundred dollars.","h2":"In Virginia, a first DUI conviction is a Class 1 misdemeanor with a mandatory minimum fine of $250.","p":"Right. At least $250."},"es":{"q":"En Virginia, ¿cuál es la multa mínima por una primera condena de DUI?","o":["$50","$100","$250","$5,000"],"h1":"Son unos cientos de dólares.","h2":"En Virginia, una primera condena de DUI es un delito menor de Clase 1 con una multa mínima obligatoria de $250.","p":"Correcto. Por lo menos $250."},"ref":{"doc":"VA","page":null}},{"id":"vt-001","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","16 years old","15 and a half years old"],"h1":"It is one year before the junior operator's license.","h2":"You can get a Vermont learner's permit at 15, then practice for at least a year before a junior operator's license.","p":"Right. The Vermont permit starts at 15."},"es":{"q":"En Vermont, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","16 años","15 años y medio"],"h1":"Es un año antes de la licencia de operador menor.","h2":"Usted puede obtener el permiso de aprendiz en Vermont a los 15 años y luego practicar por lo menos un año antes de la licencia de operador menor.","p":"Correcto. El permiso en Vermont empieza a los 15."},"zh":{"q":"在 Vermont，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","16 岁","15 岁半"],"h1":"它比青少年驾照早一年。","h2":"在 Vermont，你 15 岁就可以拿到学习驾照，然后至少练习一年，才能拿青少年驾照（junior operator's license）。","p":"对。Vermont 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Vermont, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","15 tuổi rưỡi"],"h1":"Đó là một năm trước bằng lái thiếu niên.","h2":"Ở Vermont, bạn có thể có giấy phép tập lái lúc 15 tuổi, rồi tập ít nhất một năm trước khi có bằng lái thiếu niên (junior operator's license).","p":"Đúng. Giấy phép tập lái ở Vermont bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Vermont, ano ang pinakabatang edad para makakuha ng learner's permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","15 at kalahating taong gulang"],"h1":"Isang taon ito bago ang lisensya ng batang drayber.","h2":"Puwede kang kumuha ng learner's permit sa Vermont sa edad na 15, pagkatapos ay magsanay nang hindi bababa sa isang taon bago ang lisensya ng batang drayber (junior operator's license).","p":"Tama. Nagsisimula ang permit sa Vermont sa edad na 15."},"ar":{"q":"في Vermont، ما أصغر عمر للحصول على تصريح تعلّم القيادة (learner's permit)؟","o":["14 سنة","15 سنة","16 سنة","15 سنة ونصف"],"h1":"إنه قبل رخصة السائق الصغير بسنة واحدة.","h2":"يمكنك الحصول على تصريح تعلّم القيادة في Vermont في عمر 15 سنة، ثم تتدرّب سنة على الأقل قبل رخصة السائق الصغير (junior operator's license).","p":"صحيح. تصريح التعلّم في Vermont يبدأ من عمر 15 سنة."},"ref":{"doc":"VT","page":12}},{"id":"vt-002","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a learner's permit holder may drive with which licensed person in the front seat?","o":["Any licensed driver age 18 or older","A licensed friend age 21 or older","Any passenger with a permit","A parent or guardian, a driving instructor, or a licensed adult age 25 or older"],"h1":"The adult must be older than in many other states, or a parent or teacher.","h2":"A Vermont permit holder must drive with a licensed parent or guardian, a certified driving instructor, or a licensed adult at least 25 years old beside them.","p":"Right. The supervisor must be a parent, guardian, instructor, or licensed adult 25 or older."},"es":{"q":"En Vermont, el titular de un permiso de aprendiz puede manejar con, ¿qué persona con licencia en el asiento delantero?","o":["Cualquier conductor con licencia de 18 años o más","Un amigo con licencia de 21 años o más","Cualquier pasajero con permiso","Su padre, madre o tutor, un instructor de manejo, o un adulto con licencia de 25 años o más"],"h1":"El adulto debe ser mayor que en muchos otros estados, o ser un padre o un maestro.","h2":"Quien tiene permiso en Vermont debe manejar con su padre, madre o tutor con licencia, un instructor de manejo certificado o un adulto con licencia de por lo menos 25 años a su lado.","p":"Correcto. El supervisor debe ser un padre, tutor, instructor o adulto con licencia de 25 años o más."},"zh":{"q":"在 Vermont，持学习驾照的人开车时，前座可以坐哪位有驾照的人？","o":["任何 18 岁或以上有驾照的人","21 岁或以上有驾照的朋友","任何有学习驾照的乘客","父母或监护人、驾驶教练，或 25 岁或以上有驾照的成年人"],"h1":"这个成年人的年龄要比很多州要求的大，或者是父母或老师。","h2":"在 Vermont，持学习驾照的人开车时，旁边必须坐着有驾照的父母或监护人、有资格的驾驶教练，或至少 25 岁、有驾照的成年人。","p":"对。陪同的人必须是父母、监护人、教练，或 25 岁或以上有驾照的成年人。"},"vi":{"q":"Ở Vermont, người có giấy phép tập lái được lái xe với người có bằng lái nào ngồi ghế trước?","o":["Bất kỳ ai có bằng lái từ 18 tuổi trở lên","Một người bạn có bằng lái từ 21 tuổi trở lên","Bất kỳ hành khách nào có giấy phép tập lái","Cha mẹ hoặc người giám hộ, giáo viên dạy lái xe, hoặc người lớn có bằng lái từ 25 tuổi trở lên"],"h1":"Người lớn phải lớn tuổi hơn so với nhiều tiểu bang khác, hoặc là cha mẹ hay giáo viên.","h2":"Ở Vermont, người có giấy phép tập lái phải lái xe với cha mẹ hoặc người giám hộ có bằng lái, giáo viên dạy lái xe có chứng chỉ, hoặc người lớn có bằng lái ít nhất 25 tuổi ngồi bên cạnh.","p":"Đúng. Người giám sát phải là cha mẹ, người giám hộ, giáo viên, hoặc người lớn có bằng lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Vermont, puwedeng magmaneho ang may learner's permit kasama ang aling may lisensyang tao sa upuan sa harap?","o":["Sinumang may lisensyang drayber na edad 18 pataas","Isang kaibigang may lisensya na edad 21 pataas","Sinumang pasaherong may permit","Magulang o tagapag-alaga, guro sa pagmamaneho, o may lisensyang adulto na edad 25 pataas"],"h1":"Mas matanda ang adulto kaysa sa maraming ibang estado, o kaya magulang o guro.","h2":"Ang may permit sa Vermont ay dapat magmaneho kasama sa tabi ang may lisensyang magulang o tagapag-alaga, isang sertipikadong guro sa pagmamaneho, o may lisensyang adulto na hindi bababa sa 25 taong gulang.","p":"Tama. Ang kasama ay dapat magulang, tagapag-alaga, guro, o may lisensyang adulto na 25 pataas."},"ar":{"q":"في Vermont، يمكن لحامل تصريح التعلّم أن يقود مع أيّ شخص يحمل رخصة في المقعد الأمامي؟","o":["أي سائق يحمل رخصة وعمره 18 سنة أو أكثر","صديق يحمل رخصة وعمره 21 سنة أو أكثر","أي راكب معه تصريح تعلّم","أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر"],"h1":"يجب أن يكون البالغ أكبر سنًّا مما في ولايات كثيرة أخرى، أو أن يكون أحد الوالدين أو معلّمًا.","h2":"يجب على حامل تصريح التعلّم في Vermont أن يقود وبجانبه أحد الوالدين أو الوصي يحمل رخصة، أو مدرّب قيادة معتمد، أو شخص بالغ يحمل رخصة وعمره 25 سنة على الأقل.","p":"صحيح. يجب أن يكون المرافق أحد الوالدين أو الوصي أو مدرّبًا أو بالغًا يحمل رخصة وعمره 25 سنة أو أكثر."},"ref":{"doc":"VT","page":13}},{"id":"vt-003","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how long must a teen hold a learner's permit before getting a junior operator's license?","o":["At least one year","At least 3 months","At least 6 months","At least 2 years"],"h1":"It is longer than in many states.","h2":"A Vermont teen must hold a learner's permit for at least one year before getting a junior operator's license.","p":"Right. The permit must be held at least one year."},"es":{"q":"En Vermont, ¿cuánto tiempo debe tener un adolescente el permiso de aprendiz antes de obtener la licencia de operador menor?","o":["Por lo menos un año","Por lo menos 3 meses","Por lo menos 6 meses","Por lo menos 2 años"],"h1":"Es más tiempo que en muchos estados.","h2":"Un adolescente en Vermont debe tener el permiso de aprendiz por lo menos un año antes de obtener la licencia de operador menor.","p":"Correcto. El permiso se debe tener por lo menos un año."},"zh":{"q":"在 Vermont，青少年拿青少年驾照（junior operator's license）前，必须持有学习驾照多久？","o":["至少一年","至少 3 个月","至少 6 个月","至少 2 年"],"h1":"它比很多州要求的时间长。","h2":"在 Vermont，青少年必须持有学习驾照至少一年，才能拿青少年驾照。","p":"对。学习驾照必须持有至少一年。"},"vi":{"q":"Ở Vermont, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi có bằng lái thiếu niên (junior operator's license)?","o":["Ít nhất một năm","Ít nhất 3 tháng","Ít nhất 6 tháng","Ít nhất 2 năm"],"h1":"Thời gian này dài hơn so với nhiều tiểu bang.","h2":"Ở Vermont, thiếu niên phải giữ giấy phép tập lái ít nhất một năm trước khi có bằng lái thiếu niên.","p":"Đúng. Phải giữ giấy phép tập lái ít nhất một năm."},"tl":{"q":"Sa Vermont, gaano katagal dapat hawak ng tinedyer ang learner's permit bago makakuha ng lisensya ng batang drayber (junior operator's license)?","o":["Hindi bababa sa isang taon","Hindi bababa sa 3 buwan","Hindi bababa sa 6 na buwan","Hindi bababa sa 2 taon"],"h1":"Mas matagal ito kaysa sa maraming estado.","h2":"Ang tinedyer sa Vermont ay dapat humawak ng learner's permit nang hindi bababa sa isang taon bago makakuha ng lisensya ng batang drayber.","p":"Tama. Dapat hawak ang permit nang hindi bababa sa isang taon."},"ar":{"q":"في Vermont، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على رخصة السائق الصغير (junior operator's license)؟","o":["سنة واحدة على الأقل","3 أشهر على الأقل","6 أشهر على الأقل","سنتان على الأقل"],"h1":"إنها أطول مما في ولايات كثيرة.","h2":"يجب على المراهق في Vermont أن يحمل تصريح التعلّم سنة واحدة على الأقل قبل الحصول على رخصة السائق الصغير.","p":"صحيح. يجب حمل تصريح التعلّم سنة واحدة على الأقل."},"ref":{"doc":"VT","page":13}},{"id":"vt-004","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how many hours of supervised driving must a teen complete before a junior operator's license?","o":["20 hours","30 hours","40 hours","60 hours"],"h1":"It is less than fifty.","h2":"A Vermont teen must complete at least 40 hours of supervised driving before a junior operator's license.","p":"Right. Vermont asks for 40 hours of practice."},"es":{"q":"En Vermont, ¿cuántas horas de manejo supervisado debe completar un adolescente antes de la licencia de operador menor?","o":["20 horas","30 horas","40 horas","60 horas"],"h1":"Es menos de cincuenta.","h2":"Un adolescente en Vermont debe completar por lo menos 40 horas de manejo supervisado antes de la licencia de operador menor.","p":"Correcto. Vermont pide 40 horas de práctica."},"zh":{"q":"在 Vermont，青少年拿青少年驾照前，必须完成多少小时有人陪同的驾驶练习？","o":["20 小时","30 小时","40 小时","60 小时"],"h1":"它少于五十。","h2":"在 Vermont，青少年拿青少年驾照前，必须完成至少 40 小时有人陪同的驾驶练习。","p":"对。Vermont 要求练习 40 小时。"},"vi":{"q":"Ở Vermont, thiếu niên phải lái xe có người giám sát bao nhiêu giờ trước khi có bằng lái thiếu niên?","o":["20 giờ","30 giờ","40 giờ","60 giờ"],"h1":"Ít hơn năm mươi.","h2":"Ở Vermont, thiếu niên phải lái xe có người giám sát ít nhất 40 giờ trước khi có bằng lái thiếu niên.","p":"Đúng. Vermont yêu cầu 40 giờ tập lái."},"tl":{"q":"Sa Vermont, ilang oras ng pagmamanehong may kasamang tagabantay ang dapat tapusin ng tinedyer bago ang lisensya ng batang drayber?","o":["20 oras","30 oras","40 oras","60 oras"],"h1":"Mas kaunti ito sa limampu.","h2":"Ang tinedyer sa Vermont ay dapat tumapos ng hindi bababa sa 40 oras ng pagmamanehong may kasamang tagabantay bago ang lisensya ng batang drayber.","p":"Tama. Humihingi ang Vermont ng 40 oras ng pagsasanay."},"ar":{"q":"في Vermont، كم ساعة من القيادة تحت الإشراف يجب أن يُكملها المراهق قبل رخصة السائق الصغير؟","o":["20 ساعة","30 ساعة","40 ساعة","60 ساعة"],"h1":"إنها أقل من خمسين.","h2":"يجب على المراهق في Vermont أن يُكمل 40 ساعة على الأقل من القيادة تحت الإشراف قبل رخصة السائق الصغير.","p":"صحيح. تطلب Vermont 40 ساعة من التدريب."},"ref":{"doc":"VT","page":13}},{"id":"vt-005","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many of the 40 practice hours must be driven at night?","o":["At least 5 hours","At least 10 hours","At least 15 hours","At least 20 hours"],"h1":"It is one quarter of the total.","h2":"At least 10 of the 40 practice hours in Vermont must be at night, because driving in the dark needs its own practice.","p":"Right. At least 10 hours must be at night."},"es":{"q":"En Vermont, ¿cuántas de las 40 horas de práctica deben ser de noche?","o":["Por lo menos 5 horas","Por lo menos 10 horas","Por lo menos 15 horas","Por lo menos 20 horas"],"h1":"Es la cuarta parte del total.","h2":"Por lo menos 10 de las 40 horas de práctica en Vermont deben ser de noche, porque manejar en la oscuridad necesita su propia práctica.","p":"Correcto. Por lo menos 10 horas deben ser de noche."},"zh":{"q":"在 Vermont，40 小时练习中，有多少小时必须在夜间开车？","o":["至少 5 小时","至少 10 小时","至少 15 小时","至少 20 小时"],"h1":"它是总数的四分之一。","h2":"在 Vermont，40 小时练习中至少 10 小时必须在夜间，因为天黑开车需要专门练习。","p":"对。至少 10 小时必须在夜间。"},"vi":{"q":"Ở Vermont, trong 40 giờ tập lái, bao nhiêu giờ phải lái vào ban đêm?","o":["Ít nhất 5 giờ","Ít nhất 10 giờ","Ít nhất 15 giờ","Ít nhất 20 giờ"],"h1":"Đó là một phần tư tổng số.","h2":"Ở Vermont, ít nhất 10 trong 40 giờ tập lái phải vào ban đêm, vì lái xe trong bóng tối cần được tập riêng.","p":"Đúng. Ít nhất 10 giờ phải vào ban đêm."},"tl":{"q":"Sa Vermont, ilan sa 40 oras ng pagsasanay ang dapat imaneho sa gabi?","o":["Hindi bababa sa 5 oras","Hindi bababa sa 10 oras","Hindi bababa sa 15 oras","Hindi bababa sa 20 oras"],"h1":"Ito ay isang-kapat ng kabuuan.","h2":"Hindi bababa sa 10 sa 40 oras ng pagsasanay sa Vermont ang dapat sa gabi, dahil kailangan ng sariling pagsasanay ang pagmamaneho sa dilim.","p":"Tama. Hindi bababa sa 10 oras ang dapat sa gabi."},"ar":{"q":"في Vermont، كم ساعة من ساعات التدريب الـ 40 يجب أن تكون في الليل؟","o":["5 ساعات على الأقل","10 ساعات على الأقل","15 ساعة على الأقل","20 ساعة على الأقل"],"h1":"إنها ربع المجموع.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 40 في Vermont في الليل، لأن القيادة في الظلام تحتاج إلى تدريب خاص بها.","p":"صحيح. يجب أن تكون 10 ساعات على الأقل في الليل."},"ref":{"doc":"VT","page":13}},{"id":"vt-006","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what course must a teen pass before getting a junior operator's license?","o":["A first aid course","A car repair course","A defensive driving course for adults","A state-approved driver education course"],"h1":"It is taught to new drivers, often in high school.","h2":"A Vermont teen must finish a state-approved driver education course before getting a junior operator's license.","p":"Right. Driver education is required."},"es":{"q":"En Vermont, ¿qué curso debe aprobar un adolescente antes de obtener la licencia de operador menor?","o":["Un curso de primeros auxilios","Un curso de reparación de autos","Un curso de manejo defensivo para adultos","Un curso de educación vial aprobado por el estado"],"h1":"Se enseña a conductores nuevos, muchas veces en la secundaria.","h2":"Un adolescente en Vermont debe terminar un curso de educación vial aprobado por el estado antes de obtener la licencia de operador menor.","p":"Correcto. La educación vial es obligatoria."},"zh":{"q":"在 Vermont，青少年拿青少年驾照前，必须通过什么课程？","o":["急救课程","修车课程","成人防御性驾驶课程","州政府认可的驾驶教育课程"],"h1":"这门课是教新司机的，常常在高中上。","h2":"在 Vermont，青少年必须完成州政府认可的驾驶教育课程（driver education），才能拿青少年驾照。","p":"对。必须上驾驶教育课。"},"vi":{"q":"Ở Vermont, thiếu niên phải học xong khóa học nào trước khi có bằng lái thiếu niên?","o":["Khóa sơ cứu","Khóa sửa xe","Khóa lái xe phòng thủ cho người lớn","Khóa giáo dục lái xe được tiểu bang chấp thuận"],"h1":"Khóa này dạy cho người mới lái, thường ở trường trung học.","h2":"Ở Vermont, thiếu niên phải học xong khóa giáo dục lái xe (driver education) được tiểu bang chấp thuận trước khi có bằng lái thiếu niên.","p":"Đúng. Bắt buộc phải học giáo dục lái xe."},"tl":{"q":"Sa Vermont, anong kurso ang dapat ipasa ng tinedyer bago makakuha ng lisensya ng batang drayber?","o":["Kurso sa first aid","Kurso sa pag-aayos ng kotse","Kurso sa ligtas na pagmamaneho para sa adulto","Kurso sa edukasyon sa pagmamaneho na aprubado ng estado"],"h1":"Itinuturo ito sa mga bagong drayber, madalas sa high school.","h2":"Ang tinedyer sa Vermont ay dapat tumapos ng kurso sa edukasyon sa pagmamaneho (driver education) na aprubado ng estado bago makakuha ng lisensya ng batang drayber.","p":"Tama. Kailangan ang edukasyon sa pagmamaneho."},"ar":{"q":"في Vermont، أيّ دورة يجب أن ينجح فيها المراهق قبل الحصول على رخصة السائق الصغير؟","o":["دورة إسعافات أولية","دورة تصليح سيارات","دورة القيادة الدفاعية للبالغين","دورة تعليم قيادة معتمدة من الولاية"],"h1":"تُدرَّس للسائقين الجدد، وغالبًا في المدرسة الثانوية.","h2":"يجب على المراهق في Vermont أن يُنهي دورة تعليم قيادة (driver education) معتمدة من الولاية قبل الحصول على رخصة السائق الصغير.","p":"صحيح. تعليم القيادة مطلوب."},"ref":{"doc":"VT","page":13}},{"id":"vt-007","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, during the first three months of a junior operator's license, who may ride with the driver?","o":["Any friends, if they wear seat belts","Only brothers and sisters","No one, or a parent, guardian, instructor, or licensed adult age 25 or older","Up to two friends under 18"],"h1":"In the first months, the driver is alone or with a qualified adult.","h2":"For the first three months, a Vermont junior operator may drive only alone or with a parent or guardian, a driving instructor, or a licensed adult 25 or older.","p":"Right. At first, drive alone or with a qualified adult."},"es":{"q":"En Vermont, durante los primeros tres meses de la licencia de operador menor, ¿quién puede ir con el conductor?","o":["Cualquier amigo, si usa cinturón","Solo hermanos y hermanas","Nadie, o un padre, tutor, instructor o adulto con licencia de 25 años o más","Hasta dos amigos menores de 18"],"h1":"En los primeros meses, el conductor va solo o con un adulto calificado.","h2":"Durante los primeros tres meses, un operador menor en Vermont solo puede manejar solo o con su padre, madre o tutor, un instructor de manejo o un adulto con licencia de 25 años o más.","p":"Correcto. Al principio, maneje solo o con un adulto calificado."},"zh":{"q":"在 Vermont，拿到青少年驾照的头三个月，谁可以和司机一起坐车？","o":["任何朋友，只要系安全带","只有兄弟姐妹","没有人，或者父母、监护人、教练，或 25 岁或以上有驾照的成年人","最多两个 18 岁以下的朋友"],"h1":"头几个月，司机要么一个人，要么和合格的成年人一起。","h2":"在 Vermont，拿到青少年驾照的头三个月，司机只能一个人开车，或者和父母或监护人、驾驶教练，或 25 岁或以上有驾照的成年人一起开车。","p":"对。开始时，一个人开车或和合格的成年人一起开车。"},"vi":{"q":"Ở Vermont, trong ba tháng đầu có bằng lái thiếu niên, ai được đi cùng xe với người lái?","o":["Bất kỳ người bạn nào, nếu họ thắt dây an toàn","Chỉ anh chị em ruột","Không ai, hoặc cha mẹ, người giám hộ, giáo viên, hoặc người lớn có bằng lái từ 25 tuổi trở lên","Tối đa hai người bạn dưới 18 tuổi"],"h1":"Trong những tháng đầu, người lái đi một mình hoặc với một người lớn đủ điều kiện.","h2":"Ở Vermont, trong ba tháng đầu, người có bằng lái thiếu niên chỉ được lái một mình hoặc với cha mẹ hay người giám hộ, giáo viên dạy lái xe, hoặc người lớn có bằng lái từ 25 tuổi trở lên.","p":"Đúng. Lúc đầu, lái một mình hoặc với một người lớn đủ điều kiện."},"tl":{"q":"Sa Vermont, sa unang tatlong buwan ng lisensya ng batang drayber, sino ang puwedeng sumakay kasama ng drayber?","o":["Kahit sinong kaibigan, kung naka-seat belt sila","Mga kapatid lamang","Walang iba, o magulang, tagapag-alaga, guro, o may lisensyang adulto na edad 25 pataas","Hanggang dalawang kaibigang wala pang 18"],"h1":"Sa mga unang buwan, mag-isa ang drayber o kasama ang kuwalipikadong adulto.","h2":"Sa unang tatlong buwan, ang batang drayber sa Vermont ay puwedeng magmaneho nang mag-isa lamang, o kasama ang magulang o tagapag-alaga, guro sa pagmamaneho, o may lisensyang adulto na 25 pataas.","p":"Tama. Sa simula, magmaneho nang mag-isa o kasama ang kuwalipikadong adulto."},"ar":{"q":"في Vermont، خلال الأشهر الثلاثة الأولى من رخصة السائق الصغير، مَن يمكنه الركوب مع السائق؟","o":["أي أصدقاء، إذا ربطوا أحزمة الأمان","الإخوة والأخوات فقط","لا أحد، أو أحد الوالدين أو الوصي أو مدرّب أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر","صديقان على الأكثر عمرهما أقل من 18 سنة"],"h1":"في الأشهر الأولى، يكون السائق وحده أو مع شخص بالغ مؤهّل.","h2":"في الأشهر الثلاثة الأولى، يمكن للسائق الصغير في Vermont أن يقود وحده فقط، أو مع أحد الوالدين أو الوصي، أو مدرّب قيادة، أو شخص بالغ يحمل رخصة وعمره 25 سنة أو أكثر.","p":"صحيح. في البداية، قُد وحدك أو مع شخص بالغ مؤهّل."},"ref":{"doc":"VT","page":15}},{"id":"vt-008","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, during months four to six of a junior operator's license, who else may the driver carry?","o":["Family members","Any friend over 18","Up to three classmates","Anyone with a learner's permit"],"h1":"Think of the people you live with.","h2":"During the second three months, a Vermont junior operator may also carry family members, but not other young passengers without a qualified adult.","p":"Right. Family members may ride in months four to six."},"es":{"q":"En Vermont, durante los meses cuatro a seis de la licencia de operador menor, ¿a quién más puede llevar el conductor?","o":["A familiares","A cualquier amigo mayor de 18","Hasta tres compañeros de clase","A cualquiera con permiso de aprendiz"],"h1":"Piense en las personas con quienes vive.","h2":"Durante los segundos tres meses, un operador menor en Vermont también puede llevar a familiares, pero no a otros pasajeros jóvenes sin un adulto calificado.","p":"Correcto. Los familiares pueden ir en los meses cuatro a seis."},"zh":{"q":"在 Vermont，拿到青少年驾照的第四到第六个月，司机还可以载谁？","o":["家人","任何 18 岁以上的朋友","最多三个同学","任何有学习驾照的人"],"h1":"想想和你住在一起的人。","h2":"在 Vermont，第二个三个月里，青少年司机还可以载家人，但没有合格的成年人在车上时，不能载其他年轻乘客。","p":"对。第四到第六个月可以载家人。"},"vi":{"q":"Ở Vermont, từ tháng thứ tư đến tháng thứ sáu có bằng lái thiếu niên, người lái còn được chở thêm ai?","o":["Người trong gia đình","Bất kỳ người bạn nào trên 18 tuổi","Tối đa ba bạn cùng lớp","Bất kỳ ai có giấy phép tập lái"],"h1":"Hãy nghĩ đến những người sống cùng nhà với bạn.","h2":"Ở Vermont, trong ba tháng thứ hai, người có bằng lái thiếu niên được chở thêm người trong gia đình, nhưng không được chở hành khách trẻ khác nếu không có người lớn đủ điều kiện.","p":"Đúng. Người trong gia đình được đi cùng từ tháng thứ tư đến tháng thứ sáu."},"tl":{"q":"Sa Vermont, sa ikaapat hanggang ikaanim na buwan ng lisensya ng batang drayber, sino pa ang puwedeng isakay ng drayber?","o":["Mga kapamilya","Kahit sinong kaibigan na lampas 18","Hanggang tatlong kaklase","Sinumang may learner's permit"],"h1":"Isipin ang mga taong kasama mo sa bahay.","h2":"Sa ikalawang tatlong buwan, puwede ring magsakay ng mga kapamilya ang batang drayber sa Vermont, pero hindi ibang batang pasahero kung walang kuwalipikadong adulto.","p":"Tama. Puwedeng sumakay ang mga kapamilya sa ikaapat hanggang ikaanim na buwan."},"ar":{"q":"في Vermont، خلال الأشهر من الرابع إلى السادس من رخصة السائق الصغير، مَن أيضًا يمكن للسائق أن يُركِب معه؟","o":["أفراد العائلة","أي صديق عمره أكثر من 18 سنة","ثلاثة زملاء دراسة على الأكثر","أي شخص معه تصريح تعلّم"],"h1":"فكّر في الأشخاص الذين تعيش معهم.","h2":"خلال الأشهر الثلاثة الثانية، يمكن للسائق الصغير في Vermont أن يُركِب أيضًا أفراد العائلة، ولكن لا يُركِب ركّابًا صغارًا آخرين بدون شخص بالغ مؤهّل.","p":"صحيح. يمكن لأفراد العائلة الركوب في الأشهر من الرابع إلى السادس."},"ref":{"doc":"VT","page":15}},{"id":"vt-009","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator may never carry more passengers than what?","o":["Two people","The number of seat belts in the car","Four people","The number of doors on the car"],"h1":"Every rider needs something to buckle.","h2":"A Vermont junior operator may never carry more passengers than there are seat belts in the vehicle.","p":"Right. No more passengers than seat belts."},"es":{"q":"En Vermont, un operador menor nunca puede llevar más pasajeros que, ¿qué?","o":["Dos personas","El número de cinturones de seguridad del auto","Cuatro personas","El número de puertas del auto"],"h1":"Cada pasajero necesita algo para abrocharse.","h2":"Un operador menor en Vermont nunca puede llevar más pasajeros que cinturones de seguridad hay en el vehículo.","p":"Correcto. No más pasajeros que cinturones."},"zh":{"q":"在 Vermont，青少年司机载的乘客，绝不能多于什么？","o":["两个人","车里安全带的数量","四个人","车门的数量"],"h1":"每个乘客都需要能系上的东西。","h2":"在 Vermont，青少年司机载的乘客绝不能多于车里安全带的数量。","p":"对。乘客不能多于安全带。"},"vi":{"q":"Ở Vermont, người có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số nào?","o":["Hai người","Số dây an toàn trong xe","Bốn người","Số cửa của xe"],"h1":"Mỗi người ngồi xe cần có thứ để cài.","h2":"Ở Vermont, người có bằng lái thiếu niên không bao giờ được chở nhiều hành khách hơn số dây an toàn trong xe.","p":"Đúng. Không chở nhiều hành khách hơn số dây an toàn."},"tl":{"q":"Sa Vermont, hindi kailanman puwedeng magsakay ang batang drayber ng mas maraming pasahero kaysa sa ano?","o":["Dalawang tao","Bilang ng seat belt sa kotse","Apat na tao","Bilang ng pinto ng kotse"],"h1":"Bawat sakay ay kailangan ng maikakabit.","h2":"Ang batang drayber sa Vermont ay hindi kailanman puwedeng magsakay ng mas maraming pasahero kaysa sa bilang ng seat belt sa sasakyan.","p":"Tama. Hindi lalampas ang pasahero sa bilang ng seat belt."},"ar":{"q":"في Vermont، لا يجوز أبدًا للسائق الصغير أن يُركِب ركّابًا أكثر من ماذا؟","o":["شخصين","عدد أحزمة الأمان في السيارة","أربعة أشخاص","عدد أبواب السيارة"],"h1":"كل راكب يحتاج إلى شيء يربطه.","h2":"لا يجوز أبدًا للسائق الصغير في Vermont أن يُركِب ركّابًا أكثر من عدد أحزمة الأمان في السيارة.","p":"صحيح. لا ركّاب أكثر من أحزمة الأمان."},"ref":{"doc":"VT","page":15}},{"id":"vt-010","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what happens if a junior operator breaks the passenger rules?","o":["Only a warning","A one-year suspension","A new road test","The license is recalled for 90 days"],"h1":"The license is taken back for about three months.","h2":"Breaking the passenger rules in Vermont leads to a 90-day recall of the junior operator's license.","p":"Right. The penalty is a 90-day recall."},"es":{"q":"En Vermont, ¿qué pasa si un operador menor no cumple las reglas de pasajeros?","o":["Solo una advertencia","Una suspensión de un año","Un nuevo examen de manejo","Le retiran la licencia por 90 días"],"h1":"Le quitan la licencia unos tres meses.","h2":"No cumplir las reglas de pasajeros en Vermont lleva a que le retiren la licencia de operador menor por 90 días.","p":"Correcto. El castigo es retirar la licencia por 90 días."},"zh":{"q":"在 Vermont，青少年司机违反乘客规定会怎样？","o":["只是警告","吊销驾照一年","重新考路考","驾照被收回 90 天"],"h1":"驾照会被收回大约三个月。","h2":"在 Vermont，违反乘客规定会被收回青少年驾照 90 天。","p":"对。处罚是收回驾照 90 天。"},"vi":{"q":"Ở Vermont, chuyện gì xảy ra nếu người có bằng lái thiếu niên vi phạm luật về hành khách?","o":["Chỉ bị cảnh cáo","Bị treo bằng một năm","Phải thi lái lại","Bằng lái bị thu hồi 90 ngày"],"h1":"Bằng lái bị lấy lại khoảng ba tháng.","h2":"Ở Vermont, vi phạm luật về hành khách sẽ bị thu hồi bằng lái thiếu niên 90 ngày.","p":"Đúng. Hình phạt là thu hồi bằng 90 ngày."},"tl":{"q":"Sa Vermont, ano ang mangyayari kung lumabag ang batang drayber sa mga tuntunin sa pasahero?","o":["Babala lamang","Suspensyon nang isang taon","Bagong road test","Babawiin ang lisensya nang 90 araw"],"h1":"Kukunin muli ang lisensya nang mga tatlong buwan.","h2":"Sa Vermont, ang paglabag sa mga tuntunin sa pasahero ay humahantong sa pagbawi ng lisensya ng batang drayber nang 90 araw.","p":"Tama. Ang parusa ay pagbawi nang 90 araw."},"ar":{"q":"في Vermont، ماذا يحدث إذا خالف السائق الصغير قواعد الركّاب؟","o":["تحذير فقط","إيقاف الرخصة لمدة سنة","اختبار قيادة جديد","تُسحب الرخصة لمدة 90 يومًا"],"h1":"تُؤخذ الرخصة لمدة ثلاثة أشهر تقريبًا.","h2":"مخالفة قواعد الركّاب في Vermont تؤدي إلى سحب رخصة السائق الصغير لمدة 90 يومًا.","p":"صحيح. العقوبة هي سحب الرخصة لمدة 90 يومًا."},"ref":{"doc":"VT","page":null}},{"id":"vt-011","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, may a driver under 18 use a phone hands-free while driving?","o":["Yes, if it is on speaker","Yes, on roads under 40 mph","No, not even hands-free","Yes, after six months of driving"],"h1":"The rule for young drivers is stricter than for adults.","h2":"A Vermont driver under 18 may not use any portable electronic device while driving, even hands-free, except to reach police or emergency services in an emergency.","p":"Right. Drivers under 18 may not use a phone, even hands-free."},"es":{"q":"En Vermont, ¿puede un conductor menor de 18 años usar el teléfono con manos libres mientras maneja?","o":["Sí, si está en altavoz","Sí, en caminos de menos de 40 mph","No, ni siquiera con manos libres","Sí, después de seis meses manejando"],"h1":"La regla para conductores jóvenes es más estricta que para los adultos.","h2":"Un conductor menor de 18 años en Vermont no puede usar ningún aparato electrónico portátil mientras maneja, ni con manos libres, salvo para comunicarse con la policía o los servicios de emergencia en una emergencia.","p":"Correcto. Los menores de 18 no pueden usar el teléfono, ni con manos libres."},"zh":{"q":"在 Vermont，18 岁以下的司机开车时可以用免提打电话吗？","o":["可以，如果开扬声器","可以，在时速低于 40 mph 的路上","不可以，免提也不行","可以，开车六个月以后"],"h1":"对年轻司机的规定比对成年人更严格。","h2":"在 Vermont，18 岁以下的司机开车时不能用任何便携电子设备，免提也不行，只有在紧急情况下联系警察或急救服务除外。","p":"对。18 岁以下的司机不能用手机，免提也不行。"},"vi":{"q":"Ở Vermont, người lái dưới 18 tuổi có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, nếu bật loa ngoài","Có, trên đường dưới 40 mph","Không, rảnh tay cũng không được","Có, sau sáu tháng lái xe"],"h1":"Luật cho người lái trẻ nghiêm hơn cho người lớn.","h2":"Ở Vermont, người lái dưới 18 tuổi không được dùng bất kỳ thiết bị điện tử cầm tay nào khi lái xe, kể cả rảnh tay, trừ khi gọi cảnh sát hoặc dịch vụ cấp cứu trong trường hợp khẩn cấp.","p":"Đúng. Người lái dưới 18 tuổi không được dùng điện thoại, kể cả rảnh tay."},"tl":{"q":"Sa Vermont, puwede bang gumamit ng telepono nang hands-free ang drayber na wala pang 18 habang nagmamaneho?","o":["Oo, kung naka-speaker","Oo, sa mga daang mas mababa sa 40 mph","Hindi, kahit hands-free","Oo, pagkatapos ng anim na buwang pagmamaneho"],"h1":"Mas mahigpit ang tuntunin para sa batang drayber kaysa sa adulto.","h2":"Ang drayber sa Vermont na wala pang 18 ay hindi puwedeng gumamit ng anumang portable na electronic device habang nagmamaneho, kahit hands-free, maliban sa pagtawag sa pulis o emergency services sa oras ng emergency.","p":"Tama. Ang drayber na wala pang 18 ay hindi puwedeng gumamit ng telepono, kahit hands-free."},"ar":{"q":"في Vermont، هل يجوز للسائق الذي عمره أقل من 18 سنة استخدام الهاتف بدون يدين أثناء القيادة؟","o":["نعم، إذا كان على مكبّر الصوت","نعم، على الطرق التي سرعتها أقل من 40 mph","لا، ولا حتى بدون يدين","نعم، بعد ستة أشهر من القيادة"],"h1":"القاعدة للسائقين الصغار أشدّ منها للبالغين.","h2":"لا يجوز للسائق في Vermont الذي عمره أقل من 18 سنة استخدام أي جهاز إلكتروني محمول أثناء القيادة، حتى بدون يدين، إلا للاتصال بالشرطة أو خدمات الطوارئ في حالة طارئة.","p":"صحيح. السائقون تحت 18 سنة لا يستخدمون الهاتف، حتى بدون يدين."},"ref":{"doc":"VT","page":null}},{"id":"vt-012","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, may an adult driver hold a phone while stopped at a red light?","o":["No, the ban applies even when stopped","Yes, the car is not moving","Yes, for a short text only","Yes, if the engine is idling"],"h1":"Stopping in traffic does not end the rule.","h2":"Vermont bans holding a phone while driving, and the ban still applies when you are stopped at a red light or stop sign.","p":"Right. No handheld phone, even at a red light."},"es":{"q":"En Vermont, ¿puede un conductor adulto sostener el teléfono mientras está detenido en un semáforo rojo?","o":["No, la prohibición vale aunque esté detenido","Sí, el auto no se mueve","Sí, solo para un mensaje corto","Sí, si el motor está encendido"],"h1":"Detenerse en el tráfico no termina la regla.","h2":"Vermont prohíbe sostener el teléfono mientras maneja, y la prohibición sigue cuando está detenido en un semáforo rojo o en un alto.","p":"Correcto. Nada de teléfono en la mano, ni en el semáforo rojo."},"zh":{"q":"在 Vermont，成年司机在红灯前停车时可以手拿手机吗？","o":["不可以，停车时也禁止","可以，车没有在动","可以，只发一条短信","可以，如果发动机在空转"],"h1":"在车流中停下来，规定并不结束。","h2":"Vermont 禁止开车时手拿手机，在红灯或停车标志前停下时也同样禁止。","p":"对。红灯时也不能手拿手机。"},"vi":{"q":"Ở Vermont, người lái là người lớn có được cầm điện thoại khi dừng đèn đỏ không?","o":["Không, lệnh cấm vẫn áp dụng khi dừng xe","Có, vì xe không chạy","Có, chỉ để nhắn tin ngắn","Có, nếu máy xe đang nổ"],"h1":"Dừng lại giữa dòng xe không làm hết luật.","h2":"Vermont cấm cầm điện thoại khi lái xe, và lệnh cấm vẫn áp dụng khi bạn dừng ở đèn đỏ hoặc bảng dừng (stop sign).","p":"Đúng. Không cầm điện thoại, kể cả khi dừng đèn đỏ."},"tl":{"q":"Sa Vermont, puwede bang hawakan ng adultong drayber ang telepono habang nakahinto sa pulang ilaw?","o":["Hindi, umiiral pa rin ang pagbabawal kahit nakahinto","Oo, hindi gumagalaw ang kotse","Oo, para sa maikling text lamang","Oo, kung umaandar ang makina"],"h1":"Hindi natatapos ang tuntunin kapag huminto ka sa trapiko.","h2":"Ipinagbabawal ng Vermont ang paghawak ng telepono habang nagmamaneho, at umiiral pa rin ito kapag nakahinto ka sa pulang ilaw o STOP sign.","p":"Tama. Bawal hawakan ang telepono, kahit sa pulang ilaw."},"ar":{"q":"في Vermont، هل يجوز للسائق البالغ أن يمسك الهاتف وهو متوقف عند الإشارة الحمراء؟","o":["لا، المنع يسري حتى عند التوقف","نعم، السيارة لا تتحرك","نعم، لرسالة قصيرة فقط","نعم، إذا كان المحرك يعمل"],"h1":"التوقف في حركة المرور لا يُنهي القاعدة.","h2":"تمنع Vermont إمساك الهاتف أثناء القيادة، ويبقى المنع ساريًا عندما تتوقف عند إشارة حمراء أو لافتة توقف (STOP).","p":"صحيح. لا تمسك الهاتف، حتى عند الإشارة الحمراء."},"ref":{"doc":"VT","page":55}},{"id":"vt-013","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, which phone use is allowed for a driver age 18 or older?","o":["Typing a text at low speed","Talking hands-free, without holding the phone","Holding the phone on speaker","Watching a video at a stop"],"h1":"Your hands must stay off the phone.","h2":"Vermont lets adult drivers use a phone only hands-free, without holding it in either hand.","p":"Right. Adults may use a phone hands-free."},"es":{"q":"En Vermont, ¿qué uso del teléfono está permitido para un conductor de 18 años o más?","o":["Escribir un mensaje a baja velocidad","Hablar con manos libres, sin sostener el teléfono","Sostener el teléfono en altavoz","Ver un video en un alto"],"h1":"Sus manos no deben tocar el teléfono.","h2":"Vermont permite a los conductores adultos usar el teléfono solo con manos libres, sin sostenerlo en ninguna mano.","p":"Correcto. Los adultos pueden usar el teléfono con manos libres."},"zh":{"q":"在 Vermont，18 岁或以上的司机可以怎样使用手机？","o":["低速时打字发短信","用免提通话，不用手拿手机","开扬声器拿着手机","停车时看视频"],"h1":"你的手不能碰手机。","h2":"Vermont 只允许成年司机用免提使用手机，两只手都不能拿着手机。","p":"对。成年人可以用免提使用手机。"},"vi":{"q":"Ở Vermont, người lái từ 18 tuổi trở lên được dùng điện thoại theo cách nào?","o":["Nhắn tin khi chạy chậm","Nói chuyện rảnh tay, không cầm điện thoại","Cầm điện thoại bật loa ngoài","Xem video khi dừng xe"],"h1":"Tay bạn phải không chạm vào điện thoại.","h2":"Vermont chỉ cho người lái là người lớn dùng điện thoại rảnh tay, không cầm điện thoại bằng tay nào cả.","p":"Đúng. Người lớn được dùng điện thoại rảnh tay."},"tl":{"q":"Sa Vermont, aling paggamit ng telepono ang pinapayagan para sa drayber na edad 18 pataas?","o":["Pag-type ng text sa mabagal na takbo","Pakikipag-usap nang hands-free, nang hindi hinahawakan ang telepono","Paghawak ng telepono na naka-speaker","Panonood ng video kapag nakahinto"],"h1":"Hindi dapat hawakan ng iyong mga kamay ang telepono.","h2":"Pinapayagan ng Vermont ang adultong drayber na gumamit ng telepono nang hands-free lamang, nang hindi ito hinahawakan ng alinmang kamay.","p":"Tama. Puwedeng gumamit ang adulto ng telepono nang hands-free."},"ar":{"q":"في Vermont، أيّ استخدام للهاتف مسموح للسائق الذي عمره 18 سنة أو أكثر؟","o":["كتابة رسالة على سرعة منخفضة","التحدّث بدون يدين، بدون إمساك الهاتف","إمساك الهاتف على مكبّر الصوت","مشاهدة فيديو عند التوقف"],"h1":"يجب أن تبقى يداك بعيدتين عن الهاتف.","h2":"تسمح Vermont للسائقين البالغين باستخدام الهاتف بدون يدين فقط، بدون إمساكه بأيّ يد.","p":"صحيح. يمكن للبالغين استخدام الهاتف بدون يدين."},"ref":{"doc":"VT","page":null}},{"id":"vt-014","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, a driver under 21 breaks the law with a blood alcohol level of what?","o":["0.08 or more","0.05 or more","0.10 or more","0.02 or more"],"h1":"It is much lower than the adult limit.","h2":"In Vermont, a driver under 21 with a blood alcohol level of 0.02 or more commits a violation, far below the adult limit of 0.08.","p":"Right. Under 21, the limit is 0.02."},"es":{"q":"En Vermont, un conductor menor de 21 años viola la ley con un nivel de alcohol en la sangre de, ¿cuánto?","o":["0.08 o más","0.05 o más","0.10 o más","0.02 o más"],"h1":"Es mucho menor que el límite para adultos.","h2":"En Vermont, un conductor menor de 21 años con 0.02 o más de alcohol en la sangre comete una infracción, muy por debajo del límite de 0.08 para adultos.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 Vermont，21 岁以下的司机血液酒精浓度达到多少就违法？","o":["0.08 或以上","0.05 或以上","0.10 或以上","0.02 或以上"],"h1":"它比成年人的上限低很多。","h2":"在 Vermont，21 岁以下的司机血液酒精浓度达到 0.02 或以上就违法，远低于成年人的上限 0.08。","p":"对。21 岁以下，上限是 0.02。"},"vi":{"q":"Ở Vermont, người lái dưới 21 tuổi phạm luật khi nồng độ cồn trong máu là bao nhiêu?","o":["0.08 trở lên","0.05 trở lên","0.10 trở lên","0.02 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn cho người lớn.","h2":"Ở Vermont, người lái dưới 21 tuổi có nồng độ cồn trong máu từ 0.02 trở lên là phạm luật, thấp hơn nhiều so với giới hạn 0.08 cho người lớn.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa Vermont, lumalabag sa batas ang drayber na wala pang 21 kapag ang alak sa dugo ay ano?","o":["0.08 o higit pa","0.05 o higit pa","0.10 o higit pa","0.02 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa Vermont, ang drayber na wala pang 21 na may 0.02 o higit pang alak sa dugo ay lumalabag, mas mababa nang malaki kaysa sa limitasyon ng adulto na 0.08.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في Vermont، يخالف السائق الذي عمره أقل من 21 سنة القانون إذا كانت نسبة الكحول في دمه كم؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.10 أو أكثر","0.02 أو أكثر"],"h1":"إنها أقل بكثير من حدّ البالغين.","h2":"في Vermont، السائق الذي عمره أقل من 21 سنة ونسبة الكحول في دمه 0.02 أو أكثر يرتكب مخالفة، وهذا أقل بكثير من حدّ البالغين وهو 0.08.","p":"صحيح. تحت 21 سنة، الحدّ هو 0.02."},"ref":{"doc":"VT","page":52}},{"id":"vt-015","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what happens the first time a driver under 21 is caught at 0.02 or more?","o":["A warning letter only","A 30-day suspension","A 90-day license suspension","A one-week suspension"],"h1":"It lasts about three months.","h2":"Since July 2025, a Vermont driver under 21 caught at 0.02 or more loses the license for 90 days the first time, and for 180 days if they do not finish the required youth alcohol program.","p":"Right. A first violation means a 90-day suspension."},"es":{"q":"En Vermont, ¿qué pasa la primera vez que encuentran a un conductor menor de 21 años con 0.02 o más?","o":["Solo una carta de aviso","Una suspensión de 30 días","Una suspensión de la licencia de 90 días","Una suspensión de una semana"],"h1":"Dura unos tres meses.","h2":"Desde julio de 2025, un conductor menor de 21 años en Vermont con 0.02 o más pierde la licencia por 90 días la primera vez, y por 180 días si no termina el programa obligatorio para jóvenes sobre el alcohol.","p":"Correcto. La primera infracción significa una suspensión de 90 días."},"zh":{"q":"在 Vermont，21 岁以下的司机第一次被查到酒精浓度 0.02 或以上，会怎样？","o":["只收到警告信","吊销驾照 30 天","吊销驾照 90 天","吊销驾照一星期"],"h1":"大约三个月。","h2":"从 2025 年 7 月起，在 Vermont，21 岁以下的司机第一次被查到 0.02 或以上，驾照会被吊销 90 天；如果没有完成规定的青少年酒精课程，就是 180 天。","p":"对。第一次违规会吊销驾照 90 天。"},"vi":{"q":"Ở Vermont, lần đầu người lái dưới 21 tuổi bị bắt với nồng độ 0.02 trở lên thì sao?","o":["Chỉ nhận thư cảnh cáo","Bị treo bằng 30 ngày","Bị treo bằng lái 90 ngày","Bị treo bằng một tuần"],"h1":"Khoảng ba tháng.","h2":"Từ tháng 7 năm 2025, ở Vermont, người lái dưới 21 tuổi bị bắt lần đầu với nồng độ 0.02 trở lên sẽ mất bằng 90 ngày, và 180 ngày nếu không học xong chương trình về rượu bia cho người trẻ theo yêu cầu.","p":"Đúng. Vi phạm lần đầu là treo bằng 90 ngày."},"tl":{"q":"Sa Vermont, ano ang mangyayari sa unang beses na mahuli ang drayber na wala pang 21 na may 0.02 o higit pa?","o":["Sulat ng babala lamang","Suspensyon nang 30 araw","Suspensyon ng lisensya nang 90 araw","Suspensyon nang isang linggo"],"h1":"Tumatagal ito nang mga tatlong buwan.","h2":"Mula Hulyo 2025, ang drayber sa Vermont na wala pang 21 na nahuli na may 0.02 o higit pa ay mawawalan ng lisensya nang 90 araw sa unang beses, at 180 araw kung hindi niya tatapusin ang kinakailangang programa tungkol sa alak para sa kabataan.","p":"Tama. Ang unang paglabag ay suspensyon nang 90 araw."},"ar":{"q":"في Vermont، ماذا يحدث في المرة الأولى التي يُضبط فيها سائق عمره أقل من 21 سنة بنسبة 0.02 أو أكثر؟","o":["رسالة تحذير فقط","إيقاف لمدة 30 يومًا","إيقاف الرخصة لمدة 90 يومًا","إيقاف لمدة أسبوع"],"h1":"يستمر نحو ثلاثة أشهر.","h2":"منذ يوليو 2025، السائق في Vermont الذي عمره أقل من 21 سنة ويُضبط بنسبة 0.02 أو أكثر يفقد رخصته لمدة 90 يومًا في المرة الأولى، و180 يومًا إذا لم يُنهِ برنامج الكحول المطلوب للشباب.","p":"صحيح. المخالفة الأولى تعني إيقاف الرخصة لمدة 90 يومًا."},"ref":{"doc":"VT","page":null}},{"id":"vt-016","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, what is the highest speed allowed when no sign shows a different limit?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"It is lower than in many states.","h2":"Vermont law sets 50 mph as the maximum speed unless a different limit is posted, and you must go slower when conditions require.","p":"Right. Without a sign, the maximum is 50 mph."},"es":{"q":"En Vermont, ¿cuál es la velocidad máxima permitida cuando ningún letrero indica otro límite?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Es menor que en muchos estados.","h2":"La ley de Vermont fija 50 mph como velocidad máxima si no hay otro límite indicado, y usted debe ir más despacio cuando las condiciones lo exigen.","p":"Correcto. Sin letrero, el máximo es 50 mph."},"zh":{"q":"在 Vermont，没有标志显示别的限速时，最高车速是多少？","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"它比很多州的低。","h2":"Vermont 法律规定，除非标出别的限速，最高车速是 50 mph，路况需要时你还要开得更慢。","p":"对。没有标志时，最高 50 mph。"},"vi":{"q":"Ở Vermont, tốc độ cao nhất được phép là bao nhiêu khi không có bảng ghi giới hạn khác?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Nó thấp hơn so với nhiều tiểu bang.","h2":"Luật Vermont đặt 50 mph là tốc độ tối đa nếu không có bảng ghi giới hạn khác, và bạn phải chạy chậm hơn khi điều kiện đòi hỏi.","p":"Đúng. Không có bảng, tối đa là 50 mph."},"tl":{"q":"Sa Vermont, ano ang pinakamataas na bilis na pinapayagan kapag walang karatulang nagpapakita ng ibang limitasyon?","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"Mas mababa ito kaysa sa maraming estado.","h2":"Itinatakda ng batas ng Vermont ang 50 mph bilang pinakamataas na bilis maliban kung may nakapaskil na ibang limitasyon, at dapat kang bumagal kapag kailangan ng kondisyon.","p":"Tama. Kung walang karatula, ang pinakamataas ay 50 mph."},"ar":{"q":"في Vermont، ما أعلى سرعة مسموحة عندما لا توجد لافتة تُظهر حدًّا مختلفًا؟","o":["50 mph","55 mph","45 mph","65 mph"],"h1":"إنها أقل مما في ولايات كثيرة.","h2":"يحدّد قانون Vermont أن 50 mph هي السرعة القصوى إلا إذا وُضعت لافتة بحدّ مختلف، ويجب أن تقود أبطأ عندما تتطلّب الظروف ذلك.","p":"صحيح. بدون لافتة، السرعة القصوى 50 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-017","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, what is the highest speed limit on an Interstate?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"It is lower than in many western states.","h2":"The highest speed on a Vermont Interstate is 65 mph, unless a sign shows a lower limit.","p":"Right. Vermont Interstates top out at 65 mph."},"es":{"q":"En Vermont, ¿cuál es el límite de velocidad más alto en una autopista interestatal?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Es menor que en muchos estados del oeste.","h2":"La velocidad más alta en una autopista interestatal de Vermont es 65 mph, a menos que un letrero indique un límite menor.","p":"Correcto. En Vermont el máximo en las interestatales es 65 mph."},"zh":{"q":"在 Vermont，州际公路（Interstate）的最高限速是多少？","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"它比很多西部州的低。","h2":"Vermont 州际公路的最高车速是 65 mph，除非标志显示更低的限速。","p":"对。Vermont 州际公路最高 65 mph。"},"vi":{"q":"Ở Vermont, giới hạn tốc độ cao nhất trên xa lộ liên bang (Interstate) là bao nhiêu?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Nó thấp hơn so với nhiều tiểu bang miền tây.","h2":"Tốc độ cao nhất trên xa lộ liên bang ở Vermont là 65 mph, trừ khi có bảng ghi giới hạn thấp hơn.","p":"Đúng. Xa lộ liên bang ở Vermont tối đa 65 mph."},"tl":{"q":"Sa Vermont, ano ang pinakamataas na speed limit sa Interstate?","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"Mas mababa ito kaysa sa maraming estado sa kanluran.","h2":"Ang pinakamataas na bilis sa Interstate ng Vermont ay 65 mph, maliban kung may karatulang nagpapakita ng mas mababang limitasyon.","p":"Tama. Hanggang 65 mph lamang ang mga Interstate ng Vermont."},"ar":{"q":"في Vermont، ما أعلى حدّ للسرعة على الطريق السريع بين الولايات (Interstate)؟","o":["55 mph","75 mph","70 mph","65 mph"],"h1":"إنه أقل مما في ولايات غربية كثيرة.","h2":"أعلى سرعة على Interstate في Vermont هي 65 mph، إلا إذا أظهرت لافتة حدًّا أقل.","p":"صحيح. أقصى سرعة على Interstate في Vermont هي 65 mph."},"ref":{"doc":"VT","page":28}},{"id":"vt-018","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you approach a stopped police car, ambulance or tow truck with flashing lights. What must you do?","o":["Keep your speed and lane","Slow down and, if safe, move out of the lane next to it","Stop behind it until it leaves","Speed up to pass quickly"],"h1":"Give the people at the roadside more space and time.","h2":"Vermont's move over law says to slow down and, when it is safe, leave the lane closest to a stopped emergency or tow vehicle with flashing lights.","p":"Right. Slow down and move over when safe."},"es":{"q":"En Vermont, usted se acerca a una patrulla, ambulancia o grúa detenida con luces intermitentes. ¿Qué debe hacer?","o":["Mantener su velocidad y carril","Reducir la velocidad y, si es seguro, salir del carril junto a ella","Detenerse detrás hasta que se vaya","Acelerar para pasar rápido"],"h1":"Dé más espacio y tiempo a las personas al lado del camino.","h2":"La ley de Vermont dice que debe reducir la velocidad y, cuando sea seguro, salir del carril más cercano a un vehículo de emergencia o grúa detenido con luces intermitentes.","p":"Correcto. Reduzca la velocidad y cámbiese de carril si es seguro."},"zh":{"q":"在 Vermont，你开近一辆停着、闪着灯的警车、救护车或拖车。你必须怎么做？","o":["保持车速和车道","减速，安全时离开它旁边的车道","停在它后面等它开走","加速快点开过去"],"h1":"给路边的人更多空间和时间。","h2":"Vermont 的让道法（move over law）规定，要减速，安全时离开最靠近停着、闪着灯的紧急车辆或拖车的车道。","p":"对。减速，安全时换道让开。"},"vi":{"q":"Ở Vermont, bạn đến gần một xe cảnh sát, xe cứu thương hoặc xe kéo đang dừng và chớp đèn. Bạn phải làm gì?","o":["Giữ tốc độ và làn đường","Chạy chậm lại và, nếu an toàn, rời khỏi làn đường sát bên nó","Dừng phía sau cho đến khi nó đi","Tăng tốc để vượt nhanh"],"h1":"Hãy cho những người bên lề đường thêm khoảng trống và thời gian.","h2":"Luật tránh sang (move over law) của Vermont nói phải chạy chậm lại và, khi an toàn, rời khỏi làn đường gần nhất với xe khẩn cấp hoặc xe kéo đang dừng và chớp đèn.","p":"Đúng. Chạy chậm lại và tránh sang khi an toàn."},"tl":{"q":"Sa Vermont, papalapit ka sa nakahintong kotse ng pulis, ambulansya o tow truck na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at linya","Bumagal at, kung ligtas, lumipat mula sa linyang katabi nito","Huminto sa likod nito hanggang umalis ito","Bumilis para mabilis na lumampas"],"h1":"Bigyan ng mas maraming espasyo at oras ang mga tao sa gilid ng daan.","h2":"Sinasabi ng move over law ng Vermont na bumagal at, kapag ligtas, umalis sa linyang pinakamalapit sa nakahintong emergency vehicle o tow truck na may kumikislap na ilaw.","p":"Tama. Bumagal at lumipat ng linya kapag ligtas."},"ar":{"q":"في Vermont، تقترب من سيارة شرطة أو إسعاف أو سيارة سحب متوقفة وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك ومسارك","خفّف السرعة، وإذا كان آمنًا، ابتعد عن المسار المجاور لها","توقّف خلفها حتى تغادر","زِد السرعة لتتجاوزها بسرعة"],"h1":"أعطِ الناس على جانب الطريق مساحة ووقتًا أكثر.","h2":"قانون الابتعاد (move over law) في Vermont يقول أن تخفّف السرعة، وعندما يكون آمنًا، تترك المسار الأقرب إلى سيارة طوارئ أو سيارة سحب متوقفة وأضواؤها تومض.","p":"صحيح. خفّف السرعة وابتعد عندما يكون آمنًا."},"ref":{"doc":"VT","page":31}},{"id":"vt-019","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how long must you stay stopped for a school bus with flashing red lights?","o":["Until the red lights stop flashing","For 30 seconds","Until the door closes","Until you see no children"],"h1":"Watch the bus lights, not a clock.","h2":"In Vermont you must stay stopped as long as the school bus's red lights are flashing.","p":"Right. Stay stopped while the red lights flash."},"es":{"q":"En Vermont, ¿cuánto tiempo debe quedarse detenido ante un autobús escolar con luces rojas intermitentes?","o":["Hasta que las luces rojas dejen de parpadear","Durante 30 segundos","Hasta que se cierre la puerta","Hasta que no vea niños"],"h1":"Mire las luces del autobús, no el reloj.","h2":"En Vermont usted debe quedarse detenido mientras las luces rojas del autobús escolar estén parpadeando.","p":"Correcto. Quédese detenido mientras parpadean las luces rojas."},"zh":{"q":"在 Vermont，校车闪红灯时，你必须停多久？","o":["直到红灯不再闪","30 秒","直到车门关上","直到看不见孩子"],"h1":"看校车的灯，不是看时钟。","h2":"在 Vermont，只要校车的红灯在闪，你就必须一直停着。","p":"对。红灯闪着时一直停着。"},"vi":{"q":"Ở Vermont, bạn phải dừng bao lâu khi xe buýt học sinh chớp đèn đỏ?","o":["Cho đến khi đèn đỏ ngừng chớp","Trong 30 giây","Cho đến khi cửa xe đóng","Cho đến khi không thấy trẻ em"],"h1":"Hãy nhìn đèn xe buýt, không phải đồng hồ.","h2":"Ở Vermont, bạn phải dừng suốt thời gian đèn đỏ của xe buýt học sinh còn chớp.","p":"Đúng. Dừng khi đèn đỏ còn chớp."},"tl":{"q":"Sa Vermont, gaano katagal ka dapat nakahinto para sa school bus na may kumikislap na pulang ilaw?","o":["Hanggang tumigil ang pagkislap ng pulang ilaw","Nang 30 segundo","Hanggang sumara ang pinto","Hanggang wala ka nang makitang bata"],"h1":"Tingnan ang ilaw ng bus, hindi ang orasan.","h2":"Sa Vermont, dapat kang manatiling nakahinto habang kumikislap ang pulang ilaw ng school bus.","p":"Tama. Manatiling nakahinto habang kumikislap ang pulang ilaw."},"ar":{"q":"في Vermont، كم مدة يجب أن تبقى متوقفًا عند حافلة مدرسية أضواؤها الحمراء تومض؟","o":["حتى تتوقف الأضواء الحمراء عن الوميض","لمدة 30 ثانية","حتى يُغلق الباب","حتى لا ترى أطفالًا"],"h1":"راقب أضواء الحافلة، لا الساعة.","h2":"في Vermont يجب أن تبقى متوقفًا ما دامت الأضواء الحمراء للحافلة المدرسية تومض.","p":"صحيح. ابقَ متوقفًا ما دامت الأضواء الحمراء تومض."},"ref":{"doc":"VT","page":39}},{"id":"vt-020","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, a school bus with flashing red lights is stopped on the other roadway of a divided highway. What must you do?","o":["Stop until the lights turn off","Stop, then pass at 10 mph","You do not have to stop","Honk and pass slowly"],"h1":"A divided highway has separate roadways for each direction.","h2":"In Vermont, you do not have to stop for a school bus that is on a different roadway of a divided highway, but drive with care.","p":"Right. The other roadway of a divided highway does not have to stop."},"es":{"q":"En Vermont, un autobús escolar con luces rojas intermitentes está detenido en la otra calzada de una carretera dividida. ¿Qué debe hacer usted?","o":["Detenerse hasta que se apaguen las luces","Detenerse y luego pasar a 10 mph","No tiene que detenerse","Tocar la bocina y pasar despacio"],"h1":"Una carretera dividida tiene calzadas separadas para cada dirección.","h2":"En Vermont, usted no tiene que detenerse por un autobús escolar que está en otra calzada de una carretera dividida, pero maneje con cuidado.","p":"Correcto. La otra calzada de una carretera dividida no tiene que detenerse."},"zh":{"q":"在 Vermont，一辆闪红灯的校车停在分隔公路的另一边车道上。你必须怎么做？","o":["停车，直到灯熄灭","停车，然后以 10 mph 开过去","你不用停车","按喇叭，慢慢开过去"],"h1":"分隔公路的每个方向都有分开的路面。","h2":"在 Vermont，校车如果在分隔公路的另一边路面上，你不用停车，但要小心驾驶。","p":"对。分隔公路另一边的车不用停。"},"vi":{"q":"Ở Vermont, một xe buýt học sinh chớp đèn đỏ đang dừng ở phần đường bên kia của xa lộ có dải phân cách. Bạn phải làm gì?","o":["Dừng cho đến khi đèn tắt","Dừng, rồi vượt qua ở 10 mph","Bạn không phải dừng","Bấm còi và vượt chậm"],"h1":"Xa lộ có dải phân cách có phần đường riêng cho mỗi chiều.","h2":"Ở Vermont, bạn không phải dừng cho xe buýt học sinh ở phần đường khác của xa lộ có dải phân cách, nhưng phải lái cẩn thận.","p":"Đúng. Xe ở phần đường bên kia của xa lộ có dải phân cách không phải dừng."},"tl":{"q":"Sa Vermont, may school bus na may kumikislap na pulang ilaw na nakahinto sa kabilang daan ng divided highway. Ano ang dapat mong gawin?","o":["Huminto hanggang mamatay ang ilaw","Huminto, pagkatapos ay lumampas sa 10 mph","Hindi mo kailangang huminto","Bumusina at lumampas nang dahan-dahan"],"h1":"Ang divided highway ay may hiwalay na daan para sa bawat direksyon.","h2":"Sa Vermont, hindi mo kailangang huminto para sa school bus na nasa ibang daan ng divided highway, pero magmaneho nang maingat.","p":"Tama. Hindi kailangang huminto sa kabilang daan ng divided highway."},"ar":{"q":"في Vermont، حافلة مدرسية أضواؤها الحمراء تومض متوقفة على الطريق الآخر من طريق سريع مقسوم. ماذا يجب أن تفعل؟","o":["توقّف حتى تنطفئ الأضواء","توقّف، ثم تجاوز بسرعة 10 mph","ليس عليك أن تتوقف","استعمل البوق وتجاوز ببطء"],"h1":"الطريق المقسوم فيه طريق منفصل لكل اتجاه.","h2":"في Vermont، ليس عليك أن تتوقف لحافلة مدرسية على طريق مختلف من طريق سريع مقسوم، ولكن قُد بحذر.","p":"صحيح. الطريق الآخر من الطريق المقسوم ليس عليه أن يتوقف."},"ref":{"doc":"VT","page":40}},{"id":"vt-021","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how many points within two years start a license suspension?","o":["5 points","10 points","8 points","12 points"],"h1":"It is a round number.","h2":"In Vermont, 10 or more points within two years lead the Commissioner to suspend your license.","p":"Right. Ten points in two years starts a suspension."},"es":{"q":"En Vermont, ¿cuántos puntos en dos años inician una suspensión de la licencia?","o":["5 puntos","10 puntos","8 puntos","12 puntos"],"h1":"Es un número redondo.","h2":"En Vermont, 10 puntos o más en dos años llevan a que el Comisionado suspenda su licencia.","p":"Correcto. Diez puntos en dos años inician una suspensión."},"zh":{"q":"在 Vermont，两年内扣多少分会开始吊销驾照？","o":["5 分","10 分","8 分","12 分"],"h1":"它是个整数。","h2":"在 Vermont，两年内扣 10 分或以上，州长官（Commissioner）会吊销你的驾照。","p":"对。两年内 10 分就会开始吊销。"},"vi":{"q":"Ở Vermont, bao nhiêu điểm trong hai năm thì bắt đầu bị treo bằng lái?","o":["5 điểm","10 điểm","8 điểm","12 điểm"],"h1":"Đó là một số tròn.","h2":"Ở Vermont, từ 10 điểm trở lên trong hai năm thì Ủy viên (Commissioner) sẽ treo bằng lái của bạn.","p":"Đúng. Mười điểm trong hai năm là bắt đầu bị treo bằng."},"tl":{"q":"Sa Vermont, ilang puntos sa loob ng dalawang taon ang nagsisimula ng suspensyon ng lisensya?","o":["5 puntos","10 puntos","8 puntos","12 puntos"],"h1":"Ito ay buong bilang na madaling tandaan.","h2":"Sa Vermont, ang 10 o higit pang puntos sa loob ng dalawang taon ay nagiging dahilan para suspindihin ng Commissioner ang iyong lisensya.","p":"Tama. Sampung puntos sa dalawang taon ang nagsisimula ng suspensyon."},"ar":{"q":"في Vermont، كم نقطة خلال سنتين تبدأ إيقاف الرخصة؟","o":["5 نقاط","10 نقاط","8 نقاط","12 نقطة"],"h1":"إنه رقم مستدير.","h2":"في Vermont، 10 نقاط أو أكثر خلال سنتين تجعل المفوّض (Commissioner) يوقف رخصتك.","p":"صحيح. عشر نقاط في سنتين تبدأ الإيقاف."},"ref":{"doc":"VT","page":64}},{"id":"vt-022","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how long is the suspension for reaching 10 points?","o":["One year","90 days","30 days","10 days"],"h1":"The number of days matches the number of points.","h2":"Reaching 10 points in Vermont brings a 10-day suspension, and the time grows as points go up.","p":"Right. Ten points means a 10-day suspension."},"es":{"q":"En Vermont, ¿cuánto dura la suspensión por llegar a 10 puntos?","o":["Un año","90 días","30 días","10 días"],"h1":"El número de días es igual al número de puntos.","h2":"Llegar a 10 puntos en Vermont trae una suspensión de 10 días, y el tiempo aumenta con más puntos.","p":"Correcto. Diez puntos significan una suspensión de 10 días."},"zh":{"q":"在 Vermont，扣到 10 分会吊销驾照多久？","o":["一年","90 天","30 天","10 天"],"h1":"天数和分数一样。","h2":"在 Vermont，扣到 10 分会吊销驾照 10 天，分数越多，时间越长。","p":"对。10 分就是吊销 10 天。"},"vi":{"q":"Ở Vermont, khi đủ 10 điểm thì bị treo bằng bao lâu?","o":["Một năm","90 ngày","30 ngày","10 ngày"],"h1":"Số ngày bằng số điểm.","h2":"Ở Vermont, đủ 10 điểm sẽ bị treo bằng 10 ngày, và thời gian tăng lên khi điểm tăng.","p":"Đúng. Mười điểm là treo bằng 10 ngày."},"tl":{"q":"Sa Vermont, gaano katagal ang suspensyon kapag umabot ka sa 10 puntos?","o":["Isang taon","90 araw","30 araw","10 araw"],"h1":"Pareho ang bilang ng araw at ang bilang ng puntos.","h2":"Ang pag-abot sa 10 puntos sa Vermont ay nagdudulot ng 10 araw na suspensyon, at humahaba ang panahon habang dumarami ang puntos.","p":"Tama. Sampung puntos ay 10 araw na suspensyon."},"ar":{"q":"في Vermont، كم مدة الإيقاف عند الوصول إلى 10 نقاط؟","o":["سنة واحدة","90 يومًا","30 يومًا","10 أيام"],"h1":"عدد الأيام يساوي عدد النقاط.","h2":"الوصول إلى 10 نقاط في Vermont يجلب إيقافًا لمدة 10 أيام، وتزيد المدة كلما زادت النقاط.","p":"صحيح. عشر نقاط تعني إيقافًا لمدة 10 أيام."},"ref":{"doc":"VT","page":null}},{"id":"vt-023","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what is the minimum liability insurance for property damage?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"It is the smallest of the three required amounts.","h2":"Vermont requires at least $10,000 for property damage, with $25,000 per injured person and $50,000 per crash.","p":"Right. Property damage coverage must be at least $10,000."},"es":{"q":"En Vermont, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Es la menor de las tres cantidades exigidas.","h2":"Vermont exige por lo menos $10,000 por daños a la propiedad, con $25,000 por persona lesionada y $50,000 por choque.","p":"Correcto. La cobertura por daños a la propiedad debe ser de por lo menos $10,000."},"zh":{"q":"在 Vermont，财产损失的最低责任保险是多少？","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"它是三个必须金额中最小的。","h2":"Vermont 要求财产损失保险至少 $10,000，每个受伤的人 $25,000，每次车祸 $50,000。","p":"对。财产损失保险至少 $10,000。"},"vi":{"q":"Ở Vermont, bảo hiểm trách nhiệm tối thiểu cho thiệt hại tài sản là bao nhiêu?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Đó là số nhỏ nhất trong ba số tiền bắt buộc.","h2":"Vermont yêu cầu ít nhất $10,000 cho thiệt hại tài sản, $25,000 cho mỗi người bị thương và $50,000 cho mỗi vụ tai nạn.","p":"Đúng. Bảo hiểm thiệt hại tài sản phải ít nhất $10,000."},"tl":{"q":"Sa Vermont, ano ang pinakamababang liability insurance para sa pinsala sa ari-arian?","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"Ito ang pinakamaliit sa tatlong kinakailangang halaga.","h2":"Hinihingi ng Vermont ang hindi bababa sa $10,000 para sa pinsala sa ari-arian, $25,000 bawat taong nasaktan, at $50,000 bawat banggaan.","p":"Tama. Ang insurance sa pinsala sa ari-arian ay dapat hindi bababa sa $10,000."},"ar":{"q":"في Vermont، ما الحدّ الأدنى لتأمين المسؤولية عن أضرار الممتلكات؟","o":["$5,000","$25,000","$10,000","$15,000"],"h1":"إنه أصغر المبالغ الثلاثة المطلوبة.","h2":"تطلب Vermont على الأقل $10,000 لأضرار الممتلكات، و$25,000 لكل شخص مُصاب، و$50,000 لكل حادث.","p":"صحيح. تأمين أضرار الممتلكات يجب أن يكون $10,000 على الأقل."},"ref":{"doc":"VT","page":67}},{"id":"vt-024","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how many of the 20 questions on the learner's permit test must you answer correctly?","o":["16","14","18","12"],"h1":"You may miss four.","h2":"To pass the Vermont learner's permit test, you must answer at least 16 of the 20 questions correctly, which is 80 percent.","p":"Right. You need 16 correct answers out of 20."},"es":{"q":"En Vermont, ¿cuántas de las 20 preguntas del examen del permiso de aprendiz debe contestar bien?","o":["16","14","18","12"],"h1":"Puede fallar cuatro.","h2":"Para aprobar el examen del permiso de aprendiz en Vermont, debe contestar bien por lo menos 16 de las 20 preguntas, es decir, el 80 por ciento.","p":"Correcto. Necesita 16 respuestas correctas de 20."},"zh":{"q":"在 Vermont，学习驾照考试 20 道题中，你必须答对多少道？","o":["16","14","18","12"],"h1":"你可以错四道。","h2":"要通过 Vermont 学习驾照考试，你必须答对 20 道题中至少 16 道，也就是 80%。","p":"对。20 道题要答对 16 道。"},"vi":{"q":"Ở Vermont, trong 20 câu hỏi của bài thi giấy phép tập lái, bạn phải trả lời đúng bao nhiêu câu?","o":["16","14","18","12"],"h1":"Bạn được sai bốn câu.","h2":"Để đậu bài thi giấy phép tập lái ở Vermont, bạn phải trả lời đúng ít nhất 16 trong 20 câu, tức là 80 phần trăm.","p":"Đúng. Bạn cần 16 câu đúng trong 20 câu."},"tl":{"q":"Sa Vermont, ilan sa 20 tanong sa learner's permit test ang dapat mong masagot nang tama?","o":["16","14","18","12"],"h1":"Puwede kang magkamali ng apat.","h2":"Para pumasa sa learner's permit test ng Vermont, dapat mong masagot nang tama ang hindi bababa sa 16 sa 20 tanong, na 80 porsiyento.","p":"Tama. Kailangan mo ng 16 na tamang sagot sa 20."},"ar":{"q":"في Vermont، كم سؤالًا من الأسئلة الـ 20 في اختبار تصريح التعلّم يجب أن تجيب عنه إجابة صحيحة؟","o":["16","14","18","12"],"h1":"يمكنك أن تُخطئ في أربعة.","h2":"لكي تنجح في اختبار تصريح التعلّم في Vermont، يجب أن تجيب إجابة صحيحة عن 16 سؤالًا على الأقل من 20، أي 80 بالمئة.","p":"صحيح. تحتاج إلى 16 إجابة صحيحة من 20."},"ref":{"doc":"VT","page":18}},{"id":"vt-025","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, after a crash with an injury or more than $3,000 in damage, how soon must you send a written report to the DMV?","o":["Within 24 hours","Within 72 hours","Within 10 days","Within 30 days"],"h1":"It is three days.","h2":"In Vermont, a crash that hurts someone or causes more than $3,000 in damage must be reported to the DMV in writing within 72 hours.","p":"Right. Report it to the DMV within 72 hours."},"es":{"q":"En Vermont, después de un choque con un herido o con más de $3,000 en daños, ¿en cuánto tiempo debe enviar un reporte escrito al DMV?","o":["En 24 horas","En 72 horas","En 10 días","En 30 días"],"h1":"Son tres días.","h2":"En Vermont, un choque que hiere a alguien o causa más de $3,000 en daños se debe reportar por escrito al DMV en 72 horas.","p":"Correcto. Repórtelo al DMV en 72 horas."},"zh":{"q":"在 Vermont，发生有人受伤或损坏超过 $3,000 的车祸后，你必须在多长时间内向 DMV 交书面报告？","o":["24 小时内","72 小时内","10 天内","30 天内"],"h1":"是三天。","h2":"在 Vermont，造成有人受伤或损坏超过 $3,000 的车祸，必须在 72 小时内用书面形式报告给 DMV。","p":"对。在 72 小时内报告给 DMV。"},"vi":{"q":"Ở Vermont, sau một vụ tai nạn có người bị thương hoặc thiệt hại hơn $3,000, bạn phải gửi báo cáo bằng văn bản cho DMV trong bao lâu?","o":["Trong vòng 24 giờ","Trong vòng 72 giờ","Trong vòng 10 ngày","Trong vòng 30 ngày"],"h1":"Đó là ba ngày.","h2":"Ở Vermont, vụ tai nạn làm người khác bị thương hoặc gây thiệt hại hơn $3,000 phải được báo cáo bằng văn bản cho DMV trong vòng 72 giờ.","p":"Đúng. Báo cho DMV trong vòng 72 giờ."},"tl":{"q":"Sa Vermont, pagkatapos ng banggaan na may nasaktan o may pinsalang higit sa $3,000, gaano kabilis ka dapat magpadala ng nakasulat na report sa DMV?","o":["Sa loob ng 24 oras","Sa loob ng 72 oras","Sa loob ng 10 araw","Sa loob ng 30 araw"],"h1":"Tatlong araw ito.","h2":"Sa Vermont, ang banggaan na may nasaktan o may pinsalang higit sa $3,000 ay dapat i-report nang nakasulat sa DMV sa loob ng 72 oras.","p":"Tama. I-report ito sa DMV sa loob ng 72 oras."},"ar":{"q":"في Vermont، بعد حادث فيه إصابة أو ضرر بأكثر من $3,000، خلال كم من الوقت يجب أن ترسل تقريرًا مكتوبًا إلى الـ DMV؟","o":["خلال 24 ساعة","خلال 72 ساعة","خلال 10 أيام","خلال 30 يومًا"],"h1":"هي ثلاثة أيام.","h2":"في Vermont، الحادث الذي يُصيب شخصًا أو يسبب ضررًا بأكثر من $3,000 يجب التبليغ عنه كتابةً إلى الـ DMV خلال 72 ساعة.","p":"صحيح. بلّغ الـ DMV خلال 72 ساعة."},"ref":{"doc":"VT","page":58}},{"id":"vt-026","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what happens if a driver refuses a police officer's request for an alcohol or drug test?","o":["Nothing, the test is optional","A warning letter from the DMV","A 10-day suspension","Loss of the license for at least six months"],"h1":"Vermont has an Implied Consent law, so refusing has a real cost.","h2":"Under Vermont's Implied Consent law, a driver who refuses the alcohol or drug test loses the driver's license for at least six months.","p":"Right. Refusing the test means losing your license for at least six months."},"es":{"q":"En Vermont, ¿qué pasa si un conductor se niega cuando un policía le pide una prueba de alcohol o drogas?","o":["Nada, la prueba es opcional","Una carta de advertencia del DMV","Una suspensión de 10 días","Pierde la licencia por al menos seis meses"],"h1":"Vermont tiene una ley de Consentimiento Implícito, así que negarse tiene un costo real.","h2":"Bajo la ley de Consentimiento Implícito de Vermont, el conductor que se niega a la prueba de alcohol o drogas pierde su licencia por al menos seis meses.","p":"Correcto. Negarse a la prueba significa perder la licencia por al menos seis meses."},"zh":{"q":"在 Vermont，如果司机拒绝警察要求的酒精或药物检测，会怎样？","o":["没事，检测可以不做","DMV 寄来一封警告信","吊销驾照 10 天","失去驾照至少六个月"],"h1":"Vermont 有默示同意法（Implied Consent law），所以拒绝会有真正的后果。","h2":"根据 Vermont 的默示同意法（Implied Consent law），拒绝酒精或药物检测的司机会失去驾照至少六个月。","p":"对。拒绝检测就会失去驾照至少六个月。"},"vi":{"q":"Ở Vermont, điều gì xảy ra nếu tài xế từ chối yêu cầu kiểm tra rượu bia hoặc ma túy của cảnh sát?","o":["Không sao, kiểm tra là tùy ý","Một thư cảnh cáo từ DMV","Bị treo bằng 10 ngày","Mất bằng lái ít nhất sáu tháng"],"h1":"Vermont có luật Đồng Ý Ngầm (Implied Consent law), nên từ chối sẽ có hậu quả thật.","h2":"Theo luật Đồng Ý Ngầm (Implied Consent law) của Vermont, tài xế từ chối kiểm tra rượu bia hoặc ma túy sẽ mất bằng lái ít nhất sáu tháng.","p":"Đúng. Từ chối kiểm tra nghĩa là mất bằng lái ít nhất sáu tháng."},"tl":{"q":"Sa Vermont, ano ang mangyayari kung tumanggi ang drayber sa hiling ng pulis na magpa-test sa alak o droga?","o":["Wala, hindi sapilitan ang test","Isang sulat ng babala mula sa DMV","10 araw na suspensyon","Mawawala ang lisensya nang hindi bababa sa anim na buwan"],"h1":"May Implied Consent law ang Vermont, kaya may tunay na kapalit ang pagtanggi.","h2":"Ayon sa Implied Consent law ng Vermont, ang drayber na tumanggi sa test sa alak o droga ay mawawalan ng lisensya sa pagmamaneho nang hindi bababa sa anim na buwan.","p":"Tama. Kapag tumanggi sa test, mawawala ang lisensya mo nang hindi bababa sa anim na buwan."},"ar":{"q":"في Vermont، ماذا يحدث إذا رفض السائق طلب الشرطي إجراء فحص الكحول أو المخدرات؟","o":["لا شيء، الفحص اختياري","رسالة تحذير من DMV","إيقاف الرخصة 10 أيام","فقدان الرخصة ستة أشهر على الأقل"],"h1":"في Vermont قانون الموافقة الضمنية (Implied Consent law)، لذلك للرفض ثمن حقيقي.","h2":"بموجب قانون الموافقة الضمنية (Implied Consent law) في Vermont، السائق الذي يرفض فحص الكحول أو المخدرات يفقد رخصة القيادة ستة أشهر على الأقل.","p":"صحيح. رفض الفحص يعني فقدان رخصتك ستة أشهر على الأقل."},"ref":{"doc":"VT","page":53}},{"id":"vt-027","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, how must a child under 2 years old ride in a car?","o":["In a rear-facing car seat with a harness","In a booster seat with a lap belt","In a forward-facing seat in the front","On an adult's lap with a seat belt"],"h1":"The youngest children face the back of the car.","h2":"In Vermont, a child under two years old must ride in an approved rear-facing car seat with a harness, never in front of an active airbag.","p":"Right. Under 2, the child rides rear-facing in a harnessed car seat."},"es":{"q":"En Vermont, ¿cómo debe viajar en el carro un niño menor de 2 años?","o":["En un asiento de seguridad mirando hacia atrás, con arnés","En un asiento elevador con cinturón de cadera","En un asiento mirando hacia adelante, en el frente","En las piernas de un adulto con cinturón"],"h1":"Los niños más pequeños miran hacia la parte de atrás del carro.","h2":"En Vermont, un niño menor de dos años debe viajar en un asiento de seguridad aprobado, mirando hacia atrás y con arnés, nunca delante de una bolsa de aire activa.","p":"Correcto. Antes de los 2 años, el niño va mirando hacia atrás en un asiento con arnés."},"zh":{"q":"在 Vermont，不满 2 岁的孩子坐车时必须怎么坐？","o":["坐在带安全带束带的后向儿童座椅里","坐在增高座椅上，用腰部安全带","坐在前排的前向座椅里","坐在大人腿上，系安全带"],"h1":"最小的孩子要面朝车尾。","h2":"在 Vermont，不满两岁的孩子必须坐在合格的、带束带的后向儿童座椅里，绝不能放在开启的安全气囊前面。","p":"对。不满 2 岁，孩子要坐带束带的后向儿童座椅。"},"vi":{"q":"Ở Vermont, trẻ dưới 2 tuổi phải ngồi trên xe như thế nào?","o":["Trong ghế xe quay mặt về phía sau có dây đai","Trong ghế nâng với dây thắt lưng ngang hông","Trong ghế quay mặt về phía trước ở hàng ghế trước","Trên đùi người lớn có thắt dây an toàn"],"h1":"Trẻ nhỏ nhất quay mặt về phía sau xe.","h2":"Ở Vermont, trẻ dưới hai tuổi phải ngồi trong ghế xe quay mặt về phía sau được chấp thuận, có dây đai, và không bao giờ ngồi trước túi khí đang hoạt động.","p":"Đúng. Dưới 2 tuổi, trẻ ngồi ghế xe quay mặt về phía sau có dây đai."},"tl":{"q":"Sa Vermont, paano dapat sumakay sa kotse ang batang wala pang 2 taong gulang?","o":["Sa car seat na nakaharap sa likod at may harness","Sa booster seat na may lap belt","Sa upuang nakaharap sa unahan sa harap","Sa kandungan ng matanda na may seat belt"],"h1":"Nakaharap sa likod ng kotse ang pinakabatang mga bata.","h2":"Sa Vermont, ang batang wala pang dalawang taong gulang ay dapat sumakay sa aprubadong car seat na nakaharap sa likod at may harness, at hindi kailanman sa harap ng gumaganang airbag.","p":"Tama. Kapag wala pang 2 taon, nakaharap sa likod ang bata sa car seat na may harness."},"ar":{"q":"في Vermont، كيف يجب أن يركب الطفل الذي عمره أقل من 2 سنة في السيارة؟","o":["في مقعد سيارة مواجه للخلف مع أحزمة","في مقعد رافع مع حزام الحِجر","في مقعد مواجه للأمام في المقدمة","في حضن شخص بالغ مع حزام الأمان"],"h1":"أصغر الأطفال يواجهون مؤخرة السيارة.","h2":"في Vermont، يجب أن يركب الطفل الذي عمره أقل من سنتين في مقعد سيارة معتمد مواجه للخلف مع أحزمة، وأبدًا أمام وسادة هوائية تعمل.","p":"صحيح. تحت عمر 2، يركب الطفل في مقعد سيارة مواجه للخلف مع أحزمة."},"ref":{"doc":"VT","page":62}},{"id":"vt-028","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, you may not park within how many feet of a fire hydrant?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Vermont's distance is shorter than in many other states.","h2":"In Vermont, you may not park within 6 feet of a fire hydrant.","p":"Right. Stay at least 6 feet away."},"es":{"q":"En Vermont, ¿a menos de cuántos pies de un hidrante no puede estacionarse?","o":["15 pies","6 pies","20 pies","10 pies"],"h1":"La distancia de Vermont es más corta que en muchos otros estados.","h2":"En Vermont, no puede estacionarse a menos de 6 pies de un hidrante.","p":"Correcto. Quédese al menos a 6 pies."},"zh":{"q":"在 Vermont，你不能把车停在离消防栓多少英尺以内的地方？","o":["15 英尺","6 英尺","20 英尺","10 英尺"],"h1":"Vermont 的距离比很多其他州短。","h2":"在 Vermont，你不能把车停在离消防栓 6 英尺以内的地方。","p":"对。至少离开 6 英尺。"},"vi":{"q":"Ở Vermont, bạn không được đậu xe trong vòng bao nhiêu feet tính từ trụ cứu hỏa?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Khoảng cách ở Vermont ngắn hơn ở nhiều tiểu bang khác.","h2":"Ở Vermont, bạn không được đậu xe trong vòng 6 feet tính từ trụ cứu hỏa.","p":"Đúng. Hãy cách ra ít nhất 6 feet."},"tl":{"q":"Sa Vermont, hindi ka puwedeng mag-park sa loob ng ilang feet mula sa fire hydrant?","o":["15 feet","6 feet","20 feet","10 feet"],"h1":"Mas maikli ang layo sa Vermont kaysa sa maraming ibang estado.","h2":"Sa Vermont, hindi ka puwedeng mag-park sa loob ng 6 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 6 feet."},"ar":{"q":"في Vermont، لا يجوز لك أن تركن سيارتك على مسافة أقل من كم قدمًا من حنفية الإطفاء؟","o":["15 قدمًا","6 أقدام","20 قدمًا","10 أقدام"],"h1":"المسافة في Vermont أقصر منها في كثير من الولايات الأخرى.","h2":"في Vermont، لا يجوز لك أن تركن سيارتك على مسافة أقل من 6 أقدام من حنفية الإطفاء.","p":"صحيح. ابقَ بعيدًا 6 أقدام على الأقل."},"ref":{"doc":"VT","page":29}},{"id":"vt-029","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, your driver's license has expired. After how many days is it no longer valid for driving?","o":["30 days","60 days","90 days","14 days"],"h1":"It is about two weeks.","h2":"In Vermont, a license that has been expired for more than 14 days is not valid, and you may not drive with it.","p":"Right. After 14 days."},"es":{"q":"En Vermont, su licencia de conducir está vencida. ¿Después de cuántos días ya no es válida para manejar?","o":["30 días","60 días","90 días","14 días"],"h1":"Son unas dos semanas.","h2":"En Vermont, una licencia que lleva más de 14 días vencida no es válida y no puede manejar con ella.","p":"Correcto. Después de 14 días."},"zh":{"q":"在 Vermont，你的驾照过期了。过期多少天以后就不能再用来开车？","o":["30 天","60 天","90 天","14 天"],"h1":"大约是两个星期。","h2":"在 Vermont，驾照过期超过 14 天就无效了，你不能再用它开车。","p":"对。14 天以后。"},"vi":{"q":"Ở Vermont, bằng lái của bạn đã hết hạn. Sau bao nhiêu ngày thì bằng lái không còn dùng để lái xe được nữa?","o":["30 ngày","60 ngày","90 ngày","14 ngày"],"h1":"Khoảng hai tuần.","h2":"Ở Vermont, bằng lái đã hết hạn hơn 14 ngày thì không còn giá trị, và bạn không được lái xe với bằng lái đó.","p":"Đúng. Sau 14 ngày."},"tl":{"q":"Sa Vermont, expired na ang iyong lisensya sa pagmamaneho. Pagkalipas ng ilang araw ito hindi na puwedeng gamitin sa pagmamaneho?","o":["30 araw","60 araw","90 araw","14 araw"],"h1":"Mga dalawang linggo ito.","h2":"Sa Vermont, hindi na valid ang lisensyang expired nang higit sa 14 araw, at hindi ka puwedeng magmaneho gamit ito.","p":"Tama. Pagkalipas ng 14 araw."},"ar":{"q":"في Vermont، انتهت صلاحية رخصة القيادة الخاصة بك. بعد كم يومًا لا تعود صالحة للقيادة؟","o":["30 يومًا","60 يومًا","90 يومًا","14 يومًا"],"h1":"إنها نحو أسبوعين.","h2":"في Vermont، الرخصة التي انتهت صلاحيتها منذ أكثر من 14 يومًا لا تكون صالحة، ولا يجوز لك أن تقود بها.","p":"صحيح. بعد 14 يومًا."},"ref":{"doc":"VT","page":24}},{"id":"vt-030","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how much space should you leave when you pass a bicycle?","o":["At least 4 feet","At least 2 feet","At least 1 foot","At least 10 feet"],"h1":"Give more room than an arm's length.","h2":"In Vermont, you should leave at least four feet of space between your vehicle and a bicycle or vehicle you are passing.","p":"Right. At least four feet."},"es":{"q":"En Vermont, ¿cuánto espacio debe dejar al rebasar a una bicicleta?","o":["Al menos 4 pies","Al menos 2 pies","Al menos 1 pie","Al menos 10 pies"],"h1":"Deje más espacio que el largo de un brazo.","h2":"En Vermont, debe dejar al menos cuatro pies de espacio entre su vehículo y la bicicleta o el vehículo que rebasa.","p":"Correcto. Al menos cuatro pies."},"zh":{"q":"在 Vermont，你超过一辆自行车时，应该留出多少空间？","o":["至少 4 英尺","至少 2 英尺","至少 1 英尺","至少 10 英尺"],"h1":"留出的空间要比一只手臂的长度更多。","h2":"在 Vermont，你超过自行车或其他车辆时，你的车和它之间应该留出至少 4 英尺的空间。","p":"对。至少 4 英尺。"},"vi":{"q":"Ở Vermont, bạn nên chừa bao nhiêu khoảng trống khi vượt một chiếc xe đạp?","o":["Ít nhất 4 feet","Ít nhất 2 feet","Ít nhất 1 foot","Ít nhất 10 feet"],"h1":"Hãy chừa nhiều hơn chiều dài một cánh tay.","h2":"Ở Vermont, bạn nên chừa ít nhất 4 feet giữa xe của bạn và chiếc xe đạp hoặc xe mà bạn đang vượt.","p":"Đúng. Ít nhất 4 feet."},"tl":{"q":"Sa Vermont, gaano kalaking espasyo ang dapat mong iwan kapag nag-o-overtake ka sa bisikleta?","o":["Hindi bababa sa 4 feet","Hindi bababa sa 2 feet","Hindi bababa sa 1 foot","Hindi bababa sa 10 feet"],"h1":"Magbigay ng mas malaking espasyo kaysa sa haba ng isang braso.","h2":"Sa Vermont, dapat kang mag-iwan ng hindi bababa sa 4 feet na espasyo sa pagitan ng iyong sasakyan at ng bisikleta o sasakyang ino-overtake mo.","p":"Tama. Hindi bababa sa 4 feet."},"ar":{"q":"في Vermont، ما المسافة التي يجب أن تتركها عندما تتجاوز درّاجة هوائية؟","o":["4 أقدام على الأقل","قدمان على الأقل","قدم واحدة على الأقل","10 أقدام على الأقل"],"h1":"اترك مسافة أكبر من طول الذراع.","h2":"في Vermont، يجب أن تترك مسافة 4 أقدام على الأقل بين سيارتك والدرّاجة أو المركبة التي تتجاوزها.","p":"صحيح. 4 أقدام على الأقل."},"ref":{"doc":"VT","page":52}},{"id":"vt-031","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, the law says your headlights must be on when you cannot clearly see people or vehicles how far ahead?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Think of fog, heavy rain or heavy snow.","h2":"In Vermont, the law requires your headlights to be on whenever you cannot clearly see people or vehicles 500 feet ahead.","p":"Right. 500 feet."},"es":{"q":"En Vermont, la ley exige encender las luces cuando no puede ver con claridad a personas o vehículos a cierta distancia adelante. ¿Cuál es esa distancia?","o":["100 pies","250 pies","500 pies","1,000 pies"],"h1":"Piense en niebla, lluvia fuerte o nieve fuerte.","h2":"En Vermont, la ley exige tener las luces encendidas siempre que no pueda ver con claridad a personas o vehículos a 500 pies adelante.","p":"Correcto. 500 pies."},"zh":{"q":"在 Vermont，法律规定：当你看不清前方多远的人或车辆时，必须打开车头灯？","o":["100 英尺","250 英尺","500 英尺","1,000 英尺"],"h1":"想一想大雾、大雨或大雪的时候。","h2":"在 Vermont，法律规定，只要你看不清前方 500 英尺的人或车辆，就必须打开车头灯。","p":"对。500 英尺。"},"vi":{"q":"Ở Vermont, luật nói rằng bạn phải bật đèn pha khi không thể nhìn rõ người hoặc xe ở phía trước bao xa?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Hãy nghĩ đến sương mù, mưa lớn hoặc tuyết dày.","h2":"Ở Vermont, luật bắt buộc bạn phải bật đèn pha bất cứ khi nào bạn không thể nhìn rõ người hoặc xe ở phía trước 500 feet.","p":"Đúng. 500 feet."},"tl":{"q":"Sa Vermont, sinasabi ng batas na dapat nakabukas ang iyong headlights kapag hindi mo malinaw na makita ang mga tao o sasakyan sa unahan na gaano kalayo?","o":["100 feet","250 feet","500 feet","1,000 feet"],"h1":"Isipin ang makapal na fog, malakas na ulan o makapal na snow.","h2":"Sa Vermont, iniuutos ng batas na nakabukas ang iyong headlights tuwing hindi mo malinaw na makita ang mga tao o sasakyan na 500 feet sa unahan.","p":"Tama. 500 feet."},"ar":{"q":"في Vermont، يقول القانون إن مصابيحك الأمامية يجب أن تكون مضاءة عندما لا تستطيع أن ترى بوضوح الناس أو المركبات على أي مسافة أمامك؟","o":["100 قدم","250 قدمًا","500 قدم","1,000 قدم"],"h1":"فكّر في الضباب أو المطر الغزير أو الثلج الكثيف.","h2":"في Vermont، يفرض القانون أن تكون مصابيحك الأمامية مضاءة كلما لم تستطع أن ترى بوضوح الناس أو المركبات على بُعد 500 قدم أمامك.","p":"صحيح. 500 قدم."},"ref":{"doc":"VT","page":46}},{"id":"vt-032","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, after getting a junior operator's license, how long must a teen wait before driving as part of a job, such as delivering pizza?","o":["No wait; it is allowed right away","Three months","One year, or until age 18 if that comes first","Six months"],"h1":"The wait is longer than the passenger limits.","h2":"In Vermont, a junior operator may not drive for work until holding the license for one year or turning 18, whichever comes first.","p":"Right. One year, or age 18 if sooner."},"es":{"q":"En Vermont, después de obtener la licencia de operador menor, ¿cuánto tiempo debe esperar un adolescente antes de manejar como parte de un trabajo, por ejemplo repartiendo pizza?","o":["No hay espera; se permite enseguida","Tres meses","Un año, o hasta cumplir 18 si eso pasa antes","Seis meses"],"h1":"La espera es más larga que los límites de pasajeros.","h2":"En Vermont, un operador menor no puede manejar por trabajo hasta tener la licencia un año o cumplir 18 años, lo que ocurra primero.","p":"Correcto. Un año, o los 18 años si llegan antes."},"zh":{"q":"在 Vermont，拿到青少年驾照后，青少年要等多久才能为工作开车，比如送披萨？","o":["不用等，马上就可以","三个月","一年，或者到 18 岁，以先到者为准","六个月"],"h1":"等的时间比乘客限制的时间更长。","h2":"在 Vermont，青少年司机要持有驾照满一年或年满 18 岁（以先到者为准），才可以为工作开车。","p":"对。一年，或者如果更早的话到 18 岁。"},"vi":{"q":"Ở Vermont, sau khi có bằng lái thiếu niên, thiếu niên phải chờ bao lâu mới được lái xe để làm việc, ví dụ như giao pizza?","o":["Không phải chờ; được phép ngay","Ba tháng","Một năm, hoặc đến 18 tuổi nếu điều đó đến trước","Sáu tháng"],"h1":"Thời gian chờ dài hơn so với giới hạn hành khách.","h2":"Ở Vermont, người có bằng lái thiếu niên không được lái xe để làm việc cho đến khi có bằng được một năm hoặc đủ 18 tuổi, tùy điều nào đến trước.","p":"Đúng. Một năm, hoặc 18 tuổi nếu sớm hơn."},"tl":{"q":"Sa Vermont, pagkatapos makakuha ng lisensya ng batang drayber, gaano katagal dapat maghintay ang tinedyer bago magmaneho bilang bahagi ng trabaho, gaya ng pagdedeliver ng pizza?","o":["Walang hintay; puwede agad","Tatlong buwan","Isang taon, o hanggang edad 18 kung iyon ang mauna","Anim na buwan"],"h1":"Mas mahaba ang paghihintay kaysa sa mga limitasyon sa pasahero.","h2":"Sa Vermont, hindi puwedeng magmaneho para sa trabaho ang batang drayber hanggang hawak na niya ang lisensya nang isang taon o umabot siya sa edad 18, alinman ang mauna.","p":"Tama. Isang taon, o edad 18 kung mas maaga."},"ar":{"q":"في Vermont، بعد الحصول على رخصة السائق الصغير، كم يجب أن ينتظر المراهق قبل أن يقود كجزء من عمل، مثل توصيل البيتزا؟","o":["لا انتظار؛ مسموح فورًا","ثلاثة أشهر","سنة واحدة، أو حتى عمر 18 سنة إذا جاء ذلك أولًا","ستة أشهر"],"h1":"الانتظار أطول من قيود الركّاب.","h2":"في Vermont، لا يجوز للسائق الصغير أن يقود من أجل العمل حتى يحمل الرخصة سنة واحدة أو يبلغ 18 سنة، أيّهما يأتي أولًا.","p":"صحيح. سنة واحدة، أو عمر 18 سنة إذا جاء قبل ذلك."},"ref":{"doc":"VT","page":15}},{"id":"vt-033","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator's license is recalled for 90 days after how many points in total?","o":["4 points","6 points","10 points","12 points"],"h1":"It is fewer than the 10 points that start a regular suspension.","h2":"In Vermont, a junior operator who reaches 6 points in total, or gets a single 3-point speeding ticket, has the license recalled for 90 days.","p":"Right. Six points means a 90-day recall."},"es":{"q":"En Vermont, ¿con cuántos puntos en total le retiran la licencia de operador menor por 90 días?","o":["4 puntos","6 puntos","10 puntos","12 puntos"],"h1":"Son menos que los 10 puntos que inician una suspensión normal.","h2":"En Vermont, a un operador menor que llega a 6 puntos en total, o que recibe una sola multa de velocidad de 3 puntos, le retiran la licencia por 90 días.","p":"Correcto. Seis puntos significan retirar la licencia por 90 días."},"zh":{"q":"在 Vermont，青少年驾照总共扣到多少分会被收回 90 天？","o":["4 分","6 分","10 分","12 分"],"h1":"它比开始普通吊销的 10 分要少。","h2":"在 Vermont，青少年司机总共扣到 6 分，或者一张超速罚单就扣 3 分，驾照会被收回 90 天。","p":"对。6 分会被收回驾照 90 天。"},"vi":{"q":"Ở Vermont, bằng lái thiếu niên bị thu hồi 90 ngày sau khi bị tổng cộng bao nhiêu điểm?","o":["4 điểm","6 điểm","10 điểm","12 điểm"],"h1":"Ít hơn 10 điểm bắt đầu việc treo bằng thông thường.","h2":"Ở Vermont, người có bằng lái thiếu niên bị tổng cộng 6 điểm, hoặc chỉ một vé phạt chạy quá tốc độ 3 điểm, sẽ bị thu hồi bằng lái 90 ngày.","p":"Đúng. Sáu điểm là bị thu hồi 90 ngày."},"tl":{"q":"Sa Vermont, binabawi ang lisensya ng batang drayber nang 90 araw pagkatapos ng ilang puntos sa kabuuan?","o":["4 puntos","6 puntos","10 puntos","12 puntos"],"h1":"Mas kaunti ito sa 10 puntos na nagsisimula ng karaniwang suspensyon.","h2":"Sa Vermont, ang batang drayber na umabot sa 6 na puntos sa kabuuan, o nakakuha ng isang tiket sa sobrang bilis na may 3 puntos, ay babawian ng lisensya nang 90 araw.","p":"Tama. Ang anim na puntos ay pagbawi nang 90 araw."},"ar":{"q":"في Vermont، تُسحب رخصة السائق الصغير لمدة 90 يومًا بعد كم نقطة في المجموع؟","o":["4 نقاط","6 نقاط","10 نقاط","12 نقطة"],"h1":"إنها أقل من الـ 10 نقاط التي تبدأ الإيقاف العادي.","h2":"في Vermont، السائق الصغير الذي يصل إلى 6 نقاط في المجموع، أو يحصل على مخالفة سرعة واحدة بـ 3 نقاط، تُسحب رخصته لمدة 90 يومًا.","p":"صحيح. 6 نقاط تعني سحب الرخصة لمدة 90 يومًا."},"ref":{"doc":"VT","page":21}},{"id":"vt-034","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how long is a junior operator's license recalled for texting while driving?","o":["30 days","7 days","90 days","One year"],"h1":"It is about one month.","h2":"In Vermont, a junior operator caught texting while driving has the license recalled for 30 days, and also gets a fine and points.","p":"Right. Texting means a 30-day recall."},"es":{"q":"En Vermont, ¿por cuánto tiempo le retiran la licencia a un operador menor por enviar mensajes de texto mientras maneja?","o":["30 días","7 días","90 días","Un año"],"h1":"Es más o menos un mes.","h2":"En Vermont, a un operador menor que envía mensajes de texto mientras maneja le retiran la licencia por 30 días, y además recibe una multa y puntos.","p":"Correcto. Los mensajes de texto significan retirar la licencia por 30 días."},"zh":{"q":"在 Vermont，青少年司机开车时发短信，驾照会被收回多久？","o":["30 天","7 天","90 天","一年"],"h1":"大约一个月。","h2":"在 Vermont，青少年司机开车时发短信被抓到，驾照会被收回 30 天，还会被罚款和扣分。","p":"对。发短信会被收回驾照 30 天。"},"vi":{"q":"Ở Vermont, bằng lái thiếu niên bị thu hồi bao lâu vì nhắn tin khi lái xe?","o":["30 ngày","7 ngày","90 ngày","Một năm"],"h1":"Khoảng một tháng.","h2":"Ở Vermont, người có bằng lái thiếu niên bị bắt gặp nhắn tin khi lái xe sẽ bị thu hồi bằng lái 30 ngày, và còn bị phạt tiền và bị điểm.","p":"Đúng. Nhắn tin là bị thu hồi 30 ngày."},"tl":{"q":"Sa Vermont, gaano katagal binabawi ang lisensya ng batang drayber dahil sa pag-text habang nagmamaneho?","o":["30 araw","7 araw","90 araw","Isang taon"],"h1":"Mga isang buwan ito.","h2":"Sa Vermont, ang batang drayber na nahuling nagte-text habang nagmamaneho ay babawian ng lisensya nang 30 araw, at magkakaroon din ng multa at puntos.","p":"Tama. Ang pag-text ay pagbawi nang 30 araw."},"ar":{"q":"في Vermont، كم مدة سحب رخصة السائق الصغير بسبب كتابة الرسائل أثناء القيادة؟","o":["30 يومًا","7 أيام","90 يومًا","سنة واحدة"],"h1":"إنها حوالي شهر واحد.","h2":"في Vermont، السائق الصغير الذي يُضبط وهو يكتب الرسائل أثناء القيادة تُسحب رخصته لمدة 30 يومًا، ويحصل أيضًا على غرامة ونقاط.","p":"صحيح. كتابة الرسائل تعني سحب الرخصة لمدة 30 يومًا."},"ref":{"doc":"VT","page":21}},{"id":"vt-035","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, you move here with a valid license from another state. How soon must you get a Vermont license?","o":["Within 10 days","Within 30 days","Within 1 year","Within 60 days"],"h1":"It is about two months.","h2":"A new Vermont resident with a valid license from another state must get a Vermont license within 60 days of moving in.","p":"Right. Within 60 days."},"es":{"q":"En Vermont, usted se muda aquí con una licencia válida de otro estado. ¿En cuánto tiempo debe obtener una licencia de Vermont?","o":["En 10 días","En 30 días","En 1 año","En 60 días"],"h1":"Son unos dos meses.","h2":"Un nuevo residente de Vermont con una licencia válida de otro estado debe obtener una licencia de Vermont en los 60 días después de mudarse.","p":"Correcto. En 60 días."},"zh":{"q":"在 Vermont，你持有其他州的有效驾照搬来这里。你必须在多久内拿到 Vermont 驾照？","o":["10 天内","30 天内","1 年内","60 天内"],"h1":"大约两个月。","h2":"持有其他州有效驾照的 Vermont 新居民，必须在搬来后 60 天内拿到 Vermont 驾照。","p":"对。60 天内。"},"vi":{"q":"Ở Vermont, bạn chuyển đến đây với bằng lái còn hiệu lực của tiểu bang khác. Bạn phải lấy bằng lái Vermont trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 1 năm","Trong vòng 60 ngày"],"h1":"Khoảng hai tháng.","h2":"Cư dân mới của Vermont có bằng lái còn hiệu lực của tiểu bang khác phải lấy bằng lái Vermont trong vòng 60 ngày sau khi chuyển đến.","p":"Đúng. Trong vòng 60 ngày."},"tl":{"q":"Sa Vermont, lumipat ka rito na may valid na lisensya mula sa ibang estado. Gaano kabilis ka dapat kumuha ng lisensya ng Vermont?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 1 taon","Sa loob ng 60 araw"],"h1":"Mga dalawang buwan ito.","h2":"Ang bagong residente ng Vermont na may valid na lisensya mula sa ibang estado ay dapat kumuha ng lisensya ng Vermont sa loob ng 60 araw mula nang lumipat.","p":"Tama. Sa loob ng 60 araw."},"ar":{"q":"في Vermont، انتقلت إلى هنا ومعك رخصة سارية من ولاية أخرى. خلال كم من الوقت يجب أن تحصل على رخصة Vermont؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال سنة واحدة (1)","خلال 60 يومًا"],"h1":"إنها حوالي شهرين.","h2":"يجب على المقيم الجديد في Vermont الذي معه رخصة سارية من ولاية أخرى أن يحصل على رخصة Vermont خلال 60 يومًا من انتقاله.","p":"صحيح. خلال 60 يومًا."},"ref":{"doc":"VT","page":12}},{"id":"vt-036","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you fail the road test for the first time. How long must you wait before you take it again?","o":["One day","At least one week","Three months","Six months"],"h1":"It is longer than the wait after a failed written test.","h2":"In Vermont, after you fail the road test you must wait at least one week before you try again.","p":"Right. Wait at least one week."},"es":{"q":"En Vermont, usted reprueba el examen de manejo por primera vez. ¿Cuánto tiempo debe esperar para tomarlo otra vez?","o":["Un día","Por lo menos una semana","Tres meses","Seis meses"],"h1":"Es más que la espera después de reprobar el examen escrito.","h2":"En Vermont, después de reprobar el examen de manejo debe esperar por lo menos una semana para intentarlo otra vez.","p":"Correcto. Espere por lo menos una semana."},"zh":{"q":"在 Vermont，你第一次路考没通过。你要等多久才能再考？","o":["一天","至少一周","三个月","六个月"],"h1":"它比笔试没通过后等的时间更长。","h2":"在 Vermont，路考没通过后，你必须至少等一周才能再考。","p":"对。至少等一周。"},"vi":{"q":"Ở Vermont, bạn thi lái xe trên đường (road test) bị rớt lần đầu. Bạn phải chờ bao lâu mới được thi lại?","o":["Một ngày","Ít nhất một tuần","Ba tháng","Sáu tháng"],"h1":"Lâu hơn thời gian chờ sau khi rớt bài thi viết.","h2":"Ở Vermont, sau khi rớt bài thi lái xe trên đường, bạn phải chờ ít nhất một tuần mới được thi lại.","p":"Đúng. Chờ ít nhất một tuần."},"tl":{"q":"Sa Vermont, bumagsak ka sa road test sa unang pagkakataon. Gaano katagal ka dapat maghintay bago kumuha ulit?","o":["Isang araw","Hindi bababa sa isang linggo","Tatlong buwan","Anim na buwan"],"h1":"Mas mahaba ito kaysa sa paghihintay pagkatapos bumagsak sa nakasulat na pagsusulit.","h2":"Sa Vermont, pagkatapos mong bumagsak sa road test, dapat kang maghintay nang hindi bababa sa isang linggo bago sumubok ulit.","p":"Tama. Maghintay nang hindi bababa sa isang linggo."},"ar":{"q":"في Vermont، رسبت في اختبار القيادة على الطريق لأول مرة. كم يجب أن تنتظر قبل أن تأخذه مرة أخرى؟","o":["يوم واحد","أسبوع واحد على الأقل","ثلاثة أشهر","ستة أشهر"],"h1":"إنه أطول من الانتظار بعد الرسوب في الاختبار المكتوب.","h2":"في Vermont، بعد أن ترسب في اختبار القيادة على الطريق يجب أن تنتظر أسبوعًا واحدًا على الأقل قبل أن تحاول مرة أخرى.","p":"صحيح. انتظر أسبوعًا واحدًا على الأقل."},"ref":{"doc":"VT","page":19}},{"id":"vt-037","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, how many points go on your license for passing a stopped school bus with its red lights flashing?","o":["2 points","4 points","5 points","10 points"],"h1":"It is the same as for not yielding to an ambulance or fire truck.","h2":"In Vermont, passing a stopped school bus with its red lights on adds 5 points to your license, along with a large fine.","p":"Right. It costs 5 points."},"es":{"q":"En Vermont, ¿cuántos puntos recibe en su licencia por rebasar un autobús escolar detenido con las luces rojas intermitentes?","o":["2 puntos","4 puntos","5 puntos","10 puntos"],"h1":"Es lo mismo que por no ceder el paso a una ambulancia o un camión de bomberos.","h2":"En Vermont, rebasar un autobús escolar detenido con las luces rojas encendidas suma 5 puntos a su licencia, además de una multa grande.","p":"Correcto. Cuesta 5 puntos."},"zh":{"q":"在 Vermont，超过停着、闪着红灯的校车，驾照会被扣多少分？","o":["2 分","4 分","5 分","10 分"],"h1":"和不给救护车或消防车让路扣的分一样。","h2":"在 Vermont，超过停着、亮着红灯的校车，驾照会被扣 5 分，还会被重罚。","p":"对。会被扣 5 分。"},"vi":{"q":"Ở Vermont, vượt qua xe buýt học sinh đang dừng và chớp đèn đỏ thì bằng lái bị bao nhiêu điểm?","o":["2 điểm","4 điểm","5 điểm","10 điểm"],"h1":"Bằng với lỗi không nhường đường cho xe cứu thương hoặc xe cứu hỏa.","h2":"Ở Vermont, vượt qua xe buýt học sinh đang dừng và bật đèn đỏ sẽ bị thêm 5 điểm vào bằng lái, cùng với một khoản phạt lớn.","p":"Đúng. Bị 5 điểm."},"tl":{"q":"Sa Vermont, ilang puntos ang ilalagay sa lisensya mo dahil sa paglampas sa nakahintong school bus na may kumikislap na pulang ilaw?","o":["2 puntos","4 puntos","5 puntos","10 puntos"],"h1":"Pareho ito sa hindi pagbibigay-daan sa ambulansya o trak ng bumbero.","h2":"Sa Vermont, ang paglampas sa nakahintong school bus na nakabukas ang pulang ilaw ay nagdadagdag ng 5 puntos sa lisensya mo, kasama ang malaking multa.","p":"Tama. 5 puntos ito."},"ar":{"q":"في Vermont، كم نقطة تُضاف إلى رخصتك إذا تجاوزت حافلة مدرسية متوقفة وأضواؤها الحمراء تومض؟","o":["نقطتان (2)","4 نقاط","5 نقاط","10 نقاط"],"h1":"إنه نفس عدد النقاط لعدم إفساح الطريق لسيارة إسعاف أو سيارة إطفاء.","h2":"في Vermont، تجاوز حافلة مدرسية متوقفة وأضواؤها الحمراء مضاءة يضيف 5 نقاط إلى رخصتك، مع غرامة كبيرة.","p":"صحيح. يكلّفك ذلك 5 نقاط."},"ref":{"doc":"VT","page":40}},{"id":"vt-038","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, a police officer stops you and you have no car insurance. Besides a fine, how many points go on your record?","o":["2 points","No points","6 points","10 points"],"h1":"It is the same as for running a stop sign.","h2":"In Vermont, driving without insurance brings a ticket, a fine and 2 points on your driving record.","p":"Right. A fine and 2 points."},"es":{"q":"En Vermont, un policía lo detiene y usted no tiene seguro de auto. Además de una multa, ¿cuántos puntos recibe en su historial?","o":["2 puntos","Ningún punto","6 puntos","10 puntos"],"h1":"Es lo mismo que por no parar en una señal de alto.","h2":"En Vermont, manejar sin seguro trae una multa de tránsito y 2 puntos en su historial de manejo.","p":"Correcto. Una multa y 2 puntos."},"zh":{"q":"在 Vermont，警察拦下你，你没有汽车保险。除了罚款，你的记录上会被扣多少分？","o":["2 分","不扣分","6 分","10 分"],"h1":"和闯停车标志扣的分一样。","h2":"在 Vermont，没有保险开车会收到罚单、被罚款，驾驶记录上还会被扣 2 分。","p":"对。罚款加 2 分。"},"vi":{"q":"Ở Vermont, cảnh sát chặn xe bạn và bạn không có bảo hiểm xe. Ngoài tiền phạt, hồ sơ của bạn bị bao nhiêu điểm?","o":["2 điểm","Không bị điểm","6 điểm","10 điểm"],"h1":"Bằng với lỗi chạy qua bảng dừng (stop sign).","h2":"Ở Vermont, lái xe không có bảo hiểm sẽ bị phạt vé, phạt tiền và bị 2 điểm trong hồ sơ lái xe.","p":"Đúng. Phạt tiền và 2 điểm."},"tl":{"q":"Sa Vermont, pinahinto ka ng pulis at wala kang insurance ng kotse. Bukod sa multa, ilang puntos ang ilalagay sa rekord mo?","o":["2 puntos","Walang puntos","6 na puntos","10 puntos"],"h1":"Pareho ito sa hindi paghinto sa STOP sign.","h2":"Sa Vermont, ang pagmamaneho nang walang insurance ay may tiket, multa at 2 puntos sa rekord mo sa pagmamaneho.","p":"Tama. Multa at 2 puntos."},"ar":{"q":"في Vermont، أوقفك شرطي وليس معك تأمين للسيارة. بالإضافة إلى الغرامة، كم نقطة تُضاف إلى سجلّك؟","o":["نقطتان (2)","لا نقاط","6 نقاط","10 نقاط"],"h1":"إنه نفس عدد النقاط لعدم التوقف عند لافتة التوقف (STOP).","h2":"في Vermont، القيادة بدون تأمين تجلب مخالفة وغرامة ونقطتين (2) على سجلّ القيادة الخاص بك.","p":"صحيح. غرامة ونقطتان (2)."},"ref":{"doc":"VT","page":67}},{"id":"vt-039","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you have insurance but cannot show the card when a police officer stops you. How long do you have to show it?","o":["24 hours","15 days","60 days","90 days"],"h1":"It is about two weeks.","h2":"In Vermont, if you are insured but cannot show your card to the officer, you have 15 days to show proof that you were insured on the day you were stopped.","p":"Right. You have 15 days."},"es":{"q":"En Vermont, usted tiene seguro pero no puede mostrar la tarjeta cuando un policía lo detiene. ¿Cuánto tiempo tiene para mostrarla?","o":["24 horas","15 días","60 días","90 días"],"h1":"Son unas dos semanas.","h2":"En Vermont, si tiene seguro pero no puede mostrar su tarjeta al policía, tiene 15 días para mostrar prueba de que tenía seguro el día que lo detuvieron.","p":"Correcto. Tiene 15 días."},"zh":{"q":"在 Vermont，你有保险，但警察拦下你时你拿不出保险卡。你有多长时间出示它？","o":["24 小时","15 天","60 天","90 天"],"h1":"大约两周。","h2":"在 Vermont，如果你有保险但拿不出保险卡给警察看，你有 15 天时间出示证明，证明你被拦下那天有保险。","p":"对。你有 15 天。"},"vi":{"q":"Ở Vermont, bạn có bảo hiểm nhưng không xuất trình được thẻ khi cảnh sát chặn xe. Bạn có bao lâu để xuất trình?","o":["24 giờ","15 ngày","60 ngày","90 ngày"],"h1":"Khoảng hai tuần.","h2":"Ở Vermont, nếu bạn có bảo hiểm nhưng không xuất trình được thẻ cho cảnh sát, bạn có 15 ngày để đưa ra bằng chứng rằng bạn có bảo hiểm vào ngày bị chặn xe.","p":"Đúng. Bạn có 15 ngày."},"tl":{"q":"Sa Vermont, may insurance ka pero hindi mo maipakita ang card kapag pinahinto ka ng pulis. Gaano katagal ka para ipakita ito?","o":["24 oras","15 araw","60 araw","90 araw"],"h1":"Mga dalawang linggo ito.","h2":"Sa Vermont, kung may insurance ka pero hindi mo maipakita ang card sa pulis, may 15 araw ka para magpakita ng patunay na may insurance ka noong araw na pinahinto ka.","p":"Tama. May 15 araw ka."},"ar":{"q":"في Vermont، معك تأمين لكن لا تستطيع إظهار البطاقة عندما يوقفك شرطي. كم لديك من الوقت لإظهارها؟","o":["24 ساعة","15 يومًا","60 يومًا","90 يومًا"],"h1":"إنها حوالي أسبوعين.","h2":"في Vermont، إذا كان معك تأمين لكن لا تستطيع إظهار بطاقتك للشرطي، فلديك 15 يومًا لتُظهر إثباتًا أنك كنت مؤمَّنًا في اليوم الذي أُوقفت فيه.","p":"صحيح. لديك 15 يومًا."},"ref":{"doc":"VT","page":67}},{"id":"vt-040","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what vision level must you meet at the DMV eye screening, or be sent to an eye doctor?","o":["20/20","20/70","20/100","20/40"],"h1":"It is the same standard used in many states.","h2":"In Vermont, if your vision does not meet the 20/40 standard at the screening, you are sent to an eye doctor for more testing.","p":"Right. The standard is 20/40."},"es":{"q":"En Vermont, ¿qué nivel de visión debe tener en la prueba de la vista del DMV para que no lo envíen a un oculista?","o":["20/20","20/70","20/100","20/40"],"h1":"Es el mismo estándar que usan muchos estados.","h2":"En Vermont, si su visión no llega al estándar de 20/40 en la prueba, lo envían a un oculista para más exámenes.","p":"Correcto. El estándar es 20/40."},"zh":{"q":"在 Vermont，在 DMV 视力检查时你必须达到什么视力，否则会被转到眼科医生那里？","o":["20/20","20/70","20/100","20/40"],"h1":"很多州都用这个标准。","h2":"在 Vermont，如果你在检查时视力达不到 20/40 的标准，你会被转到眼科医生那里做更多检查。","p":"对。标准是 20/40。"},"vi":{"q":"Ở Vermont, bạn phải đạt mức thị lực nào khi kiểm tra mắt ở DMV, nếu không sẽ bị gửi đến bác sĩ mắt?","o":["20/20","20/70","20/100","20/40"],"h1":"Đó là tiêu chuẩn được dùng ở nhiều tiểu bang.","h2":"Ở Vermont, nếu thị lực của bạn không đạt tiêu chuẩn 20/40 khi kiểm tra, bạn sẽ được gửi đến bác sĩ mắt để kiểm tra thêm.","p":"Đúng. Tiêu chuẩn là 20/40."},"tl":{"q":"Sa Vermont, anong antas ng paningin ang dapat mong maabot sa eye screening ng DMV, o ipapadala ka sa doktor sa mata?","o":["20/20","20/70","20/100","20/40"],"h1":"Ito ang parehong pamantayan na ginagamit sa maraming estado.","h2":"Sa Vermont, kung hindi umabot ang paningin mo sa pamantayang 20/40 sa screening, ipapadala ka sa doktor sa mata para sa dagdag na pagsusuri.","p":"Tama. Ang pamantayan ay 20/40."},"ar":{"q":"في Vermont، ما مستوى النظر الذي يجب أن تصل إليه في فحص النظر في DMV، وإلا تُرسَل إلى طبيب عيون؟","o":["20/20","20/70","20/100","20/40"],"h1":"إنه نفس المعيار المستخدم في ولايات كثيرة.","h2":"في Vermont، إذا لم يصل نظرك إلى معيار 20/40 في الفحص، تُرسَل إلى طبيب عيون لمزيد من الفحص.","p":"صحيح. المعيار هو 20/40."},"ref":{"doc":"VT","page":18}},{"id":"vt-041","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, in good conditions, what is the smallest safe following distance behind the vehicle ahead?","o":["1 second","2 seconds","3 seconds","4 seconds"],"h1":"Vermont asks for more than many other states do.","h2":"Vermont teaches a following distance of at least four seconds behind the vehicle ahead, and more in bad weather or at high speed.","p":"Right. Keep at least four seconds."},"es":{"q":"En Vermont, con buenas condiciones, ¿cuál es la distancia mínima segura detrás del vehículo de adelante?","o":["1 segundo","2 segundos","3 segundos","4 segundos"],"h1":"Vermont pide más que muchos otros estados.","h2":"Vermont enseña una distancia de por lo menos cuatro segundos detrás del vehículo de adelante, y más con mal tiempo o a alta velocidad.","p":"Correcto. Deje por lo menos cuatro segundos."},"zh":{"q":"在 Vermont，在良好条件下，和前车保持的最小安全跟车距离是多少？","o":["1 秒","2 秒","3 秒","4 秒"],"h1":"Vermont 要求的比很多其他州多。","h2":"Vermont 教导和前车至少保持四秒的跟车距离，天气不好或速度快时要更多。","p":"对。至少保持四秒。"},"vi":{"q":"Ở Vermont, khi điều kiện tốt, khoảng cách an toàn nhỏ nhất khi chạy sau xe phía trước là bao nhiêu?","o":["1 giây","2 giây","3 giây","4 giây"],"h1":"Vermont yêu cầu nhiều hơn so với nhiều tiểu bang khác.","h2":"Vermont dạy giữ khoảng cách ít nhất bốn giây sau xe phía trước, và nhiều hơn khi thời tiết xấu hoặc chạy tốc độ cao.","p":"Đúng. Giữ ít nhất bốn giây."},"tl":{"q":"Sa Vermont, sa magandang kondisyon, ano ang pinakamaikling ligtas na distansya sa pagsunod sa sasakyan sa unahan?","o":["1 segundo","2 segundo","3 segundo","4 segundo"],"h1":"Mas marami ang hinihingi ng Vermont kaysa sa maraming ibang estado.","h2":"Itinuturo ng Vermont ang distansya sa pagsunod na hindi bababa sa apat na segundo sa likod ng sasakyan sa unahan, at mas mahaba pa kapag masama ang panahon o mabilis ang takbo.","p":"Tama. Panatilihin ang hindi bababa sa apat na segundo."},"ar":{"q":"في Vermont، في الظروف الجيدة، ما أقل مسافة آمنة تتركها خلف المركبة التي أمامك؟","o":["ثانية واحدة (1)","ثانيتان (2)","3 ثوانٍ","4 ثوانٍ"],"h1":"تطلب Vermont أكثر مما تطلبه ولايات أخرى كثيرة.","h2":"تعلّم Vermont أن تترك مسافة أربع ثوانٍ على الأقل خلف المركبة التي أمامك، وأكثر في الطقس السيئ أو عند السرعة العالية.","p":"صحيح. اترك أربع ثوانٍ على الأقل."},"ref":{"doc":"VT","page":27}},{"id":"vt-042","scope":"VT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Vermont, you pass a stopped emergency vehicle with flashing lights but cannot change lanes. How much must you slow down?","o":["5 mph below the limit","10 mph below the limit","20 mph below the limit","To 5 mph"],"h1":"It is a big drop in speed.","h2":"In Vermont, if you cannot move away from a stopped emergency vehicle, you must slow to 20 mph below the speed limit as you pass.","p":"Right. Slow to 20 mph below the limit."},"es":{"q":"En Vermont, usted pasa junto a un vehículo de emergencia detenido con luces intermitentes, pero no puede cambiarse de carril. ¿Cuánto debe reducir la velocidad?","o":["5 mph por debajo del límite","10 mph por debajo del límite","20 mph por debajo del límite","Hasta 5 mph"],"h1":"Es una gran reducción de velocidad.","h2":"En Vermont, si no puede alejarse de un vehículo de emergencia detenido, debe bajar a 20 mph por debajo del límite de velocidad al pasar.","p":"Correcto. Baje a 20 mph por debajo del límite."},"zh":{"q":"在 Vermont，你经过一辆停着、闪着灯的紧急车辆，但不能换车道。你必须减速多少？","o":["比限速低 5 mph","比限速低 10 mph","比限速低 20 mph","降到 5 mph"],"h1":"速度要降很多。","h2":"在 Vermont，如果你不能离开停着的紧急车辆，经过时必须把速度降到比限速低 20 mph。","p":"对。降到比限速低 20 mph。"},"vi":{"q":"Ở Vermont, bạn chạy qua một xe khẩn cấp đang dừng và chớp đèn nhưng không thể đổi làn. Bạn phải giảm tốc độ bao nhiêu?","o":["Thấp hơn giới hạn 5 mph","Thấp hơn giới hạn 10 mph","Thấp hơn giới hạn 20 mph","Xuống 5 mph"],"h1":"Đó là giảm tốc độ nhiều.","h2":"Ở Vermont, nếu bạn không thể tránh xa xe khẩn cấp đang dừng, bạn phải giảm xuống thấp hơn giới hạn tốc độ 20 mph khi chạy qua.","p":"Đúng. Giảm xuống thấp hơn giới hạn 20 mph."},"tl":{"q":"Sa Vermont, dadaan ka sa nakahintong emergency vehicle na may kumikislap na ilaw pero hindi ka makalipat ng linya. Gaano ka dapat bumagal?","o":["5 mph na mas mababa sa limitasyon","10 mph na mas mababa sa limitasyon","20 mph na mas mababa sa limitasyon","Hanggang 5 mph"],"h1":"Malaking pagbaba ito ng bilis.","h2":"Sa Vermont, kung hindi ka makalayo sa nakahintong emergency vehicle, dapat kang bumagal sa 20 mph na mas mababa sa speed limit habang dumadaan.","p":"Tama. Bumagal sa 20 mph na mas mababa sa limitasyon."},"ar":{"q":"في Vermont، تمرّ بمركبة طوارئ متوقفة وأضواؤها تومض لكن لا تستطيع تغيير المسار. كم يجب أن تخفّف سرعتك؟","o":["5 mph أقل من الحدّ","10 mph أقل من الحدّ","20 mph أقل من الحدّ","إلى 5 mph"],"h1":"إنه انخفاض كبير في السرعة.","h2":"في Vermont، إذا لم تستطع الابتعاد عن مركبة طوارئ متوقفة، يجب أن تخفّف سرعتك إلى 20 mph أقل من حدّ السرعة وأنت تمرّ بها.","p":"صحيح. خفّف إلى 20 mph أقل من الحدّ."},"ref":{"doc":"VT","page":51}},{"id":"vt-043","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, you are driving slowly and traffic is backing up behind you. What does the law require?","o":["Pull over when it is safe and let the vehicles pass","Speed up past the speed limit","Turn on your hazard lights and keep going","Stop in your lane so they can go around"],"h1":"Make room for the drivers behind you.","h2":"In Vermont, when traffic backs up behind your slow vehicle, the law says to pull over when it is safe and let the other vehicles go by.","p":"Right. Pull over safely and let them pass."},"es":{"q":"En Vermont, usted maneja despacio y se forma una fila de vehículos detrás de usted. ¿Qué exige la ley?","o":["Orillarse cuando sea seguro y dejar pasar a los vehículos","Acelerar por encima del límite de velocidad","Encender las luces de emergencia y seguir","Detenerse en su carril para que le den la vuelta"],"h1":"Deje espacio a los conductores de atrás.","h2":"En Vermont, cuando se forma una fila detrás de su vehículo lento, la ley dice que debe orillarse cuando sea seguro y dejar pasar a los demás.","p":"Correcto. Oríllese con seguridad y déjelos pasar."},"zh":{"q":"在 Vermont，你开得很慢，后面的车排起了队。法律要求你怎么做？","o":["安全时靠边停车，让车辆通过","加速超过限速","打开危险警示灯继续开","在你的车道上停下，让他们绕过去"],"h1":"给后面的司机让出空间。","h2":"在 Vermont，当你的慢车后面排起车队时，法律规定要在安全时靠边停车，让其他车辆过去。","p":"对。安全靠边，让他们过去。"},"vi":{"q":"Ở Vermont, bạn đang chạy chậm và xe phía sau bị dồn lại. Luật yêu cầu gì?","o":["Tấp vào lề khi an toàn và để các xe vượt qua","Tăng tốc vượt quá giới hạn tốc độ","Bật đèn khẩn cấp và tiếp tục chạy","Dừng lại trong làn của bạn để họ chạy vòng qua"],"h1":"Nhường chỗ cho những người lái phía sau bạn.","h2":"Ở Vermont, khi xe phía sau bị dồn lại vì xe bạn chạy chậm, luật nói phải tấp vào lề khi an toàn và để các xe khác chạy qua.","p":"Đúng. Tấp vào lề an toàn và để họ vượt qua."},"tl":{"q":"Sa Vermont, mabagal ang takbo mo at nagkakapila na ang mga sasakyan sa likod mo. Ano ang hinihingi ng batas?","o":["Tumabi kapag ligtas at paraanin ang mga sasakyan","Bumilis nang lampas sa speed limit","Buksan ang hazard lights at magpatuloy","Huminto sa linya mo para makaikot sila"],"h1":"Bigyan ng puwang ang mga drayber sa likod mo.","h2":"Sa Vermont, kapag nagkakapila ang trapiko sa likod ng mabagal mong sasakyan, sinasabi ng batas na tumabi kapag ligtas at paraanin ang ibang sasakyan.","p":"Tama. Tumabi nang ligtas at paraanin sila."},"ar":{"q":"في Vermont، تقود ببطء والسيارات تتجمّع خلفك. ماذا يطلب القانون؟","o":["ابتعد إلى جانب الطريق عندما يكون آمنًا ودع المركبات تمرّ","زِد سرعتك فوق حدّ السرعة","شغّل أضواء التحذير واستمرّ في القيادة","توقّف في مسارك حتى يلتفّوا حولك"],"h1":"أفسح المجال للسائقين خلفك.","h2":"في Vermont، عندما تتجمّع السيارات خلف مركبتك البطيئة، يقول القانون أن تبتعد إلى جانب الطريق عندما يكون آمنًا وتدع المركبات الأخرى تمرّ.","p":"صحيح. ابتعد إلى الجانب بأمان ودعهم يمرّون."},"ref":{"doc":"VT","page":25}},{"id":"vt-044","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, if you must stop on a rural highway, from how far away in each direction should other drivers be able to see your vehicle?","o":["50 feet","100 feet","150 feet","25 feet"],"h1":"So avoid hills and curves.","h2":"In Vermont, do not stop on a rural highway where your vehicle cannot be seen from at least 150 feet in each direction, and get all wheels off the road.","p":"Right. At least 150 feet each way."},"es":{"q":"En Vermont, si tiene que detenerse en una carretera rural, ¿desde qué distancia en cada dirección deben poder ver su vehículo los otros conductores?","o":["50 pies","100 pies","150 pies","25 pies"],"h1":"Por eso evite colinas y curvas.","h2":"En Vermont, no se detenga en una carretera rural donde su vehículo no se vea desde por lo menos 150 pies en cada dirección, y saque todas las ruedas del camino.","p":"Correcto. Por lo menos 150 pies en cada dirección."},"zh":{"q":"在 Vermont，如果你必须在乡村公路上停车，其他司机应该能从每个方向多远的地方看到你的车？","o":["50 英尺","100 英尺","150 英尺","25 英尺"],"h1":"所以要避开坡和弯道。","h2":"在 Vermont，不要在乡村公路上从每个方向 150 英尺外都看不到你车的地方停车，并且要让所有车轮都离开路面。","p":"对。每个方向至少 150 英尺。"},"vi":{"q":"Ở Vermont, nếu phải dừng xe trên xa lộ nông thôn, người lái khác phải thấy được xe bạn từ khoảng cách bao xa ở mỗi hướng?","o":["50 feet","100 feet","150 feet","25 feet"],"h1":"Vì vậy hãy tránh đồi dốc và khúc cua.","h2":"Ở Vermont, đừng dừng xe trên xa lộ nông thôn ở nơi mà xe bạn không thể được nhìn thấy từ ít nhất 150 feet ở mỗi hướng, và hãy đưa tất cả bánh xe ra khỏi mặt đường.","p":"Đúng. Ít nhất 150 feet mỗi hướng."},"tl":{"q":"Sa Vermont, kung kailangan mong huminto sa rural na highway, mula gaano kalayo sa bawat direksyon dapat makita ng ibang drayber ang sasakyan mo?","o":["50 feet","100 feet","150 feet","25 feet"],"h1":"Kaya iwasan ang mga burol at kurba.","h2":"Sa Vermont, huwag huminto sa rural na highway kung saan hindi makikita ang sasakyan mo mula sa hindi bababa sa 150 feet sa bawat direksyon, at ilabas ang lahat ng gulong sa kalsada.","p":"Tama. Hindi bababa sa 150 feet sa bawat direksyon."},"ar":{"q":"في Vermont، إذا كان يجب أن تتوقف على طريق سريع ريفي، من أيّ مسافة في كل اتجاه يجب أن يتمكّن السائقون الآخرون من رؤية مركبتك؟","o":["50 feet","100 feet","150 feet","25 feet"],"h1":"لذلك تجنّب التلال والمنعطفات.","h2":"في Vermont، يجب ألّا تتوقف على طريق سريع ريفي في مكان لا يمكن فيه رؤية مركبتك من 150 feet على الأقل في كل اتجاه، وأخرج كل العجلات عن الطريق.","p":"صحيح. 150 feet على الأقل في كل اتجاه."},"ref":{"doc":"VT","page":29}},{"id":"vt-045","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, what is the fine for a first offense of using a hand-held phone while driving?","o":["$25 to $50","$100 to $200","$1,000","$500 to $1,000"],"h1":"It starts at a hundred dollars.","h2":"In Vermont, a first offense for using a portable electronic device while driving brings a fine of $100 to $200, and more for later offenses.","p":"Right. $100 to $200 the first time."},"es":{"q":"En Vermont, ¿cuál es la multa por la primera vez que usa un teléfono en la mano mientras maneja?","o":["De $25 a $50","De $100 a $200","$1,000","De $500 a $1,000"],"h1":"Empieza en cien dólares.","h2":"En Vermont, la primera vez que usa un aparato electrónico portátil mientras maneja la multa es de $100 a $200, y más en las siguientes veces.","p":"Correcto. De $100 a $200 la primera vez."},"zh":{"q":"在 Vermont，开车时第一次手持手机会被罚多少钱？","o":["$25 到 $50","$100 到 $200","$1,000","$500 到 $1,000"],"h1":"从一百美元起。","h2":"在 Vermont，开车时第一次使用便携电子设备会被罚 $100 到 $200，以后再犯罚得更多。","p":"对。第一次 $100 到 $200。"},"vi":{"q":"Ở Vermont, tiền phạt cho lần vi phạm đầu tiên vì cầm điện thoại khi lái xe là bao nhiêu?","o":["$25 đến $50","$100 đến $200","$1,000","$500 đến $1,000"],"h1":"Bắt đầu từ một trăm đô la.","h2":"Ở Vermont, lần vi phạm đầu tiên vì dùng thiết bị điện tử cầm tay khi lái xe bị phạt từ $100 đến $200, và nhiều hơn cho các lần sau.","p":"Đúng. $100 đến $200 cho lần đầu."},"tl":{"q":"Sa Vermont, magkano ang multa sa unang paglabag sa paggamit ng hawak na telepono habang nagmamaneho?","o":["$25 hanggang $50","$100 hanggang $200","$1,000","$500 hanggang $1,000"],"h1":"Nagsisimula ito sa isang daang dolyar.","h2":"Sa Vermont, ang unang paglabag sa paggamit ng portable na electronic device habang nagmamaneho ay may multang $100 hanggang $200, at mas malaki sa mga susunod na paglabag.","p":"Tama. $100 hanggang $200 sa unang beses."},"ar":{"q":"في Vermont، ما الغرامة على المخالفة الأولى لاستخدام هاتف باليد أثناء القيادة؟","o":["من $25 إلى $50","من $100 إلى $200","$1,000","من $500 إلى $1,000"],"h1":"تبدأ من مئة دولار.","h2":"في Vermont، المخالفة الأولى لاستخدام جهاز إلكتروني محمول أثناء القيادة تجلب غرامة من $100 إلى $200، وأكثر في المخالفات التالية.","p":"صحيح. من $100 إلى $200 في المرة الأولى."},"ref":{"doc":"VT","page":55}},{"id":"vt-046","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, a child is not in a car seat with a harness. Until what age must the child ride in a booster seat?","o":["Until age 5","Until age 8","Until age 13","Until age 18"],"h1":"Most children are in second or third grade at this age.","h2":"In Vermont, a child under 8 who is not in a harnessed car seat must ride in a booster seat.","p":"Right. A booster seat until age 8."},"es":{"q":"En Vermont, un niño no va en un asiento de auto con arnés. ¿Hasta qué edad debe ir en un asiento elevador (booster)?","o":["Hasta los 5 años","Hasta los 8 años","Hasta los 13 años","Hasta los 18 años"],"h1":"A esa edad, la mayoría de los niños están en segundo o tercer grado.","h2":"En Vermont, un niño menor de 8 años que no va en un asiento con arnés debe ir en un asiento elevador (booster).","p":"Correcto. Asiento elevador hasta los 8 años."},"zh":{"q":"在 Vermont，一个孩子没有坐在带安全带的儿童座椅里。孩子要坐增高座椅到几岁？","o":["到 5 岁","到 8 岁","到 13 岁","到 18 岁"],"h1":"这个年龄的大多数孩子在上二年级或三年级。","h2":"在 Vermont，8 岁以下、没有坐在带安全带儿童座椅里的孩子，必须坐增高座椅（booster seat）。","p":"对。坐增高座椅到 8 岁。"},"vi":{"q":"Ở Vermont, một đứa trẻ không ngồi ghế trẻ em có dây đai. Trẻ phải ngồi ghế nâng (booster seat) cho đến bao nhiêu tuổi?","o":["Đến 5 tuổi","Đến 8 tuổi","Đến 13 tuổi","Đến 18 tuổi"],"h1":"Phần lớn trẻ ở tuổi này học lớp hai hoặc lớp ba.","h2":"Ở Vermont, trẻ dưới 8 tuổi không ngồi ghế trẻ em có dây đai thì phải ngồi ghế nâng.","p":"Đúng. Ngồi ghế nâng đến 8 tuổi."},"tl":{"q":"Sa Vermont, ang bata ay wala sa car seat na may harness. Hanggang anong edad dapat sumakay ang bata sa booster seat?","o":["Hanggang edad 5","Hanggang edad 8","Hanggang edad 13","Hanggang edad 18"],"h1":"Karamihan sa mga bata ay nasa ikalawa o ikatlong baitang sa edad na ito.","h2":"Sa Vermont, ang batang wala pang 8 na wala sa car seat na may harness ay dapat sumakay sa booster seat.","p":"Tama. Booster seat hanggang edad 8."},"ar":{"q":"في Vermont، طفل لا يجلس في مقعد أطفال بأحزمة. حتى أيّ عمر يجب أن يجلس في مقعد رافع (booster seat)؟","o":["حتى عمر 5 سنوات","حتى عمر 8 سنوات","حتى عمر 13 سنة","حتى عمر 18 سنة"],"h1":"معظم الأطفال في الصف الثاني أو الثالث في هذا العمر.","h2":"في Vermont، الطفل الذي عمره أقل من 8 سنوات ولا يجلس في مقعد أطفال بأحزمة يجب أن يجلس في مقعد رافع.","p":"صحيح. مقعد رافع حتى عمر 8 سنوات."},"ref":{"doc":"VT","page":63}},{"id":"vt-047","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, what is the least tread depth a tire may have and still be legal?","o":["2/32 of an inch","1/32 of an inch","1/2 of an inch","No set amount"],"h1":"Try the penny test with Lincoln's head.","h2":"In Vermont, tires must have at least 2/32 of an inch of tread; below that they are not safe or legal.","p":"Right. At least 2/32 of an inch."},"es":{"q":"En Vermont, ¿cuál es la profundidad mínima de la banda de rodadura que puede tener una llanta para ser legal?","o":["2/32 de pulgada","1/32 de pulgada","1/2 pulgada","No hay una medida fija"],"h1":"Haga la prueba del centavo con la cabeza de Lincoln.","h2":"En Vermont, las llantas deben tener por lo menos 2/32 de pulgada de banda de rodadura; con menos no son seguras ni legales.","p":"Correcto. Por lo menos 2/32 de pulgada."},"zh":{"q":"在 Vermont，轮胎花纹最浅可以是多少，仍然合法？","o":["2/32 英寸","1/32 英寸","1/2 英寸","没有规定"],"h1":"试试用一美分硬币上的林肯头像来测。","h2":"在 Vermont，轮胎花纹深度必须至少 2/32 英寸；低于这个深度就不安全，也不合法。","p":"对。至少 2/32 英寸。"},"vi":{"q":"Ở Vermont, độ sâu gai lốp ít nhất mà lốp xe phải có để vẫn hợp pháp là bao nhiêu?","o":["2/32 inch","1/32 inch","1/2 inch","Không có mức quy định"],"h1":"Hãy thử kiểm tra bằng đồng xu một cent có hình đầu Lincoln.","h2":"Ở Vermont, lốp xe phải có gai sâu ít nhất 2/32 inch; dưới mức đó là không an toàn và không hợp pháp.","p":"Đúng. Ít nhất 2/32 inch."},"tl":{"q":"Sa Vermont, ano ang pinakamababang lalim ng tread na puwedeng magkaroon ang gulong at legal pa rin?","o":["2/32 ng isang pulgada","1/32 ng isang pulgada","1/2 ng isang pulgada","Walang takdang sukat"],"h1":"Subukan ang penny test gamit ang ulo ni Lincoln.","h2":"Sa Vermont, ang gulong ay dapat may tread na hindi bababa sa 2/32 ng isang pulgada; kapag mas mababa roon, hindi ito ligtas o legal.","p":"Tama. Hindi bababa sa 2/32 ng isang pulgada."},"ar":{"q":"في Vermont، ما أقل عمق لنقشة الإطار (tread) يبقى فيه الإطار قانونيًا؟","o":["2/32 من البوصة","1/32 من البوصة","1/2 من البوصة","لا يوجد مقدار محدد"],"h1":"جرّب اختبار السنت (penny test) برأس Lincoln.","h2":"في Vermont، يجب أن يكون عمق نقشة الإطارات 2/32 من البوصة على الأقل؛ وأقل من ذلك ليس آمنًا ولا قانونيًا.","p":"صحيح. 2/32 من البوصة على الأقل."},"ref":{"doc":"VT","page":60}},{"id":"vt-048","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, during what hours does the law require your headlights to be on?","o":["From 9 p.m. to 6 a.m.","From one hour after sunset to one hour before sunrise","Only when there are no streetlights","From a half hour after sunset to a half hour before sunrise"],"h1":"Think of the time just after the sun goes down.","h2":"In Vermont, the law requires headlights from a half hour after sunset to a half hour before sunrise.","p":"Right. A half hour after sunset to a half hour before sunrise."},"es":{"q":"En Vermont, ¿en qué horas exige la ley tener las luces delanteras encendidas?","o":["De 9 p.m. a 6 a.m.","Desde una hora después de la puesta del sol hasta una hora antes del amanecer","Solo cuando no hay alumbrado público","Desde media hora después de la puesta del sol hasta media hora antes del amanecer"],"h1":"Piense en el tiempo justo después de que se pone el sol.","h2":"En Vermont, la ley exige las luces delanteras desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Desde media hora después de la puesta del sol hasta media hora antes del amanecer."},"zh":{"q":"在 Vermont，法律要求在什么时间开车头灯？","o":["晚上 9 点到早上 6 点","日落后一小时到日出前一小时","只有在没有路灯的时候","日落后半小时到日出前半小时"],"h1":"想想太阳刚下山之后的时间。","h2":"在 Vermont，法律要求从日落后半小时到日出前半小时开车头灯。","p":"对。日落后半小时到日出前半小时。"},"vi":{"q":"Ở Vermont, luật yêu cầu bật đèn pha trong những giờ nào?","o":["Từ 9 giờ tối đến 6 giờ sáng","Từ một giờ sau khi mặt trời lặn đến một giờ trước khi mặt trời mọc","Chỉ khi không có đèn đường","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc"],"h1":"Hãy nghĩ đến lúc ngay sau khi mặt trời lặn.","h2":"Ở Vermont, luật yêu cầu bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa Vermont, sa anong mga oras hinihingi ng batas na nakabukas ang headlights mo?","o":["Mula 9 p.m. hanggang 6 a.m.","Mula isang oras pagkalubog ng araw hanggang isang oras bago sumikat ang araw","Kapag walang ilaw sa kalye lamang","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw"],"h1":"Isipin ang oras pagkalubog na pagkalubog ng araw.","h2":"Sa Vermont, hinihingi ng batas na nakabukas ang headlights mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw."},"ar":{"q":"في Vermont، في أيّ ساعات يطلب القانون أن تكون المصابيح الأمامية مضاءة؟","o":["من 9 مساءً إلى 6 صباحًا","من ساعة بعد غروب الشمس إلى ساعة قبل شروقها","فقط عندما لا توجد أضواء في الشارع","من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها"],"h1":"فكّر في الوقت بعد غروب الشمس مباشرة.","h2":"في Vermont، يطلب القانون إضاءة المصابيح الأمامية من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها."},"ref":{"doc":"VT","page":49}},{"id":"vt-049","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, you must stop for a train at a railroad crossing. What is the closest you may stop to the nearest rail?","o":["3 feet","5 feet","10 feet","15 feet"],"h1":"It is about the length of a car.","h2":"In Vermont, when you must stop at a railroad crossing, you stop no closer than 15 feet from the nearest rail.","p":"Right. No closer than 15 feet."},"es":{"q":"En Vermont, usted debe detenerse por un tren en un cruce de ferrocarril. ¿A qué distancia mínima del riel más cercano debe detenerse?","o":["3 pies","5 pies","10 pies","15 pies"],"h1":"Es más o menos el largo de un auto.","h2":"En Vermont, cuando debe detenerse en un cruce de ferrocarril, se detiene a no menos de 15 pies del riel más cercano.","p":"Correcto. A no menos de 15 pies."},"zh":{"q":"在 Vermont，你必须在铁路道口停车等火车。你停车时离最近的铁轨最近可以是多少？","o":["3 英尺","5 英尺","10 英尺","15 英尺"],"h1":"大约一辆车的长度。","h2":"在 Vermont，你必须在铁路道口停车时，停车位置离最近的铁轨不能少于 15 英尺。","p":"对。不能少于 15 英尺。"},"vi":{"q":"Ở Vermont, bạn phải dừng chờ tàu hỏa ở chỗ giao nhau với đường ray. Bạn được dừng gần nhất cách đường ray gần nhất bao xa?","o":["3 feet","5 feet","10 feet","15 feet"],"h1":"Khoảng chiều dài một chiếc xe hơi.","h2":"Ở Vermont, khi phải dừng ở chỗ giao nhau với đường ray, bạn dừng cách đường ray gần nhất không dưới 15 feet.","p":"Đúng. Không gần hơn 15 feet."},"tl":{"q":"Sa Vermont, dapat kang huminto para sa tren sa tawiran ng riles. Gaano kalapit ang pinakamalapit na puwede kang huminto sa pinakamalapit na riles?","o":["3 feet","5 feet","10 feet","15 feet"],"h1":"Mga haba ito ng isang kotse.","h2":"Sa Vermont, kapag kailangan mong huminto sa tawiran ng riles, huminto nang hindi lalapit sa 15 feet mula sa pinakamalapit na riles.","p":"Tama. Hindi lalapit sa 15 feet."},"ar":{"q":"في Vermont، يجب أن تتوقف لقطار عند تقاطع سكة حديد. ما أقرب مسافة يجوز أن تتوقف عندها من أقرب قضيب؟","o":["3 feet","5 feet","10 feet","15 feet"],"h1":"إنها حوالي طول سيارة.","h2":"في Vermont، عندما يجب أن تتوقف عند تقاطع سكة حديد، تتوقف على مسافة لا تقلّ عن 15 feet من أقرب قضيب.","p":"صحيح. ليس أقرب من 15 feet."},"ref":{"doc":"VT","page":37}},{"id":"vt-050","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, you come up to a town snowplow working on the road with its lights flashing. What must you do?","o":["Go ahead with caution and yield the right of way to it","Honk so the driver moves over","Pass it quickly before it slows you down","Follow close behind it on the cleared road"],"h1":"Treat road crews with the same care as other working vehicles.","h2":"In Vermont, the law says you must slow down, use caution and yield the right of way to a state, city or town maintenance vehicle, such as a snowplow, working on the road.","p":"Right. Use caution and yield to it."},"es":{"q":"En Vermont, usted se acerca a un quitanieves del pueblo que trabaja en el camino con las luces intermitentes. ¿Qué debe hacer?","o":["Seguir con precaución y cederle el paso","Tocar la bocina para que el conductor se aparte","Rebasarlo rápido antes de que lo retrase","Seguirlo de cerca por el camino limpio"],"h1":"Trate a las cuadrillas de carreteras con el mismo cuidado que a otros vehículos de trabajo.","h2":"En Vermont, la ley dice que debe reducir la velocidad, tener precaución y ceder el paso a un vehículo de mantenimiento del estado, la ciudad o el pueblo, como un quitanieves, que trabaja en el camino.","p":"Correcto. Tenga precaución y cédale el paso."},"zh":{"q":"在 Vermont，你开近一辆正在路上作业、闪着灯的镇上铲雪车。你必须怎么做？","o":["小心前进，并把先行权让给它","按喇叭让司机让开","在它让你变慢之前快速超过它","在清理过的路上紧跟在它后面"],"h1":"对待道路作业人员要像对待其他作业车辆一样小心。","h2":"在 Vermont，法律规定你必须减速、小心，并把先行权让给正在路上作业的州、市或镇的养护车辆，比如铲雪车。","p":"对。要小心，并给它让路。"},"vi":{"q":"Ở Vermont, bạn đến gần một xe ủi tuyết của thị trấn đang làm việc trên đường và chớp đèn. Bạn phải làm gì?","o":["Tiếp tục đi một cách cẩn thận và nhường quyền ưu tiên cho xe đó","Bấm còi để tài xế tránh sang","Vượt qua nhanh trước khi nó làm bạn chậm lại","Chạy sát phía sau nó trên con đường đã được dọn"],"h1":"Hãy cẩn thận với đội làm đường giống như với các xe đang làm việc khác.","h2":"Ở Vermont, luật nói bạn phải chạy chậm lại, cẩn thận và nhường quyền ưu tiên cho xe bảo trì đường của tiểu bang, thành phố hoặc thị trấn đang làm việc trên đường, ví dụ như xe ủi tuyết.","p":"Đúng. Cẩn thận và nhường đường cho nó."},"tl":{"q":"Sa Vermont, papalapit ka sa snowplow ng bayan na nagtatrabaho sa kalsada na may kumikislap na ilaw. Ano ang dapat mong gawin?","o":["Magpatuloy nang maingat at ibigay dito ang right of way","Bumusina para tumabi ang drayber","Lampasan ito nang mabilis bago ka nito pabagalin","Sumunod nang malapit sa likod nito sa nalinis na kalsada"],"h1":"Ituring ang mga road crew nang may parehong ingat tulad ng ibang sasakyang nagtatrabaho.","h2":"Sa Vermont, sinasabi ng batas na dapat kang bumagal, mag-ingat at ibigay ang right of way sa maintenance vehicle ng estado, lungsod o bayan, gaya ng snowplow, na nagtatrabaho sa kalsada.","p":"Tama. Mag-ingat at magbigay-daan dito."},"ar":{"q":"في Vermont، تقترب من كاسحة ثلج تابعة للبلدة تعمل على الطريق وأضواؤها تومض. ماذا يجب أن تفعل؟","o":["تقدّم بحذر وأعطِها حقّ الأولوية في المرور","اضغط على البوق حتى يبتعد السائق","تجاوزها بسرعة قبل أن تُبطئك","سِر قريبًا خلفها على الطريق النظيف"],"h1":"عامِل فرق العمل على الطريق بنفس الحذر مثل المركبات العاملة الأخرى.","h2":"في Vermont، يقول القانون إنه يجب أن تخفّف سرعتك وتنتبه وتعطي حقّ الأولوية في المرور لمركبة صيانة تابعة للولاية أو المدينة أو البلدة، مثل كاسحة الثلج، وهي تعمل على الطريق.","p":"صحيح. انتبه وأعطِها حقّ الأولوية."},"ref":{"doc":"VT","page":31}},{"id":"vt-051","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you move here with a commercial driver's license (CDL) from another state. How soon must you transfer it?","o":["Within 10 days","Within 30 days","Within 60 days","Within 90 days"],"h1":"It is shorter than the time allowed for a regular license.","h2":"A new Vermont resident with a commercial driver's license from another state must transfer it within 30 days.","p":"Right. A CDL must be transferred within 30 days."},"es":{"q":"En Vermont, usted se muda aquí con una licencia comercial (CDL) de otro estado. ¿En cuánto tiempo debe transferirla?","o":["En 10 días","En 30 días","En 60 días","En 90 días"],"h1":"Es menos tiempo que el que se da para una licencia normal.","h2":"Un nuevo residente de Vermont con una licencia comercial de otro estado debe transferirla en un plazo de 30 días.","p":"Correcto. La CDL se debe transferir en 30 días."},"ref":{"doc":"VT","page":12}},{"id":"vt-052","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, a person under 18 applying for a learner's permit must have a clean driving record for how long before applying?","o":["The past 6 months","The past year","The past 2 years","The past 5 years"],"h1":"It is more than one year.","h2":"A Vermont permit applicant under 18 must have kept a clean driving record for the previous two years.","p":"Right. Two clean years are needed before the permit."},"es":{"q":"En Vermont, una persona menor de 18 que solicita el permiso de aprendiz debe tener un historial de manejo limpio, ¿por cuánto tiempo antes de solicitarlo?","o":["Los últimos 6 meses","El último año","Los últimos 2 años","Los últimos 5 años"],"h1":"Es más de un año.","h2":"Quien solicita el permiso en Vermont siendo menor de 18 debe haber tenido un historial de manejo limpio durante los dos años anteriores.","p":"Correcto. Se necesitan dos años limpios antes del permiso."},"ref":{"doc":"VT","page":12}},{"id":"vt-053","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a foreign exchange student age 16 wants a learner's permit. Who may sign the permission form?","o":["The host parent","A teacher at the school","Any licensed adult age 25 or older","A parent or legal guardian, not the host parent"],"h1":"The family the student is staying with cannot sign.","h2":"A foreign exchange student's permit form must be signed by a parent or legal guardian; a host parent may not sign it.","p":"Right. Only a parent or legal guardian may sign, not the host parent."},"es":{"q":"En Vermont, un estudiante de intercambio de 16 años quiere un permiso de aprendiz. ¿Quién puede firmar el formulario de permiso?","o":["La madre o el padre anfitrión","Un maestro de la escuela","Cualquier adulto con licencia de 25 años o más","Su padre, madre o tutor legal, no el anfitrión"],"h1":"La familia con la que vive el estudiante no puede firmar.","h2":"El formulario del permiso de un estudiante de intercambio lo debe firmar su padre, madre o tutor legal; un padre anfitrión no puede firmarlo.","p":"Correcto. Solo un padre o tutor legal puede firmar, no el anfitrión."},"ref":{"doc":"VT","page":12}},{"id":"vt-054","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, at what times of day may you drive with a learner's permit?","o":["Only in daylight","Only before 9 p.m.","At any time, day or night, with a qualified supervisor beside you","Only on weekends"],"h1":"Vermont puts no clock limit on permit driving.","h2":"With a valid learner's permit you may drive anywhere in Vermont at any time, as long as a qualified supervisor rides beside you.","p":"Right. Any time is allowed, with a qualified supervisor."},"es":{"q":"En Vermont, ¿a qué horas del día puede manejar con un permiso de aprendiz?","o":["Solo de día","Solo antes de las 9 p.m.","A cualquier hora, de día o de noche, con un supervisor calificado a su lado","Solo los fines de semana"],"h1":"Vermont no pone límite de horario al manejo con permiso.","h2":"Con un permiso de aprendiz válido usted puede manejar en cualquier parte de Vermont a cualquier hora, siempre que un supervisor calificado vaya a su lado.","p":"Correcto. Se permite a cualquier hora, con un supervisor calificado."},"ref":{"doc":"VT","page":13}},{"id":"vt-055","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, you have a Vermont learner's permit and plan a trip to another state. What should you do before driving there?","o":["Check with that state first, because driving there on your permit may not be legal","Nothing, a Vermont permit is valid in every state","Get a temporary license at the border","Drive only on Interstates in that state"],"h1":"Each state makes its own rules for permits from other states.","h2":"Before driving in another state with a Vermont learner's permit, you must check with that state's motor vehicle agency or police to see if it is legal.","p":"Right. Check with the other state first."},"es":{"q":"En Vermont, usted tiene un permiso de aprendiz de Vermont y planea un viaje a otro estado. ¿Qué debe hacer antes de manejar allí?","o":["Consultar primero con ese estado, porque manejar allí con su permiso puede no ser legal","Nada, un permiso de Vermont vale en todos los estados","Sacar una licencia temporal en la frontera","Manejar solo en carreteras interestatales en ese estado"],"h1":"Cada estado tiene sus propias reglas para permisos de otros estados.","h2":"Antes de manejar en otro estado con un permiso de aprendiz de Vermont, debe consultar con la agencia de vehículos o la policía de ese estado para saber si es legal.","p":"Correcto. Consulte primero con el otro estado."},"ref":{"doc":"VT","page":13}},{"id":"vt-056","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, before you can get a junior operator's license, how long must you go with no recall, suspension or revocation of your learner's permit?","o":["1 month","3 months","6 months","2 years"],"h1":"It is half a year.","h2":"To get a Vermont junior operator's license, your learner's permit must have had no recall, suspension or revocation for the previous six months.","p":"Right. Six clean months on the permit are needed."},"es":{"q":"En Vermont, antes de obtener la licencia de operador menor, ¿cuánto tiempo debe pasar sin que su permiso de aprendiz haya sido retirado, suspendido o revocado?","o":["1 mes","3 meses","6 meses","2 años"],"h1":"Es medio año.","h2":"Para obtener la licencia de operador menor en Vermont, su permiso de aprendiz no debe haber tenido ningún retiro, suspensión ni revocación durante los seis meses anteriores.","p":"Correcto. Se necesitan seis meses limpios con el permiso."},"ref":{"doc":"VT","page":13}},{"id":"vt-057","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator's license is issued to drivers of what ages?","o":["15 and 16","16 and 17","17 and 18","18 to 20"],"h1":"It is for teens who are not adults yet but are past the permit age.","h2":"Vermont issues the junior operator's license to drivers who are 16 or 17 years old and pass the required tests.","p":"Right. The junior license is for ages 16 and 17."},"es":{"q":"En Vermont, la licencia de operador menor se da a conductores, ¿de qué edades?","o":["15 y 16","16 y 17","17 y 18","18 a 20"],"h1":"Es para adolescentes que aún no son adultos pero ya pasaron la edad del permiso.","h2":"Vermont da la licencia de operador menor a conductores de 16 o 17 años que aprueban los exámenes requeridos.","p":"Correcto. La licencia de menor es para 16 y 17 años."},"ref":{"doc":"VT","page":13}},{"id":"vt-058","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how many hours of classroom study does a state-approved driver education course include?","o":["6 hours","12 hours","30 hours","40 hours"],"h1":"It is more than the 6 behind-the-wheel hours, but less than the 40 practice hours.","h2":"A state-approved driver education course in Vermont includes 30 hours of classroom study, plus 6 hours behind the wheel and 6 hours of observation.","p":"Right. The course has 30 classroom hours."},"es":{"q":"En Vermont, ¿cuántas horas de clase en el aula incluye un curso de educación vial aprobado por el estado?","o":["6 horas","12 horas","30 horas","40 horas"],"h1":"Es más que las 6 horas al volante, pero menos que las 40 horas de práctica.","h2":"Un curso de educación vial aprobado en Vermont incluye 30 horas de clase en el aula, más 6 horas al volante y 6 horas de observación.","p":"Correcto. El curso tiene 30 horas en el aula."},"ref":{"doc":"VT","page":13}},{"id":"vt-059","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, do the 6 behind-the-wheel hours of driver education count toward the 40 hours of practice?","o":["No, the 40 practice hours are in addition to them","Yes, they count toward the 40","Only if they are at night","Only half of them count"],"h1":"The law adds the practice hours on top of the course.","h2":"The 40 hours of supervised practice in Vermont are in addition to the 6 behind-the-wheel hours of driver education, so they do not count toward it.","p":"Right. The 40 hours come on top of driver education."},"es":{"q":"En Vermont, ¿las 6 horas al volante de educación vial cuentan para las 40 horas de práctica?","o":["No, las 40 horas de práctica son adicionales","Sí, cuentan para las 40","Solo si son de noche","Solo cuenta la mitad"],"h1":"La ley suma las horas de práctica además del curso.","h2":"Las 40 horas de práctica supervisada en Vermont son adicionales a las 6 horas al volante de educación vial, así que esas no cuentan.","p":"Correcto. Las 40 horas son además de la educación vial."},"ref":{"doc":"VT","page":14}},{"id":"vt-060","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, your learner's permit has expired and you want to take the road test. After how long expired must you take the written test again first?","o":["More than 30 days","More than 1 year","More than 3 years","More than 10 years"],"h1":"It is a few years.","h2":"If your Vermont learner's permit has been expired for more than three years, you must pass the written test again before the road test.","p":"Right. After more than three years expired, the written test is needed again."},"es":{"q":"En Vermont, su permiso de aprendiz está vencido y quiere tomar el examen de manejo. ¿Después de cuánto tiempo vencido debe tomar otra vez primero el examen escrito?","o":["Más de 30 días","Más de 1 año","Más de 3 años","Más de 10 años"],"h1":"Son unos pocos años.","h2":"Si su permiso de aprendiz de Vermont lleva más de tres años vencido, debe aprobar otra vez el examen escrito antes del examen de manejo.","p":"Correcto. Con más de tres años vencido, se necesita otra vez el examen escrito."},"ref":{"doc":"VT","page":13}},{"id":"vt-061","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, you arrive for your road test, but you do not have the car's insurance card. What happens?","o":["You may take the test and bring the card later","You pay a small fee and take the test","The examiner gives you a warning","You cannot take the road test"],"h1":"The card and registration must be shown before the test starts.","h2":"In Vermont, failing to show a valid insurance card and registration certificate for the car prevents you from taking the road test.","p":"Right. No insurance card means no road test."},"es":{"q":"En Vermont, usted llega a su examen de manejo pero no tiene la tarjeta del seguro del carro. ¿Qué pasa?","o":["Puede tomar el examen y traer la tarjeta después","Paga una pequeña cuota y toma el examen","El examinador le da una advertencia","No puede tomar el examen de manejo"],"h1":"La tarjeta y el registro se deben mostrar antes de empezar el examen.","h2":"En Vermont, si no muestra una tarjeta de seguro válida y el certificado de registro del carro, no puede tomar el examen de manejo.","p":"Correcto. Sin tarjeta de seguro no hay examen de manejo."},"ref":{"doc":"VT","page":14}},{"id":"vt-062","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, a 16-year-old moves here with a junior license from another state. How long must they have held it to skip Vermont's graduated license limits?","o":["1 month","3 months","At least 6 months","At least 1 year"],"h1":"It is half a year.","h2":"A teen who held a junior license in another state for at least six months is not subject to Vermont's graduated license limits; otherwise they apply.","p":"Right. At least six months in the other state is needed."},"es":{"q":"En Vermont, un joven de 16 años se muda aquí con una licencia de menor de otro estado. ¿Cuánto tiempo debe haberla tenido para no tener los límites de la licencia gradual de Vermont?","o":["1 mes","3 meses","Por lo menos 6 meses","Por lo menos 1 año"],"h1":"Es medio año.","h2":"Un adolescente que tuvo una licencia de menor en otro estado por lo menos seis meses no queda sujeto a los límites de la licencia gradual de Vermont; si no, sí se aplican.","p":"Correcto. Se necesitan por lo menos seis meses en el otro estado."},"ref":{"doc":"VT","page":14}},{"id":"vt-063","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, may a driver with a junior operator's license drive passengers who pay for the ride?","o":["Yes, after the first three months","No, never while holding a junior license","Yes, if a parent agrees","Only family members who pay"],"h1":"Think of a taxi or ride service.","h2":"A Vermont junior operator may never carry passengers for hire; doing so brings a 90-day recall of the license.","p":"Right. No paying passengers on a junior license."},"es":{"q":"En Vermont, ¿puede un conductor con licencia de operador menor llevar pasajeros que pagan por el viaje?","o":["Sí, después de los primeros tres meses","No, nunca mientras tenga licencia de menor","Sí, si un padre está de acuerdo","Solo familiares que pagan"],"h1":"Piense en un taxi o servicio de transporte.","h2":"Un operador menor en Vermont nunca puede llevar pasajeros que pagan; hacerlo trae un retiro de la licencia por 90 días.","p":"Correcto. No se llevan pasajeros que pagan con licencia de menor."},"ref":{"doc":"VT","page":21}},{"id":"vt-064","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, what can happen to a junior operator's license if the parent or guardian withdraws permission to drive?","o":["The license can be taken away","Nothing, the license stays valid","The teen must pay a fine","The teen must take the permit test again"],"h1":"The parent's signature is what allowed the license.","h2":"A Vermont junior operator's license can be taken away if the parent or guardian withdraws permission for the teen to drive.","p":"Right. The license can be taken away."},"es":{"q":"En Vermont, ¿qué puede pasar con la licencia de operador menor si el padre, madre o tutor retira su permiso para manejar?","o":["Le pueden quitar la licencia","Nada, la licencia sigue válida","El joven debe pagar una multa","El joven debe tomar otra vez el examen del permiso"],"h1":"La firma del padre es lo que permitió la licencia.","h2":"A un operador menor en Vermont le pueden quitar la licencia si su padre, madre o tutor retira el permiso para que maneje.","p":"Correcto. Le pueden quitar la licencia."},"ref":{"doc":"VT","page":15}},{"id":"vt-065","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, at what age can you get a regular driver's license instead of a junior operator's license?","o":["16","17","18","21"],"h1":"It is the age of an adult.","h2":"Vermont issues a regular driver's license to eligible people 18 or older who pass the required tests.","p":"Right. A regular license starts at 18."},"es":{"q":"En Vermont, ¿a qué edad puede obtener una licencia de manejar normal en vez de la licencia de operador menor?","o":["16","17","18","21"],"h1":"Es la edad de un adulto.","h2":"Vermont da la licencia de manejar normal a personas de 18 años o más que cumplen los requisitos y aprueban los exámenes.","p":"Correcto. La licencia normal empieza a los 18."},"ref":{"doc":"VT","page":16}},{"id":"vt-066","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, which vehicles may you drive with a regular driver's license?","o":["Any vehicle, including school buses","Only cars, not pickup trucks","Any vehicle, including motorcycles","Any noncommercial vehicle except a school bus or motorcycle"],"h1":"Two kinds of vehicles need extra tests.","h2":"A regular Vermont driver's license lets you drive any noncommercial vehicle except a school bus or a motorcycle, which need additional tests.","p":"Right. School buses and motorcycles need more."},"es":{"q":"En Vermont, ¿qué vehículos puede manejar con una licencia de manejar normal?","o":["Cualquier vehículo, incluso autobuses escolares","Solo carros, no camionetas","Cualquier vehículo, incluso motocicletas","Cualquier vehículo no comercial, menos un autobús escolar o una motocicleta"],"h1":"Dos tipos de vehículos necesitan exámenes adicionales.","h2":"La licencia de manejar normal de Vermont permite manejar cualquier vehículo no comercial, menos un autobús escolar o una motocicleta, que necesitan exámenes adicionales.","p":"Correcto. Los autobuses escolares y las motocicletas necesitan más."},"ref":{"doc":"VT","page":16}},{"id":"vt-067","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, you turn 18 with a junior operator's license, but your license was suspended and reinstated 2 months ago. What must happen before you get a full license?","o":["Six months must pass with no recall or suspension, counted from reinstatement","Nothing, at 18 you get it right away","You must wait until age 21","You must take driver education again"],"h1":"The clean period starts again on the day you are reinstated.","h2":"To move from a junior to a full Vermont license you must be 18 and have no recall, suspension or revocation in the previous six months, counted from your reinstatement date.","p":"Right. You need six clean months after reinstatement."},"es":{"q":"En Vermont, usted cumple 18 con licencia de operador menor, pero su licencia fue suspendida y restablecida hace 2 meses. ¿Qué debe pasar antes de obtener la licencia completa?","o":["Deben pasar seis meses sin retiro ni suspensión, contados desde el restablecimiento","Nada, a los 18 la recibe de inmediato","Debe esperar hasta los 21","Debe tomar otra vez educación vial"],"h1":"El período limpio empieza de nuevo el día en que se restablece la licencia.","h2":"Para pasar de la licencia de menor a la licencia completa en Vermont, usted debe tener 18 años y ningún retiro, suspensión ni revocación en los seis meses anteriores, contados desde la fecha del restablecimiento.","p":"Correcto. Necesita seis meses limpios después del restablecimiento."},"ref":{"doc":"VT","page":21}},{"id":"vt-068","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you are a new resident with a valid license from another state. Which test must you take to get a Vermont license?","o":["Written and road tests","An eye (vision) test","Only a road test","No test at all"],"h1":"They want to know you can see well enough.","h2":"A new Vermont resident with a valid out-of-state license, or one expired three years or less, must take an eye exam to get a Vermont license.","p":"Right. An eye exam is required."},"es":{"q":"En Vermont, usted es un nuevo residente con una licencia válida de otro estado. ¿Qué examen debe tomar para obtener una licencia de Vermont?","o":["Examen escrito y de manejo","Un examen de la vista","Solo un examen de manejo","Ningún examen"],"h1":"Quieren saber que usted ve lo suficientemente bien.","h2":"Un nuevo residente de Vermont con una licencia válida de otro estado, o vencida hace tres años o menos, debe hacer un examen de la vista para obtener la licencia de Vermont.","p":"Correcto. Se requiere un examen de la vista."},"ref":{"doc":"VT","page":16}},{"id":"vt-069","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, you move here and your old license from another state expired more than 3 years ago. Which tests must you take?","o":["Only an eye test","Only a written test","Only a road test","Vision, written and road tests"],"h1":"After that long, you are treated like a new driver.","h2":"If your out-of-state license has been expired for more than three years, or you have none, you must take the vision, written and road tests in Vermont.","p":"Right. All three tests are needed."},"es":{"q":"En Vermont, usted se muda aquí y su licencia de otro estado venció hace más de 3 años. ¿Qué exámenes debe tomar?","o":["Solo un examen de la vista","Solo un examen escrito","Solo un examen de manejo","Examen de la vista, escrito y de manejo"],"h1":"Después de tanto tiempo, lo tratan como a un conductor nuevo.","h2":"Si su licencia de otro estado lleva más de tres años vencida, o no tiene licencia, debe tomar en Vermont los exámenes de la vista, escrito y de manejo.","p":"Correcto. Se necesitan los tres exámenes."},"ref":{"doc":"VT","page":16}},{"id":"vt-070","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, you will drive schoolchildren in a small school bus built for fewer than 16 passengers. What do you need on your license?","o":["Nothing extra","A motorcycle endorsement","A Type II school bus endorsement","A Class A commercial license"],"h1":"Every driver of schoolchildren in a school bus needs a special mark on the license.","h2":"To drive schoolchildren in a school bus rated for fewer than 16 passengers in Vermont, you need a Type II school bus endorsement on your driver's license.","p":"Right. A Type II school bus endorsement is needed."},"es":{"q":"En Vermont, usted llevará a niños de escuela en un autobús escolar pequeño hecho para menos de 16 pasajeros. ¿Qué necesita en su licencia?","o":["Nada adicional","Un endoso de motocicleta","Un endoso de autobús escolar Tipo II","Una licencia comercial Clase A"],"h1":"Todo conductor que lleva a escolares en un autobús escolar necesita una marca especial en la licencia.","h2":"Para llevar a escolares en un autobús escolar para menos de 16 pasajeros en Vermont, necesita un endoso de autobús escolar Tipo II en su licencia de manejar.","p":"Correcto. Se necesita un endoso de autobús escolar Tipo II."},"ref":{"doc":"VT","page":17}},{"id":"vt-071","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how old must a licensed driver be to get a motorcycle permit or endorsement?","o":["15","16","18","21"],"h1":"It is the same age as the start of the junior license.","h2":"In Vermont, a licensed person 16 or older can get a motorcycle permit or endorsement by passing a test.","p":"Right. The minimum age is 16."},"es":{"q":"En Vermont, ¿qué edad debe tener un conductor con licencia para obtener un permiso o endoso de motocicleta?","o":["15","16","18","21"],"h1":"Es la misma edad en que empieza la licencia de menor.","h2":"En Vermont, una persona con licencia de 16 años o más puede obtener un permiso o endoso de motocicleta si aprueba un examen.","p":"Correcto. La edad mínima es 16."},"ref":{"doc":"VT","page":17}},{"id":"vt-072","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, what is the benefit of passing the Basic Rider Course of the Vermont Rider Education Program?","o":["A lower motorcycle registration fee","Permission to ride on sidewalks","Permission to ride without a helmet","You skip the state written and skill tests for the motorcycle endorsement"],"h1":"It replaces some of the DMV tests.","h2":"Riders who pass Vermont's Basic Rider Course do not have to take the state written and skill exams for a motorcycle endorsement.","p":"Right. The course replaces the state written and skill tests."},"es":{"q":"En Vermont, ¿qué ventaja tiene aprobar el Curso Básico para Motociclistas del Programa de Educación de Motociclistas de Vermont?","o":["Una cuota de registro de moto más baja","Permiso para andar en la acera","Permiso para andar sin casco","No tiene que tomar los exámenes estatales escrito y de habilidad para el endoso de motocicleta"],"h1":"Reemplaza algunos exámenes del DMV.","h2":"Quienes aprueban el Curso Básico para Motociclistas de Vermont no tienen que tomar los exámenes estatales escrito y de habilidad para el endoso de motocicleta.","p":"Correcto. El curso reemplaza los exámenes estatales escrito y de habilidad."},"ref":{"doc":"VT","page":17}},{"id":"vt-073","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how do you visit a DMV office?","o":["By appointment only","Walk in any time without an appointment","Walk in only on Mondays","Appointments are needed only for road tests"],"h1":"Plan ahead online or by phone.","h2":"All visits to a Vermont DMV office are by appointment only, made online at mydmv.vermont.gov or by phone.","p":"Right. Every DMV visit needs an appointment."},"es":{"q":"En Vermont, ¿cómo visita una oficina del DMV?","o":["Solo con cita","Puede llegar sin cita a cualquier hora","Sin cita solo los lunes","Solo se necesita cita para el examen de manejo"],"h1":"Planee con tiempo por internet o por teléfono.","h2":"Todas las visitas a una oficina del DMV de Vermont son solo con cita, que se hace en mydmv.vermont.gov o por teléfono.","p":"Correcto. Toda visita al DMV necesita cita."},"ref":{"doc":"VT","page":17}},{"id":"vt-074","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you fail the online learner's permit test. How long must you wait before you try again?","o":["One hour","At least one day","At least one week","At least one month"],"h1":"It is the shortest wait among the tests.","h2":"If you fail the Vermont knowledge test, you must wait at least one day before taking it again.","p":"Right. Wait at least one day."},"es":{"q":"En Vermont, usted reprueba el examen del permiso de aprendiz por internet. ¿Cuánto debe esperar para intentarlo otra vez?","o":["Una hora","Por lo menos un día","Por lo menos una semana","Por lo menos un mes"],"h1":"Es la espera más corta de los exámenes.","h2":"Si reprueba el examen de conocimientos de Vermont, debe esperar por lo menos un día antes de tomarlo otra vez.","p":"Correcto. Espere por lo menos un día."},"ref":{"doc":"VT","page":18}},{"id":"vt-075","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, where do you take the learner's permit knowledge test?","o":["Only at a DMV office","At a police station","Online, through mydmv.vermont.gov","At your high school only"],"h1":"It is no longer taken in the office.","h2":"The Vermont learner's permit test is taken online through the DMV website, mydmv.vermont.gov.","p":"Right. The permit test is online."},"es":{"q":"En Vermont, ¿dónde se toma el examen de conocimientos del permiso de aprendiz?","o":["Solo en una oficina del DMV","En una estación de policía","Por internet, en mydmv.vermont.gov","Solo en su escuela secundaria"],"h1":"Ya no se toma en la oficina.","h2":"El examen del permiso de aprendiz de Vermont se toma por internet en el sitio del DMV, mydmv.vermont.gov.","p":"Correcto. El examen del permiso es por internet."},"ref":{"doc":"VT","page":2}},{"id":"vt-076","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, you have failed the road test three times. How long must you wait before the next try?","o":["One day","One week","Two weeks","At least one month"],"h1":"The wait gets longer after several failures.","h2":"After failing the Vermont road test three times, you must wait at least one month before testing again.","p":"Right. After three failures, wait at least a month."},"es":{"q":"En Vermont, usted ha reprobado el examen de manejo tres veces. ¿Cuánto debe esperar antes del siguiente intento?","o":["Un día","Una semana","Dos semanas","Por lo menos un mes"],"h1":"La espera es más larga después de varios fracasos.","h2":"Después de reprobar el examen de manejo de Vermont tres veces, debe esperar por lo menos un mes antes de volver a tomarlo.","p":"Correcto. Después de tres fracasos, espere por lo menos un mes."},"ref":{"doc":"VT","page":19}},{"id":"vt-077","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, may you bring your dog in the car during your road test?","o":["No, no animals are allowed in the car during a road test","Yes, if it stays in the back seat","Yes, if it is in a carrier","Only a small dog"],"h1":"The examiner wants no distractions in the car.","h2":"No animals of any kind are allowed in the vehicle during a Vermont road test.","p":"Right. No animals during the road test."},"es":{"q":"En Vermont, ¿puede llevar a su perro en el carro durante el examen de manejo?","o":["No, no se permiten animales en el carro durante el examen","Sí, si va en el asiento de atrás","Sí, si va en una jaula","Solo un perro pequeño"],"h1":"El examinador no quiere distracciones en el carro.","h2":"No se permite ningún animal en el vehículo durante el examen de manejo de Vermont.","p":"Correcto. No se permiten animales durante el examen."},"ref":{"doc":"VT","page":19}},{"id":"vt-078","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, you want to use a rental car for your road test. When is that allowed?","o":["Always","Never, under any condition","Only with a letter from the rental company accepting full responsibility","Only if the rental lasts more than a week"],"h1":"The rental company must agree in writing.","h2":"A rental car may be used for a Vermont road test only if the rental company gives a letter accepting full responsibility for the test.","p":"Right. A letter from the rental company is needed."},"es":{"q":"En Vermont, usted quiere usar un carro rentado para el examen de manejo. ¿Cuándo se permite?","o":["Siempre","Nunca, bajo ninguna condición","Solo con una carta de la compañía de renta que acepte toda la responsabilidad","Solo si la renta dura más de una semana"],"h1":"La compañía de renta debe estar de acuerdo por escrito.","h2":"Un carro rentado se puede usar en el examen de manejo de Vermont solo si la compañía de renta da una carta aceptando toda la responsabilidad.","p":"Correcto. Se necesita una carta de la compañía de renta."},"ref":{"doc":"VT","page":19}},{"id":"vt-079","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, which car can NOT be used for a road test?","o":["A registered, inspected car from another state","A car with antique plates","A car owned by a friend, with insurance","A registered car with a valid inspection sticker"],"h1":"Some special plates may only be used in limited ways.","h2":"No Vermont road test is given in a vehicle with agriculture, antique or exhibit plates, because the law limits how those plates may be used.","p":"Right. Antique plates are not allowed for a road test."},"es":{"q":"En Vermont, ¿qué carro NO se puede usar para el examen de manejo?","o":["Un carro registrado e inspeccionado en otro estado","Un carro con placas de antigüedad","El carro de un amigo, con seguro","Un carro registrado con calcomanía de inspección válida"],"h1":"Algunas placas especiales solo se pueden usar de forma limitada.","h2":"En Vermont no se da el examen de manejo en un vehículo con placas agrícolas, de antigüedad o de exhibición, porque la ley limita el uso de esas placas.","p":"Correcto. Las placas de antigüedad no se permiten en el examen."},"ref":{"doc":"VT","page":19}},{"id":"vt-080","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a junior operator drives for a job during the first year of the license. What is the penalty?","o":["A warning letter","A 10-day recall","A 30-day recall","A 90-day recall"],"h1":"It is the same as for carrying paying passengers.","h2":"Driving in the course of a job during the first year of a Vermont junior license brings a 90-day recall of the license.","p":"Right. Driving for a job brings a 90-day recall."},"es":{"q":"En Vermont, un operador menor maneja para un trabajo durante el primer año de la licencia. ¿Cuál es la sanción?","o":["Una carta de advertencia","Un retiro de 10 días","Un retiro de 30 días","Un retiro de 90 días"],"h1":"Es igual que por llevar pasajeros que pagan.","h2":"Manejar como parte de un trabajo durante el primer año de la licencia de menor en Vermont trae un retiro de la licencia por 90 días.","p":"Correcto. Manejar para un trabajo trae un retiro de 90 días."},"ref":{"doc":"VT","page":21}},{"id":"vt-081","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a junior operator gets one speeding ticket worth 3 points. What happens to the license?","o":["Nothing until 10 points","It is recalled for 90 days","It is recalled for 10 days","It is canceled for one year"],"h1":"For teens, a single speeding ticket of this size is enough.","h2":"A single 3-point speeding violation brings a 90-day recall of a Vermont junior operator's license.","p":"Right. One 3-point speeding ticket means a 90-day recall."},"es":{"q":"En Vermont, un operador menor recibe una multa por exceso de velocidad de 3 puntos. ¿Qué pasa con la licencia?","o":["Nada hasta llegar a 10 puntos","Se retira por 90 días","Se retira por 10 días","Se cancela por un año"],"h1":"Para los jóvenes, una sola multa de este tamaño es suficiente.","h2":"Una sola infracción de velocidad de 3 puntos trae un retiro de 90 días de la licencia de operador menor en Vermont.","p":"Correcto. Una multa de velocidad de 3 puntos significa un retiro de 90 días."},"ref":{"doc":"VT","page":21}},{"id":"vt-082","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, a Diversion or Reparative Board recommends a recall of a teen's provisional license. How long is that recall?","o":["30 days","90 days","6 months","1 year"],"h1":"It is the same length as the recall for teen texting.","h2":"A recommendation from a Diversion or Reparative Board brings a 30-day recall of a Vermont learner's permit or junior license.","p":"Right. That recall lasts 30 days."},"es":{"q":"En Vermont, una Junta de Desvío o Reparación recomienda retirar la licencia provisional de un joven. ¿Cuánto dura ese retiro?","o":["30 días","90 días","6 meses","1 año"],"h1":"Dura lo mismo que el retiro por enviar textos siendo menor.","h2":"Una recomendación de una Junta de Desvío o Reparación trae un retiro de 30 días del permiso de aprendiz o de la licencia de menor en Vermont.","p":"Correcto. Ese retiro dura 30 días."},"ref":{"doc":"VT","page":21}},{"id":"vt-083","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, when a recalled learner's permit or junior license is restored, what reinstatement fee must you pay?","o":["$24","$62","No reinstatement fee","Double the license fee"],"h1":"Recalls of provisional licenses are treated differently from suspensions.","h2":"No reinstatement fee is due in Vermont when a recalled learner's permit or junior operator's license is restored.","p":"Right. There is no reinstatement fee for a restored recall."},"es":{"q":"En Vermont, cuando se devuelve un permiso de aprendiz o una licencia de menor que fue retirada, ¿qué cuota de restablecimiento debe pagar?","o":["$24","$62","Ninguna cuota de restablecimiento","El doble de la cuota de licencia"],"h1":"Los retiros de licencias provisionales se tratan distinto a las suspensiones.","h2":"En Vermont no se paga cuota de restablecimiento cuando se devuelve un permiso de aprendiz o una licencia de operador menor que fue retirada.","p":"Correcto. No hay cuota de restablecimiento al terminar un retiro."},"ref":{"doc":"VT","page":21}},{"id":"vt-084","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how can a parent or guardian suspend their teen's learner's permit or junior license?","o":["By taking the card away at home","By calling the police","By telling the driving school","By writing to the Commissioner of Motor Vehicles"],"h1":"It is done by a letter to the DMV.","h2":"A Vermont parent or guardian may suspend a child's provisional license by writing to the Commissioner of the Department of Motor Vehicles.","p":"Right. The parent writes to the Commissioner."},"es":{"q":"En Vermont, ¿cómo puede un padre, madre o tutor suspender el permiso de aprendiz o la licencia de menor de su hijo?","o":["Quitándole la tarjeta en casa","Llamando a la policía","Avisando a la escuela de manejo","Escribiendo al Comisionado de Vehículos Motorizados"],"h1":"Se hace con una carta al DMV.","h2":"En Vermont, un padre, madre o tutor puede suspender la licencia provisional de su hijo escribiendo al Comisionado del Departamento de Vehículos Motorizados.","p":"Correcto. El padre escribe al Comisionado."},"ref":{"doc":"VT","page":73}},{"id":"vt-085","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what is the total cost of the knowledge test and learner's permit, at the fees printed in the 2024 manual?","o":["$24","$39","$63","$85"],"h1":"It is the test fee of $39 plus the permit fee of $24.","h2":"At the fees printed in the Vermont manual (July 2024), the knowledge test and learner's permit cost $63 in total: $39 for the test and $24 for the permit.","p":"Right. The test and permit cost $63."},"es":{"q":"En Vermont, ¿cuánto cuestan en total el examen de conocimientos y el permiso de aprendiz, según las cuotas del manual de 2024?","o":["$24","$39","$63","$85"],"h1":"Es la cuota del examen de $39 más la del permiso de $24.","h2":"Según las cuotas del manual de Vermont (julio de 2024), el examen de conocimientos y el permiso de aprendiz cuestan $63 en total: $39 por el examen y $24 por el permiso.","p":"Correcto. El examen y el permiso cuestan $63."},"ref":{"doc":"VT","page":23}},{"id":"vt-086","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, how much is the road test fee, as printed in the 2024 manual?","o":["$10","$23","$39","$62"],"h1":"It is the smallest fee on the list.","h2":"The Vermont road test fee printed in the July 2024 manual is $23, paid on top of the license fee.","p":"Right. The road test costs $23."},"es":{"q":"En Vermont, ¿cuánto cuesta el examen de manejo, según el manual de 2024?","o":["$10","$23","$39","$62"],"h1":"Es la cuota más pequeña de la lista.","h2":"La cuota del examen de manejo de Vermont en el manual de julio de 2024 es de $23, que se paga además de la cuota de la licencia.","p":"Correcto. El examen de manejo cuesta $23."},"ref":{"doc":"VT","page":23}},{"id":"vt-087","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a driver's license can be issued for which lengths of time?","o":["1 or 2 years","2 or 4 years","5 or 10 years","8 years only"],"h1":"The fee list shows a shorter and a longer choice.","h2":"A Vermont driver's license is issued for either 2 years or 4 years, with a different fee for each.","p":"Right. Vermont licenses last 2 or 4 years."},"es":{"q":"En Vermont, ¿por cuánto tiempo se puede dar una licencia de manejar?","o":["1 o 2 años","2 o 4 años","5 o 10 años","Solo 8 años"],"h1":"La lista de cuotas muestra una opción corta y una larga.","h2":"La licencia de manejar de Vermont se da por 2 años o por 4 años, con una cuota distinta para cada una.","p":"Correcto. Las licencias de Vermont duran 2 o 4 años."},"ref":{"doc":"VT","page":23}},{"id":"vt-088","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how much does it cost to renew a 4-year driver's license with no motorcycle endorsement, at the 2024 fees?","o":["$24","$39","$62","$78"],"h1":"It costs more than a 2-year license, and less than one with a motorcycle endorsement.","h2":"At the July 2024 fees, renewing a 4-year Vermont driver's license costs $62, or $78 with a motorcycle endorsement.","p":"Right. A 4-year renewal costs $62."},"es":{"q":"En Vermont, ¿cuánto cuesta renovar una licencia de manejar de 4 años sin endoso de motocicleta, según las cuotas de 2024?","o":["$24","$39","$62","$78"],"h1":"Cuesta más que una licencia de 2 años y menos que una con endoso de motocicleta.","h2":"Según las cuotas de julio de 2024, renovar una licencia de Vermont de 4 años cuesta $62, o $78 con endoso de motocicleta.","p":"Correcto. Renovar por 4 años cuesta $62."},"ref":{"doc":"VT","page":23}},{"id":"vt-089","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, how much does it cost to replace a lost license or permit, or to correct its name or address, at the 2024 fees?","o":["$24","$39","$62","It is free"],"h1":"It is the same as the learner's permit fee.","h2":"At the July 2024 fees, replacing a lost Vermont license or permit, or correcting the name or address on it, costs $24.","p":"Right. A replacement costs $24."},"es":{"q":"En Vermont, ¿cuánto cuesta reemplazar una licencia o permiso perdido, o corregir el nombre o la dirección, según las cuotas de 2024?","o":["$24","$39","$62","Es gratis"],"h1":"Es lo mismo que la cuota del permiso de aprendiz.","h2":"Según las cuotas de julio de 2024, reemplazar una licencia o permiso perdido de Vermont, o corregir el nombre o la dirección, cuesta $24.","p":"Correcto. Un reemplazo cuesta $24."},"ref":{"doc":"VT","page":23}},{"id":"vt-090","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how much extra does an Enhanced Driver's License (EDL) cost, at the 2024 fees?","o":["$10","$24","$30","$36"],"h1":"It is added on top of the regular license fee.","h2":"At the July 2024 fees, an Enhanced Driver's License in Vermont costs $36 in addition to any other license fees.","p":"Right. The EDL adds $36."},"es":{"q":"En Vermont, ¿cuánto cuesta de más una Licencia de Manejar Mejorada (EDL), según las cuotas de 2024?","o":["$10","$24","$30","$36"],"h1":"Se suma a la cuota normal de la licencia.","h2":"Según las cuotas de julio de 2024, una Licencia de Manejar Mejorada en Vermont cuesta $36 además de las otras cuotas de la licencia.","p":"Correcto. La EDL agrega $36."},"ref":{"doc":"VT","page":23}},{"id":"vt-091","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, about when does the DMV mail you a renewal application for your license or permit?","o":["About a month before it expires","About a week after it expires","On your birthday each year","About a year before it expires"],"h1":"It arrives shortly before the card runs out.","h2":"The Vermont DMV mails a renewal application about a month before your license or permit expires; you can also renew online.","p":"Right. It comes about a month before it expires."},"es":{"q":"En Vermont, ¿más o menos cuándo le envía el DMV por correo la solicitud de renovación de su licencia o permiso?","o":["Más o menos un mes antes de que venza","Más o menos una semana después de que venza","Cada año en su cumpleaños","Más o menos un año antes de que venza"],"h1":"Llega poco antes de que la tarjeta se venza.","h2":"El DMV de Vermont envía por correo la solicitud de renovación más o menos un mes antes de que venza su licencia o permiso; también puede renovar por internet.","p":"Correcto. Llega más o menos un mes antes del vencimiento."},"ref":{"doc":"VT","page":24}},{"id":"vt-092","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, how long is a license photo good for before it must be updated?","o":["2 years","4 years","6 years","8 years"],"h1":"It lasts through two 4-year licenses.","h2":"A Vermont license photo is valid for 8 years, and it is updated any time you renew in person.","p":"Right. A license photo is good for 8 years."},"es":{"q":"En Vermont, ¿cuánto tiempo vale la foto de la licencia antes de que se deba actualizar?","o":["2 años","4 años","6 años","8 años"],"h1":"Dura dos licencias de 4 años.","h2":"La foto de la licencia de Vermont vale por 8 años, y se actualiza cada vez que usted renueva en persona.","p":"Correcto. La foto de la licencia vale 8 años."},"ref":{"doc":"VT","page":24}},{"id":"vt-093","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, you move to a new address. How soon must you tell the DMV?","o":["Within 10 days","Within 15 days","Within 30 days","Within 60 days"],"h1":"It is about one month.","h2":"If you change your name or address, you must report it to the Vermont DMV within 30 days.","p":"Right. Report it within 30 days."},"es":{"q":"En Vermont, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar al DMV?","o":["En 10 días","En 15 días","En 30 días","En 60 días"],"h1":"Es más o menos un mes.","h2":"Si cambia su nombre o su dirección, debe avisar al DMV de Vermont en un plazo de 30 días.","p":"Correcto. Avise en 30 días."},"ref":{"doc":"VT","page":24}},{"id":"vt-094","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you got married and changed your last name. How must you update your license?","o":["Online at mydmv.vermont.gov","In person at the DMV","By mail only","You do not need to update it"],"h1":"An address can be changed online, but a name cannot.","h2":"In Vermont, an address can be updated online, but a name change on your license requires an in-person visit to the DMV.","p":"Right. A name change must be done in person."},"es":{"q":"En Vermont, usted se casó y cambió su apellido. ¿Cómo debe actualizar su licencia?","o":["Por internet en mydmv.vermont.gov","En persona en el DMV","Solo por correo","No necesita actualizarla"],"h1":"La dirección se puede cambiar por internet, pero el nombre no.","h2":"En Vermont, la dirección se puede actualizar por internet, pero el cambio de nombre en la licencia requiere una visita en persona al DMV.","p":"Correcto. El cambio de nombre se hace en persona."},"ref":{"doc":"VT","page":24}},{"id":"vt-095","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, you bring a photocopy of your birth certificate to the DMV to prove who you are. Will it be accepted?","o":["No, documents must be originals or copies certified by the agency that issued them","Yes, any clear photocopy is fine","Yes, if a friend signs it","Yes, if it is sent by fax"],"h1":"Photocopies and faxes are a problem.","h2":"The Vermont DMV accepts only original documents or copies certified by the issuing agency; photocopies and faxes are not accepted.","p":"Right. Bring originals or certified copies."},"es":{"q":"En Vermont, usted lleva al DMV una fotocopia de su acta de nacimiento para probar quién es. ¿Se la aceptarán?","o":["No, los documentos deben ser originales o copias certificadas por la agencia que los emitió","Sí, cualquier fotocopia clara sirve","Sí, si la firma un amigo","Sí, si se envía por fax"],"h1":"Las fotocopias y los faxes son un problema.","h2":"El DMV de Vermont solo acepta documentos originales o copias certificadas por la agencia que los emitió; no acepta fotocopias ni faxes.","p":"Correcto. Lleve originales o copias certificadas."},"ref":{"doc":"VT","page":8}},{"id":"vt-096","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, proof of lawful status in the United States is required only for which cards?","o":["Every learner's permit","Every regular license","A Driver Privilege Card","A REAL ID or Enhanced Driver's License"],"h1":"One card type is made for federal ID use, and another for crossing the border.","h2":"Vermont asks for proof of lawful status in the United States only for a REAL ID card or license and for an Enhanced Driver's License.","p":"Right. Lawful status is needed only for REAL ID and the EDL."},"es":{"q":"En Vermont, ¿para qué tarjetas se exige prueba de estatus legal en los Estados Unidos?","o":["Para todo permiso de aprendiz","Para toda licencia normal","Para una Tarjeta de Privilegio de Manejo","Para una REAL ID o una Licencia de Manejar Mejorada"],"h1":"Un tipo de tarjeta es para identificación federal, y otro para cruzar la frontera.","h2":"Vermont pide prueba de estatus legal en los Estados Unidos solo para una tarjeta o licencia REAL ID y para una Licencia de Manejar Mejorada.","p":"Correcto. El estatus legal solo se pide para REAL ID y la EDL."},"ref":{"doc":"VT","page":8}},{"id":"vt-097","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, which address may you NOT use as your residential address on a license application?","o":["Your street address","A post office box","Your rural road address used by the post office","The street address where you live with relatives"],"h1":"Your home address must show where you actually live.","h2":"The residential address on a Vermont license application must be a street or highway address, not a post office box; a P.O. box may be used only as a mailing address.","p":"Right. A P.O. box cannot be your residential address."},"es":{"q":"En Vermont, ¿qué dirección NO puede usar como dirección de residencia en una solicitud de licencia?","o":["La dirección de su calle","Un apartado postal","Su dirección rural usada por el correo","La dirección de la calle donde vive con familiares"],"h1":"Su dirección de casa debe mostrar dónde vive de verdad.","h2":"La dirección de residencia en una solicitud de licencia de Vermont debe ser una dirección de calle o carretera, no un apartado postal; el apartado solo se puede usar como dirección de correo.","p":"Correcto. Un apartado postal no puede ser su dirección de residencia."},"ref":{"doc":"VT","page":10}},{"id":"vt-098","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, you live in New Hampshire. When may you get a Vermont learner's permit?","o":["Never","Any time, if you work in Vermont","Only to take a driver education course in Vermont","Only if you own a car registered in Vermont"],"h1":"It is tied to a class.","h2":"A person who does not live in Vermont may get a Vermont learner's permit only to take part in a driver education course, with a letter from the school.","p":"Right. Only for a Vermont driver education course."},"es":{"q":"En Vermont, usted vive en New Hampshire. ¿Cuándo puede obtener un permiso de aprendiz de Vermont?","o":["Nunca","En cualquier momento, si trabaja en Vermont","Solo para tomar un curso de educación vial en Vermont","Solo si tiene un carro registrado en Vermont"],"h1":"Está relacionado con una clase.","h2":"Una persona que no vive en Vermont puede obtener un permiso de aprendiz de Vermont solo para tomar un curso de educación vial, con una carta de la escuela.","p":"Correcto. Solo para un curso de educación vial en Vermont."},"ref":{"doc":"VT","page":10}},{"id":"vt-099","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, a temporary visitor applies for a license. The DMV will not issue it if less than how much lawful presence time remains?","o":["7 days","14 days","60 days","30 days"],"h1":"It is about one month.","h2":"The Vermont DMV will not issue a license or ID if the applicant has less than 30 days of lawful presence remaining.","p":"Right. At least 30 days must remain."},"es":{"q":"En Vermont, un visitante temporal solicita una licencia. El DMV no la dará si le queda menos de, ¿cuánto tiempo de estancia legal?","o":["7 días","14 días","60 días","30 días"],"h1":"Es más o menos un mes.","h2":"El DMV de Vermont no da una licencia ni una identificación si al solicitante le quedan menos de 30 días de estancia legal.","p":"Correcto. Deben quedar por lo menos 30 días."},"ref":{"doc":"VT","page":9}},{"id":"vt-100","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, what is true about a Driver Privilege Card?","o":["It is not REAL ID compliant, and it does not require proof of legal presence","It is the same as a REAL ID","It can be used to cross the Canadian border","It is only for drivers over 65"],"h1":"It is a Vermont license for residents who cannot or do not want to show lawful status.","h2":"A Vermont Driver Privilege Card is a license or permit that is not REAL ID compliant, and getting one does not require proof of legal presence or citizenship.","p":"Right. It is not REAL ID and needs no proof of legal presence."},"es":{"q":"En Vermont, ¿qué es cierto sobre la Tarjeta de Privilegio de Manejo?","o":["No cumple con REAL ID y no requiere prueba de estancia legal","Es lo mismo que una REAL ID","Sirve para cruzar la frontera con Canadá","Es solo para conductores mayores de 65"],"h1":"Es una licencia de Vermont para residentes que no pueden o no quieren mostrar estatus legal.","h2":"La Tarjeta de Privilegio de Manejo de Vermont es una licencia o permiso que no cumple con REAL ID, y para obtenerla no se pide prueba de estancia legal ni de ciudadanía.","p":"Correcto. No es REAL ID y no pide prueba de estancia legal."},"ref":{"doc":"VT","page":11}},{"id":"vt-101","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what extra document does an Enhanced Driver's License (EDL) require?","o":["A letter from your employer","A vehicle registration","Proof of U.S. citizenship","A medical form"],"h1":"The EDL can be used to come back into the country by land or sea.","h2":"An Enhanced Driver's License requires proof of U.S. citizenship, and it can be used instead of a passport when returning from Canada, Mexico, the Caribbean or Bermuda by land or sea.","p":"Right. The EDL needs proof of U.S. citizenship."},"es":{"q":"En Vermont, ¿qué documento adicional pide la Licencia de Manejar Mejorada (EDL)?","o":["Una carta de su empleador","El registro de un vehículo","Prueba de ciudadanía estadounidense","Un formulario médico"],"h1":"La EDL se puede usar para regresar al país por tierra o por mar.","h2":"La Licencia de Manejar Mejorada pide prueba de ciudadanía estadounidense, y se puede usar en vez del pasaporte al regresar de Canadá, México, el Caribe o Bermudas por tierra o por mar.","p":"Correcto. La EDL pide prueba de ciudadanía estadounidense."},"ref":{"doc":"VT","page":9}},{"id":"vt-102","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, do you need documents to prove the height, weight, eye color or gender you list on your license?","o":["Yes, a doctor's note","No, you choose these yourself and need no documents","Yes, a birth certificate","Only for eye color"],"h1":"Vermont calls these self-designated.","h2":"Height, weight, eye color and gender on a Vermont license are self-designated, so you do not need documents to confirm them.","p":"Right. No documents are needed for these."},"es":{"q":"En Vermont, ¿necesita documentos para probar la estatura, el peso, el color de ojos o el género que pone en su licencia?","o":["Sí, una nota del médico","No, usted los elige y no necesita documentos","Sí, el acta de nacimiento","Solo para el color de ojos"],"h1":"Vermont los llama datos autodesignados.","h2":"La estatura, el peso, el color de ojos y el género en una licencia de Vermont son autodesignados, así que no necesita documentos para confirmarlos.","p":"Correcto. No se necesitan documentos para estos datos."},"ref":{"doc":"VT","page":11}},{"id":"vt-103","scope":"VT","cat":"licensing","sign":null,"c":3,"en":{"q":"In Vermont, your license is suspended in another state. You apply for a Vermont license. What happens?","o":["You get a Vermont license right away","You get a Vermont license, but only for daytime","You pay a fee and get a Vermont license","You are denied until you show you have been reinstated or cleared in that state"],"h1":"A national database is checked when you apply.","h2":"Vermont checks the national Problem Driver Pointer System, and a person suspended in another state is denied a Vermont license or permit until proof of reinstatement there is received.","p":"Right. You must be cleared in the other state first."},"es":{"q":"En Vermont, su licencia está suspendida en otro estado. Usted solicita una licencia de Vermont. ¿Qué pasa?","o":["Recibe la licencia de Vermont de inmediato","Recibe la licencia de Vermont, pero solo para el día","Paga una cuota y recibe la licencia de Vermont","Se la niegan hasta que muestre que fue restablecido o aclarado en ese estado"],"h1":"Al solicitar se revisa una base de datos nacional.","h2":"Vermont revisa el sistema nacional de conductores con problemas (PDPS), y a una persona suspendida en otro estado se le niega la licencia o el permiso de Vermont hasta recibir prueba de que fue restablecida allí.","p":"Correcto. Primero debe quedar aclarado en el otro estado."},"ref":{"doc":"VT","page":7}},{"id":"vt-104","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, a person lies about their identity on a license application. Besides a fine or jail, what happens to their driving privilege?","o":["Nothing","A 10-day suspension","A 90-day suspension","A lifetime ban"],"h1":"It is about three months.","h2":"In Vermont, using a false identity on a license, permit or registration application can bring a fine up to $1,000, up to two years in jail, and a 90-day suspension of the right to drive.","p":"Right. The driving privilege is suspended for 90 days."},"es":{"q":"En Vermont, una persona miente sobre su identidad en una solicitud de licencia. Además de multa o cárcel, ¿qué pasa con su privilegio de manejar?","o":["Nada","Una suspensión de 10 días","Una suspensión de 90 días","Una prohibición de por vida"],"h1":"Son unos tres meses.","h2":"En Vermont, usar una identidad falsa en una solicitud de licencia, permiso o registro puede traer una multa de hasta $1,000, hasta dos años de cárcel y una suspensión de 90 días del derecho a manejar.","p":"Correcto. El privilegio de manejar se suspende 90 días."},"ref":{"doc":"VT","page":7}},{"id":"vt-105","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a person under 21 gets a ticket for having alcohol. How soon must they contact the Teen Alcohol Safety Program (TASP)?","o":["Within 5 days","Within 15 days","Within 30 days","Within 60 days"],"h1":"It is about two weeks.","h2":"A minor ticketed for alcohol in Vermont must contact the Teen Alcohol Safety Program within 15 days; otherwise the case goes to the Judicial Bureau, with a $300 penalty and a 90-day license suspension if found liable.","p":"Right. Contact TASP within 15 days."},"es":{"q":"En Vermont, una persona menor de 21 recibe una multa por tener alcohol. ¿En cuánto tiempo debe comunicarse con el Programa de Seguridad sobre Alcohol para Jóvenes (TASP)?","o":["En 5 días","En 15 días","En 30 días","En 60 días"],"h1":"Son unas dos semanas.","h2":"Un menor multado por alcohol en Vermont debe comunicarse con el Programa TASP en un plazo de 15 días; si no, el caso pasa a la Oficina Judicial, con una multa de $300 y una suspensión de la licencia de 90 días si lo encuentran responsable.","p":"Correcto. Comuníquese con TASP en 15 días."},"ref":{"doc":"VT","page":7}},{"id":"vt-106","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, you have epilepsy or insulin-treated diabetes and want a learner's permit. What must you do first?","o":["Tell the DMV Driver Improvement Section before making a test appointment","Nothing, just take the test","Tell only the road test examiner","Wait until age 21"],"h1":"A doctor's form is part of the process.","h2":"A person with a condition that may cause loss of consciousness, such as epilepsy or diabetes needing insulin, must notify the Vermont DMV Driver Improvement Section before making an exam appointment; a doctor then completes a medical form.","p":"Right. Notify the DMV first, and a doctor fills out a form."},"es":{"q":"En Vermont, usted tiene epilepsia o diabetes tratada con insulina y quiere un permiso de aprendiz. ¿Qué debe hacer primero?","o":["Avisar a la Sección de Mejoramiento de Conductores del DMV antes de hacer la cita del examen","Nada, solo tomar el examen","Avisar solo al examinador del examen de manejo","Esperar hasta los 21 años"],"h1":"Un formulario del médico es parte del proceso.","h2":"Una persona con una condición que puede causar pérdida del conocimiento, como epilepsia o diabetes que necesita insulina, debe avisar a la Sección de Mejoramiento de Conductores del DMV de Vermont antes de hacer la cita del examen; luego un médico llena un formulario.","p":"Correcto. Avise primero al DMV, y un médico llena un formulario."},"ref":{"doc":"VT","page":71}},{"id":"vt-107","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how much does a Disabled Parking Placard cost?","o":["$24","$10 per year","Nothing, there is no fee","$62"],"h1":"The state does not charge for it.","h2":"There is no fee for a Vermont Disabled Parking Placard; a doctor fills out part of the application.","p":"Right. The placard is free."},"es":{"q":"En Vermont, ¿cuánto cuesta un Permiso de Estacionamiento para Discapacitados?","o":["$24","$10 por año","Nada, no tiene costo","$62"],"h1":"El estado no cobra por él.","h2":"El Permiso de Estacionamiento para Discapacitados de Vermont no tiene costo; un médico llena parte de la solicitud.","p":"Correcto. El permiso es gratis."},"ref":{"doc":"VT","page":71}},{"id":"vt-108","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, a driver with a disabled plate or placard asks for help at a self-service gas station. What does the law say?","o":["The station may refuse","An attendant must pump the gas, at the self-service price","The driver pays the full-service price","The driver must call ahead"],"h1":"The driver should not pay more for the help.","h2":"Under Vermont law, a self-service station must have an attendant pump gas for a driver with a disabled plate or placard when asked, at the self-service price.","p":"Right. An attendant pumps the gas at the self-service price."},"es":{"q":"En Vermont, un conductor con placa o permiso de discapacitado pide ayuda en una gasolinera de autoservicio. ¿Qué dice la ley?","o":["La gasolinera puede negarse","Un empleado debe echar la gasolina, al precio de autoservicio","El conductor paga el precio de servicio completo","El conductor debe llamar antes"],"h1":"El conductor no debe pagar más por la ayuda.","h2":"Según la ley de Vermont, una gasolinera de autoservicio debe hacer que un empleado eche la gasolina a un conductor con placa o permiso de discapacitado cuando lo pide, al precio de autoservicio.","p":"Correcto. Un empleado echa la gasolina al precio de autoservicio."},"ref":{"doc":"VT","page":72}},{"id":"vt-109","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, you need a commercial driver's license (CDL) to drive a vehicle designed to carry how many people, counting the driver?","o":["10 or more","16 or more","20 or more","30 or more"],"h1":"It is the same number that makes a school bus need a CDL.","h2":"In Vermont a commercial driver's license is required for vehicles rated over 26,000 pounds, vehicles carrying hazardous materials, or vehicles designed to carry 16 or more people including the driver.","p":"Right. 16 or more people, counting the driver, needs a CDL."},"es":{"q":"En Vermont, necesita licencia comercial (CDL) para manejar un vehículo hecho para llevar, ¿cuántas personas, contando al conductor?","o":["10 o más","16 o más","20 o más","30 o más"],"h1":"Es el mismo número que hace que un autobús escolar necesite CDL.","h2":"En Vermont se necesita licencia comercial para vehículos de más de 26,000 libras, vehículos con materiales peligrosos o vehículos hechos para llevar 16 o más personas, contando al conductor.","p":"Correcto. Para 16 o más personas, contando al conductor, se necesita CDL."},"ref":{"doc":"VT","page":70}},{"id":"vt-110","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, the driver manual compares the steering wheel to a clock. Where does it suggest you hold the wheel?","o":["At 12 o'clock with one hand","At 6 o'clock with both hands","At 11 and 1 o'clock","At 9 and 3, or 8 and 4 o'clock"],"h1":"Your hands should be on the sides of the wheel.","h2":"The Vermont manual recommends holding the steering wheel at the 9 and 3 or the 8 and 4 o'clock positions.","p":"Right. Hold the wheel at 9 and 3, or 8 and 4."},"es":{"q":"En Vermont, el manual compara el volante con un reloj. ¿Dónde sugiere que sostenga el volante?","o":["A las 12 con una mano","A las 6 con las dos manos","A las 11 y a la 1","A las 9 y 3, o a las 8 y 4"],"h1":"Sus manos deben estar a los lados del volante.","h2":"El manual de Vermont recomienda sostener el volante en la posición de las 9 y 3 o de las 8 y 4.","p":"Correcto. Sostenga el volante a las 9 y 3, o a las 8 y 4."},"ref":{"doc":"VT","page":25}},{"id":"vt-111","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, after seeing danger, about how long does it take the average driver to press the brake?","o":["About 1/4 of a second","About 3/4 of a second","About 2 seconds","About 4 seconds"],"h1":"It is less than one second.","h2":"The Vermont manual says it takes the average driver about 3/4 of a second after seeing danger to apply the brakes, and the car keeps moving during that time.","p":"Right. About 3/4 of a second."},"es":{"q":"En Vermont, después de ver un peligro, ¿más o menos cuánto tarda el conductor promedio en pisar el freno?","o":["Más o menos 1/4 de segundo","Más o menos 3/4 de segundo","Más o menos 2 segundos","Más o menos 4 segundos"],"h1":"Es menos de un segundo.","h2":"El manual de Vermont dice que el conductor promedio tarda más o menos 3/4 de segundo en frenar después de ver un peligro, y el carro sigue avanzando en ese tiempo.","p":"Correcto. Más o menos 3/4 de segundo."},"ref":{"doc":"VT","page":26}},{"id":"vt-112","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what is the distance your car travels from the moment you see danger until you step on the brake called?","o":["Braking distance","Following distance","Reaction distance","Passing distance"],"h1":"It happens before the brakes do anything.","h2":"The distance traveled from seeing danger until you step on the brake is called reaction distance; the distance after the brakes are applied is braking distance.","p":"Right. That is reaction distance."},"es":{"q":"En Vermont, ¿cómo se llama la distancia que recorre su carro desde que ve un peligro hasta que pisa el freno?","o":["Distancia de frenado","Distancia de seguimiento","Distancia de reacción","Distancia para rebasar"],"h1":"Ocurre antes de que los frenos hagan algo.","h2":"La distancia recorrida desde que ve el peligro hasta que pisa el freno se llama distancia de reacción; la distancia después de frenar es la distancia de frenado.","p":"Correcto. Es la distancia de reacción."},"ref":{"doc":"VT","page":26}},{"id":"vt-113","scope":"VT","cat":"signals","sign":null,"c":1,"en":{"q":"In Vermont, the law says you must signal a turn or lane change at least how far before you make it?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"Signaling 3 to 5 seconds ahead covers it.","h2":"Vermont law requires a turn signal at least 100 feet before turning or changing lanes; signaling 3 to 5 seconds ahead meets this rule.","p":"Right. Signal at least 100 feet ahead."},"es":{"q":"En Vermont, la ley dice que debe señalar una vuelta o un cambio de carril, ¿por lo menos a qué distancia antes de hacerlo?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Señalar de 3 a 5 segundos antes lo cumple.","h2":"La ley de Vermont exige poner la direccional por lo menos 100 pies antes de dar vuelta o cambiar de carril; señalar de 3 a 5 segundos antes cumple esta regla.","p":"Correcto. Señale por lo menos 100 pies antes."},"ref":{"doc":"VT","page":26}},{"id":"vt-114","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, when you prepare to turn left from a two-lane road, where should you position your car, if it is safe?","o":["Within one foot of the center line","Three feet from the right edge","In the middle of your lane","On the right shoulder"],"h1":"Get close to the line that divides the two directions.","h2":"Before a left turn in Vermont, move your car to within one foot of the center line, if it is safe, so traffic behind can pass on your right.","p":"Right. Move within one foot of the center line."},"es":{"q":"En Vermont, cuando se prepara para dar vuelta a la izquierda desde una calle de dos carriles, ¿dónde debe poner su carro, si es seguro?","o":["A un pie o menos de la línea central","A tres pies del borde derecho","En medio de su carril","En el acotamiento derecho"],"h1":"Acérquese a la línea que divide los dos sentidos.","h2":"Antes de una vuelta a la izquierda en Vermont, ponga su carro a un pie o menos de la línea central, si es seguro, para que el tráfico de atrás pueda pasar por su derecha.","p":"Correcto. Póngase a un pie o menos de la línea central."},"ref":{"doc":"VT","page":26}},{"id":"vt-115","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, you are stopped and waiting to turn left across oncoming traffic. How should you keep your front wheels?","o":["Turned fully to the left","Turned to the right","It does not matter","Straight, until you are ready to turn"],"h1":"Think about what happens if someone hits you from behind.","h2":"Keep your wheels straight while waiting to turn left, so a crash from behind will not push you into oncoming traffic.","p":"Right. Keep the wheels straight until you turn."},"es":{"q":"En Vermont, usted está detenido esperando para dar vuelta a la izquierda cruzando el tráfico que viene de frente. ¿Cómo debe tener las llantas delanteras?","o":["Giradas totalmente a la izquierda","Giradas a la derecha","No importa","Derechas, hasta que esté listo para dar vuelta"],"h1":"Piense qué pasa si alguien lo choca por detrás.","h2":"Mantenga las llantas derechas mientras espera para dar vuelta a la izquierda, para que un choque por detrás no lo empuje hacia el tráfico que viene de frente.","p":"Correcto. Mantenga las llantas derechas hasta dar vuelta."},"ref":{"doc":"VT","page":26}},{"id":"vt-116","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, as you approach a right turn, about how far from the right side of the road should your car be?","o":["Touching the curb","About one inch","About three feet","Near the center line"],"h1":"Stay close to the right, but not on the curb.","h2":"As you approach a right turn in Vermont, your car should be about three feet from the right side of the road, and you should not swing left first.","p":"Right. About three feet from the right side."},"es":{"q":"En Vermont, al acercarse a una vuelta a la derecha, ¿más o menos a qué distancia del lado derecho de la calle debe estar su carro?","o":["Tocando la banqueta","A más o menos una pulgada","A más o menos tres pies","Cerca de la línea central"],"h1":"Quédese cerca de la derecha, pero no sobre la banqueta.","h2":"Al acercarse a una vuelta a la derecha en Vermont, su carro debe estar a más o menos tres pies del lado derecho de la calle, y no debe abrirse primero a la izquierda.","p":"Correcto. A más o menos tres pies del lado derecho."},"ref":{"doc":"VT","page":27}},{"id":"vt-117","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, you turn onto a street with two lanes going your way. Which lane should you turn into?","o":["The nearest lane","The far lane","Either lane, then switch during the turn","The lane with less traffic, crossing over if needed"],"h1":"Do not swing wide across lanes.","h2":"When turning into a street with more than one lane in your direction, turn into the nearest lane, then keep right unless passing or turning.","p":"Right. Turn into the nearest lane."},"es":{"q":"En Vermont, usted da vuelta hacia una calle con dos carriles en su sentido. ¿A qué carril debe entrar?","o":["Al carril más cercano","Al carril más lejano","A cualquiera, y cambiarse durante la vuelta","Al carril con menos tráfico, cruzando si hace falta"],"h1":"No se abra cruzando carriles.","h2":"Al dar vuelta hacia una calle con más de un carril en su sentido, entre al carril más cercano y luego manténgase a la derecha, salvo para rebasar o dar vuelta.","p":"Correcto. Entre al carril más cercano."},"ref":{"doc":"VT","page":27}},{"id":"vt-118","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, two cars arrive at a four-way stop at about the same time from different directions. Who should go first?","o":["The car on the left","The car on the right","The larger vehicle","The car going straight, always"],"h1":"The driver on the left waits.","h2":"At a Vermont four-way stop, if two vehicles arrive at about the same time, the driver on the left yields to the driver on the right.","p":"Right. The car on the right goes first."},"es":{"q":"En Vermont, dos carros llegan a un alto de cuatro vías más o menos al mismo tiempo desde distintas direcciones. ¿Quién debe pasar primero?","o":["El carro de la izquierda","El carro de la derecha","El vehículo más grande","El carro que va derecho, siempre"],"h1":"El conductor de la izquierda espera.","h2":"En un alto de cuatro vías en Vermont, si dos vehículos llegan más o menos al mismo tiempo, el conductor de la izquierda cede el paso al de la derecha.","p":"Correcto. Pasa primero el carro de la derecha."},"ref":{"doc":"VT","page":28}},{"id":"vt-119","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, you are pulling onto a road from a driveway, alley or parking lot. Who has the right of way?","o":["All traffic already on the road","You do, if you signal","Whoever is going faster","You do, if the road is a small street"],"h1":"You are joining traffic that is already moving.","h2":"A driver coming onto a road from a driveway, alley, parking lot or the stem of a T-intersection must yield to all traffic on the road.","p":"Right. Yield to all traffic on the road."},"es":{"q":"En Vermont, usted sale a una calle desde una entrada de casa, un callejón o un estacionamiento. ¿Quién tiene el derecho de paso?","o":["Todo el tráfico que ya está en la calle","Usted, si pone la direccional","El que vaya más rápido","Usted, si la calle es pequeña"],"h1":"Usted se está uniendo a un tráfico que ya va en movimiento.","h2":"Un conductor que entra a una calle desde una entrada, un callejón, un estacionamiento o la base de una intersección en T debe ceder el paso a todo el tráfico de la calle.","p":"Correcto. Ceda el paso a todo el tráfico de la calle."},"ref":{"doc":"VT","page":28}},{"id":"vt-120","scope":"VT","cat":"signals","sign":null,"c":2,"en":{"q":"In Vermont, you come to an intersection where the traffic light is completely dark because of a power failure. What should you do?","o":["Drive through without slowing","Treat it like a yield sign","Stop as if there were stop signs in all directions","Honk and keep going"],"h1":"No light means everyone takes turns.","h2":"When a traffic signal is dark, as in a power failure, Vermont drivers must stop as if there were stop signs in all directions.","p":"Right. Treat it as a stop in all directions."},"es":{"q":"En Vermont, llega a una intersección donde el semáforo está totalmente apagado por un corte de luz. ¿Qué debe hacer?","o":["Pasar sin bajar la velocidad","Tratarlo como señal de ceder el paso","Detenerse como si hubiera señales de alto en todas las direcciones","Tocar el claxon y seguir"],"h1":"Sin luz, todos se turnan.","h2":"Cuando un semáforo está apagado, como en un corte de luz, en Vermont se debe parar como si hubiera señales de alto en todas las direcciones.","p":"Correcto. Trátelo como un alto en todas las direcciones."},"ref":{"doc":"VT","page":31}},{"id":"vt-121","scope":"VT","cat":"signals","sign":null,"c":3,"en":{"q":"In Vermont, may you turn right at a steady red light (a red circle)?","o":["Never","Only if a police officer is there","Yes, without stopping if the way is clear","Usually yes, after a full stop and yielding, unless a sign forbids it"],"h1":"It is usually allowed, but with conditions.","h2":"In Vermont, a right turn at a circular red light is usually allowed after a complete stop, a scan of the intersection and yielding to pedestrians and vehicles, unless a sign says no turn on red.","p":"Right. Stop fully, yield, then turn unless a sign forbids it."},"es":{"q":"En Vermont, ¿puede dar vuelta a la derecha con una luz roja fija (un círculo rojo)?","o":["Nunca","Solo si hay un policía","Sí, sin detenerse si el camino está libre","Por lo general sí, después de un alto total y de ceder el paso, salvo que una señal lo prohíba"],"h1":"Por lo general se permite, pero con condiciones.","h2":"En Vermont, una vuelta a la derecha con luz roja circular por lo general se permite después de un alto total, revisar la intersección y ceder el paso a peatones y vehículos, salvo que una señal prohíba la vuelta en rojo.","p":"Correcto. Pare por completo, ceda el paso y dé vuelta, salvo que una señal lo prohíba."},"ref":{"doc":"VT","page":31}},{"id":"vt-122","scope":"VT","cat":"signals","sign":null,"c":1,"en":{"q":"In Vermont, you want to turn right, and the signal shows a steady red arrow pointing right. What should you do?","o":["Turn after a full stop","Wait; do not turn right on a red arrow","Turn if no pedestrians are present","Turn without stopping"],"h1":"An arrow is stricter than a red circle.","h2":"The Vermont manual says not to turn right on a red arrow; wait until the arrow changes.","p":"Right. Do not turn right on a red arrow."},"es":{"q":"En Vermont, usted quiere dar vuelta a la derecha y el semáforo muestra una flecha roja fija hacia la derecha. ¿Qué debe hacer?","o":["Dar vuelta después de un alto total","Esperar; no dé vuelta a la derecha con flecha roja","Dar vuelta si no hay peatones","Dar vuelta sin detenerse"],"h1":"Una flecha es más estricta que un círculo rojo.","h2":"El manual de Vermont dice que no se debe dar vuelta a la derecha con flecha roja; espere a que la flecha cambie.","p":"Correcto. No dé vuelta a la derecha con flecha roja."},"ref":{"doc":"VT","page":38}},{"id":"vt-123","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, police vehicles use flashing lights of which color?","o":["Blue, or blue and white","Green","Amber (yellow-orange)","Purple"],"h1":"In Vermont, red lights are for ambulances and fire trucks.","h2":"Vermont law uses blue or blue-and-white lights for law enforcement vehicles, red or red-and-white for ambulances and fire trucks, and amber for tow and repair trucks.","p":"Right. Vermont police use blue lights."},"es":{"q":"En Vermont, los vehículos de policía usan luces intermitentes, ¿de qué color?","o":["Azul, o azul y blanco","Verde","Ámbar (amarillo anaranjado)","Morado"],"h1":"En Vermont, las luces rojas son para ambulancias y bomberos.","h2":"La ley de Vermont usa luces azules o azules y blancas para la policía, rojas o rojas y blancas para ambulancias y bomberos, y ámbar para grúas y vehículos de reparación.","p":"Correcto. La policía de Vermont usa luces azules."},"ref":{"doc":"VT","page":null}},{"id":"vt-124","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, when you park on a two-lane road, how close to the curb or edge must your right wheels be?","o":["Within 6 inches","Within 12 inches","Within 18 inches","Within 24 inches"],"h1":"It is one foot.","h2":"When parking on a two-lane road in Vermont, your right wheels must be within 12 inches of the right side of the road or curb.","p":"Right. Within 12 inches of the curb."},"es":{"q":"En Vermont, cuando se estaciona en una calle de dos carriles, ¿qué tan cerca de la banqueta o del borde deben estar sus llantas derechas?","o":["A 6 pulgadas o menos","A 12 pulgadas o menos","A 18 pulgadas o menos","A 24 pulgadas o menos"],"h1":"Es un pie.","h2":"Al estacionarse en una calle de dos carriles en Vermont, sus llantas derechas deben estar a 12 pulgadas o menos del lado derecho de la calle o de la banqueta.","p":"Correcto. A 12 pulgadas o menos de la banqueta."},"ref":{"doc":"VT","page":29}},{"id":"vt-125","scope":"VT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Vermont, which way must your car face when you park along a street?","o":["Either way","Against the flow of traffic","In the same direction as traffic","Toward the nearest store"],"h1":"Park the way you would be driving in that lane.","h2":"In Vermont, a parked vehicle must face the same direction as the traffic flow, and you must not cross the center line to park.","p":"Right. Park facing the same way as traffic."},"es":{"q":"En Vermont, ¿hacia dónde debe mirar su carro cuando se estaciona en la calle?","o":["Hacia cualquier lado","En contra del tráfico","En el mismo sentido que el tráfico","Hacia la tienda más cercana"],"h1":"Estaciónese como si fuera manejando en ese carril.","h2":"En Vermont, un vehículo estacionado debe quedar en el mismo sentido que el tráfico, y no debe cruzar la línea central para estacionarse.","p":"Correcto. Estaciónese en el mismo sentido que el tráfico."},"ref":{"doc":"VT","page":29}},{"id":"vt-126","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, you must park on a highway in a rural area. Where must your wheels be?","o":["All wheels off the traveled part of the road","Two wheels on the road, two on the shoulder","In the travel lane, with flashers on","On the center line"],"h1":"Leave the lanes completely clear.","h2":"When parking on a rural Vermont highway, all of your wheels must be off the traveled portion of the road.","p":"Right. All wheels off the traveled road."},"es":{"q":"En Vermont, usted debe estacionarse en una carretera en una zona rural. ¿Dónde deben estar sus llantas?","o":["Todas fuera de la parte por donde se circula","Dos en la carretera y dos en el acotamiento","En el carril, con las intermitentes","Sobre la línea central"],"h1":"Deje los carriles totalmente libres.","h2":"Al estacionarse en una carretera rural de Vermont, todas sus llantas deben quedar fuera de la parte de la carretera por donde se circula.","p":"Correcto. Todas las llantas fuera de la carretera."},"ref":{"doc":"VT","page":29}},{"id":"vt-127","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, you may not park within how many feet of the nearest rail of a railroad crossing?","o":["10 feet","15 feet","30 feet","50 feet"],"h1":"It is more than the distance where you stop for a train.","h2":"Vermont drivers may not park on railroad tracks or within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the rail."},"es":{"q":"En Vermont, no se puede estacionar a menos de, ¿cuántos pies del riel más cercano de un cruce de ferrocarril?","o":["10 pies","15 pies","30 pies","50 pies"],"h1":"Es más que la distancia a la que se detiene por un tren.","h2":"En Vermont no se puede estacionar sobre las vías ni a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. Quédese por lo menos a 50 pies del riel."},"ref":{"doc":"VT","page":29}},{"id":"vt-128","scope":"VT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Vermont, you may not park within how many feet of a crosswalk at an intersection?","o":["6 feet","10 feet","20 feet","50 feet"],"h1":"It is more than the fire hydrant distance, but less than 30.","h2":"In Vermont, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay 20 feet from the crosswalk."},"es":{"q":"En Vermont, no se puede estacionar a menos de, ¿cuántos pies de un cruce peatonal en una intersección?","o":["6 pies","10 pies","20 pies","50 pies"],"h1":"Es más que la distancia de un hidrante, pero menos de 30.","h2":"En Vermont no se puede estacionar a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese a 20 pies del cruce peatonal."},"ref":{"doc":"VT","page":29}},{"id":"vt-129","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, you may not park within how many feet of a stop sign, a traffic light, or a flashing red or yellow light?","o":["15 feet","30 feet","50 feet","100 feet"],"h1":"It is more than the crosswalk distance.","h2":"In Vermont, you may not park within 30 feet of a stop sign, a traffic light, or a flashing red or yellow light.","p":"Right. Stay 30 feet away."},"es":{"q":"En Vermont, no se puede estacionar a menos de, ¿cuántos pies de una señal de alto, un semáforo o una luz roja o amarilla intermitente?","o":["15 pies","30 pies","50 pies","100 pies"],"h1":"Es más que la distancia del cruce peatonal.","h2":"En Vermont no se puede estacionar a menos de 30 pies de una señal de alto, un semáforo o una luz roja o amarilla intermitente.","p":"Correcto. Quédese a 30 pies."},"ref":{"doc":"VT","page":29}},{"id":"vt-130","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, where signs are posted, how far from a fire station driveway must you stay when parking on the opposite side of the street?","o":["20 feet","30 feet","50 feet","75 feet"],"h1":"It is farther than on the same side, which is 20 feet.","h2":"Where signs are posted, Vermont drivers may not park within 20 feet of a fire station driveway on the same side, or within 75 feet of it on the other side of the street.","p":"Right. Stay 75 feet away across the street."},"es":{"q":"En Vermont, donde hay señales, ¿a qué distancia de la entrada de una estación de bomberos debe quedarse al estacionarse en el lado opuesto de la calle?","o":["20 pies","30 pies","50 pies","75 pies"],"h1":"Es más lejos que del mismo lado, que son 20 pies.","h2":"Donde hay señales, en Vermont no se puede estacionar a menos de 20 pies de la entrada de una estación de bomberos del mismo lado, ni a menos de 75 pies del otro lado de la calle.","p":"Correcto. Quédese a 75 pies del otro lado de la calle."},"ref":{"doc":"VT","page":29}},{"id":"vt-131","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, which of these is a place where you may NOT park?","o":["On a bridge","40 feet from a stop sign","10 feet from a fire hydrant","100 feet from a railroad crossing"],"h1":"Look for a spot listed as never allowed.","h2":"Vermont forbids parking on a bridge or in a tunnel; the other spots in this list are far enough from the hydrant, stop sign and tracks.","p":"Right. You may not park on a bridge."},"es":{"q":"En Vermont, ¿cuál de estos es un lugar donde NO se puede estacionar?","o":["Sobre un puente","A 40 pies de una señal de alto","A 10 pies de un hidrante","A 100 pies de un cruce de ferrocarril"],"h1":"Busque un lugar que nunca se permite.","h2":"Vermont prohíbe estacionarse sobre un puente o dentro de un túnel; los otros lugares de la lista están bastante lejos del hidrante, de la señal de alto y de las vías.","p":"Correcto. No se puede estacionar sobre un puente."},"ref":{"doc":"VT","page":29}},{"id":"vt-132","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you are inside a roundabout with two circulating lanes. May you change lanes while in it?","o":["Yes, any time","No, drivers may not change lanes once inside the roundabout","Only to the left","Only if you signal"],"h1":"Choose your lane before you enter.","h2":"Drivers in a Vermont multi-lane roundabout may not change lanes once inside, so pick the correct lane from the signs and markings before entering.","p":"Right. No lane changes inside the roundabout."},"es":{"q":"En Vermont, usted está dentro de una glorieta con dos carriles. ¿Puede cambiar de carril dentro de ella?","o":["Sí, en cualquier momento","No, no se puede cambiar de carril una vez dentro de la glorieta","Solo a la izquierda","Solo si pone la direccional"],"h1":"Elija su carril antes de entrar.","h2":"En una glorieta de varios carriles en Vermont no se puede cambiar de carril una vez adentro, así que elija el carril correcto según las señales y marcas antes de entrar.","p":"Correcto. No se cambia de carril dentro de la glorieta."},"ref":{"doc":"VT","page":30}},{"id":"vt-133","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, a police car signals you to stop while you are on a divided highway. Where should you stop?","o":["In the center median","In the middle of an intersection","As close to the right side of the road as you safely can","In the left lane"],"h1":"Get out of the way of traffic, but not into the median.","h2":"When stopped by police, drive as close as you safely can to the right side of the road, and do not stop in an intersection or pull into the center median.","p":"Right. Pull to the right side of the road."},"es":{"q":"En Vermont, una patrulla le indica que se detenga mientras va por una carretera dividida. ¿Dónde debe parar?","o":["En el camellón central","En medio de una intersección","Lo más cerca del lado derecho de la carretera que pueda con seguridad","En el carril izquierdo"],"h1":"Salga del paso del tráfico, pero no hacia el camellón.","h2":"Cuando la policía lo detiene, maneje lo más cerca del lado derecho de la carretera que pueda con seguridad, y no se detenga en una intersección ni en el camellón central.","p":"Correcto. Oríllese al lado derecho de la carretera."},"ref":{"doc":"VT","page":30}},{"id":"vt-134","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, you have been pulled over by police. When should you take off your seat belt?","o":["Right away, to get your papers","As soon as you stop the car","When you see the lights behind you","Not until the officer has seen you wearing it"],"h1":"Let the officer see that you were buckled.","h2":"During a police stop in Vermont, keep your seat belt fastened until the officer has seen you wearing it.","p":"Right. Keep it on until the officer has seen it."},"es":{"q":"En Vermont, la policía lo ha detenido. ¿Cuándo debe quitarse el cinturón de seguridad?","o":["De inmediato, para buscar sus papeles","En cuanto pare el carro","Cuando vea las luces detrás de usted","No hasta que el policía haya visto que lo lleva puesto"],"h1":"Deje que el policía vea que iba abrochado.","h2":"Durante una parada de la policía en Vermont, mantenga el cinturón abrochado hasta que el policía haya visto que lo lleva puesto.","p":"Correcto. Déjelo puesto hasta que el policía lo vea."},"ref":{"doc":"VT","page":30}},{"id":"vt-135","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, you are pulled over by police at night on a dark road. What should you do before the officer reaches your car?","o":["Turn on the inside light of your car","Get out and walk to the police car","Turn off all your lights","Start looking under the seats"],"h1":"Help the officer see you clearly.","h2":"If you are stopped in a dimly lit area, turn on your car's interior light after stopping and before the officer approaches, and stay in the car.","p":"Right. Turn on the interior light."},"es":{"q":"En Vermont, la policía lo detiene de noche en un camino oscuro. ¿Qué debe hacer antes de que el policía llegue a su carro?","o":["Prender la luz de adentro del carro","Bajarse y caminar a la patrulla","Apagar todas las luces","Empezar a buscar debajo de los asientos"],"h1":"Ayude a que el policía lo vea bien.","h2":"Si lo detienen en un lugar con poca luz, prenda la luz interior de su carro después de parar y antes de que el policía se acerque, y quédese en el carro.","p":"Correcto. Prenda la luz interior."},"ref":{"doc":"VT","page":30}},{"id":"vt-136","scope":"VT","cat":"signs","sign":null,"c":2,"en":{"q":"In Vermont, what does an orange and red triangle sign on the back of a tractor or farm machine mean?","o":["The vehicle carries hazardous materials","The driver is a student","It is a slow-moving vehicle that cannot travel at highway speed","The vehicle is about to turn left"],"h1":"Think of farm equipment on a country road.","h2":"An orange and red triangular sign on the rear of a vehicle marks a slow-moving vehicle, such as a tractor, that cannot reach highway speed, so slow down early.","p":"Right. It marks a slow-moving vehicle."},"es":{"q":"En Vermont, ¿qué significa una señal triangular anaranjada y roja en la parte de atrás de un tractor o máquina agrícola?","o":["El vehículo lleva materiales peligrosos","El conductor es estudiante","Es un vehículo lento que no puede ir a velocidad de carretera","El vehículo va a dar vuelta a la izquierda"],"h1":"Piense en maquinaria agrícola en un camino rural.","h2":"Una señal triangular anaranjada y roja en la parte de atrás de un vehículo indica un vehículo lento, como un tractor, que no alcanza la velocidad de carretera, así que baje la velocidad con tiempo.","p":"Correcto. Indica un vehículo lento."},"ref":{"doc":"VT","page":44}},{"id":"vt-137","scope":"VT","cat":"signs","sign":null,"c":3,"en":{"q":"In Vermont, a school or pedestrian warning sign has a small sign below it with a downward-pointing arrow. What does the arrow show?","o":["The speed limit ahead","A detour ahead","A school bus stop in one mile","The exact location of the crosswalk or crossing"],"h1":"The arrow points at a spot on the road.","h2":"A downward arrow under a school or pedestrian sign shows where the crosswalk or crossing area is.","p":"Right. It marks the crossing location."},"es":{"q":"En Vermont, una señal de advertencia de escuela o de peatones tiene debajo una señal pequeña con una flecha hacia abajo. ¿Qué indica la flecha?","o":["El límite de velocidad más adelante","Un desvío más adelante","Una parada de autobús escolar a una milla","El lugar exacto del cruce peatonal o de la zona de cruce"],"h1":"La flecha apunta a un lugar del camino.","h2":"Una flecha hacia abajo debajo de una señal de escuela o de peatones indica dónde está el cruce peatonal o la zona de cruce.","p":"Correcto. Marca el lugar del cruce."},"ref":{"doc":"VT","page":33}},{"id":"vt-138","scope":"VT","cat":"signs","sign":null,"c":0,"en":{"q":"In Vermont, a road sign is covered with snow and you cannot read the words. How can you still know its general meaning?","o":["By its shape","By its height above the road","By the sound of passing cars","You cannot know at all"],"h1":"Stop signs and yield signs each have their own outline.","h2":"If a sign is covered by snow or dirt, you should know whether it is a regulatory, warning or information sign by its shape.","p":"Right. The shape tells you the general meaning."},"es":{"q":"En Vermont, una señal de tránsito está cubierta de nieve y no puede leer las palabras. ¿Cómo puede saber de todos modos su significado general?","o":["Por su forma","Por su altura sobre el camino","Por el ruido de los carros que pasan","No se puede saber"],"h1":"Las señales de alto y de ceder el paso tienen cada una su propio contorno.","h2":"Si una señal está cubierta de nieve o de tierra, usted debe saber por su forma si es reglamentaria, de advertencia o de información.","p":"Correcto. La forma indica el significado general."},"ref":{"doc":"VT","page":32}},{"id":"vt-139","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, you move into a center two-way left-turn lane to turn left. How much of your car should be in that lane?","o":["Only the front wheels","All of your vehicle","Half of the car","None; turn from your own lane"],"h1":"Do not leave part of your car blocking the lane you came from.","h2":"When using a two-way left-turn lane in Vermont, move in a short distance before the turn with all of your vehicle in the turn lane, so you do not block traffic; it is not a travel lane.","p":"Right. All of your car should be in the turn lane."},"es":{"q":"En Vermont, usted entra al carril central de vuelta a la izquierda en ambos sentidos para dar vuelta. ¿Qué parte de su carro debe estar en ese carril?","o":["Solo las llantas delanteras","Todo su vehículo","La mitad del carro","Nada; dé vuelta desde su carril"],"h1":"No deje parte del carro bloqueando el carril de donde viene.","h2":"Al usar un carril central de vuelta a la izquierda en Vermont, entre poco antes de la vuelta con todo su vehículo dentro del carril, para no bloquear el tráfico; no es un carril para circular.","p":"Correcto. Todo el carro debe estar en el carril de vuelta."},"ref":{"doc":"VT","page":34}},{"id":"vt-140","scope":"VT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Vermont, when do the safety rules for work zones apply?","o":["Only on weekdays","Only in daylight","At all times, 24 hours a day, 7 days a week","Only when you see workers"],"h1":"Hazards stay there after the crew goes home.","h2":"Vermont work zone rules apply 24 hours a day, 7 days a week, not just in daylight.","p":"Right. Work zone rules apply 24/7."},"es":{"q":"En Vermont, ¿cuándo se aplican las reglas de seguridad de las zonas de construcción?","o":["Solo entre semana","Solo de día","Siempre, las 24 horas, los 7 días de la semana","Solo cuando ve trabajadores"],"h1":"Los peligros siguen allí después de que los trabajadores se van.","h2":"Las reglas de las zonas de construcción en Vermont se aplican las 24 horas del día, los 7 días de la semana, no solo de día.","p":"Correcto. Las reglas se aplican 24/7."},"ref":{"doc":"VT","page":35}},{"id":"vt-141","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, what happens to fines for speeding in a work zone?","o":["They stay the same","They are doubled","They are cut in half","They become a warning only"],"h1":"Work zones carry a heavier penalty.","h2":"In Vermont, fines are doubled for speeding in a work zone.","p":"Right. Speeding fines are doubled in work zones."},"es":{"q":"En Vermont, ¿qué pasa con las multas por exceso de velocidad en una zona de construcción?","o":["Siguen iguales","Se duplican","Se reducen a la mitad","Son solo una advertencia"],"h1":"Las zonas de construcción tienen una sanción más fuerte.","h2":"En Vermont, las multas por exceso de velocidad se duplican en una zona de construcción.","p":"Correcto. Las multas por velocidad se duplican en zonas de construcción."},"ref":{"doc":"VT","page":35}},{"id":"vt-142","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, the driver manual says a passenger car at 60 mph on dry pavement needs about how many feet to stop completely?","o":["75 feet","120 feet","180 feet","240 feet"],"h1":"At 30 mph it takes about 75 feet; doubling the speed makes it much more than double.","h2":"The Vermont manual says a passenger car at 60 mph on dry pavement needs about 240 feet to stop, compared with about 75 feet at 30 mph.","p":"Right. About 240 feet at 60 mph."},"es":{"q":"En Vermont, el manual dice que un carro de pasajeros a 60 mph en pavimento seco necesita, ¿más o menos cuántos pies para detenerse por completo?","o":["75 pies","120 pies","180 pies","240 pies"],"h1":"A 30 mph necesita unos 75 pies; al doblar la velocidad necesita mucho más del doble.","h2":"El manual de Vermont dice que un carro de pasajeros a 60 mph en pavimento seco necesita unos 240 pies para detenerse, comparado con unos 75 pies a 30 mph.","p":"Correcto. Unos 240 pies a 60 mph."},"ref":{"doc":"VT","page":35}},{"id":"vt-143","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, how many points does a first conviction for using a hand-held phone in a work zone with workers present, or a marked school zone, add to your record?","o":["2 points","4 points","6 points","10 points"],"h1":"It is double the points for the same offense elsewhere.","h2":"Under Vermont law, hand-held phone use in a work zone with workers present or a marked school zone brings 4 points and a $200 to $400 fine for a first conviction, and 5 points after that.","p":"Right. A first offense there adds 4 points."},"es":{"q":"En Vermont, ¿cuántos puntos agrega a su historial una primera condena por usar un teléfono en la mano en una zona de construcción con trabajadores presentes, o en una zona escolar señalizada?","o":["2 puntos","4 puntos","6 puntos","10 puntos"],"h1":"Es el doble de los puntos por la misma falta en otro lugar.","h2":"Según la ley de Vermont, usar un teléfono en la mano en una zona de construcción con trabajadores o en una zona escolar señalizada trae 4 puntos y una multa de $200 a $400 en la primera condena, y 5 puntos después.","p":"Correcto. Una primera falta allí agrega 4 puntos."},"ref":{"doc":"VT","page":null}},{"id":"vt-144","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what is the fine range for a second hand-held phone violation within two years, outside work and school zones?","o":["$50 to $100","$100 to $200","$250 to $500","$1,000 to $2,000"],"h1":"It is more than double the first-offense range.","h2":"In Vermont, a second or later hand-held phone violation within two years brings a fine of $250 to $500, compared with $100 to $200 the first time.","p":"Right. A second violation costs $250 to $500."},"es":{"q":"En Vermont, ¿cuál es el rango de la multa por una segunda infracción de usar el teléfono en la mano en dos años, fuera de zonas de construcción y escolares?","o":["$50 a $100","$100 a $200","$250 a $500","$1,000 a $2,000"],"h1":"Es más del doble del rango de la primera vez.","h2":"En Vermont, una segunda infracción o más de usar el teléfono en la mano en dos años trae una multa de $250 a $500, comparada con $100 a $200 la primera vez.","p":"Correcto. Una segunda infracción cuesta de $250 a $500."},"ref":{"doc":"VT","page":55}},{"id":"vt-145","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, you drive through a work zone with temporary lane markers. On which side should the yellow markers be?","o":["On your left; if not, you are in the wrong lane","On your right","On both sides","Yellow markers are not used in work zones"],"h1":"Yellow separates traffic going opposite ways.","h2":"In a Vermont work zone, yellow markers separate lanes going in opposite directions and should be on your left; if they are not, you are in the wrong lane.","p":"Right. Yellow should be on your left."},"es":{"q":"En Vermont, usted pasa por una zona de construcción con marcas temporales en los carriles. ¿De qué lado deben estar las marcas amarillas?","o":["A su izquierda; si no, va en el carril equivocado","A su derecha","A los dos lados","No se usan marcas amarillas en zonas de construcción"],"h1":"El amarillo separa el tráfico que va en sentidos opuestos.","h2":"En una zona de construcción de Vermont, las marcas amarillas separan carriles de sentidos opuestos y deben estar a su izquierda; si no lo están, va en el carril equivocado.","p":"Correcto. El amarillo debe estar a su izquierda."},"ref":{"doc":"VT","page":36}},{"id":"vt-146","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, you may not pass another vehicle when you are within how many feet of an intersection or railroad crossing, unless signs allow it?","o":["50 feet","100 feet","200 feet","500 feet"],"h1":"It is about the length of a football field's third.","h2":"Vermont law forbids passing another vehicle within 100 feet of, or in, an intersection or railroad grade crossing unless traffic control devices allow it.","p":"Right. No passing within 100 feet."},"es":{"q":"En Vermont, no puede rebasar a otro vehículo cuando está a menos de, ¿cuántos pies de una intersección o de un cruce de ferrocarril, salvo que las señales lo permitan?","o":["50 pies","100 pies","200 pies","500 pies"],"h1":"Es más o menos un tercio de una cancha de fútbol americano.","h2":"La ley de Vermont prohíbe rebasar a otro vehículo a menos de 100 pies de una intersección o cruce de ferrocarril, o dentro de ellos, salvo que las señales lo permitan.","p":"Correcto. No se rebasa a menos de 100 pies."},"ref":{"doc":"VT","page":null}},{"id":"vt-147","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, you notice a dangerous problem at a railroad crossing, such as a stalled truck on the tracks. What should you do?","o":["Try to push the truck yourself","Wait for a train to come","Call the number on the crossing's emergency sign and give the crossing number","Drive around the gates"],"h1":"The railroad can stop trains if it knows exactly where.","h2":"If a dangerous condition exists at a rail crossing, call the number on the emergency sign and give the posted crossing number so the railroad can stop or reroute trains.","p":"Right. Call the sign's number and give the crossing number."},"es":{"q":"En Vermont, usted ve un problema peligroso en un cruce de ferrocarril, como un camión detenido en las vías. ¿Qué debe hacer?","o":["Tratar de empujar el camión usted mismo","Esperar a que venga un tren","Llamar al número del letrero de emergencia del cruce y dar el número del cruce","Rodear las barreras"],"h1":"El ferrocarril puede parar los trenes si sabe exactamente dónde.","h2":"Si hay una condición peligrosa en un cruce de tren, llame al número del letrero de emergencia y dé el número del cruce para que el ferrocarril pueda detener o desviar los trenes.","p":"Correcto. Llame al número del letrero y dé el número del cruce."},"ref":{"doc":"VT","page":37}},{"id":"vt-148","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, a person with a white cane or a guide dog is waiting to cross the street ahead of you. What must you do?","o":["Stop and yield the right of way","Honk to let them know you are there","Drive around them slowly","Wave them across and keep going"],"h1":"The law gives them special protection.","h2":"In Vermont, when a pedestrian with a white cane or guide dog is crossing or waiting to cross ahead of you, you must stop and yield; failing to yield to a blind person is a 4-point violation.","p":"Right. Stop and yield to them."},"es":{"q":"En Vermont, una persona con bastón blanco o perro guía está esperando para cruzar la calle delante de usted. ¿Qué debe hacer?","o":["Detenerse y cederle el paso","Tocar el claxon para avisar que está allí","Rodearla despacio","Hacerle señas para que cruce y seguir"],"h1":"La ley le da protección especial.","h2":"En Vermont, cuando un peatón con bastón blanco o perro guía está cruzando o esperando para cruzar delante de usted, debe detenerse y cederle el paso; no ceder el paso a una persona ciega es una infracción de 4 puntos.","p":"Correcto. Deténgase y cédale el paso."},"ref":{"doc":"VT","page":38}},{"id":"vt-149","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, where does the driver manual say you should never stop to pick up hitchhikers?","o":["In a parking lot","At a gas station","In a town center","On the Interstate or its ramps"],"h1":"It is a high-speed road where stopping is dangerous.","h2":"The Vermont manual says not to stop to pick up hitchhikers on the Interstate or its ramps.","p":"Right. Never on the Interstate or its ramps."},"es":{"q":"En Vermont, ¿dónde dice el manual que nunca debe parar a recoger a personas que piden aventón?","o":["En un estacionamiento","En una gasolinera","En el centro de un pueblo","En la interestatal o en sus rampas"],"h1":"Es una carretera de alta velocidad donde parar es peligroso.","h2":"El manual de Vermont dice que no se debe parar a recoger a personas que piden aventón en la interestatal ni en sus rampas.","p":"Correcto. Nunca en la interestatal ni en sus rampas."},"ref":{"doc":"VT","page":38}},{"id":"vt-150","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, on a road with no sidewalk, which side should a person walk on?","o":["The right side, with traffic","The left side, facing traffic","In the middle of the lane","Either side, it does not matter"],"h1":"Walkers should see the cars coming at them.","h2":"Where there is no sidewalk, a pedestrian in Vermont should walk as far left as possible, facing oncoming traffic.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Vermont, en un camino sin banqueta, ¿de qué lado debe caminar una persona?","o":["Del lado derecho, con el tráfico","Del lado izquierdo, de frente al tráfico","En medio del carril","De cualquier lado, no importa"],"h1":"Quien camina debe ver los carros que vienen hacia él.","h2":"Donde no hay banqueta, un peatón en Vermont debe caminar lo más a la izquierda posible, de frente al tráfico que viene.","p":"Correcto. Camine por la izquierda, de frente al tráfico."},"ref":{"doc":"VT","page":39}},{"id":"vt-151","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, how many points are added for failing to yield to a pedestrian in a crosswalk?","o":["2 points","3 points","4 points","10 points"],"h1":"It is the same as for disobeying a police officer.","h2":"In Vermont, failing to yield the right of way to a pedestrian in a crosswalk adds 4 points to your driving record.","p":"Right. It adds 4 points."},"es":{"q":"En Vermont, ¿cuántos puntos se agregan por no ceder el paso a un peatón en un cruce peatonal?","o":["2 puntos","3 puntos","4 puntos","10 puntos"],"h1":"Es lo mismo que por desobedecer a un policía.","h2":"En Vermont, no ceder el paso a un peatón en un cruce peatonal agrega 4 puntos a su historial de manejo.","p":"Correcto. Agrega 4 puntos."},"ref":{"doc":"VT","page":64}},{"id":"vt-152","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, a school bus ahead turns on its alternately flashing yellow lights. What does that mean?","o":["You may pass quickly","The bus is broken down","The bus is leaving the stop","The bus is about to stop for students, so prepare to stop"],"h1":"Yellow comes before red.","h2":"Alternately flashing yellow lights on a Vermont school bus mean it is slowing to pick up or drop off students, so you should prepare to stop before the red lights come on.","p":"Right. Get ready to stop."},"es":{"q":"En Vermont, un autobús escolar adelante enciende sus luces amarillas que parpadean alternadamente. ¿Qué significa?","o":["Puede rebasarlo rápido","El autobús está descompuesto","El autobús está saliendo de la parada","El autobús va a parar por estudiantes, así que prepárese para detenerse"],"h1":"El amarillo viene antes que el rojo.","h2":"Las luces amarillas que parpadean alternadamente en un autobús escolar de Vermont significan que va bajando la velocidad para recoger o dejar estudiantes, así que prepárese para detenerse antes de que se enciendan las rojas.","p":"Correcto. Prepárese para detenerse."},"ref":{"doc":"VT","page":39}},{"id":"vt-153","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, a school bus is stopped with its red lights flashing inside a school yard, not on the road. May you pass it?","o":["No, you must not pass it even in a school yard","Yes, the law only applies on highways","Yes, if you go slowly","Yes, if no children are visible"],"h1":"The red lights mean the same thing everywhere.","h2":"In Vermont, even in a school yard you must not pass a stopped school bus with its alternately flashing red lights on.","p":"Right. Do not pass it, even in a school yard."},"es":{"q":"En Vermont, un autobús escolar está detenido con sus luces rojas encendidas dentro del patio de una escuela, no en la calle. ¿Puede rebasarlo?","o":["No, no debe rebasarlo ni siquiera en el patio de la escuela","Sí, la ley solo se aplica en carreteras","Sí, si va despacio","Sí, si no se ven niños"],"h1":"Las luces rojas significan lo mismo en todas partes.","h2":"En Vermont, incluso en el patio de una escuela, no debe rebasar un autobús escolar detenido con sus luces rojas intermitentes encendidas.","p":"Correcto. No lo rebase, ni siquiera en el patio de la escuela."},"ref":{"doc":"VT","page":40}},{"id":"vt-154","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, on which roads are bicyclists NOT allowed to ride?","o":["Any road with a speed limit over 30 mph","Limited-access highways such as the Interstate","Any road without a bike lane","Dirt roads"],"h1":"Bicyclists may use almost every road.","h2":"Under Vermont law bicyclists may ride on all roads except where specially prohibited, such as limited-access highways like the Interstate.","p":"Right. Bicycles are kept off the Interstate."},"es":{"q":"En Vermont, ¿en qué caminos NO pueden andar los ciclistas?","o":["En cualquier camino con límite de más de 30 mph","En autopistas de acceso limitado como la interestatal","En cualquier camino sin ciclovía","En caminos de tierra"],"h1":"Los ciclistas pueden usar casi todos los caminos.","h2":"Según la ley de Vermont, los ciclistas pueden andar en todos los caminos menos donde está prohibido especialmente, como en autopistas de acceso limitado como la interestatal.","p":"Correcto. Las bicicletas no van en la interestatal."},"ref":{"doc":"VT","page":40}},{"id":"vt-155","scope":"VT","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Vermont, two bicyclists are riding side by side in your lane. Is that legal?","o":["No, they must always ride single file","Only on weekends","Yes, two bicyclists may legally ride side by side if they do not hold up normal traffic","Only in towns"],"h1":"Slow down and wait for a safe chance to pass.","h2":"Vermont allows bicyclists to ride two abreast as long as they do not impede the normal and reasonable flow of traffic; slow down and pass only when it is safe.","p":"Right. Riding two side by side is legal."},"es":{"q":"En Vermont, dos ciclistas van uno al lado del otro en su carril. ¿Es legal?","o":["No, siempre deben ir en fila","Solo los fines de semana","Sí, dos ciclistas pueden ir lado a lado legalmente si no detienen el tráfico normal","Solo en los pueblos"],"h1":"Baje la velocidad y espere una oportunidad segura para rebasar.","h2":"Vermont permite que los ciclistas vayan de dos en fondo siempre que no estorben el flujo normal y razonable del tráfico; baje la velocidad y rebase solo cuando sea seguro.","p":"Correcto. Ir dos lado a lado es legal."},"ref":{"doc":"VT","page":41}},{"id":"vt-156","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, when should you honk at a bicyclist?","o":["Only when you have good cause to warn them","Every time you pass them","Whenever they ride in the lane","To ask them to move over"],"h1":"A loud horn can startle a rider.","h2":"Do not honk at a bicyclist unless you have good cause to warn them, because the noise can startle the rider and cause a crash.","p":"Right. Only when you truly need to warn them."},"es":{"q":"En Vermont, ¿cuándo debe tocar el claxon a un ciclista?","o":["Solo cuando tiene una buena razón para advertirle","Cada vez que lo rebasa","Siempre que va en el carril","Para pedirle que se haga a un lado"],"h1":"Un claxon fuerte puede asustar al ciclista.","h2":"No le toque el claxon a un ciclista a menos que tenga una buena razón para advertirle, porque el ruido lo puede asustar y causar un choque.","p":"Correcto. Solo cuando de verdad necesita advertirle."},"ref":{"doc":"VT","page":40}},{"id":"vt-157","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, what is the smallest civil penalty for passing a bicyclist or pedestrian without the care and space the law requires?","o":["$25","$50","$100","$200"],"h1":"It is more than the fine for a first seat belt violation.","h2":"Vermont law requires slowing down and giving at least four feet when passing a vulnerable user, such as a bicyclist or pedestrian; a violation brings a civil penalty of at least $200.","p":"Right. The penalty is at least $200."},"es":{"q":"En Vermont, ¿cuál es la multa civil mínima por rebasar a un ciclista o peatón sin el cuidado y el espacio que exige la ley?","o":["$25","$50","$100","$200"],"h1":"Es más que la multa por la primera falta del cinturón.","h2":"La ley de Vermont exige bajar la velocidad y dejar por lo menos cuatro pies al rebasar a un usuario vulnerable, como un ciclista o un peatón; la infracción trae una multa civil de por lo menos $200.","p":"Correcto. La multa es de por lo menos $200."},"ref":{"doc":"VT","page":null}},{"id":"vt-158","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you come up behind a garbage truck or utility truck stopped with flashing lights. What does the law say to do?","o":["Pass at the same speed","Slow down and give it extra space, at least four feet if you can","Stop until it moves","Honk and pass on the right"],"h1":"Workers may step out around it.","h2":"Vermont law says to slow down and give a stopped sanitation, maintenance, utility or delivery vehicle with flashing lights extra clearance, with at least four feet recommended.","p":"Right. Slow down and give at least four feet."},"es":{"q":"En Vermont, usted se acerca por detrás a un camión de basura o de servicios detenido con luces intermitentes. ¿Qué dice la ley que haga?","o":["Rebasarlo a la misma velocidad","Bajar la velocidad y darle más espacio, por lo menos cuatro pies si puede","Detenerse hasta que se mueva","Tocar el claxon y rebasar por la derecha"],"h1":"Puede haber trabajadores bajándose a su alrededor.","h2":"La ley de Vermont dice que hay que bajar la velocidad y dar más espacio a un vehículo de basura, mantenimiento, servicios o reparto detenido con luces intermitentes, con por lo menos cuatro pies recomendados.","p":"Correcto. Baje la velocidad y deje por lo menos cuatro pies."},"ref":{"doc":"VT","page":null}},{"id":"vt-159","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, how much following distance should you leave behind a motorcycle?","o":["1 second","2 seconds","3 seconds","More than 4 seconds"],"h1":"Riders often slow down without a brake light.","h2":"Allow more than 4 seconds of following distance behind a motorcycle in Vermont, because riders often slow by downshifting without showing a brake light.","p":"Right. Leave more than 4 seconds."},"es":{"q":"En Vermont, ¿cuánta distancia debe dejar detrás de una motocicleta?","o":["1 segundo","2 segundos","3 segundos","Más de 4 segundos"],"h1":"Los motociclistas muchas veces bajan la velocidad sin luz de freno.","h2":"Deje más de 4 segundos de distancia detrás de una motocicleta en Vermont, porque los motociclistas muchas veces bajan la velocidad cambiando de marcha sin mostrar luz de freno.","p":"Correcto. Deje más de 4 segundos."},"ref":{"doc":"VT","page":42}},{"id":"vt-160","scope":"VT","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Vermont, how should you pass a motorcycle?","o":["Change lanes completely, because a motorcycle is entitled to a full lane","Share the lane with it","Squeeze past on the same lane if it rides to one side","Pass on the shoulder"],"h1":"Treat it like any other vehicle.","h2":"Motorcycles in Vermont are entitled to a full lane, so when you pass one, change lanes completely and do not cut back in too close.","p":"Right. Use a full lane change."},"es":{"q":"En Vermont, ¿cómo debe rebasar a una motocicleta?","o":["Cambiando de carril por completo, porque la motocicleta tiene derecho a un carril entero","Compartiendo el carril con ella","Pasando por el mismo carril si va a un lado","Pasando por el acotamiento"],"h1":"Trátela como a cualquier otro vehículo.","h2":"En Vermont las motocicletas tienen derecho a un carril entero, así que al rebasar a una, cambie de carril por completo y no se meta demasiado cerca.","p":"Correcto. Cambie de carril por completo."},"ref":{"doc":"VT","page":43}},{"id":"vt-161","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, who must wear a helmet on a motorcycle?","o":["Only riders under 18","Every operator and passenger","Only the operator","Only on the Interstate"],"h1":"Vermont has a universal helmet law.","h2":"Vermont law requires every person operating or riding on a motorcycle on a highway to wear a helmet that meets federal safety standards.","p":"Right. Every rider and passenger must wear a helmet."},"es":{"q":"En Vermont, ¿quién debe usar casco en una motocicleta?","o":["Solo los menores de 18","Todo conductor y pasajero","Solo el conductor","Solo en la interestatal"],"h1":"Vermont tiene una ley de casco para todos.","h2":"La ley de Vermont exige que toda persona que maneja o va en una motocicleta en la carretera use un casco que cumpla las normas federales de seguridad.","p":"Correcto. Todo conductor y pasajero debe usar casco."},"ref":{"doc":"VT","page":null}},{"id":"vt-162","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, a motorcycle has no windshield. What must the operator wear?","o":["Nothing extra","Gloves","Eyeglasses, goggles or a face shield","A reflective vest"],"h1":"It protects the eyes.","h2":"Vermont law requires the operator of a motorcycle without a windshield to wear eyeglasses, goggles or a protective face shield, with clear lenses at night.","p":"Right. Eye protection is required."},"es":{"q":"En Vermont, una motocicleta no tiene parabrisas. ¿Qué debe usar el conductor?","o":["Nada adicional","Guantes","Lentes, gafas protectoras o una careta","Un chaleco reflectante"],"h1":"Protege los ojos.","h2":"La ley de Vermont exige que el conductor de una motocicleta sin parabrisas use lentes, gafas protectoras o una careta, con lentes transparentes de noche.","p":"Correcto. Se requiere protección para los ojos."},"ref":{"doc":"VT","page":null}},{"id":"vt-163","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, a large truck is backing up and blocking the street. What should you do?","o":["Drive around it quickly","Honk and pass behind it","Pass on the sidewalk","Wait; never go around a truck that is backing up"],"h1":"The trailer can hide you from the driver.","h2":"Never go around a truck that is preparing to back up or is backing, because you can enter its blind spot where the driver cannot see you.","p":"Right. Wait for the truck to finish."},"es":{"q":"En Vermont, un camión grande va en reversa y bloquea la calle. ¿Qué debe hacer?","o":["Rodearlo rápido","Tocar el claxon y pasar por detrás","Pasar por la banqueta","Esperar; nunca rodee un camión que va en reversa"],"h1":"El remolque lo puede ocultar del conductor.","h2":"Nunca rodee un camión que se prepara para ir en reversa o que va en reversa, porque puede meterse en su punto ciego donde el conductor no lo ve.","p":"Correcto. Espere a que el camión termine."},"ref":{"doc":"VT","page":43}},{"id":"vt-164","scope":"VT","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Vermont, you are following a horse and rider or a horse-drawn wagon. How much following distance should you leave?","o":["1 second","At least 4 seconds","2 seconds","Just a car length"],"h1":"Give the animal plenty of room.","h2":"When following a horse with a rider, a horse and wagon, or herded animals in Vermont, leave at least a 4-second following distance.","p":"Right. Leave at least 4 seconds."},"es":{"q":"En Vermont, usted va detrás de un caballo con jinete o de una carreta tirada por caballos. ¿Cuánta distancia debe dejar?","o":["1 segundo","Por lo menos 4 segundos","2 segundos","Solo el largo de un carro"],"h1":"Dele mucho espacio al animal.","h2":"Al ir detrás de un caballo con jinete, una carreta con caballos o animales en arreo en Vermont, deje por lo menos 4 segundos de distancia.","p":"Correcto. Deje por lo menos 4 segundos."},"ref":{"doc":"VT","page":45}},{"id":"vt-165","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, why are moose especially hard to see at night?","o":["They only cross in daylight","They are always in groups","Their eyes often do not reflect headlights, and they are dark and tall","They make loud noises"],"h1":"Deer eyes shine in your lights, but a moose's head is higher.","h2":"Moose are hard to see at night because they are tall, so their eyes may not reflect your headlights, and they are dark colored; they also weigh more than 1,000 pounds.","p":"Right. Their eyes often do not shine in your headlights."},"es":{"q":"En Vermont, ¿por qué es tan difícil ver un alce de noche?","o":["Solo cruzan de día","Siempre andan en grupos","Sus ojos muchas veces no reflejan las luces y son oscuros y altos","Hacen mucho ruido"],"h1":"Los ojos del venado brillan con sus luces, pero la cabeza del alce está más alta.","h2":"Los alces son difíciles de ver de noche porque son altos, así que sus ojos pueden no reflejar sus luces, y son de color oscuro; además pesan más de 1,000 libras.","p":"Correcto. Sus ojos muchas veces no brillan con las luces."},"ref":{"doc":"VT","page":45}},{"id":"vt-166","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, at what times are moose and deer most likely to be on the road?","o":["Late evening, night and early morning","Midday","Only in summer afternoons","Only during rush hour"],"h1":"Think of the darker hours.","h2":"Moose and deer are most likely to be on Vermont highways in the late evening, at night and in the early morning, so take extra care then.","p":"Right. Late evening, night and early morning."},"es":{"q":"En Vermont, ¿a qué horas es más probable que haya alces y venados en el camino?","o":["Al anochecer, de noche y temprano en la mañana","Al mediodía","Solo en las tardes de verano","Solo en horas pico"],"h1":"Piense en las horas más oscuras.","h2":"Es más probable encontrar alces y venados en las carreteras de Vermont al anochecer, de noche y temprano en la mañana, así que tenga más cuidado a esas horas.","p":"Correcto. Al anochecer, de noche y temprano en la mañana."},"ref":{"doc":"VT","page":45}},{"id":"vt-167","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, your car stalls in a flooded area. What does the driver manual say to do?","o":["Stay inside until the water goes down","Try to restart it again and again","Push the car out of the water","Leave the car as soon as possible"],"h1":"Flood water can rise fast and sweep a car away.","h2":"If your vehicle stalls in a flooded area, abandon it as soon as possible, because flood waters can rise quickly and many deaths come from trying to move stalled cars.","p":"Right. Get out and leave the car."},"es":{"q":"En Vermont, su carro se apaga en una zona inundada. ¿Qué dice el manual que haga?","o":["Quedarse adentro hasta que baje el agua","Tratar de encenderlo una y otra vez","Empujar el carro fuera del agua","Dejar el carro lo antes posible"],"h1":"El agua de una inundación puede subir rápido y arrastrar un carro.","h2":"Si su vehículo se apaga en una zona inundada, abandónelo lo antes posible, porque el agua puede subir rápido y muchas muertes ocurren al tratar de mover carros detenidos.","p":"Correcto. Salga y deje el carro."},"ref":{"doc":"VT","page":46}},{"id":"vt-168","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, how much gas does the driver manual say to keep in your tank in winter?","o":["Any amount is fine","At least one quarter tank","At least half a tank","Always a full tank"],"h1":"You may need to run the engine for heat if you get stuck.","h2":"The Vermont manual says to always keep at least half a tank of gas in your vehicle during winter.","p":"Right. Keep at least half a tank."},"es":{"q":"En Vermont, ¿cuánta gasolina dice el manual que debe tener en el tanque en invierno?","o":["Cualquier cantidad está bien","Por lo menos un cuarto de tanque","Por lo menos medio tanque","Siempre el tanque lleno"],"h1":"Puede necesitar el motor para calentarse si se queda atascado.","h2":"El manual de Vermont dice que siempre debe tener por lo menos medio tanque de gasolina en invierno.","p":"Correcto. Tenga por lo menos medio tanque."},"ref":{"doc":"VT","page":47}},{"id":"vt-169","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, you are stranded in your car during a blizzard. About how long should you run the engine and heater?","o":["About 10 minutes each hour","Without stopping, all the time","Never","About 30 minutes, then 30 minutes off"],"h1":"Save fuel, and open a window a little when it runs.","h2":"When stranded in a blizzard, stay in your car and run the engine and heater about 10 minutes each hour, with a downwind window open slightly.","p":"Right. About 10 minutes each hour."},"es":{"q":"En Vermont, usted se queda varado en su carro durante una tormenta de nieve. ¿Más o menos cuánto tiempo debe tener prendido el motor y la calefacción?","o":["Más o menos 10 minutos cada hora","Sin parar, todo el tiempo","Nunca","Más o menos 30 minutos prendido y 30 apagado"],"h1":"Ahorre gasolina y abra un poco una ventana cuando esté prendido.","h2":"Si queda varado en una tormenta de nieve, quédese en su carro y prenda el motor y la calefacción más o menos 10 minutos cada hora, con una ventana un poco abierta del lado contrario al viento.","p":"Correcto. Más o menos 10 minutos cada hora."},"ref":{"doc":"VT","page":47}},{"id":"vt-170","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, the ABS warning light stays on after you start driving. What does it mean?","o":["Your car has no brakes at all","The anti-lock system is not working, but you still have regular brakes","The parking brake is on","You are low on gas"],"h1":"Only one part of the brake system is affected.","h2":"If the ABS light stays on after you begin driving, the anti-lock brake system is not working, but the vehicle still has its regular brakes.","p":"Right. ABS is off, but the regular brakes still work."},"es":{"q":"En Vermont, la luz de advertencia del ABS se queda prendida después de empezar a manejar. ¿Qué significa?","o":["Su carro no tiene frenos","El sistema antibloqueo no funciona, pero todavía tiene frenos normales","El freno de mano está puesto","Le queda poca gasolina"],"h1":"Solo una parte del sistema de frenos está afectada.","h2":"Si la luz del ABS se queda prendida después de empezar a manejar, el sistema de frenos antibloqueo no funciona, pero el vehículo todavía tiene sus frenos normales.","p":"Correcto. El ABS no funciona, pero los frenos normales sí."},"ref":{"doc":"VT","page":49}},{"id":"vt-171","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, the driver manual says that at night with low beams you are already overdriving your headlights at what speed?","o":["15 mph","25 mph","40 mph","Only above 70 mph"],"h1":"It is lower than most highway speed limits.","h2":"The Vermont manual says that driving at 40 mph at night with low beams means you are overdriving your headlights and cannot stop within the distance you can see.","p":"Right. At 40 mph on low beams."},"es":{"q":"En Vermont, el manual dice que de noche con luces bajas usted ya va más rápido de lo que alumbran sus luces, ¿a qué velocidad?","o":["15 mph","25 mph","40 mph","Solo a más de 70 mph"],"h1":"Es menos que la mayoría de los límites en carretera.","h2":"El manual de Vermont dice que manejar a 40 mph de noche con luces bajas significa que va más rápido de lo que alumbran sus luces y no puede parar dentro de la distancia que ve.","p":"Correcto. A 40 mph con luces bajas."},"ref":{"doc":"VT","page":49}},{"id":"vt-172","scope":"VT","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Vermont, your car breaks down on the Interstate and you need help. What does the manual say to do?","o":["Move to the breakdown lane, raise the hood, tie a white cloth on the car and stay inside","Stop in the travel lane and walk for help","Park in the median and hitchhike","Back up to the last exit"],"h1":"Make your car easy to spot and stay safe in it.","h2":"For an emergency stop on a Vermont Interstate, move into the breakdown lane as far right as possible; if you need help, raise the hood, tie a white cloth on the vehicle and stay inside.","p":"Right. Breakdown lane, hood up, white cloth, stay inside."},"es":{"q":"En Vermont, su carro se descompone en la interestatal y necesita ayuda. ¿Qué dice el manual que haga?","o":["Moverse al carril de emergencia, levantar el cofre, amarrar un trapo blanco al carro y quedarse adentro","Parar en el carril y caminar a buscar ayuda","Estacionarse en el camellón y pedir aventón","Ir en reversa hasta la última salida"],"h1":"Haga que su carro se vea fácil y quédese seguro adentro.","h2":"Para una parada de emergencia en una interestatal de Vermont, muévase al carril de emergencia lo más a la derecha posible; si necesita ayuda, levante el cofre, amarre un trapo blanco al vehículo y quédese adentro.","p":"Correcto. Carril de emergencia, cofre arriba, trapo blanco y quedarse adentro."},"ref":{"doc":"VT","page":51}},{"id":"vt-173","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, who may use the emergency turnarounds (median crossovers) on the Interstate?","o":["Anyone who missed an exit","Trucks only","Cars, at night only","Only emergency and maintenance vehicles"],"h1":"If you miss your exit, go on to the next one.","h2":"Interstate median crossovers in Vermont are for emergency and maintenance vehicles only; if you miss your exit, continue to the next exit.","p":"Right. Only emergency and maintenance vehicles."},"es":{"q":"En Vermont, ¿quién puede usar los retornos de emergencia (cruces del camellón) en la interestatal?","o":["Cualquiera que se pasó la salida","Solo camiones","Carros, solo de noche","Solo vehículos de emergencia y de mantenimiento"],"h1":"Si se pasa la salida, siga hasta la siguiente.","h2":"Los cruces del camellón en las interestatales de Vermont son solo para vehículos de emergencia y de mantenimiento; si se pasa la salida, siga hasta la próxima.","p":"Correcto. Solo vehículos de emergencia y de mantenimiento."},"ref":{"doc":"VT","page":51}},{"id":"vt-174","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, another vehicle is passing you on a two-lane road. What should you do?","o":["Speed up so it can pass faster","Slow a little and keep to the right","Move toward the center line","Brake hard"],"h1":"Make the pass easier and shorter for the other driver.","h2":"When you are being passed in Vermont, slow a little and keep right, and do not speed up until the other vehicle has completely passed.","p":"Right. Slow a little and keep right."},"es":{"q":"En Vermont, otro vehículo lo está rebasando en una calle de dos carriles. ¿Qué debe hacer?","o":["Acelerar para que rebase más rápido","Bajar un poco la velocidad y mantenerse a la derecha","Acercarse a la línea central","Frenar fuerte"],"h1":"Haga que el rebase sea más fácil y corto para el otro conductor.","h2":"Cuando lo están rebasando en Vermont, baje un poco la velocidad y manténgase a la derecha, y no acelere hasta que el otro vehículo haya pasado por completo.","p":"Correcto. Baje un poco la velocidad y manténgase a la derecha."},"ref":{"doc":"VT","page":52}},{"id":"vt-175","scope":"VT","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Vermont, you are passing on a two-lane road using the oncoming lane. You must be back in your lane before you come within how many feet of an oncoming vehicle?","o":["50 feet","100 feet","200 feet","1,000 feet"],"h1":"It is twice the no-passing distance near intersections.","h2":"Vermont law says a passing driver using the lane for oncoming traffic must return to an authorized lane before coming within 200 feet of any approaching vehicle or vulnerable user.","p":"Right. Be back before 200 feet."},"es":{"q":"En Vermont, usted rebasa en una calle de dos carriles usando el carril contrario. ¿Debe volver a su carril antes de quedar a cuántos pies de un vehículo que viene de frente?","o":["50 pies","100 pies","200 pies","1,000 pies"],"h1":"Es el doble de la distancia sin rebase cerca de las intersecciones.","h2":"La ley de Vermont dice que quien rebasa usando el carril del tráfico contrario debe volver a un carril permitido antes de quedar a 200 pies de cualquier vehículo o usuario vulnerable que se acerque.","p":"Correcto. Vuelva antes de los 200 pies."},"ref":{"doc":"VT","page":null}},{"id":"vt-176","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, you may not make a U-turn on a curve or near the top of a hill if other drivers cannot see you from how far away?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is the same distance used in the headlight law.","h2":"Vermont law forbids turning around on a curve or near the crest of a hill where other drivers cannot see your vehicle from 500 feet in either direction.","p":"Right. 500 feet."},"es":{"q":"En Vermont, no puede dar una vuelta en U en una curva o cerca de la cima de una loma si los demás conductores no lo pueden ver, ¿desde qué distancia?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es la misma distancia que se usa en la ley de las luces.","h2":"La ley de Vermont prohíbe dar vuelta en U en una curva o cerca de la cima de una loma donde los otros conductores no pueden ver su vehículo desde 500 pies en cualquier dirección.","p":"Correcto. 500 pies."},"ref":{"doc":"VT","page":null}},{"id":"vt-177","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, how long is the license suspension after a first conviction for driving under the influence (DUI)?","o":["90 days","30 days","18 months","Life"],"h1":"It is about three months.","h2":"After a first DUI conviction in Vermont, the license is suspended for 90 days and until the driver completes the required alcohol program steps.","p":"Right. A first DUI conviction means a 90-day suspension."},"es":{"q":"En Vermont, ¿cuánto dura la suspensión de la licencia después de una primera condena por manejar bajo la influencia (DUI)?","o":["90 días","30 días","18 meses","De por vida"],"h1":"Son unos tres meses.","h2":"Después de una primera condena por DUI en Vermont, la licencia se suspende por 90 días y hasta que el conductor complete los pasos del programa de alcohol requerido.","p":"Correcto. Una primera condena por DUI significa 90 días de suspensión."},"ref":{"doc":"VT","page":null}},{"id":"vt-178","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, what happens to the license after a third conviction for driving under the influence (DUI)?","o":["A 90-day suspension","A one-year suspension","An 18-month suspension","It is revoked for life"],"h1":"A second conviction already brings 18 months.","h2":"After a third or later DUI conviction in Vermont, the license is revoked for life, although an ignition interlock permit may be possible.","p":"Right. A third DUI means lifetime revocation."},"es":{"q":"En Vermont, ¿qué pasa con la licencia después de una tercera condena por manejar bajo la influencia (DUI)?","o":["Una suspensión de 90 días","Una suspensión de un año","Una suspensión de 18 meses","Se revoca de por vida"],"h1":"Una segunda condena ya trae 18 meses.","h2":"Después de una tercera condena por DUI o más en Vermont, la licencia se revoca de por vida, aunque podría ser posible un permiso con dispositivo de bloqueo de encendido.","p":"Correcto. Un tercer DUI significa revocación de por vida."},"ref":{"doc":"VT","page":null}},{"id":"vt-179","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, what is the legal blood alcohol limit for a person driving a school bus?","o":["0.08","0.02","0.04","0.10"],"h1":"It is the strictest limit in the law, the same as for drivers under 21.","h2":"Vermont law forbids driving a school bus with an alcohol concentration of 0.02 or more.","p":"Right. The school bus limit is 0.02."},"es":{"q":"En Vermont, ¿cuál es el límite legal de alcohol en la sangre para una persona que maneja un autobús escolar?","o":["0.08","0.02","0.04","0.10"],"h1":"Es el límite más estricto de la ley, el mismo que para menores de 21.","h2":"La ley de Vermont prohíbe manejar un autobús escolar con una concentración de alcohol de 0.02 o más.","p":"Correcto. El límite para autobús escolar es 0.02."},"ref":{"doc":"VT","page":null}},{"id":"vt-180","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, what is the legal blood alcohol limit for a person driving a commercial vehicle?","o":["0.02","0.08","0.04","0.06"],"h1":"It is half of the limit for regular adult drivers.","h2":"Vermont law forbids driving a commercial vehicle with an alcohol concentration of 0.04 or more, half the 0.08 limit for other adult drivers.","p":"Right. The commercial limit is 0.04."},"es":{"q":"En Vermont, ¿cuál es el límite legal de alcohol en la sangre para una persona que maneja un vehículo comercial?","o":["0.02","0.08","0.04","0.06"],"h1":"Es la mitad del límite para conductores adultos normales.","h2":"La ley de Vermont prohíbe manejar un vehículo comercial con una concentración de alcohol de 0.04 o más, la mitad del límite de 0.08 para los demás conductores adultos.","p":"Correcto. El límite comercial es 0.04."},"ref":{"doc":"VT","page":null}},{"id":"vt-181","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, where may an open bottle of alcohol be carried while you drive?","o":["In an unlocked glove compartment","In a cup holder","Under the passenger seat","In the trunk, away from the seats"],"h1":"The passenger area includes anything you can reach from your seat.","h2":"Vermont law forbids an open container of alcohol in the passenger area, which includes an unlocked glove compartment, so it must be in a place like the trunk.","p":"Right. Keep it in the trunk, out of the passenger area."},"es":{"q":"En Vermont, ¿dónde se puede llevar una botella de alcohol abierta mientras maneja?","o":["En la guantera sin llave","En el portavasos","Debajo del asiento del pasajero","En la cajuela, lejos de los asientos"],"h1":"El área de pasajeros incluye todo lo que se alcanza desde el asiento.","h2":"La ley de Vermont prohíbe un envase abierto de alcohol en el área de pasajeros, que incluye la guantera sin llave, así que debe ir en un lugar como la cajuela.","p":"Correcto. Llévela en la cajuela, fuera del área de pasajeros."},"ref":{"doc":"VT","page":null}},{"id":"vt-182","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, a passenger wants to smoke cannabis in the car while you drive. What does the law say?","o":["It is not allowed; the driver may not consume cannabis, including secondhand smoke in the car","It is fine if the windows are open","It is fine if only the passenger smokes","It is fine on back roads"],"h1":"The law counts the smoke the driver breathes.","h2":"Vermont law forbids a driver from consuming cannabis while driving, and that includes secondhand cannabis smoke from someone else in the vehicle.","p":"Right. Even secondhand cannabis smoke counts against the driver."},"es":{"q":"En Vermont, un pasajero quiere fumar cannabis en el carro mientras usted maneja. ¿Qué dice la ley?","o":["No se permite; el conductor no puede consumir cannabis, incluso el humo de otros en el carro","Está bien si las ventanas van abiertas","Está bien si solo fuma el pasajero","Está bien en caminos rurales"],"h1":"La ley cuenta el humo que respira el conductor.","h2":"La ley de Vermont prohíbe que el conductor consuma cannabis mientras maneja, y eso incluye el humo de cannabis de otra persona dentro del vehículo.","p":"Correcto. Incluso el humo de otros cuenta contra el conductor."},"ref":{"doc":"VT","page":null}},{"id":"vt-183","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, when may an adult driver hold a phone in their hand to make a call?","o":["At a red light","In slow traffic","While driving under 25 mph","After pulling to the side of or off the road and stopping where it is safe and legal"],"h1":"Being stopped in traffic does not count.","h2":"Vermont allows hand-held phone use only after the driver has moved the vehicle to the side of or off the road and stopped where it can safely and lawfully stay.","p":"Right. Pull off the road and stop safely first."},"es":{"q":"En Vermont, ¿cuándo puede un conductor adulto tener el teléfono en la mano para hacer una llamada?","o":["En una luz roja","En tráfico lento","Manejando a menos de 25 mph","Después de orillarse o salirse del camino y parar donde sea seguro y legal"],"h1":"Estar detenido en el tráfico no cuenta.","h2":"Vermont permite usar el teléfono en la mano solo después de que el conductor mueve el vehículo a un lado o fuera del camino y para donde puede quedarse de forma segura y legal.","p":"Correcto. Primero salga del camino y pare de forma segura."},"ref":{"doc":"VT","page":null}},{"id":"vt-184","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, you hit a parked car and cause damage, but you cannot find the owner. What must you do?","o":["Drive away, since no one saw it","Wait at the car until the owner returns, however long it takes","Leave a note in or on the car with your name, address and phone number","Call the owner's insurance company"],"h1":"The owner needs a way to reach you.","h2":"If you damage a parked vehicle in Vermont and cannot find the owner, you must leave your name, address and phone number in or on that vehicle.","p":"Right. Leave a note with your contact information."},"es":{"q":"En Vermont, usted choca un carro estacionado y le causa daños, pero no encuentra al dueño. ¿Qué debe hacer?","o":["Irse, porque nadie lo vio","Esperar junto al carro hasta que vuelva el dueño, lo que tarde","Dejar una nota dentro o sobre el carro con su nombre, dirección y teléfono","Llamar a la compañía de seguros del dueño"],"h1":"El dueño necesita una forma de comunicarse con usted.","h2":"Si daña un vehículo estacionado en Vermont y no encuentra al dueño, debe dejar su nombre, dirección y teléfono dentro o sobre ese vehículo.","p":"Correcto. Deje una nota con sus datos."},"ref":{"doc":"VT","page":58}},{"id":"vt-185","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, after a crash where someone is hurt, within how many days must an insured driver give the injured person the name of their insurance company and policy number?","o":["5 days","72 hours","15 days","30 days"],"h1":"It is less than one week.","h2":"Vermont law requires the owner and operator of an insured vehicle to tell anyone injured, or whose property was damaged, the names of the insurance companies and policy numbers within five days.","p":"Right. Within five days."},"es":{"q":"En Vermont, después de un choque con una persona herida, ¿en cuántos días debe un conductor asegurado darle al herido el nombre de su compañía de seguros y el número de póliza?","o":["5 días","72 horas","15 días","30 días"],"h1":"Es menos de una semana.","h2":"La ley de Vermont exige que el dueño y el conductor de un vehículo asegurado le den a cualquier persona herida, o cuya propiedad fue dañada, los nombres de las compañías de seguros y los números de póliza en un plazo de cinco días.","p":"Correcto. En cinco días."},"ref":{"doc":"VT","page":null}},{"id":"vt-186","scope":"VT","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Vermont, how many points does a conviction for leaving the scene of a crash (failing to stop) add to your record?","o":["2 points","4 points","5 points","10 points"],"h1":"One conviction alone is enough to start a suspension.","h2":"Failing to stop when involved in a crash brings 10 points in Vermont, enough by itself to start a license suspension.","p":"Right. Leaving the scene brings 10 points."},"es":{"q":"En Vermont, ¿cuántos puntos agrega a su historial una condena por irse del lugar de un choque (no detenerse)?","o":["2 puntos","4 puntos","5 puntos","10 puntos"],"h1":"Una sola condena basta para empezar una suspensión.","h2":"No detenerse después de participar en un choque trae 10 puntos en Vermont, lo que por sí solo basta para empezar una suspensión de la licencia.","p":"Correcto. Irse del lugar trae 10 puntos."},"ref":{"doc":"VT","page":null}},{"id":"vt-187","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, how often must your vehicle be inspected?","o":["Once a year","Every two years","Every six months","Only when it is sold"],"h1":"The sticker shows when the next one is due.","h2":"Every vehicle in Vermont must be inspected once a year, and a newly registered vehicle must be inspected within 15 days unless it has a valid Vermont sticker.","p":"Right. Once a year."},"es":{"q":"En Vermont, ¿cada cuánto se debe inspeccionar su vehículo?","o":["Una vez al año","Cada dos años","Cada seis meses","Solo cuando se vende"],"h1":"La calcomanía muestra cuándo toca la siguiente.","h2":"Todo vehículo en Vermont se debe inspeccionar una vez al año, y un vehículo recién registrado se debe inspeccionar en 15 días a menos que tenga una calcomanía de Vermont válida.","p":"Correcto. Una vez al año."},"ref":{"doc":"VT","page":59}},{"id":"vt-188","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, may you hang something, like an air freshener, from the rearview mirror?","o":["Yes, anything of any size","Only if it does not materially block your view of the road","Only one item, of any size","Only at night"],"h1":"What matters is whether it gets in the way of your view.","h2":"Under Vermont law, an item hung behind the windshield is illegal only when it materially blocks the driver's view, so keep anything hanging there small and out of your line of sight.","p":"Right. It must not materially block your view."},"es":{"q":"En Vermont, ¿puede colgar algo, como un aromatizante, del espejo retrovisor?","o":["Sí, cualquier cosa de cualquier tamaño","Solo si no le tapa de forma importante la vista del camino","Solo una cosa, de cualquier tamaño","Solo de noche"],"h1":"Lo que importa es si le estorba la vista.","h2":"Según la ley de Vermont, un objeto colgado detrás del parabrisas es ilegal solo cuando tapa de forma importante la vista del conductor, así que mantenga lo que cuelgue allí pequeño y fuera de su línea de visión.","p":"Correcto. No debe taparle la vista de forma importante."},"ref":{"doc":"VT","page":null}},{"id":"vt-189","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, may you put tinting film on the side windows right next to the driver?","o":["Yes, any darkness","Yes, if it is light gray","No, unless the DMV gives a medical exemption","Only in summer"],"h1":"Vermont is strict about the front side windows.","h2":"Vermont law does not allow material on the windshield or the side windows next to the driver, except small allowed areas or a medical exemption granted by the Commissioner.","p":"Right. No tint there without a medical exemption."},"es":{"q":"En Vermont, ¿puede poner película polarizada en las ventanas laterales junto al conductor?","o":["Sí, de cualquier oscuridad","Sí, si es gris claro","No, a menos que el DMV dé una excepción médica","Solo en verano"],"h1":"Vermont es estricto con las ventanas laterales delanteras.","h2":"La ley de Vermont no permite material en el parabrisas ni en las ventanas laterales junto al conductor, salvo pequeñas áreas permitidas o una excepción médica dada por el Comisionado.","p":"Correcto. No se polarizan sin una excepción médica."},"ref":{"doc":"VT","page":null}},{"id":"vt-190","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, before you leave your car unattended on the street, what does the law require?","o":["Leave it running if you return in five minutes","Stop the engine, remove the key and set the brake","Only lock the doors","Turn on the flashers"],"h1":"An idling, unlocked car can roll or be taken.","h2":"Vermont law says you may not leave a vehicle unattended without stopping the engine, locking the ignition, removing the key and setting the brake, and turning the wheels to the curb on a hill.","p":"Right. Engine off, key out, brake set."},"es":{"q":"En Vermont, antes de dejar su carro solo en la calle, ¿qué exige la ley?","o":["Dejarlo prendido si regresa en cinco minutos","Apagar el motor, sacar la llave y poner el freno","Solo cerrar las puertas","Prender las intermitentes"],"h1":"Un carro prendido y abierto se puede mover o lo pueden robar.","h2":"La ley de Vermont dice que no puede dejar un vehículo solo sin apagar el motor, trabar el encendido, sacar la llave y poner el freno, y girar las llantas hacia la banqueta en una pendiente.","p":"Correcto. Motor apagado, llave fuera y freno puesto."},"ref":{"doc":"VT","page":null}},{"id":"vt-191","scope":"VT","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Vermont, can a police officer stop an adult driver only because someone age 18 or older is not wearing a seat belt?","o":["Yes, at any time","No, the seat belt law for adults is enforced only when the driver is stopped for another violation","Only on the Interstate","Only at night"],"h1":"Vermont treats this as a secondary offense for adults.","h2":"Vermont's seat belt law for people 18 and older may be enforced only when an officer has stopped the driver for another suspected traffic violation; the fine is $25 for a first violation.","p":"Right. It is enforced only with another violation."},"es":{"q":"En Vermont, ¿puede un policía detener a un conductor adulto solo porque alguien de 18 años o más no lleva el cinturón?","o":["Sí, en cualquier momento","No, la ley del cinturón para adultos solo se aplica cuando lo detienen por otra infracción","Solo en la interestatal","Solo de noche"],"h1":"Vermont lo trata como una falta secundaria para adultos.","h2":"La ley del cinturón de Vermont para personas de 18 años o más solo se puede aplicar cuando un policía detuvo al conductor por otra posible infracción de tránsito; la multa es de $25 la primera vez.","p":"Correcto. Solo se aplica junto con otra infracción."},"ref":{"doc":"VT","page":null}},{"id":"vt-192","scope":"VT","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Vermont, children under what age should ride in the back seat whenever practical?","o":["Under 13","Under 8","Under 10","Under 16"],"h1":"It is the age when a child becomes a teenager.","h2":"Vermont law says a child under 13 must ride in the back seat whenever it is practical.","p":"Right. Under 13 rides in the back."},"es":{"q":"En Vermont, ¿los niños menores de qué edad deben ir en el asiento de atrás siempre que se pueda?","o":["Menores de 13","Menores de 8","Menores de 10","Menores de 16"],"h1":"Es la edad en que un niño se vuelve adolescente.","h2":"La ley de Vermont dice que un niño menor de 13 años debe ir en el asiento de atrás siempre que sea posible.","p":"Correcto. Los menores de 13 van atrás."},"ref":{"doc":"VT","page":63}},{"id":"vt-193","scope":"VT","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Vermont, how must a child who is over 2 but under 5 years old ride?","o":["In a booster seat","In a seat belt only","In a rear-facing or forward-facing car seat with a harness","On an adult's lap"],"h1":"A harness is still needed at this age.","h2":"A Vermont child over 2 but under 5 must ride in a federally approved rear-facing or forward-facing car seat with a harness.","p":"Right. A harnessed car seat, rear- or forward-facing."},"es":{"q":"En Vermont, ¿cómo debe ir un niño mayor de 2 años pero menor de 5?","o":["En un asiento elevado (booster)","Solo con cinturón de seguridad","En un asiento de auto con arnés, mirando hacia atrás o hacia adelante","En las piernas de un adulto"],"h1":"A esta edad todavía se necesita un arnés.","h2":"Un niño en Vermont mayor de 2 años pero menor de 5 debe ir en un asiento de auto aprobado con arnés, mirando hacia atrás o hacia adelante.","p":"Correcto. Un asiento con arnés, hacia atrás o hacia adelante."},"ref":{"doc":"VT","page":62}},{"id":"vt-194","scope":"VT","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Vermont, how many points are added for driving more than 30 mph over the speed limit?","o":["2 points","3 points","5 points","8 points"],"h1":"It is the highest speeding level in the points table.","h2":"Vermont adds 8 points for driving more than 30 mph over the limit, compared with 2 points for less than 10 over, 3 for more than 10 over and 5 for more than 20 over.","p":"Right. More than 30 over means 8 points."},"es":{"q":"En Vermont, ¿cuántos puntos se agregan por manejar a más de 30 mph sobre el límite de velocidad?","o":["2 puntos","3 puntos","5 puntos","8 puntos"],"h1":"Es el nivel de velocidad más alto en la tabla de puntos.","h2":"Vermont agrega 8 puntos por manejar a más de 30 mph sobre el límite, comparado con 2 puntos por menos de 10 de más, 3 por más de 10 y 5 por más de 20.","p":"Correcto. Más de 30 de más son 8 puntos."},"ref":{"doc":"VT","page":null}},{"id":"vt-195","scope":"VT","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Vermont, how many points are added for following another vehicle too closely?","o":["2 points","3 points","5 points","10 points"],"h1":"It is the same as for illegal passing.","h2":"Following too closely is a 3-point violation in Vermont, the same as illegal passing and no-passing-zone violations.","p":"Right. Tailgating brings 3 points."},"es":{"q":"En Vermont, ¿cuántos puntos se agregan por seguir demasiado cerca a otro vehículo?","o":["2 puntos","3 puntos","5 puntos","10 puntos"],"h1":"Es lo mismo que por rebasar ilegalmente.","h2":"Seguir demasiado cerca es una infracción de 3 puntos en Vermont, igual que rebasar ilegalmente o en zona prohibida.","p":"Correcto. Ir pegado trae 3 puntos."},"ref":{"doc":"VT","page":null}},{"id":"vt-196","scope":"VT","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Vermont, how many points are added for failing to yield to an ambulance, fire truck or police vehicle?","o":["2 points","3 points","4 points","5 points"],"h1":"It is the same as passing a stopped school bus.","h2":"Failing to yield the right of way to an ambulance, fire truck or police vehicle adds 5 points to a Vermont driving record.","p":"Right. It adds 5 points."},"es":{"q":"En Vermont, ¿cuántos puntos se agregan por no ceder el paso a una ambulancia, un camión de bomberos o una patrulla?","o":["2 puntos","3 puntos","4 puntos","5 puntos"],"h1":"Es lo mismo que rebasar un autobús escolar detenido.","h2":"No ceder el paso a una ambulancia, un camión de bomberos o una patrulla agrega 5 puntos al historial de manejo en Vermont.","p":"Correcto. Agrega 5 puntos."},"ref":{"doc":"VT","page":64}},{"id":"vt-197","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, how long is the license suspension for reaching 15 points?","o":["10 days","20 days","30 days","90 days"],"h1":"It is longer than the 10 days for 10 points, and shorter than the 90 days for 20 points.","h2":"Vermont suspends a license for 30 days at 15 points, compared with 10 days at 10 points and 90 days at 20 points.","p":"Right. 15 points means a 30-day suspension."},"es":{"q":"En Vermont, ¿cuánto dura la suspensión de la licencia al llegar a 15 puntos?","o":["10 días","20 días","30 días","90 días"],"h1":"Es más que los 10 días por 10 puntos y menos que los 90 días por 20 puntos.","h2":"Vermont suspende la licencia por 30 días al llegar a 15 puntos, comparado con 10 días a los 10 puntos y 90 días a los 20 puntos.","p":"Correcto. 15 puntos significan 30 días de suspensión."},"ref":{"doc":"VT","page":null}},{"id":"vt-198","scope":"VT","cat":"licensing","sign":null,"c":0,"en":{"q":"In Vermont, you move here from another state with your car. How soon must you register it in Vermont?","o":["Within 60 days","Within 10 days","Within 6 months","Within 1 year"],"h1":"It is about two months.","h2":"A person moving to Vermont from another state must register their vehicle in Vermont within 60 days of moving in.","p":"Right. Register within 60 days."},"es":{"q":"En Vermont, usted se muda aquí desde otro estado con su carro. ¿En cuánto tiempo debe registrarlo en Vermont?","o":["En 60 días","En 10 días","En 6 meses","En 1 año"],"h1":"Son unos dos meses.","h2":"Una persona que se muda a Vermont desde otro estado debe registrar su vehículo en Vermont en un plazo de 60 días después de mudarse.","p":"Correcto. Regístrelo en 60 días."},"ref":{"doc":"VT","page":65}},{"id":"vt-199","scope":"VT","cat":"licensing","sign":null,"c":1,"en":{"q":"In Vermont, what percent is the Purchase and Use Tax when you buy a vehicle?","o":["3%","6%","8%","10%"],"h1":"It is a single-digit percent.","h2":"Vermont's Purchase and Use Tax is 6% of the price paid for the vehicle or its current fair market value, whichever is greater.","p":"Right. It is 6%."},"es":{"q":"En Vermont, ¿qué porcentaje es el Impuesto de Compra y Uso al comprar un vehículo?","o":["3%","6%","8%","10%"],"h1":"Es un porcentaje de un solo dígito.","h2":"El Impuesto de Compra y Uso de Vermont es el 6% del precio pagado por el vehículo o de su valor justo de mercado actual, lo que sea mayor.","p":"Correcto. Es el 6%."},"ref":{"doc":"VT","page":66}},{"id":"vt-200","scope":"VT","cat":"licensing","sign":null,"c":2,"en":{"q":"In Vermont, what is the minimum liability insurance for the injury or death of one person?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"The amount for two or more people is double this.","h2":"Vermont requires liability insurance of at least $25,000 for injury or death of one person, $50,000 for two or more people, and $10,000 for property damage.","p":"Right. $25,000 for one person."},"es":{"q":"En Vermont, ¿cuál es el seguro de responsabilidad mínimo por lesión o muerte de una persona?","o":["$10,000","$15,000","$25,000","$50,000"],"h1":"La cantidad para dos o más personas es el doble de esta.","h2":"Vermont exige un seguro de responsabilidad de por lo menos $25,000 por lesión o muerte de una persona, $50,000 por dos o más personas y $10,000 por daños a la propiedad.","p":"Correcto. $25,000 por una persona."},"ref":{"doc":"VT","page":67}},{"id":"wa-001","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, how many questions are on the knowledge test?","o":["25 questions","40 questions","50 questions","20 questions"],"h1":"It is a round number between 30 and 50.","h2":"The Washington knowledge test has 40 questions.","p":"Right. The test has 40 questions."},"es":{"q":"En Washington, ¿cuántas preguntas tiene el examen de conocimientos?","o":["25 preguntas","40 preguntas","50 preguntas","20 preguntas"],"h1":"Es un número redondo entre 30 y 50.","h2":"El examen de conocimientos de Washington tiene 40 preguntas.","p":"Correcto. El examen tiene 40 preguntas."},"zh":{"q":"在 Washington，笔试（knowledge test）有多少道题？","o":["25 道题","40 道题","50 道题","20 道题"],"h1":"它是 30 到 50 之间的一个整数。","h2":"Washington 的笔试有 40 道题。","p":"对。笔试有 40 道题。"},"vi":{"q":"Ở Washington, bài thi lý thuyết (knowledge test) có bao nhiêu câu hỏi?","o":["25 câu hỏi","40 câu hỏi","50 câu hỏi","20 câu hỏi"],"h1":"Đó là một số tròn giữa 30 và 50.","h2":"Bài thi lý thuyết ở Washington có 40 câu hỏi.","p":"Đúng. Bài thi có 40 câu hỏi."},"tl":{"q":"Sa Washington, ilang tanong ang nasa knowledge test?","o":["25 tanong","40 tanong","50 tanong","20 tanong"],"h1":"Isa itong buong numero sa pagitan ng 30 at 50.","h2":"May 40 tanong ang knowledge test sa Washington.","p":"Tama. May 40 tanong ang test."},"ar":{"q":"في Washington، كم سؤالًا في الامتحان النظري (knowledge test)؟","o":["25 سؤالًا","40 سؤالًا","50 سؤالًا","20 سؤالًا"],"h1":"هو عدد كامل بين 30 و50.","h2":"الامتحان النظري في Washington فيه 40 سؤالًا.","p":"صحيح. في الامتحان 40 سؤالًا."},"ref":{"doc":"WA","page":null}},{"id":"wa-002","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many correct answers do you need to pass the knowledge test?","o":["20","28","35","32"],"h1":"It is 80 percent of 40.","h2":"To pass the Washington knowledge test you need 32 correct answers out of 40, which is 80 percent.","p":"Correct. You need 32 right answers."},"es":{"q":"En Washington, ¿cuántas respuestas correctas necesita para aprobar el examen de conocimientos?","o":["20","28","35","32"],"h1":"Es el 80 por ciento de 40.","h2":"Para aprobar el examen de conocimientos de Washington necesita 32 respuestas correctas de 40, que es el 80 por ciento.","p":"Correcto. Necesita 32 respuestas correctas."},"zh":{"q":"在 Washington，笔试要答对多少道题才能通过？","o":["20","28","35","32"],"h1":"它是 40 的 80%。","h2":"要通过 Washington 的笔试，40 道题中你需要答对 32 道，也就是 80%。","p":"对。你需要答对 32 道题。"},"vi":{"q":"Ở Washington, bạn cần trả lời đúng bao nhiêu câu để đậu bài thi lý thuyết?","o":["20","28","35","32"],"h1":"Đó là 80% của 40.","h2":"Để đậu bài thi lý thuyết ở Washington, bạn cần trả lời đúng 32 trên 40 câu, tức là 80%.","p":"Đúng. Bạn cần 32 câu trả lời đúng."},"tl":{"q":"Sa Washington, ilang tamang sagot ang kailangan mo para pumasa sa knowledge test?","o":["20","28","35","32"],"h1":"Ito ang 80% ng 40.","h2":"Para pumasa sa knowledge test sa Washington, kailangan mo ng 32 tamang sagot sa 40, o 80%.","p":"Tama. Kailangan mo ng 32 tamang sagot."},"ar":{"q":"في Washington، كم إجابة صحيحة تحتاج لتنجح في الامتحان النظري؟","o":["20","28","35","32"],"h1":"هي 80% من 40.","h2":"لتنجح في الامتحان النظري في Washington تحتاج 32 إجابة صحيحة من 40، أي 80%.","p":"صحيح. تحتاج 32 إجابة صحيحة."},"ref":{"doc":"WA","page":null}},{"id":"wa-003","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long is a passing knowledge test score good for?","o":["2 years","30 days","6 months","Forever"],"h1":"It lasts more than one year.","h2":"A passing score on the Washington knowledge test stays valid for 2 years.","p":"Right. It is good for 2 years."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un puntaje aprobado en el examen de conocimientos?","o":["2 años","30 días","6 meses","Para siempre"],"h1":"Dura más de un año.","h2":"Un puntaje aprobado en el examen de conocimientos de Washington sigue siendo válido por 2 años.","p":"Correcto. Es válido por 2 años."},"zh":{"q":"在 Washington，笔试及格的成绩有效多久？","o":["2 年","30 天","6 个月","永久"],"h1":"它超过一年。","h2":"Washington 笔试的及格成绩有效期为 2 年。","p":"对。有效期是 2 年。"},"vi":{"q":"Ở Washington, điểm đậu bài thi lý thuyết có giá trị trong bao lâu?","o":["2 năm","30 ngày","6 tháng","Mãi mãi"],"h1":"Nó kéo dài hơn một năm.","h2":"Điểm đậu bài thi lý thuyết ở Washington có giá trị trong 2 năm.","p":"Đúng. Nó có giá trị 2 năm."},"tl":{"q":"Sa Washington, gaano katagal may bisa ang pumasang score sa knowledge test?","o":["2 taon","30 araw","6 na buwan","Habambuhay"],"h1":"Mas matagal ito sa isang taon.","h2":"Ang pumasang score sa knowledge test sa Washington ay may bisa nang 2 taon.","p":"Tama. May bisa ito nang 2 taon."},"ar":{"q":"في Washington، كم مدة صلاحية نتيجة النجاح في الامتحان النظري؟","o":["2 سنة","30 يومًا","6 أشهر","إلى الأبد"],"h1":"هي أكثر من سنة واحدة.","h2":"نتيجة النجاح في الامتحان النظري في Washington تبقى صالحة لمدة 2 سنة.","p":"صحيح. هي صالحة لمدة 2 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-004","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what is the youngest age to get an instruction permit if you are enrolled in driver training?","o":["14","14 and a half","15","16"],"h1":"Without a course you would wait six months longer.","h2":"In Washington you can get an instruction permit at 15 if you are enrolled in an approved driver training course.","p":"Correct. Age 15 with driver training."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción si está inscrito en un curso de manejo?","o":["14 años","14 años y medio","15 años","16 años"],"h1":"Sin curso tendría que esperar seis meses más.","h2":"En Washington usted puede obtener un permiso de instrucción a los 15 años si está inscrito en un curso de manejo aprobado.","p":"Correcto. A los 15 con curso de manejo."},"zh":{"q":"在 Washington，如果你报名参加了驾驶培训课程，最小几岁可以拿到学习驾照（instruction permit）？","o":["14","14 岁半","15","16"],"h1":"如果不上课程，你要多等六个月。","h2":"在 Washington，如果你报名参加了批准的驾驶培训课程，15 岁就可以拿到学习驾照。","p":"对。参加驾驶培训可以在 15 岁拿到。"},"vi":{"q":"Ở Washington, nếu bạn đã ghi danh khóa huấn luyện lái xe, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["14","14 tuổi rưỡi","15","16"],"h1":"Nếu không học khóa nào, bạn phải chờ thêm sáu tháng.","h2":"Ở Washington, bạn có thể lấy giấy phép tập lái khi 15 tuổi nếu bạn đã ghi danh một khóa huấn luyện lái xe được chấp thuận.","p":"Đúng. 15 tuổi khi có học lái xe."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para makakuha ng instruction permit kung naka-enroll ka sa driver training?","o":["14","14 at kalahati","15","16"],"h1":"Kung walang kurso, maghihintay ka pa nang anim na buwan.","h2":"Sa Washington, puwede kang kumuha ng instruction permit sa edad na 15 kung naka-enroll ka sa aprubadong driver training course.","p":"Tama. Edad 15 kapag may driver training."},"ar":{"q":"في Washington، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit) إذا كنت مسجّلًا في دورة تدريب على القيادة؟","o":["14","14 سنة ونصف","15","16"],"h1":"بدون دورة ستنتظر ستة أشهر أكثر.","h2":"في Washington يمكنك الحصول على تصريح التعلّم في عمر 15 سنة إذا كنت مسجّلًا في دورة تدريب على القيادة معتمدة.","p":"صحيح. عمر 15 سنة مع دورة تدريب."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-005","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to get an instruction permit without enrolling in driver training?","o":["15","15 and a half","16","17"],"h1":"It is half a year later than with a course.","h2":"In Washington a teen who is not in a driver training course must be 15 and a half to get an instruction permit.","p":"Right. 15 and a half without a course."},"es":{"q":"En Washington, ¿cuál es la edad mínima para obtener un permiso de instrucción sin inscribirse en un curso de manejo?","o":["15 años","15 años y medio","16 años","17 años"],"h1":"Es medio año más tarde que con un curso.","h2":"En Washington un joven que no está en un curso de manejo debe tener 15 años y medio para obtener un permiso de instrucción.","p":"Correcto. 15 años y medio sin curso."},"zh":{"q":"在 Washington，如果不参加驾驶培训课程，最小几岁可以拿到学习驾照（instruction permit）？","o":["15","15 岁半","16","17"],"h1":"它比上课程的情况晚半年。","h2":"在 Washington，没有参加驾驶培训课程的青少年必须年满 15 岁半才能拿到学习驾照。","p":"对。不上课程要 15 岁半。"},"vi":{"q":"Ở Washington, nếu không ghi danh khóa huấn luyện lái xe, tuổi nhỏ nhất để lấy giấy phép tập lái (instruction permit) là bao nhiêu?","o":["15","15 tuổi rưỡi","16","17"],"h1":"Nó trễ hơn nửa năm so với khi có học khóa.","h2":"Ở Washington, thiếu niên không học khóa huấn luyện lái xe phải đủ 15 tuổi rưỡi mới lấy được giấy phép tập lái.","p":"Đúng. 15 tuổi rưỡi nếu không học khóa."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para makakuha ng instruction permit kung hindi ka naka-enroll sa driver training?","o":["15","15 at kalahati","16","17"],"h1":"Kalahating taon itong mas huli kaysa kapag may kurso.","h2":"Sa Washington, ang tinedyer na wala sa driver training course ay dapat 15 at kalahating taong gulang para makakuha ng instruction permit.","p":"Tama. 15 at kalahati kapag walang kurso."},"ar":{"q":"في Washington، ما أصغر عمر للحصول على تصريح التعلّم (instruction permit) بدون التسجيل في دورة تدريب على القيادة؟","o":["15","15 سنة ونصف","16","17"],"h1":"هو بعد نصف سنة من العمر مع الدورة.","h2":"في Washington يجب أن يكون عمر المراهق غير المسجّل في دورة تدريب على القيادة 15 سنة ونصف ليحصل على تصريح التعلّم.","p":"صحيح. 15 سنة ونصف بدون دورة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-006","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, who may supervise a driver with an instruction permit?","o":["Any person 16 or older","Any passenger with a car","A driver licensed for at least 1 year","A driver licensed for at least 5 years"],"h1":"The rule is about years of driving experience, not age.","h2":"A Washington permit holder must drive with a driving instructor or a licensed driver who has at least 5 years of driving experience.","p":"Correct. Licensed for 5 years or more."},"es":{"q":"En Washington, ¿quién puede supervisar a un conductor con permiso de instrucción?","o":["Cualquier persona de 16 años o más","Cualquier pasajero que tenga carro","Un conductor con licencia desde hace por lo menos 1 año","Un conductor con licencia desde hace por lo menos 5 años"],"h1":"La regla se refiere a los años de experiencia, no a la edad.","h2":"En Washington, quien tiene permiso debe manejar con un instructor de manejo o con un conductor con licencia que tenga por lo menos 5 años de experiencia.","p":"Correcto. Con licencia desde hace 5 años o más."},"zh":{"q":"在 Washington，谁可以监督持有学习驾照的驾驶人？","o":["任何 16 岁或以上的人","任何有车的乘客","有驾照至少 1 年的驾驶人","有驾照至少 5 年的驾驶人"],"h1":"这条规定看的是驾驶经验的年数，不是年龄。","h2":"Washington 的学习驾照持有人必须和驾驶教练一起开车，或者和有至少 5 年驾驶经验的持照驾驶人一起开车。","p":"对。有驾照 5 年或以上。"},"vi":{"q":"Ở Washington, ai có thể giám sát người lái có giấy phép tập lái?","o":["Bất kỳ ai từ 16 tuổi trở lên","Bất kỳ hành khách nào có xe","Người lái có bằng ít nhất 1 năm","Người lái có bằng ít nhất 5 năm"],"h1":"Quy định này dựa trên số năm kinh nghiệm lái xe, không phải tuổi.","h2":"Ở Washington, người có giấy phép tập lái phải lái cùng giáo viên dạy lái xe hoặc một người có bằng lái với ít nhất 5 năm kinh nghiệm lái xe.","p":"Đúng. Có bằng lái từ 5 năm trở lên."},"tl":{"q":"Sa Washington, sino ang puwedeng magbantay sa driver na may instruction permit?","o":["Kahit sinong 16 taong gulang pataas","Kahit sinong pasahero na may kotse","Driver na may lisensya nang hindi bababa sa 1 taon","Driver na may lisensya nang hindi bababa sa 5 taon"],"h1":"Tungkol sa dami ng taon ng karanasan sa pagmamaneho ang patakaran, hindi sa edad.","h2":"Sa Washington, ang may permit ay dapat magmaneho kasama ang driving instructor o lisensyadong driver na may hindi bababa sa 5 taong karanasan sa pagmamaneho.","p":"Tama. May lisensya nang 5 taon o higit pa."},"ar":{"q":"في Washington، من يمكنه أن يراقب سائقًا معه تصريح تعلّم؟","o":["أي شخص عمره 16 سنة أو أكثر","أي راكب عنده سيارة","سائق معه رخصة منذ سنة 1 على الأقل","سائق معه رخصة منذ 5 سنوات على الأقل"],"h1":"القاعدة عن عدد سنوات الخبرة في القيادة، وليس عن العمر.","h2":"في Washington يجب أن يقود صاحب التصريح مع مدرّب قيادة أو مع سائق له رخصة وخبرة في القيادة 5 سنوات على الأقل.","p":"صحيح. معه رخصة منذ 5 سنوات أو أكثر."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-007","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, where must the supervising driver sit when a permit holder drives?","o":["In the seat beside the driver","In the back seat","Anywhere in the car","In another car following behind"],"h1":"The helper must be close enough to help right away.","h2":"In Washington the supervising driver must sit in the seat beside the permit holder.","p":"Right. Beside the driver."},"es":{"q":"En Washington, ¿dónde debe sentarse el conductor que supervisa cuando maneja alguien con permiso?","o":["En el asiento al lado del conductor","En el asiento de atrás","En cualquier lugar del carro","En otro carro que va detrás"],"h1":"El acompañante debe estar lo bastante cerca para ayudar de inmediato.","h2":"En Washington el conductor que supervisa debe sentarse en el asiento al lado de quien tiene el permiso.","p":"Correcto. Al lado del conductor."},"zh":{"q":"在 Washington，学习驾照持有人开车时，监督的驾驶人必须坐在哪里？","o":["坐在驾驶人旁边的座位","坐在后座","坐在车里任何地方","坐在后面跟着的另一辆车里"],"h1":"帮忙的人必须坐得够近，可以马上帮忙。","h2":"在 Washington，监督的驾驶人必须坐在学习驾照持有人旁边的座位上。","p":"对。坐在驾驶人旁边。"},"vi":{"q":"Ở Washington, khi người có giấy phép tập lái đang lái, người giám sát phải ngồi ở đâu?","o":["Ở ghế bên cạnh người lái","Ở ghế sau","Ở bất kỳ chỗ nào trong xe","Trong một xe khác chạy theo sau"],"h1":"Người giúp phải ngồi đủ gần để giúp ngay lập tức.","h2":"Ở Washington, người giám sát phải ngồi ở ghế bên cạnh người có giấy phép tập lái.","p":"Đúng. Bên cạnh người lái."},"tl":{"q":"Sa Washington, saan dapat umupo ang nagbabantay na driver kapag nagmamaneho ang may permit?","o":["Sa upuan sa tabi ng driver","Sa likod na upuan","Kahit saan sa kotse","Sa ibang kotse na sumusunod sa likod"],"h1":"Dapat sapat na malapit ang tumutulong para makatulong agad.","h2":"Sa Washington, ang nagbabantay na driver ay dapat umupo sa upuan sa tabi ng may permit.","p":"Tama. Sa tabi ng driver."},"ar":{"q":"في Washington، أين يجب أن يجلس السائق المراقب عندما يقود صاحب التصريح؟","o":["في المقعد بجانب السائق","في المقعد الخلفي","في أي مكان في السيارة","في سيارة أخرى تسير خلفه"],"h1":"يجب أن يكون المساعد قريبًا بما يكفي ليساعد فورًا.","h2":"في Washington يجب أن يجلس السائق المراقب في المقعد بجانب صاحب التصريح.","p":"صحيح. بجانب السائق."},"ref":{"doc":"WA","page":null}},{"id":"wa-008","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how long is an instruction permit valid?","o":["30 days","6 months","1 year","5 years"],"h1":"It can be renewed for a fee when it runs out.","h2":"A Washington instruction permit is valid for 1 year and can be renewed for a fee.","p":"Correct. One year."},"es":{"q":"En Washington, ¿por cuánto tiempo es válido un permiso de instrucción?","o":["30 días","6 meses","1 año","5 años"],"h1":"Se puede renovar pagando una tarifa cuando vence.","h2":"Un permiso de instrucción en Washington es válido por 1 año y se puede renovar pagando una tarifa.","p":"Correcto. Un año."},"zh":{"q":"在 Washington，学习驾照（instruction permit）有效多久？","o":["30 天","6 个月","1 年","5 年"],"h1":"到期后可以付费续期。","h2":"Washington 的学习驾照有效期为 1 年，可以付费续期。","p":"对。一年。"},"vi":{"q":"Ở Washington, giấy phép tập lái (instruction permit) có giá trị trong bao lâu?","o":["30 ngày","6 tháng","1 năm","5 năm"],"h1":"Khi hết hạn, có thể gia hạn nếu trả phí.","h2":"Giấy phép tập lái ở Washington có giá trị 1 năm và có thể gia hạn nếu trả phí.","p":"Đúng. Một năm."},"tl":{"q":"Sa Washington, gaano katagal may bisa ang instruction permit?","o":["30 araw","6 na buwan","1 taon","5 taon"],"h1":"Puwede itong i-renew nang may bayad kapag nag-expire.","h2":"Ang instruction permit sa Washington ay may bisa nang 1 taon at puwedeng i-renew nang may bayad.","p":"Tama. Isang taon."},"ar":{"q":"في Washington، كم مدة صلاحية تصريح التعلّم (instruction permit)؟","o":["30 يومًا","6 أشهر","1 سنة","5 سنوات"],"h1":"يمكن تجديده مقابل رسوم عندما ينتهي.","h2":"تصريح التعلّم في Washington صالح لمدة 1 سنة، ويمكن تجديده مقابل رسوم.","p":"صحيح. سنة واحدة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-009","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what must a teen do to get a driver license before turning 18?","o":["Nothing extra","Take a driver training course","Pass a test in another state","Wait until a parent turns 40"],"h1":"Without it, the teen must wait until 18.","h2":"In Washington a teen who wants a driver license before 18 must take a driver training course.","p":"Right. Driver training is required before 18."},"es":{"q":"En Washington, ¿qué debe hacer un joven para obtener la licencia antes de cumplir 18 años?","o":["Nada adicional","Tomar un curso de manejo","Aprobar un examen en otro estado","Esperar a que su padre o madre cumpla 40"],"h1":"Sin esto, el joven debe esperar hasta los 18.","h2":"En Washington un joven que quiere la licencia antes de los 18 años debe tomar un curso de manejo.","p":"Correcto. El curso de manejo es obligatorio antes de los 18."},"zh":{"q":"在 Washington，青少年想在 18 岁以前拿到驾照，必须做什么？","o":["不用做额外的事","参加驾驶培训课程","在另一个州考试","等到父母满 40 岁"],"h1":"如果不做这件事，青少年必须等到 18 岁。","h2":"在 Washington，想在 18 岁以前拿到驾照的青少年必须参加驾驶培训课程。","p":"对。18 岁以前必须参加驾驶培训。"},"vi":{"q":"Ở Washington, thiếu niên phải làm gì để lấy bằng lái trước khi đủ 18 tuổi?","o":["Không cần làm gì thêm","Học một khóa huấn luyện lái xe","Thi ở một tiểu bang khác","Chờ cho đến khi cha mẹ 40 tuổi"],"h1":"Nếu không làm việc này, thiếu niên phải chờ đến 18 tuổi.","h2":"Ở Washington, thiếu niên muốn có bằng lái trước 18 tuổi phải học một khóa huấn luyện lái xe.","p":"Đúng. Phải học lái xe nếu dưới 18 tuổi."},"tl":{"q":"Sa Washington, ano ang dapat gawin ng tinedyer para makakuha ng driver license bago mag-18?","o":["Wala nang iba","Kumuha ng driver training course","Pumasa sa test sa ibang estado","Maghintay hanggang mag-40 ang magulang"],"h1":"Kung wala ito, dapat maghintay ang tinedyer hanggang 18.","h2":"Sa Washington, ang tinedyer na gustong magka-driver license bago mag-18 ay dapat kumuha ng driver training course.","p":"Tama. Kailangan ang driver training bago mag-18."},"ar":{"q":"في Washington، ماذا يجب أن يفعل المراهق ليحصل على رخصة قيادة قبل عمر 18 سنة؟","o":["لا شيء إضافي","أن يأخذ دورة تدريب على القيادة","أن ينجح في امتحان في ولاية أخرى","أن ينتظر حتى يصبح عمر أحد الوالدين 40 سنة"],"h1":"بدون ذلك يجب أن ينتظر المراهق حتى عمر 18 سنة.","h2":"في Washington يجب على المراهق الذي يريد رخصة قيادة قبل عمر 18 سنة أن يأخذ دورة تدريب على القيادة.","p":"صحيح. دورة التدريب مطلوبة قبل عمر 18 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-010","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how long must a teen hold an instruction permit before getting an intermediate license?","o":["At least 6 months","At least 1 month","At least 2 years","No minimum"],"h1":"It is half a year.","h2":"A Washington teen must hold an instruction permit for at least 6 months before getting an intermediate license.","p":"Correct. At least 6 months."},"es":{"q":"En Washington, ¿por cuánto tiempo debe un joven tener el permiso de instrucción antes de obtener la licencia intermedia?","o":["Por lo menos 6 meses","Por lo menos 1 mes","Por lo menos 2 años","No hay un mínimo"],"h1":"Es medio año.","h2":"Un joven en Washington debe tener el permiso de instrucción por lo menos 6 meses antes de obtener la licencia intermedia.","p":"Correcto. Por lo menos 6 meses."},"zh":{"q":"在 Washington，青少年要持有学习驾照多久，才能拿到中级驾照（intermediate license）？","o":["至少 6 个月","至少 1 个月","至少 2 年","没有最短时间"],"h1":"是半年。","h2":"Washington 的青少年必须持有学习驾照至少 6 个月，才能拿到中级驾照。","p":"对。至少 6 个月。"},"vi":{"q":"Ở Washington, thiếu niên phải giữ giấy phép tập lái bao lâu trước khi lấy bằng lái trung cấp (intermediate license)?","o":["Ít nhất 6 tháng","Ít nhất 1 tháng","Ít nhất 2 năm","Không có thời gian tối thiểu"],"h1":"Đó là nửa năm.","h2":"Thiếu niên ở Washington phải giữ giấy phép tập lái ít nhất 6 tháng trước khi lấy bằng lái trung cấp.","p":"Đúng. Ít nhất 6 tháng."},"tl":{"q":"Sa Washington, gaano katagal dapat hawak ng tinedyer ang instruction permit bago makakuha ng intermediate license?","o":["Hindi bababa sa 6 na buwan","Hindi bababa sa 1 buwan","Hindi bababa sa 2 taon","Walang minimum"],"h1":"Kalahating taon ito.","h2":"Ang tinedyer sa Washington ay dapat may hawak na instruction permit nang hindi bababa sa 6 na buwan bago makakuha ng intermediate license.","p":"Tama. Hindi bababa sa 6 na buwan."},"ar":{"q":"في Washington، كم مدة يجب أن يحمل المراهق تصريح التعلّم قبل الحصول على الرخصة المتوسطة (intermediate license)؟","o":["6 أشهر على الأقل","شهر 1 على الأقل","2 سنة على الأقل","لا يوجد حد أدنى"],"h1":"هي نصف سنة.","h2":"يجب على المراهق في Washington أن يحمل تصريح التعلّم 6 أشهر على الأقل قبل الحصول على الرخصة المتوسطة.","p":"صحيح. 6 أشهر على الأقل."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-011","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many hours of supervised daytime driving does a teen need before an intermediate license?","o":["10 hours","20 hours","30 hours","40 hours"],"h1":"Add 10 night hours to it and you get 50.","h2":"A Washington teen needs at least 40 hours of supervised daytime driving, plus 10 hours at night, before an intermediate license.","p":"Right. Forty daytime hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de día necesita un joven antes de la licencia intermedia?","o":["10 horas","20 horas","30 horas","40 horas"],"h1":"Si le suma 10 horas de noche, da 50.","h2":"Un joven en Washington necesita por lo menos 40 horas de manejo supervisado de día, más 10 horas de noche, antes de la licencia intermedia.","p":"Correcto. Cuarenta horas de día."},"zh":{"q":"在 Washington，青少年在拿到中级驾照以前，需要多少小时有人监督的白天驾驶？","o":["10 小时","20 小时","30 小时","40 小时"],"h1":"再加上 10 小时夜间驾驶，就是 50 小时。","h2":"Washington 的青少年在拿到中级驾照以前，需要至少 40 小时有人监督的白天驾驶，再加 10 小时夜间驾驶。","p":"对。白天 40 小时。"},"vi":{"q":"Ở Washington, thiếu niên cần bao nhiêu giờ lái ban ngày có người giám sát trước khi lấy bằng lái trung cấp?","o":["10 giờ","20 giờ","30 giờ","40 giờ"],"h1":"Cộng thêm 10 giờ ban đêm thì được 50.","h2":"Thiếu niên ở Washington cần ít nhất 40 giờ lái ban ngày có người giám sát, cộng thêm 10 giờ ban đêm, trước khi lấy bằng lái trung cấp.","p":"Đúng. Bốn mươi giờ ban ngày."},"tl":{"q":"Sa Washington, ilang oras ng binabantayang pagmamaneho sa araw ang kailangan ng tinedyer bago makakuha ng intermediate license?","o":["10 oras","20 oras","30 oras","40 oras"],"h1":"Dagdagan ito ng 10 oras sa gabi at magiging 50.","h2":"Ang tinedyer sa Washington ay kailangan ng hindi bababa sa 40 oras ng binabantayang pagmamaneho sa araw, at 10 oras sa gabi, bago makakuha ng intermediate license.","p":"Tama. Apatnapung oras sa araw."},"ar":{"q":"في Washington، كم ساعة من القيادة في النهار مع مراقب يحتاج المراهق قبل الرخصة المتوسطة؟","o":["10 ساعات","20 ساعة","30 ساعة","40 ساعة"],"h1":"أضف إليها 10 ساعات في الليل فتصبح 50.","h2":"يحتاج المراهق في Washington إلى 40 ساعة على الأقل من القيادة في النهار مع مراقب، وأيضًا 10 ساعات في الليل، قبل الرخصة المتوسطة.","p":"صحيح. أربعون ساعة في النهار."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-012","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how many hours of supervised night driving does a teen need before an intermediate license?","o":["2 hours","5 hours","10 hours","40 hours"],"h1":"It is a round number, a quarter of the daytime hours.","h2":"A Washington teen needs at least 10 hours of supervised night driving before an intermediate license.","p":"Correct. Ten night hours."},"es":{"q":"En Washington, ¿cuántas horas de manejo supervisado de noche necesita un joven antes de la licencia intermedia?","o":["2 horas","5 horas","10 horas","40 horas"],"h1":"Es un número redondo, la cuarta parte de las horas de día.","h2":"Un joven en Washington necesita por lo menos 10 horas de manejo supervisado de noche antes de la licencia intermedia.","p":"Correcto. Diez horas de noche."},"zh":{"q":"在 Washington，青少年在拿到中级驾照以前，需要多少小时有人监督的夜间驾驶？","o":["2 小时","5 小时","10 小时","40 小时"],"h1":"它是一个整数，是白天小时数的四分之一。","h2":"Washington 的青少年在拿到中级驾照以前，需要至少 10 小时有人监督的夜间驾驶。","p":"对。夜间 10 小时。"},"vi":{"q":"Ở Washington, thiếu niên cần bao nhiêu giờ lái ban đêm có người giám sát trước khi lấy bằng lái trung cấp?","o":["2 giờ","5 giờ","10 giờ","40 giờ"],"h1":"Đó là một số tròn, bằng một phần tư số giờ ban ngày.","h2":"Thiếu niên ở Washington cần ít nhất 10 giờ lái ban đêm có người giám sát trước khi lấy bằng lái trung cấp.","p":"Đúng. Mười giờ ban đêm."},"tl":{"q":"Sa Washington, ilang oras ng binabantayang pagmamaneho sa gabi ang kailangan ng tinedyer bago makakuha ng intermediate license?","o":["2 oras","5 oras","10 oras","40 oras"],"h1":"Isa itong buong numero, isang-kapat ng oras sa araw.","h2":"Ang tinedyer sa Washington ay kailangan ng hindi bababa sa 10 oras ng binabantayang pagmamaneho sa gabi bago makakuha ng intermediate license.","p":"Tama. Sampung oras sa gabi."},"ar":{"q":"في Washington، كم ساعة من القيادة في الليل مع مراقب يحتاج المراهق قبل الرخصة المتوسطة؟","o":["2 ساعة","5 ساعات","10 ساعات","40 ساعة"],"h1":"هو عدد كامل، ربع ساعات النهار.","h2":"يحتاج المراهق في Washington إلى 10 ساعات على الأقل من القيادة في الليل مع مراقب قبل الرخصة المتوسطة.","p":"صحيح. عشر ساعات في الليل."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-013","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, what is the youngest age to apply for an intermediate license?","o":["15","16","17","18"],"h1":"It comes after holding a permit for at least six months.","h2":"In Washington you can apply for an intermediate license at 16.","p":"Right. Age 16."},"es":{"q":"En Washington, ¿cuál es la edad mínima para solicitar una licencia intermedia?","o":["15 años","16 años","17 años","18 años"],"h1":"Llega después de tener el permiso por lo menos seis meses.","h2":"En Washington usted puede solicitar una licencia intermedia a los 16 años.","p":"Correcto. A los 16 años."},"zh":{"q":"在 Washington，最小几岁可以申请中级驾照（intermediate license）？","o":["15","16","17","18"],"h1":"它是在持有学习驾照至少六个月以后。","h2":"在 Washington，你 16 岁可以申请中级驾照。","p":"对。16 岁。"},"vi":{"q":"Ở Washington, tuổi nhỏ nhất để nộp đơn xin bằng lái trung cấp (intermediate license) là bao nhiêu?","o":["15","16","17","18"],"h1":"Nó đến sau khi giữ giấy phép tập lái ít nhất sáu tháng.","h2":"Ở Washington, bạn có thể nộp đơn xin bằng lái trung cấp khi 16 tuổi.","p":"Đúng. 16 tuổi."},"tl":{"q":"Sa Washington, ano ang pinakabatang edad para mag-apply ng intermediate license?","o":["15","16","17","18"],"h1":"Darating ito pagkatapos hawakan ang permit nang hindi bababa sa anim na buwan.","h2":"Sa Washington, puwede kang mag-apply ng intermediate license sa edad na 16.","p":"Tama. Edad 16."},"ar":{"q":"في Washington، ما أصغر عمر لتقديم طلب الرخصة المتوسطة (intermediate license)؟","o":["15","16","17","18"],"h1":"يأتي بعد حمل التصريح ستة أشهر على الأقل.","h2":"في Washington يمكنك تقديم طلب الرخصة المتوسطة في عمر 16 سنة.","p":"صحيح. عمر 16 سنة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-014","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during which hours may an intermediate license holder not drive, unless an exception applies?","o":["1 a.m. to 5 a.m.","Midnight to 6 a.m.","10 p.m. to 5 a.m.","11 p.m. to 4 a.m."],"h1":"The window is four hours long and starts after midnight.","h2":"A Washington intermediate license holder may not drive between 1 a.m. and 5 a.m., unless an exception applies.","p":"Correct. No driving from 1 to 5 a.m."},"es":{"q":"En Washington, ¿en qué horario no puede manejar el titular de una licencia intermedia, salvo una excepción?","o":["De 1 a.m. a 5 a.m.","De medianoche a 6 a.m.","De 10 p.m. a 5 a.m.","De 11 p.m. a 4 a.m."],"h1":"El período dura cuatro horas y empieza después de medianoche.","h2":"El titular de una licencia intermedia en Washington no puede manejar entre la 1 a.m. y las 5 a.m., salvo una excepción.","p":"Correcto. No se maneja de 1 a 5 a.m."},"zh":{"q":"在 Washington，除非有例外情况，中级驾照持有人在哪段时间不可以开车？","o":["凌晨 1 点到凌晨 5 点","午夜 12 点到早上 6 点","晚上 10 点到凌晨 5 点","晚上 11 点到凌晨 4 点"],"h1":"这段时间有四个小时，在午夜以后开始。","h2":"除非有例外情况，Washington 的中级驾照持有人不可以在凌晨 1 点到凌晨 5 点之间开车。","p":"对。凌晨 1 点到 5 点不能开车。"},"vi":{"q":"Ở Washington, trừ khi có trường hợp ngoại lệ, người có bằng lái trung cấp không được lái xe trong khoảng giờ nào?","o":["1 giờ sáng đến 5 giờ sáng","Nửa đêm đến 6 giờ sáng","10 giờ tối đến 5 giờ sáng","11 giờ tối đến 4 giờ sáng"],"h1":"Khoảng thời gian này dài bốn giờ và bắt đầu sau nửa đêm.","h2":"Người có bằng lái trung cấp ở Washington không được lái xe từ 1 giờ sáng đến 5 giờ sáng, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Không lái từ 1 đến 5 giờ sáng."},"tl":{"q":"Sa Washington, anong oras hindi puwedeng magmaneho ang may intermediate license, maliban kung may exception?","o":["1 a.m. hanggang 5 a.m.","Hatinggabi hanggang 6 a.m.","10 p.m. hanggang 5 a.m.","11 p.m. hanggang 4 a.m."],"h1":"Apat na oras ang haba nito at nagsisimula pagkatapos ng hatinggabi.","h2":"Ang may intermediate license sa Washington ay hindi puwedeng magmaneho mula 1 a.m. hanggang 5 a.m., maliban kung may exception.","p":"Tama. Bawal magmaneho mula 1 hanggang 5 a.m."},"ar":{"q":"في Washington، في أي ساعات لا يجوز لصاحب الرخصة المتوسطة أن يقود، إلا إذا كان هناك استثناء؟","o":["من 1 صباحًا إلى 5 صباحًا","من منتصف الليل إلى 6 صباحًا","من 10 مساءً إلى 5 صباحًا","من 11 مساءً إلى 4 صباحًا"],"h1":"المدة أربع ساعات وتبدأ بعد منتصف الليل.","h2":"لا يجوز لصاحب الرخصة المتوسطة في Washington أن يقود بين 1 صباحًا و5 صباحًا، إلا إذا كان هناك استثناء.","p":"صحيح. لا قيادة من 1 إلى 5 صباحًا."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-015","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, which of these lets an intermediate license holder drive between 1 a.m. and 5 a.m.?","o":["Driving to a party","Driving with a friend who is 18","Driving on an empty road","Driving with a licensed driver who is at least 25"],"h1":"An older, experienced driver must be in the car, or the trip is for school, religion or work.","h2":"In Washington an intermediate license holder may drive between 1 a.m. and 5 a.m. with a licensed driver at least 25, or for school, religious or work activities.","p":"Right. A licensed driver 25 or older."},"es":{"q":"En Washington, ¿cuál de estas opciones permite al titular de una licencia intermedia manejar entre la 1 a.m. y las 5 a.m.?","o":["Ir a una fiesta","Manejar con un amigo de 18 años","Manejar por una calle vacía","Manejar con un conductor con licencia de por lo menos 25 años"],"h1":"Debe ir un conductor mayor con experiencia, o el viaje debe ser por escuela, religión o trabajo.","h2":"En Washington el titular de una licencia intermedia puede manejar entre la 1 a.m. y las 5 a.m. con un conductor con licencia de por lo menos 25 años, o para actividades escolares, religiosas o de trabajo.","p":"Correcto. Un conductor con licencia de 25 años o más."},"zh":{"q":"在 Washington，下面哪一种情况可以让中级驾照持有人在凌晨 1 点到凌晨 5 点之间开车？","o":["开车去参加聚会","和一个 18 岁的朋友一起开车","在空荡的路上开车","和一个至少 25 岁的持照驾驶人一起开车"],"h1":"车里必须有一位年龄较大、有经验的驾驶人，或者是为了上学、宗教或工作。","h2":"在 Washington，中级驾照持有人可以在凌晨 1 点到凌晨 5 点之间开车，条件是有一位至少 25 岁的持照驾驶人在车上，或者是为了上学、宗教或工作活动。","p":"对。一位 25 岁或以上的持照驾驶人。"},"vi":{"q":"Ở Washington, điều nào sau đây cho phép người có bằng lái trung cấp lái xe từ 1 giờ sáng đến 5 giờ sáng?","o":["Lái xe đi dự tiệc","Lái xe với một người bạn 18 tuổi","Lái xe trên đường vắng","Lái xe với một người có bằng lái ít nhất 25 tuổi"],"h1":"Phải có một người lái lớn tuổi, có kinh nghiệm trong xe, hoặc chuyến đi là vì trường học, tôn giáo hay công việc.","h2":"Ở Washington, người có bằng lái trung cấp có thể lái xe từ 1 giờ sáng đến 5 giờ sáng khi có một người có bằng lái ít nhất 25 tuổi đi cùng, hoặc vì các hoạt động trường học, tôn giáo hay công việc.","p":"Đúng. Một người có bằng lái từ 25 tuổi trở lên."},"tl":{"q":"Sa Washington, alin dito ang nagpapahintulot sa may intermediate license na magmaneho mula 1 a.m. hanggang 5 a.m.?","o":["Pagmamaneho papunta sa party","Pagmamaneho kasama ang kaibigang 18 taong gulang","Pagmamaneho sa walang lamang kalsada","Pagmamaneho kasama ang lisensyadong driver na hindi bababa sa 25 taong gulang"],"h1":"Dapat may mas matanda at may karanasang driver sa kotse, o ang biyahe ay para sa paaralan, relihiyon o trabaho.","h2":"Sa Washington, ang may intermediate license ay puwedeng magmaneho mula 1 a.m. hanggang 5 a.m. kasama ang lisensyadong driver na hindi bababa sa 25 taong gulang, o para sa gawain sa paaralan, relihiyon o trabaho.","p":"Tama. Lisensyadong driver na 25 pataas."},"ar":{"q":"في Washington، أي من هذه يسمح لصاحب الرخصة المتوسطة أن يقود بين 1 صباحًا و5 صباحًا؟","o":["القيادة إلى حفلة","القيادة مع صديق عمره 18 سنة","القيادة في طريق فارغ","القيادة مع سائق له رخصة وعمره 25 سنة على الأقل"],"h1":"يجب أن يكون في السيارة سائق أكبر سنًا وله خبرة، أو تكون الرحلة للمدرسة أو الدين أو العمل.","h2":"في Washington يجوز لصاحب الرخصة المتوسطة أن يقود بين 1 صباحًا و5 صباحًا مع سائق له رخصة وعمره 25 سنة على الأقل، أو لأنشطة المدرسة أو الدين أو العمل.","p":"صحيح. سائق له رخصة وعمره 25 سنة أو أكثر."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-016","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, during the first six months of an intermediate license, which passengers under 20 may ride with the driver?","o":["Only immediate family members","Up to three friends","One friend","Anyone"],"h1":"Friends under 20 have to wait.","h2":"During the first six months, a Washington intermediate license holder may carry no passengers under 20 except immediate family members.","p":"Correct. Only immediate family."},"es":{"q":"En Washington, durante los primeros seis meses de la licencia intermedia, ¿qué pasajeros menores de 20 años pueden ir con el conductor?","o":["Solo familiares directos","Hasta tres amigos","Un amigo","Cualquier persona"],"h1":"Los amigos menores de 20 tienen que esperar.","h2":"Durante los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar pasajeros menores de 20 años, excepto familiares directos.","p":"Correcto. Solo familiares directos."},"zh":{"q":"在 Washington，拿到中级驾照的头六个月里，哪些 20 岁以下的乘客可以坐驾驶人的车？","o":["只有直系家庭成员","最多三个朋友","一个朋友","任何人"],"h1":"20 岁以下的朋友要等一等。","h2":"在头六个月里，Washington 的中级驾照持有人除了直系家庭成员以外，不可以载任何 20 岁以下的乘客。","p":"对。只有直系家庭成员。"},"vi":{"q":"Ở Washington, trong sáu tháng đầu có bằng lái trung cấp, những hành khách dưới 20 tuổi nào được đi cùng người lái?","o":["Chỉ người trong gia đình trực hệ","Tối đa ba người bạn","Một người bạn","Bất kỳ ai"],"h1":"Bạn bè dưới 20 tuổi phải chờ.","h2":"Trong sáu tháng đầu, người có bằng lái trung cấp ở Washington không được chở hành khách nào dưới 20 tuổi, trừ người trong gia đình trực hệ.","p":"Đúng. Chỉ gia đình trực hệ."},"tl":{"q":"Sa Washington, sa unang anim na buwan ng intermediate license, aling mga pasaherong wala pang 20 ang puwedeng sumakay kasama ng driver?","o":["Mga kasapi lamang ng malapit na pamilya","Hanggang tatlong kaibigan","Isang kaibigan","Kahit sino"],"h1":"Kailangang maghintay ang mga kaibigang wala pang 20.","h2":"Sa unang anim na buwan, ang may intermediate license sa Washington ay hindi puwedeng magsakay ng pasaherong wala pang 20, maliban sa mga kasapi ng malapit na pamilya.","p":"Tama. Malapit na pamilya lamang."},"ar":{"q":"في Washington، في أول ستة أشهر من الرخصة المتوسطة، أي ركاب تحت 20 سنة يمكنهم الركوب مع السائق؟","o":["أفراد العائلة المباشرة فقط","حتى ثلاثة أصدقاء","صديق واحد","أي شخص"],"h1":"الأصدقاء تحت 20 سنة يجب أن ينتظروا.","h2":"في أول ستة أشهر، لا يجوز لصاحب الرخصة المتوسطة في Washington أن ينقل أي ركاب تحت 20 سنة إلا أفراد العائلة المباشرة.","p":"صحيح. العائلة المباشرة فقط."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-017","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, after the first six months of an intermediate license, how many non-family passengers under 20 may the driver carry?","o":["None","One","Up to three","Up to five"],"h1":"The limit goes up after six months, but it is still a small number.","h2":"After the first six months, a Washington intermediate license holder may carry no more than three passengers under 20 who are not immediate family.","p":"Right. Up to three."},"es":{"q":"En Washington, después de los primeros seis meses de la licencia intermedia, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar el conductor?","o":["Ninguno","Uno","Hasta tres","Hasta cinco"],"h1":"El límite sube después de seis meses, pero sigue siendo pequeño.","h2":"Después de los primeros seis meses, el titular de una licencia intermedia en Washington no puede llevar más de tres pasajeros menores de 20 años que no sean familiares directos.","p":"Correcto. Hasta tres."},"zh":{"q":"在 Washington，拿到中级驾照六个月以后，驾驶人可以载多少个 20 岁以下、不是家人的乘客？","o":["一个也不行","一个","最多三个","最多五个"],"h1":"六个月以后人数限制会提高，但仍然是一个小数字。","h2":"头六个月以后，Washington 的中级驾照持有人最多可以载三个不是直系家庭成员的 20 岁以下乘客。","p":"对。最多三个。"},"vi":{"q":"Ở Washington, sau sáu tháng đầu có bằng lái trung cấp, người lái được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một người","Tối đa ba người","Tối đa năm người"],"h1":"Giới hạn tăng lên sau sáu tháng, nhưng vẫn là một số nhỏ.","h2":"Sau sáu tháng đầu, người có bằng lái trung cấp ở Washington được chở không quá ba hành khách dưới 20 tuổi không phải người trong gia đình trực hệ.","p":"Đúng. Tối đa ba người."},"tl":{"q":"Sa Washington, pagkatapos ng unang anim na buwan ng intermediate license, ilang pasaherong wala pang 20 at hindi kapamilya ang puwedeng isakay ng driver?","o":["Wala","Isa","Hanggang tatlo","Hanggang lima"],"h1":"Tumataas ang limitasyon pagkatapos ng anim na buwan, pero maliit na numero pa rin ito.","h2":"Pagkatapos ng unang anim na buwan, ang may intermediate license sa Washington ay puwedeng magsakay ng hindi hihigit sa tatlong pasaherong wala pang 20 na hindi malapit na kapamilya.","p":"Tama. Hanggang tatlo."},"ar":{"q":"في Washington، بعد أول ستة أشهر من الرخصة المتوسطة، كم راكبًا تحت 20 سنة من غير العائلة يمكن للسائق أن ينقل؟","o":["لا أحد","واحد","حتى ثلاثة","حتى خمسة"],"h1":"الحد يرتفع بعد ستة أشهر، لكنه ما زال عددًا صغيرًا.","h2":"بعد أول ستة أشهر، يجوز لصاحب الرخصة المتوسطة في Washington أن ينقل ثلاثة ركاب على الأكثر تحت 20 سنة ليسوا من العائلة المباشرة.","p":"صحيح. حتى ثلاثة."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-018","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, may a driver with an instruction permit or intermediate license use a phone hands-free?","o":["Yes, any time","No, only in an emergency","Yes, at red lights","Yes, for short calls"],"h1":"New drivers have a stricter rule than other drivers.","h2":"In Washington permit and intermediate license holders may not use a wireless device at all, even hands-free, except in an emergency.","p":"Correct. No phone except in an emergency."},"es":{"q":"En Washington, ¿puede un conductor con permiso de instrucción o licencia intermedia usar el teléfono con manos libres?","o":["Sí, en cualquier momento","No, solo en una emergencia","Sí, en los semáforos en rojo","Sí, para llamadas cortas"],"h1":"Los conductores nuevos tienen una regla más estricta que los demás.","h2":"En Washington quienes tienen permiso o licencia intermedia no pueden usar ningún dispositivo inalámbrico, ni siquiera con manos libres, excepto en una emergencia.","p":"Correcto. Nada de teléfono salvo en una emergencia."},"zh":{"q":"在 Washington，持有学习驾照或中级驾照的驾驶人可以用免提方式打电话吗？","o":["可以，任何时候都可以","不可以，只有紧急情况可以","可以，在红灯时可以","可以，打短电话可以"],"h1":"新驾驶人的规定比其他驾驶人更严格。","h2":"在 Washington，学习驾照和中级驾照持有人完全不可以使用无线设备，即使是免提也不行，紧急情况除外。","p":"对。除了紧急情况，不能用电话。"},"vi":{"q":"Ở Washington, người lái có giấy phép tập lái hoặc bằng lái trung cấp có được dùng điện thoại rảnh tay (hands-free) không?","o":["Có, bất cứ lúc nào","Không, chỉ khi khẩn cấp","Có, khi dừng đèn đỏ","Có, cho các cuộc gọi ngắn"],"h1":"Người mới lái có quy định nghiêm hơn những người lái khác.","h2":"Ở Washington, người có giấy phép tập lái và bằng lái trung cấp hoàn toàn không được dùng thiết bị không dây, kể cả rảnh tay, trừ khi khẩn cấp.","p":"Đúng. Không dùng điện thoại trừ khi khẩn cấp."},"tl":{"q":"Sa Washington, puwede bang gumamit ng phone nang hands-free ang driver na may instruction permit o intermediate license?","o":["Oo, kahit kailan","Hindi, sa emergency lamang","Oo, sa red light","Oo, para sa maiikling tawag"],"h1":"Mas mahigpit ang patakaran para sa mga bagong driver kaysa sa ibang driver.","h2":"Sa Washington, ang may permit at intermediate license ay hindi puwedeng gumamit ng wireless device kahit kailan, kahit hands-free, maliban sa emergency.","p":"Tama. Bawal ang phone maliban sa emergency."},"ar":{"q":"في Washington، هل يجوز للسائق الذي معه تصريح تعلّم أو رخصة متوسطة أن يستعمل الهاتف بدون يدين (hands-free)؟","o":["نعم، في أي وقت","لا، فقط في حالة طوارئ","نعم، عند الإشارة الحمراء","نعم، للمكالمات القصيرة"],"h1":"للسائقين الجدد قاعدة أشد من السائقين الآخرين.","h2":"في Washington لا يجوز لأصحاب التصريح والرخصة المتوسطة أن يستعملوا أي جهاز لاسلكي أبدًا، حتى بدون يدين، إلا في حالة طوارئ.","p":"صحيح. لا هاتف إلا في حالة طوارئ."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-019","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, may any driver hold a phone while stopped at a red light?","o":["Yes, while the light is red","Yes, if the engine is running","No, not even when stopped in traffic or at a light","Yes, to read a text"],"h1":"Being stopped in traffic still counts as driving.","h2":"Washington's distracted driving law says a driver may not hold a phone even when stopped in traffic or at a light.","p":"Right. Not even at a red light."},"es":{"q":"En Washington, ¿puede cualquier conductor sostener el teléfono mientras está detenido en un semáforo en rojo?","o":["Sí, mientras la luz está en rojo","Sí, si el motor está encendido","No, ni siquiera detenido en el tráfico o en un semáforo","Sí, para leer un mensaje"],"h1":"Estar detenido en el tráfico todavía cuenta como manejar.","h2":"La ley de manejo distraído de Washington dice que un conductor no puede sostener el teléfono ni siquiera detenido en el tráfico o en un semáforo.","p":"Correcto. Ni siquiera en un semáforo en rojo."},"zh":{"q":"在 Washington，任何驾驶人在红灯前停车时可以拿着手机吗？","o":["可以，在红灯时可以","可以，如果引擎还开着","不可以，即使在车流中停着或在红绿灯前停着也不可以","可以，用来看短信"],"h1":"在车流中停着仍然算是在开车。","h2":"Washington 的分心驾驶法规定，即使在车流中停着或在红绿灯前停着，驾驶人也不可以拿着手机。","p":"对。在红灯前也不可以。"},"vi":{"q":"Ở Washington, người lái nào cũng có được cầm điện thoại khi dừng đèn đỏ không?","o":["Có, khi đèn đang đỏ","Có, nếu máy xe đang chạy","Không, kể cả khi dừng trong dòng xe hay ở đèn giao thông","Có, để đọc tin nhắn"],"h1":"Dừng trong dòng xe vẫn được tính là đang lái xe.","h2":"Luật lái xe mất tập trung của Washington nói rằng người lái không được cầm điện thoại, kể cả khi dừng trong dòng xe hay ở đèn giao thông.","p":"Đúng. Kể cả ở đèn đỏ cũng không được."},"tl":{"q":"Sa Washington, puwede bang humawak ng phone ang kahit sinong driver habang nakahinto sa red light?","o":["Oo, habang pula ang ilaw","Oo, kung umaandar ang makina","Hindi, kahit nakahinto sa trapiko o sa ilaw","Oo, para magbasa ng text"],"h1":"Ang pagkakahinto sa trapiko ay itinuturing pa ring pagmamaneho.","h2":"Ayon sa distracted driving law ng Washington, hindi puwedeng humawak ng phone ang driver kahit nakahinto sa trapiko o sa ilaw.","p":"Tama. Kahit sa red light, bawal."},"ar":{"q":"في Washington، هل يجوز لأي سائق أن يمسك الهاتف وهو متوقف عند إشارة حمراء؟","o":["نعم، ما دامت الإشارة حمراء","نعم، إذا كان المحرك يعمل","لا، حتى عند التوقف في زحمة السير أو عند الإشارة","نعم، لقراءة رسالة"],"h1":"التوقف في زحمة السير ما زال يُعدّ قيادة.","h2":"قانون القيادة مع تشتّت الانتباه في Washington يقول إن السائق لا يجوز له أن يمسك الهاتف حتى عند التوقف في زحمة السير أو عند الإشارة.","p":"صحيح. ولا حتى عند الإشارة الحمراء."},"ref":{"doc":"WA","page":"§3.4"}},{"id":"wa-020","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, if you cannot move over a lane for a stopped emergency vehicle, how much must you slow down?","o":["5 mph below the limit","To 15 mph","Not at all","At least 10 mph below the posted limit"],"h1":"It is a round number of miles per hour below the limit.","h2":"In Washington, if you cannot safely move over one lane, you must slow to at least 10 mph below the posted speed limit.","p":"Correct. At least 10 mph slower."},"es":{"q":"En Washington, si no puede cambiarse de carril por un vehículo de emergencia detenido, ¿cuánto debe reducir la velocidad?","o":["5 mph menos que el límite","Hasta 15 mph","Nada","Por lo menos 10 mph menos que el límite indicado"],"h1":"Es un número redondo de millas por hora menos que el límite.","h2":"En Washington, si no puede cambiarse un carril con seguridad, debe bajar la velocidad por lo menos 10 mph por debajo del límite indicado.","p":"Correcto. Por lo menos 10 mph menos."},"zh":{"q":"在 Washington，如果你没办法为停着的紧急车辆让出一条车道，你必须减速多少？","o":["比限速低 5 mph","降到 15 mph","完全不用减速","比标示的限速至少低 10 mph"],"h1":"它是比限速低一个整数的 mph。","h2":"在 Washington，如果你没办法安全地让出一条车道，你必须把速度降到比标示的限速至少低 10 mph。","p":"对。至少慢 10 mph。"},"vi":{"q":"Ở Washington, nếu bạn không thể chuyển sang làn khác để tránh xe cấp cứu đang dừng, bạn phải giảm tốc độ bao nhiêu?","o":["Thấp hơn giới hạn 5 mph","Xuống 15 mph","Không cần giảm","Thấp hơn giới hạn tốc độ ghi trên biển ít nhất 10 mph"],"h1":"Đó là một số tròn mph thấp hơn giới hạn.","h2":"Ở Washington, nếu bạn không thể chuyển sang một làn khác một cách an toàn, bạn phải giảm tốc độ xuống thấp hơn giới hạn tốc độ ghi trên biển ít nhất 10 mph.","p":"Đúng. Chậm hơn ít nhất 10 mph."},"tl":{"q":"Sa Washington, kung hindi ka makalipat ng lane para sa nakahintong emergency vehicle, gaano mo dapat bagalan ang takbo?","o":["5 mph na mas mababa sa limit","Hanggang 15 mph","Hindi na kailangan","Hindi bababa sa 10 mph na mas mababa sa nakapaskil na limit"],"h1":"Isa itong buong numero ng mph na mas mababa sa limit.","h2":"Sa Washington, kung hindi ka ligtas na makalipat ng isang lane, dapat mong bagalan ang takbo nang hindi bababa sa 10 mph na mas mababa sa nakapaskil na speed limit.","p":"Tama. Hindi bababa sa 10 mph na mas mabagal."},"ar":{"q":"في Washington، إذا لم تستطع الانتقال إلى مسار آخر بعيدًا عن سيارة طوارئ متوقفة، كم يجب أن تخفّف سرعتك؟","o":["5 mph أقل من الحد","إلى 15 mph","لا تخفّف أبدًا","10 mph على الأقل أقل من الحد المكتوب على اللافتة"],"h1":"هو عدد كامل من mph أقل من الحد.","h2":"في Washington، إذا لم تستطع الانتقال مسارًا واحدًا بأمان، يجب أن تخفّف سرعتك إلى 10 mph على الأقل أقل من حد السرعة المكتوب على اللافتة.","p":"صحيح. أبطأ بـ 10 mph على الأقل."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-021","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, how far before and after a stopped emergency vehicle does the Move Over zone reach?","o":["50 feet","200 feet","500 feet","One mile"],"h1":"It is a few car lengths more than 100 feet.","h2":"In Washington the Move Over zone covers 200 feet before and 200 feet after the stopped emergency or work vehicle.","p":"Right. 200 feet each way."},"es":{"q":"En Washington, ¿hasta qué distancia antes y después de un vehículo de emergencia detenido llega la zona de Move Over?","o":["50 pies","200 pies","500 pies","Una milla"],"h1":"Es unos cuantos carros más que 100 pies.","h2":"En Washington la zona de Move Over cubre 200 pies antes y 200 pies después del vehículo de emergencia o de trabajo detenido.","p":"Correcto. 200 pies en cada dirección."},"zh":{"q":"在 Washington，让道区（Move Over zone）在停着的紧急车辆前后各有多远？","o":["50 英尺","200 英尺","500 英尺","1 英里"],"h1":"它比 100 英尺多几个车身的长度。","h2":"在 Washington，让道区包括停着的紧急车辆或工作车辆前面 200 英尺和后面 200 英尺。","p":"对。前后各 200 英尺。"},"vi":{"q":"Ở Washington, khu vực nhường đường (Move Over zone) kéo dài bao xa phía trước và phía sau xe cấp cứu đang dừng?","o":["50 feet","200 feet","500 feet","Một dặm"],"h1":"Nó dài hơn 100 feet vài chiều dài xe.","h2":"Ở Washington, khu vực nhường đường bao gồm 200 feet phía trước và 200 feet phía sau xe cấp cứu hoặc xe công tác đang dừng.","p":"Đúng. 200 feet mỗi bên."},"tl":{"q":"Sa Washington, gaano kalayo bago at pagkatapos ng nakahintong emergency vehicle umaabot ang Move Over zone?","o":["50 feet","200 feet","500 feet","Isang milya"],"h1":"Ilang haba ng kotse ito na mas mahaba sa 100 feet.","h2":"Sa Washington, ang Move Over zone ay sumasaklaw sa 200 feet bago at 200 feet pagkatapos ng nakahintong emergency o work vehicle.","p":"Tama. 200 feet sa bawat panig."},"ar":{"q":"في Washington، إلى أي مسافة قبل سيارة الطوارئ المتوقفة وبعدها تمتد منطقة الابتعاد (Move Over zone)؟","o":["50 قدمًا","200 قدم","500 قدم","ميل واحد"],"h1":"هي أكثر من 100 قدم بطول بضع سيارات.","h2":"في Washington تشمل منطقة الابتعاد 200 قدم قبل سيارة الطوارئ أو سيارة العمل المتوقفة و200 قدم بعدها.","p":"صحيح. 200 قدم من كل جهة."},"ref":{"doc":"WA","page":null}},{"id":"wa-022","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, at what blood alcohol level is a driver under 21 breaking the law?","o":["0.02 or more","0.05 or more","0.08 or more","0.10 or more"],"h1":"It is much lower than the adult limit of 0.08.","h2":"In Washington a driver under 21 breaks the law with a blood alcohol level of 0.02 or more.","p":"Correct. The limit under 21 is 0.02."},"es":{"q":"En Washington, ¿con qué nivel de alcohol en la sangre un conductor menor de 21 años infringe la ley?","o":["0.02 o más","0.05 o más","0.08 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos, que es 0.08.","h2":"En Washington un conductor menor de 21 años infringe la ley con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. El límite para menores de 21 es 0.02."},"zh":{"q":"在 Washington，21 岁以下的驾驶人血液酒精浓度达到多少就算违法？","o":["0.02 或以上","0.05 或以上","0.08 或以上","0.10 或以上"],"h1":"它比成年人的上限 0.08 低很多。","h2":"在 Washington，21 岁以下的驾驶人血液酒精浓度达到 0.02 或以上就是违法。","p":"对。21 岁以下的上限是 0.02。"},"vi":{"q":"Ở Washington, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu ở mức nào?","o":["0.02 trở lên","0.05 trở lên","0.08 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn 0.08 của người lớn.","h2":"Ở Washington, người lái dưới 21 tuổi vi phạm luật khi nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Giới hạn cho người dưới 21 tuổi là 0.02."},"tl":{"q":"Sa Washington, sa anong blood alcohol level lumalabag sa batas ang driver na wala pang 21?","o":["0.02 o higit pa","0.05 o higit pa","0.08 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa 0.08 na limit para sa adult.","h2":"Sa Washington, ang driver na wala pang 21 ay lumalabag sa batas kapag ang blood alcohol level niya ay 0.02 o higit pa.","p":"Tama. Ang limit para sa wala pang 21 ay 0.02."},"ar":{"q":"في Washington، عند أي نسبة كحول في الدم يخالف السائق تحت 21 سنة القانون؟","o":["0.02 أو أكثر","0.05 أو أكثر","0.08 أو أكثر","0.10 أو أكثر"],"h1":"هي أقل بكثير من حد البالغين وهو 0.08.","h2":"في Washington يخالف السائق تحت 21 سنة القانون إذا كانت نسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. الحد تحت 21 سنة هو 0.02."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-023","scope":"WA","cat":"signals","sign":null,"c":2,"en":{"q":"In Washington, after a full stop at a red light, when may you turn left on red if no sign forbids it?","o":["Never","Only from a one-way street onto a two-way street","From a one-way or two-way street onto a one-way street going left","From any street onto any street"],"h1":"The street you turn into must carry traffic in only one direction, the way you are turning.","h2":"In Washington, after stopping and yielding, you may turn left on red from a one-way or two-way street onto a one-way street that carries traffic to the left, unless a sign forbids it.","p":"Right. Only onto a one-way street."},"es":{"q":"En Washington, después de detenerse por completo en un semáforo en rojo, ¿cuándo puede dar vuelta a la izquierda en rojo si ningún letrero lo prohíbe?","o":["Nunca","Solo de una calle de un sentido a una calle de doble sentido","De una calle de un sentido o de doble sentido a una calle de un sentido que va hacia la izquierda","De cualquier calle a cualquier calle"],"h1":"La calle a la que entra debe tener tráfico en un solo sentido, hacia donde usted da la vuelta.","h2":"En Washington, después de detenerse y ceder el paso, usted puede dar vuelta a la izquierda en rojo de una calle de un sentido o de doble sentido a una calle de un sentido con tráfico hacia la izquierda, a menos que un letrero lo prohíba.","p":"Correcto. Solo hacia una calle de un sentido."},"zh":{"q":"在 Washington，在红灯前完全停车以后，如果没有标志禁止，什么时候可以红灯左转？","o":["永远不可以","只有从单行道转进双向道","从单行道或双向道转进向左行驶的单行道","从任何街道转进任何街道"],"h1":"你转进去的街道必须只有一个行驶方向，就是你转弯的方向。","h2":"在 Washington，停车并让行以后，你可以在红灯时从单行道或双向道左转进入向左行驶的单行道，除非有标志禁止。","p":"对。只能转进单行道。"},"vi":{"q":"Ở Washington, sau khi dừng hẳn ở đèn đỏ, khi nào bạn được rẽ trái lúc đèn đỏ nếu không có biển cấm?","o":["Không bao giờ","Chỉ từ đường một chiều vào đường hai chiều","Từ đường một chiều hoặc hai chiều vào đường một chiều chạy về bên trái","Từ bất kỳ đường nào vào bất kỳ đường nào"],"h1":"Con đường bạn rẽ vào phải chỉ có xe chạy một chiều, theo hướng bạn rẽ.","h2":"Ở Washington, sau khi dừng lại và nhường đường, bạn được rẽ trái lúc đèn đỏ từ đường một chiều hoặc hai chiều vào đường một chiều có xe chạy về bên trái, trừ khi có biển cấm.","p":"Đúng. Chỉ rẽ vào đường một chiều."},"tl":{"q":"Sa Washington, pagkatapos ng full stop sa red light, kailan ka puwedeng kumaliwa sa red kung walang karatulang nagbabawal?","o":["Hindi kailanman","Mula sa one-way street papunta sa two-way street lamang","Mula sa one-way o two-way street papunta sa one-way street na papakaliwa ang daloy","Mula sa kahit anong kalye papunta sa kahit anong kalye"],"h1":"Ang kalyeng papasukan mo ay dapat may trapiko sa iisang direksyon lamang, ang direksyon ng liko mo.","h2":"Sa Washington, pagkatapos huminto at magbigay-daan, puwede kang kumaliwa sa red mula sa one-way o two-way street papunta sa one-way street na papakaliwa ang daloy ng trapiko, maliban kung may karatulang nagbabawal.","p":"Tama. Papunta lamang sa one-way street."},"ar":{"q":"في Washington، بعد التوقف الكامل عند إشارة حمراء، متى يجوز لك الانعطاف يسارًا والإشارة حمراء إذا لم تمنعه لافتة؟","o":["أبدًا","فقط من شارع باتجاه واحد إلى شارع باتجاهين","من شارع باتجاه واحد أو باتجاهين إلى شارع باتجاه واحد يسير نحو اليسار","من أي شارع إلى أي شارع"],"h1":"الشارع الذي تنعطف إليه يجب أن يكون السير فيه باتجاه واحد فقط، وهو اتجاه انعطافك.","h2":"في Washington، بعد التوقف وإعطاء الأولوية، يجوز لك الانعطاف يسارًا والإشارة حمراء من شارع باتجاه واحد أو باتجاهين إلى شارع باتجاه واحد يسير نحو اليسار، إلا إذا منعته لافتة.","p":"صحيح. فقط إلى شارع باتجاه واحد."},"ref":{"doc":"WA","page":"§4.11"}},{"id":"wa-024","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what is the minimum liability insurance you must have?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Injury to one person is covered for twenty-five thousand dollars.","h2":"In Washington, the minimum is $25,000 for one person hurt or killed, $50,000 for two or more people, and $10,000 for damage to property.","p":"Right. Washington requires at least $25,000, $50,000 and $10,000 of coverage."},"es":{"q":"En Washington, ¿cuál es el seguro de responsabilidad civil mínimo que debe tener?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Las lesiones de una persona están cubiertas por veinticinco mil dólares.","h2":"En Washington, el mínimo es $25,000 por una persona herida o muerta, $50,000 por dos o más personas y $10,000 por daños a la propiedad.","p":"Correcto. Washington exige al menos $25,000, $50,000 y $10,000 de cobertura."},"zh":{"q":"在 Washington，你必须有的最低责任保险是多少？","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"一个人受伤的保额是两万五千美元。","h2":"在 Washington，最低保额是：一个人受伤或死亡 $25,000，两个人或更多人 $50,000，财产损失 $10,000。","p":"对。Washington 要求至少 $25,000、$50,000 和 $10,000 的保额。"},"vi":{"q":"Ở Washington, bảo hiểm trách nhiệm tối thiểu bạn phải có là bao nhiêu?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Thương tích của một người được bảo hiểm hai mươi lăm nghìn đô la.","h2":"Ở Washington, mức tối thiểu là $25,000 cho một người bị thương hoặc tử vong, $50,000 cho hai người trở lên, và $10,000 cho thiệt hại tài sản.","p":"Đúng. Washington yêu cầu bảo hiểm ít nhất $25,000, $50,000 và $10,000."},"tl":{"q":"Sa Washington, ano ang pinakamababang liability insurance na dapat mayroon ka?","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"Ang pinsala sa isang tao ay sakop ng dalawampu't limang libong dolyar.","h2":"Sa Washington, ang pinakamababa ay $25,000 para sa isang taong nasaktan o namatay, $50,000 para sa dalawa o higit pang tao, at $10,000 para sa sira sa ari-arian.","p":"Tama. Hinihingi ng Washington ang hindi bababa sa $25,000, $50,000 at $10,000 na coverage."},"ar":{"q":"في Washington، ما الحد الأدنى من تأمين المسؤولية الذي يجب أن يكون لديك؟","o":["$15,000 / $30,000 / $5,000","$50,000 / $100,000 / $25,000","$25,000 / $50,000 / $10,000","$10,000 / $20,000 / $10,000"],"h1":"إصابة شخص واحد مغطاة بخمسة وعشرين ألف دولار.","h2":"في Washington، الحد الأدنى هو $25,000 لشخص واحد مصاب أو متوفى، و$50,000 لشخصين أو أكثر، و$10,000 لأضرار الممتلكات.","p":"صحيح. تشترط Washington تغطية لا تقل عن $25,000 و$50,000 و$10,000."},"ref":{"doc":"WA","page":"§2.3"}},{"id":"wa-025","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, a driver 21 or older is considered under the influence of cannabis at what level of active THC in the blood?","o":["5 nanograms per milliliter or more","Any amount above zero","20 nanograms per milliliter or more","There is no THC limit"],"h1":"The number is the same as the fingers on one hand.","h2":"In Washington, a driver 21 or older with 5 nanograms or more of active THC per milliliter of blood is considered to be driving under the influence.","p":"Right. For adults, the THC limit is 5 nanograms per milliliter."},"es":{"q":"En Washington, ¿con qué nivel de THC activo en la sangre se considera que un conductor de 21 años o más maneja bajo la influencia del cannabis?","o":["5 nanogramos por mililitro o más","Cualquier cantidad mayor que cero","20 nanogramos por mililitro o más","No hay límite de THC"],"h1":"El número es igual a los dedos de una mano.","h2":"En Washington, un conductor de 21 años o más con 5 nanogramos o más de THC activo por mililitro de sangre se considera que maneja bajo la influencia.","p":"Correcto. Para los adultos, el límite de THC es de 5 nanogramos por mililitro."},"zh":{"q":"在 Washington，21 岁或以上的司机血液中活性 THC 达到多少时，被认为受大麻影响驾驶？","o":["每毫升 5 纳克或更多","任何大于零的量","每毫升 20 纳克或更多","THC 没有限制"],"h1":"这个数字和一只手的手指数一样。","h2":"在 Washington，21 岁或以上的司机，如果每毫升血液中有 5 纳克或更多的活性 THC，就被认为是受影响驾驶。","p":"对。成年人的 THC 限制是每毫升 5 纳克。"},"vi":{"q":"Ở Washington, tài xế từ 21 tuổi trở lên bị xem là lái xe dưới ảnh hưởng của cần sa khi lượng THC hoạt tính trong máu ở mức nào?","o":["5 nanogram mỗi mililít trở lên","Bất kỳ lượng nào lớn hơn không","20 nanogram mỗi mililít trở lên","Không có giới hạn THC"],"h1":"Con số này bằng số ngón tay trên một bàn tay.","h2":"Ở Washington, tài xế từ 21 tuổi trở lên có 5 nanogram THC hoạt tính trở lên trong mỗi mililít máu bị xem là lái xe dưới ảnh hưởng.","p":"Đúng. Với người lớn, giới hạn THC là 5 nanogram mỗi mililít."},"tl":{"q":"Sa Washington, ang driver na 21 taong gulang pataas ay itinuturing na under the influence ng cannabis sa anong antas ng active THC sa dugo?","o":["5 nanograms bawat milliliter o higit pa","Kahit anong dami na higit sa zero","20 nanograms bawat milliliter o higit pa","Walang limit sa THC"],"h1":"Ang numero ay kapareho ng bilang ng daliri sa isang kamay.","h2":"Sa Washington, ang driver na 21 taong gulang pataas na may 5 nanograms o higit pa ng active THC bawat milliliter ng dugo ay itinuturing na nagmamaneho nang under the influence.","p":"Tama. Para sa mga adult, ang limit ng THC ay 5 nanograms bawat milliliter."},"ar":{"q":"في Washington، عند أي مستوى من THC النشط في الدم يُعتبر السائق الذي عمره 21 عامًا أو أكثر تحت تأثير القنب؟","o":["5 نانوغرامات لكل مليلتر أو أكثر","أي كمية أكبر من صفر","20 نانوغرامًا لكل مليلتر أو أكثر","لا يوجد حد لـ THC"],"h1":"الرقم يساوي عدد أصابع اليد الواحدة.","h2":"في Washington، السائق الذي عمره 21 عامًا أو أكثر ولديه 5 نانوغرامات أو أكثر من THC النشط لكل مليلتر من الدم يُعتبر أنه يقود تحت التأثير.","p":"صحيح. بالنسبة للبالغين، حد THC هو 5 نانوغرامات لكل مليلتر."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-026","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, until what age must a child ride in a rear-facing car seat?","o":["Until age 1","Until age 2","Until age 4","Until age 6"],"h1":"It is later than a baby's first birthday.","h2":"In Washington, children must ride in a rear-facing car seat until they are 2 years old.","p":"Right. Children ride rear-facing until age 2."},"es":{"q":"En Washington, ¿hasta qué edad debe un niño viajar en un asiento de seguridad orientado hacia atrás?","o":["Hasta 1 año","Hasta 2 años","Hasta 4 años","Hasta 6 años"],"h1":"Es después del primer cumpleaños del bebé.","h2":"En Washington, los niños deben viajar en un asiento de seguridad orientado hacia atrás hasta que cumplan 2 años.","p":"Correcto. Los niños viajan mirando hacia atrás hasta los 2 años."},"zh":{"q":"在 Washington，孩子必须坐后向安全座椅到几岁？","o":["到 1 岁","到 2 岁","到 4 岁","到 6 岁"],"h1":"比宝宝的第一个生日更晚。","h2":"在 Washington，孩子必须坐后向安全座椅，直到满 2 岁。","p":"对。孩子坐后向座椅到 2 岁。"},"vi":{"q":"Ở Washington, trẻ em phải ngồi ghế an toàn quay mặt về phía sau cho đến bao nhiêu tuổi?","o":["Đến 1 tuổi","Đến 2 tuổi","Đến 4 tuổi","Đến 6 tuổi"],"h1":"Muộn hơn sinh nhật đầu tiên của em bé.","h2":"Ở Washington, trẻ em phải ngồi ghế an toàn quay mặt về phía sau cho đến khi được 2 tuổi.","p":"Đúng. Trẻ em ngồi quay mặt về phía sau đến 2 tuổi."},"tl":{"q":"Sa Washington, hanggang anong edad dapat nakaupo ang bata sa rear-facing car seat?","o":["Hanggang edad 1","Hanggang edad 2","Hanggang edad 4","Hanggang edad 6"],"h1":"Mas huli ito kaysa sa unang kaarawan ng sanggol.","h2":"Sa Washington, ang mga bata ay dapat nakaupo sa rear-facing car seat hanggang sila ay 2 taong gulang.","p":"Tama. Nakaharap sa likod ang mga bata hanggang edad 2."},"ar":{"q":"في Washington، حتى أي عمر يجب أن يجلس الطفل في مقعد سيارة مواجه للخلف؟","o":["حتى عمر سنة واحدة (1)","حتى عمر سنتين (2)","حتى عمر 4 سنوات","حتى عمر 6 سنوات"],"h1":"إنه بعد عيد الميلاد الأول للطفل.","h2":"في Washington، يجب أن يجلس الأطفال في مقعد سيارة مواجه للخلف حتى يبلغوا عمر سنتين (2).","p":"صحيح. يجلس الأطفال مواجهين للخلف حتى عمر سنتين (2)."},"ref":{"doc":"WA","page":"§2.6"}},{"id":"wa-027","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, if no police officer files a report after your crash, within how many days must you file a collision report?","o":["1 day","10 days","30 days","4 days"],"h1":"It is less than one week.","h2":"In Washington, if a police officer does not file a report, you must file a collision report within 4 days of the crash.","p":"Right. You have 4 days to file the collision report."},"es":{"q":"En Washington, si ningún policía hace un informe después de su choque, ¿en cuántos días debe usted presentar un informe de colisión?","o":["1 día","10 días","30 días","4 días"],"h1":"Es menos de una semana.","h2":"En Washington, si un policía no hace el informe, usted debe presentar un informe de colisión dentro de los 4 días después del choque.","p":"Correcto. Tiene 4 días para presentar el informe de colisión."},"zh":{"q":"在 Washington，如果车祸后没有警察写报告，你必须在几天内提交事故报告？","o":["1 天","10 天","30 天","4 天"],"h1":"不到一个星期。","h2":"在 Washington，如果警察没有写报告，你必须在车祸后 4 天内提交事故报告。","p":"对。你有 4 天时间提交事故报告。"},"vi":{"q":"Ở Washington, nếu không có cảnh sát làm biên bản sau vụ tai nạn của bạn, bạn phải nộp báo cáo va chạm trong vòng bao nhiêu ngày?","o":["1 ngày","10 ngày","30 ngày","4 ngày"],"h1":"Ít hơn một tuần.","h2":"Ở Washington, nếu cảnh sát không làm biên bản, bạn phải nộp báo cáo va chạm trong vòng 4 ngày sau vụ tai nạn.","p":"Đúng. Bạn có 4 ngày để nộp báo cáo va chạm."},"tl":{"q":"Sa Washington, kung walang pulis na gumawa ng report pagkatapos ng banggaan mo, sa loob ng ilang araw dapat kang mag-file ng collision report?","o":["1 araw","10 araw","30 araw","4 na araw"],"h1":"Mas maikli ito sa isang linggo.","h2":"Sa Washington, kung walang pulis na gumawa ng report, dapat kang mag-file ng collision report sa loob ng 4 na araw pagkatapos ng banggaan.","p":"Tama. May 4 na araw ka para mag-file ng collision report."},"ar":{"q":"في Washington، إذا لم يكتب أي شرطي تقريرًا بعد حادثك، خلال كم يومًا يجب أن تقدم تقرير حادث؟","o":["يوم واحد (1)","10 أيام","30 يومًا","4 أيام"],"h1":"إنها أقل من أسبوع.","h2":"في Washington، إذا لم يكتب شرطي التقرير، يجب أن تقدم تقرير حادث خلال 4 أيام من الحادث.","p":"صحيح. لديك 4 أيام لتقديم تقرير الحادث."},"ref":{"doc":"WA","page":"§5.9"}},{"id":"wa-028","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, how early can you renew your driver license before it expires?","o":["Up to 30 days early","Up to 90 days early","Up to one year early","Only after it expires"],"h1":"You can renew quite a while before the date on your card.","h2":"In Washington, you can renew your driver license up to one year before it expires.","p":"Right. You can renew up to one year early."},"es":{"q":"En Washington, ¿con cuánta anticipación puede renovar su licencia de conducir antes de que venza?","o":["Hasta 30 días antes","Hasta 90 días antes","Hasta un año antes","Solo después de que venza"],"h1":"Puede renovarla bastante tiempo antes de la fecha de su tarjeta.","h2":"En Washington, usted puede renovar su licencia de conducir hasta un año antes de que venza.","p":"Correcto. Puede renovarla hasta un año antes."},"zh":{"q":"在 Washington，驾照到期前多久可以更新？","o":["最多提前 30 天","最多提前 90 天","最多提前一年","只能在到期后"],"h1":"你可以在卡上日期之前很久就更新。","h2":"在 Washington，你可以在驾照到期前最多一年更新驾照。","p":"对。你最多可以提前一年更新。"},"vi":{"q":"Ở Washington, bạn có thể gia hạn bằng lái sớm bao lâu trước khi bằng hết hạn?","o":["Sớm tối đa 30 ngày","Sớm tối đa 90 ngày","Sớm tối đa một năm","Chỉ sau khi hết hạn"],"h1":"Bạn có thể gia hạn khá lâu trước ngày ghi trên thẻ.","h2":"Ở Washington, bạn có thể gia hạn bằng lái tối đa một năm trước khi bằng hết hạn.","p":"Đúng. Bạn có thể gia hạn sớm tối đa một năm."},"tl":{"q":"Sa Washington, gaano kaaga mo puwedeng i-renew ang driver license mo bago ito mag-expire?","o":["Hanggang 30 araw na mas maaga","Hanggang 90 araw na mas maaga","Hanggang isang taon na mas maaga","Pagkatapos lang itong mag-expire"],"h1":"Puwede kang mag-renew nang matagal bago ang petsa sa card mo.","h2":"Sa Washington, puwede mong i-renew ang driver license mo hanggang isang taon bago ito mag-expire.","p":"Tama. Puwede kang mag-renew hanggang isang taon na mas maaga."},"ar":{"q":"في Washington، كم من الوقت قبل انتهاء رخصة القيادة يمكنك تجديدها؟","o":["حتى 30 يومًا قبل الانتهاء","حتى 90 يومًا قبل الانتهاء","حتى سنة واحدة قبل الانتهاء","فقط بعد انتهائها"],"h1":"يمكنك التجديد قبل التاريخ المكتوب على بطاقتك بوقت طويل.","h2":"في Washington، يمكنك تجديد رخصة القيادة حتى سنة واحدة قبل انتهائها.","p":"صحيح. يمكنك التجديد حتى سنة واحدة مبكرًا."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-029","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, you are using high beams. How close can an oncoming vehicle get before you must switch to low beams?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"It is more than one and a half football fields.","h2":"In Washington, you must switch to low beams when you are within 500 feet of an oncoming vehicle.","p":"Right. Dim your lights within 500 feet of an oncoming vehicle."},"es":{"q":"En Washington, usted tiene las luces altas encendidas. ¿A qué distancia puede acercarse un vehículo que viene de frente antes de que usted cambie a luces bajas?","o":["500 pies","100 pies","1,000 pies","50 pies"],"h1":"Es más que una cancha y media de fútbol americano.","h2":"En Washington, usted debe cambiar a luces bajas cuando está a 500 pies o menos de un vehículo que viene de frente.","p":"Correcto. Baje las luces a 500 pies de un vehículo que viene de frente."},"zh":{"q":"在 Washington，你正在使用远光灯。对面来车离你多近时，你必须换成近光灯？","o":["500 英尺","100 英尺","1,000 英尺","50 英尺"],"h1":"这比一个半足球场还长。","h2":"在 Washington，当你离对面来车 500 英尺以内时，你必须换成近光灯。","p":"对。离对面来车 500 英尺以内时要把灯调暗。"},"vi":{"q":"Ở Washington, bạn đang bật đèn pha (đèn chiếu xa). Xe chạy ngược chiều đến gần bao nhiêu thì bạn phải chuyển sang đèn cos (đèn chiếu gần)?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"Nó dài hơn một sân bóng bầu dục rưỡi.","h2":"Ở Washington, bạn phải chuyển sang đèn cos khi bạn ở trong vòng 500 feet của xe chạy ngược chiều.","p":"Đúng. Hãy giảm đèn khi xe ngược chiều ở trong vòng 500 feet."},"tl":{"q":"Sa Washington, naka-high beam ka. Gaano kalapit ang paparating na sasakyan bago ka dapat lumipat sa low beam?","o":["500 feet","100 feet","1,000 feet","50 feet"],"h1":"Mas mahaba ito sa isa't kalahating football field.","h2":"Sa Washington, dapat kang lumipat sa low beam kapag nasa loob ka ng 500 feet ng paparating na sasakyan.","p":"Tama. Hinaan ang ilaw mo kapag nasa loob ng 500 feet ang paparating na sasakyan."},"ar":{"q":"في Washington، أنت تستخدم الأضواء العالية. كم يمكن أن تقترب سيارة قادمة من الاتجاه المقابل قبل أن يجب عليك التحويل إلى الأضواء المنخفضة؟","o":["500 قدم","100 قدم","1,000 قدم","50 قدمًا"],"h1":"هي أكثر من طول ملعب كرة قدم ونصف.","h2":"في Washington، يجب أن تحول إلى الأضواء المنخفضة عندما تكون على بعد 500 قدم أو أقل من سيارة قادمة من الاتجاه المقابل.","p":"صحيح. خفّض أضواءك على بعد 500 قدم من السيارة القادمة."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-030","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, when you pass a bicyclist, how much space must you leave between the bicyclist and your vehicle?","o":["At least 1 foot","At least 2 feet","At least 5 feet","At least 3 feet"],"h1":"Measure from the widest part of your vehicle, such as the mirror.","h2":"In Washington, you must leave at least 3 feet between the bicyclist and the widest part of your vehicle when you pass.","p":"Right. Leave at least 3 feet when you pass a bicyclist."},"es":{"q":"En Washington, cuando usted rebasa a un ciclista, ¿cuánto espacio debe dejar entre el ciclista y su vehículo?","o":["Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 5 pies","Por lo menos 3 pies"],"h1":"Mida desde la parte más ancha de su vehículo, como el espejo.","h2":"En Washington, usted debe dejar por lo menos 3 pies entre el ciclista y la parte más ancha de su vehículo cuando lo rebasa.","p":"Correcto. Deje por lo menos 3 pies al rebasar a un ciclista."},"zh":{"q":"在 Washington，当你超过骑自行车的人时，你必须在自行车和你的车之间留出多少空间？","o":["至少 1 英尺","至少 2 英尺","至少 5 英尺","至少 3 英尺"],"h1":"从你的车最宽的部分量起，比如后视镜。","h2":"在 Washington，超过骑自行车的人时，你必须在骑车人和你的车最宽的部分之间留出至少 3 英尺。","p":"对。超过骑自行车的人时，至少留出 3 英尺。"},"vi":{"q":"Ở Washington, khi bạn vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng cách giữa người đi xe đạp và xe của bạn?","o":["Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 5 feet","Ít nhất 3 feet"],"h1":"Đo từ phần rộng nhất của xe bạn, ví dụ như gương chiếu hậu.","h2":"Ở Washington, khi vượt, bạn phải chừa ít nhất 3 feet giữa người đi xe đạp và phần rộng nhất của xe bạn.","p":"Đúng. Hãy chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Washington, kapag nag-overtake ka sa nagbibisikleta, gaano kalaking espasyo ang dapat mong iwan sa pagitan ng nagbibisikleta at ng sasakyan mo?","o":["Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 5 feet","Hindi bababa sa 3 feet"],"h1":"Sukatin mula sa pinakamalapad na bahagi ng sasakyan mo, gaya ng salamin.","h2":"Sa Washington, kapag nag-overtake ka, dapat kang mag-iwan ng hindi bababa sa 3 feet sa pagitan ng nagbibisikleta at ng pinakamalapad na bahagi ng sasakyan mo.","p":"Tama. Mag-iwan ng hindi bababa sa 3 feet kapag nag-overtake ka sa nagbibisikleta."},"ar":{"q":"في Washington، عندما تتجاوز راكب دراجة، ما المسافة التي يجب أن تتركها بين راكب الدراجة وسيارتك؟","o":["قدم واحدة (1) على الأقل","قدمان (2) على الأقل","5 أقدام على الأقل","3 أقدام على الأقل"],"h1":"قِس من أعرض جزء في سيارتك، مثل المرآة.","h2":"في Washington، عندما تتجاوز يجب أن تترك 3 أقدام على الأقل بين راكب الدراجة وأعرض جزء في سيارتك.","p":"صحيح. اترك 3 أقدام على الأقل عندما تتجاوز راكب دراجة."},"ref":{"doc":"WA","page":"§4.6"}},{"id":"wa-031","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you may not park within how many feet of a railroad crossing?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"It is more than the distance for a fire hydrant.","h2":"In Washington, you may not park within 50 feet of a railroad crossing.","p":"Right. Keep at least 50 feet from a railroad crossing when you park."},"es":{"q":"En Washington, ¿a cuántos pies de un cruce de ferrocarril no puede estacionarse?","o":["15 pies","50 pies","100 pies","5 pies"],"h1":"Es más que la distancia de un hidrante.","h2":"En Washington, usted no puede estacionarse a menos de 50 pies de un cruce de ferrocarril.","p":"Correcto. Al estacionarse, quédese por lo menos a 50 pies de un cruce de ferrocarril."},"zh":{"q":"在 Washington，你不可以在铁路道口多少英尺以内停车？","o":["15 英尺","50 英尺","100 英尺","5 英尺"],"h1":"这比消防栓的距离还远。","h2":"在 Washington，你不可以在铁路道口 50 英尺以内停车。","p":"对。停车时离铁路道口至少 50 英尺。"},"vi":{"q":"Ở Washington, bạn không được đậu xe trong vòng bao nhiêu feet tính từ chỗ giao nhau với đường sắt?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"Nó xa hơn khoảng cách với trụ cứu hỏa.","h2":"Ở Washington, bạn không được đậu xe trong vòng 50 feet tính từ chỗ giao nhau với đường sắt.","p":"Đúng. Khi đậu xe, hãy cách chỗ giao nhau với đường sắt ít nhất 50 feet."},"tl":{"q":"Sa Washington, hindi ka puwedeng mag-park sa loob ng ilang feet mula sa railroad crossing?","o":["15 feet","50 feet","100 feet","5 feet"],"h1":"Mas malayo ito sa distansya para sa fire hydrant.","h2":"Sa Washington, hindi ka puwedeng mag-park sa loob ng 50 feet mula sa railroad crossing.","p":"Tama. Lumayo nang hindi bababa sa 50 feet mula sa railroad crossing kapag nagpa-park ka."},"ar":{"q":"في Washington، لا يجوز لك الوقوف (الركن) على بعد كم قدمًا من تقاطع السكة الحديدية؟","o":["15 قدمًا","50 قدمًا","100 قدم","5 أقدام"],"h1":"هي أكثر من المسافة المطلوبة عن صنبور إطفاء الحريق.","h2":"في Washington، لا يجوز لك الوقوف على بعد أقل من 50 قدمًا من تقاطع السكة الحديدية.","p":"صحيح. ابتعد 50 قدمًا على الأقل عن تقاطع السكة الحديدية عندما تقف."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-032","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you are 18 or older, you have a license from another state, and you just moved here. How soon must you get a Washington driver license?","o":["Within 30 days","Within 90 days","Within 10 days","Within 1 year"],"h1":"It is about one month.","h2":"In Washington, a new resident 18 or older with a license from another state has 30 days to get a Washington driver license.","p":"Right. New residents have 30 days to get a Washington license."},"es":{"q":"En Washington, usted tiene 18 años o más, tiene licencia de otro estado y acaba de mudarse aquí. ¿En cuánto tiempo debe obtener una licencia de conducir de Washington?","o":["Dentro de 30 días","Dentro de 90 días","Dentro de 10 días","Dentro de 1 año"],"h1":"Es más o menos un mes.","h2":"En Washington, un nuevo residente de 18 años o más con licencia de otro estado tiene 30 días para obtener una licencia de conducir de Washington.","p":"Correcto. Los nuevos residentes tienen 30 días para obtener una licencia de Washington."},"zh":{"q":"在 Washington，你 18 岁或以上，有别的州的驾照，刚搬到这里。你必须在多长时间内办 Washington 驾照？","o":["30 天内","90 天内","10 天内","1 年内"],"h1":"大约是一个月。","h2":"在 Washington，18 岁或以上、有别的州驾照的新居民，有 30 天时间办 Washington 驾照。","p":"对。新居民有 30 天时间办 Washington 驾照。"},"vi":{"q":"Ở Washington, bạn từ 18 tuổi trở lên, có bằng lái của tiểu bang khác và vừa chuyển đến đây. Bạn phải lấy bằng lái Washington trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 90 ngày","Trong vòng 10 ngày","Trong vòng 1 năm"],"h1":"Khoảng một tháng.","h2":"Ở Washington, cư dân mới từ 18 tuổi trở lên có bằng lái của tiểu bang khác có 30 ngày để lấy bằng lái Washington.","p":"Đúng. Cư dân mới có 30 ngày để lấy bằng lái Washington."},"tl":{"q":"Sa Washington, ikaw ay 18 taong gulang pataas, may lisensya ka mula sa ibang state, at kalilipat mo lang dito. Gaano kabilis ka dapat kumuha ng Washington driver license?","o":["Sa loob ng 30 araw","Sa loob ng 90 araw","Sa loob ng 10 araw","Sa loob ng 1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa Washington, ang bagong residente na 18 taong gulang pataas na may lisensya mula sa ibang state ay may 30 araw para kumuha ng Washington driver license.","p":"Tama. May 30 araw ang mga bagong residente para kumuha ng Washington license."},"ar":{"q":"في Washington، عمرك 18 سنة أو أكثر، ومعك رخصة من ولاية أخرى، وانتقلت إلى هنا للتو. خلال كم من الوقت يجب أن تحصل على رخصة قيادة من Washington؟","o":["خلال 30 يومًا","خلال 90 يومًا","خلال 10 أيام","خلال سنة 1"],"h1":"هي شهر تقريبًا.","h2":"في Washington، المقيم الجديد الذي عمره 18 سنة أو أكثر ومعه رخصة من ولاية أخرى عنده 30 يومًا ليحصل على رخصة قيادة من Washington.","p":"صحيح. عند المقيمين الجدد 30 يومًا للحصول على رخصة من Washington."},"ref":{"doc":"WA","page":"§1.5"}},{"id":"wa-033","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you move to a new home. How soon must you update your address with the Department of Licensing?","o":["Within 30 days","Within 10 days","Within 6 months","At your next renewal"],"h1":"It is less than two weeks.","h2":"In Washington, you must update your address within 10 days after you move.","p":"Right. Update your address within 10 days."},"es":{"q":"En Washington, usted se muda a una casa nueva. ¿En cuánto tiempo debe actualizar su dirección con el Departamento de Licencias?","o":["Dentro de 30 días","Dentro de 10 días","Dentro de 6 meses","En su próxima renovación"],"h1":"Es menos de dos semanas.","h2":"En Washington, usted debe actualizar su dirección dentro de los 10 días después de mudarse.","p":"Correcto. Actualice su dirección dentro de 10 días."},"zh":{"q":"在 Washington，你搬了新家。你必须在多长时间内向车辆管理部门（Department of Licensing）更新地址？","o":["30 天内","10 天内","6 个月内","下次更新驾照时"],"h1":"不到两个星期。","h2":"在 Washington，你搬家后必须在 10 天内更新地址。","p":"对。在 10 天内更新地址。"},"vi":{"q":"Ở Washington, bạn chuyển đến nhà mới. Bạn phải cập nhật địa chỉ với Sở Cấp Phép (Department of Licensing) trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 6 tháng","Vào lần gia hạn tới"],"h1":"Ít hơn hai tuần.","h2":"Ở Washington, bạn phải cập nhật địa chỉ trong vòng 10 ngày sau khi chuyển nhà.","p":"Đúng. Cập nhật địa chỉ trong vòng 10 ngày."},"tl":{"q":"Sa Washington, lumipat ka sa bagong bahay. Gaano kabilis mo dapat i-update ang address mo sa Department of Licensing?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 6 na buwan","Sa susunod mong renewal"],"h1":"Kulang ito sa dalawang linggo.","h2":"Sa Washington, dapat mong i-update ang address mo sa loob ng 10 araw pagkatapos mong lumipat.","p":"Tama. I-update ang address mo sa loob ng 10 araw."},"ar":{"q":"في Washington، انتقلت إلى بيت جديد. خلال كم من الوقت يجب أن تحدّث عنوانك لدى دائرة الترخيص (Department of Licensing)؟","o":["خلال 30 يومًا","خلال 10 أيام","خلال 6 أشهر","عند التجديد القادم"],"h1":"أقل من أسبوعين.","h2":"في Washington، يجب أن تحدّث عنوانك خلال 10 أيام بعد انتقالك.","p":"صحيح. حدّث عنوانك خلال 10 أيام."},"ref":{"doc":"WA","page":"§1.16"}},{"id":"wa-034","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, an officer thinks you are driving under the influence, and you refuse to be tested. How long could you lose your driving privilege?","o":["7 to 30 days","30 to 60 days","90 to 730 days, or until age 21 if that is longer","5 to 10 years"],"h1":"It starts at about three months and can reach two years.","h2":"In Washington, refusing the test can cost you your driving privilege for 90 to 730 days, or until you turn 21 if that is longer.","p":"Right. A refusal can mean 90 to 730 days without your privilege, or until age 21 if that is longer."},"es":{"q":"En Washington, un oficial cree que usted maneja bajo la influencia y usted se niega a hacerse la prueba. ¿Por cuánto tiempo podría perder su privilegio de manejar?","o":["De 7 a 30 días","De 30 a 60 días","De 90 a 730 días, o hasta los 21 años si eso es más tiempo","De 5 a 10 años"],"h1":"Empieza en unos tres meses y puede llegar a dos años.","h2":"En Washington, negarse a la prueba puede costarle su privilegio de manejar por 90 a 730 días, o hasta cumplir 21 años si eso es más tiempo.","p":"Correcto. Negarse puede significar de 90 a 730 días sin su privilegio, o hasta los 21 años si eso es más tiempo."},"zh":{"q":"在 Washington，警察认为你酒后或吸毒后驾驶，而你拒绝接受检测。你可能会失去驾驶权多久？","o":["7 到 30 天","30 到 60 天","90 到 730 天，或者到 21 岁（如果那更久）","5 到 10 年"],"h1":"从大约三个月开始，最长可到两年。","h2":"在 Washington，拒绝检测可能让你失去驾驶权 90 到 730 天，或者到你满 21 岁（如果那更久）。","p":"对。拒绝检测可能让你 90 到 730 天没有驾驶权，或者到 21 岁（如果那更久）。"},"vi":{"q":"Ở Washington, cảnh sát nghĩ bạn đang lái xe khi say rượu hoặc dùng chất kích thích, và bạn từ chối xét nghiệm. Bạn có thể mất quyền lái xe bao lâu?","o":["Từ 7 đến 30 ngày","Từ 30 đến 60 ngày","Từ 90 đến 730 ngày, hoặc đến 21 tuổi nếu thời gian đó lâu hơn","Từ 5 đến 10 năm"],"h1":"Bắt đầu khoảng ba tháng và có thể lên đến hai năm.","h2":"Ở Washington, từ chối xét nghiệm có thể làm bạn mất quyền lái xe từ 90 đến 730 ngày, hoặc đến khi bạn 21 tuổi nếu thời gian đó lâu hơn.","p":"Đúng. Từ chối có thể làm bạn mất quyền lái xe từ 90 đến 730 ngày, hoặc đến 21 tuổi nếu thời gian đó lâu hơn."},"tl":{"q":"Sa Washington, iniisip ng pulis na nagmamaneho ka nang lasing o lango, at tumanggi kang magpa-test. Gaano katagal mo puwedeng mawala ang karapatan mong magmaneho?","o":["7 hanggang 30 araw","30 hanggang 60 araw","90 hanggang 730 araw, o hanggang edad 21 kung mas matagal iyon","5 hanggang 10 taon"],"h1":"Nagsisimula ito sa mga tatlong buwan at puwedeng umabot sa dalawang taon.","h2":"Sa Washington, kapag tumanggi ka sa test, puwede mong mawala ang karapatan mong magmaneho nang 90 hanggang 730 araw, o hanggang mag-21 ka kung mas matagal iyon.","p":"Tama. Ang pagtanggi ay puwedeng mangahulugan ng 90 hanggang 730 araw na walang karapatang magmaneho, o hanggang edad 21 kung mas matagal iyon."},"ar":{"q":"في Washington، يظن الشرطي أنك تقود تحت تأثير الكحول أو المخدرات، وأنت ترفض الفحص. كم من الوقت قد تفقد حقك في القيادة؟","o":["من 7 إلى 30 يومًا","من 30 إلى 60 يومًا","من 90 إلى 730 يومًا، أو حتى سن 21 إذا كان ذلك أطول","من 5 إلى 10 سنوات"],"h1":"تبدأ من نحو ثلاثة أشهر وقد تصل إلى سنتين.","h2":"في Washington، رفض الفحص قد يُفقدك حقك في القيادة من 90 إلى 730 يومًا، أو حتى تبلغ 21 سنة إذا كان ذلك أطول.","p":"صحيح. الرفض قد يعني من 90 إلى 730 يومًا بلا حق في القيادة، أو حتى سن 21 إذا كان ذلك أطول."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-035","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, a driver with an intermediate license gets a second traffic violation or at-fault crash. What happens?","o":["Only a warning letter","A fine, but nothing else changes","The driver must retake the knowledge test","The license is suspended for 6 months or until age 18, whichever comes first"],"h1":"After the second one, the driver stops driving for a while.","h2":"In Washington, a second violation on an intermediate license means the license is suspended for 6 months or until age 18, whichever comes first.","p":"Right. The license is suspended for 6 months or until age 18, whichever comes first."},"es":{"q":"En Washington, un conductor con licencia intermedia recibe una segunda infracción de tránsito o tiene un segundo choque por su culpa. ¿Qué pasa?","o":["Solo una carta de advertencia","Una multa, pero nada más cambia","El conductor debe repetir el examen de conocimientos","La licencia se suspende por 6 meses o hasta los 18 años, lo que ocurra primero"],"h1":"Después de la segunda vez, el conductor deja de manejar por un tiempo.","h2":"En Washington, una segunda infracción con licencia intermedia significa que la licencia se suspende por 6 meses o hasta los 18 años, lo que ocurra primero.","p":"Correcto. La licencia se suspende por 6 meses o hasta los 18 años, lo que ocurra primero."},"zh":{"q":"在 Washington，持有中级驾照（intermediate license）的司机第二次违反交通规则，或第二次发生自己有责任的车祸。会怎样？","o":["只收到一封警告信","罚款，但别的都不变","司机必须重考笔试","驾照被暂停 6 个月或到 18 岁，以先到者为准"],"h1":"第二次以后，司机要停开一段时间。","h2":"在 Washington，持中级驾照第二次违规，驾照会被暂停 6 个月或到 18 岁，以先到者为准。","p":"对。驾照被暂停 6 个月或到 18 岁，以先到者为准。"},"vi":{"q":"Ở Washington, một tài xế có bằng lái trung cấp (intermediate license) bị vi phạm giao thông lần thứ hai hoặc gây tai nạn lần thứ hai do lỗi của mình. Chuyện gì xảy ra?","o":["Chỉ nhận một lá thư cảnh cáo","Bị phạt tiền, nhưng không có gì khác thay đổi","Tài xế phải thi lại bài thi lý thuyết","Bằng lái bị đình chỉ 6 tháng hoặc đến 18 tuổi, tùy điều nào đến trước"],"h1":"Sau lần thứ hai, tài xế phải ngừng lái một thời gian.","h2":"Ở Washington, vi phạm lần thứ hai khi có bằng lái trung cấp nghĩa là bằng lái bị đình chỉ 6 tháng hoặc đến 18 tuổi, tùy điều nào đến trước.","p":"Đúng. Bằng lái bị đình chỉ 6 tháng hoặc đến 18 tuổi, tùy điều nào đến trước."},"tl":{"q":"Sa Washington, ang driver na may intermediate license ay nagkaroon ng ikalawang traffic violation o ikalawang aksidente na siya ang may kasalanan. Ano ang mangyayari?","o":["Warning letter lang","Multa, pero walang ibang magbabago","Kailangang ulitin ng driver ang knowledge test","Masususpinde ang lisensya nang 6 na buwan o hanggang edad 18, alinman ang mauna"],"h1":"Pagkatapos ng ikalawa, titigil muna sa pagmamaneho ang driver.","h2":"Sa Washington, ang ikalawang violation sa intermediate license ay nangangahulugang masususpinde ang lisensya nang 6 na buwan o hanggang edad 18, alinman ang mauna.","p":"Tama. Masususpinde ang lisensya nang 6 na buwan o hanggang edad 18, alinman ang mauna."},"ar":{"q":"في Washington، سائق معه رخصة متوسطة (intermediate license) ارتكب مخالفة مرور ثانية أو تسبّب في حادث ثانٍ بخطئه. ماذا يحدث؟","o":["رسالة تحذير فقط","غرامة، ولا يتغيّر شيء آخر","يجب على السائق أن يعيد الامتحان النظري","تُوقَف الرخصة 6 أشهر أو حتى سن 18، أيّهما يأتي أولًا"],"h1":"بعد المرة الثانية، يتوقف السائق عن القيادة مدة من الوقت.","h2":"في Washington، المخالفة الثانية مع رخصة متوسطة تعني أن الرخصة تُوقَف 6 أشهر أو حتى سن 18، أيّهما يأتي أولًا.","p":"صحيح. تُوقَف الرخصة 6 أشهر أو حتى سن 18، أيّهما يأتي أولًا."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-036","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you get a traffic ticket. Within how many days must you follow the instructions on the back of it?","o":["15 days","30 days","60 days","5 days"],"h1":"It is about two weeks.","h2":"In Washington, you must follow the instructions on the back of a ticket within 15 days, or your driving privilege could be suspended.","p":"Right. Act on a ticket within 15 days."},"es":{"q":"En Washington, usted recibe una multa de tránsito. ¿En cuántos días debe seguir las instrucciones que están al reverso?","o":["15 días","30 días","60 días","5 días"],"h1":"Son unas dos semanas.","h2":"En Washington, usted debe seguir las instrucciones al reverso de una multa dentro de 15 días, o su privilegio de manejar podría ser suspendido.","p":"Correcto. Responda a una multa dentro de 15 días."},"zh":{"q":"在 Washington，你收到一张交通罚单。你必须在几天内按照罚单背面的说明去做？","o":["15 天","30 天","60 天","5 天"],"h1":"大约两个星期。","h2":"在 Washington，你必须在 15 天内按照罚单背面的说明去做，否则你的驾驶权可能会被暂停。","p":"对。收到罚单后要在 15 天内处理。"},"vi":{"q":"Ở Washington, bạn nhận một giấy phạt giao thông. Bạn phải làm theo hướng dẫn ở mặt sau giấy phạt trong bao nhiêu ngày?","o":["15 ngày","30 ngày","60 ngày","5 ngày"],"h1":"Khoảng hai tuần.","h2":"Ở Washington, bạn phải làm theo hướng dẫn ở mặt sau giấy phạt trong vòng 15 ngày, nếu không quyền lái xe của bạn có thể bị đình chỉ.","p":"Đúng. Xử lý giấy phạt trong vòng 15 ngày."},"tl":{"q":"Sa Washington, nakatanggap ka ng traffic ticket. Sa loob ng ilang araw mo dapat sundin ang mga instruction sa likod nito?","o":["15 araw","30 araw","60 araw","5 araw"],"h1":"Mga dalawang linggo ito.","h2":"Sa Washington, dapat mong sundin ang mga instruction sa likod ng ticket sa loob ng 15 araw, kung hindi ay puwedeng masuspinde ang karapatan mong magmaneho.","p":"Tama. Asikasuhin ang ticket sa loob ng 15 araw."},"ar":{"q":"في Washington، أخذت مخالفة مرور. خلال كم يومًا يجب أن تتّبع التعليمات المكتوبة على ظهرها؟","o":["15 يومًا","30 يومًا","60 يومًا","5 أيام"],"h1":"هي أسبوعان تقريبًا.","h2":"في Washington، يجب أن تتّبع التعليمات المكتوبة على ظهر المخالفة خلال 15 يومًا، وإلا قد يُوقَف حقك في القيادة.","p":"صحيح. تصرّف في المخالفة خلال 15 يومًا."},"ref":{"doc":"WA","page":"§5.10"}},{"id":"wa-037","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, during which hours does the law require your headlights to be on?","o":["From sunset to sunrise only","From a half hour after sunset to a half hour before sunrise","From 8 p.m. to 6 a.m.","Only when there are no street lights"],"h1":"The rule follows the sun, with a short gap of time.","h2":"In Washington, the law requires headlights from a half hour after sunset to a half hour before sunrise.","p":"Right. Headlights go on from a half hour after sunset to a half hour before sunrise."},"es":{"q":"En Washington, ¿durante qué horas exige la ley que tenga los faros encendidos?","o":["Solo desde la puesta del sol hasta la salida del sol","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","De 8 p.m. a 6 a.m.","Solo cuando no hay luces en la calle"],"h1":"La regla sigue al sol, con un poco de tiempo de margen.","h2":"En Washington, la ley exige los faros encendidos desde media hora después de la puesta del sol hasta media hora antes de la salida del sol.","p":"Correcto. Los faros van encendidos desde media hora después de la puesta del sol hasta media hora antes de la salida del sol."},"zh":{"q":"在 Washington，法律要求你在哪段时间开车头灯？","o":["只从日落到日出","从日落后半小时到日出前半小时","从晚上 8 点到早上 6 点","只在没有路灯的时候"],"h1":"这条规定跟着太阳走，再加一点时间。","h2":"在 Washington，法律要求从日落后半小时到日出前半小时开车头灯。","p":"对。从日落后半小时到日出前半小时要开车头灯。"},"vi":{"q":"Ở Washington, luật yêu cầu bạn bật đèn pha trong những giờ nào?","o":["Chỉ từ lúc mặt trời lặn đến lúc mặt trời mọc","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc","Từ 8 giờ tối đến 6 giờ sáng","Chỉ khi không có đèn đường"],"h1":"Quy định đi theo mặt trời, có thêm một khoảng thời gian ngắn.","h2":"Ở Washington, luật yêu cầu bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa Washington, sa anong mga oras iniuutos ng batas na nakabukas ang headlights mo?","o":["Mula paglubog hanggang pagsikat ng araw lang","Mula kalahating oras pagkatapos lumubog ang araw hanggang kalahating oras bago sumikat ang araw","Mula 8 p.m. hanggang 6 a.m.","Kapag walang ilaw sa kalye lang"],"h1":"Sinusunod ng patakaran ang araw, may maikling dagdag na oras.","h2":"Sa Washington, iniuutos ng batas na nakabukas ang headlights mula kalahating oras pagkatapos lumubog ang araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Buksan ang headlights mula kalahating oras pagkatapos lumubog ang araw hanggang kalahating oras bago sumikat ang araw."},"ar":{"q":"في Washington، في أي ساعات يفرض القانون أن تكون أضواء سيارتك الأمامية مشتعلة؟","o":["من الغروب إلى الشروق فقط","من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق","من 8 مساءً إلى 6 صباحًا","فقط عندما لا توجد أضواء في الشارع"],"h1":"القاعدة تتبع الشمس، مع وقت قصير زيادة.","h2":"في Washington، يفرض القانون إشعال الأضواء الأمامية من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق.","p":"صحيح. تُشعَل الأضواء الأمامية من نصف ساعة بعد الغروب إلى نصف ساعة قبل الشروق."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-038","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, you are driving behind another vehicle with your high beams on. Within how many feet of it must you switch to low beams?","o":["100 feet","200 feet","300 feet","1,000 feet"],"h1":"It is less than the 500 feet used for a car coming toward you.","h2":"In Washington, you must switch to low beams when you are within 300 feet behind another vehicle.","p":"Right. Use low beams within 300 feet when you follow a vehicle."},"es":{"q":"En Washington, usted maneja detrás de otro vehículo con las luces altas encendidas. ¿A cuántos pies de él debe cambiar a luces bajas?","o":["100 pies","200 pies","300 pies","1,000 pies"],"h1":"Es menos que los 500 pies que se usan para un carro que viene de frente.","h2":"En Washington, usted debe cambiar a luces bajas cuando está a menos de 300 pies detrás de otro vehículo.","p":"Correcto. Use luces bajas a menos de 300 pies cuando sigue a un vehículo."},"zh":{"q":"在 Washington，你开着远光灯跟在另一辆车后面。离它多少英尺以内必须换成近光灯？","o":["100 英尺","200 英尺","300 英尺","1,000 英尺"],"h1":"它比对面来车时用的 500 英尺要短。","h2":"在 Washington，当你在另一辆车后面 300 英尺以内时，必须换成近光灯。","p":"对。跟车时在 300 英尺以内要用近光灯。"},"vi":{"q":"Ở Washington, bạn đang lái sau một xe khác và bật đèn pha chiếu xa. Khi cách xe đó bao nhiêu feet thì bạn phải chuyển sang đèn chiếu gần?","o":["100 feet","200 feet","300 feet","1,000 feet"],"h1":"Ít hơn 500 feet dùng cho xe chạy ngược chiều về phía bạn.","h2":"Ở Washington, bạn phải chuyển sang đèn chiếu gần khi bạn ở trong vòng 300 feet phía sau một xe khác.","p":"Đúng. Dùng đèn chiếu gần trong vòng 300 feet khi bạn đi sau một xe."},"tl":{"q":"Sa Washington, nagmamaneho ka sa likod ng ibang sasakyan at nakabukas ang high beams mo. Sa loob ng ilang feet mula rito ka dapat lumipat sa low beams?","o":["100 feet","200 feet","300 feet","1,000 feet"],"h1":"Mas maikli ito sa 500 feet na ginagamit para sa sasakyang paparating sa iyo.","h2":"Sa Washington, dapat kang lumipat sa low beams kapag nasa loob ka ng 300 feet sa likod ng ibang sasakyan.","p":"Tama. Gumamit ng low beams sa loob ng 300 feet kapag may sinusundan kang sasakyan."},"ar":{"q":"في Washington، أنت تقود خلف سيارة أخرى والأضواء العالية مشتعلة. على بُعد كم قدمًا منها يجب أن تنتقل إلى الأضواء المنخفضة؟","o":["100 قدم","200 قدم","300 قدم","1,000 قدم"],"h1":"هي أقل من الـ 500 قدم المستعملة لسيارة قادمة نحوك.","h2":"في Washington، يجب أن تنتقل إلى الأضواء المنخفضة عندما تكون على بُعد 300 قدم أو أقل خلف سيارة أخرى.","p":"صحيح. استعمل الأضواء المنخفضة على بُعد 300 قدم أو أقل عندما تسير خلف سيارة."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-039","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, at least how many feet before a turn should you turn on your signal?","o":["20 feet","50 feet","500 feet","100 feet"],"h1":"It is about the length of six cars in a row.","h2":"In Washington, you should turn on your signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet before the turn."},"es":{"q":"En Washington, ¿por lo menos a cuántos pies antes de una vuelta debe poner la direccional?","o":["20 pies","50 pies","500 pies","100 pies"],"h1":"Es más o menos el largo de seis carros en fila.","h2":"En Washington, usted debe poner la direccional por lo menos 100 pies antes de dar la vuelta.","p":"Correcto. Ponga la direccional por lo menos 100 pies antes de la vuelta."},"zh":{"q":"在 Washington，转弯前至少多少英尺就应该打转向灯？","o":["20 英尺","50 英尺","500 英尺","100 英尺"],"h1":"大约是六辆车排成一排的长度。","h2":"在 Washington，你应该在转弯前至少 100 英尺打转向灯。","p":"对。转弯前至少 100 英尺打转向灯。"},"vi":{"q":"Ở Washington, bạn nên bật đèn xi nhan ít nhất bao nhiêu feet trước khi rẽ?","o":["20 feet","50 feet","500 feet","100 feet"],"h1":"Khoảng bằng chiều dài của sáu chiếc xe xếp hàng.","h2":"Ở Washington, bạn nên bật đèn xi nhan ít nhất 100 feet trước khi rẽ.","p":"Đúng. Bật xi nhan ít nhất 100 feet trước khi rẽ."},"tl":{"q":"Sa Washington, hindi bababa sa ilang feet bago lumiko mo dapat buksan ang signal mo?","o":["20 feet","50 feet","500 feet","100 feet"],"h1":"Mga kasinghaba ito ng anim na sasakyang magkakasunod.","h2":"Sa Washington, dapat mong buksan ang signal mo nang hindi bababa sa 100 feet bago ka lumiko.","p":"Tama. Mag-signal nang hindi bababa sa 100 feet bago lumiko."},"ar":{"q":"في Washington، قبل المنعطف بكم قدمًا على الأقل يجب أن تشغّل إشارة الانعطاف؟","o":["20 قدمًا","50 قدمًا","500 قدم","100 قدم"],"h1":"هي تقريبًا طول ست سيارات في صف واحد.","h2":"في Washington، يجب أن تشغّل إشارة الانعطاف قبل أن تنعطف بـ 100 قدم على الأقل.","p":"صحيح. شغّل الإشارة قبل المنعطف بـ 100 قدم على الأقل."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-040","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, children under what age should never ride in the front seat, because of the airbags?","o":["13","8","10","16"],"h1":"It is the age when a child becomes a teenager.","h2":"In Washington, children under 13 should never ride in the front seat, because an airbag could badly hurt them.","p":"Right. Children under 13 ride in the back seat."},"es":{"q":"En Washington, ¿los niños menores de qué edad nunca deben ir en el asiento delantero, por las bolsas de aire?","o":["13","8","10","16"],"h1":"Es la edad en que un niño se vuelve adolescente.","h2":"En Washington, los niños menores de 13 años nunca deben ir en el asiento delantero, porque una bolsa de aire podría lastimarlos gravemente.","p":"Correcto. Los niños menores de 13 años van en el asiento de atrás."},"zh":{"q":"在 Washington，因为有安全气囊，几岁以下的儿童永远不应该坐前座？","o":["13","8","10","16"],"h1":"就是孩子变成青少年的年龄。","h2":"在 Washington，13 岁以下的儿童永远不应该坐前座，因为安全气囊可能会严重伤害他们。","p":"对。13 岁以下的儿童坐后座。"},"vi":{"q":"Ở Washington, trẻ em dưới bao nhiêu tuổi không bao giờ nên ngồi ghế trước, vì túi khí?","o":["13","8","10","16"],"h1":"Đó là tuổi trẻ em bắt đầu thành thiếu niên.","h2":"Ở Washington, trẻ em dưới 13 tuổi không bao giờ nên ngồi ghế trước, vì túi khí có thể làm các em bị thương nặng.","p":"Đúng. Trẻ em dưới 13 tuổi ngồi ghế sau."},"tl":{"q":"Sa Washington, ang mga batang wala pang ilang taong gulang ay hindi kailanman dapat umupo sa harap, dahil sa airbags?","o":["13","8","10","16"],"h1":"Ito ang edad kung kailan nagiging teenager ang bata.","h2":"Sa Washington, ang mga batang wala pang 13 taong gulang ay hindi kailanman dapat umupo sa harap, dahil puwede silang masaktan nang malubha ng airbag.","p":"Tama. Sa likod umuupo ang mga batang wala pang 13 taong gulang."},"ar":{"q":"في Washington، الأطفال تحت أي سن يجب ألّا يجلسوا أبدًا في المقعد الأمامي، بسبب الوسائد الهوائية؟","o":["13","8","10","16"],"h1":"هي السن التي يصبح فيها الطفل مراهقًا.","h2":"في Washington، الأطفال تحت 13 سنة يجب ألّا يجلسوا أبدًا في المقعد الأمامي، لأن الوسادة الهوائية قد تؤذيهم أذًى شديدًا.","p":"صحيح. الأطفال تحت 13 سنة يجلسون في المقعد الخلفي."},"ref":{"doc":"WA","page":"§2.6"}},{"id":"wa-041","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you may not park within how many feet of a stop sign, yield sign, or traffic signal?","o":["15 feet","30 feet","50 feet","10 feet"],"h1":"It is twice the distance for a fire hydrant.","h2":"In Washington, you may not park within 30 feet of a stop sign, yield sign, or traffic signal.","p":"Right. Park at least 30 feet from a stop sign, yield sign, or traffic signal."},"es":{"q":"En Washington, ¿a cuántos pies de una señal de alto, una señal de ceda el paso o un semáforo no puede estacionarse?","o":["15 pies","30 pies","50 pies","10 pies"],"h1":"Es el doble de la distancia de un hidrante.","h2":"En Washington, usted no puede estacionarse a menos de 30 pies de una señal de alto, una señal de ceda el paso o un semáforo.","p":"Correcto. Estaciónese por lo menos a 30 pies de una señal de alto, de ceda el paso o de un semáforo."},"zh":{"q":"在 Washington，离停车标志（stop sign）、让行标志（yield sign）或红绿灯多少英尺以内不能停车？","o":["15 英尺","30 英尺","50 英尺","10 英尺"],"h1":"它是消防栓距离的两倍。","h2":"在 Washington，你不能在停车标志、让行标志或红绿灯 30 英尺以内停车。","p":"对。停车时要离停车标志、让行标志或红绿灯至少 30 英尺。"},"vi":{"q":"Ở Washington, bạn không được đậu xe trong vòng bao nhiêu feet từ biển dừng (stop sign), biển nhường đường (yield sign) hoặc đèn giao thông?","o":["15 feet","30 feet","50 feet","10 feet"],"h1":"Gấp đôi khoảng cách với trụ nước cứu hỏa.","h2":"Ở Washington, bạn không được đậu xe trong vòng 30 feet từ biển dừng, biển nhường đường hoặc đèn giao thông.","p":"Đúng. Đậu xe cách biển dừng, biển nhường đường hoặc đèn giao thông ít nhất 30 feet."},"tl":{"q":"Sa Washington, sa loob ng ilang feet mula sa stop sign, yield sign, o traffic signal ka hindi puwedeng pumarada?","o":["15 feet","30 feet","50 feet","10 feet"],"h1":"Doble ito ng layo para sa fire hydrant.","h2":"Sa Washington, hindi ka puwedeng pumarada sa loob ng 30 feet mula sa stop sign, yield sign, o traffic signal.","p":"Tama. Pumarada nang hindi bababa sa 30 feet mula sa stop sign, yield sign, o traffic signal."},"ar":{"q":"في Washington، على بُعد كم قدمًا من لافتة قف (stop sign) أو لافتة أفضلية المرور (yield sign) أو إشارة المرور لا يجوز لك أن تركن؟","o":["15 قدمًا","30 قدمًا","50 قدمًا","10 أقدام"],"h1":"هي ضعف المسافة من حنفية الحريق.","h2":"في Washington، لا يجوز لك أن تركن على بُعد 30 قدمًا أو أقل من لافتة قف أو لافتة أفضلية المرور أو إشارة المرور.","p":"صحيح. اركن على بُعد 30 قدمًا على الأقل من لافتة قف أو لافتة أفضلية المرور أو إشارة المرور."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-042","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, you may not park within how many feet of a fire hydrant?","o":["5 feet","10 feet","15 feet","30 feet"],"h1":"It is about the length of one car.","h2":"In Washington, you may not park within 15 feet of a fire hydrant.","p":"Right. Keep at least 15 feet from a fire hydrant when you park."},"es":{"q":"En Washington, ¿a cuántos pies de un hidrante no puede estacionarse?","o":["5 pies","10 pies","15 pies","30 pies"],"h1":"Es más o menos el largo de un carro.","h2":"En Washington, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Al estacionarse, quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 Washington，离消防栓多少英尺以内不能停车？","o":["5 英尺","10 英尺","15 英尺","30 英尺"],"h1":"大约是一辆车的长度。","h2":"在 Washington，你不能在消防栓 15 英尺以内停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở Washington, bạn không được đậu xe trong vòng bao nhiêu feet từ trụ nước cứu hỏa?","o":["5 feet","10 feet","15 feet","30 feet"],"h1":"Khoảng bằng chiều dài một chiếc xe.","h2":"Ở Washington, bạn không được đậu xe trong vòng 15 feet từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa Washington, sa loob ng ilang feet mula sa fire hydrant ka hindi puwedeng pumarada?","o":["5 feet","10 feet","15 feet","30 feet"],"h1":"Mga kasinghaba ito ng isang sasakyan.","h2":"Sa Washington, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet sa fire hydrant kapag pumaparada ka."},"ar":{"q":"في Washington، على بُعد كم قدمًا من حنفية الحريق لا يجوز لك أن تركن؟","o":["5 أقدام","10 أقدام","15 قدمًا","30 قدمًا"],"h1":"هي تقريبًا طول سيارة واحدة.","h2":"في Washington، لا يجوز لك أن تركن على بُعد 15 قدمًا أو أقل من حنفية الحريق.","p":"صحيح. ابقَ على بُعد 15 قدمًا على الأقل من حنفية الحريق عندما تركن."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-043","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, when you park next to a curb, what is the farthest your vehicle may be from the curb?","o":["24 inches","18 inches","6 inches","12 inches"],"h1":"Think of the length of a school ruler.","h2":"In Washington, a vehicle parked next to a curb may be no more than 12 inches from the curb.","p":"Right. Park no more than 12 inches from the curb."},"es":{"q":"En Washington, cuando se estaciona junto a la acera, ¿a qué distancia máxima de la acera puede quedar su vehículo?","o":["24 pulgadas","18 pulgadas","6 pulgadas","12 pulgadas"],"h1":"Piense en el largo de una regla escolar.","h2":"En Washington, un vehículo estacionado junto a la acera no puede quedar a más de 12 pulgadas de la acera.","p":"Correcto. Estaciónese a no más de 12 pulgadas de la acera."},"zh":{"q":"在 Washington，靠路边石停车时，你的车离路边石最远可以多远？","o":["24 英寸","18 英寸","6 英寸","12 英寸"],"h1":"想一想学校用的尺子有多长。","h2":"在 Washington，靠路边石停的车离路边石不能超过 12 英寸。","p":"对。停车时离路边石不超过 12 英寸。"},"vi":{"q":"Ở Washington, khi đậu xe sát lề đường, xe của bạn được cách lề đường xa nhất là bao nhiêu?","o":["24 inch","18 inch","6 inch","12 inch"],"h1":"Hãy nghĩ đến chiều dài của cây thước ở trường.","h2":"Ở Washington, xe đậu sát lề đường không được cách lề đường quá 12 inch.","p":"Đúng. Đậu xe cách lề đường không quá 12 inch."},"tl":{"q":"Sa Washington, kapag pumarada ka sa tabi ng curb, ano ang pinakamalayong puwedeng layo ng sasakyan mo sa curb?","o":["24 inches","18 inches","6 inches","12 inches"],"h1":"Isipin ang haba ng ruler sa paaralan.","h2":"Sa Washington, ang sasakyang nakaparada sa tabi ng curb ay hindi puwedeng lumayo nang higit sa 12 inches mula sa curb.","p":"Tama. Pumarada nang hindi hihigit sa 12 inches mula sa curb."},"ar":{"q":"في Washington، عندما تركن بجانب الرصيف، ما أبعد مسافة يمكن أن تكون بين سيارتك والرصيف؟","o":["24 بوصة","18 بوصة","6 بوصات","12 بوصة"],"h1":"فكّر في طول مسطرة المدرسة.","h2":"في Washington، السيارة المركونة بجانب الرصيف يجب ألّا تبعد عن الرصيف أكثر من 12 بوصة.","p":"صحيح. اركن على بُعد 12 بوصة أو أقل من الرصيف."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-044","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, what is the speed limit in a school zone?","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"It is a low, round number.","h2":"In Washington, the speed limit in a school zone is 20 mph.","p":"Right. Drive no faster than 20 mph in a school zone."},"es":{"q":"En Washington, ¿cuál es el límite de velocidad en una zona escolar?","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"Es un número bajo y redondo.","h2":"En Washington, el límite de velocidad en una zona escolar es de 20 mph.","p":"Correcto. No maneje a más de 20 mph en una zona escolar."},"zh":{"q":"在 Washington，学校区域的限速是多少？","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"它是一个小的整数。","h2":"在 Washington，学校区域的限速是 20 mph。","p":"对。在学校区域车速不要超过 20 mph。"},"vi":{"q":"Ở Washington, giới hạn tốc độ trong khu vực trường học là bao nhiêu?","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"Đó là một số tròn và nhỏ.","h2":"Ở Washington, giới hạn tốc độ trong khu vực trường học là 20 mph.","p":"Đúng. Không lái nhanh hơn 20 mph trong khu vực trường học."},"tl":{"q":"Sa Washington, ano ang speed limit sa school zone?","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"Isa itong mababa at buong numero.","h2":"Sa Washington, 20 mph ang speed limit sa school zone.","p":"Tama. Huwag lumampas sa 20 mph sa school zone."},"ar":{"q":"في Washington، ما حد السرعة في منطقة المدرسة؟","o":["20 mph","25 mph","15 mph","30 mph"],"h1":"هو عدد صغير وكامل.","h2":"في Washington، حد السرعة في منطقة المدرسة هو 20 mph.","p":"صحيح. لا تتجاوز 20 mph في منطقة المدرسة."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-045","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you enter a shared center lane to turn left. What is the farthest you should drive in that lane?","o":["100 feet","300 feet","500 feet","As far as you want"],"h1":"It is about the length of a football field.","h2":"In Washington, you should not drive more than 300 feet in a shared center left-turn lane.","p":"Right. Drive no more than 300 feet in the center lane."},"es":{"q":"En Washington, usted entra al carril central compartido para dar vuelta a la izquierda. ¿Cuál es la distancia máxima que debe manejar en ese carril?","o":["100 pies","300 pies","500 pies","Lo que usted quiera"],"h1":"Es más o menos el largo de un campo de fútbol americano.","h2":"En Washington, usted no debe manejar más de 300 pies en un carril central compartido para vueltas a la izquierda.","p":"Correcto. No maneje más de 300 pies en el carril central."},"zh":{"q":"在 Washington，你开进中间共用车道准备左转。你在这条车道里最多应该开多远？","o":["100 英尺","300 英尺","500 英尺","想开多远就开多远"],"h1":"大约是一个橄榄球场的长度。","h2":"在 Washington，你在中间共用左转车道里开的距离不应该超过 300 英尺。","p":"对。在中间车道里开的距离不超过 300 英尺。"},"vi":{"q":"Ở Washington, bạn vào làn giữa dùng chung để rẽ trái. Bạn nên lái trong làn đó xa nhất là bao nhiêu?","o":["100 feet","300 feet","500 feet","Bao xa tùy ý"],"h1":"Khoảng bằng chiều dài một sân bóng bầu dục.","h2":"Ở Washington, bạn không nên lái quá 300 feet trong làn giữa dùng chung để rẽ trái.","p":"Đúng. Không lái quá 300 feet trong làn giữa."},"tl":{"q":"Sa Washington, pumasok ka sa shared center lane para kumaliwa. Ano ang pinakamalayong dapat mong imaneho sa lane na iyon?","o":["100 feet","300 feet","500 feet","Kahit gaano kalayo ang gusto mo"],"h1":"Mga kasinghaba ito ng football field.","h2":"Sa Washington, hindi ka dapat magmaneho nang higit sa 300 feet sa shared center left-turn lane.","p":"Tama. Huwag magmaneho nang higit sa 300 feet sa center lane."},"ar":{"q":"في Washington، دخلت المسار الأوسط المشترك لتنعطف يسارًا. ما أبعد مسافة يجب أن تقودها في هذا المسار؟","o":["100 قدم","300 قدم","500 قدم","أي مسافة تريدها"],"h1":"هي تقريبًا طول ملعب كرة القدم الأمريكية.","h2":"في Washington، يجب ألّا تقود أكثر من 300 قدم في المسار الأوسط المشترك للانعطاف يسارًا.","p":"صحيح. لا تقد أكثر من 300 قدم في المسار الأوسط."},"ref":{"doc":"WA","page":"§4.16"}},{"id":"wa-046","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, a person is walking across the street in front of you. They are not using a cane, wheelchair, or service animal. When may you drive on?","o":["As soon as they pass your front bumper","When they reach the middle of the street","When they have cleared your lane and one more lane","When they step off the curb"],"h1":"Clearing only your own lane is not enough.","h2":"In Washington, you must wait until a person crossing has cleared your lane and one more lane before you drive on.","p":"Right. Wait until they clear your lane and one more lane."},"es":{"q":"En Washington, una persona cruza la calle caminando frente a usted. No usa bastón, silla de ruedas ni animal de servicio. ¿Cuándo puede seguir manejando?","o":["En cuanto pase su parachoques delantero","Cuando llegue a la mitad de la calle","Cuando haya salido de su carril y de un carril más","Cuando baje de la acera"],"h1":"No basta con que salga solo de su carril.","h2":"En Washington, usted debe esperar a que la persona que cruza haya salido de su carril y de un carril más antes de seguir.","p":"Correcto. Espere a que salga de su carril y de un carril más."},"zh":{"q":"在 Washington，有人在你前面走路过马路。他没有用拐杖、轮椅或服务动物。你什么时候可以继续开？","o":["他一走过你的前保险杠就可以","他走到马路中间时","他已经走出你的车道，再走出一条车道时","他走下路边石时"],"h1":"只走出你自己的车道还不够。","h2":"在 Washington，你必须等过马路的人走出你的车道，再走出一条车道，才能继续开。","p":"对。等他走出你的车道，再走出一条车道。"},"vi":{"q":"Ở Washington, một người đang đi bộ qua đường trước mặt bạn. Người đó không dùng gậy, xe lăn hay động vật phục vụ. Khi nào bạn được lái tiếp?","o":["Ngay khi họ đi qua cản trước xe bạn","Khi họ đến giữa đường","Khi họ đã ra khỏi làn của bạn và thêm một làn nữa","Khi họ bước xuống khỏi lề đường"],"h1":"Chỉ ra khỏi làn của bạn thôi thì chưa đủ.","h2":"Ở Washington, bạn phải chờ người qua đường ra khỏi làn của bạn và thêm một làn nữa rồi mới lái tiếp.","p":"Đúng. Chờ họ ra khỏi làn của bạn và thêm một làn nữa."},"tl":{"q":"Sa Washington, may taong naglalakad patawid ng kalye sa harap mo. Hindi siya gumagamit ng tungkod, wheelchair, o service animal. Kailan ka puwedeng magpatuloy sa pagmamaneho?","o":["Pagkalampas niya sa harap na bumper mo","Pagdating niya sa gitna ng kalye","Kapag nakalabas na siya sa lane mo at sa isa pang lane","Pagbaba niya sa curb"],"h1":"Hindi sapat na makalabas lang siya sa sarili mong lane.","h2":"Sa Washington, dapat kang maghintay hanggang makalabas ang tumatawid sa lane mo at sa isa pang lane bago ka magpatuloy.","p":"Tama. Maghintay hanggang makalabas siya sa lane mo at sa isa pang lane."},"ar":{"q":"في Washington، شخص يعبر الشارع مشيًا أمامك. لا يستعمل عصا ولا كرسيًّا متحركًا ولا حيوان خدمة. متى يمكنك أن تتابع القيادة؟","o":["بمجرد أن يتجاوز المصدّ الأمامي لسيارتك","عندما يصل إلى منتصف الشارع","عندما يخرج من مسارك ومن مسار آخر بعده","عندما ينزل عن الرصيف"],"h1":"خروجه من مسارك وحده لا يكفي.","h2":"في Washington، يجب أن تنتظر حتى يخرج الشخص العابر من مسارك ومن مسار آخر بعده قبل أن تتابع القيادة.","p":"صحيح. انتظر حتى يخرج من مسارك ومن مسار آخر بعده."},"ref":{"doc":"WA","page":"§4.1"}},{"id":"wa-047","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, you are on a four-lane highway divided by a median. A school bus on the other side, coming toward you, stops with its red lights flashing. What must you do?","o":["Stop until the red lights stop flashing","Stop, then go when the bus driver waves","Stop and turn on your hazard lights","You do not need to stop, but watch for children"],"h1":"The median keeps you apart from the bus.","h2":"In Washington, on a divided highway with three or more lanes, you do not need to stop for a school bus going the other way, but you should still watch for children.","p":"Right. You do not need to stop, but stay alert for children."},"es":{"q":"En Washington, usted va por una carretera de cuatro carriles dividida por una mediana. Un autobús escolar del otro lado, que viene hacia usted, se detiene con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que las luces rojas dejen de parpadear","Detenerse y seguir cuando el chofer del autobús le haga señas","Detenerse y encender las luces de emergencia","No necesita detenerse, pero esté atento a los niños"],"h1":"La mediana lo separa del autobús.","h2":"En Washington, en una carretera dividida de tres o más carriles, usted no necesita detenerse por un autobús escolar que va en sentido contrario, pero aun así debe estar atento a los niños.","p":"Correcto. No necesita detenerse, pero esté atento a los niños."},"zh":{"q":"在 Washington，你在一条有中央隔离带的四车道公路上。对面迎着你开来的校车停下，红灯在闪。你必须怎么做？","o":["停车，直到红灯不再闪","停车，等校车司机挥手再走","停车并打开双闪灯","你不需要停车，但要注意儿童"],"h1":"中央隔离带把你和校车分开了。","h2":"在 Washington，在三条或更多车道的分隔公路上，你不需要为对向行驶的校车停车，但仍然应该注意儿童。","p":"对。你不需要停车，但要留意儿童。"},"vi":{"q":"Ở Washington, bạn đang ở trên đường cao tốc bốn làn có dải phân cách ở giữa. Một xe buýt trường học ở bên kia đường, đang đi về phía bạn, dừng lại và nháy đèn đỏ. Bạn phải làm gì?","o":["Dừng lại cho đến khi đèn đỏ ngừng nháy","Dừng lại, rồi đi khi tài xế xe buýt vẫy tay","Dừng lại và bật đèn khẩn cấp","Bạn không cần dừng, nhưng hãy để ý trẻ em"],"h1":"Dải phân cách tách bạn khỏi xe buýt.","h2":"Ở Washington, trên đường có dải phân cách với ba làn trở lên, bạn không cần dừng lại cho xe buýt trường học đi ngược chiều, nhưng vẫn nên để ý trẻ em.","p":"Đúng. Bạn không cần dừng, nhưng hãy để ý trẻ em."},"tl":{"q":"Sa Washington, nasa four-lane highway ka na may median sa gitna. Ang school bus sa kabilang panig, na papunta sa iyo, ay huminto at kumikislap ang pulang ilaw nito. Ano ang dapat mong gawin?","o":["Huminto hanggang tumigil sa pagkislap ang pulang ilaw","Huminto, saka umandar kapag kumaway ang driver ng bus","Huminto at buksan ang hazard lights mo","Hindi mo kailangang huminto, pero bantayan ang mga bata"],"h1":"Pinaghihiwalay ka ng median sa bus.","h2":"Sa Washington, sa divided highway na may tatlo o higit pang lane, hindi mo kailangang huminto para sa school bus na papunta sa kabilang direksyon, pero dapat mo pa ring bantayan ang mga bata.","p":"Tama. Hindi mo kailangang huminto, pero bantayan ang mga bata."},"ar":{"q":"في Washington، أنت على طريق سريع من أربعة مسارات يقسمه حاجز في الوسط. حافلة مدرسية في الجهة الأخرى، قادمة نحوك، تتوقف وأضواؤها الحمراء تومض. ماذا يجب أن تفعل؟","o":["توقف حتى تتوقف الأضواء الحمراء عن الوميض","توقف، ثم انطلق عندما يلوّح لك سائق الحافلة","توقف وشغّل أضواء الطوارئ","ليس عليك أن تتوقف، لكن انتبه للأطفال"],"h1":"الحاجز الأوسط يفصلك عن الحافلة.","h2":"في Washington، على طريق مقسوم بحاجز فيه ثلاثة مسارات أو أكثر، ليس عليك أن تتوقف لحافلة مدرسية تسير في الاتجاه المعاكس، لكن يجب أن تبقى منتبهًا للأطفال.","p":"صحيح. ليس عليك أن تتوقف، لكن ابقَ منتبهًا للأطفال."},"ref":{"doc":"WA","page":"§4.2"}},{"id":"wa-048","scope":"WA","cat":"signals","sign":null,"c":0,"en":{"q":"In Washington, what should you know about flashing green traffic lights?","o":["Washington does not use them","They mean you have a protected left turn","They mean stop, then go when it is safe","They mean the light will turn red soon"],"h1":"You might see one across the border in British Columbia, Canada.","h2":"Washington does not use flashing green traffic lights, though you might see them in British Columbia, Canada.","p":"Right. You will not see a flashing green light in Washington."},"es":{"q":"En Washington, ¿qué debe saber sobre los semáforos con luz verde intermitente?","o":["Washington no los usa","Significan que tiene una vuelta a la izquierda protegida","Significan pare y luego siga cuando sea seguro","Significan que la luz pronto cambiará a roja"],"h1":"Podría ver uno al otro lado de la frontera, en Columbia Británica, Canadá.","h2":"Washington no usa semáforos con luz verde intermitente, aunque podría verlos en Columbia Británica, Canadá.","p":"Correcto. En Washington no verá una luz verde intermitente."},"zh":{"q":"在 Washington，关于闪烁的绿灯你应该知道什么？","o":["Washington 不使用闪烁的绿灯","表示你有受保护的左转","表示先停车，安全时再走","表示灯很快会变红"],"h1":"你可能会在边境另一边的加拿大 British Columbia 看到。","h2":"Washington 不使用闪烁的绿灯，不过你可能会在加拿大 British Columbia 看到。","p":"对。在 Washington 你不会看到闪烁的绿灯。"},"vi":{"q":"Ở Washington, bạn nên biết gì về đèn giao thông màu xanh nhấp nháy?","o":["Washington không dùng loại đèn này","Nghĩa là bạn được rẽ trái có bảo vệ","Nghĩa là dừng lại, rồi đi khi an toàn","Nghĩa là đèn sắp chuyển sang đỏ"],"h1":"Bạn có thể thấy loại đèn này ở bên kia biên giới, tại British Columbia, Canada.","h2":"Washington không dùng đèn giao thông màu xanh nhấp nháy, nhưng bạn có thể thấy chúng ở British Columbia, Canada.","p":"Đúng. Bạn sẽ không thấy đèn xanh nhấp nháy ở Washington."},"tl":{"q":"Sa Washington, ano ang dapat mong malaman tungkol sa kumikislap na berdeng traffic light?","o":["Hindi ito ginagamit sa Washington","Ibig sabihin, may protected left turn ka","Ibig sabihin, huminto, saka umandar kapag ligtas na","Ibig sabihin, malapit nang maging pula ang ilaw"],"h1":"Baka makakita ka nito sa kabila ng border, sa British Columbia, Canada.","h2":"Hindi gumagamit ang Washington ng kumikislap na berdeng traffic light, pero baka makakita ka nito sa British Columbia, Canada.","p":"Tama. Hindi ka makakakita ng kumikislap na berdeng ilaw sa Washington."},"ar":{"q":"في Washington، ماذا يجب أن تعرف عن إشارات المرور الخضراء الوامضة؟","o":["Washington لا تستعملها","تعني أن لك انعطافًا محميًّا إلى اليسار","تعني توقف، ثم انطلق عندما يكون ذلك آمنًا","تعني أن الإشارة ستصبح حمراء قريبًا"],"h1":"قد ترى واحدة على الجهة الأخرى من الحدود، في British Columbia في كندا.","h2":"Washington لا تستعمل إشارات المرور الخضراء الوامضة، لكنك قد تراها في British Columbia في كندا.","p":"صحيح. لن ترى إشارة خضراء وامضة في Washington."},"ref":{"doc":"WA","page":"§4.11"}},{"id":"wa-049","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you may drive on some ocean beaches. What is the speed limit on the beach?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is between 20 and 30 mph.","h2":"In Washington, the speed limit on ocean beaches where driving is allowed is 25 mph.","p":"Right. Drive no faster than 25 mph on the beach."},"es":{"q":"En Washington, se puede manejar en algunas playas del océano. ¿Cuál es el límite de velocidad en la playa?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Está entre 20 y 30 mph.","h2":"En Washington, el límite de velocidad en las playas del océano donde se permite manejar es de 25 mph.","p":"Correcto. No maneje a más de 25 mph en la playa."},"zh":{"q":"在 Washington，有些海边沙滩可以开车。沙滩上的限速是多少？","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"在 20 和 30 mph 之间。","h2":"在 Washington，允许开车的海边沙滩上限速是 25 mph。","p":"对。在沙滩上车速不要超过 25 mph。"},"vi":{"q":"Ở Washington, bạn được lái xe trên một số bãi biển. Giới hạn tốc độ trên bãi biển là bao nhiêu?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Nằm giữa 20 và 30 mph.","h2":"Ở Washington, giới hạn tốc độ trên các bãi biển được phép lái xe là 25 mph.","p":"Đúng. Không lái nhanh hơn 25 mph trên bãi biển."},"tl":{"q":"Sa Washington, puwede kang magmaneho sa ilang beach sa tabi ng dagat. Ano ang speed limit sa beach?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Nasa pagitan ito ng 20 at 30 mph.","h2":"Sa Washington, 25 mph ang speed limit sa mga beach sa tabi ng dagat kung saan pinapayagang magmaneho.","p":"Tama. Huwag lumampas sa 25 mph sa beach."},"ar":{"q":"في Washington، يمكنك أن تقود على بعض شواطئ المحيط. ما حد السرعة على الشاطئ؟","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"هو بين 20 و30 mph.","h2":"في Washington، حد السرعة على شواطئ المحيط التي يُسمح فيها بالقيادة هو 25 mph.","p":"صحيح. لا تتجاوز 25 mph على الشاطئ."},"ref":{"doc":"WA","page":"§4.20"}},{"id":"wa-050","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, the signal at a railroad crossing is flashing. Where must you stop?","o":["Between 5 and 10 feet from the nearest rail","Within 5 feet of the nearest rail","Between 15 and 50 feet from the nearest rail","At least 100 feet from the nearest rail"],"h1":"Stay well clear of the tracks, but not so far back that you cannot see.","h2":"In Washington, when a railroad crossing signal is flashing, you must stop between 15 and 50 feet from the nearest rail.","p":"Right. Stop between 15 and 50 feet from the nearest rail."},"es":{"q":"En Washington, la señal de un cruce de ferrocarril está parpadeando. ¿Dónde debe detenerse?","o":["Entre 5 y 10 pies del riel más cercano","A menos de 5 pies del riel más cercano","Entre 15 y 50 pies del riel más cercano","Por lo menos a 100 pies del riel más cercano"],"h1":"Quédese lejos de las vías, pero no tan atrás que no pueda ver.","h2":"En Washington, cuando la señal de un cruce de ferrocarril está parpadeando, usted debe detenerse entre 15 y 50 pies del riel más cercano.","p":"Correcto. Deténgase entre 15 y 50 pies del riel más cercano."},"zh":{"q":"在 Washington，铁路道口的信号灯在闪。你必须在哪里停车？","o":["离最近的铁轨 5 到 10 英尺","离最近的铁轨 5 英尺以内","离最近的铁轨 15 到 50 英尺","离最近的铁轨至少 100 英尺"],"h1":"离铁轨远一点，但不要远到看不见。","h2":"在 Washington，铁路道口的信号灯在闪时，你必须在离最近的铁轨 15 到 50 英尺的地方停车。","p":"对。在离最近的铁轨 15 到 50 英尺的地方停车。"},"vi":{"q":"Ở Washington, đèn tín hiệu ở chỗ giao nhau với đường sắt đang nhấp nháy. Bạn phải dừng ở đâu?","o":["Cách đường ray gần nhất từ 5 đến 10 feet","Trong vòng 5 feet từ đường ray gần nhất","Cách đường ray gần nhất từ 15 đến 50 feet","Cách đường ray gần nhất ít nhất 100 feet"],"h1":"Tránh xa đường ray, nhưng đừng lùi xa đến mức không nhìn thấy.","h2":"Ở Washington, khi đèn tín hiệu ở chỗ giao nhau với đường sắt nhấp nháy, bạn phải dừng cách đường ray gần nhất từ 15 đến 50 feet.","p":"Đúng. Dừng cách đường ray gần nhất từ 15 đến 50 feet."},"tl":{"q":"Sa Washington, kumikislap ang signal sa railroad crossing. Saan ka dapat huminto?","o":["Mula 5 hanggang 10 feet mula sa pinakamalapit na riles","Sa loob ng 5 feet mula sa pinakamalapit na riles","Mula 15 hanggang 50 feet mula sa pinakamalapit na riles","Hindi bababa sa 100 feet mula sa pinakamalapit na riles"],"h1":"Lumayo nang husto sa riles, pero huwag masyadong malayo na hindi ka na makakita.","h2":"Sa Washington, kapag kumikislap ang signal sa railroad crossing, dapat kang huminto mula 15 hanggang 50 feet mula sa pinakamalapit na riles.","p":"Tama. Huminto mula 15 hanggang 50 feet mula sa pinakamalapit na riles."},"ar":{"q":"في Washington، إشارة تقاطع سكة الحديد تومض. أين يجب أن تتوقف؟","o":["على بُعد 5 إلى 10 أقدام من أقرب سكة","على بُعد 5 أقدام أو أقل من أقرب سكة","على بُعد 15 إلى 50 قدمًا من أقرب سكة","على بُعد 100 قدم على الأقل من أقرب سكة"],"h1":"ابقَ بعيدًا عن السكة، لكن ليس بعيدًا جدًا حتى لا ترى.","h2":"في Washington، عندما تومض إشارة تقاطع سكة الحديد، يجب أن تتوقف على بُعد 15 إلى 50 قدمًا من أقرب سكة.","p":"صحيح. توقف على بُعد 15 إلى 50 قدمًا من أقرب سكة."},"ref":{"doc":"WA","page":"§4.7"}},{"id":"wa-051","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, what must you have before you can apply for an instruction permit?","o":["A WDL number from the Department of Licensing","A high school diploma","A car registered in your name","A signed letter from a driving instructor"],"h1":"It is a number that starts with three letters.","h2":"In Washington, you need a WDL number before you can apply for an instruction permit.","p":"Right. You need a WDL number first."},"es":{"q":"En Washington, ¿qué debe tener antes de solicitar un permiso de instrucción?","o":["Un número WDL del Departamento de Licencias","Un diploma de secundaria","Un carro registrado a su nombre","Una carta firmada por un instructor de manejo"],"h1":"Es un número que empieza con tres letras.","h2":"En Washington, usted necesita un número WDL antes de solicitar un permiso de instrucción.","p":"Correcto. Primero necesita un número WDL."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-052","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you are 16, you have a license from another state, and you just moved here. What must you apply for?","o":["A full Washington license with no limits","Nothing; your old license works until you turn 18","A new instruction permit, starting over","A Washington intermediate driver license"],"h1":"Teens in Washington drive with limits until 18.","h2":"A 16- or 17-year-old new resident with an out-of-state license must apply for a Washington intermediate driver license.","p":"Right. You apply for an intermediate license."},"es":{"q":"En Washington, usted tiene 16 años, tiene licencia de otro estado y acaba de mudarse aquí. ¿Qué debe solicitar?","o":["Una licencia completa de Washington sin límites","Nada; su licencia anterior sirve hasta los 18 años","Un nuevo permiso de instrucción, empezando de cero","Una licencia intermedia de Washington"],"h1":"En Washington los jóvenes manejan con límites hasta los 18.","h2":"Un nuevo residente de 16 o 17 años con licencia de otro estado debe solicitar una licencia intermedia de Washington.","p":"Correcto. Debe solicitar una licencia intermedia."},"ref":{"doc":"WA","page":"§1.5"}},{"id":"wa-053","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, which of these can you NOT do with a standard (not enhanced) driver license?","o":["Drive a car","Show who you are at a bank","Get through airport security for a flight inside the US","Prove your age at a store"],"h1":"Standard licenses do not meet REAL ID rules.","h2":"A standard Washington license does not meet REAL ID rules, so it is not accepted at airport security, even for flights inside the US.","p":"Right. It is not accepted for domestic flights."},"es":{"q":"En Washington, ¿qué NO puede hacer con una licencia estándar (no mejorada)?","o":["Manejar un carro","Mostrar quién es usted en un banco","Pasar el control de seguridad del aeropuerto para un vuelo dentro de EE. UU.","Probar su edad en una tienda"],"h1":"Las licencias estándar no cumplen las reglas de REAL ID.","h2":"Una licencia estándar de Washington no cumple las reglas de REAL ID, así que no se acepta en el control de seguridad del aeropuerto, ni siquiera para vuelos dentro de EE. UU.","p":"Correcto. No se acepta para vuelos nacionales."},"ref":{"doc":"WA","page":"§1.6"}},{"id":"wa-054","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, an enhanced driver license is NOT good for which of these?","o":["Flights inside the US","International air travel","Crossing into Canada by land","Entering a federal building"],"h1":"You will still need a passport for one kind of trip.","h2":"A Washington enhanced driver license is not good for international air travel; you still need a passport to fly to another country.","p":"Right. It does not work for international flights."},"es":{"q":"En Washington, ¿para cuál de estas cosas NO sirve una licencia mejorada (enhanced)?","o":["Vuelos dentro de EE. UU.","Viajar en avión a otro país","Cruzar a Canadá por tierra","Entrar a un edificio federal"],"h1":"Para un tipo de viaje todavía necesita pasaporte.","h2":"Una licencia mejorada de Washington no sirve para viajar en avión a otro país; para eso todavía necesita pasaporte.","p":"Correcto. No sirve para vuelos internacionales."},"ref":{"doc":"WA","page":"§1.6"}},{"id":"wa-055","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you are experiencing homelessness and need an ID card. What can you get?","o":["Only a full-price ID","A no-cost or reduced-fee ID","No ID until you have an address","A temporary paper ID that lasts one week"],"h1":"The state offers help with the cost.","h2":"In Washington, a person experiencing homelessness can get a no-cost or reduced-fee ID card.","p":"Right. A no-cost or reduced-fee ID."},"es":{"q":"En Washington, usted no tiene vivienda y necesita una tarjeta de identificación. ¿Qué puede obtener?","o":["Solo una identificación a precio completo","Una identificación gratis o a precio reducido","Ninguna identificación hasta tener una dirección","Una identificación de papel que dura una semana"],"h1":"El estado ayuda con el costo.","h2":"En Washington, una persona sin vivienda puede obtener una tarjeta de identificación gratis o a precio reducido.","p":"Correcto. Gratis o a precio reducido."},"ref":{"doc":"WA","page":"§1.5"}},{"id":"wa-056","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you will take a driver training course. When may you apply for your instruction permit?","o":["1 to 10 days before the course starts","Only after the course ends","At least 3 months before the course","On your 16th birthday"],"h1":"It is a short window just before class begins.","h2":"In Washington, a student in a driver training course can apply for the instruction permit 1 to 10 days before the course starts.","p":"Right. 1 to 10 days before the course starts."},"es":{"q":"En Washington, usted va a tomar un curso de manejo. ¿Cuándo puede solicitar su permiso de instrucción?","o":["De 1 a 10 días antes de que empiece el curso","Solo después de terminar el curso","Por lo menos 3 meses antes del curso","El día que cumpla 16 años"],"h1":"Es un periodo corto justo antes de empezar las clases.","h2":"En Washington, un estudiante de un curso de manejo puede solicitar el permiso de instrucción de 1 a 10 días antes de que empiece el curso.","p":"Correcto. De 1 a 10 días antes del curso."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-057","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, a teen took a traffic safety course in another state. What is the least it must include to count?","o":["10 hours in class and 2 hours behind the wheel","20 hours online only","50 hours behind the wheel and no class","30 hours in class and 6 hours behind the wheel"],"h1":"Think of a month of class hours plus a few drives.","h2":"In Washington, an out-of-state traffic safety course must include at least 30 hours of classroom and 6 hours of behind-the-wheel instruction.","p":"Right. 30 hours of class and 6 hours driving."},"es":{"q":"En Washington, un joven tomó un curso de seguridad vial en otro estado. ¿Qué es lo mínimo que debe incluir para contar?","o":["10 horas de clase y 2 horas al volante","20 horas solo en línea","50 horas al volante y nada de clase","30 horas de clase y 6 horas al volante"],"h1":"Piense en muchas horas de clase y unas pocas de manejo.","h2":"En Washington, un curso de seguridad vial de otro estado debe incluir por lo menos 30 horas de clase y 6 horas de instrucción al volante.","p":"Correcto. 30 horas de clase y 6 horas al volante."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-058","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, a teen is applying for a first license. For how long before applying must they have no traffic violations?","o":["1 month","2 years","6 months","3 years"],"h1":"It is the same length as the permit holding time.","h2":"In Washington, a teen must have no traffic violations or convictions for the 6 months before applying for a license.","p":"Right. 6 months with no violations."},"es":{"q":"En Washington, un joven solicita su primera licencia. ¿Por cuánto tiempo antes de solicitarla no debe tener infracciones de tránsito?","o":["1 mes","2 años","6 meses","3 años"],"h1":"Es el mismo tiempo que debe tener el permiso.","h2":"En Washington, un joven no debe tener infracciones ni condenas de tránsito durante los 6 meses antes de solicitar la licencia.","p":"Correcto. 6 meses sin infracciones."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-059","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, a teen practices 50 hours before getting a license. The supervising driver must have been licensed for at least how long?","o":["1 year","6 months","3 years","10 years"],"h1":"It is fewer years than the rule for adults with a permit.","h2":"In Washington, a teen's 50 practice hours must be with a licensed driver who has at least 3 years of driving experience.","p":"Right. At least 3 years of experience."},"es":{"q":"En Washington, un joven practica 50 horas antes de obtener la licencia. ¿Por cuánto tiempo, como mínimo, debe tener licencia el conductor que lo supervisa?","o":["1 año","6 meses","3 años","10 años"],"h1":"Son menos años que la regla para adultos con permiso.","h2":"En Washington, las 50 horas de práctica de un joven deben ser con un conductor con licencia que tenga por lo menos 3 años de experiencia.","p":"Correcto. Por lo menos 3 años de experiencia."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-060","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you get your first license at a licensing office. How long is the temporary license good for?","o":["7 days","45 days","6 months","1 year"],"h1":"It is about a month and a half.","h2":"In Washington, the temporary license you get at the office is good for 45 days while your card comes in the mail.","p":"Right. 45 days."},"es":{"q":"En Washington, usted recibe su primera licencia en una oficina. ¿Por cuánto tiempo vale la licencia temporal?","o":["7 días","45 días","6 meses","1 año"],"h1":"Es como mes y medio.","h2":"En Washington, la licencia temporal que recibe en la oficina vale por 45 días mientras le llega la tarjeta por correo.","p":"Correcto. 45 días."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-061","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, after you pass an exam at a driver training school, how long does the school have to enter your score?","o":["24 hours","7 days","30 days","3 months"],"h1":"It is one day.","h2":"In Washington, a driver training school has 24 hours to enter your score after you pass each exam.","p":"Right. 24 hours."},"es":{"q":"En Washington, después de pasar un examen en una escuela de manejo, ¿cuánto tiempo tiene la escuela para registrar su resultado?","o":["24 horas","7 días","30 días","3 meses"],"h1":"Es un día.","h2":"En Washington, la escuela de manejo tiene 24 horas para registrar su resultado después de que usted pasa cada examen.","p":"Correcto. 24 horas."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-062","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you get your first license online and print the receipt. What is true about that receipt?","o":["It is your permanent license","It is valid photo ID for flying","It does not let you drive until the card arrives","It is your temporary license, but it has no photo, so it is not valid ID"],"h1":"Think about what is missing from a printed receipt.","h2":"In Washington, the printed receipt is your temporary license, but it has no photo, so you cannot use it as identification.","p":"Right. It lets you drive but is not valid ID."},"es":{"q":"En Washington, usted obtiene su primera licencia en línea e imprime el recibo. ¿Qué es cierto sobre ese recibo?","o":["Es su licencia permanente","Sirve como identificación con foto para volar","No le permite manejar hasta que llegue la tarjeta","Es su licencia temporal, pero no tiene foto, así que no sirve como identificación"],"h1":"Piense en lo que le falta a un recibo impreso.","h2":"En Washington, el recibo impreso es su licencia temporal, pero no tiene foto, así que no puede usarlo como identificación.","p":"Correcto. Le permite manejar, pero no sirve como identificación."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-063","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, a driver with an intermediate license gets a first traffic violation. What happens?","o":["The license is taken away for 1 year","Nothing; only the second one counts","The driver must retake the permit test","The intermediate license limits stay in place until age 18"],"h1":"The limits do not end early.","h2":"In Washington, after a first violation, the intermediate license limits stay in place until the driver turns 18.","p":"Right. The limits last until age 18."},"es":{"q":"En Washington, un conductor con licencia intermedia recibe su primera infracción de tránsito. ¿Qué pasa?","o":["Le quitan la licencia por 1 año","Nada; solo cuenta la segunda","Debe repetir el examen del permiso","Los límites de la licencia intermedia siguen hasta los 18 años"],"h1":"Los límites no terminan antes.","h2":"En Washington, después de una primera infracción, los límites de la licencia intermedia siguen hasta que el conductor cumple 18 años.","p":"Correcto. Los límites siguen hasta los 18 años."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-064","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, a driver with an intermediate license gets a third traffic violation. What happens?","o":["The license is suspended for 30 days","The driver pays a fine only","The license is suspended until age 18","The driver gets a warning letter"],"h1":"It is the strongest of the three steps.","h2":"In Washington, a third violation on an intermediate license means the license is suspended until the driver turns 18.","p":"Right. Suspended until age 18."},"es":{"q":"En Washington, un conductor con licencia intermedia recibe su tercera infracción de tránsito. ¿Qué pasa?","o":["Le suspenden la licencia por 30 días","Solo paga una multa","Le suspenden la licencia hasta los 18 años","Recibe una carta de advertencia"],"h1":"Es el paso más fuerte de los tres.","h2":"En Washington, una tercera infracción con licencia intermedia significa que la licencia se suspende hasta que el conductor cumple 18 años.","p":"Correcto. Suspendida hasta los 18 años."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-065","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, a 17-year-old has had an intermediate license for one year with no crashes and no tickets. What changes?","o":["Nothing changes until age 18","They may drive at any hour and carry passengers","They must take the skills test again","They may drive at night but still with no passengers"],"h1":"One year of safe driving earns something.","h2":"In Washington, after one year of safe driving with no crashes or traffic offenses, an intermediate license holder may drive at any hour and carry passengers.","p":"Right. Any hour, with passengers."},"es":{"q":"En Washington, un joven de 17 años ha tenido licencia intermedia por un año sin choques ni multas. ¿Qué cambia?","o":["Nada cambia hasta los 18 años","Puede manejar a cualquier hora y llevar pasajeros","Debe repetir el examen de manejo","Puede manejar de noche, pero sin pasajeros"],"h1":"Un año de manejo seguro tiene premio.","h2":"En Washington, después de un año de manejo seguro sin choques ni infracciones, quien tiene licencia intermedia puede manejar a cualquier hora y llevar pasajeros.","p":"Correcto. A cualquier hora y con pasajeros."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-066","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, when may an intermediate license holder drive at any hour, with passengers, during the first year?","o":["When driving for agricultural (farm) purposes","When driving to a party with friends","On weekends only","When a friend who is 18 rides along"],"h1":"It has to do with farm work.","h2":"In Washington, an intermediate license holder may drive at any hour, with passengers, for agricultural purposes.","p":"Right. For farm work."},"es":{"q":"En Washington, ¿cuándo puede alguien con licencia intermedia manejar a cualquier hora y con pasajeros durante el primer año?","o":["Cuando maneja para trabajo agrícola (del campo)","Cuando va a una fiesta con amigos","Solo los fines de semana","Cuando lo acompaña un amigo de 18 años"],"h1":"Tiene que ver con el trabajo del campo.","h2":"En Washington, quien tiene licencia intermedia puede manejar a cualquier hora y con pasajeros para trabajo agrícola.","p":"Correcto. Para trabajo del campo."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-067","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you have an intermediate license and turn 18. What must you do?","o":["Nothing; the limits end on their own","Get a new license that same day","Retake the knowledge test","Pay a fee to remove the limits"],"h1":"No trip to the office is needed.","h2":"In Washington, intermediate license limits end automatically at 18, so you do not need a new license until you renew.","p":"Right. The limits end automatically."},"es":{"q":"En Washington, usted tiene licencia intermedia y cumple 18 años. ¿Qué debe hacer?","o":["Nada; los límites terminan solos","Sacar una licencia nueva ese mismo día","Repetir el examen de conocimientos","Pagar para quitar los límites"],"h1":"No hace falta ir a la oficina.","h2":"En Washington, los límites de la licencia intermedia terminan solos a los 18 años, así que no necesita una licencia nueva hasta renovarla.","p":"Correcto. Los límites terminan solos."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-068","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, what is the youngest age for a juvenile agricultural permit to drive for farm work?","o":["14","15 and a half","16","There is no minimum age"],"h1":"This permit is different from an instruction permit.","h2":"In Washington, there is no minimum age for a juvenile agricultural permit, which only allows driving in a set area for farm work.","p":"Right. There is no minimum age."},"es":{"q":"En Washington, ¿cuál es la edad mínima para un permiso agrícola juvenil para manejar en trabajo del campo?","o":["14","15 años y medio","16","No hay edad mínima"],"h1":"Este permiso es distinto del permiso de instrucción.","h2":"En Washington, no hay edad mínima para un permiso agrícola juvenil, que solo permite manejar en un área fija para trabajo del campo.","p":"Correcto. No hay edad mínima."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-069","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, who gets an early warning letter from the Department of Licensing after a first moving violation?","o":["All drivers over 65","Only drivers with a commercial license","Drivers ages 18 to 21","Drivers who just moved to Washington"],"h1":"Young adult drivers are at higher risk after one ticket.","h2":"In Washington, the Department of Licensing sends an early warning letter to drivers ages 18 to 21 after their first moving violation.","p":"Right. Drivers ages 18 to 21."},"es":{"q":"En Washington, ¿quién recibe una carta de advertencia temprana del Departamento de Licencias después de su primera infracción en movimiento?","o":["Todos los conductores mayores de 65 años","Solo conductores con licencia comercial","Conductores de 18 a 21 años","Conductores que acaban de mudarse a Washington"],"h1":"Los conductores adultos jóvenes corren más riesgo después de una multa.","h2":"En Washington, el Departamento de Licencias envía una carta de advertencia temprana a los conductores de 18 a 21 años después de su primera infracción en movimiento.","p":"Correcto. Conductores de 18 a 21 años."},"ref":{"doc":"WA","page":"§1.8"}},{"id":"wa-070","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you wear glasses when you take the vision screening. What happens?","o":["Nothing is noted on your license","It is noted on your license, and you must wear them when you drive","You may only drive during the day","You must retake the screening every year"],"h1":"The license shows a note about it.","h2":"In Washington, if you use glasses or contact lenses, it is recorded on your license, and you must wear them whenever you drive.","p":"Right. It is noted, and you must wear them."},"es":{"q":"En Washington, usted usa lentes cuando hace el examen de la vista. ¿Qué pasa?","o":["No se anota nada en su licencia","Se anota en su licencia y debe usarlos siempre que maneje","Solo puede manejar de día","Debe repetir el examen de la vista cada año"],"h1":"La licencia muestra una nota sobre eso.","h2":"En Washington, si usa lentes o lentes de contacto, se anota en su licencia y debe usarlos siempre que maneje.","p":"Correcto. Se anota y debe usarlos."},"ref":{"doc":"WA","page":"§1.9"}},{"id":"wa-071","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, which of these designations can you add to your license or ID card to help first responders?","o":["Your favorite hospital","Deaf or hard of hearing","Your blood type","Your car insurance company"],"h1":"It tells responders how you communicate.","h2":"In Washington, you can add a deaf or hard of hearing designation, as well as developmental disability or medical alert, to your license or ID card.","p":"Right. Deaf or hard of hearing is one of them."},"es":{"q":"En Washington, ¿cuál de estas anotaciones puede agregar a su licencia o identificación para ayudar a los socorristas?","o":["Su hospital favorito","Sordo o con dificultad para oír","Su tipo de sangre","Su compañía de seguro de carro"],"h1":"Les dice a los socorristas cómo se comunica usted.","h2":"En Washington, puede agregar a su licencia o identificación la anotación de sordo o con dificultad para oír, además de discapacidad del desarrollo o alerta médica.","p":"Correcto. Sordo o con dificultad para oír es una de ellas."},"ref":{"doc":"WA","page":"§1.9"}},{"id":"wa-072","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, who may ride in the car during your driving skills exam?","o":["Only you and the examiner, except a service animal or sign language interpreter","You, the examiner, and one parent","Anyone who has a license","Your driving instructor, sitting in the back"],"h1":"The car should be almost empty.","h2":"In Washington, only you and the examiner may be in the car during the skills exam, except for a service animal or a sign language interpreter.","p":"Right. Only you and the examiner."},"es":{"q":"En Washington, ¿quién puede ir en el carro durante su examen de manejo?","o":["Solo usted y el examinador, salvo un animal de servicio o un intérprete de lenguaje de señas","Usted, el examinador y uno de sus padres","Cualquier persona con licencia","Su instructor de manejo, sentado atrás"],"h1":"El carro debe ir casi vacío.","h2":"En Washington, solo usted y el examinador pueden ir en el carro durante el examen de manejo, salvo un animal de servicio o un intérprete de lenguaje de señas.","p":"Correcto. Solo usted y el examinador."},"ref":{"doc":"WA","page":"§1.12"}},{"id":"wa-073","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, what must the car you bring to the driving skills exam have?","o":["Tinted windows and a backup camera","A second brake pedal for the examiner","A paid-off loan and a clean title","Proof of current liability insurance and working brake lights, signals, and seat belts"],"h1":"The examiner checks paperwork and safety parts.","h2":"In Washington, the car for the skills exam must be licensed and registered, have proof of current liability insurance, and have working brake lights, turn signals, and seat belts.","p":"Right. Proof of insurance and working safety equipment."},"es":{"q":"En Washington, ¿qué debe tener el carro que usted lleva al examen de manejo?","o":["Vidrios polarizados y cámara de reversa","Un segundo pedal de freno para el examinador","Un préstamo pagado y un título limpio","Prueba de seguro de responsabilidad vigente y luces de freno, direccionales y cinturones que funcionen"],"h1":"El examinador revisa papeles y piezas de seguridad.","h2":"En Washington, el carro del examen de manejo debe estar registrado, tener prueba de seguro de responsabilidad vigente y tener luces de freno, direccionales y cinturones de seguridad que funcionen.","p":"Correcto. Prueba de seguro y equipo de seguridad que funcione."},"ref":{"doc":"WA","page":"§1.12"}},{"id":"wa-074","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, what must driver training courses for students under 18 offer to parents?","o":["A free car inspection","A discount on car insurance","A parent orientation class","A ride-along on the skills test"],"h1":"It helps mentors understand the program.","h2":"In Washington, driver training courses for students under 18 must offer a parent orientation class.","p":"Right. A parent orientation class."},"es":{"q":"En Washington, ¿qué deben ofrecer a los padres los cursos de manejo para estudiantes menores de 18 años?","o":["Una inspección gratis del carro","Un descuento en el seguro del carro","Una clase de orientación para padres","Acompañar al estudiante en el examen de manejo"],"h1":"Ayuda a los mentores a entender el programa.","h2":"En Washington, los cursos de manejo para estudiantes menores de 18 años deben ofrecer una clase de orientación para padres.","p":"Correcto. Una clase de orientación para padres."},"ref":{"doc":"WA","page":"§1.14"}},{"id":"wa-075","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, your license expired 8 years ago. What must you do to get a license again?","o":["Just pay the renewal fee","Only pass a vision test","Retake the knowledge and skills tests","Take an online class"],"h1":"After that long, you prove your skills again.","h2":"In Washington, if your license has been expired for 8 years or more, you must retake the knowledge and skills tests.","p":"Right. You retake both tests."},"es":{"q":"En Washington, su licencia venció hace 8 años. ¿Qué debe hacer para volver a tener licencia?","o":["Solo pagar la renovación","Solo pasar el examen de la vista","Repetir los exámenes de conocimientos y de manejo","Tomar una clase en línea"],"h1":"Después de tanto tiempo, debe demostrar otra vez lo que sabe.","h2":"En Washington, si su licencia lleva 8 años o más vencida, debe repetir los exámenes de conocimientos y de manejo.","p":"Correcto. Repite los dos exámenes."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-076","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, a minor commits an alcohol, drug, or firearm offense. How long could their license be delayed?","o":["Until age 16","Until age 17","Until age 25","For one week"],"h1":"It is one year after the usual age for a first license.","h2":"In Washington, a minor with an alcohol, drug, or firearm offense risks having their license delayed until age 17.","p":"Right. Until age 17."},"es":{"q":"En Washington, un menor comete un delito de alcohol, drogas o armas de fuego. ¿Hasta cuándo podrían retrasar su licencia?","o":["Hasta los 16 años","Hasta los 17 años","Hasta los 25 años","Por una semana"],"h1":"Es un año después de la edad usual para la primera licencia.","h2":"En Washington, un menor con un delito de alcohol, drogas o armas de fuego puede tener su licencia retrasada hasta los 17 años.","p":"Correcto. Hasta los 17 años."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-077","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, a teen lost their license for an alcohol, drug, or firearm offense and can now get it back. What must they do?","o":["Retake the knowledge and skills exams and pay a reissue fee","Nothing; the old license starts working again","Only watch a safety video","Wait for a new card in the mail"],"h1":"Even passed exams must be taken again.","h2":"In Washington, after this kind of suspension, the driver must retake the knowledge and skills exams and pay a reissue fee, plus have a parent's consent if under 18.","p":"Right. Retake both exams and pay the reissue fee."},"es":{"q":"En Washington, un joven perdió la licencia por un delito de alcohol, drogas o armas y ya puede recuperarla. ¿Qué debe hacer?","o":["Repetir los exámenes de conocimientos y de manejo y pagar una cuota de reexpedición","Nada; la licencia anterior vuelve a servir","Solo ver un video de seguridad","Esperar una tarjeta nueva por correo"],"h1":"Hay que repetir hasta los exámenes ya aprobados.","h2":"En Washington, después de este tipo de suspensión, el conductor debe repetir los exámenes de conocimientos y de manejo y pagar una cuota de reexpedición, y si es menor de 18, tener el permiso de un padre.","p":"Correcto. Repite los dos exámenes y paga la reexpedición."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-078","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you got married and changed your last name. Where must you update your license?","o":["Online in License Express","By phone","At any police station","At a driver licensing office"],"h1":"Address changes can be done online, but this one cannot.","h2":"In Washington, a name change must be made in person at a driver licensing office.","p":"Right. At a driver licensing office."},"es":{"q":"En Washington, usted se casó y cambió su apellido. ¿Dónde debe actualizar su licencia?","o":["En línea en License Express","Por teléfono","En cualquier estación de policía","En una oficina de licencias de manejo"],"h1":"El cambio de dirección se puede hacer en línea, pero este no.","h2":"En Washington, el cambio de nombre se debe hacer en persona en una oficina de licencias de manejo.","p":"Correcto. En una oficina de licencias."},"ref":{"doc":"WA","page":"§1.16"}},{"id":"wa-079","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you are 16 and applying for a driver license. What can you do about voting?","o":["Vote in the next election","Nothing until you turn 18","Register to vote only by mail","Pre-register to vote"],"h1":"You cannot vote yet, but you can get ready.","h2":"In Washington, 16- and 17-year-olds can pre-register to vote when they apply for a driver license or ID card.","p":"Right. You can pre-register."},"es":{"q":"En Washington, usted tiene 16 años y solicita una licencia de manejo. ¿Qué puede hacer sobre el voto?","o":["Votar en la próxima elección","Nada hasta cumplir 18 años","Inscribirse para votar solo por correo","Preinscribirse para votar"],"h1":"Todavía no puede votar, pero puede prepararse.","h2":"En Washington, los jóvenes de 16 y 17 años pueden preinscribirse para votar cuando solicitan la licencia o la identificación.","p":"Correcto. Puede preinscribirse."},"ref":{"doc":"WA","page":"§1.16"}},{"id":"wa-080","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, which of these can cost you your driving privileges?","o":["Driving an older car","Getting a parking ticket you paid on time","Putting a construction or emergency worker in danger","Driving with the radio on"],"h1":"Think about people working on or near the road.","h2":"In Washington, putting a construction or emergency worker in danger is one of the reasons you can lose your driving privileges.","p":"Right. Endangering road workers can cost you your license."},"es":{"q":"En Washington, ¿cuál de estas cosas puede hacerle perder sus privilegios de manejar?","o":["Manejar un carro viejo","Recibir una multa de estacionamiento que pagó a tiempo","Poner en peligro a un trabajador de construcción o de emergencia","Manejar con la radio prendida"],"h1":"Piense en las personas que trabajan en la carretera o cerca de ella.","h2":"En Washington, poner en peligro a un trabajador de construcción o de emergencia es una de las razones por las que puede perder sus privilegios de manejar.","p":"Correcto. Poner en peligro a trabajadores viales puede costarle la licencia."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-081","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, how many years is a driver license usually issued for?","o":["2 years","8 years","4 years","12 years"],"h1":"It is longer than most states' 4 or 5 years.","h2":"In Washington, a driver license usually expires on your birthday 8 years after it is issued, though a 6-year option is also offered.","p":"Right. Usually 8 years."},"es":{"q":"En Washington, ¿por cuántos años se expide normalmente una licencia de manejo?","o":["2 años","8 años","4 años","12 años"],"h1":"Es más que los 4 o 5 años de muchos estados.","h2":"En Washington, la licencia normalmente vence en su cumpleaños 8 años después de expedirse, aunque también se ofrece la opción de 6 años.","p":"Correcto. Normalmente 8 años."},"ref":{"doc":"WA","page":null}},{"id":"wa-082","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how much is the driver license fee under state law?","o":["$10 for each year the license is issued","$5 for the whole license","$50 for each year","There is no fee"],"h1":"The fee depends on how many years the license lasts.","h2":"Washington law sets the driver license fee at $10 for each year the license is issued, renewed, or extended.","p":"Right. $10 per year."},"es":{"q":"En Washington, ¿cuánto cuesta la licencia de manejo según la ley estatal?","o":["$10 por cada año de la licencia","$5 por toda la licencia","$50 por cada año","No cuesta nada"],"h1":"El costo depende de cuántos años dura la licencia.","h2":"La ley de Washington fija el costo de la licencia en $10 por cada año que se expide, renueva o extiende.","p":"Correcto. $10 por año."},"ref":{"doc":"WA","page":null}},{"id":"wa-083","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you renew your license more than 60 days after it expired. What extra penalty fee do you pay?","o":["$10","$100","$250","None"],"h1":"It is a small amount.","h2":"In Washington, renewing more than 60 days after your license expired adds a $10 penalty fee, with some exceptions such as being out of state.","p":"Right. A $10 penalty fee."},"es":{"q":"En Washington, usted renueva su licencia más de 60 días después de vencida. ¿Qué cuota de penalidad extra paga?","o":["$10","$100","$250","Ninguna"],"h1":"Es una cantidad pequeña.","h2":"En Washington, renovar más de 60 días después del vencimiento agrega una penalidad de $10, con algunas excepciones como estar fuera del estado.","p":"Correcto. Una penalidad de $10."},"ref":{"doc":"WA","page":null}},{"id":"wa-084","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how much is the instruction permit application fee starting January 1, 2026?","o":["$10","$25","$100","$35"],"h1":"It went up by $10 that year.","h2":"Washington law sets the instruction permit application fee at $35 starting January 1, 2026; it was $25 before that.","p":"Right. $35."},"es":{"q":"En Washington, ¿cuánto cuesta la solicitud del permiso de instrucción a partir del 1 de enero de 2026?","o":["$10","$25","$100","$35"],"h1":"Subió $10 ese año.","h2":"La ley de Washington fija la solicitud del permiso de instrucción en $35 a partir del 1 de enero de 2026; antes costaba $25.","p":"Correcto. $35."},"ref":{"doc":"WA","page":null}},{"id":"wa-085","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, first-time license applicants under what age must pass a free online work zone and first responder safety course?","o":["Under 18","Under 21","Under 25","Under 30"],"h1":"It covers teens and young adults.","h2":"Washington law requires first-time license applicants under 25 to pass a free online course on work zone and first responder safety.","p":"Right. Under 25."},"es":{"q":"En Washington, ¿los solicitantes de su primera licencia menores de qué edad deben aprobar un curso gratis en línea sobre zonas de trabajo y socorristas?","o":["Menores de 18","Menores de 21","Menores de 25","Menores de 30"],"h1":"Incluye a adolescentes y adultos jóvenes.","h2":"La ley de Washington exige que quienes solicitan su primera licencia y son menores de 25 años aprueben un curso gratis en línea sobre seguridad en zonas de trabajo y con socorristas.","p":"Correcto. Menores de 25."},"ref":{"doc":"WA","page":null}},{"id":"wa-086","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, starting January 1, 2027, an 18-year-old getting a first driver license must also do what?","o":["Hold a permit for 2 years","Complete a driver training course","Have a parent sign for them","Pass a medical exam"],"h1":"Until then, only teens under 18 had to do this.","h2":"Washington law requires 18-year-olds getting a first license to complete a driver training course starting January 1, 2027, and the age range grows each year after that.","p":"Right. They must complete driver training."},"es":{"q":"En Washington, a partir del 1 de enero de 2027, ¿qué más debe hacer una persona de 18 años que saca su primera licencia?","o":["Tener el permiso por 2 años","Terminar un curso de manejo","Tener la firma de uno de sus padres","Pasar un examen médico"],"h1":"Hasta entonces, solo los menores de 18 tenían que hacerlo.","h2":"La ley de Washington exige que las personas de 18 años que sacan su primera licencia terminen un curso de manejo a partir del 1 de enero de 2027, y el rango de edad crece cada año después.","p":"Correcto. Debe terminar un curso de manejo."},"ref":{"doc":"WA","page":null}},{"id":"wa-087","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, where must you keep proof of insurance?","o":["Only at home","With you or in the vehicle","Only at the insurance office","You do not need to keep proof"],"h1":"An officer may ask to see it during a stop.","h2":"In Washington, you must keep proof of liability insurance with you or in your vehicle.","p":"Right. With you or in the vehicle."},"es":{"q":"En Washington, ¿dónde debe tener la prueba del seguro?","o":["Solo en su casa","Con usted o en el vehículo","Solo en la oficina del seguro","No necesita tener prueba"],"h1":"Un oficial puede pedirla durante una parada.","h2":"En Washington, usted debe tener la prueba del seguro de responsabilidad con usted o en su vehículo.","p":"Correcto. Con usted o en el vehículo."},"ref":{"doc":"WA","page":"§2.3"}},{"id":"wa-088","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you show proof of insurance to an officer on your phone. What may the officer look at?","o":["Only the proof of insurance","Anything on your phone","Your photos and messages","Your phone's call history"],"h1":"The law protects the rest of your phone.","h2":"Washington law says that when you show proof of insurance on a phone, the officer may only view the proof of insurance and nothing else on the device.","p":"Right. Only the proof of insurance."},"es":{"q":"En Washington, usted le muestra a un oficial la prueba del seguro en su teléfono. ¿Qué puede mirar el oficial?","o":["Solo la prueba del seguro","Cualquier cosa en su teléfono","Sus fotos y mensajes","El historial de llamadas"],"h1":"La ley protege el resto de su teléfono.","h2":"La ley de Washington dice que cuando usted muestra la prueba del seguro en un teléfono, el oficial solo puede ver la prueba del seguro y nada más en el aparato.","p":"Correcto. Solo la prueba del seguro."},"ref":{"doc":"WA","page":null}},{"id":"wa-089","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, how many moving violations in 12 months will get your license suspended?","o":["2","3","12","6"],"h1":"It is half a dozen.","h2":"In Washington, your license is suspended if you get 6 moving violations in 12 months, or 7 in 24 months.","p":"Right. 6 in 12 months."},"es":{"q":"En Washington, ¿cuántas infracciones en movimiento en 12 meses hacen que le suspendan la licencia?","o":["2","3","12","6"],"h1":"Es media docena.","h2":"En Washington, le suspenden la licencia si recibe 6 infracciones en movimiento en 12 meses, o 7 en 24 meses.","p":"Correcto. 6 en 12 meses."},"ref":{"doc":"WA","page":null}},{"id":"wa-090","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, your license is suspended for too many moving violations. How long is the suspension?","o":["7 days","1 year","60 days","5 years"],"h1":"It is about two months.","h2":"In Washington, a suspension for too many moving violations lasts 60 days, followed by a 1-year probation.","p":"Right. 60 days."},"es":{"q":"En Washington, le suspenden la licencia por demasiadas infracciones en movimiento. ¿Cuánto dura la suspensión?","o":["7 días","1 año","60 días","5 años"],"h1":"Son unos dos meses.","h2":"En Washington, una suspensión por demasiadas infracciones en movimiento dura 60 días, seguida de 1 año de prueba (probation).","p":"Correcto. 60 días."},"ref":{"doc":"WA","page":null}},{"id":"wa-091","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, after a suspension for too many tickets, what reissue fee must you pay to get your license back?","o":["$5","$500","$75","No fee"],"h1":"It is between $50 and $100.","h2":"In Washington, getting your license back after this suspension costs a $75 reissue fee plus the usual licensing fees.","p":"Right. $75."},"es":{"q":"En Washington, después de una suspensión por demasiadas multas, ¿qué cuota de reexpedición debe pagar para recuperar la licencia?","o":["$5","$500","$75","Ninguna"],"h1":"Está entre $50 y $100.","h2":"En Washington, recuperar la licencia después de esta suspensión cuesta una cuota de reexpedición de $75 más las cuotas normales de licencia.","p":"Correcto. $75."},"ref":{"doc":"WA","page":null}},{"id":"wa-092","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you become a habitual traffic offender if you have how many serious offenses, such as DUI or reckless driving, within 5 years?","o":["1","3 or more","2","10 or more"],"h1":"It is a small number of very serious offenses.","h2":"In Washington, three or more serious offenses such as DUI, reckless driving, or hit and run within five years make you a habitual traffic offender.","p":"Right. Three or more."},"es":{"q":"En Washington, ¿cuántos delitos graves, como DUI o manejo temerario, en 5 años lo convierten en infractor habitual?","o":["1","3 o más","2","10 o más"],"h1":"Es un número pequeño de delitos muy graves.","h2":"En Washington, tres o más delitos graves como DUI, manejo temerario o huir de un choque en cinco años lo convierten en infractor habitual de tránsito.","p":"Correcto. Tres o más."},"ref":{"doc":"WA","page":null}},{"id":"wa-093","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, how many moving violations within 5 years can also make you a habitual traffic offender?","o":["20 or more","5 or more","8 or more","50 or more"],"h1":"It is a much larger number than for serious offenses.","h2":"In Washington, 20 or more moving violations within five years can make you a habitual traffic offender.","p":"Right. 20 or more."},"es":{"q":"En Washington, ¿cuántas infracciones en movimiento en 5 años también pueden convertirlo en infractor habitual?","o":["20 o más","5 o más","8 o más","50 o más"],"h1":"Es un número mucho mayor que el de delitos graves.","h2":"En Washington, 20 o más infracciones en movimiento en cinco años pueden convertirlo en infractor habitual de tránsito.","p":"Correcto. 20 o más."},"ref":{"doc":"WA","page":null}},{"id":"wa-094","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, a driver is convicted of reckless driving. For at least how long is the license suspended?","o":["7 days","6 months","5 years","30 days"],"h1":"It is about one month.","h2":"In Washington, a reckless driving conviction means a license suspension of at least 30 days.","p":"Right. At least 30 days."},"es":{"q":"En Washington, un conductor es condenado por manejo temerario. ¿Por cuánto tiempo, como mínimo, le suspenden la licencia?","o":["7 días","6 meses","5 años","30 días"],"h1":"Es como un mes.","h2":"En Washington, una condena por manejo temerario significa una suspensión de la licencia de por lo menos 30 días.","p":"Correcto. Por lo menos 30 días."},"ref":{"doc":"WA","page":null}},{"id":"wa-095","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, a person is convicted a second time of leaving a child under 16 alone in a car with the motor running. What happens to their license?","o":["Nothing happens to the license","They get a warning letter","They must retake the vision test","It is revoked"],"h1":"The second conviction brings the strongest action.","h2":"Washington law says that on a second conviction for leaving a child under 16 alone in a running vehicle, the driver's license is revoked.","p":"Right. The license is revoked."},"es":{"q":"En Washington, una persona es condenada por segunda vez por dejar a un niño menor de 16 años solo en un carro con el motor prendido. ¿Qué pasa con su licencia?","o":["No pasa nada con la licencia","Recibe una carta de advertencia","Debe repetir el examen de la vista","Se la revocan"],"h1":"La segunda condena trae la acción más fuerte.","h2":"La ley de Washington dice que en una segunda condena por dejar a un niño menor de 16 años solo en un vehículo prendido, se revoca la licencia de manejo.","p":"Correcto. Le revocan la licencia."},"ref":{"doc":"WA","page":null}},{"id":"wa-096","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, you sit in a parked car after drinking, with the keys and the ability to start it. Can you be charged with DUI?","o":["No, only moving cars count","No, as long as the engine is off","Yes, being in physical control of the vehicle counts","Only if you are on a freeway"],"h1":"The law looks at control, not only motion.","h2":"In Washington, DUI also covers being in physical control of a vehicle, even a parked one, if you can control its engine or operation.","p":"Right. Physical control counts, even when parked."},"es":{"q":"En Washington, usted está sentado en un carro estacionado después de tomar alcohol, con las llaves y la posibilidad de prenderlo. ¿Lo pueden acusar de DUI?","o":["No, solo cuentan los carros en movimiento","No, si el motor está apagado","Sí, tener el control físico del vehículo cuenta","Solo si está en una autopista"],"h1":"La ley mira el control, no solo el movimiento.","h2":"En Washington, el DUI también cubre tener el control físico de un vehículo, aunque esté estacionado, si usted puede controlar el motor o su manejo.","p":"Correcto. El control físico cuenta, aunque esté estacionado."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-097","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, what does the Implied Consent Law mean?","o":["You must give a ride to anyone who asks","By driving, you agree to be tested if an officer suspects you are impaired","Your car may be searched at any time","You agree to pay any ticket without a hearing"],"h1":"It is about breath or blood tests.","h2":"Under Washington's Implied Consent Law, everyone who drives agrees to be tested if an officer suspects they are under the influence of alcohol or drugs.","p":"Right. Driving means you agree to be tested."},"es":{"q":"En Washington, ¿qué significa la Ley de Consentimiento Implícito?","o":["Debe llevar a cualquiera que le pida un aventón","Al manejar, usted acepta hacerse la prueba si un oficial sospecha que está bajo la influencia","Pueden revisar su carro en cualquier momento","Acepta pagar cualquier multa sin audiencia"],"h1":"Se trata de pruebas de aliento o de sangre.","h2":"Según la Ley de Consentimiento Implícito de Washington, toda persona que maneja acepta hacerse la prueba si un oficial sospecha que está bajo la influencia de alcohol o drogas.","p":"Correcto. Manejar significa aceptar la prueba."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-098","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, how long do alcohol- and drug-related driving offenses stay on your driving record?","o":["For life","For 1 year","For 3 years","Until you renew your license"],"h1":"They never go away.","h2":"In Washington, alcohol- and drug-related offenses stay on your driving record for life.","p":"Right. For life."},"es":{"q":"En Washington, ¿cuánto tiempo quedan en su historial de manejo los delitos relacionados con alcohol y drogas?","o":["De por vida","Por 1 año","Por 3 años","Hasta que renueve su licencia"],"h1":"Nunca se borran.","h2":"En Washington, los delitos relacionados con alcohol y drogas quedan en su historial de manejo de por vida.","p":"Correcto. De por vida."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-099","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, a DUI conviction can suspend your driving privileges for how long?","o":["90 days to 4 years","1 to 7 days","10 to 20 years","It never affects your license"],"h1":"The shortest is about three months.","h2":"In Washington, a DUI conviction can suspend your driving privileges for 90 days to 4 years.","p":"Right. 90 days to 4 years."},"es":{"q":"En Washington, ¿por cuánto tiempo puede una condena por DUI suspender sus privilegios de manejar?","o":["De 90 días a 4 años","De 1 a 7 días","De 10 a 20 años","Nunca afecta su licencia"],"h1":"Lo más corto son unos tres meses.","h2":"En Washington, una condena por DUI puede suspender sus privilegios de manejar de 90 días a 4 años.","p":"Correcto. De 90 días a 4 años."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-100","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, where may you carry an opened bottle of alcohol in your car?","o":["In the glove compartment","Under the driver's seat","In a cup holder if the cap is on","In the trunk or truck bed"],"h1":"It must be where no one in the car can reach it.","h2":"In Washington, open alcohol or cannabis may only be carried in the trunk or truck bed, not in any compartment the driver can reach.","p":"Right. In the trunk or truck bed."},"es":{"q":"En Washington, ¿dónde puede llevar en su carro una botella de alcohol abierta?","o":["En la guantera","Debajo del asiento del conductor","En el portavasos si tiene la tapa puesta","En la cajuela o en la caja de la camioneta"],"h1":"Debe ir donde nadie en el carro la alcance.","h2":"En Washington, el alcohol o cannabis abierto solo se puede llevar en la cajuela o en la caja de la camioneta, no en ningún compartimiento que el conductor alcance.","p":"Correcto. En la cajuela o en la caja de la camioneta."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-101","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, you are driving and your adult passenger opens a can of beer and drinks it. Is that legal?","o":["Yes, passengers may drink","Yes, if the passenger is over 21","No, it is a traffic infraction for anyone in the vehicle","Yes, if the car is stopped at a light"],"h1":"The open container law covers every person in the car.","h2":"In Washington, it is a traffic infraction for any person in a vehicle on the road to drink alcohol or consume cannabis, passengers included.","p":"Right. It is illegal for passengers too."},"es":{"q":"En Washington, usted maneja y su pasajero adulto abre una lata de cerveza y se la toma. ¿Es legal?","o":["Sí, los pasajeros pueden tomar","Sí, si el pasajero tiene más de 21 años","No, es una infracción para cualquier persona en el vehículo","Sí, si el carro está parado en un semáforo"],"h1":"La ley de envases abiertos cubre a todas las personas en el carro.","h2":"En Washington, es una infracción que cualquier persona en un vehículo en la vía tome alcohol o consuma cannabis, incluidos los pasajeros.","p":"Correcto. También es ilegal para los pasajeros."},"ref":{"doc":"WA","page":"§1.15"}},{"id":"wa-102","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, a driver 21 or older takes a breath test that shows 0.08 or more. It is a first incident in seven years. How long is the license suspended by the Department of Licensing?","o":["7 days","90 days","2 years","10 years"],"h1":"It is about three months.","h2":"In Washington, a first test result of 0.08 or more within seven years brings a 90-day license suspension, unless the person is in a 24/7 sobriety program.","p":"Right. 90 days."},"es":{"q":"En Washington, un conductor de 21 años o más hace una prueba de aliento que marca 0.08 o más. Es el primer incidente en siete años. ¿Por cuánto tiempo le suspende la licencia el Departamento de Licencias?","o":["7 días","90 días","2 años","10 años"],"h1":"Son unos tres meses.","h2":"En Washington, un primer resultado de 0.08 o más en siete años trae una suspensión de 90 días, salvo que la persona esté en un programa de sobriedad 24/7.","p":"Correcto. 90 días."},"ref":{"doc":"WA","page":null}},{"id":"wa-103","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, what is the shortest jail term for a first DUI with a blood alcohol level under 0.15?","o":["No jail is possible","24 hours in a row","30 days","1 year"],"h1":"It is one full day.","h2":"In Washington, a first DUI with an alcohol level under 0.15 carries at least 24 consecutive hours in jail, though a court may order electronic home monitoring or a sobriety program instead.","p":"Right. At least 24 hours in a row."},"es":{"q":"En Washington, ¿cuál es la pena de cárcel más corta para un primer DUI con nivel de alcohol menor de 0.15?","o":["No puede haber cárcel","24 horas seguidas","30 días","1 año"],"h1":"Es un día completo.","h2":"En Washington, un primer DUI con nivel de alcohol menor de 0.15 tiene por lo menos 24 horas seguidas de cárcel, aunque un juez puede ordenar monitoreo electrónico en casa o un programa de sobriedad en su lugar.","p":"Correcto. Por lo menos 24 horas seguidas."},"ref":{"doc":"WA","page":null}},{"id":"wa-104","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, what is the lowest fine for a first DUI with a blood alcohol level under 0.15?","o":["$350","$50","$1,000","$10,000"],"h1":"It is a few hundred dollars.","h2":"In Washington, a first DUI with an alcohol level under 0.15 carries a fine of at least $350 and up to $5,000.","p":"Right. At least $350."},"es":{"q":"En Washington, ¿cuál es la multa más baja para un primer DUI con nivel de alcohol menor de 0.15?","o":["$350","$50","$1,000","$10,000"],"h1":"Son unos cientos de dólares.","h2":"En Washington, un primer DUI con nivel de alcohol menor de 0.15 tiene una multa de por lo menos $350 y hasta $5,000.","p":"Correcto. Por lo menos $350."},"ref":{"doc":"WA","page":null}},{"id":"wa-105","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, at what blood alcohol level do the penalties for a first DUI get tougher?","o":["0.05 or more","0.10 or more","0.30 or more","0.15 or more"],"h1":"It is almost twice the legal limit for adults.","h2":"In Washington, a first DUI with an alcohol level of 0.15 or more brings tougher penalties, such as at least 48 hours in jail and a $500 minimum fine.","p":"Right. 0.15 or more."},"es":{"q":"En Washington, ¿a partir de qué nivel de alcohol en la sangre se vuelven más duras las penas de un primer DUI?","o":["0.05 o más","0.10 o más","0.30 o más","0.15 o más"],"h1":"Es casi el doble del límite legal para adultos.","h2":"En Washington, un primer DUI con nivel de alcohol de 0.15 o más trae penas más duras, como por lo menos 48 horas de cárcel y una multa mínima de $500.","p":"Correcto. 0.15 o más."},"ref":{"doc":"WA","page":null}},{"id":"wa-106","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, recreational cannabis is legal for adults 21 and older. When is it legal to drive after using it?","o":["After one hour","Whenever you feel fine","Driving after using any cannabis is illegal for all ages","Only if you are over 21"],"h1":"The handbook says there is no safe amount.","h2":"In Washington, driving after consuming any cannabis is illegal for all ages, and there is no safe amount for driving.","p":"Right. It is illegal at any age."},"es":{"q":"En Washington, el cannabis recreativo es legal para adultos de 21 años o más. ¿Cuándo es legal manejar después de usarlo?","o":["Después de una hora","Cuando usted se sienta bien","Manejar después de consumir cualquier cannabis es ilegal a cualquier edad","Solo si tiene más de 21 años"],"h1":"El manual dice que no hay una cantidad segura.","h2":"En Washington, manejar después de consumir cualquier cannabis es ilegal a cualquier edad, y no hay una cantidad segura para manejar.","p":"Correcto. Es ilegal a cualquier edad."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-107","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, what kind of impairment is most common in fatal crashes?","o":["Alcohol alone","Caffeine","Polydrug use, mixing more than one drug","Cold medicine alone"],"h1":"It involves combining substances.","h2":"The Washington handbook says polydrug use, taking more than one kind of drug, is the most common impairment in fatal crashes.","p":"Right. Polydrug use."},"es":{"q":"En Washington, ¿qué tipo de impedimento es el más común en los choques mortales?","o":["Solo el alcohol","La cafeína","El uso de varias drogas a la vez (polidrogas)","Solo la medicina para el resfriado"],"h1":"Se trata de combinar sustancias.","h2":"El manual de Washington dice que el uso de varias drogas a la vez es el impedimento más común en los choques mortales.","p":"Correcto. El uso de varias drogas a la vez."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-108","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, you are driving alone and start to feel tired. What does the handbook suggest?","o":["Drink coffee and keep going","Pull off the road and take a 20-minute nap","Open the window and turn up the music","Drive faster to get home sooner"],"h1":"Rest is the real fix.","h2":"The Washington handbook says that if you start to feel tired while driving alone, pull off the road and take a 20-minute nap.","p":"Right. Pull off and take a 20-minute nap."},"es":{"q":"En Washington, usted maneja solo y empieza a sentirse cansado. ¿Qué sugiere el manual?","o":["Tomar café y seguir","Salirse del camino y tomar una siesta de 20 minutos","Abrir la ventana y subir la música","Manejar más rápido para llegar antes"],"h1":"Descansar es la solución real.","h2":"El manual de Washington dice que si empieza a sentirse cansado manejando solo, se salga del camino y tome una siesta de 20 minutos.","p":"Correcto. Salirse y tomar una siesta de 20 minutos."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-109","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, on a long trip, how often does the handbook suggest you stop for a break?","o":["About every 100 miles or 2 hours","Every 10 miles","Every 500 miles","Only when you need gas"],"h1":"Think of a couple of hours on the highway.","h2":"The Washington handbook suggests stopping about every 100 miles or 2 hours on long trips.","p":"Right. About every 100 miles or 2 hours."},"es":{"q":"En Washington, en un viaje largo, ¿cada cuánto sugiere el manual parar a descansar?","o":["Más o menos cada 100 millas o 2 horas","Cada 10 millas","Cada 500 millas","Solo cuando necesite gasolina"],"h1":"Piense en un par de horas en la carretera.","h2":"El manual de Washington sugiere parar más o menos cada 100 millas o 2 horas en viajes largos.","p":"Correcto. Más o menos cada 100 millas o 2 horas."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-110","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, how does the law treat aggressive driving and road rage?","o":["Both are only warnings","Both are legal if no one is hurt","Road rage is a parking violation","Aggressive driving is a traffic offense; road rage is a criminal offense"],"h1":"One of them involves violence.","h2":"In Washington, aggressive driving is a traffic offense, and road rage, which leads to violent behavior, is a criminal offense.","p":"Right. Road rage is a crime."},"es":{"q":"En Washington, ¿cómo trata la ley el manejo agresivo y la furia al volante (road rage)?","o":["Los dos son solo advertencias","Los dos son legales si nadie sale herido","La furia al volante es una infracción de estacionamiento","El manejo agresivo es una infracción de tránsito; la furia al volante es un delito"],"h1":"Uno de ellos incluye violencia.","h2":"En Washington, el manejo agresivo es una infracción de tránsito, y la furia al volante, que lleva a conductas violentas, es un delito.","p":"Correcto. La furia al volante es un delito."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-111","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, besides fines and jail, what can happen to people who take part in street racing?","o":["They get a free driving class","Nothing else","They get extra points on a reward card","Their vehicle can be impounded"],"h1":"Think about what happens to the car.","h2":"In Washington, people who take part in street racing can face fines, jail time, and having their vehicle impounded.","p":"Right. Their vehicle can be impounded."},"es":{"q":"En Washington, además de multas y cárcel, ¿qué les puede pasar a quienes participan en carreras callejeras?","o":["Reciben una clase de manejo gratis","Nada más","Reciben puntos extra en una tarjeta de premios","Les pueden confiscar el vehículo"],"h1":"Piense en lo que le pasa al carro.","h2":"En Washington, quienes participan en carreras callejeras pueden recibir multas, cárcel y la confiscación de su vehículo.","p":"Correcto. Les pueden confiscar el vehículo."},"ref":{"doc":"WA","page":"§3.1"}},{"id":"wa-112","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, may you drive wearing earbuds or headphones in both ears?","o":["Yes, if the music is low","Yes, on freeways only","No, but a hands-free device in one ear may be allowed","Yes, if they cancel noise"],"h1":"You must be able to hear sirens and horns.","h2":"In Washington, it is illegal to drive wearing earbuds, headphones, or headsets that play sound or cancel noise, though a hands-free device in one ear may be allowed.","p":"Right. Not in both ears."},"es":{"q":"En Washington, ¿puede manejar con audífonos en los dos oídos?","o":["Sí, si la música está baja","Sí, solo en autopistas","No, pero se puede permitir un aparato manos libres en un oído","Sí, si cancelan el ruido"],"h1":"Debe poder oír sirenas y bocinas.","h2":"En Washington, es ilegal manejar con audífonos que reproducen sonido o cancelan el ruido, aunque se puede permitir un aparato manos libres en un oído.","p":"Correcto. No en los dos oídos."},"ref":{"doc":"WA","page":"§3.0"}},{"id":"wa-113","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, you get a second ticket for using a handheld phone while driving. What can happen to the fine?","o":["It is cut in half","It can be doubled","It stays the same","It is dropped"],"h1":"Repeat offenses cost more.","h2":"In Washington, fines for the distracted driving law can be doubled after your first violation.","p":"Right. The fine can be doubled."},"es":{"q":"En Washington, usted recibe una segunda multa por usar el teléfono en la mano mientras maneja. ¿Qué puede pasar con la multa?","o":["Se reduce a la mitad","Puede ser el doble","Queda igual","Se cancela"],"h1":"Repetir la falta cuesta más.","h2":"En Washington, las multas por la ley de manejo distraído pueden ser el doble después de la primera infracción.","p":"Correcto. La multa puede ser el doble."},"ref":{"doc":"WA","page":"§3.4"}},{"id":"wa-114","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, when may you hold your phone in your hand while in your car?","o":["After you pull off the road and stop where you can safely stay","While stopped at a red light","While stuck in slow traffic","While driving under 25 mph"],"h1":"Being stopped in traffic still counts as driving.","h2":"Under Washington law, you may hold your phone once you have pulled off the active roadway and stopped where you can safely stay; being stopped in traffic or at a light still counts as driving.","p":"Right. Only after pulling off the road and stopping safely."},"es":{"q":"En Washington, ¿cuándo puede tener el teléfono en la mano dentro de su carro?","o":["Después de salirse del camino y parar donde pueda quedarse con seguridad","Mientras está parado en un semáforo en rojo","Mientras está en tráfico lento","Mientras maneja a menos de 25 mph"],"h1":"Estar parado en el tráfico todavía cuenta como manejar.","h2":"Según la ley de Washington, puede tener el teléfono en la mano cuando se ha salido de la vía activa y ha parado donde puede quedarse con seguridad; estar parado en el tráfico o en un semáforo todavía cuenta como manejar.","p":"Correcto. Solo después de salirse y parar con seguridad."},"ref":{"doc":"WA","page":null}},{"id":"wa-115","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, an officer stops you for speeding and sees you were also eating in a way that made you drive unsafely. What extra base penalty can you get for driving dangerously distracted?","o":["$30","$300","$1,000","None; eating is always allowed"],"h1":"It is a small extra amount added to another ticket.","h2":"In Washington, driving dangerously distracted carries a $30 base penalty, and it can only be given when you are stopped for another traffic violation.","p":"Right. A $30 base penalty."},"es":{"q":"En Washington, un oficial lo para por exceso de velocidad y ve que usted también comía de una forma que lo hacía manejar sin seguridad. ¿Qué multa base extra puede recibir por manejar peligrosamente distraído?","o":["$30","$300","$1,000","Ninguna; comer siempre está permitido"],"h1":"Es una cantidad pequeña que se suma a otra multa.","h2":"En Washington, manejar peligrosamente distraído tiene una multa base de $30, y solo se puede dar cuando lo paran por otra infracción de tránsito.","p":"Correcto. Una multa base de $30."},"ref":{"doc":"WA","page":null}},{"id":"wa-116","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, what does the handbook say about wearing sunglasses or tinted lenses at night?","o":["Wear them to cut headlight glare","Wear them only on freeways","Wear them if you have a passenger","Do not wear them; they reduce your vision"],"h1":"Night driving needs all the light you can get.","h2":"The Washington handbook says not to wear sunglasses or tinted lenses when driving at night or on overcast days, because they reduce your vision.","p":"Right. Do not wear them at night."},"es":{"q":"En Washington, ¿qué dice el manual sobre usar lentes de sol o lentes con color de noche?","o":["Úselos para reducir el reflejo de los faros","Úselos solo en autopistas","Úselos si lleva un pasajero","No los use; reducen su visión"],"h1":"De noche se necesita toda la luz posible.","h2":"El manual de Washington dice que no use lentes de sol ni lentes con color de noche o en días nublados, porque reducen su visión.","p":"Correcto. No los use de noche."},"ref":{"doc":"WA","page":"§5.6"}},{"id":"wa-117","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, the Clean Car Law requires vehicles made in what year and later to meet strict clean air standards before they can be registered or sold?","o":["1980","1995","2009","2025"],"h1":"It is late in the 2000s.","h2":"Washington's Clean Car Law requires vehicles made in 2009 and later to meet strict clean air standards before they can be registered, licensed, or sold.","p":"Right. 2009 and later."},"es":{"q":"En Washington, la Ley de Carros Limpios exige que los vehículos fabricados desde qué año cumplan normas estrictas de aire limpio antes de registrarse o venderse?","o":["1980","1995","2009","2025"],"h1":"Es a finales de los años 2000.","h2":"La Ley de Carros Limpios de Washington exige que los vehículos fabricados en 2009 o después cumplan normas estrictas de aire limpio antes de registrarse, obtener placas o venderse.","p":"Correcto. Desde 2009."},"ref":{"doc":"WA","page":"§3.6"}},{"id":"wa-118","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, a person dumps more than one cubic foot of trash from a car onto a road. What is it under state law?","o":["A warning only","A misdemeanor, a crime","Legal if it is paper","A parking ticket"],"h1":"Larger amounts of litter are treated more seriously.","h2":"Under Washington law, littering more than one cubic foot is a misdemeanor, while one cubic foot or less is a civil infraction.","p":"Right. It is a misdemeanor."},"es":{"q":"En Washington, una persona tira desde un carro más de un pie cúbico de basura en la vía. ¿Qué es según la ley estatal?","o":["Solo una advertencia","Un delito menor (misdemeanor)","Legal si es papel","Una multa de estacionamiento"],"h1":"Las cantidades grandes de basura se tratan con más seriedad.","h2":"Según la ley de Washington, tirar más de un pie cúbico de basura es un delito menor (misdemeanor), y un pie cúbico o menos es una infracción civil.","p":"Correcto. Es un delito menor."},"ref":{"doc":"WA","page":null}},{"id":"wa-119","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, the handbook teaches the OODA Loop for problem solving on the road. What do the letters stand for?","o":["Open, Overtake, Drive, Arrive","Observe, Orient, Decide, Act","Order, Obey, Direct, Alert","Over, Out, Down, Away"],"h1":"The first step is to notice what changed.","h2":"In the Washington handbook, the OODA Loop stands for Observe, Orient, Decide, and Act.","p":"Right. Observe, Orient, Decide, Act."},"es":{"q":"En Washington, el manual enseña el ciclo OODA para resolver problemas en la vía. ¿Qué significan las letras?","o":["Abrir, Adelantar, Manejar, Llegar","Observar, Orientarse, Decidir, Actuar","Ordenar, Obedecer, Dirigir, Alertar","Encima, Afuera, Abajo, Lejos"],"h1":"El primer paso es notar qué cambió.","h2":"En el manual de Washington, el ciclo OODA significa Observar (Observe), Orientarse (Orient), Decidir (Decide) y Actuar (Act).","p":"Correcto. Observar, Orientarse, Decidir, Actuar."},"ref":{"doc":"WA","page":"§3.3"}},{"id":"wa-120","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, the handbook gives a routine for handling hazards. Which list is in the right order?","o":["Plan, Communicate, Check, Execute, Evaluate","Brake, Honk, Swerve, Stop, Leave","Check, Plan, Evaluate, Communicate, Execute","Execute, Evaluate, Plan, Check, Communicate"],"h1":"You think first and look back at the end.","h2":"The Washington handbook's hazard routine is Plan, Communicate, Check, Execute, and Evaluate.","p":"Right. Plan, Communicate, Check, Execute, Evaluate."},"es":{"q":"En Washington, el manual da una rutina para manejar peligros. ¿Qué lista está en el orden correcto?","o":["Planear, Comunicar, Revisar, Ejecutar, Evaluar","Frenar, Pitar, Desviarse, Parar, Irse","Revisar, Planear, Evaluar, Comunicar, Ejecutar","Ejecutar, Evaluar, Planear, Revisar, Comunicar"],"h1":"Primero se piensa y al final se repasa.","h2":"La rutina de peligros del manual de Washington es Planear, Comunicar, Revisar, Ejecutar y Evaluar.","p":"Correcto. Planear, Comunicar, Revisar, Ejecutar, Evaluar."},"ref":{"doc":"WA","page":"§5.0"}},{"id":"wa-121","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, the handbook describes how a vehicle's weight shifts. What is the side-to-side tilt of a car in a turn called?","o":["Pitch","Yaw","Drift","Roll"],"h1":"Think of a hand rotating from the little finger to the thumb.","h2":"In the Washington handbook, the side-to-side motion of a vehicle, such as leaning in a turn, is called roll.","p":"Right. It is called roll."},"es":{"q":"En Washington, el manual describe cómo se mueve el peso del vehículo. ¿Cómo se llama la inclinación de lado a lado de un carro en una curva?","o":["Pitch (cabeceo)","Yaw (giro)","Drift (derrape)","Roll (balanceo lateral)"],"h1":"Piense en una mano que gira del dedo meñique al pulgar.","h2":"En el manual de Washington, el movimiento de lado a lado del vehículo, como inclinarse en una curva, se llama roll (balanceo lateral).","p":"Correcto. Se llama roll."},"ref":{"doc":"WA","page":"§2.10"}},{"id":"wa-122","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, the handbook suggests an exercise to judge distance. How far ahead should you pick a marker, like a sign or pole?","o":["About 1 second ahead","About 2 minutes ahead","About 15 seconds ahead","Right next to your car"],"h1":"It is a quarter of a minute.","h2":"The Washington handbook suggests picking a marker that you think is 15 seconds ahead and counting until you reach it.","p":"Right. About 15 seconds ahead."},"es":{"q":"En Washington, el manual sugiere un ejercicio para calcular distancias. ¿Qué tan adelante debe escoger un punto, como un letrero o un poste?","o":["Solo 1 segundo adelante","Unos 2 minutos adelante","Unos 15 segundos adelante","Justo al lado de su carro"],"h1":"Es un cuarto de minuto.","h2":"El manual de Washington sugiere escoger un punto que usted crea que está 15 segundos adelante y contar hasta llegar a él.","p":"Correcto. Unos 15 segundos adelante."},"ref":{"doc":"WA","page":"§5.4"}},{"id":"wa-123","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, at night you should drive at a speed that lets you stop within the glow of your headlights. About how far is that, usually?","o":["40 feet","1,000 feet","400 feet","One mile"],"h1":"It is less than the 500-foot dimming distance.","h2":"The Washington handbook says to drive at night at a speed that lets you stop within the glow of your headlights, usually about 400 feet.","p":"Right. Usually about 400 feet."},"es":{"q":"En Washington, de noche debe manejar a una velocidad que le permita parar dentro de la luz de sus faros. ¿Más o menos qué distancia es, normalmente?","o":["40 pies","1,000 pies","400 pies","Una milla"],"h1":"Es menos que los 500 pies para bajar las luces.","h2":"El manual de Washington dice que de noche maneje a una velocidad que le permita parar dentro de la luz de sus faros, normalmente unos 400 pies.","p":"Correcto. Normalmente unos 400 pies."},"ref":{"doc":"WA","page":"§5.6"}},{"id":"wa-124","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, where should you keep your vehicle's title (certificate of ownership)?","o":["In the glove compartment","In a safe place, but not in the vehicle","Taped to the windshield","With your insurance company"],"h1":"If the car is stolen, the title should not go with it.","h2":"In Washington, keep your vehicle title in a safe place, but not in the vehicle.","p":"Right. Somewhere safe, not in the car."},"es":{"q":"En Washington, ¿dónde debe guardar el título (certificado de propiedad) de su vehículo?","o":["En la guantera","En un lugar seguro, pero no dentro del vehículo","Pegado al parabrisas","Con su compañía de seguros"],"h1":"Si se roban el carro, el título no debe irse con él.","h2":"En Washington, guarde el título de su vehículo en un lugar seguro, pero no dentro del vehículo.","p":"Correcto. En un lugar seguro, no en el carro."},"ref":{"doc":"WA","page":"§2.0"}},{"id":"wa-125","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, you just moved here with your car. How long do you have to register it?","o":["30 days","7 days","6 months","1 year"],"h1":"It matches the time new adult residents have to get a license.","h2":"In Washington, new residents have 30 days to register their vehicles.","p":"Right. 30 days."},"es":{"q":"En Washington, usted acaba de mudarse aquí con su carro. ¿Cuánto tiempo tiene para registrarlo?","o":["30 días","7 días","6 meses","1 año"],"h1":"Es el mismo tiempo que tienen los nuevos residentes adultos para sacar la licencia.","h2":"En Washington, los nuevos residentes tienen 30 días para registrar sus vehículos.","p":"Correcto. 30 días."},"ref":{"doc":"WA","page":"§2.0"}},{"id":"wa-126","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you get a new registration when you renew your tabs. What should you do with it?","o":["Mail it back to the state","Keep it at home in a drawer","Throw it away; only the tabs matter","Sign it and keep it in your vehicle"],"h1":"An officer may ask for it during a stop.","h2":"In Washington, sign each new vehicle registration and keep it in your vehicle.","p":"Right. Sign it and keep it in the car."},"es":{"q":"En Washington, usted recibe un registro nuevo cuando renueva sus calcomanías (tabs). ¿Qué debe hacer con él?","o":["Enviarlo de vuelta al estado","Guardarlo en un cajón en su casa","Tirarlo; solo importan las calcomanías","Firmarlo y guardarlo en su vehículo"],"h1":"Un oficial puede pedirlo durante una parada.","h2":"En Washington, firme cada registro nuevo del vehículo y guárdelo en su vehículo.","p":"Correcto. Fírmelo y guárdelo en el carro."},"ref":{"doc":"WA","page":"§2.0"}},{"id":"wa-127","scope":"WA","cat":"licensing","sign":null,"c":3,"en":{"q":"In Washington, you change the address on your driver license. What happens to the address for your vehicle?","o":["It changes automatically","Your car registration is canceled","Your insurance updates it for you","It does not change; you must update it separately"],"h1":"Licenses and vehicles are separate records.","h2":"In Washington, changing the address on your driver license does not change your vehicle address; you must update it separately online or at a vehicle licensing office.","p":"Right. You update the vehicle address separately."},"es":{"q":"En Washington, usted cambia la dirección de su licencia de manejo. ¿Qué pasa con la dirección de su vehículo?","o":["Cambia sola","Le cancelan el registro del carro","Su seguro la actualiza por usted","No cambia; debe actualizarla por separado"],"h1":"Las licencias y los vehículos son registros distintos.","h2":"En Washington, cambiar la dirección de su licencia no cambia la dirección de su vehículo; debe actualizarla por separado en línea o en una oficina de vehículos.","p":"Correcto. La dirección del vehículo se actualiza por separado."},"ref":{"doc":"WA","page":"§2.0"}},{"id":"wa-128","scope":"WA","cat":"licensing","sign":null,"c":2,"en":{"q":"In Washington, you sell your car to another person. Within how many days must you file a Vehicle Report of Sale?","o":["30 days","60 days","5 days","1 year"],"h1":"It is less than a week.","h2":"In Washington, if you sell, trade, or give away your vehicle, you must file a Vehicle Report of Sale within 5 days.","p":"Right. Within 5 days."},"es":{"q":"En Washington, usted le vende su carro a otra persona. ¿En cuántos días debe presentar el Reporte de Venta del Vehículo?","o":["30 días","60 días","5 días","1 año"],"h1":"Es menos de una semana.","h2":"En Washington, si vende, cambia o regala su vehículo, debe presentar el Reporte de Venta del Vehículo dentro de 5 días.","p":"Correcto. Dentro de 5 días."},"ref":{"doc":"WA","page":"§2.1"}},{"id":"wa-129","scope":"WA","cat":"licensing","sign":null,"c":1,"en":{"q":"In Washington, you buy a used car from a private seller. How soon must you transfer the title to avoid penalty fees?","o":["Within 1 year","Within 15 days","Within 90 days","There is no deadline"],"h1":"It is about two weeks.","h2":"In Washington, the buyer must bring the signed title to a licensing office to transfer ownership within 15 days to avoid penalty fees.","p":"Right. Within 15 days."},"es":{"q":"En Washington, usted compra un carro usado a un vendedor particular. ¿En cuánto tiempo debe transferir el título para evitar multas?","o":["Dentro de 1 año","Dentro de 15 días","Dentro de 90 días","No hay plazo"],"h1":"Son unas dos semanas.","h2":"En Washington, el comprador debe llevar el título firmado a una oficina de licencias para transferir la propiedad dentro de 15 días y evitar multas.","p":"Correcto. Dentro de 15 días."},"ref":{"doc":"WA","page":"§2.1"}},{"id":"wa-130","scope":"WA","cat":"licensing","sign":null,"c":0,"en":{"q":"In Washington, where must license plates be shown on a car registered here?","o":["On both the front and the rear","Only on the rear","Only on the front","Inside the back window"],"h1":"Washington uses two plates.","h2":"In Washington, license plates must be clearly shown on both the front and rear of the vehicle, and a frame may not cover the letters, numbers, or tabs.","p":"Right. Front and rear."},"es":{"q":"En Washington, ¿dónde deben estar las placas de un carro registrado aquí?","o":["Adelante y atrás","Solo atrás","Solo adelante","Dentro del vidrio trasero"],"h1":"Washington usa dos placas.","h2":"En Washington, las placas deben verse claramente adelante y atrás del vehículo, y un marco no puede tapar las letras, los números ni las calcomanías.","p":"Correcto. Adelante y atrás."},"ref":{"doc":"WA","page":"§2.2"}},{"id":"wa-131","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, what is the least tire tread depth the handbook allows?","o":["2/32 of an inch","1/2 of an inch","1/64 of an inch","1 inch"],"h1":"It is a very small fraction of an inch.","h2":"The Washington handbook says tire tread should not be less than 2/32 of an inch.","p":"Right. 2/32 of an inch."},"es":{"q":"En Washington, ¿cuál es la profundidad mínima del dibujo de las llantas que permite el manual?","o":["2/32 de pulgada","1/2 pulgada","1/64 de pulgada","1 pulgada"],"h1":"Es una fracción muy pequeña de pulgada.","h2":"El manual de Washington dice que el dibujo de las llantas no debe ser menor de 2/32 de pulgada.","p":"Correcto. 2/32 de pulgada."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-132","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, your car has daytime running lights. Why are they not enough at dusk?","o":["They are too bright for other drivers","They only work on freeways","They make your brake lights stop working","They are not as bright as headlights and do not turn on your taillights"],"h1":"Think about the back of your car.","h2":"In Washington, daytime running lights are not as bright as headlights and do not turn on your taillights, so turn on your headlights when needed.","p":"Right. They are dimmer and do not light your taillights."},"es":{"q":"En Washington, su carro tiene luces de circulación diurna. ¿Por qué no bastan al atardecer?","o":["Son demasiado brillantes para otros conductores","Solo funcionan en autopistas","Hacen que sus luces de freno dejen de funcionar","No son tan brillantes como los faros y no prenden las luces traseras"],"h1":"Piense en la parte de atrás de su carro.","h2":"En Washington, las luces de circulación diurna no son tan brillantes como los faros y no prenden las luces traseras, así que prenda sus faros cuando haga falta.","p":"Correcto. Son más débiles y no prenden las luces traseras."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-133","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, besides the hours around sunset and sunrise, when must your headlights be on?","o":["Only when it snows","Only on freeways","Whenever you cannot clearly see people and vehicles 1,000 feet ahead","Whenever you have passengers"],"h1":"Think of rain, fog, or smoke cutting how far you can see.","h2":"Washington law also requires headlights whenever, because of poor light or weather, people and vehicles are not clearly visible 1,000 feet ahead.","p":"Right. When you cannot see clearly 1,000 feet ahead."},"es":{"q":"En Washington, además de las horas cerca del atardecer y el amanecer, ¿cuándo debe tener los faros prendidos?","o":["Solo cuando nieva","Solo en autopistas","Siempre que no pueda ver con claridad personas y vehículos a 1,000 pies","Siempre que lleve pasajeros"],"h1":"Piense en lluvia, neblina o humo que reducen lo que puede ver.","h2":"La ley de Washington también exige los faros siempre que, por poca luz o mal tiempo, las personas y los vehículos no se vean con claridad a 1,000 pies.","p":"Correcto. Cuando no pueda ver con claridad a 1,000 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-134","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, from how far away must your red brake lights be clearly visible?","o":["10 feet","100 feet","25 feet","1 mile"],"h1":"It is the same distance as the turn signal rule.","h2":"In Washington, your brake lights are red and must be clearly visible from 100 feet away.","p":"Right. 100 feet."},"es":{"q":"En Washington, ¿desde qué distancia deben verse claramente sus luces rojas de freno?","o":["10 pies","100 pies","25 pies","1 milla"],"h1":"Es la misma distancia que la regla de la direccional.","h2":"En Washington, sus luces de freno son rojas y deben verse claramente desde 100 pies.","p":"Correcto. 100 pies."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-135","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, your brake lights are not working. What should you do when you slow down or stop?","o":["Flash your high beams","Use the hand signal: left arm out, fingers pointing down","Honk twice","Turn on your right turn signal"],"h1":"Your arm can do the job of the lights.","h2":"In Washington, if your brake lights are not working, use the stop hand signal: put your left arm out the window with your fingers pointing to the ground.","p":"Right. Left arm out, fingers down."},"es":{"q":"En Washington, sus luces de freno no funcionan. ¿Qué debe hacer cuando reduce la velocidad o para?","o":["Hacer cambio de luces altas","Usar la señal de mano: brazo izquierdo afuera, dedos hacia abajo","Pitar dos veces","Prender la direccional derecha"],"h1":"Su brazo puede hacer el trabajo de las luces.","h2":"En Washington, si sus luces de freno no funcionan, use la señal de mano para parar: saque el brazo izquierdo por la ventana con los dedos apuntando al suelo.","p":"Correcto. Brazo izquierdo afuera, dedos hacia abajo."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-136","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, how far should your chest be from the steering wheel?","o":["At least 10 inches","At least 2 inches","Exactly 3 feet","As close as possible"],"h1":"You need room for the airbag.","h2":"In Washington, your chest should be at least 10 inches from the steering wheel to leave space for the airbag.","p":"Right. At least 10 inches."},"es":{"q":"En Washington, ¿a qué distancia del volante debe estar su pecho?","o":["Por lo menos 10 pulgadas","Por lo menos 2 pulgadas","Exactamente 3 pies","Lo más cerca posible"],"h1":"Necesita espacio para la bolsa de aire.","h2":"En Washington, su pecho debe estar por lo menos a 10 pulgadas del volante para dejar espacio a la bolsa de aire.","p":"Correcto. Por lo menos 10 pulgadas."},"ref":{"doc":"WA","page":"§2.5"}},{"id":"wa-137","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, a child is 3 years old and has outgrown the rear-facing seat. What must the child ride in?","o":["A regular seat belt only","A booster seat with no harness","A parent's lap","A car seat with a harness"],"h1":"Ages 2 to 4 still need straps that hold the body.","h2":"In Washington, children ages 2 to 4 must ride in a car seat with a harness, rear-facing or forward-facing.","p":"Right. A car seat with a harness."},"es":{"q":"En Washington, un niño tiene 3 años y ya no cabe en el asiento mirando hacia atrás. ¿En qué debe viajar?","o":["Solo con el cinturón normal","En un asiento elevado (booster) sin arnés","En las piernas de un padre","En un asiento de seguridad con arnés"],"h1":"De 2 a 4 años todavía necesitan correas que sujeten el cuerpo.","h2":"En Washington, los niños de 2 a 4 años deben viajar en un asiento de seguridad con arnés, mirando hacia atrás o hacia adelante.","p":"Correcto. En un asiento con arnés."},"ref":{"doc":"WA","page":"§2.6"}},{"id":"wa-138","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, a child over 4 should use a booster seat until reaching what height, so the seat belt fits?","o":["3 feet","5 feet 6 inches","4 feet 9 inches","6 feet"],"h1":"It is just under five feet.","h2":"In Washington, children 4 and older ride in a car or booster seat until the seat belt fits, usually at 4 feet 9 inches tall.","p":"Right. 4 feet 9 inches."},"es":{"q":"En Washington, un niño mayor de 4 años debe usar asiento elevado (booster) hasta alcanzar qué estatura, para que el cinturón le quede bien?","o":["3 pies","5 pies 6 pulgadas","4 pies 9 pulgadas","6 pies"],"h1":"Es un poco menos de cinco pies.","h2":"En Washington, los niños de 4 años o más viajan en asiento de seguridad o booster hasta que el cinturón les quede bien, normalmente al medir 4 pies 9 pulgadas.","p":"Correcto. 4 pies 9 pulgadas."},"ref":{"doc":"WA","page":"§2.6"}},{"id":"wa-139","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, a 14-year-old passenger is not wearing a seat belt. Who is responsible under the law?","o":["Only the passenger","The car owner, even if absent","The driver","No one; belts are optional under 16"],"h1":"The law speaks to the person operating the vehicle.","h2":"Washington law says no one may drive a motor vehicle unless every passenger under 16 is wearing a seat belt or is in an approved child restraint, so the driver is responsible.","p":"Right. The driver is responsible."},"es":{"q":"En Washington, un pasajero de 14 años no lleva el cinturón puesto. ¿Quién es responsable según la ley?","o":["Solo el pasajero","El dueño del carro, aunque no esté","El conductor","Nadie; el cinturón es opcional para menores de 16"],"h1":"La ley se dirige a la persona que maneja el vehículo.","h2":"La ley de Washington dice que nadie puede manejar un vehículo a menos que cada pasajero menor de 16 años lleve el cinturón o vaya en un asiento infantil aprobado, así que el conductor es responsable.","p":"Correcto. El conductor es responsable."},"ref":{"doc":"WA","page":null}},{"id":"wa-140","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, when does the handbook recommend one hand at the 12 o'clock position on the steering wheel?","o":["When driving on the freeway","Only when backing up","When turning left","Whenever you are tired"],"h1":"You turn your body to look behind you.","h2":"The Washington handbook recommends the 12 o'clock one-hand position only when backing a vehicle.","p":"Right. Only when backing up."},"es":{"q":"En Washington, ¿cuándo recomienda el manual poner una mano en la posición de las 12 en el volante?","o":["Al manejar en la autopista","Solo al manejar en reversa","Al dar vuelta a la izquierda","Cuando está cansado"],"h1":"Usted gira el cuerpo para mirar hacia atrás.","h2":"El manual de Washington recomienda la posición de una mano a las 12 solo al manejar en reversa.","p":"Correcto. Solo en reversa."},"ref":{"doc":"WA","page":"§2.7"}},{"id":"wa-141","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, when does the handbook say to use hand-over-hand steering?","o":["When turning at low speeds, parking, or recovering from a skid","When driving straight on the freeway","When changing lanes at high speed","Never; it is not allowed"],"h1":"It is for big turns of the wheel at slow speeds.","h2":"The Washington handbook says to use hand-over-hand steering for low-speed turns, limited visibility, intersections, parking, and recovering from a skid.","p":"Right. Low-speed turns, parking, and skids."},"es":{"q":"En Washington, ¿cuándo dice el manual que use la técnica de mano sobre mano en el volante?","o":["Al dar vueltas a baja velocidad, al estacionarse o al recuperarse de un derrape","Al manejar derecho en la autopista","Al cambiar de carril a alta velocidad","Nunca; no está permitido"],"h1":"Es para girar mucho el volante a poca velocidad.","h2":"El manual de Washington dice que use la técnica de mano sobre mano en vueltas a baja velocidad, con poca visibilidad, en intersecciones, al estacionarse y al recuperarse de un derrape.","p":"Correcto. Vueltas lentas, estacionarse y derrapes."},"ref":{"doc":"WA","page":"§2.7"}},{"id":"wa-142","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, what does an antilock braking system (ABS) do in an emergency stop?","o":["It makes the car stop in half the distance","It turns on your hazard lights","It lets you brake without using the pedal","It lets you keep steering, but it does not shorten your stopping distance"],"h1":"Its main benefit is control, not distance.","h2":"In Washington, the handbook explains that ABS lets you steer during emergency braking, but it does not shorten your stopping distance.","p":"Right. You can steer, but it does not stop you sooner."},"es":{"q":"En Washington, ¿qué hace el sistema de frenos antibloqueo (ABS) en una parada de emergencia?","o":["Hace que el carro pare en la mitad de distancia","Prende las luces intermitentes","Le permite frenar sin usar el pedal","Le permite seguir dirigiendo, pero no acorta la distancia para parar"],"h1":"Su ventaja principal es el control, no la distancia.","h2":"En Washington, el manual explica que el ABS le permite dirigir el carro al frenar de emergencia, pero no acorta la distancia para parar.","p":"Correcto. Puede dirigir, pero no para antes."},"ref":{"doc":"WA","page":"§2.8"}},{"id":"wa-143","scope":"WA","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Washington, window tint film on side and rear windows must let in at least what percent of light?","o":["5 percent","50 percent","90 percent","24 percent"],"h1":"It is about one quarter.","h2":"Washington law requires window tint film on windows other than the windshield to have a light transmission of 24 percent or more.","p":"Right. At least 24 percent."},"es":{"q":"En Washington, ¿qué porcentaje de luz, como mínimo, debe dejar pasar el polarizado en los vidrios laterales y trasero?","o":["5 por ciento","50 por ciento","90 por ciento","24 por ciento"],"h1":"Es como una cuarta parte.","h2":"La ley de Washington exige que el polarizado en los vidrios que no son el parabrisas deje pasar 24 por ciento de la luz o más.","p":"Correcto. Por lo menos 24 por ciento."},"ref":{"doc":"WA","page":null}},{"id":"wa-144","scope":"WA","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Washington, during which months may you use tires with metal studs, unless the state extends the season?","o":["All year","From June through August","From November 1 until April 1","Only in January"],"h1":"It is the winter season.","h2":"Washington law allows metal studded tires from November 1 until April 1; using them between April 1 and November 1 is unlawful unless the state extends the season.","p":"Right. November 1 until April 1."},"es":{"q":"En Washington, ¿en qué meses puede usar llantas con clavos de metal, salvo que el estado extienda la temporada?","o":["Todo el año","De junio a agosto","Del 1 de noviembre al 1 de abril","Solo en enero"],"h1":"Es la temporada de invierno.","h2":"La ley de Washington permite llantas con clavos de metal del 1 de noviembre al 1 de abril; usarlas entre el 1 de abril y el 1 de noviembre es ilegal, salvo que el estado extienda la temporada.","p":"Correcto. Del 1 de noviembre al 1 de abril."},"ref":{"doc":"WA","page":null}},{"id":"wa-145","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, your car horn must be loud enough to be heard from at least how far away?","o":["20 feet","200 feet","1,000 feet","One mile"],"h1":"It is less than a city block.","h2":"Washington law requires a car horn that can be heard under normal conditions from at least 200 feet.","p":"Right. 200 feet."},"es":{"q":"En Washington, la bocina de su carro debe oírse por lo menos desde qué distancia?","o":["20 pies","200 pies","1,000 pies","Una milla"],"h1":"Es menos que una cuadra.","h2":"La ley de Washington exige una bocina que se oiga en condiciones normales desde por lo menos 200 pies.","p":"Correcto. 200 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-146","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, who must wear a motorcycle helmet?","o":["Every rider and passenger","Only riders under 18","Only riders under 21","No one; helmets are optional"],"h1":"Washington has a universal helmet law.","h2":"In Washington, every person who operates or rides on a motorcycle on a public road must wear a motorcycle helmet with the strap fastened.","p":"Right. Every rider and passenger."},"es":{"q":"En Washington, ¿quién debe usar casco de motocicleta?","o":["Todo conductor y pasajero","Solo los menores de 18","Solo los menores de 21","Nadie; el casco es opcional"],"h1":"Washington exige el casco a todos.","h2":"En Washington, toda persona que maneje o viaje en una motocicleta en una vía pública debe usar casco de motocicleta con la correa abrochada.","p":"Correcto. Todo conductor y pasajero."},"ref":{"doc":"WA","page":null}},{"id":"wa-147","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, children under what age may not ride on a motorcycle?","o":["5","2","10","16"],"h1":"It is the age many children start kindergarten.","h2":"Washington law makes it unlawful to carry a child under the age of 5 on a motorcycle.","p":"Right. Under 5."},"es":{"q":"En Washington, ¿los niños menores de qué edad no pueden viajar en motocicleta?","o":["5","2","10","16"],"h1":"Es la edad en que muchos niños empiezan el kínder.","h2":"La ley de Washington prohíbe llevar en motocicleta a un niño menor de 5 años.","p":"Correcto. Menores de 5."},"ref":{"doc":"WA","page":null}},{"id":"wa-148","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, may a motorcyclist ride between lanes of traffic or between rows of cars?","o":["Yes, in slow traffic","Yes, on freeways only","Yes, if they go under 25 mph","No, it is illegal"],"h1":"Washington does not allow lane splitting.","h2":"Washington law says no one may ride a motorcycle between lanes of traffic or between rows of vehicles.","p":"Right. It is illegal."},"es":{"q":"En Washington, ¿puede un motociclista pasar entre carriles de tráfico o entre filas de carros?","o":["Sí, en tráfico lento","Sí, solo en autopistas","Sí, si va a menos de 25 mph","No, es ilegal"],"h1":"Washington no permite pasar entre carriles.","h2":"La ley de Washington dice que nadie puede manejar una motocicleta entre carriles de tráfico ni entre filas de vehículos.","p":"Correcto. Es ilegal."},"ref":{"doc":"WA","page":null}},{"id":"wa-149","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, a motorcycle is riding far to the right side of a wide lane. May you drive in the same lane beside it?","o":["Yes, if the lane is wide","Yes, if you honk first","No, a motorcycle is entitled to the whole lane","Yes, during the day"],"h1":"A motorcycle gets the same lane width as a car.","h2":"In Washington, never move into the same lane alongside a motorcycle, even if the lane is wide and the rider is far to one side.","p":"Right. The motorcycle gets the whole lane."},"es":{"q":"En Washington, una motocicleta va muy a la derecha de un carril ancho. ¿Puede usted manejar en el mismo carril a su lado?","o":["Sí, si el carril es ancho","Sí, si pita primero","No, la motocicleta tiene derecho a todo el carril","Sí, de día"],"h1":"Una motocicleta tiene derecho al mismo ancho que un carro.","h2":"En Washington, nunca se meta en el mismo carril al lado de una motocicleta, aunque el carril sea ancho y el motociclista vaya muy a un lado.","p":"Correcto. La motocicleta tiene todo el carril."},"ref":{"doc":"WA","page":"§4.5"}},{"id":"wa-150","scope":"WA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Washington, why might a motorcycle ahead slow down without showing a brake light?","o":["Motorcycles have no brake lights","The rider may slow down with the throttle instead of the brakes","The light only works at night","It means the rider is turning"],"h1":"Easing off the gas also slows a motorcycle.","h2":"In Washington, the handbook warns that motorcyclists may slow down using the throttle instead of the brakes, so no brake light shows.","p":"Right. They may slow with the throttle."},"es":{"q":"En Washington, ¿por qué una motocicleta adelante podría frenar sin que se vea la luz de freno?","o":["Las motocicletas no tienen luz de freno","El motociclista puede bajar la velocidad con el acelerador en vez de los frenos","La luz solo funciona de noche","Significa que va a dar vuelta"],"h1":"Soltar el acelerador también frena una motocicleta.","h2":"En Washington, el manual advierte que los motociclistas pueden bajar la velocidad con el acelerador en vez de los frenos, así que no se ve la luz de freno.","p":"Correcto. Pueden frenar con el acelerador."},"ref":{"doc":"WA","page":"§4.5"}},{"id":"wa-151","scope":"WA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Washington, a bicycle ridden in the dark must have a white front light visible from at least how far?","o":["50 feet","500 feet","100 feet","2 miles"],"h1":"It is the same as the high-beam dimming distance.","h2":"Washington law requires a bicycle used in the dark to have a white front lamp visible from at least 500 feet and a red rear reflector.","p":"Right. 500 feet."},"es":{"q":"En Washington, una bicicleta que se usa en la oscuridad debe tener una luz blanca adelante que se vea desde por lo menos qué distancia?","o":["50 pies","500 pies","100 pies","2 millas"],"h1":"Es la misma distancia para bajar las luces altas.","h2":"La ley de Washington exige que una bicicleta usada en la oscuridad tenga una luz blanca adelante visible desde por lo menos 500 pies y un reflector rojo atrás.","p":"Correcto. 500 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-152","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, a person rides a bicycle across the street in a crosswalk. How should you treat them?","o":["As a pedestrian; you must yield","As a car; whoever is first goes","You may go first because bikes must stop","Honk so they get out of the way"],"h1":"In the crosswalk, the rules for people walking apply.","h2":"In Washington, bicyclists in crosswalks are considered pedestrians, and you must yield to them in marked and unmarked crosswalks.","p":"Right. Treat them as pedestrians and yield."},"es":{"q":"En Washington, una persona cruza la calle en bicicleta por el cruce peatonal. ¿Cómo debe tratarla?","o":["Como peatón; usted debe ceder el paso","Como un carro; pasa quien llegue primero","Usted pasa primero porque las bicicletas deben parar","Pitar para que se quite"],"h1":"En el cruce peatonal se aplican las reglas de las personas a pie.","h2":"En Washington, los ciclistas en los cruces peatonales se consideran peatones, y usted debe cederles el paso en cruces marcados y no marcados.","p":"Correcto. Trátela como peatón y ceda el paso."},"ref":{"doc":"WA","page":"§4.6"}},{"id":"wa-153","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, when may you drive in a bicycle lane?","o":["Whenever traffic is slow","To pass a car on the right","Any time no bicycle is in sight","Only to turn, or to cross it to park near the curb"],"h1":"It is for bikes except for a short crossing.","h2":"In Washington, you may drive in a bicycle lane only when turning or crossing it to park near the curb.","p":"Right. Only to turn or to reach the curb."},"es":{"q":"En Washington, ¿cuándo puede manejar en un carril para bicicletas?","o":["Cuando el tráfico está lento","Para rebasar a un carro por la derecha","Siempre que no vea bicicletas","Solo para dar vuelta o cruzarlo para estacionarse junto a la acera"],"h1":"Es para bicicletas, salvo un cruce corto.","h2":"En Washington, solo puede manejar en un carril para bicicletas para dar vuelta o para cruzarlo y estacionarse junto a la acera.","p":"Correcto. Solo para dar vuelta o llegar a la acera."},"ref":{"doc":"WA","page":"§4.6"}},{"id":"wa-154","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, you are about to turn right and a bicyclist is riding ahead of you on the right. What should you do?","o":["Speed up and pass them just before the turn","Honk and turn in front of them","Stay behind the bicyclist and turn after they pass the intersection","Turn from the bike lane"],"h1":"Passing just before the turn can cut them off.","h2":"In Washington, do not pass a bicyclist just before a right turn; let the bicyclist clear the intersection before you turn.","p":"Right. Let the bicyclist go first."},"es":{"q":"En Washington, usted va a dar vuelta a la derecha y un ciclista va adelante a su derecha. ¿Qué debe hacer?","o":["Acelerar y rebasarlo justo antes de la vuelta","Pitar y dar vuelta frente a él","Quedarse detrás del ciclista y dar vuelta cuando pase la intersección","Dar vuelta desde el carril de bicicletas"],"h1":"Rebasarlo justo antes de la vuelta puede cerrarle el paso.","h2":"En Washington, no rebase a un ciclista justo antes de una vuelta a la derecha; deje que pase la intersección antes de dar vuelta.","p":"Correcto. Deje pasar primero al ciclista."},"ref":{"doc":"WA","page":"§4.6"}},{"id":"wa-155","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, the handbook suggests the \"Dutch Reach\" when you leave a parked car. What is it?","o":["Reaching back to grab your bag first","Opening the door quickly to get out fast","Opening the door with the hand farthest from it","Waving to cars behind you"],"h1":"It makes your body turn so you can see behind you.","h2":"The Dutch Reach means opening the car door with the hand farthest from it, which turns your body so you can see bicyclists coming.","p":"Right. Use the hand farthest from the door."},"es":{"q":"En Washington, el manual sugiere el \"Dutch Reach\" al bajarse de un carro estacionado. ¿Qué es?","o":["Buscar su bolsa atrás primero","Abrir la puerta rápido para bajarse pronto","Abrir la puerta con la mano más lejana a ella","Saludar a los carros de atrás"],"h1":"Hace que su cuerpo gire para ver hacia atrás.","h2":"El Dutch Reach es abrir la puerta del carro con la mano más lejana a ella, lo que hace girar su cuerpo para ver a los ciclistas que vienen.","p":"Correcto. Use la mano más lejana a la puerta."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-156","scope":"WA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Washington, a person who is blind is crossing with a guide dog. What should you NOT do?","o":["Wait until they have fully crossed","Honk your horn","Stay stopped behind the crosswalk","Keep your engine quiet and wait"],"h1":"A loud noise could confuse or frighten them.","h2":"In Washington, do not honk at a person using a service animal; it could confuse or frighten the animal or the person.","p":"Right. Do not honk."},"es":{"q":"En Washington, una persona ciega cruza con un perro guía. ¿Qué NO debe hacer?","o":["Esperar a que termine de cruzar","Pitar","Quedarse parado antes del cruce peatonal","Esperar en silencio"],"h1":"Un ruido fuerte podría confundirlos o asustarlos.","h2":"En Washington, no pite a una persona con un animal de servicio; podría confundir o asustar al animal o a la persona.","p":"Correcto. No pite."},"ref":{"doc":"WA","page":"§4.1"}},{"id":"wa-157","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, what happens to the fine if you pass a stopped school bus with its red lights flashing?","o":["It is doubled","It is cut in half","There is no fine, only a warning","It is the same as a parking ticket"],"h1":"The penalty is extra strong to protect children.","h2":"In Washington, fines are doubled for anyone who passes a stopped school bus.","p":"Right. The fine is doubled."},"es":{"q":"En Washington, ¿qué pasa con la multa si rebasa un autobús escolar detenido con las luces rojas intermitentes?","o":["Es el doble","Se reduce a la mitad","No hay multa, solo una advertencia","Es igual a una multa de estacionamiento"],"h1":"La pena es extra fuerte para proteger a los niños.","h2":"En Washington, las multas son el doble para quien rebasa un autobús escolar detenido.","p":"Correcto. La multa es el doble."},"ref":{"doc":"WA","page":"§4.2"}},{"id":"wa-158","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, you are in the center turn lane when a school bus ahead stops with red lights flashing. What must you do?","o":["Use the turn lane to pass the bus","Keep going if you are turning left","Honk and drive around slowly","Stop; drivers in turn lanes must stop too"],"h1":"A turn lane does not let you go around a school bus.","h2":"In Washington, never use a center turn lane to pass a stopped school bus; drivers in all turn lanes must stop.","p":"Right. You must stop."},"es":{"q":"En Washington, usted está en el carril central de vuelta cuando un autobús escolar adelante para con las luces rojas intermitentes. ¿Qué debe hacer?","o":["Usar el carril de vuelta para rebasar el autobús","Seguir si va a dar vuelta a la izquierda","Pitar y pasar despacio","Parar; los conductores en carriles de vuelta también deben parar"],"h1":"Un carril de vuelta no le permite rodear un autobús escolar.","h2":"En Washington, nunca use el carril central de vuelta para rebasar un autobús escolar detenido; los conductores en todos los carriles de vuelta deben parar.","p":"Correcto. Debe parar."},"ref":{"doc":"WA","page":"§4.2"}},{"id":"wa-159","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, a transit bus traveling your way has signaled and is pulling back onto the road. What should you do?","o":["Speed up to pass it first","Honk to warn the driver","Move into the bus stop area","Yield and let the bus in"],"h1":"The bus has signaled its plan.","h2":"In Washington, yield to a transit bus traveling in your direction that has signaled and is pulling back onto the roadway.","p":"Right. Yield to the bus."},"es":{"q":"En Washington, un autobús de transporte público que va en su dirección puso la direccional y está volviendo a la vía. ¿Qué debe hacer?","o":["Acelerar para pasarlo primero","Pitar para avisarle al chofer","Meterse en la parada del autobús","Ceder el paso y dejarlo entrar"],"h1":"El autobús ya avisó lo que va a hacer.","h2":"En Washington, ceda el paso a un autobús de transporte público que va en su dirección, puso la direccional y está volviendo a la vía.","p":"Correcto. Ceda el paso al autobús."},"ref":{"doc":"WA","page":"§4.3"}},{"id":"wa-160","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, how far does a loaded truck with good brakes need to stop from 55 mph?","o":["About 45 feet","About 100 feet","About 450 feet","About 2 miles"],"h1":"It is longer than a football field.","h2":"The Washington handbook says a loaded truck with properly adjusted brakes needs about 450 feet to stop from 55 mph, so never cut in front of one.","p":"Right. About 450 feet."},"es":{"q":"En Washington, ¿qué distancia necesita un camión cargado con buenos frenos para parar desde 55 mph?","o":["Unos 45 pies","Unos 100 pies","Unos 450 pies","Unas 2 millas"],"h1":"Es más que una cancha de fútbol americano.","h2":"El manual de Washington dice que un camión cargado con frenos bien ajustados necesita unos 450 pies para parar desde 55 mph, así que nunca se le meta adelante.","p":"Correcto. Unos 450 pies."},"ref":{"doc":"WA","page":"§4.4"}},{"id":"wa-161","scope":"WA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Washington, which vehicle must stop before every railroad crossing, even when no train is coming?","o":["A pickup truck","A school bus carrying children","A motorcycle","A car pulling a small trailer"],"h1":"Think of vehicles carrying many passengers or dangerous cargo.","h2":"Washington law requires school buses carrying children, passenger buses, and certain hazardous material vehicles to stop 15 to 50 feet before a railroad crossing.","p":"Right. A school bus carrying children."},"es":{"q":"En Washington, ¿qué vehículo debe parar antes de cada cruce de tren, aunque no venga ningún tren?","o":["Una camioneta pickup","Un autobús escolar con niños","Una motocicleta","Un carro con un remolque pequeño"],"h1":"Piense en vehículos con muchos pasajeros o carga peligrosa.","h2":"La ley de Washington exige que los autobuses escolares con niños, los autobuses de pasajeros y ciertos vehículos con materiales peligrosos paren de 15 a 50 pies antes de un cruce de tren.","p":"Correcto. Un autobús escolar con niños."},"ref":{"doc":"WA","page":null}},{"id":"wa-162","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, you are driving near a light rail train. How much space should you leave between your car and the train?","o":["At least one car length","A few inches","At least one mile","No space is needed"],"h1":"Think of the length of your own car.","h2":"The Washington handbook says to leave at least one car length, or more, between your vehicle and a light rail train.","p":"Right. At least one car length."},"es":{"q":"En Washington, usted maneja cerca de un tren ligero. ¿Cuánto espacio debe dejar entre su carro y el tren?","o":["Por lo menos el largo de un carro","Unas pulgadas","Por lo menos una milla","No hace falta espacio"],"h1":"Piense en el largo de su propio carro.","h2":"El manual de Washington dice que deje por lo menos el largo de un carro, o más, entre su vehículo y un tren ligero.","p":"Correcto. Por lo menos el largo de un carro."},"ref":{"doc":"WA","page":"§4.7"}},{"id":"wa-163","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, you pulled to the right for an ambulance and it has passed. How should the stopped drivers go back into traffic?","o":["Signal and re-enter in the order they were in before","Whoever is fastest goes first","The car closest to the ambulance follows it","Everyone pulls out at the same time"],"h1":"Keep the same order as before.","h2":"In Washington, after an emergency vehicle passes, signal and re-enter traffic in the order you were traveling before.","p":"Right. In the same order as before."},"es":{"q":"En Washington, usted se orilló a la derecha por una ambulancia y ya pasó. ¿Cómo deben volver al tráfico los conductores parados?","o":["Poner la direccional y volver en el mismo orden en que iban","Pasa primero el más rápido","El carro más cerca de la ambulancia la sigue","Todos salen al mismo tiempo"],"h1":"Mantenga el mismo orden de antes.","h2":"En Washington, después de que pasa un vehículo de emergencia, ponga la direccional y vuelva al tráfico en el orden en que iban antes.","p":"Correcto. En el mismo orden de antes."},"ref":{"doc":"WA","page":"§4.9"}},{"id":"wa-164","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, a fire truck is going to a fire. How close may you follow it?","o":["No closer than 50 feet","As close as you like","No closer than 1 mile","No closer than 500 feet"],"h1":"It is about a tenth of a mile.","h2":"Washington law says you may not follow a fire truck going to a fire closer than 500 feet, or stop within 500 feet of one stopped at a fire.","p":"Right. No closer than 500 feet."},"es":{"q":"En Washington, un camión de bomberos va hacia un incendio. ¿Qué tan cerca puede seguirlo?","o":["No más cerca de 50 pies","Tan cerca como quiera","No más cerca de 1 milla","No más cerca de 500 pies"],"h1":"Es como una décima de milla.","h2":"La ley de Washington dice que no puede seguir a un camión de bomberos que va a un incendio a menos de 500 pies, ni parar a menos de 500 pies de uno detenido en un incendio.","p":"Correcto. No más cerca de 500 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-165","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, may you use a carpool (HOV) lane as a passing lane?","o":["Yes, any time","Yes, if you go back within one mile","No, carpool lanes are not passing lanes","Yes, at night only"],"h1":"Those lanes have their own rules about who may use them.","h2":"The Washington handbook says carpool lanes are not passing lanes.","p":"Right. They are not for passing."},"es":{"q":"En Washington, ¿puede usar un carril de carpool (HOV) para rebasar?","o":["Sí, en cualquier momento","Sí, si vuelve antes de una milla","No, los carriles de carpool no son para rebasar","Sí, solo de noche"],"h1":"Esos carriles tienen sus propias reglas sobre quién los usa.","h2":"El manual de Washington dice que los carriles de carpool no son carriles para rebasar.","p":"Correcto. No son para rebasar."},"ref":{"doc":"WA","page":"§4.10"}},{"id":"wa-166","scope":"WA","cat":"signals","sign":null,"c":1,"en":{"q":"In Washington, you come to an intersection where the traffic signal is not working at all. What should you do?","o":["Drive through without slowing","Treat it like a four-way stop","Honk and go first","Only stop if a car is coming"],"h1":"Every driver stops, then takes turns.","h2":"In Washington, treat an intersection with a broken traffic signal like a four-way stop: stop fully, yield to traffic on your right, and go when it is safe.","p":"Right. Treat it like a four-way stop."},"es":{"q":"En Washington, llega a una intersección donde el semáforo no funciona para nada. ¿Qué debe hacer?","o":["Pasar sin bajar la velocidad","Tratarla como un alto de cuatro vías","Pitar y pasar primero","Parar solo si viene un carro"],"h1":"Todos paran y luego se turnan.","h2":"En Washington, trate una intersección con el semáforo descompuesto como un alto de cuatro vías: pare por completo, ceda el paso al tráfico de su derecha y siga cuando sea seguro.","p":"Correcto. Como un alto de cuatro vías."},"ref":{"doc":"WA","page":"§4.10"}},{"id":"wa-167","scope":"WA","cat":"signals","sign":null,"c":1,"en":{"q":"In Washington, the light turns yellow just as you reach the intersection. May you speed up past the limit to get through?","o":["Yes, that is what yellow means","No, you may not go over the speed limit to beat the light","Yes, if no police are around","Yes, by up to 10 mph"],"h1":"Yellow is a warning, not a race.","h2":"In Washington, you are not allowed to go faster than the posted speed limit to enter or clear an intersection on a yellow light.","p":"Right. You may not speed to beat the yellow."},"es":{"q":"En Washington, la luz se pone amarilla justo cuando llega a la intersección. ¿Puede acelerar más del límite para pasar?","o":["Sí, eso significa la luz amarilla","No, no puede pasar el límite de velocidad para ganarle a la luz","Sí, si no hay policía","Sí, hasta 10 mph más"],"h1":"La luz amarilla es una advertencia, no una carrera.","h2":"En Washington, no se permite ir más rápido que el límite para entrar o salir de una intersección con luz amarilla.","p":"Correcto. No puede acelerar para ganarle a la amarilla."},"ref":{"doc":"WA","page":"§4.11"}},{"id":"wa-168","scope":"WA","cat":"signals","sign":null,"c":0,"en":{"q":"In Washington, an automated traffic safety camera may record you for which of these?","o":["Speeding in a school zone","Not wearing a seat belt","Eating while driving","Having dirty windows"],"h1":"These cameras watch red lights, rail crossings, and one kind of zone.","h2":"In Washington, automated traffic safety cameras record drivers who run a red light, fail to stop at a railroad crossing signal, or speed in a school zone.","p":"Right. Speeding in a school zone."},"es":{"q":"En Washington, ¿por cuál de estas cosas puede grabarlo una cámara automática de tránsito?","o":["Exceso de velocidad en una zona escolar","No llevar el cinturón","Comer mientras maneja","Tener los vidrios sucios"],"h1":"Estas cámaras vigilan luces rojas, cruces de tren y un tipo de zona.","h2":"En Washington, las cámaras automáticas de tránsito graban a quien se pasa una luz roja, no para en la señal de un cruce de tren o va con exceso de velocidad en una zona escolar.","p":"Correcto. Exceso de velocidad en zona escolar."},"ref":{"doc":"WA","page":"§4.12"}},{"id":"wa-169","scope":"WA","cat":"signs","sign":null,"c":3,"en":{"q":"In Washington, when are fines doubled in a construction work zone?","o":["Only at night","Only on weekends","Never","When workers are present"],"h1":"It depends on who is there.","h2":"In Washington, fines double for offenses committed in construction areas when workers are present.","p":"Right. When workers are present."},"es":{"q":"En Washington, ¿cuándo son el doble las multas en una zona de construcción?","o":["Solo de noche","Solo los fines de semana","Nunca","Cuando hay trabajadores presentes"],"h1":"Depende de quién está ahí.","h2":"En Washington, las multas son el doble por infracciones en zonas de construcción cuando hay trabajadores presentes.","p":"Correcto. Cuando hay trabajadores presentes."},"ref":{"doc":"WA","page":"§4.12"}},{"id":"wa-170","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, a driver is convicted of reckless endangerment of emergency or work zone workers. How long is the license suspended?","o":["1 day","1 week","60 days","10 years"],"h1":"It is about two months.","h2":"Washington law requires a 60-day license suspension for a conviction of reckless endangerment of emergency or work zone workers.","p":"Right. 60 days."},"es":{"q":"En Washington, un conductor es condenado por poner en peligro de forma temeraria a trabajadores de emergencia o de zonas de trabajo. ¿Por cuánto tiempo le suspenden la licencia?","o":["1 día","1 semana","60 días","10 años"],"h1":"Son unos dos meses.","h2":"La ley de Washington exige una suspensión de la licencia de 60 días por una condena por poner en peligro de forma temeraria a trabajadores de emergencia o de zonas de trabajo.","p":"Correcto. 60 días."},"ref":{"doc":"WA","page":null}},{"id":"wa-171","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, which of these is a roadside response vehicle you must move over or slow down for?","o":["A delivery van parked in a driveway","A school bus with no lights on","A garbage (solid waste) truck with flashing lights","A car with a flat tire and no lights"],"h1":"The list includes tow trucks, utility vehicles, and trash trucks.","h2":"In Washington, roadside response vehicles with flashing lights include tow trucks, solid waste trucks, utility vehicles, highway maintenance, police, fire trucks, and ambulances.","p":"Right. A garbage truck with flashing lights counts."},"es":{"q":"En Washington, ¿cuál de estos es un vehículo de respuesta en carretera por el que debe cambiarse de carril o bajar la velocidad?","o":["Una camioneta de reparto estacionada en una entrada","Un autobús escolar sin luces prendidas","Un camión de basura con luces intermitentes","Un carro con una llanta ponchada y sin luces"],"h1":"La lista incluye grúas, vehículos de servicios públicos y camiones de basura.","h2":"En Washington, los vehículos de respuesta en carretera con luces intermitentes incluyen grúas, camiones de basura, vehículos de servicios públicos, mantenimiento de carreteras, policía, bomberos y ambulancias.","p":"Correcto. Un camión de basura con luces intermitentes cuenta."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-172","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, what is the fastest you may ever drive in an emergency zone?","o":["25 mph","50 mph","60 mph","70 mph"],"h1":"It is a round number below highway speeds.","h2":"The Washington handbook says never to drive faster than 50 mph in an emergency zone.","p":"Right. Never faster than 50 mph."},"es":{"q":"En Washington, ¿qué es lo más rápido que puede manejar en una zona de emergencia?","o":["25 mph","50 mph","60 mph","70 mph"],"h1":"Es un número redondo menor que la velocidad de carretera.","h2":"El manual de Washington dice que nunca maneje a más de 50 mph en una zona de emergencia.","p":"Correcto. Nunca a más de 50 mph."},"ref":{"doc":"WA","page":"§4.17"}},{"id":"wa-173","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, two cars arrive at a four-way stop at about the same time. Which one goes first?","o":["The car on the right","The car on the left","The larger vehicle","The car that honks first"],"h1":"Look to your right.","h2":"In Washington, if two vehicles arrive at a four-way stop at about the same time, the driver on the left yields to the vehicle on the right.","p":"Right. The car on the right goes first."},"es":{"q":"En Washington, dos carros llegan a un alto de cuatro vías casi al mismo tiempo. ¿Cuál pasa primero?","o":["El carro de la derecha","El carro de la izquierda","El vehículo más grande","El carro que pite primero"],"h1":"Mire a su derecha.","h2":"En Washington, si dos vehículos llegan a un alto de cuatro vías casi al mismo tiempo, el de la izquierda cede el paso al de la derecha.","p":"Correcto. Pasa primero el carro de la derecha."},"ref":{"doc":"WA","page":"§4.13"}},{"id":"wa-174","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, when are U-turns allowed?","o":["Never in Washington","Only on freeways","Only at night","Generally, unless a sign says no U-turn, and only where you can see clearly in all directions"],"h1":"Washington allows them unless posted, but not on curves or hilltops.","h2":"In Washington, U-turns are generally allowed unless a sign forbids them, but only where you can see clearly in all directions, not on a curve or near the top of a hill.","p":"Right. Allowed unless posted, with a clear view."},"es":{"q":"En Washington, ¿cuándo se permiten las vueltas en U?","o":["Nunca en Washington","Solo en autopistas","Solo de noche","Por lo general, salvo que un letrero las prohíba, y solo donde pueda ver bien en todas direcciones"],"h1":"Washington las permite salvo letrero, pero no en curvas ni en la cima de una colina.","h2":"En Washington, las vueltas en U se permiten por lo general salvo que un letrero las prohíba, pero solo donde pueda ver bien en todas direcciones, no en una curva ni cerca de la cima de una colina.","p":"Correcto. Permitidas salvo letrero, con buena visibilidad."},"ref":{"doc":"WA","page":"§4.14"}},{"id":"wa-175","scope":"WA","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Washington, a fire truck goes the \"wrong way\" (clockwise) around a small traffic calming circle. Why can that happen?","o":["The fire truck is breaking the law","All traffic goes clockwise in these circles","It means the circle is closed","These circles are made for cars, so large vehicles may need to go clockwise to fit"],"h1":"Think about the size of the vehicle.","h2":"In Washington, traffic calming circles are meant for passenger vehicles, and large vehicles like fire trucks may have to go clockwise to get through, so give them space.","p":"Right. Large vehicles may need to go clockwise."},"es":{"q":"En Washington, un camión de bomberos da la vuelta \"al revés\" (en el sentido del reloj) en un pequeño círculo para calmar el tráfico. ¿Por qué puede pasar eso?","o":["El camión de bomberos rompe la ley","Todo el tráfico va en el sentido del reloj en estos círculos","Significa que el círculo está cerrado","Estos círculos son para carros, así que los vehículos grandes pueden tener que ir en el sentido del reloj para caber"],"h1":"Piense en el tamaño del vehículo.","h2":"En Washington, los círculos para calmar el tráfico son para vehículos de pasajeros, y los vehículos grandes como camiones de bomberos pueden tener que ir en el sentido del reloj para pasar, así que deles espacio.","p":"Correcto. Los vehículos grandes pueden ir en el sentido del reloj."},"ref":{"doc":"WA","page":"§4.15"}},{"id":"wa-176","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, roundabouts are designed for what speed?","o":["5 mph or less","35 to 45 mph","15 to 25 mph","55 mph"],"h1":"It is about school-zone speed.","h2":"In Washington, roundabouts are designed for speeds between 15 and 25 mph, so slow down as you approach.","p":"Right. 15 to 25 mph."},"es":{"q":"En Washington, ¿para qué velocidad están diseñadas las glorietas?","o":["5 mph o menos","De 35 a 45 mph","De 15 a 25 mph","55 mph"],"h1":"Es como la velocidad de zona escolar.","h2":"En Washington, las glorietas están diseñadas para velocidades de 15 a 25 mph, así que baje la velocidad al acercarse.","p":"Correcto. De 15 a 25 mph."},"ref":{"doc":"WA","page":"§4.15"}},{"id":"wa-177","scope":"WA","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Washington, you are at an uncontrolled intersection, leaving a gravel road onto a paved road. Who must yield?","o":["The cars on the paved road must yield to you","You must yield","Whoever is going faster","The larger vehicle"],"h1":"The road with no pavement is the minor one.","h2":"In Washington, at an uncontrolled intersection, you must yield when you enter a paved road from an unpaved road.","p":"Right. You must yield."},"es":{"q":"En Washington, está en una intersección sin señales y sale de un camino de grava a una calle pavimentada. ¿Quién debe ceder el paso?","o":["Los carros de la calle pavimentada deben cederle el paso","Usted debe ceder el paso","El que vaya más rápido","El vehículo más grande"],"h1":"El camino sin pavimento es el menor.","h2":"En Washington, en una intersección sin señales, usted debe ceder el paso cuando entra a una calle pavimentada desde un camino sin pavimento.","p":"Correcto. Usted debe ceder el paso."},"ref":{"doc":"WA","page":"§4.15"}},{"id":"wa-178","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, besides carpools, vanpools, and buses, which vehicles may use HOV lanes?","o":["Motorcycles","Large trucks","Cars towing trailers","Any car with one driver"],"h1":"They are small and use little space.","h2":"In Washington, motorcycles are also allowed to use HOV lanes.","p":"Right. Motorcycles."},"es":{"q":"En Washington, además de carpools, vanpools y autobuses, ¿qué vehículos pueden usar los carriles HOV?","o":["Las motocicletas","Los camiones grandes","Los carros con remolque","Cualquier carro con solo el conductor"],"h1":"Son pequeñas y ocupan poco espacio.","h2":"En Washington, las motocicletas también pueden usar los carriles HOV.","p":"Correcto. Las motocicletas."},"ref":{"doc":"WA","page":"§4.16"}},{"id":"wa-179","scope":"WA","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Washington, you are stopped at a red light where there is a bicycle box painted in front of you. May you turn right on red?","o":["No, you cannot turn right on red at a bicycle box","Yes, after a full stop","Yes, if no bicycle is in the box","Yes, if you honk first"],"h1":"Bikes wait in front of you there.","h2":"In Washington, you cannot turn right on red near a bicycle box; stay behind the white line until the box is clear.","p":"Right. No right turn on red there."},"es":{"q":"En Washington, está parado en una luz roja donde hay una caja para bicicletas pintada delante de usted. ¿Puede dar vuelta a la derecha en rojo?","o":["No, no puede dar vuelta a la derecha en rojo en una caja para bicicletas","Sí, después de parar por completo","Sí, si no hay bicicletas en la caja","Sí, si pita primero"],"h1":"Ahí las bicicletas esperan delante de usted.","h2":"En Washington, no puede dar vuelta a la derecha en rojo cerca de una caja para bicicletas; quédese detrás de la línea blanca hasta que la caja esté libre.","p":"Correcto. Ahí no se da vuelta a la derecha en rojo."},"ref":{"doc":"WA","page":"§4.16"}},{"id":"wa-180","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, you may not park within how many feet of a driveway, alley, or private road?","o":["1 foot","20 feet","100 feet","5 feet"],"h1":"It is a small gap, about the width of a person lying down.","h2":"In Washington, do not park within 5 feet of a driveway, alley, or private road.","p":"Right. 5 feet."},"es":{"q":"En Washington, ¿a menos de cuántos pies de una entrada de carros, callejón o camino privado no puede estacionarse?","o":["1 pie","20 pies","100 pies","5 pies"],"h1":"Es un espacio pequeño, como una persona acostada.","h2":"En Washington, no se estacione a menos de 5 pies de una entrada de carros, callejón o camino privado.","p":"Correcto. 5 pies."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-181","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, how far must you park from a fire station driveway when you park on the opposite side of the street?","o":["10 feet","25 feet","75 feet","500 feet"],"h1":"It is between 50 and 100 feet.","h2":"In Washington, do not park within 75 feet of a fire station driveway on the opposite side of the street.","p":"Right. 75 feet."},"es":{"q":"En Washington, ¿a qué distancia de la entrada de una estación de bomberos debe estacionarse cuando lo hace en el lado opuesto de la calle?","o":["10 pies","25 pies","75 pies","500 pies"],"h1":"Está entre 50 y 100 pies.","h2":"En Washington, no se estacione a menos de 75 pies de la entrada de una estación de bomberos en el lado opuesto de la calle.","p":"Correcto. 75 pies."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-182","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you may not park within how many feet of a crosswalk?","o":["2 feet","20 feet","50 feet","200 feet"],"h1":"It is about the length of one and a half cars.","h2":"Washington law says you may not stand or park within 20 feet of a crosswalk, except briefly to pick up or drop off passengers.","p":"Right. 20 feet."},"es":{"q":"En Washington, ¿a menos de cuántos pies de un cruce peatonal no puede estacionarse?","o":["2 pies","20 pies","50 pies","200 pies"],"h1":"Es como el largo de un carro y medio.","h2":"La ley de Washington dice que no puede detenerse ni estacionarse a menos de 20 pies de un cruce peatonal, salvo por un momento para subir o bajar pasajeros.","p":"Correcto. 20 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-183","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, it is a crime to leave a child under what age alone in a parked car?","o":["3","12","8","18"],"h1":"It is a different age than the rule for a running engine.","h2":"In Washington, it is a crime to leave a child under 12 unattended in a parked vehicle, and under 16 if the motor is running.","p":"Right. Under 12."},"es":{"q":"En Washington, es delito dejar solo en un carro estacionado a un niño menor de qué edad?","o":["3","12","8","18"],"h1":"Es una edad distinta a la de la regla con el motor prendido.","h2":"En Washington, es delito dejar solo en un vehículo estacionado a un niño menor de 12 años, y menor de 16 si el motor está prendido.","p":"Correcto. Menor de 12."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-184","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, you park facing uphill next to a tall curb. Which way should you turn your steering wheel?","o":["Away from the curb, so the back of the front tire touches the curb","Toward the curb","Keep the wheels straight","It does not matter if the brake is set"],"h1":"If the car rolls back, the curb should stop it.","h2":"In Washington, when parking uphill next to a tall curb, turn the wheel away from the curb so the back of the front tire rests against it.","p":"Right. Turn away from the curb."},"es":{"q":"En Washington, usted se estaciona cuesta arriba junto a una acera alta. ¿Hacia dónde debe girar el volante?","o":["Lejos de la acera, para que la parte de atrás de la llanta delantera toque la acera","Hacia la acera","Con las llantas derechas","No importa si puso el freno"],"h1":"Si el carro rueda hacia atrás, la acera debe detenerlo.","h2":"En Washington, al estacionarse cuesta arriba junto a una acera alta, gire el volante lejos de la acera para que la parte de atrás de la llanta delantera quede contra ella.","p":"Correcto. Gire lejos de la acera."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-185","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, you park facing downhill next to a curb. Which way should you turn your steering wheel?","o":["Away from the curb","Keep the wheels straight","Toward the middle of the street","Toward the curb"],"h1":"If the car rolls forward, the curb should stop it.","h2":"In Washington, when parking downhill, turn the wheel toward the curb so the front of the front tire touches it.","p":"Right. Turn toward the curb."},"es":{"q":"En Washington, usted se estaciona cuesta abajo junto a una acera. ¿Hacia dónde debe girar el volante?","o":["Lejos de la acera","Con las llantas derechas","Hacia el centro de la calle","Hacia la acera"],"h1":"Si el carro rueda hacia adelante, la acera debe detenerlo.","h2":"En Washington, al estacionarse cuesta abajo, gire el volante hacia la acera para que la parte de adelante de la llanta delantera la toque.","p":"Correcto. Gire hacia la acera."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-186","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, may you park a gas car in an electric vehicle charging space for a few minutes?","o":["Yes, for up to 15 minutes","Yes, if you stay in the car","No, it is illegal unless the vehicle is connected to the charger","Yes, at night"],"h1":"The space is for vehicles that are charging.","h2":"In Washington, it is illegal to park in an electric vehicle charging space if the vehicle is not connected to the charging equipment.","p":"Right. Only vehicles connected to the charger may park there."},"es":{"q":"En Washington, ¿puede estacionar un carro de gasolina en un espacio de carga para vehículos eléctricos por unos minutos?","o":["Sí, hasta 15 minutos","Sí, si se queda en el carro","No, es ilegal salvo que el vehículo esté conectado al cargador","Sí, de noche"],"h1":"El espacio es para vehículos que se están cargando.","h2":"En Washington, es ilegal estacionarse en un espacio de carga para vehículos eléctricos si el vehículo no está conectado al equipo de carga.","p":"Correcto. Solo vehículos conectados al cargador."},"ref":{"doc":"WA","page":"§4.18"}},{"id":"wa-187","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, in which counties is driving allowed on ocean beaches?","o":["All coastal counties","King and Pierce Counties","Only Grays Harbor and Pacific Counties","Nowhere in Washington"],"h1":"Both are on the southern coast.","h2":"In Washington, driving on ocean beaches is allowed only in Grays Harbor and Pacific Counties.","p":"Right. Grays Harbor and Pacific Counties."},"es":{"q":"En Washington, ¿en qué condados se permite manejar en las playas del océano?","o":["En todos los condados de la costa","En los condados de King y Pierce","Solo en los condados de Grays Harbor y Pacific","En ninguna parte de Washington"],"h1":"Los dos están en la costa sur.","h2":"En Washington, manejar en las playas del océano solo se permite en los condados de Grays Harbor y Pacific.","p":"Correcto. Grays Harbor y Pacific."},"ref":{"doc":"WA","page":"§4.20"}},{"id":"wa-188","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, unless a sign says otherwise, what is the speed limit on city and town streets?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"It is a little faster than a school zone.","h2":"Washington law sets a 25 mph maximum speed on city and town streets unless a different limit is posted.","p":"Right. 25 mph."},"es":{"q":"En Washington, salvo que un letrero diga otra cosa, ¿cuál es el límite de velocidad en las calles de ciudades y pueblos?","o":["20 mph","25 mph","35 mph","45 mph"],"h1":"Es un poco más que una zona escolar.","h2":"La ley de Washington fija una velocidad máxima de 25 mph en calles de ciudades y pueblos, salvo que se indique otro límite.","p":"Correcto. 25 mph."},"ref":{"doc":"WA","page":null}},{"id":"wa-189","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, unless a sign says otherwise, what is the speed limit on county roads?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"It is half of 100.","h2":"Washington law sets a 50 mph maximum speed on county roads unless a different limit is posted.","p":"Right. 50 mph."},"es":{"q":"En Washington, salvo que un letrero diga otra cosa, ¿cuál es el límite de velocidad en los caminos del condado?","o":["50 mph","35 mph","60 mph","70 mph"],"h1":"Es la mitad de 100.","h2":"La ley de Washington fija una velocidad máxima de 50 mph en los caminos del condado, salvo que se indique otro límite.","p":"Correcto. 50 mph."},"ref":{"doc":"WA","page":null}},{"id":"wa-190","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, unless a sign says otherwise, what is the speed limit on state highways?","o":["50 mph","70 mph","75 mph","60 mph"],"h1":"It is one mile per minute.","h2":"Washington law sets a 60 mph maximum speed on state highways unless a different limit is posted.","p":"Right. 60 mph."},"es":{"q":"En Washington, salvo que un letrero diga otra cosa, ¿cuál es el límite de velocidad en las carreteras estatales?","o":["50 mph","70 mph","75 mph","60 mph"],"h1":"Es una milla por minuto.","h2":"La ley de Washington fija una velocidad máxima de 60 mph en las carreteras estatales, salvo que se indique otro límite.","p":"Correcto. 60 mph."},"ref":{"doc":"WA","page":null}},{"id":"wa-191","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, how far in each direction from a posted school crosswalk does the 20 mph school speed zone reach?","o":["30 feet","1,000 feet","Half a mile","300 feet"],"h1":"It is about the length of a football field.","h2":"Under Washington law, the 20 mph speed zone at a posted school or playground crosswalk extends 300 feet in each direction from the crosswalk.","p":"Right. 300 feet."},"es":{"q":"En Washington, ¿hasta qué distancia en cada dirección desde un cruce escolar con letreros llega la zona escolar de 20 mph?","o":["30 pies","1,000 pies","Media milla","300 pies"],"h1":"Es como el largo de una cancha de fútbol americano.","h2":"Según la ley de Washington, la zona de 20 mph en un cruce escolar o de parque con letreros se extiende 300 pies en cada dirección desde el cruce.","p":"Correcto. 300 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-192","scope":"WA","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Washington, you get a speeding ticket in a school zone. What happens to the penalty?","o":["It is cut in half for a first offense","It is the same as anywhere else","It is doubled and cannot be waived or reduced","It becomes a warning"],"h1":"Children's safety makes it extra costly.","h2":"Washington law doubles the penalty for speeding in a school or playground speed zone, and it may not be waived, reduced, or suspended.","p":"Right. It is doubled and cannot be reduced."},"es":{"q":"En Washington, recibe una multa por exceso de velocidad en una zona escolar. ¿Qué pasa con la multa?","o":["Se reduce a la mitad la primera vez","Es igual que en cualquier otro lugar","Es el doble y no se puede perdonar ni reducir","Se vuelve una advertencia"],"h1":"La seguridad de los niños la hace extra cara.","h2":"La ley de Washington duplica la multa por exceso de velocidad en zonas escolares o de parques, y no se puede perdonar, reducir ni suspender.","p":"Correcto. Es el doble y no se puede reducir."},"ref":{"doc":"WA","page":null}},{"id":"wa-193","scope":"WA","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Washington, you are driving slowly on a two-lane road where passing is unsafe. At least how many vehicles lined up behind you means you must pull over where it is safe?","o":["2","5","10","20"],"h1":"It is the number of fingers on one hand.","h2":"Washington law says a slow-moving vehicle with five or more vehicles lined up behind it must turn off the road at a safe turnout to let them pass.","p":"Right. Five or more."},"es":{"q":"En Washington, usted maneja despacio en un camino de dos carriles donde no es seguro rebasar. ¿Desde cuántos vehículos en fila detrás de usted debe orillarse donde sea seguro?","o":["2","5","10","20"],"h1":"Es el número de dedos de una mano.","h2":"La ley de Washington dice que un vehículo lento con cinco o más vehículos en fila detrás debe salirse del camino en un lugar seguro para dejarlos pasar.","p":"Correcto. Cinco o más."},"ref":{"doc":"WA","page":null}},{"id":"wa-194","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, you pass on a two-lane road using the oncoming lane. You must be back in your lane before coming within how many feet of oncoming traffic?","o":["200 feet","20 feet","50 feet","2,000 feet"],"h1":"It is twice the distance for signaling before a turn.","h2":"Washington law says a driver passing in the oncoming lane must return to the proper lane before coming within 200 feet of any approaching traffic.","p":"Right. 200 feet."},"es":{"q":"En Washington, usted rebasa en un camino de dos carriles usando el carril contrario. ¿Antes de llegar a cuántos pies del tráfico que viene debe volver a su carril?","o":["200 pies","20 pies","50 pies","2,000 pies"],"h1":"Es el doble de la distancia para poner la direccional antes de dar vuelta.","h2":"La ley de Washington dice que quien rebasa por el carril contrario debe volver a su carril antes de llegar a 200 pies de cualquier vehículo que venga de frente.","p":"Correcto. 200 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-195","scope":"WA","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Washington, you may not drive on the left side of the road to pass within how many feet of an intersection or railroad crossing?","o":["100 feet","10 feet","500 feet","1 mile"],"h1":"It is the same distance as the turn signal rule.","h2":"Washington law says you may not drive on the left side of the roadway when approaching within 100 feet of, or crossing, an intersection or railroad crossing.","p":"Right. 100 feet."},"es":{"q":"En Washington, ¿a menos de cuántos pies de una intersección o cruce de tren no puede manejar por el lado izquierdo del camino para rebasar?","o":["100 pies","10 pies","500 pies","1 milla"],"h1":"Es la misma distancia que la regla de la direccional.","h2":"La ley de Washington dice que no puede manejar por el lado izquierdo del camino al acercarse a menos de 100 pies de una intersección o cruce de tren, ni al cruzarlo.","p":"Correcto. 100 pies."},"ref":{"doc":"WA","page":null}},{"id":"wa-196","scope":"WA","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Washington, you are towing a trailer on a freeway with three or more lanes going your way. May you drive in the far left lane?","o":["Yes, any time","Yes, if you are passing","Yes, during rush hour","No, except when preparing for a legal left turn or left exit"],"h1":"Towing vehicles must stay out of that lane.","h2":"Washington law says a vehicle towing a trailer may not use the left-hand lane of a limited access road with three or more lanes in one direction, except to prepare for a legal left turn or exit.","p":"Right. Not except to prepare for a left turn or exit."},"es":{"q":"En Washington, usted lleva un remolque en una autopista con tres o más carriles en su dirección. ¿Puede manejar en el carril de la extrema izquierda?","o":["Sí, en cualquier momento","Sí, si está rebasando","Sí, en horas pico","No, salvo para prepararse para una vuelta o salida legal a la izquierda"],"h1":"Los vehículos con remolque deben mantenerse fuera de ese carril.","h2":"La ley de Washington dice que un vehículo con remolque no puede usar el carril izquierdo de una vía de acceso limitado con tres o más carriles en una dirección, salvo para prepararse para una vuelta o salida legal a la izquierda.","p":"Correcto. No, salvo para prepararse para una vuelta o salida a la izquierda."},"ref":{"doc":"WA","page":null}},{"id":"wa-197","scope":"WA","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Washington, a negligent driver seriously injures a bicyclist or pedestrian. What penalty can the law impose?","o":["A $50 fine only","A written warning","A $5,000 fine and a 90-day license suspension","Losing the license for one day"],"h1":"Bicyclists and pedestrians are called vulnerable road users.","h2":"Under Washington law, negligent driving that seriously injures a vulnerable road user carries a $5,000 penalty and a 90-day license suspension, unless the court allows other options.","p":"Right. $5,000 and a 90-day suspension."},"es":{"q":"En Washington, un conductor negligente hiere gravemente a un ciclista o peatón. ¿Qué pena puede imponer la ley?","o":["Solo una multa de $50","Una advertencia por escrito","Una multa de $5,000 y 90 días de suspensión de la licencia","Perder la licencia por un día"],"h1":"A los ciclistas y peatones se les llama usuarios vulnerables de la vía.","h2":"Según la ley de Washington, manejar con negligencia y herir gravemente a un usuario vulnerable de la vía trae una multa de $5,000 y una suspensión de 90 días, salvo que el juez permita otras opciones.","p":"Correcto. $5,000 y 90 días de suspensión."},"ref":{"doc":"WA","page":null}},{"id":"wa-198","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, a crash with no injuries must be reported when damage to any one person's property is at least how much?","o":["$100","$1,000","$5,000","$25,000"],"h1":"It is a four-digit amount.","h2":"In Washington, the reporting threshold for a property damage crash is $1,000, set by Washington State Patrol rule.","p":"Right. $1,000."},"es":{"q":"En Washington, un choque sin heridos se debe reportar cuando el daño a la propiedad de una persona es de por lo menos cuánto?","o":["$100","$1,000","$5,000","$25,000"],"h1":"Es una cantidad de cuatro cifras.","h2":"En Washington, el límite para reportar un choque con daños a la propiedad es de $1,000, fijado por una regla de la Patrulla Estatal de Washington.","p":"Correcto. $1,000."},"ref":{"doc":"WA","page":null}},{"id":"wa-199","scope":"WA","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Washington, you hit a parked car and cannot find the owner. What must you do?","o":["Drive away; no one saw it","Leave a written note in plain view with your name and address","Wait one hour, then leave","Call your insurance company only"],"h1":"The owner must be able to find you.","h2":"Washington law says if you hit an unattended vehicle and cannot find the owner, you must leave a written note in a place it can easily be seen with your name and address and the owner's name and address; leaving without doing so is a misdemeanor.","p":"Right. Leave a note with your name and address."},"es":{"q":"En Washington, usted choca un carro estacionado y no encuentra al dueño. ¿Qué debe hacer?","o":["Irse; nadie lo vio","Dejar una nota escrita a la vista con su nombre y dirección","Esperar una hora y luego irse","Solo llamar a su compañía de seguros"],"h1":"El dueño debe poder encontrarlo.","h2":"La ley de Washington dice que si choca un vehículo sin nadie adentro y no encuentra al dueño, debe dejar una nota escrita en un lugar fácil de ver con su nombre y dirección y los del dueño del vehículo; irse sin hacerlo es un delito menor.","p":"Correcto. Deje una nota con su nombre y dirección."},"ref":{"doc":"WA","page":null}},{"id":"wa-200","scope":"WA","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Washington, after a crash, a power line is lying on your car. There is no fire. What should you do?","o":["Stay inside, call 911, and wait for responders","Get out and run away fast","Drive forward to get off the line","Touch the line to see if it is live"],"h1":"Assume the line is energized.","h2":"In Washington, if a power line touches your vehicle and there is no fire, stay inside, call 911, and wait for emergency responders; the ground nearby may also be energized.","p":"Right. Stay inside and call 911."},"es":{"q":"En Washington, después de un choque, un cable de luz está encima de su carro. No hay fuego. ¿Qué debe hacer?","o":["Quedarse adentro, llamar al 911 y esperar a los socorristas","Salir y correr rápido","Avanzar para salir del cable","Tocar el cable para ver si tiene corriente"],"h1":"Suponga que el cable tiene corriente.","h2":"En Washington, si un cable de luz toca su vehículo y no hay fuego, quédese adentro, llame al 911 y espere a los socorristas; el suelo cerca también puede tener corriente.","p":"Correcto. Quédese adentro y llame al 911."},"ref":{"doc":"WA","page":"§5.9"}},{"id":"wi-001","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how many questions are on the knowledge test?","o":["20 questions","25 questions","35 questions","50 questions"],"h1":"It is half of one hundred.","h2":"The Wisconsin knowledge test has 50 questions.","p":"Right. The Wisconsin test has 50 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen de conocimientos?","o":["20 preguntas","25 preguntas","35 preguntas","50 preguntas"],"h1":"Es la mitad de cien.","h2":"El examen de conocimientos de Wisconsin tiene 50 preguntas.","p":"Correcto. El examen de Wisconsin tiene 50 preguntas."},"zh":{"q":"在 Wisconsin，知识考试有多少道题？","o":["20 道题","25 道题","35 道题","50 道题"],"h1":"它是一百的一半。","h2":"Wisconsin 的知识考试有 50 道题。","p":"对。Wisconsin 的考试有 50 道题。"},"vi":{"q":"Ở Wisconsin, bài thi kiến thức có bao nhiêu câu hỏi?","o":["20 câu hỏi","25 câu hỏi","35 câu hỏi","50 câu hỏi"],"h1":"Đó là một nửa của một trăm.","h2":"Bài thi kiến thức ở Wisconsin có 50 câu hỏi.","p":"Đúng. Bài thi ở Wisconsin có 50 câu hỏi."},"tl":{"q":"Sa Wisconsin, ilang tanong ang nasa knowledge test?","o":["20 tanong","25 tanong","35 tanong","50 tanong"],"h1":"Ito ay kalahati ng isang daan.","h2":"Ang knowledge test ng Wisconsin ay may 50 tanong.","p":"Tama. Ang test sa Wisconsin ay may 50 tanong."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار المعرفة؟","o":["20 سؤالًا","25 سؤالًا","35 سؤالًا","50 سؤالًا"],"h1":"هو نصف المئة.","h2":"اختبار المعرفة في Wisconsin فيه 50 سؤالًا.","p":"صحيح. اختبار Wisconsin فيه 50 سؤالًا."},"ref":{"doc":"WI","page":1}},{"id":"wi-002","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many knowledge test questions must you answer correctly to pass?","o":["40","30","35","45"],"h1":"You need 80 percent of the 50 questions.","h2":"You must answer at least 40 of the 50 Wisconsin knowledge test questions correctly, which is 80 percent.","p":"Right. You need 40 correct answers."},"es":{"q":"En Wisconsin, ¿cuántas preguntas del examen de conocimientos debe contestar bien para aprobar?","o":["40","30","35","45"],"h1":"Necesita el 80 por ciento de las 50 preguntas.","h2":"Usted debe contestar bien por lo menos 40 de las 50 preguntas del examen de conocimientos de Wisconsin, que es el 80 por ciento.","p":"Correcto. Necesita 40 respuestas correctas."},"zh":{"q":"在 Wisconsin，知识考试必须答对多少道题才能通过？","o":["40","30","35","45"],"h1":"你需要答对 50 道题中的 80%。","h2":"Wisconsin 知识考试的 50 道题中，你必须至少答对 40 道，也就是 80%。","p":"对。你需要答对 40 道题。"},"vi":{"q":"Ở Wisconsin, bạn phải trả lời đúng bao nhiêu câu trong bài thi kiến thức để đậu?","o":["40","30","35","45"],"h1":"Bạn cần đúng 80% của 50 câu hỏi.","h2":"Bạn phải trả lời đúng ít nhất 40 trong 50 câu hỏi của bài thi kiến thức ở Wisconsin, tức là 80%.","p":"Đúng. Bạn cần 40 câu trả lời đúng."},"tl":{"q":"Sa Wisconsin, ilang tanong sa knowledge test ang dapat mong masagot nang tama para pumasa?","o":["40","30","35","45"],"h1":"Kailangan mo ang 80% ng 50 tanong.","h2":"Dapat mong masagot nang tama ang hindi bababa sa 40 sa 50 tanong ng knowledge test ng Wisconsin, o 80%.","p":"Tama. Kailangan mo ng 40 tamang sagot."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار المعرفة يجب أن تجيب عنه إجابة صحيحة لتنجح؟","o":["40","30","35","45"],"h1":"تحتاج إلى 80% من الأسئلة الـ 50.","h2":"يجب أن تجيب إجابة صحيحة عن 40 سؤالًا على الأقل من 50 سؤالًا في اختبار المعرفة في Wisconsin، أي 80%.","p":"صحيح. تحتاج إلى 40 إجابة صحيحة."},"ref":{"doc":"WI","page":1}},{"id":"wi-003","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how many questions are on the separate road signs test?","o":["5 questions","10 questions","15 questions","25 questions"],"h1":"It is between 10 and 20.","h2":"Wisconsin gives a separate road signs test with 15 questions, and you must answer at least 12 correctly.","p":"Right. The signs test has 15 questions."},"es":{"q":"En Wisconsin, ¿cuántas preguntas tiene el examen separado de señales de tránsito?","o":["5 preguntas","10 preguntas","15 preguntas","25 preguntas"],"h1":"Está entre 10 y 20.","h2":"Wisconsin hace un examen separado de señales de tránsito con 15 preguntas, y usted debe contestar bien por lo menos 12.","p":"Correcto. El examen de señales tiene 15 preguntas."},"zh":{"q":"在 Wisconsin，单独的交通标志考试有多少道题？","o":["5 道题","10 道题","15 道题","25 道题"],"h1":"它在 10 和 20 之间。","h2":"Wisconsin 有单独的交通标志考试，共 15 道题，你必须至少答对 12 道。","p":"对。标志考试有 15 道题。"},"vi":{"q":"Ở Wisconsin, bài thi biển báo đường bộ riêng có bao nhiêu câu hỏi?","o":["5 câu hỏi","10 câu hỏi","15 câu hỏi","25 câu hỏi"],"h1":"Con số này nằm giữa 10 và 20.","h2":"Wisconsin có một bài thi biển báo đường bộ riêng với 15 câu hỏi, và bạn phải trả lời đúng ít nhất 12 câu.","p":"Đúng. Bài thi biển báo có 15 câu hỏi."},"tl":{"q":"Sa Wisconsin, ilang tanong ang nasa hiwalay na test tungkol sa mga karatula sa daan?","o":["5 tanong","10 tanong","15 tanong","25 tanong"],"h1":"Ito ay nasa pagitan ng 10 at 20.","h2":"May hiwalay na test ang Wisconsin tungkol sa mga karatula sa daan na may 15 tanong, at dapat mong masagot nang tama ang hindi bababa sa 12.","p":"Tama. Ang test sa karatula ay may 15 tanong."},"ar":{"q":"في Wisconsin، كم سؤالًا في اختبار إشارات الطريق المنفصل؟","o":["5 أسئلة","10 أسئلة","15 سؤالًا","25 سؤالًا"],"h1":"العدد بين 10 و 20.","h2":"في Wisconsin اختبار منفصل لإشارات الطريق فيه 15 سؤالًا، ويجب أن تجيب إجابة صحيحة عن 12 سؤالًا على الأقل.","p":"صحيح. اختبار الإشارات فيه 15 سؤالًا."},"ref":{"doc":"WI","page":1}},{"id":"wi-004","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many hours of driving practice does an applicant under 18 need before a probationary license?","o":["30 hours","50 hours","20 hours","100 hours"],"h1":"The number went up in 2021.","h2":"A Wisconsin applicant under 18 needs 50 hours of driving practice, 10 of them at night, before a probationary license.","p":"Right. Wisconsin requires 50 hours."},"es":{"q":"En Wisconsin, ¿cuántas horas de práctica de manejo necesita un solicitante menor de 18 años antes de la licencia probatoria?","o":["30 horas","50 horas","20 horas","100 horas"],"h1":"El número subió en 2021.","h2":"Un solicitante de Wisconsin menor de 18 años necesita 50 horas de práctica de manejo, 10 de ellas de noche, antes de la licencia probatoria.","p":"Correcto. Wisconsin exige 50 horas."},"zh":{"q":"在 Wisconsin，18 岁以下的申请人在拿试用驾照（probationary license）前需要练车多少小时？","o":["30 小时","50 小时","20 小时","100 小时"],"h1":"这个数字在 2021 年提高了。","h2":"在 Wisconsin，18 岁以下的申请人在拿试用驾照前需要练车 50 小时，其中 10 小时要在夜间。","p":"对。Wisconsin 要求 50 小时。"},"vi":{"q":"Ở Wisconsin, người nộp đơn dưới 18 tuổi cần bao nhiêu giờ tập lái trước khi có bằng lái tạm thời (probationary license)?","o":["30 giờ","50 giờ","20 giờ","100 giờ"],"h1":"Con số này đã tăng lên vào năm 2021.","h2":"Ở Wisconsin, người nộp đơn dưới 18 tuổi cần 50 giờ tập lái, trong đó 10 giờ vào ban đêm, trước khi có bằng lái tạm thời.","p":"Đúng. Wisconsin yêu cầu 50 giờ."},"tl":{"q":"Sa Wisconsin, ilang oras ng pagsasanay sa pagmamaneho ang kailangan ng aplikanteng wala pang 18 bago makakuha ng probationary license?","o":["30 oras","50 oras","20 oras","100 oras"],"h1":"Tumaas ang bilang na ito noong 2021.","h2":"Ang aplikante sa Wisconsin na wala pang 18 ay kailangan ng 50 oras ng pagsasanay sa pagmamaneho, 10 dito sa gabi, bago makakuha ng probationary license.","p":"Tama. 50 oras ang kailangan sa Wisconsin."},"ar":{"q":"في Wisconsin، كم ساعة من التدريب على القيادة يحتاج المتقدم الذي عمره أقل من 18 قبل رخصة القيادة التجريبية (probationary license)؟","o":["30 ساعة","50 ساعة","20 ساعة","100 ساعة"],"h1":"زاد هذا العدد في سنة 2021.","h2":"المتقدم في Wisconsin الذي عمره أقل من 18 يحتاج إلى 50 ساعة من التدريب على القيادة، منها 10 ساعات في الليل، قبل رخصة القيادة التجريبية.","p":"صحيح. Wisconsin تطلب 50 ساعة."},"ref":{"doc":"WI","page":6}},{"id":"wi-005","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many of the required practice hours must be at night?","o":["10 hours","5 hours","15 hours","25 hours"],"h1":"It is one fifth of 50.","h2":"At least 10 of the 50 practice hours required in Wisconsin must be driven at night.","p":"Right. Ten hours must be at night."},"es":{"q":"En Wisconsin, ¿cuántas de las horas de práctica obligatorias deben ser de noche?","o":["10 horas","5 horas","15 horas","25 horas"],"h1":"Es la quinta parte de 50.","h2":"Por lo menos 10 de las 50 horas de práctica que exige Wisconsin deben manejarse de noche.","p":"Correcto. Diez horas deben ser de noche."},"zh":{"q":"在 Wisconsin，规定的练车时间中有多少小时必须在夜间？","o":["10 小时","5 小时","15 小时","25 小时"],"h1":"它是 50 的五分之一。","h2":"在 Wisconsin 规定的 50 小时练车时间中，至少 10 小时必须在夜间开车。","p":"对。10 小时必须在夜间。"},"vi":{"q":"Ở Wisconsin, trong số giờ tập lái bắt buộc, bao nhiêu giờ phải lái vào ban đêm?","o":["10 giờ","5 giờ","15 giờ","25 giờ"],"h1":"Đó là một phần năm của 50.","h2":"Trong 50 giờ tập lái bắt buộc ở Wisconsin, ít nhất 10 giờ phải lái vào ban đêm.","p":"Đúng. Mười giờ phải lái vào ban đêm."},"tl":{"q":"Sa Wisconsin, ilan sa mga kailangang oras ng pagsasanay ang dapat sa gabi?","o":["10 oras","5 oras","15 oras","25 oras"],"h1":"Ito ay ikalimang bahagi ng 50.","h2":"Hindi bababa sa 10 sa 50 oras ng pagsasanay na kailangan sa Wisconsin ang dapat imaneho sa gabi.","p":"Tama. Sampung oras ang dapat sa gabi."},"ar":{"q":"في Wisconsin، كم ساعة من ساعات التدريب المطلوبة يجب أن تكون في الليل؟","o":["10 ساعات","5 ساعات","15 ساعة","25 ساعة"],"h1":"هي خُمس الـ 50.","h2":"يجب أن تكون 10 ساعات على الأقل من ساعات التدريب الـ 50 المطلوبة في Wisconsin قيادةً في الليل.","p":"صحيح. عشر ساعات يجب أن تكون في الليل."},"ref":{"doc":"WI","page":6}},{"id":"wi-006","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how long must you hold an instruction permit, violation free, before a probationary license?","o":["1 month","3 months","12 months","6 months"],"h1":"It is half a year.","h2":"In Wisconsin you must hold an instruction permit for at least six months and be violation free for those six months before a probationary license.","p":"Right. Six months, with no violations."},"es":{"q":"En Wisconsin, ¿cuánto tiempo debe tener el permiso de aprendiz, sin infracciones, antes de la licencia probatoria?","o":["1 mes","3 meses","12 meses","6 meses"],"h1":"Es medio año.","h2":"En Wisconsin usted debe tener el permiso de aprendiz por lo menos seis meses y no tener infracciones en esos seis meses antes de la licencia probatoria.","p":"Correcto. Seis meses, sin infracciones."},"zh":{"q":"在 Wisconsin，拿试用驾照前，你必须持有学习驾照（instruction permit）多久，并且没有违规？","o":["1 个月","3 个月","12 个月","6 个月"],"h1":"它是半年。","h2":"在 Wisconsin，拿试用驾照前，你必须持有学习驾照至少六个月，而且这六个月内没有违规。","p":"对。六个月，没有违规。"},"vi":{"q":"Ở Wisconsin, bạn phải giữ giấy phép tập lái (instruction permit) bao lâu, không vi phạm, trước khi có bằng lái tạm thời?","o":["1 tháng","3 tháng","12 tháng","6 tháng"],"h1":"Đó là nửa năm.","h2":"Ở Wisconsin, bạn phải giữ giấy phép tập lái ít nhất sáu tháng và không có vi phạm nào trong sáu tháng đó trước khi có bằng lái tạm thời.","p":"Đúng. Sáu tháng, không vi phạm."},"tl":{"q":"Sa Wisconsin, gaano katagal mo dapat hawak ang instruction permit, nang walang paglabag, bago makakuha ng probationary license?","o":["1 buwan","3 buwan","12 buwan","6 na buwan"],"h1":"Ito ay kalahating taon.","h2":"Sa Wisconsin, dapat hawak mo ang instruction permit nang hindi bababa sa anim na buwan at walang paglabag sa anim na buwang iyon bago makakuha ng probationary license.","p":"Tama. Anim na buwan, walang paglabag."},"ar":{"q":"في Wisconsin، كم مدة يجب أن تحمل تصريح التعلم (instruction permit) بدون مخالفات قبل رخصة القيادة التجريبية؟","o":["شهر واحد","3 أشهر","12 شهرًا","6 أشهر"],"h1":"هي نصف سنة.","h2":"في Wisconsin يجب أن تحمل تصريح التعلم ستة أشهر على الأقل وأن تكون بدون مخالفات خلال هذه الأشهر الستة قبل رخصة القيادة التجريبية.","p":"صحيح. ستة أشهر بدون مخالفات."},"ref":{"doc":"WI","page":6}},{"id":"wi-007","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, besides driver education, what else does a teen need to apply for a probationary license?","o":["A car in their own name","A part-time job","An adult sponsor","A high school diploma"],"h1":"An adult must take responsibility for the teen driver.","h2":"A Wisconsin teen applying for a probationary license must be at least 16, finish an approved driver education course, and have an adult sponsor.","p":"Right. An adult sponsor is required."},"es":{"q":"En Wisconsin, además del curso de manejo, ¿qué más necesita un joven para solicitar la licencia probatoria?","o":["Un carro a su nombre","Un trabajo de medio tiempo","Un adulto patrocinador","Un diploma de secundaria"],"h1":"Un adulto debe hacerse responsable del joven conductor.","h2":"Un joven de Wisconsin que solicita la licencia probatoria debe tener por lo menos 16 años, terminar un curso de manejo aprobado y tener un adulto patrocinador.","p":"Correcto. Se necesita un adulto patrocinador."},"zh":{"q":"在 Wisconsin，除了驾驶教育课程，青少年申请试用驾照还需要什么？","o":["一辆登记在自己名下的车","一份兼职工作","一位成年担保人（adult sponsor）","高中毕业证书"],"h1":"必须有一个成年人为这个青少年司机负责。","h2":"在 Wisconsin，申请试用驾照的青少年必须年满 16 岁，完成认可的驾驶教育课程，并有一位成年担保人。","p":"对。需要一位成年担保人。"},"vi":{"q":"Ở Wisconsin, ngoài khóa học lái xe, thiếu niên còn cần gì để xin bằng lái tạm thời?","o":["Một chiếc xe đứng tên mình","Một công việc bán thời gian","Một người lớn bảo lãnh (adult sponsor)","Bằng tốt nghiệp trung học"],"h1":"Một người lớn phải chịu trách nhiệm cho tài xế thiếu niên.","h2":"Ở Wisconsin, thiếu niên xin bằng lái tạm thời phải ít nhất 16 tuổi, hoàn thành khóa học lái xe được chấp thuận, và có một người lớn bảo lãnh.","p":"Đúng. Cần có một người lớn bảo lãnh."},"tl":{"q":"Sa Wisconsin, bukod sa driver education, ano pa ang kailangan ng isang teen para mag-apply ng probationary license?","o":["Kotseng nakapangalan sa kanya","Part-time na trabaho","Isang adult sponsor","High school diploma"],"h1":"Isang adult ang dapat managot para sa batang driver.","h2":"Ang teen sa Wisconsin na nag-a-apply ng probationary license ay dapat hindi bababa sa 16 taong gulang, tapos sa aprubadong driver education course, at may adult sponsor.","p":"Tama. Kailangan ng adult sponsor."},"ar":{"q":"في Wisconsin، بالإضافة إلى دورة تعليم القيادة، ماذا يحتاج المراهق أيضًا ليتقدم لرخصة القيادة التجريبية؟","o":["سيارة باسمه","عمل بدوام جزئي","شخص بالغ كفيل (adult sponsor)","شهادة الثانوية"],"h1":"يجب أن يتحمل شخص بالغ المسؤولية عن السائق المراهق.","h2":"المراهق في Wisconsin الذي يتقدم لرخصة القيادة التجريبية يجب أن يكون عمره 16 على الأقل، وأن يُنهي دورة معتمدة لتعليم القيادة، وأن يكون له شخص بالغ كفيل.","p":"صحيح. يجب وجود شخص بالغ كفيل."},"ref":{"doc":"WI","page":3}},{"id":"wi-008","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, during daylight, how old must the licensed adult be who rides with an instruction permit holder, when not a parent or instructor?","o":["18","21","16","30"],"h1":"The adult must be old enough to drink legally.","h2":"In Wisconsin a permit holder may practice by day with a licensed adult who is at least 21 and has at least two years of driving experience; after dark the adult must be at least 25.","p":"Right. The adult must be 21 or older."},"es":{"q":"En Wisconsin, de día, ¿qué edad debe tener el adulto con licencia que acompaña a un conductor con permiso, si no es un padre ni un instructor?","o":["18","21","16","30"],"h1":"El adulto debe tener edad para tomar alcohol legalmente.","h2":"En Wisconsin un conductor con permiso puede practicar de día con un adulto con licencia que tenga por lo menos 21 años y por lo menos dos años de experiencia manejando; de noche el adulto debe tener por lo menos 25 años.","p":"Correcto. El adulto debe tener 21 años o más."},"zh":{"q":"在 Wisconsin，白天陪学习驾照持有人开车的有驾照的成年人，如果不是父母或教练，必须几岁？","o":["18","21","16","30"],"h1":"这个成年人必须到了可以合法喝酒的年龄。","h2":"在 Wisconsin，学习驾照持有人白天可以和一位至少 21 岁、至少有两年驾驶经验、有驾照的成年人一起练车；天黑后，这个成年人必须至少 25 岁。","p":"对。这个成年人必须 21 岁或以上。"},"vi":{"q":"Ở Wisconsin, vào ban ngày, người lớn có bằng lái đi cùng người có giấy phép tập lái phải bao nhiêu tuổi, nếu không phải là cha mẹ hay người hướng dẫn?","o":["18","21","16","30"],"h1":"Người lớn đó phải đủ tuổi uống rượu hợp pháp.","h2":"Ở Wisconsin, người có giấy phép tập lái có thể tập lái ban ngày với một người lớn có bằng lái, ít nhất 21 tuổi và có ít nhất hai năm kinh nghiệm lái xe; sau khi trời tối, người lớn đó phải ít nhất 25 tuổi.","p":"Đúng. Người lớn phải từ 21 tuổi trở lên."},"tl":{"q":"Sa Wisconsin, sa araw, ilang taon dapat ang adult na may lisensya na kasama ng may instruction permit, kung hindi siya magulang o instructor?","o":["18","21","16","30"],"h1":"Dapat nasa edad na ang adult para legal na uminom ng alak.","h2":"Sa Wisconsin, ang may permit ay puwedeng magsanay sa araw kasama ang adult na may lisensya na hindi bababa sa 21 taong gulang at may hindi bababa sa dalawang taong karanasan sa pagmamaneho; pagdilim, ang adult ay dapat hindi bababa sa 25.","p":"Tama. Ang adult ay dapat 21 o mas matanda."},"ar":{"q":"في Wisconsin، في النهار، كم يجب أن يكون عمر الشخص البالغ الذي معه رخصة ويركب مع حامل تصريح التعلم، إذا لم يكن أحد الوالدين أو مدربًا؟","o":["18","21","16","30"],"h1":"يجب أن يكون البالغ في السن القانونية لشرب الكحول.","h2":"في Wisconsin يمكن لحامل التصريح أن يتدرب في النهار مع شخص بالغ معه رخصة، عمره 21 على الأقل، وله خبرة قيادة سنتين على الأقل؛ وبعد حلول الظلام يجب أن يكون عمر البالغ 25 على الأقل.","p":"صحيح. يجب أن يكون عمر البالغ 21 أو أكثر."},"ref":{"doc":"WI","page":5}},{"id":"wi-009","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, who may ride with a probationary driver under 18 who is driving alone?","o":["No passengers at all","Only one family member","Up to three friends","Any number of immediate family and one other person"],"h1":"Family is treated differently from friends.","h2":"A Wisconsin probationary driver under 18 may carry any number of immediate family members and one other person; a qualified licensed adult may also ride along.","p":"Right. Immediate family plus one other person."},"es":{"q":"En Wisconsin, ¿quién puede viajar con un conductor con licencia probatoria menor de 18 años que maneja solo?","o":["Ningún pasajero","Solo un familiar","Hasta tres amigos","Cualquier número de familiares directos y una persona más"],"h1":"La familia se trata diferente que los amigos.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede llevar a cualquier número de familiares directos y a una persona más; también puede ir un adulto con licencia que cumpla los requisitos.","p":"Correcto. Familiares directos y una persona más."},"zh":{"q":"在 Wisconsin，18 岁以下的试用驾照司机单独开车时，谁可以坐在车上？","o":["完全不能有乘客","只能有一位家人","最多三个朋友","任何数量的直系家人，再加一个其他人"],"h1":"家人和朋友的规定不一样。","h2":"在 Wisconsin，18 岁以下的试用驾照司机可以载任何数量的直系家人，再加一个其他人；合格的有驾照成年人也可以同车。","p":"对。直系家人再加一个其他人。"},"vi":{"q":"Ở Wisconsin, ai có thể đi cùng tài xế có bằng lái tạm thời dưới 18 tuổi khi người đó lái một mình?","o":["Không có hành khách nào cả","Chỉ một người trong gia đình","Tối đa ba người bạn","Bất kỳ số người thân trong gia đình nào và thêm một người khác"],"h1":"Gia đình được đối xử khác với bạn bè.","h2":"Ở Wisconsin, tài xế có bằng lái tạm thời dưới 18 tuổi có thể chở bất kỳ số người thân trong gia đình nào và thêm một người khác; một người lớn có bằng lái đủ điều kiện cũng có thể đi cùng.","p":"Đúng. Người thân trong gia đình và thêm một người khác."},"tl":{"q":"Sa Wisconsin, sino ang puwedeng sumakay kasama ng probationary driver na wala pang 18 na nagmamaneho nang mag-isa?","o":["Walang pasahero","Isang miyembro lang ng pamilya","Hanggang tatlong kaibigan","Kahit ilang malapit na kapamilya at isa pang tao"],"h1":"Iba ang turing sa pamilya kaysa sa mga kaibigan.","h2":"Ang probationary driver sa Wisconsin na wala pang 18 ay puwedeng magsakay ng kahit ilang malapit na kapamilya at isa pang tao; puwede ring sumakay ang isang kwalipikadong adult na may lisensya.","p":"Tama. Malapit na kapamilya at isa pang tao."},"ar":{"q":"في Wisconsin، من يمكنه الركوب مع سائق برخصة تجريبية عمره أقل من 18 يقود وحده؟","o":["لا ركاب أبدًا","فرد واحد فقط من العائلة","حتى ثلاثة أصدقاء","أي عدد من أفراد العائلة المقربين وشخص واحد آخر"],"h1":"العائلة تُعامَل بشكل مختلف عن الأصدقاء.","h2":"السائق برخصة تجريبية في Wisconsin الذي عمره أقل من 18 يمكنه أن ينقل أي عدد من أفراد العائلة المقربين وشخصًا واحدًا آخر؛ ويمكن أيضًا أن يركب معه شخص بالغ مؤهل معه رخصة.","p":"صحيح. العائلة المقربة وشخص واحد آخر."},"ref":{"doc":"WI","page":6}},{"id":"wi-010","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, between midnight and 5 a.m., where may a probationary driver under 18 drive alone?","o":["Only between home, school and work","Anywhere","Only on highways","Nowhere, even for work"],"h1":"Think of the places a teen must get to.","h2":"A Wisconsin probationary driver under 18 may drive alone from midnight to 5 a.m. only between home, school and work.","p":"Right. Only between home, school and work."},"es":{"q":"En Wisconsin, entre medianoche y las 5 a.m., ¿a dónde puede manejar solo un conductor con licencia probatoria menor de 18 años?","o":["Solo entre la casa, la escuela y el trabajo","A cualquier lugar","Solo por autopistas","A ningún lugar, ni siquiera al trabajo"],"h1":"Piense en los lugares a los que un joven tiene que llegar.","h2":"Un conductor con licencia probatoria menor de 18 años en Wisconsin puede manejar solo de medianoche a 5 a.m. únicamente entre la casa, la escuela y el trabajo.","p":"Correcto. Solo entre la casa, la escuela y el trabajo."},"zh":{"q":"在 Wisconsin，午夜到早上 5 点之间，18 岁以下的试用驾照司机可以单独开车去哪里？","o":["只能在家、学校和工作地点之间","任何地方","只能在高速公路上","哪里都不行，上班也不行"],"h1":"想一想青少年必须去的地方。","h2":"在 Wisconsin，18 岁以下的试用驾照司机在午夜到早上 5 点之间，只能在家、学校和工作地点之间单独开车。","p":"对。只能在家、学校和工作地点之间。"},"vi":{"q":"Ở Wisconsin, từ nửa đêm đến 5 giờ sáng, tài xế có bằng lái tạm thời dưới 18 tuổi được lái một mình đi đâu?","o":["Chỉ giữa nhà, trường học và nơi làm việc","Bất cứ đâu","Chỉ trên đường cao tốc","Không được đi đâu cả, kể cả đi làm"],"h1":"Hãy nghĩ đến những nơi thiếu niên phải đến.","h2":"Ở Wisconsin, tài xế có bằng lái tạm thời dưới 18 tuổi chỉ được lái một mình từ nửa đêm đến 5 giờ sáng giữa nhà, trường học và nơi làm việc.","p":"Đúng. Chỉ giữa nhà, trường học và nơi làm việc."},"tl":{"q":"Sa Wisconsin, mula hatinggabi hanggang 5 a.m., saan puwedeng magmaneho nang mag-isa ang probationary driver na wala pang 18?","o":["Sa pagitan lang ng bahay, paaralan at trabaho","Kahit saan","Sa highway lang","Wala, kahit papunta sa trabaho"],"h1":"Isipin ang mga lugar na kailangang puntahan ng isang teen.","h2":"Ang probationary driver sa Wisconsin na wala pang 18 ay puwedeng magmaneho nang mag-isa mula hatinggabi hanggang 5 a.m. sa pagitan lang ng bahay, paaralan at trabaho.","p":"Tama. Sa pagitan lang ng bahay, paaralan at trabaho."},"ar":{"q":"في Wisconsin، بين منتصف الليل و5 صباحًا، أين يمكن للسائق برخصة تجريبية الذي عمره أقل من 18 أن يقود وحده؟","o":["فقط بين البيت والمدرسة والعمل","في أي مكان","على الطرق السريعة فقط","لا مكان، حتى للعمل"],"h1":"فكّر في الأماكن التي يجب أن يصل إليها المراهق.","h2":"السائق برخصة تجريبية في Wisconsin الذي عمره أقل من 18 يمكنه أن يقود وحده من منتصف الليل حتى 5 صباحًا فقط بين البيت والمدرسة والعمل.","p":"صحيح. فقط بين البيت والمدرسة والعمل."},"ref":{"doc":"WI","page":7}},{"id":"wi-011","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, may a driver with an instruction permit or probationary license use a hands-free phone while driving?","o":["Yes, hands-free is allowed","No, except to report an emergency","Yes, but only on highways","Yes, if a parent says so"],"h1":"The rule covers every kind of phone, not only hand-held.","h2":"A Wisconsin driver with an instruction permit or probationary license may not use any phone while driving, hand-held or hands-free, except to report an emergency.","p":"Right. Only for an emergency."},"es":{"q":"En Wisconsin, ¿puede un conductor con permiso de aprendiz o licencia probatoria usar un teléfono manos libres mientras maneja?","o":["Sí, el manos libres está permitido","No, excepto para reportar una emergencia","Sí, pero solo en autopistas","Sí, si un padre lo autoriza"],"h1":"La regla cubre todo tipo de teléfono, no solo en la mano.","h2":"Un conductor de Wisconsin con permiso de aprendiz o licencia probatoria no puede usar ningún teléfono mientras maneja, ni en la mano ni con manos libres, excepto para reportar una emergencia.","p":"Correcto. Solo en una emergencia."},"zh":{"q":"在 Wisconsin，持学习驾照或试用驾照的司机开车时可以用免提电话吗？","o":["可以，免提是允许的","不可以，报告紧急情况除外","可以，但只能在高速公路上","可以，如果父母同意"],"h1":"这条规定包括所有电话，不只是手持电话。","h2":"在 Wisconsin，持学习驾照或试用驾照的司机开车时不能使用任何电话，手持或免提都不行，只有报告紧急情况时除外。","p":"对。只有紧急情况可以。"},"vi":{"q":"Ở Wisconsin, tài xế có giấy phép tập lái hoặc bằng lái tạm thời có được dùng điện thoại rảnh tay khi lái xe không?","o":["Có, được dùng rảnh tay","Không, trừ khi báo trường hợp khẩn cấp","Có, nhưng chỉ trên đường cao tốc","Có, nếu cha mẹ cho phép"],"h1":"Quy định này áp dụng cho mọi loại điện thoại, không chỉ điện thoại cầm tay.","h2":"Ở Wisconsin, tài xế có giấy phép tập lái hoặc bằng lái tạm thời không được dùng bất kỳ điện thoại nào khi lái xe, cầm tay hay rảnh tay, trừ khi báo trường hợp khẩn cấp.","p":"Đúng. Chỉ khi khẩn cấp."},"tl":{"q":"Sa Wisconsin, puwede bang gumamit ng hands-free na telepono habang nagmamaneho ang driver na may instruction permit o probationary license?","o":["Oo, puwede ang hands-free","Hindi, maliban kung mag-uulat ng emergency","Oo, pero sa highway lang","Oo, kung payag ang magulang"],"h1":"Sakop ng patakaran ang lahat ng uri ng telepono, hindi lang ang hawak sa kamay.","h2":"Ang driver sa Wisconsin na may instruction permit o probationary license ay hindi puwedeng gumamit ng anumang telepono habang nagmamaneho, hawak man o hands-free, maliban kung mag-uulat ng emergency.","p":"Tama. Para lang sa emergency."},"ar":{"q":"في Wisconsin، هل يمكن للسائق الذي معه تصريح تعلم أو رخصة تجريبية أن يستخدم هاتفًا بدون يدين (hands-free) أثناء القيادة؟","o":["نعم، الهاتف بدون يدين مسموح","لا، إلا للإبلاغ عن حالة طوارئ","نعم، لكن على الطرق السريعة فقط","نعم، إذا وافق أحد الوالدين"],"h1":"القاعدة تشمل كل أنواع الهواتف، وليس فقط الهاتف في اليد.","h2":"السائق في Wisconsin الذي معه تصريح تعلم أو رخصة تجريبية لا يمكنه استخدام أي هاتف أثناء القيادة، في اليد أو بدون يدين، إلا للإبلاغ عن حالة طوارئ.","p":"صحيح. فقط في حالة الطوارئ."},"ref":{"doc":"WI","page":49}},{"id":"wi-012","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, on a road with two or more lanes going your way, what does the Move Over law tell you to do for a stopped emergency vehicle with flashing lights?","o":["Stop behind it","Keep your lane and speed","Move out of the lane closest to it, or slow down if you cannot","Turn on your hazard lights and pass"],"h1":"Give the stopped vehicle a whole empty lane if you can.","h2":"Wisconsin's Move Over law says to move out of the lane closest to a stopped emergency or maintenance vehicle with flashing lights, or to slow down if you cannot move over safely.","p":"Right. Move over, or slow down if you cannot."},"es":{"q":"En Wisconsin, en un camino con dos o más carriles en su sentido, ¿qué le indica la ley de \"Move Over\" ante un vehículo de emergencia detenido con luces encendidas?","o":["Detenerse detrás de él","Seguir en su carril y a su velocidad","Salir del carril más cercano a él, o bajar la velocidad si no puede","Encender sus luces intermitentes y pasar"],"h1":"Si puede, déjele un carril completo libre al vehículo detenido.","h2":"La ley de \"Move Over\" de Wisconsin dice que debe salir del carril más cercano a un vehículo de emergencia o mantenimiento detenido con luces encendidas, o bajar la velocidad si no puede cambiarse con seguridad.","p":"Correcto. Cámbiese de carril, o baje la velocidad si no puede."},"zh":{"q":"在 Wisconsin，在你的方向有两条或更多车道的路上，对于停着并闪灯的紧急车辆，让道法（Move Over law）要求你怎么做？","o":["停在它后面","保持你的车道和速度","离开最靠近它的车道，如果做不到就减速","打开双闪灯然后超过去"],"h1":"如果可以，给停着的车留出一整条空车道。","h2":"Wisconsin 的让道法（Move Over law）规定，要离开最靠近停着并闪灯的紧急车辆或养护车辆的车道；如果不能安全变道，就要减速。","p":"对。让道，如果做不到就减速。"},"vi":{"q":"Ở Wisconsin, trên con đường có hai làn trở lên cùng chiều với bạn, luật Nhường Làn (Move Over law) bảo bạn làm gì khi có xe cấp cứu đang dừng và nháy đèn?","o":["Dừng lại phía sau xe đó","Giữ nguyên làn và tốc độ","Rời khỏi làn gần xe đó nhất, hoặc giảm tốc độ nếu không thể","Bật đèn khẩn cấp và vượt qua"],"h1":"Hãy chừa cho xe đang dừng cả một làn trống nếu có thể.","h2":"Luật Nhường Làn (Move Over law) của Wisconsin nói phải rời khỏi làn gần nhất với xe cấp cứu hoặc xe bảo trì đang dừng và nháy đèn, hoặc giảm tốc độ nếu bạn không thể chuyển làn an toàn.","p":"Đúng. Chuyển làn, hoặc giảm tốc độ nếu không thể."},"tl":{"q":"Sa Wisconsin, sa daan na may dalawa o higit pang lane papunta sa direksyon mo, ano ang sinasabi ng Move Over law na gawin mo para sa nakahintong emergency vehicle na may kumikislap na ilaw?","o":["Huminto sa likod nito","Manatili sa lane mo at sa bilis mo","Lumipat mula sa lane na pinakamalapit dito, o bumagal kung hindi mo kaya","Buksan ang hazard lights at lumampas"],"h1":"Bigyan ang nakahintong sasakyan ng isang buong bakanteng lane kung kaya mo.","h2":"Sinasabi ng Move Over law ng Wisconsin na lumipat mula sa lane na pinakamalapit sa nakahintong emergency o maintenance vehicle na may kumikislap na ilaw, o bumagal kung hindi ka ligtas na makalipat.","p":"Tama. Lumipat, o bumagal kung hindi mo kaya."},"ar":{"q":"في Wisconsin، على طريق فيه حارتان أو أكثر في اتجاهك، ماذا يطلب منك قانون الابتعاد (Move Over law) أن تفعل عند مركبة طوارئ متوقفة وأضواؤها تومض؟","o":["توقف خلفها","ابقَ في حارتك وعلى سرعتك","اخرج من الحارة الأقرب إليها، أو خفّف السرعة إذا لم تستطع","شغّل أضواء التحذير وتجاوزها"],"h1":"اترك للمركبة المتوقفة حارة كاملة فارغة إذا استطعت.","h2":"قانون الابتعاد (Move Over law) في Wisconsin يقول أن تخرج من الحارة الأقرب إلى مركبة الطوارئ أو الصيانة المتوقفة وأضواؤها تومض، أو أن تخفّف السرعة إذا لم تستطع تغيير الحارة بأمان.","p":"صحيح. ابتعد، أو خفّف السرعة إذا لم تستطع."},"ref":{"doc":"WI","page":51}},{"id":"wi-013","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, what was added to the Move Over law by 2025 Wisconsin Act 54?","o":["Disabled vehicles","Parked bicycles","Mail trucks only","Nothing was added"],"h1":"Think of a car stopped on the shoulder after breaking down.","h2":"Since 2025 Wisconsin Act 54, the Move Over law also protects disabled vehicles stopped along the road.","p":"Right. Disabled vehicles are now covered."},"es":{"q":"En Wisconsin, ¿qué se agregó a la ley de \"Move Over\" con la Ley 54 de Wisconsin de 2025?","o":["Vehículos descompuestos","Bicicletas estacionadas","Solo camiones del correo","No se agregó nada"],"h1":"Piense en un carro detenido en el acotamiento porque se descompuso.","h2":"Desde la Ley 54 de Wisconsin de 2025, la ley de \"Move Over\" también protege a los vehículos descompuestos detenidos a un lado del camino.","p":"Correcto. Los vehículos descompuestos ahora están cubiertos."},"zh":{"q":"在 Wisconsin，2025 Wisconsin Act 54 给让道法（Move Over law）增加了什么？","o":["故障车辆","停着的自行车","只有邮政卡车","什么都没增加"],"h1":"想一想车坏了以后停在路肩上的车。","h2":"自从 2025 Wisconsin Act 54 以后，让道法也保护停在路边的故障车辆。","p":"对。现在故障车辆也受保护。"},"vi":{"q":"Ở Wisconsin, 2025 Wisconsin Act 54 đã thêm gì vào luật Nhường Làn (Move Over law)?","o":["Xe bị hư","Xe đạp đang đậu","Chỉ xe chở thư","Không thêm gì cả"],"h1":"Hãy nghĩ đến chiếc xe dừng bên lề đường sau khi bị hư.","h2":"Từ khi có 2025 Wisconsin Act 54, luật Nhường Làn cũng bảo vệ các xe bị hư đang dừng bên đường.","p":"Đúng. Xe bị hư nay cũng được bảo vệ."},"tl":{"q":"Sa Wisconsin, ano ang idinagdag sa Move Over law ng 2025 Wisconsin Act 54?","o":["Mga sirang sasakyan","Mga nakaparadang bisikleta","Mga mail truck lang","Walang idinagdag"],"h1":"Isipin ang kotseng nakahinto sa gilid ng daan dahil nasira.","h2":"Mula sa 2025 Wisconsin Act 54, pinoprotektahan na rin ng Move Over law ang mga sirang sasakyan na nakahinto sa tabi ng daan.","p":"Tama. Sakop na ngayon ang mga sirang sasakyan."},"ar":{"q":"في Wisconsin، ماذا أضاف 2025 Wisconsin Act 54 إلى قانون الابتعاد (Move Over law)؟","o":["المركبات المعطّلة","الدراجات المتوقفة","شاحنات البريد فقط","لم يُضَف شيء"],"h1":"فكّر في سيارة متوقفة على كتف الطريق بعد أن تعطّلت.","h2":"منذ 2025 Wisconsin Act 54، يحمي قانون الابتعاد أيضًا المركبات المعطّلة المتوقفة على جانب الطريق.","p":"صحيح. المركبات المعطّلة مشمولة الآن."},"ref":{"doc":"WI","page":null}},{"id":"wi-014","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how much alcohol may a driver under 21 have in the blood?","o":["Up to 0.08","Up to 0.04","Up to 0.02","None at all"],"h1":"Wisconsin calls this the absolute sobriety law.","h2":"Under Wisconsin's absolute sobriety law, a driver under 21 may not drive with any alcohol in the blood.","p":"Right. Under 21, no alcohol at all."},"es":{"q":"En Wisconsin, ¿cuánto alcohol puede tener en la sangre un conductor menor de 21 años?","o":["Hasta 0.08","Hasta 0.04","Hasta 0.02","Nada de alcohol"],"h1":"Wisconsin llama a esto la ley de sobriedad absoluta.","h2":"Según la ley de sobriedad absoluta de Wisconsin, un conductor menor de 21 años no puede manejar con nada de alcohol en la sangre.","p":"Correcto. Menor de 21, nada de alcohol."},"zh":{"q":"在 Wisconsin，21 岁以下的司机血液中可以有多少酒精？","o":["最多 0.08","最多 0.04","最多 0.02","完全不可以有"],"h1":"Wisconsin 把这叫做绝对清醒法（absolute sobriety law）。","h2":"根据 Wisconsin 的绝对清醒法，21 岁以下的司机血液中有任何酒精都不能开车。","p":"对。21 岁以下，完全不能有酒精。"},"vi":{"q":"Ở Wisconsin, tài xế dưới 21 tuổi được có bao nhiêu cồn trong máu?","o":["Tối đa 0.08","Tối đa 0.04","Tối đa 0.02","Hoàn toàn không có"],"h1":"Wisconsin gọi đây là luật tỉnh táo tuyệt đối (absolute sobriety law).","h2":"Theo luật tỉnh táo tuyệt đối của Wisconsin, tài xế dưới 21 tuổi không được lái xe khi có bất kỳ chút cồn nào trong máu.","p":"Đúng. Dưới 21 tuổi, hoàn toàn không có cồn."},"tl":{"q":"Sa Wisconsin, gaano karaming alak ang puwedeng nasa dugo ng driver na wala pang 21?","o":["Hanggang 0.08","Hanggang 0.04","Hanggang 0.02","Wala talaga"],"h1":"Tinatawag ito ng Wisconsin na absolute sobriety law.","h2":"Sa ilalim ng absolute sobriety law ng Wisconsin, ang driver na wala pang 21 ay hindi puwedeng magmaneho nang may kahit anong alak sa dugo.","p":"Tama. Wala pang 21, walang alak talaga."},"ar":{"q":"في Wisconsin، كم من الكحول يمكن أن يكون في دم السائق الذي عمره أقل من 21؟","o":["حتى 0.08","حتى 0.04","حتى 0.02","لا شيء أبدًا"],"h1":"تسمّي Wisconsin هذا قانون الامتناع التام (absolute sobriety law).","h2":"حسب قانون الامتناع التام في Wisconsin، لا يمكن للسائق الذي عمره أقل من 21 أن يقود وفي دمه أي كمية من الكحول.","p":"صحيح. أقل من 21، لا كحول أبدًا."},"ref":{"doc":"WI","page":49}},{"id":"wi-015","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the penalty for breaking the absolute sobriety law?","o":["A warning only","A 3-month suspension, a $200 forfeiture and 4 points","Ten years in prison","A $5 fine"],"h1":"It includes a suspension of a quarter of a year.","h2":"Breaking Wisconsin's absolute sobriety law brings a three-month suspension, a $200 forfeiture and four points on your record.","p":"Right. Three months, $200 and four points."},"es":{"q":"En Wisconsin, ¿cuál es la sanción por no cumplir la ley de sobriedad absoluta?","o":["Solo una advertencia","Una suspensión de 3 meses, una multa de $200 y 4 puntos","Diez años de cárcel","Una multa de $5"],"h1":"Incluye una suspensión de la cuarta parte de un año.","h2":"No cumplir la ley de sobriedad absoluta de Wisconsin trae una suspensión de tres meses, una multa de $200 y cuatro puntos en su historial.","p":"Correcto. Tres meses, $200 y cuatro puntos."},"zh":{"q":"在 Wisconsin，违反绝对清醒法（absolute sobriety law）会受到什么处罚？","o":["只有警告","吊销驾照 3 个月，罚款 $200，记 4 分","坐牢十年","罚款 $5"],"h1":"它包括吊销驾照四分之一年。","h2":"违反 Wisconsin 的绝对清醒法会被吊销驾照三个月，罚款 $200，并在你的记录上记四分。","p":"对。三个月，$200，四分。"},"vi":{"q":"Ở Wisconsin, hình phạt khi vi phạm luật tỉnh táo tuyệt đối (absolute sobriety law) là gì?","o":["Chỉ cảnh cáo","Treo bằng 3 tháng, phạt $200 và 4 điểm","Mười năm tù","Phạt $5"],"h1":"Nó gồm việc treo bằng một phần tư năm.","h2":"Vi phạm luật tỉnh táo tuyệt đối của Wisconsin sẽ bị treo bằng ba tháng, phạt $200 và bốn điểm trong hồ sơ của bạn.","p":"Đúng. Ba tháng, $200 và bốn điểm."},"tl":{"q":"Sa Wisconsin, ano ang parusa sa paglabag sa absolute sobriety law?","o":["Babala lang","3 buwang suspensyon, $200 na multa (forfeiture) at 4 na puntos","Sampung taon sa kulungan","$5 na multa"],"h1":"Kasama dito ang suspensyon na isang-kapat ng taon.","h2":"Ang paglabag sa absolute sobriety law ng Wisconsin ay may tatlong buwang suspensyon, $200 na multa (forfeiture) at apat na puntos sa iyong record.","p":"Tama. Tatlong buwan, $200 at apat na puntos."},"ar":{"q":"في Wisconsin، ما عقوبة مخالفة قانون الامتناع التام (absolute sobriety law)؟","o":["تحذير فقط","إيقاف الرخصة 3 أشهر، وغرامة $200، و4 نقاط","عشر سنوات في السجن","غرامة $5"],"h1":"تشمل إيقاف الرخصة ربع سنة.","h2":"مخالفة قانون الامتناع التام في Wisconsin تؤدي إلى إيقاف الرخصة ثلاثة أشهر، وغرامة $200، وأربع نقاط في سجلك.","p":"صحيح. ثلاثة أشهر، و$200، وأربع نقاط."},"ref":{"doc":"WI","page":null}},{"id":"wi-016","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how is a first drunk driving (OWI) offense with no aggravating factors treated?","o":["As a felony","As a misdemeanor crime","As a civil violation, not a crime","It is not punished"],"h1":"Wisconsin is unusual among the states on this point.","h2":"In Wisconsin a first OWI offense is a civil violation rather than a crime, but it still brings a forfeiture and loss of your license.","p":"Right. A first OWI is a civil violation in Wisconsin."},"es":{"q":"En Wisconsin, ¿cómo se trata una primera infracción de manejar bajo los efectos del alcohol (OWI) sin agravantes?","o":["Como delito grave","Como delito menor","Como infracción civil, no como delito","No se castiga"],"h1":"Wisconsin es poco común entre los estados en este punto.","h2":"En Wisconsin una primera infracción OWI es una infracción civil y no un delito, pero aun así trae una multa y la pérdida de la licencia.","p":"Correcto. Una primera OWI es una infracción civil en Wisconsin."},"zh":{"q":"在 Wisconsin，第一次酒后驾驶（OWI），而且没有加重情节，会被怎样对待？","o":["当作重罪","当作轻罪","当作民事违规，不是犯罪","不会受到处罚"],"h1":"在这一点上，Wisconsin 和其他州很不一样。","h2":"在 Wisconsin，第一次 OWI 是民事违规，不是犯罪，但仍然会被罚款并失去驾照。","p":"对。在 Wisconsin，第一次 OWI 是民事违规。"},"vi":{"q":"Ở Wisconsin, lần đầu lái xe khi say rượu (OWI) mà không có tình tiết tăng nặng được xử lý thế nào?","o":["Là trọng tội","Là tội nhẹ","Là vi phạm dân sự, không phải tội phạm","Không bị phạt"],"h1":"Wisconsin khác thường so với các tiểu bang khác ở điểm này.","h2":"Ở Wisconsin, lần đầu phạm OWI là vi phạm dân sự chứ không phải tội phạm, nhưng vẫn bị phạt tiền và mất bằng lái.","p":"Đúng. Lần đầu phạm OWI ở Wisconsin là vi phạm dân sự."},"tl":{"q":"Sa Wisconsin, paano itinuturing ang unang paglabag sa pagmamaneho nang lasing (OWI) na walang nagpapabigat na dahilan?","o":["Bilang felony","Bilang misdemeanor na krimen","Bilang civil violation, hindi krimen","Hindi ito pinaparusahan"],"h1":"Kakaiba ang Wisconsin kumpara sa ibang estado sa puntong ito.","h2":"Sa Wisconsin, ang unang OWI ay civil violation at hindi krimen, pero may multa pa rin ito at mawawala ang iyong lisensya.","p":"Tama. Ang unang OWI ay civil violation sa Wisconsin."},"ar":{"q":"في Wisconsin، كيف تُعامَل أول مخالفة قيادة تحت تأثير الكحول (OWI) بدون ظروف مشدِّدة؟","o":["كجناية","كجنحة","كمخالفة مدنية، وليست جريمة","لا عقوبة عليها"],"h1":"Wisconsin غير عادية بين الولايات في هذه النقطة.","h2":"في Wisconsin أول مخالفة OWI هي مخالفة مدنية وليست جريمة، لكنها مع ذلك تؤدي إلى غرامة وفقدان رخصتك.","p":"صحيح. أول OWI مخالفة مدنية في Wisconsin."},"ref":{"doc":"WI","page":null}},{"id":"wi-017","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, unless posted otherwise, what is the speed limit when passing a school while children are going to or from school?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"It is lower than 20.","h2":"Unless a different limit is posted, Wisconsin sets 15 miles per hour when passing a school while children are going to or from school or playing near it.","p":"Right. 15 mph near schools when children are present."},"es":{"q":"En Wisconsin, si no hay otro límite indicado, ¿cuál es el límite al pasar por una escuela mientras los niños llegan o salen?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Es menos de 20.","h2":"Si no hay otro límite indicado, Wisconsin fija 15 millas por hora al pasar por una escuela mientras los niños llegan, salen o juegan cerca.","p":"Correcto. 15 mph cerca de escuelas cuando hay niños."},"zh":{"q":"在 Wisconsin，如果没有其他标示，孩子上学或放学时经过学校，限速是多少？","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"它比 20 低。","h2":"如果没有标示其他限速，Wisconsin 规定在孩子上学、放学或在附近玩耍时经过学校，限速是每小时 15 英里。","p":"对。有孩子时学校附近限速 15 mph。"},"vi":{"q":"Ở Wisconsin, nếu không có biển báo khác, tốc độ tối đa khi đi qua trường học lúc trẻ em đang đi học hoặc tan học là bao nhiêu?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Nó thấp hơn 20.","h2":"Nếu không có biển báo tốc độ khác, Wisconsin quy định 15 dặm một giờ khi đi qua trường học lúc trẻ em đang đi học, tan học hoặc chơi gần đó.","p":"Đúng. 15 mph gần trường học khi có trẻ em."},"tl":{"q":"Sa Wisconsin, kung walang ibang nakapaskil, ano ang speed limit kapag dumadaan sa paaralan habang papasok o pauwi ang mga bata?","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"Mas mababa ito sa 20.","h2":"Kung walang ibang limit na nakapaskil, 15 milya bawat oras ang itinakda ng Wisconsin kapag dumadaan sa paaralan habang papasok o pauwi ang mga bata o naglalaro malapit dito.","p":"Tama. 15 mph malapit sa paaralan kapag may mga bata."},"ar":{"q":"في Wisconsin، إذا لم توجد لافتة بحد آخر، ما حد السرعة عند المرور بجانب مدرسة أثناء ذهاب الأطفال إلى المدرسة أو عودتهم منها؟","o":["25 mph","30 mph","20 mph","15 mph"],"h1":"هو أقل من 20.","h2":"إذا لم توجد لافتة بحد آخر، تحدد Wisconsin سرعة 15 ميلًا في الساعة عند المرور بجانب مدرسة أثناء ذهاب الأطفال إليها أو عودتهم منها أو لعبهم قربها.","p":"صحيح. 15 mph قرب المدارس عند وجود الأطفال."},"ref":{"doc":"WI","page":10}},{"id":"wi-018","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the highest speed limit that may be posted on some freeways?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is five more than 65.","h2":"Wisconsin law allows a speed limit of 70 miles per hour on freeways where signs post it.","p":"Right. Some Wisconsin freeways are posted at 70 mph."},"es":{"q":"En Wisconsin, ¿cuál es el límite de velocidad más alto que se puede indicar en algunas autopistas?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Es cinco más que 65.","h2":"La ley de Wisconsin permite un límite de 70 millas por hora en las autopistas donde las señales lo indican.","p":"Correcto. Algunas autopistas de Wisconsin están indicadas a 70 mph."},"zh":{"q":"在 Wisconsin，一些高速公路上可以标示的最高限速是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它比 65 多五。","h2":"Wisconsin 法律允许在有标志的高速公路上限速每小时 70 英里。","p":"对。Wisconsin 一些高速公路标示 70 mph。"},"vi":{"q":"Ở Wisconsin, tốc độ tối đa cao nhất có thể được ghi trên một số xa lộ là bao nhiêu?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Nó nhiều hơn 65 năm đơn vị.","h2":"Luật Wisconsin cho phép tốc độ tối đa 70 dặm một giờ trên các xa lộ có biển báo ghi như vậy.","p":"Đúng. Một số xa lộ ở Wisconsin ghi 70 mph."},"tl":{"q":"Sa Wisconsin, ano ang pinakamataas na speed limit na puwedeng ipaskil sa ilang freeway?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Ito ay lima pa kaysa 65.","h2":"Pinapayagan ng batas ng Wisconsin ang speed limit na 70 milya bawat oras sa mga freeway kung saan ito nakapaskil.","p":"Tama. May mga freeway sa Wisconsin na naka-post na 70 mph."},"ar":{"q":"في Wisconsin، ما أعلى حد للسرعة يمكن وضعه على بعض الطرق السريعة؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"هو أكثر من 65 بخمسة.","h2":"قانون Wisconsin يسمح بحد سرعة 70 ميلًا في الساعة على الطرق السريعة التي توجد عليها لافتات بذلك.","p":"صحيح. بعض الطرق السريعة في Wisconsin حدها 70 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-019","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how many demerit points within 12 months will cost you your driving privilege?","o":["6 points or more","8 points or more","12 points or more","18 points or more"],"h1":"It is the same number as the months.","h2":"In Wisconsin, 12 or more demerit points within any 12-month period lead to a suspension or revocation of your driving privilege.","p":"Right. 12 points in 12 months means you lose the privilege to drive."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito en 12 meses le hacen perder el privilegio de manejar?","o":["6 puntos o más","8 puntos o más","12 puntos o más","18 puntos o más"],"h1":"Es el mismo número que los meses.","h2":"En Wisconsin, 12 o más puntos de demérito en cualquier período de 12 meses llevan a la suspensión o revocación de su privilegio de manejar.","p":"Correcto. 12 puntos en 12 meses y usted pierde el privilegio de manejar."},"zh":{"q":"在 Wisconsin，12 个月内累计多少扣分会让你失去驾驶资格？","o":["6 分或以上","8 分或以上","12 分或以上","18 分或以上"],"h1":"它和月份的数字一样。","h2":"在 Wisconsin，任何 12 个月内累计 12 分或以上的扣分，会导致你的驾驶资格被暂停或吊销。","p":"对。12 个月内扣 12 分，你就会失去驾驶资格。"},"vi":{"q":"Ở Wisconsin, bao nhiêu điểm phạt trong vòng 12 tháng sẽ làm bạn mất quyền lái xe?","o":["6 điểm trở lên","8 điểm trở lên","12 điểm trở lên","18 điểm trở lên"],"h1":"Đó là cùng con số với số tháng.","h2":"Ở Wisconsin, có 12 điểm phạt trở lên trong bất kỳ khoảng 12 tháng nào sẽ dẫn đến việc bị đình chỉ hoặc thu hồi quyền lái xe.","p":"Đúng. 12 điểm trong 12 tháng nghĩa là bạn mất quyền lái xe."},"tl":{"q":"Sa Wisconsin, ilang demerit point sa loob ng 12 buwan ang magpapawala sa iyo ng pribilehiyong magmaneho?","o":["6 na puntos o higit pa","8 puntos o higit pa","12 puntos o higit pa","18 puntos o higit pa"],"h1":"Pareho ito sa bilang ng mga buwan.","h2":"Sa Wisconsin, ang 12 o higit pang demerit point sa loob ng anumang 12 buwan ay magdudulot ng suspensyon o pagbawi ng iyong pribilehiyong magmaneho.","p":"Tama. 12 puntos sa 12 buwan ay nangangahulugang mawawala ang pribilehiyo mong magmaneho."},"ar":{"q":"في Wisconsin، كم نقطة مخالفة خلال 12 شهرًا تجعلك تفقد حق القيادة؟","o":["6 نقاط أو أكثر","8 نقاط أو أكثر","12 نقطة أو أكثر","18 نقطة أو أكثر"],"h1":"هو نفس عدد الأشهر.","h2":"في Wisconsin، 12 نقطة مخالفة أو أكثر خلال أي فترة 12 شهرًا تؤدي إلى إيقاف حق القيادة أو سحبه.","p":"صحيح. 12 نقطة في 12 شهرًا تعني أنك تفقد حق القيادة."},"ref":{"doc":"WI","page":53}},{"id":"wi-020","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, what happens to the points of a probationary license holder on a second or later conviction?","o":["The points are doubled","The points are cut in half","No points are added","The points are removed after a month"],"h1":"New drivers are held to a stricter rule.","h2":"In Wisconsin, a probationary license holder gets double points for the second traffic conviction and every one after it.","p":"Right. Probationary drivers get double points from the second conviction on."},"es":{"q":"En Wisconsin, ¿qué pasa con los puntos de quien tiene una licencia probatoria en una segunda condena o en las siguientes?","o":["Los puntos se duplican","Los puntos se reducen a la mitad","No se agregan puntos","Los puntos se borran después de un mes"],"h1":"Los conductores nuevos tienen una regla más estricta.","h2":"En Wisconsin, quien tiene una licencia probatoria recibe el doble de puntos por la segunda condena de tránsito y por cada una después.","p":"Correcto. Los conductores con licencia probatoria reciben el doble de puntos desde la segunda condena."},"zh":{"q":"在 Wisconsin，试用驾照持有人第二次或之后被判违规时，扣分会怎样？","o":["扣分加倍","扣分减半","不扣分","一个月后扣分被取消"],"h1":"新司机要遵守更严格的规定。","h2":"在 Wisconsin，试用驾照持有人从第二次交通违规判决开始，每一次都扣双倍的分。","p":"对。试用驾照司机从第二次违规开始扣双倍的分。"},"vi":{"q":"Ở Wisconsin, điểm phạt của người có bằng lái tạm thời sẽ ra sao khi bị kết tội lần thứ hai hoặc các lần sau?","o":["Điểm bị nhân đôi","Điểm bị giảm một nửa","Không bị cộng điểm","Điểm được xóa sau một tháng"],"h1":"Tài xế mới phải theo quy định nghiêm hơn.","h2":"Ở Wisconsin, người có bằng lái tạm thời bị nhân đôi điểm phạt cho lần vi phạm giao thông thứ hai và mọi lần sau đó.","p":"Đúng. Tài xế có bằng lái tạm thời bị nhân đôi điểm từ lần vi phạm thứ hai."},"tl":{"q":"Sa Wisconsin, ano ang nangyayari sa puntos ng may probationary license sa ikalawa o susunod na conviction?","o":["Dinodoble ang puntos","Hinahati sa kalahati ang puntos","Walang puntos na idinadagdag","Inaalis ang puntos pagkalipas ng isang buwan"],"h1":"Mas mahigpit ang patakaran sa mga bagong driver.","h2":"Sa Wisconsin, ang may probationary license ay nakakakuha ng dobleng puntos sa ikalawang traffic conviction at sa bawat isa pagkatapos nito.","p":"Tama. Dobleng puntos ang probationary driver mula sa ikalawang conviction."},"ar":{"q":"في Wisconsin، ماذا يحدث لنقاط حامل رخصة القيادة التجريبية عند الإدانة الثانية أو ما بعدها؟","o":["تتضاعف النقاط","تُخفض النقاط إلى النصف","لا تُضاف نقاط","تُحذف النقاط بعد شهر"],"h1":"السائقون الجدد يخضعون لقاعدة أشد.","h2":"في Wisconsin، حامل رخصة القيادة التجريبية يحصل على نقاط مضاعفة في الإدانة المرورية الثانية وفي كل إدانة بعدها.","p":"صحيح. السائق برخصة تجريبية يحصل على نقاط مضاعفة من الإدانة الثانية فما بعد."},"ref":{"doc":"WI","page":53}},{"id":"wi-021","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a crash with no injuries must be reported to police when private property damage reaches what amount?","o":["$200 or more","$500 or more","$2,500 or more","$1,000 or more"],"h1":"Damage to government property has a lower amount.","h2":"In Wisconsin, you must report a crash to police when it causes $1,000 or more in property damage, even if no one is hurt.","p":"Right. $1,000 or more in damage means you call the police."},"es":{"q":"En Wisconsin, un choque sin heridos se debe reportar a la policía cuando el daño a la propiedad privada llega a ¿qué cantidad?","o":["$200 o más","$500 o más","$2,500 o más","$1,000 o más"],"h1":"El daño a propiedad del gobierno tiene una cantidad más baja.","h2":"En Wisconsin, usted debe reportar un choque a la policía cuando causa $1,000 o más en daños a la propiedad, aunque nadie esté herido.","p":"Correcto. Con $1,000 o más en daños, se llama a la policía."},"zh":{"q":"在 Wisconsin，没有人受伤的车祸，私人财产损失达到多少时必须向警察报告？","o":["$200 或以上","$500 或以上","$2,500 或以上","$1,000 或以上"],"h1":"政府财产损失的金额要求更低。","h2":"在 Wisconsin，即使没有人受伤，车祸造成 $1,000 或以上的财产损失时，你必须向警察报告。","p":"对。损失达到 $1,000 或以上，就要报警。"},"vi":{"q":"Ở Wisconsin, một vụ tai nạn không có người bị thương phải được báo cho cảnh sát khi thiệt hại tài sản tư nhân đạt bao nhiêu?","o":["$200 trở lên","$500 trở lên","$2,500 trở lên","$1,000 trở lên"],"h1":"Thiệt hại tài sản của chính phủ có mức thấp hơn.","h2":"Ở Wisconsin, bạn phải báo cho cảnh sát khi vụ tai nạn gây thiệt hại tài sản từ $1,000 trở lên, kể cả khi không ai bị thương.","p":"Đúng. Thiệt hại từ $1,000 trở lên thì bạn gọi cảnh sát."},"tl":{"q":"Sa Wisconsin, ang aksidenteng walang nasaktan ay dapat i-report sa pulis kapag umabot sa anong halaga ang pinsala sa pribadong ari-arian?","o":["$200 o higit pa","$500 o higit pa","$2,500 o higit pa","$1,000 o higit pa"],"h1":"Mas mababa ang halaga para sa pinsala sa ari-arian ng gobyerno.","h2":"Sa Wisconsin, dapat mong i-report sa pulis ang aksidente kapag nagdulot ito ng $1,000 o higit pang pinsala sa ari-arian, kahit walang nasaktan.","p":"Tama. Kapag $1,000 o higit pa ang pinsala, tumawag sa pulis."},"ar":{"q":"في Wisconsin، يجب إبلاغ الشرطة عن حادث بدون إصابات عندما تصل أضرار الممتلكات الخاصة إلى أي مبلغ؟","o":["$200 أو أكثر","$500 أو أكثر","$2,500 أو أكثر","$1,000 أو أكثر"],"h1":"أضرار الممتلكات الحكومية لها مبلغ أقل.","h2":"في Wisconsin يجب أن تبلغ الشرطة عن الحادث عندما يسبب أضرارًا في الممتلكات بقيمة $1,000 أو أكثر، حتى لو لم يُصب أحد.","p":"صحيح. أضرار بقيمة $1,000 أو أكثر تعني أن تتصل بالشرطة."},"ref":{"doc":"WI","page":47}},{"id":"wi-022","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, a school bus is stopped with its red lights flashing. How far from it must you stop?","o":["At least 10 feet","At least 20 feet","At least 50 feet","At least 100 feet"],"h1":"It is about the length of one and a half cars.","h2":"In Wisconsin, stop at least 20 feet from a school bus with flashing red lights. On a divided highway, traffic on the other side of the median does not have to stop.","p":"Right. Stop at least 20 feet away from the bus."},"es":{"q":"En Wisconsin, un autobús escolar está detenido con sus luces rojas intermitentes. ¿A qué distancia de él debe usted detenerse?","o":["Al menos 10 pies","Al menos 20 pies","Al menos 50 pies","Al menos 100 pies"],"h1":"Es más o menos el largo de un carro y medio.","h2":"En Wisconsin, deténgase al menos a 20 pies de un autobús escolar con luces rojas intermitentes. En una carretera dividida, el tráfico del otro lado de la división no tiene que detenerse.","p":"Correcto. Deténgase al menos a 20 pies del autobús."},"zh":{"q":"在 Wisconsin，一辆校车闪着红灯停下。你必须在离它多远的地方停车？","o":["至少 10 英尺","至少 20 英尺","至少 50 英尺","至少 100 英尺"],"h1":"大约是一辆半汽车的长度。","h2":"在 Wisconsin，要在离闪着红灯的校车至少 20 英尺的地方停车。在有中间隔离带的公路上，隔离带另一边的车不用停。","p":"对。在离校车至少 20 英尺的地方停车。"},"vi":{"q":"Ở Wisconsin, một xe buýt trường học đang dừng và nháy đèn đỏ. Bạn phải dừng lại cách nó bao xa?","o":["Ít nhất 10 feet","Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet"],"h1":"Khoảng bằng chiều dài của một chiếc xe rưỡi.","h2":"Ở Wisconsin, hãy dừng lại cách ít nhất 20 feet so với xe buýt trường học đang nháy đèn đỏ. Trên xa lộ có dải phân cách, xe ở phía bên kia dải phân cách không phải dừng.","p":"Đúng. Dừng lại cách xe buýt ít nhất 20 feet."},"tl":{"q":"Sa Wisconsin, nakahinto ang isang school bus na kumikislap ang pulang ilaw. Gaano kalayo mula rito ka dapat huminto?","o":["Hindi bababa sa 10 feet","Hindi bababa sa 20 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet"],"h1":"Mga haba ito ng isa't kalahating kotse.","h2":"Sa Wisconsin, huminto nang hindi bababa sa 20 feet mula sa school bus na kumikislap ang pulang ilaw. Sa divided highway, hindi kailangang huminto ang mga sasakyan sa kabilang panig ng median.","p":"Tama. Huminto nang hindi bababa sa 20 feet mula sa bus."},"ar":{"q":"في Wisconsin، حافلة مدرسية متوقفة وأضواؤها الحمراء تومض. على أي بعد منها يجب أن تتوقف؟","o":["10 أقدام على الأقل","20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل"],"h1":"هي تقريبًا طول سيارة ونصف.","h2":"في Wisconsin، توقّف على بعد 20 قدمًا على الأقل من حافلة مدرسية أضواؤها الحمراء تومض. على طريق سريع مقسوم، ليس على السيارات في الجهة الأخرى من الفاصل أن تتوقف.","p":"صحيح. توقّف على بعد 20 قدمًا على الأقل من الحافلة."},"ref":{"doc":"WI","page":51}},{"id":"wi-023","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, how many seconds of following distance does the handbook tell you to keep in good conditions?","o":["1 second","2 seconds","4 seconds","8 seconds"],"h1":"It is more than three seconds.","h2":"Wisconsin teaches a four-second following distance, and you add one more second for each bad condition such as rain, snow, ice or heavy traffic.","p":"Right. Keep at least four seconds behind the car ahead."},"es":{"q":"En Wisconsin, ¿cuántos segundos de distancia detrás de otro vehículo le pide mantener el manual en buenas condiciones?","o":["1 segundo","2 segundos","4 segundos","8 segundos"],"h1":"Es más de tres segundos.","h2":"Wisconsin enseña una distancia de cuatro segundos detrás del otro vehículo, y usted agrega un segundo más por cada condición mala, como lluvia, nieve, hielo o mucho tráfico.","p":"Correcto. Mantenga al menos cuatro segundos detrás del carro de adelante."},"zh":{"q":"在 Wisconsin，手册说在良好条件下要保持几秒的跟车距离？","o":["1 秒","2 秒","4 秒","8 秒"],"h1":"它多于三秒。","h2":"Wisconsin 教的是四秒跟车距离，遇到雨、雪、冰或交通拥挤等每一种不好的情况，就再加一秒。","p":"对。和前面的车保持至少四秒的距离。"},"vi":{"q":"Ở Wisconsin, sổ tay hướng dẫn bảo bạn giữ khoảng cách bao nhiêu giây với xe phía trước khi điều kiện tốt?","o":["1 giây","2 giây","4 giây","8 giây"],"h1":"Nhiều hơn ba giây.","h2":"Wisconsin dạy giữ khoảng cách bốn giây với xe phía trước, và cộng thêm một giây cho mỗi điều kiện xấu như mưa, tuyết, băng hoặc kẹt xe.","p":"Đúng. Giữ khoảng cách ít nhất bốn giây với xe phía trước."},"tl":{"q":"Sa Wisconsin, ilang segundo ng following distance ang sinasabi ng handbook na panatilihin mo kapag maayos ang kondisyon?","o":["1 segundo","2 segundo","4 na segundo","8 segundo"],"h1":"Mas mahaba ito sa tatlong segundo.","h2":"Itinuturo ng Wisconsin ang apat na segundong following distance, at magdagdag ng isa pang segundo sa bawat masamang kondisyon tulad ng ulan, niyebe, yelo o mabigat na trapiko.","p":"Tama. Manatili nang hindi bababa sa apat na segundo sa likod ng sasakyan sa unahan."},"ar":{"q":"في Wisconsin، كم ثانية من مسافة المتابعة يطلب منك الدليل أن تحافظ عليها في الظروف الجيدة؟","o":["ثانية واحدة","ثانيتان","4 ثوانٍ","8 ثوانٍ"],"h1":"هي أكثر من ثلاث ثوانٍ.","h2":"تعلّم Wisconsin مسافة متابعة أربع ثوانٍ، وتضيف ثانية أخرى لكل ظرف سيئ مثل المطر أو الثلج أو الجليد أو الزحام الشديد.","p":"صحيح. ابقَ أربع ثوانٍ على الأقل خلف السيارة التي أمامك."},"ref":{"doc":"WI","page":10}},{"id":"wi-024","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, you must turn on your headlights when you cannot see a person or vehicle how far away?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"It is about one city block.","h2":"In Wisconsin, you must use your headlights when you cannot see a person or vehicle 500 feet away, and from a half hour after sunset to a half hour before sunrise.","p":"Right. If you cannot see 500 feet ahead, turn your headlights on."},"es":{"q":"En Wisconsin, usted debe encender las luces delanteras cuando no puede ver a una persona o un vehículo ¿a qué distancia?","o":["500 pies","100 pies","1,000 pies","200 pies"],"h1":"Es más o menos una cuadra de la ciudad.","h2":"En Wisconsin, usted debe usar las luces delanteras cuando no puede ver a una persona o un vehículo a 500 pies, y desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Si no puede ver a 500 pies, encienda las luces delanteras."},"zh":{"q":"在 Wisconsin，当你看不到多远之外的人或车辆时，必须打开前大灯？","o":["500 英尺","100 英尺","1,000 英尺","200 英尺"],"h1":"大约是城市里一个街区的长度。","h2":"在 Wisconsin，当你看不到 500 英尺外的人或车辆时，以及从日落后半小时到日出前半小时，你必须打开前大灯。","p":"对。如果看不到前面 500 英尺，就打开前大灯。"},"vi":{"q":"Ở Wisconsin, bạn phải bật đèn pha khi không thể nhìn thấy người hoặc xe ở cách bao xa?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"Khoảng một dãy phố trong thành phố.","h2":"Ở Wisconsin, bạn phải bật đèn pha khi không thể nhìn thấy người hoặc xe ở cách 500 feet, và từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc.","p":"Đúng. Nếu không nhìn thấy 500 feet phía trước, hãy bật đèn pha."},"tl":{"q":"Sa Wisconsin, dapat mong buksan ang headlights kapag hindi mo makita ang tao o sasakyan sa gaano kalayo?","o":["500 feet","100 feet","1,000 feet","200 feet"],"h1":"Mga isang block sa lungsod ito.","h2":"Sa Wisconsin, dapat mong gamitin ang headlights kapag hindi mo makita ang tao o sasakyan na 500 feet ang layo, at mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw.","p":"Tama. Kung hindi mo makita ang 500 feet sa unahan, buksan ang headlights."},"ar":{"q":"في Wisconsin، يجب أن تشغّل المصابيح الأمامية عندما لا ترى شخصًا أو سيارة على أي مسافة؟","o":["500 قدم","100 قدم","1,000 قدم","200 قدم"],"h1":"هي تقريبًا طول مربع سكني واحد في المدينة.","h2":"في Wisconsin يجب أن تستعمل المصابيح الأمامية عندما لا ترى شخصًا أو سيارة على بعد 500 قدم، ومن نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها.","p":"صحيح. إذا لم ترَ 500 قدم أمامك، شغّل المصابيح الأمامية."},"ref":{"doc":"WI","page":21}},{"id":"wi-025","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how much room should you give a snowplow that has its lights flashing?","o":["At least 20 feet","At least 50 feet","At least 100 feet","At least 200 feet"],"h1":"Snowplows throw snow and stop often, so give them a lot of space.","h2":"In Wisconsin, you should stay at least 200 feet away from a snowplow when its red, amber or green lights are flashing.","p":"Right. Give a working snowplow at least 200 feet."},"es":{"q":"En Wisconsin, ¿cuánto espacio debe dejarle a una máquina quitanieves que tiene sus luces intermitentes?","o":["Al menos 20 pies","Al menos 50 pies","Al menos 100 pies","Al menos 200 pies"],"h1":"Las quitanieves tiran nieve y se detienen a menudo, así que deles mucho espacio.","h2":"En Wisconsin, usted debe mantenerse al menos a 200 pies de una quitanieves cuando sus luces rojas, ámbar o verdes están intermitentes.","p":"Correcto. Deje al menos 200 pies a una quitanieves trabajando."},"zh":{"q":"在 Wisconsin，对一辆灯在闪的扫雪车，你应该留出多少距离？","o":["至少 20 英尺","至少 50 英尺","至少 100 英尺","至少 200 英尺"],"h1":"扫雪车会把雪甩出来，还经常停车，所以要给它们很多空间。","h2":"在 Wisconsin，当扫雪车的红灯、琥珀色灯或绿灯在闪时，你应该离它至少 200 英尺。","p":"对。和正在工作的扫雪车保持至少 200 英尺。"},"vi":{"q":"Ở Wisconsin, bạn nên chừa khoảng cách bao nhiêu với xe ủi tuyết đang nhấp nháy đèn?","o":["Ít nhất 20 feet","Ít nhất 50 feet","Ít nhất 100 feet","Ít nhất 200 feet"],"h1":"Xe ủi tuyết hất tuyết ra và thường dừng lại, nên hãy chừa nhiều khoảng trống.","h2":"Ở Wisconsin, bạn nên cách xe ủi tuyết ít nhất 200 feet khi đèn đỏ, đèn vàng hổ phách hoặc đèn xanh của nó đang nhấp nháy.","p":"Đúng. Giữ cách xe ủi tuyết đang làm việc ít nhất 200 feet."},"tl":{"q":"Sa Wisconsin, gaano kalaking espasyo ang dapat mong ibigay sa snowplow na kumikislap ang ilaw?","o":["Hindi bababa sa 20 feet","Hindi bababa sa 50 feet","Hindi bababa sa 100 feet","Hindi bababa sa 200 feet"],"h1":"Nagtatapon ng niyebe ang snowplow at madalas huminto, kaya bigyan sila ng maraming espasyo.","h2":"Sa Wisconsin, dapat kang manatili nang hindi bababa sa 200 feet mula sa snowplow kapag kumikislap ang pula, amber o berdeng ilaw nito.","p":"Tama. Bigyan ang gumaganang snowplow ng hindi bababa sa 200 feet."},"ar":{"q":"في Wisconsin، ما المسافة التي يجب أن تتركها لكاسحة الثلج التي تومض أضواؤها؟","o":["20 قدمًا على الأقل","50 قدمًا على الأقل","100 قدم على الأقل","200 قدم على الأقل"],"h1":"كاسحات الثلج ترمي الثلج وتتوقف كثيرًا، فاترك لها مسافة كبيرة.","h2":"في Wisconsin يجب أن تبقى على بعد 200 قدم على الأقل من كاسحة الثلج عندما تومض أضواؤها الحمراء أو الكهرمانية أو الخضراء.","p":"صحيح. اترك لكاسحة الثلج التي تعمل 200 قدم على الأقل."},"ref":{"doc":"WI","page":45}},{"id":"wi-026","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what happens if you refuse a police officer's request to take a breath or blood alcohol test?","o":["You get a warning the first time","You lose your driving privilege for at least one year","You lose your license for 30 days","You pay a small fine and keep driving"],"h1":"This is the Implied Consent Law, and the penalty is long.","h2":"In Wisconsin, if you refuse the alcohol test, you are arrested under the Implied Consent Law and lose your driving privilege for at least one year.","p":"Right. Refusing the test costs you at least one year of driving."},"es":{"q":"En Wisconsin, ¿qué pasa si usted se niega cuando un policía le pide una prueba de alcohol de aliento o de sangre?","o":["Recibe una advertencia la primera vez","Pierde su privilegio de manejar por al menos un año","Pierde su licencia por 30 días","Paga una multa pequeña y sigue manejando"],"h1":"Es la Ley de Consentimiento Implícito, y la sanción es larga.","h2":"En Wisconsin, si usted se niega a la prueba de alcohol, lo arrestan bajo la Ley de Consentimiento Implícito y pierde su privilegio de manejar por al menos un año.","p":"Correcto. Negarse a la prueba le cuesta al menos un año sin manejar."},"zh":{"q":"在 Wisconsin，如果你拒绝警察要求你做呼气或血液酒精测试，会怎样？","o":["第一次只会得到警告","你至少一年失去驾驶资格","你的驾照被吊销 30 天","你交一点罚款，可以继续开车"],"h1":"这是默示同意法（Implied Consent Law），处罚时间很长。","h2":"在 Wisconsin，如果你拒绝酒精测试，你会根据默示同意法被逮捕，并且至少一年失去驾驶资格。","p":"对。拒绝测试会让你至少一年不能开车。"},"vi":{"q":"Ở Wisconsin, điều gì xảy ra nếu bạn từ chối yêu cầu của cảnh sát làm xét nghiệm nồng độ cồn qua hơi thở hoặc máu?","o":["Lần đầu bạn chỉ bị cảnh cáo","Bạn mất quyền lái xe ít nhất một năm","Bạn bị mất bằng lái 30 ngày","Bạn trả một khoản phạt nhỏ và tiếp tục lái xe"],"h1":"Đây là Luật Đồng Ý Ngầm (Implied Consent Law), và hình phạt kéo dài.","h2":"Ở Wisconsin, nếu bạn từ chối xét nghiệm nồng độ cồn, bạn bị bắt theo Luật Đồng Ý Ngầm và mất quyền lái xe ít nhất một năm.","p":"Đúng. Từ chối xét nghiệm làm bạn mất quyền lái xe ít nhất một năm."},"tl":{"q":"Sa Wisconsin, ano ang mangyayari kung tatanggihan mo ang hiling ng pulis na magpa-breath o blood alcohol test?","o":["Babala lang sa unang beses","Mawawala ang pribilehiyo mong magmaneho nang hindi bababa sa isang taon","Mawawala ang lisensya mo nang 30 araw","Magbabayad ka ng maliit na multa at patuloy na magmamaneho"],"h1":"Ito ang Implied Consent Law, at mahaba ang parusa.","h2":"Sa Wisconsin, kapag tumanggi ka sa alcohol test, aarestuhin ka sa ilalim ng Implied Consent Law at mawawala ang pribilehiyo mong magmaneho nang hindi bababa sa isang taon.","p":"Tama. Ang pagtanggi sa test ay nagpapawala sa iyo ng pagmamaneho nang hindi bababa sa isang taon."},"ar":{"q":"في Wisconsin، ماذا يحدث إذا رفضت طلب الشرطي أن تجري اختبار الكحول بالنفس أو بالدم؟","o":["تحصل على تحذير في المرة الأولى","تفقد حق القيادة لمدة سنة على الأقل","تفقد رخصتك لمدة 30 يومًا","تدفع غرامة صغيرة وتستمر في القيادة"],"h1":"هذا هو قانون الموافقة الضمنية (Implied Consent Law)، والعقوبة طويلة.","h2":"في Wisconsin، إذا رفضت اختبار الكحول، يتم القبض عليك بموجب قانون الموافقة الضمنية وتفقد حق القيادة لمدة سنة على الأقل.","p":"صحيح. رفض الاختبار يكلفك سنة على الأقل بدون قيادة."},"ref":{"doc":"WI","page":49}},{"id":"wi-027","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, until what age does a child generally need to ride in a booster seat?","o":["Age 4","Age 6","Age 8","Age 12"],"h1":"Children usually leave the car seat at 4, and the booster comes after that.","h2":"In Wisconsin, children generally ride in a child safety seat until age four and then in a booster seat until age eight.","p":"Right. A booster seat until age eight."},"es":{"q":"En Wisconsin, ¿hasta qué edad un niño generalmente debe viajar en un asiento elevador (booster)?","o":["4 años","6 años","8 años","12 años"],"h1":"Los niños suelen dejar el asiento de seguridad a los 4, y el elevador viene después.","h2":"En Wisconsin, los niños generalmente viajan en un asiento de seguridad hasta los cuatro años y luego en un asiento elevador hasta los ocho años.","p":"Correcto. Asiento elevador hasta los ocho años."},"zh":{"q":"在 Wisconsin，孩子一般要坐加高座椅（booster seat）到几岁？","o":["4 岁","6 岁","8 岁","12 岁"],"h1":"孩子通常在 4 岁离开儿童安全座椅，之后用加高座椅。","h2":"在 Wisconsin，孩子一般坐儿童安全座椅到四岁，然后坐加高座椅到八岁。","p":"对。坐加高座椅到八岁。"},"vi":{"q":"Ở Wisconsin, trẻ em thường phải ngồi ghế nâng (booster seat) đến bao nhiêu tuổi?","o":["4 tuổi","6 tuổi","8 tuổi","12 tuổi"],"h1":"Trẻ em thường rời ghế an toàn lúc 4 tuổi, và ghế nâng là bước tiếp theo.","h2":"Ở Wisconsin, trẻ em thường ngồi ghế an toàn trẻ em đến bốn tuổi và sau đó ngồi ghế nâng đến tám tuổi.","p":"Đúng. Ngồi ghế nâng đến tám tuổi."},"tl":{"q":"Sa Wisconsin, hanggang ilang taon karaniwang kailangang sumakay ang bata sa booster seat?","o":["Edad 4","Edad 6","Edad 8","Edad 12"],"h1":"Karaniwang umaalis ang bata sa car seat sa edad na 4, at booster seat ang kasunod.","h2":"Sa Wisconsin, karaniwang sumasakay ang bata sa child safety seat hanggang edad apat at pagkatapos ay sa booster seat hanggang edad walo.","p":"Tama. Booster seat hanggang edad walo."},"ar":{"q":"في Wisconsin، حتى أي عمر يجب عادةً أن يجلس الطفل في مقعد رافع (booster seat)؟","o":["عمر 4","عمر 6","عمر 8","عمر 12"],"h1":"يترك الأطفال عادةً مقعد السيارة في عمر 4، والمقعد الرافع يأتي بعد ذلك.","h2":"في Wisconsin، يجلس الأطفال عادةً في مقعد أمان للأطفال حتى عمر أربع سنوات، ثم في مقعد رافع حتى عمر ثماني سنوات.","p":"صحيح. مقعد رافع حتى عمر ثماني سنوات."},"ref":{"doc":"WI","page":55}},{"id":"wi-028","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how often must you renew a regular driver license?","o":["Every 4 years","Every 8 years","Every 10 years","Every 2 years"],"h1":"It is a long time, but less than ten years.","h2":"In Wisconsin, a regular driver license must be renewed every eight years.","p":"Right. A regular license is renewed every eight years."},"es":{"q":"En Wisconsin, ¿cada cuánto debe renovar una licencia de conducir regular?","o":["Cada 4 años","Cada 8 años","Cada 10 años","Cada 2 años"],"h1":"Es mucho tiempo, pero menos de diez años.","h2":"En Wisconsin, una licencia de conducir regular se debe renovar cada ocho años.","p":"Correcto. La licencia regular se renueva cada ocho años."},"zh":{"q":"在 Wisconsin，普通驾照多久必须更新一次？","o":["每 4 年","每 8 年","每 10 年","每 2 年"],"h1":"时间很长，但不到十年。","h2":"在 Wisconsin，普通驾照必须每 8 年更新一次。","p":"对。普通驾照每 8 年更新一次。"},"vi":{"q":"Ở Wisconsin, bằng lái thường phải gia hạn bao lâu một lần?","o":["Mỗi 4 năm","Mỗi 8 năm","Mỗi 10 năm","Mỗi 2 năm"],"h1":"Đó là một thời gian dài, nhưng ít hơn mười năm.","h2":"Ở Wisconsin, bằng lái thường phải được gia hạn mỗi 8 năm.","p":"Đúng. Bằng lái thường được gia hạn mỗi 8 năm."},"tl":{"q":"Sa Wisconsin, gaano kadalas mo dapat i-renew ang regular na driver license?","o":["Tuwing 4 na taon","Tuwing 8 taon","Tuwing 10 taon","Tuwing 2 taon"],"h1":"Matagal ito, pero mas maikli sa sampung taon.","h2":"Sa Wisconsin, ang regular na driver license ay dapat i-renew tuwing 8 taon.","p":"Tama. Ang regular na license ay nire-renew tuwing 8 taon."},"ar":{"q":"في Wisconsin، كل كم سنة يجب أن تجدد رخصة القيادة العادية؟","o":["كل 4 سنوات","كل 8 سنوات","كل 10 سنوات","كل سنتين (2)"],"h1":"هي مدة طويلة، لكنها أقل من عشر سنوات.","h2":"في Wisconsin، يجب تجديد رخصة القيادة العادية كل 8 سنوات.","p":"صحيح. تُجدَّد الرخصة العادية كل 8 سنوات."},"ref":{"doc":"WI","page":7}},{"id":"wi-029","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, a person with a guide dog or a white cane is crossing the road. How far away must you stop?","o":["At least 3 feet","At least 5 feet","At least 10 feet","At least 50 feet"],"h1":"Give the person a lot of room, more than one car door's width.","h2":"In Wisconsin, you must stop at least 10 feet away until a person with a guide dog or white cane is off the road.","p":"Right. Stop at least 10 feet away and wait until the person is off the road."},"es":{"q":"En Wisconsin, una persona con un perro guía o un bastón blanco está cruzando la calle. ¿A qué distancia debe detenerse usted?","o":["Por lo menos a 3 pies","Por lo menos a 5 pies","Por lo menos a 10 pies","Por lo menos a 50 pies"],"h1":"Dele mucho espacio a la persona, más que el ancho de una puerta de carro.","h2":"En Wisconsin, usted debe detenerse por lo menos a 10 pies hasta que la persona con perro guía o bastón blanco salga de la calle.","p":"Correcto. Deténgase por lo menos a 10 pies y espere a que la persona salga de la calle."},"zh":{"q":"在 Wisconsin，一个带导盲犬或白手杖的人正在过马路。你必须在多远的地方停车？","o":["至少 3 英尺","至少 5 英尺","至少 10 英尺","至少 50 英尺"],"h1":"给这个人留出很大的空间，比一扇车门还宽。","h2":"在 Wisconsin，你必须在至少 10 英尺外停车，直到带导盲犬或白手杖的人离开道路。","p":"对。在至少 10 英尺外停车，等这个人离开道路。"},"vi":{"q":"Ở Wisconsin, một người có chó dẫn đường hoặc gậy trắng đang băng qua đường. Bạn phải dừng xe cách bao xa?","o":["Ít nhất 3 feet","Ít nhất 5 feet","Ít nhất 10 feet","Ít nhất 50 feet"],"h1":"Hãy chừa cho người đó nhiều chỗ, rộng hơn một cánh cửa xe.","h2":"Ở Wisconsin, bạn phải dừng xe cách ít nhất 10 feet cho đến khi người có chó dẫn đường hoặc gậy trắng ra khỏi đường.","p":"Đúng. Dừng xe cách ít nhất 10 feet và chờ đến khi người đó ra khỏi đường."},"tl":{"q":"Sa Wisconsin, may taong may guide dog o puting tungkod na tumatawid sa kalsada. Gaano kalayo ka dapat huminto?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 5 feet","Hindi bababa sa 10 feet","Hindi bababa sa 50 feet"],"h1":"Bigyan ng malaking espasyo ang tao, mas malapad pa sa isang pinto ng kotse.","h2":"Sa Wisconsin, dapat kang huminto nang hindi bababa sa 10 feet ang layo hanggang makaalis sa kalsada ang taong may guide dog o puting tungkod.","p":"Tama. Huminto nang hindi bababa sa 10 feet ang layo at maghintay hanggang makaalis ang tao sa kalsada."},"ar":{"q":"في Wisconsin، شخص معه كلب مرشد أو عصا بيضاء يعبر الطريق. على أي مسافة يجب أن تتوقف؟","o":["3 أقدام على الأقل","5 أقدام على الأقل","10 أقدام على الأقل","50 قدمًا على الأقل"],"h1":"اترك للشخص مساحة كبيرة، أكثر من عرض باب سيارة واحد.","h2":"في Wisconsin، يجب أن تتوقف على بعد 10 أقدام على الأقل حتى يخرج الشخص الذي معه كلب مرشد أو عصا بيضاء من الطريق.","p":"صحيح. توقف على بعد 10 أقدام على الأقل وانتظر حتى يخرج الشخص من الطريق."},"ref":{"doc":"WI","page":9}},{"id":"wi-030","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, how much room must you give a bicyclist when you pass?","o":["At least 3 feet","At least 1 foot","At least 2 feet","At least 10 feet"],"h1":"It is about the length of a yardstick.","h2":"In Wisconsin, you must give a bicyclist at least three feet of room when you pass.","p":"Right. Give bicyclists at least three feet when you pass."},"es":{"q":"En Wisconsin, ¿cuánto espacio debe dar a un ciclista cuando lo rebasa?","o":["Por lo menos 3 pies","Por lo menos 1 pie","Por lo menos 2 pies","Por lo menos 10 pies"],"h1":"Es más o menos un metro.","h2":"En Wisconsin, usted debe dar a un ciclista por lo menos tres pies de espacio cuando lo rebasa.","p":"Correcto. Dé por lo menos tres pies a los ciclistas al rebasarlos."},"zh":{"q":"在 Wisconsin，超过骑自行车的人时，你必须留出多少空间？","o":["至少 3 英尺","至少 1 英尺","至少 2 英尺","至少 10 英尺"],"h1":"大约是一把码尺的长度。","h2":"在 Wisconsin，超过骑自行车的人时，你必须留出至少 3 英尺的空间。","p":"对。超过骑自行车的人时，至少留出 3 英尺。"},"vi":{"q":"Ở Wisconsin, khi vượt người đi xe đạp, bạn phải chừa bao nhiêu khoảng trống?","o":["Ít nhất 3 feet","Ít nhất 1 foot","Ít nhất 2 feet","Ít nhất 10 feet"],"h1":"Khoảng bằng chiều dài một cây thước yard.","h2":"Ở Wisconsin, khi vượt người đi xe đạp, bạn phải chừa ít nhất 3 feet khoảng trống.","p":"Đúng. Chừa ít nhất 3 feet khi vượt người đi xe đạp."},"tl":{"q":"Sa Wisconsin, gaano kalaking espasyo ang dapat mong ibigay sa nagbibisikleta kapag lumalampas ka?","o":["Hindi bababa sa 3 feet","Hindi bababa sa 1 foot","Hindi bababa sa 2 feet","Hindi bababa sa 10 feet"],"h1":"Mga kasinghaba ito ng isang yardstick.","h2":"Sa Wisconsin, dapat kang magbigay ng hindi bababa sa 3 feet na espasyo sa nagbibisikleta kapag lumalampas ka.","p":"Tama. Magbigay ng hindi bababa sa 3 feet sa mga nagbibisikleta kapag lumalampas ka."},"ar":{"q":"في Wisconsin، كم مسافة يجب أن تترك لراكب الدراجة عندما تتجاوزه؟","o":["3 أقدام على الأقل","قدم واحدة (1) على الأقل","قدمان (2) على الأقل","10 أقدام على الأقل"],"h1":"هي تقريبًا طول مسطرة الياردة.","h2":"في Wisconsin، يجب أن تترك لراكب الدراجة مسافة 3 أقدام على الأقل عندما تتجاوزه.","p":"صحيح. اترك لراكبي الدراجات 3 أقدام على الأقل عندما تتجاوزهم."},"ref":{"doc":"WI","page":52}},{"id":"wi-031","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what must the vehicles in a funeral procession have turned on?","o":["Hazard lights only","Turn signals","Interior lights","Headlights"],"h1":"These lights help other drivers see that the cars are traveling together.","h2":"In Wisconsin, vehicles in a funeral procession must have their headlights on, and you must not cut into the line.","p":"Right. Cars in a funeral procession drive with headlights on."},"es":{"q":"En Wisconsin, ¿qué deben tener encendido los vehículos de un cortejo fúnebre?","o":["Solo las luces intermitentes","Las direccionales","Las luces interiores","Los faros delanteros"],"h1":"Estas luces ayudan a otros conductores a ver que los carros van juntos.","h2":"En Wisconsin, los vehículos de un cortejo fúnebre deben llevar los faros delanteros encendidos, y usted no debe meterse en la fila.","p":"Correcto. Los carros de un cortejo fúnebre van con los faros delanteros encendidos."},"zh":{"q":"在 Wisconsin，送葬车队中的车辆必须打开什么？","o":["只开危险警示灯","转向灯","车内灯","前大灯"],"h1":"这些灯帮助其他司机看出这些车是一起行驶的。","h2":"在 Wisconsin，送葬车队中的车辆必须打开前大灯，而且你不能插进车队。","p":"对。送葬车队中的车辆开着前大灯行驶。"},"vi":{"q":"Ở Wisconsin, các xe trong đoàn xe tang phải bật gì?","o":["Chỉ đèn khẩn cấp","Đèn xi nhan","Đèn trong xe","Đèn pha"],"h1":"Những đèn này giúp các tài xế khác thấy rằng các xe đang đi cùng nhau.","h2":"Ở Wisconsin, các xe trong đoàn xe tang phải bật đèn pha, và bạn không được chen vào đoàn xe.","p":"Đúng. Các xe trong đoàn xe tang chạy với đèn pha bật."},"tl":{"q":"Sa Wisconsin, ano ang dapat nakabukas sa mga sasakyan sa isang funeral procession?","o":["Hazard lights lang","Turn signals","Mga ilaw sa loob","Headlights"],"h1":"Tinutulungan ng mga ilaw na ito ang ibang driver na makita na magkakasamang bumibiyahe ang mga kotse.","h2":"Sa Wisconsin, ang mga sasakyan sa funeral procession ay dapat nakabukas ang headlights, at hindi ka dapat sumingit sa hanay.","p":"Tama. Nakabukas ang headlights ng mga kotse sa funeral procession."},"ar":{"q":"في Wisconsin، ماذا يجب أن تشغّل السيارات في موكب الجنازة؟","o":["أضواء التحذير فقط","إشارات الانعطاف","الأضواء الداخلية","المصابيح الأمامية"],"h1":"هذه الأضواء تساعد السائقين الآخرين على رؤية أن السيارات تسير معًا.","h2":"في Wisconsin، يجب أن تشغّل السيارات في موكب الجنازة المصابيح الأمامية، ولا يجوز لك أن تدخل بين سيارات الموكب.","p":"صحيح. تسير سيارات موكب الجنازة والمصابيح الأمامية مضاءة."},"ref":{"doc":"WI","page":43}},{"id":"wi-032","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what vision is needed to get a regular car license?","o":["20/20 in both eyes","20/40 in at least one eye","20/60 in at least one eye","20/100 in both eyes"],"h1":"You need good vision in only one eye, with or without glasses.","h2":"In Wisconsin, you need vision of at least 20/40 in one eye, with or without glasses or contacts, to get a regular car license.","p":"Right. You need 20/40 in at least one eye."},"es":{"q":"En Wisconsin, ¿qué visión se necesita para obtener una licencia regular de auto?","o":["20/20 en ambos ojos","20/40 en al menos un ojo","20/60 en al menos un ojo","20/100 en ambos ojos"],"h1":"Usted necesita buena visión en un solo ojo, con o sin anteojos.","h2":"En Wisconsin, usted necesita una visión de al menos 20/40 en un ojo, con o sin anteojos o lentes de contacto, para obtener una licencia regular de auto.","p":"Correcto. Necesita 20/40 en al menos un ojo."},"zh":{"q":"在 Wisconsin，要拿普通汽车驾照需要什么视力？","o":["两只眼睛都是 20/20","至少一只眼睛 20/40","至少一只眼睛 20/60","两只眼睛都是 20/100"],"h1":"只需要一只眼睛视力好，戴不戴眼镜都可以。","h2":"在 Wisconsin，要拿普通汽车驾照，至少一只眼睛的视力要达到 20/40，戴不戴眼镜或隐形眼镜都可以。","p":"对。至少一只眼睛要 20/40。"},"vi":{"q":"Ở Wisconsin, cần thị lực như thế nào để có bằng lái xe hơi thường?","o":["20/20 ở cả hai mắt","20/40 ở ít nhất một mắt","20/60 ở ít nhất một mắt","20/100 ở cả hai mắt"],"h1":"Bạn chỉ cần một mắt nhìn tốt, có hoặc không có kính.","h2":"Ở Wisconsin, bạn cần thị lực ít nhất 20/40 ở một mắt, có hoặc không có kính hay kính áp tròng, để có bằng lái xe hơi thường.","p":"Đúng. Bạn cần 20/40 ở ít nhất một mắt."},"tl":{"q":"Sa Wisconsin, anong paningin ang kailangan para makakuha ng regular na lisensya sa kotse?","o":["20/20 sa dalawang mata","20/40 sa kahit isang mata","20/60 sa kahit isang mata","20/100 sa dalawang mata"],"h1":"Kailangan mo lang ng malinaw na paningin sa isang mata, may salamin man o wala.","h2":"Sa Wisconsin, kailangan mo ng paningin na hindi bababa sa 20/40 sa isang mata, may salamin o contact lens man o wala, para makakuha ng regular na lisensya sa kotse.","p":"Tama. Kailangan mo ng 20/40 sa kahit isang mata."},"ar":{"q":"في Wisconsin، ما قوة النظر المطلوبة للحصول على رخصة سيارة عادية؟","o":["20/20 في العينين كلتيهما","20/40 في عين واحدة على الأقل","20/60 في عين واحدة على الأقل","20/100 في العينين كلتيهما"],"h1":"تحتاج إلى نظر جيد في عين واحدة فقط، بنظارة أو بدونها.","h2":"في Wisconsin، تحتاج إلى نظر لا يقل عن 20/40 في عين واحدة، بنظارة أو عدسات لاصقة أو بدونها، للحصول على رخصة سيارة عادية.","p":"صحيح. تحتاج إلى 20/40 في عين واحدة على الأقل."},"ref":{"doc":"WI","page":1}},{"id":"wi-033","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the youngest age to get an instruction permit?","o":["14","14 and a half","15","16"],"h1":"It is one year before you can get a probationary license.","h2":"In Wisconsin, you can get an instruction permit at age 15 if you are enrolled in driver education, including the behind-the-wheel part.","p":"Right. You can get a permit at 15."},"es":{"q":"En Wisconsin, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14","14 y medio","15","16"],"h1":"Es un año antes de poder obtener una licencia probatoria.","h2":"En Wisconsin, usted puede obtener un permiso de aprendiz a los 15 años si está inscrito en educación vial, incluida la parte de práctica al volante.","p":"Correcto. Puede obtener el permiso a los 15 años."},"zh":{"q":"在 Wisconsin，最小几岁可以拿学习驾照？","o":["14","14 岁半","15","16"],"h1":"比可以拿试用驾照早一年。","h2":"在 Wisconsin，如果你已报名参加驾驶教育（包括上路驾驶部分），15 岁就可以拿学习驾照。","p":"对。15 岁就可以拿学习驾照。"},"vi":{"q":"Ở Wisconsin, tuổi nhỏ nhất để có giấy phép tập lái là bao nhiêu?","o":["14","14 tuổi rưỡi","15","16"],"h1":"Đó là một năm trước khi bạn có thể có bằng lái tạm thời.","h2":"Ở Wisconsin, bạn có thể có giấy phép tập lái lúc 15 tuổi nếu bạn đã ghi danh học lái xe, kể cả phần lái xe thực tế.","p":"Đúng. Bạn có thể có giấy phép lúc 15 tuổi."},"tl":{"q":"Sa Wisconsin, ano ang pinakabatang edad para makakuha ng instruction permit?","o":["14","14 at kalahati","15","16"],"h1":"Isang taon ito bago ka makakuha ng probationary license.","h2":"Sa Wisconsin, makakakuha ka ng instruction permit sa edad na 15 kung naka-enroll ka sa driver education, kasama ang bahaging pagmamaneho sa kalsada.","p":"Tama. Makakakuha ka ng permit sa edad na 15."},"ar":{"q":"في Wisconsin، ما أصغر سن للحصول على تصريح التعلّم؟","o":["14","14 ونصف","15","16"],"h1":"هو قبل سنة من السن التي تحصل فيها على رخصة تحت الاختبار.","h2":"في Wisconsin، يمكنك الحصول على تصريح التعلّم في سن 15 إذا كنت مسجلًا في دروس تعليم القيادة، بما فيها جزء القيادة الفعلية.","p":"صحيح. يمكنك الحصول على التصريح في سن 15."},"ref":{"doc":"WI","page":5}},{"id":"wi-034","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how often should you check your rearview mirror to see if someone is following too closely?","o":["Every 30 seconds","Every 1 to 2 seconds","Every 15 to 20 seconds","Every 6 to 8 seconds"],"h1":"It is more often than every ten seconds, but not every second.","h2":"In Wisconsin, check your rearview mirror every 6 to 8 seconds; if someone is tailgating, slowly reduce your speed so they go around you.","p":"Right. Check the mirror every 6 to 8 seconds."},"es":{"q":"En Wisconsin, ¿cada cuánto debe mirar el espejo retrovisor para ver si alguien lo sigue demasiado cerca?","o":["Cada 30 segundos","Cada 1 a 2 segundos","Cada 15 a 20 segundos","Cada 6 a 8 segundos"],"h1":"Es más seguido que cada diez segundos, pero no cada segundo.","h2":"En Wisconsin, mire el espejo retrovisor cada 6 a 8 segundos; si alguien lo sigue muy de cerca, reduzca la velocidad poco a poco para que lo pase.","p":"Correcto. Mire el espejo cada 6 a 8 segundos."},"zh":{"q":"在 Wisconsin，应该多久看一次后视镜，看看有没有人跟得太近？","o":["每 30 秒","每 1 到 2 秒","每 15 到 20 秒","每 6 到 8 秒"],"h1":"比每十秒更频繁，但不是每一秒。","h2":"在 Wisconsin，每 6 到 8 秒看一次后视镜；如果有人跟得太近，就慢慢减速，让他们绕过你。","p":"对。每 6 到 8 秒看一次后视镜。"},"vi":{"q":"Ở Wisconsin, bạn nên nhìn gương chiếu hậu bao lâu một lần để xem có ai bám quá sát không?","o":["Mỗi 30 giây","Mỗi 1 đến 2 giây","Mỗi 15 đến 20 giây","Mỗi 6 đến 8 giây"],"h1":"Thường hơn mỗi mười giây, nhưng không phải mỗi giây.","h2":"Ở Wisconsin, hãy nhìn gương chiếu hậu mỗi 6 đến 8 giây; nếu có người bám quá sát, hãy từ từ giảm tốc độ để họ vượt qua bạn.","p":"Đúng. Nhìn gương mỗi 6 đến 8 giây."},"tl":{"q":"Sa Wisconsin, gaano kadalas mo dapat tingnan ang rearview mirror para makita kung may sumusunod nang masyadong malapit?","o":["Bawat 30 segundo","Bawat 1 hanggang 2 segundo","Bawat 15 hanggang 20 segundo","Bawat 6 hanggang 8 segundo"],"h1":"Mas madalas ito kaysa bawat sampung segundo, pero hindi bawat segundo.","h2":"Sa Wisconsin, tingnan ang rearview mirror bawat 6 hanggang 8 segundo; kung may sumusunod nang masyadong malapit, dahan-dahang bagalan ang takbo para malampasan ka nila.","p":"Tama. Tingnan ang salamin bawat 6 hanggang 8 segundo."},"ar":{"q":"في Wisconsin، كل كم يجب أن تنظر في المرآة الخلفية لترى إن كان أحد يسير خلفك قريبًا جدًا؟","o":["كل 30 ثانية","كل 1 إلى 2 ثانية","كل 15 إلى 20 ثانية","كل 6 إلى 8 ثوانٍ"],"h1":"هو أكثر من مرة كل عشر ثوانٍ، لكن ليس كل ثانية.","h2":"في Wisconsin، انظر في المرآة الخلفية كل 6 إلى 8 ثوانٍ؛ وإذا كان أحد يسير خلفك قريبًا جدًا، فخفف سرعتك ببطء حتى يتجاوزك.","p":"صحيح. انظر في المرآة كل 6 إلى 8 ثوانٍ."},"ref":{"doc":"WI","page":13}},{"id":"wi-035","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, how far ahead of your vehicle should you be able to see?","o":["10 to 15 seconds","2 to 3 seconds","4 to 5 seconds","About one minute"],"h1":"It is more than the four-second following distance.","h2":"In Wisconsin, you should be able to see 10 to 15 seconds ahead of your vehicle; if you cannot, slow down.","p":"Right. Look 10 to 15 seconds ahead."},"es":{"q":"En Wisconsin, ¿hasta dónde delante de su vehículo debe poder ver?","o":["10 a 15 segundos","2 a 3 segundos","4 a 5 segundos","Más o menos un minuto"],"h1":"Es más que la distancia de cuatro segundos detrás de otro vehículo.","h2":"En Wisconsin, usted debe poder ver de 10 a 15 segundos delante de su vehículo; si no puede, reduzca la velocidad.","p":"Correcto. Mire de 10 a 15 segundos adelante."},"zh":{"q":"在 Wisconsin，你应该能看到车前方多远？","o":["10 到 15 秒","2 到 3 秒","4 到 5 秒","大约一分钟"],"h1":"比四秒的跟车距离更远。","h2":"在 Wisconsin，你应该能看到车前方 10 到 15 秒的距离；如果看不到，就要减速。","p":"对。看前方 10 到 15 秒。"},"vi":{"q":"Ở Wisconsin, bạn nên nhìn thấy xa bao nhiêu phía trước xe của mình?","o":["10 đến 15 giây","2 đến 3 giây","4 đến 5 giây","Khoảng một phút"],"h1":"Xa hơn khoảng cách bốn giây khi đi theo xe khác.","h2":"Ở Wisconsin, bạn nên nhìn thấy 10 đến 15 giây phía trước xe của mình; nếu không thấy được, hãy chạy chậm lại.","p":"Đúng. Nhìn 10 đến 15 giây phía trước."},"tl":{"q":"Sa Wisconsin, gaano kalayo sa unahan ng sasakyan mo ang dapat mong makita?","o":["10 hanggang 15 segundo","2 hanggang 3 segundo","4 hanggang 5 segundo","Mga isang minuto"],"h1":"Mas malayo ito kaysa sa apat na segundong distansya sa sinusundang sasakyan.","h2":"Sa Wisconsin, dapat mong makita ang 10 hanggang 15 segundo sa unahan ng sasakyan mo; kung hindi mo makita, magdahan-dahan.","p":"Tama. Tumingin nang 10 hanggang 15 segundo sa unahan."},"ar":{"q":"في Wisconsin، إلى أي مسافة أمام سيارتك يجب أن تستطيع الرؤية؟","o":["10 إلى 15 ثانية","2 إلى 3 ثوانٍ","4 إلى 5 ثوانٍ","نحو دقيقة واحدة"],"h1":"هي أكثر من مسافة المتابعة البالغة أربع ثوانٍ.","h2":"في Wisconsin، يجب أن تستطيع الرؤية مسافة 10 إلى 15 ثانية أمام سيارتك؛ وإن لم تستطع، فخفف سرعتك.","p":"صحيح. انظر 10 إلى 15 ثانية إلى الأمام."},"ref":{"doc":"WI","page":12}},{"id":"wi-036","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how long do the passenger and night limits last for a new probationary driver under 18?","o":["3 months","6 months","9 months","12 months"],"h1":"It is less than a year.","h2":"In Wisconsin, a probationary driver under 18 has passenger and night limits for the first nine months, or until turning 18 if that comes first.","p":"Right. The limits last nine months."},"es":{"q":"En Wisconsin, ¿cuánto duran los límites de pasajeros y de noche para un nuevo conductor con licencia probatoria menor de 18 años?","o":["3 meses","6 meses","9 meses","12 meses"],"h1":"Es menos de un año.","h2":"En Wisconsin, un conductor con licencia probatoria menor de 18 años tiene límites de pasajeros y de noche durante los primeros nueve meses, o hasta cumplir 18 si eso pasa antes.","p":"Correcto. Los límites duran nueve meses."},"zh":{"q":"在 Wisconsin，未满 18 岁的新试用驾照司机，乘客和夜间限制会持续多久？","o":["3 个月","6 个月","9 个月","12 个月"],"h1":"不到一年。","h2":"在 Wisconsin，未满 18 岁的试用驾照司机在头九个月有乘客和夜间限制，如果先满 18 岁，就到 18 岁为止。","p":"对。限制持续九个月。"},"vi":{"q":"Ở Wisconsin, các giới hạn về hành khách và lái ban đêm kéo dài bao lâu đối với tài xế mới có bằng tạm thời dưới 18 tuổi?","o":["3 tháng","6 tháng","9 tháng","12 tháng"],"h1":"Ít hơn một năm.","h2":"Ở Wisconsin, tài xế có bằng tạm thời dưới 18 tuổi có giới hạn về hành khách và lái ban đêm trong chín tháng đầu, hoặc cho đến khi đủ 18 tuổi nếu điều đó đến trước.","p":"Đúng. Các giới hạn kéo dài chín tháng."},"tl":{"q":"Sa Wisconsin, gaano katagal ang limitasyon sa pasahero at sa gabi para sa bagong probationary driver na wala pang 18?","o":["3 buwan","6 na buwan","9 na buwan","12 buwan"],"h1":"Mas maikli ito sa isang taon.","h2":"Sa Wisconsin, ang probationary driver na wala pang 18 ay may limitasyon sa pasahero at sa gabi sa unang siyam na buwan, o hanggang mag-18 siya kung iyon ang mauuna.","p":"Tama. Siyam na buwan ang limitasyon."},"ar":{"q":"في Wisconsin، كم تستمر قيود الركاب والقيادة ليلًا للسائق الجديد ذي الرخصة تحت الاختبار الذي عمره أقل من 18؟","o":["3 أشهر","6 أشهر","9 أشهر","12 شهرًا"],"h1":"هي أقل من سنة.","h2":"في Wisconsin، السائق ذو الرخصة تحت الاختبار الذي عمره أقل من 18 عليه قيود الركاب والقيادة ليلًا في الأشهر التسعة الأولى، أو حتى يبلغ 18 إن جاء ذلك أولًا.","p":"صحيح. تستمر القيود تسعة أشهر."},"ref":{"doc":"WI","page":6}},{"id":"wi-037","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, a teen with a probationary license gets a ticket for a moving violation. How much longer do the passenger and night limits last?","o":["6 more months","9 more months","1 more year","2 more years"],"h1":"It is half a year.","h2":"In Wisconsin, the probationary limits are extended six months if the teen is convicted of a moving violation, breaks a limit, or has the license suspended or revoked.","p":"Right. The limits go on for six more months."},"es":{"q":"En Wisconsin, un joven con licencia probatoria recibe una multa por una infracción en movimiento. ¿Cuánto tiempo más duran los límites de pasajeros y de noche?","o":["6 meses más","9 meses más","1 año más","2 años más"],"h1":"Es medio año.","h2":"En Wisconsin, los límites de la licencia probatoria se extienden seis meses si el joven es condenado por una infracción en movimiento, no cumple un límite, o le suspenden o revocan la licencia.","p":"Correcto. Los límites siguen seis meses más."},"zh":{"q":"在 Wisconsin，持试用驾照的青少年因行车违规被开罚单。乘客和夜间限制还要再持续多久？","o":["再 6 个月","再 9 个月","再 1 年","再 2 年"],"h1":"是半年。","h2":"在 Wisconsin，如果青少年被判行车违规、违反限制，或驾照被暂停或吊销，试用期限制会延长六个月。","p":"对。限制再延长六个月。"},"vi":{"q":"Ở Wisconsin, một thiếu niên có bằng tạm thời bị phạt vì vi phạm khi đang lái xe. Các giới hạn về hành khách và lái ban đêm kéo dài thêm bao lâu?","o":["Thêm 6 tháng","Thêm 9 tháng","Thêm 1 năm","Thêm 2 năm"],"h1":"Đó là nửa năm.","h2":"Ở Wisconsin, các giới hạn của bằng tạm thời được kéo dài thêm sáu tháng nếu thiếu niên bị kết tội vi phạm khi lái xe, vi phạm một giới hạn, hoặc bị đình chỉ hay thu hồi bằng lái.","p":"Đúng. Các giới hạn kéo dài thêm sáu tháng."},"tl":{"q":"Sa Wisconsin, ang isang teen na may probationary license ay nakakuha ng ticket para sa moving violation. Gaano pa katagal ang limitasyon sa pasahero at sa gabi?","o":["6 na buwan pa","9 na buwan pa","1 taon pa","2 taon pa"],"h1":"Kalahating taon ito.","h2":"Sa Wisconsin, pinahahaba nang anim na buwan ang mga limitasyon ng probationary license kung ang teen ay nahatulan ng moving violation, lumabag sa isang limitasyon, o nasuspinde o nabawi ang lisensya.","p":"Tama. Anim na buwan pa ang limitasyon."},"ar":{"q":"في Wisconsin، حصل مراهق ذو رخصة تحت الاختبار على مخالفة أثناء القيادة. كم تطول قيود الركاب والقيادة ليلًا بعد ذلك؟","o":["6 أشهر أخرى","9 أشهر أخرى","سنة واحدة أخرى","سنتان أخريان"],"h1":"هي نصف سنة.","h2":"في Wisconsin، تطول قيود الرخصة تحت الاختبار ستة أشهر إذا أُدين المراهق بمخالفة أثناء القيادة، أو خالف أحد القيود، أو أُوقفت رخصته أو أُلغيت.","p":"صحيح. تستمر القيود ستة أشهر أخرى."},"ref":{"doc":"WI","page":7}},{"id":"wi-038","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, you move here with a regular license from another state. How soon should you apply for a Wisconsin license?","o":["Within 10 days","Within 30 days","Within 45 days","Within 60 days"],"h1":"It is about two months.","h2":"In Wisconsin, a new resident with a regular out-of-state license should apply for a Wisconsin license within 60 days after moving.","p":"Right. Apply within 60 days."},"es":{"q":"En Wisconsin, usted se muda aquí con una licencia regular de otro estado. ¿En cuánto tiempo debe solicitar una licencia de Wisconsin?","o":["En 10 días","En 30 días","En 45 días","En 60 días"],"h1":"Son unos dos meses.","h2":"En Wisconsin, un nuevo residente con una licencia regular de otro estado debe solicitar una licencia de Wisconsin dentro de los 60 días después de mudarse.","p":"Correcto. Solicítela en 60 días."},"zh":{"q":"在 Wisconsin，你搬来时持有其他州的普通驾照。应该多快申请 Wisconsin 驾照？","o":["10 天内","30 天内","45 天内","60 天内"],"h1":"大约两个月。","h2":"在 Wisconsin，持有外州普通驾照的新居民应在搬来后 60 天内申请 Wisconsin 驾照。","p":"对。在 60 天内申请。"},"vi":{"q":"Ở Wisconsin, bạn chuyển đến đây với bằng lái thường của tiểu bang khác. Bạn nên xin bằng lái Wisconsin trong bao lâu?","o":["Trong vòng 10 ngày","Trong vòng 30 ngày","Trong vòng 45 ngày","Trong vòng 60 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở Wisconsin, cư dân mới có bằng lái thường của tiểu bang khác nên xin bằng lái Wisconsin trong vòng 60 ngày sau khi chuyển đến.","p":"Đúng. Xin trong vòng 60 ngày."},"tl":{"q":"Sa Wisconsin, lumipat ka rito na may regular na lisensya mula sa ibang estado. Gaano kabilis ka dapat mag-apply para sa lisensya ng Wisconsin?","o":["Sa loob ng 10 araw","Sa loob ng 30 araw","Sa loob ng 45 araw","Sa loob ng 60 araw"],"h1":"Mga dalawang buwan ito.","h2":"Sa Wisconsin, ang bagong residente na may regular na lisensya mula sa ibang estado ay dapat mag-apply para sa lisensya ng Wisconsin sa loob ng 60 araw pagkalipat.","p":"Tama. Mag-apply sa loob ng 60 araw."},"ar":{"q":"في Wisconsin، انتقلت إلى هنا ومعك رخصة عادية من ولاية أخرى. خلال كم يجب أن تتقدم بطلب رخصة Wisconsin؟","o":["خلال 10 أيام","خلال 30 يومًا","خلال 45 يومًا","خلال 60 يومًا"],"h1":"هي نحو شهرين.","h2":"في Wisconsin، يجب على المقيم الجديد الذي معه رخصة عادية من ولاية أخرى أن يتقدم بطلب رخصة Wisconsin خلال 60 يومًا بعد الانتقال.","p":"صحيح. قدّم الطلب خلال 60 يومًا."},"ref":{"doc":"WI","page":8}},{"id":"wi-039","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, unless a sign says otherwise, what is the speed limit in a residential area?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is lower than 30 mph.","h2":"In Wisconsin, the speed limit in a residential area is 25 miles per hour unless a sign shows a different limit.","p":"Right. 25 mph in residential areas."},"es":{"q":"En Wisconsin, si no hay un letrero que diga otra cosa, ¿cuál es el límite de velocidad en una zona residencial?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es menos de 30 mph.","h2":"En Wisconsin, el límite de velocidad en una zona residencial es 25 millas por hora, a menos que un letrero indique otro límite.","p":"Correcto. 25 mph en zonas residenciales."},"zh":{"q":"在 Wisconsin，如果没有标志另作规定，住宅区的限速是多少？","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"低于 30 mph。","h2":"在 Wisconsin，除非标志显示其他限速，住宅区的限速是每小时 25 英里。","p":"对。住宅区限速 25 mph。"},"vi":{"q":"Ở Wisconsin, nếu không có biển báo khác, tốc độ tối đa trong khu dân cư là bao nhiêu?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Thấp hơn 30 mph.","h2":"Ở Wisconsin, tốc độ tối đa trong khu dân cư là 25 dặm một giờ, trừ khi có biển báo giới hạn khác.","p":"Đúng. 25 mph trong khu dân cư."},"tl":{"q":"Sa Wisconsin, maliban kung iba ang sinasabi ng karatula, ano ang speed limit sa residential area?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Mas mababa ito sa 30 mph.","h2":"Sa Wisconsin, ang speed limit sa residential area ay 25 milya kada oras maliban kung iba ang limitasyong nakasaad sa karatula.","p":"Tama. 25 mph sa residential area."},"ar":{"q":"في Wisconsin، ما لم تقل لافتة غير ذلك، ما حد السرعة في الحي السكني؟","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"هو أقل من 30 mph.","h2":"في Wisconsin، حد السرعة في الحي السكني 25 ميلًا في الساعة ما لم تُظهر لافتة حدًا آخر.","p":"صحيح. 25 mph في الأحياء السكنية."},"ref":{"doc":"WI","page":10}},{"id":"wi-040","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the highest speed allowed in the outlying parts of a city or village when no limit is posted?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"It is 10 mph more than the residential limit.","h2":"In Wisconsin, the most you may drive in the outlying parts of a city or village with no posted limit is 35 miles per hour.","p":"Right. 35 mph in outlying areas."},"es":{"q":"En Wisconsin, ¿cuál es la velocidad máxima en las afueras de una ciudad o pueblo cuando no hay límite indicado?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Es 10 mph más que el límite residencial.","h2":"En Wisconsin, lo máximo que puede manejar en las afueras de una ciudad o pueblo sin límite indicado es 35 millas por hora.","p":"Correcto. 35 mph en las afueras."},"zh":{"q":"在 Wisconsin，如果没有标示限速，在城市或村镇外围地区最高可以开多快？","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"比住宅区限速高 10 mph。","h2":"在 Wisconsin，在没有标示限速的城市或村镇外围地区，最高可以开每小时 35 英里。","p":"对。外围地区 35 mph。"},"vi":{"q":"Ở Wisconsin, tốc độ cao nhất được phép ở vùng ven của thành phố hoặc làng khi không có biển giới hạn là bao nhiêu?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Cao hơn giới hạn khu dân cư 10 mph.","h2":"Ở Wisconsin, tốc độ cao nhất bạn được chạy ở vùng ven của thành phố hoặc làng không có biển giới hạn là 35 dặm một giờ.","p":"Đúng. 35 mph ở vùng ven."},"tl":{"q":"Sa Wisconsin, ano ang pinakamataas na bilis na pinapayagan sa mga labas na bahagi ng lungsod o village kapag walang nakapaskil na limitasyon?","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"Mas mataas ito nang 10 mph sa limitasyon sa residential area.","h2":"Sa Wisconsin, ang pinakamabilis na puwede mong takbo sa mga labas na bahagi ng lungsod o village na walang nakapaskil na limitasyon ay 35 milya kada oras.","p":"Tama. 35 mph sa mga labas na bahagi."},"ar":{"q":"في Wisconsin، ما أعلى سرعة مسموح بها في الأطراف الخارجية للمدينة أو القرية إذا لم توجد لافتة بحد السرعة؟","o":["25 mph","30 mph","35 mph","45 mph"],"h1":"هي أعلى بـ 10 mph من حد الحي السكني.","h2":"في Wisconsin، أعلى سرعة يمكنك القيادة بها في الأطراف الخارجية للمدينة أو القرية بلا لافتة حد سرعة هي 35 ميلًا في الساعة.","p":"صحيح. 35 mph في الأطراف الخارجية."},"ref":{"doc":"WI","page":10}},{"id":"wi-041","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, about how far behind a large truck is its No-Zone, where the driver cannot see you?","o":["About 200 feet","About 20 feet","About 50 feet","About 100 feet"],"h1":"The space behind is ten times the space in front.","h2":"In Wisconsin, a large truck's No-Zone reaches about 200 feet behind it and about 20 feet in front of it.","p":"Right. About 200 feet behind a truck is a blind area."},"es":{"q":"En Wisconsin, ¿más o menos hasta qué distancia detrás de un camión grande llega su Zona Ciega (No-Zone), donde el conductor no lo puede ver?","o":["Unos 200 pies","Unos 20 pies","Unos 50 pies","Unos 100 pies"],"h1":"El espacio de atrás es diez veces el espacio de adelante.","h2":"En Wisconsin, la Zona Ciega de un camión grande llega a unos 200 pies detrás de él y a unos 20 pies delante de él.","p":"Correcto. Unos 200 pies detrás de un camión son una zona ciega."},"zh":{"q":"在 Wisconsin，大卡车后方的“盲区”（司机看不到你的地方）大约有多远？","o":["大约 200 英尺","大约 20 英尺","大约 50 英尺","大约 100 英尺"],"h1":"后方的距离是前方的十倍。","h2":"在 Wisconsin，大卡车的盲区在车后方大约 200 英尺，在车前方大约 20 英尺。","p":"对。卡车后方大约 200 英尺是盲区。"},"vi":{"q":"Ở Wisconsin, \"vùng mù\" (No-Zone) phía sau một xe tải lớn, nơi tài xế không thấy bạn, dài khoảng bao nhiêu?","o":["Khoảng 200 feet","Khoảng 20 feet","Khoảng 50 feet","Khoảng 100 feet"],"h1":"Khoảng phía sau dài gấp mười lần khoảng phía trước.","h2":"Ở Wisconsin, vùng mù của xe tải lớn kéo dài khoảng 200 feet phía sau xe và khoảng 20 feet phía trước xe.","p":"Đúng. Khoảng 200 feet phía sau xe tải là vùng mù."},"tl":{"q":"Sa Wisconsin, mga gaano kalayo sa likod ng malaking trak ang No-Zone nito, kung saan hindi ka makita ng driver?","o":["Mga 200 talampakan","Mga 20 talampakan","Mga 50 talampakan","Mga 100 talampakan"],"h1":"Sampung beses ng espasyo sa harap ang espasyo sa likod.","h2":"Sa Wisconsin, ang No-Zone ng malaking trak ay umaabot nang mga 200 talampakan sa likod nito at mga 20 talampakan sa harap nito.","p":"Tama. Mga 200 talampakan sa likod ng trak ay blind area."},"ar":{"q":"في Wisconsin، كم تمتد تقريبًا المنطقة العمياء (No-Zone) خلف الشاحنة الكبيرة، حيث لا يستطيع السائق رؤيتك؟","o":["نحو 200 قدم","نحو 20 قدمًا","نحو 50 قدمًا","نحو 100 قدم"],"h1":"المسافة خلفها عشرة أضعاف المسافة أمامها.","h2":"في Wisconsin، تمتد المنطقة العمياء للشاحنة الكبيرة نحو 200 قدم خلفها ونحو 20 قدمًا أمامها.","p":"صحيح. نحو 200 قدم خلف الشاحنة منطقة عمياء."},"ref":{"doc":"WI","page":52}},{"id":"wi-042","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, when may you cross two solid yellow center lines to pass?","o":["Never, for any reason","To pass any slow truck","To pass slow farm equipment","To pass a vehicle going under half the speed limit, if safe and not farm equipment"],"h1":"There is an exception for very slow vehicles, but not for tractors.","h2":"In Wisconsin, you may cross two solid yellow lines to pass a vehicle going less than half the speed limit when it is safe, but not to pass farm equipment.","p":"Right. Only for a vehicle under half the speed limit, never farm equipment."},"es":{"q":"En Wisconsin, ¿cuándo puede cruzar dos líneas amarillas continuas para rebasar?","o":["Nunca, por ninguna razón","Para rebasar cualquier camión lento","Para rebasar maquinaria agrícola lenta","Para rebasar un vehículo que va a menos de la mitad del límite, si es seguro y no es maquinaria agrícola"],"h1":"Hay una excepción para vehículos muy lentos, pero no para tractores.","h2":"En Wisconsin, usted puede cruzar dos líneas amarillas continuas para rebasar un vehículo que va a menos de la mitad del límite de velocidad cuando es seguro, pero no para rebasar maquinaria agrícola.","p":"Correcto. Solo para un vehículo a menos de la mitad del límite, nunca maquinaria agrícola."},"zh":{"q":"在 Wisconsin，什么时候可以越过两条黄色实线中心线超车？","o":["任何原因都不行","超过任何慢速卡车时","超过慢速农用机械时","超过速度不到限速一半的车辆时，前提是安全且不是农用机械"],"h1":"非常慢的车辆有例外，但拖拉机不算。","h2":"在 Wisconsin，安全时你可以越过两条黄色实线去超过速度不到限速一半的车辆，但不可以这样超过农用机械。","p":"对。只能超过速度不到限速一半的车辆，绝不能是农用机械。"},"vi":{"q":"Ở Wisconsin, khi nào bạn được vượt qua hai vạch vàng liền ở giữa đường để vượt xe?","o":["Không bao giờ, vì bất cứ lý do gì","Để vượt bất kỳ xe tải chạy chậm nào","Để vượt máy móc nông nghiệp chạy chậm","Để vượt xe chạy dưới một nửa tốc độ tối đa, nếu an toàn và không phải máy móc nông nghiệp"],"h1":"Có ngoại lệ cho xe chạy rất chậm, nhưng không áp dụng cho máy kéo.","h2":"Ở Wisconsin, bạn được vượt qua hai vạch vàng liền để vượt một xe chạy dưới một nửa tốc độ tối đa khi an toàn, nhưng không được làm vậy để vượt máy móc nông nghiệp.","p":"Đúng. Chỉ với xe chạy dưới một nửa tốc độ tối đa, không bao giờ với máy móc nông nghiệp."},"tl":{"q":"Sa Wisconsin, kailan ka puwedeng tumawid sa dalawang tuloy-tuloy na dilaw na linya sa gitna para mag-overtake?","o":["Hindi kailanman, sa anumang dahilan","Para lampasan ang anumang mabagal na trak","Para lampasan ang mabagal na makinang pansaka","Para lampasan ang sasakyang mas mabagal sa kalahati ng speed limit, kung ligtas at hindi ito makinang pansaka"],"h1":"May eksepsiyon para sa napakabagal na sasakyan, pero hindi para sa traktora.","h2":"Sa Wisconsin, puwede kang tumawid sa dalawang tuloy-tuloy na dilaw na linya para lampasan ang sasakyang mas mabagal sa kalahati ng speed limit kapag ligtas, pero hindi para lampasan ang makinang pansaka.","p":"Tama. Para lang sa sasakyang mas mabagal sa kalahati ng speed limit, hindi kailanman sa makinang pansaka."},"ar":{"q":"في Wisconsin، متى يمكنك عبور الخطين الأصفرين المتصلين في وسط الطريق لتتجاوز؟","o":["أبدًا، لأي سبب","لتتجاوز أي شاحنة بطيئة","لتتجاوز آلات زراعية بطيئة","لتتجاوز مركبة سرعتها أقل من نصف حد السرعة، إن كان ذلك آمنًا ولم تكن آلة زراعية"],"h1":"يوجد استثناء للمركبات البطيئة جدًا، لكن ليس للجرارات.","h2":"في Wisconsin، يمكنك عبور الخطين الأصفرين المتصلين لتتجاوز مركبة سرعتها أقل من نصف حد السرعة عندما يكون ذلك آمنًا، لكن يجب ألّا تفعل ذلك لتتجاوز آلات زراعية.","p":"صحيح. فقط لمركبة سرعتها أقل من نصف حد السرعة، وأبدًا لآلة زراعية."},"ref":{"doc":"WI","page":35}},{"id":"wi-043","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, when may you use a paved shoulder to go around another vehicle?","o":["Any time traffic in your lane is slow","Only when the vehicle ahead is stopped or turning left","Any time the shoulder is empty","Never, even if the vehicle ahead is stopped"],"h1":"The vehicle ahead is not moving forward in your lane.","h2":"In Wisconsin, you may use a paved shoulder to go around a vehicle only when it is stopped or making a left turn.","p":"Right. Only around a stopped or left-turning vehicle."},"es":{"q":"En Wisconsin, ¿cuándo puede usar un acotamiento pavimentado para pasar a otro vehículo?","o":["Siempre que el tráfico de su carril vaya lento","Solo cuando el vehículo de adelante está detenido o girando a la izquierda","Siempre que el acotamiento esté vacío","Nunca, aunque el vehículo de adelante esté detenido"],"h1":"El vehículo de adelante no está avanzando en su carril.","h2":"En Wisconsin, usted puede usar un acotamiento pavimentado para pasar a un vehículo solo cuando está detenido o girando a la izquierda.","p":"Correcto. Solo para pasar a un vehículo detenido o que gira a la izquierda."},"zh":{"q":"在 Wisconsin，什么时候可以用铺好的路肩绕过另一辆车？","o":["只要你车道上的车流慢就可以","只有前车停住或正在左转时","只要路肩上没有车就可以","绝不可以，即使前车停住"],"h1":"前车在你的车道上没有往前走。","h2":"在 Wisconsin，只有在前车停住或正在左转时，你才可以用铺好的路肩绕过它。","p":"对。只能绕过停住或左转的车。"},"vi":{"q":"Ở Wisconsin, khi nào bạn được dùng lề đường đã tráng nhựa để vượt qua một xe khác?","o":["Bất cứ khi nào xe trong làn của bạn chạy chậm","Chỉ khi xe phía trước dừng lại hoặc đang rẽ trái","Bất cứ khi nào lề đường trống","Không bao giờ, kể cả khi xe phía trước dừng lại"],"h1":"Xe phía trước không đi tới trong làn của bạn.","h2":"Ở Wisconsin, bạn chỉ được dùng lề đường đã tráng nhựa để vượt qua một xe khi xe đó dừng lại hoặc đang rẽ trái.","p":"Đúng. Chỉ để vượt xe đang dừng hoặc đang rẽ trái."},"tl":{"q":"Sa Wisconsin, kailan ka puwedeng gumamit ng sementadong gilid ng kalsada (shoulder) para lampasan ang ibang sasakyan?","o":["Anumang oras na mabagal ang trapiko sa lane mo","Kapag nakahinto o kumakaliwa lang ang sasakyan sa unahan","Anumang oras na walang laman ang shoulder","Hindi kailanman, kahit nakahinto ang sasakyan sa unahan"],"h1":"Hindi umaabante ang sasakyan sa unahan sa lane mo.","h2":"Sa Wisconsin, puwede kang gumamit ng sementadong shoulder para lampasan ang isang sasakyan kapag nakahinto lang ito o kumakaliwa.","p":"Tama. Para lang lampasan ang nakahinto o kumakaliwang sasakyan."},"ar":{"q":"في Wisconsin، متى يمكنك استخدام كتف الطريق المعبّد لتلتف حول مركبة أخرى؟","o":["في أي وقت يكون السير في مسارك بطيئًا","فقط عندما تكون المركبة التي أمامك متوقفة أو تنعطف يسارًا","في أي وقت يكون الكتف فارغًا","أبدًا، حتى لو كانت المركبة التي أمامك متوقفة"],"h1":"المركبة التي أمامك لا تتقدم في مسارك.","h2":"في Wisconsin، يمكنك استخدام كتف الطريق المعبّد لتلتف حول مركبة فقط عندما تكون متوقفة أو تنعطف يسارًا.","p":"صحيح. فقط حول مركبة متوقفة أو تنعطف يسارًا."},"ref":{"doc":"WI","page":17}},{"id":"wi-044","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, an orange triangle sign is on the back of a vehicle. How fast may that vehicle be going?","o":["25 mph or less","35 mph or less","45 mph or less","55 mph or less"],"h1":"It is the same as the speed limit on most home streets.","h2":"In Wisconsin, the orange triangle Slow Moving Vehicle sign means the vehicle may be going 25 miles per hour or less.","p":"Right. It may go 25 mph or less."},"es":{"q":"En Wisconsin, un vehículo lleva atrás un letrero triangular anaranjado. ¿A qué velocidad puede ir ese vehículo?","o":["25 mph o menos","35 mph o menos","45 mph o menos","55 mph o menos"],"h1":"Es lo mismo que el límite en la mayoría de las calles residenciales.","h2":"En Wisconsin, el letrero triangular anaranjado de Vehículo Lento significa que el vehículo puede ir a 25 millas por hora o menos.","p":"Correcto. Puede ir a 25 mph o menos."},"zh":{"q":"在 Wisconsin，一辆车的后面有橙色三角形标志。这辆车可能开多快？","o":["25 mph 或更慢","35 mph 或更慢","45 mph 或更慢","55 mph 或更慢"],"h1":"和大多数住宅街道的限速一样。","h2":"在 Wisconsin，橙色三角形的慢速车辆标志表示这辆车的速度可能是每小时 25 英里或更慢。","p":"对。它可能开 25 mph 或更慢。"},"vi":{"q":"Ở Wisconsin, một biển hình tam giác màu cam ở phía sau một xe. Xe đó có thể chạy nhanh bao nhiêu?","o":["25 mph hoặc chậm hơn","35 mph hoặc chậm hơn","45 mph hoặc chậm hơn","55 mph hoặc chậm hơn"],"h1":"Bằng tốc độ tối đa trên hầu hết các đường trong khu nhà ở.","h2":"Ở Wisconsin, biển tam giác màu cam báo xe chạy chậm có nghĩa là xe đó có thể chạy 25 dặm một giờ hoặc chậm hơn.","p":"Đúng. Xe có thể chạy 25 mph hoặc chậm hơn."},"tl":{"q":"Sa Wisconsin, may orange na tatsulok na karatula sa likod ng isang sasakyan. Gaano kabilis ang takbo ng sasakyang iyon?","o":["25 mph o mas mabagal","35 mph o mas mabagal","45 mph o mas mabagal","55 mph o mas mabagal"],"h1":"Pareho ito sa speed limit sa karamihan ng mga kalye sa tirahan.","h2":"Sa Wisconsin, ang orange na tatsulok na karatulang Slow Moving Vehicle ay nangangahulugang ang sasakyan ay maaaring tumatakbo nang 25 milya kada oras o mas mabagal.","p":"Tama. Maaaring 25 mph o mas mabagal ang takbo nito."},"ar":{"q":"في Wisconsin، توجد لافتة مثلثة برتقالية على مؤخرة مركبة. ما السرعة التي قد تسير بها هذه المركبة؟","o":["25 mph أو أقل","35 mph أو أقل","45 mph أو أقل","55 mph أو أقل"],"h1":"هي مثل حد السرعة في معظم الشوارع السكنية.","h2":"في Wisconsin، لافتة المركبة البطيئة المثلثة البرتقالية تعني أن المركبة قد تسير بسرعة 25 ميلًا في الساعة أو أقل.","p":"صحيح. قد تسير بسرعة 25 mph أو أقل."},"ref":{"doc":"WI","page":25}},{"id":"wi-045","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, when may you use a hand-held cell phone while driving through a construction zone?","o":["Any time traffic is stopped","Any time you go under 25 mph","Only to report an emergency","Any time if you are 18 or older"],"h1":"Workers are close to the road, so your full attention is needed.","h2":"In Wisconsin, you may use a hand-held cell phone in a construction zone only to report an emergency. Traffic fines are also doubled there.","p":"Right. Only to report an emergency."},"es":{"q":"En Wisconsin, ¿cuándo puede usar un teléfono celular en la mano mientras maneja por una zona de construcción?","o":["Siempre que el tráfico esté detenido","Siempre que vaya a menos de 25 mph","Solo para reportar una emergencia","Siempre, si tiene 18 años o más"],"h1":"Hay trabajadores cerca de la carretera, así que se necesita toda su atención.","h2":"En Wisconsin, usted puede usar un teléfono celular en la mano en una zona de construcción solo para reportar una emergencia. Allí las multas también son el doble.","p":"Correcto. Solo para reportar una emergencia."},"zh":{"q":"在 Wisconsin，开车经过施工区时，什么时候可以用手持手机？","o":["只要车流停下就可以","只要车速低于 25 mph 就可以","只为报告紧急情况","只要你 18 岁或以上就随时可以"],"h1":"工人离道路很近，所以你需要全神贯注。","h2":"在 Wisconsin，在施工区只有为了报告紧急情况才可以用手持手机。那里的交通罚款也会加倍。","p":"对。只为报告紧急情况。"},"vi":{"q":"Ở Wisconsin, khi nào bạn được dùng điện thoại cầm tay khi lái xe qua khu vực công trường?","o":["Bất cứ khi nào xe cộ dừng lại","Bất cứ khi nào bạn chạy dưới 25 mph","Chỉ để báo cáo trường hợp khẩn cấp","Bất cứ lúc nào nếu bạn từ 18 tuổi trở lên"],"h1":"Công nhân ở gần đường, nên bạn cần tập trung hoàn toàn.","h2":"Ở Wisconsin, bạn chỉ được dùng điện thoại cầm tay trong khu vực công trường để báo cáo trường hợp khẩn cấp. Tiền phạt giao thông ở đó cũng tăng gấp đôi.","p":"Đúng. Chỉ để báo cáo trường hợp khẩn cấp."},"tl":{"q":"Sa Wisconsin, kailan ka puwedeng gumamit ng hawak na cell phone habang nagmamaneho sa construction zone?","o":["Anumang oras na nakahinto ang trapiko","Anumang oras na mas mabagal ka sa 25 mph","Para lang mag-report ng emergency","Anumang oras kung 18 ka o mas matanda"],"h1":"Malapit sa kalsada ang mga trabahador, kaya kailangan ang buong atensyon mo.","h2":"Sa Wisconsin, puwede kang gumamit ng hawak na cell phone sa construction zone para lang mag-report ng emergency. Doble rin ang multa sa trapiko roon.","p":"Tama. Para lang mag-report ng emergency."},"ar":{"q":"في Wisconsin، متى يمكنك استخدام الهاتف المحمول باليد أثناء القيادة في منطقة أعمال إنشاء؟","o":["في أي وقت يتوقف فيه السير","في أي وقت تسير بأقل من 25 mph","فقط للإبلاغ عن حالة طارئة","في أي وقت إذا كان عمرك 18 أو أكثر"],"h1":"العمال قريبون من الطريق، لذلك تحتاج إلى انتباهك الكامل.","h2":"في Wisconsin، يمكنك استخدام الهاتف المحمول باليد في منطقة أعمال الإنشاء فقط للإبلاغ عن حالة طارئة. وتتضاعف غرامات المرور هناك أيضًا.","p":"صحيح. فقط للإبلاغ عن حالة طارئة."},"ref":{"doc":"WI","page":26}},{"id":"wi-046","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, your car hits a deer. What does the handbook say about the deer?","o":["You must leave it on the road","You must take it to a game warden","You must pay a fine for it","You may keep it, after police give you a tag"],"h1":"The police play a part, but the deer is not wasted.","h2":"In Wisconsin, if you hit a deer you may keep it, and you call the police so they can give you a tag for it; if you do not want it, the next driver may keep it.","p":"Right. You may keep it once police tag it."},"es":{"q":"En Wisconsin, su carro choca con un venado. ¿Qué dice el manual sobre el venado?","o":["Debe dejarlo en la carretera","Debe llevarlo a un guardabosques","Debe pagar una multa por él","Puede quedárselo, después de que la policía le dé una etiqueta"],"h1":"La policía participa, pero el venado no se desperdicia.","h2":"En Wisconsin, si choca con un venado puede quedárselo, y llama a la policía para que le den una etiqueta; si no lo quiere, el siguiente conductor puede quedárselo.","p":"Correcto. Puede quedárselo cuando la policía le dé la etiqueta."},"zh":{"q":"在 Wisconsin，你的车撞到一只鹿。驾驶手册对这只鹿怎么说？","o":["你必须把它留在路上","你必须把它送到野生动物管理员那里","你必须为它交罚款","警察给你标签后，你可以留下它"],"h1":"警察会参与，但鹿不会被浪费。","h2":"在 Wisconsin，如果你撞到鹿，你可以留下它，你要打电话给警察，让他们给你一个标签；如果你不想要，下一位司机可以留下它。","p":"对。警察给它挂上标签后，你可以留下它。"},"vi":{"q":"Ở Wisconsin, xe của bạn đâm phải một con nai. Sổ tay nói gì về con nai?","o":["Bạn phải để nó lại trên đường","Bạn phải mang nó đến kiểm lâm","Bạn phải đóng tiền phạt vì nó","Bạn có thể giữ nó, sau khi cảnh sát đưa bạn một thẻ"],"h1":"Cảnh sát có vai trò, nhưng con nai không bị bỏ phí.","h2":"Ở Wisconsin, nếu bạn đâm phải một con nai, bạn có thể giữ nó, và bạn gọi cảnh sát để họ đưa bạn một thẻ cho nó; nếu bạn không muốn, tài xế kế tiếp có thể giữ nó.","p":"Đúng. Bạn có thể giữ nó khi cảnh sát gắn thẻ."},"tl":{"q":"Sa Wisconsin, nabangga ng kotse mo ang isang usa. Ano ang sinasabi ng handbook tungkol sa usa?","o":["Dapat mo itong iwan sa kalsada","Dapat mo itong dalhin sa game warden","Dapat kang magbayad ng multa para dito","Puwede mo itong itago, pagkatapos kang bigyan ng pulis ng tag"],"h1":"May papel ang pulis, pero hindi masasayang ang usa.","h2":"Sa Wisconsin, kung nakabangga ka ng usa puwede mo itong itago, at tatawag ka sa pulis para mabigyan ka nila ng tag para dito; kung ayaw mo, puwede itong itago ng susunod na driver.","p":"Tama. Puwede mo itong itago kapag na-tag na ng pulis."},"ar":{"q":"في Wisconsin، صدمت سيارتك غزالًا. ماذا يقول دليل السائق عن الغزال؟","o":["يجب أن تتركه على الطريق","يجب أن تأخذه إلى حارس الصيد","يجب أن تدفع غرامة بسببه","يمكنك الاحتفاظ به بعد أن تعطيك الشرطة بطاقة له"],"h1":"للشرطة دور، لكن الغزال لا يضيع.","h2":"في Wisconsin، إذا صدمت غزالًا يمكنك الاحتفاظ به، وتتصل بالشرطة لتعطيك بطاقة له؛ وإن لم تُرده، يمكن للسائق التالي أن يحتفظ به.","p":"صحيح. يمكنك الاحتفاظ به بعد أن تضع الشرطة بطاقة عليه."},"ref":{"doc":"WI","page":43}},{"id":"wi-047","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, who is a habitual traffic offender?","o":["Someone with 3 major or 6 minor violations in 3 years","Someone with 4 major or 12 minor violations in 5 years","Someone with 5 major or 15 minor violations in 10 years","Someone with 2 major or 8 minor violations in 2 years"],"h1":"The time window is five years.","h2":"In Wisconsin, a habitual traffic offender has four or more major or twelve or more minor violations within five years, and loses the driving privilege for five years.","p":"Right. Four major or twelve minor in five years."},"es":{"q":"En Wisconsin, ¿quién es un infractor de tránsito habitual?","o":["Alguien con 3 infracciones graves o 6 menores en 3 años","Alguien con 4 infracciones graves o 12 menores en 5 años","Alguien con 5 infracciones graves o 15 menores en 10 años","Alguien con 2 infracciones graves u 8 menores en 2 años"],"h1":"El período es de cinco años.","h2":"En Wisconsin, un infractor de tránsito habitual tiene cuatro o más infracciones graves o doce o más menores en cinco años, y pierde el privilegio de manejar por cinco años.","p":"Correcto. Cuatro graves o doce menores en cinco años."},"zh":{"q":"在 Wisconsin，谁是惯常交通违规者？","o":["3 年内有 3 次重大或 6 次轻微违规的人","5 年内有 4 次重大或 12 次轻微违规的人","10 年内有 5 次重大或 15 次轻微违规的人","2 年内有 2 次重大或 8 次轻微违规的人"],"h1":"时间范围是五年。","h2":"在 Wisconsin，惯常交通违规者是在五年内有四次或更多重大违规，或十二次或更多轻微违规的人，会被取消驾驶权五年。","p":"对。五年内四次重大或十二次轻微违规。"},"vi":{"q":"Ở Wisconsin, ai là người vi phạm giao thông thường xuyên?","o":["Người có 3 vi phạm nặng hoặc 6 vi phạm nhẹ trong 3 năm","Người có 4 vi phạm nặng hoặc 12 vi phạm nhẹ trong 5 năm","Người có 5 vi phạm nặng hoặc 15 vi phạm nhẹ trong 10 năm","Người có 2 vi phạm nặng hoặc 8 vi phạm nhẹ trong 2 năm"],"h1":"Khoảng thời gian là năm năm.","h2":"Ở Wisconsin, người vi phạm giao thông thường xuyên là người có từ bốn vi phạm nặng trở lên hoặc từ mười hai vi phạm nhẹ trở lên trong vòng năm năm, và bị mất quyền lái xe trong năm năm.","p":"Đúng. Bốn vi phạm nặng hoặc mười hai vi phạm nhẹ trong năm năm."},"tl":{"q":"Sa Wisconsin, sino ang habitual traffic offender?","o":["Taong may 3 malaki o 6 na maliit na paglabag sa loob ng 3 taon","Taong may 4 na malaki o 12 maliit na paglabag sa loob ng 5 taon","Taong may 5 malaki o 15 maliit na paglabag sa loob ng 10 taon","Taong may 2 malaki o 8 maliit na paglabag sa loob ng 2 taon"],"h1":"Limang taon ang panahon.","h2":"Sa Wisconsin, ang habitual traffic offender ay may apat o higit pang malaking paglabag o labindalawa o higit pang maliit na paglabag sa loob ng limang taon, at nawawalan ng pribilehiyong magmaneho nang limang taon.","p":"Tama. Apat na malaki o labindalawang maliit sa loob ng limang taon."},"ar":{"q":"في Wisconsin، من هو مرتكب المخالفات المرورية المعتاد؟","o":["من لديه 3 مخالفات كبيرة أو 6 صغيرة خلال 3 سنوات","من لديه 4 مخالفات كبيرة أو 12 صغيرة خلال 5 سنوات","من لديه 5 مخالفات كبيرة أو 15 صغيرة خلال 10 سنوات","من لديه مخالفتان كبيرتان أو 8 صغيرة خلال سنتين"],"h1":"المدة الزمنية خمس سنوات.","h2":"في Wisconsin، مرتكب المخالفات المرورية المعتاد هو من لديه أربع مخالفات كبيرة أو أكثر، أو اثنتا عشرة مخالفة صغيرة أو أكثر، خلال خمس سنوات، ويفقد حق القيادة لمدة خمس سنوات.","p":"صحيح. أربع كبيرة أو اثنتا عشرة صغيرة خلال خمس سنوات."},"ref":{"doc":"WI","page":53}},{"id":"wi-048","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how much may you drive with an occupational license?","o":["Up to 12 hours a day and 60 hours a week","Up to 8 hours a day and 40 hours a week","Up to 10 hours a day and 50 hours a week","Up to 16 hours a day and 80 hours a week"],"h1":"It is half of each day.","h2":"In Wisconsin, an occupational license lets you drive up to 12 hours a day and 60 hours a week, for work, school and needed trips such as groceries and medical visits.","p":"Right. Up to 12 hours a day and 60 a week."},"es":{"q":"En Wisconsin, ¿cuánto puede manejar con una licencia ocupacional?","o":["Hasta 12 horas al día y 60 horas a la semana","Hasta 8 horas al día y 40 horas a la semana","Hasta 10 horas al día y 50 horas a la semana","Hasta 16 horas al día y 80 horas a la semana"],"h1":"Es la mitad de cada día.","h2":"En Wisconsin, una licencia ocupacional le permite manejar hasta 12 horas al día y 60 horas a la semana, para el trabajo, la escuela y viajes necesarios como compras de comida y citas médicas.","p":"Correcto. Hasta 12 horas al día y 60 a la semana."},"zh":{"q":"在 Wisconsin，持职业驾照可以开多少时间？","o":["每天最多 12 小时，每周最多 60 小时","每天最多 8 小时，每周最多 40 小时","每天最多 10 小时，每周最多 50 小时","每天最多 16 小时，每周最多 80 小时"],"h1":"是每天的一半。","h2":"在 Wisconsin，职业驾照让你每天最多开 12 小时、每周最多开 60 小时，用于工作、上学和必要的出行，例如买菜和看病。","p":"对。每天最多 12 小时，每周最多 60 小时。"},"vi":{"q":"Ở Wisconsin, với bằng lái nghề nghiệp (occupational license), bạn được lái bao nhiêu?","o":["Tối đa 12 giờ một ngày và 60 giờ một tuần","Tối đa 8 giờ một ngày và 40 giờ một tuần","Tối đa 10 giờ một ngày và 50 giờ một tuần","Tối đa 16 giờ một ngày và 80 giờ một tuần"],"h1":"Đó là một nửa của mỗi ngày.","h2":"Ở Wisconsin, bằng lái nghề nghiệp cho phép bạn lái tối đa 12 giờ một ngày và 60 giờ một tuần, để đi làm, đi học và các chuyến đi cần thiết như mua thực phẩm và đi khám bệnh.","p":"Đúng. Tối đa 12 giờ một ngày và 60 giờ một tuần."},"tl":{"q":"Sa Wisconsin, gaano katagal ka puwedeng magmaneho gamit ang occupational license?","o":["Hanggang 12 oras bawat araw at 60 oras bawat linggo","Hanggang 8 oras bawat araw at 40 oras bawat linggo","Hanggang 10 oras bawat araw at 50 oras bawat linggo","Hanggang 16 na oras bawat araw at 80 oras bawat linggo"],"h1":"Kalahati ito ng bawat araw.","h2":"Sa Wisconsin, pinapayagan ka ng occupational license na magmaneho nang hanggang 12 oras bawat araw at 60 oras bawat linggo, para sa trabaho, paaralan at mga kailangang lakad gaya ng pamimili ng pagkain at pagpunta sa doktor.","p":"Tama. Hanggang 12 oras bawat araw at 60 bawat linggo."},"ar":{"q":"في Wisconsin، كم يمكنك أن تقود برخصة العمل (occupational license)؟","o":["حتى 12 ساعة في اليوم و60 ساعة في الأسبوع","حتى 8 ساعات في اليوم و40 ساعة في الأسبوع","حتى 10 ساعات في اليوم و50 ساعة في الأسبوع","حتى 16 ساعة في اليوم و80 ساعة في الأسبوع"],"h1":"هي نصف كل يوم.","h2":"في Wisconsin، تسمح لك رخصة العمل بالقيادة حتى 12 ساعة في اليوم و60 ساعة في الأسبوع، للعمل والدراسة والمشاوير الضرورية مثل شراء الطعام وزيارة الطبيب.","p":"صحيح. حتى 12 ساعة في اليوم و60 في الأسبوع."},"ref":{"doc":"WI","page":53}},{"id":"wi-049","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, you are inside a roundabout when an emergency vehicle with a siren comes in. What should you do?","o":["Stop where you are in the roundabout","Speed up and go around again","Leave at the next exit, then pull over","Stop next to the center island"],"h1":"Avoid stopping inside the roundabout.","h2":"In Wisconsin, if you are already in a roundabout when an emergency vehicle comes, leave safely at the next exit and then pull over.","p":"Right. Exit first, then pull over."},"es":{"q":"En Wisconsin, usted está dentro de una glorieta cuando entra un vehículo de emergencia con sirena. ¿Qué debe hacer?","o":["Detenerse donde está en la glorieta","Acelerar y dar otra vuelta","Salir por la siguiente salida y luego orillarse","Detenerse junto a la isla del centro"],"h1":"Evite detenerse dentro de la glorieta.","h2":"En Wisconsin, si ya está en una glorieta cuando llega un vehículo de emergencia, salga con cuidado por la siguiente salida y luego oríllese.","p":"Correcto. Primero salga y luego oríllese."},"zh":{"q":"在 Wisconsin，你在环岛里时，一辆鸣着警笛的紧急车辆开进来。你应该怎么做？","o":["在环岛里原地停下","加速再绕一圈","从下一个出口出去，然后靠边停车","在中心岛旁边停下"],"h1":"不要在环岛里停车。","h2":"在 Wisconsin，如果紧急车辆来时你已经在环岛里，要安全地从下一个出口出去，然后靠边停车。","p":"对。先出去，再靠边停车。"},"vi":{"q":"Ở Wisconsin, bạn đang ở trong vòng xuyến thì một xe cấp cứu có còi hú chạy vào. Bạn nên làm gì?","o":["Dừng lại ngay chỗ bạn đang ở trong vòng xuyến","Tăng tốc và đi thêm một vòng","Ra ở lối ra kế tiếp, rồi tấp vào lề","Dừng lại cạnh đảo ở giữa"],"h1":"Tránh dừng lại bên trong vòng xuyến.","h2":"Ở Wisconsin, nếu bạn đã ở trong vòng xuyến khi xe cấp cứu đến, hãy ra an toàn ở lối ra kế tiếp rồi tấp vào lề.","p":"Đúng. Ra khỏi vòng xuyến trước, rồi tấp vào lề."},"tl":{"q":"Sa Wisconsin, nasa loob ka ng roundabout nang pumasok ang emergency vehicle na may sirena. Ano ang dapat mong gawin?","o":["Huminto kung nasaan ka sa roundabout","Bumilis at umikot muli","Lumabas sa susunod na exit, saka tumabi","Huminto sa tabi ng isla sa gitna"],"h1":"Iwasang huminto sa loob ng roundabout.","h2":"Sa Wisconsin, kung nasa loob ka na ng roundabout nang dumating ang emergency vehicle, lumabas nang ligtas sa susunod na exit at saka tumabi.","p":"Tama. Lumabas muna, saka tumabi."},"ar":{"q":"في Wisconsin، أنت داخل الدوار عندما تدخل مركبة طوارئ بصفارة. ماذا يجب أن تفعل؟","o":["توقف مكانك داخل الدوار","أسرع ودُر مرة أخرى","اخرج من المخرج التالي، ثم توقف على جانب الطريق","توقف بجانب الجزيرة الوسطى"],"h1":"تجنّب التوقف داخل الدوار.","h2":"في Wisconsin، إذا كنت داخل الدوار عندما تأتي مركبة طوارئ، فاخرج بأمان من المخرج التالي ثم توقف على جانب الطريق.","p":"صحيح. اخرج أولًا، ثم توقف على جانب الطريق."},"ref":{"doc":"WI","page":39}},{"id":"wi-050","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what does the handbook say about headphones while driving?","o":["They are fine if the music is quiet","They are fine on highways only","They are fine if you are 18 or older","Do not wear ones that cover or go in both ears"],"h1":"You must be able to hear sirens.","h2":"In Wisconsin, do not drive wearing headphones or a headset that covers or goes in both ears, so you can hear emergency vehicles.","p":"Right. Keep both ears free to hear sirens."},"es":{"q":"En Wisconsin, ¿qué dice el manual sobre los audífonos mientras maneja?","o":["Están bien si la música está baja","Están bien solo en autopistas","Están bien si tiene 18 años o más","No use los que cubren o entran en ambos oídos"],"h1":"Usted debe poder oír las sirenas.","h2":"En Wisconsin, no maneje con audífonos que cubren o entran en ambos oídos, para que pueda oír los vehículos de emergencia.","p":"Correcto. Deje ambos oídos libres para oír las sirenas."},"zh":{"q":"在 Wisconsin，驾驶手册对开车时戴耳机怎么说？","o":["音乐声音小就可以","只在高速公路上可以","你 18 岁或以上就可以","不要戴盖住双耳或塞进双耳的耳机"],"h1":"你必须能听到警笛声。","h2":"在 Wisconsin，开车时不要戴盖住双耳或塞进双耳的耳机或头戴式耳机，这样你才能听到紧急车辆。","p":"对。让双耳保持空着，才能听到警笛。"},"vi":{"q":"Ở Wisconsin, sổ tay nói gì về tai nghe khi lái xe?","o":["Được nếu nhạc nhỏ","Chỉ được trên xa lộ","Được nếu bạn từ 18 tuổi trở lên","Đừng đeo loại che hoặc nhét vào cả hai tai"],"h1":"Bạn phải nghe được tiếng còi hú.","h2":"Ở Wisconsin, đừng lái xe khi đeo tai nghe hoặc bộ tai nghe che hoặc nhét vào cả hai tai, để bạn có thể nghe thấy xe cấp cứu.","p":"Đúng. Để cả hai tai trống để nghe còi hú."},"tl":{"q":"Sa Wisconsin, ano ang sinasabi ng handbook tungkol sa headphones habang nagmamaneho?","o":["Ayos lang kung mahina ang musika","Ayos lang sa highway lang","Ayos lang kung 18 ka o mas matanda","Huwag magsuot ng tumatakip o pumapasok sa dalawang tainga"],"h1":"Kailangan mong marinig ang mga sirena.","h2":"Sa Wisconsin, huwag magmaneho nang may suot na headphones o headset na tumatakip o pumapasok sa dalawang tainga, para marinig mo ang mga emergency vehicle.","p":"Tama. Panatilihing malaya ang dalawang tainga para marinig ang sirena."},"ar":{"q":"في Wisconsin، ماذا يقول دليل السائق عن سماعات الأذن أثناء القيادة؟","o":["لا بأس بها إذا كانت الموسيقى هادئة","لا بأس بها على الطرق السريعة فقط","لا بأس بها إذا كان عمرك 18 أو أكثر","يجب ألّا تلبس سماعات تغطي الأذنين كلتيهما أو تدخل فيهما"],"h1":"يجب أن تستطيع سماع صفارات الطوارئ.","h2":"في Wisconsin، يجب ألّا تقود وأنت تلبس سماعات أو سماعة رأس تغطي الأذنين كلتيهما أو تدخل فيهما، حتى تستطيع سماع مركبات الطوارئ.","p":"صحيح. اترك أذنيك كلتيهما حرتين لتسمع الصفارات."},"ref":{"doc":"WI","page":49}},{"id":"wi-051","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how wide a field of vision must you have from the center of each eye to get a regular car license?","o":["30 degrees","50 degrees","70 degrees","120 degrees"],"h1":"It is between 60 and 80 degrees.","h2":"Wisconsin requires a 70-degree field of vision from the center of each eye.","p":"Right. You need a 70-degree field of vision from each eye."},"es":{"q":"En Wisconsin, ¿qué campo de visión debe tener desde el centro de cada ojo para obtener una licencia regular de carro?","o":["30 grados","50 grados","70 grados","120 grados"],"h1":"Está entre 60 y 80 grados.","h2":"Wisconsin exige un campo de visión de 70 grados desde el centro de cada ojo.","p":"Correcto. Necesita un campo de visión de 70 grados en cada ojo."},"ref":{"doc":"WI","page":1}},{"id":"wi-052","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, the highway signs test has 15 questions. How many must you answer correctly to pass?","o":["10","12","14","15"],"h1":"You need 80 percent.","h2":"You must answer 12 of the 15 signs questions correctly to pass.","p":"Right. 12 of 15 correct is a pass."},"es":{"q":"En Wisconsin, el examen de señales de tránsito tiene 15 preguntas. ¿Cuántas debe contestar bien para aprobar?","o":["10","12","14","15"],"h1":"Necesita el 80 por ciento.","h2":"Debe contestar bien 12 de las 15 preguntas de señales para aprobar.","p":"Correcto. Con 12 de 15 correctas aprueba."},"ref":{"doc":"WI","page":1}},{"id":"wi-053","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, about how long does the knowledge test take at a DMV service center?","o":["About 15 minutes","About 45 minutes","About 2 hours","About 4 hours"],"h1":"Plan for less than an hour, and arrive well before closing.","h2":"The knowledge test takes about 45 minutes, so start it well before the DMV closes.","p":"Right. Allow about 45 minutes for the test."},"es":{"q":"En Wisconsin, ¿cuánto tiempo dura más o menos el examen de conocimientos en un centro del DMV?","o":["Unos 15 minutos","Unos 45 minutos","Unas 2 horas","Unas 4 horas"],"h1":"Calcule menos de una hora y llegue mucho antes del cierre.","h2":"El examen de conocimientos dura unos 45 minutos, así que empiécelo mucho antes de que cierre el DMV.","p":"Correcto. Calcule unos 45 minutos para el examen."},"ref":{"doc":"WI","page":1}},{"id":"wi-054","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, a 16-year-old wants to take the knowledge test online at home. How much does it cost?","o":["It is free","$5","$10","$35"],"h1":"The test at a DMV center is free; online at home costs a little.","h2":"Applicants age 15 to 17 may take the knowledge test online for a $10 fee.","p":"Right. The online test for ages 15 to 17 costs $10."},"es":{"q":"En Wisconsin, un joven de 16 años quiere tomar el examen de conocimientos en línea desde su casa. ¿Cuánto cuesta?","o":["Es gratis","$5","$10","$35"],"h1":"En un centro del DMV es gratis; en línea desde casa cuesta un poco.","h2":"Los solicitantes de 15 a 17 años pueden tomar el examen de conocimientos en línea por $10.","p":"Correcto. El examen en línea para 15 a 17 años cuesta $10."},"ref":{"doc":"WI","page":1}},{"id":"wi-055","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, which test do you need an appointment for?","o":["The skills (road) test","The knowledge test","The highway signs test","The vision screening"],"h1":"It is the test where an examiner rides with you.","h2":"You must make an appointment for the skills (road) test; the knowledge and signs tests need no appointment.","p":"Right. Only the road test needs an appointment."},"es":{"q":"En Wisconsin, ¿para qué examen necesita hacer una cita?","o":["El examen práctico de manejo","El examen de conocimientos","El examen de señales de tránsito","El examen de la vista"],"h1":"Es el examen en el que un examinador va con usted en el carro.","h2":"Debe hacer una cita para el examen práctico de manejo; los exámenes de conocimientos y de señales no necesitan cita.","p":"Correcto. Solo el examen de manejo necesita cita."},"ref":{"doc":"WI","page":2}},{"id":"wi-056","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what does the DMV examiner do before your road test starts?","o":["Gives you a written quiz","Asks you to drive on the freeway first","Checks your school report card","Checks that your car is safe, such as the horn, lights and mirrors"],"h1":"The examiner will not ride in a car that is unsafe.","h2":"Before the road test, the examiner checks your car, including the horn, lights, signals, plates, doors and mirrors.","p":"Right. The examiner checks that your car is safe first."},"es":{"q":"En Wisconsin, ¿qué hace el examinador del DMV antes de empezar su examen de manejo?","o":["Le da un examen escrito","Le pide manejar primero en la autopista","Revisa sus calificaciones de la escuela","Revisa que su carro sea seguro, como la bocina, las luces y los espejos"],"h1":"El examinador no se sube a un carro que no sea seguro.","h2":"Antes del examen de manejo, el examinador revisa su carro, incluidos la bocina, las luces, las direccionales, las placas, las puertas y los espejos.","p":"Correcto. Primero el examinador revisa que el carro sea seguro."},"ref":{"doc":"WI","page":2}},{"id":"wi-057","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many documents proving that you live in Wisconsin must you bring when you apply for a license?","o":["One","Two","Three","None"],"h1":"A utility bill and a bank statement would do it.","h2":"You must bring two documents that prove you live in Wisconsin, such as a utility bill or a financial statement.","p":"Right. Bring two proofs of Wisconsin residence."},"es":{"q":"En Wisconsin, ¿cuántos documentos que prueben que vive en Wisconsin debe llevar cuando solicita una licencia?","o":["Uno","Dos","Tres","Ninguno"],"h1":"Un recibo de luz y un estado de cuenta del banco servirían.","h2":"Debe llevar dos documentos que prueben que vive en Wisconsin, como un recibo de servicios o un estado de cuenta.","p":"Correcto. Lleve dos pruebas de que vive en Wisconsin."},"ref":{"doc":"WI","page":3}},{"id":"wi-058","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, what does an adult who sponsors a teen driver agree to?","o":["To be legally and financially responsible for crashes the teen causes","To buy the teen a car","To ride with the teen every time they drive","To pay the teen's traffic tickets only"],"h1":"The sponsor \"accepts liability.\"","h2":"A sponsor accepts liability, which means being legally and financially responsible for incidents the teen causes while driving.","p":"Right. The sponsor takes legal and financial responsibility."},"es":{"q":"En Wisconsin, ¿a qué se compromete el adulto que patrocina a un conductor adolescente?","o":["A ser legal y económicamente responsable por los choques que cause el adolescente","A comprarle un carro al adolescente","A ir con el adolescente cada vez que maneje","A pagar solo las multas del adolescente"],"h1":"El patrocinador \"acepta la responsabilidad\".","h2":"El patrocinador acepta la responsabilidad, es decir, es legal y económicamente responsable por los incidentes que cause el adolescente al manejar.","p":"Correcto. El patrocinador asume la responsabilidad legal y económica."},"ref":{"doc":"WI","page":3}},{"id":"wi-059","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, besides accepting liability, what does a teen's sponsor confirm on the application?","o":["That the teen has a job","That the teen owns a car","That the teen has no siblings who drive","That the teen is enrolled in school and is not habitually truant"],"h1":"It is about school.","h2":"The sponsor confirms that the teen is enrolled in a school program and is not habitually truant.","p":"Right. The sponsor confirms school enrollment and attendance."},"es":{"q":"En Wisconsin, además de aceptar la responsabilidad, ¿qué confirma el patrocinador de un adolescente en la solicitud?","o":["Que el adolescente tiene trabajo","Que el adolescente tiene carro propio","Que el adolescente no tiene hermanos que manejen","Que el adolescente está inscrito en la escuela y no falta habitualmente"],"h1":"Tiene que ver con la escuela.","h2":"El patrocinador confirma que el adolescente está inscrito en un programa escolar y no falta a clases habitualmente.","p":"Correcto. El patrocinador confirma la inscripción y la asistencia escolar."},"ref":{"doc":"WI","page":3}},{"id":"wi-060","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, until what age does a teen driver need an adult sponsor?","o":["Until the instruction permit is issued","Until the road test is passed","Until age 17","Until age 18"],"h1":"The sponsor stays through the probationary license.","h2":"A teen needs a sponsor through the probationary license phase, until turning 18.","p":"Right. A sponsor is needed until age 18."},"es":{"q":"En Wisconsin, ¿hasta qué edad necesita un patrocinador adulto un conductor adolescente?","o":["Hasta que recibe el permiso de aprendizaje","Hasta que aprueba el examen de manejo","Hasta los 17 años","Hasta los 18 años"],"h1":"El patrocinador sigue durante la licencia de prueba.","h2":"Un adolescente necesita patrocinador durante la etapa de licencia de prueba, hasta cumplir 18 años.","p":"Correcto. Necesita patrocinador hasta los 18 años."},"ref":{"doc":"WI","page":3}},{"id":"wi-061","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, a teen does not live with a parent or guardian. Who may sign as the teen's sponsor?","o":["A grandparent","A school teacher","The teen's employer","A friend who is 21"],"h1":"It must be a relative or a foster parent.","h2":"If the teen does not live with a parent or guardian, a grandparent, aunt or uncle, adult sibling, adult spouse or foster parent may sponsor.","p":"Right. A grandparent may sponsor in that case."},"es":{"q":"En Wisconsin, un adolescente no vive con su padre, madre ni tutor. ¿Quién puede firmar como su patrocinador?","o":["Un abuelo o abuela","Un maestro de la escuela","El empleador del adolescente","Un amigo de 21 años"],"h1":"Debe ser un familiar o un padre de crianza.","h2":"Si el adolescente no vive con un padre o tutor, puede patrocinarlo un abuelo, un tío o tía, un hermano adulto, un cónyuge adulto o un padre de crianza.","p":"Correcto. Un abuelo puede ser el patrocinador en ese caso."},"ref":{"doc":"WI","page":4}},{"id":"wi-062","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, a 17-year-old has no living parent. What can they file instead of having a sponsor?","o":["A letter from a teacher","A doctor's note","Proof of insurance","Nothing; they must wait until 18"],"h1":"It shows someone can pay for damage.","h2":"A teen under 18 with no living parent may file proof of insurance instead of having a sponsor.","p":"Right. Proof of insurance can take the place of a sponsor."},"es":{"q":"En Wisconsin, un joven de 17 años no tiene padres vivos. ¿Qué puede presentar en lugar de tener un patrocinador?","o":["Una carta de un maestro","Una nota del médico","Prueba de seguro","Nada; debe esperar hasta los 18"],"h1":"Demuestra que alguien puede pagar los daños.","h2":"Un adolescente menor de 18 años sin padres vivos puede presentar prueba de seguro en lugar de tener patrocinador.","p":"Correcto. La prueba de seguro puede reemplazar al patrocinador."},"ref":{"doc":"WI","page":4}},{"id":"wi-063","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, you are 19 and want an instruction permit. What must you do?","o":["Pass the knowledge test, the highway signs test and the vision screening","Finish a driver education course first","Find an adult sponsor","Wait 6 months after applying"],"h1":"Driver education and a sponsor are rules for applicants under 18.","h2":"At 18 or older, you get an instruction permit by passing the knowledge test, the highway signs test and the vision screening.","p":"Right. Adults need the three tests, not driver education."},"es":{"q":"En Wisconsin, usted tiene 19 años y quiere un permiso de aprendizaje. ¿Qué debe hacer?","o":["Aprobar el examen de conocimientos, el de señales y el de la vista","Terminar primero un curso de educación vial","Conseguir un patrocinador adulto","Esperar 6 meses después de solicitarlo"],"h1":"La educación vial y el patrocinador son reglas para menores de 18.","h2":"A los 18 años o más, obtiene el permiso de aprendizaje al aprobar el examen de conocimientos, el de señales de tránsito y el de la vista.","p":"Correcto. Los adultos necesitan los tres exámenes, no la educación vial."},"ref":{"doc":"WI","page":5}},{"id":"wi-064","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many years of licensed driving experience must the person supervising an instruction permit holder have?","o":["1 year","2 years","5 years","10 years"],"h1":"It is more than one year.","h2":"The supervising driver must have at least two years of licensed driving experience.","p":"Right. The supervisor needs at least two years of experience."},"es":{"q":"En Wisconsin, ¿cuántos años de experiencia manejando con licencia debe tener la persona que supervisa a quien tiene permiso de aprendizaje?","o":["1 año","2 años","5 años","10 años"],"h1":"Es más de un año.","h2":"El conductor que supervisa debe tener al menos dos años de experiencia manejando con licencia.","p":"Correcto. El supervisor necesita al menos dos años de experiencia."},"ref":{"doc":"WI","page":5}},{"id":"wi-065","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, your aunt has a probationary license and wants to supervise your permit driving. May she?","o":["Yes, any license is fine","Yes, if she is over 18","No, the supervisor must hold a valid regular license","Yes, during daylight only"],"h1":"Probationary and occupational licenses do not count.","h2":"The supervisor must hold a valid regular license, not a probationary or occupational license.","p":"Right. Only a regular license holder may supervise."},"es":{"q":"En Wisconsin, su tía tiene una licencia de prueba y quiere supervisarlo mientras practica con su permiso. ¿Puede hacerlo?","o":["Sí, cualquier licencia sirve","Sí, si tiene más de 18 años","No, el supervisor debe tener una licencia regular válida","Sí, pero solo de día"],"h1":"Las licencias de prueba y las ocupacionales no cuentan.","h2":"El supervisor debe tener una licencia regular válida, no una licencia de prueba ni una ocupacional.","p":"Correcto. Solo puede supervisar quien tenga licencia regular."},"ref":{"doc":"WI","page":5}},{"id":"wi-066","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a 16-year-old permit holder wants to practice with a family friend who is 30. What does the friend need first?","o":["A driving instructor certificate","A commercial license","Nothing; any adult may supervise","Written permission from the teen's parent or guardian"],"h1":"The parent has to agree.","h2":"When the permit holder is under 18, a supervisor age 21 or older needs written authorization from the parent or guardian before driving.","p":"Right. The friend needs the parent's written permission."},"es":{"q":"En Wisconsin, un joven de 16 años con permiso de aprendizaje quiere practicar con un amigo de la familia de 30 años. ¿Qué necesita primero el amigo?","o":["Un certificado de instructor de manejo","Una licencia comercial","Nada; cualquier adulto puede supervisar","Permiso por escrito del padre, la madre o el tutor del joven"],"h1":"El padre o la madre tiene que estar de acuerdo.","h2":"Si quien tiene el permiso es menor de 18 años, un supervisor de 21 años o más necesita autorización por escrito del padre o tutor antes de manejar.","p":"Correcto. El amigo necesita el permiso por escrito de los padres."},"ref":{"doc":"WI","page":5}},{"id":"wi-067","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, a permit holder age 16 or older may carry one more licensed passenger, besides the supervisor. Where and how old?","o":["In the front seat, age 18 or older","In any seat, age 21 or older","Not in the front seat, age 25 or older","In the back seat, any age"],"h1":"This extra adult sits behind and is older than 21.","h2":"A permit holder age 16 or older may also carry one licensed person age 25 or older, with 2 years of experience, in a seat other than the front seat.","p":"Right. One extra licensed adult, 25 or older, may ride in back."},"es":{"q":"En Wisconsin, quien tiene permiso de aprendizaje y 16 años o más puede llevar a otro pasajero con licencia, además del supervisor. ¿Dónde y de qué edad?","o":["En el asiento delantero, de 18 años o más","En cualquier asiento, de 21 años o más","No en el asiento delantero, de 25 años o más","En el asiento de atrás, de cualquier edad"],"h1":"Este adulto extra va atrás y tiene más de 21 años.","h2":"Quien tiene permiso y 16 años o más también puede llevar a una persona con licencia de 25 años o más, con 2 años de experiencia, en un asiento que no sea el delantero.","p":"Correcto. Un adulto con licencia, de 25 años o más, puede ir atrás."},"ref":{"doc":"WI","page":5}},{"id":"wi-068","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a permit holder wants to practice after dark with an uncle. How old must a licensed supervisor who is not an instructor be at night?","o":["18","19","21","25"],"h1":"It is older than the daytime rule of 21.","h2":"In darkness, the supervisor must be a qualified instructor or a licensed person age 25 or older with at least two years of experience.","p":"Right. At night the supervisor must be at least 25, or an instructor."},"es":{"q":"En Wisconsin, quien tiene permiso quiere practicar de noche con su tío. ¿Qué edad debe tener de noche un supervisor con licencia que no sea instructor?","o":["18","19","21","25"],"h1":"Es más que la regla de 21 años para el día.","h2":"De noche, el supervisor debe ser un instructor calificado o una persona con licencia de 25 años o más con al menos dos años de experiencia.","p":"Correcto. De noche el supervisor debe tener al menos 25 años, o ser instructor."},"ref":{"doc":"WI","page":5}},{"id":"wi-069","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, who confirms that a teen completed the 50 hours of supervised driving practice?","o":["The teen's sponsor","The DMV examiner","The teen's school principal","A police officer"],"h1":"It is the same adult who signed the application.","h2":"The sponsor verifies that the teen drove at least 50 hours, 10 of them in darkness.","p":"Right. The sponsor verifies the practice hours."},"es":{"q":"En Wisconsin, ¿quién confirma que un adolescente completó las 50 horas de práctica supervisada?","o":["El patrocinador del adolescente","El examinador del DMV","El director de la escuela","Un policía"],"h1":"Es el mismo adulto que firmó la solicitud.","h2":"El patrocinador confirma que el adolescente manejó al menos 50 horas, 10 de ellas de noche.","p":"Correcto. El patrocinador confirma las horas de práctica."},"ref":{"doc":"WI","page":6}},{"id":"wi-070","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, a probationary driver turns 18 four months after getting the license. What happens to the passenger and night limits?","o":["They continue for the full 9 months","They end at age 18","They continue until age 21","They are doubled"],"h1":"The limits last 9 months, unless something comes first.","h2":"The passenger and night limits end at age 18, even if the 9 months are not over.","p":"Right. At 18 the limits no longer apply."},"es":{"q":"En Wisconsin, un conductor con licencia de prueba cumple 18 años cuatro meses después de recibirla. ¿Qué pasa con los límites de pasajeros y de horario nocturno?","o":["Siguen durante los 9 meses completos","Terminan a los 18 años","Siguen hasta los 21 años","Se duplican"],"h1":"Los límites duran 9 meses, a menos que algo pase antes.","h2":"Los límites de pasajeros y de horario nocturno terminan a los 18 años, aunque no hayan pasado los 9 meses.","p":"Correcto. A los 18 años los límites ya no se aplican."},"ref":{"doc":"WI","page":6}},{"id":"wi-071","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, a teen finishes the 9 months of graduated license limits. What must they do to drive without the limits?","o":["Nothing; no new license is needed","Get a new license at the DMV","Retake the road test","Take a new vision test"],"h1":"The limits simply stop.","h2":"No new license is needed when the graduated license limits end.","p":"Right. The limits end without a new license."},"es":{"q":"En Wisconsin, un adolescente termina los 9 meses de límites de la licencia gradual. ¿Qué debe hacer para manejar sin esos límites?","o":["Nada; no necesita una licencia nueva","Sacar una licencia nueva en el DMV","Repetir el examen de manejo","Tomar un nuevo examen de la vista"],"h1":"Los límites simplemente terminan.","h2":"No necesita una licencia nueva cuando terminan los límites de la licencia gradual.","p":"Correcto. Los límites terminan sin licencia nueva."},"ref":{"doc":"WI","page":6}},{"id":"wi-072","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how long before a probationary license expires can you start renewing it to a regular license?","o":["30 days","60 days","90 days","1 year"],"h1":"It is about three months.","h2":"Renewal time starts 90 days before the probationary license expires.","p":"Right. You can renew starting 90 days before it expires."},"es":{"q":"En Wisconsin, ¿cuánto tiempo antes de que venza la licencia de prueba puede empezar a renovarla por una licencia regular?","o":["30 días","60 días","90 días","1 año"],"h1":"Son unos tres meses.","h2":"El plazo de renovación empieza 90 días antes de que venza la licencia de prueba.","p":"Correcto. Puede renovar desde 90 días antes del vencimiento."},"ref":{"doc":"WI","page":7}},{"id":"wi-073","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how far ahead of the expiration date may you renew a regular driver license?","o":["30 days","60 days","6 months","Up to 1 year"],"h1":"It is the longest choice.","h2":"You can renew a regular license up to a year before it expires.","p":"Right. You may renew up to a year early."},"es":{"q":"En Wisconsin, ¿con cuánta anticipación a la fecha de vencimiento puede renovar una licencia regular?","o":["30 días","60 días","6 meses","Hasta 1 año"],"h1":"Es la opción más larga.","h2":"Puede renovar una licencia regular hasta un año antes de que venza.","p":"Correcto. Puede renovar hasta un año antes."},"ref":{"doc":"WI","page":7}},{"id":"wi-074","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, when is the license renewal reminder notice sent?","o":["On your birthday","45 to 60 days before your birthday in the year it expires","One year before it expires","Only after it expires"],"h1":"It comes about one or two months ahead.","h2":"The renewal reminder comes 45 to 60 days before your birthday in the year your license expires.","p":"Right. The reminder arrives 45 to 60 days before your birthday."},"es":{"q":"En Wisconsin, ¿cuándo se envía el aviso para renovar la licencia?","o":["El día de su cumpleaños","De 45 a 60 días antes de su cumpleaños en el año en que vence","Un año antes de que venza","Solo después de que vence"],"h1":"Llega uno o dos meses antes.","h2":"El aviso de renovación llega de 45 a 60 días antes de su cumpleaños en el año en que vence la licencia.","p":"Correcto. El aviso llega de 45 a 60 días antes de su cumpleaños."},"ref":{"doc":"WI","page":7}},{"id":"wi-075","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, you move here with a commercial driver license (CDL) from another state. How soon should you apply for a Wisconsin CDL?","o":["Within 30 days","Within 60 days","Within 90 days","Within 1 year"],"h1":"It is sooner than the 60 days for a regular license.","h2":"You should apply for a Wisconsin CDL within 30 days after moving to Wisconsin.","p":"Right. A CDL should be transferred within 30 days."},"es":{"q":"En Wisconsin, usted se muda aquí con una licencia comercial (CDL) de otro estado. ¿En cuánto tiempo debe solicitar una CDL de Wisconsin?","o":["En 30 días","En 60 días","En 90 días","En 1 año"],"h1":"Es menos que los 60 días de una licencia regular.","h2":"Debe solicitar una CDL de Wisconsin dentro de los 30 días después de mudarse a Wisconsin.","p":"Correcto. La CDL se debe transferir en 30 días."},"ref":{"doc":"WI","page":8}},{"id":"wi-076","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, you had a REAL ID in your old state. What happens when you get a Wisconsin license?","o":["Your REAL ID transfers automatically","You must show all the required documents again to get a Wisconsin REAL ID","Wisconsin does not offer REAL ID","You must wait one year for a REAL ID"],"h1":"Wisconsin checks the documents itself.","h2":"A REAL ID from another state does not carry over; you must present all acceptable documents to Wisconsin.","p":"Right. You must bring your documents again."},"es":{"q":"En Wisconsin, usted tenía una REAL ID en su estado anterior. ¿Qué pasa cuando saca una licencia de Wisconsin?","o":["Su REAL ID se transfiere automáticamente","Debe mostrar de nuevo todos los documentos requeridos para obtener una REAL ID de Wisconsin","Wisconsin no ofrece REAL ID","Debe esperar un año para tener REAL ID"],"h1":"Wisconsin revisa los documentos por su cuenta.","h2":"Una REAL ID de otro estado no se transfiere; debe presentar en Wisconsin todos los documentos aceptables.","p":"Correcto. Debe llevar sus documentos otra vez."},"ref":{"doc":"WI","page":8}},{"id":"wi-077","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how can you tell that a driver license is REAL ID compliant?","o":["It has a red border","It says \"TEMPORARY\" on it","It is marked with a star","It has no photo"],"h1":"Look in the corner of the card for a symbol.","h2":"A Wisconsin REAL ID compliant license or ID card is marked with a star.","p":"Right. A star marks a REAL ID card."},"es":{"q":"En Wisconsin, ¿cómo sabe si una licencia de manejar cumple con REAL ID?","o":["Tiene un borde rojo","Dice \"TEMPORAL\"","Tiene una estrella","No tiene foto"],"h1":"Busque un símbolo en la esquina de la tarjeta.","h2":"Una licencia o identificación de Wisconsin que cumple con REAL ID tiene una estrella.","p":"Correcto. La estrella indica que es REAL ID."},"ref":{"doc":"WI","page":8}},{"id":"wi-078","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what do you need a REAL ID (or another accepted ID, like a passport) for?","o":["To drive a car in Wisconsin","To buy car insurance","To register to vote","To fly within the U.S. or enter a military base"],"h1":"It is a federal rule for airports and federal buildings.","h2":"Since May 7, 2025, you need a REAL ID or another accepted ID, such as a passport, to fly within the U.S. or enter a military base or other federal building.","p":"Right. REAL ID is for domestic flights and federal buildings."},"es":{"q":"En Wisconsin, ¿para qué necesita una REAL ID (u otra identificación aceptada, como el pasaporte)?","o":["Para manejar un carro en Wisconsin","Para comprar seguro de carro","Para registrarse para votar","Para volar dentro de EE. UU. o entrar a una base militar"],"h1":"Es una regla federal para aeropuertos y edificios federales.","h2":"Desde el 7 de mayo de 2025, necesita una REAL ID u otra identificación aceptada, como el pasaporte, para volar dentro de EE. UU. o entrar a una base militar u otro edificio federal.","p":"Correcto. La REAL ID sirve para vuelos nacionales y edificios federales."},"ref":{"doc":"WI","page":8}},{"id":"wi-079","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, you use the four-second following distance rule. It is raining and traffic is heavy. What should you do?","o":["Add one second for each bad condition, making it six seconds","Keep exactly four seconds","Drop to two seconds so others cannot cut in","Add one second only at night"],"h1":"Each adverse condition adds time.","h2":"Add one second for every adverse condition, such as heavy traffic, rain, snow or ice, so rain plus heavy traffic means six seconds.","p":"Right. Add a second for each bad condition."},"es":{"q":"En Wisconsin, usted usa la regla de cuatro segundos de distancia. Está lloviendo y hay mucho tráfico. ¿Qué debe hacer?","o":["Agregar un segundo por cada mala condición, o sea seis segundos","Mantener exactamente cuatro segundos","Bajar a dos segundos para que nadie se meta","Agregar un segundo solo de noche"],"h1":"Cada condición adversa agrega tiempo.","h2":"Agregue un segundo por cada condición adversa, como tráfico pesado, lluvia, nieve o hielo, así que lluvia más tráfico pesado son seis segundos.","p":"Correcto. Agregue un segundo por cada mala condición."},"ref":{"doc":"WI","page":10}},{"id":"wi-080","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, may you go over the speed limit for a short time to pass another vehicle?","o":["Yes, by up to 10 mph","No, never","Yes, on two-lane roads only","Yes, if the other driver is going slowly"],"h1":"The limit is the limit.","h2":"You may not go over the speed limit to pass another vehicle.","p":"Right. Passing never allows speeding."},"es":{"q":"En Wisconsin, ¿puede pasar el límite de velocidad por un momento para rebasar a otro vehículo?","o":["Sí, hasta 10 mph más","No, nunca","Sí, solo en caminos de dos carriles","Sí, si el otro conductor va despacio"],"h1":"El límite es el límite.","h2":"No puede pasar el límite de velocidad para rebasar a otro vehículo.","p":"Correcto. Rebasar nunca permite exceder la velocidad."},"ref":{"doc":"WI","page":18}},{"id":"wi-081","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, what does the handbook say about coasting in neutral while driving?","o":["It saves fuel and is recommended","It is fine on downhill roads","Do not do it; stay in gear so you have full control","It is required at stop signs"],"h1":"Neutral means the engine is not helping you control the car.","h2":"Do not coast in neutral; stay in gear so you have full control of the vehicle.","p":"Right. Stay in gear, do not coast."},"es":{"q":"En Wisconsin, ¿qué dice el manual sobre ir en neutral (sin cambio) mientras maneja?","o":["Ahorra gasolina y se recomienda","Está bien en bajadas","No lo haga; mantenga el cambio puesto para tener control total","Es obligatorio en las señales de alto"],"h1":"En neutral el motor no le ayuda a controlar el carro.","h2":"No vaya en neutral; mantenga el carro en cambio para tener control total del vehículo.","p":"Correcto. Mantenga el cambio puesto, no vaya en neutral."},"ref":{"doc":"WI","page":12}},{"id":"wi-082","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, you are stopped in an intersection waiting to turn left. How should you hold your steering wheel?","o":["Turned to the left, ready to go","Turned to the right","It does not matter","Straight, so a crash from behind will not push you into oncoming traffic"],"h1":"Think about what happens if someone hits you from behind.","h2":"Keep the steering wheel and wheels straight while waiting, so a rear-end crash will not push you into oncoming traffic.","p":"Right. Keep the wheels straight until you turn."},"es":{"q":"En Wisconsin, usted está parado en una intersección esperando para dar vuelta a la izquierda. ¿Cómo debe tener el volante?","o":["Girado a la izquierda, listo para salir","Girado a la derecha","No importa","Derecho, para que un choque por detrás no lo empuje hacia el tráfico de frente"],"h1":"Piense qué pasa si alguien lo choca por detrás.","h2":"Mantenga el volante y las llantas derechos mientras espera, para que un choque por detrás no lo empuje hacia el tráfico que viene de frente.","p":"Correcto. Mantenga las llantas derechas hasta dar la vuelta."},"ref":{"doc":"WI","page":14}},{"id":"wi-083","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, where does the handbook say you may make a U-turn, if it is safe and does not interfere with traffic?","o":["On any rural two-lane highway","On any freeway","In the middle of a downtown block","On a curve with a hill ahead"],"h1":"Think of a quiet country road.","h2":"You may make a U-turn on any rural two-lane highway if it is done safely and does not interfere with traffic.","p":"Right. Rural two-lane highways allow a safe U-turn."},"es":{"q":"En Wisconsin, ¿dónde dice el manual que puede dar una vuelta en U, si es seguro y no estorba al tráfico?","o":["En cualquier carretera rural de dos carriles","En cualquier autopista","A mitad de cuadra en el centro","En una curva antes de una colina"],"h1":"Piense en un camino tranquilo del campo.","h2":"Puede dar una vuelta en U en cualquier carretera rural de dos carriles si lo hace con seguridad y sin estorbar al tráfico.","p":"Correcto. En carreteras rurales de dos carriles se permite una vuelta en U segura."},"ref":{"doc":"WI","page":15}},{"id":"wi-084","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, you turn left from the middle of three left-turn lanes. Which lane should you end up in?","o":["The far-left lane","The middle lane of the new street","The far-right lane","Any lane that is open"],"h1":"Stay in the same position you started in.","h2":"With multiple turn lanes, finish the turn in the matching lane, so the middle lane goes to the middle lane.","p":"Right. Middle lane in, middle lane out."},"es":{"q":"En Wisconsin, usted da vuelta a la izquierda desde el carril del medio de tres carriles para vuelta izquierda. ¿En qué carril debe terminar?","o":["En el carril de la extrema izquierda","En el carril del medio de la nueva calle","En el carril de la extrema derecha","En cualquier carril libre"],"h1":"Quédese en la misma posición en la que empezó.","h2":"Con varios carriles de vuelta, termine la vuelta en el carril que corresponde, así que el carril del medio va al carril del medio.","p":"Correcto. Entra por el medio y sale por el medio."},"ref":{"doc":"WI","page":16}},{"id":"wi-085","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, when should you use a Y-turn (three-point turn) to turn around?","o":["On a busy highway","At any traffic light","On a residential street too narrow for a U-turn","On a freeway ramp"],"h1":"It is for small, quiet streets.","h2":"Use a Y-turn only on residential streets that are too narrow for a U-turn.","p":"Right. Y-turns are for narrow residential streets."},"es":{"q":"En Wisconsin, ¿cuándo debe usar una vuelta en Y (vuelta en tres movimientos) para regresar?","o":["En una carretera con mucho tráfico","En cualquier semáforo","En una calle residencial demasiado angosta para una vuelta en U","En una rampa de autopista"],"h1":"Es para calles pequeñas y tranquilas.","h2":"Use la vuelta en Y solo en calles residenciales demasiado angostas para una vuelta en U.","p":"Correcto. La vuelta en Y es para calles residenciales angostas."},"ref":{"doc":"WI","page":17}},{"id":"wi-086","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, how many vehicles should you pass at one time?","o":["Two","Three","As many as you can see","One"],"h1":"There may not be time for more.","h2":"Pass only one vehicle at a time, on the left, then move back to your lane.","p":"Right. Pass one vehicle at a time."},"es":{"q":"En Wisconsin, ¿cuántos vehículos debe rebasar a la vez?","o":["Dos","Tres","Todos los que pueda ver","Uno"],"h1":"Puede que no haya tiempo para más.","h2":"Rebase solo un vehículo a la vez, por la izquierda, y luego regrese a su carril.","p":"Correcto. Rebase un vehículo a la vez."},"ref":{"doc":"WI","page":18}},{"id":"wi-087","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, how fast should you go when you back up?","o":["No faster than a slow walk","About 10 mph","About 15 mph","As fast as traffic allows"],"h1":"Think of a person strolling.","h2":"Back up no faster than a slow walk.","p":"Right. Back up at a slow walking speed."},"es":{"q":"En Wisconsin, ¿a qué velocidad debe ir cuando maneja en reversa?","o":["No más rápido que una persona caminando despacio","A unas 10 mph","A unas 15 mph","Tan rápido como lo permita el tráfico"],"h1":"Piense en una persona que pasea.","h2":"Maneje en reversa no más rápido que una persona caminando despacio.","p":"Correcto. En reversa, a paso lento."},"ref":{"doc":"WI","page":18}},{"id":"wi-088","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, the curb is painted yellow. What does it mean?","o":["Parking for 15 minutes","No parking","Parking for disabled drivers only","Loading zone for all cars"],"h1":"Yellow markings on a curb are a warning.","h2":"Parking is not allowed where the curb has yellow markings.","p":"Right. A yellow curb means no parking."},"es":{"q":"En Wisconsin, la orilla de la banqueta está pintada de amarillo. ¿Qué significa?","o":["Estacionamiento por 15 minutos","No estacionarse","Estacionamiento solo para personas con discapacidad","Zona de carga para todos los carros"],"h1":"Las marcas amarillas en la orilla son una advertencia.","h2":"No se permite estacionarse donde la orilla tiene marcas amarillas.","p":"Correcto. La orilla amarilla significa no estacionarse."},"ref":{"doc":"WI","page":18}},{"id":"wi-089","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, how much longer than your car should a parallel parking space be?","o":["1 to 2 feet","3 to 6 feet","8 to 10 feet","12 to 15 feet"],"h1":"A little more than one car door's width.","h2":"Look for a parallel parking space about 3 to 6 feet longer than your vehicle.","p":"Right. About 3 to 6 feet longer than your car."},"es":{"q":"En Wisconsin, ¿cuánto más largo que su carro debe ser un espacio para estacionarse en paralelo?","o":["De 1 a 2 pies","De 3 a 6 pies","De 8 a 10 pies","De 12 a 15 pies"],"h1":"Un poco más que el ancho de una puerta.","h2":"Busque un espacio para estacionarse en paralelo de unos 3 a 6 pies más largo que su vehículo.","p":"Correcto. Unos 3 a 6 pies más largo que su carro."},"ref":{"doc":"WI","page":19}},{"id":"wi-090","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, you start to parallel park. Where do you stop first?","o":["Right behind the space, touching the car in back","In the middle of the space","Even with the car ahead of the space, about 2 feet away from it","About 10 feet away from the car ahead"],"h1":"Line up side by side with the car you will back in behind.","h2":"Signal, then stop even with the vehicle ahead of the space, about 2 feet away from it.","p":"Right. Stop beside the car ahead, about 2 feet away."},"es":{"q":"En Wisconsin, usted empieza a estacionarse en paralelo. ¿Dónde se detiene primero?","o":["Justo detrás del espacio, tocando el carro de atrás","En medio del espacio","A la par del carro que está delante del espacio, a unos 2 pies de él","A unos 10 pies del carro de adelante"],"h1":"Póngase lado a lado con el carro detrás del cual va a entrar.","h2":"Ponga la direccional y deténgase a la par del vehículo que está delante del espacio, a unos 2 pies de él.","p":"Correcto. Pare al lado del carro de adelante, a unos 2 pies."},"ref":{"doc":"WI","page":19}},{"id":"wi-091","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, after you parallel park, how far should you be from the cars in front of and behind you?","o":["At least 6 inches","At least 5 feet","Bumper to bumper is fine","At least 2 feet"],"h1":"Leave them room to get out.","h2":"When you finish parallel parking, be at least 2 feet from the vehicles in front and behind.","p":"Right. Leave at least 2 feet front and back."},"es":{"q":"En Wisconsin, después de estacionarse en paralelo, ¿a qué distancia debe quedar de los carros de adelante y de atrás?","o":["A por lo menos 6 pulgadas","A por lo menos 5 pies","Pegado a ellos está bien","A por lo menos 2 pies"],"h1":"Déjeles espacio para salir.","h2":"Al terminar de estacionarse en paralelo, quede a por lo menos 2 pies de los vehículos de adelante y de atrás.","p":"Correcto. Deje por lo menos 2 pies adelante y atrás."},"ref":{"doc":"WI","page":20}},{"id":"wi-092","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, during which hours must your headlights be on?","o":["From a half hour after sunset to a half hour before sunrise","Only from midnight to 5 a.m.","Only when it is raining","From sunset to midnight only"],"h1":"There is a half hour on each end.","h2":"Headlights must be on from a half hour after sunset to a half hour before sunrise.","p":"Right. Lights on from a half hour after sunset to a half hour before sunrise."},"es":{"q":"En Wisconsin, ¿en qué horario debe llevar las luces delanteras encendidas?","o":["Desde media hora después de la puesta del sol hasta media hora antes del amanecer","Solo de medianoche a las 5 a. m.","Solo cuando llueve","Solo desde la puesta del sol hasta medianoche"],"h1":"Hay media hora en cada extremo.","h2":"Las luces delanteras deben ir encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer.","p":"Correcto. Luces encendidas desde media hora después de la puesta del sol hasta media hora antes del amanecer."},"ref":{"doc":"WI","page":21}},{"id":"wi-093","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how much farther do high beams let you see than low beams?","o":["About the same distance","About 10 percent farther","About twice as far","About five times as far"],"h1":"Think \"double.\"","h2":"High beams let you see about twice as far as low beams.","p":"Right. High beams reach about twice as far."},"es":{"q":"En Wisconsin, ¿cuánto más lejos le permiten ver las luces altas que las bajas?","o":["Más o menos lo mismo","Un 10 por ciento más","Más o menos el doble","Unas cinco veces más"],"h1":"Piense en \"el doble\".","h2":"Las luces altas le permiten ver más o menos el doble de lejos que las bajas.","p":"Correcto. Las luces altas alumbran más o menos el doble."},"ref":{"doc":"WI","page":21}},{"id":"wi-094","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, when should you use only your parking lights?","o":["When driving at dusk","When driving in fog","When following another car at night","When you are parked with the engine idling"],"h1":"The name tells you.","h2":"Parking lights should only be used when you are parked and idling, never instead of headlights while driving.","p":"Right. Parking lights are for when you are parked."},"es":{"q":"En Wisconsin, ¿cuándo debe usar solo las luces de estacionamiento?","o":["Al manejar al anochecer","Al manejar con neblina","Al seguir a otro carro de noche","Cuando está estacionado con el motor encendido"],"h1":"El nombre se lo dice.","h2":"Las luces de estacionamiento solo se usan cuando está estacionado con el motor encendido, nunca en lugar de las luces delanteras al manejar.","p":"Correcto. Las luces de estacionamiento son para cuando está estacionado."},"ref":{"doc":"WI","page":21}},{"id":"wi-095","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, you plan to turn into a driveway just past an intersection. When should you start your turn signal?","o":["Once you have crossed the intersection","Before you reach the intersection","After you start turning","You do not need to signal for a driveway"],"h1":"Signaling too early could make others think you are turning at the intersection.","h2":"If you are turning after an intersection, start signaling once you have crossed the intersection.","p":"Right. Signal after you cross the intersection."},"es":{"q":"En Wisconsin, usted piensa entrar a una entrada de carros justo después de una intersección. ¿Cuándo debe poner la direccional?","o":["Cuando ya cruzó la intersección","Antes de llegar a la intersección","Después de empezar a dar la vuelta","No tiene que poner la direccional para una entrada"],"h1":"Si la pone muy pronto, otros pueden pensar que va a dar vuelta en la intersección.","h2":"Si va a dar vuelta después de una intersección, ponga la direccional cuando ya haya cruzado la intersección.","p":"Correcto. Ponga la direccional después de cruzar la intersección."},"ref":{"doc":"WI","page":21}},{"id":"wi-096","scope":"WI","cat":"signs","sign":null,"c":1,"en":{"q":"In Wisconsin, how often are mile marker (reference marker) signs placed along highways?","o":["Every 5 miles","Every one to two-tenths of a mile","Every 10 miles","Only at exits"],"h1":"They are very close together.","h2":"Wisconsin mile markers are placed every one to two-tenths of a mile to help you report where you are.","p":"Right. They appear every one to two-tenths of a mile."},"es":{"q":"En Wisconsin, ¿cada cuánto se colocan las señales de marcador de millas en las carreteras?","o":["Cada 5 millas","Cada una o dos décimas de milla","Cada 10 millas","Solo en las salidas"],"h1":"Están muy cerca una de otra.","h2":"Los marcadores de millas de Wisconsin se colocan cada una o dos décimas de milla para ayudarle a decir dónde está.","p":"Correcto. Aparecen cada una o dos décimas de milla."},"ref":{"doc":"WI","page":28}},{"id":"wi-097","scope":"WI","cat":"signs","sign":null,"c":2,"en":{"q":"In Wisconsin, what does a county highway route sign look like?","o":["A red and blue shield","A green rectangle with white letters","A white rectangle with rounded corners and black lettering","A brown sign with a white arrow"],"h1":"Wisconsin county roads are often named with letters, like County A.","h2":"A county road sign is a white rectangle with rounded edges and black lettering.","p":"Right. County signs are white with rounded edges."},"es":{"q":"En Wisconsin, ¿cómo es la señal de ruta de una carretera del condado?","o":["Un escudo rojo y azul","Un rectángulo verde con letras blancas","Un rectángulo blanco con esquinas redondeadas y letras negras","Una señal café con una flecha blanca"],"h1":"Las carreteras de condado en Wisconsin muchas veces llevan letras, como County A.","h2":"La señal de carretera del condado es un rectángulo blanco con orillas redondeadas y letras negras.","p":"Correcto. Las señales de condado son blancas con orillas redondeadas."},"ref":{"doc":"WI","page":29}},{"id":"wi-098","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, you drive a car with a manual transmission over railroad tracks. What should you avoid?","o":["Looking both ways","Crossing in a low gear","Keeping a steady speed","Shifting gears while crossing the tracks"],"h1":"You do not want the car to stall on the tracks.","h2":"Do not shift gears while crossing railroad tracks.","p":"Right. Do not shift gears on the tracks."},"es":{"q":"En Wisconsin, usted maneja un carro de cambios manuales y va a cruzar las vías del tren. ¿Qué debe evitar?","o":["Mirar a ambos lados","Cruzar en una velocidad baja","Mantener una velocidad constante","Cambiar de velocidad mientras cruza las vías"],"h1":"No quiere que el carro se apague sobre las vías.","h2":"No cambie de velocidad mientras cruza las vías del tren.","p":"Correcto. No cambie de velocidad sobre las vías."},"ref":{"doc":"WI","page":30}},{"id":"wi-099","scope":"WI","cat":"signs","sign":null,"c":0,"en":{"q":"In Wisconsin, what does an \"EXEMPT\" sign at a railroad crossing mean?","o":["Certain vehicles that usually must stop, like buses, do not have to stop there","No car ever has to look for trains there","The crossing is closed","Only trains may use the crossing"],"h1":"It is about vehicles that normally must stop at every crossing.","h2":"An \"Exempt\" sign means certain vehicles that are normally required to stop are not required to stop before crossing.","p":"Right. Exempt means those vehicles may skip the stop."},"es":{"q":"En Wisconsin, ¿qué significa una señal que dice \"EXEMPT\" en un cruce de tren?","o":["Ciertos vehículos que normalmente deben parar, como los autobuses, no tienen que parar ahí","Ningún carro tiene que fijarse si viene el tren","El cruce está cerrado","Solo los trenes pueden usar el cruce"],"h1":"Tiene que ver con vehículos que normalmente deben parar en todos los cruces.","h2":"Una señal \"Exempt\" significa que ciertos vehículos que normalmente deben parar no tienen que hacerlo antes de cruzar.","p":"Correcto. Exempt significa que esos vehículos pueden no parar."},"ref":{"doc":"WI","page":30}},{"id":"wi-101","scope":"WI","cat":"signals","sign":null,"c":2,"en":{"q":"In Wisconsin, when may you cross a solid white line between lanes?","o":["Whenever traffic is light","Only at night","To avoid a hazard, or when turning within the next block","Never, for any reason"],"h1":"There are two exceptions in the handbook.","h2":"You may cross a solid white lane line only for a hazard or when you are turning within the next block.","p":"Right. Only for a hazard or a turn in the next block."},"es":{"q":"En Wisconsin, ¿cuándo puede cruzar una línea blanca continua entre carriles?","o":["Cuando hay poco tráfico","Solo de noche","Para evitar un peligro, o para dar vuelta en la siguiente cuadra","Nunca, por ningún motivo"],"h1":"El manual da dos excepciones.","h2":"Puede cruzar una línea blanca continua entre carriles solo por un peligro o si va a dar vuelta en la siguiente cuadra.","p":"Correcto. Solo por un peligro o una vuelta en la siguiente cuadra."},"ref":{"doc":"WI","page":34}},{"id":"wi-102","scope":"WI","cat":"signals","sign":null,"c":3,"en":{"q":"In Wisconsin, the center of the road has two solid yellow lines. May you cross them to turn left into a driveway?","o":["No, never","Only if a police officer waves you on","Only on Sundays","Yes, if it is safe"],"h1":"Double yellow lines forbid passing, not every crossing.","h2":"You may cross double solid yellow lines to turn into a driveway when it is safe.","p":"Right. You may cross to turn into a driveway if it is safe."},"es":{"q":"En Wisconsin, el centro del camino tiene dos líneas amarillas continuas. ¿Puede cruzarlas para dar vuelta a la izquierda y entrar a una entrada de carros?","o":["No, nunca","Solo si un policía le hace señas","Solo los domingos","Sí, si es seguro"],"h1":"Las dos líneas amarillas prohíben rebasar, no todo cruce.","h2":"Puede cruzar las dos líneas amarillas continuas para entrar a una entrada de carros cuando sea seguro.","p":"Correcto. Puede cruzarlas para entrar a una entrada de carros si es seguro."},"ref":{"doc":"WI","page":35}},{"id":"wi-103","scope":"WI","cat":"signals","sign":null,"c":0,"en":{"q":"In Wisconsin, a lane is reserved for buses only. When may your car use it?","o":["To turn across it within the next half block","Whenever no bus is in sight","During rush hour","To pass slow traffic"],"h1":"It is about a turn coming up very soon.","h2":"You may enter a reserved lane only if you need to turn across it in the next half of a block.","p":"Right. Only to turn within the next half block."},"es":{"q":"En Wisconsin, un carril está reservado solo para autobuses. ¿Cuándo puede usarlo su carro?","o":["Para dar vuelta cruzándolo dentro de la siguiente media cuadra","Cuando no se ve ningún autobús","En las horas pico","Para rebasar el tráfico lento"],"h1":"Tiene que ver con una vuelta muy cercana.","h2":"Puede entrar a un carril reservado solo si necesita cruzarlo para dar vuelta en la siguiente media cuadra.","p":"Correcto. Solo para dar vuelta en la siguiente media cuadra."},"ref":{"doc":"WI","page":37}},{"id":"wi-104","scope":"WI","cat":"signals","sign":null,"c":1,"en":{"q":"In Wisconsin, what is a \"flex lane\"?","o":["A lane that changes direction every hour","A paved shoulder that may be used as a travel lane when signs show a green arrow","A lane only for motorcycles","A lane for parking during events"],"h1":"It is the shoulder, opened at busy times.","h2":"A flex lane is a paved shoulder that may be used as a travel lane when the signs show a green arrow.","p":"Right. A flex lane is a shoulder opened by a green arrow."},"es":{"q":"En Wisconsin, ¿qué es un \"flex lane\" (carril flexible)?","o":["Un carril que cambia de dirección cada hora","Un acotamiento pavimentado que se puede usar como carril cuando las señales muestran una flecha verde","Un carril solo para motocicletas","Un carril para estacionarse durante eventos"],"h1":"Es el acotamiento, abierto en horas de mucho tráfico.","h2":"Un carril flexible es un acotamiento pavimentado que se puede usar como carril cuando las señales muestran una flecha verde.","p":"Correcto. Es un acotamiento que se abre con flecha verde."},"ref":{"doc":"WI","page":38}},{"id":"wi-105","scope":"WI","cat":"signals","sign":null,"c":2,"en":{"q":"In Wisconsin, which vehicles may never drive in a flex lane?","o":["Cars with one person","Motorcycles","Large trucks","Electric cars"],"h1":"Think of the heaviest vehicles on the road.","h2":"No large trucks may drive in the flex lane.","p":"Right. Large trucks are not allowed in the flex lane."},"es":{"q":"En Wisconsin, ¿qué vehículos nunca pueden usar un carril flexible?","o":["Los carros con una sola persona","Las motocicletas","Los camiones grandes","Los carros eléctricos"],"h1":"Piense en los vehículos más pesados del camino.","h2":"Los camiones grandes no pueden usar el carril flexible.","p":"Correcto. Los camiones grandes no pueden usar el carril flexible."},"ref":{"doc":"WI","page":38}},{"id":"wi-106","scope":"WI","cat":"signals","sign":null,"c":3,"en":{"q":"In Wisconsin, a freeway entrance ramp has a sign that says \"Ramp Metered When Flashing\" and its light is flashing. What should you do?","o":["Ignore the ramp signal and merge","Stop at the top of the ramp and wait for a gap","Back up and use another ramp","Pull up to the white stop line and go when your ramp signal turns green"],"h1":"The flashing sign means the ramp signal is working.","h2":"When the sign is flashing, the ramp is metered: pull up to the white stop line and go when your signal turns green.","p":"Right. Stop at the line and go on green."},"es":{"q":"En Wisconsin, una rampa de entrada a la autopista tiene una señal que dice \"Ramp Metered When Flashing\" y su luz está parpadeando. ¿Qué debe hacer?","o":["No hacer caso al semáforo y entrar","Parar al final de la rampa y esperar un espacio","Echarse en reversa y usar otra rampa","Avanzar hasta la línea blanca de alto y salir cuando su semáforo de rampa se ponga en verde"],"h1":"La señal que parpadea quiere decir que el semáforo de la rampa está funcionando.","h2":"Cuando la señal parpadea, la rampa está regulada: avance hasta la línea blanca de alto y salga cuando su semáforo se ponga en verde.","p":"Correcto. Pare en la línea y salga con la luz verde."},"ref":{"doc":"WI","page":41}},{"id":"wi-107","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, a police officer pulls you over. Where should your hands be?","o":["On top of the steering wheel, in plain sight","In your lap","Reaching for your papers in the glove box","Out the window"],"h1":"The officer wants to see them.","h2":"During a traffic stop, put your hands on top of the steering wheel where the officer can see them.","p":"Right. Keep your hands on top of the wheel."},"es":{"q":"En Wisconsin, un policía le indica que se detenga. ¿Dónde deben estar sus manos?","o":["Arriba del volante, a la vista","En sus piernas","Buscando sus papeles en la guantera","Fuera de la ventana"],"h1":"El policía quiere verlas.","h2":"Durante una parada de tránsito, ponga las manos arriba del volante, donde el policía las vea.","p":"Correcto. Mantenga las manos arriba del volante."},"ref":{"doc":"WI","page":43}},{"id":"wi-108","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, during a traffic stop, what should you do?","o":["Get out and walk to the police car","Stay in the vehicle with your seat belt on","Unbuckle and look for your papers right away","Keep the engine and radio on"],"h1":"Let the officer come to you.","h2":"Stay in your vehicle with your seat belt on, and turn off the engine and the radio.","p":"Right. Stay in the car, belted."},"es":{"q":"En Wisconsin, durante una parada de tránsito, ¿qué debe hacer?","o":["Bajarse y caminar hacia la patrulla","Quedarse en el vehículo con el cinturón de seguridad puesto","Quitarse el cinturón y buscar sus papeles de inmediato","Dejar el motor y el radio encendidos"],"h1":"Deje que el policía venga a usted.","h2":"Quédese en su vehículo con el cinturón puesto, y apague el motor y el radio.","p":"Correcto. Quédese en el carro con el cinturón puesto."},"ref":{"doc":"WI","page":43}},{"id":"wi-109","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, when are deer most active?","o":["At noon","Only in summer afternoons","From sunset to sunrise","Only in the middle of the day in winter"],"h1":"Think of dusk, night and dawn.","h2":"Deer are most active in the hours from sunset to sunrise.","p":"Right. Watch for deer from sunset to sunrise."},"es":{"q":"En Wisconsin, ¿cuándo están más activos los venados?","o":["Al mediodía","Solo en las tardes de verano","Desde la puesta del sol hasta el amanecer","Solo a mediodía en el invierno"],"h1":"Piense en el atardecer, la noche y el amanecer.","h2":"Los venados están más activos desde la puesta del sol hasta el amanecer.","p":"Correcto. Cuidado con los venados desde la puesta del sol hasta el amanecer."},"ref":{"doc":"WI","page":43}},{"id":"wi-110","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what are \"bald tires\"?","o":["New tires with no air","Winter tires with studs","Tires with white sidewalls","Tires so worn that they have little tread, which reduces grip and lengthens stopping"],"h1":"Think about a worn-down surface.","h2":"Bald tires are badly worn tires; they reduce traction and increase stopping distance, especially in bad weather.","p":"Right. Bald tires are worn out and grip poorly."},"es":{"q":"En Wisconsin, ¿qué son las \"llantas lisas\" (bald tires)?","o":["Llantas nuevas sin aire","Llantas de invierno con clavos","Llantas con costados blancos","Llantas tan gastadas que casi no tienen dibujo, lo que reduce el agarre y alarga el frenado"],"h1":"Piense en una superficie muy gastada.","h2":"Las llantas lisas están muy gastadas; reducen el agarre y aumentan la distancia para frenar, sobre todo con mal tiempo.","p":"Correcto. Las llantas lisas están gastadas y agarran mal."},"ref":{"doc":"WI","page":44}},{"id":"wi-111","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, your car does not have anti-lock brakes (ABS). How should you brake on a slippery road?","o":["Gently pump the brakes","Press hard and hold the pedal to the floor","Pull the parking brake","Shift into neutral and coast"],"h1":"Without ABS, you do the pumping yourself.","h2":"Without ABS, gently pump the brakes to keep the car from skidding or sliding.","p":"Right. Without ABS, pump the brakes gently."},"es":{"q":"En Wisconsin, su carro no tiene frenos antibloqueo (ABS). ¿Cómo debe frenar en un camino resbaloso?","o":["Bombear el freno suavemente","Pisar fuerte y mantener el pedal hasta el piso","Jalar el freno de mano","Poner neutral y dejar que avance solo"],"h1":"Sin ABS, usted mismo tiene que bombear.","h2":"Sin ABS, bombee el freno suavemente para que el carro no patine ni se deslice.","p":"Correcto. Sin ABS, bombee el freno suavemente."},"ref":{"doc":"WI","page":44}},{"id":"wi-112","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, cattle are being moved along a rural road ahead of you. What should you do?","o":["Honk so they move out of the way","Yield, slow down, keep a safe distance and do not honk","Drive around them quickly","Flash your high beams at them"],"h1":"A loud noise could scare the animals.","h2":"Yield the right-of-way to livestock, slow down, keep a safe distance and do not honk your horn.","p":"Right. Yield to livestock and do not honk."},"es":{"q":"En Wisconsin, están moviendo ganado por un camino rural delante de usted. ¿Qué debe hacer?","o":["Tocar la bocina para que se quiten","Ceder el paso, bajar la velocidad, mantener distancia y no tocar la bocina","Rodearlos rápido","Echarles las luces altas"],"h1":"Un ruido fuerte podría asustar a los animales.","h2":"Ceda el paso al ganado, baje la velocidad, mantenga una distancia segura y no toque la bocina.","p":"Correcto. Ceda el paso al ganado y no toque la bocina."},"ref":{"doc":"WI","page":45}},{"id":"wi-113","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the youngest age at which a person may drive a farm tractor on a highway?","o":["12","14","16","18"],"h1":"It is the same age as a probationary license.","h2":"No one under 16 may operate a farm tractor or self-propelled farm machinery on highways.","p":"Right. You must be at least 16."},"es":{"q":"En Wisconsin, ¿cuál es la edad mínima para manejar un tractor agrícola en una carretera?","o":["12","14","16","18"],"h1":"Es la misma edad que para la licencia de prueba.","h2":"Nadie menor de 16 años puede manejar un tractor agrícola ni maquinaria agrícola autopropulsada en las carreteras.","p":"Correcto. Debe tener por lo menos 16 años."},"ref":{"doc":"WI","page":45}},{"id":"wi-114","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what happens to a teen driver's chance of a crash with another teen in the car?","o":["It goes down","It stays the same","It goes up only at night","It doubles"],"h1":"Passengers can be a big distraction.","h2":"The chance of a crash doubles when a teen driver has another teen in the vehicle.","p":"Right. One teen passenger doubles the crash risk."},"es":{"q":"En Wisconsin, ¿qué pasa con el riesgo de choque de un conductor adolescente si lleva a otro adolescente en el carro?","o":["Baja","Sigue igual","Sube solo de noche","Se duplica"],"h1":"Los pasajeros pueden distraer mucho.","h2":"El riesgo de choque se duplica cuando un conductor adolescente lleva a otro adolescente en el vehículo.","p":"Correcto. Un pasajero adolescente duplica el riesgo de choque."},"ref":{"doc":"WI","page":46}},{"id":"wi-115","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, you see a vehicle stopped on the side of the road ahead. How can you warn the drivers behind you?","o":["Tap your brake pedal three or four times","Honk your horn for a long time","Turn on your high beams","Stop in your lane"],"h1":"Flashing brake lights catch their attention.","h2":"Warn drivers behind you by tapping your brake pedal three or four times.","p":"Right. Tap your brakes a few times."},"es":{"q":"En Wisconsin, usted ve un vehículo parado a un lado del camino más adelante. ¿Cómo puede avisar a los conductores que vienen detrás?","o":["Tocar el pedal del freno tres o cuatro veces","Tocar la bocina un buen rato","Encender las luces altas","Parar en su carril"],"h1":"Las luces de freno que parpadean llaman su atención.","h2":"Avise a los conductores de atrás tocando el pedal del freno tres o cuatro veces.","p":"Correcto. Toque el freno varias veces."},"ref":{"doc":"WI","page":46}},{"id":"wi-116","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, another vehicle is about to hit you from the side. Which crash-avoidance choice may be best?","o":["Stopping right where you are","Speeding up, then slowing down once the danger has passed","Steering into the oncoming lane","Closing your eyes and braking hard"],"h1":"You may be able to get out of its path.","h2":"When another vehicle is about to hit you from the side or from behind, speeding up may be best; slow down again once the danger has passed.","p":"Right. Speeding up can help in that case."},"es":{"q":"En Wisconsin, otro vehículo está a punto de chocarlo por un costado. ¿Qué opción para evitar el choque puede ser la mejor?","o":["Pararse ahí mismo","Acelerar y luego bajar la velocidad cuando pase el peligro","Meterse al carril contrario","Cerrar los ojos y frenar fuerte"],"h1":"Tal vez pueda salir de su camino.","h2":"Cuando otro vehículo está a punto de chocarlo por un costado o por detrás, acelerar puede ser lo mejor; baje la velocidad cuando pase el peligro.","p":"Correcto. Acelerar puede ayudar en ese caso."},"ref":{"doc":"WI","page":46}},{"id":"wi-117","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, your car damages a guardrail. At what amount of damage to government property must you report the crash to police?","o":["$100 or more","$200 or more","$500 or more","$1,000 or more"],"h1":"It is lower than the $1,000 rule for private property.","h2":"A crash must be reported to police if it causes $200 or more in damage to government property, such as signs or guardrails.","p":"Right. $200 or more to government property must be reported."},"es":{"q":"En Wisconsin, su carro daña una barrera de contención. ¿Desde qué monto de daño a propiedad del gobierno debe reportar el choque a la policía?","o":["$100 o más","$200 o más","$500 o más","$1,000 o más"],"h1":"Es menos que la regla de $1,000 para propiedad privada.","h2":"Debe reportar el choque a la policía si causa $200 o más de daño a propiedad del gobierno, como señales o barreras.","p":"Correcto. Desde $200 de daño a propiedad del gobierno debe reportarse."},"ref":{"doc":"WI","page":47}},{"id":"wi-118","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, a minor crash causes little damage, but the other driver seems to be drunk. Must you report it to police?","o":["No, only if damage is over $1,000","No, only if someone is hurt","Yes, a crash must be reported if a driver appears to be under the influence","Only if the other driver agrees"],"h1":"The handbook lists this as its own reason to report.","h2":"You must report a crash to police if a driver appears to be under the influence of alcohol or drugs.","p":"Right. A driver who seems impaired means you report it."},"es":{"q":"En Wisconsin, un choque leve causa poco daño, pero el otro conductor parece estar borracho. ¿Debe reportarlo a la policía?","o":["No, solo si el daño pasa de $1,000","No, solo si alguien está herido","Sí, se debe reportar si un conductor parece estar bajo la influencia","Solo si el otro conductor está de acuerdo"],"h1":"El manual lo pone como un motivo propio para reportar.","h2":"Debe reportar un choque a la policía si un conductor parece estar bajo la influencia del alcohol o las drogas.","p":"Correcto. Si un conductor parece afectado, se reporta."},"ref":{"doc":"WI","page":47}},{"id":"wi-119","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, you are in a crash and someone is injured. What should you do with the vehicles?","o":["Move them to the nearest parking lot","Drive home and call police from there","Push them off the road even if it is unsafe","Do not move them; call 911 and stay at the scene"],"h1":"Police need to see how the crash happened.","h2":"If someone is injured or killed, call 911, stay at the scene and do not move the vehicles.","p":"Right. Leave the vehicles, call 911 and stay."},"es":{"q":"En Wisconsin, usted tiene un choque y alguien está herido. ¿Qué debe hacer con los vehículos?","o":["Llevarlos al estacionamiento más cercano","Irse a su casa y llamar a la policía desde ahí","Empujarlos fuera del camino aunque no sea seguro","No moverlos; llamar al 911 y quedarse en el lugar"],"h1":"La policía necesita ver cómo ocurrió el choque.","h2":"Si alguien está herido o muerto, llame al 911, quédese en el lugar y no mueva los vehículos.","p":"Correcto. No mueva los vehículos, llame al 911 y quédese."},"ref":{"doc":"WI","page":47}},{"id":"wi-120","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, your engine suddenly stops while you are driving. What should you expect?","o":["The steering wheel will be hard to turn; keep the key on and pull over when safe","The car will stop at once by itself","The steering will become lighter","The doors will lock"],"h1":"Power steering needs the engine.","h2":"If the engine stops, hold the wheel, keep the key in the \"on\" position and pull over when safe; the steering will be hard to turn.","p":"Right. Steering gets hard; keep the key on and pull over."},"es":{"q":"En Wisconsin, el motor se apaga de repente mientras maneja. ¿Qué debe esperar?","o":["El volante estará duro; deje la llave en \"on\" y oríllese cuando sea seguro","El carro se detendrá solo de inmediato","El volante se volverá más ligero","Las puertas se cerrarán con seguro"],"h1":"La dirección asistida necesita el motor.","h2":"Si el motor se apaga, sujete el volante, deje la llave en la posición \"on\" y oríllese cuando sea seguro; el volante estará duro.","p":"Correcto. El volante se pone duro; deje la llave en \"on\" y oríllese."},"ref":{"doc":"WI","page":48}},{"id":"wi-121","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how much of a restricted controlled substance (illegal drug) in your system makes driving illegal?","o":["Only an amount that makes you fall asleep","Only amounts above 0.08","Any amount","None; only alcohol counts"],"h1":"There is no safe level.","h2":"Any amount of a restricted controlled substance is treated the same as driving impaired.","p":"Right. Any amount counts."},"es":{"q":"En Wisconsin, ¿qué cantidad de una sustancia controlada restringida (droga ilegal) en su cuerpo hace que manejar sea ilegal?","o":["Solo la cantidad que le dé sueño","Solo más de 0.08","Cualquier cantidad","Ninguna; solo cuenta el alcohol"],"h1":"No hay un nivel seguro.","h2":"Cualquier cantidad de una sustancia controlada restringida se trata igual que manejar intoxicado.","p":"Correcto. Cualquier cantidad cuenta."},"ref":{"doc":"WI","page":49}},{"id":"wi-122","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, when may you drive on a sidewalk?","o":["When the road is blocked","To pass a slow car","To park for a few minutes","Only to cross it, such as at a driveway"],"h1":"Sidewalks are for people on foot.","h2":"It is illegal to drive on a sidewalk unless you are crossing it, such as at a driveway.","p":"Right. Only to cross it."},"es":{"q":"En Wisconsin, ¿cuándo puede manejar sobre una banqueta?","o":["Cuando el camino está bloqueado","Para rebasar a un carro lento","Para estacionarse unos minutos","Solo para cruzarla, como en una entrada de carros"],"h1":"Las banquetas son para los peatones.","h2":"Es ilegal manejar sobre una banqueta a menos que la esté cruzando, como en una entrada de carros.","p":"Correcto. Solo para cruzarla."},"ref":{"doc":"WI","page":51}},{"id":"wi-123","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, why should you leave extra room when following a motorcycle?","o":["A motorcycle can stop faster than most vehicles","Motorcycles always go slower than the limit","Motorcycles have no brake lights","It is required only at night"],"h1":"It is light and its brakes work quickly.","h2":"Motorcycles are lightweight and can stop faster than most vehicles, so give them extra room when you follow.","p":"Right. A motorcycle can stop faster than your car."},"es":{"q":"En Wisconsin, ¿por qué debe dejar más espacio cuando va detrás de una motocicleta?","o":["Una motocicleta puede frenar más rápido que la mayoría de los vehículos","Las motocicletas siempre van más lento que el límite","Las motocicletas no tienen luces de freno","Solo es obligatorio de noche"],"h1":"Es liviana y sus frenos actúan rápido.","h2":"Las motocicletas son livianas y pueden frenar más rápido que la mayoría de los vehículos, así que deles más espacio cuando las siga.","p":"Correcto. Una motocicleta puede frenar más rápido que su carro."},"ref":{"doc":"WI","page":51}},{"id":"wi-124","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, a bicyclist is riding in the middle of your traffic lane. What does the handbook say?","o":["The bicyclist must ride on the sidewalk","Bicyclists may use the whole lane; do not share the lane with them","You may squeeze past in the same lane","Honk until the bicyclist moves over"],"h1":"A bicycle has a right to the lane.","h2":"Bicyclists can use the whole traffic lane, so do not share a lane with them; wait to pass safely.","p":"Right. Bicyclists may use the full lane."},"es":{"q":"En Wisconsin, un ciclista va por el centro de su carril. ¿Qué dice el manual?","o":["El ciclista debe ir por la banqueta","Los ciclistas pueden usar todo el carril; no comparta el carril con ellos","Puede pasar apretado en el mismo carril","Toque la bocina hasta que se haga a un lado"],"h1":"La bicicleta tiene derecho al carril.","h2":"Los ciclistas pueden usar todo el carril, así que no comparta el carril con ellos; espere para rebasar con seguridad.","p":"Correcto. Los ciclistas pueden usar todo el carril."},"ref":{"doc":"WI","page":52}},{"id":"wi-125","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, about how far in front of a large truck is its No-Zone, where the driver cannot see you?","o":["About 20 feet","About 2 feet","About 100 feet","About 500 feet"],"h1":"It is much shorter than the No-Zone behind the truck.","h2":"A large truck's No-Zone reaches about 20 feet in front of it.","p":"Right. About 20 feet in front is a No-Zone."},"es":{"q":"En Wisconsin, ¿más o menos hasta qué distancia delante de un camión grande llega su zona ciega (No-Zone), donde el conductor no lo ve?","o":["Unos 20 pies","Unos 2 pies","Unos 100 pies","Unos 500 pies"],"h1":"Es mucho más corta que la zona ciega detrás del camión.","h2":"La zona ciega de un camión grande llega unos 20 pies delante de él.","p":"Correcto. Unos 20 pies adelante es zona ciega."},"ref":{"doc":"WI","page":52}},{"id":"wi-126","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how long is the driving privilege revoked for a habitual traffic offender?","o":["6 months","1 year","5 years","For life"],"h1":"It matches the number of years used to count the violations.","h2":"A habitual traffic offender loses the driving privilege for five years.","p":"Right. The revocation lasts five years."},"es":{"q":"En Wisconsin, ¿por cuánto tiempo se revoca el privilegio de manejar a un infractor habitual de tránsito?","o":["6 meses","1 año","5 años","De por vida"],"h1":"Es el mismo número de años que se usa para contar las infracciones.","h2":"Un infractor habitual de tránsito pierde el privilegio de manejar por cinco años.","p":"Correcto. La revocación dura cinco años."},"ref":{"doc":"WI","page":53}},{"id":"wi-127","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, a habitual traffic offender wants an occupational license. How long must they wait first?","o":["30 days","2 years","4 years","They can never get one"],"h1":"It is less than half of the five-year revocation.","h2":"A habitual traffic offender may be eligible for an occupational license after a two-year waiting period.","p":"Right. The wait is two years."},"es":{"q":"En Wisconsin, un infractor habitual de tránsito quiere una licencia ocupacional. ¿Cuánto tiempo debe esperar primero?","o":["30 días","2 años","4 años","Nunca puede obtenerla"],"h1":"Es menos de la mitad de la revocación de cinco años.","h2":"Un infractor habitual de tránsito puede tener derecho a una licencia ocupacional después de esperar dos años.","p":"Correcto. La espera es de dos años."},"ref":{"doc":"WI","page":53}},{"id":"wi-128","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what must you show to get an occupational license after losing your driving privilege?","o":["A new vision test only","A letter from your employer only","A paid parking ticket","Proof of financial responsibility (an SR22 insurance certificate)"],"h1":"It shows you are insured.","h2":"To get an occupational license you must show proof of financial responsibility, which is an SR22 insurance certificate.","p":"Right. You need proof of financial responsibility."},"es":{"q":"En Wisconsin, ¿qué debe presentar para obtener una licencia ocupacional después de perder el privilegio de manejar?","o":["Solo un nuevo examen de la vista","Solo una carta de su empleador","Una multa de estacionamiento pagada","Prueba de responsabilidad financiera (un certificado de seguro SR22)"],"h1":"Demuestra que tiene seguro.","h2":"Para obtener una licencia ocupacional debe presentar prueba de responsabilidad financiera, que es un certificado de seguro SR22.","p":"Correcto. Necesita prueba de responsabilidad financiera."},"ref":{"doc":"WI","page":53}},{"id":"wi-129","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, you have an invisible disability, one that other people cannot see. What can you do?","o":["Nothing; the DMV does not accept this","Put a sign on your car window","Disclose it to the DMV, so police officers can see it on your record","Get a special license plate automatically"],"h1":"There is a DMV form for this.","h2":"You may report an invisible disability to the DMV with form MV2167; the information is available to law enforcement officers.","p":"Right. You can disclose it to the DMV, and police can see it."},"es":{"q":"En Wisconsin, usted tiene una discapacidad no visible, que otras personas no pueden ver. ¿Qué puede hacer?","o":["Nada; el DMV no acepta esto","Poner un letrero en la ventana del carro","Informarla al DMV, para que la policía pueda verla en su registro","Recibir una placa especial automáticamente"],"h1":"Hay un formulario del DMV para esto.","h2":"Puede informar una discapacidad no visible al DMV con el formulario MV2167; la información está disponible para los agentes de policía.","p":"Correcto. Puede informarla al DMV y la policía puede verla."},"ref":{"doc":"WI","page":54}},{"id":"wi-130","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how old must a U.S. citizen be to start the petition process for a free ID card for voting?","o":["16","17","18","21"],"h1":"It is one year younger than the voting age.","h2":"You must be at least 17 and a U.S. citizen to start the free voting ID petition process.","p":"Right. You can start at 17."},"es":{"q":"En Wisconsin, ¿qué edad debe tener un ciudadano de EE. UU. para empezar el trámite de una identificación gratuita para votar?","o":["16","17","18","21"],"h1":"Es un año menos que la edad para votar.","h2":"Debe tener por lo menos 17 años y ser ciudadano de EE. UU. para empezar el trámite de la identificación gratuita para votar.","p":"Correcto. Puede empezar a los 17."},"ref":{"doc":"WI","page":54}},{"id":"wi-131","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, how loose should the shoulder belt be across your chest?","o":["Loose enough to hang over your arm","So tight you cannot breathe deeply","It should go under your arm","Loose enough to fit your fist between the belt and your chest"],"h1":"Make a fist and check.","h2":"Adjust the shoulder belt so that you can put your fist between the belt and your chest.","p":"Right. A fist should fit between the belt and your chest."},"es":{"q":"En Wisconsin, ¿qué tan flojo debe ir el cinturón de hombro sobre su pecho?","o":["Tan flojo que cuelgue sobre su brazo","Tan apretado que no pueda respirar hondo","Debe ir por debajo del brazo","Lo justo para que quepa su puño entre el cinturón y el pecho"],"h1":"Haga un puño y compruébelo.","h2":"Ajuste el cinturón de hombro de modo que quepa su puño entre el cinturón y el pecho.","p":"Correcto. Debe caber su puño entre el cinturón y el pecho."},"ref":{"doc":"WI","page":55}},{"id":"wi-132","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, until what age must a child generally ride in a child safety seat (before moving to a booster seat)?","o":["Age 2","Age 4","Age 6","Age 8"],"h1":"The booster seat comes after this age and lasts until 8.","h2":"Children generally must ride in a child safety seat until age four, then in a booster seat until age eight.","p":"Right. A child safety seat until age four."},"es":{"q":"En Wisconsin, ¿hasta qué edad debe ir un niño, en general, en una silla de seguridad infantil (antes de pasar a un asiento elevador)?","o":["Hasta los 2 años","Hasta los 4 años","Hasta los 6 años","Hasta los 8 años"],"h1":"El asiento elevador viene después de esta edad y dura hasta los 8.","h2":"En general, los niños deben ir en silla de seguridad infantil hasta los cuatro años y luego en asiento elevador hasta los ocho.","p":"Correcto. Silla de seguridad hasta los cuatro años."},"ref":{"doc":"WI","page":55}},{"id":"wi-133","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, you borrow a friend's car. Whose job is it to make sure the car is insured?","o":["Yours, as the driver","Only your friend's","The DMV's","No one's, for a short trip"],"h1":"You are the one driving it on the road.","h2":"If you drive someone else's car, it is your job to make sure it has insurance.","p":"Right. The driver must make sure the car is insured."},"es":{"q":"En Wisconsin, usted le pide prestado el carro a un amigo. ¿A quién le toca asegurarse de que el carro tenga seguro?","o":["A usted, como conductor","Solo a su amigo","Al DMV","A nadie, si es un viaje corto"],"h1":"Usted es quien lo maneja en el camino.","h2":"Si maneja el carro de otra persona, a usted le toca asegurarse de que tenga seguro.","p":"Correcto. El conductor debe asegurarse de que el carro tenga seguro."},"ref":{"doc":"WI","page":55}},{"id":"wi-134","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, what does the Driver Education Grant Program do?","o":["Gives free cars to new drivers","Pays traffic fines for teens","Pays for driver training for teens who are income eligible","Lets teens skip the road test"],"h1":"It helps families who cannot afford driver education.","h2":"The Driver Education Grant Program lets the state pay for classroom and behind-the-wheel training for income-eligible teens.","p":"Right. It pays for driver training for eligible teens."},"es":{"q":"En Wisconsin, ¿qué hace el programa de becas para educación vial (Driver Education Grant Program)?","o":["Regala carros a los nuevos conductores","Paga las multas de los adolescentes","Paga la educación vial de los adolescentes que califican por sus ingresos","Permite saltarse el examen de manejo"],"h1":"Ayuda a las familias que no pueden pagar la educación vial.","h2":"El programa de becas para educación vial permite que el estado pague las clases teóricas y prácticas de los adolescentes que califican por sus ingresos.","p":"Correcto. Paga la educación vial de los adolescentes que califican."},"ref":{"doc":"WI","page":55}},{"id":"wi-135","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, unless a sign says otherwise, what is the speed limit in an alley?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"It is the same as a school zone with children present.","h2":"The speed limit in any alley in Wisconsin is 15 mph unless signs show otherwise.","p":"Right. Alleys are 15 mph."},"es":{"q":"En Wisconsin, si no hay una señal que diga otra cosa, ¿cuál es el límite de velocidad en un callejón?","o":["15 mph","20 mph","25 mph","35 mph"],"h1":"Es igual que en una zona escolar con niños presentes.","h2":"El límite de velocidad en cualquier callejón de Wisconsin es de 15 mph, a menos que las señales indiquen otra cosa.","p":"Correcto. En los callejones es de 15 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-136","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, on a highway with no posted limit and no other fixed limit, what is the speed limit?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"It is the common rural highway limit.","h2":"When no other limit applies or is posted, the Wisconsin speed limit is 55 mph.","p":"Right. The default limit is 55 mph."},"es":{"q":"En Wisconsin, en una carretera sin límite indicado y sin otro límite fijo, ¿cuál es el límite de velocidad?","o":["35 mph","45 mph","50 mph","55 mph"],"h1":"Es el límite común de las carreteras rurales.","h2":"Cuando no se aplica ni se indica otro límite, el límite de velocidad en Wisconsin es de 55 mph.","p":"Correcto. El límite general es de 55 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-137","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the highest speed limit on an expressway (a divided highway that still has some crossroads)?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"It is 5 mph below the freeway limit.","h2":"The speed limit on a Wisconsin expressway is 65 mph where posted; freeways may be posted at 70 mph.","p":"Right. Expressways are 65 mph."},"es":{"q":"En Wisconsin, ¿cuál es el límite de velocidad más alto en una \"expressway\" (carretera dividida que todavía tiene algunos cruces)?","o":["55 mph","60 mph","65 mph","70 mph"],"h1":"Es 5 mph menos que el límite de las autopistas.","h2":"El límite de velocidad en una expressway de Wisconsin es de 65 mph donde está indicado; en las autopistas puede ser de 70 mph.","p":"Correcto. En las expressways es de 65 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-138","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the speed limit on a road marked as a Rustic Road, when signs show it?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"It is 10 mph below the usual rural limit.","h2":"The speed limit on a designated Rustic Road is 45 mph when signs are posted.","p":"Right. Rustic Roads are 45 mph."},"es":{"q":"En Wisconsin, ¿cuál es el límite de velocidad en un camino marcado como Rustic Road (camino rústico), cuando hay señales?","o":["35 mph","45 mph","55 mph","65 mph"],"h1":"Es 10 mph menos que el límite rural normal.","h2":"El límite de velocidad en un Rustic Road designado es de 45 mph cuando hay señales.","p":"Correcto. En los Rustic Roads es de 45 mph."},"ref":{"doc":"WI","page":null}},{"id":"wi-139","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, you are caught speeding in a school zone while children are present. What happens to the fine?","o":["There is no fine, only a warning","The fine is cut in half","The fine is the same as anywhere else","The minimum and maximum fines are doubled"],"h1":"The law adds extra protection for children.","h2":"Speeding fines are doubled when children are present in a zone marked with school signs.","p":"Right. The fines double in a school zone with children."},"es":{"q":"En Wisconsin, lo sorprenden manejando a exceso de velocidad en una zona escolar mientras hay niños. ¿Qué pasa con la multa?","o":["No hay multa, solo una advertencia","La multa se reduce a la mitad","La multa es igual que en cualquier otro lugar","La multa mínima y la máxima se duplican"],"h1":"La ley protege más a los niños.","h2":"Las multas por exceso de velocidad se duplican cuando hay niños en una zona marcada con señales escolares.","p":"Correcto. Las multas se duplican en zona escolar con niños."},"ref":{"doc":"WI","page":null}},{"id":"wi-140","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, a school bus ahead turns on its flashing amber (yellow) lights. What does that mean?","o":["The bus is about to stop; slow down and get ready to stop","You may pass the bus quickly","The bus is broken down","The bus is letting children off right now"],"h1":"Amber comes before red.","h2":"Flashing amber lights mean the bus is getting ready to stop to load or unload children; slow down and prepare to stop.","p":"Right. Amber lights warn that the bus is about to stop."},"es":{"q":"En Wisconsin, un autobús escolar delante de usted enciende sus luces ámbar (amarillas) intermitentes. ¿Qué significa?","o":["El autobús está por detenerse; baje la velocidad y prepárese para parar","Puede rebasar el autobús rápido","El autobús está descompuesto","El autobús está bajando niños en ese momento"],"h1":"El ámbar viene antes del rojo.","h2":"Las luces ámbar intermitentes indican que el autobús se está preparando para detenerse a subir o bajar niños; baje la velocidad y prepárese para parar.","p":"Correcto. Las luces ámbar avisan que el autobús va a detenerse."},"ref":{"doc":"WI","page":null}},{"id":"wi-141","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, an adult school crossing guard signals you to stop. How far from the crossing must you stop?","o":["Right at the crosswalk line","2 to 5 feet","10 to 30 feet","50 to 100 feet"],"h1":"Leave a safe space, but not too far away.","h2":"When a school crossing guard directs you to stop, stop between 10 and 30 feet from the crossing and stay stopped until told to go.","p":"Right. Stop 10 to 30 feet from the crossing."},"es":{"q":"En Wisconsin, un guardia adulto de cruce escolar le indica que se detenga. ¿A qué distancia del cruce debe parar?","o":["Justo en la línea del cruce","De 2 a 5 pies","De 10 a 30 pies","De 50 a 100 pies"],"h1":"Deje un espacio seguro, pero no demasiado lejos.","h2":"Cuando un guardia de cruce escolar le indica que se detenga, pare entre 10 y 30 pies del cruce y quédese parado hasta que le indique avanzar.","p":"Correcto. Pare a 10 a 30 pies del cruce."},"ref":{"doc":"WI","page":null}},{"id":"wi-142","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, which of these vehicles must always stop before crossing railroad tracks?","o":["A pickup truck","A motorcycle","A car pulling a small trailer","A bus carrying passengers"],"h1":"Think of vehicles full of people or dangerous loads.","h2":"A bus carrying passengers must stop 15 to 50 feet from the nearest rail before crossing, as must certain hazardous-cargo vehicles.","p":"Right. Buses with passengers must always stop."},"es":{"q":"En Wisconsin, ¿cuál de estos vehículos siempre debe detenerse antes de cruzar las vías del tren?","o":["Una camioneta pickup","Una motocicleta","Un carro que jala un remolque pequeño","Un autobús con pasajeros"],"h1":"Piense en vehículos llenos de gente o con cargas peligrosas.","h2":"Un autobús con pasajeros debe detenerse de 15 a 50 pies del riel más cercano antes de cruzar, igual que ciertos vehículos con carga peligrosa.","p":"Correcto. Los autobuses con pasajeros siempre deben parar."},"ref":{"doc":"WI","page":null}},{"id":"wi-143","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, the car ahead of you has its left turn signal on. May you pass it on the left?","o":["No, you may not pass on the left a vehicle signaling a left turn","Yes, if you speed up","Yes, on a two-lane road","Yes, if you honk first"],"h1":"It is about to turn into the space you would use.","h2":"You may not pass on the left a vehicle that is signaling a left turn or U-turn.","p":"Right. Never pass on the left a car signaling left."},"es":{"q":"En Wisconsin, el carro de adelante tiene puesta la direccional izquierda. ¿Puede rebasarlo por la izquierda?","o":["No, no puede rebasar por la izquierda a un vehículo que indica vuelta a la izquierda","Sí, si acelera","Sí, en un camino de dos carriles","Sí, si toca la bocina antes"],"h1":"Está a punto de meterse al espacio que usted usaría.","h2":"No puede rebasar por la izquierda a un vehículo que indica que va a dar vuelta a la izquierda o en U.","p":"Correcto. Nunca rebase por la izquierda a un carro que indica vuelta a la izquierda."},"ref":{"doc":"WI","page":null}},{"id":"wi-144","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, outside a city, how far behind another vehicle must a truck over 10,000 pounds stay?","o":["100 feet","200 feet","300 feet","500 feet"],"h1":"It is the longest choice.","h2":"Outside a business or residence district, a truck over 10,000 pounds must stay at least 500 feet behind the vehicle ahead, except when passing.","p":"Right. Heavy trucks must keep 500 feet back."},"es":{"q":"En Wisconsin, fuera de la ciudad, ¿a qué distancia detrás de otro vehículo debe ir un camión de más de 10,000 libras?","o":["100 pies","200 pies","300 pies","500 pies"],"h1":"Es la opción más larga.","h2":"Fuera de una zona comercial o residencial, un camión de más de 10,000 libras debe ir por lo menos a 500 pies detrás del vehículo de adelante, salvo al rebasar.","p":"Correcto. Los camiones pesados deben ir a 500 pies."},"ref":{"doc":"WI","page":null}},{"id":"wi-145","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, a military convoy with its headlights on is going through an intersection. What must you do?","o":["Drive between the vehicles if there is a gap","Yield the right-of-way to it, as you would to a funeral procession","Honk to let them know you are there","Go first because you have a green light"],"h1":"The same rule protects funeral processions.","h2":"At an intersection, you must yield to vehicles in a military convoy or funeral procession that have their headlights on.","p":"Right. Yield to the convoy."},"es":{"q":"En Wisconsin, un convoy militar con las luces encendidas está pasando por una intersección. ¿Qué debe hacer?","o":["Meterse entre los vehículos si hay espacio","Cederle el paso, como lo haría con un cortejo fúnebre","Tocar la bocina para que sepan que está ahí","Pasar primero porque tiene luz verde"],"h1":"La misma regla protege a los cortejos fúnebres.","h2":"En una intersección, debe ceder el paso a los vehículos de un convoy militar o de un cortejo fúnebre que lleven las luces encendidas.","p":"Correcto. Ceda el paso al convoy."},"ref":{"doc":"WI","page":null}},{"id":"wi-146","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, the lead car of a funeral procession goes through on a green light, then the light turns red. What may the rest of the procession do?","o":["Stop and wait for the next green light","Go one car at a time after stopping","Keep going through without stopping","Turn right only"],"h1":"The lead car obeys the signal for everyone.","h2":"Once the lead vehicle has lawfully entered the intersection, the other vehicles in the procession may follow without stopping, regardless of the signal.","p":"Right. The procession may follow the lead car through."},"es":{"q":"En Wisconsin, el primer carro de un cortejo fúnebre cruza con luz verde y luego el semáforo cambia a rojo. ¿Qué pueden hacer los demás carros del cortejo?","o":["Parar y esperar la siguiente luz verde","Pasar uno por uno después de parar","Seguir pasando sin detenerse","Dar vuelta solo a la derecha"],"h1":"El primer carro respeta la señal por todos.","h2":"Una vez que el primer vehículo entró legalmente a la intersección, los demás vehículos del cortejo pueden seguirlo sin detenerse, sin importar la señal.","p":"Correcto. El cortejo puede seguir al primer carro."},"ref":{"doc":"WI","page":null}},{"id":"wi-147","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, the Move Over law applies to an emergency vehicle stopped on or within how many feet of the road?","o":["5 feet","12 feet","25 feet","50 feet"],"h1":"It is about the width of one traffic lane.","h2":"The Move Over law applies when an emergency, roadside service or disabled vehicle is stopped on or within 12 feet of the roadway.","p":"Right. Within 12 feet of the road."},"es":{"q":"En Wisconsin, ¿a cuántos pies del camino, como máximo, puede estar parado un vehículo de emergencia para que se aplique la ley Move Over?","o":["5 pies","12 pies","25 pies","50 pies"],"h1":"Es más o menos el ancho de un carril.","h2":"La ley Move Over se aplica cuando un vehículo de emergencia, de servicio en carretera o descompuesto está parado sobre el camino o a menos de 12 pies de él.","p":"Correcto. A menos de 12 pies del camino."},"ref":{"doc":"WI","page":null}},{"id":"wi-148","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, a driver breaks the Move Over law and damages another person's property. What happens to the license?","o":["Nothing happens to the license","A 7-day suspension","A suspension of 90 days to 1 year","A lifetime revocation"],"h1":"It is at least three months.","h2":"A Move Over violation that damages someone else's property brings a license suspension of 90 days to one year.","p":"Right. The suspension is 90 days to one year."},"es":{"q":"En Wisconsin, un conductor no cumple la ley Move Over y daña la propiedad de otra persona. ¿Qué pasa con su licencia?","o":["No le pasa nada a la licencia","Una suspensión de 7 días","Una suspensión de 90 días a 1 año","Una revocación de por vida"],"h1":"Son por lo menos tres meses.","h2":"Una infracción de la ley Move Over que daña la propiedad de otra persona trae una suspensión de la licencia de 90 días a un año.","p":"Correcto. La suspensión es de 90 días a un año."},"ref":{"doc":"WI","page":null}},{"id":"wi-149","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, fire trucks have stopped at a house fire on a street. Where may you not drive in or park?","o":["At the fire hydrant only","Only in front of the burning house","Nowhere; there are no limits","In that block, or within 300 feet of the fire trucks' access point"],"h1":"Give firefighters the whole block.","h2":"You may not drive into or park within the block where fire apparatus has stopped for an alarm, or within 300 feet of the driveway or road it is using.","p":"Right. Stay out of the block, or 300 feet away."},"es":{"q":"En Wisconsin, los camiones de bomberos se detuvieron en una calle por el incendio de una casa. ¿Dónde no puede entrar con el carro ni estacionarse?","o":["Solo junto al hidrante","Solo frente a la casa que se quema","En ningún lado; no hay límites","En esa cuadra, o a menos de 300 pies del acceso que usan los bomberos"],"h1":"Deje a los bomberos toda la cuadra.","h2":"No puede entrar ni estacionarse en la cuadra donde se detuvieron los camiones de bomberos por una alarma, ni a menos de 300 pies de la entrada o el camino que están usando.","p":"Correcto. No entre a la cuadra o quédese a 300 pies."},"ref":{"doc":"WI","page":null}},{"id":"wi-150","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, a fire hose is lying across the street at a fire. May you drive over it?","o":["No, not without the consent of the fire official in charge","Yes, if you drive slowly","Yes, if the hose is flat","Yes, if no firefighter is near it"],"h1":"Only the person in command can say yes.","h2":"You may not drive over an unprotected fire hose without the consent of the fire department official in command.","p":"Right. Do not drive over it without permission."},"es":{"q":"En Wisconsin, hay una manguera de bomberos atravesada en la calle durante un incendio. ¿Puede pasar con el carro sobre ella?","o":["No, no sin el permiso del jefe de bomberos a cargo","Sí, si pasa despacio","Sí, si la manguera está plana","Sí, si no hay bomberos cerca"],"h1":"Solo la persona a cargo puede dar permiso.","h2":"No puede pasar sobre una manguera de bomberos sin protección sin el permiso del jefe de bomberos a cargo.","p":"Correcto. No pase sobre ella sin permiso."},"ref":{"doc":"WI","page":null}},{"id":"wi-151","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, a snowplow with its lights on is clearing a road posted at 35 mph. How close may you follow it?","o":["No closer than 75 feet","No closer than 25 feet","No closer than 500 feet","As close as you like"],"h1":"On faster roads the distance is 200 feet; on slower roads it is less.","h2":"On a road posted at 35 mph or less, you may not follow a working snowplow closer than 75 feet.","p":"Right. Stay at least 75 feet back on slower roads."},"es":{"q":"En Wisconsin, una quitanieves con las luces encendidas limpia un camino con límite de 35 mph. ¿Qué tan cerca puede seguirla?","o":["No a menos de 75 pies","No a menos de 25 pies","No a menos de 500 pies","Tan cerca como quiera"],"h1":"En caminos más rápidos la distancia es de 200 pies; en los más lentos es menos.","h2":"En un camino con límite de 35 mph o menos, no puede seguir a una quitanieves trabajando a menos de 75 pies.","p":"Correcto. Quédese por lo menos a 75 pies en caminos más lentos."},"ref":{"doc":"WI","page":null}},{"id":"wi-152","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, you come up behind a working snowplow that is stopped at an intersection. Where must you stop?","o":["Right against its rear bumper","Beside it in the next lane","At least 20 feet behind it","You may drive around it on the right"],"h1":"It is the same distance as for a stopped school bus.","h2":"Stop at least 20 feet behind a working snowplow stopped at an intersection, and stay stopped until it moves.","p":"Right. Stop at least 20 feet back."},"es":{"q":"En Wisconsin, usted llega detrás de una quitanieves trabajando que está parada en una intersección. ¿Dónde debe detenerse?","o":["Pegado a su defensa trasera","A su lado en el otro carril","Por lo menos a 20 pies detrás de ella","Puede rodearla por la derecha"],"h1":"Es la misma distancia que para un autobús escolar parado.","h2":"Deténgase por lo menos a 20 pies detrás de una quitanieves trabajando que está parada en una intersección, y espere hasta que avance.","p":"Correcto. Pare por lo menos a 20 pies."},"ref":{"doc":"WI","page":null}},{"id":"wi-153","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, unless a sign shows a greater distance, how close to a fire hydrant may you park?","o":["5 feet","10 feet","20 feet","30 feet"],"h1":"It is a little closer than in many other states.","h2":"In Wisconsin you may not park within 10 feet of a fire hydrant, unless a sign shows a greater distance.","p":"Right. Stay at least 10 feet from a hydrant."},"es":{"q":"En Wisconsin, a menos que una señal indique más distancia, ¿qué tan cerca de un hidrante puede estacionarse?","o":["5 pies","10 pies","20 pies","30 pies"],"h1":"Es un poco menos que en muchos otros estados.","h2":"En Wisconsin no puede estacionarse a menos de 10 pies de un hidrante, a menos que una señal indique más distancia.","p":"Correcto. Quédese por lo menos a 10 pies del hidrante."},"ref":{"doc":"WI","page":null}},{"id":"wi-154","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, how close to a crosswalk may you park?","o":["5 feet","10 feet","15 feet","30 feet"],"h1":"It is between 10 and 20 feet.","h2":"In Wisconsin you may not park closer than 15 feet to the near edge of a crosswalk.","p":"Right. Stay at least 15 feet from a crosswalk."},"es":{"q":"En Wisconsin, ¿qué tan cerca de un cruce peatonal puede estacionarse?","o":["5 pies","10 pies","15 pies","30 pies"],"h1":"Está entre 10 y 20 pies.","h2":"En Wisconsin no puede estacionarse a menos de 15 pies de la orilla cercana de un cruce peatonal.","p":"Correcto. Quédese por lo menos a 15 pies del cruce."},"ref":{"doc":"WI","page":null}},{"id":"wi-155","scope":"WI","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wisconsin, how close to the entrance of a driveway or alley may you park?","o":["4 feet","1 foot","15 feet","25 feet"],"h1":"It is the smallest parking distance in the law.","h2":"You may not park within 4 feet of the entrance to an alley, private road or driveway.","p":"Right. Leave at least 4 feet at a driveway."},"es":{"q":"En Wisconsin, ¿qué tan cerca de la entrada de una cochera o de un callejón puede estacionarse?","o":["4 pies","1 pie","15 pies","25 pies"],"h1":"Es la distancia de estacionamiento más corta de la ley.","h2":"No puede estacionarse a menos de 4 pies de la entrada de un callejón, un camino privado o una entrada de carros.","p":"Correcto. Deje por lo menos 4 pies en una entrada de carros."},"ref":{"doc":"WI","page":null}},{"id":"wi-156","scope":"WI","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wisconsin, how close to the nearest rail of a railroad crossing may you stop or park?","o":["5 feet","10 feet","15 feet","25 feet"],"h1":"It is the longest choice.","h2":"You may not stop or park within 25 feet of the nearest rail at a railroad crossing.","p":"Right. Stay at least 25 feet from the rail."},"es":{"q":"En Wisconsin, ¿qué tan cerca del riel más cercano de un cruce de tren puede detenerse o estacionarse?","o":["5 pies","10 pies","15 pies","25 pies"],"h1":"Es la opción más larga.","h2":"No puede detenerse ni estacionarse a menos de 25 pies del riel más cercano de un cruce de tren.","p":"Correcto. Quédese por lo menos a 25 pies del riel."},"ref":{"doc":"WI","page":null}},{"id":"wi-157","scope":"WI","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wisconsin, on a two-way street without angle parking, which way must your parked car face?","o":["Against traffic, on the left side","In the direction of traffic, on the right side of the street","Either way","Toward the nearest intersection"],"h1":"Park the way you would be driving.","h2":"On a two-way street, park parallel to the curb, facing the direction of traffic on the right side of the street.","p":"Right. Park facing the way traffic moves, on the right."},"es":{"q":"En Wisconsin, en una calle de doble sentido sin estacionamiento en ángulo, ¿hacia dónde debe quedar su carro estacionado?","o":["En contra del tráfico, en el lado izquierdo","En el sentido del tráfico, en el lado derecho de la calle","En cualquier sentido","Hacia la intersección más cercana"],"h1":"Estaciónese como si fuera manejando.","h2":"En una calle de doble sentido, estaciónese en paralelo a la orilla, en el sentido del tráfico y en el lado derecho de la calle.","p":"Correcto. Estaciónese en el sentido del tráfico, a la derecha."},"ref":{"doc":"WI","page":null}},{"id":"wi-158","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, you are using high beams and come up behind another car. Within what distance must you dim them?","o":["100 feet","300 feet","500 feet","1,000 feet"],"h1":"It is the same distance as for an oncoming car in Wisconsin.","h2":"In Wisconsin you must dim your high beams within 500 feet of a vehicle you are following.","p":"Right. Dim within 500 feet when following."},"es":{"q":"En Wisconsin, usted lleva las luces altas y se acerca por detrás a otro carro. ¿A qué distancia debe bajarlas?","o":["100 pies","300 pies","500 pies","1,000 pies"],"h1":"En Wisconsin es la misma distancia que para un carro que viene de frente.","h2":"En Wisconsin debe bajar las luces altas a 500 pies de un vehículo que va delante de usted.","p":"Correcto. Bájelas a 500 pies cuando va detrás de otro."},"ref":{"doc":"WI","page":null}},{"id":"wi-159","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, where may an opened bottle of alcohol be carried in a car on the road?","o":["In the glove compartment","Under the driver's seat","In a passenger's hand","In the trunk"],"h1":"It must be outside the area where people sit.","h2":"An opened container of alcohol may be kept only in the trunk, or in an area not normally used by people; the glove compartment counts as the passenger area.","p":"Right. An open container belongs in the trunk."},"es":{"q":"En Wisconsin, ¿dónde se puede llevar una botella de alcohol abierta en un carro que va por el camino?","o":["En la guantera","Debajo del asiento del conductor","En la mano de un pasajero","En la cajuela"],"h1":"Debe ir fuera del área donde se sienta la gente.","h2":"Un envase de alcohol abierto solo puede ir en la cajuela, o en un área que la gente no ocupa normalmente; la guantera cuenta como área de pasajeros.","p":"Correcto. Un envase abierto va en la cajuela."},"ref":{"doc":"WI","page":null}},{"id":"wi-160","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what is the forfeiture (fine) for texting while driving?","o":["$5 to $10","$1,000 to $2,000","There is no fine","$20 to $400"],"h1":"The maximum is a few hundred dollars.","h2":"Composing or sending a text or email while driving can bring a forfeiture of $20 to $400.","p":"Right. Texting while driving costs $20 to $400."},"es":{"q":"En Wisconsin, ¿cuál es la multa por escribir mensajes de texto mientras maneja?","o":["De $5 a $10","De $1,000 a $2,000","No hay multa","De $20 a $400"],"h1":"El máximo es de unos cientos de dólares.","h2":"Escribir o enviar un mensaje de texto o correo electrónico mientras maneja puede costar una multa de $20 a $400.","p":"Correcto. Escribir mensajes al manejar cuesta de $20 a $400."},"ref":{"doc":"WI","page":null}},{"id":"wi-161","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, may a driver watch a movie on a screen the driver can see while driving?","o":["No, but a GPS or vehicle information display is allowed","Yes, if the sound is off","Yes, on the freeway","Yes, if a passenger holds it"],"h1":"Navigation is fine; entertainment is not.","h2":"A driver may not watch or be able to see a screen showing video entertainment, though GPS and vehicle information screens are allowed.","p":"Right. No video entertainment the driver can see."},"es":{"q":"En Wisconsin, ¿puede un conductor ver una película en una pantalla que alcanza a ver mientras maneja?","o":["No, pero sí se permite un GPS o la pantalla de información del vehículo","Sí, si no tiene sonido","Sí, en la autopista","Sí, si un pasajero la sostiene"],"h1":"La navegación está bien; el entretenimiento no.","h2":"Un conductor no puede ver ni tener a la vista una pantalla con video de entretenimiento, aunque sí se permiten el GPS y las pantallas de información del vehículo.","p":"Correcto. Nada de video de entretenimiento a la vista del conductor."},"ref":{"doc":"WI","page":null}},{"id":"wi-162","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the forfeiture (fine) for not wearing a seat belt?","o":["$1","$10","$100","$250"],"h1":"It is small, but the danger is not.","h2":"Not wearing a seat belt brings a $10 forfeiture in Wisconsin.","p":"Right. The seat belt forfeiture is $10."},"es":{"q":"En Wisconsin, ¿cuál es la multa por no usar el cinturón de seguridad?","o":["$1","$10","$100","$250"],"h1":"Es poca, pero el peligro no.","h2":"No usar el cinturón de seguridad tiene una multa de $10 en Wisconsin.","p":"Correcto. La multa por el cinturón es de $10."},"ref":{"doc":"WI","page":null}},{"id":"wi-163","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, a baby is 10 months old and weighs 22 pounds. How must the baby ride?","o":["In a rear-facing child seat, in the back seat if the car has one","In a forward-facing child seat in front","In a booster seat","On an adult's lap with a seat belt"],"h1":"Under 1 year old means rear-facing, whatever the weight.","h2":"A child under 1 year old or under 20 pounds must ride in a rear-facing child seat, in a back seat if the vehicle has one.","p":"Right. Under one year means rear-facing."},"es":{"q":"En Wisconsin, un bebé tiene 10 meses y pesa 22 libras. ¿Cómo debe ir?","o":["En una silla mirando hacia atrás, en el asiento trasero si el carro tiene","En una silla mirando hacia adelante en el asiento delantero","En un asiento elevador","En las piernas de un adulto con cinturón"],"h1":"Menos de 1 año quiere decir mirando hacia atrás, pese lo que pese.","h2":"Un niño menor de 1 año o de menos de 20 libras debe ir en una silla mirando hacia atrás, en un asiento trasero si el vehículo tiene.","p":"Correcto. Menos de un año, mirando hacia atrás."},"ref":{"doc":"WI","page":null}},{"id":"wi-164","scope":"WI","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wisconsin, a child who is at least 4 may move to a booster seat once they weigh at least how much?","o":["20 pounds","40 pounds","60 pounds","100 pounds"],"h1":"It is twice the rear-facing weight limit of 20 pounds.","h2":"A child at least 4 years old who weighs at least 40 pounds may ride in a booster seat.","p":"Right. At 4 years and 40 pounds, a booster seat is allowed."},"es":{"q":"En Wisconsin, un niño de por lo menos 4 años puede pasar a un asiento elevador. ¿Cuánto debe pesar como mínimo?","o":["20 libras","40 libras","60 libras","100 libras"],"h1":"Es el doble del límite de 20 libras para ir mirando hacia atrás.","h2":"Un niño de por lo menos 4 años que pese por lo menos 40 libras puede ir en un asiento elevador.","p":"Correcto. Con 4 años y 40 libras se permite el asiento elevador."},"ref":{"doc":"WI","page":null}},{"id":"wi-165","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, a car horn must be loud enough to be heard from at least how far away?","o":["20 feet","50 feet","200 feet","1 mile"],"h1":"It is a few hundred feet.","h2":"A car horn must work and be audible under normal conditions from at least 200 feet.","p":"Right. The horn must be heard from 200 feet."},"es":{"q":"En Wisconsin, ¿desde qué distancia, como mínimo, debe oírse la bocina de un carro?","o":["20 pies","50 pies","200 pies","1 milla"],"h1":"Son unos cientos de pies.","h2":"La bocina debe funcionar y oírse en condiciones normales desde por lo menos 200 pies.","p":"Correcto. La bocina debe oírse a 200 pies."},"ref":{"doc":"WI","page":null}},{"id":"wi-166","scope":"WI","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wisconsin, how much light must the front side windows let through if tinting film is added?","o":["At least 10 percent","At least 25 percent","At least 50 percent","At least 90 percent"],"h1":"It is half.","h2":"With tinting film added, the front side windows must let through at least 50 percent of visible light.","p":"Right. Front side windows must pass at least 50 percent of light."},"es":{"q":"En Wisconsin, si se pone película polarizada, ¿cuánta luz deben dejar pasar las ventanas laterales delanteras?","o":["Por lo menos 10 por ciento","Por lo menos 25 por ciento","Por lo menos 50 por ciento","Por lo menos 90 por ciento"],"h1":"Es la mitad.","h2":"Con película polarizada, las ventanas laterales delanteras deben dejar pasar por lo menos el 50 por ciento de la luz visible.","p":"Correcto. Deben dejar pasar por lo menos el 50 por ciento."},"ref":{"doc":"WI","page":null}},{"id":"wi-167","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, may you put studded tires on your own Wisconsin car for winter?","o":["Yes, any car may use them all year","Yes, from November to April","Yes, if the studs are long","No, they are generally limited to emergency vehicles, school buses, mail vehicles and out-of-state cars passing through"],"h1":"Studs damage the pavement, so the law limits them.","h2":"Studded tires are limited to authorized emergency vehicles, school buses, mail delivery vehicles and out-of-state cars passing through for 30 days or less.","p":"Right. Ordinary Wisconsin cars may not use studded tires."},"es":{"q":"En Wisconsin, ¿puede ponerle llantas con clavos a su carro de Wisconsin para el invierno?","o":["Sí, cualquier carro todo el año","Sí, de noviembre a abril","Sí, si los clavos son largos","No, en general solo se permiten en vehículos de emergencia, autobuses escolares, vehículos de correo y carros de otros estados de paso"],"h1":"Los clavos dañan el pavimento, así que la ley los limita.","h2":"Las llantas con clavos se limitan a vehículos de emergencia autorizados, autobuses escolares, vehículos de correo y carros de otros estados que pasan por 30 días o menos.","p":"Correcto. Los carros comunes de Wisconsin no pueden usar llantas con clavos."},"ref":{"doc":"WI","page":null}},{"id":"wi-168","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, a driver has 3 or more prior OWI offenses. Above what alcohol concentration is it illegal for them to drive?","o":["0.02","0.04","0.08","0.10"],"h1":"It is much lower than the 0.08 limit for first offenders.","h2":"A driver with three or more prior OWI offenses may not drive with an alcohol concentration above 0.02.","p":"Right. Their limit is 0.02."},"es":{"q":"En Wisconsin, un conductor tiene 3 o más condenas anteriores por manejar intoxicado (OWI). ¿Por encima de qué concentración de alcohol es ilegal que maneje?","o":["0.02","0.04","0.08","0.10"],"h1":"Es mucho menos que el límite de 0.08 para quien es primerizo.","h2":"Un conductor con tres o más infracciones anteriores de OWI no puede manejar con una concentración de alcohol mayor de 0.02.","p":"Correcto. Su límite es 0.02."},"ref":{"doc":"WI","page":null}},{"id":"wi-169","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the forfeiture for a first OWI offense with no aggravating factors?","o":["$10 to $50","$150 to $300","$5,000 to $10,000","There is no money penalty"],"h1":"It is a few hundred dollars, plus other costs and a license revocation.","h2":"A first OWI offense with no aggravating factors carries a forfeiture of $150 to $300, plus costs and a license revocation.","p":"Right. The forfeiture is $150 to $300."},"es":{"q":"En Wisconsin, ¿cuál es la multa por una primera infracción de manejar intoxicado (OWI) sin factores agravantes?","o":["De $10 a $50","De $150 a $300","De $5,000 a $10,000","No hay multa de dinero"],"h1":"Son unos cientos de dólares, más otros costos y la revocación de la licencia.","h2":"Una primera infracción de OWI sin factores agravantes tiene una multa de $150 a $300, más costos y la revocación de la licencia.","p":"Correcto. La multa es de $150 a $300."},"ref":{"doc":"WI","page":null}},{"id":"wi-170","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a driver is convicted of a first OWI while a child under 16 was in the car. What penalty applies?","o":["Only a warning","The same $150 to $300 forfeiture as any first offense","A $10 forfeiture","A fine of $350 to $1,100 and 5 days to 6 months in jail"],"h1":"A child in the car turns a civil forfeiture into jail time.","h2":"With a passenger under 16, even a first OWI brings a fine of $350 to $1,100 and 5 days to 6 months in jail.","p":"Right. A child passenger means jail and a larger fine."},"es":{"q":"En Wisconsin, un conductor es condenado por una primera infracción de OWI y llevaba en el carro a un niño menor de 16 años. ¿Qué castigo se aplica?","o":["Solo una advertencia","La misma multa de $150 a $300 de cualquier primera infracción","Una multa de $10","Una multa de $350 a $1,100 y de 5 días a 6 meses de cárcel"],"h1":"Un niño en el carro convierte la multa civil en cárcel.","h2":"Con un pasajero menor de 16 años, incluso una primera infracción de OWI tiene una multa de $350 a $1,100 y de 5 días a 6 meses de cárcel.","p":"Correcto. Un niño pasajero significa cárcel y una multa mayor."},"ref":{"doc":"WI","page":null}},{"id":"wi-171","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how long is the license revoked for a first OWI conviction?","o":["1 month","3 months","6 to 9 months","5 years"],"h1":"It is between half a year and three quarters of a year.","h2":"A first OWI conviction brings a license revocation of 6 to 9 months.","p":"Right. The revocation is 6 to 9 months."},"es":{"q":"En Wisconsin, ¿por cuánto tiempo se revoca la licencia por una primera condena de OWI?","o":["1 mes","3 meses","De 6 a 9 meses","5 años"],"h1":"Está entre medio año y tres cuartos de año.","h2":"Una primera condena de OWI trae una revocación de la licencia de 6 a 9 meses.","p":"Correcto. La revocación es de 6 a 9 meses."},"ref":{"doc":"WI","page":null}},{"id":"wi-172","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, at what alcohol concentration does even a first OWI lead to an order for an ignition interlock device?","o":["0.02 or more","0.04 or more","0.08 or more","0.15 or more"],"h1":"It is almost twice the legal limit.","h2":"A court must order an ignition interlock device if the driver had an alcohol concentration of 0.15 or more, even on a first offense.","p":"Right. At 0.15 or more, an interlock is ordered."},"es":{"q":"En Wisconsin, ¿con qué concentración de alcohol incluso una primera infracción de OWI lleva a una orden de instalar un dispositivo de bloqueo de encendido (interlock)?","o":["0.02 o más","0.04 o más","0.08 o más","0.15 o más"],"h1":"Es casi el doble del límite legal.","h2":"El juez debe ordenar un dispositivo de bloqueo de encendido si el conductor tenía una concentración de alcohol de 0.15 o más, aun en una primera infracción.","p":"Correcto. Con 0.15 o más se ordena el interlock."},"ref":{"doc":"WI","page":null}},{"id":"wi-173","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, a driver improperly refuses a chemical test for the second time in 10 years. How long is the license revoked?","o":["6 months","2 years","10 years","For life"],"h1":"The first refusal is one year; it goes up from there.","h2":"A second improper refusal within 10 years brings a two-year revocation.","p":"Right. A second refusal means two years."},"es":{"q":"En Wisconsin, un conductor se niega indebidamente por segunda vez en 10 años a una prueba química. ¿Por cuánto tiempo se revoca la licencia?","o":["6 meses","2 años","10 años","De por vida"],"h1":"La primera negativa es de un año; de ahí sube.","h2":"Una segunda negativa indebida dentro de 10 años trae una revocación de dos años.","p":"Correcto. Una segunda negativa significa dos años."},"ref":{"doc":"WI","page":null}},{"id":"wi-174","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, you are 19 and driving with a closed case of beer in the car. You do not work for an alcohol seller. Is this legal?","o":["No, an underage person may not knowingly transport alcohol in a vehicle","Yes, if the case is closed","Yes, if it is in the trunk","Yes, if a parent bought it"],"h1":"The legal drinking age is 21.","h2":"An underage person may not knowingly possess or transport alcohol in a motor vehicle unless doing so for work; it can lead to a license suspension.","p":"Right. Under 21, you may not carry alcohol in the car."},"es":{"q":"En Wisconsin, usted tiene 19 años y maneja con una caja cerrada de cerveza en el carro. No trabaja para un vendedor de alcohol. ¿Es legal?","o":["No, una persona menor de edad no puede llevar alcohol a sabiendas en un vehículo","Sí, si la caja está cerrada","Sí, si va en la cajuela","Sí, si la compró uno de sus padres"],"h1":"La edad legal para beber es 21 años.","h2":"Una persona menor de edad no puede tener ni transportar alcohol a sabiendas en un vehículo, salvo por su trabajo; puede llevar a la suspensión de la licencia.","p":"Correcto. Menor de 21, no puede llevar alcohol en el carro."},"ref":{"doc":"WI","page":null}},{"id":"wi-175","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the minimum liability insurance for injury to or death of one person in a crash?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"The minimums are written 25/50/10.","h2":"A Wisconsin liability policy must cover at least $25,000 for injury to or death of one person.","p":"Right. $25,000 per person."},"es":{"q":"En Wisconsin, ¿cuál es el seguro de responsabilidad mínimo por lesiones o muerte de una persona en un choque?","o":["$5,000","$10,000","$25,000","$100,000"],"h1":"Los mínimos se escriben 25/50/10.","h2":"Una póliza de responsabilidad en Wisconsin debe cubrir por lo menos $25,000 por lesiones o muerte de una persona.","p":"Correcto. $25,000 por persona."},"ref":{"doc":"WI","page":null}},{"id":"wi-176","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, what is the minimum liability insurance for damage to other people's property in one crash?","o":["$5,000","$10,000","$25,000","$50,000"],"h1":"It is the last number in 25/50/10.","h2":"A Wisconsin liability policy must cover at least $10,000 for damage to the property of others in one crash.","p":"Right. $10,000 for property damage."},"es":{"q":"En Wisconsin, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad de otras personas en un choque?","o":["$5,000","$10,000","$25,000","$50,000"],"h1":"Es el último número de 25/50/10.","h2":"Una póliza de responsabilidad en Wisconsin debe cubrir por lo menos $10,000 por daños a la propiedad de otros en un choque.","p":"Correcto. $10,000 por daños a la propiedad."},"ref":{"doc":"WI","page":null}},{"id":"wi-177","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what is the most you can be fined for driving without liability insurance?","o":["$10","$50","$100","$500"],"h1":"It is the largest choice.","h2":"Driving without the required liability insurance can bring a forfeiture of up to $500.","p":"Right. Up to $500."},"es":{"q":"En Wisconsin, ¿cuál es la multa máxima por manejar sin seguro de responsabilidad?","o":["$10","$50","$100","$500"],"h1":"Es la opción más alta.","h2":"Manejar sin el seguro de responsabilidad obligatorio puede costar una multa de hasta $500.","p":"Correcto. Hasta $500."},"ref":{"doc":"WI","page":null}},{"id":"wi-178","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, an officer asks for your proof of insurance. May you show it on your phone?","o":["Yes, an electronic image on a phone is accepted","No, only the paper card counts","Only if you also mail it to the DMV","Only during the daytime"],"h1":"The law allows printed or electronic proof.","h2":"Proof of insurance may be shown on paper or electronically, such as on a cell phone, and the officer may not look at anything else on the phone.","p":"Right. Proof on your phone is accepted."},"es":{"q":"En Wisconsin, un policía le pide su prueba de seguro. ¿Puede mostrarla en su teléfono?","o":["Sí, se acepta una imagen electrónica en el teléfono","No, solo cuenta la tarjeta de papel","Solo si también la envía por correo al DMV","Solo de día"],"h1":"La ley permite la prueba impresa o electrónica.","h2":"La prueba de seguro se puede mostrar en papel o en forma electrónica, como en un teléfono celular, y el policía no puede ver nada más en el teléfono.","p":"Correcto. Se acepta la prueba en su teléfono."},"ref":{"doc":"WI","page":null}},{"id":"wi-179","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, you had a reportable crash, but no police agency made a report. How soon must you send a written report to the DMV?","o":["Within 24 hours","Within 10 days","Within 30 days","Within 6 months"],"h1":"It is less than two weeks.","h2":"If no police agency reports it, the driver must send a written crash report to the DMV within 10 days.","p":"Right. Send it within 10 days."},"es":{"q":"En Wisconsin, usted tuvo un choque que debe reportarse, pero ninguna agencia de policía hizo un reporte. ¿En cuánto tiempo debe enviar un reporte escrito al DMV?","o":["En 24 horas","En 10 días","En 30 días","En 6 meses"],"h1":"Es menos de dos semanas.","h2":"Si ninguna agencia de policía lo reporta, el conductor debe enviar un reporte escrito del choque al DMV en un plazo de 10 días.","p":"Correcto. Envíelo en 10 días."},"ref":{"doc":"WI","page":null}},{"id":"wi-180","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, you move to a new address. How soon must you tell the DMV or get a new license?","o":["Within 5 days","Within 10 days","Within 30 days","At your next renewal"],"h1":"It is about a month.","h2":"Within 30 days after moving, you must apply for a duplicate license or notify the DMV in writing of your new address.","p":"Right. Within 30 days."},"es":{"q":"En Wisconsin, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar al DMV o sacar una licencia nueva?","o":["En 5 días","En 10 días","En 30 días","En su próxima renovación"],"h1":"Es más o menos un mes.","h2":"En los 30 días siguientes a la mudanza, debe pedir un duplicado de la licencia o avisar por escrito al DMV de su nueva dirección.","p":"Correcto. En 30 días."},"ref":{"doc":"WI","page":null}},{"id":"wi-181","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, who must wear a helmet on a motorcycle?","o":["Riders and passengers under 18, and anyone with a motorcycle instruction permit","Everyone, at all times","Only riders over 65","No one; helmets are never required"],"h1":"It depends on age and on the kind of license.","h2":"A helmet is required for anyone under 18, whether riding or carried as a passenger, and for anyone riding with a motorcycle instruction permit.","p":"Right. Under 18 and permit holders must wear a helmet."},"es":{"q":"En Wisconsin, ¿quién debe usar casco en una motocicleta?","o":["Los conductores y pasajeros menores de 18 años, y quien tenga permiso de aprendizaje de motocicleta","Todos, siempre","Solo los mayores de 65 años","Nadie; el casco nunca es obligatorio"],"h1":"Depende de la edad y del tipo de licencia.","h2":"El casco es obligatorio para cualquier menor de 18 años, ya sea que maneje o vaya de pasajero, y para quien maneje con permiso de aprendizaje de motocicleta.","p":"Correcto. Los menores de 18 y quienes tienen permiso deben usar casco."},"ref":{"doc":"WI","page":null}},{"id":"wi-182","scope":"WI","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wisconsin, what must every motorcycle rider wear, unless the motorcycle has a windshield at least 15 inches above the handlebars?","o":["A leather jacket","Bright orange clothing","Steel-toe boots","Eye protection, such as a face shield, glasses or goggles"],"h1":"It protects the eyes from wind and bugs.","h2":"Every motorcycle rider must wear eye protection, such as a face shield, glasses or goggles, unless the motorcycle has a windshield at least 15 inches above the handlebars.","p":"Right. Eye protection is required."},"es":{"q":"En Wisconsin, ¿qué debe usar todo motociclista, a menos que la moto tenga un parabrisas de por lo menos 15 pulgadas sobre el manubrio?","o":["Una chamarra de cuero","Ropa color naranja brillante","Botas con punta de acero","Protección para los ojos, como una careta, lentes o gafas protectoras"],"h1":"Protege los ojos del viento y los insectos.","h2":"Todo motociclista debe usar protección para los ojos, como una careta, lentes o gafas protectoras, a menos que la moto tenga un parabrisas de por lo menos 15 pulgadas sobre el manubrio.","p":"Correcto. La protección para los ojos es obligatoria."},"ref":{"doc":"WI","page":null}},{"id":"wi-183","scope":"WI","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wisconsin, a bicycle ridden after dark must have a white front light visible from at least how far?","o":["50 feet","100 feet","500 feet","1 mile"],"h1":"It is the same distance used for many vehicle lights.","h2":"At night a bicycle needs a white front light visible from at least 500 feet, plus a red rear reflector or light.","p":"Right. A white front light visible from 500 feet."},"es":{"q":"En Wisconsin, ¿desde qué distancia mínima debe verse la luz blanca delantera de una bicicleta que se usa de noche?","o":["50 pies","100 pies","500 pies","1 milla"],"h1":"Es la misma distancia que se usa para muchas luces de vehículos.","h2":"De noche, una bicicleta necesita una luz blanca delantera visible desde por lo menos 500 pies, además de un reflector o luz roja atrás.","p":"Correcto. Una luz blanca delantera visible a 500 pies."},"ref":{"doc":"WI","page":null}},{"id":"wi-184","scope":"WI","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wisconsin, where is a U-turn not allowed?","o":["In the middle of a block on a street in a business district","At a quiet rural intersection with clear views","At a crossover on a divided highway, where allowed","On an empty rural two-lane road"],"h1":"Think of a busy downtown street.","h2":"You may not make a U-turn in mid-block on a street in a business district, except at a marked crossover on a divided highway.","p":"Right. No mid-block U-turns in a business district."},"es":{"q":"En Wisconsin, ¿dónde no se permite dar una vuelta en U?","o":["A mitad de cuadra en una calle de una zona comercial","En una intersección rural tranquila con buena visibilidad","En un cruce de una carretera dividida, donde se permite","En un camino rural vacío de dos carriles"],"h1":"Piense en una calle concurrida del centro.","h2":"No puede dar vuelta en U a mitad de cuadra en una calle de una zona comercial, salvo en un cruce marcado de una carretera dividida.","p":"Correcto. No hay vueltas en U a mitad de cuadra en zonas comerciales."},"ref":{"doc":"WI","page":null}},{"id":"wi-185","scope":"WI","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wisconsin, on a two-way road with three lanes and no other markings, from which lane do you turn left?","o":["The right lane","The center lane","Any lane","The shoulder"],"h1":"It is the lane in the middle.","h2":"On a two-way road with an uneven number of lanes, make a left turn or U-turn from the center lane unless signs or markings say otherwise.","p":"Right. Turn left from the center lane."},"es":{"q":"En Wisconsin, en un camino de doble sentido con tres carriles y sin otras marcas, ¿desde qué carril da vuelta a la izquierda?","o":["El carril derecho","El carril del centro","Cualquier carril","El acotamiento"],"h1":"Es el carril de en medio.","h2":"En un camino de doble sentido con un número impar de carriles, dé la vuelta a la izquierda o en U desde el carril del centro, a menos que las señales o marcas digan otra cosa.","p":"Correcto. Vuelta a la izquierda desde el carril del centro."},"ref":{"doc":"WI","page":null}},{"id":"wi-186","scope":"WI","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wisconsin, when may you drive your car in a bicycle lane?","o":["To pass slow traffic","Whenever no bicycles are in sight","During rush hour","To enter a driveway or parking space, or to merge into it just before a turn, yielding to bicycles"],"h1":"Only for short moves, and bikes come first.","h2":"You may drive in a bicycle lane only to enter a driveway, to enter or leave a parking space, or to merge into it before turning, and you must yield to bicycles in it.","p":"Right. Only for those short moves, yielding to bikes."},"es":{"q":"En Wisconsin, ¿cuándo puede manejar su carro en un carril para bicicletas?","o":["Para rebasar el tráfico lento","Cuando no se ve ninguna bicicleta","En las horas pico","Para entrar a una cochera o a un espacio de estacionamiento, o para meterse justo antes de dar vuelta, cediendo el paso a las bicicletas"],"h1":"Solo para movimientos cortos, y las bicicletas van primero.","h2":"Solo puede manejar en un carril para bicicletas para entrar a una entrada de carros, entrar o salir de un espacio de estacionamiento, o meterse antes de dar vuelta, y debe ceder el paso a las bicicletas que estén en él.","p":"Correcto. Solo para esos movimientos cortos, cediendo el paso a las bicicletas."},"ref":{"doc":"WI","page":null}},{"id":"wi-187","scope":"WI","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wisconsin, your car radio is so loud it can be heard from the sidewalk. From what distance does it break the law?","o":["75 feet or more","10 feet or more","25 feet or more","1,000 feet or more"],"h1":"It is about the length of five cars.","h2":"It is illegal to play a car radio or other sound system so loudly that it can be heard from 75 feet or more.","p":"Right. Audible from 75 feet or more is illegal."},"es":{"q":"En Wisconsin, el radio de su carro está tan fuerte que se oye desde la banqueta. ¿Desde qué distancia viola la ley?","o":["75 pies o más","10 pies o más","25 pies o más","1,000 pies o más"],"h1":"Es más o menos el largo de cinco carros.","h2":"Es ilegal poner el radio u otro sistema de sonido del carro tan fuerte que se oiga desde 75 pies o más.","p":"Correcto. Que se oiga desde 75 pies o más es ilegal."},"ref":{"doc":"WI","page":null}},{"id":"wi-188","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, your car was issued two license plates. Where do they go?","o":["Both on the rear","One on the front and one on the rear","One on the rear and one inside the windshield","One on the rear; keep the other at home"],"h1":"Wisconsin requires plates at both ends.","h2":"When two plates are issued, one must be attached to the front and one to the rear of the vehicle.","p":"Right. One plate in front, one in back."},"es":{"q":"En Wisconsin, a su carro le dieron dos placas. ¿Dónde van?","o":["Las dos atrás","Una adelante y otra atrás","Una atrás y otra dentro del parabrisas","Una atrás; la otra se guarda en casa"],"h1":"Wisconsin exige placas en ambos extremos.","h2":"Cuando se entregan dos placas, una debe ir en la parte delantera y la otra en la parte trasera del vehículo.","p":"Correcto. Una placa adelante y otra atrás."},"ref":{"doc":"WI","page":null}},{"id":"wi-189","scope":"WI","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wisconsin, what is the forfeiture for parking in a space reserved for people with disabilities without a permit?","o":["$10 to $20","$25 to $50","$150 to $300","$1,000 to $2,000"],"h1":"It is a few hundred dollars.","h2":"Parking in a reserved disability space without the special plate or card brings a forfeiture of $150 to $300.","p":"Right. The forfeiture is $150 to $300."},"es":{"q":"En Wisconsin, ¿cuál es la multa por estacionarse sin permiso en un espacio reservado para personas con discapacidad?","o":["De $10 a $20","De $25 a $50","De $150 a $300","De $1,000 a $2,000"],"h1":"Son unos cientos de dólares.","h2":"Estacionarse en un espacio reservado para personas con discapacidad sin la placa o tarjeta especial tiene una multa de $150 a $300.","p":"Correcto. La multa es de $150 a $300."},"ref":{"doc":"WI","page":null}},{"id":"wi-190","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how many demerit points do you get for driving 10 mph or less over the speed limit?","o":["1","2","3","6"],"h1":"It is half of the points for going 20 or more over.","h2":"Speeding 10 mph or less over the limit adds 3 demerit points.","p":"Right. Up to 10 mph over is 3 points."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito recibe por manejar 10 mph o menos por encima del límite?","o":["1","2","3","6"],"h1":"Es la mitad de los puntos por ir 20 o más por encima.","h2":"Exceder el límite por 10 mph o menos suma 3 puntos de demérito.","p":"Correcto. Hasta 10 mph de más son 3 puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-191","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, may a police officer stop your car only to check whether you have insurance?","o":["Yes, at any time","No, but you can be cited for no insurance after a stop made for another reason","Yes, but only at night","Only if your car is from another state"],"h1":"There must be some other reason for the stop.","h2":"An officer may not stop or inspect a vehicle only to check for insurance, but may cite you for no insurance during a stop made for another reason.","p":"Right. Insurance alone is not a reason to stop you."},"es":{"q":"En Wisconsin, ¿puede un policía detener su carro solo para revisar si tiene seguro?","o":["Sí, en cualquier momento","No, pero le pueden multar por no tener seguro en una parada hecha por otro motivo","Sí, pero solo de noche","Solo si su carro es de otro estado"],"h1":"Tiene que haber otro motivo para la parada.","h2":"Un policía no puede detener ni revisar un vehículo solo para ver si tiene seguro, pero sí puede multarlo por no tenerlo durante una parada hecha por otro motivo.","p":"Correcto. El seguro por sí solo no es motivo para detenerlo."},"ref":{"doc":"WI","page":null}},{"id":"wi-192","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, how many demerit points do you get for driving 20 mph or more over the speed limit?","o":["2","3","4","6"],"h1":"It is the highest point value, the same as reckless driving.","h2":"Speeding 20 mph or more over the limit adds 6 demerit points.","p":"Right. 20 or more over is 6 points."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito recibe por manejar 20 mph o más por encima del límite?","o":["2","3","4","6"],"h1":"Es el valor más alto, igual que manejar de forma imprudente.","h2":"Exceder el límite por 20 mph o más suma 6 puntos de demérito.","p":"Correcto. 20 o más de más son 6 puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-193","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how many demerit points do you get for failing to stop for a school bus with flashing red lights?","o":["2","4","6","12"],"h1":"It is the same as failing to yield the right-of-way.","h2":"Failing to stop for a school bus with its red lights flashing adds 4 demerit points.","p":"Right. It is 4 points."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito recibe por no detenerse ante un autobús escolar con luces rojas intermitentes?","o":["2","4","6","12"],"h1":"Es lo mismo que por no ceder el paso.","h2":"No detenerse ante un autobús escolar con las luces rojas intermitentes suma 4 puntos de demérito.","p":"Correcto. Son 4 puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-194","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, how many demerit points go on your record for not wearing a seat belt?","o":["0","2","3","4"],"h1":"You pay a forfeiture, but your point total does not change.","h2":"A seat belt violation carries no demerit points, though it does bring a forfeiture.","p":"Right. A seat belt ticket adds no points."},"es":{"q":"En Wisconsin, ¿cuántos puntos de demérito se anotan en su registro por no usar el cinturón de seguridad?","o":["0","2","3","4"],"h1":"Paga una multa, pero sus puntos no cambian.","h2":"No usar el cinturón no suma puntos de demérito, aunque sí tiene multa.","p":"Correcto. La multa por cinturón no suma puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-195","scope":"WI","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wisconsin, a driver with a regular license gets 14 demerit points within 12 months. How long is the suspension?","o":["2 months","6 months","1 year","5 years"],"h1":"It is the shortest suspension, for 12 to 16 points.","h2":"With a regular license, 12 to 16 points within 12 months brings a 2-month suspension.","p":"Right. 12 to 16 points means 2 months."},"es":{"q":"En Wisconsin, un conductor con licencia regular acumula 14 puntos de demérito en 12 meses. ¿Cuánto dura la suspensión?","o":["2 meses","6 meses","1 año","5 años"],"h1":"Es la suspensión más corta, para 12 a 16 puntos.","h2":"Con licencia regular, de 12 a 16 puntos en 12 meses trae una suspensión de 2 meses.","p":"Correcto. De 12 a 16 puntos son 2 meses."},"ref":{"doc":"WI","page":null}},{"id":"wi-196","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, a probationary license holder gets 14 demerit points within 12 months. How long is the suspension?","o":["2 weeks","1 month","2 months","6 months"],"h1":"New drivers get a longer suspension than regular license holders.","h2":"With a probationary license or instruction permit, 12 to 30 points within 12 months brings a 6-month suspension.","p":"Right. A probationary driver is suspended for 6 months."},"es":{"q":"En Wisconsin, alguien con licencia de prueba acumula 14 puntos de demérito en 12 meses. ¿Cuánto dura la suspensión?","o":["2 semanas","1 mes","2 meses","6 meses"],"h1":"Los conductores nuevos reciben una suspensión más larga que los de licencia regular.","h2":"Con licencia de prueba o permiso de aprendizaje, de 12 a 30 puntos en 12 meses trae una suspensión de 6 meses.","p":"Correcto. Un conductor con licencia de prueba queda suspendido 6 meses."},"ref":{"doc":"WI","page":null}},{"id":"wi-197","scope":"WI","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wisconsin, how many points can an approved traffic safety course take off your record?","o":["1 point","2 points","3 points","All of your points"],"h1":"It is a small reduction, allowed once every three years.","h2":"Completing an approved traffic safety course reduces your point total by 3 points, once in a three-year period.","p":"Right. The course takes off 3 points."},"es":{"q":"En Wisconsin, ¿cuántos puntos le puede quitar de su registro un curso aprobado de seguridad vial?","o":["1 punto","2 puntos","3 puntos","Todos sus puntos"],"h1":"Es una reducción pequeña, permitida una vez cada tres años.","h2":"Terminar un curso aprobado de seguridad vial reduce su total en 3 puntos, una vez cada tres años.","p":"Correcto. El curso quita 3 puntos."},"ref":{"doc":"WI","page":null}},{"id":"wi-198","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, you get a speeding ticket in another state. How many Wisconsin demerit points are added?","o":["Double the usual points","The same points as in Wisconsin","12 points","None, but the conviction goes on your Wisconsin record"],"h1":"The conviction is recorded, but points work differently.","h2":"No points are assessed for convictions from other states, though the conviction is entered on your Wisconsin driving record.","p":"Right. No points, but it is on your record."},"es":{"q":"En Wisconsin, usted recibe una multa por exceso de velocidad en otro estado. ¿Cuántos puntos de demérito de Wisconsin se le suman?","o":["El doble de lo normal","Los mismos puntos que en Wisconsin","12 puntos","Ninguno, pero la condena se anota en su registro de Wisconsin"],"h1":"La condena se anota, pero los puntos funcionan distinto.","h2":"No se suman puntos por condenas de otros estados, aunque la condena sí se anota en su registro de manejo de Wisconsin.","p":"Correcto. No hay puntos, pero queda en su registro."},"ref":{"doc":"WI","page":null}},{"id":"wi-199","scope":"WI","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wisconsin, how long is an instruction permit valid?","o":["6 months","18 months","2 years","8 years"],"h1":"It is a year and a half.","h2":"A Wisconsin instruction permit expires 18 months after it is issued.","p":"Right. The permit lasts 18 months."},"es":{"q":"En Wisconsin, ¿por cuánto tiempo es válido el permiso de aprendizaje?","o":["6 meses","18 meses","2 años","8 años"],"h1":"Es un año y medio.","h2":"El permiso de aprendizaje de Wisconsin vence 18 meses después de su emisión.","p":"Correcto. El permiso dura 18 meses."},"ref":{"doc":"WI","page":null}},{"id":"wi-200","scope":"WI","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wisconsin, what is the youngest age at which a new driver can get a regular (non-probationary) license?","o":["16","17","18","19"],"h1":"It is one year older than the age when the night and passenger limits end.","h2":"You must be at least 19 to get a regular driver license after holding a probationary license.","p":"Right. A regular license comes at 19 or older."},"es":{"q":"En Wisconsin, ¿a qué edad mínima puede un conductor nuevo obtener una licencia regular (no de prueba)?","o":["16","17","18","19"],"h1":"Es un año más que la edad en que terminan los límites de noche y de pasajeros.","h2":"Debe tener por lo menos 19 años para obtener una licencia regular después de tener la licencia de prueba.","p":"Correcto. La licencia regular es a los 19 años o más."},"ref":{"doc":"WI","page":null}},{"id":"wv-001","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what is the youngest age for a Level 1 instruction permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year before the Level 2 license.","h2":"In West Virginia you can get a Level 1 instruction permit at 15.","p":"Right. Level 1 starts at 15."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para el permiso de instrucción de Nivel 1?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año antes de la licencia de Nivel 2.","h2":"En Virginia Occidental usted puede obtener el permiso de instrucción de Nivel 1 a los 15 años.","p":"Correcto. El Nivel 1 empieza a los 15."},"zh":{"q":"在 West Virginia，最小几岁可以拿到第 1 级学习驾照（Level 1 instruction permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比第 2 级驾照早一年。","h2":"在 West Virginia，你 15 岁就可以拿到第 1 级学习驾照。","p":"对。第 1 级从 15 岁开始。"},"vi":{"q":"Ở West Virginia, tuổi nhỏ nhất để có giấy phép tập lái Cấp 1 (Level 1 instruction permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Sớm hơn một năm so với bằng lái Cấp 2.","h2":"Ở West Virginia, bạn có thể có giấy phép tập lái Cấp 1 khi 15 tuổi.","p":"Đúng. Cấp 1 bắt đầu từ 15 tuổi."},"tl":{"q":"Sa West Virginia, ano ang pinakabatang edad para sa Level 1 na instruction permit (Level 1 instruction permit)?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito bago ang Level 2 na lisensya.","h2":"Sa West Virginia, puwede kang kumuha ng Level 1 na instruction permit sa edad na 15.","p":"Tama. Nagsisimula ang Level 1 sa 15."},"ar":{"q":"في West Virginia، ما أصغر عمر للحصول على تصريح التعلّم من المستوى 1 (Level 1 instruction permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"إنه قبل رخصة المستوى 2 بسنة واحدة.","h2":"في West Virginia يمكنك الحصول على تصريح التعلّم من المستوى 1 في عمر 15 سنة.","p":"صحيح. المستوى 1 يبدأ في عمر 15 سنة."},"ref":{"doc":"WV","page":9}},{"id":"wv-002","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, who must sign the permit application of someone under 18?","o":["A school principal","Any adult friend","A parent or legal guardian","Nobody, the teen signs alone"],"h1":"It is the adult responsible for the teen.","h2":"In West Virginia a parent or legal guardian must sign the application of an applicant under 18 before testing.","p":"Correct. A parent or guardian signs."},"es":{"q":"En Virginia Occidental, ¿quién debe firmar la solicitud de permiso de un menor de 18 años?","o":["El director de la escuela","Cualquier amigo adulto","Un padre o tutor legal","Nadie, el joven firma solo"],"h1":"Es el adulto responsable del joven.","h2":"En Virginia Occidental, un padre o tutor legal debe firmar la solicitud de un menor de 18 años antes del examen.","p":"Correcto. Firma un padre o tutor."},"zh":{"q":"在 West Virginia，未满 18 岁的人申请学习驾照时，谁必须在申请表上签字？","o":["学校校长","任何成年朋友","父母或法定监护人","不需要别人，青少年自己签字"],"h1":"是对这个青少年负责的大人。","h2":"在 West Virginia，未满 18 岁的申请人考试前，必须由父母或法定监护人在申请表上签字。","p":"正确。由父母或监护人签字。"},"vi":{"q":"Ở West Virginia, ai phải ký đơn xin giấy phép tập lái của người dưới 18 tuổi?","o":["Hiệu trưởng trường học","Bất kỳ người bạn lớn tuổi nào","Cha mẹ hoặc người giám hộ hợp pháp","Không ai cả, thiếu niên tự ký"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở West Virginia, cha mẹ hoặc người giám hộ hợp pháp phải ký đơn của người dưới 18 tuổi trước khi thi.","p":"Đúng. Cha mẹ hoặc người giám hộ ký."},"tl":{"q":"Sa West Virginia, sino ang dapat pumirma sa aplikasyon para sa permit ng taong wala pang 18?","o":["Isang punong-guro ng paaralan","Kahit sinong kaibigang adulto","Isang magulang o legal na tagapag-alaga","Wala, ang tinedyer ang pipirma nang mag-isa"],"h1":"Ito ang adultong may pananagutan sa tinedyer.","h2":"Sa West Virginia, dapat pumirma ang isang magulang o legal na tagapag-alaga sa aplikasyon ng aplikanteng wala pang 18 bago ang pagsusulit.","p":"Tama. Magulang o tagapag-alaga ang pipirma."},"ar":{"q":"في West Virginia، من يجب أن يوقّع طلب التصريح لشخص عمره أقل من 18 سنة؟","o":["مدير المدرسة","أي صديق بالغ","أحد الوالدين أو الوصي القانوني","لا أحد، المراهق يوقّع وحده"],"h1":"إنه الشخص البالغ المسؤول عن المراهق.","h2":"في West Virginia يجب أن يوقّع أحد الوالدين أو الوصي القانوني على طلب المتقدّم الذي عمره أقل من 18 سنة قبل الاختبار.","p":"صحيح. أحد الوالدين أو الوصي يوقّع."},"ref":{"doc":"WV","page":9}},{"id":"wv-003","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how old must the licensed driver supervising a Level 1 permit holder be?","o":["16 or older","18 or older","25 or older","21 or older"],"h1":"The supervisor must be old enough to drink legally.","h2":"In West Virginia a Level 1 permit holder must be supervised by a licensed driver who is 21 or older, or by a driving instructor.","p":"Right. The supervisor must be 21 or older."},"es":{"q":"En Virginia Occidental, ¿qué edad debe tener el conductor con licencia que supervisa a quien tiene permiso de Nivel 1?","o":["16 años o más","18 años o más","25 años o más","21 años o más"],"h1":"El supervisor debe tener edad para tomar alcohol legalmente.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe ir supervisado por un conductor con licencia de 21 años o más, o por un instructor de manejo.","p":"Correcto. El supervisor debe tener 21 años o más."},"zh":{"q":"在 West Virginia，陪同第 1 级学习驾照持有人开车的有照司机必须几岁以上？","o":["16 岁或以上","18 岁或以上","25 岁或以上","21 岁或以上"],"h1":"陪同的人必须到了可以合法喝酒的年龄。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，必须有 21 岁或以上的有照司机或驾驶教练陪同。","p":"对。陪同的人必须 21 岁或以上。"},"vi":{"q":"Ở West Virginia, người có bằng lái đi kèm người có giấy phép tập lái Cấp 1 phải bao nhiêu tuổi?","o":["16 tuổi trở lên","18 tuổi trở lên","25 tuổi trở lên","21 tuổi trở lên"],"h1":"Người đi kèm phải đủ tuổi uống rượu hợp pháp.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 phải có một người lái xe có bằng từ 21 tuổi trở lên, hoặc một giáo viên dạy lái xe, đi kèm.","p":"Đúng. Người đi kèm phải từ 21 tuổi trở lên."},"tl":{"q":"Sa West Virginia, ilang taon dapat ang may lisensyang drayber na nagbabantay sa may hawak ng Level 1 na permit?","o":["16 o higit pa","18 o higit pa","25 o higit pa","21 o higit pa"],"h1":"Dapat nasa edad na ang nagbabantay para legal na uminom ng alak.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay dapat bantayan ng may lisensyang drayber na 21 o higit pa, o ng isang driving instructor.","p":"Tama. Dapat 21 o higit pa ang nagbabantay."},"ar":{"q":"في West Virginia، كم يجب أن يكون عمر السائق المرخّص الذي يرافق حامل تصريح المستوى 1؟","o":["16 سنة أو أكثر","18 سنة أو أكثر","25 سنة أو أكثر","21 سنة أو أكثر"],"h1":"يجب أن يكون المرافق في عمر يسمح له قانونيًا بشرب الكحول.","h2":"في West Virginia يجب أن يرافق حاملَ تصريح المستوى 1 سائقٌ مرخّص عمره 21 سنة أو أكثر، أو مدرّب قيادة.","p":"صحيح. يجب أن يكون عمر المرافق 21 سنة أو أكثر."},"ref":{"doc":"WV","page":9}},{"id":"wv-004","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, who else may sit in the front seat while a Level 1 permit holder drives?","o":["Only the supervising driver","Any friend","A younger brother or sister","Nobody may sit in front"],"h1":"The front seat is for the person in charge of the lesson.","h2":"In West Virginia the supervising driver must be the only other person in the front seat while a Level 1 permit holder drives.","p":"Correct. Only the supervisor sits in front."},"es":{"q":"En Virginia Occidental, ¿quién más puede ir en el asiento delantero mientras maneja alguien con permiso de Nivel 1?","o":["Solo el conductor que supervisa","Cualquier amigo","Un hermano menor","Nadie puede ir adelante"],"h1":"El asiento delantero es para quien está a cargo de la práctica.","h2":"En Virginia Occidental, el conductor que supervisa debe ser la única otra persona en el asiento delantero mientras maneja alguien con permiso de Nivel 1.","p":"Correcto. Solo el supervisor va adelante."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人开车时，前排还可以坐谁？","o":["只有陪同的司机","任何朋友","弟弟或妹妹","前排不能坐任何人"],"h1":"前排座位是给负责这次练习的人坐的。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，前排除了司机只能坐陪同的司机。","p":"正确。前排只能坐陪同的人。"},"vi":{"q":"Ở West Virginia, khi người có giấy phép tập lái Cấp 1 lái xe, ai khác được ngồi ở ghế trước?","o":["Chỉ người lái xe đi kèm","Bất kỳ người bạn nào","Em trai hoặc em gái","Không ai được ngồi ở ghế trước"],"h1":"Ghế trước dành cho người phụ trách buổi tập.","h2":"Ở West Virginia, khi người có giấy phép tập lái Cấp 1 lái xe, người lái xe đi kèm phải là người duy nhất khác ngồi ở ghế trước.","p":"Đúng. Chỉ người đi kèm ngồi ở ghế trước."},"tl":{"q":"Sa West Virginia, sino pa ang puwedeng umupo sa harap habang nagmamaneho ang may hawak ng Level 1 na permit?","o":["Ang nagbabantay na drayber lamang","Kahit sinong kaibigan","Isang nakababatang kapatid","Walang puwedeng umupo sa harap"],"h1":"Ang upuan sa harap ay para sa taong namamahala sa aralin.","h2":"Sa West Virginia, ang nagbabantay na drayber lamang ang puwedeng ibang tao sa upuan sa harap habang nagmamaneho ang may hawak ng Level 1 na permit.","p":"Tama. Ang nagbabantay lamang ang uupo sa harap."},"ar":{"q":"في West Virginia، من غير السائق يمكنه الجلوس في المقعد الأمامي عندما يقود حامل تصريح المستوى 1؟","o":["السائق المرافق فقط","أي صديق","أخ أو أخت أصغر","لا يجوز لأحد الجلوس في الأمام"],"h1":"المقعد الأمامي للشخص المسؤول عن الدرس.","h2":"في West Virginia يجب أن يكون السائق المرافق هو الشخص الوحيد الآخر في المقعد الأمامي عندما يقود حامل تصريح المستوى 1.","p":"صحيح. المرافق فقط يجلس في الأمام."},"ref":{"doc":"WV","page":null}},{"id":"wv-005","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during which hours may a Level 1 permit holder drive?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and 10 p.m.","Between 5 a.m. and midnight","At any hour with a supervisor"],"h1":"The window ends in the late evening, before midnight.","h2":"In West Virginia a Level 1 permit holder may drive only between 5 a.m. and 10 p.m.","p":"Right. Level 1 driving is from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿en qué horario puede manejar quien tiene permiso de Nivel 1?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y las 10 p.m.","Entre las 5 a.m. y la medianoche","A cualquier hora con supervisor"],"h1":"El horario termina en la noche, antes de la medianoche.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 solo puede manejar entre las 5 a.m. y las 10 p.m.","p":"Correcto. El Nivel 1 maneja de 5 a.m. a 10 p.m."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人在什么时间可以开车？","o":["早上 6 点到晚上 9 点","早上 5 点到晚上 10 点","早上 5 点到半夜 12 点","有人陪同时任何时间都可以"],"h1":"结束时间在晚上，比半夜早。","h2":"在 West Virginia，第 1 级学习驾照持有人只能在早上 5 点到晚上 10 点之间开车。","p":"对。第 1 级可以在早上 5 点到晚上 10 点开车。"},"vi":{"q":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được lái xe trong những giờ nào?","o":["Từ 6 giờ sáng đến 9 giờ tối","Từ 5 giờ sáng đến 10 giờ tối","Từ 5 giờ sáng đến nửa đêm","Bất cứ giờ nào nếu có người đi kèm"],"h1":"Thời gian kết thúc vào buổi tối muộn, trước nửa đêm.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 chỉ được lái xe từ 5 giờ sáng đến 10 giờ tối.","p":"Đúng. Cấp 1 được lái từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa West Virginia, anong oras puwedeng magmaneho ang may hawak ng Level 1 na permit?","o":["Mula 6 a.m. hanggang 9 p.m.","Mula 5 a.m. hanggang 10 p.m.","Mula 5 a.m. hanggang hatinggabi","Kahit anong oras kung may nagbabantay"],"h1":"Natatapos ito sa gabi, bago maghatinggabi.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay puwedeng magmaneho lamang mula 5 a.m. hanggang 10 p.m.","p":"Tama. Ang pagmamaneho sa Level 1 ay mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في West Virginia، في أي ساعات يمكن لحامل تصريح المستوى 1 أن يقود؟","o":["من 6 صباحًا إلى 9 مساءً","من 5 صباحًا إلى 10 مساءً","من 5 صباحًا إلى منتصف الليل","في أي ساعة مع مرافق"],"h1":"الوقت ينتهي في آخر المساء، قبل منتصف الليل.","h2":"في West Virginia يمكن لحامل تصريح المستوى 1 أن يقود فقط من 5 صباحًا إلى 10 مساءً.","p":"صحيح. القيادة في المستوى 1 من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"WV","page":10}},{"id":"wv-006","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many passengers besides the supervisor may ride with a Level 1 permit holder, not counting family?","o":["None","No more than one","No more than two","No more than four"],"h1":"It is a small number, more than one.","h2":"In West Virginia a Level 1 permit holder may carry no more than two additional passengers unless they are family members.","p":"Correct. Up to two extra passengers."},"es":{"q":"En Virginia Occidental, ¿cuántos pasajeros, además del supervisor, pueden ir con alguien con permiso de Nivel 1, sin contar a la familia?","o":["Ninguno","No más de uno","No más de dos","No más de cuatro"],"h1":"Es un número pequeño, mayor que uno.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 no puede llevar más de dos pasajeros adicionales, salvo que sean familiares.","p":"Correcto. Hasta dos pasajeros más."},"zh":{"q":"在 West Virginia，除了陪同的人，第 1 级学习驾照持有人最多可以载几个乘客（不算家人）？","o":["一个也不行","最多一个","最多两个","最多四个"],"h1":"人数很少，但多于一个。","h2":"在 West Virginia，第 1 级学习驾照持有人最多只能多载两个乘客，家人除外。","p":"正确。最多再载两个乘客。"},"vi":{"q":"Ở West Virginia, ngoài người đi kèm, người có giấy phép tập lái Cấp 1 được chở bao nhiêu hành khách, không tính người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá bốn người"],"h1":"Đó là một số nhỏ, hơn một.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được chở thêm không quá hai hành khách, trừ khi họ là người trong gia đình.","p":"Đúng. Tối đa thêm hai hành khách."},"tl":{"q":"Sa West Virginia, bukod sa nagbabantay, ilang pasahero ang puwedeng isakay ng may hawak ng Level 1 na permit, hindi kasama ang pamilya?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa apat"],"h1":"Maliit na bilang ito, higit sa isa.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay puwedeng magsakay ng hindi hihigit sa dalawang dagdag na pasahero, maliban kung kapamilya sila.","p":"Tama. Hanggang dalawang dagdag na pasahero."},"ar":{"q":"في West Virginia، كم راكبًا غير المرافق يمكن أن يركب مع حامل تصريح المستوى 1، دون حساب أفراد العائلة؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من أربعة"],"h1":"إنه عدد صغير، أكثر من واحد.","h2":"في West Virginia يمكن لحامل تصريح المستوى 1 أن يحمل راكبَين إضافيَّين على الأكثر، إلا إذا كانوا من أفراد العائلة.","p":"صحيح. راكبان إضافيان على الأكثر."},"ref":{"doc":"WV","page":10}},{"id":"wv-007","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, what blood alcohol level is allowed for a Level 1 permit holder?","o":["Below 0.02","Below 0.05","Below 0.08","None at all"],"h1":"This is called zero tolerance.","h2":"In West Virginia a Level 1 permit holder must drive with no measurable alcohol in the blood at all.","p":"Right. Zero alcohol for permit holders."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre se permite a quien tiene permiso de Nivel 1?","o":["Menos de 0.02","Menos de 0.05","Menos de 0.08","Nada en absoluto"],"h1":"Esto se llama tolerancia cero.","h2":"En Virginia Occidental, quien tiene permiso de Nivel 1 debe manejar sin ninguna cantidad medible de alcohol en la sangre.","p":"Correcto. Cero alcohol con permiso."},"zh":{"q":"在 West Virginia，第 1 级学习驾照持有人血液中可以有多少酒精？","o":["低于 0.02","低于 0.05","低于 0.08","一点都不可以"],"h1":"这叫做零容忍。","h2":"在 West Virginia，第 1 级学习驾照持有人开车时，血液中不能有任何可测出的酒精。","p":"对。持学习驾照的人不能有任何酒精。"},"vi":{"q":"Ở West Virginia, người có giấy phép tập lái Cấp 1 được phép có nồng độ cồn trong máu là bao nhiêu?","o":["Dưới 0.02","Dưới 0.05","Dưới 0.08","Hoàn toàn không có"],"h1":"Điều này gọi là không khoan nhượng.","h2":"Ở West Virginia, người có giấy phép tập lái Cấp 1 phải lái xe mà hoàn toàn không có chút cồn nào đo được trong máu.","p":"Đúng. Người có giấy phép tập lái không được có cồn."},"tl":{"q":"Sa West Virginia, gaano karaming alak sa dugo ang pinapayagan para sa may hawak ng Level 1 na permit?","o":["Mas mababa sa 0.02","Mas mababa sa 0.05","Mas mababa sa 0.08","Wala talaga"],"h1":"Ito ang tinatawag na zero tolerance.","h2":"Sa West Virginia, ang may hawak ng Level 1 na permit ay dapat magmaneho nang walang anumang nasusukat na alak sa dugo.","p":"Tama. Walang alak para sa may hawak ng permit."},"ar":{"q":"في West Virginia، ما نسبة الكحول في الدم المسموح بها لحامل تصريح المستوى 1؟","o":["أقل من 0.02","أقل من 0.05","أقل من 0.08","لا شيء على الإطلاق"],"h1":"هذا يُسمّى عدم التسامح مطلقًا.","h2":"في West Virginia يجب أن يقود حامل تصريح المستوى 1 دون أي كحول يمكن قياسه في الدم على الإطلاق.","p":"صحيح. لا كحول أبدًا لحاملي التصريح."},"ref":{"doc":"WV","page":10}},{"id":"wv-008","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, how many hours of supervised driving are needed for a Level 2 license if you did not take driver education?","o":["50 hours","20 hours","30 hours","100 hours"],"h1":"It is a round number between 30 and 100.","h2":"In West Virginia you need 50 hours of supervised behind-the-wheel driving for a Level 2 license unless you completed driver education.","p":"Correct. Fifty hours are needed."},"es":{"q":"En Virginia Occidental, ¿cuántas horas de manejo supervisado se necesitan para la licencia de Nivel 2 si no tomó educación vial?","o":["50 horas","20 horas","30 horas","100 horas"],"h1":"Es un número redondo entre 30 y 100.","h2":"En Virginia Occidental usted necesita 50 horas de manejo supervisado para la licencia de Nivel 2, salvo que haya completado educación vial.","p":"Correcto. Se necesitan 50 horas."},"zh":{"q":"在 West Virginia，如果你没有上驾驶教育课，拿第 2 级驾照需要多少小时有人陪同的驾驶练习？","o":["50 小时","20 小时","30 小时","100 小时"],"h1":"它是 30 到 100 之间的一个整数。","h2":"在 West Virginia，如果你没有完成驾驶教育课，拿第 2 级驾照需要 50 小时有人陪同的实际驾驶练习。","p":"正确。需要 50 小时。"},"vi":{"q":"Ở West Virginia, nếu bạn không học lớp giáo dục lái xe, cần bao nhiêu giờ lái xe có người đi kèm để có bằng lái Cấp 2?","o":["50 giờ","20 giờ","30 giờ","100 giờ"],"h1":"Đó là một số tròn giữa 30 và 100.","h2":"Ở West Virginia, bạn cần 50 giờ tự cầm lái có người đi kèm để có bằng lái Cấp 2, trừ khi bạn đã học xong lớp giáo dục lái xe.","p":"Đúng. Cần 50 giờ."},"tl":{"q":"Sa West Virginia, ilang oras ng binabantayang pagmamaneho ang kailangan para sa Level 2 na lisensya kung hindi ka kumuha ng driver education?","o":["50 oras","20 oras","30 oras","100 oras"],"h1":"Isa itong bilog na numero sa pagitan ng 30 at 100.","h2":"Sa West Virginia, kailangan mo ng 50 oras ng binabantayang pagmamaneho para sa Level 2 na lisensya, maliban kung natapos mo ang driver education.","p":"Tama. Limampung oras ang kailangan."},"ar":{"q":"في West Virginia، كم ساعة من القيادة مع مرافق تحتاج للحصول على رخصة المستوى 2 إذا لم تأخذ دورة تعليم القيادة؟","o":["50 ساعة","20 ساعة","30 ساعة","100 ساعة"],"h1":"إنه عدد مُقرَّب بين 30 و100.","h2":"في West Virginia تحتاج إلى 50 ساعة من القيادة الفعلية مع مرافق للحصول على رخصة المستوى 2، إلا إذا أكملت دورة تعليم القيادة.","p":"صحيح. تحتاج إلى 50 ساعة."},"ref":{"doc":"WV","page":10}},{"id":"wv-009","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many of the 50 supervised hours must be at night?","o":["At least 2 hours","At least 10 hours","At least 5 hours","At least 25 hours"],"h1":"It is one fifth of the total.","h2":"In West Virginia at least 10 of the 50 supervised driving hours must be at night.","p":"Right. Ten hours are at night."},"es":{"q":"En Virginia Occidental, ¿cuántas de las 50 horas supervisadas deben ser de noche?","o":["Por lo menos 2 horas","Por lo menos 10 horas","Por lo menos 5 horas","Por lo menos 25 horas"],"h1":"Es la quinta parte del total.","h2":"En Virginia Occidental, por lo menos 10 de las 50 horas de manejo supervisado deben ser de noche.","p":"Correcto. Diez horas son de noche."},"zh":{"q":"在 West Virginia，这 50 小时有人陪同的练习中，有多少小时必须在晚上？","o":["至少 2 小时","至少 10 小时","至少 5 小时","至少 25 小时"],"h1":"它是总数的五分之一。","h2":"在 West Virginia，50 小时有人陪同的驾驶练习中，至少 10 小时必须在晚上。","p":"对。10 小时在晚上。"},"vi":{"q":"Ở West Virginia, trong 50 giờ lái xe có người đi kèm, bao nhiêu giờ phải là vào ban đêm?","o":["Ít nhất 2 giờ","Ít nhất 10 giờ","Ít nhất 5 giờ","Ít nhất 25 giờ"],"h1":"Đó là một phần năm của tổng số.","h2":"Ở West Virginia, ít nhất 10 trong 50 giờ lái xe có người đi kèm phải là vào ban đêm.","p":"Đúng. 10 giờ là vào ban đêm."},"tl":{"q":"Sa West Virginia, ilan sa 50 oras ng binabantayang pagmamaneho ang dapat gawin sa gabi?","o":["Hindi bababa sa 2 oras","Hindi bababa sa 10 oras","Hindi bababa sa 5 oras","Hindi bababa sa 25 oras"],"h1":"Ito ay isang-kalima ng kabuuan.","h2":"Sa West Virginia, hindi bababa sa 10 sa 50 oras ng binabantayang pagmamaneho ang dapat gawin sa gabi.","p":"Tama. Sampung oras ang sa gabi."},"ar":{"q":"في West Virginia، كم ساعة من الـ 50 ساعة مع مرافق يجب أن تكون في الليل؟","o":["2 ساعة على الأقل","10 ساعات على الأقل","5 ساعات على الأقل","25 ساعة على الأقل"],"h1":"إنه خُمس المجموع.","h2":"في West Virginia يجب أن تكون 10 ساعات على الأقل من الـ 50 ساعة من القيادة مع مرافق في الليل.","p":"صحيح. 10 ساعات في الليل."},"ref":{"doc":"WV","page":10}},{"id":"wv-010","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how long must you hold a Level 1 permit without a conviction before applying for Level 2?","o":["30 days","90 days","180 days","One year"],"h1":"It is about six months.","h2":"In West Virginia you must hold your Level 1 permit conviction-free for the 180 days before you apply for a Level 2 license.","p":"Correct. It is 180 days without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener el permiso de Nivel 1 sin condenas antes de solicitar el Nivel 2?","o":["30 días","90 días","180 días","Un año"],"h1":"Son unos seis meses.","h2":"En Virginia Occidental usted debe tener el permiso de Nivel 1 sin condenas durante los 180 días antes de solicitar la licencia de Nivel 2.","p":"Correcto. Son 180 días sin condenas."},"zh":{"q":"在 West Virginia，你必须持有第 1 级学习驾照多久而没有违法定罪，才可以申请第 2 级？","o":["30 天","90 天","180 天","一年"],"h1":"大约是六个月。","h2":"在 West Virginia，申请第 2 级驾照之前，你必须持有第 1 级学习驾照 180 天，而且没有违法定罪。","p":"正确。是 180 天没有违法定罪。"},"vi":{"q":"Ở West Virginia, bạn phải giữ giấy phép tập lái Cấp 1 bao lâu mà không bị kết tội vi phạm trước khi xin Cấp 2?","o":["30 ngày","90 ngày","180 ngày","Một năm"],"h1":"Khoảng sáu tháng.","h2":"Ở West Virginia, bạn phải giữ giấy phép tập lái Cấp 1 trong 180 ngày mà không bị kết tội vi phạm trước khi xin bằng lái Cấp 2.","p":"Đúng. Là 180 ngày không bị kết tội vi phạm."},"tl":{"q":"Sa West Virginia, gaano katagal mo dapat hawak ang Level 1 na permit nang walang conviction bago mag-apply para sa Level 2?","o":["30 araw","90 araw","180 araw","Isang taon"],"h1":"Mga anim na buwan ito.","h2":"Sa West Virginia, dapat mong hawak ang Level 1 na permit nang walang conviction sa loob ng 180 araw bago ka mag-apply para sa Level 2 na lisensya.","p":"Tama. 180 araw ito nang walang conviction."},"ar":{"q":"في West Virginia، كم مدة يجب أن تحمل تصريح المستوى 1 دون إدانة قبل التقدّم للمستوى 2؟","o":["30 يومًا","90 يومًا","180 يومًا","سنة واحدة"],"h1":"إنها حوالي ستة أشهر.","h2":"في West Virginia يجب أن تحمل تصريح المستوى 1 دون أي إدانة لمدة 180 يومًا قبل أن تتقدّم لرخصة المستوى 2.","p":"صحيح. 180 يومًا دون إدانة."},"ref":{"doc":"WV","page":10}},{"id":"wv-011","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, when may a Level 2 driver drive alone without a supervisor?","o":["Between 6 a.m. and 9 p.m.","Between 5 a.m. and midnight","Only on school days","Between 5 a.m. and 10 p.m."],"h1":"It is the same window as for a Level 1 permit.","h2":"In West Virginia a Level 2 driver may drive unsupervised between 5 a.m. and 10 p.m.; later hours need a licensed driver 21 or older, except for work, school, religious events or emergencies.","p":"Right. Alone from 5 a.m. to 10 p.m."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor de Nivel 2 manejar solo, sin supervisor?","o":["Entre las 6 a.m. y las 9 p.m.","Entre las 5 a.m. y la medianoche","Solo los días de escuela","Entre las 5 a.m. y las 10 p.m."],"h1":"Es el mismo horario que el del permiso de Nivel 1.","h2":"En Virginia Occidental, un conductor de Nivel 2 puede manejar solo entre las 5 a.m. y las 10 p.m.; más tarde necesita un conductor con licencia de 21 años o más, salvo por trabajo, escuela, eventos religiosos o emergencias.","p":"Correcto. Solo, de 5 a.m. a 10 p.m."},"zh":{"q":"在 West Virginia，第 2 级驾照的司机什么时候可以没有人陪同、自己开车？","o":["早上 6 点到晚上 9 点","早上 5 点到半夜 12 点","只有上学的日子","早上 5 点到晚上 10 点"],"h1":"和第 1 级学习驾照的时间一样。","h2":"在 West Virginia，第 2 级驾照的司机可以在早上 5 点到晚上 10 点之间自己开车；更晚的时间需要 21 岁或以上的有照司机陪同，但上班、上学、宗教活动或紧急情况除外。","p":"对。早上 5 点到晚上 10 点可以自己开。"},"vi":{"q":"Ở West Virginia, khi nào người có bằng lái Cấp 2 được lái xe một mình mà không có người đi kèm?","o":["Từ 6 giờ sáng đến 9 giờ tối","Từ 5 giờ sáng đến nửa đêm","Chỉ vào ngày đi học","Từ 5 giờ sáng đến 10 giờ tối"],"h1":"Giống với giờ của giấy phép tập lái Cấp 1.","h2":"Ở West Virginia, người có bằng lái Cấp 2 được lái xe một mình từ 5 giờ sáng đến 10 giờ tối; giờ muộn hơn cần một người có bằng lái từ 21 tuổi trở lên đi kèm, trừ khi đi làm, đi học, đi sự kiện tôn giáo hoặc trường hợp khẩn cấp.","p":"Đúng. Lái một mình từ 5 giờ sáng đến 10 giờ tối."},"tl":{"q":"Sa West Virginia, kailan puwedeng magmaneho nang mag-isa, nang walang nagbabantay, ang drayber na may Level 2?","o":["Mula 6 a.m. hanggang 9 p.m.","Mula 5 a.m. hanggang hatinggabi","Sa mga araw ng pasok lamang","Mula 5 a.m. hanggang 10 p.m."],"h1":"Pareho ito ng oras para sa Level 1 na permit.","h2":"Sa West Virginia, ang drayber na may Level 2 ay puwedeng magmaneho nang walang nagbabantay mula 5 a.m. hanggang 10 p.m.; sa mas huling oras, kailangan ng may lisensyang drayber na 21 o higit pa, maliban kung para sa trabaho, paaralan, gawaing panrelihiyon o emergency.","p":"Tama. Mag-isa mula 5 a.m. hanggang 10 p.m."},"ar":{"q":"في West Virginia، متى يمكن لسائق المستوى 2 أن يقود وحده دون مرافق؟","o":["من 6 صباحًا إلى 9 مساءً","من 5 صباحًا إلى منتصف الليل","في أيام المدرسة فقط","من 5 صباحًا إلى 10 مساءً"],"h1":"إنه نفس وقت تصريح المستوى 1.","h2":"في West Virginia يمكن لسائق المستوى 2 أن يقود دون مرافق من 5 صباحًا إلى 10 مساءً؛ وبعد ذلك يحتاج إلى سائق مرخّص عمره 21 سنة أو أكثر، إلا للعمل أو المدرسة أو المناسبات الدينية أو حالات الطوارئ.","p":"صحيح. وحدك من 5 صباحًا إلى 10 مساءً."},"ref":{"doc":"WV","page":10}},{"id":"wv-012","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, during the first six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","One","Two","Three"],"h1":"The first months are the strictest.","h2":"In West Virginia, for the first six months of a Level 2 license, you may not carry any passengers under 20 unless they are family members.","p":"Correct. No young non-family passengers at first."},"es":{"q":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familia puede llevar?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Los primeros meses son los más estrictos.","h2":"En Virginia Occidental, durante los primeros seis meses de la licencia de Nivel 2, no puede llevar pasajeros menores de 20 años, salvo que sean familiares.","p":"Correcto. Al principio, ningún pasajero joven que no sea familia."},"zh":{"q":"在 West Virginia，拿到第 2 级驾照的头六个月，你可以载几个未满 20 岁、又不是家人的乘客？","o":["一个也不行","一个","两个","三个"],"h1":"头几个月是最严格的。","h2":"在 West Virginia，拿到第 2 级驾照的头六个月，你不能载任何未满 20 岁的乘客，除非他们是家人。","p":"正确。开始时不能载不是家人的年轻乘客。"},"vi":{"q":"Ở West Virginia, trong sáu tháng đầu có bằng lái Cấp 2, bạn được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Một người","Hai người","Ba người"],"h1":"Những tháng đầu là nghiêm nhất.","h2":"Ở West Virginia, trong sáu tháng đầu có bằng lái Cấp 2, bạn không được chở hành khách nào dưới 20 tuổi, trừ khi họ là người trong gia đình.","p":"Đúng. Lúc đầu không được chở người trẻ không phải người nhà."},"tl":{"q":"Sa West Virginia, sa unang anim na buwan ng Level 2 na lisensya, ilang pasaherong wala pang 20 na hindi kapamilya ang puwede mong isakay?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ang mga unang buwan ang pinakamahigpit.","h2":"Sa West Virginia, sa unang anim na buwan ng Level 2 na lisensya, hindi ka puwedeng magsakay ng kahit sinong pasaherong wala pang 20, maliban kung kapamilya sila.","p":"Tama. Walang batang pasaherong hindi kapamilya sa simula."},"ar":{"q":"في West Virginia، خلال أول ستة أشهر من رخصة المستوى 2، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يمكنك أن تحمل؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"الأشهر الأولى هي الأكثر صرامة.","h2":"في West Virginia، خلال أول ستة أشهر من رخصة المستوى 2، لا يجوز لك أن تحمل أي راكب عمره أقل من 20 سنة إلا إذا كان من أفراد العائلة.","p":"صحيح. لا ركّاب صغار من خارج العائلة في البداية."},"ref":{"doc":"WV","page":11}},{"id":"wv-013","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, during the second six months of a Level 2 license, how many passengers under 20 who are not family may you carry?","o":["None","No more than one","No more than two","No more than three"],"h1":"The limit opens up by just one.","h2":"In West Virginia, for the second six months of a Level 2 license, you may not carry more than one passenger under 20 who is not a family member.","p":"Right. Only one passenger under 20."},"es":{"q":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, ¿cuántos pasajeros menores de 20 años que no son familiares puede llevar?","o":["Ninguno","No más de uno","No más de dos","No más de tres"],"h1":"El límite se abre solo en uno.","h2":"En Virginia Occidental, durante los segundos seis meses de la licencia de Nivel 2, no puede llevar más de un pasajero menor de 20 años que no sea familiar.","p":"Correcto. Solo un pasajero menor de 20."},"zh":{"q":"在 West Virginia，拿到第 2 级驾照的第二个六个月，你可以载几个未满 20 岁、又不是家人的乘客？","o":["一个也不行","最多一个","最多两个","最多三个"],"h1":"限制只放宽了一个人。","h2":"在 West Virginia，拿到第 2 级驾照的第二个六个月，你最多只能载一个未满 20 岁、又不是家人的乘客。","p":"对。只能载一个未满 20 岁的乘客。"},"vi":{"q":"Ở West Virginia, trong sáu tháng thứ hai có bằng lái Cấp 2, bạn được chở bao nhiêu hành khách dưới 20 tuổi không phải người trong gia đình?","o":["Không ai","Không quá một người","Không quá hai người","Không quá ba người"],"h1":"Giới hạn chỉ tăng thêm một người.","h2":"Ở West Virginia, trong sáu tháng thứ hai có bằng lái Cấp 2, bạn không được chở quá một hành khách dưới 20 tuổi không phải người trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 20 tuổi."},"tl":{"q":"Sa West Virginia, sa ikalawang anim na buwan ng Level 2 na lisensya, ilang pasaherong wala pang 20 na hindi kapamilya ang puwede mong isakay?","o":["Wala","Hindi hihigit sa isa","Hindi hihigit sa dalawa","Hindi hihigit sa tatlo"],"h1":"Isa lang ang idinadagdag sa limitasyon.","h2":"Sa West Virginia, sa ikalawang anim na buwan ng Level 2 na lisensya, hindi ka puwedeng magsakay ng higit sa isang pasaherong wala pang 20 na hindi kapamilya.","p":"Tama. Isang pasahero lang na wala pang 20."},"ar":{"q":"في West Virginia، خلال الستة أشهر الثانية من رخصة المستوى 2، كم راكبًا عمره أقل من 20 سنة وليس من العائلة يمكنك أن تحمل؟","o":["لا أحد","ليس أكثر من واحد","ليس أكثر من اثنين","ليس أكثر من ثلاثة"],"h1":"الحدّ يزيد بواحد فقط.","h2":"في West Virginia، خلال الستة أشهر الثانية من رخصة المستوى 2، لا يجوز لك أن تحمل أكثر من راكب واحد عمره أقل من 20 سنة وليس من أفراد العائلة.","p":"صحيح. راكب واحد فقط عمره أقل من 20 سنة."},"ref":{"doc":"WV","page":11}},{"id":"wv-014","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what is the youngest age for a Level 3 full license?","o":["16 years old","18 years old","17 years old","21 years old"],"h1":"It is one year after the youngest Level 2 age.","h2":"In West Virginia you can get a Level 3 full license at 17 after holding a Level 2 license for 12 months without a conviction.","p":"Correct. Level 3 starts at 17."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para la licencia completa de Nivel 3?","o":["16 años","18 años","17 años","21 años"],"h1":"Es un año después de la edad mínima del Nivel 2.","h2":"En Virginia Occidental usted puede obtener la licencia completa de Nivel 3 a los 17 años, después de tener la licencia de Nivel 2 por 12 meses sin condenas.","p":"Correcto. El Nivel 3 empieza a los 17."},"zh":{"q":"在 West Virginia，最小几岁可以拿到第 3 级正式驾照（Level 3 full license）？","o":["16 岁","18 岁","17 岁","21 岁"],"h1":"它比拿第 2 级驾照的最小年龄晚一年。","h2":"在 West Virginia，你持有第 2 级驾照 12 个月而没有违法定罪后，17 岁就可以拿到第 3 级正式驾照。","p":"正确。第 3 级从 17 岁开始。"},"vi":{"q":"Ở West Virginia, tuổi nhỏ nhất để có bằng lái đầy đủ Cấp 3 (Level 3 full license) là bao nhiêu?","o":["16 tuổi","18 tuổi","17 tuổi","21 tuổi"],"h1":"Muộn hơn một năm so với tuổi nhỏ nhất của Cấp 2.","h2":"Ở West Virginia, bạn có thể có bằng lái đầy đủ Cấp 3 khi 17 tuổi, sau khi giữ bằng lái Cấp 2 trong 12 tháng mà không bị kết tội vi phạm.","p":"Đúng. Cấp 3 bắt đầu từ 17 tuổi."},"tl":{"q":"Sa West Virginia, ano ang pinakabatang edad para sa Level 3 na buong lisensya (Level 3 full license)?","o":["16 taong gulang","18 taong gulang","17 taong gulang","21 taong gulang"],"h1":"Isang taon ito pagkatapos ng pinakabatang edad para sa Level 2.","h2":"Sa West Virginia, puwede kang kumuha ng Level 3 na buong lisensya sa edad na 17, pagkatapos mong hawakan ang Level 2 na lisensya nang 12 buwan nang walang conviction.","p":"Tama. Nagsisimula ang Level 3 sa 17."},"ar":{"q":"في West Virginia، ما أصغر عمر للحصول على الرخصة الكاملة من المستوى 3 (Level 3 full license)؟","o":["16 سنة","18 سنة","17 سنة","21 سنة"],"h1":"إنه بعد أصغر عمر للمستوى 2 بسنة واحدة.","h2":"في West Virginia يمكنك الحصول على الرخصة الكاملة من المستوى 3 في عمر 17 سنة بعد أن تحمل رخصة المستوى 2 لمدة 12 شهرًا دون إدانة.","p":"صحيح. المستوى 3 يبدأ في عمر 17 سنة."},"ref":{"doc":"WV","page":12}},{"id":"wv-015","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how long must you hold a Level 2 license without a conviction before Level 3?","o":["3 months","6 months","24 months","12 months"],"h1":"It is one full year.","h2":"In West Virginia you must hold a Level 2 license conviction-free for 12 months before applying for Level 3.","p":"Right. One year without a conviction."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener la licencia de Nivel 2 sin condenas antes del Nivel 3?","o":["3 meses","6 meses","24 meses","12 meses"],"h1":"Es un año completo.","h2":"En Virginia Occidental usted debe tener la licencia de Nivel 2 sin condenas durante 12 meses antes de solicitar el Nivel 3.","p":"Correcto. Un año sin condenas."},"zh":{"q":"在 West Virginia，你必须持有第 2 级驾照多久而没有违法定罪，才可以拿第 3 级？","o":["3 个月","6 个月","24 个月","12 个月"],"h1":"是整整一年。","h2":"在 West Virginia，申请第 3 级之前，你必须持有第 2 级驾照 12 个月，而且没有违法定罪。","p":"对。一年没有违法定罪。"},"vi":{"q":"Ở West Virginia, bạn phải giữ bằng lái Cấp 2 bao lâu mà không bị kết tội vi phạm trước khi lên Cấp 3?","o":["3 tháng","6 tháng","24 tháng","12 tháng"],"h1":"Đúng một năm.","h2":"Ở West Virginia, bạn phải giữ bằng lái Cấp 2 trong 12 tháng mà không bị kết tội vi phạm trước khi xin Cấp 3.","p":"Đúng. Một năm không bị kết tội vi phạm."},"tl":{"q":"Sa West Virginia, gaano katagal mo dapat hawak ang Level 2 na lisensya nang walang conviction bago ang Level 3?","o":["3 buwan","6 na buwan","24 na buwan","12 buwan"],"h1":"Isang buong taon ito.","h2":"Sa West Virginia, dapat mong hawak ang Level 2 na lisensya nang walang conviction sa loob ng 12 buwan bago mag-apply para sa Level 3.","p":"Tama. Isang taon nang walang conviction."},"ar":{"q":"في West Virginia، كم مدة يجب أن تحمل رخصة المستوى 2 دون إدانة قبل المستوى 3؟","o":["3 أشهر","6 أشهر","24 شهرًا","12 شهرًا"],"h1":"إنها سنة كاملة.","h2":"في West Virginia يجب أن تحمل رخصة المستوى 2 دون أي إدانة لمدة 12 شهرًا قبل التقدّم للمستوى 3.","p":"صحيح. سنة واحدة دون إدانة."},"ref":{"doc":"WV","page":12}},{"id":"wv-016","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, when may a driver under 18 with a permit or Level 2 license use a phone while driving?","o":["Only to call 911","Any time, if it is hands-free","Only at red lights","Only to text a parent"],"h1":"There is only one exception, and it is for emergencies.","h2":"In West Virginia a driver under 18 with a permit or Level 2 license may not use a phone or other wireless device while driving, except to call 911.","p":"Correct. Only a 911 call is allowed."},"es":{"q":"En Virginia Occidental, ¿cuándo puede un conductor menor de 18 años con permiso o licencia de Nivel 2 usar el teléfono mientras maneja?","o":["Solo para llamar al 911","En cualquier momento, si es manos libres","Solo en los semáforos en rojo","Solo para escribirle a un padre"],"h1":"Hay una sola excepción, y es para emergencias.","h2":"En Virginia Occidental, un conductor menor de 18 años con permiso o licencia de Nivel 2 no puede usar un teléfono ni otro aparato inalámbrico mientras maneja, salvo para llamar al 911.","p":"Correcto. Solo se permite llamar al 911."},"zh":{"q":"在 West Virginia，未满 18 岁、持有学习驾照或第 2 级驾照的司机，开车时什么时候可以用手机？","o":["只能打 911","任何时候，只要不用手拿","只有在红灯时","只能给父母发短信"],"h1":"只有一个例外，是为了紧急情况。","h2":"在 West Virginia，未满 18 岁、持有学习驾照或第 2 级驾照的司机，开车时不能用手机或其他无线设备，只可以打 911。","p":"正确。只可以打 911。"},"vi":{"q":"Ở West Virginia, khi nào người lái xe dưới 18 tuổi có giấy phép tập lái hoặc bằng lái Cấp 2 được dùng điện thoại khi đang lái xe?","o":["Chỉ để gọi 911","Bất cứ lúc nào, nếu không cầm tay","Chỉ khi dừng đèn đỏ","Chỉ để nhắn tin cho cha mẹ"],"h1":"Chỉ có một ngoại lệ, và đó là cho trường hợp khẩn cấp.","h2":"Ở West Virginia, người lái xe dưới 18 tuổi có giấy phép tập lái hoặc bằng lái Cấp 2 không được dùng điện thoại hay thiết bị không dây khác khi lái xe, trừ khi gọi 911.","p":"Đúng. Chỉ được gọi 911."},"tl":{"q":"Sa West Virginia, kailan puwedeng gumamit ng telepono habang nagmamaneho ang drayber na wala pang 18 na may permit o Level 2 na lisensya?","o":["Para lamang tumawag sa 911","Kahit kailan, kung hands-free","Sa pulang ilaw lamang","Para lamang mag-text sa magulang"],"h1":"Isa lang ang eksepsiyon, at ito ay para sa emergency.","h2":"Sa West Virginia, ang drayber na wala pang 18 na may permit o Level 2 na lisensya ay hindi puwedeng gumamit ng telepono o ibang wireless device habang nagmamaneho, maliban para tumawag sa 911.","p":"Tama. Pagtawag lamang sa 911 ang pinapayagan."},"ar":{"q":"في West Virginia، متى يمكن للسائق الذي عمره أقل من 18 سنة ويحمل تصريحًا أو رخصة المستوى 2 أن يستخدم الهاتف أثناء القيادة؟","o":["فقط للاتصال بـ 911","في أي وقت، إذا كان دون استخدام اليدين","فقط عند الإشارة الحمراء","فقط لإرسال رسالة إلى أحد الوالدين"],"h1":"هناك استثناء واحد فقط، وهو للطوارئ.","h2":"في West Virginia لا يجوز للسائق الذي عمره أقل من 18 سنة ويحمل تصريحًا أو رخصة المستوى 2 أن يستخدم الهاتف أو أي جهاز لاسلكي آخر أثناء القيادة، إلا للاتصال بـ 911.","p":"صحيح. مسموح فقط الاتصال بـ 911."},"ref":{"doc":"WV","page":11}},{"id":"wv-017","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what does the law say about adult drivers and phones?","o":["You may text if traffic is slow","You may not hold the phone; calls must be hands-free","You may hold the phone on rural roads","There is no phone law for adults"],"h1":"Your hands belong on the wheel.","h2":"In West Virginia no driver may hold a phone while driving, and calls are allowed only with hands-free or voice-operated features.","p":"Right. Adults must be hands-free too."},"es":{"q":"En Virginia Occidental, ¿qué dice la ley sobre los conductores adultos y el teléfono?","o":["Puede escribir mensajes si el tráfico es lento","No puede sostener el teléfono; las llamadas deben ser manos libres","Puede sostener el teléfono en caminos rurales","No hay ley de teléfonos para adultos"],"h1":"Sus manos deben estar en el volante.","h2":"En Virginia Occidental ningún conductor puede sostener un teléfono mientras maneja, y las llamadas solo se permiten con manos libres o por voz.","p":"Correcto. Los adultos también deben usar manos libres."},"zh":{"q":"在 West Virginia，法律对成年司机用手机有什么规定？","o":["车开得慢时可以发短信","不能用手拿手机；打电话必须用免提","在乡村道路上可以用手拿手机","成年人没有手机法律"],"h1":"你的手应该放在方向盘上。","h2":"在 West Virginia，任何司机开车时都不能用手拿手机，打电话只能用免提或语音控制功能。","p":"对。成年人也必须用免提。"},"vi":{"q":"Ở West Virginia, luật nói gì về người lái xe trưởng thành và điện thoại?","o":["Bạn được nhắn tin nếu xe chạy chậm","Bạn không được cầm điện thoại; gọi điện phải dùng chế độ rảnh tay","Bạn được cầm điện thoại trên đường nông thôn","Không có luật về điện thoại cho người lớn"],"h1":"Tay bạn phải đặt trên vô lăng.","h2":"Ở West Virginia, không người lái xe nào được cầm điện thoại khi lái xe, và chỉ được gọi điện bằng chế độ rảnh tay hoặc điều khiển bằng giọng nói.","p":"Đúng. Người lớn cũng phải dùng chế độ rảnh tay."},"tl":{"q":"Sa West Virginia, ano ang sinasabi ng batas tungkol sa mga adultong drayber at telepono?","o":["Puwede kang mag-text kung mabagal ang trapiko","Hindi mo puwedeng hawakan ang telepono; ang tawag ay dapat hands-free","Puwede mong hawakan ang telepono sa mga daan sa probinsya","Walang batas sa telepono para sa mga adulto"],"h1":"Ang mga kamay mo ay dapat nasa manibela.","h2":"Sa West Virginia, walang drayber ang puwedeng humawak ng telepono habang nagmamaneho, at ang tawag ay pinapayagan lamang gamit ang hands-free o voice-operated na feature.","p":"Tama. Dapat hands-free din ang mga adulto."},"ar":{"q":"في West Virginia، ماذا يقول القانون عن السائقين البالغين والهواتف؟","o":["يمكنك إرسال الرسائل إذا كانت حركة السير بطيئة","لا يجوز لك أن تمسك الهاتف؛ المكالمات يجب أن تكون دون استخدام اليدين","يمكنك أن تمسك الهاتف على الطرق الريفية","لا يوجد قانون للهاتف للبالغين"],"h1":"يداك مكانهما على المِقوَد.","h2":"في West Virginia لا يجوز لأي سائق أن يمسك الهاتف أثناء القيادة، والمكالمات مسموحة فقط باستخدام خاصية عدم استخدام اليدين أو التحكّم بالصوت.","p":"صحيح. البالغون أيضًا يجب أن يستخدموا الهاتف دون اليدين."},"ref":{"doc":"WV","page":17}},{"id":"wv-018","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, what blood alcohol level is a crime for a driver under 21?","o":["0.08 or more","0.05 or more","0.02 or more","0.10 or more"],"h1":"It is far below the adult limit.","h2":"In West Virginia a driver under 21 commits a misdemeanor by driving with a blood alcohol level of 0.02 or more.","p":"Correct. Under 21, the limit is 0.02."},"es":{"q":"En Virginia Occidental, ¿qué nivel de alcohol en la sangre es un delito para un conductor menor de 21 años?","o":["0.08 o más","0.05 o más","0.02 o más","0.10 o más"],"h1":"Es mucho más bajo que el límite para adultos.","h2":"En Virginia Occidental, un conductor menor de 21 años comete un delito menor si maneja con un nivel de alcohol en la sangre de 0.02 o más.","p":"Correcto. Para menores de 21, el límite es 0.02."},"zh":{"q":"在 West Virginia，未满 21 岁的司机血液酒精浓度达到多少就是犯罪？","o":["0.08 或以上","0.05 或以上","0.02 或以上","0.10 或以上"],"h1":"它远远低于成年人的上限。","h2":"在 West Virginia，未满 21 岁的司机血液酒精浓度达到 0.02 或以上时开车，就犯了轻罪。","p":"正确。未满 21 岁，上限是 0.02。"},"vi":{"q":"Ở West Virginia, nồng độ cồn trong máu bao nhiêu là phạm tội đối với người lái xe dưới 21 tuổi?","o":["0.08 trở lên","0.05 trở lên","0.02 trở lên","0.10 trở lên"],"h1":"Nó thấp hơn nhiều so với giới hạn của người lớn.","h2":"Ở West Virginia, người lái xe dưới 21 tuổi phạm tội nhẹ nếu lái xe với nồng độ cồn trong máu từ 0.02 trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là 0.02."},"tl":{"q":"Sa West Virginia, anong antas ng alak sa dugo ang krimen para sa drayber na wala pang 21?","o":["0.08 o higit pa","0.05 o higit pa","0.02 o higit pa","0.10 o higit pa"],"h1":"Mas mababa ito nang malaki kaysa sa limitasyon ng adulto.","h2":"Sa West Virginia, ang drayber na wala pang 21 ay gumagawa ng misdemeanor kapag nagmaneho siya na may antas ng alak sa dugo na 0.02 o higit pa.","p":"Tama. Kung wala pang 21, ang limitasyon ay 0.02."},"ar":{"q":"في West Virginia، ما نسبة الكحول في الدم التي تُعتبر جريمة للسائق الذي عمره أقل من 21 سنة؟","o":["0.08 أو أكثر","0.05 أو أكثر","0.02 أو أكثر","0.10 أو أكثر"],"h1":"إنها أقل بكثير من حدّ البالغين.","h2":"في West Virginia يرتكب السائق الذي عمره أقل من 21 سنة جنحة إذا قاد ونسبة الكحول في دمه 0.02 أو أكثر.","p":"صحيح. لمن هم أقل من 21 سنة، الحدّ هو 0.02."},"ref":{"doc":"WV","page":null}},{"id":"wv-019","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, which stopped vehicle with flashing lights is covered by the move over law?","o":["Only police cars","Only fire trucks","Only ambulances","All of these: police cars, ambulances and tow trucks"],"h1":"The law covers any stopped vehicle that shows warning lights.","h2":"In West Virginia the move over law covers every stopped vehicle with flashing or hazard lights, including police cars, ambulances and tow trucks, so you move over if it is safe or slow down.","p":"Right. The law covers all of them."},"es":{"q":"En Virginia Occidental, ¿qué vehículo detenido con luces intermitentes está cubierto por la ley de cambiarse de carril (move over)?","o":["Solo patrullas","Solo camiones de bomberos","Solo ambulancias","Todos estos: patrullas, ambulancias y grúas"],"h1":"La ley cubre a cualquier vehículo detenido que muestre luces de advertencia.","h2":"En Virginia Occidental, la ley de cambiarse de carril cubre a todo vehículo detenido con luces intermitentes o de emergencia, incluidas patrullas, ambulancias y grúas, así que usted se cambia de carril si es seguro o reduce la velocidad.","p":"Correcto. La ley los cubre a todos."},"zh":{"q":"在 West Virginia，哪一种停在路边、亮着闪灯的车辆受「让道法」（move over law）保护？","o":["只有警车","只有消防车","只有救护车","以上都是：警车、救护车和拖车"],"h1":"法律包括任何停着、亮着警示灯的车辆。","h2":"在 West Virginia，「让道法」包括所有停着、亮着闪灯或危险警示灯的车辆，包括警车、救护车和拖车，所以安全时你要换到另一条车道，否则要减速。","p":"对。法律包括所有这些车辆。"},"vi":{"q":"Ở West Virginia, loại xe đang dừng và có đèn nhấp nháy nào được luật nhường đường (move over law) bảo vệ?","o":["Chỉ xe cảnh sát","Chỉ xe cứu hỏa","Chỉ xe cứu thương","Tất cả: xe cảnh sát, xe cứu thương và xe kéo"],"h1":"Luật áp dụng cho bất kỳ xe nào đang dừng và bật đèn cảnh báo.","h2":"Ở West Virginia, luật nhường đường áp dụng cho mọi xe đang dừng có đèn nhấp nháy hoặc đèn cảnh báo nguy hiểm, kể cả xe cảnh sát, xe cứu thương và xe kéo, nên bạn phải chuyển làn nếu an toàn, hoặc chạy chậm lại.","p":"Đúng. Luật áp dụng cho tất cả các xe đó."},"tl":{"q":"Sa West Virginia, aling nakahintong sasakyan na may kumikislap na ilaw ang sakop ng move over law?","o":["Mga sasakyan ng pulis lamang","Mga trak ng bumbero lamang","Mga ambulansya lamang","Lahat ng ito: sasakyan ng pulis, ambulansya at tow truck"],"h1":"Sakop ng batas ang anumang nakahintong sasakyan na may babalang ilaw.","h2":"Sa West Virginia, sakop ng move over law ang bawat nakahintong sasakyan na may kumikislap o hazard na ilaw, kasama ang sasakyan ng pulis, ambulansya at tow truck, kaya lumipat ka ng lane kung ligtas, o bumagal.","p":"Tama. Sakop ng batas ang lahat ng ito."},"ar":{"q":"في West Virginia، أي مركبة متوقّفة وأضواؤها تومض يشملها قانون الابتعاد (move over law)؟","o":["سيارات الشرطة فقط","سيارات الإطفاء فقط","سيارات الإسعاف فقط","كل هذه: سيارات الشرطة والإسعاف وشاحنات السحب"],"h1":"القانون يشمل أي مركبة متوقّفة تُظهر أضواء تحذير.","h2":"في West Virginia يشمل قانون الابتعاد كل مركبة متوقّفة بأضواء وامضة أو أضواء تحذير، ومنها سيارات الشرطة والإسعاف وشاحنات السحب، لذلك تنتقل إلى مسار آخر إذا كان ذلك آمنًا، أو تخفّف السرعة.","p":"صحيح. القانون يشملها كلها."},"ref":{"doc":"WV","page":null}},{"id":"wv-020","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, if you fail the permit knowledge test, how long must you wait to try again?","o":["Seven days","One day","Thirty days","Six months"],"h1":"It is one week.","h2":"In West Virginia you must wait seven days before retaking a failed knowledge test.","p":"Correct. You wait one week."},"es":{"q":"En Virginia Occidental, si no aprueba el examen de conocimientos del permiso, ¿cuánto debe esperar para intentarlo otra vez?","o":["Siete días","Un día","Treinta días","Seis meses"],"h1":"Es una semana.","h2":"En Virginia Occidental usted debe esperar siete días antes de repetir un examen de conocimientos que no aprobó.","p":"Correcto. Se espera una semana."},"zh":{"q":"在 West Virginia，如果你没有通过学习驾照笔试，要等多久才可以再考？","o":["七天","一天","三十天","六个月"],"h1":"是一个星期。","h2":"在 West Virginia，笔试没通过，你必须等七天才可以重考。","p":"正确。你要等一个星期。"},"vi":{"q":"Ở West Virginia, nếu bạn thi trượt bài thi lý thuyết để lấy giấy phép tập lái, bạn phải chờ bao lâu để thi lại?","o":["Bảy ngày","Một ngày","Ba mươi ngày","Sáu tháng"],"h1":"Đó là một tuần.","h2":"Ở West Virginia, bạn phải chờ bảy ngày trước khi thi lại bài thi lý thuyết bị trượt.","p":"Đúng. Bạn chờ một tuần."},"tl":{"q":"Sa West Virginia, kung bumagsak ka sa knowledge test para sa permit, gaano katagal kang maghihintay bago sumubok ulit?","o":["Pitong araw","Isang araw","Tatlumpung araw","Anim na buwan"],"h1":"Isang linggo ito.","h2":"Sa West Virginia, dapat kang maghintay ng pitong araw bago kumuha ulit ng knowledge test na binagsak mo.","p":"Tama. Maghihintay ka ng isang linggo."},"ar":{"q":"في West Virginia، إذا رسبت في اختبار المعرفة للتصريح، كم يجب أن تنتظر لتحاول مرة أخرى؟","o":["سبعة أيام","يوم واحد","ثلاثون يومًا","ستة أشهر"],"h1":"إنه أسبوع واحد.","h2":"في West Virginia يجب أن تنتظر سبعة أيام قبل إعادة اختبار المعرفة الذي رسبت فيه.","p":"صحيح. تنتظر أسبوعًا واحدًا."},"ref":{"doc":"WV","page":26}},{"id":"wv-021","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what do you need to take the permit knowledge test online?","o":["Only a smartphone","A computer with a mouse and a webcam","A tablet with no camera","A printed paper test"],"h1":"A phone will not work for this test.","h2":"In West Virginia the online knowledge test needs a computer with a mouse and a webcam; phones and touch screens do not work.","p":"Right. You need a computer with a camera."},"es":{"q":"En Virginia Occidental, ¿qué necesita para tomar en línea el examen de conocimientos del permiso?","o":["Solo un teléfono inteligente","Una computadora con ratón y cámara web","Una tableta sin cámara","Un examen impreso en papel"],"h1":"Un teléfono no sirve para este examen.","h2":"En Virginia Occidental, el examen de conocimientos en línea necesita una computadora con ratón y cámara web; los teléfonos y las pantallas táctiles no sirven.","p":"Correcto. Necesita una computadora con cámara."},"zh":{"q":"在 West Virginia，在网上考学习驾照笔试需要什么？","o":["只要一部智能手机","一台有鼠标和摄像头的电脑","一台没有摄像头的平板电脑","一份印出来的纸质考卷"],"h1":"用手机不能考这个试。","h2":"在 West Virginia，网上笔试需要一台有鼠标和摄像头的电脑；手机和触摸屏都不能用。","p":"对。你需要一台有摄像头的电脑。"},"vi":{"q":"Ở West Virginia, bạn cần gì để làm bài thi lý thuyết lấy giấy phép tập lái trực tuyến?","o":["Chỉ cần một điện thoại thông minh","Một máy tính có chuột và webcam","Một máy tính bảng không có camera","Một bài thi in trên giấy"],"h1":"Điện thoại không dùng được cho bài thi này.","h2":"Ở West Virginia, bài thi lý thuyết trực tuyến cần một máy tính có chuột và webcam; điện thoại và màn hình cảm ứng không dùng được.","p":"Đúng. Bạn cần một máy tính có camera."},"tl":{"q":"Sa West Virginia, ano ang kailangan mo para kumuha ng knowledge test para sa permit online?","o":["Isang smartphone lamang","Isang computer na may mouse at webcam","Isang tablet na walang camera","Isang naka-print na papel na test"],"h1":"Hindi gagana ang telepono para sa test na ito.","h2":"Sa West Virginia, ang online na knowledge test ay nangangailangan ng computer na may mouse at webcam; hindi gagana ang mga telepono at touch screen.","p":"Tama. Kailangan mo ng computer na may camera."},"ar":{"q":"في West Virginia، ماذا تحتاج لتأخذ اختبار المعرفة للتصريح عبر الإنترنت؟","o":["هاتف ذكي فقط","حاسوب مع فأرة وكاميرا ويب","جهاز لوحي دون كاميرا","اختبار ورقي مطبوع"],"h1":"الهاتف لا يعمل لهذا الاختبار.","h2":"في West Virginia يحتاج اختبار المعرفة عبر الإنترنت إلى حاسوب مع فأرة وكاميرا ويب؛ الهواتف والشاشات التي تعمل باللمس لا تعمل.","p":"صحيح. تحتاج إلى حاسوب مع كاميرا."},"ref":{"doc":"WV","page":null}},{"id":"wv-022","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many correct answers out of 25 do you need to pass the knowledge test?","o":["15","19","22","25"],"h1":"You can miss up to six questions.","h2":"In West Virginia, you need 19 correct answers out of 25 to pass the knowledge test, and the test is timed.","p":"Right. 19 out of 25."},"es":{"q":"En Virginia Occidental, ¿cuántas respuestas correctas de 25 necesita para aprobar el examen de conocimientos?","o":["15","19","22","25"],"h1":"Puede fallar hasta seis preguntas.","h2":"En Virginia Occidental, necesita 19 respuestas correctas de 25 para aprobar el examen de conocimientos, y el examen tiene un límite de tiempo.","p":"Correcto. 19 de 25."},"zh":{"q":"在 West Virginia，知识考试 25 题中你需要答对几题才能通过？","o":["15","19","22","25"],"h1":"你最多可以答错六题。","h2":"在 West Virginia，知识考试 25 题中你需要答对 19 题才能通过，而且考试有时间限制。","p":"对。25 题中答对 19 题。"},"vi":{"q":"Ở West Virginia, bạn cần trả lời đúng bao nhiêu câu trong 25 câu để đậu bài thi kiến thức?","o":["15","19","22","25"],"h1":"Bạn có thể sai tối đa sáu câu.","h2":"Ở West Virginia, bạn cần trả lời đúng 19 trên 25 câu để đậu bài thi kiến thức, và bài thi có giới hạn thời gian.","p":"Đúng. 19 trên 25 câu."},"tl":{"q":"Sa West Virginia, ilang tamang sagot sa 25 ang kailangan mo para pumasa sa knowledge test?","o":["15","19","22","25"],"h1":"Puwede kang magkamali nang hanggang anim na tanong.","h2":"Sa West Virginia, kailangan mo ng 19 na tamang sagot sa 25 para pumasa sa knowledge test, at may takdang oras ang test.","p":"Tama. 19 sa 25."},"ar":{"q":"في West Virginia، كم إجابة صحيحة من 25 تحتاج لتنجح في اختبار المعرفة؟","o":["15","19","22","25"],"h1":"يمكنك أن تخطئ في ستة أسئلة على الأكثر.","h2":"في West Virginia، تحتاج إلى 19 إجابة صحيحة من 25 لتنجح في اختبار المعرفة، والاختبار له وقت محدد.","p":"صحيح. 19 من 25."},"ref":{"doc":"WV","page":24}},{"id":"wv-023","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, what is the minimum liability insurance for the death or injury of one person?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"It is the same amount as the minimum for property damage.","h2":"In West Virginia, the minimum liability insurance is $25,000 for one death or injury, $50,000 for two or more, and $25,000 for property damage.","p":"Right. $25,000 for one person."},"es":{"q":"En Virginia Occidental, ¿cuál es el seguro de responsabilidad mínimo por la muerte o lesión de una persona?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Es la misma cantidad que el mínimo por daños a la propiedad.","h2":"En Virginia Occidental, el seguro de responsabilidad mínimo es de $25,000 por una muerte o lesión, $50,000 por dos o más, y $25,000 por daños a la propiedad.","p":"Correcto. $25,000 por una persona."},"zh":{"q":"在 West Virginia，一个人死亡或受伤的最低责任保险是多少？","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"它和财产损失的最低金额一样。","h2":"在 West Virginia，最低责任保险是：一个人死亡或受伤 $25,000，两个人或以上 $50,000，财产损失 $25,000。","p":"对。一个人是 $25,000。"},"vi":{"q":"Ở West Virginia, mức bảo hiểm trách nhiệm tối thiểu cho việc một người chết hoặc bị thương là bao nhiêu?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Số tiền này bằng mức tối thiểu cho thiệt hại tài sản.","h2":"Ở West Virginia, bảo hiểm trách nhiệm tối thiểu là $25,000 cho một người chết hoặc bị thương, $50,000 cho hai người trở lên, và $25,000 cho thiệt hại tài sản.","p":"Đúng. $25,000 cho một người."},"tl":{"q":"Sa West Virginia, magkano ang pinakamababang liability insurance para sa pagkamatay o pagkapinsala ng isang tao?","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"Pareho ito ng pinakamababang halaga para sa sira sa ari-arian.","h2":"Sa West Virginia, ang pinakamababang liability insurance ay $25,000 para sa pagkamatay o pagkapinsala ng isang tao, $50,000 para sa dalawa o higit pa, at $25,000 para sa sira sa ari-arian.","p":"Tama. $25,000 para sa isang tao."},"ar":{"q":"في West Virginia، ما الحد الأدنى لتأمين المسؤولية عن وفاة شخص واحد أو إصابته؟","o":["$5,000","$10,000","$100,000","$25,000"],"h1":"إنه نفس المبلغ الأدنى لأضرار الممتلكات.","h2":"في West Virginia، الحد الأدنى لتأمين المسؤولية هو $25,000 لوفاة شخص واحد أو إصابته، و$50,000 لشخصين أو أكثر، و$25,000 لأضرار الممتلكات.","p":"صحيح. $25,000 لشخص واحد."},"ref":{"doc":"WV","page":16}},{"id":"wv-024","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points on your record can lead to a license suspension?","o":["3 points","6 points","12 points","25 points"],"h1":"At half this number, the DMV sends a letter of caution.","h2":"In West Virginia, the DMV sends a letter of caution at 6 points, and a driver with 12 points can have the license suspended.","p":"Right. 12 points can mean a suspension."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos en su historial pueden llevar a la suspensión de la licencia?","o":["3 puntos","6 puntos","12 puntos","25 puntos"],"h1":"Con la mitad de este número, el DMV envía una carta de advertencia.","h2":"En Virginia Occidental, el DMV envía una carta de advertencia con 6 puntos, y a un conductor con 12 puntos se le puede suspender la licencia.","p":"Correcto. 12 puntos pueden llevar a una suspensión."},"zh":{"q":"在 West Virginia，记录上有多少分可能导致驾照被暂停？","o":["3 分","6 分","12 分","25 分"],"h1":"到这个数字的一半时，DMV 会寄一封警告信。","h2":"在 West Virginia，到 6 分时 DMV 会寄一封警告信，有 12 分的司机可能会被暂停驾照。","p":"对。12 分可能导致驾照被暂停。"},"vi":{"q":"Ở West Virginia, bao nhiêu điểm trong hồ sơ có thể khiến bằng lái bị đình chỉ?","o":["3 điểm","6 điểm","12 điểm","25 điểm"],"h1":"Khi đến một nửa số điểm này, DMV sẽ gửi thư cảnh báo.","h2":"Ở West Virginia, DMV gửi thư cảnh báo khi có 6 điểm, và tài xế có 12 điểm có thể bị đình chỉ bằng lái.","p":"Đúng. 12 điểm có thể bị đình chỉ bằng lái."},"tl":{"q":"Sa West Virginia, ilang puntos sa iyong rekord ang puwedeng mauwi sa suspensyon ng lisensya?","o":["3 puntos","6 puntos","12 puntos","25 puntos"],"h1":"Sa kalahati ng bilang na ito, magpapadala ang DMV ng sulat ng babala.","h2":"Sa West Virginia, nagpapadala ang DMV ng sulat ng babala sa 6 na puntos, at puwedeng masuspinde ang lisensya ng drayber na may 12 puntos.","p":"Tama. Ang 12 puntos ay puwedeng mauwi sa suspensyon."},"ar":{"q":"في West Virginia، كم نقطة في سجلك يمكن أن تؤدي إلى تعليق الرخصة؟","o":["3 نقاط","6 نقاط","12 نقطة","25 نقطة"],"h1":"عند نصف هذا العدد، ترسل DMV رسالة تحذير.","h2":"في West Virginia، ترسل DMV رسالة تحذير عند 6 نقاط، والسائق الذي لديه 12 نقطة يمكن أن تُعلَّق رخصته.","p":"صحيح. 12 نقطة يمكن أن تعني تعليق الرخصة."},"ref":{"doc":"WV","page":18}},{"id":"wv-025","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, what happens if you are arrested for DUI and refuse the breath test?","o":["Your license is revoked for at least one year","You pay a small fine and keep driving","You get a warning the first time","Your license is suspended for one week"],"h1":"West Virginia's implied consent law treats refusal very seriously.","h2":"In West Virginia, a driver arrested for DUI who refuses the breath test has the driving privilege revoked for at least one year, and up to life.","p":"Right. Revoked for at least one year."},"es":{"q":"En Virginia Occidental, ¿qué pasa si lo arrestan por manejar bajo los efectos del alcohol (DUI) y se niega a la prueba de aliento?","o":["Le revocan la licencia por lo menos un año","Paga una multa pequeña y sigue manejando","Recibe una advertencia la primera vez","Le suspenden la licencia por una semana"],"h1":"La ley de consentimiento implícito de Virginia Occidental trata la negativa con mucha seriedad.","h2":"En Virginia Occidental, a un conductor arrestado por DUI que se niega a la prueba de aliento le revocan el privilegio de manejar por lo menos un año, y hasta de por vida.","p":"Correcto. Revocada por lo menos un año."},"zh":{"q":"在 West Virginia，如果你因酒后驾驶（DUI）被捕并拒绝呼气测试，会怎样？","o":["你的驾照会被吊销至少一年","你交一小笔罚款，还可以继续开车","第一次只会收到警告","你的驾照会被暂停一周"],"h1":"West Virginia 的默示同意法（implied consent law）把拒绝测试看得非常严重。","h2":"在 West Virginia，因酒后驾驶（DUI）被捕并拒绝呼气测试的司机，驾驶资格会被吊销至少一年，最长可以是终身。","p":"对。至少吊销一年。"},"vi":{"q":"Ở West Virginia, điều gì xảy ra nếu bạn bị bắt vì lái xe khi say (DUI) và từ chối kiểm tra hơi thở?","o":["Bằng lái của bạn bị thu hồi ít nhất một năm","Bạn trả một khoản phạt nhỏ và tiếp tục lái xe","Bạn chỉ bị cảnh cáo lần đầu","Bằng lái của bạn bị đình chỉ một tuần"],"h1":"Luật đồng ý ngầm (implied consent law) của West Virginia coi việc từ chối là rất nghiêm trọng.","h2":"Ở West Virginia, tài xế bị bắt vì lái xe khi say (DUI) mà từ chối kiểm tra hơi thở sẽ bị thu hồi quyền lái xe ít nhất một năm, và có thể đến suốt đời.","p":"Đúng. Bị thu hồi ít nhất một năm."},"tl":{"q":"Sa West Virginia, ano ang mangyayari kung arestuhin ka dahil sa DUI at tumanggi ka sa breath test?","o":["Babawiin ang iyong lisensya nang hindi bababa sa isang taon","Magbabayad ka ng maliit na multa at magpapatuloy sa pagmamaneho","Babala lang ang makukuha mo sa unang beses","Masususpinde ang iyong lisensya nang isang linggo"],"h1":"Napakaseryoso ng pagtanggi sa ilalim ng implied consent law ng West Virginia.","h2":"Sa West Virginia, ang drayber na inaresto dahil sa DUI at tumanggi sa breath test ay babawian ng karapatang magmaneho nang hindi bababa sa isang taon, at puwedeng habambuhay.","p":"Tama. Babawiin nang hindi bababa sa isang taon."},"ar":{"q":"في West Virginia، ماذا يحدث إذا قُبض عليك بتهمة القيادة تحت التأثير (DUI) ورفضت اختبار التنفس؟","o":["تُلغى رخصتك لمدة سنة واحدة على الأقل","تدفع غرامة صغيرة وتستمر في القيادة","تحصل على تحذير في المرة الأولى","تُعلَّق رخصتك لمدة أسبوع واحد"],"h1":"قانون الموافقة الضمنية (implied consent law) في West Virginia يعامل الرفض بجدية كبيرة.","h2":"في West Virginia، السائق الذي يُقبض عليه بتهمة القيادة تحت التأثير (DUI) ويرفض اختبار التنفس يُلغى حقه في القيادة لمدة سنة واحدة على الأقل، وقد يصل ذلك إلى مدى الحياة.","p":"صحيح. تُلغى لمدة سنة واحدة على الأقل."},"ref":{"doc":"WV","page":22}},{"id":"wv-026","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In West Virginia, what is the speed limit in a school zone while children are present, unless posted otherwise?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"It is lower than the 25 mph limit for residential areas.","h2":"In West Virginia, the speed limit in a school zone is 15 mph while children are present along the road.","p":"Right. 15 mph in a school zone."},"es":{"q":"En Virginia Occidental, ¿cuál es el límite de velocidad en una zona escolar cuando hay niños presentes, si no hay otro señalado?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Es más bajo que el límite de 25 mph de las zonas residenciales.","h2":"En Virginia Occidental, el límite de velocidad en una zona escolar es de 15 mph cuando hay niños presentes a lo largo de la calle.","p":"Correcto. 15 mph en una zona escolar."},"zh":{"q":"在 West Virginia，如果没有其他标示，有孩子在场时学校区域的限速是多少？","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"它比住宅区 25 mph 的限速低。","h2":"在 West Virginia，路边有孩子时，学校区域的限速是 15 mph。","p":"对。学校区域是 15 mph。"},"vi":{"q":"Ở West Virginia, nếu không có biển báo khác, tốc độ giới hạn trong khu vực trường học khi có trẻ em là bao nhiêu?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Nó thấp hơn giới hạn 25 mph ở khu dân cư.","h2":"Ở West Virginia, tốc độ giới hạn trong khu vực trường học là 15 mph khi có trẻ em dọc theo đường.","p":"Đúng. 15 mph trong khu vực trường học."},"tl":{"q":"Sa West Virginia, ano ang speed limit sa school zone habang may mga bata, maliban kung iba ang nakapaskil?","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"Mas mababa ito sa 25 mph na limit sa mga residential area.","h2":"Sa West Virginia, ang speed limit sa school zone ay 15 mph habang may mga bata sa tabi ng daan.","p":"Tama. 15 mph sa school zone."},"ar":{"q":"في West Virginia، ما حد السرعة في منطقة المدرسة عند وجود أطفال، ما لم تُوضع لافتة بغير ذلك؟","o":["10 mph","15 mph","25 mph","35 mph"],"h1":"إنه أقل من حد 25 mph في المناطق السكنية.","h2":"في West Virginia، حد السرعة في منطقة المدرسة هو 15 mph عند وجود أطفال على جانب الطريق.","p":"صحيح. 15 mph في منطقة المدرسة."},"ref":{"doc":"WV","page":42}},{"id":"wv-027","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points can an approved 8-hour defensive driving class remove from your record?","o":["1 point","All of your points","3 points","6 points"],"h1":"You can only do this once every 12 months.","h2":"In West Virginia, finishing an approved 8-hour defensive driving class removes 3 points from your record, no more than once every 12 months.","p":"Right. The class removes 3 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos puede quitar de su historial una clase aprobada de manejo defensivo de 8 horas?","o":["1 punto","Todos sus puntos","3 puntos","6 puntos"],"h1":"Solo puede hacerlo una vez cada 12 meses.","h2":"En Virginia Occidental, terminar una clase aprobada de manejo defensivo de 8 horas le quita 3 puntos de su historial, no más de una vez cada 12 meses.","p":"Correcto. La clase quita 3 puntos."},"zh":{"q":"在 West Virginia，一门认可的 8 小时防御性驾驶课程可以从你的记录中去掉几分？","o":["1 分","你所有的分数","3 分","6 分"],"h1":"每 12 个月只能这样做一次。","h2":"在 West Virginia，完成一门认可的 8 小时防御性驾驶课程可以从你的记录中去掉 3 分，每 12 个月最多一次。","p":"对。这门课去掉 3 分。"},"vi":{"q":"Ở West Virginia, một lớp lái xe phòng vệ 8 giờ được chấp thuận có thể xóa bao nhiêu điểm khỏi hồ sơ của bạn?","o":["1 điểm","Tất cả số điểm của bạn","3 điểm","6 điểm"],"h1":"Bạn chỉ có thể làm điều này một lần mỗi 12 tháng.","h2":"Ở West Virginia, hoàn thành một lớp lái xe phòng vệ 8 giờ được chấp thuận sẽ xóa 3 điểm khỏi hồ sơ của bạn, không quá một lần mỗi 12 tháng.","p":"Đúng. Lớp học xóa 3 điểm."},"tl":{"q":"Sa West Virginia, ilang puntos ang puwedeng alisin sa iyong rekord ng isang aprubadong 8-oras na defensive driving class?","o":["1 punto","Lahat ng iyong puntos","3 puntos","6 puntos"],"h1":"Isang beses mo lang ito puwedeng gawin bawat 12 buwan.","h2":"Sa West Virginia, ang pagtatapos ng isang aprubadong 8-oras na defensive driving class ay nag-aalis ng 3 puntos sa iyong rekord, hindi hihigit sa isang beses bawat 12 buwan.","p":"Tama. Nag-aalis ang klase ng 3 puntos."},"ar":{"q":"في West Virginia، كم نقطة يمكن أن تزيلها من سجلك دورة قيادة دفاعية معتمدة مدتها 8 ساعات؟","o":["نقطة واحدة","كل نقاطك","3 نقاط","6 نقاط"],"h1":"يمكنك فعل ذلك مرة واحدة فقط كل 12 شهرًا.","h2":"في West Virginia، إنهاء دورة قيادة دفاعية معتمدة مدتها 8 ساعات يزيل 3 نقاط من سجلك، ولا يكون ذلك أكثر من مرة واحدة كل 12 شهرًا.","p":"صحيح. الدورة تزيل 3 نقاط."},"ref":{"doc":"WV","page":18}},{"id":"wv-028","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, after you move to the state, how soon must you apply for a West Virginia driver's license?","o":["Within 30 days","Within 10 days","Within 90 days","Within 1 year"],"h1":"It is about one month.","h2":"In West Virginia, a new resident who wants to drive must apply for a West Virginia driver's license within 30 days.","p":"Right. New residents have 30 days to apply."},"es":{"q":"En West Virginia, después de mudarse al estado, ¿en cuánto tiempo debe solicitar una licencia de conducir de West Virginia?","o":["En 30 días","En 10 días","En 90 días","En 1 año"],"h1":"Es más o menos un mes.","h2":"En West Virginia, un nuevo residente que quiere manejar debe solicitar una licencia de conducir de West Virginia en 30 días.","p":"Correcto. Los nuevos residentes tienen 30 días para solicitarla."},"zh":{"q":"在 West Virginia，搬到本州以后，你必须在多长时间内申请 West Virginia 驾照？","o":["30 天内","10 天内","90 天内","1 年内"],"h1":"大约是一个月。","h2":"在 West Virginia，想开车的新居民必须在 30 天内申请 West Virginia 驾照。","p":"对。新居民有 30 天时间申请。"},"vi":{"q":"Ở West Virginia, sau khi chuyển đến tiểu bang, bạn phải nộp đơn xin bằng lái West Virginia trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 90 ngày","Trong vòng 1 năm"],"h1":"Khoảng một tháng.","h2":"Ở West Virginia, cư dân mới muốn lái xe phải nộp đơn xin bằng lái West Virginia trong vòng 30 ngày.","p":"Đúng. Cư dân mới có 30 ngày để nộp đơn."},"tl":{"q":"Sa West Virginia, pagkalipat mo sa estado, gaano kabilis ka dapat mag-apply ng West Virginia driver's license?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 90 araw","Sa loob ng 1 taon"],"h1":"Mga isang buwan ito.","h2":"Sa West Virginia, ang bagong residente na gustong magmaneho ay dapat mag-apply ng West Virginia driver's license sa loob ng 30 araw.","p":"Tama. May 30 araw ang mga bagong residente para mag-apply."},"ar":{"q":"في West Virginia، بعد أن تنتقل إلى الولاية، خلال كم من الوقت يجب أن تقدّم طلبًا للحصول على رخصة قيادة من West Virginia؟","o":["خلال 30 يومًا","خلال 10 أيام","خلال 90 يومًا","خلال سنة واحدة (1)"],"h1":"إنه نحو شهر واحد.","h2":"في West Virginia، يجب على المقيم الجديد الذي يريد القيادة أن يقدّم طلبًا للحصول على رخصة قيادة من West Virginia خلال 30 يومًا.","p":"صحيح. لدى المقيمين الجدد 30 يومًا لتقديم الطلب."},"ref":{"doc":"WV","page":2}},{"id":"wv-029","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, you are driving at night behind another vehicle. Within how many feet must you dim your headlights?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"It is a shorter distance than for an oncoming vehicle.","h2":"In West Virginia, you must dim your headlights within 200 feet when you follow another vehicle.","p":"Right. Dim your lights within 200 feet of a vehicle ahead."},"es":{"q":"En West Virginia, usted maneja de noche detrás de otro vehículo. ¿A cuántos pies debe bajar las luces?","o":["100 pies","500 pies","200 pies","1,000 pies"],"h1":"Es una distancia más corta que para un vehículo que viene de frente.","h2":"En West Virginia, usted debe bajar las luces a 200 pies cuando va detrás de otro vehículo.","p":"Correcto. Baje las luces a 200 pies de un vehículo que va adelante."},"zh":{"q":"在 West Virginia，你晚上在另一辆车后面开车。你必须在多少英尺以内把大灯调暗？","o":["100 英尺","500 英尺","200 英尺","1,000 英尺"],"h1":"这个距离比对面来车时要短。","h2":"在 West Virginia，跟在另一辆车后面时，你必须在 200 英尺以内把大灯调暗。","p":"对。前面有车时，在 200 英尺以内要调暗车灯。"},"vi":{"q":"Ở West Virginia, bạn đang lái xe ban đêm phía sau một xe khác. Bạn phải giảm đèn pha trong phạm vi bao nhiêu feet?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"Khoảng cách này ngắn hơn so với khi có xe chạy ngược chiều.","h2":"Ở West Virginia, bạn phải giảm đèn pha trong phạm vi 200 feet khi bạn chạy theo sau một xe khác.","p":"Đúng. Giảm đèn trong phạm vi 200 feet khi có xe phía trước."},"tl":{"q":"Sa West Virginia, nagmamaneho ka sa gabi sa likod ng ibang sasakyan. Sa loob ng ilang talampakan (feet) mo dapat hinaan ang iyong headlights?","o":["100 feet","500 feet","200 feet","1,000 feet"],"h1":"Mas maikli ang layong ito kaysa sa sasakyang paparating mula sa kabila.","h2":"Sa West Virginia, dapat mong hinaan ang iyong headlights sa loob ng 200 feet kapag sumusunod ka sa ibang sasakyan.","p":"Tama. Hinaan ang ilaw sa loob ng 200 feet ng sasakyang nasa unahan."},"ar":{"q":"في West Virginia، أنت تقود ليلًا خلف مركبة أخرى. ضمن كم قدمًا يجب أن تخفّض أضواء سيارتك الأمامية؟","o":["100 قدم","500 قدم","200 قدم","1,000 قدم"],"h1":"إنها مسافة أقصر من مسافة المركبة القادمة من الاتجاه المقابل.","h2":"في West Virginia، يجب أن تخفّض أضواءك الأمامية ضمن 200 قدم عندما تسير خلف مركبة أخرى.","p":"صحيح. خفّض أضواءك ضمن 200 قدم من المركبة التي أمامك."},"ref":{"doc":"WV","page":62}},{"id":"wv-030","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, you may not park within how many feet of a fire hydrant?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Fire trucks need room to connect their hoses.","h2":"In West Virginia, you may not park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet from a fire hydrant when you park."},"es":{"q":"En West Virginia, ¿a cuántos pies de un hidrante no puede estacionarse?","o":["5 pies","10 pies","25 pies","15 pies"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En West Virginia, usted no puede estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Al estacionarse, quédese por lo menos a 15 pies de un hidrante."},"zh":{"q":"在 West Virginia，你不可以在离消防栓多少英尺以内停车？","o":["5 英尺","10 英尺","25 英尺","15 英尺"],"h1":"消防车需要空间来接水管。","h2":"在 West Virginia，你不可以在离消防栓 15 英尺以内停车。","p":"对。停车时要离消防栓至少 15 英尺。"},"vi":{"q":"Ở West Virginia, bạn không được đậu xe trong phạm vi bao nhiêu feet từ trụ nước cứu hỏa?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Xe cứu hỏa cần chỗ để nối vòi nước.","h2":"Ở West Virginia, bạn không được đậu xe trong phạm vi 15 feet từ trụ nước cứu hỏa.","p":"Đúng. Khi đậu xe, hãy cách trụ nước cứu hỏa ít nhất 15 feet."},"tl":{"q":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng ilang talampakan (feet) mula sa fire hydrant?","o":["5 feet","10 feet","25 feet","15 feet"],"h1":"Kailangan ng mga trak ng bumbero ng espasyo para ikabit ang kanilang hose.","h2":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng 15 feet mula sa fire hydrant.","p":"Tama. Lumayo nang hindi bababa sa 15 feet mula sa fire hydrant kapag pumarada ka."},"ar":{"q":"في West Virginia، لا يجوز لك أن تركن سيارتك ضمن كم قدمًا من صنبور إطفاء الحريق؟","o":["5 أقدام","10 أقدام","25 قدمًا","15 قدمًا"],"h1":"تحتاج سيارات الإطفاء إلى مساحة لتوصيل خراطيمها.","h2":"في West Virginia، لا يجوز لك أن تركن سيارتك ضمن 15 قدمًا من صنبور إطفاء الحريق.","p":"صحيح. ابقَ على بعد 15 قدمًا على الأقل من صنبور إطفاء الحريق عندما تركن."},"ref":{"doc":"WV","page":45}},{"id":"wv-031","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the lowest fine for littering on a road?","o":["$10","$50","$250","$2,000"],"h1":"The fine can go up to $1,000.","h2":"In West Virginia, littering can bring a fine of at least $50 and up to $1,000, or instead jail or picking up litter along the road.","p":"Right. Littering costs at least $50, and you may also get points."},"es":{"q":"En West Virginia, ¿cuál es la multa más baja por tirar basura en la carretera?","o":["$10","$50","$250","$2,000"],"h1":"La multa puede llegar hasta $1,000.","h2":"En West Virginia, tirar basura puede costar una multa de por lo menos $50 y hasta $1,000, o en su lugar cárcel o recoger basura en la carretera.","p":"Correcto. Tirar basura cuesta por lo menos $50, y también puede recibir puntos."},"zh":{"q":"在 West Virginia，在道路上乱扔垃圾的最低罚款是多少？","o":["$10","$50","$250","$2,000"],"h1":"罚款最高可以到 $1,000。","h2":"在 West Virginia，乱扔垃圾可能被罚款至少 $50、最多 $1,000，或者改为坐牢或在路边捡垃圾。","p":"对。乱扔垃圾至少罚 $50，你还可能被扣分。"},"vi":{"q":"Ở West Virginia, tiền phạt thấp nhất cho việc xả rác trên đường là bao nhiêu?","o":["$10","$50","$250","$2,000"],"h1":"Tiền phạt có thể lên đến $1,000.","h2":"Ở West Virginia, xả rác có thể bị phạt ít nhất $50 và tối đa $1,000, hoặc thay vào đó là ngồi tù hoặc nhặt rác dọc đường.","p":"Đúng. Xả rác bị phạt ít nhất $50, và bạn cũng có thể bị trừ điểm."},"tl":{"q":"Sa West Virginia, ano ang pinakamababang multa sa pagkakalat ng basura sa kalsada?","o":["$10","$50","$250","$2,000"],"h1":"Puwedeng umabot ang multa hanggang $1,000.","h2":"Sa West Virginia, ang pagkakalat ng basura ay puwedeng magdala ng multang hindi bababa sa $50 at hanggang $1,000, o sa halip ay kulong o pamumulot ng basura sa tabi ng kalsada.","p":"Tama. Hindi bababa sa $50 ang multa sa pagkakalat ng basura, at puwede ka ring magkaroon ng points."},"ar":{"q":"في West Virginia، ما أقل غرامة لرمي النفايات على الطريق؟","o":["$10","$50","$250","$2,000"],"h1":"يمكن أن تصل الغرامة إلى $1,000.","h2":"في West Virginia، يمكن أن يؤدي رمي النفايات إلى غرامة لا تقل عن $50 وتصل إلى $1,000، أو بدلًا من ذلك السجن أو جمع النفايات على جانب الطريق.","p":"صحيح. غرامة رمي النفايات $50 على الأقل، وقد تحصل أيضًا على نقاط."},"ref":{"doc":"WV","page":77}},{"id":"wv-032","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, you move to a new address. How soon must you tell the DMV in writing?","o":["Within 60 days","Within 90 days","Within 20 days","At your next renewal"],"h1":"It is less than a month.","h2":"In West Virginia you must tell the DMV about your new address in writing within 20 days.","p":"Right. Tell the DMV within 20 days."},"es":{"q":"En Virginia Occidental, usted se muda a una nueva dirección. ¿En cuánto tiempo debe avisar por escrito al DMV?","o":["En 60 días","En 90 días","En 20 días","En su próxima renovación"],"h1":"Es menos de un mes.","h2":"En Virginia Occidental usted debe avisar por escrito al DMV de su nueva dirección en un plazo de 20 días.","p":"Correcto. Avise al DMV en 20 días."},"zh":{"q":"在 West Virginia，你搬到了新地址。你必须在多久之内以书面方式通知 DMV？","o":["60 天之内","90 天之内","20 天之内","下次换照的时候"],"h1":"不到一个月。","h2":"在 West Virginia，你必须在 20 天之内以书面方式把新地址通知 DMV。","p":"对。在 20 天之内通知 DMV。"},"vi":{"q":"Ở West Virginia, bạn chuyển đến địa chỉ mới. Bạn phải báo cho DMV bằng văn bản trong bao lâu?","o":["Trong vòng 60 ngày","Trong vòng 90 ngày","Trong vòng 20 ngày","Vào lần gia hạn bằng lái tới"],"h1":"Ít hơn một tháng.","h2":"Ở West Virginia, bạn phải báo địa chỉ mới cho DMV bằng văn bản trong vòng 20 ngày.","p":"Đúng. Báo cho DMV trong vòng 20 ngày."},"tl":{"q":"Sa West Virginia, lumipat ka sa bagong address. Gaano kabilis mo dapat sabihan nang nakasulat ang DMV?","o":["Sa loob ng 60 araw","Sa loob ng 90 araw","Sa loob ng 20 araw","Sa susunod mong pag-renew"],"h1":"Mas maikli ito sa isang buwan.","h2":"Sa West Virginia, dapat mong sabihan nang nakasulat ang DMV tungkol sa bago mong address sa loob ng 20 araw.","p":"Tama. Sabihan ang DMV sa loob ng 20 araw."},"ar":{"q":"في West Virginia، انتقلت إلى عنوان جديد. خلال كم من الوقت يجب أن تُبلغ DMV كتابيًا؟","o":["خلال 60 يومًا","خلال 90 يومًا","خلال 20 يومًا","عند تجديد الرخصة القادم"],"h1":"إنه أقل من شهر.","h2":"في West Virginia يجب أن تُبلغ DMV كتابيًا بعنوانك الجديد خلال 20 يومًا.","p":"صحيح. أبلغ DMV خلال 20 يومًا."},"ref":{"doc":"WV","page":6}},{"id":"wv-033","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what color is the driver's license or permit of a driver aged 15 to 17?","o":["Red","Blue","Green","Gold"],"h1":"It is the color of a stop sign.","h2":"In West Virginia drivers aged 15 to 17 get a vertical license or permit that is color-coded red.","p":"Correct. Ages 15 to 17 get a red card."},"es":{"q":"En Virginia Occidental, ¿de qué color es la licencia o el permiso de un conductor de 15 a 17 años?","o":["Rojo","Azul","Verde","Dorado"],"h1":"Es el color de una señal de alto.","h2":"En Virginia Occidental los conductores de 15 a 17 años reciben una licencia o un permiso vertical de color rojo.","p":"Correcto. De 15 a 17 años, la tarjeta es roja."},"zh":{"q":"在 West Virginia，15 到 17 岁司机的驾照或学习驾照是什么颜色？","o":["红色","蓝色","绿色","金色"],"h1":"它是停车标志的颜色。","h2":"在 West Virginia，15 到 17 岁的司机拿到的是竖版驾照或学习驾照，用红色标示。","p":"对。15 到 17 岁拿到的是红色的卡。"},"vi":{"q":"Ở West Virginia, bằng lái hoặc giấy phép tập lái của tài xế từ 15 đến 17 tuổi có màu gì?","o":["Đỏ","Xanh dương","Xanh lá","Vàng kim"],"h1":"Đó là màu của biển báo dừng.","h2":"Ở West Virginia, tài xế từ 15 đến 17 tuổi nhận bằng lái hoặc giấy phép tập lái dạng dọc, có mã màu đỏ.","p":"Đúng. Từ 15 đến 17 tuổi nhận thẻ màu đỏ."},"tl":{"q":"Sa West Virginia, anong kulay ang lisensya o permit ng drayber na edad 15 hanggang 17?","o":["Pula","Asul","Berde","Ginto"],"h1":"Ito ang kulay ng stop sign.","h2":"Sa West Virginia, ang mga drayber na edad 15 hanggang 17 ay binibigyan ng patayong lisensya o permit na may kulay pula.","p":"Tama. Pulang card ang para sa edad 15 hanggang 17."},"ar":{"q":"في West Virginia، ما لون رخصة القيادة أو التصريح للسائق الذي عمره من 15 إلى 17 سنة؟","o":["أحمر","أزرق","أخضر","ذهبي"],"h1":"إنه لون لافتة التوقف.","h2":"في West Virginia يحصل السائقون الذين أعمارهم من 15 إلى 17 سنة على رخصة أو تصريح عمودي مُميَّز باللون الأحمر.","p":"صحيح. الأعمار من 15 إلى 17 تحصل على بطاقة حمراء."},"ref":{"doc":"WV","page":7}},{"id":"wv-034","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, what vision do you need to pass the vision screening, with or without glasses?","o":["20/100 or better","20/70 or better","20/60 or better","20/40 or better"],"h1":"It is the best of these four numbers.","h2":"In West Virginia you need vision of 20/40 or better, with or without glasses or contact lenses, to pass the screening.","p":"Right. You need 20/40 or better."},"es":{"q":"En Virginia Occidental, ¿qué visión necesita para aprobar el examen de la vista, con o sin lentes?","o":["20/100 o mejor","20/70 o mejor","20/60 o mejor","20/40 o mejor"],"h1":"Es el mejor de estos cuatro números.","h2":"En Virginia Occidental usted necesita una visión de 20/40 o mejor, con o sin anteojos o lentes de contacto, para aprobar el examen.","p":"Correcto. Necesita 20/40 o mejor."},"zh":{"q":"在 West Virginia，戴或不戴眼镜，你的视力要达到多少才能通过视力检查？","o":["20/100 或更好","20/70 或更好","20/60 或更好","20/40 或更好"],"h1":"它是这四个数字里最好的一个。","h2":"在 West Virginia，无论戴不戴眼镜或隐形眼镜，你的视力都要达到 20/40 或更好，才能通过检查。","p":"对。你需要 20/40 或更好。"},"vi":{"q":"Ở West Virginia, bạn cần thị lực bao nhiêu để qua kiểm tra mắt, có hoặc không có kính?","o":["20/100 hoặc tốt hơn","20/70 hoặc tốt hơn","20/60 hoặc tốt hơn","20/40 hoặc tốt hơn"],"h1":"Đó là con số tốt nhất trong bốn con số này.","h2":"Ở West Virginia, bạn cần thị lực 20/40 hoặc tốt hơn, có hoặc không có kính hay kính áp tròng, để qua kiểm tra.","p":"Đúng. Bạn cần 20/40 hoặc tốt hơn."},"tl":{"q":"Sa West Virginia, anong linaw ng paningin ang kailangan mo para pumasa sa vision screening, may salamin man o wala?","o":["20/100 o mas mahusay","20/70 o mas mahusay","20/60 o mas mahusay","20/40 o mas mahusay"],"h1":"Ito ang pinakamahusay sa apat na numerong ito.","h2":"Sa West Virginia, kailangan mo ng paningin na 20/40 o mas mahusay, may salamin o contact lens man o wala, para pumasa sa screening.","p":"Tama. Kailangan mo ng 20/40 o mas mahusay."},"ar":{"q":"في West Virginia، ما قوة النظر التي تحتاجها لتنجح في فحص النظر، بالنظارة أو بدونها؟","o":["20/100 أو أفضل","20/70 أو أفضل","20/60 أو أفضل","20/40 أو أفضل"],"h1":"إنه أفضل رقم بين هذه الأرقام الأربعة.","h2":"في West Virginia تحتاج إلى نظر 20/40 أو أفضل، بالنظارة أو العدسات اللاصقة أو بدونها، لتنجح في الفحص.","p":"صحيح. تحتاج إلى 20/40 أو أفضل."},"ref":{"doc":"WV","page":24}},{"id":"wv-035","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, a Level 1 permit holder is convicted of two traffic offenses. What happens?","o":["Nothing, if the fines are paid","The permit is revoked for 90 days","The permit is suspended for 7 days","The holder must add 10 more practice hours"],"h1":"The permit is taken away for about three months.","h2":"In West Virginia two convictions on a Level 1 permit mean the permit is revoked for 90 days, and then you must apply and test again.","p":"Correct. Two convictions cost the permit for 90 days."},"es":{"q":"En Virginia Occidental, el titular de un permiso de Nivel 1 es condenado por dos infracciones de tránsito. ¿Qué pasa?","o":["Nada, si paga las multas","El permiso se revoca por 90 días","El permiso se suspende por 7 días","Debe sumar 10 horas más de práctica"],"h1":"Le quitan el permiso por unos tres meses.","h2":"En Virginia Occidental dos condenas con un permiso de Nivel 1 hacen que el permiso se revoque por 90 días, y luego debe solicitarlo y examinarse de nuevo.","p":"Correcto. Dos condenas le quitan el permiso por 90 días."},"zh":{"q":"在 West Virginia，一名第 1 级学习驾照持有人有两次交通违规被定罪。会怎样？","o":["只要交了罚款，就没事","学习驾照被吊销 90 天","学习驾照被暂停 7 天","持有人必须多练习 10 小时"],"h1":"学习驾照会被收走大约三个月。","h2":"在 West Virginia，第 1 级学习驾照有两次定罪，学习驾照会被吊销 90 天，之后你必须重新申请并重新考试。","p":"对。两次定罪会失去学习驾照 90 天。"},"vi":{"q":"Ở West Virginia, người có giấy phép tập lái Cấp 1 bị kết tội hai lần vi phạm giao thông. Điều gì xảy ra?","o":["Không có gì, nếu đã trả tiền phạt","Giấy phép bị thu hồi 90 ngày","Giấy phép bị đình chỉ 7 ngày","Người đó phải tập lái thêm 10 giờ"],"h1":"Giấy phép bị lấy đi khoảng ba tháng.","h2":"Ở West Virginia, hai lần bị kết tội khi có giấy phép Cấp 1 nghĩa là giấy phép bị thu hồi 90 ngày, sau đó bạn phải nộp đơn và thi lại.","p":"Đúng. Hai lần bị kết tội làm mất giấy phép 90 ngày."},"tl":{"q":"Sa West Virginia, nahatulan ang may hawak ng Level 1 na permit sa dalawang paglabag sa trapiko. Ano ang mangyayari?","o":["Wala, kung nabayaran ang mga multa","Babawiin ang permit nang 90 araw","Masususpinde ang permit nang 7 araw","Dapat magdagdag ang may hawak ng 10 pang oras ng pagsasanay"],"h1":"Kukunin ang permit nang mga tatlong buwan.","h2":"Sa West Virginia, ang dalawang conviction habang may Level 1 na permit ay nangangahulugang babawiin ang permit nang 90 araw, at pagkatapos ay dapat kang mag-apply at kumuha ulit ng pagsusulit.","p":"Tama. Ang dalawang conviction ay nagpapawala ng permit nang 90 araw."},"ar":{"q":"في West Virginia، أُدين حامل تصريح المستوى 1 بمخالفتين مروريتين. ماذا يحدث؟","o":["لا شيء، إذا دُفعت الغرامات","يُلغى التصريح لمدة 90 يومًا","يُعلَّق التصريح لمدة 7 أيام","يجب أن يضيف حامله 10 ساعات تدريب أخرى"],"h1":"يُسحب التصريح لمدة ثلاثة أشهر تقريبًا.","h2":"في West Virginia، إدانتان على تصريح المستوى 1 تعنيان أن التصريح يُلغى لمدة 90 يومًا، وبعد ذلك يجب أن تتقدّم بطلب وتُختبر من جديد.","p":"صحيح. إدانتان تُفقدانك التصريح لمدة 90 يومًا."},"ref":{"doc":"WV","page":11}},{"id":"wv-036","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what must a Level 2 driver do after a first traffic conviction?","o":["Pay a $1,000 fine","Give up the license for one year","Enroll in a driver improvement program","Take the vision test again"],"h1":"It is a program to help you drive better.","h2":"In West Virginia a Level 2 driver must enroll in a driver improvement program after the first conviction.","p":"Right. A first conviction means a driver improvement program."},"es":{"q":"En Virginia Occidental, ¿qué debe hacer un conductor de Nivel 2 después de su primera condena de tránsito?","o":["Pagar una multa de $1,000","Entregar la licencia por un año","Inscribirse en un programa de mejora para conductores","Repetir el examen de la vista"],"h1":"Es un programa para ayudarle a manejar mejor.","h2":"En Virginia Occidental un conductor de Nivel 2 debe inscribirse en un programa de mejora para conductores después de la primera condena.","p":"Correcto. La primera condena exige un programa de mejora."},"zh":{"q":"在 West Virginia，第 2 级驾照的司机第一次交通违规被定罪后，必须做什么？","o":["交 $1,000 罚款","交出驾照一年","参加驾驶改进课程","重新做视力检查"],"h1":"它是一个帮你开得更好的课程。","h2":"在 West Virginia，第 2 级驾照的司机第一次被定罪后，必须参加驾驶改进课程。","p":"对。第一次定罪就要参加驾驶改进课程。"},"vi":{"q":"Ở West Virginia, người có bằng lái Cấp 2 phải làm gì sau lần đầu bị kết tội vi phạm giao thông?","o":["Trả tiền phạt $1,000","Nộp lại bằng lái trong một năm","Ghi danh vào chương trình cải thiện kỹ năng lái xe","Kiểm tra mắt lại"],"h1":"Đó là một chương trình giúp bạn lái xe tốt hơn.","h2":"Ở West Virginia, người có bằng lái Cấp 2 phải ghi danh vào chương trình cải thiện kỹ năng lái xe sau lần đầu bị kết tội.","p":"Đúng. Lần đầu bị kết tội nghĩa là phải học chương trình cải thiện kỹ năng lái xe."},"tl":{"q":"Sa West Virginia, ano ang dapat gawin ng drayber na may Level 2 pagkatapos ng unang conviction sa trapiko?","o":["Magbayad ng $1,000 na multa","Isuko ang lisensya nang isang taon","Mag-enroll sa driver improvement program","Kumuha ulit ng vision test"],"h1":"Ito ay programang tutulong sa iyo na magmaneho nang mas mahusay.","h2":"Sa West Virginia, dapat mag-enroll sa driver improvement program ang drayber na may Level 2 pagkatapos ng unang conviction.","p":"Tama. Ang unang conviction ay nangangahulugang driver improvement program."},"ar":{"q":"في West Virginia، ماذا يجب أن يفعل سائق المستوى 2 بعد أول إدانة بمخالفة مرورية؟","o":["أن يدفع غرامة $1,000","أن يتخلّى عن الرخصة لمدة سنة واحدة","أن يلتحق ببرنامج تحسين القيادة","أن يعيد فحص النظر"],"h1":"إنه برنامج يساعدك على القيادة بشكل أفضل.","h2":"في West Virginia يجب أن يلتحق سائق المستوى 2 ببرنامج تحسين القيادة بعد أول إدانة.","p":"صحيح. أول إدانة تعني برنامج تحسين القيادة."},"ref":{"doc":"WV","page":11}},{"id":"wv-037","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, under the \"Drive for Five\" program, when does your driver's license expire?","o":["In a year when your age can be divided by five","Every year on January 1","Every ten years","On your 21st birthday only"],"h1":"Think of ages like 25, 30 and 35.","h2":"In West Virginia, under Drive for Five, your license expires in a year when your age can be divided by five, such as 25, 30 or 35.","p":"Correct. It expires at an age divisible by five."},"es":{"q":"En Virginia Occidental, con el programa \"Drive for Five\", ¿cuándo vence su licencia de conducir?","o":["En un año en que su edad se puede dividir entre cinco","Cada año el 1 de enero","Cada diez años","Solo al cumplir 21 años"],"h1":"Piense en edades como 25, 30 y 35.","h2":"En Virginia Occidental, con Drive for Five, su licencia vence en un año en que su edad se puede dividir entre cinco, como 25, 30 o 35.","p":"Correcto. Vence a una edad divisible entre cinco."},"zh":{"q":"在 West Virginia，按照 “Drive for Five” 计划，你的驾照什么时候到期？","o":["在你的年龄能被五整除的那一年","每年 1 月 1 日","每十年","只在你 21 岁生日那天"],"h1":"想想 25、30 和 35 这样的年龄。","h2":"在 West Virginia，按照 Drive for Five 计划，你的驾照在你的年龄能被五整除的那一年到期，比如 25、30 或 35 岁。","p":"对。驾照在能被五整除的年龄到期。"},"vi":{"q":"Ở West Virginia, theo chương trình \"Drive for Five\", khi nào bằng lái của bạn hết hạn?","o":["Vào năm tuổi của bạn chia hết cho năm","Mỗi năm vào ngày 1 tháng 1","Mỗi mười năm","Chỉ vào sinh nhật 21 tuổi của bạn"],"h1":"Hãy nghĩ đến các tuổi như 25, 30 và 35.","h2":"Ở West Virginia, theo chương trình Drive for Five, bằng lái của bạn hết hạn vào năm tuổi của bạn chia hết cho năm, ví dụ 25, 30 hoặc 35.","p":"Đúng. Bằng lái hết hạn ở tuổi chia hết cho năm."},"tl":{"q":"Sa West Virginia, sa ilalim ng programang \"Drive for Five\", kailan mag-e-expire ang iyong lisensya?","o":["Sa taon na ang iyong edad ay mahahati sa lima","Tuwing Enero 1 bawat taon","Bawat sampung taon","Sa iyong ika-21 kaarawan lamang"],"h1":"Isipin ang mga edad tulad ng 25, 30 at 35.","h2":"Sa West Virginia, sa ilalim ng Drive for Five, mag-e-expire ang iyong lisensya sa taon na ang iyong edad ay mahahati sa lima, tulad ng 25, 30 o 35.","p":"Tama. Nag-e-expire ito sa edad na mahahati sa lima."},"ar":{"q":"في West Virginia، وفق برنامج \"Drive for Five\"، متى تنتهي صلاحية رخصة قيادتك؟","o":["في السنة التي يقبل فيها عمرك القسمة على خمسة","كل سنة في 1 يناير","كل عشر سنوات","في عيد ميلادك الحادي والعشرين فقط"],"h1":"فكّر في أعمار مثل 25 و30 و35.","h2":"في West Virginia، وفق برنامج Drive for Five، تنتهي صلاحية رخصتك في السنة التي يقبل فيها عمرك القسمة على خمسة، مثل 25 أو 30 أو 35.","p":"صحيح. تنتهي في عمر يقبل القسمة على خمسة."},"ref":{"doc":"WV","page":12}},{"id":"wv-038","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, a crash injures a person. Within how many days must it be reported to the police?","o":["30 days","15 days","10 days","5 days"],"h1":"It is less than one week.","h2":"In West Virginia a crash with an injury, a death or more than $1,000 in damage must be reported to the police by the quickest means within 5 days.","p":"Right. Report it within 5 days."},"es":{"q":"En Virginia Occidental, un choque hiere a una persona. ¿En cuántos días se debe reportar a la policía?","o":["30 días","15 días","10 días","5 días"],"h1":"Es menos de una semana.","h2":"En Virginia Occidental un choque con heridos, muertos o más de $1,000 en daños se debe reportar a la policía por el medio más rápido en un plazo de 5 días.","p":"Correcto. Repórtelo en 5 días."},"zh":{"q":"在 West Virginia，一场车祸让一个人受了伤。必须在几天之内向警察报告？","o":["30 天","15 天","10 天","5 天"],"h1":"不到一个星期。","h2":"在 West Virginia，有人受伤、有人死亡或损失超过 $1,000 的车祸，必须用最快的方式在 5 天之内向警察报告。","p":"对。在 5 天之内报告。"},"vi":{"q":"Ở West Virginia, một vụ tai nạn làm một người bị thương. Phải báo cho cảnh sát trong vòng bao nhiêu ngày?","o":["30 ngày","15 ngày","10 ngày","5 ngày"],"h1":"Ít hơn một tuần.","h2":"Ở West Virginia, tai nạn có người bị thương, có người chết hoặc thiệt hại hơn $1,000 phải được báo cho cảnh sát bằng cách nhanh nhất trong vòng 5 ngày.","p":"Đúng. Báo trong vòng 5 ngày."},"tl":{"q":"Sa West Virginia, may nasaktang tao sa isang aksidente. Sa loob ng ilang araw ito dapat iulat sa pulis?","o":["30 araw","15 araw","10 araw","5 araw"],"h1":"Mas maikli ito sa isang linggo.","h2":"Sa West Virginia, ang aksidenteng may nasaktan, may namatay o may pinsalang higit sa $1,000 ay dapat iulat sa pulis sa pinakamabilis na paraan sa loob ng 5 araw.","p":"Tama. Iulat ito sa loob ng 5 araw."},"ar":{"q":"في West Virginia، أصاب حادث شخصًا بجروح. خلال كم يومًا يجب إبلاغ الشرطة به؟","o":["30 يومًا","15 يومًا","10 أيام","5 أيام"],"h1":"إنه أقل من أسبوع واحد.","h2":"في West Virginia يجب إبلاغ الشرطة بأسرع وسيلة خلال 5 أيام عن أي حادث فيه إصابة أو وفاة أو أضرار تزيد على $1,000.","p":"صحيح. أبلغ عنه خلال 5 أيام."},"ref":{"doc":"WV","page":16}},{"id":"wv-039","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the fine for a first offense of using a phone that is not hands-free while driving?","o":["$25","$100","$500","$1,000"],"h1":"The second offense is $200.","h2":"In West Virginia a first offense for using a phone that is not hands-free while driving is a $100 fine with no points.","p":"Correct. The first offense is $100."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa por la primera vez que usa un teléfono que no es de manos libres mientras maneja?","o":["$25","$100","$500","$1,000"],"h1":"La segunda vez son $200.","h2":"En Virginia Occidental la primera infracción por usar un teléfono que no es de manos libres mientras maneja es una multa de $100 sin puntos.","p":"Correcto. La primera infracción es de $100."},"zh":{"q":"在 West Virginia，开车时使用非免提手机，第一次违规罚款多少？","o":["$25","$100","$500","$1,000"],"h1":"第二次违规罚 $200。","h2":"在 West Virginia，开车时使用非免提手机，第一次违规罚款 $100，不扣分。","p":"对。第一次违规罚 $100。"},"vi":{"q":"Ở West Virginia, tiền phạt lần đầu cho việc dùng điện thoại không rảnh tay khi lái xe là bao nhiêu?","o":["$25","$100","$500","$1,000"],"h1":"Lần vi phạm thứ hai là $200.","h2":"Ở West Virginia, lần đầu dùng điện thoại không rảnh tay khi lái xe bị phạt $100 và không bị tính điểm.","p":"Đúng. Lần đầu bị phạt $100."},"tl":{"q":"Sa West Virginia, magkano ang multa sa unang paglabag ng paggamit ng teleponong hindi hands-free habang nagmamaneho?","o":["$25","$100","$500","$1,000"],"h1":"$200 ang ikalawang paglabag.","h2":"Sa West Virginia, ang unang paglabag ng paggamit ng teleponong hindi hands-free habang nagmamaneho ay may multang $100 at walang puntos.","p":"Tama. $100 ang unang paglabag."},"ar":{"q":"في West Virginia، ما غرامة المخالفة الأولى لاستخدام هاتف غير حرّ اليدين (hands-free) أثناء القيادة؟","o":["$25","$100","$500","$1,000"],"h1":"المخالفة الثانية $200.","h2":"في West Virginia، المخالفة الأولى لاستخدام هاتف غير حرّ اليدين أثناء القيادة غرامتها $100 بدون نقاط.","p":"صحيح. المخالفة الأولى $100."},"ref":{"doc":"WV","page":17}},{"id":"wv-040","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how long do points stay on your driving record?","o":["Six months","One year","Two years","Ten years"],"h1":"It is more than one year.","h2":"In West Virginia points stay on your driving record for two years from the date of the conviction.","p":"Right. Points stay for two years."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo permanecen los puntos en su historial de manejo?","o":["Seis meses","Un año","Dos años","Diez años"],"h1":"Es más de un año.","h2":"En Virginia Occidental los puntos permanecen en su historial de manejo por dos años desde la fecha de la condena.","p":"Correcto. Los puntos duran dos años."},"zh":{"q":"在 West Virginia，扣分会在你的驾驶记录上保留多久？","o":["六个月","一年","两年","十年"],"h1":"超过一年。","h2":"在 West Virginia，扣分从定罪那天起会在你的驾驶记录上保留两年。","p":"对。扣分保留两年。"},"vi":{"q":"Ở West Virginia, điểm phạt ở lại trong hồ sơ lái xe của bạn bao lâu?","o":["Sáu tháng","Một năm","Hai năm","Mười năm"],"h1":"Lâu hơn một năm.","h2":"Ở West Virginia, điểm phạt ở lại trong hồ sơ lái xe của bạn hai năm kể từ ngày bị kết tội.","p":"Đúng. Điểm phạt ở lại hai năm."},"tl":{"q":"Sa West Virginia, gaano katagal mananatili ang mga puntos sa iyong driving record?","o":["Anim na buwan","Isang taon","Dalawang taon","Sampung taon"],"h1":"Mas mahaba ito sa isang taon.","h2":"Sa West Virginia, mananatili ang mga puntos sa iyong driving record nang dalawang taon mula sa petsa ng conviction.","p":"Tama. Mananatili ang mga puntos nang dalawang taon."},"ar":{"q":"في West Virginia، كم من الوقت تبقى النقاط في سجل قيادتك؟","o":["ستة أشهر","سنة واحدة","سنتين","عشر سنوات"],"h1":"إنها أكثر من سنة واحدة.","h2":"في West Virginia تبقى النقاط في سجل قيادتك لمدة سنتين من تاريخ الإدانة.","p":"صحيح. تبقى النقاط لمدة سنتين."},"ref":{"doc":"WV","page":18}},{"id":"wv-041","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what does the DMV do when you have 6 or more points on your record?","o":["It sends you a letter of caution","It takes your license for one year","It makes you retake the road test","Nothing, until you reach 20 points"],"h1":"It is a warning, not a penalty yet.","h2":"In West Virginia, when you have 6 or more points, the DMV sends you a letter of caution asking you to drive carefully.","p":"Correct. At 6 points you get a letter of caution."},"es":{"q":"En Virginia Occidental, ¿qué hace el DMV cuando usted tiene 6 puntos o más en su historial?","o":["Le envía una carta de advertencia","Le quita la licencia por un año","Le hace repetir el examen de manejo","Nada, hasta que llegue a 20 puntos"],"h1":"Es un aviso, todavía no un castigo.","h2":"En Virginia Occidental, cuando usted tiene 6 puntos o más, el DMV le envía una carta de advertencia pidiéndole que maneje con cuidado.","p":"Correcto. Con 6 puntos recibe una carta de advertencia."},"zh":{"q":"在 West Virginia，当你的记录上有 6 分或更多时，DMV 会怎么做？","o":["给你寄一封警告信","收走你的驾照一年","让你重考路考","什么都不做，直到你有 20 分"],"h1":"这是一个警告，还不是处罚。","h2":"在 West Virginia，当你有 6 分或更多时，DMV 会给你寄一封警告信，提醒你小心开车。","p":"对。到 6 分你会收到一封警告信。"},"vi":{"q":"Ở West Virginia, DMV làm gì khi bạn có 6 điểm trở lên trong hồ sơ?","o":["Gửi cho bạn một thư cảnh báo","Lấy bằng lái của bạn một năm","Bắt bạn thi lái xe trên đường lại","Không làm gì cho đến khi bạn có 20 điểm"],"h1":"Đó là lời cảnh báo, chưa phải hình phạt.","h2":"Ở West Virginia, khi bạn có 6 điểm trở lên, DMV gửi cho bạn một thư cảnh báo, nhắc bạn lái xe cẩn thận.","p":"Đúng. Khi có 6 điểm, bạn nhận được thư cảnh báo."},"tl":{"q":"Sa West Virginia, ano ang ginagawa ng DMV kapag may 6 o higit pang puntos ka sa iyong rekord?","o":["Nagpapadala ito sa iyo ng sulat ng babala","Kinukuha nito ang iyong lisensya nang isang taon","Pinapaulit nito sa iyo ang road test","Wala, hanggang umabot ka sa 20 puntos"],"h1":"Babala ito, hindi pa parusa.","h2":"Sa West Virginia, kapag may 6 o higit pang puntos ka, nagpapadala ang DMV ng sulat ng babala na humihiling na mag-ingat ka sa pagmamaneho.","p":"Tama. Sa 6 na puntos, makakatanggap ka ng sulat ng babala."},"ar":{"q":"في West Virginia، ماذا تفعل DMV عندما يكون في سجلك 6 نقاط أو أكثر؟","o":["ترسل إليك رسالة تحذير","تسحب رخصتك لمدة سنة واحدة","تجعلك تعيد اختبار القيادة على الطريق","لا شيء، حتى تصل إلى 20 نقطة"],"h1":"إنه تحذير، وليس عقوبة بعد.","h2":"في West Virginia، عندما يكون لديك 6 نقاط أو أكثر، ترسل إليك DMV رسالة تحذير تطلب منك أن تقود بحذر.","p":"صحيح. عند 6 نقاط تصلك رسالة تحذير."},"ref":{"doc":"WV","page":18}},{"id":"wv-042","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, how many points are added to your record for speeding in a school zone?","o":["2 points","3 points","4 points","6 points"],"h1":"It is one of the highest point values, the same as reckless driving.","h2":"In West Virginia speeding in a school zone adds 6 points to your driving record.","p":"Right. Speeding in a school zone is 6 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos se suman a su historial por exceso de velocidad en una zona escolar?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Es uno de los valores más altos, igual que manejar de forma imprudente.","h2":"En Virginia Occidental el exceso de velocidad en una zona escolar suma 6 puntos a su historial de manejo.","p":"Correcto. Son 6 puntos."},"zh":{"q":"在 West Virginia，在学校区域超速会在你的记录上加几分？","o":["2 分","3 分","4 分","6 分"],"h1":"它是最高的分数之一，和鲁莽驾驶一样。","h2":"在 West Virginia，在学校区域超速会在你的驾驶记录上加 6 分。","p":"对。在学校区域超速是 6 分。"},"vi":{"q":"Ở West Virginia, chạy quá tốc độ trong khu vực trường học bị cộng bao nhiêu điểm vào hồ sơ của bạn?","o":["2 điểm","3 điểm","4 điểm","6 điểm"],"h1":"Đó là một trong những mức điểm cao nhất, bằng với lái xe liều lĩnh.","h2":"Ở West Virginia, chạy quá tốc độ trong khu vực trường học bị cộng 6 điểm vào hồ sơ lái xe của bạn.","p":"Đúng. Chạy quá tốc độ trong khu vực trường học là 6 điểm."},"tl":{"q":"Sa West Virginia, ilang puntos ang idinadagdag sa iyong rekord dahil sa pag-overspeed sa school zone?","o":["2 puntos","3 puntos","4 puntos","6 puntos"],"h1":"Isa ito sa pinakamataas na puntos, kapareho ng reckless driving.","h2":"Sa West Virginia, ang pag-overspeed sa school zone ay nagdadagdag ng 6 na puntos sa iyong driving record.","p":"Tama. 6 na puntos ang pag-overspeed sa school zone."},"ar":{"q":"في West Virginia، كم نقطة تُضاف إلى سجلك بسبب تجاوز السرعة في منطقة مدرسة؟","o":["نقطتان","3 نقاط","4 نقاط","6 نقاط"],"h1":"إنها من أعلى قيم النقاط، مثل القيادة المتهوّرة.","h2":"في West Virginia، تجاوز السرعة في منطقة مدرسة يضيف 6 نقاط إلى سجل قيادتك.","p":"صحيح. تجاوز السرعة في منطقة مدرسة 6 نقاط."},"ref":{"doc":"WV","page":20}},{"id":"wv-043","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, a driver under 21 is caught driving with any measurable alcohol for the first time. What is the minimum license revocation?","o":["7 days","30 days","6 months","2 years"],"h1":"It is about one month.","h2":"In West Virginia a first zero-tolerance offense by a driver under 21 brings a license revocation of at least 30 days.","p":"Correct. The minimum is 30 days."},"es":{"q":"En Virginia Occidental, un conductor menor de 21 años maneja con cualquier cantidad medible de alcohol por primera vez. ¿Cuál es la revocación mínima de la licencia?","o":["7 días","30 días","6 meses","2 años"],"h1":"Es más o menos un mes.","h2":"En Virginia Occidental la primera infracción de tolerancia cero de un conductor menor de 21 años trae una revocación de la licencia de al menos 30 días.","p":"Correcto. El mínimo es de 30 días."},"zh":{"q":"在 West Virginia，一名未满 21 岁的司机第一次被发现开车时体内有任何可测量的酒精。驾照最少被吊销多久？","o":["7 天","30 天","6 个月","2 年"],"h1":"大约一个月。","h2":"在 West Virginia，未满 21 岁的司机第一次违反零容忍规定，驾照会被吊销至少 30 天。","p":"对。最少是 30 天。"},"vi":{"q":"Ở West Virginia, tài xế dưới 21 tuổi bị phát hiện lái xe có bất kỳ lượng cồn đo được nào lần đầu. Thời gian thu hồi bằng lái tối thiểu là bao lâu?","o":["7 ngày","30 ngày","6 tháng","2 năm"],"h1":"Khoảng một tháng.","h2":"Ở West Virginia, lần vi phạm đầu tiên về quy định không dung thứ của tài xế dưới 21 tuổi bị thu hồi bằng lái ít nhất 30 ngày.","p":"Đúng. Tối thiểu là 30 ngày."},"tl":{"q":"Sa West Virginia, nahuli sa unang pagkakataon ang drayber na wala pang 21 na nagmamaneho nang may kahit anong nasusukat na alak. Ano ang pinakamaikling pagbawi ng lisensya?","o":["7 araw","30 araw","6 na buwan","2 taon"],"h1":"Mga isang buwan ito.","h2":"Sa West Virginia, ang unang zero-tolerance na paglabag ng drayber na wala pang 21 ay may pagbawi ng lisensya nang hindi bababa sa 30 araw.","p":"Tama. 30 araw ang pinakamaikli."},"ar":{"q":"في West Virginia، ضُبط سائق عمره أقل من 21 سنة لأول مرة وهو يقود مع أي كمية كحول يمكن قياسها. ما أقل مدة لإلغاء الرخصة؟","o":["7 أيام","30 يومًا","6 أشهر","سنتان"],"h1":"إنها شهر واحد تقريبًا.","h2":"في West Virginia، أول مخالفة لقاعدة عدم التسامح (zero tolerance) من سائق عمره أقل من 21 سنة تؤدي إلى إلغاء الرخصة لمدة 30 يومًا على الأقل.","p":"صحيح. الحد الأدنى 30 يومًا."},"ref":{"doc":"WV","page":22}},{"id":"wv-044","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, when must a driver take part in the Interlock Program?","o":["After any speeding ticket","After one parking ticket","After two or more DUI revocations within ten years","Only if the driver is under 18"],"h1":"It is for repeat drunk driving within a set number of years.","h2":"In West Virginia the Interlock Program is required for a driver revoked for two or more DUIs or related offenses within ten years.","p":"Right. Two or more DUIs in ten years make it required."},"es":{"q":"En Virginia Occidental, ¿cuándo debe un conductor participar en el programa de Interlock?","o":["Después de cualquier multa por velocidad","Después de una multa de estacionamiento","Después de dos o más revocaciones por DUI en diez años","Solo si el conductor es menor de 18 años"],"h1":"Es para quien repite manejar ebrio en cierto número de años.","h2":"En Virginia Occidental el programa de Interlock es obligatorio para un conductor revocado por dos o más DUI u ofensas relacionadas en diez años.","p":"Correcto. Dos o más DUI en diez años lo hacen obligatorio."},"zh":{"q":"在 West Virginia，司机在什么情况下必须参加点火联锁计划（Interlock Program）？","o":["任何超速罚单之后","一张停车罚单之后","十年内因酒后驾驶（DUI）被吊销驾照两次或更多之后","只有司机未满 18 岁时"],"h1":"它是针对在一定年数内多次酒后驾驶的。","h2":"在 West Virginia，十年内因两次或更多酒后驾驶（DUI）或相关违法被吊销驾照的司机，必须参加点火联锁计划。","p":"对。十年内两次或更多 DUI 就必须参加。"},"vi":{"q":"Ở West Virginia, khi nào tài xế phải tham gia Chương trình Khóa liên động (Interlock Program)?","o":["Sau bất kỳ vé phạt chạy quá tốc độ nào","Sau một vé phạt đậu xe","Sau hai lần trở lên bị thu hồi bằng lái vì lái xe khi say (DUI) trong vòng mười năm","Chỉ khi tài xế dưới 18 tuổi"],"h1":"Đó là dành cho việc lái xe khi say nhiều lần trong một số năm nhất định.","h2":"Ở West Virginia, tài xế bị thu hồi bằng lái vì hai lần DUI trở lên hoặc vi phạm liên quan trong vòng mười năm bắt buộc phải tham gia Chương trình Khóa liên động.","p":"Đúng. Hai lần DUI trở lên trong mười năm thì bắt buộc tham gia."},"tl":{"q":"Sa West Virginia, kailan dapat sumali ang drayber sa Interlock Program?","o":["Pagkatapos ng kahit anong tiket sa pag-overspeed","Pagkatapos ng isang tiket sa pagparada","Pagkatapos ng dalawa o higit pang pagbawi dahil sa DUI sa loob ng sampung taon","Kung wala pang 18 ang drayber lamang"],"h1":"Ito ay para sa paulit-ulit na lasing na pagmamaneho sa loob ng tiyak na bilang ng taon.","h2":"Sa West Virginia, kailangang sumali sa Interlock Program ang drayber na binawian ng lisensya dahil sa dalawa o higit pang DUI o kaugnay na paglabag sa loob ng sampung taon.","p":"Tama. Ang dalawa o higit pang DUI sa loob ng sampung taon ay nagpapasali rito nang sapilitan."},"ar":{"q":"في West Virginia، متى يجب أن يشارك السائق في برنامج قفل الإشعال (Interlock Program)؟","o":["بعد أي مخالفة سرعة","بعد مخالفة وقوف واحدة","بعد إلغاء الرخصة مرتين أو أكثر بسبب القيادة تحت التأثير (DUI) خلال عشر سنوات","فقط إذا كان عمر السائق أقل من 18 سنة"],"h1":"إنه لمن يكرّر القيادة وهو سكران خلال عدد معيّن من السنوات.","h2":"في West Virginia يكون برنامج قفل الإشعال إلزاميًا للسائق الذي أُلغيت رخصته بسبب قيادتين أو أكثر تحت التأثير (DUI) أو مخالفات مرتبطة بها خلال عشر سنوات.","p":"صحيح. مرتان أو أكثر من DUI خلال عشر سنوات تجعل البرنامج إلزاميًا."},"ref":{"doc":"WV","page":23}},{"id":"wv-045","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, who may legally ride in a passenger vehicle without a seat belt?","o":["A person 18 or older in the back seat","Any passenger in the front seat","A child under 8 in the back seat","Anyone on a short trip"],"h1":"It is an adult, and not in the front.","h2":"In West Virginia everyone must wear a seat belt, except a person 18 or older riding in the back seat.","p":"Correct. Only adults 18 or older in the back seat are exempt."},"es":{"q":"En Virginia Occidental, ¿quién puede viajar legalmente sin cinturón de seguridad en un vehículo de pasajeros?","o":["Una persona de 18 años o más en el asiento trasero","Cualquier pasajero en el asiento delantero","Un niño menor de 8 años en el asiento trasero","Cualquiera en un viaje corto"],"h1":"Es un adulto, y no va adelante.","h2":"En Virginia Occidental todos deben usar el cinturón de seguridad, menos una persona de 18 años o más que viaja en el asiento trasero.","p":"Correcto. Solo los adultos de 18 años o más en el asiento trasero están exentos."},"zh":{"q":"在 West Virginia，谁可以合法地在乘用车里不系安全带？","o":["坐在后座、18 岁或以上的人","前座的任何乘客","坐在后座、未满 8 岁的孩子","短途出行的任何人"],"h1":"是成年人，而且不坐在前面。","h2":"在 West Virginia，每个人都必须系安全带，只有坐在后座、18 岁或以上的人除外。","p":"对。只有坐在后座、18 岁或以上的成年人可以例外。"},"vi":{"q":"Ở West Virginia, ai được phép ngồi trong xe chở khách mà không thắt dây an toàn?","o":["Người từ 18 tuổi trở lên ngồi ở ghế sau","Bất kỳ hành khách nào ở ghế trước","Trẻ em dưới 8 tuổi ở ghế sau","Bất kỳ ai đi quãng đường ngắn"],"h1":"Đó là người lớn, và không ngồi phía trước.","h2":"Ở West Virginia, mọi người đều phải thắt dây an toàn, trừ người từ 18 tuổi trở lên ngồi ở ghế sau.","p":"Đúng. Chỉ người lớn từ 18 tuổi trở lên ngồi ở ghế sau được miễn."},"tl":{"q":"Sa West Virginia, sino ang legal na puwedeng sumakay sa pampasaherong sasakyan nang walang seat belt?","o":["Taong 18 o higit pa na nasa upuan sa likod","Kahit sinong pasahero sa upuan sa harap","Batang wala pang 8 na nasa upuan sa likod","Kahit sino sa maikling biyahe"],"h1":"Adulto ito, at wala sa harap.","h2":"Sa West Virginia, dapat mag-seat belt ang lahat, maliban sa taong 18 o higit pa na nakasakay sa upuan sa likod.","p":"Tama. Ang mga adultong 18 o higit pa sa upuan sa likod lamang ang exempted."},"ar":{"q":"في West Virginia، من يجوز له قانونيًا الركوب في سيارة ركّاب دون حزام أمان؟","o":["شخص عمره 18 سنة أو أكثر في المقعد الخلفي","أي راكب في المقعد الأمامي","طفل عمره أقل من 8 سنوات في المقعد الخلفي","أي شخص في رحلة قصيرة"],"h1":"إنه شخص بالغ، وليس في الأمام.","h2":"في West Virginia يجب على الجميع ربط حزام الأمان، إلا الشخص الذي عمره 18 سنة أو أكثر ويركب في المقعد الخلفي.","p":"صحيح. فقط البالغون بعمر 18 سنة أو أكثر في المقعد الخلفي مُعفَون."},"ref":{"doc":"WV","page":67}},{"id":"wv-046","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, window tint is illegal if it lets through less than what amount of light?","o":["5 percent","10 percent","20 percent","35 percent"],"h1":"It is about one third.","h2":"In West Virginia windows tinted to let through less than 35 percent of light are illegal equipment.","p":"Right. Less than 35 percent is illegal."},"es":{"q":"En Virginia Occidental, el polarizado de las ventanas es ilegal si deja pasar menos de ¿qué cantidad de luz?","o":["5 por ciento","10 por ciento","20 por ciento","35 por ciento"],"h1":"Es más o menos un tercio.","h2":"En Virginia Occidental las ventanas polarizadas que dejan pasar menos del 35 por ciento de la luz son equipo ilegal.","p":"Correcto. Menos del 35 por ciento es ilegal."},"zh":{"q":"在 West Virginia，车窗贴膜如果透光量低于多少就是违法的？","o":["5%","10%","20%","35%"],"h1":"大约三分之一。","h2":"在 West Virginia，透光量低于 35% 的车窗贴膜属于违法装备。","p":"对。低于 35% 是违法的。"},"vi":{"q":"Ở West Virginia, phim dán kính xe là bất hợp pháp nếu cho ánh sáng đi qua ít hơn bao nhiêu?","o":["5 phần trăm","10 phần trăm","20 phần trăm","35 phần trăm"],"h1":"Khoảng một phần ba.","h2":"Ở West Virginia, kính xe dán phim cho ánh sáng đi qua ít hơn 35 phần trăm là thiết bị bất hợp pháp.","p":"Đúng. Ít hơn 35 phần trăm là bất hợp pháp."},"tl":{"q":"Sa West Virginia, ilegal ang tint ng bintana kung nagpapadaan ito ng liwanag na mas mababa sa anong dami?","o":["5 porsiyento","10 porsiyento","20 porsiyento","35 porsiyento"],"h1":"Mga isang-katlo ito.","h2":"Sa West Virginia, ilegal na kagamitan ang mga bintanang may tint na nagpapadaan ng liwanag na mas mababa sa 35 porsiyento.","p":"Tama. Ilegal ang mas mababa sa 35 porsiyento."},"ar":{"q":"في West Virginia، يكون تظليل النوافذ غير قانوني إذا سمح بمرور ضوء أقل من أي نسبة؟","o":["5 بالمئة","10 بالمئة","20 بالمئة","35 بالمئة"],"h1":"إنها الثلث تقريبًا.","h2":"في West Virginia، النوافذ المظلّلة التي تسمح بمرور أقل من 35 بالمئة من الضوء تُعدّ تجهيزات غير قانونية.","p":"صحيح. أقل من 35 بالمئة غير قانوني."},"ref":{"doc":"WV","page":25}},{"id":"wv-047","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In West Virginia, what is the highest speed allowed on an interstate unless another limit is posted?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"It is 15 mph more than on an open country highway.","h2":"In West Virginia the speed limit on an interstate is 70 mph unless a different limit is posted.","p":"Correct. The interstate limit is 70 mph."},"es":{"q":"En Virginia Occidental, ¿cuál es la velocidad máxima en una autopista interestatal si no hay otro límite señalado?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Son 15 mph más que en una carretera abierta del condado.","h2":"En Virginia Occidental el límite de velocidad en una autopista interestatal es de 70 mph, a menos que se señale otro límite.","p":"Correcto. El límite en la interestatal es de 70 mph."},"zh":{"q":"在 West Virginia，如果没有标示其他限速，州际公路上允许的最高速度是多少？","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"它比开阔乡村公路多 15 mph。","h2":"在 West Virginia，除非标示了不同的限速，州际公路的限速是 70 mph。","p":"对。州际公路限速是 70 mph。"},"vi":{"q":"Ở West Virginia, tốc độ cao nhất được phép trên đường liên tiểu bang (interstate) là bao nhiêu, nếu không có biển báo giới hạn khác?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Cao hơn 15 mph so với đường quốc lộ vùng nông thôn thoáng.","h2":"Ở West Virginia, tốc độ giới hạn trên đường liên tiểu bang là 70 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Giới hạn trên đường liên tiểu bang là 70 mph."},"tl":{"q":"Sa West Virginia, ano ang pinakamataas na bilis na pinapayagan sa interstate, maliban kung may ibang limit na nakapaskil?","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"Mas mataas ito nang 15 mph kaysa sa bukas na highway sa probinsya.","h2":"Sa West Virginia, ang speed limit sa interstate ay 70 mph maliban kung may ibang limit na nakapaskil.","p":"Tama. 70 mph ang limit sa interstate."},"ar":{"q":"في West Virginia، ما أعلى سرعة مسموح بها على الطريق السريع بين الولايات (interstate) ما لم تُوضع لافتة بحد آخر؟","o":["65 mph","70 mph","75 mph","80 mph"],"h1":"إنها أكثر بـ 15 mph من الطريق الريفي المفتوح.","h2":"في West Virginia حد السرعة على الطريق السريع بين الولايات هو 70 mph ما لم تُوضع لافتة بحد مختلف.","p":"صحيح. حد الطريق السريع بين الولايات 70 mph."},"ref":{"doc":"WV","page":42}},{"id":"wv-048","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, a school zone includes the street next to the school grounds for how far?","o":["25 feet","50 feet","125 feet","500 feet"],"h1":"It is more than 100 feet.","h2":"In West Virginia a school zone includes any street next to the school grounds for 125 feet from the grounds.","p":"Right. The zone reaches 125 feet."},"es":{"q":"En Virginia Occidental, ¿hasta qué distancia de la escuela incluye la zona escolar la calle junto al terreno escolar?","o":["25 pies","50 pies","125 pies","500 pies"],"h1":"Es más de 100 pies.","h2":"En Virginia Occidental una zona escolar incluye cualquier calle junto al terreno de la escuela hasta 125 pies desde el terreno.","p":"Correcto. La zona llega a 125 pies."},"zh":{"q":"在 West Virginia，学校区域包括紧挨着校园的街道，范围有多远？","o":["25 英尺","50 英尺","125 英尺","500 英尺"],"h1":"超过 100 英尺。","h2":"在 West Virginia，学校区域包括紧挨着校园的任何街道，从校园算起 125 英尺以内。","p":"对。学校区域延伸到 125 英尺。"},"vi":{"q":"Ở West Virginia, khu vực trường học bao gồm đoạn đường cạnh khuôn viên trường dài bao xa?","o":["25 feet","50 feet","125 feet","500 feet"],"h1":"Hơn 100 feet.","h2":"Ở West Virginia, khu vực trường học bao gồm bất kỳ con đường nào cạnh khuôn viên trường, trong phạm vi 125 feet tính từ khuôn viên.","p":"Đúng. Khu vực kéo dài đến 125 feet."},"tl":{"q":"Sa West Virginia, gaano kalayo ang saklaw ng school zone sa kalyeng katabi ng paaralan?","o":["25 feet","50 feet","125 feet","500 feet"],"h1":"Higit ito sa 100 feet.","h2":"Sa West Virginia, saklaw ng school zone ang anumang kalyeng katabi ng paaralan hanggang 125 feet mula sa bakuran nito.","p":"Tama. Umaabot ang zone nang 125 feet."},"ar":{"q":"في West Virginia، إلى أي مسافة تشمل منطقة المدرسة الشارع المجاور لأرض المدرسة؟","o":["25 قدمًا","50 قدمًا","125 قدمًا","500 قدم"],"h1":"إنها أكثر من 100 قدم.","h2":"في West Virginia تشمل منطقة المدرسة أي شارع مجاور لأرض المدرسة لمسافة 125 قدمًا من أرض المدرسة.","p":"صحيح. تمتد المنطقة إلى 125 قدمًا."},"ref":{"doc":"WV","page":42}},{"id":"wv-049","scope":"WV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In West Virginia, you may not park within how many feet of a mailbox served by a mail carrier in a vehicle?","o":["20 feet","5 feet","50 feet","100 feet"],"h1":"The carrier needs room to pull up to the box.","h2":"In West Virginia you may not park within 20 feet of a mailbox that a carrier serves from a motor vehicle.","p":"Correct. Stay 20 feet from the mailbox."},"es":{"q":"En Virginia Occidental, ¿a menos de cuántos pies de un buzón que el cartero atiende desde un vehículo no se puede estacionar?","o":["20 pies","5 pies","50 pies","100 pies"],"h1":"El cartero necesita espacio para acercarse al buzón.","h2":"En Virginia Occidental usted no puede estacionarse a menos de 20 pies de un buzón que un cartero atiende desde un vehículo motorizado.","p":"Correcto. Quédese a 20 pies del buzón."},"zh":{"q":"在 West Virginia，邮递员开车送信的邮箱，你不可以在离它多少英尺以内停车？","o":["20 英尺","5 英尺","50 英尺","100 英尺"],"h1":"邮递员需要空间把车开到邮箱旁边。","h2":"在 West Virginia，邮递员开车送信的邮箱，你不可以在离它 20 英尺以内停车。","p":"对。离邮箱 20 英尺以外停车。"},"vi":{"q":"Ở West Virginia, bạn không được đậu xe trong phạm vi bao nhiêu feet từ hộp thư mà người đưa thư phục vụ bằng xe?","o":["20 feet","5 feet","50 feet","100 feet"],"h1":"Người đưa thư cần chỗ để chạy xe đến sát hộp thư.","h2":"Ở West Virginia, bạn không được đậu xe trong phạm vi 20 feet từ hộp thư mà người đưa thư phục vụ bằng xe cơ giới.","p":"Đúng. Đậu xe cách hộp thư 20 feet."},"tl":{"q":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng ilang talampakan (feet) mula sa mailbox na sinisilbihan ng kartero na nakasasakyan?","o":["20 feet","5 feet","50 feet","100 feet"],"h1":"Kailangan ng kartero ng lugar para makalapit sa mailbox.","h2":"Sa West Virginia, hindi ka puwedeng pumarada sa loob ng 20 feet mula sa mailbox na sinisilbihan ng kartero mula sa sasakyan.","p":"Tama. Lumayo nang 20 feet sa mailbox."},"ar":{"q":"في West Virginia، لا يجوز لك أن تركن سيارتك ضمن كم قدمًا من صندوق بريد يخدمه ساعي بريد بسيارة؟","o":["20 قدمًا","5 أقدام","50 قدمًا","100 قدم"],"h1":"يحتاج ساعي البريد إلى مكان ليقترب بسيارته من الصندوق.","h2":"في West Virginia لا يجوز لك أن تركن سيارتك ضمن 20 قدمًا من صندوق بريد يخدمه ساعي البريد من سيارة.","p":"صحيح. ابقَ على بُعد 20 قدمًا من صندوق البريد."},"ref":{"doc":"WV","page":46}},{"id":"wv-050","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, what is the minimum license penalty for a first offense of passing a stopped school bus?","o":["A warning letter only","2 points","A 7-day suspension","A 60-day suspension"],"h1":"It is about two months.","h2":"In West Virginia passing a stopped school bus is punished, for a first offense, by a license suspension of at least 60 days.","p":"Right. At least 60 days of suspension."},"es":{"q":"En Virginia Occidental, ¿cuál es la sanción mínima a la licencia por rebasar un autobús escolar detenido por primera vez?","o":["Solo una carta de advertencia","2 puntos","Una suspensión de 7 días","Una suspensión de 60 días"],"h1":"Son unos dos meses.","h2":"En Virginia Occidental rebasar un autobús escolar detenido se castiga, la primera vez, con una suspensión de la licencia de al menos 60 días.","p":"Correcto. Al menos 60 días de suspensión."},"zh":{"q":"在 West Virginia，第一次超越停着的校车，对驾照最轻的处罚是什么？","o":["只有一封警告信","扣 2 分","暂停 7 天","暂停 60 天"],"h1":"大约两个月。","h2":"在 West Virginia，第一次超越停着的校车，处罚是暂停驾照至少 60 天。","p":"对。至少暂停 60 天。"},"vi":{"q":"Ở West Virginia, hình phạt tối thiểu đối với bằng lái cho lần đầu vượt xe buýt trường học đang dừng là gì?","o":["Chỉ một thư cảnh báo","2 điểm","Đình chỉ 7 ngày","Đình chỉ 60 ngày"],"h1":"Khoảng hai tháng.","h2":"Ở West Virginia, lần đầu vượt xe buýt trường học đang dừng bị phạt đình chỉ bằng lái ít nhất 60 ngày.","p":"Đúng. Đình chỉ ít nhất 60 ngày."},"tl":{"q":"Sa West Virginia, ano ang pinakamababang parusa sa lisensya sa unang paglabag ng paglampas sa nakahintong school bus?","o":["Sulat ng babala lamang","2 puntos","7-araw na suspensyon","60-araw na suspensyon"],"h1":"Mga dalawang buwan ito.","h2":"Sa West Virginia, ang unang paglabag ng paglampas sa nakahintong school bus ay pinaparusahan ng suspensyon ng lisensya nang hindi bababa sa 60 araw.","p":"Tama. Hindi bababa sa 60 araw na suspensyon."},"ar":{"q":"في West Virginia، ما أقل عقوبة على الرخصة لأول مخالفة تجاوز حافلة مدرسية متوقفة؟","o":["رسالة تحذير فقط","نقطتان","تعليق لمدة 7 أيام","تعليق لمدة 60 يومًا"],"h1":"إنها شهران تقريبًا.","h2":"في West Virginia، عقوبة أول مخالفة لتجاوز حافلة مدرسية متوقفة هي تعليق الرخصة لمدة 60 يومًا على الأقل.","p":"صحيح. تعليق لمدة 60 يومًا على الأقل."},"ref":{"doc":"WV","page":50}},{"id":"wv-051","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, a visitor who lives in another state has a valid license from home. For how many days in a calendar year may they drive here without a West Virginia license?","o":["30 days","60 days","90 days","180 days"],"h1":"It is about three months.","h2":"In West Virginia a nonresident with a valid license from another state or country may drive for up to 90 days in a calendar year.","p":"Right. Visitors may drive up to 90 days a year."},"es":{"q":"En Virginia Occidental, un visitante que vive en otro estado tiene una licencia válida de su estado. ¿Cuántos días por año calendario puede manejar aquí sin licencia de Virginia Occidental?","o":["30 días","60 días","90 días","180 días"],"h1":"Son unos tres meses.","h2":"En Virginia Occidental una persona no residente con licencia válida de otro estado o país puede manejar hasta 90 días por año calendario.","p":"Correcto. Los visitantes pueden manejar hasta 90 días al año."},"ref":{"doc":"WV","page":1}},{"id":"wv-052","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, which of these people can be denied a driver's license?","o":["A 16-year-old who is not enrolled in school and has not graduated","A 19-year-old college student","A 30-year-old who just moved from another state","A 70-year-old with 20/40 vision"],"h1":"Think about school for people under 18.","h2":"In West Virginia a person under 18 who is not enrolled in school and has not graduated can be denied a driver's license.","p":"Right. Under 18, you must be in school or have graduated."},"es":{"q":"En Virginia Occidental, ¿a cuál de estas personas se le puede negar la licencia de manejar?","o":["A un joven de 16 años que no está inscrito en la escuela y no se ha graduado","A un estudiante universitario de 19 años","A una persona de 30 años que acaba de mudarse de otro estado","A una persona de 70 años con visión 20/40"],"h1":"Piense en la escuela para los menores de 18 años.","h2":"En Virginia Occidental se le puede negar la licencia a un menor de 18 años que no está inscrito en la escuela y no se ha graduado.","p":"Correcto. Si es menor de 18, debe estar en la escuela o haberse graduado."},"ref":{"doc":"WV","page":1}},{"id":"wv-053","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, after you apply for a driver's license, how does the card reach you?","o":["You pick it up at the office the same day","It comes by mail in about 15 to 20 business days","It is sent by email","You get it at your road test"],"h1":"You get a temporary license to use while you wait.","h2":"In West Virginia the license card is mailed to you in about 15 to 20 business days, and you use a temporary license until it arrives.","p":"Right. It comes by mail; a temporary license covers the wait."},"es":{"q":"En Virginia Occidental, después de solicitar la licencia de manejar, ¿cómo le llega la tarjeta?","o":["La recoge en la oficina el mismo día","Llega por correo en unos 15 a 20 días hábiles","Se la envían por correo electrónico","Se la dan en el examen de manejo"],"h1":"Le dan una licencia temporal para usar mientras espera.","h2":"En Virginia Occidental la tarjeta de licencia llega por correo en unos 15 a 20 días hábiles, y usted usa una licencia temporal hasta que llegue.","p":"Correcto. Llega por correo; una licencia temporal cubre la espera."},"ref":{"doc":"WV","page":1}},{"id":"wv-054","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how much more does a REAL ID (\"For Federal Use\") license cost than a regular one?","o":["Nothing more","$5 more","$7.50 more","$10 more"],"h1":"It is a round number of dollars.","h2":"In West Virginia a REAL ID \"For Federal Use\" license or ID card costs an additional $10.","p":"Right. REAL ID costs $10 more."},"es":{"q":"En Virginia Occidental, ¿cuánto más cuesta una licencia REAL ID (\"For Federal Use\") que una normal?","o":["Nada más","$5 más","$7.50 más","$10 más"],"h1":"Es una cantidad redonda de dólares.","h2":"En Virginia Occidental una licencia o tarjeta de identificación REAL ID \"For Federal Use\" cuesta $10 adicionales.","p":"Correcto. La REAL ID cuesta $10 más."},"ref":{"doc":"WV","page":2}},{"id":"wv-055","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how can you tell that a license is a REAL ID card for federal use?","o":["It is printed on blue paper","It has a gold star on the front","It has the word FEDERAL in red","It has no photo"],"h1":"Look for a small symbol on the face of the card.","h2":"In West Virginia a REAL ID card that meets federal rules has a gold star on the front.","p":"Right. The gold star marks a REAL ID."},"es":{"q":"En Virginia Occidental, ¿cómo se sabe que una licencia es una tarjeta REAL ID para uso federal?","o":["Está impresa en papel azul","Tiene una estrella dorada en el frente","Tiene la palabra FEDERAL en rojo","No tiene foto"],"h1":"Busque un pequeño símbolo en el frente de la tarjeta.","h2":"En Virginia Occidental una tarjeta REAL ID que cumple las reglas federales tiene una estrella dorada en el frente.","p":"Correcto. La estrella dorada indica una REAL ID."},"ref":{"doc":"WV","page":2}},{"id":"wv-056","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, you are transferring a license from another state but cannot bring that license. How recent must your certified driving record be?","o":["Dated 30 days or less before you apply","Dated within 6 months","Dated within 1 year","Any date is fine"],"h1":"It must be about one month old or newer.","h2":"In West Virginia a certified driving record from your old state must be dated 30 days or less before the date you apply.","p":"Right. The record must be 30 days old or newer."},"es":{"q":"En Virginia Occidental, usted transfiere una licencia de otro estado pero no puede traer esa licencia. ¿Qué tan reciente debe ser su historial de manejo certificado?","o":["Con fecha de 30 días o menos antes de solicitar","Con fecha de menos de 6 meses","Con fecha de menos de 1 año","Cualquier fecha sirve"],"h1":"Debe tener un mes o menos.","h2":"En Virginia Occidental el historial de manejo certificado de su estado anterior debe tener fecha de 30 días o menos antes de la solicitud.","p":"Correcto. El historial debe tener 30 días o menos."},"ref":{"doc":"WV","page":2}},{"id":"wv-057","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, you bring a utility bill as proof of where you live. How old may it be?","o":["Up to 1 year old","Up to 6 months old","No more than 90 days old","Any age, if it shows your name"],"h1":"It is about three months.","h2":"In West Virginia a recurring document like a utility bill used as proof of residency may be no more than 90 days old.","p":"Right. A utility bill must be 90 days old or newer."},"es":{"q":"En Virginia Occidental, usted trae una factura de servicios como prueba de dónde vive. ¿Qué antigüedad puede tener?","o":["Hasta 1 año","Hasta 6 meses","No más de 90 días","Cualquiera, si muestra su nombre"],"h1":"Son unos tres meses.","h2":"En Virginia Occidental un documento periódico como una factura de servicios usado como prueba de residencia no puede tener más de 90 días.","p":"Correcto. La factura debe tener 90 días o menos."},"ref":{"doc":"WV","page":4}},{"id":"wv-058","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, which proof of residency will the DMV NOT accept?","o":["A lease agreement with your street address","A West Virginia bank statement","A West Virginia voter registration card","A document that shows only a PO Box"],"h1":"The DMV needs to see where you actually live.","h2":"In West Virginia documents with a PO Box are not accepted as proof of residency, because they do not show a physical address.","p":"Right. A PO Box is not accepted."},"es":{"q":"En Virginia Occidental, ¿qué prueba de residencia NO acepta el DMV?","o":["Un contrato de alquiler con su dirección","Un estado de cuenta de un banco de Virginia Occidental","Una tarjeta de registro de votante de Virginia Occidental","Un documento que solo muestra un apartado postal (PO Box)"],"h1":"El DMV necesita ver dónde vive usted realmente.","h2":"En Virginia Occidental no se aceptan documentos con apartado postal (PO Box) como prueba de residencia, porque no muestran una dirección física.","p":"Correcto. No se acepta un apartado postal."},"ref":{"doc":"WV","page":4}},{"id":"wv-059","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, which birth record is NOT accepted as proof of identity?","o":["A certified copy of a U.S. birth certificate","A hospital birth certificate","A U.S. Military birth certificate","A U.S. Department of State birth certificate"],"h1":"Think about who issues an official record.","h2":"In West Virginia a hospital birth certificate is not accepted as proof of identity; you need an official or certified copy of a government-issued birth certificate.","p":"Right. Hospital birth certificates are not accepted."},"es":{"q":"En Virginia Occidental, ¿qué registro de nacimiento NO se acepta como prueba de identidad?","o":["Una copia certificada de un acta de nacimiento de EE. UU.","Un certificado de nacimiento del hospital","Un acta de nacimiento militar de EE. UU.","Un acta de nacimiento del Departamento de Estado de EE. UU."],"h1":"Piense en quién emite un registro oficial.","h2":"En Virginia Occidental no se acepta un certificado de nacimiento del hospital como prueba de identidad; necesita un acta oficial o una copia certificada emitida por el gobierno.","p":"Correcto. No se aceptan los certificados del hospital."},"ref":{"doc":"WV","page":3}},{"id":"wv-060","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, a new resident transfers a valid out-of-state license. Besides the documents, what must they do?","o":["Pass a vision screening, take a short alcohol awareness course and turn in the old license","Take the full road test again","Take a 30-hour driving class","Wait one year"],"h1":"There are three short steps, and none of them is a road test.","h2":"In West Virginia a new resident with a valid out-of-state license must pass a vision screening, finish a brief alcohol awareness course and surrender the old license.","p":"Right. Vision, a short alcohol course, and surrender the old license."},"es":{"q":"En Virginia Occidental, un nuevo residente transfiere una licencia válida de otro estado. Además de los documentos, ¿qué debe hacer?","o":["Pasar un examen de la vista, tomar un curso corto sobre alcohol y entregar la licencia anterior","Tomar de nuevo el examen de manejo completo","Tomar una clase de manejo de 30 horas","Esperar un año"],"h1":"Son tres pasos cortos, y ninguno es un examen de manejo.","h2":"En Virginia Occidental un nuevo residente con licencia válida de otro estado debe pasar un examen de la vista, completar un curso breve sobre alcohol y entregar la licencia anterior.","p":"Correcto. Vista, un curso corto sobre alcohol y entregar la licencia anterior."},"ref":{"doc":"WV","page":6}},{"id":"wv-061","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, your driver's license has been expired for a while. After how long must you take the tests again?","o":["30 days","6 months","1 year","3 years or more"],"h1":"It is several years.","h2":"In West Virginia a license that has been expired for three years or more means you must retest as a first-time applicant.","p":"Right. Expired three years or more means a retest."},"es":{"q":"En Virginia Occidental, su licencia de manejar lleva tiempo vencida. ¿Después de cuánto tiempo debe tomar los exámenes otra vez?","o":["30 días","6 meses","1 año","3 años o más"],"h1":"Son varios años.","h2":"En Virginia Occidental si la licencia lleva vencida tres años o más, debe tomar los exámenes otra vez como solicitante por primera vez.","p":"Correcto. Vencida tres años o más significa repetir los exámenes."},"ref":{"doc":"WV","page":7}},{"id":"wv-062","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, you moved and told the U.S. Post Office. Is your DMV address now updated?","o":["Yes, the Post Office tells the DMV","Yes, after 30 days","No, you must also tell the DMV in writing","No, you must get a new license plate"],"h1":"The Post Office and the DMV are separate.","h2":"In West Virginia notifying the Post Office does not update your DMV record; you must tell the DMV yourself in writing.","p":"Right. You must tell the DMV yourself."},"es":{"q":"En Virginia Occidental, usted se mudó y avisó al Correo de EE. UU. ¿Ya está actualizada su dirección en el DMV?","o":["Sí, el Correo le avisa al DMV","Sí, después de 30 días","No, también debe avisar al DMV por escrito","No, debe sacar una nueva placa"],"h1":"El Correo y el DMV son oficinas separadas.","h2":"En Virginia Occidental avisar al Correo no actualiza su registro en el DMV; usted mismo debe avisar al DMV por escrito.","p":"Correcto. Usted mismo debe avisar al DMV."},"ref":{"doc":"WV","page":6}},{"id":"wv-063","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what does the license of a driver aged 18 to 20 look like?","o":["Horizontal with a landscape background","Vertical and color-coded blue","Vertical and color-coded red","Horizontal and color-coded green"],"h1":"It is upright, but not red.","h2":"In West Virginia drivers aged 18 to 20 get a vertical license that is color-coded blue.","p":"Right. Ages 18 to 20 get a vertical blue license."},"es":{"q":"En Virginia Occidental, ¿cómo es la licencia de un conductor de 18 a 20 años?","o":["Horizontal con fondo de paisaje","Vertical y de color azul","Vertical y de color rojo","Horizontal y de color verde"],"h1":"Es vertical, pero no roja.","h2":"En Virginia Occidental los conductores de 18 a 20 años reciben una licencia vertical de color azul.","p":"Correcto. De 18 a 20 años la licencia es vertical y azul."},"ref":{"doc":"WV","page":7}},{"id":"wv-064","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, how long is a regular instruction permit for drivers 18 and older valid?","o":["6 months","1 year","2 years","Until you pass the road test"],"h1":"If it runs out, you must retest for a new permit.","h2":"In West Virginia a regular Class E instruction permit for drivers 18 and older is valid for six months.","p":"Right. It is valid for six months."},"es":{"q":"En Virginia Occidental, ¿por cuánto tiempo es válido el permiso de aprendizaje normal para mayores de 18 años?","o":["6 meses","1 año","2 años","Hasta que pase el examen de manejo"],"h1":"Si se vence, debe repetir los exámenes para otro permiso.","h2":"En Virginia Occidental el permiso de aprendizaje normal Clase E para mayores de 18 años es válido por seis meses.","p":"Correcto. Es válido por seis meses."},"ref":{"doc":"WV","page":9}},{"id":"wv-065","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, you are 19 and have never had a license. How long must you hold your instruction permit before the road skills test?","o":["No waiting time","7 days","At least 30 days","180 days"],"h1":"It is about one month.","h2":"In West Virginia an adult who has never been licensed must hold the instruction permit for at least 30 days before taking the road skills test.","p":"Right. At least 30 days."},"es":{"q":"En Virginia Occidental, usted tiene 19 años y nunca ha tenido licencia. ¿Cuánto tiempo debe tener el permiso de aprendizaje antes del examen de manejo?","o":["No hay que esperar","7 días","Al menos 30 días","180 días"],"h1":"Es más o menos un mes.","h2":"En Virginia Occidental un adulto que nunca ha tenido licencia debe tener el permiso de aprendizaje al menos 30 días antes del examen de manejo.","p":"Correcto. Al menos 30 días."},"ref":{"doc":"WV","page":9}},{"id":"wv-066","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, a married 16-year-old applies for a Level 1 permit. What do they bring instead of a parent's consent?","o":["A letter from their school","Their spouse's driver's license","Nothing; married teens cannot get a permit","A certified copy of their marriage certificate"],"h1":"Parental consent is not needed for married applicants.","h2":"In West Virginia a married applicant under 18 does not need a parent's consent but must show a certified copy of the marriage certificate.","p":"Right. A certified marriage certificate replaces parental consent."},"es":{"q":"En Virginia Occidental, un joven casado de 16 años solicita el permiso de Nivel 1. ¿Qué trae en lugar del consentimiento de un padre?","o":["Una carta de su escuela","La licencia de su cónyuge","Nada; los jóvenes casados no pueden tener permiso","Una copia certificada de su acta de matrimonio"],"h1":"No se necesita el consentimiento de los padres si está casado.","h2":"En Virginia Occidental un solicitante casado menor de 18 años no necesita el consentimiento de un padre, pero debe mostrar una copia certificada del acta de matrimonio.","p":"Correcto. El acta de matrimonio certificada reemplaza el consentimiento."},"ref":{"doc":"WV","page":9}},{"id":"wv-067","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how much does each attempt at the knowledge test cost?","o":["It is free","$7.50","$12.50","$25"],"h1":"It is the same fee printed for most tests in the handbook.","h2":"In West Virginia the knowledge test costs $7.50 for each attempt.","p":"Right. $7.50 per attempt."},"es":{"q":"En Virginia Occidental, ¿cuánto cuesta cada intento del examen de conocimientos?","o":["Es gratis","$7.50","$12.50","$25"],"h1":"Es la misma tarifa que aparece para la mayoría de los exámenes en el manual.","h2":"En Virginia Occidental el examen de conocimientos cuesta $7.50 por cada intento.","p":"Correcto. $7.50 por intento."},"ref":{"doc":"WV","page":10}},{"id":"wv-068","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, when does a Level 1 instruction permit expire?","o":["After one year","After 180 days","On your 18th birthday, with a 30-day grace period","On your 21st birthday"],"h1":"It is tied to a birthday, and it cannot be renewed.","h2":"In West Virginia a Level 1 permit expires on your 18th birthday, with a 30-day grace period to finish the road skills test.","p":"Right. It ends at 18, plus a 30-day grace period."},"es":{"q":"En Virginia Occidental, ¿cuándo vence el permiso de aprendizaje de Nivel 1?","o":["Después de un año","Después de 180 días","En su cumpleaños número 18, con 30 días de gracia","En su cumpleaños número 21"],"h1":"Depende de un cumpleaños, y no se puede renovar.","h2":"En Virginia Occidental el permiso de Nivel 1 vence en su cumpleaños número 18, con 30 días de gracia para terminar el examen de manejo.","p":"Correcto. Termina a los 18, más 30 días de gracia."},"ref":{"doc":"WV","page":10}},{"id":"wv-069","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what is the youngest age for a Level 2 intermediate license?","o":["15","16","17","18"],"h1":"It is one year after the youngest permit age.","h2":"In West Virginia you must be at least 16 to get a Level 2 intermediate license.","p":"Right. Level 2 starts at 16."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para la licencia intermedia de Nivel 2?","o":["15","16","17","18"],"h1":"Es un año después de la edad mínima del permiso.","h2":"En Virginia Occidental debe tener al menos 16 años para la licencia intermedia de Nivel 2.","p":"Correcto. El Nivel 2 empieza a los 16."},"ref":{"doc":"WV","page":10}},{"id":"wv-070","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you have a Level 2 license and drive alone at 11 p.m. Which trip is allowed?","o":["Coming home from a friend's party","Going out for food with friends","Driving around to practice","Coming home from your job"],"h1":"The law lists work, school activities, religious activities and emergencies.","h2":"In West Virginia a Level 2 driver may drive alone between 10 p.m. and 5 a.m. when going to or coming home from a job.","p":"Right. Going to or from work is an exception."},"es":{"q":"En Virginia Occidental, usted tiene licencia de Nivel 2 y maneja solo a las 11 p.m. ¿Qué viaje está permitido?","o":["Volver de una fiesta de un amigo","Salir a comer con amigos","Manejar por ahí para practicar","Volver a casa de su trabajo"],"h1":"La ley menciona el trabajo, actividades escolares, actividades religiosas y emergencias.","h2":"En Virginia Occidental un conductor de Nivel 2 puede manejar solo entre las 10 p.m. y las 5 a.m. cuando va o vuelve de su trabajo.","p":"Correcto. Ir o volver del trabajo es una excepción."},"ref":{"doc":"WV","page":10}},{"id":"wv-071","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, a 17-year-old gives up (surrenders) their Level 2 license. What happens if they want to drive again?","o":["They get it back the next day","They must start over with a Level 1 permit","They go straight to Level 3","They must wait until age 21"],"h1":"Under 18, they go back to the first level.","h2":"In West Virginia a driver under 18 who surrenders a Level 2 license must start over with a Level 1 instruction permit.","p":"Right. They start again at Level 1."},"es":{"q":"En Virginia Occidental, un joven de 17 años entrega su licencia de Nivel 2. ¿Qué pasa si quiere volver a manejar?","o":["Se la devuelven al día siguiente","Debe empezar de nuevo con un permiso de Nivel 1","Pasa directo al Nivel 3","Debe esperar hasta los 21 años"],"h1":"Si es menor de 18, vuelve al primer nivel.","h2":"En Virginia Occidental un menor de 18 años que entrega su licencia de Nivel 2 debe empezar de nuevo con un permiso de aprendizaje de Nivel 1.","p":"Correcto. Empieza otra vez en el Nivel 1."},"ref":{"doc":"WV","page":11}},{"id":"wv-072","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, a Level 1 permit holder gets a traffic conviction after 4 months. What happens to the 6 conviction-free months needed for Level 2?","o":["Nothing; only 2 months are left","The time is cut to 3 months","The 6 months start over from the conviction date","The permit becomes a Level 2 license"],"h1":"Each conviction resets the clock.","h2":"In West Virginia each conviction on a Level 1 permit restarts the 6-month conviction-free period from the date of the conviction.","p":"Right. The 6 months start over."},"es":{"q":"En Virginia Occidental, alguien con permiso de Nivel 1 recibe una condena de tránsito a los 4 meses. ¿Qué pasa con los 6 meses sin condenas que necesita para el Nivel 2?","o":["Nada; solo le quedan 2 meses","El tiempo baja a 3 meses","Los 6 meses empiezan de nuevo desde la fecha de la condena","El permiso se convierte en licencia de Nivel 2"],"h1":"Cada condena reinicia el reloj.","h2":"En Virginia Occidental cada condena con permiso de Nivel 1 reinicia el periodo de 6 meses sin condenas desde la fecha de la condena.","p":"Correcto. Los 6 meses empiezan de nuevo."},"ref":{"doc":"WV","page":11}},{"id":"wv-073","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, a Level 2 driver does not enroll in the required driver improvement program after a first conviction. What is the result?","o":["They stay at Level 2 until age 18","They lose their license for life","They pay a $5 fine","Nothing happens"],"h1":"They cannot move up early.","h2":"In West Virginia a Level 2 driver who fails to enroll in a required driver improvement program must stay at Level 2 until age 18.","p":"Right. They stay at Level 2 until 18."},"es":{"q":"En Virginia Occidental, un conductor de Nivel 2 no se inscribe en el programa de mejoramiento de conductores después de su primera condena. ¿Cuál es el resultado?","o":["Se queda en el Nivel 2 hasta los 18 años","Pierde la licencia de por vida","Paga una multa de $5","No pasa nada"],"h1":"No puede subir de nivel antes.","h2":"En Virginia Occidental un conductor de Nivel 2 que no se inscribe en el programa de mejoramiento requerido debe quedarse en el Nivel 2 hasta los 18 años.","p":"Correcto. Se queda en el Nivel 2 hasta los 18."},"ref":{"doc":"WV","page":11}},{"id":"wv-074","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, a Level 2 driver is convicted of a second moving violation. What happens?","o":["A warning letter","A $25 fine only","A 30-day suspension","The license is revoked until age 18, and they must retest"],"h1":"It is much more serious than the first conviction.","h2":"In West Virginia a second moving violation conviction on a Level 2 license means revocation until age 18 and retesting as a first-time applicant.","p":"Right. Revoked until 18, then a full retest."},"es":{"q":"En Virginia Occidental, un conductor de Nivel 2 recibe una condena por una segunda infracción de tránsito en movimiento. ¿Qué pasa?","o":["Una carta de advertencia","Solo una multa de $25","Una suspensión de 30 días","Se le revoca la licencia hasta los 18 años y debe repetir los exámenes"],"h1":"Es mucho más grave que la primera condena.","h2":"En Virginia Occidental una segunda condena por infracción en movimiento con licencia de Nivel 2 significa la revocación hasta los 18 años y repetir los exámenes como solicitante nuevo.","p":"Correcto. Revocada hasta los 18, y luego todos los exámenes."},"ref":{"doc":"WV","page":11}},{"id":"wv-075","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, a 16-year-old with a Level 2 license gets a ticket for using a phone while driving. What happens to their conviction-free time?","o":["Nothing, phone tickets do not count","It starts over","It is cut in half","It is extended by one week"],"h1":"Phone tickets count like other convictions for teen drivers.","h2":"In West Virginia a phone ticket on a Level 1 permit or Level 2 license makes the conviction-free time start over.","p":"Right. The conviction-free time starts over."},"es":{"q":"En Virginia Occidental, un joven de 16 años con licencia de Nivel 2 recibe una multa por usar el teléfono mientras maneja. ¿Qué pasa con su tiempo sin condenas?","o":["Nada, las multas por teléfono no cuentan","Empieza de nuevo","Se reduce a la mitad","Se alarga una semana"],"h1":"Las multas por teléfono cuentan como otras condenas para conductores jóvenes.","h2":"En Virginia Occidental una multa por teléfono con permiso de Nivel 1 o licencia de Nivel 2 hace que el tiempo sin condenas empiece de nuevo.","p":"Correcto. El tiempo sin condenas empieza de nuevo."},"ref":{"doc":"WV","page":11}},{"id":"wv-076","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you qualify for a Level 3 license at 17. Must you get it?","o":["Yes, within 30 days","Yes, or your Level 2 license is canceled","No, but you must stop driving","No, you may keep Level 2 and its limits until you turn 18"],"h1":"Moving up is your choice.","h2":"In West Virginia getting a Level 3 license is optional; you may keep your Level 2 license and follow its limits until age 18.","p":"Right. You may keep Level 2 until 18."},"es":{"q":"En Virginia Occidental, usted califica para la licencia de Nivel 3 a los 17 años. ¿Está obligado a sacarla?","o":["Sí, dentro de 30 días","Sí, o se cancela su licencia de Nivel 2","No, pero debe dejar de manejar","No, puede quedarse con el Nivel 2 y sus límites hasta cumplir 18"],"h1":"Subir de nivel es su decisión.","h2":"En Virginia Occidental sacar la licencia de Nivel 3 es opcional; puede quedarse con la licencia de Nivel 2 y seguir sus límites hasta los 18 años.","p":"Correcto. Puede quedarse con el Nivel 2 hasta los 18."},"ref":{"doc":"WV","page":12}},{"id":"wv-077","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, a 16-year-old moves from a state with no graduated license program. How can they get credit for the time they already drove?","o":["Bring a current driving record from the old state","Show a school report card","Bring a letter from a parent","There is no way to get credit"],"h1":"The DMV needs an official record of the old license.","h2":"In West Virginia a teen who brings a current driving record from the old state gets credit for the time they held that license toward the Level 1 time.","p":"Right. A current driving record earns the credit."},"es":{"q":"En Virginia Occidental, un joven de 16 años se muda de un estado sin programa de licencia gradual. ¿Cómo puede recibir crédito por el tiempo que ya manejó?","o":["Trayendo un historial de manejo actual del estado anterior","Mostrando su boleta de calificaciones","Trayendo una carta de un padre","No hay manera de recibir crédito"],"h1":"El DMV necesita un registro oficial de la licencia anterior.","h2":"En Virginia Occidental un joven que trae un historial de manejo actual de su estado anterior recibe crédito por el tiempo que tuvo esa licencia para el tiempo del Nivel 1.","p":"Correcto. Un historial de manejo actual le da el crédito."},"ref":{"doc":"WV","page":12}},{"id":"wv-078","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, a driver's license shows restriction code 3. What does it mean?","o":["Corrective lenses","Daylight driving only","Automatic transmission only","Hand controls"],"h1":"It is about the kind of car you may drive.","h2":"In West Virginia restriction code 3 on a license means the driver may drive only a vehicle with an automatic transmission.","p":"Right. Code 3 means automatic transmission."},"es":{"q":"En Virginia Occidental, una licencia muestra el código de restricción 3. ¿Qué significa?","o":["Lentes correctivos","Manejar solo de día","Solo transmisión automática","Controles de mano"],"h1":"Se trata del tipo de carro que puede manejar.","h2":"En Virginia Occidental el código de restricción 3 en la licencia significa que la persona solo puede manejar un vehículo de transmisión automática.","p":"Correcto. El código 3 significa transmisión automática."},"ref":{"doc":"WV","page":12}},{"id":"wv-079","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, once you are in the \"Drive for Five\" cycle, how many years is a renewed license valid?","o":["4 years","5 years","8 years","10 years"],"h1":"The program's name gives a hint.","h2":"In West Virginia a license in the \"Drive for Five\" program is valid for five years.","p":"Right. Five years."},"es":{"q":"En Virginia Occidental, una vez que está en el ciclo \"Drive for Five\", ¿por cuántos años es válida una licencia renovada?","o":["4 años","5 años","8 años","10 años"],"h1":"El nombre del programa da una pista.","h2":"En Virginia Occidental una licencia del programa \"Drive for Five\" es válida por cinco años.","p":"Correcto. Cinco años."},"ref":{"doc":"WV","page":12}},{"id":"wv-080","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you are 21 and renew your license. It will next expire on your 25th birthday. What is the renewal fee?","o":["$5","$7.50","$12.50","$20"],"h1":"The fee is $5 for each year until it expires.","h2":"In West Virginia the renewal fee is $5 per year, so four years until age 25 costs $20.","p":"Right. Four years at $5 is $20."},"es":{"q":"En Virginia Occidental, usted tiene 21 años y renueva su licencia. Vencerá en su cumpleaños número 25. ¿Cuánto cuesta la renovación?","o":["$5","$7.50","$12.50","$20"],"h1":"La tarifa es $5 por cada año hasta que vence.","h2":"En Virginia Occidental la renovación cuesta $5 por año, así que cuatro años hasta los 25 cuestan $20.","p":"Correcto. Cuatro años a $5 son $20."},"ref":{"doc":"WV","page":13}},{"id":"wv-081","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, on what day does a newer driver's license expire?","o":["On your birthday","On the last day of your birth month","On January 1","On the date you first got it"],"h1":"It is a day that is easy to remember.","h2":"In West Virginia driver's licenses issued after January 1, 2001, expire on the driver's birthday.","p":"Right. It expires on your birthday."},"es":{"q":"En Virginia Occidental, ¿qué día vence una licencia de manejar reciente?","o":["En su cumpleaños","El último día del mes de su cumpleaños","El 1 de enero","En la fecha en que la recibió por primera vez"],"h1":"Es un día fácil de recordar.","h2":"En Virginia Occidental las licencias emitidas después del 1 de enero de 2001 vencen en el cumpleaños del conductor.","p":"Correcto. Vence en su cumpleaños."},"ref":{"doc":"WV","page":13}},{"id":"wv-082","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, your license expires on your 21st birthday. How long do you have to get the new adult license?","o":["No extra time","10 days","A 30-day grace period","6 months"],"h1":"You get about one month.","h2":"In West Virginia a license that expires on your 18th or 21st birthday has a 30-day grace period to get the license with the right color and style.","p":"Right. There is a 30-day grace period."},"es":{"q":"En Virginia Occidental, su licencia vence en su cumpleaños número 21. ¿Cuánto tiempo tiene para sacar la nueva licencia de adulto?","o":["Nada de tiempo extra","10 días","Un periodo de gracia de 30 días","6 meses"],"h1":"Tiene más o menos un mes.","h2":"En Virginia Occidental una licencia que vence en su cumpleaños número 18 o 21 tiene 30 días de gracia para sacar la licencia del color y estilo correctos.","p":"Correcto. Hay 30 días de gracia."},"ref":{"doc":"WV","page":13}},{"id":"wv-083","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, you want to add or remove the organ donor mark on the front of your license. What must you do?","o":["Call the DMV","Get a new license and pay any fee","Mark it yourself with a pen","Nothing; it changes on its own"],"h1":"The registry can change online, but the card itself cannot.","h2":"In West Virginia changing the organ donor mark on the face of your license means getting a new license and paying any fee.","p":"Right. You need a new license."},"es":{"q":"En Virginia Occidental, usted quiere agregar o quitar la marca de donante de órganos en el frente de su licencia. ¿Qué debe hacer?","o":["Llamar al DMV","Sacar una licencia nueva y pagar la tarifa que corresponda","Marcarla usted mismo con un bolígrafo","Nada; cambia sola"],"h1":"El registro puede cambiar en línea, pero la tarjeta no.","h2":"En Virginia Occidental para cambiar la marca de donante de órganos en el frente de la licencia hay que sacar una licencia nueva y pagar la tarifa que corresponda.","p":"Correcto. Necesita una licencia nueva."},"ref":{"doc":"WV","page":13}},{"id":"wv-084","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, an officer stops you and you forgot your license at home. It is valid. When will you NOT be convicted?","o":["If you promise to carry it next time","If a passenger has a license","If it was only one block from home","If you later show the valid license in court or at the officer's office"],"h1":"You must prove it was valid at the time of the stop.","h2":"In West Virginia not showing your license on demand is a misdemeanor, but you will not be convicted if the license was valid and you show it in court or at the arresting officer's office.","p":"Right. Show the valid license later and you are not convicted."},"es":{"q":"En Virginia Occidental, un oficial lo detiene y usted dejó su licencia en casa. La licencia es válida. ¿Cuándo NO lo condenarán?","o":["Si promete llevarla la próxima vez","Si un pasajero tiene licencia","Si estaba a solo una cuadra de casa","Si después muestra la licencia válida en la corte o en la oficina del oficial"],"h1":"Debe probar que era válida en el momento de la parada.","h2":"En Virginia Occidental no mostrar la licencia cuando se la piden es un delito menor, pero no lo condenarán si la licencia era válida y la muestra en la corte o en la oficina del oficial que lo detuvo.","p":"Correcto. Si muestra después la licencia válida, no lo condenan."},"ref":{"doc":"WV","page":13}},{"id":"wv-085","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what may you do with a motorcycle instruction permit?","o":["Ride in daylight with no passengers","Ride at night with one passenger","Ride anywhere with a licensed rider behind you","Ride only on interstates"],"h1":"Think about light and who is on the bike.","h2":"In West Virginia a motorcycle instruction permit lets you ride on public roads only in daylight and without passengers.","p":"Right. Daylight only, no passengers."},"es":{"q":"En Virginia Occidental, ¿qué puede hacer con un permiso de aprendizaje de motocicleta?","o":["Manejar de día y sin pasajeros","Manejar de noche con un pasajero","Manejar a cualquier lugar con un motociclista con licencia detrás","Manejar solo en carreteras interestatales"],"h1":"Piense en la luz y en quién va en la moto.","h2":"En Virginia Occidental el permiso de aprendizaje de motocicleta solo permite manejar en vías públicas de día y sin pasajeros.","p":"Correcto. Solo de día y sin pasajeros."},"ref":{"doc":"WV","page":14}},{"id":"wv-086","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what is the youngest age to apply for a motorcycle instruction permit?","o":["14","15","16","18"],"h1":"A teen must first meet the Level 2 requirements.","h2":"In West Virginia you must be at least 16 to apply for a motorcycle instruction permit, and a teen under 18 must first meet the Level 2 or Class E requirements.","p":"Right. The minimum age is 16."},"es":{"q":"En Virginia Occidental, ¿cuál es la edad mínima para solicitar el permiso de aprendizaje de motocicleta?","o":["14","15","16","18"],"h1":"Un joven primero debe cumplir los requisitos del Nivel 2.","h2":"En Virginia Occidental debe tener al menos 16 años para solicitar el permiso de aprendizaje de motocicleta, y un menor de 18 primero debe cumplir los requisitos del Nivel 2 o de la Clase E.","p":"Correcto. La edad mínima es 16."},"ref":{"doc":"WV","page":14}},{"id":"wv-087","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what score do you need on the 25-question motorcycle knowledge test?","o":["70% or better","80% or better","90% or better","100%"],"h1":"It is higher than three out of four.","h2":"In West Virginia you must score 80% or better on the 25-question motorcycle knowledge test.","p":"Right. You need 80% or better."},"es":{"q":"En Virginia Occidental, ¿qué calificación necesita en el examen de conocimientos de motocicleta de 25 preguntas?","o":["70% o más","80% o más","90% o más","100%"],"h1":"Es más que tres de cada cuatro.","h2":"En Virginia Occidental debe sacar 80% o más en el examen de conocimientos de motocicleta de 25 preguntas.","p":"Correcto. Necesita 80% o más."},"ref":{"doc":"WV","page":14}},{"id":"wv-088","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, how long must you hold a motorcycle instruction permit before you can add the motorcycle (F) endorsement?","o":["1 day","30 days","6 months","At least 7 days"],"h1":"It is about one week.","h2":"In West Virginia you must hold a motorcycle instruction permit for at least seven days before you can add the F endorsement.","p":"Right. At least seven days."},"es":{"q":"En Virginia Occidental, ¿cuánto tiempo debe tener el permiso de aprendizaje de motocicleta antes de agregar el endoso de motocicleta (F)?","o":["1 día","30 días","6 meses","Al menos 7 días"],"h1":"Es más o menos una semana.","h2":"En Virginia Occidental debe tener el permiso de aprendizaje de motocicleta al menos siete días antes de agregar el endoso F.","p":"Correcto. Al menos siete días."},"ref":{"doc":"WV","page":14}},{"id":"wv-089","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, you pass the Motorcycle Safety Foundation Basic Rider Course. What does that do for you?","o":["The DMV motorcycle skills test is waived","You can carry passengers on your permit","You skip the knowledge test","You get a car license too"],"h1":"It replaces one test given by the DMV.","h2":"In West Virginia passing the Basic Rider Course after holding a permit at least 7 days waives the DMV on-cycle skills test.","p":"Right. It waives the DMV skills test."},"es":{"q":"En Virginia Occidental, usted aprueba el Curso Básico para Motociclistas de la Motorcycle Safety Foundation. ¿Qué logra con eso?","o":["No tiene que tomar el examen práctico de motocicleta del DMV","Puede llevar pasajeros con su permiso","No tiene que tomar el examen de conocimientos","También recibe licencia de carro"],"h1":"Reemplaza un examen del DMV.","h2":"En Virginia Occidental aprobar el Curso Básico para Motociclistas, después de tener el permiso al menos 7 días, lo exime del examen práctico en motocicleta del DMV.","p":"Correcto. Lo exime del examen práctico del DMV."},"ref":{"doc":"WV","page":14}},{"id":"wv-090","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what may a person with only a Class F license drive?","o":["Any car or truck","Cars, but not trucks","Only a motorcycle","Only a moped"],"h1":"Class F is a motorcycle-only license.","h2":"In West Virginia a Class F license is for motorcycles only, and the holder cannot drive any other type of motor vehicle.","p":"Right. Only a motorcycle."},"es":{"q":"En Virginia Occidental, ¿qué puede manejar una persona que solo tiene licencia Clase F?","o":["Cualquier carro o camión","Carros, pero no camiones","Solo una motocicleta","Solo un ciclomotor"],"h1":"La Clase F es una licencia solo para motocicleta.","h2":"En Virginia Occidental la licencia Clase F es solo para motocicletas, y quien la tiene no puede manejar ningún otro tipo de vehículo.","p":"Correcto. Solo una motocicleta."},"ref":{"doc":"WV","page":14}},{"id":"wv-091","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, about how long is the Basic Rider Course for motorcyclists?","o":["4 hours","About 17 hours","40 hours","2 weeks"],"h1":"It includes both classroom and riding time.","h2":"In West Virginia the Basic Rider Course is about 17 hours long, with classroom and on-cycle instruction.","p":"Right. About 17 hours."},"es":{"q":"En Virginia Occidental, ¿cuánto dura más o menos el Curso Básico para Motociclistas?","o":["4 horas","Unas 17 horas","40 horas","2 semanas"],"h1":"Incluye clases en el aula y práctica en la moto.","h2":"En Virginia Occidental el Curso Básico para Motociclistas dura unas 17 horas, con clases en el aula y práctica en motocicleta.","p":"Correcto. Unas 17 horas."},"ref":{"doc":"WV","page":15}},{"id":"wv-092","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, what does a duplicate driver's license cost?","o":["It is free","$2.50","$5.00","$7.50"],"h1":"It is the same amount as one knowledge test attempt.","h2":"In West Virginia a duplicate driver's license costs $7.50.","p":"Right. A duplicate costs $7.50."},"es":{"q":"En Virginia Occidental, ¿cuánto cuesta un duplicado de la licencia de manejar?","o":["Es gratis","$2.50","$5.00","$7.50"],"h1":"Es la misma cantidad que un intento del examen de conocimientos.","h2":"En Virginia Occidental un duplicado de la licencia de manejar cuesta $7.50.","p":"Correcto. Un duplicado cuesta $7.50."},"ref":{"doc":"WV","page":15}},{"id":"wv-093","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, besides your license, which two papers must you keep in your vehicle?","o":["Proof of West Virginia liability insurance and the registration card","Your birth certificate and Social Security card","The car title and bill of sale","Your last inspection receipt and repair records"],"h1":"An officer may ask for them at a traffic stop.","h2":"In West Virginia you must keep proof of West Virginia liability insurance and a current registration card in your vehicle.","p":"Right. Insurance proof and the registration card."},"es":{"q":"En Virginia Occidental, además de su licencia, ¿qué dos papeles debe llevar en su vehículo?","o":["La prueba de seguro de responsabilidad de Virginia Occidental y la tarjeta de registro","Su acta de nacimiento y su tarjeta de Seguro Social","El título del carro y la factura de compra","El último recibo de inspección y los registros de reparación"],"h1":"Un oficial se los puede pedir en una parada de tránsito.","h2":"En Virginia Occidental debe llevar en su vehículo la prueba de seguro de responsabilidad de Virginia Occidental y la tarjeta de registro vigente.","p":"Correcto. La prueba de seguro y la tarjeta de registro."},"ref":{"doc":"WV","page":15}},{"id":"wv-094","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, a teen's school tells the DMV that the teen has too many unexcused absences. What can happen to the teen's license?","o":["It can be limited to driving for work, medical, school or religious reasons","Nothing; school and driving are separate","It is canceled for life","The teen must pay a $500 fine"],"h1":"The license is not taken away, but it is limited.","h2":"In West Virginia excessive unexcused absences can lead the DMV to restrict a minor's license to work, medical, educational and religious purposes until age 18 or until the school allows reinstatement.","p":"Right. The license can be limited to those purposes."},"es":{"q":"En Virginia Occidental, la escuela de un joven le avisa al DMV que tiene demasiadas faltas sin justificar. ¿Qué le puede pasar a su licencia?","o":["Se puede limitar a manejar por trabajo, motivos médicos, escuela o religión","Nada; la escuela y el manejo son cosas separadas","Se cancela de por vida","El joven debe pagar una multa de $500"],"h1":"No le quitan la licencia, pero la limitan.","h2":"En Virginia Occidental las faltas excesivas sin justificar pueden hacer que el DMV limite la licencia de un menor a trabajo, motivos médicos, educativos y religiosos hasta los 18 años o hasta que la escuela autorice la restitución.","p":"Correcto. La licencia se puede limitar a esos motivos."},"ref":{"doc":"WV","page":16}},{"id":"wv-095","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, you worry that your elderly parent can no longer drive safely. What can you do?","o":["Take away their license yourself","Write a detailed letter to the DMV Medical Section","Call their insurance company to cancel it","Nothing; only a judge can act"],"h1":"The DMV can reexamine the driver.","h2":"In West Virginia a family member can write a detailed explanation to the DMV Medical Section, and the DMV may reexamine the driver.","p":"Right. Write to the DMV Medical Section."},"es":{"q":"En Virginia Occidental, a usted le preocupa que su padre o madre de edad avanzada ya no pueda manejar con seguridad. ¿Qué puede hacer?","o":["Quitarle usted mismo la licencia","Escribir una carta detallada a la Sección Médica del DMV","Llamar a su compañía de seguros para cancelarlo","Nada; solo un juez puede actuar"],"h1":"El DMV puede volver a evaluar al conductor.","h2":"En Virginia Occidental un familiar puede escribir una explicación detallada a la Sección Médica del DMV, y el DMV puede volver a evaluar al conductor.","p":"Correcto. Escriba a la Sección Médica del DMV."},"ref":{"doc":"WV","page":16}},{"id":"wv-096","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, the DMV orders you to take a driving or medical reexamination and you refuse. What can happen?","o":["Nothing, it is optional","You pay a small fee","You must retake driver education","Your license can be suspended or revoked"],"h1":"Refusing is not a way to avoid the result.","h2":"In West Virginia refusing a required reexamination is grounds to suspend or revoke your driver's license.","p":"Right. Refusing can cost you your license."},"es":{"q":"En Virginia Occidental, el DMV le ordena tomar una nueva evaluación de manejo o médica y usted se niega. ¿Qué puede pasar?","o":["Nada, es opcional","Paga una tarifa pequeña","Debe repetir el curso de manejo","Le pueden suspender o revocar la licencia"],"h1":"Negarse no evita el resultado.","h2":"En Virginia Occidental negarse a una evaluación requerida es motivo para suspender o revocar su licencia.","p":"Correcto. Negarse le puede costar la licencia."},"ref":{"doc":"WV","page":16}},{"id":"wv-097","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, until when is a Level 3 graduated license valid?","o":["Until age 18","Until age 19","Until 30 days after your 21st birthday","For 10 years"],"h1":"Then you move to a regular adult license.","h2":"In West Virginia a Level 3 license is valid until 30 days after your 21st birthday.","p":"Right. It lasts until 30 days after you turn 21."},"es":{"q":"En Virginia Occidental, ¿hasta cuándo es válida la licencia gradual de Nivel 3?","o":["Hasta los 18 años","Hasta los 19 años","Hasta 30 días después de cumplir 21 años","Por 10 años"],"h1":"Después pasa a una licencia normal de adulto.","h2":"En Virginia Occidental la licencia de Nivel 3 es válida hasta 30 días después de cumplir 21 años.","p":"Correcto. Dura hasta 30 días después de cumplir 21."},"ref":{"doc":"WV","page":null}},{"id":"wv-098","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what is the fine for a first violation of the rules of a Level 1 permit or Level 2 license?","o":["$25","$100","$250","$500"],"h1":"It is the smallest of these amounts; it rises to $50 and then $75.","h2":"In West Virginia a first violation of the terms of a graduated license is a misdemeanor with a $25 fine.","p":"Right. The first fine is $25."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa por la primera violación de las reglas del permiso de Nivel 1 o de la licencia de Nivel 2?","o":["$25","$100","$250","$500"],"h1":"Es la cantidad más pequeña; sube a $50 y luego a $75.","h2":"En Virginia Occidental la primera violación de las condiciones de una licencia gradual es un delito menor con multa de $25.","p":"Correcto. La primera multa es de $25."},"ref":{"doc":"WV","page":null}},{"id":"wv-099","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, a crash hurts no one. Above what amount of property damage must it be reported to the police?","o":["$500","$1,000","$2,500","$5,000"],"h1":"It is a round number in the thousands.","h2":"In West Virginia a crash with property damage over $1,000 must be reported to the police, even if no one is hurt.","p":"Right. Damage over $1,000 must be reported."},"es":{"q":"En Virginia Occidental, en un choque no hay heridos. ¿A partir de qué cantidad de daños materiales hay que reportarlo a la policía?","o":["$500","$1,000","$2,500","$5,000"],"h1":"Es un número redondo en miles.","h2":"En Virginia Occidental un choque con daños materiales de más de $1,000 se debe reportar a la policía, aunque no haya heridos.","p":"Correcto. Daños de más de $1,000 se deben reportar."},"ref":{"doc":"WV","page":16}},{"id":"wv-100","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you have a crash that must be reported, on a road outside any city or town. Whom do you report it to?","o":["The city police of the nearest town","The DMV","Your insurance company only","The county sheriff or the nearest State Police office"],"h1":"Inside a city it goes to the local police; outside, to someone else.","h2":"In West Virginia a reportable crash outside a city or town is reported to the county sheriff or the nearest West Virginia State Police office.","p":"Right. Report it to the sheriff or the State Police."},"es":{"q":"En Virginia Occidental, usted tiene un choque que se debe reportar, en una carretera fuera de cualquier ciudad o pueblo. ¿A quién lo reporta?","o":["A la policía del pueblo más cercano","Al DMV","Solo a su compañía de seguros","A la oficina del sheriff del condado o a la oficina más cercana de la Policía Estatal"],"h1":"Dentro de una ciudad va a la policía local; fuera, a otra autoridad.","h2":"En Virginia Occidental un choque que se debe reportar fuera de una ciudad o pueblo se reporta al sheriff del condado o a la oficina más cercana de la Policía Estatal de Virginia Occidental.","p":"Correcto. Se reporta al sheriff o a la Policía Estatal."},"ref":{"doc":"WV","page":16}},{"id":"wv-101","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, your car had no liability insurance on the day of a crash. What happens?","o":["Your registration and your driving privilege are suspended","You get a warning letter","The other driver pays for everything","Nothing, if the crash was not your fault"],"h1":"Two things are taken away.","h2":"In West Virginia if your vehicle was not insured on the date of a crash, both your vehicle registration and your driving privilege are suspended.","p":"Right. Registration and license are both suspended."},"es":{"q":"En Virginia Occidental, su carro no tenía seguro de responsabilidad el día de un choque. ¿Qué pasa?","o":["Le suspenden el registro del vehículo y el privilegio de manejar","Recibe una carta de advertencia","El otro conductor paga todo","Nada, si el choque no fue su culpa"],"h1":"Le quitan dos cosas.","h2":"En Virginia Occidental si su vehículo no tenía seguro el día del choque, le suspenden tanto el registro del vehículo como el privilegio de manejar.","p":"Correcto. Suspenden el registro y la licencia."},"ref":{"doc":"WV","page":16}},{"id":"wv-102","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, what is the minimum liability insurance for the deaths or injuries of two or more people in one crash?","o":["$25,000","$40,000","$50,000","$100,000"],"h1":"It is twice the amount for one person.","h2":"In West Virginia the minimum liability coverage is $50,000 for the deaths or injuries of two or more people.","p":"Right. $50,000 for two or more people."},"es":{"q":"En Virginia Occidental, ¿cuál es el seguro de responsabilidad mínimo por la muerte o lesiones de dos o más personas en un choque?","o":["$25,000","$40,000","$50,000","$100,000"],"h1":"Es el doble de la cantidad para una persona.","h2":"En Virginia Occidental la cobertura mínima de responsabilidad es de $50,000 por la muerte o lesiones de dos o más personas.","p":"Correcto. $50,000 por dos o más personas."},"ref":{"doc":"WV","page":16}},{"id":"wv-103","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what is the minimum liability insurance for damage to other people's property?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"It is the same amount as for one person's injury.","h2":"In West Virginia the minimum liability coverage for property damage is $25,000.","p":"Right. $25,000 for property damage."},"es":{"q":"En Virginia Occidental, ¿cuál es el seguro de responsabilidad mínimo por daños a la propiedad de otras personas?","o":["$10,000","$25,000","$50,000","$100,000"],"h1":"Es la misma cantidad que por las lesiones de una persona.","h2":"En Virginia Occidental la cobertura mínima de responsabilidad por daños a la propiedad es de $25,000.","p":"Correcto. $25,000 por daños a la propiedad."},"ref":{"doc":"WV","page":16}},{"id":"wv-104","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, your car insurance is canceled. What must you do with your license plate?","o":["Keep it until it expires","Give it to the insurance company","Throw it away","Surrender it to the DMV"],"h1":"You may not keep driving an uninsured car with a valid plate.","h2":"In West Virginia if your insurance is canceled for any reason, you must surrender the vehicle registration plate to the DMV.","p":"Right. Turn the plate in to the DMV."},"es":{"q":"En Virginia Occidental, le cancelan el seguro del carro. ¿Qué debe hacer con la placa?","o":["Quedársela hasta que venza","Dársela a la compañía de seguros","Tirarla a la basura","Entregarla al DMV"],"h1":"No puede seguir manejando un carro sin seguro con una placa vigente.","h2":"En Virginia Occidental si le cancelan el seguro por cualquier motivo, debe entregar la placa del vehículo al DMV.","p":"Correcto. Entregue la placa al DMV."},"ref":{"doc":"WV","page":17}},{"id":"wv-105","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, an officer asks for proof of insurance. May you show it on your phone screen?","o":["Yes, an image on a phone is valid proof","No, only paper is accepted","Only if you also have the paper at home","Only during a vehicle inspection"],"h1":"The law accepts an image on a wireless device.","h2":"In West Virginia an image of your proof of insurance shown on a phone or other wireless device is valid proof.","p":"Right. A phone image is valid proof."},"es":{"q":"En Virginia Occidental, un oficial le pide la prueba de seguro. ¿Puede mostrarla en la pantalla de su teléfono?","o":["Sí, una imagen en el teléfono es prueba válida","No, solo se acepta en papel","Solo si también tiene el papel en casa","Solo durante una inspección del vehículo"],"h1":"La ley acepta una imagen en un dispositivo inalámbrico.","h2":"En Virginia Occidental una imagen de su prueba de seguro mostrada en un teléfono u otro dispositivo inalámbrico es prueba válida.","p":"Correcto. Una imagen en el teléfono es prueba válida."},"ref":{"doc":"WV","page":17}},{"id":"wv-106","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, a driver gives the DMV false insurance information. Besides possible prosecution, what happens to the license?","o":["A warning only","A 10-day suspension","An additional 90-day suspension","A one-week class"],"h1":"It is about three months.","h2":"In West Virginia filing false or fraudulent insurance information leads to an additional 90-day license suspension and revocation of the vehicle registration.","p":"Right. An extra 90-day suspension."},"es":{"q":"En Virginia Occidental, un conductor le da al DMV información falsa del seguro. Además de un posible proceso penal, ¿qué pasa con su licencia?","o":["Solo una advertencia","Una suspensión de 10 días","Una suspensión adicional de 90 días","Una clase de una semana"],"h1":"Son unos tres meses.","h2":"En Virginia Occidental presentar información de seguro falsa o fraudulenta trae una suspensión adicional de la licencia de 90 días y la revocación del registro del vehículo.","p":"Correcto. Una suspensión adicional de 90 días."},"ref":{"doc":"WV","page":17}},{"id":"wv-107","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, for which handheld phone offense are points first added to your record?","o":["The first offense","The second offense","The third offense","Points are never added"],"h1":"The first two offenses bring fines but zero points.","h2":"In West Virginia the third and later handheld phone offenses bring a $300 fine and 3 points; the first two bring fines with no points.","p":"Right. Points start at the third offense."},"es":{"q":"En Virginia Occidental, ¿con qué infracción por usar el teléfono en la mano se agregan puntos a su historial por primera vez?","o":["La primera infracción","La segunda infracción","La tercera infracción","Nunca se agregan puntos"],"h1":"Las dos primeras infracciones tienen multa pero cero puntos.","h2":"En Virginia Occidental la tercera infracción y las siguientes por usar el teléfono en la mano tienen una multa de $300 y 3 puntos; las dos primeras tienen multa sin puntos.","p":"Correcto. Los puntos empiezan con la tercera infracción."},"ref":{"doc":"WV","page":17}},{"id":"wv-108","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, when is it legal to use a handheld phone while driving?","o":["When stopped at a red light","When texting a short message","On a straight country road","To report a crash, fire or serious road hazard to the authorities"],"h1":"There is an exception for emergencies.","h2":"In West Virginia using a phone to report a fire, crash, serious road hazard or emergency to the proper authorities is not a violation.","p":"Right. Reporting an emergency is allowed."},"es":{"q":"En Virginia Occidental, ¿cuándo es legal usar el teléfono en la mano mientras maneja?","o":["Cuando está detenido en un semáforo en rojo","Para escribir un mensaje corto","En una carretera rural recta","Para reportar a las autoridades un choque, un incendio o un peligro grave en la vía"],"h1":"Hay una excepción para emergencias.","h2":"En Virginia Occidental usar el teléfono para reportar a las autoridades un incendio, un choque, un peligro grave en la vía o una emergencia no es una infracción.","p":"Correcto. Reportar una emergencia está permitido."},"ref":{"doc":"WV","page":18}},{"id":"wv-109","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how often may you get the 3-point reduction for an approved defensive driving class?","o":["Once in your life","Once every 6 months","Once every 12 months","Every time you take the class"],"h1":"It is once a year at most.","h2":"In West Virginia you may get the 3-point defensive driving reduction only once every 12 months.","p":"Right. Once every 12 months."},"es":{"q":"En Virginia Occidental, ¿cada cuánto puede recibir la reducción de 3 puntos por una clase aprobada de manejo defensivo?","o":["Una vez en la vida","Una vez cada 6 meses","Una vez cada 12 meses","Cada vez que toma la clase"],"h1":"Es como máximo una vez al año.","h2":"En Virginia Occidental solo puede recibir la reducción de 3 puntos por manejo defensivo una vez cada 12 meses.","p":"Correcto. Una vez cada 12 meses."},"ref":{"doc":"WV","page":18}},{"id":"wv-110","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, you take a defensive driving class before your new points appear on your record. Do you get the point reduction?","o":["No, the points must be on your record first","Yes, the points are removed when they appear","Yes, but only 1 point","Only if a judge agrees"],"h1":"Timing matters.","h2":"In West Virginia you are not eligible for the point deduction if you take the class before the points appear on your record.","p":"Right. The points must be on your record first."},"es":{"q":"En Virginia Occidental, usted toma una clase de manejo defensivo antes de que aparezcan sus nuevos puntos en el historial. ¿Recibe la reducción de puntos?","o":["No, los puntos deben estar primero en su historial","Sí, se quitan cuando aparezcan","Sí, pero solo 1 punto","Solo si un juez está de acuerdo"],"h1":"El momento importa.","h2":"En Virginia Occidental no tiene derecho a la reducción si toma la clase antes de que los puntos aparezcan en su historial.","p":"Correcto. Los puntos deben estar primero en su historial."},"ref":{"doc":"WV","page":18}},{"id":"wv-111","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, you get a speeding ticket while driving in another state. What happens?","o":["Nothing; it stays in the other state","It becomes part of your West Virginia record, and points may be added","You must get a license from that state","Only your insurance company is told"],"h1":"West Virginia belongs to the Driver License Compact.","h2":"In West Virginia traffic violations from other states become part of your West Virginia driving record, and points may be assessed, under the Driver License Compact.","p":"Right. It goes on your West Virginia record."},"es":{"q":"En Virginia Occidental, usted recibe una multa por exceso de velocidad mientras maneja en otro estado. ¿Qué pasa?","o":["Nada; se queda en el otro estado","Pasa a su historial de Virginia Occidental y le pueden poner puntos","Debe sacar licencia de ese estado","Solo se le avisa a su compañía de seguros"],"h1":"Virginia Occidental es parte del Driver License Compact.","h2":"En Virginia Occidental las infracciones de otros estados pasan a su historial de manejo de Virginia Occidental y le pueden poner puntos, según el Driver License Compact.","p":"Correcto. Pasa a su historial de Virginia Occidental."},"ref":{"doc":"WV","page":18}},{"id":"wv-112","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you never pay a traffic ticket you got in another state that is in the Non-Resident Violator Compact. What can happen?","o":["Nothing, the other state cannot reach you","The ticket is canceled after a year","You may only drive in West Virginia","West Virginia can suspend your license"],"h1":"Member states agree to act against their own drivers.","h2":"In West Virginia, under the Non-Resident Violator Compact, your license can be suspended if you fail to comply with a ticket from another member state.","p":"Right. West Virginia can suspend your license."},"es":{"q":"En Virginia Occidental, usted nunca paga una multa de tránsito que recibió en otro estado que es parte del Non-Resident Violator Compact. ¿Qué puede pasar?","o":["Nada, el otro estado no puede hacer nada","La multa se cancela después de un año","Solo puede manejar en Virginia Occidental","Virginia Occidental puede suspender su licencia"],"h1":"Los estados miembros acuerdan actuar contra sus propios conductores.","h2":"En Virginia Occidental, según el Non-Resident Violator Compact, le pueden suspender la licencia si no cumple con una multa de otro estado miembro.","p":"Correcto. Virginia Occidental puede suspender su licencia."},"ref":{"doc":"WV","page":18}},{"id":"wv-113","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, which of these can get your driver's license suspended even though it has nothing to do with driving?","o":["Failing to keep up with child support payments","Being late on your rent","Owing a library fine","Missing a doctor's appointment"],"h1":"State law ties it to a family court duty.","h2":"In West Virginia the DMV must suspend your driver's license if you fail to keep up with child support payments.","p":"Right. Unpaid child support can suspend your license."},"es":{"q":"En Virginia Occidental, ¿cuál de estas cosas puede causar la suspensión de su licencia aunque no tenga nada que ver con manejar?","o":["No cumplir con los pagos de manutención de los hijos","Atrasarse en el pago del alquiler","Deber una multa de la biblioteca","Faltar a una cita con el médico"],"h1":"La ley estatal lo relaciona con una obligación familiar.","h2":"En Virginia Occidental el DMV debe suspender su licencia si no cumple con los pagos de manutención de los hijos.","p":"Correcto. No pagar la manutención puede suspender su licencia."},"ref":{"doc":"WV","page":18}},{"id":"wv-114","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, you let a friend use your driver's license as their own. What is the penalty?","o":["A 90-day suspension","A $10 fine","A warning","Nothing, if it is only once"],"h1":"It is about three months.","h2":"In West Virginia letting someone else use your license, or using someone else's, is punished with a 90-day suspension.","p":"Right. A 90-day suspension."},"es":{"q":"En Virginia Occidental, usted deja que un amigo use su licencia como si fuera de él. ¿Cuál es la sanción?","o":["Una suspensión de 90 días","Una multa de $10","Una advertencia","Nada, si es solo una vez"],"h1":"Son unos tres meses.","h2":"En Virginia Occidental dejar que otra persona use su licencia, o usar la de otra persona, se castiga con una suspensión de 90 días.","p":"Correcto. Una suspensión de 90 días."},"ref":{"doc":"WV","page":18}},{"id":"wv-115","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, how many reckless driving convictions within 24 months lead to mandatory revocation of your license?","o":["Two","Three","Four","Five"],"h1":"It is more than two.","h2":"In West Virginia three reckless driving convictions within 24 months require the DMV to revoke your license.","p":"Right. Three convictions in 24 months."},"es":{"q":"En Virginia Occidental, ¿cuántas condenas por manejo imprudente en 24 meses llevan a la revocación obligatoria de la licencia?","o":["Dos","Tres","Cuatro","Cinco"],"h1":"Son más de dos.","h2":"En Virginia Occidental tres condenas por manejo imprudente en 24 meses obligan al DMV a revocar su licencia.","p":"Correcto. Tres condenas en 24 meses."},"ref":{"doc":"WV","page":19}},{"id":"wv-116","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, which of these leads to mandatory license revocation on a second conviction?","o":["Parking at an expired meter","Driving with a broken taillight","Forgetting to signal","Driving off without paying for gasoline"],"h1":"It happens at the gas pump.","h2":"In West Virginia a second conviction for failing to pay for gasoline requires revocation of your driver's license.","p":"Right. A second gas drive-off means revocation."},"es":{"q":"En Virginia Occidental, ¿cuál de estas acciones lleva a la revocación obligatoria de la licencia con una segunda condena?","o":["Estacionar con el parquímetro vencido","Manejar con una luz trasera rota","Olvidar poner la direccional","Irse sin pagar la gasolina"],"h1":"Pasa en la bomba de gasolina.","h2":"En Virginia Occidental una segunda condena por no pagar la gasolina obliga a revocar su licencia de manejar.","p":"Correcto. Una segunda vez sin pagar la gasolina significa revocación."},"ref":{"doc":"WV","page":19}},{"id":"wv-117","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what is the mandatory jail sentence for driving while your license is revoked for DUI?","o":["30 days to 6 months","None, only a fine","1 to 3 days","5 to 10 years"],"h1":"The minimum is about one month.","h2":"In West Virginia driving while your license is revoked for DUI carries a mandatory jail sentence of 30 days to six months.","p":"Right. 30 days to six months in jail."},"es":{"q":"En Virginia Occidental, ¿cuál es la pena de cárcel obligatoria por manejar con la licencia revocada por DUI?","o":["De 30 días a 6 meses","Ninguna, solo una multa","De 1 a 3 días","De 5 a 10 años"],"h1":"El mínimo es de un mes más o menos.","h2":"En Virginia Occidental manejar con la licencia revocada por DUI tiene una pena obligatoria de cárcel de 30 días a seis meses.","p":"Correcto. De 30 días a seis meses de cárcel."},"ref":{"doc":"WV","page":19}},{"id":"wv-118","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points are added to your record for fleeing from a police officer?","o":["3 points","6 points","8 points","12 points"],"h1":"It is the highest value on the point scale.","h2":"In West Virginia fleeing from an officer adds 8 points, the most of any offense on the point scale.","p":"Right. Fleeing an officer is 8 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos se agregan a su historial por huir de un oficial de policía?","o":["3 puntos","6 puntos","8 puntos","12 puntos"],"h1":"Es el valor más alto de la tabla de puntos.","h2":"En Virginia Occidental huir de un oficial agrega 8 puntos, el valor más alto de la tabla de puntos.","p":"Correcto. Huir de un oficial son 8 puntos."},"ref":{"doc":"WV","page":20}},{"id":"wv-119","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, how many points does a reckless driving conviction add to your record?","o":["2 points","3 points","6 points","8 points"],"h1":"It is the same as speeding in a school zone.","h2":"In West Virginia reckless driving adds 6 points to your record.","p":"Right. Reckless driving is 6 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos agrega a su historial una condena por manejo imprudente?","o":["2 puntos","3 puntos","6 puntos","8 puntos"],"h1":"Es igual que el exceso de velocidad en zona escolar.","h2":"En Virginia Occidental el manejo imprudente agrega 6 puntos a su historial.","p":"Correcto. El manejo imprudente son 6 puntos."},"ref":{"doc":"WV","page":20}},{"id":"wv-120","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, you are caught driving 17 mph over the speed limit. How many points is that?","o":["2 points","3 points","4 points","5 points"],"h1":"The scale has bands of 11 to 14, 15 to 19, and 20 or more over.","h2":"In West Virginia speeding 15 to 19 mph over the limit adds 5 points.","p":"Right. 15 to 19 mph over is 5 points."},"es":{"q":"En Virginia Occidental, lo detienen manejando 17 mph sobre el límite de velocidad. ¿Cuántos puntos son?","o":["2 puntos","3 puntos","4 puntos","5 puntos"],"h1":"La tabla tiene grupos de 11 a 14, de 15 a 19 y de 20 o más sobre el límite.","h2":"En Virginia Occidental exceder el límite por 15 a 19 mph agrega 5 puntos.","p":"Correcto. De 15 a 19 mph sobre el límite son 5 puntos."},"ref":{"doc":"WV","page":20}},{"id":"wv-121","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, how many points are added for speeding 12 mph over the limit?","o":["3 points","5 points","6 points","No points"],"h1":"It is the lowest speeding band on the scale.","h2":"In West Virginia speeding 11 to 14 mph over the limit adds 3 points.","p":"Right. 11 to 14 mph over is 3 points."},"es":{"q":"En Virginia Occidental, ¿cuántos puntos se agregan por manejar 12 mph sobre el límite?","o":["3 puntos","5 puntos","6 puntos","Ningún punto"],"h1":"Es el grupo de velocidad más bajo de la tabla.","h2":"En Virginia Occidental exceder el límite por 11 a 14 mph agrega 3 puntos.","p":"Correcto. De 11 a 14 mph sobre el límite son 3 puntos."},"ref":{"doc":"WV","page":20}},{"id":"wv-122","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, you drive with four passengers squeezed into the front seat beside you. How many points can this add to your record?","o":["None, it is not an offense","2 points","6 points","8 points"],"h1":"The point scale lists more than 3 passengers in the front seat.","h2":"In West Virginia having more than 3 passengers in the front seat is an offense worth 2 points.","p":"Right. It is 2 points."},"es":{"q":"En Virginia Occidental, usted maneja con cuatro pasajeros apretados a su lado en el asiento delantero. ¿Cuántos puntos le pueden agregar a su historial?","o":["Ninguno, no es una infracción","2 puntos","6 puntos","8 puntos"],"h1":"La tabla de puntos menciona más de 3 pasajeros en el asiento delantero.","h2":"En Virginia Occidental llevar más de 3 pasajeros en el asiento delantero es una infracción de 2 puntos.","p":"Correcto. Son 2 puntos."},"ref":{"doc":"WV","page":20}},{"id":"wv-123","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, a driver is convicted of leaving the scene of a crash in which someone was hurt. How long is the license revoked?","o":["30 days","Six months","One year","No revocation, only a fine"],"h1":"It is counted from the conviction or release from jail.","h2":"In West Virginia a driver convicted of leaving the scene of an injury crash has the license revoked for one year.","p":"Right. The license is revoked for one year."},"es":{"q":"En Virginia Occidental, condenan a un conductor por irse del lugar de un choque en el que alguien resultó herido. ¿Por cuánto tiempo se le revoca la licencia?","o":["30 días","Seis meses","Un año","No hay revocación, solo una multa"],"h1":"Se cuenta desde la condena o desde que sale de la cárcel.","h2":"En Virginia Occidental a un conductor condenado por irse del lugar de un choque con heridos se le revoca la licencia por un año.","p":"Correcto. La licencia se revoca por un año."},"ref":{"doc":"WV","page":null}},{"id":"wv-124","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, a driver's BAC is 0.06 percent. What does the law say?","o":["It is always legal under 0.08","It can be used as evidence that the driver's ability is impaired","It is only illegal for truck drivers","It means the driver is presumed under the influence"],"h1":"The handbook names a range between 0.05 and 0.08.","h2":"In West Virginia a BAC above 0.05 and below 0.08 percent is evidence that a person's ability to drive is impaired, and the license can be revoked below 0.08.","p":"Right. It can be evidence of impairment."},"es":{"q":"En Virginia Occidental, un conductor tiene un nivel de alcohol en la sangre (BAC) de 0.06 por ciento. ¿Qué dice la ley?","o":["Siempre es legal por debajo de 0.08","Se puede usar como prueba de que su capacidad de manejar está afectada","Solo es ilegal para choferes de camión","Significa que se presume que maneja bajo la influencia"],"h1":"El manual menciona un rango entre 0.05 y 0.08.","h2":"En Virginia Occidental un BAC de más de 0.05 y menos de 0.08 por ciento es prueba de que la capacidad de manejar está afectada, y se puede revocar la licencia por debajo de 0.08.","p":"Correcto. Puede ser prueba de que está afectado."},"ref":{"doc":"WV","page":21}},{"id":"wv-125","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, a 16-year-old is convicted of DUI. How long is the license revoked?","o":["30 days","Until age 21","6 months exactly","Until age 18 or the statutory period, whichever is longer"],"h1":"Two time limits are compared.","h2":"In West Virginia a DUI by a driver under 18 means revocation until age 18 or for the statutory period, whichever is longer.","p":"Right. Until 18 or the legal period, whichever is longer."},"es":{"q":"En Virginia Occidental, condenan por DUI a un joven de 16 años. ¿Por cuánto tiempo se le revoca la licencia?","o":["30 días","Hasta los 21 años","Exactamente 6 meses","Hasta los 18 años o el periodo de la ley, lo que sea más largo"],"h1":"Se comparan dos plazos.","h2":"En Virginia Occidental un DUI de un conductor menor de 18 años significa la revocación hasta los 18 años o por el periodo que marca la ley, lo que sea más largo.","p":"Correcto. Hasta los 18 o el periodo de la ley, lo que sea más largo."},"ref":{"doc":"WV","page":22}},{"id":"wv-126","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, what must you complete before you can reinstate a license revoked for DUI?","o":["A Safety and Treatment program","A new vision test only","A motorcycle course","Nothing, it comes back by itself"],"h1":"It is a program about alcohol and drugs.","h2":"In West Virginia anyone whose license is revoked or suspended for DUI must complete a prescribed Safety and Treatment program before reinstatement.","p":"Right. A Safety and Treatment program."},"es":{"q":"En Virginia Occidental, ¿qué debe completar antes de recuperar una licencia revocada por DUI?","o":["Un programa de Seguridad y Tratamiento","Solo un nuevo examen de la vista","Un curso de motocicleta","Nada, se recupera sola"],"h1":"Es un programa sobre alcohol y drogas.","h2":"En Virginia Occidental toda persona con la licencia revocada o suspendida por DUI debe completar un programa de Seguridad y Tratamiento antes de recuperarla.","p":"Correcto. Un programa de Seguridad y Tratamiento."},"ref":{"doc":"WV","page":22}},{"id":"wv-127","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the minimum license revocation for a first DUI with a BAC under 0.15?","o":["5 days","15 days","30 days","1 year"],"h1":"It is about two weeks.","h2":"In West Virginia a first DUI offense with a BAC under 0.15 carries a minimum revocation of 15 days.","p":"Right. At least 15 days."},"es":{"q":"En Virginia Occidental, ¿cuál es la revocación mínima de la licencia por un primer DUI con BAC menor de 0.15?","o":["5 días","15 días","30 días","1 año"],"h1":"Son unas dos semanas.","h2":"En Virginia Occidental un primer DUI con BAC menor de 0.15 tiene una revocación mínima de 15 días.","p":"Correcto. Al menos 15 días."},"ref":{"doc":"WV","page":22}},{"id":"wv-128","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the minimum license revocation for a first DUI with a BAC of 0.15 or higher?","o":["15 days","45 days","6 months","Lifetime"],"h1":"It is three times longer than for a lower BAC.","h2":"In West Virginia a first DUI with a BAC of 0.15 or more carries a minimum revocation of 45 days.","p":"Right. At least 45 days."},"es":{"q":"En Virginia Occidental, ¿cuál es la revocación mínima de la licencia por un primer DUI con BAC de 0.15 o más?","o":["15 días","45 días","6 meses","De por vida"],"h1":"Es tres veces más larga que con un BAC más bajo.","h2":"En Virginia Occidental un primer DUI con BAC de 0.15 o más tiene una revocación mínima de 45 días.","p":"Correcto. Al menos 45 días."},"ref":{"doc":"WV","page":22}},{"id":"wv-129","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, a 19-year-old is caught a second time driving with a measurable amount of alcohol. What is the minimum revocation?","o":["15 days","30 days","1 year","60 days or until age 18, whichever is greater"],"h1":"It is twice the first-offense minimum.","h2":"In West Virginia a second zero-tolerance offense by a driver under 21 carries a minimum revocation of 60 days or until the 18th birthday, whichever is greater.","p":"Right. At least 60 days."},"es":{"q":"En Virginia Occidental, detienen por segunda vez a un joven de 19 años manejando con una cantidad medible de alcohol. ¿Cuál es la revocación mínima?","o":["15 días","30 días","1 año","60 días o hasta los 18 años, lo que sea mayor"],"h1":"Es el doble del mínimo de la primera vez.","h2":"En Virginia Occidental una segunda infracción de tolerancia cero de un menor de 21 años tiene una revocación mínima de 60 días o hasta los 18 años, lo que sea mayor.","p":"Correcto. Al menos 60 días."},"ref":{"doc":"WV","page":22}},{"id":"wv-130","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, what is the fine for a first DUI offense with a BAC under 0.15?","o":["$100 to $500","$25 to $100","$1,000 to $3,000","$5,000"],"h1":"It is in the hundreds of dollars.","h2":"In West Virginia a first DUI offense with a BAC under 0.15 carries a fine of $100 to $500.","p":"Right. $100 to $500."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa por un primer DUI con BAC menor de 0.15?","o":["De $100 a $500","De $25 a $100","De $1,000 a $3,000","$5,000"],"h1":"Son cientos de dólares.","h2":"En Virginia Occidental un primer DUI con BAC menor de 0.15 tiene una multa de $100 a $500.","p":"Correcto. De $100 a $500."},"ref":{"doc":"WV","page":22}},{"id":"wv-131","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, what is the license revocation for a DUI that causes a death?","o":["60 days","1 year","5 years","Lifetime"],"h1":"It is the most severe revocation in the chart.","h2":"In West Virginia a DUI causing death is a felony with lifetime revocation of the license.","p":"Right. Lifetime revocation."},"es":{"q":"En Virginia Occidental, ¿cuál es la revocación de la licencia por un DUI que causa una muerte?","o":["60 días","1 año","5 años","De por vida"],"h1":"Es la revocación más grave de la tabla.","h2":"En Virginia Occidental un DUI que causa una muerte es un delito grave con revocación de la licencia de por vida.","p":"Correcto. Revocación de por vida."},"ref":{"doc":"WV","page":22}},{"id":"wv-132","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, what is the minimum license revocation for a second DUI offense?","o":["45 days","6 months","1 year","10 years"],"h1":"It is the same minimum as for a third offense.","h2":"In West Virginia a second DUI offense carries a minimum revocation of one year.","p":"Right. At least one year."},"es":{"q":"En Virginia Occidental, ¿cuál es la revocación mínima de la licencia por un segundo DUI?","o":["45 días","6 meses","1 año","10 años"],"h1":"Es el mismo mínimo que para un tercer DUI.","h2":"En Virginia Occidental un segundo DUI tiene una revocación mínima de un año.","p":"Correcto. Al menos un año."},"ref":{"doc":"WV","page":22}},{"id":"wv-133","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, what is the fine for a first zero-tolerance offense (under 21 with any measurable alcohol)?","o":["$25 to $100","$100 to $500","$500 to $1,000","No fine, only a warning"],"h1":"It is the lowest fine in the DUI chart.","h2":"In West Virginia a first zero-tolerance offense by a driver under 21 carries a fine of $25 to $100.","p":"Right. $25 to $100."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa por una primera infracción de tolerancia cero (menor de 21 años con cualquier cantidad medible de alcohol)?","o":["De $25 a $100","De $100 a $500","De $500 a $1,000","No hay multa, solo una advertencia"],"h1":"Es la multa más baja de la tabla de DUI.","h2":"En Virginia Occidental una primera infracción de tolerancia cero de un menor de 21 años tiene una multa de $25 a $100.","p":"Correcto. De $25 a $100."},"ref":{"doc":"WV","page":22}},{"id":"wv-134","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, a driver revoked for an alcohol DUI is approved for the Interlock Program before the revocation starts. What happens?","o":["They must still serve the full revocation","They may drive any car they want","They must wait one year to apply","They can install the device and keep driving, with no minimum revocation"],"h1":"Applying early matters.","h2":"In West Virginia a driver approved for the Interlock Program before the revocation begins does not serve a minimum revocation and can keep driving a vehicle with the device.","p":"Right. Apply early and keep driving with the device."},"es":{"q":"En Virginia Occidental, a un conductor revocado por DUI con alcohol lo aprueban para el Programa de Interlock antes de que empiece la revocación. ¿Qué pasa?","o":["Igual debe cumplir toda la revocación","Puede manejar cualquier carro","Debe esperar un año para solicitar","Puede instalar el dispositivo y seguir manejando, sin revocación mínima"],"h1":"Solicitar temprano es importante.","h2":"En Virginia Occidental un conductor aprobado para el Programa de Interlock antes de que empiece la revocación no cumple una revocación mínima y puede seguir manejando un vehículo con el dispositivo.","p":"Correcto. Si solicita temprano, sigue manejando con el dispositivo."},"ref":{"doc":"WV","page":23}},{"id":"wv-135","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the West Virginia handbook, after how many hours awake can your driving be like that of someone under the influence?","o":["8 hours","12 hours","18 hours","36 hours"],"h1":"It is less than a full day.","h2":"The West Virginia handbook says that after about 18 hours awake, driving skills can be like those of someone under the influence of drugs or alcohol.","p":"Right. About 18 hours awake."},"es":{"q":"Según el manual de Virginia Occidental, ¿después de cuántas horas despierto su manejo puede ser como el de alguien bajo la influencia?","o":["8 horas","12 horas","18 horas","36 horas"],"h1":"Es menos de un día completo.","h2":"El manual de Virginia Occidental dice que después de unas 18 horas despierto, la habilidad de manejar puede ser como la de alguien bajo la influencia de drogas o alcohol.","p":"Correcto. Unas 18 horas despierto."},"ref":{"doc":"WV","page":23}},{"id":"wv-136","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, you feel drowsy and pull over to nap. How long a nap can make a big difference?","o":["2 to 3 minutes","10 to 20 minutes","2 hours","A full night only"],"h1":"It is a short nap.","h2":"The West Virginia handbook says a nap of as little as 10 to 20 minutes can make a big difference when you are drowsy.","p":"Right. 10 to 20 minutes can help."},"es":{"q":"Según el manual de Virginia Occidental, usted tiene sueño y se detiene a dormir un poco. ¿Qué tan larga debe ser la siesta para hacer una gran diferencia?","o":["2 a 3 minutos","10 a 20 minutos","2 horas","Solo una noche completa"],"h1":"Es una siesta corta.","h2":"El manual de Virginia Occidental dice que una siesta de solo 10 a 20 minutos puede hacer una gran diferencia cuando tiene sueño.","p":"Correcto. De 10 a 20 minutos ayuda."},"ref":{"doc":"WV","page":23}},{"id":"wv-137","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, you have sight in only one eye. Can you pass the vision screening?","o":["Yes, if that eye sees 20/40 or better","No, you need two eyes","Only with telescopic lenses","Only for a motorcycle license"],"h1":"The same 20/40 standard applies.","h2":"In West Virginia a person with only one eye can pass the vision screening if that eye sees 20/40 or better.","p":"Right. One eye at 20/40 or better can pass."},"es":{"q":"En Virginia Occidental, usted ve solo con un ojo. ¿Puede pasar el examen de la vista?","o":["Sí, si ese ojo ve 20/40 o mejor","No, necesita los dos ojos","Solo con lentes telescópicos","Solo para licencia de motocicleta"],"h1":"Se usa el mismo estándar de 20/40.","h2":"En Virginia Occidental una persona con un solo ojo puede pasar el examen de la vista si ese ojo ve 20/40 o mejor.","p":"Correcto. Un ojo con 20/40 o mejor puede pasar."},"ref":{"doc":"WV","page":24}},{"id":"wv-138","scope":"WV","cat":"licensing","sign":null,"c":2,"en":{"q":"In West Virginia, you need glasses to reach 20/40 vision. What will your license show?","o":["Nothing different","Daylight driving only","A restriction code for corrective lenses","A shorter expiration date"],"h1":"It is a restriction on the front of the card.","h2":"In West Virginia if you need glasses or contacts to see 20/40 or better, your license shows a restriction code for corrective lenses.","p":"Right. A corrective lenses restriction."},"es":{"q":"En Virginia Occidental, usted necesita lentes para ver 20/40. ¿Qué mostrará su licencia?","o":["Nada diferente","Manejar solo de día","Un código de restricción por lentes correctivos","Una fecha de vencimiento más corta"],"h1":"Es una restricción en el frente de la tarjeta.","h2":"En Virginia Occidental si necesita anteojos o lentes de contacto para ver 20/40 o mejor, su licencia muestra un código de restricción por lentes correctivos.","p":"Correcto. Una restricción por lentes correctivos."},"ref":{"doc":"WV","page":24}},{"id":"wv-139","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, which lenses may NOT be used to meet the vision standard on the screening?","o":["Regular glasses","Contact lenses","Reading glasses worn over contacts","Bi-optic or telescopic lenses"],"h1":"They are special lens arrangements.","h2":"In West Virginia special lenses such as bi-optic or telescopic lenses may not be used to meet the visual acuity standard.","p":"Right. Bi-optic or telescopic lenses do not count."},"es":{"q":"En Virginia Occidental, ¿qué lentes NO se pueden usar para cumplir el estándar en el examen de la vista?","o":["Anteojos normales","Lentes de contacto","Lentes de lectura sobre lentes de contacto","Lentes biópticos o telescópicos"],"h1":"Son arreglos especiales de lentes.","h2":"En Virginia Occidental no se pueden usar lentes especiales, como los biópticos o telescópicos, para cumplir el estándar de agudeza visual.","p":"Correcto. Los lentes biópticos o telescópicos no cuentan."},"ref":{"doc":"WV","page":24}},{"id":"wv-140","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, the knowledge test is timed. What happens to questions you have not answered when time runs out?","o":["They are skipped and not counted","They count as incorrect","You get extra time","The test is canceled"],"h1":"Time matters on this test.","h2":"In West Virginia questions not answered within the time limit on the knowledge test are counted as incorrect.","p":"Right. Unanswered questions count as wrong."},"es":{"q":"En Virginia Occidental, el examen de conocimientos tiene tiempo límite. ¿Qué pasa con las preguntas que no contestó cuando se acaba el tiempo?","o":["Se saltan y no cuentan","Cuentan como incorrectas","Le dan más tiempo","Se cancela el examen"],"h1":"El tiempo importa en este examen.","h2":"En Virginia Occidental las preguntas que no se contestan dentro del tiempo límite cuentan como incorrectas.","p":"Correcto. Las preguntas sin contestar cuentan como incorrectas."},"ref":{"doc":"WV","page":24}},{"id":"wv-141","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, a person who has trouble reading takes the audio version of the knowledge test. How is it given?","o":["With headphones; staff may not read or explain the questions","A DMV worker reads the questions aloud","A friend may read the questions","It is an easier test with fewer questions"],"h1":"The same rules apply as for the printed test.","h2":"In West Virginia the audio knowledge test is given with headphones, and DMV employees may not read, reword or explain the questions.","p":"Right. Headphones, and no extra help from staff."},"es":{"q":"En Virginia Occidental, una persona con dificultad para leer toma la versión en audio del examen de conocimientos. ¿Cómo se da?","o":["Con audífonos; el personal no puede leer ni explicar las preguntas","Un empleado del DMV lee las preguntas en voz alta","Un amigo puede leer las preguntas","Es un examen más fácil con menos preguntas"],"h1":"Se aplican las mismas reglas que en el examen impreso.","h2":"En Virginia Occidental el examen de conocimientos en audio se da con audífonos, y los empleados del DMV no pueden leer, cambiar ni explicar las preguntas.","p":"Correcto. Con audífonos y sin ayuda extra del personal."},"ref":{"doc":"WV","page":24}},{"id":"wv-142","scope":"WV","cat":"licensing","sign":null,"c":0,"en":{"q":"In West Virginia, what short course must first-time driver's license applicants complete after passing the road skills test?","o":["A DUI awareness course","A first aid course","A motorcycle safety course","A car repair course"],"h1":"You get a card or a stamp when you finish.","h2":"In West Virginia first-time applicants complete a short DUI awareness course after passing the road skills test.","p":"Right. A short DUI awareness course."},"es":{"q":"En Virginia Occidental, ¿qué curso corto deben completar los solicitantes de licencia por primera vez después de pasar el examen de manejo?","o":["Un curso de concientización sobre DUI","Un curso de primeros auxilios","Un curso de seguridad en motocicleta","Un curso de reparación de carros"],"h1":"Al terminar recibe una tarjeta o un sello.","h2":"En Virginia Occidental los solicitantes por primera vez completan un curso corto de concientización sobre DUI después de pasar el examen de manejo.","p":"Correcto. Un curso corto sobre DUI."},"ref":{"doc":"WV","page":25}},{"id":"wv-143","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, what must the car you bring for the road skills test have?","o":["Tinted windows","A valid inspection sticker and proof of insurance","A backup camera","A sunroof"],"h1":"The examiner checks it before you start.","h2":"In West Virginia a road test vehicle must have a valid inspection sticker and proof of insurance, and it must be legally equipped.","p":"Right. A valid inspection sticker and insurance."},"es":{"q":"En Virginia Occidental, ¿qué debe tener el carro que trae para el examen de manejo?","o":["Vidrios polarizados","Una calcomanía de inspección vigente y prueba de seguro","Una cámara de reversa","Un techo corredizo"],"h1":"El examinador lo revisa antes de empezar.","h2":"En Virginia Occidental el vehículo del examen de manejo debe tener una calcomanía de inspección vigente y prueba de seguro, y debe estar equipado según la ley.","p":"Correcto. Calcomanía de inspección vigente y seguro."},"ref":{"doc":"WV","page":25}},{"id":"wv-144","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, your test car has a defect and cannot be used for the road test. May you switch to another car that same day?","o":["Yes, any car","Yes, if a parent brings it","Only if it is a rental","No, not on the same test date"],"h1":"The examiner may allow a minor fix, but not a new car.","h2":"In West Virginia you may not continue the road test in another vehicle on the same test date.","p":"Right. Not on the same day."},"es":{"q":"En Virginia Occidental, su carro de examen tiene un defecto y no se puede usar para el examen de manejo. ¿Puede cambiar a otro carro ese mismo día?","o":["Sí, cualquier carro","Sí, si un padre lo trae","Solo si es alquilado","No, no en la misma fecha del examen"],"h1":"El examinador puede permitir un arreglo menor, pero no otro carro.","h2":"En Virginia Occidental no puede continuar el examen de manejo en otro vehículo en la misma fecha.","p":"Correcto. No el mismo día."},"ref":{"doc":"WV","page":25}},{"id":"wv-145","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, which of these is illegal equipment on a passenger car?","o":["More than one spotlight","Two backup lights","A working horn","Seat belts in the back seat"],"h1":"Count the lights.","h2":"In West Virginia a car may not have more than one spotlight.","p":"Right. More than one spotlight is illegal."},"es":{"q":"En Virginia Occidental, ¿cuál de estos es un equipo ilegal en un carro de pasajeros?","o":["Más de un reflector (spotlight)","Dos luces de reversa","Una bocina que funciona","Cinturones en el asiento trasero"],"h1":"Cuente las luces.","h2":"En Virginia Occidental un carro no puede tener más de un reflector (spotlight).","p":"Correcto. Más de un reflector es ilegal."},"ref":{"doc":"WV","page":25}},{"id":"wv-146","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, how far may a load stick out beyond the fenders on the RIGHT side of a passenger car?","o":["Not at all","6 inches","2 feet","3 feet"],"h1":"It is less than a foot. On the left side, it may not stick out at all.","h2":"In West Virginia a load may not extend beyond the left fenders at all, or more than six inches beyond the right fenders, of a passenger car.","p":"Right. No more than six inches on the right."},"es":{"q":"En Virginia Occidental, ¿cuánto puede sobresalir una carga de los guardafangos del lado DERECHO de un carro de pasajeros?","o":["Nada","6 pulgadas","2 pies","3 pies"],"h1":"Es menos de un pie. Del lado izquierdo no puede sobresalir nada.","h2":"En Virginia Occidental una carga no puede sobresalir nada de los guardafangos izquierdos, ni más de seis pulgadas de los derechos, en un carro de pasajeros.","p":"Correcto. No más de seis pulgadas a la derecha."},"ref":{"doc":"WV","page":25}},{"id":"wv-147","scope":"WV","cat":"licensing","sign":null,"c":1,"en":{"q":"In West Virginia, which window must work on the car you use for the road test?","o":["The sunroof","The driver side window","The rear window","None of them"],"h1":"The examiner may need you to signal by hand.","h2":"In West Virginia the driver side window must be operational on a road test vehicle.","p":"Right. The driver side window must work."},"es":{"q":"En Virginia Occidental, ¿qué ventana debe funcionar en el carro que usa para el examen de manejo?","o":["El techo corredizo","La ventana del lado del conductor","La ventana trasera","Ninguna"],"h1":"Puede necesitar hacer señales con la mano.","h2":"En Virginia Occidental la ventana del lado del conductor debe funcionar en el vehículo del examen de manejo.","p":"Correcto. La ventana del conductor debe funcionar."},"ref":{"doc":"WV","page":26}},{"id":"wv-148","scope":"WV","cat":"licensing","sign":null,"c":3,"en":{"q":"In West Virginia, what happens if you use your phone at any time during the road skills test?","o":["You lose 5 points","You get a warning","You must restart the test","You fail automatically"],"h1":"It is on the list of automatic failures.","h2":"In West Virginia using a wireless communication device at any time during the road test is an automatic failure.","p":"Right. Using a phone is an automatic failure."},"es":{"q":"En Virginia Occidental, ¿qué pasa si usa su teléfono en cualquier momento durante el examen de manejo?","o":["Pierde 5 puntos","Recibe una advertencia","Debe empezar el examen de nuevo","Reprueba automáticamente"],"h1":"Está en la lista de errores que reprueban automáticamente.","h2":"En Virginia Occidental usar un dispositivo de comunicación inalámbrica en cualquier momento del examen de manejo significa reprobar automáticamente.","p":"Correcto. Usar el teléfono reprueba automáticamente."},"ref":{"doc":"WV","page":31}},{"id":"wv-149","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, you want to put red and blue flashing lights on your personal car. Is that allowed?","o":["Yes, if they face backward","Yes, at night only","No, only authorized emergency vehicles may have them","Yes, if you pay a small permit fee"],"h1":"These colors are kept for one kind of vehicle.","h2":"In West Virginia red or blue flashing lights are illegal equipment unless the vehicle is an authorized emergency vehicle.","p":"Right. Only authorized emergency vehicles may have them."},"es":{"q":"En Virginia Occidental, usted quiere poner luces intermitentes rojas y azules en su carro personal. ¿Está permitido?","o":["Sí, si miran hacia atrás","Sí, solo de noche","No, solo los vehículos de emergencia autorizados pueden tenerlas","Sí, si paga una pequeña tarifa de permiso"],"h1":"Estos colores están reservados para un tipo de vehículo.","h2":"En Virginia Occidental las luces intermitentes rojas o azules son equipo ilegal a menos que el vehículo sea un vehículo de emergencia autorizado.","p":"Correcto. Solo los vehículos de emergencia autorizados pueden tenerlas."},"ref":{"doc":"WV","page":25}},{"id":"wv-150","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the West Virginia road test rules, how should you hold the steering wheel?","o":["Both hands on the outside of the wheel, with no palming","One hand on top of the wheel","Palm flat in the center of the wheel","With your elbow resting in the window"],"h1":"Hand-over-hand and hand-to-hand steering are both fine.","h2":"On the West Virginia road test you must keep both hands on the outside of the steering wheel, and palming the wheel is not allowed.","p":"Right. Both hands outside the wheel, no palming."},"es":{"q":"Según las reglas del examen de manejo de Virginia Occidental, ¿cómo debe sostener el volante?","o":["Con las dos manos por fuera del volante, sin girarlo con la palma","Con una mano arriba del volante","Con la palma plana en el centro del volante","Con el codo apoyado en la ventana"],"h1":"Girar mano sobre mano o mano a mano está bien.","h2":"En el examen de manejo de Virginia Occidental debe tener las dos manos por fuera del volante, y no se permite girarlo con la palma.","p":"Correcto. Las dos manos por fuera, sin usar la palma."},"ref":{"doc":"WV","page":30}},{"id":"wv-151","scope":"WV","cat":"signs","sign":null,"c":3,"en":{"q":"In West Virginia, what does a triangle sign with a reflective red border and a fluorescent orange center mean on the back of a vehicle?","o":["A school bus","A truck carrying fuel","A police vehicle","A slow-moving vehicle, or one that has made an emergency stop"],"h1":"You often see it on farm equipment.","h2":"In West Virginia a right-side-up triangle with a red border and orange center marks a slow-moving vehicle or a vehicle that has made an emergency stop.","p":"Right. It marks a slow-moving or emergency-stopped vehicle."},"es":{"q":"En Virginia Occidental, ¿qué significa una señal triangular con borde rojo reflectante y centro anaranjado fluorescente en la parte trasera de un vehículo?","o":["Un autobús escolar","Un camión que lleva combustible","Un vehículo de policía","Un vehículo lento, o uno que hizo una parada de emergencia"],"h1":"Se ve mucho en maquinaria agrícola.","h2":"En Virginia Occidental un triángulo con la punta hacia arriba, borde rojo y centro anaranjado marca un vehículo lento o un vehículo que hizo una parada de emergencia.","p":"Correcto. Marca un vehículo lento o detenido por emergencia."},"ref":{"doc":"WV","page":34}},{"id":"wv-152","scope":"WV","cat":"signs","sign":null,"c":0,"en":{"q":"In a West Virginia work zone, the diagonal stripes on a barricade slope downward to the right. What should you do?","o":["Bear to the right","Bear to the left","Stop and wait","Speed up"],"h1":"The stripes point the way traffic should pass.","h2":"In West Virginia stripes on a barricade or panel that slope downward to the right mean you should bear to the right.","p":"Right. Stripes sloping down to the right mean bear right."},"es":{"q":"En una zona de trabajo de Virginia Occidental, las franjas diagonales de una barrera bajan hacia la derecha. ¿Qué debe hacer?","o":["Desviarse hacia la derecha","Desviarse hacia la izquierda","Detenerse y esperar","Acelerar"],"h1":"Las franjas indican por dónde debe pasar el tránsito.","h2":"En Virginia Occidental las franjas de una barrera o panel que bajan hacia la derecha indican que debe desviarse hacia la derecha.","p":"Correcto. Franjas que bajan a la derecha significan ir a la derecha."},"ref":{"doc":"WV","page":37}},{"id":"wv-153","scope":"WV","cat":"signals","sign":null,"c":0,"en":{"q":"In West Virginia, you are on a one-way street at a red light and want to turn left onto another one-way street. What may you do?","o":["Stop, yield to traffic and pedestrians, then turn left unless a sign forbids it","You may never turn left on red","Turn left without stopping","Turn left only if a police officer waves you on"],"h1":"It works like a right turn on red.","h2":"In West Virginia you may turn left on red from a one-way street onto another one-way street after stopping and yielding, unless a sign prohibits it.","p":"Right. Stop, yield, then turn unless a sign says no."},"es":{"q":"En Virginia Occidental, usted está en una calle de un solo sentido con el semáforo en rojo y quiere girar a la izquierda hacia otra calle de un solo sentido. ¿Qué puede hacer?","o":["Detenerse, ceder el paso al tránsito y a los peatones, y girar a la izquierda si ninguna señal lo prohíbe","Nunca puede girar a la izquierda en rojo","Girar a la izquierda sin detenerse","Girar a la izquierda solo si un policía le hace señas"],"h1":"Funciona como girar a la derecha en rojo.","h2":"En Virginia Occidental puede girar a la izquierda en rojo de una calle de un solo sentido a otra de un solo sentido después de detenerse y ceder el paso, si ninguna señal lo prohíbe.","p":"Correcto. Deténgase, ceda el paso y gire si no hay señal que lo prohíba."},"ref":{"doc":"WV","page":39}},{"id":"wv-154","scope":"WV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In West Virginia, a blind person with a white cane or guide dog starts to cross the street away from a crosswalk. Who has the right-of-way?","o":["You do, because they are not in a crosswalk","The blind person","Whoever is moving faster","Only a person in a marked crosswalk"],"h1":"The rule applies whether or not they are in a crosswalk.","h2":"In West Virginia a blind pedestrian using a white cane, walking stick or guide dog has the right-of-way, whether or not they are in a crosswalk.","p":"Right. The blind pedestrian has the right-of-way."},"es":{"q":"En Virginia Occidental, una persona ciega con bastón blanco o perro guía empieza a cruzar la calle lejos de un cruce peatonal. ¿Quién tiene el derecho de paso?","o":["Usted, porque no está en un cruce peatonal","La persona ciega","El que va más rápido","Solo una persona en un cruce marcado"],"h1":"La regla se aplica esté o no en un cruce peatonal.","h2":"En Virginia Occidental un peatón ciego que usa bastón blanco o perro guía tiene el derecho de paso, esté o no en un cruce peatonal.","p":"Correcto. La persona ciega tiene el derecho de paso."},"ref":{"doc":"WV","page":40}},{"id":"wv-155","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, what is the speed limit on an open country highway unless another limit is posted?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"It is 15 mph less than the interstate.","h2":"In West Virginia the speed limit on an open country highway is 55 mph unless otherwise posted.","p":"Right. 55 mph on open country highways."},"es":{"q":"En Virginia Occidental, ¿cuál es el límite de velocidad en una carretera rural abierta si no hay otro límite indicado?","o":["45 mph","50 mph","55 mph","65 mph"],"h1":"Son 15 mph menos que en la interestatal.","h2":"En Virginia Occidental el límite de velocidad en una carretera rural abierta es de 55 mph si no se indica otro.","p":"Correcto. 55 mph en carreteras rurales abiertas."},"ref":{"doc":"WV","page":42}},{"id":"wv-156","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In West Virginia, what is the speed limit in a business or residential area unless another limit is posted?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"It is higher than a school zone but lower than 30.","h2":"In West Virginia the speed limit in business and residential areas is 25 mph unless otherwise posted.","p":"Right. 25 mph in business and residential areas."},"es":{"q":"En Virginia Occidental, ¿cuál es el límite de velocidad en una zona comercial o residencial si no hay otro límite indicado?","o":["15 mph","25 mph","35 mph","45 mph"],"h1":"Es más que en una zona escolar pero menos de 30.","h2":"En Virginia Occidental el límite de velocidad en zonas comerciales y residenciales es de 25 mph si no se indica otro.","p":"Correcto. 25 mph en zonas comerciales y residenciales."},"ref":{"doc":"WV","page":42}},{"id":"wv-157","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, when may an ambulance or fire truck go faster than the speed limit?","o":["Any time it wants","Only on interstates","Only at night","On an emergency run with its signal equipment on, without endangering others"],"h1":"Two conditions must be met.","h2":"In West Virginia an authorized emergency vehicle may exceed the speed limit on emergency duty with its emergency signals operating, as long as others are not endangered.","p":"Right. On an emergency, with signals on, safely."},"es":{"q":"En Virginia Occidental, ¿cuándo puede una ambulancia o un camión de bomberos ir más rápido que el límite de velocidad?","o":["Cuando quiera","Solo en las interestatales","Solo de noche","En una emergencia con sus luces y sirena encendidas, sin poner en peligro a otros"],"h1":"Se deben cumplir dos condiciones.","h2":"En Virginia Occidental un vehículo de emergencia autorizado puede exceder el límite en servicio de emergencia con sus señales encendidas, siempre que no ponga en peligro a otros.","p":"Correcto. En una emergencia, con señales encendidas y con seguridad."},"ref":{"doc":"WV","page":42}},{"id":"wv-158","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In West Virginia, you are driving slowly on a road with one lane each way, and faster cars cannot pass. What should you do?","o":["Speed up past the limit","Pull off at the first safe turnout to let them pass","Turn on your high beams","Stop in your lane"],"h1":"Help the line behind you get by.","h2":"In West Virginia a slow driver on a road with one lane each way should pull off at the first safe turnout to let faster traffic pass.","p":"Right. Use the first safe turnout."},"es":{"q":"En Virginia Occidental, usted maneja despacio en una carretera de un carril en cada sentido y los carros más rápidos no pueden pasar. ¿Qué debe hacer?","o":["Acelerar por encima del límite","Salirse en el primer lugar seguro para dejarlos pasar","Encender las luces altas","Detenerse en su carril"],"h1":"Ayude a la fila de atrás a pasar.","h2":"En Virginia Occidental un conductor lento en una carretera de un carril en cada sentido debe salirse en el primer lugar seguro para dejar pasar al tránsito más rápido.","p":"Correcto. Use el primer lugar seguro para salirse."},"ref":{"doc":"WV","page":43}},{"id":"wv-159","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, how far before a turn should you start signaling?","o":["At least 25 feet","Only as you turn","At least 100 feet","At least half a mile"],"h1":"It is about the length of a third of a football field.","h2":"In West Virginia you should signal at least 100 feet before you turn.","p":"Right. Signal at least 100 feet before."},"es":{"q":"En Virginia Occidental, ¿a qué distancia antes de girar debe empezar a poner la direccional?","o":["Al menos 25 pies","Solo al girar","Al menos 100 pies","Al menos media milla"],"h1":"Es como un tercio de una cancha de fútbol americano.","h2":"En Virginia Occidental debe poner la direccional al menos 100 pies antes de girar.","p":"Correcto. Al menos 100 pies antes."},"ref":{"doc":"WV","page":43}},{"id":"wv-160","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the West Virginia handbook, where should your hands be on the steering wheel?","o":["Left hand near 8 o'clock, right hand near 4 o'clock","Both hands at 12 o'clock","One hand at the bottom","Left hand at 10, right hand on the gear shift"],"h1":"Picture a clock face, a little lower than you might think.","h2":"The West Virginia handbook says to hold the wheel with the left hand near 8 o'clock and the right hand near 4 o'clock, which also keeps your hands safer if the air bag opens.","p":"Right. Hands at about 8 and 4 o'clock."},"es":{"q":"Según el manual de Virginia Occidental, ¿dónde deben estar sus manos en el volante?","o":["La mano izquierda cerca de las 8 y la derecha cerca de las 4","Las dos manos a las 12","Una mano abajo","La izquierda a las 10 y la derecha en la palanca de cambios"],"h1":"Imagine la cara de un reloj, un poco más abajo de lo que cree.","h2":"El manual de Virginia Occidental dice que sostenga el volante con la mano izquierda cerca de las 8 y la derecha cerca de las 4, lo que también protege sus manos si se abre la bolsa de aire.","p":"Correcto. Las manos más o menos a las 8 y a las 4."},"ref":{"doc":"WV","page":43}},{"id":"wv-161","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"According to the West Virginia handbook, you are stopped, waiting to turn left. How should your front wheels point?","o":["Turned to the left","Turned to the right","Toward the curb","Straight ahead"],"h1":"Think about what happens if a car bumps you from behind.","h2":"The West Virginia handbook says to keep your wheels straight while waiting to turn left, so a bump from behind will not push you into oncoming traffic.","p":"Right. Keep the wheels straight."},"es":{"q":"Según el manual de Virginia Occidental, usted está detenido esperando para girar a la izquierda. ¿Hacia dónde deben apuntar sus ruedas delanteras?","o":["Giradas a la izquierda","Giradas a la derecha","Hacia la acera","Derechas, hacia adelante"],"h1":"Piense qué pasa si un carro lo golpea por detrás.","h2":"El manual de Virginia Occidental dice que mantenga las ruedas derechas mientras espera para girar a la izquierda, para que un golpe por detrás no lo empuje hacia el tránsito que viene de frente.","p":"Correcto. Mantenga las ruedas derechas."},"ref":{"doc":"WV","page":44}},{"id":"wv-162","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, it is illegal to turn around near a curve or hill crest where other drivers cannot see you within how many feet?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is the same distance as dimming for oncoming cars.","h2":"In West Virginia you may not turn around near a curve or the crest of a hill where an approaching driver cannot see you within 500 feet in either direction.","p":"Right. 500 feet."},"es":{"q":"En Virginia Occidental, es ilegal dar la vuelta cerca de una curva o la cima de una colina donde otros conductores no lo pueden ver a menos de cuántos pies?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es la misma distancia que para bajar las luces ante carros de frente.","h2":"En Virginia Occidental no puede dar la vuelta cerca de una curva o la cima de una colina donde un conductor que se acerca no lo pueda ver a 500 pies en cualquier dirección.","p":"Correcto. 500 pies."},"ref":{"doc":"WV","page":45}},{"id":"wv-163","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, you may not park within how many feet of a crosswalk at an intersection?","o":["10 feet","15 feet","20 feet","50 feet"],"h1":"It is a little more than the fire hydrant distance.","h2":"In West Virginia you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. 20 feet from a crosswalk."},"es":{"q":"En Virginia Occidental, ¿a menos de cuántos pies de un cruce peatonal en una intersección no puede estacionarse?","o":["10 pies","15 pies","20 pies","50 pies"],"h1":"Es un poco más que la distancia de un hidrante.","h2":"En Virginia Occidental no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. 20 pies de un cruce peatonal."},"ref":{"doc":"WV","page":45}},{"id":"wv-164","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, you may not park within how many feet of a stop sign or traffic signal?","o":["15 feet","20 feet","30 feet","100 feet"],"h1":"It is more than the crosswalk distance.","h2":"In West Virginia you may not park within 30 feet of a stop sign or traffic control signal.","p":"Right. 30 feet from a stop sign or signal."},"es":{"q":"En Virginia Occidental, ¿a menos de cuántos pies de una señal de alto o un semáforo no puede estacionarse?","o":["15 pies","20 pies","30 pies","100 pies"],"h1":"Es más que la distancia de un cruce peatonal.","h2":"En Virginia Occidental no puede estacionarse a menos de 30 pies de una señal de alto o un semáforo.","p":"Correcto. 30 pies de una señal de alto o semáforo."},"ref":{"doc":"WV","page":45}},{"id":"wv-165","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, you may not park within how many feet of the nearest rail of a railroad crossing?","o":["10 feet","20 feet","30 feet","50 feet"],"h1":"It is the largest of these distances.","h2":"In West Virginia you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. 50 feet from the nearest rail."},"es":{"q":"En Virginia Occidental, ¿a menos de cuántos pies del riel más cercano de un cruce de ferrocarril no puede estacionarse?","o":["10 pies","20 pies","30 pies","50 pies"],"h1":"Es la mayor de estas distancias.","h2":"En Virginia Occidental no puede estacionarse a menos de 50 pies del riel más cercano de un cruce de ferrocarril.","p":"Correcto. 50 pies del riel más cercano."},"ref":{"doc":"WV","page":45}},{"id":"wv-166","scope":"WV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In West Virginia, which of these is a place where you may NOT stop or park?","o":["On a bridge or in a highway tunnel","Along a curb on a quiet street","In a marked parking space","In a parking lot"],"h1":"Think about elevated structures.","h2":"In West Virginia you may not stop, stand or park on a bridge or other elevated structure or in a highway tunnel.","p":"Right. Not on a bridge or in a tunnel."},"es":{"q":"En Virginia Occidental, ¿en cuál de estos lugares NO puede detenerse ni estacionarse?","o":["En un puente o en un túnel de carretera","Junto a la acera en una calle tranquila","En un espacio de estacionamiento marcado","En un estacionamiento"],"h1":"Piense en estructuras elevadas.","h2":"En Virginia Occidental no puede detenerse ni estacionarse en un puente u otra estructura elevada ni en un túnel de carretera.","p":"Correcto. No en un puente ni en un túnel."},"ref":{"doc":"WV","page":46}},{"id":"wv-167","scope":"WV","cat":"signals","sign":null,"c":2,"en":{"q":"In West Virginia, what does a curb painted yellow usually mean?","o":["Loading zone for buses only","Parking for 15 minutes","No parking","Parking for people with disabilities"],"h1":"It marks a zone where official signs could also forbid something.","h2":"In West Virginia a curb in a no-parking zone may be painted yellow.","p":"Right. A yellow curb means no parking."},"es":{"q":"En Virginia Occidental, ¿qué significa normalmente una acera pintada de amarillo?","o":["Zona de carga solo para autobuses","Estacionamiento por 15 minutos","Prohibido estacionarse","Estacionamiento para personas con discapacidad"],"h1":"Marca una zona donde las señales oficiales también podrían prohibir algo.","h2":"En Virginia Occidental la acera de una zona donde se prohíbe estacionarse puede estar pintada de amarillo.","p":"Correcto. Una acera amarilla significa prohibido estacionarse."},"ref":{"doc":"WV","page":46}},{"id":"wv-168","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, as you get ready to pull into an angle parking space on your right, how far out from the parked cars should you stay?","o":["1 foot","At least 5 feet","At least 15 feet","Right next to them"],"h1":"Leave room to swing in.","h2":"The West Virginia handbook says to stay parallel to the curb at least five feet out from the parked vehicles before turning into an angle space.","p":"Right. At least five feet out."},"es":{"q":"Según el manual de Virginia Occidental, al prepararse para entrar a un espacio de estacionamiento en ángulo a su derecha, ¿a qué distancia de los carros estacionados debe mantenerse?","o":["1 pie","Al menos 5 pies","Al menos 15 pies","Justo al lado de ellos"],"h1":"Deje espacio para girar.","h2":"El manual de Virginia Occidental dice que se mantenga paralelo a la acera, al menos a cinco pies de los vehículos estacionados, antes de girar hacia un espacio en ángulo.","p":"Correcto. Al menos cinco pies."},"ref":{"doc":"WV","page":46}},{"id":"wv-169","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In West Virginia, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Toward the curb","Straight ahead","It does not matter","Away from the curb"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In West Virginia when you park uphill with a curb, turn your front wheels away from the curb.","p":"Right. Uphill with a curb: wheels away from the curb."},"es":{"q":"En Virginia Occidental, usted se estaciona cuesta arriba junto a una acera. ¿Hacia dónde debe girar las ruedas delanteras?","o":["Hacia la acera","Derechas","No importa","Lejos de la acera"],"h1":"Si el carro rueda hacia atrás, la parte de atrás de la llanta delantera debe chocar con la acera.","h2":"En Virginia Occidental cuando se estaciona cuesta arriba con acera, gire las ruedas delanteras lejos de la acera.","p":"Correcto. Cuesta arriba con acera: ruedas lejos de la acera."},"ref":{"doc":"WV","page":46}},{"id":"wv-170","scope":"WV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"According to the West Virginia handbook, you park on a downhill slope in a car with a manual transmission. Which gear should you leave it in?","o":["Reverse","First gear","Neutral","Third gear"],"h1":"Choose the gear that pushes against rolling forward.","h2":"The West Virginia handbook says to leave a manual-shift car in reverse on a downgrade, along with the parking brake.","p":"Right. Reverse on a downhill slope."},"es":{"q":"Según el manual de Virginia Occidental, usted se estaciona en una bajada con un carro de transmisión manual. ¿En qué cambio debe dejarlo?","o":["Reversa","Primera","Neutro","Tercera"],"h1":"Elija el cambio que empuja contra el movimiento hacia adelante.","h2":"El manual de Virginia Occidental dice que deje un carro de cambios manuales en reversa en una bajada, además del freno de estacionamiento.","p":"Correcto. Reversa en una bajada."},"ref":{"doc":"WV","page":46}},{"id":"wv-171","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, when you parallel park, how close to the curb must your wheels be?","o":["Within 6 feet","Within 3 feet","Within 18 inches","Touching the curb"],"h1":"It is a foot and a half.","h2":"In West Virginia when you parallel park, your wheels must be within 18 inches of the curb.","p":"Right. Within 18 inches of the curb."},"es":{"q":"En Virginia Occidental, cuando se estaciona en paralelo, ¿qué tan cerca de la acera deben estar sus ruedas?","o":["A menos de 6 pies","A menos de 3 pies","A menos de 18 pulgadas","Tocando la acera"],"h1":"Es un pie y medio.","h2":"En Virginia Occidental cuando se estaciona en paralelo, sus ruedas deben estar a menos de 18 pulgadas de la acera.","p":"Correcto. A menos de 18 pulgadas de la acera."},"ref":{"doc":"WV","page":47}},{"id":"wv-172","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, what following distance should you keep in normal conditions?","o":["1 to 2 seconds","3 to 4 seconds","8 to 10 seconds","One car length for every 20 mph"],"h1":"Count \"one thousand one\" as the car ahead passes a sign.","h2":"The West Virginia handbook says to use the three-to-four second rule for following distance.","p":"Right. Three to four seconds."},"es":{"q":"Según el manual de Virginia Occidental, ¿qué distancia debe mantener con el carro de adelante en condiciones normales?","o":["1 a 2 segundos","3 a 4 segundos","8 a 10 segundos","Un carro de largo por cada 20 mph"],"h1":"Cuente \"mil uno\" cuando el carro de adelante pase una señal.","h2":"El manual de Virginia Occidental dice que use la regla de tres a cuatro segundos para la distancia de seguimiento.","p":"Correcto. De tres a cuatro segundos."},"ref":{"doc":"WV","page":47}},{"id":"wv-173","scope":"WV","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"According to the West Virginia handbook, it is dark or raining. What following distance should you keep?","o":["At least 4 seconds","At least 2 seconds","Exactly 3 seconds","At least 10 seconds"],"h1":"Add time to the normal rule.","h2":"The West Virginia handbook says the following distance should be at least four seconds when it is dark or raining.","p":"Right. At least four seconds."},"es":{"q":"Según el manual de Virginia Occidental, está oscuro o lloviendo. ¿Qué distancia de seguimiento debe mantener?","o":["Al menos 4 segundos","Al menos 2 segundos","Exactamente 3 segundos","Al menos 10 segundos"],"h1":"Agregue tiempo a la regla normal.","h2":"El manual de Virginia Occidental dice que la distancia de seguimiento debe ser de al menos cuatro segundos cuando está oscuro o lloviendo.","p":"Correcto. Al menos cuatro segundos."},"ref":{"doc":"WV","page":47}},{"id":"wv-174","scope":"WV","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"According to the West Virginia handbook, there is ice or snow on the road. How far behind the car ahead should you stay?","o":["2 seconds","3 seconds","4 seconds","At least 6 seconds"],"h1":"It is the longest gap in the handbook.","h2":"The West Virginia handbook says to stay at least six seconds behind the vehicle ahead on ice or snow.","p":"Right. At least six seconds."},"es":{"q":"Según el manual de Virginia Occidental, hay hielo o nieve en la carretera. ¿A qué distancia del carro de adelante debe mantenerse?","o":["2 segundos","3 segundos","4 segundos","Al menos 6 segundos"],"h1":"Es el espacio más largo del manual.","h2":"El manual de Virginia Occidental dice que se mantenga al menos seis segundos detrás del vehículo de adelante con hielo o nieve.","p":"Correcto. Al menos seis segundos."},"ref":{"doc":"WV","page":47}},{"id":"wv-175","scope":"WV","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, you pull out to pass on a two-lane road at night. How can you warn the driver ahead?","o":["Turn on your hazard lights","Blink your headlights","Turn off your headlights","Use your turn signal for the whole pass"],"h1":"In daytime you would tap your horn.","h2":"The West Virginia handbook says to sound your horn to warn the driver you are passing, and at night you can also blink your headlights.","p":"Right. Blink your headlights at night."},"es":{"q":"Según el manual de Virginia Occidental, usted sale a rebasar en una carretera de dos carriles de noche. ¿Cómo puede avisar al conductor de adelante?","o":["Encender las luces intermitentes de emergencia","Hacer un cambio de luces","Apagar las luces delanteras","Dejar la direccional puesta todo el rebase"],"h1":"De día tocaría la bocina.","h2":"El manual de Virginia Occidental dice que toque la bocina para avisar al conductor que lo va a rebasar, y de noche también puede hacer un cambio de luces.","p":"Correcto. De noche haga un cambio de luces."},"ref":{"doc":"WV","page":48}},{"id":"wv-176","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, passing on a two-lane road is prohibited within how many feet of an intersection or railroad crossing?","o":["25 feet","50 feet","100 feet","300 feet"],"h1":"The same distance applies to bridges, tunnels and underpasses.","h2":"In West Virginia passing is prohibited within 100 feet of an intersection, a railroad crossing, or a bridge, viaduct, tunnel or underpass.","p":"Right. No passing within 100 feet."},"es":{"q":"En Virginia Occidental, ¿a menos de cuántos pies de una intersección o un cruce de ferrocarril está prohibido rebasar en una carretera de dos carriles?","o":["25 pies","50 pies","100 pies","300 pies"],"h1":"La misma distancia se aplica a puentes, túneles y pasos a desnivel.","h2":"En Virginia Occidental está prohibido rebasar a menos de 100 pies de una intersección, un cruce de ferrocarril, o un puente, viaducto, túnel o paso a desnivel.","p":"Correcto. No se rebasa a menos de 100 pies."},"ref":{"doc":"WV","page":48}},{"id":"wv-177","scope":"WV","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In West Virginia, the car ahead of you has stopped at an intersection to let a pedestrian cross. May you pass it?","o":["No, passing a car stopped for a pedestrian is prohibited","Yes, if you honk first","Yes, on the right side","Yes, if the pedestrian is almost across"],"h1":"The stopped car may be hiding the person from you.","h2":"In West Virginia you may not pass a vehicle that has stopped at an intersection to let a pedestrian cross.","p":"Right. Never pass a car stopped for a pedestrian."},"es":{"q":"En Virginia Occidental, el carro de adelante se detuvo en una intersección para dejar cruzar a un peatón. ¿Puede rebasarlo?","o":["No, está prohibido rebasar un carro detenido por un peatón","Sí, si toca la bocina primero","Sí, por la derecha","Sí, si el peatón ya casi cruzó"],"h1":"El carro detenido puede taparle a la persona.","h2":"En Virginia Occidental no puede rebasar un vehículo que se detuvo en una intersección para dejar cruzar a un peatón.","p":"Correcto. Nunca rebase un carro detenido por un peatón."},"ref":{"doc":"WV","page":49}},{"id":"wv-178","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"According to the West Virginia handbook, you pull over and stop for an ambulance with siren and lights. Why keep your foot on the brake?","o":["To save gas","To keep the engine warm","To turn off cruise control","So the emergency driver can see you are stopped"],"h1":"Your brake lights send a message.","h2":"The West Virginia handbook says to keep your foot on the brake so the emergency vehicle driver knows you are stopped.","p":"Right. Your brake lights show you are stopped."},"es":{"q":"Según el manual de Virginia Occidental, usted se orilla y se detiene para dejar pasar una ambulancia con sirena y luces. ¿Por qué debe mantener el pie en el freno?","o":["Para ahorrar gasolina","Para mantener el motor caliente","Para apagar el control de crucero","Para que el conductor de emergencia vea que usted está detenido"],"h1":"Sus luces de freno envían un mensaje.","h2":"El manual de Virginia Occidental dice que mantenga el pie en el freno para que el conductor del vehículo de emergencia sepa que usted está detenido.","p":"Correcto. Las luces de freno muestran que está detenido."},"ref":{"doc":"WV","page":49}},{"id":"wv-179","scope":"WV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, what is true about yielding to a funeral procession?","o":["The law requires you to stop for it everywhere","It is a courtesy, not required by law; once the lead car clears an intersection, the rest may follow through","You must join the end of the procession","You may cut through the procession if you are late"],"h1":"The handbook calls it a courtesy.","h2":"The West Virginia handbook says yielding to a funeral procession is a courtesy, not required by law, and once the lead vehicle clears an intersection the rest of the procession has the right-of-way.","p":"Right. It is a courtesy, and the procession stays together."},"es":{"q":"Según el manual de Virginia Occidental, ¿qué es cierto sobre ceder el paso a un cortejo fúnebre?","o":["La ley lo obliga a detenerse en todas partes","Es una cortesía, no lo exige la ley; cuando el primer carro pasa la intersección, los demás pueden seguir","Debe unirse al final del cortejo","Puede cruzar entre los carros del cortejo si va tarde"],"h1":"El manual lo llama una cortesía.","h2":"El manual de Virginia Occidental dice que ceder el paso a un cortejo fúnebre es una cortesía, no lo exige la ley, y cuando el primer vehículo pasa la intersección, el resto del cortejo tiene el derecho de paso.","p":"Correcto. Es una cortesía, y el cortejo va junto."},"ref":{"doc":"WV","page":49}},{"id":"wv-180","scope":"WV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In West Virginia, a pedestrian is walking along a road that has no sidewalk. Where should they walk?","o":["On the right side, with traffic","In the middle of the lane","On the left side, facing oncoming traffic","Anywhere they like"],"h1":"Walkers should be able to see cars coming at them.","h2":"In West Virginia a pedestrian on a road with no sidewalk should walk on the left side, facing oncoming traffic, on the shoulder if possible.","p":"Right. Walk on the left, facing traffic."},"es":{"q":"En Virginia Occidental, un peatón camina por una carretera sin acera. ¿Por dónde debe caminar?","o":["Por la derecha, en el mismo sentido que los carros","Por el centro del carril","Por la izquierda, de frente al tránsito","Por donde quiera"],"h1":"Quien camina debe poder ver los carros que vienen hacia él.","h2":"En Virginia Occidental un peatón en una carretera sin acera debe caminar por el lado izquierdo, de frente al tránsito, y por el acotamiento si es posible.","p":"Correcto. Por la izquierda, de frente al tránsito."},"ref":{"doc":"WV","page":50}},{"id":"wv-181","scope":"WV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In West Virginia, a school bus with flashing red lights is unloading children in a school parking lot. Must you stop?","o":["No, the law only applies on public roads","Yes, you must stop on parking lots, private roads and driveways too","Only if a crossing guard is there","Only if you are behind the bus"],"h1":"The rule is not limited to highways.","h2":"In West Virginia you must stop for a school bus loading or unloading children on all highways, streets, parking lots, private roads and driveways.","p":"Right. You must stop there too."},"es":{"q":"En Virginia Occidental, un autobús escolar con luces rojas intermitentes está bajando niños en el estacionamiento de una escuela. ¿Debe detenerse?","o":["No, la ley solo se aplica en vías públicas","Sí, también debe detenerse en estacionamientos, caminos privados y entradas de casas","Solo si hay un guardia de cruce","Solo si va detrás del autobús"],"h1":"La regla no se limita a las carreteras.","h2":"En Virginia Occidental debe detenerse ante un autobús escolar que sube o baja niños en todas las carreteras, calles, estacionamientos, caminos privados y entradas de casas.","p":"Correcto. También debe detenerse ahí."},"ref":{"doc":"WV","page":50}},{"id":"wv-182","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, what is the minimum fine for a first offense of passing a stopped school bus?","o":["$50","$100","$250","$500"],"h1":"It is the largest amount listed.","h2":"In West Virginia a first offense of passing a stopped school bus carries a minimum fine of $500, or up to six months in jail, plus a license suspension.","p":"Right. At least $500."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa mínima por la primera vez que rebasa un autobús escolar detenido?","o":["$50","$100","$250","$500"],"h1":"Es la cantidad más alta de la lista.","h2":"En Virginia Occidental la primera vez que rebasa un autobús escolar detenido tiene una multa mínima de $500, o hasta seis meses de cárcel, además de la suspensión de la licencia.","p":"Correcto. Al menos $500."},"ref":{"doc":"WV","page":50}},{"id":"wv-183","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, at night a car is coming toward you. Within how many feet must you dim your high beams?","o":["100 feet","200 feet","500 feet","1,000 feet"],"h1":"It is more than twice the distance for a car you are following.","h2":"In West Virginia you must dim your headlights within 500 feet of an approaching vehicle.","p":"Right. Dim within 500 feet of oncoming cars."},"es":{"q":"En Virginia Occidental, de noche viene un carro de frente. ¿A menos de cuántos pies debe bajar las luces altas?","o":["100 pies","200 pies","500 pies","1,000 pies"],"h1":"Es más del doble de la distancia para un carro que va delante de usted.","h2":"En Virginia Occidental debe bajar las luces altas a menos de 500 pies de un vehículo que se acerca de frente.","p":"Correcto. Baje las luces a 500 pies de los carros de frente."},"ref":{"doc":"WV","page":51}},{"id":"wv-184","scope":"WV","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In West Virginia, when must a motorcycle have its headlight on?","o":["At all times on the highway","Only from sunset to sunrise","Only in rain or fog","Only on interstates"],"h1":"The rule is the same for school buses.","h2":"In West Virginia motorcycles, motor-driven cycles, mopeds and school buses must display lighted headlamps at all times on the highway.","p":"Right. Motorcycles keep the headlight on at all times."},"es":{"q":"En Virginia Occidental, ¿cuándo debe tener encendida la luz delantera una motocicleta?","o":["Siempre que esté en la vía","Solo desde la puesta hasta la salida del sol","Solo con lluvia o neblina","Solo en las interestatales"],"h1":"La regla es la misma para los autobuses escolares.","h2":"En Virginia Occidental las motocicletas, ciclomotores y autobuses escolares deben llevar las luces delanteras encendidas en todo momento en la vía.","p":"Correcto. Las motocicletas llevan la luz encendida siempre."},"ref":{"doc":"WV","page":null}},{"id":"wv-185","scope":"WV","cat":"right-of-way","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, a fully loaded tractor-trailer is going 55 mph. How much distance does it need to stop compared to a car?","o":["The same distance","About three times as much","Half as much","Ten times as much"],"h1":"Heavy trucks need far more room.","h2":"The West Virginia handbook says a fully loaded tractor-trailer at 55 mph needs about three times the distance a car needs to stop.","p":"Right. About three times as much."},"es":{"q":"Según el manual de Virginia Occidental, un tráiler totalmente cargado va a 55 mph. ¿Cuánta distancia necesita para detenerse comparado con un carro?","o":["La misma distancia","Unas tres veces más","La mitad","Diez veces más"],"h1":"Los camiones pesados necesitan mucho más espacio.","h2":"El manual de Virginia Occidental dice que un tráiler totalmente cargado a 55 mph necesita unas tres veces la distancia que necesita un carro para detenerse.","p":"Correcto. Unas tres veces más."},"ref":{"doc":"WV","page":52}},{"id":"wv-186","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, where may people NOT ride horses or other animals?","o":["On country roads","On the shoulder of a two-lane highway","On city streets","On interstate highways"],"h1":"It is the type of road where people on foot are also banned.","h2":"In West Virginia animal riders may use most public highways, but they may not use interstate highways.","p":"Right. No animal riders on interstates."},"es":{"q":"En Virginia Occidental, ¿por dónde NO pueden andar personas a caballo o en otros animales?","o":["Por caminos rurales","Por el acotamiento de una carretera de dos carriles","Por calles de la ciudad","Por carreteras interestatales"],"h1":"Es el tipo de carretera donde también se prohíbe a los peatones.","h2":"En Virginia Occidental las personas que montan animales pueden usar la mayoría de las vías públicas, pero no las carreteras interestatales.","p":"Correcto. No se permiten jinetes en las interestatales."},"ref":{"doc":"WV","page":53}},{"id":"wv-187","scope":"WV","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In West Virginia, you are passing a bicycle going the same way. How much space must you leave?","o":["At least 3 feet","At least 1 foot","At least 10 feet","No set amount"],"h1":"It is about the length of a yardstick.","h2":"In West Virginia you must pass a bicycle on the left at a distance of at least three feet, at a careful and reduced speed.","p":"Right. At least three feet."},"es":{"q":"En Virginia Occidental, usted va a rebasar una bicicleta que va en el mismo sentido. ¿Cuánto espacio debe dejar?","o":["Al menos 3 pies","Al menos 1 pie","Al menos 10 pies","No hay una cantidad fija"],"h1":"Es más o menos el largo de una regla de una yarda.","h2":"En Virginia Occidental debe rebasar una bicicleta por la izquierda dejando al menos tres pies, con cuidado y a menor velocidad.","p":"Correcto. Al menos tres pies."},"ref":{"doc":"WV","page":null}},{"id":"wv-188","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In West Virginia, who on a motorcycle must wear a helmet?","o":["Only riders under 21","Only the operator","Both the operator and any passenger","No one, helmets are optional"],"h1":"The law covers everyone on the motorcycle.","h2":"In West Virginia both the operator and any passenger on a motorcycle must wear a securely fastened protective helmet.","p":"Right. The operator and the passenger."},"es":{"q":"En Virginia Occidental, ¿quién debe usar casco en una motocicleta?","o":["Solo los menores de 21 años","Solo el conductor","El conductor y cualquier pasajero","Nadie, el casco es opcional"],"h1":"La ley incluye a todos los que van en la moto.","h2":"En Virginia Occidental el conductor y cualquier pasajero de una motocicleta deben usar un casco protector bien abrochado.","p":"Correcto. El conductor y el pasajero."},"ref":{"doc":"WV","page":null}},{"id":"wv-189","scope":"WV","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In West Virginia, a fire truck is answering an alarm. How close behind it may you follow?","o":["50 feet","100 feet","No closer than 500 feet","Any distance, if you keep up"],"h1":"It is about a tenth of a mile.","h2":"In West Virginia you may not follow an emergency vehicle answering an alarm closer than 500 feet.","p":"Right. Stay at least 500 feet back."},"es":{"q":"En Virginia Occidental, un camión de bomberos va a atender una alarma. ¿Qué tan cerca puede seguirlo?","o":["50 pies","100 pies","No más cerca de 500 pies","A cualquier distancia, si no se queda atrás"],"h1":"Es más o menos una décima de milla.","h2":"En Virginia Occidental no puede seguir a un vehículo de emergencia que va a una alarma a menos de 500 pies.","p":"Correcto. Manténgase al menos a 500 pies."},"ref":{"doc":"WV","page":null}},{"id":"wv-190","scope":"WV","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In West Virginia, a railroad crossing signal is flashing. Where must you stop?","o":["Right on the tracks","Within 5 feet of the rail","At least 100 feet away","Within 50 feet but not less than 15 feet from the nearest rail"],"h1":"There is both a closest and a farthest point.","h2":"In West Virginia when a crossing signal warns of a train, you must stop within 50 feet but not less than 15 feet from the nearest rail.","p":"Right. Between 15 and 50 feet from the nearest rail."},"es":{"q":"En Virginia Occidental, la señal de un cruce de ferrocarril está parpadeando. ¿Dónde debe detenerse?","o":["Sobre las vías","A menos de 5 pies del riel","Al menos a 100 pies","A menos de 50 pies pero no a menos de 15 pies del riel más cercano"],"h1":"Hay un punto más cercano y uno más lejano.","h2":"En Virginia Occidental cuando la señal de un cruce avisa que viene un tren, debe detenerse a menos de 50 pies pero no a menos de 15 pies del riel más cercano.","p":"Correcto. Entre 15 y 50 pies del riel más cercano."},"ref":{"doc":"WV","page":null}},{"id":"wv-191","scope":"WV","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In West Virginia, you see a stopped vehicle with flashing lights on a two-lane road that is not divided, and you cannot move over. How fast may you pass it?","o":["No more than 15 mph","No more than 25 mph","No more than 35 mph","The posted speed limit"],"h1":"It is the same number as the school zone limit.","h2":"In West Virginia if you cannot change lanes, you must slow to no more than 15 mph on a nondivided road (25 mph on a divided highway) when passing a stopped vehicle with flashing lights.","p":"Right. No more than 15 mph on a nondivided road."},"es":{"q":"En Virginia Occidental, ve un vehículo detenido con luces intermitentes en una carretera de dos carriles sin división, y no puede cambiarse de carril. ¿A qué velocidad puede pasarlo?","o":["No más de 15 mph","No más de 25 mph","No más de 35 mph","El límite de velocidad indicado"],"h1":"Es el mismo número que el límite en zona escolar.","h2":"En Virginia Occidental si no puede cambiarse de carril, debe bajar a no más de 15 mph en una carretera sin división (25 mph en una carretera dividida) al pasar un vehículo detenido con luces intermitentes.","p":"Correcto. No más de 15 mph en una carretera sin división."},"ref":{"doc":"WV","page":null}},{"id":"wv-192","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, what is the fine for speeding in a school zone?","o":["$5","$25 to $50","$100 to $500","$2,000"],"h1":"It is a range in the hundreds of dollars.","h2":"In West Virginia speeding in a school zone is a misdemeanor with a fine of $100 to $500.","p":"Right. $100 to $500."},"es":{"q":"En Virginia Occidental, ¿cuál es la multa por exceso de velocidad en una zona escolar?","o":["$5","De $25 a $50","De $100 a $500","$2,000"],"h1":"Es un rango de cientos de dólares.","h2":"En Virginia Occidental el exceso de velocidad en una zona escolar es un delito menor con multa de $100 a $500.","p":"Correcto. De $100 a $500."},"ref":{"doc":"WV","page":null}},{"id":"wv-193","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, what is the penalty for not wearing a seat belt?","o":["A $100 fine and 2 points","A $25 fine and no points","A warning only","A 30-day suspension"],"h1":"No points can be added for this.","h2":"In West Virginia not wearing a seat belt carries a $25 fine, and no points may be added to your record.","p":"Right. A $25 fine, no points."},"es":{"q":"En Virginia Occidental, ¿cuál es la sanción por no usar el cinturón de seguridad?","o":["Multa de $100 y 2 puntos","Multa de $25 y ningún punto","Solo una advertencia","Suspensión de 30 días"],"h1":"No se pueden agregar puntos por esto.","h2":"En Virginia Occidental no usar el cinturón de seguridad tiene una multa de $25, y no se pueden agregar puntos a su historial.","p":"Correcto. Multa de $25, sin puntos."},"ref":{"doc":"WV","page":null}},{"id":"wv-194","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In West Virginia, a 7-year-old is 4 feet 10 inches tall. What must they use in the car?","o":["A rear-facing car seat","A booster seat until age 12","Nothing, children ride free","A seat belt is enough"],"h1":"Children under 8 need a child seat unless they are at least 4 feet 9 inches tall.","h2":"In West Virginia a child under 8 must ride in a child safety seat, but a seat belt is enough if the child is at least 4 feet 9 inches tall.","p":"Right. At that height, a seat belt is enough."},"es":{"q":"En Virginia Occidental, un niño de 7 años mide 4 pies 10 pulgadas. ¿Qué debe usar en el carro?","o":["Un asiento mirando hacia atrás","Un asiento elevado hasta los 12 años","Nada, los niños van libres","El cinturón de seguridad es suficiente"],"h1":"Los menores de 8 años necesitan asiento de niño, a menos que midan al menos 4 pies 9 pulgadas.","h2":"En Virginia Occidental un niño menor de 8 años debe ir en un asiento de seguridad para niños, pero el cinturón es suficiente si mide al menos 4 pies 9 pulgadas.","p":"Correcto. Con esa estatura, el cinturón es suficiente."},"ref":{"doc":"WV","page":67}},{"id":"wv-195","scope":"WV","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In West Virginia, what is the slowest you should drive on an interstate when the weather and road are good and no lower limit is posted?","o":["40 mph","45 mph","55 mph","65 mph"],"h1":"It is the same as the open country highway limit.","h2":"In West Virginia you should not drive slower than 55 mph on an interstate unless weather or road conditions are bad or a lower speed is posted.","p":"Right. Do not go below 55 mph."},"es":{"q":"En Virginia Occidental, ¿cuál es la velocidad más baja a la que debe manejar en una interestatal cuando el clima y la vía están bien y no hay un límite menor indicado?","o":["40 mph","45 mph","55 mph","65 mph"],"h1":"Es igual al límite de las carreteras rurales abiertas.","h2":"En Virginia Occidental no debe manejar a menos de 55 mph en una interestatal, a menos que el clima o la vía estén mal o se indique una velocidad menor.","p":"Correcto. No baje de 55 mph."},"ref":{"doc":"WV","page":59}},{"id":"wv-196","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the West Virginia handbook, your car breaks down on the interstate. Where should you put flares?","o":["Only one, in front of the car","On top of the car","One about one car length behind, and another about 300 feet back","In the middle of the travel lane"],"h1":"Give drivers an early warning and a close one.","h2":"The West Virginia handbook says to put one flare about one vehicle length behind your car and another about 300 feet back, on the shoulder near the travel lane.","p":"Right. One car length and about 300 feet back."},"es":{"q":"Según el manual de Virginia Occidental, su carro se descompone en la interestatal. ¿Dónde debe poner las bengalas?","o":["Solo una, delante del carro","Encima del carro","Una a un carro de distancia detrás, y otra a unos 300 pies atrás","En medio del carril de tránsito"],"h1":"Dé un aviso temprano y uno cercano.","h2":"El manual de Virginia Occidental dice que ponga una bengala a un vehículo de distancia detrás de su carro y otra a unos 300 pies atrás, en el acotamiento cerca del carril.","p":"Correcto. A un carro de distancia y a unos 300 pies."},"ref":{"doc":"WV","page":60}},{"id":"wv-197","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In West Virginia, how often must your vehicle pass a state safety inspection?","o":["Every year","Every two years","Every five years","Only when you buy it"],"h1":"The sticker shows the month and year of the next one.","h2":"In West Virginia vehicles must be inspected every two years at an official inspection station.","p":"Right. Every two years."},"es":{"q":"En Virginia Occidental, ¿cada cuánto debe pasar su vehículo la inspección de seguridad del estado?","o":["Cada año","Cada dos años","Cada cinco años","Solo cuando lo compra"],"h1":"La calcomanía muestra el mes y el año de la próxima.","h2":"En Virginia Occidental los vehículos se deben inspeccionar cada dos años en una estación oficial de inspección.","p":"Correcto. Cada dos años."},"ref":{"doc":"WV","page":64}},{"id":"wv-198","scope":"WV","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the West Virginia handbook, it can take up to how many times the normal distance to stop on snow or ice?","o":["2 times","4 times","6 times","12 times"],"h1":"It is much more than you might guess.","h2":"The West Virginia handbook says it can take as much as 12 times the normal distance to stop on snow or ice compared with dry pavement.","p":"Right. Up to 12 times."},"es":{"q":"Según el manual de Virginia Occidental, ¿hasta cuántas veces la distancia normal puede necesitar para detenerse sobre nieve o hielo?","o":["2 veces","4 veces","6 veces","12 veces"],"h1":"Es mucho más de lo que podría pensar.","h2":"El manual de Virginia Occidental dice que puede necesitar hasta 12 veces la distancia normal para detenerse sobre nieve o hielo comparado con pavimento seco.","p":"Correcto. Hasta 12 veces."},"ref":{"doc":"WV","page":63}},{"id":"wv-199","scope":"WV","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the West Virginia handbook, at about what speed does partial hydroplaning start on a wet road in a standard passenger car?","o":["About 15 mph","About 35 mph","About 70 mph","Only above 80 mph"],"h1":"At 55 mph the tires can ride fully on the water.","h2":"The West Virginia handbook says partial hydroplaning starts at about 35 mph in a standard passenger car, and at 55 mph the tires can ride totally on top of the water.","p":"Right. About 35 mph."},"es":{"q":"Según el manual de Virginia Occidental, ¿a qué velocidad más o menos empieza el hidroplaneo parcial en una vía mojada con un carro de pasajeros normal?","o":["Unas 15 mph","Unas 35 mph","Unas 70 mph","Solo a más de 80 mph"],"h1":"A 55 mph las llantas pueden ir totalmente sobre el agua.","h2":"El manual de Virginia Occidental dice que el hidroplaneo parcial empieza a unas 35 mph en un carro de pasajeros normal, y a 55 mph las llantas pueden ir totalmente sobre el agua.","p":"Correcto. Unas 35 mph."},"ref":{"doc":"WV","page":63}},{"id":"wv-200","scope":"WV","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the West Virginia handbook, a fire in your car gets out of control. How far away should you move?","o":["10 feet","25 feet","At least 100 feet","Stay next to the car to guard it"],"h1":"The gas tank may explode.","h2":"The West Virginia handbook says to move at least 100 feet away from a car fire that is out of control, because the gas tank may explode.","p":"Right. At least 100 feet away."},"es":{"q":"Según el manual de Virginia Occidental, un incendio en su carro se sale de control. ¿A qué distancia debe alejarse?","o":["10 pies","25 pies","Al menos 100 pies","Quedarse junto al carro para cuidarlo"],"h1":"El tanque de gasolina puede explotar.","h2":"El manual de Virginia Occidental dice que se aleje al menos 100 pies de un incendio de carro fuera de control, porque el tanque de gasolina puede explotar.","p":"Correcto. Al menos 100 pies."},"ref":{"doc":"WV","page":72}},{"id":"wy-001","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, what is the youngest age to get a learner's permit?","o":["14 years old","15 years old","15 and a half years old","16 years old"],"h1":"It is one year before the intermediate permit.","h2":"In Wyoming you can get a learner's permit at 15 years old.","p":"Right. The Wyoming learner's permit starts at 15."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener un permiso de aprendiz?","o":["14 años","15 años","15 años y medio","16 años"],"h1":"Es un año antes del permiso intermedio.","h2":"En Wyoming usted puede obtener el permiso de aprendiz a los 15 años.","p":"Correcto. El permiso de aprendiz en Wyoming empieza a los 15."},"zh":{"q":"在 Wyoming，最小几岁可以拿到学习驾照（learner's permit）？","o":["14 岁","15 岁","15 岁半","16 岁"],"h1":"它比拿中级驾照的年龄早一年。","h2":"在 Wyoming，你 15 岁就可以拿到学习驾照。","p":"对。Wyoming 的学习驾照从 15 岁开始。"},"vi":{"q":"Ở Wyoming, tuổi nhỏ nhất để có giấy phép tập lái (learner's permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","15 tuổi rưỡi","16 tuổi"],"h1":"Đó là một năm trước tuổi có giấy phép trung cấp.","h2":"Ở Wyoming, bạn có thể có giấy phép tập lái khi 15 tuổi.","p":"Đúng. Giấy phép tập lái ở Wyoming bắt đầu từ 15 tuổi."},"tl":{"q":"Sa Wyoming, ano ang pinakabatang edad para makakuha ng learner's permit (permit sa pag-aaral magmaneho)?","o":["14 taong gulang","15 taong gulang","15 at kalahating taong gulang","16 taong gulang"],"h1":"Isang taon ito bago ang intermediate permit.","h2":"Sa Wyoming, makakakuha ka ng learner's permit sa edad na 15.","p":"Tama. Sa Wyoming, nagsisimula ang learner's permit sa edad na 15."},"ar":{"q":"في Wyoming، ما أصغر عمر للحصول على تصريح التعلّم (learner's permit)؟","o":["14 سنة","15 سنة","15 سنة ونصف","16 سنة"],"h1":"هو قبل التصريح المتوسط بسنة واحدة.","h2":"في Wyoming يمكنك الحصول على تصريح التعلّم في عمر 15 سنة.","p":"صحيح. يبدأ تصريح التعلّم في Wyoming من عمر 15 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-002","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how long must you hold a learner's permit before you can get an intermediate permit?","o":["At least 10 days","At least 6 months","At least one year","At least two years"],"h1":"Wyoming's waiting time is much shorter than in most states.","h2":"In Wyoming you must hold your learner's permit for at least 10 days before you can get an intermediate permit.","p":"Right. Only 10 days in Wyoming."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso de aprendiz antes de obtener el permiso intermedio?","o":["Por lo menos 10 días","Por lo menos 6 meses","Por lo menos un año","Por lo menos dos años"],"h1":"En Wyoming la espera es mucho más corta que en la mayoría de los estados.","h2":"En Wyoming usted debe tener el permiso de aprendiz por lo menos 10 días antes de obtener el permiso intermedio.","p":"Correcto. Solo 10 días en Wyoming."},"zh":{"q":"在 Wyoming，拿中级驾照（intermediate permit）前，必须持有学习驾照多久？","o":["至少 10 天","至少六个月","至少一年","至少两年"],"h1":"Wyoming 的等待时间比大多数州短得多。","h2":"在 Wyoming，你必须持有学习驾照至少 10 天，才能拿中级驾照。","p":"对。在 Wyoming 只要 10 天。"},"vi":{"q":"Ở Wyoming, bạn phải giữ giấy phép tập lái bao lâu trước khi có thể có giấy phép trung cấp (intermediate permit)?","o":["Ít nhất 10 ngày","Ít nhất 6 tháng","Ít nhất một năm","Ít nhất hai năm"],"h1":"Thời gian chờ ở Wyoming ngắn hơn nhiều so với hầu hết các tiểu bang.","h2":"Ở Wyoming, bạn phải giữ giấy phép tập lái ít nhất 10 ngày trước khi có thể có giấy phép trung cấp.","p":"Đúng. Ở Wyoming chỉ cần 10 ngày."},"tl":{"q":"Sa Wyoming, gaano katagal mo dapat hawak ang learner's permit bago ka makakuha ng intermediate permit?","o":["Hindi bababa sa 10 araw","Hindi bababa sa 6 na buwan","Hindi bababa sa isang taon","Hindi bababa sa dalawang taon"],"h1":"Mas maikli nang husto ang paghihintay sa Wyoming kaysa sa karamihan ng estado.","h2":"Sa Wyoming, dapat mong hawak ang learner's permit nang hindi bababa sa 10 araw bago ka makakuha ng intermediate permit.","p":"Tama. 10 araw lang sa Wyoming."},"ar":{"q":"في Wyoming، كم مدة يجب أن تحمل تصريح التعلّم قبل أن تحصل على التصريح المتوسط (intermediate permit)؟","o":["10 أيام على الأقل","6 أشهر على الأقل","سنة واحدة على الأقل","سنتان على الأقل"],"h1":"مدة الانتظار في Wyoming أقصر بكثير من معظم الولايات.","h2":"في Wyoming يجب أن تحمل تصريح التعلّم 10 أيام على الأقل قبل أن تحصل على التصريح المتوسط.","p":"صحيح. 10 أيام فقط في Wyoming."},"ref":{"doc":"WY","page":null}},{"id":"wy-003","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, what is the youngest age to get an intermediate permit?","o":["14 years old","15 years old","16 years old","17 years old"],"h1":"It is one year after the learner's permit age.","h2":"In Wyoming you must be at least 16 to get an intermediate permit.","p":"Right. The intermediate permit starts at 16."},"es":{"q":"En Wyoming, ¿cuál es la edad mínima para obtener el permiso intermedio?","o":["14 años","15 años","16 años","17 años"],"h1":"Es un año después de la edad del permiso de aprendiz.","h2":"En Wyoming usted debe tener por lo menos 16 años para obtener el permiso intermedio.","p":"Correcto. El permiso intermedio empieza a los 16."},"zh":{"q":"在 Wyoming，最小几岁可以拿到中级驾照（intermediate permit）？","o":["14 岁","15 岁","16 岁","17 岁"],"h1":"它比拿学习驾照的年龄晚一年。","h2":"在 Wyoming，你必须至少 16 岁才能拿到中级驾照。","p":"对。中级驾照从 16 岁开始。"},"vi":{"q":"Ở Wyoming, tuổi nhỏ nhất để có giấy phép trung cấp (intermediate permit) là bao nhiêu?","o":["14 tuổi","15 tuổi","16 tuổi","17 tuổi"],"h1":"Đó là một năm sau tuổi có giấy phép tập lái.","h2":"Ở Wyoming, bạn phải ít nhất 16 tuổi để có giấy phép trung cấp.","p":"Đúng. Giấy phép trung cấp bắt đầu từ 16 tuổi."},"tl":{"q":"Sa Wyoming, ano ang pinakabatang edad para makakuha ng intermediate permit?","o":["14 taong gulang","15 taong gulang","16 taong gulang","17 taong gulang"],"h1":"Isang taon ito pagkatapos ng edad para sa learner's permit.","h2":"Sa Wyoming, dapat ay hindi bababa sa 16 taong gulang ka para makakuha ng intermediate permit.","p":"Tama. Nagsisimula ang intermediate permit sa edad na 16."},"ar":{"q":"في Wyoming، ما أصغر عمر للحصول على التصريح المتوسط (intermediate permit)؟","o":["14 سنة","15 سنة","16 سنة","17 سنة"],"h1":"هو بعد عمر تصريح التعلّم بسنة واحدة.","h2":"في Wyoming يجب أن يكون عمرك 16 سنة على الأقل للحصول على التصريح المتوسط.","p":"صحيح. يبدأ التصريح المتوسط من عمر 16 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-004","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how many hours behind the wheel must you complete before the intermediate permit, and how many at night?","o":["25 hours, 5 at night","30 hours, 10 at night","40 hours, 15 at night","50 hours, 10 at night"],"h1":"The night hours are one fifth of the total.","h2":"In Wyoming you must complete 50 hours behind the wheel, including 10 hours at night, before getting an intermediate permit.","p":"Right. Fifty hours, ten at night."},"es":{"q":"En Wyoming, ¿cuántas horas al volante debe completar antes del permiso intermedio, y cuántas de noche?","o":["25 horas, 5 de noche","30 horas, 10 de noche","40 horas, 15 de noche","50 horas, 10 de noche"],"h1":"Las horas de noche son una quinta parte del total.","h2":"En Wyoming usted debe completar 50 horas al volante, con 10 horas de noche, antes de obtener el permiso intermedio.","p":"Correcto. Cincuenta horas, diez de noche."},"zh":{"q":"在 Wyoming，拿中级驾照前，必须完成多少小时的实际驾驶，其中多少小时在夜间？","o":["25 小时，夜间 5 小时","30 小时，夜间 10 小时","40 小时，夜间 15 小时","50 小时，夜间 10 小时"],"h1":"夜间小时数是总数的五分之一。","h2":"在 Wyoming，拿中级驾照前，你必须完成 50 小时的实际驾驶，其中包括 10 小时夜间驾驶。","p":"对。五十小时，其中十小时在夜间。"},"vi":{"q":"Ở Wyoming, bạn phải lái xe thực tế bao nhiêu giờ trước khi có giấy phép trung cấp, và bao nhiêu giờ vào ban đêm?","o":["25 giờ, 5 giờ ban đêm","30 giờ, 10 giờ ban đêm","40 giờ, 15 giờ ban đêm","50 giờ, 10 giờ ban đêm"],"h1":"Số giờ ban đêm là một phần năm của tổng số.","h2":"Ở Wyoming, bạn phải lái xe thực tế 50 giờ, trong đó có 10 giờ ban đêm, trước khi có giấy phép trung cấp.","p":"Đúng. Năm mươi giờ, mười giờ ban đêm."},"tl":{"q":"Sa Wyoming, ilang oras ng aktuwal na pagmamaneho ang dapat mong tapusin bago ang intermediate permit, at ilan dito ang sa gabi?","o":["25 oras, 5 sa gabi","30 oras, 10 sa gabi","40 oras, 15 sa gabi","50 oras, 10 sa gabi"],"h1":"Ang oras sa gabi ay ikalimang bahagi ng kabuuan.","h2":"Sa Wyoming, dapat kang magmaneho nang 50 oras, kasama ang 10 oras sa gabi, bago makakuha ng intermediate permit.","p":"Tama. Limampung oras, sampu sa gabi."},"ar":{"q":"في Wyoming، كم ساعة من القيادة الفعلية يجب أن تكملها قبل التصريح المتوسط، وكم منها في الليل؟","o":["25 ساعة، منها 5 في الليل","30 ساعة، منها 10 في الليل","40 ساعة، منها 15 في الليل","50 ساعة، منها 10 في الليل"],"h1":"ساعات الليل هي خُمس المجموع.","h2":"في Wyoming يجب أن تكمل 50 ساعة من القيادة الفعلية، منها 10 ساعات في الليل، قبل الحصول على التصريح المتوسط.","p":"صحيح. خمسون ساعة، منها عشر في الليل."},"ref":{"doc":"WY","page":14}},{"id":"wy-005","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, who must certify that a teen finished the practice driving hours?","o":["The teen alone","A parent or guardian","A police officer","A school teacher"],"h1":"It is the adult who is responsible for the teen.","h2":"In Wyoming, a parent or guardian must certify that the teen completed the practice driving hours.","p":"Right. A parent or guardian signs for the hours."},"es":{"q":"En Wyoming, ¿quién debe certificar que un adolescente terminó las horas de práctica?","o":["El adolescente solo","El padre, madre o tutor","Un policía","Un maestro de la escuela"],"h1":"Es el adulto responsable del adolescente.","h2":"En Wyoming, el padre, madre o tutor debe certificar que el adolescente completó las horas de práctica de manejo.","p":"Correcto. El padre, madre o tutor firma por las horas."},"zh":{"q":"在 Wyoming，谁必须证明青少年已经完成练习驾驶的小时数？","o":["只有青少年自己","父母或监护人","警察","学校老师"],"h1":"是对这个青少年负责的成年人。","h2":"在 Wyoming，必须由父母或监护人证明青少年已经完成练习驾驶的小时数。","p":"对。由父母或监护人为这些小时数签字。"},"vi":{"q":"Ở Wyoming, ai phải xác nhận rằng thiếu niên đã hoàn thành số giờ tập lái?","o":["Chỉ một mình thiếu niên","Cha mẹ hoặc người giám hộ","Một cảnh sát","Một giáo viên"],"h1":"Đó là người lớn chịu trách nhiệm về thiếu niên đó.","h2":"Ở Wyoming, cha mẹ hoặc người giám hộ phải xác nhận rằng thiếu niên đã hoàn thành số giờ tập lái.","p":"Đúng. Cha mẹ hoặc người giám hộ ký xác nhận số giờ."},"tl":{"q":"Sa Wyoming, sino ang dapat magpatunay na natapos ng kabataan ang mga oras ng pagsasanay sa pagmamaneho?","o":["Ang kabataan lang","Isang magulang o tagapag-alaga","Isang pulis","Isang guro sa paaralan"],"h1":"Ito ang adultong may pananagutan sa kabataan.","h2":"Sa Wyoming, isang magulang o tagapag-alaga ang dapat magpatunay na natapos ng kabataan ang mga oras ng pagsasanay sa pagmamaneho.","p":"Tama. Ang magulang o tagapag-alaga ang pumipirma para sa mga oras."},"ar":{"q":"في Wyoming، من يجب أن يشهد بأن المراهق أكمل ساعات التدريب على القيادة؟","o":["المراهق وحده","أحد الوالدين أو الوصي","شرطي","معلّم في المدرسة"],"h1":"هو الشخص البالغ المسؤول عن المراهق.","h2":"في Wyoming يجب أن يشهد أحد الوالدين أو الوصي بأن المراهق أكمل ساعات التدريب على القيادة.","p":"صحيح. أحد الوالدين أو الوصي يوقّع على الساعات."},"ref":{"doc":"WY","page":14}},{"id":"wy-006","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, during which hours may an intermediate permit holder drive?","o":["5 a.m. to 11 p.m.","6 a.m. to 9 p.m.","7 a.m. to 10 p.m.","Any time"],"h1":"The window ends late in the evening.","h2":"In Wyoming, an intermediate permit holder may drive only between 5 a.m. and 11 p.m., unless an exception applies.","p":"Right. Five in the morning to eleven at night."},"es":{"q":"En Wyoming, ¿en qué horario puede manejar quien tiene permiso intermedio?","o":["De 5 a.m. a 11 p.m.","De 6 a.m. a 9 p.m.","De 7 a.m. a 10 p.m.","A cualquier hora"],"h1":"El horario termina tarde en la noche.","h2":"En Wyoming, quien tiene permiso intermedio solo puede manejar entre las 5 a.m. y las 11 p.m., salvo que aplique una excepción.","p":"Correcto. De cinco de la mañana a once de la noche."},"zh":{"q":"在 Wyoming，持中级驾照的人可以在什么时间开车？","o":["早上 5 点到晚上 11 点","早上 6 点到晚上 9 点","早上 7 点到晚上 10 点","任何时间"],"h1":"这个时段在晚上很晚才结束。","h2":"在 Wyoming，持中级驾照的人只可以在早上 5 点到晚上 11 点之间开车，除非有例外情况。","p":"对。早上五点到晚上十一点。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp được lái xe trong những giờ nào?","o":["5 giờ sáng đến 11 giờ tối","6 giờ sáng đến 9 giờ tối","7 giờ sáng đến 10 giờ tối","Bất cứ lúc nào"],"h1":"Khoảng thời gian này kết thúc muộn vào buổi tối.","h2":"Ở Wyoming, người có giấy phép trung cấp chỉ được lái xe từ 5 giờ sáng đến 11 giờ tối, trừ khi có trường hợp ngoại lệ.","p":"Đúng. Từ năm giờ sáng đến mười một giờ tối."},"tl":{"q":"Sa Wyoming, sa anong mga oras puwedeng magmaneho ang may intermediate permit?","o":["5 a.m. hanggang 11 p.m.","6 a.m. hanggang 9 p.m.","7 a.m. hanggang 10 p.m.","Kahit anong oras"],"h1":"Natatapos ang oras na ito nang gabing-gabi na.","h2":"Sa Wyoming, puwedeng magmaneho ang may intermediate permit mula 5 a.m. hanggang 11 p.m. lang, maliban kung may exception.","p":"Tama. Mula alas-singko ng umaga hanggang alas-onse ng gabi."},"ar":{"q":"في Wyoming، في أي ساعات يُسمح لحامل التصريح المتوسط بالقيادة؟","o":["من 5 صباحًا إلى 11 مساءً","من 6 صباحًا إلى 9 مساءً","من 7 صباحًا إلى 10 مساءً","في أي وقت"],"h1":"هذه الفترة تنتهي في وقت متأخر من المساء.","h2":"في Wyoming يُسمح لحامل التصريح المتوسط بالقيادة فقط بين 5 صباحًا و11 مساءً، إلا إذا كان هناك استثناء.","p":"صحيح. من الخامسة صباحًا إلى الحادية عشرة ليلًا."},"ref":{"doc":"WY","page":14}},{"id":"wy-007","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, an intermediate permit holder drives at night for work. What is needed?","o":["Nothing at all","A note from a friend","A signed exception form","A police escort"],"h1":"Wyoming has a special paper for this.","h2":"In Wyoming, driving outside the allowed hours for work, school, sports or religious activities requires a signed exception form.","p":"Right. You need the signed exception form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche por trabajo. ¿Qué necesita?","o":["Nada","Una nota de un amigo","Un formulario de excepción firmado","Una escolta de policía"],"h1":"Wyoming tiene un papel especial para esto.","h2":"En Wyoming, para manejar fuera del horario permitido por trabajo, escuela, deportes o actividades religiosas se necesita un formulario de excepción firmado.","p":"Correcto. Necesita el formulario de excepción firmado."},"zh":{"q":"在 Wyoming，持中级驾照的人因为工作要在夜间开车。需要什么？","o":["什么都不需要","朋友写的字条","签过字的例外表格","警察护送"],"h1":"Wyoming 有一张专门用于这种情况的文件。","h2":"在 Wyoming，因为工作、上学、体育或宗教活动要在允许时间以外开车，需要一张签过字的例外表格。","p":"对。你需要签过字的例外表格。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp lái xe ban đêm vì công việc. Cần gì?","o":["Không cần gì cả","Một tờ giấy của bạn bè","Một mẫu đơn ngoại lệ có chữ ký","Cảnh sát hộ tống"],"h1":"Wyoming có một loại giấy riêng cho việc này.","h2":"Ở Wyoming, lái xe ngoài giờ cho phép vì công việc, trường học, thể thao hoặc hoạt động tôn giáo cần có mẫu đơn ngoại lệ có chữ ký.","p":"Đúng. Bạn cần mẫu đơn ngoại lệ có chữ ký."},"tl":{"q":"Sa Wyoming, nagmamaneho sa gabi para sa trabaho ang may intermediate permit. Ano ang kailangan?","o":["Wala talaga","Sulat mula sa kaibigan","Isang pinirmahang exception form","Kasamang pulis"],"h1":"May espesyal na papel ang Wyoming para dito.","h2":"Sa Wyoming, kailangan ng pinirmahang exception form para magmaneho sa labas ng pinapayagang oras para sa trabaho, paaralan, sports o gawaing panrelihiyon.","p":"Tama. Kailangan mo ang pinirmahang exception form."},"ar":{"q":"في Wyoming، حامل التصريح المتوسط يقود في الليل من أجل العمل. ما المطلوب؟","o":["لا شيء أبدًا","ورقة من صديق","نموذج استثناء موقّع","مرافقة من الشرطة"],"h1":"لدى Wyoming ورقة خاصة لهذا.","h2":"في Wyoming، القيادة خارج الساعات المسموح بها من أجل العمل أو المدرسة أو الرياضة أو النشاطات الدينية تحتاج إلى نموذج استثناء موقّع.","p":"صحيح. تحتاج إلى نموذج الاستثناء الموقّع."},"ref":{"doc":"WY","page":14}},{"id":"wy-008","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, an intermediate permit holder drives to the hospital at night for a medical emergency. Is an exception form needed?","o":["Yes, always","Yes, signed by a doctor","Yes, signed by the police","No, a medical emergency does not need the form"],"h1":"In a real emergency, paperwork comes second.","h2":"In Wyoming, a trip to the hospital for a medical emergency does not require the exception form.","p":"Right. A medical emergency needs no form."},"es":{"q":"En Wyoming, quien tiene permiso intermedio maneja de noche al hospital por una emergencia médica. ¿Necesita el formulario de excepción?","o":["Sí, siempre","Sí, firmado por un médico","Sí, firmado por la policía","No, una emergencia médica no necesita el formulario"],"h1":"En una emergencia real, los papeles van después.","h2":"En Wyoming, un viaje al hospital por una emergencia médica no requiere el formulario de excepción.","p":"Correcto. Una emergencia médica no necesita formulario."},"zh":{"q":"在 Wyoming，持中级驾照的人因为医疗紧急情况在夜间开车去医院。需要例外表格吗？","o":["需要，每次都需要","需要，由医生签字","需要，由警察签字","不需要，医疗紧急情况不需要这张表格"],"h1":"在真正的紧急情况下，文件是次要的。","h2":"在 Wyoming，因为医疗紧急情况开车去医院，不需要例外表格。","p":"对。医疗紧急情况不需要表格。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp lái xe đến bệnh viện vào ban đêm vì cấp cứu y tế. Có cần mẫu đơn ngoại lệ không?","o":["Có, luôn luôn cần","Có, do bác sĩ ký","Có, do cảnh sát ký","Không, cấp cứu y tế không cần mẫu đơn"],"h1":"Khi thật sự khẩn cấp, giấy tờ là chuyện sau.","h2":"Ở Wyoming, lái xe đến bệnh viện vì cấp cứu y tế không cần mẫu đơn ngoại lệ.","p":"Đúng. Cấp cứu y tế không cần mẫu đơn."},"tl":{"q":"Sa Wyoming, nagmamaneho sa gabi papunta sa ospital ang may intermediate permit dahil sa medical emergency. Kailangan ba ang exception form?","o":["Oo, palagi","Oo, pirmado ng doktor","Oo, pirmado ng pulis","Hindi, hindi kailangan ng form sa medical emergency"],"h1":"Sa tunay na emergency, pangalawa lang ang papeles.","h2":"Sa Wyoming, hindi kailangan ng exception form sa pagpunta sa ospital dahil sa medical emergency.","p":"Tama. Walang form na kailangan sa medical emergency."},"ar":{"q":"في Wyoming، حامل التصريح المتوسط يقود إلى المستشفى في الليل بسبب حالة طبية طارئة. هل يحتاج إلى نموذج استثناء؟","o":["نعم، دائمًا","نعم، موقّع من طبيب","نعم، موقّع من الشرطة","لا، الحالة الطبية الطارئة لا تحتاج إلى النموذج"],"h1":"في الطوارئ الحقيقية، الأوراق تأتي في المرتبة الثانية.","h2":"في Wyoming، الذهاب إلى المستشفى بسبب حالة طبية طارئة لا يحتاج إلى نموذج الاستثناء.","p":"صحيح. الحالة الطبية الطارئة لا تحتاج إلى نموذج."},"ref":{"doc":"WY","page":null}},{"id":"wy-009","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how many passengers under 18 who are not immediate family may an intermediate permit holder carry?","o":["None","One","Two","Three"],"h1":"It is the smallest number that is more than zero.","h2":"In Wyoming, an intermediate permit holder may carry no more than one passenger under 18 who is not an immediate family member.","p":"Right. Only one non-family passenger under 18."},"es":{"q":"En Wyoming, ¿cuántos pasajeros menores de 18 años que no son familia directa puede llevar quien tiene permiso intermedio?","o":["Ninguno","Uno","Dos","Tres"],"h1":"Es el número más pequeño mayor que cero.","h2":"En Wyoming, quien tiene permiso intermedio puede llevar como máximo un pasajero menor de 18 años que no sea familiar directo.","p":"Correcto. Solo un pasajero menor de 18 que no sea familia."},"zh":{"q":"在 Wyoming，持中级驾照的人可以载几名不是直系亲属、未满 18 岁的乘客？","o":["一名也不可以","一名","两名","三名"],"h1":"它是比零大的最小数字。","h2":"在 Wyoming，持中级驾照的人最多只可以载一名不是直系亲属、未满 18 岁的乘客。","p":"对。只可以载一名不是家人、未满 18 岁的乘客。"},"vi":{"q":"Ở Wyoming, người có giấy phép trung cấp được chở bao nhiêu hành khách dưới 18 tuổi không phải là người thân trong gia đình?","o":["Không ai","Một","Hai","Ba"],"h1":"Đó là số nhỏ nhất lớn hơn không.","h2":"Ở Wyoming, người có giấy phép trung cấp được chở không quá một hành khách dưới 18 tuổi không phải là người thân trong gia đình.","p":"Đúng. Chỉ một hành khách dưới 18 tuổi không phải người nhà."},"tl":{"q":"Sa Wyoming, ilang pasaherong wala pang 18 at hindi malapit na kapamilya ang puwedeng isakay ng may intermediate permit?","o":["Wala","Isa","Dalawa","Tatlo"],"h1":"Ito ang pinakamaliit na bilang na higit sa zero.","h2":"Sa Wyoming, hindi hihigit sa isang pasaherong wala pang 18 at hindi malapit na kapamilya ang puwedeng isakay ng may intermediate permit.","p":"Tama. Isa lang na pasaherong wala pang 18 na hindi kapamilya."},"ar":{"q":"في Wyoming، كم راكبًا عمره أقل من 18 سنة وليس من العائلة المباشرة يمكن أن يحمل حامل التصريح المتوسط؟","o":["لا أحد","واحد","اثنان","ثلاثة"],"h1":"هو أصغر عدد أكبر من الصفر.","h2":"في Wyoming لا يمكن لحامل التصريح المتوسط أن يحمل أكثر من راكب واحد عمره أقل من 18 سنة وليس من العائلة المباشرة.","p":"صحيح. راكب واحد فقط عمره أقل من 18 سنة وليس من العائلة."},"ref":{"doc":"WY","page":14}},{"id":"wy-010","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, when does the passenger limit for an intermediate permit holder not apply?","o":["When a licensed driver age 18 or older is in the car with you","On weekends","On rural roads","When the radio is off"],"h1":"Having an experienced adult driver along changes the rule.","h2":"In Wyoming, the passenger limit does not apply when a licensed driver who is at least 18 rides in the car with you.","p":"Right. A licensed driver 18 or older riding with you lifts the limit."},"es":{"q":"En Wyoming, ¿cuándo no aplica el límite de pasajeros para quien tiene permiso intermedio?","o":["Cuando un conductor con licencia de 18 años o más va en el carro con usted","Los fines de semana","En caminos rurales","Cuando el radio está apagado"],"h1":"Tener a un adulto con licencia en el carro cambia la regla.","h2":"En Wyoming, el límite de pasajeros no aplica cuando un conductor con licencia de por lo menos 18 años va en el carro con usted.","p":"Correcto. Un conductor con licencia de 18 años o más en el carro quita el límite."},"zh":{"q":"在 Wyoming，什么时候中级驾照的乘客人数限制不适用？","o":["有一名 18 岁或以上、有驾照的司机和你一起在车里时","在周末","在乡村道路上","收音机关着的时候"],"h1":"有一位有经验的成年司机同行，规定就会不同。","h2":"在 Wyoming，如果有一名至少 18 岁、有驾照的司机和你一起坐在车里，乘客人数限制就不适用。","p":"对。有一名 18 岁或以上、有驾照的司机和你同车，就没有这个限制。"},"vi":{"q":"Ở Wyoming, khi nào giới hạn số hành khách của người có giấy phép trung cấp không áp dụng?","o":["Khi có một người có bằng lái từ 18 tuổi trở lên ngồi trong xe với bạn","Vào cuối tuần","Trên đường nông thôn","Khi tắt radio"],"h1":"Có một người lớn lái xe có kinh nghiệm đi cùng sẽ làm thay đổi quy định.","h2":"Ở Wyoming, giới hạn số hành khách không áp dụng khi có một người có bằng lái ít nhất 18 tuổi ngồi trong xe với bạn.","p":"Đúng. Có một người có bằng lái từ 18 tuổi trở lên đi cùng thì không còn giới hạn này."},"tl":{"q":"Sa Wyoming, kailan hindi umiiral ang limitasyon sa pasahero ng may intermediate permit?","o":["Kapag may kasama kang lisensiyadong driver na 18 taong gulang o higit pa sa kotse","Tuwing weekend","Sa mga kalsada sa probinsiya","Kapag nakapatay ang radyo"],"h1":"Nagbabago ang patakaran kapag may kasamang may karanasang adult na driver.","h2":"Sa Wyoming, hindi umiiral ang limitasyon sa pasahero kapag may kasama kang lisensiyadong driver na hindi bababa sa 18 taong gulang sa kotse.","p":"Tama. Kapag may kasama kang lisensiyadong driver na 18 o higit pa, wala na ang limitasyon."},"ar":{"q":"في Wyoming، متى لا ينطبق حدّ عدد الركاب على حامل التصريح المتوسط؟","o":["عندما يكون معك في السيارة سائق مرخّص عمره 18 سنة أو أكثر","في عطلة نهاية الأسبوع","على الطرق الريفية","عندما يكون الراديو مطفأً"],"h1":"وجود سائق بالغ صاحب خبرة معك يغيّر القاعدة.","h2":"في Wyoming لا ينطبق حدّ عدد الركاب عندما يركب معك في السيارة سائق مرخّص عمره 18 سنة على الأقل.","p":"صحيح. وجود سائق مرخّص عمره 18 سنة أو أكثر معك يرفع هذا الحدّ."},"ref":{"doc":"WY","page":14}},{"id":"wy-011","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how long must you hold an intermediate permit?","o":["30 days","3 months","Six months or until age 17","Until age 18"],"h1":"It is half a year, unless a birthday comes first.","h2":"In Wyoming you must hold the intermediate permit for at least six months or until you turn 17.","p":"Right. Six months or until 17."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe tener el permiso intermedio?","o":["30 días","3 meses","Seis meses o hasta los 17 años","Hasta los 18 años"],"h1":"Es medio año, a menos que llegue antes un cumpleaños.","h2":"En Wyoming usted debe tener el permiso intermedio por lo menos seis meses o hasta cumplir 17 años.","p":"Correcto. Seis meses o hasta los 17."},"zh":{"q":"在 Wyoming，必须持有中级驾照多久？","o":["30 天","3 个月","六个月或到 17 岁","到 18 岁"],"h1":"它是半年，除非生日先到。","h2":"在 Wyoming，你必须持有中级驾照至少六个月，或者持有到你满 17 岁。","p":"对。六个月或到 17 岁。"},"vi":{"q":"Ở Wyoming, bạn phải giữ giấy phép trung cấp bao lâu?","o":["30 ngày","3 tháng","Sáu tháng hoặc đến 17 tuổi","Đến 18 tuổi"],"h1":"Đó là nửa năm, trừ khi sinh nhật đến trước.","h2":"Ở Wyoming, bạn phải giữ giấy phép trung cấp ít nhất sáu tháng hoặc cho đến khi bạn 17 tuổi.","p":"Đúng. Sáu tháng hoặc đến 17 tuổi."},"tl":{"q":"Sa Wyoming, gaano katagal mo dapat hawak ang intermediate permit?","o":["30 araw","3 buwan","Anim na buwan o hanggang 17 taong gulang","Hanggang 18 taong gulang"],"h1":"Kalahating taon ito, maliban kung mauna ang kaarawan.","h2":"Sa Wyoming, dapat mong hawak ang intermediate permit nang hindi bababa sa anim na buwan o hanggang mag-17 ka.","p":"Tama. Anim na buwan o hanggang 17."},"ar":{"q":"في Wyoming، كم مدة يجب أن تحمل التصريح المتوسط؟","o":["30 يومًا","3 أشهر","ستة أشهر أو حتى عمر 17 سنة","حتى عمر 18 سنة"],"h1":"هي نصف سنة، إلا إذا جاء عيد الميلاد أولًا.","h2":"في Wyoming يجب أن تحمل التصريح المتوسط ستة أشهر على الأقل أو حتى تبلغ 17 سنة.","p":"صحيح. ستة أشهر أو حتى 17 سنة."},"ref":{"doc":"WY","page":7}},{"id":"wy-012","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the highest speed limit on interstate highways?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Some interstate parts are 75 mph. The top limit is a little higher.","h2":"In Wyoming the highest interstate speed limit is 80 mph, and some interstate sections are 75 mph, so always obey the posted sign.","p":"Right. The top limit on Wyoming interstates is 80 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad más alto en las autopistas interestatales?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Algunas partes de la interestatal son de 75 mph. El límite más alto es un poco mayor.","h2":"En Wyoming el límite más alto en las interestatales es de 80 mph, y algunas partes son de 75 mph, así que siempre obedezca el letrero.","p":"Correcto. El límite más alto en las interestatales de Wyoming es de 80 mph."},"zh":{"q":"在 Wyoming，州际公路（interstate）上最高的限速是多少？","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"有些州际公路路段是 75 mph。最高限速再高一点。","h2":"在 Wyoming，州际公路的最高限速是 80 mph，有些州际公路路段是 75 mph，所以一定要遵守路边标志上的限速。","p":"对。Wyoming 州际公路的最高限速是 80 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ cao nhất trên xa lộ liên bang (interstate) là bao nhiêu?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"Một số đoạn xa lộ liên bang là 75 mph. Giới hạn cao nhất cao hơn một chút.","h2":"Ở Wyoming, giới hạn tốc độ cao nhất trên xa lộ liên bang là 80 mph, và một số đoạn là 75 mph, vì vậy luôn tuân theo biển báo.","p":"Đúng. Giới hạn cao nhất trên xa lộ liên bang ở Wyoming là 80 mph."},"tl":{"q":"Sa Wyoming, ano ang pinakamataas na speed limit sa mga interstate highway?","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"May mga bahagi ng interstate na 75 mph. Medyo mas mataas ang pinakamataas na limit.","h2":"Sa Wyoming, 80 mph ang pinakamataas na speed limit sa interstate, at 75 mph ang ilang bahagi nito, kaya laging sundin ang nakapaskil na karatula.","p":"Tama. 80 mph ang pinakamataas na limit sa mga interstate sa Wyoming."},"ar":{"q":"في Wyoming، ما أعلى حد للسرعة على الطرق السريعة بين الولايات (interstate)؟","o":["65 mph","70 mph","80 mph","90 mph"],"h1":"بعض أجزاء الطرق السريعة بين الولايات حدها 75 mph. والحد الأعلى أكبر قليلًا.","h2":"في Wyoming أعلى حد للسرعة على الطرق السريعة بين الولايات هو 80 mph، وبعض الأجزاء حدها 75 mph، لذلك اتبع دائمًا اللافتة الموجودة.","p":"صحيح. أعلى حد على الطرق السريعة بين الولايات في Wyoming هو 80 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-013","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, what is the speed limit on a state highway that is not an interstate, when no other limit is posted?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"It is ten less than the interstate limit.","h2":"In Wyoming the speed limit on a state highway that is not an interstate is 70 mph unless another limit is posted.","p":"Right. State highways that are not interstates are 70 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una carretera estatal que no es interestatal, cuando no hay otro límite indicado?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Es diez menos que el límite de la interestatal.","h2":"En Wyoming el límite de velocidad en una carretera estatal que no es interestatal es de 70 mph, a menos que haya otro límite indicado.","p":"Correcto. Las carreteras estatales que no son interestatales son de 70 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，不是州际公路的州公路（state highway）限速是多少？","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"它比州际公路的限速少十。","h2":"在 Wyoming，不是州际公路的州公路限速是 70 mph，除非标出其他限速。","p":"对。不是州际公路的州公路限速是 70 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trên quốc lộ tiểu bang (state highway) không phải xa lộ liên bang là bao nhiêu, khi không có biển báo giới hạn khác?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Nó ít hơn giới hạn trên xa lộ liên bang mười.","h2":"Ở Wyoming, giới hạn tốc độ trên quốc lộ tiểu bang không phải xa lộ liên bang là 70 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Quốc lộ tiểu bang không phải xa lộ liên bang là 70 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa state highway na hindi interstate, kapag walang ibang nakapaskil na limit?","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa interstate.","h2":"Sa Wyoming, 70 mph ang speed limit sa state highway na hindi interstate, maliban kung may ibang nakapaskil na limit.","p":"Tama. 70 mph ang mga state highway na hindi interstate."},"ar":{"q":"في Wyoming، ما حد السرعة على طريق الولاية السريع (state highway) الذي ليس طريقًا بين الولايات، عندما لا توجد لافتة بحد آخر؟","o":["55 mph","70 mph","75 mph","80 mph"],"h1":"هو أقل بعشرة من حد الطرق السريعة بين الولايات.","h2":"في Wyoming حد السرعة على طريق الولاية السريع الذي ليس طريقًا بين الولايات هو 70 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. طرق الولاية السريعة التي ليست بين الولايات حدها 70 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-014","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit on an unpaved road when no other limit is posted?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"It is fifteen less than on a paved road.","h2":"In Wyoming the speed limit on an unpaved road is 55 mph unless another limit is posted.","p":"Right. Unpaved roads are 55 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en un camino sin pavimentar cuando no hay otro límite indicado?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Es quince menos que en un camino pavimentado.","h2":"En Wyoming el límite de velocidad en un camino sin pavimentar es de 55 mph, a menos que haya otro límite indicado.","p":"Correcto. Los caminos sin pavimentar son de 55 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，没有铺路面的道路限速是多少？","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"它比有铺路面的道路少十五。","h2":"在 Wyoming，没有铺路面的道路限速是 55 mph，除非标出其他限速。","p":"对。没有铺路面的道路限速是 55 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trên đường không trải nhựa là bao nhiêu, khi không có biển báo giới hạn khác?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Nó ít hơn đường trải nhựa mười lăm.","h2":"Ở Wyoming, giới hạn tốc độ trên đường không trải nhựa là 55 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Đường không trải nhựa là 55 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa daang hindi sementado, kapag walang ibang nakapaskil na limit?","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"Labinlima itong mas mababa kaysa sa sementadong daan.","h2":"Sa Wyoming, 55 mph ang speed limit sa daang hindi sementado, maliban kung may ibang nakapaskil na limit.","p":"Tama. 55 mph ang mga daang hindi sementado."},"ar":{"q":"في Wyoming، ما حد السرعة على طريق غير معبّد، عندما لا توجد لافتة بحد آخر؟","o":["55 mph","45 mph","65 mph","70 mph"],"h1":"هو أقل بخمسة عشر من الطريق المعبّد.","h2":"في Wyoming حد السرعة على الطريق غير المعبّد هو 55 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. الطرق غير المعبّدة حدها 55 mph."},"ref":{"doc":"WY","page":null}},{"id":"wy-015","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, what is the speed limit in an urban area when no other limit is posted?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"It is ten more than a school zone.","h2":"In Wyoming the speed limit in urban areas is 30 mph unless another limit is posted.","p":"Right. Urban areas are 30 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona urbana cuando no hay otro límite indicado?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Es diez más que en una zona escolar.","h2":"En Wyoming el límite de velocidad en zonas urbanas es de 30 mph, a menos que haya otro límite indicado.","p":"Correcto. Las zonas urbanas son de 30 mph."},"zh":{"q":"在 Wyoming，没有标出其他限速时，城市地区的限速是多少？","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"它比学校区多十。","h2":"在 Wyoming，城市地区的限速是 30 mph，除非标出其他限速。","p":"对。城市地区限速是 30 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trong khu đô thị là bao nhiêu, khi không có biển báo giới hạn khác?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Nó nhiều hơn khu vực trường học mười.","h2":"Ở Wyoming, giới hạn tốc độ trong khu đô thị là 30 mph, trừ khi có biển báo giới hạn khác.","p":"Đúng. Khu đô thị là 30 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa lungsod (urban area), kapag walang ibang nakapaskil na limit?","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"Sampu itong mas mataas kaysa sa school zone.","h2":"Sa Wyoming, 30 mph ang speed limit sa lungsod, maliban kung may ibang nakapaskil na limit.","p":"Tama. 30 mph sa lungsod."},"ar":{"q":"في Wyoming، ما حد السرعة في المناطق الحضرية، عندما لا توجد لافتة بحد آخر؟","o":["20 mph","25 mph","30 mph","35 mph"],"h1":"هو أكثر بعشرة من منطقة المدرسة.","h2":"في Wyoming حد السرعة في المناطق الحضرية هو 30 mph، إلا إذا كانت هناك لافتة بحد آخر.","p":"صحيح. المناطق الحضرية حدها 30 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-016","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit in a signed school zone with a reduced limit?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"It is ten less than the urban limit.","h2":"In Wyoming the speed limit in a school zone with signs showing the reduced limit is 20 mph.","p":"Right. School zones are 20 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una zona escolar señalizada con límite reducido?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Es diez menos que el límite urbano.","h2":"En Wyoming el límite de velocidad en una zona escolar con letreros de límite reducido es de 20 mph.","p":"Correcto. Las zonas escolares son de 20 mph."},"zh":{"q":"在 Wyoming，有标志标出降低限速的学校区（school zone），限速是多少？","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"它比城市地区的限速少十。","h2":"在 Wyoming，有标志标出降低限速的学校区，限速是 20 mph。","p":"对。学校区限速是 20 mph。"},"vi":{"q":"Ở Wyoming, giới hạn tốc độ trong khu vực trường học (school zone) có biển báo giảm tốc độ là bao nhiêu?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Nó ít hơn giới hạn trong khu đô thị mười.","h2":"Ở Wyoming, giới hạn tốc độ trong khu vực trường học có biển báo giảm tốc độ là 20 mph.","p":"Đúng. Khu vực trường học là 20 mph."},"tl":{"q":"Sa Wyoming, ano ang speed limit sa school zone na may karatula ng mas mababang limit?","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"Sampu itong mas mababa kaysa sa limit sa lungsod.","h2":"Sa Wyoming, 20 mph ang speed limit sa school zone na may karatulang nagpapakita ng mas mababang limit.","p":"Tama. 20 mph sa mga school zone."},"ar":{"q":"في Wyoming، ما حد السرعة في منطقة المدرسة (school zone) التي فيها لافتات بحد مخفّض؟","o":["20 mph","15 mph","25 mph","30 mph"],"h1":"هو أقل بعشرة من حد المناطق الحضرية.","h2":"في Wyoming حد السرعة في منطقة المدرسة التي فيها لافتات تبيّن الحد المخفّض هو 20 mph.","p":"صحيح. مناطق المدارس حدها 20 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-017","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver under 21 may not drive with a blood alcohol level of what amount or more?","o":[".05 percent",".02 percent",".08 percent",".10 percent"],"h1":"It is a tiny fraction of the adult limit.","h2":"In Wyoming a driver under 21 may not drive with a blood alcohol level of .02 percent or more.","p":"Right. Under 21, the limit is .02."},"es":{"q":"En Wyoming, ¿a partir de qué nivel de alcohol en la sangre no puede manejar un conductor menor de 21 años?","o":[".05 por ciento",".02 por ciento",".08 por ciento",".10 por ciento"],"h1":"Es una fracción muy pequeña del límite para adultos.","h2":"En Wyoming un conductor menor de 21 años no puede manejar con un nivel de alcohol en la sangre de .02 por ciento o más.","p":"Correcto. Para menores de 21, el límite es .02."},"zh":{"q":"在 Wyoming，未满 21 岁的司机血液酒精浓度达到多少或以上就不可以开车？","o":["0.05%","0.02%","0.08%","0.10%"],"h1":"它是成年人限制的很小一部分。","h2":"在 Wyoming，未满 21 岁的司机血液酒精浓度达到 0.02% 或以上就不可以开车。","p":"对。未满 21 岁，限制是 0.02%。"},"vi":{"q":"Ở Wyoming, tài xế dưới 21 tuổi không được lái xe khi nồng độ cồn trong máu từ mức nào trở lên?","o":[".05 phần trăm",".02 phần trăm",".08 phần trăm",".10 phần trăm"],"h1":"Đó là một phần rất nhỏ của giới hạn cho người lớn.","h2":"Ở Wyoming, tài xế dưới 21 tuổi không được lái xe khi nồng độ cồn trong máu từ .02 phần trăm trở lên.","p":"Đúng. Dưới 21 tuổi, giới hạn là .02."},"tl":{"q":"Sa Wyoming, hindi puwedeng magmaneho ang driver na wala pang 21 kapag ang alak sa dugo niya ay umabot sa anong antas o higit pa?","o":[".05 porsiyento",".02 porsiyento",".08 porsiyento",".10 porsiyento"],"h1":"Napakaliit na bahagi ito ng limit para sa adulto.","h2":"Sa Wyoming, hindi puwedeng magmaneho ang driver na wala pang 21 kapag .02 porsiyento o higit pa ang alak sa dugo niya.","p":"Tama. Kapag wala pang 21, .02 ang limit."},"ar":{"q":"في Wyoming، لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود إذا كانت نسبة الكحول في دمه تبلغ أي مقدار أو أكثر؟","o":[".05 بالمئة",".02 بالمئة",".08 بالمئة",".10 بالمئة"],"h1":"هي جزء صغير جدًا من حد البالغين.","h2":"في Wyoming لا يجوز للسائق الذي عمره أقل من 21 سنة أن يقود إذا كانت نسبة الكحول في دمه .02 بالمئة أو أكثر.","p":"صحيح. لمن عمره أقل من 21 سنة، الحد هو .02."},"ref":{"doc":"WY","page":22}},{"id":"wy-018","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, how long is the license suspension when a driver under 21 is found driving at .02 or more?","o":["7 days","30 days","One year","90 days"],"h1":"It is about three months.","h2":"In Wyoming, a driver under 21 caught driving at .02 or more has the license suspended for 90 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Wyoming, ¿cuánto dura la suspensión de la licencia cuando un conductor menor de 21 años maneja con .02 o más?","o":["7 días","30 días","Un año","90 días"],"h1":"Son unos tres meses.","h2":"En Wyoming, a un conductor menor de 21 años que maneja con .02 o más se le suspende la licencia por 90 días.","p":"Correcto. La suspensión es de 90 días."},"zh":{"q":"在 Wyoming，未满 21 岁的司机被发现血液酒精浓度在 0.02% 或以上开车，驾照会被吊销多久？","o":["7 天","30 天","一年","90 天"],"h1":"大约三个月。","h2":"在 Wyoming，未满 21 岁的司机被发现血液酒精浓度在 0.02% 或以上开车，驾照会被吊销 90 天。","p":"对。吊销 90 天。"},"vi":{"q":"Ở Wyoming, bằng lái bị đình chỉ bao lâu khi tài xế dưới 21 tuổi bị phát hiện lái xe với nồng độ cồn từ .02 trở lên?","o":["7 ngày","30 ngày","Một năm","90 ngày"],"h1":"Khoảng ba tháng.","h2":"Ở Wyoming, tài xế dưới 21 tuổi bị bắt khi lái xe với nồng độ cồn từ .02 trở lên sẽ bị đình chỉ bằng lái 90 ngày.","p":"Đúng. Bị đình chỉ 90 ngày."},"tl":{"q":"Sa Wyoming, gaano katagal ang suspensiyon ng lisensiya kapag nahuling nagmamaneho ang driver na wala pang 21 na may .02 o higit pa?","o":["7 araw","30 araw","Isang taon","90 araw"],"h1":"Mga tatlong buwan ito.","h2":"Sa Wyoming, sinususpinde nang 90 araw ang lisensiya ng driver na wala pang 21 na nahuling nagmamaneho na may .02 o higit pa.","p":"Tama. 90 araw ang suspensiyon."},"ar":{"q":"في Wyoming، كم مدة إيقاف الرخصة عندما يُضبط سائق عمره أقل من 21 سنة يقود ونسبة الكحول .02 أو أكثر؟","o":["7 أيام","30 يومًا","سنة واحدة","90 يومًا"],"h1":"هي حوالي ثلاثة أشهر.","h2":"في Wyoming، السائق الذي عمره أقل من 21 سنة ويُضبط يقود ونسبة الكحول .02 أو أكثر تُوقف رخصته 90 يومًا.","p":"صحيح. الإيقاف 90 يومًا."},"ref":{"doc":"WY","page":22}},{"id":"wy-019","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, which speeding tickets always go on your driving record?","o":["Only tickets on interstates","Only tickets at night","Speeding in a school zone or construction zone","None of them"],"h1":"Think of places where children or workers may be near the road.","h2":"In Wyoming, a speeding violation in a school zone or a construction zone always goes on your driving record.","p":"Right. School and construction zones go on the record."},"es":{"q":"En Wyoming, ¿qué multas por exceso de velocidad siempre quedan en su historial de manejo?","o":["Solo las de autopistas interestatales","Solo las de noche","Las de exceso de velocidad en zona escolar o zona de obras","Ninguna"],"h1":"Piense en lugares donde puede haber niños o trabajadores cerca de la vía.","h2":"En Wyoming, una infracción por exceso de velocidad en una zona escolar o zona de obras siempre queda en su historial de manejo.","p":"Correcto. Las zonas escolares y de obras quedan en el historial."},"zh":{"q":"在 Wyoming，哪些超速罚单一定会记录在你的驾驶记录上？","o":["只有州际公路上的罚单","只有夜间的罚单","在学校区或施工区超速","都不会"],"h1":"想一想孩子或工人可能在路边的地方。","h2":"在 Wyoming，在学校区或施工区超速，一定会记录在你的驾驶记录上。","p":"对。学校区和施工区的超速会记录在驾驶记录上。"},"vi":{"q":"Ở Wyoming, loại vé phạt chạy quá tốc độ nào luôn được ghi vào hồ sơ lái xe của bạn?","o":["Chỉ vé phạt trên xa lộ liên bang","Chỉ vé phạt vào ban đêm","Chạy quá tốc độ trong khu vực trường học hoặc khu vực thi công","Không loại nào"],"h1":"Hãy nghĩ đến những nơi trẻ em hoặc công nhân có thể ở gần đường.","h2":"Ở Wyoming, vi phạm tốc độ trong khu vực trường học hoặc khu vực thi công luôn được ghi vào hồ sơ lái xe của bạn.","p":"Đúng. Khu vực trường học và khu vực thi công được ghi vào hồ sơ."},"tl":{"q":"Sa Wyoming, aling mga tiket sa sobrang bilis ang laging napupunta sa driving record mo?","o":["Mga tiket sa interstate lang","Mga tiket sa gabi lang","Sobrang bilis sa school zone o construction zone","Wala sa kanila"],"h1":"Isipin ang mga lugar kung saan maaaring malapit sa daan ang mga bata o manggagawa.","h2":"Sa Wyoming, laging napupunta sa driving record mo ang paglabag sa bilis sa school zone o construction zone.","p":"Tama. Napupunta sa record ang mga school zone at construction zone."},"ar":{"q":"في Wyoming، أي مخالفات السرعة تُسجّل دائمًا في سجل القيادة الخاص بك؟","o":["المخالفات على الطرق السريعة بين الولايات فقط","المخالفات في الليل فقط","السرعة الزائدة في منطقة مدرسة أو منطقة أعمال إنشاء","لا شيء منها"],"h1":"فكّر في الأماكن التي قد يكون فيها أطفال أو عمّال قرب الطريق.","h2":"في Wyoming، مخالفة السرعة في منطقة مدرسة أو منطقة أعمال إنشاء تُسجّل دائمًا في سجل القيادة الخاص بك.","p":"صحيح. مناطق المدارس ومناطق الإنشاء تُسجّل في السجل."},"ref":{"doc":"WY","page":null}},{"id":"wy-020","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, is texting while driving allowed?","o":["Yes, on rural roads","No, texting while driving is banned","Yes, if you are over 21","Only at speeds under 30 mph"],"h1":"Reading or sending a message takes your eyes off the road.","h2":"Wyoming bans texting while driving, so you may not write, send or read a text message while driving on a public road.","p":"Right. Texting while driving is banned."},"es":{"q":"En Wyoming, ¿se permite enviar mensajes de texto mientras maneja?","o":["Sí, en caminos rurales","No, está prohibido enviar mensajes mientras maneja","Sí, si es mayor de 21 años","Solo a menos de 30 mph"],"h1":"Leer o enviar un mensaje le quita la vista de la vía.","h2":"Wyoming prohíbe enviar mensajes de texto mientras maneja, así que usted no puede escribir, enviar ni leer un mensaje mientras maneja en una vía pública.","p":"Correcto. Está prohibido enviar mensajes mientras maneja."},"zh":{"q":"在 Wyoming，开车时可以发短信吗？","o":["可以，在乡村道路上","不可以，开车时发短信是被禁止的","可以，如果你超过 21 岁","只有车速低于 30 mph 时可以"],"h1":"看或发信息会让你的眼睛离开道路。","h2":"Wyoming 禁止开车时发短信，所以在公共道路上开车时，你不可以写、发送或阅读短信。","p":"对。开车时发短信是被禁止的。"},"vi":{"q":"Ở Wyoming, có được nhắn tin khi đang lái xe không?","o":["Có, trên đường nông thôn","Không, nhắn tin khi lái xe bị cấm","Có, nếu bạn trên 21 tuổi","Chỉ khi chạy dưới 30 mph"],"h1":"Đọc hoặc gửi tin nhắn làm mắt bạn rời khỏi đường.","h2":"Wyoming cấm nhắn tin khi lái xe, vì vậy bạn không được viết, gửi hoặc đọc tin nhắn khi lái xe trên đường công cộng.","p":"Đúng. Nhắn tin khi lái xe bị cấm."},"tl":{"q":"Sa Wyoming, pinapayagan ba ang pag-text habang nagmamaneho?","o":["Oo, sa mga daan sa probinsiya","Hindi, bawal ang pag-text habang nagmamaneho","Oo, kung lampas 21 ka na","Kapag mas mababa lang sa 30 mph ang bilis"],"h1":"Inaalis ng pagbasa o pagpapadala ng mensahe ang mata mo sa daan.","h2":"Bawal sa Wyoming ang pag-text habang nagmamaneho, kaya hindi ka puwedeng sumulat, magpadala o magbasa ng text habang nagmamaneho sa pampublikong daan.","p":"Tama. Bawal ang pag-text habang nagmamaneho."},"ar":{"q":"في Wyoming، هل يُسمح بكتابة الرسائل النصية أثناء القيادة؟","o":["نعم، على الطرق الريفية","لا، كتابة الرسائل أثناء القيادة ممنوعة","نعم، إذا كان عمرك أكثر من 21 سنة","فقط عندما تكون السرعة أقل من 30 mph"],"h1":"قراءة رسالة أو إرسالها تبعد عينيك عن الطريق.","h2":"تمنع Wyoming كتابة الرسائل النصية أثناء القيادة، لذلك لا يجوز لك أن تكتب أو ترسل أو تقرأ رسالة نصية أثناء القيادة على طريق عام.","p":"صحيح. كتابة الرسائل أثناء القيادة ممنوعة."},"ref":{"doc":"WY","page":89}},{"id":"wy-021","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, after a crash, when must you contact the police?","o":["Only when a car must be towed","Only when someone wants to sue","When someone is hurt or killed, or damage is $1,000 or more","Only when the crash happens on an interstate"],"h1":"Think about injuries and the dollar amount of the damage.","h2":"In Wyoming you must contact the police when a crash causes an injury, a death, or property damage of $1,000 or more.","p":"Right. Injury, death, or $1,000 or more in damage means you call the police."},"es":{"q":"En Wyoming, después de un choque, ¿cuándo debe usted avisar a la policía?","o":["Solo cuando hay que remolcar un auto","Solo cuando alguien quiere demandar","Cuando alguien resulta herido o muere, o el daño es de $1,000 o más","Solo cuando el choque ocurre en una autopista interestatal"],"h1":"Piense en los heridos y en el valor en dólares del daño.","h2":"En Wyoming usted debe avisar a la policía cuando un choque causa heridos, una muerte o daños a la propiedad de $1,000 o más.","p":"Correcto. Heridos, una muerte o $1,000 o más en daños significa que usted llama a la policía."},"zh":{"q":"在 Wyoming，发生车祸后，什么时候必须联系警察？","o":["只有车必须被拖走时","只有有人想起诉时","有人受伤或死亡，或损失达到 $1,000 或以上时","只有车祸发生在州际公路上时"],"h1":"想一想受伤情况和损失的金额。","h2":"在 Wyoming，如果车祸造成有人受伤、有人死亡，或财产损失达到 $1,000 或以上，你必须联系警察。","p":"对。有人受伤、死亡，或损失达到 $1,000 或以上，就要打电话给警察。"},"vi":{"q":"Ở Wyoming, sau một vụ tai nạn, khi nào bạn phải liên lạc với cảnh sát?","o":["Chỉ khi xe phải bị kéo đi","Chỉ khi có người muốn kiện","Khi có người bị thương hoặc tử vong, hoặc thiệt hại từ $1,000 trở lên","Chỉ khi tai nạn xảy ra trên xa lộ liên tiểu bang"],"h1":"Hãy nghĩ về người bị thương và số tiền thiệt hại.","h2":"Ở Wyoming, bạn phải liên lạc với cảnh sát khi tai nạn làm có người bị thương, có người tử vong, hoặc gây thiệt hại tài sản từ $1,000 trở lên.","p":"Đúng. Có người bị thương, tử vong, hoặc thiệt hại từ $1,000 trở lên thì bạn gọi cảnh sát."},"tl":{"q":"Sa Wyoming, pagkatapos ng banggaan, kailan mo dapat tawagan ang pulis?","o":["Kapag kailangan lang hilahin ang kotse","Kapag may gusto lang magdemanda","Kapag may nasaktan o namatay, o ang pinsala ay $1,000 o higit pa","Kapag nangyari lang ang banggaan sa interstate"],"h1":"Isipin ang mga nasaktan at ang halaga ng pinsala.","h2":"Sa Wyoming, dapat mong tawagan ang pulis kapag ang banggaan ay nagdulot ng pinsala sa tao, pagkamatay, o pinsala sa ari-arian na $1,000 o higit pa.","p":"Tama. Kapag may nasaktan, namatay, o $1,000 o higit pa ang pinsala, tawagan ang pulis."},"ar":{"q":"في Wyoming، بعد حادث سير، متى يجب أن تتصل بالشرطة؟","o":["فقط عندما يجب سحب السيارة","فقط عندما يريد أحد أن يرفع دعوى","عندما يُصاب أحد أو يموت، أو تكون الأضرار $1,000 أو أكثر","فقط عندما يقع الحادث على طريق سريع بين الولايات"],"h1":"فكّر في الإصابات وفي قيمة الأضرار بالدولار.","h2":"في Wyoming يجب أن تتصل بالشرطة عندما يسبب الحادث إصابة أو وفاة أو أضرارًا في الممتلكات قيمتها $1,000 أو أكثر.","p":"صحيح. إذا كانت هناك إصابة أو وفاة أو أضرار بقيمة $1,000 أو أكثر، فاتصل بالشرطة."},"ref":{"doc":"WY","page":67}},{"id":"wy-022","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, on a two-lane road posted at 45 mph or more, you pass a stopped emergency vehicle with its lights on. What must you do?","o":["Keep your speed and honk","Slow to 20 mph below the posted limit","Slow to 5 mph below the posted limit","Stop and wait until it leaves"],"h1":"On a two-lane road you cannot change lanes, so you slow down a lot.","h2":"In Wyoming, on a two-lane road posted at 45 mph or more, you must slow to 20 mph below the posted limit when passing a stopped emergency vehicle.","p":"Right. Wyoming's Move Over law says slow to 20 mph under the limit there."},"es":{"q":"En Wyoming, en una carretera de dos carriles con límite de 45 mph o más, usted pasa un vehículo de emergencia detenido con las luces encendidas. ¿Qué debe hacer?","o":["Mantener su velocidad y tocar la bocina","Bajar a 20 mph menos que el límite indicado","Bajar a 5 mph menos que el límite indicado","Detenerse y esperar a que se vaya"],"h1":"En una carretera de dos carriles no puede cambiar de carril, así que reduce mucho la velocidad.","h2":"En Wyoming, en una carretera de dos carriles con límite de 45 mph o más, usted debe bajar a 20 mph menos que el límite al pasar un vehículo de emergencia detenido.","p":"Correcto. La ley de Move Over de Wyoming pide bajar a 20 mph menos que el límite en ese caso."},"zh":{"q":"在 Wyoming，在限速 45 mph 或以上的双车道道路上，你经过一辆停着并亮着灯的紧急车辆。你必须怎么做？","o":["保持车速并按喇叭","减速到比限速低 20 mph","减速到比限速低 5 mph","停车，等它离开"],"h1":"在双车道道路上你不能换车道，所以要大幅减速。","h2":"在 Wyoming，在限速 45 mph 或以上的双车道道路上，经过停着的紧急车辆时，你必须减速到比限速低 20 mph。","p":"对。Wyoming 的 Move Over 法律规定，在这种道路上要减速到比限速低 20 mph。"},"vi":{"q":"Ở Wyoming, trên đường hai làn có tốc độ giới hạn 45 mph trở lên, bạn đi ngang qua một xe cấp cứu đang dừng và bật đèn. Bạn phải làm gì?","o":["Giữ tốc độ và bấm còi","Giảm xuống thấp hơn tốc độ giới hạn 20 mph","Giảm xuống thấp hơn tốc độ giới hạn 5 mph","Dừng lại và chờ cho đến khi xe đó đi"],"h1":"Trên đường hai làn bạn không thể đổi làn, nên bạn phải chạy chậm lại nhiều.","h2":"Ở Wyoming, trên đường hai làn có tốc độ giới hạn 45 mph trở lên, bạn phải giảm xuống thấp hơn tốc độ giới hạn 20 mph khi đi ngang qua xe cấp cứu đang dừng.","p":"Đúng. Luật Move Over của Wyoming nói phải giảm xuống thấp hơn giới hạn 20 mph ở đó."},"tl":{"q":"Sa Wyoming, sa daang may dalawang lane na may limit na 45 mph o higit pa, dadaan ka sa nakahintong emergency vehicle na nakabukas ang ilaw. Ano ang dapat mong gawin?","o":["Panatilihin ang bilis at bumusina","Bumagal hanggang 20 mph na mas mababa sa limit","Bumagal hanggang 5 mph na mas mababa sa limit","Huminto at maghintay hanggang umalis ito"],"h1":"Sa daang may dalawang lane, hindi ka makakalipat ng lane, kaya bumagal ka nang husto.","h2":"Sa Wyoming, sa daang may dalawang lane na may limit na 45 mph o higit pa, dapat kang bumagal hanggang 20 mph na mas mababa sa limit kapag dumadaan sa nakahintong emergency vehicle.","p":"Tama. Sinasabi ng Move Over law ng Wyoming na bumagal hanggang 20 mph na mas mababa sa limit doon."},"ar":{"q":"في Wyoming، على طريق بمسارين حدّ السرعة فيه 45 mph أو أكثر، تمر بجانب مركبة طوارئ متوقفة وأضواؤها تعمل. ماذا يجب أن تفعل؟","o":["حافظ على سرعتك واستخدم البوق","خفّف السرعة إلى 20 mph أقل من الحد المسموح","خفّف السرعة إلى 5 mph أقل من الحد المسموح","توقف وانتظر حتى تغادر"],"h1":"على طريق بمسارين لا يمكنك تغيير المسار، لذلك تخفف السرعة كثيرًا.","h2":"في Wyoming، على طريق بمسارين حدّ السرعة فيه 45 mph أو أكثر، يجب أن تخفف السرعة إلى 20 mph أقل من الحد المسموح عندما تمر بجانب مركبة طوارئ متوقفة.","p":"صحيح. قانون Move Over في Wyoming يقول خفّف السرعة إلى 20 mph أقل من الحد هناك."},"ref":{"doc":"WY","page":72}},{"id":"wy-023","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, until what age must a child ride in a child safety seat or booster, unless the seat belt fits properly?","o":["Until the 4th birthday","Until the 6th birthday","Until the 12th birthday","Until the 9th birthday"],"h1":"It is older than a preschool child, but younger than ten.","h2":"In Wyoming a child must use a child restraint until the 9th birthday, unless the lap and shoulder belt fit properly.","p":"Right. Wyoming's child restraint law covers children under 9."},"es":{"q":"En Wyoming, ¿hasta qué edad debe un niño viajar en un asiento de seguridad o elevador, a menos que el cinturón le quede bien?","o":["Hasta cumplir 4 años","Hasta cumplir 6 años","Hasta cumplir 12 años","Hasta cumplir 9 años"],"h1":"Es mayor que un niño de preescolar, pero menor de diez años.","h2":"En Wyoming un niño debe usar un sistema de retención infantil hasta cumplir 9 años, a menos que el cinturón de regazo y hombro le quede bien.","p":"Correcto. La ley de Wyoming sobre asientos infantiles cubre a los niños menores de 9 años."},"zh":{"q":"在 Wyoming，除非安全带合适，孩子必须坐儿童安全座椅或增高座椅到几岁？","o":["到 4 岁生日","到 6 岁生日","到 12 岁生日","到 9 岁生日"],"h1":"比学龄前儿童大，但比十岁小。","h2":"在 Wyoming，孩子必须使用儿童约束装置直到 9 岁生日，除非腰带和肩带合适。","p":"对。Wyoming 的儿童约束法律适用于 9 岁以下的孩子。"},"vi":{"q":"Ở Wyoming, trẻ em phải ngồi ghế an toàn trẻ em hoặc ghế nâng cho đến tuổi nào, trừ khi dây an toàn vừa vặn?","o":["Cho đến sinh nhật 4 tuổi","Cho đến sinh nhật 6 tuổi","Cho đến sinh nhật 12 tuổi","Cho đến sinh nhật 9 tuổi"],"h1":"Lớn hơn trẻ mẫu giáo, nhưng nhỏ hơn mười tuổi.","h2":"Ở Wyoming, trẻ em phải dùng ghế an toàn trẻ em cho đến sinh nhật 9 tuổi, trừ khi dây đai ngang hông và dây đai vai vừa vặn.","p":"Đúng. Luật ghế an toàn trẻ em của Wyoming áp dụng cho trẻ dưới 9 tuổi."},"tl":{"q":"Sa Wyoming, hanggang anong edad dapat sumakay ang bata sa child safety seat o booster, maliban kung tama ang lapat ng seat belt?","o":["Hanggang ika-4 na kaarawan","Hanggang ika-6 na kaarawan","Hanggang ika-12 na kaarawan","Hanggang ika-9 na kaarawan"],"h1":"Mas matanda ito sa batang preschool, pero mas bata sa sampu.","h2":"Sa Wyoming, dapat gumamit ang bata ng child restraint hanggang sa ika-9 na kaarawan niya, maliban kung tama ang lapat ng lap belt at shoulder belt.","p":"Tama. Sakop ng child restraint law ng Wyoming ang mga batang wala pang 9 taong gulang."},"ar":{"q":"في Wyoming، حتى أي عمر يجب أن يجلس الطفل في مقعد أمان للأطفال أو مقعد رافع، إلا إذا كان حزام الأمان مناسبًا له؟","o":["حتى عيد ميلاده الرابع","حتى عيد ميلاده السادس","حتى عيد ميلاده الثاني عشر","حتى عيد ميلاده التاسع"],"h1":"العمر أكبر من طفل ما قبل المدرسة، لكنه أصغر من عشر سنوات.","h2":"في Wyoming يجب أن يستخدم الطفل مقعد أمان للأطفال حتى عيد ميلاده التاسع، إلا إذا كان حزام الحضن وحزام الكتف مناسبين له.","p":"صحيح. قانون مقاعد الأطفال في Wyoming يشمل الأطفال تحت 9 سنوات."},"ref":{"doc":"WY","page":30}},{"id":"wy-024","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what happens if an intermediate permit holder breaks the permit's rules, such as the night or passenger limits?","o":["A 30-day suspension","A warning letter only","A one-year suspension","A $5 fine only"],"h1":"The suspension is about one month.","h2":"In Wyoming, breaking the rules of an intermediate permit leads to a 30-day suspension.","p":"Right. Breaking the intermediate permit rules means a 30-day suspension."},"es":{"q":"En Wyoming, ¿qué pasa si quien tiene un permiso intermedio no cumple sus reglas, como los límites de noche o de pasajeros?","o":["Una suspensión de 30 días","Solo una carta de advertencia","Una suspensión de un año","Solo una multa de $5"],"h1":"La suspensión dura más o menos un mes.","h2":"En Wyoming, no cumplir las reglas del permiso intermedio lleva a una suspensión de 30 días.","p":"Correcto. No cumplir las reglas del permiso intermedio significa una suspensión de 30 días."},"zh":{"q":"在 Wyoming，如果持有中级驾照的人违反驾照规定，例如夜间或乘客限制，会怎么样？","o":["暂停 30 天","只收到一封警告信","暂停一年","只罚款 $5"],"h1":"暂停时间大约是一个月。","h2":"在 Wyoming，违反中级驾照的规定会导致驾照暂停 30 天。","p":"对。违反中级驾照的规定会被暂停 30 天。"},"vi":{"q":"Ở Wyoming, điều gì xảy ra nếu người có giấy phép trung cấp vi phạm quy định của giấy phép, như giới hạn ban đêm hoặc giới hạn hành khách?","o":["Bị đình chỉ 30 ngày","Chỉ nhận thư cảnh cáo","Bị đình chỉ một năm","Chỉ bị phạt $5"],"h1":"Thời gian đình chỉ khoảng một tháng.","h2":"Ở Wyoming, vi phạm quy định của giấy phép trung cấp sẽ bị đình chỉ 30 ngày.","p":"Đúng. Vi phạm quy định của giấy phép trung cấp nghĩa là bị đình chỉ 30 ngày."},"tl":{"q":"Sa Wyoming, ano ang mangyayari kung lumabag ang may intermediate permit sa mga patakaran ng permit, gaya ng limit sa gabi o sa pasahero?","o":["30 araw na suspensiyon","Sulat ng babala lang","Isang taong suspensiyon","$5 na multa lang"],"h1":"Mga isang buwan ang suspensiyon.","h2":"Sa Wyoming, ang paglabag sa mga patakaran ng intermediate permit ay nagdudulot ng 30 araw na suspensiyon.","p":"Tama. Ang paglabag sa mga patakaran ng intermediate permit ay 30 araw na suspensiyon."},"ar":{"q":"في Wyoming، ماذا يحدث إذا خالف حامل التصريح المتوسط قواعد التصريح، مثل قيود القيادة ليلًا أو عدد الركاب؟","o":["إيقاف لمدة 30 يومًا","رسالة تحذير فقط","إيقاف لمدة سنة","غرامة $5 فقط"],"h1":"مدة الإيقاف حوالي شهر واحد.","h2":"في Wyoming، مخالفة قواعد التصريح المتوسط تؤدي إلى إيقاف لمدة 30 يومًا.","p":"صحيح. مخالفة قواعد التصريح المتوسط تعني إيقافًا لمدة 30 يومًا."},"ref":{"doc":"WY","page":26}},{"id":"wy-026","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver 21 or older takes a breath or blood test and the result is 0.08 percent or more. What happens to the license?","o":["Nothing until a court date","It is suspended for 90 days","It is suspended for 7 days","It is suspended for 5 years"],"h1":"The suspension lasts about three months.","h2":"In Wyoming, a test result of 0.08 percent or more leads to a 90-day license suspension, and there may be criminal penalties too.","p":"Right. A result of 0.08 or more means a 90-day suspension."},"es":{"q":"En Wyoming, un conductor de 21 años o más se hace una prueba de aliento o de sangre y el resultado es 0.08 por ciento o más. ¿Qué pasa con la licencia?","o":["Nada hasta la fecha de la corte","Se suspende por 90 días","Se suspende por 7 días","Se suspende por 5 años"],"h1":"La suspensión dura unos tres meses.","h2":"En Wyoming, un resultado de 0.08 por ciento o más lleva a una suspensión de la licencia por 90 días, y también puede haber penas criminales.","p":"Correcto. Un resultado de 0.08 o más significa una suspensión de 90 días."},"zh":{"q":"在 Wyoming，一位 21 岁或以上的司机做了呼气或血液检测，结果是 0.08% 或以上。驾照会怎么样？","o":["在开庭前什么都不会发生","被暂停 90 天","被暂停 7 天","被暂停 5 年"],"h1":"暂停时间大约是三个月。","h2":"在 Wyoming，检测结果是 0.08% 或以上会导致驾照被暂停 90 天，还可能有刑事处罚。","p":"对。结果是 0.08 或以上就会被暂停 90 天。"},"vi":{"q":"Ở Wyoming, một tài xế từ 21 tuổi trở lên làm xét nghiệm hơi thở hoặc máu và kết quả là 0.08% trở lên. Điều gì xảy ra với bằng lái?","o":["Không có gì cho đến ngày ra tòa","Bị đình chỉ 90 ngày","Bị đình chỉ 7 ngày","Bị đình chỉ 5 năm"],"h1":"Thời gian đình chỉ khoảng ba tháng.","h2":"Ở Wyoming, kết quả xét nghiệm từ 0.08% trở lên sẽ làm bằng lái bị đình chỉ 90 ngày, và cũng có thể có hình phạt hình sự.","p":"Đúng. Kết quả từ 0.08 trở lên nghĩa là bị đình chỉ 90 ngày."},"tl":{"q":"Sa Wyoming, isang driver na 21 o mas matanda ang kumuha ng breath o blood test at ang resulta ay 0.08% o higit pa. Ano ang mangyayari sa lisensiya?","o":["Wala hanggang sa araw ng korte","Masususpinde ito nang 90 araw","Masususpinde ito nang 7 araw","Masususpinde ito nang 5 taon"],"h1":"Mga tatlong buwan ang suspensiyon.","h2":"Sa Wyoming, ang resulta ng test na 0.08% o higit pa ay nagdudulot ng 90 araw na suspensiyon ng lisensiya, at puwede ring may parusang kriminal.","p":"Tama. Ang resultang 0.08 o higit pa ay 90 araw na suspensiyon."},"ar":{"q":"في Wyoming، سائق عمره 21 سنة أو أكثر يُجري اختبار تنفس أو دم والنتيجة 0.08% أو أكثر. ماذا يحدث للرخصة؟","o":["لا شيء حتى موعد المحكمة","يتم إيقافها لمدة 90 يومًا","يتم إيقافها لمدة 7 أيام","يتم إيقافها لمدة 5 سنوات"],"h1":"مدة الإيقاف حوالي ثلاثة أشهر.","h2":"في Wyoming، نتيجة اختبار 0.08% أو أكثر تؤدي إلى إيقاف الرخصة لمدة 90 يومًا، وقد تكون هناك عقوبات جنائية أيضًا.","p":"صحيح. نتيجة 0.08 أو أكثر تعني إيقافًا لمدة 90 يومًا."},"ref":{"doc":"WY","page":37}},{"id":"wy-027","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, can a driver be convicted of driving under the influence with a blood alcohol level below 0.08 percent?","o":["No, never below 0.08 percent","Only if the driver is over 65","Only if there was a crash","Yes, from 0.05 percent with other evidence"],"h1":"A lower level can count when there are other signs of impairment.","h2":"In Wyoming a driver can be convicted of driving under the influence with a level of 0.05 percent when there is other evidence of impairment.","p":"Right. In Wyoming, 0.05 plus other evidence can lead to a conviction."},"es":{"q":"En Wyoming, ¿se puede condenar a un conductor por manejar bajo la influencia con un nivel de alcohol en la sangre menor de 0.08 por ciento?","o":["No, nunca por debajo de 0.08 por ciento","Solo si el conductor tiene más de 65 años","Solo si hubo un choque","Sí, desde 0.05 por ciento con otras pruebas"],"h1":"Un nivel más bajo puede contar cuando hay otras señales de que el conductor está afectado.","h2":"En Wyoming se puede condenar a un conductor por manejar bajo la influencia con un nivel de 0.05 por ciento cuando hay otras pruebas de que está afectado.","p":"Correcto. En Wyoming, 0.05 más otras pruebas puede llevar a una condena."},"zh":{"q":"在 Wyoming，如果血液酒精浓度低于 0.08%，司机会被判酒后驾驶吗？","o":["不会，低于 0.08% 永远不会","只有司机超过 65 岁时","只有发生了车祸时","会，从 0.05% 开始，并有其他证据时"],"h1":"有其他受影响的迹象时，较低的浓度也可能算数。","h2":"在 Wyoming，如果有其他证据显示司机受到影响，血液酒精浓度为 0.05% 的司机也可能被判酒后驾驶。","p":"对。在 Wyoming，0.05 加上其他证据就可能被定罪。"},"vi":{"q":"Ở Wyoming, tài xế có thể bị kết tội lái xe khi say nếu nồng độ cồn trong máu dưới 0.08% không?","o":["Không, không bao giờ khi dưới 0.08%","Chỉ khi tài xế trên 65 tuổi","Chỉ khi đã xảy ra tai nạn","Có, từ 0.05% khi có bằng chứng khác"],"h1":"Mức thấp hơn vẫn có thể bị tính khi có dấu hiệu khác cho thấy bị ảnh hưởng.","h2":"Ở Wyoming, tài xế có thể bị kết tội lái xe khi say với mức 0.05% khi có bằng chứng khác cho thấy bị ảnh hưởng.","p":"Đúng. Ở Wyoming, 0.05 cộng với bằng chứng khác có thể dẫn đến bị kết tội."},"tl":{"q":"Sa Wyoming, puwede bang mahatulan ang driver ng pagmamaneho nang lasing kung ang alcohol sa dugo niya ay mas mababa sa 0.08%?","o":["Hindi, hindi kailanman kapag mas mababa sa 0.08%","Kung lampas 65 lang ang driver","Kung may banggaan lang","Oo, mula 0.05% kapag may iba pang ebidensiya"],"h1":"Puwedeng bilangin ang mas mababang level kapag may iba pang palatandaan na apektado ang driver.","h2":"Sa Wyoming, puwedeng mahatulan ang driver ng pagmamaneho nang lasing sa level na 0.05% kapag may iba pang ebidensiya na apektado siya.","p":"Tama. Sa Wyoming, ang 0.05 kasama ang iba pang ebidensiya ay puwedeng humantong sa paghatol."},"ar":{"q":"في Wyoming، هل يمكن إدانة سائق بالقيادة تحت تأثير الكحول إذا كانت نسبة الكحول في دمه أقل من 0.08%؟","o":["لا، أبدًا تحت 0.08%","فقط إذا كان عمر السائق أكثر من 65 سنة","فقط إذا وقع حادث","نعم، من 0.05% مع أدلة أخرى"],"h1":"قد تُحسب النسبة الأقل عندما توجد علامات أخرى على التأثر.","h2":"في Wyoming يمكن إدانة السائق بالقيادة تحت تأثير الكحول بنسبة 0.05% عندما توجد أدلة أخرى على أنه متأثر.","p":"صحيح. في Wyoming، نسبة 0.05 مع أدلة أخرى قد تؤدي إلى الإدانة."},"ref":{"doc":"WY","page":37}},{"id":"wy-028","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what eyesight do you need in both eyes to meet the vision standard for driving?","o":["20/40","20/20","20/80","20/200"],"h1":"Glasses or contact lenses may be used to reach it.","h2":"In Wyoming, you need 20/40 vision with both eyes, with or without glasses, to meet the vision standard.","p":"Right. The standard is 20/40 with both eyes."},"es":{"q":"En Wyoming, ¿qué visión necesita en ambos ojos para cumplir con el requisito de visión para manejar?","o":["20/40","20/20","20/80","20/200"],"h1":"Puede usar lentes o lentes de contacto para lograrlo.","h2":"En Wyoming, usted necesita una visión de 20/40 con ambos ojos, con o sin lentes, para cumplir con el requisito de visión.","p":"Correcto. El requisito es 20/40 con ambos ojos."},"zh":{"q":"在 Wyoming，双眼视力需要达到多少才符合驾驶的视力标准？","o":["20/40","20/20","20/80","20/200"],"h1":"可以戴眼镜或隐形眼镜来达到这个标准。","h2":"在 Wyoming，你的双眼视力需要达到 20/40（戴不戴眼镜都可以），才符合视力标准。","p":"对。标准是双眼 20/40。"},"vi":{"q":"Ở Wyoming, bạn cần thị lực hai mắt bao nhiêu để đạt tiêu chuẩn thị lực khi lái xe?","o":["20/40","20/20","20/80","20/200"],"h1":"Bạn có thể dùng kính hoặc kính áp tròng để đạt mức này.","h2":"Ở Wyoming, bạn cần thị lực 20/40 với cả hai mắt, có hoặc không có kính, để đạt tiêu chuẩn thị lực.","p":"Đúng. Tiêu chuẩn là 20/40 với cả hai mắt."},"tl":{"q":"Sa Wyoming, anong linaw ng paningin sa dalawang mata ang kailangan mo para pumasa sa pamantayan sa paningin para makapagmaneho?","o":["20/40","20/20","20/80","20/200"],"h1":"Puwedeng gumamit ng salamin o contact lens para maabot ito.","h2":"Sa Wyoming, kailangan mo ng 20/40 na paningin sa dalawang mata, may salamin man o wala, para pumasa sa pamantayan sa paningin.","p":"Tama. Ang pamantayan ay 20/40 sa dalawang mata."},"ar":{"q":"في Wyoming، ما قوة النظر التي تحتاجها في العينين معًا لتستوفي معيار النظر للقيادة؟","o":["20/40","20/20","20/80","20/200"],"h1":"يمكن استخدام النظارات أو العدسات اللاصقة للوصول إليها.","h2":"في Wyoming تحتاج إلى نظر 20/40 في العينين معًا، بنظارات أو بدونها، لتستوفي معيار النظر.","p":"صحيح. المعيار هو 20/40 في العينين معًا."},"ref":{"doc":"WY","page":8}},{"id":"wy-029","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, after you move to a new address, how soon must you tell the driver license office in writing?","o":["Within 30 days","Within 10 days","Within 60 days","Within 1 year"],"h1":"It is less than two weeks.","h2":"In Wyoming, you must notify the department in writing within 10 days after you change your address.","p":"Right. Report a new address within 10 days."},"es":{"q":"En Wyoming, después de cambiar de domicilio, ¿en cuánto tiempo debe avisar por escrito a la oficina de licencias?","o":["En 30 días","En 10 días","En 60 días","En 1 año"],"h1":"Es menos de dos semanas.","h2":"En Wyoming, usted debe avisar por escrito al departamento en 10 días después de cambiar de domicilio.","p":"Correcto. Informe su nuevo domicilio en 10 días."},"zh":{"q":"在 Wyoming，搬到新地址后，你必须在多长时间内书面通知驾照办公室？","o":["30 天内","10 天内","60 天内","1 年内"],"h1":"不到两个星期。","h2":"在 Wyoming，你更改地址后，必须在 10 天内书面通知驾照部门。","p":"对。新地址要在 10 天内报告。"},"vi":{"q":"Ở Wyoming, sau khi chuyển đến địa chỉ mới, bạn phải báo cho văn phòng bằng lái bằng văn bản trong bao lâu?","o":["Trong vòng 30 ngày","Trong vòng 10 ngày","Trong vòng 60 ngày","Trong vòng 1 năm"],"h1":"Ít hơn hai tuần.","h2":"Ở Wyoming, bạn phải báo cho cơ quan bằng văn bản trong vòng 10 ngày sau khi đổi địa chỉ.","p":"Đúng. Hãy báo địa chỉ mới trong vòng 10 ngày."},"tl":{"q":"Sa Wyoming, pagkatapos mong lumipat sa bagong address, gaano kabilis mo dapat sabihan nang nakasulat ang opisina ng driver license?","o":["Sa loob ng 30 araw","Sa loob ng 10 araw","Sa loob ng 60 araw","Sa loob ng 1 taon"],"h1":"Mas maikli ito sa dalawang linggo.","h2":"Sa Wyoming, dapat mong sabihan nang nakasulat ang departamento sa loob ng 10 araw pagkatapos mong magpalit ng address.","p":"Tama. Iulat ang bagong address sa loob ng 10 araw."},"ar":{"q":"في Wyoming، بعد انتقالك إلى عنوان جديد، خلال كم من الوقت يجب أن تُبلغ مكتب رخص القيادة كتابيًا؟","o":["خلال 30 يومًا","خلال 10 أيام","خلال 60 يومًا","خلال سنة واحدة"],"h1":"المدة أقل من أسبوعين.","h2":"في Wyoming يجب أن تُبلغ الإدارة كتابيًا خلال 10 أيام بعد تغيير عنوانك.","p":"صحيح. أبلغ عن العنوان الجديد خلال 10 أيام."},"ref":{"doc":"WY","page":8}},{"id":"wy-030","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how many times may you take the written test in one day?","o":["Once","Three times","Twice","Five times"],"h1":"You get one more try the same day if the first one does not go well.","h2":"In Wyoming, a driver license applicant may take the written test twice in one day.","p":"Right. You may take the written test twice in one day."},"es":{"q":"En Wyoming, ¿cuántas veces puede tomar el examen escrito en un mismo día?","o":["Una vez","Tres veces","Dos veces","Cinco veces"],"h1":"Tiene un intento más el mismo día si el primero no sale bien.","h2":"En Wyoming, una persona que solicita la licencia puede tomar el examen escrito dos veces en un mismo día.","p":"Correcto. Puede tomar el examen escrito dos veces en un día."},"zh":{"q":"在 Wyoming，你一天可以参加几次笔试？","o":["一次","三次","两次","五次"],"h1":"如果第一次没考好，同一天你还有一次机会。","h2":"在 Wyoming，申请驾照的人一天可以参加两次笔试。","p":"对。你一天可以参加两次笔试。"},"vi":{"q":"Ở Wyoming, bạn được thi viết bao nhiêu lần trong một ngày?","o":["Một lần","Ba lần","Hai lần","Năm lần"],"h1":"Bạn được thử thêm một lần trong cùng ngày nếu lần đầu không tốt.","h2":"Ở Wyoming, người xin bằng lái được thi viết hai lần trong một ngày.","p":"Đúng. Bạn được thi viết hai lần trong một ngày."},"tl":{"q":"Sa Wyoming, ilang beses ka puwedeng kumuha ng written test sa isang araw?","o":["Isang beses","Tatlong beses","Dalawang beses","Limang beses"],"h1":"May isa ka pang pagkakataon sa parehong araw kung hindi maganda ang una.","h2":"Sa Wyoming, puwedeng kumuha ng written test nang dalawang beses sa isang araw ang nag-a-apply ng driver license.","p":"Tama. Puwede kang kumuha ng written test nang dalawang beses sa isang araw."},"ar":{"q":"في Wyoming، كم مرة يمكنك أن تأخذ الاختبار الكتابي في يوم واحد؟","o":["مرة واحدة","ثلاث مرات","مرتين","خمس مرات"],"h1":"لديك محاولة أخرى في اليوم نفسه إذا لم تنجح المحاولة الأولى.","h2":"في Wyoming يمكن لمن يتقدم لرخصة القيادة أن يأخذ الاختبار الكتابي مرتين في يوم واحد.","p":"صحيح. يمكنك أن تأخذ الاختبار الكتابي مرتين في يوم واحد."},"ref":{"doc":"WY","page":9}},{"id":"wy-031","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, you are coming up behind another vehicle at night. Within how many feet must you dim your headlights?","o":["100 feet","200 feet","500 feet","300 feet"],"h1":"It is less than the distance for an oncoming vehicle.","h2":"In Wyoming, you must dim your headlights when you are within 300 feet of the rear of a vehicle you are approaching.","p":"Right. Dim your lights within 300 feet of a vehicle ahead."},"es":{"q":"En Wyoming, usted se acerca de noche por detrás a otro vehículo. ¿A cuántos pies debe bajar las luces?","o":["100 pies","200 pies","500 pies","300 pies"],"h1":"Es menos que la distancia para un vehículo que viene de frente.","h2":"En Wyoming, usted debe bajar las luces cuando está a 300 pies o menos de la parte de atrás de un vehículo al que se acerca.","p":"Correcto. Baje las luces a 300 pies de un vehículo que va adelante."},"zh":{"q":"在 Wyoming，晚上你正在从后面接近另一辆车。你必须在多少英尺以内把大灯调暗？","o":["100 英尺","200 英尺","500 英尺","300 英尺"],"h1":"这个距离比对面来车时的距离短。","h2":"在 Wyoming，当你接近前面一辆车，距离它的车尾 300 英尺以内时，必须把大灯调暗。","p":"对。在前车 300 英尺以内要调暗车灯。"},"vi":{"q":"Ở Wyoming, bạn đang chạy đến gần phía sau một xe khác vào ban đêm. Bạn phải giảm đèn pha khi cách bao nhiêu feet?","o":["100 feet","200 feet","500 feet","300 feet"],"h1":"Khoảng cách này ngắn hơn khoảng cách với xe chạy ngược chiều.","h2":"Ở Wyoming, bạn phải giảm đèn pha khi bạn cách đuôi xe phía trước 300 feet hoặc gần hơn.","p":"Đúng. Hãy giảm đèn khi cách xe phía trước 300 feet."},"tl":{"q":"Sa Wyoming, papalapit ka sa likod ng ibang sasakyan sa gabi. Sa loob ng ilang talampakan mo dapat i-dim ang headlights mo?","o":["100 talampakan","200 talampakan","500 talampakan","300 talampakan"],"h1":"Mas maikli ito kaysa sa distansiya para sa paparating na sasakyan.","h2":"Sa Wyoming, dapat mong i-dim ang headlights mo kapag nasa loob ka ng 300 talampakan mula sa likod ng sasakyang nilalapitan mo.","p":"Tama. I-dim ang ilaw mo sa loob ng 300 talampakan mula sa sasakyan sa unahan."},"ar":{"q":"في Wyoming، أنت تقترب ليلًا من خلف سيارة أخرى. ضمن كم قدمًا يجب أن تخفض أضواءك الأمامية؟","o":["100 قدم","200 قدم","500 قدم","300 قدم"],"h1":"المسافة أقل من المسافة الخاصة بالسيارة القادمة من الاتجاه المقابل.","h2":"في Wyoming يجب أن تخفض أضواءك الأمامية عندما تكون على بعد 300 قدم أو أقل من مؤخرة السيارة التي تقترب منها.","p":"صحيح. اخفض أضواءك عندما تكون على بعد 300 قدم من السيارة التي أمامك."},"ref":{"doc":"WY","page":78}},{"id":"wy-032","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a 14-year-old gets a restricted license because of a family hardship. During which hours is it valid?","o":["6 a.m. to 6 p.m.","5 a.m. to 8 p.m.","5 a.m. to 11 p.m.","At any hour"],"h1":"It ends earlier in the evening than the intermediate permit's limit.","h2":"In Wyoming, a restricted hardship license for ages 14 and 15 is valid only from 5 a.m. to 8 p.m.","p":"Right. The restricted license is valid from 5 a.m. to 8 p.m."},"es":{"q":"En Wyoming, un joven de 14 años obtiene una licencia restringida por una dificultad familiar. ¿En qué horario es válida?","o":["De 6 a.m. a 6 p.m.","De 5 a.m. a 8 p.m.","De 5 a.m. a 11 p.m.","A cualquier hora"],"h1":"Termina más temprano en la noche que el límite del permiso intermedio.","h2":"En Wyoming, la licencia restringida por dificultad para jóvenes de 14 y 15 años solo es válida de 5 a.m. a 8 p.m.","p":"Correcto. La licencia restringida es válida de 5 a.m. a 8 p.m."},"zh":{"q":"在 Wyoming，一个 14 岁的孩子因为家庭困难拿到了限制驾照。这个驾照在什么时间内有效？","o":["早上 6 点到晚上 6 点","早上 5 点到晚上 8 点","早上 5 点到晚上 11 点","任何时间"],"h1":"它在晚上结束的时间比中级驾照的限制早。","h2":"在 Wyoming，14 岁和 15 岁的困难限制驾照只在早上 5 点到晚上 8 点之间有效。","p":"对。限制驾照在早上 5 点到晚上 8 点之间有效。"},"vi":{"q":"Ở Wyoming, một em 14 tuổi được cấp bằng lái hạn chế vì gia đình có hoàn cảnh khó khăn. Bằng này có hiệu lực trong những giờ nào?","o":["6 giờ sáng đến 6 giờ chiều","5 giờ sáng đến 8 giờ tối","5 giờ sáng đến 11 giờ tối","Bất cứ giờ nào"],"h1":"Nó kết thúc vào buổi tối sớm hơn giới hạn của giấy phép trung cấp.","h2":"Ở Wyoming, bằng lái hạn chế vì hoàn cảnh khó khăn cho tuổi 14 và 15 chỉ có hiệu lực từ 5 giờ sáng đến 8 giờ tối.","p":"Đúng. Bằng lái hạn chế có hiệu lực từ 5 giờ sáng đến 8 giờ tối."},"tl":{"q":"Sa Wyoming, isang 14 taong gulang ang nakakuha ng restricted license dahil sa hirap ng pamilya. Sa anong mga oras ito puwedeng gamitin?","o":["6 a.m. hanggang 6 p.m.","5 a.m. hanggang 8 p.m.","5 a.m. hanggang 11 p.m.","Kahit anong oras"],"h1":"Mas maaga itong natatapos sa gabi kaysa sa limitasyon ng intermediate permit.","h2":"Sa Wyoming, ang restricted hardship license para sa edad 14 at 15 ay puwedeng gamitin mula 5 a.m. hanggang 8 p.m. lang.","p":"Tama. Puwedeng gamitin ang restricted license mula 5 a.m. hanggang 8 p.m."},"ar":{"q":"في Wyoming، حصل شخص عمره 14 سنة على رخصة مقيّدة بسبب ظروف عائلية صعبة. في أي ساعات تكون صالحة؟","o":["من 6 صباحًا إلى 6 مساءً","من 5 صباحًا إلى 8 مساءً","من 5 صباحًا إلى 11 مساءً","في أي ساعة"],"h1":"تنتهي في المساء قبل الحدّ الخاص بالتصريح المتوسط.","h2":"في Wyoming تكون الرخصة المقيّدة بسبب الظروف الصعبة لعمر 14 و15 سنة صالحة فقط من 5 صباحًا إلى 8 مساءً.","p":"صحيح. الرخصة المقيّدة صالحة من 5 صباحًا إلى 8 مساءً."},"ref":{"doc":"WY","page":13}},{"id":"wy-033","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how far from home may a driver with a restricted hardship license (ages 14 to 15) drive?","o":["Up to 10 miles","Up to 25 miles","Up to 50 miles","Anywhere in the state"],"h1":"It is a round number, more than 25.","h2":"In Wyoming, a restricted hardship license is valid only within 50 miles of the driver's home.","p":"Right. The limit is 50 miles from home."},"es":{"q":"En Wyoming, ¿qué tan lejos de su casa puede manejar un conductor con licencia restringida por dificultad (14 a 15 años)?","o":["Hasta 10 millas","Hasta 25 millas","Hasta 50 millas","A cualquier lugar del estado"],"h1":"Es un número redondo, mayor que 25.","h2":"En Wyoming, la licencia restringida por dificultad solo es válida dentro de 50 millas de la casa del conductor.","p":"Correcto. El límite es 50 millas desde la casa."},"zh":{"q":"在 Wyoming，持有困难限制驾照（14 到 15 岁）的司机可以开到离家多远？","o":["最多 10 英里","最多 25 英里","最多 50 英里","州内任何地方"],"h1":"这是一个整数，比 25 大。","h2":"在 Wyoming，困难限制驾照只在离司机家 50 英里以内有效。","p":"对。限制是离家 50 英里。"},"vi":{"q":"Ở Wyoming, người có bằng lái hạn chế vì hoàn cảnh khó khăn (14 đến 15 tuổi) được lái xa nhà bao nhiêu?","o":["Tối đa 10 dặm","Tối đa 25 dặm","Tối đa 50 dặm","Bất cứ đâu trong tiểu bang"],"h1":"Đó là một số tròn, lớn hơn 25.","h2":"Ở Wyoming, bằng lái hạn chế vì hoàn cảnh khó khăn chỉ có hiệu lực trong vòng 50 dặm từ nhà của người lái.","p":"Đúng. Giới hạn là 50 dặm từ nhà."},"tl":{"q":"Sa Wyoming, gaano kalayo mula sa bahay puwedeng magmaneho ang may restricted hardship license (edad 14 hanggang 15)?","o":["Hanggang 10 milya","Hanggang 25 milya","Hanggang 50 milya","Kahit saan sa estado"],"h1":"Ito ay isang buong numero na higit sa 25.","h2":"Sa Wyoming, ang restricted hardship license ay puwede lang gamitin sa loob ng 50 milya mula sa bahay ng driver.","p":"Tama. Ang limitasyon ay 50 milya mula sa bahay."},"ar":{"q":"في Wyoming، إلى أي مسافة من البيت يمكن لسائق يحمل رخصة مقيّدة بسبب الظروف الصعبة (من 14 إلى 15 سنة) أن يقود؟","o":["حتى 10 أميال","حتى 25 ميلًا","حتى 50 ميلًا","إلى أي مكان في الولاية"],"h1":"هو رقم مستدير، أكثر من 25.","h2":"في Wyoming تكون الرخصة المقيّدة بسبب الظروف الصعبة صالحة فقط ضمن 50 ميلًا من بيت السائق.","p":"صحيح. الحدّ هو 50 ميلًا من البيت."},"ref":{"doc":"WY","page":13}},{"id":"wy-034","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, when does an intermediate license end on its own?","o":["On the 17th birthday","One year after it was issued","On the 18th birthday","30 days after the 17th birthday"],"h1":"It lasts a short time past a birthday.","h2":"In Wyoming, an intermediate license expires 30 days after the holder's 17th birthday.","p":"Right. It expires 30 days after you turn 17."},"es":{"q":"En Wyoming, ¿cuándo vence por sí sola una licencia intermedia?","o":["El día que cumple 17 años","Un año después de emitirla","El día que cumple 18 años","30 días después de cumplir 17 años"],"h1":"Dura poco tiempo después de un cumpleaños.","h2":"En Wyoming, la licencia intermedia vence 30 días después de que el titular cumple 17 años.","p":"Correcto. Vence 30 días después de cumplir 17."},"zh":{"q":"在 Wyoming，中级驾照什么时候会自动失效？","o":["满 17 岁生日那天","发证一年后","满 18 岁生日那天","满 17 岁生日后 30 天"],"h1":"它在某个生日之后还会持续一小段时间。","h2":"在 Wyoming，中级驾照在持有人满 17 岁生日后 30 天失效。","p":"对。它在你满 17 岁后 30 天失效。"},"vi":{"q":"Ở Wyoming, khi nào bằng lái trung cấp tự hết hạn?","o":["Vào sinh nhật 17 tuổi","Một năm sau khi được cấp","Vào sinh nhật 18 tuổi","30 ngày sau sinh nhật 17 tuổi"],"h1":"Nó kéo dài thêm một thời gian ngắn sau một ngày sinh nhật.","h2":"Ở Wyoming, bằng lái trung cấp hết hạn 30 ngày sau sinh nhật 17 tuổi của người giữ bằng.","p":"Đúng. Nó hết hạn 30 ngày sau khi bạn 17 tuổi."},"tl":{"q":"Sa Wyoming, kailan kusang natatapos ang intermediate license?","o":["Sa ika-17 kaarawan","Isang taon matapos itong ibigay","Sa ika-18 kaarawan","30 araw matapos ang ika-17 kaarawan"],"h1":"Tumatagal ito nang kaunting panahon pagkatapos ng isang kaarawan.","h2":"Sa Wyoming, nag-e-expire ang intermediate license 30 araw matapos ang ika-17 kaarawan ng may-hawak nito.","p":"Tama. Nag-e-expire ito 30 araw matapos kang mag-17."},"ar":{"q":"في Wyoming، متى تنتهي الرخصة المتوسطة من تلقاء نفسها؟","o":["في عيد الميلاد السابع عشر","بعد سنة من إصدارها","في عيد الميلاد الثامن عشر","بعد 30 يومًا من عيد الميلاد السابع عشر"],"h1":"تستمر وقتًا قصيرًا بعد عيد ميلاد معيّن.","h2":"في Wyoming تنتهي الرخصة المتوسطة بعد 30 يومًا من عيد الميلاد السابع عشر لحاملها.","p":"صحيح. تنتهي بعد 30 يومًا من بلوغك 17 سنة."},"ref":{"doc":"WY","page":15}},{"id":"wy-035","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, who must ride with you when you drive with an instruction permit?","o":["A licensed driver age 18 or older, in the front passenger seat","Any passenger age 16 or older, in any seat","A licensed driver age 25 or older, in the back seat","No one, if you drive in daylight"],"h1":"This person must be an adult with a license and must sit where they can help you.","h2":"In Wyoming, a driver with an instruction permit must have a licensed driver age 18 or older in the front passenger seat.","p":"Right. A licensed driver 18 or older sits in the front passenger seat."},"es":{"q":"En Wyoming, ¿quién debe ir con usted cuando maneja con un permiso de instrucción?","o":["Un conductor con licencia de 18 años o más, en el asiento del pasajero delantero","Cualquier pasajero de 16 años o más, en cualquier asiento","Un conductor con licencia de 25 años o más, en el asiento trasero","Nadie, si maneja de día"],"h1":"Esta persona debe ser adulta, con licencia, y sentarse donde pueda ayudarle.","h2":"En Wyoming, un conductor con permiso de instrucción debe ir con un conductor con licencia de 18 años o más en el asiento del pasajero delantero.","p":"Correcto. Un conductor con licencia de 18 años o más va en el asiento delantero."},"zh":{"q":"在 Wyoming，你持学习驾照（instruction permit）开车时，谁必须和你同车？","o":["一名 18 岁或以上、有驾照的司机，坐在前排乘客座位","任何 16 岁或以上的乘客，坐在任何座位","一名 25 岁或以上、有驾照的司机，坐在后座","如果白天开车，不需要任何人"],"h1":"这个人必须是有驾照的成年人，而且要坐在能帮助你的位置。","h2":"在 Wyoming，持学习驾照开车的人必须有一名 18 岁或以上、有驾照的司机坐在前排乘客座位。","p":"对。一名 18 岁或以上、有驾照的司机坐在前排乘客座位。"},"vi":{"q":"Ở Wyoming, khi bạn lái xe với giấy phép tập lái (instruction permit), ai phải đi cùng bạn?","o":["Một người có bằng lái từ 18 tuổi trở lên, ngồi ở ghế hành khách phía trước","Bất kỳ hành khách nào từ 16 tuổi trở lên, ngồi ở bất kỳ ghế nào","Một người có bằng lái từ 25 tuổi trở lên, ngồi ở ghế sau","Không ai cả, nếu bạn lái ban ngày"],"h1":"Người này phải là người lớn có bằng lái và phải ngồi ở chỗ có thể giúp bạn.","h2":"Ở Wyoming, người lái xe với giấy phép tập lái phải có một người có bằng lái từ 18 tuổi trở lên ngồi ở ghế hành khách phía trước.","p":"Đúng. Một người có bằng lái từ 18 tuổi trở lên ngồi ở ghế hành khách phía trước."},"tl":{"q":"Sa Wyoming, sino ang dapat kasama mo kapag nagmamaneho ka na may instruction permit?","o":["Isang lisensiyadong driver na 18 taong gulang o higit pa, sa upuan ng pasahero sa harap","Kahit sinong pasahero na 16 o higit pa, sa kahit anong upuan","Isang lisensiyadong driver na 25 o higit pa, sa likod na upuan","Wala, kung sa araw ka nagmamaneho"],"h1":"Dapat adult ang taong ito na may lisensiya at nakaupo kung saan ka niya matutulungan.","h2":"Sa Wyoming, ang nagmamaneho na may instruction permit ay dapat may kasamang lisensiyadong driver na 18 taong gulang o higit pa sa upuan ng pasahero sa harap.","p":"Tama. Isang lisensiyadong driver na 18 o higit pa ang nakaupo sa upuan ng pasahero sa harap."},"ar":{"q":"في Wyoming، من يجب أن يركب معك عندما تقود بتصريح التدريب (instruction permit)؟","o":["سائق مرخّص عمره 18 سنة أو أكثر، في مقعد الراكب الأمامي","أي راكب عمره 16 سنة أو أكثر، في أي مقعد","سائق مرخّص عمره 25 سنة أو أكثر، في المقعد الخلفي","لا أحد، إذا كنت تقود في النهار"],"h1":"يجب أن يكون هذا الشخص بالغًا ومعه رخصة، وأن يجلس في مكان يستطيع منه مساعدتك.","h2":"في Wyoming يجب أن يكون مع السائق الذي يحمل تصريح التدريب سائق مرخّص عمره 18 سنة أو أكثر في مقعد الراكب الأمامي.","p":"صحيح. سائق مرخّص عمره 18 سنة أو أكثر يجلس في مقعد الراكب الأمامي."},"ref":{"doc":"WY","page":10}},{"id":"wy-036","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, which moving violation within 12 months leads to a license suspension?","o":["The second one","The third one","The fourth one","The sixth one"],"h1":"You are allowed up to three in 12 months.","h2":"In Wyoming, a fourth moving violation within 12 months leads to a 90-day license suspension.","p":"Right. The fourth moving violation in 12 months brings a suspension."},"es":{"q":"En Wyoming, ¿cuál infracción de tránsito en movimiento dentro de 12 meses lleva a la suspensión de la licencia?","o":["La segunda","La tercera","La cuarta","La sexta"],"h1":"Se permiten hasta tres en 12 meses.","h2":"En Wyoming, una cuarta infracción en movimiento dentro de 12 meses lleva a una suspensión de 90 días.","p":"Correcto. La cuarta infracción en 12 meses trae una suspensión."},"zh":{"q":"在 Wyoming，12 个月内第几次行车违规会导致驾照被暂停？","o":["第二次","第三次","第四次","第六次"],"h1":"12 个月内最多可以有三次。","h2":"在 Wyoming，12 个月内第四次行车违规会导致驾照被暂停 90 天。","p":"对。12 个月内第四次行车违规会导致暂停驾照。"},"vi":{"q":"Ở Wyoming, lỗi vi phạm khi lái xe thứ mấy trong vòng 12 tháng sẽ dẫn đến bị đình chỉ bằng lái?","o":["Lần thứ hai","Lần thứ ba","Lần thứ tư","Lần thứ sáu"],"h1":"Bạn được phép có tối đa ba lần trong 12 tháng.","h2":"Ở Wyoming, lỗi vi phạm khi lái xe lần thứ tư trong vòng 12 tháng sẽ dẫn đến bị đình chỉ bằng lái 90 ngày.","p":"Đúng. Lỗi vi phạm khi lái xe lần thứ tư trong 12 tháng sẽ bị đình chỉ bằng lái."},"tl":{"q":"Sa Wyoming, pang-ilang moving violation sa loob ng 12 buwan ang magdudulot ng suspensiyon ng lisensiya?","o":["Ang pangalawa","Ang pangatlo","Ang pang-apat","Ang pang-anim"],"h1":"Puwede kang magkaroon ng hanggang tatlo sa loob ng 12 buwan.","h2":"Sa Wyoming, ang pang-apat na moving violation sa loob ng 12 buwan ay nagdudulot ng 90 araw na suspensiyon ng lisensiya.","p":"Tama. Ang pang-apat na moving violation sa loob ng 12 buwan ay nagdudulot ng suspensiyon."},"ar":{"q":"في Wyoming، أي مخالفة قيادة خلال 12 شهرًا تؤدي إلى إيقاف الرخصة؟","o":["الثانية","الثالثة","الرابعة","السادسة"],"h1":"يُسمح لك بثلاث مخالفات كحدّ أقصى خلال 12 شهرًا.","h2":"في Wyoming، مخالفة القيادة الرابعة خلال 12 شهرًا تؤدي إلى إيقاف الرخصة لمدة 90 يومًا.","p":"صحيح. مخالفة القيادة الرابعة خلال 12 شهرًا تؤدي إلى إيقاف الرخصة."},"ref":{"doc":"WY","page":24}},{"id":"wy-037","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, you fail the driving skills test. How long must you wait before you try again?","o":["You may try again right away","24 hours","One week","30 days"],"h1":"It is one full day.","h2":"In Wyoming, if you fail the driving skills test, you must wait 24 hours before you test again.","p":"Right. You wait 24 hours before the next skills test."},"es":{"q":"En Wyoming, usted no aprueba el examen práctico de manejo. ¿Cuánto debe esperar para intentarlo de nuevo?","o":["Puede intentarlo de inmediato","24 horas","Una semana","30 días"],"h1":"Es un día completo.","h2":"En Wyoming, si no aprueba el examen práctico de manejo, debe esperar 24 horas para volver a tomarlo.","p":"Correcto. Debe esperar 24 horas para el siguiente examen práctico."},"zh":{"q":"在 Wyoming，你的路考没有通过。你必须等多久才能再考？","o":["可以马上再考","24 小时","一个星期","30 天"],"h1":"是整整一天。","h2":"在 Wyoming，如果路考没有通过，你必须等 24 小时才能再考。","p":"对。你要等 24 小时才能再参加路考。"},"vi":{"q":"Ở Wyoming, bạn trượt bài thi lái xe thực hành. Bạn phải đợi bao lâu trước khi thi lại?","o":["Bạn có thể thi lại ngay","24 giờ","Một tuần","30 ngày"],"h1":"Đó là trọn một ngày.","h2":"Ở Wyoming, nếu bạn trượt bài thi lái xe thực hành, bạn phải đợi 24 giờ trước khi thi lại.","p":"Đúng. Bạn đợi 24 giờ trước lần thi thực hành tiếp theo."},"tl":{"q":"Sa Wyoming, bumagsak ka sa driving skills test. Gaano katagal ka dapat maghintay bago sumubok ulit?","o":["Puwede kang sumubok ulit agad","24 oras","Isang linggo","30 araw"],"h1":"Isang buong araw ito.","h2":"Sa Wyoming, kapag bumagsak ka sa driving skills test, dapat kang maghintay ng 24 oras bago mag-test ulit.","p":"Tama. Maghihintay ka ng 24 oras bago ang susunod na skills test."},"ar":{"q":"في Wyoming، رسبت في اختبار مهارات القيادة. كم يجب أن تنتظر قبل أن تحاول مرة أخرى؟","o":["يمكنك أن تحاول مرة أخرى فورًا","24 ساعة","أسبوعًا واحدًا","30 يومًا"],"h1":"هو يوم كامل.","h2":"في Wyoming، إذا رسبت في اختبار مهارات القيادة يجب أن تنتظر 24 ساعة قبل أن تختبر مرة أخرى.","p":"صحيح. تنتظر 24 ساعة قبل اختبار المهارات التالي."},"ref":{"doc":"WY","page":9}},{"id":"wy-038","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, after a violation, you must file an SR-22 proof of insurance. How long must you keep it?","o":["30 days","Six months","One year","Three years"],"h1":"It is longer than one year.","h2":"In Wyoming, proof of financial responsibility (an SR-22) must be kept for three years from the date it is required.","p":"Right. You keep the SR-22 for three years."},"es":{"q":"En Wyoming, después de una infracción, usted debe presentar un comprobante de seguro SR-22. ¿Por cuánto tiempo debe mantenerlo?","o":["30 días","Seis meses","Un año","Tres años"],"h1":"Es más de un año.","h2":"En Wyoming, el comprobante de responsabilidad financiera (SR-22) se debe mantener por tres años desde la fecha en que se exige.","p":"Correcto. Se mantiene el SR-22 por tres años."},"zh":{"q":"在 Wyoming，因为违规，你必须提交 SR-22 保险证明。你必须保留它多久？","o":["30 天","六个月","一年","三年"],"h1":"比一年长。","h2":"在 Wyoming，财务责任证明（SR-22）必须从被要求之日起保留三年。","p":"对。你要保留 SR-22 三年。"},"vi":{"q":"Ở Wyoming, sau một lỗi vi phạm, bạn phải nộp giấy chứng nhận bảo hiểm SR-22. Bạn phải giữ nó trong bao lâu?","o":["30 ngày","Sáu tháng","Một năm","Ba năm"],"h1":"Nó dài hơn một năm.","h2":"Ở Wyoming, giấy chứng nhận trách nhiệm tài chính (SR-22) phải được giữ trong ba năm kể từ ngày bị yêu cầu.","p":"Đúng. Bạn giữ SR-22 trong ba năm."},"tl":{"q":"Sa Wyoming, matapos ang isang paglabag, kailangan mong mag-file ng SR-22 na patunay ng insurance. Gaano katagal mo ito dapat panatilihin?","o":["30 araw","Anim na buwan","Isang taon","Tatlong taon"],"h1":"Mas mahaba ito sa isang taon.","h2":"Sa Wyoming, ang patunay ng financial responsibility (SR-22) ay dapat panatilihin nang tatlong taon mula sa petsang ito ay hiningi.","p":"Tama. Pananatilihin mo ang SR-22 nang tatlong taon."},"ar":{"q":"في Wyoming، بعد مخالفة، يجب أن تقدّم إثبات تأمين SR-22. كم مدة يجب أن تحتفظ به؟","o":["30 يومًا","ستة أشهر","سنة واحدة","ثلاث سنوات"],"h1":"المدة أطول من سنة واحدة.","h2":"في Wyoming يجب الاحتفاظ بإثبات المسؤولية المالية (SR-22) لمدة ثلاث سنوات من تاريخ طلبه.","p":"صحيح. تحتفظ بـ SR-22 لمدة ثلاث سنوات."},"ref":{"doc":"WY","page":28}},{"id":"wy-039","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a driver is convicted of a first DWUI. The blood alcohol level at arrest was .15 percent or more. How long must the driver hold an ignition interlock license?","o":["30 days","6 months","2 years","For life"],"h1":"It is half a year.","h2":"In Wyoming, a first DWUI with a blood alcohol level of .15 percent or more means holding an ignition interlock license for 6 months.","p":"Right. Six months with an ignition interlock license."},"es":{"q":"En Wyoming, un conductor es condenado por un primer DWUI. Su nivel de alcohol en la sangre al ser arrestado era de .15 por ciento o más. ¿Por cuánto tiempo debe tener una licencia con dispositivo de bloqueo de encendido (ignition interlock)?","o":["30 días","6 meses","2 años","De por vida"],"h1":"Es medio año.","h2":"En Wyoming, un primer DWUI con un nivel de alcohol de .15 por ciento o más exige tener una licencia con bloqueo de encendido por 6 meses.","p":"Correcto. Seis meses con licencia de bloqueo de encendido."},"zh":{"q":"在 Wyoming，一名司机第一次被判 DWUI（受影响下驾驶）。被捕时血液酒精浓度是 .15% 或更高。这名司机必须持有点火联锁驾照（ignition interlock license）多久？","o":["30 天","6 个月","2 年","终身"],"h1":"是半年。","h2":"在 Wyoming，第一次 DWUI 而且血液酒精浓度是 .15% 或更高，就必须持有点火联锁驾照 6 个月。","p":"对。要持有点火联锁驾照六个月。"},"vi":{"q":"Ở Wyoming, một người lái xe bị kết án DWUI (lái xe khi bị ảnh hưởng) lần đầu. Nồng độ cồn trong máu lúc bị bắt là .15 phần trăm trở lên. Người này phải giữ bằng lái có khóa khởi động đo cồn (ignition interlock license) trong bao lâu?","o":["30 ngày","6 tháng","2 năm","Suốt đời"],"h1":"Đó là nửa năm.","h2":"Ở Wyoming, DWUI lần đầu với nồng độ cồn trong máu từ .15 phần trăm trở lên nghĩa là phải giữ bằng lái có khóa khởi động đo cồn trong 6 tháng.","p":"Đúng. Sáu tháng với bằng lái có khóa khởi động đo cồn."},"tl":{"q":"Sa Wyoming, nahatulan ang isang driver sa unang DWUI (pagmamaneho habang nasa impluwensiya). Ang blood alcohol level niya nang arestuhin ay .15 percent o higit pa. Gaano katagal dapat niyang hawakan ang ignition interlock license?","o":["30 araw","6 na buwan","2 taon","Habambuhay"],"h1":"Kalahating taon ito.","h2":"Sa Wyoming, ang unang DWUI na may blood alcohol level na .15 percent o higit pa ay nangangahulugang hahawak ng ignition interlock license nang 6 na buwan.","p":"Tama. Anim na buwan na may ignition interlock license."},"ar":{"q":"في Wyoming، أُدين سائق بأول مخالفة DWUI (القيادة تحت التأثير). كانت نسبة الكحول في الدم عند القبض عليه .15 في المئة أو أكثر. كم مدة يجب أن يحمل رخصة جهاز قفل الإشعال (ignition interlock license)؟","o":["30 يومًا","6 أشهر","سنتين","مدى الحياة"],"h1":"هي نصف سنة.","h2":"في Wyoming، أول مخالفة DWUI مع نسبة كحول في الدم .15 في المئة أو أكثر تعني حمل رخصة جهاز قفل الإشعال لمدة 6 أشهر.","p":"صحيح. ستة أشهر مع رخصة جهاز قفل الإشعال."},"ref":{"doc":"WY","page":20}},{"id":"wy-040","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, a driver is convicted of a second DWUI within 10 years. How long is the license suspended?","o":["90 days","Six months","One year","Five years"],"h1":"It is longer than the 90 days for a first offense.","h2":"In Wyoming, a second DWUI within 10 years brings a one-year license suspension.","p":"Right. A second DWUI means a one-year suspension."},"es":{"q":"En Wyoming, un conductor es condenado por un segundo DWUI dentro de 10 años. ¿Por cuánto tiempo se suspende la licencia?","o":["90 días","Seis meses","Un año","Cinco años"],"h1":"Es más que los 90 días de la primera vez.","h2":"En Wyoming, un segundo DWUI dentro de 10 años trae una suspensión de la licencia por un año.","p":"Correcto. Un segundo DWUI significa un año de suspensión."},"zh":{"q":"在 Wyoming，一名司机在 10 年内第二次被判 DWUI。驾照会被暂停多久？","o":["90 天","六个月","一年","五年"],"h1":"比第一次违规的 90 天长。","h2":"在 Wyoming，10 年内第二次 DWUI 会导致驾照被暂停一年。","p":"对。第二次 DWUI 意味着暂停驾照一年。"},"vi":{"q":"Ở Wyoming, một người lái xe bị kết án DWUI lần thứ hai trong vòng 10 năm. Bằng lái bị đình chỉ bao lâu?","o":["90 ngày","Sáu tháng","Một năm","Năm năm"],"h1":"Nó dài hơn 90 ngày của lần vi phạm đầu tiên.","h2":"Ở Wyoming, DWUI lần thứ hai trong vòng 10 năm sẽ bị đình chỉ bằng lái một năm.","p":"Đúng. DWUI lần thứ hai nghĩa là bị đình chỉ một năm."},"tl":{"q":"Sa Wyoming, nahatulan ang isang driver sa pangalawang DWUI sa loob ng 10 taon. Gaano katagal masususpinde ang lisensiya?","o":["90 araw","Anim na buwan","Isang taon","Limang taon"],"h1":"Mas mahaba ito sa 90 araw ng unang paglabag.","h2":"Sa Wyoming, ang pangalawang DWUI sa loob ng 10 taon ay nagdudulot ng isang taong suspensiyon ng lisensiya.","p":"Tama. Ang pangalawang DWUI ay nangangahulugang isang taong suspensiyon."},"ar":{"q":"في Wyoming، أُدين سائق بمخالفة DWUI ثانية خلال 10 سنوات. كم مدة إيقاف الرخصة؟","o":["90 يومًا","ستة أشهر","سنة واحدة","خمس سنوات"],"h1":"المدة أطول من 90 يومًا للمخالفة الأولى.","h2":"في Wyoming، مخالفة DWUI الثانية خلال 10 سنوات تؤدي إلى إيقاف الرخصة لمدة سنة واحدة.","p":"صحيح. مخالفة DWUI الثانية تعني إيقافًا لمدة سنة واحدة."},"ref":{"doc":"WY","page":20}},{"id":"wy-041","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, a driver is convicted of a third DWUI within 10 years. What happens to the license?","o":["It is revoked for three years","It is suspended for 90 days","It is suspended for six months","Nothing, if the driver pays a fine"],"h1":"A third offense is much more serious than the first two.","h2":"In Wyoming, a third DWUI within 10 years leads to a three-year revocation of the license.","p":"Right. A third DWUI means a three-year revocation."},"es":{"q":"En Wyoming, un conductor es condenado por un tercer DWUI dentro de 10 años. ¿Qué pasa con la licencia?","o":["Se revoca por tres años","Se suspende por 90 días","Se suspende por seis meses","Nada, si el conductor paga una multa"],"h1":"Una tercera vez es mucho más grave que las dos primeras.","h2":"En Wyoming, un tercer DWUI dentro de 10 años lleva a la revocación de la licencia por tres años.","p":"Correcto. Un tercer DWUI significa tres años de revocación."},"zh":{"q":"在 Wyoming，一名司机在 10 年内第三次被判 DWUI。驾照会怎么样？","o":["被吊销三年","被暂停 90 天","被暂停六个月","如果司机交罚款，就没事"],"h1":"第三次违规比前两次严重得多。","h2":"在 Wyoming，10 年内第三次 DWUI 会导致驾照被吊销三年。","p":"对。第三次 DWUI 意味着驾照被吊销三年。"},"vi":{"q":"Ở Wyoming, một người lái xe bị kết án DWUI lần thứ ba trong vòng 10 năm. Bằng lái sẽ ra sao?","o":["Bị thu hồi ba năm","Bị đình chỉ 90 ngày","Bị đình chỉ sáu tháng","Không sao cả, nếu người lái trả tiền phạt"],"h1":"Lần vi phạm thứ ba nghiêm trọng hơn nhiều so với hai lần đầu.","h2":"Ở Wyoming, DWUI lần thứ ba trong vòng 10 năm sẽ bị thu hồi bằng lái ba năm.","p":"Đúng. DWUI lần thứ ba nghĩa là bị thu hồi bằng lái ba năm."},"tl":{"q":"Sa Wyoming, nahatulan ang isang driver sa pangatlong DWUI sa loob ng 10 taon. Ano ang mangyayari sa lisensiya?","o":["Babawiin ito nang tatlong taon","Masususpinde ito nang 90 araw","Masususpinde ito nang anim na buwan","Wala, kung magbabayad ng multa ang driver"],"h1":"Mas mabigat ang pangatlong paglabag kaysa sa unang dalawa.","h2":"Sa Wyoming, ang pangatlong DWUI sa loob ng 10 taon ay nagdudulot ng pagbawi ng lisensiya nang tatlong taon.","p":"Tama. Ang pangatlong DWUI ay nangangahulugang pagbawi ng lisensiya nang tatlong taon."},"ar":{"q":"في Wyoming، أُدين سائق بمخالفة DWUI ثالثة خلال 10 سنوات. ماذا يحدث للرخصة؟","o":["تُسحب لمدة ثلاث سنوات","تُوقف لمدة 90 يومًا","تُوقف لمدة ستة أشهر","لا شيء، إذا دفع السائق غرامة"],"h1":"المخالفة الثالثة أخطر بكثير من المخالفتين الأوليين.","h2":"في Wyoming، مخالفة DWUI الثالثة خلال 10 سنوات تؤدي إلى سحب الرخصة لمدة ثلاث سنوات.","p":"صحيح. مخالفة DWUI الثالثة تعني سحب الرخصة لمدة ثلاث سنوات."},"ref":{"doc":"WY","page":21}},{"id":"wy-042","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a child under 9 rides in a child safety seat in a car that has a back seat. Where must the child ride?","o":["In the front seat, so the driver can watch","In a back seat","In any seat that has an airbag","In the front seat if the child weighs over 40 pounds"],"h1":"Think about airbags and the safest place for a child.","h2":"In Wyoming, a child under 9 must ride in a seat other than the front seat, unless the car has only one row or all other belts are used by children.","p":"Right. The child rides in a back seat."},"es":{"q":"En Wyoming, un niño menor de 9 años viaja en un asiento de seguridad en un auto que tiene asiento trasero. ¿Dónde debe ir el niño?","o":["En el asiento delantero, para que el conductor lo vea","En un asiento trasero","En cualquier asiento que tenga bolsa de aire","En el asiento delantero si el niño pesa más de 40 libras"],"h1":"Piense en las bolsas de aire y en el lugar más seguro para un niño.","h2":"En Wyoming, un niño menor de 9 años debe ir en un asiento que no sea el delantero, salvo que el auto tenga una sola fila o todos los demás cinturones los usen otros niños.","p":"Correcto. El niño va en un asiento trasero."},"zh":{"q":"在 Wyoming，一个 9 岁以下的孩子坐在有后座的车里的儿童安全座椅上。孩子必须坐在哪里？","o":["坐前座，方便司机看着","坐后座","坐任何有安全气囊的座位","如果孩子超过 40 磅，坐前座"],"h1":"想一想安全气囊，以及对孩子最安全的位置。","h2":"在 Wyoming，9 岁以下的孩子必须坐在前座以外的座位，除非车只有一排座位，或者其他安全带都已经被孩子使用。","p":"对。孩子坐在后座。"},"vi":{"q":"Ở Wyoming, một em bé dưới 9 tuổi ngồi ghế an toàn trẻ em trong một chiếc xe có ghế sau. Em bé phải ngồi ở đâu?","o":["Ở ghế trước, để người lái có thể trông chừng","Ở ghế sau","Ở bất kỳ ghế nào có túi khí","Ở ghế trước nếu em bé nặng hơn 40 pound"],"h1":"Hãy nghĩ về túi khí và chỗ an toàn nhất cho trẻ em.","h2":"Ở Wyoming, trẻ em dưới 9 tuổi phải ngồi ở ghế khác ngoài ghế trước, trừ khi xe chỉ có một hàng ghế hoặc tất cả các dây an toàn khác đều đã có trẻ em dùng.","p":"Đúng. Em bé ngồi ở ghế sau."},"tl":{"q":"Sa Wyoming, isang batang wala pang 9 taong gulang ang nakaupo sa child safety seat sa kotseng may upuan sa likod. Saan dapat umupo ang bata?","o":["Sa upuan sa harap, para mabantayan ng driver","Sa upuan sa likod","Sa kahit anong upuan na may airbag","Sa upuan sa harap kung ang bata ay higit sa 40 pounds"],"h1":"Isipin ang mga airbag at ang pinakaligtas na lugar para sa bata.","h2":"Sa Wyoming, ang batang wala pang 9 taong gulang ay dapat umupo sa upuang hindi sa harap, maliban kung iisa lang ang hanay ng upuan ng kotse o lahat ng ibang seat belt ay gamit na ng mga bata.","p":"Tama. Sa upuan sa likod umuupo ang bata."},"ar":{"q":"في Wyoming، طفل عمره أقل من 9 سنوات يجلس في مقعد أمان للأطفال في سيارة فيها مقعد خلفي. أين يجب أن يجلس الطفل؟","o":["في المقعد الأمامي، لكي يراقبه السائق","في مقعد خلفي","في أي مقعد فيه وسادة هوائية","في المقعد الأمامي إذا كان وزن الطفل أكثر من 40 رطلًا"],"h1":"فكّر في الوسائد الهوائية وفي أكثر مكان آمن للطفل.","h2":"في Wyoming يجب أن يجلس الطفل الذي عمره أقل من 9 سنوات في مقعد غير المقعد الأمامي، إلا إذا كان في السيارة صف واحد فقط أو كانت كل الأحزمة الأخرى يستعملها أطفال.","p":"صحيح. يجلس الطفل في مقعد خلفي."},"ref":{"doc":"WY","page":30}},{"id":"wy-043","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, a vehicle ahead has a slow-moving vehicle sign on the back. How fast can that vehicle go at most?","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"It is slower than most town speed limits.","h2":"In Wyoming, the slow-moving vehicle sign means the vehicle cannot go faster than 25 mph.","p":"Right. That vehicle cannot go faster than 25 mph."},"es":{"q":"En Wyoming, un vehículo adelante tiene en la parte trasera la señal de vehículo lento. ¿Qué tan rápido puede ir ese vehículo como máximo?","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"Es más lento que la mayoría de los límites de velocidad en la ciudad.","h2":"En Wyoming, la señal de vehículo lento significa que el vehículo no puede ir a más de 25 mph.","p":"Correcto. Ese vehículo no puede ir a más de 25 mph."},"zh":{"q":"在 Wyoming，前面一辆车的车尾有慢速车辆标志。那辆车最快可以开多快？","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"比大多数城镇的限速还慢。","h2":"在 Wyoming，慢速车辆标志表示那辆车不能开得比 25 mph 快。","p":"对。那辆车不能开得比 25 mph 快。"},"vi":{"q":"Ở Wyoming, một xe phía trước có biển báo xe chạy chậm ở phía sau. Xe đó có thể chạy nhanh nhất là bao nhiêu?","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"Nó chậm hơn giới hạn tốc độ của hầu hết các thị trấn.","h2":"Ở Wyoming, biển báo xe chạy chậm có nghĩa là xe đó không thể chạy nhanh hơn 25 mph.","p":"Đúng. Xe đó không thể chạy nhanh hơn 25 mph."},"tl":{"q":"Sa Wyoming, may slow-moving vehicle sign sa likod ng sasakyan sa unahan mo. Hanggang gaano kabilis puwedeng tumakbo ang sasakyang iyon?","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"Mas mabagal ito kaysa sa karamihan ng speed limit sa bayan.","h2":"Sa Wyoming, ang slow-moving vehicle sign ay nangangahulugang hindi puwedeng tumakbo nang mas mabilis sa 25 mph ang sasakyan.","p":"Tama. Hindi puwedeng tumakbo nang mas mabilis sa 25 mph ang sasakyang iyon."},"ar":{"q":"في Wyoming، على مؤخرة مركبة أمامك علامة المركبة البطيئة. ما أقصى سرعة يمكن أن تسير بها تلك المركبة؟","o":["45 mph","35 mph","15 mph","25 mph"],"h1":"هي أبطأ من حدود السرعة في معظم البلدات.","h2":"في Wyoming تعني علامة المركبة البطيئة أن المركبة لا تستطيع أن تسير أسرع من 25 mph.","p":"صحيح. تلك المركبة لا تستطيع أن تسير أسرع من 25 mph."},"ref":{"doc":"WY","page":71}},{"id":"wy-044","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, you are stranded on the road in a blizzard. What should you do?","o":["Stay with your car so you can be found more easily","Walk to the nearest town for help","Run the engine all the time with the windows shut","Let everyone in the car sleep at the same time"],"h1":"Rescuers look for cars, not people walking in the snow.","h2":"In Wyoming, if you are stranded in a blizzard, stay with your car so rescuers can find you more easily.","p":"Right. Stay with your car."},"es":{"q":"En Wyoming, usted queda atrapado en la carretera durante una ventisca. ¿Qué debe hacer?","o":["Quedarse con su auto para que lo encuentren más fácilmente","Caminar al pueblo más cercano para pedir ayuda","Dejar el motor encendido todo el tiempo con las ventanas cerradas","Dejar que todos en el auto duerman al mismo tiempo"],"h1":"Los rescatistas buscan autos, no personas caminando en la nieve.","h2":"En Wyoming, si queda atrapado en una ventisca, quédese con su auto para que los rescatistas lo encuentren más fácilmente.","p":"Correcto. Quédese con su auto."},"zh":{"q":"在 Wyoming，你在暴风雪中被困在路上。你应该怎么做？","o":["留在车里，这样更容易被找到","走到最近的小镇求助","一直开着引擎，并且关紧车窗","让车里所有人同时睡觉"],"h1":"救援人员找的是车，而不是在雪中走路的人。","h2":"在 Wyoming，如果你在暴风雪中被困，要留在车里，这样救援人员更容易找到你。","p":"对。留在车里。"},"vi":{"q":"Ở Wyoming, bạn bị kẹt trên đường trong một trận bão tuyết. Bạn nên làm gì?","o":["Ở lại với xe để người ta dễ tìm thấy bạn hơn","Đi bộ đến thị trấn gần nhất để xin giúp đỡ","Để máy xe chạy liên tục và đóng kín cửa sổ","Để mọi người trong xe ngủ cùng một lúc"],"h1":"Đội cứu hộ tìm xe, không tìm người đi bộ trong tuyết.","h2":"Ở Wyoming, nếu bạn bị kẹt trong bão tuyết, hãy ở lại với xe để đội cứu hộ dễ tìm thấy bạn hơn.","p":"Đúng. Hãy ở lại với xe."},"tl":{"q":"Sa Wyoming, na-stranded ka sa kalsada sa gitna ng blizzard. Ano ang dapat mong gawin?","o":["Manatili sa kotse mo para mas madali kang mahanap","Maglakad papunta sa pinakamalapit na bayan para humingi ng tulong","Paandarin ang makina nang tuloy-tuloy habang sarado ang mga bintana","Patulugin nang sabay-sabay ang lahat ng nasa kotse"],"h1":"Kotse ang hinahanap ng mga rescuer, hindi mga taong naglalakad sa niyebe.","h2":"Sa Wyoming, kapag na-stranded ka sa blizzard, manatili sa kotse mo para mas madali kang mahanap ng mga rescuer.","p":"Tama. Manatili sa kotse mo."},"ar":{"q":"في Wyoming، علقت على الطريق في عاصفة ثلجية. ماذا يجب أن تفعل؟","o":["ابقَ مع سيارتك لكي يسهل العثور عليك","امشِ إلى أقرب بلدة لطلب المساعدة","شغّل المحرك طوال الوقت والنوافذ مغلقة","دع كل من في السيارة ينامون في الوقت نفسه"],"h1":"فرق الإنقاذ تبحث عن السيارات، وليس عن أشخاص يمشون في الثلج.","h2":"في Wyoming، إذا علقت في عاصفة ثلجية فابقَ مع سيارتك لكي يسهل على فرق الإنقاذ العثور عليك.","p":"صحيح. ابقَ مع سيارتك."},"ref":{"doc":"WY","page":80}},{"id":"wy-045","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, when must your headlights be on?","o":["Only from sunset to sunrise","Only when the street lights are on","From half an hour after sunset to half an hour before sunrise","From one hour after sunset to one hour before sunrise"],"h1":"The rule adds a short time around sunset and sunrise.","h2":"In Wyoming, headlights must be on from half an hour after sunset to half an hour before sunrise, and whenever you cannot see clearly 1,000 feet ahead.","p":"Right. From half an hour after sunset to half an hour before sunrise."},"es":{"q":"En Wyoming, ¿cuándo deben estar encendidas sus luces delanteras?","o":["Solo desde la puesta del sol hasta la salida del sol","Solo cuando las luces de la calle están encendidas","Desde media hora después de la puesta del sol hasta media hora antes de la salida del sol","Desde una hora después de la puesta del sol hasta una hora antes de la salida del sol"],"h1":"La regla agrega un poco de tiempo alrededor de la puesta y la salida del sol.","h2":"En Wyoming, las luces delanteras deben estar encendidas desde media hora después de la puesta del sol hasta media hora antes de la salida del sol, y siempre que no pueda ver bien a 1,000 pies.","p":"Correcto. Desde media hora después de la puesta del sol hasta media hora antes de la salida."},"zh":{"q":"在 Wyoming，什么时候必须开车头灯？","o":["只在日落到日出之间","只在路灯亮着的时候","从日落后半小时到日出前半小时","从日落后一小时到日出前一小时"],"h1":"这条规定在日落和日出前后加了一小段时间。","h2":"在 Wyoming，从日落后半小时到日出前半小时，以及任何你看不清前方 1,000 英尺的时候，都必须开车头灯。","p":"对。从日落后半小时到日出前半小时。"},"vi":{"q":"Ở Wyoming, khi nào bạn phải bật đèn pha?","o":["Chỉ từ lúc mặt trời lặn đến lúc mặt trời mọc","Chỉ khi đèn đường đang bật","Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc","Từ một giờ sau khi mặt trời lặn đến một giờ trước khi mặt trời mọc"],"h1":"Quy định này thêm một khoảng thời gian ngắn quanh lúc mặt trời lặn và mọc.","h2":"Ở Wyoming, phải bật đèn pha từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc, và bất cứ khi nào bạn không thể nhìn rõ 1,000 feet phía trước.","p":"Đúng. Từ nửa giờ sau khi mặt trời lặn đến nửa giờ trước khi mặt trời mọc."},"tl":{"q":"Sa Wyoming, kailan dapat nakabukas ang headlights mo?","o":["Mula paglubog hanggang pagsikat ng araw lang","Kapag nakabukas lang ang mga ilaw sa kalye","Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw","Mula isang oras pagkalubog ng araw hanggang isang oras bago sumikat ang araw"],"h1":"Nagdadagdag ang patakaran ng maikling oras sa paligid ng paglubog at pagsikat ng araw.","h2":"Sa Wyoming, dapat nakabukas ang headlights mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw, at tuwing hindi mo makita nang malinaw ang 1,000 feet sa unahan.","p":"Tama. Mula kalahating oras pagkalubog ng araw hanggang kalahating oras bago sumikat ang araw."},"ar":{"q":"في Wyoming، متى يجب أن تكون أضواء سيارتك الأمامية مضاءة؟","o":["فقط من غروب الشمس إلى شروقها","فقط عندما تكون أضواء الشارع مضاءة","من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها","من ساعة بعد غروب الشمس إلى ساعة قبل شروقها"],"h1":"القاعدة تضيف وقتًا قصيرًا حول الغروب والشروق.","h2":"في Wyoming يجب أن تكون الأضواء الأمامية مضاءة من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها، وكلما لم تستطع أن ترى بوضوح 1,000 قدم أمامك.","p":"صحيح. من نصف ساعة بعد غروب الشمس إلى نصف ساعة قبل شروقها."},"ref":{"doc":"WY","page":77}},{"id":"wy-046","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, you are passing a vehicle that is going slower than the speed limit. How much over the limit may you go while passing?","o":["Not at all","Up to 5 mph","Up to 20 mph","Up to 10 mph"],"h1":"It is a small amount, and only while you pass.","h2":"In Wyoming, while passing a vehicle that is going slower than the limit, you may go up to 10 mph over the speed limit.","p":"Right. Up to 10 mph over the limit while passing."},"es":{"q":"En Wyoming, usted rebasa a un vehículo que va más lento que el límite de velocidad. ¿Cuánto puede pasar del límite mientras rebasa?","o":["Nada","Hasta 5 mph","Hasta 20 mph","Hasta 10 mph"],"h1":"Es poco, y solo mientras rebasa.","h2":"En Wyoming, al rebasar a un vehículo que va más lento que el límite, usted puede ir hasta 10 mph por encima del límite de velocidad.","p":"Correcto. Hasta 10 mph sobre el límite mientras rebasa."},"zh":{"q":"在 Wyoming，你正在超过一辆开得比限速慢的车。超车时你最多可以超出限速多少？","o":["完全不可以","最多 5 mph","最多 20 mph","最多 10 mph"],"h1":"只超出一点点，而且只在超车的时候。","h2":"在 Wyoming，超过一辆开得比限速慢的车时，你最多可以超出限速 10 mph。","p":"对。超车时最多可以超出限速 10 mph。"},"vi":{"q":"Ở Wyoming, bạn đang vượt một xe chạy chậm hơn giới hạn tốc độ. Khi vượt, bạn được chạy quá giới hạn bao nhiêu?","o":["Hoàn toàn không được","Tối đa 5 mph","Tối đa 20 mph","Tối đa 10 mph"],"h1":"Đó là một mức nhỏ, và chỉ trong lúc bạn vượt.","h2":"Ở Wyoming, khi vượt một xe chạy chậm hơn giới hạn, bạn được chạy quá giới hạn tốc độ tối đa 10 mph.","p":"Đúng. Tối đa 10 mph quá giới hạn khi vượt."},"tl":{"q":"Sa Wyoming, nag-o-overtake ka sa sasakyang mas mabagal kaysa sa speed limit. Gaano kalaki ang puwede mong ilampas sa limit habang nag-o-overtake?","o":["Hindi talaga puwede","Hanggang 5 mph","Hanggang 20 mph","Hanggang 10 mph"],"h1":"Maliit lang ito, at habang nag-o-overtake ka lang.","h2":"Sa Wyoming, habang nag-o-overtake sa sasakyang mas mabagal kaysa sa limit, puwede kang lumampas nang hanggang 10 mph sa speed limit.","p":"Tama. Hanggang 10 mph lampas sa limit habang nag-o-overtake."},"ar":{"q":"في Wyoming، أنت تتجاوز مركبة تسير أبطأ من حدّ السرعة. بكم يمكنك أن تتجاوز حدّ السرعة أثناء التجاوز؟","o":["لا يُسمح بذلك أبدًا","حتى 5 mph","حتى 20 mph","حتى 10 mph"],"h1":"هو مقدار صغير، وفقط أثناء التجاوز.","h2":"في Wyoming، أثناء تجاوز مركبة تسير أبطأ من الحدّ، يمكنك أن تزيد حتى 10 mph فوق حدّ السرعة.","p":"صحيح. حتى 10 mph فوق الحدّ أثناء التجاوز."},"ref":{"doc":"WY","page":54}},{"id":"wy-047","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, trees and buildings block your view at an intersection. How fast should you go as you come near it?","o":["No more than 10 mph","No more than 15 mph","No more than 25 mph","The posted speed limit"],"h1":"It is slower than a school zone.","h2":"In Wyoming, you should come near a blind intersection at no more than 15 mph.","p":"Right. No more than 15 mph at a blind intersection."},"es":{"q":"En Wyoming, árboles y edificios le tapan la vista en una intersección. ¿A qué velocidad debe acercarse a ella?","o":["A no más de 10 mph","A no más de 15 mph","A no más de 25 mph","Al límite de velocidad indicado"],"h1":"Es más lento que en una zona escolar.","h2":"En Wyoming, usted debe acercarse a una intersección sin visibilidad a no más de 15 mph.","p":"Correcto. A no más de 15 mph en una intersección sin visibilidad."},"zh":{"q":"在 Wyoming，树木和建筑物挡住了你在路口的视线。你接近这个路口时应该开多快？","o":["不超过 10 mph","不超过 15 mph","不超过 25 mph","标示的限速"],"h1":"比学校区还慢。","h2":"在 Wyoming，接近视线被挡住的路口时，你的速度应该不超过 15 mph。","p":"对。在视线被挡住的路口不超过 15 mph。"},"vi":{"q":"Ở Wyoming, cây cối và nhà cửa che khuất tầm nhìn của bạn tại một giao lộ. Bạn nên chạy nhanh bao nhiêu khi đến gần giao lộ đó?","o":["Không quá 10 mph","Không quá 15 mph","Không quá 25 mph","Theo giới hạn tốc độ được ghi trên biển"],"h1":"Nó chậm hơn khu vực trường học.","h2":"Ở Wyoming, bạn nên đến gần một giao lộ bị che khuất tầm nhìn với tốc độ không quá 15 mph.","p":"Đúng. Không quá 15 mph tại giao lộ bị che khuất tầm nhìn."},"tl":{"q":"Sa Wyoming, hinaharangan ng mga puno at gusali ang tanaw mo sa isang intersection. Gaano kabilis ka dapat habang papalapit dito?","o":["Hindi hihigit sa 10 mph","Hindi hihigit sa 15 mph","Hindi hihigit sa 25 mph","Ang nakapaskil na speed limit"],"h1":"Mas mabagal ito kaysa sa school zone.","h2":"Sa Wyoming, dapat kang lumapit sa blind intersection nang hindi hihigit sa 15 mph.","p":"Tama. Hindi hihigit sa 15 mph sa blind intersection."},"ar":{"q":"في Wyoming، الأشجار والمباني تحجب رؤيتك عند تقاطع. بأي سرعة يجب أن تقترب منه؟","o":["ليس أكثر من 10 mph","ليس أكثر من 15 mph","ليس أكثر من 25 mph","حدّ السرعة المكتوب على اللافتة"],"h1":"هي أبطأ من منطقة المدرسة.","h2":"في Wyoming يجب أن تقترب من التقاطع المحجوب الرؤية بسرعة لا تزيد على 15 mph.","p":"صحيح. ليس أكثر من 15 mph عند التقاطع المحجوب الرؤية."},"ref":{"doc":"WY","page":41}},{"id":"wy-048","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, the road is covered with packed snow. How much should you slow down?","o":["By at least half","By 5 mph","By 10 mph","Not at all if you have four-wheel drive"],"h1":"It is a big cut, much more than on a wet road.","h2":"In Wyoming, on packed snow you should cut your speed by at least half.","p":"Right. Slow down by at least half on packed snow."},"es":{"q":"En Wyoming, la carretera está cubierta de nieve compacta. ¿Cuánto debe reducir la velocidad?","o":["Por lo menos a la mitad","5 mph","10 mph","Nada, si tiene tracción en las cuatro ruedas"],"h1":"Es una reducción grande, mucho más que en una carretera mojada.","h2":"En Wyoming, sobre nieve compacta usted debe reducir su velocidad por lo menos a la mitad.","p":"Correcto. Reduzca la velocidad por lo menos a la mitad sobre nieve compacta."},"zh":{"q":"在 Wyoming，路面上覆盖着压实的雪。你应该减速多少？","o":["至少减一半","减 5 mph","减 10 mph","如果是四轮驱动，完全不用减速"],"h1":"减得很多，比在湿路上多得多。","h2":"在 Wyoming，在压实的雪上，你应该把速度至少减一半。","p":"对。在压实的雪上至少减速一半。"},"vi":{"q":"Ở Wyoming, mặt đường phủ đầy tuyết bị nén chặt. Bạn nên giảm tốc độ bao nhiêu?","o":["Ít nhất một nửa","5 mph","10 mph","Không cần giảm nếu xe bạn dẫn động bốn bánh"],"h1":"Đó là mức giảm lớn, nhiều hơn hẳn so với trên đường ướt.","h2":"Ở Wyoming, trên tuyết bị nén chặt, bạn nên giảm tốc độ ít nhất một nửa.","p":"Đúng. Giảm tốc độ ít nhất một nửa trên tuyết bị nén chặt."},"tl":{"q":"Sa Wyoming, natatakpan ng siksik na niyebe ang kalsada. Gaano mo dapat bagalan ang takbo?","o":["Hindi bababa sa kalahati","Nang 5 mph","Nang 10 mph","Hindi na kailangan kung four-wheel drive ka"],"h1":"Malaking bawas ito, mas malaki kaysa sa basang kalsada.","h2":"Sa Wyoming, sa siksik na niyebe, dapat mong bawasan ang bilis mo nang hindi bababa sa kalahati.","p":"Tama. Bagalan nang hindi bababa sa kalahati sa siksik na niyebe."},"ar":{"q":"في Wyoming، الطريق مغطّى بثلج مضغوط. كم يجب أن تخفّف سرعتك؟","o":["إلى النصف على الأقل","بمقدار 5 mph","بمقدار 10 mph","ليس عليك أن تخفّفها إذا كانت سيارتك رباعية الدفع"],"h1":"هو تخفيض كبير، أكثر بكثير من الطريق المبلّل.","h2":"في Wyoming، على الثلج المضغوط يجب أن تخفّف سرعتك إلى النصف على الأقل.","p":"صحيح. خفّف سرعتك إلى النصف على الأقل على الثلج المضغوط."},"ref":{"doc":"WY","page":41}},{"id":"wy-049","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, ice covers the road. How many seconds behind the vehicle ahead should a car stay?","o":["2 seconds","4 seconds","6 seconds","8 seconds"],"h1":"Take the normal following time and multiply it by four.","h2":"In Wyoming, on ice a car should stay about 8 seconds behind the vehicle ahead, four times the normal following time.","p":"Right. About 8 seconds on ice."},"es":{"q":"En Wyoming, hay hielo en la carretera. ¿Cuántos segundos detrás del vehículo de adelante debe mantenerse un auto?","o":["2 segundos","4 segundos","6 segundos","8 segundos"],"h1":"Tome el tiempo normal de distancia y multiplíquelo por cuatro.","h2":"En Wyoming, sobre hielo un auto debe mantenerse unos 8 segundos detrás del vehículo de adelante, cuatro veces la distancia normal.","p":"Correcto. Unos 8 segundos sobre hielo."},"zh":{"q":"在 Wyoming，路面结冰。汽车应该和前车保持几秒的距离？","o":["2 秒","4 秒","6 秒","8 秒"],"h1":"把正常的跟车时间乘以四。","h2":"在 Wyoming，在冰上，汽车应该和前车保持大约 8 秒的距离，是正常跟车时间的四倍。","p":"对。在冰上大约 8 秒。"},"vi":{"q":"Ở Wyoming, băng phủ mặt đường. Một chiếc xe hơi nên giữ khoảng cách bao nhiêu giây sau xe phía trước?","o":["2 giây","4 giây","6 giây","8 giây"],"h1":"Lấy thời gian giữ khoảng cách bình thường nhân với bốn.","h2":"Ở Wyoming, trên băng, xe hơi nên giữ khoảng 8 giây sau xe phía trước, gấp bốn lần thời gian giữ khoảng cách bình thường.","p":"Đúng. Khoảng 8 giây trên băng."},"tl":{"q":"Sa Wyoming, may yelo sa kalsada. Ilang segundo dapat ang layo ng kotse sa sasakyan sa unahan?","o":["2 segundo","4 na segundo","6 na segundo","8 segundo"],"h1":"Kunin ang normal na following time at i-multiply sa apat.","h2":"Sa Wyoming, sa yelo, dapat manatili ang kotse nang mga 8 segundo sa likod ng sasakyan sa unahan, apat na beses ng normal na following time.","p":"Tama. Mga 8 segundo sa yelo."},"ar":{"q":"في Wyoming، الجليد يغطّي الطريق. كم ثانية يجب أن تبقى السيارة خلف المركبة التي أمامها؟","o":["ثانيتان (2)","4 ثوانٍ","6 ثوانٍ","8 ثوانٍ"],"h1":"خذ وقت المسافة العادي واضربه في أربعة.","h2":"في Wyoming، على الجليد يجب أن تبقى السيارة نحو 8 ثوانٍ خلف المركبة التي أمامها، أي أربعة أضعاف وقت المسافة العادي.","p":"صحيح. نحو 8 ثوانٍ على الجليد."},"ref":{"doc":"WY","page":79}},{"id":"wy-050","scope":"WY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wyoming, at an intersection with no signs or signals, you arrive first. A car is coming from your right. Who must yield?","o":["The other car, because you arrived first","Whoever is going faster","You must yield to the car on your right","Neither car; both may go slowly"],"h1":"At these intersections, arriving first does not decide it.","h2":"In Wyoming, at an intersection with no signs or signals, you must yield to a driver coming from your right, even if you got there first.","p":"Right. You yield to the car on your right."},"es":{"q":"En Wyoming, en una intersección sin señales ni semáforos, usted llega primero. Un auto viene por su derecha. ¿Quién debe ceder el paso?","o":["El otro auto, porque usted llegó primero","El que vaya más rápido","Usted debe ceder el paso al auto de su derecha","Ninguno; los dos pueden pasar despacio"],"h1":"En estas intersecciones, llegar primero no es lo que decide.","h2":"En Wyoming, en una intersección sin señales ni semáforos, usted debe ceder el paso al conductor que viene por su derecha, aunque usted haya llegado primero.","p":"Correcto. Usted cede el paso al auto de su derecha."},"zh":{"q":"在 Wyoming，在一个没有标志或信号灯的路口，你先到。有一辆车从你的右边开过来。谁必须让行？","o":["另一辆车，因为你先到","开得比较快的那辆","你必须让右边的车先走","两辆都不用让，都可以慢慢开"],"h1":"在这种路口，谁先到并不决定谁先走。","h2":"在 Wyoming，在没有标志或信号灯的路口，你必须让从你右边来的司机先走，即使你先到。","p":"对。你要让右边的车先走。"},"vi":{"q":"Ở Wyoming, tại một giao lộ không có biển báo hay đèn tín hiệu, bạn đến trước. Có một xe đang đến từ bên phải bạn. Ai phải nhường đường?","o":["Xe kia, vì bạn đến trước","Xe nào đang chạy nhanh hơn","Bạn phải nhường đường cho xe bên phải","Không xe nào; cả hai có thể đi chậm"],"h1":"Ở những giao lộ này, ai đến trước không quyết định ai được đi.","h2":"Ở Wyoming, tại giao lộ không có biển báo hay đèn tín hiệu, bạn phải nhường đường cho người lái đến từ bên phải bạn, dù bạn đến trước.","p":"Đúng. Bạn nhường đường cho xe bên phải."},"tl":{"q":"Sa Wyoming, sa intersection na walang sign o signal, ikaw ang unang dumating. May kotseng paparating mula sa kanan mo. Sino ang dapat magbigay-daan?","o":["Ang ibang kotse, dahil ikaw ang unang dumating","Kung sino ang mas mabilis","Dapat kang magbigay-daan sa kotse sa kanan mo","Wala; puwedeng dumaan nang dahan-dahan ang dalawa"],"h1":"Sa ganitong intersection, hindi ang pagdating nang una ang nagpapasya.","h2":"Sa Wyoming, sa intersection na walang sign o signal, dapat kang magbigay-daan sa driver na galing sa kanan mo, kahit ikaw ang unang dumating.","p":"Tama. Magbibigay-daan ka sa kotse sa kanan mo."},"ar":{"q":"في Wyoming، عند تقاطع بلا لافتات أو إشارات، وصلت أولًا. هناك سيارة قادمة من يمينك. من يجب أن يفسح الطريق؟","o":["السيارة الأخرى، لأنك وصلت أولًا","من يسير أسرع","يجب أن تفسح الطريق للسيارة التي على يمينك","لا أحد منهما؛ يمكن للسيارتين أن تسيرا ببطء"],"h1":"عند هذه التقاطعات، الوصول أولًا لا يحدّد من يمرّ.","h2":"في Wyoming، عند تقاطع بلا لافتات أو إشارات، يجب أن تفسح الطريق للسائق القادم من يمينك، حتى لو وصلت أولًا.","p":"صحيح. تفسح الطريق للسيارة التي على يمينك."},"ref":{"doc":"WY","page":42}},{"id":"wy-051","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, you move from another state with a valid license. How long do you have to give up your old state's license?","o":["Within 10 days","Within 90 days","Within one year","You never have to"],"h1":"It is a long time, counted from when you become a resident.","h2":"In Wyoming, a new resident must give up the out-of-state license within one year of residency.","p":"Right. You have one year to give up the old license."},"es":{"q":"En Wyoming, usted se muda de otro estado con una licencia válida. ¿Cuánto tiempo tiene para entregar la licencia de su estado anterior?","o":["Dentro de 10 días","Dentro de 90 días","Dentro de un año","Nunca tiene que hacerlo"],"h1":"Es bastante tiempo, contado desde que usted se hace residente.","h2":"En Wyoming, un nuevo residente debe entregar la licencia de otro estado dentro de un año de residencia.","p":"Correcto. Tiene un año para entregar la licencia anterior."},"ref":{"doc":"WY","page":5}},{"id":"wy-052","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, a full-time student at the University of Wyoming has a valid license from another state. Does the student need a Wyoming license?","o":["No, the out-of-state license is enough","Yes, within 10 days","Yes, within 30 days","Only to drive on interstates"],"h1":"The handbook lists these students among people who do not need a Wyoming license.","h2":"In Wyoming, a full-time student at the University of Wyoming or a Wyoming community college may drive with a valid license from another state.","p":"Right. Full-time students may keep using their valid out-of-state license."},"es":{"q":"En Wyoming, un estudiante de tiempo completo de la Universidad de Wyoming tiene una licencia válida de otro estado. ¿Necesita una licencia de Wyoming?","o":["No, la licencia de otro estado es suficiente","Sí, dentro de 10 días","Sí, dentro de 30 días","Solo para manejar en autopistas interestatales"],"h1":"El manual pone a estos estudiantes entre las personas que no necesitan licencia de Wyoming.","h2":"En Wyoming, un estudiante de tiempo completo de la Universidad de Wyoming o de un colegio comunitario de Wyoming puede manejar con una licencia válida de otro estado.","p":"Correcto. Los estudiantes de tiempo completo pueden seguir usando su licencia válida de otro estado."},"ref":{"doc":"WY","page":5}},{"id":"wy-053","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a Class C license lets you drive a single vehicle that weighs (GVWR) less than how much?","o":["10,001 pounds","26,001 pounds","36,001 pounds","There is no weight limit"],"h1":"It is the same weight line where commercial Class B starts.","h2":"In Wyoming, a Class C license covers vehicles with a GVWR of less than 26,001 pounds, except motorcycles.","p":"Right. Class C is for vehicles under 26,001 pounds."},"es":{"q":"En Wyoming, una licencia Clase C le permite manejar un solo vehículo con un peso (GVWR) menor de ¿cuánto?","o":["10,001 libras","26,001 libras","36,001 libras","No hay límite de peso"],"h1":"Es el mismo peso donde empieza la Clase B comercial.","h2":"En Wyoming, la licencia Clase C cubre vehículos con un GVWR menor de 26,001 libras, excepto motocicletas.","p":"Correcto. La Clase C es para vehículos de menos de 26,001 libras."},"ref":{"doc":"WY","page":6}},{"id":"wy-054","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, what is a Class M license for?","o":["Buses","Farm tractors","Moving trucks","Motorcycles"],"h1":"Think of the first letter of the vehicle.","h2":"In Wyoming, the Class M license is only for driving motorcycles.","p":"Right. Class M is the motorcycle license."},"es":{"q":"En Wyoming, ¿para qué es la licencia Clase M?","o":["Autobuses","Tractores agrícolas","Camiones de mudanza","Motocicletas"],"h1":"Piense en la primera letra del vehículo en inglés.","h2":"En Wyoming, la licencia Clase M es solo para manejar motocicletas.","p":"Correcto. La Clase M es la licencia de motocicleta."},"ref":{"doc":"WY","page":6}},{"id":"wy-055","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a license shows restriction code B. What does it mean?","o":["Automatic transmission only","You must wear glasses or contact lenses to drive","Daylight driving only","No passengers"],"h1":"It is the most common restriction, and it is about your eyes.","h2":"In Wyoming, restriction code B means you must wear corrective lenses when you drive.","p":"Right. Code B means corrective lenses."},"es":{"q":"En Wyoming, una licencia muestra el código de restricción B. ¿Qué significa?","o":["Solo transmisión automática","Debe usar lentes o lentes de contacto para manejar","Solo manejar de día","Sin pasajeros"],"h1":"Es la restricción más común y tiene que ver con sus ojos.","h2":"En Wyoming, el código de restricción B significa que usted debe usar lentes correctivos cuando maneja.","p":"Correcto. El código B significa lentes correctivos."},"ref":{"doc":"WY","page":7}},{"id":"wy-056","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a license shows restriction code G. What does it mean?","o":["Glasses required","Automatic transmission only","Daylight driving only","Valid without photo"],"h1":"It limits the time of day when you may drive.","h2":"In Wyoming, restriction code G means the driver may drive only in daylight.","p":"Right. Code G means daylight driving only."},"es":{"q":"En Wyoming, una licencia muestra el código de restricción G. ¿Qué significa?","o":["Lentes obligatorios","Solo transmisión automática","Solo manejar de día","Válida sin foto"],"h1":"Limita la hora del día en que puede manejar.","h2":"En Wyoming, el código de restricción G significa que la persona solo puede manejar de día.","p":"Correcto. El código G significa manejar solo de día."},"ref":{"doc":"WY","page":7}},{"id":"wy-057","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, a license shows restriction code A. What does it mean?","o":["You may drive only a car with an automatic transmission","You must wear glasses","You may drive only in Wyoming","You may not carry passengers"],"h1":"It is about the kind of gearbox the car has.","h2":"In Wyoming, restriction code A means the driver may drive only vehicles with an automatic transmission.","p":"Right. Code A means automatic transmission only."},"es":{"q":"En Wyoming, una licencia muestra el código de restricción A. ¿Qué significa?","o":["Solo puede manejar un carro con transmisión automática","Debe usar lentes","Solo puede manejar en Wyoming","No puede llevar pasajeros"],"h1":"Tiene que ver con el tipo de caja de cambios del carro.","h2":"En Wyoming, el código de restricción A significa que la persona solo puede manejar vehículos con transmisión automática.","p":"Correcto. El código A significa solo transmisión automática."},"ref":{"doc":"WY","page":7}},{"id":"wy-058","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, you are 16 and applying for a license. What must you bring besides your ID and proof of residency?","o":["A letter from your school principal","Proof that you own a car","A doctor's note","A release form signed by a parent or legal guardian"],"h1":"Applicants under 18 need an adult's permission.","h2":"In Wyoming, an applicant under 18 must have a minor's release form signed by a parent or legal guardian.","p":"Right. Under 18, a parent or guardian signs a release."},"es":{"q":"En Wyoming, usted tiene 16 años y solicita una licencia. ¿Qué debe traer además de su identificación y prueba de residencia?","o":["Una carta del director de su escuela","Prueba de que es dueño de un carro","Una nota del médico","Un formulario de autorización firmado por su padre, madre o tutor legal"],"h1":"Los solicitantes menores de 18 años necesitan el permiso de un adulto.","h2":"En Wyoming, un solicitante menor de 18 años debe tener un formulario de autorización firmado por su padre, madre o tutor legal.","p":"Correcto. Si es menor de 18, un padre o tutor firma una autorización."},"ref":{"doc":"WY","page":7}},{"id":"wy-059","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how many documents must you show to prove that you live in the state?","o":["One","Two","Three","Four"],"h1":"More than one, but not many.","h2":"In Wyoming, you must show two documents that prove your Wyoming residency.","p":"Right. You need two proofs of residency."},"es":{"q":"En Wyoming, ¿cuántos documentos debe mostrar para probar que vive en el estado?","o":["Uno","Dos","Tres","Cuatro"],"h1":"Más de uno, pero no muchos.","h2":"En Wyoming, usted debe mostrar dos documentos que prueben su residencia en Wyoming.","p":"Correcto. Necesita dos pruebas de residencia."},"ref":{"doc":"WY","page":8}},{"id":"wy-060","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, your proof of residency shows only a P.O. Box. Will it be accepted?","o":["Yes, any address is fine","Yes, if it is a Wyoming P.O. Box","No, it must show a home address, not a P.O. Box","Only if a parent signs it"],"h1":"The office wants to know where you actually live.","h2":"In Wyoming, proof of residency must show a residential address; a P.O. Box is not accepted.","p":"Right. It must show where you live, not a P.O. Box."},"es":{"q":"En Wyoming, su prueba de residencia muestra solo un apartado postal (P.O. Box). ¿La aceptarán?","o":["Sí, cualquier dirección sirve","Sí, si es un apartado postal de Wyoming","No, debe mostrar la dirección de su casa, no un apartado postal","Solo si la firma un padre"],"h1":"La oficina quiere saber dónde vive usted de verdad.","h2":"En Wyoming, la prueba de residencia debe mostrar una dirección residencial; no se acepta un apartado postal.","p":"Correcto. Debe mostrar dónde vive, no un apartado postal."},"ref":{"doc":"WY","page":8}},{"id":"wy-061","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how wide must your side-to-side field of vision be, with both eyes, to meet the vision standard?","o":["At least 120 degrees","At least 90 degrees","At least 60 degrees","At least 180 degrees"],"h1":"It is one third of a full circle.","h2":"In Wyoming, you need a combined horizontal field of vision of at least 120 degrees.","p":"Right. You need at least 120 degrees of side vision."},"es":{"q":"En Wyoming, ¿qué tan amplio debe ser su campo de visión de lado a lado, con ambos ojos, para cumplir el requisito de visión?","o":["Por lo menos 120 grados","Por lo menos 90 grados","Por lo menos 60 grados","Por lo menos 180 grados"],"h1":"Es un tercio de un círculo completo.","h2":"En Wyoming, usted necesita un campo de visión horizontal combinado de por lo menos 120 grados.","p":"Correcto. Necesita por lo menos 120 grados de visión lateral."},"ref":{"doc":"WY","page":8}},{"id":"wy-062","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, your eyesight is worse than 20/40 but at least 20/100. What will you have to do?","o":["Nothing more; you pass","Wait one year","Get a license for motorcycles only","Take a driving skills test"],"h1":"The examiner wants to see you drive.","h2":"In Wyoming, if your eyesight is worse than 20/40 but at least 20/100, you must take a driving skills test.","p":"Right. You will take a driving skills test."},"es":{"q":"En Wyoming, su vista es peor que 20/40 pero por lo menos 20/100. ¿Qué tendrá que hacer?","o":["Nada más; usted pasa","Esperar un año","Sacar una licencia solo para motocicleta","Tomar un examen práctico de manejo"],"h1":"El examinador quiere verle manejar.","h2":"En Wyoming, si su vista es peor que 20/40 pero por lo menos 20/100, usted debe tomar un examen práctico de manejo.","p":"Correcto. Tomará un examen práctico de manejo."},"ref":{"doc":"WY","page":8}},{"id":"wy-063","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, you fail the vision screening at the license office. What must you get?","o":["A note from a parent","A vision statement from an eye specialist","A new birth certificate","A letter from your school"],"h1":"A professional who checks eyes must fill it out.","h2":"In Wyoming, if you fail the vision screening, you must get a vision statement from an eye specialist.","p":"Right. You need a vision statement from an eye specialist."},"es":{"q":"En Wyoming, usted no pasa la prueba de visión en la oficina de licencias. ¿Qué debe conseguir?","o":["Una nota de su padre o madre","Una declaración de visión de un especialista de los ojos","Un acta de nacimiento nueva","Una carta de su escuela"],"h1":"La debe llenar un profesional que revisa los ojos.","h2":"En Wyoming, si no pasa la prueba de visión, usted debe conseguir una declaración de visión de un especialista de los ojos.","p":"Correcto. Necesita una declaración de visión de un especialista de los ojos."},"ref":{"doc":"WY","page":8}},{"id":"wy-064","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, the written test is given only in English. What may a person who does not read English use?","o":["A test in another language","A phone translation app during the test","An interpreter","Nothing; they cannot take the test"],"h1":"Another person can help.","h2":"In Wyoming, all tests are in English, but a person who cannot speak or write English may use an interpreter.","p":"Right. An interpreter may be used."},"es":{"q":"En Wyoming, el examen escrito se da solo en inglés. ¿Qué puede usar una persona que no lee inglés?","o":["Un examen en otro idioma","Una aplicación de traducción en el teléfono durante el examen","Un intérprete","Nada; no puede tomar el examen"],"h1":"Otra persona puede ayudar.","h2":"En Wyoming, todos los exámenes son en inglés, pero una persona que no habla ni escribe inglés puede usar un intérprete.","p":"Correcto. Se puede usar un intérprete."},"ref":{"doc":"WY","page":9}},{"id":"wy-065","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, you want to take the written test as an oral (spoken) test. When must you ask for it?","o":["Before you start the test","After you fail the test once","At least 30 days ahead, in writing","Oral tests are not offered"],"h1":"You cannot switch in the middle.","h2":"In Wyoming, an oral test is available, but you must ask for it before you take the test.","p":"Right. Ask for the oral test before you start."},"es":{"q":"En Wyoming, usted quiere tomar el examen escrito de forma oral (hablada). ¿Cuándo debe pedirlo?","o":["Antes de empezar el examen","Después de reprobar el examen una vez","Por lo menos 30 días antes, por escrito","No se ofrecen exámenes orales"],"h1":"No puede cambiar a la mitad.","h2":"En Wyoming, hay examen oral, pero usted debe pedirlo antes de tomar el examen.","p":"Correcto. Pida el examen oral antes de empezar."},"ref":{"doc":"WY","page":9}},{"id":"wy-066","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, you miss 13 or more questions on the test. How long must you wait to test again?","o":["One hour","24 hours","One week","Three days"],"h1":"It is longer than the wait after a smaller miss, but less than a week.","h2":"In Wyoming, an applicant who misses 13 or more questions must wait three days to be retested.","p":"Right. Missing 13 or more means a three-day wait."},"es":{"q":"En Wyoming, usted falla 13 preguntas o más en el examen. ¿Cuánto tiempo debe esperar para volver a tomarlo?","o":["Una hora","24 horas","Una semana","Tres días"],"h1":"Es más que la espera después de fallar menos, pero menos de una semana.","h2":"En Wyoming, quien falla 13 preguntas o más debe esperar tres días para volver a tomar el examen.","p":"Correcto. Fallar 13 o más significa esperar tres días."},"ref":{"doc":"WY","page":9}},{"id":"wy-067","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a driver education card can let you skip the driving skills test. How much classroom time must the course include?","o":["10 hours","30 hours","50 hours","6 hours"],"h1":"It is much more than the six hours behind the wheel.","h2":"In Wyoming, the driver education card must show 30 hours of classroom instruction and six hours of behind-the-wheel driving.","p":"Right. The course has 30 classroom hours."},"es":{"q":"En Wyoming, una tarjeta de educación vial le puede permitir saltar el examen práctico de manejo. ¿Cuántas horas de clase debe incluir el curso?","o":["10 horas","30 horas","50 horas","6 horas"],"h1":"Es mucho más que las seis horas al volante.","h2":"En Wyoming, la tarjeta de educación vial debe mostrar 30 horas de clase y seis horas de manejo al volante.","p":"Correcto. El curso tiene 30 horas de clase."},"ref":{"doc":"WY","page":9}},{"id":"wy-068","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, how long is a driver education certification card honored to waive the skills test?","o":["Six months","One year","No longer than two years","For life"],"h1":"It does not last forever.","h2":"In Wyoming, a driver education certification card is honored for no longer than two years.","p":"Right. The card is good for up to two years."},"es":{"q":"En Wyoming, ¿por cuánto tiempo se acepta una tarjeta de educación vial para saltar el examen práctico?","o":["Seis meses","Un año","No más de dos años","De por vida"],"h1":"No dura para siempre.","h2":"En Wyoming, una tarjeta de educación vial se acepta por no más de dos años.","p":"Correcto. La tarjeta sirve hasta por dos años."},"ref":{"doc":"WY","page":9}},{"id":"wy-071","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how often can you renew your license by mail instead of in person?","o":["Every time","Once every other renewal period","Never","Only after age 65"],"h1":"You must still come in some of the time.","h2":"In Wyoming, a driver may renew by mail once every other renewal period.","p":"Right. Mail renewal is allowed every other time."},"es":{"q":"En Wyoming, ¿con qué frecuencia puede renovar su licencia por correo en vez de en persona?","o":["Siempre","Una vez cada dos periodos de renovación","Nunca","Solo después de los 65 años"],"h1":"Todavía tiene que ir en persona algunas veces.","h2":"En Wyoming, un conductor puede renovar por correo una vez cada dos periodos de renovación.","p":"Correcto. Puede renovar por correo una vez sí y otra no."},"ref":{"doc":"WY","page":10}},{"id":"wy-072","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, you let your license expire. What happens when you want to drive again?","o":["You pay a late fee by mail","You get 60 extra days to drive","You apply in person and may have to take all the tests again","Nothing; it renews on its own"],"h1":"An expired license is treated almost like starting over.","h2":"In Wyoming, if your license expires, you must apply in person and may have to take the written, vision and skills tests.","p":"Right. Apply in person; you may retake all tests."},"es":{"q":"En Wyoming, usted deja vencer su licencia. ¿Qué pasa cuando quiere volver a manejar?","o":["Paga un recargo por correo","Tiene 60 días más para manejar","Solicita en persona y puede que tenga que tomar todos los exámenes otra vez","Nada; se renueva sola"],"h1":"Una licencia vencida es casi como empezar de nuevo.","h2":"En Wyoming, si su licencia vence, usted debe solicitar en persona y puede que tenga que tomar los exámenes escrito, de visión y práctico.","p":"Correcto. Solicite en persona; puede que repita todos los exámenes."},"ref":{"doc":"WY","page":10}},{"id":"wy-073","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what is the fee for an instruction permit (not counting the extra technology fee)?","o":["$40","$20","$10","$100"],"h1":"It is the same as the fee for an original license.","h2":"In Wyoming, an instruction permit costs $40, plus the $5 technology fee.","p":"Right. The instruction permit fee is $40."},"es":{"q":"En Wyoming, ¿cuánto cuesta un permiso de instrucción (sin contar el cargo extra de tecnología)?","o":["$40","$20","$10","$100"],"h1":"Es lo mismo que cuesta una licencia original.","h2":"En Wyoming, un permiso de instrucción cuesta $40, más el cargo de tecnología de $5.","p":"Correcto. El permiso de instrucción cuesta $40."},"ref":{"doc":"WY","page":11}},{"id":"wy-074","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how much is the extra technology fee added to every class of driver license?","o":["$1","$2","$10","$5"],"h1":"It is a small amount, less than ten dollars.","h2":"In Wyoming, a $5 technology fee is added to all classes of driver licenses.","p":"Right. The technology fee is $5."},"es":{"q":"En Wyoming, ¿cuánto es el cargo extra de tecnología que se suma a toda clase de licencia de manejar?","o":["$1","$2","$10","$5"],"h1":"Es poco dinero, menos de diez dólares.","h2":"En Wyoming, se suma un cargo de tecnología de $5 a toda clase de licencia de manejar.","p":"Correcto. El cargo de tecnología es $5."},"ref":{"doc":"WY","page":11}},{"id":"wy-075","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, how much does an identification (ID) card cost, according to the handbook's fee table?","o":["$5","$10","$30","$40"],"h1":"It costs much less than a driver license.","h2":"In Wyoming, an identification card costs $10.","p":"Right. An ID card costs $10."},"es":{"q":"En Wyoming, ¿cuánto cuesta una tarjeta de identificación (ID), según la tabla de tarifas del manual?","o":["$5","$10","$30","$40"],"h1":"Cuesta mucho menos que una licencia de manejar.","h2":"En Wyoming, una tarjeta de identificación cuesta $10.","p":"Correcto. La tarjeta de identificación cuesta $10."},"ref":{"doc":"WY","page":11}},{"id":"wy-076","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a 14-year-old asks for a restricted license because of a hardship at home. Living how far from school or work counts as a hardship?","o":["At least 1 mile","At least 2 miles","More than 5 miles","More than 25 miles"],"h1":"It is a distance too far to walk easily, but not a huge one.","h2":"In Wyoming, living more than five miles from school or from a regular job counts as an extreme inconvenience for a restricted hardship license.","p":"Right. More than 5 miles away counts."},"es":{"q":"En Wyoming, un joven de 14 años pide una licencia restringida por una dificultad en su casa. ¿Vivir a qué distancia de la escuela o del trabajo cuenta como dificultad?","o":["Por lo menos 1 milla","Por lo menos 2 millas","Más de 5 millas","Más de 25 millas"],"h1":"Es una distancia difícil de caminar, pero no enorme.","h2":"En Wyoming, vivir a más de cinco millas de la escuela o de un trabajo regular cuenta como una dificultad extrema para una licencia restringida.","p":"Correcto. Vivir a más de 5 millas cuenta."},"ref":{"doc":"WY","page":null}},{"id":"wy-077","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, who approves applications for a restricted hardship license for drivers aged 14 and 15?","o":["The Wyoming Highway Patrol","The school principal","The county sheriff","A judge"],"h1":"It is the state police agency that patrols highways.","h2":"In Wyoming, the Wyoming Highway Patrol approves applications for restricted licenses.","p":"Right. The Highway Patrol approves them."},"es":{"q":"En Wyoming, ¿quién aprueba las solicitudes de licencia restringida por dificultad para conductores de 14 y 15 años?","o":["La Patrulla de Carreteras de Wyoming (Highway Patrol)","El director de la escuela","El alguacil del condado","Un juez"],"h1":"Es la agencia de policía estatal que patrulla las carreteras.","h2":"En Wyoming, la Patrulla de Carreteras de Wyoming aprueba las solicitudes de licencia restringida.","p":"Correcto. La Patrulla de Carreteras las aprueba."},"ref":{"doc":"WY","page":13}},{"id":"wy-078","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, a 15-year-old with a restricted hardship license is convicted of one moving traffic violation. What happens?","o":["Nothing until the fourth violation","A warning letter is sent","The teen must retake the written test","The license is suspended"],"h1":"These licenses have very little room for mistakes.","h2":"In Wyoming, a restricted hardship license is suspended after just one moving traffic violation conviction.","p":"Right. One moving violation suspends a restricted license."},"es":{"q":"En Wyoming, un joven de 15 años con licencia restringida por dificultad es declarado culpable de una infracción de tránsito en movimiento. ¿Qué pasa?","o":["Nada hasta la cuarta infracción","Le envían una carta de advertencia","Debe repetir el examen escrito","Le suspenden la licencia"],"h1":"Estas licencias casi no permiten errores.","h2":"En Wyoming, una licencia restringida por dificultad se suspende con una sola condena por infracción de tránsito en movimiento.","p":"Correcto. Una sola infracción suspende la licencia restringida."},"ref":{"doc":"WY","page":13}},{"id":"wy-079","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, when does a restricted hardship license (issued at ages 14 to 15) expire?","o":["On the 15th birthday","30 days after the 16th birthday","On the 17th birthday","It never expires"],"h1":"It ends a short time after the age when an intermediate license is possible.","h2":"In Wyoming, a restricted hardship license expires 30 days after the holder's 16th birthday.","p":"Right. It expires 30 days after turning 16."},"es":{"q":"En Wyoming, ¿cuándo vence una licencia restringida por dificultad (dada a los 14 o 15 años)?","o":["Al cumplir 15 años","30 días después de cumplir 16 años","Al cumplir 17 años","Nunca vence"],"h1":"Termina poco después de la edad en que se puede tener una licencia intermedia.","h2":"En Wyoming, una licencia restringida por dificultad vence 30 días después de que la persona cumple 16 años.","p":"Correcto. Vence 30 días después de cumplir 16."},"ref":{"doc":"WY","page":13}},{"id":"wy-080","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a teen approved for a restricted license has no instruction permit yet, so gets a restricted instruction permit. How long is it valid?","o":["10 days","30 days","60 days","One year"],"h1":"It is about two months.","h2":"In Wyoming, a restricted instruction permit for ages 14 to 15 is valid for 60 days.","p":"Right. It is valid for 60 days."},"es":{"q":"En Wyoming, un joven aprobado para una licencia restringida todavía no tiene permiso de instrucción, así que recibe un permiso de instrucción restringido. ¿Por cuánto tiempo es válido?","o":["10 días","30 días","60 días","Un año"],"h1":"Son unos dos meses.","h2":"En Wyoming, un permiso de instrucción restringido para jóvenes de 14 y 15 años es válido por 60 días.","p":"Correcto. Es válido por 60 días."},"ref":{"doc":"WY","page":13}},{"id":"wy-081","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how long is a regular instruction permit (learner's permit) valid?","o":["One year","90 days","Six months","Two years"],"h1":"It is valid for 12 months.","h2":"In Wyoming, a regular instruction permit lets you practice driving for one year.","p":"Right. The instruction permit is good for one year."},"es":{"q":"En Wyoming, ¿por cuánto tiempo es válido un permiso de instrucción normal (permiso de aprendiz)?","o":["Un año","90 días","Seis meses","Dos años"],"h1":"Es válido por 12 meses.","h2":"En Wyoming, un permiso de instrucción normal le permite practicar a manejar durante un año.","p":"Correcto. El permiso de instrucción sirve por un año."},"ref":{"doc":"WY","page":null}},{"id":"wy-082","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, you drive with an intermediate license. Who in the car must wear a seat belt?","o":["Only you","Only people in the front seat","Only passengers under 18","Everyone in the vehicle"],"h1":"The intermediate license has a rule about every seat that is used.","h2":"In Wyoming, an intermediate license holder must make sure that everyone in the vehicle wears a seat belt.","p":"Right. Everyone in the car must be buckled."},"es":{"q":"En Wyoming, usted maneja con una licencia intermedia. ¿Quién en el carro debe usar el cinturón de seguridad?","o":["Solo usted","Solo las personas en el asiento de adelante","Solo los pasajeros menores de 18","Todas las personas en el vehículo"],"h1":"La licencia intermedia tiene una regla sobre cada asiento que se usa.","h2":"En Wyoming, quien tiene licencia intermedia debe asegurarse de que todas las personas en el vehículo usen el cinturón de seguridad.","p":"Correcto. Todos en el carro deben llevar el cinturón."},"ref":{"doc":"WY","page":14}},{"id":"wy-083","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, an intermediate license holder has a signed exception form for night driving. What must they do with it?","o":["Mail it to WYDOT each month","Carry it and show it to police if stopped","Leave it at home","Tape it to the windshield"],"h1":"An officer may ask to see it.","h2":"In Wyoming, the signed exception form must be carried by the driver and shown to law enforcement if stopped.","p":"Right. Carry the form and show it if stopped."},"es":{"q":"En Wyoming, alguien con licencia intermedia tiene un formulario de excepción firmado para manejar de noche. ¿Qué debe hacer con él?","o":["Enviarlo por correo a WYDOT cada mes","Llevarlo consigo y mostrarlo a la policía si lo detienen","Dejarlo en casa","Pegarlo en el parabrisas"],"h1":"Un policía puede pedir verlo.","h2":"En Wyoming, el formulario de excepción firmado debe llevarlo el conductor y mostrarlo a la policía si lo detienen.","p":"Correcto. Lleve el formulario y muéstrelo si lo detienen."},"ref":{"doc":"WY","page":14}},{"id":"wy-084","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, an intermediate license holder must drive home from a late school game after 11 p.m. Who signs the exception form?","o":["The coach","The school principal","A parent or legal guardian","A police officer"],"h1":"For school, sports and religious activities, a family adult certifies it.","h2":"In Wyoming, for driving to or from school, a school activity, youth sports or a religious activity, a parent or legal guardian signs the exception form.","p":"Right. A parent or legal guardian signs it."},"es":{"q":"En Wyoming, alguien con licencia intermedia debe volver a casa de un partido escolar después de las 11 p.m. ¿Quién firma el formulario de excepción?","o":["El entrenador","El director de la escuela","Su padre, madre o tutor legal","Un policía"],"h1":"Para actividades escolares, deportivas o religiosas, lo certifica un adulto de la familia.","h2":"En Wyoming, para manejar de ida o vuelta de la escuela, una actividad escolar, deportes juveniles o una actividad religiosa, el padre, la madre o el tutor legal firma el formulario de excepción.","p":"Correcto. Lo firma el padre, la madre o el tutor legal."},"ref":{"doc":"WY","page":14}},{"id":"wy-085","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, a teen has an intermediate permit for a motorcycle. How many passengers may the teen carry on the motorcycle?","o":["None","One","One family member","Two"],"h1":"The rule for motorcycles is stricter than for cars.","h2":"In Wyoming, an intermediate motorcycle permit holder may not carry any passengers.","p":"Right. No passengers are allowed."},"es":{"q":"En Wyoming, un joven tiene un permiso intermedio para motocicleta. ¿Cuántos pasajeros puede llevar en la motocicleta?","o":["Ninguno","Uno","Un familiar","Dos"],"h1":"La regla para motocicletas es más estricta que para carros.","h2":"En Wyoming, quien tiene un permiso intermedio de motocicleta no puede llevar pasajeros.","p":"Correcto. No se permiten pasajeros."},"ref":{"doc":"WY","page":14}},{"id":"wy-086","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, a teen passes the written test for a motorcycle instruction permit but has not passed the riding test. How long is that first permit valid?","o":["10 days","30 days","One year","90 days"],"h1":"It is about three months, and no passengers are allowed.","h2":"In Wyoming, a motorcycle instruction permit issued after the written test is valid for 90 days, without passengers.","p":"Right. It is valid for 90 days."},"es":{"q":"En Wyoming, un joven pasa el examen escrito para un permiso de instrucción de motocicleta, pero no ha pasado el examen de manejo. ¿Por cuánto tiempo es válido ese primer permiso?","o":["10 días","30 días","Un año","90 días"],"h1":"Son unos tres meses, y no se permiten pasajeros.","h2":"En Wyoming, un permiso de instrucción de motocicleta dado después del examen escrito es válido por 90 días, sin pasajeros.","p":"Correcto. Es válido por 90 días."},"ref":{"doc":"WY","page":null}},{"id":"wy-087","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, can police stop a car only because the intermediate permit driver has too many teen passengers?","o":["Yes, at any time","No, a car may not be stopped only for that","Only at night","Only on interstates"],"h1":"These permit rules are enforced only when the car is stopped for another reason.","h2":"In Wyoming, a vehicle may not be stopped only for breaking the intermediate permit rules on passengers or hours.","p":"Right. Police need another reason to stop the car."},"es":{"q":"En Wyoming, ¿puede la policía detener un carro solo porque el conductor con permiso intermedio lleva demasiados pasajeros jóvenes?","o":["Sí, en cualquier momento","No, no se puede detener un carro solo por eso","Solo de noche","Solo en autopistas interestatales"],"h1":"Estas reglas del permiso se hacen cumplir solo cuando el carro es detenido por otra razón.","h2":"En Wyoming, no se puede detener un vehículo solo por no cumplir las reglas del permiso intermedio sobre pasajeros u horas.","p":"Correcto. La policía necesita otra razón para detener el carro."},"ref":{"doc":"WY","page":null}},{"id":"wy-088","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, when does a regular driver license expire?","o":["Every year on January 1","On your birthday two years after it was issued","On your birthday in the fifth year after it was issued","It never expires"],"h1":"Wyoming licenses last several years and end on a date that is personal to you.","h2":"In Wyoming, a driver license expires on your birthday in the fifth year after it was issued.","p":"Right. It expires on your birthday in the fifth year."},"es":{"q":"En Wyoming, ¿cuándo vence una licencia de manejar normal?","o":["Cada año el 1 de enero","En su cumpleaños dos años después de emitida","En su cumpleaños en el quinto año después de emitida","Nunca vence"],"h1":"Las licencias de Wyoming duran varios años y terminan en una fecha que es personal para usted.","h2":"En Wyoming, una licencia de manejar vence en su cumpleaños en el quinto año después de emitida.","p":"Correcto. Vence en su cumpleaños en el quinto año."},"ref":{"doc":"WY","page":null}},{"id":"wy-089","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, how long must a physical impairment last for a person to get a permanent disabled parking placard?","o":["At least 12 months","At least 30 days","At least 6 months","At least 5 years"],"h1":"Shorter impairments get a temporary placard for up to 6 months.","h2":"In Wyoming, a permanent disabled placard is for an impairment that will last at least 12 months.","p":"Right. The impairment must last at least 12 months."},"es":{"q":"En Wyoming, ¿cuánto tiempo debe durar una discapacidad física para que una persona reciba un permiso permanente de estacionamiento para discapacitados?","o":["Por lo menos 12 meses","Por lo menos 30 días","Por lo menos 6 meses","Por lo menos 5 años"],"h1":"Las discapacidades más cortas reciben un permiso temporal de hasta 6 meses.","h2":"En Wyoming, un permiso permanente para discapacitados es para una discapacidad que durará por lo menos 12 meses.","p":"Correcto. La discapacidad debe durar por lo menos 12 meses."},"ref":{"doc":"WY","page":18}},{"id":"wy-090","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how much does a disabled parking placard cost?","o":["$5","$10","$25","Nothing; it is free"],"h1":"WYDOT does not charge for it.","h2":"In Wyoming, disabled parking placards are available at no cost.","p":"Right. Disabled placards are free."},"es":{"q":"En Wyoming, ¿cuánto cuesta un permiso de estacionamiento para discapacitados?","o":["$5","$10","$25","Nada; es gratis"],"h1":"WYDOT no cobra por él.","h2":"En Wyoming, los permisos de estacionamiento para discapacitados no tienen costo.","p":"Correcto. Los permisos para discapacitados son gratis."},"ref":{"doc":"WY","page":18}},{"id":"wy-091","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, you are arrested for DWUI with a test result of 0.08 or more. When does the 90-day administrative suspension start?","o":["Right away","30 days after the officer gives you the temporary license and notice","Only after a court conviction","One year later"],"h1":"The officer gives you a temporary license that covers a short time first.","h2":"In Wyoming, the administrative suspension starts 30 days after the officer issues the temporary license and notice of suspension.","p":"Right. It starts 30 days after the notice."},"es":{"q":"En Wyoming, lo arrestan por DWUI con un resultado de 0.08 o más. ¿Cuándo empieza la suspensión administrativa de 90 días?","o":["De inmediato","30 días después de que el policía le da la licencia temporal y el aviso","Solo después de una condena en la corte","Un año después"],"h1":"El policía primero le da una licencia temporal que cubre poco tiempo.","h2":"En Wyoming, la suspensión administrativa empieza 30 días después de que el policía da la licencia temporal y el aviso de suspensión.","p":"Correcto. Empieza 30 días después del aviso."},"ref":{"doc":"WY","page":19}},{"id":"wy-092","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, your DWUI charge is dismissed in court, but your breath test was over 0.08. What happens to the administrative suspension?","o":["It is canceled too","It is cut in half","It still stands; the court dismissal does not affect it","It turns into a warning"],"h1":"The administrative action is separate from the criminal case.","h2":"In Wyoming, dismissal of the DWUI in court does not affect the administrative per se suspension.","p":"Right. The administrative suspension still applies."},"es":{"q":"En Wyoming, la corte desecha su cargo de DWUI, pero su prueba de aliento fue de más de 0.08. ¿Qué pasa con la suspensión administrativa?","o":["También se cancela","Se reduce a la mitad","Sigue igual; la decisión de la corte no la afecta","Se convierte en una advertencia"],"h1":"La acción administrativa es aparte del caso penal.","h2":"En Wyoming, que la corte deseche el cargo de DWUI no afecta la suspensión administrativa.","p":"Correcto. La suspensión administrativa sigue en pie."},"ref":{"doc":"WY","page":19}},{"id":"wy-093","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, a driver is convicted of a second alcohol DWUI within 10 years. How long must they hold an ignition interlock license?","o":["One year","Six months","Two years","For life"],"h1":"It is longer than after a first offense and shorter than after a third.","h2":"In Wyoming, a second DWUI that involves alcohol requires an ignition interlock restricted license for one year.","p":"Right. A second DWUI means one year with an interlock."},"es":{"q":"En Wyoming, un conductor es condenado por un segundo DWUI con alcohol en 10 años. ¿Por cuánto tiempo debe tener una licencia con bloqueo de encendido (interlock)?","o":["Un año","Seis meses","Dos años","De por vida"],"h1":"Es más que después de una primera infracción y menos que después de una tercera.","h2":"En Wyoming, un segundo DWUI con alcohol requiere una licencia restringida con bloqueo de encendido por un año.","p":"Correcto. Un segundo DWUI significa un año con bloqueo de encendido."},"ref":{"doc":"WY","page":20}},{"id":"wy-094","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, a driver is convicted of a fourth DWUI that involves alcohol. How long is the ignition interlock requirement?","o":["One year","Two years","Five years","For life, though the driver may ask the court to remove it after 5 years"],"h1":"It is the strictest level, with one way to ask for relief later.","h2":"In Wyoming, a fourth DWUI with alcohol brings a lifetime ignition interlock requirement; the driver may petition the court for removal 5 years after the conviction.","p":"Right. It is for life, with a chance to petition after 5 years."},"es":{"q":"En Wyoming, un conductor es condenado por un cuarto DWUI con alcohol. ¿Cuánto dura el requisito de bloqueo de encendido?","o":["Un año","Dos años","Cinco años","De por vida, aunque puede pedir a la corte quitarlo después de 5 años"],"h1":"Es el nivel más estricto, con una forma de pedir alivio más tarde.","h2":"En Wyoming, un cuarto DWUI con alcohol trae un bloqueo de encendido de por vida; la persona puede pedir a la corte quitarlo 5 años después de la condena.","p":"Correcto. Es de por vida, con la opción de pedir a la corte después de 5 años."},"ref":{"doc":"WY","page":21}},{"id":"wy-095","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a driver under 21 is caught a second time within two years driving with 0.02 or more. How long is the suspension?","o":["90 days","Six months","One year","Three years"],"h1":"It is double the first-offense suspension.","h2":"In Wyoming, a second youthful driver offense within two years brings a six-month suspension.","p":"Right. A second offense means six months."},"es":{"q":"En Wyoming, un conductor menor de 21 años es sorprendido por segunda vez en dos años manejando con 0.02 o más. ¿Cuánto dura la suspensión?","o":["90 días","Seis meses","Un año","Tres años"],"h1":"Es el doble de la suspensión por la primera vez.","h2":"En Wyoming, una segunda infracción de conductor joven en dos años trae una suspensión de seis meses.","p":"Correcto. La segunda vez son seis meses."},"ref":{"doc":"WY","page":22}},{"id":"wy-096","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a driver is convicted of reckless driving for the first time in five years. How long is the license suspended?","o":["30 days","One year","90 days","It is not suspended"],"h1":"It is the same length as a first DWUI suspension.","h2":"In Wyoming, a first reckless driving conviction within five years brings a 90-day suspension.","p":"Right. A first reckless driving conviction means 90 days."},"es":{"q":"En Wyoming, un conductor es condenado por manejo imprudente (reckless driving) por primera vez en cinco años. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","Un año","90 días","No se suspende"],"h1":"Dura lo mismo que la suspensión por un primer DWUI.","h2":"En Wyoming, una primera condena por manejo imprudente en cinco años trae una suspensión de 90 días.","p":"Correcto. La primera condena por manejo imprudente son 90 días."},"ref":{"doc":"WY","page":22}},{"id":"wy-097","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what happens after a third reckless driving conviction within five years?","o":["The license is revoked for one year","A 30-day suspension","A warning letter","A 90-day suspension"],"h1":"A third time is treated more seriously than a suspension.","h2":"In Wyoming, a third reckless driving conviction within five years brings a one-year revocation.","p":"Right. The license is revoked for one year."},"es":{"q":"En Wyoming, ¿qué pasa después de una tercera condena por manejo imprudente en cinco años?","o":["Le revocan la licencia por un año","Una suspensión de 30 días","Una carta de advertencia","Una suspensión de 90 días"],"h1":"Una tercera vez se trata con más seriedad que una suspensión.","h2":"En Wyoming, una tercera condena por manejo imprudente en cinco años trae una revocación de un año.","p":"Correcto. Le revocan la licencia por un año."},"ref":{"doc":"WY","page":23}},{"id":"wy-098","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, an adult is convicted of carrying alcohol in a car to give to someone under 21. How long is the license suspended?","o":["30 days","90 days","Six months","One year"],"h1":"It is a long suspension.","h2":"In Wyoming, a conviction for transporting liquor to a minor brings a one-year license suspension.","p":"Right. The suspension is one year."},"es":{"q":"En Wyoming, un adulto es condenado por llevar alcohol en un carro para dárselo a alguien menor de 21 años. ¿Por cuánto tiempo se suspende la licencia?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Es una suspensión larga.","h2":"En Wyoming, una condena por transportar alcohol para un menor trae una suspensión de licencia de un año.","p":"Correcto. La suspensión es de un año."},"ref":{"doc":"WY","page":23}},{"id":"wy-099","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, you get a fourth moving violation within 12 months. How long is your license suspended?","o":["30 days","90 days","Six months","One year"],"h1":"Each extra violation in the same 12 months adds the same amount again.","h2":"In Wyoming, a suspension for too many moving violations lasts 90 days, and each further violation in the 12 months adds another 90 days.","p":"Right. The suspension is 90 days."},"es":{"q":"En Wyoming, usted recibe una cuarta infracción en movimiento en 12 meses. ¿Por cuánto tiempo se suspende su licencia?","o":["30 días","90 días","Seis meses","Un año"],"h1":"Cada infracción extra en los mismos 12 meses suma la misma cantidad otra vez.","h2":"En Wyoming, la suspensión por demasiadas infracciones en movimiento dura 90 días, y cada infracción adicional en los 12 meses suma otros 90 días.","p":"Correcto. La suspensión es de 90 días."},"ref":{"doc":"WY","page":24}},{"id":"wy-100","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a court convicts you of driving without liability insurance. How long does the suspension last?","o":["30 days","One year","Until an SR-22 insurance form is filed","Until you pay a $10 fee"],"h1":"It ends when you prove you have insurance.","h2":"In Wyoming, a compulsory insurance suspension lasts until an SR-22 insurance form has been filed with the department.","p":"Right. It lasts until the SR-22 is filed."},"es":{"q":"En Wyoming, una corte lo condena por manejar sin seguro de responsabilidad civil. ¿Cuánto dura la suspensión?","o":["30 días","Un año","Hasta que se presente el formulario de seguro SR-22","Hasta que pague $10"],"h1":"Termina cuando usted prueba que tiene seguro.","h2":"En Wyoming, la suspensión por falta de seguro obligatorio dura hasta que se presente el formulario de seguro SR-22 ante el departamento.","p":"Correcto. Dura hasta que se presente el SR-22."},"ref":{"doc":"WY","page":25}},{"id":"wy-101","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, you lend your driver license to a friend to use as ID. What can happen to you?","o":["Nothing, if the friend gives it back","A $10 fine only","You must retake the vision test","Your license can be canceled or suspended for 90 days"],"h1":"Lending a license is treated as unlawful use.","h2":"In Wyoming, lending your license for someone else to use can lead to cancellation and a 90-day suspension.","p":"Right. It can mean cancellation or a 90-day suspension."},"es":{"q":"En Wyoming, usted le presta su licencia de manejar a un amigo para que la use como identificación. ¿Qué le puede pasar?","o":["Nada, si el amigo se la devuelve","Solo una multa de $10","Debe repetir la prueba de visión","Le pueden cancelar la licencia o suspenderla por 90 días"],"h1":"Prestar una licencia se considera uso ilegal.","h2":"En Wyoming, prestar su licencia para que otra persona la use puede causar la cancelación y una suspensión de 90 días.","p":"Correcto. Puede significar cancelación o una suspensión de 90 días."},"ref":{"doc":"WY","page":25}},{"id":"wy-102","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, a parent is behind on child support. When can the state suspend the parent's driver license without a court order?","o":["After missing one payment","When more than $2,500 is owed and no full monthly payment has been made for 90 days in a row","When $500 is owed for 30 days","Never; licenses are not linked to child support"],"h1":"Both a dollar amount and a length of time must be reached.","h2":"In Wyoming, a license can be suspended without a court order when a parent owes more than $2,500 in child support and has made no full monthly payment for 90 consecutive days.","p":"Right. It is more than $2,500 owed and no full payment for 90 days in a row."},"es":{"q":"En Wyoming, un padre está atrasado con la manutención de sus hijos. ¿Cuándo puede el estado suspenderle la licencia de conducir sin una orden de la corte?","o":["Después de no hacer un solo pago","Cuando debe más de $2,500 y no ha hecho un pago mensual completo durante 90 días seguidos","Cuando debe $500 durante 30 días","Nunca; la licencia no tiene relación con la manutención"],"h1":"Se debe llegar a una cantidad de dinero y a un tiempo.","h2":"En Wyoming, se puede suspender una licencia sin orden de la corte cuando un padre debe más de $2,500 de manutención y no ha hecho un pago mensual completo durante 90 días seguidos.","p":"Correcto. Son más de $2,500 y ningún pago completo durante 90 días seguidos."},"ref":{"doc":"WY","page":null}},{"id":"wy-103","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, a driver under 21 is caught driving while the license is already suspended. What extra penalty does WYDOT add?","o":["A 30-day suspension","A one-year revocation","A $5 fee","Nothing extra"],"h1":"It is the same length as an intermediate license suspension.","h2":"In Wyoming, driving under suspension, revocation or cancellation brings a 30-day suspension for a driver under 21.","p":"Right. It adds a 30-day suspension."},"es":{"q":"En Wyoming, un conductor menor de 21 años es sorprendido manejando con la licencia ya suspendida. ¿Qué castigo extra agrega WYDOT?","o":["Una suspensión de 30 días","Una revocación de un año","Un cargo de $5","Nada extra"],"h1":"Dura lo mismo que la suspensión de una licencia intermedia.","h2":"En Wyoming, manejar con la licencia suspendida, revocada o cancelada trae una suspensión de 30 días para un conductor menor de 21 años.","p":"Correcto. Agrega una suspensión de 30 días."},"ref":{"doc":"WY","page":26}},{"id":"wy-104","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a driver with a restricted RC license is convicted of a second moving violation. How long is the suspension?","o":["30 days","90 days","One year","Six months"],"h1":"The first offense brings 90 days; the second is longer.","h2":"In Wyoming, a second moving violation on a restricted RC license brings a one-year suspension.","p":"Right. A second violation means one year."},"es":{"q":"En Wyoming, un conductor con licencia restringida RC es condenado por una segunda infracción en movimiento. ¿Cuánto dura la suspensión?","o":["30 días","90 días","Un año","Seis meses"],"h1":"La primera vez son 90 días; la segunda es más larga.","h2":"En Wyoming, una segunda infracción en movimiento con licencia restringida RC trae una suspensión de un año.","p":"Correcto. La segunda infracción significa un año."},"ref":{"doc":"WY","page":26}},{"id":"wy-105","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, you get a suspension notice and want a contested case hearing. How soon must your written request be postmarked?","o":["Within 5 days","Within 20 days","Within 60 days","Within one year"],"h1":"It is about three weeks.","h2":"In Wyoming, a request for a contested case hearing or a record review must be postmarked within 20 days of the notice.","p":"Right. It must be postmarked within 20 days."},"es":{"q":"En Wyoming, usted recibe un aviso de suspensión y quiere una audiencia para impugnarla. ¿En qué plazo debe tener matasellos su solicitud por escrito?","o":["Dentro de 5 días","Dentro de 20 días","Dentro de 60 días","Dentro de un año"],"h1":"Son unas tres semanas.","h2":"En Wyoming, la solicitud de una audiencia o de una revisión del expediente debe tener matasellos dentro de los 20 días del aviso.","p":"Correcto. Debe tener matasellos dentro de 20 días."},"ref":{"doc":"WY","page":27}},{"id":"wy-106","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, how many probationary licenses (limited driving privileges during a suspension) can you get in a five-year period?","o":["As many as you need","Three","Two","Only one"],"h1":"It is a one-time help within that period.","h2":"In Wyoming, you can be issued only one probationary driver license in a five-year period.","p":"Right. Only one in five years."},"es":{"q":"En Wyoming, ¿cuántas licencias probatorias (permiso limitado para manejar durante una suspensión) puede recibir en un periodo de cinco años?","o":["Todas las que necesite","Tres","Dos","Solo una"],"h1":"Es una ayuda de una sola vez en ese periodo.","h2":"En Wyoming, usted puede recibir solo una licencia probatoria en un periodo de cinco años.","p":"Correcto. Solo una en cinco años."},"ref":{"doc":"WY","page":27}},{"id":"wy-107","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, what is the usual fee to reinstate a license after a suspension?","o":["$50","$5","$15","$100"],"h1":"A child support suspension has a much smaller fee than this.","h2":"In Wyoming, the reinstatement fee for most suspensions is $50.","p":"Right. The usual reinstatement fee is $50."},"es":{"q":"En Wyoming, ¿cuál es el cargo normal para reactivar una licencia después de una suspensión?","o":["$50","$5","$15","$100"],"h1":"Una suspensión por manutención tiene un cargo mucho menor.","h2":"En Wyoming, el cargo de reactivación para la mayoría de las suspensiones es $50.","p":"Correcto. El cargo normal de reactivación es $50."},"ref":{"doc":"WY","page":27}},{"id":"wy-108","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, which of these offenses causes a license revocation?","o":["A first speeding ticket","Not wearing a seat belt","Leaving the scene of a crash where someone was hurt","Parking near a fire hydrant"],"h1":"Revocation is for the most serious offenses.","h2":"In Wyoming, leaving the scene of an injury crash is one of the offenses that causes a revocation.","p":"Right. Leaving an injury crash scene causes a revocation."},"es":{"q":"En Wyoming, ¿cuál de estas infracciones causa la revocación de la licencia?","o":["Una primera multa por exceso de velocidad","No usar el cinturón de seguridad","Irse del lugar de un choque donde alguien resultó herido","Estacionarse cerca de un hidrante"],"h1":"La revocación es para las infracciones más graves.","h2":"En Wyoming, irse del lugar de un choque con heridos es una de las infracciones que causan la revocación.","p":"Correcto. Irse de un choque con heridos causa la revocación."},"ref":{"doc":"WY","page":27}},{"id":"wy-109","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, WYDOT gives you notice that it will suspend your license, and you do not ask for a hearing. When does the suspension usually start?","o":["The day the notice is given","20 days after the notice is given","One year later","When you choose"],"h1":"You get a short time to ask for a hearing before it begins.","h2":"In Wyoming, a suspension or revocation usually starts 20 days after WYDOT gives notice, or later if a hearing is requested or an earlier suspension is still running.","p":"Right. It usually starts 20 days after the notice."},"es":{"q":"En Wyoming, WYDOT le avisa que va a suspender su licencia y usted no pide una audiencia. ¿Cuándo empieza normalmente la suspensión?","o":["El día en que le dan el aviso","20 días después de que le dan el aviso","Un año después","Cuando usted decida"],"h1":"Usted tiene poco tiempo para pedir una audiencia antes de que empiece.","h2":"En Wyoming, una suspensión o revocación normalmente empieza 20 días después de que WYDOT da el aviso, o más tarde si se pide una audiencia o si sigue vigente una suspensión anterior.","p":"Correcto. Normalmente empieza 20 días después del aviso."},"ref":{"doc":"WY","page":null}},{"id":"wy-110","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, a driver must get an ignition interlock license. Besides the $50 reinstatement fee, what other fee does WYDOT charge?","o":["$5","$25","$50","A $100 ignition interlock fee"],"h1":"It is double the reinstatement fee.","h2":"In Wyoming, a driver who needs an ignition interlock must pay a $100 ignition interlock fee as well as the $50 reinstatement fee.","p":"Right. The ignition interlock fee is $100."},"es":{"q":"En Wyoming, un conductor debe sacar una licencia con bloqueo de encendido. Además del cargo de reactivación de $50, ¿qué otro cargo cobra WYDOT?","o":["$5","$25","$50","Un cargo de $100 por bloqueo de encendido"],"h1":"Es el doble del cargo de reactivación.","h2":"En Wyoming, un conductor que necesita bloqueo de encendido debe pagar un cargo de $100 por el bloqueo, además del cargo de reactivación de $50.","p":"Correcto. El cargo por bloqueo de encendido es $100."},"ref":{"doc":"WY","page":29}},{"id":"wy-111","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, who pays to install an ignition interlock device after a DWUI?","o":["The driver","The state","The county","The insurance company"],"h1":"It is part of the cost of the offense.","h2":"In Wyoming, an ignition interlock device is installed at the driver's own expense.","p":"Right. The driver pays for it."},"es":{"q":"En Wyoming, ¿quién paga la instalación de un bloqueo de encendido después de un DWUI?","o":["El conductor","El estado","El condado","La compañía de seguros"],"h1":"Es parte del costo de la infracción.","h2":"En Wyoming, el bloqueo de encendido se instala a cargo del propio conductor.","p":"Correcto. El conductor lo paga."},"ref":{"doc":"WY","page":28}},{"id":"wy-112","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, a court orders a DWUI offender into the 24/7 Sobriety Program instead of an ignition interlock. What license may the driver ask for?","o":["A commercial license","A motorcycle license","A 24/7 restricted driver license","An intermediate license"],"h1":"The license is named after the program.","h2":"In Wyoming, a driver ordered into the 24/7 Sobriety Program instead of an interlock may apply for a 24/7 restricted driver license.","p":"Right. They may apply for a 24/7 restricted license."},"es":{"q":"En Wyoming, una corte ordena a una persona condenada por DWUI entrar al programa de sobriedad 24/7 en vez del bloqueo de encendido. ¿Qué licencia puede pedir?","o":["Una licencia comercial","Una licencia de motocicleta","Una licencia restringida 24/7","Una licencia intermedia"],"h1":"La licencia lleva el nombre del programa.","h2":"En Wyoming, una persona enviada al programa de sobriedad 24/7 en vez del bloqueo de encendido puede pedir una licencia restringida 24/7.","p":"Correcto. Puede pedir una licencia restringida 24/7."},"ref":{"doc":"WY","page":29}},{"id":"wy-113","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a passenger in your car is not wearing a seat belt. Whose responsibility is it?","o":["Only the passenger's","The driver's","The car owner's, if not driving","No one's, if the passenger is an adult"],"h1":"The person behind the wheel is in charge.","h2":"In Wyoming, all occupants must wear seat belts, and it is the driver's responsibility to see that the law is obeyed.","p":"Right. The driver is responsible."},"es":{"q":"En Wyoming, un pasajero en su carro no lleva el cinturón de seguridad. ¿De quién es la responsabilidad?","o":["Solo del pasajero","Del conductor","Del dueño del carro, si no maneja","De nadie, si el pasajero es adulto"],"h1":"La persona al volante es la que manda.","h2":"En Wyoming, todos los ocupantes deben usar el cinturón, y es responsabilidad del conductor que se cumpla la ley.","p":"Correcto. El conductor es el responsable."},"ref":{"doc":"WY","page":29}},{"id":"wy-114","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, can a police officer stop your car only because someone is not wearing a seat belt?","o":["Yes, at any time","Only on interstates","Only at night","No, a car may not be stopped only for that"],"h1":"For adults, the seat belt law is enforced only when the car is stopped for another reason.","h2":"In Wyoming, a motor vehicle may not be stopped only for a seat belt violation.","p":"Right. Police need another reason to stop the car."},"es":{"q":"En Wyoming, ¿puede un policía detener su carro solo porque alguien no lleva el cinturón de seguridad?","o":["Sí, en cualquier momento","Solo en autopistas interestatales","Solo de noche","No, no se puede detener un carro solo por eso"],"h1":"Para adultos, la ley del cinturón se hace cumplir solo cuando el carro es detenido por otra razón.","h2":"En Wyoming, no se puede detener un vehículo solo por una infracción del cinturón de seguridad.","p":"Correcto. La policía necesita otra razón para detener el carro."},"ref":{"doc":"WY","page":null}},{"id":"wy-115","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, what is the most a driver can be fined for not wearing a seat belt?","o":["$10","$25","$100","$500"],"h1":"A passenger's top fine is $10; the driver's is a bit higher.","h2":"In Wyoming, a driver who does not wear a seat belt may be fined up to $25, and a passenger up to $10.","p":"Right. The driver's fine is up to $25."},"es":{"q":"En Wyoming, ¿cuál es la multa más alta para un conductor que no usa el cinturón de seguridad?","o":["$10","$25","$100","$500"],"h1":"La multa más alta de un pasajero es $10; la del conductor es un poco más.","h2":"En Wyoming, un conductor que no usa el cinturón puede recibir una multa de hasta $25, y un pasajero de hasta $10.","p":"Correcto. La multa del conductor es de hasta $25."},"ref":{"doc":"WY","page":null}},{"id":"wy-116","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, you get a ticket for another traffic offense, but everyone in your car was wearing a seat belt. What happens to your fine?","o":["It doubles","Nothing changes","It is lowered by $10","It is canceled"],"h1":"Wyoming rewards buckling up.","h2":"In Wyoming, a driver whose car complied with the seat belt law gets a $10 reduction on the fine for another traffic offense.","p":"Right. The fine is lowered by $10."},"es":{"q":"En Wyoming, usted recibe una multa por otra infracción de tránsito, pero todos en su carro llevaban el cinturón de seguridad. ¿Qué pasa con su multa?","o":["Se duplica","No cambia","Se reduce $10","Se cancela"],"h1":"Wyoming premia el uso del cinturón.","h2":"En Wyoming, un conductor cuyo carro cumplía la ley del cinturón recibe una reducción de $10 en la multa por otra infracción de tránsito.","p":"Correcto. La multa se reduce $10."},"ref":{"doc":"WY","page":null}},{"id":"wy-117","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, what is the most you can be fined for a first child safety seat violation?","o":["$50","$25","$200","$500"],"h1":"The second-offense fine is higher, at $100.","h2":"In Wyoming, the first child restraint offense has a maximum fine of $50.","p":"Right. The first offense fine is up to $50."},"es":{"q":"En Wyoming, ¿cuál es la multa más alta por una primera infracción de asiento de seguridad para niños?","o":["$50","$25","$200","$500"],"h1":"La multa por segunda vez es más alta, $100.","h2":"En Wyoming, la primera infracción de asiento de seguridad para niños tiene una multa máxima de $50.","p":"Correcto. La primera multa es de hasta $50."},"ref":{"doc":"WY","page":null}},{"id":"wy-118","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, you get a first ticket for not using a child safety seat. How can you get the fine waived?","o":["Pay it within 7 days","Take a driving class","Write a letter to the judge","Show the court proof that you got an approved child seat after the ticket"],"h1":"The goal is to get the child into a proper seat.","h2":"In Wyoming, the court waives the first child restraint fine when you show proof that you bought, leased or got an approved restraint after the offense.","p":"Right. Proof of getting an approved seat waives the fine."},"es":{"q":"En Wyoming, usted recibe una primera multa por no usar un asiento de seguridad para niños. ¿Cómo puede lograr que se la perdonen?","o":["Pagarla en 7 días","Tomar una clase de manejo","Escribir una carta al juez","Mostrar a la corte prueba de que consiguió un asiento aprobado después de la multa"],"h1":"La meta es que el niño viaje en un asiento adecuado.","h2":"En Wyoming, la corte perdona la primera multa de asiento para niños cuando usted muestra prueba de que compró, rentó o consiguió un asiento aprobado después de la infracción.","p":"Correcto. La prueba de un asiento aprobado perdona la multa."},"ref":{"doc":"WY","page":30}},{"id":"wy-119","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, can police stop a car just because a young child is not in a proper child safety seat?","o":["No, never","Only if there is also speeding","Yes, it is a primary offense","Only on school days"],"h1":"The child seat law is enforced differently from the adult seat belt law.","h2":"In Wyoming, a child restraint violation is a primary offense, so it is a reason by itself for police to stop the vehicle.","p":"Right. It is a primary offense."},"es":{"q":"En Wyoming, ¿puede la policía detener un carro solo porque un niño pequeño no va en un asiento de seguridad adecuado?","o":["No, nunca","Solo si también hay exceso de velocidad","Sí, es una infracción primaria","Solo en días de escuela"],"h1":"La ley del asiento para niños se aplica distinto a la ley del cinturón para adultos.","h2":"En Wyoming, no usar el asiento para niños es una infracción primaria, así que es razón suficiente para que la policía detenga el vehículo.","p":"Correcto. Es una infracción primaria."},"ref":{"doc":"WY","page":30}},{"id":"wy-120","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming's child seat guide, a belt-positioning booster seat gives protection to a child over what weight?","o":["20 pounds","40 pounds","80 pounds","100 pounds"],"h1":"Smaller children need a car seat with its own harness.","h2":"In Wyoming, the child restraint guide says a belt-positioning booster protects a child over 40 pounds.","p":"Right. Boosters are for children over 40 pounds."},"es":{"q":"En la guía de asientos para niños de Wyoming, un asiento elevado (booster) protege a un niño de más de ¿qué peso?","o":["20 libras","40 libras","80 libras","100 libras"],"h1":"Los niños más pequeños necesitan un asiento con su propio arnés.","h2":"En Wyoming, la guía de asientos para niños dice que un asiento elevado protege a un niño de más de 40 libras.","p":"Correcto. Los asientos elevados son para niños de más de 40 libras."},"ref":{"doc":"WY","page":31}},{"id":"wy-121","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming's guide, which sign shows that a child fits an adult seat belt without a booster?","o":["Knees bend over the edge of the seat and feet stay flat on the floor","The child can reach the radio","The shoulder belt crosses the neck","The child is taller than the headrest"],"h1":"Look at how the child sits all the way back on the seat.","h2":"In Wyoming, a child fits the seat belt when the back is against the seat, the knees bend over the edge, and the feet stay flat on the floor for the whole trip.","p":"Right. Knees bend at the seat edge and feet are flat."},"es":{"q":"En la guía de Wyoming, ¿qué muestra que un niño ya puede usar el cinturón de adulto sin asiento elevado?","o":["Las rodillas se doblan en el borde del asiento y los pies quedan planos en el piso","El niño alcanza la radio","El cinturón del hombro cruza el cuello","El niño es más alto que la cabecera"],"h1":"Fíjese en cómo se sienta el niño bien atrás en el asiento.","h2":"En Wyoming, un niño cabe en el cinturón cuando la espalda toca el asiento, las rodillas se doblan en el borde y los pies quedan planos en el piso todo el viaje.","p":"Correcto. Las rodillas se doblan en el borde y los pies quedan planos."},"ref":{"doc":"WY","page":31}},{"id":"wy-122","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, which of these people does not have to wear a seat belt?","o":["A teen passenger in the back seat","A driver going only a few blocks","A passenger on an interstate","A U.S. postal carrier while delivering mail"],"h1":"The exception is for a certain job while doing that job.","h2":"In Wyoming, a U.S. postal service carrier performing mail delivery duties does not have to wear a seat belt.","p":"Right. Postal carriers on duty are exempt."},"es":{"q":"En Wyoming, ¿cuál de estas personas no tiene que usar el cinturón de seguridad?","o":["Un pasajero adolescente en el asiento de atrás","Un conductor que va solo unas cuadras","Un pasajero en una autopista interestatal","Un cartero del servicio postal de EE. UU. mientras reparte correo"],"h1":"La excepción es para cierto trabajo mientras se hace ese trabajo.","h2":"En Wyoming, un cartero del servicio postal de EE. UU. que está repartiendo correo no tiene que usar el cinturón de seguridad.","p":"Correcto. Los carteros en servicio están exentos."},"ref":{"doc":"WY","page":32}},{"id":"wy-123","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, what is the main idea of the Driver License Compact that Wyoming belongs to?","o":["Free licenses for students","Lower insurance rates","One license and one driving record for each driver","A single national speed limit"],"h1":"States share information so a driver cannot hide a bad record.","h2":"In Wyoming, the Driver License Compact follows a one license, one record idea, so states share driving records.","p":"Right. One license, one record."},"es":{"q":"En Wyoming, ¿cuál es la idea principal del Pacto de Licencias de Conducir (Driver License Compact) al que pertenece Wyoming?","o":["Licencias gratis para estudiantes","Seguros más baratos","Una licencia y un historial de manejo por conductor","Un solo límite de velocidad nacional"],"h1":"Los estados comparten información para que nadie esconda un mal historial.","h2":"En Wyoming, el Pacto de Licencias de Conducir sigue la idea de una licencia y un historial, así que los estados comparten los historiales de manejo.","p":"Correcto. Una licencia, un historial."},"ref":{"doc":"WY","page":33}},{"id":"wy-124","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Wyoming handbook, how long does it take the body to fully absorb the alcohol in one drink?","o":["5 to 10 minutes","30 to 40 minutes","About 3 hours","About 8 hours"],"h1":"It is less than an hour.","h2":"In Wyoming, the handbook says it takes 30 to 40 minutes to fully absorb the alcohol in a single drink.","p":"Right. It takes 30 to 40 minutes."},"es":{"q":"Según el manual de Wyoming, ¿cuánto tarda el cuerpo en absorber por completo el alcohol de una bebida?","o":["De 5 a 10 minutos","De 30 a 40 minutos","Unas 3 horas","Unas 8 horas"],"h1":"Es menos de una hora.","h2":"En Wyoming, el manual dice que el cuerpo tarda de 30 a 40 minutos en absorber por completo el alcohol de una bebida.","p":"Correcto. Tarda de 30 a 40 minutos."},"ref":{"doc":"WY","page":34}},{"id":"wy-125","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Wyoming handbook, about how fast does the liver remove alcohol from the body?","o":["About one drink per hour","About one drink every 10 minutes","About three drinks per hour","It depends on how much coffee you drink"],"h1":"The rate is about the same for everyone and cannot be sped up.","h2":"In Wyoming, the handbook says the liver removes alcohol at about one drink per hour, and nothing makes it faster.","p":"Right. About one drink per hour."},"es":{"q":"Según el manual de Wyoming, ¿más o menos a qué velocidad elimina el hígado el alcohol del cuerpo?","o":["Más o menos una bebida por hora","Más o menos una bebida cada 10 minutos","Más o menos tres bebidas por hora","Depende de cuánto café tome"],"h1":"La velocidad es casi igual para todos y no se puede acelerar.","h2":"En Wyoming, el manual dice que el hígado elimina el alcohol a más o menos una bebida por hora, y nada lo hace más rápido.","p":"Correcto. Más o menos una bebida por hora."},"ref":{"doc":"WY","page":34}},{"id":"wy-126","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"According to the Wyoming handbook, a drinking driver going 55 mph reacts more slowly. About how much farther does the car go before the brakes are applied?","o":["3 feet","10 feet","100 feet","32 feet or more"],"h1":"The extra delay is about two-fifths of a second.","h2":"In Wyoming, the handbook says a drinking driver at 55 mph travels an extra 32 feet or more before braking.","p":"Right. About 32 feet or more."},"es":{"q":"Según el manual de Wyoming, un conductor que ha bebido y va a 55 mph reacciona más lento. ¿Cuánto más avanza el carro antes de frenar?","o":["3 pies","10 pies","100 pies","32 pies o más"],"h1":"El retraso extra es de unas dos quintas partes de segundo.","h2":"En Wyoming, el manual dice que un conductor que ha bebido, a 55 mph, avanza 32 pies o más antes de frenar.","p":"Correcto. Unos 32 pies o más."},"ref":{"doc":"WY","page":36}},{"id":"wy-127","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"According to the Wyoming handbook, alcohol is one of the most dangerous combinations when mixed with which feeling?","o":["Boredom","Anger","Hunger","Happiness"],"h1":"It is a strong emotion that already makes self-control hard.","h2":"In Wyoming, the handbook says anger and alcohol together are one of the most dangerous combinations.","p":"Right. Anger and alcohol are a dangerous mix."},"es":{"q":"Según el manual de Wyoming, el alcohol es una de las combinaciones más peligrosas cuando se mezcla con ¿qué sentimiento?","o":["Aburrimiento","Enojo","Hambre","Alegría"],"h1":"Es una emoción fuerte que ya hace difícil controlarse.","h2":"En Wyoming, el manual dice que el enojo y el alcohol juntos son una de las combinaciones más peligrosas.","p":"Correcto. El enojo y el alcohol son una mezcla peligrosa."},"ref":{"doc":"WY","page":36}},{"id":"wy-128","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, you are arrested for DWUI and refuse the chemical test. What may the officer do?","o":["Nothing; the case ends","Let you go home","Get a warrant to require the test","Give you a parking ticket"],"h1":"A judge can order the test.","h2":"In Wyoming, if you refuse the test, law enforcement may get a warrant to require the test.","p":"Right. The officer may get a warrant."},"es":{"q":"En Wyoming, lo arrestan por DWUI y usted se niega a la prueba química. ¿Qué puede hacer el policía?","o":["Nada; el caso termina","Dejarlo ir a casa","Conseguir una orden judicial para exigir la prueba","Darle una multa de estacionamiento"],"h1":"Un juez puede ordenar la prueba.","h2":"En Wyoming, si usted se niega a la prueba, la policía puede conseguir una orden judicial para exigirla.","p":"Correcto. El policía puede conseguir una orden judicial."},"ref":{"doc":"WY","page":37}},{"id":"wy-129","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, what is the longest jail term for a first DWUI conviction (without a child passenger)?","o":["Six months","30 days","Two years","Five years"],"h1":"It is half a year.","h2":"In Wyoming, a first DWUI conviction can bring up to six months in jail, a fine of up to $750, or both.","p":"Right. Up to six months in jail."},"es":{"q":"En Wyoming, ¿cuál es la pena de cárcel más larga por una primera condena de DWUI (sin un niño de pasajero)?","o":["Seis meses","30 días","Dos años","Cinco años"],"h1":"Es medio año.","h2":"En Wyoming, una primera condena de DWUI puede traer hasta seis meses de cárcel, una multa de hasta $750, o ambas.","p":"Correcto. Hasta seis meses de cárcel."},"ref":{"doc":"WY","page":null}},{"id":"wy-130","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, a driver is convicted of a second DWUI within 10 years. What is the shortest time they must spend in jail?","o":["No jail time","One day","30 days","Seven days"],"h1":"It is about one week.","h2":"In Wyoming, a second DWUI conviction within 10 years brings at least seven days in jail.","p":"Right. At least seven days in jail."},"es":{"q":"En Wyoming, un conductor es condenado por un segundo DWUI en 10 años. ¿Cuál es el tiempo mínimo que debe pasar en la cárcel?","o":["Nada de cárcel","Un día","30 días","Siete días"],"h1":"Es más o menos una semana.","h2":"En Wyoming, una segunda condena de DWUI en 10 años trae por lo menos siete días de cárcel.","p":"Correcto. Por lo menos siete días de cárcel."},"ref":{"doc":"WY","page":null}},{"id":"wy-131","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, an adult drives under the influence with a child passenger in the car. What is the longest jail term for a first conviction?","o":["30 days","One year","Six months","Ten years"],"h1":"It is longer than for a DWUI with no child in the car.","h2":"In Wyoming, an adult convicted of DWUI with a child passenger faces up to one year in jail for a first conviction.","p":"Right. Up to one year in jail."},"es":{"q":"En Wyoming, un adulto maneja bajo los efectos del alcohol con un niño de pasajero. ¿Cuál es la pena de cárcel más larga por una primera condena?","o":["30 días","Un año","Seis meses","Diez años"],"h1":"Es más largo que por un DWUI sin un niño en el carro.","h2":"En Wyoming, un adulto condenado por DWUI con un niño de pasajero puede recibir hasta un año de cárcel por una primera condena.","p":"Correcto. Hasta un año de cárcel."},"ref":{"doc":"WY","page":null}},{"id":"wy-132","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, what is the highest fine for a driver under 21 convicted of driving with 0.02 or more alcohol?","o":["$50","$200","$750","$5,000"],"h1":"It is the same top fine as a first adult DWUI.","h2":"In Wyoming, a driver under 21 convicted of driving with 0.02 or more can be fined up to $750.","p":"Right. The fine can be up to $750."},"es":{"q":"En Wyoming, ¿cuál es la multa más alta para un conductor menor de 21 años condenado por manejar con 0.02 o más de alcohol?","o":["$50","$200","$750","$5,000"],"h1":"Es la misma multa máxima que un primer DWUI de adulto.","h2":"En Wyoming, un conductor menor de 21 años condenado por manejar con 0.02 o más puede recibir una multa de hasta $750.","p":"Correcto. La multa puede ser de hasta $750."},"ref":{"doc":"WY","page":null}},{"id":"wy-133","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, your passenger has an open can of beer in the car while you drive on a highway. What is the highest fine for a first conviction?","o":["$200","$25","$1,000","There is no fine"],"h1":"Later convictions within a year cost more.","h2":"In Wyoming, a first open container conviction can bring a fine of up to $200.","p":"Right. Up to $200 for a first conviction."},"es":{"q":"En Wyoming, su pasajero tiene una lata de cerveza abierta en el carro mientras usted maneja en una carretera. ¿Cuál es la multa más alta por una primera condena?","o":["$200","$25","$1,000","No hay multa"],"h1":"Las condenas siguientes en el mismo año cuestan más.","h2":"En Wyoming, una primera condena por envase abierto puede traer una multa de hasta $200.","p":"Correcto. Hasta $200 por una primera condena."},"ref":{"doc":"WY","page":null}},{"id":"wy-134","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, where in a car may you legally carry an opened bottle of alcohol while driving?","o":["In the cup holder","Under the driver's seat","In the glove box","In the trunk"],"h1":"It must be out of reach of everyone in the car.","h2":"In Wyoming, an open alcoholic beverage may be carried in the trunk or another outside compartment that no one can reach while driving.","p":"Right. In the trunk, out of reach."},"es":{"q":"En Wyoming, ¿dónde en el carro puede llevar legalmente una botella de alcohol abierta mientras maneja?","o":["En el portavasos","Debajo del asiento del conductor","En la guantera","En la cajuela (maletero)"],"h1":"Debe estar fuera del alcance de todos en el carro.","h2":"En Wyoming, una bebida alcohólica abierta se puede llevar en la cajuela u otro compartimiento exterior que nadie pueda alcanzar mientras se maneja.","p":"Correcto. En la cajuela, fuera del alcance."},"ref":{"doc":"WY","page":null}},{"id":"wy-135","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, a police officer signals you to pull over. Where should you not stop?","o":["On the right shoulder","On a bridge or against a guardrail","In a wide, safe spot","Off the road to the right"],"h1":"Pick a place that is safe for both you and the officer.","h2":"In Wyoming, when stopped by police, pull to the right in a safe place and do not stop in the travel lane, on bridges or against guardrails.","p":"Right. Do not stop on a bridge or against a guardrail."},"es":{"q":"En Wyoming, un policía le hace señal para que se orille. ¿Dónde no debe detenerse?","o":["En el acotamiento derecho","En un puente o pegado a una barrera de contención","En un lugar amplio y seguro","Fuera del camino a la derecha"],"h1":"Elija un lugar seguro para usted y para el policía.","h2":"En Wyoming, cuando la policía lo detiene, oríllese a la derecha en un lugar seguro y no se detenga en el carril, en puentes ni pegado a barreras de contención.","p":"Correcto. No se detenga en un puente ni junto a una barrera."},"ref":{"doc":"WY","page":39}},{"id":"wy-136","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, you are pulled over by police at night. What should you do inside the car?","o":["Get out and walk to the police car","Search for your papers right away","Turn on the interior light and keep your hands on the wheel","Turn off your headlights and lock the doors"],"h1":"Help the officer see you and your hands.","h2":"In Wyoming, if you are stopped at night, turn on the interior light and keep your hands on the steering wheel.","p":"Right. Interior light on, hands on the wheel."},"es":{"q":"En Wyoming, la policía lo detiene de noche. ¿Qué debe hacer dentro del carro?","o":["Bajarse y caminar a la patrulla","Buscar sus papeles de inmediato","Prender la luz interior y mantener las manos en el volante","Apagar las luces delanteras y cerrar las puertas con seguro"],"h1":"Ayude al policía a verle a usted y sus manos.","h2":"En Wyoming, si lo detienen de noche, prenda la luz interior y mantenga las manos en el volante.","p":"Correcto. Luz interior prendida y manos en el volante."},"ref":{"doc":"WY","page":39}},{"id":"wy-137","scope":"WY","cat":"licensing","sign":null,"c":0,"en":{"q":"In Wyoming, which papers does the law require you to carry when you drive?","o":["Your driver license, proof of insurance and vehicle registration","Only your driver license","Your birth certificate","Your car title and tax papers"],"h1":"An officer will ask for three things.","h2":"In Wyoming, the law requires you to carry your driver license, proof of insurance and the vehicle registration.","p":"Right. License, insurance and registration."},"es":{"q":"En Wyoming, ¿qué papeles exige la ley que lleve cuando maneja?","o":["Su licencia de manejar, prueba de seguro y registro del vehículo","Solo su licencia de manejar","Su acta de nacimiento","El título del carro y papeles de impuestos"],"h1":"Un policía le pedirá tres cosas.","h2":"En Wyoming, la ley exige llevar la licencia de manejar, la prueba de seguro y el registro del vehículo.","p":"Correcto. Licencia, seguro y registro."},"ref":{"doc":"WY","page":39}},{"id":"wy-138","scope":"WY","cat":"licensing","sign":null,"c":3,"en":{"q":"In Wyoming, an officer asks for proof of insurance and you cannot show it. How long do you have to produce it?","o":["24 hours","30 days","90 days","Seven days"],"h1":"It is about one week.","h2":"In Wyoming, a driver who cannot show proof of insurance has seven days to produce it.","p":"Right. You have seven days."},"es":{"q":"En Wyoming, un policía le pide prueba de seguro y usted no la puede mostrar. ¿Cuánto tiempo tiene para presentarla?","o":["24 horas","30 días","90 días","Siete días"],"h1":"Es más o menos una semana.","h2":"En Wyoming, un conductor que no puede mostrar la prueba de seguro tiene siete días para presentarla.","p":"Correcto. Tiene siete días."},"ref":{"doc":"WY","page":null}},{"id":"wy-139","scope":"WY","cat":"licensing","sign":null,"c":1,"en":{"q":"In Wyoming, what is the minimum liability insurance a car owner must carry?","o":["$10,000 / $20,000 / $5,000","$25,000 / $50,000 / $20,000","$50,000 / $100,000 / $50,000","$100,000 / $300,000 / $100,000"],"h1":"The first number is for one person hurt; the last is for property damage.","h2":"In Wyoming, the minimum liability coverage is $25,000 for one person hurt, $50,000 for two or more people, and $20,000 for property damage.","p":"Right. The minimum is 25/50/20."},"es":{"q":"En Wyoming, ¿cuál es el seguro de responsabilidad civil mínimo que debe tener el dueño de un carro?","o":["$10,000 / $20,000 / $5,000","$25,000 / $50,000 / $20,000","$50,000 / $100,000 / $50,000","$100,000 / $300,000 / $100,000"],"h1":"El primer número es para una persona herida; el último es para daños a la propiedad.","h2":"En Wyoming, la cobertura mínima es $25,000 por una persona herida, $50,000 por dos o más personas y $20,000 por daños a la propiedad.","p":"Correcto. El mínimo es 25/50/20."},"ref":{"doc":"WY","page":null}},{"id":"wy-140","scope":"WY","cat":"licensing","sign":null,"c":2,"en":{"q":"In Wyoming, what is the lowest fine for driving a car without the required liability insurance?","o":["$25","$100","$500","$5,000"],"h1":"The fine can go as high as $1,500.","h2":"In Wyoming, driving without required liability insurance carries a fine of $500 to $1,500, up to six months in jail, or both.","p":"Right. The fine starts at $500."},"es":{"q":"En Wyoming, ¿cuál es la multa más baja por manejar un carro sin el seguro de responsabilidad civil obligatorio?","o":["$25","$100","$500","$5,000"],"h1":"La multa puede llegar a $1,500.","h2":"En Wyoming, manejar sin el seguro obligatorio tiene una multa de $500 a $1,500, hasta seis meses de cárcel, o ambas.","p":"Correcto. La multa empieza en $500."},"ref":{"doc":"WY","page":null}},{"id":"wy-141","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, what is the speed limit on a paved road that is not an interstate, a state highway or in town, when no limit is posted?","o":["65 mph","55 mph","70 mph","45 mph"],"h1":"Unpaved roads get 55 mph; paved ones get 10 mph more.","h2":"In Wyoming, the limit is 65 mph on other paved roads where no other limit is set.","p":"Right. Other paved roads are 65 mph."},"es":{"q":"En Wyoming, ¿cuál es el límite de velocidad en una carretera pavimentada que no es interestatal, ni carretera estatal, ni está en la ciudad, si no hay letrero?","o":["65 mph","55 mph","70 mph","45 mph"],"h1":"Los caminos sin pavimentar tienen 55 mph; los pavimentados tienen 10 mph más.","h2":"En Wyoming, el límite es 65 mph en otros caminos pavimentados donde no hay otro límite.","p":"Correcto. Otros caminos pavimentados son 65 mph."},"ref":{"doc":"WY","page":null}},{"id":"wy-142","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, you get a speeding ticket on a road posted at 75 mph. Up to what speed will the ticket stay off your driving record?","o":["76 mph","78 mph","80 mph","90 mph"],"h1":"Where the limit is 65 to 75 mph, there is a single top speed for this rule.","h2":"In Wyoming, a speeding ticket of up to 80 mph where the posted limit is 65 to 75 mph is not put on your driving record.","p":"Right. Up to 80 mph stays off the record there."},"es":{"q":"En Wyoming, usted recibe una multa por exceso de velocidad en un camino con límite de 75 mph. ¿Hasta qué velocidad la multa no aparece en su historial de manejo?","o":["76 mph","78 mph","80 mph","90 mph"],"h1":"Donde el límite es de 65 a 75 mph, hay una sola velocidad máxima para esta regla.","h2":"En Wyoming, una multa de hasta 80 mph donde el límite es de 65 a 75 mph no se anota en su historial de manejo.","p":"Correcto. Hasta 80 mph no aparece en el historial allí."},"ref":{"doc":"WY","page":null}},{"id":"wy-143","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, the road is wet. How much should you slow down from your dry-road speed?","o":["Not at all","By half","To a crawl","By at least 5 to 10 mph"],"h1":"Wet roads need less slowing than snow or ice.","h2":"In Wyoming, on a wet road you should reduce your speed by at least 5 to 10 mph.","p":"Right. Slow down at least 5 to 10 mph."},"es":{"q":"En Wyoming, el camino está mojado. ¿Cuánto debe bajar su velocidad comparada con un camino seco?","o":["Nada","A la mitad","Casi hasta detenerse","Por lo menos de 5 a 10 mph"],"h1":"Un camino mojado requiere bajar menos que con nieve o hielo.","h2":"En Wyoming, en un camino mojado usted debe bajar la velocidad por lo menos de 5 a 10 mph.","p":"Correcto. Baje por lo menos de 5 a 10 mph."},"ref":{"doc":"WY","page":41}},{"id":"wy-144","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, the road is covered with ice. How fast should you drive?","o":["10 mph below the limit","At a crawl, and even slower if vehicles are ahead","Half the speed limit","The normal speed with your hazard lights on"],"h1":"Ice calls for the slowest speed of all road surfaces.","h2":"In Wyoming, on ice you should reduce your speed to a crawl, and slow even more if vehicles are ahead.","p":"Right. Slow to a crawl on ice."},"es":{"q":"En Wyoming, el camino está cubierto de hielo. ¿A qué velocidad debe manejar?","o":["10 mph menos que el límite","Muy despacio, casi a paso de tortuga, y más lento si hay vehículos adelante","La mitad del límite","A la velocidad normal con las luces de emergencia prendidas"],"h1":"El hielo pide la velocidad más baja de todas las superficies.","h2":"En Wyoming, en hielo usted debe bajar la velocidad casi hasta arrastrarse, y más aún si hay vehículos adelante.","p":"Correcto. En hielo, maneje muy despacio."},"ref":{"doc":"WY","page":41}},{"id":"wy-145","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"According to the Wyoming handbook, your headlights let you see clearly about how far ahead at night?","o":["50 feet","100 feet","250 feet","1,000 feet"],"h1":"Going faster than 55 mph means you cannot stop within this distance.","h2":"In Wyoming, the handbook says headlights let you see clearly about 250 feet, so faster than 55 mph on a dark road is driving blind.","p":"Right. About 250 feet."},"es":{"q":"Según el manual de Wyoming, de noche sus luces delanteras le dejan ver con claridad unos ¿cuántos pies adelante?","o":["50 pies","100 pies","250 pies","1,000 pies"],"h1":"A más de 55 mph no puede detenerse dentro de esta distancia.","h2":"En Wyoming, el manual dice que las luces delanteras dejan ver con claridad unos 250 pies, así que a más de 55 mph en un camino oscuro se maneja a ciegas.","p":"Correcto. Unos 250 pies."},"ref":{"doc":"WY","page":42}},{"id":"wy-146","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, heavy snow means you cannot see more than about 100 feet ahead. What does the handbook say to do?","o":["Pull off the road and wait until it clears","Drive at 25 mph","Follow the taillights of the car ahead closely","Turn on your high beams"],"h1":"At that distance, no speed is safe.","h2":"In Wyoming, when you cannot see more than about 100 feet ahead, you cannot drive safely at any speed, so pull off the road and wait.","p":"Right. Pull off and wait until it clears."},"es":{"q":"En Wyoming, una nevada fuerte no le deja ver más de unos 100 pies adelante. ¿Qué dice el manual que haga?","o":["Salir del camino y esperar a que mejore","Manejar a 25 mph","Seguir de cerca las luces traseras del carro de adelante","Prender las luces altas"],"h1":"A esa distancia, ninguna velocidad es segura.","h2":"En Wyoming, cuando no puede ver más de unos 100 pies adelante, no puede manejar seguro a ninguna velocidad, así que salga del camino y espere.","p":"Correcto. Salga del camino y espere a que mejore."},"ref":{"doc":"WY","page":42}},{"id":"wy-147","scope":"WY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wyoming, at an intersection with no signs or signals, you want to turn left. Cars are coming from straight ahead and from your right. Who do you yield to?","o":["No one, if you arrived first","Only the car on your right","Only the car coming straight at you","Both the car on your right and the oncoming car"],"h1":"A left turn crosses the path of more than one driver.","h2":"In Wyoming, at an uncontrolled intersection, a driver turning left yields to both the car on the right and the oncoming car.","p":"Right. Yield to both."},"es":{"q":"En Wyoming, en un cruce sin letreros ni semáforos, usted quiere girar a la izquierda. Vienen carros de frente y por su derecha. ¿A quién le cede el paso?","o":["A nadie, si usted llegó primero","Solo al carro de su derecha","Solo al carro que viene de frente","Al carro de su derecha y al que viene de frente"],"h1":"Un giro a la izquierda cruza el camino de más de un conductor.","h2":"En Wyoming, en un cruce sin control, quien gira a la izquierda cede el paso al carro de la derecha y al que viene de frente.","p":"Correcto. Ceda el paso a los dos."},"ref":{"doc":"WY","page":43}},{"id":"wy-148","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, you come to a place where others may cross your path. After looking ahead, which way should you check first?","o":["Right, then never left","Left, because vehicles from the left reach you first","Behind you","Only at the traffic signal"],"h1":"Think about which lane is closest to you.","h2":"In Wyoming, after checking ahead, look left first, since you will meet vehicles coming from the left first, then right, then both ways again.","p":"Right. Look left first."},"es":{"q":"En Wyoming, llega a un lugar donde otros pueden cruzar su camino. Después de mirar al frente, ¿hacia dónde debe mirar primero?","o":["A la derecha, y nunca a la izquierda","A la izquierda, porque los vehículos de la izquierda llegan primero a usted","Hacia atrás","Solo al semáforo"],"h1":"Piense en qué carril está más cerca de usted.","h2":"En Wyoming, después de mirar al frente, mire primero a la izquierda, porque encontrará primero a los vehículos que vienen de ese lado; luego a la derecha y otra vez a ambos lados.","p":"Correcto. Mire primero a la izquierda."},"ref":{"doc":"WY","page":43}},{"id":"wy-149","scope":"WY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wyoming, you are not sure who should go first at a four-way stop. What does the handbook say to do?","o":["Go first and honk","Wave everyone through","Yield to the driver on your right","Yield to the largest vehicle"],"h1":"It is the same rule as at intersections with no signs.","h2":"In Wyoming, at a four-way stop, if in doubt, yield to the driver on your right.","p":"Right. If in doubt, yield to the driver on your right."},"es":{"q":"En Wyoming, usted no sabe quién debe pasar primero en un alto de cuatro vías. ¿Qué dice el manual que haga?","o":["Pasar primero y tocar el claxon","Hacer señas a todos para que pasen","Ceder el paso al conductor de su derecha","Ceder el paso al vehículo más grande"],"h1":"Es la misma regla que en los cruces sin letreros.","h2":"En Wyoming, en un alto de cuatro vías, si tiene duda, ceda el paso al conductor de su derecha.","p":"Correcto. Si tiene duda, ceda el paso al de su derecha."},"ref":{"doc":"WY","page":47}},{"id":"wy-150","scope":"WY","cat":"right-of-way","sign":null,"c":0,"en":{"q":"In Wyoming, a driver is speeding when entering an intersection. What happens to any right of way that driver had?","o":["The driver gives it up","It stays the same","It doubles","It passes to the police"],"h1":"Breaking the speed law has a cost at intersections.","h2":"In Wyoming, a driver who enters an intersection while speeding forfeits any right of way they might have had.","p":"Right. The speeding driver loses the right of way."},"es":{"q":"En Wyoming, un conductor va con exceso de velocidad al entrar a un cruce. ¿Qué pasa con el derecho de paso que tenía?","o":["Lo pierde","Sigue igual","Se duplica","Pasa a la policía"],"h1":"Violar el límite de velocidad tiene un costo en los cruces.","h2":"En Wyoming, un conductor que entra a un cruce con exceso de velocidad pierde el derecho de paso que pudiera haber tenido.","p":"Correcto. El conductor que va rápido pierde el derecho de paso."},"ref":{"doc":"WY","page":47}},{"id":"wy-151","scope":"WY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wyoming, you have pulled over and stopped for an ambulance coming from behind. Why should you keep your foot on the brake?","o":["To charge the battery","To be ready to follow the ambulance","To turn off your engine faster","So the emergency driver knows you are stopped"],"h1":"Think about what the ambulance driver sees from behind you.","h2":"In Wyoming, keep your foot on the brake so the emergency vehicle driver knows you are stopped.","p":"Right. Your brake lights show you are stopped."},"es":{"q":"En Wyoming, usted se orilló y se detuvo por una ambulancia que viene por detrás. ¿Por qué debe mantener el pie en el freno?","o":["Para cargar la batería","Para estar listo para seguir a la ambulancia","Para apagar el motor más rápido","Para que el conductor de emergencia sepa que usted está detenido"],"h1":"Piense en lo que ve el conductor de la ambulancia detrás de usted.","h2":"En Wyoming, mantenga el pie en el freno para que el conductor del vehículo de emergencia sepa que usted está detenido.","p":"Correcto. Sus luces de freno muestran que está detenido."},"ref":{"doc":"WY","page":49}},{"id":"wy-152","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, a blind person with a white cane is waiting to cross the street in front of you. What must you do?","o":["Honk so they know you are there","Stop and let them cross","Drive around them slowly","Flash your lights"],"h1":"The law gives this person special protection.","h2":"In Wyoming, you must stop and yield to a blind pedestrian carrying a white cane or using a guide dog.","p":"Right. Stop and let them cross."},"es":{"q":"En Wyoming, una persona ciega con un bastón blanco espera para cruzar la calle frente a usted. ¿Qué debe hacer?","o":["Tocar el claxon para que sepa que usted está ahí","Detenerse y dejarla cruzar","Rodearla despacio","Hacer cambio de luces"],"h1":"La ley le da a esta persona una protección especial.","h2":"En Wyoming, usted debe detenerse y ceder el paso a un peatón ciego con bastón blanco o con perro guía.","p":"Correcto. Deténgase y déjela cruzar."},"ref":{"doc":"WY","page":49}},{"id":"wy-153","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Wyoming handbook, about how long does it take to move your foot from the gas pedal to the brake?","o":["About 3/4 of a second","About 3 seconds","About 1/10 of a second","About 5 seconds"],"h1":"It is less than one second.","h2":"In Wyoming, the handbook says it takes about 3/4 of a second to move your foot from the accelerator to the brake.","p":"Right. About 3/4 of a second."},"es":{"q":"Según el manual de Wyoming, ¿cuánto tiempo toma más o menos pasar el pie del acelerador al freno?","o":["Unos 3/4 de segundo","Unos 3 segundos","Más o menos 1/10 de segundo","Unos 5 segundos"],"h1":"Es menos de un segundo.","h2":"En Wyoming, el manual dice que toma unos 3/4 de segundo pasar el pie del acelerador al freno.","p":"Correcto. Unos 3/4 de segundo."},"ref":{"doc":"WY","page":49}},{"id":"wy-154","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"According to the Wyoming handbook, about how far does a passenger car going 55 mph need to stop?","o":["30 to 40 feet","60 to 70 feet","130 to 140 feet","400 feet"],"h1":"It is about half the length of a football field.","h2":"In Wyoming, the handbook says a passenger car at 55 mph can typically stop in about 130 to 140 feet.","p":"Right. About 130 to 140 feet."},"es":{"q":"Según el manual de Wyoming, ¿más o menos qué distancia necesita un carro de pasajeros que va a 55 mph para detenerse?","o":["De 30 a 40 pies","De 60 a 70 pies","De 130 a 140 pies","400 pies"],"h1":"Es como la mitad de un campo de fútbol americano.","h2":"En Wyoming, el manual dice que un carro de pasajeros a 55 mph normalmente se detiene en unos 130 a 140 pies.","p":"Correcto. Unos 130 a 140 pies."},"ref":{"doc":"WY","page":50}},{"id":"wy-155","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, you are leaving a parking lot to enter a street. What must you do first?","o":["Honk and pull out","Stop before entering the street","Slow down only if you see a car","Flash your hazard lights"],"h1":"The same rule applies to driveways and alleys.","h2":"In Wyoming, you must stop when entering a street from a driveway, alley, building or parking lot.","p":"Right. Stop before you enter the street."},"es":{"q":"En Wyoming, usted sale de un estacionamiento para entrar a una calle. ¿Qué debe hacer primero?","o":["Tocar el claxon y salir","Detenerse antes de entrar a la calle","Bajar la velocidad solo si ve un carro","Prender las luces de emergencia"],"h1":"La misma regla aplica a las entradas de casas y los callejones.","h2":"En Wyoming, usted debe detenerse al entrar a una calle desde una entrada de cochera, un callejón, un edificio o un estacionamiento.","p":"Correcto. Deténgase antes de entrar a la calle."},"ref":{"doc":"WY","page":50}},{"id":"wy-156","scope":"WY","cat":"right-of-way","sign":null,"c":3,"en":{"q":"In Wyoming, you are on a divided highway with a median. A school bus on the other side has stopped with flashing red lights. What must you do?","o":["Stop until the bus moves","Stop, then go after 10 seconds","Speed up to pass quickly","You do not have to stop, but watch for people"],"h1":"A physical barrier between you and the bus changes the rule.","h2":"In Wyoming, on a divided roadway only vehicles on the same side as the bus must stop, though you must still watch carefully for pedestrians.","p":"Right. You may go on with extreme caution."},"es":{"q":"En Wyoming, usted va por una carretera dividida con camellón. Un autobús escolar del otro lado se detuvo con luces rojas intermitentes. ¿Qué debe hacer?","o":["Detenerse hasta que el autobús avance","Detenerse y seguir después de 10 segundos","Acelerar para pasar rápido","No tiene que detenerse, pero debe estar atento a las personas"],"h1":"Una barrera física entre usted y el autobús cambia la regla.","h2":"En Wyoming, en un camino dividido solo deben detenerse los vehículos del mismo lado que el autobús, aunque usted debe tener mucho cuidado con los peatones.","p":"Correcto. Puede seguir con mucha precaución."},"ref":{"doc":"WY","page":51}},{"id":"wy-157","scope":"WY","cat":"right-of-way","sign":null,"c":2,"en":{"q":"In Wyoming, a school bus camera records a car passing the stopped bus, and the driver is unknown. How much is the registered owner fined?","o":["$25","$75","$195","$1,000"],"h1":"It is just under $200.","h2":"In Wyoming, when a school bus camera records a violation and the driver is unknown, the registered owner is fined $195.","p":"Right. The owner is fined $195."},"es":{"q":"En Wyoming, la cámara de un autobús escolar graba a un carro pasando al autobús detenido, y no se sabe quién manejaba. ¿Cuánto es la multa para el dueño registrado?","o":["$25","$75","$195","$1,000"],"h1":"Es un poco menos de $200.","h2":"En Wyoming, cuando la cámara de un autobús escolar graba una infracción y no se sabe quién manejaba, el dueño registrado recibe una multa de $195.","p":"Correcto. La multa para el dueño es $195."},"ref":{"doc":"WY","page":null}},{"id":"wy-158","scope":"WY","cat":"signals","sign":null,"c":0,"en":{"q":"In Wyoming, how far before an intersection must you start signaling a turn?","o":["At least 100 feet","At least 20 feet","At least 50 feet","At least 500 feet"],"h1":"It is about the length of six or seven cars.","h2":"In Wyoming, you must signal at least 100 feet before the intersection, and 4 to 5 seconds ahead is better at higher speeds.","p":"Right. Signal at least 100 feet before."},"es":{"q":"En Wyoming, ¿a qué distancia antes de un cruce debe empezar a señalar un giro?","o":["Por lo menos 100 pies","Por lo menos 20 pies","Por lo menos 50 pies","Por lo menos 500 pies"],"h1":"Es como el largo de seis o siete carros.","h2":"En Wyoming, usted debe señalar por lo menos 100 pies antes del cruce, y de 4 a 5 segundos antes es mejor a velocidades altas.","p":"Correcto. Señale por lo menos 100 pies antes."},"ref":{"doc":"WY","page":51}},{"id":"wy-159","scope":"WY","cat":"signals","sign":null,"c":2,"en":{"q":"In Wyoming, how do you give the hand signal for a right turn?","o":["Left arm straight out","Left arm bent down","Left arm bent up at the elbow","Right arm out the passenger window"],"h1":"All hand signals use the left arm.","h2":"In Wyoming, for a right turn you hold your left hand and arm straight up from the elbow.","p":"Right. Left arm bent up means a right turn."},"es":{"q":"En Wyoming, ¿cómo se hace la señal con la mano para girar a la derecha?","o":["Brazo izquierdo extendido hacia afuera","Brazo izquierdo doblado hacia abajo","Brazo izquierdo doblado hacia arriba desde el codo","Brazo derecho por la ventana del pasajero"],"h1":"Todas las señales con la mano usan el brazo izquierdo.","h2":"En Wyoming, para girar a la derecha usted levanta la mano y el brazo izquierdo hacia arriba desde el codo.","p":"Correcto. El brazo izquierdo doblado hacia arriba significa giro a la derecha."},"ref":{"doc":"WY","page":51}},{"id":"wy-160","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, what does the handbook say to do before you back up your car?","o":["Honk twice","Walk behind the vehicle to check","Use only your mirrors","Back up quickly"],"h1":"Small children and objects can hide behind a car.","h2":"In Wyoming, check behind your vehicle by walking behind it before you back up, then turn your head and body to look as you back slowly.","p":"Right. Walk behind the car to check first."},"es":{"q":"En Wyoming, ¿qué dice el manual que haga antes de echar el carro en reversa?","o":["Tocar el claxon dos veces","Caminar detrás del vehículo para revisar","Usar solo los espejos","Retroceder rápido"],"h1":"Niños pequeños y objetos pueden quedar escondidos detrás de un carro.","h2":"En Wyoming, revise detrás de su vehículo caminando por atrás antes de retroceder, y luego voltee la cabeza y el cuerpo para mirar mientras retrocede despacio.","p":"Correcto. Camine detrás del carro para revisar primero."},"ref":{"doc":"WY","page":54}},{"id":"wy-161","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, you are on a two-lane road behind a line of slow cars. How many vehicles may you try to pass at one time?","o":["As many as you can see","Three","Two","One"],"h1":"Passing more than this keeps you in the oncoming lane too long.","h2":"In Wyoming, do not try to pass more than one vehicle at a time on a two-lane road.","p":"Right. Pass only one vehicle at a time."},"es":{"q":"En Wyoming, usted va por un camino de dos carriles detrás de una fila de carros lentos. ¿Cuántos vehículos puede intentar rebasar a la vez?","o":["Todos los que pueda ver","Tres","Dos","Uno"],"h1":"Rebasar más que esto lo deja demasiado tiempo en el carril contrario.","h2":"En Wyoming, no intente rebasar más de un vehículo a la vez en un camino de dos carriles.","p":"Correcto. Rebase solo un vehículo a la vez."},"ref":{"doc":"WY","page":54}},{"id":"wy-162","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, you decide to pass a car on a two-lane road. How far behind it should you be when you start?","o":["At least two seconds behind","Right on its bumper","At least ten seconds behind","Beside it"],"h1":"Use the same count as your normal following distance.","h2":"In Wyoming, start your pass at least two seconds behind the vehicle ahead.","p":"Right. Start at least two seconds behind."},"es":{"q":"En Wyoming, usted decide rebasar a un carro en un camino de dos carriles. ¿A qué distancia detrás de él debe estar al empezar?","o":["Por lo menos dos segundos detrás","Pegado a su defensa","Por lo menos diez segundos detrás","A su lado"],"h1":"Use la misma cuenta que su distancia normal de seguimiento.","h2":"En Wyoming, empiece a rebasar por lo menos dos segundos detrás del vehículo de adelante.","p":"Correcto. Empiece por lo menos dos segundos detrás."},"ref":{"doc":"WY","page":54}},{"id":"wy-163","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, a car ahead is turning left and you want to pass it on the right. Which of these is not allowed?","o":["Checking your mirrors","Passing slowly on the pavement","Driving onto the shoulder or dirt to get around it","Waiting behind the car"],"h1":"Stay on the road surface.","h2":"In Wyoming, you may pass on the right of a car turning left, but it is not legal to leave the pavement to do it.","p":"Right. Do not leave the pavement to pass on the right."},"es":{"q":"En Wyoming, un carro adelante va a girar a la izquierda y usted quiere rebasarlo por la derecha. ¿Cuál de estas cosas no se permite?","o":["Revisar los espejos","Rebasar despacio sobre el pavimento","Meterse al acotamiento o a la tierra para rodearlo","Esperar detrás del carro"],"h1":"Quédese sobre la superficie del camino.","h2":"En Wyoming, puede rebasar por la derecha a un carro que gira a la izquierda, pero no es legal salirse del pavimento para hacerlo.","p":"Correcto. No salga del pavimento para rebasar por la derecha."},"ref":{"doc":"WY","page":55}},{"id":"wy-164","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, you pass using the oncoming lane on a two-lane road. You must be back in your lane before you come within how many feet of an oncoming vehicle?","o":["50 feet","200 feet","1,000 feet","20 feet"],"h1":"It is about 13 car lengths.","h2":"In Wyoming, a passing driver must return to the right lane before coming within 200 feet of an approaching vehicle.","p":"Right. Be back before you are within 200 feet."},"es":{"q":"En Wyoming, usted rebasa usando el carril contrario en un camino de dos carriles. ¿Antes de llegar a cuántos pies de un vehículo que viene de frente debe volver a su carril?","o":["50 pies","200 pies","1,000 pies","20 pies"],"h1":"Es como el largo de 13 carros.","h2":"En Wyoming, quien rebasa debe volver al carril derecho antes de llegar a 200 pies de un vehículo que viene de frente.","p":"Correcto. Vuelva antes de estar a 200 pies."},"ref":{"doc":"WY","page":null}},{"id":"wy-165","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, how close to an intersection or railroad crossing may you drive on the left side of the road to pass, unless signs allow it?","o":["Up to 10 feet away","Up to 25 feet away","Up to 50 feet away","Not within 100 feet"],"h1":"The distance is the same as the signaling distance before a turn.","h2":"In Wyoming, you may not drive on the left side of the road within 100 feet of an intersection or railroad crossing, unless traffic signs allow it.","p":"Right. Not within 100 feet."},"es":{"q":"En Wyoming, ¿qué tan cerca de un cruce o de un paso de tren puede manejar por el lado izquierdo del camino para rebasar, si no hay letreros que lo permitan?","o":["Hasta 10 pies","Hasta 25 pies","Hasta 50 pies","No a menos de 100 pies"],"h1":"La distancia es la misma que para señalar antes de un giro.","h2":"En Wyoming, no puede manejar por el lado izquierdo del camino a menos de 100 pies de un cruce o de un paso de tren, a menos que las señales lo permitan.","p":"Correcto. No a menos de 100 pies."},"ref":{"doc":"WY","page":null}},{"id":"wy-167","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"According to the Wyoming handbook, how long can some trucks with double trailers be?","o":["As much as 100 feet","About 20 feet","About 40 feet","As much as 300 feet"],"h1":"That is about five or six cars in a row.","h2":"In Wyoming, the handbook says some rigs with double trailers can be as much as 100 feet long, so passing them takes longer.","p":"Right. Up to about 100 feet."},"es":{"q":"Según el manual de Wyoming, ¿qué tan largos pueden ser algunos camiones con doble remolque?","o":["Hasta 100 pies","Unos 20 pies","Unos 40 pies","Hasta 300 pies"],"h1":"Son como cinco o seis carros en fila.","h2":"En Wyoming, el manual dice que algunos camiones con doble remolque pueden medir hasta 100 pies, así que rebasarlos toma más tiempo.","p":"Correcto. Hasta unos 100 pies."},"ref":{"doc":"WY","page":57}},{"id":"wy-169","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, what is a \"right-turn squeeze\"?","o":["A tight parking space","A car caught in the right-side blind spot of a truck that is turning right","A narrow bridge","A sharp curve to the right"],"h1":"Large trucks often swing wide before turning right.","h2":"In Wyoming, a right-turn squeeze happens when a car is in the blind spot on the right side of a heavy vehicle that is turning right.","p":"Right. It is a car trapped beside a truck turning right."},"es":{"q":"En Wyoming, ¿qué es un \"right-turn squeeze\" (apretón al girar a la derecha)?","o":["Un espacio de estacionamiento estrecho","Un carro atrapado en el punto ciego derecho de un camión que gira a la derecha","Un puente angosto","Una curva cerrada a la derecha"],"h1":"Los camiones grandes a menudo se abren antes de girar a la derecha.","h2":"En Wyoming, el right-turn squeeze ocurre cuando un carro está en el punto ciego del lado derecho de un vehículo pesado que gira a la derecha.","p":"Correcto. Es un carro atrapado junto a un camión que gira a la derecha."},"ref":{"doc":"WY","page":58}},{"id":"wy-170","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, a car is parked at the curb. May you park on the road side of it (double park)?","o":["Yes, for up to 15 minutes","Only if you drive a truck","No, parking on the road side of a parked car is illegal","Yes, at night"],"h1":"It would block a lane of traffic.","h2":"In Wyoming, it is not legal to park on the roadway side of any stopped or parked vehicle.","p":"Right. Double parking is illegal."},"es":{"q":"En Wyoming, hay un carro estacionado junto a la acera. ¿Puede estacionarse del lado de la calle junto a él (en doble fila)?","o":["Sí, hasta por 15 minutos","Solo si maneja un camión","No, estacionarse del lado de la calle de un carro estacionado es ilegal","Sí, de noche"],"h1":"Bloquearía un carril de tráfico.","h2":"En Wyoming, no es legal estacionarse del lado de la calle de un vehículo detenido o estacionado.","p":"Correcto. Estacionarse en doble fila es ilegal."},"ref":{"doc":"WY","page":58}},{"id":"wy-171","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, how close to a fire hydrant may you park?","o":["No closer than 15 feet","No closer than 5 feet","No closer than 50 feet","Right next to it is fine"],"h1":"Firefighters need room to connect their hoses.","h2":"In Wyoming, it is not legal to park within 15 feet of a fire hydrant.","p":"Right. Stay at least 15 feet away."},"es":{"q":"En Wyoming, ¿qué tan cerca de un hidrante puede estacionarse?","o":["No a menos de 15 pies","No a menos de 5 pies","No a menos de 50 pies","Justo al lado está bien"],"h1":"Los bomberos necesitan espacio para conectar sus mangueras.","h2":"En Wyoming, no es legal estacionarse a menos de 15 pies de un hidrante.","p":"Correcto. Quédese por lo menos a 15 pies."},"ref":{"doc":"WY","page":59}},{"id":"wy-172","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, how close to a crosswalk at an intersection may you park?","o":["5 feet","10 feet","15 feet","No closer than 20 feet"],"h1":"It is a bit more than the distance from a fire hydrant.","h2":"In Wyoming, you may not park within 20 feet of a crosswalk at an intersection.","p":"Right. Stay at least 20 feet from the crosswalk."},"es":{"q":"En Wyoming, ¿qué tan cerca de un cruce peatonal en una intersección puede estacionarse?","o":["5 pies","10 pies","15 pies","No a menos de 20 pies"],"h1":"Es un poco más que la distancia de un hidrante.","h2":"En Wyoming, no puede estacionarse a menos de 20 pies de un cruce peatonal en una intersección.","p":"Correcto. Quédese por lo menos a 20 pies del cruce peatonal."},"ref":{"doc":"WY","page":null}},{"id":"wy-173","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, how close to the nearest rail of a railroad crossing may you park?","o":["10 feet","No closer than 50 feet","20 feet","100 feet"],"h1":"It is farther than the distance from a crosswalk.","h2":"In Wyoming, you may not park within 50 feet of the nearest rail of a railroad crossing.","p":"Right. Stay at least 50 feet from the tracks."},"es":{"q":"En Wyoming, ¿qué tan cerca del riel más cercano de un paso de tren puede estacionarse?","o":["10 pies","No a menos de 50 pies","20 pies","100 pies"],"h1":"Es más lejos que la distancia de un cruce peatonal.","h2":"En Wyoming, no puede estacionarse a menos de 50 pies del riel más cercano de un paso de tren.","p":"Correcto. Quédese por lo menos a 50 pies de las vías."},"ref":{"doc":"WY","page":null}},{"id":"wy-174","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, how close to a stop sign at the side of the road may you park?","o":["5 feet","10 feet","No closer than 20 feet","50 feet"],"h1":"The rule also covers yield signs and traffic signals.","h2":"In Wyoming, you may not park within 20 feet before a stop sign, yield sign, flashing signal or traffic signal at the side of the road.","p":"Right. Stay at least 20 feet back."},"es":{"q":"En Wyoming, ¿qué tan cerca de un letrero de alto al lado del camino puede estacionarse?","o":["5 pies","10 pies","No a menos de 20 pies","50 pies"],"h1":"La regla también incluye letreros de ceda el paso y semáforos.","h2":"En Wyoming, no puede estacionarse a menos de 20 pies antes de un letrero de alto, de ceda el paso, una luz intermitente o un semáforo al lado del camino.","p":"Correcto. Quédese por lo menos a 20 pies."},"ref":{"doc":"WY","page":null}},{"id":"wy-175","scope":"WY","cat":"speed-lanes","sign":null,"c":0,"en":{"q":"In Wyoming, you park facing uphill next to a curb. Which way should you turn your front wheels?","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"h1":"If the car rolls back, the back of the front tire should catch the curb.","h2":"In Wyoming, when parking uphill with a curb, set the parking brake and turn your wheels away from the curb.","p":"Right. Uphill with a curb, turn away from the curb."},"es":{"q":"En Wyoming, usted se estaciona en subida junto a una acera. ¿Hacia dónde debe girar las llantas delanteras?","o":["Hacia afuera de la acera","Hacia la acera","Derechas","No importa"],"h1":"Si el carro se va para atrás, la parte trasera de la llanta debe detenerse en la acera.","h2":"En Wyoming, al estacionarse en subida con acera, ponga el freno de mano y gire las llantas hacia afuera de la acera.","p":"Correcto. En subida con acera, gire hacia afuera."},"ref":{"doc":"WY","page":59}},{"id":"wy-176","scope":"WY","cat":"speed-lanes","sign":null,"c":3,"en":{"q":"In Wyoming, you realize you are going the wrong way on an Interstate ramp. What should you do?","o":["Keep going to the next exit","Back up quickly to the start of the ramp","Make a fast U-turn right away","Pull onto the shoulder, stop, and turn around only when no traffic is coming"],"h1":"Get out of the way first, then wait for a safe moment.","h2":"In Wyoming, if you are going the wrong way on a ramp, pull onto the shoulder, stop, and turn around only when there is no oncoming traffic.","p":"Right. Pull onto the shoulder, stop, and turn when it is clear."},"es":{"q":"En Wyoming, usted se da cuenta de que va en sentido contrario en una rampa de la autopista interestatal. ¿Qué debe hacer?","o":["Seguir hasta la siguiente salida","Retroceder rápido al inicio de la rampa","Dar una vuelta en U rápida de inmediato","Meterse al acotamiento, detenerse y dar la vuelta solo cuando no venga tráfico"],"h1":"Primero quítese del camino, luego espere un momento seguro.","h2":"En Wyoming, si va en sentido contrario en una rampa, métase al acotamiento, deténgase y dé la vuelta solo cuando no venga tráfico de frente.","p":"Correcto. Acotamiento, alto, y dé la vuelta cuando esté despejado."},"ref":{"doc":"WY","page":60}},{"id":"wy-177","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, your car breaks down on the Interstate. What does the handbook say not to do?","o":["Walk for help","Turn on your four-way flashers","Raise the hood","Get out on the side away from traffic"],"h1":"Walking beside fast traffic is very dangerous.","h2":"In Wyoming, if your vehicle breaks down on the Interstate, do not walk for help; use your flashers and signal for help with a raised hood or a white cloth.","p":"Right. Do not walk for help on the Interstate."},"es":{"q":"En Wyoming, su carro se descompone en la autopista interestatal. ¿Qué dice el manual que no haga?","o":["Caminar para buscar ayuda","Prender las luces de emergencia","Levantar el cofre","Bajarse por el lado contrario al tráfico"],"h1":"Caminar junto a tráfico rápido es muy peligroso.","h2":"En Wyoming, si su vehículo se descompone en la autopista interestatal, no camine para buscar ayuda; use las luces de emergencia y pida ayuda levantando el cofre o con un trapo blanco.","p":"Correcto. No camine para buscar ayuda en la interestatal."},"ref":{"doc":"WY","page":84}},{"id":"wy-178","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, a solid yellow line is on your side of the center line. When may you cross it?","o":["To pass a slow truck","To turn left into or out of an alley, private road or driveway","Never, for any reason","When the road is empty"],"h1":"The exception is about getting on or off the road, not passing.","h2":"In Wyoming, a solid yellow line means no passing or lane changing, unless you are turning left into or from an alley, private road or driveway.","p":"Right. Only to turn left into or out of a driveway or alley."},"es":{"q":"En Wyoming, hay una línea amarilla continua de su lado de la línea central. ¿Cuándo puede cruzarla?","o":["Para rebasar un camión lento","Para girar a la izquierda para entrar o salir de un callejón, camino privado o entrada de cochera","Nunca, por ninguna razón","Cuando el camino está vacío"],"h1":"La excepción es para entrar o salir del camino, no para rebasar.","h2":"En Wyoming, una línea amarilla continua significa no rebasar ni cambiar de carril, salvo para girar a la izquierda hacia o desde un callejón, camino privado o entrada de cochera.","p":"Correcto. Solo para girar a la izquierda hacia o desde una entrada o callejón."},"ref":{"doc":"WY","page":63}},{"id":"wy-179","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, you hit a parked car and cannot find the owner. You leave a note with your information. What else must you do?","o":["Nothing else","Wait there for 24 hours","Contact the nearest law enforcement agency","Call the owner's insurance company"],"h1":"Someone official must also be told.","h2":"In Wyoming, after leaving a note on an unattended vehicle you damaged, you must also contact the nearest law enforcement agency.","p":"Right. Leave a note and tell law enforcement."},"es":{"q":"En Wyoming, usted choca un carro estacionado y no encuentra al dueño. Deja una nota con sus datos. ¿Qué más debe hacer?","o":["Nada más","Esperar ahí 24 horas","Avisar a la agencia de policía más cercana","Llamar a la compañía de seguros del dueño"],"h1":"También hay que avisar a una autoridad.","h2":"En Wyoming, después de dejar una nota en un vehículo sin conductor que usted dañó, también debe avisar a la agencia de policía más cercana.","p":"Correcto. Deje una nota y avise a la policía."},"ref":{"doc":"WY","page":67}},{"id":"wy-180","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, a driver leaves the scene of a crash in which someone was hurt. What is the highest fine?","o":["$100","$500","$1,000","$5,000"],"h1":"The driver may also face up to a year in jail.","h2":"In Wyoming, a driver who fails to stop at a crash with injury or death can be fined up to $5,000, jailed up to one year, or both.","p":"Right. The fine can be up to $5,000."},"es":{"q":"En Wyoming, un conductor se va del lugar de un choque donde alguien resultó herido. ¿Cuál es la multa más alta?","o":["$100","$500","$1,000","$5,000"],"h1":"También puede recibir hasta un año de cárcel.","h2":"En Wyoming, un conductor que no se detiene en un choque con heridos o muertos puede recibir una multa de hasta $5,000, hasta un año de cárcel, o ambas.","p":"Correcto. La multa puede ser de hasta $5,000."},"ref":{"doc":"WY","page":null}},{"id":"wy-181","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, who must wear a helmet when riding a motorcycle?","o":["Riders and passengers under 18","Everyone, at every age","Only riders over 65","No one; helmets are never required"],"h1":"The law protects minors.","h2":"In Wyoming, motorcycle riders and passengers under 18 must wear a helmet.","p":"Right. Riders and passengers under 18 must wear a helmet."},"es":{"q":"En Wyoming, ¿quién debe usar casco al ir en motocicleta?","o":["Conductores y pasajeros menores de 18 años","Todos, a cualquier edad","Solo los conductores mayores de 65","Nadie; nunca se exige casco"],"h1":"La ley protege a los menores de edad.","h2":"En Wyoming, los conductores y pasajeros de motocicleta menores de 18 años deben usar casco.","p":"Correcto. Los menores de 18 deben usar casco."},"ref":{"doc":"WY","page":null}},{"id":"wy-182","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, when must a motorcycle's headlight be on?","o":["Only at night","Only in rain or fog","Only on interstates","At all times, even in daylight"],"h1":"It helps other drivers see the motorcycle.","h2":"In Wyoming, a motorcycle must have its headlight on at all times, including daylight hours.","p":"Right. The headlight is always on."},"es":{"q":"En Wyoming, ¿cuándo debe tener la luz delantera prendida una motocicleta?","o":["Solo de noche","Solo con lluvia o niebla","Solo en autopistas interestatales","Siempre, aun de día"],"h1":"Ayuda a que otros conductores vean la motocicleta.","h2":"En Wyoming, una motocicleta debe llevar la luz delantera prendida en todo momento, incluso de día.","p":"Correcto. La luz delantera siempre va prendida."},"ref":{"doc":"WY","page":null}},{"id":"wy-183","scope":"WY","cat":"right-of-way","sign":null,"c":1,"en":{"q":"In Wyoming, you are on the Interstate. A highway maintenance truck with flashing lights is moving slower than 20 mph on the shoulder. What must you do, if it is safe?","o":["Honk and keep going","Move over into the lane farthest from the truck","Stop behind the truck","Speed up to pass quickly"],"h1":"The move-over law also covers road crews, not just police.","h2":"In Wyoming, on a road with two or more lanes in your direction, you must merge into the lane farthest from a stopped or slow (under 20 mph) maintenance vehicle with lights on.","p":"Right. Move over to the farthest lane."},"es":{"q":"En Wyoming, usted va por la autopista interestatal. Un camión de mantenimiento con luces intermitentes avanza a menos de 20 mph por el acotamiento. ¿Qué debe hacer, si es seguro?","o":["Tocar el claxon y seguir","Cambiarse al carril más lejano del camión","Detenerse detrás del camión","Acelerar para pasar rápido"],"h1":"La ley de cambiarse de carril también protege a los trabajadores, no solo a la policía.","h2":"En Wyoming, en un camino con dos o más carriles en su dirección, debe cambiarse al carril más lejano de un vehículo de mantenimiento detenido o lento (menos de 20 mph) con luces prendidas.","p":"Correcto. Cámbiese al carril más lejano."},"ref":{"doc":"WY","page":71}},{"id":"wy-184","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, during which seasons are crashes with deer and other big game most common?","o":["Summer and winter","Only in winter","Fall and spring","Only in summer"],"h1":"These are the seasons when animals migrate.","h2":"In Wyoming, animal crashes are most common in the fall and spring, when animals move between summer and winter ranges.","p":"Right. Fall and spring."},"es":{"q":"En Wyoming, ¿en qué temporadas son más comunes los choques con venados y otros animales grandes?","o":["Verano e invierno","Solo en invierno","Otoño y primavera","Solo en verano"],"h1":"Son las temporadas en que los animales migran.","h2":"En Wyoming, los choques con animales son más comunes en otoño y primavera, cuando los animales se mueven entre sus zonas de verano y de invierno.","p":"Correcto. Otoño y primavera."},"ref":{"doc":"WY","page":72}},{"id":"wy-185","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, you see a deer near the road ahead. What does the handbook say to do?","o":["Slow down, tap your brakes to warn others, and sound your horn","Flash your headlights at the deer","Speed up to get past it","Swerve into the other lane"],"h1":"Bright flashing lights may make the animal freeze in place.","h2":"In Wyoming, when you see an animal near the road, reduce speed, tap your brakes to warn drivers behind, and sound your horn.","p":"Right. Slow, tap the brakes and honk."},"es":{"q":"En Wyoming, usted ve un venado cerca del camino adelante. ¿Qué dice el manual que haga?","o":["Bajar la velocidad, tocar el freno para avisar a otros y tocar el claxon","Hacerle cambio de luces al venado","Acelerar para pasarlo","Desviarse al otro carril"],"h1":"Las luces brillantes pueden hacer que el animal se quede paralizado.","h2":"En Wyoming, cuando ve un animal cerca del camino, baje la velocidad, toque el freno para avisar a los de atrás y toque el claxon.","p":"Correcto. Baje la velocidad, toque el freno y el claxon."},"ref":{"doc":"WY","page":73}},{"id":"wy-186","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, how far ahead does the handbook say defensive drivers scan?","o":["2 to 3 seconds","At least 10 to 15 seconds","1 minute","Only to the car in front"],"h1":"Count from when you spot an object until you reach it.","h2":"In Wyoming, defensive drivers scan at least 10 to 15 seconds ahead.","p":"Right. Scan at least 10 to 15 seconds ahead."},"es":{"q":"En Wyoming, ¿qué tan adelante dice el manual que miran los conductores defensivos?","o":["De 2 a 3 segundos","Por lo menos de 10 a 15 segundos","1 minuto","Solo hasta el carro de adelante"],"h1":"Cuente desde que ve un objeto hasta que llega a él.","h2":"En Wyoming, los conductores defensivos miran por lo menos de 10 a 15 segundos adelante.","p":"Correcto. Mire por lo menos de 10 a 15 segundos adelante."},"ref":{"doc":"WY","page":74}},{"id":"wy-187","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, how many seconds behind the vehicle ahead should a tractor-trailer driver stay in good conditions?","o":["Two seconds","Three seconds","Four seconds","At least six seconds"],"h1":"The rule is two seconds for every 20 feet of vehicle length.","h2":"In Wyoming, a car stays at least two seconds back, a bus at least four, and a tractor-trailer at least six seconds back.","p":"Right. A tractor-trailer stays at least six seconds back."},"es":{"q":"En Wyoming, ¿cuántos segundos detrás del vehículo de adelante debe ir un tractocamión en buenas condiciones?","o":["Dos segundos","Tres segundos","Cuatro segundos","Por lo menos seis segundos"],"h1":"La regla es dos segundos por cada 20 pies de largo del vehículo.","h2":"En Wyoming, un carro va por lo menos dos segundos atrás, un autobús por lo menos cuatro y un tractocamión por lo menos seis segundos atrás.","p":"Correcto. Un tractocamión va por lo menos seis segundos atrás."},"ref":{"doc":"WY","page":75}},{"id":"wy-188","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, oncoming cars are on your left and a child on a bike is on your right. You cannot separate them. What should you do?","o":["Stay exactly in the middle of your lane","Move closer to the right edge","Move closer to the center line to give the child more room","Speed up past both"],"h1":"Give the most room to the one most likely to move suddenly.","h2":"In Wyoming, when you must deal with two risks at once, give the most room to the worst danger; here, move toward the center line to give the child more space.","p":"Right. Give the child the most room."},"es":{"q":"En Wyoming, hay carros de frente a su izquierda y un niño en bicicleta a su derecha. No puede separarlos. ¿Qué debe hacer?","o":["Quedarse justo en el centro de su carril","Acercarse a la orilla derecha","Acercarse a la línea central para darle más espacio al niño","Acelerar para pasar a los dos"],"h1":"Dele más espacio al que tiene más probabilidad de moverse de repente.","h2":"En Wyoming, cuando debe enfrentar dos riesgos a la vez, dele más espacio al peligro mayor; aquí, acérquese a la línea central para darle más espacio al niño.","p":"Correcto. Dele más espacio al niño."},"ref":{"doc":"WY","page":77}},{"id":"wy-189","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, how far before meeting an oncoming vehicle should you dim your high beams?","o":["At least 500 feet","At least 100 feet","At least 50 feet","At least one mile"],"h1":"It is about four to five seconds before you meet.","h2":"In Wyoming, dim your high beams at least 500 feet before meeting an oncoming vehicle.","p":"Right. Dim at least 500 feet before."},"es":{"q":"En Wyoming, ¿a qué distancia antes de cruzarse con un vehículo que viene de frente debe bajar las luces altas?","o":["Por lo menos 500 pies","Por lo menos 100 pies","Por lo menos 50 pies","Por lo menos una milla"],"h1":"Son unos cuatro a cinco segundos antes de cruzarse.","h2":"En Wyoming, baje las luces altas por lo menos 500 pies antes de cruzarse con un vehículo que viene de frente.","p":"Correcto. Bájelas por lo menos 500 pies antes."},"ref":{"doc":"WY","page":78}},{"id":"wy-190","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, you are driving in fog. According to the handbook, the chance of a crash becomes extremely high when your speed differs from other traffic by more than how much?","o":["2 mph","5 mph","50 mph","15 mph"],"h1":"Driving much slower or faster than others is risky.","h2":"In Wyoming, the handbook says the chance of a crash is extremely high when your speed differs from other traffic by more than 15 mph.","p":"Right. More than 15 mph."},"es":{"q":"En Wyoming, usted maneja con niebla. Según el manual, la posibilidad de un choque es altísima cuando su velocidad es diferente a la del resto del tráfico por más de ¿cuánto?","o":["2 mph","5 mph","50 mph","15 mph"],"h1":"Manejar mucho más lento o más rápido que los demás es peligroso.","h2":"En Wyoming, el manual dice que la posibilidad de un choque es altísima cuando su velocidad es diferente a la del tráfico por más de 15 mph.","p":"Correcto. Más de 15 mph."},"ref":{"doc":"WY","page":78}},{"id":"wy-191","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, you are stranded in your car in a blizzard. Why should you keep a window open a little?","o":["To hear snowplows","Freezing wet snow can seal the car and keep out fresh air","To let heat out","So rescuers can open the door"],"h1":"Think about the air you breathe inside the car.","h2":"In Wyoming, keep a window open a bit when stranded, because freezing wet snow can completely seal out oxygen.","p":"Right. Wet snow can seal out fresh air."},"es":{"q":"En Wyoming, usted queda atrapado en su carro durante una ventisca. ¿Por qué debe dejar una ventana un poco abierta?","o":["Para oír las máquinas quitanieves","La nieve húmeda que se congela puede sellar el carro y no dejar entrar aire fresco","Para que salga el calor","Para que los rescatistas puedan abrir la puerta"],"h1":"Piense en el aire que respira dentro del carro.","h2":"En Wyoming, deje una ventana un poco abierta si queda atrapado, porque la nieve húmeda que se congela puede tapar por completo la entrada de oxígeno.","p":"Correcto. La nieve húmeda puede tapar el aire fresco."},"ref":{"doc":"WY","page":80}},{"id":"wy-192","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, you lose your bearings in a ground blizzard on an icy road. How can you find where you are on the road?","o":["Turn on your high beams","Speed up to get out of it","Follow the car ahead very closely","Roll down the window and look on the downwind side for the center stripe or road edge"],"h1":"Blowing snow is thinner on one side of the car.","h2":"In Wyoming, if you lose your bearings in a ground blizzard, roll down the window and look on the downwind side to find the center stripe or the edge of the road.","p":"Right. Look out the downwind side for a road line."},"es":{"q":"En Wyoming, usted pierde la orientación en una ventisca a ras de suelo en un camino con hielo. ¿Cómo puede saber dónde está en el camino?","o":["Prender las luces altas","Acelerar para salir de ella","Seguir muy de cerca al carro de adelante","Bajar la ventana y mirar del lado hacia donde va el viento para ver la raya central o la orilla"],"h1":"La nieve que sopla es menos espesa de un lado del carro.","h2":"En Wyoming, si pierde la orientación en una ventisca a ras de suelo, baje la ventana y mire del lado hacia donde sopla el viento para ver la raya central o la orilla del camino.","p":"Correcto. Mire por el lado hacia donde va el viento para ver una línea."},"ref":{"doc":"WY","page":46}},{"id":"wy-193","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, the vehicle ahead of you spins out on an icy hill. What does the handbook advise?","o":["Pass it on the shoulder","Honk and go around it","Stay in line and wait for a snowplow to clear the way","Turn around on the highway"],"h1":"Patience gets you through faster.","h2":"In Wyoming, if a vehicle ahead spins out on an icy hill, stay in line and wait for a snowplow to clear the way.","p":"Right. Stay in line and wait for the plow."},"es":{"q":"En Wyoming, el vehículo de adelante patina y da vueltas en una subida con hielo. ¿Qué aconseja el manual?","o":["Rebasarlo por el acotamiento","Tocar el claxon y rodearlo","Quedarse en la fila y esperar a que una máquina quitanieves limpie el camino","Dar la vuelta en la carretera"],"h1":"La paciencia lo hace pasar más rápido.","h2":"En Wyoming, si un vehículo adelante patina en una subida con hielo, quédese en la fila y espere a que una máquina quitanieves limpie el camino.","p":"Correcto. Quédese en la fila y espere la quitanieves."},"ref":{"doc":"WY","page":46}},{"id":"wy-194","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, a head-on crash seems about to happen and you must turn away. Which way does the handbook's rule of thumb say to turn?","o":["To the right","To the left","Do not turn; brake hard","Into the other car's lane"],"h1":"If the other driver follows the same rule, you may miss each other.","h2":"In Wyoming, the rule of thumb is to turn right to avoid a head-on crash, even running off the road if necessary.","p":"Right. Turn to the right."},"es":{"q":"En Wyoming, parece que va a ocurrir un choque de frente y usted debe desviarse. ¿Hacia dónde dice la regla general del manual que gire?","o":["A la derecha","A la izquierda","No gire; frene fuerte","Al carril del otro carro"],"h1":"Si el otro conductor sigue la misma regla, pueden evitarse.","h2":"En Wyoming, la regla general es girar a la derecha para evitar un choque de frente, aunque tenga que salirse del camino.","p":"Correcto. Gire a la derecha."},"ref":{"doc":"WY","page":81}},{"id":"wy-195","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, you see a disabled vehicle parked on the right shoulder. What should you do if possible?","o":["Honk as you pass","Move to the left lane","Stop right behind it","Speed up past it"],"h1":"The driver may open a door or pull out without seeing you.","h2":"In Wyoming, when you see a disabled vehicle on the shoulder, move to the left lane if possible.","p":"Right. Move to the left lane."},"es":{"q":"En Wyoming, usted ve un vehículo descompuesto en el acotamiento derecho. ¿Qué debe hacer si es posible?","o":["Tocar el claxon al pasar","Cambiarse al carril izquierdo","Detenerse justo detrás de él","Acelerar para pasarlo"],"h1":"El conductor puede abrir una puerta o salir sin verle.","h2":"En Wyoming, cuando ve un vehículo descompuesto en el acotamiento, cámbiese al carril izquierdo si es posible.","p":"Correcto. Cámbiese al carril izquierdo."},"ref":{"doc":"WY","page":84}},{"id":"wy-196","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, what is the highest fine for reading or sending a text message while driving?","o":["$10","$25","$750","$75"],"h1":"It is less than $100.","h2":"In Wyoming, texting while driving is a misdemeanor with a fine of up to $75.","p":"Right. The fine is up to $75."},"es":{"q":"En Wyoming, ¿cuál es la multa más alta por leer o enviar un mensaje de texto mientras maneja?","o":["$10","$25","$750","$75"],"h1":"Es menos de $100.","h2":"En Wyoming, enviar mensajes de texto mientras maneja es un delito menor con una multa de hasta $75.","p":"Correcto. La multa es de hasta $75."},"ref":{"doc":"WY","page":null}},{"id":"wy-197","scope":"WY","cat":"signals","sign":null,"c":0,"en":{"q":"In Wyoming, you are on a one-way street at a red light and want to turn left onto another one-way street. What may you do?","o":["Stop, yield, then turn left","Never turn on red","Turn left without stopping","Wait for a green arrow only"],"h1":"It works like a right turn on red.","h2":"In Wyoming, after stopping and yielding, you may turn left on red from a one-way street onto another one-way street.","p":"Right. Stop, yield, then turn left."},"es":{"q":"En Wyoming, usted está en una calle de un solo sentido con luz roja y quiere girar a la izquierda hacia otra calle de un solo sentido. ¿Qué puede hacer?","o":["Detenerse, ceder el paso y luego girar a la izquierda","Nunca girar con luz roja","Girar a la izquierda sin detenerse","Esperar solo una flecha verde"],"h1":"Funciona como un giro a la derecha con luz roja.","h2":"En Wyoming, después de detenerse y ceder el paso, puede girar a la izquierda con luz roja desde una calle de un solo sentido hacia otra de un solo sentido.","p":"Correcto. Deténgase, ceda el paso y gire a la izquierda."},"ref":{"doc":"WY","page":97}},{"id":"wy-198","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, how much light must pass through the tinted front side windows next to the driver?","o":["At least 5%","At least 15%","At least 28%","At least 70%"],"h1":"It is a little more than one quarter.","h2":"In Wyoming, the front side windows next to the driver must let at least 28% of light through the tint and glass together.","p":"Right. At least 28% of light."},"es":{"q":"En Wyoming, ¿cuánta luz debe pasar por las ventanas delanteras laterales polarizadas junto al conductor?","o":["Por lo menos 5%","Por lo menos 15%","Por lo menos 28%","Por lo menos 70%"],"h1":"Es un poco más de una cuarta parte.","h2":"En Wyoming, las ventanas laterales delanteras junto al conductor deben dejar pasar por lo menos el 28% de la luz entre la película y el vidrio.","p":"Correcto. Por lo menos 28% de la luz."},"ref":{"doc":"WY","page":null}},{"id":"wy-199","scope":"WY","cat":"speed-lanes","sign":null,"c":1,"en":{"q":"In Wyoming, you may not make a U-turn on a curve or near a hilltop where other drivers cannot see you within how many feet?","o":["100 feet","500 feet","50 feet","2,000 feet"],"h1":"It is the same distance as dimming your lights for oncoming cars.","h2":"In Wyoming, you may not turn around on a curve or near the crest of a hill where drivers from either direction cannot see you within 500 feet.","p":"Right. 500 feet."},"es":{"q":"En Wyoming, no puede dar una vuelta en U en una curva o cerca de la cima de una subida donde otros conductores no le vean dentro de ¿cuántos pies?","o":["100 pies","500 pies","50 pies","2,000 pies"],"h1":"Es la misma distancia que para bajar las luces ante carros de frente.","h2":"En Wyoming, no puede dar la vuelta en una curva o cerca de la cima de una subida donde los conductores de cualquier dirección no le vean dentro de 500 pies.","p":"Correcto. 500 pies."},"ref":{"doc":"WY","page":null}},{"id":"wy-200","scope":"WY","cat":"safe-driving","sign":null,"c":2,"en":{"q":"In Wyoming, a road sign says chains or snow tires are required, and you drive on without them. What is the highest fine if no road closure results?","o":["$25","$75","$250","$5,000"],"h1":"If your crash closes the highway, it can go up to $750.","h2":"In Wyoming, driving in violation of a chain or traction restriction can bring a fine of up to $250, or up to $750 if it causes a full road closure.","p":"Right. Up to $250."},"es":{"q":"En Wyoming, un letrero dice que se requieren cadenas o llantas para nieve y usted sigue sin ellas. ¿Cuál es la multa más alta si no se llega a cerrar el camino?","o":["$25","$75","$250","$5,000"],"h1":"Si su choque cierra la carretera, puede llegar a $750.","h2":"En Wyoming, no cumplir una restricción de cadenas o tracción puede traer una multa de hasta $250, o hasta $750 si causa el cierre total del camino.","p":"Correcto. Hasta $250."},"ref":{"doc":"WY","page":null}},{"id":"wy-201","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, how many motorcycles may ride side by side in the same lane?","o":["Only one","Two, if both riders agree","Three","As many as fit"],"h1":"It takes the consent of both riders.","h2":"In Wyoming, no more than two motorcycles may ride side by side in one lane, and only if both riders agree.","p":"Right. Two, with both riders' consent."},"es":{"q":"En Wyoming, ¿cuántas motocicletas pueden ir lado a lado en el mismo carril?","o":["Solo una","Dos, si ambos conductores están de acuerdo","Tres","Todas las que quepan"],"h1":"Se necesita el permiso de ambos conductores.","h2":"En Wyoming, no más de dos motocicletas pueden ir lado a lado en un carril, y solo si ambos conductores están de acuerdo.","p":"Correcto. Dos, con el acuerdo de ambos conductores."},"ref":{"doc":"WY","page":69}},{"id":"wy-202","scope":"WY","cat":"safe-driving","sign":null,"c":3,"en":{"q":"In Wyoming, what equipment must a bicycle have when it is ridden after dark?","o":["A horn and a mirror","A flag on a pole","Only a bell","A front light and rear reflectors"],"h1":"One item lights the way ahead; the other shines back at cars behind.","h2":"In Wyoming, a bicycle used after dark must have a front light and rear reflectors.","p":"Right. A front light and rear reflectors."},"es":{"q":"En Wyoming, ¿qué equipo debe tener una bicicleta cuando se usa de noche?","o":["Una bocina y un espejo","Una bandera en un poste","Solo un timbre","Una luz delantera y reflectores traseros"],"h1":"Una cosa ilumina hacia adelante; la otra refleja la luz de los carros de atrás.","h2":"En Wyoming, una bicicleta que se usa de noche debe tener una luz delantera y reflectores traseros.","p":"Correcto. Luz delantera y reflectores traseros."},"ref":{"doc":"WY","page":70}},{"id":"wy-203","scope":"WY","cat":"safe-driving","sign":null,"c":0,"en":{"q":"In Wyoming, it is getting dark and headlights are required. May you drive with only your parking lights on?","o":["No, driving with only parking lights is illegal then","Yes, in town","Yes, if you drive slowly","Yes, until full darkness"],"h1":"Parking lights are hard to see until your car is already close.","h2":"In Wyoming, it is not legal to drive with only parking lights when headlights are required.","p":"Right. Parking lights alone are not allowed."},"es":{"q":"En Wyoming, está oscureciendo y se requieren las luces delanteras. ¿Puede manejar solo con las luces de estacionamiento?","o":["No, manejar solo con luces de estacionamiento es ilegal en ese caso","Sí, en la ciudad","Sí, si maneja despacio","Sí, hasta que esté totalmente oscuro"],"h1":"Las luces de estacionamiento casi no se ven hasta que su carro ya está cerca.","h2":"En Wyoming, no es legal manejar solo con las luces de estacionamiento cuando se requieren las luces delanteras.","p":"Correcto. No se permite usar solo las luces de estacionamiento."},"ref":{"doc":"WY","page":77}},{"id":"wy-204","scope":"WY","cat":"speed-lanes","sign":null,"c":2,"en":{"q":"In Wyoming, a registered multipurpose vehicle (such as an ATV with plates) may be driven on streets. Where may it not be driven?","o":["On city streets","On county roads","On interstate highways","On gravel roads"],"h1":"It must follow slow-moving vehicle rules, so fast roads are off limits.","h2":"In Wyoming, a registered multipurpose vehicle may not be operated on interstate highways.","p":"Right. Not on interstates."},"es":{"q":"En Wyoming, un vehículo multipropósito registrado (como una cuatrimoto con placas) puede circular por las calles. ¿Por dónde no puede circular?","o":["Por calles de la ciudad","Por caminos del condado","Por autopistas interestatales","Por caminos de grava"],"h1":"Debe seguir las reglas de vehículos lentos, así que los caminos rápidos están prohibidos.","h2":"En Wyoming, un vehículo multipropósito registrado no puede circular por autopistas interestatales.","p":"Correcto. No por autopistas interestatales."},"ref":{"doc":"WY","page":93}},{"id":"wy-205","scope":"WY","cat":"safe-driving","sign":null,"c":1,"en":{"q":"In Wyoming, what is the minimum legal tread depth for car tires?","o":["1/32 inch","2/32 inch","6/32 inch","1/2 inch"],"h1":"Front tires on buses and trucks need 4/32; cars need half that.","h2":"In Wyoming, you may not drive a car on tires with less than 2/32 inch of tread.","p":"Right. At least 2/32 inch of tread."},"es":{"q":"En Wyoming, ¿cuál es la profundidad mínima legal del dibujo (banda de rodamiento) de las llantas de un carro?","o":["1/32 de pulgada","2/32 de pulgada","6/32 de pulgada","1/2 pulgada"],"h1":"Las llantas delanteras de autobuses y camiones necesitan 4/32; los carros, la mitad.","h2":"En Wyoming, no puede manejar un carro con llantas que tengan menos de 2/32 de pulgada de dibujo.","p":"Correcto. Por lo menos 2/32 de pulgada de dibujo."},"ref":{"doc":"WY","page":null}}];
